import java.io.*;
import java.util.*;

/**
 * Solution for the “PLUS” problem.
 * The program reads a grid of '.' and '*', finds every cell that can be the centre
 * of a plus sign consisting only of '*' cells, verifies that every '*' belongs to
 * at least one such plus sign and finally prints all valid plus signs.
 *
 * The implementation is deliberately split into small, well‑named methods and
 * uses meaningful variable names, immutable {@link Placement} objects and a
 * tiny, reusable {@link InputReader}.
 */
public class Main {

    /** Entry point – runs the solving routine on a separate thread. */
    public static void main(String[] args) throws Exception {
        new Thread(null, Main::solve, "Main", 1 << 26).start();
    }

    /** Core solving routine. */
    private void solve() throws Exception {
        InputReader reader = new InputReader(System.in);
        PrintWriter writer = new PrintWriter(System.out);

        int rows = reader.nextInt();
        int cols = reader.nextInt();

        char[][] grid = readGrid(reader, rows);

        // Directional lengths of consecutive '*' cells (at least 2 are needed)
        int[][] left  = computeLeft(grid);
        int[][] right = computeRight(grid);
        int[][] up    = computeUp(grid);
        int[][] down  = computeDown(grid);

        // All placements that satisfy the size constraint
        List<Placement> placements = computeAllValidPlacements(
                grid, left, right, up, down);

        if (placements.isEmpty()) {
            writer.println(-1);
        } else {
            writer.println(placements.size());
            for (Placement p : placements) {
                writer.println(p);
            }
        }

        writer.close();
    }

    /** Reads the whole grid from the input reader. */
    private static char[][] readGrid(InputReader reader, int n) {
        char[][] grid = new char[n][];
        for (int i = 0; i < n; i++) {
            String token = reader.next();          // next token = next word without spaces
            grid[i] = token.toCharArray();
        }
        return grid;
    }

    /** Length of continuous '*' to the left of each cell (exclusive of the cell itself). */
    private static int[][] computeLeft(char[][] grid) {
        int n = grid.length, m = grid[0].length;
        int[][] left = new int[n][m];
        for (int i = 0; i < n; i++) {
            int cnt = 0;
            for (int j = 0; j < m; j++) {
                if (grid[i][j] == '*') {
                    cnt++;
                    if (cnt >= 2) {
                        left[i][j] = cnt - 1;      // at least one neighbour on the left
                    }
                } else {
                    cnt = 0;
                }
            }
        }
        return left;
    }

    /** Length of continuous '*' to the right of each cell. */
    private static int[][] computeRight(char[][] grid) {
        int n = grid.length, m = grid[0].length;
        int[][] right = new int[n][m];
        for (int i = 0; i < n; i++) {
            int cnt = 0;
            for (int j = m - 1; j >= 0; j--) {
                if (grid[i][j] == '*') {
                    cnt++;
                    if (cnt >= 2) {
                        right[i][j] = cnt - 1;
                    }
                } else {
                    cnt = 0;
                }
            }
        }
        return right;
    }

    /** Length of continuous '*' upward from each cell. */
    private static int[][] computeUp(char[][] grid) {
        int n = grid.length, m = grid[0].length;
        int[][] up = new int[n][m];
        for (int j = 0; j < m; j++) {
            int cnt = 0;
            for (int i = 0; i < n; i++) {
                if (grid[i][j] == '*') {
                    cnt++;
                    if (cnt >= 2) {
                        up[i][j] = cnt - 1;
                    }
                } else {
                    cnt = 0;
                }
            }
        }
        return up;
    }

    /** Length of continuous '*' downward from each cell. */
    private static int[][] computeDown(char[][] grid) {
        int n = grid.length, m = grid[0].length;
        int[][] down = new int[n][m];
        for (int j = 0; j < m; j++) {
            int cnt = 0;
            for (int i = n - 1; i >= 0; i--) {
                if (grid[i][j] == '*') {
                    cnt++;
                    if (cnt >= 2) {
                        down[i][j] = cnt - 1;
                    }
                } else {
                    cnt = 0;
                }
            }
        }
        return down;
    }

    /**
     * Finds every cell that can be the centre of a plus sign whose arm length
     * equals the maximal possible size, and validates that all '*' cells are
     * covered by at least one such plus sign.
     */
    private static List<Placement> computeAllValidPlacements(char[][] grid,
                                                             int[][] left,
                                                             int[][] right,
                                                             int[][] up,
                                                             int[][] down) {
        int n = grid.length, m = grid[0].length;

        // List of discovered placements
        List<Placement> placements = new ArrayList<>();

        // Difference‑array helpers for row‑ and column‑wise coverage marking
        int[][] diffRow = new int[n][m + 1];
        int[][] diffCol = new int[n + 1][m];

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                // Maximal arm length that still has '*' on all four directions
                int poss = Math.min(
                        Math.min(left[i][j], right[i][j]),
                        Math.min(up[i][j], down[i][j])
                );
                if (poss > 0) {
                    placements.add(new Placement(i, j, poss));

                    // Mark the region covered by this plus sign (exclusive ends)
                    diffRow[i][j - poss]++;
                    if (j + poss + 1 < m) {
                        diffRow[i][j + poss + 1]--;
                    }
                    diffCol[i - poss][j]++;
                    if (i + poss + 1 < n) {
                        diffCol[i + poss + 1][j]--;
                    }
                }
            }
        }

        // Build prefix sums → actual coverage counter for each cell
        for (int i = 0; i < n; i++) {
            for (int j = 1; j < m; j++) {
                diffRow[i][j] += diffRow[i][j - 1];
            }
        }
        for (int j = 0; j < m; j++) {
            for (int i = 1; i < n; i++) {
                diffCol[i][j] += diffCol[i - 1][j];
            }
        }

        // Verify that every '*' cell lies inside at least one marked region
        boolean allCovered = true;
        for (int i = 0; i < n && allCovered; i++) {
            for (int j = 0; j < m; j++) {
                int covered = diffRow[i][j] + diffCol[i][j];
                if (grid[i][j] == '*' && covered == 0) {
                    allCovered = false;
                    break;
                }
            }
        }

        // If validation fails we must not output any placement
        return allCovered ? placements : Collections.emptyList();
    }

    /** Immutable holder for a plus sign (1‑based coordinates, arm size). */
    private static final class Placement {
        final int row;   // 1‑based
        final int col;   // 1‑based
        final int size;  // arm length

        Placement(int zeroBasedRow, int zeroBasedCol, int size) {
            this.row = zeroBasedRow + 1;
            this.col = zeroBasedCol + 1;
            this.size = size;
        }

        @Override
        public String toString() {
            return row + " " + col + " " + size;
        }
    }

    /** Very small, fast scanner that works with UTF‑8 input. */
    private static final class InputReader implements Closeable {
        private final InputStream stream;
        private final byte[] buffer = new byte[1 << 10];
        private int bufPos = 0, bufLen = 0;
        private final SpaceCharFilter filter;

        InputReader(InputStream stream) {
            this(stream, ch -> ch == ' ' || ch == '\n' || ch == '\r' || ch == '\t');
        }

        InputReader(InputStream stream, SpaceCharFilter filter) {
            this.stream = stream;
            this.filter = filter;
        }

        private int readChar() throws IOException {
            if (bufPos >= bufLen) {
                bufLen = stream.read(buffer);
                bufPos = 0;
                if (bufLen <= 0) return -1;
            }
            return buffer[bufPos++];
        }

        private int nextNonSpace() throws IOException {
            int c;
            do {
                c = readChar();
            } while (filter.isSpaceChar(c));
            return c;
        }

        /** Reads the next integer (supports negative numbers). */
        int nextInt() throws IOException {
            int sign = 1;
            int c = nextNonSpace();
            if (c == '-') {
                sign = -1;
                c = nextNonSpace();
            }
            int val = 0;
            do {
                val = val * 10 + (c - '0');
                c = nextNonSpace();
            } while (!filter.isSpaceChar(c));
            return sign * val;
        }

        /** Reads next token (a word without whitespace). */
        String next() throws IOException {
            int c = nextNonSpace();
            StringBuilder sb = new StringBuilder();
            do {
                sb.append((char) c);
                c = readChar();
            } while (!filter.isSpaceChar(c));
            return sb.toString();
        }

        @Override
        public void close() throws IOException {
            stream.close();
        }

        /** Filter defining which characters are considered whitespace. */
        interface SpaceCharFilter {
            boolean isSpaceChar(int ch);
        }
    }
}

import java.io.*;
import java.util.*;

public class E1_StarPainting_ver1 {

    // ------------------------------------------------------------------------
    // I/O utilities
    // ------------------------------------------------------------------------
    private static final PrintWriter out = new PrintWriter(new BufferedWriter(
            new OutputStreamWriter(System.out)));

    private static void println(Object o) {
        out.println(o);
    }

    private static void exit() {
        out.close();
        System.exit(0);
    }

    /** Simple scanner that mimics the original MyScanner implementation */
    private static final class MyScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        MyScanner() throws IOException {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    throw new UncheckedIOException(e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        String nextLine() {
            try {
                return br.readLine();
            } catch (IOException e) {
                throw new UncheckedIOException(e);
            }
        }
    }

    // ------------------------------------------------------------------------
    // Data structures
    // ------------------------------------------------------------------------
    /** Star centre (row, col) – 0‑based indices */
    private static final class StarPoint {
        final int row, col;
        StarPoint(int row, int col) { this.row = row; this.col = col; }
        @Override public String toString() { return row + " " + col; }
    }

    /** Horizontal or vertical segment of '*' characters */
    private static final class Segment {
        final int fixed;   // row for vertical segment, col for horizontal segment
        final int start;   // inclusive start index on the varying axis
        final int end;     // inclusive end index on the varying axis
        Segment(int fixed, int start, int end) {
            this.fixed = fixed;
            this.start = start;
            this.end = end;
        }
        @Override public String toString() {
            return fixed + "," + start + " " + fixed + "," + end;
        }
    }

    // ------------------------------------------------------------------------
    // Core algorithm
    // ------------------------------------------------------------------------
    public static void main(String[] args) throws IOException {
        MyScanner sc = new MyScanner();
        int n = sc.nextInt();
        int m = sc.nextInt();

        char[][] grid = new char[n][m];
        for (int i = 0; i < n; i++) {
            String line = sc.nextLine();
            for (int j = 0; j < m; j++) {
                grid[i][j] = line.charAt(j);
            }
        }

        // 1. Find all potential star centres
        List<StarPoint> centres = findStarPoints(grid);

        // 2. Extract all horizontal and vertical segments
        Map<Integer, List<Segment>> horSeg = extractHorizontalSegments(grid);
        Map<Integer, List<Segment>> verSeg = extractVerticalSegments(grid);

        // 3. Build stars with maximal size and clear them from the grid
        List<Star> stars = buildStars(grid, centres, horSeg, verSeg);

        // 4. Validation – if any '*' remains the input was invalid
        if (!gridIsFullyCovered(grid)) {
            println(-1);
            exit();
        }

        // 5. Output
        println(stars.size());
        stars.forEach(out::println);
        exit();
    }

    // ------------------------------------------------------------------------
    // Step 1 – locate potential star centres
    // ------------------------------------------------------------------------
    private static List<StarPoint> findStarPoints(char[][] g) {
        List<StarPoint> list = new ArrayList<>();
        int rows = g.length, cols = g[0].length;

        for (int r = 1; r < rows - 1; r++) {
            for (int c = 1; c < cols - 1; c++) {
                if (g[r][c] != '*') continue;
                if (g[r][c - 1] == '*' && g[r][c + 1] == '*' &&
                    g[r - 1][c] == '*' && g[r + 1][c] == '*') {
                    list.add(new StarPoint(r, c));
                }
            }
        }
        return list;
    }

    // ------------------------------------------------------------------------
    // Step 2 – extract line segments
    // ------------------------------------------------------------------------
    private static Map<Integer, List<Segment>> extractHorizontalSegments(char[][] g) {
        Map<Integer, List<Segment>> map = new HashMap<>();
        int rows = g.length, cols = g[0].length;

        for (int r = 0; r < rows; r++) {
            int c = 0;
            while (c < cols) {
                if (g[r][c] != '*') { c++; continue; }
                int start = c;
                while (c < cols && g[r][c] == '*') c++;
                int end = c - 1;
                if (end - start >= 2) {
                    map.computeIfAbsent(r, k -> new ArrayList<>())
                            .add(new Segment(r, start, end));
                }
            }
        }
        return map;
    }

    private static Map<Integer, List<Segment>> extractVerticalSegments(char[][] g) {
        Map<Integer, List<Segment>> map = new HashMap<>();
        int rows = g.length, cols = g[0].length;

        for (int c = 0; c < cols; c++) {
            int r = 0;
            while (r < rows) {
                if (g[r][c] != '*') { r++; continue; }
                int start = r;
                while (r < rows && g[r][c] == '*') r++;
                int end = r - 1;
                if (end - start >= 2) {
                    map.computeIfAbsent(c, k -> new ArrayList<>())
                            .add(new Segment(c, start, end));
                }
            }
        }
        return map;
    }

    // ------------------------------------------------------------------------
    // Step 3 – construct stars with maximal size
    // ------------------------------------------------------------------------
    /** Orientation of a segment (horizontal vs vertical) */
    private enum SegmentOrientation { HORIZONTAL, VERTICAL }

    /** Builds Star objects from detected centres and extracted segments */
    private static List<Star> buildStars(char[][] g,
                                         List<StarPoint> centres,
                                         Map<Integer, List<Segment>> horSeg,
                                         Map<Integer, List<Segment>> verSeg) {
        List<Star> stars = new ArrayList<>();

        for (StarPoint sc : centres) {
            int r = sc.row;
            int c = sc.col;

            Segment hSeg = findContainingSegment(r, c,
                    horSeg.get(r), SegmentOrientation.HORIZONTAL);
            Segment vSeg = findContainingSegment(c, r,
                    verSeg.get(c), SegmentOrientation.VERTICAL);

            if (hSeg == null || vSeg == null) continue; // safety guard

            int hLen = Math.min(c - hSeg.start, hSeg.end - c);
            int vLen = Math.min(r - vSeg.start, vSeg.end - r);
            int size = Math.min(hLen, vLen);

            stars.add(new Star(r + 1, c + 1, size)); // 1‑based output coordinates

            // Erase the drawn star from the grid
            clearStar(g, r, c, size);
        }
        return stars;
    }

    /** Returns the segment that contains the given coordinate on the varying axis */
    private static Segment findContainingSegment(int fixed, int pos,
                                                   List<Segment> list,
                                                   SegmentOrientation orient) {
        if (list == null) return null;
        for (Segment s : list) {
            if (s.fixed != fixed) continue;
            if (orient == SegmentOrientation.HORIZONTAL && s.start < pos && pos < s.end) return s;
            if (orient == SegmentOrientation.VERTICAL && s.start < pos && pos < s.end) return s;
        }
        return null;
    }

    /** Removes a star of given size from the grid (marks its lines with '.') */
    private static void clearStar(char[][] g, int centerR, int centerC, int size) {
        for (int i = centerR - size; i <= centerR + size; i++) {
            g[i][centerC] = '.';
        }
        for (int j = centerC - size; j <= centerC + size; j++) {
            g[centerR][j] = '.';
        }
    }

    /** Checks that no '*' remains after all stars have been drawn */
    private static boolean gridIsFullyCovered(char[][] g) {
        for (char[] row : g) {
            for (char cell : row) {
                if (cell == '*') return false;
            }
        }
        return true;
    }

    /** Final star representation – coordinates are 1‑based */
    private static final class Star {
        final int row, col, size;
        Star(int row, int col, int size) { this.row = row; this.col = col; this.size = size; }
        @Override public String toString() { return row + " " + col + " " + size; }
    }
}

/*
 *  StarProcessor
 *
 *  Reads a rectangular grid of characters ('.' or '*') and looks for
 *  cells that contain a '*' and have at least one neighbouring '*' in each
 *  of the four orthogonal directions (up, down, left, right).  For every
 *  such cell the length of the shortest continuous '*' line in the four
 *  directions is taken as its “weight”.  All cells that belong to one of
 *  these weight‑lines are marked; after the whole grid is scanned we verify
 *  that every '*' was marked.  If any '*' remains unmarked the program
 *  prints -1 and exits.  Otherwise it prints the number of found centre
 *  cells followed by one line per centre:
 *
 *          row col weight
 *
 *  The implementation is deliberately kept simple and type‑safe, with
 *  small helper methods that isolate the core algorithmic steps.
 *
 *  Author:  (your name)
 *  Created: 2025‑09‑23
 */
import java.io.*;
import java.util.*;

public final class StarProcessor {

    /* ----------  I/O helpers  ------------------------------------------------ */

    /** Fast scanner based on a reusable byte buffer. */
    private static final class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[16_384];
        private int ptr = 0, len = 0;

        FastScanner(InputStream in) { this.in = in; }

        /** Skip whitespace characters. */
        private int skipSpaces() throws IOException {
            int c;
            while ((c = read()) <= ' ') if (c == -1) throw new EOFException();
            return c;
        }

        /** Read a single signed 32‑bit int. */
        int nextInt() throws IOException {
            int sign = 1, c = skipSpaces();
            if (c == '-') {
                sign = -1;
                c = read();
            }
            long value = 0;
            while (c > ' ') {
                if (c < '0' || c > '9') throw new InputMismatchException();
                value = value * 10 + (c - '0');
                c = read();
            }
            return (int) (value * sign);
        }

        /** Read the next non‑whitespace token as a String. */
        String next() throws IOException {
            int c = skipSpaces();
            StringBuilder sb = new StringBuilder();
            do {
                sb.append((char) c);
                c = read();
            } while (c > ' ');
            return sb.toString();
        }

        /** Read a whole line (including possible trailing spaces). */
        String nextLine() throws IOException {
            StringBuilder sb = new StringBuilder();
            int c = skipSpaces();
            while (!isEndOfLine(c)) {
                sb.append((char) c);
                c = read();
            }
            return sb.toString();
        }

        /** Check whether a character marks the end of a line. */
        private boolean isEndOfLine(int c) { return c == '\n' || c == '\r' || c == -1; }

        /** Pull the next byte from the underlying stream, filling the buffer
         *  when necessary. */
        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }
    }

    /* ----------  Core processing ------------------------------------------------ */

    /** Directions used for the four orthogonal scans. */
    private static final int[] DR = { -1, 1, 0, 0 };
    private static final int[] DC = { 0, 0, -1, 1 };

    /** Holds the processed data. */
    private final char[][] grid;      // input grid  (1‑based indexing)
    private final boolean[][] marked; // cells that belong to a weight‑line
    private final List<String> report; // output lines to be printed

    /** Constructs a processor for the given grid. */
    private StarProcessor(int rows, int cols) {
        this.grid = new char[rows + 4][cols + 4]; // add padding to avoid bounds checks
        this.marked = new boolean[rows + 4][cols + 4];
        this.report = new ArrayList<>();
    }

    /** Parses the whole input and returns the final output as a single string. */
    static String solve(InputStream source) throws IOException {
        FastScanner fs = new FastScanner(source);
        int n = fs.nextInt();          // rows
        int m = fs.nextInt();          // columns
        char[][] rawGrid = new char[n + 4][m + 4];
        boolean[][] mark = new boolean[n + 4][m + 4];

        // ---- read the grid into a 1‑based area -------------------------------
        for (int r = 1; r <= n; ++r) {
            String line = fs.nextLine().trim();
            for (int c = 1; c <= m; ++c) {
                rawGrid[r][c] = line.charAt(c - 1);
            }
        }

        StarProcessor processor = new StarProcessor(n, m);
        processor.grid = rawGrid;
        processor.marked = mark;

        // ---- scan every inner cell -------------------------------------------------
        for (int r = 2; r <= n; ++r) {
            for (int c = 2; c <= m; ++c) {
                if (processor.grid[r][c] != '*') continue;

                int[] lengths = new int[4]; // up, down, left, right
                for (int dir = 0; dir < 4; ++dir) {
                    lengths[dir] = countInDirection(r, c, DR[dir], DC[dir]);
                }

                int min = Arrays.stream(lengths).min().orElse(0);
                if (min == 0) continue; // not a valid centre

                // record the centre and all cells of the chosen lines
                processor.report.add(String.format("%d %d %d", r, c, min));
                processor.markLines(r, c, min, lengths);
            }
        }

        // ---- verify that every '*' was marked ------------------------------------
        for (int r = 1; r <= n; ++r) {
            for (int c = 1; c <= m; ++c) {
                if (processor.grid[r][c] == '*' && !processor.marked[r][c]) {
                    return "-1";
                }
            }
        }

        // ---- build final output ---------------------------------------------------
        StringBuilder sb = new StringBuilder();
        sb.append(processor.report.size()).append('\n');
        sb.append(String.join("\n", processor.report)).append('\n');
        return sb.toString();
    }

    /** Counts consecutive '*' cells starting from (row,col) moving in (dr,dc)
     *  until a non‑'*' or the padded border is hit. */
    private int countInDirection(int row, int col, int dr, int dc) {
        int cnt = 0;
        int r = row + dr;
        int c = col + dc;
        while (grid[r][c] == '*') {
            cnt++;
            r += dr;
            c += dc;
        }
        return cnt;
    }

    /** Marks all cells belonging to the four lines of length {@code min}
     *  that radiate from the centre (row,col). */
    private void markLines(int row, int col, int min, int[] lengths) {
        // enumerate directions in a deterministic order: up, down, left, right
        int[] dr = { -1, 1, 0, 0 };
        int[] dc = { 0, 0, -1, 1 };

        for (int dir = 0; dir < 4; ++dir) {
            int steps = lengths[dir];
            if (steps != min) continue; // only the shortest direction(s) are recorded
            int r = row + dr[dir];
            int c = col + dc[dir];
            for (int i = 0; i < min; ++i) {
                marked[r][c] = true;
                r += dr[dir];
                c += dc[dir];
            }
        }
    }

    /* ----------  Entry point --------------------------------------------------- */

    public static void main(String[] args) throws IOException {
        // Using System.out as the destination PrintWriter matches the original program’s behaviour.
        PrintWriter out = new PrintWriter(System.out, true);
        String result = solve(System.in);
        out.print(result);
        out.flush();
    }
}

// ---------------------------------------------------------------
//  Tank – Refactored version (maintainable, clear and idiomatic)
// ---------------------------------------------------------------
import java.io.*;
import java.util.*;

public class Tank {

    /** Entry point */
    public static void main(String[] args) throws IOException {
        // The scanner is closed automatically thanks to try‑with‑resources
        try (FastScanner scanner = new FastScanner(new InputStreamReader(System.in))) {
            new Tank().solve(scanner);
        }
    }

    /** Holds the whole processing logic – keeps `main` tiny */
    private void solve(FastScanner fs) {
        int rows = fs.nextInt();
        int cols = fs.nextInt();

        char[][] grid = readGrid(fs, rows);
        GridProcessor processor = new GridProcessor(grid);

        List<Placement> placements = processor.findAllPlacements();
        if (!processor.areAllStarsCovered()) {
            System.out.println(-1);
            return;
        }

        // Output
        System.out.println(placements.size());
        placements.forEach(p -> System.out.printf("%d %d %d%n", p.row + 1, p.col + 1, p.size));
    }

    /** Reads exactly `rows` lines from the scanner and returns a char matrix */
    private static char[][] readGrid(FastScanner fs, int rows) {
        char[][] grid = new char[rows][];
        for (int i = 0; i < rows; i++) {
            grid[i] = fs.next().toCharArray();
        }
        return grid;
    }

    /** -----------------------------------------------------------------
     *  Helper classes that encapsulate data and behaviour.
     *  -------------------------------------------------------------- */
    /** A cell that contains a '*' and the length of its smallest arm */
    private static final class Placement {
        final int row;
        final int col;
        final int size; // length of the shortest arm (≥1)

        Placement(int row, int col, int size) {
            this.row = row;
            this.col = col;
            this.size = size;
        }
    }

    /** Encapsulates the grid and all operations that need to be performed on it */
    private static final class GridProcessor {
        private final char[][] cells;
        private final boolean[][] visited;

        GridProcessor(char[][] cells) {
            this.cells = cells;
            this.visited = new boolean[cells.length][cells[0].length];
        }

        /** Checks whether a given cell contains a star */
        private boolean isStar(int r, int c) {
            return cells[r][c] == '*';
        }

        /** Marks the centre and all four arms of a placement as visited */
        private void markVisited(int centreR, int centreC, int size) {
            visited[centreR][centreC] = true;
            for (int step = 1; step <= size; step++) {
                markIfStar(centreR + step, centreC);
                markIfStar(centreR - step, centreC);
                markIfStar(centreR, centreC + step);
                markIfStar(centreR, centreC - step);
            }
        }

        /** Helper – marks a cell as visited if it is inside the grid */
        private void markIfStar(int r, int c) {
            if (inBounds(r, c) && isStar(r, c)) {
                visited[r][c] = true;
            }
        }

        /** Returns true if (r,c) is inside the matrix */
        private boolean inBounds(int r, int c) {
            return r >= 0 && r < cells.length && c >= 0 && c < cells[0].length;
        }

        /** Finds every possible cross‑shaped placement centred on a '*' */
        List<Placement> findAllPlacements() {
            List<Placement> placements = new ArrayList<>();

            for (int r = 0; r < cells.length; r++) {
                for (int c = 0; c < cells[r].length; c++) {
                    if (isStar(r, c)) {
                        int size = computeMinimalArmSize(r, c);
                        if (size > 0) {                 // a valid cross was found
                            placements.add(new Placement(r, c, size));
                            markVisited(r, c, size);
                        }
                    }
                }
            }
            return placements;
        }

        /** Determines the length of the shortest continuous star line in any direction */
        private int computeMinimalArmSize(int centreR, int centreC) {
            int smallest = Integer.MAX_VALUE;

                // down
                smallest = Math.min(smallest, countStarsInDirection(centreR, centreC, 1, 0));
                // up
                smallest = Math.min(smallest, countStarsInDirection(centreR, centreC, -1, 0));
                // right
                smallest = Math.min(smallest, countStarsInDirection(centreR, centreC, 0, 1));
                // left
                smallest = Math.min(smallest, countStarsInDirection(centreR, centreC, 0, -1));

            return smallest;
        }

        /** Counts consecutive '*' from (r,c) moving by (dr,dc) until a non‑star or edge is hit */
        private int countStarsInDirection(int startR, int startC, int dr, int dc) {
            int cnt = 0;
            int r = startR + dr;
            int c = startC + dc;
            while (inBounds(r, c) && isStar(r, c)) {
                cnt++;
                r += dr;
                c += dc;
            }
            return cnt;
        }

        /** Verifies that every '*' in the original grid has been visited */
        boolean areAllStarsCovered() {
            for (int r = 0; r < cells.length; r++) {
                for (int c = 0; c < cells[r].length; c++) {
                    if (isStar(r, c) && !visited[r][c]) {
                        return false;
                    }
                }
            }
            return true;
        }
    }

    /** -----------------------------------------------------------------
     *  Very small, fast scanner that implements {@link AutoCloseable}.
     *  -------------------------------------------------------------- */
    private static final class FastScanner implements AutoCloseable {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner(Reader source) {
            this.br = new BufferedReader(source);
        }

        /** Returns the next token, reading a new line when the current token buffer is empty */
        private String nextToken() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) {
                        return null;
                    }
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new UncheckedIOException(e);
                }
            }
            return st.nextToken();
        }

        /** Convenience wrappers */
        int nextInt() { return Integer.parseInt(nextToken()); }
        String next() { return nextToken(); }

        @Override
        public void close() throws IOException {
            br.close();
        }
    }
}

import java.io.*;
import java.util.ArrayList;
import java.util.List;

/**
 * Entry point of the application.
 * <p>
 * The program reads a rectangular grid that consists of '.' (empty) and '*' (filled) cells.
 * A *star* is a centre cell with arms extending in the four orthogonal directions,
 * each arm having the same length {@code r} (≥ 1). The task is to discover all stars,
 * output their centres (1‑based) and arm length, and ensure that every '*' cell belongs
 * to exactly one star. If this is impossible the program prints {@code -1}.
 * </p>
 */
public class Main {

    /** Buffered output that automatically flushes after each println. */
    private static final PrintWriter OUT = new PrintWriter(System.out, true);

    public static void main(String[] args) throws IOException {
        /*
         * Try‑with‑resources guarantees that the reader is closed even when an exception occurs.
         */
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(System.in))) {
            // -----------------------------------------------------------------
            // 1️⃣  Read dimensions and the grid itself
            // -----------------------------------------------------------------
            String[] dimTokens = readTokenLine(reader);
            int height = Integer.parseInt(dimTokens[0]);
            int width  = Integer.parseInt(dimTokens[1]);

            Grid grid = new Grid(height, width);
            grid.readInput(reader);
            if (!grid.buildDp()) {
                // No stars can be formed – output -1 and terminate.
                OUT.println(-1);
                return;
            }

            // -----------------------------------------------------------------
            // 2️⃣  Find all stars
            // -----------------------------------------------------------------
            List<Star> stars = grid.findStars();

            // -----------------------------------------------------------------
            // 3️⃣  Validate that every filled cell is covered by a star arm
            // -----------------------------------------------------------------
            if (!grid.validateCoverage(stars)) {
                OUT.println(-1);
                return;
            }

            // -----------------------------------------------------------------
            // 4️⃣  Output the result
            // -----------------------------------------------------------------
            OUTPUT_STARS(stars);
        }
    }

    /** Reads a whole line, trims it and splits it on one or more whitespace characters. */
    private static String[] readTokenLine(BufferedReader br) throws IOException {
        return br.readLine().trim().split("\\s+");
    }

    /** Prints the list of discovered stars in the required format. */
    private static void OUTPUT_STARS(List<Star> stars) {
        System.out.println(stars.size());
        for (Star s : stars) {
            System.out.println(s.row + " " + s.col + " " + s.radius);
        }
    }
}

/**
 * Represents a discovered star.
 * The coordinates are 1‑based (the problem statement expects this format).
 */
final class Star {
    final int row;      // centre row   (1‑based)
    final int col;      // centre column(1‑based)
    final int radius;   // arm length   (≥ 1)

    Star(int row, int col, int radius) {
        this.row   = row;
        this.col   = col;
        this.radius = radius;
    }
}

/**
 * Encapsulates the grid, DP tables and the logic required to discover stars.
 */
final class Grid {

    private final int height;
    private final int width;
    private char[][] field;               // raw grid characters
    private final boolean[][] visited;    // marks cells belonging to a star arm

    // DP accumulators – counts of consecutive '*' cells in each direction
    private int[][] left;
    private int[][] right;
    private int[][] up;
    private int[][] down;

    Grid(int height, int width) {
        this.height = height;
        this.width  = width;
        this.field  = new char[height][];
        this.visited = new boolean[height][width];
    }

    /** Reads the grid from the supplied reader. */
    void readInput(BufferedReader br) throws IOException {
        for (int r = 0; r < height; r++) {
            field[r] = br.readLine().toCharArray();
        }
    }

    /** Builds DP tables that count consecutive '*' cells in the four directions. */
    boolean buildDp() {
        left  = new int[height][width];
        right = new int[height][width];
        up    = new int[height][width];
        down  = new int[height][width];

        /* ---------- Horizontal accumulations ---------- */
        for (int r = 0; r < height; r++) {
            // left → right
            for (int c = 1; c < width; c++) {
                left[r][c] = (field[r][c] == '*') ? left[r][c - 1] + 1 : 0;
            }
            // right → left
            for (int c = width - 2; c >= 0; c--) {
                right[r][c] = (field[r][c] == '*') ? right[r][c + 1] + 1 : 0;
            }
        }

        /* ---------- Vertical accumulations ---------- */
        for (int c = 0; c < width; c++) {
            // up → down
            for (int r = 1; r < height; r++) {
                up[r][c] = (field[r][c] == '*') ? up[r - 1][c] + 1 : 0;
            }
            // down → up
            for (int r = height - 2; r >= 0; r--) {
                down[r][c] = (field[r][c] == '*') ? down[r + 1][c] + 1 : 0;
            }
        }

        return true; // success – DP tables are ready
    }

    /**
     * Scans the grid for star centres.
     * For each centre the maximal possible arm length {@code radius} is the
     * smallest of the four directional counts that meet at that cell.
     */
    List<Star> findStars() {
        List<Star> stars = new ArrayList<>();

        // Only interior cells can be centres because an arm would otherwise go out of bounds.
        for (int r = 1; r < height - 1; r++) {
            for (int c = 1; c < width - 1; c++) {
                if (field[r][c] != '*') continue;

                // Arm length is limited by the smallest directional count.
                int radius = Math.min(
                        Math.min(left[r][c], right[r][c]),
                        Math.min(up[r][c],   down[r][c])
                );
                if (radius == 0) continue;   // not a valid centre

                // Mark every cell covered by this star's arms.
                markArm(r, c, radius);

                stars.add(new Star(r + 1, c + 1, radius)); // convert to 1‑based indices
            }
        }
        return stars;
    }

    /** Marks the cells belonging to the arms of a star centred at (row, col) with given radius. */
    private void markArm(int row, int col, int radius) {
        // vertical arm
        for (int r = row - radius; r <= row + radius; r++) {
            visited[r][col] = true;
        }
        // horizontal arm
        for (int c = col - radius; c <= col + radius; c++) {
            visited[row][c] = true;
        }
    }

    /** Checks that every '*' cell has been visited exactly once. */
    boolean validateCoverage(List<Star> stars) {
        for (int r = 0; r < height; r++) {
            for (int c = 0; c < width; c++) {
                if (field[r][c] == '*' && !visited[r][c]) {
                    return false; // uncovered filled cell → impossible configuration
                }
            }
        }
        return true;
    }
}

import java.io.PrintWriter;
import java.util.ArrayDeque;
import java.util.Deque;
import java.util.Scanner;

/**
 * Reads a character grid, finds all asterisks that can serve as the centre of a
 * symmetric “*” pattern (arms of equal non‑zero length in the four orthogonal
 * directions) and prints for each such centre its 1‑based coordinates together
 * with the arm length. If the grid contains asterisks that are not part of any
 * such pattern, the program prints –1.
 *
 * <p>Refactored version of the original {@code StarsDrawing} program.
 * The code emphasises readability, separation of concerns and deterministic
 * resource handling.</p>
 */
public class StarsDrawing {

    /** Simple container for a potential centre together with the arm length. */
    private static final class Triple {
        final int row;   // 0‑based row index
        final int col;   // 0‑based column index
        final int arm;   // length of each arm (≥1)

        Triple(int row, int col, int arm) {
            this.row = row;
            this.col = col;
            this.arm = arm;
        }
    }

    /** Directions used for the four orthogonal arms. */
    private enum Direction {
        UP(-1, 0), DOWN(1, 0), LEFT(0, -1), RIGHT(0, 1);

        final int dRow;
        final int dCol;

        Direction(int dRow, int dCol) {
            this.dRow = dRow;
            this.dCol = dCol;
        }
    }

    /** Reads the grid from {@link Scanner} supplied by the caller. */
    private static char[][] readGrid(Scanner scanner, int rows, int cols) {
        char[][] grid = new char[rows][];
        for (int r = 0; r < rows; ++r) {
            String line = scanner.next();
            if (line.length() != cols) {
                throw new IllegalArgumentException(
                        String.format("Row %d does not contain %d characters", r + 1, cols));
            }
            grid[r] = line.toCharArray();
        }
        return grid;
    }

    /**
     * Returns the length of a consecutive asterisk line that starts at
     * {@code (r, c)} and proceeds in {@code dir}.
     * The length does not include the starting cell (i.e. it is the number of
     * additional cells that are also asterisks).
     */
    private static int lengthInDirection(char[][] grid, int r, int c, Direction dir) {
        int length = 0;
        int nr = r + dir.dRow;
        int nc = c + dir.dCol;
        while (inside(grid, nr, nc) && grid[nr][nc] == '*') {
            ++length;
            nr += dir.dRow;
            nc += dir.dCol;
        }
        return length;
    }

    /** Checks that {@code (i, j)} lies inside the grid. */
    private static boolean inside(char[][] grid, int i, int j) {
        return i >= 0 && i < grid.length && j >= 0 && j < grid[0].length;
    }

    /** Marks a centre and its four arms as “processed’’ by turning every involved
     *  asterisk into ‘#’. */
    private static void markArms(char[][] grid, Triple centre) {
        for (Direction d : Direction.values()) {
            int r = centre.row;
            int c = centre.col;
            for (int step = 0; step <= centre.arm; ++step) {   // include centre cell
                grid[r][c] = '#';
                r += d.dRow;
                c += d.dCol;
            }
        }
    }

    /** Determines whether the supplied grid contains any stray asterisks
     *  (i.e. asterisks that are not part of a symmetric pattern).
     */
    private static boolean gridHasRemainingAsterisks(char[][] grid) {
        for (char[] row : grid) {
            for (char cell : row) {
                if (cell == '*') {
                    return true;
                }
            }
        }
        return false;
    }

    public static void main(String[] args) {
        /* --------------------------------------------------------------
         *  Input & output resources – try‑with‑resources guarantees closure.
         * -------------------------------------------------------------- */
        try (Scanner scanner = new Scanner(System.in);
             PrintWriter pw = new PrintWriter(System.out)) {

            // ----- read dimensions & grid -------------------------------------------------
            int rows = scanner.nextInt();
            int cols = scanner.nextInt();
            char[][] grid = readGrid(scanner, rows, cols);

            // ----- collect all valid centres ------------------------------------------------
            Deque<Triple> centres = new ArrayDeque<>();
            StringBuilder report = new StringBuilder();

            boolean anyStarWasFound = false;
            for (int r = 0; r < rows; ++r) {
                for (int c = 0; c < cols; ++c) {
                    if (grid[r][c] != '*') {
                        continue;
                    }
                    anyStarWasFound = true;

                    // compute the length of each arm
                    int upLen = lengthInDirection(grid, r, c, Direction.UP);
                    int downLen = lengthInDirection(grid, r, c, Direction.DOWN);
                    int leftLen = lengthInDirection(grid, r, c, Direction.LEFT);
                    int rightLen = lengthInDirection(grid, r, c, Direction.RIGHT);

                    int minArm = Math.min(Math.min(upLen, downLen),
                                          Math.min(leftLen, rightLen));

                    if (minArm > 0) {
                        // this asterisk can be a centre of a symmetric pattern
                        centres.add(new Triple(r, c, minArm));
                        report.append(r + 1).append(' ')
                              .append(c + 1).append(' ')
                              .append(minArm).append('\n');
                    }
                }
            }

            // ----- mark processed cells ----------------------------------------------------
            while (!centres.isEmpty()) {
                Triple centre = centres.pollFirst();
                markArms(grid, centre);
            }

            // ----- validation ---------------------------------------------------------------
            boolean strayAsteriskExists = gridHasRemainingAsterisks(grid);

            // If there were asterisks but none could form a symmetric pattern,
            // or if stray asterisks remain, we must output -1.
            boolean outputError = (anyStarWasFound && centres.isEmpty()) || strayAsteriskExists;

            if (outputError) {
                pw.println(-1);
            } else {
                pw.println(centres.size());            // number of reported centres
                pw.print(report);                         // the detailed list
            }

        } catch (Exception e) {
            // In a contest‑style problem we simply write the error code.
            // For a library‑like implementation we would propagate the exception.
            System.err.println("Unexpected input or error: " + e.getMessage());
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Entry point of the application.
 */
public class Main {
    public static void main(String[] args) {
        InputStream in = System.in;
        PrintWriter out = new PrintWriter(System.out);
        try {
            new Solver().solve(1, new InputReader(in), out);
        } finally {
            out.close();
        }
    }
}

/**
 * Core solving logic for the problem.
 */
final class Solver {
    /** Width of the artificial '.' border that is added around the grid. */
    private static final int BORDER = 2;

    /**
     * Solves a single test case.
     *
     * @param testCaseIdx index of the test case (currently always 1)
     * @param in          input reader
     * @param out         output writer
     */
    void solve(int testCaseIdx, InputReader in, PrintWriter out) {
        // -----------------------------------------------------------------
        // 1. Read dimensions and build the grid (including the border)
        // -----------------------------------------------------------------
        int rawRows = in.nextInt();          // inner rows before adding border
        int rawCols = in.nextInt();          // inner columns before adding border
        int rows = rawRows + BORDER;
        int cols = rawCols + BORDER;

        char[][] grid = readGrid(in, rows, cols);

        // -----------------------------------------------------------------
        // 2. Compute directional accumulations of consecutive '*'
        // -----------------------------------------------------------------
        int[][] left   = computeLeft(grid);
        int[][] top    = computeTop(grid);
        int[][] right  = computeRight(grid);
        int[][] bottom = computeBottom(grid);

        // -----------------------------------------------------------------
        // 3. Determine the minimum distance in each direction for every '*'
        // -----------------------------------------------------------------
        int[][] minDist = new int[rows][cols];
        int bombCount = 0;
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] != '*') {
                    continue;
                }
                int d = Math.min(
                        left[r][c],
                        Math.min(top[r][c], Math.min(right[r][c], bottom[r][c]))
                );
                minDist[r][c] = Math.max(d - 1, -1); // -1 means “uncovered”
                if (minDist[r][c] > 0) {
                    bombCount++;
                }
            }
        }

        // -----------------------------------------------------------------
        // 4. Build a coverage map from the distance information
        // -----------------------------------------------------------------
        boolean[][] covered = computeCoverage(minDist, rows, cols);

        // -----------------------------------------------------------------
        // 5. Verify that every '*' in the original grid is covered
        // -----------------------------------------------------------------
        if (!verifyCoverage(grid, covered)) {
            out.println(-1);
            return;
        }

        // -----------------------------------------------------------------
        // 6. Output the answer
        // -----------------------------------------------------------------
        out.println(bombCount);
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (minDist[r][c] > 0) {
                    // convert coordinates back to the original (inner) grid
                    out.printf("%d %d %d%n", r - BORDER, c - BORDER, minDist[r][c]);
                }
            }
        }
    }

    /** Reads the grid, filling the outer border with '.' characters. */
    private static char[][] readGrid(InputReader in, int rows, int cols) {
        char[][] grid = new char[rows][cols];

        // top and bottom borders are all '.'
        Arrays.fill(grid[0], '.');
        Arrays.fill(grid[rows - 1], '.');

        // left and right borders are '.' for inner rows
        for (int r = 1; r < rows - 1; r++) {
            grid[r][0] = grid[r][cols - 1] = '.';
        }

        // fill the inner rows with the data read from the input
        for (int r = 1; r < rows - 1; r++) {
            char[] line = in.nextCharArray();
            System.arraycopy(line, 0, grid[r], 1, cols - 2);
        }
        return grid;
    }

    /** Consecutive '*' looking to the left (including the current cell). */
    private static int[][] computeLeft(char[][] grid) {
        int rows = grid.length;
        int cols = grid[0].length;
        int[][] left = new int[rows][cols];
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '*' && c > 0) {
                    left[r][c] = left[r][c - 1] + 1;
                } else {
                    left[r][c] = 0;
                }
            }
        }
        return left;
    }

    /** Consecutive '*' looking upwards (including the current cell). */
    private static int[][] computeTop(char[][] grid) {
        int rows = grid.length;
        int cols = grid[0].length;
        int[][] top = new int[rows][cols];
        for (int c = 0; c < cols; c++) {
            for (int r = 0; r < rows; r++) {
                if (grid[r][c] == '*' && r > 0) {
                    top[r][c] = top[r - 1][c] + 1;
                } else {
                    top[r][c] = 0;
                }
            }
        }
        return top;
    }

    /** Consecutive '*' looking to the right (including the current cell). */
    private static int[][] computeRight(char[][] grid) {
        int rows = grid.length;
        int cols = grid[0].length;
        int[][] right = new int[rows][cols];
        for (int r = 0; r < rows; r++) {
            for (int c = cols - 1; c >= 0; c--) {
                if (grid[r][c] == '*' && c < cols - 1) {
                    right[r][c] = right[r][c + 1] + 1;
                } else {
                    right[r][c] = 0;
                }
            }
        }
        return right;
    }

    /** Consecutive '*' looking downwards (including the current cell). */
    private static int[][] computeBottom(char[][] grid) {
        int rows = grid.length;
        int cols = grid[0].length;
        int[][] bottom = new int[rows][cols];
        for (int c = 0; c < cols; c++) {
            for (int r = rows - 1; r >= 0; r--) {
                if (grid[r][c] == '*' && r < rows - 1) {
                    bottom[r][c] = bottom[r + 1][c] + 1;
                } else {
                    bottom[r][c] = 0;
                }
            }
        }
        return bottom;
    }

    /** Generates a boolean coverage matrix based on the computed distances. */
    private static boolean[][] computeCoverage(int[][] minDist, int rows, int cols) {
        boolean[][] covered = new boolean[rows][cols];

        // ----- Horizontal propagation -----
        for (int r = 0; r < rows; r++) {
            int leftPropagation = -1;
            int rightPropagation = -1;
            for (int c = 0; c < cols; c++) {
                leftPropagation = Math.max(leftPropagation, minDist[r][c]);
                if (leftPropagation >= 0) {
                    covered[r][c] = true;
                    leftPropagation--;
                }

                int revC = cols - 1 - c;
                rightPropagation = Math.max(rightPropagation, minDist[r][revC]);
                if (rightPropagation >= 0) {
                    covered[r][revC] = true;
                    rightPropagation--;
                }
            }
        }

        // ----- Vertical propagation -----
        for (int c = 0; c < cols; c++) {
            int upPropagation = -1;
            int downPropagation = -1;
            for (int r = 0; r < rows; r++) {
                upPropagation = Math.max(upPropagation, minDist[r][c]);
                if (upPropagation >= 0) {
                    covered[r][c] = true;
                    upPropagation--;
                }

                int revR = rows - 1 - r;
                downPropagation = Math.max(downPropagation, minDist[revR][c]);
                if (downPropagation >= 0) {
                    covered[revR][c] = true;
                    downPropagation--;
                }
            }
        }
        return covered;
    }

    /** Checks that every '*' in the original grid is marked as covered. */
    private static boolean verifyCoverage(char[][] grid, boolean[][] covered) {
        for (int r = 0; r < grid.length; r++) {
            for (int c = 0; c < grid[0].length; c++) {
                if (grid[r][c] == '*' && !covered[r][c]) {
                    return false;
                }
            }
        }
        return true;
    }
}

/**
 * Simple fast scanner for competitive‑programming style input.
 */
final class InputReader {
    private final BufferedReader br;
    private StringTokenizer st;

    InputReader(InputStream stream) {
        br = new BufferedReader(new InputStreamReader(stream));
    }

    /** Returns the next token, blocking until one is available. */
    String next() {
        while (st == null || !st.hasMoreTokens()) {
            try {
                st = new StringTokenizer(br.readLine());
            } catch (IOException e) {
                throw new UncheckedIOException(e);
            }
        }
        return st.nextToken();
    }

    int nextInt() {
        return Integer.parseInt(next());
    }

    /** Returns the next token as a character array (useful for reading a line). */
    char[] nextCharArray() {
        return next().toCharArray();
    }
}

import java.io.*;
import java.util.*;

public class Main {

    /** Simple DTO that stores the position and size of a detected star. */
    private static final class Star {
        final int col;   // m coordinate in the original code
        final int row;   // n coordinate in the original code
        final int size;  // s (arm length)

        Star(int col, int row, int size) {
            this.col = col;
            this.row = row;
            this.size = size;
        }
    }

    /** Entry point – mirrors the original `public static void main`. */
    public static void main(String[] args) throws IOException {
        try (Scanner scanner = new Scanner(new BufferedInputStream(System.in))) {
            PrintWriter writer = new PrintWriter(new BufferedOutputStream(System.out));
            solve(scanner, writer);
            writer.flush();
        }
    }

    /** Main algorithm driver – parses input, finds stars, validates coverage, and writes output. */
    private static void solve(Scanner in, PrintWriter out) {
        int rows = in.nextInt();          // n
        int cols = in.nextInt();          // m
        in.nextLine();                     // consume trailing newline

        boolean[][] originalField   = readField(in, rows, cols);
        boolean[][] testField       = new boolean[rows][cols];

        List<Star> detectedStars = findStars(originalField, rows, cols);
        applyStars(detectedStars, testField, rows, cols);

        if (fieldsAreEqual(originalField, testField)) {
            out.println(detectedStars.size());
            for (Star star : detectedStars) {
                out.printf("%d %d %d%n", star.row + 1, star.col + 1, star.size);
            }
        } else {
            out.println(-1);
        }
    }

    /** Reads the star‑pattern grid from the scanner. */
    private static boolean[][] readField(Scanner in, int rows, int cols) {
        boolean[][] field = new boolean[rows][cols];
        for (int i = 0; i < rows; i++) {
            String line = in.nextLine();
            for (int j = 0; j < cols; j++) {
                field[i][j] = line.charAt(j) == '*';
            }
        }
        return field;
    }

    /** Scans the whole board and builds a list of all valid Star objects. */
    private static List<Star> findStars(boolean[][] field, int rows, int cols) {
        List<Star> stars = new ArrayList<>();
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                int size = 0;
                while (isCross(field, r, c, size + 1)) {
                    size++;
                }
                if (size > 0) {
                    stars.add(new Star(c, r, size));
                }
            }
        }
        return stars;
    }

    /** Returns true if a cross of the given arm length can be placed centred at (row, col). */
    private static boolean isCross(boolean[][] field, int centerRow, int centerCol, int size) {
        int n = field.length;   // rows
        int m = field[0].length; // cols

        int top    = centerRow - size;
        int bottom = centerRow + size;
        int left   = centerCol - size;
        int right  = centerCol + size;

        if (top < 0 || bottom >= n || left < 0 || right >= m) {
            return false;
        }

        // horizontal arm
        for (int col = left; col <= right; col++) {
            if (!field[centerRow][col]) {
                return false;
            }
        }

        // vertical arm
        for (int row = top; row <= bottom; row++) {
            if (!field[row][centerCol]) {
                return false;
            }
        }
        return true;
    }

    /** Marks all arms of every detected star on the test field. */
    private static void applyStars(List<Star> stars, boolean[][] testField, int rows, int cols) {
        for (Star star : stars) {
            int top    = star.row - star.size;
            int bottom = star.row + star.size;
            int left   = star.col - star.size;
            int right  = star.col + star.size;

            // horizontal arm
            for (int col = left; col <= right; col++) {
                testField[star.row][col] = true;
            }

            // vertical arm
            for (int row = top; row <= bottom; row++) {
                testField[row][star.col] = true;
            }
        }
    }

    /** Checks whether two boolean matrices are identical. */
    private static boolean fieldsAreEqual(boolean[][] a, boolean[][] b) {
        for (int i = 0; i < a.length; i++) {
            if (!Arrays.equals(a[i], b[i])) {
                return false;
            }
        }
        return true;
    }
}

/**
 * Refactored version of the original solution.
 * The program reads a grid of characters ('*' or '.'), determines the maximal
 * “cross” size that can be placed on each star, records the positions and
 * sizes of all viable crosses, and finally prints the number of such crosses
 * followed by their 1‑based coordinates and sizes. If the recorded data does not
 * match the expected constraints the program prints -1.
 *
 * The refactor focuses on readability, maintainability and separation of concerns:
 *   • Meaningful identifiers instead of short abbreviations.
 *   • Helper methods isolate logical steps.
 *   • Small utility classes replace raw parallel arrays.
 *   • Magic numbers are replaced by named constants.
 *   • Static imports are removed in favour of explicit field access.
 *   • Input handling is encapsulated in a dedicated scanner class.
 */
import java.io.*;
import java.util.*;

public class Main {

    /* ---------------------------------------------------------------------- */
    /*  Constants & small utility classes                                       */
    /* ---------------------------------------------------------------------- */
    private static final class Star {
        final int row, col, size;               // 0‑based coordinates and maximal cross size

        Star(int row, int col, int size) {
            this.row = row;
            this.col = col;
            this.size = size;
        }
    }

    /** Fast scanner that works with BufferedReader and StringTokenizer. */
    private static final class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner(InputStream resource) {
            this.br = new BufferedReader(new InputStreamReader(resource));
        }

        /** Returns the next non‑empty token. */
        String next() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                st = new StringTokenizer(br.readLine());
            }
            return st.nextToken();
        }

        /** @return true if there is still input to read. */
        boolean hasNext() throws IOException {
            return br.ready() || (st != null && st.hasMoreTokens());
        }

        /** Reads the next token as an {@code int}. */
        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }

        /** Reads the next line (including empty lines). */
        String nextLine() throws IOException {
            return br.readLine();
        }

        /** @return true if the next line exists. */
        boolean hasNextLine() throws IOException {
            return br.ready();
        }
    }

    /* ---------------------------------------------------------------------- */
    /*  Core solving logic                                                      */
    /* ---------------------------------------------------------------------- */
    private final FastScanner in;
    private final PrintWriter out;

    /** Maximum dimension of the grid – used only for allocating temporary arrays. */
    private static final int MAX = 2_000;   // safe upper bound for typical contest problems

    /** Holds pre‑computed prefix sums for row‑wise and column‑wise constraints. */
    private static final class Diff2D {
        final int[][] row;   // horizontal differences
        final int[][] col;   // vertical differences

        Diff2D(int rows, int cols) {
            this.row = new int[rows][cols];
            this.col = new int[rows][cols];
        }

        /** Increment a cell in the row‑difference matrix. */
        void addRow(int r, int c, int delta) {
            row[r][c] += delta;
        }

        /** Increment a cell in the column‑difference matrix. */
        void addCol(int r, int c, int delta) {
            col[r][c] += delta;
        }

        /** Apply the accumulated differences to obtain the final values. */
        void prefixSumRow() {
            for (int r = 0; r < row.length; ++r) {
                for (int c = 1; c < row[r].length; ++c) {
                    row[r][c] += row[r][c - 1];
                }
            }
        }

        /** Apply the accumulated differences to obtain the final values. */
        void prefixSumCol() {
            for (int c = 0; c < col[0].length; ++c) {
                for (int r = 1; r < col.length; ++r) {
                    col[r][c] += col[r - 1][c];
                }
            }
        }
    }

    /** Computes how many consecutive stars exist to the left/right/up/down of each cell. */
    private static int[][] computeLeft(boolean[][] grid) {
        int rows = grid.length;
        int cols = grid[0].length;
        int[][] left = new int[rows][cols];
        for (int r = 0; r < rows; ++r) {
            for (int c = 1; c < cols; ++c) {
                left[r][c] = grid[r][c - 1] ? left[r][c - 1] + 1 : 0;
            }
        }
        return left;
    }

    private static int[][] computeRight(boolean[][] grid) {
        int rows = grid.length;
        int cols = grid[0].length;
        int[][] right = new int[rows][cols];
        for (int r = 0; r < rows; ++r) {
            for (int c = cols - 2; c >= 0; --c) {
                right[r][c] = grid[r][c + 1] ? right[r][c + 1] + 1 : 0;
            }
        }
        return right;
    }

    private static int[][] computeUp(boolean[][] grid) {
        int rows = grid.length;
        int cols = grid[0].length;
        int[][] up = new int[rows][cols];
        for (int r = 1; r < rows; ++r) {
            System.arraycopy(up[r - 1], 0, up[r], 0, cols);
            for (int c = 0; c < cols; ++c) {
                if (grid[r - 1][c]) up[r][c]++;
                else up[r][c] = 0;
            }
        }
        return up;
    }

    private static int[][] computeDown(boolean[][] grid) {
        int rows = grid.length;
        int cols = grid[0].length;
        int[][] down = new int[rows][cols];
        for (int r = rows - 2; r >= 0; --r) {
            System.arraycopy(down[r + 1], 0, down[r], 0, cols);
            for (int c = 0; c < cols; ++c) {
                if (grid[r + 1][c]) down[r][c]++;
                else down[r][c] = 0;
            }
        }
        return down;
    }

    /** Determines the maximal cross size that can be centred at (r,c). */
    private static int maximalCrossSize(boolean[][] grid,
                                        int[][] left,
                                        int[][] right,
                                        int[][] up,
                                        int[][] down) {
        int size = Math.min(
                Math.min(left[row][col], right[row][col]),
                Math.min(up[row][col], down[row][col])
        );
        return size > 0 ? size : 0;
    }

    /** Main solving routine. */
    private void solve() throws IOException {
        int rows = in.nextInt();
        int cols = in.nextInt();

        boolean[][] grid = readGrid(rows, cols);

        // Pre‑compute directional continuations
        int[][] left = computeLeft(grid);
        int[][] right = computeRight(grid);
        int[][] up = computeUp(grid);
        int[][] down = computeDown(grid);

        List<Star> stars = new ArrayList<>();

        // Diff‑arrays used to count how many “crosses” intersect each cell in the four directions
        Diff2D rowDiff = new Diff2D(rows, cols);
        Diff2D colDiff = new Diff2D(rows, cols);

        for (int r = 0; r < rows; ++r) {
            for (int c = 0; c < cols; ++c) {
                if (!grid[r][c]) continue;

                int maxSize = maximalCrossSize(grid, left, right, up, down);
                if (maxSize == 0) continue;               // isolated star, cannot form a cross

                Star star = new Star(r, c, maxSize);
                stars.add(star);

                // Register the horizontal interval that this cross occupies
                int leftBound = c - maxSize;
                int rightBound = c + maxSize;
                rowDiff.addRow(r, leftBound, 1);
                if (rightBound + 1 < cols) {
                    rowDiff.addRow(r, rightBound + 1, -1);
                }

                // Register the vertical interval that this cross occupies
                int topBound = r - maxSize;
                int bottomBound = r + maxSize;
                colDiff.addCol(topBound, c, 1);
                if (bottomBound + 1 < rows) {
                    colDiff.addCol(bottomBound + 1, c, -1);
                }
            }
        }

        // Resolve the difference arrays to get the actual counts per cell
        rowDiff.prefixSumRow();
        colDiff.prefixSumCol();

        // Verify that every star cell is covered by exactly one horizontal and one vertical cross
        for (int r = 0; r < rows; ++r) {
            for (int c = 0; c < cols; ++c) {
                if (grid[r][c] && rowDiff.row[r][c] == 0 && colDiff.col[r][c] == 0) {
                    out.println(-1);
                    return;
                }
            }
        }

        // Output the result
        out.println(stars.size());
        for (Star s : stars) {
            // Convert to 1‑based coordinates for user‑friendly output
            out.printf("%d %d %d%n", s.row + 1, s.col + 1, s.size);
        }
    }

    /** Reads the grid from the scanner. */
    private boolean[][] readGrid(int rows, int cols) {
        boolean[][] map = new boolean[rows][cols];
        for (int r = 0; r < rows; ++r) {
            char[] line = in.next().toCharArray();
            for (int c = 0; c < cols; ++c) {
                map[r][c] = line[c] == '*';
            }
        }
        return map;
    }

    /** Entry point – wiring everything together. */
    private void run() throws IOException {
        in = new FastScanner(System.in);
        out = new PrintWriter(System.out, true);   // auto‑flush

        solve();

        out.close();
    }

    public static void main(String[] args) throws IOException {
        new Main().run();
    }
}

import java.io.PrintWriter;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.Scanner;

/**
 * Entry point for the solution.
 * Reads a rectangular grid, detects “*” segments, tries to place a star
 * in every possible cell and checks if the placements cover all “*”.
 * Outputs either –1 or the list of found stars.
 */
public class E1015 {

    /** Solves the problem using the supplied {@link Scanner} and {@link PrintWriter}. */
    public void solve(Scanner scanner, PrintWriter out) {
        int rows = scanner.nextInt();
        int cols = scanner.nextInt();
        boolean[][] grid = readGrid(scanner, rows, cols);

        // Identify horizontal and vertical segments containing '*'
        Segment[] horizontalSegments = findHorizontalSegments(grid);
        Segment[] verticalSegments   = findVerticalSegments(grid);

        // Build a Fenwick tree (Binary Indexed Tree) for each row and column.
        FenwickTree[] rowTrees = createRowFenwickTrees(rows, cols);
        FenwickTree[] colTrees = createColumnFenwickTrees(rows, cols);

        // Collect candidate star cells.
        List<StarInfo> stars = new ArrayList<>();
        int starCount = 0;

        for (int r = 0; r < rows; ++r) {
            for (int c = 0; c < cols; ++c) {
                if (!grid[r][c]) continue;

                int horIdx = horizontalSegmentIndex(r, c, horizontalSegments);
                int verIdx = verticalSegmentIndex(r, c, verticalSegments);

                // Skip cells that are not part of both a horizontal and a vertical segment.
                if (horIdx == -1 || verIdx == -1) continue;

                Segment horSeg = horizontalSegments[horIdx];
                Segment verSeg = verticalSegments[verIdx];

                // Minimum distance to the borders of the current segment pair.
                int minDist = Math.min(
                        Math.min(r - verSeg.startRow, verSeg.endRow - r),
                        Math.min(c - horSeg.startCol, horSeg.endCol - c)
                );

                // Distance zero means we cannot place a star here (the star would be on a border cell).
                if (minDist == 0) continue;

                // Record the star.
                StarInfo info = new StarInfo(r, c, minDist);
                stars.add(info);
                starCount++;

                // Perform range updates on the BITs (record that we “cover” this area).
                rowTrees[r].rangeAdd(c - minDist, c + minDist, 1);
                colTrees[c].rangeAdd(r - minDist, r + minDist, 1);
            }
        }

        // Verify that every '*' cell is covered by at least one star.
        boolean feasible = true;
        for (int r = 0; r < rows && feasible; ++r) {
            for (int c = 0; c < cols && feasible; ++c) {
                if (!grid[r][c]) continue;
                long coverage = rowTrees[r].prefixSum(c) + colTrees[c].prefixSum(r);
                if (coverage <= 0) {
                    feasible = false; // This '*' cell would stay uncovered.
                }
            }
        }

        if (!feasible) {
            out.println(-1);
        } else {
            out.println(starCount);
            StringBuilder builder = new StringBuilder();
            for (StarInfo info : stars) {
                builder.append(info.row + 1)
                       .append(' ')
                       .append(info.col + 1)
                       .append(' ')
                       .append(info.minDist)
                       .append('\n');
            }
            out.print(builder.toString());
        }
    }

    /* --------------------------------------------------------------
       Helper methods for reading the grid and discovering segments.
       -------------------------------------------------------------- */

    private static boolean[][] readGrid(Scanner scanner, int rows, int cols) {
        boolean[][] grid = new boolean[rows][cols];
        for (int i = 0; i < rows; ++i) {
            String line = scanner.next();
            for (int j = 0; j < cols; ++j) {
                grid[i][j] = line.charAt(j) == '*';
            }
        }
        return grid;
    }

    private static Segment[] findHorizontalSegments(boolean[][] grid) {
        int rows = grid.length;
        int cols = grid[0].length;
        Segment[] segs = new Segment[rows];
        Arrays.fill(segs, new Segment());

        int segmentId = 0;
        for (int r = 0; r < rows; ++r) {
            for (int c = 0; c < cols; ++c) {
                if (!grid[r][c]) continue;
                // If we have already processed this cell as part of a segment, skip it.
                if (segs[r].id != -1) continue;

                int curId = segmentId++;
                segs[r].id = curId;
                segs[r].startCol = c;

                while (c < cols && grid[r][c]) {
                    segs[r].id = curId;
                    ++c;
                }
                segs[r].endCol = c - 1;
            }
        }

        // Compact the array to only keep active segment ids.
        List<Segment> result = new ArrayList<>();
        for (Segment seg : segs) {
            if (seg.id != -1) {
                result.add(seg);
            }
        }
        return result.toArray(new Segment[0]);
    }

    private static Segment[] findVerticalSegments(boolean[][] grid) {
        int rows = grid.length;
        int cols = grid[0].length;
        Segment[] segs = new Segment[cols];
        Arrays.fill(segs, new Segment());

        int segmentId = 0;
        for (int c = 0; c < cols; ++c) {
            for (int r = 0; r < rows; ++r) {
                if (!grid[r][c]) continue;
                if (segs[c].id != -1) continue;

                int curId = segmentId++;
                segs[c].id = curId;
                segs[c].startRow = r;

                while (r < rows && grid[r][c]) {
                    segs[c].id = curId;
                    ++r;
                }
                segs[c].endRow = r - 1;
            }
        }

        List<Segment> result = new ArrayList<>();
        for (Segment seg : segs) {
            if (seg.id != -1) {
                result.add(new Segment(seg.id, seg.startRow, seg.endRow, 0, 0));
            }
        }
        return result.toArray(new Segment[0]);
    }

    private static int horizontalSegmentIndex(int row, int col, Segment[] segments) {
        for (Segment seg : segments) {
            if (isWithin(row, col, seg.row, seg.startCol, seg.endCol)) {
                return seg.id;
            }
        }
        return -1;
    }

    private static int verticalSegmentIndex(int row, int col, Segment[] segments) {
        for (Segment seg : segments) {
            if (isWithin(row, col, seg.col, seg.startRow, seg.endRow)) {
                return seg.id;
            }
        }
        return -1;
    }

    private static boolean isWithin(int row, int col, int fixed, int start, int end) {
        return fixed == row && col >= start && col <= end;
    }

    /* --------------------------------------------------------------
       FenwickTree (Binary Indexed Tree) implementation.
       -------------------------------------------------------------- */

    private static class FenwickTree {
        private final long[] tree; // 1‑based indexing, extra space for safety.
        private final int size;

        /** Creates a tree that can handle indices 0 … size‑1. */
        FenwickTree(int size) {
            this.size = size + 10; // small safety margin.
            this.tree = new long[this.size + 1];
        }

        /** Adds {@code value} to position {@code idx} (0‑based). */
        void add(int idx, long value) {
            int i = idx + 5; // the original offset (kept for compatibility).
            while (i <= size) {
                tree[i] += value;
                i += i & -i;
            }
        }

        /** Prefix sum of indices [0, idx] (inclusive). */
        long prefixSum(int idx) {
            int i = idx + 5;
            long res = 0;
            while (i >= 1) {
                res += tree[i];
                i -= i & -i;
            }
            return res;
        }

        /**
         * Adds {@code value} to every index in the inclusive range
         * {@code [from, to]}.  Internally performed with two point updates.
         */
        void rangeAdd(int from, int to, long value) {
            add(from, value);
            add(to + 1, -value);
        }
    }

    /* --------------------------------------------------------------
       Simple container for a candidate star.
       -------------------------------------------------------------- */

    private static final class StarInfo {
        final int row;          // 0‑based
        final int col;          // 0‑based
        final int minDist;      // distance to nearest border of its segment pair

        StarInfo(int row, int col, int minDist) {
            this.row = row;
            this.col = col;
            this.minDist = minDist;
        }
    }

    /* --------------------------------------------------------------
       Simple structure that stores a found segment (horizontal or vertical).
       -------------------------------------------------------------- */

    private static final class Segment {
        final int id;           // unique identifier for the segment
        final int startCol;     // for horizontal segments
        final int endCol;
        final int startRow;     // for vertical segments
        final int endRow;

        Segment() {
            this.id = -1;
            this.startCol = -1;
            this.endCol = -1;
            this.startRow = -1;
            this.endRow = -1;
        }

        Segment(int id, int startRow, int endRow, int startCol, int endCol) {
            this.id = id;
            this.startRow = startRow;
            this.endRow = endRow;
            this.startCol = startCol;
            this.endCol = endCol;
        }
    }

    /* --------------------------------------------------------------
       Main method – unchanged public signature for compatibility.
       -------------------------------------------------------------- */

    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in);
             PrintWriter out = new PrintWriter(System.out)) {
            new E1015().solve(scanner, out);
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Detects all maximal symmetric plus-shaped star patterns in a grid.
 * The algorithm scans every cell, finds the largest valid plus centered at that cell,
 * marks its cells as processed, and finally reports the found stars or –1 if any star
 * cell remains unprocessed.
 */
public class StarPatternFinder {

    /** Represents the centre and radius of a detected plus‑shaped star. */
    public static final class Star {
        public final int row;   // 1‑based row index
        public final int col;   // 1‑based column index
        public final int radius;// arm length minus one (as in original code)

        public Star(int row, int col, int radius) {
            this.row = row;
            this.col = col;
            this.radius = radius;
        }
    }

    /**
     * Simple fast scanner that reads tokens from {@code System.in}.
     */
    private static final class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner(InputStream in) {
            this.br = new BufferedReader(new InputStreamReader(in));
        }

        /** Ensures that a {@link StringTokenizer} is available; refills it when empty. */
        private void ensureTokenizer() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                String line = br.readLine();
                if (line == null) {
                    return;               // EOF
                }
                st = new StringTokenizer(line);
            }
        }

        /** Reads the next integer token. */
        public int nextInt() throws IOException {
            ensureTokenizer();
            return Integer.parseInt(st.nextToken());
        }

        /** Reads the next line (including possible spaces). */
        public String nextLine() throws IOException {
            ensureTokenizer();
            // The delimiter "\n" makes nextToken return the whole line without trimming.
            return st.nextToken("\n");
        }
    }

    /**
     * Encapsulates all processing related to detecting and marking stars.
     */
    private static final class StarProcessor {
        private final int rows;
        private final int cols;
        private final int[][] grid; // 0 = empty, 1 = original star, 2 = processed

        public StarProcessor(int rows, int cols, int[][] grid) {
            this.rows = rows;
            this.cols = cols;
            this.grid = grid;
        }

        /** Finds the largest symmetric plus centred at (row, col). */
        public Star findStar(int row, int col) {
            // Compute the length of the arm in each direction.
            int up    = armUp(row, col);
            int down  = armDown(row, col);
            int left  = armLeft(row, col);
            int right = armRight(row, col);

            int arm = Math.min(Math.min(up, down), Math.min(left, right));
            if (arm > 1) {
                // radius = arm - 1 matches the original implementation
                return new Star(row, col, arm - 1);
            }
            return null;
        }

        private int armUp(int row, int col) {
            int length = 0;
            for (int r = row; r >= 1; r--) {
                if (grid[r][col] == 0) break;
                length++;
            }
            return length;
        }

        private int armDown(int row, int col) {
            int length = 0;
            for (int r = row; r <= rows; r++) {
                if (grid[r][col] == 0) break;
                length++;
            }
            return length;
        }

        private int armLeft(int row, int col) {
            int length = 0;
            for (int c = col; c >= 1; c--) {
                if (grid[row][c] == 0) break;
                length++;
            }
            return length;
        }

        private int armRight(int row, int col) {
            int length = 0;
            for (int c = col; c <= cols; c++) {
                if (grid[row][c] == 0) break;
                length++;
            }
            return length;
        }

        /** Marks all cells belonging to the given star as processed (value 2). */
        public void mark(Star star) {
            int r = star.row;
            int c = star.col;
            int radius = star.radius;

            for (int i = 0; i <= radius; i++) {
                grid[r + i][c] = 2;               // down
                grid[r - i][c] = 2;               // up
                grid[r][c + i] = 2;               // right
                grid[r][c - i] = 2;               // left
            }
        }

        /** Checks whether any original star cells (value 1) are still unprocessed. */
        public boolean hasRemainingStars() {
            for (int i = 1; i <= rows; i++) {
                for (int j = 1; j <= cols; j++) {
                    if (grid[i][j] == 1) {
                        return true;
                    }
                }
            }
            return false;
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner sc = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(System.out);

        int n = sc.nextInt();   // number of rows (grid height)
        int m = sc.nextInt();   // number of columns (grid width)

        // Padded grid: extra border of zeros simplifies boundary checks.
        int[][] rawGrid = new int[n + 2][m + 2];

        // Fill the inner part with 1 for '*' and 0 otherwise.
        for (int i = 1; i <= n; i++) {
            String line = sc.nextLine().trim();
            for (int j = 1; j <= m; j++) {
                rawGrid[i][j] = (line.charAt(j - 1) == '*') ? 1 : 0;
            }
        }

        StarProcessor processor = new StarProcessor(n, m, rawGrid);
        List<Star> detectedStars = new ArrayList<>();

        // Examine each cell as a potential centre of a star.
        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= m; j++) {
                Star centre = processor.findStar(i, j);
                if (centre != null) {
                    processor.mark(centre);
                    detectedStars.add(centre);
                }
            }
        }

        // If any original star remains unprocessed, the pattern is invalid.
        if (processor.hasRemainingStars()) {
            out.println(-1);
        } else {
            out.println(detectedStars.size());
            for (Star s : detectedStars) {
                out.println(s.row + " " + s.col + " " + s.radius);
            }
        }

        out.close();
    }
}

import java.io.*;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.List;

/**
 * Solves the problem described in the original E1015 source.
 *
 * <p>Key improvements:
 * <ul>
 *   <li>Extracted responsibilities into dedicated methods.
 *   <li>Used meaningful names and constants instead of cryptic variables.
 *   <li>Removed dead code (unused swaps, helper methods, imports).
 *   <li>Wrapped command data in a small immutable class.
 *   <li>Added comments to clarify each step of the algorithm.
 * </ul>
 *
 * @author  (refactored by AI)
 */
public class E1015 {

    /** Directions used for traversing the grid. */
    private enum Direction {
        UP, DOWN, LEFT, RIGHT
    }

    /** Simple container for a star‑painting command. */
    private static final class Command {
        final int row;   // 1‑based output row
        final int col;   // 1‑based output column
        final int size;  // length of the painted segment (command size - 1 in output)

        Command(int row, int col, int size) {
            this.row = row;
            this.col = col;
            this.size = size;
        }

        @Override
        public String toString() {
            return row + " " + col + " " + (size - 1);
        }
    }

    /** Fast scanner that works with both files and standard input. */
    private static final class FastScanner {
        private final InputStream stream;
        private final byte[] buffer = new byte[1024];
        private int curPos = 0;
        private int curLen = 0;

        FastScanner(InputStream stream) {
            this.stream = stream;
        }

        private int readByte() throws IOException {
            if (curPos >= curLen) {
                curPos = 0;
                curLen = stream.read(buffer);
                if (curLen <= 0) {
                    return -1;
                }
            }
            return buffer[curPos++];
        }

        /** Skips whitespace characters. */
        private int skipWhite() throws IOException {
            int b;
            do {
                b = readByte();
            } while (!isSpaceChar(b));
            return b;
        }

        private static boolean isSpaceChar(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        public String next() throws IOException {
            int c = readByte();
            while (!isSpaceChar(c)) {
                c = readByte();
            }
            StringBuilder sb = new StringBuilder();
            do {
                sb.append((char) c);
                c = readByte();
            } while (!isSpaceChar(c));
            return sb.toString();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }

    /** Core logic of the solver. */
    private static final class Solver {
        private final FastScanner in;
        private final PrintWriter out;

        // Grid dimensions
        private int rows, cols;

        // Grid representation (true = '*', false = '.')
        private boolean[][] grid;

        // Maximum contiguous star length from each cell in each direction
        private int[][][] dirMaxLen;

        // Coverage map after commands are applied
        private boolean[][] covered;

        Solver(FastScanner in, PrintWriter out) {
            this.in = in;
            this.out = out;
        }

        /** Reads the whole test case and solves it. */
        void solve() throws IOException {
            readInput();
            computeMaximumRuns();
            collectCommands();
            if (!isFullyCovered()) {
                out.println(-1);
                return;
            }
            outputSolution();
        }

        /** Parses grid dimensions and the character matrix. */
        private void readInput() throws IOException {
            rows = in.nextInt();
            cols = in.nextInt();
            grid = new boolean[rows][cols];
            String line = in.next();               // next token consists of the whole first line of characters
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    grid[i][j] = line.charAt(j) == '*';
                }
                // Prepare next line for the next iteration (if any)
                if (i + 1 < rows) {
                    line = in.next();
                }
            }
        }

        /** Fills dirMaxLen[][][] with the longest contiguous stars in each direction. */
        private void computeMaximumRuns() {
            dirMaxLen = new int[4][rows][cols]; // 0=UP,1=DOWN,2=LEFT,3=RIGHT

            // Horizontal scans
            for (int r = 0; r < rows; r++) {
                processRowDirection(r, Direction.LEFT, Direction.RIGHT, dirMaxLen[2]);
                processRowDirection(r, Direction.RIGHT, Direction.LEFT, dirMaxLen[3]);
            }

            // Vertical scans
            for (int c = 0; c < cols; c++) {
                processColumnDirection(c, Direction.UP, Direction.DOWN, dirMaxLen[0]);
                processColumnDirection(c, Direction.DOWN, Direction.UP, dirMaxLen[1]);
            }
        }

        /** Helper: scans a row from start to end, filling lengths for the given direction. */
        private void processRowDirection(int row, Direction forward, Direction backward, int[][] target) {
            int p = forward == Direction.LEFT ? 0 : cols - 1;
            int q = p;
            while (p >= 0 && p < cols && !grid[row][p]) {
                p += forward == Direction.LEFT ? 1 : -1;
            }
            while (true) {
                while (q != p) {
                    q += forward == Direction.LEFT ? 1 : -1;
                }
                while (nextInSameRun(row, q, forward, backward)) {
                    q += forward == Direction.LEFT ? 1 : -1;
                }
                int runLen = Math.abs(q - p) + 1;
                // Fill the length for every cell belonging to the run
                int step = forward == Direction.LEFT ? 1 : -1;
                for (int idx = p; idx != q + step; idx += step) {
                    target[row][idx] = runLen;
                }
                if (!forwardScanningFurther(row, forward, backward)) {
                    break;
                }
                // Advance to the next run
                p = q;
                while (p >= 0 && p < cols && !grid[row][p]) {
                    p += forward == Direction.LEFT ? 1 : -1;
                }
            }
        }

        /** Helper: scans a column similarly. */
        private void processColumnDirection(int col, Direction forward, Direction backward, int[][] target) {
            int p = forward == Direction.UP ? 0 : rows - 1;
            int q = p;
            while (p >= 0 && p < rows && !grid[p][col]) {
                p += forward == Direction.UP ? 1 : -1;
            }
            while (true) {
                while (q != p) {
                    q += forward == Direction.UP ? 1 : -1;
                }
                while (nextInSameRunVertical(col, q, forward, backward)) {
                    q += forward == Direction.UP ? 1 : -1;
                }
                int runLen = Math.abs(q - p) + 1;
                int step = forward == Direction.UP ? 1 : -1;
                for (int idx = p; idx != q + step; idx += step) {
                    target[idx][col] = runLen;
                }
                if (!forwardScanningFurtherVertical(col, forward, backward)) {
                    break;
                }
                p = q;
                while (p >= 0 && p < rows && !grid[p][col]) {
                    p += forward == Direction.UP ? 1 : -1;
                }
            }
        }

        /** Returns true if there is at least one more star after the current position in the given direction. */
        private boolean nextInSameRun(int row, int col, Direction forward, Direction backward) {
            int next = forward == Direction.LEFT ? col + 1 : col - 1;
            return next >= 0 && next < cols && grid[row][next];
        }

        private boolean nextInSameRunVertical(int col, int row, Direction forward, Direction backward) {
            int next = forward == Direction.UP ? row + 1 : row - 1;
            return next >= 0 && next < rows && grid[next][col];
        }

        private boolean forwardScanningFurther(int row, Direction forward, Direction backward) {
            // Checks whether we can move forward from the current p to find the next possible run.
            // Simplified for readability – the original algorithm relied on a loop that always makes progress.
            return forward == Direction.LEFT ? row < rows : row >= 0;
        }

        private boolean forwardScanningFurtherVertical(int col, Direction forward, Direction backward) {
            return forward == Direction.UP ? col < rows : col >= 0;
        }

        /** Finds all valid star‑painting commands and stores them in a list. */
        private void collectCommands() {
            List<Command> commands = new ArrayList<>();

            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    // Minimum length among the four directions
                    int minLen = Integer.MAX_VALUE;
                    for (int d = 0; d < 4; d++) {
                        minLen = Math.min(minLen, dirMaxLen[d][r][c]);
                    }
                    // A command is only meaningful if the minimal length is at least 2
                    if (minLen >= 2) {
                        commands.add(new Command(r + 1, c + 1, minLen));
                        // Mark cells that would be painted by this command (directions are only illustrative)
                        markCommandCoverage(r, c, minLen, commands);
                    }
                }
            }

            // Store the found commands for later validation
            List<Command> foundCommands = commands;

            // Save them in a field so we can output later
            this.collectCommandsResult = foundCommands;
        }

        /** Marks cells covered by a given command in the four cardinal directions. */
        private void markCommandCoverage(int startRow, int startCol, int size, List<Command> commands) {
            // Directions: move outward size‑1 steps, filling the coverage grid.
            // This mirrors the original algorithm's attempt to paint cells.
            int[][] dr = {{-1,0},{1,0},{0,-1},{0,1}};
            for (int k = 0; k < size; k++) {
                for (int d = 0; d < 4; d++) {
                    int nr = startRow + dr[d][0] * k;
                    int nc = startCol + dr[d][1] * k;
                    if (inside(nr, nc)) {
                        covered[nr][nc] = true;
                    }
                }
            }
        }

        private boolean inside(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }

        /** Verifies that every '*' cell is covered by at least one command. */
        private boolean isFullyCovered() {
            covered = new boolean[rows][cols];
            for (Command cmd : collectCommandsResult) {
                // Re‑apply the same marking to build the coverage map
                markCommandCoverage(cmd.row - 1, cmd.col - 1, cmd.size, null);
            }
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (grid[r][c] && !covered[r][c]) {
                        return false;
                    }
                }
            }
            return true;
        }

        /** Outputs the number of commands followed by each command (1‑based coordinates). */
        private void outputSolution() {
            System.out.println(collectCommandsResult.size());
            for (Command cmd : collectCommandsResult) {
                System.out.println(cmd);
            }
        }

        // Temporary holder for the command list produced by collectCommands()
        private List<Command> collectCommandsResult;
    }

    /** Standard entry point. */
    public static void main(String[] args) throws Exception {
        try (FastScanner scanner = new FastScanner(System.in);
             PrintWriter printer = new PrintWriter(System.out)) {

            new Solver(scanner, printer).solve();
        }
    }
}

import java.io.IOException;
import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;

/**
 * Analyzes a grid of characters for plus‑shaped patterns of '*'
 * and outputs the coordinates of each centre together with the
 * length of its arms.
 */
public class StarPatternAnalyzer {

    private static final char STAR = '*';

    public static void main(String[] args) throws IOException {
        try (Scanner scanner = new Scanner(System.in)) {
            int rows = scanner.nextInt();
            int cols = scanner.nextInt();

            char[][] board = readBoard(scanner, rows);
            boolean[][] visited = new boolean[rows][cols];

            List<int[]> centres = findAllPlusCentres(board);
            List<String> resultLines = new ArrayList<>();

            for (int[] centre : centres) {
                int armLength = computeArmLength(board, centre[0], centre[1]);
                if (armLength > 0) {
                    // store result line: row col armLength
                    resultLines.add(
                            (centre[0] + 1) + " " + (centre[1] + 1) + " " + armLength);
                    markVisited(visited, centre[0], centre[1], armLength);
                }
            }

            // If any '*' was not visited → impossible configuration
            if (!allStarsCovered(board, visited)) {
                System.out.println(-1);
                return;
            }

            // Build final output
            StringBuilder output = new StringBuilder();
            output.append(centres.size()).append('\n');
            output.append(String.join("\n", resultLines));
            System.out.print(output);
        }
    }

    /** Reads the board from the scanner. */
    private static char[][] readBoard(Scanner scanner, int rows) {
        char[][] board = new char[rows][];
        for (int i = 0; i < rows; i++) {
            board[i] = scanner.next().toCharArray();
        }
        return board;
    }

    /** Returns a list of centre coordinates (row, col) that form a plus shape. */
    private static List<int[]> findAllPlusCentres(char[][] board) {
        List<int[]> centres = new ArrayList<>();
        int rows = board.length;
        int cols = board[0].length;

        for (int i = 1; i < rows - 1; i++) {
            for (int j = 1; j < cols - 1; j++) {
                if (isPlusShape(board, i, j)) {
                    centres.add(new int[]{i, j});
                }
            }
        }
        return centres;
    }

    /** Checks whether the 5‑cell pattern (centre + 4 neighbours) is a plus of '*'. */
    private static boolean isPlusShape(char[][] board, int i, int j) {
        return board[i][j] == STAR &&
                board[i - 1][j] == STAR &&
                board[i + 1][j] == STAR &&
                board[i][j - 1] == STAR &&
                board[i][j + 1] == STAR;
    }

    /** Determines the maximal length of the four arms of a plus centred at (i,j). */
    private static int computeArmLength(char[][] board, int i, int j) {
        int up = countContinuousStars(board, i, j, -1, 0);
        int down = countContinuousStars(board, i, j, 1, 0);
        int left = countContinuousStars(board, i, j, 0, -1);
        int right = countContinuousStars(board, i, j, 0, 1);
        return Math.min(Math.min(up, down), Math.min(left, right));
    }

    /** Counts consecutive '*' starting from (i,j) moving by (di,dj). */
    private static int countContinuousStars(char[][] board, int i, int j, int di, int dj) {
        int count = 0;
        int ni = i + di;
        int nj = j + dj;
        while (inside(board, ni, nj) && board[ni][nj] == STAR) {
            count++;
            ni += di;
            nj += dj;
        }
        return count;
    }

    /** Simple bounds check. */
    private static boolean inside(char[][] board, int i, int j) {
        return i >= 0 && i < board.length && j >= 0 && j < board[0].length;
    }

    /** Marks all cells belonging to the plus centred at (ci,cj) with the given arm length. */
    private static void markVisited(boolean[][] visited, int ci, int cj, int armLength) {
        for (int offset = 0; offset <= armLength; offset++) {
            setVisited(visited, ci + offset, cj);
            setVisited(visited, ci - offset, cj);
            setVisited(visited, ci, cj + offset);
            setVisited(visited, ci, cj - offset);
        }
    }

    /** Helper that sets a single cell to visited. */
    private static void setVisited(boolean[][] visited, int i, int j) {
        visited[i][j] = true;
    }

    /** Verifies that every '*' on the board has been visited by a plus centre. */
    private static boolean allStarsCovered(char[][] board, boolean[][] visited) {
        for (int i = 0; i < board.length; i++) {
            for (int j = 0; j < board[i].length; j++) {
                if (board[i][j] == STAR && !visited[i][j]) {
                    return false;
                }
            }
        }
        return true;
    }
}

import java.io.*;
import java.util.StringTokenizer;

/**
 * Solution for the “plus‑shapes” task.
 *
 * <p>The program reads an {@code n × m} grid. Each cell contains either '.' or another
 * character. If any cell contains the character '*', the program prints {@code -1}.
 * Otherwise it finds every maximal plus‑shaped pattern whose arms consist only of
 * non‑'.' characters and prints:
 *
 * <ul>
 *   <li>the number of pluses found, and
 *   <li>the centre (row, column) and the size of each plus, one per line.
 * </ul>
 *
 * <p>The refactor focuses on readability, encapsulation and maintainability:
 * <ul>
 *   <li>All mutable state is confined to local variables or small immutable objects.</li>
 *   <li>Magic numbers are replaced by clear constants.</li>
 *   <li>Logic is split into well‑named methods.</li>
 *   <li>Input handling is wrapped in a dedicated {@code InputReader}.</li>
 *   <li>Output is built with a {@code StringBuilder} and written once at the end.</li>
 * </ul>
 */
public final class Main {

    /** Character used to denote an empty cell. */
    private static final char EMPTY = '.';

    /** Marker used when a cell has been processed. */
    private static final char MARKED = 'n';

    /** Character that makes the whole test fail. */
    private static final char FAIL_CHAR = '*';

    /** Maximum possible size of a plus (bounded by the grid dimensions). */
    private static final int MAX_PLUS_SIZE = 500; // safe upper bound for the problem constraints

    /** Buffered reader for fast input. */
    private static final InputReader IN = new InputReader(System.in);

    /** Buffered writer for fast output. */
    private static final PrintWriter OUT = new PrintWriter(new BufferedOutputStream(System.out), true);

    /** Collects the output lines before they are printed. */
    private static final StringBuilder OUTPUT = new StringBuilder();

    /** Marks whether a '*' was encountered anywhere in the grid. */
    private static boolean failDetected = false;

    /** Simple container for a discovered plus. */
    private static final class Plus {
        final int row;   // 1‑based
        final int col;   // 1‑based
        final int size;  // arm length

        Plus(int row, int col, int size) {
            this.row = row;
            this.col = col;
            this.size = size;
        }

        @Override public String toString() {
            return row + " " + col + " " + size;
        }
    }

    /** Entry point. */
    public static void main(String[] args) throws IOException {
        int n = IN.nextInt();           // number of rows
        int m = IN.nextInt();           // number of columns
        char[][] grid = new char[n][];
        for (int i = 0; i < n; i++) {
            grid[i] = IN.next().toCharArray();
        }

        // 1️⃣  Detect an immediate failure condition.
        if (containsFailChar(grid)) {
            OUT.println(-1);
            return;
        }

        // 2️⃣  Scan the whole board looking for pluses.
        for (int r = 0; r < n; r++) {
            for (int c = 0; c < m; c++) {
                if (!isProcessed(grid, r, c)) {
                    Plus plus = findLargestPlus(grid, r, c);
                    if (plus != null) {
                        OUTPUT.append(plus).append('\n');
                        markProcessed(grid, plus);
                        count++; // keep track of how many pluses we discovered
                    }
                }
            }
        }

        // 3️⃣  Produce the final output.
        OUT.print(count);
        OUT.flush();               // ensure everything is flushed before the program ends
        System.out.println(OUTPUT);
    }

    /** Returns {@code true} if the grid contains the failure character '*'. */
    private static boolean containsFailChar(char[][] grid) {
        for (char[] row : grid) {
            for (char cell : row) {
                if (cell == FAIL_CHAR) {
                    failDetected = true;
                    return true;
                }
            }
        }
        return false;
    }

    /** Checks whether the cell has already been marked as processed. */
    private static boolean isProcessed(char[][] grid, int r, int c) {
        return grid[r][c] == MARKED;
    }

    /** Marks all cells belonging to a found plus as processed. */
    private static void markProcessed(char[][] grid, Plus plus) {
        int r = plus.row - 1;   // back to 0‑based
        int c = plus.col - 1;
        int s = plus.size;

        grid[r][c] = MARKED;                 // centre
        grid[r - s][c] = MARKED;             // up
        grid[r + s][c] = MARKED;             // down
        grid[r][c - s] = MARKED;             // left
        grid[r][c + s] = MARKED;             // right
    }

    /**
     * Finds the largest plus that can be centred at {@code (r,c)}.
     *
     * @return a {@link Plus} object describing the centre, arm length and size,
     *         or {@code null} if no plus exists at that position.
     */
    private static Plus findLargestPlus(char[][] grid, int r, int c) {
        int maxArm = Math.min(Math.min(r, n - 1 - r), Math.min(c, m - 1 - c));
        if (maxArm == 0) {
            return null; // cannot form any arm longer than zero
        }

        // Search from the largest possible arm down to 1.
        for (int size = maxArm; size >= 1; size--) {
            if (isValidPlusAt(grid, r, c, size)) {
                return new Plus(r + 1, c + 1, size); // convert to 1‑based indices
            }
        }
        return null; // no plus found at this cell
    }

    /**
     * Verifies that a plus of the given {@code size} centred at {@code (r,c)}
     * consists only of non‑'.' cells on its four arms.
     */
    private static boolean isValidPlusAt(char[][] grid, int r, int c, int size) {
        // Boundary check is already guaranteed by the caller.
        return grid[r][c] != EMPTY &&                     // centre
               grid[r - size][c] != EMPTY &&               // up
               grid[r + size][c] != EMPTY &&               // down
               grid[r][c - size] != EMPTY &&               // left
               grid[r][c + size] != EMPTY;                 // right
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;

/**
 * Reads a binary matrix, detects all “cross” patterns,
 * validates coverage and prints the minimal set of operations.
 *
 * The program follows clean‑code principles:
 *   • Meaningful naming
 *   • Small, single‑purpose methods
 *   • No unused imports or fields
 *   • Proper resource handling (try‑with‑resources)
 */
public class Main {

    /** Number of rows and columns of the input matrix. */
    private static int rows, cols;

    /** The binary matrix (1 = obstacle, 0 = free). */
    private static int[][] grid;

    /** Tracks cells that are already covered by a cross centre. */
    private static boolean[][] visited;

    /** Size of the maximal cross centred at each cell (0 = no centre). */
    private static int[][] crossSize;

    public static void main(String[] args) throws IOException {
        // Try‑with‑resources guarantees the reader is closed.
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in))) {
            solve(br);
        }
    }

    /** Entry point for the algorithm – parses, processes and outputs. */
    private static void solve(BufferedReader br) throws IOException {
        // 1️⃣  Parse header (rows, columns)
        String[] header = parseHeader(br);
        rows = Integer.parseInt(header[0]);
        cols = Integer.parseInt(header[1]);

        // 2️⃣  Allocate data structures
        grid      = new int[rows][cols];
        visited   = new boolean[rows][cols];
        crossSize = new int[rows][cols];

        // 3️⃣  Read the matrix representation
        readMatrix(br);

        // 4️⃣  Find every possible cross centre
        detectAllCrosses();

        // 5️⃣  Validate that every '1' cell is covered by at least one cross
        if (!isFullyCovered()) {
            System.out.println(-1);
            return;
        }

        // 6️⃣  Output number of operations and their positions/sizes
        int operationCount = countOperations();
        System.out.println(operationCount);
        printOperations();
    }

    /** Reads the first line of input and verifies it contains two integers. */
    private static String[] parseHeader(BufferedReader br) throws IOException {
        String line = br.readLine();
        if (line == null) {
            throw new IOException("Empty input");
        }
        String[] parts = line.trim().split("\\s+");
        if (parts.length < 2) {
            throw new IOException("Header must contain at least two numbers");
        }
        return parts;
    }

    /** Fills the `grid` array from subsequent input lines. */
    private static void readMatrix(BufferedReader br) throws IOException {
        for (int r = 0; r < rows; r++) {
            String rowStr = br.readLine();
            if (rowStr == null) {
                throw new IOException("Unexpected end of input while reading matrix");
            }
            for (int c = 0; c < cols; c++) {
                // '.' → free (0), any other char → obstacle (1)
                grid[r][c] = (rowStr.charAt(c) == '.') ? 0 : 1;
            }
        }
    }

    /** Detects maximal cross size for every cell that can be a centre. */
    private static void detectAllCrosses() {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                centreAt(r, c);
            }
        }
    }

    /** Computes the largest cross (if any) centred at (r, c). */
    private static void centreAt(int r, int c) {
        if (grid[r][c] != 1) {
            return;               // centre must be on an obstacle cell
        }

        int maxSize = 0;
        // Expand outward symmetrically while all four required cells are present
        for (int step = 1; ; step++) {
            int up   = r - step;
            int down = r + step;
            int left = c - step;
            int right = c + step;

            // Boundary check
            if (isOutOfBounds(up, c) || isOutOfBounds(down, c) ||
                isOutOfBounds(r, left) || isOutOfBounds(r, right)) {
                break;
            }

            // Verify the four neighbour cells are also obstacles
            if (grid[up][c] == 1 && grid[down][c] == 1 &&
                grid[r][left] == 1 && grid[r][right] == 1) {
                maxSize = step;

                // Mark all five cells as visited (they belong to some cross)
                visited[r][c]     = true;
                visited[up][c]    = true;
                visited[down][c]  = true;
                visited[r][left]  = true;
                visited[r][right] = true;
            } else {
                break;
            }
        }
        crossSize[r][c] = maxSize;
    }

    /** Returns true if the supplied coordinates lie outside the matrix. */
    private static boolean isOutOfBounds(int r, int c) {
        return r < 0 || r >= rows || c < 0 || c >= cols;
    }

    /** Checks that every obstacle cell has been visited by at least one cross. */
    private static boolean isFullyCovered() {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == 1 && !visited[r][c]) {
                    return false;
                }
            }
        }
        return true;
    }

    /** Counts cells that host a non‑zero cross (i.e., performed operations). */
    private static int countOperations() {
        int count = 0;
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (crossSize[r][c] > 0) {
                    count++;
                }
            }
        }
        return count;
    }

    /** Prints each operation: centre row, centre column, cross size. */
    private static void printOperations() {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (crossSize[r][c] > 0) {
                    // 1‑based output as required by the original specification
                    System.out.println((r + 1) + " " + (c + 1) + " " + crossSize[r][c]);
                }
            }
        }
    }
}

import java.io.*;
import java.util.*;

public class CFA {

    private static final long MOD = 1_000_000_007L;
    private static final String YES = "Yes";
    private static final String NO = "No";

    /** Buffered input & PrintWriter output */
    private final BufferedReader br;
    private final PrintWriter out;
    private StringTokenizer st;

    /** Entry point */
    public static void main(String[] args) throws IOException {
        new CFA();
    }

    /** Constructor – wires up the I/O and starts solving */
    public CFA() throws IOException {
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
        PrintWriter writer = new PrintWriter(System.out);
        try {
            solve(reader, writer);
        } finally {
            writer.close();
        }
    }

    /** Core algorithm */
    private void solve(BufferedReader reader, PrintWriter writer) throws IOException {
        this.br = new BufferedReader(new InputStreamReader(System.in));
        this.out = writer;
        st = new StringTokenizer(reader.readLine());

        int n = nextInt();               // number of rows
        int m = nextInt();               // number of columns
        char[][] grid = readCharMatrix(n);

        boolean[][] visited = new boolean[n][m];
        List<Operation> ops = new ArrayList<>();

        /* Process every '*' cell */
        for (int r = 0; r < n; r++) {
            for (int c = 0; c < m; c++) {
                if (grid[r][c] == '*') {
                    handleStar(r, c, grid, visited, ops);
                }
            }
        }

        /* If any '*' was never covered → impossible */
        if (!allStarsCovered(grid, visited)) {
            out.println(-1);
            return;
        }

        /* Output answer */
        out.println(ops.size());
        for (Operation op : ops) {
            out.printf("%d %d %d%n", op.row, op.col, op.size);
        }
    }

    /** Reads the whole matrix (n rows, each a string) */
    private char[][] readCharMatrix(int n) throws IOException {
        char[][] mat = new char[n][];
        for (int i = 0; i < n; i++) {
            String line = nextString();
            mat[i] = line.toCharArray();
        }
        return mat;
    }

    /** Analyzes a '*' cell, records an operation if a valid cross exists */
    private void handleStar(int r, int c, char[][] grid,
                            boolean[][] visited,
                            List<Operation> ops) {

        int up    = goUp(grid, r, c);
        int down  = goDown(grid, r, c);
        int left  = goLeft(grid, r, c);
        int right = goRight(grid, c);

        int maxArm = Math.min(Math.min(up, down), Math.min(left, right));
        if (maxArm <= 1) {
            return;                     // cross too small to be useful
        }

        int size = maxArm;               // arm length including centre
        ops.add(new Operation(r + 1, c + 1, size));

        /* Mark every cell belonging to this cross */
        for (int d = 0; d < size; d++) {
            visited[r + d][c] = true;   // down
            visited[r - d][c] = true;   // up
            visited[r][c + d] = true;   // right
            visited[r][c - d] = true;   // left
        }
    }

    /* ---------- Helper traversals ---------- */
    private int goUp(char[][] grid, int r, int c) {
        int cnt = 0;
        while (r - cnt - 1 >= 0 && grid[r - cnt - 1][c] == '*') {
            cnt++;
        }
        return cnt;
    }

    private int goDown(char[][] grid, int r, int c) {
        int cnt = 0;
        while (r + cnt + 1 < grid.length && grid[r + cnt + 1][c] == '*') {
            cnt++;
        }
        return cnt;
    }

    private int goLeft(char[][] grid, int r, int c) {
        int cnt = 0;
        while (c - cnt - 1 >= 0 && grid[r][c - cnt - 1] == '*') {
            cnt++;
        }
        return cnt;
    }

    private int goRight(char[][] grid, int r, int c) {
        int cnt = 0;
        while (c + cnt + 1 < grid[0].length && grid[r][c + cnt + 1] == '*') {
            cnt++;
        }
        return cnt;
    }

    /** Checks that every '*' has been visited by some operation */
    private boolean allStarsCovered(char[][] grid, boolean[][] visited) {
        for (int i = 0; i < grid.length; i++) {
            for (int j = 0; j < grid[i].length; j++) {
                if (grid[i][j] == '*' && !visited[i][j]) {
                    return false;
                }
            }
        }
        return true;
    }

    /** Simple DTO for an operation (1‑based coordinates) */
    private static final class Operation {
        final int row;   // 1‑based
        final int col;   // 1‑based
        final int size;  // total arm length including centre

        Operation(int row, int col, int size) {
            this.row = row;
            this.col = col;
            this.size = size;
        }
    }

    /* ---------- Fast I/O utilities ---------- */
    private BufferedReader getReader() {
        return br;
    }

    private PrintWriter getOut() {
        return out;
    }

    private String nextToken() {
        while (st == null || !st.hasMoreTokens()) {
            try {
                st = new StringTokenizer(getReader().readLine());
            } catch (IOException e) {
                throw new UncheckedIOException(e);
            }
        }
        return st.nextToken();
    }

    private String nextString() throws IOException {
        return getReader().readLine();
    }

    private int nextInt() throws IOException {
        return Integer.parseInt(nextToken());
    }

    private long nextLong() throws IOException {
        return Long.parseLong(nextToken());
    }
}

import java.io.*;
import java.util.*;

/**
 * Main class – solves the problem described in the original source.
 * The program reads a grid, detects “+”‑shaped crosses made of
 * asterisks, records their centres and radii and finally checks that
 * every empty cell ('.') is covered by at least one cross.
 */
public class Main {

    /* -------------------------------------------------------------
     *  Helper class that stores the four directional lengths for a cell.
     * ------------------------------------------------------------- */
    private static final class DirLengths {
        final int left;   // consecutive '*' to the left (including current)
        final int right;  // consecutive '*' to the right
        final int up;     // consecutive '*' upward
        final int down;   // consecutive '*' downward

        DirLengths(int left, int right, int up, int down) {
            this.left = left;
            this.right = right;
            this.up = up;
            this.down = down;
        }
    }

    /* -------------------------------------------------------------
     *  Fast input reader.
     * ------------------------------------------------------------- */
    private static final class FastReader {
        private final BufferedReader br;
        private StringTokenizer st;

        FastReader() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        /** Returns next token (String). */
        private String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    throw new UncheckedIOException(e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        long nextLong() {
            return Long.parseLong(next());
        }

        double nextDouble() {
            return Double.parseDouble(next());
        }

        String nextLine() {
            try {
                return br.readLine();
            } catch (IOException e) {
                throw new UncheckedIOException(e);
            }
        }
    }

    /* -------------------------------------------------------------
     *  Entry point.
     * ------------------------------------------------------------- */
    public static void main(String[] args) throws IOException {
        FastReader scanner = new FastReader();
        PrintWriter out = new PrintWriter(System.out);

        int testCases = 1;                     // the original code treats it as a loop until exhausted
        // -----------------------------------------------------------------
        // Main processing for each test case
        // -----------------------------------------------------------------
        while (testCases-- > 0) {
            solveOneTestCase(scanner, out);
        }

        out.close();
    }

    /**
     * Handles a single test case – reads the grid, computes the required
     * information, checks coverage and prints the answer.
     */
    private static void solveOneTestCase(FastReader scanner, PrintWriter out) {
        int n = scanner.nextInt();            // rows
        int m = scanner.nextInt();            // columns
        char[][] grid = new char[n + 2][m + 2]; // 1‑based indexing, border cells are sentinel '*'

        // -------------------------------------------------------------
        // 1. Read the grid, filling the border with a dummy character.
        // -------------------------------------------------------------
        for (int i = 1; i <= n; i++) {
            String line = scanner.nextLine().trim();
            for (int j = 1; j <= m; j++) {
                grid[i][j] = line.charAt(j - 1);
            }
        }

        // -------------------------------------------------------------
        // 2. Pre‑compute the four directional lengths for every cell.
        // -------------------------------------------------------------
        int[][] leftLen  = new int[n + 2][m + 2];
        int[][] rightLen = new int[n + 2][m + 2];
        int[][] upLen    = new int[n + 2][m + 2];
        int[][] downLen  = new int[n + 2][m + 2];

        computeHorizontalLengths(grid, leftLen, rightLen, upLen, downLen);
        computeVerticalLengths(grid, leftLen, rightLen, upLen, downLen);

        // -------------------------------------------------------------
        // 3. Find all possible cross centres.
        // -------------------------------------------------------------
        List<Cross> crosses = new ArrayList<>();
        boolean[][] covered = new boolean[n + 2][m + 2]; // sentinel borders stay false

        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= m; j++) {
                // Minimum of the four directions tells us the maximal radius.
                int radius = Math.min(
                        leftLen[i][j],
                        Math.min(rightLen[i][j], Math.min(upLen[i][j], downLen[i][j]))
                );

                if (radius > 1) {                     // a valid cross
                    Cross cross = new Cross(i, j, radius - 1);
                    crosses.add(cross);

                    // Mark all cells belonging to this cross as covered.
                    for (int d = 0; d <= radius; d++) {
                        covered[i - d][j] = true;          // up
                        covered[i + d][j] = true;          // down
                        covered[i][j - d] = true;          // left
                        covered[i][j + d] = true;          // right
                    }
                }
            }
        }

        // -------------------------------------------------------------
        // 4. Verify that every '.' cell is covered.
        // -------------------------------------------------------------
        boolean allCovered = true;
        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= m; j++) {
                if (grid[i][j] == '.' && !covered[i][j]) {
                    allCovered = false;
                    break;
                }
            }
            if (!allCovered) break;
        }

        if (!allCovered) {
            out.println("-1");
            return;
        }

        // -------------------------------------------------------------
        // 5. Output the list of crosses.
        // -------------------------------------------------------------
        out.println(crosses.size());
        for (Cross cross : crosses) {
            out.printf("%d %d %d%n", cross.row, cross.col, cross.radius);
        }
    }

    /**
     * Fills the provided matrices with the length of consecutive '*'
     * characters towards the left/right/up/down for each cell.
     */
    private static void computeHorizontalLengths(
            char[][] grid,
            int[][] left,
            int[][] right,
            int[][] /*unused*/ int[][] up,
            int[][] /*unused*/ int[][] down) {

        // left → process each row from left to right
        for (int i = 1; i < grid.length; i++) {
            for (int j = 1; j < grid[i].length; j++) {
                if (grid[i][j] == '*') {
                    left[i][j] = 1 + left[i][j - 1];
                } else {
                    left[i][j] = 0;
                }
            }
        }

        // right → process each row from right to left
        for (int i = 1; i < grid.length; i++) {
            for (int j = grid[i].length - 2; j >= 1; j--) {
                if (grid[i][j] == '*') {
                    right[i][j] = 1 + right[i][j + 1];
                } else {
                    right[i][j] = 0;
                }
            }
        }
    }

    /**
     * Same as {@link #computeHorizontalLengths} but fills the vertical
     * direction matrices (up / down).  They are stored in the same arrays
     * passed to the caller for convenience.
     */
    private static void computeVerticalLengths(
            char[][] grid,
            int[][] left,
            int[][] right,
            int[][] up,
            int[][] down) {

        // up → process each column from top to bottom
        for (int j = 1; j < grid[0].length; j++) {
            for (int i = 1; i < grid.length; i++) {
                if (grid[i][j] == '*') {
                    up[i][j] = 1 + up[i - 1][j];
                } else {
                    up[i][j] = 0;
                }
            }
        }

        // down → process each column from bottom to top
        for (int j = 1; j < grid[0].length; j++) {
            for (int i = grid.length - 2; i >= 1; i--) {
                if (grid[i][j] == '*') {
                    down[i][j] = 1 + down[i + 1][j];
                } else {
                    down[i][j] = 0;
                }
            }
        }
    }

    /** Simple holder for a detected cross. */
    private static final class Cross {
        final int row;      // centre row (1‑based)
        final int col;      // centre column (1‑based)
        final int radius;   // radius of the plus sign ( >=1 )

        Cross(int row, int col, int radius) {
            this.row = row;
            this.col = col;
            this.radius = radius;
        }
    }
}

import java.io.*;
import java.util.*;

public class Main {

    private static final long MOD = 1000000007L;

    public static void main(String[] args) {
        try (FastScanner sc = new FastScanner();
             PrintWriter out = new PrintWriter(System.out)) {

            int n = sc.nextInt();
            int m = sc.nextInt();
            boolean[][] occupied = readGrid(sc, n, m);

            // Per‑row and per‑column lookup structures
            RowColumnInfo[] rows = buildRowInfo(occupied);
            RowColumnInfo[] cols = buildColInfo(occupied);

            // BITs used to mark ranges covered by each star
            BinaryIndexedTree[] rowMarkers = new BinaryIndexedTree[n];
            BinaryIndexedTree[] colMarkers = new BinaryIndexedTree[m];
            for (int i = 0; i < n; i++) {
                rowMarkers[i] = new BinaryIndexedTree(m + 2);
            }
            for (int j = 0; j < m; j++) {
                colMarkers[j] = new BinaryIndexedTree(n + 2);
            }

            List<Star> stars = new ArrayList<>();

            // Scan every occupied cell and compute the maximal “size”
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    if (!occupied[i][j]) {
                        continue;
                    }

                    int rowIdx = rows[i].indexOf(j);
                    int colIdx = cols[j].indexOf(i);

                    int upSize = findMaxSize(rows[i].positions, rowIdx, true);
                    int downSize = findMaxSize(rows[i].positions, rowIdx, false);
                    int leftSize = findMaxSize(cols[j].positions, colIdx, true);
                    int rightSize = findMaxSize(cols[j].positions, colIdx, false);

                    int maxSize = Math.min(Math.min(upSize, downSize), Math.min(leftSize, rightSize));
                    if (maxSize > 0) {
                        Star star = new Star(i, j, maxSize);
                        stars.add(star);

                        // Mark the horizontal and vertical ranges covered by this star
                        markRange(rowMarkers[i], j - maxSize, j + maxSize + 1);
                        markRange(colMarkers[j], i - maxSize, i + maxSize + 1);
                    }
                }
            }

            // Verify that every occupied cell is covered by at least one star
            boolean good = true;
            for (int i = 0; i < n && good; i++) {
                for (int j = 0; j < m; j++) {
                    if (occupied[i][j]) {
                        if (rowMarkers[i].sum(j + 1) == 0 && colMarkers[j].sum(i + 1) == 0) {
                            good = false;
                            break;
                        }
                    }
                }
            }

            if (good) {
                out.println(stars.size());
                for (Star s : stars) {
                    out.println(s);
                }
            } else {
                out.println(-1);
            }

        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
    }

    /** Reads the grid from the scanner. */
    private static boolean[][] readGrid(FastScanner sc, int rows, int cols) {
        boolean[][] grid = new boolean[rows][cols];
        for (int i = 0; i < rows; i++) {
            String line = sc.next();
            for (int j = 0; j < cols; j++) {
                grid[i][j] = line.charAt(j) == '*';
            }
        }
        return grid;
    }

    /** Holds per‑row (or per‑column) mapping from a coordinate to its index in an ordered list. */
    private static final class RowColumnInfo {
        final List<Integer> positions;          // ordered list of occupied coordinates
        final Map<Integer, Integer> indexToPos; // coordinate -> position in the list

        RowColumnInfo() {
            positions = new ArrayList<>();
            indexToPos = new HashMap<>();
        }

        /** Returns the index of a coordinate inside the ordered list. */
        int indexOf(int coordinate) {
            return indexToPos.get(coordinate);
        }
    }

    /** Builds per‑row structures (row index → list of occupied column indices). */
    private static RowColumnInfo[] buildRowInfo(boolean[][] grid) {
        int n = grid.length;
        RowColumnInfo[] rows = new RowColumnInfo[n];
        for (int i = 0; i < n; i++) {
            rows[i] = new RowColumnInfo();
        }
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < grid[i].length; j++) {
                if (grid[i][j]) {
                    int pos = rows[i].positions.size();
                    rows[i].positions.add(j);
                    rows[i].indexToPos.put(j, pos);
                }
            }
        }
        return rows;
    }

    /** Builds per‑column structures (column index → list of occupied row indices). */
    private static RowColumnInfo[] buildColInfo(boolean[][] grid) {
        int m = grid[0].length;
        RowColumnInfo[] cols = new RowColumnInfo[m];
        for (int j = 0; j < m; j++) {
            cols[j] = new RowColumnInfo();
        }
        for (int j = 0; j < m; j++) {
            for (int i = 0; i < grid.length; i++) {
                if (grid[i][j]) {
                    int pos = cols[j].positions.size();
                    cols[j].positions.add(i);
                    cols[j].indexToPos.put(i, pos);
                }
            }
        }
        return cols;
    }

    /** Marks a range [from, to) in a BIT by adding delta at `from` and subtracting at `to`. */
    private static void markRange(BinaryIndexedTree bit, int from, int to) {
        bit.add(1, from);
        bit.add(-1, to);
    }

    /** Binary search that returns the maximal contiguous size to the given direction. */
    private static int findMaxSize(List<Integer> sorted, int idx, boolean upward) {
        int value = sorted.get(idx);
        if (upward) {
            int low = 0;
            int high = idx;
            while (low < high) {
                int mid = (low + high) >>> 1;
                if (sorted.get(mid) == value - (idx - mid)) {
                    high = mid;
                } else {
                    low = mid + 1;
                }
            }
            return idx - low;
        } else {
            int low = idx;
            int high = sorted.size() - 1;
            while (low < high) {
                int mid = (low + high + 1) >>> 1;
                if (sorted.get(mid) == value + (mid - idx)) {
                    low = mid;
                } else {
                    high = mid - 1;
                }
            }
            return low - idx;
        }
    }

    /** Simple data holder for a star (center cell and its “size”). */
    private static final class Star {
        final int row;
        final int col;
        final int size;

        Star(int row, int col, int size) {
            this.row = row;
            this.col = col;
            this.size = size;
        }

        @Override
        public String toString() {
            return (row + 1) + " " + (col + 1) + " " + size;
        }
    }

    /** Classic Fenwick tree (Binary Indexed Tree). */
    private static final class BinaryIndexedTree {
        private final int[] tree;

        BinaryIndexedTree(int capacity) {
            tree = new int[capacity];
        }

        /** Adds `delta` at the given 1‑based `index`. */
        void add(int delta, int index) {
            int i = index + 1;
            while (i < tree.length) {
                tree[i] += delta;
                i += i & -i;
            }
        }

        /** Returns the prefix sum up to (and including) `index`. */
        int sum(int index) {
            int total = 0;
            int i = index;
            while (i > 0) {
                total += tree[i];
                i -= i & -i;
            }
            return total;
        }
    }

    /** Fast scanner used throughout the program. */
    private static final class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner() throws IOException {
            this.br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                st = new StringTokenizer(readLine());
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        private String readLine() {
            try {
                return br.readLine();
            } catch (IOException e) {
                throw new UncheckedIOException(e);
            }
        }
    }
}

import java.io.*;
import java.util.*;
import java.util.stream.Collectors;

import static java.lang.Integer.min;

/**
 * Main class that reads a grid, discovers all stars placed on it and verifies that
 * the discovered stars exactly reproduce the original grid.
 * <p>
 * The implementation follows the original algorithm but is refactored for
 * readability, modularity and maintainability.
 */
public class Main {

    // -------------------------------------------------------------------------
    // Data structures
    // -------------------------------------------------------------------------

    /** A star centred at (row, col) with a given size. */
    private static final class Star {
        final int row;
        final int col;
        final int size;

        Star(int row, int col, int size) {
            this.row = row;
            this.col = col;
            this.size = size;
        }
    }

    /** Holds the number of consecutive '*' cells in the four cardinal directions
     *  from a particular cell (the cell itself is not counted). */
    private static final class CellCounts {
        int left;
        int right;
        int top;
        int bottom;
    }

    // -------------------------------------------------------------------------
    // I/O helpers (kept almost unchanged for compatibility)
    // -------------------------------------------------------------------------

    /** Fast scanner that works with {@link InputStream} or a file. */
    private static final class FastScanner {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        FastScanner(final InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
        }

        FastScanner(final File file) {
            try {
                reader = new BufferedReader(new FileReader(file));
            } catch (FileNotFoundException e) {
                throw new IllegalStateException(e);
            }
        }

        private void ensureTokens() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new UncheckedIOException(e);
                }
            }
        }

        int nextInt() {
            ensureTokens();
            return Integer.parseInt(tokenizer.nextToken());
        }

        String next() {
            ensureTokens();
            return tokenizer.nextToken();
        }
    }

    /** Fast output writer that accumulates data before flushing. */
    private static final class FastOutput {
        private final BufferedWriter writer;

        FastOutput(final OutputStream out) {
            writer = new BufferedWriter(new OutputStreamWriter(out));
        }

        void print(Object value) {
            try {
                writer.write(value.toString());
            } catch (IOException e) {
                throw new UncheckedIOException(e);
            }
        }

        void println(Object value) {
            print(value);
            print('\n');
        }

        void print(Object... values) {
            print(delimiter(values));
        }

        private static String delimiter(Object[] values) {
            return Arrays.stream(values)
                    .map(Object::toString)
                    .collect(Collectors.joining(" "));
        }

        void finish() {
            try {
                writer.flush();
                writer.close();
            } catch (IOException e) {
                throw new UncheckedIOException(e);
            }
        }
    }

    // -------------------------------------------------------------------------
    // Core algorithm
    // -------------------------------------------------------------------------

    public void run() {
        try (FastScanner in = new FastScanner();
             FastOutput out = new FastOutput()) {

            final int rows = in.nextInt();
            final int cols = in.nextInt();

            final boolean[][] grid = readGrid(in, rows, cols);
            final CellCounts[][] dirCounts = computeDirectionCounts(grid);
            final List<Star> stars = collectStars(grid, dirCounts);

            if (!validateCoverage(grid, stars)) {
                out.println(-1);
                return;
            }

            out.println(stars.size());
            stars.forEach(star -> out.print(star.row + 1, star.col + 1, star.size));
            out.finish();
        }
    }

    /** Reads the matrix of characters ('*' or '.') from the scanner. */
    private static boolean[][] readGrid(FastScanner in, int n, int m) {
        final boolean[][] grid = new boolean[n][m];
        for (int i = 0; i < n; i++) {
            final String line = in.next();
            for (int j = 0; j < m; j++) {
                grid[i][j] = line.charAt(j) == '*';
            }
        }
        return grid;
    }

    /** Computes for every cell the amount of consecutive '*' cells
     *  in the left, right, top and bottom directions. */
    private static CellCounts[][] computeDirectionCounts(boolean[][] grid) {
        final int n = grid.length;
        final int m = grid[0].length;
        final CellCounts[][] counts = new CellCounts[n][m];

        // Horizontal direction counts (left & right)
        for (int i = 0; i < n; i++) {
            fillHorizontal(row -> grid[i], i, counts);
        }

        // Vertical direction counts (top & bottom)
        for (int j = 0; j < m; j++) {
            fillVertical(grid, j, counts);
        }
        return counts;
    }

    /** Fills left & right counters for a given row. */
    private static void fillHorizontal(IntPredicate predicate, int rowIdx,
                                        CellCounts[][] counts) {
        boolean[] row = counts[rowIdx];
        int stars = 0;
        for (int col = 0; col < row.length; col++) {
            counts[rowIdx][col].left = stars;
            if (predicate.test(rowIdx, col)) {
                stars++;
            } else {
                stars = 0;
            }
        }

        stars = 0;
        for (int col = row.length - 1; col >= 0; col--) {
            counts[rowIdx][col].right = stars;
            if (predicate.test(rowIdx, col)) {
                stars++;
            } else {
                stars = 0;
            }
        }
    }

    /** Fills top & bottom counters for a given column. */
    private static void fillVertical(boolean[][] grid, int colIdx,
                                      CellCounts[][] counts) {
        int stars = 0;
        for (int row = 0; row < grid.length; row++) {
            counts[row][colIdx].top = stars;
            if (grid[row][colIdx]) {
                stars++;
            } else {
                stars = 0;
            }
        }
        stars = 0;
        for (int row = grid.length - 1; row >= 0; row--) {
            counts[row][colIdx].bottom = stars;
            if (grid[row][colIdx]) {
                stars++;
            } else {
                stars = 0;
            }
        }
    }

    /** Collects all stars that can be placed on the grid.
     *  The size of each star is the maximal possible value derived from the
     *  four direction counts. */
    private static List<Star> collectStars(boolean[][] grid,
                                            CellCounts[][] counts) {
        final List<Star> stars = new ArrayList<>();
        final int n = grid.length;
        final int m = grid[0].length;

        for (int i = 1; i < n - 1; i++) {
            for (int j = 1; j < m - 1; j++) {
                if (!grid[i][j]) {
                    continue;
                }
                final CellCounts c = counts[i][j];
                final int maxSize = min(min(c.bottom, c.top), min(c.left, c.right));
                if (maxSize < 1) {
                    continue;
                }
                stars.add(new Star(i, j, maxSize));
            }
        }
        return stars;
    }

    /** Verifies that the union of all discovered stars reproduces the original grid.
     *  The verification mimics the difference‑array sweep performed in the original code. */
    private static boolean validateCoverage(boolean[][] original,
                                              List<Star> stars) {
        final int n = original.length;
        final int m = original[0].length;

        final int[][] vert = new int[n][m];
        final int[][] goriz = new int[n][m];

        // Apply each star's effect using the difference‑array technique.
        for (Star star : stars) {
            final int i = star.row;
            final int j = star.col;
            final int l = star.size;

            vert[i - l][j]++;
            if (i + l + 1 < n) {
                vert[i + l + 1][j]--;
            }

            goriz[i][j - l]++;
            if (j + l + 1 < m) {
                goriz[i][j + l + 1]--;
            }
        }

        // Build prefix sums and compare with the original pattern.
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (i > 0) {
                    vert[i][j] += vert[i - 1][j];
                }
                if (j > 0) {
                    goriz[i][j] += goriz[i][j - 1];
                }
                boolean covered = vert[i][j] + goriz[i][j] > 0;
                if (covered != original[i][j]) {
                    return false;
                }
            }
        }
        return true;
    }

    // -------------------------------------------------------------------------
    // Entry point
    // -------------------------------------------------------------------------

    public static void main(String[] args) {
        new Main().run();
    }
}

import java.io.*;
import java.util.*;

public class Main {

    /* Directions: down, up, left, right */
    private static final int[][] DIRECTIONS = {
            {1, 0},
            {-1, 0},
            {0, -1},
            {0, 1}
    };

    /** Star information – 1‑based coordinates and ray length */
    private static final class Star {
        final int row;
        final int col;
        final int length;

        Star(int row, int col, int length) {
            this.row = row;
            this.col = col;
            this.length = length;
        }

        @Override
        public String toString() {
            return row + " " + col + " " + length;
        }
    }

    public static void main(String[] args) throws IOException {
        try (FastReader reader = new FastReader()) {
            int n = reader.nextInt();
            int m = reader.nextInt();
            char[][] grid = new char[n];
            for (int i = 0; i < n; i++) {
                grid[i] = reader.next().toCharArray();
            }

            List<Star> stars = analyse(grid);
            if (stars == null) {
                System.out.println(-1);
            } else {
                System.out.println(stars.size());
                for (Star s : stars) {
                    System.out.println(s);
                }
            }
        }
    }

    /** Returns the list of stars if the picture can be explained, otherwise {@code null}. */
    private static List<Star> analyse(char[][] grid) {
        int rows = grid.length;
        int cols = grid[0].length;
        int[][] coverage = new int[rows][cols];
        List<Star> result = new ArrayList<>();

        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '*') {
                    int maxLen = maxLegalLength(grid, r, c);
                    if (maxLen > 0) {
                        coverage[r][c]++;                     // centre is covered

                        // mark every ray cell (distance 1 … maxLen) in all four directions
                        for (int[] dir : DIRECTIONS) {
                            int len = maxLen;
                            while (len > 0) {
                                int nr = r + dir[0] * len;
                                int nc = c + dir[1] * len;
                                coverage[nr][nc]++;
                                len--;
                            }
                        }

                        result.add(new Star(r + 1, c + 1, maxLen));
                    }
                }
            }
        }

        // every '*' must have been covered at least once
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '*' && coverage[r][c] == 0) {
                    return null;          // impossible configuration
                }
            }
        }
        return result;
    }

    /** Finds the maximal length `l` such that all four directions contain '*' at distance `l`. */
    private static int maxLegalLength(char[][] grid, int r, int c) {
        int length = 0;
        while (true) {
            length++;
            boolean stillLegal = true;
            for (int[] d : DIRECTIONS) {
                int nr = r + d[0] * length;
                int nc = c + d[1] * length;
                if (!isInside(grid, nr, nc) || grid[nr][nc] != '*') {
                    stillLegal = false;
                    break;
                }
            }
            if (!stillLegal) {
                break;
            }
        }
        // the loop exits with length equal to the first illegal distance,
        // therefore the maximal legal length is length‑1.
        return length > 0 ? length - 1 : 0;
    }

    private static boolean isInside(char[][] grid, int x, int y) {
        return x >= 0 && x < grid.length && y >= 0 && y < grid[0].length;
    }

    /** Fast buffered reader – mirrors the original FastReader behaviour. */
    private static final class FastReader {
        private final BufferedReader br;
        private StringTokenizer st;

        FastReader() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        private String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    throw new UncheckedIOException(e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

/*
 *  Refactored version of the “Star drawing” program.
 *
 *  What the program does
 *  ----------------------
 *  * It reads an N × M grid that consists of '.' (already filled) and '*'
 *    (needs to be covered by a star).
 *  * A star is defined by a centre cell (r, c) and an integer length L.
 *    It consists of the centre cell and the cells
 *      (r ± i, c) and (r, c ± i)   for 1 ≤ i ≤ L.
 *  * The goal is to place stars so that every '*' cell becomes covered.
 *    If it is impossible the program prints –1, otherwise it prints the
 *    number of placed stars followed by each star in the form
 *        r+1 c+1 L
 *    (1‑based coordinates).
 *
 *  Why the original code was hard to maintain
 *  -----------------------------------------
 *  * Global mutable static fields were used everywhere.
 *  * The drawing logic was mixed with input/output handling.
 *  * Variable names were cryptic and the control flow was tangled.
 *  * No separation of concerns – reading the grid, computing stars,
 *    drawing them and validating the result were all interleaved.
 *
 *  What this refactor does
 *  ----------------------
 *  * Encapsulates a star as its own immutable value object.
 *  * Keeps all mutable state inside clearly‑named local variables.
 *  * Splits the algorithm into small, well‑named static methods.
 *  * Uses try‑with‑resources for automatically closing I/O streams.
 *  * Reads the whole input first, then processes it, and finally writes
 *    the result – no interleaving of concerns.
 *  * The code is now easier to test, reason about and extend.
 */

import java.io.PrintWriter;
import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;

public final class StarFieldSolver {

    /** Immutable representation of a placed star. */
    private static final class Star {
        private final int row;   // 0‑based row index of the centre
        private final int col;   // 0‑based column index of the centre
        private final int size;  // arm length (number of steps from centre)

        Star(int row, int col, int size) {
            this.row = row;
            this.col = col;
            this.size = size;
        }

        /** Returns the centre in 1‑based coordinates together with its size. */
        @Override
        public String toString() {
            return String.format("%d %d %d", row + 1, col + 1, size);
        }
    }

    /** Main entry point. */
    public static void main(String[] args) {
        // --------------------------------------------------------------------
        // 1️⃣  Input handling – everything is read before any processing.
        // --------------------------------------------------------------------
        try (Scanner scanner = new Scanner(System.in);
             PrintWriter out = new PrintWriter(System.out, true)) {

            int n = scanner.nextInt();          // number of rows
            int m = scanner.nextInt();          // number of columns
            scanner.nextLine();                 // consume end‑of‑line

            // Store the grid as an array of strings for fast random access.
            String[] grid = new String[n];
            for (int i = 0; i < n; i++) {
                grid[i] = scanner.nextLine();
            }

            // --------------------------------------------------------------------
            // 2️⃣  Prepare the “filled” matrix.
            //    true  → cell is already covered (originally '.' )
            //    false → cell still needs to be covered (originally '*')
            // --------------------------------------------------------------------
            boolean[][] filled = new boolean[n][m];
            for (int r = 0; r < n; r++) {
                for (int c = 0; c < m; c++) {
                    filled[r][c] = (grid[r].charAt(c) == '.');
                }
            }

            // --------------------------------------------------------------------
            // 3️⃣  Find all possible stars and place the biggest ones first.
            // --------------------------------------------------------------------
            List<Star> placedStars = new ArrayList<>();

            // Helper: compute the maximal arm length that can be drawn from (r,c)
            // without hitting a '.' or the border.
            java.util.function.BiFunction<Integer, Integer, Integer> maxStarLength =
                    (r, c) -> {
                        // maximum possible length limited by distance to borders
                        int maxPossible = Math.min(
                                Math.min(r, n - 1 - r),
                                Math.min(c, m - 1 - c));

                        int length = 0;
                        for (int step = 1; step <= maxPossible; step++) {
                            if (grid[r - step].charAt(c) == '*' &&
                                grid[r + step].charAt(c) == '*' &&
                                grid[r].charAt(c - step) == '*' &&
                                grid[r].charAt(c + step) == '*') {
                                length = step;
                            } else {
                                break; // as soon as one direction contains '.', stop
                            }
                        }
                        return length;
                    };

            // Iterate over every cell that is a '*' (i.e. not yet filled).
            // Process cells in descending order of potential size – this
            // reduces the number of placed stars and matches the original greedy
            // approach while keeping the code simple.
            for (int r = 1; r < n - 1; r++) {
                for (int c = 1; c < m - 1; c++) {
                    if (!filled[r][c]) { // only consider '*' cells
                        int size = maxStarLength.apply(r, c);
                        if (size > 0) {
                            // Record the star and mark all its cells as filled.
                            placedStars.add(new Star(r, c, size));
                            filled[r][c] = true; // centre
                            for (int step = 1; step <= size; step++) {
                                filled[r + step][c] = true;
                                filled[r - step][c] = true;
                                filled[r][c + step] = true;
                                filled[r][c - step] = true;
                            }
                        }
                    }
                }
            }

            // --------------------------------------------------------------------
            // 4️⃣  Validation – are all cells now filled?
            // --------------------------------------------------------------------
            boolean allCovered = true;
            for (int r = 0; r < n && allCovered; r++) {
                for (int c = 0; c < m && allCovered; c++) {
                    allCovered = filled[r][c];
                }
            }

            // --------------------------------------------------------------------
            // 5️⃣  Output – either the list of stars or –1.
            // --------------------------------------------------------------------
            if (allCovered) {
                out.println(placedStars.size());
                for (Star star : placedStars) {
                    out.println(star);
                }
            } else {
                out.println(-1);
            }

        } // ← resources (Scanner, PrintWriter) are closed automatically here
    }
}

import java.io.*;
import java.util.*;

public class B {

    /** Direction vectors: up, down, left, right */
    private static final class Direction {
        final int dx;
        final int dy;
        Direction(int dx, int dy) { this.dx = dx; this.dy = dy; }
    }

    private static final Direction[] DIRS = {
            new Direction(-1, 0), // up
            new Direction(1, 0),  // down
            new Direction(0, -1), // left
            new Direction(0, 1)   // right
    };

    /** Reads the dimensions and the grid from standard input. */
    private static char[][] readGrid(BufferedReader br, int n) throws IOException {
        char[][] grid = new char[n][];
        for (int i = 0; i < n; i++) {
            String line = br.readLine();
            grid[i] = line.toCharArray();          // exactly m characters are guaranteed
        }
        return grid;
    }

    /** Returns the maximal arm length (size) of a plus centred at (r, c). */
    private static int maximalArmLength(char[][] grid, int r, int c) {
        int maxSize = 0;
        int size = 1;
        while (true) {
            boolean ok = true;
            for (Direction d : DIRS) {
                int nr = r + size * d.dx;
                int nc = c + size * d.dy;
                if (nr < 0 || nr >= grid.length || nc < 0 || nc >= grid[0] || grid[nr][nc] == '.') {
                    ok = false;
                    break;
                }
            }
            if (!ok) {
                break;
            }
            maxSize = size;
            size++;
        }
        return maxSize;
    }

    /** Marks every cell that belongs to the plus of given size centred at (r, c). */
    private static void markCovered(boolean[][] covered, int r, int c, int size) {
        for (int k = 0; k <= size; k++) {
            for (Direction d : DIRS) {
                int nr = r + k * d.dx;
                int nc = c + k * d.dy;
                covered[nr][nc] = true;
            }
        }
    }

    public static void main(String[] args) throws Exception {
        // --------------------------------------------------------------
        // Input handling (try‑with‑resources guarantees proper closing)
        // --------------------------------------------------------------
        try (BufferedReader br = new BufferedReader(
                new InputStreamReader(System.in))) {

            // First line: n m
            String[] dims = br.readLine().split("\\s+");
            int n = Integer.parseInt(dims[0]);
            int m = Integer.parseInt(dims[1]);

            char[][] grid = readGrid(br, n);

            // --------------------------------------------------------------
            // Core algorithm
            // --------------------------------------------------------------
            boolean[][] covered = new boolean[n][m];
            List<String> resultLines = new ArrayList<>();
            int answer = 0;

            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    if (grid[i][j] == '.') {
                        continue;                     // nothing to do for empty cells
                    }

                    int arm = maximalArmLength(grid, i, j);
                    if (arm == 0) {
                        continue;                     // no plus can be formed here
                    }

                    answer++;
                    resultLines.add((i + 1) + " " + (j + 1) + " " + arm);
                    markCovered(covered, i, j, arm);
                }
            }

            // Verify that every '*' cell is covered by at least one plus
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    if (grid[i][j] == '*' && !covered[i][j]) {
                        System.out.println(-1);
                        return;
                    }
                }
            }

            // --------------------------------------------------------------
            // Output
            // --------------------------------------------------------------
            try (PrintWriter pw = new PrintWriter(System.out)) {
                pw.println(answer);
                for (String line : resultLines) {
                    pw.println(line);
                }
            }
        }
    }
}

import java.io.IOException;
import java.util.ArrayList;
import java.util.Arrays;

/**
 * Solution for CF1015E2 – “Most of the tests passed!”
 *
 * The program reads a grid made of '*' and '.' characters, computes the largest
 * plus‑sign that can be placed at each cell, verifies that every '*' belongs to
 * at least one plus of size > 1 and finally prints all such pluses.
 *
 * The implementation is deliberately broken into small, purpose‑focused methods,
 * uses clear naming, and avoids obscure tricks – making it far easier to
 * understand and maintain.
 */
public class Main {

    /** Entry point – delegates all work to {@link #run()}. */
    public static void main(String[] args) {
        new Main().run();
    }

    /** Orchestrates input reading, processing and output. */
    private void run() {
        FastScanner fs = new FastScanner();
        int n = fs.nextInt();               // number of rows
        int m = fs.nextInt();               // number of columns
        char[][] board = readBoard(fs, n, m);
        int minDim = Math.min(n, m);

        int[][] maxPlusLimit = computeMaximumPlusSize(board, n, m, minDim);
        if (!isBoardFullyCoveredByPluses(board, maxPlusLimit, n, m)) {
            System.out.println(-1);
            return;
        }

        List<Placement> placements = collectAllPlacements(maxPlusLimit, n, m);
        System.out.println(placements.size());
        for (Placement p : placements) {
            System.out.printf("%d %d %d%n", p.row + 1, p.col + 1, p.size);
        }
    }

    /** Reads the grid from {@link FastScanner}. */
    private static char[][] readBoard(FastScanner fs, int n, int m) {
        char[][] board = new char[n][];
        for (int i = 0; i < n; i++) {
            board[i] = fs.nextToken().toCharArray();
        }
        return board;
    }

    /**
     * Computes, for every cell, the maximal size of a plus sign that can be
     * centred there.  The returned matrix stores the *arm length* (+1 for the
     * centre).  Size 1 corresponds to a single star.
     */
    private static int[][] computeMaximumPlusSize(char[][] board,
                                                  int n,
                                                  int m,
                                                  int minDim) {
        int[][] limit = new int[n][m];
        // Initialise with the theoretical maximum possible size.
        for (int i = 0; i < n; i++) {
            Arrays.fill(limit[i], minDim);
        }

        // ---- Horizontal constraints -------------------------------------------------
        for (int i = 0; i < n; i++) {
            int streak = 0;
            // left → right
            for (int j = 0; j < m; j++) {
                streak = (board[i][j] == '*') ? streak + 1 : 0;
                limit[i][j] = Math.min(limit[i][j], streak);
            }
            // right → left
            streak = 0;
            for (int j = m - 1; j >= 0; j--) {
                streak = (board[i][j] == '*') ? streak + 1 : 0;
                limit[i][j] = Math.min(limit[i][j], streak);
            }
        }

        // ---- Vertical constraints ---------------------------------------------------
        for (int j = 0; j < m; j++) {
            int streak = 0;
            // top → bottom
            for (int i = 0; i < n; i++) {
                streak = (board[i][j] == '*') ? streak + 1 : 0;
                limit[i][j] = Math.min(limit[i][j], streak);
            }
            // bottom → top
            streak = 0;
            for (int i = n - 1; i >= 0; i--) {
                streak = (board[i][j] == '*') ? streak + 1 : 0;
                limit[i][j] = Math.min(limit[i][j], streak);
            }
        }

        // Ensure that every cell has at least size 1 (a single star is always valid).
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                limit[i][j] = Math.max(limit[i][j], 1);
            }
        }
        return limit;
    }

    /**
     * Determines whether every original '*' cell is covered by at least one
     * plus of size > 1 (i.e., arm length ≥ 1).  The method uses a difference array
     * to efficiently mark covered cells both row‑wise and column‑wise.
     *
     * @return {@code true} if the board can be completely represented by pluses,
     *         {@code false} otherwise.
     */
    private static boolean isBoardFullyCoveredByPluses(char[][] board,
                                                       int[][] limit,
                                                       int n,
                                                       int m) {
        // Row‑wise coverage marking
        int[] rowDiff = new int[m + 2];
        for (int i = 0; i < n; i++) {
            Arrays.fill(rowDiff, 0);
            for (int j = 0; j < m; j++) {
                int arm = limit[i][j] - 1;                // radius of the plus
                if (arm > 0) {
                    int left  = Math.max(0, j - arm + 1);
                    int right = Math.min(m, j + arm);    // exclusive upper bound
                    rowDiff[left]++;
                    rowDiff[right]--;
                }
            }
            // Apply the difference array and clear covered cells
            int cur = 0;
            for (int j = 0; j < m; j++) {
                cur += rowDiff[j];
                if (cur > 0) {
                    board[i][j] = '.';
                }
            }
        }

        // Column‑wise coverage marking (symmetrical to the row pass)
        int[] colDiff = new int[n + 2];
        for (int j = 0; j < m; j++) {
            Arrays.fill(colDiff, 0);
            for (int i = 0; i < n; i++) {
                int arm = limit[i][j] - 1;
                if (arm > 0) {
                    int top    = Math.max(0, i - arm + 1);
                    int bottom = Math.min(n, i + arm);
                    colDiff[top]++;
                    colDiff[bottom]--;
                }
            }
            int cur = 0;
            for (int i = 0; i < n; i++) {
                cur += colDiff[i];
                if (cur > 0) {
                    board[i][j] = '.';
                }
            }
        }

        // If any '*' remains uncovered, the board cannot be represented by pluses.
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (board[i][j] == '*') {
                    return false;
                }
            }
        }
        return true;
    }

    /** Simple holder for a plus‑sign placement (row, column, arm length). */
    private static final class Placement {
        final int row;   // 0‑based index
        final int col;   // 0‑based index
        final int size;  // arm length (radius)

        Placement(int row, int col, int size) {
            this.row = row;
            this.col = col;
            this.size = size;
        }
    }

    /** Collects all plus placements whose arm length is at least 1. */
    private static List<Placement> collectAllPlacements(int[][] limit,
                                                        int n,
                                                        int m) {
        List<Placement> result = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                int size = limit[i][j] - 1;   // arm length
                if (size > 0) {
                    result.add(new Placement(i, j, size));
                }
            }
        }
        return result;
    }

    /** Very small wrapper around {@link Scanner} for convenient token access. */
    private static final class FastScanner {
        private final Scanner sc = new Scanner(System.in);

        int nextInt() {
            return sc.nextInt();
        }

        String nextToken() {
            return sc.next();
        }
    }
}

/**
 * Refactored version of the original solution.
 *
 * <p>
 *   The program reads a grid that contains only '*' and '.'.
 *   It tries to cover every '*' with the arms of a plus‑shaped tile.
 *   For each possible centre (i, j) it expands as far as possible
 *   in the four diagonal directions and records the centre together
 *   with the length of the expansion (span).  If after processing
 *   every centre there remains an uncovered '*', the answer is –1.
 * </p>
 *
 * <p>Changes made for maintainability:</p>
 * <ul>
 *   <li>Extracted a small {@code FastScanner} to isolate input parsing.</li>
 *   <li>Replaced ad‑hoc static helper methods with clearly‑named functions.</li>
 *   <li>Renamed variables to reflect their purpose.</li>
 *   <li>Removed unused imports and dead code (e.g. {@code pow()} and modulo arithmetic).</li>
 *   <li>Wrapped related constants in a dedicated {@code Config} class.</li>
 *   <li>Added inline documentation and grouped logical blocks.</li>
 *   <li>Used {@code final} where possible to emphasize immutability.</li>
 *   <li>Improved readability of the main algorithm by extracting the
 *       “handle cell” logic into {@code tryExpandCell}.</li>
 * </ul>
 */
public final class Main {

    /** Configuration constants – keep them together for easy tuning. */
    private static final class Config {
        /** Maximum allowed grid dimension (200 005 as in the original code). */
        static final int MAX_N = 200_005;
        /** The input source – {@code System.in}. */
        static final java.io.BufferedReader IN = java.io.BufferedReader(
                new java.io.InputStreamReader(java.lang.System.in, java.nio.charset.StandardCharsets.UTF_8));
        /** The output destination – {@code System.out}. */
        static final java.io.PrintWriter OUT = new java.io.PrintWriter(java.lang.System.out);
    }

    /** Simple fast scanner that works with whitespace‑separated tokens. */
    private static final class FastScanner {
        private java.util.StringTokenizer tokenizer;

        /** @return {@code true} if another token is available. */
        boolean hasMoreTokens() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = Config.IN.readLine();
                    if (line == null) {
                        return false;
                    }
                    tokenizer = new java.util.StringTokenizer(line);
                } catch (java.io.IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return true;
        }

        /** @return next token as a {@code String}. */
        String nextToken() {
            return tokenizer.nextToken();
        }

        /** @param <T> type of the parsed value */
        T nextInt() {
            return (T) java.lang.Integer.valueOf(nextToken());
        }

        /** @param <T> type of the parsed value */
        T nextLong() {
            return (T) java.lang.Long.valueOf(nextToken());
        }
    }

    /** Directions in which we expand from a centre cell. */
    private enum ExpandDirection {
        UP_LEFT(-1, 0),
        DOWN_RIGHT(1, 0),
        LEFT(0, -1),
        RIGHT(0, 1);

        private final int deltaRow;
        private final int deltaCol;

        ExpandDirection(int dr, int dc) {
            this.deltaRow = dr;
            this.deltaCol = dc;
        }

        int deltaRow() { return deltaRow; }
        int deltaCol() { return deltaCol; }
    }

    /** Record of a plus‑shaped operation: centre row, centre column, span. */
    private static final class Operation {
        final int row;   // 1‑based
        final int col;   // 1-based
        final int span;  // number of steps we could expand

        Operation(int row, int col, int span) {
            this.row = row;
            this.col = col;
            this.span = span;
        }
    }

    /** Holds the grid and the visitation matrix while solving a test case. */
    private static final class Solver {
        private final char[][] grid;
        private final boolean[][] visited;
        private final java.util.List<Operation> operations = new java.util.ArrayList<>();

        Solver(char[][] grid, boolean[][] visited) {
            this.grid = grid;
            this.visited = visited;
        }

        /** Entry point for a single test case. */
        void solve(FastScanner scanner) {
            int rows = scanner.nextInt();
            int cols = scanner.nextInt();

            // read the grid row‑by‑row
            for (int r = 0; r < rows; r++) {
                grid[r] = scanner.nextToken().toCharArray();
            }

            // try to expand a plus from each '*' cell we encounter
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (grid[r][c] == '*') {
                        tryExpandCell(r, c, rows, cols);
                    }
                }
            }

            // verify that every '*' was visited at least once
            if (!allStarsCovered(rows, cols)) {
                Config.OUT.println(-1);
                return;
            }

            // output the found operations
            Config.OUT.println(operations.size());
            for (Operation op : operations) {
                Config.OUT.println(op.row + " " + op.col + " " + op.span);
            }
        }

        /** Attempts to grow a plus centred at (row, col) and records it if possible. */
        private void tryExpandCell(int startRow, int startCol, int rows, int cols) {
            int[][] offsets = {
                    {-1, 0},  // up
                    { 1, 0},  // down
                    { 0,-1},  // left
                    { 0, 1}   // right
            };

            // count how many steps we can extend in each direction
            int span = 0;
            boolean canExpand = true;

            // continue expanding while all four neighbours are still '*'
            while (canExpand) {
                int r1 = startRow - span;
                int r2 = startRow + span;
                int c3 = startCol - span;
                int c4 = startCol + span;

                // check the four diagonal neighbours
                if (!isStar(r1, startCol, rows, cols) ||
                    !isStar(r2, startCol, rows, cols) ||
                    !isStar(startRow, c3, rows, cols) ||
                    !isStar(startRow, c4, rows, cols)) {
                    break;
                }

                // mark visited cells (the centre itself is also considered)
                markVisited(startRow, startCol);
                markVisited(r1, startCol);
                markVisited(r2, startCol);
                markVisited(startRow, c3);
                markVisited(startRow, c4);

                span++;
            }

            // if we expanded at least one step, store the operation
            if (span > 0) {
                operations.add(new Operation(startRow + 1, startCol + 1, span));
            }
        }

        /** Marks a cell as visited and guards against out‑of‑bounds access. */
        private void markVisited(int r, int c) {
            if (r >= 0 && r < visited.length && c >= 0 && c < visited[0].length) {
                visited[r][c] = true;
            }
        }

        /** Returns {@code true} if the cell (r, c) contains a '*' and is inside the grid. */
        private boolean isStar(int r, int c, int rows, int cols) {
            return r >= 0 && r < rows && c >= 0 && c < cols && grid[r][c] == '*';
        }

        /** Checks whether every '*' cell has been visited. */
        private boolean allStarsCovered(int rows, int cols) {
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (grid[r][c] == '*' && !visited[r][c]) {
                        return false;
                    }
                }
            }
            return true;
        }
    }

    /** Solves a single test case. The outer driver reads the number of test cases. */
    private static void solveSingleTestCase(FastScanner scanner) {
        Solver solver = new Solver(new char[200_005][], new boolean[200_005][]);
        solver.solve(scanner);
    }

    /** Entry point – handles multiple test cases as in the original program. */
    public static void main(String[] args) {
        FastScanner scanner = new FastScanner();

        // The original code used “while (t-- > 0)”, i.e. exactly one test case.
        // Keeping the loop makes the refactor future‑proof if more cases are added.
        int testCases = 1;
        while (testCases-- > 0) {
            solveSingleTestCase(scanner);
        }

        Config.OUT.close();
    }
}

import java.io.*;
import java.util.*;

public class E {

    /* -------------------------------------------------
       Core algorithm
       ------------------------------------------------- */
    private static char[][] grid;          // input grid
    private static int rows, cols;         // dimensions
    private static final StringBuilder RESULT = new StringBuilder(); // output buffer

    public static void main(String[] args) throws Exception {
        readInput();
        processGrid();
        printResult();
    }

    /** Reads dimensions and the grid from standard input. */
    private static void readInput() throws IOException {
        rows = nextInt();
        cols = nextInt();
        grid = new char[rows][];
        for (int r = 0; r < rows; r++) {
            grid[r] = next().toCharArray();
        }
    }

    /** Main processing loop – finds all usable crosses. */
    private static void processGrid() {
        int answer = 0;

        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] != '*') {
                    continue;
                }

                int level = computeMaximumLevel(r, c);
                if (level == 0) {
                    continue;                 // isolated star – cannot be part of any cross
                }

                // store the move (1‑based coordinates required by the original problem)
                answer++;
                RESULT.append(r + 1)
                      .append(' ')
                      .append(c + 1)
                      .append(' ')
                      .append(level)
                      .append('\n');

                markCross(r, c, level);       // mark used cells
            }
        }

        // if any star is left untouched, the configuration is impossible
        if (anyStarRemaining()) {
            System.out.println(-1);
            System.exit(0);
        }

        System.out.println(answer);
        System.out.print(RESULT);
    }

    /** Returns the largest level such that a cross of that size fits completely
     *  inside the grid and every cell of the cross is either a '*' or already used ('#'). */
    private static int computeMaximumLevel(int centerR, int centerC) {
        int level = 0;
        while (true) {
            int next = level + 1;
            if (!isCrossOffsetValid(centerR, centerC, next)) {
                break;
            }
            level = next;
        }
        return level;
    }

    /** Checks whether the four cells at distance {@code offset} from (r,c) are inside
     *  the board and contain either '*' or '#'. */
    private static boolean isCrossOffsetValid(int r, int c, int offset) {
        // boundary test
        if (r - offset < 0 || r + offset >= rows || c - offset < 0 || c + offset >= cols) {
            return false;
        }
        // all four directions must be acceptable
        return acceptable(grid[r - offset][c]) &&
               acceptable(grid[r + offset][c]) &&
               acceptable(grid[r][c - offset]) &&
               acceptable(grid[r][c + offset]);
    }

    /** Helper that treats both '*' (still available) and '#' (already taken) as valid. */
    private static boolean acceptable(char ch) {
        return ch == '*' || ch == '#';
    }

    /** Marks all cells belonging to the selected cross with '#'. */
    private static void markCross(int centerR, int centerC, int level) {
        for (int d = 0; d <= level; d++) {
            grid[centerR - d][centerC] = '#';
            grid[centerR + d][centerC] = '#';
            grid[centerR][centerC - d] = '#';
            grid[centerR][centerC + d] = '#';
        }
    }

    /** Returns true if any '*' remains in the grid. */
    private static boolean anyStarRemaining() {
        for (char[] row : grid) {
            for (char cell : row) {
                if (cell == '*') {
                    return true;
                }
            }
        }
        return false;
    }

    /* -------------------------------------------------
       Input utilities (identical to the original scanner)
       ------------------------------------------------- */
    private static class Scanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public Scanner(InputStream source) {
            br = new BufferedReader(new InputStreamReader(source));
        }

        String next() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                st = new StringTokenizer(br.readLine());
            }
            return st.nextToken();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }

        long nextLong() throws IOException {
            return Long.parseLong(next());
        }

        String nextLine() throws IOException {
            return br.readLine();
        }

        double nextDouble() throws IOException {
            String x = next();
            StringBuilder sb = new StringBuilder("0");
            double res = 0, f = 1;
            boolean dec = false, neg = false;
            int start = 0;
            if (x.charAt(0) == '-') {
                neg = true;
                start++;
            }
            for (int i = start; i < x.length(); i++) {
                if (x.charAt(i) == '.') {
                    res = Long.parseLong(sb.toString());
                    sb = new StringBuilder("0");
                    dec = true;
                } else {
                    sb.append(x.charAt(i));
                    if (dec) {
                        f *= 10;
                    }
                }
            }
            res += Long.parseLong(sb.toString()) / f;
            return res * (neg ? -1 : 1);
        }

        boolean ready() throws IOException {
            return br.ready();
        }
    }

    /* -------------------------------------------------
       Miscellaneous helpers (preserved from original)
       ------------------------------------------------- */
    private static void shuffle(long[] a) {
        int n = a.length;
        for (int i = 0; i < n; i++) {
            int r = i + (int) (Math.random() * (n - i));
            long tmp = a[i];
            a[i] = a[r];
            a[r] = tmp;
        }
    }

    private static void shuffle(int[] a) {
        int n = a.length;
        for (int i = 0; i < n; i++) {
            int r = i + (int) (Math.random() * (n - i));
            int tmp = a[i];
            a[i] = a[r];
            a[r] = tmp;
        }
    }

    static class Pair {
        int a, b;
        Pair(int w, int h) {
            this.a = w;
            this.b = h;
        }
    }
}

