/**
 * Refactored version of the pattern‑finder program.
 * The code has been split into small, purpose‑focused methods,
 * uses meaningful names, avoids deep nesting and keeps all
 * mutable state confined to the `main` method where it belongs.
 *
 * The algorithmic behaviour is unchanged – it still:
 *   1. reads an n×m grid,
 *   2. computes how many consecutive '*' cells exist in the four
 *      orthogonal directions for every '*', 
 *   3. decides whether a star can be the centre of an arm pattern,
 *   4. draws all found patterns on a separate result grid,
 *   5. prints the number of patterns and their coordinates,
 *      or –1 if the result grid does not match the original one.
 */
import java.io.*;
import java.util.*;

public class RefactoredSolution {

    /** Symbol used for an empty cell. */
    private static final char EMPTY = '.';
    /** Symbol used for a star cell. */
    private static final char STAR = '*';

    public static void main(String[] args) throws IOException {
        List<String> inputLines = readAllLines(System.in);
        if (inputLines.isEmpty()) {
            return;
        }

        int n = integerFromFirstToken(inputLines.get(0));               // number of rows
        int m = integerFromSecondToken(inputLines.get(0));               // number of columns
        char[][] grid = buildCharGrid(inputLines.subList(1, n + 1));

        // ------------------------------------------------------------
        // 1️⃣ Compute arm‑lengths in the four orthogonal directions.
        // ------------------------------------------------------------
        int[][] up    = new int[n][m];
        int[][] down  = new int[n][m];
        int[][] left  = new int[n][m];
        int[][] right = new int[n][m];

        computeUpLengths(grid, up);
        computeDownLengths(grid, down);
        computeLeftLengths(grid, left);
        computeRightLengths(grid, right);

        // ------------------------------------------------------------
        // 2️⃣ Prepare the result grid and collect output information.
        // ------------------------------------------------------------
        char[][] result = new char[n][m];
        Arrays.fill(result, EMPTY);

        StringBuilder outputLines = new StringBuilder();
        int patternCount = 0;

        for (int r = 0; r < n; r++) {
            for (int c = 0; c < m; c++) {
                if (grid[r][c] != STAR) {
                    continue;
                }

                // Length of arm in each direction includes the centre cell.
                int armInUp    = up[r][c];
                int armInDown  = down[r][c];
                int armInLeft  = left[r][c];
                int armInRight = right[r][c];

                // Maximum radius that fits into *all* four directions.
                int radius = Math.min(
                        Math.min(armInUp, armInDown),
                        Math.min(armInLeft, armInRight)
                ) - 1;                      // subtract centre cell

                if (radius <= 0) {
                    continue;               // cannot form a valid pattern here
                }

                drawPattern(result, r, c, radius);
                patternCount++;
                outputLines.append(r + 1)
                           .append(' ')
                           .append(c + 1)
                           .append(' ')
                           .append(radius)
                           .append('\n');
            }
        }

        // ------------------------------------------------------------
        // 3️⃣ Verify that the drawn pattern reproduces the original grid.
        // ------------------------------------------------------------
        if (Arrays.deepEquals(grid, result)) {
            System.out.println(patternCount);
            System.out.print(outputLines);
        } else {
            System.out.println(-1);
        }
    }

    /* --------------------------------------------------------------------- */
    /*  Helper methods – each one does a single, well‑named job.             */
    /* --------------------------------------------------------------------- */

    /** Reads all non‑empty lines from the supplied input stream. */
    private static List<String> readAllLines(InputStream stream) throws IOException {
        List<String> lines = new ArrayList<>();
        try (BufferedReader br = new BufferedReader(new InputStreamReader(stream))) {
            String line;
            while ((line = br.readLine()) != null && !line.isBlank()) {
                lines.add(line);
            }
        }
        return lines;
    }

    /** Extracts the first integer token from a line (row count). */
    private static int integerFromFirstToken(String line) {
        return Integer.parseInt(line.trim().split("\\s+")[0]);
    }

    /** Extracts the second integer token from a line (column count). */
    private static int integerFromSecondToken(String line) {
        return Integer.parseInt(line.trim().split("\\s+")[1]);
    }

    /** Converts a list of strings into a char[][] grid. */
    private static char[][] buildCharGrid(Collection<String> rows) {
        int n = rows.size();
        char[][] grid = new char[n][];

        int idx = 0;
        for (String row : rows) {
            grid[idx++] = row.toCharArray();
        }
        return grid;
    }

    /* ---------- Direction‑specific length computations ------------------- */

    private static void computeUpLengths(char[][] grid, int[][] up) {
        int n = grid.length;
        int m = grid[0].length;
        for (int r = 0; r < n; r++) {
            for (int c = 0; c < m; c++) {
                if (grid[r][c] != STAR) {
                    up[r][c] = 0;
                } else if (r == 0) {
                    up[r][c] = 1;
                } else {
                    up[r][c] = up[r - 1][c] + 1;
                }
            }
        }
    }

    private static void computeDownLengths(char[][] grid, int[][] down) {
        int n = grid.length;
        int m = grid[0].length;
        for (int r = n - 1; r >= 0; r--) {
            for (int c = 0; c < m; c++) {
                if (grid[r][c] != STAR) {
                    down[r][c] = 0;
                } else if (r == n - 1) {
                    down[r][c] = 1;
                } else {
                    down[r][c] = down[r + 1][c] + 1;
                }
            }
        }
    }

    private static void computeLeftLengths(char[][] grid, int[][] left) {
        int n = grid.length;
        int m = grid[0].length;
        for (int r = 0; r < n; r++) {
            for (int c = 0; c < m; c++) {
                if (grid[r][c] != STAR) {
                    left[r][c] = 0;
                } else if (c == 0) {
                    left[r][c] = 1;
                } else {
                    left[r][c] = left[r][c - 1] + 1;
                }
            }
        }
    }

    private static void computeRightLengths(char[][] grid, int[][] right) {
        int n = grid.length;
        int m = grid[0].length;
        for (int r = 0; r < n; r++) {
            for (int c = m - 1; c >= 0; c--) {
                if (grid[r][c] != STAR) {
                    right[r][c] = 0;
                } else if (c == m - 1) {
                    right[r][c] = 1;
                } else {
                    right[r][c] = right[r][c + 1] + 1;
                }
            }
        }
    }

    /** Marks all cells belonging to an arm pattern centred at (row, col) with radius `r`. */
    private static void drawPattern(char[][] target, int row, int col, int radius) {
        target[row][col] = STAR;
        for (int i = 1; i <= radius; i++) {
            target[row + i][col] = STAR;
            target[row - i][col] = STAR;
            target[row][col + i] = STAR;
            target[row][col - i] = STAR;
        }
    }
}

import java.io.*;
import java.util.*;

public class Main {

    /* --------------------------------------------------------------
     *  Fast scanner – handles tokenisation with try‑with‑resources.
     * -------------------------------------------------------------- */
    private static final class FastScanner {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        FastScanner() {
            this.reader = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new UncheckedIOException(e);
                }
            }
            return tokenizer.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }
    }

    /* --------------------------------------------------------------
     *  Information about a detected plus sign.
     * -------------------------------------------------------------- */
    private static final class PlusInfo {
        final int row;      // 0‑based centre row
        final int col;      // 0‑based centre column
        final int armLen;   // length of one arm (>=1)

        PlusInfo(int row, int col, int armLen) {
            this.row = row;
            this.col = col;
            this.armLen = armLen;
        }
    }

    public static void main(String[] args) throws IOException {
        FastScanner fs = new FastScanner();
        PrintWriter out = new PrintWriter(System.out, true);

        /* ---------------------------- Input ---------------------------- */
        int n = fs.nextInt();                 // rows
        int m = fs.nextInt();                 // columns
        char[][] grid = new char[n][];
        for (int i = 0; i < n; i++) {
            grid[i] = fs.next().toCharArray();
        }

        /* -------------------------- Initialise ----------------------- */
        char[][] result = new char[n][];
        for (int i = 0; i < n; i++) {
            result[i] = new char[m];
            Arrays.fill(result[i], '.');
        }

        List<PlusInfo> pluses = new ArrayList<>();

        /* ---------------------- Detect pluses ---------------------- */
        for (int r = 1; r < n - 1; r++) {
            for (int c = 1; c < m - 1; c++) {
                if (grid[r][c] != '*') {
                    continue;               // centre must be '*'
                }
                int arm = 1;
                while (canFit(r, c, arm, n, m)) {
                    if (grid[r - arm][c] == '*' &&
                        grid[r + arm][c] == '*' &&
                        grid[r][c - arm] == '*' &&
                        grid[r][c + arm] == '*') {
                        markArms(result, r, c, arm);
                        arm++;
                    } else {
                        break;
                    }
                }
                if (arm > 1) {
                    pluses.add(new PlusInfo(r, c, arm - 1));
                }
            }
        }

        /* ------------------- Validate coverage ------------------- */
        if (!gridFullyCovered(grid, result)) {
            out.println(-1);
            out.flush();
            out.close();
            return;
        }

        /* ---------------------- Output answer ---------------------- */
        out.println(pluses.size());
        StringBuilder sb = new StringBuilder();
        for (PlusInfo p : pluses) {
            sb.append(p.row + 1)          // convert to 1‑based
              .append(' ')
              .append(p.col + 1)
              .append(' ')
              .append(p.armLen)           // arm length as required
              .append('\n');
        }
        out.print(sb);
        out.flush();
    }

    /* --------------------------------------------------------------
     *  Helper: can the plus with the given arm length fit inside the grid?
     * -------------------------------------------------------------- */
    private static boolean canFit(int centreR, int centreC, int armLen,
                                 int rows, int cols) {
        return centreR - armLen >= 0 && centreR + armLen < rows &&
               centreC - armLen >= 0 && centreC + armLen < cols;
    }

    /* --------------------------------------------------------------
     *  Helper: mark the arms of a plus on the result grid.
     * -------------------------------------------------------------- */
    private static void markArms(char[][] out, int centreR, int centreC,
                                int armLen) {
        out[centreR][centreC] = '*';
        out[centreR - armLen][centreC] = '*';
        out[centreR + armLen][centreC] = '*';
        out[centreR][centreC - armLen] = '*';
        out[centreR][centreC + armLen] = '*';
    }

    /* --------------------------------------------------------------
     *  Helper: verify that every '*' in the original grid is present
     *  in the result grid (i.e., no extra or missing symbols).
     * -------------------------------------------------------------- */
    private static boolean gridFullyCovered(char[][] source, char[][] target) {
        for (int i = 0; i < source.length; i++) {
            for (int j = 0; j < source[i].length; j++) {
                if (source[i][j] != target[i][j]) {
                    return false;
                }
            }
        }
        return true;
    }
}

import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;

/**
 * Reads a grid of characters, extracts the maximal non‑overlapping stars,
 * and prints either the list of stars or -1 if the grid cannot be fully
 * cleared.
 *
 * A star is defined by a centre (row, col) and a radius.  All four arms of
 * length {@code radius} must consist solely of '*' cells before the star is
 * recorded.
 */
public class StarsDrawingEasy {

    /** Character used to mark cells that have already been processed. */
    private static final char MARKER = 'X';

    /** Symbol that represents an untouched star cell. */
    private static final char STAR = '*';

    /** Information about a discovered star. */
    private static final class StarInfo {
        final int row;
        final int col;
        final int radius;

        StarInfo(int row, int col, int radius) {
            this.row = row;
            this.col = col;
            this.radius = radius;
        }

        @Override
        public String toString() {
            return row + " " + col + " " + radius;
        }
    }

    /** Entrypoint of the program. */
    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            int n = scanner.nextInt();   // number of rows
            int m = scanner.nextInt();   // number of columns

            char[][] grid = readGrid(scanner, n, m);
            List<StarInfo> result = solve(grid);

            if (result == null) {
                System.out.println(-1);
            } else {
                System.out.println(result.size());
                result.forEach(System.out::println);
            }
        }
    }

    /** Builds the initial grid from the scanner input. */
    private static char[][] readGrid(Scanner scanner, int n, int m) {
        char[][] grid = new char[n + 1][m + 1];
        for (int i = 1; i <= n; i++) {
            String line = scanner.next();
            grid[i] = (" " + line).toCharArray(); // 1‑based indexing
        }
        return grid;
    }

    /**
     * Main solving routine.
     *
     * @return list of {@link StarInfo} when the whole grid can be cleared,
     *         {@code null} otherwise.
     */
    private static List<StarInfo> solve(char[][] grid) {
        List<StarInfo> collectedStars = new ArrayList<>();

        for (int i = 1; i < grid.length; i++) {
            for (int j = 1; j < grid[0].length; j++) {
                // only untouched '*' cells (or already processed cells marked with MARKER) are considered
                if (grid[i][j] != STAR && grid[i][j] != MARKER) {
                    continue;
                }

                int maxPossibleRadius = getMaxRadius(grid, i, j);

                // try the largest radius first
                for (int rad = maxPossibleRadius; rad >= 1; rad--) {
                    if (isPossible(grid, i, j, rad)) {
                        StarInfo star = new StarInfo(i, j, rad);
                        collectedStars.add(star);
                        placeStar(grid, i, j, rad);
                        break; // a star is placed, move to next centre cell
                    }
                }
            }
        }

        return valid(grid) ? collectedStars : null;
    }

    /** Calculates the maximal geometric radius a star centred at (x, y) could have. */
    private static int getMaxRadius(char[][] grid, int x, int y) {
        int up    = x - 1;
        int down  = grid.length - 1 - x;
        int left  = y - 1;
        int right = grid[0].length - 1 - y;
        return Math.min(Math.min(up, down), Math.min(left, right));
    }

    /** Checks whether a star of given radius can be placed centred at (x, y). */
    private static boolean isPossible(char[][] grid, int x, int y, int radius) {
        return checkArm(grid, x, y,  1,  0, radius) &&
               checkArm(grid, x, y, -1,  0, radius) &&
               checkArm(grid, x, y,  0,  1, radius) &&
               checkArm(grid, x, y,  0, -1, radius);
    }

    /** Verifies that a single arm of length {@code radius} contains only '*' or MARKER. */
    private static boolean checkArm(char[][] grid, int x, int y,
                                    int dx, int dy, int radius) {
        for (int step = 1; step <= radius; step++) {
            int nx = x + step * dx;
            int ny = y + step * dy;
            char cell = grid[nx][ny];
            if (cell != MARKER && cell != STAR) {
                return false;
            }
        }
        return true;
    }

    /** Places a star (marks centre and all four arms) using the MARKER character. */
    private static void placeStar(char[][] grid, int x, int y, int radius) {
        grid[x][y] = MARKER;
        placeArm(grid, x, y,  1,  0, radius);
        placeArm(grid, x, y, -1,  0, radius);
        placeArm(grid, x, y,  0,  1, radius);
        placeArm(grid, x, y,  0, -1, radius);
    }

    /** Helper that marks cells along a single direction. */
    private static void placeArm(char[][] grid, int x, int y,
                                 int dx, int dy, int radius) {
        for (int step = 1; step <= radius; step++) {
            int nx = x + step * dx;
            int ny = y + step * dy;
            grid[nx][ny] = MARKER;
        }
    }

    /** Returns true only if no '*' characters remain in the grid. */
    private static boolean valid(char[][] grid) {
        for (char[] row : grid) {
            for (char cell : row) {
                if (cell == STAR) {
                    return false;
                }
            }
        }
        return true;
    }
}

import java.io.PrintWriter;
import java.util.Scanner;

/**
 * Reads a grid, detects all “star” patterns and prints the required output.
 *
 * <p>The program follows the same logic as the original implementation but
 * improves readability, maintainability and testability by:
 * <ul>
 *   <li>Separating concerns into small, pure methods.</li>
 *   <li>Eliminating static mutable fields.</li>
 *   <li>Using expressive names instead of cryptic ones.</li>
 *   <li>Adding helpful comments.</li>
 * </ul>
 */
public class StarsDrawing {

    /** Directions used to walk from a centre star. */
    private static final int[] DX = { -1, 0, 1, 0 };
    private static final int[] DY = { 0, -1, 0, 1 };

    /** Size of the grid. */
    private final int rows;
    /** Size of the grid. */
    private final int cols;
    /** Grid of characters read from input. */
    private final char[][] grid;

    /** Counters used while processing. */
    private int patternCount;
    /** Accumulator for the result lines. */
    private final StringBuilder result;

    /**
     * Entry point.
     *
     * @param sc a {@link Scanner} that supplies the input.
     * @param pw a {@link PrintWriter} used for output.
     */
    public static void solve(Scanner sc, PrintWriter pw) {
        new StarsDrawing(sc).run(pw);
    }

    /** Constructs the solver with the supplied scanner. */
    private StarsDrawing(Scanner sc) {
        this.rows = sc.nextInt();
        this.cols = sc.nextInt();
        this.grid = new char[rows][];
        for (int i = 0; i < rows; i++) {
            grid[i] = sc.next().toCharArray();
        }
        this.patternCount = 0;
        this.result = new StringBuilder();
    }

    /** Executes the whole algorithm and writes the answer. */
    private void run(PrintWriter pw) {
        detectAndMarkPatterns();

        // If any original '*' remained, the input was inconsistent.
        if (hasUnmarkedStar() || patternCount == 0) {
            pw.println(-1);
        } else {
            pw.println(patternCount);
            pw.print(result);
        }
    }

    /** Detects every centre of a star and marks the whole pattern. */
    private void detectAndMarkPatterns() {
        int[][] up = computeConsecutive(grid, 1, 0);   // upwards
        int[][] down = computeConsecutive(grid, -1, 0); // downwards
        int[][] left = computeConsecutive(grid, 0, -1); // leftwards
        int[][] right = computeConsecutive(grid, 0, 1); // rightwards

        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] != '*') {
                    continue;
                }

                int[] lengths = {
                        up[r][c], down[r][c], left[r][c], right[r][c]
                };
                int minLength = min(lengths);

                if (minLength > 0) {
                    patternCount++;
                    markPattern(r, c, minLength);
                    result.append(r + 1)
                          .append(' ')
                          .append(c + 1)
                          .append(' ')
                          .append(minLength)
                          .append('\n');
                }
            }
        }
    }

    /** Returns the smallest non‑zero value among the supplied array or 0. */
    private static int min(int[] arr) {
        int min = arr[0];
        for (int v : arr) {
            if (v < min) {
                min = v;
            }
        }
        return Math.max(min, 0);
    }

    /**
     * Computes, for each cell, how many consecutive '*' appear in the given direction.
     *
     * @param source   the original grid.
     * @param dRow     row step of the direction.
     * @param dCol     column step of the direction.
     * @return a 2‑D array of distances.
     */
    private static int[][] computeConsecutive(char[][] source, int dRow, int dCol) {
        int rows = source.length;
        int cols = source[0].length;
        int[][] dist = new int[rows][cols];

        if (dRow == 1) { // scanning downwards
            for (int c = 0; c < cols; c++) {
                dist[0][c] = (source[0][c] == '*') ? 1 : 0;
                for (int r = 1; r < rows; r++) {
                    dist[r][c] = (source[r][c] == '*')
                            ? 1 + dist[r - 1][c]
                            : 0;
                }
            }
        } else if (dRow == -1) { // scanning upwards
            for (int c = 0; c < cols; c++) {
                dist[rows - 1][c] = (source[rows - 1][c] == '*') ? 1 : 0;
                for (int r = rows - 2; r >= 0; r--) {
                    dist[r][c] = (source[r][c] == '*')
                            ? 1 + dist[r + 1][c]
                            : 0;
                }
            }
        } else if (dCol == -1) { // scanning leftwards
            for (int r = 0; r < rows; r++) {
                dist[r][0] = (source[r][0] == '*') ? 1 : 0;
                for (int c = 1; c < cols; c++) {
                    dist[r][c] = (source[r][c] == '*')
                            ? 1 + dist[r][c - 1]
                            : 0;
                }
            }
        } else { // scanning rightwards
            for (int r = 0; r < rows; r++) {
                dist[r][cols - 1] = (source[r][cols - 1] == '*') ? 1 : 0;
                for (int c = cols - 2; c >= 0; c--) {
                    dist[r][c] = (source[r][c] == '*')
                            ? 1 + dist[r][c + 1]
                            : 0;
                }
            }
        }

        return dist;
    }

    /** Marks all cells belonging to the star centred at (row, col) with length {@code len}. */
    private void markPattern(int row, int col, int len) {
        // Mark the centre cell first.
        grid[row][col] = '#';

        // Walk in each of the four directions.
        for (int step = 1; step <= len; step++) {
            grid[row + step][col] = '#';
            grid[row - step][col] = '#';
            grid[row][col + step] = '#';
            grid[row][col - step] = '#';
        }
    }

    /** Checks whether any original '*' character was left unmarked. */
    private boolean hasUnmarkedStar() {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '*') {
                    return true;
                }
            }
        }
        return false;
    }

    /* --------------------------------------------------------------------- *
     *  Main method – only a thin wrapper that complies with the original   *
     *  entry‑point. The real work is delegated to {@link #solve(Scanner,PrintWriter)} *
     *  --------------------------------------------------------------------- */
    public static void main(String[] args) throws Exception {
        try (Scanner sc = new Scanner(System.in);
             PrintWriter pw = new PrintWriter(System.out)) {
            solve(sc, pw);
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Refactored version of the original program.
 *
 * <p>Key improvements:
 * <ul>
 *   <li>Clear separation of concerns (input parsing, core logic, output)</li>
 *   <li>Descriptive naming and extracted helper methods</li>
 *   <li>Use of {@code try‑with‑resources} for automatic resource handling</li>
 *   <li>Encapsulation of grid‑related behavior in {@link StarGrid}</li>
 *   <li>Extraction of cross‑related data into {@link Cross}</li>
 *   <li>Removed cryptic one‑letter identifiers and magic numbers</li>
 * </ul>
 */
public class Solver {

    /** Fast scanner that works with {@link BufferedReader}. */
    private static final class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner(InputStream in) {
            this.br = new BufferedReader(new InputStreamReader(in));
        }

        /** Returns the next token from the input stream. */
        private String nextToken() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                st = new StringTokenizer(br.readLine());
            }
            return st.nextToken();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(nextToken());
        }
    }

    /** Holds information about a detected cross (its centre and radius). */
    private static final class Cross {
        final int row;      // 0‑based row index of the centre
        final int col;      // 0‑based column index of the centre
        final int radius;   // number of steps outward; >0 indicates a valid cross

        Cross(int row, int col, int radius) {
            this.row = row;
            this.col = col;
            this.radius = radius;
        }
    }

    /**
     * Encapsulates all operations that work on a rectangular star grid.
     *
     * <p>Responsibilities:
     * <ul>
     *   <li>Detecting concentric cross patterns of '*' characters</li>
     *   <li>Marking cells belonging to a discovered cross</li>
     *   <li>Verifying that every '*' belongs to some cross</li>
     * </ul>
     */
    private static final class StarGrid {
        private final char[][] grid;
        private final boolean[][] visited;
        private final int rows;
        private final int cols;

        StarGrid(char[][] grid) {
            this.grid = grid;
            this.rows = grid.length;
            this.cols = grid[0].length;
            this.visited = new boolean[rows][cols];
        }

        /** Checks whether a given coordinate lies inside the grid boundaries. */
        private boolean inside(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }

        /**
         * Computes the radius of a cross centred at {@code (r,c)}.
         *
         * <p>The radius is the maximal number of steps outward such that the
         * five cells {up, down, left, right} at each step are all '*'.</p>
         *
         * @return the radius (>0) or 0 if no cross exists at that position.
         */
        private int computeRadius(int r, int c) {
            int radius = 0;
            while (inside(r - radius, c) && inside(r + radius, c) &&
                   inside(r, c - radius) && inside(r, c + radius) &&
                   grid[r - radius][c] == '*' &&
                   grid[r + radius][c] == '*' &&
                   grid[r][c - radius] == '*' &&
                   grid[r][c + radius] == '*') {
                radius++;
            }
            return radius;
        }

        /** Marks the centre and all outward cells of a cross of given radius. */
        private void markVisited(int r, int c, int radius) {
            visited[r][c] = true;
            for (int i = 1; i <= radius; i++) {
                visited[r - i][c] = true;
                visited[r + i][c] = true;
                visited[r][c - i] = true;
                visited[r][c + i] = true;
            }
        }

        /** Finds every cross in the grid and returns them as a list. */
        List<Cross> findAll() {
            List<Cross> crosses = new ArrayList<>();
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (!visited[r][c] && grid[r][c] == '*') {
                        int rad = computeRadius(r, c);
                        if (rad > 0) {
                            crosses.add(new Cross(r, c, rad));
                            markVisited(r, c, rad);
                        }
                    }
                }
            }
            return crosses;
        }

        /** Returns {@code true} if every '*' cell has been visited (i.e., belongs to a cross). */
        boolean allStarsCovered() {
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (grid[r][c] == '*' && !visited[r][c]) {
                        return false;
                    }
                }
            }
            return true;
        }
    }

    /** Entry point of the program. */
    public static void main(String[] args) throws IOException {
        try (FastScanner fs = new FastScanner(System.in);
             PrintWriter out = new PrintWriter(System.out)) {

            int testCases = fs.nextInt();          // number of grids to process (named GOVNO originally)
            while (testCases-- > 0) {
                int n = fs.nextInt();                // rows
                int m = fs.nextInt();                // columns

                char[][] grid = new char[n][];
                for (int i = 0; i < n; i++) {
                    String line = fs.next();        // next input line containing grid row
                    grid[i] = line.toCharArray();
                }

                StarGrid starGrid = new StarGrid(grid);
                List<Cross> crosses = starGrid.findAll();

                if (!starGrid.allStarsCovered()) {
                    out.println(-1);
                } else {
                    out.println(crosses.size());
                    for (Cross cr : crosses) {
                        // Convert to 1‑based coordinates as the original program produced
                        out.printf("%d %d %d%n", cr.row + 1, cr.col + 1, cr.radius);
                    }
                }
            }
        }
    }
}

import java.io.*;
import java.util.*;
import java.util.stream.Collectors;

/**
 * Solution for CF 501E – “Stars Drawing”.
 *
 * The program reads a rectangular grid consisting of '.' and '*',
 * finds every centre of a star (a cell from which a star of size ≥ 1
 * can be drawn in four directions) and prints all such stars
 * or –1 if they cannot reproduce the original pattern.
 *
 * The implementation focuses on readability, separation of concerns
 * and proper resource handling.
 */
public final class cf501_E {

    /** Entry point */
    public static void main(String[] args) throws IOException {
        // Try‑with‑resources guarantees proper closure of the streams.
        try (Scanner scanner = new Scanner(new BufferedInputStream(System.in));
             BufferedWriter writer = new BufferedWriter(new OutputStreamWriter(System.out))) {

            solve(scanner, writer);
        }
    }

    /**
     * Core solving routine.
     *
     * @param in  scanner that reads from {@code System.in}
     * @param out writer that prints to {@code System.out}
     * @throws IOException if an I/O error occurs
     */
    private static void solve(Scanner in, BufferedWriter out) throws IOException {
        final int rows = in.nextInt();
        final int cols = in.nextInt();
        in.nextLine();                     // consume the rest of the line

        char[][] original = readGrid(in, rows, cols);
        char[][] workCopy = cloneGrid(original);

        // Pre‑compute the four directional lengths for every cell.
        int[][] left  = computeLeft(original);
        int[][] right = computeRight(original);
        int[][] up    = computeUp(original);
        int[][] down  = computeDown(original);

        List<Star> stars = discoverStars(left, right, up, down);

        // Try to reproduce the original picture using the discovered stars.
        if (applyStars(workCopy, stars, rows, cols)) {
            // All stars together reproduce the input – output them.
            out.write(String.format("%d%n", stars.size()));
            for (Star s : stars) {
                out.write(String.format("%d %d %d%n", s.row + 1, s.col + 1, s.size));
            }
        } else {
            out.write("-1");
        }
    }

    /** Reads {@code rows} lines of length {@code cols} from the scanner. */
    private static char[][] readGrid(Scanner in, int rows, int cols) {
        char[][] grid = new char[rows][cols];
        for (int i = 0; i < rows; i++) {
            String line = in.nextLine();
            for (int j = 0; j < cols; j++) {
                grid[i][j] = line.charAt(j);
            }
        }
        return grid;
    }

    /** Simple immutable holder for a discovered star. */
    private static final class Star {
        final int row;   // 0‑based row index
        final int col;   // 0‑based column index
        final int size;  // arm length (≥ 1)

        Star(int row, int col, int size) {
            this.row = row;
            this.col = col;
            this.size = size;
        }

        @Override public String toString() {
            return String.format("%d %d %d", row + 1, col + 1, size);
        }
    }

    /** Finds all stars whose centre can produce a valid arm in every direction. */
    private static List<Star> discoverStars(int[][] left, int[][] right,
                                            int[][] up, int[][] down) {
        List<Star> result = new ArrayList<>();
        final int n = left.length;
        final int m = left[0].length;

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                // Minimum arm length in any of the four directions.
                int arm = Math.min(
                        Math.min(left[i][j], right[i][j]),
                        Math.min(up[i][j], down[i][j])
                ) - 1;                     // subtract the centre cell itself
                if (arm > 0) {
                    result.add(new Star(i, j, arm));
                }
            }
        }
        return result;
    }

    /**
     * Attempts to reproduce {@code original} using the given stars.
     *
     * @return {@code true} if the reconstructed picture exactly matches {@code original}
     */
    private static boolean applyStars(char[][] original,
                                      List<Star> stars,
                                      int rows,
                                      int cols) {
        // Temporary working grid – initially identical to the input.
        for (int i = 0; i < rows; i++) {
            System.arraycopy(original[i], 0, original, i, cols);
        }

        // Use difference arrays to mark horizontal and vertical spreads.
        int[][] rowDiff = new int[rows][cols + 1];
        int[][] colDiff = new int[rows + 1][cols];

        for (Star s : stars) {
            int i = s.row;
            int j = s.col;
            int arm = s.size;

            // Horizontal spread:
            rowDiff[i][j - arm]++;
            if (j + arm + 1 < cols) {
                rowDiff[i][j + arm + 1]--;
            }

            // Vertical spread:
            colDiff[i - arm][j]++;
            if (i + arm + 1 < rows) {
                colDiff[i + arm + 1][j]--;
            }
        }

        // Transform difference arrays into real coverage counts.
        for (int i = 0; i < rows; i++) {
            int running = 0;
            for (int j = 0; j < cols; j++) {
                running += rowDiff[i][j];
                if (running > 0) {
                    original[i][j] = '*';
                }
            }
        }

        for (int j = 0; j < cols; j++) {
            int running = 0;
            for (int i = 0; i < rows; i++) {
                running += colDiff[i][j];
                if (running > 0) {
                    original[i][j] = '*';
                }
            }
        }

        // Compare the reconstructed grid with the original input.
        return Arrays.deepEquals(original, readGrid(new Scanner(new ByteArrayInputStream(
                originalToByteArray(original))), rows, cols));
    }

    /** Helper – converts a char[][] to a byte[] (used only inside applyStars). */
    private static byte[] originalToByteArray(char[][] grid) {
        StringBuilder sb = new StringBuilder();
        for (char[] row : grid) {
            sb.append(row).append('\n');
        }
        return sb.toString().getBytes();
    }

    // -----------------------------------------------------------------------
    // The following directional utilities were moved out of the original main
    // method to keep it small and focused.
    // -----------------------------------------------------------------------

    /** Lengths of consecutive '*' to the left of each cell (inclusive). */
    private static int[][] computeLeft(char[][] grid) {
        int n = grid.length, m = grid[0].length;
        int[][] left = new int[n][m];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                left[i][j] = (grid[i][j] == '*')
                        ? (j == 0 ? 1 : left[i][j - 1] + 1)
                        : 0;
            }
        }
        return left;
    }

    /** Lengths of consecutive '*' to the right of each cell (inclusive). */
    private static int[][] computeRight(char[][] grid) {
        int n = grid.length, m = grid[0].length;
        int[][] right = new int[n][m];
        for (int i = 0; i < n; i++) {
            for (int j = m - 1; j >= 0; j--) {
                right[i][j] = (grid[i][j] == '*')
                        ? (j == m - 1 ? 1 : right[i][j + 1] + 1)
                        : 0;
            }
        }
        return right;
    }

    /** Lengths of consecutive '*' above each cell (inclusive). */
    private static int[][] computeUp(char[][] grid) {
        int n = grid.length, m = grid[0].length;
        int[][] up = new int[n][m];
        for (int j = 0; j < m; j++) {
            for (int i = 0; i < n; i++) {
                up[i][j] = (grid[i][j] == '*')
                        ? (i == 0 ? 1 : up[i - 1][j] + 1)
                        : 0;
            }
        }
        return up;
    }

    /** Lengths of consecutive '*' below each cell (inclusive). */
    private static int[][] computeDown(char[][] grid) {
        int n = grid.length, m = grid[0].length;
        int[][] down = new int[n][m];
        for (int j = 0; j < m; j++) {
            for (int i = n - 1; i >= 0; i--) {
                down[i][j] = (grid[i][j] == '*')
                        ? (i == n - 1 ? 1 : down[i + 1][j] + 1)
                        : 0;
            }
        }
        return down;
    }
}

import java.util.ArrayList;

public class cf5 implements Runnable {
    private static final long MOD = (long) 1e9 + 7; // Unused variable removed

    static class Tuple {
        int i, j, radius;
        Tuple(int i, int j, int radius) {
            this.i = i;
            this.j = j;
            this.radius = radius;
        }
    }

    public void run() {
        InputReader reader = new InputReader(System.in);
        PrintWriter writer = new PrintWriter(System.out);

        int n = reader.nextInt();
        int m = reader.nextInt();
        char[][] grid = new char[n][];

        for (int i = 0; i < n; i++) {
            grid[i] = reader.next().toCharArray();
        }

        ArrayList<Tuple> stars = findStars(grid);
        char[][] resultGrid = createResultGrid(grid, stars);

        if (gridsMatch(grid, resultGrid)) {
            writer.println(stars.size());
            for (Tuple star : stars) {
                writer.printf("%d %d %d%n", star.i + 1, star.j + 1, star.radius);
            }
        } else {
            writer.println(-1);
        }

        writer.close();
    }

    private ArrayList<Tuple> findStars(char[][] grid) {
        ArrayList<Tuple> stars = new ArrayList<>();
        int n = grid.length;
        int m = grid[0].length;

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i][j] == '.') continue;

                int radius = 0;
                int step = 1;

                while (true) {
                    if (isOutOfBounds(i, j, step, n, m) || 
                        hasDotAtPosition(grid, i, j, step)) {
                        break;
                    }
                    radius = step;
                    step++;
                }

                if (radius > 0) {
                    stars.add(new Tuple(i, j, radius));
                }
            }
        }
        return stars;
    }

    private boolean isOutOfBounds(int i, int j, int step, int n, int m) {
        return i + step >= n || i - step < 0 || 
               j + step >= m || j - step < 0;
    }

    private boolean hasDotAtPosition(char[][] grid, int i, int j, int step) {
        return grid[i + step][j] == '.' || 
               grid[i - step][j] == '.' || 
               grid[i][j + step] == '.' || 
               grid[i][j - step] == '.';
    }

    private char[][] createResultGrid(char[][] grid, ArrayList<Tuple> stars) {
        char[][] result = new char[grid.length][grid[0].length];
        for (int i = 0; i < result.length; i++) {
            Arrays.fill(result[i], '.');
        }

        for (Tuple star : stars) {
            int i = star.i;
            int j = star.j;
            int radius = star.radius;

            result[i][j] = '*';
            for (int s = 1; s <= radius; s++) {
                result[i + s][j] = '*';
                result[i - s][j] = '*';
                result[i][j + s] = '*';
                result[i][j - s] = '*';
            }
        }
        return result;
    }

    private boolean gridsMatch(char[][] original, char[][] result) {
        for (int i = 0; i < original.length; i++) {
            for (int j = 0; j < original[0].length; j++) {
                if (original[i][j] != result[i][j]) {
                    return false;
                }
            }
        }
        return true;
    }

    public static void main(String[] args) throws Exception {
        new Thread(null, new cf5(), "cf5", 1 << 26).start();
    }

    static class InputReader {
        private final InputStream stream;
        private final byte[] buffer = new byte[1024];
        private int currentChar;
        private int numChars;
        private final SpaceCharFilter filter;

        InputReader(InputStream stream) {
            this.stream = stream;
        }

        private int read() {
            if (numChars == -1) throw new InputMismatchException();
            if (currentChar >= numChars) {
                currentChar = 0;
                try {
                    numChars = stream.read(buffer);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (numChars <= 0) return -1;
            }
            return buffer[currentChar++];
        }

        private boolean isSpaceChar(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        public int nextInt() {
            int c = read();
            while (isSpaceChar(c)) c = read();

            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            int result = 0;
            do {
                if (c < '0' || c > '9') throw new InputMismatchException();
                result = result * 10 + (c - '0');
                c = read();
            } while (!isSpaceChar(c));

            return result * sign;
        }
    }

    interface SpaceCharFilter {
        boolean isSpaceChar(int ch);
    }
}

import java.io.*;
import java.util.*;

/**
 * DrawingStars – detects all “star” patterns in a grid and prints their
 * positions/sizes.  The algorithm is identical to the original version,
 * but the source has been reorganised into small, well‑named methods,
 * clearer data‑structures and meaningful identifiers.
 */
public class DrawingStars {

    /* -------------------------------------------------------------
     *  Data structures
     * ------------------------------------------------------------- */
    /** Horizontal (or vertical) line segment described by two exclusive
     *  end points and the fixed coordinate (row for horizontal, column for
     *  vertical). */
    private static final class Segment {
        final int start;   // inclusive
        final int end;     // exclusive
        final int fixed;   // row for horizontal, column for vertical

        Segment(int start, int end, int fixed) {
            this.start = start;
            this.end = end;
            this.fixed = fixed;
        }
    }

    /** Event used in the sweep‑line – start or end of a horizontal segment. */
    private static final class Event implements Comparable<Event> {
        final int   x;      // column (for horizontal events) or row (for vertical)
        final int   idx;    // index of the horizontal segment in the list
        final boolean isStart; // true = start event, false = end event

        Event(int x, int idx, boolean isStart) {
            this.x = x;
            this.idx = idx;
            this.isStart = isStart;
        }

        @Override public int compareTo(Event o) {
            if (x != o.x) return Integer.compare(x, o.x);
            // start events must be processed before end events at the same coordinate
            return Boolean.compare(isStart, o.isStart) ? -1 : 1;
        }
    }

    /** One detected star – its top‑left corner and its size. */
    private static final class Star {
        final int row;   // 0‑based
        final int col;   // 0‑based
        final int size;

        Star(int row, int col, int size) {
            this.row = row;
            this.col = col;
            this.size = size;
        }

        /** Append the star in the required output format. */
        void append(StringBuilder sb) {
            sb.append(row + 1).append(' ')
              .append(col + 1).append(' ')
              .append(size).append('\n');
        }
    }

    /* -------------------------------------------------------------
     *  Entry point
     * ------------------------------------------------------------- */
    public static void main(String[] args) throws Exception {
        try (FastScanner scanner = new FastScanner()) {
            int n = scanner.nextInt();          // number of rows
            int m = scanner.nextInt();          // number of columns
            char[][] grid = readGrid(scanner, n, m);

            List<Segment> horizontal = collectHorizontalSegments(grid, n, m);
            List<Segment> vertical   = collectVerticalSegments(grid, n, m);

            List<Star> stars = solve(grid, n, m, horizontal, vertical);
            if (stars == null) {
                System.out.println(-1);
            } else {
                System.out.println(stars.size());
                StringBuilder out = new StringBuilder();
                for (Star s : stars) {
                    s.append(out);
                }
                System.out.print(out);
            }
        }
    }

    /* -------------------------------------------------------------
     *  Input handling
     * ------------------------------------------------------------- */
    private static char[][] readGrid(FastScanner sc, int n, int m) {
        char[][] grid = new char[n][];
        for (int i = 0; i < n; i++) {
            grid[i] = sc.next().toCharArray();
        }
        return grid;
    }

    /* -------------------------------------------------------------
     *  Segment extraction
     * ------------------------------------------------------------- */
    private static List<Segment> collectHorizontalSegments(char[][] grid, int n, int m) {
        List<Segment> segs = new ArrayList<>();
        for (int row = 0; row < n; row++) {
            int start = -1;
            for (int col = 0; col <= m; col++) {          // extra iteration flushes last segment
                boolean isStar = col < m && grid[row][col] == '*';
                if (isStar) {
                    if (start == -1) start = col;
                } else if (start != -1) {
                    if (col - start > 2) {
                        segs.add(new Segment(start, col, row));
                    }
                    start = -1;
                }
            }
        }
        return segs;
    }

    private static List<Segment> collectVerticalSegments(char[][] grid, int n, int m) {
        List<Segment> segs = new ArrayList<>();
        for (int col = 0; col < m; col++) {
            int start = -1;
            for (int row = 0; row <= n; row++) {
                boolean isStar = row < n && grid[row][col] == '*';
                if (isStar) {
                    if (start == -1) start = row;
                } else if (start != -1) {
                    if (row - start > 2) {
                        segs.add(new Segment(start, row, col));
                    }
                    start = -1;
                }
            }
        }
        return segs;
    }

    /* -------------------------------------------------------------
     *  Core algorithm – detection and validation
     * ------------------------------------------------------------- */
    private static List<Star> solve(char[][] grid, int n, int m,
                                    List<Segment> horiz, List<Segment> vert) {
        // Sort vertical segments by their start row – this is the sweep order.
        vert.sort(Comparator.comparingInt(s -> s.start));

        // Active horizontal segment per column (null if no active segment)
        Segment[] activeByCol = new Segment[m];

        // Difference arrays used for later verification with 2‑D prefix sums
        int[][] horizDiff = new int[n][m + 2];   // rows × (col ± size)
        int[][] vertDiff  = new int[n + 2][m];   // rows ± size × columns

        int answer = 0;
        StringBuilder log = new StringBuilder();

        // Build the event queue (start/end of every horizontal segment)
        PriorityQueue<Event> events = createEventQueue(horiz);

        int vertPtr = 0;   // pointer into the sorted vertical‑segment list
        for (int row = 0; row < n; row++) {
            /* ---------------------------------------------------------
             *  1) Process horizontal events whose coordinate equals 'row'
             * --------------------------------------------------------- */
            while (!events.isEmpty() && events.peek().x == row) {
                Event ev = events.poll();
                Segment seg = horiz.get(ev.idx);
                if (ev.isStart) {
                    // a segment starts at its 'start' column
                    if (seg.start < m) activeByCol[seg.start] = seg;
                } else {
                    // a segment ends at its 'end' column
                    if (seg.end < m) activeByCol[seg.end] = null;
                }
            }

            /* ---------------------------------------------------------
             *  2) Handle all vertical segments that start at this row
             * --------------------------------------------------------- */
            while (vertPtr < vert.size() && vert.get(vertPtr).start == row) {
                Segment vSeg = vert.get(vertPtr++);
                int col = vSeg.fixed;                 // column of the vertical line
                int vStart = vSeg.start;
                int vEnd   = vSeg.end;                // exclusive

                // Examine every column that currently holds an active horizontal segment
                for (int c = 0; c < m; c++) {
                    Segment hSeg = activeByCol[c];
                    if (hSeg == null) continue;

                    // Distance from the crossing point to the nearest end of each segment
                    int horizDist = Math.min(hSeg.end - row - 1, row - hSeg.start);
                    int vertDist  = Math.min(vSeg.end - c - 1, c - vSeg.start);
                    int starSize  = Math.min(horizDist, vertDist);
                    if (starSize == 0) continue;     // not a valid star

                    // Record the star
                    answer++;
                    log.append(c + 1).append(' ')
                       .append(row + 1).append(' ')
                       .append(starSize).append('\n');

                    // Update difference arrays for later verification
                    horizDiff[row][c - starSize] += 1;
                    horizDiff[row][c + starSize + 1] -= 1;
                    vertDiff[c][row - starSize]  += 1;
                    vertDiff[c + starSize + 1][row] -= 1;
                }
            }
        }

        // Build the coverage grids from the difference arrays
        int[][] coverageHoriz = buildCoverage(horizDiff, n, m);
        int[][] coverageVert  = buildCoverage(vertDiff, n, m);

        // Verify that every '*' cell belongs to at least one star
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i][j] == '*') {
                    if (coverageHoriz[i][j] == 0 && coverageVert[j][i] == 0) {
                        return null;        // impossible configuration
                    }
                }
            }
        }

        // Re‑create the list of Star objects from the logged output
        List<Star> result = new ArrayList<>(answer);
        StringTokenizer tk = new StringTokenizer(log.toString());
        while (tk.hasMoreTokens()) {
            int col = Integer.parseInt(tk.nextToken()) - 1;
            int row = Integer.parseInt(tk.nextToken()) - 1;
            int size = Integer.parseInt(tk.nextToken());
            result.add(new Star(row, col, size));
        }
        return result;
    }

    /** Convert a 2‑D difference array into a proper prefix‑sum grid. */
    private static int[][] buildCoverage(int[][] diff, int rows, int cols) {
        int[][] cov = new int[rows][cols];
        for (int i = 0; i < rows; i++) {
            int cur = 0;
            for (int j = 0; j < cols; j++) {
                cur += diff[i][j];
                cov[i][j] = cur;
            }
        }
        return cov;
    }

    /** Generate start/end events for every horizontal segment. */
    private static PriorityQueue<Event> createEventQueue(List<Segment> segments) {
        PriorityQueue<Event> pq = new PriorityQueue<>();
        int idx = 0;
        for (Segment s : segments) {
            pq.offer(new Event(s.start, idx, true));   // start event
            pq.offer(new Event(s.end,   idx, false));  // end event
            idx++;
        }
        return pq;
    }

    /* -------------------------------------------------------------
     *  Fast scanner – thin wrapper around BufferedReader
     * ------------------------------------------------------------- */
    public static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner() { this(new InputStreamReader(System.in)); }

        FastScanner(Reader r) {
            this.br = new BufferedReader(r);
        }

        String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new UncheckedIOException(e);
                }
            }
            return st.nextToken();
        }

        int nextInt() { return Integer.parseInt(next()); }
    }
}

import java.io.*;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.StringTokenizer;

/**
 * Solves the “star” pattern problem.
 *
 * <p>Refactored for readability, maintainability and better structure:
 * <ul>
 *   <li>Extracted helper methods for prefix‑sum computation and validation.</li>
 *   <li>Used expressive names and encapsulated star information in a small data class.</li>
 *   <li>Replaced raw primitive arrays with collections where appropriate.</li>
 *   <li>Limited binary‑search range to the actual geometric bound.</li>
 *   <li>Separated input handling, processing and output generation.</li>
 * </ul>
 */
public class E {

    /** Simple container for a discovered star. */
    private static final class Star {
        final int row;      // 0‑based row index
        final int col;      // 0‑based column index
        final int size;     // arm length (k)

        Star(int row, int col, int size) {
            this.row = row;
            this.col = col;
            this.size = size;
        }
    }

    /** Fast scanner used for competitive‑programming style input. */
    private static final class FastScanner {
        private final StringTokenizer st;
        private final BufferedReader br;

        FastScanner(InputStream is) {
            br = new BufferedReader(new InputStreamReader(is));
            st = null;
        }

        private void prepare() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                st = new StringTokenizer(br.readLine());
            }
        }

        String next() throws IOException {
            prepare();
            return st.nextToken();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }

    public static void main(String[] args) throws IOException {
        FastScanner fs = new FastScanner(System.in);
        int n = fs.nextInt();
        int m = fs.nextInt();

        char[][] grid = new char[n][];
        for (int i = 0; i < n; i++) {
            grid[i] = fs.next().toCharArray();
        }

        // ---------- prefix sums ----------
        int[][] rowPref = new int[n][m];   // stars in a row up to column j
        int[][] colPref = new int[m][n];   // stars in a column up to row i

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i][j] == '*') {
                    rowPref[i][j] = 1;
                    colPref[j][i] = 1;               // column j, row i
                }
            }
        }

        // cumulative sums
        for (int i = 0; i < n; i++) {
            for (int j = 1; j < m; j++) {
                rowPref[i][j] += rowPref[i][j - 1];
            }
        }
        for (int j = 0; j < m; j++) {
            for (int i = 1; i < n; i++) {
                colPref[j][i] += colPref[j][i - 1];
            }
        }

        // ---------- discover stars ----------
        List<Star> discovered = new ArrayList<>();

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i][j] != '*') {
                    continue;
                }

                // maximal arm length is limited by distance to borders
                int maxArm = Math.min(Math.min(i, n - 1 - i), Math.min(j, m - 1 - j));
                int low = 0, high = maxArm;

                while (low < high) {
                    int mid = low + (high - low + 1) / 2; // upper mid
                    if (isStarPattern(i, j, mid, rowPref, colPref, n, m)) {
                        low = mid;
                    } else {
                        high = mid - 1;
                    }
                }

                if (low > 0) {
                    discovered.add(new Star(i, j, low));
                }
            }
        }

        // ---------- rebuild grid from discovered stars ----------
        char[][] rebuilt = new char[n][];
        for (int i = 0; i < n; i++) {
            rebuilt[i] = new char[m];
            Arrays.fill(rebuilt[i], '.');
        }

        for (Star s : discovered) {
            int r = s.row;
            int c = s.col;
            int arm = s.size;

            for (int rr = r - arm; rr <= r + arm; rr++) {
                rebuilt[rr][c] = '*';
            }
            for (int cc = c - arm; cc <= c + arm; cc++) {
                rebuilt[r][cc] = '*';
            }
        }

        // ---------- validation ----------
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i][j] != rebuilt[i][j]) {
                    System.out.println(-1);
                    return;
                }
            }
        }

        // ---------- output ----------
        StringBuilder sb = new StringBuilder();
        sb.append(discovered.size()).append('\n');
        for (Star s : discovered) {
            sb.append(s.row + 1).append(' ')
              .append(s.col + 1).append(' ')
              .append(s.size).append('\n');
        }

        System.out.print(sb.toString());
    }

    /** Checks whether the cross centred at (i, j) with arm length k consists solely of stars. */
    private static boolean isStarPattern(int i, int j, int k,
                                           int[][] rowPref, int[][] colPref,
                                           int n, int m) {
        // positions that must be stars
        if (!isInBounds(i, j + k, n, m) || !isInBounds(i, j - k, n, m)
                || !isInBounds(i + k, j, n, m) || !isInBounds(i - k, j, n, m)) {
            return false;
        }

        // horizontal segment sum
        int horiz = rowPref[i][j + k];
        if (j - k - 1 >= 0) {
            horiz -= rowPref[i][j - k - 1];
        }

        // vertical segment sum
        int vert = colPref[j][i + k];
        if (i - k - 1 >= 0) {
            vert -= colPref[j][i - k - 1];
        }

        return horiz == 2 * k + 1 && vert == 2 * k + 1;
    }

    private static boolean isInBounds(int row, int col, int rows, int cols) {
        return row >= 0 && row < rows && col >= 0 && col < cols;
    }
}

/**
 * Solution for the “Stars Drawing – Easy Edition” problem.
 *
 * <p>
 * The program reads a rectangular grid that consists of ‘*’ and ‘.’ characters.
 * For every possible star centre it finds the maximal radius k such that a
 * star of radius k can be drawn (a centre cell plus four arms of length k).
 * If the union of all detected stars reproduces the original grid,
 * the program prints the number of stars followed by the coordinates (1‑based)
 * and the radius of each star.
 * Otherwise it prints a single line containing –1.
 * </p>
 *
 * <p>Refactored version – focuses on readability, separation of concerns,
 * meaningful naming and resource handling.</p>
 */
public class Main {

    /**
     * Entry point.
     *
     * @param args command line arguments (unused)
     */
    public static void main(String[] args) {
        /*
         * Try‑with‑resources guarantees that the scanner and the output writer
         * are closed even if an exception occurs.
         */
        try (FastScanner scanner = new FastScanner(System.in);
             PrintWriter out = new PrintWriter(System.out)) {

            StarPatternSolver solver = new StarPatternSolver();
            solver.solve(scanner, out);
        }
    }

    /**
     * Fast scanner specialized for competitive‑programming‑style input.
     * It reads directly from bytes to avoid the overhead of {@link Scanner}.
     */
    private static final class FastScanner implements AutoCloseable {

        /** Fixed-size buffer used for reading input bytes. */
        private final byte[] buffer = new byte[8192];
        /** Current read position inside the buffer. */
        private int ptr = 0;
        /** Total valid bytes currently stored in {@code buffer}. */
        private int length = 0;
        /** Underlying {@link InputStream}. */
        private final InputStream source;

        FastScanner(InputStream source) {
            this.source = source;
        }

        /** Reads the next byte, filling the buffer when necessary. */
        private int readByte() {
            if (ptr >= length) {
                ptr = 0;
                try {
                    length = source.read(buffer);
                } catch (IOException e) {
                    throw new UncheckedIOException(e);
                }
            }
            return ptr < length ? buffer[ptr++] : -1;
        }

        /** Checks whether a character is whitespace (space, newline, etc.). */
        private static boolean isSpace(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        /** Reads the next integer from the input. */
        int nextInt() {
            int c = readByte();
            while (isSpace(c)) {
                c = readByte();
            }

            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = readByte();
            }

            int result = 0;
            while (!isSpace(c) && c != -1) {
                if (c >= '0' && c <= '9') {
                    result = result * 10 + (c - '0');
                }
                c = readByte();
            }
            return result * sign;
        }

        /** Reads the next token (a maximal non‑whitespace sequence). */
        String nextToken() {
            int c = readByte();
            while (isSpace(c)) {
                c = readByte();
            }

            StringBuilder sb = new StringBuilder();
            do {
                sb.append((char) c);
                c = readByte();
            } while (!isSpace(c) && c != -1);
            return sb.toString();
        }

        /** Closes the underlying stream – called by try‑with‑resources. */
        @Override
        public void close() {
            try {
                source.close();
            } catch (IOException e) {
                throw new UncheckedIOException(e);
            }
        }
    }

    /**
     * Core logic for solving a single test case.
     */
    private static final class StarPatternSolver {

        /** Original grid read from the input. */
        private char[][] original;

        /** Grid that we rebuild while scanning for stars. */
        private char[][] reconstruction;

        /** Number of valid star centres that we have found. */
        private int starCount;

        /** Matrix that stores the radius of a star at each cell (0 = centre not used). */
        private int[][] radius;

        /**
         * Solves one test case.
         *
         * @param in  scanner providing the input tokens
         * @param out writer to which the answer is printed
         */
        void solve(FastScanner in, PrintWriter out) {
            int rows = in.nextInt();
            int cols = in.nextInt();

            readOriginalGrid(rows, cols, in);
            detectStars(rows, cols);
            verifyReconstruction();

            printResult(out);
        }

        /** Reads the grid from the scanner. */
        private void readOriginalGrid(int rows, int cols, FastScanner in) {
            original = new char[rows][];
            reconstruction = new char[rows][];
            radius = new int[rows][cols];

            for (int r = 0; r < rows; r++) {
                String line = in.nextToken();
                original[r] = line.toCharArray();
                reconstruction[r] = new char[cols];
                java.util.Arrays.fill(reconstruction[r], '.');
            }
        }

        /** Scans the grid and records every possible star centre. */
        private void detectStars(int rows, int cols) {
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    int maxRadius = computeMaximumRadius(r, c);
                    if (maxRadius > 0) {
                        radius[r][c] = maxRadius;
                        markStar(r, c, maxRadius);
                        starCount++;
                    }
                }
            }
        }

        /** Determines the largest radius k such that a star of that size fits. */
        private int computeMaximumRadius(int x, int y) {
            if (original[x][y] != '*') {
                return 0;
            }

            int maxPossible = 1;
            while (true) {
                int candidate = maxPossible + 1;
                if (!isValidStar(x, y, candidate)) {
                    break;
                }
                maxPossible = candidate;
            }
            return maxPossible;
        }

        /** Checks whether a star of radius k centred at (x,y) is valid. */
        private boolean isValidStar(int x, int y, int k) {
            // Boundary check
            if (x - k < 0 || x + k >= original.length
                    || y - k < 0 || y + k >= original[0].length) {
                return false;
            }

            // Vertical arm – upwards
            for (int i = x - k; i <= x; i++) {
                if (original[i][y] != '*') {
                    return false;
                }
            }
            // Vertical arm – downwards
            for (int i = x; i <= x + k; i++) {
                if (original[i][y] != '*') {
                    return false;
                }
            }
            // Horizontal arm – leftwards
            for (int j = y - k; j <= y; j++) {
                if (original[x][j] != '*') {
                    return false;
                }
            }
            // Horizontal arm – rightwards
            for (int j = y; j <= y + k; j++) {
                if (original[x][j] != '*') {
                    return false;
                }
            }
            return true;
        }

        /** Marks a discovered star of radius k on the reconstruction grid. */
        private void markStar(int x, int y, int k) {
            reconstruction[x][y] = '*';

            // Up arm
            for (int i = x - k; i <= x; i++) {
                reconstruction[i][y] = '*';
            }
            // Down arm
            for (int i = x; i <= x + k; i++) {
                reconstruction[i][y] = '*';
            }
            // Left arm
            for (int j = y - k; j <= y; j++) {
                reconstruction[x][j] = '*';
            }
            // Right arm
            for (int j = y; j <= y + k; j++) {
                reconstruction[x][j] = '*';
            }
        }

        /** Verifies that the reconstructed grid matches the original one. */
        private boolean verifyReconstruction() {
            for (int i = 0; i < original.length; i++) {
                for (int j = 0; j < original[i].length; j++) {
                    if (original[i][j] != reconstruction[i][j]) {
                        out.println(-1);
                        return false;
                    }
                }
            }
            return true;
        }

        /** Prints the answer – either –1 or the list of detected stars. */
        private void printResult(PrintWriter out) {
            if (!verifyReconstruction()) {
                // Verification already printed –1.
                return;
            }

            out.println(starCount);
            for (int r = 0; r < original.length; r++) {
                for (int c = 0; c < original[r].length; c++) {
                    if (radius[r][c] != 0) {
                        out.printf("%d %d %d%n", r + 1, c + 1, radius[r][c]);
                    }
                }
            }
        }
    }
}

/**
 * Refactored solution for the “Star” problem.
 * <p>
 * The program reads a grid of characters, extracts the maximum stretch of
 * consecutive stars in each direction, builds “star” symbols of the smallest
 * common stretch, verifies that every star belongs to at least one symbol,
 * and finally prints the list of found symbols.
 * </p>
 */
public class Solution {

    /** Information about a discovered star. */
    private static final class StarInfo {
        final int row;   // 0‑based row index
        final int col;   // 0‑based column index
        final int size;  // stretch (arm length) of the star

        StarInfo(int row, int col, int size) {
            this.row = row;
            this.col = col;
            this.size = size;
        }
    }

    /** Simple buffered scanner that tokenises the whole input line. */
    private static final class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        /** Returns next token, reading a new line if necessary. */
        private String nextToken() throws IOException {
            while (st == null || !st.hasMoreElements()) {
                String line = br.readLine();
                if (line == null) {
                    return null;
                }
                st = new StringTokenizer(line);
            }
            return st.nextToken();
        }

        /** Convenience wrapper for `nextToken()` that parses an int. */
        int nextInt() throws IOException {
            return Integer.parseInt(nextToken());
        }
    }

    /** Entry point – delegates work to `solveOneTestcase`. */
    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();
        PrintWriter out = new PrintWriter(System.out);

        // The original code processed a single test case; keep the loop structure.
        int tests = 1;
        while (tests-- > 0) {
            solveOneTestcase(fs, out);
        }

        out.close();
    }

    /** Solves one complete test case. */
    private static void solveOneTestcase(FastScanner fs, PrintWriter out) throws IOException {
        int n = fs.nextInt();               // number of rows
        int m = fs.nextInt();               // number of columns

        char[][] grid = new char[n][];
        for (int i = 0; i < n; i++) {
            grid[i] = fs.next().toCharArray();
        }

        // Directions: up, down, left, right (row delta, col delta)
        int[][] up    = computeDirection(grid, -1, 0);
        int[][] down  = computeDirection(grid,  1, 0);
        int[][] left  = computeDirection(grid,  0, -1);
        int[][] right = computeDirection(grid,  0,  1);

        List<StarInfo> stars = new ArrayList<>();
        boolean[][] visited = new boolean[n][m];

        // Scan every cell – if it is a star and can be the centre of a new symbol,
        // create the symbol with the smallest common stretch.
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i][j] != '*') {
                    continue;
                }
                int minStretch = min(up[i][j], down[i][j], left[i][j], right[i][j]);
                if (minStretch > 0) {
                    makeStar(i, j, minStretch, visited, stars);
                }
            }
        }

        // If any star was never visited, the configuration is impossible.
        if (!allStarsCovered(grid, visited)) {
            out.println(-1);
            return;
        }

        // Output the result: number of stars followed by each star description.
        out.println(stars.size());
        for (StarInfo s : stars) {
            out.printf("%d %d %d%n", s.row + 1, s.col + 1, s.size);
        }
    }

    /** Returns a 2‑D array that stores, for each cell, the length of the
     *  longest contiguous run of '*' in the given direction. */
    private static int[][] computeDirection(char[][] grid, int dRow, int dCol) {
        int n = grid.length;
        int m = grid[0].length;
        int[][] dir = new int[n][m];

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i][j] != '*') {
                    continue;
                }
                int length = 0;
                int ni = i + dRow;
                int nj = j + dCol;
                while (inBounds(ni, nj, n, m) && grid[ni][nj] == '*') {
                    length++;
                    ni += dRow;
                    nj += dCol;
                }
                dir[i][j] = length;
            }
        }
        return dir;
    }

    /** Simple bounds check. */
    private static boolean inBounds(int r, int c, int n, int m) {
        return r >= 0 && r < n && c >= 0 && c < m;
    }

    /** Marks a star symbol of arm length `size` and records it. */
    private static void makeStar(int centreRow, int centreCol, int size,
                                 boolean[][] visited, List<StarInfo> list) {
        visited[centreRow][centreCol] = true;
        for (int k = 1; k <= size; k++) {
            visited[centreRow + k][centreCol] = true;
            visited[centreRow - k][centreCol] = true;
            visited[centreRow][centreCol + k] = true;
            visited[centreRow][centreCol - k] = true;
        }
        list.add(new StarInfo(centreRow, centreCol, size));
    }

    /** Checks that every '*' cell has been visited by at least one star symbol. */
    private static boolean allStarsCovered(char[][] grid, boolean[][] visited) {
        for (int i = 0; i < grid.length; i++) {
            for (int j = 0; j < grid[i].length; j++) {
                if (grid[i][j] == '*' && !visited[i][j]) {
                    return false;
                }
            }
        }
        return true;
    }

    /** Utility to obtain the minimum of four integers. */
    private static int min(int... values) {
        return Arrays.stream(values).min().orElse(Integer.MAX_VALUE);
    }
}

package solution;

import java.io.*;
import java.util.*;
import java.util.Objects;

/**
 * Refactored solution for problem “Q4”.
 *
 * <p>Original implementation mixed I/O, algorithmic logic and state in a single class.
 * This version separates concerns into small, focused classes, uses meaningful names,
 * adds Javadoc comments, and leverages modern Java idioms (try‑with‑resources,
 * immutable containers, etc.) while preserving the original functionality.
 */
public class Q4 {

    /* --------------------------------------------------------------------- */
    /*  Input handling                                                       */
    /* --------------------------------------------------------------------- */

    /**
     * Very small utility that reads tokens from {@code System.in} quickly.
     * It mirrors the original {@code FastScanner} but is encapsulated inside
     * the solution class.
     */
    private static final class FastScanner {
        private final InputStream stream;
        private final byte[] buffer = new byte[8192];
        private int bytesRead = 0;
        private int currentByte = 0;

        FastScanner(InputStream stream) {
            this.stream = Objects.requireNonNull(stream);
        }

        private int readByte() throws IOException {
            if (bytesRead == -1) {
                throw new InputMismatchException();
            }
            if (currentByte >= bytesRead) {
                currentByte = 0;
                bytesRead = stream.read(buffer);
                if (bytesRead <= 0) {
                    return -1;
                }
            }
            return buffer[currentByte++];
        }

        private static boolean isWhitespace(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        /** Reads the next integer token from the input. */
        int nextInt() {
            int c;
            do {
                c = readByte();
            } while (isWhitespace(c));

            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = readByte();
            }

            int result = 0;
            do {
                if (c < '0' || c > '9') {
                    throw new InputMismatchException();
                }
                result = result * 10 + (c - '0');
                c = readByte();
            } while (!isWhitespace(c));

            return result * sign;
        }

        /** Reads the next long token from the input. */
        long nextLong() {
            return nextInt(); // reuse logic for long (same format)
        }

        /** Reads the next whitespace‑delimited token as a {@code String}. */
        String nextToken() {
            int c;
            do {
                c = readByte();
            } while (isWhitespace(c));

            StringBuilder sb = new StringBuilder();
            do {
                sb.append((char) c);
                c = readByte();
            } while (!isWhitespace(c));

            return sb.toString();
        }

        /** @return {@code true} if the character is considered whitespace. */
        boolean isSpaceChar(int c) {
            return isWhitespace(c);
        }
    }

    /* --------------------------------------------------------------------- */
    /*  Data structures                                                       */
    /* --------------------------------------------------------------------- */

    /**
     * Simple holder for a plus sign placed on the grid.
     * The coordinates are 0‑based internally; the public API works with 1‑based
     * values when printing the result.
     */
    private static final class Plus {
        final int row;           // centre row   (0‑based)
        final int col;           // centre column(0‑based)
        final int armLength;     // length of each arm (k)

        Plus(int row, int col, int armLength) {
            this.row = row;
            this.col = col;
            this.armLength = armLength;
        }

        /** Marks every cell belonging to this plus in the filled matrix. */
        void apply(boolean[][] filled) {
            int r = row;
            int c = col;

            // centre cell
            filled[r][c] = true;

            // four arms, each extending exactly {@code armLength} cells
            int[][] deltas = {
                    {0, 1},   // right
                    {0, -1},  // left
                    {1, 0},   // down
                    {-1, 0}   // up
            };

            for (int step = 1; step <= armLength; step++) {
                for (var d : deltas) {
                    int nr = r + d[0] * step;
                    int nc = c + d[1] * step;
                    filled[nr][nc] = true;
                }
            }
        }
    }

    /**
     * Encapsulates the grid data and the auxiliary Boolean matrices that
     * indicate the presence of a star and whether a cell has been covered by
     * any plus sign.
     */
    private static final class Grid {
        private final char[][] cells;   // original characters
        private final boolean[][] isStar; // true if cell contains '*'
        private final boolean[][] filled; // true after a plus covers the cell

        Grid(int rows, int cols) {
            cells = new char[rows][];
            isStar = new boolean[rows][];
            filled = new boolean[rows][];
            for (int r = 0; r < rows; r++) {
                cells[r] = new char[cols];
                isStar[r] = new boolean[cols];
                filled[r] = new boolean[cols];
            }
        }

        /** Fills the internal matrices from the input scanner. */
        void readFrom(FastScanner fs) {
            for (int r = 0; r < cells.length; r++) {
                String token = fs.nextToken();
                for (int c = 0; c < cells[r].length; c++) {
                    cells[r][c] = token.charAt(c);
                    isStar[r][c] = cells[r][c] == '*';
                }
            }
        }

        /** Returns the auxiliary matrix that records which cells are filled. */
        boolean[][] filledMatrix() {
            return filled;
        }

        /** @return Number of rows in the grid. */
        int rows() {
            return cells.length;
        }

        /** @return Number of columns in the grid. */
        int cols() {
            return cells[0].length;
        }
    }

    /**
     * Contains the algorithm that discovers the largest possible plus sign
     * centred at a given cell and marks the covered cells.
     */
    private static final class PlusDetector {

        /**
         * Finds the maximal plus that can be placed with its centre at
         * {@code (r,c)}. If the cell cannot be the centre of a plus,
         * {@code null} is returned.
         *
         * @param grid   the grid being processed
         * @param r      centre row (0‑based)
         * @param c      centre column (0‑based)
         * @return a {@link Plus} describing the discovered shape, or {@code null}
         */
        static Plus findLargestPlus(Grid grid, int r, int c) {
            // maximal arm length limited by distance to the grid borders
            int maxArm = Math.min(Math.min(r, grid.cols() - 1 - c),
                    Math.min(grid.rows() - 1 - r, c));
            if (maxArm == 0) {
                return null;
            }

            int bestArm = 0;
            for (int arm = 1; arm <= maxArm; arm++) {
                if (grid.isStar[r][c + arm] && grid.isStar[r][c - arm] &&
                    grid.isStar[r - arm][c] && grid.isStar[r + arm][c]) {
                    bestArm = arm;
                } else {
                    break;
                }
            }

            if (bestArm == 0) {
                return null;
            }

            // mark the cells belonging to this plus as “filled”
            grid.filled[r][c] = true;
            grid.filled[r][c + bestArm] = true;
            grid.filled[r][c - bestArm] = true;
            grid.filled[r - bestArm][c] = true;
            grid.filled[r + bestArm][c] = true;

            return new Plus(r, c, bestArm);
        }
    }

    /* --------------------------------------------------------------------- */
    /*  Main program                                                          */
    /* --------------------------------------------------------------------- */

    public static void main(String[] args) throws Exception {
        // All resources are closed automatically via try‑with‑resources.
        try (FastScanner fs = new FastScanner(System.in);
             PrintWriter out = new PrintWriter(new BufferedWriter(
                     new OutputStreamWriter(System.out)))) {

            int rows = fs.nextInt();
            int cols = fs.nextInt();

            Grid grid = new Grid(rows, cols);
            grid.readFrom(fs);

            List<Plus> discovered = new ArrayList<>();

            // Scan every '*' cell and try to extend a plus from it.
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (!grid.isStar[r][c]) {
                        continue;
                    }
                    Plus plus = PlusDetector.findLargestPlus(grid, r, c);
                    if (plus != null) {
                        discovered.add(plus);
                    }
                }
            }

            // Verify that every '*' cell was covered by at least one plus.
            boolean allCovered = true;
            for (int r = 0; r < rows && allCovered; r++) {
                for (int c = 0; c < cols; c++) {
                    if (grid.isStar[r][c] && !grid.filled[r][c]) {
                        allCovered = false;
                        break;
                    }
                }
            }

            if (allCovered) {
                out.println(discovered.size());
                for (Plus p : discovered) {
                    // Output uses 1‑based coordinates and the arm length (size)
                    out.printf("%d %d %d%n", p.row + 1, p.col + 1, p.armLength);
                }
            } else {
                out.println("-1");
            }
        }
    }
}

import java.io.*;
import java.util.*;
import java.util.stream.Collectors;

/**
 * Reads a rectangular grid of '.' and 'X' characters, finds for each 'X'
 * the smallest distance to a blocked cell in the four orthogonal directions,
 * stores the position and that distance and finally reports the collection
 * unless some 'X' remains un‑visited – in that case it prints -1.
 *
 * The program follows the same algorithmic behaviour as the original
 * implementation but is written with clearer naming, separated responsibilities
 * and additional comments for readability.
 */
public class Template {

    /** Directions used for scanning neighbours (up, down, left, right). */
    private enum Direction {
        UP(-1, 0),
        DOWN(1, 0),
        LEFT(0, -1),
        RIGHT(0, 1);

        private final int rowDelta;
        private final int colDelta;

        Direction(int rowDelta, int colDelta) {
            this.rowDelta = rowDelta;
            this.colDelta = colDelta;
        }

        int getRowDelta() {
            return rowDelta;
        }

        int getColDelta() {
            return colDelta;
        }
    }

    /** Simple container for a selected cell together with its computed distance. */
    private static final class SelectedCell {
        final int row;   // 1‑based output row
        final int col;   // 1‑based output column
        final int minDist; // smallest distance found in any direction

        SelectedCell(int row, int col, int minDist) {
            this.row = row;
            this.col = col;
            this.minDist = minDist;
        }

        @Override public String toString() {
            return row + " " + col + " " + minDist;
        }
    }

    /** Fast input wrapper (identical to the original FastScanner). */
    private static final class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
            st = new StringTokenizer("");
        }

        private void ensureTokenizer() throws IOException {
            while (!st.hasMoreTokens()) {
                st = new StringTokenizer(br.readLine());
            }
        }

        String next() {
            while (!st.hasMoreTokens()) {
                try {
                    ensureTokenizer();
                } catch (IOException e) {
                    throw new UncheckedIOException(e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }
    }

    /** Entry point – performs all parsing, processing and output. */
    public static void main(String[] args) throws IOException {
        FastScanner sc = new FastScanner();
        PrintWriter out = new PrintWriter(System.out);

        int rows = sc.nextInt();
        int cols = sc.nextInt();
        char[][] grid = readGrid(sc, rows, cols);

        boolean[][] visited = new boolean[rows][cols];
        List<SelectedCell> selectedCells = new ArrayList<>();

        // Scan the whole grid looking for un‑visited 'X' cells.
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == 'X') {
                    int minInAllDirections = computeMinDistance(grid, i, j);
                    if (minInAllDirections > 0) {
                        SelectedCell cell = new SelectedCell(i + 1, j + 1, minInAllDirections);
                        selectedCells.add(cell);
                        markVisitedInAllDirections(grid, visited, i, j, minInAllDirections);
                    }
                }
            }
        }

        // Determine whether any 'X' cell stayed un‑visited.
        boolean allVisited = !hasUnvisitedOne(grid, visited);

        if (allVisited) {
            out.println(selectedCells.size());
            selectedCells.forEach(out::println);
        } else {
            out.println(-1);
        }

        out.close();
    }

    /** Reads the grid from the scanner into a char matrix. */
    private static char[][] readGrid(FastScanner sc, int rows, int cols) {
        char[][] result = new char[rows][];
        for (int i = 0; i < rows; i++) {
            String line = sc.next();
            result[i] = line.toCharArray();
        }
        return result;
    }

    /**
     * Calculates the smallest distance to a different character ('X' or out of bounds)
     * in the four orthogonal directions starting from (r, c). The returned value
     * is the *minimum* of the four distances minus one (mirroring the original
     * implementation).
     */
    private static int computeMinDistance(char[][] grid, int r, int c) {
        int up = countConsecutive(grid, r, c, Direction.UP);
        int down = countConsecutive(grid, r, c, Direction.DOWN);
        int left = countConsecutive(grid, r, c, Direction.LEFT);
        int right = countConsecutive(grid, r, c, Direction.RIGHT);

        int min = Math.min(Math.min(up, down), Math.min(left, right));
        // The original code treats a min of zero as “no valid direction”.
        return min > 0 ? min : 0;
    }

    /**
     * Returns how many consecutive identical cells (including the start cell)
     * exist when moving in the given direction. The returned value corresponds
     * to the original implementation’s “count‑1”.
     */
    private static int countConsecutive(char[][] grid, int startRow, int startCol, Direction dir) {
        int count = 0;
        int row = startRow;
        int col = startCol;
        while (inBounds(grid, row, col) && grid[row][col] == grid[startRow][startCol]) {
            count++;
            row += dir.getRowDelta();
            col += dir.getColDelta();
        }
        // mimic the original "-1" offset
        return Math.max(0, count - 1);
    }

    /** Utility to check whether (r, c) lies inside the matrix. */
    private static boolean inBounds(char[][] grid, int r, int c) {
        return r >= 0 && r < grid.length && c >= 0 && c < grid[0].length;
    }

    /**
     * Marks cells in the four directions up to {@code minDist} steps away
     * (including the starting cell) as visited.
     */
    private static void markVisitedInAllDirections(char[][] grid,
                                                    boolean[][] visited,
                                                    int startRow,
                                                    int startCol,
                                                    int minDist) {
        // Upward
        markDirectionVisited(grid, visited, startRow, startCol,
                Direction.UP, minDist, true);
        // Downward
        markDirectionVisited(grid, visited, startRow, startCol,
                Direction.DOWN, minDist, true);
        // Leftward
        markDirectionVisited(grid, visited, startRow, startCol,
                Direction.LEFT, minDist, true);
        // Rightward
        markDirectionVisited(grid, visited, startRow, startCol,
                Direction.RIGHT, minDist, true);
    }

    /**
     * Helper that walks from (r, c) in {@code dir} until {@code steps} cells
     * (including the start) have been marked visited.
     */
    private static void markDirectionVisited(char[][] grid,
                                              boolean[][] visited,
                                              int startRow,
                                              int startCol,
                                              Direction dir,
                                              int steps,
                                              boolean mark) {
        int row = startRow;
        int col = startCol;
        int visitedCount = -1; // mirrors the original code's initialisation

        while (inBounds(grid, row, col) && visitedCount < steps) {
            visited[row][col] = mark;
            visitedCount++;
            if (visitedCount == steps) {
                break;
            }
            row += dir.getRowDelta();
            col += dir.getColDelta();
        }
    }

    /** Returns true if there exists at least one 'X' cell that has not been visited. */
    private static boolean hasUnvisitedOne(char[][] grid, boolean[][] visited) {
        for (int i = 0; i < grid.length; i++) {
            for (int j = 0; j < grid[i].length; j++) {
                if (grid[i][j] == 'X' && !visited[i][j]) {
                    return true;
                }
            }
        }
        return false;
    }
}

import java.io.*;
import java.util.*;

/**
 * Reads a matrix of '.' and '*', finds all “cross” patterns (arms of equal length ≥ 1)
 * and prints the number of crosses together with their centre position and arm length.
 * If any '*' remains after removing all found crosses the program prints -1.
 */
public class CrossFinder {

    /** Simple container for a detected cross. */
    private static final class Cross {
        final int row;      // 1‑based row of the centre
        final int col;      // 1‑based column of the centre
        final int arm;      // length of each arm (number of cells in one direction)

        Cross(int row, int col, int arm) {
            this.row = row;
            this.col = col;
            this.arm = arm;
        }
    }

    /** Directions in which we compute the maximal continuous '*' length. */
    private static final int[] DR = {1, 0, -1, 0, 1, -1, -1, 1}; // 8 neighbours (not used directly)
    private static final int[] DC = {0, 1, 0, -1, 1, 1, -1, -1};

    /** Fast scanner that works with white‑space separated tokens. */
    private static final class FastReader {
        private final BufferedReader br;
        private StringTokenizer st;

        FastReader() throws IOException {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    throw new UncheckedIOException(e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }
    }

    /** Holds all directional lengths for each cell. */
    private static final class Directions {
        final int[][] rowLen;   // length of continuous '*' upwards
        final int[][] colLen;   // length of continuous '*' leftwards
        final int[][] downLen;  // length of continuous '*' downwards
        final int[][] rightLen; // length of continuous '*' rightwards

        Directions(int[][] rowLen, int[][] colLen, int[][] downLen, int[][] rightLen) {
            this.rowLen = rowLen;
            this.colLen = colLen;
            this.downLen = downLen;
            this.rightLen = rightLen;
        }
    }

    /** Entry point. */
    public static void main(String[] args) throws IOException {
        new CrossFinder().solve();
    }

    /** Main workflow: read → analyse → output. */
    private void solve() throws IOException {
        FastReader sc = new FastReader();
        int rows = sc.nextInt();
        int cols = sc.nextInt();

        int[][] grid = readGrid(sc, rows, cols);
        if (!hasStar(grid)) {
            out.println(0);
            return;
        }

        Directions dirs = computeLengths(grid);
        List<Cross> crosses = findAllCrosses(rows, cols, grid, dirs);

        if (crosses.isEmpty()) {
            out.println(-1);
            return;
        }

        // Remove every detected cross from the grid.
        for (Cross c : crosses) {
            removeCross(grid, c);
        }

        // If any '*' remains the answer is -1, otherwise the list of crosses.
        if (hasStar(grid)) {
            out.println(-1);
        } else {
            out.println(crosses.size());
            for (Cross c : crosses) {
                out.println(c.row + " " + c.col + " " + c.arm);
            }
        }
    }

    /** Reads the matrix and stores it in a 0‑based int array (1 = '*', 0 = '.'). */
    private static int[][] readGrid(FastReader sc, int n, int m) {
        int[][] a = new int[n][m];
        boolean hasStar = false;
        for (int i = 0; i < n; i++) {
            String line = sc.next();
            for (int j = 0; j < m; j++) {
                a[i][j] = line.charAt(j) == '*' ? 1 : 0;
                if (a[i][j] == 1) {
                    hasStar = true;
                }
            }
        }
        // Guard against empty input – should never happen because we checked above.
        if (!hasStar) {
            System.out.println(0);
            System.exit(0);
        }
        return a;
    }

    /** Returns true if there is at least one '*' in the matrix. */
    private static boolean hasStar(int[][] g) {
        for (int[] row : g) {
            for (int cell : row) {
                if (cell == 1) {
                    return true;
                }
            }
        }
        return false;
    }

    /**
     * Pre‑computes for each cell the length of the continuous '*' line
     * in the four orthogonal directions (up, left, down, right).
     */
    private static Directions computeLengths(int[][] a) {
        int n = a.length;
        int m = a[0].length;

        int[][] up = new int[n][m];
        int[][] left = new int[n][m];
        int[][] down = new int[n][m];
        int[][] right = new int[n][m];

        // up
        for (int j = 0; j < m; j++) {
            up[0][j] = a[0][j];
        }
        for (int i = 1; i < n; i++) {
            for (int j = 0; j < m; j++) {
                up[i][j] = (a[i][j] == 0) ? 0 : up[i - 1][j] + 1;
            }
        }

        // left
        for (int i = 0; i < n; i++) {
            left[i][0] = a[i][0];
        }
        for (int i = 0; i < n; i++) {
            for (int j = 1; j < m; j++) {
                left[i][j] = (a[i][j] == 0) ? 0 : left[i][j - 1] + 1;
            }
        }

        // down
        for (int j = 0; j < m; j++) {
            down[n - 1][j] = a[n - 1][j];
        }
        for (int i = n - 2; i >= 0; i--) {
            for (int j = 0; j < m; j++) {
                down[i][j] = (a[i][j] == 0) ? 0 : down[i + 1][j] + 1;
            }
        }

        // right
        for (int j = 0; j < m; j++) {
            right[n - 1][j] = a[n - 1][j];
        }
        for (int i = 0; i < n; i++) {
            for (int j = m - 2; j >= 0; j--) {
                right[i][j] = (a[i][j] == 0) ? 0 : right[i][j + 1] + 1;
            }
        }

        return new Directions(up, left, down, right);
    }

    /** Finds every centre cell that forms a cross of equal arm length ≥ 1. */
    private static List<Cross> findAllCrosses(int n, int m, int[][] grid,
                                              Directions dirs) {
        List<Cross> result = new ArrayList<>();

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                int arm = Math.min(
                        dirs.up[i][j],
                        dirs.left[i][j],
                        Math.min(dirs.down[i][j], dirs.right[i][j])
                );

                if (arm > 1) {
                    result.add(new Cross(i + 1, j + 1, arm - 1)); // store 1‑based indices
                }
            }
        }
        return result;
    }

    /** Erases (sets to 0) all cells belonging to the given cross in the grid. */
    private static void removeCross(int[][] grid, Cross cross) {
        int r = cross.row - 1;      // back to 0‑based
        int c = cross.col - 1;
        int arm = cross.arm;        // number of cells per direction (arms)

        // vertical arm – upwards
        for (int i = 0; i < arm; i++) {
            grid[r - i][c] = 0;
        }
        // vertical arm – downwards
        for (int i = 1; i <= arm; i++) {
            grid[r + i][c] = 0;
        }
        // horizontal arm – leftwards
        for (int i = 0; i < arm; i++) {
            grid[r][c - i] = 0;
        }
        // horizontal arm – rightwards
        for (int i = 1; i <= arm; i++) {
            grid[r][c + i] = 0;
        }
        // centre cell (already cleared by the loops above)
    }

    /** Simple wrapper around System.out to keep the original print statements untouched. */
    private static final PrintWriter out = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)));
}

import java.io.PrintWriter;
import java.io.IOException;
import java.util.ArrayList;
import java.util.List;
import java.util.StringTokenizer;
import java.io.BufferedReader;
import java.io.InputStreamReader;

/**
 * Reads a grid of characters ('*' or '.') and finds all “stars”.
 * A star is defined by a centre cell and a size s≥1 such that in each
 * of the four orthogonal directions there are at least s consecutive '*'
 * cells starting from the centre.  For every star we output its centre
 * (1‑based) and its size, together with the total number of stars.
 * If some '*' cannot be covered by any row or column belonging to a
 * star the program prints –1.
 *
 * The implementation is deliberately split into small, single‑purpose
 * methods and uses expressive names, avoiding static mutable fields.
 */
public class Solution {

    /* --------------------------------------------------------------------- *
     *  Simple data holder for a discovered star
     * --------------------------------------------------------------------- */
    private static final class Star {
        final int row;   // 1‑based output coordinate
        final int col;   // 1‑based output coordinate
        final int size;  // star size (must be > 0)

        Star(int row, int col, int size) {
            this.row = row;
            this.col = col;
            this.size = size;
        }

        @Override
        public String toString() {
            return row + " " + col + " " + size;
        }
    }

    /* --------------------------------------------------------------------- *
     *  Entry point
     * --------------------------------------------------------------------- */
    public static void main(String[] args) throws IOException {
        FastScanner fs = new FastScanner();
        PrintWriter out = new PrintWriter(System.out);

        int tests = 1;                     // the original code expects a single test case
        while (tests-- > 0) {
            int n = fs.nextInt();          // number of rows
            int m = fs.nextInt();          // number of columns
            char[][] grid = new char[n];
            for (int i = 0; i < n; i++) {
                grid[i] = fs.next().toCharArray();
            }

            // ---------- 1. Compute directional accumulators ----------
            int[][] up    = computeUp(grid);
            int[][] down  = computeDown(grid);
            int[][] left  = computeLeft(grid);
            int[][] right = computeRight(grid);

            // ---------- 2. Detect all possible stars ----------
            List<Star> stars = new ArrayList<>();
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    if (grid[i][j] == '*') {
                        int minLength = Math.min(
                                up[i][j],
                                down[i][j],
                                left[i][j],
                                right[i][j]
                        );
                        int s = minLength - 1;                 // maximal legal size
                        if (s > 0) {
                            stars.add(new Star(i + 1, j + 1, s)); // store 1‑based coordinates
                            applyMarkings(stars, up, down, left, right, i, j, s);
                        }
                    }
                }
            }

            // ---------- 3. Verify that every '*' is covered ----------
            if (!isFullyCovered(grid, stars)) {
                out.println(-1);
                out.flush();
                return;
            }

            // ---------- 4. Output ----------
            out.println(stars.size());
            for (Star star : stars) {
                out.println(star);
            }
            out.flush();
        }

        out.close();
    }

    /* --------------------------------------------------------------------- *
     *  Helper methods
     * --------------------------------------------------------------------- */

    /** Upward consecutive '*' count including the current cell. */
    private static int[][] computeUp(char[][] g) {
        int n = g.length, m = g[0].length;
        int[][] up = new int[n][m];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (g[i][j] == '*') {
                    up[i][j] = (i == 0) ? 1 : up[i - 1][j] + 1;
                } else {
                    up[i][j] = 0;
                }
            }
        }
        return up;
    }

    /** Downward consecutive '*' count including the current cell. */
    private static int[][] computeDown(char[][] g) {
        int n = g.length, m = g[0].length;
        int[][] down = new int[n][m];
        for (int i = n - 1; i >= 0; i--) {
            for (int j = 0; j < m; j++) {
                if (g[i][j] == '*') {
                    down[i][j] = (i == n - 1) ? 1 : down[i + 1][j] + 1;
                } else {
                    down[i][j] = 0;
                }
            }
        }
        return down;
    }

    /** Leftward consecutive '*' count including the current cell. */
    private static int[][] computeLeft(char[][] g) {
        int n = g.length, m = g[0].length;
        int[][] left = new int[n][m];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (g[i][j] == '*') {
                    left[i][j] = (j == 0) ? 1 : left[i][j - 1] + 1;
                } else {
                    left[i][j] = 0;
                }
            }
        }
        return left;
    }

    /** Rightward consecutive '*' count including the current cell. */
    private static int[][] computeRight(char[][] g) {
        int n = g.length, m = g[0].length;
        int[][] right = new int[n][m];
        for (int i = 0; i < n; i++) {
            for (int j = m - 1; j >= 0; j--) {
                if (g[i][j] == '*') {
                    right[i][j] = (j == m - 1) ? 1 : right[i][j + 1] + 1;
                } else {
                    right[i][j] = 0;
                }
            }
        }
        return right;
    }

    /**
     * Register the vertical and horizontal increments that a star contributes.
     * The method updates two auxiliary 2‑D difference arrays that are later
     * turned into prefix sums to test coverage.
     */
    private static void applyMarkings(
            List<Star> accumulator,
            int[][] up,
            int[][] down,
            int[][] left,
            int[][] right,
            int centreRow,
            int centreCol,
            int size) {

        // The original code used two 2‑D arrays `h` (vertical) and `w` (horizontal)
        // as difference arrays.  To keep the logic identical we store those
        // structures in static fields of the class (they are cleared at the
        // beginning of each test case).  This mirrors the original behaviour
        // while avoiding the creation of many small temporary arrays.
        //
        // NOTE: The fields are intentionally package‑private to keep the class
        // cohesive and to avoid exposing them publicly.
        incrementVertical(accumulator, centreRow, centreCol, size);
        incrementHorizontal(accumulator, centreRow, centreCol, size);
    }

    /** Updates the vertical (column) difference array for the given star. */
    private static void incrementVertical(List<Star> accumulator,
                                          int centreRow,
                                          int centreCol,
                                          int size) {
        // Convert to 0‑based indices for internal arrays
        int r = centreRow - 1;
        int c = centreCol - 1;
        int top    = r - size;
        int bottom = r + size;

        SolutionFieldHolder.h[top][c]++;                     // +1 at start
        if (bottom + 1 < SolutionFieldHolder.h.length) {
            SolutionFieldHolder.h[bottom + 1][c]--;          // -1 after end
        }
    }

    /** Updates the horizontal (row) difference array for the given star. */
    private static void incrementHorizontal(List<Star> accumulator,
                                            int centreRow,
                                            int centreCol,
                                            int size) {
        int r = centreRow - 1;
        int c = centreCol - 1;
        int left  = c - size;
        int right = c + size;

        SolutionFieldHolder.w[r][left]++;                    // +1 at start
        if (right + 1 < SolutionFieldHolder.w[0].length) {
            SolutionFieldHolder.w[r][right + 1]--;           // -1 after end
        }
    }

    /**
     * After all stars have been processed the two difference arrays (`h` and `w`)
     * are turned into prefix sums.  The resulting boolean tells whether every
     * '*' cell lies on at least one marked row or column.
     */
    private static boolean isFullyCovered(char[][] grid, List<Star> stars) {
        int n = grid.length;
        int m = grid[0].length;

        // Transform the difference arrays into prefix sums
        int[][] rowCoverage = new int[n][m];
        int[][] colCoverage = new int[n][m];

        // Prefix sum over rows for vertical marks (h)
        for (int j = 0; j < m; j++) {
            int running = 0;
            for (int i = 0; i < n; i++) {
                running += SolutionFieldHolder.h[i][j];
                rowCoverage[i][j] = running;
            }
        }

        // Prefix sum over columns for horizontal marks (w)
        for (int i = 0; i < n; i++) {
            int running = 0;
            for (int j = 0; j < m; j++) {
                running += SolutionFieldHolder.w[i][j];
                colCoverage[i][j] = running;
            }
        }

        // Verify that every '*' is covered by at least one row or column line
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i][j] == '*' && rowCoverage[i][j] == 0 && colCoverage[i][j] == 0) {
                    return false;
                }
            }
        }
        return true;
    }

    /* --------------------------------------------------------------------- *
     *  Static auxiliary containers used as difference‑array storage.
     *  They are re‑initialised at the start of each test case (see main()).
     * --------------------------------------------------------------------- */
    /** Vertical (column) difference array – size n × m */
    static int[][] h = new int[0][0];

    /** Horizontal (row) difference array – size n × m */
    static int[][] w = new int[0][0];

    /* --------------------------------------------------------------------- *
     *  Fast input scanner
     * --------------------------------------------------------------------- */
    private static final class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner() {
            this.br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return st.nextToken();
        }

        String nextLine() throws IOException {
            return br.readLine();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        int[] readArray(int n) {
            int[] a = new int[n];
        }
    }
}

import java.io.*;
import java.util.List;
import java.util.ArrayList;
import java.util.StringTokenizer;

/**
 * Refactored solution for problem “E”.
 *
 * <p>
 * The program reads a grid where '*' represents an obstacle.
 * It computes the size of each possible “star” (cross) centred on a '*'
 * and determines whether all obstacles can be eliminated by those stars.
 * If elimination is possible, it prints the number of stars, their
 * 1‑based positions and sizes; otherwise it prints -1.
 * </p>
 */
public final class ProblemE {

    /** Simple container for a star definition. */
    private static final class Star {
        final int row;      // 0‑based
        final int col;      // 0‑based
        final int size;     // star length – 1 (as in the original code)

        Star(int row, int col, int size) {
            this.row = row;
            this.col = col;
            this.size = size;
        }
    }

    public static void main(String[] args) throws IOException {
        // Using try‑with‑resources guarantees streams are closed promptly.
        try (InputStream in = System.in;
             OutputStream out = System.out) {

            Solver solver = new Solver(in, out);
            solver.solve();
        }
    }

    /** Encapsulates all processing logic – makes the code easier to test and maintain. */
    private static final class Solver {
        private final BufferedReader reader;
        private final PrintWriter writer;
        private int rows, cols;
        private char[][] grid;
        private int[][] up, down, left, right;
        private int[][] starSize;
        private final List<Star> stars = new ArrayList<>();

        Solver(BufferedReader reader, PrintWriter writer) {
            this.reader = reader;
            this.writer = writer;
        }

        /** Reads input, performs the computation and prints the result. */
        void solve() throws IOException {
            readInput();
            computeDirectionalLengths();
            computeStarSizes();
            if (!canRemoveAllObstacles()) {
                writer.println(-1);
                writer.flush();
                return;
            }
            writer.println(stars.size());
            for (Star star : stars) {
                writer.printf("%d %d %d%n", star.row + 1, star.col + 1, star.size + 1);
            }
            writer.flush();
        }

        /** Parses the textual input into a char grid. */
        private void readInput() throws IOException {
            StringTokenizer tk = new StringTokenizer(reader.readLine());
            rows = Integer.parseInt(tk.nextToken());
            cols = Integer.parseInt(tk.nextToken());

            grid = new char[rows][];
            for (int r = 0; r < rows; r++) {
                grid[r] = reader.readLine().trim().toCharArray();
            }
        }

        /** Calculates the number of consecutive '*' cells in the four orthogonal directions. */
        private void computeDirectionalLengths() {
            up = new int[rows][cols];
            left = new int[rows][cols];
            down = new int[rows][cols];
            right = new int[rows][cols];

            // Forward scan – up & left
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (grid[r][c] == '*') {
                        up[r][c] = (r == 0) ? 1 : up[r - 1][c] + 1;
                        left[r][c] = (c == 0) ? 1 : left[r][c - 1] + 1;
                    }
                }
            }

            // Backward scan – down & right
            for (int r = rows - 1; r >= 0; r--) {
                for (int c = cols - 1; c >= 0; c--) {
                    if (grid[r][c] == '*') {
                        down[r][c] = (r == rows - 1) ? 1 : down[r + 1][c] + 1;
                        right[r][c] = (c == cols - 1) ? 1 : right[r][c + 1] + 1;
                    }
                }
            }
        }

        /** Determines the size of each star and stores their positions. */
        private void computeStarSizes() {
            starSize = new int[rows][cols];
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (grid[r][c] != '*') {
                        continue;
                    }
                    int minLen = Math.min(up[r][c], down[r][c]);
                    minLen = Math.min(minLen, left[r][c]);
                    minLen = Math.min(minLen, right[r][c]);

                    if (minLen > 1) {
                        int size = minLen - 1;               // size matches original definition
                        starSize[r][c] = size;
                        stars.add(new Star(r, c, size));
                    }
                }
            }
        }

        /**
         * Simulates the removal process of the original program.
         *
         * @return {@code true} if every '*' cell can be turned into '.' after the
         *         simulated elimination; otherwise {@code false}.
         */
        private boolean canRemoveAllObstacles() {
            // Work on a mutable copy of the boolean representation of the grid.
            boolean[][] work = new boolean[rows][cols];
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    work[r][c] = grid[r][c] == '*';
                }
            }

            // Row‑wise elimination (both directions)
            for (int r = 0; r < rows; r++) {
                int toErase = 0;
                for (int c = 0; c < cols; c++) {
                    if (toErase > 0) {
                        toErase--;
                    }
                    if (starSize[r][c] != 0) {
                        toErase = Math.max(toErase, starSize[r][c]);
                    }
                    if (toErase > 0) {
                        work[r][c] = false;
                    }
                }

                toErase = 0;
                for (int c = cols - 1; c >= 0; c--) {
                    if (toErase > 0) {
                        toErase--;
                    }
                    if (starSize[r][c] != 0) {
                        toErase = Math.max(toErase, starSize[r][c]);
                    }
                    if (toErase > 0) {
                        work[r][c] = false;
                    }
                }
            }

            // Column‑wise elimination (both directions)
            for (int c = 0; c < cols; c++) {
                int toErase = 0;
                for (int r = 0; r < rows; r++) {
                    if (toErase > 0) {
                        toErase--;
                    }
                    if (starSize[r][c] != 0) {
                        toErase = Math.max(toErase, starSize[r][c]);
                    }
                    if (toErase > 0) {
                        work[r][c] = false;
                    }
                }

                toErase = 0;
                for (int r = rows - 1; r >= 0; r--) {
                    if (toErase > 0) {
                        toErase--;
                    }
                    if (starSize[r][c] != 0) {
                        toErase = Math.max(toErase, starSize[r][c]);
                    }
                    if (toErase > 0) {
                        work[r][c] = false;
                    }
                }
            }

            // Verify that no obstacle remains.
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (work[r][c]) {
                        return false;
                    }
                }
            }
            return true;
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Main class of the application.  It reads a rectangular grid of characters,
 * detects “crosses” formed by consecutive ‘1’ cells in the four orthogonal
 * directions, prints information about each detected cross and finally checks
 * that every ‘1’ belongs to some cross.
 *
 * The program has been refactored to improve readability, maintainability and
 * separation of concerns.
 */
public class Main {

    /** Directional constants used for the four sweep‑through passes. */
    private static final int LEFT = 0;
    private static final int RIGHT = 1;
    private static final int UP = 2;
    private static final int DOWN = 3;

    /** Holds the data for a single discovered cross. */
    private static final class Cross {
        final int row;          // 0‑based row index
        final int col;          // 0‑based column index
        final int size;         // length of the arm (after the decrement step)

        Cross(int row, int col, int size) {
            this.row = row;
            this.col = col;
            this.size = size;
        }

        @Override public String toString() {
            // Output format matches the original program:
            //   row+1  col+1  size (the decremented arm length)
            return String.format("%d %d %d%n", row + 1, col + 1, size);
        }
    }

    /** Simple wrapper around a BufferedReader that provides tokenised input. */
    private static final class TokenReader {
        private final BufferedReader br;
        private StringTokenizer tokenizer;

        /** Initialise with the standard input stream. */
        static TokenReader init(System input) {
            return new TokenReader(new BufferedReader(new InputStreamReader(input)));
        }

        /** Initialise with a FileReader (not used in this program). */
        static TokenReader init(FileReader file) {
            return new TokenReader(new BufferedReader(file));
        }

        private TokenReader(BufferedReader br) {
            this.br = br;
            tokenizer = new StringTokenizer("");
        }

        /** Return the next token, reading a new line if the current one is exhausted. */
        String nextToken() throws IOException {
            while (!tokenizer.hasMoreTokens()) {
                tokenizer = new StringTokenizer(br.readLine());
            }
            return tokenizer.nextToken();
        }

        /** Convenience wrappers for the primitive types used by the original code. */
        int nextInt() throws IOException { return Integer.parseInt(nextToken()); }
        long nextLong() throws IOException { return Long.parseLong(nextToken()); }
        float nextFloat() throws IOException { return Float.parseFloat(nextToken()); }
        double nextDouble() throws IOException { return Double.parseDouble(nextToken()); }
        String nextLine() throws IOException { return br.readLine(); }
    }

    /**
     * Reads the whole input and builds an integer matrix where 1 represents a
     * “*” (star) cell and 0 represents a “.” (empty) cell.
     */
    private static int[][] readGrid(TokenReader tr, int rows, int cols) throws IOException {
        int[][] grid = new int[rows][cols];
        for (int r = 0; r < rows; r++) {
            String line = tr.nextLine();
            for (int c = 0; c < cols; c++) {
                grid[r][c] = (line.charAt(c) == '*') ? 1 : 0;
            }
        }
        return grid;
    }

    /**
     * Performs four passes over {@code grid} to compute, for each cell that
     * contains a ‘1’, the length of the continuous run of ‘1’s in each
     * orthogonal direction.
     *
     * @return an array {@code counts[dir][row][col]} where {@code dir}
     *         corresponds to LEFT, RIGHT, UP or DOWN.
     */
    private static int[][][] computeDirectionalCounts(int[][] grid) {
        int n = grid.length;
        int m = grid[0].length;
        int[][][] counts = new int[4][n][m];   // 0: left, 1: right, 2: up, 3: down

        // ----- left → right ----------------------------------------------------
        for (int r = 0; r < n; r++) {
            for (int c = 0; c < m; c++) {
                if (grid[r][c] == 1) {
                    counts[LEFT][r][c] = (c == 0) ? 1 : counts[LEFT][r][c - 1] + 1;
                } else {
                    counts[LEFT][r][c] = 0;
                }
            }
        }

        // ----- right → left ----------------------------------------------------
        for (int r = 0; r < n; r++) {
            for (int c = m - 1; c >= 0; c--) {
                if (grid[r][c] == 1) {
                    counts[RIGHT][r][c] = (c == m - 1) ? 1 : counts[RIGHT][r][c + 1] + 1;
                } else {
                    counts[RIGHT][r][c] = 0;
                }
            }
        }

        // ----- top → bottom ----------------------------------------------------
        for (int c = 0; c < m; c++) {
            for (int r = 0; r < n; r++) {
                if (grid[r][c] == 1) {
                    counts[UP][r][c] = (r == 0) ? 1 : counts[UP][r - 1][c] + 1;
                } else {
                    counts[UP][r][c] = 0;
                }
            }
        }

        // ----- bottom → top ----------------------------------------------------
        for (int c = 0; c < m; c++) {
            for (int r = n - 1; r >= 0; r--) {
                if (grid[r][c] == 1) {
                    counts[DOWN][r][c] = (r == n - 1) ? 1 : counts[DOWN][r + 1][c] + 1;
                } else {
                    counts[DOWN][r][c] = 0;
                }
            }
        }

        return counts;
    }

    /**
     * Detects all cross‑shaped patterns in the matrix.
     *
     * A cross is identified when a cell has at least length {@code s+1}
     * consecutive ‘1’s in each of the four directions; after decrementing
     * {@code s} becomes the arm length.  For each discovered cross we store
     * its centre, its arm length and we also mark the cells belonging to that
     * cross in a separate boolean matrix {@code marked}.
     *
     * @return a list of {@link Cross} objects.
     */
    private static List<Cross> discoverCrosses(int[][] grid,
                                               int[][][] counts,
                                               boolean[][] marked) {
        List<Cross> crosses = new ArrayList<>();
        int n = grid.length;
        int m = grid[0].length;

        for (int r = 0; r < n; r++) {
            for (int c = 0; c < m; c++) {
                if (grid[r][c] != 1) {
                    continue;                       // nothing to do on empty cells
                }

                // The smallest arm length among the four directions.
                int arm = Math.min(
                        Math.min(counts[LEFT][r][c], counts[RIGHT][r][c]),
                        Math.min(counts[UP][r][c], counts[DOWN][r][c])
                );

                if (arm <= 1) {
                    continue;                       // need at least a 2‑cell arm
                }

                int size = arm - 1;                   // the decremented size used for output
                crosses.add(new Cross(r, c, size));

                // Mark the whole cross (+ shape) in the auxiliary matrix.
                int half = size;
                for (int rr = r - half; rr <= r + half; rr++) {
                    marked[rr][c] = true;
                }
                for (int cc = c - half; cc <= c + half; cc++) {
                    marked[r][cc] = true;
                }
            }
        }
        return crosses;
    }

    /**
     * Verifies that every ‘1’ cell in the original grid belongs to at least one
     * discovered cross.  If any ‘1’ remains unmarked, the method returns {@code false}
     * signalling that the input configuration is invalid and the program must
     * output {@code -1}.
     */
    private static boolean allOnesAreMarked(int[][] grid, boolean[][] marked) {
        for (int r = 0; r < grid.length; r++) {
            for (int c = 0; c < grid[0].length; c++) {
                if (grid[r][c] == 1 && !marked[r][c]) {
                    return false;
                }
            }
        }
        return true;
    }

    /** Entry point – mirrors the behaviour of the original program. */
    public static void main(String[] args) throws Exception {
        TokenReader reader = TokenReader.init(System.in);

        int n = reader.nextInt();          // number of rows
        int m = reader.nextInt();          // number of columns
        int[][] grid = readGrid(reader, n, m);

        // 1. Compute runs of consecutive ‘1’s in the four directions.
        int[][][] directionalCounts = computeDirectionalCounts(grid);

        // 2. Prepare a matrix that will be used to mark cells belonging to a cross.
        boolean[][] marked = new boolean[n][m];

        // 3. Find all crosses and simultaneously fill {@code marked}.
        List<Cross> discovered = discoverCrosses(grid, directionalCounts, marked);

        // 4. Validate that every ‘1’ is part of some cross.
        boolean configurationValid = allOnesAreMarked(grid, marked);

        // 5. Output according to the specification.
        try (PrintWriter out = new PrintWriter(System.out)) {
            if (!configurationValid) {
                out.println(-1);
                return;
            }

            out.println(discovered.size());
            for (Cross cross : discovered) {
                out.print(cross);
            }
        }

        reader.close();   // close the underlying BufferedReader
    }
}

import java.io.*;
import java.util.ArrayList;
import java.util.List;

/**
 * Refactored solution that keeps the original algorithmic behaviour
 * but improves readability, naming, structure and resource handling.
 */
public final class Solution {

    /* --------------------------------------------------------------------- */
    /*  Constants & Fields                                                    */
    /* --------------------------------------------------------------------- */
    private static final long MOD = 1_000_000_007L;
    private static final String TOKEN_DELIM = " ";

    private BufferedReader reader;
    private StringTokenizer tokenizer;

    /* --------------------------------------------------------------------- */
    /*  Entry point                                                          */
    /* --------------------------------------------------------------------- */
    public static void main(String[] args) throws Exception {
        new Solution().solve();
    }

    /* --------------------------------------------------------------------- */
    /*  Public solving method                                                 */
    /* --------------------------------------------------------------------- */
    private void solve() throws IOException {
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in))) {
            initReader(br);
            int n = readInt();
            int m = readInt();

            int[][] org = readOrgGrid(n, m);
            DirectionalCounters dirs = computeDirectionalCounters(org);

            List<StarInfo> stars = findStars(org, dirs);
            if (!validateCoverage(org, stars)) {
                System.out.println(-1);
                return;
            }

            StringBuilder out = new StringBuilder();
            out.append(stars.size()).append('\n');
            for (StarInfo s : stars) {
                out.append(s.row).append(' ')
                   .append(s.col).append(' ')
                   .append(s.maxRadius).append('\n');
            }
            System.out.print(out);
        }
    }

    /* --------------------------------------------------------------------- */
    /*  Input helpers                                                         */
    /* --------------------------------------------------------------------- */
    private void initReader(BufferedReader br) {
        this.reader = br;
        this.tokenizer = null;
    }

    private String readLine() throws IOException {
        return tokenizer == null ? nextLine() : tokenizer.nextToken();
    }

    private String nextLine() throws IOException {
        return reader.readLine();
    }

    private String nextToken() throws IOException {
        if (tokenizer == null || !tokenizer.hasMoreTokens()) {
            tokenizer = new StringTokenizer(readLine(), TOKEN_DELIM);
        }
        return tokenizer.nextToken();
    }

    private int readInt() throws IOException {
        return Integer.parseInt(nextToken());
    }

    /* --------------------------------------------------------------------- */
    /*  Grid reading                                                          */
    /* --------------------------------------------------------------------- */
    /**
     * Reads the grid and builds the {@code org} matrix (1 for '*', 0 otherwise).
     */
    private int[][] readOrgGrid(int n, int m) {
        int[][] org = new int[n][m];
        for (int i = 0; i < n; i++) {
            String line = readLine();
            for (int j = 0; j < m; j++) {
                org[i][j] = (line.charAt(j) == '*') ? 1 : 0;
            }
        }
        return org;
    }

    /* --------------------------------------------------------------------- */
    /*  Directional counters (prefix sums)                                    */
    /* --------------------------------------------------------------------- */
    /**
     * Computes four directional prefix‑sum matrices that count how many
     * consecutive stars exist upwards, downwards, leftwards and rightwards
     * from each cell (including the cell itself).
     */
    private static DirectionalCounters computeDirectionalCounters(int[][] org) {
        int n = org.length;
        int m = org[0].length;

        int[][] up    = new int[n][m];
        int[][] down  = new int[n][m];
        int[][] left  = new int[n][m];
        int[][] right = new int[n][m];
        int[][] copy  = new int[n][m];   // a copy of {@code org} used for init

        // initialise all four directional matrices with the star indicator
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (org[i][j] == 1) {
                    up[i][j] = down[i][j] = left[i][j] = right[i][j] = copy[i][j] = 1;
                }
            }
        }

        // upward propagation
        for (int i = 1; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (up[i - 1][j] > 0 && up[i][j] > 0) {
                    up[i][j] += up[i - 1][j];
                }
            }
        }

        // leftward propagation
        for (int i = 0; i < n; i++) {
            for (int j = 1; j < m; j++) {
                if (left[i][j - 1] > 0 && left[i][j] > 0) {
                    left[i][j] += left[i][j - 1];
                }
            }
        }

        // downward propagation
        for (int i = n - 2; i >= 0; i--) {
            for (int j = 0; j < m; j++) {
                if (down[i + 1][j] > 0 && down[i][j] > 0) {
                    down[i][j] += down[i + 1][j];
                }
            }
        }

        // rightward propagation
        for (int i = 0; i < n; i++) {
            for (int j = m - 2; j >= 0; j--) {
                if (right[i][j + 1] > 0 && right[i][j] > 0) {
                    right[i][j] += right[i][j + 1];
                }
            }
        }

        return new DirectionalCounters(up, down, left, right, copy);
    }

    /* --------------------------------------------------------------------- */
    /*  Star discovery                                                        */
    /* --------------------------------------------------------------------- */
    /**
     * Collects all stars that can be the centre of a "cross" whose arm length
     * equals the smallest of the four directional counts minus one.
     */
    private List<StarInfo> findStars(int[][] org, DirectionalCounters dirs) {
        List<StarInfo> result = new ArrayList<>();
        int n = org.length;
        int m = org[0].length;

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (org[i][j] != 1) {
                    continue;
                }

                int maxUp    = dirs.up[i][j] - 1;
                int maxDown  = dirs.down[i][j] - 1;
                int maxLeft  = dirs.left[i][j] - 1;
                int maxRight = dirs.right[i][j] - 1;

                int radius = Math.min(Math.min(maxUp, maxDown), Math.min(maxLeft, maxRight));
                if (radius > 0) {
                    result.add(new StarInfo(i + 1, j + 1, radius));
                }
            }
        }
        return result;
    }

    /* --------------------------------------------------------------------- */
    /*  Coverage validation                                                   */
    /* --------------------------------------------------------------------- */
    /**
     * Verifies that the union of all cross‑shapes exactly reproduces the
     * original star pattern.  If any cell is covered where there is no star,
     * or a star is left uncovered, the method returns {@code false}.
     */
    private boolean validateCoverage(int[][] org, List<StarInfo> stars) {
        int n = org.length;
        int m = org[0].length;
        int[][] cover = new int[n][m];

        for (StarInfo s : stars) {
            int r = s.maxRadius;
            int i = s.row - 1;
            int j = s.col - 1;

            // horizontal arm
            for (int c = j - r; c <= j + r; c++) {
                if (c >= 0 && c < m) {
                    cover[i][c] = 1;
                }
            }
            // vertical arm
            for (int row = i - r; row <= i + r; row++) {
                if (row >= 0 && row < n) {
                    cover[row][j] = 1;
                }
            }
        }

        // final comparison – the cover matrix must be identical to the original
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (cover[i][j] != org[i][j]) {
                    return false;
                }
            }
        }
        return true;
    }

    /* --------------------------------------------------------------------- */
    /*  Data carrier classes                                                   */
    /* --------------------------------------------------------------------- */
    /**
     * Holds information about a discovered star.
     */
    private static final class StarInfo {
        final int row;      // 1‑based
        final int col;      // 1‑based
        final int maxRadius;

        StarInfo(int row, int col, int maxRadius) {
            this.row = row;
            this.col = col;
            this.maxRadius = maxRadius;
        }
    }

    /**
     * Container for the four directional prefix‑sum matrices and the original
     * star indicator matrix.
     */
    private static final class DirectionalCounters {
        final int[][] up;
        final int[][] down;
        final int[][] left;
        final int[][] right;
        final int[][] org;

        DirectionalCounters(int[][] up, int[][] down, int[][] left,
                            int[][] right, int[][] org) {
            this.up = up;
            this.down = down;
            this.left = left;
            this.right = right;
            this.org = org;
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Refactored solution that is easier to read, maintain and extend.
 * The algorithm is identical to the original implementation but
 * organized into small, self‑contained components.
 */
public class Main {

    /** Simple interval holder used for merging overlapping ranges. */
    private static final class Interval implements Comparable<Interval> {
        final int start;
        final int end;

        Interval(int start, int end) {
            this.start = start;
            this.end = end;
        }

        @Override
        public int compareTo(@NotNull Interval o) {
            return Integer.compare(this.start, o.start);
        }
    }

    /** One star with its position and radius (half‑length of each arm). */
    private static final class Star {
        final int row;
        final int col;
        final int radius; // length of each arm

        Star(int row, int col, int radius) {
            this.row = row;
            this.col = col;
            this.radius = radius;
        }

        int getRow() { return row; }
        int getCol() { return col; }
        int getRadius() { return radius; }

        @Override
        public String toString() {
            return row + " " + col + " " + radius;
        }
    }

    /** Directions used for DP accumulation. */
    private enum Direction {
        LEFT(0, -1), RIGHT(0, 1), UP(-1, 0), DOWN(1, 0);
        final int dr, dc;
        Direction(int dr, int dc) { this.dr = dr; this.dc = dc; }
    }

    /** Fast line/token scanner. */
    private static final class InputReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        InputReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream), 32768);
        }

        String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        int nextInt() { return Integer.parseInt(next()); }
        String nextLine() { try { return reader.readLine(); } catch (IOException e) { throw new RuntimeException(e); } return ""; }
    }

    public static void main(String[] args) {
        InputReader in = new InputReader(System.in);
        int n = in.nextInt();
        int m = in.nextInt();

        String[] grid = new String[n];
        for (int i = 0; i < n; i++) {
            grid[i] = in.nextLine().trim();
        }

        // dp[row][col][dir] = number of consecutive '*' adjacent in direction dir
        int[][][] dp = new int[n][m][Direction.values().length];

        // ----- fill left / right counts per row -----
        for (int r = 0; r < n; r++) {
            // leftwards
            for (int c = 1; c < m; c++) {
                dp[r][c][Direction.LEFT.ordinal()] = (grid[r].charAt(c - 1) == '*')
                        ? dp[r][c - 1][Direction.LEFT.ordinal()] + 1 : 0;
            }
            // rightwards (process backwards)
            for (int c = m - 2; c >= 0; c--) {
                dp[r][c][Direction.RIGHT.ordinal()] = (grid[r].charAt(c + 1) == '*')
                        ? dp[r][c + 1][Direction.RIGHT.ordinal()] + 1 : 0;
            }
        }

        // ----- fill up / down counts per column -----
        for (int c = 0; c < m; c++) {
            // upwards
            for (int r = 1; r < n; r++) {
                dp[r][c][Direction.UP.ordinal()] = (grid[r - 1].charAt(c) == '*')
                        ? dp[r - 1][c][Direction.UP.ordinal()] + 1 : 0;
            }
            // downwards (process backwards)
            for (int r = n - 2; r >= 0; r--) {
                dp[r][c][Direction.DOWN.ordinal()] = (grid[r + 1].charAt(c) == '*')
                        ? dp[r + 1][c][Direction.DOWN.ordinal()] + 1 : 0;
            }
        }

        // ----- collect stars and store intervals for coverage marking -----
        List<Star> stars = new ArrayList<>();
        @SuppressWarnings("unchecked")
        List<Interval>[] rowIntervals = new List[n];   // intervals of columns per row
        @SuppressWarnings("unchecked")
        List<Interval>[] colIntervals = new List[m];   // intervals of rows per column
        for (int i = 0; i < n; i++) rowIntervals[i] = new ArrayList<>();
        for (int i = 0; i < m; i++) colIntervals[i] = new ArrayList<>();

        for (int r = 0; r < n; r++) {
            for (int c = 0; c < m; c++) {
                if (grid[r].charAt(c) != '*') continue;

                int left = dp[r][c][Direction.LEFT.ordinal()];
                int right = dp[r][c][Direction.RIGHT.ordinal()];
                int up = dp[r][c][Direction.UP.ordinal()];
                int down = dp[r][c][Direction.DOWN.ordinal()];
                int radius = Math.min(Math.min(left, right), Math.min(up, down));

                if (radius > 0) {
                    stars.add(new Star(r, c, radius));

                    // interval of columns covered by this star in its row
                    int colStart = c - radius;
                    int colEnd   = c + radius;
                    rowIntervals[r].add(new Interval(colStart, colEnd));

                    // interval of rows covered by this star in its column
                    int rowStart = r - radius;
                    int rowEnd   = r + radius;
                    colIntervals[c].add(new Interval(rowStart, rowEnd));
                }
            }
        }

        // ----- mark all covered cells -----
        boolean[][] covered = new boolean[n][m];

        // mark columns covered in each row
        for (int r = 0; r < n; r++) {
            List<Interval> list = rowIntervals[r];
            if (list.isEmpty()) continue;

            list.sort(Interval::compareTo);
            int curEnd = -1;
            for (Interval iv : list) {
                int start = Math.max(iv.start, curEnd + 1);
                int end   = iv.end;
                if (start <= end) {
                    for (int col = start; col <= end; col++) {
                        covered[r][col] = true;
                    }
                }
                curEnd = Math.max(curEnd, end);
            }
        }

        // mark rows covered in each column
        for (int c = 0; c < m; c++) {
            List<Interval> list = colIntervals[c];
            if (list.isEmpty()) continue;

            list.sort(Interval::compareTo);
            int curEnd = -1;
            for (Interval iv : list) {
                int start = Math.max(iv.start, curEnd + 1);
                int end   = iv.end;
                if (start <= end) {
                    for (int row = start; row <= end; row++) {
                        covered[row][c] = true;
                    }
                }
                curEnd = Math.max(curEnd, end);
            }
        }

        // ----- validation: every '*' must be covered -----
        for (int r = 0; r < n; r++) {
            for (int c = 0; c < m; c++) {
                if (grid[r].charAt(c) == '*' && !covered[r][c]) {
                    System.out.println(-1);
                    return;
                }
            }
        }

        // ----- output answer -----
        PrintWriter out = new PrintWriter(System.out);
        out.println(stars.size());
        for (Star s : stars) {
            out.println((s.getRow() + 1) + " " + (s.getCol() + 1) + " " + s.getRadius());
        }
        out.close();
    }
}

import java.io.*;
import java.util.*;

public class E1015 {

    public static void main(String[] args) {
        FastScanner fs = new FastScanner();
        int n = fs.nextInt();
        int m = fs.nextInt();

        char[][] grid = new char[n][];
        for (int i = 0; i < n; i++) {
            grid[i] = fs.nextLine().toCharArray();
        }

        Processor processor = new Processor(grid);
        Result result = processor.process();

        System.out.println(result.isSolvable()
                ? result.totalStars() + "\n" + result.linesJoined()
                : -1);
    }

    /* ----------------------------------------------------- */
    /** Fast scanner that preserves the original performance tricks. */
    private static final class FastScanner {
        private final byte[] buffer = new byte[1 << 10];
        private int ptr = 0, len = 0;

        private int readByte() {
            if (ptr >= len) {
                len = System.in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        private boolean isSpace(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        private boolean isEndOfLine(int c) {
            return c == '\n' || c == '\r' || c == -1;
        }

        String nextLine() {
            int c;
            do { c = readByte(); } while (c != -1 && !isEndOfLine(c) && isSpace(c));
            StringBuilder sb = new StringBuilder();
            do {
                sb.append((char) c);
                c = readByte();
            } while (c != -1 && !isSpace(c));
            return sb.toString();
        }

        int nextInt() {
            int c;
            do { c = readByte(); } while (c != -1 && isSpace(c));
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = readByte();
            }
            int value = 0;
            while (c >= '0' && c <= '9') {
                value = value * 10 + (c - '0');
                c = readByte();
            }
            return value * sign;
        }
    }

    /* ----------------------------------------------------- */
    /** Four possible laser directions. */
    private enum Direction {
        UP(-1, 0), LEFT(0, -1), RIGHT(0, 1), DOWN(1, 0);
        private final int dr, dc;
        Direction(int dr, int dc) { this.dr = dr; this.dc = dc; }

        int[] offset() { return new int[]{dr, dc}; }
    }

    /* ----------------------------------------------------- */
    /** Holds the contiguous‑star counts for a single '*' cell. */
    private static final class StarInfo {
        private final int[] counts = new int[4]; // UP, LEFT, RIGHT, DOWN

        StarInfo(char[][] grid, int row, int col, int n, int m) {
            for (int i = 0; i < 4; i++) {
                counts[i] = countInDirection(grid, row, col, Direction.values()[i], n, m);
            }
        }

        /** Returns the maximal length of a square "laser" that can start here. */
        int startLength() {
            if (!isValid()) return 0;
            return Math.min(Math.min(counts[0], counts[1]), Math.min(counts[2], counts[3]));
        }

        /** All four directions must contain at least one '*'. */
        boolean isValid() {
            return counts[0] > 0 && counts[1] > 0 && counts[2] > 0 && counts[3] > 0;
        }

        /** Count continuous '*' starting from (row,col) stepping in the given direction. */
        private static int countInDirection(char[][] grid,
                                            int r, int c,
                                            Direction dir,
                                            int n, int m) {
            int cnt = 0;
            int nr = r + dir.dr;
            int nc = c + dir.dc;
            while (inside(nr, nc, n, m) && grid[nr][nc] == '*') {
                cnt++;
                nr += dir.dr;
                nc += dir.dc;
            }
            return cnt;
        }

        private static boolean inside(int r, int c, int n, int m) {
            return r >= 0 && r < n && c >= 0 && c < m;
        }
    }

    /* ----------------------------------------------------- */
    /** Aggregates the processing result (found lasers + validation). */
    private static final class Result {
        private final List<String> outputLines = new ArrayList<>();
        private final int processedStars;
        private final boolean solvable;

        Result(int processedStars, boolean solvable) {
            this.processedStars = processedStars;
            this.solvable = solvable;
        }

        void addResultLine(int i, int j, int length) {
            outputLines.add(i + 1 + " " + j + 1 + " " + length);
        }

        /** Total number of lasers that were successfully placed. */
        int totalStars() {
            return processedStars;
        }

        /** True if after all placements no '*' remain. */
        boolean isSolvable() {
            return solvable;
        }

        /** All result lines joined by '\n' with a trailing newline. */
        String linesJoined() {
            return String.join("\n", outputLines) + "\n";
        }
    }

    /* ----------------------------------------------------- */
    /** Core algorithm: locate lasers, mark them, and validate the final grid. */
    private static final class Processor {
        private final char[][] originalGrid;
        private final int n, m;

        Processor(char[][] grid) {
            this.originalGrid = grid;
            this.n = grid.length;
            this.m = grid[0].length;
        }

        Result process() {
            char[][] workGrid = Arrays.stream(originalGrid)
                    .map(String::toCharArray)
                    .toArray(char[][]::new);
            Result result = new Result(0, true);

            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    if (workGrid[i][j] != '*') continue;

                    StarInfo info = new StarInfo(workGrid, i, j, n, m);
                    if (!info.isValid()) continue;

                    int length = info.startLength();
                    if (length == 0) continue;

                    // Record the found laser
                    result.addResultLine(i, j, length);
                    result.processedStars++;

                    // Mark the whole laser path with '#'
                    markLaserPath(workGrid, i, j, length);
                }
            }

            // After all placements, verify that the grid contains no remaining '*'
            result.solvable = !Arrays.stream(workGrid)
                    .anyMatch(row -> Arrays.stream(row).anyMatch(ch -> ch == '*'));

            return result;
        }

        /** Marks the starting cell and the four arms of length steps each. */
        private void markLaserPath(char[][] grid, int row, int col, int length) {
            // centre cell
            grid[row][col] = '#';

            // up arm
            int r = row;
            for (int s = 0; s < length; s++) {
                r--;
                grid[r][col] = '#';
            }

            // left arm
            int c = col;
            for (int s = 0; s < length; s++) {
                c--;
                grid[row][c] = '#';
            }

            // right arm
            c = col;
            for (int s = 0; s < length; s++) {
                c++;
                grid[row][c] = '#';
            }

            // down arm
            r = row;
            for (int s = 0; s < length; s++) {
                r++;
                grid[r][col] = '#';
            }
        }
    }
}

import java.io.*;
import java.util.*;
import java.util.stream.Collectors;

/**
 * Refactored solution for the “Stars Drawing” problem (CF 1015E).
 *
 * The program:
 *   1. Reads a grid of '*' and '.' characters.
 *   2. Computes, for every '*', how far it extends consecutively in the four
 *      directions (left, right, up, down).
 *   3. Determines the largest “diamond” that can be centred at each '*'
 *      without crossing a '.'.
 *   4. Uses two segment‑trees (row‑wise and column‑wise) to verify that every
 *      cell that belongs to a maximal diamond is actually covered by at
 *      least one maximal centre.
 *   5. Outputs all maximal diamonds or -1 if the configuration is impossible.
 *
 * The code is deliberately split into small, well‑named methods and uses
 * meaningful identifiers, try‑with‑resources and a clean SegmentTree
 * implementation.
 */
public class StarsDrawingSolution {

    /** Directional accumulators – see {@link #computeDirectionalAccumulations}. */
    private static class Directional {
        final int[][] left;   // from left to right
        final int[][] right;  // from right to left
        final int[][] up;     // from top to bottom
        final int[][] down;   // from bottom to top

        Directional(int[][] left, int[][] right, int[][] up, int[][] down) {
            this.left = left;
            this.right = right;
            this.up = up;
            this.down = down;
        }
    }

    /** Main entry point – keeps the original I/O signature but uses modern Java features. */
    public static void main(String[] args) throws IOException {
        // -----------------------------------------------------------------
        // 1️⃣  Input handling (try‑with‑resources makes sure everything is closed)
        // -----------------------------------------------------------------
        try (Scanner scanner = new Scanner(System.in);
             PrintWriter out = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out))) ) {

            int rows = scanner.nextInt();
            int cols = scanner.nextInt();

            char[][] grid = readGrid(scanner, rows, cols);
            Directional dirs = computeDirectionalAccumulations(grid, rows, cols);

            // -----------------------------------------------------------------
            // 2️⃣  Determine the largest possible diamond size for each '*'
            // -----------------------------------------------------------------
            int[][] maxDiamonds = computeMaxDiamonds(grid, dirs, rows, cols);

            // -----------------------------------------------------------------
            // 3️⃣  Build segment‑trees that allow us to verify coverage later
            // -----------------------------------------------------------------
            SegmentTree[] rowTrees = buildRowSegmentTrees(maxDiamonds, rows, cols);
            SegmentTree[] colTrees = buildColumnSegmentTrees(maxDiamonds, rows, cols);

            // -----------------------------------------------------------------
            // 4️⃣  Verify that every cell belonging to a maximal diamond is covered
            // -----------------------------------------------------------------
            boolean configurationPossible = verifyCoverage(rowTrees, colTrees, maxDiamonds, rows, cols);

            // -----------------------------------------------------------------
            // 5️⃣  Produce the required output
            // -----------------------------------------------------------------
            if (!configurationPossible) {
                out.println(-1);
            } else {
                List<String> result = collectOutput(maxDiamonds, rows, cols);
                out.println(result.size());
                out.print(result.stream().collect(Collectors.joining(System.lineSeparator())));
            }

            out.flush();               // ensure everything is written
        }
    }

    // -------------------------------------------------------------------------
    // 1️⃣  Reading the grid
    // -------------------------------------------------------------------------
    private static char[][] readGrid(Scanner scanner, int rows, int cols) {
        char[][] grid = new char[rows][cols];
        for (int i = 0; i < rows; i++) {
            String line = scanner.next();
            System.arraycopy(line.toCharArray(), 0, grid[i], 0, cols);
        }
        return grid;
    }

    // -------------------------------------------------------------------------
    // 2️⃣  Computing directional consecutive counts
    // -------------------------------------------------------------------------
    private static Directional computeDirectionalAccumulations(char[][] grid, int rows, int cols) {
        int[][] left  = new int[rows][cols];
        int[][] right = new int[rows][cols];
        int[][] up    = new int[rows][cols];
        int[][] down  = new int[rows][cols];

        // left → right
        for (int r = 0; r < rows; r++) {
            int cnt = 0;
            for (int c = 0; c < cols; c++) {
                cnt = grid[r][c] == '*' ? cnt + 1 : 0;
                left[r][c] = cnt;
            }
        }

        // right → left
        for (int r = 0; r < rows; r++) {
            int cnt = 0;
            for (int c = cols - 1; c >= 0; c--) {
                cnt = grid[r][c] == '*' ? cnt + 1 : 0;
                right[r][c] = cnt;
            }
        }

        // top → bottom
        for (int c = 0; c < cols; c++) {
            int cnt = 0;
            for (int r = 0; r < rows; r++) {
                cnt = grid[r][c] == '*' ? cnt + 1 : 0;
                up[r][c] = cnt;
            }
        }

        // bottom → top
        for (int c = 0; c < cols; c++) {
            int cnt = 0;
            for (int r = rows - 1; r >= 0; r--) {
                cnt = grid[r][c] == '*' ? cnt + 1 : 0;
                down[r][c] = cnt;
            }
        }

        return new Directional(left, right, up, down);
    }

    // -------------------------------------------------------------------------
    // 3️⃣  Finding the maximal diamond size at each '*'
    // -------------------------------------------------------------------------
    private static int[][] computeMaxDiamonds(char[][] grid, Directional dirs, int rows, int cols) {
        int[][] maxDiamonds = new int[rows][cols];

        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] != '*') {
                    continue;
                }

                // The smallest of the four directional lengths determines the
                // radius of the largest centred diamond (minus 1 because the centre
                // itself is also counted).
                int radius = Math.min(
                        Math.min(dirs.left[r][c], dirs.right[r][c]),
                        Math.min(dirs.up[r][c], dirs.down[r][c])
                ) - 1;

                maxDiamonds[r][c] = Math.max(maxDiamonds[r][c], radius);
            }
        }
        return maxDiamonds;
    }

    // -------------------------------------------------------------------------
    // 4️⃣  Building segment‑trees for rows and columns (range‑add, point‑query)
    // -------------------------------------------------------------------------
    private static SegmentTree[] buildRowSegmentTrees(int[][] maxDiamonds, int rows, int cols) {
        SegmentTree[] trees = new SegmentTree[rows];
        int size = nearestPowerOfTwo(cols);

        for (int r = 0; r < rows; r++) {
            trees[r] = new SegmentTree(size);
            for (int c = 0; c < cols; c++) {
                int radius = maxDiamonds[r][c];
                if (radius <= 0) {
                    continue;
                }
                // The diamond influences a symmetric interval around the centre.
                int from = c + 1 - radius; // 1‑based inclusive start
                int to   = c + 1 + radius; // 1‑based inclusive end
                trees[r].updateRange(from, to, 1);
            }
        }
        return trees;
    }

    private static SegmentTree[] buildColumnSegmentTrees(int[][] maxDiamonds, int rows, int cols) {
        SegmentTree[] trees = new SegmentTree[cols];
        int size = nearestPowerOfTwo(rows);

        for (int c = 0; c < cols; c++) {
            trees[c] = new SegmentTree(size);
            for (int r = 0; r < rows; r++) {
                int radius = maxDiamonds[r][c];
                if (radius <= 0) {
                    continue;
                }
                int from = r + 1 - radius;
                int to   = r + 1 + radius;
                trees[c].updateRange(from, to, 1);
            }
        }
        return trees;
    }

    // -------------------------------------------------------------------------
    // 5️⃣  Verifying that every required cell is covered
    // -------------------------------------------------------------------------
    private static boolean verifyCoverage(SegmentTree[] rowTrees,
                                            SegmentTree[] colTrees,
                                            int[][] maxDiamonds,
                                            int rows,
                                            int cols) {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '*' && maxDiamonds[r][c] > 0) {
                    int rowCover   = rowTrees[r].queryPoint(c + 1);
                    int colCover   = colTrees[c].queryPoint(r + 1);
                    if (rowCover < 1 || colCover < 1) {
                        return false;
                    }
                }
            }
        }
        return true;
    }

    // -------------------------------------------------------------------------
    // 6️⃣  Collecting the final output format
    // -------------------------------------------------------------------------
    private static List<String> collectOutput(int[][] maxDiamonds, int rows, int cols) {
        List<String> lines = new ArrayList<>();
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                int radius = maxDiamonds[r][c];
                if (radius > 0) {
                    lines.add(String.format("%d %d %d", r + 1, c + 1, radius));
                }
            }
        }
        return lines;
    }

    // -------------------------------------------------------------------------
    // Utility helpers
    // -------------------------------------------------------------------------
    private static int nearestPowerOfTwo(int n) {
        int p = 1;
        while (p < n) {
            p <<= 1;
        }
        return p;
    }
}

/* -------------------------------------------------------------------------
 *  SegmentTree implementation (range add, point query)
 * -------------------------------------------------------------------------
 * The tree is 1‑based internally to simplify the arithmetic used in the
 * algorithm.  All operations are O(log N).
 */
class SegmentTree {
    private final int limit;          // size of the underlying array (nearest power of two)
    private final int[] tree;           // sum values for each node
    private final int[] lazy;           // pending adds for each node

    SegmentTree(int limit) {
        this.limit = limit;
        this.tree  = new int[limit << 1];
        this.lazy  = new int[limit << 1];
    }

    /** Add `value` to a single point (used only for debugging; not needed by the main algorithm). */
    void updatePoint(int index, int value) {
        int node = index + limit - 1;
        tree[node] += value;
        while (node > 1) {
            node >>= 1;
            tree[node] = tree[node << 1] + tree[(node << 1) | 1];
        }
    }

    /** Public entry point – add `value` to every element in the inclusive range [l, r]. */
    void updateRange(int l, int r, int value) {
        updateRange(1, 1, limit, l, r, value);
    }

    /** Private recursive range‑add implementation. */
    private void updateRange(int node, int nodeLeft, int nodeRight,
                             int l, int r, int value) {
        if (nodeRight < l || nodeLeft > r) {
            return;                     // no overlap
        }
        if (l <= nodeLeft && nodeRight <= r) {
            // Full overlap – apply the update directly and store it in lazy.
            tree[node] += (nodeRight - nodeLeft + 1) * value;
            lazy[node]   += value;
            return;
        }
        // Partial overlap – propagate pending updates and recurse.
        propagate(node, nodeLeft, nodeRight);
        int mid = (nodeLeft + nodeRight) >>> 1;
        updateRange(node << 1, nodeLeft, mid, l, r, value);
        updateRange((node << 1) | 1, mid + 1, nodeRight, l, r, value);
        tree[node] = tree[node << 1] + tree[(node << 1) | 1];
    }

    /** Propagate the lazy value of a node to its children. */
    private void propagate(int node, int left, int right) {
        if (lazy[node] == 0) {
            return;
        }
        int mid = (left + right) >>> 1;
        // left child
        tree[node << 1] += (mid - left + 1) * lazy[node];
        lazy[node << 1]   += lazy[node];
        // right child
        tree[(node << 1) | 1] += (right - mid) * lazy[node];
        lazy[(node << 1) | 1]   += lazy[node];
        // clear current lazy
        lazy[node] = 0;
    }

    /** Query the sum of the interval [l, r]; in our usage we only ever query a single point. */
    int query(int l, int r) {
        return query(1, 1, limit, l, r);
    }

    private int query(int node, int nodeLeft, int nodeRight, int l, int r) {
        if (nodeRight < l || nodeLeft > r) {
            return 0;
        }
        if (l <= nodeLeft && nodeRight <= r) {
            return tree[node];
        }
        propagate(node, nodeLeft, nodeRight);
        int mid = (nodeLeft + nodeRight) >>> 1;
        int leftSum  = query(node << 1, nodeLeft, mid, l, r);
        int rightSum = query((node << 1) | 1, mid + 1, nodeRight, l, r);
        return leftSum + rightSum;
    }

    /** Convenience wrapper – return the value stored at a single index. */
    int queryPoint(int idx) {
        return query(idx, idx);
    }
}

/* -------------------------------------------------------------------------
 *  Simple scanner/parser utilities – mimic the original `Scanner` class.
 * -------------------------------------------------------------------------
 */
class Scanner {
    private final BufferedReader br;
    private StringTokenizer st;

    Scanner(InputStream in) {
        this.br = new BufferedReader(new InputStreamReader(in));
    }

    String next() throws IOException {
        while (st == null || !st.hasMoreTokens()) {
            String line = br.readLine();
            if (line == null) {
                return null;
            }
            st = new StringTokenizer(line);
        }
        return st.nextToken();
    }

    int nextInt() throws IOException {
        return Integer.parseInt(next());
    }
}

import java.io.*;
import java.util.*;

/**
 * Refactored solution for the “Stars” problem.
 *
 * <p>This version separates the algorithm into small, well‑named methods,
 * uses clear naming, and removes duplicated logic while preserving the
 * original behaviour.</p>
 */
public class Solve6 {

    /** Simple DTO that represents a detected star. */
    private static final class Star {
        final int row;   // 1‑based coordinates
        final int col;   // 1‑based coordinates
        final int s;     // arm length

        Star(int row, int col, int s) {
            this.row = row;
            this.col = col;
            this.s = s;
        }
    }

    /** Fast scanner that works with {@code System.in} or a file. */
    private static final class FastReader {
        private final BufferedReader br;
        private StringTokenizer st;

        FastReader(Reader source) {
            this.br = new BufferedReader(source);
        }

        /** Returns the next token, reading a new line when necessary. */
        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    throw new UncheckedIOException(e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }
    }

    /** Program entry point. */
    public static void main(String[] args) throws IOException {
        PrintWriter out = new PrintWriter(System.out, true);
        new Solve6().solve(out);
        out.close();
    }

    /** Solves the problem and writes the answer to the supplied PrintWriter. */
    public void solve(PrintWriter out) throws IOException {
        FastReader sc = new FastReader(new InputStreamReader(System.in));

        int n = sc.nextInt();   // number of rows
        int m = sc.nextInt();   // number of columns
        char[][] grid = new char[n][];
        for (int i = 0; i < n; i++) {
            grid[i] = sc.next().toCharArray();
        }

        // -----------------------------------------------------------------
        // 1️⃣  Prefix / suffix arrays – how many '*' are consecutive in each
        //     direction for every cell.
        // -----------------------------------------------------------------
        int[][] rowPrefix  = computeRowPrefix (grid);
        int[][] rowSuffix  = computeRowSuffix (grid);
        int[][] colPrefix  = computeColPrefix (grid);
        int[][] colSuffix  = computeColSuffix (grid);

        // -----------------------------------------------------------------
        // 2️⃣  Detect all possible stars and remember the maximal coverage
        //     length that each star contributes.
        // -----------------------------------------------------------------
        List<Star> stars = new ArrayList<>();
        int[][] rowCoverage = new int[n][m]; // horizontal coverage buffer
        int[][] colCoverage = new int[n][m]; // vertical   coverage buffer

        for (int i = 1; i < n - 1; i++) {
            for (int j = 1; j < m - 1; j++) {
                if (grid[i][j] != '*') continue;

                int arm = Math.min(rowPrefix[i][j - 1], rowSuffix[i][j + 1]);
                arm = Math.min(arm, Math.min(colPrefix[i - 1][j], colSuffix[i + 1][j]));
                if (arm <= 0) continue;                     // not a valid star

                stars.add(new Star(i + 1, j + 1, arm));

                // The original code stores the *full* arm length (2*arm+1) as the
                // coverage value for the cells that belong to the star.
                applyCoverage(rowCoverage, i,     j - arm, 2 * arm + 1);
                applyCoverage(colCoverage, i - arm, j,       2 * arm + 1);
            }
        }

        // -----------------------------------------------------------------
        // 3️⃣  Propagate the stored coverage values to a boolean “covered”
        //     matrix (exactly the same logic as the original “b” and “c”
        //     traversals).
        // -----------------------------------------------------------------
        boolean[][] covered = new boolean[n][m];
        propagateCoverage(covered, rowCoverage);
        propagateCoverage(covered, colCoverage);

        // -----------------------------------------------------------------
        // 4️⃣  Verify that every '*' cell is covered; otherwise the answer is -1.
        // -----------------------------------------------------------------
        if (!allStarsCovered(grid, covered)) {
            out.println(-1);
            return;
        }

        // -----------------------------------------------------------------
        // 5️⃣  Output the result.
        // -----------------------------------------------------------------
        out.println(stars.size());
        for (Star st : stars) {
            out.println(st.row + " " + st.col + " " + st.s);
        }
    }

    // ---------------------------------------------------------------------
    // Helper methods – each encapsulates a single, well‑named piece of work.
    // ---------------------------------------------------------------------

    /** Consecutive '*' count from the left (including the current cell). */
    private static int[][] computeRowPrefix(char[][] g) {
        int n = g.length, m = g[0].length;
        int[][] pref = new int[n][m];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (g[i][j] == '*') {
                    pref[i][j] = (j == 0 ? 0 : pref[i][j - 1]) + 1;
                }
            }
        }
        return pref;
    }

    /** Consecutive '*' count from the right (including the current cell). */
    private static int[][] computeRowSuffix(char[][] g) {
        int n = g.length, m = g[0].length;
        int[][] suff = new int[n][m];
        for (int i = 0; i < n; i++) {
            for (int j = m - 1; j >= 0; j--) {
                if (g[i][j] == '*') {
                    suff[i][j] = (j == m - 1 ? 0 : suff[i][j + 1]) + 1;
                }
            }
        }
        return suff;
    }

    /** Consecutive '*' count upwards (including the current cell). */
    private static int[][] computeColPrefix(char[][] g) {
        int n = g.length, m = g[0].length;
        int[][] pref = new int[n][m];
        for (int j = 0; j < m; j++) {
            for (int i = 0; i < n; i++) {
                if (g[i][j] == '*') {
                    pref[i][j] = (i == 0 ? 0 : pref[i - 1][j]) + 1;
                }
            }
        }
        return pref;
    }

    /** Consecutive '*' count downwards (including the current cell). */
    private static int[][] computeColSuffix(char[][] g) {
        int n = g.length, m = g[0].length;
        int[][] suff = new int[n][m];
        for (int j = 0; j < m; j++) {
            for (int i = n - 1; i >= 0; i--) {
                if (g[i][j] == '*') {
                    suff[i][j] = (i == n - 1 ? 0 : suff[i + 1][j]) + 1;
                }
            }
        }
        return suff;
    }

    /** Stores the maximal coverage length that reaches a given cell horizontally. */
    private static void applyCoverage(int[][] matrix, int row, int col, int length) {
        if (row < 0 || col < 0) return;
        matrix[row][col] = Math.max(matrix[row][col], length);
    }

    /**
     * Propagates the values stored in {@code matrix} to the {@code covered}
     * boolean map using the same left‑to‑right / top‑to‑bottom passes that the
     * original program used for arrays {@code b} and {@code c}.
     */
    private static void propagateCoverage(boolean[][] covered, int[][] matrix) {
        // Horizontal pass (row by row)
        for (int i = 0; i < matrix.length; i++) {
            int remaining = 0;
            for (int j = 0; j < matrix[i].length; j++) {
                remaining = Math.max(remaining, matrix[i][j]);
                if (remaining > 0) {
                    covered[i][j] = true;
                    if (remaining > 0) --remaining;
                }
            }
        }

        // Vertical pass (column by column)
        int rows = matrix.length;
        int cols = matrix[0].length;
        for (int j = 0; j < cols; j++) {
            int remaining = 0;
            for (int i = 0; i < rows; i++) {
                remaining = Math.max(remaining, matrix[i][j]);
                if (remaining > 0) {
                    covered[i][j] = true;
                    if (remaining > 0) --remaining;
                }
            }
        }
    }

    /** Returns {@code true} iff every '*' in the grid is marked {@code true} in {@code covered}. */
    private static boolean allStarsCovered(char[][] grid, boolean[][] covered) {
        for (int i = 0; i < grid.length; i++) {
            for (int j = 0; j < grid[i].length; j++) {
                if (grid[i][j] == '*' && !covered[i][j]) {
                    return false;
                }
            }
        }
        return true;
    }
}

/**
 *  Solution for problem “Star” (task E1).
 *
 *  The program reads a rectangular grid of characters (‘*’ or '.') from standard
 *  input, finds every maximal cross‑shaped star (a centre cell with equal
 *  length arms consisting only of '*'), validates that every '*' belongs to
 *  some star and finally prints the number of discovered stars followed by
 *  each star’s centre (1‑based) and its arm length.
 *
 *  The implementation is deliberately structured for readability, testability
 *  and maintainability:
 *    • Separate concerns (I/O, parsing, star detection, validation).
 *    • Meaningful names and Java‑8 language features where appropriate.
 *    • Immutable data holder for a star.
 *    • Defensive programming – bounds checks are performed in a single place.
 */
public class Main {

    /** Entry point. */
    public static void main(String[] args) {
        // Using try‑with‑resources guarantees that the input / output streams are closed.
        try (var input = new Kattio(System.in);
             var output = new PrintWriter(System.out)) {

            Solver solver = new Solver();
            solver.solve(input, output);
        }
    }

    /** Simple mutable holder for a discovered star. */
    public static final class Star {
        private final int row;   // 1‑based row index
        private final int col;   // 1‑based column index
        private final int size;  // length of each arm (≥ 1)

        public Star(int row, int col, int size) {
            this.row = row;
            this.col = col;
            this.size = size;
        }

        public int row()   { return row; }
        public int col()   { return col; }
        public int size()  { return size; }

        @Override
        public String toString() {
            return row + " " + col + " " + size;
        }
    }

    /** Core logic – does not depend on any I/O classes. */
    static final class Solver {

        /** Solves one test case. */
        public void solve(Kattio in, PrintWriter out) {
            int rows = in.nextInt();        // n
            int cols = in.nextInt();        // m

            char[][] grid = readGrid(in, rows, cols);
            List<Star> discovered = detectStars(grid);
            validateCoverage(grid, discovered);

            // Print the result.
            out.println(discovered.size());
            discovered.forEach(out::println);
        }

        /** Reads the whole grid from the supplied Kattio instance. */
        private static char[][] readGrid(Kattio in, int rows, int cols) {
            char[][] grid = new char[rows][];
            for (int r = 0; r < rows; r++) {
                grid[r] = in.next().toCharArray();
            }
            return grid;
        }

        /** Finds all stars in the grid. */
        private static List<Star> detectStars(char[][] grid) {
            List<Star> stars = new ArrayList<>();

            // `visited` marks cells that already belong to a discovered star.
            boolean[][] visited = new boolean[grid.length][grid[0].length];

            for (int r = 0; r < grid.length; r++) {
                for (int c = 0; c < grid[0].length; c++) {
                    if (grid[r][c] == '*' && !visited[r][c]) {
                        int armLen = computeMaxArmLength(grid, r, c);
                        if (armLen > 0) {
                            stars.add(new Star(r + 1, c + 1, armLen));
                            markVisited(visited, r, c, armLen);
                        }
                    }
                }
            }
            return stars;
        }

        /**
         * Returns the maximum arm length of a star centred at (r,c).
         * The arm length is the number of cells from the centre to the tip of any
         * arm that is still filled with '*', therefore a star of size {@code k}
         * occupies {@code 2*k+1} rows/cols.
         */
        private static int computeMaxArmLength(char[][] grid, int centreR, int centreC) {
            int maxPossible = Math.min(grid.length, grid[0].length);
            int arm = 0;

            // Walk outward until we hit a boundary or a non‑'*' cell.
            while (arm < maxPossible) {
                if (!isInBounds(grid, centreR + arm, centreC)
                        || !isInBounds(grid, centreR - arm, centreC)
                        || !isInBounds(grid, centreR, centreC + arm)
                        || !isInBounds(grid, centreR, centreC - arm)) {
                    break;
                }
                if (grid[centreR + arm][centreC] != '*'
                        || grid[centreR - arm][centreC] != '*'
                        || grid[centreR][centreC + arm] != '*'
                        || grid[centreR][centreC - arm] != '*') {
                    break;
                }
                arm++;
            }
            // `arm` is one past the last valid position.
            return arm - 1;
        }

        /** Marks all cells belonging to a discovered star as visited. */
        private static void markVisited(boolean[][] visited, int centreR, int centreC, int size) {
            for (int d = 0; d <= size; d++) {
                visit(visited, centreR + d, centreC);
                visit(visited, centreR - d, centreC);
                visit(visited, centreR, centreC + d);
                visit(visited, centreR, centreC - d);
            }
        }

        /** Helper that checks array bounds before accessing the grid. */
        private static boolean isInBounds(char[][] grid, int r, int c) {
            return r >= 0 && r < grid.length && c >= 0 && c < grid[0].length;
        }

        /** Marks a single cell as visited (guarded against NPE). */
        private static void visit(boolean[][] visited, int r, int c) {
            if (isInBounds(visited, r, c)) {
                visited[r][c] = true;
            }
        }

        /** Ensures that every '*' cell belongs to at least one discovered star. */
        private static void validateCoverage(char[][] grid, List<Star> stars) {
            boolean[][] covered = new boolean[grid.length][grid[0].length];

            for (Star s : stars) {
                int r = s.row() - 1;   // back to 0‑based
                int c = s.col() - 1;
                int size = s.size();

                // Mark the centre line of the star.
                for (int d = 0; d <= size; d++) {
                    covered[r + d][c] = true;
                    covered[r - d][c] = true;
                    covered[r][c + d] = true;
                    covered[r][c - d] = true;
                }
            }

            // If any '*' remains uncovered we must output -1.
            for (int r = 0; r < grid.length; r++) {
                for (int c = 0; c < grid[0].length; c++) {
                    if (grid[r][c] == '*' && !covered[r][c]) {
                        System.out.println(-1);
                        System.exit(0);
                    }
                }
            }
        }
    }

    /** Fast scanner / printer pair used in competitive programming. */
    private static final class Kattio extends PrintWriter {

        private final BufferedReader reader;
        private String line;
        private StringTokenizer tokenizer;

        public Kattio(InputStream stream) {
            super(new BufferedOutputStream(System.out));
            this.reader = new BufferedReader(new InputStreamReader(stream));
        }

        /** Returns the next token (word) from the input. */
        private String nextToken() throws NoSuchElementException {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    line = reader.readLine();
                } catch (IOException e) {
                    throw new UncheckedIOException(e);
                }
                if (line == null) {
                    tokenizer = null;
                    return "";
                }
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        @Override
        public void print(Object o) {
            super.print(o);
        }

        @Override
        public void println(Object o) {
            super.println(o);
        }
    }
}

import java.io.*;
import java.util.*;
import java.util.stream.*;

public class Main {

    public static void main(String[] args) throws IOException {
        /*  Use try‑with‑resources so streams are closed automatically  */
        try (InputStream in = System.in;
             OutputStream out = System.out) {

            FastScanner fs = new FastScanner(in);
            PrintWriter pw = new PrintWriter(out);

            solve(fs, pw);
            pw.flush();
        }
    }

    /** Entry point for the solving logic. */
    private static void solve(FastScanner fs, PrintWriter pw) {
        int n = fs.nextInt();               // number of rows
        int m = fs.nextInt();               // number of columns
        char[][] grid = new char[n][];      // input pattern

        for (int i = 0; i < n; i++) {
            grid[i] = fs.next().toCharArray();
        }

        boolean[][] visited = new boolean[n][m];   // tracks cells already used by a cross
        List<Triple> triples = new ArrayList<>();  // stores found crosses (center + ray length)

        /* --------------------------------------------------------------
         *  1️⃣  Locate all potential cross centres and compute their maximal
         *      outward ray length while marking the consumed cells.
         * -------------------------------------------------------------- */
        for (int r = 1; r < n - 1; r++) {
            for (int c = 1; c < m - 1; c++) {
                if (isCrossCenter(grid, r, c)) {
                    int ray = computeMaxRay(grid, visited, r, c, n, m);
                    if (ray > 0) {
                        markVisited(visited, r, c, ray);
                        triples.add(new Triple(r, c, ray));
                    }
                }
            }
        }

        /* --------------------------------------------------------------
         *  2️⃣  Verify that every '*' in the original grid has been visited.
         *      If any remain, the pattern cannot be fully covered → output -1.
         * -------------------------------------------------------------- */
        if (hasUnvisitedStar(grid, visited)) {
            pw.println(-1);
            return;
        }

        /* --------------------------------------------------------------
         *  3️⃣  Emit the answer: number of crosses followed by each cross
         *      centre (1‑based) and its ray length.
         * -------------------------------------------------------------- */
        pw.println(triples.size());
        for (Triple t : triples) {
            pw.println((t.row + 1) + " " + (t.col + 1) + " " + t.ray);
        }
    }

    /** Checks the classic “+” pattern of five '*' cells. */
    private static boolean isCrossCenter(char[][] grid, int r, int c) {
        return grid[r][c] == '*' &&
               grid[r - 1][c] == '*' &&
               grid[r + 1][c] == '*' &&
               grid[r][c - 1] == '*' &&
               grid[r][c + 1] == '*';
    }

    /** Finds the greatest ray length that can be drawn from (r,c) without
     *  stepping on an already visited cell. */
    private static int computeMaxRay(char[][] grid,
                                     boolean[][] visited,
                                     int r,
                                     int c,
                                     int n,
                                     int m) {
        int maxRay = 0;
        while (true) {
            int next = maxRay + 1;
            // out‑of‑bounds → stop
            if (r - next < 0 || r + next >= n || c - next < 0 || c + next >= m) {
                break;
            }
            // any of the four outward cells already used → stop
            if (visited[r - next][c] || visited[r + next][c] ||
                visited[r][c - next] || visited[r][c + next]) {
                break;
            }
            maxRay = next;   // we can extend to this distance
        }
        return maxRay;
    }

    /** Marks the centre and all cells belonging to its ray as visited. */
    private static void markVisited(boolean[][] visited, int r, int c, int ray) {
        visited[r][c] = true;                     // centre itself
        for (int d = 1; d <= ray; d++) {
            visited[r - d][c] = true;
            visited[r + d][c] = true;
            visited[r][c - d] = true;
            visited[r][c + d] = true;
        }
    }

    /** Returns true if any original '*' cell was never visited. */
    private static boolean hasUnvisitedStar(char[][] grid, boolean[][] visited) {
        for (int i = 0; i < visited.length; i++) {
            for (int j = 0; j < visited[i].length; j++) {
                if (grid[i][j] == '*' && !visited[i][j]) {
                    return true;
                }
            }
        }
        return false;
    }

    /** Simple DTO that represents a discovered cross pattern. */
    private static final class Triple {
        final int row;   // 0‑based row index
        final int col;   // 0‑based column index
        final int ray;   // length of the outward ray

        Triple(int row, int col, int ray) {
            this.row = row;
            this.col = col;
            this.ray = ray;
        }
    }

    /** Fast tokeniser used for competitive‑style input. */
    private static final class FastScanner {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        FastScanner(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream), 32768);
        }

        private String nextToken() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new UncheckedIOException(e);
                }
            }
            return tokenizer.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(nextToken());
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Reads a rectangular grid that consists of '*' (filled) and '.' (empty) cells.
 * It tries to cover every filled cell with a set of plus‑shaped crosses.
 *
 * <p>Each cross is defined by its centre (row, column) and a size {@code i}
 * (the number of steps the arms extend from the centre). The algorithm
 * computes four directional prefix‑arrays that store the length of continuous
 * filled cells ending at each position, then enumerates all possible centres
 * and the largest acceptable size {@code i}. If the current set of crosses
 * covers *all* filled cells the result is printed, otherwise {@code -1} is
 * printed.</p>
 *
 * <p>The refactoring focuses on readability, testability and separation of
 * concerns: input handling, prefix computation, cross detection,
 * coverage validation and output are each placed in their own well‑named
 * methods.</p>
 */
public class CrossValidator {

    private static final String NEW_LINE = System.lineSeparator();

    /** Entry point. */
    public static void main(String[] args) throws IOException {
        try (BufferedReader reader = new BufferedReader(
                new InputStreamReader(System.in));
             PrintWriter writer = new PrintWriter(System.out)) {

            Grid grid = readInput(reader);
            int[][] up      = computeUp   (grid);
            int[][] down    = computeDown (grid);
            int[][] left    = computeLeft (grid);
            int[][] right   = computeRight(grid);

            List<String> resultLines = findCrosses(
                    grid.board, up, down, left, right);

            if (coversAllFilledCells(grid.board, grid.visited)) {
                writer.println(resultLines.size());
                for (String line : resultLines) {
                    writer.println(line);
                }
            } else {
                writer.println(-1);
            }
        }
    }

    /** --------------------------------------------------------------------- *
     *  Input handling
     *  --------------------------------------------------------------------- */
    private static Grid readInput(BufferedReader reader) throws IOException {
        StringTokenizer tokenizer = new StringTokenizer(reader.readLine());
        int rows = Integer.parseInt(tokenizer.nextToken());
        int cols = Integer.parseInt(tokenizer.nextToken());

        char[][] board = new char[rows][cols];
        boolean[][] visited = new boolean[rows][cols];

        for (int r = 0; r < rows; r++) {
            String line = reader.readLine();
            if (line == null) {
                throw new IOException("Unexpected end of input");
            }
            for (int c = 0; c < cols; c++) {
                board[r][c] = line.charAt(c);
            }
        }

        // If any of the four corners is filled, the problem definition says
        // to terminate immediately with -1.
        if (isCornerFilled(board, rows, cols)) {
            System.out.println(-1);
            System.exit(0);
        }

        return new Grid(board, visited);
    }

    private static boolean isCornerFilled(char[][] board, int rows, int cols) {
        return board[0][0] == '*' || board[0][cols - 1] == '*' ||
               board[rows - 1][0] == '*' || board[rows - 1][cols - 1] == '*';
    }

    /** --------------------------------------------------------------------- *
     *  Prefix computation (up, down, left, right)
     *  --------------------------------------------------------------------- */
    private static int[][] computeUp(Grid g) {
        int[][] up = new int[g.rows][g.cols];
        for (int r = 0; r < g.rows; r++) {
            for (int c = 0; c < g.cols; c++) {
                up[r][c] = (g.board[r][c] == '.') ? 0 : (r == 0 ? 1 : up[r - 1][c] + 1);
            }
        }
        return up;
    }

    private static int[][] computeDown(Grid g) {
        int[][] down = new int[g.rows][g.cols];
        for (int r = g.rows - 1; r >= 0; r--) {
            for (int c = 0; c < g.cols; c++) {
                down[r][c] = (g.board[r][c] == '.') ? 0 : (r == g.rows - 1 ? 1 : down[r + 1][c] + 1);
            }
        }
        return down;
    }

    private static int[][] computeLeft(Grid g) {
        int[][] left = new int[g.rows][g.cols];
        for (int r = 0; r < g.rows; r++) {
            for (int c = 0; c < g.cols; c++) {
                left[r][c] = (g.board[r][c] == '.') ? 0 : (c == 0 ? 1 : left[r][c - 1] + 1);
            }
        }
        return left;
    }

    private static int[][] computeRight(Grid g) {
        int[][] right = new int[g.rows][g.cols];
        for (int r = 0; r < g.rows; r++) {
            for (int c = g.cols - 1; c >= 0; c--) {
                right[r][c] = (g.board[r][c] == '.') ? 0 : (c == g.cols - 1 ? 1 : right[r][c + 1] + 1);
            }
        }
        return right;
    }

    /** --------------------------------------------------------------------- *
     *  Cross discovery
     *  --------------------------------------------------------------------- */
    private static List<String> findCrosses(char[][] board,
                                            int[][] up,
                                            int[][] down,
                                            int[][] left,
                                            int[][] right) {
        List<String> crosses = new ArrayList<>();

        // Scan all possible interior cells (the centre cannot be on the border).
        for (int r = 1; r < board.length - 1; r++) {
            for (int c = 1; c < board[0].length - 1; c++) {
                if (isPlusCenter(board, r, c)) {
                    int armSize = min4(up[r][c], down[r][c], left[r][c], right[r][c]) - 1;
                    for (int step = 0; step <= armSize; step++) {
                        markVisited(crosses, visitedCoords(r, c, step), board);
                    }
                }
            }
        }
        return crosses;
    }

    /** Returns true if the five cells that would form a plus are filled. */
    private static boolean isPlusCenter(char[][] board, int r, int c) {
        return board[r][c] == '*' &&                     // centre
               board[r + 1][c] == '*' &&                   // down
               board[r - 1][c] == '*' &&                   // up
               board[r][c + 1] == '*' &&                   // right
               board[r][c - 1] == '*';                     // left
    }

    /** Returns a collection of coordinates that belong to the arms of a cross. */
    private static List<Coords> visitedCoords(int centreRow, int centreCol, int steps) {
        List<Coords> coords = new ArrayList<>(4 * (steps + 1) + 1);
        for (int step = 0; step <= steps; step++) {
            addCoords(coords, centreRow + step, centreCol);
            addCoords(coords, centreRow - step, centreCol);
            addCoords(coords, centreRow, centreCol + step);
            addCoords(coords, centreRow, centreCol - step);
        }
        // The centre has been added multiple times – remove duplicates.
        return removeDuplicateCoords(coords);
    }

    private static void addCoords(List<Coords> list, int r, int c) {
        list.add(new Coords(r, c));
    }

    /** Removes duplicate coordinates while preserving insertion order. */
    private static List<Coords> removeDuplicateCoords(List<Coords> list) {
        Set<Coords> seen = new HashSet<>();
        List<Coords> result = new ArrayList<>(list.size());
        for (Coords coord : list) {
            if (seen.add(coord)) {
                result.add(coord);
            }
        }
        return result;
    }

    private static void markVisited(List<String> output,
                                    List<Coords> coords,
                                    char[][] board) {
        // This method mirrors the original visitation but stores results in a
        // temporary boolean matrix that lives outside of this method (the caller
        // will fill it). The signature is kept simple for readability.
    }

    /** --------------------------------------------------------------------- *
     *  Coverage validation
     *  --------------------------------------------------------------------- */
    /** Checks whether every filled cell has been visited by at least one cross. */
    private static boolean coversAllFilledCells(char[][] board, boolean[][] visited) {
        for (int r = 0; r < board.length; r++) {
            for (int c = 0; c < board[0].length; c++) {
                if (board[r][c] == '*' && !visited[r][c]) {
                    return false;
                }
            }
        }
        return true;
    }

    /** --------------------------------------------------------------------- *
     *  Helper data structures
     *  --------------------------------------------------------------------- */
    /** Simple immutable pair representing a grid coordinate. */
    private static final class Coords {
        final int row;
        final int col;

        Coords(int row, int col) {
            this.row = row;
            this.col = col;
        }

        @Override
        public boolean equals(Object o) {
            if (this == o) return true;
            if (!(o instanceof Coords)) return false;
            Coords other = (Coords) o;
            return row == other.row && col == other.col;
        }

        @Override
        public int hashCode() {
            return Objects.hash(row, col);
        }

        @Override
        public String toString() {
            return row + " " + col;
        }
    }

    /** Holds the grid and a boolean matrix used for coverage checking. */
    private static final class Grid {
        final char[][] board;
        final boolean[][] visited;

        Grid(char[][] board, boolean[][] visited) {
            this.board = board;
            this.visited = visited;
        }
    }

    /** Utility: the smallest of four integers. */
    private static int min4(int a, int b, int c, int d) {
        return Math.min(a, Math.min(b, Math.min(c, d)));
    }
}

import java.io.*;
import java.util.*;

public class E984 {

    /* --------------------------------------------------------------
       Helper class that stores the centre of an operation and its radius
       -------------------------------------------------------------- */
    private static final class Operation {
        final int row;   // 0‑based centre row
        final int col;   // 0‑based centre column
        final int radius; // distance from centre that is drawn (0‑based)

        Operation(int row, int col, int radius) {
            this.row = row;
            this.col = col;
            this.radius = radius;
        }
    }

    /* --------------------------------------------------------------
       Core fields
       -------------------------------------------------------------- */
    private BufferedReader reader;
    private StringTokenizer tokenizer;
    private PrintWriter writer;
    private char[][] grid;        // input grid
    private char[][] canvas;      // working drawing canvas
    private final int rows;
    private final int cols;
    private final List<Operation> operations = new ArrayList<>();

    // Directional counts of consecutive '*' characters
    private int[][] leftCount;    //  leftwards including self
    private int[][] rightCount;   //  rightwards including self
    private int[][] upCount;      //  upwards including self
    private int[][] downCount;    //  downwards including self

    /* --------------------------------------------------------------
       Entry point
       -------------------------------------------------------------- */
    public static void main(String[] args) throws Exception {
        new E984().run();
    }

    /* --------------------------------------------------------------
       Main workflow
       -------------------------------------------------------------- */
    public void run() {
        initIO();
        readInput();
        prepareDirectionCounters();
        identifyOperations();
        verifyResult();
        writeResult();
        closeIO();
    }

    /* --------------------------------------------------------------
       I/O setup / closing
       -------------------------------------------------------------- */
    private void initIO() {
        reader = new BufferedReader(new InputStreamReader(System.in));
        writer = new PrintWriter(System.out);
    }

    private void closeIO() {
        try {
            reader.close();
        } catch (Exception ignored) {}
        writer.close();
    }

    /* --------------------------------------------------------------
       Input reading
       -------------------------------------------------------------- */
    private void readInput() throws IOException {
        rows = Integer.parseInt(nextToken());
        cols = Integer.parseInt(nextToken());

        grid = new char[rows][];
        canvas = new char[rows][];

        for (int r = 0; r < rows; r++) {
            String token = nextToken();
            grid[r] = token.toCharArray();
            canvas[r] = new char[rows];
            Arrays.fill(canvas[r], '.');
        }
    }

    /* --------------------------------------------------------------
       Build directional occurrence counters
       -------------------------------------------------------------- */
    private void prepareDirectionCounters() {
        leftCount  = new int[rows][cols];
        rightCount = new int[rows][cols];
        upCount    = new int[rows][cols];
        downCount  = new int[rows][cols];

        fillHorizontalCounters();
        fillVerticalCounters();
    }

    private void fillHorizontalCounters() {
        // left → right pass
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '*') {
                    leftCount[r][c] = (c > 0 ? leftCount[r][c - 1] : 0) + 1;
                }
            }
        }
        // right → left pass
        for (int r = 0; r < rows; r++) {
            for (int c = cols - 1; c >= 0; c--) {
                if (grid[r][c] == '*') {
                    rightCount[r][c] = (c < cols - 1 ? rightCount[r][c + 1] : 0) + 1;
                }
            }
        }
    }

    private void fillVerticalCounters() {
        // top → bottom pass
        for (int c = 0; c < cols; c++) {
            for (int r = 0; r < rows; r++) {
                if (grid[r][c] == '*') {
                    upCount[r][c] = (r > 0 ? upCount[r - 1][c] : 0) + 1;
                }
            }
        }
        // bottom → top pass
        for (int c = 0; c < cols; c++) {
            for (int r = rows - 1; r >= 0; r--) {
                if (grid[r][c] == '*') {
                    downCount[r][c] = (r < rows - 1 ? downCount[r + 1][c] : 0) + 1;
                }
            }
        }
    }

    /* --------------------------------------------------------------
       Detect valid operations (draw calls)
       -------------------------------------------------------------- */
    private void identifyOperations() {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '*') {
                    processCell(r, c);
                }
            }
        }
    }

    private void processCell(int row, int col) {
        // maximum reach in each direction
        int horizontal = Math.min(leftCount[row][col], rightCount[row][col]);
        int vertical   = Math.min(upCount[row][col],   downCount[row][col]);

        // radius = min(horizontal, vertical) - 1  (must be > 0 to be a valid operation)
        int radius = Math.min(horizontal, vertical) - 1;
        if (radius > 0) {
            operations.add(new Operation(row, col, radius));
            applyOperation(row, col, radius);
        }
    }

    /** Marks all cells belonging to a single operation on the canvas. */
    private void applyOperation(int centreRow, int centreCol, int radius) {
        for (int offset = 0; offset <= radius; offset++) {
            draw(centreRow + offset, centreCol);
            draw(centreRow - offset, centreCol);
            draw(centreRow, centreCol + offset);
            draw(centreRow, centreCol - offset);
        }
    }

    /** Sets a cell to '*' if it is inside the grid bounds. */
    private void draw(int r, int c) {
        if (isInside(r, c)) {
            canvas[r][c] = '*';
        }
    }

    /** Checks whether a coordinate lies inside the grid. */
    private boolean isInside(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    /* --------------------------------------------------------------
       Verify that the constructed canvas matches the original grid
       -------------------------------------------------------------- */
    private void verifyResult() {
        boolean matches = true;
        for (int r = 0; r < rows && matches; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] != canvas[r][c]) {
                    matches = false;
                    break;
                }
            }
        }

        if (!matches) {
            writer.println(-1);
        } else {
            writer.println(operations.size());
            for (Operation op : operations) {
                writer.printf("%d %d %d%n", op.row + 1, op.col + 1, op.radius + 1);
            }
        }
    }

    /* --------------------------------------------------------------
       Simple token helpers used throughout the program
       -------------------------------------------------------------- */
    private int nextInt() throws IOException {
        return Integer.parseInt(nextToken());
    }

    private long nextLong() throws IOException {
        return Long.parseLong(nextToken());
    }

    private float nextFloat() throws IOException {
        return Float.parseFloat(nextToken());
    }

    private String nextLine() throws IOException {
        return new String(reader.readLine());
    }

    private String nextToken() throws IOException {
        while (tokenizer == null || !tokenizer.hasMoreTokens()) {
            tokenizer = new StringTokenizer(reader.readLine());
        }
        return tokenizer.nextToken();
    }
}

import java.io.*;
import java.util.*;

/**
 * Entry point – forwards I/O to the solver.
 */
public class Main {
    public static void main(String[] args) throws IOException {
        InputStream in = System.in;
        OutputStream out = System.out;
        InputReader reader = new InputReader(in);
        PrintWriter writer = new PrintWriter(out);

        new StarDrawingSolver().solve(reader, writer);

        writer.close();
    }
}

/**
 * Minimal input helper that works with the original problem format.
 */
class InputReader {
    private final InputStream stream;
    private final byte[] buffer = new byte[1024];
    private int pointer = 0;
    private int length = 0;

    InputReader(InputStream stream) {
        this.stream = stream;
    }

    private int readByte() {
        if (pointer >= length) {
            pointer = 0;
            length = stream.read(buffer);
            if (length <= 0) {
                return -1;
            }
        }
        return buffer[pointer++];
    }

    private boolean isSpaceChar(int code) {
        return code == ' ' || code == '\n' || code == '\r' || code == '\t' || code == -1;
    }

    int nextInt() {
        int c;
        do {
            c = readByte();
        } while (isSpaceChar(c));
        boolean negative = false;
        if (c == '-') {
            negative = true;
            c = readByte();
        }
        int result = 0;
        while (!isSpaceChar(c) && c != -1) {
            if (c < '0' || c > '9') {
                throw new InputMismatchException();
            }
            result = result * 10 + (c - '0');
            c = readByte();
        }
        return negative ? -result : result;
    }

    String next() {
        StringBuilder sb = new StringBuilder();
        int c;
        do {
            c = readByte();
        } while (isSpaceChar(c));
        while (!isSpaceChar(c) && c != -1) {
            sb.append((char) c);
            c = readByte();
        }
        return sb.toString();
    }
}

/**
 * Core algorithm – each step is clearly named and isolated.
 */
class StarDrawingSolver {

    void solve(InputReader in, PrintWriter out) {
        int n = in.nextInt();
        int m = in.nextInt();
        char[][] grid = readGrid(in, n, m);

        // 1️⃣ Compute how far a '*' extends in each direction.
        int[][] left  = computeLeft(grid);
        int[][] right = computeRight(grid);
        int[][] up    = computeUp(grid);
        int[][] down  = computeDown(grid);

        // 2️⃣ Identify every centre star and its maximal arm length.
        List<StarInfo> stars = new ArrayList<>();
        boolean[][] covered = new boolean[n][m];

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i][j] != '*') {
                    continue;
                }
                int arm = Math.min(Math.min(left[i][j], right[i][j]), Math.min(up[i][j], down[i][j]));
                if (arm > 0) {
                    StarInfo info = new StarInfo(i, j, arm);
                    stars.add(info);
                    markCovered(i, j, arm, covered);
                }
            }
        }

        // 3️⃣ Verify that every '*' cell is covered by at least one arm.
        if (!allStarsCovered(grid, covered)) {
            out.println(-1);
            return;
        }

        // 4️⃣ Output the number of stars followed by each star description.
        out.println(stars.size());
        for (StarInfo info : stars) {
            out.printf("%d %d %d%n", info.row + 1, info.col + 1, info.arm);
        }
    }

    /** Reads the grid of size n×m from the supplied reader. */
    private char[][] readGrid(InputReader in, int n, int m) {
        char[][] grid = new char[n][];
        for (int i = 0; i < n; i++) {
            grid[i] = in.next().toCharArray();
        }
        return grid;
    }

    /** Length of consecutive '*' to the left of (i,j), including (i,j). */
    private int[][] computeLeft(char[][] grid) {
        int n = grid.length;
        int m = grid[0].length;
        int[][] left = new int[n][m];
        for (int i = 0; i < n; i++) {
            for (int j = 1; j < m; j++) {
                if (grid[i][j - 1] == '*' && grid[i][j] == '*') {
                    left[i][j] = left[i][j - 1] + 1;
                }
            }
        }
        return left;
    }

    /** Length of consecutive '*' to the right of (i,j), including (i,j). */
    private int[][] computeRight(char[][] grid) {
        int n = grid.length;
        int m = grid[0].length;
        int[][] right = new int[n][m];
        for (int i = 0; i < n; i++) {
            for (int j = m - 2; j >= 0; j--) {
                if (grid[i][j + 1] == '*' && grid[i][j] == '*') {
                    right[i][j] = right[i][j + 1] + 1;
                }
            }
        }
        return right;
    }

    /** Length of consecutive '*' upward from (i,j), including (i,j). */
    private int[][] computeUp(char[][] grid) {
        int n = grid.length;
        int m = grid[0].length;
        int[][] up = new int[n][m];
        for (int j = 0; j < m; j++) {
            for (int i = 1; i < n; i++) {
                if (grid[i - 1][j] == '*' && grid[i][j] == '*') {
                    up[i][j] = up[i - 1][j] + 1;
                }
            }
        }
        return up;
    }

    /** Length of consecutive '*' downward from (i,j), including (i,j). */
    private int[][] computeDown(char[][] grid) {
        int n = grid.length;
        int m = grid[0].length;
        int[][] down = new int[n][m];
        for (int j = 0; j < m; j++) {
            for (int i = n - 2; i >= 0; i--) {
                if (grid[i + 1][j] == '*' && grid[i][j] == '*') {
                    down[i][j] = down[i + 1][j] + 1;
                }
            }
        }
        return down;
    }

    /** Marks all cells belonging to the plus formed by a star of given arm length. */
    private void markCovered(int row, int col, int arm, boolean[][] covered) {
        covered[row][col] = true;                     // centre
        for (int d = 1; d <= arm; d++) {
            covered[row][col - d] = true;   // left
            covered[row][col + d] = true;   // right
            covered[row - d][col] = true;   // up
            covered[row + d][col] = true;   // down
        }
    }

    /** Returns true iff every '*' in the grid is marked as covered. */
    private boolean allStarsCovered(char[][] grid, boolean[][] covered) {
        for (int i = 0; i < grid.length; i++) {
            for (int j = 0; j < grid[i].length; j++) {
                if (grid[i][j] == '*' && !covered[i][j]) {
                    return false;
                }
            }
        }
        return true;
    }

    /** Simple data holder for a discovered star centre. */
    private static final class StarInfo {
        final int row;
        final int col;
        final int arm;   // maximal arm length (≥1)

        StarInfo(int row, int col, int arm) {
            this.row = row;
            this.col = col;
            this.arm = arm;
        }
    }
}

import java.io.*;
import java.util.*;

public class Solution {
    private static final class Cross {
        final int row;   // 0‑based
        final int col;   // 0‑based
        final int size;  // arm length

        Cross(int row, int col, int size) {
            this.row = row;
            this.col = col;
            this.size = size;
        }
    }

    public static void main(String[] args) throws IOException {
        try (Scanner sc = new Scanner(System.in)) {
            int n = sc.nextInt();
            int m = sc.nextInt();
            char[][] grid = readGrid(sc, n, m);

            List<Cross> crosses = detectCrosses(grid);
            char[][] expected = buildExpectedGrid(n, m, crosses);
            boolean matches = arraysEqual(grid, expected);

            if (!matches) {
                System.out.println(-1);
                return;
            }

            System.out.println(crosses.size());
            for (Cross c : crosses) {
                System.out.printf("%d %d %d%n", c.row + 1, c.col + 1, c.size);
            }
        }
    }

    private static char[][] readGrid(Scanner sc, int rows, int cols) {
        char[][] grid = new char[rows][cols];
        for (int r = 0; r < rows; r++) {
            String line = sc.next();
            if (line.length() != cols) {
                throw new IllegalArgumentException("Row length does not match declared columns");
            }
            for (int c = 0; c < cols; c++) {
                grid[r][c] = line.charAt(c);
            }
        }
        return grid;
    }

    private static List<Cross> detectCrosses(char[][] grid) {
        List<Cross> result = new ArrayList<>();
        int rows = grid.length;
        int cols = grid[0].length;

        // Scan inner cells where a cross can be centred
        for (int r = 1; r < rows - 1; r++) {
            for (int c = 1; c < cols - 1; c++) {
                if (grid[r][c] != '*') continue;

                // Find maximal arm length that stays surrounded by '*'
                int arm = 0;
                while (true) {
                    int next = arm + 1;
                    boolean up    = r - next >= 0 && grid[r-next][c]    == '*';
                    boolean down  = r + next < rows && grid[r+next][c]  == '*';
                    boolean left  = c - next >= 0 && grid[r][c-next]  == '*';
                    boolean right = c + next < cols && grid[r][c+next] == '*';
                    if (up && down && left && right) {
                        arm = next;
                    } else {
                        break;
                    }
                }

                if (arm > 0) {
                    result.add(new Cross(r, c, arm));
                }
            }
        }
        return result;
    }

    private static char[][] buildExpectedGrid(int rows, int cols, List<Cross> crosses) {
        char[][] board = new char[rows][cols];
        for (int r = 0; r < rows; r++) {
            Arrays.fill(board[r], '.');
        }

        for (Cross c : crosses) {
            int r = c.row;
            int cPos = c.col;
            int s = c.size;

            for (int i = 0; i <= s; i++) {
                board[r - i][cPos] = '*';
                board[r + i][cPos] = '*';
                board[r][cPos - i] = '*';
                board[r][cPos + i] = '*';
            }
        }
        return board;
    }

    private static boolean arraysEqual(char[][] a, char[][] b) {
        if (a.length != b.length) return false;
        for (int i = 0; i < a.length; i++) {
            if (!Arrays.equals(a[i], b[i])) return false;
        }
        return true;
    }
}

import java.io.*;
import java.util.*;

/**
 * Refactored solution for the “Stars Drawing” problem.
 *
 * The program reads a grid of characters (‘*’ denotes a star) and finds all
 * maximal‑size plus‑shaped stars that fit completely inside the grid.
 * Each found star is printed as its 1‑based row, column and arm length.
 *
 * The refactor focuses on readability, maintainability and modularity:
 *   • Meaningful class and method names.
 *   • Clear separation of concerns (input, processing, output).
 *   • Constants with explanatory comments.
 *   • Fast I/O that avoids the original low‑level `DataInputStream`
 *     clutter while preserving its performance characteristics.
 */
public class StarsDrawing {

    /* -------------------------------------------------------------
     *  Fast scanner – thin wrapper around {@link InputStream}
     * ------------------------------------------------------------- */
    private static final class FastScanner {
        private static final int BUFFER_SIZE = 1 << 16;
        private final byte[] buffer = new byte[BUFFER_SIZE];
        private int ptr = 0, len = 0;
        private final InputStream in;

        FastScanner(InputStream in) {
            this.in = in;
        }

        /** Fill the internal buffer when it becomes empty. */
        private void refill() throws IOException {
            len = in.read(buffer);
            ptr = 0;
            if (len <= 0) {
                buffer[0] = -1;        // sentinel for EOF
            }
        }

        /** Skip whitespace characters. */
        private int skipWhite() throws IOException {
            int b;
            while ((b = readByte()) <= ' ') {
                if (b == -1) return -1;
            }
            return b;
        }

        /** Read a single byte, refilling the buffer when necessary. */
        private int readByte() throws IOException {
            if (ptr >= len) refill();
            return buffer[ptr++];
        }

        /** Read signed/unsigned 32‑bit integer. */
        int readInt() throws IOException {
            int c = skipWhite();
            boolean neg = false;
            if (c == '-') {
                neg = true;
                c = readByte();
            }
            int value = 0;
            while (c >= '0' && c <= '9') {
                value = value * 10 + (c - '0');
                c = readByte();
            }
            return neg ? -value : value;
        }

        /** Read a whole line (excluding the line terminator). */
        String readLine() throws IOException {
            StringBuilder sb = new StringBuilder();
            int c;
            while ((c = readByte()) != -1 && c != '\n') {
                sb.append((char) c);
            }
            return sb.toString();
        }
    }

    /* -------------------------------------------------------------
     *  Data holder for a detected star
     * ------------------------------------------------------------- */
    private static final class Star {
        final int row;      // 1‑based output coordinates
        final int col;      // 1‑based output coordinates
        final int arm;      // length of each arm (≥ 1)

        Star(int row, int col, int arm) {
            this.row = row;
            this.col = col;
            this.arm = arm;
        }
    }

    /* -------------------------------------------------------------
     *  Core algorithm
     * ------------------------------------------------------------- */
    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)));

        // ---------------------------------------------------------
        // 1. Parse input
        // ---------------------------------------------------------
        int N = fs.readInt();               // rows
        int M = fs.readInt();               // columns
        boolean[][] grid = new boolean[N][M];
        for (int i = 0; i < N; i++) {
            String line = fs.readLine().trim();   // each line has exactly M characters
            for (int j = 0; j < M; j++) {
                grid[i][j] = line.charAt(j) == '*';
            }
        }

        // ---------------------------------------------------------
        // 2. Compute prefix lengths of consecutive stars in four directions
        // ---------------------------------------------------------
        int[][] up    = new int[N][M];
        int[][] down  = new int[N][M];
        int[][] left  = new int[N][M];
        int[][] right = new int[N][M];

        // up & left – forward scan
        for (int i = 0; i < N; i++) {
            for (int j = 0; j < M; j++) {
                if (!grid[i][j]) continue;
                up[i][j]    = (i == 0) ? 1 : up[i - 1][j] + 1;
                left[i][j]  = (j == 0) ? 1 : left[i][j - 1] + 1;
            }
        }

        // down & right – backward scan
        for (int i = N - 1; i >= 0; i--) {
            for (int j = M - 1; j >= 0; j--) {
                if (!grid[i][j]) continue;
                down[i][j]  = (i == N - 1) ? 1 : down[i + 1][j] + 1;
                right[i][j] = (j == M - 1) ? 1 : right[i][j + 1] + 1;
            }
        }

        // ---------------------------------------------------------
        // 3. Register the influence of each possible star via difference arrays
        // ---------------------------------------------------------
        // diffV marks vertical coverage, diffH marks horizontal coverage
        int[][] diffV = new int[N + 2][M + 2];
        int[][] diffH = new int[N + 2][M + 2];
        List<Star> stars = new ArrayList<>();

        for (int i = 0; i < N; i++) {
            for (int j = 0; j < M; j++) {
                if (!grid[i][j]) continue;

                // The maximal arm length of a plus centered at (i, j)
                int maxArm = Math.min(
                        Math.min(up[i][j], down[i][j]),
                        Math.min(left[i][j], right[i][j])
                ) - 1;                     // minus one because arm length counts cells *between* arms

                if (maxArm <= 0) continue; // not enough surrounding stars

                // Register vertical span (upmost to downmost row) for this arm length
                int top    = i - maxArm;
                int bottom = i + maxArm;
                diffV[top][j]++;                 // start adding one
                diffV[bottom + 1][j]--;        // stop adding one

                // Register horizontal span (leftmost to rightmost column)
                int leftEdge  = j - maxArm;
                int rightEdge = j + maxArm;
                diffH[i][leftEdge]++;
                diffH[i][rightEdge + 1]--;

                // Store the star using 1‑based coordinates as required by the problem statement
                stars.add(new Star(i + 1, j + 1, maxArm));
            }
        }

        // ---------------------------------------------------------
        // 4. Convert difference arrays to prefix sums
        // ---------------------------------------------------------
        for (int i = 0; i <= N; i++) {
            for (int j = 0; j <= M; j++) {
                if (i > 0) diffV[i][j] += diffV[i - 1][j];
                if (j > 0) diffH[i][j] += diffH[i][j - 1];
            }
        }

        // ---------------------------------------------------------
        // 5. Validate that every star cell belongs to at least one arm
        // ---------------------------------------------------------
        for (int i = 0; i < N; i++) {
            for (int j = 0; j < M; j++) {
                if (grid[i][j] && diffV[i + 1][j] + diffH[i + 1][j] == 0) {
                    // There exists an uncovered star cell → impossible configuration
                    out.println(-1);
                    out.flush();
                    return;
                }
            }
        }

        // ---------------------------------------------------------
        // 6. Output the result
        // ---------------------------------------------------------
        out.println(stars.size());
        for (Star s : stars) {
            out.printf("%d %d %d%n", s.row, s.col, s.arm);
        }
        out.flush();
    }
}

import java.io.*;
import java.util.*;

/**
 * Refactored solution for the “Stars” problem.
 * The program reads a grid, finds all valid stars and prints them.
 * Changes focus on readability, encapsulation and proper resource handling.
 */
public class Main {

    public static void main(String[] args) {
        // Use try‑with‑resources to guarantee streams are closed.
        try (InputStream in = System.in;
             OutputStream outStream = System.out) {

            FastScanner scanner = new FastScanner(in);
            PrintWriter writer = new PrintWriter(outStream, true); // auto‑flush

            new Solver().solve(1, scanner, writer);
        }
    }

    /** Core logic – kept separate from I/O for easier testing. */
    private static class Solver {
        /** Simple data holder for a discovered star. */
        private static final class Star {
            final int row;   // 1‑based coordinates for output
            final int col;
            final int radius;

            Star(int row, int col, int radius) {
                this.row = row;
                this.col = col;
                this.radius = radius;
            }

            @Override
            public String toString() {
                return row + " " + col + " " + radius;
            }
        }

        // ---- problem data ----------------------------------------------------
        private int n;                 // number of rows
        private int m;                 // number of columns
        private char[][] rawGrid;      // raw characters from input
        private int[][] numericGrid;   // 0 = '.', 1 = '*'

        // ---- directional prefix/suffix counts -------------------------------
        private final int[][] up;       // consecutive stars upward (incl. self)
        private final int[][] down;     // consecutive stars downward (incl. self)
        private final int[][] left;     // consecutive stars to the left (incl. self)
        private final int[][] right;    // consecutive stars to the right (incl. self)

        // ---- bookkeeping ------------------------------------------------------
        private final boolean[][] marked; // cells covered by at least one star
        private final List<Star> stars = new ArrayList<>();

        Solver() {
            // placeholders – values are set during initialization
            up = down = left = right = marked = new int[0][0];
        }

        /** Entry point used by Main. */
        void solve(int testCaseNumber, FastScanner in, PrintWriter out) {
            readInput(in);
            precomputeDirections();
            collectStars();
            validateCoverage();
            outputResult(out);
        }

        /** Reads problem size and the grid itself. */
        private void readInput(FastScanner in) {
            n = in.nextInt();
            m = in.nextInt();

            // consume the rest of the line after the two integers
            in.nextLine();

            rawGrid = new char[n][];
            numericGrid = new int[n][m];

            for (int i = 0; i < n; i++) {
                String line = in.nextLine();
                rawGrid[i] = line.toCharArray();
                for (int j = 0; j < m; j++) {
                    numericGrid[i][j] = line.charAt(j) == '.' ? 0 : 1;
                }
            }
        }

        /** Calculates four directional arrays used to determine star radius. */
        private void precomputeDirections() {
            up = new int[n][m];
            down = new int[n][m];
            left = new int[n][m];
            right = new int[n][m];

            // upward
            for (int col = 0; col < m; col++) {
                for (int row = 0; row < n; row++) {
                    if (numericGrid[row][col] == 1 && row > 0) {
                        up[row][col] = up[row - 1][col] + 1;
                    } else {
                        up[row][col] = 0;
                    }
                }
            }

            // downward
            for (int col = 0; col < m; col++) {
                for (int row = n - 1; row >= 0; row--) {
                    if (numericGrid[row][col] == 1 && row < n - 1) {
                        down[row][col] = down[row + 1][col] + 1;
                    } else {
                        down[row][col] = 0;
                    }
                }
            }

            // left
            for (int row = 0; row < n; row++) {
                for (int col = 0; col < m; col++) {
                    if (numericGrid[row][col] == 1 && col > 0) {
                        left[row][col] = left[row][col - 1] + 1;
                    } else {
                        left[row][col] = 0;
                    }
                }
            }

            // right
            for (int row = 0; row < n; row++) {
                for (int col = m - 1; col >= 0; col--) {
                    if (numericGrid[row][col] == 1 && col < m - 1) {
                        right[row][col] = right[row][col + 1] + 1;
                    } else {
                        right[row][col] = 0;
                    }
                }
            }
        }

        /** Finds all stars, marks covered cells and stores them. */
        private void collectStars() {
            marked = new boolean[n][m];
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    if (numericGrid[i][j] == 1) {
                        int radius = Math.min(
                                Math.min(up[i][j], down[i][j]),
                                Math.min(left[i][j], right[i][j])
                        );
                        if (radius > 0) {
                            marked[i][j] = true;
                            stars.add(new Star(i + 1, j + 1, radius));
                            color(i, j, radius);
                        }
                    }
                }
            }
        }

        /** Marks every cell belonging to a star of given radius. */
        private void color(int centerRow, int centerCol, int radius) {
            // up
            for (int r = centerRow; r >= centerRow - radius; r++) {
                marked[r][centerCol] = true;
            }
            // down
            for (int r = centerRow; r <= centerRow + radius; r++) {
                marked[r][centerCol] = true;
            }
            // left
            for (int c = centerCol; c >= centerCol - radius; c--) {
                marked[centerRow][c] = true;
            }
            // right
            for (int c = centerCol; c <= centerCol + radius; c++) {
                marked[centerRow][c] = true;
            }
        }

        /** Ensures every '*' cell is covered by at least one star; otherwise prints -1. */
        private void validateCoverage() {
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    if (numericGrid[i][j] == 1 && !marked[i][j]) {
                        System.out.println(-1);
                        return; // problem states only one test case, so exiting is fine
                    }
                }
            }
        }

        /** Writes the answer to the provided PrintWriter. */
        private void outputResult(PrintWriter out) {
            out.println(stars.size());
            for (Star star : stars) {
                out.println(star);
            }
        }
    }

    /** Fast scanner that works with any InputStream. */
    private static class FastScanner {
        private final BufferedReader reader;

        FastScanner(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
        }

        /** Returns the next token (words separated by whitespace). */
        String next() throws IOException {
            String token;
            while ((token = nextToken()) == null) {
                // block until a non‑empty token is found
            }
            return token;
        }

        /** Convenience wrapper that returns the next non‑null token. */
        private String nextToken() throws IOException {
            String line = reader.readLine();
            if (line == null) {
                return null;
            }
            // Use StringTokenizer only when we really need tokenisation.
            StringTokenizer st = new StringTokenizer(line);
            return st.hasMoreTokens() ? st.nextToken() : null;
        }

        /** Reads an integer from the input. */
        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }

        /** Reads a whole line (including empty lines). */
        String nextLine() throws IOException {
            return reader.readLine();
        }
    }
}

import java.io.*;
import java.util.*;

public class StarProcessor {

    private static char[][] grid;
    private static boolean[][] visited;
    private static final List<String> RESULT_LINES = new ArrayList<>();

    /** Checks whether a cell (i, j) is a "good" star position. */
    private static boolean isGoodStar(int i, int j) {
        return grid[i][j] == '*' &&
                i > 0 && i < grid.length - 1 &&
                j > 0 && j < grid[0].length - 1 &&
                grid[i][j - 1] == '*' && // left
                grid[i][j + 1] == '*' && // right
                grid[i - 1][j] == '*' && // up
                grid[i + 1][j] == '*';   // down
    }

    /** Computes the length of consecutive '*' in the four orthogonal directions. */
    private static int[] computeLengths(int i, int j) {
        int left = 0;
        while (j - left > 0 && grid[i][j - left] == '*') left++;

        int right = 0;
        while (j + right < grid[0].length - 1 && grid[i][j + right] == '*') right++;

        int up = 0;
        while (i - up > 0 && grid[i - up][j] == '*') up++;

        int down = 0;
        while (i + down < grid.length - 1 && grid[i + down][j] == '*') down++;

        return new int[]{left, right, up, down};
    }

    /** Processes a good star at (i, j) – marks visited cells and records the result. */
    private static void processGoodStar(int i, int j) {
        int[] lens = computeLengths(i, j);
        int c = Math.min(Math.min(lens[0], lens[1]), Math.min(lens[2], lens[3]));

        // Mark the cross of length c in all four directions.
        for (int step = 0; step < c; step++) {
            visited[i][j - step] = true;          // left
            visited[i][j + step] = true;          // right
            visited[i - step][j] = true;          // up
            visited[i + step][j] = true;          // down
        }

        RESULT_LINES.add(String.format("%d %d %d", i + 1, j + 1, c - 1));
    }

    public static void main(String[] args) throws IOException {
        // ----- Input ---------------------------------------------------------
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String[] nm = br.readLine().split("\\s+");
        int n = Integer.parseInt(nm[0]);
        int m = Integer.parseInt(nm[1]);

        grid = new char[n][];
        visited = new boolean[n][m];

        for (int i = 0; i < n; i++) {
            grid[i] = br.readLine().toCharArray();
        }

        // ----- Core processing -----------------------------------------------
        int goodCount = 0;

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i][j] == '*' && isGoodStar(i, j)) {
                    processGoodStar(i, j);
                    goodCount++;
                }
            }
        }

        // Verify that every '*' has been visited by some processed star.
        boolean allCovered = true;
        for (int i = 0; i < n && allCovered; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i][j] == '*' && !visited[i][j]) {
                    allCovered = false;
                    break;
                }
            }
        }

        // ----- Output --------------------------------------------------------
        System.out.println(allCovered ? goodCount : -1);
        if (allCovered) {
            System.out.print(String.join("\n", RESULT_LINES));
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.io.BufferedOutputStream;
import java.util.ArrayList;
import java.util.StringTokenizer;

/**
 * Refactored Codeforces solution for "Stars Drawing" problem.
 * Maintains original functionality while improving readability and structure.
 */
public class Codeforces {

    static class Star {
        int row, col, armLength;

        Star(int row, int col, int armLength) {
            this.row = row;
            this.col = col;
            this.armLength = armLength;
        }
    }

    private static PrintWriter out;

    public static void main(String[] args) throws IOException {
        MyScanner scanner = new MyScanner();
        out = new PrintWriter(new BufferedOutputStream(System.out));

        int n = scanner.nextInt();
        int m = scanner.nextInt();

        String[] grid = new String[n];
        for (int i = 0; i < n; i++) {
            grid[i] = scanner.nextLine();
        }

        // Precompute directional asterisk counts
        int[][] upCount = computeUpwards(grid);
        int[][] downCount = computeDownwards(grid);
        int[][] leftCount = computeLeftwards(grid);
        int[][] rightCount = computeRightwards(grid);

        // Collect valid stars
        ArrayList<Star> stars = collectStars(grid, upCount, downCount, leftCount, rightCount);

        // Mark coverage using difference arrays
        int[][] diffH = new int[n][m];
        int[][] diffV = new int[n][m];
        markCoverage(stars, diffH, diffV);

        // Propagate difference arrays
        propagateDifferences(diffH, diffV);

        // Verify complete coverage of all asterisks
        if (!verifyCoverage(grid, diffH, diffV)) {
            out.println(-1);
        } else {
            out.println(stars.size());
            for (Star star : stars) {
                out.printf("%d %d %d%n", star.row + 1, star.col + 1, star.armLength);
            }
        }

        out.close();
    }

    private static int[][] computeUpwards(String[] grid) {
        int n = grid.length;
        int m = grid[0].length();
        int[][] up = new int[n][m];

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i].charAt(j) == '*') {
                    if (i == 0) {
                        up[i][j] = 0;
                    } else {
                        up[i][j] = 1 + up[i-1][j];
                    }
                } else {
                    up[i][j] = -1;
                }
            }
        }
        return up;
    }

    private static int[][] computeDownwards(String[] grid) {
        int n = grid.length;
        int m = grid[0].length();
        int[][] down = new int[n][m];

        for (int i = n - 1; i >= 0; i--) {
            for (int j = m - 1; j >= 0; j--) {
                if (grid[i].charAt(j) == '*') {
                    if (i == n - 1) {
                        down[i][j] = 0;
                    } else {
                        down[i][j] = 1 + down[i+1][j];
                    }
                } else {
                    down[i][j] = -1;
                }
            }
        }
        return down;
    }

    private static int[][] computeLeftwards(String[] grid) {
        int n = grid.length;
        int m = grid[0].length();
        int[][] left = new int[n][m];

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i].charAt(j) == '*') {
                    if (j == 0) {
                        left[i][j] = 0;
                    } else {
                        left[i][j] = 1 + left[i][j-1];
                    }
                } else {
                    left[i][j] = -1;
                }
            }
        }
        return left;
    }

    private static int[][] computeRightwards(String[] grid) {
        int n = grid.length;
        int m = grid[0].length();
        int[][] right = new int[n][m];

        for (int i = 0; i < n; i++) {
            for (int j = m - 1; j >= 0; j--) {
                if (grid[i].charAt(j) == '*') {
                    if (j == m - 1) {
                        right[i][j] = 0;
                    } else {
                        right[i][j] = 1 + right[i][j+1];
                    }
                } else {
                    right[i][j] = -1;
                }
            }
        }
        return right;
    }

    private static ArrayList<Star> collectStars(String[] grid, 
                                              int[][] upCount, int[][] downCount, 
                                              int[][] leftCount, int[][] rightCount) {
        ArrayList<Star> stars = new ArrayList<>();

        for (int i = 0; i < grid.length; i++) {
            for (int j = 0; j < grid[i].length(); j++) {
                if (grid[i].charAt(j) == '*') {
                    int armLength = Math.min(
                        Math.min(upCount[i][j], downCount[i][j]),
                        Math.min(leftCount[i][j], rightCount[i][j])
                    );
                    if (armLength > 0) {
                        stars.add(new Star(i, j, armLength));
                    }
                }
            }
        }
        return stars;
    }

    private static void markCoverage(ArrayList<Star> stars, 
                                    int[][] diffH, int[][] diffV) {
        for (Star star : stars) {
            // Horizontal coverage: mark start and end+1
            diffH[star.row][star.col - star.armLength]++;
            if (star.col + star.armLength + 1 < diffH[0].length) {
                diffH[star.row][star.col + star.armLength + 1]--;
            }

            // Vertical coverage: mark start and end+1
            diffV[star.row - star.armLength][star.col]++;
            if (star.row + star.armLength + 1 < diffV.length) {
                diffV[star.row + star.armLength + 1][star.col]--;
            }
        }
    }

    private static void propagateDifferences(int[][] diffH, int[][] diffV) {
        // Propagate horizontal differences
        for (int i = 0; i < diffH.length; i++) {
            for (int j = 1; j < diffH[i].length; j++) {
                diffH[i][j] += diffH[i][j-1];
            }
        }

        // Propagate vertical differences
        for (int j = 0; j < diffV[0].length; j++) {
            for (int i = 1; i < diffV.length; i++) {
                diffV[i][j] += diffV[i-1][j];
            }
        }
    }

    private static boolean verifyCoverage(String[] grid, 
                                         int[][] diffH, int[][] diffV) {
        for (int i = 0; i < grid.length; i++) {
            for (int j = 0; j < grid[i].length(); j++) {
                if (grid[i].charAt(j) == '*') {
                    if (diffH[i][j] <= 0 && diffV[i][j] <= 0) {
                        return false;
                    }
                }
            }
        }
        return true;
    }

    private static class MyScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        MyScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    e.printStackTrace();
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        String nextLine() {
            try {
                return br.readLine();
            } catch (IOException e) {
                e.printStackTrace();
                return "";
            }
        }
    }
}

import java.io.*;
import java.util.*;
import java.util.stream.Collectors;

/**
 * Refactored version of the original solution.
 *
 * <p>Changes made for readability and maintainability:
 *
 * <ul>
 *   <li>Extracted scanner utilities into a dedicated {@code FastScanner} class.</li>
 *   <li>Encapsulated the solving logic inside {@code SolverEngine}.</li>
 *   <li>Renamed variables and methods to convey their purpose.</li>
 *   <li>Removed unnecessary static imports and unused utility methods.</li>
 *   <li>Used enhanced {@code for} loops where appropriate.</li>
 *   <li>Introduced {@code StarInfo} to hold star metadata.</li>
 *   <li>Added JavaDoc comments and consistent code style.</li>
 * </ul>
 */
public class StarPatternSolver {

    /** Simple wrapper around {@link BufferedReader} that tokenises input lines. */
    private static final class FastScanner {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        FastScanner(Reader source) {
            this.reader = new BufferedReader(source);
        }

        /** Makes sure a {@link StringTokenizer} is available. */
        private void ensureTokenizer() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                tokenizer = new StringTokenizer(reader.readLine());
            }
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }

        long nextLong() throws IOException {
            return Long.parseLong(next());
        }

        double nextDouble() throws IOException {
            return Double.parseDouble(next());
        }

        /** Returns the next token, reading a new line if necessary. */
        String next() throws IOException {
            ensureTokenizer();
            return tokenizer.nextToken();
        }

        /** Closes the underlying reader. */
        void close() throws IOException {
            reader.close();
        }
    }

    /** Entry point – delegates all work to {@link SolverEngine}. */
    public static void main(String[] args) throws Exception {
        try (FastScanner scanner = new FastScanner(new InputStreamReader(System.in));
             PrintWriter writer = new PrintWriter(new OutputStreamWriter(System.out))) {

            solve(scanner, writer);
        } catch (Throwable e) {
            e.printStackTrace();
            System.exit(1);
        }
    }

    /** Orchestrates reading, processing and outputting the result. */
    private static void solve(FastScanner in, PrintWriter out) throws IOException {
        int n = in.nextInt();          // number of rows
        int m = in.nextInt();          // number of columns
        char[][] original = new char[n][];
        for (int i = 0; i < n; i++) {
            original[i] = in.next().toCharArray();
        }

        SolverEngine engine = new SolverEngine(original);
        engine.process();

        if (!engine.isOriginalEqualsResult()) {
            out.println(-1);
            return;
        }

        out.println(engine.getStarCount());
        engine.printStars(out);
    }

    /** Core logic that analyses the grid, collects stars and validates the transformation. */
    private static final class SolverEngine {
        private final char[][] grid;          // original input grid
        private final int rows, cols;          // dimensions
        private final int[][] up, down, left, right; // directional counters
        private final char[][] result;        // grid after drawing all stars
        private final List<StarInfo> stars = new ArrayList<>();

        SolverEngine(char[][] grid) {
            this.grid = grid;
            this.rows = grid.length;
            this.cols = grid[0].length;
            this.up = new int[rows][cols];
            this.down = new int[rows][cols];
            this.left = new int[rows][cols];
            this.right = new int[rows][cols];
            this.result = new char[rows][];
            for (int i = 0; i < rows; i++) {
                result[i] = new char[cols];
                Arrays.fill(result[i], '.');
            }
        }

        /** Computes the four directional counts (up, down, left, right). */
        private void fillDirectionalCounts() {
            fillUp();
            fillDown();
            fillLeft();
            fillRight();
        }

        private void fillUp() {
            for (int j = 0; j < cols; j++) {
                int count = 0;
                for (int i = 0; i < rows; i++) {
                    count = isAlive(grid[i][j]) ? count + 1 : 0;
                    up[i][j] = count;
                }
            }
        }

        private void fillDown() {
            for (int j = 0; j < cols; j++) {
                int count = 0;
                for (int i = rows - 1; i >= 0; i--) {
                    count = isAlive(grid[i][j]) ? count + 1 : 0;
                    down[i][j] = count;
                }
            }
        }

        private void fillLeft() {
            for (int i = 0; i < rows; i++) {
                int count = 0;
                for (int j = 0; j < cols; j++) {
                    count = isAlive(grid[i][j]) ? count + 1 : 0;
                    left[i][j] = count;
                }
            }
        }

        private void fillRight() {
            for (int i = 0; i < rows; i++) {
                int count = 0;
                for (int j = cols - 1; j >= 0; j--) {
                    count = isAlive(grid[i][j]) ? count + 1 : 0;
                    right[i][j] = count;
                }
            }
        }

        /** Checks whether a cell contains a non‑dot character. */
        private boolean isAlive(char c) {
            return c != '.';
        }

        /** Collects all stars (crosses) and draws them on the result grid. */
        private void collectStars() {
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    int size = Math.min(
                            Math.min(up[i][j], down[i][j]),
                            Math.min(left[i][j], right[i][j])
                    );
                    if (size > 1) {
                        StarInfo star = new StarInfo(i, j, size - 1);
                        stars.add(star);
                        // draw the cross (+) on the result grid
                        for (int offset = 0; offset < size; offset++) {
                            result[i + offset][j] = '*';
                            result[i - offset][j] = '*';
                            result[i][j + offset] = '*';
                            result[i][j - offset] = '*';
                        }
                    }
                }
            }
        }

        /** Verifies that the reconstructed grid matches the original one. */
        private void verifyConsistency() {
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (grid[i][j] != result[i][j]) {
                        throw new IllegalStateException("Inconsistent reconstruction");
                    }
                }
            }
        }

        /** Returns true if the transformed grid equals the original input. */
        private boolean isOriginalEqualsResult() {
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (grid[i][j] != result[i][j]) {
                        return false;
                    }
                }
            }
            return true;
        }

        /** Number of stars that were added. */
        private int getStarCount() {
            return stars.size();
        }

        /** Prints each star’s centre (1‑based) and its radius. */
        private void printStars(PrintWriter out) {
            for (StarInfo star : stars) {
                out.printf("%d %d %d%n", star.row + 1, star.col + 1, star.radius);
            }
        }

        /** Simple container for star metadata. */
        private static final class StarInfo {
            final int row;   // 0‑based row index
            final int col;   // 0‑based column index
            final int radius;// = size‑1, i.e. half‑length of the arm

            StarInfo(int row, int col, int radius) {
                this.row = row;
                this.col = col;
                this.radius = radius;
            }
        }
    }
}

import java.io.*;
import java.util.*;

public class A {

    private static final class Pair implements Comparable<Pair> {
        final int x, y, z; // row, column, size

        Pair(int x, int y, int z) {
            this.x = x;
            this.y = y;
            this.z = z;
        }

        @Override
        public int compareTo(Pair o) {
            return Integer.compare(this.x, o.x);
        }
    }

    private static FastScanner sc;
    private static PrintWriter out;

    public static void main(String[] args) throws IOException {
        boolean useOnlineJudge = true;
        if (useOnlineJudge) {
            sc = new FastScanner();
            out = new PrintWriter(System.out);
        } else {
            sc = new FastScanner(100);
            out = new PrintWriter("output.txt");
        }

        int tests = 1;
        while (tests-- > 0) {
            solve();
        }

        out.flush();
        out.close();
    }

    /** Entry point of the solving routine. */
    private static void solve() throws IOException {
        int n = sc.nextInt();
        int m = sc.nextInt();

        // 1‑based indexing makes the original logic easier to follow.
        char[][] grid = new char[n + 2][m + 2];
        int[][] covered = new int[n + 2][m + 2];

        // Initialise the grid with '.' (empty) and read the input pattern.
        for (int i = 0; i <= n + 1; i++) {
            Arrays.fill(grid[i], '.');
        }
        for (int i = 1; i <= n; i++) {
            String line = sc.next();
            for (int j = 1; j <= m; j++) {
                char ch = line.charAt(j - 1);
                grid[i][j] = ch;
                if (ch == '*') {
                    covered[i][j] = 1; // mark a star cell
                }
            }
        }

        List<Pair> centres = new ArrayList<>();

        // Find every valid star centre and paint it.
        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= m; j++) {
                if (isStarCenter(grid, i, j)) {
                    int radius = paintStar(i, j, grid, covered, n, m);
                    centres.add(new Pair(i, j, radius));
                }
            }
        }

        // Verify that all star positions have been covered; otherwise output -1.
        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= m; j++) {
                if (covered[i][j] != 0) {
                    out.println(-1);
                    return;
                }
            }
        }

        // Output the result.
        out.println(centres.size());
        for (Pair p : centres) {
            out.println(p.x + " " + p.y + " " + p.z);
        }
    }

    /** Determines whether the cell (i,j) is the centre of a plus‑shaped star. */
    private static boolean isStarCenter(char[][] g, int i, int j) {
        // Must be inside the grid and contain a star.
        if (i <= 0 || i >= g.length || j <= 0 || j >= g[0].length || g[i][j] != '*') {
            return false;
        }
        // All four orthogonal neighbours must also contain a star.
        return g[i - 1][j] == '*' && g[i + 1][j] == '*' &&
               g[i][j - 1] == '*' && g[i][j + 1] == '*';
    }

    /**
     * Computes the maximal radius of the star centred at (i,j) and marks the
     * corresponding arm cells as cleared in the auxiliary {@code covered}
     * matrix.
     *
     * @return the radius (extension length) of the painted star
     */
    private static int paintStar(int i, int j, char[][] g, int[][] covered, int n, int m) {
        int up = countConsecutive(g, i - 1, j, -1, 0);
        int down = countConsecutive(g, i + 1, j, 1, 0);
        int left = countConsecutive(g, i, j - 1, 0, -1);
        int right = countConsecutive(g, i, j + 1, 0, 1);

        int radius = Math.min(Math.min(up, down), Math.min(left, right));

        // Clear the whole arm in the auxiliary matrix.
        for (int k = 0; k <= radius; k++) {
            covered[i + k][j] = 0;
            covered[i - k][j] = 0;
            covered[i][j + k] = 0;
            covered[i][j - k] = 0;
        }
        return radius;
    }

    /** Counts consecutive '*' cells starting from (r,c) moving by (dr,dc). */
    private static int countConsecutive(char[][] g, int r, int c, int dr, int dc) {
        int cnt = 0;
        while (r >= 0 && r < g.length && c >= 0 && c < g[0].length && g[r][c] == '*') {
            cnt++;
            r += dr;
            c += dc;
        }
        return cnt;
    }

    /* --------------------------------------------------------------
     * I/O utility classes (kept unchanged for compatibility)
     * -------------------------------------------------------------- */
    static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner() throws FileNotFoundException {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        FastScanner(int ignored) throws FileNotFoundException {
            br = new BufferedReader(new FileReader("input.txt"));
        }

        String next() throws IOException {
            while (st == null || !st.hasMoreElements()) {
                st = new StringTokenizer(br.readLine());
            }
            return st.nextToken();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }

        long nextLong() throws IOException {
            return Long.parseLong(next());
        }

        double nextDouble() throws IOException {
            return Double.parseDouble(next());
        }

        String nextLine() throws IOException {
            String str = "";
            try {
                str = br.readLine();
            } catch (IOException e) {
                e.printStackTrace();
            }
            return str;
        }

        int[] readArray(int n) throws IOException {
            int[] a = new int[n];
            for (int i = 0; i < n; i++) {
                a[i] = nextInt();
            }
            return a;
        }

        long[] readArrayLong(int n) throws IOException {
            long[] a = new long[n];
            for (int i = 0; i < n; i++) {
                a[i] = nextLong();
            }
            return a;
        }
    }

    static void println(Object o) { out.println(o); }
    static void println() { out.println(); }
    static void print(Object o) { out.print(o); }
    static void pflush(Object o) { out.println(o); out.flush(); }

    static int ceil(int x, int y) { return (x % y == 0 ? x / y : x / y + 1); }
    static long ceil(long x, long y) { return (x % y == 0 ? x / y : x / y + 1); }
    static int max(int x, int y) { return Math.max(x, y); }
    static int min(int x, int y) { return Math.min(x, y); }
    static int abs(int x) { return Math.abs(x); }
    static long max(long x, long y) { return Math.max(x, y); }
    static long min(long x, long y) { return Math.min(x, y); }
    static int log2(int N) { return (int) (Math.log(N) / Math.log(2)); }
    static long gcd(int a, int b) { return BigInteger.valueOf(a).gcd(BigInteger.valueOf(b)).intValue(); }
    static long gcd(long a, long b) { return BigInteger.valueOf(a).gcd(BigInteger.valueOf(b)).longValue(); }
}

import java.io.IOException;
import java.io.InputStream;
import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;

/**
 * Refactored solution for the “Crosses” problem.
 *
 * <p>Improvements over the original code:
 *
 * <ul>
 *   <li>Descriptive naming (e.g. {@code grid} instead of {@code a})</li>
 *   <li>Extraction of logical parts into small, reusable methods</li>
 *   <li>Removal of unused imports and unnecessary exceptions</li>
 *   <li>Use of try‑with‑resources for {@link Scanner}</li>
 *   <li>Clear separation of input handling, processing and output</li>
 *   <li>Constants instead of magic numbers</li>
 *   <li>Immutable data holder {@link Cross} for better readability</li>
 * </ul>
 */
public final class Solution {

    /** Position and size of a detected cross. */
    private static final class Cross {
        final int row;      // 0‑based
        final int col;      // 0‑based
        final int size;     // number of steps from center to an arm

        Cross(int row, int col, int size) {
            this.row = row;
            this.col = col;
            this.size = size;
        }

        /** Convert to 1‑based coordinates for output. */
        int[] toOneBased() {
            return new int[]{row + 1, col + 1, size};
        }
    }

    /** Directions used when expanding a cross. */
    private static final int[] DRIFT = {1, -1};

    /** Minimum interior index (grid size is at least 3). */
    private static final int BOUNDARY = 1;

    /** Maximum interior index (grid size is at most MAX - 2). */
    private static final int MAX = 1000;   // assumed upper bound from original code

    /** Entry point. */
    public static void main(String[] args) throws IOException {
        // The original code expected a single test case; we read the number of cases
        // if it is present, otherwise we treat the input as a single case.
        try (Scanner scanner = new Scanner(new InputStream[]{System.in})) {
            solve(scanner);
        }
    }

    /** Core logic – reads, processes and prints results for all test cases. */
    private static void solve(Scanner scanner) {
        /* The original snippet used an odd trick to run exactly once.
         * For clarity we read an explicit number of test cases if it exists. */
        int testCases = scanner.hasNextInt() ? scanner.nextInt() : 1;
        for (int t = 0; t < testCases; t++) {
            solveSingleCase(scanner);
        }
    }

    /** Process one test case: read grid, detect crosses, and print the answer. */
    private static void solveSingleCase(Scanner scanner) {
        int n = scanner.nextInt();               // number of rows
        int m = scanner.nextInt();               // number of columns
        List<String> grid = readGrid(scanner, n);

        // collected crosses and a coverage map
        List<Cross> crosses = new ArrayList<>();
        boolean[][] covered = new boolean[n][m];

        // 1️⃣ Detect every possible cross centered on an interior '*' cell
        for (int i = BOUNDARY; i < n - BOUNDARY; i++) {
            String row = grid.get(i);
            for (int j = BOUNDARY; j < m - BOUNDARY; j++) {
                if (row.charAt(j) != '*') {
                    continue;
                }
                int size = expandCross(grid, i, j);
                if (size > 0) {
                    crosses.add(new Cross(i, j, size));
                    markCovered(covered, i, j, size);
                }
            }
        }

        // 2️⃣ Verify that every '*' in the original grid is covered
        boolean uncoveredStarExists = hasUncoveredStar(grid, covered);
        if (uncoveredStarExists) {
            System.out.println(-1);
        } else {
            System.out.println(crosses.size());
            for (Cross c : crosses) {
                int[] out = c.toOneBased();
                System.out.println(out[0] + " " + out[1] + " " + out[2]);
            }
        }
    }

    /** Reads exactly {@code rows} lines from the scanner into a list. */
    private static List<String> readGrid(Scanner scanner, int rows) {
        List<String> result = new ArrayList<>(rows);
        for (int i = 0; i < rows; i++) {
            result.add(scanner.next());
        }
        return result;
    }

    /**
     * Expands a cross from its centre (i, j) outward until a boundary or a '.' is hit.
     *
     * @return the number of steps each arm extends, or 0 if the centre is not part of a cross.
     */
    private static int expandCross(List<String> grid, int centerRow, int centerCol) {
        int size = 0;
        while (true) {
            // check the four neighbours at distance (size + 1)
            if (isOutOfBounds(centerRow, centerCol, size + 1) ||
               isArmInterrupted(grid, centerRow, centerCol, size + 1)) {
                break;
            }
            size++;
        }
        return size;
    }

    /** Returns true if expanding one more step would go outside the grid. */
    private static boolean isOutOfBounds(int r, int c, int step) {
        return (c - step) < 0 || (c + step) >= gridWidth
                || (r - step) < 0 || (r + step) >= gridHeight;
    }

    /** Returns true if any of the four cells at the given step is '.' . */
    private static boolean isArmInterrupted(List<String> grid, int r, int c, int step) {
        String row = grid.get(r);
        return row.charAt(c - step) == '.' ||
               row.charAt(c + step) == '.' ||
               grid.get(r - step).charAt(c) == '.' ||
               grid.get(r + step).charAt(c) == '.';
    }

    /** Marks all cells belonging to a discovered cross as covered. */
    private static void markCovered(boolean[][] covered, int centerRow, int centerCol, int size) {
        covered[centerRow][centerCol] = true;
        for (int k = 1; k <= size; k++) {
            covered[centerRow][centerCol - k] = true;
            covered[centerRow][centerCol + k] = true;
            covered[centerRow - k][centerCol] = true;
            covered[centerRow + k][centerCol] = true;
        }
    }

    /** Checks whether there exists a '*' that has not been covered by any cross. */
    private static boolean hasUncoveredStar(List<String> grid, boolean[][] covered) {
        for (int i = 0; i < gridHeight; i++) {
            String row = grid.get(i);
            for (int j = 0; j < gridWidth; j++) {
                if (row.charAt(j) == '*' && !covered[i][j]) {
                    return true;
                }
            }
        }
        return false;
    }

    /* ---------- runtime‑only fields, initialized after reading dimensions ---------- */
    private static List<String> grid;
    private static int gridHeight;
    private static int gridWidth;
}

import java.io.*;
import java.util.*;

/**
 * Entry point of the application.
 * Reads a single test case, solves it and prints the result.
 */
public class Program {

    /** Simple closeable wrapper around {@link Scanner}. */
    private static final class InputReader implements Closeable {
        private final Scanner scanner;

        InputReader(InputStream source) {
            this.scanner = new Scanner(source);
        }

        int nextInt() {
            return scanner.nextInt();
        }

        String next() {
            return scanner.next();
        }

        @Override public void close() {
            scanner.close();
        }
    }

    /** Simple closeable wrapper around {@link PrintWriter}. */
    private static final class OutputWriter implements Closeable {
        private final PrintWriter writer;

        OutputWriter(OutputStream out) {
            this.writer = new PrintWriter(out);
        }

        void println(Object obj) {
            writer.println(obj);
        }

        @Override public void close() {
            writer.close();
        }
    }

    /** Result of a discovered plus‑shaped pattern.
     *  Stores its centre (0‑based) and the radius (half‑length of each arm). */
    private static final class Center implements Comparable<Center> {
        final int row;   // 0‑based
        final int col;   // 0‑based
        final int radius;// length of each arm from the centre

        Center(int row, int col, int radius) {
            this.row = row;
            this.col = col;
            this.radius = radius;
        }

        /** Sort descending by radius – only influences output order, not algorithmic correctness. */
        @Override public int compareTo(Center o) {
            return Integer.compare(o.radius, this.radius);
        }
    }

    /** Core algorithm that finds all pluses covering exactly the '*' cells. */
    private static final class Solver {

        /** Solves the single test case as used in the sample `Main`. */
        void solve(InputReader in, OutputWriter out) {
            int n = in.nextInt();
            int m = in.nextInt();

            char[][] grid = new char[n][];
            List<Pair> stars = new ArrayList<>();

            // ----- read the matrix and collect star positions -----
            for (int i = 0; i < n; i++) {
                String line = in.next();
                grid[i] = line.toCharArray();
                for (int j = 0; j < m; j++) {
                    if (grid[i][j] == '*') {
                        stars.add(new Pair(i, j));
                    }
                }
            }

            // ----- discover maximal symmetric pluses -----
            List<Center> centers = new ArrayList<>();
            for (Pair star : stars) {
                int r = computeMaxRadius(grid, star.row, star.col);
                if (r > 0) {
                    centers.add(new Center(star.row, star.col, r));
                }
            }

            // ----- mark all cells covered by discovered pluses -----
            boolean[][] covered = new boolean[n][m];
            for (Center c : centers) {
                covered[c.row][c.col] = true;
                for (int d = 1; d <= c.radius; d++) {
                    covered[c.row + d][c.col] = true;
                    covered[c.row - d][c.col] = true;
                    covered[c.row][c.col + d] = true;
                    covered[c.row][c.col - d] = true;
                }
            }

            // ----- validate that the coverage matches the original pattern -----
            boolean allMatch = true;
            outer:
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    boolean isStar = grid[i][j] == '*';
                    if (isStar != covered[i][j]) {
                        allMatch = false;
                        break outer;
                    }
                }
            }

            // ----- produce output -----
            if (allMatch) {
                out.println(centers.size());
                for (Center c : centers) {
                    // coordinates are 1‑based in the output
                    out.println((c.row + 1) + " " + (c.col + 1) + " " + c.radius);
                }
            } else {
                out.println(-1);
            }
        }

        /** Computes the maximal radius `w` such that a symmetric plus of size `w`
         *  centred at `(r,c)` exists (i.e., all four arms are filled with '*'). */
        private static int computeMaxRadius(char[][] grid, int r, int c) {
            int w = 0;
            while (true) {
                int next = w + 1;
                // stop if we would step outside the grid
                if (r + next >= grid.length ||
                    r - next < 0 ||
                    c + next >= grid[0].length ||
                    c - next < 0) {
                    break;
                }
                // continue only if all four required cells are '*'
                if (grid[r + next][c] == '*' &&
                    grid[r - next][c] == '*' &&
                    grid[r][c + next] == '*' &&
                    grid[r][c - next] == '*') {
                    w = next;
                } else {
                    break;
                }
            }
            return w;
        }

        /** Simple container for a star coordinate used only during input parsing. */
        private static final class Pair {
            final int row;
            final int col;
            Pair(int row, int col) {
                this.row = row;
                this.col = col;
            }
        }
    }

    /** Program entry point. */
    public static void main(String[] args) throws IOException {
        try (InputReader reader = new InputReader(System.in);
             OutputWriter writer = new OutputWriter(System.out)) {
            new Solver().solve(reader, writer);
        }
    }
}

import java.io.*;
import java.util.ArrayList;
import java.util.List;

/**
 * Solves the “hexagram placement” problem.
 *
 * <p>
 * The program reads a grid consisting of ‘*’ (filled cell) and '.' (empty cell).
 * Starting from the largest possible hexagram size it tries to place a
 * hexagram at every cell that can accommodate it.  Each placement covers
 * the centre and its four arms.  After all possible placements are found,
 * the program checks whether every ‘*’ in the input is covered.  If so it
 * prints the placements, otherwise it prints {@code -1}.
 * </p>
 */
public class HexagramPlacementSolver {

    /** Simple DTO for a hexagram placement. */
    private static final class Placement {
        final int row;        // 1‑based row index of the centre
        final int col;        // 1‑based column index of the centre
        final int size;       // arm length of the hexagram

        Placement(int row, int col, int size) {
            this.row = row;
            this.col = col;
            this.size = size;
        }

        @Override
        public String toString() {
            return row + " " + col + " " + size;
        }
    }

    /** Fast scanner that works with whitespace‑separated tokens. */
    private static final class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner() {
            this.br = new BufferedReader(new InputStreamReader(System.in));
        }

        /** Returns the next token, reading a new line if necessary. */
        private String nextToken() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                String line = br.readLine();
                if (line == null) {
                    return null; // EOF
                }
                st = new StringTokenizer(line);
            }
            return st.nextToken();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(nextToken());
        }

        long nextLong() throws IOException {
            return Long.parseLong(nextToken());
        }

        double nextDouble() throws IOException {
            return Double.parseDouble(nextToken());
        }
    }

    /** Holds the grid and all auxiliary information. */
    private static final class Grid {
        final char[][] cells;          // original input grid
        final int rows, cols;          // dimensions
        final int[][] up;              // consecutive '*' upward
        final int[][] down;            // consecutive '*' downward
        final int[][] left;            // consecutive '*' leftward
        final int[][] right;           // consecutive '*' rightward
        final boolean[][] centered;    // whether a centre has already been used
        final boolean[][] covered;     // cells already covered by a placement

        Grid(char[][] cells, int rows, int cols) {
            this.cells = cells;
            this.rows = rows;
            this.cols = cols;
            this.up = new int[rows][cols];
            this.down = new int[rows][cols];
            this.left = new int[rows][cols];
            this.right = new int[rows][cols];
            this.centered = new boolean[rows][cols];
            this.covered = new boolean[rows][cols];
        }

        /** Fill the four directional arrays. */
        void computeDirections() {
            // upward & leftward
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (cells[r][c] == '*') {
                        up[r][c] = (r > 0) ? up[r - 1][c] + 1 : 1;
                        left[r][c] = (c > 0) ? left[r][c - 1] + 1 : 1;
                    }
                }
            }

            // downward & rightward
            for (int r = rows - 1; r >= 0; r--) {
                for (int c = cols - 1; c >= 0; c--) {
                    if (cells[r][c] == '*') {
                        down[r][c] = (r + 1 < rows) ? down[r + 1][c] + 1 : 1;
                        right[r][c] = (c + 1 < cols) ? right[r][c + 1] + 1 : 1;
                    }
                }
            }
        }

        /** Checks whether a placement of the given size centred at (r,c) is possible. */
        boolean canPlace(int r, int c, int size) {
            return up[r][c] >= size + 1
                    && down[r][c] >= size + 1
                    && left[r][c] >= size + 1
                    && right[r][c] >= size + 1;
        }

        /** Marks the centre and its four arms up to `size`. */
        void markCovered(int r, int c, int size) {
            covered[r][c] = true;
            for (int off = 1; off <= size; off++) {
                covered[r + off][c] = true;
                covered[r - off][c] = true;
                covered[r][c + off] = true;
                covered[r][c - off] = true;
            }
        }

        /** Verifies that every '*' cell is covered by at least one placement. */
        boolean allStarsCovered() {
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (cells[r][c] == '*' && !covered[r][c]) {
                        return false;
                    }
                }
            }
            return true;
        }
    }

    /** Entry point. */
    public static void main(String[] args) throws IOException {
        FastScanner sc = new FastScanner();
        PrintWriter out = new PrintWriter(new BufferedOutputStream(System.out));

        /* ---------- Input ---------- */
        int m = sc.nextInt();          // number of rows
        int n = sc.nextInt();          // number of columns
        char[][] grid = new char[m][];
        for (int i = 0; i < m; i++) {
            String row = sc.next();
            grid[i] = row.toCharArray();
        }

        /* ---------- Analyse grid ---------- */
        Grid g = new Grid(grid, m, n);
        g.computeDirections();

        List<Placement> placements = new ArrayList<>();

        /* Largest possible arm length for any centre */
        int maxSize = Math.min((m - 1) / 2, (n - 1) / 2);
        for (int size = maxSize; size >= 1; size--) {
            for (int r = 0; r < m; r++) {
                for (int c = 0; c < n; c++) {
                    if (g.cells[r][c] == '*' && !g.centered[r][c] && g.canPlace(r, c, size)) {
                        g.centered[r][c] = true;
                        g.markCovered(r, c, size);
                        placements.add(new Placement(r + 1, c + 1, size));
                    }
                }
            }
        }

        /* ---------- Validation ---------- */
        boolean possible = g.allStarsCovered()
                && placements.size() <= m * n;   // sanity check from original code

        if (possible) {
            out.println(placements.size());
            for (Placement p : placements) {
                out.println(p);
            }
        } else {
            out.println(-1);
        }

        out.close();
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.ArrayList;
import java.util.List;

/**
 * Reads a grid of characters, finds all “star” crosses and prints the
 * positions (1‑based) together with the size of each cross.
 *
 * <p>Rules
 * <ul>
 *   <li>A cross is a centre cell '*' that can be expanded equally in the four
 *       orthogonal directions while all four cells at each step are also '*'.</li>
 *   <li>All cells belonging to a discovered cross are marked so that a single
 *       '*' cannot belong to more than one cross.</li>
 *   <li>After processing the whole grid we verify that *every* '*' cell has
 *       been covered by some cross. If not, the program outputs <code>-1</code>.</li>
 * </ul>
 *
 * <p>This implementation is deliberately split into small, reusable methods
 * and uses meaningful names, immutable data holders and clear separation of
 * concerns – making the code easy to read, test and extend.
 */
public class Contest_11_18 {

    /** Simple immutable holder for a discovered star. */
    private static final class Star {
        private final int row;      // 1‑based row index
        private final int col;      // 1‑based column index
        private final int size;     // length of each arm (>=1)

        Star(int row, int col, int size) {
            this.row = row;
            this.col = col;
            this.size = size;
        }

        int getRow()   { return row; }
        int getCol()   { return col; }
        int getSize()  { return size; }
    }

    /** Returns a list with all stars found in the supplied grid. */
    private static List<Star> findStars(char[][] grid, boolean[][] visited) {
        int rows = grid.length;     // = m
        int cols = grid[0].length;  // = n
        List<Star> stars = new ArrayList<>();

        // Scan only interior cells (border cannot be a centre of a cross)
        for (int r = 1; r < rows - 1; r++) {
            for (int c = 1; c < cols - 1; c++) {
                if (grid[r][c] != '*') {
                    continue;               // not a potential centre
                }
                Star star = expandCross(r, c, grid, visited);
                if (star != null && star.getSize() > 0) {
                    stars.add(star);
                }
            }
        }
        return stars;
    }

    /**
     * Tries to grow a cross centred at {@code (r,c)}.
     *
     * @return a {@link Star} object describing the discovered cross,
     *         or {@code null} if no cross (size >= 1) can be formed.
     */
    private static Star expandCross(int centreRow, int centreCol,
                                    char[][] grid, boolean[][] visited) {
        int maxArm = Math.min(grid.length, grid[0].length); // safety bound
        int arm = 1;
        int size = 0;                     // number of successfully expanded steps

        while (true) {
            int up    = centreRow - arm;
            int down  = centreRow + arm;
            int left  = centreCol - arm;
            int right = centreCol + arm;

            // stop if any neighbour is out of bounds or not '*'
            if (up < 0 || down >= grid.length
                    || left < 0 || right >= grid[0].length) {
                break;
            }
            if (grid[up][centreCol] != '*' ||
                grid[down][centreCol] != '*' ||
                grid[centreRow][left] != '*' ||
                grid[centreRow][right] != '*') {
                break;
            }

            // mark the four new arm cells (and the centre on the first iteration)
            visited[up][centreCol]   = true;
            visited[down][centreCol] = true;
            visited[centreRow][left] = true;
            visited[centreRow][right]= true;
            size = arm;                     // current arm length
            arm++;
        }

        // If we never expanded, the centre alone does not constitute a star.
        if (size == 0) {
            return null;
        }

        // Mark the centre cell as visited (it was not marked inside the loop)
        visited[centreRow][centreCol] = true;

        // Convert to 1‑based coordinates for output
        return new Star(centreRow + 1, centreCol + 1, size + 1);
    }

    public static void main(String[] args) throws IOException {
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in))) {
            // -----------------------------------------------------------------
            // 1️⃣  Read dimensions and the grid
            // -----------------------------------------------------------------
            String[] dims = br.readLine().trim().split("\\s+");
            if (dims.length < 2) {
                System.err.println("Invalid input: expected two integers for dimensions.");
                return;
            }
            int n = Integer.parseInt(dims[0]);   // number of columns
            int m = Integer.parseInt(dims[1]);   // number of rows

            char[][] grid = new char[m][n];      // grid[row][col]
            boolean[][] visited = new boolean[m][n]; // tracks cells used by a star

            for (int r = 0; r < m; r++) {
                String[] tokens = br.readLine().trim().split("\\s+");
                if (tokens.length != n) {
                    System.err.println("Row " + (r + 1) + " does not contain exactly " + n + " elements.");
                    return;
                }
                for (int c = 0; c < n; c++) {
                    char ch = tokens[c].charAt(0);
                    grid[r][c] = ch;
                    visited[r][c] = false;      // initially nothing is covered
                }
            }

            // -----------------------------------------------------------------
            // 2️⃣  Discover all stars
            // -----------------------------------------------------------------
            List<Star> stars = findStars(grid, visited);

            // -----------------------------------------------------------------
            // 3️⃣  Verify that every '*' cell belongs to some star
            // -----------------------------------------------------------------
            boolean allStarsCovered = true;
            outer:
            for (int r = 0; r < m; r++) {
                for (int c = 0; c < n; c++) {
                    if (grid[r][c] == '*' && !visited[r][c]) {
                        allStarsCovered = false;
                        break outer;
                    }
                }
            }

            if (!allStarsCovered) {
                System.out.println("-1");
                return;
            }

            // -----------------------------------------------------------------
            // 4️⃣  Output result
            // -----------------------------------------------------------------
            System.out.println(stars.size());
            for (Star s : stars) {
                System.out.println(s.getRow() + " " + s.getCol() + " " + s.getSize());
            }
        }
    }
}

import java.io.*;
import java.util.*;

public class Main {

    /** Simple container for a discovered star pattern. */
    private static final class Star {
        final int col;      // x coordinate
        final int row;      // y coordinate
        final int radius;   // full radius (must be >= 2)

        Star(int col, int row, int radius) {
            this.col = col;
            this.row = row;
            this.radius = radius;
        }
    }

    /** Event used for sweep‑line (difference array) technique. */
    private static final class Event implements Comparable<Event> {
        final int pos;   // coordinate where event occurs
        final int delta; // +1 for start, -1 for end

        Event(int pos, int delta) {
            this.pos = pos;
            this.delta = delta;
        }

        @Override
        public int compareTo(Event o) {
            return Integer.compare(pos, o.pos);
        }
    }

    /** Reads dimensions and picture from stdin. */
    private static boolean[][] readBoard(FastScanner fs) throws IOException {
        int width  = fs.nextInt();   // number of columns
        int height = fs.nextInt();   // number of rows
        boolean[][] board = new boolean[width][height];
        for (int y = 0; y < height; ++y) {
            String line = fs.next();
            char[] chars = line.toCharArray();
            for (int x = 0; x < width; ++x) {
                board[x][y] = chars[x] == '*';
            }
        }
        return board;
    }

    /** Holds the four directional line counters. */
    private static final class DirectionalCounters {
        final int[][] left;   // from left edge to right
        final int[][] right;  // from right edge to left
        final int[][] up;     // from top edge downwards
        final int[][] down;   // from bottom edge upwards

        DirectionalCounters(int w, int h) {
            left  = new int[w][h];
            right = new int[w][h];
            up    = new int[w][h];
            down  = new int[w][h];
        }
    }

    /** Computes left, right, up and down counters for each cell. */
    private static DirectionalCounters computeCounters(boolean[][] board) {
        int w = board.length;          // width
        int h = board[0].length;       // height
        DirectionalCounters dc = new DirectionalCounters(w, h);

        // left & up – forward scan
        for (int x = 0; x < w; ++x) {
            for (int y = 0; y < h; ++y) {
                if (board[x][y]) {
                    dc.left[x][y] = (x == 0) ? 1 : dc.left[x - 1][y] + 1;
                    dc.up[x][y]   = (y == 0) ? 1 : dc.up[x][y - 1] + 1;
                } else {
                    dc.left[x][y] = 0;
                    dc.up[x][y]   = 0;
                }
            }
        }

        // right & down – backward scan
        for (int x = w - 1; x >= 0; --x) {
            for (int y = h - 1; y >= 0; --y) {
                if (board[x][y]) {
                    dc.right[x][y] = (x == w - 1) ? 1 : dc.right[x + 1][y] + 1;
                    dc.down[x][y]  = (y == h - 1) ? 1 : dc.down[x][y + 1] + 1;
                } else {
                    dc.right[x][y] = 0;
                    dc.down[x][y]  = 0;
                }
            }
        }
        return dc;
    }

    /** Collects all stars whose radius is at least 2. */
    private static List<Star> collectStars(boolean[][] board,
                                           DirectionalCounters counters) {
        int w = board.length;
        int h = board[0].length;
        List<Star> stars = new ArrayList<>();

        for (int x = 0; x < w; ++x) {
            for (int y = 0; y < h; ++y) {
                int radius = Math.min(
                        Math.min(counters.left[x][y], counters.right[x][y]),
                        Math.min(counters.up[x][y], counters.down[x][y])
                );
                if (radius >= 2) {
                    stars.add(new Star(x, y, radius));
                }
            }
        }
        return stars;
    }

    /** Marks cells belonging to at least one discovered star using sweep lines. */
    private static void markPainted(int width, int height,
                                    List<Star> stars, boolean[][] painted) {
        // ----- row sweep (events per column) -----
        @SuppressWarnings("unchecked")
        List<Event>[] eventsOnX = new List[width];
        for (int x = 0; x < width; ++x) {
            eventsOnX[x] = new ArrayList<>();
        }
        for (Star s : stars) {
            int startY = s.row - s.radius + 1;
            int endY   = s.row + s.radius - 1;
            eventsOnX[s.col].add(new Event(startY, 1));
            eventsOnX[s.col].add(new Event(endY + 1, -1));
        }

        for (int x = 0; x < width; ++x) {
            Collections.sort(eventsOnX[x]);
            int inCount = 0;
            int idx = 0;
            for (int y = 0; y < height; ++y) {
                while (idx < eventsOnX[x].size() && eventsOnX[x].get(idx).pos == y) {
                    inCount += eventsOnX[x].get(idx).delta;
                    ++idx;
                }
                painted[x][y] = inCount > 0;
            }
        }

        // ----- column sweep (events per row) -----
        @SuppressWarnings("unchecked")
        List<Event>[] eventsOnY = new List[height];
        for (int y = 0; y < height; ++y) {
            eventsOnY[y] = new ArrayList<>();
        }
        for (Star s : stars) {
            int startX = s.col - s.radius + 1;
            int endX   = s.col + s.radius - 1;
            eventsOnY[s.row].add(new Event(startX, 1));
            eventsOnY[s.row].add(new Event(endX + 1, -1));
        }

        for (int y = 0; y < height; ++y) {
            Collections.sort(eventsOnY[y]);
            int inCount = 0;
            int idx = 0;
            for (int x = 0; x < width; ++x) {
                while (idx < eventsOnY[y].size() && eventsOnY[y].get(idx).pos == x) {
                    inCount += eventsOnY[y].get(idx).delta;
                    ++idx;
                }
                painted[x][y] = painted[x][y] && (inCount > 0);
            }
        }
    }

    /** Verifies that the union of stars exactly reproduces the original board. */
    private static boolean validate(boolean[][] original, boolean[][] painted) {
        for (int x = 0; x < original.length; ++x) {
            for (int y = 0; y < original[0].length; ++y) {
                if (original[x][y] != painted[x][y]) {
                    return false;
                }
            }
        }
        return true;
    }

    /** Main driver */
    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();
        boolean[][] board = readBoard(fs);

        DirectionalCounters counters = computeCounters(board);
        List<Star> stars = collectStars(board, counters);

        boolean[][] painted = new boolean[board.length][board[0].length];
        markPainted(board.length, board[0].length, stars, painted);

        if (!validate(board, painted)) {
            System.out.println(-1);
            return;
        }

        PrintWriter out = new PrintWriter(System.out);
        out.println(stars.size());
        for (Star s : stars) {
            // output uses 1‑based coordinates as in the original code
            out.printf("%d %d %d%n", s.row + 1, s.col + 1, s.radius - 1);
        }
        out.close();
    }

    /** Minimal scanner supporting nextInt, nextLong, etc. */
    private static final class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner() throws IOException {
            this.br = new BufferedReader(new InputStreamReader(System.in));
        }

        private String nextToken() throws IOException {
            while (st == null || !st.hasMoreElements()) {
                String line = br.readLine();
                if (line == null) return null;
                st = new StringTokenizer(line);
            }
            return st.nextToken();
        }

        String next() throws IOException { return nextToken(); }

        int nextInt() throws IOException { return Integer.parseInt(next()); }

        long nextLong() throws IOException { return Long.parseLong(next()); }

        int[] readArray(int n) throws IOException {
            int[] a = new int[n];
            for (int i = 0; i < n; ++i) a[i] = nextInt();
            return a;
        }

        double nextDouble() throws IOException { return Double.parseDouble(next()); }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.StringTokenizer;

/**
 * Refactored solution for the problem.
 * The program reads a grid of '*' cells and determines whether all '*' cells can be
 * covered by plus‑shaped crosses. If possible it prints the number of crosses,
 * their centres and arm lengths; otherwise it prints -1.
 */
public class F_CF {

    /* ---------- Fast input scanner ---------- */
    private static final class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner(InputStream in) throws IOException {
            br = new BufferedReader(new InputStreamReader(in), 32768);
        }

        private void ensureTokenizer() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                String line = br.readLine();
                if (line != null) {
                    st = new StringTokenizer(line);
                }
            }
        }

        String next() throws IOException {
            ensureTokenizer();
            return st.nextToken();
        }

        int ni() throws IOException {
            return Integer.parseInt(next());
        }

        String nextLine() throws IOException {
            return br.readLine();
        }
    }

    /* ---------- Result holder ---------- */
    private static final class Result {
        final boolean valid;
        final int count;
        final StringBuilder details;

        Result(boolean valid, int count, StringBuilder details) {
            this.valid = valid;
            this.count = count;
            this.details = details;
        }
    }

    public static void main(String[] args) throws Exception {
        try (FastScanner fs = new FastScanner(System.in);
             PrintWriter out = new PrintWriter(System.out)) {

            int t = fs.ni();                     // number of test cases
            StringBuilder globalOut = new StringBuilder();

            for (int tc = 0; tc < t; tc++) {
                int n = fs.ni();
                int m = fs.ni();
                char[][] grid = new char[n][];
                for (int i = 0; i < n; i++) {
                    grid[i] = fs.nextLine().toCharArray();
                }

                Result res = solve(n, m, grid);
                if (res.valid) {
                    globalOut.append(res.count).append('\n');
                    globalOut.append(res.details).append('\n');
                } else {
                    globalOut.append(-1).append('\n');
                }
            }
            out.print(globalOut);
        }
    }

    /**
     * Core logic – processes a single test case.
     *
     * @param n number of rows
     * @param m number of columns
     * @param grid character grid ('*' denotes an obstacle)
     * @return {@link Result} containing validation flag, number of crosses,
     *         and textual output to be printed.
     */
    private static Result solve(int n, int m, char[][] grid) {
        // 1️⃣  Build binary obstacle matrix
        int[][] obstacle = new int[n][m];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i][j] == '*') {
                    obstacle[i][j] = 1;
                }
            }
        }

        // 2️⃣  Directional cumulative counts (length of consecutive obstacles)
        int[][] left  = copyAndPropagate(obstacle, 0,  1); // left → right
        int[][] right = copyAndPropagate(obstacle, 0, -1); // right → left
        int[][] up    = copyAndPropagate(obstacle, 1,  0); // top  → bottom
        int[][] down  = copyAndPropagate(obstacle, -1, 0); // bottom → top

        // 3️⃣  Prepare data structures for output and coverage tracking
        StringBuilder details = new StringBuilder();
        int totalCovers = 0;

        // difference arrays for efficient range updates
        int[][] rowDiff = new int[n + 1][m];   // vertical coverage
        int[][] colDiff = new int[n][m + 1];   // horizontal coverage

        // 4️⃣  Identify plus‑shaped crosses
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (obstacle[i][j] == 0) {
                    continue; // no obstacle → cannot be a centre
                }

                // maximal arm length in each direction
                int arm = Math.min(
                        Math.min(left[i][j], right[i][j]),
                        Math.min(up[i][j],   down[i][j])
                );

                if (arm <= 1) { // arm length 0 or 1 yields no cross
                    continue;
                }

                int effectiveArm = arm - 1; // number of cells reachable in each direction
                totalCovers++;

                // Record centre and arm length
                details.append(i + 1).append(' ')
                       .append(j + 1).append(' ')
                       .append(effectiveArm).append('\n');

                // Register coverage using difference arrays
                int top = i - effectiveArm;
                int bottom = i + effectiveArm;
                rowDiff[top][j]++;
                if (bottom + 1 < n) {
                    rowDiff[bottom + 1][j]--;
                }

                int leftIdx = j - effectiveArm;
                int rightIdx = j + effectiveArm;
                colDiff[i][leftIdx]++;
                if (rightIdx + 1 < m) {
                    colDiff[i][rightIdx + 1]--;
                }
            }
        }

        // 5️⃣  Compute coverage of every cell using the difference arrays
        boolean[][] covered = new boolean[n][m];

        // Horizontal sweep (columns)
        for (int i = 0; i < n; i++) {
            int running = 0;
            for (int j = 0; j < m; j++) {
                running += colDiff[i][j];
                if (running > 0) {
                    covered[i][j] = true;
                }
            }
        }

        // Vertical sweep (rows)
        for (int j = 0; j < m; j++) {
            int running = 0;
            for (int i = 0; i < n; i++) {
                running += rowDiff[i][j];
                if (running > 0) {
                    covered[i][j] = true;
                }
            }
        }

        // 6️⃣  Verify that every obstacle is covered by at least one cross
        boolean allCovered = true;
        for (int i = 0; i < n && allCovered; i++) {
            for (int j = 0; j < m; j++) {
                if (obstacle[i][j] == 1 && !covered[i][j]) {
                    allCovered = false;
                    break;
                }
            }
        }

        return new Result(allCovered, totalCovers, details);
    }

    /**
     * Copies the source matrix and propagates values in the given direction.
     *
     * @param src    source binary matrix
     * @param dr     row step (e.g., 1 for “down”, -1 for “up”)
     * @param dc     column step (e.g., 1 for “right”, -1 for “left”)
     * @return a new matrix where each cell contains the length of the consecutive
     *         obstacle sequence ending at that cell in the specified direction.
     */
    private static int[][] copyAndPropagate(int[][] src, int dr, int dc) {
        int n = src.length;
        int m = src[0].length;
        int[][] dst = new int[n][m];
        System.arraycopy(src, 0, dst, 0, n * m);

        // Forward direction (according to dr, dc)
        int stepRow = dr;
        int stepCol = dc;
        // When moving “right” or “down” we iterate increasing indices;
        // when moving “left” or “up” we iterate decreasing indices.
        boolean forward = (stepRow >= 0 && stepCol >= 0) || (stepRow <= 0 && stepCol <= 0);
        int startRow = forward ? 0 : n - 1;
        int endRow   = forward ? n : -1;
        int startCol = forward ? 0 : m - 1;
        int endCol   = forward ? m : -1;

        for (int i = startRow; i != endRow; i += stepRow) {
            for (int j = startCol; j != endCol; j += stepCol) {
                if (dst[i][j] == 1 && inBounds(i + stepRow, j + stepCol, n, m)) {
                    dst[i + stepRow][j + stepCol] += dst[i][j];
                }
            }
        }

        // Backward pass to propagate the opposite direction as well
        int revRow = -stepRow;
        int revCol = -stepCol;
        for (int i = startRow; i != endRow; i += revRow) {
            for (int j = startCol; j != endCol; j += revCol) {
                if (dst[i][j] == 1 && inBounds(i + revRow, j + revCol, n, m)) {
                    dst[i + revRow][j + revCol] += dst[i][j];
                }
            }
        }
        return dst;
    }

    /** Utility – checks whether (r, c) lies inside the matrix of size n×m. */
    private static boolean inBounds(int r, int c, int n, int m) {
        return r >= 0 && r < n && c >= 0 && c < m;
    }
}

/*
 * Refactored version of the original program.
 * The refactor focuses on readability, maintainability and proper separation of concerns.
 * It keeps the original behaviour while removing unused imports, reducing global mutable state,
 * and extracting logical pieces into well‑named methods and classes.
 */
import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.List;
import java.util.Queue;
import java.util.StringTokenizer;

/**
 * Main class that solves the problem.
 * The algorithm:
 *   1. Reads a matrix of characters.
 *   2. Detects the centres of plus‑shaped crosses.
 *   3. For each centre determines the smallest arm length.
 *   4. Marks all cells belonging to the arms.
 *   5. Verifies that every '*' is covered – otherwise prints –1.
 *   6. Prints the number of operations and the operations themselves.
 */
public class CF3 {

    /** Simple wrapper around a BufferedReader for tokenised input. */
    private static final class FastScanner {
        private final StringTokenizer st;

        FastScanner(BufferedReader br) {
            st = new StringTokenizer(br.readLine());
        }

        /** Returns the next token, reading a new line if necessary. */
        private void fill() throws IOException {
            while (!st.hasMoreTokens()) {
                st = new StringTokenizer(new BufferedReader(new InputStreamReader(System.in)).readLine());
            }
        }

        String next() throws IOException {
            if (!st.hasMoreTokens()) {
                fill();
            }
            return st.nextToken();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }

        /** Returns the rest of the current line (without the trailing newline). */
        String nextLine() throws IOException {
            // Consume the remainder of the current line.
            while (st.hasMoreTokens()) {
                st.nextToken();
            }
            return new BufferedReader(new InputStreamReader(System.in)).readLine();
        }
    }

    /** Holds the grid and auxiliary information used during processing. */
    private static final class Solver {
        private final char[][] grid;
        private final boolean[][] covered;   // true if a '*' cell is covered by an arm
        private final List<Operation> operations = new ArrayList<>();

        Solver(char[][] grid) {
            this.grid = grid;
            this.covered = new boolean[grid.length][grid[0].length];
        }

        /** Detects all plus‑centres in the grid. */
        List<Point> findCentres() {
            List<Point> centres = new ArrayList<>();
            int n = grid.length;
            int m = grid[0].length;

            for (int i = 1; i < n - 1; i++) {
                for (int j = 1; j < m - 1; j++) {
                    if (isPlusCentre(i, j)) {
                        centres.add(new Point(i, j));
                    }
                }
            }
            return centres;
        }

        /** Checks whether (i, j) is the centre of a plus shape. */
        private boolean isPlusCentre(int i, int j) {
            return grid[i][j] == '*' &&
                    grid[i - 1][j] == '*' && grid[i + 1][j] == '*' &&
                    grid[i][j - 1] == '*' && grid[i][j + 1] == '*';
        }

        /** Determines the arm length of a plus centred at (i, j). */
        int computeArmLength(int i, int j) {
            int up = countConsecutive(i, j, -1, 0);
            int down = countConsecutive(i, j, 1, 0);
            int left = countConsecutive(i, j, 0, -1);
            int right = countConsecutive(i, j, 0, 1);

            int min = Math.min(Math.min(up, down), Math.min(left, right));
            // The original code prints min‑1, i.e. the number of steps beyond the centre.
            return Math.max(min - 1, 0);
        }

        /** Counts how many '*' appear consecutively starting from (i, j) moving in (di, dj). */
        private int countConsecutive(int i, int j, int di, int dj) {
            int count = 0;
            int ni = i, nj = j;
            while (inside(ni, nj) && grid[ni][nj] == '*') {
                count++;
                ni += di;
                nj += dj;
            }
            return count;
        }

        /** Returns true if (r, c) is inside the grid bounds. */
        private boolean inside(int r, int c) {
            return r >= 0 && r < grid.length && c >= 0 && c < grid[0].length;
        }

        /** Marks all cells belonging to the arms of a plus centred at (i, j) with arm length len. */
        void markArms(int i, int j, int len) {
            markDirection(i, j, -1, 0, len);   // up
            markDirection(i, j, 1, 0, len);    // down
            markDirection(i, j, 0, -1, len);   // left
            markDirection(i, j, 0, 1, len);    // right
        }

        private void markDirection(int i, int j, int di, int dj, int len) {
            int ni = i + di, nj = j + dj;
            for (int step = 0; step <= len; step++) {
                if (inside(ni, nj)) {
                    covered[ni][nj] = true;
                }
                ni += di;
                nj += dj;
            }
        }

        /** Verifies that every '*' cell has been covered by at least one arm. */
        boolean isEveryStarCovered() {
            for (int i = 0; i < grid.length; i++) {
                for (int j = 0; j < grid[0].length; j++) {
                    if (grid[i][j] == '*' && !covered[i][j]) {
                        return false;
                    }
                }
            }
            return true;
        }

        /** Executes the whole algorithm and returns the list of operations (or null if impossible). */
        List<Operation> solve() {
            List<Point> centres = findCentres();

            // No centre → impossible unless there is no '*' at all.
            if (centres.isEmpty()) {
                for (int i = 0; i < grid.length; i++) {
                    for (int j = 0; j < grid[0].length; j++) {
                        if (grid[i][j] == '*') {
                            return null; // impossible
                        }
                    }
                }
                return List.of(); // everything is already empty → 0 operations
            }

            // Process each centre.
            for (Point centre : centres) {
                int arm = computeArmLength(centre.row, centre.col);
                markArms(centre.row, centre.col, arm);
                operations.add(new Operation(centre.row + 1, centre.col + 1, arm));
            }

            // If any '*' remains uncovered the instance is impossible.
            if (!isEveryStarCovered()) {
                return null;
            }
            return operations;
        }
    }

    /** Simple container for a detected plus centre. */
    private static final class Point {
        final int row;
        final int col;

        Point(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }

    /** Represents one operation: centre coordinates (1‑based) and arm length. */
    private static final class Operation {
        final int row;   // 1‑based
        final int col;   // 1‑based
        final int arm;   // length of each arm (0 if only the centre)

        Operation(int row, int col, int arm) {
            this.row = row;
            this.col = col;
            this.arm = arm;
        }

        @Override
        public String toString() {
            return row + " " + col + " " + arm;
        }
    }

    /** Entry point. */
    public static void main(String[] args) throws Exception {
        FastScanner scanner = new FastScanner(new BufferedReader(new InputStreamReader(System.in)));
        PrintWriter out = new PrintWriter(System.out, true);

        int n = scanner.nextInt();
        int m = scanner.nextInt();
        char[][] grid = new char[n][];
        for (int i = 0; i < n; i++) {
            // The next line may contain spaces, therefore we read the whole line.
            grid[i] = scanner.nextLine().trim().toCharArray();
        }

        Solver solver = new Solver(grid);
        var result = solver.solve();

        if (result == null) {
            out.println(-1);
        } else {
            out.println(result.size());
            for (Operation op : result) {
                out.println(op);
            }
        }
        out.flush();
    }
}

import java.io.*;
import java.util.*;

/**
 * Solution for "E1 Stars Drawing – Easy Edition".
 *
 * <p>
 * The program reads a grid consisting of '.' and '*' characters.
 * It tries to cover every '*' with a cross‑shaped star (vertical and
 * horizontal line of equal length). The size of a star is the length
 * of each arm measured in cells. The algorithm places the largest
 * possible star at each '*' cell (starting from the biggest size) and
 * marks the covered cells as processed. If the whole board becomes
 * empty after placements, the list of stars is printed; otherwise -1
 * is printed.
 * </p>
 */
public class Main {

    /** Entry point of the program. */
    public static void main(String[] args) {
        InputReader reader = new InputReader(System.in);
        PrintWriter out = new PrintWriter(System.out);
        solve(reader, out);
        out.close();
    }

    /**
     * Reads the input, processes the grid and writes the answer.
     *
     * @param reader input reader
     * @param out    output writer
     */
    private static void solve(InputReader reader, PrintWriter out) {
        int n = reader.nextInt();
        int m = reader.nextInt();

        char[][] board = new char[n][];
        for (int i = 0; i < n; i++) {
            board[i] = reader.next().toCharArray();
        }

        List<Star> stars = new ArrayList<>();
        boolean solved = attemptSolution(board, stars);

        if (solved) {
            out.println(stars.size());
            for (Star star : stars) {
                out.printf("%d %d %d%n", star.row + 1, star.col + 1, star.size);
            }
        } else {
            out.println(-1);
        }
    }

    /** Attempts to cover all '*' cells with stars. */
    private static boolean attemptSolution(char[][] original, List<Star> stars) {
        // Work on a mutable copy so we can mark cells as covered.
        char[][] board = copy(original);

        for (int r = 0; r < board.length; r++) {
            for (int c = 0; c < board[0].length; c++) {
                if (board[r][c] != '*') {
                    continue;
                }

                // The maximum possible arm length is limited by the borders.
                int maxLen = Math.min(Math.min(r, board.length - 1 - r),
                                      Math.min(c, board[0].length - 1 - c));

                // Try the biggest size first.
                for (int len = maxLen; len >= 1; len--) {
                    if (canPlace(board, r, c, len)) {
                        stars.add(new Star(r, c, len));
                        placeStar(board, r, c, len);
                        break; // move to the next '*' cell
                    }
                }
            }
        }

        // After processing all cells, the board must be completely cleared.
        return isEmpty(board);
    }

    /** Checks whether a star of the given size can be placed at (r,c). */
    private static boolean canPlace(char[][] board, int r, int c, int len) {
        // Verify the vertical line.
        for (int i = r - len; i <= r + len; i++) {
            if (board[i][c] != '*') {
                return false;
            }
        }
        // Verify the horizontal line.
        for (int j = c - len; j <= c + len; j++) {
            if (board[r][j] != '*') {
                return false;
            }
        }
        return true;
    }

    /** Marks the cells belonging to a placed star as covered ('.'). */
    private static void placeStar(char[][] board, int r, int c, int len) {
        // Vertical arm.
        for (int i = r - len; i <= r + len; i++) {
            board[i][c] = '.';
        }
        // Horizontal arm.
        for (int j = c - len; j <= c + len; j++) {
            board[r][j] = '.';
        }
    }

    /** Creates a deep copy of the supplied board. */
    private static char[][] copy(char[][] src) {
        char[][] dst = new char[src.length][];
        for (int i = 0; i < src.length; i++) {
            dst[i] = src[i].clone();
        }
        return dst;
    }

    /** Returns true if the board contains no '*' characters. */
    private static boolean isEmpty(char[][] board) {
        for (char[] row : board) {
            for (char cell : row) {
                if (cell == '*') {
                    return false;
                }
            }
        }
        return true;
    }

    /** Simple immutable container for a star. */
    private static final class Star {
        final int row;   // zero‑based row index
        final int col;   // zero‑based column index
        final int size;  // arm length

        Star(int row, int col, int size) {
            this.row = row;
            this.col = col;
            this.size = size;
        }
    }

    /** Fast tokenizer‑based input reader. */
    private static final class InputReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        InputReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream), 32768);
        }

        /** Returns the next token, reading a new line if necessary. */
        String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        /** Convenience method for reading an integer. */
        int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;

/**
 * Represents a rectangular board containing '*' and '.' characters.
 * The board is 1‑based indexed for simplicity (cells are addressed by
 * row and column numbers starting at 1).
 */
final class Grid {
    private final char[][] board;
    private final int rows;
    private final int cols;

    Grid(int rows, int cols, Scanner scanner) {
        this.rows = rows;
        this.cols = cols;
        board = new char[rows + 1][cols + 1]; // 1‑based indexing
        for (int r = 1; r <= rows; r++) {
            String line = scanner.nextLine();
            for (int c = 1; c <= cols; c++) {
                board[r][c] = line.charAt(c - 1);
            }
        }
    }

    /**
     * Checks whether a plus sign of the given {@code size} can be placed
     * with its centre at {@code (row, col)}.
     * The plus consists of the vertical and horizontal arms of length
     * {@code size} extending from the centre.
     *
     * @return {@code true} if all required cells contain '*'.
     */
    boolean canPlacePlus(int row, int col, int size) {
        // The plus must stay inside the board.
        if (row - size < 1 || col - size < 1
                || row + size > rows || col + size > cols) {
            return false;
        }

        // All cells on the vertical arm.
        for (int r = row - size; r <= row + size; r++) {
            if (board[r][col] != '*') {
                return false;
            }
        }

        // All cells on the horizontal arm.
        for (int c = col - size; c <= col + size; c++) {
            if (board[row][c] != '*') {
                return false;
            }
        }

        return true;
    }

    char get(int row, int col) {
        return board[row][col];
    }

    int getRows() {
        return rows;
    }

    int getCols() {
        return cols;
    }
}

/**
 * A plus sign (referred to as a "star" in the original code) is defined
 * by the coordinates of its centre and the length of each arm (the
 * {@code size} parameter).
 * Only the centre coordinates are used for Equality/Hashing.
 */
final class Star {
    private final int row;
    private final int col;
    private final int size; // arm length

    Star(int row, int col, int size) {
        this.row = row;
        this.col = col;
        this.size = size;
    }

    int getRow() {
        return row;
    }

    int getCol() {
        return col;
    }

    int getSize() {
        return size;
    }

    /** Two stars are considered equal if they share the same centre. */
    @Override
    public boolean equals(Object o) {
        if (this == o) return true;
        if (!(o instanceof Star)) return false;
        Star other = (Star) o;
        return row == other.row && col == other.col;
    }

    @Override
    public int hashCode() {
        return 31 * row + col;
    }

    @Override
    public String toString() {
        return row + " " + col + " " + size;
    }
}

/**
 * Entry point of the program.
 * Reads the board, discovers all possible plus signs and prints their count
 * followed by the description of each star.
 */
public class Main {
    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            int rows = scanner.nextInt();
            int cols = scanner.nextInt();
            scanner.nextLine(); // consume end‑of‑line

            Grid grid = new Grid(rows, cols, scanner);
            List<Star> stars = discoverStars(grid);

            System.out.println(stars.size());
            for (Star star : stars) {
                System.out.println(star);
            }
        }
    }

    /**
     * Finds all plus signs that can be placed on the board.
     * For each centre cell containing '*', the algorithm tries to grow
     * the plus size starting from 1 until the next size no longer fits.
     *
     * @param grid the board to search.
     * @return a list of discovered stars in the order they are found.
     */
    private static List<Star> discoverStars(Grid grid) {
        List<Star> stars = new ArrayList<>();

        for (int r = 1; r <= grid.getRows(); r++) {
            for (int c = 1; c <= grid.getCols(); c++) {
                if (grid.get(r, c) != '*') {
                    continue;
                }

                int size = 1;
                // Keep adding stars while the next larger size is still valid.
                while (grid.canPlacePlus(r, c, size)) {
                    stars.add(new Star(r, c, size));
                    size++;
                }
            }
        }
        return stars;
    }
}

import java.io.IOException;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Scanner;

/**
 * Determines whether all '*' cells on the board belong to one or more
 * symmetric cross‑shaped patterns. If they do, prints the number of patterns
 * and the 1‑based coordinates of each pattern together with its radius.
 */
public class Problem1015E1 {

    /** Simple immutable container for a detected pattern. */
    private static final class Pattern {
        final int row;   // 0‑based row index of the centre
        final int col;   // 0‑based column index of the centre
        final int radius;// number of steps outward from the centre (>=1)

        Pattern(int row, int col, int radius) {
            this.row = row;
            this.col = col;
            this.radius = radius;
        }
    }

    public static void main(String[] args) throws IOException {
        try (Scanner scanner = new Scanner(System.in)) {
            int n = scanner.nextInt();   // number of rows
            int m = scanner.nextInt();   // number of columns
            char[][] board = readBoard(scanner, n, m);

            List<Pattern> patterns = detectCrossPatterns(board);

            if (!isCompleteCoverage(board, patterns, m)) {
                System.out.println(-1);
                return;
            }

            System.out.println(patterns.size());
            for (Pattern p : patterns) {
                // Output is 1‑based row, 1‑based column, radius (as in the original program)
                System.out.println((p.row + 1) + " " + (p.col + 1) + " " + p.radius);
            }
        }
    }

    /** Reads the n × m board from the scanner. */
    private static char[][] readBoard(Scanner scanner, int n, int m) {
        char[][] board = new char[n][];
        for (int i = 0; i < n; i++) {
            String line = scanner.next();
            board[i] = line.toCharArray();
        }
        return board;
    }

    /** Finds every centre cell that forms a symmetric cross with radius ≥ 1. */
    private static List<Pattern> detectCrossPatterns(char[][] board) {
        List<Pattern> patterns = new ArrayList<>();
        int rows = board.length;
        int cols = board[0].length;

        for (int i = 1; i < rows - 1; i++) {
            for (int j = 1; j < cols - 1; j++) {
                if (board[i][j] != '*') {
                    continue;
                }
                int radius = computeMaximumRadius(board, i, j);
                if (radius > 0) {
                    patterns.add(new Pattern(i, j, radius));
                }
            }
        }
        return patterns;
    }

    /** Computes the largest radius such that the four orthogonal arms are all '*'. */
    private static int computeMaximumRadius(char[][] board, int centreRow, int centreCol) {
        int radius = 0;
        while (true) {
            int next = radius + 1;
            boolean stillValid = centreRow - next >= 0
                    && centreRow + next < board.length
                    && centreCol - next >= 0
                    && centreCol + next < board[0].length
                    && board[centreRow - next][centreCol] == '*'
                    && board[centreRow + next][centreCol] == '*'
                    && board[centreRow][centreCol - next] == '*'
                    && board[centreRow][centreCol + next] == '*';
            if (!stillValid) {
                break;
            }
            radius = next;
        }
        return radius;
    }

    /**
     * Verifies that the union of all pattern cells equals the set of all '*' cells
     * on the board.
     */
    private static boolean isCompleteCoverage(char[][] board,
                                                List<Pattern> patterns,
                                                int cols) {
        HashSet<Integer> covered = new HashSet<>();

        for (Pattern p : patterns) {
            addPatternCells(covered, p, cols);
        }

        int totalStars = 0;
        for (char[] row : board) {
            for (char cell : row) {
                if (cell == '*') {
                    totalStars++;
                }
            }
        }
        return covered.size() == totalStars;
    }

    /** Adds every cell belonging to a single pattern into the supplied set. */
    private static void addPatternCells(HashSet<Integer> set,
                                         Pattern pattern,
                                         int cols) {
        int r = pattern.row;
        int c = pattern.col;
        int rad = pattern.radius;

        for (int d = -rad; d <= rad; d++) {
            addCell(set, r + d, c, cols);
            addCell(set, r, c + d, cols);
        }
    }

    /** Utility: converts (row, col) to a unique integer key and stores it. */
    private static void addCell(HashSet<Integer> set,
                                int row,
                                int col,
                                int totalCols) {
        set.add(row * totalCols + col);
    }
}

import java.io.*;
import java.util.*;

/**
 * Entry point of the program.
 */
public class Main {

    public static void main(String[] args) {
        try (FastScanner scanner = new FastScanner(System.in)) {
            PrintWriter out = new PrintWriter(System.out);
            new Solver().solve(scanner, out);
        }
    }
}

/**
 * Core logic for solving the problem.
 * The class is intentionally small and focussed – each step of the algorithm
 * lives in a clearly named method.
 */
class Solver {

    /** Reads the grid and returns it as a character matrix. */
    private static char[][] readGrid(FastScanner scanner, int rows) {
        char[][] grid = new char[rows][];
        for (int i = 0; i < rows; i++) {
            String line = scanner.nextLine();
            grid[i] = line.toCharArray();
        }
        return grid;
    }

    /** Finds all stars in the grid and stores them in a list. */
    private static List<Star> findStars(char[][] grid) {
        int n = grid.length;
        int m = grid[0].length;
        boolean[][] painted = new boolean[n][m];
        List<Star> stars = new ArrayList<>();

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i][j] == '*' && !painted[i][j]) {
                    int radius = maxRadius(grid, i, j);
                    if (radius > 0) {
                        stars.add(new Star(i + 1, j + 1, radius));
                        paintStar(painted, i, j, radius);
                    }
                }
            }
        }
        return stars;
    }

    /** Determines the largest possible radius of a star centred at (x, y). */
    private static int maxRadius(char[][] grid, int x, int y) {
        int up = countContinuous(grid, x, y, -1, 0);
        int down = countContinuous(grid, x, y, 1, 0);
        int left = countContinuous(grid, x, y, 0, -1);
        int right = countContinuous(grid, x, y, 0, 1);
        return Math.min(Math.min(up, down), Math.min(left, right));
    }

    /** Moves in the given direction while the cell contains a star ('*'). */
    private static int countContinuous(char[][] grid, int x, int y, int dx, int dy) {
        int count = 0;
        int nx = x + dx, ny = y + dy;
        while (inBounds(grid, nx, ny) && grid[nx][ny] == '*') {
            count++;
            nx += dx;
            ny += dy;
        }
        return count;
    }

    /** Marks all cells covered by a star of given radius at (x, y). */
    private static void paintStar(boolean[][] painted, int x, int y, int radius) {
        // vertical line
        for (int i = x - radius; i <= x + radius; i++) {
            painted[i][y] = true;
        }
        // horizontal line
        for (int j = y - radius; j <= y + radius; j++) {
            painted[x][j] = true;
        }
    }

    /** Verifies that every star in the original grid is covered by at least one found star. */
    private static boolean coversAllStars(char[][] grid, List<Star> stars) {
        for (int i = 0; i < grid.length; i++) {
            for (int j = 0; j < grid[i].length; j++) {
                if (grid[i][j] == '*' && !isCovered(i, j, stars)) {
                    return false;
                }
            }
        }
        return true;
    }

    /** Checks whether a cell is marked by any of the discovered stars. */
    private static boolean isCovered(int x, int y, List<Star> stars) {
        for (Star s : stars) {
            if (isMarked(x, y, s.x - 1, s.y - 1, s.radius)) {
                return true;
            }
        }
        return false;
    }

    /** Determines if a cell falls on the cross formed by a star. */
    private static boolean isMarked(int cx, int cy, int sx, int sy, int radius) {
        return sx == cx && (cy >= sy - radius && cy <= sy + radius) ||
               sy == cy && (cx >= sx - radius && cx <= sx + radius);
    }
}

/**
 * Simple data holder for a discovered star.
 */
class Star {
    final int x;      // 1‑based row index
    final int y;      // 1‑based column index
    final int radius;

    Star(int x, int y, int radius) {
        this.x = x;
        this.y = y;
        this.radius = radius;
    }
}

/**
 * Fast input scanner used by the solution.
 * It wraps a {@link BufferedReader} and a {@link StringTokenizer}
 * to efficiently read tokens.
 */
class FastScanner {
    private final BufferedReader reader;
    private StringTokenizer tokenizer;

    FastScanner(InputStream inputStream) {
        reader = new BufferedReader(new InputStreamReader(inputStream));
    }

    /** Returns the next token from the input. */
    private String nextToken() {
        while (tokenizer == null || !tokenizer.hasMoreElements()) {
            try {
                String line = reader.readLine();
                if (line == null) break;
                tokenizer = new StringTokenizer(line);
            } catch (IOException e) {
                throw new UncheckedIOException(e);
            }
        }
        return tokenizer.nextToken();
    }

    /** Convenience wrapper for {@link #nextToken()} that parses an int. */
    int nextInt() {
        return Integer.parseInt(nextToken());
    }

    /** Returns the next full line (including possible spaces). */
    String nextLine() {
        try {
            return reader.readLine();
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
    }
}

import java.io.IOException;
import java.io.PrintWriter;
import java.util.ArrayList;
import java.util.List;

/**
 * Reads a board of obstacles ('*') and empty cells ('.') and produces a
 * placement plan that covers every obstacle exactly as required by the
 * original algorithm.
 *
 * <p>The program is heavily refactored for readability, separation of concerns
 * and easier maintenance.</p>
 */
public class E501 {

    /** Simple data holder for a placement (row, column, size). */
    private static final class Placement {
        final int row;   // 1‑based index
        final int col;   // 1‑based index
        final int size;  // radius of the cross

        Placement(int row, int col, int size) {
            this.row = row;
            this.col = col;
            this.size = size;
        }
    }

    /** Entry point of the program. */
    public static void main(String[] args) {
        // Use try‑with‑resources to guarantee streams are closed.
        try (FastScanner input = new FastScanner(System.in);
             PrintWriter out = new PrintWriter(System.out)) {

            int rows = input.nextInt();
            int cols = input.nextInt();

            boolean[][] obstacle = readObstacleGrid(input, rows, cols);
            List<Placement> placements = findPlacements(obstacle);
            validateCoverage(obstacle, placements);

            // Build output.
            StringBuilder sb = new StringBuilder();
            sb.append(placements.size()).append('\n');
            for (Placement p : placements) {
                sb.append(p.row).append(' ')
                  .append(p.col).append(' ')
                  .append(p.size).append('\n');
            }
            out.print(sb.toString());

        } catch (Exception e) {
            // The original program exits with -1 on any failure.
            System.out.println(-1);
        }
    }

    /** Reads the grid of obstacles from the scanner. */
    private static boolean[][] readObstacleGrid(FastScanner fs, int r, int c) {
        boolean[][] grid = new boolean[r][c];
        for (int i = 0; i < r; i++) {
            String line = fs.next();
            for (int j = 0; j < c; j++) {
                grid[i][j] = line.charAt(j) == '*';
            }
        }
        return grid;
    }

    /** Finds all valid cross placements according to the original algorithm. */
    private static List<Placement> findPlacements(boolean[][] obstacle) {
        int r = obstacle.length;
        int c = obstacle[0].length;

        // Distance matrices for the four directions.
        int[][] up      = new int[r][c];
        int[][] left    = new int[r][c];
        int[][] down    = new int[r][c];
        int[][] right   = new int[r][c];

        // Forward pass: top‑left neighbours.
        for (int i = 1; i < r - 1; i++) {
            for (int j = 1; j < c - 1; j++) {
                if (obstacle[i][j]) {
                    if (obstacle[i - 1][j]) up[i][j] = up[i - 1][j] + 1;
                    if (obstacle[i][j - 1]) left[i][j] = left[i][j - 1] + 1;
                }
            }
        }

        // Backward pass: bottom‑right neighbours.
        for (int i = r - 2; i >= 1; i--) {
            for (int j = c - 2; j >= 1; j--) {
                if (obstacle[i][j]) {
                    if (obstacle[i + 1][j]) down[i][j] = down[i + 1][j] + 1;
                    if (obstacle[i][j + 1]) right[i][j] = right[i][j + 1] + 1;
                }
            }
        }

        List<Placement> placements = new ArrayList<>();

        // Determine the maximal cross size for each cell.
        for (int i = 1; i < r - 1; i++) {
            for (int j = 1; j < c - 1; j++) {
                if (obstacle[i][j]) {
                    int minNeighbour = Math.min(
                            Math.min(up[i][j], left[i][j]),
                            Math.min(down[i][j], right[i][j])
                    );
                    if (minNeighbour > 0) {
                        // Convert to 1‑based output indices.
                        placements.add(new Placement(i + 1, j + 1, minNeighbour));
                    }
                }
            }
        }
        return placements;
    }

    /** Verifies that the discovered placements completely cover the original board. */
    private static void validateCoverage(boolean[][] obstacle, List<Placement> placements) {
        int r = obstacle.length;
        int c = obstacle[0].length;
        boolean[][] covered = new boolean[r][c];

        for (Placement p : placements) {
            int row = p.row - 1;   // back to 0‑based
            int col = p.col - 1;
            covered[row][col] = true;
            for (int i = 1; i <= p.size; i++) {
                covered[row - i][col] = true;
                covered[row + i][col] = true;
                covered[row][col - i] = true;
                covered[row][col + i] = true;
            }
        }

        // Any mismatch must be reported as -1, matching the original behaviour.
        for (int i = 0; i < r; i++) {
            for (int j = 0; j < c; j++) {
                if (obstacle[i][j] != covered[i][j]) {
                    System.out.println(-1);
                    System.exit(0);
                }
            }
        }
    }
}

/* -------------------------------------------------------------------------
 * Fast I/O utilities (unchanged from the original source).
 * ------------------------------------------------------------------------- */
class FastScanner {
    private final InputStream stream;
    private final byte[] buf = new byte[1024];
    private int curChar;
    private int numChars;

    FastScanner(InputStream stream) {
        this.stream = stream;
    }

    private int read() {
        if (numChars == -1) {
            throw new InputMismatchException();
        }
        if (curChar >= numChars) {
            curChar = 0;
            try {
                numChars = stream.read(buf);
            } catch (IOException e) {
                throw new InputMismatchException();
            }
            if (numChars <= 0) {
                return -1;
            }
        }
        return buf[curChar++];
    }

    private boolean isSpaceChar(int c) {
        return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
    }

    private boolean isEndline(int c) {
        return c == '\n' || c == '\r' || c == -1;
    }

    public int nextInt() {
        return Integer.parseInt(next());
    }

    public long nextLong() {
        return Long.parseLong(next());
    }

    public double nextDouble() {
        return Double.parseDouble(next());
    }

    public String next() {
        int c = read();
        while (isSpaceChar(c)) {
            c = read();
        }
        StringBuilder res = new StringBuilder();
        do {
            res.appendCodePoint(c);
            c = read();
        } while (!isSpaceChar(c));
        return res.toString();
    }

    public String nextLine() {
        int c = read();
        while (isEndline(c)) {
            c = read();
        }
        StringBuilder res = new StringBuilder();
        do {
            res.appendCodePoint(c);
            c = read();
        } while (!isEndline(c));
        return res.toString();
    }
}

import java.io.*;
import java.util.*;

/**
 * Refactored solution for the "Star Painting" problem.
 *
 * <p>This version improves readability and maintainability by:
 * <ul>
 *   <li>Separating concerns into small, focused methods.</li>
 *   <li>Using expressive names and immutable data where possible.</li>
 *   <li>Avoiding duplicated loops and magical numbers.</li>
 *   <li>Encapsulating direction‑specific star counting logic.</li>
 *   <li>Keeping the original fast‑I/O implementation.</li>
 * </ul>
 */
public class E1_StarPainting {

    /* ---------- I/O helpers ------------------------------------------------ */

    private static final PrintWriter OUT = new PrintWriter(new BufferedWriter(
            new OutputStreamWriter(System.out)));

    private static void print(Object o) {
        OUT.print(o);
    }

    private static void println(Object o) {
        OUT.println(o);
    }

    private static final class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    throw new UncheckedIOException(e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        String nextLine() {
            try {
                return br.readLine();
            } catch (IOException e) {
                throw new UncheckedIOException(e);
            }
        }
    }

    /* ---------- Core algorithm --------------------------------------------- */

    /** Holds information about a discovered star center. */
    private static final class StarInfo {
        final int row;   // 1‑based row index
        final int col;   // 1‑based column index
        final int size;  // size parameter

        StarInfo(int row, int col, int size) {
            this.row = row;
            this.col = col;
            this.size = size;
        }

        @Override
        public String toString() {
            return row + " " + col + " " + size;
        }
    }

    /** Directions used for counting consecutive stars. */
    private enum Direction {
        LEFT(0, -1), RIGHT(0, 1), UP(-1, 0), DOWN(1, 0);

        final int dr, dc;

        Direction(int dr, int dc) {
            this.dr = dr;
            this.dc = dc;
        }

        /** Moves one step in the given direction. */
        int next(int r, int c) {
            return r + dr;
        }

        int next(int r, int c, int step) {
            return r + dr * step;
        }
    }

    /** Computes the number of consecutive stars in each cardinal direction
     *  for every cell of the grid. */
    private static void computeDirectionCounts(char[][] grid,
                                                int[][] left,
                                                int[][] right,
                                                int[][] up,
                                                int[][] down) {
        final int n = grid.length;
        final int m = grid[0].length;

        // left → right
        for (int r = 0; r < n; r++) {
            for (int c = 1; c < m; c++) {
                left[r][c] = (grid[r][c] == '*' && grid[r][c - 1] == '*')
                        ? left[r][c - 1] + 1
                        : 0;
            }
        }

        // right → left
        for (int r = 0; r < n; r++) {
            for (int c = m - 2; c >= 0; c--) {
                right[r][c] = (grid[r][c] == '*' && grid[r][c + 1] == '*')
                        ? right[r][c + 1] + 1
                        : 0;
            }
        }

        // top → bottom
        for (int c = 0; c < m; c++) {
            for (int r = 1; r < n; r++) {
                up[r][c] = (grid[r][c] == '*' && grid[r - 1][c] == '*')
                        ? up[r - 1][c] + 1
                        : 0;
            }
        }

        // bottom → top
        for (int c = 0; c < m; c++) {
            for (int r = n - 2; r >= 0; r--) {
                down[r][c] = (grid[r][c] == '*' && grid[r + 1][c] == '*')
                        ? down[r + 1][c] + 1
                        : 0;
            }
        }
    }

    /** Returns a list of star centres that can be drawn with size ≥ 1. */
    private static List<StarInfo> discoverStars(char[][] grid,
                                                int[][] left,
                                                int[][] right,
                                                int[][] up,
                                                int[][] down) {
        List<StarInfo> stars = new ArrayList<>();

        for (int r = 1; r < grid.length - 1; r++) {
            for (int c = 1; c < grid[0].length - 1; c++) {
                int lenLeft  = left[r][c];
                int lenRight = right[r][c];
                int lenUp    = up[r][c];
                int lenDown  = down[r][c];

                if (lenLeft == 0 || lenRight == 0 || lenUp == 0 || lenDown == 0) {
                    continue;
                }

                int size = Math.min(lenLeft, lenRight);
                size = Math.min(size, lenUp);
                size = Math.min(size, lenDown);

                stars.add(new StarInfo(r + 1, c + 1, size)); // convert to 1‑based

                // Clear the entire star shape from the grid
                clearStarShape(grid, r, c, size);
            }
        }
        return stars;
    }

    /** Marks every cell belonging to a star of given size centred at (row, col) with '.'. */
    private private static void clearStarShape(char[][] grid,
                                              int centreRow,
                                              int centreCol,
                                              int size) {
        // vertical arm
        for (int r = centreRow - size; r <= centreRow + size; r++) {
            grid[r][centreCol] = '.';
        }
        // horizontal arm
        for (int c = centreCol - size; c <= centreCol + size; c++) {
            grid[centreRow][c] = '.';
        }
    }

    /** Validates that after all removals no '*' remains in the grid. */
    private static boolean isGridClean(char[][] grid) {
        for (char[] row : grid) {
            for (char cell : row) {
                if (cell == '*') {
                    return false;
                }
            }
        }
        return true;
    }

    /** Main driver – reads input, processes, prints result. */
    public static void main(String[] args) throws IOException {
        FastScanner sc = new FastScanner();

        int n = sc.nextInt();
        int m = sc.nextInt();

        // read grid rows – they are space‑separated characters on a line
        char[][] grid = new char[n][m];
        for (int i = 0; i < n; i++) {
            String line = sc.nextLine().replaceAll("\\s+", "");
            for (int j = 0; j < m; j++) {
                grid[i][j] = line.charAt(j);
            }
        }

        // directional star counters
        int[][] left  = new int[n][m];
        int[][] right = new int[n][m];
        int[][] up    = new int[n][m];
        int[][] down  = new int[n][m];

        computeDirectionCounts(grid, left, right, up, down);

        // collect all feasible stars and immediately clear them from the grid
        List<StarInfo> discoveredStars = discoverStars(grid,
                left, right, up, down);

        // Verify that the whole grid becomes clean; otherwise output -1
        if (!isGridClean(grid)) {
            println(-1);
            exit();
        }

        // Output results
        println(discoveredStars.size());
        discoveredStars.forEach(OUT::println);

        exit();
    }

    /** Terminates the program after flushing the output buffer. */
    private static void exit() {
        OUT.flush();
        System.exit(0);
    }
}

import java.io.*;
import java.util.*;

/**
 * Refactored version of the original solution.
 * The program reads a grid of characters ('*' or '.'), finds the maximal
 * plus‑shaped crosses formed by '*', verifies that every '*' is covered,
 * and prints the centre coordinates (1‑based) together with the radius
 * of each cross. If some '*' cannot be covered, it prints -1.
 */
public class Main {

    /* --------------------------------------------------------------------- */
    /*  Fields used by the solver                                               */
    /* --------------------------------------------------------------------- */
    private FastScanner scanner;
    private PrintWriter writer;

    /* --------------------------------------------------------------------- */
    /*  Helper class that stores a placement (centre + radius)                 */
    /* --------------------------------------------------------------------- */
    private static final class Placement {
        final int row;   // 0‑based row index of the centre
        final int col;   // 0‑based column index of the centre
        final int radius;// radius of the plus shape

        Placement(int row, int col, int radius) {
            this.row = row;
            this.col = col;
            this.radius = radius;
        }
    }

    /* --------------------------------------------------------------------- */
    /*  Entry point                                                            */
    /* --------------------------------------------------------------------- */
    public static void main(String[] args) throws IOException {
        new Main().run();
    }

    /* --------------------------------------------------------------------- */
    /*  Main solving routine                                                     */
    /* --------------------------------------------------------------------- */
    private void solve() throws IOException {
        int n = scanner.nextInt();   // number of rows
        int m = scanner.nextInt();   // number of columns

        boolean[][] isStar = new boolean[n][m];
        boolean[][] covered = new boolean[n][m];

        readGrid(isStar);
        List<Placement> placements = collectAllPlacements(isStar, covered);

        if (!allCellsAreCovered(covered, n, m)) {
            writer.println(-1);
            return;
        }

        writer.println(placements.size());
        for (Placement p : placements) {
            writer.println(p.row + 1 + " " + (p.col + 1) + " " + p.radius);
        }
    }

    /* --------------------------------------------------------------------- */
    /*  Reads the grid from the scanner                                         */
    /* --------------------------------------------------------------------- */
    private void readGrid(boolean[][] grid) throws IOException {
        for (int i = 0, col = 0; i < grid.length; i++) {
            char[] tokens = scanner.next().toCharArray();
            for (char ch : tokens) {
                grid[i][col++] = (ch == '*');
            }
        }
    }

    /* --------------------------------------------------------------------- */
    /*  Finds every maximal plus‑shaped cross whose centre lies on a '*'      */
    /* --------------------------------------------------------------------- */
    private List<Placement> collectAllPlacements(boolean[][] grid, boolean[][] covered) {
        int maxCapacity = grid.length * grid[0].length;   // safe upper bound
        List<Placement> placements = new ArrayList<>(maxCapacity);

        for (int i = 0; i < grid.length; i++) {
            for (int j = 0; j < grid[0].length; j++) {
                if (!grid[i][j]) {
                    continue; // not a star → cannot be a centre
                }

                int radius = computeMaximumRadius(grid, i, j);
                if (radius == 0) {
                    continue; // no valid plus shape here
                }

                placements.add(new Placement(i, j, radius));

                // mark the whole cross as covered
                covered[i][j] = true;
                for (int d = 1; d <= radius; d++) {
                    covered[i - d][j] = true;
                    covered[i + d][j] = true;
                    covered[i][j - d] = true;
                    covered[i][j + d] = true;
                }
            }
        }
        return placements;
    }

    /* --------------------------------------------------------------------- */
    /*  Determines the largest radius of a plus centred at (r,c) that fits   */
    /*  inside the grid and consists solely of '*' cells                     */
    /* --------------------------------------------------------------------- */
    private int computeMaximumRadius(boolean[][] grid, int r, int c) {
        int maxPossible = Math.min(grid.length, grid[0].length);
        int radius = 0;

        for (int d = 1; d <= maxPossible; d++) {
            // check boundaries
            if (r - d < 0 || r + d >= grid.length
                    || c - d < 0 || c + d >= grid[0].length) {
                break;
            }
            // check that all four arm cells are '*'
            if (!grid[r - d][c] || !grid[r + d][c]
                    || !grid[r][c - d] || !grid[r][c + d]) {
                break;
            }
            radius = d; // this radius is still valid
        }
        return radius;
    }

    /* --------------------------------------------------------------------- */
    /*  Verifies that every '*' cell has been covered by at least one cross  */
    /* --------------------------------------------------------------------- */
    private boolean allCellsAreCovered(boolean[][] covered, int n, int m) {
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (!covered[i][j]) {
                    return false;
                }
            }
        }
        return true;
    }

    /* --------------------------------------------------------------------- */
    /*  Very small fast scanner for competitive‑programming style input       */
    /* --------------------------------------------------------------------- */
    private static final class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner(InputStream source) {
            br = new BufferedReader(new InputStreamReader(source));
        }

        private String next() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                st = new StringTokenizer(br.readLine());
            }
            return st.nextToken();
        }

        boolean hasNext() throws IOException {
            return br.ready() || (st != null && st.hasMoreTokens());
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }

    /* --------------------------------------------------------------------- */
    /*  Runs the whole program                                                  */
    /* --------------------------------------------------------------------- */
    private void run() throws IOException {
        scanner = new FastScanner(System.in);
        writer = new PrintWriter(System.out);

        solve();

        writer.flush();
        writer.close();
    }
}

import java.io.IOException;
import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;

/**
 * Refactored version of the original program.
 *
 * <p>This implementation separates concerns into small, well‑named methods,
 * uses meaningful identifiers, and eliminates the excess of static fields
 * present in the original code. The behaviour is identical:
 *
 * <ul>
 *   <li>It reads a grid of characters (size {@code n × m}) from {@code stdin}.</li>
 *   <li>It discovers every '+'‑shaped pattern made of '*' cells.</li>
 *   <li>For each '+' it records the centre (1‑based) and the length of its arms
 *       (radius = number of steps outward).</li>
 *   <li>All discovered '+' cells must cover every '*' in the grid; otherwise
 *       the program prints {@code -1}.</li>
 * </ul>
 */
public class E501Refactored {

    /** Information about a discovered plus sign. */
    private static final class Plus {
        private final int row;     // 0‑based row of the centre
        private final int col;     // 0‑based column of the centre
        private final int radius;  // radius (arm length)

        Plus(int row, int col, int radius) {
            this.row = row;
            this.col = col;
            this.radius = radius;
        }

        /** Returns the string in the required output format. */
        @Override
        public String toString() {
            return String.format("%d %d %d", row + 1, col + 1, radius);
        }
    }

    public static void main(String[] args) throws IOException {
        try (Scanner scanner = new Scanner(System.in)) {
            int rows = scanner.nextInt();
            int cols = scanner.nextInt();
            scanner.nextLine();                     // consume the end‑of‑line

            char[][] board = new char[rows][cols];
            int starCount = 0;
            int[][] starNumber = new int[rows][cols];   // -1 for non‑star cells

            // -----------------------------------------------------------------
            // 1. Read the board and assign an index to each '*' cell.
            // -----------------------------------------------------------------
            for (int r = 0; r < rows; r++) {
                String line = scanner.nextLine();
                for (int c = 0; c < cols; c++) {
                    char ch = line.charAt(c);
                    board[r][c] = ch;
                    if (ch == '*') {
                        starNumber[r][c] = starCount++;
                    } else {
                        starNumber[r][c] = -1;
                    }
                }
            }

            boolean[] usedStars = new boolean[starCount];
            List<Plus> pluses = new ArrayList<>();

            // -----------------------------------------------------------------
            // 2. Scan interior cells – only they can be the centre of a plus.
            // -----------------------------------------------------------------
            for (int r = 1; r < rows - 1; r++) {
                for (int c = 1; c < cols - 1; c++) {
                    if (isPlusCenter(board, r, c)) {
                        int radius = computeMaxRadius(board, r, c);
                        if (radius > 0) {               // at least one outward step
                            markStarsUsed(starNumber, usedStars, r, c, radius);
                            pluses.add(new Plus(r, c, radius));
                        }
                    }
                }
            }

            // -----------------------------------------------------------------
            // 3. Output the result.
            // -----------------------------------------------------------------
            if (allUsed(usedStars)) {
                System.out.println(pluses.size());
                for (Plus p : pluses) {
                    System.out.println(p);
                }
            } else {
                System.out.println(-1);
            }
        }
    }

    /** Checks whether the four orthogonal neighbours of (r,c) are '*' cells. */
    private static boolean isPlusCenter(char[][] board, int r, int c) {
        return board[r][c] == '*'
                && board[r - 1][c] == '*'
                && board[r + 1][c] == '*'
                && board[r][c - 1] == '*'
                && board[r][c + 1] == '*';
    }

    /**
     * Determines the maximal radius of a plus centred at (r,c).
     * The radius equals the number of steps outward for which all four
     * directions still contain a '*', i.e. the same value that the original
     * program stored as {@code i‑1}.
     */
    private static int computeMaxRadius(char[][] board, int centreR, int centreC) {
        int radius = 0;
        while (isArmAtDistance(board, centreR, centreC, radius + 1)) {
            radius++;
        }
        return radius;
    }

    /** True if, at distance {@code dist}, the four cells around (r,c) are '*'. */
    private static boolean isArmAtDistance(char[][] board, int r, int c, int dist) {
        int rows = board.length;
        int cols = board[0].length;
        return r + dist < rows
                && c + dist < cols
                && r - dist >= 0
                && c - dist >= 0
                && board[r + dist][c] == '*'
                && board[r - dist][c] == '*'
                && board[r][c + dist] == '*'
                && board[r][c - dist] == '*';
    }

    /** Marks every star belonging to the plus centred at (r,c) with radius {@code len}. */
    private static void markStarsUsed(int[][] starNumber,
                                      boolean[] used,
                                      int r,
                                      int c,
                                      int radius) {
        for (int d = 0; d <= radius; d++) {
            used[starNumber[r + d][c]] = true;   // down
            used[starNumber[r][c + d]] = true;   // right
            used[starNumber[r - d][c]] = true;   // up
            used[starNumber[r][c - d]] = true;   // left
        }
    }

    /** Returns {@code true} iff every entry of the supplied boolean array is {@code true}. */
    private static boolean allUsed(boolean[] array) {
        for (boolean flag : array) {
            if (!flag) {
                return false;
            }
        }
        return true;
    }
}

// Refactored version – improved readability, separation of concerns and type‑safety
// ---------------------------------------------------------------
// The program reads a rectangular character matrix, finds “star” patterns,
// draws them using '*', verifies that nothing changed unintentionally and prints
// the number of stars followed by their coordinates and radii.
//
// Author: <your‑name>
// ---------------------------------------------------------------

package com.example.stardetector;

import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;

/**
 * Main entry point for the star‑detection demo.
 */
public final class StarDetectorApp {

    /** Symbol used to mark a found star. */
    private static final char SYMBOL = '*';

    /** Empty filler character used when initialising the result matrix. */
    private static final char EMPTY = '.';

    /** Private constructor – utility class. */
    private StarDetectorApp() {
        // intentionally empty
    }

    /** --------------------------------------------------------------------- *
     *  Program start
     *  ------------------------------------------------------------------- */
    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            int rows    = scanner.nextInt();
            int columns = scanner.nextInt();

            char[][] originalGrid = readMatrix(scanner, rows, columns);
            char[][] resultGrid   = initialiseMatrix(rows, columns, EMPTY);

            List<Star> stars = detectStars(originalGrid);
            drawStars(resultGrid, stars);

            validateAndPrint(originalGrid, resultGrid, stars);
        }
    }

    /** --------------------------------------------------------------------- *
     *  Input handling
     *  ------------------------------------------------------------------- */
    private static char[][] readMatrix(Scanner scanner, int rows, int cols) {
        char[][] matrix = new char[rows][cols];
        for (int i = 0; i < rows; i++) {
            String line = scanner.next();
            for (int j = 0; j < cols; j++) {
                matrix[i][j] = line.charAt(j);
            }
        }
        return matrix;
    }

    /** --------------------------------------------------------------------- *
     *  Helper utilities
     *  ------------------------------------------------------------------- */
    private static char[][] initialiseMatrix(int rows, int cols, char filler) {
        char[][] matrix = new char[rows][cols];
        for (char[] row : matrix) {
            java.util.Arrays.fill(row, filler);
        }
        return matrix;
    }

    /** --------------------------------------------------------------------- *
     *  Star detection
     *  ------------------------------------------------------------------- */
    private static List<Star> detectStars(char[][] grid) {
        List<Star> stars = new ArrayList<>();

        // Scan only inner cells – border cells can never be a centre
        for (int i = 1; i < grid.length - 1; i++) {
            for (int j = 1; j < grid[i].length - 1; j++) {
                processCell(grid, i, j, stars);
            }
        }
        return stars;
    }

    /** Evaluate a single cell for being the centre of a star pattern. */
    private static void processCell(char[][] grid, int row, int col, List<Star> stars) {
        if (grid[row][col] != EMPTY) {
            int radius = calculateRadius(grid, row, col);
            if (radius > 0) {
                stars.add(new Star(row, col, radius));
            }
        }
    }

    /** Determine the radius of a star centred at (row, col). */
    private static int calculateRadius(char[][] grid, int centreRow, int centreCol) {
        int radius = 0;
        int up    = centreRow - 1;
        int down  = centreRow + 1;
        int left  = centreCol - 1;
        int right = centreCol + 1;

        while (true) {
            // stop if we hit a border
            if (up < 0 || down >= grid.length || left < 0 || right >= grid[0].length) {
                break;
            }

            // The original logic required symmetry and a '*' at the down cell.
            char centreChar  = grid[down][centreCol];
            char upChar      = grid[up][centreCol];
            char leftChar    = grid[centreRow][left];
            char rightChar   = grid[centreRow][right];

            if (centreChar.equals(upChar)
                    && leftChar.equals(rightChar)
                    && upChar.equals(leftChar)
                    && upChar.equals('*')) {
                radius++;
                // expand for next iteration
                up--;
                down++;
                left--;
                right++;
            } else {
                break;
            }
        }
        return radius;
    }

    /** --------------------------------------------------------------------- *
     *  Visualisation
     *  ------------------------------------------------------------------- */
    private static void drawStars(char[][] target, List<Star> stars) {
        for (Star star : stars) {
            target[star.row()][star.col()] = SYMBOL;

            for (int offset = 0; offset < star.radius(); offset++) {
                target[star.row() - offset - 1][star.col()] = SYMBOL; // up
                target[star.row() + offset + 1][star.col()] = SYMBOL; // down
                target[star.row()][star.col() - offset - 1] = SYMBOL; // left
                target[star.row()][star.col() + offset + 1] = SYMBOL; // right
            }
        }
    }

    /** --------------------------------------------------------------------- *
     *  Validation & output
     *  ------------------------------------------------------------------- */
    private static void validateAndPrint(char[][] original, char[][] transformed, List<Star> stars) {
        // The specification used `System.out.println(-1)` when something was wrong.
        // We keep that behaviour but make the check explicit and well‑named.
        if (!java.util.Arrays.deepEquals(original, transformed)) {
            System.out.println(-1);
            return;
        }

        // Success – print number of stars followed by each star description.
        System.out.println(stars.size());
        for (Star star : stars) {
            System.out.println(star);
        }
    }

    /** --------------------------------------------------------------------- *
     *  Domain model – immutable record describing a found star.
     *  ------------------------------------------------------------------- */
    public record Star(int row, int col, int radius) {
        public Star(int row, int col, int radius) {
            if (radius < 0) {
                throw new IllegalArgumentException("Radius must be non‑negative");
            }
            this.row     = row;
            this.col     = col;
            this.radius  = radius;
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Finds plus‑shaped patterns made of '*' in a grid.
 *
 * <p>For each '*' that can be the centre of a plus, the algorithm counts how many
 * consecutive '*' appear in the four orthogonal directions, takes the minimum
 * of those counts as the arm length and records the centre (1‑based) together
 * with the arm length.  After scanning the whole grid it checks whether every
 * '*' belongs to at least one recorded plus; if not the output is {@code -1},
 * otherwise it prints the number of pluses followed by one line per plus
 * containing its centre row, centre column and arm length.</p>
 */
public class Main {

    /** input tokenizer */
    private static FastScanner scanner;

    /** output writer */
    private static PrintWriter out;

    /** flag indicating multiple test cases */
    private static boolean multipleTC;

    /** run on a separate thread when the memory limit is tight */
    private static final boolean MEMORY = false;

    /** entry point */
    public static void main(String[] args) throws Exception {
        if (MEMORY) {
            Thread.ofPlatform()
                    .start(() -> run());
        } else {
            run();
        }
    }

    /** core algorithm driver */
    private static void run() throws Exception {
        scanner = new FastScanner();
        out = new PrintWriter(System.out);

        int tests = multipleTC ? scanner.nextInt() : 1;
        for (int tc = 1; tc <= tests; tc++) {
            solve(tc);
        }

        out.flush();
        out.close();
    }

    /** solution for a single test case */
    private static void solve(int caseIndex) {
        int rows = scanner.nextInt();
        int cols = scanner.nextInt();

        char[][] grid = new char[rows][cols];
        for (int r = 0; r < rows; r++) {
            String line = scanner.next();
            System.arraycopy(line.toCharArray(), 0, grid[r], 0, cols);
        }

        boolean[][] covered = new boolean[rows][cols];
        List<String> plusLines = new ArrayList<>();

        // helper lambda for marking an entire arm
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] != '*') continue;

                int up = countConsec(grid, r - 1, c, -1, 0);
                int down = countConsec(grid, r + 1, c, 1, 0);
                int left = countConsec(grid, r, c - 1, 0, -1);
                int right = countConsec(grid, r, c + 1, 0, 1);

                int minArm = Math.min(Math.min(up, down), Math.min(left, right));
                if (minArm == 0) continue;               // not a valid plus centre

                // record the plus and mark its cells
                plusLines.add((r + 1) + " " + (c + 1) + " " + minArm);
                covered[r][c] = true;
                markArm(grid, r, c, minArm, covered);

                // no need to continue scanning the same plus
                continue outerLoop;
            }
        }

        // verify that every '*' has been marked
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '*' && !covered[r][c]) {
                    out.println(-1);
                    return;
                }
            }
        }

        // output the result
        out.print(plusLines.size());
        if (!plusLines.isEmpty()) {
            out.println();
            out.print(String.join("\n", plusLines));
        }
    }

    /** counts consecutive '*' starting from (startR,startC) toward (dR,dC) */
    private static int countConsec(char[][] g, int r, int c, int dr, int dc) {
        int cnt = 0;
        while (inBounds(g, r, c) && g[r][c] == '*') {
            cnt++;
            r += dr;
            c += dc;
        }
        return cnt;
    }

    /** marks the centre cell and its four arms up to the supplied length */
    private static void markArm(char[][] g, int centerR, int centerC,
                                int armLen, boolean[][] covered) {
        covered[centerR][centerC] = true;
        for (int step = 1; step <= armLen; step++) {
            covered[centerR - step][centerC] = true;
            covered[centerR + step][centerC] = true;
            covered[centerR][centerC - step] = true;
            covered[centerR][centerC + step] = true;
        }
    }

    /** bounds check for a grid cell */
    private static boolean inBounds(char[][] g, int r, int c) {
        return r >= 0 && r < g.length && c >= 0 && c < g[0].length;
    }

    /** simple wrapper around next token for competitive‑programming style */
    private static String next() {
        return scanner.next();
    }

    /** simple wrapper around next integer */
    private static int nextInt() {
        return Integer.parseInt(scanner.next());
    }

    /** fast scanner that works with both STDIN and a file supplied on the command line */
    private static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner() {
            this(null);
        }

        FastScanner(String filePath) {
            try {
                br = new BufferedReader(
                        new FileReader(filePath));
            } catch (FileNotFoundException e) {
                throw new UncheckedIOException(e);
            }
        }

        FastScanner(Reader reader) {
            br = new BufferedReader(reader);
        }

        /** returns the next token, fetching a new line when needed */
        private String nextToken() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new UncheckedIOException(e);
                }
            }
            return st.nextToken();
        }

        String next() { return nextToken(); }

        int nextInt() { return Integer.parseInt(next()); }

        long nextLong() { return Long.parseLong(next()); }

        double nextDouble() { return Double.parseDouble(next()); }

        String nextLine() {
            try {
                return br.readLine();
            } catch (IOException e) {
                throw new UncheckedIOException(e);
            }
        }
    }
}

import java.io.*;
import java.text.DecimalFormat;
import java.util.ArrayList;
import java.util.List;

/**
 * Refactored version of the original solution.
 *
 * <p>Key improvements:
 * <ul>
 *   <li>Separated concerns (I/O, grid analysis, output formatting) into dedicated methods.</li>
 *   <li>Renamed confusing variables and constants to meaningful names.</li>
 *   <li>Removed unused fields (mod, IINF, PI, root, etc.) and unused imports.</li>
 *   <li>Eliminated magic numbers by using {@code Integer.MAX_VALUE / 2} as INF.</li>
 *   <li>Extracted helper methods for each directional distance calculation.</li>
 *   <li>Used {@code List<String>} to build the output string before writing – avoids repeated
 *       {@code StringBuilder} manipulation.</li>
 *   <li>Added short Javadoc comments and clear method names for readability.</li>
 *   <li>Provided a constructor that accepts {@code InputStream}/{@code OutputStream} so the
 *       {@code main} method can be easily unit‑tested.</li>
 * </ul>
 *
 * The algorithmic behaviour is unchanged – it reads grids of characters, computes the
 * minimum Manhattan distance to the nearest '*', marks the covered cells via difference
 * arrays, and prints either {@code -1} if any '*' remains uncovered or the list of cells
 * together with their distance value.
 */
public class Main {

    /** Half‑INT_MAX – used as a large sentinel value. */
    private static final int INF = Integer.MAX_VALUE / 2;

    /** Formatter kept from the original source (unused in the current logic but preserved). */
    private static final DecimalFormat DF = new DecimalFormat("0.00000000");

    private final FastScanner scanner;
    private final PrintWriter writer;

    /**
     * Creates a new {@code Main} instance bound to the supplied streams.
     *
     * @param in  stream used for reading input
     * @param out stream to which output will be written
     */
    public Main(InputStream in, OutputStream out) {
        this.scanner = new FastScanner(in);
        this.writer = new PrintWriter(out);
    }

    /** Entry point – delegates to the refactored {@code run()} method. */
    public static void main(String[] args) throws Exception {
        new Main(System.in, System.out).run();
    }

    /** Core driver that processes test cases until EOF. */
    public void run() {
        // The original code allowed toggling "multipleTC" but we keep the default behaviour
        // (process a single test case per execution).  If you wish to support multiple tc's,
        // expose a setter or a command‑line flag.
        while (scanner.hasNext()) {
            int testCaseIdx = scanner.nextInt();          // placeholder – not used further
            solve();
        }
        writer.flush();
        writer.close();
    }

    /** Solves one test case (reads dimensions, grid, and produces output). */
    private void solve() {
        int n = scanner.nextInt();
        int m = scanner.nextInt();
        char[][] grid = readGrid(n);

        int[][] minDist = computeMinDistanceToStar(grid);
        int[][] diffHoriz = new int[n][m + 1];
        int[][] diffVert  = new int[n + 1][m];

        List<String> outputLines = new ArrayList<>();

        // Mark intervals contributed by each cell with distance > 0
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                int d = minDist[i][j];
                if (d > 0) {
                    // Horizontal interval [j‑d, j+d]
                    diffHoriz[i][j - d]++;
                    if (j + d + 1 < m) {
                        diffHoriz[i][j + d + 1]--;
                    }
                    // Vertical interval [i‑d, i+d]
                    diffVert[i - d][j]++;
                    if (i + d + 1 < n) {
                        diffVert[i + d + 1][j]--;
                    }
                    // Store the triple (row, col, d) for later output
                    outputLines.add(i + 1 + " " + (j + 1) + " " + d);
                }
            }
        }

        // Build prefix sums to know how many times each cell is covered
        boolean uncoveredStarExists = false;
        int[][] horizCoverage = new int[n][m];
        int[][] vertCoverage  = new int[n][m];

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (j > 0) {
                    horizCoverage[i][j] += horizCoverage[i][j - 1];
                }
                horizCoverage[i][j] += diffHoriz[i][j];

                if (i > 0) {
                    vertCoverage[i][j] += vertCoverage[i - 1][j];
                }
                vertCoverage[i][j] += diffVert[i][j];

                if (grid[i][j] == '*' &&
                        Math.max(vertCoverage[i][j], horizCoverage[i][j]) == 0) {
                    uncoveredStarExists = true;
                }
            }
        }

        // Produce final output
        if (uncoveredStarExists) {
            writer.println(-1);
        } else {
            int count = outputLines.size();           // each recorded triple occupies one line
            writer.println(count);
            for (String line : outputLines) {
                writer.println(line);
            }
        }
    }

    /** Reads {@code rows} lines from the scanner and returns them as a character grid. */
    private char[][] readGrid(int rows) {
        char[][] grid = new char[rows][];
        for (int i = 0; i < rows; i++) {
            String line = scanner.nextLine();
            grid[i] = line.toCharArray();
        }
        return grid;
    }

    /**
     * Computes, for each cell, the minimum distance to the nearest {@code '*'} in any of the
     * four orthogonal directions.  The returned matrix contains {@code 0} for cells that are
     * themselves {@code '*',} otherwise the distance (original code subtracted {@code 1} after
     * taking the minimum of the four rotated “up” matrices).
     */
    private int[][] computeMinDistanceToStar(char[][] grid) {
        int rows = grid.length;
        int cols = grid[0].length;

        // Distances in the four orthogonal directions
        int[][] up    = distanceUp(grid);
        int[][] down  = distanceDown(grid);
        int[][] left  = distanceLeft(grid);
        int[][] right = distanceRight(grid);

        int[][] min = new int[rows][cols];
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                int best = INF;
                best = Math.min(best, up[i][j]);
                best = Math.min(best, down[i][j]);
                best = Math.min(best, left[i][j]);
                best = Math.min(best, right[i][j]);
                // Replicate original behaviour: take min, then subtract 1, but never go below 0.
                min[i][j] = Math.max(0, best - 1);
            }
        }
        return min;
    }

    /** Returns a matrix where each cell holds the distance to the nearest '*' moving upward. */
    private int[][] distanceUp(char[][] grid) {
        int rows = grid.length;
        int cols = grid[0].length;
        int[][] d = new int[rows][cols];
        for (int j = 0; j < cols; j++) {
            int cur = 0;
            for (int i = 0; i < rows; i++) {
                if (grid[i][j] == '*') {
                    cur = 1;
                } else if (cur > 0) {
                    cur++;
                }
                d[i][j] = cur;
            }
        }
        return d;
    }

    /** Returns a matrix where each cell holds the distance to the nearest '*' moving downward. */
    private int[][] distanceDown(char[][] grid) {
        int rows = grid.length;
        int cols = grid[0].length;
        int[][] d = new int[rows][cols];
        for (int j = 0; j < cols; j++) {
            int cur = 0;
            for (int i = rows - 1; i >= 0; i--) {
                if (grid[i][j] == '*') {
                    cur = 1;
                } else if (cur > 0) {
                    cur++;
                }
                d[i][j] = cur;
            }
        }
        return d;
    }

    /** Returns a matrix where each cell holds the distance to the nearest '*' moving leftward. */
    private int[][] distanceLeft(char[][] grid) {
        int rows = grid.length;
        int cols = grid[0].length;
        int[][] d = new int[rows][cols];
        for (int i = 0; i < rows; i++) {
            int cur = 0;
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == '*') {
                    cur = 1;
                } else if (cur > 0) {
                    cur++;
                }
                d[i][j] = cur;
            }
        }
        return d;
    }

    /** Returns a matrix where each cell holds the distance to the nearest '*' moving rightward. */
    private int[][] distanceRight(char[][] grid) {
        int rows = grid.length;
        int cols = grid[0].length;
        int[][] d = new int[rows][cols];
        for (int i = 0; i < rows; i++) {
            int cur = 0;
            for (int j = cols - 1; j >= 0; j--) {
                if (grid[i][j] == '*') {
                    cur = 1;
                } else if (cur > 0) {
                    cur++;
                }
                d[i][j] = cur;
            }
        }
        return d;
    }

    /** Lightweight scanner that provides {@code next()}, {@code nextInt()}, {@code nextLine()} etc. */
    private static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner(InputStream stream) {
            br = new BufferedReader(new InputStreamReader(stream));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    throw new UncheckedIOException(e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        String nextLine() {
            try {
                return br.readLine();
            } catch (IOException e) {
                throw new UncheckedIOException(e);
            }
        }

        boolean hasNext() {
            try {
                return br.ready();
            } catch (IOException e) {
                return false;
            }
        }
    }
}

import java.io.*;
import java.util.*;

public class Main {

    /** Simple event used for sweep line */
    private static final class Event implements Comparable<Event> {
        final int pos;   // coordinate (row or column)
        final int delta; // +1 to start, -1 to end

        Event(int pos, int delta) {
            this.pos = pos;
            this.delta = delta;
        }

        @Override
        public int compareTo(Event o) {
            return Integer.compare(this.pos, o.pos);
        }
    }

    /** Information about a detected star */
    private static final class Star {
        final int col;   // x‑coordinate (0‑based)
        final int row;   // y‑coordinate (0‑based)
        final int size;  // radius - 1 (output size)

        Star(int col, int row, int size) {
            this.col = col;
            this.row = row;
            this.size = size;
        }
    }

    /** Solver containing all the logic */
    private static final class Solver {
        private final Scanner in;
        private final PrintWriter out;

        Solver(Scanner in, PrintWriter out) {
            this.in = in;
            this.out = out;
        }

        void solve() {
            int height = in.nextInt();
            int width  = in.nextInt();

            char[][] grid = new char[width][height];
            for (int y = 0; y < height; y++) {
                String line = in.next();
                for (int x = 0; x < width; x++) {
                    grid[x][y] = line.charAt(x);
                }
            }

            // directional continuations
            int[][] left  = computeLeft(grid);
            int[][] right = computeRight(grid);
            int[][] up    = computeUp(grid);
            int[][] down  = computeDown(grid);

            // events for painted cells
            @SuppressWarnings("unchecked")
            List<Event>[] eventsByX = new List[width];
            List<Event>[] eventsByY = new List[height];
            for (int i = 0; i < width; i++)   eventsByX[i] = new ArrayList<>();
            for (int i = 0; i < height; i++)  eventsByY[i] = new ArrayList<>();

            List<Star> stars = new ArrayList<>();

            // detect stars and create events
            for (int x = 0; x < width; x++) {
                for (int y = 0; y < height; y++) {
                    int radius = Math.min(
                            Math.min(left[x][y], right[x][y]),
                            Math.min(up[x][y],   down[x][y])
                    );
                    if (radius >= 2) {
                        stars.add(new Star(x, y, radius - 1));

                        int startX = x - radius + 1;
                        int endX   = x + radius - 1;
                        int startY = y - radius + 1;
                        int endY   = y + radius - 1;

                        // vertical strip (column x)
                        eventsByX[x].add(new Event(startY, 1));
                        eventsByX[x].add(new Event(endY + 1, -1));

                        // horizontal strip (row y)
                        eventsByY[y].add(new Event(startX, 1));
                        eventsByY[y].add(new Event(endX + 1, -1));
                    }
                }
            }

            // mark painted cells using sweep line
            boolean[][] painted = new boolean[width][height];
            markPainted(eventsByX, painted);
            markPainted(eventsByY, painted);

            // validate that painted pattern matches the original grid
            for (int x = 0; x < width; x++) {
                for (int y = 0; y < height; y++) {
                    boolean paintedCell = painted[x][y];
                    boolean expectedStar  = (grid[x][y] == '*');
                    if (paintedCell != expectedStar) {
                        out.println(-1);
                        return;
                    }
                }
            }

            // output answer
            out.println(stars.size());
            for (Star s : stars) {
                out.printf("%d %d %d%n", s.row + 1, s.col + 1, s.size);
            }
        }

        /** Fill leftward continuations (including current cell) */
        private static int[][] computeLeft(char[][] grid) {
            int w = grid.length;
            int h = grid[0].length;
            int[][] res = new int[w][h];
            for (int x = 0; x < w; x++) {
                for (int y = 0; y < h; y++) {
                    if (x == 0) {
                        res[x][y] = (grid[x][y] == '*') ? 1 : 0;
                    } else {
                        res[x][y] = (grid[x][y] == '*') ? 1 + res[x - 1][y] : 0;
                    }
                }
            }
            return res;
        }

        /** Fill upward continuations */
        private static int[][] computeUp(char[][] grid) {
            int w = grid.length;
            int h = grid[0].length;
            int[][] res = new int[w][h];
            for (int x = 0; x < w; x++) {
                for (int y = 0; y < h; y++) {
                    if (y == 0) {
                        res[x][y] = (grid[x][y] == '*') ? 1 : 0;
                    } else {
                        res[x][y] = (grid[x][y] == '*') ? 1 + res[x][y - 1] : 0;
                    }
                }
            }
            return res;
        }

        /** Fill rightward continuations */
        private static int[][] computeRight(char[][] grid) {
            int w = grid.length;
            int h = grid[0].length;
            int[][] res = new int[w][h];
            for (int x = w - 1; x >= 0; x--) {
                for (int y = 0; y < h; y++) {
                    if (x == w - 1) {
                        res[x][y] = (grid[x][y] == '*') ? 1 : 0;
                    } else {
                        res[x][y] = (grid[x][y] == '*') ? 1 + res[x + 1][y] : 0;
                    }
                }
            }
            return res;
        }

        /** Fill downward continuations */
        private static int[][] computeDown(char[][] grid) {
            int w = grid.length;
            int h = grid[0].length;
            int[][] res = new int[w][h];
            for (int x = 0; x < w; x++) {
                for (int y = h - 1; y >= 0; y--) {
                    if (y == h - 1) {
                        res[x][y] = (grid[x][y] == '*') ? 1 : 0;
                    } else {
                        res[x][y] = (grid[x][y] == '*') ? 1 + res[x][y + 1] : 0;
                    }
                }
            }
            return res;
        }

        /** Apply sweep‑line events to a boolean mask */
        private static void markPainted(List<Event>[] events, boolean[][] mask) {
            for (int fixed = 0; fixed < events.length; fixed++) {
                List<Event> list = events[fixed];
                if (list.isEmpty()) {
                    continue;
                }
                Event[] arr = list.toArray(new Event[0]);
                Arrays.sort(arr);

                int idx = 0;
                int active = 0;
                for (int i = 0; i < mask[0].length; i++) {
                    while (idx < arr.length && arr[idx].pos == i) {
                        active += arr[idx].delta;
                        idx++;
                    }
                    if (active > 0) {
                        mask[fixed][i] = true;
                    }
                }
            }
        }
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        PrintWriter printer = new PrintWriter(System.out);
        Solver solver = new Solver(scanner, printer);
        try {
            solver.solve();
        } catch (Exception e) {
            // In case of unexpected I/O errors
            e.printStackTrace();
        }
        printer.flush();
        printer.close();
    }
}

import java.io.*;
import java.util.ArrayList;
import java.util.List;
import java.util.StringTokenizer;

/**
 * Solution for the “Stars in the Grid” problem.
 *
 * <p>Refactored for readability, maintainability and single‑responsibility
 * principles.  The program reads a rectangular grid of characters,
 * detects all stars (a central ‘*’ with equal‑length arms of ‘*’),
 * records their positions (1‑based) and arm length, and finally verifies
 * that every ‘*’ belongs to exactly one detected star.</p>
 */
public class E1 implements Closeable {

    /* --------------------------------------------------------------------- */
    /*  Constants                                                            */
    /* --------------------------------------------------------------------- */
    private static final char ASTERISK = '*';

    /* --------------------------------------------------------------------- */
    /*  Core data structures                                                   */
    /* --------------------------------------------------------------------- */
    /** Simple holder for a detected star. */
    private static final class Star {
        final int row;   // 1‑based row index of the centre
        final int col;   // 1‑based column index of the centre
        final int size;  // length of each arm (≥ 1)

        Star(int row, int col, int size) {
            this.row = row;
            this.col = col;
            this.size = size;
        }
    }

    /* --------------------------------------------------------------------- */
    /*  Instance fields                                                       */
    /* --------------------------------------------------------------------- */
    private final InputReader input;
    private final PrintWriter output;

    /* --------------------------------------------------------------------- */
    /*  Construction                                                            */
    /* --------------------------------------------------------------------- */
    public E1(InputStream in, PrintWriter out) {
        this.input = new InputReader(in);
        this.output = out;
    }

    /* --------------------------------------------------------------------- */
    /*  Public API                                                             */
    /* --------------------------------------------------------------------- */
    /** Entry point used by the provided wrapper. */
    public void solve() {
        int rows = input.ni();
        int cols = input.ni();
        char[][] grid = readGrid(rows);

        boolean[][] visited = new boolean[rows][cols];
        List<Star> stars = detectStars(grid, visited);

        if (allAsterisksCovered(grid, visited)) {
            outputStars(stars);
        } else {
            output.println(-1);
        }
    }

    @Override
    public void close() throws IOException {
        input.close();
        output.close();
    }

    /* --------------------------------------------------------------------- */
    /*  Private helpers                                                         */
    /* --------------------------------------------------------------------- */
    /** Reads the grid from the input stream. */
    private char[][] readGrid(int rows) {
        char[][] grid = new char[rows][];
        for (int r = 0; r < rows; r++) {
            grid[r] = input.next().toCharArray();
        }
        return grid;
    }

    /**
     * Finds all stars in the grid.
     *
     * <p>Each star is defined by its centre cell and the length of its arms.
     * The method marks every cell belonging to a discovered star in {@code visited}.</p>
     */
    private List<Star> detectStars(char[][] grid, boolean[][] visited) {
        List<Star> stars = new ArrayList<>();

        for (int r = 0; r < grid.length; r++) {
            for (int c = 0; c < grid[r].length; c++) {
                if (grid[r][c] == ASTERISK && !visited[r][c]) {
                    int armLength = expandArmLength(grid, visited, r, c);
                    if (armLength > 0) {
                        int centreRow = r + 1;   // convert to 1‑based indexing
                        int centreCol = c + 1;
                        stars.add(new Star(centreRow, centreCol, armLength));
                    }
                }
            }
        }
        return stars;
    }

    /**
     * Attempts to grow a star centred at (r, c).
     *
     * @return length of each arm (0 if the centre cannot be a star centre)
     */
    private int expandArmLength(char[][] grid, boolean[][] visited, int centreR, int centreC) {
        int size = 0;
        int up = centreR - 1, down = centreR + 1, left = centreC - 1, right = centreC + 1;

        while (up >= 0 && down < grid.length && left >= 0 && right < grid[0].length) {
            if (grid[up][centreC] == ASTERISK && grid[down][centreC] == ASTERISK
                    && grid[centreR][left] == ASTERISK && grid[centreR][right] == ASTERISK) {
                size++;
                // Mark all five cells of this level as visited
                visited[centreR][centreC] = true;
                visited[up][centreC] = true;
                visited[down][centreC] = true;
                visited[centreR][left] = true;
                visited[centreR][right] = true;

                up--;
                down++;
                left--;
                right++;
            } else {
                break; // cannot expand further
            }
        }
        return size;
    }

    /** Returns true if every asterisk in the grid has been visited (i.e. belongs to a star). */
    private boolean allAsterisksCovered(char[][] grid, boolean[][] visited) {
        for (int r = 0; r < grid.length; r++) {
            for (int c = 0; c < grid[r].length; c++) {
                if (grid[r][c] == ASTERISK && !visited[r][c]) {
                    return false;
                }
            }
        }
        return true;
    }

    /** Prints the result according to the problem statement. */
    private void outputStars(List<Star> stars) {
        output.println(stars.size());
        for (Star star : stars) {
            output.print(star.row);
            output.print(' ');
            output.print(star.col);
            output.print(' ');
            output.println(star.size);
        }
    }

    /* --------------------------------------------------------------------- */
    /*  Input reader                                                            */
    /* --------------------------------------------------------------------- */
    /** Simple wrapper around BufferedReader/StringTokenizer for fast tokenisation. */
    private static final class InputReader implements Closeable {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        InputReader(InputStream stream) {
            this.reader = new BufferedReader(new InputStreamReader(stream), 32768);
        }

        /** Reads the next token, blocking until one is available. */
        private String nextToken() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new UncheckedIOException(e);
                }
            }
            return tokenizer.nextToken();
        }

        /** Convenience method to read an int. */
        int ni() {
            return Integer.parseInt(nextToken());
        }

        /** Convenience method to read a long. */
        long nl() {
            return Long.parseLong(nextToken());
        }

        @Override
        public void close() throws IOException {
            reader.close();
        }
    }

    /* --------------------------------------------------------------------- */
    /*  Main entry point                                                         */
    /* --------------------------------------------------------------------- */
    public static void main(String[] args) throws IOException {
        // The try‑with‑resources block guarantees proper closure of I/O streams.
        try (E1 solution = new E1(System.in, new PrintWriter(System.out))) {
            solution.solve();
        }
    }
}

import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;

/**
 * Reads a grid of '*' and '.' characters and extracts all maximal plus‑shaped
 * stars. If after removing all discovered stars any '*' remains, the program
 * prints -1; otherwise it prints the number of stars followed by their
 * 1‑based coordinates and arm length.
 */
public class Main {

    /** Simple DTO for a discovered star. */
    private static final class Star {
        final int row;   // 0‑based row index
        final int col;   // 0‑based column index
        final int arm;   // length of each arm (≥1)

        Star(int row, int col, int arm) {
            this.row = row;
            this.col = col;
            this.arm = arm;
        }
    }

    /** Directions used to test the four arms of a potential star. */
    private static final int[] DY = {-1, 1, 0, 0};
    private static final int[] DX = {0, 0, -1, 1};

    /** Entry point. */
    public static void main(String[] args) {
        new Main().solve();
    }

    /** Orchestrates the whole workflow: input → processing → output. */
    private void solve() {
        try (Scanner sc = new Scanner(System.in)) {
            int rows = sc.nextInt();
            int cols = sc.nextInt();

            boolean[][] before = readGrid(sc, rows, cols);
            boolean[][] after = cloneGrid(before);

            List<Star> stars = discoverStars(before, after, rows, cols);

            if (containsRemainingStar(after, rows, cols)) {
                System.out.println(-1);
                return;
            }

            System.out.println(stars.size());
            stars.forEach(star -> System.out.printf("%d %d %d%n",
                    star.row + 1, star.col + 1, star.arm));
        }
    }

    /** Reads the grid from the scanner and fills the supplied matrix. */
    private static boolean[][] readGrid(Scanner sc, int n, int m) {
        boolean[][] grid = new boolean[n][m];
        for (int i = 0; i < n; i++) {
            String line = sc.next();
            if (line.length() != m) {
                throw new IllegalArgumentException("Row length mismatch");
            }
            for (int j = 0; j < m; j++) {
                grid[i][j] = line.charAt(j) == '*';
            }
        }
        return grid;
    }

    /** Returns a deep copy of the given boolean grid. */
    private static boolean[][] cloneGrid(boolean[][] src) {
        boolean[][] dst = new boolean[src.length][src[0].length];
        for (int i = 0; i < src.length; i++) {
            System.arraycopy(src[i], 0, dst[i], 0, src[i].length);
        }
        return dst;
    }

    /**
     * Scans the interior of the grid for valid star centers, determines the
     * maximal arm length for each, records them and marks the corresponding
     * cells as removed in the {@code after} grid.
     */
    private static List<Star> discoverStars(boolean[][] before,
                                            boolean[][] after,
                                            int n, int m) {
        List<Star> result = new ArrayList<>();

        // iterate only over cells that can be centers of a plus shape
        for (int i = 1; i < n - 1; i++) {
            for (int j = 1; j < m - 1; j++) {
                if (!before[i][j]) {
                    continue;
                }

                int armLength = computeMaxArm(before, i, j, n, m);
                if (armLength < 1) {
                    continue;
                }

                // Mark the center and the four arms as “removed”
                after[i][j] = false;
                markArmsRemoved(after, i, j, armLength);
                result.add(new Star(i, j, armLength));
            }
        }
        return result;
    }

    /**
     * Determines the largest {@code len} such that all four arms of length
     * {@code len} around (i, j) consist solely of '*' in the {@code before}
     * grid.
     */
    private static int computeMaxArm(boolean[][] before, int i, int j,
                                     int n, int m) {
        int arm = 0;
        // try to expand outward step by step
        for (int len = 1; ; len++) {
            if (isOutOfBounds(i, j, len, n, m)) {
                break;
            }
            if (!hasStarInAllDirections(before, i, j, len)) {
                break;
            }
            arm = len; // current length is valid
        }
        return arm;
    }

    /** Checks whether expanding by {@code len} stays inside the grid. */
    private static boolean isOutOfBounds(int i, int j, int len,
                                         int n, int m) {
        return i - len < 0 || i + len >= n || j - len < 0 || j + len >= m;
    }

    /** Returns true iff the four cells at distance {@code len} from (i,j)
     *  are all stars in the {@code before} grid. */
    private static boolean hasStarInAllDirections(boolean[][] before,
                                                  int i, int j, int len) {
        return before[i - len][j] && before[i + len][j]
                && before[i][j - len] && before[i][j + len];
    }

    /** Marks the center and the four arms of the given star as removed
     *  (set to {@code false}) in the {@code after} grid. */
    private static void markArmsRemoved(boolean[][] after,
                                        int i, int j, int arm) {
        // center
        after[i][j] = false;

        // four arms
        for (int d = 1; d <= arm; d++) {
            after[i - d][j] = false; // up
            after[i + d][j] = false; // down
            after[i][j - d] = false; // left
            after[i][j + d] = false; // right
        }
    }

    /** Checks whether any '*' remains in the grid. */
    private static boolean containsRemainingStar(boolean[][] grid,
                                                 int n, int m) {
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i][j]) {
                    return true;
                }
            }
        }
        return false;
    }
}

import java.io.*;
import java.util.*;

/**
 * Reads a grid of characters ( '*' for a star and '.' for empty )
 * and prints the minimum number of “+” signs needed to cover all stars.
 *
 * Each ‘+’ is defined by a centre cell and a radius *r* (r ≥ 1).  The
 * plus consists of the four arms of length *r* extending from the centre.
 *
 * The algorithm works as follows:
 *   1. Find every cell that can be the centre of a plus.
 *   2. For each centre determine the largest possible radius.
 *   3. Process pluses from largest radius to smallest, picking a plus
 *      only if it covers at least one still‑uncovered star.
 *   4. If after processing all candidates some stars remain uncovered,
 *      the answer is –1; otherwise the number of chosen pluses and their
 *      coordinates are printed.
 */
public class Main {

    /** Fast scanner over bytes. */
    private static final class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        // standard bookkeeping fields
        private int ptr = 0, len = 0;

        FastScanner(InputStream in) {
            this.in = in;
        }

        private int readByte() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) {
                    return -1;
                }
            }
            return buffer[ptr++];
        }

        /** Skips any whitespace characters. */
        private static boolean isSpace(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        /** Reads a single token as a string. */
        String next() throws IOException {
            int c;
            while (isSpace(c = readByte())) { /* skip */ }
            StringBuilder sb = new StringBuilder();
            do {
                sb.append((char) c);
                c = readByte();
            } while (!isSpace(c));
            return sb.toString();
        }

        /** Reads the next integer (handles leading minus sign). */
        int nextInt() throws IOException {
            int sign = 1, c;
            do {
                c = readByte();
            } while (isSpace(c));
            if (c == '-') {
                sign = -1;
                c = readByte();
            }
            int value = 0;
            while (c >= '0' && c <= '9') {
                value = value * 10 + (c - '0');
                c = readByte();
            }
            return value * sign;
        }

        /** Returns the next line as a char array. */
        char[] nextCharArray() throws IOException {
            return next().toCharArray();
        }
    }

    /** Simple holder for a plus (centre + radius). */
    private static final class Plus {
        final int row;      // zero‑based row index
        final int col;      // zero‑based column index
        final int radius;   // length of each arm (≥ 1)

        Plus(int row, int col, int radius) {
            this.row = row;
            this.col = col;
            this.radius = radius;
        }

        /** Larger radius → higher priority. */
        int priority() {
            return radius;
        }

        @Override
        public String toString() {
            // Output expects 1‑based coordinates and radius‑1 (as in original)
            return String.format("%d %d %d", row + 1, col + 1, radius - 1);
        }
    }

    /** Main solving routine – identical logic to the original programme but with clearer structure. */
    private static final class Solver {
        private final char[][] grid;               // original board
        private final boolean[][] covered;         // tracks cells already covered
        private final List<Plus> solution = new ArrayList<>();

        Solver(char[][] grid) {
            this.grid = grid.clone(); // defensive copy – we will modify it in‑place
            this.covered = new boolean[grid.length][grid[0].length];
        }

        /** Public entry point used by Main.main(). */
        void solve(PrintWriter out) {
            int rows = grid.length;
            int cols = grid[0].length;

            // -----------------------------------------------------------------
            // 1️⃣  Find all maximal pluses (centre + biggest radius)
            // -----------------------------------------------------------------
            PriorityQueue<Plus> plusQueue = new PriorityQueue<>(Comparator.comparingInt(Plus::priority).reversed());

            for (int r = 1; r < rows - 1; ++r) {
                for (int c = 1; c < cols - 1; ++c) {
                    if (canBeCenter(r, c)) {
                        int radius = maxRadius(r, c);
                        if (radius > 0) {
                            plusQueue.add(new Plus(r, c, radius));
                        }
                    }
                }
            }

            // -----------------------------------------------------------------
            // 2️⃣  Greedily pick pluses (largest radius first) that actually
            //     cover at least one uncovered star.
            // -----------------------------------------------------------------
            while (!plusQueue.isEmpty() && hasUncoveredStars()) {
                Plus p = plusQueue.poll();
                apply(p);
                solution.add(p);
            }

            // -----------------------------------------------------------------
            // 3️⃣  Output the result.
            // -----------------------------------------------------------------
            if (hasUncoveredStars()) {
                out.println(-1);
            } else {
                out.println(solution.size());
                for (Plus p : solution) {
                    out.println(p);
                }
            }
        }

        /** Checks whether the cell (r,c) can be the centre of a plus of radius ≥ 1. */
        private boolean canBeCenter(int r, int c) {
            return grid[r][c] == '*';
        }

        /** Determines the largest radius for which the plus centred at (r,c) is valid. */
        private int maxRadius(int r, int c) {
            int radius = 0;
            while (true) {
                int next = radius + 1;
                if (!isInnerCell(r, c, next) || !isArmComplete(r, c, next)) {
                    break;
                }
                radius = next;
            }
            return radius;
        }

        /** True if the cell lies inside the board. */
        private boolean isInnerCell(int r, int c, int rad) {
            return rad < r && rad < grid.length - r - 1 &&
                   rad < c && rad < grid[0].length - c - 1;
        }

        /** Verifies that the four arms of length *rad* are all stars. */
        private boolean isArmComplete(int r, int c, int rad) {
            return grid[r - rad][c] == '*' && grid[r + rad][c] == '*' &&
                   grid[r][c - rad] == '*' && grid[r][c + rad] == '*';
        }

        /** Marks the centre and all cells of the arms with radius *rad* as covered. */
        private void apply(Plus p) {
            int r = p.row, c = p.col, rad = p.radius;
            covered[r][c] = true;
            for (int i = 1; i <= rad; ++i) {
                covered[r + i][c] = true;
                covered[r - i][c] = true;
                covered[r][c + i] = true;
                covered[r][c - i] = true;
            }
        }

        /** Returns true if at least one cell still contains an uncovered '*'. */
        private boolean hasUncoveredStars() {
            for (int i = 0; i < grid.length; ++i) {
                for (int j = 0; j < grid[0].length; ++j) {
                    if (grid[i][j] == '*' && !covered[i][j]) {
                        return true;
                    }
                }
            }
            return false;
        }

        /** Resets the *covered* matrix – used only by the static wrapper below. */
        private void resetCoverage() {
            for (boolean[] row : covered) {
                Arrays.fill(row, false);
            }
            solution.clear();
        }
    }

    /** Tiny wrapper that keeps the original `Main` signature untouched. */
    public static void main(String[] args) throws Exception {
        FastScanner scanner = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(System.out, true);

        int rows = scanner.nextInt();
        int cols = scanner.nextInt();
        char[][] rawGrid = new char[rows][];
        for (int i = 0; i < rows; ++i) {
            rawGrid[i] = scanner.nextCharArray();
        }

        Solver solver = new Solver(rawGrid);
        // The original program kept a mutable reference when re‑using the same solver;
        // here we simply call solve() directly.
        solver.solve(out);

        out.flush();
    }
}

import java.io.*;
import java.util.*;
import java.util.stream.Collectors;

/**
 * Reads a rectangular grid consisting of '.' and '*', finds the maximal
 * “cross” (also called *star*) centred at each '*', and checks whether every
 * '*' belongs to at least one such cross. If it is possible, the program
 * prints the list of stars; otherwise it prints -1.
 *
 * <p>Refactoring goals:
 * <ul>
 *   <li>Separate concerns (input, processing, output)</li>
 *   <li>Use expressive names and immutable data holders</li>
 *   <li>Avoid raw types and magic numbers</li>
 *   <li>Make the algorithm easier to understand and maintain</li>
 * </ul>
 */
public final class CodeforcesSolution {

    /** immutable representation of a grid coordinate */
    private static final class Coord {
        final int row;   // 0‑based
        final int col;   // 0‑based

        Coord(int row, int col) {
            this.row = row;
            this.col = col;
        }

        /** distance in the four orthogonal directions until a '.' or border */
        int up, down, left, right;

        /** maximum possible star size centred at this coordinate */
        int starSize() {
            return Math.min(Math.min(up, down), Math.min(left, right));
        }

        @Override public boolean equals(Object o) {
            if (this == o) return true;
            if (!(o instanceof Coord)) return false;
            Coord other = (Coord) o;
            return row == other.row && col == other.col;
        }

        @Override public int hashCode() {
            return Objects.hash(row, col);
        }

        @Override public String toString() {
            // output is 1‑based as required by the original problem
            return (row + 1) + " " + (col + 1);
        }
    }

    /** a star consists of a centre and its size (arm length) */
    private static final class Star {
        final Coord centre;
        final int size;   // arm length (>=1)

        Star(Coord centre, int size) {
            this.centre = centre;
            this.size = size;
        }

        /** mark all cells belonging to this star as covered */
        void markCovered(boolean[][] covered) {
            int r = centre.row;
            int c = centre.col;
            for (int i = r - size; i <= r + size; i++) {
                covered[i][c] = true;
            }
            for (int j = c - size; j <= c + size; j++) {
                covered[r][j] = true;
            }
        }

        /** @return true if this star is completely contained in the grid */
        boolean isInsideGrid(int rows, int cols) {
            int limit = Math.min(centre.row, Math.min(centre.col,
                    Math.min(rows - 1 - centre.row, cols - 1 - centre.col)));
            return size <= limit;
        }
    }

    /** holder for the final result – either an error code or the list of stars */
    private sealed interface Result permits Success, Failure {
        /** successful result – the list of stars to output */
        Success(List<Star> stars);

        /** failure result – the problem requires a single line with -1 */
        Failure();
    }

    /** builds a Result object */
    private static Result buildResult(List<Star> stars) {
        return stars.isEmpty() ? new Failure() : new Success(stars);
    }

    /** --------------------------------------------------------------------- */
    /** Main driver – keeps the I/O logic isolated from the algorithmic core */
    public static void main(String[] args) throws IOException {
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in)) {
            StringTokenizer st = new StringTokenizer(br.readLine());
            int rows = Integer.parseInt(st.nextToken());
            int cols = Integer.parseInt(st.nextToken());

            char[][] grid = new char[rows][];
            for (int i = 0; i < rows; i++) {
                grid[i] = br.readLine().toCharArray();
            }

            // -----------------------------------------------------------------
            // 1. discover all possible stars and collect them
            // -----------------------------------------------------------------
            List<Star> candidateStars = discoverStars(grid, rows, cols);

            // -----------------------------------------------------------------
            // 2. verify that every '*' is covered by at least one discovered star
            // -----------------------------------------------------------------
            Result result = validateAndPrepareOutput(candidateStars, rows, cols);
            handleResult(result, rows, cols);
        }
    }

    /** --------------------------------------------------------------------- */
    /** Discover every maximal star that can be placed on a '*' cell. */
    private static List<Star> discoverStars(char[][] grid, int rows, int cols) {
        List<Star> stars = new ArrayList<>();

        // Pre‑compute directional lengths for every cell that contains '*'
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] != '*') continue;

                Coord coord = computeDirections(grid, r, c);
                int size = coord.starSize();
                if (size == 0) continue;               // not a centre of a star

                Coord centre = new Coord(r, c);
                Star star = new Star(centre, size);

                // Keep only the *largest* star for a given centre – eliminates duplicates
                stars.add(star);
            }
        }

        // Remove duplicate centres, preserving the star with the greatest size
        Map<Coord, Star> uniqueByCentre = stars.stream()
                .collect(Collectors.toMap(s -> s.centre, s -> s,
                        (existing, replacement) -> existing.size > replacement.size ? existing : replacement));

        return new ArrayList<>(uniqueByCentre.values());
    }

    /** --------------------------------------------------------------------- */
    /** Compute the four directional lengths (up, down, left, right) for a cell. */
    private static Coord computeDirections(char[][] grid, int r, int c) {
        int up = 0;
        while (r - up - 1 >= 0 && grid[r - up - 1][c] == '*') up++;

        int down = 0;
        while (r + down + 1 < grid.length && grid[r + down + 1][c] == '*') down++;

        int left = 0;
        while (c - left - 1 >= 0 && grid[r][c - left - 1] == '*') left++;

        int right = 0;
        while (c + right + 1 < grid[0].length && grid[r][c + right + 1] == '*') right++;

        Coord coord = new Coord(r, c);
        coord.up = up;
        coord.down = down;
        coord.left = left;
        coord.right = right;
        return coord;
    }

    /** --------------------------------------------------------------------- */
    /** Validate coverage and prepare the final output (either -1 or the list). */
    private static void handleResult(Result result, int rows, int cols) throws IOException {
        if (result instanceof Failure) {
            System.out.println(-1);
            return;
        }

        List<Star> stars = ((Success) result).stars;
        StringBuilder out = new StringBuilder();
        out.append(stars.size()).append('\n');
        for (Star s : stars) {
            out.append(s.centre).append(' ').append(s.size).append('\n');
        }
        System.out.print(out.toString());
    }

    /** --------------------------------------------------------------------- */
    /** Validate that every '*' belongs to at least one discovered star. */
    private static Result validateAndPrepareOutput(List<Star> stars,
                                                    int rows,
                                                    int cols) {
        boolean[][] covered = new boolean[rows][cols];

        // mark all cells that belong to any star
        for (Star s : stars) {
            s.markCovered(covered);
        }

        // check whether any original '*' remained uncovered
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '*' && !covered[r][c]) {
                    return new Failure();   // not all '*' are covered → impossible
                }
            }
        }

        // Sort stars for deterministic output (e.g., increasing centre, then size)
        List<Star> sortedStars = stars.stream()
                .sorted(Comparator.comparing(s -> s.centre.row)
                        .thenComparing(s -> s.centre.col)
                        .thenComparingInt(s -> s.size))
                .collect(Collectors.toList());

        return buildResult(sortedStars);
    }
}

/**
 * Refactored version of the original `a` class.
 * The program reads a grid of characters, identifies “plus” patterns,
 * records their centers and arm lengths, validates that every cell
 * belonging to a plus is marked as covered, and finally outputs the
 * number of pluses together with their positions (1‑based) and arm
 * length.
 *
 * The refactor focuses on readability, maintainability and correctness
 * of the structure while preserving the original behaviour.
 */
public class PlusPatternFinder {

    /** Simple container for a found plus pattern. */
    private static final class Tuple implements Comparable<Tuple> {
        /** Row index (1‑based) of the plus centre. */
        final int row;
        /** Column index (1‑based) of the plus centre. */
        final int col;
        /** Length of one arm (number of steps from centre to the edge). */
        final int armLength;

        Tuple(int row, int col, int armLength) {
            this.row = row;
            this.col = col;
            this.armLength = armLength;
        }

        @Override
        public int compareTo(Tuple other) {
            if (other.col != col) {
                return Integer.compare(other.col, col);
            }
            return Integer.compare(other.row, row);
        }
    }

    /** Helper class that bundles input reading and output writing. */
    private static final class FastScanner {
        private final java.io.BufferedReader reader;

        FastScanner() {
            this.reader = new java.io.BufferedReader(
                    new java.io.InputStreamReader(System.in)
            );
        }

        /** Reads the next token (word) from the input. */
        String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new java.util.StringTokenizer(reader.readLine());
                } catch (java.io.IOException e) {
                    throw new UncheckedIOException(e);
                }
            }
            return tokenizer.nextToken();
        }

        /** Reads the next integer from the input. */
        int nextInt() {
            return Integer.parseInt(next());
        }

        /** Reads a whole line (used for reading grid rows). */
        String readLine() {
            try {
                return reader.readLine();
            } catch (java.io.IOException e) {
                throw new UncheckedIOException(e);
            }
        }

        // Cached tokenizer to avoid repeated allocations.
        private java.util.StringTokenizer tokenizer;
    }

    /** Entry point of the program. */
    public static void main(String[] args) throws java.io.IOException {
        try (FastScanner scanner = new FastScanner();
             java.io.PrintWriter printer = new java.io.PrintWriter(
                     new java.io.BufferedWriter(
                             new java.io.OutputStreamWriter(System.out)
                     )
             )
        ) {
            // According to the original code only a single test case is processed.
            // The loop keeps the same semantics but is left here for extensibility.
            int testCount = scanner.nextInt();               // expected to be 1
            for (int t = 0; t < testCount; t++) {
                solve(testCount, scanner, printer);
            }
            printer.flush();
        }
    }

    /**
     * Core logic that processes one test case.
     *
     * @param testNumber dummy identifier kept for compatibility with the original API
     * @param scanner    input scanner
     * @param printer    output printer
     */
    private static void solve(int testNumber, FastScanner scanner, java.io.PrintWriter printer) {
        int rows = scanner.nextInt();   // n
        int cols = scanner.nextInt();   // m
        boolean[][] original = new boolean[rows][cols];
        readGrid(scanner, original, rows, cols);

        boolean[][] covered = new boolean[rows][cols];
        java.util.List<Tuple> pluses = new java.util.ArrayList<>();

        // Scan the grid for plus patterns.
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (!original[i][j]) {
                    continue;
                }
                // Try to extend a plus centred at (i, j).
                int armSteps = discoverPlus(original, covered, i, j);
                if (armSteps > 0) {
                    pluses.add(new Tuple(i + 1, j + 1, armSteps));
                }
            }
        }

        // Validate that every asterisk belongs to exactly one plus.
        if (!isFullCoverage(original, covered)) {
            printer.println(-1);
            return;
        }

        // Output results.
        printer.println(pluses.size());
        for (Tuple tpl : pluses) {
            printer.println(tpl.row + " " + tpl.col + " " + tpl.armLength);
        }
    }

    /**
     * Reads the remaining {@code rows} lines from {@code scanner} into {@code grid}.
     */
    private static void readGrid(FastScanner scanner,
                                 boolean[][] grid,
                                 int rows,
                                 int cols) {
        for (int r = 0; r < rows; r++) {
            String line = scanner.readLine();
            if (line == null) {
                throw new AssertionError("Unexpected end of input while reading grid.");
            }
            for (int c = 0; c < cols; c++) {
                grid[r][c] = line.charAt(c) == '*';
            }
        }
    }

    /**
     * Attempts to expand a plus centred at (centerRow, centerCol).
     * The method marks all cells belonging to a found plus in {@code covered}
     * and returns the arm length (0 if no plus is found).
     *
     * @return the number of steps each arm extends from the centre,
     *         or 0 if the centre cannot be the tip of a plus.
     */
    private static int discoverPlus(boolean[][] original,
                                    boolean[][] covered,
                                    int centerRow,
                                    int centerCol) {
        // The plus must have at least one cell in each direction.
        int maxPossible = Math.min(original.length, original[0].length);

        for (int step = 1; step < maxPossible; step++) {
            // Border positions of the cross.
            int up    = centerRow - step;
            int down  = centerRow + step;
            int left  = centerCol - step;
            int right = centerCol + step;

            // Verify that all required cells exist and contain an asterisk.
            boolean hasUp    = inBounds(original, up,     centerCol);
            boolean hasDown  = inBounds(original, down,   centerCol);
            boolean hasLeft  = inBounds(original, centerRow, left);
            boolean hasRight = inBounds(original, centerRow, right);
            boolean hasCenter = original[centerRow][centerCol];

            if (!hasCenter && (hasUp || hasDown || hasLeft || hasRight)) {
                // If the centre itself is not an asterisk we cannot start a plus.
                break;
            }
            if (!(hasUp && hasDown && hasLeft && hasRight)) {
                break;
            }

            // Mark the five cells belonging to this plus.
            markCovered(covered, centerRow,      centerCol,    step);
            markCovered(covered, up,            centerCol,    step);
            markCovered(covered, down,          centerCol,    step);
            markCovered(covered, centerRow,     left,         step);
            markCovered(covered, centerRow,     right,        step);

            // We have successfully extended the plus by one more step.
            // Continue scanning for a larger plus; the final step count is the arm length.
            // If we later break, the arm length will be step.
        }

        // The number of successfully executed steps equals the arm length.
        // The loop increments step until failure, so the arm length is step-1.
        return Math.max(0, maxPossible - 1);
    }

    /** Marks a cell as covered if it is within the bounds of {@code original}. */
    private static void markCovered(boolean[][] covered, int row, int col, int step) {
        if (inBounds(covered, row, col)) {
            covered[row][col] = true;
        }
    }

    /** Utility: checks whether (r, c) lies inside the matrix dimensions. */
    private static boolean inBounds(boolean[][] matrix, int r, int c) {
        return r >= 0 && r < matrix.length && c >= 0 && c < matrix[0].length;
    }

    /** Utility: checks whether every asterisk in the original grid is covered. */
    private static boolean isFullCoverage(boolean[][] original, boolean[][] covered) {
        for (int r = 0; r < original.length; r++) {
            for (int c = 0; c < original[0].length; c++) {
                if (original[r][c] && !covered[r][c]) {
                    return false;
                }
            }
        }
        return true;
    }
}

import java.io.IOException;
import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;

/**
 * Refactored solution for the “upright‑cross explosion” problem.
 *
 * <p>
 * The program reads an {@code n × m} board where '*' denotes a potential bomb
 * centre. It finds all maximal upright‑cross explosions (centre + four arms of
 * equal length) that are completely contained in '*' cells, prints the number
 * of such explosions and their locations/radii, or {@code -1} if any '*' cell
 * remains uncovered.
 * </p>
 */
public class Sol2 {

    /** Data holder for a single explosion. */
    private static final class Explosion {
        /** 1‑based row index of the explosion centre. */
        final int row;
        /** 1‑based column index of the explosion centre. */
        final int col;
        /** Length of each arm (radius) of the cross. */
        final int radius;

        Explosion(int row, int col, int radius) {
            this.row = row;
            this.col = col;
            this.radius = radius;
        }

        @Override
        public String toString() {
            return row + " " + col + " " + radius;
        }
    }

    /** Entry point – parses input, computes the answer and prints it. */
    public static void main(String[] args) throws IOException {
        try (Scanner sc = new Scanner(System.in)) {
            int n = sc.nextInt();
            int m = sc.nextInt();

            boolean[][] board = readBoard(sc, n, m);
            List<Explosion> explosions = findExplosions(board, n, m);
            boolean allCovered = validateCoverage(board, explosions, n, m);

            if (!allCovered) {
                System.out.println(-1);
                return;
            }

            System.out.println(explosions.size());
            for (Explosion e : explosions) {
                System.out.println(e);
            }
        }
    }

    /** Reads the board from the scanner. */
    private static boolean[][] readBoard(Scanner sc, int n, int m) {
        boolean[][] board = new boolean[n][m];
        for (int i = 0; i < n; i++) {
            String line = sc.next();
            for (int j = 0; j < m; j++) {
                board[i][j] = line.charAt(j) == '*';
            }
        }
        return board;
    }

    /**
     * Finds all maximal upright‑cross explosions that can be placed on the board.
     *
     * @return a list of {@link Explosion} objects representing the detected explosions.
     */
    private static List<Explosion> findExplosions(boolean[][] board, int n, int m) {
        List<Explosion> explosions = new ArrayList<>();

        for (int r = 1; r < n - 1; r++) {
            for (int c = 1; c < m - 1; c++) {
                if (!board[r][c]) {
                    continue;
                }

                // maximum possible radius for a cross centred at (r, c)
                int maxRadius = Math.min(r, Math.min(n - r - 1, Math.min(c, m - c - 1)));
                int bestRadius = 0;

                // expand radius while the cross stays inside '*' cells
                for (int k = 1; k <= maxRadius; k++) {
                    if (board[r + k][c] && board[r - k][c]
                            && board[r][c + k] && board[r][c - k]) {
                        bestRadius = k;               // keep the largest successful radius
                    } else {
                        break;                         // first failure stops further growth
                    }
                }

                if (bestRadius > 0) {
                    explosions.add(new Explosion(r + 1, c + 1, bestRadius)); // convert to 1‑based
                }
            }
        }
        return explosions;
    }

    /**
     * Checks whether every '*' cell on the board belongs to at least one explosion arm.
     *
     * @return {@code true} if full coverage is achieved, {@code false} otherwise.
     */
    private static boolean validateCoverage(boolean[][] board,
                                            List<Explosion> explosions,
                                            int n,
                                            int m) {
        // mark all cells covered by any explosion
        boolean[][] covered = new boolean[n][m];

        for (Explosion e : explosions) {
            int center = e.row - 1;          // back to zero‑based coordinates
            int radius = e.radius;

            // vertical arm (same column)
            for (int dr = -radius; dr <= radius; dr++) {
                int nr = center + dr;
                if (nr >= 0 && nr < n) {
                    covered[nr][center] = true;
                }
            }

            // horizontal arm (same row)
            for (int dc = -radius; dc <= radius; dc++) {
                int nc = center + dc;
                if (nc >= 0 && nc < m) {
                    covered[center][nc] = true;
                }
            }
        }

        // verify that every '*' is covered
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (board[i][j] && !covered[i][j]) {
                    return false;
                }
            }
        }
        return true;
    }
}

import java.io.*;
import java.util.ArrayList;
import java.util.List;
import java.util.StringTokenizer;

/**
 * Main driver for the solution.  It reads a binary matrix, finds all maximal
 * “cross‑shaped” patterns of 1’s, records their centers and radii, verifies that
 * the discovered pattern exactly matches the input, and finally prints the
 * result.
 */
public class Main {

    /** Upper bound for the search radius – safe default (1000). */
    private static final int MAX_RADIUS = 1000;

    /** Holds all discovered patterns; each pattern stores its centre and radius. */
    private static final class Pattern {
        final int row;
        final int col;
        final int radius;

        Pattern(int row, int col, int radius) {
            this.row = row;
            this.col = col;
            this.radius = radius;
        }

        @Override
        public String toString() {
            return row + " " + col + " " + radius;
        }
    }

    /** Encapsulates the solution logic for a single test case. */
    static class Solver {

        private final int rows;
        private final int cols;
        private final int[][] matrix;      // original binary matrix
        private final int[][] rowPrefix;    // cumulative row sums
        private final int[][] colPrefix;    // cumulative column sums
        private final List<Pattern> patterns = new ArrayList<>();

        Solver(int rows, int cols, int[][] matrix) {
            this.rows = rows;
            this.cols = cols;
            this.matrix = matrix;
            this.rowPrefix = buildRowPrefixes();
            this.colPrefix = buildColPrefixes();
        }

        /** Builds row‑wise prefix sums (size: rows × (cols+1)). */
        private int[][] buildRowPrefixes() {
            int[][] prefix = new int[rows][cols + 1];
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    prefix[r][c + 1] = prefix[r][c] + matrix[r][c];
                }
            }
            return prefix;
        }

        /** Builds column‑wise prefix sums (size: cols × (rows+1)). */
        private int[][] buildColPrefixes() {
            int[][] prefix = new int[cols][rows + 1];
            for (int c = 0; c < cols; c++) {
                for (int r = 0; r < rows; r++) {
                    prefix[c][r + 1] = prefix[c][r] + matrix[r][c];
                }
            }
            return prefix;
        }

        /**
         * Returns the sum of elements in {@code prefix}[from..to] (inclusive of {@code from},
         * exclusive of {@code to}) after checking bounds.
         */
        private int getPrefixSum(int[][] prefix, int from, int to) {
            if (from < 0 || to > prefix.length) {
                return 0;
            }
            return prefix[to - 1] - (from == 0 ? 0 : prefix[from - 1]);
        }

        /**
         * Binary‑searches the largest radius {@code k} such that the square centred at
         * (i, j) of side {@code 2k+1} contains only 1’s both row‑wise and column‑wise.
         */
        private int findMaxRadius(int rowSum[], int colSum[], int i, int j) {
            int lo = 0, hi = Math.min(i, j, rows - i - 1, cols - j - 1);
            int best = 0;

            while (lo <= hi) {
                int mid = (lo + hi) >>> 1; // avoid overflow
                int rowStart = j - mid;
                int rowEnd   = j + mid + 1; // exclusive
                int colStart = i - mid;
                int colEnd   = i + mid + 1; // exclusive

                int rowSumMid = getPrefixSum(rowPrefix[i], rowStart, rowEnd);
                int colSumMid = getPrefixSum(colPrefix[j], colStart, colEnd);

                if (rowSumMid == 2 * mid + 1 && colSumMid == 2 * mid + 1) {
                    best = mid;          // mid works – try larger
                    lo = mid + 1;
                } else {
                    hi = mid - 1;        // too large – shrink
                }
            }
            return best;
        }

        /** Finds all patterns in the matrix. */
        private List<Pattern> discoverPatterns() {
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (matrix[r][c] == 1) {
                        int radius = findMaxRadius(rowPrefix[r], colPrefix[c], r, c);
                        if (radius > 0) {
                            patterns.add(new Pattern(r, c, radius));
                            // Register the inverse influence (used later for reconstruction)
                            addInverseInfluence(r, c, radius);
                        }
                    }
                }
            }
            return patterns;
        }

        /** Stores delta changes for later reconstruction of the mask matrix. */
        private void addInverseInfluence(int centreRow, int centreCol, int radius) {
            // horizontal strip
            rowPS[centreRow][centreCol + radius + 1]--;
            rowPS[centreRow][centreCol - radius]++;

            // vertical strip
            colPS[centreCol][centreRow + radius + 1]--;
            colPS[centreCol][centreRow - radius]++;
        }

        /** Reconstructs the mask matrix from the recorded delta changes. */
        private boolean reconstructMask(int[][] otMask, int[][] rowDelta, int[][] colDelta) {
            // Apply row deltas
            for (int r = 0; r < rows; r++) {
                int running = 0;
                for (int c = 0; c < cols; c++) {
                    running += rowDelta[r][c];
                    if (running > 0) {
                        otMask[r][c] = 1;
                    }
                }
            }

            // Apply column deltas – note that column deltas are stored transposed
            for (int c = 0; c < cols; c++) {
                int running = 0;
                for (int r = 0; r < rows; r++) {
                    running += colDelta[c][r];
                    if (running > 0) {
                        otMask[r][c] = 1;
                    }
                }
            }

            // Validate against the original matrix
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (otMask[r][c] == 1 && matrix[r][c] == 0) {
                        return false; // extra 1 where original is 0
                    }
                    if (otMask[r][c] == 0 && matrix[r][c] == 1) {
                        return false; // missing 1
                    }
                }
            }
            return true;
        }

        /** Solves the whole problem – ties everything together and prints the answer. */
        void solve(Scanner sc, PrintWriter pw) throws IOException {
            // ----- input ---------------------------------------------------------
            int n = sc.nextInt(); // rows
            int m = sc.nextInt(); // columns
            int[][] raw = new int[n][m];
            for (int i = 0; i < n; i++) {
                String line = sc.next();
                for (int j = 0; j < m; j++) {
                    raw[i][j] = line.charAt(j) == '.' ? 0 : 1;
                }
            }

            // ----- prefix construction -----------------------------------------
            this.rowPrefix = buildRowPrefixes();
            this.colPrefix = buildColPrefixes();

            // ----- discover patterns --------------------------------------------
            discoverPatterns();

            // ----- reconstruct mask matrix --------------------------------------
            int[][] otMask = new int[n][m];
            // temporary delta storage (same size as original matrix)
            rowPS = new int[n][m + 2];           // +2 to safely handle end indices
            colPS = new int[m][n + 2];
            // run reconstruction and validate
            boolean valid = reconstructMask(otMask, rowPS, colPS);

            // ----- output ---------------------------------------------------------
            if (!valid) {
                pw.println(-1);
            } else {
                pw.println(patterns.size());
                for (Pattern p : patterns) {
                    pw.println((p.row + 1) + " " + (p.col + 1) + " " + p.radius);
                }
            }
        }

        // ---------- fields used for reconstruction ---------------------------------
        private int[][] rowPS;   // horizontal delta for each row
        private int[][] colPS;   // vertical delta for each column
    }

    /** Fast scanner that works on token streams. */
    static class Scanner {
        private final StringTokenizer st;
        private final BufferedReader br;

        Scanner(InputStream source) {
            br = new BufferedReader(new InputStreamReader(source));
            st = null;
        }

        /** Returns the next token, expanding the tokeniser lazily. */
        private String nextToken() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                String line = br.readLine();
                if (line == null) return null;
                st = new StringTokenizer(line);
            }
            return st.nextToken();
        }

        String next() throws IOException { return nextToken(); }

        int nextInt() throws IOException { return Integer.parseInt(next()); }

        long nextLong() throws IOException { return Long.parseLong(next()); }

        String nextLine() throws IOException { return br.readLine(); }
    }

    /** Benchmark utilities – not part of the algorithmic core. */
    static long TIME_START, TIME_END;

    public static void main(String[] args) throws IOException {
        Scanner sc = new Scanner(System.in);
        PrintWriter pw = new PrintWriter(new BufferedOutputStream(System.out));

        Runtime runtime = Runtime.getRuntime();
        long usedBefore = runtime.totalMemory() - runtime.freeMemory();
        TIME_START = System.currentTimeMillis();

        new Solver(0, 0, new int[0][0]).solve(sc, pw); // actual data injected by Solver itself

        TIME_END = System.currentTimeMillis();
        long usedAfter = runtime.totalMemory() - runtime.freeMemory();

        pw.close();
        System.err.println("Memory increased: " + ((usedAfter - usedBefore) / 1_000_000) + " MB");
        System.err.println("Time used: " + (TIME_END - TIME_START) + " ms");
    }
}

import java.io.IOException;
import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;

/**
 * Refactored version of the original program.
 *
 * <p>The program reads a rectangular grid of characters, finds plus‑shaped
 * clusters of '*' and reports their centres and arm length. If any '*' remains
 * after all possible pluses are marked, it outputs {@code -1}.
 *
 * <p>The implementation is split into small, single‑purpose methods and uses
 * explicit data holder classes to improve readability and maintainability.
 */
public class Main {

    /** Holds the four directional run‑lengths for a cell. */
    private static final class DirectionStats {
        final int up;
        final int down;
        final int left;
        final int right;

        DirectionStats(int up, int down, int left, int right) {
            this.up = up;
            this.down = down;
            this.left = left;
            this.right = right;
        }
    }

    /** Result of a discovered plus: centre coordinates (0‑based) and arm length. */
    private static final class Placement {
        final int row;
        final int col;
        final int arm; // symmetric arm length (0‑based)

        Placement(int row, int col, int arm) {
            this.row = row;
            this.col = col;
            this.arm = arm;
        }
    }

    /** Entry point of the program. */
    public static void main(String[] args) throws IOException {
        try (Scanner scanner = new Scanner(System.in)) {
            int rows = scanner.nextInt();
            int cols = scanner.nextInt();
            char[][] grid = readGrid(scanner, rows, cols);

            DirectionStats[][] directionalStats = computeDirectionalStats(grid);
            List<Placement> placements = discoverPluses(grid, directionalStats);
            StringBuilder formattedOutput = formatResult(placements);

            if (stillContainsStar(grid)) {
                System.out.println(-1);
            } else {
                System.out.println(placements.size());
                System.out.print(formattedOutput);
            }
        }
    }

    /** Reads the matrix from {@code scanner}. */
    private static char[][] readGrid(Scanner scanner, int n, int m) {
        char[][] grid = new char[n][m];
        for (int i = 0; i < n; i++) {
            String line = scanner.next();
            for (int j = 0; j < m; j++) {
                grid[i][j] = line.charAt(j);
            }
        }
        return grid;
    }

    /** Computes the length of contiguous '*' in all four directions. */
    private static DirectionStats[][] computeDirectionalStats(char[][] grid) {
        int n = grid.length;
        int m = grid[0].length;
        DirectionStats[][] stats = new DirectionStats[n][m];

        // first pass: up & left (top‑left → bottom‑right)
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i][j] == '*') {
                    stats[i][j] = new DirectionStats(
                            (i > 0) ? stats[i - 1][j].up + 1 : 0,
                            0,
                            (j > 0) ? stats[i][j - 1].left + 1 : 0,
                            0);
                } else {
                    stats[i][j] = new DirectionStats(0, 0, 0, 0);
                }
            }
        }

        // second pass: down & right (bottom‑right → top‑left)
        for (int i = n - 1; i >= 0; i--) {
            for (int j = m - 1; j >= 0; j--) {
                if (grid[i][j] == '*') {
                    int down = (i + 1 < n) ? stats[i + 1][j].down + 1 : 0;
                    int right = (j + 1 < m) ? stats[i][j + 1].right + 1 : 0;
                    stats[i][j].down = down;
                    stats[i][j].right = right;
                }
            }
        }
        return stats;
    }

    /** Finds all pluses according to the original algorithm. */
    private static List<Placement> discoverPluses(char[][] grid,
                                                    DirectionStats[][] stats) {
        List<Placement> placements = new ArrayList<>();

        for (int i = 0; i < grid.length; i++) {
            for (int j = 0; j < grid[i].length; j++) {
                if (grid[i][j] != '*') {
                    continue;
                }

                int symmetricArm = Math.min(
                        Math.min(stats[i][j].up, stats[i][j].down),
                        Math.min(stats[i][j].left, stats[i][j].right));

                if (symmetricArm == 0) {
                    continue; // not a valid centre for a plus
                }

                markPlus(grid, i, j, symmetricArm);
                placements.add(new Placement(i, j, symmetricArm));
            }
        }
        return placements;
    }

    /** Marks a discovered plus with 'x' so it is not processed again. */
    private static void markPlus(char[][] grid, int centreRow, int centreCol, int arm) {
        // vertical line extending upward
        for (int r = centreRow; r >= centreRow - arm; r--) {
            grid[r][centreCol] = 'x';
        }
        // vertical line extending downward
        for (int r = centreRow; r <= centreRow + arm; r++) {
            grid[r][centreCol] = 'x';
        }
        // horizontal line extending to the left
        for (int c = centreCol; c >= centreCol - arm; c--) {
            grid[centreRow][c] = 'x';
        }
        // horizontal line extending to the right
        for (int c = centreCol; c <= centreCol + arm; c++) {
            grid[centreRow][c] = 'x';
        }
    }

    /** Formats the discovered placements as required. */
    private static StringBuilder formatResult(List<Placement> placements) {
        StringBuilder sb = new StringBuilder();
        for (Placement p : placements) {
            sb.append(p.row + 1)
              .append(' ')
              .append(p.col + 1)
              .append(' ')
              .append(p.arm)
              .append('\n');
        }
        return sb;
    }

    /** Checks whether any original '*' characters are still left. */
    private static boolean stillContainsStar(char[][] grid) {
        for (char[] row : grid) {
            for (char cell : row) {
                if (cell == '*') {
                    return true;
                }
            }
        }
        return false;
    }
}

import java.io.*;
import java.util.*;

/**
 * Refactored version of the original program.
 * The logic is unchanged – it reads a grid of characters,
 * determines the maximal “star‑plus” arms that can be placed,
 * and either prints the number of placed pluses together with
 * their centers and arm lengths or -1 if the configuration cannot
 * be completed.
 */
public class Main {

    /** Directions used for the four passes over the grid. */
    private enum Direction {
        UP, DOWN, LEFT, RIGHT
    }

    public static void main(String[] args) throws Exception {
        try (FastScanner scanner = new FastScanner(System.in);
             PrintWriter out = new PrintWriter(System.out)) {

            int rows = scanner.nextInt();
            int cols = scanner.nextInt();

            char[][] grid = new char[rows][cols];
            char[][] workingGrid = new char[rows][cols];

            for (int r = 0; r < rows; r++) {
                grid[r] = scanner.next().toCharArray();
                Arrays.fill(workingGrid[r], '.');
            }

            int[][] maxArmLength = computeMaximumArmLength(grid, rows, cols);

            boolean configurationValid = rebuildGridWithArms(
                    grid, workingGrid, maxArmLength, rows, cols);

            if (configurationValid) {
                printSolution(out, maxArmLength);
            } else {
                out.println(-1);
            }
        }
    }

    /**
     * Computes, for each cell, the minimum of the four directional
     * star‑counts that end at that cell. The result represents the
     * maximal arm length of a plus that can be centred at the cell.
     */
    private static int[][] computeMaximumArmLength(
            char[][] grid, int n, int m) {

        int[][] maxArm = new int[n][m];

        // vertical passes (up & down)
        for (int r = 0; r < n; r++) {
            fillVerticalCounts(grid, maxArm, Direction.UP, r, true);
            fillVerticalCounts(grid, maxArm, Direction.DOWN, r, false);
        }

        // horizontal passes (left & right)
        for (int c = 0; c < m; c++) {
            fillHorizontalCounts(grid, maxArm, Direction.LEFT, c, true);
            fillHorizontalCounts(grid, maxArm, Direction.RIGHT, c, false);
        }

        return maxArm;
    }

    /** Helper that fills counts for the upward direction. */
    private static void fillVerticalCounts(char[][] grid, int[][] maxArm,
                                            Direction dir, int row, boolean forward) {
        int count = -1;
        int step = forward ? 1 : -1;

        for (int r = forward ? 0 : n - 1; ; r += step) {
            int limit = forward ? Math.min(row + 1, n) : Math.max(row - 1, -1);
            if ((forward && r > row) || (!forward && r < row)) {
                break;
            }
            if (grid[r][col] == '*') {
                count++;
            } else {
                count = -1;
            }
            maxArm[r][col] = Math.min(maxArm[r][col], count);
        }
    }

    /** Helper that fills counts for the leftward direction. */
    private static void fillHorizontalCounts(char[][] grid, int[][] maxArm,
                                            Direction dir, int col, boolean forward) {
        int count = -1;
        int step = forward ? 1 : -1;

        for (int c = forward ? 0 : m - 1; ; c += step) {
            int limit = forward ? Math.min(col + 1, m) : Math.max(col - 1, -1);
            if ((forward && c > col) || (!forward && c < col)) {
                break;
            }
            if (grid[row][c] == '*') {
                count++;
            } else {
                count = -1;
            }
            maxArm[row][c] = Math.min(maxArm[row][c], count);
        }
    }

    /**
     * Attempts to reconstruct the grid by placing pluses whose arm
     * length equals the corresponding value in {@code maxArm}.
     * Returns {@code true} if the reconstruction exactly matches the
     * original pattern, otherwise {@code false}.
     */
    private static boolean rebuildGridWithArms(
            char[][] original, char[][] result, int[][] maxArm,
            int n, int m) {

        int plusCount = 0;
        StringBuilder log = new StringBuilder();

        for (int r = 0; r < n; r++) {
            for (int c = 0; c < m; c++) {
                if (original[r][c] != '*' || maxArm[r][c] < 1) {
                    continue;
                }

                plusCount++;
                result[r][c] = '*';
                int arm = maxArm[r][c];
                for (int d = 1; d <= arm; d++) {
                    result[r - d][c] = '*';
                    result[r + d][c] = '*';
                    result[r][c - d] = '*';
                    result[r][c + d] = '*';
                }
                log.append(r + 1)
                   .append(' ')
                   .append(c + 1)
                   .append(' ')
                   .append(arm)
                   .append('\n');
            }
        }

        // Verify that the reconstructed grid matches the expected pattern
        boolean isValid = true;
        for (int r = 0; r < n && isValid; r++) {
            for (int c = 0; c < m; c++) {
                if (original[r][c] != result[r][c]) {
                    isValid = false;
                    break;
                }
            }
        }

        if (isValid) {
            System.out.print(log.toString());   // `out` is used in the caller
            System.out.println(plusCount);
        }

        return isValid;
    }

    /**
     * Prints the collected log of plus placements.
     * (In this refactor the logging is done directly in {@code rebuildGridWithArms}
     * but the method is kept for future extensions.)
     */
    private static void printSolution(PrintWriter out, int[][] maxArm) {
        // Placeholder – actual listing is produced during reconstruction.
    }
}

/**
 * Simple fast scanner based on {@link BufferedReader}.
 * Keeps the original behaviour but with clearer naming.
 */
class FastScanner {
    private final BufferedReader reader;
    private StringTokenizer tokenizer;

    FastScanner(InputStream in) {
        this.reader = new BufferedReader(new InputStreamReader(in));
    }

    String next() {
        return nextToken();
    }

    String nextToken() {
        if (tokenizer == null || !tokenizer.hasMoreTokens()) {
            try {
                tokenizer = new StringTokenizer(reader.readLine());
            } catch (IOException e) {
                throw new UncheckedIOException(e);
            }
        }
        return tokenizer.nextToken();
    }

    String nextLine() {
        if (tokenizer != null && tokenizer.hasMoreTokens()) {
            return tokenizer.nextToken("\n");
        }
        try {
            return reader.readLine();
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
    }

    long nextLong() {
        return Long.parseLong(next());
    }

    int nextInt() {
        return Integer.parseInt(next());
    }

    double nextDouble() {
        return Double.parseDouble(next());
    }

    /* Convenience methods for bulk reading – unchanged from original */
    public String[] nextArray(int n) {
        String[] a = new String[n];
        for (int i = 0; i < n; i++) {
            a[i] = next();
        }
        return a;
    }

    public int[] nextIntArray(int n) {
        int[] a = new int[n];
        for (int i = 0; i < n; i++) {
            a[i] = nextInt();
        }
        return a;
    }

    public long[] nextLongArray(int n) {
        long[] a = new long[n];
        for (int i = 0; i < n; i++) {
            a[i] = nextLong();
        }
        return a;
    }
}

import java.io.*;
import java.util.*;
import java.util.stream.*;

public class Main {

    /** Star shape that can be drawn on the grid */
    private static final class Star {
        final int row;
        final int col;
        final int size; // half‑length of each arm

        Star(int row, int col, int size) {
            this.row = row;
            this.col = col;
            this.size = size;
        }

        @Override
        public String toString() {
            return row + " " + col + " " + size;
        }
    }

    /** Fast scanner / tokeniser used in competitive programming */
    private static final class Kattio {
        private final BufferedReader reader;
        private String line;
        private StringTokenizer tokenizer;

        Kattio(InputStream input) {
            this.reader = new BufferedReader(new InputStreamReader(input));
            this.tokenizer = null;
            this.line = null;
        }

        /** Lazily fetch the next token */
        private String peekToken() {
            if (tokenizer == null) {
                try {
                    while (line == null || !tokenizer.hasMoreTokens()) {
                        line = reader.readLine();
                        if (line == null) return null;
                        tokenizer = new StringTokenizer(line);
                    }
                } catch (IOException e) {
                    throw new UncheckedIOException(e);
                }
            }
            return tokenizer.nextToken();
        }

        /** Return the next token and discard it */
        private String nextToken() {
            String token = peekToken();
            if (token == null) tokenizer = null;
            return token;
        }

        int nextInt() {
            return Integer.parseInt(nextToken());
        }

        String next() {
            return nextToken();
        }

        void close() {
            try {
                reader.close();
            } catch (IOException e) {
                throw new UncheckedIOException(e);
            }
        }
    }

    /** Core logic – solves the problem */
    private static final class Solver {

        /** Minimum allowed size for a star (the problem requires size ≥ 1) */
        private static final int MIN_SIZE = 1;

        /** Entry point called from `main` */
        void solve(Kattio in, PrintWriter out) {
            int n = in.nextInt(); // rows
            int m = in.nextInt(); // columns

            char[][] grid = readGrid(in, n, m);

            // 2‑D difference arrays that will hold row‑ and column‑wise coverage
            int[][][] diffRow = new int[n + 4][m + 4];
            int[][][] diffCol = new int[n + 4][m + 4];

            // auxiliary structures that store the nearest '*' in each direction
            int[][][] nearestLeft  = new int[n + 4][m + 4][2];
            int[][][] nearestRight = new int[n + 4][m + 4][2];
            int[][][] nearestUp    = new int[n + 4][m + 4][2];
            int[][][] nearestDown  = new int[n + 4][m + 4][2];

            initDirectionArrays(nearestLeft, nearestRight, nearestUp, nearestDown);

            fillDirectionInfo(grid, nearestLeft, nearestRight, nearestUp, nearestDown);

            // Build prefix‑sum coverage from the stars we decide to draw
            buildCoverageArrays(grid, nearestLeft, nearestRight, nearestUp, nearestDown,
                                diffRow, diffCol);

            // Verify that every '*' is covered by at least one arm of some star
            if (!allStarsCovered(grid, diffRow, diffCol)) {
                out.println(-1);
                return;
            }

            // Collect the stars that were used
            List<Star> stars = collectStars(grid, nearestLeft, nearestRight,
                                            nearestUp, nearestDown);

            // Output
            out.println(stars.size());
            stars.forEach(out::println);
        }

        /** Reads the grid from the input stream, padding it with '.' around the edges */
        private static char[][] readGrid(Kattio in, int n, int m) {
            char[][] grid = new char[n + 2][m + 2];
            // Pad with '.' to avoid boundary checks
            for (int i = 0; i <= n + 1; i++) {
                Arrays.fill(grid[i], '.');
            }
            for (int j = 0; j <= m + 1; j++) {
                grid[0][j] = grid[n + 1][j] = '.';
            }

            for (int i = 1; i <= n; i++) {
                String row = in.next();
                Arrays.fill(grid[i], '.');
                for (int j = 1; j <= m; j++) {
                    grid[i][j] = row.charAt(j - 1);
                }
            }
            return grid;
        }

        /** Fill the four direction arrays with sentinel -1 */
        private static void initDirectionArrays(int[][][] left,
                                                int[][][] right,
                                                int[][][] up,
                                                int[][][] down) {
            for (int[][][] arr : List.of(left, right, up, down)) {
                for (int[][] row : arr) {
                    Arrays.fill(row, -1);
                }
            }
        }

        /** Compute nearest '*' positions in all four directions */
        private static void fillDirectionInfo(char[][] grid,
                                              int[][][] left,
                                              int[][][] right,
                                              int[][][] up,
                                              int[][][] down) {
            // Propagation from left → right, top → bottom
            for (int i = 1; i < grid.length - 1; i++) {
                for (int j = 1; j < grid[0].length - 1; j++) {
                    if (grid[i][j] == '*') {
                        // horizontal: leftmost column of a continuous '*'
                        left[i][j][0] = j;
                        if (grid[i][j - 1] == '*') {
                            left[i][j][0] = left[i][j - 1][0];
                        }

                        // vertical: topmost row of a continuous '*'
                        up[i][j][2] = i;
                        if (grid[i - 1][j] == '*') {
                            up[i][j][2] = up[i - 1][j][2];
                        }
                    }
                }
            }

            // Propagation from right → left, bottom → top
            for (int i = grid.length - 2; i >= 1; i--) {
                for (int j = grid[0].length - 2; j >= 1; j--) {
                    if (grid[i][j] == '*') {
                        right[i][j][1] = j;
                        if (grid[i][j + 1] == '*') {
                            right[i][j][1] = right[i][j + 1][1];
                        }

                        down[i][j][3] = i;
                        if (grid[i + 1][j] == '*') {
                            down[i][j][3] = down[i + 1][j][3];
                        }
                    }
                }
            }
        }

        /** Convert star definitions into a 2‑D difference representation of coverage */
        private static void buildCoverageArrays(char[][] grid,
                                                int[][][] left,
                                                int[][][] right,
                                                int[][][] up,
                                                int[][][] down,
                                                int[][][] diffRow,
                                                int[][][] diffCol) {
            for (int i = 1; i < grid.length - 1; i++) {
                for (int j = 1; j < grid[0].length - 1; j++) {
                    if (grid[i][j] != '*') continue;

                    int leftDist  = j - left[i][j][0];
                    int rightDist = right[i][j][1] - j;
                    int upDist    = i - up[i][j][2];
                    int downDist  = down[i][j][3] - i;

                    int size = Math.min(Math.min(leftDist, rightDist), Math.min(upDist, downDist));
                    if (size < MIN_SIZE) continue; // star must have at least size 1

                    // Horizontal coverage update (difference on rows)
                    diffRow[i][j - size][0] += 1;
                    diffRow[i][j + size + 1][0] -= 1;

                    // Vertical coverage update (difference on columns)
                    diffCol[i - size][j][1] += 1;
                    diffCol[i + size + 1][j][1] -= 1;
                }
            }

            // Transform differences into prefix sums
            for (int i = 1; i < diffRow.length; i++) {
                for (int j = 1; j < diffRow[0].length; j++) {
                    diffRow[i][j][0] += diffRow[i][j - 1][0]; // row coverage
                    diffCol[i][j][1] += diffCol[i - 1][j][1]; // column coverage
                }
            }
        }

        /** Check that every '*' has received at least one coverage contribution */
        private static boolean allStarsCovered(char[][] grid,
                                                int[][][] diffRow,
                                                int[][][] diffCol) {
            for (int i = 1; i < grid.length - 2; i++) {
                for (int j = 1; j < grid[0].length - 2; j++) {
                    int rowCoverage = diffRow[i][j][0];
                    int colCoverage = diffCol[i][j][1];
                    if (grid[i][j] == '*' && (rowCoverage + colCoverage) == 0) {
                        return false; // uncovered star → impossible to solve
                    }
                }
            }
            return true;
        }

        /** Gather all stars that satisfy the size requirement */
        private static List<Star> collectStars(char[][] grid,
                                               int[][][] left,
                                               int[][][] right,
                                               int[][][] up,
                                               int[][][] down) {
            List<Star> result = new ArrayList<>();
            for (int i = 1; i < grid.length - 2; i++) {
                for (int j = 1; j < grid[0].length - 2; j++) {
                    if (grid[i][j] != '*') continue;

                    int leftDist  = j - left[i][j][0];
                    int rightDist = right[i][j][1] - j;
                    int upDist    = i - up[i][j][2];
                    int downDist  = down[i][j][3] - i;

                    int size = Math.min(Math.min(leftDist, rightDist),
                                        Math.min(upDist, downDist));
                    if (size > 0) {
                        result.add(new Star(i, j, size));
                    }
                }
            }
            return result;
        }
    }

    /** Program entry point */
    public static void main(String[] args) {
        try (Kattio in = new Kattio(System.in)) {
            Solver solver = new Solver();
            solver.solve(in, new PrintWriter(System.out, true));
            in.close();
        }
    }
}

package stars_drawing_easy;

import java.io.*;
import java.util.*;

/**
 * Reads a grid that contains only '*' and '.'.
 * The task is to cover every '*' with disjoint plus‑signs.
 * A plus‑sign is defined by its centre (row, col) and a radius r ≥ 1,
 * i.e. the centre together with r cells up, down, left and right.
 *
 * If every '*' can be covered, the program prints all plus‑signs
 * (centre 1‑based, radius) in the order they were discovered.
 * Otherwise it prints -1.
 */
public class StarsDrawingEasy {

    /** Input helper – thin wrapper around BufferedReader. */
    private static final class FastIO {
        private final BufferedReader br;
        private StringTokenizer st;

        FastIO() {
            this.br = new BufferedReader(new InputStreamReader(System.in));
        }

        /** Returns next non‑empty token. */
        private String nextToken() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    throw new UncheckedIOException(e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(nextToken());
        }

        char[] nextCharArray() {
            return nextToken().toCharArray();
        }
    }

    /** Simple container for a discovered plus‑sign. */
    private static final class Placement {
        final int row;   // 0‑based centre row
        final int col;   // 0‑based centre column
        final int radius; // non‑negative radius (>=1 if a plus exists)

        Placement(int row, int col, int radius) {
            this.row = row;
            this.col = col;
            this.radius = radius;
        }
    }

    /** Directions used to investigate the arms of a plus. */
    private static final int[] DR = { -1, 0, 1, 0 };
    private static final int[] DC = { 0, -1, 0, 1 };

    /**
     * Finds all disjoint plus‑signs in the grid.
     *
     * @param grid      input characters
     * @param used      marks cells that already belong to a plus
     * @return list of placements discovered (empty if none)
     */
    private static List<Placement> discoverPlacements(char[][] grid, boolean[][] used) {
        int n = grid.length;
        int m = grid[0].length;
        List<Placement> placements = new ArrayList<>();

        for (int r = 1; r < n - 1; r++) {
            for (int c = 1; c < m - 1; c++) {
                if (!isPossiblePlus(grid, used, r, c)) {
                    continue;
                }

                // Determine the maximal radius that still respects '*' cells
                int radius = computeRadius(grid, r, c);
                if (radius == 0) {
                    continue; // not a valid plus
                }

                placements.add(new Placement(r, c, radius));
                markUsed(grid, used, r, c, radius);
                // After marking we start the search from the beginning again
                // to guarantee we do not miss placements that overlap partially.
                return discoverPlacements(grid, used);
            }
        }
        return placements;
    }

    /** Checks whether a plus centred at (r,c) can be placed without re‑using cells. */
    private static boolean isPossiblePlus(char[][] grid, boolean[][] used, int r, int c) {
        // centre must be '*'
        if (grid[r][c] != '*') {
            return false;
        }
        // all four adjacent cells must be '*'
        if (grid[r - 1][c] != '*' || grid[r + 1][c] != '*' ||
            grid[r][c - 1] != '*' || grid[r][c + 1] != '*') {
            return false;
        }
        // centre itself must not have been used yet
        return !used[r][c];
    }

    /**
     * Computes the maximal radius of a plus centred at (r,c).
     *
     * @return maximal radius (0 means no valid plus)
     */
    private static int computeRadius(char[][] grid, int r, int c) {
        int up = countConsecutiveUp(grid, r, c);
        int down = countConsecutiveDown(grid, r, c);
        int left = countConsecutiveLeft(grid, r, c);
        int right = countConsecutiveRight(grid, r, c);
        return Math.min(Math.min(up, down), Math.min(left, right));
    }

    private static int countConsecutiveUp(char[][] grid, int r, int c) {
        int cnt = 0;
        for (int i = r - 1; i >= 0 && grid[i][c] == '*'; i--) {
            cnt++;
        }
        return cnt;
    }

    private static int countConsecutiveDown(char[][] grid, int r, int c) {
        int cnt = 0;
        for (int i = r + 1; i < grid.length && grid[i][c] == '*'; i++) {
            cnt++;
        }
        return cnt;
    }

    private static int countConsecutiveLeft(char[][] grid, int r, int c) {
        int cnt = 0;
        for (int j = c - 1; j >= 0 && grid[r][j] == '*'; j--) {
            cnt++;
        }
        return cnt;
    }

    private static int countConsecutiveRight(char[][] grid, int r, int c) {
        int cnt = 0;
        for (int j = c + 1; j < grid[0].length && grid[r][j] == '*'; j++) {
            cnt++;
        }
        return cnt;
    }

    /** Marks all cells belonging to a plus of given radius as used. */
    private static void markUsed(char[][] grid, boolean[][] used, int r, int c, int radius) {
        // centre is always used
        used[r][c] = true;

        // arm up
        for (int i = 1; i <= radius; i++) {
            used[r - i][c] = true;
        }
        // arm down
        for (int i = 1; i <= radius; i++) {
            used[r + i][c] = true;
        }
        // arm left
        for (int i = 1; i <= radius; i++) {
            used[r][c - i] = true;
        }
        // arm right
        for (int i = 1; i <= radius; i++) {
            used[r][c + i] = true;
        }
    }

    /** Verifies that every '*' in the grid has been covered by a plus. */
    private static boolean allStarsCovered(char[][] grid, boolean[][] used) {
        for (int i = 0; i < grid.length; i++) {
            for (int j = 0; j < grid[i].length; j++) {
                if (grid[i][j] == '*' && !used[i][j]) {
                    return false;
                }
            }
        }
        return true;
    }

    /** Main driver – reads input, solves the problem, prints the answer. */
    public static void main(String[] args) throws Exception {
        try (FastIO io = new FastIO()) {
            int n = io.nextInt();
            int m = io.nextInt();
            char[][] grid = new char[n][];
            for (int i = 0; i < n; i++) {
                grid[i] = io.nextCharArray();
            }

            boolean[][] used = new boolean[n][m];
            List<Placement> placements = discoverPlacements(grid, used);

            if (allStarsCovered(grid, used)) {
                System.out.println(placements.size());
                for (Placement p : placements) {
                    // Output is 1‑based row/col as required by the original problem
                    System.out.printf("%d %d %d%n", p.row + 1, p.col + 1, p.radius);
                }
            } else {
                System.out.println(-1);
            }
        }
    }
}

import java.io.*;
import java.util.*;

public class Solution {

    /** Switch to read from STDIN (`true`) or from a file pair (`false`). */
    private static final boolean USE_STDIN = true;

    private static FastScanner scanner;
    private static PrintWriter writer;

    public static void main(String[] args) throws IOException {
        if (USE_STDIN) {
            scanner = new FastScanner();
            writer = new PrintWriter(new OutputStreamWriter(System.out));
        } else {
            scanner = new FastScanner("input");
            writer = new PrintWriter(new FileWriter("input.out"));
        }

        Solver solver = new Solver();
        solver.solve(scanner, writer);
        writer.close();
    }

    /** Represents a discovered cross‑shaped figure (a star). */
    private static final class Star {
        final int row;          // centre row (0‑based)
        final int col;          // centre column (0‑based)
        final int size;         // length of each arm (positive if a cross exists)

        Star(int row, int col, int size) {
            this.row = row;
            this.col = col;
            this.size = size;
        }
    }

    /** Core algorithm implementation. */
    private static class Solver {

        /** Solve the problem using the supplied scanner and writer. */
        void solve(FastScanner in, PrintWriter out) {
            int n = in.ni();                 // number of rows
            int m = in.ni();                 // number of columns

            // ----- read the grid -------------------------------------------------
            boolean[][] grid = new boolean[n][m];
            for (int r = 0; r < n; r++) {
                String line = in.nt();
                for (int c = 0; c < m; c++) {
                    grid[r][c] = line.charAt(c) == '*';
                }
            }

            // ----- detection of crosses -----------------------------------------
            boolean[][] visitedCross = new boolean[n][m];
            List<Star> stars = new ArrayList<>();

            for (int r = 0; r < n; r++) {
                for (int c = 0; c < m; c++) {
                    if (!grid[r][c]) {
                        continue;                     // not a potential centre
                    }

                    // maximal arm length that fits inside the matrix
                    int maxArm = Math.min(Math.min(n - r - 1, m - c - 1),
                                          Math.min(r, c));

                    int armLen = 0;
                    for (int d = 1; d <= maxArm; d++) {
                        if (!grid[r][c + d] || !grid[r][c - d]
                                || !grid[r + d][c] || !grid[r - d][c]) {
                            break;                       // cross broken at this distance
                        }
                        visitedCross[r][c + d] = true;
                        visitedCross[r][c - d] = true;
                        visitedCross[r + d][c] = true;
                        visitedCross[r - d][c] = true;
                        armLen = d;                       // current valid distance
                    }

                    if (armLen > 0) {
                        visitedCross[r][c] = true;      // centre itself belongs to the cross
                        stars.add(new Star(r, c, armLen));
                    }
                }
            }

            // ----- validation ----------------------------------------------------
            boolean allCovered = true;
            for (int r = 0; r < n; r++) {
                for (int c = 0; c < m; c++) {
                    if (grid[r][c] && !visitedCross[r][c]) {
                        allCovered = false;
                        break;
                    }
                }
                if (!allCovered) {
                    break;
                }
            }

            // ----- output --------------------------------------------------------
            if (allCovered) {
                out.println(stars.size());
                for (Star s : stars) {
                    // The problem expects 1‑based indices
                    out.printf("%d %d %d%n", s.row + 1, s.col + 1, s.size);
                }
            } else {
                out.println(-1);
            }
        }

        // -----------------------------------------------------------------------
        // Utility mathematical helpers (kept for completeness; currently unused)
        // -----------------------------------------------------------------------
        private static long gcd(long a, long b) {
            return b == 0 ? a : gcd(b % a, a);
        }

        private static long lcm(long a, long b) {
            return a * (b / gcd(a, b));
        }

        private static long pow(long base, long exp) {
            long result = 1;
            long cur = base % MOD;
            while (exp > 0) {
                if ((exp & 1) == 1) {
                    result = (result * cur) % MOD;
                }
                cur = (cur * cur) % MOD;
                exp >>= 1;
            }
            return result;
        }
    }

    /** Fast scanner that supports the operations used by the program. */
    private static class FastScanner {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        FastScanner() {
            reader = new BufferedReader(new InputStreamReader(System.in));
        }

        FastScanner(String filename) {
            try {
                reader = new BufferedReader(new FileReader(filename));
            } catch (FileNotFoundException e) {
                throw new RuntimeException(e);
            }
        }

        /** Return the next token as a String. */
        private String nextToken() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new UncheckedIOException(e);
                }
            }
            return tokenizer.nextToken();
        }

        /** Integer token. */
        int ni() {
            return Integer.parseInt(nextToken());
        }

        /** Long integer token. */
        long nl() {
            return Long.parseLong(nextToken());
        }

        /** Double token. */
        double nd() {
            return Double.parseDouble(nextToken());
        }

        /** String token (used for reading whole grid rows). */
        String nt() {
            return nextToken();
        }
    }
}

import java.io.IOException;
import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;

/**
 * Solves the “cross guard” problem.
 *
 * <p>
 *   The algorithm scans every interior cell that contains a '*'. For each such cell it
 *   determines the smallest arm length that can be extended in all four directions
 *   while staying on '*' cells. That length becomes the size of a guard placed at the
 *   current position. All cells covered by the guard are marked, and at the end we
 *   verify that every '*' in the grid has been covered. If any '*' remains uncovered,
 *   the solution prints -1; otherwise it prints the number of guards and their
 *   positions (1‑based) together with their size.
 * </p>
 */
public class Main {

    /** Represents a guard placement: row and column (1‑based) and the size of the cross. */
    private static final class Guard {
        private final int row;   // 1‑based output coordinate
        private final int col;   // 1‑based output coordinate
        private final int size;  // length of each arm of the cross

        Guard(int row, int col, int size) {
            this.row = row;
            this.col = col;
            this.size = size;
        }

        int getRow() { return row; }
        int getCol() { return col; }
        int getSize() { return size; }
    }

    /** Directions used to explore the four arms of a potential guard. */
    private enum Direction {
        DOWN(1, 0),
        LEFT(0, -1),
        UP(-1, 0),
        RIGHT(0, 1);

        final int dr;
        final int dc;

        Direction(int dr, int dc) {
            this.dr = dr;
            this.dc = dc;
        }

        /**
         * Returns the length of consecutive '*' cells starting from (r,c) moving in this direction.
         */
        int armLength(char[][] grid, int r, int c) {
            int length = 0;
            int rows = grid.length;
            int cols = grid[0].length;
            int nr = r + dr;
            int nc = c + dc;
            while (isInside(grid, nr, nc) && grid[nr][nc] == '*') {
                length++;
                nr += dr;
                nc += dc;
            }
            return length;
        }

        private boolean isInside(char[][] grid, int r, int c) {
            return r >= 0 && r < grid.length && c >= 0 && c < grid[0].length;
        }
    }

    public static void main(String[] args) throws IOException {
        // -----------------------------------------------------------------------
        // Input handling
        // -----------------------------------------------------------------------
        try (Scanner scanner = new Scanner(System.in)) {
            int rows = scanner.nextInt();
            int cols = scanner.nextInt();
            char[][] grid = new char[rows][];
            for (int i = 0; i < rows; i++) {
                grid[i] = scanner.next().toCharArray();
            }

            // -------------------------------------------------------------------
            // Core algorithm
            // -------------------------------------------------------------------
            boolean[][] covered = new boolean[rows][cols];
            List<Guard> guards = new ArrayList<>();

            // Scan every interior cell (exclude the border)
            for (int r = 1; r < rows - 1; r++) {
                for (int c = 1; c < cols - 1; c++) {
                    if (grid[r][c] != '*') {
                        continue; // not a candidate centre
                    }

                    // Determine the smallest arm length among the four directions
                    int minArm = Integer.MAX_VALUE;
                    for (Direction dir : Direction.values()) {
                        minArm = Math.min(minArm, dir.armLength(grid, r, c));
                    }

                    // Guard size must be > 0; otherwise this cell cannot host a guard
                    if (minArm == 0) {
                        continue;
                    }

                    // Mark all cells belonging to the cross (centre + minArm cells on each side)
                    markCovered(covered, r, c, minArm);
                    // Store guard using 1‑based coordinates for the required output format
                    guards.add(new Guard(r + 1, c + 1, minArm));
                }
            }

            // -------------------------------------------------------------------
            // Validation: ensure every '*' is covered
            // -------------------------------------------------------------------
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (grid[r][c] == '*' && !covered[r][c]) {
                        System.out.println(-1);
                        return;
                    }
                }
            }

            // -------------------------------------------------------------------
            // Output
            // -------------------------------------------------------------------
            System.out.println(guards.size());
            for (Guard g : guards) {
                System.out.println(g.getRow() + " " + g.getCol() + " " + g.getSize());
            }
        }
    }

    /**
     * Marks the cells that belong to the cross centred at (r,c) with arm length {@code size}.
     *
     * @param covered   matrix that records which cells have been covered
     * @param r         centre row (0‑based)
     * @param c         centre column (0‑based)
     * @param size      length of each arm (including the centre)
     */
    private static void markCovered(boolean[][] covered, int r, int c, int size) {
        covered[r][c] = true; // centre cell
        for (int i = 1; i <= size; i++) {
            covered[r + i][c] = true;   // down
            covered[r - i][c] = true;   // up
            covered[r][c + i] = true;   // right
            covered[r][c - i] = true;   // left
        }
    }
}

import java.io.*;
import java.util.*;

public class P1015E2 {

    /** Direction vectors for the four cardinal directions (up, right, down, left). */
    private enum Direction {
        UP(-1, 0),
        RIGHT(0, 1),
        DOWN(1, 0),
        LEFT(0, -1);

        final int di;
        final int dj;

        Direction(int di, int dj) {
            this.di = di;
            this.dj = dj;
        }
    }

    /** Simple data holder for a detected star (center and ray length). */
    private static final class Star {
        final int row;
        final int col;
        final int length;

        Star(int row, int col, int length) {
            this.row = row;
            this.col = col;
            this.length = length;
        }

        @Override
        public String toString() {
            return (row + 1) + " " + (col + 1) + " " + length;
        }
    }

    /** Fast scanner used for competitive‑style input. */
    private static final class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 10];
        private int bufPos = 0;
        private int bufLen = 0;

        FastScanner(InputStream in) {
            this.in = in;
        }

        private int read() throws IOException {
            if (bufPos >= bufLen) {
                bufLen = in.read(buffer);
                bufPos = 0;
                if (bufLen <= 0) {
                    return -1;
                }
            }
            return buffer[bufPos++];
        }

        private boolean isSpace(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        private boolean isEndline(int c) {
            return c == '\n' || c == '\r' || c == -1;
        }

        String next() {
            int c;
            do {
                c = read();
            } while (isSpace(c));
            StringBuilder sb = new StringBuilder();
            do {
                sb.append((char) c);
                c = read();
            } while (!isSpace(c));
            return sb.toString();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        String nextLine() {
            int c;
            do {
                c = read();
            } while (isEndline(c));
            StringBuilder sb = new StringBuilder();
            do {
                sb.append((char) c);
                c = read();
            } while (!isEndline(c));
            return sb.toString();
        }
    }

    /** Entry point of the program. */
    public static void main(String[] args) throws Exception {
        try (FastScanner fs = new FastScanner(System.in);
             PrintWriter out = new PrintWriter(System.out)) {

            readDimensions(fs);
            computeDirectionalCounts();

            Queue<Star> stars = new LinkedList<>();

            // Detect and record every valid star.
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    if (grid[i][j] == '.') {
                        continue;
                    }
                    int ray = computeRayLength(i, j);
                    if (ray < 1) {
                        continue;
                    }
                    fillCoverage(i, j, ray);
                    stars.add(new Star(i, j, ray));
                }
            }

            // Verify that every '*' cell is covered by at least one star.
            if (!allCoverageMarked()) {
                out.println(-1);
                return;
            }

            out.println(stars.size());
            for (Star s : stars) {
                out.println(s);
            }
        }
    }

    // -------------------------------------------------------------------------
    // Static state used throughout the algorithm (mirroring the original design)
    // -------------------------------------------------------------------------
    private static int n;
    private static int m;
    private static char[][] grid;
    private static boolean[][] coverage; // marks cells that belong to some star

    private static final int[] DIR_DI = {-1, 0, 1, 0};
    private static final int[] DIR_DJ = {0, 1, 0, -1};

    // -------------------------------------------------------------------------
    // Input handling
    // -------------------------------------------------------------------------
    private static void readDimensions(FastScanner fs) {
        n = fs.nextInt();
        m = fs.nextInt();
        grid = new char[n][];
        for (int i = 0; i < n; i++) {
            grid[i] = fs.nextLine().toCharArray();
        }
    }

    // -------------------------------------------------------------------------
    // Pre‑computations of consecutive '*' counts in each direction
    // -------------------------------------------------------------------------
    private static int[][] up;
    private static int[][] down;
    private static int[][] left;
    private static int[][] right;

    private static void computeDirectionalCounts() {
        up = new int[n][m];
        down = new int[n][m];
        left = new int[n][m];
        right = new int[n][m];

        // Up & down (vertical)
        for (int j = 0; j < m; j++) {
            if (grid[0][j] == '*') up[0][j] = 1;
            for (int i = 1; i < n; i++) {
                if (grid[i][j] == '*') up[i][j] = up[i - 1][j] + 1;
            }
            if (grid[n - 1][j] == '*') down[n - 1][j] = 1;
            for (int i = n - 2; i >= 0; i--) {
                if (grid[i][j] == '*') down[i][j] = down[i + 1][j] + 1;
            }
        }

        // Left & right (horizontal)
        for (int i = 0; i < n; i++) {
            if (grid[i][0] == '*') left[i][0] = 1;
            for (int j = 1; j < m; j++) {
                if (grid[i][j] == '*') left[i][j] = left[i][j - 1] + 1;
            }
            if (grid[i][m - 1] == '*') right[i][m - 1] = 1;
            for (int j = m - 2; j >= 0; j--) {
                if (grid[i][j] == '*') right[i][j] = right[i][j + 1] + 1;
            }
        }
    }

    // -------------------------------------------------------------------------
    // Core algorithm helpers
    // -------------------------------------------------------------------------
    /** Returns the maximal ray length (minus one) for a cell that contains '*'. */
    private static int computeRayLength(int i, int j) {
        return Math.min(up[i][j],
                       Math.min(down[i][j],
                                Math.min(left[i][j], right[i][j]))) - 1;
    }

    /** Marks the center cell and its four rays with the coverage matrix. */
    private static void fillCoverage(int i, int j, int ray) {
        coverage[i][j] = true;
        for (int dir = 0; dir < 4; dir++) {
            int ni = i;
            int nj = j;
            for (int step = 0; step < ray; step++) {
                ni += DIR_DI[dir];
                nj += DIR_DJ[dir];
                coverage[ni][nj] = true;
            }
        }
    }

    /** Checks that every '*' in the grid is covered by at least one star. */
    private static boolean allCoverageMarked() {
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i][j] == '*' && !coverage[i][j]) {
                    return false;
                }
            }
        }
        return true;
    }
}

import java.io.*;
import java.util.*;

/**
 * Reads a grid of characters and finds all maximal squares containing only '*'.
 * For each such square it outputs its top‑left coordinate (1‑based) and its side length.
 * If any '*' cell cannot belong to any square that consists exclusively of '*', the program prints -1.
 */
public class Main {

    /** Fast scanner for competitive‑style input. */
    private static final class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner(InputStream in) {
            this.br = new BufferedReader(new InputStreamReader(in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    throw new UncheckedIOException(e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }
    }

    /** Represents a maximal square of '*' identified by its centre (0‑based) and radius. */
    private static final class Square {
        final int row;   // centre row  (0‑based)
        final int col;   // centre column (0‑based)
        final int radius; // side length of the square

        Square(int row, int col, int radius) {
            this.row = row;
            this.col = col;
            this.radius = radius;
        }
    }

    public static void main(String[] args) {
        FastScanner fs = new FastScanner(System.in);
        int H = fs.nextInt();
        int W = fs.nextInt();

        char[][] grid = new char[H][];
        for (int r = 0; r < H; r++) {
            grid[r] = fs.next().toCharArray();
        }

        List<Square> squares = computeSquares(grid);
        if (squares == null) {
            System.out.println(-1);
        } else {
            StringBuilder out = new StringBuilder();
            out.append(squares.size()).append('\n');
            for (Square s : squares) {
                // output uses 1‑based coordinates as required by the original program
                out.append(s.row + 1).append(' ')
                   .append(s.col + 1).append(' ')
                   .append(s.radius).append('\n');
            }
            System.out.print(out.toString());
        }
    }

    /**
     * Finds all maximal squares composed exclusively of '*' cells.
     *
     * @param grid the input character grid
     * @return a list of {@link Square} objects, or {@code null} if validation fails
     */
    private static List<Square> computeSquares(char[][] grid) {
        int H = grid.length;
        int W = grid[0].length;

        // ---- 1. Compute how far each cell is from the nearest '*' in every direction ----
        int[][] up   = directionalCount(grid, true,  false); // upward
        int[][] down = directionalCount(grid, false, true);   // downward
        int[][] left = directionalCount(grid, false, true);   // leftward
        int[][] right= directionalCount(grid, false, true);   // rightward (re‑used logic)

        // ---- 2. Gather candidate squares centred on each '*' cell -------------------
        List<Square> candidates = new ArrayList<>();
        int[][] rowDiff = new int[H][W + 1];
        int[][] colDiff = new int[H + 1][W];

        for (int r = 0; r < H; r++) {
            for (int c = 0; c < W; c++) {
                if (grid[r][c] != '*') {
                    continue;
                }
                int radius = Math.min(
                        left[r][c],
                        right[r][c],
                        up[r][c],
                        down[r][c]);

                if (radius >= 1) {
                    Square sq = new Square(r, c, radius);
                    candidates.add(sq);

                    // Mark the rows and columns that are covered by this square
                    rowDiff[r][c - radius]++;
                    rowDiff[r][c + radius + 1]--;

                    colDiff[r - radius][c]++;
                    colDiff[r + radius + 1][c]--;
                }
            }
        }

        // ---- 3. Build prefix sums to know how many squares influence each cell -------
        for (int r = 0; r < H; r++) {
            for (int c = 1; c < W; c++) {
                rowDiff[r][c] += rowDiff[r][c - 1];
            }
        }
        for (int c = 0; c < W; c++) {
            for (int r = 1; r < H; r++) {
                colDiff[r][c] += colDiff[r - 1][c];
            }
        }

        // ---- 4. Validate that every '*' belongs to at least one square ---------------
        for (int r = 0; r < H; r++) {
            for (int c = 0; c < W; c++) {
                if (grid[r][c] == '*' && (rowDiff[r][c] == 0 && colDiff[r][c] == 0)) {
                    return null; // at least one isolated star
                }
            }
        }

        return candidates;
    }

    /**
     * Calculates, for each cell, the number of consecutive '*' cells in the given direction.
     *
     * @param grid      the character grid
     * @param upward    {@code true} to count upward, {@code false} to count leftward
     * @param downward  {@code true} to count downward, {@code false} to count rightward
     * @return a 2‑D array where each entry holds the count of consecutive '*' in the specified direction
     */
    private static int[][] directionalCount(char[][] grid, boolean upward, boolean downward) {
        int H = grid.length;
        int W = grid[0].length;
        int[][] result = new int[H][W];

        for (int col = 0; col < W; col++) {
            int count = 0;
            if (upward) {
                // upward scan (top → bottom)
                for (int row = 0; row < H; row++) {
                    count = (grid[row][col] == '*') ? count + 1 : 0;
                    result[row][col] = count;
                }
            } else if (downward) {
                // downward scan (bottom → top)
                for (int row = H - 1; row >= 0; row--) {
                    count = (grid[row][col] == '*') ? count + 1 : 0;
                    result[row][col] = count;
                }
            }
        }
        // Horizontal scans (left ↔ right) are performed in a similar fashion but with a different loop order.
        for (int row = 0; row < H; row++) {
            int count = 0;
            if (!upward && !downward) { // left → right
                for (int col = 0; col < W; col++) {
                    count = (grid[row][col] == '*') ? count + 1 : 0;
                    result[row][col] = count;
                }
            } else { // right → left
                for (int col = W - 1; col >= 0; col--) {
                    count = (grid[row][col] == '*') ? count + 1 : 0;
                    result[row][col] = count;
                }
            }
        }
        return result;
    }
}

import java.util.Scanner;

/**
 * Reads several passwords and transforms each one so that it contains at
 * least one digit, one uppercase and one lowercase character.
 *
 * The transformation follows the same rules that the original code used,
 * but the implementation is now split into small, self‑documenting
 * methods and uses expressive names.
 */
public class VasyaAndPassword {

    /** Character used to insert a missing digit. */
    private static final char DIGIT = '0';

    /** Character used to insert a missing uppercase letter. */
    private static final char UPPER = 'A';

    /** Character used to insert a missing lowercase letter. */
    private static final char LOWER = 'a';

    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            int testCases = scanner.nextInt();

            for (int t = 0; t < testCases; t++) {
                String password = scanner.next();
                System.out.println(transform(password));
            }
        }
    }

    /**
     * Returns a new password that satisfies the “digit‑upper‑lower” rule.
     * The algorithm is a direct, but clearer, implementation of the
     * original nested‑if logic.
     */
    private static String transform(String original) {
        char[] chars = original.toCharArray();

        // -----------------------------------------------------------------
        // 1️⃣ Count the three required categories
        // -----------------------------------------------------------------
        int digitCount  = 0;
        int upperCount  = 0;
        int lowerCount  = 0;

        for (char c : chars) {
            if (Character.isDigit(c)) {
                digitCount++;
            } else if (Character.isUpperCase(c)) {
                upperCount++;
            } else if (Character.isLowerCase(c)) {
                lowerCount++;
            }
        }

        // -----------------------------------------------------------------
        // 2️⃣ Apply the specific replacement rules
        // -----------------------------------------------------------------
        if (needsDigit(digitCount, upperCount, lowerCount)) {
            replaceFirst(chars, DIGIT);
        } else if (needsUpper(upperCount, digitCount, lowerCount)) {
            replaceFirst(chars, UPPER);
        } else if (needsLower(lowerCount, digitCount, upperCount)) {
            replaceFirst(chars, LOWER);
        }

        // -----------------------------------------------------------------
        // 3️⃣ When more than one category is missing we have to decide
        //     which existing category to replace.
        // -----------------------------------------------------------------
        // The original code contains many mutually exclusive branches.
        // Here we keep the same decision tree but with expressive names.
        // -----------------------------------------------------------------
        switch (pickReplacementCase(digitCount, upperCount, lowerCount)) {
            case REPLACE_FIRST_WITH_DIGIT:
                chars[0] = DIGIT;
                break;
            case REPLACE_FIRST_WITH_UPPER:
                replaceFirstUpper(chars);
                break;
            case REPLACE_FIRST_WITH_LOWER:
                replaceFirstLower(chars);
                break;
            case REPLACE_FIRST_WITH_BOTH:
                // missing digit & both other categories are present,
                // we need to insert two characters at the beginning.
                // This mirrors the original last three “else‑if” blocks.
                chars[0] = LOWER;
                chars[1] = DIGIT;
                break;
            default:
                // No change needed – the password already satisfies the rule.
                break;
        }

        return new String(chars);
    }

    /** Determines whether a digit is missing **and** the other two categories
     *  are present in a pattern that matches the original `if` conditions. */
    private static boolean needsDigit(int digit, int upper, int lower) {
        // missing digit && upper > 1 && lower > 1
        return digit == 0 && upper > 1 && lower > 1;
    }

    /** Determines whether a digit is missing **and** exactly one uppercase
     *  exists while lower‑case appears >1 (mirrors original branch). */
    private static boolean needsDigitWithSingleUpper(int digit, int upper, int lower) {
        return digit == 0 && upper > 1 && lower == 1;
    }

    /** Determines whether a digit is missing **and** exactly one lowercase
     *  exists while upper‑case appears >1 (mirrors original branch). */
    private static boolean needsDigitWithSingleLower(int digit, int upper, int lower) {
        return digit == 0 && upper == 1 && lower > 1;
    }

    /** Determines the appropriate replacement strategy for a missing
     *  uppercase letter. Returns an enum describing the concrete action. */
    private enum UpperReplacement {
        REPLACE_FIRST_WITH_UPPER,
        REPLACE_FIRST_DIGIT_WITH_UPPER,
        REPLACE_FIRST_LOWER_WITH_UPPER,
        REPLACE_FIRST_WITH_UPPER_AND_DIGIT,
        REPLACE_FIRST_WITH_UPPER_AND_LOWER,
        NONE
    }

    /** Chooses which rule to apply when the current password lacks uppercase
     *  letters, based on the counts of the other categories. */
    private static UpperReplacement pickUpperReplacement(int digit, int upper, int lower) {
        if (upper == 0 && digit > 1 && lower > 1) {
            return UpperReplacement.REPLACE_FIRST_WITH_UPPER;
        }
        if (upper == 0 && digit > 1 && lower == 1) {
            return UpperReplacement.REPLACE_FIRST_DIGIT_WITH_UPPER;
        }
        if (upper == 0 && digit == 1 && lower > 1) {
            return UpperReplacement.REPLACE_FIRST_LOWER_WITH_UPPER;
        }
        if (upper == 0 && digit == 0 && lower > 1) {
            return UpperReplacement.REPLACE_FIRST_WITH_UPPER_AND_DIGIT;
        }
        if (upper == 0 && digit > 1 && lower == 0) {
            return UpperReplacement.REPLACE_FIRST_WITH_UPPER_AND_LOWER;
        }
        return UpperReplacement.NONE;
    }

    /** Determines the appropriate replacement strategy for a missing
     *  lowercase letter. */
    private enum LowerReplacement {
        REPLACE_FIRST_WITH_LOWER,
        REPLACE_FIRST_DIGIT_WITH_LOWER,
        REPLACE_FIRST_UPPER_WITH_LOWER,
        REPLACE_FIRST_WITH_BOTH,
        NONE
    }

    /** Chooses which rule to apply when the current password lacks lowercase
     *  letters, based on the counts of the other categories. */
    private static LowerReplacement pickLowerReplacement(int digit, int upper, int lower) {
        if (lower == 0 && digit > 1 && upper > 1) {
            return LowerReplacement.REPLACE_FIRST_WITH_BOTH;
        }
        if (lower == 0 && digit > 1 && upper == 1) {
            return LowerReplacement.REPLACE_FIRST_DIGIT_WITH_LOWER;
        }
        if (lower == 0 && digit == 1 && upper > 1) {
            return LowerReplacement.REPLACE_FIRST_UPPER_WITH_LOWER;
        }
        return LowerReplacement.NONE;
    }

    /** Helper that replaces the first character that belongs to a given
     *  category with the supplied replacement character. */
    private static void replaceFirst(char[] arr, char replacement) {
        for (int i = 0; i < arr.length; i++) {
            if (Character.isDigit(arr[i])) {
                arr[i] = replacement;
                break;
            }
        }
    }

    /** Helper that replaces the first uppercase letter with the supplied
     *  replacement character. */
    private static void replaceFirstUpper(char[] arr) {
        for (int i = 0; i < arr.length; i++) {
            if (Character.isUpperCase(arr[i])) {
                arr[i] = UPPER;
                break;
            }
        }
    }

    /** Helper that replaces the first lowercase letter with the supplied
     *  replacement character. */
    private static void replaceFirstLower(char[] arr) {
        for (int i = 0; i < arr.length; i++) {
            if (Character.isLowerCase(arr[i])) {
                arr[i] = LOWER;
                break;
            }
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.StringTokenizer;

/**
 * Main application that reads several test strings and transforms them
 * according to a set of rules concerning the presence of lower‑case,
 * upper‑case and “other” characters.
 *
 * <p>The refactored version improves readability, separates concerns
 * (classification, transformation and I/O) and uses meaningful names
 * and constants.</p>
 */
public class Main {

    /** Character used to replace a lower‑case letter when it must become upper‑case. */
    private static final char REPLACE_TO_UPPER = 'A';
    /** Character used to replace an upper‑case letter when it must become lower‑case. */
    private static final char REPLACE_TO_LOWER = 'a';
    /** Character used to replace a character when a digit is required. */
    private static final char REPLACE_WITH_DIGIT = '1';

    public static void main(String[] ... args) throws IOException {
        // Try‑with‑resources ensures the underlying BufferedReader is closed.
        try (FastReader reader = new FastReader()) {
            PrintWriter writer = new PrintWriter(System.out);
            int testCases = reader.nextInt();

            for (int t = 0; t < testCases; t++) {
                String current = reader.next();
                CategoryInfo info = countCategories(current);
                String transformed = transform(current, info);
                writer.println(transformed);
            }

            writer.flush();
        }
    }

    /**
     * Counts how many lower‑case, upper‑case and “other” characters are present
     * and records the index of the last occurrence of each category.
     */
    private static CategoryInfo countCategories(String s) {
        int lowerCount = 0, upperCount = 0, otherCount = 0;
        int lastLowerIdx = -1, lastUpperIdx = -1, lastOtherIdx = -1;

        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (Character.isLowerCase(c)) {
                lowerCount++;
                lastLowerIdx = i;
            } else if (Character.isUpperCase(c)) {
                upperCount++;
                lastUpperIdx = i;
            } else {
                otherCount++;
                lastOtherIdx = i;
            }
        }
        return new CategoryInfo(lowerCount, upperCount, otherCount,
                lastLowerIdx, lastUpperIdx, lastOtherIdx);
    }

    /**
     * Applies the transformation rules described in the original program.
     *
     * @param s      the original string
     * @param info   classification information produced by {@link #countCategories(String)}
     * @return the possibly transformed string
     */
    private static String transform(String s, CategoryInfo info) {
        boolean hasLower = info.lowerCount > 0;
        boolean hasUpper = info.upperCount > 0;
        boolean hasOther = info.otherCount > 0;

        // All three categories are present → nothing to change.
        if (hasLower && hasUpper && hasOther) {
            return s;
        }

        // Only a single category is present → add a fixed prefix.
        if (hasLower && !hasUpper && !hasOther) {
            return "A1" + s.substring(2);
        }
        if (!hasLower && hasUpper && !hasOther) {
            return "a1" + s.substring(2);
        }
        if (!hasLower && !hasUpper && hasOther) {
            return "aA" + s.substring(2);
        }

        // Exactly two categories are present → replace a character
        // depending on which category is missing.
        if (hasLower && hasUpper && !hasOther) {               // missing other
            if (info.lowerCount > 1) {
                return replaceAt(s, info.lastLowerIdx, REPLACE_WITH_DIGIT);
            }
            if (info.upperCount > 1) {
                return replaceAt(s, info.lastUpperIdx, REPLACE_WITH_DIGIT);
            }
        } else if (!hasLower && hasUpper && hasOther) {        // missing lower
            if (info.upperCount > 1) {
                return replaceAt(s, info.lastUpperIdx, REPLACE_TO_UPPER);
            }
            if (info.otherCount > 1) {
                return replaceAt(s, info.lastOtherIdx, REPLACE_TO_UPPER);
            }
        } else if (hasLower && !hasUpper && hasOther) {        // missing upper
            if (info.lowerCount > 1) {
                return replaceAt(s, info.lastLowerIdx, REPLACE_TO_LOWER);
            }
            if (info.otherCount > 1) {
                return replaceAt(s, info.lastOtherIdx, REPLACE_TO_LOWER);
            }
        }

        // Fallback – should never be reached with the given logic.
        return s;
    }

    /**
     * Returns a new string with the character at {@code index} replaced by
     * {@code newChar}.
     */
    private static String replaceAt(String s, int index, char newChar) {
        if (index < 0 || index >= s.length()) {
            return s;
        }
        return s.substring(0, index) + newChar + s.substring(index + 1);
    }

    /** Holds classification data for a single input string. */
    private static final class CategoryInfo {
        final int lowerCount;
        final int upperCount;
        final int otherCount;
        final int lastLowerIdx;
        final int lastUpperIdx;
        final int lastOtherIdx;

        CategoryInfo(int lowerCount, int upperCount, int otherCount,
                     int lastLowerIdx, int lastUpperIdx, int lastOtherIdx) {
            this.lowerCount = lowerCount;
            this.upperCount = upperCount;
            this.otherCount = otherCount;
            this.lastLowerIdx = lastLowerIdx;
            this.lastUpperIdx = lastUpperIdx;
            this.lastOtherIdx = lastOtherIdx;
        }
    }

    /** Minimal fast scanner used for reading input tokens. */
    static class FastReader {
        private final BufferedReader br;
        private StringTokenizer st;

        FastReader() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    throw new UncheckedIOException(e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.io.*;
import java.util.Scanner;

/**
 * Refactored solution for the “Codeforces” problem.
 * <p>
 * The program reads several test cases, each consisting of a single string.
 * It guarantees that the resulting string contains at least one lower‑case
 * letter, one upper‑case letter and one digit.  If any of those categories are
 * missing the algorithm inserts placeholder characters ('a', 'A' or '1')
 * before the first suitable character.
 * </p>
 */
public final class Codeforces {

    /** Placeholder characters used when a category is missing */
    private static final char LOWER_PLACEHOLDER  = 'a';
    private static final char UPPER_PLACEHOLDER  = 'A';
    private static final char DIGIT_PLACEHOLDER  = '1';

    /** Simple DTO that holds the three counting values */
    private static final class CountInfo {
        final int lower;
        final int upper;
        final int digit;

        CountInfo(int lower, int upper, int digit) {
            this.lower = lower;
            this.upper = upper;
            this.digit = digit;
        }

        /** True when all three categories are present */
        boolean isComplete() {
            return lower > 0 && upper > 0 && digit > 0;
        }
    }

    /** Counts lower‑case, upper‑case and digit characters in the given string */
    private static CountInfo countCategories(String s) {
        int lower = 0, upper = 0, digit = 0;
        for (char c : s.toCharArray()) {
            if (Character.isLowerCase(c)) {
                lower++;
            } else if (Character.isUpperCase(c)) {
                upper++;
            } else if (Character.isDigit(c)) {
                digit++;
            }
        }
        return new CountInfo(lower, upper, digit);
    }

    /**
     * Builds the output string according to the original algorithm.
     * The logic is kept identical but expressed with clearer variable names
     * and without duplicated loops.
     */
    private static String transform(String original, CountInfo info) {
        // All categories already present → nothing to do.
        if (info.isComplete()) {
            return original;
        }

        // Flags that tell us which placeholders are still required.
        boolean needLower  = !info.hasLower();
        boolean needUpper  = !info.hasUpper();
        boolean needDigit  = !info.hasDigit();

        StringBuilder result = new StringBuilder();
        boolean lowerInserted  = false;
        boolean upperInserted  = false;
        boolean digitInserted  = false;

        for (int i = 0; i < original.length(); i++) {
            char c = original.charAt(i);

            // Insert a placeholder if we still need it and at least one
            // other category has already been inserted.
            if (!lowerInserted && needLower && (upperInserted || digitInserted)) {
                result.append(LOWER_PLACEHOLDER);
                lowerInserted = true;
            }
            if (!upperInserted && needUpper && (lowerInserted || digitInserted)) {
                result.append(UPPER_PLACEHOLDER);
                upperInserted = true;
            }
            if (!digitInserted && needDigit && (lowerInserted || upperInserted)) {
                result.append(DIGIT_PLACEHOLDER);
                digitInserted = true;
            }

            result.append(c);
        }

        // If a placeholder never got a chance to be inserted inside the loop,
        // append it now (covers cases where the string starts with a needed type).
        if (!lowerInserted && needLower) {
            result.append(LOWER_PLACEHOLDER);
        }
        if (!upperInserted && needUpper) {
            result.append(UPPER_PLACEHOLDER);
        }
        if (!digitInserted && needDigit) {
            result.append(DIGIT_PLACEHOLDER);
        }

        return result.toString();
    }

    /** Entry point – reads from standard input and prints the answers. */
    public static void main(String[] args) {
        // Using the standard Scanner is sufficient for the problem constraints.
        try (Scanner scanner = new Scanner(System.in)) {
            int testCases = scanner.nextInt();
            while (testCases-- > 0) {
                String input = scanner.next();
                CountInfo counts = countCategories(input);
                String answer = transform(input, counts);
                System.out.println(answer);
            }
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Entry point of the solution. It tries to open “input.txt / output.txt”.
 * If those files are not present it falls back to {@code System.in / System.out}
 * – exactly like the original program.
 */
public class Main {

    /** Helper constant used in the original code. */
    private static final int OO = (int) 1e9;

    /** Characters that may be used for replacement (the same three used originally). */
    private static final char[] REPLACEMENT_CHARS = {'0', 'a', 'A'};

    public static void main(String[] args) {
        try (Kattio io = openStreams()) {
            int t = io.getInt();
            for (int i = 1; i <= t; i++) {
                new Solve(io).solve();
            }
        } catch (FileNotFoundException e) {
            // Fallback to standard streams – mirrors the behaviour of the original code.
            try (Kattio io = new Kattio(System.in, System.out)) {
                int t = io.getInt();
                for (int i = 1; i <= t; i++) {
                    new Solve(io).solve();
                }
            }
        }
    }

    /**
     * Tries to open the files {@code input.txt} and {@code output.txt}.
     * If they do not exist the method returns a {@link Kattio} that reads from
     * {@code System.in} and writes to {@code System.out}.
     */
    private static Kattio openStreams() throws FileNotFoundException {
        try {
            return new Kattio(new FileInputStream("input.txt"),
                              new FileOutputStream("output.txt"));
        } catch (FileNotFoundException ignored) {
            return new Kattio(System.in, System.out);
        }
    }
}

/**
 * Solves a single test case.
 * <p>
 * The algorithm is a faithful, but clearer, recreation of the original
 * {@code check0 / check1 / check2 / check3} logic.
 */
class Solve {

    private final Kattio io;
    /** The password that has to be fixed. */
    private String password;

    Solve(Kattio io) {
        this.io = io;
    }

    /** Executes the whole solving process for the current test case. */
    void solve() {
        password = io.getWord();
        String answer = findValidPassword();
        io.println(answer);
    }

    /**
     * Looks for a valid password by applying replacement rules of length 1, 2
     * and 3, in that order – exactly the same order the original program used.
     */
    private String findValidPassword() {
        if (isValid(password)) {
            return password;                     // already valid
        }

        // Try every possible replacement of length 1, then 2, then 3.
        for (int len = 1; len <= 3; len++) {
            List<String> patterns = patternsOfLength(len);
            for (int start = 0; start <= password.length() - len; start++) {
                for (String pattern : patterns) {
                    String candidate = replaceAt(password, start, pattern);
                    if (isValid(candidate)) {
                        return candidate;
                    }
                }
            }
        }
        return "";                                 // no solution found (should not happen)
    }

    /**
     * Replaces the substring of {@code source} that starts at {@code start}
     * and has the same length as {@code replacement} with {@code replacement}.
     */
    private String replaceAt(String source, int start, String replacement) {
        return source.substring(0, start) + replacement
                + source.substring(start + replacement.length());
    }

    /** Checks whether a candidate password contains at least one digit,
     *  one lower‑case letter and one upper‑case letter. */
    private boolean isValid(String candidate) {
        boolean hasDigit = false, hasLower = false, hasUpper = false;
        for (char ch : candidate.toCharArray()) {
            if (Character.isDigit(ch)) {
                hasDigit = true;
            } else if (Character.isLowerCase(ch)) {
                hasLower = true;
            } else if (Character.isUpperCase(ch)) {
                hasUpper = true;
            }
        }
        return hasDigit && hasLower && hasUpper;
    }

    /**
     * Returns the concrete replacement strings that were used in the original
     * implementation, grouped by their length.
     */
    private List<String> patternsOfLength(int length) {
        List<String> list = new ArrayList<>();
        switch (length) {
            case 1:
                list.add("0");
                list.add("a");
                list.add("A");
                break;
            case 2:
                list.add("0a");
                list.add("0A");
                list.add("Aa");
                break;
            case 3:
                list.add("0aA");
                break;
        }
        return list;
    }
}

/**
 * Very small wrapper around {@code PrintWriter} that mimics the original
 * {@code Kattio} class (fast tokeniser + printer).  It is deliberately left
 * unchanged apart from minor formatting improvements.
 */
class Kattio extends PrintWriter {

    public Kattio(InputStream input) {
        super(new BufferedOutputStream(System.out));
        read(input);
    }

    public Kattio(InputStream input, OutputStream output) {
        super(new BufferedOutputStream(output));
        read(input);
    }

    private void read(InputStream input) {
        this.r = new BufferedReader(new InputStreamReader(input));
    }

    public boolean hasMoreTokens() {
        return peekToken() != null;
    }

    public int getInt() {
        return Integer.parseInt(nextToken());
    }

    public double getDouble() {
        return Double.parseDouble(nextToken());
    }

    public long getLong() {
        return Long.parseLong(nextToken());
    }

    public String getWord() {
        return nextToken();
    }

    private String peekToken() {
        if (token == null) {
            try {
                while (st == null || !st.hasMoreTokens()) {
                    String line = r.readLine();
                    if (line == null) {
                        return null;
                    }
                    st = new StringTokenizer(line);
                }
                token = st.nextToken();
            } catch (IOException ignored) {
            }
        }
        return token;
    }

    private String nextToken() {
        String ans = peekToken();
        token = null;
        return ans;
    }

    // -----------------------------------------------------------------
    //  Fields used by the tokeniser
    // -----------------------------------------------------------------
    private BufferedReader r;
    private String line;
    private StringTokenizer st;
    private String token;
}

