public class ProblemA {
    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            int T = scanner.nextInt();
            StringBuilder output = new StringBuilder();
            for (int i = 0; i < T; i++) {
                String input = scanner.next();
                output.append(transformInput(input)).append('\n');
            }
            System.out.print(output.toString());
        }
    }

    private static String transformInput(String input) {
        int lowercaseCount = 0;
        int uppercaseCount = 0;
        int digitCount = 0;
        int lastLowerIndex = -1;
        int lastUpperIndex = -1;
        int lastDigitIndex = -1;

        for (int i = 0; i < input.length(); i++) {
            char c = input.charAt(i);
            if (Character.isLowerCase(c)) {
                lowercaseCount++;
                lastLowerIndex = i;
            } else if (Character.isUpperCase(c)) {
                uppercaseCount++;
                lastUpperIndex = i;
            } else if (Character.isDigit(c)) {
                digitCount++;
                lastDigitIndex = i;
            }
        }

        // Handle cases where exactly two character types are absent
        if (lowercaseCount == 0 && uppercaseCount == 0) {
            String suffix = input.length() > 2 ? input.substring(2) : "";
            return "aA" + suffix;
        } else if (uppercaseCount == 0 && digitCount == 0) {
            String suffix = input.length() > 2 ? input.substring(2) : "";
            return "A1" + suffix;
        } else if (digitCount == 0 && lowercaseCount == 0) {
            String suffix = input.length() > 2 ? input.substring(2) : "";
            return "a1" + suffix;
        }

        // Handle specific single-type presence cases
        if (lowercaseCount == 0 && uppercaseCount == 1) {
            StringBuilder sb = new StringBuilder(input);
            if (lastDigitIndex != -1) sb.setCharAt(lastDigitIndex, 'a');
            return sb.toString();
        } else if (lowercaseCount == 1 && uppercaseCount == 0) {
            StringBuilder sb = new StringBuilder(input);
            if (lastDigitIndex != -1) sb.setCharAt(lastDigitIndex, 'A');
            return sb.toString();
        } else if (uppercaseCount == 0 && digitCount == 1) {
            StringBuilder sb = new StringBuilder(input);
            if (lastLowerIndex != -1) sb.setCharAt(lastLowerIndex, '1');
            return sb.toString();
        } else if (digitCount == 0 && uppercaseCount == 1) {
            StringBuilder sb = new StringBuilder(input);
            if (lastLowerIndex != -1) sb.setCharAt(lastLowerIndex, 'a');
            return sb.toString();
        } else if (digitCount == 0 && lowercaseCount == 1) {
            StringBuilder sb = new StringBuilder(input);
            if (lastUpperIndex != -1) sb.setCharAt(lastUpperIndex, '1');
            return sb.toString();
        }

        // Handle cases where exactly one character type is absent
        if (lowercaseCount == 0) {
            StringBuilder sb = new StringBuilder(input);
            if (lastDigitIndex != -1) sb.setCharAt(lastDigitIndex, 'a');
            return sb.toString();
        } else if (uppercaseCount == 0) {
            StringBuilder sb = new StringBuilder(input);
            if (lastDigitIndex != -1) sb.setCharAt(lastDigitIndex, 'A');
            return sb.toString();
        } else if (digitCount == 0) {
            StringBuilder sb = new StringBuilder(input);
            if (lastLowerIndex != -1) sb.setCharAt(lastLowerIndex, '1');
            return sb.toString();
        }

        // Default case: no modifications needed
        return input;
    }
}

import java.util.Scanner;

/**
 * Utility class that validates passwords and attempts to fix invalid ones
 * by inserting known test patterns.
 *
 * <p>Validation rules require at least one lowercase letter, one uppercase
 * letter and one digit.</p>
 */
final class PasswordValidator {

    /** Known patterns used for fixing invalid passwords. */
    private static final String[] DEFAULT_PATTERNS = {
            "a", "A", "1", "aA", "a1", "A1", "aA1"
    };

    /** Prevents instantiation of this utility class. */
    private PasswordValidator() {
        // no‑op
    }

    /**
     * Checks whether the supplied password satisfies the validation rules.
     *
     * @param password password to validate (may be {@code null})
     * @return {@code true} if the password contains a lowercase, an uppercase
     *         and a digit character.
     */
    static boolean isValid(String password) {
        if (password == null || password.isEmpty()) {
            return false;
        }

        boolean hasLower = false;
        boolean hasUpper = false;
        boolean hasDigit = false;

        for (char c : password.toCharArray()) {
            if (Character.isLowerCase(c)) {
                hasLower = true;
            } else if (Character.isUpperCase(c)) {
                hasUpper = true;
            } else if (Character.isDigit(c)) {
                hasDigit = true;
            }

            // early exit if all three categories are already present
            if (hasLower && hasUpper && hasDigit) {
                return true;
            }
        }

        return hasLower && hasUpper && hasDigit;
    }

    /**
     * Attempts to fix an invalid password by replacing a contiguous segment
     * (of the same length as one of the known patterns) with that pattern.
     * If a valid password is produced, it is printed and the method returns
     * {@code true}.
     *
     * @param original the original password entered by the user
     */
    private static void attemptFix(String original) {
        for (String pattern : DEFAULT_PATTERNS) {
            int patternLength = pattern.length();

            // we can only replace a segment that fits completely inside the password
            for (int start = 0; start <= original.length() - patternLength; start++) {
                // build the candidate by swapping the segment
                String candidate = original.substring(0, start)
                        + pattern
                        + original.substring(start + patternLength);
                if (isValid(candidate)) {
                    System.out.println(candidate);
                    return; // fix found – exit early
                }
            }
        }
        // If no fix is found, nothing is printed – matching original behaviour.
    }

    /**
     * Main driver program that reads several passwords from standard input,
     * validates each, and prints either the original valid password or a
     * fixed version.
     */
    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            int testCaseCount = scanner.nextInt();
            scanner.nextLine(); // consume the line‑break after the integer

            for (int i = 0; i < testCaseCount; i++) {
                String password = scanner.nextLine();

                if (isValid(password)) {
                    System.out.println(password);
                } else {
                    attemptFix(password);
                }
            }
        }
    }
}

