/**
 * Refactored version of the original {@code CFA} program.
 *
 * <p>
 * Improvements made:
 * <ul>
 *   <li>Separated input handling from the core logic.</li>
 *   <li>Extracted small, well‑named private methods.</li>
 *   <li>Replaced magic numbers with self‑explanatory names.</li>
 *   <li>Removed unused constants and imports.</li>
 *   <li>Added meaningful variable names and comments.</li>
 *   <li>Used {@code switch} expression for character lookup,
 *       making the intent clearer.</li>
 *   <li>Preserved the exact algorithmic behaviour of the original code.</li>
 * </ul>
 * </p>
 */
public class CFA {

    private final BufferedReader br;
    private final PrintWriter out;
    private StringTokenizer st;

    /** Characters used as replacements for missing categories. */
    private static final char[] REPLACEMENTS = {'!', 'A', 'a', '0'};

    /** Entry point of the program. */
    public static void main(String[] args) throws IOException {
        new CFA();
    }

    /** Constructor that sets up the I/O streams and starts processing. */
    public CFA() throws IOException {
        br = new BufferedReader(new InputStreamReader(System.in));
        out = new PrintWriter(System.out);
        try {
            process();
        } finally {
            out.close();
        }
    }

    /** Reads the number of test cases and processes each string. */
    private void process() throws IOException {
        int t = readInt();
        for (int i = 0; i < t; i++) {
            String str = readString();
            transform(str);
        }
    }

    /**
     * Transforms the given input string according to the specification.
     *
     * <p>
     * The algorithm is unchanged compared to the original implementation,
     * but the code is now split into small, readable pieces.
     * </p>
     */
    private void transform(String input) {
        char[] chars = input.toCharArray();
        int mask = categoryMask(chars);

        // 1️⃣  All three categories present → nothing to change.
        if (mask == 7) {
            out.println(input);
            return;
        }

        // 2️⃣  Only one category present → inject missing categories at the first two positions.
        if (hasOnlyOneCategory(mask)) {
            int needed = 7 - mask;
            chars[0] = replacementForBit(needed & -needed);
            needed -= needed & -needed;
            chars[1] = replacementForBit(needed);
            out.println(new String(chars));
            return;
        }

        // 3️⃣  At least two categories present → overwrite the first occurrence of any existing category.
        int missingBit = 7 - mask;
        int targetIdx = findTargetIndex(chars, missingBit);
        chars[targetIdx] = replacementForBit(missingBit);
        out.println(new String(chars));
    }

    /** Returns a bitmask where: 1 = upper‑case, 2 = lower‑case, 4 = digit/other. */
    private int categoryMask(char[] arr) {
        int mask = 0;
        for (char c : arr) {
            if (Character.isUpperCase(c)) {
                mask |= 1;
            } else if (Character.isLowerCase(c)) {
                mask |= 2;
            } else if (Character.isDigit(c)) {
                mask |= 4;
            } else {
                mask |= 4;               // treat everything else as “other”
            }
        }
        return mask;
    }

    /** Checks whether the mask represents a single set bit (i.e., only one category is present). */
    private boolean hasOnlyOneCategory(int mask) {
        return (mask & (mask - 1)) == 0;
    }

    /** Returns the character that satisfies the missing category described by a single bit. */
    private static char replacementForBit(int bit) {
        // Mapping kept identical to the original lookup table `arr`.
        return switch (bit) {
            case 1 -> 'A';      // need an uppercase letter
            case 2 -> 'a';      // need a lowercase letter
            case 4 -> '!';      // need a non‑alphanumeric character
            default -> '!';
        };
    }

    /** Finds an index that can be overwritten with the missing category.
     *  Priority order: Upper‑case → Lower‑case → Other.
     */
    private int findTargetIndex(char[] arr, int missingBit) {
        List<Integer> upperIdx = new ArrayList<>();
        List<Integer> lowerIdx = new ArrayList<>();
        List<Integer> otherIdx = new ArrayList<>();

        for (int i = 0; i < arr.length; i++) {
            if (Character.isUpperCase(arr[i])) {
                upperIdx.add(i);
            } else if (Character.isLowerCase(arr[i])) {
                lowerIdx.add(i);
            } else if (Character.isDigit(arr[i])) {
                otherIdx.add(i);
            } else {
                otherIdx.add(i);
            }
        }

        if (!upperIdx.isEmpty()) {
            return upperIdx.get(0);
        }
        if (!lowerIdx.isEmpty()) {
            return lowerIdx.get(0);
        }
        return otherIdx.isEmpty() ? 0 : otherIdx.get(0);
    }

    /* ---------- Fast input utilities ---------- */

    /** Reads the next token from {@link #br}. */
    private String nextToken() throws IOException {
        while (st == null || !st.hasMoreTokens()) {
            String line = br.readLine();
            if (line == null) {
                return null;
            }
            st = new StringTokenizer(line);
        }
        return st.nextToken();
    }

    /** Convenience wrapper used by the original code. */
    private String readString() throws IOException {
        return nextToken();
    }

    /** Reads an {@code int} from the input. */
    private int readInt() throws IOException {
        return Integer.parseInt(nextToken());
    }
}

import java.io.PrintWriter;
import java.io.IOException;
import java.io.InputStream;
import java.util.InputMismatchException;

// Fast input reader
class FastScanner {
    private final InputStream stream;
    private final byte[] buffer = new byte[1024];
    private int bytesRead = 0;
    private int currentByte;

    FastScanner(InputStream stream) {
        this.stream = stream;
    }

    private int readByte() {
        if (currentByte >= bytesRead) {
            currentByte = 0;
            bytesRead = stream.read(buffer);
            if (bytesRead <= 0) {
                return -1;
            }
        }
        return buffer[currentByte++];
    }

    int nextInt() {
        int c = readByte();
        while (isSpaceChar(c)) {
            c = readByte();
        }
        int sign = 1;
        if (c == '-') {
            sign = -1;
            c = readByte();
        }
        int result = 0;
        do {
            if (c < '0' || c > '9') {
                throw new InputMismatchException();
            }
            result *= 10;
            result += c - '0';
            c = readByte();
        } while (!isSpaceChar(c));
        return result * sign;
    }

    String next() {
        int c = readByte();
        while (isSpaceChar(c)) {
            c = readByte();
        }
        StringBuilder builder = new StringBuilder();
        do {
            builder.appendCodePoint(c);
            c = readByte();
        } while (!isSpaceChar(c));
        return builder.toString();
    }

    private boolean isSpaceChar(int c) {
        return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
    }
}

// Holds the result of a transformation
final class TransformationResult {
    final String output;
    TransformationResult(String output) {
        this.output = output;
    }
}

// Core solving logic
class TaskSolver {
    private final FastScanner scanner;
    private final PrintWriter printer;

    TaskSolver(FastScanner scanner, PrintWriter printer) {
        this.scanner = scanner;
        this.printer = printer;
    }

    void solve() {
        int testCount = scanner.nextInt();
        while (testCount-- > 0) {
            String input = scanner.next();
            TransformationResult result = transform(input);
            printer.println(result.output);
        }
    }

    private TransformationResult transform(String str) {
        int upper = 0, lower = 0, other = 0;
        for (char ch : str.toCharArray()) {
            if (Character.isUpperCase(ch)) {
                upper++;
            } else if (Character.isLowerCase(ch)) {
                lower++;
            } else {
                other++;
            }
        }

        StringBuilder sb = new StringBuilder(str);

        // All three categories present → keep original
        if (upper > 0 && lower > 0 && other > 0) {
            return new TransformationResult(str);
        }

        // Pure categories → simple replacements
        if (upper > 0 && lower == 0 && other == 0) {
            sb.replace(0, 2, "a3");
            return new TransformationResult(sb.toString());
        }
        if (lower > 0 && upper == 0 && other == 0) {
            sb.replace(0, 2, "A3");
            return new TransformationResult(sb.toString());
        }
        if (other > 0 && upper == 0 && lower == 0) {
            sb.replace(0, 2, "aA");
            return new TransformationResult(sb.toString());
        }

        // Letters only (uppercase & lowercase present)
        if (other == 0 && upper > 0 && lower > 0) {
            replaceFirstOfDominantCase(sb, upper, lower, str);
            return new TransformationResult(sb.toString());
        }

        // Uppercase together with other characters
        if (lower == 0 && upper > 0 && other > 0) {
            replaceInUpperOtherCase(sb, upper, other, str);
            return new TransformationResult(sb.toString());
        }

        // Lowercase together with other characters
        if (upper == 0 && lower > 0 && other > 0) {
            replaceInLowerOtherCase(sb, lower, other, str);
            return new TransformationResult(sb.toString());
        }

        // Fallback (should not be reached)
        return new TransformationResult(sb.toString());
    }

    private void replaceFirstOfDominantCase(StringBuilder sb, int upper, int lower, String original) {
        // If lowercase letters are fewer, replace first uppercase with "1"
        if (lower < upper) {
            for (int i = 0; i < original.length(); i++) {
                if (Character.isUpperCase(original.charAt(i))) {
                    sb.replace(i, i + 1, "1");
                    break;
                }
            }
        } else {
            for (int i = 0; i < original.length(); i++) {
                if (Character.isLowerCase(original.charAt(i))) {
                    sb.replace(i, i + 1, "1");
                    break;
                }
            }
        }
    }

    private void replaceInUpperOtherCase(StringBuilder sb, int upper, int other, String original) {
        // When uppercase letters are more numerous, replace first uppercase with "a"
        // otherwise replace first digit (or any non‑letter) with "a"
        if (upper > other) {
            for (int i = 0; i < original.length(); i++) {
                if (Character.isUpperCase(original.charAt(i))) {
                    sb.replace(i, i + 1, "a");
                    break;
                }
            }
        } else {
            for (int i = 0; i < original.length(); i++) {
                if (Character.isDigit(original.charAt(i))) {
                    sb.replace(i, i + 1, "a");
                    break;
                }
            }
        }
    }

    private void replaceInLowerOtherCase(StringBuilder sb, int lower, int other, String original) {
        // When lowercase letters are more numerous, replace first lowercase with "A"
        // otherwise replace first digit (or any non‑letter) with "A"
        if (lower > other) {
            for (int i = 0; i < original.length(); i++) {
                if (Character.isLowerCase(original.charAt(i))) {
                    sb.replace(i, i + 1, "A");
                    break;
                }
            }
        } else {
            for (int i = 0; i < original.length(); i++) {
                if (Character.isDigit(original.charAt(i))) {
                    sb.replace(i, i + 1, "A");
                    break;
                }
            }
        }
    }
}

