/**
 * Refactored version of the original program.
 * Improves readability, naming, separation of concerns and overall maintainability.
 */
public class Ideone {

    private static final char ZERO = '0';
    private static final char LOWER = 'a';
    private static final char UPPER = 'A';

    public static void main(String[] args) throws IOException {
        // Use try‑with‑resources to guarantee the scanner is closed.
        try (Scanner scanner = new Scanner(System.in)) {
            int testCases = scanner.nextInt();
            for (int t = 0; t < testCases; t++) {
                String input = scanner.next();
                System.out.println(transform(input));
            }
        }
    }

    /**
     * Performs the required transformation on the given input string.
     *
     * @param input the original string to process
     * @return the transformed string
     */
    private static String transform(String input) {
        // Counters and indices for each character type
        int digitCount = 0;
        int lowerCount = 0;
        int upperCount = 0;

        int lastDigitPos = -1;
        int lastLowerPos = -1;
        int lastUpperPos = -1;

        // Scan the string once to collect statistics.
        for (int i = 0; i < input.length(); i++) {
            char ch = input.charAt(i);
            if (Character.isDigit(ch)) {
                digitCount++;
                lastDigitPos = i;
            } else if (Character.isLowerCase(ch)) {
                lowerCount++;
                lastLowerPos = i;
            } else if (Character.isUpperCase(ch)) {
                upperCount++;
                lastUpperPos = i;
            }
        }

        // Determine which character types are present.
        boolean hasDigits = digitCount > 0;
        boolean hasLower = lowerCount > 0;
        boolean hasUpper = upperCount > 0;

        // Work on a mutable character array.
        char[] chars = input.toCharArray();

        int distinctTypes = countNonZero(hasDigits, hasLower, hasUpper);

        switch (distinctTypes) {
            case 2 -> replaceWithMissingCategory(chars, hasDigits, hasLower, hasUpper);
            case 1 -> replaceFirstTwoBasedOnDominantCategory(chars, digitCount, lowerCount, upperCount);
            default -> { /* No change needed */ }
        }

        return new String(chars);
    }

    /**
     * Counts how many of the three character categories (digit, lower, upper) are present.
     */
    private static int countNonZero(boolean hasDigits, boolean hasLower, boolean hasUpper) {
        int cnt = 0;
        if (hasDigits) cnt++;
        if (hasLower) cnt++;
        if (hasUpper) cnt++;
        return cnt;
    }

    /**
     * Handles the case where exactly two character categories are present.
     * It replaces the last occurrence of a category that appears at least twice
     * with a placeholder that belongs to the missing category.
     */
    private static void replaceWithMissingCategory(char[] chars,
                                                    boolean hasDigits,
                                                    boolean hasLower,
                                                    boolean hasUpper) {
        // Identify the missing category.
        String missingCategory = identifyMissingCategory(hasDigits, hasLower, hasUpper);
        char replacement = switch (missingCategory) {
            case "digit" -> ZERO;
            case "lower" -> LOWER;
            case "upper" -> UPPER;
            default -> throw new IllegalStateException("Unhandled missing category: " + missingCategory);
        };

        // Find a present category that appears at least twice.
        if (hasDigits && digitCount >= 2) {
            chars[lastDigitPos] = replacement;
        } else if (hasUpper && upperCount >= 2) {
            chars[lastUpperPos] = replacement;
        } else if (hasLower && lowerCount >= 2) {
            chars[lastLowerPos] = replacement;
        }
    }

    /**
     * Determines which category is missing among digit, lower, upper.
     */
    private static String identifyMissingCategory(boolean hasDigits,
                                                  boolean hasLower,
                                                  boolean hasUpper) {
        if (!hasDigits) return "digit";
        if (!hasLower) return "lower";
        return "upper";
    }

    /**
     * Handles the case where only a single character category is present.
     * Replaces the first two characters with a specific pair depending on the category.
     */
    private static void replaceFirstTwoBasedOnDominantCategory(char[] chars,
                                                                int digitCount,
                                                                int lowerCount,
                                                                int upperCount) {
        if (hasDigits()) {
            chars[0] = LOWER;
            chars[1] = UPPER;
        } else if (hasUpperCase()) {
            chars[0] = LOWER;
            chars[1] = ZERO;
        } else { // only lowercase present
            chars[0] = UPPER;
            chars[1] = ZERO;
        }
    }

    // Helper methods used by {@link #replaceFirstTwoBasedOnDominantCategory}
