/**
 * Reads several password strings and, for each, finds a minimal insertion
 * that makes the password contain at least one uppercase letter, one lowercase
 * letter and one digit. The first found solution is printed.
 *
 * The implementation purposefully favours readability and maintainability
 * over micro‑optimisation.
 */
public final class PasswordFixer {

    /** Input reader shared by the whole program. */
    private final BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
    /** Tokeniser used by {@link #next()}. */
    private StringTokenizer st;

    /** Checks whether a password already satisfies the security rules. */
    private static boolean isSecure(String password) {
        boolean hasUpper = false, hasLower = false, hasDigit = false;
        for (char c : password.toCharArray()) {
            if (Character.isUpperCase(c)) {
                hasUpper = true;
            } else if (Character.isLowerCase(c)) {
                hasLower = true;
            } else if (Character.isDigit(c)) {
                hasDigit = true;
            }
        }
        return hasUpper && hasLower && hasDigit;
    }

    /**
     * Tries to fix the given password by inserting the smallest possible
     * additional characters. Returns a secured password or {@code null} if
     * none can be found (the problem guarantees a solution exists).
     */
    private static String fixPassword(String password) {
        // Password already meets the criteria – nothing to do.
        if (isSecure(password)) {
            return password;
        }

        // -----------------------------------------------------------------
        // 1️⃣  Try inserting a single character (uppercase, lowercase or digit)
        // -----------------------------------------------------------------
        for (int pos = 0; pos <= password.length(); pos++) {
            for (char cand : new char[]{'A', 'a', '1'}) {
                String candidate = insertAt(password, pos, cand);
                if (isSecure(candidate)) {
                    return candidate;
                }
            }
        }

        // -----------------------------------------------------------------
        // 2️⃣  Try inserting two characters. The combinations we need are:
        //      "Aa", "A1", "a1"  (order matters, but the original code covered all)
        // -----------------------------------------------------------------
        String[] pairs = {"Aa", "A1", "a1"};
        for (int pos = 0; pos <= password.length(); pos++) {
            for (String pair : pairs) {
                String candidate = insertAt(password, pos, pair.charAt(0))
                        + pair.charAt(1)
                        + password.substring(pos + 2);
                if (isSecure(candidate)) {
                    return candidate;
                }
            }
        }

        // According to the problem statement a solution always exists.
        return null;
    }

    /**
     * Helper that returns a new string with {@code ch} inserted at {@code index}.
     */
    private static String insertAt(String src, int index, char ch) {
        StringBuilder sb = new StringBuilder(src.length() + 1);
        sb.append(src, 0, index);
        sb.append(ch);
        sb.append(src, index, src.length());
        return sb.toString();
    }

    /** Reads the next token from standard input (used for test case count). */
    private String nextToken() throws IOException {
        while (st == null || !st.hasMoreTokens()) {
            st = new StringTokenizer(reader.readLine());
        }
        return st.nextToken();
    }

    /** Reads an {@code int} from the input stream. */
    private int nextInt() throws IOException {
        return Integer.parseInt(nextToken());
    }

    /** Reads a {@code String} token – the actual passwords. */
    private String nextPassword() throws IOException {
        return nextToken();
    }

    /** Core driver: reads test count and processes each password. */
    private void solve() throws IOException {
        String tc = nextToken();                     // number of test cases
        int testCount = Integer.parseInt(tc);

        StringBuilder output = new StringBuilder();
        for (int i = 0; i < testCount; i++) {
            String pwd = nextPassword();
            String fixed = fixPassword(pwd);
            output.append(fixed).append('\n');
        }
        System.out.print(output.toString());
    }

    /** Starts the program. */
    public static void main(String[] args) throws Exception {
        new PasswordFixer().solve();
    }
}

import java.util.List;
import java.util.Scanner;

/**
 * Refactored version of the original program.
 *
 * <p>What it does:
 *
 * <ul>
 *   <li>Reads several test strings.</li>
 *   <li>For each string it tries to transform it so that it contains at least
 *       one lower‑case letter, one upper‑case letter and one digit.</li>
 *   <li>Modifications are performed on a {@link StringBuilder} and the first
 *       successful transformation is printed.</li>
 * </ul>
 *
 * <p>The implementation focuses on readability, maintainability and clear
 * separation of concerns:
 *
 * <ul>
 *   <li>Constants for the replacement characters.</li>
 *   <li>Single‑responsibility helper methods.</li>
 *   <li>Immutable checks that never mutate the original builder.</li>
 *   <li>Descriptive method names.</li>
 * </ul>
 */
public class Main {

    /** Character used for a lower‑case replacement. */
    private static final char REPL_LOWER = 'a';

    /** Character used for an upper‑case replacement. */
    private static final char REPL_UPPER = 'A';

    /** Character used for a digit replacement. */
    private static final char REPL_DIGIT = '9';

    /** All possible single‑character replacements. */
    private static final List<Character> SINGLE_REPLACEMENTS =
            List.of(REPL_LOWER, REPL_UPPER, REPL_DIGIT);

    /** All possible two‑character replacements for adjacent positions. */
    private static final List<String> TWO_CHAR_REPLACEMENTS =
            List.of("aA", "a9", "A9");

    /**
     * Determines whether the supplied {@link StringBuilder} already satisfies the
     * “good” condition – i.e., it contains at least one lower‑case letter,
     * one upper‑case letter and one digit.
     *
     * @param sb the string to validate
     * @return {@code true} if the string is good, {@code false} otherwise
     */
    private static boolean isGood(StringBuilder sb) {
        boolean hasLower = sb.chars().anyMatch(c -> c >= 'a' && c <= 'z');
        boolean hasUpper = sb.chars().anyMatch(c -> c >= 'A' && c <= 'Z');
        boolean hasDigit = sb.chars().anyMatch(c -> c >= '0' && c <= '9');
        return hasLower && hasUpper && hasDigit;
    }

    /** Prints the current content of the builder followed by a newline. */
    private static void print(StringBuilder sb) {
        System.out.println(sb);
    }

    /**
     * Tries to fix the string by replacing a single character with one of the
     * allowed replacement characters. If a successful replacement is found,
     * it is printed and {@code true} is returned.
     *
     * @param sb the mutable string to attempt to fix
     * @return {@code true} if a replacement succeeded, {@code false} otherwise
     */
    private static boolean trySingleCharReplacement(StringBuilder sb) {
        for (int i = 0; i < sb.length(); i++) {
            char original = sb.charAt(i);
            for (char repl : SINGLE_REPLACEMENTS) {
                sb.setCharAt(i, repl);
                if (isGood(sb)) {
                    print(sb);
                    return true;
                }
                sb.setCharAt(i, original); // restore for next iteration
            }
        }
        return false;
    }

    /**
     * Tries to fix the string by replacing any adjacent pair of characters with
     * one of the predefined two‑character patterns. If a successful replacement
     * is found, it is printed and {@code true} is returned.
     *
     * @param sb the mutable string to attempt to fix
     * @return {@code true} if a replacement succeeded, {@code false} otherwise
     */
    private static boolean tryTwoCharReplacement(StringBuilder sb) {
        for (int i = 0; i < sb.length() - 1; i++) {
            String originalPair = sb.substring(i, i + 2);
            for (String repl : TWO_CHAR_REPLACEMENTS) {
                sb.replace(i, i + 2, repl);
                if (isGood(sb)) {
                    print(sb);
                    return true;
                }
                // restore original characters before trying next pattern
                sb.replace(i, i + 2, originalPair);
            }
        }
        return false;
    }

    /**
     * Orchestrates the fixing process. It first attempts single‑character
     * modifications and, if none succeed, proceeds to adjacent‑pair replacements.
     *
     * @param sb the string to attempt to fix; it will be mutated only when a
     *           successful transformation is found
     */
    public static void solve(StringBuilder sb) {
        // 1️⃣ Try fixing with a single‑character replacement.
        if (trySingleCharReplacement(sb)) {
            return;
        }

        // 2️⃣ If that failed, try fixing with an adjacent‑pair replacement.
        tryTwoCharReplacement(sb);
        // No return value needed – the method prints only when a fix is found.
    }

    /** Entry point of the program. */
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int testCases = scanner.nextInt();

        while (testCases-- > 0) {
            String raw = scanner.next();
            solve(new StringBuilder(raw));
        }

        scanner.close();
    }
}

import java.util.Scanner;

/**
 * Refactored version of the original program.
 * The logic has been extracted into small, well‑named methods
 * to improve readability, testability and maintainability.
 */
public class Solution {

    private static final String PREFIX_AA = "aA";
    private static final String PREFIX_A1 = "a1";
    private static final String PREFIX_1A = "1A";

    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            int testCases = scanner.nextInt();
            scanner.nextLine();               // consume end‑of‑line after the integer
            for (int i = 0; i < testCases; i++) {
                String line = scanner.nextLine();
                System.out.println(process(line));
            }
        }
    }

    /**
     * Entry point for a single test case.
     *
     * @param input the raw line read from STDIN
     * @return the transformed string according to the original rules
     */
    private static String process(String input) {
        // -----------------------------------------------------------------
        // 1️⃣  Gather statistics about the characters in the input line
        // -----------------------------------------------------------------
       _stats stats = analyse(input);

        // -----------------------------------------------------------------
        // 2️⃣  Apply the transformation rules (mirroring the original flow)
        // -----------------------------------------------------------------
        switch (true) {
            case (stats.lowerCount == 0 && stats.upperCount == 0) -> {
                // No letters at all → replace the first two characters with "aA"
                return PREFIX_AA + input.substring(2);
            }
            case (stats.lowerCount == 0 && stats.nonLetterCount == 0) -> {
                // Only uppercase letters → replace the first two characters with "a1"
                return PREFIX_A1 + input.substring(2);
            }
            case (stats.nonLetterCount == 0 && stats.upperCount == 0) -> {
                // Only lowercase letters → replace the first two characters with "1A"
                return PREFIX_1A + input.substring(2);
            }
            case (stats.lowerCount == 0) -> {
                // No lowercase letters → insert 'a' somewhere
                return insertChar(
                        input,
                        decideInsertionIndex(stats, true, false),
                        'a'                           // character to insert
                );
            }
            case (stats.upperCount == 0) -> {
                // No uppercase letters → insert 'A' somewhere
                return insertChar(
                        input,
                        decideInsertionIndex(stats, false, true),
                        'A'
                );
            }
            case (stats.nonLetterCount == 0) -> {
                // No non‑letter characters → insert '1' somewhere
                return insertChar(
                        input,
                        decideInsertionIndex(stats, false, false),
                        '1'
                );
            }
            default -> {
                // No special rule applies → return the original string unchanged
                return input;
            }
        }
    }

    /** Simple container for the statistics we need. */
    private static final class _stats {
        final int lowerCount;
        final int upperCount;
        final int nonLetterCount;
        final int lastLowerIdx;
        final int lastUpperIdx;
        final int lastNonLetterIdx;

        _stats(int lower, int upper, int nonLetter,
               int lastLower, int lastUpper, int lastNonLetter) {
            this.lowerCount = lower;
            this.upperCount = upper;
            this.nonLetterCount = nonLetter;
            this.lastLowerIdx = lastLower;
            this.lastUpperIdx = lastUpper;
            this.lastNonLetterIdx = lastNonLetter;
        }
    }

    /** Analyse the string and store the required character counts / indices. */
    private static _stats analyse(String s) {
        int lower = 0, upper = 0, nonLetter = 0;
        int lastLower = -1, lastUpper = -1, lastNonLetter = -1;

        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (Character.isLowerCase(c)) {
                lower++;
                lastLower = i;
            } else if (Character.isUpperCase(c)) {
                upper++;
                lastUpper = i;
            } else {
                nonLetter++;
                lastNonLetter = i;
            }
        }
        return new _stats(lower, upper, nonLetter, lastLower, lastUpper, lastNonLetter);
    }

    /**
     * Determines the index where a character should be inserted.
     *
     * @param stats   the collected statistics
     * @param useUpperIfMissingLower  flag that mirrors the original branching
     * @param useLowerIfMissingUpper  flag that mirrors the original branching
     * @return the index to use for insertion
     */
    private static int decideInsertionIndex(_stats stats,
                                            boolean useUpperIfMissingLower,
                                            boolean useLowerIfMissingUpper) {
        // The original code distinguishes three situations:
        //   • more than one “non‑letter” (digits / others) → use the last non‑letter index
        //   • otherwise → fall back to the last index of the other relevant group
        if (stats.lowerCount == 0 && useUpperIfMissingLower) {
            // We are in the “no lowercase” branch.
            return stats.nonLetterCount > 1 ? stats.lastNonLetterIdx : stats.lastUpperIdx;
        }
        if (stats.upperCount == 0 && useLowerIfMissingUpper) {
            // We are in the “no uppercase” branch.
            return stats.nonLetterCount > 1 ? stats.lastNonLetterIdx : stats.lastLowerIdx;
        }
        // This path is only taken for the “no non‑letter” branch.
        return stats.upperCount > 1 ? stats.lastUpperIdx : stats.lastLowerIdx;
    }

    /**
     * Returns a new string where a single character is inserted at the supplied index.
     *
     * @param source        the original string
     * @param index         position where the insertion should happen
     * @param insertionChar the character to insert
     * @return the modified string
     */
    private static String insertChar(String source, int index, char insertionChar) {
        if (index < 0 || index >= source.length()) {
            return source; // safety guard – should not happen with the current logic
        }
        return source.substring(0, index) + insertionChar + source.substring(index + 1);
    }
}

import java.io.*;
import java.util.*;
import java.util.function.Predicate;
import java.util.stream.Collectors;

/**
 * Entry point of the application.
 * Reads multiple test cases, processes each password and prints the result.
 */
public class Main {

    public static void main(String[] args) {
        // Use try‑with‑resources to guarantee proper closing of I/O streams
        try (InputStream inStream = System.in;
             OutputStream outStream = System.out) {

            InputReader reader = new InputReader(inStream);
            PrintWriter writer = new PrintWriter(outStream);

            int testCaseCount = Integer.parseInt(reader.next());

            // Process each test case independently
            for (int caseIdx = 0; caseIdx < testCaseCount; caseIdx++) {
                String password = reader.next();
                PasswordProcessor processor = new PasswordProcessor();
                writer.println(processor.process(password));
            }

            writer.flush();        // Ensure all output is flushed before closing
            writer.close();
        } catch (IOException e) {
            // Propagate checked exceptions as unchecked to keep main signature simple
            throw new RuntimeException("I/O error", e);
        }
    }

    /**
     * Reads tokens from an underlying {@link InputStream}.
     * Handles tokenisation and line reading in a compact way.
     */
    static class InputReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        InputReader(InputStream source) {
            this.reader = new BufferedReader(new InputStreamReader(source));
        }

        /** Returns the next available token, reading a new line if necessary. */
        String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                tokenizer = new StringTokenizer(readLine());
            }
            return tokenizer.nextToken();
        }

        /** Reads a complete line from the underlying reader. */
        String readLine() {
            try {
                return reader.readLine();
            } catch (IOException e) {
                throw new RuntimeException(e);
            }
        }
    }

    /**
     * Encapsulates the logic that determines whether a password meets the policy.
     */
    static class PasswordValidator {

        /** Checks that the password contains at least one lower‑case, one upper‑case and one digit. */
        boolean isValid(String password) {
            return hasLowerCase(password) && hasUpperCase(password) && hasDigit(password);
        }

        private boolean hasLowerCase(String s) {
            return s.chars().anyMatch(Character::isLowerCase);
        }

        private boolean hasUpperCase(String s) {
            return s.chars().anyMatch(Character::isUpperCase);
        }

        private boolean hasDigit(String s) {
            return s.chars().anyMatch(Character::isDigit);
        }
    }

    /**
     * Performs the transformation of a password until it becomes valid,
     * respecting the allowed replacement operation.
     */
    static class PasswordProcessor {

        /**
         * Main entry point for processing a single password.
         *
         * @param password the original password
         * @return the resulting (potentially modified) password
         */
        String process(String password) {
            // Apply replacements only while the password is invalid
            while (!new PasswordValidator().isValid(password)) {
                password = applySingleReplacement(password);
                if (password == null) {
                    // No valid replacement could be found – break the loop
                    break;
                }
            }
            return password;
        }

        /**
         * Attempts to replace a single contiguous segment of length 1‑3 with a
         * character determined by a 3‑bit mask. If a valid replacement is found,
         * the new password is returned; otherwise {@code null} is returned.
         */
        private String applySingleReplacement(String password) {
            int maxLen = 3;                                 // maximum length to replace
            for (int len = 1; len <= maxLen; len++) {       // length of the segment to replace
                for (int start = 0; start <= password.length() - len; start++) {
                    for (int mask = 1; mask < (1 << 3); mask++) { // 3‑bit mask (1‑7)
                        if (Integer.bitCount(mask) != len) {
                            continue; // mask must have exactly `len` bits set
                        }
                        String replacement = maskToChars(mask);
                        String candidate = replaceSegment(password, start, len, replacement);
                        if (new PasswordValidator().isValid(candidate)) {
                            return candidate; // success – return the transformed password
                        }
                    }
                }
            }
            // No transformation led to a valid password
            return null;
        }

        /**
         * Converts a 3‑bit mask into the corresponding string of characters.
         * Bit 0 → 'a', Bit 1 → 'A', Bit 2 → '1'.
         */
        private String maskToChars(int mask) {
            StringBuilder sb = new StringBuilder(Integer.bitCount(mask));
            if ((mask & 1) != 0) sb.append('a');
            if ((mask & 2) != 0) sb.append('A');
            if ((mask & 4) != 0) sb.append('1');
            return sb.toString();
        }

        /**
         * Replaces the substring [start, start+len) with {@code replacement}.
         */
        private String replaceSegment(String source, int start, int len, String replacement) {
            return source.substring(0, start)
                    + replacement
                    + source.substring(start + len);
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.PrintWriter;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

/**
 * Refactored version of the original solution.
 * The program reads several test cases, each consisting of a single string.
 * For every test case it finds the shortest contiguous substring that can be
 * replaced so that the whole string contains at least one digit, one
 * uppercase letter and one lowercase letter. The replacement string is built
 * from the missing categories and padded with ‘0’ to the same length as the
 * replaced segment. Among all possible replacements the one that uses the
 * smallest segment length is printed.
 */
public class Main {

    /** Entry point of the program. */
    public static void main(String[] args) {
        MyScanner scanner = new MyScanner();
        PrintWriter writer = new PrintWriter(System.out);
        new Task().solve(scanner, writer);
        writer.close();
    }

    /**
     * Core logic class that processes the input and produces the output.
     */
    private static final class Task {

        private PrintWriter out;
        private MyScanner in;

        /** Length of the best (shortest) segment found so far. */
        private int bestLen = Integer.MAX_VALUE;
        /** Result string that corresponds to the best segment. */
        private String bestResult;

        /** Solves one test case after the input has been wired up. */
        void solve(MyScanner in, PrintWriter out) {
            this.out = out;
            this.in = in;

            int t = in.nextInt();
            for (int tt = 0; tt < t; tt++) {
                bestLen = Integer.MAX_VALUE;
                bestResult = null;
                String s = in.next();

                evaluate(s);
                out.println(bestResult);
            }
        }

        /** Scans the string and tries every possible replacement segment. */
        private void evaluate(String s) {
            for (int start = 0; start < s.length(); start++) {
                for (int end = start; end <= s.length(); end++) {
                    attemptReplacement(s, start, end);
                }
            }
        }

        /**
         * Tries to replace the substring {@code [start, end)}.
         * If the replacement is feasible and yields a shorter segment than the
         * current best, the global best is updated.
         */
        private void attemptReplacement(String s, int start, int end) {
            MissingInfo info = missingInfoOutside(s, start, end);
            if (info.missingCount() > end - start) {
                return;                       // not enough space to satisfy missing types
            }

            StringBuilder repl = new StringBuilder(end - start);
            if (!info.hasDigit()) {
                repl.append('1');
            }
            if (!info.hasUpper()) {
                repl.append('A');
            }
            if (!info.hasLower()) {
                repl.append('a');
            }
            // Pad with '0' until the builder length matches the segment length.
            while (repl.length() < end - start) {
                repl.append('0');
            }

            String candidate = s.substring(0, start) + repl + s.substring(end);
            if (end - start < bestLen) {
                bestLen = end - start;
                bestResult = candidate;
            }
        }

        /**
         * Determines which character categories (digit, uppercase, lowercase)
         * are present *outside* the given segment [start, end).
         */
        private MissingInfo missingInfoOutside(String s, int start, int end) {
            boolean hasDigit = false, hasUpper = false, hasLower = false;

            // Prefix part (0 .. start)
            for (int i = 0; i < start; i++) {
                char c = s.charAt(i);
                if (Character.isDigit(c)) {
                    hasDigit = true;
                } else if (Character.isUpperCase(c)) {
                    hasUpper = true;
                } else if (Character.isLowerCase(c)) {
                    hasLower = true;
                }
            }

            // Suffix part (end .. end of string)
            for (int i = end; i < s.length(); i++) {
                char c = s.charAt(i);
                if (Character.isDigit(c)) {
                    hasDigit = true;
                } else if (Character.isUpperCase(c)) {
                    hasUpper = true;
                } else if (Character.isLowerCase(c)) {
                    hasLower = true;
                }
            }

            return new MissingInfo(hasDigit, hasUpper, hasLower);
        }

        /** Simple holder for the three boolean flags. */
        private static final class MissingInfo {
            private final boolean hasDigit;
            private final boolean hasUpper;
            private final boolean hasLower;

            MissingInfo(boolean hasDigit, boolean hasUpper, boolean hasLower) {
                this.hasDigit = hasDigit;
                this.hasUpper = hasUpper;
                this.hasLower = hasLower;
            }

            boolean hasDigit() { return hasDigit; }
            boolean hasUpper() { return hasUpper; }
            boolean hasLower() { return hasLower; }

            /** Number of missing categories. */
            int missingCount() {
                int cnt = 0;
                if (!hasDigit) cnt++;
                if (!hasUpper) cnt++;
                if (!hasLower) cnt++;
                return cnt;
            }
        }
    }

    /**
     * Minimal scanner that reads whitespace‑separated tokens from {@code stdin}.
     * It mirrors the behaviour of the original implementation but throws
     * unchecked exceptions for I/O problems to keep the code tidy.
     */
    public static class MyScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public MyScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        /** Returns the next token, blocking until one is available. */
        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return st.nextToken();
        }

        /** Convenience wrappers kept for compatibility with the original code. */
        int nextInt()          { return Integer.parseInt(next()); }
        long nextLong()        { return Long.parseLong(next()); }
        double nextDouble()    { return Double.parseDouble(next()); }
        String nextLine()      {
            try {
                return br.readLine();
            } catch (IOException e) {
                throw new RuntimeException(e);
            }
        }
    }
}

import java.io.*;
