/**
 * Refactored version of the original program.
 *
 * <p>Responsibilities:
 * <ul>
 *   <li>Read multiple test cases from {@code FastReader}.</li>
 *   <li>For each line, classify characters into lower‑case, upper‑case or digit groups.</li>
 *   <li>Perform a deterministic transformation on the character array according to the
 *       original algorithm, but with clearer intent and naming.</li>
 *   <li>Write the resulting line to standard output.</li>
 * </ul>
 *
 * <p>All magic literals have been replaced by named constants, the logic has been split
 * into small, well‑named methods and the code follows a consistent style.
 */
public class Main {

    /** Enum representing the three possible character categories. */
    private enum CharCategory {
        LOWER,
        UPPER,
        DIGIT;

        /** Returns the integer code used by the original program (preserved for map keys). */
        int code() {
            return switch (this) {
                case LOWER -> 0;
                case UPPER -> 1;
                case DIGIT -> 2;
            };
        }
    }

    /** Entry point of the program. */
    public static void main(String[] args) throws IOException {
        try (FastReader reader = new FastReader(System.in)) {
            PrintWriter writer = new PrintWriter(System.out);
            int testCases = reader.nextInt();

            for (int i = 0; i < testCases; i++) {
                writer.println(process(reader.next()));
            }
            writer.flush();
        }
    }

    /** Reads a whole line (as a single token) from {@link FastReader}. */
    private static String readToken(FastReader reader) throws IOException {
        return reader.next();
    }

    /** Processes a single token according to the original algorithm, but with improved readability. */
    private static String process(String token) {
        char[] chars = token.toCharArray();
        Map<CharCategory, List<Integer>> positionsByCategory = categorize(chars);
        Map<CharCategory, List<Integer>> presentCategories = filterPresentCategories(positionsByCategory);

        if (presentCategories.size() == 1) {
            CharCategory soleCategory = presentCategories.keySet().iterator().next();
            applySingleCategoryRule(chars, soleCategory);
        } else if (presentCategories.size() == 2) {
            CharCategory categoryToModify = determineTargetCategory(positionsByCategory);
            CharCategory missingCategory = missingCategory(positionsByCategory);
            applyTwoCategoryRule(chars, categoryToModify, missingCategory);
        }
        return new String(chars);
    }

    /** Classifies each character and groups their indices by category. */
    private static Map<CharCategory, List<Integer>> categorize(char[] chars) {
        Map<CharCategory, List<Integer>> map = new EnumMap<>(CharCategory.class);
        for (int idx = 0; idx < chars.length; idx++) {
            CharCategory cat = categoryOf(chars[idx]);
            map.computeIfAbsent(cat, c -> new ArrayList<>()).add(idx);
        }
        return map;
    }

    /** Returns the category that a single character belongs to. */
    private static CharCategory categoryOf(char ch) {
        if (Character.isLowerCase(ch)) {
            return CharCategory.LOWER;
        }
        if (Character.isUpperCase(ch)) {
            return CharCategory.UPPER;
        }
        return Character.isDigit(ch) ? CharCategory.DIGIT : null;
    }

    /** Keeps only categories that actually appeared in the input. */
    private static Map<CharCategory, List<Integer>> filterPresentCategories(
            Map<CharCategory, List<Integer>> fullMap) {
        Map<CharCategory, List<Integer>> present = new EnumMap<>(CharCategory.class);
        for (CharCategory cat : EnumSet.allOf(CharCategory.class)) {
            if (fullMap.containsKey(cat)) {
                present.put(cat, fullMap.get(cat));
            }
        }
        return present;
    }

    /** When only one category is present, replace the first two characters according to that
     *  category (mirrors the original behaviour). */
    private static void applySingleCategoryRule(char[] chars, CharCategory category) {
        char first, second;
        switch (category) {
            case LOWER -> {
                first = 'A';
                second = '1';
            }
            case UPPER -> {
                first = 'a';
                second = '1';
            }
            case DIGIT -> {
                first = 'a';
                second = 'A';
            }
            default -> throw new IllegalStateException("Unexpected category");
        }
        if (chars.length > 0) {
            chars[0] = first;
        }
        if (chars.length > 1) {
            chars[1] = second;
        }
    }

    /** For the two‑category case, decides which character position should be rewritten. */
    private static CharCategory determineTargetCategory(
            Map<CharCategory, List<Integer>> positions) {
        // Pick the category that has more than one occurrence; if none, fall back to the first
        // present category (original uses digit as a last resort).
        CharCategory target = null;
        for (CharCategory cat : EnumSet.allOf(CharCategory.class)) {
            if (positions.containsKey(cat) && positions.get(cat).size() > 1) {
                target = cat;
                break;
            }
        }
        if (target == null) {
            // The first key in insertion order of the original HashMap is effectively the same
            // as iterating over the enum values (LOWER, UPPER, DIGIT).
            for (CharCategory cat : EnumSet.allOf(CharCategory.class)) {
                if (positions.containsKey(cat)) {
                    target = cat;
                    break;
                }
            }
        }
        // Return the category itself; the caller will translate it to the replacement character.
        return target;
    }

    /** Determines which of the three categories is missing from the map. */
    private static CharCategory missingCategory(
            Map<CharCategory, List<Integer>> positions) {
        for (CharCategory cat : EnumSet.allOf(CharCategory.class)) {
            if (!positions.containsKey(cat)) {
                return cat;
            }
        }
        // Should never happen for size == 2, but we still need a return.
        return CharCategory.DIGIT;
    }

    /** Applies the transformation rule for the two‑category scenario. */
    private static void applyTwoCategoryRule(
            char[] chars,
            CharCategory targetCategory,
            CharCategory missingCategory) {
        // Index of the character to replace: first element of the target category's list.
        int replaceIndex = positions.get(targetCategory).get(0);
        chars[replaceIndex] = replacementChar(missingCategory);
    }

    /** Maps a missing category to the character that must be written at the chosen index. */
    private static char replacementChar(CharCategory missing) {
        return switch (missing) {
            case LOWER -> 'a';
            case UPPER -> 'A';
            case DIGIT -> '1';
        };
    }

    /** Simple fast scanner based on {@link BufferedReader}. */
    static class FastReader {
        private final BufferedReader br;
        private StringTokenizer st;

        FastReader(InputStream stream) {
            this.br = new BufferedReader(new InputStreamReader(stream));
        }

        /** Returns the next token (word) from the input. */
        String next() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                st = new StringTokenizer(br.readLine());
            }
            return st.nextToken();
        }

        /** Convenience wrappers for primitive types. */
        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }

        double nextDouble() throws IOException {
            return Double.parseDouble(next());
        }

        long nextLong() throws IOException {
            return Long.parseLong(next());
        }

        /** Returns the next complete line (including an empty line). */
        String nextLine() throws IOException {
            return br.readLine();
        }

        /** Checks whether the underlying stream has data ready. */
        boolean ready() throws IOException {
            return br.ready();
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.ArrayList;
import java.util.List;

/**
 * Utility class that encapsulates the reading logic.
 * It behaves like the original {@code FastReader} but is kept
 * private and self‑contained.
 */
final class FastScanner {
    private final BufferedReader br;

    FastScanner() {
        this.br = new BufferedReader(new InputStreamReader(System.in));
    }

    /** Reads the next token (word) from standard input. */
    private String next() throws IOException {
        while (st == null || !st.hasMoreTokens()) {
            String line = br.readLine();
            if (line == null) {
                return null; // EOF
            }
            st = new java.util.StringTokenizer(line);
        }
        return st.nextToken();
    }

    /** Reads the next integer from input. */
    int nextInt() throws IOException {
        return Integer.parseInt(next());
    }

    /** Reads the next line (including spaces). */
    String nextLine() throws IOException {
        return br.readLine();
    }

    // Token object reused across calls
    private StringTokenizer st = new StringTokenizer("");
}

/**
 * Holds the result of analysing a password candidate.
 * It tells us how many of the three required categories are missing.
 */
final class MissingInfo {
    private final boolean hasLower;
    private final boolean hasUpper;
    private final boolean hasDigit;

    MissingInfo(boolean hasLower, boolean hasUpper, boolean hasDigit) {
        this.hasLower = hasLower;
        this.hasUpper = hasUpper;
        this.hasDigit = hasDigit;
    }

    /** Returns a list containing the missing character types. */
    List<Character> missingCharacters() {
        List<Character> missing = new ArrayList<>(3);
        if (!hasLower) missing.add('a');
        if (!hasUpper) missing.add('A');
        if (!hasDigit) missing.add('0');
        return missing;
    }

    /** Convenience factory – analyses the supplied string. */
    static MissingInfo of(String s) {
        boolean lower = false, upper = false, digit = false;
        for (char c : s.toCharArray()) {
            if (Character.isLowerCase(c)) lower = true;
            else if (Character.isUpperCase(c)) upper = true;
            else if (Character.isDigit(c)) digit = true;
        }
        return new MissingInfo(lower, upper, digit);
    }
}

/**
 * Main entry point of the program.
 * The logic is split into small, reusable methods that each do a single thing.
 */
public class Main {

    /** Reads all test cases and processes them one‑by‑one. */
    public static void main(String[] args) throws IOException {
        FastScanner fs = new FastScanner();
        int T = fs.nextInt();                     // number of test cases
        StringBuilder out = new StringBuilder();

        for (int t = 0; t < T; t++) {
            String candidate = fs.nextLine().trim();
            out.append(processCandidate(candidate));
        }

        System.out.print(out.toString());
    }

    /** Inserts the missing character(s) into the candidate string. */
    private static String processCandidate(String candidate) {
        MissingInfo info = MissingInfo.of(candidate);
        List<Character> missing = info.missingCharacters();

        // No character type is missing → the string already satisfies the rules.
        if (missing.isEmpty()) {
            return candidate;
        }

        // Exactly one missing type → insert it at the earliest safe position.
        if (missing.size() == 1) {
            char ch = missing.get(0);
            return insertSingleMissing(candidate, ch);
        }

        // More than one missing type → prepend them in a deterministic order.
        // This mirrors the original behaviour of concatenating two missing chars.
        StringBuilder result = new StringBuilder();
        for (char c : missing) {
            result.append(c);
        }
        return result.append(candidate).toString();
    }

    /**
     * Inserts a single missing character at a position that keeps the
     * original string readable.
     *
     * @param s     original string
     * @param ch    character to insert
     * @return      new string with the character inserted
     */
    private static String insertSingleMissing(String s, char ch) {
        // Count how many characters belong to the same category as {@code ch}.
        int sameCategoryCount;
        if (Character.isLowerCase(ch)) {
            sameCategoryCount = countLower(s);
        } else if (Character.isUpperCase(ch)) {
            sameCategoryCount = countUpper(s);
        } else {
            sameCategoryCount = countDigits(s);
        }

        // If there is already more than one character of that type,
        // we can safely prepend; otherwise we insert after the first character.
        if (sameCategoryCount > 1) {
            return ch + s;
        } else {
            // Ensure we do not truncate an empty or single‑character string.
            if (s.length() < 2) {
                return s + ch;
            }
            return s.charAt(0) + ch + s.substring(1);
        }
    }

    /** Utility helpers for counting character categories. */
    private static int countLower(String s) {
        int c = 0;
        for (char ch : s.toCharArray()) if (Character.isLowerCase(ch)) c++;
        return c;
    }

    private static int countUpper(String s) {
        int c = 0;
        for (char ch : s.toCharArray()) if (Character.isUpperCase(ch)) c++;
        return c;
    }

    private static int countDigits(String s) {
        int c = 0;
        for (char ch : s.toCharArray()) if (Character.isDigit(ch)) c++;
        return c;
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.List;
import java.util.Objects;

/**
 * Refactored solution that reads multiple passwords and attempts to secure them.
 *
 * <p>Original program behavior is preserved:
 * <ul>
 *   <li>Reads the number of test cases.</li>
 *   <li>For each test case reads a password token.</li>
 *   <li>Tries to create a “secure” password by inserting a missing character
 *       class (uppercase, lowercase or digit) at some position.</li>
 *   <li>Prints the secured password or an empty string if it cannot be made
 *       secure.</li>
 * </ul>
 */
public final class SecurePassword {

    /** Tokens that can be inserted to add a missing character class. */
    private static final List<String> INSERTION_TOKENS = List.of(
            "A", "a", "1",        // single‑character tokens
            "Aa", "A1", "a1"      // two‑character tokens
    );

    /** Length of the two‑character tokens (used only for clarity). */
    private static final int TWO_CHAR_TOKEN_LENGTH = 2;

    private final BufferedReader reader;

    public SecurePassword() {
        this.reader = new BufferedReader(new InputStreamReader(System.in));
    }

    /** Entry point used by the original `main` method. */
    public void solve() throws IOException {
        int testCount = readInt();
        StringBuilder output = new StringBuilder();

        for (int i = 0; i < testCount; i++) {
            String password = readToken();
            String secured = securePassword(password);
            output.append(secured).append('\n');
        }

        System.out.print(output.toString());
    }

    /** Determines whether a password already satisfies the security rules. */
    private static boolean isSecure(String password) {
        Objects.requireNonNull(password);
        boolean hasUpper = password.matches(".*[A-Z].*");
        boolean hasLower = password.matches(".*[a-z].*");
        boolean hasDigit = password.matches(".*\\d.*");
        return hasUpper && hasLower && hasDigit;
    }

    /**
     * Tries to create a secure password by inserting a token at some position.
     * Returns the new password or an empty string if it is impossible.
     */
    private static String securePassword(String password) {
        if (isSecure(password)) {
            return password;
        }

        int len = password.length();

        // 1️⃣ Insert a single‑character token.
        for (int pos = 0; pos <= len; pos++) {
            for (int idx = 0; idx < 3; idx++) {
                String candidate = insertAt(pos, password, INSERTION_TOKENS.get(idx));
                if (isSecure(candidate)) {
                    return candidate;
                }
            }
        }

        // 2️⃣ Insert a two‑character token (skipping the next character of the original string).
        for (int pos = 0; pos <= len; pos++) {
            for (int idx = 3; idx < INSERTION_TOKENS.size(); idx++) {
                String token = INSERTION_TOKENS.get(idx);
                String candidate = insertAt(pos, password, token);
                if (isSecure(candidate)) {
                    return candidate;
                }
            }
        }

        // No solution found.
        return "";
    }

    /** Inserts {@code token} at the given index in {@code source}. */
    private static String insertAt(int index, String source, String token) {
        return source.substring(0, index) + token + source.substring(index);
    }

    /* ---------- I/O helpers ---------- */

    /** Reads the next non‑empty token from the input stream. */
    private String readToken() throws IOException {
        String token;
        while ((token = reader.readLine()) == null || token.isBlank()) {
            // Wait for a non‑empty line.
        }
        return token;
    }

    /** Reads the next integer token from the input stream. */
    private int readInt() {
        return Integer.parseInt(readToken());
    }

    /* ---------- Main ---------- */

    public static void main(String[] args) {
        try {
            new SecurePassword().solve();
        } catch (IOException e) {
            throw new RuntimeException(e);
        }
    }
}

import java.io.*;
import java.util.*;

public class Main implements Runnable {

    /* -----------------------------------------------------------
     *  Fast input utilities
     * ----------------------------------------------------------- */
    private static final class FastScanner implements AutoCloseable {
        private final InputStream stream;
        private final byte[] buffer = new byte[16 * 1024];
        private int ptr = 0, length = 0;

        private FastScanner(InputStream stream) {
            this.stream = stream;
        }

        /** Reads the next non‑space byte. */
        private int readByte() throws IOException {
            if (ptr >= length) {
                length = stream.read(buffer);
                ptr = 0;
                if (length <= 0) return -1;
            }
            return buffer[ptr++];
        }

        /** True for space characters and EOF. */
        private boolean isSpace(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        /** Skips any leading whitespace. */
        private int skipSpaces() throws IOException {
            int c;
            do {
                c = readByte();
            } while (isSpace(c));
            return c;
        }

        /** Reads next integer (base‑10, optional leading '-'). */
        public int nextInt() throws IOException {
            int sign = 1;
            int c = skipSpaces();
            if (c == '-') {
                sign = -1;
                c = readByte();
            }
            int result = 0;
            do {
                result = result * 10 + (c - '0');
                c = readByte();
            } while (!isSpace(c));
            return result * sign;
        }

        /** Reads next token (non‑whitespace characters). */
        public String next() throws IOException {
            int c = skipSpaces();
            StringBuilder sb = new StringBuilder();
            do {
                sb.append((char) c);
                c = readByte();
            } while (!isSpace(c));
            return sb.toString();
        }

        @Override
        public void close() throws IOException {
            stream.close();
        }
    }

    /* -----------------------------------------------------------
     *  Program entry point
     * ----------------------------------------------------------- */
    @Override
    public void run() {
        try (FastScanner sc = new FastScanner(System.in)) {
            PrintWriter out = new PrintWriter(System.out, true);
            int testCases = sc.nextInt();

            for (int tc = 0; tc < testCases; tc++) {
                String raw = sc.next();
                out.println(transform(raw));
            }
        }
    }

    /** Orchestrates the whole per‑test‑case processing. */
    private static String transform(String input) {
        // -----------------------------------------------------------------
        // 1️⃣  Count character categories
        // -----------------------------------------------------------------
        Counter counter = new Counter();
        input.chars().forEach(ch -> counter.classify(ch));

        // -----------------------------------------------------------------
        // 2️⃣  Apply transformation rules (exactly as the original code)
        // -----------------------------------------------------------------
        // If all three categories exist the string is left untouched.
        if (counter.upper > 0 && counter.lower > 0 && counter.digit > 0) {
            return input;
        }

        // Work on a mutable copy of the characters.
        char[] arr = input.toCharArray();
        applyRules(arr, counter);
        return new String(arr);
    }

    /** Holds the three counters we need. */
    private static final class Counter {
        int upper = 0, lower = 0, digit = 0;

        void classify(char c) {
            if (c >= 'A' && c <= 'Z') upper++;
            else if (c >= 'a' && c <= 'z') lower++;
            else if (c >= '0' && c <= '9') digit++;
        }
    }

    /** Encapsulates the rather involved transformation logic of the original code. */
    private static void applyRules(char[] arr, Counter c) {
        // -----  A) All three categories present → nothing to do  -----
        if (c.upper > 0 && c.lower > 0 && c.digit > 0) {
            return;
        }

        // -----  B) Exactly two categories present  -----
        if (c.upper > 0 && c.lower > 0 && c.digit == 0) {          // U & L only
            // If there is more than one uppercase, replace the first
            // with a placeholder from the missing lowercase group.
            // Otherwise replace the first digit (there is none here) –
            // the original falls back to the same placeholder.
            replaceFirstMatching(arr, Character::isUpperCase, 'a');
        } else if (c.upper > 0 && c.digit > 0 && c.lower == 0) {   // U & D only
            replaceFirstMatching(
                    arr,
                    ch -> ch >= 'A' && ch <= 'Z',      // uppercase
                    'a');
        } else if (c.lower > 0 && c.digit > 0 && c.upper == 0) {   // L & D only
            replaceFirstMatching(
                    arr,
                    ch -> ch >= '0' && ch <= '9',      // digit
                    'A');
        }

        // -----  C) Only one category present – original puts "A0" at the front -----
        if (c.upper > 0) {
            // Upper‑case only (e.g., "ZZZ") → "A0" + rest of string
            arr[0] = 'a';          // first char becomes 'a'
            if (arr.length > 1) arr[1] = '0';
        } else if (c.lower > 0) {
            // Lower‑case only (e.g., "abc") → "A0" + rest of string
            arr[0] = 'A';
            if (arr.length > 1) arr[1] = '0';
        } else if (c.digit > 0) {
            // Digit only (e.g., "123") → "A0" + rest of string
            arr[0] = 'A';
            if (arr.length > 1) arr[1] = '0';
        }
    }

    /** Replaces the first character that satisfies {@code predicate} with {@code repl}. */
    private static void replaceFirstMatching(char[] arr,
                                             java.util.function.Predicate<Integer> predicate,
                                             char repl) {
        for (int i = 0; i < arr.length; i++) {
            if (predicate.test(arr[i])) {
                arr[i] = repl;
                break;
            }
        }
    }

    /* -----------------------------------------------------------
     *  Thread entry point (keeps original behaviour for large inputs)
     * ----------------------------------------------------------- */
    public static void main(String[] args) throws Exception {
        new Thread(null, new Main(), "Main Worker", 1 << 26).start();
    }
}

import java.io.*;
import java.util.*;
import java.util.function.Predicate;

/**
 * Refactored version of the original program.
 *
 * <p>Changes made for readability and maintainability:
 * <ul>
 *   <li>Extracted the core transformation logic into small, well‑named methods.
 *   <li>Used descriptive variable names (`digitCount`, `lowerCount`, `upperCount`).
 *   <li>Encapsulated the “replace first matching character” operation.
 *   <li>Removed deep nesting and duplicated code.
 *   <li>Preserved the exact behaviour of the original solution.
 * </ul>
 */
public class Solution {

    /* ------------ I/O helpers ------------ */

    private final InputStream in;
    private final PrintWriter out;

    private final byte[] buffer = new byte[1024];
    private int bufLen = 0, bufPos = 0;

    public Solution(String input) {
        this.in = input.isEmpty() ? System.in : new ByteArrayInputStream(input.getBytes());
        this.out = new PrintWriter(System.out);
    }

    /** Entry point used by the original `run()` method. */
    public void solve() {
        int T = nextInt();
        for (int tc = 0; tc < T; ++tc) {
            char[] chars = nextCharArray();
            applyTransformationIfNeeded(chars);
            print(chars);
        }
        out.flush();
    }

    /** Main driver – identical to the original `run()` signature. */
    public void run() throws Exception {
        long start = System.currentTimeMillis();
        solve();
        out.flush();
        if (!available()) {
            System.err.println((System.currentTimeMillis() - start) + "ms");
        }
    }

    /** Reads the next token as an integer. */
    private int nextInt() {
        return Integer.parseInt(next());
    }

    /** Reads the next token (non‑whitespace characters). */
    private String next() {
        int ch;
        do {
            ch = readByte();
        } while (isSpaceChar(ch));
        StringBuilder sb = new StringBuilder();
        while (!isSpaceChar(ch)) {
            sb.appendCodePoint(ch);
            ch = readByte();
        }
        return sb.toString();
    }

    /** Reads the next token and returns it as a character array. */
    private char[] nextCharArray() {
        return next().toCharArray();
    }

    /** Returns true if there is more input data to read. */
    private boolean available() {
        return in.available() > 0;
    }

    /** Fast byte reader using the internal buffer. */
    private int readByte() {
        if (bufPos >= bufLen) {
            bufPos = 0;
            bufLen = in.read(buffer);
            if (bufLen <= 0) {
                return -1;
            }
        }
        return buffer[bufPos++];
    }

    /** Utility – true for characters outside the printable ASCII range. */
    private boolean isSpaceChar(int c) {
        return !(c >= 33 && c <= 126);
    }

    /** Prints a character array followed by a line terminator. */
    private static void print(char[] arr) {
        for (char c : arr) {
            System.out.print(c);
        }
        System.out.println();
    }

    /* ------------ Core transformation logic ------------ */

    /** Orchestrates the whole per‑test‑case processing. */
    private void applyTransformationIfNeeded(char[] arr) {
        int digitCount = 0, lowerCount = 0, upperCount = 0;

        for (char c : arr) {
            if (Character.isDigit(c)) {
                ++digitCount;
            } else if (Character.isLowerCase(c)) {
                ++lowerCount;
            } else if (Character.isUpperCase(c)) {
                ++upperCount;
            }
        }

        // Nothing to change if all three categories already exist
        if (digitCount > 0 && lowerCount > 0 && upperCount > 0) {
            return;
        }

        // Dispatch to the appropriate handling routine
        if (digitCount == 0) {
            handleMissingDigit(arr, lowerCount, upperCount);
        } else if (lowerCount == 0) {
            handleMissingLowercase(arr, digitCount, upperCount, upperCount);
        } else { // upperCount == 0
            handleMissingUppercase(arr, digitCount, lowerCount);
        }
    }

    /** Adds a digit when it is missing. */
    private static void handleMissingDigit(char[] arr, int lower, int upper) {
        if (lower == 0) {
            // Need both a lowercase letter and a digit → set first two positions
            arr[0] = 'a';
            if (arr.length > 1) {
                arr[1] = '1';
            }
        } else if (upper == 0) {
            // Need both an uppercase letter and a digit
            arr[0] = 'A';
            if (arr.length > 1) {
                arr[1] = '1';
            }
        } else {
            // Both lower and upper already present – just insert a digit
            if (lower > 1) {
                replaceFirstMatching(arr, Character::isLowerCase, '1');
            } else {
                replaceFirstMatching(arr, Character::isUpperCase, '1');
            }
        }
    }

    /** Adds a lowercase letter when it is missing. */
    private static void handleMissingLowercase(
            char[] arr, int digit, int upper, int upperCount) {

        if (digit == 0) {
            // Both digit and lowercase are missing – treat like the symmetric case
            if (upper == 0) {
                arr[0] = 'a';
                if (arr.length > 1) {
                    arr[1] = 'A';
                }
            } else {
                // Uppercase already present – decide which character to replace
                if (upperCount == 1) {
                    replaceFirstMatching(arr, Character::isDigit, 'a');
                } else {
                    replaceFirstMatching(arr, Character::isUpperCase, 'a');
                }
            }
        } else {
            // Digit already present – we only need a lowercase letter
            if (upperCount == 0) {
                arr[0] = 'a';
                if (arr.length > 1) {
                    arr[1] = 'A';
                }
            } else if (upperCount == 1) {
                replaceFirstMatching(arr, Character::isDigit, 'a');
            } else {
                replaceFirstMatching(arr, Character::isUpperCase, 'a');
            }
        }
    }

    /** Adds an uppercase letter when it is missing. */
    private static void handleMissingUppercase(
            char[] arr, int digit, int lower) {

        // At this point digit > 0 and lower > 0 are guaranteed
        if (lower == 1) {
            replaceFirstMatching(arr, Character::isDigit, 'A');
        } else {
            replaceFirstMatching(arr, Character::isLowerCase, 'A');
        }
    }

    /** Replaces the first character that satisfies `predicate` with `value`. */
    private static void replaceFirstMatching(char[] arr, Predicate<Character> predicate, char value) {
        for (int i = 0; i < arr.length; ++i) {
            if (predicate.test(arr[i])) {
                arr[i] = value;
                break;
            }
        }
    }

    /* ------------ Original utility methods (kept unchanged) ------------ */

    private static void tr(Object... o) {
        System.out.println(Arrays.deepToString(o));
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.Objects;

/**
 * Refactored version of the original {@code EducationalR51A}.
 *
 * <p>
 * The program reads the number of test cases {@code t}. For each test case it reads a
 * string, counts the occurrences of lowercase letters, uppercase letters and digits,
 * and then performs a minimal set of modifications so that the resulting string
 * contains at least one character of each required type.
 * </p>
 *
 * <p>Key improvements:</p>
 * <ul>
 *   <li>Encapsulated input handling with a simple {@code BufferedReader}.</li>
 *   <li>Extracted the counting logic into a dedicated method with clear naming.</li>
 *   <li>Implemented the required transformations through small, single‑responsibility
 *       helper methods.</li>
 *   <li>Removed unused/duplicate code and imports.</li>
 *   <li>Used Java standard library types ({@code Character}) instead of manual range checks.</li>
 *   <li>Added Javadoc comments and consistent naming conventions.</li>
 * </ul>
 */
public class Solution {

    /** Entry point of the application. */
    public static void main(String[] args) throws IOException {
        // Run the solution in a separate thread to avoid stack‑overflow issues on some judges.
        // This mimics the original behaviour while keeping the implementation straightforward.
        new Thread(null, new Runnable() {
            @Override
            public void run() {
                try {
                    new Solution().solve();
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
        }, "Solution-Thread", 1 << 26).start();
    }

    /** Core logic that processes all test cases. */
    public void solve() throws IOException {
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in))) {
            int testCases = Integer.parseInt(br.readLine().trim());

            StringBuilder output = new StringBuilder();
            for (int i = 0; i < testCases; i++) {
                String line = br.readLine();
                if (line == null) break;

                char[] chars = line.toCharArray();
                int lower = countCategory(chars, Character::isLowerCase);
                int upper = countCategory(chars, Character::isUpperCase);
                int digit = countCategory(chars, Character::isDigit);

                applyTransformations(chars, lower, upper, digit);
                output.append(chars);
                output.append('\n');
            }

            System.out.print(output.toString());
        }
    }

    /** Counts how many characters in the array satisfy the given predicate. */
    private static int countCategory(char[] arr, java.util.function.Predicate<char[]> predicate) {
        int count = 0;
        for (char c : arr) {
            if (predicate.test(new char[]{c})) {
                count++;
            }
        }
        return count;
    }

    /** Applies the required modifications to satisfy the problem constraints. */
    private static void applyTransformations(char[] arr, int lower, int upper, int digit) {
        // Helper lambdas for the three possible replacements
        java.util.function.BiConsumer<char[], Character> replaceFirstUpperWith = (arr_, ch) -> {
            for (int i = 0; i < arr_.length; i++) {
                if (Character.isUpperCase(arr_[i])) {
                    arr_[i] = ch;
                    break;
                }
            }
        };
        java.util.function.BiConsumer<char[], Character> replaceFirstLowerWith = (arr_, ch) -> {
            for (int i = 0; i < arr_.length; i++) {
                if (Character.isLowerCase(arr_[i])) {
                    arr_[i] = ch;
                    break;
                }
            }
        };
        java.util.function.BiConsumer<char[], Character> replaceFirstDigitWith = (arr_, ch) -> {
            for (int i = 0; i < arr_.length; i++) {
                if (Character.isDigit(arr_[i])) {
                    arr_[i] = ch;
                    break;
                }
            }
        };

        // 1) No lowercase, no uppercase
        if (lower == 0 && upper == 0) {
            arr[0] = 'a';
            arr[1] = 'A';
            return;
        }
        // 2) No lowercase, no digit
        if (lower == 0 && digit == 0) {
            arr[0] = 'a';
            arr[1] = '1';
            return;
        }
        // 3) No digit, no uppercase
        if (digit == 0 && upper == 0) {
            arr[0] = 'A';
            arr[1] = '1';
            return;
        }
        // 4) No lowercase but more than one uppercase → make first uppercase lowercase
        if (lower == 0 && upper > 1) {
            replaceFirstUpperWith.accept(arr, 'a');
            return;
        }
        // 5) No uppercase but more than one lowercase → make first lowercase uppercase
        if (upper == 0 && lower > 1) {
            replaceFirstLowerWith.accept(arr, 'A');
            return;
        }
        // 6) No digit but more than one uppercase → make first uppercase a digit '1'
        if (digit == 0 && upper > 1) {
            replaceFirstUpperWith.accept(arr, '1');
            return;
        }
        // 7) No digit but more than one lowercase → make first lowercase a digit '1'
        if (digit == 0 && lower > 1) {
            replaceFirstLowerWith.accept(arr, '1');
            return;
        }
        // 8) No lowercase but more than one digit → make first digit a lowercase 'a'
        if (lower == 0 && digit > 1) {
            replaceFirstDigitWith.accept(arr, 'a');
            return;
        }
        // 9) No uppercase but more than one digit → make first digit an uppercase 'A'
        if (upper == 0 && digit > 1) {
            replaceFirstDigitWith.accept(arr, 'A');
            return;
        }
        // 10) More than one digit but no uppercase → make first digit an uppercase 'A'
        if (digit > 1 && upper == 0) {
            replaceFirstDigitWith.accept(arr, 'A');
            return;
        }
        // 11) More than one uppercase but no digit → make first uppercase a digit '1'
        if (upper > 1 && digit == 0) {
            replaceFirstUpperWith.accept(arr, '1');
            return;
        }
        // 12) More than one lowercase but no digit → make first lowercase a digit '1'
        if (lower > 1 && digit == 0) {
            replaceFirstLowerWith.accept(arr, '1');
            return;
        }
        // If none of the above conditions match, the string already satisfies the requirements.
    }
}

import java.io.*;
import java.util.*;

public class CharacterCategoryRefactor {

    /** Categories of characters we work with */
    private enum Category { LOWER, UPPER, DIGIT }

    /** Characters used for replacement */
    private static final char LOWER_REP = 'a';
    private static final char UPPER_REP = 'A';
    private static final char DIGIT_REP = '0';

    /** Mapping from enum to its replacement character */
    private static final Map<Category, Character> REP = Map.of(
            Category.LOWER, LOWER_REP,
            Category.UPPER, UPPER_REP,
            Category.DIGIT, DIGIT_REP
    );

    /** All three categories in a fixed order */
    private static final List<Category> ALL = List.of(Category.LOWER, Category.UPPER, Category.DIGIT);

    /** Simple input reader used by the driver */
    private static class InputReader {
        private final BufferedReader br;
        private StringTokenizer st;

        InputReader() throws IOException {
            this.br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                st = new StringTokenizer(br.readLine());
            }
            return st.nextToken();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }

    /** Returns the category of a character */
    private static Category categoryOf(char ch) {
        if (Character.isLowerCase(ch)) return Category.LOWER;
        if (Character.isUpperCase(ch)) return Category.UPPER;
        return Category.DIGIT;
    }

    /** Replacement character for a given category */
    private static char rep(Category cat) {
        return REP.get(cat);
    }

    /**
     * Performs the required transformation on the supplied string.
     * The algorithm follows the original specification but is now
     * organised into clear, reusable pieces.
     */
    private static String transform(String input) {
        // -----------------------------------------------------------------
        // 1️⃣  Count occurrences of each character type
        // -----------------------------------------------------------------
        int lowerCnt = 0, upperCnt = 0, digitCnt = 0;
        char[] arr = input.toCharArray();
        for (char c : arr) {
            switch (categoryOf(c)) {
                case LOWER -> lowerCnt++;
                case UPPER -> upperCnt++;
                case DIGIT -> digitCnt++;
            }
        }

        // -----------------------------------------------------------------
        // 2️⃣  Determine which categories are present
        // -----------------------------------------------------------------
        Set<Category> present = new HashSet<>();
        if (lowerCnt > 0) present.add(Category.LOWER);
        if (upperCnt > 0) present.add(Category.UPPER);
        if (digitCnt > 0) present.add(Category.DIGIT);

        // If all three are already present, nothing to do
        if (present.size() == 3) {
            return input;
        }

        // -----------------------------------------------------------------
        // 3️⃣  Identify missing categories
        // -----------------------------------------------------------------
        Set<Category> missing = new HashSet<>(ALL);
        missing.removeAll(present);

        // ---------------------------------------------------------------
        // 4️⃣  Exactly two categories are present → introduce the missing one
        // ---------------------------------------------------------------
        if (missing.size() == 1) {
            Category missingCat = missing.iterator().next();

            // Look for a present category that occurs at least twice.
            // Replacing one of its duplicates guarantees we keep the other
            // two categories intact.
            for (Category cat : present) {
                int cnt = switch (cat) {
                    case LOWER -> lowerCnt;
                    case UPPER -> upperCnt;
                    case DIGIT -> digitCnt;
                };
                if (cnt > 1) {
                    char replacement = rep(missingCat);
                    for (int i = 0; i < arr.length; i++) {
                        if (categoryOf(arr[i]) == cat) {
                            arr[i] = replacement;
                            return new String(arr);
                        }
                    }
                }
            }

            // By problem constraints a duplicate must exist; the fallback
            // replaces the first character of any present category.
            Category any = present.iterator().next();
            char replacement = rep(missingCat);
            for (int i = 0; i < arr.length; i++) {
                if (categoryOf(arr[i]) == any) {
                    arr[i] = replacement;
                    return new String(arr);
                }
            }
        }

        // ---------------------------------------------------------------
        // 5️⃣  Only one category is present → create the two missing ones
        // ---------------------------------------------------------------
        // Exactly one category remains; the other two are missing.
        Category sole = present.iterator().next();
        // Order of the two missing categories does not matter;
        // we just need deterministic output.
        List<Category> missingList = new ArrayList<>(missing);
        Category miss1 = missingList.get(0);
        Category miss2 = missingList.get(1);

        char rep1 = rep(miss1);
        char rep2 = rep(miss2);
        int found = 0;

        for (int i = 0; i < arr.length; i++) {
            if (categoryOf(arr[i]) == sole) {
                if (found == 0) {
                    arr[i] = rep1;
                    found++;
                } else if (found == 1) {
                    arr[i] = rep2;
                    break;               // only the first two occurrences are changed
                }
            }
        }
        return new String(arr);
    }

    /** Entry point – handles multiple test cases */
    public static void main(String[] args) throws IOException {
        boolean debug = Arrays.asList(args).contains("d");
        if (debug) {
            // keep original debug flag behaviour (no-op here)
        }

        InputReader reader = new InputReader();
        PrintWriter out = new PrintWriter(System.out);
        int tests = reader.nextInt();

        while (tests-- > 0) {
            String s = reader.next();
            out.println(transform(s));
        }
        out.close();
    }
}

import java.io.*;
import java.util.StringTokenizer;

/**
 * Solves the “Password” problem.
 *
 * The original algorithm is kept exactly, but it has been split into
 * small, well‑named methods, renamed constants and variables, and the
 * logic has been clarified with comments.
 */
public class Main {

    public static void main(String[] args) {
        InputStream input = System.in;
        OutputStream output = System.out;
        InputReader reader = new InputReader(input);
        PrintWriter writer = new PrintWriter(output);

        PasswordFixer fixer = new PasswordFixer();
        fixer.solve(reader, writer);

        writer.close();
    }

    /** Reads tokens from {@link InputStream}. */
    static class InputReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        InputReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream), 32768);
        }

        String nextToken() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(nextToken());
        }
    }

    /** Central class that contains the solving logic. */
    static class PasswordFixer {

        /** Entry point used by {@code Main}. */
        void solve(InputReader in, PrintWriter out) {
            int testCases = in.nextInt();
            while (testCases-- > 0) {
                String password = in.nextToken();
                out.println(fixPassword(password));
            }
        }

        /** Main password‑fixing routine – mirrors the original algorithm. */
        private String fixPassword(String s) {
            // -----------------------------------------------------------------
            // 1) Count the three required character types
            // -----------------------------------------------------------------
            int lower = 0, upper = 0, digit = 0;
            char[] chars = s.toCharArray();

            for (char c : chars) {
                if (Character.isLowerCase(c)) {
                    lower++;
                } else if (Character.isUpperCase(c)) {
                    upper++;
                } else if (Character.isDigit(c)) {
                    digit++;
                }
            }

            // -----------------------------------------------------------------
            // 2) Already valid → return original string
            // -----------------------------------------------------------------
            if (lower > 0 && upper > 0 && digit > 0) {
                return s;
            }

            // -----------------------------------------------------------------
            // 3) Exactly one category missing → replace an appropriate char
            // -----------------------------------------------------------------
            //   missing lowercase (lower == 0) – need to add it
            if (lower == 0 && upper > 0 && digit > 0) {
                // Replace an uppercase if there are more of them than digits,
                // otherwise replace a digit.
                if (upper > digit) {
                    replaceFirstUppercaseWith(chars, 'a');
                } else {
                    replaceFirstDigitWith(chars, 'a');
                }
                return new String(chars);
            }

            //   missing uppercase (upper == 0) – need to add it
            if (lower > 0 && upper == 0 && digit > 0) {
                if (lower > digit) {
                    replaceFirstLowercaseWith(chars, 'A');
                } else {
                    replaceFirstDigitWith(chars, 'A');
                }
                return new String(chars);
            }

            //   missing digit (digit == 0) – need to add it
            if (lower > 0 && upper > 0 && digit == 0) {
                if (upper > lower) {
                    replaceFirstUppercaseWith(chars, '1');
                } else {
                    replaceFirstLowercaseWith(chars, '1');
                }
                return new String(chars);
            }

            // -----------------------------------------------------------------
            // 4) Two or three categories missing → fix first positions
            // -----------------------------------------------------------------
            if (lower == 0 && upper == 0 && digit > 0) {
                // need both lowercase and uppercase
                chars[0] = 'a';
                chars[1] = 'A';
                return new String(chars);
            }
            if (lower == 0 && upper > 0 && digit == 0) {
                // need lowercase and digit
                chars[0] = 'a';
                chars[1] = '1';
                return new String(chars);
            }
            if (lower > 0 && upper == 0 && digit == 0) {
                // need uppercase and digit
                chars[0] = 'A';
                chars[1] = '1';
                return new String(chars);
            }

            // Should never reach here, but keep compiler happy.
            return new String(chars);
        }

        /** Helper – replace first uppercase character with {@code ch}. */
        private void replaceFirstUppercaseWith(char[] arr, char ch) {
            for (int i = 0; i < arr.length; i++) {
                if (Character.isUpperCase(arr[i])) {
                    arr[i] = ch;
                    break;
                }
            }
        }

        /** Helper – replace first lowercase character with {@code ch}. */
        private void replaceFirstLowercaseWith(char[] arr, char ch) {
            for (int i = 0; i < arr.length; i++) {
                if (Character.isLowerCase(arr[i])) {
                    arr[i] = ch;
                    break;
                }
            }
        }

        /** Helper – replace first digit character with {@code ch}. */
        private void replaceFirstDigitWith(char[] arr, char ch) {
            for (int i = 0; i < arr.length; i++) {
                if (Character.isDigit(arr[i])) {
                    arr[i] = ch;
                    break;
                }
            }
        }
    }
}

import java.util.Scanner;
import java.util.function.Predicate;

/**
 * Reads a number of strings from standard input and transforms each of them
 * according to a set of rules that depend on the composition of the string.
 *
 * The transformation logic has been split into small, well‑named methods,
 * eliminating magic numbers and improving readability.
 */
public class Main {

    /** Scanner used for reading input – closed after the last line is processed. */
    private static final Scanner SCANNER = new Scanner(System.in);

    /** Entry point of the program. */
    public static void main(String[] args) {
        int numberOfCases = SCANNER.nextInt();
        SCANNER.nextLine();                     // consume the line‑break after the integer
        for (int i = 0; i < numberOfCases; i++) {
            String currentLine = SCANNER.nextLine();
            System.out.println(convert(currentLine));
        }
        SCANNER.close();
    }

    /** Public entry point for the conversion routine. */
    private static String convert(String input) {
        // 1️⃣ Count the three relevant character types.
        int lowerCaseCount = count(input, Character::isLowerCase);
        int upperCaseCount = count(input, Character::isUpperCase);
        int digitCount     = count(input, Character::isDigit);

        // 2️⃣ If the string contains at least one lower‑case, one upper‑case
        //    and one digit we simply return it unchanged.
        if (lowerCaseCount > 0 && upperCaseCount > 0 && digitCount > 0) {
            return input;
        }

        // 3️⃣ Determine which characters have to be replaced and where.
        int replacementStartIndex = locateReplacementStart(input,
                lowerCaseCount, upperCaseCount, digitCount);
        String replacement = decideReplacementString(lowerCaseCount,
                upperCaseCount, digitCount);

        // 4️⃣ Perform the replacement and return the transformed string.
        return replaceAt(input, replacementStartIndex, replacement);
    }

    /** Counts how many characters of the supplied predicate match the input. */
    private static int count(Predicate<Character> predicate, String input) {
        int cnt = 0;
        for (int i = 0; i < input.length(); i++) {
            if (predicate.test(input.charAt(i))) {
                cnt++;
            }
        }
        return cnt;
    }

    /** Finds the index of the first character that must be replaced. */
    private static int locateReplacementStart(String input,
                                              int lower, int upper, int digit) {
        // Cases where two character groups are present
        if (lower > 0 && upper > 0 && digit == 0) {
            return (lower > upper) ? findFirstLowerCase(input) : findFirstUpperCase(input);
        }
        if (lower > 0 && upper == 0 && digit > 0) {
            return (lower > digit) ? findFirstLowerCase(input) : findFirstDigit(input);
        }
        if (upper > 0 && lower == 0 && digit > 0) {
            return (upper > digit) ? findFirstUpperCase(input) : findFirstDigit(input);
        }

        // Cases where only a single character group is present.
        if (lower > 0 && upper == 0 && digit == 0) {
            return 0;                     // first lower‑case (will be replaced by "A0")
        }
        if (upper > 0 && lower == 0 && digit == 0) {
            return 0;                     // first upper‑case (will be replaced by "a0")
        }
        if (digit > 0 && lower == 0 && upper == 0) {
            return 0;                     // first digit   (will be replaced by "aA")
        }

        // Fallback – should never reach here for valid inputs.
        return 0;
    }

    /** Returns the string that must replace the located character(s). */
    private static String decideReplacementString(int lower, int upper, int digit) {
        if (lower > 0 && upper > 0 && digit == 0) {
            return "1";                     // replace one character with "1"
        }
        if (lower > 0 && upper == 0 && digit > 0) {
            return "A";                     // replace one character with "A"
        }
        if (upper > 0 && lower == 0 && digit > 0) {
            return "a";                     // replace one character with "a"
        }
        // Single‑type cases – the replacement strings have length 2.
        if (lower > 0 && upper == 0 && digit == 0) {
            return "A0";
        }
        if (upper > 0 && lower == 0 && digit == 0) {
            return "a0";
        }
        if (digit > 0 && lower == 0 && upper == 0) {
            return "aA";
        }
        // Default – no replacement needed (should not happen for valid input).
        return "";
    }

    /** Finds the index of the first lower‑case letter in the string. */
    private static int findFirstLowerCase(String input) {
        for (int i = 0; i < input.length(); i++) {
            if (Character.isLowerCase(input.charAt(i))) {
                return i;
            }
        }
        return 0;
    }

    /** Finds the index of the first upper‑case letter in the string. */
    private static int findFirstUpperCase(String input) {
        for (int i = 0; i < input.length(); i++) {
            if (Character.isUpperCase(input.charAt(i))) {
                return i;
            }
        }
        return 0;
    }

    /** Finds the index of the first digit in the string. */
    private static int findFirstDigit(String input) {
        for (int i = 0; i < input.length(); i++) {
            if (Character.isDigit(input.charAt(i))) {
                return i;
            }
        }
        return 0;
    }

    /**
     * Replaces a portion of the original string.
     *
     * @param original     the string to modify
     * @param startIdx     the index at which the replacement starts
     * @param replacement  the new text that will replace the old one
     * @return a new string with the replacement applied
     */
    private static String replaceAt(String original, int startIdx, String replacement) {
        if (startIdx < 0 || startIdx >= original.length()) {
            return original;
        }
        // Determine how many characters of the original text have to be removed.
        // For the current algorithm the removed length is either 1 or 2,
        // depending on the replacement string length.
        int removedLength = Math.min(replacement.length(),
                /* original removal length is always 1 for the single‑char cases,
                   otherwise 2 for the two‑char cases (handled by the caller). */
                replacement.length());

        // Build the new string by concatenating the parts that stay unchanged.
        return original.substring(0, startIdx) +
               replacement +
               original.substring(startIdx + removedLength);
    }
}

import java.io.IOException;
import java.io.InputStream;
import java.util.StringTokenizer;

/**
 * Reads multiple test cases and transforms each input string according to the
 * original specification, but with a clean, well‑structured implementation.
 */
public class Main {

    /** Pattern that is inserted when the original word contains only numbers. */
    private static final String NUMBER_PREFIX_UPPER = "A1";
    private static final String NUMBER_PREFIX_LOWER = "a1";
    private static final String LETTER_PREFIX_MIXED = "aA";

    /** Fast I/O helper – unchanged from the original code. */
    private static final class FastReader {
        private final byte[] buffer = new byte[2048];
        private int index = 0, size = 0;
        private final InputStream in;

        FastReader(InputStream is) { this.in = is; }

        private int readByte() throws IOException {
            if (index >= size) {
                index = 0;
                size = in.read(buffer);
                if (size <= 0) return -1;
            }
            return buffer[index++];
        }

        /** Skips whitespace and returns the next token. */
        String next() throws IOException {
            int c;
            while ((c = readByte()) <= 32) { }
            StringBuilder sb = new StringBuilder();
            do { sb.append((char) c); } while ((c = readByte()) > 32);
            return sb.toString();
        }

        /** Reads the next integer (supports a leading ‘-’). */
        int nextInt() throws IOException {
            int c, value = 0;
            while ((c = readByte()) <= 32) { }
            boolean neg = c == '-';
            if (c == '-' || c == '+') c = readByte();
            for (; c >= '0' && c <= '9'; c = readByte())
                value = (value << 3) + (value << 1) + (c & 15);
            return neg ? -value : value;
        }
    }

    /** Holds the result of processing a single word. */
    private static final class Processor {

        /** Counts lower‑case, upper‑case and “other” characters in the word. */
        private static counts countCategories(String word) {
            int lower = 0, upper = 0, other = 0;
            for (char ch : word.toCharArray()) {
                if (Character.isLowerCase(ch)) lower++;
                else if (Character.isUpperCase(ch)) upper++;
                else other++;
            }
            return new counts(lower, upper, other);
        }

        /** Returns the index of the first character that satisfies the predicate,
         *  or -1 if none is found. */
        private static int firstIndex(String word, CharPredicate predicate) {
            for (int i = 0; i < word.length(); i++) {
                if (predicate.test(word.charAt(i))) return i;
            }
            return -1;
        }

        /** Main transformation routine – mirrors the behaviour of the original
         *  program but is now isolated and easier to understand. */
        static String transform(String word) {
            counts c = countCategories(word);
            int len = word.length();

            // 1️⃣  All three categories present → keep original word unchanged
            if (c.lower >= 1 && c.upper >= 1 && c.other >= 1) {
                return word;
            }

            // 2️⃣  No lower‑case and no upper‑case (only “other”) → prepend "aA"
            //     and drop the first two characters of the original word.
            if (c.lower == 0 && c.upper == 0 && c.other >= 1) {
                String tail = (len > 2) ? word.substring(2) : "";
                return LETTER_PREFIX_MIXED + tail;
            }

            // 3️⃣  No lower‑case, at least one upper‑case and no “other” → prepend "a1"
            if (c.lower == 0 && c.upper >= 1 && c.other == 0) {
                String tail = (len > 2) ? word.substring(2) : "";
                return NUMBER_PREFIX_LOWER + tail;
            }

            // 4️⃣  At least one lower‑case, no upper‑case, no “other” → prepend "A1"
            if (c.lower >= 1 && c.upper == 0 && c.other == 0) {
                String tail = (len > 2) ? word.substring(2) : "";
                return NUMBER_PREFIX_UPPER + tail;
            }

            // Helper for cases that need to replace a single character
            char replacement(char newChar) { return newChar; }

            // 5️⃣  No lower‑case, more than one upper‑case and at least one “other”
            if (c.lower == 0 && c.upper > 1 && c.other >= 1) {
                int idx = firstIndex(word, Character::isUpperCase);
                if (idx >= 0) {
                    StringBuilder sb = new StringBuilder(word);
                    sb.setCharAt(idx, replacement('a'));
                    return sb.toString();
                }
                return word; // fallback – should not happen
            }

            // 6️⃣  More than one lower‑case, no upper‑case, at least one “other”
            if (c.lower > 1 && c.upper == 0 && c.other >= 1) {
                int idx = firstIndex(word, Character::isLowerCase);
                if (idx >= 0) {
                    StringBuilder sb = new StringBuilder(word);
                    sb.setCharAt(idx, replacement('A'));
                    return sb.toString();
                }
                return word;
            }

            // 7️⃣  At least one lower‑case, no upper‑case, more than one “other”
            if (c.lower >= 1 && c.upper == 0 && c.other > 1) {
                int idx = firstIndex(word, ch -> Character.isDigit(ch));
                if (idx >= 0) {
                    StringBuilder sb = new StringBuilder(word);
                    sb.setCharAt(idx, replacement('A'));
                    return sb.toString();
                }
                return word;
            }

            // 8️⃣  More than one lower‑case, at least one upper‑case, no “other”
            if (c.lower > 1 && c.upper >= 1 && c.other == 0) {
                int idx = firstIndex(word, Character::isLowerCase);
                if (idx >= 0) {
                    StringBuilder sb = new StringBuilder(word);
                    sb.setCharAt(idx, replacement('1'));
                    return sb.toString();
                }
                return word;
            }

            // 9️⃣  At least one lower‑case, more than one upper‑case, no “other”
            if (c.lower >= 1 && c.upper > 1 && c.other == 0) {
                int idx = firstIndex(word, Character::isUpperCase);
                if (idx >= 0) {
                    StringBuilder sb = new StringBuilder(word);
                    sb.setCharAt(idx, replacement('1'));
                    return sb.toString();
                }
                return word;
            }

            // 10️⃣ No lower‑case, at least one upper‑case, more than one “other”
            if (c.lower == 0 && c.upper >= 1 && c.other > 1) {
                int idx = firstIndex(word, Character::isDigit);
                if (idx >= 0) {
                    StringBuilder sb = new StringBuilder(word);
                    sb.setCharAt(idx, replacement('a'));
                    return sb.toString();
                }
                return word;
            }

            // If none of the above patterns match, return the original word.
            return word;
        }

        /** Simple holder for the three counters. */
        private static final class counts {
            final int lower, upper, other;
            counts(int lower, int upper, int other) {
                this.lower = lower;
                this.upper = upper;
                this.other = other;
            }
        }
    }

    public static void main(String[] args) throws IOException {
        FastReader reader = new FastReader(System.in);
        StringBuilder output = new StringBuilder();

        int testCases = reader.nextInt();
        while (testCases-- > 0) {
            String word = reader.next();
            String processed = Processor.transform(word);
            output.append(processed).append('\n');
        }

        System.out.print(output.toString());
    }
}

import java.io.*;
import java.util.*;

public class VasyaAndPassword {

    /* --------------------------------------------------------------------- */
    /*  Input handling (identical to the original, but encapsulated)        */
    /* --------------------------------------------------------------------- */
    private static final class InputReader {
        private final InputStream stream;
        private final byte[] buffer = new byte[8192];
        private int currentChar;
        private int numberOfChars;

        public InputReader(InputStream stream) {
            this.stream = stream;
        }

        private int read() {
            if (numberOfChars == -1) {
                throw new InputMismatchException();
            }
            if (currentChar >= numberOfChars) {
                currentChar = 0;
                try {
                    numberOfChars = stream.read(buffer);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (numberOfChars <= 0) {
                    return -1;
                }
            }
            return buffer[currentChar++];
        }

        public int nextInt() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            int result = 0;
            do {
                result = result * 10 + (c - '0');
                c = read();
            } while (!isSpaceChar(c));
            return result * sign;
        }

        public String readString() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }
            StringBuilder sb = new StringBuilder();
            do {
                sb.appendCodePoint(c);
                c = read();
            } while (!isSpaceChar(c));
            return sb.toString();
        }

        public String readLine() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }
            StringBuilder sb = new StringBuilder();
            do {
                sb.appendCodePoint(c);
                c = read();
            } while (!isEndOfLine(c));
            return sb.toString();
        }

        public boolean isSpaceChar(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        private boolean isEndOfLine(int c) {
            return c == '\n' || c == '\r' || c == -1;
        }
    }

    /* --------------------------------------------------------------------- */
    /*  Core logic – refactored to be clearer and self‑documenting           */
    /* --------------------------------------------------------------------- */
    public static void main(String[] args) {
        try (PrintWriter out = new PrintWriter(System.out)) {
            InputReader reader = new InputReader(System.in);
            int testCases = reader.nextInt();
            StringBuilder output = new StringBuilder();

            for (int tc = 0; tc < testCases; tc++) {
                char[] password = reader.readLine().toCharArray();
                out.print(processPassword(password));
                out.println();
            }
            out.flush();
        }
    }

    /**
     * Determines the minimal changes required to make the password meet the
     * specification and returns the resulting string.
     */
    private static String processPassword(char[] pwd) {
        boolean hasLower = false, hasUpper = false, hasDigit = false;
        int lowerCnt = 0, upperCnt = 0, digitCnt = 0;

        // -----------------------------------------------------------------
        // 1. Gather statistics about the current password
        // -----------------------------------------------------------------
        for (char ch : pwd) {
            if (Character.isLowerCase(ch)) {
                hasLower = true;
                lowerCnt++;
            } else if (Character.isUpperCase(ch)) {
                hasUpper = true;
                upperCnt++;
            } else if (Character.isDigit(ch)) {
                hasDigit = true;
                digitCnt++;
            }
        }

        // -----------------------------------------------------------------
        // 2. If it already satisfies all three requirements, nothing to do
        // -----------------------------------------------------------------
        if (hasLower && hasUpper && hasDigit) {
            return new String(pwd);
        }

        // -----------------------------------------------------------------
        // 3. Determine how many categories are missing
        // -----------------------------------------------------------------
        int missingCategories = 0;
        if (!hasDigit) missingCategories++;
        if (!hasUpper) missingCategories++;
        if (!hasLower) missingCategories++;

        // -----------------------------------------------------------------
        // 4. Exactly one category is missing → try to replace a unique
        //    character of an existing category that appears exactly twice.
        // -----------------------------------------------------------------
        if (missingCategories == 1) {
            // Identify which category is missing
            char missingChar = missingCharacter(hasLower, hasUpper, hasDigit);

            // Scan for a character belonging to a category whose total count is 2
            for (int i = 0; i < pwd.length; i++) {
                char cur = pwd[i];
                int categoryCount;

                if (!hasLower && Character.isLowerCase(cur)) {
                    categoryCount = lowerCnt;
                } else if (!hasUpper && Character.isUpperCase(cur)) {
                    categoryCount = upperCnt;
                } else { // must be digit
                    categoryCount = digitCnt;
                }

                if (categoryCount == 2) {
                    pwd[i] = missingChar;
                    break; // only one replacement is needed
                }
            }
        }

        // -----------------------------------------------------------------
        // 5. Two or three categories are missing → prepend the required
        //    characters at the first two positions (mirrors original logic).
        // -----------------------------------------------------------------
        if (!hasLower || !hasUpper || !hasDigit) {
            if (!hasLower && !hasUpper) {
                pwd[0] = 'a';
                pwd[1] = 'A';
            } else if (!hasLower && !hasDigit) {
                pwd[0] = 'a';
                pwd[1] = '1';
            } else { // !hasUpper && !hasDigit
                pwd[0] = 'A';
                pwd[1] = '1';
            }
        }

        return new String(pwd);
    }

    /** Returns the character needed to satisfy the currently missing category. */
    private static char missingCharacter(boolean hasLower, boolean hasUpper, boolean hasDigit) {
        if (!hasLower) return 'a';
        if (!hasUpper) return 'A';
        return '1'; // !hasDigit
    }
}

import java.io.*;
import java.util.StringTokenizer;

/**
 * Main application that processes a list of strings.
 * The processing logic is exactly the same as the original
 * program, but the code has been reorganised for readability,
 * maintainability and proper encapsulation.
 */
public class Solution {

    /* -------------------------------------------------------------
     *  Entry point
     * ------------------------------------------------------------- */
    public static void main(String[] args) {
        FastReader scanner = new FastReader();

        int n = scanner.nextInt();                     // number of input lines
        String[] lines = new String[n];
        for (int i = 0; i < n; i++) {
            lines[i] = scanner.nextLine();             // read each line
        }

        PrintWriter out = new PrintWriter(System.out);
        for (String line : lines) {
            out.print(process(line));
            out.println();                             // line separator
        }
        out.flush();
    }

    /* -------------------------------------------------------------
     *  Public processing API
     * ------------------------------------------------------------- */
    /**
     * Applies the original transformation rules to the supplied line.
     *
     * @param input the raw line read from the input stream
     * @return the transformed string according to the original logic
     */
    public static String process(String input) {
        // -----------------------------------------------------------------
        // 1️⃣  Gather statistics about the characters in the line
        // -----------------------------------------------------------------
        int digitCount   = 0;   // number of decimal digits  (a)
        int upperCount   = 0;   // number of uppercase letters (b)
        int lowerCount   = 0;   // number of lowercase letters (c)

        for (int i = 0; i < input.length(); i++) {
            char ch = input.charAt(i);
            if (Character.isDigit(ch)) {
                digitCount++;
            } else if (Character.isUpperCase(ch)) {
                upperCount++;
            } else if (Character.isLowerCase(ch)) {
                lowerCount++;
            }
        }

        boolean hasDigit   = digitCount > 0;
        boolean hasUpper   = upperCount > 0;
        boolean hasLower   = lowerCount > 0;

        // -----------------------------------------------------------------
        // 2️⃣  Apply the branching rules that were present in the original code
        // -----------------------------------------------------------------
        // If *all three* character types are present, the line is emitted unchanged.
        if (hasDigit && hasUpper && hasLower) {
            return input;
        }

        // When no digits are found we have several sub‑cases.
        if (!hasDigit) {
            return handleNoDigitCase(input, hasUpper, hasLower, upperCount, lowerCount);
        }

        // When at least one digit exists the original program distinguishes
        // a few more sub‑cases.  Those are handled by the dedicated helper.
        return handleDigitPresentCase(input, hasUpper, hasLower, digitCount, upperCount, lowerCount);
    }

    /* -------------------------------------------------------------
     *  Helper methods – each encapsulates a distinct logical branch
     * ------------------------------------------------------------- */

    /**
     * Deals with the situation where the input contains **no digits**.
     * The original program emitted a special prefix and then the
     * substring starting at index 2.  Additional rules about replacing
     * the first occurrence of a particular character are also applied.
     */
    private static String handleNoDigitCase(String s,
                                            boolean hasUpper,
                                            boolean hasLower,
                                            int upperCount,
                                            int lowerCount) {
        // Determine the prefix that the original code used.
        String prefix;
        if (!hasUpper && !hasLower) {
            prefix = "2A";
        } else if (!hasUpper) {
            prefix = "2a";
        } else if (!hasLower) {
            prefix = "aA";
        } else {
            // This situation cannot happen given the earlier checks,
            // but we keep the fallback for symmetry with the original flow.
            prefix = "";
        }

        // The original code also replaced the first occurrence of a
        // certain character (controlled by the `was` flag).  We replicate
        // that behaviour with a small loop.
        StringBuilder result = new StringBuilder(prefix);
        boolean replaced = false;

        // When exactly one uppercase or one lowercase appears, the
        // original code replaced the *first* such character with "1".
        // We follow the same rule here.
        if (upperCount == 1 && !hasLower) {
            // Replace first lowercase letter with "1"
            for (int i = 0; i < s.length(); i++) {
                char ch = s.charAt(i);
                if (Character.isLowerCase(ch) && !replaced) {
                    result.append('1');
                    replaced = true;
                } else {
                    result.append(ch);
                }
            }
        } else if (lowerCount == 1 && !hasUpper) {
            // Replace first uppercase letter with "1"
            for (int i = 0; i < s.length(); i++) {
                char ch = s.charAt(i);
                if (Character.isUpperCase(ch) && !replaced) {
                    result.append('1');
                    replaced = true;
                } else {
                    result.append(ch);
                }
            }
        } else {
            // Otherwise just copy the whole string after the prefix.
            result.append(s.substring(2));
        }
        return result.toString();
    }

    /**
     * Handles the remaining branches that apply when the input **does**
     * contain at least one digit.  The logic mirrors the original source
     * code but is now isolated in its own method for clarity.
     */
    private static String handleDigitPresentCase(String s,
                                                 boolean hasUpper,
                                                 boolean hasLower,
                                                 int digitCount,
                                                 int upperCount,
                                                 int lowerCount) {
        StringBuilder out = new StringBuilder();

        // The original program printed a different prefix depending on
        // which character types were missing.
        if (!hasUpper && !hasLower) {
            out.append("aA");
        } else if (!hasUpper) {
            out.append("a");                     // prefix when only uppercase missing
        } else if (!hasLower) {
            out.append("a");                     // prefix when only lowercase missing
        } else {
            // When both cases are present we simply start with "1"
            out.append('1');
        }

        // The original implementation replaced the *first* occurrence of
        // a certain character with "1" (controlled by the `was` flag).
        // We perform the same replacement here.
        boolean replaced = false;
        for (int i = 0; i < s.length(); i++) {
            char ch = s.charAt(i);
            if (!replaced && shouldReplace(ch, digitCount, upperCount, lowerCount)) {
                out.append('1');
                replaced = true;
            } else {
                out.append(ch);
            }
        }
        return out.toString();
    }

    /**
     * Determines whether the current character must be replaced with
     * the digit “1”.  The replacement rule is exactly the one used in
     * the original source (replace the first lower‑case / upper‑case /
     * digit depending on the counts that were tracked).
     */
    private static boolean shouldReplace(char ch,
                                          int digitCount,
                                          int upperCount,
                                          int lowerCount) {
        // No‑digit case – replace first lower‑case when there is exactly
        // one lowercase and no uppercase, or replace first upper‑case
        // when there is exactly one uppercase and no lowercase.
        if (digitCount == 0) {
            if (lowerCount == 1 && !isUpperPresent()) {
                return Character.isLowerCase(ch);
            }
            if (upperCount == 1 && !isLowerPresent()) {
                return Character.isUpperCase(ch);
            }
        }

        // Digit‑present case – always replace the very first character
        // (mirroring the original “was” flag behaviour).
        return true;
    }

    /** Utility used by {@link #shouldReplace}. */
    private static boolean isUpperPresent() {
        //Placeholder – actual presence is determined outside the helper.
        return false;
    }

    /** Utility used by {@link #shouldReplace}. */
    private static boolean isLowerPresent() {
        //Placeholder – actual presence is determined outside the helper.
        return false;
    }

    /* -------------------------------------------------------------
     *  Fast input reader (unchanged from the original snippet)
     * ------------------------------------------------------------- */
    private static class FastReader {
        private final BufferedReader br;
        private StringTokenizer st;

        FastReader() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        String nextLine() {
            try {
                return br.readLine();
            } catch (IOException e) {
                throw new RuntimeException(e);
            }
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;

/**
 * Refactored solution that reads several test cases, validates each string,
 * attempts to fix it, and prints the appropriate result.
 */
public class Submit {

    /* --------------------------------------------------------------------- */
    /*  Utility enums / helpers                                               */
    /* --------------------------------------------------------------------- */

    /** Categorises a character into one of three groups. */
    private enum CharCategory {
        DIGIT,
        LOWER,
        UPPER,
        SPECIAL;   // any character that is not a digit or a letter

        static CharCategory of(char ch) {
            if (ch >= '0' && ch <= '9') {
                return DIGIT;
            }
            if (ch >= 'a' && ch <= 'z') {
                return LOWER;
            }
            if (ch >= 'A' && ch <= 'Z') {
                return UPPER;
            }
            return SPECIAL;
        }
    }

    /** Counts how many characters of each category appear in a string. */
    private static final class Counter {
        int digit;
        int lower;
        int upper;
        int special;

        void add(char ch) {
            switch (CharCategory.of(ch)) {
                case DIGIT -> digit++;
                case LOWER -> lower++;
                case UPPER -> upper++;
                default -> special++;
            }
        }

        int digit()   { return digit; }
        int lower()   { return lower; }
        int upper()   { return upper; }
        int special() { return special; }
    }

    /* --------------------------------------------------------------------- */
    /*  Validation                                                            */
    /* --------------------------------------------------------------------- */

    /** Returns true if the string contains at least one digit, one lower‑case
     *  letter and one upper‑case letter, and no special characters. */
    private static boolean isValid(String s) {
        Counter c = new Counter();
        for (char ch : s.toCharArray()) {
            c.add(ch);
        }
        return c.digit() > 0 && c.lower() > 0 && c.upper() > 0 && c.special() == 0;
    }

    /* --------------------------------------------------------------------- */
    /*  Transformation helpers                                                */
    /* --------------------------------------------------------------------- */

    /**
     * Tries to make the string valid by replacing a single character.
     * Returns the modified string, or the original string if no replacement
     * could be performed.
     */
    private static String makeValid(String original) {
        StringBuilder sb = new StringBuilder(original);
        Counter counters = new Counter();
        for (char ch : original.toCharArray()) {
            counters.add(ch);
        }

        int n = original.length();
        for (int i = 0; i < n; i++) {
            char ch = original.charAt(i);
            switch (CharCategory.of(ch)) {
                case DIGIT -> {
                    if (counters.digit() > 1 && counters.lower() == 0 && counters.upper() == 0) {
                        sb.setCharAt(i, 'a');
                        return sb.toString();
                    }
                    if (counters.digit() > 1 && counters.special() == 0) {
                        sb.setCharAt(i, 'A');
                        return sb.toString();
                    }
                }
                case LOWER -> {
                    if (counters.lower() > 1 && counters.digit() == 0 && counters.upper() == 0) {
                        sb.setCharAt(i, '0');
                        return sb.toString();
                    }
                    if (counters.lower() > 1 && counters.special() == 0) {
                        sb.setCharAt(i, 'A');
                        return sb.toString();
                    }
                }
                case UPPER -> {
                    if (counters.upper() > 1 && counters.digit() == 0 && counters.lower() == 0) {
                        sb.setCharAt(i, '0');
                        return sb.toString();
                    }
                    if (counters.upper() > 1 && counters.lower() == 0) {
                        sb.setCharAt(i, 'a');
                        return sb.toString();
                    }
                }
            }
        }
        // No useful replacement was found – return the original string.
        return sb.toString();
    }

    /** Applies the fallback rule from the original code when the string cannot
     *  be fixed by a single‑character substitution. */
    private static String applyFallback(String s) {
        // The original program always assumes length ≥ 3.
        if (s.length() < 3) {
            return s;
        }
        char third = s.charAt(2);
        if (Character.isLowerCase(third)) {
            return "A1" + s.substring(2);
        } else if (Character.isUpperCase(third)) {
            return "a1" + s.substring(2);
        } else {
            return "aA" + s.substring(2);
        }
    }

    /* --------------------------------------------------------------------- */
    /*  Main processing                                                         */
    /* --------------------------------------------------------------------- */

    public static void main(String[] args) throws IOException {
        // Using try‑with‑resources guarantees the reader is closed properly.
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(System.in))) {
            int testCases = Integer.parseInt(reader.readLine().trim());

            for (int t = 0; t < testCases; t++) {
                String line = reader.readLine();
                if (line == null || line.isEmpty()) {
                    continue;                     // skip empty lines
                }

                // 1️⃣ Already valid – just output it.
                if (isValid(line)) {
                    System.out.println(line);
                    continue;
                }

                // 2️⃣ Try to fix it with a single‑character change.
                String fixed = makeValid(line);
                if (isValid(fixed)) {
                    System.out.println(fixed);
                    continue;
                }

                // 3️⃣ Fallback rule (modifies characters at index 2).
                String result = applyFallback(line);
                System.out.println(result);
            }
        }
    }
}

