/**
 * Refactored version of Task1051A.
 * The program reads several strings, classifies each one and prints a
 * modified version according to the original specification.
 */
public class Task1051A {

    /* --------------------------------------------------------------------- */
    /*  Constants for the different output prefixes                           */
    private static final String PREFIX_1  = "1";
    private static final String PREFIX_2  = "a";
    private static final String PREFIX_3  = "A";
    private static final String PREFIX_12 = "1a";
    private static final String PREFIX_13 = "1A";
