        }

        for (String s : inputs) {
            int analysis = analyze(s);
            System.out.println(applyFix(s, analysis));
        }
        scanner.close();
    }

    /* --------------------------------------------------------------------- */
    /**
     * Analyses a string and returns a code that describes which
     * character class is missing or whether the string already contains
     * all three classes.
     *
     * @return -1  if the string already contains uppercase, lowercase and digit
     *         1‑3  if only one class is missing
     *         12‑13‑23 if two classes are missing
     */
    private static int analyze(String s) {
        int upper = 0, lower = 0, digit = 0;
        for (char c : s.toCharArray()) {
            if (Character.isUpperCase(c)) {
                upper++;
            } else if (Character.isLowerCase(c)) {
                lower++;
            } else if (Character.isDigit(c)) {
                digit++;
            }
        }

        // all three categories present → nothing to add
        if (upper > 0 && lower > 0 && digit > 0) {
            return -1;
        }

        // missing digit
        if (digit == 0) {
            if (upper == 0) {
                return 13;                // need digit + uppercase → "1A"
            }
            // upper > 0
            if (lower == 0) {
                return 12;                // need digit + lowercase → "1a"
            }
            return 1;                     // need only digit → insert "1"
        }

        // digit present, missing lowercase
        if (lower == 0) {
            if (upper == 0) {
                return 23;                // need lowercase + uppercase → "aA"
            }
            return 2;                     // need only lowercase → insert "a"
        }

        // digit and lowercase present, missing uppercase
        return 3;                         // need only uppercase → insert "A"
    }

    /* --------------------------------------------------------------------- */
    /**
     * Produces the final output string according to the numeric code
     * returned by {@link #analyze(String)}.
     */
    private static String applyFix(String original, int code) {
        return switch (code) {
            case 12 -> PREFIX_12 + original.substring(2);
            case 13 -> PREFIX_13 + original.substring(2);
            case 23 -> PREFIX_23 + original.substring(2);
            case 1  -> insertAt(findInsertionPositionForDigit(original), original, PREFIX_1);
            case 2  -> insertAt(findInsertionPositionForLower(original),  original, PREFIX_2);
            case 3  -> insertAt(findInsertionPositionForUpper(original),  original, PREFIX_3);
            default -> original; // should never happen
        };
    }

    /* --------------------------------------------------------------------- */
    /** Position where a digit '1' should be inserted. */
    private static int findInsertionPositionForDigit(String s) {
        return findInsertionPosition(s, Character::isUpperCase);
    }

    /** Position where a lowercase letter 'a' should be inserted. */
    private static int findInsertionPositionForLower(String s) {
        // gap analysis involves uppercase and digit characters
        return computeInsertionPosition(s, Character::isUpperCase, Character::isDigit);
    }

    /** Position where an uppercase letter 'A' should be inserted. */
    private static int findInsertionPositionForUpper(String s) {
        // gap analysis involves lowercase and digit characters
        return computeInsertionPosition(s, Character::isLowerCase, Character::isDigit);
    }

    /**
     * Determines the index where a missing character of the supplied
     * {@code targetPredicate} should be inserted.
     * The method looks at the distances between consecutive positions that
     * satisfy {@code firstPredicate} (or {@code secondPredicate}) and picks
     * the earlier index of the pair that yields the smallest gap.
     *
     * @return the insertion index, or 0 if no suitable gap exists
     */
    private static int computeInsertionPosition(String s,
                                                Predicate<Character> firstPredicate,
                                                Predicate<Character> secondPredicate) {
        List<Integer> firstPos = new ArrayList<>();
        List<Integer> secondPos = new ArrayList<>();

        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (firstPredicate.test(c)) {
                firstPos.add(i);
            } else if (secondPredicate.test(c)) {
                secondPos.add(i);
            }
        }

        int bestIndex = -1;
        int bestGap   = Integer.MAX_VALUE;

        // examine gaps between consecutive firstPredicate matches
        for (int i = 1; i < firstPos.size(); i++) {
            int gap = firstPos.get(i) - firstPos.get(i - 1);
            if (gap < bestGap) {
                bestGap = gap;
                bestIndex = firstPos.get(i - 1);
            }
        }

        // fallback – if no gap was found we simply insert at the beginning
        return bestIndex >= 0 ? bestIndex : 0;
    }

    /* --------------------------------------------------------------------- */
    /** Utility to apply a consumer to each element of a list (kept for readability). */
    private static <T> void forEach(List<T> list, Consumer<T> action) {
        for (T element : list) {
            action.accept(element);
        }
    }

    /* --------------------------------------------------------------------- */
    /** Inserts {@code toInsert} at the given {@code index} in {@code source}. */
    private static String insertAt(int index, String source, String toInsert) {
        // Guard against negative index – treat it as insertion at the start
        if (index < 0) {
            index = 0;
        }
        return source.substring(0, index) + toInsert + source.substring(index);
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.ArrayList;
import java.util.List;
import java.util.Objects;
import java.util.stream.Collectors;

/**
 * Reads several test cases and transforms each string according to the
 * original logic, but with a clear, modular design.
 */
public class Solution {

    /** Category indices: 0 = Upper‑case, 1 = Lower‑case, 2 = Digit */
    private static final char[] CATEGORY_REP = {'A', 'a', '1'};

    private BufferedReader br;
    private StringTokenizer st;

    /** Entry point */
    public static void main(String[] args) {
        new Solution().run();
    }

    /** Runs the whole program: read → process → output */
    private void run() {
        init();
        try {
            br.close();
        } catch (IOException e) {
            throw new RuntimeException(e);
        }
    }

    /** Initializes the input reader and starts solving */
    private void init() {
        br = new BufferedReader(new InputStreamReader(System.in));
        int testCount = nextInt();
        for (int t = 0; t < testCount; t++) {
            System.out.println(processTestCase(next()));
        }
    }

    /** Reads the next token from the input stream */
    private String next() {
        while (Objects.isNull(st) || !st.hasMoreTokens()) {
            try {
                st = new StringTokenizer(br.readLine());
            } catch (IOException e) {
                throw new RuntimeException(e);
            }
        }
        return st.nextToken();
    }

    /** Reads the next integer token */
    private int nextInt() {
        return Integer.parseInt(next());
    }

    /** --------------------------------------------------------------------- */
    /** -------------------------- Core logic ------------------------------- */

    /** Processes a single test case string */
    private String processTestCase(String s) {
        int[] counts = countCategories(s);
        int presentCategories = (int) java.util.Arrays.stream(counts).filter(c -> c > 0).count();

        // 3 categories present → nothing to change
        if (presentCategories == 3) {
            return s;
        }

        // Only one category present → prepend the missing categories (original behaviour)
        if (presentCategories == 1) {
            String missing = missingCategorySymbols(counts);
            // The original code kept the substring starting at index 2;
            // we preserve that quirky requirement.
            return missing + s.substring(2);
        }

        // Exactly two categories present → insert the missing one
        int missingIdx = findMissingCategoryIndex(counts);
        return insertMissingCategory(s, missingIdx);
    }

    /** Counts how many upper‑case, lower‑case and digit characters are in the string */
    private int[] countCategories(String s) {
        int[] cnt = new int[3];
        for (char c : s.toCharArray()) {
            categoryOf(c).ifPresent(idx -> cnt[idx]++);
        }
        return cnt;
    }

    /** Returns the category index of a character (0,1,2) or empty if none */
    private java.util.OptionalInt categoryOf(char c) {
        if ('A' <= c && c <= 'Z') return java.util.OptionalInt.of(0);
        if ('a' <= c && c <= 'z') return java.util.OptionalInt.of(1);
        if ('0' <= c && c <= '9') return java.util.OptionalInt.of(2);
        return java.util.OptionalInt.empty();
    }

    /** Returns the symbols that are missing from the three categories */
    private String missingCategorySymbols(int[] counts) {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < 3; i++) {
            if (counts[i] == 0) sb.append(CATEGORY_REP[i]);
        }
        return sb.toString();
    }

    /** Finds the index (0‑2) of the missing category */
    private int findMissingCategoryIndex(int[] counts) {
        for (int i = 0; i < 3; i++) {
            if (counts[i] == 0) return i;
        }
        throw new IllegalStateException("No missing category found");
    }

    /**
     * Inserts the missing category symbol at the first position where a
     * duplicate of another category appears (mirrors the original nested loops).
     */
    private String insertMissingCategory(String s, int missingIdx) {
        int[] counts = countCategories(s);
        char replacement = CATEGORY_REP[missingIdx];

        // Find a character that belongs to a category with count > 1
        for (int i = 0; i < s.length(); i++) {
            int catIdx = categoryOf(s.charAt(i)).orElse(-1);
            if (catIdx != -1 && counts[catIdx] > 1) {
                return s.substring(0, i) + replacement + s.substring(i + 1);
            }
        }
        // Fallback – prepend the missing symbol (should not happen for valid input)
        return replacement + s;
    }
}

import java.io.*;
import java.nio.charset.StandardCharsets;

/**
 * Reads several passwords and guarantees that each password contains at least
 * one lowercase letter, one uppercase letter and one digit.
 *
 * <p>If a required character class is missing, the algorithm tries to convert
 * an existing character (that appears at least twice) to the missing class.
 * When no such character exists, the first character of the password is used.
 *
 * <p>The implementation focuses on readability, separation of concerns and
 * proper resource handling.
 */
public class VasyaAndPassword {

    /** Characters used to fill the missing class. */
    private static final char LOWER_CHAR = 'a';
    private static final char UPPER_CHAR = 'A';
    private static final char DIGIT_CHAR = '0';

    /** Holds the three counters for a password. */
    private static final class CategoryCounts {
        final int lower;
        final int upper;
        final int digit;

        CategoryCounts(int lower, int upper, int digit) {
            this.lower = lower;
            this.upper = upper;
            this.digit = digit;
        }
    }

    /**
     * Counts how many characters of each required class are present in the password.
     */
    private static CategoryCounts countCategories(String password) {
        int lower = 0, upper = 0, digit = 0;
        for (char c : password.toCharArray()) {
            if (c >= 'a' && c <= 'z') lower++;
            else if (c >= 'A' && c <= 'Z') upper++;
            else if (c >= '0' && c <= '9') digit++;
        }
        return new CategoryCounts(lower, upper, digit);
    }

    /**
     * Fixes a password that is missing one or more required character classes.
     *
     * @param password original password
     * @return a modified password that satisfies all requirements
     */
    private static String fixPassword(String password) {
        char[] chars = password.toCharArray();
        CategoryCounts counts = countCategories(password);

        // Helper to modify the first character that can be turned into the missing class
        java.util.function.Predicate<Character, Integer, Character> canReplace = (c, idx, needed) -> {
            // The character must belong to a class that appears at least twice
            // (so we won't break another requirement) and we must be able to replace it.
            return countsForClass(c) > 1;
        };

        // Helper to get the current count of the class a character belongs to
        java.util.function.Function<Character, Integer> countsForClass = c -> {
            if (c >= 'a' && c <= 'z') return counts.lower;
            if (c >= 'A' && c <= 'Z') return counts.upper;
            if (c >= '0' && c <= '9') return counts.digit;
            return 0;
        };

        // Missing classes → action
        if (counts.lower == 0) {
            for (int i = 0; i < chars.length; i++) {
                if (canReplace.test(chars[i], i, LOWER_CHAR)) {
                    chars[i] = LOWER_CHAR;
                    break;
                }
            }
        }
        if (counts.upper == 0) {
            for (int i = 0; i < chars.length; i++) {
                if (canReplace.test(chars[i], i, UPPER_CHAR)) {
                    chars[i] = UPPER_CHAR;
                    break;
                }
            }
        }
        if (counts.digit == 0) {
            for (int i = 0; i < chars.length; i++) {
                if (canReplace.test(chars[i], i, DIGIT_CHAR)) {
                    chars[i] = DIGIT_CHAR;
                    break;
                }
            }
        }

        // If nothing was changed (e.g., all classes were already present) we simply
        // return the original string.
        return new String(chars);
    }

    /** Entry point – reads input, processes passwords and writes results. */
    public static void main(String[] args) throws IOException {
        // Using try‑with‑resources guarantees that streams are closed automatically.
        try (BufferedReader reader = new BufferedReader(
                new InputStreamReader(new BufferedInputStream(System.in), StandardCharsets.UTF_8));
             BufferedWriter writer = new BufferedWriter(
                new OutputStreamWriter(new BufferedOutputStream(System.out), StandardCharsets.UTF_8))) {

            String line;
            int testCases = Integer.parseInt(reader.readLine()); // t

            while (testCases-- > 0 && (line = reader.readLine()) != null) {
                String fixed = fixPassword(line);
                writer.write(fixed);
                writer.write('\n');
                writer.flush(); // ensure line is written before next iteration
            }
        } catch (IOException e) {
            // In a contest setting we usually just print the stack trace; in production
            // we would log it appropriately.
            e.printStackTrace();
        }
    }
}

import java.io.*;
import java.util.ArrayList;
import java.util.List;

/**
 * Refactored solution for the original {@code utkarsh} program.
 *
 * <p>
 * The algorithm:
 * <ol>
 *   <li>Read the number of test cases.</li>
 *   <li>For each test case read an arbitrary string.</li>
 *   <li>Classify each character as:
 *       <ul>
 *         <li>lower‑case letter (type 0)</li>
 *         <li>upper‑case letter (type 1)</li>
 *         <li>any other character (type 2)</li>
 *       </ul>
 *   </li>
 *   <li>Depending on which categories are empty, replace a single character
 *       according to the rules described in the original program.</li>
 *   <li>Print the modified string.</li>
 * </ol>
 * </p>
 *
 * The refactor improves readability by:
 * <ul>
 *   <li>Extracting the classification logic into {@link #classify(char[])}.</li>
 *   <li>Encapsulating the rule‑application logic into {@link #applyRules(char[], List, List, List)}.</li>
 *   <li>Using meaningful variable names and constants.</li>
 *   <li>Removing unused imports and magic numbers.</li>
 *   <li>Keeping the fast scanner implementation but making its intent clearer.</li>
 * </ul>
 */
public class utkarsh {

    /* -------------------------------------------------------- */
    /*                     Configuration                        */
    /* -------------------------------------------------------- */
    private static final long MOD = 1_000_000_007L;   // Not used directly, kept for compatibility
    private static final long INF = 3_000_000_000_000_000_000L;

    /** Indicates whether execution timing should be shown (default: disabled). */
    private boolean SHOW_TIME = false;
    /** Enables debug output when set to {@code true}. */
    private boolean debug = false;

    /* -------------------------------------------------------- */
    /*                     Core processing                      */
    /* -------------------------------------------------------- */
    /**
     * Entry point for the solution – parses input, processes each case and
     * writes the result to standard output.
     */
    public void solve() {
        int testCases = ni();
        StringBuilder output = new StringBuilder();

        for (int tc = 0; tc < testCases; tc++) {
            String raw = ns();               // read the whole next token
            char[] chars = raw.toCharArray();  // mutable view for transformations
            List<Integer> lower   = new ArrayList<>();
            List<Integer> upper   = new ArrayList<>();
            List<Integer> others  = new ArrayList<>();

            classify(chars, lower, upper, others);   // categorize each character
            applyRules(chars, lower, upper, others); // modify according to the problem rules

            out.print(new String(chars));   // write result (original code used print+ln)
            out.println();
        }
    }

    /**
     * Places the indices of the characters into three distinct buckets:
     * <ul>
     *   <li>lower  – lower‑case latin letters</li>
     *   <li>upper  – upper‑case latin letters</li>
     *   <li>others – everything else</li>
     * </ul>
     *
     * @param chars   the character array to examine
     * @param lower   list that will receive indices of lower‑case characters
     * @param upper   list that will receive indices of upper‑case characters
     * @param others  list that will receive indices of all other characters
     */
    private void classify(char[] chars, List<Integer> lower, List<Integer> upper, List<Integer> others) {
        for (int i = 0; i < chars.length; i++) {
            char c = chars[i];
            if ('a' <= c && c <= 'z') {
                lower.add(i);
            } else if ('A' <= c && c <= 'Z') {
                upper.add(i);
            } else {
                others.add(i);
            }
        }
    }

    /**
     * Implements the exact replacement logic from the original program.
     *
     * <p>The method mutates {@code chars} in‑place according to the following
     * priorities:</p>
     *
     * <ol>
     *   <li>If there are no lower‑case letters:
     *       <ul>
     *         <li>No upper‑case letters → replace positions 0 and 1 with {@code 'a'} and {@code 'A'}.</li>
     *         <li>No “other” characters → replace positions 0 and 1 with {@code 'a'} and {@code '1'}.</li>
     *         <li>Otherwise, replace either the first “other” index or the first upper‑case index
     *             with {@code 'a'}, depending on whether there is exactly one upper‑case character.</li>
     *       </ul>
     *   </li>
     *   <li>If there are no upper‑case letters: analogous handling, swapping {@code 'a'} with {@code 'A'}.</li>
     *   <li>If there are no “other” characters, replace the first lower‑case or upper‑case index
     *       with {@code '1'}, depending on whether there is exactly one upper‑case character.</li>
     * </ol>
     *
     * @param chars   mutable character array to modify
     * @param lower   indices of lower‑case characters (may be empty)
     * @param upper   indices of upper‑case characters (may be empty)
     * @param others  indices of all other characters (may be empty)
     */
    private void applyRules(char[] chars, List<Integer> lower, List<Integer> upper, List<Integer> others) {
        if (lower.isEmpty()) {
            if (upper.isEmpty()) {
                // Both lower and upper empty – force at least one of each in the output
                chars[0] = 'a';
                chars[1] = 'A';
            } else if (others.isEmpty()) {
                // No “other” chars – replace first two positions with a pair of symbols
                chars[0] = 'a';
                chars[1] = '1';
            } else {
                // There are “other” characters – replace either the first “other” or first upper‑case
                if (upper.size() == 1) {
                    chars[others.get(0)] = 'a';
                } else {
                    chars[upper.get(0)] = 'a';
                }
            }
        } else if (upper.isEmpty()) {
            if (others.isEmpty()) {
                // No “other” chars – replace positions 0 and 1 with ‘A’ and ‘1’
                chars[0] = 'A';
                chars[1] = '1';
            } else {
                // Replace either the first lower‑case or first “other” index with ‘A’
                if (lower.size() == 1) {
                    chars[others.get(0)] = 'A';
                } else {
                    chars[lower.get(0)] = 'A';
                }
            }
        } else if (others.isEmpty()) {
            // No “other” chars – replace according to the size of the upper list
            if (upper.size() == 1) {
                chars[lower.get(0)] = '1';
            } else {
                chars[upper.get(0)] = '1';
            }
        }
    }

    /* -------------------------------------------------------- */
    /*                  I/O Helper (Fast Scanner)             */
    /* -------------------------------------------------------- */
    private final InputStream is = System.in;
    private final PrintWriter out = new PrintWriter(System.out);

    /** Fast scanner utilities – identical in behaviour to the original implementation. */
    private byte[] input = new byte[1024];
    private int len = 0, ptr = 0;

    private int readByte() {
        if (ptr >= len) {
            ptr = 0;
            try {
                len = is.read(input);
            } catch (IOException e) {
                throw new InputMismatchException();
            }
            if (len <= 0) {
                return -1;
            }
        }
        return input[ptr++];
    }

    private boolean isSpaceChar(int c) {
        return !(c >= 33 && c <= 126);
    }

    private int skip() {
        int b = readByte();
        while (b != -1 && isSpaceChar(b)) {
            b = readByte();
        }
        return b;
    }

    private char nc() {
        return (char) skip();
    }

    /** Reads a single whitespace‑delimited token as a {@code String}. */
    private String ns() {
        int b = skip();
        StringBuilder sb = new StringBuilder();
        while (!isSpaceChar(b)) {
            sb.appendCodePoint(b);
            b = readByte();
        }
        return sb.toString();
    }

    /** Reads a whole line (including spaces) as a {@code String}. */
    private String nLine() {
        int b = skip();
        StringBuilder sb = new StringBuilder();
        while (!(isSpaceChar(b) && b != ' ')) {
            sb.appendCodePoint(b);
            b = readByte();
        }
        return sb.toString();
    }

    /** Reads a signed/unsigned decimal integer. */
    private int ni() {
        int n = 0;
        int b = readByte();
        boolean minus = false;
        while (b != -1 && !( (b >= '0' && b <= '9') || b == '-')) {
            b = readByte();
        }
        if (b == '-') {
            minus = true;
            b = readByte();
        }
        if (b == -1) {
            return -1;
        }
        while (b >= '0' && b <= '9') {
            n = n * 10 + (b - '0');
            b = readByte();
        }
        return minus ? -n : n;
    }

    /** Reads a signed/unsigned decimal long. */
    private long nl() {
        long n = 0L;
        int b = readByte();
        boolean minus = false;
        while (b != -1 && !( (b >= '0' && b <= '9') || b == '-')) {
            b = readByte();
        }
        if (b == '-') {
            minus = true;
            b = readByte();
        }
        while (b >= '0' && b <= '9') {
            n = n * 10 + (b - '0');
            b = readByte();
        }
        return minus ? -n : n;
    }

    /** Reads a double value. */
    private double nd() {
        return Double.parseDouble(ns());
    }

    /** Reads a float value. */
    private float nf() {
        return Float.parseFloat(ns());
    }

    /** Reads an array of {@code int} of length {@code n}. */
    private int[] na(int n) {
        int[] a = new int[n];
        for (int i = 0; i < n; i++) {
            a[i] = ni();
        }
        return a;
    }

    /** Reads a char array of length {@code n} (stops early on whitespace). */
    private char[] ns(int n) {
        char[] c = new char[n];
        int i = 0;
        int b = skip();
        for (; i < n; i++) {
            if (isSpaceChar(b)) {
                break;
            }
            c[i] = (char) b;
            b = readByte();
        }
        return i == n ? c : java.util.Arrays.copyOf(c, i);
    }
    /* -------------------------------------------------------- */

    /** Standard entry point – creates an instance and runs the solution. */
    public static void main(String[] args) {
        new utkarsh().run();
    }

    /** Wrapper that starts timing (if enabled) and invokes {@link #solve()}. */
    private void run() {
        SHOW_TIME = false;                // can be toggled for debugging
        long start = System.currentTimeMillis();
        solve();
        long end = System.currentTimeMillis();
        if (SHOW_TIME) {
            out.println("\n" + (end - start) + " ms");
        }
        out.flush();
    }
}

import java.util.Scanner;

public class StringProcessor {

    /** Enum to clearly identify the three character categories we track. */
    private enum Category {
        UPPER, LOWER, DIGIT
    }

    public static void main(String[] args) {
        // Try‑with‑resources guarantees the Scanner is closed promptly.
        try (Scanner scanner = new Scanner(System.in)) {

            int testCases = scanner.nextInt();
            while (testCases-- > 0) {
                String input = scanner.next();
                System.out.println(fixString(input));
            }
        }
    }

    /**
     * Guarantees that the string contains at least one uppercase letter,
     * one lowercase letter and one digit. Missing categories are appended
     * at the end of the string in a deterministic order (UPPER → LOWER → DIGIT).
     *
     * @param s the original string
     * @return the possibly‑modified string
     */
    private static String fixString(String s) {
        int upperCount  = count(s, Category.UPPER);
        int lowerCount  = count(s, Category.LOWER);
        int digitCount  = count(s, Category.DIGIT);

        // If any category is missing, append the required characters.
        if (upperCount == 0 || lowerCount == 0 || digitCount == 0) {
            StringBuilder result = new StringBuilder(s);

            if (upperCount == 0) {
                result.append('A');          // missing uppercase
            }
            if (lowerCount == 0) {
                result.append('a');          // missing lowercase
            }
            if (digitCount == 0) {
                result.append('0');          // missing digit
            }

            return result.toString();
        }

        // All categories are present – return the string unchanged.
        return s;
    }

    /**
     * Counts how many characters of the given {@link Category} appear in the string.
     *
     * @param s    the string to inspect
     * @param cat  the category to count
     * @return the number of characters belonging to that category
     */
    private static int count(String s, Category cat) {
        int count = 0;
        for (int i = 0; i < s.length(); i++) {
            char ch = s.charAt(i);
            if (cat == Category.UPPER && Character.isUpperCase(ch)) {
                count++;
            } else if (cat == Category.LOWER && Character.isLowerCase(ch)) {
                count++;
            } else if (cat == Category.DIGIT && Character.isDigit(ch)) {
                count++;
            }
        }
        return count;
    }
}

package vasyaPassword;

import java.io.*;
import java.util.StringTokenizer;

/**
 * Reads several test cases and, for each password string,
 * prints it unchanged if it already satisfies all three
 * required character classes (lower‑case, upper‑case, digit).
 * Otherwise it modifies the string minimally so that it does.
 *
 * The original logic is kept, but the implementation has been
 * reorganised for readability, testability and future extensions.
 */
public class VasyaPassword {

    /** Entry point */
    public static void main(String[] args) {
        MyScanner scanner = new MyScanner();
        int t = scanner.nextInt();                     // number of test cases
        while (t-- > 0) {
            String password = scanner.next();
            solve(password);
        }
    }

    /** Main processing routine for a single password */
    private static void solve(String password) {
        // -----------------------------------------------------------------
        // 1️⃣  Gather information about the characters that are present.
        // -----------------------------------------------------------------
        boolean hasLower   = password.chars().anyMatch(Character::isLowerCase);
        boolean hasUpper   = password.chars().anyMatch(Character::isUpperCase);
        boolean hasDigit   = password.chars().anyMatch(Character::isDigit);

        int lowerCount = (int) password.chars().filter(ch -> Character.isLowerCase(ch)).count();
        int upperCount = (int) password.chars().filter(ch -> Character.isUpperCase(ch)).count();
        int digitCount = (int) password.chars().filter(ch -> Character.isDigit(ch)).count();

        // -----------------------------------------------------------------
        // 2️⃣  If the password already meets all three requirements → print it.
        // -----------------------------------------------------------------
        if (hasLower && hasUpper && hasDigit) {
            System.out.println(password);
            return;
        }

        // -----------------------------------------------------------------
        // 3️⃣  Otherwise, fix the password according to the missing classes.
        // -----------------------------------------------------------------
        System.out.println(fixPassword(password, hasLower, hasUpper, hasDigit,
                lowerCount, upperCount, digitCount));
    }

    /** Returns a modified password that satisfies the missing requirements. */
    private static String fixPassword(String s,
                                      boolean hasLower,
                                      boolean hasUpper,
                                      boolean hasDigit,
                                      int lowerCount,
                                      int upperCount,
                                      int digitCount) {

        // The decision tree mirrors the original program but is now
        // expressed with expressive names and small helper methods.
        if (hasLower && hasUpper) {                         // missing a digit
            return hasDigit ? s
                    : (lowerCount > 1
                            ? replaceFirstMatching(s, Character::isLowerCase, '1')
                            : replaceFirstMatching(s, Character::isUpperCase, '1'));
        }

        if (hasUpper && hasDigit) {                         // missing a lower‑case
            return hasLower ? s
                    : (upperCount > 1
                            ? replaceFirstMatching(s, Character::isUpperCase, 'a')
                            : replaceFirstMatching(s, Character::isDigit, 'a'));
        }

        if (hasLower && hasDigit) {                         // missing an upper‑case
            return hasUpper ? s
                    : (lowerCount > 1
                            ? replaceFirstMatching(s, Character::isLowerCase, 'A')
                            : replaceFirstMatching(s, Character::isDigit, 'A'));
        }

        if (hasLower) {                                     // only lower‑case present
            return replaceFirstTwo(s, '1', 'A');
        }

        if (hasUpper) {                                     // only upper‑case present
            return replaceFirstTwo(s, '1', 'a');
        }

        // No required class is present at all.
        return replaceFirstTwo(s, 'a', 'A');
    }

    /** Replaces the first character that matches {@code predicate} with {@code newChar}. */
    private static String replaceFirstMatching(String source,
                                               java.util.function.IntPredicate predicate,
                                               char newChar) {
        char[] arr = source.toCharArray();
        for (int i = 0; i < arr.length; i++) {
            if (predicate.test(arr[i])) {
                arr[i] = newChar;
                break;
            }
        }
        return new String(arr);
    }

    /** Replaces the characters at positions 0 and 1 with the supplied values. */
    private static String replaceFirstTwo(String source, char first, char second) {
        char[] arr = source.toCharArray();
        if (arr.length > 0) arr[0] = first;
        if (arr.length > 1) arr[1] = second;
        return new String(arr);
    }

    /** Simple scanner wrapper used for competitive‑programming style input. */
    static class MyScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        MyScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    throw new UncheckedIOException(e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.io.*;
import java.util.StringTokenizer;
import java.util.function.Predicate;

public class Main {

    public static void main(String[] args) {
        InputStream input = System.in;
        OutputStream output = System.out;
        FastScanner scanner = new FastScanner(input);
        FastOutput out = new FastOutput(output);

        int tests = scanner.nextInt();
        while (tests-- > 0) {
            String s = scanner.next();
            out.println(transform(s));
        }
        out.flush();
    }

    /** Applies the required transformation to the given string. */
    private static String transform(String s) {
        int upper = 0, lower = 0, digit = 0;
        for (char c : s.toCharArray()) {
            if (Character.isUpperCase(c)) {
                upper++;
            } else if (Character.isLowerCase(c)) {
                lower++;
            } else {
                digit++;
            }
        }

        // If all three categories are present, the string is left unchanged.
        if (upper > 0 && lower > 0 && digit > 0) {
            return s;
        }

        boolean hasUpper = upper > 0;
        boolean hasLower = lower > 0;
        boolean hasDigit = digit > 0;

        // ---------- Only one category present ----------
        if (!hasUpper && !hasLower && hasDigit) {          // only digits
            return replaceFirstNC(s, 2, new char[]{'a', 'A'});
        }
        if (!hasUpper && !hasDigit && hasLower) {          // only lowercase
            return replaceFirstNC(s, 2, new char[]{'1', 'A'});
        }
        if (!hasLower && !hasDigit && hasUpper) {          // only uppercase
            return replaceFirstNC(s, 2, new char[]{'1', 'a'});
        }

        // ---------- Exactly two categories present ----------
        // Only letters (no digits)
        if (!hasDigit && hasUpper && hasLower) {
            return (upper > lower)
                    ? replaceFirst(s, Character::isUpperCase, '0')
                    : replaceFirst(s, Character::isLowerCase, '0');
        }
        // Uppercase + digits (lowercase missing)
        if (!hasLower && hasUpper && hasDigit) {
            return (digit > upper)
                    ? replaceFirst(s, Character::isDigit, 'A')
                    : replaceFirst(s, Character::isUpperCase, 'A');
        }
        // Lowercase + digits (uppercase missing)
        if (!hasUpper && hasLower && hasDigit) {
            return (digit > lower)
                    ? replaceFirst(s, Character::isDigit, 'A')
                    : replaceFirst(s, Character::isLowerCase, 'a');
        }

        // Fallback – should never be reached
        return s;
    }

    /** Returns a new string where the first character satisfying {@code predicate}
     *  is replaced by {@code replacement}. */
    private static String replaceFirst(String source, Predicate<Character> predicate, char replacement) {
        StringBuilder sb = new StringBuilder(source);
        for (int i = 0; i < sb.length(); i++) {
            if (predicate.test(sb.charAt(i))) {
                sb.setCharAt(i, replacement);
                break;
            }
        }
        return sb.toString();
    }

    /** Replaces the first {@code n} characters with the values from {@code values}.
     *  If the string is shorter than {@code n}, only the existing prefix is replaced. */
    private static String replaceFirstNC(String source, int n, char[] values) {
        if (n <= 0) return source;
        StringBuilder sb = new StringBuilder(source);
        int limit = Math.min(n, sb.length());
        for (int i = 0; i < limit; i++) {
            sb.setCharAt(i, values[i]);
        }
        return sb.toString();
    }

    // -----------------------------------------------------------------
    // Helper I/O classes
    // -----------------------------------------------------------------
    private static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner(InputStream stream) {
            br = new BufferedReader(new InputStreamReader(stream));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    throw new UncheckedIOException(e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }
    }

    private static class FastOutput {
        private final PrintWriter out;

        FastOutput(OutputStream stream) {
            out = new PrintWriter(new BufferedWriter(new OutputStreamWriter(stream)));
        }

        void println(Object o) {
            out.println(o);
        }

        void flush() {
            out.flush();
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.HashMap;
import java.util.Map;
import java.util.Optional;

/**
 * Utility class that analyses a string with respect to three character categories:
 *   - NUMERIC   (digits 0‑9)
 *   - UPPERCASE (letters A‑Z)
 *   - LOWERCASE (letters a‑z)
 *
 * It can also try to *fix* a string that does not contain all three categories
 * by inserting a missing character(s) at the earliest possible position.
 *
 * The logic mirrors the original implementation but is now organised into
 * small, well‑named methods and classes, making it easier to maintain and
 * extend.
 */
public class Main {

    /** Entry point */
    public static void main(String[] args) {
        FastScanner fs = new FastScanner();

        int testCases = fs.nextInt();
        for (int t = 0; t < testCases; t++) {
            String original = fs.next();
            CategoryInfo info = analyse(original);

            if (info.containsAllThreeCategories()) {
                // Already valid – print the original string
                System.out.println(original);
            } else {
                // Try to obtain a valid string by inserting the missing
                // character(s) at the first suitable position.
                Optional<String> fixed = tryToFix(original, info);
                fixed.ifPresent(System.out::println);
            }
        }
    }

    /** Analyse the supplied string and fill a {@link CategoryInfo} instance. */
    private static CategoryInfo analyse(String s) {
        CategoryInfo info = new CategoryInfo();

        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (Character.isDigit(c)) {
                info.hasDigit = true;
            } else if (Character.isUpperCase(c)) {
                info.hasUpper = true;
            } else if (Character.isLowerCase(c)) {
                info.hasLower = true;
            }
        }
        return info;
    }

    /** Returns the original string if it already contains the three required categories. */
    private static boolean isComplete(CategoryInfo info) {
        return info.hasDigit && info.hasUpper && info.hasLower;
    }

    /**
     * Attempts to fix a string that does not yet contain all three categories.
     * The method follows the same insertion strategy as the original code:
     *
     * <ul>
     *   <li>If only one category is present, insert a *pair* of characters that
     *       introduces the two missing categories.</li>
     *   <li>If exactly two categories are present, insert a *single* character
     *       that introduces the missing one.</li>
     * </ul>
     *
     * The first successful insertion (scanning from left to right) is returned.
     */
    private static Optional<String> tryToFix(String original, CategoryInfo info) {
        int len = original.length();

        // ---- Only one category present (size == 1) -------------------------
        if (!isComplete(info) && info.categoryCount() == 1) {
            // Determine which categories are missing
            MissingCategories missing = MissingCategories.from(info);

            // The original code used three different two‑character insertions
            // depending on the *present* category.
            String insertion;
            switch (missing.presentCategory()) {
                case NUMERIC -> insertion = "Aa";          // need UPPER+LOWER
                case UPPER   -> insertion = "1a";          // need DIGIT+LOWER
                case LOWER   -> insertion = "1A";          // need DIGIT+UPPER
                default -> throw new IllegalStateException();
            }

            // Try every possible insertion position (len-1 positions are valid)
            for (int pos = 0; pos < len - 1; pos++) {
                String candidate = insertAt(original, pos, insertion);
                if (analyse(candidate).containsAllThreeCategories()) {
                    return Optional.of(candidate);
                }
            }
        }

        // ---- Exactly two categories present (size == 2) -------------------
        if (!isComplete(info) && info.categoryCount() == 2) {
            MissingCategories missing = MissingCategories.from(info);
            char singleChar;
            switch (missing.presentCategory()) {
                case NUMERIC -> singleChar = '1';               // need DIGIT
                case UPPER   -> singleChar = 'A';               // need UPPER (already present, so this case never happens)
                case LOWER   -> singleChar = 'a';               // need LOWER (already present)
                default -> throw new IllegalStateException();
            }

            // For the realistic missing categories we only need to handle DIGIT
            // and LOWER when UPPER is missing, or UPPER when DIGIT is missing.
            char missingChar = switch (missing.missingCategories()) {
                case DIGIT -> '1';
                case LOWER -> 'a';
                case UPPER -> 'A';
                default -> '*';
            };

            for (int pos = 0; pos < len; pos++) {
                String candidate = insertAt(original, pos, String.valueOf(missingChar));
                if (analyse(candidate).containsAllThreeCategories()) {
                    return Optional.of(candidate);
                }
            }
        }

        // No fix found – return empty
        return Optional.empty();
    }

    /** Insert {@code token} into {@code base} at position {@code index}. */
    private static String insertAt(String base, int index, String token) {
        return base.substring(0, index) + token + base.substring(index);
    }

    /** --------------------------------------------------------------- */
    /** Holds the three boolean flags describing which categories are present. */
    private static final class CategoryInfo {
        private boolean hasDigit;
        private boolean hasUpper;
        private boolean hasLower;

        /** Does the string contain all three required categories? */
        boolean containsAllThreeCategories() {
            return hasDigit && hasUpper && hasLower;
        }

        /** Number of categories actually present (0‑3). */
        int categoryCount() {
            int count = 0;
            if (hasDigit) count++;
            if (hasUpper) count++;
            if (hasLower) count++;
            return count;
        }

        /** Re‑populate the flags from a string (used for the *fixed* version). */
        void reAnalyse(String s) {
            hasDigit = hasUpper = hasLower = false;
            for (int i = 0; i < s.length(); i++) {
                char c = s.charAt(i);
                if (Character.isDigit(c)) {
                    hasDigit = true;
                } else if (Character.isUpperCase(c)) {
                    hasUpper = true;
                } else if (Character.isLowerCase(c)) {
                    hasLower = true;
                }
            }
        }
    }

    /**
     * Small helper that determines which categories are missing and which one
     * is already present when the string contains only a single category.
     */
    private enum MissingCategories {
        DIGIT_ONLY   (Category.NUMERIC),
        UPPER_ONLY   (Category.UPPER),
        LOWER_ONLY   (Category.LOWER);

        private final Category presentCategory;

        MissingCategories(Category presentCategory) {
            this.presentCategory = presentCategory;
        }

        /** Category that is currently present (only one of the three). */
        Category presentCategory() {
            return presentCategory;
        }

        /** The set of categories that are *missing* from the original string. */
        java.util.Set<Category> missingCategories() {
            java.util.Set<Category> missing = new java.util.HashSet<>();
            for (Category cat : Category.values()) {
                if (cat != presentCategory) {
                    missing.add(cat);
                }
            }
            return missing;
        }

        /** Factory method that builds an instance from a {@link CategoryInfo}. */
        static MissingCategories from(CategoryInfo info) {
            if (info.hasDigit && !info.hasUpper && !info.hasLower) {
                return DIGIT_ONLY;
            }
            if (!info.hasDigit && info.hasUpper && !info.hasLower) {
                return UPPER_ONLY;
            }
            if (!info.hasDigit && !info.hasUpper && info.hasLower) {
                return LOWER_ONLY;
            }
            throw new IllegalStateException("Expected exactly one category");
        }
    }

    /** The three categories we care about – used only for readability. */
    private enum Category {
        NUMERIC,
        UPPER,
        LOWER
    }

    /** --------------------------------------------------------------- */
    /** Very small, fast scanner that mimics the original implementation. */
    private static final class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    throw new UncheckedIOException(e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;

/**
 * Refactored solution for CF1051A.
 * The program reads several test cases, each containing a string.
 * It applies simple transformation rules based on the presence of
 * lowercase letters, uppercase letters and non‑letter characters.
 */
public class CF1051A {

    /* Constants used for replacements */
    private static final char LOWER_REPLACEMENT = 'a';
    private static final char UPPER_REPLACEMENT = 'A';
    private static final char DIGIT_REPLACEMENT = '8';

    /* Enum to describe which category is missing */
    private enum MissingCategory { NONE, LOWER, UPPER, DIGIT }

    /* Simple DTO to keep the three counters together */
    private static final class CategoryCounts {
        final int lower;
        final int upper;
        final int other;

        CategoryCounts(int lower, int upper, int other) {
            this.lower = lower;
            this.upper = upper;
            this.other = other;
        }

        boolean allPresent() {
            return lower > 0 && upper > 0 && other > 0;
        }

        boolean onlyOnePresent() {
            return (lower > 0 && upper == 0 && other == 0) ||
                   (lower == 0 && upper > 0 && other == 0) ||
                   (lower == 0 && upper == 0 && other > 0);
        }
    }

    public static void main(String[] args) throws IOException {
        /* Fast reading of input */
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in))) {
            int t = Integer.parseInt(br.readLine().trim());

            StringBuilder output = new StringBuilder();
            for (int i = 0; i < t; i++) {
                String line = br.readLine().trim();
                output.append(process(line)).append('\n');
            }
            System.out.print(output.toString());
        }
    }

    /**
     * Main processing routine for a single input string.
     */
    private static String process(String input) {
        CategoryCounts counts = countCategories(input);

        // 1️⃣ All three categories present → nothing to change
        if (counts.allPresent()) {
            return input;
        }

        // 2️⃣ Only one category is present (two missing) → replace first two chars
        if (counts.onlyOnePresent()) {
            char first, second;
            if (counts.lower > 0) {                 // only lowercase letters
                first = LOWER_REPLACEMENT;
                second = UPPER_REPLACEMENT;
            } else if (counts.upper > 0) {          // only uppercase letters
                first = LOWER_REPLACEMENT;
                second = DIGIT_REPLACEMENT;
            } else {                                // only non‑letter characters
                first = DIGIT_REPLACEMENT;
                second = UPPER_REPLACEMENT;
            }
            char[] arr = input.toCharArray();
            arr[0] = first;
            arr[1] = second;
            return new String(arr);
        }

        // 3️⃣ Exactly one category is missing → fix it by changing the first suitable character
        MissingCategory missing = determineMissingCategory(counts);
        char[] arr = input.toCharArray();
        switch (missing) {
            case LOWER -> replaceFirstNonLower(arr);
            case UPPER -> replaceFirstNonUpper(arr);
            case DIGIT -> replaceFirstNonDigit(arr);
        }
        return new String(arr);
    }

    /** Counts lowercase, uppercase and other characters in the string. */
    private static CategoryCounts countCategories(String s) {
        int lower = 0, upper = 0, other = 0;
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (Character.isLowerCase(c)) {
                lower++;
            } else if (Character.isUpperCase(c)) {
                upper++;
            } else {
                other++;
            }
        }
        return new CategoryCounts(lower, upper, other);
    }

    /** Determines which single category is missing (lowercase, uppercase or digit/other). */
    private static MissingCategory determineMissingCategory(CategoryCounts counts) {
        if (counts.lower == 0) return MissingCategory.LOWER;
        if (counts.upper == 0) return MissingCategory.UPPER;
        // otherwise the missing category corresponds to “other” (i.e., non‑letter characters)
        return MissingCategory.DIGIT;
    }

    /** Replaces the first character that is not lowercase with LOWER_REPLACEMENT. */
    private static void replaceFirstNonLower(char[] arr) {
        for (int i = 0; i < arr.length; i++) {
            if (!Character.isLowerCase(arr[i])) {
                arr[i] = LOWER_REPLACEMENT;
                break;
            }
        }
    }

    /** Replaces the first character that is not uppercase with UPPER_REPLACEMENT. */
    private static void replaceFirstNonUpper(char[] arr) {
        for (int i = 0; i < arr.length; i++) {
            if (!Character.isUpperCase(arr[i])) {
                arr[i] = UPPER_REPLACEMENT;
                break;
            }
        }
    }

    /** Replaces the first character that is not a digit with DIGIT_REPLACEMENT. */
    private static void replaceFirstNonDigit(char[] arr) {
        for (int i = 0; i < arr.length; i++) {
            if (!Character.isDigit(arr[i])) {
                arr[i] = DIGIT_REPLACEMENT;
                break;
            }
        }
    }
}

import java.util.*;

public class VasyaPassword {

    /** The three character categories that a password must contain. */
    private enum CharCategory { DIGIT, LOWER, UPPER }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int testCases = scanner.nextInt();
        scanner.nextLine();                       // consume trailing newline

        for (int i = 0; i < testCases; i++) {
            String password = scanner.nextLine();
            System.out.println(strengthenPassword(password));
        }
    }

    /**
     * Guarantees that the password contains at least one digit,
     * one lower‑case letter and one upper‑case letter.
     * <p>
     * The algorithm
     * <ul>
     *   <li>detects which categories are already satisfied,</li>
     *   <li>collects the missing categories,</li>
     *   <li>finds distinct positions that are *not* already occupied by a
     *       required character,</li>
     *   <li>replaces those positions with the minimal set of characters that
     *       fulfil the missing categories.</li>
     * </ul>
     * All changes are made with the smallest possible number of modifications
     * and never overwrite a character that already satisfies a required
     * category.
     *
     * @param original the original password
     * @return a modified password that meets the requirements
     */
    private static String strengthenPassword(String original) {
        char[] buf = original.toCharArray();

        /* -------------------------------------------------------------
         * 1. Detect which categories are already present and remember one
         *    representative index for each of them.
         * ------------------------------------------------------------- */
        boolean hasDigit = false, hasLower = false, hasUpper = false;
        int digitPos = -1, lowerPos = -1, upperPos = -1;

        for (int i = 0; i < buf.length; i++) {
            char c = buf[i];
            if (Character.isDigit(c)) {
                hasDigit = true;
                digitPos = i;
            } else if (Character.isLowerCase(c)) {
                hasLower = true;
                lowerPos = i;
            } else if (Character.isUpperCase(c)) {
                hasUpper = true;
                upperPos = i;
            }
        }

        /* -------------------------------------------------------------
         * 2. Determine which categories are missing.
         * ------------------------------------------------------------- */
        Set<CharCategory> missing = new EnumSet<>(CharCategory.class);
        if (!hasDigit) missing.add(CharCategory.DIGIT);
        if (!hasLower) missing.add(CharCategory.LOWER);
        if (!hasUpper) missing.add(CharCategory.UPPER);

        /* -------------------------------------------------------------
         * 3. Find free positions that are not currently used by a
         *    required category. We need exactly as many free positions as
         *    missing categories.
         * ------------------------------------------------------------- */
        List<Integer> freePositions = new ArrayList<>();
        for (int i = 0; i < buf.length; i++) {
            boolean reserved = false;
            if (hasDigit && i == digitPos) reserved = true;
            if (hasLower && i == lowerPos) reserved = true;
            if (hasUpper && i == upperPos) reserved = true;
            if (!reserved) {
                freePositions.add(i);
            }
        }

        /* -------------------------------------------------------------
         * 4. Apply the minimal set of replacements.
         * ------------------------------------------------------------- */
        int replacementIndex = 0;
        for (CharCategory cat : missing) {
            char replacer = switch (cat) {
                case DIGIT    -> '1';
                case LOWER    -> 'a';
                case UPPER    -> Character.toUpperCase('a');
            };
            int pos = freePositions.get(replacementIndex++);
            buf[pos] = replacer;
        }

        return new String(buf);
    }
}

import java.io.*;
import java.util.*;

public class Main {

    /* -------------------------------------------------------------
     *  Fast scanner/reader – preserves the original speed‑optimised
     *  input handling while keeping the code clean.
     * -------------------------------------------------------------*/
    private static class FastScanner {
        private final InputStream stream;
        private final byte[] buffer = new byte[1024];
        private int ptr = 0, len = 0;

        FastScanner(InputStream stream) {
            this.stream = stream;
        }

        private int readByte() throws IOException {
            if (ptr >= len) {
                len = stream.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        private boolean isSpace(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        private int nextInt() throws IOException {
            int c, sign = 1, val = 0;
            do { c = readByte(); } while (isSpace(c));
            if (c == '-') { sign = -1; c = readByte(); }
            while (!isSpace(c)) {
                val = val * 10 + (c - '0');
                c = readByte();
            }
            return val * sign;
        }

        private String nextToken() throws IOException {
            int c;
            do { c = readByte(); } while (isSpace(c));
            StringBuilder sb = new StringBuilder();
            do {
                sb.append((char) c);
                c = readByte();
            } while (!isSpace(c));
            return sb.toString();
        }

        private String nextLine() throws IOException {
            StringBuilder sb = new StringBuilder();
            int c;
            do { c = readByte(); } while (c < ' ');
            while (c != '\n' && c != '\r' && c != -1) {
                sb.append((char) c);
                c = readByte();
            }
            return sb.toString();
        }
    }

    /* -------------------------------------------------------------
     *  Utility: check whether a string contains at least one uppercase,
     *  one lowercase and one “other” character (the original program
     *  treats any character that is not a letter as the third category).
     * -------------------------------------------------------------*/
    private static boolean hasAllThree(String s) {
        boolean upper = false, lower = false, other = false;
        for (char ch : s.toCharArray()) {
            if (Character.isUpperCase(ch)) {
                upper = true;
            } else if (Character.isLowerCase(ch)) {
                lower = true;
            } else {
                other = true;
            }
        }
        return upper && lower && other;
    }

    /* -------------------------------------------------------------
     *  Try to fix the string by changing a single character.
     *  The three candidates correspond to the three categories:
     *   – '1' (or any digit) → “other”
     *   – 'a'               → lowercase
     *   – 'A'               → uppercase
     *  If any candidate makes the modified string satisfy the condition,
     *  that modified string is returned.
     * -------------------------------------------------------------*/
    private static Optional<String> fixSingleChar(String s) {
        char[] arr = s.toCharArray();
        for (int i = 0; i < arr.length; i++) {
            char original = arr[i];
            for (char candidate : new char[]{'1', 'a', 'A'}) {
                arr[i] = candidate;
                if (hasAllThree(new String(arr))) {
                    return Optional.of(new String(arr));
                }
            }
            arr[i] = original;   // restore original character
        }
        return Optional.empty();
    }

    /* -------------------------------------------------------------
     *  Try to fix the string by changing two adjacent characters.
     *  The original code used three specific adjacent replacements:
     *   – "5" + "a"
     *   – "1" + "A"
     *   – "A" + "a"
     *  If any of those replacements yields a string that satisfies the
     *  condition, it is returned.
     * -------------------------------------------------------------*/
    private static Optional<String> fixTwoAdjacent(String s) {
        char[] arr = s.toCharArray();
        // the three concrete adjacent replacements used originally
        char[][] replacements = {
                new char[]{'5', 'a'},
                new char[]{'1', 'A'},
                new char[]{'A', 'a'}
        };

        for (int i = 0; i < arr.length - 1; i++) {
            char saved0 = arr[i];
            char saved1 = arr[i + 1];
            for (char[] repl : replacements) {
                arr[i] = repl[0];
                arr[i + 1] = repl[1];
                if (hasAllThree(new String(arr))) {
                    return Optional.of(new String(arr));
                }
            }
            // restore original characters for the next iteration
            arr[i] = saved0;
            arr[i + 1] = saved1;
        }
        return Optional.empty();
    }

    /* -------------------------------------------------------------
     *  Main driver – reads test cases, applies the checks above and
     *  prints the required output.
     * -------------------------------------------------------------*/
    public static void main(String[] args) throws IOException {
        FastScanner sc = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(System.out, true);

        int t = sc.nextInt();                     // number of test cases
        while (t-- > 0) {
            String s = sc.nextToken();            // each test case string

            // Already valid → just output it
            if (hasAllThree(s)) {
                out.println(s);
                continue;
            }

            // Try to obtain a valid string by a single‑character change
            Optional<String> result = fixSingleChar(s);
            if (!result.isPresent()) {
                // Fallback to a two‑character adjacent change
                result = fixTwoAdjacent(s);
            }

            // Print the result only if a transformation succeeded
            result.ifPresent(out::println);
        }
    }
}

import java.io.*;
import java.util.*;

public class VasyaAndPassword {

    private static final PrintWriter OUT = new PrintWriter(System.out, true);
    private static final InputReader IN = new InputReader(System.in);

    public static void main(String[] args) throws Exception {
        // Run inside its own thread for faster I/O on some judges
        new Thread(() -> {
            try {
                solve();
            } catch (Exception e) {
                e.printStackTrace();
                System.exit(1);
            }
        }).start();
    }

    /** Core logic for each test case */
    private static void solve() {
        long startTime = System.currentTimeMillis();

        int t = IN.nextInt();
        while (t-- > 0) {
            String raw = IN.readString().trim();          // read and trim password
            char[] pwd = raw.toCharArray();                // work on a mutable array

            // -----------------------------------------------------------------
            // Collect positions and counts of lower‑case, upper‑case and digits
            // -----------------------------------------------------------------
            List<Integer> lowerPos = new ArrayList<>();
            List<Integer> upperPos = new ArrayList<>();
            List<Integer> digitPos = new ArrayList<>();

            int lowerCnt = 0, upperCnt = 0, digitCnt = 0;
            for (int i = 0; i < pwd.length; i++) {
                char c = pwd[i];
                if (Character.isLowerCase(c)) {
                    lowerPos.add(i);
                    lowerCnt++;
                } else if (Character.isUpperCase(c)) {
                    upperPos.add(i);
                    upperCnt++;
                } else if (Character.isDigit(c)) {
                    digitPos.add(i);
                    digitCnt++;
                }
            }

            // ---------------------------------------------------------------
            // If the password already meets all three criteria, output it
            // ---------------------------------------------------------------
            if (lowerCnt > 0 && upperCnt > 0 && digitCnt > 0) {
                printPassword(pwd);
                OUT.println();
                continue;
            }

            // ---------------------------------------------------------------
            // Apply the minimal correction required (exactly the same rules
            // as the original program but with clearer variable names)
            // ---------------------------------------------------------------
            if (lowerCnt == 0 && upperCnt != 0 && digitCnt != 0) {
                // Need to introduce a lower‑case character
                if (digitCnt >= upperCnt) {
                    pwd[digitPos.get(0)] = 'a';
                } else {
                    pwd[upperPos.get(0)] = 'a';
                }
            } else if (lowerCnt != 0 && upperCnt == 0 && digitCnt != 0) {
                // Need to introduce an upper‑case character
                if (digitCnt >= lowerCnt) {
                    pwd[digitPos.get(0)] = 'A';
                } else {
                    pwd[lowerPos.get(0)] = 'A';
                }
            } else if (lowerCnt != 0 && upperCnt != 0 && digitCnt == 0) {
                // Need to introduce a digit
                if (lowerCnt >= upperCnt) {
                    pwd[lowerPos.get(0)] = '1';
                } else {
                    pwd[upperPos.get(0)] = '1';
                }
            } else if (lowerCnt == 0 && upperCnt == 0 && digitCnt != 0) {
                // No lower‑case or upper‑case at all
                pwd[0] = 'a';
                pwd[1] = 'A';
            } else if (lowerCnt == 0 && upperCnt != 0 && digitCnt == 0) {
                // No lower‑case or digit at all
                pwd[0] = '1';
                pwd[1] = 'a';
            } else { // all three counts are zero
                pwd[0] = 'A';
                pwd[1] = '1';
            }

            printPassword(pwd);
            OUT.println();
        }

        // -----------------------------------------------------------------
        // Execution timing (mirrors the original program's output)
        // -----------------------------------------------------------------
        long execTimeSec = (System.currentTimeMillis() - startTime) / 1000.0;
        OUT.printf("\nExecution time was :- %.6f s%n", execTimeSec);
    }

    /** Helper that prints the password characters separated by a space */
    private static void printPassword(char[] pwd) {
        StringBuilder sb = new StringBuilder();
        for (char c : pwd) {
            sb.append(c).append(' ');
        }
        // Remove trailing space before the newline that the original code adds
        OUT.print(sb.toString().trim());
    }

    /* --------------------------------------------------------------------
       Fast scanner utilities – kept almost identical to the original
       implementation but renamed for readability.
       -------------------------------------------------------------------- */
    private static class InputReader {
        private final InputStream stream;
        private final byte[] buffer = new byte[1 << 16];
        private int curPos = 0, endPos = 0;

        InputReader(InputStream stream) {
            this.stream = stream;
        }

        private int read() throws IOException {
            if (curPos >= endPos) {
                endPos = stream.read(buffer);
                curPos = 0;
                if (endPos <= 0) {
                    return -1;
                }
            }
            return buffer[curPos++];
        }

        private boolean isSpaceChar(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        /** Reads the next non‑whitespace token */
        String readString() {
            int c = read();
            while (isSpaceChar(c)) c = read();
            StringBuilder sb = new StringBuilder();
            do {
                sb.append((char) c);
                c = read();
            } while (!isSpaceChar(c));
            return sb.toString();
        }

        int nextInt() {
            int c = read();
            while (isSpaceChar(c)) c = read();
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            int result = 0;
            while (!isSpaceChar(c)) {
                if (c < '0' || c > '9') {
                    throw new InputMismatchException();
                }
                result = result * 10 + (c - '0');
                c = read();
            }
            return result * sign;
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

/**
 * Refactored version of the original program.
 *
 * <p>Key improvements:</p>
 * <ul>
 *   <li>Single responsibility methods – parsing, analysis and fixing are separated.</li>
 *   <li>Descriptive naming and small helper classes.</li>
 *   <li>Early‑exit returns instead of deep nesting.</li>
 *   <li>Encapsulation of “missing type” information.</li>
 *   <li>No reliance on raw {@code StringTokenizer} – we read whole lines and trim.</li>
 * </ul>
 */
public class PasswordProcessor {

    /** Character constants used for missing‑type insertion. */
    private static final char LOWER = 'a';
    private static final char UPPER = 'A';
    private static final char DIGIT = '1';

    /** Entry point. */
    public static void main(String[] args) throws IOException {
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in))) {
            int testCases = readInt(br);
            for (int i = 0; i < testCases; i++) {
                String password = readLineTrimmed(br);
                MissingTypeSet missing = analyse(password);
                fixPassword(password.toCharArray(), missing);
                System.out.println(new String(password.toCharArray()));
            }
        }
    }

    /* --------------------------- Input helpers --------------------------- */

    private static int readInt(BufferedReader br) throws IOException {
        String token = readLineTrimmed(br);
        return Integer.parseInt(token);
    }

    private static String readLineTrimmed(BufferedReader br) throws IOException {
        String line = br.readLine();
        return line == null ? "" : line.trim();
    }

    /* --------------------------- Analysis --------------------------- */

    /** Holds the three possible missing character groups. */
    private static final class MissingTypeSet {
        private final int lower;   // missing lower‑case letters
        private final int upper;   // missing upper‑case letters
        private final int digit;   // missing digits

        MissingTypeSet(int lower, int upper, int digit) {
            this.lower = lower;
            this.upper = upper;
            this.digit = digit;
        }

        /** Total number of groups that are missing. */
        int issueCount() {
            int cnt = 0;
            if (lower == 0) cnt++;
            if (upper == 0) cnt++;
            if (digit == 0) cnt++;
            return cnt;
        }

        /** Convenience checks for the caller. */
        boolean isMissingLower() { return lower == 0; }
        boolean isMissingUpper() { return upper == 0; }
        boolean isMissingDigit() { return digit == 0; }

        int lowerCount()    { return lower; }
        int upperCount()    { return upper; }
        int digitCount()    { return digit; }
    }

    private static MissingTypeSet analyse(String password) {
        int lower = 0, upper = 0, digit = 0;
        for (char c : password.toCharArray()) {
            if (Character.isLowerCase(c)) lower++;
            else if (Character.isUpperCase(c)) upper++;
            else if (Character.isDigit(c)) digit++;
        }
        return new MissingTypeSet(lower, upper, digit);
    }

    /* --------------------------- Fixing --------------------------- */

    /**
     * Mutates the password array in‑place according to the missing‑type rules.
     *
     * <p>The algorithm mirrors the original behaviour but is expressed with
     * clearer intent and safeguarded against {@code IndexOutOfBoundsException}.</p>
     */
    private static void fixPassword(char[] pwd, MissingTypeSet missing) {
        if (missing.issueCount() == 1) {
            fixSingleMissingType(pwd, missing);
        } else {
            // Add missing characters at the beginning to keep output format stable.
            if (missing.isMissingLower()) {
                pwd[0] = LOWER;
                pwd[1] = DIGIT;
            } else if (missing.isMissingUpper()) {
                pwd[0] = UPPER;
                pwd[1] = DIGIT;
            } else { // missing digit
                pwd[0] = LOWER;
                pwd[1] = UPPER;
            }
        }
    }

    /** Addresses the case where exactly one type is missing. */
    private static void fixSingleMissingType(char[] pwd, MissingTypeSet missing) {
        int pos = findAdjacentSameCategory(pwd);
        if (pos < 0) {               // fallback – nothing to replace safely
            pos = 0;
        }

        if (missing.isMissingLower()) {
            pwd[pos] = LOWER;
        } else if (missing.isMissingUpper()) {
            // Preserve the original “only one upper case available” rule
            if (missing.upperCount() > 1) {
                pwd[pos] = UPPER;
            } else {
                pwd[pos + 1] = UPPER;
            }
        } else { // missing digit
            if (missing.digitCount() > 1) {
                pwd[pos] = DIGIT;
            } else {
                pwd[pos + 1] = DIGIT;
            }
        }
    }

    /** Returns the index of the first adjacent pair that share the same category. */
    private static int findAdjacentSameCategory(char[] arr) {
        for (int i = 0; i < arr.length - 1; i++) {
            boolean sameLower = isLower(arr[i]) && isLower(arr[i + 1]);
            boolean sameUpper = isUpper(arr[i]) && isUpper(arr[i + 1]);
            boolean sameDigit = isDigit(arr[i]) && isDigit(arr[i + 1]);
            if (sameLower || sameUpper || sameDigit) {
                return i;
            }
        }
        return -1;
    }

    private static boolean isLower(char c) { return Character.isLowerCase(c); }
    private static boolean isUpper(char c) { return Character.isUpperCase(c); }
    private static boolean isDigit(char c) { return Character.isDigit(c); }
}

import java.io.*;
import java.util.*;

public class Solution {

    /** Simple fast scanner that reads ints, longs and strings from stdin. */
    private static class FastInput {
        private final InputStream stream;
        private final byte[] buffer = new byte[8192];
        private int bufferPos = 0, bufferLen = 0;

        FastInput(InputStream stream) {
            this.stream = stream;
        }

        private int readByte() {
            if (bufferPos >= bufferLen) {
                bufferLen = stream.read(buffer);
                bufferPos = 0;
                if (bufferLen <= 0) return -1;
            }
            return buffer[bufferPos++];
        }

        private boolean isSpaceChar(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        private boolean isEndOfLine(int c) {
            return c == '\n' || c == '\r' || c == -1;
        }

        /** Reads the next token as a string (skipping leading whitespace). */
        String readString() {
            int c;
            do {
                c = readByte();
            } while (isSpaceChar(c));
            StringBuilder sb = new StringBuilder();
            do {
                sb.appendCodePoint(c);
                c = readByte();
            } while (!isSpaceChar(c));
            return sb.toString();
        }

        /** Reads the next integer token. */
        int nextInt() {
            int sign = 1, c = readByte(), value = 0;
            while (isSpaceChar(c)) c = readByte();
            if (c == '-') {
                sign = -1;
                c = readByte();
            }
            while (!isSpaceChar(c)) {
                value = value * 10 + (c - '0');
                c = readByte();
            }
            return value * sign;
        }

        /** Reads the next long token. */
        long nextLong() {
            int sign = 1, c = readByte(), value = 0;
            while (isSpaceChar(c)) c = readByte();
            if (c == '-') {
                sign = -1;
                c = readByte();
            }
            while (!isSpaceChar(c)) {
                value = value * 10 + (c - '0');
                c = readByte();
            }
            return sign * (long) value;
        }
    }

    /** Classification result for a character. */
    private enum CharCategory {
        LOWER, UPPER, DIGIT
    }

    /** Holds the counts of each character type in a string. */
    private static final class CharStatistics {
        final int lower;
        final int upper;
        final int digit;

        CharStatistics(int lower, int upper, int digit) {
            this.lower = lower;
            this.upper = upper;
            this.digit = digit;
        }
    }

    /** Determines the type of transformation that must be applied. */
    private enum Transformation {
        /** Original string already contains at least one lower, upper and digit. */
        KEEP_ORIGINAL,
        /** Needs a leading uppercase letter + a digit at position 1. */
        PREFIX_UPPER_DIGIT,
        /** Needs a leading lowercase letter + a digit at position 1. */
        PREFIX_LOWER_DIGIT,
        /** Needs a leading lowercase letter + an uppercase letter at position 1. */
        PREFIX_LOWER_UPPER,
        /** Replace the first lower‑case letter with '0' (if more than one lower‑case). */
        REPLACE_FIRST_LOWER_WITH_ZERO,
        /** Replace the first uppercase letter with '0' (if more than one uppercase). */
        REPLACE_FIRST_UPPER_WITH_ZERO,
        /** Replace the first digit with '0' (if more than one digit). */
        REPLACE_FIRST_DIGIT_WITH_ZERO,
        /** Replace the first lower‑case letter with 'A'. */
        REPLACE_FIRST_LOWER_WITH_A,
        /** Replace the first upper‑case letter with 'a'. */
        REPLACE_FIRST_UPPER_WITH_A,
        /** Replace the first digit with 'A'. */
        REPLACE_FIRST_DIGIT_WITH_A
    }

    /** Main processing routine for a single test case. */
    private static void solve(FastInput in, PrintWriter out) {
        String original = in.readString();
        CharStatistics stats = countCharacterTypes(original);
        Transformation type = decideTransformation(stats, original);

        String result = handleTransformation(original, type);
        out.println(result);
    }

    /** Counts how many lower‑case, upper‑case and digit characters are present. */
    private static CharStatistics countCharacterTypes(String s) {
        int lower = 0, upper = 0, digit = 0;
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (Character.isLowerCase(c)) {
                lower++;
            } else if (Character.isUpperCase(c)) {
                upper++;
            } else if (Character.isDigit(c)) {
                digit++;
            }
        }
        return new CharStatistics(lower, upper, digit);
    }

    /** Decides which transformation must be applied based on the statistics. */
    private static Transformation decideTransformation(CharStatistics stats, String s) {
        int lower = stats.lower;
        int upper = stats.upper;
        int digit = stats.digit;

        // 1. All three categories present → keep original.
        if (lower > 0 && upper > 0 && digit > 0) {
            return Transformation.KEEP_ORIGINAL;
        }

        // 2. Only lower‑case letters.
        if (lower > 0 && upper == 0 && digit == 0) {
            return Transformation.PREFIX_UPPER_DIGIT;
        }
        // 3. Only upper‑case letters.
        if (upper > 0 && lower == 0 && digit == 0) {
            return Transformation.PREFIX_LOWER_DIGIT;
        }
        // 4. Only digits.
        if (lower == 0 && upper == 0 && digit > 0) {
            return Transformation.PREFIX_LOWER_UPPER;
        }

        // 5. Lower + Upper, no digits.
        if (lower > 0 && upper > 0 && digit == 0) {
            return lower > 1 ? Transformation.REPLACE_FIRST_LOWER_WITH_ZERO
                             : (upper > 1 ? Transformation.REPLACE_FIRST_UPPER_WITH_ZERO
                                        : Transformation.KEEP_ORIGINAL);
        }
        // 6. Lower + Digit, no upper.
        if (lower > 0 && digit > 0 && upper == 0) {
            return lower > 1 ? Transformation.REPLACE_FIRST_LOWER_WITH_A
                             : (digit > 1 ? Transformation.REPLACE_FIRST_DIGIT_WITH_A
                                        : Transformation.KEEP_ORIGINAL);
        }
        // 7. Upper + Digit, no lower.
        if (upper > 0 && digit > 0 && lower == 0) {
            return upper > 1 ? Transformation.REPLACE_FIRST_UPPER_WITH_A
                             : (digit > 1 ? Transformation.REPLACE_FIRST_DIGIT_WITH_A
                                        : Transformation.KEEP_ORIGINAL);
        }

        // Fallback – should never reach here with valid input.
        return Transformation.KEEP_ORIGINAL;
    }

    /** Applies the chosen transformation to the original string. */
    private static String applyTransformation(String original, Transformation type) {
        // For the “prefix” transformations we need at least two characters.
        if (type == Transformation.PREFIX_UPPER_DIGIT) {
            return "A0" + original.substring(2);
        }
        if (type == Transformation.PREFIX_LOWER_DIGIT) {
            return "a0" + original.substring(2);
        }
        if (type == Transformation.PREFIX_LOWER_UPPER) {
            return "aA" + original.substring(2);
        }

        // Transformations that replace a single character at a known index.
        switch (type) {
            case REPLACE_FIRST_LOWER_WITH_ZERO:
                return replaceFirstMatching(original, Character::isLowerCase, '0');
            case REPLACE_FIRST_UPPER_WITH_ZERO:
                return replaceFirstMatching(original, Character::isUpperCase, '0');
            case REPLACE_FIRST_DIGIT_WITH_ZERO:
                return replaceFirstMatching(original, Character::isDigit, '0');
            case REPLACE_FIRST_LOWER_WITH_A:
                return replaceFirstMatching(original, Character::isLowerCase, 'A');
            case REPLACE_FIRST_UPPER_WITH_A:
                return replaceFirstMatching(original, Character::isUpperCase, 'a');
            case REPLACE_FIRST_DIGIT_WITH_A:
                return replaceFirstMatching(original, Character::isDigit, 'A');
            default:
                // Should never happen for valid input.
                return original;
        }
    }

    /** Utility: replace the first character that satisfies `predicate` with `replacement`. */
    private static String replaceFirstMatching(String s, java.util.function.Predicate<Character> predicate, char replacement) {
        int index = -1;
        for (int i = 0; i < s.length(); i++) {
            if (predicate.test(s.charAt(i))) {
                index = i;
                break;
            }
        }
        if (index < 0) {
            // No matching character – return original (should not happen under problem constraints).
            return s;
        }
        // Build a new string with the replacement at the found index.
        return new StringBuilder(s).replace(index, index + 1, String.valueOf(replacement)).toString();
    }

    /** Entry point – reads input, runs `solve` for every test case, writes output. */
    public static void main(String[] args) throws Exception {
        FastInput in = new FastInput(System.in);
        PrintWriter out = new PrintWriter(System.out);
        int t = in.nextInt();
        for (int i = 0; i < t; i++) {
            solve(in, out);
        }
        out.close();
    }
}

import java.io.*;
import java.util.*;

/**
 * Refactored version of the original program.
 *
 * <p>
 *  The program reads multiple test cases. For each test case a string is processed
 *  according to the following rules:
 * <ul>
 *   <li>If the string already contains at least one digit, one lowercase letter
 *       and one uppercase letter, it is printed unchanged.
 *   <li>Otherwise the smallest possible string that guarantees the presence of
 *       a digit, an uppercase and a lowercase character is produced.
 *       The original characters are kept in their original order, but a sentinel
 *       character is inserted before the first occurrence of each missing category
 *       ( '1' for a digit, 'A' for an uppercase letter, 'a' for a lowercase letter).
 *       If a required category never appears in the original string, its sentinel
 *       is appended at the end.
 * </ul>
 * </p>
 *
 * <p>All input handling, processing and output are kept in separate, clearly‑named
 * helper classes/methods to improve readability and maintainability.</p>
 */
public class Main {

    /** Simple wrapper around {@link BufferedReader} that supplies convenient token
     *  extraction methods. */
    private static class InputReader {
        private final BufferedReader br;
        private StringTokenizer st;

        InputReader() throws IOException {
            this.br = new BufferedReader(new InputStreamReader(System.in));
        }

        /** Returns the next token or throws {@link IOException} on EOF. */
        String next() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                st = new StringTokenizer(br.readLine());
            }
            return st.nextToken();
        }

        /** Reads the next full line (including empty lines). */
        String nextLine() throws IOException {
            return br.readLine();
        }

        /** Shortcut for reading an {@code int}. */
        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }

        /** Shortcut for reading a {@code long}. */
        long nextLong() throws IOException {
            return Long.parseLong(next());
        }

        /** Shortcut for reading a {@code double}. */
        double nextDouble() throws IOException {
            return Double.parseDouble(next());
        }
    }

    /**
     * Transform a single input string according to the problem’s requirements.
     *
     * @param input the raw string read from the test case
     * @return the possibly‑modified string that guarantees at least one digit,
     *         one lowercase and one uppercase character
     */
    private static String transform(String input) {
        // ------------------------------------------------------------
        // 1️⃣  Check whether the string already satisfies all three categories.
        // ------------------------------------------------------------
        boolean hasDigit = false, hasLower = false, hasUpper = false;
        for (int i = 0; i < input.length(); i++) {
            char ch = input.charAt(i);
            if (Character.isDigit(ch)) {
                hasDigit = true;
            } else if (Character.isLowerCase(ch)) {
                hasLower = true;
            } else if (Character.isUpperCase(ch)) {
                hasUpper = true;
            }
        }

        // If all three are present we can return the original unchanged.
        if (hasDigit && hasLower && hasUpper) {
            return input;
        }

        // ------------------------------------------------------------
        // 2️⃣  Build the output respecting the “first‑occurrence” rule.
        // ------------------------------------------------------------
        StringBuilder sb = new StringBuilder();
        boolean addedDigit = false;
        boolean addedUpper = false;
        boolean addedLower = false;

        for (int i = 0; i < input.length(); i++) {
            char ch = input.charAt(i);

            // Insert a sentinel before the first occurrence of each missing type.
            if (Character.isDigit(ch) && !addedDigit) {
                sb.append('1');
                addedDigit = true;
            } else if (Character.isUpperCase(ch) && !addedUpper) {
                sb.append('A');
                addedUpper = true;
            } else if (Character.isLowerCase(ch) && !addedLower) {
                sb.append('a');
                addedLower = true;
            }

            // Preserve the original character.
            sb.append(ch);
        }

        // If a required category never appeared, append its sentinel at the end.
        if (!addedDigit) {
            sb.append('1');
        }
        if (!addedUpper) {
            sb.append('A');
        }
        if (!addedLower) {
            sb.append('a');
        }

        return sb.toString();
    }

    /** Program entry point – reads test cases, processes them and prints the results. */
    public static void main(String[] args) throws Exception {
        InputReader reader = new InputReader();
        int numberOfTests = reader.nextInt();

        StringBuilder output = new StringBuilder();

        for (int tc = 0; tc < numberOfTests; tc++) {
            String current = reader.next();          // each test case is a single token
            String transformed = transform(current); // apply the refactored logic
            output.append(transformed).append('\n'); // each result on its own line
        }

        System.out.print(output.toString());
    }
}

import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;

/**
 * Refactored version of the original program.
 *
 * <p>
 * The program reads several test cases. For each test case it receives a string that may
 * contain lower‑case letters, upper‑case letters and digits. It tries to transform the
 * string so that it contains at least one character of each of the three categories
 * (lower‑case, upper‑case, digit). If the original string already contains all three,
 * the string is printed unchanged. Otherwise the algorithm repeatedly replaces a
 * duplicate character of a category that is still present with a character belonging
 * to a missing category, following the same replacement rules as the original code.
 * </p>
 *
 * <p>Refactoring goals:</p>
 * <ul>
 *   <li>Clear naming and meaningful constants</li>
 *   <li>Extraction of responsibilities into small, testable methods</li>
 *   <li>Removal of duplicated logic</li>
 *   <li>Elimination of magic numbers and raw types</li>
 *   <li>Better separation of concerns (I/O vs. processing)</li>
 * </ul>
 */
public class Main {

    /** Enumerates the three supported character kinds. */
    private enum Kind {
        LOWER,
        UPPER,
        DIGIT;

        /** Character used to represent a kind when it must be inserted. */
        char placeholder() {
            return switch (this) {
                case LOWER -> 'a';
                case UPPER -> 'A';
                case DIGIT -> '0';
            };
        }

        /** Returns the kind of a character, or {@code null} if it does not belong to any kind. */
        static Kind fromChar(char c) {
            if (c >= 'a' && c <= 'z') return Kind.LOWER;
            if (c >= 'A' && c <= 'Z') return Kind.UPPER;
            if (c >= '0' && c <= '9') return Kind.DIGIT;
            return null;
        }
    }

    /** Entry point. */
    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            int remainingCases = scanner.nextInt();
            while (remainingCases-- > 0) {
                String input = scanner.next();
                System.out.println(transform(input));
            }
        }
    }

    /**
     * Transforms the given {@code input} so that it contains at least one lower‑case
     * letter, one upper‑case letter and one digit. The transformation follows the same
     * deterministic rules as the original implementation.
     *
     * @param input the original string
     * @return the possibly modified string
     */
    private static String transform(String input) {
        char[] chars = input.toCharArray();
        int length = chars.length;

        // Count how many characters of each kind we already have.
        int[] kindCounts = new int[Kind.values().length]; // 0 LOWER, 1 UPPER, 2 DIGIT
        boolean[] kindSeen = new boolean[Kind.values().length];

        for (int i = 0; i < length; i++) {
            Kind kind = Kind.fromChar(chars[i]);
            if (kind != null) {
                kindCounts[kind.ordinal()]++;
                kindSeen[kind.ordinal()] = true;
            }
        }

        // Tracks which kinds are still missing.
        List<Integer> missingKinds = new ArrayList<>();
        for (int k = 0; k < Kind.values().length; k++) {
            if (!kindSeen[k]) {
                missingKinds.add(k);
            }
        }

        StringBuilder result = new StringBuilder(input);
        int i = 0;

        while (i < length && !missingKinds.isEmpty()) {
            char current = chars[i];
            Kind currentKind = Kind.fromChar(current);
            if (currentKind == null) {
                i++;
                continue;
            }

            // We can only replace a character if we have more than one of its kind.
            if (kindCounts[currentKind.ordinal()] > 1) {
                for (int idx = 0; idx < missingKinds.size(); idx++) {
                    int targetKindOrdinal = missingKinds.get(idx);
                    Kind targetKind = Kind.values()[targetKindOrdinal];

                    // The original code required a duplicate of the source kind and the
                    // target kind not yet being present – both conditions are satisfied
                    // here because we checked duplicate count and missingKinds contains
                    // exactly the still‑missing kinds.
                    if (canReplace(currentKind, targetKind)) {
                        char replacement = targetKind.placeholder();
                        result.setCharAt(i, replacement);

                        // Update bookkeeping: we consumed one character of the source kind
                        // and we now have the target kind covered.
                        kindCounts[currentKind.ordinal()]--;
                        missingKinds.remove(idx);
                        break; // replacement performed – go to next position
                    }
                }
            }
            i++;
        }

        return result.toString();
    }

    /**
     * Determines whether a character of {@code sourceKind} can be replaced by a
     * character of {@code targetKind} according to the replacement rules used in the
     * original program.
     *
     * <p>The mapping is:</p>
     * <ul>
     *   <li>UPPER → DIGIT (replace with '0')</li>
     *   <li>UPPER → LOWER (replace with 'a')</li>
     *   <li>DIGIT → LOWER (replace with 'a')</li>
     *   <li>DIGIT → UPPER (replace with 'A')</li>
     *   <li>LOWER → UPPER (replace with 'A')</li>
     *   <li>LOWER → DIGIT (replace with '0')</li>
     * </ul>
     *
     * @param sourceKind the kind of the character that may be changed
     * @param targetKind the kind we want to introduce
     * @return {@code true} if the replacement conforms to the original rules
     */
    private static boolean canReplace(Kind sourceKind, Kind targetKind) {
        return switch (sourceKind) {
            case UPPER -> targetKind == Kind.DIGIT || targetKind == Kind.LOWER;
            case DIGIT -> targetKind == Kind.LOWER || targetKind == Kind.UPPER;
            case LOWER -> targetKind == Kind.UPPER || targetKind == Kind.DIGIT;
        };
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.function.Predicate;

/**
 * Reads multiple test strings from standard input.
 * For each string it:
 *   • prints the string unchanged if it already contains at least one
 *     lowercase letter, one uppercase letter and one digit;
 *   • otherwise transforms the string so that the missing character types
 *     are introduced at the earliest possible positions.
 *
 * The implementation is deliberately split into small, well‑named methods,
 * uses meaningful constants and avoids magic numbers.
 */
public class VAP {

    /* --------------------------------------------------------------------- */
    /*  ASCII range constants – make the intent explicit                      */
    /* --------------------------------------------------------------------- */
    private static final int ASCII_LOWERCASE_START = 'a';
    private static final int ASCII_LOWERCASE_END   = 'z';
    private static final int ASCII_UPPERCASE_START = 'A';
    private static final int ASCII_UPPERCASE_END   = 'Z';
    private static final int ASCII_DIGIT_START     = '0';
    private static final int ASCII_DIGIT_END       = '9';

    public static void main(String[] args) throws IOException {
        /* --------------------------------------------------------------- */
        /*  Input handling – try‑with‑resources guarantees proper closing   */
        /* --------------------------------------------------------------- */
        try (BufferedReader reader = new BufferedReader(
                new InputStreamReader(System.in))) {

            int testCases = Integer.parseInt(reader.readLine().trim());
            StringBuilder output = new StringBuilder();

            for (int t = 0; t < testCases; t++) {
                String input = reader.readLine();
                int lowerCount = countCategory(input, Character::isLowerCase);
                int upperCount = countCategory(input, Character::isUpperCase);
                int digitCount = countCategory(input, Character::isDigit);

                if (hasAllThreeCategories(lowerCount, upperCount, digitCount)) {
                    output.append(input).append('\n');
                } else {
                    output.append(
                            transform(input, lowerCount, upperCount, digitCount)
                    ).append('\n');
                }
            }

            System.out.print(output.toString());
        }
    }

    /** Counts how many characters of the supplied predicate are present. */
    private static int countCategory(String text, Predicate<Character> predicate) {
        int count = 0;
        for (int i = 0; i < text.length(); i++) {
            if (predicate.test(text.charAt(i))) {
                count++;
            }
        }
        return count;
    }

    /** Returns true when the string already contains lower, upper and digit. */
    private static boolean hasAllThreeCategories(int lower, int upper, int digit) {
        return lower > 0 && upper > 0 && digit > 0;
    }

    /**
     * Produces a transformed version of {@code original} where at least one
     * character of each missing category is introduced.
     *
     * The algorithm mirrors the original behaviour but is written with
     * clearer variable names and fewer nested conditionals.
     */
    private static String transform(String original,
                                    int lowerCount,
                                    int upperCount,
                                    int digitCount) {
        char[] chars = original.toCharArray();

        /* --------------------------------------------------------------- */
        /*  Special‑case handling – the original code always overwrote the */
        /*  first two positions when exactly two categories were missing.   */
        /* --------------------------------------------------------------- */
        if (upperCount == 0 && digitCount == 0) {
            chars[0] = 'D';
            if (chars.length > 1) {
                chars[1] = '1';
            }
            return new String(chars);
        }
        if (upperCount == 0 && lowerCount == 0) {
            chars[0] = 'D';
            if (chars.length > 1) {
                chars[1] = 'a';
            }
            return new String(chars);
        }
        if (lowerCount == 0 && digitCount == 0) {
            chars[0] = 'a';
            if (chars.length > 1) {
                chars[1] = '1';
            }
            return new String(chars);
        }

        /* --------------------------------------------------------------- */
        /*  General case – replace the first suitable character so that the */
        /*  missing categories become represented.                           */
        /* --------------------------------------------------------------- */
        for (int i = 0; i < chars.length; i++) {
            char ch = chars[i];

            // Upper‑case character can be turned into lower‑case or digit
            if (Character.isUpperCase(ch) && upperCount > 1) {
                if (lowerCount == 0) {
                    chars[i] = 'a';
                    break;
                } else if (digitCount == 0) {
                    chars[i] = '1';
                    break;
                }
            }

            // Lower‑case character can be turned into upper‑case or digit
            if (Character.isLowerCase(ch) && lowerCount > 1) {
                if (upperCount == 0) {
                    chars[i] = 'A';
                    break;
                } else if (digitCount == 0) {
                    chars[i] = '1';
                    break;
                }
            }

            // Digit character can be turned into upper‑case or lower‑case
            if (Character.isDigit(ch) && digitCount > 1) {
                if (upperCount == 0) {
                    chars[i] = 'A';
                    break;
                } else if (lowerCount == 0) {
                    chars[i] = 'a';
                    break;
                }
            }
        }

        return new String(chars);
    }
}

import java.io.*;
import java.util.*;
import java.util.function.BiConsumer;
import java.util.function.Consumer;
import java.util.function.Function;

/**
 * Refactored solution that reads multiple test cases.
 * For each string it guarantees the presence of at least one
 * digit, one lowercase and one uppercase letter.
 * The algorithm is written for readability, maintainability
 * and proper encapsulation.
 */
public class Main {

    private static final char DIGIT_CHAR = '0';
    private static final char LOWER_CHAR = 'a';
    private static final char UPPER_CHAR = 'A';

    private final FastScanner fs;

    /** Entry point */
    public static void main(String[] args) throws Exception {
        try (FastScanner fs = new FastScanner(System.in)) {
            new Main(fs).run();
        }
    }

    /** Constructor */
    public Main(FastScanner fs) {
        this.fs = fs;
    }

    /** Main driver – reads test count and processes each case */
    private void run() {
        int t = fs.nextInt();
        StringBuilder out = new StringBuilder();
        for (int i = 0; i < t; i++) {
            out.append(correctString(fs.nextString())).append('\n');
        }
        System.out.print(out.toString());
    }

    /**
     * Core transformation:
     * 1. Categorise every character index into DIGIT, LOWER or UPPER.
     * 2. If a category is missing, replace the first usable index
     *    from the remaining categories with the missing character.
     * 3. Return the modified string.
     */
    private String correctString(String s) {
        // -----------------------------------------------------------------
        // 1️⃣  Categorise positions
        // -----------------------------------------------------------------
        List<Integer> digit   = new ArrayList<>();
        List<Integer> lower   = new ArrayList<>();
        List<Integer> upper   = new ArrayList<>();

        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (Character.isDigit(c)) {
                digit.add(i);
            } else if (Character.isLowerCase(c)) {
                lower.add(i);
            } else if (Character.isUpperCase(c)) {
                upper.add(i);
            }
        }

        // -----------------------------------------------------------------
        // 2️⃣  Mutate the string only when a category is absent
        // -----------------------------------------------------------------
        StringBuilder sb = new StringBuilder(s);
        Set<Integer> usedPositions = new HashSet<>();

        // Helper that registers a replaced index to avoid reuse
        Consumer<Integer> markUsed = pos -> usedPositions.add(pos);

        // Replaces the character at `pos` with `value` and records the change
        BiConsumer<Integer, Character> replacer = (pos, value) -> {
            sb.setCharAt(pos, value);
            markUsed.accept(pos);
        };

        // Retrieve the first unused index from a collection of lists
        Function<List<Integer>, Integer> firstUnused = collections -> {
            for (List<Integer> list : collections) {
                for (int idx : list) {
                    if (!usedPositions.contains(idx)) {
                        return idx;
                    }
                }
            }
            // Should never happen for valid input – fallback to -1
            return -1;
        };

        // ----- Ensure at least one digit -------------------------------------------------
        if (digit.isEmpty()) {
            int pos = firstUnused(Arrays.asList(lower, upper));
            replacer.accept(pos, DIGIT_CHAR);
        }

        // ----- Ensure at least one lowercase letter ---------------------------------------
        if (lower.isEmpty()) {
            int pos = firstUnused(Arrays.asList(digit, upper));
            replacer.accept(pos, LOWER_CHAR);
        }

        // ----- Ensure at least one uppercase letter ---------------------------------------
        if (upper.isEmpty()) {
            int pos = firstUnused(Arrays.asList(digit, lower));
            replacer.accept(pos, UPPER_CHAR);
        }

        // -----------------------------------------------------------------
        // 3️⃣  Return the transformed string
        // -----------------------------------------------------------------
        return sb.toString();
    }

    /**
     * Very small fast scanner based on {@link BufferedInputStream}.
     * It supports the methods used by the solution: {@code nextInt},
     * {@code nextString}, etc.
     */
    private static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream in) {
            this.in = in;
        }

        private int readByte() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        private int skip() throws IOException {
            int b;
            while ((b = readByte()) != -1 && isSpace(b)) {}
            return b;
        }

        private static boolean isSpace(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t'
                    || c == '\f' || c == '\b';
        }

        /** Reads the next token (non‑whitespace characters). */
        String nextString() throws IOException {
            int ch = skip();
            StringBuilder sb = new StringBuilder();
            while (ch != -1 && !isSpace(ch)) {
                sb.append((char) ch);
                ch = readByte();
            }
            return sb.toString();
        }

        /** Reads the next integer (supports negative numbers). */
        int nextInt() throws IOException {
            int c = skip();
            boolean negative = false;
            if (c == '-') {
                negative = true;
                c = readByte();
            }
            int value = 0;
            while (c >= '0' && c <= '9') {
                value = value * 10 + (c - '0');
                c = readByte();
            }
            return negative ? -value : value;
        }
    }
}

import java.io.PrintWriter;
import java.util.Scanner;

/**
 * Main driver class. It reads test cases, delegates processing to
 * {@link Processing}, and writes the results.
 */
public class CodingLegacy {

    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in);
             PrintWriter out = new PrintWriter(System.out)) {

            int testCount = scanner.nextInt();
            for (int i = 1; i <= testCount; i++) {
                Processing.process(i, scanner, out);
            }
        }
    }
