/**
 * Encapsulates all logic required to transform an input string into a
 * “complete” string (contains at least one lowercase, one uppercase,
 * and one digit) while preserving as much of the original content as
 * possible.
 */
final class Processing {

    private Processing() { /* utility class – no instances */ }

    /**
     * Handles a single test case.
     *
     * @param caseNumber 1‑based test case index
     * @param scanner    source of input data
     * @param out        destination for output
     */
    static void process(int caseNumber, Scanner scanner, PrintWriter out) {
        String original = scanner.next();
        char[] buf = original.toCharArray();

        // Already complete – nothing to modify.
        if (CharacterValidator.isComplete(buf)) {
            out.println(original);
            return;
        }

        // 1️⃣ Try to fix by changing a single character.
        String candidate = trySingleChange(buf);
        if (candidate != null) {
            out.println(candidate);
            return;
        }

        // 2️⃣ Try to fix by adjusting two adjacent characters.
        candidate = tryAdjacentChange(buf);
        if (candidate != null) {
            out.println(candidate);
            return;
        }

        // 3️⃣ Fallback to a deterministic default.
        out.println(defaultFallback());
    }

    /** Attempts a single‑position replacement that yields a complete string. */
    private static String trySingleChange(char[] buf) {
        final char[] REPLACEMENTS = {'a', 'A', '0'};

        for (int i = 0; i < buf.length; i++) {
            char saved = buf[i];
            for (char repl : REPLACEMENTS) {
                buf[i] = repl;
                if (CharacterValidator.isComplete(buf)) {
                    return new String(buf);
                }
            }
            buf[i] = saved; // restore
        }
        return null;
    }

    /** Attempts a simultaneous adjacent‑position change that yields a complete string. */
    private static String tryAdjacentChange(char[] buf) {
        final char[] REPLACEMENTS = {'a', 'A', '0'};

        for (int i = 0; i < buf.length - 1; i++) {
            char firstSaved = buf[i];
            char secondSaved = buf[i + 1];

            for (int j = 0; j < REPLACEMENTS.length; j++) {
                buf[i] = REPLACEMENTS[j];
                buf[i + 1] = REPLACEMENTS[(j + 1) % REPLACEMENTS.length];
                if (CharacterValidator.isComplete(buf)) {
                    return new String(buf);
                }
            }
            // restore original characters
            buf[i] = firstSaved;
            buf[i + 1] = secondSaved;
        }
        return null;
    }

    /** Returns a deterministic fallback string when no modification succeeds. */
    private static String defaultFallback() {
        return "aA0";
    }
}

/**
 * Utility class that validates whether a character array satisfies the
 * “complete” requirement: it must contain at least one lowercase
 * letter, one uppercase letter, and one digit.
 */
final class CharacterValidator {

    private CharacterValidator() { /* no instantiation */ }

    /**
     * Checks the completeness criteria.
     *
     * @param chars array to evaluate
     * @return {@code true} if {@code chars} contains at least one
     *         lowercase letter, one uppercase letter, and one digit;
     *         otherwise {@code false}
     */
    static boolean isComplete(char[] chars) {
        boolean hasLower = false;
        boolean hasUpper = false;
        boolean hasDigit = false;

        for (char c : chars) {
            if (Character.isLowerCase(c)) {
                hasLower = true;
            } else if (Character.isUpperCase(c)) {
                hasUpper = true;
            } else if (Character.isDigit(c)) {
                hasDigit = true;
            }
        }
        return hasLower && hasUpper && hasDigit;
    }
}

import java.io.BufferedReader;
