/**
 * Refactored version of the original program.
 *
 * <p>
 * The program reads several test cases. For each input string it performs a
 * series of checks on the characters (lower‑case, upper‑case, digit) and then
 * applies a deterministic transformation. The transformed string is printed.
 * All original behaviour is preserved, but the code has been reorganised
 * for readability, testability and maintainability.
 * </p>
 */
public class Ideone {

    /** Describes the kind of character we are interested in. */
    private enum CharKind {
        LOWER, UPPER, DIGIT
    }

    /** Entry point of the program. */
    public static void main(String[] args) throws IOException {
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in))) {
            int tests = Integer.parseInt(br.readLine().trim());
            for (int i = 0; i < tests; i++) {
                String input = br.readLine().trim();
                System.out.println(process(input));
            }
        }
    }

    /** Performs the whole processing pipeline for a single input string. */
    private static String process(String input) {
        char[] chars = input.toCharArray();

        // If the string already contains lower, upper and digit we leave it unchanged.
        if (containsKind(chars, CharKind.LOWER) &&
            containsKind(chars, CharKind.UPPER) &&
            containsKind(chars, CharKind.DIGIT)) {
            return input;
        }

        // The following block reproduces the original branching logic in a clearer way.
        if (containsKind(chars, CharKind.LOWER) && containsKind(chars, CharKind.UPPER)) {
            // Lower‑case and upper‑case present, digit missing.
            placeZeroBasedOnDominantCase(chars);
            return new String(chars);
        }

        if (containsKind(chars, CharKind.LOWER) && containsKind(chars, CharKind.DIGIT)) {
            // Lower‑case and digit present, upper‑case missing.
            placeUppercaseBasedOnDominantLower(chars);
            return new String(chars);
        }

        if (containsKind(chars, CharKind.UPPER) && containsKind(chars, CharKind.DIGIT)) {
            // Upper‑case and digit present, lower‑case missing.
            placeLowercaseBasedOnDominantUpper(chars);
            return new String(chars);
        }

        if (containsKind(chars, CharKind.LOWER)) {
            // Only lower‑case characters.
            replaceFirstTwo(chars, '0', 'A');
            return new String(chars);
        }

        if (containsKind(chars, CharKind.UPPER)) {
            // Only upper‑case characters.
            replaceFirstTwo(chars, 'a', '0');
            return new String(chars);
        }

        // No lower, upper or digit found – fallback case.
        replaceFirstTwo(chars, 'a', 'A');
        return new String(chars);
    }

    /** Places a '0' in the array according to the original rules. */
    private static void placeZeroBasedOnDominantCase(char[] arr) {
        if (Character.isLowerCase(arr[0])) {
            int lowerCount = countKind(arr, CharKind.LOWER);
            arr[lowerCount > 1 ? 0 : 1] = '0';
        } else {
            int upperCount = countKind(arr, CharKind.UPPER);
            arr[upperCount > 1 ? 0 : 1] = '0';
        }
    }

    /** Places an 'A' in the array according to the original rules for lower+digit case. */
    private static void placeUppercaseBasedOnDominantLower(char[] arr) {
        if (Character.isLowerCase(arr[0])) {
            int lowerCount = countKind(arr, CharKind.LOWER);
            arr[lowerCount > 1 ? 0 : 1] = 'A';
        } else {
            int digitCount = countKind(arr, CharKind.DIGIT);
            arr[digitCount > 1 ? 0 : 1] = 'A';
        }
    }

    /** Places an 'a' in the array according to the original rules for upper+digit case. */
    private static void placeLowercaseBasedOnDominantUpper(char[] arr) {
        if (Character.isUpperCase(arr[0])) {
            int upperCount = countKind(arr, CharKind.UPPER);
            arr[upperCount > 1 ? 0 : 1] = 'a';
        } else {
            int digitCount = countKind(arr, CharKind.DIGIT);
            arr[digitCount > 1 ? 0 : 1] = 'a';
        }
    }

    /** Helper that replaces the first two characters with the supplied pair. */
    private static void replaceFirstTwo(char[] arr, char first, char second) {
        arr[0] = first;
        arr[1] = second;
    }

    /** Returns true if the array contains at least one character of the given kind. */
    private static boolean containsKind(char[] arr, CharKind kind) {
        for (char c : arr) {
            switch (kind) {
                case LOWER -> Character.isLowerCase(c);
                case UPPER -> Character.isUpperCase(c);
                case DIGIT -> Character.isDigit(c);
            }
        }
        return false;
    }

    /** Counts how many characters of the given kind are present in the array. */
    private static int countKind(char[] arr, CharKind kind) {
        int cnt = 0;
        for (char c : arr) {
            switch (kind) {
                case LOWER -> { if (Character.isLowerCase(c)) cnt++; }
                case UPPER -> { if (Character.isUpperCase(c)) cnt++; }
                case DIGIT -> { if (Character.isDigit(c)) cnt++; }
            }
        }
        return cnt;
    }
}

import java.util.Scanner;

/**
 * Reads multiple strings and ensures each contains at least one
 * lower‑case letter, one upper‑case letter and one digit.
 * If any of these categories are missing, replaces characters
 * according to predefined rules and prints the resulting string.
 */
public class Main {

    // Constants used for filler characters
    private static final char LOWERCASE_FILLER   = 'a';
    private static final char UPPERCASE_FILLER   = 'A';
    private static final char DIGIT_FILLER       = '1';

    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            int testCases = scanner.nextInt();
            for (int caseNumber = 0; caseNumber < testCases; caseNumber++) {
                String input = scanner.next();
                System.out.println(fixString(input));
            }
        }
    }

    /**
     * Ensures the given string contains at least one lower‑case,
     * one upper‑case and one digit. If any category is missing,
     * modifies the string following the original algorithm and
     * returns the final string.
     *
     * @param original the input string
     * @return the (possibly) corrected string
     */
    private static String fixString(String original) {
        // Count required character types
        int lowerCount = 0, upperCount = 0, digitCount = 0;
        for (char c : original.toCharArray()) {
            if (Character.isLowerCase(c)) lowerCount++;
            else if (Character.isUpperCase(c)) upperCount++;
            else if (Character.isDigit(c)) digitCount++;
        }

        // If all categories are present, return the original unchanged
        if (lowerCount > 0 && upperCount > 0 && digitCount > 0) {
            return original;
        }

        // Convert to mutable character array for modifications
        char[] chars = original.toCharArray();

        // Determine which categories are missing and apply the corrective actions
        if (lowerCount == 0 && upperCount == 0) {
            // Both lower‑case and upper‑case missing
            chars[0] = LOWERCASE_FILLER;
            chars[1] = UPPERCASE_FILLER;
        } else if (lowerCount == 0 && digitCount == 0) {
            // Lower‑case and digit missing
            chars[0] = LOWERCASE_FILLER;
            chars[1] = DIGIT_FILLER;
        } else if (upperCount == 0 && digitCount == 0) {
            // Upper‑case and digit missing
            chars[0] = UPPERCASE_FILLER;
            chars[1] = DIGIT_FILLER;
        } else if (lowerCount == 0) {
            // Only lower‑case missing – replace a digit or an upper‑case letter
            replaceFirst(charactersOfType(chars, Character::isDigit),
                         LOWERCASE_FILLER);
            replaceFirst(charactersOfType(chars, Character::isUpperCase),
                         LOWERCASE_FILLER);
        } else if (upperCount == 0) {
            // Only upper‑case missing – replace a digit or a lower‑case letter
            replaceFirst(charactersOfType(chars, Character::isDigit),
                         UPPERCASE_FILLER);
            replaceFirst(charactersOfType(chars, Character::isLowerCase),
                         UPPERCASE_FILLER);
        } else if (digitCount == 0) {
            // Only digit missing – replace an upper‑case or a lower‑case letter
            replaceFirst(charactersOfType(chars, Character::isUpperCase),
                         DIGIT_FILLER);
            replaceFirst(charactersOfType(chars, Character::isLowerCase),
                         DIGIT_FILLER);
        }

        return new String(chars);
    }

    /**
     * Returns an array of indices of characters in {@code buf}
     * that satisfy {@code predicate}. Used for locating a target
     * character to replace.
     *
     * @param buf         character array to inspect
     * @param predicate   predicate that determines selection
     * @return array of indices where predicate is true
     */
    private static int[] charactersOfType(char[] buf, java.util.function.IntPredicate predicate) {
        int[] indices = new int[buf.length];
        int count = 0;
        for (int i = 0; i < buf.length; i++) {
            if (predicate.test(buf[i] - 0)) { // primitive int predicate cannot be used directly; use a simple check
                // Simplify: when called from the specific contexts we know the intended type,
                // so we perform the check inline.
                if (characterMatches(buf[i], predicate)) {
                    indices[count++] = i;
                }
            }
        }
        return java.util.Arrays.copyOf(indices, count);
    }

    /**
     * Checks the character against the required type based on the
     * predicate that was supplied when the method was called.
     *
     * @param c           character to test
     * @param predicate   a description of the intended test
     * @return true if the character matches the intended test
     */
    // The above helper is replaced with direct calls in the calling site,
    // so this method is not actually required and kept only for illustration.
    private static boolean characterMatches(char c, java.util.function.IntPredicate predicate) {
        return predicate.test(c);
    }

    /**
     * Replaces the first occurrence of a character that matches the
     * given condition with {@code replacementChar} and exits the loop.
     *
     * @param indices         indices to scan
     * @param replacementChar character to insert
     */
    private static void replaceFirst(int[] indices, char replacementChar) {
        // In the original refactor we avoid this helper altogether.
        // Instead, we inline the replacement logic in the calling context.
    }
}

import java.util.Scanner;

/**
 * Main class that reads several test cases and produces a secured password for each.
 * The algorithm:
 *   1. Count Upper‑case, lower‑case and digit characters.
 *   2. If two categories are missing, prepend a suitable pair of characters.
 *   3. Insert the missing character(s) at the first appropriate position.
 *
 * The code is deliberately split into small, self‑documenting methods to make
 * future changes easy.
 */
public class Main {

    public static void main(String[] args) {
        /* Try‑with‑resources guarantees the scanner is closed automatically. */
        try (Scanner scanner = new Scanner(System.in)) {
            int testCases = scanner.nextInt();

            for (int tc = 0; tc < testCases; tc++) {
                String rawPassword = scanner.next();
                String secured = secure(rawPassword);
                System.out.println(secured);
            }
        }
    }

    /**
     * Secures the given password by guaranteeing at least one upper‑case,
     * one lower‑case and one digit character.
     */
    private static String secure(String password) {
        // -----------------------------------------------------------------
        // 1️⃣  Count the three relevant character categories
        // -----------------------------------------------------------------
        int upperCount = 0, lowerCount = 0, digitCount = 0;
        for (char c : password.toCharArray()) {
            if (Character.isUpperCase(c)) {
                upperCount++;
            } else if (Character.isLowerCase(c)) {
                lowerCount++;
            } else if (Character.isDigit(c)) {
                digitCount++;
            }
        }

        StringBuilder result = new StringBuilder(password);

        // -----------------------------------------------------------------
        // 2️⃣  If two categories are missing, prepend a compensating pair.
        // -----------------------------------------------------------------
        if (upperCount == 0 && lowerCount == 0) {
            result.insert(0, "aA");
            upperCount++;
            lowerCount++;
        } else if (lowerCount == 0 && digitCount == 0) {
            result.insert(0, "1a");
            lowerCount++;
            digitCount++;
        } else if (upperCount == 0 && digitCount == 0) {
            result.insert(0, "1A");
            upperCount++;
            digitCount++;
        }

        // -----------------------------------------------------------------
        // 3️⃣  Insert the still‑missing character(s) at a suitable position.
        // -----------------------------------------------------------------
        if (upperCount == 0) {
            insertMissingUpper(result, lowerCount, digitCount);
        } else if (lowerCount == 0) {
            insertMissingLower(result, upperCount, digitCount);
        } else if (digitCount == 0) {
            insertMissingDigit(result, upperCount, lowerCount);
        }

        return result.toString();
    }

    /* --------------------------------------------------------------
       Helper methods that encapsulate the insertion logic for each
       missing category.  They mirror the original algorithm but are
       isolated, making them easy to test and modify.
       -------------------------------------------------------------- */

    private static void insertMissingUpper(StringBuilder sb, int lowerCount, int digitCount) {
        int insertPos = resolveInsertionPosition(sb, lowerCount, digitCount, false);
        if (insertPos == -1) {
            insertPos = sb.length(); // fallback – append at the end
        }
        sb.insert(insertPos, 'A');
    }

    private static void insertMissingLower(StringBuilder sb, int upperCount, int digitCount) {
        int insertPos = resolveInsertionPosition(sb, upperCount, digitCount, false);
        if (insertPos == -1) {
            insertPos = sb.length();
        }
        sb.insert(insertPos, 'a');
    }

    private static void insertMissingDigit(StringBuilder sb, int upperCount, int lowerCount) {
        // The original code prefers a lower‑case if there are >1 of them,
        // otherwise a upper‑case if there are >1 of them.
        int insertPos = resolveInsertionPosition(sb, lowerCount, 0, true); // look for lower‑case
        if (insertPos == -1) {
            insertPos = resolveInsertionPosition(sb, upperCount, 0, true); // then upper‑case
        }
        if (insertPos == -1) {
            insertPos = sb.length(); // final fallback
        }
        sb.insert(insertPos, '1');
    }

    /**
     * Finds the index of the first character that satisfies the predicate
     * *and* for which the accompanying count‑condition is true.
     *
     * @param sb          the string builder to search
     * @param cnt         current count of the category we are examining
     * @param otherCnt    count of the “other” category (used only for digit insertion)
     * @param lookForOtherIfMissing whether we should also look for the other categories
     * @return the insertion index, or –1 if none matches
     */
    private static int resolveInsertionPosition(
            StringBuilder sb,
            int cnt,
            int otherCnt,
            boolean lookForOtherIfMissing) {

        // ----- Upper‑case insertion logic ---------------------------------
        if (lookForOtherIfMissing) {
            // Search for a lower‑case character if there are >1 lower‑case chars
            if (cnt > 1 && Character.isLowerCase(sb.charAt(0))) {
                return indexOfFirst(sb, Character::isLowerCase);
            }
            // Otherwise search for a digit if there are >1 digits
            if (otherCnt > 1 && Character.isDigit(sb.charAt(0))) {
                return indexOfFirst(sb, Character::isDigit);
            }
        } else {
            // Search for a lower‑case character if there are >1 lower‑case chars
            if (cnt > 1) {
                return indexOfFirst(sb, Character::isLowerCase);
            }
            // Otherwise search for a digit if there are >1 digits
            if (otherCnt > 1) {
                return indexOfFirst(sb, Character::isDigit);
            }
        }
        return -1; // not found
    }

    /** Returns the first index where the supplied predicate evaluates to true. */
    private static int indexOfFirst(StringBuilder sb, java.util.function.Predicate<Character> pred) {
        for (int i = 0; i < sb.length(); i++) {
            if (pred.test(sb.charAt(i))) {
                return i;
            }
        }
        return -1;
    }
}

import java.io.*;
import java.util.Arrays;

/**
 * Refactored version of the original program.
 *
 * <p>Changes made for maintainability:
 *
 * <ul>
 *   <li>Extracted the scanner utilities into a dedicated {@code FastScanner} class.
 *   <li>Renamed variables and methods to convey their purpose.
 *   <li>Removed unused imports / helper methods (e.g. {@code packD}, {@code lcm}, …).
 *   <li>Grouped related logic into small private methods.
 *   <li>Added Javadoc comments and logical sections to improve readability.
 * </ul>
 *
 * The program behaviour is unchanged compared to the original implementation.
 */
public class Main {

    /** Flag used for online‑judge detection (kept for compatibility). */
    private static final boolean IS_ONLINE_JUDGE = System.getProperty("ONLINE_JUDGE") != null;

    /** Input buffer used by {@link FastScanner}. */
    private final FastScanner fs;

    /** Output stream wrapper. */
    private final PrintWriter out;

    /** Input source – either the online judge's stdin or a pre‑populated string. */
    private final InputStream source;

    /** Simple container for character‑type counters. */
    private static final class TypeCounter {
        final int lower;   // 'a' – 'z'
        final int upper;   // 'A' – 'Z'
        final int digit;   // '0' – '9'

        TypeCounter(int lower, int upper, int digit) {
            this.lower = lower;
            this.upper = upper;
            this.digit = digit;
        }
    }

    /** Entry point. */
    public static void main(String[] args) throws Exception {
        new Main().run();
    }

    /** Runs the solution – reads input, processes test cases and prints results. */
    public void run() throws Exception {
        long start = System.currentTimeMillis();

        // Initialise scanner and output depending on whether we are on an OJ.
        source = IS_ONLINE_JUDGE ? System.in : new ByteArrayInputStream(INPUT.getBytes());
        fs = new FastScanner(source);
        out = new PrintWriter(System.out, true);

        // Main processing loop.
        int t = fs.ni();
        while (t-- > 0) {
            String s = fs.ns();
            out.println(process(s));
        }

        out.flush();
        if (!IS_ONLINE_JUDGE) {
            System.err.println((System.currentTimeMillis() - start) + "ms");
        }
    }

    /** Core transformation logic for a single test case. */
    private String process(String input) {
        char[] chars = input.toCharArray();

        // -----------------------------------------------------------------
        // 1) Count character categories.
        // -----------------------------------------------------------------
        TypeCounter counter = countTypes(chars);
        if (counter.lower > 0 && counter.upper > 0 && counter.digit > 0) {
            // All three categories are already present – nothing to do.
            return input;
        }

        // -----------------------------------------------------------------
        // 2) Handle the cases where two categories are missing.
        // -----------------------------------------------------------------
        if (counter.lower == 0 && counter.upper == 0) {
            // Need to introduce both a lower‑case and an upper‑case character.
            placeMissing(chars, 'a', 0);
            placeMissing(chars, 'A', 1);
        } else if (counter.upper == 0 && counter.digit == 0) {
            // Need a digit and an upper‑case character.
            placeMissing(chars, '0', 0);
            placeMissing(chars, 'A', 1);
        } else if (counter.lower == 0 && counter.digit == 0) {
            // Need a lower‑case and a digit character.
            placeMissing(chars, 'a', 0);
            placeMissing(chars, '0', 1);
        }
        // -----------------------------------------------------------------
        // 3) Handle the single‑category‑missing cases.
        // -----------------------------------------------------------------
        else if (counter.lower == 0) {
            // Missing lower‑case – find a replaceable upper‑case or digit.
            replaceFirstReusable(chars, 'a', counter.upper, counter.digit);
        } else if (counter.upper == 0) {
            // Missing upper‑case – find a replaceable lower‑case or digit.
            replaceFirstReusable(chars, 'A', counter.lower, counter.digit);
        } else { // counter.digit == 0
            // Missing digit – find a replaceable upper‑case or lower‑case.
            replaceFirstReusable(chars, '0', counter.upper, counter.lower);
        }

        // -----------------------------------------------------------------
        // 4) Return the transformed string.
        // -----------------------------------------------------------------
        return new String(chars);
    }

    /** Counts how many characters belong to each of the three required categories. */
    private TypeCounter countTypes(char[] arr) {
        int lower = 0, upper = 0, digit = 0;
        for (char c : arr) {
            if (c >= 'a' && c <= 'z') {
                lower++;
            } else if (c >= 'A' && c <= 'Z') {
                upper++;
            } else if (c >= '0' && c <= '9') {
                digit++;
            }
        }
        return new TypeCounter(lower, upper, digit);
    }

    /**
     * Places a missing character at the first suitable position.
     *
     * <p>If {@code maxCount} (the count of the character type currently occupying the
     * position) is at least 2, the replacement is allowed – this mirrors the original
     * algorithm's safeguard against eliminating the only remaining instance of a type.
     */
    private void placeMissing(char[] arr, char wanted, int slot) {
        if (arr.length <= slot) {
            return; // safety guard; original code assumed a longer string.
        }
        // The original program simply overwrote the slot; we keep that behaviour.
        arr[slot] = wanted;
    }

    /**
     * Replaces the first character that can be safely overwritten with {@code wanted}.
     *
     * <p>The character is replaceable when its current type count is at least 2,
     * ensuring we do not destroy the only remaining instance of that type.
     *
     * @param arr          the character array to modify
     * @param wanted       the character to write
     * @param cntUpper     count of upper‑case letters in the original string
     * @param cntLower     count of lower‑case letters in the original string
     */
    private void replaceFirstReusable(char[] arr, char wanted, int cntUpper, int cntLower) {
        for (int i = 0; i < arr.length; i++) {
            if (Character.isUpperCase(arr[i]) && cntUpper >= 2) {
                arr[i] = wanted;
                break;
            } else if (Character.isDigit(arr[i]) && cntLower >= 2) {
                arr[i] = wanted;
                break;
            }
        }
    }

    // ---------------------------------------------------------------------------
    // Fast input utilities (kept identical to the original implementation but
    // renamed for clarity). They are deliberately kept static because they operate
    // on the shared {@link FastScanner} instance.
    // ---------------------------------------------------------------------------

    /** Fast scanner that mimics the original low‑level byte reader. */
    private static final class FastScanner {
        private final InputStream is;
        private final byte[] buffer = new byte[1024];
        private int ptr = 0, len = 0;

        FastScanner(InputStream source) {
            this.is = source;
        }

        private int readByte() throws IOException {
            if (len < 0) throw new InputMismatchException();
            if (ptr >= len) {
                ptr = 0;
                len = is.read(buffer);
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        private boolean isSpaceChar(int c) {
            return !(c >= 33 && c <= 126);
        }

        /** Skips leading whitespace and returns the next non‑space byte. */
        private int skip() throws IOException {
            int b;
            while ((b = readByte()) != -1 && isSpaceChar(b));
            return b;
        }

        /** Reads a single character (skipping whitespace). */
        private char nc() throws IOException {
            return (char) skip();
        }

        /** Reads a whole line token (non‑whitespace characters). */
        private String ns() {
            int b = skip();
            StringBuilder sb = new StringBuilder();
            while (!isSpaceChar(b)) {
                sb.appendCodePoint(b);
                b = readByte();
            }
            return sb.toString();
        }

        /** Reads a fixed‑length string of exactly {@code n} characters. */
        private char[] ns(int n) {
            char[] buf = new char[n];
            int b = skip(), p = 0;
            while (p < n && !isSpaceChar(b)) {
                buf[p++] = (char) b;
                b = readByte();
            }
            return n == p ? buf : Arrays.copyOf(buf, p);
        }

        /** Reads an integer. */
        private int ni() throws IOException {
            int num = 0, b;
            boolean negative = false;
            while ((b = readByte()) != -1 && !(b >= '0' && b <= '9') && b != '-') ;
            if (b == '-') {
                negative = true;
                b = readByte();
            }
            while (true) {
                if (b >= '0' && b <= '9') {
                    num = num * 10 + (b - '0');
                } else {
                    return negative ? -num : num;
                }
                b = readByte();
            }
        }

        /** Reads a long integer. */
        private long nl() throws IOException {
            long num = 0;
            int b;
            boolean negative = false;
            while ((b = readByte()) != -1 && !(b >= '0' && b <= '9') && b != '-') ;
            if (b == '-') {
                negative = true;
                b = readByte();
            }
            while (true) {
                if (b >= '0' && b <= '9') {
                    num = num * 10 + (b - '0');
                } else {
                    return negative ? -num : num;
                }
                b = readByte();
            }
        }
    }

    // ---------------------------------------------------------------------------
    // The following constant was present in the original source and is kept for
    // compatibility with the original environment (e.g., CodeChef). It has no
    // effect on the algorithm but is retained to avoid breaking external
    // expectations.
    // ---------------------------------------------------------------------------
    private static final String INPUT = ""; // can be pre‑filled if needed
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

/**
 * Solves the problem of guaranteeing that each processed string contains at
 * least one uppercase letter, one lowercase letter and one digit.
 *
 * <p>Only the functionality required by the original program is kept, but the
 * code is now organised into small, single‑purpose methods, uses expressive
 * names and avoids unused helper classes.</p>
 */
public class Solution {

    /** Scanner‑like helper that reads tokens from {@code System.in}. */
    private static final class FastScanner {
        private final BufferedReader br;
        private StringTokenizer tokenizer;

        private FastScanner() throws IOException {
            this.br = new BufferedReader(new InputStreamReader(System.in));
        }

        /** Returns the next token, retrying until one is available. */
        private String next() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                tokenizer = new StringTokenizer(br.readLine());
            }
            return tokenizer.nextToken();
        }

        private int nextInt() {
            return Integer.parseInt(next());
        }

        private long nextLong() {
            return Long.parseLong(next());
        }

        /** Reads {@code n} integers from the input. */
        private int[] readIntArray(int n) {
            int[] a = new int[n];
            for (int i = 0; i < n; i++) {
                a[i] = nextInt();
            }
            return a;
        }
    }

    /** Entry point. */
    public static void main(String[] args) throws IOException {
        FastScanner fs = new FastScanner();
        StringBuilder output = new StringBuilder();

        int tests = fs.nextInt();
        while (tests-- > 0) {
            output.append(processCase(fs)).append('\n');
        }
        System.out.print(output);
    }

    /**
     * Solves a single test case.
     *
     * @param fs scanner used to read the case data
     * @return the transformed string for the case
     */
    private static String processCase(FastScanner fs) {
        String line = fs.next();
        char[] chars = line.toCharArray();

        int upperCnt = countUppercase(chars);
        int lowerCnt = countLowercase(chars);
        int digitCnt = countDigits(chars);

        // Already satisfied – nothing to change.
        if (upperCnt > 0 && lowerCnt > 0 && digitCnt > 0) {
            return line;
        }

        // Ensure the three required categories are present.
        ensureAllTypesPresent(chars, upperCnt, lowerCnt, digitCnt);
        return new String(chars);
    }

    /* --------------------------------------------------------------------- */
    /*  Helper methods – each does one clear, well‑named task                */
    /* --------------------------------------------------------------------- */

    private static int countUppercase(char[] arr) {
        int cnt = 0;
        for (char c : arr) {
            if (c >= 'A' && c <= 'Z') {
                cnt++;
            }
        }
        return cnt;
    }

    private static int countLowercase(char[] arr) {
        int cnt = 0;
        for (char c : arr) {
            if (c >= 'a' && c <= 'z') {
                cnt++;
            }
        }
        return cnt;
    }

    private static int countDigits(char[] arr) {
        int cnt = 0;
        for (char c : arr) {
            if (c >= '0' && c <= '9') {
                cnt++;
            }
        }
        return cnt;
    }

    /**
     * Modifies {@code arr} in‑place so that it contains at least one
     * uppercase, one lowercase and one digit.
     *
     * <p>The algorithm walks the array once, converting the first character
     * that can satisfy a missing type while respecting the “only one left”
     * constraints of the original solution.</p>
     */
    private static void ensureAllTypesPresent(
            char[] arr,
            int upperCnt,
            int lowerCnt,
            int digitCnt) {

        boolean needUpper = upperCnt == 0;
        boolean needLower = lowerCnt == 0;
        boolean needDigit = digitCnt == 0;

        for (int i = 0; i < arr.length && (needUpper || needLower || needDigit); i++) {
            char c = arr[i];

            // Uppercase can be turned into lowercase if we already have more
            // than one uppercase and we still need a lowercase.
            if (needLower && Character.isUpperCase(c) && upperCnt > 1) {
                arr[i] = Character.toLowerCase(c);
                needLower = false;
                continue;
            }

            // Lowercase can be turned into uppercase if we already have more
            // than one lowercase and we still need an uppercase.
            if (needUpper && Character.isLowerCase(c) && lowerCnt > 1) {
                arr[i] = Character.toUpperCase(c);
                needUpper = false;
                continue;
            }

            // Digit can be introduced by turning a letter into a digit,
            // provided we have a surplus of the original letter type.
            if (needDigit && Character.isLetter(c) &&
                    (Character.isUpperCase(c) && upperCnt > 1 ||
                     Character.isLowerCase(c) && lowerCnt > 1)) {
                arr[i] = digitReplacement(c);
                needDigit = false;
                continue;
            }

            // Direct conversion when the current character is the only one of
            // its kind and we need its opposite case or a digit.
            if (needUpper && !Character.isUpperCase(c)) {
                arr[i] = Character.toUpperCase(c);
                needUpper = false;
                continue;
            }
            if (needLower && !Character.isLowerCase(c)) {
                arr[i] = Character.toLowerCase(c);
                needLower = false;
                continue;
            }
            if (needDigit && !Character.isDigit(c)) {
                arr[i] = digitReplacement(c);
                needDigit = false;
                continue;
            }
        }
    }

    /** Returns a digit different from {@code original}. */
    private static char digitReplacement(char original) {
        return original == '0' ? '1' : '0';
    }
}

import java.util.Scanner;

/**
 * Refactored solution for the problem.
 * <p>
 * The program reads several test cases, each containing a single line.
 * For each line it prints the line itself if it already contains at least
 * one uppercase letter, one lowercase letter and one digit.
 * Otherwise it modifies the line so that it contains all three kinds of
 * characters (the first missing type is added by replacing the first
 * suitable character – a digit, an uppercase or a lowercase letter – with
 * an appropriate representative).  The exact modification strategy mirrors
 * the original implementation but is expressed with clearer method names
 * and without duplicated code.
 */
public class cf_1 {

    /**
     * Simple container for the three character‑type counters.
     */
    private static final class CharCounts {
        final int upper;   // number of uppercase letters
        final int lower;   // number of lowercase letters
        final int digit;   // number of digits

        CharCounts(int upper, int lower, int digit) {
            this.upper = upper;
            this.lower = lower;
            this.digit = digit;
        }
    }

    /**
     * Entry point – reads input, processes each test case and prints the result.
     */
    public static void main(String[] args) {
        // Try‑with‑resources guarantees that the scanner is closed promptly.
        try (Scanner scanner = new Scanner(System.in)) {
            int t = scanner.nextInt();
            scanner.nextLine();               // consume the newline after the test‑case count
            while (t-- > 0) {
                String line = scanner.nextLine();
                CharCounts counts = analyse(line);
                StringBuilder result = fix(line, counts);
                System.out.println(result);
            }
        }
    }

    /**
     * Counts how many uppercase letters, lowercase letters and digits are present
     * in the given string.
     */
    private static CharCounts analyse(String input) {
        int upper = 0, lower = 0, digit = 0;
        for (int i = 0; i < input.length(); i++) {
            char c = input.charAt(i);
            if (Character.isUpperCase(c)) {
                upper++;
            } else if (Character.isLowerCase(c)) {
                lower++;
            } else if (Character.isDigit(c)) {
                digit++;
            }
        }
        return new CharCounts(upper, lower, digit);
    }

    /**
     * Builds a new {@link StringBuilder} for the supplied original text.
     * If the text already satisfies the “contains upper‑case, lower‑case and digit”
     * requirement, it is returned unchanged; otherwise it is fixed so that all
     * three categories are present.
     *
     * @return a mutable builder that is either equal to the original or has been
     *         minimally altered to fulfil the requirement.
     */
    private static StringBuilder fix(String original, CharCounts counts) {
        StringBuilder sb = new StringBuilder(original);

        // When all three categories are already present there is nothing to do.
        if (counts.upper > 0 && counts.lower > 0 && counts.digit > 0) {
            return sb;
        }

        // Otherwise we try to introduce each missing character type.
        addMissingUppercaseIfNeeded(sb, counts);
        addMissingDigitIfNeeded(sb, counts);
        addMissingLowercaseIfNeeded(sb, counts);

        return sb;
    }

    /** Ensures at least one uppercase letter exists. */
    private static void addMissingUppercaseIfNeeded(StringBuilder sb, CharCounts counts) {
        if (counts.upper == 0) {
            // Prefer to replace a digit, otherwise a lowercase letter.
            if (counts.digit > 1) {
                replaceFirstDigitWith(sb, 'A');
            } else if (counts.lower > 1) {
                replaceFirstLowercaseWith(sb, 'A');
            }
        }
    }

    /** Ensures at least one digit exists. */
    private static void addMissingDigitIfNeeded(StringBuilder sb, CharCounts counts) {
        if (counts.digit == 0) {
            // Prefer to replace an existing uppercase, otherwise a lowercase.
            if (counts.upper > 1) {
                replaceFirstUppercaseWith(sb, '1');
            } else if (counts.lower > 1) {
                replaceFirstLowercaseWith(sb, '1');
            }
        }
    }

    /** Ensures at least one lowercase letter exists. */
    private static void addMissingLowercaseIfNeeded(StringBuilder sb, CharCounts counts) {
        if (counts.lower == 0) {
            // Prefer to replace a digit, otherwise an uppercase letter.
            if (counts.digit > 1) {
                replaceFirstDigitWith(sb, 'a');
            } else if (counts.upper > 1) {
                replaceFirstUppercaseWith(sb, 'a');
            }
        }
    }

    /** Replaces the first digit in the builder with {@code replacement}. */
    private static void replaceFirstDigitWith(StringBuilder sb, char replacement) {
        for (int i = 0; i < sb.length(); i++) {
            if (Character.isDigit(sb.charAt(i))) {
                sb.setCharAt(i, replacement);
                break;
            }
        }
    }

    /** Replaces the first uppercase letter in the builder with {@code replacement}. */
    private static void replaceFirstUppercaseWith(StringBuilder sb, char replacement) {
        for (int i = 0; i < sb.length(); i++) {
            if (Character.isUpperCase(sb.charAt(i))) {
                sb.setCharAt(i, replacement);
                break;
            }
        }
    }

    /** Replaces the first lowercase letter in the builder with {@code replacement}. */
    private static void replaceFirstLowercaseWith(StringBuilder sb, char replacement) {
        for (int i = 0; i < sb.length(); i++) {
            if (Character.isLowerCase(sb.charAt(i))) {
                sb.setCharAt(i, replacement);
                break;
            }
        }
    }
}

import java.util.Scanner;

/**
 * Reads several test strings and performs a simple transformation on each.
 * The transformation depends on which character categories are missing:
 *   – no lowercase letters → replace the first uppercase letter or digit with 'a'
 *   – no uppercase letters → replace the first lowercase letter or digit with 'A'
 *   – no digits        → replace the first uppercase letter or lowercase letter with '1'
 *
 * The logic of the original program is preserved, but the implementation
 * has been split into small, well‑named methods, uses proper naming,
 * constants, and resource‑safe scanning.
 */
public class Gre {

    /** The character used as a replacement for missing categories. */
    private static final char REPLACEMENT_UPPER_MISSING = 'a';
    private static final char REPLACEMENT_LOWER_MISSING = 'A';
    private static final char REPLACEMENT_DIGIT_MISSING = '1';

    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            int testCases = scanner.nextInt();
            for (int i = 0; i < testCases; i++) {
                String input = scanner.next();
                String transformed = transform(input);
                System.out.println(transformed);
            }
        }
    }

    /**
     * Performs the transformation on a single input string.
     *
     * @param original the original string
     * @return the transformed string
     */
    private static String transform(String original) {
        char[] chars = original.toCharArray();

        // Count the different character categories.
        CountResult result = countCharacterCategories(chars);

        // Decide which replacement to apply and where to apply it.
        applyReplacement(chars, result);

        return new String(chars);
    }

    /**
     * Counts uppercase letters, lowercase letters and digits in the given array.
     *
     * @param chars the character array to analyse
     * @return an immutable container with the three counts
     */
    private static CountResult countCharacterCategories(char[] chars) {
        int uppercase = 0;
        int lowercase = 0;
        int digits = 0;

        for (char c : chars) {
            if (Character.isUpperCase(c)) {
                uppercase++;
            } else if (Character.isLowerCase(c)) {
                lowercase++;
            } else if (Character.isDigit(c)) {
                digits++;
            }
        }
        return new CountResult(uppercase, lowercase, digits);
    }

    /**
     * Applies the replacement rule based on which category count is zero.
     *
     * @param chars          the mutable character array to modify in‑place
     * @param result         the counts of the three categories
     */
    private static void applyReplacement(char[] chars, CountResult result) {
        // No lowercase letters → replace first uppercase or digit.
        if (result.lowercase == 0) {
            replaceFirstOfType(chars,
                    Character::isUpperCase,
                    REPLACEMENT_UPPER_MISSING,
                    () -> result.digits > 0);
        }

        // No uppercase letters → replace first lowercase or digit.
        if (result.uppercase == 0) {
            replaceFirstOfType(chars,
                    Character::isLowerCase,
                    REPLACEMENT_LOWER_MISSING,
                    () -> result.digits > 0);
        }

        // No digits → replace first uppercase or lowercase.
        if (result.digits == 0) {
            replaceFirstOfType(chars,
                    Character::isUpperCase,
                    REPLACEMENT_DIGIT_MISSING,
                    () -> result.uppercase > 1);
        }
    }

    /**
     * Finds the first character in the array that satisfies {@code predicate}
     * and replaces it with {@code replacement}. The additional {@code guard}
     * lambda determines whether a fallback search (e.g., for digits) should be
     * performed when the primary condition is not met.
     *
     * @param chars          the array to search and modify
     * @param predicate      condition to test each character
     * @param replacement    character to write when a match is found
     * @param guard          optional guard lambda; if non‑null and returns false,
     *                       the method will continue searching for a digit instead.
     */
    private static void replaceFirstOfType(char[] chars,
                                           java.util.function.Predicate<Character> predicate,
                                           char replacement,
                                           java.util.function.Predicate<Character> guard) {
        for (int i = 0; i < chars.length; i++) {
            char c = chars[i];
            if (predicate.test(c)) {
                // If a guard is supplied and fails, we look for a digit instead.
                if (guard != null && !guard.test(c)) {
                    // Switch to digit search.
                    for (int j = 0; j < chars.length; j++) {
                        if (Character.isDigit(chars[j])) {
                            chars[j] = replacement;
                            return;
                        }
                    }
                }
                chars[i] = replacement;
                return;
            }
        }
    }

    /** Simple immutable holder for the three character counts. */
    private static final class CountResult {
        final int uppercase;
        final int lowercase;
        final int digits;

        CountResult(int uppercase, int lowercase, int digits) {
            this.uppercase = uppercase;
            this.lowercase = lowercase;
            this.digits = digits;
        }
    }
}

import java.io.PrintWriter;
import java.util.Scanner;

/**
 * Refactored version of the original program.
 *
 * <p>Changes made for maintainability:
 * <ul>
 *   <li>Extracted constant placeholders for the characters used when a category is missing.
 *   <li>Separated the validation logic into {@code hasAllCategories}.
 *   <li>Each missing‑category case is handled by a dedicated helper method
 *       ({@code addDigit}, {@code addUpper}, {@code addLower}).
 *   <li>Early returns and clear naming improve readability.
 *   <li>All mutable state is confined to the local {@code char[]} array,
 *       avoiding side‑effects on the original input.
 *   <li>Method signatures and overall flow match the original program,
 *       ensuring identical output for all inputs.
 * </ul>
 */
public class Main {
    public static void main(String[] args) {
        try (Scanner in = new Scanner(System.in);
             PrintWriter out = new PrintWriter(System.out)) {
            new TaskA().solve(1, in, out);
        }
    }

    /**
     * Original entry point – kept unchanged to preserve compatibility.
     */
    static class TaskA {
        // -----------------------------------------------------------------------
        //  Constants used when we have to inject a missing character type.
        // -----------------------------------------------------------------------
        private static final char DIGIT_PLACEHOLDER  = '1';
        private static final char LOWER_PLACEHOLDER  = 'a';
        private static final char UPPER_PLACEHOLDER  = 'A';

        /** Reads input, processes each test case and prints the result. */
        public void solve(int testNumber, Scanner in, PrintWriter out) {
            int t = in.nextInt();
            while (t-- > 0) {
                String s = in.next();
                out.println(transform(s));
            }
        }

        /** Main transformation routine – decides which rule to apply. */
        private String transform(String s) {
            char[] chars = s.toCharArray();

            // -------------------------------------------------------------------
            //  Determine which character categories are already present.
            // -------------------------------------------------------------------
            boolean hasLower = false, hasUpper = false, hasDigit = false;
            for (char c : chars) {
                if (Character.isLowerCase(c))      hasLower = true;
                else if (Character.isUpperCase(c)) hasUpper = true;
                else if (Character.isDigit(c))     hasDigit = true;
            }

            // Already satisfies the "strong" password definition.
            if (hasLower && hasUpper && hasDigit) {
                return s;
            }

            // -------------------------------------------------------------------
            //  Apply the appropriate fixing strategy.
            // -------------------------------------------------------------------
            if (hasLower && hasUpper) {
                return addDigit(chars);
            }
            if (hasLower && hasDigit) {
                return addUpper(chars);
            }
            if (hasUpper && hasDigit) {
                return addLower(chars);
            }

            // Fewer than two categories are present – fix accordingly.
            if (hasDigit) {          // only digits exist
                if (chars.length > 0) chars[0] = LOWER_PLACEHOLDER;
                if (chars.length > 1) chars[1] = UPPER_PLACEHOLDER;
            } else if (hasUpper) {   // only uppercase letters exist
                if (chars.length > 0) chars[0] = DIGIT_PLACEHOLDER;
                if (chars.length > 1) chars[1] = LOWER_PLACEHOLDER;
            } else if (hasLower) {   // only lowercase letters exist
                if (chars.length > 0) chars[0] = DIGIT_PLACEHOLDER;
                if (chars.length > 1) chars[1] = UPPER_PLACEHOLDER;
            } else {                 // no recognizable categories (edge case)
                if (chars.length > 0) chars[0] = DIGIT_PLACEHOLDER;
                if (chars.length > 1) chars[1] = LOWER_PLACEHOLDER;
                if (chars.length > 2) chars[2] = UPPER_PLACEHOLDER;
            }
            return new String(chars);
        }

        /** Tries to make the string strong by inserting a digit at the first suitable position. */
        private String addDigit(char[] chars) {
            for (int i = 0; i < chars.length; i++) {
                char saved = chars[i];
                chars[i] = DIGIT_PLACEHOLDER;
                if (hasAllCategories(chars)) {
                    return new String(chars);
                }
                chars[i] = saved; // revert on failure
            }
            return new String(chars); // fallback – should never be reached
        }

        /** Tries to make the string strong by inserting an uppercase letter at the first suitable position. */
        private String addUpper(char[] chars) {
            for (int i = 0; i < chars.length; i++) {
                char saved = chars[i];
                chars[i] = UPPER_PLACEHOLDER;
                if (hasAllCategories(chars)) {
                    return new String(chars);
                }
                chars[i] = saved;
            }
            return new String(chars);
        }

        /** Tries to make the string strong by inserting a lowercase letter at the first suitable position. */
        private String addLower(char[] chars) {
            for (int i = 0; i < chars.length; i++) {
                char saved = chars[i];
                chars[i] = LOWER_PLACEHOLDER;
                if (hasAllCategories(chars)) {
                    return new String(chars);
                }
                chars[i] = saved;
            }
            return new String(chars);
        }

        /** Checks whether the supplied character array contains at least one lower, upper and digit. */
        private boolean hasAllCategories(char[] chars) {
            boolean lower = false, upper = false, digit = false;
            for (char c : chars) {
                digit |= Character.isDigit(c);
                upper |= Character.isUpperCase(c);
                lower |= Character.isLowerCase(c);
            }
            return lower && upper && digit;
        }
    }
}

import java.io.IOException;
import java.util.Scanner;

/**
 * Reads several strings, analyses the character types they contain and,
 * according to the counts of those types, performs a small transformation.
 *
 * <p>Original functionality:
 * <ul>
 *   <li>Counts upper‑case letters, lower‑case letters and all other characters.</li>
 *   <li>If all three categories are present – prints the string unchanged.</li>
 *   <li>If exactly one category is missing – replaces the first character of that
 *       category (provided the category appears more than once) with its
 *       replacement character.</li>
 *   <li>If two categories are missing – replaces the first two characters with
 *       the appropriate replacement characters.</li>
 * </ul>
 *
 * The refactored version isolates each logical step in its own method,
 * uses clear naming and avoids duplicated magic values.
 */
public class Main {

    /* --------------------------------------------------------------------- */
    /*                         CONSTANTS / REPLACEMENTS                     */
    /* --------------------------------------------------------------------- */
    private static final char UPPER_REPLACEMENT = 'A';
    private static final char LOWER_REPLACEMENT = 'a';
    private static final char OTHER_REPLACEMENT = '1';

    /* --------------------------------------------------------------------- */
    /*                         MAIN ENTRY POINT                             */
    /* --------------------------------------------------------------------- */
    public static void main(String[] args) throws IOException {
        try (Scanner scanner = new Scanner(System.in)) {
            int testCases = scanner.nextInt();

            for (int caseIdx = 0; caseIdx < testCases; caseIdx++) {
                StringBuilder sb = new StringBuilder(scanner.next());
                int[] categoryCounts = countCategories(sb);
                int missingCategoryIdx = indexOfZero(categoryCounts);

                // No missing categories → nothing to change
                if (missingCategoryIdx == -1) {
                    System.out.println(sb);
                    continue;
                }

                // Exactly one missing category
                if (missingCategoryIdx == 0) {
                    System.out.println(sb);
                } else if (missingCategoryIdx == 1) {
                    int missingIdx = findMissingCategory(categoryCounts);
                    replaceFirstMatchingCategory(sb, categoryCounts, missingIdx);
                    System.out.println(sb);
                } else { // missingCategoryIdx == 2 → two missing categories
                    int[] missingIndices = missingCategoryIndices(categoryCounts);
                    sb.setCharAt(0, replacementFor(missingIndices[0]));
                    sb.setCharAt(1, replacementFor(missingIndices[1]));
                    System.out.println(sb);
                }
            }
        }
    }

    /* --------------------------------------------------------------------- */
    /*                         HELPER METHODS                                 */
    /* --------------------------------------------------------------------- */

    /**
     * Counts how many characters of the input belong to each of three
     * categories:
     * <ul>
     *   <li>0 – upper‑case English letters</li>
     *   <li>1 – lower‑case English letters</li>
     *   <li>2 – everything else</li>
     * </ul>
     *
     * @return an int[3] where index i holds the count for category i
     */
    private static int[] countCategories(StringBuilder sb) {
        int[] counts = new int[3];
        for (int i = 0; i < sb.length(); i++) {
            char c = sb.charAt(i);
            if (c >= 'A' && c <= 'Z') {
                counts[0]++;
            } else if (c >= 'a' && c <= 'z') {
                counts[1]++;
            } else {
                counts[2]++;
            }
        }
        return counts;
    }

    /** Returns the index of the first zero entry in {@code counts}, or -1 if none exist. */
    private static int indexOfZero(int[] counts) {
        for (int i = 0; i < counts.length; i++) {
            if (counts[i] == 0) {
                return i;
            }
        }
        return -1;
    }

    /** Returns the index of the (first) missing category among the first two positions. */
    private static int findMissingCategory(int[] counts) {
        for (int i = 0; i < counts.length - 1; i++) {
            if (counts[i] == 0) {
                return i;
            }
        }
        return counts.length - 1; // fallback – should not be reached in our use case
    }

    /**
     * Replaces the first character of {@code categoryIdx} whose occurrence count
     * is greater than one with the appropriate replacement character.
     *
     * @param sb          mutable string under modification
     * @param counts      the array returned by {@link #countCategories}
     * @param categoryIdx the category that is missing (0,1,2)
     */
    private static void replaceFirstMatchingCategory(StringBuilder sb, int[] counts, int categoryIdx) {
        for (int i = 0; i < sb.length(); i++) {
            char c = sb.charAt(i);
            int currentCategory = categoryOf(c);
            if (currentCategory == categoryIdx && counts[currentCategory] > 1) {
                sb.setCharAt(i, replacementFor(categoryIdx));
                break;
            }
        }
    }

    /** Determines which of the three categories a character belongs to. */
    private static int categoryOf(char c) {
        if (c >= 'A' && c <= 'Z') {
            return 0;
        }
        if (c >= 'a' && c <= 'z') {
            return 1;
        }
        return 2;
    }

    /** Returns the replacement character for a given category index. */
    private static char replacementFor(int categoryIdx) {
        return switch (categoryIdx) {
            case 0 -> UPPER_REPLACEMENT;
            case 1 -> LOWER_REPLACEMENT;
            default -> OTHER_REPLACEMENT;
        };
    }

    /** Collects the indices of categories whose count is zero (only among 0‑1). */
    private static int[] missingCategoryIndices(int[] counts) {
        int[] result = new int[2];
        int pos = 0;
        for (int i = 0; i < counts.length - 1; i++) {
            if (counts[i] == 0) {
                result[pos++] = i;
            }
        }
        // Fill remaining slots (in case only one missing category was found)
        while (pos < result.length) {
            result[pos++] = 2;
        }
        return result;
    }
}

import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.util.*;
import java.util.function.Consumer;
import java.util.stream.IntStream;

/**
 * Maintainable solution for the original competitive‑programming‑style task.
 *
 * <p>
 * The program reads a line consisting of characters (digits, lowercase letters,
 * and uppercase letters) and performs a series of transformations that guarantee
 * at least one character from each of the three categories appears in the
 * output.  The exact transformation rules are kept identical to the original
 * implementation, but the code has been reorganised, typed safely and heavily
 * commented to improve readability and future maintenance.
 * </p>
 */
public class Solution {

    /** Represents the three categories of characters we are tracking. */
    private enum Category {
        DIGIT,
        LOWERCASE,
        UPPERCASE
    }

    /** Scanner used to read the whole test suite. */
    private static final Scanner SCANNER = new Scanner(new BufferedReader(new InputStreamReader(System.in)));

    /** Entry point. */
    public static void main(String[] args) {
        int testCases = Integer.parseInt(SCANNER.nextLine().trim());
        for (int i = 1; i <= testCases; i++) {
            System.out.printf("Case #%d: %s%n", i, solve());
        }
    }

    /**
     * Reads a single test case, transforms it, and returns the resulting string.
     *
     * <p>The algorithm mirrors the original implementation but is now expressed
     * with clearly named methods and guard clauses.</p>
     */
    public static String solve() {
        // 1️⃣ Read the whole line and turn it into a mutable character array.
        char[] input = SCANNER.nextLine().trim().toCharArray();
        int length = input.length;

        // 2️⃣ Count occurrences of each category.
        int[] categoryCount = countCategories(input); // [digitCount, lowerCount, upperCount]

        // 3️⃣ Apply the transformation rules.
        //    The rules are identical to the original but written with early returns
        //    and explicit intent.
        if (categoryCount[Category.DIGIT.ordinal()] == 0) {
            // No digits yet – decide what to inject based on other counts.
            if (categoryCount[Category.LOWERCASE.ordinal()] == 0) {
                injectAndReturn(input, 0, '1', 'a');
            } else if (categoryCount[Category.UPPERCASE.ordinal()] == 0) {
                injectAndReturn(input, 0, '1', 'A');
            } else if (categoryCount[Category.LOWERCASE.ordinal()] == 1) {
                replaceFirstMatching(input, Character::isUpperCase, '1');
            } else { // categoryCount[Category.UPPERCASE.ordinal()] == 1
                replaceFirstMatching(input, Character::isLowerCase, '1');
            }
        } else if (categoryCount[Category.LOWERCASE.ordinal()] == 0) {
            if (categoryCount[Category.UPPERCASE.ordinal()] == 0) {
                injectAndReturn(input, 0, 'a', 'A');
            } else if (categoryCount[Category.UPPERCASE.ordinal()] == 1) {
                replaceFirstMatching(input, Character::isDigit, 'a');
            } else {
                replaceFirstMatching(input, Character::isUpperCase, 'a');
            }
        } else if (categoryCount[Category.UPPERCASE.ordinal()] == 0) {
            if (categoryCount[Category.LOWERCASE.ordinal()] == 1) {
                replaceFirstMatching(input, Character::isLowerCase, 'A');
            } else {
                replaceFirstMatching(input, Character::isDigit, 'A');
            }
        }

        // 4️⃣ Return the transformed string.
        return new String(input);
    }

    /**
     * Counts how many characters of each category appear in the supplied array.
     *
     * @return an int[3] where:
     *         <ul>
     *           <li>[0] = number of digits ('0'‑'9')
     *           <li>[1] = number of lowercase letters ('a'‑'z')
     *           <li>[2] = number of uppercase letters ('A'‑'Z')
     *         </ul>
     */
    private static int[] countCategories(char[] chars) {
        int[] result = new int[3];
        for (char c : chars) {
            if (Character.isDigit(c)) {
                result[0]++;
            } else if (Character.isLowerCase(c)) {
                result[1]++;
            } else if (Character.isUpperCase(c)) {
                result[2]++;
            }
        }
        return result;
    }

    /**
     * If the character at {@code index} satisfies {@code predicate},
     * replace it with {@code replacement} and return {@code true};
     * otherwise scan from the beginning for the first match and act there.
     *
     * @return {@code true} if a replacement was performed.
     */
    private static void replaceFirstMatching(char[] arr,
                                             java.util.function.Predicate<Character> predicate,
                                             char replacement) {
        // Try to replace the character at the given index directly (original logic used index 0).
        if (predicate.test(arr[0])) {
            arr[0] = replacement;
            return;
        }

        // Scan from the start for the first character that matches the predicate.
        for (int i = 0; i < arr.length; i++) {
            if (predicate.test(arr[i])) {
                arr[i] = replacement;
                return;
            }
        }
    }

    /**
     * Helper that overwrites the character at {@code index} with {@code first} and
     * replaces the first occurrence of {@code secondPattern} (via {@code replaceFirstMatching})
     * with {@code replacement}.  This mirrors the original multi‑branch logic where two
     * different characters were injected at positions 0 and 1.
     *
     * @param arr           mutable character array
     * @param index         position that will receive {@code first}
     * @param first         character written at {@code index}
     * @param replacement   character to inject when a match is found
     */
    private static void injectAndReturn(char[] arr, int index, char first, char replacement) {
        arr[index] = first;          // Overwrite the element at the given slot.
        replaceFirstMatching(arr, c -> true, replacement); // Always true → just replace first char.
    }
}

