import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;

/**
 * Refactored version of the original program.
 *
 * <p>
 *  The program reads several test cases. For each test case it
 *  examines the characters that appear in the input string:
 *  <ul>
 *      <li>lower‑case letters</li>
 *      <li>upper‑case letters</li>
 *      <li>digits</li>
 *  </ul>
 *  If all three categories are present the original string is printed.
 *  Otherwise the program decides which category is missing or least frequent,
 *  inserts a representative character at an appropriate position, and prints
 *  the resulting string.
 * </p>
 *
 * <p>Design goals of this refactor:</p>
 * <ul>
 *   <li>Clear separation of concerns (reading, classifying, processing, output).</li>
 *   <li>Use of expressive names, enums and helper methods instead of raw magic numbers.</li>
 *   <li>Elimination of duplicated code (e.g. the insertion logic).</li>
 *   <li>Proper resource handling with try‑with‑resources.</li>
 *   <li>Constants for ASCII ranges and insertion‑type codes.</li>
 * </ul>
 */
public class Main {

    /** Enum representing the three possible character categories. */
    private enum Category {
        LOWER, UPPER, DIGIT;

        /** Small helper to map the enum to the character we want to insert. */
        private static final java.util.Map<Category, String> INSERT_CHAR = Map.of(
                Category.LOWER, "a",
                Category.UPPER, "A",
                Category.DIGIT, "0"
        );

        /** Returns the insertion character for this category. */
        public String insertionChar() {
            return INSERT_CHAR.get(this);
        }
    }

    /** Simple holder for the statistics of a given string. */
    private static final class Statistics {
        int lowerCount = 0;
        int upperCount = 0;
        int digitCount = 0;
        boolean hasLower = false;
        boolean hasUpper = false;
        boolean hasDigit = false;
    }

    /** Reads one line from the buffered reader, returning {@code null} on EOF. */
    private static String readLineSafe(BufferedReader br) throws IOException {
        String line = br.readLine();
        return line == null ? null : line.trim();
    }

    /**
     * Classifies every character of {@code input} into one of the three categories.
     *
     * @param input the string to analyse
     * @param stats a mutable holder that will be filled with the counts and presence flags
     */
    private static void classify(String input, Statistics stats) {
        for (int i = 0; i < input.length(); i++) {
            char c = input.charAt(i);
            if (Character.isLowerCase(c)) {
                stats.lowerCount++;
                stats.hasLower = true;
            } else if (Character.isUpperCase(c)) {
                stats.upperCount++;
                stats.hasUpper = true;
            } else if (Character.isDigit(c)) {
                stats.digitCount++;
                stats.hasDigit = true;
            }
        }
    }

    /**
     * Determines which category is currently the most frequent (ignoring categories that are missing).
     *
     * @param stats the statistics object containing the three counts
     * @return the {@link Category} that corresponds to the highest count
     */
    private static Category mostFrequentCategory(Statistics stats) {
        Category mostFrequent = Category.LOWER; // start with a safe default

        if (stats.hasUpper && stats.upperCount > stats.lowerCount) {
            mostFrequent = Category.UPPER;
        }
        if (stats.hasDigit && stats.digitCount > (mostFrequent == Category.LOWER ?
                stats.lowerCount : (mostFrequent == Category.UPPER ? stats.upperCount : 0))) {
            mostFrequent = Category.DIGIT;
        }
        return mostFrequent;
    }

    /**
     * Inserts a representative character of the given {@link Category} at the first position
     * where a character of that same category already appears. If no such position exists,
     * the character is appended.
     *
     * @param input        the original string
     * @param category     the category to insert
     * @return the new string with the inserted character
     */
    private static String insertCharacter(String input, Category category) {
        String insertionChar = category.insertionChar();

        for (int i = 0; i < input.length(); i++) {
            char c = input.charAt(i);
            boolean matchesDesiredCategory = switch (category) {
                case LOWER -> Character.isLowerCase(c);
                case UPPER -> Character.isUpperCase(c);
                case DIGIT -> Character.isDigit(c);
            };
            if (matchesDesiredCategory) {
                return input.substring(0, i) + insertionChar + input.substring(i);
            }
        }
        // No matching character found – simply append.
        return input + insertionChar;
    }

    /**
     * Produces the output string that corresponds to the original logic of the program.
     *
     * @param input the raw input line
     * @param stats the classification statistics for {@code input}
     * @return the processed string to be printed
     */
    private static String process(String input, Statistics stats) {
        // All three categories are present → nothing to modify.
        if (stats.hasLower && stats.hasUpper && stats.hasDigit) {
            return input;
        }

        // Decide which category should be inserted.
        Category categoryToInsert = mostFrequentCategory(stats);

        // Determine which categories are missing.
        boolean missingLower = !stats.hasLower;
        boolean missingUpper = !stats.hasUpper;
        boolean missingDigit = !stats.hasDigit;

        // -----------------------------------------------------------------------
        // The original program performed a few special‑case concatenations:
        //   "Aa"   – when both letter cases are missing
        //   "a0"   – when only digit is missing and lower‑case is missing
        //   "A0"   – when only digit is missing and upper‑case is missing
        // -----------------------------------------------------------------------
        if (!missingUpper && !missingLower) {
            // Neither lower nor upper case characters appear – prepend "Aa"
            return "Aa" + input.substring(2);
        } else if (!missingDigit && !missingLower) {
            // No digits, but lower case exists – prepend "a0"
            return "a0" + input.substring(2);
        } else if (!missingDigit && !missingUpper) {
            // No digits, but upper case exists – prepend "A0"
            return "A0" + input.substring(2);
        }

        // Normal case: insert the appropriate character.
        return insertCharacter(input, categoryToInsert);
    }

    /** Entry point of the application. */
    public static void main(String[] args) throws IOException {
        // Use try‑with‑resources to guarantee the reader is closed.
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in))) {
            int testCases = Integer.parseInt(readLineSafe(br));

            while (testCases-- > 0) {
                String line = readLineSafe(br);
                if (line == null || line.isEmpty()) {
                    System.out.println(line);
                    continue;
                }

                Statistics stats = new Statistics();
                classify(line, stats);

                String result = process(line, stats);
                System.out.println(result);
            }
        }
    }
}

import java.io.IOException;
import java.util.HashSet;
import java.util.Scanner;

/**
 * Refactored solution that transforms each input string.
 *
 * <p>
 *   Original behaviour:
 *   <ul>
 *     <li>If a string already contains at least one lowercase, one uppercase
 *         and one digit, it is printed unchanged.
 *     <li>Otherwise the missing categories are inserted at distinct positions
 *         using the placeholders 'a', 'A' and '1' – exactly the same logic as the
 *         original implementation, but expressed with clearer naming and
 *         separated concerns.
 *   </ul>
 * </p>
 */
public class Main {

    /** Placeholder used when a lowercase character is missing. */
    private static final char LOWER_PLACEHOLDER = 'a';

    /** Placeholder used when an uppercase character is missing. */
    private static final char UPPER_PLACEHOLDER = 'A';

    /** Placeholder used when a digit is missing. */
    private static final char DIGIT_PLACEHOLDER = '1';

    public static void main(String[] args) throws IOException {
        /* Try‑with‑resources guarantees the scanner is closed promptly. */
        try (Scanner scanner = new Scanner(System.in)) {
            int testCases = scanner.nextInt();
            for (int caseIdx = 0; caseIdx < testCases; caseIdx++) {
                String current = scanner.next();
                System.out.println(transform(current));
            }
        }
    }

    /**
     * Returns the possibly transformed string.
     *
     * <p>
     * The algorithm consists of three clear steps:
     * <ol>
     *   <li>Detect which of the three required categories are missing.</li>
     *   <li>If all categories are present, return the original string.</li>
     *   <li>Otherwise place the appropriate placeholder on the first free index
     *       for each missing category, preserving the original order of characters
     *       for all other positions.</li>
     * </ol>
     * </p>
     *
     * @param input the string to be examined and possibly transformed
     * @return the (possibly) transformed string
     */
    private static String transform(String input) {
        // -----------------------------------------------------------------
        // 1️⃣  Detect which categories are already present.
        // -----------------------------------------------------------------
        boolean hasLower = false;
        boolean hasUpper = false;
        boolean hasDigit = false;

        for (int i = 0; i < input.length(); i++) {
            char c = input.charAt(i);
            if (Character.isLowerCase(c)) {
                hasLower = true;
            } else if (Character.isUpperCase(c)) {
                hasUpper = true;
            } else if (Character.isDigit(c)) {
                hasDigit = true;
            }
        }

        // -----------------------------------------------------------------
        // 2️⃣  If nothing is missing, just return the original string.
        // -----------------------------------------------------------------
        if (hasLower && hasUpper && hasDigit) {
            return input;
        }

        // -----------------------------------------------------------------
        // 3️⃣  Build the result array, inserting placeholders for the missing
        //      categories while guaranteeing that each placeholder occupies a
        //      distinct index (mirroring the original algorithm's behaviour).
        // -----------------------------------------------------------------
        char[] result = input.toCharArray();
        HashSet<Integer> usedIndices = new HashSet<>();

        // Missing categories are filled in a fixed order: lower → upper → digit.
        // The first free index is chosen for each placeholder.
        for (int i = 0; i < result.length; i++) {
            if (!hasLower && !usedIndices.contains(i)) {
                result[i] = LOWER_PLACEHOLDER;
                usedIndices.add(i);
                hasLower = true;               // mark as filled
                continue;
            }
            if (!hasUpper && !usedIndices.contains(i)) {
                result[i] = UPPER_PLACEHOLDER;
                usedIndices.add(i);
                hasUpper = true;
                continue;
            }
            if (!hasDigit && !usedIndices.contains(i)) {
                result[i] = DIGIT_PLACEHOLDER;
                usedIndices.add(i);
                hasDigit = true;
                continue;
            }
            // Keep the original character when no placeholder is needed here.
            result[i] = input.charAt(i);
        }

        return new String(result);
    }
}

import java.io.*;
import java.util.*;

public class Main {

    /* Constants used for the required insertions */
    private static final char INSERT_LOWER   = 'a';
    private static final char INSERT_UPPER   = 'A';
    private static final char INSERT_DIGIT   = '1';

    /** Simple holder for the three character categories */
    private static final class Category {
        final int count;      // how many characters of this type
        final int firstPos;   // index of the first occurrence (-1 if none)

        Category(int count, int firstPos) {
            this.count = count;
            this.firstPos = firstPos;
        }
    }

    public static void main(String[] args) {
        /* Use try‑with‑resources to guarantee the reader is closed */
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in))) {
            int testCases = Integer.parseInt(br.readLine().trim());
            StringBuilder output = new StringBuilder();

            for (int t = 0; t < testCases; t++) {
                String line = br.readLine();
                if (line == null || line.isEmpty()) {
                    continue;                     // skip empty lines
                }

                char[] chars = line.toCharArray();
                Category[] stats = analyse(line);

                transform(chars, stats);
                output.append(chars).append('\n');
            }

            System.out.print(output.toString());
        } catch (IOException e) {
            throw new RuntimeException(e);
        }
    }

    /** Analyses a line and returns counts + first positions for lower/upper/digit. */
    private static Category[] analyse(String line) {
        int lowerCnt = 0, upperCnt = 0, digitCnt = 0;
        int lowerPos = -1, upperPos = -1, digitPos = -1;

        for (int i = 0; i < line.length(); i++) {
            char c = line.charAt(i);
            if (Character.isLowerCase(c)) {
                lowerCnt++;
                if (lowerPos == -1) lowerPos = i;
            } else if (Character.isUpperCase(c)) {
                upperCnt++;
                if (upperPos == -1) upperPos = i;
            } else if (Character.isDigit(c)) {
                digitCnt++;
                if (digitPos == -1) digitPos = i;
            }
        }
        return new Category[] {
                new Category(lowerCnt, lowerPos),
                new Category(upperCnt, upperPos),
                new Category(digitCnt, digitPos)
        };
    }

    /** Applies the transformation rules defined in the original program. */
    private static void transform(char[] chars, Category[] stats) {
        boolean hasLower = stats[0].count > 0;
        boolean hasUpper = stats[1].count > 0;
        boolean hasDigit = stats[2].count > 0;

        int presentCategories = (hasLower ? 1 : 0) + (hasUpper ? 1 : 0) + (hasDigit ? 1 : 0);

        switch (presentCategories) {
            case 2 -> { // exactly two categories are present – one is missing
                if (!hasLower) {                     // missing lowercase
                    int replacePos = (stats[1].count > stats[2].count)
                            ? stats[1].firstPos   // uppercase count larger (or equal → digit)
                            : stats[2].firstPos;
                    chars[replacePos] = INSERT_LOWER;
                } else if (!hasUpper) {              // missing uppercase
                    int replacePos = (stats[0].count > stats[2].count)
                            ? stats[0].firstPos   // lowercase count larger
                            : stats[2].firstPos;
                    chars[replacePos] = INSERT_UPPER;
                } else {                             // missing digit
                    int replacePos = (stats[0].count > stats[1].count)
                            ? stats[0].firstPos   // lowercase count larger
                            : stats[1].firstPos;
                    chars[replacePos] = INSERT_DIGIT;
                }
            }
            case 1 -> { // only one category present – normalise the first two characters
                if (hasLower) {
                    chars[0] = INSERT_UPPER;
                    chars[1] = INSERT_DIGIT;
                } else if (hasUpper) {
                    chars[0] = INSERT_LOWER;
                    chars[1] = INSERT_DIGIT;
                } else { // only digits present
                    chars[0] = INSERT_LOWER;
                    chars[1] = INSERT_UPPER;
                }
            }
            /* No other cases are reachable given the input guarantees. */
        }
    }
}

import java.io.*;
import java.util.StringTokenizer;

/**
 * Refactored version of the original program.
 * The code has been reorganised into clearly named methods,
 * uses expressive variable names and separates input handling
 * from the transformation logic.
 */
public class Main {

    /** Character used as a placeholder for a missing digit. */
    private static final char DIGIT_PLACEHOLDER = '0';

    /** Character used as a placeholder for a missing uppercase letter. */
    private static final char UPPER_PLACEHOLDER = 'A';

    /** Character used as a placeholder for a missing lowercase letter. */
    private static final char LOWER_PLACEHOLDER = 'a';

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(System.out, true);

        int t = fs.nextInt();
        for (int tc = 0; tc < t; ++tc) {
            String input = fs.next();
            out.println(transform(input));
        }

        out.close();
    }

    /**
     * Performs the transformation defined by the original algorithm.
     *
     * @param s the original string
     * @return the possibly modified string
     */
    private static String transform(String s) {
        boolean hasLower = false, hasUpper = false, hasDigit = false;
        int lastPos = -1;               // index of the last repeated category
        char[] buf = s.toCharArray();

        for (int i = 0; i < s.length(); ++i) {
            char ch = s.charAt(i);
            if (Character.isDigit(ch)) {
                if (hasDigit) {
                    lastPos = i;
                }
                hasDigit = true;
            } else if (Character.isUpperCase(ch)) {
                if (hasUpper) {
                    lastPos = i;
                }
                hasUpper = true;
            } else { // lowercase
                if (hasLower) {
                    lastPos = i;
                }
                hasLower = true;
            }
        }

        // All three categories are present – nothing to change.
        if (hasLower && hasUpper && hasDigit) {
            return s;
        }

        // Helper to build the result when a replacement is required.
        BiFunction<Integer, Character, String> buildResult = (idx, repl) -> {
            char[] result = buf.clone();
            if (idx != -1) {
                result[idx] = repl;
            } else {
                // When no repetition was found we fall back to the
                // same positions that the original code used.
                switch (determineFallbackCase(hasLower, hasUpper, hasDigit)) {
                    case 1 -> { result[0] = UPPER_PLACEHOLDER; result[1] = DIGIT_PLACEHOLDER; }
                    case 2 -> { result[0] = DIGIT_PLACEHOLDER; result[1] = LOWER_PLACEHOLDER; }
                    case 3 -> { result[0] = LOWER_PLACEHOLDER; result[1] = UPPER_PLACEHOLDER; }
                    default -> { /* should never happen */ }
                }
            }
            return new String(result);
        };

        // Decide which category is missing and act accordingly.
        if (hasLower) {
            if (hasUpper) {
                // Missing digit
                return buildResult.apply(lastPos, DIGIT_PLACEHOLDER);
            } else {
                // Missing uppercase
                return buildResult.apply(lastPos, UPPER_PLACEHOLDER);
            }
        } else if (hasUpper) {
            if (hasDigit) {
                // Missing lowercase
                return buildResult.apply(lastPos, LOWER_PLACEHOLDER);
            } else {
                // Missing both lowercase and digit
                return buildResult.apply(0, LOWER_PLACEHOLDER);
            }
        } else {
            // No lowercase nor uppercase present – only digits exist.
            // The original code used a fixed replacement for the first two chars.
            return buildResult.apply(0, LOWER_PLACEHOLDER);
        }
    }

    /**
     * Determines which fallback pattern to apply when the original
     * algorithm would replace the first two characters.
     *
     * @return an identifier for the pattern (1‑3) matching the
     *         original series of assignments.
     */
    private static int determineFallbackCase(boolean hasLower, boolean hasUpper, boolean hasDigit) {
        if (!hasLower && hasUpper && !hasDigit) {
            return 1; // original: replace first two with 'A' and '0'
        }
        if (!hasLower && !hasUpper && hasDigit) {
            return 2; // original: replace first two with '0' and 'a'
        }
        // The only remaining situation corresponds to the final else‑branch
        // of the original program.
        return 3; // original: replace first two with 'a' and 'A'
    }

    /** Simple fast scanner used for reading input tokens. */
    private static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner(InputStream stream) {
            br = new BufferedReader(new InputStreamReader(stream), 256_000 * 4);
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.io.PrintWriter;
