import java.io.*;
import java.util.*;

/**
 * Main entry point of the program.
 * Reads the board dimensions and cell contents,
 * then decides whether the board can be completely
 * covered by the allowed 3×3 stamp pattern.
 */
public class Main {

    public static void main(String[] args) {
        // Use try‑with‑resources so that every I/O resource is closed automatically.
        try (InputStream in = System.in;
             OutputStream outStream = System.out) {

            InputReader reader = new InputReader(in);
            PrintWriter writer = new PrintWriter(outStream, true);

            new Solver().solve(reader, writer);

        } catch (IOException e) {
            // In a competition setting we simply terminate on I/O errors.
            throw new UncheckedIOException(e);
        }
    }

    /**
     * Core logic that decides whether the given board can be fully covered
     * by the 3×3 stamp pattern (all '#' except the centre '.')
     */
    static class Solver {

        /** Size of the stamp (always 3). */
        private static final int STAMP_SIZE = 3;

        /** The reference pattern – a 3×3 block with a hole in the centre. */
        private static final char[][] STAMP_PATTERN = fillStampPattern();

        /**
         * Entry point for the solving process.
         *
         * @param reader  object that reads tokens from {@code System.in}
         * @param writer  object that writes output to {@code System.out}
         */
        public void solve(InputReader reader, PrintWriter writer) {
            int rows = reader.nextInt();
            int cols = reader.nextInt();

            char[][] board = readBoard(reader, rows);
            boolean[][] visited = new boolean[rows][cols];

            // Try to place a stamp with its top‑left corner at every possible position.
            for (int r = 0; r <= rows - STAMP_SIZE; r++) {
                for (int c = 0; c <= cols - STAMP_SIZE; c++) {
                    if (canPlaceStamp(board, visited, r, c)) {
                        placeStamp(visited, r, c);
                    }
                }
            }

            // If any '#' cell was never visited, covering is impossible.
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (board[r][c] == '#' && !visited[r][c]) {
                        writer.println("NO");
                        return;
                    }
                }
            }

            writer.println("YES");
        }

        /**
         * Reads a rectangular board of characters.
         *
         * @param reader Input reader
         * @param rows   number of rows
         * @return       character matrix representing the board
         */
        private char[][] readBoard(InputReader reader, int rows) {
            char[][] board = new char[rows][];
            for (int i = 0; i < rows; i++) {
                board[i] = reader.next().toCharArray();
            }
            return board;
        }

        /**
         * Determines whether a stamp with its top‑left corner at (startRow,
         * startCol) can be placed on the board. The condition is that every
         * cell of the stamp must be '#' except for the centre cell, which must
         * also be '#' in the source board (the centre is allowed to stay
         * uncovered – later we will skip marking it).
         *
         * @param board   source board
         * @param visited matrix indicating which cells have already been covered
         * @param startRow row index of the stamp's top‑left corner
         * @param startCol column index of the stamp's top‑left corner
         * @return true if the stamp can be placed here, false otherwise
         */
        private boolean canPlaceStamp(char[][] board, boolean[][] visited, int startRow, int startCol) {
            // Quick reject: the centre cell must be '#'; otherwise the stamp pattern would be invalid.
            int centreRow = startRow + 1;
            int centreCol = startCol + 1;
            if (board[centreRow][centreCol] != '#') {
                return false;
            }

            // Verify that all eight outer cells are '#'.
            for (int dr = 0; dr < STAMP_SIZE; dr++) {
                for (int dc = 0; dc < STAMP_SIZE; dc++) {
                    if (dr == 1 && dc == 1) {
                        continue; // skip centre cell
                    }
                    if (board[startRow + dr][startCol + dc] != '#') {
                        return false;
                    }
                }
            }
            return true;
        }

        /**
         * Marks the eight outer cells of the stamp as visited.
         *
         * @param visited matrix to be updated
         * @param startRow row index of the stamp's top‑left corner
         * @param startCol column index of the stamp's top‑left corner
         */
        private void placeStamp(boolean[][] visited, int startRow, int startCol) {
            for (int dr = 0; dr < STAMP_SIZE; dr++) {
                for (int dc = 0; dc < STAMP_SIZE; dc++) {
                    if (dr == 1 && dc == 1) {
                        continue; // centre stays unmarked on purpose
                    }
                    visited[startRow + dr][startCol + dc] = true;
                }
            }
        }

        /**
         * Fills a 3×3 array with the reference stamp pattern:
         * all cells are '#', the centre cell is '.'.
         *
         * @return a freshly allocated 3×3 pattern
         */
        private static char[][] fillStampPattern() {
            char[][] pattern = new char[STAMP_SIZE][STAMP_SIZE];
            for (int r = 0; r < STAMP_SIZE; r++) {
                Arrays.fill(pattern[r], '#');
            }
            pattern[1][1] = '.';
            return pattern;
        }
    }

    /**
     * Simple, fast tokenizer that works with any {@link InputStream}.
     * It mirrors the original implementation but keeps the contract
     * explicit and well‑documented.
     */
    static class InputReader {
        private final InputStream stream;
        private final byte[] buffer = new byte[16384];
        private int currentByte;
        private int bytesRead;
        private boolean endOfFile;

        public InputReader(InputStream stream) {
            this.stream = stream;
        }

        /** Reads the next byte, returning -1 on EOF. */
        private int readByte() {
            if (endOfFile) {
                return -1;
            }
            if (currentByte >= bytesRead) {
                currentByte = 0;
                bytesRead = stream.read(buffer);
                if (bytesRead <= 0) {
                    endOfFile = true;
                    return -1;
                }
            }
            return buffer[currentByte++];
        }

        /** Returns true if the character is a whitespace according to the problem statement. */
        private static boolean isSpaceChar(int ch) {
            return ch == ' ' || ch == '\n' || ch == '\r' || ch == '\t' || ch == -1;
        }

        /** Reads the next non‑space token. */
        public String next() {
            int c;
            do {
                c = readByte();
            } while (isSpaceChar(c));
            StringBuilder sb = new StringBuilder();
            do {
                sb.append((char) c);
                c = readByte();
            } while (!isSpaceChar(c));
            return sb.toString();
        }

        /** Reads the next integer (supports negative numbers). */
        public int nextInt() {
            int c = nextByte();
            while (isSpaceChar(c)) {
                c = nextByte();
            }
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = nextByte();
            }
            int result = 0;
            do {
                if (c < '0' || c > '9') {
                    throw new InputMismatchException();
                }
                result = result * 10 + (c - '0');
                c = nextByte();
            } while (!isSpaceChar(c));
            return result * sign;
        }

        /** Reads the next byte, skipping whitespace. */
        private int nextByte() {
            int b;
            do {
                b = readByte();
            } while (isSpaceChar(b));
            return b;
        }
    }
}

import java.util.*;

public class Codeforces {

    private static final char HASH = '#';
    private static final char DOT = '.';
    private static PrintWriter out;

    /** Entry point */
    public static void main(String[] args) throws Exception {
        try (Scanner sc = new Scanner(System.in)) {
            int n = sc.nextInt();
            int m = sc.nextInt();
            char[][] board = new char[n][];
            for (int i = 0; i < n; i++) {
                board[i] = sc.next().toCharArray();
            }

            out = new PrintWriter(new BufferedOutputStream(System.out));
            out.println(solve(n, m, board));
            out.close();
        }
    }

    /** Determines whether the board can be fully covered by the allowed 8‑cell patterns. */
    private static String solve(int n, int m, char[][] board) {
        boolean[][] visited = new boolean[n][m];

        // 8 distinct patterns – each describes the relative positions of the 8 '#'
        // cells (the first offset is always the anchor at (0,0)).
        final int[][] PATTERN_ONE = {
                {0, 0}, {1, 0}, {2, 0}, {0, 1}, {0, 2}, {1, 2}, {2, 1}, {2, 2}
        };
        final int[][] PATTERN_TWO = {
                {0, 0}, {0, -1}, {2, 0}, {1, -1}, {2, -1}, {0, 1}, {1, 1}, {2, 1}
        };
        final int[][] PATTERN_THREE = {
                {0, 0}, {0, -1}, {0, -2}, {1, 0}, {1, -2}, {2, 0}, {2, -1}, {2, -2}
        };
        final int[][] PATTERN_FOUR = {
                {0, 0}, {-1, 0}, {-1, 1}, {-1, 2}, {0, 2}, {1, 0}, {1, 1}, {1, 2}
        };
        final int[][] PATTERN_FIVE = {
                {0, 0}, {-1, 0}, {-1, -1}, {-1, -2}, {0, -2}, {1, 0}, {1, -1}, {1, -2}
        };
        final int[][] PATTERN_SIX = {
                {0, 0}, {-1, 0}, {-2, 0}, {-2, 1}, {0, 1}, {-2, 2}, {-1, 2}, {0, 2}
        };
        final int[][] PATTERN_SEVEN = {
                {0, 0}, {0, -1}, {-1, -1}, {-2, -1}, {-2, 0}, {-2, 1}, {-1, 1}, {0, 1}
        };
        final int[][] PATTERN_EIGHT = {
                {0, 0}, {-1, 0}, {-2, 0}, {-2, -1}, {0, -1}, {0, -2}, {-1, -2}, {-2, -2}
        };

        List<int[][]> patterns = List.of(
                PATTERN_ONE, PATTERN_TWO, PATTERN_THREE,
                PATTERN_FOUR, PATTERN_FIVE, PATTERN_SIX,
                PATTERN_SEVEN, PATTERN_EIGHT
        );

        // Scan the board; every '#' must belong to exactly one pattern.
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (board[i][j] != HASH || visited[i][j]) {
                    continue;
                }

                boolean placed = false;
                for (int[][] offsets : patterns) {
                    if (canPlace(board, visited, i, j, offsets)) {
                        place(board, visited, i, j, offsets);
                        placed = true;
                        break;
                    }
                }
                if (!placed) {
                    return "NO";
                }
            }
        }
        return "YES";
    }

    /** Checks whether the pattern anchored at (i,j) can be placed on the board. */
    private static boolean canPlace(char[][] board, boolean[][] visited,
                                    int i, int j, int[][] offsets) {
        for (int[] off : offsets) {
            int ni = i + off[0];
            int nj = j + off[1];
            if (ni < 0 || ni >= board.length || nj < 0 || nj >= board[0].length) {
                return false;
            }
            if (board[ni][nj] != HASH || visited[ni][nj]) {
                return false;
            }
        }
        return true;
    }

    /** Marks all cells of the successfully placed pattern as visited. */
    private static void place(char[][] board, boolean[][] visited,
                              int i, int j, int[][] offsets) {
        for (int[] off : offsets) {
            visited[i + off[0]][j + off[1]] = true;
        }
    }
}

