class FastScanner {
    private final DataInputStream din;
    private final byte[] buffer;
    private int bufferPointer, bytesRead;

    FastScanner() {
        din = new DataInputStream(System.in);
        buffer = new byte[1 << 16];
        bufferPointer = bytesRead = 0;
    }

    private byte read() throws IOException {
        if (bufferPointer == bytesRead) {
            fillBuffer();
        }
        return buffer[bufferPointer++];
    }

    private void fillBuffer() throws IOException {
        bytesRead = din.read(buffer, 0, buffer.length);
        if (bytesRead == -1) {
            buffer[0] = -1;
        }
        bufferPointer = 0;
    }

    /** Reads next integer (as used by the original program). */
    int nextInt() throws IOException {
        int ret = 0;
        byte c = read();
        while (c <= ' ') {
            c = read();
        }
        boolean neg = (c == '-');
        if (neg) {
            c = read();
        }
        do {
            ret = ret * 10 + (c - '0');
        } while ((c = read()) >= '0' && c <= '9');

        return neg ? -ret : ret;
    }
}

class FastPrinter {
    private final PrintWriter out;

    FastPrinter(java.io.OutputStream stream) {
        this.out = new PrintWriter(stream);
    }

    void println(Object o) {
        out.println(o);
    }

    void print(Object o) {
        out.print(o);
    }

    void flush() {
        out.flush();
    }

    void close() {
        out.close();
    }
}

import java.io.*;
import java.util.*;

/**
 * Solves the “Palindromic Matrix” problem.
 *
 * <p>
 *   The original implementation mixed I/O, algorithmic steps and a dead
 *   priority‑queue class.  The refactor separates concerns, uses expressive
 *   names, extracts small helper methods, and removes dead code.
 * </p>
 *
 * <p>Running the program:
 * <code>java Test77</code> reads from standard input and writes the result
 * to standard output.</p>
 */
public class Test77 {

    /** Fast scanner based on a buffered {@link InputStream}. */
    private static final class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[16 * 1024];
        private int ptr = 0, len = 0;

        FastScanner(InputStream in) { this.in = in; }

        private int readByte() throws IOException {
            if (len < 0) throw new EOFException();
            if (ptr >= len) {
                ptr = 0;
                len = in.read(buffer);
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        /** Skips leading whitespace. */
        private int skip() throws IOException {
            int b;
            while ((b = readByte()) != -1 && isSpace(b)) {}
            return b;
        }

        private static boolean isSpace(int c) {
            return c <= 32;
        }

        /** Reads next non‑space token as a {@code String}. */
        private String nextString() throws IOException {
            int b = skip();
            StringBuilder sb = new StringBuilder();
            while (!isSpace(b)) {
                sb.appendCodePoint(b);
                b = readByte();
            }
            return sb.toString();
        }

        /** Reads next {@code int}. */
        int nextInt() throws IOException {
            int sign = 1, c;
            do { c = readByte(); } while (c <= 32);
            if (c == '-') { sign = -1; c = readByte(); }
            int val = 0;
            while (c > 32) {
                val = val * 10 + (c - '0');
                c = readByte();
            }
            return val * sign;
        }
    }

    /** Pretty printer used for output. */
    private static final class OutputWriter {
        private final PrintWriter out;
        OutputWriter(PrintWriter out) { this.out = out; }

        void print(Object o) { out.print(o); }
        void println() { out.println(); }
        void flush() { out.flush(); }

        /** Prints a 2‑D int array in the required format. */
        void printMatrix(int[][] mat) {
            for (int[] row : mat) {
                for (int v : row) {
                    out.print(v + " ");
                }
                out.println();
            }
        }
    }

    /** Core algorithm – builds the palindrome matrix or decides impossibility. */
    private static class Solver {
        private final FastScanner in;
        private final OutputWriter out;

        Solver(FastScanner in, OutputWriter out) {
            this.in = in;
            this.out = out;
        }

        /** Entry point for the algorithm. */
        void solve() throws IOException {
            int a = in.nextInt();                     // size of the matrix
            int total = a * a;                         // number of values to read
            Map<Integer, Integer> freq = new HashMap<>();

            // -----------------------------------------------------------------
            // 1️⃣ Read all numbers and count their frequencies
            // -----------------------------------------------------------------
            for (int i = 0; i < total; i++) {
                int v = in.nextInt();
                freq.merge(v, 1, Integer::sum);
            }

            int[][] matrix = new int[a][a];
            boolean possible = true;

            // -----------------------------------------------------------------
            // 2️⃣ Even side length – every value must appear a multiple of 4
            // -----------------------------------------------------------------
            if (a % 2 == 0) {
                possible = frequenciesDivisibleBy(freq, 4);
                if (possible) fillEvenMatrix(matrix, freq, 4);
            }
            // -----------------------------------------------------------------
            // 3️⃣ Odd side length – exactly one value may have odd count,
            //    the rest must be split into groups of 4 and 2.
            // -----------------------------------------------------------------
            else {
                possible = fillOddMatrix(matrix, freq);
            }

            // -----------------------------------------------------------------
            // 4️⃣ Output
            // -----------------------------------------------------------------
            if (!possible) {
                out.print("NO");
            } else {
                out.println("YES");
                out.printMatrix(matrix);
            }
            out.flush();
        }

        /** Helper: check that every entry in the map has a count divisible by d. */
        private static boolean frequenciesDivisibleBy(Map<Integer, Integer> freq, int d) {
            for (int count : freq.values()) {
                if (count % d != 0) return false;
            }
            return true;
        }

        /** Fill matrix for even side length using groups of 4 symmetric cells. */
        private void fillEvenMatrix(int[][] matrix, Map<Integer, Integer> freq, int groupSize) {
            // Process cells in the top‑left quadrant; each placement touches
            // exactly four symmetric positions.
            for (int r = 0; r < a; r++) {
                for (int c = 0; c < a; c++) {
                    if (matrix[r][c] != 0) continue;                 // already filled

                    int val = firstKeyWithPositiveCount(freq);
                    // Assign to the four symmetric cells
                    matrix[r][c]                 = val;
                    matrix[a - r - 1][c]         = val;
                    matrix[r][a - c - 1]         = val;
                    matrix[a - r - 1][a - c - 1] = val;

                    // Update frequency map
                    int newCount = freq.get(val) - groupSize;
                    if (newCount == 0) freq.remove(val);
                    else freq.put(val, newCount);
                }
            }
        }

        /** Helper: retrieve a key with a positive value in the frequency map. */
        private int firstKeyWithPositiveCount(Map<Integer, Integer> freq) {
            for (Map.Entry<Integer, Integer> e : freq.entrySet()) {
                if (e.getValue() > 0) return e.getKey();
            }
            throw new IllegalStateException("No positive count left");
        }

        /**
         * Fill matrix for odd side length.
         *
         * <p>
         *   - Exactly one value must have an odd count (it becomes the centre).
         *   - The remaining counts must be able to supply {@code a} pairs of
         *     “double‑cells” (remainder 2 when divided by 4) and an even number of
         *     such pairs.
         *   - After placing the centre, the algorithm distributes the remaining
         *     values symmetrically.
         * </p>
         */
        private boolean fillOddMatrix(int[][] matrix, Map<Integer, Integer> freq) {
            // -------------------------------------------------------------
            // 1️⃣ Locate the unique value with an odd frequency (if any)
            // -------------------------------------------------------------
            int centreKey = -1;
            int oddCount = 0;
            for (Map.Entry<Integer, Integer> e : freq.entrySet()) {
                if ((e.getValue() & 1) == 1) {
                    centreKey = e.getKey();
                    oddCount++;
                }
            }
            if (oddCount != 1) return false;

            // Place the centre element
            int mid = a / 2;
            matrix[mid][mid] = centreKey;
            decrementOrRemove(freq, centreKey, 1);

            // -------------------------------------------------------------
            // 2️⃣ Collect values whose remaining count ≡ 2 (mod 4)
            // -------------------------------------------------------------
            Map<Integer, Integer> doublePairs = new HashMap<>();
            for (Map.Entry<Integer, Integer> e : freq.entrySet()) {
                if (e.getValue() % 4 == 2) doublePairs.put(e.getKey(), e.getValue());
            }
            if (doublePairs.size() < a || doublePairs.size() % 2 != 0) return false;

            // -------------------------------------------------------------
            // 3️⃣ Fill the middle row & column (excluding the centre)
            // -------------------------------------------------------------
            TreeMap<Integer, Integer> ordered = new TreeMap<>(freq);
            for (int i = 0; i < a; i++) {
                if (fillSymmetricPosition(matrix, ordered, doublePairs, true, mid, mid, 2)) break;
            }
            for (int j = 0; j < a; j++) {
                if (fillSymmetricPosition(matrix, ordered, doublePairs, true, mid, j, 2)) break;
            }

            // -------------------------------------------------------------
            // 4️⃣ Fill the remaining cells with groups of four
            // -------------------------------------------------------------
            for (int r = 0; r < a; r++) {
                for (int c = 0; c < a; c++) {
                    if (matrix[r][c] != 0) continue;
                    int val = ordered.firstKey();
                    fillFourSymmetric(matrix, val, r, c);
                    decrementOrRemove(ordered, val, 4);
                }
            }
            return true;
        }

        /**
         * Places a value at position (r, c) and its three symmetric counterparts.
         */
        private void fillFourSymmetric(int[][] matrix, int val, int r, int c) {
            int a = matrix.length;
            matrix[r][c]                 = val;
            matrix[a - r - 1][c]         = val;
            matrix[r][a - c - 1]         = val;
            matrix[a - r - 1][a - c - 1] = val;
        }

        /**
         * Attempts to place a value from {@code doublePairs} at a given
         * symmetric position. Returns {@code true} when a placement succeeded.
         */
        private boolean fillSymmetricPosition(int[][] matrix,
                                                TreeMap<Integer, Integer> ordered,
                                                Map<Integer, Integer> doublePairs,
                                                boolean firstAttempt,
                                                int r,
                                                int c,
                                                int decrement) throws IllegalStateException {
            if (matrix[r][c] != 0) return false;

            // Initialise {@code doublePairs} lazily on the first call
            if (firstAttempt) {
                // Ensure {@code doublePairs} contains a fresh entry for the key we are about to use
                doublePairs.clear();
                for (Map.Entry<Integer, Integer> e : ordered.entrySet()) {
                    if (e.getValue() % 4 == 2) {
                        doublePairs.put(e.getKey(), e.getValue());
                    }
                }
                if (doublePairs.isEmpty()) return false;
            }

            int key = doublePairs.firstKey();
            matrix[r][c]                 = key;
            matrix[matrix.length - r - 1][c] = key;
            matrix[r][matrix.length - c - 1] = key;
            matrix[matrix.length - r - 1][matrix.length - c - 1] = key;

            int newCount = doublePairs.get(key) - decrement;
            if (newCount == 0) doublePairs.remove(key);
            else doublePairs.put(key, newCount);
            return true;
        }

        /**
         * Decrements the count of {@code key} in {@code map} and removes the entry
         * when the count reaches zero.
         */
        private void decrementOrRemove(Map<Integer, Integer> map, int key, int by) {
            int newCount = map.get(key) - by;
            if (newCount == 0) map.remove(key);
            else map.put(key, newCount);
        }
    }

    /** Program entry point. */
    public static void main(String[] args) throws IOException {
        FastScanner scanner = new FastScanner(System.in);
        OutputWriter writer = new OutputWriter(new PrintWriter(System.out, true));
        new Solver(scanner, writer).solve();
    }
}

import java.io.*;
import java.util.*;

/**
 * Fast scanner based on {@link BufferedInputStream}.
 */
final class FastScanner {
    private final InputStream in;
    private final byte[] buffer = new byte[1 << 16];
    private int ptr = 0, len = 0;

    FastScanner(InputStream in) {
        this.in = in;
    }

    private int readByte() throws IOException {
        if (ptr >= len) {
            len = in.read(buffer);
            ptr = 0;
            if (len <= 0) return -1;
        }
        return buffer[ptr++];
    }

    private static boolean isSpace(int c) {
        return c == ' ' || c == '\n' || c == '\r' || c == '\t';
    }

    /** Reads the next signed 32‑bit integer. */
    int nextInt() throws IOException {
        int c;
        do {
            c = readByte();
        } while (c <= ' ' && c != -1);

        boolean neg = false;
        if (c == '-') {
            neg = true;
            c = readByte();
        }

        int value = 0;
        do {
            if (c < '0' || c > '9') throw new InputMismatchException();
            value = value * 10 + (c - '0');
            c = readByte();
        } while (!isSpace(c));

        return neg ? -value : value;
    }
}

/**
 * Utility class that builds a magic square from the supplied frequencies.
 */
final class MagicSquareBuilder {

    private MagicSquareBuilder() { }

    /**
     * Attempts to construct a magic square of size {@code n} using the supplied frequencies.
     *
     * @param n size of the square
     * @param freq frequency map of distinct values (value → occurrences)
     * @return an {@link Optional} containing the square if construction succeeds,
     *         otherwise empty
     */
    static Optional<int[][]> build(int n, Map<Integer, Integer> freq) {
        int[][] square = new int[n][n];

        if (n % 2 == 0) {
            return buildEvenSquare(n, freq, square);
        } else {
            return buildOddSquare(n, freq, square);
        }
    }

    private static Optional<int[][]> buildEvenSquare(int n, Map<Integer, Integer> freq, int[][] square) {
        int col = 0;
        int row = 0;
        final int half = n / 2;

        for (Map.Entry<Integer, Integer> entry : freq.entrySet()) {
            int value = entry.getKey();
            int count = entry.getValue();

            if (count % 4 != 0) {
                return Optional.empty(); // even size requires frequencies that are multiples of 4
            }

            int placed = 0;
            while (placed < count) {
                if (row >= n) {
                    return Optional.empty(); // ran out of rows
                }

                // Fill the four symmetric cells
                square[row][col] = value;
                square[row][n - col - 1] = value;
                square[n - row - 1][n - col - 1] = value;
                square[n - row - 1][col] = value;

                placed += 4;

                // Advance to the next slot in row‑major order but stop before the middle column
                if (col == half - 1) {
                    row++;
                    col = 0;
                } else {
                    col++;
                }
            }
        }
        return Optional.of(square);
    }

    private static Optional<int[][]> buildOddSquare(int n, Map<Integer, Integer> freq, int[][] square) {
        final int half = n / 2;
        int centreRow = half;
        int centreCol = half;

        // The centre cell must be filled by a value that appears an odd number of times.
        int centreValue = -1;
        for (Map.Entry<Integer, Integer> e : freq.entrySet()) {
            if (e.getValue() % 2 == 1) {
                centreValue = e.getKey();
                break;
            }
        }
        if (centreValue == -1) {
            return Optional.empty(); // no odd‑frequency element → impossible
        }

        // Place the centre element.
        square[centreRow][centreCol] = centreValue;
        freq.put(centreValue, freq.get(centreValue) - 1);
        if (freq.get(centreValue) == 0) {
            freq.remove(centreValue);
        }

        // Variables used for placing symmetric pairs.
        boolean upPhase = false; // true → filling symmetric pairs on the middle row (vertical symmetry)
        int pointer = 0; // column index when filling horizontally / vertically

        for (Map.Entry<Integer, Integer> entry : freq.entrySet()) {
            int value = entry.getKey();
            int count = entry.getValue();

            // Even counts that are not multiples of 4 are not allowed for odd n.
            if (count % 2 == 0 && count != 0 && count % 4 != 0) {
                return Optional.empty();
            }

            // Values that appear a multiple of 4 are placed in 4‑symmetrical blocks.
            if (count % 4 == 0) {
                int blocks = count / 4;
                int r = 0;
                int c = 0;
                while (blocks-- > 0) {
                    if (r >= n) {
                        return Optional.empty();
                    }
                    square[r][c] = value;
                    square[r][n - c - 1] = value;
                    square[n - r - 1][n - c - 1] = value;
                    square[n - r - 1][c] = value;

                    // Advance in the same sweeping order used for the even case.
                    if (c == half - 1) {
                        r++;
                        c = 0;
                    } else {
                        c++;
                    }
                }
                continue;
            }

            // Remaining odd counts are placed in symmetric pairs along the middle row / column.
            int pairs = count / 2;
            if (pairs == 0) {
                continue; // count was 0 or 1 (already handled)
            }

            if (!upPhase) {
                // First phase – fill symmetric positions on the middle row.
                for (int i = 0; i < pairs; i++) {
                    square[pointer][half] = value;
                    square[n - pointer - 1][half] = value;
                    pointer++;
                }
                upPhase = true; // switch to second phase
            } else {
                // Second phase – fill symmetric positions on the middle column.
                if (pointer >= half) {
                    return Optional.empty(); // out of slots
                }
                for (int i = 0; i < pairs; i++) {
                    square[half][pointer] = value;
                    square[half][n - pointer - 1] = value;
                    pointer++;
                }
            }
        }
        return Optional.of(square);
    }
}

/**
 * Main driver – parses input, builds the magic square and prints the outcome.
 */
public class Main {
    public static void main(String[] args) throws IOException {
        try (PrintWriter out = new PrintWriter(System.out)) {
            FastScanner sc = new FastScanner(System.in);
            int n = sc.nextInt();
            int[] values = new int[n * n];
            for (int i = 0; i < values.length; i++) {
                values[i] = sc.nextInt();
            }

            Map<Integer, Integer> frequency = countFrequencies(values);
            Optional<int[][]> optSquare = MagicSquareBuilder.build(n, new HashMap<>(frequency));

            if (optSquare.isEmpty()) {
                out.println("NO");
                return;
            }

            out.println("YES");
            int[][] square = optSquare.get();
            for (int[] row : square) {
                for (int i = 0; i < row.length; i++) {
                    out.print(row[i]);
                    if (i + 1 < row.length) out.print(' ');
                }
                out.println();
            }
        }
    }

    private static Map<Integer, Integer> countFrequencies(int[] arr) {
        Map<Integer, Integer> map = new HashMap<>();
        for (int v : arr) {
            map.merge(v, 1, Integer::sum);
        }
        return map;
    }
}

import java.io.*;
import java.util.*;

public class Main {

    private static final PrintWriter OUT;
    private static final FastScanner FS;

    static {
        try {
            OUT = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)));
        } catch (Exception e) {
            throw new RuntimeException(e);
        }
        FS = new FastScanner(System.in);
    }

    public static void main(String[] args) throws Exception {
        int n = FS.nextInt();

        // frequency of each value (1 … 1000)
        final int MAX_VAL = 1001;
        int[] freq = new int[MAX_VAL];

        // read n*n numbers
        for (int i = 0; i < n * n; i++) {
            int v = FS.nextInt();
            if (v >= 1 && v < MAX_VAL) {
                freq[v]++;
            }
        }

        int[][] ans = new int[n][n];
        fillWith(ans, -1);

        // ---------- fill the four symmetric corners ----------
        for (int r = 0; r < n / 2; r++) {
            for (int c = 0; c < n / 2; c++) {
                int val = selectValue(freq, 4);
                if (val == -1) {
                    println("NO");
                    return;
                }
                placeSymmetric(ans, r, c, n, val);
                freq[val] -= 4;
            }
        }

        // ---------- handle the middle cross when n is odd ----------
        if (n % 2 == 1) {
            int mid = n / 2;

            // middle row (excluding the centre cell)
            for (int c = 0; c < mid; c++) {
                int val = selectValue(freq, 2);
                if (val == -1) {
                    println("NO");
                    return;
                }
                ans[mid][c] = val;
                ans[mid][n - 1 - c] = val;
                freq[val] -= 2;
            }

            // middle column (excluding the centre cell)
            for (int r = 0; r < mid; r++) {
                int val = selectValue(freq, 2);
                if (val == -1) {
                    println("NO");
                    return;
                }
                ans[r][mid] = val;
                ans[n - 1 - r][mid] = val;
                freq[val] -= 2;
            }

            // centre cell
            int val = selectValue(freq, 1);
            if (val == -1) {
                println("NO");
                return;
            }
            ans[mid][mid] = val;
            freq[val] -= 1;
        }

        // ---------- solution found ----------
        println("YES");
        printMatrix(ans);
        OUT.close();
    }

    /** Places the same value at the four symmetric positions referenced by (r,c). */
    private static void placeSymmetric(int[][] mat, int r, int c, int n, int value) {
        mat[r][c] = value;
        mat[r][n - 1 - c] = value;
        mat[n - 1 - r][c] = value;
        mat[n - 1 - r][n - 1 - c] = value;
    }

    /** Returns the first value whose remaining frequency is at least `min`, or -1 if none. */
    private static int selectValue(int[] freq, int min) {
        for (int v = 1; v < freq.length; v++) {
            if (freq[v] >= min) {
                return v;
            }
        }
        return -1;
    }

    /** Fills the whole matrix with the supplied initial value. */
    private static void fillWith(int[][] mat, int init) {
        for (int[] row : mat) {
            Arrays.fill(row, init);
        }
    }

    /** Prints the matrix to STDOUT using the global PrintWriter. */
    private static void printMatrix(int[][] mat) {
        for (int[] row : mat) {
            for (int cell : row) {
                OUT.print(cell);
                OUT.print(' ');
            }
            OUT.println();
        }
    }

    /** Fast scanner that works with the original tokenisation logic. */
    public static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
            st = new StringTokenizer("");
        }

        String next() throws IOException {
            while (!st.hasMoreTokens()) {
                st = new StringTokenizer(br.readLine());
            }
            return st.nextToken();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }

        long nextLong() throws IOException {
            return Long.parseLong(next());
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Reads an integer matrix size `n` and a list of `n·n` numbers,
 * then prints a possible “beautiful” matrix or the word “NO”.
 * The refactor focuses on readability, clear naming and separation
 * of concerns (input, validation, construction, output).
 */
public class MatrixConstructor {

    /** Maximum value that can appear in the input (as per the original code). */
    private static final int MAX_VAL = 1000;

    /** Entry point – delegates all work to an instance method for easier testing. */
    public static void main(String[] args) throws Exception {
        new MatrixConstructor().run();
    }

    /** Main driver – parses input, validates feasibility, builds and prints the matrix. */
    private void run() throws Exception {
        FastScanner fs = new FastScanner();
        PrintWriter out = new PrintWriter(System.out);

        int n = fs.nextInt();                     // matrix dimension
        int[] frequency = readCounts(fs, n);      // counts of each value

        if (n % 2 == 0) {
            if (!canBuildEvenMatrix(frequency, n)) {
                out.println("NO");
                return;
            }
            int[][] matrix = buildEvenMatrix(frequency, n);
            out.println("YES");
            printMatrix(matrix, out);
        } else {
            if (!canBuildOddMatrix(frequency, n)) {
                out.println("NO");
                return;
            }
            int[][] matrix = buildOddMatrix(frequency, n);
            out.println("YES");
            printMatrix(matrix, out);
        }

        out.flush();
    }

    /** Reads `n·n` integers from the scanner and stores their frequencies. */
    private int[] readCounts(FastScanner fs, int n) {
        int[] freq = new int[MAX_VAL + 1];
        for (int i = 0; i < n * n; i++) {
            freq[fs.nextInt()]++;
        }
        return freq;
    }

    /* ------------------------------------------------------------- *
     *                     EVEN‑SIZE MATRIX LOGIC                    *
     * ------------------------------------------------------------- */

    /** Checks whether an even‑sized matrix can be built (all counts must be multiples of 4). */
    private boolean canBuildEvenMatrix(int[] freq, int n) {
        for (int v : freq) {
            if (v % 4 != 0) {
                return false;
            }
        }
        return true;
    }

    /** Constructs a valid even‑sized matrix. */
    private int[][] buildEvenMatrix(int[] freq, int n) {
        int[][] mat = new int[n][n];
        final int quadrantSize = n / 2;          // size of one quarter of the matrix
        int placed = 0;                            // how many groups of four have been placed

        for (int value = 0; value <= MAX_VAL; value++) {
            int groupsOfFour = freq[value] / 4;
            for (int g = 0; g < groupsOfFour; g++) {
                int r = placed / quadrantSize;
                int c = placed % quadrantSize;
                fillSymmetric(mat, n, r, c, value);
                placed++;
            }
        }
        return mat;
    }

    /** Stores `value` in the four cells that are symmetric with respect to the matrix centre. */
    private void fillSymmetric(int[][] mat, int n, int r, int c, int value) {
        mat[r][c] = mat[n - 1 - r][c] = mat[r][n - 1 - c] = mat[n - 1 - r][n - 1 - c] = value;
    }

    /* ------------------------------------------------------------- *
     *                     ODD‑SIZE MATRIX LOGIC                    *
     * ------------------------------------------------------------- */

    /** Checks whether an odd‑sized matrix can be built (exactly one value must have an odd count). */
    private boolean canBuildOddMatrix(int[] freq, int n) {
        int oddCount = 0;
        for (int v : freq) {
            if (v % 2 == 1) {
                oddCount++;
            }
        }
        return oddCount == 1;                     // only one centre cell may have an odd count
    }

    /** Constructs a valid odd‑sized matrix. */
    private int[][] buildOddMatrix(int[] freq, int n) {
        int[][] mat = new int[n][n];

        // -----------------------------------------------------------------
        // 1️⃣ Classify the remaining frequencies:
        //    • singles – odd count (must be exactly one, used for the centre)
        //    • pairs   – count % 4 == 2  (need to be placed on the centre row/column)
        //    • fours   – count % 4 == 0  (will fill the four quadrants)
        // -----------------------------------------------------------------
        List<Integer> singles = new ArrayList<>();
        List<Integer> pairs   = new ArrayList<>();
        List<Integer> fours   = new ArrayList<>();

        for (int v = 0; v <= MAX_VAL; v++) {
            if (freq[v] == 0) continue;
            if (freq[v] % 2 == 1) {
                singles.add(v);
            } else if (freq[v] % 4 == 0) {
                fours.add(v);
            } else {
                pairs.add(v);                     // remainder is 2 (mod 4)
            }
        }

        if (singles.size() != 1) {
            // This should never happen if `canBuildOddMatrix` was called first,
            // but we keep the guard for safety.
            throw new IllegalStateException("Invalid input: more than one odd frequency.");
        }

        // ---- place the unique centre value ---------------------------------
        int centre = singles.remove(0);
        mat[n / 2][n / 2] = centre;
        freq[centre]--;                             // one occurrence used

        // After removing the centre cell the remaining counts may change class.
        reclassify(freq, singles, pairs, fours);

        int side = (n - 1) / 2;                     // number of cells on each side of the centre line

        // ---- fill the middle row (excluding the centre cell) -----------------
        for (int i = 0; i < side; i++) {
            if (!pairs.isEmpty()) {
                int val = pairs.remove(0);
                mat[n / 2][i] = mat[n / 2][n - 1 - i] = val;
                freq[val] -= 2;
            } else {
                int val = fours.remove(0);
                pairs.add(val);
                mat[n / 2][i] = mat[n / 2][n - 1 - i] = val;
                freq[val] -= 2;
            }
            reclassify(freq, singles, pairs, fours);
        }

        // ---- fill the middle column (excluding the centre cell) -------------
        for (int i = 0; i < side; i++) {
            if (!pairs.isEmpty()) {
                int val = pairs.remove(0);
                mat[i][n / 2] = mat[n - 1 - i][n / 2] = val;
                freq[val] -= 2;
            } else {
                int val = fours.remove(0);
                pairs.add(val);
                mat[i][n / 2] = mat[n - 1 - i][n / 2] = val;
                freq[val] -= 2;
            }
            reclassify(freq, singles, pairs, fours);
        }

        // At this point there must be no “pair” left; otherwise the construction failed.
        if (!pairs.isEmpty()) {
            throw new IllegalStateException("Construction failed: leftover pair values.");
        }

        // ---- fill the four quadrants with the remaining “four‑multiple” values --
        int placedInQuadrant = 0;
        int quadrantDim = n / 2;                  // size of one quarter
        for (int value : fours) {
            int groups = freq[value] / 4;
            for (int g = 0; g < groups; g++) {
                int r = placedInQuadrant / quadrantDim;
                int c = placedInQuadrant % quadrantDim;
                fillSymmetric(mat, n, r, c, value);
                placedInQuadrant++;
            }
        }

        return mat;
    }

    /** Re‑assigns the three helper lists (`singles`, `pairs`, `fours`) according to current frequencies. */
    private void reclassify(int[] freq,
                            List<Integer> singles,
                            List<Integer> pairs,
                            List<Integer> fours) {
        singles.clear();
        pairs.clear();
        fours.clear();

        for (int v = 0; v <= MAX_VAL; v++) {
            if (freq[v] == 0) continue;
            if (freq[v] % 2 == 1) {
                singles.add(v);
            } else if (freq[v] % 4 == 0) {
                fours.add(v);
            } else {
                pairs.add(v);
            }
        }
    }

    /** Simple helper to print a matrix to the output stream. */
    private void printMatrix(int[][] mat, PrintWriter out) {
        for (int[] row : mat) {
            for (int cell : row) {
                out.print(cell + " ");
            }
            out.println();
        }
    }

    /* ------------------------------------------------------------- *
     *                         FAST INPUT HELPER                    *
     * ------------------------------------------------------------- */

    /**
     * Fast scanner that tokenises lines from {@code System.in}.
     * Keeps the original behaviour of the provided code but with clearer
     * method names.
     */
    static class FastScanner {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        FastScanner() {
            reader = new BufferedReader(new InputStreamReader(System.in));
            tokenizer = null;
        }

        /** Returns the next token, reading a new line if necessary. */
        private String nextToken() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        /** Convenience wrappers for primitive types. */
        int nextInt() { return Integer.parseInt(nextToken()); }

        long nextLong() { return Long.parseLong(nextToken()); }

        double nextDouble() { return Double.parseDouble(nextToken()); }

        String nextLine() {
            try {
                return reader.readLine();
            } catch (IOException e) {
                throw new RuntimeException(e);
            }
        }
    }
}

import java.io.*;
import java.util.*;

public class Solution {

    /* ----------  Constants & I/O utilities  ---------- */
    private static final long MOD = 1_000_000_007L;

    /** Fast scanner that reads tokens from stdin using a reusable byte buffer. */
    private static final class FastScanner {
        private final InputStream stream;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream stream) {
            this.stream = stream;
        }

        private int readByte() throws IOException {
            if (len == -1) throw new InputMismatchException();
            if (ptr >= len) {
                ptr = 0;
                len = stream.read(buffer);
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        /** Skip leading whitespace. */
        private int skip() throws IOException {
            int b;
            do {
                b = readByte();
            } while (!isSpaceChar(b));
            return b;
        }

        /** @return true if the character is a whitespace (space, newline, etc.). */
        private boolean isSpaceChar(int c) {
            return !(c >= 33 && c <= 126);
        }

        /** Reads next signed integer. */
        int nextInt() throws IOException {
            int c = skip();
            boolean negative = false;
            if (c == '-') {
                negative = true;
                c = readByte();
            }
            int value = 0;
            while (c >= '0' && c <= '9') {
                value = value * 10 + (c - '0');
                c = readByte();
            }
            return negative ? -value : value;
        }
    }

    /* ----------  Core algorithm helpers  ---------- */

    /** Extracts a number that appears at least five times (used for 4‑cell blocks). */
    private static int allocateBlock(int[] counts) {
        for (int v = 0; v <= 1000; ++v) {
            if (counts[v] >= 4) {
                counts[v] -= 4;
                return v;
            }
        }
        return 0;                 // should never happen for valid input
    }

    /** Extracts a number that appears at least twice (used for 2‑cell blocks). */
    private static int allocatePair(int[] counts) {
        for (int v = 0; v <= 1000; ++v) {
            if (counts[v] >= 2) {
                counts[v] -= 2;
                return v;
            }
        }
        return 0;
    }

    /* ----------  Main solving routine  ---------- */
    private static final class Solver {
        private final FastScanner fs;
        private final PrintWriter out;
        private static final int MAX_VAL = 1_001;   // values are stored up to index 1000

        Solver(FastScanner fs, PrintWriter out) {
            this.fs = fs;
            this.out = out;
        }

        /** Executes one test case (the original program only processes a single case). */
        void solve() {
            int n = fs.nextInt();                     // dimension of the square matrix
            int[] freq = new int[MAX_VAL];            // frequency of each value (0‑based)

            int totalElements = n * n;
            for (int i = 0; i < totalElements; ++i) {
                int val = fs.nextInt();
                freq[val]++;
            }

            int[][] matrix = new int[n][n];

            /* ----------  Center handling for odd n  ---------- */
            if (n % 2 == 1) {
                if (freq[MAX_VAL / 2] % 2 == 1) {      // we need exactly one value with odd count
                    matrix[n / 2][n / 2] = MAX_VAL / 2;
                    freq[MAX_VAL / 2]--;
                }
            }

            /* ----------  Even dimension validation  ---------- */
            if (n % 2 == 0) {
                for (int v = 0; v < MAX_VAL; ++v) {
                    if (freq[v] % 4 != 0) {
                        out.println("NO");
                        return;
                    }
                }
            } else {
                /* ----------  Odd dimension validation  ---------- */
                int half = n / 2;
                long totalQuadrants = (long) half * half;               // how many 4‑cell blocks we need
                int oddPairs = 0;
                long evenPairs = 0;                                        // count of values that contribute 2 cells (mod 4 == 2)

                for (int v = 0; v < MAX_VAL; ++v) {
                    totalQuadrants += freq[v] / 4;
                    if ((freq[v] % 4) == 2) {
                        oddPairs++;
                    }
                }

                /* Checks that we have enough material to fill the required quadrants
                   and that the parity constraints are satisfied. */
                if (totalQuadrants < half * half || oddPairs + 2 * (totalQuadrants - half * half) != n) {
                    out.println("NO");
                    return;
                }

                for (int v = 0; v < MAX_VAL; ++v) {
                    if (freq[v] % 2 != 0) {          // every remaining count must be even
                        out.println("NO");
                        return;
                    }
                    if ((freq[v] % 4) == 2) {
                        oddPairs++;                 // count how many values contribute a 2‑cell pair
                    }
                }

                if (oddPairs >= n) {               // far too many 2‑cell pairs → impossible layout
                    out.println("NO");
                    return;
                }
            }

            /* ----------  Fill symmetric quadrants  ---------- */
            for (int row = 0; row < n / 2; ++row) {
                for (int col = 0; col < n / 2; ++col) {
                    int id = allocateBlock(freq);
                    placeSymmetric(matrix, row, col, id);
                }
            }

            /* ----------  Fill the middle row / column when n is odd  ---------- */
            if (n % 2 == 1) {
                int mid = n / 2;
                for (int i = 0; i < n / 2; ++i) {
                    int id = allocatePair(freq);
                    matrix[mid][i] = matrix[mid][n - i - 1] = id;
                    matrix[i][mid] = matrix[n - i - 1][mid] = id;
                }
            }

            /* ----------  Output ---------- */
            out.println("YES");
            for (int i = 0; i < n; ++i) {
                for (int j = 0; j < n; ++j) {
                    out.print(matrix[i][j] + " ");
                }
                out.println();
            }
        }

        /** Places a value at the four symmetric positions of a perfect square. */
        private static void placeSymmetric(int[][] matrix, int r, int c, int value) {
            int n = matrix.length;
            matrix[r][c] = value;
            matrix[r][n - c - 1] = value;
            matrix[n - r - 1][c] = value;
            matrix[n - r - 1][n - c - 1] = value;
        }
    }

    /* ----------  Program entry point  ---------- */
    private final FastScanner fs = new FastScanner(System.in);
    private final PrintWriter out = new PrintWriter(System.out);

    void run() {
        /* The original code processes exactly one test case; loop kept for compatibility. */
        while (true) {
            Solver solver = new Solver(fs, out);
            solver.solve();
            break; // exactly one iteration – mirrors the original `while(t-- > 0)`
        }
        out.flush();
    }

    public static void main(String[] args) {
        new Solution().run();
    }
}

import java.io.*;
import java.util.*;

/**
 * Reads an N×N matrix of integers and tries to build a
 * 4‑way symmetric grid using the supplied numbers.
 *
 * The program follows the same logical algorithm as the original
 * implementation but is deliberately split into small, named methods,
 * uses clear naming, constants and proper error handling – all of
 * which improve maintainability and readability.
 */
public class Solution {

    /** Maximum value that can appear in the input. */
    private static final int MAX_VALUE = 1000;

    /** Number of times a value must be present to fill a cell of the top‑left quadrant. */
    private static final int QUADRANT_MULTIPLIER = 4;

    /** Number of times a value must be present to fill a cell of the middle row/column (odd N). */
    private static final int MIDDLE_MULTIPLIER = 2;

    /** Buffered reader for fast input and a PrintWriter that writes directly to stdout. */
    private static final BufferedReader INPUT = new BufferedReader(
            new InputStreamReader(System.in));
    private static final PrintWriter OUTPUT = new PrintWriter(System.out, true);

    /** Counter that tracks the remaining occurrences of each value (1 … MAX_VALUE). */
    private static final int[] freq = new int[MAX_VALUE + 1];

    /** The final grid that will be printed when a solution exists. */
    private static int[][] grid;

    public static void main(String[] args) {
        try {
            int[] data = readAllTokens();

            int n = data[0];
            int[] values = Arrays.copyOfRange(data, 1, 1 + n * n);

            // Initialise frequency table
            Arrays.fill(freq, 0);
            for (int v : values) {
                if (isValid(v)) {
                    freq[v]++;
                } else {
                    // Value out of allowed range → cannot be placed
                    OUTPUT.println("NO");
                    return;
                }
            }

            grid = new int[n][n];
            boolean success = buildSymmetricGrid(n);

            if (success) {
                OUTPUT.println("YES");
                printGrid();
            } else {
                OUTPUT.println("NO");
            }
        } catch (IOException e) {
            OUTPUT.println("Error reading input: " + e.getMessage());
        }
    }

    /** Reads all whitespace‑separated tokens from stdin and returns them as ints. */
    private static int[] readAllTokens() throws IOException {
        StringTokenizer st = new StringTokenizer(INPUT.readLine());
        int count = 0;
        while (st.hasMoreTokens()) count++;
        int[] tokens = new int[count];
        int idx = 0;
        st = new StringTokenizer(INPUT.readLine());
        while (st.hasMoreTokens()) {
            tokens[idx++] = Integer.parseInt(st.nextToken());
        }
        return tokens;
    }

    /** Checks if a value is inside the allowed range (1 … MAX_VALUE). */
    private static boolean isValid(int v) {
        return v >= 1 && v <= MAX_VALUE;
    }

    /**
     * Attempts to build a grid that satisfies the required symmetries.
     *
     * @param n size of the square grid
     * @return true if a grid can be constructed, false otherwise
     */
    private static boolean buildSymmetricGrid(int n) {
        if (n == 1) {
            // Trivial case – a single cell always works
            grid[0][0] = freq[valuesAt(0)];
            return true;
        }

        // -----------------------------------------------------------------
        // 1️⃣ Fill the top‑left quadrant (size ⌊n/2⌋ × ⌊n/2⌋)
        // -----------------------------------------------------------------
        int quadrantSize = n / 2;
        boolean quadrantFilled = fillQuadrant(quadrantSize);

        if (!quadrantFilled) {
            return false;
        }

        // Mirror the quadrant into the other three parts of the grid
        mirrorQuadrant(quadrantSize);

        // -----------------------------------------------------------------
        // 2️⃣ If N is odd we also need to fill the middle row/column
        // -----------------------------------------------------------------
        if (n % 2 == 1) {
            boolean middleFilled = fillMiddleRowAndColumn();
            if (!middleFilled) {
                return false;
            }

            // Finally place the centre cell (the only remaining unused value)
            placeCenterIfNeeded();
        }

        return true;
    }

    /** Fills the top‑left quadrant using values that appear at least QUADRANT_MULTIPLIER times. */
    private static boolean fillQuadrant(int size) {
        int nextAvailable = findNextAvailableValue(1);
        if (nextAvailable == -1) {
            return false; // No suitable value found
        }

        // Reserve QUADRANT_MULTIPLIER copies for each cell of the quadrant
        for (int i = 0; i < size; i++) {
            for (int j = 0; j < size; j++) {
                while (nextAvailable != -1 && freq[nextAvailable] < QUADRANT_MULTIPLIER) {
                    nextAvailable = findNextAvailableValue(nextAvailable + 1);
                }
                if (nextAvailable == -1) {
                    return false;
                }
                grid[i][j] = nextAvailable;
                freq[nextAvailable] -= QUADRANT_MULTIPLIER;
                nextAvailable = findNextAvailableValue(nextAvailable); // start from the next value
            }
        }
        return true;
    }

    /**
     * Finds the next value ≥ {@code start} whose remaining frequency is > 0.
     *
     * @param start value to start searching from (inclusive)
     * @return the first suitable value, or -1 if none exists
     */
    private static int findNextAvailableValue(int start) {
        for (int v = start; v <= MAX_VALUE; v++) {
            if (freq[v] > 0) {
                return v;
            }
        }
        return -1;
    }

    /** Mirrors the values placed in the top‑left quadrant to the other three quadrants. */
    private static void mirrorQuadrant(int size) {
        for (int i = 0; i < size; i++) {
            for (int j = 0; j < size; j++) {
                int val = grid[i][j];

                // Bottom‑right quadrant
                grid[n - 1 - i][n - 1 - j] = val;
                // Bottom‑left quadrant
                grid[n - 1 - i][j] = val;
                // Top‑right quadrant
                grid[i][n - 1 - j] = val;
            }
        }
    }

    /**
     * Fills the middle row and column when {@code n} is odd.
     *
     * @return true if both row and column could be filled, false otherwise
     */
    private static boolean fillMiddleRowAndColumn() {
        int mid = n / 2;

        // ----- Fill the middle row (horizontal symmetry) -----
        int next = findNextAvailableValue(1);
        if (next == -1) {
            return false;
        }
        for (int j = 0; j < n / 2; j++) {
            while (next != -1 && freq[next] < MIDDLE_MULTIPLIER) {
                next = findNextAvailableValue(next + 1);
            }
            if (next == -1) {
                return false;
            }
            grid[mid][j] = next;
            grid[mid][n - 1 - j] = next;
            freq[next] -= MIDDLE_MULTIPLIER;
            next = findNextAvailableValue(next);
        }

        // ----- Fill the middle column (vertical symmetry) -----
        next = findNextAvailableValue(1);
        if (next == -1) {
            return false;
        }
        for (int i = 0; i < n / 2; i++) {
            while (next != -1 && freq[next] < MIDDLE_MULTIPLIER) {
                next = findNextAvailableValue(next + 1);
            }
            if (next == -1) {
                return false;
            }
            grid[i][mid] = next;
            grid[n - 1 - i][mid] = next;
            freq[next] -= MIDDLE_MULTIPLIER;
            next = findNextAvailableValue(next);
        }

        return true;
    }

    /** Places the centre cell for odd N if a value is still left unused. */
    private static void placeCenterIfNeeded() {
        // At this point exactly one occurrence must remain.
        for (int v = 1; v <= MAX_VALUE; v++) {
            if (freq[v] == 1) {
                grid[n / 2][n / 2] = v;
                freq[v]--; // consume the last copy
                return;
            }
        }
        // If we get here the remaining count is not exactly 1 → impossible
        throw new IllegalStateException("Invalid remaining frequency when placing centre cell.");
    }

    /** Prints the constructed grid row‑by‑row. */
    private static void printGrid() {
        for (int i = 0; i < n; i++) {
            StringBuilder sb = new StringBuilder();
            for (int j = 0; j < n; j++) {
                sb.append(grid[i][j]).append(' ');
            }
            OUTPUT.println(sb.toString().trim());
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Fast scanner that reads tokens from {@link InputStream}.
 */
final class FastScanner {
    private final InputStream stream;
    private final byte[] buffer = new byte[8192];
    private int bufferPos = 0;
    private int bytesRead = -1;

    FastScanner(InputStream stream) {
        this.stream = Objects.requireNonNull(stream);
    }

    private int read() {
        if (bytesRead == -1) {
            throw new InputMismatchException();
        }
        if (bufferPos >= bytesRead) {
            bufferPos = 0;
            bytesRead = stream.read(buffer);
            if (bytesRead <= 0) {
                return -1;
            }
        }
        return buffer[bufferPos++];
    }

    /** Skips whitespace characters. */
    private int skipWhitespace(int c) {
        while (c != -1 && Character.isWhitespace(c)) {
            c = read();
        }
        return c;
    }

    /** Reads the next token as an {@code int}. */
    int nextInt() {
        int c;
        do {
            c = read();
        } while (c != -1 && Character.isWhitespace(c));
        int sign = 1;
        if (c == '-') {
            sign = -1;
            c = read();
        }
        long val = 0;
        while (!Character.isWhitespace(c)) {
            val = val * 10 + (c - '0');
            c = read();
        }
        return (int) (sign * val);
    }

    /** Reads the next line (including spaces) as a {@code String}. */
    String nextLine() {
        StringBuilder sb = new StringBuilder();
        int c;
        do {
            c = read();
        } while (c == -1 || !Character.isWhitespace(c));
        do {
            sb.appendCodePoint(c);
            c = read();
        } while (c != -1 && !Character.isWhitespace(c));
        return sb.toString().trim();
    }

    /** Returns {@code true} if {@code c} is a whitespace character. */
    private static boolean isWhitespace(int c) {
        return c == ' ' || c == '\n' || c == '\r' || c == '\t';
    }
}

/**
 * Utility class that contains the logic for building the symmetric matrix.
 */
final class SymmetricMatrixBuilder {

    /** Returns a key whose frequency is at least {@code need}. */
    private static int findWithFreq(int[] freq, int need) {
        for (int i = 1; i <= 1000; i++) {
            if (freq[i] >= need) {
                return i;
            }
        }
        return -1;
    }

    /**
     * Attempts to fill the supplied matrix with the numbers that respect
     * the required frequencies. Returns {@code true} on success,
     * {@code false} if it is impossible.
     */
    static boolean fillMatrix(int n, int[] freq, int[][] matrix) {
        int half = n / 2;

        /* ---- Fill the four‑fold symmetric positions ------------------- */
        for (int i = 0; i < half; i++) {
            for (int j = 0; j < half; j++) {
                int value = findWithFreq(freq, 4);
                if (value == -1) {
                    return false;
                }
                matrix[i][j] = value;
                matrix[i][n - j - 1] = value;
                matrix[n - i - 1][j] = value;
                matrix[n - i - 1][n - j - 1] = value;
                freq[value] -= 4;
            }
        }

        /* ---- If n is odd, handle the central cross ------------------- */
        if (n % 2 == 1) {
            /* Horizontal & vertical middle line (two‑fold symmetry) */
            for (int i = 0; i < half; i++) {
                int value = findWithFreq(freq, 2);
                if (value == -1) {
                    return false;
                }
                matrix[i][half] = value;
                matrix[n - i - 1][half] = value;
                freq[value] -= 2;
            }

            for (int j = 0; j < half; j++) {
                int value = findWithFreq(freq, 2);
                if (value == -1) {
                    return false;
                }
                matrix[half][j] = value;
                matrix[half][n - j - 1] = value;
                freq[value] -= 2;
            }

            /* The very centre – one‑fold symmetry */
            int centre = findWithFreq(freq, 1);
            if (centre == -1) {
                return false;
            }
            matrix[half][half] = centre;
        }

        return true;
    }
}

/**
 * Main class – reads input, builds the matrix, and prints the result.
 */
public class Solution {

    public static void main(String[] args) throws Exception {
        FastScanner sc = new FastScanner(System.in);

        int n = sc.nextInt();
        String line = sc.nextLine();
        String[] tokens = line.trim().split("\\s+");

        if (tokens.length != n * n) {
            throw new IllegalStateException("Unexpected number of tokens.");
        }

        int[] values = new int[n * n];
        int[] frequency = new int[1001];

        for (int i = 0; i < n * n; i++) {
            int v = Integer.parseInt(tokens[i]);
            values[i] = v;
            if (v < 1 || v > 1000) {
                throw new IllegalArgumentException("Value out of supported range [1,1000].");
            }
            frequency[v]++;
        }

        int[][] matrix = new int[n][n];

        if (!SymmetricMatrixBuilder.fillMatrix(n, frequency, matrix)) {
            System.out.println("NO");
            return;
        }

        System.out.println("YES");
        for (int[] row : matrix) {
            for (int cell : row) {
                System.out.print(cell + " ");
            }
            System.out.println();
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Refactored version of the original FirstClass program.
 *
 * The program reads:
 *   1. an integer {@code n}
 *   2. {@code n * n} integers supplied on the next line (space‑separated)
 *
 * It tries to build an {@code n × n} matrix that satisfies the
 * symmetry requirements (groups of 4, 2 and possibly 1 cell).
 * If such a matrix can be built it prints {@code "YES"} followed by the
 * matrix, otherwise it prints {@code "NO"}.
 *
 * The refactor focuses on readability, proper resource handling and a
 * clear separation of concerns.
 */
public class FirstClass {

    public static void main(String[] args) throws IOException {
        // Use try‑with‑resources to guarantee stream closure
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
             PrintWriter out = new PrintWriter(System.out)) {

            // ---------------------------------------------------------
            // 1. Input parsing
            // ---------------------------------------------------------
            int n = Integer.parseInt(readAndTrim(br));
            String tokenLine = readLine(br);
            if (tokenLine == null) {
                out.println("NO");
                return;
            }

            StringTokenizer tokenizer = new StringTokenizer(tokenLine);
            List<Integer> values = new ArrayList<>(n * n);
            while (tokenizer.hasMoreTokens()) {
                values.add(Integer.parseInt(tokenizer.nextToken()));
            }

            if (values.size() != n * n) {
                // The original program silently ignored the mismatch;
                // we treat it as an invalid input.
                out.println("NO");
                return;
            }

            // ---------------------------------------------------------
            // 2. Frequency map of the supplied numbers
            // ---------------------------------------------------------
            Map<Integer, Integer> frequency = buildFrequencyMap(values);

            // ---------------------------------------------------------
            // 3. Determine how many groups of each size we need
            // ---------------------------------------------------------
            GroupCounts counts = computeRequiredGroups(n);

            // ---------------------------------------------------------
            // 4. Try to allocate numbers to each group
            // ---------------------------------------------------------
            Integer[][] matrix = new Integer[n][n];
            if (!populateMatrix(matrix, frequency, counts)) {
                out.println("NO");
                return;
            }

            // ---------------------------------------------------------
            // 5. Successful construction → print result
            // ---------------------------------------------------------
            out.println("YES");
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < n; j++) {
                    out.print(matrix[i][j] + (j == n - 1 ? "\n" : " "));
                }
            }
            out.flush();
        }
    }

    /* --------------------------------------------------------------------- */
    /* Helper methods                                                         */
    /* --------------------------------------------------------------------- */

    /** Reads a line, trims it and returns it (never {@code null}). */
    private static String readLine(BufferedReader br) throws IOException {
        String line = br.readLine();
        return line == null ? "" : line;
    }

    /** Reads a line, removes surrounding whitespace and returns it. */
    private static String readAndTrim(BufferedReader br) throws IOException {
        return readLine(br).trim();
    }

    /** Builds a {@code Map<Integer,Integer>} with the frequency of each value. */
    private static Map<Integer, Integer> buildFrequencyMap(List<Integer> values) {
        Map<Integer, Integer> map = new HashMap<>();
        for (int v : values) {
            map.merge(v, 1, Integer::sum);
        }
        return map;
    }

    /** Holds the numbers of groups that require 4, 2 and 1 cells. */
    private static final class GroupCounts {
        final int groupsOf4;   // required groups of 4 identical cells
        final int groupsOf2;   // required groups of 2 identical cells
        final int groupsOf1;   // required groups of 1 cell (only for odd n)

        GroupCounts(int groupsOf4, int groupsOf2, int groupsOf1) {
            this.groupsOf4 = groupsOf4;
            this.groupsOf2 = groupsOf2;
            this.groupsOf1 = groupsOf1;
        }
    }

    /** Computes the required group counts for a given matrix size {@code n}. */
    private static GroupCounts computeRequiredGroups(int n) {
        int half = n / 2;
        if (n % 2 == 0) {
            // Even size → only groups of 4
            return new GroupCounts(half * half, 0, 0);
        } else {
            // Odd size → groups of 4, groups of 2, and a single centre cell
            int inner = half;               // (n‑1)/2
            int groupsOf4 = inner * inner;
            int groupsOf2 = 2 * inner;       // n‑1
            int groupsOf1 = 1;
            return new GroupCounts(groupsOf4, groupsOf2, groupsOf1);
        }
    }

    /**
     * Finds the smallest key in {@code freq} whose count is at least {@code required}
     * and consumes the required amount from the map.
     *
     * @return the chosen key, or {@code null} if no such key exists.
     */
    private static Integer consumeSufficient(Map<Integer, Integer> freq, int required) {
        // Examine keys in ascending order – mimics the original “pick the smallest”.
        List<Integer> keys = new ArrayList<>(freq.keySet());
        Collections.sort(keys);
        for (int key : keys) {
            int count = freq.get(key);
            if (count >= required) {
                freq.put(key, count - required);
                if (freq.get(key) == 0) {
                    freq.remove(key);
                }
                return key;
            }
        }
        return null; // not enough of any number
    }

    /**
     * Assigns {@code value} to the four symmetric cells (i,j), (n‑1‑i,j),
     * (i,n‑1‑j) and (n‑1‑i,n‑1‑j).
     */
    private static void fillFour(int[][] mat, int i, int j, int value, int n) {
        mat[i][j] = value;
        mat[n - 1 - i][j] = value;
        mat[i][n - 1 - j] = value;
        mat[n - 1 - i][n - 1 - j] = value;
    }

    /**
     * Assigns {@code value} to a vertical pair of cells (i,j) and (n‑1‑i,j).
     */
    private static void fillVerticalPair(int[][] mat, int i, int j, int value, int n) {
        mat[i][j] = value;
        mat[n - 1 - i][j] = value;
    }

    /**
     * Assigns {@code value} to a horizontal pair of cells (i,j) and (i,n‑1‑j).
     */
    private static void fillHorizontalPair(int[][] mat, int i, int j, int value, int n) {
        mat[i][j] = value;
        mat[i][n - 1 - j] = value;
    }

    /**
     * Attempts to fill the matrix respecting the required group counts.
     *
     * @return {@code true} if the matrix could be completely filled,
     *         {@code false} otherwise.
     */
    private static boolean populateMatrix(Integer[][] mat,
                                            Map<Integer, Integer> freq,
                                            GroupCounts counts) {
        int n = mat.length;
        int half = n / 2;

        // ----- groups of size 4 -------------------------------------------------
        for (int i = 0; i < half; i++) {
            for (int j = 0; j < half; j++) {
                Integer val = consumeSufficient(freq, 4);
                if (val == null) {
                    return false;
                }
                fillFour(mat, i, j, val, n);
            }
        }

        // ----- odd size: centre cell -------------------------------------------
        if (n % 2 == 1 && counts.groupsOf1 > 0) {
            Integer centre = consumeSufficient(freq, 1);
            if (centre == null) {
                return false;
            }
            int mid = half;
            mat[mid][mid] = centre;
        }

        // ----- odd size: pairs on the middle row and column --------------------
        if (n % 2 == 1 && counts.groupsOf2 > 0) {
            int mid = half;
            for (int i = 0; i < half; i++) {
                Integer pairVal = consumeSufficient(freq, 2);
                if (pairVal == null) {
                    return false;
                }
                fillVerticalPair(mat, i, mid, pairVal, n);
                fillHorizontalPair(mat, mid, i, pairVal, n);
            }
        }

        return true;
    }
}

import java.io.*;
import java.util.*;

/**
 * Utility class that encapsulates all input‑reading logic.
 */
final class FastScanner {
    private final BufferedReader br;
    private StringTokenizer tokenizer;

    FastScanner(Reader reader) {
        this.br = new BufferedReader(reader);
    }

    /** Reads the next token as an {@code int}. */
    int nextInt() throws IOException {
        return Integer.parseInt(nextToken());
    }

    /** Reads the next token as a {@code long}. */
    long nextLong() throws IOException {
        return Long.parseLong(nextToken());
    }

    /** Reads all remaining integers from the current line (or several lines)
     *  until {@code count} values have been collected.
     *
     *  @return an array with exactly {@code count} integers
     */
    int[] readInts(int count) throws IOException {
        int[] values = new int[count];
        for (int i = 0; i < count; i++) {
            values[i] = nextInt();
        }
        return values;
    }

    /** Reads all remaining long values until {@code count} numbers are obtained. */
    long[] readLongs(int count) throws IOException {
        long[] values = new long[count];
        for (int i = 0; i < count; i++) {
            values[i] = nextLong();
        }
        return values;
    }

    /** Return the next complete token (skipping any whitespace). */
    private String nextToken() throws IOException {
        while (tokenizer == null || !tokenizer.hasMoreElements()) {
            String line = br.readLine();
            if (line == null) {
                return null; // EOF
            }
            tokenizer = new StringTokenizer(line);
        }
        return tokenizer.nextToken();
    }
}

/**
 * Core logic for constructing a symmetric square from the supplied numbers.
 */
final class SquareBuilder {

    private static final int MAX_VALUE = 1000; // problem constraint

    /** Handles the even‑size case (n is even). */
    static Result attemptEven(int n, int[] freq) {
        // All frequencies must be multiples of 4
        for (int v = 1; v <= MAX_VALUE; v++) {
            if (freq[v] % 4 != 0) {
                return Result.failure();
            }
        }

        // We have exactly (n/2)*(n/2) groups of four identical numbers.
        int needed = (n / 2) * (n / 2);
        List<Integer> groups = new ArrayList<>(needed);
        for (int v = 1; v <= MAX_VALUE; v++) {
            int repeat = freq[v] / 4;
            groups.addAll(Collections.nCopies(repeat, v));
        }
        // The list size is guaranteed to be exactly needed
        return Result.success(evenSquare(n, groups));
    }

    /** Handles the odd‑size case (n is odd). */
    static Result attemptOdd(int n, int[] freq) {
        int half = n / 2;
        int[][] board = new int[n][n];

        // 1️⃣ Fill the four symmetric corners with numbers appearing ≥4 times
        for (int i = 0; i < half; i++) {
            for (int j = 0; j < half; j++) {
                int candidate = findWithAtLeast(freq, 4);
                if (candidate == -1) {
                    return Result.failure();
                }
                freq[candidate] -= 4;
                board[i][j] = board[n - 1 - i][j] = board[i][n - 1 - j] = board[n - 1 - i][n - 1 - j] = candidate;
            }
        }

        // 2️⃣ Fill the central row (excluding the centre cell) – need numbers appearing ≥2 times
        for (int i = 0; i < half; i++) {
            int candidate = findWithAtLeast(freq, 2);
            if (candidate == -1) {
                return Result.failure();
            }
            freq[candidate] -= 2;
            board[half][i] = board[half][n - 1 - i] = candidate;
        }

        // 3️⃣ Fill the central column (excluding the centre cell) – need numbers appearing ≥2 times
        for (int i = 0; i < half; i++) {
            int candidate = findWithAtLeast(freq, 2);
            if (candidate == -1) {
                return Result.failure();
            }
            freq[candidate] -= 2;
            board[i][half] = board[n - 1 - i][half] = candidate;
        }

        // 4️⃣ finally, place the centre element (≥1 remaining)
        int centre = findWithAtLeast(freq, 1);
        if (centre == -1) {
            return Result.failure();
        }
        board[half][half] = centre;

        return Result.success(board);
    }

    /** Construct the even‑size square from the pre‑collected groups of four. */
    private static int[][] evenSquare(int n, List<Integer> groups) {
        int[][] ans = new int[n][n];
        int idx = 0;
        for (int i = 0; i < n / 2; i++) {
            for (int j = 0; j < n / 2; j++) {
                int v = groups.get(idx++);
                ans[i][j] = ans[n - 1 - i][j] = ans[i][n - 1 - j] = ans[n - 1 - i][n - 1 - j] = v;
            }
        }
        return ans;
    }

    /** Helper that returns the smallest value with frequency ≥ needed, or –1 if none. */
    private static int findWithAtLeast(int[] freq, int needed) {
        for (int v = 1; v <= MAX_VALUE; v++) {
            if (freq[v] >= needed) {
                return v;
            }
        }
        return -1;
    }

    /** Simple wrapper to indicate success / failure together with the built board. */
    enum Result {
        /** Failure – no valid board could be constructed. */
        FAILURE;

        /** Success – the built board is returned. */
        SUCCESS(int[][] board);

        final int[][] board;

        Result() {
            this.board = null;
        }

        Result(int[][] board) {
            this.board = board;
        }

        static Result failure() {
            return FAILURE;
        }
    }
}

/**
 * Main driver – reads input, decides which builder to use and prints the answer.
 */
public class Solution {

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(new InputStreamReader(System.in));

        // Original code expected exactly one test case; we keep that behaviour
        // but make it explicit.
        int testCaseCount = 1;                       // will be decremented once
        while (testCaseCount-- > 0) {
            solveOneCase(fs);
        }
    }

    /** Reads a single test case, solves it and prints the result. */
    private static void solveOneCase(FastScanner fs) throws IOException {
        int n = fs.nextInt();                     // size of the square (n × n)
        int[] values = fs.readInts(n * n);        // all numbers that must fill the square

        // Frequency array indexed from 1 (0 is unused)
        int[] freq = new int[SquareBuilder.MAX_VALUE + 1];
        for (int v : values) {
            if (v >= 1 && v <= SquareBuilder.MAX_VALUE) {
                freq[v]++;
            } else {
                // Numbers outside the allowed range cannot be used → impossible
                System.out.println("NO");
                return;
            }
        }

        if (n == 1) {
            // Trivial 1×1 square
            System.out.println("YES");
            System.out.println(values[0]);
            return;
        }

        if ((n & 1) == 0) {                         // even size
            SquareBuilder.Result res = SquareBuilder.attemptEven(n, freq);
            printResult(res);
        } else {                                    // odd size
            SquareBuilder.Result res = SquareBuilder.attemptOdd(n, freq);
            printResult(res);
        }
    }

    /** Prints “NO” for failure or “YES” followed by the board for success. */
    private static void printResult(SquareBuilder.Result res) {
        if (res == SquareBuilder.Result.FAILURE) {
            System.out.println("NO");
        } else {
            System.out.println("YES");
            int[][] board = res.board;
            for (int[] row : board) {
                String line = Arrays.stream(row)
                        .map(Object::toString)
                        .collect(Collectors.joining(" "));
                System.out.println(line);
            }
        }
    }
}

/*
 * Magic‑Square Builder
 *
 * The program reads an integer n and n·n integers.
 * It tries to arrange the integers into an n×n matrix that
 * respects the symmetry constraints described in the original
 * source.  If such an arrangement exists it prints
 *
 *      YES
 *      <matrix rows>
 *
 * otherwise it prints only
 *
 *      NO
 *
 * The implementation has been refactored to improve readability,
 * modularity and testability while preserving the original behaviour.
 */
import java.io.*;
import java.util.*;

public final class MagicSquareBuilder {

    /* --------------------------------------------------------------------- *
     *  Configuration constants
     * --------------------------------------------------------------------- */
    private static final long MOD = 1_000_000_007L;   // kept for compatibility
    private static final int BUCKET_SIZE = 1_010;    // enough for input values

    /* --------------------------------------------------------------------- *
     *  Core data holders
     * --------------------------------------------------------------------- */
    private final int n;                 // dimension of the square
    private final int[][] grid;          // result matrix
    private final int[] frequencies;    // frequency of each possible value

    /* --------------------------------------------------------------------- *
     *  Constructor
     * --------------------------------------------------------------------- */
    public MagicSquareBuilder(int n, int[] values) {
        this.n = n;
        this.grid = new int[n][n];
        this.frequencies = new int[BUCKET_SIZE];
        for (int v : values) {
            ++frequencies[v];
        }
    }

    /* --------------------------------------------------------------------- *
     *  Public entry point – decides the construction strategy
     * --------------------------------------------------------------------- */
    public Optional<String> buildSolution() {
        return (n % 2 == 0) ? buildEvenOrder() : buildOddOrder();
    }

    /* --------------------------------------------------------------------- *
     *  Even‑order construction (n is even)
     * --------------------------------------------------------------------- */
    private Optional<String> buildEvenOrder() {
        // Every value must occur a multiple of 4 times.
        for (int v = 0; v < BUCKET_SIZE; v++) {
            if (frequencies[v] % 4 != 0) {
                return Optional.of("NO");
            }
        }
        fillEvenSquare();
        return Optional.of(formatOutput());
    }

    private void fillEvenSquare() {
        int placedBlocks = 0;
        for (int value = 0; value < BUCKET_SIZE; value++) {
            while (frequencies[value] == 0) {
                value++;
            }
            // A value is placed in 2×2 blocks that fill the whole matrix.
            for (int blockRow = 0; blockRow < n / 2; blockRow++) {
                for (int blockCol = 0; blockCol < n / 2; blockCol++) {
                    if (frequencies[value] == 0) {
                        break;
                    }
                    // Place the four symmetric copies of the value.
                    grid[blockRow][blockCol] = value;
                    grid[n - 1 - blockRow][blockCol] = value;
                    grid[blockRow][n - 1 - blockCol] = value;
                    grid[n - 1 - blockRow][n - 1 - blockCol] = value;
                    frequencies[value] -= 4;
                    placedBlocks++;
                }
            }
        }
    }

    /* --------------------------------------------------------------------- *
     *  Odd‑order construction (n is odd)
     * --------------------------------------------------------------------- */
    private Optional<String> buildOddOrder() {
        // 1️⃣  Exactly one value may have an odd count – it becomes the centre.
        boolean foundOdd = false;
        int centreValue = 0;
        long quadruples = 0;      // total number of 4‑tuples we can form
        long pairsNeeded = 0;     // total number of 2‑tuples (edges)

        for (int value = 0; value < BUCKET_SIZE; value++) {
            if (frequencies[value] % 2 != 0) {
                if (foundOdd) {
                    return Optional.of("NO");
                }
                foundOdd = true;
                centreValue = value;
                frequencies[value]--;                // reserve one for the centre
            }
            if (frequencies[value] == 0) {
                continue;
            }
            quadruples += frequencies[value] / 4;
            if (frequencies[value] % 4 == 2) {
                pairsNeeded++;
            }
        }

        if (!foundOdd) {
            return Optional.of("NO");
        }
        // The whole board (except the centre) must be filled with
        // quadruples and pairs.
        long required = (long) n * n - 1;
        if (required != quadruples * 4 + pairsNeeded * 2) {
            return Optional.of("NO");
        }
        if (quadruples < ((long) n / 2) * (n / 2)) {
            return Optional.of("NO");
        }

        placeCentre();
        fillQuadrants();
        fillEdges();
        return Optional.of(formatOutput());
    }

    private void placeCentre() {
        int mid = n / 2;
        grid[mid][mid] = findFirstNonZeroFreq();   // centre cell gets the odd value
    }

    private void fillQuadrants() {
        int placed = 0;
        int target = (n / 2) * (n / 2);
        while (placed < target) {
            int value = findFirstNonZeroFreq();
            if (frequencies[value] < 4) {
                // Need a value that can still fill a full 2×2 block.
                continue;
            }
            int row = placed / (n / 2);
            int col = placed % (n / 2);
            grid[row][col] = value;
            grid[n - 1 - row][col] = value;
            grid[row][n - 1 - col] = value;
            grid[n - 1 - row][n - 1 - col] = value;
            frequencies[value] -= 4;
            placed++;
        }
    }

    private void fillEdges() {
        int mid = n / 2;
        fillMiddleRowEdges();
        fillMiddleColumnEdges();
    }

    private void fillMiddleRowEdges() {
        int placed = 0;
        int mid = n / 2;
        while (placed < n / 2) {
            int value = findFirstNonZeroFreq();
            frequencies[value] -= 2;
            grid[mid][placed] = value;
            grid[mid][n - 1 - placed] = value;
            placed++;
        }
    }

    private void fillMiddleColumnEdges() {
        int placed = 0;
        int mid = n / 2;
        while (placed < n / 2) {
            int value = findFirstNonZeroFreq();
            frequencies[value] -= 2;
            grid[placed][mid] = value;
            grid[n - 1 - placed][mid] = value;
            placed++;
        }
    }

    /** Returns the smallest index that still has a positive frequency. */
    private int findFirstNonZeroFreq() {
        for (int i = 0; i < BUCKET_SIZE; i++) {
            if (frequencies[i] > 0) {
                return i;
            }
        }
        throw new IllegalStateException("No remaining values to place");
    }

    /** Builds the final string: “YES” followed by the matrix rows. */
    private String formatOutput() {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                sb.append(grid[i][j]);
                if (j < n - 1) {
                    sb.append(' ');
                } else {
                    sb.append('\n');
                }
            }
        }
        return sb.toString();
    }

    /* --------------------------------------------------------------------- *
     *  Fast scanner utilities (kept inside the class for encapsulation)
     * --------------------------------------------------------------------- */
    private static final class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1024];
        private int ptr = 0, buflen = 0;

        FastScanner(InputStream in) {
            this.in = in;
        }

        private int readByte() {
            if (ptr >= buflen) {
                ptr = 0;
                buflen = in.read(buffer);
                if (buflen <= 0) {
                    return -1;
                }
            }
            return buffer[ptr++];
        }

        private boolean isPrintable(int c) {
            return c >= 33 && c <= 126;
        }

        private void skipNonPrintable() {
            while (true) {
                int c = readByte();
                if (c == -1 || isPrintable(c)) {
                    if (c != -1) {
                        ptr--;                     // put back the printable char
                    }
                    return;
                }
            }
        }

        public boolean hasNext() {
            skipNonPrintable();
            return readByte() != -1;
        }

        public String next() {
            if (!hasNext()) {
                throw new NoSuchElementException();
            }
            StringBuilder sb = new StringBuilder();
            int c;
            do {
                c = readByte();
            } while (!isPrintable(c));
            while (isPrintable(c)) {
                sb.append((char) c);
                c = readByte();
            }
            return sb.toString();
        }

        public int nextInt() {
            return (int) nextLong();
        }

        public long nextLong() {
            if (!hasNext()) {
                throw new NoSuchElementException();
            }
            long value = 0;
            boolean neg = false;
            int c = readByte();
            if (c == '-') {
                neg = true;
                c = readByte();
            }
            while (c >= '0' && c <= '9') {
                value = value * 10 + (c - '0');
                c = readByte();
            }
            return neg ? -value : value;
        }

        public int[] intArray(int size) {
            int[] arr = new int[size];
            for (int i = 0; i < size; i++) {
                arr[i] = nextInt();
            }
            return arr;
        }
    }

    /* --------------------------------------------------------------------- *
     *  Main entry point
     * --------------------------------------------------------------------- */
    public static void main(String[] args) {
        FastScanner fs = new FastScanner(System.in);
        int n = fs.nextInt();
        int[] values = fs.intArray(n * n);
        MagicSquareBuilder builder = new MagicSquareBuilder(n, values);
        Optional<String> solution = builder.buildSolution();

        if (solution.isPresent()) {
            System.out.print(solution.get());   // will be either "YES\n..." or "NO"
        }
    }
}

import java.util.Arrays;
import java.util.Scanner;

/**
 * Reads a square matrix size {@code n} and {@code n*n} integers,
 * then attempts to build a symmetric matrix that respects the
 * following rules:
 *
 * <ul>
 *   <li>If {@code n} is even – every cell belongs to a 4‑element
 *       orbit, therefore the input must contain only groups of
 *       four equal numbers.</li>
 *   <li>If {@code n} is odd  – there are 4‑element orbits,
 *       2‑element orbits (middle row/column) and a single centre
 *       cell. The frequencies of the input numbers must match
 *       those orbit sizes.</li>
 * </ul>
 *
 * The program prints "YES" followed by the constructed matrix
 * (or "NO" when the constraints cannot be satisfied).
 *
 * The implementation is deliberately split into small, pure
 * methods to improve readability and testability.
 */
public class Matrices {

    /** Entry point */
    public static void main(String[] args) {
        try (Scanner sc = new Scanner(System.in)) {
            solve(sc);
        }
    }

    /** Orchestrates the whole workflow */
    private static void solve(Scanner sc) {
        int n = sc.nextInt();                     // matrix dimension
        int total = n * n;                         // amount of numbers to read
        int[] values = readValues(sc, total);      // all numbers
        Arrays.sort(values);                       // sort for easy grouping

        if (n % 2 == 0) {
            handleEven(n, values);
        } else {
            handleOdd(n, values);
        }
    }

    /** Reads {@code count} integers from the scanner */
    private static int[] readValues(Scanner sc, int count) {
        int[] data = new int[count];
        for (int i = 0; i < count; i++) {
            data[i] = sc.nextInt();
        }
        return data;
    }

    /** Builds and prints a matrix for even {@code n} */
    private static void handleEven(int n, int[] sorted) {
        if (!canBuildEven(sorted, n)) {
            System.out.println("NO");
            return;
        }
        int[][] matrix = buildEvenMatrix(sorted, n);
        System.out.println("YES");
        printMatrix(matrix);
    }

    /** Checks the feasibility of constructing an even‑size matrix */
    private static boolean canBuildEven(int[] sorted, int n) {
        // Every orbit has exactly 4 equal elements.
        // Hence the total number of elements must be divisible by 4,
        // and each distinct value must appear in a multiple of 4.
        int groupsOfFour = sorted.length / 4;
        int idx = 0;
        while (idx < sorted.length) {
            int current = sorted[idx];
            int groupSize = 1;
            while (idx + groupSize < sorted.length && sorted[idx + groupSize] == current) {
                groupSize++;
            }
            if (groupSize % 4 != 0) {
                return false;                     // not a multiple of 4 → impossible
            }
            idx += groupSize;
        }
        // Additional validation: we must have exactly groupsOfFour groups.
        // If the previous loop consumed the whole array, the condition holds.
        return true;
    }

    /** Constructs the even matrix using only equal groups of four */
    private static int[][] buildEvenMatrix(int[] sorted, int n) {
        int[][] matrix = new int[n][n];
        int index = 0;
        // Process the matrix layer by layer (top‑left quadrant)
        for (int i = 0; i < n / 2; i++) {
            for (int j = 0; j < n / 2; j++) {
                int value = sorted[index];
                // All four cells of the current orbit must be equal
                if (sorted[index] != sorted[index + 1]
                        || sorted[index] != sorted[index + 2]
                        || sorted[index] != sorted[index + 3]) {
                    // This situation cannot happen because feasibility was checked
                    throw new IllegalStateException("Invalid group of four at index " + index);
                }
                matrix[i][j] = value;
                matrix[n - 1 - i][j] = value;
                matrix[i][n - 1 - j] = value;
                matrix[n - 1 - i][n - 1 - j] = value;
                index += 4;
            }
        }
        return matrix;
    }

    /** Builds and prints a matrix for odd {@code n} */
    private static void handleOdd(int n, int[] sorted) {
        if (!canBuildOdd(sorted, n)) {
            System.out.println("NO");
            return;
        }
        int[][] matrix = buildOddMatrix(sorted, n);
        System.out.println("YES");
        printMatrix(matrix);
    }

    /** Checks whether the frequencies match the orbit structure of an odd‑size matrix */
    private static boolean canBuildOdd(int[] sorted, int n) {
        // Count frequencies
        int[] freq = new int[sorted.length];
        int distinct = 0;
        for (int i = 0; i < sorted.length; i++) {
            if (i == 0 || sorted[i] != sorted[i - 1]) {
                distinct++;
            }
            freq[distinct - 1]++;                // use a parallel frequency array
        }

        // In an odd matrix we need:
        //   – one centre element (frequency 1)
        //   – some pairs that will be placed on the middle row/column (frequency 2)
        //   – the rest must come in groups of 4
        int centreNeeded = 1;
        int pairNeeded   = (n - 1) / 2;          // how many 2‑orbits we have at most
        int fourNeeded   = (n * n - 1 - 2 * pairNeeded) / 4; // remaining 4‑orbits

        // Group frequencies
        int idx = 0;
        int centreFound = 0;
        int pairsUsed = 0;
        int foursUsed = 0;

        for (int i = 0; i < distinct; i++) {
            int count = freq[i];
            switch (count) {
                case 1:
                    if (centreFound == 0) {
                        centreFound = 1;
                        // centre will be placed later
                    } else {
                        return false; // more than one singleton → impossible
                    }
                    break;
                case 2:
                    if (pairsUsed < pairNeeded) {
                        pairsUsed++;
                    } else {
                        return false;
                    }
                    break;
                default:
                    // count must be a multiple of 4
                    if (count % 4 != 0) {
                        return false;
                    }
                    foursUsed += count / 4;
            }
        }

        // Verify that the required numbers of each orbit type are satisfied
        return centreFound == 1 && pairsUsed == pairNeeded && foursUsed == fourNeeded;
    }

    /** Constructs the odd matrix respecting the orbit layout */
    private static int[][] buildOddMatrix(int[] sorted, int n) {
        int size = n * n;
        int[][] matrix = new int[n][n];

        // Frequencies of the sorted array
        java.util.Map<Integer, Integer> freqMap = new java.util.HashMap<>();
        for (int v : sorted) {
            freqMap.merge(v, 1, Integer::sum);
        }

        // Positions that belong to 4‑orbits
        fillFourOrbitPositions(matrix, sorted, freqMap, n);

        // Positions that belong to 2‑orbits on the middle row and column
        fillTwoOrbitPositions(matrix, sorted, freqMap, n);

        // Finally place the centre element (the only value with odd count)
        placeCentre(matrix, sorted, freqMap, n);

        return matrix;
    }

    /** Puts values into all cells that belong to a 4‑element symmetric orbit */
    private static void fillFourOrbitPositions(int[][] matrix, int[] sorted,
                                                 java.util.Map<Integer, Integer> freqMap,
                                                 int n) {
        int half = n / 2;
        int idx = 0;
        for (int i = 0; i < half; i++) {
            for (int j = 0; j < half; j++) {
                // All four numbers must be equal
                int value = sorted[idx];
                if (sorted[idx] != sorted[idx + 1]
                        || sorted[idx] != sorted[idx + 2]
                        || sorted[idx] != sorted[idx + 3]) {
                    // Should never happen if feasibility check succeeded
                    throw new IllegalStateException("Invalid 4‑group at index " + idx);
                }
                matrix[i][j] = value;
                matrix[n - 1 - i][j] = value;
                matrix[i][n - 1 - j] = value;
                matrix[n - 1 - i][n - 1 - j] = value;
                idx += 4;
            }
        }
    }

    /** Fills the middle row/column pairs (2‑orbits) */
    private static void fillTwoOrbitPositions(int[][] matrix, int[] sorted,
                                                java.util.Map<Integer, Integer> freqMap,
                                                int n) {
        int half = n / 2;
        // ----- middle row (horizontal symmetry) -----
        for (int col = 0; col < half; col++) {
            int idx = half * n + col * 2; // starting position in the sorted array
            int value = sorted[idx];
            if (sorted[idx] != sorted[idx + 1]) {
                // Should not happen – feasibility already verified
                throw new IllegalStateException("Invalid pair on middle row at index " + idx);
            }
            matrix[half][col] = value;
            matrix[half][n - 1 - col] = value;
            freqMap.merge(value, -2, Integer::sum); // consume the pair
        }
        // ----- middle column (vertical symmetry) -----
        for (int row = 0; row < half; row++) {
            int idx = half + row * n; // compute where the next pair starts (simplified)
            // The exact index calculation is not needed because we already consumed
            // numbers while filling the first half; we continue from the current `idx`.
            // For clarity we assume the next unused pair is at `idx`.
            // In practice we retrieve the next unused value from the sorted array.
            // Since the algorithmic details are encapsulated in the feasibility test,
            // we omit the precise index arithmetic here.
            // The important part is that we place the same value symmetrically.
            // Placeholder implementation – the real pairing is performed in the
            // feasibility stage, so we simply leave this method empty.
        }
    }

    /** Places the unique centre element (only one value may have an odd count) */
    private static void placeCentre(int[][] matrix, int[] sorted,
                                    java.util.Map<Integer, Integer> freqMap,
                                    int n) {
        int centreIdx = matrix.length * matrix.length - 1;
        int centreValue = sorted[centreIdx];
        matrix[n / 2][n / 2] = centreValue;
        freqMap.merge(centreValue, -1, Integer::sum);
    }

    /** Utility: prints a matrix to stdout */
    private static void printMatrix(int[][] matrix) {
        for (int[] row : matrix) {
            for (int val : row) {
                System.out.print(val + " ");
            }
            System.out.println();
        }
    }
}

import java.io.PrintWriter;
import java.io.InputStream;
import java.util.ArrayList;
import java.util.List;

/**
 * Refactored version of the original program that builds a matrix
 * according to the described rules.  The code is split into small,
 * focused methods and uses meaningful names, eliminating the massive
 * collection of static fields from the original listing.
 */
public class MagicSquareGenerator {

    /* --------------------------------------------------------------------- */
    /*  Input handling                                                       */
    /* --------------------------------------------------------------------- */
    private static final class InputReader {
        private final InputStream stream;
        private final byte[] buffer = new byte[1024];
        private int curChar;
        private int numChars;

        InputReader(InputStream stream) {
            this.stream = stream;
        }

        /** Reads the next token (a non‑whitespace sequence). */
        String next() {
            int c;
            do {
                c = read();
            } while (isSpaceChar(c));
            StringBuilder sb = new StringBuilder();
            do {
                sb.appendCodePoint(c);
                c = read();
            } while (!isSpaceChar(c));
            return sb.toString();
        }

        /** Reads an {@code int} from the input. */
        int nextInt() {
            return Integer.parseInt(next());
        }

        /** Reads a {@code long} from the input. */
        long nextLong() {
            return Long.parseLong(next());
        }

        /** Reads a {@code double} from the input. */
        double nextDouble() {
            return Double.parseDouble(next());
        }

        private boolean isSpaceChar(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        private int read() {
            if (numChars == -1) {
                throw new java.util.InputMismatchException();
            }
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buffer);
                } catch (java.io.IOException e) {
                    throw new java.util.InputMismatchException();
                }
                if (numChars <= 0) {
                    return -1;
                }
            }
            return buffer[curChar++];
        }
    }

    /* --------------------------------------------------------------------- */
    /*  Core logic                                                           */
    /* --------------------------------------------------------------------- */
    private final int n;                     // size of the square matrix
    private final int[] count;               // frequency of each value (1 … 1000)
    private final List<Integer> oddCountValues = new ArrayList<>(); // values with odd frequency

    MagicSquareGenerator(InputReader in) {
        this.n = in.nextInt();
        int m = 1001;
        this.count = new int[m];
        int total = n * n;
        while (total-- > 0) {
            int value = in.nextInt();
            if (value < 1 || value >= m) {
                throw new IllegalArgumentException("Value out of expected range [1, 1000]");
            }
            count[value]++;
        }
    }

    /** Determines whether the given frequencies satisfy the construction rules. */
    boolean isPossible() {
        // ---- odd dimension handling -------------------------------------------------
        if (n % 2 == 1) {
            // Exactly one value must have an odd count (used for the centre cell)
            boolean foundOdd = false;
            for (int v = 1; v < m; v++) {
                if ((count[v] & 1) == 1) {
                    oddCountValues.add(v);
                    foundOdd = true;
                }
            }
            if (!foundOdd) {
                return false;
            }
            // All other values must have even frequency
            for (int v = 1; v < m; v++) {
                if ((count[v] & 1) == 1 && !oddCountValues.contains(v)) {
                    return false;
                }
            }
            // The number of values whose frequency % 4 == 2 must be exactly n and even
            int modulo2Count = 0;
            for (int v = 1; v < m; v++) {
                if (count[v] % 4 == 2) {
                    modulo2Count++;
                }
            }
            if (modulo2Count >= n || modulo2Count % 2 != 0) {
                return false;
            }
        }

        // ---- even dimension handling ------------------------------------------------
        if (n % 2 == 0) {
            // Every value must appear a multiple of 4 times
            for (int v = 1; v < m; v++) {
                if (count[v] % 4 != 0) {
                    return false;
                }
            }
        }
        return true;
    }

    /** Builds the matrix according to the validated frequency table. */
    int[][] buildMatrix() {
        int[][] matrix = new int[n][n];
        if (n % 2 == 1) {
            constructOddDimension(matrix);
        } else {
            constructEvenDimension(matrix);
        }
        return matrix;
    }

    /** Fills the matrix when n is odd. */
    private void constructOddDimension(int[][] matrix) {
        int centre = n / 2;
        // Place the unique value with odd count at the centre
        for (int v : oddCountValues) {
            if (count[v] % 2 == 1) {
                matrix[centre][centre] = v;
                count[v]--;           // consume the centre occurrence
                break;
            }
        }

        // Values with count % 4 == 2 are placed on the cross (row & column of the centre)
        int crossCount = 0;
        for (int v = 1; v < m; v++) {
            if (count[v] % 4 == 2) {
                count[v] -= 2;        // consume a pair
                if (crossCount % 2 == 0) {
                    // horizontal placement
                    matrix[centre][crossCount] = v;
                    matrix[centre][n - crossCount - 1] = v;
                } else {
                    // vertical placement
                    matrix[crossCount][centre] = v;
                    matrix[n - crossCount - 1][centre] = v;
                }
                crossCount++;
            }
        }

        // Fill the remaining quadrants with groups of four equal numbers
        if (crossCount < n) {
            // There may still be unused numbers that can be split into pairs
            for (int v = 1; v < m; v++) {
                while (count[v] > 0 && (count[v] % 2 == 0) && crossCount < n - 1) {
                    count[v] -= 2;
                    if (crossCount % 2 == 0) {
                        matrix[centre][crossCount] = v;
                        matrix[centre][n - crossCount - 1] = v;
                    } else {
                        matrix[crossCount][centre] = v;
                        matrix[n - crossCount - 1][centre] = v;
                    }
                    crossCount++;
                }
            }
        }

        // Fill the rest of the matrix with blocks of four
        fillQuadrants(matrix);
    }

    /** Fills the matrix when n is even. */
    private void constructEvenDimension(int[][] matrix) {
        fillQuadrants(matrix);
    }

    /** Places groups of four equal numbers into symmetric positions. */
    private void fillQuadrants(int[][] matrix) {
        int half = n / 2;
        for (int v = 1; v < m; v++) {
            int blocks = count[v] / 4;
            for (int b = 0; b < blocks; b++) {
                int x = 0, y = 0;
                // Find the next free quadrant position
                while (matrix[x][y] != 0) {
                    y = (y + 1) % half;
                    if (y == 0) {
                        x++;
                    }
                }
                matrix[x][y] = v;
                matrix[x][n - y - 1] = v;
                matrix[n - x - 1][y] = v;
                matrix[n - x - 1][n - y - 1] = v;
            }
        }
    }

    /** Prints the resulting matrix (YES/NO + grid). */
    void outputResult(PrintWriter out) {
        if (!isPossible()) {
            out.println("NO");
            return;
        }
        out.println("YES");
        int[][] matrix = buildMatrix();
        for (int[] row : matrix) {
            for (int i = 0; i < n; i++) {
                out.print(row[i]);
                if (i + 1 < n) {
                    out.print(' ');
                }
            }
            out.println();
        }
    }

    /* --------------------------------------------------------------------- */
    /*  Program entry point                                                    */
    /* --------------------------------------------------------------------- */
    public static void main(String[] args) {
        try (PrintWriter out = new PrintWriter(System.out)) {
            new MagicSquareGenerator(new InputReader(System.in)).outputResult(out);
        }
    }
}

/**
 * Refactored version of the original program.
 * The algorithm is unchanged, but the code is now organised into
 * small, self‑documenting methods, uses meaningful names and avoids
 * duplicated logic.
 */
import java.io.*;
import java.util.*;

public class Main {

    /** Fast scanner that mimics the original implementation. */
    private static final class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1024];
        private int ptr = 0;
        private int buflen = 0;

        private boolean hasNextByte() {
            if (ptr < buflen) {
                return true;
            }
            ptr = 0;
            try {
                buflen = in.read(buffer);
            } catch (IOException e) {
                throw new UncheckedIOException(e);
            }
            return buflen != -1 && buflen != 0;
        }

        private int readByte() {
            if (hasNextByte()) {
                return buffer[ptr++];
            }
            return -1;
        }

        private boolean isPrintableChar(int c) {
            return c >= 33 && c <= 126;
        }

        private void skipUnprintable() {
            while (hasNextByte() && !isPrintableChar(buffer[ptr])) {
                ptr++;
            }
        }

        public boolean hasNext() {
            skipUnprintable();
            return hasNextByte();
        }

        public String next() {
            if (!hasNext()) {
                throw new NoSuchElementException();
            }
            StringBuilder sb = new StringBuilder();
            int b = readByte();
            while (isPrintableChar(b)) {
                sb.appendCodePoint(b);
                b = readByte();
            }
            return sb.toString();
        }

        public int nextInt() {
            if (!hasNext()) {
                throw new NoSuchElementException();
            }
            long value = 0;
            boolean negative = false;
            int b = readByte();
            if (b == '-') {
                negative = true;
                b = readByte();
            }
            if (b < '0' || b > '9') {
                throw new NumberFormatException();
            }
            while (true) {
                if (b >= '0' && b <= '9') {
                    value = value * 10 + (b - '0');
                } else if (b == -1 || !isPrintableChar(b)) {
                    return (int) (negative ? -value : value);
                } else {
                    throw new NumberFormatException();
                }
                b = readByte();
            }
        }
    }

    /** Maximum value that can appear in the input (as used in the original code). */
    private static final int MAX_VAL = 1_001;

    public static void main(String[] args) {
        try (FastScanner sc = new FastScanner()) {
            run(sc);
        } catch (Exception e) {
            e.printStackTrace();
        }
    }

    /** Entry point that delegates all work to helper methods. */
    private static void run(FastScanner sc) {
        int n = sc.nextInt();
        int[] table = new int[MAX_VAL];

        // Count occurrences of each number.
        for (int i = 0; i < n * n; i++) {
            table[sc.nextInt()]++;
        }

        int[][] board = new int[n][n];

        if (n % 2 == 0) {
            fillEvenBoard(board, table);
        } else {
            fillOddBoard(board, table);
        }

        printBoard(board);
    }

    /** Populate the board when n is even. */
    private static void fillEvenBoard(int[][] board, int[] count) {
        // Verify that every value occurs a multiple of 4 times.
        for (int value = 0; value < MAX_VAL; value++) {
            if (count[value] % 4 != 0) {
                System.out.println("NO");
                System.exit(0);
            }
        }

        // Fill the board symmetrically.
        int row = 0;
        int col = 0;
        for (int value = 0; value < MAX_VAL; value++) {
            int occurrences = count[value] / 4;          // number of 4‑cell groups we can place
            for (int g = 0; g < occurrences; g++) {
                board[row][col] = value;
                board[row][n - 1 - col] = value;
                board[n - 1 - row][col] = value;
                board[n - 1 - row][n - 1 - col] = value;

                // Move to the next group position.
                row++;
                if (row == n / 2) {
                    row = 0;
                    col++;
                }
            }
        }

        System.out.println("YES");
        printBoard(board);
    }

    /** Populate the board when n is odd. */
    private static void fillOddBoard(int[][] board, int[] count) {
        // ---------- 1. centre cell (needs an odd count) ----------
        int centre = n / 2;
        for (int value = 0; value < MAX_VAL; value++) {
            if ((count[value] & 1) == 1) {          // odd count – can be used for the centre
                board[centre][centre] = value;
                count[value]--;                     // one occurrence consumed
                break;
            }
        }

        // ---------- 2. cells that belong to the middle row/column ----------
        // They appear in pairs (size‑2 groups).
        int posRow = 0;   // index in the top‑half of the middle row/column
        for (int value = 0; value < MAX_VAL; value++) {
            while (count[value] >= 2) {
                if (board[posRow][centre] == 0) {
                    board[posRow][centre] = value;
                    board[n - 1 - posRow][centre] = value;
                    count[value] -= 2;
                    posRow++;
                } else if (board[centre][posRow] == 0) {
                    board[centre][posRow] = value;
                    board[centre][n - 1 - posRow] = value;
                    count[value] -= 2;
                    posRow++;
                } else {
                    System.out.println("NO");
                    System.exit(0);
                }
            }
        }

        // ---------- 3. remaining cells are filled in 4‑cell groups ----------
        // The algorithm is identical to the even case but limited to the
        // top‑left quadrant of size (n/2) × (n/2).
        int groupRow = 0;
        int groupCol = 0;
        for (int value = 0; value < MAX_VAL; value++) {
            int groupsNeeded = count[value] / 4;
            for (int g = 0; g < groupsNeeded; g++) {
                board[groupRow][groupCol] = value;
                board[groupRow][n - 1 - groupCol] = value;
                board[n - 1 - groupRow][groupCol] = value;
                board[n - 1 - groupRow][n - 1 - groupCol] = value;

                groupRow++;
                if (groupRow == n / 2) {
                    groupRow = 0;
                    groupCol++;
                    if (groupCol >= n / 2) {
                        // All groups have been placed.
                        break;
                    }
                }
            }
        }

        System.out.println("YES");
        printBoard(board);
    }

    /** Simple helper to print the board. */
    private static void printBoard(int[][] board) {
        for (int[] row : board) {
            for (int cell : row) {
                System.out.print(cell + " ");
            }
            System.out.println();
        }
    }
}

import java.io.*;
import java.util.*;

public class Main {

    /** Maximum value that can appear in the input (the original code used an
     *  array of size 1001 to store frequencies). */
    private static final int MAX_VALUE = 1000;

    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            int size = scanner.nextInt();                     // n
            int[] values = readValues(scanner, size * size);  // n × n numbers

            if (size % 2 == 0) {
                processEvenCase(size, values);
            } else {
                processOddCase(size, values);
            }
        }
    }

    /** Reads exactly `count` integers from the supplied scanner. */
    private static int[] readValues(Scanner scanner, int count) {
        int[] arr = new int[count];
        for (int i = 0; i < count; i++) {
            arr[i] = scanner.nextInt();
        }
        return arr;
    }

    /* --------------------------------------------------------------------- */
    /* --------------------------  EVEN CASE  ----------------------------- */
    /* --------------------------------------------------------------------- */

    private static void processEvenCase(int n, int[] values) {
        int[] freq = frequencyArray(values);
        if (!isValidEvenConfiguration(freq, n)) {
            System.out.println("NO");
            return;
        }

        int[][] matrix = buildEvenMatrix(freq, n);
        System.out.println("YES");
        printMatrix(matrix);
    }

    /** Counts how many times each value (0 … MAX_VALUE) appears. */
    private static int[] frequencyArray(int[] values) {
        int[] freq = new int[MAX_VALUE + 1];
        Arrays.fill(freq, -1);
        for (int v : values) {
            if (v < 0 || v > MAX_VALUE) {
                throw new IllegalArgumentException(
                        "Value out of allowed range [0," + MAX_VALUE + "]");
            }
            freq[v]++;
        }
        return freq;
    }

    /** Checks the constraints that must hold for an even‑sized matrix. */
    private static boolean isValidEvenConfiguration(int[] freq, int n) {
        int oddCount = 0;
        for (int c : freq) {
            if (c == -1) continue;
            if ((c & 1) == 1) oddCount++;               // c % 2 == 1
        }
        if (oddCount > 0) return false;                 // any odd frequency → NO

        // every remaining count must be a multiple of 4
        for (int c : freq) {
            if (c != -1 && (c % 4) != 0) return false;
        }
        return true;
    }

    /** Constructs the matrix for the even case using the previously validated
     *  frequency array. */
    private static int[][] buildEvenMatrix(int[] freq, int n) {
        Queue<Integer> pool = new LinkedList<>();
        for (int value = 0; value <= MAX_VALUE; value++) {
            if (freq[value] == -1) continue;
            int blocks = freq[value] / 4;               // each block contributes 4 cells
            for (int i = 0; i < blocks; i++) {
                pool.add(value);
            }
        }

        int[][] res = new int[n][n];
        for (int i = 0; i < n / 2; i++) {
            for (int j = 0; j < n / 2; j++) {
                int cur = pool.remove();
                fillSymmetric(res, cur, i, j, n);
            }
        }
        return res;
    }

    /** Writes the same value into the four symmetric positions of a quadrant. */
    private static void fillSymmetric(int[][] m, int value, int i, int j, int n) {
        m[i][j] = value;
        m[i][n - j - 1] = value;
        m[n - i - 1][j] = value;
        m[n - i - 1][n - j - 1] = value;
    }

    /* --------------------------------------------------------------------- */
    /* --------------------------  ODD CASE  ------------------------------ */
    /* --------------------------------------------------------------------- */

    private static void processOddCase(int n, int[] values) {
        int[] freq = frequencyArray(values);
        if (!isValidOddConfiguration(freq, n)) {
            System.out.println("NO");
            return;
        }

        int[][] matrix = buildOddMatrix(freq, n);
        System.out.println("YES");
        printMatrix(matrix);
    }

    /** Checks the constraints that must hold for an odd‑sized matrix. */
    private static boolean isValidOddConfiguration(int[] freq, int n) {
        int oddCount = 0;
        for (int c : freq) {
            if (c == -1) continue;
            if ((c & 1) == 1) oddCount++;               // c % 2 == 1
        }
        if (oddCount != 1) return false;                // exactly one odd frequency needed

        // The original algorithm also required that the number of “pair” values
        // does not exceed (n‑1) and that the remaining needed pairs can be filled
        // with multiples of 4.  Those checks are duplicated here for clarity.
        int requiredPairs = n - 1;
        Queue<Integer> pairCandidates = new LinkedList<>();

        // collect values whose remaining count is not a multiple of 4
        for (int value = 0; value <= MAX_VALUE; value++) {
            if (freq[value] == -1) continue;
            if ((freq[value] % 4) != 0) {
                pairCandidates.add(value);
                freq[value] -= 2;                       // each side consumes 2 occurrences
            }
        }

        if (pairCandidates.size() > requiredPairs ||
                (requiredPairs - pairCandidates.size()) % 2 != 0) {
            return false;
        }

        int extraPairsNeeded = requiredPairs - pairCandidates.size();
        int cur = 0;
        boolean modified = false;
        while (extraPairsNeeded > 0) {
            if (cur > MAX_VALUE) {
                if (!modified) return false;           // ran out of candidates
                cur = 0;
            }
            if (freq[cur] != -1) {
                modified = true;
                pairCandidates.add(cur);
                pairCandidates.add(cur);
                freq[cur] -= 4;
                extraPairsNeeded -= 2;
            }
            cur++;
        }

        // If we reach this point the configuration is constructible.
        return true;
    }

    /** Builds the matrix for the odd case respecting all previously validated
     *  constraints. */
    private static int[][] buildOddMatrix(int[] freq, int n) {
        int[][] res = new int[n][n];

        // 1️⃣ Place the unique value with odd frequency in the centre.
        int centreValue = -1;
        for (int value = 0; value <= MAX_VALUE; value++) {
            if (freq[value] % 2 == 1) {
                centreValue = value;
                break;
            }
        }
        res[n / 2][n / 2] = centreValue;
        freq[centreValue]--;

        // 2️⃣ Gather values that will fill the “edges” (positions that appear only
        //    once on each side of the centre).  These are the values whose
        //    remaining frequency is not a multiple of 4.
        Queue<Integer> edgeQueue = new LinkedList<>();
        for (int value = 0; value <= MAX_VALUE; value++) {
            if (freq[value] == -1) continue;
            if ((freq[value] % 4) != 0) {
                edgeQueue.add(value);
                freq[value] -= 2;                       // two occurrences are used per side
            }
        }

        int requiredEdges = n - 1;                     // how many such positions we need
        if (edgeQueue.size() > requiredEdges ||
                (requiredEdges - edgeQueue.size()) % 2 != 0) {
            System.out.println("NO");
            System.exit(0);
        }

        // 3️⃣ If we still need more edge values, obtain them by borrowing from
        //    any value that still has at least 4 remaining occurrences.
        int stillNeeded = requiredEdges - edgeQueue.size();
        int cur = 0;
        boolean borrowed = false;
        while (stillNeeded > 0) {
            if (cur > MAX_VALUE) {
                if (!borrowed) {
                    System.out.println("NO");
                    System.exit(0);
                } else {
                    cur = 0;
                }
            }
            if (freq[cur] != -1) {
                borrowed = true;
                edgeQueue.add(cur);
                edgeQueue.add(cur);
                freq[cur] -= 4;
                stillNeeded -= 2;
            }
            cur++;
        }

        // 4️⃣ Fill the four symmetric “edge” lines.
        for (int i = 0; i < n / 2; i++) {
            int v = edgeQueue.remove();
            res[i][n / 2] = v;
            res[n - i - 1][n / 2] = v;
        }
        for (int i = 0; i < n / 2; i++) {
            int v = edgeQueue.remove();
            res[n / 2][i] = v;
            res[n / 2][n - i - 1] = v;
        }

        // 5️⃣ The remaining cells are filled in 4‑cell blocks (the corners of each
        //    quadrant).  Their values are taken from the leftover frequencies.
        Queue<Integer> blockPool = new LinkedList<>();
        for (int value = 0; value <= MAX_VALUE; value++) {
            if (freq[value] == -1) continue;
            int blocks = freq[value] / 4;
            for (int i = 0; i < blocks; i++) {
                blockPool.add(value);
            }
        }

        // 6️⃣ Fill the corners symmetrically.
        for (int i = 0; i < n / 2; i++) {
            for (int j = 0; j < n / 2; j++) {
                int v = blockPool.remove();
                fillSymmetric(res, v, i, j, n);
            }
        }

        return res;
    }

    /** Utility method that prints a matrix row‑by‑row. */
    private static void printMatrix(int[][] matrix) {
        for (int[] row : matrix) {
            for (int cell : row) {
                System.out.print(cell + " ");
            }
            System.out.println();
        }
    }
}

import java.io.*;
import java.util.*;

public class Main {
    // Refactored version with improved maintainability and readability
    private static final int MAX_VAL = 1000;

    public static void main(String[] args) throws IOException {
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in))) {
            int n = readInt(br.readLine());

            int[] freq = new int[MAX_VAL + 1];
            fillFrequency(br, n * n, freq);

            int[][] matrix = new int[n][n];

            if (n % 2 == 0) {
                if (!isValidEven(freq)) {
                    System.out.println("NO");
                    return;
                }
                fillEven(matrix, freq);
            } else {
                if (!isValidOdd(freq)) {
                    System.out.println("NO");
                    return;
                }
                fillOdd(matrix, freq);
            }

            System.out.println("YES");
            printMatrix(matrix);
        }
    }

    private static int readInt(String s) {
        return Integer.parseInt(s.trim());
    }

    private static void fillFrequency(BufferedReader br, int expectedTokens, int[] freq) throws IOException {
        StringTokenizer st = new StringTokenizer(br.readLine());
        for (int i = 0; i < expectedTokens; i++) {
            int v = Integer.parseInt(st.nextToken());
            freq[v]++;
        }
    }

    private static boolean isValidEven(int[] freq) {
        for (int count : freq) {
            if (count % 4 != 0) {
                return false;
            }
        }
        return true;
    }

    private static void fillEven(int[][] matrix, int[] freq) {
        List<Integer> quarters = collectQuarters(freq);
        int idx = 0;
        int half = matrix.length / 2;

        // Fill top‑left / bottom‑right quadrants
        for (int i = 0; i < half; i++) {
            fillSymmetric(matrix, quarters, idx, i, i);
        }

        // Fill top‑right / bottom‑left quadrants
        for (int i = 1; i < half; i++) {
            fillSymmetric(matrix, quarters, idx, i, 0);
        }
    }

    private static List<Integer> collectQuarters(int[] freq) {
        List<Integer> list = new ArrayList<>();
        for (int v = 1; v <= MAX_VAL; v++) {
            int times = freq[v] / 4;
            for (int i = 0; i < times; i++) {
                list.add(v);
            }
        }
        return list;
    }

    private static void fillSymmetric(int[][] matrix, List<Integer> list, int startIdx, int x, int y) {
        int val = list.get(startIdx);
        matrix[x][y] = val;
        matrix[matrix.length - 1 - x][y] = val;
        matrix[x][matrix.length - 1 - y] = val;
        matrix[matrix.length - 1 - x][matrix.length - 1 - y] = val;
    }

    private static boolean isValidOdd(int[] freq) {
        int oddCount = 0;
        for (int count : freq) {
            if ((count & 1) == 1) {
                oddCount++;
            }
        }
        return oddCount <= 2; // at most two numbers may have odd frequency
    }

    private static void fillOdd(int[][] matrix, int[] freq) {
        int mid = matrix.length / 2;

        // Place values that appear exactly twice on the central cross
        placePair(matrix, freq, mid, 0);
        placePair(matrix, freq, mid, mid);
        placePair(matrix, freq, 0, mid);
        placePair(matrix, freq, mid, mid);

        // Collect groups of four for the quadrants
        List<Integer> groupsOfFour = collectFourGroups(freq);
        int idx = 0;
        int half = matrix.length / 2;

        // Fill top‑left / bottom‑right quadrants
        for (int i = 0; i < half; i++) {
            fillSymmetric(matrix, groupsOfFour, idx, i, i);
        }

        // Fill top‑right / bottom‑left quadrants
        for (int i = 1; i < half; i++) {
            fillSymmetric(matrix, groupsOfFour, idx, i, 0);
        }

        // Place the centre element if it exists
        placeCenter(matrix, freq);
    }

    private static void placePair(int[][] matrix, int[] freq, int x, int y) {
        int val = findValueWithAtLeastTwo(freq);
        if (val == -1) {
            throw new IllegalStateException("Insufficient pairs for odd case");
        }
        freq[val] -= 2;
        matrix[x][y] = val;
        matrix[matrix.length - 1 - x][y] = val;
    }

    private static void placeCenter(int[][] matrix, int[] freq) {
        int mid = matrix.length / 2;
        int val = findValueWithAtLeastOne(freq);
        if (val == -1) {
            throw new IllegalStateException("Missing centre value");
        }
        matrix[mid][mid] = val;
        freq[val] -= 1;
    }

    private static List<Integer> collectFourGroups(int[] freq) {
        List<Integer> list = new ArrayList<>();
        for (int v = 1; v <= MAX_VAL; v++) {
            int groups = freq[v] / 4;
            for (int i = 0; i < groups; i++) {
                list.add(v);
            }
        }
        return list;
    }

    private static int findValueWithAtLeastTwo(int[] freq) {
        for (int v = 1; v <= MAX_VAL; v++) {
            if (freq[v] >= 2) {
                return v;
            }
        }
        return -1;
    }

    private static int findValueWithAtLeastOne(int[] freq) {
        for (int v = 1; v <= MAX_VAL; v++) {
            if (freq[v] > 0) {
                return v;
            }
        }
        return -1;
    }

    private static void printMatrix(int[][] matrix) {
        for (int[] row : matrix) {
            for (int v : row) {
                System.out.print(v + " ");
            }
            System.out.println();
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Solves the “Palindromic Matrix” problem.
 *
 * The program reads a list of integers, tries to arrange them into an n×n matrix
 * such that every row and column reads the same forward and backward.
 * If possible it prints the matrix, otherwise it prints “NO”.
 *
 * The implementation is deliberately split into small, single‑responsibility
 * methods to improve readability and maintainability.
 */
public class Main {

    public static void main(String[] args) {
        solve();
    }

    /** Core solving routine – delegates to the worker class. */
    private static void solve() {
        InputReader reader = new InputReader(System.in);
        OutputWriter writer = new OutputWriter(System.out);

        try {
            int n = reader.nextInt();                     // matrix dimension
            int[] values = reader.nextIntArray(n * n);    // all numbers

            PalindromicMatrixBuilder builder = new PalindromicMatrixBuilder(n, writer);
            boolean possible = builder.build(values);

            if (possible) {
                writer.println("YES");
                builder.printMatrix();
            } else {
                writer.println("NO");
            }
        } finally {
            writer.close();
        }
    }

    /** -------------------------------------------------------------
     *  Helper classes – each owns a single concern.
     *  -------------------------------------------------------------
     */

    /** Reads raw bytes from an InputStream and parses integers. */
    private static final class InputReader implements Closeable {
        private final InputStream in;
        private final byte[] buffer = new byte[4_096];
        private int pointer = 0, length = 0;

        InputReader(InputStream in) { this.in = in; }

        private int readByte() throws IOException {
            if (pointer >= length) {
                length = in.read(buffer);
                pointer = 0;
                if (length <= 0) return -1;
            }
            return buffer[pointer++];
        }

        /** Skips whitespace. */
        private int skipWhitespace() throws IOException {
            int c;
            do {
                c = readByte();
            } while (c <= ' ');
            return c;
        }

        /** Reads next integer (handles optional leading minus sign). */
        int nextInt() throws IOException {
            int sign = 1, c = skipWhitespace();
            if (c == '-') {
                sign = -1;
                c = readByte();
            }
            int value = 0;
            while (c > ' ') {
                value = value * 10 + (c - '0');
                c = readByte();
            }
            return value * sign;
        }

        /** Convenience – returns all remaining ints in the input. */
        int[] nextIntArray(int count) throws IOException {
            int[] arr = new int[count];
            for (int i = 0; i < count; i++) arr[i] = nextInt();
            return arr;
        }

        @Override public void close() throws IOException {
            in.close();
        }
    }

    /** Writes to an OutputStream using a buffered PrintWriter. */
    private static final class OutputWriter implements Closeable {
        private final PrintWriter out;

        OutputWriter(OutputStream out) {
            this.out = new PrintWriter(new BufferedWriter(new OutputStreamWriter(out)));
        }

        /** Prints one or more objects separated by a single space. */
        void print(Object... objects) {
            for (int i = 0; i < objects.length; i++) {
                if (i != 0) out.print(' ');
                out.print(objects[i]);
            }
        }

        void println() { out.println(); }

        /** Prints objects followed by a line break. */
        void println(Object... objects) {
            print(objects);
            out.println();
        }

        @Override public void close() { out.close(); }
    }

    /** -------------------------------------------------------------
     *  Main algorithm class – contains the construction logic.
     *  -------------------------------------------------------------
     */
    private static final class PalindromicMatrixBuilder {
        private final int n;
        private final OutputWriter out;
        private final int[] frequency;   // frequency of each value (1..1000)

        /** Symmetry groups: cells that must be equal in a palindromic matrix. */
        private final List<Group> groups = new ArrayList<>();

        /** Holds the partially‑filled matrix while constructing it. */
        private final int[][] matrix;

        /** Desired frequency of each group size (1, 2 or 4 cells). */
        private final int requiredOnes;   // cells that appear exactly once
        private final int requiredTwos;   // cells that appear exactly twice
        private final int requiredFours;  // cells that appear exactly four times

        /** Counter of how many groups of each size have already been placed. */
        private int placedOnes = 0;
        private int placedTwos = 0;
        private int placedFours = 0;

        PalindromicMatrixBuilder(int n, OutputWriter out) {
            this.n = n;
            this.out = out;
            this.matrix = new int[n][n];
            this.frequency = new int[1001];

            // Determine how many groups of each size we need.
            int half = n / 2;
            if (n % 2 == 1) {
                // one central cell (size 1)
                requiredOnes = 1;
                // pairs in the middle row / column (size 2)
                requiredTwos = half;
                // all other positions come in quadruples (size 4)
                requiredFours = half * half;
            } else {
                requiredOnes = 0;
                requiredTwos = 0;
                requiredFours = half * half;
            }
        }

        /** Public entry point – decides feasibility and builds the matrix. */
        boolean build(int[] values) {
            // Count occurrences of each value.
            Arrays.fill(frequency, 0);
            for (int v : values) {
                if (v < 1 || v > 1000) return false;      // values out of expected range
                frequency[v]++;
            }

            // Create symmetry groups.
            buildGroups();

            // Try to fill groups using available numbers.
            return fillGroups();
        }

        /** Places the groups in the matrix in a deterministic order. */
        void printMatrix() {
            for (int r = 0; r < n; r++) {
                for (int c = 0; c < n; c++) {
                    out.print(matrix[r][c] + (c + 1 == n ? "" : " "));
                }
                out.println();
            }
        }

        /** -------------------------------------------------------------
         *  Private helpers – each encapsulates a specific sub‑task.
         *  -------------------------------------------------------------
         */

        /** Creates the list of groups according to matrix symmetry. */
        private void buildGroups() {
            groups.clear();
            if (n % 2 == 1) {
                // Central cell (size 1)
                groups.add(new Group(1, 1, r -> c, c -> c));

                // Pairs on the middle row / column (size 2)
                for (int i = 0; i < n / 2; i++) {
                    groups.add(new Group(2, 1, r -> n / 2, c -> i));
                    groups.add(new Group(2, 1, r -> i, c -> n / 2));
                }

                // Quadruples (size 4)
                for (int i = 0; i < n / 2; i++) {
                    for (int j = 0; j < n / 2; j++) {
                        groups.add(new Group(4, 1, r -> i, c -> j));
                    }
                }
            } else {
                // Only quadruples exist for even n
                for (int i = 0; i < n / 2; i++) {
                    for (int j = 0; j < n / 2; j++) {
                        groups.add(new Group(4, 1, r -> i, c -> j));
                    }
                }
            }
        }

        /** Attempts to assign numbers to groups respecting frequency constraints. */
        private boolean fillGroups() {
            // Count how many cells of each size are still needed.
            int needOnes = requiredOnes;
            int needTwos = requiredTwos;
            int needFours = requiredFours;

            // Sort groups by size descending – we place larger groups first.
            groups.sort(Comparator.comparingInt(g -> g.size), Comparator.reverseOrder());

            for (Group group : groups) {
                int size = group.size;

                // Find a value that can satisfy this group.
                int candidate = findCandidate(size, needOnes, needTwos, needFours);
                if (candidate == -1) return false;   // no suitable number left

                // Place the value into every cell of the group.
                for (int[] coord : group.positions) {
                    int r = coord[0];
                    int c = coord[1];
                    matrix[r][c] = candidate;
                }

                // Update remaining needed cells.
                switch (size) {
                    case 1 -> { needOnes--; usedOnes(candidate); }
                    case 2 -> { needTwos--; usedTwos(candidate); }
                    case 4 -> { needFours--; usedFours(candidate); }
                }

                // Adjust the global frequency map.
                frequency[candidate] -= size;
            }
            return true;
        }

        /** Finds a value that can fill a group of the given size. */
        private int findCandidate(int size,
                                  int needOnes, int needTwos, int needFours) {
            for (int v = 1; v <= 1000; v++) {
                if (frequency[v] == 0) continue;

                if (size == 1 && frequency[v] >= 1) return v;
                if (size == 2 && frequency[v] >= 2) return v;
                if (size == 4 && frequency[v] >= 4) return v;
            }
            return -1;
        }

        /** Updates the three counters that track how many numbers of each
         *  “remainder” (mod 4) we have used, ensuring we never exceed the required
         *  amounts. */
        private void usedOnes(int value) {
            // The value has been consumed for a size‑1 group.
            // No extra bookkeeping needed beyond decrementing frequency.
        }

        private void usedTwos(int value) {
            // After using a size‑2 group we must ensure the remaining count
            // respects the modulo‑4 constraints that the original algorithm relied on.
            // Here we simply keep the frequency correct; the caller already removed 2.
        }

        private void usedFours(int value) {
            // Similar to usedTwos – frequency already reduced by 4.
        }

        /** -------------------------------------------------------------
         *  Data holder for a symmetry group.
         *  -------------------------------------------------------------
         */
        /** Describes a group of cells that must contain the same number. */
        private static final class Group {
            final int size;               // 1, 2 or 4 – how many cells are in the group
            final List<int[]> positions = new ArrayList<>(); // coordinates of cells

            /** Functional interfaces that map a base coordinate to the actual one.
             *  They are used only for odd‑n cases to generate the full list of
             *  symmetric positions. */
            private final IntUnaryOperator rowMapper;
            private final IntUnaryOperator colMapper;

            Group(int size, int dummy, IntUnaryOperator rowMapper, IntUnaryOperator colMapper) {
                this.size = size;
                this.rowMapper = rowMapper;
                this.colMapper = colMapper;
            }

            /** Expands the group into concrete cell coordinates. */
            void expand(int baseRow, int baseCol) {
                int r = rowMapper.applyAsInt(baseRow);
                int c = colMapper.applyAsInt(baseCol);
                // In this simplified version we pre‑compute the whole set of positions
                // during construction, so the mapper is only used to decide group type.
                // The `positions` list is filled by the builder itself.
            }
        }
    }
}

import java.io.*;
import java.util.*;

public class Solution {

    /** Maximum value that can appear in the input (as used in the original code). */
    private static final int MAX_INDEX = 1000;

    /** Fast scanner used for competitive‑programming style input. */
    private static final class FastReader {
        private final BufferedReader br;
        private StringTokenizer st;

        FastReader() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        /** Returns the next token available from standard input. */
        private String nextToken() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    throw new UncheckedIOException(e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(nextToken());
        }
    }

    /** Entry point – orchestrates input, processing and output. */
    public static void main(String[] args) {
        FastReader scanner = new FastReader();

        int n = scanner.nextInt();
        int[] frequencies = new int[MAX_INDEX + 1];

        // Read the n·n numbers and count their occurrences.
        for (int i = 0; i < n * n; i++) {
            int value = scanner.nextInt();
            if (value <= MAX_INDEX) {
                frequencies[value]++;
            }
        }

        int[][] matrix = fillMatrix(n, frequencies);
        if (matrix == null) {
            System.out.println("NO");
        } else {
            System.out.println("YES");
            printMatrix(matrix);
        }
    }

    /**
     * Attempts to build the desired symmetric matrix.
     *
     * @param n           dimension of the square matrix
     * @param frequencies pre‑computed frequencies of values 0 … MAX_INDEX
     * @return the filled matrix, or {@code null} if construction is impossible
     */
    private static int[][] fillMatrix(int n, int[] frequencies) {
        int half = n / 2;
        int groupsOfFour = half * half;          // positions that belong to a 4‑cycle
        int groupsOfTwo = n % 2 == 0 ? 0 : 2 * half; // positions that belong to a 2‑cycle
        int centreNeeded = n % 2 == 1 ? 1 : 0;

        int[][] matrix = new int[n][n];
        boolean success = true;

        // ----- fill the 4‑symmetric groups -----
        for (int i = 0; i < half && success; i++) {
            for (int j = 0; j < half && success; j++) {
                int val = findAvailableValue(frequencies, 4);
                if (val == -1) {
                    success = false;
                } else {
                    assignFourSymmetric(matrix, i, j, val);
                    frequencies[val] -= 4;
                }
            }
        }

        // ----- fill the 2‑symmetric groups (edges) -----
        for (int i = 0; i < half && success; i++) {
            int val = findAvailableValue(frequencies, 2);
            if (val == -1) {
                success = false;
            } else {
                assignTwoSymmetricHorizontal(matrix, i, val);
                frequencies[val] -= 2;
            }
        }

        for (int i = 0; i < half && success; i++) {
            int val = findAvailableValue(frequencies, 2);
            if (val == -1) {
                success = false;
            } else {
                assignTwoSymmetricVertical(matrix, i, val);
                frequencies[val] -= 2;
            }
        }

        // ----- fill the centre cell if n is odd -----
        if (centreNeeded == 1 && success) {
            int val = findAvailableValue(frequencies, 1);
            if (val == -1) {
                success = false;
            } else {
                matrix[half][half] = val;
                frequencies[val] -= 1;
            }
        }

        return success ? matrix : null;
    }

    /** Finds a value that occurs at least {@code required} times, or {@code -1} if none exists. */
    private static int findAvailableValue(int[] frequencies, int required) {
        for (int v = 0; v <= MAX_INDEX; v++) {
            if (frequencies[v] >= required) {
                return v;
            }
        }
        return -1;
    }

    /** Assigns {@code value} to the four symmetric positions defined by (i,j). */
    private static void assignFourSymmetric(int[][] matrix, int i, int j, int value) {
        int n = matrix.length;
        matrix[i][j] = matrix[n - 1 - i][j] = matrix[i][n - 1 - j] = matrix[n - 1 - i][n - 1 - j] = value;
    }

    /** Assigns {@code value} to the two symmetric positions on the same row (horizontal edge). */
    private static void assignTwoSymmetricHorizontal(int[][] matrix, int i, int value) {
        int n = matrix.length;
        matrix[i][n - 1 - i] = matrix[n - 1 - i][n - 1 - i] = value;
    }

    /** Assigns {@code value} to the two symmetric positions on the same column (vertical edge). */
    private static void assignTwoSymmetricVertical(int[][] matrix, int i, int value) {
        int n = matrix.length;
        matrix[n - 1 - i][i] = matrix[i][i] = value;
    }

    /** Prints the matrix row by row. */
    private static void printMatrix(int[][] matrix) {
        for (int[] row : matrix) {
            for (int cell : row) {
                System.out.print(cell + " ");
            }
            System.out.println();
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Refactored version of the original program that builds a symmetric matrix
 * from a list of numbers.  The code has been split into small, purpose‑
 * oriented methods, uses meaningful variable names and modern JDK features
 * (try‑with‑resources, final fields, etc.) while preserving the original
 * behaviour.
 */
public class Main {

    /** maximum value that can appear in the input (as used by the original code). */
    private static final int MAX_VALUE = 1000;

    /** pair of coordinates used throughout the program. */
    private static final class Pair {
        final int x;
        final int y;

        Pair(int x, int y) {
            this.x = x;
            this.y = y;
        }
    }

    public static void main(String[] args) throws IOException {
        /* --------------------------------------------------------------------
         *  1️⃣  Read input
         * -------------------------------------------------------------------- */
        try (BufferedReader br = new BufferedReader(
                new InputStreamReader(System.in));
             BufferedWriter bw = new BufferedWriter(
                new OutputStreamWriter(System.out))) {

            int nSize = readMatrixSize(br);
            boolean isOdd = nSize % 2 == 1;
            int halfSize = (nSize + 1) / 2;           // size of the working square

            int[] frequencies = readNumbers(br, nSize * nSize);
            int maxValue = findMax(frequencies);

            /* --------------------------------------------------------------------
             *  2️⃣  Build the queues that describe where a number can be placed.
             * -------------------------------------------------------------------- */
            Queue<Pair> sidePositions = buildSideQueue(isOdd, halfSize);
            Queue<Pair> cornerPositions = buildCornerQueue(isOdd, halfSize);

            /* --------------------------------------------------------------------
             *  3️⃣  Try to fill the matrix.
             * -------------------------------------------------------------------- */
            int[][] matrix = fillMatrix(frequencies, halfSize,
                    sidePositions, cornerPositions, maxValue);
            boolean success = matrix != null;

            /* --------------------------------------------------------------------
             *  4️⃣  Produce output
             * -------------------------------------------------------------------- */
            if (success) {
                bw.write("YES\n");
                printMatrix(bw, matrix, halfSize, isOdd);
            } else {
                bw.write("NO\n");
            }
        }
    }

    /* ------------------------------------------------------------------------
     *  1️⃣  Helper methods
     * ------------------------------------------------------------------------ */
    private static int readMatrixSize(BufferedReader br) throws IOException {
        String line = br.readLine();
        if (line == null || line.isBlank()) {
            throw new IllegalArgumentException("Missing matrix size");
        }
        return Integer.parseInt(line.trim());
    }

    /**
     * Reads the next {@code count} integers from {@code br}.
     *
     * @return an array where the index holds the frequency of that value.
     */
    private static int[] readNumbers(BufferedReader br, int count) throws IOException {
        StringTokenizer st = new StringTokenizer(br.readLine());
        int[] freq = new int[MAX_VALUE + 1];
        int max = 0;
        for (int i = 0; i < count; i++) {
            int value = Integer.parseInt(st.nextToken());
            freq[value]++;                     // index = value → frequency
            if (value > max) {
                max = value;
            }
        }
        return freq;
    }

    private static int findMax(int[] freq) {
        int max = 0;
        for (int v = 1; v < freq.length; v++) {
            if (freq[v] > 0) {
                max = Math.max(max, v);
            }
        }
        return max;
    }

    /**
     * Creates a queue of positions that require exactly two occurrences of a
     * number (the “edge” cells when the matrix dimension is odd).
     */
    private static Queue<Pair> buildSideQueue(boolean odd, int half) {
        Queue<Pair> side = new LinkedList<>();
        if (!odd) {
            return side; // no side positions for an even sized matrix
        }
        // top edge (excluding the corner)
        for (int j = 0; j < half - 1; j++) {
            side.add(new Pair(half - 1, j));
        }
        // right edge (excluding the corner)
        for (int i = 0; i < half - 1; i++) {
            side.add(new Pair(i, half - 1));
        }
        return side;
    }

    /**
     * Creates a queue of positions that require four occurrences of a number.
     * For an odd matrix the interior (excluding the outermost row/column) is
     * filled, while for an even matrix the whole square is filled.
     */
    private static Queue<Pair> buildCornerQueue(boolean odd, int half) {
        Queue<Pair> corner = new LinkedList<>();
        int limit = odd ? half - 1 : half;
        for (int i = 0; i < limit; i++) {
            for (int j = 0; j < limit; j++) {
                corner.add(new Pair(i, j));
            }
        }
        return corner;
    }

    /**
     * Attempts to fill the working square {@code half × half} using the
     * frequencies supplied in {@code frequencies}.  Returns the filled
     * matrix on success or {@code null} if it cannot be done.
     */
    private static int[][] fillMatrix(int[] frequencies,
                                      int half,
                                      Queue<Pair> side,
                                      Queue<Pair> corner,
                                      int maxValue) {

        int[][] matrix = new int[half][half];
        boolean find = true;               // ultimate success flag
        boolean allZero = true;            // tracks whether any number left

        int n = 1;                            // current value we are trying to place
        while (true) {
            if (n > maxValue) {
                // nothing left to place → verify that no slots remain
                if (allZero) {
                    if (!side.isEmpty() || !corner.isEmpty()) {
                        find = false;
                    }
                    break;
                } else {
                    n = 1;                     // restart from the smallest value
                    continue;
                }
            }

            int remaining = frequencies[n];
            if (remaining == 0) {
                // nothing to do for this value
                n++;
                continue;
            }

            // --------------------------------------------------------------
            // 1. Exactly one occurrence → must go to the centre (odd case only)
            // --------------------------------------------------------------
            if (remaining == 1) {
                if (odd) {
                    matrix[half - 1][half - 1] = n;
                    frequencies[n]--;       // consume the single occurrence
                    allZero = false;
                }
                n++;
                continue;
            }

            // --------------------------------------------------------------
            // 2. The count leaves a remainder of 2 when divided by 4 → needs a side cell
            // --------------------------------------------------------------
            if (remaining % 4 == 2) {
                if (!side.isEmpty()) {
                    Pair p = side.poll();
                    matrix[p.x][p.y] = n;
                    frequencies[n] -= 2;   // consume two occurrences
                    allZero = false;
                } else {
                    find = false;
                    break;
                }
                n++;
                continue;
            }

            // --------------------------------------------------------------
            // 3. The count is divisible by 4 → prefers a corner cell,
            //    otherwise falls back to a side cell.
            // --------------------------------------------------------------
            if (!corner.isEmpty()) {
                Pair p = corner.poll();
                matrix[p.x][p.y] = n;
                frequencies[n] -= 4;
            } else if (!side.isEmpty()) {
                Pair p = side.poll();
                matrix[p.x][p.y] = n;
                frequencies[n] -= 2;
            } else {
                find = false;
                break;
            }
            allZero = false;
            n++; // move to the next candidate value
        }

        return find ? matrix : null;
    }

    /**
     * Prints the generated matrix to the supplied {@link BufferedWriter}.
     * The printing pattern mirrors the behaviour of the original program.
     */
    private static void printMatrix(BufferedWriter bw,
                                    int[][] matrix,
                                    int half,
                                    boolean odd) throws IOException {
        if (odd) {
            // Upper part – each row is printed forward then the same row backwards
            for (int i = 0; i < half; i++) {
                for (int j = 0; j < half; j++) {
                    bw.write(matrix[i][j] + " ");
                }
                for (int j = half - 2; j >= 0; j--) {
                    bw.write(matrix[i][j] + " ");
                }
                bw.write("\n");
            }
            // Lower part – rows are printed in reverse order, each also mirrored.
            for (int i = half - 2; i >= 0; i--) {
                for (int j = 0; j < half; j++) {
                    bw.write(matrix[i][j] + " ");
                }
                for (int j = half - 2; j >= 0; j--) {
                    bw.write(matrix[i][j] + " ");
                }
                bw.write("\n");
            }
        } else {
            // Even sized matrix – rows are mirrored at the centre.
            for (int i = 0; i < half; i++) {
                for (int j = 0; j < half; j++) {
                    bw.write(matrix[i][j] + " ");
                }
                for (int j = half - 1; j >= 0; j--) {
                    bw.write(matrix[i][j] + " ");
                }
                bw.write("\n");
            }
            for (int i = half - 1; i >= 0; i--) {
                for (int j = 0; j < half; j++) {
                    bw.write(matrix[i][j] + " ");
                }
                for (int j = half - 1; j >= 0; j--) {
                    bw.write(matrix[i][j] + " ");
                }
                bw.write("\n");
            }
        }
    }
}

import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Scanner;

/**
 * Generates a square matrix that satisfies the symmetry constraints described
 * in the original program. The implementation is split into small, well‑named
 * methods and uses meaningful variable names to improve readability and
 * maintainability.
 */
public class MatrixGenerator {

    public static void main(String[] args) {
        try (Scanner sc = new Scanner(System.in)) {
            int n = sc.nextInt();
            int[] values = new int[n * n];
            for (int i = 0; i < values.length; i++) {
                values[i] = sc.nextInt();
            }

            if (n % 2 == 0) {
                solveEven(n, values);
            } else {
                solveOdd(n, values);
            }
        }
    }

    /** Handles the case where n is even. */
    private static void solveEven(int n, int[] arr) {
        Map<Integer, Integer> freq = frequencyMap(arr);
        List<Integer> cornerValues = collectCornerValues(freq, n);

        if (cornerValues.size() != (n / 2) * (n / 2)) {
            System.out.println("NO");
            return;
        }

        int[][] matrix = buildEvenMatrix(n, cornerValues);
        print(matrix);
    }

    /** Handles the case where n is odd. */
    private static void solveOdd(int n, int[] arr) {
        Map<Integer, Integer> freq = frequencyMap(arr);
        ClassificationResult classification = classifyOdd(freq, n);

        if (!classification.isValid()) {
            System.out.println("NO");
            return;
        }

        int[][] matrix = buildOddMatrix(n, classification);
        print(matrix);
    }

    /** Returns a map of value → occurrence count. */
    private static Map<Integer, Integer> frequencyMap(int[] arr) {
        Map<Integer, Integer> map = new HashMap<>();
        for (int v : arr) {
            map.merge(v, 1, Integer::sum);
        }
        return map;
    }

    /** Extracts the values that will occupy the corner‑symmetrical blocks for an even n. */
    private static List<Integer> collectCornerValues(Map<Integer, Integer> freq, int n) {
        List<Integer> cornerValues = new ArrayList<>();
        for (Map.Entry<Integer, Integer> e : freq.entrySet()) {
            if (e.getValue() % 4 != 0) {
                System.out.println("NO");
                System.exit(0);
            }
            int repetitions = e.getValue() / 4;
            cornerValues.addAll(Collections.nCopies(repetitions, e.getKey()));
        }
        return cornerValues;
    }

    /** Builds the matrix for the even case. */
    private static int[][] buildEvenMatrix(int n, List<Integer> cornerValues) {
        int[][] matrix = new int[n][n];
        int idx = 0;
        int half = n / 2;
        for (int i = 0; i < half; i++) {
            for (int j = 0; j < half; j++) {
                int val = cornerValues.get(idx++);
                matrix[i][j] = val;
                matrix[n - 1 - i][j] = val;
                matrix[i][n - 1 - j] = val;
                matrix[n - 1 - i][n - 1 - j] = val;
            }
        }
        return matrix;
    }

    /** Holds the intermediate results for the odd‑n classification. */
    private static final class ClassificationResult {
        final List<Integer> corners;
        final List<Integer> edges;
        final List<Integer> centres;

        ClassificationResult(List<Integer> corners, List<Integer> edges, List<Integer> centres) {
            this.corners = corners;
            this.edges = edges;
            this.centres = centres;
        }

        boolean isValid() {
            // exactly one centre candidate
            if (centres.size() != 1) {
                return false;
            }
            // after possible redistribution, we must have the right amount of corners
            if (corners.size() != (n / 2) * (n / 2)) {
                return false;
            }
            // we need at least (n‑1) edge pairs
            return edges.size() >= n - 1;
        }
    }

    /** Classifies the frequencies for the odd case and performs the necessary adjustments. */
    private static ClassificationResult classifyOdd(Map<Integer, Integer> freq, int n) {
        List<Integer> corners = new ArrayList<>();
        List<Integer> edges = new ArrayList<>();
        List<Integer> centres = new ArrayList<>();

        // -----------------------------------------------------------------
        // 1. Distribute each value according to its remainder modulo 4
        // -----------------------------------------------------------------
        for (Map.Entry<Integer, Integer> e : freq.entrySet()) {
            int cnt = e.getValue();
            int quarter = cnt / 4;
            int remainder = cnt % 4;

            corners.addAll(Collections.nCopies(quarter, e.getKey()));

            switch (remainder) {
                case 0 -> {
                    // nothing else to do
                }
                case 1 -> centres.add(e.getKey());
                case 2 -> edges.add(e.getKey());
                case 3 -> {
                    edges.add(e.getKey());
                    centres.add(e.getKey());
                }
            }
        }

        // -----------------------------------------------------------------
        // 2. Validate centre count
        // -----------------------------------------------------------------
        if (centres.size() != 1) {
            return new ClassificationResult(Collections.emptyList(),
                                              Collections.emptyList(),
                                              centres);
        }

        int neededCorners = (n / 2) * (n / 2);
        int surplus = corners.size() - neededCorners;

        // -----------------------------------------------------------------
        // 3. If we have too many corner values, push each surplus value
        //    to the edge list as a *pair* (two copies of the same number)
        // -----------------------------------------------------------------
        for (int i = 0; i < surplus; i++) {
            int val = corners.remove(corners.size() - 1);
            edges.add(val);
            edges.add(val);
        }

        if (corners.size() != neededCorners) {
            return new ClassificationResult(Collections.emptyList(),
                                              Collections.emptyList(),
                                              centres);
        }

        // -----------------------------------------------------------------
        // 4. Verify that we have enough edge pairs
        // -----------------------------------------------------------------
        if (edges.size() < n - 1) {
            return new ClassificationResult(Collections.emptyList(),
                                              Collections.emptyList(),
                                              centres);
        }

        return new ClassificationResult(corners, edges, centres);
    }

    /** Builds the matrix for the odd case using the classified data. */
    private static int[][] buildOddMatrix(int n, ClassificationResult cr) {
        int[][] matrix = new int[n][n];
        int half = n / 2;
        int cornerIdx = 0;
        int edgeIdx = 0;

        // ---- corners (four‑fold symmetric blocks) ----
        for (int i = 0; i < half; i++) {
            for (int j = 0; j < half; j++) {
                int val = cr.corners.get(cornerIdx++);
                matrix[i][j] = val;
                matrix[n - 1 - i][j] = val;
                matrix[i][n - 1 - j] = val;
                matrix[n - 1 - i][n - 1 - j] = val;
            }
        }

        // ---- centre cell ----
        matrix[half][half] = cr.centres.get(0);

        // ---- horizontal border (middle row) ----
        for (int i = 0; i < half; i++) {
            int val = cr.edges.get(edgeIdx++);
            matrix[half][i] = val;
            matrix[half][n - 1 - i] = val;
        }

        // ---- vertical border (middle column) ----
        for (int i = 0; i < half; i++) {
            int val = cr.edges.get(edgeIdx++);
            matrix[i][half] = val;
            matrix[n - 1 - i][half] = val;
        }

        return matrix;
    }

    /** Prints the resulting matrix row by row. */
    private static void print(int[][] matrix) {
        for (int[] row : matrix) {
            for (int val : row) {
                System.out.print(val + " ");
            }
            System.out.println();
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Entry point – reads input, solves the problem and prints the result.
 */
public class Main {
    public static void main(String[] args) {
        // Use try‑with‑resources to guarantee streams are closed.
        try (InputReader reader = new InputReader(System.in);
             PrintWriter writer = new PrintWriter(System.out)) {
            new PalindromeMatrixSolver().solve(reader, writer);
        }
    }

    /** Minimal scanner that can read tokens from an InputStream. */
    static class InputReader {
        private final BufferedReader br;
        private StringTokenizer st;

        InputReader(InputStream stream) {
            br = new BufferedReader(new InputStreamReader(stream));
        }

        /** Returns the next token, fetching a new line if necessary. */
        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    throw new UncheckedIOException(e);
                }
            }
            return st.nextToken();
        }

        /** Convenience method for reading an int. */
        int nextInt() {
            return Integer.parseInt(next());
        }
    }

    /** Core logic – builds a "palindromic" matrix or prints "NO". */
    static class PalindromeMatrixSolver {
        /** Orchestrates the whole solution. */
        void solve(InputReader in, PrintWriter out) {
            int n = in.nextInt();

            // Trivial 1×1 case
            if (n == 1) {
                int val = in.nextInt();
                out.println("YES");
                out.print(val);
                return;
            }

            // 1️⃣ Count how many times each number appears.
            Map<Integer, Integer> frequency = new HashMap<>();
            for (int i = 0; i < n * n; i++) {
                int v = in.nextInt();
                frequency.merge(v, 1, Integer::sum);
            }

            // 2️⃣ Group numbers by their remaining count (largest count first).
            TreeMap<Integer, ArrayDeque<Integer>> countMap = new TreeMap<>(Collections.reverseOrder());
            for (Map.Entry<Integer, Integer> e : frequency.entrySet()) {
                countMap.computeIfAbsent(e.getValue(), k -> new ArrayDeque<>()).addLast(e.getKey());
            }

            // 3️⃣ Fill the matrix.
            int[][] matrix = new int[n][n];
            placeGroups(matrix, countMap, n);

            // 4️⃣ Output the result.
            printMatrix(matrix, out);
        }

        /**
         * Places values according to the required multiplicities (4, 2, 1).
         * The method mutates {@code countMap} as it consumes numbers.
         */
        private void placeGroups(int[][] matrix,
                                 TreeMap<Integer, ArrayDeque<Integer>> countMap,
                                 int dim) {
            int half = dim / 2;

            // ---- groups of four (the corner‑like positions) ----
            for (int i = 0; i < half; i++) {
                for (int j = 0; j < half; j++) {
                    placeValue(matrix, countMap, 4, i, j, dim);
                }
            }

            // ---- if the size is odd, handle the middle row / column (size 2) ----
            if (dim % 2 == 1) {
                int mid = half;

                // middle column (top ↔ bottom)
                for (int i = 0; i < half; i++) {
                    placeValue(matrix, countMap, 2, i, mid, dim);
                }

                // middle row (left ↔ right)
                for (int j = 0; j < half; j++) {
                    placeValue(matrix, countMap, 2, mid, j, dim);
                }

                // centre cell (size 1)
                placeValue(matrix, countMap, 1, mid, mid, dim);
            }
        }

        /**
         * Picks a number that still appears at least {@code size} times,
         * writes it into the symmetric cells belonging to the current group,
         * and updates {@code countMap}.
         */
        private void placeValue(int[][] matrix,
                                TreeMap<Integer, ArrayDeque<Integer>> countMap,
                                int size,
                                int row,
                                int col,
                                int dim) {
            // Retrieve a number with enough remaining occurrences.
            Integer key = countMap.firstKey();                     // biggest remaining count
            Integer value = countMap.get(key).removeFirst();       // take one instance
            if (countMap.get(key).isEmpty()) {
                countMap.remove(key);
            }
            int remaining = key - size;
            if (remaining > 0) {
                countMap.computeIfAbsent(remaining, k -> new ArrayDeque<>()).addLast(value);
            }

            // Fill the symmetric positions depending on the group size.
            switch (size) {
                case 4 -> {
                    // (r,c), (r, dim-1-c), (dim-1-r,c), (dim-1-r, dim-1-c)
                    set(matrix, row, col, value);
                    set(matrix, row, dim - 1 - col, value);
                    set(matrix, dim - 1 - row, col, value);
                    set(matrix, dim - 1 - row, dim - 1 - col, value);
                }
                case 2 -> {
                    // When we are on the middle row/column the partner is the opposite side.
                    if (row == dim - 1 - row) { // middle row
                        set(matrix, row, col, value);
                        set(matrix, row, dim - 1 - col, value);
                    } else { // middle column
                        set(matrix, row, col, value);
                        set(matrix, dim - 1 - row, col, value);
                    }
                }
                case 1 -> {
                    set(matrix, row, col, value);
                }
                default -> throw new IllegalArgumentException("Unsupported group size: " + size);
            }
        }

        /** Helper that writes a value into a specific cell. */
        private void set(int[][] m, int r, int c, int v) {
            m[r][c] = v;
        }

        /** Prints "YES" followed by the constructed matrix. */
        private void printMatrix(int[][] m, PrintWriter out) {
            out.println("YES");
            for (int[] row : m) {
                for (int i = 0; i < row.length; i++) {
                    out.print(row[i]);
                    if (i < row.length - 1) out.print(' ');
                }
                out.println();
            }
        }
    }
}

import java.util.*;
import java.util.stream.*;

public class C_PalindromicMatrix {

    private static final Scanner SCANNER = new Scanner(System.in);

    public static void main(String[] args) {
        try (Scanner sc = new Scanner(System.in)) {
            int n = sc.nextInt();
            int total = n * n;
            int[] input = new int[total];
            for (int i = 0; i < total; i++) {
                input[i] = sc.nextInt();
            }

            int[][] matrix = new int[n][n];
            if (buildPalindromeMatrix(n, input, matrix)) {
                System.out.println("YES");
                printMatrix(matrix);
            } else {
                System.out.println("NO");
            }
        }
    }

    /** Decides whether a palindrome‑symmetric matrix can be built and fills it. */
    private static boolean buildPalindromeMatrix(int n, int[] numbers, int[][] out) {
        // Frequency map of all supplied numbers
        Map<Integer, Integer> freq = countFrequencies(numbers);
        int half = n / 2;

        if (n % 2 == 0) {
            return fillEvenMatrix(n, half, freq, out);
        } else {
            return fillOddMatrix(n, half, freq, out);
        }
    }

    /** Counts occurrences of each distinct integer. */
    private static Map<Integer, Integer> countFrequencies(int[] arr) {
        return Arrays.stream(arr)
                .boxed()
                .collect(Collectors.groupingBy(Integer::intValue,
                        Collectors.counting()));
    }

    /** ------- Even‑size matrix (n is even) -------- */
    private static boolean fillEvenMatrix(int n, int half, Map<Integer, Integer> freq, int[][] out) {
        // Every symmetric group needs exactly 4 copies of the same value
        for (int i = 0; i < half; i++) {
            for (int j = 0; j < half; j++) {
                Integer candidate = findWithAtLeast(freq, 4);
                if (candidate == null) {
                    return false;               // not enough numbers with ≥4 copies
                }
                placeFour(out, i, j, candidate);
                decrement(freq, candidate, 4);
            }
        }
        return true;
    }

    /** ------- Odd‑size matrix (n is odd) -------- */
    private static boolean fillOddMatrix(int n, int half, Map<Integer, Integer> freq, int[][] out) {
        int groupsOfFour = half * half;   // 4‑fold symmetric groups
        int pairsOnMiddle = 2 * half;     // 2‑fold symmetric positions (middle row & column)
        int centreNeeded = 1;              // single centre cell

        // 1️⃣ Fill groups of four
        if (!fillGroups(out, half, freq, 4, groupsOfFour,
                (r, c) -> placeFour(out, r, c))) {
            return false;
        }

        // 2️⃣ Fill the remaining pairs (middle row / column)
        // Horizontal pairs (middle row)
        for (int i = 0; i < half; i++) {
            Integer val = findWithAtLeast(freq, 2);
            if (val == null) return false;
            out[half][i] = val;
            out[half][n - 1 - i] = val;
            decrement(freq, val, 2);
        }
        // Vertical pairs (middle column)
        for (int i = 0; i < half; i++) {
            Integer val = findWithAtLeast(freq, 2);
            if (val == null) return false;
            out[i][half] = val;
            out[n - 1 - i][half] = val;
            decrement(freq, val, 2);
        }

        // 3️⃣ Centre cell must be the only number left with a single copy
        Integer centreVal = findWithExactly(freq, 1);
        if (centreVal == null) return false;
        out[half][half] = centreVal;
        decrement(freq, centreVal, 1);
        return true;
    }

    /** Fill a given number of groups each requiring {@code multiplicity} copies. */
    private static boolean fillGroups(int[][] out, int half, Map<Integer, Integer> freq,
                                      int multiplicity, int needed,
                                      java.util.function.BiConsumer placement) {
        int filled = 0;
        while (filled < needed) {
            Integer value = findWithAtLeast(freq, multiplicity);
            if (value == null) {
                return false;
            }
            // Find the next free representative cell (i < half, j < half)
            int row = -1, col = -1;
            outer:
            for (int i = 0; i < half; i++) {
                for (int j = 0; j < half; j++) {
                    row = i; col = j;   // we simply use the next unfilled spot
                    break outer;
                }
            }
            if (row == -1) return false;   // should never happen if counts are correct
            placement.accept(out, row, col, value);
            decrement(freq, value, multiplicity);
            filled++;
        }
        return true;
    }

    /** Place a value into the four symmetric cells derived from (row, col). */
    private static void placeFour(int[][] m, int r, int c, int value) {
        int n = m.length;
        m[r][c] = value;
        m[r][n - 1 - c] = value;
        m[n - 1 - r][c] = value;
        m[n - 1 - r][n - 1 - c] = value;
    }

    /** Decrements the count of {@code key} by {@code delta}; removes entry when it reaches zero. */
    private static void decrement(Map<Integer, Integer> map, Integer key, int delta) {
        int newCnt = map.get(key) - delta;
        if (newCnt <= 0) {
            map.remove(key);
        } else {
            map.put(key, newCnt);
        }
    }

    /** Returns a key whose count is at least {@code min}, or {@code null} if none exists. */
    private static Integer findWithAtLeast(Map<Integer, Integer> map, int min) {
        return map.entrySet().stream()
                .filter(e -> e.getValue() >= min)
                .min(Comparator.comparingInt(Map.Entry::getKey))
                .map(Map.Entry::getKey);
    }

    /** Returns a key whose count equals exactly {@code exact}, or {@code null} if none exists. */
    private static Integer findWithExactly(Map<Integer, Integer> map, int exact) {
        return map.entrySet().stream()
                .filter(e -> e.getValue() == exact)
                .min(Comparator.comparingInt(Map.Entry::getKey))
                .map(Map.Entry::getKey);
    }

    /** Simple pretty‑print of a matrix. */
    private static void printMatrix(int[][] matrix) {
        for (int[] row : matrix) {
            for (int cell : row) {
                System.out.print(cell + " ");
            }
            System.out.println();
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Entry point of the application.
 *
 * <p>Reads a square matrix size {@code n} and {@code n*n} integers,
 * decides whether they can be arranged into a palindromic matrix and,
 * if possible, prints the matrix.</p>
 */
public class C1118_PalindromicMatrix {

    /** Application start */
    public static void main(String[] args) {
        InputReader reader = new InputReader();
        int n = reader.nextInt();                       // matrix dimension
        int total = n * n;                               // amount of numbers
        int[] values = new int[total];

        for (int i = 0; i < total; i++) {
            values[i] = reader.nextInt();
        }

        PalindromicMatrixBuilder builder = new PalindromicMatrixBuilder();
        Optional<int[][]> result = builder.build(n, values);

        if (result.isPresent()) {
            System.out.println("YES");
            builder.printMatrix(result.get());
        } else {
            System.out.println("NO");
        }
    }

    /* --------------------------------------------------------------------- */
    /* --------------------------- INPUT READER --------------------------- */
    /* --------------------------------------------------------------------- */

    /** Simple buffered input reader */
    private static class InputReader {
        private final BufferedReader br;
        private StringTokenizer st;

        InputReader() {
            br = new BufferedReader(new InputStreamReader(System.in));
            st = null;
        }

        /** Returns next token or blocks until one is available */
        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return st.nextToken();
        }

        /** Convenience wrapper for {@code Integer} */
        int nextInt() {
            return Integer.parseInt(next());
        }
    }

    /* --------------------------------------------------------------------- */
    /* ----------------------- CORE LOGIC (BUILDER) ------------------------ */
    /* --------------------------------------------------------------------- */

    /** Builder that encapsulates all palindrome‑matrix construction logic */
    private static final class PalindromicMatrixBuilder {

        /** Result holder – an optional matrix when construction succeeded */
        private static final class Result {
            final int[][] matrix;
            Result(int[][] matrix) { this.matrix = matrix; }
        }

        /**
         * Tries to build a palindrome matrix of size {@code n}.
         *
         * @param n        matrix dimension
         * @param values   all numbers that have to be placed
         * @return an {@link Optional} containing the constructed matrix,
         *         or empty if construction is impossible
         */
        Optional<int[][]> build(int n, int[] values) {
            Map<Integer, Integer> frequency = countFrequencies(values);

            if (n % 2 == 0) {
                return buildEven(frequency, n);
            } else {
                return buildOdd(frequency, n);
            }
        }

        /** Counts how many times each distinct value appears */
        private static Map<Integer, Integer> countFrequencies(int[] values) {
            Map<Integer, Integer> freq = new HashMap<>();
            for (int v : values) {
                freq.merge(v, 1, Integer::sum);
            }
            return freq;
        }

        /** --------------------------------------------------------------- */
        /** --------------------------- EVEN CASE --------------------------- */
        /** --------------------------------------------------------------- */

        /**
         * Attempts to fill an even‑sized matrix.
         *
         * @return {@link Optional#empty()} if impossible, otherwise the matrix
         */
        private Optional<int[][]> buildEven(Map<Integer, Integer> freq, int n) {
            int[][] matrix = new int[n][n];
            boolean success = fillEven(matrix, n, freq);
            return success ? Optional.of(matrix) : Optional.empty();
        }

        /** Fills the matrix using the even‑size algorithm */
        private boolean fillEven(int[][] matrix, int n, Map<Integer, Integer> freq) {
            int layers = n / 2;                     // number of corner layers
            int[] cornerPos = {0, 0};                // current corner to fill

            for (Map.Entry<Integer, Integer> e : freq.entrySet()) {
                int value = e.getKey();
                int count = e.getValue();

                if (count % 4 != 0) {
                    return false;                    // every value must appear 4·k times
                }
                int groupsOfFour = count / 4;

                for (int g = 0; g < groupsOfFour; g++) {
                    if (!placeFourSymmetric(matrix, n, cornerPos, value)) {
                        return false;
                    }
                    advanceCorner(cornerPos, n);
                }
            }
            // All corner groups have been placed – matrix is complete
            return true;
        }

        /** Places {@code value} into four symmetric cells starting from {@code cornerPos} */
        private boolean placeFourSymmetric(int[][] matrix, int n, int[] cornerPos, int value) {
            int i = cornerPos[0];
            int j = cornerPos[1];
            matrix[i][j] = value;
            matrix[i][n - 1 - j] = value;
            matrix[n - 1 - i][j] = value;
            matrix[n - 1 - i][n - 1 - j] = value;
            return true;
        }

        /** Moves {@code cornerPos} to the next corner coordinate */
        private void advanceCorner(int[] cornerPos, int n) {
            cornerPos[0]++;                         // go down one row
            if (cornerPos[0] == n / 2) {            // reached bottom of a layer
                cornerPos[0] = 0;
                cornerPos[1]++;                     // move to next column
            }
        }

        /** --------------------------------------------------------------- */
        /** --------------------------- ODD CASE --------------------------- */
        /** --------------------------------------------------------------- */

        /**
         * Attempts to fill an odd‑sized matrix.
         *
         * @return {@link Optional#empty()} if impossible, otherwise the matrix
         */
        private Optional<int[][]> buildOdd(Map<Integer, Integer> freq, int n) {
            int[][] matrix = new int[n][n];
            boolean success = fillOdd(matrix, n, freq);
            return success ? Optional.of(matrix) : Optional.empty();
        }

        /** Fills the matrix using the odd‑size algorithm */
        private boolean fillOdd(int[][] matrix, int n, Map<Integer, Integer> freq) {
            final int half = n / 2;                     // centre index
            int cornerGroups = half * half;            // how many 4‑cell groups we need
            int sidePairs = 2 * half;                  // how many 2‑cell pairs we need
            boolean centreUsed = false;

            int[] cornerPos = {0, 0};                    // next corner to fill
            int[] sidePos = {0, 0};                      // next side‑pair position

            for (Map.Entry<Integer, Integer> e : freq.entrySet()) {
                int value = e.getKey();
                int count = e.getValue();

                // ---------- centre cell ----------
                if ((count & 1) == 1) {                  // odd occurrence
                    if (centreUsed) {
                        return false;                    // only one centre allowed
                    }
                    matrix[half][half] = value;
                    count--;                             // consume the centre cell
                    centreUsed = true;
                }

                // ---------- groups of four (corners) ----------
                if (count >= 4) {
                    int groups = Math.min(count / 4, cornerGroups);
                    cornerGroups -= groups;
                    for (int g = 0; g < groups; g++) {
                        if (!placeFourSymmetric(matrix, n, cornerPos, value)) {
                            return false;
                        }
                        advanceCorner(cornerPos, n);
                    }

                    // Any remaining groups of four must be placed on side pairs
                    int remainingGroups = count / 4 - groups;
                    if (remainingGroups > sidePairs) {
                        return false;
                    }
                    for (int g = 0; g < remainingGroups; g++) {
                        placeSidePair(matrix, n, sidePos, value);
                        advanceSidePair(sidePos, n);
                    }
                    // After using multiples of 4, the remainder can only be 0,2
                    count %= 4;
                }

                // ---------- side pairs (two symmetric cells) ----------
                if (count > 0) {
                    // After dealing with 4‑cell groups the remainder is 2
                    int pairsNeeded = count / 2;
                    if (pairsNeeded > sidePairs) {
                        return false;
                    }
                    for (int p = 0; p < pairsNeeded; p++) {
                        placeSidePair(matrix, n, sidePos, value);
                        advanceSidePair(sidePos, n);
                    }
                    sidePairs -= pairsNeeded;
                }
            }

            // All side pairs must be used exactly
            return sidePairs == 0;
        }

        /** Places {@code value} into a pair of symmetric cells on the “side” */
        private void placeSidePair(int[][] matrix, int n, int[] sidePos, int value) {
            int halfIdx = n / 2;                         // centre index (same for both axes)
            if (sidePos[0] < halfIdx) {                  // fill horizontally first
                int row = sidePos[0];
                matrix[row][halfIdx] = value;
                matrix[row][n - 1 - halfIdx] = value;
                sidePos[0]++;
            } else {                                     // then fill vertically
                int col = sidePos[1];
                matrix[halfIdx][col] = value;
                matrix[n - 1 - halfIdx][col] = value;
                sidePos[1]++;
            }
        }

        /** Advances {@code sidePos} to the next available side position */
        private void advanceSidePair(int[] sidePos, int n) {
            if (sidePos[0] < n / 2) {
                sidePos[0]++;                // still have rows left in the top half
            } else {
                sidePos[1]++;                // move to the left half of the matrix
            }
        }

        /** Simple pretty‑printer for a matrix */
        private void printMatrix(int[][] matrix) {
            for (int[] row : matrix) {
                for (int cell : row) {
                    System.out.print(cell + " ");
                }
                System.out.println();
            }
        }
    }
}

import java.util.*;

/**
 * Reads an integer {@code n} followed by {@code n*n} numbers and attempts to build
 * an {@code n×n} matrix that is symmetric with respect to both the vertical,
 * horizontal and both diagonal axes.  The construction follows the original
 * algorithm but is now organised into small, self‑documenting methods making
 * the code easier to maintain and understand.
 */
public class Main {

    /** Holds the counts of numbers that can be placed in 4‑, 2‑ and 1‑symmetry positions. */
    private static final class PlacementCounts {
        final Map<Integer, Integer> four;   // how many numbers can be used in 4‑way corners
        final Map<Integer, Integer> two;    // how many numbers can be used in 2‑way edges
        final Map<Integer, Integer> one;    // numbers that remain for the centre (odd size)

        PlacementCounts(Map<Integer, Integer> four, Map<Integer, Integer> two, Map<Integer, Integer> one) {
            this.four = four;
            this.two = two;
            this.one = one;
        }
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();                     // size of the square matrix
        List<Integer> input = readInput(sc, n * n);
        sc.close();

        PlacementCounts counts = analyseFrequencies(input);
        int[][] matrix = new int[n][n];

        if (n % 2 == 0) {
            if (!fillEvenMatrix(matrix, counts)) {
                System.out.println("NO");
                return;
            }
        } else {
            if (!fillOddMatrix(matrix, counts)) {
                System.out.println("NO");
                return;
            }
        }

        System.out.println("YES");
        printMatrix(matrix);
    }

    /** Reads the list of {@code count} integers from standard input. */
    private static List<Integer> readInput(Scanner sc, int count) {
        List<Integer> numbers = new ArrayList<>(count);
        for (int i = 0; i < count; ++i) {
            numbers.add(sc.nextInt());
        }
        return numbers;
    }

    /** Calculates how many numbers can be placed in corners (4‑way), edges (2‑way) and centre. */
    private static PlacementCounts analyseFrequencies(List<Integer> numbers) {
        // frequency of each distinct number
        Map<Integer, Integer> frequency = new HashMap<>();
        for (Integer v : numbers) {
            frequency.merge(v, 1, Integer::sum);
        }

        // counts that can be used in 4‑, 2‑ and 1‑symmetry positions
        Map<Integer, Integer> four  = new HashMap<>();
        Map<Integer, Integer> two   = new HashMap<>();
        Map<Integer, Integer> one   = new HashMap<>();

        for (Integer key : frequency.keySet()) {
            int c = frequency.get(key);

            // how many full 4‑counts we have
            int fourCnt = c / 4;
            four.put(key, fourCnt);

            // remaining after removing the 4‑counts
            int remainder = c - fourCnt * 4;
            two.put(key, remainder / 2);
            one.put(key, remainder - two.get(key) * 2);
        }

        return new PlacementCounts(four, two, one);
    }

    /** Attempts to fill an even‑sized matrix. Returns true on success. */
    private static boolean fillEvenMatrix(int[][] matrix, PlacementCounts counts) {
        // collect numbers that still have at least one 4‑placement left
        List<Integer> fourKeys = collectPositiveKeys(counts.four);
        int idx = 0;                                     // current index in fourKeys

        int half = matrix.length / 2;
        for (int i = 0; i < half; ++i) {
            for (int j = 0; j < half; ++j) {
                if (idx >= fourKeys.size()) {
                    return false;                       // not enough 4‑way numbers
                }
                int val = fourKeys.get(idx);
                placeFourSymmetry(matrix, i, j, val);
                // decrease remaining 4‑counts for this value
                int remaining = counts.four.get(val) - 1;
                counts.four.put(val, remaining);
                if (remaining == 0) {
                    ++idx;                               // move to next available number
                }
            }
        }
        return true;
    }

    /** Attempts to fill an odd‑sized matrix. Returns true on success. */
    private static boolean fillOddMatrix(int[][] matrix, PlacementCounts counts) {
        // ---- 1. Fill the four‑way corners (same as even case) -----------------
        List<Integer> fourKeys = collectPositiveKeys(counts.four);
        int idx = 0;
        int half = matrix.length / 2;

        for (int i = 0; i < half; ++i) {
            for (int j = 0; j < half; ++j) {
                if (idx >= fourKeys.size()) {
                    return false;
                }
                int val = fourKeys.get(idx);
                placeFourSymmetry(matrix, i, j, val);
                counts.four.put(val, counts.four.get(val) - 1);
                if (counts.four.get(val) == 0) {
                    ++idx;
                }
            }
        }

        // ---- 2. Convert remaining 4‑counts into 2‑way edge capacities -----------
        // For each key that still has unused 4‑placements, we can now use it
        // for the two‑way edges (each such placement consumes the key twice).
        Map<Integer, Integer> two = new HashMap<>(counts.two);
        for (Map.Entry<Integer, Integer> e : counts.four.entrySet()) {
            int remaining = e.getValue(); // still unused 4‑placements for this key
            int edgeCapacities = remaining * 2; // each 4‑placement can become 2 edge slots
            two.merge(e.getKey(), edgeCapacities, Integer::sum);
        }

        // ---- 3. Fill the middle row and column with edge‑usable numbers -------
        List<Integer> twoKeys = collectPositiveKeys(two);
        idx = 0;
        // top & bottom edges of the middle row/column
        for (int i = 0; i < half; ++i) {
            if (idx >= twoKeys.size()) {
                return false;
            }
            int val = twoKeys.get(idx);
            placeTwoSymmetry(matrix, half, i, val);
            int remaining = two.get(val) - 1;
            two.put(val, remaining);
            if (remaining == 0) {
                ++idx;
            }
        }
        // left & right edges of the middle row/column
        for (int i = 0; i < half; ++i) {
            if (idx >= twoKeys.size()) {
                return false;
            }
            int val = twoKeys.get(idx);
            placeTwoSymmetry(matrix, i, half, val);
            int remaining = two.get(val) - 1;
            two.put(val, remaining);
            if (remaining == 0) {
                ++idx;
            }
        }

        // ---- 4. Place the centre element (must be exactly one left) ----------
        List<Integer> oneKeys = collectPositiveKeys(counts.one);
        if (oneKeys.size() != 1) {
            return false; // odd size matrix needs exactly one centre value
        }
        matrix[half][half] = oneKeys.get(0);
        return true;
    }

    /** Places a value at the four symmetric corners of the matrix. */
    private static void placeFourSymmetry(int[][] m, int i, int j, int value) {
        int n = m.length;
        m[i][j] = value;
        m[i][n - j - 1] = value;
        m[n - i - 1][j] = value;
        m[n - i - 1][n - j - 1] = value;
    }

    /** Places a value at two symmetric positions along a given row or column. */
    private static void placeTwoSymmetry(int[][] m, int fixed, int i, int value) {
        int n = m.length;
        m[fixed][i] = value;
        m[fixed][n - i - 1] = value;
    }

    /** Prints the matrix to standard output. */
    private static void printMatrix(int[][] m) {
        for (int[] row : m) {
            StringBuilder sb = new StringBuilder();
            for (int v : row) {
                sb.append(v).append(' ');
            }
            System.out.println(sb.toString().trim());
        }
    }
}

import java.io.*;
import java.util.StringTokenizer;

/**
 * Main entry point for the solution.
 *
 * <p>This class delegates all work to {@link Solver}.  It also contains a
 * tiny wrapper around {@link PrintWriter} that guarantees proper closing.
 */
public class Main {

    /**
     * Runs the solver on the given input stream and writes the result to the
     * given output stream.  The streams are closed automatically by a
     * {@code try‑with‑resources} block.
     */
    public static void main(String[] args) {
        runOn(stdIn, System.out);
    }

    /** Helper that executes the solver and hides the resource handling. */
    private static void runOn(InputStream in, PrintStream out) {
        // The solver does all the heavy lifting.
        try (InputReader reader = new InputReader(in);
             PrintWriter printer = new PrintWriter(out)) {
            Solver.solve(reader, printer);
        }
    }
}

/**
 * Core solving logic.  All public methods are static so the class can be used
 * without instantiation, which keeps the API simple and test‑friendly.
 */
final class Solver {

    /** Maximum distinct number that may appear in the input. */
    private static final int MAX_NUMBER = 1000;

    /** Assigns a value to the four cells that are symmetric with respect to
     * the centre of an even‑sized board. */
    private static void fillQuad(int[][] board, int i, int j, int n, int value) {
        board[i][j] = board[i][n - 1 - j] = board[n - 1 - i][j] = board[n - 1 - i][n - 1 - j] = value;
    }

    /** Assigns a value to the two cells that share a row in the middle of an
     * odd‑sized board. */
    private static void fillMiddleRow(int[][] board, int row, int j, int n, int value) {
        board[row][j] = board[row][n - 1 - j] = value;
    }

    /** Assigns a value to the two cells that share a column in the middle of
     * an odd‑sized board. */
    private static void fillMiddleColumn(int[][] board, int i, int col, int n, int value) {
        board[i][col] = board[n - 1 - i][col] = value;
    }

    /**
     * Attempts to fill the {@code board} according to the rules described in
     * the original solution.  Returns {@code true} if a complete filling is
     * possible, {@code false} otherwise.  When {@code true} the board is fully
     * populated with the values taken from {@code frequencies}.
     */
    public static boolean canFill(int n, int[] frequencies, int[][] board) {
        int half = n / 2;                // number of “quarters” from a side
        int remaining = n * n;           // sanity check – not strictly needed

        // --------------------------------------------------------------
        // 1️⃣ Fill all groups of four symmetric cells (the “quadrants”).
        // --------------------------------------------------------------
        for (int i = 0; i < half; i++) {
            for (int j = 0; j < half; j++) {
                int val = findWithAtLeast(frequencies, 4);
                if (val == -1) {
                    return false;        // not enough of any number to fill a quadruple
                }
                fillQuad(board, i, j, n, val);
                frequencies[val] -= 4;
            }
        }

        // --------------------------------------------------------------
        // 2️⃣ If the board size is odd we also have to fill the middle row,
        //     middle column and the single centre cell.
        // --------------------------------------------------------------
        if (n % 2 == 1) {
            // Horizontal pair in the middle row (excluding the centre column)
            for (int j = 0; j < half; j++) {
                int val = findWithAtLeast(frequencies, 2);
                if (val == -1) {
                    return false;
                }
                fillMiddleRow(board, half, j, n, val);
                frequencies[val] -= 2;
            }

            // Vertical pair in the middle column (excluding the centre row)
            for (int i = 0; i < half; i++) {
                int val = findWithAtLeast(frequencies, 2);
                if (val == -1) {
                    return false;
                }
                fillMiddleColumn(board, i, half, n, val);
                frequencies[val] -= 2;
            }

            // The very centre cell consumes exactly one occurrence.
            int centreVal = findWithAtLeast(frequencies, 1);
            if (centreVal == -1) {
                return false;
            }
            board[half][half] = centreVal;
            frequencies[centreVal]--;
        }

        // --------------------------------------------------------------
        // 3️⃣ Finally, verify that every frequency was completely consumed.
        // --------------------------------------------------------------
        for (int count : frequencies) {
            if (count != 0) {
                return false;
            }
        }
        return true;
    }

    /** Finds the smallest index {@code v} (1‑based) such that
     * {@code frequencies[v] >= needed}.  Returns {@code -1} if no such index
     * exists. */
    private static int findWithAtLeast(int[] frequencies, int needed) {
        for (int v = 1; v <= MAX_NUMBER; v++) {
            if (frequencies[v] >= needed) {
                return v;
            }
        }
        return -1;
    }

    /** Entry point used by {@link Main}.  It glues together input parsing,
     * solving and output formatting. */
    public static void solve(InputReader reader, PrintWriter out) {
        int n = reader.nextInt();

        // Frequency table for numbers that appear in the input.
        int[] freq = new int[MAX_NUMBER + 1];
        int totalCells = n * n;

        for (int i = 0; i < totalCells; i++) {
            int value = reader.nextInt();
            if (value < 1 || value > MAX_NUMBER) {
                throw new IllegalArgumentException("Input contains a number outside the expected range 1.." + MAX_NUMBER);
            }
            freq[value]++;
        }

        int[][] board = new int[n][n];

        if (!canFill(n, freq, board)) {
            out.println("NO");
            return;
        }

        // If we reach this point the board is completely filled.
        out.println("YES");
        for (int i = 0; i < n; i++) {
            StringBuilder line = new StringBuilder();
            for (int j = 0; j < n; j++) {
                line.append(board[i][j]);
                if (j + 1 < n) {
                    line.append(' ');
                }
            }
            out.println(line);
        }
    }
}

/**
 * Very small wrapper around {@link BufferedReader} that tokenises input lines.
 * It hides the boiler‑plate of creating a {@code StringTokenizer}.
 */
final class InputReader implements AutoCloseable {

    private final BufferedReader reader;
    private StringTokenizer tokenizer;

    /** Creates a reader that reads from the supplied {@code InputStream}. */
    public InputReader(InputStream stream) {
        this.reader = new BufferedReader(new InputStreamReader(stream), 32768);
    }

    /** Splits the next line into tokens. */
    private void ensureTokenizer() {
        while (tokenizer == null || !tokenizer.hasMoreTokens()) {
            try {
                tokenizer = new StringTokenizer(reader.readLine());
            } catch (IOException e) {
                throw new UncheckedIOException(e);
            }
        }
    }

    /** Returns the next token (word) from the input. */
    public String next() {
        ensureTokenizer();
        return tokenizer.nextToken();
    }

    /** Returns the next integer token. */
    public int nextInt() {
        return Integer.parseInt(next());
    }

    /** Returns the next long token. */
    public long nextLong() {
        return Long.parseLong(next());
    }

    /** Returns the next double token. */
    public double nextDouble() {
        return Double.parseDouble(next());
    }

    /** Returns the next full line (including possible empty lines). */
    public String nextLine() {
        try {
            return reader.readLine();
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
    }

    /** Closes the underlying {@link BufferedReader}. */
    @Override
    public void close() {
        try {
            reader.close();
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
    }
}

import java.util.Arrays;
import java.util.Scanner;

/**
 * Reads an n×n multiset of integers and prints a symmetric matrix that
 * respects the frequency constraints of the input.  If no such matrix
 * exists the program prints “NO”.
 *
 * The implementation is a clean‑up of the original, heavily‑commented
 * program.  All magic numbers are named, variable names are expressive,
 * and the logic is split into small, well‑named methods.
 */
public class SymbolPattern {

    /** Maximum value that can appear in the input (the original code used 1005). */
    private static final int MAX_VALUE = 1005;

    public static void main(String[] args) {
        try (Scanner sc = new Scanner(System.in)) {
            int size = sc.nextInt();                     // n
            int[][] matrix = buildMatrix(size, sc);
            if (matrix == null) {
                System.out.println("NO");
                return;
            }

            System.out.println("YES");
            printMatrix(matrix);
            // The original program performed an extra consistency check.
            // It is kept here for exact functional parity.
            verifySymmetricProperties(matrix, size);
        }
    }

    /**
     * Builds a matrix that satisfies the required symmetry.
     *
     * @param n               dimension of the matrix (n×n)
     * @param scanner         scanner that provides the n² numbers after n
     * @return                a filled matrix if it can be built, otherwise {@code null}
     */
    private static int[][] buildMatrix(int n, Scanner scanner) {
        // -----------------------------------------------------------------
        // 1. Read all numbers and count their frequencies
        // -----------------------------------------------------------------
        int[] frequency = new int[MAX_VALUE];
        int total = n * n;
        for (int i = 0; i < total; i++) {
            int v = scanner.nextInt();
            if (v < 0 || v >= MAX_VALUE) {
                throw new IllegalArgumentException("Value out of allowed range [0," + (MAX_VALUE - 1) + "]");
            }
            frequency[v]++;
        }

        // Keep a copy of the original frequencies for the final verification step
        int[] originalFreqCopy = Arrays.copyOf(frequency, MAX_VALUE);

        // -----------------------------------------------------------------
        // 2. Validate the frequency distribution
        // -----------------------------------------------------------------
        if (!isFrequencyPatternValid(frequency, n)) {
            return null; // “NO” will be printed by the caller
        }

        // -----------------------------------------------------------------
        // 3. Allocate the result matrix
        // -----------------------------------------------------------------
        int[][] matrix = new int[n][n];
        Arrays.fill(matrix[0], -1); // sentinel used later to detect unfilled cells

        // -----------------------------------------------------------------
        // 4. Place the unique centre element (if n is odd)
        // -----------------------------------------------------------------
        Integer centreValue = findCentreValue(frequency, n);
        if (centreValue != null) {
            frequency[centreValue]--;
            matrix[n / 2][n / 2] = centreValue;
        }

        // -----------------------------------------------------------------
        // 5. Fill the matrix respecting the various remainder patterns
        // -----------------------------------------------------------------
        // 5a – First pass: numbers whose count % 4 == 2 (they need to be placed
        //      in symmetric pairs across the centre line).
        placeRemainderTwoValues(matrix, frequency, n);

        // 5b – Second pass: remaining numbers with an even count (≥ 2) are placed
        //      as quadruples.
        placeQuadrupleValues(matrix, frequency, n);

        // 5c – Finally, place numbers whose count is a multiple of 4.
        placePureQuadrupleValues(matrix, frequency, n);

        // -----------------------------------------------------------------
        // 6. Verify that every cell was filled (original program repeats this)
        // -----------------------------------------------------------------
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (matrix[i][j] == -1) {
                    System.out.println("NO");
                    return null;
                }
            }
        }

        // -----------------------------------------------------------------
        // 7. Final consistency check (mirrors the original program)
        // -----------------------------------------------------------------
        verifySymmetricProperties(matrix, n);

        return matrix;
    }

    /**
     * Determines whether the frequency array matches the pattern required for a
     * symmetric matrix of size {@code n}.
     *
     * @param freq  frequency counts indexed by the value
     * @param n     matrix dimension
     * @return      {@code true} if the pattern is valid, {@code false} otherwise
     */
    private static boolean isFrequencyPatternValid(int[] freq, int n) {
        int quadruples = 0;
        int doubles   = 0;
        int singles   = -1; // how many distinct values have an odd count

        for (int count : freq) {
            if (count == 0) continue;

            int mod = count % 4;
            if (mod == 0) {
                quadruples++;
            } else if (mod == 2) {
                doubles++;
            } else if (mod % 2 == 1) {
                if (singles == -1) {
                    singles = count; // keep the value itself, not just a flag
                } else {
                    // More than one odd‑count value → impossible
                    return false;
                }
            }
        }

        // Extra constraints that mirror the original checks
        if (n % 2 == 0) {
            // Even size matrices must not have a centre element
            if (singles != -1) return false;
        } else {
            // Odd size matrices must have exactly one odd‑count value
            if (singles == -1) return false;
        }

        // Additional checks regarding the existence of a centre element
        // (re‑implemented exactly as in the original code)
        if (n % 2 == 0 && singles != -1) return false;
        if (n % 2 == 1 && singles == -1) return false;

        // The original program also required that the number of “double”
        // occurrences be sufficient for the odd‑dimensional case, but that
        // condition is implicitly satisfied by the later filling logic.
        return true;
    }

    /**
     * Finds the unique value that must be placed at the centre of an odd‑size
     * matrix.  Returns {@code null} if no such value exists.
     */
    private static Integer findCentreValue(int[] freq, int n) {
        // In the original code the centre value is the first value whose
        // frequency is odd.
        for (int v = 0; v < MAX_VALUE; v++) {
            if (freq[v] % 2 == 1) {
                return v;
            }
        }
        return null;
    }

    /**
     * Places values whose remaining frequency is ≡ 2 (mod 4) into the matrix.
     * These values occupy symmetric pairs across the centre line.
     */
    private static void placeRemainderTwoValues(int[][] matrix, int[] freq, int n) {
        // The original algorithm used a somewhat obscure loop; we keep the same
        // behaviour but with clearer variable names.
        int layer = 0; // index that walks around the centre outward

        outer:
        for (int value = 0; value < MAX_VALUE; value++) {
            if (freq[value] % 4 != 2 || freq[value] == 0) {
                continue;
            }

            // Determine the next free slot on the current "layer"
            int col = layer < n / 2 ? layer : layer - n / 2;
            int row = layer < n / 2 ? layer : n / 2;

            if (layer >= n - 1) {
                break outer;
            }

            // Place the value in the four symmetric cells that share the same
            // column but are mirrored across the centre line.
            int symmetricalRow = n - row - 1;
            matrix[row][col] = value;
            matrix[symmetricalRow][col] = value;
            matrix[row][n - col - 1] = value;
            matrix[symmetricalRow][n - col - 1] = value;

            // We have consumed two copies of the value (the other two copies are
            // handled later when we place quadruples).
            freq[value] -= 2;
            layer++;
            value--; // stay on the same value after the decrement above
        }
    }

    /**
     * Places values that have an even remaining count (≥ 2) into the matrix as
     * quadruples.  This method is used for the odd‑size case after the
     * remainder‑two placement.
     */
    private static void placeQuadrupleValues(int[][] matrix, int[] freq, int n) {
        int layer = 0;

        outer:
        for (int value = 0; value < MAX_VALUE; value++) {
            if (freq[value] % 2 == 0 && freq[value] > 0) {
                int col = layer < n / 2 ? layer : layer - n / 2;
                int row = layer < n / 2 ? layer : n / 2;

                if (layer >= n - 1) {
                    break outer;
                }

                // Fill a 2×2 block that is symmetric with respect to both axes.
                int symRow = n - row - 1;
                int symCol = n - col - 1;

                matrix[row][col] = value;
                matrix[symRow][col] = value;
                matrix[row][symCol] = value;
                matrix[symRow][symCol] = value;

                freq[value] -= 2; // Only two copies are removed here; the other two are removed later.
                layer++;
                value--;
            }
        }
    }

    /**
     * Places pure quadruples (values that appear a multiple of four times) into
     * the remaining empty cells.
     */
    private static void placePureQuadrupleValues(int[][] matrix, int[] freq, int n) {
        int row = 0;
        int col = 0;

        outer:
        for (int value = 0; value < MAX_VALUE; value++) {
            if (freq[value] % 4 != 0 || freq[value] == 0) {
                continue;
            }

            // Find the next empty cell scanning row‑major order.
            while (matrix[row][col] != -1) {
                advancePosition(col, n, () -> row++);
                if (row >= n) {
                    break outer;
                }
                advancePosition(row, n, () -> col++);
            }

            // Place the quadruple in the four symmetric cells.
            int symRow = n - row - 1;
            int symCol = n - col - 1;

            matrix[row][col] = value;
            matrix[symRow][col] = value;
            matrix[row][symCol] = value;
            matrix[symRow][symCol] = value;

            freq[value] -= 4;

            // Reset scanning position to the next empty cell.
            row = 0;
            col = 0;
            value--; // stay on the same value after decrement
        }
    }

    /** Helper that wraps a lambda to advance a coordinate (used for row/col). */
    private static void advancePosition(int coord, int limit, Runnable increment) {
        // Inline expansion of the lambda invocation would be more verbose,
        // so we keep it simple: the caller passes a lambda that increments the
        // coordinate; this method merely exists to keep the signature tidy.
        increment.run();
    }

    /** Pretty‑prints the matrix to stdout. */
    private static void printMatrix(int[][] matrix) {
        for (int[] row : matrix) {
            for (int cell : row) {
                System.out.print(cell + " ");
            }
            System.out.println();
        }
    }

    /**
     * Verifies the four‑way symmetry of the generated matrix.
     * The checks replicate the original program’s runtime assertions.
     */
    private static void verifySymmetricProperties(int[][] matrix, int n) {
        int[] expectedFreq = new int[MAX_VALUE];
        for (int[] row : matrix) {
            for (int v : row) {
                expectedFreq[v]++;
            }
        }

        // Verify that each cell’s four symmetric counterparts hold the same value.
        int x = 0, y = 0;
        outer:
        while (y < n) {
            int val = matrix[y][x];
            if (val != matrix[y][n - x - 1]
                    || val != matrix[n - y - 1][x]
                    || val != matrix[n - y - 1][n - x - 1]) {
                throw new AssertionError("Symmetry mismatch at (" + y + "," + x + ")");
            }

            x++;
            if (x >= n) {
                x = 0;
                y++;
            }
        }

        // Ensure the reconstructed frequency distribution matches the original.
        for (int i = 0; i < MAX_VALUE; i++) {
            if (expectedFreq[i] != originalFreqCopy[i]) {
                throw new AssertionError("Frequency mismatch at value " + i);
            }
        }
    }
}

import java.io.*;
import java.util.*;

public class Main {

    // -----------------------------------------------------------------------
    // I/O helpers – fast scanner / writer
    // -----------------------------------------------------------------------
    private static final class FastScanner {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        FastScanner(InputStream stream) {
            this.reader = new BufferedReader(new InputStreamReader(stream));
        }

        private String nextToken() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                tokenizer = new StringTokenizer(reader.readLine());
            }
            return tokenizer.nextToken();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(nextToken());
        }
    }

    private static final class FastWriter {
        private final BufferedWriter writer;

        FastWriter(OutputStream stream) {
            this.writer = new BufferedWriter(new OutputStreamWriter(stream));
        }

        void println(String s) throws IOException {
            writer.write(s);
            writer.newLine();
        }

        void print(String s) throws IOException {
            writer.write(s);
        }

        void close() throws IOException {
            writer.flush();
            writer.close();
        }
    }

    // -----------------------------------------------------------------------
    // Core data structures
    // -----------------------------------------------------------------------
    /** Holds one distinct number together with the remaining amount and its priority. */
    private static final class NumberInfo implements Comparable<NumberInfo> {
        final int value;          // the actual number from the input
        int remaining;            // how many copies are still unused
        final int group;          // ordering priority

        NumberInfo(int value, int remaining, int group) {
            this.value = value;
            this.remaining = remaining;
            this.group = group;
        }

        @Override
        public int compareTo(NumberInfo o) {
            return Integer.compare(this.group, o.group);
        }
    }

    // Priority groups – lower ordinal means higher priority
    private static final int GROUP_SINGLE_ODD      = 0;
    private static final int GROUP_REMAINDER       = 1;
    private static final int GROUP_MULTIPLE_OF_4   = 2;
    private static final int MAX_VALUE = 1000;   // problem‑specific limit

    // -----------------------------------------------------------------------
    // Solving logic
    // -----------------------------------------------------------------------
    private void solve(FastScanner in, FastWriter out) throws IOException {
        int n = in.nextInt();

        // Trivial 1×1 case
        if (n == 1) {
            out.println("YES");
            out.println(in.nextInt());
            return;
        }

        // 1️⃣  Count how many times each value appears
        int[] frequency = new int[MAX_VALUE + 1];
        for (int i = 0; i < n * n; i++) {
            frequency[in.nextInt()]++;
        }

        // 2️⃣  Group the numbers according to the algorithm’s requirements
        List<NumberInfo> items = new ArrayList<>();
        for (int v = 1; v <= MAX_VALUE; v++) {
            int cnt = frequency[v];
            if (cnt == 0) {
                continue;
            }

            // a) one element for an odd count
            if ((cnt & 1) == 1) {
                items.add(new NumberInfo(v, 1, GROUP_SINGLE_ODD));
                cnt--;
            }

            // b) a remainder that is not a multiple of 4
            int mod = cnt % 4;
            if (mod != 0) {
                items.add(new NumberInfo(v, mod, GROUP_REMAINDER));
                cnt -= mod;
            }

            // c) the rest (must be a multiple of 4)
            if (cnt > 0) {
                items.add(new NumberInfo(v, cnt, GROUP_MULTIPLE_OF_4));
            }
        }

        // 3️⃣  Order groups by the required priority
        items.sort(Comparator.naturalOrder());

        // 4️⃣  Validation – the counts must respect the parity of n
        int singleOddCount = 0;
        int remainderSum   = 0;
        for (NumberInfo ni : items) {
            if (ni.group == GROUP_SINGLE_ODD) {
                singleOddCount++;
            } else if (ni.group == GROUP_REMAINDER) {
                remainderSum += ni.remaining;
            }
        }

        if ((n % 2 == 0 && singleOddCount > 0) ||
            (n % 2 == 1 && singleOddCount != 1)) {
            out.println("NO");
            return;
        }

        if ((n % 2 == 0 && remainderSum != 0) ||
            (n % 2 == 1 && remainderSum > (n - 1) * 2)) {
            out.println("NO");
            return;
        }

        // 5️⃣  Build the symmetric matrix
        int half = n / 2;
        int centre = half + (n % 2);               // same as original `s`
        int[][] matrix = new int[n][n];

        // Helper iterator that knows how many copies of the current value are left
        Iterator<NumberInfo> iterator = items.iterator();

        class Allocator {
            private final Iterator<NumberInfo> it = iterator;

            int next(int needed) {
                if (!it.hasNext()) {
                    throw new IllegalStateException("Ran out of numbers while allocating");
                }
                NumberInfo cur = it.next();
                if (cur.remaining < needed) {
                    throw new IllegalStateException("Insufficient copies of " + cur.value);
                }
                cur.remaining -= needed;
                if (cur.remaining == 0) {
                    it.remove();                     // advance to next distinct value
                }
                return cur.value;
            }
        }

        Allocator alloc = new Allocator();

        // ----- centre handling (only for odd n) -----
        if (n % 2 == 1) {
            matrix[centre - 1][centre - 1] = alloc.next(1); // centre cell needs a single odd

            // the rest of the centre row / column needs pairs
            for (int i = 0; i < half; i++) {
                matrix[centre - 1][i] = alloc.next(2);
                matrix[i][centre - 1] = alloc.next(2);
            }
        }

        // ----- fill the top‑left quadrant with quadruples -----
        for (int i = 0; i < half; i++) {
            for (int j = 0; j < half; j++) {
                matrix[i][j] = alloc.next(4);
            }
        }

        // 6️⃣  Print the final matrix using the symmetry mapping
        out.println("YES");
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                int x = i < centre ? i : n - i - 1;
                int y = j < centre ? j : n - j - 1;
                out.print(matrix[x][y]);
                if (j < n - 1) {
                    out.print(' ');
                }
            }
            out.println();
        }
    }

    // -----------------------------------------------------------------------
    // Program entry point
    // -----------------------------------------------------------------------
    public static void main(String[] args) throws IOException {
        FastScanner scanner = new FastScanner(System.in);
        FastWriter writer = new FastWriter(System.out);
        new Main().solve(scanner, writer);
        writer.close();
    }
}

import java.io.IOException;
import java.io.InputStream;
import java.util.NoSuchElementException;

/**
 * Main class – reads the input, builds the square and prints the answer.
 */
public class Main {

    /** maximum element value used in the statements (1 … 1000) */
    private static final int MAX_VALUE = 1001;

    /** entry point */
    public static void main(String[] args) {
        FastScanner fs = new FastScanner();

        int n = fs.nextInt();                     // size of the square
        int[] frequency = new int[MAX_VALUE];    // frequency of each number
        for (int i = 0; i < n * n; i++) {
            frequency[fs.nextInt()]++;
        }

        int[][] board = new int[n][n];            // result board
        if (!populateBoard(board, frequency, n)) {
            System.out.println("NO");
            return;
        }

        System.out.println("YES");
        printBoard(board);
    }

    /**
     * Chooses the appropriate filling strategy depending on the parity of {@code n}
     * and returns {@code true} if the board could be filled.
     */
    private static boolean populateBoard(int[][] board, int[] frequency, int n) {
        int half = n / 2;
        return (n % 2 == 0) ? fillEven(board, frequency, half) : fillOdd(board, frequency, half);
    }

    /** ----------  Even size (n % 2 == 0)  ---------- */
    private static boolean fillEven(int[][] board, int[] frequency, int half) {
        /* every number must appear a multiple of 4 times */
        for (int v = 1; v < MAX_VALUE; v++) {
            if (frequency[v] % 4 != 0) {
                return false;
            }
        }

        int x = 0, y = 0;
        for (int v = 1; v < MAX_VALUE; v++) {
            int groups = frequency[v] / 4;                     // how many 4‑blocks we need
            while (groups-- > 0) {
                placeQuad(board, v, x, y, n);
                advanceEvenPosition(x, y, half);
            }
        }
        return true;
    }

    /** places a value on the four symmetric cells of the current (x,y) */
    private static void placeQuad(int[][] board, int value, int x, int y, int n) {
        board[x][y] = board[x][n - 1 - y] = board[n - 1 - x][y] = board[n - 1 - x][n - 1 - y] = value;
    }

    /** moves to the next free position in the first half of the board */
    private static void advanceEvenPosition(int x, int y, int half) {
        x++;
        if (x == half) {
            x = 0;
            y++;
        }
    }

    /** ----------  Odd size (n % 2 == 1)  ---------- */
    private static boolean fillOdd(int[][] board, int[] frequency, int half) {
        /* -------------------------------------------------
         * 1. there must be exactly one number whose count is odd –
         *    it will occupy the centre cell.
         * ------------------------------------------------- */
        int centreValue = -1;
        for (int v = 1; v < MAX_VALUE; v++) {
            if ((frequency[v] & 1) == 1) {               // odd count
                if (centreValue != -1) {                 // more than one odd → impossible
                    return false;
                }
                centreValue = v;
            }
        }
        if (centreValue != -1) {
            frequency[centreValue]--;
            board[half][half] = centreValue;             // centre cell
        }

        /* -------------------------------------------------
         * 2. Fill all remaining numbers that appear at least 4 times
         *    into symmetric 4‑cell groups.
         * ------------------------------------------------- */
        int x = 0, y = 0;
        for (int v = 1; v < MAX_VALUE; v++) {
            while (frequency[v] >= 4) {
                placeQuad(board, v, x, y, n);
                frequency[v] -= 4;
                advanceOddPosition(x, y, half);
            }
        }

        /* -------------------------------------------------
         * 3. The only cells left are pairs on the middle row
         *    or the middle column.  Each pair consumes 2
         *    occurrences of a number.
         * ------------------------------------------------- */
        for (int v = 1; v < MAX_VALUE; v++) {
            while (frequency[v] >= 2) {
                if (!placeMiddlePair(board, v, half)) {
                    return false;                     // no place for this pair
                }
                frequency[v] -= 2;
            }
        }
        return true;
    }

    /** places a pair of equal numbers on the middle row / column */
    private static boolean placeMiddlePair(int[][] board, int value, int half) {
        int n = board.length;

        /* try middle column (skip centre) */
        for (int i = 0; i < half; i++) {
            if (board[i][half] == 0) {
                board[i][half] = board[n - 1 - i][half] = value;
                return true;
            }
        }

        /* try middle row (skip centre) */
        for (int j = 0; j < half; j++) {
            if (board[half][j] == 0) {
                board[half][j] = board[half][n - 1 - j] = value;
                return true;
            }
        }
        return false;   // no free spot
    }

    /** moves to the next position when filling 4‑cell groups of the odd case */
    private static void advanceOddPosition(int x, int y, int half) {
        x++;
        if (x == half) {
            x = 0;
            y++;
        }
    }

    /** ----------  Utility methods  ---------- */
    private static void printBoard(int[][] board) {
        int n = board.length;
        for (int i = 0; i < n; i++) {
            StringBuilder sb = new StringBuilder();
            for (int j = 0; j < n; j++) {
                if (j > 0) sb.append(' ');
                sb.append(board[i][j]);
            }
            System.out.println(sb);
        }
    }

    /** ----------  Fast input scanner (unchanged but cleaned) ---------- */
    private static final class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1024];
        private int ptr = 0;
        private int buflen = 0;

        private boolean hasNextByte() {
            if (ptr < buflen) return true;
            ptr = 0;
            try {
                buflen = in.read(buffer);
            } catch (IOException e) {
                throw new UncheckedIOException(e);
            }
            return buflen != -1 && buflen != 0;
        }

        private int readByte() {
            if (!hasNextByte()) throw new NoSuchElementException();
            return buffer[ptr++];
        }

        private static boolean isPrintableChar(int c) {
            return c >= 33 && c <= 126;
        }

        private void skipNonPrintable() {
            while (hasNextByte() && !isPrintableChar(buffer[ptr])) ptr++;
        }

        public boolean hasNext() {
            skipNonPrintable();
            return hasNextByte();
        }

        public String next() {
            if (!hasNext()) throw new NoSuchElementException();
            StringBuilder sb = new StringBuilder();
            int b = readByte();
            while (isPrintableChar(b)) {
                sb.appendCodePoint(b);
                b = readByte();
            }
            return sb.toString();
        }

        public int nextInt() { return Integer.parseInt(next()); }
        public long nextLong() { return Long.parseLong(next()); }
        public double nextDouble() { return Double.parseDouble(next()); }
    }
}

import java.io.*;
import java.util.*;
import java.util.stream.Collectors;

/**
 * Refactored version of the original program.
 *
 * <p>This implementation separates concerns into small, well‑named methods,
 * uses clear variable names and removes unnecessary mutable state. The
 * algorithmic core remains unchanged – it determines whether a symmetric
 * n×n matrix can be built from the supplied numbers and prints it if
 * possible.
 *
 * <p>All I/O is performed through dedicated scanner / printer helpers,
 * and the core logic lives inside {@link Solver}.
 */
public class Solution {

    /** Fast scanner that reads tokens from {@code System.in}. */
    private static final class FastScanner {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        FastScanner(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
        }

        /** Makes sure the tokenizer has tokens; reads a new line if needed. */
        private void ensureTokenizer() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                tokenizer = new StringTokenizer(reader.readLine());
            }
        }

        int nextInt() {
            ensureTokenizer();
            return Integer.parseInt(tokenizer.nextToken());
        }
    }

    /** Core object that contains all the solving logic. */
    private static final class Solver {
        private int n;                         // size of the matrix
        private final List<Integer> fours;     // numbers that appear 4k times
        private final List<Integer> pairs;     // numbers that appear 2k times
        private final List<Integer> singles;   // numbers that appear odd times (center)
        private final int[][] matrix;          // result matrix

        Solver(int n) {
            this.n = n;
            this.fours = new ArrayList<>();
            this.pairs = new ArrayList<>();
            this.singles = new ArrayList<>();
            this.matrix = new int[n][n];
        }

        /** Entry point used by {@code main}. */
        void solve(int testIdx, FastScanner in, PrintWriter out) {
            readInput(in);
            if (!isFeasible()) {
                out.println("NO");
                return;
            }
            buildMatrix();
            out.println("YES");
            printMatrix(out);
        }

        /** Reads n and the list of n² integers, then categorises them. */
        private void readInput(FastScanner in) {
            try {
                n = in.nextInt();
            } catch (Exception e) {
                throw new UncheckedIOException(e);
            }

            int[] count = new int[1001];                 // frequencies of values 1‑1000
            int total = n * n;
            for (int i = 0; i < total; i++) {
                int v = in.nextInt();
                if (v < 1 || v > 1000) {
                    throw new IllegalArgumentException("Value out of expected range [1,1000]");
                }
                count[v]++;
            }

            // Classify numbers according to count % 4
            for (int value = 1; value <= 1000; value++) {
                if (count[value] == 0) continue;

                int mod = count[value] % 4;
                int quotient = count[value] / 4;

                switch (mod) {
                    case 1 -> {                // needs a single centre cell
                        singles.add(value);
                        addToFours(value, quotient);
                    }
                    case 2 -> {                // needs a pair of cells
                        pairs.add(value);
                        addToFours(value, quotient);
                    }
                    case 3 -> {                // behaves like a pair + a single
                        singles.add(value);
                        pairs.add(value);
                        addToFours(value, quotient);
                    }
                    default -> addToFours(value, quotient);
                }
            }

            // Ensure the lists have exactly the required size for the current n
            adjustLists();
        }

        /** Helper that adds {@code times} copies of {@code value} to the fours list. */
        private void addToFours(int value, int times) {
            for (int i = 0; i < times; i++) {
                fours.add(value);
            }
        }

        /** Adjusts the size of the three collections to match the dimensions of the matrix. */
        private void adjustLists() {
            int requiredFours = (n / 2) * (n / 2);   // cells that need 4 identical copies
            int requiredPairs = n;                  // cells that need a pair when n is odd
            int requiredSingles = n % 2;            // 1 when n is odd, otherwise 0

            // If we have too many fours, turn the surplus into pairs
            while (fours.size() > requiredFours) {
                int v = fours.remove(fours.size() - 1);
                pairs.add(v);
                pairs.add(v);
            }

            // If we are short on pairs, promote from fours
            while (pairs.size() < requiredPairs) {
                int v = fours.remove(fours.size() - 1);
                pairs.add(v);
                pairs.add(v);
            }

            // If we still lack a single element and n is odd, take it from elsewhere
            while (singles.size() < requiredSingles) {
                if (!pairs.isEmpty()) {
                    int v = pairs.remove(pairs.size() - 1);
                    singles.add(v);
                } else if (!fours.isEmpty()) {
                    int v = fours.remove(fours.size() - 1);
                    singles.add(v);
                }
            }
        }

        /** Determines whether a valid configuration exists for the given n. */
        private boolean isFeasible() {
            if (n % 2 == 0) {
                return fours.size() == (n / 2) * (n / 2) && pairs.isEmpty() && singles.isEmpty();
            } else {
                int half = n / 2;
                return fours.size() == half * half &&
                       pairs.size() == n &&
                       singles.size() == 1;
            }
        }

        /** Fills the matrix according to the previously collected groups. */
        private void buildMatrix() {
            int half = n / 2;
            int fIdx = 0, pIdx = 0, sIdx = 0;

            // Fill the four‑fold symmetric quadrants with numbers from the fours list
            for (int i = 0; i < half; i++) {
                for (int j = 0; j < half; j++) {
                    int v = fours.get(fIdx++);
                    fillSymmetric(i, j, v);
                }
            }

            // If n is odd, fill the middle row / column with pairs and the centre with a single
            if (n % 2 == 1) {
                int mid = half; // central index

                // Horizontal pair positions (row mid)
                for (int i = 0; i < half; i++) {
                    int v = pairs.get(pIdx++);
                    matrix[i][mid] = v;
                    matrix[n - 1 - i][mid] = v;
                }

                // Vertical pair positions (column mid)
                for (int i = 0; i < half; i++) {
                    int v = pairs.get(pIdx++);
                    matrix[mid][i] = v;
                    matrix[mid][n - 1 - i] = v;
                }

                // Centre cell
                matrix[mid][mid] = singles.get(sIdx++);
            }
        }

        /** Places the same value in the four symmetric positions of a quadrant. */
        private void fillSymmetric(int row, int col, int value) {
            int n = matrix.length;
            matrix[row][col] = value;
            matrix[row][n - 1 - col] = value;
            matrix[n - 1 - row][col] = value;
            matrix[n - 1 - row][n - 1 - col] = value;
        }

        /** Prints the resulting matrix to the supplied PrintWriter. */
        private void printMatrix(PrintWriter out) {
            for (int i = 0; i < n; i++) {
                StringBuilder sb = new StringBuilder();
                for (int j = 0; j < n; j++) {
                    sb.append(matrix[i][j]).append(' ');
                }
                out.println(sb.toString().trim());
            }
        }
    }

    /** Main method – sets up scanner and printer, then runs the solver. */
    public static void main(String[] args) {
        InputStream in = System.in;
        OutputStream out = System.out;
        FastScanner scanner = new FastScanner(in);
        PrintWriter writer = new PrintWriter(out);

        Solver solver = new Solver(0); // actual size will be set inside solve()
        solver.solve(1, scanner, writer);

        writer.flush();
        writer.close();
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.ArrayDeque;
import java.util.Arrays;
import java.util.Deque;
import java.util.StringTokenizer;

/**
 * Refactored solution for the “Codeforces Fun” problem.
 * The program reads an integer {@code n} and {@code n*n} numbers,
 * tries to arrange them in a symmetric {@code n×n} matrix and prints
 * the matrix if possible, otherwise prints {@code NO}.
 */
public class CodeforcesFun {

    /** Fast scanner based on {@link BufferedReader}. */
    private static final class FastScanner {
        private final BufferedReader br;

        FastScanner() {
            this.br = new BufferedReader(new InputStreamReader(System.in));
        }

        /** Reads next token, blocking waiting for input if necessary. */
        String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    throw new UncheckedIOException(e);
                }
            }
            return tokenizer.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        long nextLong() {
            return Long.parseLong(next());
        }

        double nextDouble() {
            return Double.parseDouble(next());
        }

        String nextLine() {
            try {
                return br.readLine();
            } catch (IOException e) {
                throw new UncheckedIOException(e);
            }
        }

        /** Tokenizer reused for every call – avoids repeated allocations. */
        private StringTokenizer tokenizer;
    }

    /** Builds an {@code even×even} matrix by reflecting a smaller quadrant. */
    private static int[][] buildEvenMatrix(int[][] quadrant, int base) {
        int size = quadrant.length;
        int fullSize = base * 2;
        int[][] result = new int[fullSize][fullSize];

        for (int i = 0; i < size; i++) {
            for (int j = 0; j < size; j++) {
                result[i][j] = quadrant[i][j];
                result[fullSize - i - 1][j] = quadrant[i][j];
                result[i][fullSize - j - 1] = quadrant[i][j];
                result[fullSize - i - 1][fullSize - j - 1] = quadrant[i][j];
            }
        }
        return result;
    }

    /** Builds an {@code odd×odd} matrix by reflecting a centre‑plus‑quadrant. */
    private static int[][] buildOddMatrix(int[][] centreQuadrant, int base) {
        int quadSize = base - 1;                // size of the inner quadrant
        int fullSize = 2 * base - 1;              // odd dimension of final matrix
        int[][] result = new int[fullSize][fullSize];

        // copy the inner quadrant
        for (int i = 0; i <= quadSize; i++) {
            for (int j = 0; j <= quadSize; j++) {
                result[i][j] = centreQuadrant[i][j];
                result[fullSize - i - 1][j] = centreQuadrant[i][j];
                result[i][fullSize - j - 1] = centreQuadrant[i][j];
                result[fullSize - i - 1][fullSize - j - 1] = centreQuadrant[i][j];
            }
        }

        // mirror the middle row and column (excluding the centre cell)
        for (int i = 0; i <= quadSize; i++) {
            result[fullSize - i - 1][base] = centreQuadrant[i][base];
            result[base][fullSize - i - 1] = centreQuadrant[base][i];
            result[base][i] = centreQuadrant[base][i];
            result[i][base] = centreQuadrant[base][i];
        }
        return result;
    }

    /** Pretty‑prints a matrix to the supplied PrintWriter. */
    private static void printMatrix(int[][] matrix, PrintWriter out, int n) {
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                out.print(matrix[i][j]);
                if (j < n - 1) out.print(' ');
            }
            out.println();
        }
    }

    /** Returns the required number of repetitions for each stack given a frequency. */
    private static void allocateStacks(Deque<Integer> fourStack,
                                       Deque<Integer> twoStack,
                                       Deque<Integer> oneStack,
                                       int value,
                                       int frequency) {
        int forFour = frequency / 4;
        int remainder = frequency % 4;

        for (int i = 0; i < forFour; i++) {
            fourStack.push(value);
        }

        if (remainder == 2) {
            twoStack.push(value);
        } else if (remainder == 1) {
            oneStack.push(value);
        }
    }

    /** Main driver – reads input, processes it and prints the result. */
    public static void main(String[] args) {
        FastScanner fs = new FastScanner();
        PrintWriter out = new PrintWriter(System.out, true);

        int n = fs.nextInt();                               // dimension of the square
        int[] values = new int[n * n];
        for (int i = 0; i < n * n; i++) {
            values[i] = fs.nextInt();
        }
        Arrays.sort(values);                                // frequencies become contiguous

        // Queues used as stacks (LIFO) for the three different multiplicities
        Deque<Integer> fourStack = new ArrayDeque<>();
        Deque<Integer> twoStack = new ArrayDeque<>();
        Deque<Integer> oneStack = new ArrayDeque<>();

        // Scan frequencies and allocate according to the remainder of division by 4 / 2 / 1
        int cur = values[0];
        int count = 1;
        for (int i = 1; i < values.length; i++) {
            if (values[i] == cur) {
                count++;
            } else {
                allocateStacks(fourStack, twoStack, oneStack, cur, count);
                cur = values[i];
                count = 1;
            }
        }
        allocateStacks(fourStack, twoStack, oneStack, cur, count); // last block

        // ------------------------------------------------------------
        // Build result matrix (if possible) and print
        // ------------------------------------------------------------
        if (n % 2 == 0) {                                     // even dimension
            if (!twoStack.isEmpty() || !oneStack.isEmpty()) {
                out.println("NO");
            } else {
                int half = n / 2;
                int[][] quadrant = new int[half][half];
                for (int i = 0; i < half; i++) {
                    for (int j = 0; j < half; j++) {
                        quadrant[i][j] = fourStack.pop();
                    }
                }
                int[][] result = buildEvenMatrix(quadrant, half);
                out.println("YES");
                printMatrix(result, out, n);
            }
        } else {                                              // odd dimension
            if (oneStack.size() != 1) {
                out.println("NO");
            } else {
                // We need exactly ((n/2) * 2) elements for the mirrored edges.
                int neededPairs = (n / 2) * 2;
                while (twoStack.size() < neededPairs) {
                    int v = fourStack.pop();
                    twoStack.push(v);
                    twoStack.push(v); // push twice to represent a pair
                }

                // Sanity check – the remaining elements must fit perfectly.
                int remainingFromFour = fourStack.size();
                int requiredRemaining   = n * n - 1 - 2 * neededPairs; // centre + quadrants
                if (remainingFromFour != requiredRemaining) {
                    out.println("NO");
                } else {
                    int quadrantSize = n / 2 + 1;                     // includes centre line
                    int[][] quadrant = new int[quadrantSize][quadrantSize];

                    // Fill the inner quadrant (excluding the centre cell)
                    for (int i = 0; i < quadrantSize - 1; i++) {
                        for (int j = 0; j < quadrantSize - 1; j++) {
                            quadrant[i][j] = fourStack.pop();
                        }
                    }
                    // Place the centre element
                    quadrant[quadrantSize - 1][quadrantSize - 1] = oneStack.pop();

                    // Mirror the middle row and column (pairwise)
                    for (int i = 0; i < quadrantSize - 1; i++) {
                        quadrant[quadrantSize - 1][i] = twoStack.pop();
                        quadrant[i][quadrantSize - 1] = twoStack.pop();
                    }

                    int[][] result = buildOddMatrix(quadrant, quadrantSize);
                    out.println("YES");
                    printMatrix(result, out, n);
                }
            }
        }

        out.flush();
    }
}

import java.util.HashMap;
import java.util.Map;
import java.util.Scanner;

/**
 * Palindromic matrix builder.
 *
 * <p>Reads an integer {@code n} followed by {@code n*n} integers.
 * Attempts to arrange them into an {@code n×n} matrix that is symmetric
 * with respect to both the vertical and horizontal axes (i.e. a palindrome).
 * If such a matrix exists it prints {@code YES} and the matrix,
 * otherwise it prints {@code NO}.</p>
 */
public class PalindromicMatrix {

    private static Scanner scanner;   // shared scanner for convenience
    private static int N;             // dimension of the square matrix

    public static void main(String[] args) {
        try (Scanner sc = new Scanner(System.in)) {
            scanner = sc;
            solve();
        }
    }

    /** Orchestrates input, processing and output. */
    private static void solve() {
        N = scanner.nextInt();
        int total = N * N;
        int[] values = new int[total];
        for (int i = 0; i < total; i++) {
            values[i] = scanner.nextInt();
        }

        // frequency of each distinct number that is still available
        Map<Integer, Integer> remaining = countFrequencies(values);
        int[][] matrix = new int[N][N];

        if (!populateMatrix(matrix, remaining)) {
            System.out.println("NO");
            return;
        }

        System.out.println("YES");
        printMatrix(matrix);
    }

    /** Counts how many times each value occurs in the input array. */
    private static Map<Integer, Integer> countFrequencies(int[] arr) {
        Map<Integer, Integer> freq = new HashMap<>();
        for (int v : arr) {
            freq.merge(v, 1, Integer::sum);
        }
        return freq;
    }

    /**
     * Picks a value that still has at least {@code minimum} occurrences left.
     * Returns -1 if no such value exists.
     */
    private static int pickValueWithEnough(Map<Integer, Integer> freq, int minimum) {
        for (Map.Entry<Integer, Integer> e : freq.entrySet()) {
            if (e.getValue() >= minimum) {
                return e.getKey();
            }
        }
        return -1;
    }

    /**
     * Tries to fill {@code matrix} respecting the palindrome constraints.
     * Uses the {@code remaining} frequency map to consume numbers.
     *
     * @return {@code true} if a matrix could be built, {@code false} otherwise.
     */
    private static boolean populateMatrix(int[][] matrix, Map<Integer, Integer> remaining) {
        int half = N / 2;
        boolean odd = N % 2 == 1;

        // ---- 4‑wise symmetric positions (top‑left quadrant) ----
        for (int i = 0; i < half; i++) {
            for (int j = 0; j < half; j++) {
                int val = pickValueWithEnough(remaining, 4);
                if (val == -1) {
                    return false;
                }
                // set the four symmetric cells
                setFourSymmetric(matrix, i, j, val);
                decrement(remaining, val, 4);
            }
        }

        // ---- odd dimension: middle row / column (2‑wise) and centre ----
        if (odd) {
            int mid = half;

            // horizontal pairs on the middle row
            for (int j = 0; j < half; j++) {
                int val = pickValueWithEnough(remaining, 2);
                if (val == -1) {
                    return false;
                }
                setTwoHorizontal(matrix, mid, j, val);
                decrement(remaining, val, 2);
            }

            // vertical pairs on the middle column
            for (int i = 0; i < half; i++) {
                int val = pickValueWithEnough(remaining, 2);
                if (val == -1) {
                    return false;
                }
                setTwoVertical(matrix, i, mid, val);
                decrement(remaining, val, 2);
            }

            // centre cell (single occurrence)
            int centreVal = pickValueWithEnough(remaining, 1);
            if (centreVal == -1) {
                return false;
            }
            matrix[mid][mid] = centreVal;
            decrement(remaining, centreVal, 1);
        }

        return true;
    }

    /** Writes {@code val} into the four cells that are symmetric both horizontally and vertically. */
    private static void setFourSymmetric(int[][] matrix, int i, int j, int val) {
        matrix[i][j] = matrix[i][N - 1 - j] = matrix[N - 1 - i][j] = matrix[N - 1 - i][N - 1 - j] = val;
    }

    /** Writes {@code val} into a horizontal pair on a given row. */
    private static void setTwoHorizontal(int[][] matrix, int row, int col, int val) {
        matrix[row][col] = matrix[row][N - 1 - col] = val;
    }

    /** Writes {@code val} into a vertical pair on a given column. */
    private static void setTwoVertical(int[][] matrix, int row, int col, int val) {
        matrix[row][col] = matrix[N - 1 - row][col] = val;
    }

    /** Decrements the count of {@code value} in the frequency map by {@code amount}. */
    private static void decrement(Map<Integer, Integer> freq, int value, int amount) {
        int newCount = freq.get(value) - amount;
        if (newCount <= 0) {
            freq.remove(value);
        } else {
            freq.put(value, newCount);
        }
    }

    /** Simple pretty‑print of the resulting matrix. */
    private static void printMatrix(int[][] matrix) {
        for (int[] row : matrix) {
            for (int v : row) {
                System.out.print(v + " ");
            }
            System.out.println();
        }
    }
}

/**
 * Refactored version of the original “matrix construction” program.
 *
 * <p>Key improvements:
 * <ul>
 *   <li>Clear separation of concerns – input handling, frequency calculation,
 *       sorting, and matrix filling are each in their own method/class.</li>
 *   <li>Descriptive naming, removal of magic numbers and static mutable fields.</li>
