 *   <li>Encapsulation of the priority logic inside {@link PriorityCalculator}.</li>
 *   <li>No reliance on global mutable state; all state is passed explicitly.</li>
 * </ul>
 *
 * <p>The program still follows the original algorithm (filling a square matrix
 * according to a fixed pattern) but is now easier to read, test and maintain.
 */
public class Main {

    /** Maximum possible value of an element (as in the original code). */
    private static final int MAX_VALUE = 1_000;

    /** Where the matrix should be printed when a solution exists. */
    private static final String SOLUTION = "YES";

    /** Where the program should print failure indication. */
    private static final String NO_SOLUTION = "NO";

    /** Entry point. */
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int n = scanner.nextInt();               // size of the square matrix
        int[] frequencies = readInputValues(scanner, n * n);
        List<FrequencyData> frequencyData = buildFrequencyData(frequencies);
        PriorityCalculator.sortByPriority(frequencyData);

        int[][] matrix = new int[n][n];
        boolean successful = MatrixBuilder.fillMatrix(matrix, frequencyData);

        if (successful) {
            System.out.println(SOLUTION);
            printMatrix(matrix);
        } else {
            System.out.println(NO_SOLUTION);
        }

        scanner.close();
    }

    /** Reads the next {@code count} integers from the scanner and updates a frequency table. */
    private static int[] readInputValues(Scanner scanner, int count) {
        int[] frequencies = new int[MAX_VALUE + 1]; // 1‑based indexing, same as original
        for (int i = 0; i < count; i++) {
            int value = scanner.nextInt();
            frequencies[value - 1]++;               // original code uses 0‑based array index
        }
        return frequencies;
    }

    /** Converts the frequency table into {@link FrequencyData} objects (ignoring zero frequencies). */
    private static List<FrequencyData> buildFrequencyData(int[] frequencies) {
        List<FrequencyData> data = new ArrayList<>();
        for (int i = 0; i < frequencies.length; i++) {
            if (frequencies[i] > 0) {
                data.add(new FrequencyData(i + 1, frequencies[i]));
            }
        }
        return data;
    }

    /** Prints a matrix to stdout in the same format as the original program. */
    private static void printMatrix(int[][] matrix) {
