/**
 * Holds a distinct value and its remaining occurrence count after each placement.
 */
class FrequencyData {
    final int value;          // the actual number (1‑based as in the original input)
    int remaining;            // how many times this value can still be placed

    FrequencyData(int value, int count) {
        this.value = value;
        this.remaining = count;
    }
}

/**
 * Encapsulates the priority calculation that determines the order in which
 * values should be tried for placement.
 *
 * <p>The algorithm mirrors the original implementation:
 * <ul>
 *   <li>odd counts → priority 0</li>
 *   <li>counts divisible by 4 → priority {@code 400 * count}</li>
 *   <li>all other counts → priority {@code count}</li>
 * </ul>
 */
class PriorityCalculator {

    /** Sorts the supplied list according to the defined priority order (in‑place). */
    static void sortByPriority(List<FrequencyData> data) {
        data.sort((d1, d2) -> {
            int p1 = calculatePriority(d1.remaining);
            int p2 = calculatePriority(d2.remaining);
            return Integer.compare(p1, p2);
        });
    }

    /** Calculates the priority for a given remaining count (identical to the original). */
    private static int calculatePriority(int count) {
        if (count % 2 != 0) {
            return 0;
        }
        if (count % 4 == 0) {
            return 400 * count;
        }
        return count;
    }
}

/**
 * Contains all logic required to fill the matrix following the pattern used
 * in the original program.
 */
class MatrixBuilder {

    /** Entry point – attempts to fill the matrix using the provided data. */
    static boolean fillMatrix(int[][] matrix, List<FrequencyData> data) {
        // The original code treats odd matrix sizes specially (center cell).
        if (matrix.length % 2 == 1) {
            fillCenter(matrix, data);
            fillMiddle(matrix, data);
        } else {
            fillSymmetric(matrix, data);
        }
        // If any placement failed, the method returns false.
        return data.stream().allMatch(d -> d.remaining == 0);
    }

    /** Places the first (highest‑priority) element into the exact centre of an odd‑sized matrix. */
    private static void fillCenter(int[][] matrix, List<FrequencyData> data) {
        int mid = matrix.length / 2;
        // There must be at least one element with count ≥ 1 to occupy the centre.
        FrequencyData centreElement = findFirstWithMinCount(data, 1);
        if (centreElement == null) {
            throw new IllegalStateException("No element available for centre placement");
        }
        matrix[mid][mid] = centreElement.value;
        centreElement.remaining--;
    }

    /** Fills the “middle” rows/columns for both odd and even sized matrices. */
    private static void fillMiddle(int[][] matrix, List<FrequencyData> data) {
        int mid = matrix.length / 2;
        // First pass – fill symmetric positions on the middle row/column.
        placeSymmetricPairs(matrix, data, mid, Direction.VERTICAL);
        // Second pass – fill symmetric positions on the middle column/row.
        placeSymmetricPairs(matrix, data, mid, Direction.HORIZONTAL);
    }

    /** Fills the four‑quadrant symmetric positions for even‑sized matrices. */
    private static void fillSymmetric(int[][] matrix, List<FrequencyData> data) {
        int half = matrix.length / 2;
        placeSymmetricPairs(matrix, data, half, Direction.BOTH);
    }

    /**
     * Places pairs of symmetric cells (horizontally and/or vertically) using the
     * highest‑priority element that still has enough remaining occurrences.
     *
     * @param matrix   target matrix
     * @param data     mutable list of frequency data (will be updated)
     * @param pivot    index of the “pivot” row/column (the one used for symmetry)
     * @param dir      which symmetry directions are required
     */
    private static void placeSymmetricPairs(int[][] matrix,
                                            List<FrequencyData> data,
                                            int pivot,
                                            Direction dir) {
        // The original algorithm distinguishes four cases depending on the direction.
        switch (dir) {
            case VERTICAL   -> placeVerticalSymmetric(matrix, data, pivot);
            case HORIZONTAL -> placeHorizontalSymmetric(matrix, data, pivot);
            case BOTH       -> {
                placeVerticalSymmetric(matrix, data, pivot);
                placeHorizontalSymmetric(matrix, data, pivot);
            }
        }
    }

    /** Places symmetric cells on the same column (top/bottom) for a given pivot column. */
    private static void placeVerticalSymmetric(int[][] matrix,
                                               List<FrequencyData> data,
                                               int column) {
        int n = matrix.length;
        for (int i = 0; i < n / 2; i++) {
            int candidateIdx = findFirstWithMinCount(data, 2);
            if (candidateIdx == -1) {
                setFailure(data);
                return;
            }

            FrequencyData fd = data.get(candidateIdx);
            // Assign to the current cell and its vertical counterpart.
            assignAndDecrement(matrix, data, candidateIdx, fd.remaining >= 2 ? 2 : 1);
            if (matrix[n - 1 - i][column] == 0) {
                assignAndDecrement(matrix, data, candidateIdx, fd.remaining >= 1 ? 1 : 0);
            }
        }
    }

    /** Places symmetric cells on the same row (left/right) for a given pivot row. */
    private static void placeHorizontalSymmetric(int[][] matrix,
                                                 List<FrequencyData> data,
                                                 int row) {
        int n = matrix.length;
        for (int i = 0; i < n / 2; i++) {
            int candidateIdx = findFirstWithMinCount(data, 2);
            if (candidateIdx == -1) {
                setFailure(data);
                return;
            }

            FrequencyData fd = data.get(candidateIdx);
            assignAndDecrement(matrix, data, candidateIdx, fd.remaining >= 2 ? 2 : 1);
            if (matrix[row][n - 1 - i] == 0) {
                assignAndDecrement(matrix, data, candidateIdx, fd.remaining >= 1 ? 1 : 0);
            }
        }
    }

    /** Helper that fills the four‑corner symmetric block when both directions are needed. */
    private static void placeSymmetricBlock(int[][] matrix,
                                            List<FrequencyData> data,
                                            int layer) {
        // The original implementation handled the four corners in a single loop,
        // but we delegate to the more primitive placement helpers.
        int n = matrix.length;
        for (int i = 0; i < n / 2; i++) {
            int idx = findFirstWithMinCount(data, 4);
            if (idx == -1) {
                setFailure(data);
                return;
            }
            FrequencyData fd = data.get(idx);
            // Top‑left
            assignAndDecrement(matrix, data, idx, fd.remaining >= 1 ? 1 : 0);
            // Top‑right
            assignAndDecrement(matrix, data, idx, fd.remaining >= 1 ? 1 : 0);
            // Bottom‑left
            assignAndDecrement(matrix, data, idx, fd.remaining >= 1 ? 1 : 0);
            // Bottom‑right
            assignAndDecrement(matrix, data, idx, fd.remaining >= 1 ? 1 : 0);
        }
    }

    /** Finds the first element in {@code data} whose {@code remaining} count is at least {@code min}. */
    private static int findFirstWithMinCount(List<FrequencyData> data, int min) {
        for (int i = 0; i < data.size(); i++) {
            if (data.get(i).remaining >= min) {
                return i;
            }
        }
        return -1; // not found
    }

    /** Marks the whole processing as failed by clearing the data list (mirrors original `judge = 0`). */
    private static void setFailure(List<FrequencyData> data) {
        // Clearing ensures that any later checks (`stream().allMatch`) will see an empty list → failure.
        data.clear();
    }

    /** Places a value into the matrix and decrements the remaining count of the chosen element. */
    private static void assignAndDecrement(List<FrequencyData> data,
                                           int index,
                                           int amount) {
        FrequencyData fd = data.get(index);
        fd.remaining -= amount;
        // Guard against negative remaining – not required by original but defensive.
        if (fd.remaining < 0) {
            fd.remaining = 0;
        }
    }

    /** Enumerates the possible symmetry directions for the placement helpers. */
    private enum Direction {
        VERTICAL,
        HORIZONTAL,
        BOTH
    }
}

/**
 * Refactored version of the original program.
 *
 * The refactor focuses on readability, separation of concerns and proper resource handling.
 * The algorithmic core is unchanged – it still solves the “matrix construction from
 * frequency counts” problem – but the code structure has been modernised.
 *
 * Author:  (refactored by AI)
 * Date:    2025‑11‑03
 */
import java.io.*;
import java.util.*;

public class MatrixBuilder {

    /** Buffered reader for input. */
    private final BufferedReader br;

    /** PrintWriter for output. */
    private final PrintWriter pw;

    /** Tokenizer used by the reader. */
    private StringTokenizer tokenizer;

    /**
     * Constructs a new {@code MatrixBuilder}.
     *
     * @param in  source of input (typically {@code System.in})
     * @param out destination for output (typically {@code System.out})
     */
    public MatrixBuilder(InputStream in, OutputStream out) {
        this.br = new BufferedReader(new InputStreamReader(in));
        this.pw = new PrintWriter(new OutputStreamWriter(out));
    }

    /** Entry point – reads, processes and prints the result. */
    public void solve() throws Exception {
        try {
            int n = readInt();
            int[][] grid = new int[n][n];

            // ----- read all numbers, sort them with radix sort -----
            int[] values = readIntArray(n * n);
            radixSort(values);

            // ----- analyse frequencies -----
            Map<Integer, Integer> frequency = countFrequencies(values);

            // ----- fill the grid according to the parity of n -----
            if (n % 2 == 0) {
                fillEvenOrderGrid(n, frequency, grid);
            } else {
                fillOddOrderGrid(n, frequency, grid);
            }

            // ----- output -----
            pw.println("YES");
            for (int[] row : grid) {
                for (int i = 0; i < row.length; i++) {
                    pw.print(row[i]);
                    if (i + 1 < row.length) {
                        pw.print(' ');
                    }
                }
                pw.println();
            }
        } finally {
            // Ensure resources are closed even if an exception is thrown.
            closeSilently(br);
            closeSilently(pw);
        }
    }

    /** Reads a single token from the input stream. */
    private String nextToken() throws IOException {
        while (tokenizer == null || !tokenizer.hasMoreTokens()) {
            tokenizer = new StringTokenizer(br.readLine());
        }
        return tokenizer.nextToken();
    }

    /** Reads an {@code int} token. */
    private int readInt() throws IOException {
        return Integer.parseInt(nextToken());
    }

    /** Reads a {@code long} token. */
    private long readLong() throws IOException {
        return Long.parseLong(nextToken());
    }

    /** Reads an {@code double} token. */
    private double readDouble() throws IOException {
        return Double.parseDouble(nextToken());
    }

    /** Reads a whole {@code int} array of the supplied length. */
    private int[] readIntArray(int length) throws IOException {
        int[] data = new int[length];
        for (int i = 0; i < length; i++) {
            data[i] = readInt();
        }
        return data;
    }

    /** Counts how many times each distinct integer appears. */
    private static Map<Integer, Integer> countFrequencies(int[] values) {
        Map<Integer, Integer> freq = new HashMap<>();
        for (int v : values) {
            freq.merge(v, 1, Integer::sum);
        }
        return freq;
    }

    /** Performs a two‑pass LSD radix sort on the given array. */
    private static int[] radixSort(int[] values) {
        int[] tmp = new int[values.length];
        // ---- 16‑bit low part ----
        int[] count = new int[65537];
        for (int v : values) {
            count[1 + (v & 0xFFFF)]++;
        }
        for (int i = 1; i <= 65536; i++) {
            count[i] += count[i - 1];
        }
        for (int i = 0; i < values.length; i++) {
            int bucket = 1 + (values[i] & 0xFFFF);
            tmp[count[bucket]++] = values[i];
        }

        // ---- 16‑bit high part ----
        count = new int[65537];
        int[] src = tmp;
        int[] dst = values;
        for (int v : src) {
            count[1 + (v >>> 16)]++;
        }
        for (int i = 1; i <= 65536; i++) {
            count[i] += count[i - 1];
        }
        for (int i = 0; i < src.length; i++) {
            int bucket = 1 + (src[i] >>> 16);
            dst[count[bucket]++] = src[i];
        }
        return dst;
    }

    /** Constructs a grid of even order (n % 2 == 0). */
    private static void fillEvenOrderGrid(int n, Map<Integer, Integer> freq, int[][] grid) {
        // Every value must appear a multiple of 4 times.
        for (int count : freq.values()) {
            if (count % 4 != 0) {
                Arrays.fill(grid[0], -1); // marker for “invalid”
                return;
            }
        }

        int idx = 0;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (grid[i][j] != 0) {
                    continue; // already filled by a previous symmetry
                }
                int val = findValueWithRemainingCount(freq, 4);
                if (val == -1) {
                    Arrays.fill(grid[0], -1);
                    return;
                }
                // place the value on the four symmetric cells
                grid[i][j] = grid[i][n - 1 - j] = grid[n - 1 - i][j] = grid[n - 1 - i][n - 1 - j] = val;
                freq.merge(val, -4, Integer::sum);
            }
        }
    }

    /** Constructs a grid of odd order (n % 2 == 1). */
    private static void fillOddOrderGrid(int n, Map<Integer, Integer> freq, int[][] grid) {
        // Place the centre element (must appear an odd number of times).
        Integer centreVal = findValueWithOddCount(freq);
        if (centreVal != null) {
            int c = n / 2;
            grid[c][c] = centreVal;
            freq.merge(centreVal, -1, Integer::sum);
        } else {
            // No centre candidate -> impossible.
            Arrays.fill(grid[0], -1);
            return;
        }

        // Fill the 4‑cell orbits.
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (grid[i][j] != 0 || (i == n / 2 || j == n / 2)) {
                    continue;
                }
                int val = findValueWithRemainingCount(freq, 4);
                if (val == -1) {
                    Arrays.fill(grid[0], -1);
                    return;
                }
                grid[i][j] = grid[i][n - 1 - j] = grid[n - 1 - i][j] = grid[n - 1 - i][n - 1 - j] = val;
                freq.merge(val, -4, Integer::sum);
            }
        }

        // Fill the arms that consist of exactly two cells.
        fillAxisSegments(n, freq, grid);

        // Finally verify that no cell is left empty.
        if (hasEmptyCell(grid)) {
            Arrays.fill(grid[0], -1);
        }
    }

    /** Picks a value that appears exactly `times` times and removes those occurrences. */
    private static int findValueWithRemainingCount(Map<Integer, Integer> freq, int times) {
        for (Map.Entry<Integer, Integer> e : freq.entrySet()) {
            if (e.getValue() >= times) {
                return e.getKey();
            }
        }
        return -1;
    }

    /** Picks a value that appears an odd number of times (used for centre placement). */
    private static Integer findValueWithOddCount(Map<Integer, Integer> freq) {
        for (Map.Entry<Integer, Integer> e : freq.entrySet()) {
            if (e.getValue() % 2 == 1) {
                return e.getKey();
            }
        }
        return null;
    }

    /** Fills the four axis segments (the middle row/column) for odd `n`. */
    private static void fillAxisSegments(int n, Map<Integer, Integer> freq, int[][] grid) {
        // Horizontal centre row (excluding the centre cell already placed)
        fillPairsAlongAxis(n, n / 2, true, freq, grid);

        // Vertical centre column (excluding the centre cell already placed)
        fillPairsAlongAxis(n, n / 2, false, freq, grid);
    }

    /** Helper that fills symmetric pairs on a given axis line. */
    private static void fillPairsAlongAxis(int n, int axisIdx, boolean isRow, Map<Integer, Integer> freq, int[][] grid) {
        int limit = n / 2 - 1;
        for (int i = 0; i <= limit; i++) {
            if (isRow) {
                // fill positions (axisIdx, i) and (axisIdx, n-1-i)
                int val = findValueWithRemainingCount(freq, 2);
                if (val == -1) {
                    Arrays.fill(grid[0], -1);
                    return;
                }
                grid[axisIdx][i] = grid[axisIdx][n - 1 - i] = val;
                freq.merge(val, -2, Integer::sum);
            } else {
                // fill positions (i, axisIdx) and (n-1-i, axisIdx)
                int val = findValueWithRemainingCount(freq, 2);
                if (val == -1) {
                    Arrays.fill(grid[0], -1);
                    return;
                }
                grid[i][axisIdx] = grid[n - 1 - i][axisIdx] = val;
                freq.merge(val, -2, Integer::sum);
            }
        }
    }

    /** Checks whether any cell of the grid is still unfilled (marked with 0). */
    private static boolean hasEmptyCell(int[][] grid) {
        for (int[] row : grid) {
            for (int cell : row) {
                if (cell == 0) {
                    return true;
                }
            }
        }
        return false;
    }

    /** Closes a Closeable silently (ignores any exception). */
    private static void closeSilently(Closeable c) {
        if (c != null) {
            try {
                c.close();
            } catch (Exception ignored) { }
        }
    }

    // -------------------------------------------------------------------------
    // The following methods are kept from the original source because they are
    // utilities that the refactored code still uses.
    // -------------------------------------------------------------------------

    /** Binary‑search like lower bound for an int array. */
    private static int lowerBound(int[] a, int v) {
        int low = -1, high = a.length;
        while (high - low > 1) {
            int mid = (low + high) >>> 1;
            if (a[mid] >= v) {
                high = mid;
            } else {
                low = mid;
            }
        }
        return high;
    }

    /** Greatest common divisor. */
    private static int gcd(int a, int b) {
        while (b != 0) {
            int tmp = b;
            b = a % b;
            a = tmp;
        }
        return a;
    }

    /** Least common multiple. */
    private static int lcm(int a, int b) {
        return a * (b / gcd(a, b));
    }

    // -------------------------------------------------------------------------

    /** Main method – delegates to the new solver class. */
    public static void main(String[] args) throws Exception {
        try (MatrixBuilder builder = new MatrixBuilder(System.in, System.out)) {
            builder.solve();
        } catch (Throwable e) {
            e.printStackTrace();
            System.exit(1);
        }
    }
}

import java.io.*;
import java.util.*;

public class Main {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter out = new PrintWriter(System.out);
        PalindromicMatrixSolver solver = new PalindromicMatrixSolver();
        solver.solve(reader, out);
        out.close();
    }

    /** Core logic for building a palindromic matrix from the given numbers. */
    static class PalindromicMatrixSolver {

        /** Entry point used by Main. */
        public void solve(FastReader in, PrintWriter out) {
            int n = in.nextInt();                     // matrix dimension
            int[] values = in.nextIntArray(n * n);    // all numbers to place

            if (n == 1) {                               // trivial case
                out.println("YES");
                out.println(values[0]);
                return;
            }

            // 1️⃣  Sort numbers and collect groups of four equal values.
            List<Integer> fourGroups = collectGroupsOfFour(sort(values));

            // 2️⃣  Fill the four‑fold symmetric quadrants.
            int half = n / 2;
            int[][] matrix = new int[n][n];
            ArrayUtils.fill(matrix, -1);               // -1 marks “not placed yet”

            if (!placeFourGroups(matrix, half, fourGroups)) {
                out.println("NO");
                return;
            }

            // 3️⃣  When n is odd we have a central row/column to fill.
            if (n % 2 == 1) {
                handleOddDimension(matrix, half, fourGroups);
            }

            // 4️⃣  Verify that every cell was filled and that the matrix is truly palindromic.
            if (ArrayUtils.isFullyFilled(matrix) && isPalindromic(matrix)) {
                out.println("YES");
                ArrayUtils.printMatrix(out, matrix);
            } else {
                out.println("NO");
            }
        }

        /** Returns a sorted copy of the input array. */
        private static int[] sort(int[] src) {
            int[] copy = src.clone();
            Arrays.sort(copy);
            return copy;
        }

        /**
         * From a sorted array extracts each value {@code count / 4} times,
         * where {@code count} is the number of occurrences of that value.
         * The resulting list holds exactly one representative for each group of four
         * symmetric positions in the matrix.
         */
        private static List<Integer> collectGroupsOfFour(int[] sorted) {
            List<Integer> groups = new ArrayList<>();
            int i = 0;
            while (i < sorted.length) {
                int current = sorted[i];
                int cnt = 0;
                while (i < sorted.length && sorted[i] == current) {
                    cnt++;
                    i++;
                }
                int groupsOfFour = cnt / 4;
                for (int g = 0; g < groupsOfFour; g++) {
                    groups.add(current);
                }
            }
            return groups;
        }

        /**
         * Places numbers from {@code groups} into the matrix occupying the four
         * symmetric cells (i, j), (n‑1‑i, j), (i, n‑1‑j), (n‑1‑i, n‑1‑j).
         * Returns {@code false} if the supplied list does not contain enough values.
         */
        private static boolean placeFourGroups(int[][] matrix, int half, List<Integer> groups) {
            int idx = 0;
            try {
                for (int i = 0; i < half; i++) {
                    for (int j = 0; j < half; j++) {
                        int val = groups.get(idx++);
                        matrix[i][j] = val;
                        matrix[n - 1 - i][j] = val;
                        matrix[i][n - 1 - j] = val;
                        matrix[n - 1 - i][n - 1 - j] = val;
                    }
                }
            } catch (IndexOutOfBoundsException e) {
                return false; // not enough distinct groups
            }
            return true;
        }

        /** Fills the centre row/column when {@code n} is odd. */
        private static void handleOddDimension(int[][] matrix, int half, List<Integer> groups) {
            // Build a temporary list that contains each selected value twice.
            List<Integer> doubled = new ArrayList<>();
            for (int v : groups) {
                doubled.add(v);
                doubled.add(v);
            }

            // Central row (excluding the centre cell)
            for (int j = 0; j < half; j++) {
                int val = doubled.get(j);
                matrix[half][j] = val;
                matrix[half][n - 1 - j] = val;
            }

            // Central column (excluding the centre cell)
            for (int i = 0; i < half; i++) {
                int val = doubled.get(half + i);
                matrix[i][half] = val;
                matrix[n - 1 - i][half] = val;
            }

            // Centre cell itself
            if (!doubled.isEmpty()) {
                matrix[half][half] = doubled.get(doubled.size() - 1);
            }
        }

        /** Checks the four‑fold symmetry required for a palindromic matrix. */
        private static boolean isPalindromic(int[][] matrix) {
            int n = matrix.length;
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < n; j++) {
                    int symI = n - 1 - i;
                    int symJ = n - 1 - j;
                    if (matrix[i][j] != matrix[symI][j] ||
                        matrix[i][j] != matrix[i][symJ] ||
                        matrix[i][j] != matrix[symI][symJ]) {
                        return false;
                    }
                }
            }
            return true;
        }
    }

    /** Fast scanner used for competitive‑programming style input. */
    static class FastReader {
        private final InputStream stream;
        private final byte[] buffer = new byte[8192];
        private int ptr = 0, len = 0;

        FastReader(InputStream stream) {
            this.stream = stream;
        }

        private int readByte() throws IOException {
            if (ptr >= len) {
                len = stream.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c, sign = 1, val = 0;
            do { c = readByte(); } while (isSpaceChar(c));
            if (c == '-') { sign = -1; c = readByte(); }
            do {
                val = val * 10 + (c - '0');
                c = readByte();
            } while (!isSpaceChar(c));
            return val * sign;
        }

        int[] nextIntArray(int size) throws IOException {
            int[] arr = new int[size];
            for (int i = 0; i < size; i++) arr[i] = nextInt();
            return arr;
        }

        private boolean isSpaceChar(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }
    }

    /** Collection of static helpers for array / matrix handling. */
    static class ArrayUtils {

        /** Fills a 2‑D array with the given value (replaces manual loops). */
        static void fill(int[][] array, int value) {
            for (int[] row : array) {
                Arrays.fill(row, value);
            }
        }

        /** Returns {@code true} iff every cell contains a value different from -1. */
        static boolean isFullyFilled(int[][] matrix) {
            for (int[] row : matrix) {
                for (int v : row) {
                    if (v == -1) return false;
                }
            }
            return true;
        }

        /** Prints a single row followed by a line break. */
        static void printArray(PrintWriter out, int[] array) {
            for (int i = 0; i < array.length; i++) {
                if (i > 0) out.print(' ');
                out.print(array[i]);
            }
            out.println();
        }

        /** Prints the whole matrix row‑by‑row. */
        static void printMatrix(PrintWriter out, int[][] matrix) {
            for (int[] row : matrix) {
                printArray(out, row);
            }
        }
    }
}

import java.io.*;
import java.util.*;

public class Boss {

    private static final int MAX_VALUE = 1000;

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();                       // order of the matrix
        int total = n * n;
        int[] values = readValues(sc, total);       // all matrix entries

        int[] count = new int[MAX_VALUE + 1];
        fillFrequency(values, count);

        if (n % 2 == 0) {
            processEvenOrder(n, count);
        } else {
            processOddOrder(n, count);
        }
    }

    /** Reads exactly `count` integer values from the scanner. */
    private static int[] readValues(Scanner sc, int count) {
        int[] arr = new int[count];
        for (int i = 0; i < count; i++) {
            arr[i] = sc.nextInt();
        }
        return arr;
    }

    /** Updates `freq` so that freq[value] holds the occurrences of `value`. */
    private static void fillFrequency(int[] values, int[] freq) {
        Arrays.fill(freq, 0);
        for (int v : values) {
            freq[v]++;
        }
    }

    /** Handles the construction when n is even. */
    private static void processEvenOrder(int n, int[] freq) {
        int requiredGroups = (n * n) / 4;               // how many 4‑tuples we need
        List<Integer> quadNumbers = new ArrayList<>(requiredGroups);

        for (int value = 1; value <= MAX_VALUE && requiredGroups > 0; value++) {
            int available = freq[value] / 4;            // how many full groups of 4 we can take
            int take = Math.min(available, requiredGroups);
            for (int i = 0; i < take; i++) {
                quadNumbers.add(value);
            }
            requiredGroups -= take;
        }

        if (requiredGroups != 0) {
            System.out.println("NO");
            return;
        }

        printEvenMatrix(quadNumbers, n);
    }

    /** Builds and prints the matrix for an even order `n`. */
    private static void printEvenMatrix(List<Integer> numbers, int n) {
        int[][] matrix = new int[n][n];
        int idx = 0;

        // Fill the four quadrants symmetrically
        for (int i = 0; i < n / 2; i++) {
            for (int j = 0; j < n / 2; j++) {
                int val = numbers.get(idx++);
                matrix[i][j] = val;
                matrix[i][n - 1 - j] = val;
                matrix[n - 1 - i][j] = val;
                matrix[n - 1 - i][n - 1 - j] = val;
            }
        }

        printMatrix(matrix);
    }

    /** Handles the construction when n is odd. */
    private static void processOddOrder(int n, int[] freq) {
        int originalN = n;               // keep the odd dimension for later use
        n--;                             // temporarily work with the even size of sub‑matrix
        int requiredQuadGroups = (n * n) / 4;   // groups of 4 symmetric cells
        int requiredDoubleGroups = originalN;   // pairs that will occupy the central cross

        // ---- collect numbers for the 4‑symmetric positions ----
        int[] quadNumbers = new int[requiredQuadGroups];
        int quadIdx = 0;
        for (int value = 1; value <= MAX_VALUE && requiredQuadGroups > 0; value++) {
            int groupsFromValue = freq[value] / 4;
            int take = Math.min(groupsFromValue, requiredQuadGroups);
            Arrays.fill(quadNumbers, value, quadNumbers + take, value);
            // Actually we need to store distinct values, so use a loop:
            // (the above line was a placeholder; real implementation below)
        }
        // Fill the array correctly:
        for (int value = 1; value <= MAX_VALUE && requiredQuadGroups > 0; value++) {
            int groups = freq[value] / 4;
            while (groups > 0 && requiredQuadGroups > 0) {
                quadNumbers[quadIdx++] = value;
                groups--;
                requiredQuadGroups--;
            }
        }

        // ---- collect numbers for the 2‑symmetric positions ----
        int[] doubleNumbers = new int[requiredDoubleGroups];
        int doubleIdx = 0;
        for (int value = 1; value <= MAX_VALUE && requiredDoubleGroups > 0; value++) {
            int pairs = freq[value] / 2;
            while (pairs > 0 && requiredDoubleGroups > 0) {
                doubleNumbers[doubleIdx++] = value;
                pairs--;
                requiredDoubleGroups--;
            }
        }

        // ---- find a leftover single value for the centre ----
        int centreValue = 0;
        for (int value = 1; value <= MAX_VALUE; value++) {
            if (freq[value] % 2 == 1) {
                centreValue = value;
                break;
            }
        }

        // ---- validate feasibility ----
        boolean feasible = (requiredQuadGroups == 0) && (requiredDoubleGroups == 0);
        if (!feasible) {
            System.out.println("NO");
            return;
        }

        // ---- build the final odd matrix ----
        int[][] matrix = new int[originalN][originalN];
        int idxQuad = 0, idxDouble = 0;

        // Fill the four symmetric quadrants
        for (int i = 0; i < originalN / 2; i++) {
            for (int j = 0; j < originalN / 2; j++) {
                int v = quadNumbers[idxQuad++];
                matrix[i][j] = v;
                matrix[i][originalN - 1 - j] = v;
                matrix[originalN - 1 - i][j] = v;
                matrix[originalN - 1 - i][originalN - 1 - j] = v;
            }
        }

        // Fill the central row (top half of the cross)
        int centreIdx = originalN / 2;
        for (int k = 0; k < originalN / 2; k++) {
            int v = doubleNumbers[idxDouble++];
            matrix[centreIdx][k] = v;
            matrix[centreIdx][originalN - 1 - k] = v;
        }

        // Fill the central column (left half of the cross)
        for (int k = 0; k < originalN / 2; k++) {
            int v = doubleNumbers[idxDouble++];
            matrix[k][centreIdx] = v;
            matrix[originalN - 1 - k][centreIdx] = v;
        }

        // Place the centre element
        matrix[centreIdx][centreIdx] = centreValue;

        printMatrix(matrix);
    }

    /** Utility to print a matrix to stdout. */
    private static void printMatrix(int[][] matrix) {
        for (int[] row : matrix) {
            for (int val : row) {
                System.out.print(val + " ");
            }
            System.out.println();
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Refactored solution for the symmetric‑matrix filling problem.
 *
 * <p>Key improvements:
 * <ul>
 *   <li>Extracted small, well‑named methods to separate concerns.</li>
 *   <li>Used a proper {@code Pair} class instead of a raw mutable holder.</li>
 *   <li>Replaced raw types with generics and added {@code final} where appropriate.</li>
 *   <li>Leveraged {@code try‑with‑resources} for automatic resource cleanup.</li>
 *   <li>Added JavaDoc comments and meaningful variable names.</li>
 *   <li>Removed duplicated logic by introducing helper methods.</li>
 * </ul>
 *
 * The algorithm remains identical to the original: it reads {@code n} and {@code n*n}
 * integers, then attempts to fill an {@code n×n} matrix respecting a symmetric
 * placement rule. If at any point a required value is unavailable, it prints
 * {@code "NO"}; otherwise it prints {@code "YES"} followed by the filled matrix.
 */
public class Main {

    /** Holds a value and its remaining occurrences. */
    private static final class Pair {
        final int value;
        int remaining;               // mutable count

        Pair(int value, int remaining) {
            this.value = value;
            this.remaining = remaining;
        }
    }

    /** Orders {@link Pair}s by their remaining count (descending). */
    private static final Comparator<Pair> BY_REMAINING_DESC =
            Comparator.comparingInt(p -> p.remaining).reversed();

    /** Simple scanner that can be closed automatically. */
    private static final class FastScanner implements AutoCloseable {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner(InputStream source) {
            this.br = new BufferedReader(new InputStreamReader(source));
        }

        String next() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                st = new StringTokenizer(br.readLine());
            }
            return st.nextToken();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }

        @Override
        public void close() throws IOException {
            br.close();
        }
    }

    /** Entry point of the application. */
    public static void main(String[] args) throws IOException {
        // The try‑with‑resources block guarantees that the underlying stream is closed.
        try (FastScanner sc = new FastScanner(System.in)) {
            int n = sc.nextInt();

            // -----------------------------------------------------------------
            // 1️⃣ Build a frequency map of the input numbers.
            // -----------------------------------------------------------------
            Map<Integer, Integer> frequency = new HashMap<>();
            int total = n * n;
            for (int i = 0; i < total; i++) {
                int x = sc.nextInt();
                frequency.merge(x, 1, Integer::sum);
            }

            // -----------------------------------------------------------------
            // 2️⃣ Prepare a priority queue that always returns the number with
            //    the highest remaining count.
            // -----------------------------------------------------------------
            PriorityQueue<Pair> pq = new PriorityQueue<>(BY_REMAINING_DESC);
            frequency.forEach((k, v) -> pq.add(new Pair(k, v)));

            // -----------------------------------------------------------------
            // 3️⃣ Initialise an empty matrix (filled with -1 to denote “unset”). 
            // -----------------------------------------------------------------
            int[][] matrix = new int[n][n];
            for (int[] row : matrix) {
                Arrays.fill(row, -1);
            }

            // -----------------------------------------------------------------
            // 4️⃣ Fill the four symmetric quadrants.
            // -----------------------------------------------------------------
            fillSymmetricQuadrants(matrix, pq, n);

            // -----------------------------------------------------------------
            // 5️⃣ If the size is odd, fill the central cross (row & column).
            // -----------------------------------------------------------------
            if (n % 2 == 1) {
                fillCentralCross(matrix, pq, n);
            }

            // -----------------------------------------------------------------
            // 6️⃣ Successful placement – output the result.
            // -----------------------------------------------------------------
            System.out.println("YES");
            printMatrix(matrix);
        }
    }

    /**
     * Places numbers into the four symmetric positions of each quadrant.
     *
     * @param matrix the target matrix
     * @param pq     priority queue of pairs (mutable remaining count)
     * @param n      matrix size
     */
    private static void fillSymmetricQuadrants(int[][] matrix, PriorityQueue<Pair> pq, int n) {
        int half = n / 2;
        for (int i = 0; i < half; i++) {
            for (int j = 0; j < half; j++) {
                Pair pair = pq.poll();
                if (pair == null) {
                    System.out.println("NO");
                    System.exit(0);
                }

                placeIfUnset(matrix, pair.value, i, n - 1 - j);
                decAndReQueue(pq, pair);

                placeIfUnset(matrix, pair.value, i, j);
                decAndReQueue(pq, pair);

                placeIfUnset(matrix, pair.value, n - 1 - i, j);
                decAndReQueue(pq, pair);

                placeIfUnset(matrix, pair.value, n - 1 - i, n - 1 - j);
                decAndReQueue(pq, pair);

                if (pair.remaining > 0) {
                    pq.add(pair);
                }
            }
        }
    }

    /**
     * Writes a value into a cell only when that cell is still unset
     * (i.e., currently {@code -1}).
     *
     * @param matrix the matrix to fill
     * @param value  the value to write
     * @param row    row index
     * @param col    column index
     */
    private static void placeIfUnset(int[][] matrix, int value, int row, int col) {
        if (matrix[row][col] == -1) {
            matrix[row][col] = value;
        }
    }

    /**
     * Decrements the remaining count of the supplied pair and re‑queues it
     * if occurrences are still left.
     *
     * @param pq     the priority queue
     * @param pair   the pair whose count should be decremented
     */
    private static void decAndReQueue(PriorityQueue<Pair> pq, Pair pair) {
        pair.remaining--;
        if (pair.remaining > 0) {
            pq.add(pair);
        }
    }

    /**
     * Fills the central column and the central row when {@code n} is odd.
     *
     * @param matrix the target matrix
     * @param pq     priority queue of remaining pairs
     * @param n      matrix size
     */
    private static void fillCentralCross(int[][] matrix, PriorityQueue<Pair> pq, int n) {
        int mid = n / 2;

        // Symmetric cells of the middle column.
        for (int i = 0; i < mid; i++) {
            Pair p = pq.poll();
            if (p == null) {
                System.out.println("NO");
                System.exit(0);
            }
            placeIfUnset(matrix, p.value, i, mid);
            decAndReQueue(pq, p);
            placeIfUnset(matrix, p.value, n - 1 - i, mid);
            decAndReQueue(pq, p);
            if (p.remaining > 0) {
                pq.add(p);
            }
        }

        // The middle row (including the exact centre cell).
        for (int i = 0; i <= mid; i++) {
            Pair p = pq.poll();
            if (p == null) {
                System.out.println("NO");
                System.exit(0);
            }
            placeIfUnset(matrix, p.value, mid, i);
            decAndReQueue(pq, p);
            placeIfUnset(matrix, p.value, mid, n - 1 - i);
            decAndReQueue(pq, p);
            if (p.remaining > 0) {
                pq.add(p);
            }
        }
    }

    /**
     * Prints the resulting matrix to standard output.
     *
     * @param matrix the matrix to display
     */
    private static void printMatrix(int[][] matrix) {
        for (int[] row : matrix) {
            for (int cell : row) {
                System.out.print(cell + " ");
            }
            System.out.println();
        }
    }
}

import java.util.*;
import java.util.stream.Collectors;

/**
 * Reads an n×n matrix of integers, checks whether a symmetric arrangement is possible
 * (mirror symmetry with respect to both axes) and, if possible, prints one valid layout.
 *
 * <p>Key improvements over the original version:
 *
 * <ul>
 *   <li>Clear separation of concerns (input, validation, construction, output).</li>
 *   <li>Descriptive, camelCase naming and small helper methods.</li>
 *   <li>Reduced duplication – symmetric placement logic is centralized.</li>
 *   <li>Self‑contained logic for the even/odd cases, avoiding magic numbers.</li>
 *   <li>Early exit on invalid input keeps the main flow easy to read.</li>
 * </ul>
 */
public class Main {

    /** Maximum matrix size the program supports. */
    private static final int MAX_SIZE = 100;

    /** 2‑dimensional holder for the resulting layout. */
    private static final int[][] output = new int[MAX_SIZE + 1][MAX_SIZE + 1];

    /** Holds numbers that must be placed in positions that appear twice (edges). */
    private static final Queue<Integer> PAIR_QUEUE = new LinkedList<>();

    /** Holds numbers that must be placed in positions that appear four times (corners). */
    private static final Queue<Integer> FOUR_QUEUE = new LinkedList<>();

    /** The centre element for odd‑sized matrices (if it exists). */
    private static Integer centreValue = null;

    /** --------------------------------------------------------------------- */
    /** Entry point – parses input, validates feasibility and prints the result. */
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = readMatrixSize(sc);
        int[][] values = readValues(sc, n * n);

        Map<Integer, Integer> frequency = frequencyMap(values);
        if (n % 2 == 0) {
            if (!validateEvenCase(frequency, n)) {
                System.out.println("NO");
                return;
            }
        } else {
            if (!validateOddCase(frequency, n)) {
                System.out.println("NO");
                return;
            }
        }

        buildMatrix(n);
        printMatrix();
        sc.close();
    }

    /** --------------------------------------------------------------------- */
    /** Reads the size of the square matrix (1 ≤ n ≤ MAX_SIZE). */
    private static int readMatrixSize(Scanner sc) {
        int n = sc.nextInt();
        if (n < 1 || n > MAX_SIZE) {
            throw new IllegalArgumentException("n must be between 1 and " + MAX_SIZE);
        }
        return n;
    }

    /** Reads n·n integers from the scanner into a flat array. */
    private static int[] readValues(Scanner sc, int count) {
        int[] arr = new int[count];
        for (int i = 0; i < count; ++i) {
            arr[i] = sc.nextInt();
        }
        return arr;
    }

    /** Creates a frequency map (value → occurrences). */
    private static Map<Integer, Integer> frequencyMap(int[] values) {
        return Arrays.stream(values)
                .boxed()
                .collect(Collectors.groupingBy(Integer::intValue,
                        Collectors.counting()));
    }

    /** --------------------------------------------------------------------- */
    /** Validation for the even‑n case: every value count must be a multiple of 4. */
    private static boolean validateEvenCase(Map<Integer, Integer> freq, int n) {
        int slots = (n / 2) * (n / 2);                 // number of 4‑cell groups
        int supplied = 0;

        for (Map.Entry<Integer, Integer> e : freq.entrySet()) {
            int cnt = e.getValue();
            if (cnt % 4 != 0) {
                return false;                         // not all multiples of 4
            }
            supplied += cnt / 4;
        }
        return supplied == slots;
    }

    /** Validation for the odd‑n case – checks centre, pairs and 4‑cell groups. */
    private static boolean validateOddCase(Map<Integer, Integer> freq, int n) {
        int half = n / 2;                              // number of 4‑cell groups per side
        int neededPairs = 2 * half;                    // pairs placed on middle row/col
        int neededSingles = 1;                         // centre cell

        int pairsAvailable = 0;
        int singlesAvailable = 0;

        for (Map.Entry<Integer, Integer> e : freq.entrySet()) {
            int cnt = e.getValue();
            int mod = cnt % 4;

            // 4‑cell groups
            for (int i = 0; i < cnt / 4; ++i) {
                FOUR_QUEUE.add(e.getKey());
            }

            // leftovers that can be used for pairs
            if (mod == 2 || mod == 3) {
                pairsAvailable += 1;                 // each leftover 2 or 3 gives one pair slot
            } else if (mod == 1) {
                singlesAvailable += 1;               // each leftover 1 can become the centre
            }
        }

        // centre must be exactly one value
        if (singlesAvailable != neededSingles) {
            return false;
        }

        // enough pairs for all required edge positions?
        return pairsAvailable >= neededPairs;
    }

    /** --------------------------------------------------------------------- */
    /** Builds the symmetric matrix using the prepared queues. */
    private static void buildMatrix(int n) {
        if (n % 2 == 0) {
            fillEvenMatrix(n);
        } else {
            fillOddMatrix(n);
        }
    }

    /** Places numbers into the four‑cell groups for the even‑size matrix. */
    private static void fillEvenMatrix(int n) {
        int half = n / 2;
        for (int i = 1; i <= half; ++i) {
            for (int j = 1; j <= half; ++j) {
                int val = FOUR_QUEUE.poll();
                placeSymmetric(i, j, val, n);
            }
        }
    }

    /** Fills the odd‑size matrix handling 4‑cell groups, edge pairs and the centre. */
    private static void fillOddMatrix(int n) {
        int half = n / 2;

        // ---- 1. Fill 4‑cell groups (corners) ----
        for (int i = 1; i <= half; ++i) {
            for (int j = 1; j <= half; ++j) {
                int val = FOUR_QUEUE.poll();
                placeSymmetric(i, j, val, n);
            }
        }

        // ---- 2. Fill the centre (if not yet set) ----
        if (centreValue != null) {
            int mid = (n + 1) / 2;
            output[mid][mid] = centreValue;
        }

        // ---- 3. Fill edge pairs on the middle row ----
        for (int i = 1; i <= half; ++i) {
            int val = takeFromPairQueue();
            output[i][mid] = output[n - i + 1][mid] = val;
        }

        // ---- 4. Fill edge pairs on the middle column ----
        for (int j = 1; j <= half; ++j) {
            int val = takeFromPairQueue();
            output[mid][j] = output[mid][n - j + 1] = val;
        }
    }

    /** Helper that extracts the next suitable value from PAIR_QUEUE (creates it on‑the‑fly if needed). */
    private static int takeFromPairQueue() {
        if (!PAIR_QUEUE.isEmpty()) {
            return PAIR_QUEUE.poll();
        }
        // No ready value – create one from a four‑cell value (split 4 → 2+2)
        int fourVal = FOUR_QUEUE.poll();
        PAIR_QUEUE.add(fourVal);
        PAIR_QUEUE.add(fourVal);
        return fourVal;
    }

    /** Places a value symmetrically in the four cells defined by (i, j). */
    private static void placeSymmetric(int i, int j, int val, int n) {
        output[i][j] = output[n - i + 1][j] = output[i][n - j + 1] = output[n - i + 1][n - j + 1] = val;
    }

    /** --------------------------------------------------------------------- */
    /** Prints "YES" followed by the constructed matrix. */
    private static void printMatrix() {
        System.out.println("YES");
        int size = (int) Math.sqrt(MAX_SIZE); // safe because we never exceed the real n
        for (int i = 1; i <= size; ++i) {
            StringBuilder sb = new StringBuilder();
            for (int j = 1; j <= size; ++j) {
                if (j > 1) {
                    sb.append(' ');
                }
                sb.append(output[i][j]);
            }
            System.out.println(sb);
        }
    }
}

import java.io.PrintWriter;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Scanner;

/**
 * Reads a size {@code n} and {@code n*n} integers, then decides whether the
 * numbers can be arranged into an {@code n×n} matrix that is symmetric with
 * respect to both the horizontal and vertical axes (a “palindromic” matrix).
 * If possible, prints {@code YES} followed by the matrix, otherwise prints
 * {@code NO}.
 *
 * <p>This refactor improves readability, isolates concerns, uses proper
 * resource handling and eliminates magic numbers.</p>
 */
public class PalindromicMatrix {

    /** Number of elements that must appear 4‑times in an even‑sized matrix. */
    private static final int GROUP_OF_FOUR = 4;

    /** Number of elements that must appear 2‑times in the central row/column
     *  of an odd‑sized matrix (excluding the centre cell). */
    private static final int GROUP_OF_TWO = 2;

    public static void main(String[] args) {
        try (Scanner in = new Scanner(System.in);
             PrintWriter out = new PrintWriter(System.out)) {

            int n = readDimension(in);
            List<Integer> values = readValues(in, n * n);
            int[][] matrix = buildPalindromicMatrix(n, values);

            if (matrix == null) {
                out.println("NO");
            } else {
                out.println("YES");
                printMatrix(matrix, out);
            }

        } catch (Exception e) {
            // In a contest environment we simply exit with an error message.
            System.err.println("Error while processing input: " + e.getMessage());
        }
    }

    /** Reads the matrix dimension {@code n} from {@code scanner}. */
    private static int readDimension(Scanner scanner) {
        String line = scanner.nextLine().trim();
        if (line.isEmpty()) {
            throw new IllegalArgumentException("Missing dimension value.");
        }
        int n = Integer.parseInt(line);
        if (n <= 0) {
            throw new IllegalArgumentException("Dimension must be positive.");
        }
        return n;
    }

    /** Reads exactly {@code expectedCount} integers from {@code scanner}. */
    private static List<Integer> readValues(Scanner scanner, int expectedCount) {
        List<Integer> list = new ArrayList<>(expectedCount);
        while (list.size() < expectedCount) {
            if (!scanner.hasNextInt()) {
                throw new IllegalArgumentException(
                        "Expected " + expectedCount + " integers but reached EOF.");
            }
            list.add(scanner.nextInt());
        }
        return list;
    }

    /**
     * Attempts to construct a palindromic matrix from the supplied values.
     *
     * @param n      matrix dimension
     * @param values list of {@code n*n} integers (may be unsorted)
     * @return a valid matrix if one exists; otherwise {@code null}
     */
    private static int[][] buildPalindromicMatrix(int n, List<Integer> values) {
        // Frequency map of all values.
        Map<Integer, Integer> frequency = computeFrequencies(values);
        // Sort values to simplify extraction of groups.
        List<Integer> sorted = new ArrayList<>(values);
        Collections.sort(sorted);

        // Determine how many groups of 4, 2 and 1 we need.
        int groupsOfFour = (n / 2) * (n / 2);
        int groupsOfTwo  = (n % 2 == 0) ? 0 : 2 * (n / 2); // 0 for even n
        int centreValue  = (n % 2 == 0) ? -1 : findCentreValue(frequency, n);

        // Allocate the output matrix.
        int[][] result = new int[n][n];

        // Helper to place a value into symmetric positions.
        // For even n only groups of four exist.
        // For odd n we additionally fill the central row/column and centre cell.
        if (n % 2 == 0) {
            return fillEvenMatrix(result, sorted, frequency, groupsOfFour);
        } else {
            return fillOddMatrix(result, sorted, frequency, groupsOfFour,
                                 groupsOfTwo, centreValue);
        }
    }

    /** Computes a frequency map of the supplied integers. */
    private static Map<Integer, Integer> computeFrequencies(List<Integer> values) {
        Map<Integer, Integer> freq = new HashMap<>();
        for (Integer v : values) {
            freq.merge(v, 1, Integer::sum);
        }
        return freq;
    }

    /**
     * Tries to fill an even‑sized matrix (n is even). Returns {@code null}
     * if the frequencies do not allow a palindromic arrangement.
     */
    private static int[][] fillEvenMatrix(int[][] matrix, List<Integer> sorted,
                                           Map<Integer, Integer> freq,
                                           int groupsOfFour) {
        int idx = 0;
        // Process groups of four in sorted order.
        while (idx < sorted.size()) {
            int value = sorted.get(idx);
            int count = freq.get(value);
            // Skip values that cannot fill a complete group of four.
            if (count < GROUP_OF_FOUR) {
                return null;
            }
            // Use four copies of this value.
            for (int i = 0; i < groupsOfFour; i++) {
                // Compute the symmetric positions and assign the value.
                // The outer loops construct a (n/2)×(n/2) “base” quadrant.
                int baseRow = i / (n / 2);
                int baseCol = i % (n / 2);
                placeInQuadrant(matrix, baseRow, baseCol, value);
                // Because of symmetry the same value will be placed four times.
            }
            // Consume four occurrences from the frequency map.
            freq.put(value, count - GROUP_OF_FOUR);
            // Move to the next distinct value.
            while (idx < sorted.size() && sorted.get(idx).equals(value)) {
                idx++;
            }
        }
        // All groups of four have been placed – the matrix is complete.
        return matrix;
    }

    /**
     * Tries to fill an odd‑sized matrix. Returns {@code null} if the
     * frequencies are incompatible with the required pattern.
     */
    private static int[][] fillOddMatrix(int[][] matrix, List<Integer> sorted,
                                          Map<Integer, Integer> freq,
                                          int groupsOfFour, int groupsOfTwo,
                                          Integer centreValue) {
        // 1. Fill groups of four.
        if (!placeGroupsOfFour(matrix, sorted, freq, groupsOfFour)) {
            return null;
        }

        // 2. Fill groups of two (central row and column, excluding centre cell).
        if (!placeGroupsOfTwo(matrix, sorted, freq, groupsOfTwo)) {
            return null;
        }

        // 3. Place the centre cell (if any value remains).
        if (centreValue == null) {
            return null; // No centre candidate found.
        }
        // There should be exactly one occurrence left for the centre.
        if (freq.get(centreValue) != 1) {
            return null;
        }
        int mid = matrix.length / 2;
        matrix[mid][mid] = centreValue;
        return matrix;
    }

    /** Places values that appear exactly four times into symmetric positions. */
    private static boolean placeGroupsOfFour(int[][] matrix, List<Integer> sorted,
                                             Map<Integer, Integer> freq, int groupsOfFour) {
        int placed = 0;
        int idx = 0;
        while (placed < groupsOfFour) {
            int value = sorted.get(idx);
            int count = freq.get(value);
            if (count < GROUP_OF_FOUR) {
                return false;
            }
            // Place the value in the next base quadrant cell.
            int baseRow = placed / (matrix.length / 2);
            int baseCol = placed % (matrix.length / 2);
            placeInQuadrant(matrix, baseRow, baseCol, value);
            // Consume four copies.
            freq.put(value, count - GROUP_OF_FOUR);
            placed++;

            // Advance idx to the next distinct value.
            while (idx < sorted.size() && sorted.get(idx).equals(value)) {
                idx++;
            }
        }
        return true;
    }

    /** Places values that appear exactly two times into the central row/column. */
    private static boolean placeGroupsOfTwo(int[][] matrix, List<Integer> sorted,
                                            Map<Integer, Integer> freq, int groupsOfTwo) {
        int placed = 0;
        int idx = 0;
        int half = matrix.length / 2;
        while (placed < groupsOfTwo) {
            int value = sorted.get(idx);
            int count = freq.get(value);
            if (count < GROUP_OF_TWO) {
                return false;
            }
            // Determine whether we are on the central row or column.
            if (placed < half) {
                // Central row, left side
                matrix[half][placed] = value;
                matrix[half][matrix.length - 1 - placed] = value;
            } else {
                // Central column, top side (skip the centre cell already placed)
                int row = placed - half;
                matrix[row][half] = value;
                matrix[matrix.length - 1 - row][half] = value;
            }
            placed++;
            // Consume two copies.
            freq.put(value, count - GROUP_OF_TWO);

            // Skip duplicates.
            while (idx < sorted.size() && sorted.get(idx).equals(value)) {
                idx++;
            }
        }
        return true;
    }

    /** Places a value into the four symmetric positions defined by (row, col). */
    private static void placeInQuadrant(int[][] matrix, int row, int col, int value) {
        int n = matrix.length;
        int symmetricRow = n - 1 - row;
        int symmetricCol = n - 1 - col;
        matrix[row][col] = value;
        matrix[row][symmetricCol] = value;
        matrix[symmetricRow][col] = value;
        matrix[symmetricRow][symmetricCol] = value;
    }

    /** Locates a value that could serve as the centre cell (must have an odd count). */
    private static Integer findCentreValue(Map<Integer, Integer> freq, int n) {
        for (Map.Entry<Integer, Integer> entry : freq.entrySet()) {
            if (entry.getValue() % 2 == 1) {
                // Prefer the smallest such value to keep deterministic output.
                return entry.getKey();
            }
        }
        return null; // No candidate found.
    }

    /** Prints the matrix using the exact format required by the original program. */
    private static void printMatrix(int[][] matrix, PrintWriter out) {
        int n = matrix.length;
        for (int i = 0; i < n; i++) {
            StringBuilder line = new StringBuilder();
            for (int j = 0; j < n; j++) {
                line.append(matrix[i][j]);
                if (j < n - 1) {
                    line.append(' ');
                }
            }
            out.println(line);
        }
    }
}

import java.io.IOException;
import java.util.Arrays;
import java.util.Scanner;

/**
 * Refactored solution for the “CodeForces 540C – Palindromic Matrix” problem.
 *
 * <p>Changes made for maintainability:
 * <ul>
 *   <li>Extracted helper methods with clear intent.</li>
 *   <li>Self‑documenting variable names instead of cryptic one‑letter names.</li>
 *   <li>Logical separation of concerns (input, centre handling, filling groups,
 *       validation, output).</li>
 *   <li>Early exits and defensive checks to avoid deeply nested code.</li>
 *   <li>Constant definitions and type‑safe operations.</li>
 * </ul>
 * The algorithmic behaviour is identical to the original program.
 */
public class MatrixBuilder {

    /** Maximum value that can appear in the input (as per original code). */
    private static final int MAX_VALUE = 1000;

    /** Entry point – reads data, invokes the solver and prints the result. */
    public static void main(String[] args) throws IOException {
        try (Scanner scanner = new Scanner(System.in)) {
            int size = scanner.nextInt();                     // n
            int[] frequencies = new int[MAX_VALUE + 1];       // frequency counter
            int totalElements = size * size;

            for (int i = 0; i < totalElements; i++) {
                int val = scanner.nextInt();
                if (val < 0 || val > MAX_VALUE) {
                    System.out.println("NO");
                    return;
                }
                frequencies[val]++;
            }

            String outcome = solve(frequencies, size);
            System.out.print(outcome);
        }
    }

    /**
     * Attempts to build the required square matrix.
     *
     * @param frequencies frequency of each possible value (0 … MAX_VALUE)
     * @param size        dimension of the square matrix
     * @return "NO" if construction is impossible,
     *         otherwise a string starting with "YES" followed by the matrix.
     */
    public static String solve(int[] frequencies, int size) {
        int[][] matrix = new int[size][size];
        int[] remaining = Arrays.copyOf(frequencies, frequencies.length);

        // --------------------------------------------------------------
        // 1. Centre cell (only when the dimension is odd)
        // --------------------------------------------------------------
        if (size % 2 == 1) {
            int centreValue = findValueWithOddCount(remaining);
            if (centreValue == -1) {
                return "NO";
            }
            int mid = size / 2;
            matrix[mid][mid] = centreValue;
            remaining[centreValue]--;               // consume one occurrence
        }

        // --------------------------------------------------------------
        // 2. Fill symmetric groups of four cells
        // --------------------------------------------------------------
        int half = size / 2;
        for (int i = 0; i < half; i++) {
            for (int j = 0; j < half; j++) {
                int value = findValueWithAtLeastCount(remaining, 4);
                if (value == -1) {
                    return "NO";
                }
                int i2 = size - 1 - i;
                int j2 = size - 1 - j;
                matrix[i][j] = value;
                matrix[i][j2] = value;
                matrix[i2][j] = value;
                matrix[i2][j2] = value;
                remaining[value] -= 4;
            }
        }

        // --------------------------------------------------------------
        // 3. Fill groups of two on the middle cross (odd size only)
        // --------------------------------------------------------------
        if (size % 2 == 1) {
            int mid = size / 2;

            // pairs on the middle row
            for (int i = 0; i < half; i++) {
                int value = findValueWithAtLeastCount(remaining, 2);
                if (value == -1) {
                    return "NO";
                }
                matrix[i][mid] = value;
                matrix[size - 1 - i][mid] = value;
                remaining[value] -= 2;
            }

            // pairs on the middle column
            for (int i = 0; i < half; i++) {
                int value = findValueWithAtLeastCount(remaining, 2);
                if (value == -1) {
                    return "NO";
                }
                matrix[mid][i] = value;
                matrix[mid][size - 1 - i] = value;
                remaining[value] -= 2;
            }
        }

        // --------------------------------------------------------------
        // 4. Verify that all frequencies have been exhausted exactly
        // --------------------------------------------------------------
        for (int count : remaining) {
            if (count != 0) {
                return "NO";
            }
        }

        // --------------------------------------------------------------
        // 5. Build the output string
        // --------------------------------------------------------------
        StringBuilder output = new StringBuilder("YES\n");
        for (int[] row : matrix) {
            for (int cell : row) {
                output.append(cell).append(' ');
            }
            output.append('\n');
        }
        return output.toString();
    }

    /** Returns a value that occurs an odd number of times, or -1 if none exists. */
    private static int findValueWithOddCount(int[] freq) {
        for (int v = 0; v < freq.length; v++) {
            if ((freq[v] & 1) == 1) {
                return v;
            }
        }
        return -1;
    }

    /** Returns a value whose remaining count is at least `need`, or -1 if none. */
    private static int findValueWithAtLeastCount(int[] freq, int need) {
        for (int v = 0; v < freq.length; v++) {
            if (freq[v] >= need) {
                return v;
            }
        }
        return -1;
    }
}

import java.util.*;

public class PalindromicMatrix {

    /** Entry point */
    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            int n = readDimension(scanner);
            int[] values = readMatrixElements(scanner, n * n);
            MatrixConstructor constructor = new MatrixConstructor(n, values);
            if (!constructor.canBuild()) {
                System.out.println("NO");
                return;
            }
            System.out.println("YES");
            int[][] matrix = constructor.build();
            printMatrix(matrix);
        }
    }

    /** Reads the size n of the square matrix. */
    private static int readDimension(Scanner sc) {
        System.out.print("Enter n: ");
        return Integer.parseInt(sc.next());
    }

    /** Reads n×n integer values from the scanner. */
    private static int[] readMatrixElements(Scanner sc, int count) {
        int[] arr = new int[count];
        for (int i = 0; i < count; i++) {
            arr[i] = sc.nextInt();
        }
        return arr;
    }

    /** Prints a 2‑D matrix to stdout. */
    private static void printMatrix(int[][] matrix) {
        for (int[] row : matrix) {
            for (int v : row) {
                System.out.print(v + " ");
            }
            System.out.println();
        }
    }

    /** --------------------------------------------------------------------- */
    /** Encapsulates all logic needed to decide whether a palindromic matrix can be built
     *  and to actually build it. */
    private static final class MatrixConstructor {

        private final int size;
        private final int[] flat;
        private final Map<Integer, Integer> frequency;
        private final Map<Integer, List<Integer>> bucketByCount;
        private final int[] linearResult; // stores the matrix in row‑major order before reshaping
        private int placed;                // how many cells have been placed so far

        MatrixConstructor(int size, int[] flat) {
            this.size = size;
            this.flat = flat;
            this.frequency = computeFrequency(flat);
            this.bucketByCount = groupByCount(frequency);
            int total = size * size;
            this.linearResult = new int[total];
            this.placed = 0;
        }

        /** Determines whether a palindromic matrix can be assembled. */
        boolean canBuild() {
            int half = (size * size) / 2;
            int mid = half + ((size * size) % 2 == 1 ? 1 : 0);

            // 1️⃣ Try to fill 4‑cell groups first
            while (placed < mid && bucketByCount.containsKey(4)) {
                placeQuadruple();
            }

            // 2️⃣ Then fill 2‑cell groups
            while (placed < mid && bucketByCount.containsKey(2)) {
                placeDouble();
            }

            // 3️⃣ Finally place the centre cell (only when size is odd)
            if (placed < mid && bucketByCount.containsKey(1)) {
                placeCenter();
            } else {
                return false; // unable to fill the centre
            }

            return placed == size * size;
        }

        /** Places a quadruple of equal numbers into four symmetric positions. */
        private void placeQuadruple() {
            int value = bucketByCount.get(4).remove(bucketByCount.get(4).size() - 1);
            int remaining = frequency.get(value) - 4;
            int baseIdx = placed;

            // Fill the four symmetric slots in the linear layout
            linearResult[baseIdx] = value;
            linearResult[size * size - baseIdx - 1] = value;
            linearResult[baseIdx + size] = value;
            linearResult[size * size - baseIdx - size - 1] = value;

            // Update remaining count and bucket mapping
            frequency.put(value, remaining);
            if (remaining == 1) {
                bucketByCount.computeIfAbsent(1, k -> new ArrayList<>()).add(value);
            } else if (remaining > 1) {
                bucketByCount.computeIfAbsent(remaining, k -> new ArrayList<>()).add(value);
            }
            // Remove the key for 4 once we have taken the last element
            bucketByCount.remove(4, Collections.emptyList());

            placed += size; // advance by one full row width because we placed a whole “quadrant”
        }

        /** Places a double of equal numbers into two symmetric positions. */
        private void placeDouble() {
            int value = bucketByCount.get(2).remove(bucketByCount.get(2).size() - 1);
            int remaining = frequency.get(value) - 2;
            int idx = placed;

            linearResult[idx] = value;
            linearResult[size * size - idx - 1] = value;

            frequency.put(value, remaining);
            if (remaining == 1) {
                bucketByCount.computeIfAbsent(1, k -> new ArrayList<>()).add(value);
            } else if (remaining > 1) {
                bucketByCount.computeIfAbsent(remaining, k -> new ArrayList<>()).add(value);
            }
            bucketByCount.remove(2, Collections.emptyList());

            placed++;
        }

        /** Places the centre element when the matrix dimension is odd. */
        private void placeCenter() {
            int value = bucketByCount.get(1).remove(bucketByCount.get(1).size() - 1);
            linearResult[placed] = value;
            placed++;
        }

        /** Builds the final 2‑D matrix from the linear representation. */
        int[][] build() {
            int[][] matrix = new int[size][size];
            int srcIdx = 0;
            for (int col = 0; col < size; col++) {
                for (int row = 0; row < size; row++) {
                    matrix[row][col] = linearResult[srcIdx++];
                }
            }
            return matrix;
        }

        /** Computes how many times each distinct integer occurs in the input array. */
        private static Map<Integer, Integer> computeFrequency(int[] values) {
            Map<Integer, Integer> map = new HashMap<>();
            for (int v : values) {
                map.merge(v, 1, Integer::sum);
            }
            return Collections.unmodifiableMap(map);
        }

        /** Groups distinct integers by the size of their occurrence (e.g., 1 → centre, 2 → pair, 4 → quadruple). */
        private static Map<Integer, List<Integer>> groupByCount(Map<Integer, Integer> freq) {
            Map<Integer, List<Integer>> buckets = new HashMap<>();
            for (Map.Entry<Integer, Integer> e : freq.entrySet()) {
                int count = e.getValue();
                buckets.computeIfAbsent(count, k -> new ArrayList<>()).add(e.getKey());
            }
            // Preserve insertion order for deterministic processing
            Map<Integer, List<Integer>> ordered = new LinkedHashMap<>();
            for (Map.Entry<Integer, List<Integer>> entry : buckets.entrySet()) {
                ordered.put(entry.getKey(), entry.getValue());
            }
            return Collections.unmodifiableMap(ordered);
        }
    }
}

import java.util.HashMap;
import java.util.Map;
import java.util.Scanner;
import java.util.stream.Collectors;

/**
 * Reads an n×n integer matrix, checks whether the supplied numbers can be arranged
 * into a symmetric pattern described in the original algorithm, and prints the resulting
 * matrix (or "NO" if it is impossible).
 *
 * The implementation is split into small, single‑purpose methods to improve readability
 * and testability.
 */
public class MatrixProcessor {

    private static final Scanner SCANNER = new Scanner(System.in);

    /** Entry point of the program. */
    public static void main(String[] args) {
        int size = readMatrixSize();
        int[][] inputMatrix = readMatrix(size);
        Map<Integer, Integer> frequency = countFrequencies(inputMatrix);
        int[][] result = buildSymmetricMatrix(size, frequency);

        if (!allCountsAreZero(frequency)) {
            System.out.println("NO");
            return;
        }

        System.out.println("YES");
        printMatrix(result);
    }

    /** Repeatedly asks for a positive integer – this mirrors the original input expectations. */
    private static int readMatrixSize() {
        while (true) {
            if (!SCANNER.hasNextInt()) {
                throw new IllegalArgumentException("Expected an integer for matrix size.");
            }
            int size = SCANNER.nextInt();
            if (size > 0) {
                return size;
            }
            System.out.println("Matrix size must be positive.");
        }
    }

    /** Reads an n×n matrix from STDIN. */
    private static int[][] readMatrix(int n) {
        int[][] matrix = new int[n][n];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                matrix[i][j] = SCANNER.nextInt();
            }
        }
        return matrix;
    }

    /** Counts how many times each distinct number occurs in the matrix. */
    private static Map<Integer, Integer> countFrequencies(int[][] matrix) {
        Map<Integer, Integer> frequency = new HashMap<>();
        for (int[] row : matrix) {
            for (int value : row) {
                frequency.merge(value, 1, Integer::sum);
            }
        }
        return frequency;
    }

    /**
     * Constructs the output matrix by placing numbers in a symmetric pattern.
     * The algorithm follows the original logic but is expressed with clearly named
     * helper methods.
     */
    private static int[][] buildSymmetricMatrix(int n, Map<Integer, Integer> frequency) {
        int[][] result = new int[n][n];
        int half = n / 2;
        int[] values = extractKeys(frequency);
        int idx = 0;

        // ---- Place numbers with count >= 4 in the four corners of each quadrant ----
        for (int i = 0; i < half && idx < values.length; i++) {
            for (int j = 0; j < half && idx < values.length; j++) {
                int value = values[idx];
                int count = frequency.get(value);
                if (count >= 4) {
                    placeValueInQuadrantCorners(result, i, j, n, value);
                    frequency.put(value, count - 4);
                    j++; // advance column after a successful placement
                } else {
                    idx++; // skip this value, try the next one
                }
            }
        }

        // ---- If n is odd, handle the middle row/column of the border ----
        if (n % 2 == 1) {
            handleOddSizeBorders(result, n, half, frequency, values, idx);
        }

        return result;
    }

    /** Returns the keys of the frequency map in the same order the original code used. */
    private static int[] extractKeys(Map<Integer, Integer> map) {
        return map.keySet()
                .stream()
                .mapToInt(Integer::intValue)
                .toArray();
    }

    /** Places a value in the four symmetric corners of a quadrant. */
    private static void placeValueInQuadrantCorners(int[][] matrix, int row, int col, int size, int value) {
        int complement = size - 1 - col;
        matrix[row][col] = value;
        matrix[row][complement] = value;
        matrix[complement][col] = value;
        matrix[complement][complement] = value;
    }

    /**
     * Handles the special case when the matrix dimension is odd:
     *   * fills the two middle rows of the outer border,
     *   * fills the two middle columns of the outer border,
     *   * finally fills the exact centre cell if any value remains.
     */
    private static void handleOddSizeBorders(int[][] matrix,
                                             int size,
                                             int half,
                                             Map<Integer, Integer> frequency,
                                             int[] values,
                                             int startIdx) {
        int mid = (size - 1) / 2;

        // Fill top/bottom border cells in the middle column
        for (int i = 0; i < half && startIdx < values.length; ) {
            int value = values[startIdx];
            if (frequency.get(value) >= 2) {
                matrix[i][mid] = value;
                matrix[size - 1 - i][mid] = value;
                frequency.put(value, frequency.get(value) - 2);
                i++;
            } else {
                startIdx++;
            }
        }

        // Fill left/right border cells in the middle row
        for (int i = 0; i < half && startIdx < values.length; ) {
            int value = values[startIdx];
            if (frequency.get(value) >= 2) {
                matrix[mid][i] = value;
                matrix[mid][size - 1 - i] = value;
                frequency.put(value, frequency.get(value) - 2);
                i++;
            } else {
                startIdx++;
            }
        }

        // Fill the single centre cell (if any value still has a positive count)
        for (int i = 0; i < values.length; i++) {
            int value = values[i];
            if (frequency.get(value) >= 1) {
                matrix[mid][mid] = value;
                frequency.put(value, frequency.get(value) - 1);
                break;
            }
        }
    }

    /** Returns true only if every entry in the frequency map has a count of zero. */
    private static boolean allCountsAreZero(Map<Integer, Integer> frequency) {
        return frequency.values()
                .stream()
                .allMatch(c -> c == 0);
    }

    /** Utility method to print a matrix to STDOUT. */
    private static void printMatrix(int[][] matrix) {
        for (int[] row : matrix) {
            for (int value : row) {
                System.out.print(value + " ");
            }
            System.out.println();
        }
    }
}

import java.io.PrintStream;
import java.util.ArrayDeque;
import java.util.Deque;

/**
 * Refactored solution that reads a square of integers and attempts to build a
 * symmetric matrix satisfying the problem constraints.
 *
 * The algorithm works in three steps:
 *   1. Count how many times each value occurs.
 *   2. Distribute the values into groups of 4 (corner‑type), 2 (edge‑type)
 *      and 1 (center‑type when the size is odd).
 *   3. Fill the matrix symmetrically using those groups.
 *
 * If the distribution is impossible the program prints {@code NO},
 * otherwise it prints {@code YES} followed by the filled matrix.
 */
public class Solution {

    /** Maximum value that can appear in the input (as defined by the original problem). */
    private static final int MAX_VALUE = 1000;

    public static void main(String[] args) throws Exception {
        // Using a dedicated method isolates the whole input‑processing / construction logic.
        try (PrintStream out = new PrintStream(new java.io.BufferedOutputStream(System.out))) {
            processInput(out);
        }
    }

    /**
     * Reads the whole input, decides whether a valid matrix can be built and,
     * if possible, prints it.
     */
    private static void processInput(PrintStream out) throws java.io.IOException {
        try (java.util.Scanner sc = new java.util.Scanner(new java.io.BufferedInputStream(System.in))) {
            int n = sc.nextInt();                     // size of the square matrix
            int[] frequencies = countFrequencies(sc, n * n);

            // Separate the numbers into groups of size 4, 2 and possibly 1.
            Distribution distribution = distributeValues(frequencies, n);

            // If distribution is impossible we already printed "NO" inside the method.
            if (distribution.isImpossible()) {
                out.println("NO");
                return;
            }

            // At this point a matrix can be built.
            out.println("YES");

            int[][] matrix = fillMatrix(distribution, n);
            printMatrix(matrix, out);
        }
    }

    /**
     * Counts how many times each integer (0‑1000) appears in the input.
     *
     * @param scanner   scanner positioned after the matrix size
     * @param expected  number of integers to read (should be n * n)
     * @return an array where index = value and entry = frequency
     */
    private static int[] countFrequencies(java.util.Scanner scanner, int expected) {
        int[] cnts = new int[MAX_VALUE + 1];
        for (int i = 0; i < expected; ++i) {
            int v = scanner.nextInt();
            if (v < 0 || v > MAX_VALUE) {
                throw new IllegalArgumentException("Value out of allowed range [0," + MAX_VALUE + "]");
            }
            cnts[v]++;
        }
        return cnts;
    }

    /**
     * Splits the frequencies into three collections:
     *   - {@code fours}  : values that can fill a 2×2 block (used four times)
     *   - {@code twos}   : values that can fill an edge cell (used twice)
     *   - {@code ones}   : value(s) that will sit in the centre (only when n is odd)
     *
     * The method also checks the feasibility constraints required by the problem.
     *
     * @param frequencies array of value frequencies
     * @param n           matrix dimension
     * @return a {@link Distribution} describing the decomposition
     */
    private static Distribution distributeValues(int[] frequencies, int n) {
        Deque<Integer> fours = new ArrayDeque<>();
        Deque<Integer> twos  = new ArrayDeque<>();
        List<Integer> ones   = new java.util.ArrayList<>();

        for (int value = 0; value <= MAX_VALUE; ++value) {
            int count = frequencies[value];

            // Fill the 4‑bucket first.
            for (int i = 0; i < count / 4; ++i) {
                fours.addLast(value);
            }
            count %= 4;

            // Then the 2‑bucket.
            for (int i = 0; i < count / 2; ++i) {
                twos.addLast(value);
            }
            count %= 2;

            // Anything left (0 or 1) must go to the centre bucket.
            if (count > 0) {
                ones.add(value);
            }
        }

        Distribution dist = new Distribution(fours, twos, ones, n);
        dist.validateAndReportIfImpossible(out);
        return dist;
    }

    /**
     * Fills the matrix using the already prepared groups of 4, 2 and (optional) 1.
     *
     * @param distribution objects holding the groups
     * @param n            matrix dimension
     * @return a fully populated square matrix
     */
    private static int[][] fillMatrix(Distribution distribution, int n) {
        int[][] result = new int[n][n];

        // First handle the centre cell when n is odd.
        if (n % 2 == 1) {
            // There must be exactly one single element left.
            distribution.ones.remove(0); // consume the centre value
        }

        // Walk through the top‑left quadrant (including the centre line when n is odd).
        int half = (n + 1) / 2;
        for (int i = 0; i < half; ++i) {
            for (int j = 0; j < half; ++j) {
                if (i == n / 2 && j == n / 2) { // centre cell (only when n odd)
                    result[i][j] = distribution.ones.remove(0);
                } else if (i != n / 2 && j != n / 2) { // interior of the quadrant
                    // Take a value that will appear four times (symmetrically).
                    int val = distribution.fours.removeLast();
                    setSymmetric(result, val, i, j, n);
                } else if (i == n / 2) { // middle row, not centre
                    int val = takeFromTwosOrConvertFromFour(distribution, twos);
                    result[i][j] = result[i][n - 1 - j] = val;
                } else if (j == n / 2) { // middle column, not centre
                    int val = takeFromTwosOrConvertFromFour(distribution, twos);
                    result[i][j] = result[n - 1 - i][j] = val;
                } else {
                    throw new AssertionError("Unhandled case during matrix filling");
                }
            }
        }

        return result;
    }

    /**
     * Helper that either takes a value from the {@code twos} deque, or,
     * if it is empty, converts a 4‑slot value into two 2‑slot entries.
     *
     * @param distribution distribution holder
     * @param twos         deque of values that can be used twice
     * @return a value to be placed symmetrically
     */
    private static int takeFromTwosOrConvertFromFour(Distribution distribution, Deque<Integer> twos) {
        if (twos.isEmpty()) {
            // Convert one of the remaining 4‑blocks into two 2‑blocks.
            int val = distribution.fours.removeLast();
            twos.addLast(val);
            twos.addLast(val);
        }
        return twos.removeLast();
    }

    /**
     * Places a value symmetrically into the four positions that are mirrors
     * with respect to the centre of the matrix.
     *
     * @param mat   matrix to fill
     * @param val   value to write
     * @param i     row index of the top‑left corner of the 2×2 block
     * @param j     column index of the top‑left corner
     * @param size matrix dimension
     */
    private static void setSymmetric(int[][] mat, int val, int i, int j, int size) {
        mat[i][j] = val;
        mat[size - 1 - i][j] = val;
        mat[i][size - 1 - j] = val;
        mat[size - 1 - i][size - 1 - j] = val;
    }

    /**
     * Prints a matrix to the supplied {@link PrintStream}.
     *
     * @param matrix matrix to print
     * @param out    stream to write to
     */
    private static void printMatrix(int[][] matrix, PrintStream out) {
        for (int[] row : matrix) {
            for (int v : row) {
                out.print(v + " ");
            }
            out.println();
        }
    }

    /* -------------------------------------------------------------------------
       Supporting classes / structures
       ------------------------------------------------------------------------- */

    /** Holds the three collections used during the distribution phase. */
    private static final class Distribution {
        private final Deque<Integer> fours;   // values usable 4 times
        private final Deque<Integer> twos;    // values usable 2 times
        private final java.util.List<Integer> ones; // centre values (size 0 or 1)

        private final int n;                  // matrix dimension
        private final PrintStream out;         // used only for error messages

        Distribution(Deque<Integer> fours, Deque<Integer> twos,
                     java.util.List<Integer> ones, int n) {
            this.fours = fours;
            this.twos = twos;
            this.ones = ones;
            this.n = n;
            this.out = System.out;
        }

        /** Checks the feasibility constraints and prints “NO” if impossible. */
        void validateAndReportIfImpossible(PrintStream out) {
            if (n % 2 == 0) {
                // Even size matrices must not have any leftover 1‑ or 2‑blocks.
                if (!ones.isEmpty() || !twos.isEmpty()) {
                    out.println("NO");
                    System.exit(0);
                }
            } else {
                // Odd size matrices need exactly one centre element
                // and not more than (n/2)*2 pairs of 2‑blocks.
                if (ones.size() != 1 || twos.size() > ((n / 2) * 2)) {
                    out.println("NO");
                    System.exit(0);
                }
            }
        }

        /** Returns {@code true} if the distribution is known to be possible
         *  (the call has already printed “NO” when not). */
        boolean isImpossible() {
            return false; // placeholder – real check already handled inside validate…
        }
    }
}

import java.io.*;
import java.util.Scanner;

/**
 * Refactored solution for the matrix‑symmetry construction problem.
 *
 * <p>
 *   ✅  Read input values.
 *   ✅  Count occurrences of each integer (1 .. 1000).
 *   ✅  Fill the matrix using the four‑fold and edge‑symmetry rules.
 *   ✅  Output "NO" when the construction is impossible, otherwise "YES" and the matrix.
 * </p>
 *
 * <p>Changes made for readability and maintainability:</p>
 * <ul>
 *   <li>Extract scanner logic into a dedicated {@code InputReader}.</li>
 *   <li>Separate concerns into small, well‑named private methods.</li>
 *   <li>Use meaningful variable and method names.</li>
 *   <li>Replace magic numbers with named constants.</li>
 *   <li>Avoid static mutable fields and replace the custom tokenizer scanner with {@link Scanner}.</li>
 *   <li>Guard early exits and keep the core algorithm in a focused method.</li>
 * </ul>
 */
public class ProblemC {

    /** Upper bound for values that may appear in the input. */
    private static final int MAX_VALUE = 1000;

    /** Handle input reading. */
    private static final class InputReader implements AutoCloseable {
        private final Scanner scanner;

        InputReader(InputStream source) {
            this.scanner = new Scanner(source);
        }

        /** Reads the size of the square matrix. */
        int readMatrixSize() {
            return scanner.nextInt();
        }

        /** Reads the next integer from the input, retrying on empty tokens. */
        int readInt() {
            return scanner.nextInt();
        }

        /** Reads the remaining {@code n * n} integers into a count array. */
        int[] readCounts(int n) {
            int[] counts = new int[MAX_VALUE + 1];
            for (int i = 0; i < n * n; i++) {
                int val = readInt();
                if (val < 0 || val > MAX_VALUE) {
                    throw new IllegalArgumentException("Value out of supported range [0, " + MAX_VALUE + "]");
                }
                counts[val]++;
            }
            return counts;
        }

        @Override
        public void close() {
            scanner.close();
        }
    }

    /** Holds the matrix that will be printed as output. */
    private static final class Result {
        final boolean possible;
        final int[][] matrix;

        Result(boolean possible, int[][] matrix) {
            this.possible = possible;
            this.matrix = matrix;
        }
    }

    /**
     * Core algorithm that tries to fill a symmetric matrix using the provided
     * occurrence counts.
     *
     * @param n        Size of the desired square matrix.
     * @param counts   Frequency of each value (index = value).
     * @return         {@link Result} containing success flag and the filled matrix
     *                 (filled only when {@code possible} is {@code true}).
     */
    private static Result buildSymmetricMatrix(int n, int[] counts) {
        int[][] matrix = new int[n][n];
        boolean possible = true;

        // ---- Fill the matrix symmetrically ----
        fillSymmetricQuadrants(n, counts, matrix);

        if (!possible) {
            return new Result(false, matrix);
        }

        // ---- If n is odd, handle the central row and column ----
        if (n % 2 == 1) {
            fillMiddleRowAndColumn(n, counts, matrix);
        }

        // ---- Place the single leftover value in the exact centre (if needed) ----
        if (!possible && n % 2 == 1) {
            for (int v = 1; v <= MAX_VALUE && possible; v++) {
                if (counts[v] == 1) {
                    matrix[n / 2][n / 2] = v;
                    counts[v]--; // not used afterwards
                    possible = true;
                }
            }
        }

        return new Result(possible, matrix);
    }

    /** Fill the four‑fold symmetric positions for the upper‑left quadrant. */
    private static void fillSymmetricQuadrants(int n, int[] counts, int[][] matrix) {
        boolean cant = false;
        int fillValue = 1; // start scanning from the smallest possible value

        for (int i = 0; i < n / 2 && !cant; i++) {
            for (int j = 0; j < n / 2 && !cant; j++) {
                // Find the first value that occurs at least four times.
                while (fillValue <= MAX_VALUE && counts[fillValue] < 4) {
                    fillValue++;
                }
                if (fillValue > MAX_VALUE) {
                    cant = true; // not enough values to satisfy the 4‑fold rule
                    break;
                }

                // Assign the value to the four symmetric cells.
                matrix[i][j] = fillValue;
                matrix[i][n - j - 1] = fillValue;
                matrix[n - i - 1][j] = fillValue;
                matrix[n - i - 1][n - j - 1] = fillValue;

                counts[fillValue] -= 4; // consume four occurrences
            }
        }
    }

    /** Fill the middle row and column when n is odd. */
    private static void fillMiddleRowAndColumn(int n, int[] counts, int[][] matrix) {
        boolean cant = false;
        int fillValue = 1;

        // Fill cells symmetric about the centre in the middle column.
        for (int i = 0; i < n / 2 && !cant; i++) {
            while (fillValue <= MAX_VALUE && counts[fillValue] < 2) {
                fillValue++;
            }
            if (fillValue > MAX_VALUE) {
                cant = true;
                break;
            }
            matrix[i][n / 2] = fillValue;
            matrix[n - i - 1][n / 2] = fillValue;
            counts[fillValue] -= 2;
        }

        if (!cant) {
            // Fill cells symmetric about the centre in the middle row.
            for (int i = 0; i < n / 2 && !cant; i++) {
                while (fillValue <= MAX_VALUE && counts[fillValue] < 2) {
                    fillValue++;
                }
                if (fillValue > MAX_VALUE) {
                    cant = true;
                    break;
                }
                matrix[n / 2][i] = fillValue;
                matrix[n / 2][n - i - 1] = fillValue;
                counts[fillValue] -= 2;
            }
        }

        if (cant) {
            // Not possible to satisfy all required placements.
            return;
        }

        // If there is exactly one unused value left, it must go to the centre.
        if (counts[fillValue] == 1) {
            // This situation can only happen when the previous loops exhausted,
            // so we simply look for any remaining single count.
            for (int v = 1; v <= MAX_VALUE && !cant; v++) {
                if (counts[v] == 1) {
                    matrix[n / 2][n / 2] = v;
                    counts[v]--; // consume the lone element
                    cant = false; // success
                }
            }
        }
    }

    /** Orchestrates input, processing, and output. */
    public static void main(String[] args) {
        try (InputReader reader = new InputReader(System.in)) {
            int n = reader.readMatrixSize();
            int[] counts = reader.readCounts(n);
            Result result = buildSymmetricMatrix(n, counts);

            if (!result.possible) {
                System.out.println("NO");
                return;
            }

            System.out.println("YES");
            int[][] matrix = result.matrix;
            for (int i = 0; i < n; i++) {
                StringBuilder line = new StringBuilder();
                for (int j = 0; j < n; j++) {
                    line.append(matrix[i][j]).append(' ');
                }
                System.out.println(line.toString().trim());
            }
        } catch (IOException e) {
            // In practice this will never happen with System.in, but we keep the guard.
            throw new UncheckedIOException(e);
        }
    }
}

/**
 * Refactored implementation of the square‑construction problem.
 *
 * <p>Reads an integer {@code n} followed by {@code n*n} integers.
 * If {@code n == 1} the single value is printed directly.
 * Otherwise it checks whether a symmetric matrix can be built from the
 * supplied numbers and prints {@code "YES"} together with such a matrix,
 * or {@code "NO"} if it is impossible.
 *
 * <p>The implementation has been refactored for readability, testability
 * and maintainability:
 * <ul>
 *   <li>Clear separation of concerns (input, validation, construction, output)</li>
 *   <li>Descriptive method and variable names</li>
 *   <li>Small helper methods that each perform a single responsibility</li>
 *   <li>Extraction of constants and reusable logic</li>
 * </ul>
 */
public class Main {

    /** Modulus used for the answer length (kept from original code). */
    private static final long MOD = 1_000_000_007L;

    /** Maximum value for the input numbers (used for counting frequencies). */
    private static final int MAX_VALUE = 1_000;

    /** Reusable {@link FastReader} instance. */
    private static final FastReader SCANNER = new FastReader();

    /** ------------------------------------------------------------------ */
    /** Entry point. */
    public static void main(String[] args) throws Exception {
        // 1️⃣  Read and store the input data.
        int dimension = SCANNER.nextInt();
        int[] values = readRemainingValues(dimension * dimension);

        // 2️⃣  Special‑case for 1×1 matrix.
        if (dimension == 1) {
            System.out.println("YES");
            System.out.println(values[0]);
            return;
        }

        // 3️⃣  Validate whether a valid construction exists.
        if (!canConstructSymmetricMatrix(values, dimension)) {
            System.out.println("NO");
            return;
        }

        // 4️⃣  Build the matrix.
        int[][] matrix = constructMatrix(values, dimension);

        // 5️⃣  Output the result.
        System.out.println("YES");
        printMatrix(matrix);
    }

    /** ------------------------------------------------------------------ */
    /** Reads {@code count} integers from {@link #SCANNER} and returns them
     *  as an int array. */
    private static int[] readRemainingValues(int count) throws IOException {
        int[] data = new int[count];
        for (int i = 0; i < count; i++) {
            data[i] = SCANNER.nextInt();
        }
        return data;
    }

    /** ------------------------------------------------------------------ */
    /** Determines whether the supplied numbers can fill an {@code n×n}
     *  symmetric matrix under the problem constraints.
     *
     *  @return {@code true} if a matrix can be built, otherwise {@code false}. */
    private static boolean canConstructSymmetricMatrix(int[] numbers, int n) {
        // Frequency of each possible value (indices 0 … 1000 are used).
        int[] frequency = buildFrequencyMap(numbers);

        // Counters for numbers that are odd/even but not divisible by 4.
        int oddCount = 0;
        int notDivisibleByFourEvenCount = 0;

        // Queues for numbers that have at least 4 or 2 remaining copies.
        Queue<Integer> atLeastFour = new LinkedList<>();
        Queue<Integer> atLeastTwo  = new LinkedList<>();

        // Scan the frequency table once to fill the auxiliary collections.
        for (int value = 0; value <= MAX_VALUE; value++) {
            int cnt = frequency[value];
            if (cnt % 4 != 0) {
                if (cnt % 2 == 0) {
                    notDivisibleByFourEvenCount++;
                } else {
                    oddCount++;
                }
            }
            if (cnt >= 4) {
                atLeastFour.add(value);
            }
            if (cnt >= 2) {
                atLeastTwo.add(value);
            }
        }

        // Main validation rules:
        //   • If n is even, there must be no odd count and no leftover evens.
        //   • For odd n, at most one odd count is allowed and we need enough
        //     numbers that can supply the “edges” (needs at most n‑1 pairs).
        boolean evenDimension = (n % 2 == 0);
        boolean validationFails =
                (evenDimension && (oddCount != 0 || notDivisibleByFourEvenCount != 0))
                || oddCount > 1
                || (!evenDimension && notDivisibleByFourEvenCount > n - 1);

        if (validationFails) {
            return false;
        }

        // All checks passed – a matrix can be built.
        return true;
    }

    /** ------------------------------------------------------------------ */
    /** Constructs (or returns a placeholder) a frequency map for the
     *  given input numbers. The returned array has size {@code MAX_VALUE+1}
     *  and stores how many times each value appears. */
    private static int[] buildFrequencyMap(int[] numbers) {
        int[] freq = new int[MAX_VALUE + 1];
        for (int v : numbers) {
            freq[v]++;
        }
        return freq;
    }

    /** ------------------------------------------------------------------ */
    /** Creates an {@code n×n} matrix that respects the symmetry constraints.
     *  The method assumes that {@code canConstructSymmetricMatrix} has already
     *  validated the input.
     *
     *  @return the constructed matrix */
    private static int[][] constructMatrix(int[] numbers, int n) {
        int[] freq = buildFrequencyMap(numbers);

        // Helper queues that will be reused during construction.
        Queue<Integer> fourPool   = new LinkedList<>();
        Queue<Integer> twoPool    = new LinkedList<>();

        // Populate the queues with values that still have enough copies.
        for (int value = 0; value <= MAX_VALUE; value++) {
            if (freq[value] >= 4) {
                fourPool.add(value);
            }
            if (freq[value] >= 2) {
                twoPool.add(value);
            }
        }

        int[][] matrix = new int[n][n];

        // ---------- Fill the four‑by‑four quadrants (central symmetry) ----------
        int firstQuadValue = fourPool.poll();
        for (int i = 0; i < n / 2; i++) {
            for (int j = 0; j < n / 2; j++) {
                // Ensure we always have a value that still has at least 4 copies.
                while (freq[firstQuadValue] < 4) {
                    firstQuadValue = fourPool.poll();
                }
                placeQuadSymmetry(matrix, i, j, firstQuadValue);
                freq[firstQuadValue] -= 4;
            }
        }

        // ---------- Fill the edge‑centers for odd dimensions ----------
        if (n % 2 == 1) {
            // The centre cell gets a single value (needs no condition).
            int centreValue = twoPool.poll(); // any value with at least 2 copies
            while (freq[centreValue] < 2) {
                centreValue = twoPool.poll();
            }
            matrix[n / 2][n / 2] = centreValue;
            freq[centreValue] -= 2; // one pair is used for the centre cell

            // Fill the symmetric rows/columns around the centre.
            // Horizontal ring.
            int horizValue = twoPool.poll();
            while (freq[horizValue] < 2) {
                horizValue = twoPool.poll();
            }
            for (int col = 0; col < n / 2; col++) {
                while (freq[horizValue] < 2) {
                    horizValue = twoPool.poll();
                }
                placeHorizontalSymmetry(matrix, n / 2, col, horizValue);
                freq[horizValue] -= 2;
            }

            // Vertical ring.
            int verticalValue = twoPool.poll();
            while (freq[verticalValue] < 2) {
                verticalValue = twoPool.poll();
            }
            for (int row = 0; row < n / 2; row++) {
                while (freq[verticalValue] < 2) {
                    verticalValue = twoPool.poll();
                }
                placeVerticalSymmetry(matrix, row, n / 2, verticalValue);
                freq[verticalValue] -= 2;
            }

            // Finally, place any remaining value at the exact centre.
            for (int value = 0; value <= MAX_VALUE; value++) {
                if (freq[value] > 0) {
                    matrix[n / 2][n / 2] = value;
                    break;
                }
            }
        }

        return matrix;
    }

    /** ------------------------------------------------------------------ */
    /** Places a value into the four symmetric positions that belong to the
     *  “quadrant” centred at (i, j). The four positions are:
     *  <pre>
     *      (i, j)                 (i, n‑j‑1)
     *      (n‑i‑1, j)             (n‑i‑1, n‑j‑1)
     *  </pre>
     *
     *  @param mat the matrix being filled
     *  @param i   row index of the top‑left corner of the current block
     *  @param j   column index of the top‑left corner of the current block
     *  @param val the value to place */
    private static void placeQuadSymmetry(int[][] mat, int i, int j, int val) {
        int n = mat.length;
        mat[i][j] = val;
        mat[i][n - j - 1] = val;
        mat[n - i - 1][j] = val;
        mat[n - i - 1][n - j - 1] = val;
    }

    /** ------------------------------------------------------------------ */
    /** Places a value symmetrically on a single row (horizontal pair). */
    private static void placeHorizontalSymmetry(int[][] mat, int row, int col, int val) {
        int n = mat.length;
        mat[row][col] = val;
        mat[row][n - col - 1] = val;
    }

    /** ------------------------------------------------------------------ */
    /** Places a value symmetrically on a single column (vertical pair). */
    private static void placeVerticalSymmetry(int[][] mat, int row, int col, int val) {
        int n = mat.length;
        mat[row][col] = val;
        mat[n - row - 1][col] = val;
    }

    /** ------------------------------------------------------------------ */
    /** Prints the matrix to {@code System.out} in the required format. */
    private static void printMatrix(int[][] matrix) {
        for (int[] row : matrix) {
            for (int i = 0; i < matrix.length; i++) {
                System.out.print(row[i]);
                if (i < matrix.length - 1) {
                    System.out.print(' ');
                }
            }
            System.out.println();
        }
    }
}

/* -------------------------------------------------------------------------
 * FastReader – a tiny wrapper around {@link BufferedReader} that supplies
 * convenient {@code next()}, {@code nextInt()}, etc. methods used throughout
 * the program.
 * ------------------------------------------------------------------------- */
class FastReader {
    private final BufferedReader br;
    private StringTokenizer st;

    public FastReader() {
        br = new BufferedReader(new InputStreamReader(System.in));
    }

    /** Splits the next line on whitespace and returns the next token. */
    private String nextToken() throws IOException {
        if (st == null || !st.hasMoreElements()) {
            st = new StringTokenizer(br.readLine());
        }
        return st.nextToken();
    }

    /** @return the next integer token */
    public int nextInt() throws IOException {
        return Integer.parseInt(nextToken());
    }
}

import java.io.*;
import java.util.*;

/**
 * Reads a square matrix size {@code n} and {@code n²} integers,
 * determines whether those integers can be arranged into a
 * palindromic matrix (symmetric with respect to both main diagonals),
 * and prints the matrix if possible.
 *
 * The implementation is intentionally split into small, single‑purpose
 * methods to improve readability, testability and maintainability.
 */
public class PalindromicMatrix {

    /** Entry point. */
    public static void main(String[] args) throws IOException {
        try (BufferedReader reader = new BufferedReader(
                new InputStreamReader(System.in))) {

            int n = parseSize(reader);
            List<Integer> numbers = parseNumbers(reader, n * n);
            int[][] result = buildPalindromicMatrix(n, numbers);

            if (result == null) {
                System.out.println("NO");
            } else {
                System.out.println("YES");
                printMatrix(result);
            }
        }
    }

    /** Parses the first line of input and returns the dimension {@code n}. */
    private static int parseSize(BufferedReader reader) throws IOException {
        String line = reader.readLine();
        if (line == null || line.isBlank()) {
            throw new IllegalArgumentException("Empty input – expected matrix size.");
        }
        return Integer.parseInt(line.trim());
    }

    /** Reads exactly {@code count} integers from the next non‑empty line. */
    private static List<Integer> parseNumbers(BufferedReader reader, int count) throws IOException {
        String line = reader.readLine();
        if (line == null) {
            throw new IllegalArgumentException("Not enough input data.");
        }
        StringTokenizer tokenizer = new StringTokenizer(line);
        if (tokenizer.countTokens() < count) {
            throw new IllegalArgumentException("Expected at least " + count + " numbers.");
        }
        List<Integer> numbers = new ArrayList<>(count);
        while (numbers.size() < count && tokenizer.hasMoreTokens()) {
            numbers.add(Integer.parseInt(tokenizer.nextToken()));
        }
        if (numbers.size() != count) {
            throw new IllegalArgumentException("Insufficient numbers provided.");
        }
        return numbers;
    }

    /**
     * Attempts to build a palindromic matrix from the supplied numbers.
     *
     * @return the filled {@code int[][]} when possible, otherwise {@code null}.
     */
    private static int[][] buildPalindromicMatrix(int n, List<Integer> numbers) {
        // Count frequency of each distinct value.
        Map<Integer, Integer> frequency = countFrequencies(numbers);

        // Prepare the result matrix.
        int[][] matrix = new int[n][n];

        if (n % 2 == 0) {
            // Even dimension → only groups of 4 are required.
            return fillEvenMatrix(matrix, frequency);
        }

        // Odd dimension → mixture of groups of 4, 2 and a single centre.
        return fillOddMatrix(matrix, frequency);
    }

    /** Counts how many times each distinct integer appears in the list. */
    private static Map<Integer, Integer> countFrequencies(List<Integer> numbers) {
        Map<Integer, Integer> count = new HashMap<>();
        for (int value : numbers) {
            count.merge(value, 1, Integer::sum);
        }
        return count;
    }

    /** Fills the matrix for an even {@code n} (only groups of 4 required). */
    private static int[][] fillEvenMatrix(int[][] matrix, Map<Integer, Integer> frequency) {
        int half = matrix.length / 2;
        int row = 0;
        int col = 0;

        for (int value : frequency.keySet()) {
            int remaining = frequency.get(value);
            if (remaining % 4 != 0) {
                // Not enough symmetric positions for this value.
                System.out.println("NO");
                System.exit(0);
            }

            while (remaining > 0) {
                placeQuad(value, matrix, row, col);
                remaining -= 4;
                advancePosition(row, col, half);
            }
        }
        return matrix;
    }

    /** Places a value in the four symmetric cells of a quadrant defined by (row, col). */
    private static void placeQuad(int value, int[][] matrix, int row, int col) {
        int n = matrix.length;
        matrix[row][col] = value;
        matrix[n - 1 - row][n - 1 - col] = value;
        matrix[row][n - 1 - col] = value;
        matrix[n - 1 - row][col] = value;
    }

    /** Moves to the next cell in row‑major order inside the top‑left quadrant. */
    private static void advancePosition(int row, int col, int quadrantSize) {
        if (row == quadrantSize - 1) {
            // End of column – move to next column, keep row at 0.
            // (When column also reaches the end, the caller will stop.)
            // Here we simply keep row at 0; the caller handles termination.
        } else {
            // Move to next row in the same column.
        }
        // The caller maintains the state; we only provide the logic for row transition.
    }

    /** Fills the matrix for an odd {@code n} (groups of 4, 2 and a single centre). */
    private static int[][] fillOddMatrix(int[][] matrix, Map<Integer, Integer> frequency) {
        int size = matrix.length;
        int half = size / 2;               // index of the middle row / column
        int centre = half;
        int row = 0;
        int col = 0;
        int remainingQuadrantSlots = centre * centre * 4;
        boolean midUsed = false;           // whether the middle row/column pair is exhausted
        boolean centreUsed = false;        // centre cell already assigned

        for (int value : frequency.keySet()) {
            int count = frequency.get(value);

            // ---- 1. Fill groups of 4 (quadrants) ---------------------------------
            while (count >= 4 && remainingQuadrantSlots > 0) {
                placeQuad(value, matrix, row, col);
                count -= 4;
                remainingQuadrantSlots -= 4;
                advancePosition(row, col, half);
            }

            // ---- 2. Fill pairs along the middle row / column --------------------
            while (count >= 2) {
                if (midUsed) {
                    System.out.println("NO");
                    System.exit(0);
                }
                if (!midUsed) {
                    // First use the middle row (horizontal pair)
                    placeHorizontalPair(value, matrix, centre, col);
                    count -= 2;
                    midUsed = true; // now switch to vertical placement
                } else {
                    // Place vertical pair using the middle column
                    placeVerticalPair(value, matrix, row, centre);
                    count -= 2;
                    row++;
                    if (row == centre) {
                        // Reset to start of a new column in the middle row
                        row = 0;
                    }
                }
            }

            // ---- 3. Place a single centre element -------------------------------
            if (count == 1) {
                if (centreUsed) {
                    System.out.println("NO");
                    System.exit(0);
                }
                matrix[centre][centre] = value;
                centreUsed = true;
            } else if (count > 1) {
                // Unexpected leftover that cannot be placed.
                System.out.println("NO");
                System.exit(0);
            }
        }

        return matrix;
    }

    /** Places a value horizontally across the middle row at column {@code col}. */
    private static void placeHorizontalPair(int value, int[][] matrix, int centre, int col) {
        int n = matrix.length;
        matrix[centre][col] = value;
        matrix[centre][n - 1 - col] = value;
    }

    /** Places a value vertically across the middle column at row {@code row}. */
    private static void placeVerticalPair(int value, int[][] matrix, int row, int centre) {
        int n = matrix.length;
        matrix[row][centre] = value;
        matrix[n - 1 - row][centre] = value;
    }

    /** Moves to the next cell in the top‑left quadrant (row‑major order). */
    private static void advancePosition(int row, int col, int quadrantSize) {
        // The caller updates both row and col; this method only extracts the logic.
        // Keeping it empty preserves readability while allowing future enhancements.
    }

    /** Prints the matrix row by row, separating elements by a single space. */
    private static void printMatrix(int[][] matrix) {
        for (int[] row : matrix) {
            for (int i = 0; i < row.length; i++) {
                System.out.print(row[i]);
                if (i < row.length - 1) {
                    System.out.print(' ');
                }
            }
            System.out.println();
        }
    }
}

import java.io.*;
import java.util.*;

public class CF1118C {

    /** Maximum possible value that can appear in the input. */
    private static final int MAX_VALUE = 1000;

    /** Maximum matrix dimension the algorithm needs to support. */
    private static final int MAX_N = 25;

    /**
     * Writes "NO" if it is impossible to construct a symmetric matrix,
     * otherwise prints "YES" followed by one possible symmetric arrangement.
     */
    public static void main(String[] args) throws IOException {
        try (Scanner in = new Scanner(new BufferedInputStream(System.in))) {
            PrintWriter out = new PrintWriter(new BufferedOutputStream(System.out));

            int n = in.nextInt();                 // size of the matrix
            int[] frequency = new int[MAX_VALUE + 1]; // index = value, value = count

            // Read n·n numbers and count their occurrences
            for (int i = 0; i < n * n; i++) {
                int value = in.nextInt();
                if (value < 1 || value > MAX_VALUE) {
                    throw new IllegalArgumentException("Value out of allowed range [1..1000]");
                }
                frequency[value]++;
            }

            int[][] matrix = new int[n][n];       // result matrix, initially all zeros
            fillSymmetricQuadrants(n, matrix, frequency);
            if (n % 2 == 1) {
                fillMiddleRowAndColumn(n, matrix, frequency);
            }
            placeCenterIfNeeded(n, matrix, frequency);

            // After all placements there must be no empty cells left
            if (hasEmptyCell(matrix)) {
                out.println("NO");
            } else {
                out.println("YES");
                printMatrix(matrix, out);
            }

            out.flush();   // ensure output is flushed before closing
        }
    }

    /** Fill the four symmetric cells surrounding (i, j) with the first suitable value. */
    private static void placeSymmetric(int i, int j, int[][] matrix, int[] freq) {
        for (int value = 1; value <= MAX_VALUE; value++) {
            if (freq[value] >= 4) {
                matrix[i][j] = matrix[i][n - j - 1] = matrix[n - i - 1][j] = matrix[n - i - 1][n - j - 1] = value;
                freq[value] -= 4;
                break;
            }
        }
    }

    /**
     * Fill all “quarter‑grid” cells (top‑left quadrant) with symmetric groups of four.
     */
    private static void fillSymmetricQuadrants(int n, int[][] matrix, int[] freq) {
        int half = n / 2;
        for (int i = 0; i < half; i++) {
            for (int j = 0; j < half; j++) {
                placeSymmetric(i, j, matrix, freq);
            }
        }
    }

    /**
     * Fill the middle row and column (for odd n) using pairs of symmetric cells.
     */
    private static void fillMiddleRowAndColumn(int n, int[][] matrix, int[] freq) {
        int mid = n / 2;
        // Fill pairs along the middle row (except the centre)
        for (int j = mid - 1; j >= 0; j--) {
            pairIntoPositions(mid, j, n - j - 1, matrix, freq);
        }
        // Fill pairs along the middle column (except the centre)
        for (int i = mid - 1; i >= 0; i--) {
            pairIntoPositions(i, mid, n - i - 1, matrix, freq);
        }
    }

    /** Helper: place a pair of equal numbers at symmetrical positions (i, col) and (n‑i‑1, col). */
    private static void pairIntoPositions(int i, int col, int symmetricCol, int[][] matrix, int[] freq) {
        for (int value = 1; value <= MAX_VALUE; value++) {
            if (freq[value] >= 2) {
                matrix[i][col] = matrix[n - i - 1][col] = value;
                freq[value] -= 2;
                break;
            }
        }
    }

    /** Place the single centre element when n is odd (if any value remains with count 1). */
    private static void placeCenterIfNeeded(int n, int[][] matrix, int[] freq) {
        if (n % 2 == 0) {
            return;
        }
        int half = n / 2;
        for (int value = 1; value <= MAX_VALUE; value++) {
            if (freq[value] == 1) {
                matrix[half][half] = value;
                freq[value]--;      // not used later, but keeps the state consistent
                break;
            }
        }
    }

    /** Verify that every cell in the matrix was filled (i.e., no zero left). */
    private static boolean hasEmptyCell(int[][] matrix) {
        for (int[] row : matrix) {
            for (int cell : row) {
                if (cell == 0) {
                    return true;
                }
            }
        }
        return false;
    }

    /** Print the matrix to the given PrintWriter. */
    private static void printMatrix(int[][] matrix, PrintWriter out) {
        for (int[] row : matrix) {
            for (int i = 0; i < matrix.length; i++) {
                out.print(row[i]);
                if (i < matrix.length - 1) {
                    out.print(' ');
                }
            }
            out.println();
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Utility class that reads input and writes output.
 */
final class IoUtil {
    private final BufferedReader reader;
    private final StringTokenizer tokenizer;

    IoUtil(Reader source) {
        this.reader = new BufferedReader(source);
        this.tokenizer = null;
    }

    private void ensureTokenizer() throws IOException {
        while (tokenizer == null || !tokenizer.hasMoreTokens()) {
            String line = reader.readLine();
            if (line == null) {
                tokenizer = null;
                return;
            }
            tokenizer = new StringTokenizer(line);
        }
    }

    /** Reads the next integer token. */
    int nextInt() throws IOException {
        ensureTokenizer();
        return Integer.parseInt(tokenizer.nextToken());
    }

    /** Returns an array of {@code size} integers. */
    int[] nextIntArray(int size) throws IOException {
        int[] arr = new int[size];
        for (int i = 0; i < size; i++) {
            arr[i] = nextInt();
        }
        return arr;
    }
}

/**
 * Simple wrapper around a PrintWriter that knows how to emit the final matrix.
 */
final class OutputWriter {
    private final PrintWriter writer;

    OutputWriter(Writer sink) {
        this.writer = new PrintWriter(sink);
    }

    void println(String msg) {
        writer.println(msg);
    }

    /** Prints a 2‑D int matrix row by row. */
    void print(int[][] matrix) {
        for (int[] row : matrix) {
            for (int value : row) {
                writer.print(value + " ");
            }
            writer.println();
        }
    }

    void close() {
        writer.close();
    }
}

/**
 * Holds the matrix that will be filled with numbers.
 */
final class PalindromeMatrix {
    private final int[][] grid;

    PalindromeMatrix(int size) {
        this.grid = new int[size][size];
    }

    int get(int r, int c) {
        return grid[r][c];
    }

    void set(int r, int c, int value) {
        grid[r][c] = value;
    }

    /** Returns the underlying 2‑D array (used only for output). */
    int[][] raw() {
        return grid;
    }

    /** Replaces every cell with {@code value}. */
    void fill(int value) {
        for (int[] row : grid) {
            Arrays.fill(row, value);
        }
    }

    int size() {
        return grid.length;
    }
}

/**
 * Core solver that decides whether a palindrome matrix can be constructed
 * from the given numbers and prints the result.
 */
final class Solver {
    private static final int MAX_VALUE = 1000;   // problem guarantees values ≤ 1000

    private final IoUtil in;
    private final OutputWriter out;

    Solver(IoUtil in, OutputWriter out) {
        this.in = in;
        this.out = out;
    }

    /** Entry point called from {@code main}. */
    void solve() throws IOException {
        int n = in.nextInt();
        int[] values = in.nextIntArray(n);

        int[] frequency = countFrequencies(values);
        boolean possible = buildPalindromeMatrix(n, frequency);
        if (!possible) {
            out.println("NO");
        }
    }

    /**
     * Attempts to fill a {@code n×n} matrix that is symmetric both horizontally
     * and vertically using the supplied frequencies.
     *
     * @return {@code true} if a matrix was built, {@code false} otherwise.
     */
    private boolean buildPalindromeMatrix(int n, int[] frequency) {
        PalindromeMatrix matrix = new PalindromeMatrix(n);

        /* --------------------------------------------------------------
         * 1️⃣  Fill the four‑way symmetric positions (top‑left quadrant)
         * -------------------------------------------------------------- */
        for (int i = 0; i < n / 2; i++) {
            for (int k = 0; k < n / 2; k++) {
                int placed = placeQuadruple(frequency);
                if (placed == -1) {
                    out.println("NO");
                    return false;
                }
                placeQuadrupleInto(matrix, i, k, placed);
            }
        }

        /* --------------------------------------------------------------
         * 2️⃣  If n is odd, handle the middle row, middle column and centre
         * -------------------------------------------------------------- */
        if (n % 2 == 1) {
            int mid = n / 2;

            // pairs along the middle row
            for (int i = 0; i < n / 2; i++) {
                int placed = placeDouble(frequency);
                if (placed == -1) {
                    out.println("NO");
                    return false;
                }
                placeDoubleInto(matrix, i, mid, placed);
                placeDoubleInto(matrix, n - 1 - i, mid, placed);
            }

            // pairs along the middle column
            for (int i = 0; i < n / 2; i++) {
                int placed = placeDouble(frequency);
                if (placed == -1) {
                    out.println("NO");
                    return false;
                }
                placeDoubleInto(matrix, mid, i, placed);
                placeDoubleInto(matrix, mid, n - 1 - i, placed);
            }

            // centre cell (only one value may remain)
            for (int value = 0; value <= MAX_VALUE; value++) {
                if (frequency[value] > 0) {
                    matrix.set(mid, mid, value);
                    out.println("YES");
                    out.print(matrix.raw());
                    return true;
                }
            }
            out.println("NO");
            return false;
        }

        /* --------------------------------------------------------------
         * 3️⃣  Even n – everything is already placed
         * -------------------------------------------------------------- */
        out.println("YES");
        out.print(matrix.raw());
        return true;
    }

    /** Fills four symmetric cells with a number that appears at least 4 times. */
    private void placeQuadrupleInto(PalindromeMatrix matrix, int i, int k, int value) {
        int oppI = matrix.size() - 1 - i;
        int oppK = matrix.size() - 1 - k;
        matrix.set(i, k, value);
        matrix.set(oppI, k, value);
        matrix.set(i, oppK, value);
        matrix.set(oppI, oppK, value);
    }

    /** Uses a number that appears at least 2 times for a pair on a line. */
    private void placeDoubleInto(PalindromeMatrix matrix, int i, int j, int value) {
        matrix.set(i, j, value);
        // The symmetric position (reflected across the centre) is filled later by the caller.
    }

    /** Returns the first value that occurs at least {@code 4} times, otherwise –1. */
    private int placeQuadruple(int[] freq) {
        for (int v = 0; v <= MAX_VALUE; v++) {
            if (freq[v] >= 4) {
                freq[v] -= 4;
                return v;
            }
        }
        return -1;
    }

    /** Returns the first value that occurs at least {@code 2} times, otherwise –1. */
    private int placeDouble(int[] freq) {
        for (int v = 0; v <= MAX_VALUE; v++) {
            if (freq[v] >= 2) {
                freq[v] -= 2;
                return v;
            }
        }
        return -1;
    }

    /** Counts how many times each value appears (only values ≤ MAX_VALUE are counted). */
    private int[] countFrequencies(int[] values) {
        int[] freq = new int[MAX_VALUE + 1];
        for (int v : values) {
            if (v <= MAX_VALUE) {
                freq[v]++;
            }
        }
        return freq;
    }
}

/** Classic “main” entry point that wires everything together. */
public class Main {
    public static void main(String[] args) throws Exception {
        try (InputReader reader = new InputReader(new InputStreamReader(System.in);
             OutputWriter writer = new OutputWriter(new OutputStreamWriter(System.out))) {
            new Solver(reader, writer).solve();
        }
    }

    /** Minimal input reader that re‑uses the token logic from the original code. */
    private static final class InputReader {
        private final BufferedReader br;

        InputReader(Reader source) {
            this.br = new BufferedReader(source);
        }

        String readLine() {
            try {
                return br.readLine();
            } catch (IOException e) {
                throw new UncheckedIOException(e);
            }
        }

        int nextInt() {
            try {
                return Integer.parseInt(readLine());
            } catch (IOException e) {
                throw new UncheckedIOException(e);
            }
        }
    }
}

/**
 * Refactored solution for constructing a palindromic matrix.
 *
 * The program reads an integer {@code n} followed by {@code n*n} integers,
 * attempts to arrange them into an {@code n×n} matrix that is symmetric
 * with respect to the center (i.e., each element appears mirrored across both
 * diagonals), and prints the resulting matrix. If such a matrix cannot be
 * formed, it prints {@code NO}; otherwise it prints {@code YES} followed by
 * the matrix.
 */
import java.io.*;
import java.util.*;

public class Main {

    /** Entry point of the program. */
    public static void main(String[] args) {
        InputStream inStream = System.in;
        OutputStream outStream = System.out;
        InputReader in = new InputReader(inStream);
        PrintWriter out = new PrintWriter(outStream);
        PalindromicMatrix solver = new PalindromicMatrix();
        solver.solve(in, out);
        out.flush();
    }

    /**
     * Simple wrapper around {@link InputStream} that provides fast integer
     * reading. It masks low‑level I/O details from the core solving logic.
     */
    static class InputReader {
        private final InputStream stream;
        private final byte[] buffer = new byte[1 << 10];
        private int pointer = 0, length = 0;

        InputReader(InputStream stream) {
            this.stream = stream;
        }

        private int readByte() throws IOException {
            if (pointer >= length) {
                length = stream.read(buffer);
                pointer = 0;
                if (length <= 0) return -1;
            }
            return buffer[pointer++];
        }

        private boolean isSpace(int ch) {
            return ch == ' ' || ch == '\n' || ch == '\r' || ch == '\t' || ch == -1;
        }

        /** Reads the next integer from the input. */
        int nextInt() {
            int c;
            do {
                c = readByte();
            } while (isSpace(c));
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = readByte();
            }
            int result = 0;
            while (!isSpace(c)) {
                result = result * 10 + (c - '0');
                c = readByte();
            }
            return result * sign;
        }

        /**
         * Reads {@code n} integers and returns them as an array.
         *
         * @param n     number of integers to read
         * @param offset position in the output array where the first value will be stored
         * @return array containing the read integers
         */
        int[] nextIntArray(int n, int offset) {
            int[] arr = new int[n];
            for (int i = 0; i < n; i++) {
                arr[i] = nextInt();
            }
            return arr;
        }
    }

    /**
     * Core class that contains the logic for building a palindromic matrix.
     * All public methods are kept small and focused to improve readability
     * and maintainability.
     */
    static class PalindromicMatrix {

        /** Solves a single test case using the supplied input reader and output writer. */
        void solve(InputReader scanner, PrintWriter out) {
            int n = scanner.nextInt();
            int[] flat = scanner.nextIntArray(n * n, 1);
            int[][] matrix = constructMatrix(n, flat);
            if (matrix == null) {
                out.println("NO");
                return;
            }
            out.println("YES");
            printMatrix(matrix, out);
        }

        /**
         * Attempts to build a palindromic matrix of size {@code n}.
         *
         * @return the constructed matrix, or {@code null} if construction is impossible
         */
        private int[][] constructMatrix(int n, int[] flat) {
            int[] count = countOccurrences(flat);
            int[][] result = new int[n + 1][n + 1]; // 1‑based indexing

            if (n % 2 == 0) {
                return fillEvenMatrix(n, count, result);
            } else {
                return fillOddMatrix(n, count, result);
            }
        }

        /** Handles the even‑size case. */
        private int[][] fillEvenMatrix(int n, int[] count, int[][] matrix) {
            // Every value must appear a multiple of 4 times.
            for (int v = 1; v <= 1000; v++) {
                if (count[v] % 4 != 0) {
                    return null;
                }
            }

            int half = n / 2;
            for (int i = 1; i <= half; i++) {
                for (int j = 1; j <= half; j++) {
                    int val = pickValue(count);
                    matrix[i][j] = val;
                    matrix[i][n + 1 - j] = val;
                    matrix[n + 1 - i][j] = val;
                    matrix[n + 1 - i][n + 1 - j] = val;
                    count[val] -= 4;
                }
            }
            return matrix;
        }

        /** Handles the odd‑size case. */
        private int[][] fillOddMatrix(int n, int[] count, int[][] matrix) {
            int half = n / 2;
            int centreIdx = half + 1;

            // Place the centre element (needs exactly one occurrence).
            int centreValue = findSingle(count);
            if (centreValue == -1) {
                return null;
            }
            matrix[centreIdx][centreIdx] = centreValue;
            count[centreValue]--;

            // Fill symmetric pairs on the middle row and column (require 2 copies each).
            fillMiddleRowAndColumn(n, half, count, matrix, centreIdx);

            // Fill the four quadrants (require 4 copies each).
            for (int i = 1; i <= half; i++) {
                for (int j = 1; j <= half; j++) {
                    int val = pickValue(count);
                    matrix[i][j] = val;
                    matrix[i][n + 1 - j] = val;
                    matrix[n + 1 - i][j] = val;
                    matrix[n + 1 - i][n + 1 - j] = val;
                    count[val] -= 4;
                }
            }
            return matrix;
        }

        /** Places values into the middle row and column that need only two copies each. */
        private void fillMiddleRowAndColumn(int n, int half, int[] count,
                                            int[][] matrix, int centreIdx) {
            // Middle row (excluding centre)
            for (int j = 1; j <= half; j++) {
                int val = pickTwo(count);
                if (val == -1) return;
                matrix[centreIdx][j] = val;
                matrix[centreIdx][n + 1 - j] = val;
                count[val] -= 2;
            }
            // Middle column (excluding centre)
            for (int i = 1; i <= half; i++) {
                int val = pickTwo(count);
                if (val == -1) return;
                matrix[i][centreIdx] = val;
                matrix[n + 1 - i][centreIdx] = val;
                count[val] -= 2;
            }
        }

        /** Returns a value that appears exactly once (used for the centre). */
        private int findSingle(int[] count) {
            for (int v = 1; v <= 1000; v++) {
                if (count[v] == 1) {
                    return v;
                }
            }
            return -1;
        }

        /** Returns a value that still has at least four copies. */
        private int pickValue(int[] count) {
            for (int v = 1; v <= 1000; v++) {
                if (count[v] >= 4) {
                    return v;
                }
            }
            return -1; // Should never happen if caller validation succeeded.
        }

        /** Returns a value that still has at least two copies. */
        private int pickTwo(int[] count) {
            for (int v = 1; v <= 1000; v++) {
                if (count[v] >= 2) {
                    return v;
                }
            }
            return -1;
        }

        /** Prints the matrix to the supplied output writer. */
        private void printMatrix(int[][] matrix, PrintWriter out) {
            int n = matrix.length - 1; // matrix is 1‑based
            for (int i = 1; i <= n; i++) {
                StringBuilder row = new StringBuilder();
                for (int j = 1; j <= n; j++) {
                    row.append(matrix[i][j]);
                    if (j < n) row.append(' ');
                }
                out.println(row.toString());
            }
        }
    }
}

/**
 * Reads an integer matrix size {@code n} followed by {@code n*n} integers
 * and tries to construct an {@code n×n} matrix that is symmetric with respect
 * to both its main diagonal and anti‑diagonal. The numbers are taken from the
 * input multiset respecting the required multiplicities (4‑fold, 2‑fold,
 * 1‑fold). If construction is impossible the program prints {@code "NO"},
 * otherwise it prints {@code "YES"} followed by the constructed matrix.
 */
public class SymmetricMatrixBuilder {

    /** Maximum value that can appear in the input. */
    private static final int MAX_VALUE = 1_000;

    /** Input reader – fast enough for typical competitive‑programming limits. */
    private static final InputReader IN = new InputReader(System.in);
    /** Output writer – buffers output for speed. */
    private static final PrintWriter OUT = new PrintWriter(System.out);

    public static void main(String[] args) {
        solve();
        OUT.close();
    }

    /** Orchestrates the whole solving process. */
    private static void solve() {
        int n = IN.nextInt();
        fillFrequencyArray(n);
        int[][] matrix = constructSymmetricMatrix(n);
        if (matrix == null) {
            System.out.println("NO");
            return;
        }
        System.out.println("YES");
        printMatrix(matrix);
    }

    /** Reads {@code n*n} numbers and stores their frequencies in {@code count}. */
    private static void fillFrequencyArray(int n) {
        int needed = n * n;
        int[] count = new int[MAX_VALUE + 1];
        for (int i = 0; i < needed; i++) {
            int value = IN.nextInt();
            if (value < 1 || value > MAX_VALUE) {
                throw new IllegalArgumentException("Value out of expected range [1, " + MAX_VALUE + "]");
            }
            count[value]++;               // count[0] stays unused
        }
        process(matrixBuilder(n), count);
    }

    /** Builds the skeleton of the matrix (empty int[][]) that will be filled later. */
    private static int[][] matrixBuilder(int n) {
        return new int[n][n];
    }

    /**
     * Main construction routine – places numbers respecting the multiplicities
     * required by symmetry.
     *
     * @param count frequency table of size {@code MAX_VALUE+1}
     * @return the filled matrix, or {@code null} if construction is impossible
     */
    private static int[][] constructSymmetricMatrix(int n) {
        int[][] out = matrixBuilder(n);
        int k = 1; // we search starting from 1 (value 0 is unused)

        // ------------------------------
        // 1. Fill the four‑fold corners (quadrants)
        // ------------------------------
        for (int i = 0; i < n / 2; i++) {
            int i1 = n - 1 - i;
            for (int j = 0; j < n / 2; j++) {
                int j1 = n - 1 - j;

                // Find the smallest unused value that appears at least 4 times
                while (k <= MAX_VALUE && countAtLeast(k, count, 4)) k++;
                if (k > MAX_VALUE) {
                    return null;                    // not enough copies for a quadrant
                }
                placeFour(k, i, j, out);
                count[k] -= 4;
            }
        }

        // ------------------------------
        // 2. Handle odd dimension: edges and centre
        // ------------------------------
        if ((n % 2) == 1) {
            int c = n / 2;               // centre index

            // Cells that belong to the central row/column but are not the centre
            for (int i = 0; i < c; i++) {
                int i1 = n - 1 - i;

                // First pair (vertical symmetry positions)
                while (k <= MAX_VALUE && countAtLeast(k, count, 2)) k++;
                if (k > MAX_VALUE) return null;
                placeTwo(k, c, i, out);
                placeTwo(k, c, i1, out);
                count[k] -= 2;

                // Second pair (horizontal symmetry positions)
                while (k <= MAX_VALUE && countAtLeast(k, count, 2)) k++;
                if (k > MAX_VALUE) return null;
                placeTwo(k, i, c, out);
                placeTwo(k, i1, c, out);
                count[k] -= 2;
            }

            // Finally the exact centre cell needs a single copy
            while (count[k] == 0) k++;
            if (k > MAX_VALUE) return null;
            out[c][c] = k;
        }

        return out;
    }

    /** Places the same value {@code v} at four symmetric positions. */
    private static void placeFour(int v, int i, int j, int[][] matrix) {
        int n = matrix.length;
        int i1 = n - 1 - i;
        int j1 = n - 1 - j;
        matrix[i][j] = matrix[i][j1] = matrix[i1][j] = matrix[i1][j1] = v;
    }

    /** Places the same value {@code v} at two symmetric positions (used for edges). */
    private static void placeTwo(int v, int i, int j, int[][] matrix) {
        matrix[i][j] = v;
    }

    /** Utility: returns true iff {@code count[v]} >= {@code required}. */
    private static boolean countAtLeast(int v, int[] count, int required) {
        return count[v] >= required;
    }

    /** Simple printer – writes the matrix row by row. */
    private static void printMatrix(int[][] matrix) {
        for (int[] row : matrix) {
            for (int val : row) {
                OUT.print(val);
                OUT.print(' ');
            }
            OUT.println();
        }
    }

    /* --------------------------------------------------------------------- */
    /* -------------------------- INPUT READER -------------------------------- */
    /* --------------------------------------------------------------------- */

    /** Fast scanner that works with standard {@code System.in}. */
    private static final class InputReader {
        private final InputStream stream;
        private final byte[] buffer = new byte[1 << 10];
        private int bytesRead = 0;
        private int curChar = 0;

        /** Creates a new reader for the supplied {@link InputStream}. */
        InputReader(InputStream stream) {
            this.stream = stream;
        }

        /** Reads the next byte, returning -1 on EOF. */
        private int readByte() {
            if (curChar >= bytesRead) {
                curChar = 0;
                bytesRead = stream.read(buffer);
                if (bytesRead <= 0) {
                    return -1;
                }
            }
            return buffer[curChar++];
        }

        /** Skips whitespace characters. */
        private int skipWhitespace() throws IOException {
            int c;
            do {
                c = readByte();
            } while (isSpaceChar(c));
            return c;
        }

        /** Reads the next integer from the input. */
        int nextInt() {
            return (int) readLong();
        }

        /** Reads the next long from the input. */
        long readLong() {
            int c = skipWhitespace();
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = readByte();
            }
            long result = 0;
            while (c >= '0' && c <= '9') {
                result = result * 10 + (c - '0');
                c = readByte();
            }
            return result * sign;
        }
    }
}

import java.io.*;
import java.util.*;

public class CF1118C {

    /** Upper bound of the numbers that can appear in the input. */
    private static final int MAX_VAL = 1000;

    /** Entry point. */
    public static void main(String[] args) throws IOException {
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in))) {
            solve(br);
        }
    }

    /** Reads input, processes the matrix and prints the result. */
    private static void solve(BufferedReader br) throws IOException {
        // -----------------------------------------------------------------
        // 1️⃣  Input parsing
        // -----------------------------------------------------------------
        int n = Integer.parseInt(br.readLine().trim());

        // The next line may contain n·n integers (they could be split across lines)
        StringTokenizer st = new StringTokenizer(br.readLine());
        int totalNumbers = n * n;
        int[] frequency = new int[MAX_VAL + 1];          // frequency[x] = how many times x occurs
        for (int i = 0; i < totalNumbers; i++) {
            int value = Integer.parseInt(st.nextToken());
            if (value < 1 || value > MAX_VAL) {
                // Input guarantees the value is within the range, but we keep the guard for safety
                System.out.println("NO");
                return;
            }
            frequency[value]++;
        }

        // -----------------------------------------------------------------
        // 2️⃣  Feasibility checks
        // -----------------------------------------------------------------
        if (!isFeasible(frequency, n)) {
            System.out.println("NO");
            return;
        }

        // -----------------------------------------------------------------
        // 3️⃣  Build the symmetric matrix
        // -----------------------------------------------------------------
        int[][] board = new int[n][n];
        placeElements(board, frequency, n);

        // -----------------------------------------------------------------
        // 4️⃣  Output
        // -----------------------------------------------------------------
        System.out.println("YES");
        printBoard(board);
    }

    /** Checks whether a solution exists and performs the first part of placement. */
    private static boolean isFeasible(int[] freq, int n) {
        // Count values that appear an odd number of times
        List<Integer> oddValues = new ArrayList<>();
        for (int v = 1; v <= MAX_VAL; v++) {
            if ((freq[v] & 1) == 1) {           // faster than % 2
                oddValues.add(v);
            }
        }

        // For even n there must be no odd occurrences,
        // for odd n there must be exactly one odd occurrence (the centre)
        boolean nIsEven = (n % 2 == 0);
        boolean oddExists = !oddValues.isEmpty();

        if (nIsEven != (!oddValues.isEmpty())) {
            return false;                       // parity mismatch
        }

        if (nIsEven) {
            // No centre – all counts must be usable in groups of 4
            // (handled later when placing quadrants)
            return true;
        }

        // n is odd → take the unique odd value as centre candidate
        int centreCandidate = oddValues.get(0);
        int centrePos = n / 2;
        board[centrePos][centrePos] = centreCandidate;
        freq[centreCandidate]--;                // one copy is used for the centre

        // After removing the centre, all remaining frequencies must be even
        for (int v = 1; v <= MAX_VAL; v++) {
            if ((freq[v] & 1) == 1) {
                return false;                   // stray odd count → impossible
            }
        }
        return true;
    }

    /** Places all remaining numbers into the matrix respecting the symmetry constraints. */
    private static void placeElements(int[][] board, int[] freq, int n) {
        int half = n / 2;         // index of the middle row / column when n is odd
        boolean oddSize = (n % 2 == 1);

        // -------------------------------------------------------------
        // 3a️⃣  Fill the “cross” (middle row & column) when n is odd
        // -------------------------------------------------------------
        if (oddSize) {
            // We need a value whose remaining count ≡ 2 (mod 4) – it can be split
            // evenly across a pair of symmetric positions.
            int candidate = findValueWithMod(freq, 2);
            if (candidate == -1) {
                fail("NO");
            }

            // Populate the vertical symmetric positions (i, half) and (n‑1‑i, half)
            for (int i = 0; i < half; i++) {
                board[i][half] = board[n - 1 - i][half] = candidate;
                freq[candidate] -= 2;          // two copies are consumed
                candidate = findValueWithMod(freq, 2);
                if (candidate == -1) {
                    fail("NO");
                }
            }

            // Populate the horizontal symmetric positions (half, j) and (half, n‑1‑j)
            for (int j = 0; j < half; j++) {
                board[half][j] = board[half][n - 1 - j] = candidate;
                freq[candidate] -= 2;
                candidate = findValueWithMod(freq, 2);
                if (candidate == -1) {
                    fail("NO");
                }
            }
        }

        // -------------------------------------------------------------
        // 3b️⃣  Fill the four symmetric quadrants (size m×m each)
        // -------------------------------------------------------------
        int m = n / 2;
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < m; j++) {
                int val = findNextNonZero(freq);
                if (val == -1) {
                    fail("NO");
                }
                if ((freq[val] & 3) != 0) {   // freq[val] % 4 != 0  → not divisible by 4
                    fail("NO");
                }
                // Place the value in all four symmetric cells
                board[i][j] = board[n - 1 - i][j] = board[i][n - 1 - j] = board[n - 1 - i][n - 1 - j] = val;
                freq[val] -= 4;
            }
        }
    }

    /** Returns the first value ≥ 1 whose frequency satisfies `freq[v] % mod == 0`. */
    private static int findValueWithMod(int[] freq, int mod) {
        for (int v = 1; v <= MAX_VAL; v++) {
            if (freq[v] % mod == 0 && freq[v] > 0) {
                return v;
            }
        }
        return -1; // not found
    }

    /** Returns the first value with a non‑zero frequency. */
    private static int findNextNonZero(int[] freq) {
        for (int v = 1; v <= MAX_VAL; v++) {
            if (freq[v] > 0) {
                return v;
            }
        }
        return -1;
    }

    /** Simple wrapper to print “NO” and terminate the program. */
    private static void fail(String message) {
        System.out.println(message);
        System.exit(0);
    }

    /** Pretty‑prints the resulting matrix. */
    private static void printBoard(int[][] board) {
        for (int[] row : board) {
            for (int cell : row) {
                System.out.print(cell + " ");
            }
            System.out.println();
        }
    }
}

import java.io.ByteArrayInputStream;
import java.io.File;
import java.io.FileInputStream;
import java.io.FileNotFoundException;
import java.io.IOException;
import java.io.PrintWriter;
import java.nio.charset.StandardCharsets;
import java.util.ArrayDeque;
import java.util.Arrays;
import java.util.PriorityQueue;
import java.util.stream.IntStream;

public class c {

    static class Solver {
        int N;
        int[][] mat;
        int[] freq;
        ArrayDeque<int[][]> fours, twos, ones;

        void solve(FastScanner s, PrintWriter out) {
            readInput(s);
            initializeSymmetricPositions();
            processNumbers(out);
            printResult(out);
        }

        private void readInput(FastScanner s) {
            N = s.nextInt();
            int[] numbers = s.nextIntArray(N * N);
            freq = new int[1001];
            for (int num : numbers) {
                freq[num]++;
            }
        }

        private void initializeSymmetricPositions() {
            fours = new ArrayDeque<>();
            twos = new ArrayDeque<>();
            ones = new ArrayDeque<>();

            // Initialize 4-symmetric positions
            for (int i = 0, ii = N - 1; i < N / 2; i++, ii--) {
                for (int j = 0, jj = N - 1; j < N / 2; j++, jj--) {
                    fours.add(createSymmetricGroup(i, j, ii, jj));
                }
            }

            // Initialize 2-symmetric and 1-symmetric positions for odd N
            if (N % 2 == 1) {
                int mid = N / 2;
                ones.add(createSinglePosition(mid, mid));

                for (int i = 0, ii = N - 1; i < N / 2; i++, ii--) {
                    twos.add(createPairPosition(i, mid, ii, mid));
                    twos.add(createPairPosition(mid, i, mid, ii));
                }
            }
        }

        private int[][] createSymmetricGroup(int i, int j, int ii, int jj) {
            return new int[][]{
                {i, j}, {ii, j}, {i, jj}, {ii, jj}
            };
        }

        private int[][] createSinglePosition(int i, int j) {
            return new int[][]{{i, j}};
        }

        private int[][] createPairPosition(int i1, int j1, int i2, int j2) {
            return new int[][]{{i1, j1}, {i2, j2}};
        }

        private void processNumbers(PrintWriter out) {
            PriorityQueue<Integer> freqQueue = new PriorityQueue<>(
                (a, b) -> freq[b] - freq[a]
            );

            for (int num = 1; num <= 1000; num++) {
                if (freq[num] > 0) {
                    freqQueue.add(num);
                }
            }

            while (!freqQueue.isEmpty()) {
                int currentNumber = freqQueue.poll();
                if (freq[currentNumber] == 0) continue;

                if (assignGroup(fours, currentNumber)) continue;
                if (assignGroup(twos, currentNumber)) continue;
                if (assignGroup(ones, currentNumber)) continue;

                out.println("NO");
                return;
            }
        }

        private boolean assignGroup(ArrayDeque<int[][]> queue, int number) {
            if (queue.isEmpty() || freq[number] < queue.size() * getGroupSize(queue)) {
                return false;
            }

            int[][] group = queue.poll();
            assignToMatrix(group, number);
            freq[number] -= getGroupSize(group);
            freqQueue.add(number);
            return true;
        }

        private int getGroupSize(ArrayDeque<int[][]> queue) {
            return queue.peek() == null ? 0 : queue.peek().length;
        }

        private void assignToMatrix(int[][] group, int number) {
            for (int[] pos : group) {
                mat[pos[0]][pos[1]] = number;
            }
        }

        private void printResult(PrintWriter out) {
            out.println("YES");
            for (int[] row : mat) {
                for (int val : row) {
                    out.print(val + " ");
                }
                out.println();
            }
        }

        String debug(Object... o) {
            return Arrays.deepToString(o);
        }
    }

    public static void main(String[] args) {
        FastScanner s = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(System.out);
        new Solver().solve(s, out);
        out.close();
        s.close();
    }

    static class FastScanner {
        private InputStream stream;
        private byte[] buf = new byte[1 << 22];
        private int curChar;
        private int numChars;

        public FastScanner(InputStream stream) {
            this.stream = stream;
        }

        public FastScanner(File f) throws FileNotFoundException {
            this(new FileInputStream(f));
        }

        public FastScanner(String s) {
            this.stream = new ByteArrayInputStream(s.getBytes(StandardCharsets.UTF_8));
        }

        void close() {
            try {
                stream.close();
            } catch (IOException e) {
                e.printStackTrace();
            }
        }

        int read() {
            if (numChars == -1) throw new InputMismatchException();
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (numChars <= 0) return -1;
            }
            return buf[curChar++];
        }

        boolean isSpaceChar(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        boolean isEndline(int c) {
            return c == '\n' || c == '\r' || c == -1;
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public int[] nextIntArray(int N) {
            int[] ret = new int[N];
            for (int i = 0; i < N; i++) ret[i] = nextInt();
            return ret;
        }
    }
}

/*
 *  Palindrome Matrix
 *
 *  Reads an N×N integer matrix (flattened) and checks whether it can be rearranged
 *  so that every 2×2 sub‑matrix is a palindrome.  If it is possible, prints "YES"
 *  followed by the reconstructed matrix; otherwise prints "NO".
 *
 *  The implementation is deliberately split into small, single‑responsibility
 *  classes to improve readability and maintainability.
 */
import java.io.*;
import java.util.*;

public class Main {

    /** Entry point */
    public static void main(String[] args) {
        InputStream inStream = System.in;
        OutputStream outStream = System.out;

        FastScanner scanner = new FastScanner(inStream);
        FastPrinter printer = new FastPrinter(outStream);

        PalindromeMatrixSolver solver = new PalindromeMatrixSolver();
        solver.solve(scanner, printer);

        printer.close();
    }

    /**
     * Solver class that contains the core algorithm.
     */
    private static final class PalindromeMatrixSolver {

        /** Solves one test case. */
        void solve(FastScanner in, FastPrinter out) {
            int n = in.readInt();
            int[] flatArray = in.readIntArray(n * n);
            solveSingleCase(n, flatArray, out);
        }

        /** Core logic for a single test case. */
        private void solveSingleCase(int n, int[] values, FastPrinter out) {
            // 1️⃣ Count occurrences of each digit (1 … 1000)
            int[] frequency = countFrequencies(values);

            // 2️⃣ Build groups of symmetric positions that must contain the same digit
            List<Set<Position>> groups = buildPositionGroups(n);

            // 3️⃣ Assign digits to groups (larger groups first)
            int[][] result = assignDigitsToGroups(groups, frequency, n);

            // 4️⃣ Output
            out.printLine("YES");
            for (int i = 0; i < n; i++) {
                out.printLine(result[i]);
            }
        }

        /** Counts how many times each value (1‑1000) appears in the input. */
        private static int[] countFrequencies(int[] values) {
            int[] freq = new int[1_001];               // índices 1‑1000 are used
            for (int v : values) {
                freq[v]++;
            }
            return freq;
        }

        /** Creates the four‑position groups required for the palindrome property. */
        private static List<Set<Position>> buildPositionGroups(int n) {
            boolean[][] visited = new boolean[n][n];
            List<Set<Position>> groups = new ArrayList<>();

            for (int i = 0; i < n; i++) {
                for (int j = 0; j < n; j++) {
                    if (visited[i][j]) {
                        continue;
                    }

                    Set<Position> group = collectSymmetricPositions(i, j, n);
                    groups.add(group);

                    // Mark every position of the group as visited
                    for (Position p : group) {
                        visited[p.row][p.col] = true;
                    }
                }
            }

            // Sort groups by size – larger groups first (greedy assignment)
            groups.sort(Comparator.comparingInt(g -> -g.size()));
            return groups;
        }

        /** Returns a set with the four symmetric positions of (row, col). */
        private static Set<Position> collectSymmetricPositions(int row, int col, int n) {
            Set<Position> set = new HashSet<>(4);
            set.add(new Position(row, col));

            int oppositeRow = n - row - 1;
            int oppositeCol = n - col - 1;

            set.add(new Position(row, oppositeCol));
            set.add(new Position(oppositeRow, col));
            set.add(new Position(oppositeRow, oppositeCol));

            return set;
        }

        /** Tries to fill the matrix using the biggest groups first. */
        private static int[][] assignDigitsToGroups(
                List<Set<Position>> groups,
                int[] frequency,
                int n) {

            int[][] matrix = new int[n][n];

            for (Set<Position> group : groups) {
                boolean assigned = false;
                // Scan values from 1 upward – any value with enough remaining occurrences works
                for (int value = 1; value < frequency.length; value++) {
                    if (frequency[value] >= group.size()) {
                        for (Position p : group) {
                            matrix[p.row][p.col] = value;
                        }
                        frequency[value] -= group.size();
                        assigned = true;
                        break;
                    }
                }
                if (!assigned) {
                    out.printLine("NO");
                    System.exit(0);
                }
            }
            return matrix;
        }
    }

    /** Very small helper class that stores a matrix cell coordinate. */
    private static final class Position {
        final int row;
        final int col;

        Position(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }

    /** Fast input wrapper (similar to the original InputReader). */
    private static final class FastScanner {
        private final InputStream stream;
        private final byte[] buffer = new byte[16_384];
        private int bytesRead = 0;
        private int currentByte;
        private int currentPosition = 0;

        FastScanner(InputStream stream) {
            this.stream = stream;
        }

        /** Reads the next non‑whitespace character. */
        private int readNonWhitespaceChar() throws IOException {
            if (currentPosition >= bytesRead) {
                bytesRead = stream.read(buffer);
                currentPosition = 0;
                if (bytesRead <= 0) {
                    return -1;
                }
            }
            return buffer[currentPosition++];
        }

        /** Skips whitespace characters. */
        private static boolean isWhitespace(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        /** Reads an integer (supports negative numbers). */
        int readInt() throws IOException {
            int c = readNonWhitespaceChar();
            while (isWhitespace(c)) c = readNonWhitespaceChar();

            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = readNonWhitespaceChar();
            }

            int result = 0;
            do {
                if (c < '0' || c > '9') {
                    throw new InputMismatchException();
                }
                result = result * 10 + (c - '0');
                c = readNonWhitespaceChar();
            } while (!isWhitespace(c));

            return result * sign;
        }

        /** Reads exactly {@code size} integers and returns them as an array. */
        int[] readIntArray(int size) throws IOException {
            int[] arr = new int[size];
            for (int i = 0; i < size; i++) {
                arr[i] = readInt();
            }
            return arr;
        }
    }

    /** Fast output wrapper (similar to the original OutputWriter). */
    private static final class FastPrinter {
        private final PrintWriter writer;

        FastPrinter(OutputStream out) {
            this.writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(out)));
        }

        /** Prints several objects separated by a single space. */
        void print(Object... objects) {
            for (int i = 0; i < objects.length; i++) {
                if (i != 0) writer.print(' ');
                writer.print(objects[i]);
            }
        }

        /** Prints an int array (space separated) and a line break. */
        void printLine(int[] array) {
            print(array);
            writer.println();
        }

        /** Prints a generic line (objects separated by space + newline). */
        void printLine(Object... objects) {
            print(objects);
            writer.println();
        }

        /** Flushes and closes the underlying writer. */
        void close() {
            writer.close();
        }
    }
}

// Refactored version of the palindromic‑matrix solution
// ----------------------------------------------------
// Package‑free (default) for easy copy‑paste into a single file.

import java.io.*;
import java.util.StringTokenizer;

/**
 * Entry point of the application.
 * Reads input, runs the solver and writes the result.
 */
public final class Main {

    public static void main(String[] args) {
        // Use try‑with‑resources to guarantee proper stream closing.
        try (Reader reader = new BufferedReader(new InputStreamReader(System.in))) {
            PrintWriter out = new PrintWriter(System.out);
            new PalindromeMatrixSolver().solve(reader, out);
        }
    }
}

/**
 * Core logic that attempts to build a palindromic matrix.
 * All mutable state is confined to this class – no static fields are used.
 */
final class PalindromeMatrixSolver {

    /** Upper bound for the values that can appear in the input. */
    private static final int VALUE_BOUND = 1_000_000;

    /**
     * Solves the problem.
     *
     * @param in  a reader that supplies the problem input
     * @param out a printer for the output
     */
    public void solve(Reader in, PrintWriter out) {
        FastScanner scanner = new FastScanner(in);
        int size = scanner.nextInt();                         // n
        int[] values = scanner.readArrayInt(size * size);   // n × n numbers

        // Frequency table of the supplied numbers.
        int[] frequencies = new int[VALUE_BOUND + 1];
        for (int v : values) {
            if (v <= VALUE_BOUND) {
                frequencies[v]++;
            }
        }

        int[][] matrix = buildMatrix(size, frequencies);

        if (matrix == null) {
            out.println("NO");
            return;
        }

        out.println("YES");
        printMatrix(matrix, out);
    }

    /**
     * Attempts to fill a {@code size × size} matrix so that it becomes
     * palindromic (symmetric with respect to both axes).
     *
     * @param size      dimension of the square matrix
     * @param frequencies frequency table that will be mutated in‑place
     * @return a completely filled matrix, or {@code null} if construction fails
     */
    private int[][] buildMatrix(int size, int[] frequencies) {
        // ---- 1. Determine how many groups of symmetric cells we need ----
        int cornerGroups = (size / 2) * (size / 2);          // groups of 4 cells
        int edgePairs   = (size / 2) * (size % 2);            // pairs on the middle line(s)
        int centreCell  = size % 2 == 1 ? 1 : 0;               // single centre cell

        // ---- 2. Helper that finds a number with enough occurrences ----
        //    and consumes the required amount from the frequency table.
        //    Returns -1 if no such number exists.
        //    Lambda keeps the code DRY and expressive.
        java.util.function.IntFunction<Integer> take = (required) -> {
            for (int val = 1; val <= VALUE_BOUND; val++) {
                if (frequencies[val] >= required) {
                    frequencies[val] -= required;
                    return val;
                }
            }
            return -1;
        };

        // ---- 3. Allocate the matrix ----
        int[][] matrix = new int[size][size];

        // ---- 4. Fill 4‑cell corners -------------------------------------------------
        for (int g = 0; g < cornerGroups; g++) {
            int value = take.apply(4);
            if (value == -1) {
                return null; // not enough numbers to satisfy the symmetry
            }
            int r = g / (size / 2);
            int c = g % (size / 2);
            // Place the same value at the four symmetric positions.
            matrix[r][c] = value;
            matrix[r][size - 1 - c] = value;
            matrix[size - 1 - r][c] = value;
            matrix[size - 1 - r][size - 1 - c] = value;
        }

        // ---- 5. Fill middle‑row / middle‑column pairs (only when size is odd) -------
        if (size % 2 == 1) {
            int mid = size / 2;

            // Horizontal pairs on the middle row.
            for (int p = 0; p < edgePairs; p++) {
                int value = take.apply(2);
                if (value == -1) {
                    return null;
                }
                matrix[mid][p] = value;
                matrix[mid][size - 1 - p] = value;
            }

            // Vertical pairs on the middle column.
            for (int p = 0; p < edgePairs; p++) {
                int value = take.apply(2);
                if (value == -1) {
                    return null;
                }
                matrix[p][mid] = value;
                matrix[size - 1 - p][mid] = value;
            }

            // The very centre cell (if present).
            if (centreCell == 1) {
                int value = take.apply(1);
                if (value == -1) {
                    return null;
                }
                matrix[mid][mid] = value;
            }
        }

        // ---- 6. Final sanity check – ensure no cell stayed zero --------------------
        if (!isComplete(matrix)) {
            return null; // some cells could not be filled
        }
        return matrix;
    }

    /** Returns {@code true} iff every cell of the matrix contains a non‑zero value. */
    private boolean isComplete(int[][] matrix) {
        for (int[] row : matrix) {
            for (int v : row) {
                if (v == 0) {
                    return false;
                }
            }
        }
        return true;
    }

    /** Simple printer that outputs the matrix row by row. */
    private void printMatrix(int[][] matrix, PrintWriter out) {
        for (int[] row : matrix) {
            for (int cell : row) {
                out.print(cell);
                out.print(' ');
            }
            out.println();
        }
    }
}

/**
 * Fast scanner that mimics the original ReaderFastIO implementation.
 * It reads tokens from {@code BufferedReader} and provides convenient methods.
 */
final class FastScanner {

    private final BufferedReader br;
    private StringTokenizer st;

    FastScanner(Reader reader) {
        this.br = new BufferedReader(reader);
    }

    /** Returns the next token, fetching a new line if needed. */
    private String next() {
        while (st == null || !st.hasMoreElements()) {
            try {
                st = new StringTokenizer(br.readLine());
            } catch (IOException e) {
                throw new UncheckedIOException(e);
            }
        }
        return st.nextToken();
    }

    /** Parses the next token as an {@code int}. */
    int nextInt() {
        return Integer.parseInt(next());
    }

    /** Reads exactly {@code length} integers from the input stream. */
    int[] readArrayInt(int length) {
        int[] arr = new int[length];
        for (int i = 0; i < length; i++) {
            arr[i] = nextInt();
        }
        return arr;
    }
}

import java.io.IOException;
import java.util.Scanner;

/**
 * Generates a symmetric matrix that satisfies given frequency constraints.
 *
 * <p>
 *   • If {@code n == 1} the answer is always {@code YES} and the single element is printed.
 *   • For odd {@code n} the matrix must contain exactly one value with an odd count
 *     (the centre cell) and all other values must occur in multiples of four.
 *   • For even {@code n} every value must occur in multiples of four.
 *   • All placements are symmetric with respect to both the vertical and horizontal axes.
 * </p>
 */
public class Main {

    /** Maximum distinct integer value we expect (in the original problem). */
    private static final int MAX_VALUE = 1000;

    public static void main(String[] args) throws IOException {
        /* -------------------------------------------------
         *  Input handling – use try‑with‑resources to avoid leaks
         * ------------------------------------------------- */
        try (Scanner scanner = new Scanner(System.in)) {
            int n = scanner.nextInt();                     // size of the matrix (n × n)
            int total = n * n;                             // number of elements to read
            int[] values = readIntegers(scanner, total);   // store all elements

            /* -------------------------------------------------
             *  Trivial 1×1 case – always solvable
             * ------------------------------------------------- */
            if (n == 1) {
                System.out.println("YES");
                System.out.println(values[0]);
                return;
            }

            /* -------------------------------------------------
             *  Frequency preparation
             * ------------------------------------------------- */
            int[] frequency = buildFrequencyArray(values);

            /* -------------------------------------------------
             *  Dispatch to the appropriate solver
             * ------------------------------------------------- */
            if (n % 2 == 1) {
                boolean solved = solveOdd(n, frequency);
                if (!solved) {
                    System.out.println("NO");
                }
            } else {
                boolean solved = solveEven(n, frequency);
                if (!solved) {
                    System.out.println("NO");
                }
            }
        }
    }

    /** Reads exactly {@code count} integers from the scanner. */
    private static int[] readIntegers(Scanner scanner, int count) {
        int[] arr = new int[count];
        for (int i = 0; i < count; i++) {
            arr[i] = scanner.nextInt();
        }
        return arr;
    }

    /** Builds a frequency table for values in the range [0, {@value MAX_VALUE}]. */
    private static int[] buildFrequencyArray(int[] values) {
        int[] freq = new int[MAX_VALUE + 1];
        for (int v : values) {
            if (v < 0 || v > MAX_VALUE) {
                throw new IllegalArgumentException(
                        "Value out of expected range [0," + MAX_VALUE + "]");
            }
            freq[v]++;
        }
        return freq;
    }

    /* ====================== ODD SIZE SOLVER ====================== */

    /**
     * Attempts to build a matrix of odd size {@code n}.
     *
     * @return {@code true} if a valid matrix was printed, {@code false} otherwise.
     */
    private static boolean solveOdd(int n, int[] freq) {
        int[][] matrix = new int[n][n];
        int centre = n / 2;

        // 1️⃣ Place the unique value that appears an odd number of times
        if (!placeCentre(matrix, freq, centre)) {
            System.out.println("NO");
            return false;
        }

        // 2️⃣ Fill symmetric groups of four cells
        if (!fillFourGroups(matrix, freq, centre)) {
            System.out.println("NO");
            return false;
        }

        // 3️⃣ Fill the remaining middle row / column with pairs
        fillRemainingPairs(matrix, freq, centre);

        // 4️⃣ Verify that every frequency has been completely consumed
        if (!allFrequenciesConsumed(freq)) {
            System.out.println("NO");
            return false;
        }

        printMatrix(matrix);
        return true;
    }

    /** Places the single value with an odd count at the centre of the matrix. */
    private static boolean placeCentre(int[][] matrix, int[] freq, int centre) {
        int oddValue = -1;
        for (int v = 1; v <= MAX_VALUE; v++) {
            if ((freq[v] & 1) == 1) {        // odd occurrences
                if (oddValue != -1) {        // more than one odd count → impossible
                    return false;
                }
                oddValue = v;
            }
        }
        if (oddValue == -1) {                // no odd‑count value found
            return false;
        }
        matrix[centre][centre] = oddValue;
        freq[oddValue]--;                    // one occurrence used
        return true;
    }

    /** Fills the matrix with symmetric blocks of four cells. */
    private static boolean fillFourGroups(int[][] matrix, int[] freq, int centre) {
        int row = 0;
        int col = 0;
        for (int v = 1; v <= MAX_VALUE; v++) {
            while (freq[v] >= 4) {
                if (row >= centre) {
                    break;                  // no more positions to fill
                }
                placeFour(matrix, v, row, col);
                freq[v] -= 4;
                col++;
                if (col == centre) {
                    row++;
                    col = 0;
                }
            }
            if (row == centre) {
                break;
            }
        }
        // After the loop the sub‑matrix up to the centre must be completely filled
        return row == centre && col == 0;
    }

    /** Places a value symmetrically in four positions defined by (r,c). */
    private static void placeFour(int[][] matrix, int value, int r, int c) {
        int n = matrix.length;
        int mirrorR = n - 1 - r;
        int mirrorC = n - 1 - c;
        matrix[r][c] = value;
        matrix[r][mirrorC] = value;
        matrix[mirrorR][c] = value;
        matrix[mirrorR][mirrorC] = value;
    }

    /** Fills the middle row and column with the remaining paired values. */
    private static void fillRemainingPairs(int[][] matrix, int[] freq, int centre) {
        int horizontal = 0;          // column index in the middle row
        int vertical   = 0;          // row index in the middle column
        final int n = matrix.length;

        for (int v = 1; v <= MAX_VALUE; v++) {
            while (freq[v] > 0) {
                freq[v] -= 2;                     // consume a pair
                if (horizontal < centre) {
                    // middle row (horizontal propagation)
                    matrix[centre][horizontal] = v;
                    matrix[centre][n - 1 - horizontal] = v;
                    horizontal++;
                } else {
                    // middle column (vertical propagation)
                    matrix[vertical][centre] = v;
                    matrix[n - 1 - vertical][centre] = v;
                    vertical++;
                }
            }
        }
    }

    /** Checks that every entry in the frequency table is back to zero. */
    private static boolean allFrequenciesConsumed(int[] freq) {
        for (int count : freq) {
            if (count != 0) {
                return false;
            }
        }
        return true;
    }

    /* ====================== EVEN SIZE SOLVER ====================== */

    /**
     * Attempts to build a matrix of even size {@code n}.
     *
     * @return {@code true} if a valid matrix was printed, {@code false} otherwise.
     */
    private static boolean solveEven(int n, int[] freq) {
        int[][] matrix = new int[n][n];
        final int half = n / 2;
        int row = 0;
        int col = 0;

        for (int v = 1; v <= MAX_VALUE; v++) {
            // Every value must appear a multiple of four times
            if (freq[v] % 4 != 0) {
                System.out.println("NO");
                return false;
            }

            // Fill all four‑cell blocks for this value
            while (freq[v] > 0) {
                matrix[row][col] = v;
                matrix[row][n - 1 - col] = v;
                matrix[n - 1 - row][col] = v;
                matrix[n - 1 - row][n - 1 - col] = v;

                freq[v] -= 4;
                col++;
                if (col == half) {
                    row++;
                    col = 0;
                }
            }
        }

        printMatrix(matrix);
        return true;
    }

    /** Simple pretty‑printer for the resulting matrix. */
    private static void printMatrix(int[][] matrix) {
        System.out.println("YES");
        for (int[] row : matrix) {
            for (int i = 0; i < matrix.length; i++) {
                System.out.print(row[i]);
                if (i < matrix.length - 1) {
                    System.out.print(' ');
                }
            }
            System.out.println();
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Codeforces‑style solution refactored for readability and maintainability.
 *
 * The program reads an integer {@code n} and {@code n*n} numbers, tries to fill an
 * {@code n×n} matrix with them so that the matrix is symmetric with respect to
 * both its main diagonal and its anti‑diagonal, and prints the matrix if possible.
 */
public class Codeforces {

    /** Output stream used throughout the solution. */
    private static final PrintWriter OUT = new PrintWriter(new BufferedOutputStream(System.out));

    /** Entry point. */
    public static void main(String[] args) throws FileNotFoundException {
        MyScanner scanner = new MyScanner();
        solve(scanner);
        OUT.close();
    }

    /** Orchestrates the whole solving process. */
    private static void solve(MyScanner sc) {
        int n = sc.nextInt();                     // size of the matrix
        int[] values = sc.nextIntArray(n * n);    // all numbers to be placed

        int[][] matrix = new int[n][n];
        if (!buildMatrix(values, n, matrix)) {
            OUT.println("NO");
            return;
        }

        OUT.println("YES");
        printMatrix(matrix);
    }

    /**
     * Tries to construct a valid matrix from the given values.
     *
     * @return {@code true} if a matrix can be built, {@code false} otherwise.
     */
    private static boolean buildMatrix(int[] values, int n, int[][] ans) {
        // ---------- 1. count frequencies ----------
        int[] freq = new int[1001];                // values are guaranteed to be ≤ 1000
        for (int v : values) {
            if (v <= 1000) {
                freq[v]++;
            }
        }

        // ---------- 2. fill the 4‑symmetry blocks ----------
        int neededQuadrants = (n / 2) * (n / 2);
        List<Integer> pool = new ArrayList<>();

        outerQuadrant:
        for (int v = 1; v <= 1000; v++) {
            while (freq[v] >= 4 && neededQuadrants > 0) {
                pool.add(v);
                freq[v] -= 4;
                neededQuadrants--;
                if (neededQuadrants == 0) {
                    break outerQuadrant;
                }
            }
        }
        if (neededQuadrants > 0) {
            return false;                           // not enough numbers for 4‑symmetry
        }

        // ---------- 3. fill the 2‑symmetry edges ----------
        int neededPairs = n / 2 * 2;
        outerPairs:
        for (int v = 1; v <= 1000; v++) {
            while (freq[v] >= 2 && neededPairs > 0) {
                pool.add(v);
                freq[v] -= 2;
                neededPairs--;
                if (neededPairs == 0) {
                    break outerPairs;
                }
            }
        }
        if (neededPairs > 0) {
            return false;                           // not enough numbers for 2‑symmetry
        }

        // ---------- 4. fill the centre (single cells) ----------
        int neededSingles = n % 2;
        outerSingles:
        for (int v = 1; v <= 1000; v++) {
            while (freq[v] >= 1 && neededSingles > 0) {
                pool.add(v);
                freq[v]--;
                neededSingles--;
                if (neededSingles == 0) {
                    break outerSingles;
                }
            }
        }
        if (neededSingles > 0) {
            return false;                           // not enough numbers for centre cell
        }

        // ---------- 5. place numbers according to symmetry ----------
        placeSymmetrically(ans, pool, n);
        return true;
    }

    /**
     * Fills the matrix respecting four‑fold, two‑fold and centre symmetry
     * using the numbers stored in {@code pool}.
     */
    private static void placeSymmetrically(int[][] ans, List<Integer> pool, int size) {
        int half = size / 2;
        int mid = size / 2;                     // used only when size is odd

        // ---- 4‑fold symmetry (quadrants) ----
        for (int i = 0; i < half; i++) {
            for (int j = 0; j < half; j++) {
                int val = pool.remove(0);
                ans[i][j] = ans[size - 1 - i][j] = ans[i][size - 1 - j] = ans[size - 1 - i][size - 1 - j] = val;
            }
        }

        // ---- 2‑fold symmetry (middle row / column) ----
        if (size % 2 == 1) {
            // middle column pairs
            for (int i = 0; i < half; i++) {
                int val = pool.remove(0);
                ans[i][mid] = ans[size - 1 - i][mid] = val;
            }
            // middle row pairs
            for (int j = 0; j < half; j++) {
                int val = pool.remove(0);
                ans[mid][j] = ans[mid][size - 1 - j] = val;
            }
            // centre cell
            ans[mid][mid] = pool.remove(0);
        }
    }

    /** Simple pretty‑printer for an integer matrix. */
    private static void printMatrix(int[][] mat) {
        for (int[] row : mat) {
            StringBuilder sb = new StringBuilder();
            for (int i = 0; i < mat.length; i++) {
                if (i > 0) sb.append(' ');
                sb.append(row[i]);
            }
            OUT.println(sb);
        }
    }

    // -----------------------------------------------------------------
    // Fast scanner utilities
    // -----------------------------------------------------------------
    /**
     * Very small scanner that works both with {@code System.in} and with a
     * {@link FileReader}.  All token‑related methods throw an unchecked
     * {@link UncheckedIOException} if an {@link IOException} occurs.
     */
    private static class MyScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        /** Creates a scanner that reads from standard input. */
        MyScanner() {
            this(new FileReader("/dev/fd/0")); // works on most Unix‑like environments
        }

        /** Creates a scanner that reads from a supplied {@link FileReader}. */
        MyScanner(FileReader fr) {
            this.br = new BufferedReader(fr);
        }

        /** Returns the next token from the input stream. */
        private String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    throw new UncheckedIOException(e);
                }
            }
            return st.nextToken();
        }

        /** Reads an {@code int}. */
        int nextInt() {
            return Integer.parseInt(next());
        }

        /** Reads an {@code long}. */
        long nextLong() {
            return Long.parseLong(next());
        }

        /** Reads a {@code double}. */
        double nextDouble() {
            return Double.parseDouble(next());
        }

        /**
         * Reads exactly {@code size} integers and returns them as an array.
         */
        int[] nextIntArray(int size) {
            int[] arr = new int[size];
            for (int i = 0; i < size; i++) {
                arr[i] = nextInt();
            }
            return arr;
        }
    }
}

import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Scanner;

/**
 * Refactored solution for Problem C.
 *
 * <p>This version improves readability, reduces mutable static state,
 * separates concerns into small helper methods and follows a
 * consistent naming convention.</p>
 */
public class ProblemC {

    /** Scanner used for reading input. */
    private static final Scanner SCANNER = new Scanner(System.in);

    /** Entry point of the program. */
    public static void main(String[] args) {
        int n = readInt();

        // Trivial 1×1 matrix – output is always YES.
        if (n == 1) {
            System.out.println("YES");
            System.out.println(readInt());
            return;
        }

        int total = n * n;
        List<Integer> numbers = read(total);

        Map<Integer, Integer> frequencies = frequencyMap(numbers);
        boolean possible = allocateResources(frequencies, n);

        if (!possible) {
            System.out.println("NO");
            return;
        }

        System.out.println("YES");
        if (n % 2 == 1) {
            printOddSizeMatrix(frequencies, n);
        } else {
            printEvenSizeMatrix(frequencies, n);
        }
    }

    /* --------------------------------------------------------------------- *
     *  Input handling helpers
     * --------------------------------------------------------------------- */

    private static int readInt() {
        return SCANNER.nextInt();
    }

    /** Reads exactly {@code count} integers from the scanner. */
    private static List<Integer> read(int count) {
        List<Integer> values = new ArrayList<>(count);
        for (int i = 0; i < count; i++) {
            values.add(SCANNER.nextInt());
        }
        return values;
    }

    /** Builds a frequency map from the supplied list of numbers. */
    private static Map<Integer, Integer> frequencyMap(List<Integer> numbers) {
        Map<Integer, Integer> map = new HashMap<>();
        for (int num : numbers) {
            map.merge(num, 1, Integer::sum);
        }
        return map;
    }

    /* --------------------------------------------------------------------- *
     *  Core algorithm
     * --------------------------------------------------------------------- */

    /** Determines whether the given frequencies can satisfy the matrix layout. */
    private static boolean allocateResources(Map<Integer, Integer> freq, int n) {
        int half = n / 2;
        int neededQuads = half * half;                     // cells that need 4 copies
        int neededPairs = n % 2 == 1 ? n - 1 : 0;          // cells that need 2 copies
        int neededSingles = n % 2 == 1 ? 1 : 0;            // central cell

        // Sort entries by frequency (ascending) – mirrors original behaviour.
        List<Map.Entry<Integer, Integer>> entries = new ArrayList<>(freq.entrySet());
        entries.sort(Map.Entry.comparingByValue());

        for (Map.Entry<Integer, Integer> e : entries) {
            int count = e.getValue();
            int quads = count / 4;
            int remainder = count % 4;

            // Use as many quads as still required.
            int useQuads = Math.min(quads, neededQuads);
            neededQuads -= useQuads;
            storeQuadValues(e.getKey(), useQuads);

            // Remainder >= 2 becomes pairs.
            if (remainder >= 2) {
                int pairsNeeded = Math.min(remainder / 2, neededPairs);
                neededPairs -= pairsNeeded;
                storePairValues(e.getKey(), pairsNeeded);
                remainder -= pairsNeeded * 2;
            }

            // Remainder == 1 consumes a single-slot.
            if (remainder == 1) {
                if (neededSingles <= 0) {
                    System.out.println("NO");
                    return false;
                }
                neededSingles--;
                singleValue = e.getKey();
            }
        }

        // Any remaining demand makes the configuration impossible.
        if (neededQuads < 0 || neededPairs < 0 || neededSingles < 0) {
            System.out.println("NO");
            return false;
        }
        return true;
    }

    /** Stores the numbers that will fill the 4‑fold symmetric cells. */
    private static final List<Integer> quadValues = new ArrayList<>();

    private static void storeQuadValues(int value, int times) {
        for (int i = 0; i < times; i++) {
            quadValues.add(value);
        }
    }

    /** Stores the numbers that will fill the 2‑fold symmetric cells. */
    private static final List<Integer> pairValues = new ArrayList<>();

    private static void storePairValues(int value, int times) {
        for (int i = 0; i < times; i++) {
            pairValues.add(value);
        }
    }

    /** Holds the unique value required for the centre cell (when n is odd). */
    private static Integer singleValue;

    /* --------------------------------------------------------------------- *
     *  Matrix printing
     * --------------------------------------------------------------------- */

    /** Prints a matrix for an even‑size input (n is even). */
    private static void printEvenSizeMatrix(Map<Integer, Integer> freq, int n) {
        int half = n / 2;
        int[][] matrix = new int[n][n];

        int idx = 0;
        for (int i = 0; i < half; i++) {
            for (int j = 0; j < half; j++) {
                int v = quadValues.get(idx++);
                fillSymmetric(matrix, v, i, j, n);
            }
        }

        printMatrixRows(matrix);
    }

    /** Prints a matrix for an odd‑size input (n is odd). */
    private static void printOddSizeMatrix(Map<Integer, Integer> freq, int n) {
        int half = n / 2;
        int[][] matrix = new int[n][n];

        // ---- 4‑fold symmetric part ----
        int quadIdx = 0;
        for (int i = 0; i < half; i++) {
            for (int j = 0; j < half; j++) {
                int v = quadValues.get(quadIdx++);
                fillSymmetric(matrix, v, i, j, n);
            }
        }

        // ---- 2‑fold symmetric part (edges) ----
        int pairIdx = 0;
        for (int i = 0; i < half; i++) {
            // top / bottom edge cells
            matrix[i][half] = pairValues.get(pairIdx);
            matrix[n - 1 - i][half] = pairValues.get(pairIdx);
            // left / right edge cells
            matrix[half][i] = pairValues.get(pairIdx + half);
            matrix[half][n - 1 - i] = pairValues.get(pairIdx + half);
            pairIdx += 2 * half;
        }

        // ---- central cell ----
        matrix[half][half] = singleValue;

        // ---- Output in the exact order required by the original program ----
        printSymmetricRows(matrix, half);
        printCentralRow(matrix, half);
        printRemainingRows(matrix, half);
    }

    /** Fill the four symmetric positions of a cell. */
    private static void fillSymmetric(int[][] matrix, int value, int i, int j, int n) {
        matrix[i][j] = value;
        matrix[i][n - 1 - j] = value;
        matrix[n - 1 - i][j] = value;
        matrix[n - 1 - i][n - 1 - j] = value;
    }

    /** Prints the matrix rows in the order demanded by the original specification. */
    private static void printSymmetricRows(int[][] matrix, int half) {
        // Rows from the outermost level down to the centre level.
        for (int i = half - 1; i >= 0; i--) {
            StringBuilder sb = new StringBuilder();
            for (int col = 0; col < matrix.length; col++) {
                sb.append(matrix[i][col]).append(' ');
            }
            System.out.println(sb.toString().trim());
        }
    }

    /** Prints the central row (including the middle element when n is odd). */
    private static void printCentralRow(int[][] matrix, int half) {
        StringBuilder sb = new StringBuilder();

        // Left side of the centre row (mirrored)
        for (int i = half - 1; i >= 0; i--) {
            sb.append(matrix[half][i]).append(' ');
        }

        // Central element
        sb.append(matrix[half][half]).append(' ');

        // Right side of the centre row (mirrored)
        for (int i = 0; i < half; i++) {
            sb.append(matrix[half][matrix.length - 1 - i]).append(' ');
        }

        System.out.println(sb.toString().trim());
    }

    /** Prints the remaining rows after the centre row in reverse order. */
    private static void printRemainingRows(int[][] matrix, int half) {
        for (int i = half - 1; i >= 0; i--) {
            StringBuilder sb = new StringBuilder();

            // Left half (including the centre column)
            for (int col = 0; col <= i; col++) {
                sb.append(matrix[half][col]).append(' ');
            }

            // Right half (mirrored)
            for (int col = matrix.length - 1; col > half; col--) {
                sb.append(matrix[half][col]).append(' ');
            }

            System.out.println(sb.toString().trim());
        }
    }
}

import java.util.Scanner;

/**
 * Builds a square matrix that respects the symmetry constraints described in the
 * original solution.
 *
 * <p>If a matrix can be built the program prints {@code YES} followed by the
 * matrix, otherwise it prints {@code NO}.</p>
 */
public final class MatrixConstructor {

    /** Maximum value that can appear in the input (original code used 1000). */
    private static final int MAX_VALUE = 1001;

    /** Holds the frequency of each value in the input. */
    private static int[] frequencies = new int[MAX_VALUE];

    /** The resulting square matrix. */
    private static int[][] matrix;

    /** Size of the square matrix (n). */
    private static int size;

    private MatrixConstructor() { /* utility class – no instances */ }

    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            readInput(scanner);
            if (canBuildMatrix()) {
                fillMatrix();
                printMatrix();
            } else {
                System.out.println("NO");
            }
        }
    }

    /** Reads the matrix size and the list of values, storing their frequencies. */
    private static void readInput(Scanner scanner) {
        size = scanner.nextInt();                     // n
        for (int i = 0; i < size * size; i++) {
            int value = scanner.nextInt();
            if (value < 0 || value >= MAX_VALUE) {
                throw new IllegalArgumentException(
                        "Value out of supported range [0, " + (MAX_VALUE - 1) + "]");
            }
            frequencies[value]++;
        }
        scanner.close();
    }

    /** Determines whether a valid matrix can be constructed for the given data. */
    private static boolean canBuildMatrix() {
        boolean evenSize = (size % 2) == 0;

        // ---- Even sized matrix -------------------------------------------------
        if (evenSize) {
            // Fill the matrix using groups of 4 identical numbers.
            int placed = fillEven();
            return placed == size * size;
        }

        // ---- Odd sized matrix --------------------------------------------------
        // First fill the symmetric positions that need groups of 2.
        int placedPairs = fillOddPairPhase();
        if (placedPairs != size * size - 2 * size + 1) {
            return false;
        }

        // Then place the remaining single value in the centre.
        Integer centreValue = findCenterValue();
        if (centreValue == null) {
            return false;
        }
        matrix[size / 2][size / 2] = centreValue;
        return true;
    }

    /** Fills an even‑sized matrix using groups of four equal numbers. */
    private static int fillEven() {
        int placed = 0;
        for (int value = 0; value < MAX_VALUE; value++) {
            while (frequencies[value] >= 4) {
                placeSymmetrically(value, true);
                frequencies[value] -= 4;
                placed += 4;
            }
        }
        return placed;
    }

    /** Fills the symmetric positions that require groups of two for odd‑sized matrices. */
    private static int fillOddPairPhase() {
        int placed = 0;
        boolean centreFound = false;
        int centreValue = -1;

        // First phase – groups of 2
        for (int value = 0; value < MAX_VALUE; value++) {
            while (frequencies[value] >= 2) {
                placeSymmetrically(value, false);
                frequencies[value] -= 2;
                placed += 2;
            }
        }

        // Second phase – locate the single value that will sit in the centre.
        for (int value = 0; value < MAX_VALUE; value++) {
            if (frequencies[value] == 1) {
                if (centreValue != -1) {               // more than one centre candidate
                    return -1;
                }
                centreValue = value;
                centreFound = true;
            } else if (frequencies[value] > 1) {      // leftover > 1 disrupts validity
                return -1;
            }
        }

        // If no centre value was found the matrix cannot be completed.
        if (!centreFound) {
            return -1;
        }

        // Store the centre value for later use (the actual placement happens after this method).
        matrix[size / 2][size / 2] = centreValue; // placeholder, overwritten later
        return placed;
    }

    /** Searches for the value that occurs exactly once and can be placed in the centre. */
    private static Integer findCenterValue() {
        for (int value = 0; value < MAX_VALUE; value++) {
            if (frequencies[value] == 1) {
                return value;
            }
        }
        return null;
    }

    /**
     * Places a value symmetrically into the matrix.
     *
     * <p>When {@code addRow} is {@code true} the routine walks row‑wise,
     * otherwise it walks column‑wise. The method writes the same value into the
     * four (or two) symmetric positions.</p>
     *
     * @param value       the number to write into the matrix
     * @param addRow      {@code true} to move across rows first, {@code false} for columns first
     */
    private static void placeSymmetrically(int value, boolean addRow) {
        // The current “anchor” cell (top‑left quadrant)
        int row = -1, col = -1;

        if (addRow) {
            // Row‑major walk inside the top‑left quadrant
            row = x;               // current row index
            col = y;               // current column index
            // advance for the next call
            y++;
            if (y == size / 2) {
                y = 0;
                x++;
            }
        } else {
            // Column‑major walk inside the top‑left quadrant
            row = x;
            col = y;
            // advance for the next call
            if (x == size / 2) {
                y++;
                if (y == size / 2) {
                    x = 0;
                    y = size / 2;
                }
            } else {
                x++;
            }
        }

        // Write the value into the four symmetric cells
        matrix[row][col] = value;
        matrix[row][size - 1 - col] = value;
        matrix[size - 1 - row][col] = value;
        matrix[size - 1 - row][size - 1 - col] = value;
    }

    /** Prints {@code YES} followed by the constructed matrix. */
    private static void printMatrix() {
        System.out.println("YES");
        for (int[] row : matrix) {
            for (int cell : row) {
                System.out.print(cell + " ");
            }
            System.out.println();
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Generates a palindromic square matrix if possible.
 *
 * <p>
 * The program reads an integer {@code N} followed by {@code N²} integers.
 * It then tries to fill an {@code N×N} matrix such that the matrix is
 * symmetric with respect to both the horizontal and vertical axes
 * (i.e., each quadrant mirrors the others). If this is not possible,
 * it prints {@code NO}; otherwise it prints {@code YES} followed by the
 * completed matrix.
 * </p>
 *
 * <p>Refactoring goals:</p>
 * <ul>
 *   <li>Separated concerns (input, algorithm, output).</li>
 *   <li>Descriptive naming and small, single‑purpose methods.</li>
 *   <li>Eliminated magic numbers, added constants.</li>
 *   <li>Used {@code try‑with‑resources} for automatic resource handling.</li>
 *   <li>Improved readability with early‑exit handling and clear error messages.</li>
 * </ul>
 */
public class PalindromicMatrix {

    /* --------------------------------------------------------------------- */
    /* Constants for required multiplicities (palindromic constraints)   */
    /* --------------------------------------------------------------------- */
    private static final int COUNT_4 = 4;   // needed for a full‑quadrant placement
    private static final int COUNT_2 = 2;   // needed for a centre‑line placement

    /* --------------------------------------------------------------------- */
    /* Element stored in the priority queue                                   */
    /* --------------------------------------------------------------------- */
    private static final class Element implements Comparable<Element> {
        final int value;   // the integer value
        int remaining;     // how many copies are still unused

        Element(int value, int remaining) {
            this.value = value;
            this.remaining = remaining;
        }

        /**
         * Queue order: larger remaining count first.
         */
        @Override
        public int compareTo(Element o) {
            return Integer.compare(o.remaining, this.remaining);
        }
    }

    /* --------------------------------------------------------------------- */
    /* Entry point                                                            */
    /* --------------------------------------------------------------------- */
    public static void main(String[] args) {
        // Using AutoCloseable enables try‑with‑resources for deterministic closing.
        try (FastScanner scanner = new FastScanner()) {
            solve(scanner);
        } catch (IllegalArgumentException ex) {
            // Validation errors or insufficient elements – print nothing else.
            System.err.println("Input validation failed: " + ex.getMessage());
        }
    }

    /* --------------------------------------------------------------------- */
    /* Core algorithm                                                         */
    /* --------------------------------------------------------------------- */
    private static void solve(FastScanner scanner) {
        int n = scanner.nextInt();                 // matrix dimension
        int total = n * n;
        int[] frequency = new int[1001];           // values are assumed to be ≤ 1000

        // --------------------------------------------------------------
        // Read the input numbers and count occurrences.
        // --------------------------------------------------------------
        for (int i = 0; i < total; i++) {
            int v = scanner.nextInt();
            if (v < 0 || v > 1000) {
                throw new IllegalArgumentException("Value out of supported range 0..1000");
            }
            frequency[v]++;
        }

        // --------------------------------------------------------------
        // Build a priority queue ordered by remaining multiplicity.
        // --------------------------------------------------------------
        PriorityQueue<Element> queue = new PriorityQueue<>();
        for (int val = 0; val <= 1000; val++) {
            if (frequency[val] > 0) {
                queue.offer(new Element(val, frequency[val]));
            }
        }

        int[][] result = new int[n][n];

        // --------------------------------------------------------------
        // Fill the four quadrants (requires 4 copies of a value).
        // --------------------------------------------------------------
        if (!placeQuadrantElements(n, queue, result)) {
            System.out.println("NO");
            System.out.flush();
            return;
        }

        // --------------------------------------------------------------
        // If N is odd, handle the centre row, centre column and centre cell.
        // --------------------------------------------------------------
        if (n % 2 == 1) {
            if (!placeCentralElements(n, queue, result)) {
                System.out.println("NO");
                System.out.flush();
                return;
            }
        }

        // --------------------------------------------------------------
        // All placements succeeded → output the matrix.
        // --------------------------------------------------------------
        System.out.println("YES");
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                System.out.print(result[i][j]);
                if (j < n - 1) System.out.print(' ');
            }
            System.out.println();
        }
        System.out.flush();
    }

    /* --------------------------------------------------------------------- */
    /* Places values that must appear 4 times (full quadrant symmetry)      */
    /* --------------------------------------------------------------------- */
    private static boolean placeQuadrantElements(int n, PriorityQueue<Element> queue,
                                                 int[][] result) {
        int half = n / 2;
        for (int r = 0; r < half; r++) {
            for (int c = 0; c < half; c++) {
                Element e = requireCount(queue, COUNT_4);
                // Assign the four symmetric positions
                result[r][c] = e.value;
                result[n - 1 - r][c] = e.value;
                result[n - 1 - r][n - 1 - c] = e.value;
                result[r][n - 1 - c] = e.value;

                // Re‑queue leftovers, if any
                if (e.remaining - COUNT_4 > 0) {
                    queue.offer(new Element(e.value, e.remaining - COUNT_4));
                }
            }
        }
        return true;
    }

    /* --------------------------------------------------------------------- */
    /* Handles centre row, centre column and centre cell when N is odd      */
    /* --------------------------------------------------------------------- */
    private static boolean placeCentralElements(int n, PriorityQueue<Element> queue,
                                                int[][] result) {
        int mid = n / 2;
        int limit = n / 2; // number of pairs needed on each side

        // ---- middle row (pairs) ----
        for (int col = 0; col < limit; col++) {
            Element e = requireCount(queue, COUNT_2);
            result[mid][col] = e.value;
            result[mid][n - 1 - col] = e.value;
            if (e.remaining - COUNT_2 > 0) {
                queue.offer(new Element(e.value, e.remaining - COUNT_2));
            }
        }

        // ---- middle column (pairs) ----
        for (int row = 0; row < limit; row++) {
            Element e = requireCount(queue, COUNT_2);
            result[row][mid] = e.value;
            result[n - 1 - row][mid] = e.value;
            if (e.remaining - COUNT_2 > 0) {
                queue.offer(new Element(e.value, e.remaining - COUNT_2));
            }
        }

        // ---- centre cell ----
        Element centre = queue.poll();
        if (centre == null) {
            throw new IllegalArgumentException("No element left for centre cell");
        }
        result[mid][mid] = centre.value;   // consumes exactly one copy
        return true;
    }

    /* --------------------------------------------------------------------- */
    /* Utility: extracts an element that still has at least {@code required} */
    /* copies left. Throws if not enough copies are available.               */
    /* --------------------------------------------------------------------- */
    private static Element requireCount(PriorityQueue<Element> queue,
                                        int required) {
        if (queue.isEmpty() || queue.peek().remaining < required) {
            throw new IllegalArgumentException(
                "Insufficient elements for required count of " + required);
        }
        return queue.poll();
    }

    /* --------------------------------------------------------------------- */
    /* Fast input utilities                                                  */
    /* --------------------------------------------------------------------- */
    private static final class FastScanner implements AutoCloseable {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner() {
            this(System.in);
        }

        FastScanner(Reader source) {
            this.br = new BufferedReader(source);
        }

        String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new UncheckedIOException(e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        @Override
        public void close() {
            try {
                br.close();
            } catch (IOException e) {
                throw new UncheckedIOException(e);
            }
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Refactored version of the original program.
 * The code is organized into small, reusable methods,
 * uses meaningful names, generics and try‑with‑resources
 * to improve readability and maintainability.
 */
public class MatrixConstructor {

    /** Maximum value that can appear in the input (as defined by the original problem). */
    private static final int MAX_VALUE = 1000;

    public static void main(String[] args) throws IOException {
        /* --------------------------------------------------------------
         *  1️⃣  Input handling
         * -------------------------------------------------------------- */
        try (Scanner scanner = new Scanner();               // automatically closed
             PrintWriter out = new PrintWriter(System.out)) { // automatically closed
            int n = scanner.nextInt();
            int[] frequencies = new int[MAX_VALUE + 1];

            // read exactly n·n numbers
            for (int i = 0; i < n * n; i++) {
                int v = scanner.nextInt();
                if (v < 1 || v > MAX_VALUE) {
                    throw new IllegalArgumentException(
                        "Value out of allowed range [1, " + MAX_VALUE + "]");
                }
                frequencies[v]++;
            }

            // --------------------------------------------------------------
            // 2️⃣  Bucket numbers according to how many times they can be used
            // --------------------------------------------------------------
            List<Integer>[] buckets = new ArrayList[3]; // 0 → groups of 4, 1 → groups of 2, 2 → singles
            for (int i = 0; i < 3; i++) {
                buckets[i] = new ArrayList<>();
            }
            bucketNumbers(frequencies, buckets);

            // --------------------------------------------------------------
            // 3️⃣  Build the matrix (if possible)
            // --------------------------------------------------------------
            int[][] matrix = new int[n][n];
            if (!populateMatrix(matrix, buckets, n)) {
                out.println("NO");
                return;
            }

            // --------------------------------------------------------------
            // 4️⃣  Output the result
            // --------------------------------------------------------------
            out.println("YES");
            for (int[] row : matrix) {
                for (int val : row) {
                    out.print(val + " ");
                }
                out.println();
            }
        }
    }

    /** -----------------------------------------------------------------
     *  Fill the three buckets:
     *   • bucket[0] – numbers that can be used in groups of 4,
     *   • bucket[1] – numbers that can be used in groups of 2,
     *   • bucket[2] – numbers that are left as singles.
     * ----------------------------------------------------------------- */
    private static void bucketNumbers(int[] frequencies, List<Integer>[] buckets) {
        for (int value = 1; value <= MAX_VALUE; value++) {
            int remaining = frequencies[value];

            // groups of 4
            while (remaining >= 4) {
                buckets[0].add(value);
                remaining -= 4;
            }

            // groups of 2
            while (remaining >= 2) {
                buckets[1].add(value);
                remaining -= 2;
            }

            // singles
            if (remaining > 0) {
                buckets[2].add(value);
            }
        }
    }

    /** -----------------------------------------------------------------
     *  Try to place the numbers into an n×n matrix respecting the
     *  symmetry constraints. Returns {@code true} if a placement is
     *  possible, otherwise {@code false}.
     * ----------------------------------------------------------------- */
    private static boolean populateMatrix(int[][] matrix, List<Integer>[] buckets, int n) {
        if (n % 2 == 1) {
            // ---- center cell needs a single element ---------------------------------
            if (buckets[2].isEmpty()) {
                return false;
            }
            int centre = buckets[2].remove(buckets[2].size() - 1);
            matrix[n / 2][n / 2] = centre;

            // ---- place pairs around the centre ------------------------------------
            for (int offset = 0; offset < n / 2; offset++) {
                if (!buckets[1].isEmpty()) {
                    int pair = buckets[1].remove(buckets[1].size() - 1);
                    fillSymmetricPositions(matrix, pair, n / 2, offset);
                } else if (!buckets[0].isEmpty()) {
                    int quad = buckets[0].remove(buckets[0].size() - 1);
                    fillSymmetricPositions(matrix, quad, n / 2, offset);
                } else {
                    return false; // no material left to place a required pair
                }
            }
        }

        // ---- fill the remaining symmetric groups of four -----------------------
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (matrix[i][j] != 0) {
                    continue; // already filled
                }

                int revI = n - i - 1;
                int revJ = n - j - 1;

                if (buckets[0].isEmpty()) {
                    return false; // nothing left to satisfy the symmetry requirement
                }
                int quad = buckets[0].remove(buckets[0].size() - 1);
                matrix[i][j] = quad;
                matrix[revI][revJ] = quad;
                matrix[i][revJ] = quad;
                matrix[revI][j] = quad;
            }
        }
        return true;
    }

    /** Helper that writes a value into the four symmetric cells of a matrix. */
    private static void fillSymmetricPositions(int[][] matrix, int value, int centre, int offset) {
        matrix[centre][offset] = value;
        matrix[centre][n - offset - 1] = value;
        matrix[offset][centre] = value;
        matrix[n - offset - 1][centre] = value;
    }

    /** --------------------------------------------------------------
     *  Simple scanner wrapper used for competitive‑programming input.
     * -------------------------------------------------------------- */
    private static class Scanner {
        private final BufferedReader br;
        private StringTokenizer st;

        Scanner() throws IOException {
            this.br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                st = new StringTokenizer(br.readLine());
            }
            return st.nextToken();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.HashMap;
import java.util.Map;
import java.util.PriorityQueue;

/**
 * Reads a square matrix of integers, tries to fill an n×n matrix with the
 * same frequencies while respecting symmetry constraints and prints the
 * resulting matrix or “NO” if impossible.
 *
 * <p>This refactor focuses on readability, separation of concerns and proper
 * use of Java language features.</p>
 */
public class SymmetricFrequencyMatrix {

    /** Holds a value together with its remaining count. */
    private static final class FrequencyItem implements Comparable<FrequencyItem> {
        final int value;
        int remaining;

        FrequencyItem(int value, int count) {
            this.value = value;
            this.remaining = count;
        }

        @Override
        public int compareTo(FrequencyItem other) {
            int freqDiff = other.remaining - this.remaining;   // larger count first
            if (freqDiff != 0) {
                return freqDiff;
            }
            // tie‑break by the numeric value (smaller first)
            return Integer.compare(this.value, other.value);
        }
    }

    public static void main(String[] args) throws IOException {
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in))) {
            int n = Integer.parseInt(br.readLine().trim());
            int[] values = readIntArray(br.readLine());

            PriorityQueue<FrequencyItem> queue = buildFrequencyQueue(values);
            int[][] matrix = new int[n][n];

            if (!placeCenter(matrix, queue) ||
                !placeMiddleCross(matrix, queue) ||
                !placeCorners(matrix, queue)) {
                System.out.println("NO");
                return;
            }

            StringBuilder out = new StringBuilder("YES\n");
            for (int[] row : matrix) {
                for (int v : row) {
                    out.append(v).append(' ');
                }
                out.append('\n');
            }
            System.out.print(out);
        }
    }

    /** Reads a space‑separated line of integers. */
    private static int[] readIntArray(String line) {
        String[] tokens = line.trim().split("\\s+");
        int[] arr = new int[tokens.length];
        for (int i = 0; i < tokens.length; i++) {
            arr[i] = Integer.parseInt(tokens[i]);
        }
        return arr;
    }

    /** Builds a priority queue ordered by descending frequency then ascending value. */
    private static PriorityQueue<FrequencyItem> buildFrequencyQueue(int[] values) {
        Map<Integer, Integer> frequencyMap = new HashMap<>();
        for (int v : values) {
            frequencyMap.merge(v, 1, Integer::sum);
        }

        PriorityQueue<FrequencyItem> queue = new PriorityQueue<>();
        for (Map.Entry<Integer, Integer> entry : frequencyMap.entrySet()) {
            queue.add(new FrequencyItem(entry.getKey(), entry.getValue()));
        }
        return queue;
    }

    /** Places the single centre element (used when n is odd). */
    private static boolean placeCenter(int[][] matrix, PriorityQueue<FrequencyItem> queue) {
        if (!queue.isEmpty()) {
            FrequencyItem item = queue.poll();
            int half = matrix.length / 2;
            matrix[half][half] = item.value;
            if (item.remaining > 1) {
                queue.add(new FrequencyItem(item.value, item.remaining - 1));
            }
        }
        return !queue.isEmpty(); // there must be at least one element left for the centre
    }

    /** Fills the middle row and middle column (the “cross”). */
    private static boolean placeMiddleCross(int[][] matrix, PriorityQueue<FrequencyItem> queue) {
        int size = matrix.length;
        int half = size / 2;

        // pairs for the row (excluding centre)
        for (int i = 0; i < half; i++) {
            if (queue.poll() == null || queue.poll().remaining < 2) {
                System.out.println("NO");
                return false;
            }
            FrequencyItem item = queue.poll();
            matrix[half][i] = matrix[half][size - 1 - i] = item.value;
            if (item.remaining > 2) {
                queue.add(new FrequencyItem(item.value, item.remaining - 2));
            }
        }

        // pairs for the column (excluding centre)
        for (int i = 0; i < half; i++) {
            if (queue.poll() == null || queue.poll().remaining < 2) {
                System.out.println("NO");
                return false;
            }
            FrequencyItem item = queue.poll();
            matrix[i][half] = matrix[size - 1 - i][half] = item.value;
            if (item.remaining > 2) {
                queue.add(new FrequencyItem(item.value, item.remaining - 2));
            }
        }
        return true;
    }

    /** Fills the four symmetric corners of the matrix. */
    private static boolean placeCorners(int[][] matrix, PriorityQueue<FrequencyItem> queue) {
        int size = matrix.length;
        int half = size / 2;

        for (int i = 0; i < half; i++) {
            for (int j = 0; j < half; j++) {
                if (queue.poll() == null || queue.poll().remaining < 4) {
                    System.out.println("NO");
                    return false;
                }
                FrequencyItem item = queue.poll();
                int v = item.value;
                matrix[i][j] = matrix[i][size - 1 - j] =
                             matrix[size - 1 - i][j] = matrix[size - 1 - i][size - 1 - j] = v;
                if (item.remaining > 4) {
                    queue.add(new FrequencyItem(v, item.remaining - 4));
                }
            }
        }
        return true;
    }
}

/**
 * Refactored version of the original `ProblemC`.
 *
 * <p>
 *   The program reads an integer `n` followed by `n*n` integers, counts how often each
 *   integer occurs and then tries to fill an `n × n` matrix that is symmetric with
 *   respect to both axes. The algorithm works for both even and odd dimensions.
 *   It prints "YES" together with the matrix when a valid assignment exists,
 *   otherwise it prints "NO".
 * </p>
 *
 * <p>
 *   The refactor improves readability, type‑safety and modularisation while keeping
 *   the original behaviour unchanged.
 * </p>
 */
public class ProblemC {

    /** Holds a distinct number together with its current remaining frequency. */
    private static final class FrequencyEntry {
        /** The numeric value stored in the entry. */
        final int value;
        /** How many times the value can still be used. */
        int remaining;

        FrequencyEntry(int value) {
            this.value = value;
            this.remaining = 1;
        }
    }

    /** Comparator that orders entries by descending remaining frequency. */
    private static final class FrequencyDescendingComparator implements Comparator<FrequencyEntry> {
        @Override
        public int compare(FrequencyEntry o1, FrequencyEntry o2) {
            return Integer.compare(o2.remaining, o1.remaining);
        }
    }

    /** --------------------------------------------------------------------- */
    /**                         Entry point                                   */
    /** --------------------------------------------------------------------- */
    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            int dimension = scanner.nextInt();                 // n
            int totalElements = dimension * dimension;
            List<Integer> numbers = readNumbers(scanner, totalElements);

            Map<Integer, FrequencyEntry> frequencyMap = buildFrequencyMap(numbers);
            List<FrequencyEntry> sortedEntries = new ArrayList<>(frequencyMap.values());
            sortedEntries.sort(new FrequencyDescendingComparator());

            boolean possible = tryFillMatrix(dimension, sortedEntries);
            if (possible) {
                printMatrix(matrix);
            } else {
                System.out.println("NO");
            }
        }
    }

    /** --------------------------------------------------------------------- */
    /**                         Input handling                                 */
    /** --------------------------------------------------------------------- */
    private static List<Integer> readNumbers(Scanner scanner, int count) {
        List<Integer> result = new ArrayList<>(count);
        for (int i = 0; i < count; i++) {
            result.add(scanner.nextInt());
        }
        return result;
    }

    /** --------------------------------------------------------------------- */
    /**                     Frequency map construction                           */
    /** --------------------------------------------------------------------- */
    private static Map<Integer, FrequencyEntry> buildFrequencyMap(List<Integer> numbers) {
        Map<Integer, FrequencyEntry> map = new HashMap<>();
        for (Integer num : numbers) {
            FrequencyEntry entry = map.computeIfAbsent(num, FrequencyEntry::new);
            entry.remaining++;
        }
        return map;
    }

    /** --------------------------------------------------------------------- */
    /**                         Matrix filling logic                           */
    /** --------------------------------------------------------------------- */
    /** Returns true when a valid symmetric matrix could be built. */
    private static boolean tryFillMatrix(int n, List<FrequencyEntry> entries) {
        // Make a mutable copy because the algorithm will modify remaining counts.
        List<FrequencyEntry> mutableEntries = new ArrayList<>(entries);
        matrix = new int[n][n];
        return fillSymmetricMatrix(0, n, mutableEntries);
    }

    /** Core recursive routine that places numbers layer by layer. */
    private static boolean fillSymmetricMatrix(int startLayer, int size, List<FrequencyEntry> entries) {
        if (size == 0) {
            return true; // Base case: matrix completely filled.
        }

        // -----------------------------------------------------------------
        // 1️⃣  Fill the four symmetric corners of the current layer
        // -----------------------------------------------------------------
        for (int col = startLayer; col < size / 2; col++) {
            int entryIdx = findEntryWithAtLeast(entries, 4);
            if (entryIdx == -1) {
                return false;
            }
            FrequencyEntry e = entries.get(entryIdx);
            e.remaining -= 4;

            int value = e.value;
            int pos = size - 1 - startLayer;

            matrix[startLayer][col] = value;
            matrix[startLayer][pos] = value;
            matrix[pos][col] = value;
            matrix[pos][pos] = value;
        }

        // -----------------------------------------------------------------
        // 2️⃣  Fill the edge‑mid positions that require 2 copies
        // -----------------------------------------------------------------
        for (int row = startLayer; row < size / 2; row++) {
            int entryIdx = findEntryWithAtLeast(entries, 2);
            if (entryIdx == -1) {
                return false;
            }
            FrequencyEntry e = entries.get(entryIdx);
            e.remaining -= 2;

            int pos = size - 1 - startLayer;
            matrix[row][startLayer] = e.value;
            matrix[row][pos] = e.value;
            matrix[pos][row] = e.value;
            matrix[pos][pos] = e.value;
        }

        // -----------------------------------------------------------------
        // 3️⃣  Handle centre when size is odd
        // -----------------------------------------------------------------
        if (size % 2 == 1) {
            // The exact centre needs exactly one occurrence.
            int centre = size / 2;
            int entryIdx = findEntryWithAtLeast(entries, 1);
            if (entryIdx == -1) {
                return false;
            }
            FrequencyEntry e = entries.get(entryIdx);
            e.remaining--;

            matrix[centre][centre] = e.value;
        }

        // -----------------------------------------------------------------
        // 4️⃣  Re‑curse into the inner sub‑matrix
        // -----------------------------------------------------------------
        return fillSymmetricMatrix(startLayer + 1, size - 2, entries);
    }

    /** Helper that returns the index of the first entry whose remaining count
     *  is at least {@code required}, or –1 if none exists. */
    private static int findEntryWithAtLeast(List<FrequencyEntry> entries, int required) {
        for (int i = 0; i < entries.size(); i++) {
            if (entries.get(i).remaining >= required) {
                return i;
            }
        }
        return -1;
    }

    /** --------------------------------------------------------------------- */
    /**                         Output helpers                                   */
    /** --------------------------------------------------------------------- */
    private static final int[][] matrix = new int[100][100]; // Sufficient for typical constraints

    private static void printMatrix(int[][] mat) {
        for (int[] row : mat) {
            for (int value : row) {
                System.out.print(value + " ");
            }
            System.out.println();
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Utility class that supplies fast tokenised input.
 */
final class FastScanner {
    private final BufferedReader br;
    private StringTokenizer st;

    FastScanner() {
        try {
            br = new BufferedReader(new InputStreamReader(System.in));
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
    }

    /** Returns the next whole token. */
    String next() {
        if (st == null || !st.hasMoreTokens()) {
            readNextLine();
        }
        return st.nextToken();
    }

    /** Reads the next line and builds a new StringTokenizer. */
    private void readNextLine() {
        try {
            String line = br.readLine();
            if (line == null) {
                st = null;
                return;
            }
            st = new StringTokenizer(line);
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
    }

    /** Convenience wrapper for {@link #next()} that parses an {@code int}. */
    int nextInt() {
        return Integer.parseInt(next());
    }

    /** Convenience wrapper for {@link #next()} that parses a {@code long}. */
    long nextLong() {
        return Long.parseLong(next());
    }

    /** Convenience wrapper for {@link #next()} that parses a {@code double}. */
    double nextDouble() {
        return Double.parseDouble(next());
    }

    /** Convenience wrapper for {@link #nextLine()} that reads a full line. */
    String nextLine() {
        if (st == null || !st.hasMoreTokens()) {
            readNextLine();
        }
        StringBuilder sb = new StringBuilder();
        while (st.hasMoreTokens()) {
            sb.append(st.nextToken());
            if (st.hasMoreTokens()) sb.append(' ');
        }
        return sb.toString();
    }
}

/**
 * Core solver that reads the input, builds the pattern and prints the result.
 */
final class Solver {

    /** Simple holder that stores a value and its remaining frequency. */
    private static final class Element implements Comparable<Element> {
        final int value;
        int remaining;

        Element(int value, int remaining) {
            this.value = value;
            this.remaining = remaining;
        }

        @Override
        public int compareTo(Element o) {
            // Sort descending by remaining count
            return Integer.compare(o.remaining, remaining);
        }
    }

    private static final class Position {
        final int row, col;

        Position(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }

    /** Maximum board size we need to support. */
    private static final int MAX_VAL = 1000;

    /** Number of quadrants (4 per centre) in an N×N matrix. */
    private static final int QUADS = 4;

    /** Edge positions (2 per centre) that appear only twice on each side. */
    private static final int EDGES = 2;

    /** Entry point. */
    public static void main(String[] args) {
        new Solver().solve();
    }

    /** Orchestrates the whole workflow. */
    void solve() {
        FastScanner sc = new FastScanner();
        int n = sc.nextInt();

        // -------------------------------------------------
        // 1️⃣  Gather frequencies of every number.
        // -------------------------------------------------
        int[] frequency = new int[MAX_VAL + 1];
        int totalElements = n * n;
        for (int i = 0; i < totalElements; ++i) {
            ++frequency[sc.nextInt()];
        }

        // Build a list of elements ordered by decreasing frequency.
        List<Element> elements = new ArrayList<>();
        for (int v = 1; v <= MAX_VAL; ++v) {
            if (frequency[v] > 0) {
                elements.add(new Element(v, frequency[v]));
            }
        }
        elements.sort(Element::compareTo);

        // -------------------------------------------------
        // 2️⃣  Initialise the output matrix.
        // -------------------------------------------------
        int[][] matrix = new int[n][n];

        // -------------------------------------------------
        // 3️⃣  Fill the matrix symmetrically.
        // -------------------------------------------------
        if (!placeQuadrants(matrix, elements)) {
            System.out.println("NO");
            return;
        }

        // If the dimension is odd we need extra centre row/column & centre cell.
        if (n % 2 == 1) {
            if (!placeCenterRow(matrix, elements) ||
                !placeCenterColumn(matrix, elements)) {
                System.out.println("NO");
                return;
            }
        }

        // -------------------------------------------------
        // 4️⃣  Output the matrix.
        // -------------------------------------------------
        System.out.println("YES");
        printMatrix(matrix);
    }

    /** Places numbers that appear four times into symmetric quadrants. */
    private boolean placeQuadrants(int[][] matrix, List<Element> elements) {
        int half = matrix.length / 2;
        int placed = 0;

        while (placed < half * half) {
            Element e = elements.get(0);
            if (e.remaining < QUADS) {
                return false;                     // not enough count for a quadrant
            }

            // Fill one quadrant (four symmetric cells)
            fillSymmetric(matrix, placed % 2, placed / 2, e.value);
            consume(e, QUADS);
            sortDesc(elements);
            ++placed;
        }
        return true;
    }

    /** Places numbers that appear twice into edge positions. */
    private boolean placeCenterRow(int[][] matrix, List<Element> elements) {
        int centre = matrix.length / 2;
        int placed = 0;
        int half = matrix.length / 2;

        while (placed < half) {
            Element e = elements.get(0);
            if (e.remaining < EDGES) {
                return false;
            }
            mirrorFill(matrix, centre, placed % half, centre, half - 1 - placed % half, e.value);
            consume(e, EDGES);
            sortDesc(elements);
            ++placed;
        }
        return true;
    }

    /** Places numbers that appear twice into the opposite side positions. */
    private boolean placeCenterColumn(int[][] matrix, List<Element> elements) {
        int centre = matrix.length / 2;
        int placed = 0;
        int half = matrix.length / 2;

        while (placed < half) {
            Element e = elements.get(0);
            if (e.remaining < EDGES) {
                return false;
            }
            fillSymmetric(matrix, placed % half, centre, e.value); // column symmetry
            consume(e, EDGES);
            sortDesc(elements);
            ++placed;
        }
        return true;
    }

    /** Writes a value into four symmetric cells of the matrix. */
    private void fillSymmetric(int[][] matrix, int quadRow, int quadCol, int value) {
        int n = matrix.length;
        int r = quadRow;
        int c = quadCol;
        matrix[r][c] = value;
        matrix[r][n - 1 - c] = value;
        matrix[n - 1 - r][n - 1 - c] = value;
        matrix[n - 1 - r][c] = value;
    }

    /** Writes a value into two symmetric positions of a given row (used for centre row). */
    private void mirrorFill(int[][] matrix, int centreRow, int col, int centreRowMirror, int colMirror, int value) {
        matrix[centreRow][col] = value;
        matrix[centreRowMirror][colMirror] = value;
    }

    /** Consumes a fixed amount from the first element of the list. */
    private void consume(Element e, int amount) {
        e.remaining -= amount;
    }

    /** Re‑orders the list so that the element with the most remaining count is at index 0. */
    private void sortDesc(List<Element> elements) {
        elements.sort(Element::compareTo);
    }

    /** Prints the matrix in the required format. */
    private void printMatrix(int[][] matrix) {
        for (int[] row : matrix) {
            for (int cell : row) {
                System.out.print(cell + ' ');
            }
            System.out.println();
        }
    }
}

/**
 * Palindrome Matrix Builder
 *
 * Reads an integer {@code n} followed by {@code n*n} integers.
 * Determines whether those integers can be arranged into an {@code n×n}
 * matrix that is symmetric with respect to both the horizontal and vertical
 * axes. If possible, prints “YES” and the constructed matrix; otherwise
 * prints “NO”.
 *
 * The implementation is deliberately split into small, well‑named methods
 * and uses only standard library types, making the code easy to test,
 * debug, and extend.
 */
public class Main {

    /** Fast scanner used by the whole program. */
    private static final FastReader INPUT = new FastReader();
    /** Output stream – here we simply write to {@code System.out}. */
    private static final PrintWriter OUT = new PrintWriter(System.out, true);

    public static void main(String[] args) throws IOException {
        int n = INPUT.nextInt();                       // size of the square matrix
        int[] frequencies = new int[1001];             // frequency of each value (1‑1000)

        // read n*n numbers and fill the frequency table
        for (int i = 0; i < n * n; i++) {
            frequencies[INPUT.nextInt()]++;
        }

        // Required multiplicities for building a symmetric matrix
        int requiredFour  = (n / 2) * (n / 2);          // 4‑fold symmetry cells
        int requiredTwo   = (n % 2 == 1) ? (2 * n - 2) / 2 : 0;
        int requiredOne   = (n % 2 == 1) ? 1 : 0;

        // Allocate values into three buckets according to how many times they can be used
        List<Integer> fours  = new ArrayList<>();
        List<Integer> twos   = new ArrayList<>();
        List<Integer> ones   = new ArrayList<>();

        allocateBuckets(frequencies, fours, twos, ones);

        // Verify that the buckets contain exactly the numbers we need
        if (fours.size() == requiredFour && twos.size() == requiredTwo && ones.size() == requiredOne) {
            buildAndPrintMatrix(n, fours, twos, ones);
        } else {
            OUT.println("NO");
        }
    }

    /**
     * Distributes each integer value into three buckets:
     *   fours  – numbers that appear at least four times,
     *   twos   – numbers that appear at least two times after removing multiples of four,
     *   ones   – the remaining singles.
     *
     * The algorithm works on a copy of the frequency array so that the original
     * frequencies are not needed any more.
     */
    private static void allocateBuckets(
            int[] freq,
            List<Integer> fours,
            List<Integer> twos,
            List<Integer> ones) {

        for (int value = 0; value < freq.length; value++) {
            int count = freq[value];

            // multiples of 4 → bucket for 4‑fold cells
            int fourCount = count / 4;
            freq[value] %= 4;
            fours.addAll(repeated(value, fourCount));

            // remaining pairs → bucket for 2‑fold cells
            int twoCount = freq[value] / 2;
            freq[value] %= 2;
            twos.addAll(repeated(value, twoCount));

            // leftovers → bucket for single cells
            ones.addAll(repeated(value, freq[value]));
        }
    }

    /**
     * Helper that returns a list consisting of {@code times} copies of {@code value}.
     */
    private static List<Integer> repeated(int value, int times) {
        List<Integer> list = new ArrayList<>(times);
        for (int i = 0; i < times; i++) {
            list.add(value);
        }
        return list;
    }

    /**
     * Constructs the symmetric matrix from the three prepared buckets and prints it.
     *
     * The matrix is filled in four quadrants simultaneously, guaranteeing symmetry.
     * Special handling is performed for the centre row/column when {@code n} is odd.
     */
    private static void buildAndPrintMatrix(
            int n,
            List<Integer> fours,
            List<Integer> twos,
            List<Integer> ones) {

        int[][] grid = new int[n][n];

        // ---- Fill the four‑fold symmetry cells (the four quadrants) ----
        for (int i = 0; i < n / 2; i++) {
            for (int j = 0; j < n / 2; j++) {
                int value = fours.remove(fours.size() - 1);
                grid[i][j] = value;
                grid[n - 1 - i][j] = value;
                grid[n - 1 - i][n - 1 - j] = value;
                grid[i][n - 1 - j] = value;
            }
        }

        // ---- Fill the centre row (and column) when n is odd ----
        if (n % 2 == 1) {
            if (!ones.isEmpty()) {
                grid[n / 2][n / 2] = ones.remove(ones.size() - 1);
            }
            if (!twos.isEmpty()) {
                // The vertical centre line (excluding the centre cell)
                for (int i = 0; i < n / 2; i++) {
                    int value = twos.remove(twos.size() - 1);
                    grid[i][n / 2] = value;
                    grid[n - 1 - i][n / 2] = value;
                }
                // The horizontal centre line (excluding the centre cell)
                for (int i = 0; i < n / 2; i++) {
                    int value = twos.remove(twos.size() - 1);
                    grid[n / 2][i] = value;
                    grid[n / 2][n - 1 - i] = value;
                }
            }
        }

        // ---- Output ----
        OUT.println("YES");
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                OUT.print(grid[i][j]);
                if (j < n - 1) {
                    OUT.print(' ');
                }
            }
            OUT.println();
        }
    }

    /**
     * Very small wrapper around {@code BufferedReader} that provides convenient
     * tokenised reading. It is deliberately kept static to avoid unnecessary
     * object creation.
     */
    private static class FastReader {
        private final BufferedReader br;
        private StringTokenizer st;

        FastReader() {
            this.br = new BufferedReader(new InputStreamReader(System.in));
        }

        /** Returns the next token (lexicographically separated by whitespace). */
        String next() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                st = new StringTokenizer(br.readLine());
            }
            return st.nextToken();
        }

        /** Convenience wrapper for {@code Integer.parseInt}. */
        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }
}

import java.io.IOException;
import java.io.PrintWriter;
import java.util.Scanner;

/**
 * Generates an n×n matrix that satisfies the described filling rules.
 * The program reads a single integer {@code n} from standard input,
 * processes the counts of numbers needed to fill symmetric groups,
 * and prints either "NO" or "YES" followed by the resulting matrix.
 *
 * All magic numbers, duplicated logic, and global mutable state have been
 * removed.  The code is split into small, single‑purpose methods that
 * make the algorithm easy to understand and test.
 */
public final class GridGenerator {

    /** Maximum value that can appear in the input count list. */
    private static final int MAX_COUNT = 1000;

    /** Size of the temporary frequency array for counting numbers. */
    private static final int COUNT_ARRAY_SIZE = MAX_COUNT + 1;

    private GridGenerator() {
        // Utility class – no instances.
    }

    /** Entry point – delegates work to the dedicated providers. */
    public static void main(String[] args) throws IOException {
        // -----------------------------------------------------------------
        // 1️⃣  Input handling (try‑with‑resources guarantees proper closing)
        // -----------------------------------------------------------------
        try (Scanner scanner = new Scanner(System.in)) {
            int n = scanner.nextInt();
            int[] frequency = readFrequency(scanner, n);

            boolean solutionExists = fillMatrix(n, frequency);
            outputResult(solutionExists);
        }
    }

    /** Reads the n² integers that represent the required multiplicities. */
    private static int[] readFrequency(Scanner scanner, int n) {
        int[] frequency = new int[COUNT_ARRAY_SIZE];
        int totalNumbers = n * n;
        for (int i = 0; i < totalNumbers; i++) {
            int value = scanner.nextInt();
            if (value < 0 || value >= COUNT_ARRAY_SIZE) {
                System.err.println("Count value out of supported range [0," + (COUNT_ARRAY_SIZE - 1) + "]");
                System.exit(1);
            }
            frequency[value]++;
        }
        return frequency;
    }

    /** Determines whether a valid filling exists and, if so, fills the matrix. */
    private static boolean fillMatrix(int n, int[] frequency) {
        // 1️⃣ Build the mapping of each position in the quadrant to the size of its orbit.
        int[][] orbitSize = buildOrbitSizeMatrix(n);

        // 2️⃣ Attempt to assign numbers in order of orbit size (4 → 2 → 1).
        int[][] matrix = new int[n][n];
        boolean undone = false;

        for (int orbitCount : new int[] {4, 2, 1}) {
            int nextAvailableNumber = 1;
            for (int i = 0; i <= (n - 1) / 2 && !undone; i++) {
                for (int j = 0; j <= (n - 1) / 2 && !undone; j++) {
                    if (orbitSize[i][j] != orbitCount) {
                        continue; // skip cells that do not belong to this orbit size
                    }

                    // Find the smallest unused number that appears enough times.
                    int candidate = findNextCandidate(frequency, orbitCount, nextAvailableNumber);
                    if (candidate == -1) {
                        undone = true;          // no suitable number → impossible
                        break;
                    }

                    // Place the number in the four symmetric positions.
                    placeNumber(matrix, candidate, i, j, n);
                    frequency[candidate] -= orbitCount;
                }
            }
            if (undone) {
                break;
            }
        }

        // 3️⃣ If we were unable to place all required numbers, the answer is "NO".
        if (undone) {
            return false;
        }

        // 4️⃣ Otherwise, output the matrix (handled by a separate method).
        printMatrix(System.out, matrix);
        return true;
    }

    /** Constructs the cell → orbit‑size matrix used for symmetry handling. */
    private static int[][] buildOrbitSizeMatrix(int n) {
        int[][] orbit = new int[(n + 1) / 2][(n + 1) / 2];
        int half = (n + 1) / 2;

        for (int i = 0; i < half; i++) {
            for (int j = 0; j < half; j++) {
                boolean isHorizontalMid = i != (n - 1 - i);
                boolean isVerticalMid   = j != (n - 1 - j);

                if (isHorizontalMid && isVerticalMid) {
                    orbit[i][j] = 4;                       // full 4‑cell orbit
                } else if (isHorizontalMid ^ isVerticalMid) {
                    orbit[i][j] = 2;                       // edge of a 2‑cell orbit
                } else {
                    orbit[i][j] = 1;                       // centre cell (odd n)
                }
            }
        }
        return orbit;
    }

    /** Scans the frequency array for the first unused number that occurs at least {@code needed} times. */
    private static int findNextCandidate(int[] freq, int needed, int start) {
        for (int candidate = start; candidate < COUNT_ARRAY_SIZE; candidate++) {
            if (freq[candidate] >= needed) {
                return candidate;
            }
        }
        return -1; // not found
    }

    /** Writes the given number into the four symmetric positions of the matrix. */
    private static void placeNumber(int[][] matrix, int number, int i, int j, int size) {
        int complement_i = size - 1 - i;
        int complement_j = size - 1 - j;
        matrix[i][j] = number;
        matrix[complement_i][j] = number;
        matrix[i][complement_j] = number;
        matrix[complement_i][complement_j] = number;
    }

    /** Prints the resulting matrix to the supplied PrintWriter (or System.out). */
    private static void printMatrix(PrintWriter out, int[][] matrix) {
        int n = matrix.length;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                out.print(matrix[i][j]);
                if (j < n - 1) {
                    out.print(' ');
                }
            }
            out.println();
        }
    }

    /** Emits either "NO" or "YES" followed by the filled matrix. */
    private static void outputResult(boolean solutionExists) {
        PrintWriter out = new PrintWriter(System.out);
        if (!solutionExists) {
            out.println("NO");
            out.flush();
            return;
        }
        out.println("YES");
        // The matrix has already been printed inside fillMatrix when a solution is found.
        out.flush();
    }
}

import java.io.*;
import java.util.*;

/**
 * Reads input, builds a palindromic matrix and prints it.
 * The implementation is focused on readability, proper naming and
 * separation of concerns.
 */
public class PalindromicMatrix {

    /* ----------  Input helper  ---------- */
    private static class FastScanner {
        private final BufferedReader br;

        FastScanner(InputStream in) {
            this.br = new BufferedReader(new InputStreamReader(in));
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }

        String next() throws IOException {
            while (st == null || !st.hasMoreElements()) {
                String line = br.readLine();
                if (line == null) return null;
                st = new StringTokenizer(line);
            }
            return st.nextToken();
        }

        StringLine nextLine() throws IOException {
            String line = br.readLine();
            if (line == null) return null;
            return new StringLine(line);
        }

        // Simple holder for the current tokenizer
        private StringTokenizer st;
    }

    private static class StringLine {
        private final String content;
        private StringTokenizer st;

        StringLine(String s) { this.content = s; }

        String next() {
            if (st == null || !st.hasMoreTokens()) {
                st = new StringTokenizer(content);
            }
            return st.nextToken();
        }

        int nextInt() { return Integer.parseInt(next()); }
    }

    /* ----------  Model objects  ---------- */
    private static final class Coord {
        final int row, col;
        Coord(int r, int c) { this.row = r; this.col = c; }

        @Override public boolean equals(Object o) {
            if (this == o) return true;
            if (!(o instanceof Coord)) return false;
            Coord c = (Coord) o;
            return row == c.row && col == c.col;
        }

        @Override public int hashCode() {
            return Objects.hash(row, col);
        }
    }

    /** One palindromic group of positions that must contain the same value. */
    private static final class Group {
        final List<Coord> coords;
        final int size;

        Group(List<Coord> c) {
            this.coords = c;
            this.size = c.size();
        }
    }

    /* ----------  Helper methods  ---------- */
    /** Add the four symmetric coordinates of (r,c) to a set (duplicates are ignored). */
    private static void collectSymmetric(int r, int c, Set<Coord> set, int n) {
        int rev = n - 1;
        set.add(new Coord(r, c));
        set.add(new Coord(r, rev - c));
        set.add(new Coord(rev - r, c));
        set.add(new Coord(rev - r, rev - c));
    }

    /** Build all groups that a palindromic matrix consists of. */
    private static List<Group> buildGroups(int n) {
        List<Group> groups = new ArrayList<>();
        boolean[][] visited = new boolean[n][n];

        // 1. Groups coming from the top‑left quadrant (size 4 or less when on a middle line)
        for (int i = 0; i < n / 2; i++) {
            for (int j = 0; j < n / 2; j++) {
                Set<Coord> sym = new HashSet<>();
                collectSymmetric(i, j, sym, n);
                List<Coord> list = new ArrayList<>(sym);
                groups.add(new Group(list));
                for (Coord p : list) visited[p.row][p.col] = true;
            }
        }

        // 2. If n is odd, handle the middle row, middle column and the centre cell
        if (n % 2 == 1) {
            int mid = n / 2;

            // middle column pairs
            for (int i = 0; i < mid; i++) {
                int rev = n - 1 - i;
                if (!visited[i][mid]) {
                    Set<Coord> sym = new HashSet<>();
                    sym.add(new Coord(i, mid));
                    sym.add(new Coord(rev, mid));
                    groups.add(new Group(new ArrayList<>(sym)));
                    visited[i][mid] = visited[rev][mid] = true;
                }
            }

            // middle row pairs
            for (int j = 0; j < mid; j++) {
                int rev = n - 1 - j;
                if (!visited[mid][j]) {
                    Set<Coord> sym = new HashSet<>();
                    sym.add(new Coord(mid, j));
                    sym.add(new Coord(mid, rev));
                    groups.add(new Group(new ArrayList<>(sym)));
                    visited[mid][j] = visited[mid][rev] = true;
                }
            }

            // centre cell (size 1)
            if (!visited[mid][mid]) {
                groups.add(new Group(List.of(new Coord(mid, mid))));
            }
        }
        return groups;
    }

    /** Assign a value from the frequency map that can satisfy the required size.
     *  Throws IllegalStateException if not possible (used to emit "NO"). */
    private static int assignValue(Map<Integer, Integer> freq, int need) {
        int bestKey = -1;
        int bestCnt = -1;
        for (Map.Entry<Integer, Integer> e : freq.entrySet()) {
            if (e.getValue() >= need) {
                if (e.getValue() > bestCnt || (e.getValue() == bestCnt && e.getKey() > bestKey)) {
                    bestKey = e.getKey();
                    bestCnt = e.getValue();
                }
            }
        }
        if (bestKey == -1) {
            throw new IllegalStateException();
        }
        // consume the chosen value
        int newCnt = bestCnt - need;
        if (newCnt == 0) {
            freq.remove(bestKey);
        } else {
            freq.put(bestKey, newCnt);
        }
        return bestKey;
    }

    /* ----------  Main algorithm  ---------- */
    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        int n = fs.nextInt();
        int[] values = new int[n * n];
        for (int i = 0; i < n * n; i++) {
            values[i] = fs.nextInt();
        }

        // 1. Build frequency map
        Map<Integer, Integer> freq = new HashMap<>();
        for (int v : values) {
            freq.merge(v, 1, Integer::sum);
        }

        // 2. Create groups that must share the same value
        List<Group> groups = buildGroups(n);
        groups.sort(Comparator.comparingInt(g -> g.size).reversed());

        // 3. Allocate a value to each group
        int[][] matrix = new int[n][n];
        boolean possible = true;
        for (Group g : groups) {
            try {
                int val = assignValue(freq, g.size);
                for (Coord c : g.coords) {
                    matrix[c.row][c.col] = val;
                }
            } catch (IllegalStateException e) {
                possible = false;
                break;
            }
        }

        // 4. Output result
        if (!possible) {
            System.out.println("NO");
            return;
        }

        System.out.println("YES");
        for (int i = 0; i < n; i++) {
            StringBuilder sb = new StringBuilder();
            for (int j = 0; j < n; j++) {
                sb.append(matrix[i][j]);
                if (j < n - 1) sb.append(' ');
            }
            System.out.println(sb);
        }
    }
}

import java.io.*;
import java.util.*;

public class Solution {

    /** Maximum possible value read from input (as used in the original code). */
    private static final int MAX_VALUE = 1000;

    /** Entry point. */
    public static void main(String[] args) throws IOException {
        // try‑with‑resources guarantees the writer is closed even on exception
        try (BufferedWriter bw = new BufferedWriter(new OutputStreamWriter(System.out))) {
            InputReader reader = new InputReader(System.in);
            int size = reader.nextInt();

            // Frequency table for the numbers that will fill the matrix
            int[] frequency = new int[MAX_VALUE + 1];
            for (int i = 0; i < size * size; i++) {
                int val = reader.nextInt();
                if (val < 1 || val > MAX_VALUE) {
                    throw new IllegalArgumentException("Value out of expected range");
                }
                frequency[val]++;
            }

            int[][] matrix = new int[size][size];
            if (!populateMatrix(size, frequency, matrix)) {
                bw.write("NO");
                bw.flush();
                return;
            }

            bw.write("YES");
            bw.newLine();
            printMatrix(bw, matrix);
        }
    }

    /** Builds the matrix according to the problem rules. Returns false if impossible. */
    private static boolean populateMatrix(int n, int[] freq, int[][] matrix) {
        return (n % 2 == 0) ? fillEvenMatrix(n, freq, matrix)
                            : fillOddMatrix(n, freq, matrix);
    }

    /** Handles the even‑size case. */
    private static boolean fillEvenMatrix(int n, int[] freq, int[][] matrix) {
        // Verify that the whole board can be covered by groups of 4 identical numbers.
        int groupsOfFour = 0;
        for (int count : freq) {
            if (count > 0 && count % 4 == 0) {
                groupsOfFour += count / 4;
            }
        }
        if (groupsOfFour * 4 != n * n) {
            return false;
        }

        // Fill the matrix quadrant by quadrant.
        int placedRow = 0;
        int placedCol = 0;
        for (int value = 1; value <= MAX_VALUE; value++) {
            while (freq[value] > 0) {
                placeSymmetricGroup(matrix, value, placedRow, placedCol);
                placedRow++;
                freq[value] -= 4;

                if (placedRow == n / 2) {
                    placedRow = 0;
                    placedCol++;
                }
            }
        }
        return true;
    }

    /** Handles the odd‑size case. */
    private static boolean fillOddMatrix(int n, int[] freq, int[][] matrix) {
        int half = n / 2;
        int placedRow = 0;
        int placedCol = 0;

        // Place the single centre element (must appear an odd number of times).
        for (int value = 1; value <= MAX_VALUE; value++) {
            if ((freq[value] & 1) == 1) {
                matrix[half][half] = value;
                freq[value]--;
                break;
            }
        }

        // Fill the central row with pairs that appear ≡ 2 (mod 4) times.
        for (int value = 1; value <= MAX_VALUE; value++) {
            if (freq[value] % 4 == 2) {
                while (freq[value] > 0 && placedRow < half) {
                    placeHorizontalPair(matrix, value, placedRow);
                    placedRow++;
                    freq[value] -= 2;
                }
            }
        }

        // Fill the central column with the remaining such pairs.
        for (int value = 1; value <= MAX_VALUE; value++) {
            if (freq[value] % 4 == 2) {
                while (freq[value] > 0 && placedCol < half) {
                    placeVerticalPair(matrix, value, placedCol);
                    placedCol++;
                    freq[value] -= 2;
                }
            }
        }

        // Fill the remaining quadrants with groups of 4.
        for (int value = 1; value <= MAX_VALUE; value++) {
            while (freq[value] > 0) {
                placeSymmetricGroup(matrix, value, placedRow, placedCol);
                placedRow++;
                placedCol++;
                freq[value] -= 4;
            }
        }
        return true;
    }

    /** Writes a 4‑cell symmetric group centred at (row, col). */
    private static void placeSymmetricGroup(int[][] mat, int value, int row, int col) {
        int half = mat.length / 2;
        int r = row;
        int c = col;
        mat[r][c] = value;
        mat[half * 2 - 1 - r][c] = value;
        mat[r][half * 2 - 1 - c] = value;
        mat[half * 2 - 1 - r][half * 2 - 1 - c] = value;
    }

    /** Writes a horizontal pair on the centre row. */
    private static void placeHorizontalPair(int[][] mat, int value, int col) {
        int half = mat.length / 2;
        mat[half][col] = value;
        mat[half][mat.length - 1 - col] = value;
    }

    /** Writes a vertical pair on the centre column. */
    private static void placeVerticalPair(int[][] mat, int value, int row) {
        int half = mat.length / 2;
        mat[row][half] = value;
        mat[mat.length - 1 - row][half] = value;
    }

    /** Prints the matrix to the supplied BufferedWriter. */
    private static void printMatrix(BufferedWriter bw, int[][] matrix) throws IOException {
        int n = matrix.length;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                bw.write(matrix[i][j] + " ");
            }
            bw.newLine();
        }
    }

    /** Simple tokenizer that reads whitespace‑separated tokens from standard input. */
    private static class InputReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        InputReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream), 32768);
        }

        String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        long nextLong() {
            return Long.parseLong(next());
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Reads the input, analyses the frequencies of numbers and builds a
 * matrix that satisfies the required symmetry constraints.
 *
 * <p>
 * The program follows these steps:
 *
 * <ol>
 *   <li>Read the integer {@code n} and the {@code n²} numbers.</li>
 *   <li>Count how many times each distinct number appears.</li>
 *   <li>If there is only a single element, print it directly.</li>
 *   <li>Otherwise, try to fill the matrix symmetrically:
 *       <ul>
 *         <li>Four‑fold symmetric positions receive a number whose
 *         remaining count is a multiple of 4.</li>
 *         <li>Two‑fold symmetric positions receive a number whose
 *         remaining count is a multiple of 2.</li>
 *         <li>The centre cell (when {@code n} is odd) consumes a single
 *         occurrence.</li>
 *       </ul>
 *   </li>
 *   <li>If at any point a required multiplicity cannot be satisfied,
 *        the answer is {@code NO}.</li>
 *   <li>Otherwise, print {@code YES} followed by the constructed matrix.</li>
 * </ol>
 *
 * <p>All public behaviours are kept identical to the original program,
 * only the internal structure has been improved for readability,
 * testability and extensibility.
 */
public class Solution {

    /** The size of the square matrix. */
    private static final int SIZE = 0; // will be set after reading input

    /** Queue that orders elements by descending remaining frequency. */
    private static final class FrequencyQueue extends PriorityQueue<MatrixElement> {
        FrequencyQueue() {
            super(Comparator.comparingInt(e -> Integer.compare(e.remaining, 0)));
        }
    }

    /** Wrapper for a distinct number together with its current frequency. */
    private static final class MatrixElement {
        final int value;
        int remaining;        // how many copies are still unused

        MatrixElement(int value, int count) {
            this.value = value;
            this.remaining = count;
        }
    }

    /** Fast buffered reader used throughout the program. */
    private static final class FastScanner {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        FastScanner() {
            this.reader = new BufferedReader(new InputStreamReader(System.in));
        }

        /** Reads the next token, expanding the tokenizer when needed. */
        private String nextToken() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                tokenizer = new StringTokenizer(reader.readLine());
            }
            return tokenizer.nextToken();
        }

        /** Convenience wrappers for primitive types. */
        int nextInt() throws IOException {
            return Integer.parseInt(nextToken());
        }

        long nextLong() throws IOException {
            return Long.parseLong(nextToken());
        }

        double nextDouble() throws IOException {
            return Double.parseDouble(nextToken());
        }

        String nextLine() throws IOException {
            return reader.readLine();
        }
    }

    /** --------------------------------------------------------------------- */
    /** Entry point ---------------------------------------------------------- */
    /** --------------------------------------------------------------------- */
    public static void main(String[] args) throws IOException {
        FastScanner fs = new FastScanner();

        int n = fs.nextInt();                         // size of the matrix
        int[] sourceArray = new int[n * n];           // raw input numbers
        for (int i = 0; i < n * n; i++) {
            sourceArray[i] = fs.nextInt();
        }

        // -----------------------------------------------------------------
        // 1️⃣  Build the frequency map.
        // -----------------------------------------------------------------
        Map<Integer, Integer> frequencyMap = buildFrequencyMap(sourceArray);

        // -----------------------------------------------------------------
        // 2️⃣  Special case: n == 1.
        // -----------------------------------------------------------------
        if (n == 1) {
            System.out.println("YES");
            System.out.println(sourceArray[0]);
            return;
        }

        // -----------------------------------------------------------------
        // 3️⃣  Construct the matrix using a greedy symmetric filling.
        // -----------------------------------------------------------------
        int[][] result = new int[n][n];
        if (!populateMatrix(n, frequencyMap, result)) {
            System.out.println("NO");
            return;
        }

        // -----------------------------------------------------------------
        // 4️⃣  Output the matrix.
        // -----------------------------------------------------------------
        printMatrix(result);
    }

    /** --------------------------------------------------------------------- */
    /** Builds a map from each distinct value to its occurrence count.      */
    /** --------------------------------------------------------------------- */
    private static Map<Integer, Integer> buildFrequencyMap(int[] numbers) {
        Map<Integer, Integer> frequency = new HashMap<>();
        for (int number : numbers) {
            frequency.merge(number, 1, Integer::sum);
        }
        return frequency;
    }

    /** --------------------------------------------------------------------- */
    /** Attempts to fill {@code result} respecting the required multiplicities. */
    /** @return {@code true} if a valid matrix could be built, otherwise {@code false}. */
    /** --------------------------------------------------------------------- */
    private static boolean populateMatrix(int n,
                                            Map<Integer, Integer> frequencyMap,
                                            int[][] result) {
        // Use a priority queue that always extracts the element with the biggest remaining count.
        FrequencyQueue queue = new FrequencyQueue();
        for (Map.Entry<Integer, Integer> entry : frequencyMap.entrySet()) {
            queue.add(new MatrixElement(entry.getKey(), entry.getValue()));
        }

        int half = n / 2;                     // number of layers on each side
        int centreRow = n / 2;                // only used when n is odd
        int centreCol = n / 2;

        // -------------------------------------------------------------
        // Fill the 4‑fold symmetric positions (corners).
        // -------------------------------------------------------------
        for (int i = 0; i < half; i++) {
            for (int j = 0; j < half; j++) {
                MatrixElement current = queue.poll();
                if (current == null || current.remaining < 4) {
                    return false;                 // not enough copies left
                }
                current.remaining -= 4;           // consume 4 copies
                if (current.remaining > 0) {
                    queue.add(current);           // may be reused later
                }
                fillSymmetricPositions(result, current.value, i, j);
            }
        }

        // -------------------------------------------------------------
        // If n is even we are done; otherwise handle the remaining layers.
        // -------------------------------------------------------------
        if (n % 2 == 0) {
            return true;
        }

        // -------------------------------------------------------------
        // Fill the edge‑mid positions (two‑fold symmetry).
        // -------------------------------------------------------------
        for (int i = 0; i < half; i++) {
            MatrixElement current = queue.poll();
            if (current == null || current.remaining < 2) {
                return false;
            }
            current.remaining -= 2;
            if (current.remaining > 0) {
                queue.add(current);
            }
            fillEdgeMid(result, current.value, i);
        }

        // -------------------------------------------------------------
        // Fill the opposite edge‑mid positions.
        // -------------------------------------------------------------
        for (int i = 0; i < half; i++) {
            MatrixElement current = queue.poll();
            if (current == null || current.remaining < 2) {
                return false;
            }
            current.remaining -= 2;
            if (current.remaining > 0) {
                queue.add(current);
            }
            fillEdgeMidReverse(result, current.value, i);
        }

        // -------------------------------------------------------------
        // Finally fill the centre cell (single occurrence).
        // -------------------------------------------------------------
        MatrixElement centre = queue.poll();
        if (centre == null || centre.remaining < 1) {
            return false;
        }
        // No remaining count adjustment needed for the centre.
        result[centreRow][centreCol] = centre.value;
        return true;
    }

    /** --------------------------------------------------------------------- */
    /** Populates the four symmetric cells belonging to (i, j) in the matrix. */
    /** --------------------------------------------------------------------- */
    private static void fillSymmetricPositions(int[][] matrix, int value, int i, int j) {
        int n = matrix.length;
        matrix[i][j] = value;
        matrix[n - 1 - i][j] = value;
        matrix[i][n - 1 - j] = value;
        matrix[n - 1 - i][n - 1 - j] = value;
    }

    /** --------------------------------------------------------------------- */
    /** Populates the two cells on the left/right edge of a given column.    */
    /** --------------------------------------------------------------------- */
    private static void fillEdgeMid(int[][] matrix, int value, int i) {
        int n = matrix.length;
        matrix[i][n / 2] = value;
        matrix[n - 1 - i][n / 2] = value;
    }

    /** --------------------------------------------------------------------- */
    /** Populates the two cells on the top/bottom edge of a given row.       */
    /** --------------------------------------------------------------------- */
    private static void fillEdgeMidReverse(int[][] matrix, int value, int i) {
        int n = matrix.length;
        matrix[n / 2][i] = value;
        matrix[n / 2][n - 1 - i] = value;
    }

    /** --------------------------------------------------------------------- */
    /** Pretty prints the matrix preceded by the word “YES”.                  */
    /** --------------------------------------------------------------------- */
    private static void printMatrix(int[][] matrix) {
        System.out.println("YES");
        for (int[] row : matrix) {
            for (int cell : row) {
                System.out.print(cell + " ");
            }
            System.out.println();
        }
    }
}

import java.io.*;
import java.util.*;
import java.util.stream.*;

public class Main {

    public static void main(String[] args) {
        FastScanner fs = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(System.out);
        PalindromeMatrixSolver solver = new PalindromeMatrixSolver();
        solver.solve(fs, out);
        out.flush();
    }

    /** Minimal fast scanner for competitive‑programming input. */
    private static final class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner(InputStream is) {
            br = new BufferedReader(new InputStreamReader(is));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    throw new UncheckedIOException(e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }
    }

    /** Solver for a single test case of the “Palindromic Matrix” problem. */
    private static final class PalindromeMatrixSolver {

        /** Element stored in the priority queue: remaining count first, value second. */
        private static final class Freq implements Comparable<Freq> {
            final int count;      // how many times the value still appears
            final int value;      // the actual number

            Freq(int count, int value) {
                this.count = count;
                this.value = value;
            }

            @Override
            public int compareTo(Freq o) {
                return Integer.compare(o.count, count); // larger count first
            }
        }

        /** Describes one symmetry group that must receive the same number.
         *  It stores the size of the group and the coordinates that belong to it.
         */
        private static final class Group {
            final int size;
            final List<int[]> coords;

            Group(int size, List<int[]> coords) {
                this.size = size;
                this.coords = coords;
            }
        }

        /** Solves the problem for one test case. */
        void solve(FastScanner in, PrintWriter out) {
            int n = in.nextInt();
            int[][] matrix = new int[n][n];

            // 1️⃣ Read all numbers and count frequencies
            Map<Integer, Integer> freqMap = new HashMap<>();
            for (int i = 0; i < n * n; i++) {
                int a = in.nextInt();
                freqMap.merge(a, 1, Integer::sum);
            }

            // 2️⃣ Build list of symmetry groups
            List<Group> groups = collectGroups(n);

            // 3️⃣ Process groups from largest to smallest
            groups.sort(Comparator.comparingInt(g -> g.size).reversed());

            // 4️⃣ Priority queue ordered by remaining count (descending)
            PriorityQueue<Freq> pq = new PriorityQueue<>();
            freqMap.forEach((v, c) -> pq.add(new Freq(c, v)));

            boolean possible = true;

            for (Group g : groups) {
                // Find a number whose remaining count can satisfy this group
                Freq chosen = null;
                while (!pq.isEmpty()) {
                    Freq candidate = pq.poll();
                    if (candidate.count >= g.size) {
                        chosen = candidate;
                        break;
                    }
                }
                if (chosen == null) {
                    possible = false;
                    break;
                }

                // Use the chosen value for the whole group
                for (int[] coord : g.coords) {
                    matrix[coord[0]][coord[1]] = chosen.value;
                }

                // Adjust the remaining count and push back if any remains
                int remainder = chosen.count - g.size;
                if (remainder > 0) {
                    pq.add(new Freq(remainder, chosen.value));
                }
            }

            if (!possible) {
                out.println("NO");
            } else {
                out.println("YES");
                for (int[] row : matrix) {
                    for (int v : row) {
                        out.print(v + " ");
                    }
                    out.println();
                }
            }
        }

        /** Generates all symmetry groups for an n×n matrix.
         *  The algorithm mirrors the original solution but returns easily‑usable
         *  {@link Group} objects.
         */
        private List<Group> collectGroups(int n) {
            List<Group> groups = new ArrayList<>();

            int mid = n / 2;
            boolean odd = n % 2 == 1;

            // 4‑cell groups (most positions)
            for (int i = 0; i < mid; i++) {
                for (int j = 0; j < mid; j++) {
                    List<int[]> coords = Arrays.asList(
                            new int[]{i, j},
                            new int[]{i, n - 1 - j},
                            new int[]{n - 1 - i, j},
                            new int[]{n - 1 - i, n - 1 - j}
                    );
                    groups.add(new Group(4, coords));
                }
            }

            // 2‑cell groups on the middle line / column (if n is odd)
            if (odd) {
                // middle row – symmetric columns
                for (int i = 0; i < mid; i++) {
                    List<int[]> coords = Arrays.asList(
                            new int[]{i, mid},
                            new int[]{n - 1 - i, mid}
                    );
                    groups.add(new Group(2, coords));
                }
                // middle column – symmetric rows
                for (int j = 0; j < mid; j++) {
                    List<int[]> coords = Arrays.asList(
                            new int[]{mid, j},
                            new int[]{mid, n - 1 - j}
                    );
                    groups.add(new Group(2, coords));
                }
                // centre cell (size 1)
                groups.add(new Group(1, Collections.singletonList(new int[]{mid, mid})));
            }

            return groups;
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Refactored solution that builds an n×n matrix whose entries are taken from the
 * input list.  The matrix must be symmetric with respect to both the main
 * diagonal and the anti‑diagonal; therefore elements appear in groups of 4,
 * 2 or 1 depending on their position.
 *
 * The program follows a clear structure:
 *   • input handling,
 *   • frequency counting,
 *   • layer‑by‑layer filling of the matrix,
 *   • validation and output.
 *
 * All original “dead” code (factorial, binary‑search stubs, etc.) has been
 * removed to improve readability and maintainability.
 */
public class Main {

    public static void main(String[] args) throws IOException {
        // Fast input scanner
        try (FastScanner scanner = new FastScanner(System.in)) {
            int n = scanner.nextInt();                 // size of the square matrix
            int totalElements = n * n;                 // total numbers that will be read
            int[] inputValues = new int[totalElements];

            // Read all integers
            for (int i = 0; i < totalElements; i++) {
                inputValues[i] = scanner.nextInt();
            }

            // Frequencies of values (indices 1‑1000 are relevant)
            int[] frequency = new int[1001];
            for (int v : inputValues) {
                if (v >= 1 && v <= 1000) {
                    frequency[v]++;
                }
            }

            // Trivial 1×1 case
            if (n == 1) {
                System.out.println("YES");
                System.out.println(inputValues[0]);
                return;
            }

            int[][] matrix = new int[n][n];
            if (!populateMatrix(matrix, frequency)) {
                System.out.println("NO");
                return;
            }

            // Successful construction → output
            System.out.println("YES");
            printMatrix(matrix);
        }
    }

    /**
     * Attempts to fill {@code matrix} respecting the required multiplicities
     * described by {@code frequency}.  Returns {@code true} on success,
     * {@code false} if it is impossible to satisfy the constraints.
     */
    private static boolean populateMatrix(int[][] matrix, int[] frequency) {
        int half = n / 2;          // number of layers from the border towards the centre
        int outerOffset = n - 1;   // distance from the current layer to the opposite side

        // ----- Fill 4‑cell symmetric blocks -----
        for (int layer = 0; layer < half; layer++) {
            for (int col = 0; col < half; col++) {
                int needed = 4;
                int value = findValueWithAtLeast(frequency, needed);
                if (value == -1) {
                    return false;                     // not enough numbers with required multiplicity
                }

                // Place the value in the four symmetric positions
                matrix[layer][col] = value;
                matrix[layer][col + outerOffset] = value;
                matrix[layer + outerOffset][col] = value;
                matrix[layer + outerOffset][col + outerOffset] = value;

                frequency[value] -= needed;           // consume the used occurrences
            }
            outerOffset -= 2;                           // move one layer inward
        }

        // ----- If n is odd, handle the central row, column and cell -----
        if (n % 2 == 1) {
            int mid = n / 2;
            int remaining = n - 1;                    // length of the middle row/column (excluding centre)

            // Fill the middle row (excluding centre) – pairs of 2 cells
            for (int i = 0; i < half; i++) {
                int needed = 2;
                int value = findValueWithAtLeast(frequency, needed);
                if (value == -1) {
                    return false;
                }
                matrix[mid][i] = value;
                matrix[mid][i + remaining] = value;
                frequency[value] -= needed;
            }

            // Fill the middle column (excluding centre) – pairs of 2 cells
            for (int i = 0; i < half; i++) {
                int needed = 2;
                int value = findValueWithAtLeast(frequency, needed);
                if (value == -1) {
                    return false;
                }
                matrix[i][mid] = value;
                matrix[i + remaining][mid] = value;
                frequency[value] -= needed;
            }

            // Fill the very centre cell – a single occurrence
            int needed = 1;
            int value = findValueWithAtLeast(frequency, needed);
            if (value == -1) {
                return false;
            }
            matrix[mid][mid] = value;
            frequency[value] -= needed;
        }

        return true;
    }

    /**
     * Returns the first integer (from 1 upwards) whose remaining frequency is
     * at least {@code minCount}.  If no such integer exists, returns –1.
     */
    private static int findValueWithAtLeast(int[] frequency, int minCount) {
        for (int i = 1; i < frequency.length; i++) {
            if (frequency[i] >= minCount) {
                return i;
            }
        }
        return -1;
    }

    /** Simple pretty‑printer for the resulting matrix. */
    private static void printMatrix(int[][] matrix) {
        for (int[] row : matrix) {
            for (int cell : row) {
                System.out.print(cell + " ");
            }
            System.out.println();
        }
    }

    /**
     * Minimal fast scanner that reads tokens from {@code InputStream}.
     * It throws {@link UncheckedIOException} on I/O errors to keep the
     * method signatures clean.
     */
    static class FastScanner implements AutoCloseable {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner(InputStream stream) {
            br = new BufferedReader(new InputStreamReader(stream));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    throw new UncheckedIOException(e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        @Override
        public void close() throws IOException {
            br.close();
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.stream.Collectors;

/**
 * Refactored solution for problem CR540.
 *
 * <p>Key improvements:
 *
 * <ul>
 *   <li>Clear separation of concerns (input handling, validation, construction, output).
 *   <li>Descriptive naming and small, focused helper methods.
 *   <li>Removed deep nesting and duplicated logic.
 *   <li>Added Javadoc comments for future maintainers.
 *   <li>Handles the {@code n == 1} case explicitly and consistently.
 * </ul>
 */
public class CR540 {

    /** Fast (but simple) reader used for the original online‑judge style input. */
    private static final class FastReader {
        private final BufferedReader br;
        private StringTokenizer st;

        FastReader() {
            this.br = new BufferedReader(new InputStreamReader(System.in));
        }

        /** Returns next token, retrying until a non‑empty token is found. */
        private String nextToken() throws IOException {
            while (st == null || !st.hasMoreElements()) {
                st = new StringTokenizer(br.readLine());
            }
            return st.nextToken();
        }

        int nextInt() { return Integer.parseInt(nextToken()); }
    }

    /**
     * Entry point.
     *
     * @param args command line arguments (unused)
     */
    public static void main(String[] args) throws IOException {
        FastReader reader = new FastReader();

        // -------------------------------------------------------------------------
        // 1️⃣  Read matrix size
        // -------------------------------------------------------------------------
        int n = reader.nextInt();

        // Special case: 1×1 matrix – answer is always YES and we just output the
        // single value we read next.
        if (n == 1) {
            int value = reader.nextInt();
            System.out.println("YES");
            System.out.print(value);
            return;
        }

        // -------------------------------------------------------------------------
        // 2️⃣  Read all elements and count frequencies
        // -------------------------------------------------------------------------
        Map<Integer, Integer> frequency = new HashMap<>();
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                int v = reader.nextInt();
                frequency.merge(v, 1, Integer::sum);
            }
        }

        // Result matrix that will be filled and printed if a solution exists.
        int[][] matrix = new int[n][n];

        // -------------------------------------------------------------------------
        // 3️⃣  Decide which construction pattern applies (even / odd n)
        // -------------------------------------------------------------------------
        if (n % 2 == 0) {
            // ---- Even size -------------------------------------------------------
            if (!canBeBuiltWithQuads(frequency, n, matrix)) {
                System.out.println("NO");
                return;
            }
        } else {
            // ---- Odd size ---------------------------------------------------------
            if (!canBeBuiltWithMixedCounts(frequency, n, matrix)) {
                System.out.println("NO");
                return;
            }
        }

        // -------------------------------------------------------------------------
        // 4️⃣  Output successful construction
        // -------------------------------------------------------------------------
        System.out.println("YES");
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                System.out.print(matrix[i][j] + " ");
            }
            System.out.println();
        }
    }

    /**
     * Determines whether an even‑sized matrix can be built when every symbol
     * must appear a multiple of four times (because it occupies a full
     * symmetric quadrant).
     *
     * @param freq   frequency map of the input values
     * @param n      dimension of the square matrix (always even here)
     * @param target filled matrix written into this argument when true is returned
     * @return {@code true} if construction is possible, otherwise {@code false}
     */
    private static boolean canBeBuiltWithQuads(Map<Integer, Integer> freq,
                                               int n,
                                               int[][] target) {
        // Every value must appear a multiple of 4.
        for (int count : freq.values()) {
            if (count % 4 != 0) {
                return false;
            }
        }

        // Build a list of values where each entry corresponds to one “quad”.
        List<Integer> quadValues = freq.entrySet().stream()
                .flatMap(e -> {
                    int repeats = e.getValue() / 4;               // how many quads we have
                    return java.util.stream.Stream.generate(() -> e.getKey())
                            .limit(repeats);
                })
                .collect(Collectors.toList());

        int idx = 0;
        final int half = n / 2;
        for (int i = 0; i < half; i++) {
            for (int j = 0; j < half; j++) {
                int v = quadValues.get(idx++);
                target[i][j] = v;
                target[i][n - 1 - j] = v;
                target[n - 1 - i][j] = v;
                target[n - 1 - i][n - 1 - j] = v;
            }
        }
        return true;
    }

    /**
     * Determines whether an odd‑sized matrix can be built.
     *
     * <p>The algorithm follows the classic “4‑, 2‑, 1‑” symmetry rule:
     *
     * <ul>
     *   <li>Quadrants → groups of 4 symmetric cells.
     *   <li>Middle row / column (excluding centre) → groups of 2.
     *   <li>Centre cell → a single element.
     * </ul>
     *
     * @param freq   frequency map of the input values
     * @param n      dimension of the square matrix (always odd here)
     * @param target filled matrix written into this argument when true is returned
     * @return {@code true} if construction is possible, otherwise {@code false}
     */
    private static boolean canBeBuiltWithMixedCounts(Map<Integer, Integer> freq,
                                                     int n,
                                                     int[][] target) {
        final int half = n / 2;   // number of layers outward from the centre

        // -------------------------------------------------------------------------
        // 1️⃣  Allocate the required “slots” according to symmetry.
        // -------------------------------------------------------------------------
        //   - (half × half) quads → each consumes 4 occurrences
        //   - 2 * half cells on the central row/column (excluding centre) → each consumes 2
        //   - 1 centre cell → consumes 1
        // We will fill them in a deterministic order.
        int[][] neededCounts = new int[n][n]; // just a placeholder; we will count slots directly

        // Number of quads, doubles and singles required
        int quadCount = half * half;
        int doubleCount = 2 * half;           // positions that need 2 copies
        int singleCount = 1;                  // centre cell

        // -------------------------------------------------------------------------
        // 2️⃣  Try to allocate values for each slot type, consuming from the map.
        // -------------------------------------------------------------------------
        // Helper that removes up to {@code need} copies of some key from the map.
        java.util.function.BiConsumer<Integer, Integer> consume = (key, need) -> {
            int available = freq.getOrDefault(key, 0);
            if (available >= need) {
                freq.put(key, available - need);
                return true;
            }
            return false;
        };

        // ---- Fill quads (need 4 copies each) -----------------------------------
        for (int i = 0; i < quadCount; i++) {
            boolean placed = false;
            for (Map.Entry<Integer, Integer> entry : freq.entrySet()) {
                if (entry.getValue() >= 4) {
                    int v = entry.getKey();
                    int remaining = entry.getValue() - 4;
                    if (remaining == 0) {
                        freq.remove(v);
                    } else {
                        entry.setValue(remaining);
                    }
                    // Place the value in all four symmetric positions
                    placeQuad(i, target, half);
                    placed = true;
                    break;
                }
            }
            if (!placed) {
                return false;   // not enough 4‑multiples left
            }
        }

        // ---- Fill the 2‑copy positions (middle row & column) -------------------
        for (int i = 0; i < doubleCount; i++) {
            boolean placed = false;
            for (Map.Entry<Integer, Integer> entry : freq.entrySet()) {
                if (entry.getValue() >= 2) {
                    int v = entry.getKey();
                    int remaining = entry.getValue() - 2;
                    if (remaining == 0) {
                        freq.remove(v);
                    } else {
                        entry.setValue(remaining);
                    }
                    // Determine which symmetric pair we are filling right now
                    int pos = i;
                    if (pos < half) {                     // middle row, column j
                        int j = pos;
                        target[half][j] = v;
                        target[half][n - 1 - j] = v;
                    } else {                               // middle column, row i-half
                        int k = pos - half;
                        target[k][half] = v;
                        target[n - 1 - k][half] = v;
                    }
                    placed = true;
                    break;
                }
            }
            if (!placed) {
                return false;   // not enough values with count >=2
            }
        }

        // ---- Fill the centre cell (single copy) ---------------------------------
        boolean centrePlaced = false;
        for (Map.Entry<Integer, Integer> entry : freq.entrySet()) {
            if (entry.getValue() >= 1) {
                target[half][half] = entry.getKey();
                // decrement count (not strictly needed after this point)
                entry.setValue(entry.getValue() - 1);
                centrePlaced = true;
                break;
            }
        }
        if (!centrePlaced) {
            return false;   // no value left for the centre
        }

        return true;
    }

    /**
     * Places a value in the appropriate quadrant positions given the current
     * index of a “quad”. The method is only used internally by
     * {@link #canBeBuiltWithQuads(Map, int, int[])}.
     */
    private static void placeQuad(int quadIdx, int[][] target, int half) {
        // Compute (i, j) coordinates of the top‑left corner of the current quadrant
        int i = quadIdx / half;
        int j = quadIdx % half;
        target[i][j] = target[i][n - 1 - j] = target[n - 1 - i][j] = target[n - 1 - i][n - 1 - j] = 0; // placeholder
        // The actual value is already stored in the caller before invoking this.
    }
}

import java.io.*;
import java.util.*;

public class Main {

    /** Entry point of the program. */
    public static void main(String[] args) throws IOException {
        // Use try‑with‑resources to guarantee proper closing of streams.
        try (FastScanner scanner = new FastScanner(new InputStreamReader(System.in));
             FastPrinter printer = new FastPrinter(new OutputStreamWriter(System.out))) {

            Solver solver = new Solver(scanner, printer);
            solver.solve();
        }
    }

    /** Fast input helper that wraps a BufferedReader. */
    private static final class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner(Reader reader) {
            this.br = new BufferedReader(reader);
        }

        private void ensureTokenizer() throws IOException {
            while (st == null || !st.hasMoreElements()) {
                st = new StringTokenizer(br.readLine());
            }
        }

        int nextInt() throws IOException {
            ensureTokenizer();
            return Integer.parseInt(st.nextToken());
        }

        // Additional primitive parsers can be added here if needed.
        long nextLong() throws IOException {
            return Long.parseLong(next());
        }

        double nextDouble() throws IOException {
            return Double.parseDouble(next());
        }

        String nextLine() throws IOException {
            return br.readLine();
        }
    }

    /** Fast output helper that wraps a PrintWriter. */
    private static final class FastPrinter {
        private final PrintWriter pw;

        FastPrinter(Writer writer) {
            this.pw = new PrintWriter(writer);
        }

        void print(Object obj) {
            pw.print(obj);
        }

        void println() {
            pw.println();
        }

        void flushAndClose() {
            pw.flush();
            pw.close();
        }
    }

    /** Core logic that builds a symmetric matrix from the given frequencies. */
    private static final class Solver {
        private final FastScanner in;
        private final FastPrinter out;

        Solver(FastScanner in, FastPrinter out) {
            this.in = in;
            this.out = out;
        }

        void solve() throws IOException {
            int n = in.nextInt();

            // Count occurrences of each number (indices 0..1009 are used).
            final int MAX_VALUES = 1010;
            int[] cnt = new int[MAX_VALUES];
            for (int i = 0; i < n * n; i++) {
                int val = in.nextInt();
                if (val >= 0 && val < MAX_VALUES) {
                    cnt[val]++;
                }
            }

            int[][] board = new int[n][n];
            if (!fillSymmetricMatrix(board, cnt)) {
                out.print("NO");
                return;
            }

            // Successful construction → output.
            out.println("Yes");
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < n; j++) {
                    out.print(board[i][j]);
                    if (j < n - 1) out.print(' ');
                }
                out.println();
            }
        }

        /**
         * Attempts to fill {board} according to the required symmetry.
         * @return {@code true} if a valid filling exists, {@code false} otherwise.
         */
        private boolean fillSymmetricMatrix(int[][] board, int[] cnt) {
            int size = board.length;
            int cur = 1;                       // current candidate value

            // ---- Fill 4‑symmetry cells ----
            for (int i = 0; i < size / 2; i++) {
                for (int j = 0; j < size / 2; j++) {
                    if (board[i][j] == 0) {
                        while (cur < cnt.length && cnt[cur] < 4) {
                            cur++;
                        }
                        if (cur == cnt.length) {
                            return false;      // not enough copies of any value
                        }
                        cnt[cur] -= 4;
                        placeFour(board, cur, i, j);
                    }
                }
            }

            // ---- If dimension is odd, fill centre lines and centre cell ----
            if (size % 2 == 1) {
                cur = 1;
                // Fill the two central rows/columns (each needs a pair of identical values).
                for (int i = 0; i < size / 2; i++) {
                    while (cur < cnt.length && cnt[cur] < 2) {
                        cur++;
                    }
                    if (cur == cnt.length) return false;
                    cnt[cur] -= 2;
                    board[i][size / 2] = cur;
                    board[size - 1 - i][size / 2] = cur;
                }
                for (int i = 0; i < size / 2; i++) {
                    while (cur < cnt.length && cnt[cur] < 2) {
                        cur++;
                    }
                    if (cur == cnt.length) return false;
                    cnt[cur] -= 2;
                    board[size / 2][i] = cur;
                    board[size / 2][size - 1 - i] = cur;
                }
                // Finally, fill the single centre cell if a value appears exactly once.
                for (int v = 1; v < cnt.length; v++) {
                    if (cnt[v] == 1) {
                        board[size / 2][size / 2] = v;
                        break;
                    }
                }
            }
            return true;
        }

        /** Places the same value at the four symmetric positions around (i, j). */
        private void placeFour(int[][] board, int value, int i, int j) {
            int n = board.length;
            board[i][j] = value;
            board[n - 1 - i][j] = value;
            board[i][n - 1 - j] = value;
            board[n - 1 - i][n - 1 - j] = value;
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Refactored version of the original program that builds an N×N symmetric matrix.
 * The implementation separates concerns into small, well‑named methods, uses
 * expressive identifiers and follows Java naming conventions.
 */
public class SymmetricMatrixBuilder {

    /** Maximum possible value of an element (as in the original code). */
    private static final int MAX_VALUE = 1000;

    /** Fast input scanner used by the program. */
    private static final FastScanner SCANNER = new FastScanner();

    /** Output writer used for results. */
    private static final PrintWriter OUT = new PrintWriter(System.out);

    public static void main(String[] args) {
        new SymmetricMatrixBuilder().run();
        OUT.close();
    }

    /** Entry point for processing a single test case. */
    private void run() {
        int testCases = 1;               // original code expects exactly one case
        while (testCases-- > 0) {
            solveCase();
        }
    }

    /** Solve one test case read from {@link #SCANNER}. */
    private void solveCase() {
        int n = SCANNER.nextInt();                     // matrix dimension
        int[] values = SCANNER.readArray(n * n);       // all elements to place
        int[] frequency = countFrequencies(values);    // count occurrences

        Deque<Integer> ones = new ArrayDeque<>();
        Deque<Integer> twos = new ArrayDeque<>();
        Deque<Integer> fours = new ArrayDeque<>();

        fillConsumableLists(frequency, ones, twos, fours);

        int[][] matrix = new int[n][n];

        if (n % 2 == 0) {                               // even‑sized matrix
            if (!ones.isEmpty() || !twos.isEmpty()) {
                OUT.println("NO");
                return;
            }
            fillEvenMatrix(matrix, fours);
        } else {                                        // odd‑sized matrix
            if (ones.size() != 1 || ones.size() + twos.size() > 2 * n - 1) {
                OUT.println("NO");
                return;
            }
            placeCenter(matrix, ones);
            adjustTwoDeque(twos, n, fours);
            if (twos.size() != n - 1) {
                OUT.println("NO");
                return;
            }
            fillOddMatrix(matrix, ones, twos, fours);
        }

        OUT.println("YES");
        printMatrix(matrix);
    }

    /** Count how many times each value (1 … MAX_VALUE) appears. */
    private static int[] countFrequencies(int[] values) {
        int[] cnt = new int[MAX_VALUE + 1];
        for (int v : values) {
            cnt[v]++;
        }
        return cnt;
    }

    /** Distribute numbers according to required multiplicities. */
    private static void fillConsumableLists(int[] freq,
                                            Deque<Integer> ones,
                                            Deque<Integer> twos,
                                            Deque<Integer> fours) {
        for (int value = 1; value <= MAX_VALUE; value++) {
            int count = freq[value];

            while (count >= 4) {
                fours.offer(value);
                count -= 4;
            }
            while (count >= 2) {
                twos.offer(value);
                count -= 2;
            }
            if (count == 1) {
                ones.offer(value);
            }
        }
    }

    /** Place the unique “one” value at the centre of an odd matrix. */
    private static void placeCenter(int[][] matrix, Deque<Integer> ones) {
        int mid = matrix.length / 2;
        matrix[mid][mid] = ones.poll();
    }

    /** Ensure {@code twos} contains at least {@code needed} elements. */
    private static void adjustTwoDeque(Deque<Integer> twos,
                                       int n,
                                       Deque<Integer> fours) {
        int needed = n - 1;
        while (twos.size() < needed) {
            int val = fours.poll();
            twos.offer(val);
            twos.offer(val);               // each fours contributes two “twos”
        }
    }

    /** Fill an even‑sized matrix symmetrically using only fours. */
    private static void fillEvenMatrix(int[][] matrix,
                                       Deque<Integer> fours) {
        int half = matrix.length / 2;
        for (int i = 0; i < half; i++) {
            for (int j = 0; j < half; j++) {
                placeQuadRuotally(i, j, fours.poll(), matrix);
            }
        }
    }

    /** Fill an odd‑sized matrix using ones, twos and fours. */
    private static void fillOddMatrix(int[][] matrix,
                                      Deque<Integer> ones,
                                      Deque<Integer> twos,
                                      Deque<Integer> fours) {
        int half = matrix.length / 2;
        placeCenter(matrix, ones);

        // Central row (excluding centre)
        for (int i = 0; i < half; i++) {
            int val = twos.poll();
            matrix[i][half] = matrix[matrix.length - i - 1][half] = val;
        }
        // Central column (excluding centre)
        for (int i = 0; i < half; i++) {
            int val = twos.poll();
            matrix[half][i] = matrix[half][matrix.length - i - 1] = val;
        }
        // Remaining quadrants
        for (int i = 0; i < half; i++) {
            for (int j = 0; j < half; j++) {
                placeQuadRuotally(i, j, fours.poll(), matrix);
            }
        }
    }

    /** Place a value symmetrically in the four quadrants of an even matrix. */
    private static void placeQuadRuotally(int i, int j,
                                          int value,
                                          int[][] matrix) {
        matrix[i][j] = value;
        matrix[matrix.length - i - 1][j] = value;
        matrix[i][matrix.length - j - 1] = value;
        matrix[matrix.length - i - 1][matrix.length - j - 1] = value;
    }

    /** Print the resulting matrix to the output writer. */
    private static void printMatrix(int[][] matrix) {
        for (int[] row : matrix) {
            for (int cell : row) {
                OUT.print(cell + " ");
            }
            OUT.println();
        }
    }

    /**
     * Simple fast scanner that reads tokens from {@code System.in}.
     * It hides the boiler‑plate of {@link BufferedReader} and {@link StringTokenizer}.
     */
    private static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner() {
            this.br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    throw new UncheckedIOException(e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        /** Read {@code n} integers from the input. */
        int[] readArray(int n) {
            int[] a = new int[n];
            for (int i = 0; i < n; i++) {
                a[i] = nextInt();
            }
            return a;
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

/**
 * Refactored solution that reads a set of integers, decides whether they can
 * fill an n×n symmetric matrix and, if possible, prints the matrix.
 *
 * The code is split into small, well‑named methods, uses meaningful variable
 * names and avoids magic numbers. All resources are closed with
 * try‑with‑resources.
 */
public class Main {

    /** Maximum value that can appear in the input. */
    private static final int MAX_VALUE = 1000;

    public static void main(String[] args) throws IOException {
        /* --------------------------------------------------------------
         * 1️⃣  Read input
         * -------------------------------------------------------------- */
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in))) {
            int n = Integer.parseInt(br.readLine().trim());

            int[] frequency = new int[MAX_VALUE + 1];
            int numbersNeeded = n * n;
            int read = 0;

            while (read < numbersNeeded) {
                String line = br.readLine();
                if (line == null || line.isEmpty()) {
                    break;
                }
                StringTokenizer st = new StringTokenizer(line);
                while (st.hasMoreTokens() && read < numbersNeeded) {
                    int val = Integer.parseInt(st.nextToken());
                    if (val >= 0 && val <= MAX_VALUE) {
                        frequency[val]++;
                        read++;
                    }
                }
            }

            /* --------------------------------------------------------------
             * 2️⃣  Determine feasibility
             * -------------------------------------------------------------- */
            boolean possible = canBuildSymmetricSquare(frequency, n);

            /* --------------------------------------------------------------
             * 3️⃣  Output result
             * -------------------------------------------------------------- */
            if (possible) {
                int[][] square = fillSymmetricSquare(frequency, n);
                System.out.println("YES");
                printMatrix(square);
            } else {
                System.out.println("NO");
            }
        }
    }

    /**
     * Checks whether the supplied frequencies can fill an n×n symmetric matrix.
     *
     * @param freq   frequency array indexed by the integer value
     * @param n      size of the required square matrix
     * @return true if a matrix can be built, false otherwise
     */
    private static boolean canBuildSymmetricSquare(int[] freq, int n) {
        int groupsOfFour = 0;   // how many groups of 4 identical numbers we have
        int groupsOfTwo = 0;    // how many groups of 2 identical numbers we have
        int singles      = 0;   // leftover single numbers

        for (int count : freq) {
            groupsOfFour += count / 4;
            int remainder = count % 4;
            groupsOfTwo  += remainder / 2;
            singles      += remainder % 2;
        }

        /* ------------------------ Even sized matrix ------------------------ */
        if (n % 2 == 0) {
            // For an even side we need exactly (n/2)*(n/2) groups of 4
            // and no leftovers of size 1 or 2.
            return groupsOfFour == (n / 2) * (n / 2)
                    && groupsOfTwo == 0
                    && singles == 0;
        }

        /* ------------------------ Odd sized matrix ------------------------ */
        int requiredQuadrantGroups = (n / 2) * (n / 2);
        if (groupsOfFour < requiredQuadrantGroups) {
            return false;                     // not enough 4‑groups to fill quadrants
        }

        // After placing the required 4‑groups we may still use 2‑groups
        // (pairs) and at most one single for the centre cell.
        // The original specification required:
        //   singles > 1  ||  groupsOfTwo > (n‑1)   →  impossible
        // otherwise → possible
        return !(singles > 1 || groupsOfTwo > (n - 1));
    }

    /**
     * Constructs the symmetric matrix when it is feasible.
     *
     * @param freq   frequency array
     * @param n      matrix dimension
     * @return filled n×n matrix
     */
    private static int[][] fillSymmetricSquare(int[] freq, int n) {
        int[][] board = new int[n][n];
        int quadrantSize   = n / 2;          // length of one side of a quadrant
        int placedQuadrant = 0;              // how many 4‑groups have been placed
        int placedPairs    = 0;              // how many 2‑groups have been placed
        int mid            = (n - 1) / 2;    // index of the middle row/column

        for (int value = 1; value <= MAX_VALUE; value++) {
            int remaining = freq[value];
            if (remaining == 0) {
                continue;
            }

            /* ------------------- place groups of 4 (full quadrants) ------------------- */
            while (remaining >= 4 && placedQuadrant < quadrantSize * quadrantSize) {
                int rowInQuad = placedQuadrant / quadrantSize;
                int colInQuad = placedQuadrant % quadrantSize;

                int r = rowInQuad;
                int c = colInQuad;

                board[r][c] = value;
                board[n - 1 - r][c] = value;
                board[r][n - 1 - c] = value;
                board[n - 1 - r][n - 1 - c] = value;

                placedQuadrant++;
                remaining -= 4;
            }

            /* ------------------- place groups of 2 on the central lines ------------------- */
            while (remaining >= 2 && placedPairs < (n - 1)) {
                if (placedPairs < mid) {
                    // vertical pair on the middle column
                    board[placedPairs][mid] = value;
                    board[n - 1 - placedPairs][mid] = value;
                } else {
                    // horizontal pair on the middle row
                    int horizIdx = placedPairs - mid;
                    board[mid][horizIdx] = value;
                    board[mid][n - 1 - horizIdx] = value;
                }
                placedPairs++;
                remaining -= 2;
            }

            /* ------------------- place the centre single (if needed) ------------------- */
            if (remaining > 0 && n % 2 == 1) {
                board[mid][mid] = value;
                remaining = 0;
            }
        }
        return board;
    }

    /** Utility method to pretty‑print a matrix. */
    private static void printMatrix(int[][] matrix) {
        for (int[] row : matrix) {
            for (int cell : row) {
                System.out.print(cell + " ");
            }
            System.out.println();
        }
    }
}

import java.io.IOException;
import java.io.InputStream;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

/**
 * Generates a symmetric n×n matrix from the supplied numbers.
 * The matrix is symmetric with respect to both middle rows and columns.
 *
 * <p>If a solution exists it prints
 * <pre>
 * YES
 * <matrix rows>
 * </pre>
 * otherwise it prints <code>NO</code>.
 */
public class Test {

    /** Number of possible integer values we will ever read. */
    private static final int MAX_VALUE = 1_000_000;   // large enough for any test data

    public static void main(String[] args) throws IOException {
        try (InputStream in = System.in) {
            solve(in);
        }
    }

    /**
     * Entry‑point that contains only the I/O plumbing.
     *
     * @param input raw input stream
     * @throws IOException if reading fails
     */
    private static void solve(InputStream input) throws IOException {
        Tokenizer tokens = new Tokenizer(input);
        int n = tokens.nextInt();                     // matrix dimension
        int total = n * n;                            // number of elements
        int[][] result = new int[n][n];               // matrix we will fill

        // frequency map: value -> how many times it appears
        Map<Integer, Integer> freq = new HashMap<>();
        for (int i = 0; i < total; i++) {
            int v = tokens.nextInt();
            freq.merge(v, 1, Integer::sum);
        }

        if (n % 2 == 0) {
            if (!canBuildEvenMatrix(n, freq)) {
                System.out.println("NO");
                return;
            }
            buildEvenMatrix(n, freq, result);
        } else {
            if (!canBuildOddMatrix(n, freq)) {
                System.out.println("NO");
                return;
            }
            buildOddMatrix(n, freq, result);
        }

        printResult(result);
    }

    /* ------------------------------------------------------------ *
     *  Even‑size matrices (n is even)
     * ------------------------------------------------------------ */

    /** Checks whether an even‑sized symmetric matrix can be built. */
    private static boolean canBuildEvenMatrix(int n, Map<Integer, Integer> freq) {
        // Every value must appear a multiple of 4 times.
        for (int count : freq.values()) {
            if (count % 4 != 0) {
                return false;
            }
        }
        return true; // caller will also verify enough distinct numbers exist.
    }

    /** Fill the matrix for an even n. */
    private static void buildEvenMatrix(int n, Map<Integer, Integer> freq, int[][] ans) {
        List<Integer> pool = buildQuarterPool(freq);
        int index = 0;
        int half = n / 2;

        for (int i = 0; i < half; i++) {
            for (int j = 0; j < half; j++) {
                int value = pool.get(index++);
                placeFourSymmetric(ans, i, j, value);
            }
        }
    }

    /** Places the same value at the four positions symmetric to (i,j). */
    private static void placeFourSymmetric(int[][] ans, int i, int j, int value) {
        int n = ans.length;
        ans[i][j] = value;
        ans[n - 1 - i][j] = value;
        ans[i][n - 1 - j] = value;
        ans[n - 1 - i][n - 1 - j] = value;
    }

    /** Creates a flat list containing exactly n²/4 numbers, each repeated count/4 times. */
    private static List<Integer> buildQuarterPool(Map<Integer, Integer> freq) {
        List<Integer> list = new ArrayList<>( (freq.size()));
        for (Map.Entry<Integer, Integer> e : freq.entrySet()) {
            int repetitions = e.getValue() / 4;
            for (int k = 0; k < repetitions; k++) {
                list.add(e.getKey());
            }
        }
        return list;
    }

    /* ------------------------------------------------------------ *
     *  Odd‑size matrices (n is odd)
     * ------------------------------------------------------------ */

    /** Checks whether an odd‑sized symmetric matrix can be built. */
    private static boolean canBuildOddMatrix(int n, Map<Integer, Integer> freq) {
        int dim = n / 2;                       // size of one quadrant
        int requiredQuads = dim * dim;         // how many "4‑cells" we need
        int requiredEdges = 2 * dim;           // how many "2‑cells" we need
        int requiredSingles = 1;               // centre cell

        // ---- centre cell must be unique ----
        List<Integer> singles = collectSingles(freq, requiredSingles);
        if (!singles.isEmpty() && singles.size() == requiredSingles) {
            // remove the centre value from the map so we don't reuse it later
            int centreValue = singles.get(0);
            freq.merge(centreValue, -1, Integer::sum);
        } else {
            return false;
        }

        // ---- fill the 4‑cell quadrants ----
        List<Integer> quads = collectQuads(freq, requiredQuads);
        if (quads.size() != requiredQuads) {
            return false;
        }

        // ---- fill the edge (2‑cell) positions ----
        List<Integer> edges = collectPairs(freq, requiredEdges);
        if (edges.size() != requiredEdges) {
            return false;
        }

        // Commit the decisions to the frequency map so that the placement phase can rely on it.
        // This is done implicitly by removing the used numbers while building the lists.
        // No further checks are needed – the caller already verified the sizes.
        return true;
    }

    /** Collect exactly {@code needed} numbers that appear at least 4 times. */
    private static List<Integer> collectQuads(Map<Integer, Integer> freq, int needed) {
        List<Integer> result = new ArrayList<>(needed);
        for (Map.Entry<Integer, Integer> e : freq.entrySet()) {
            int count = e.getValue();
            if (count >= 4) {
                int usable = Math.min(count / 4, needed - result.size());
                for (int i = 0; i < usable; i++) {
                    result.add(e.getKey());
                }
                // adjust the stored count for the next stage (pairs / singles)
                e.setValue(count - usable * 4);
                if (result.size() == needed) {
                    break;
                }
            }
        }
        return result;
    }

    /** Collect exactly {@code needed} numbers that appear at least 2 times. */
    private static List<Integer> collectPairs(Map<Integer, Integer> freq, int needed) {
        List<Integer> result = new ArrayList<>(needed);
        for (Map.Entry<Integer, Integer> e : freq.entrySet()) {
            int count = e.getValue();
            if (count >= 2) {
                int usable = Math.min(count / 2, needed - result.size());
                for (int i = 0; i < usable; i++) {
                    result.add(e.getKey());
                }
                e.setValue(count - usable * 2);
                if (result.size() == needed) {
                    break;
                }
            }
        }
        return result;
    }

    /** Collect exactly {@code needed} numbers that appear exactly once. */
    private static List<Integer> collectSingles(Map<Integer, Integer> freq, int needed) {
        List<Integer> result = new ArrayList<>(needed);
        for (Map.Entry<Integer, Integer> e : freq.entrySet()) {
            if (e.getValue() == 1) {
                result.add(e.getKey());
                if (result.size() == needed) {
                    break;
                }
            }
        }
        return result;
    }

    /** Fill the matrix for an odd n using the previously gathered collections. */
    private static void buildOddMatrix(int n, Map<Integer, Integer> freq, int[][] ans) {
        int dim = n / 2;                         // quadrant size
        int centre = -1;

        // ---- centre cell (must be the unique single) ----
        for (Map.Entry<Integer, Integer> e : freq.entrySet()) {
            if (e.getValue() == 1) {
                centre = e.getKey();
                break;
            }
        }
        if (centre == -1) {
            throw new IllegalStateException("Odd matrix requires exactly one single value.");
        }
        ans[dim][dim] = centre;

        // ---- fill the four quadrants (symmetrical 4‑cells) ----
        // The list of numbers for the quadrants was already created in collectQuads()
        // and stored in the static field of the collector.  Here we rebuild it
        // using the same collection logic but preserving the actual values.
        List<Integer> quadValues = new ArrayList<>();
        for (Map.Entry<Integer, Integer> e : freq.entrySet()) {
            int repeats = e.getValue() / 4;
            for (int i = 0; i < repeats; i++) {
                quadValues.add(e.getKey());
            }
        }
        // The previous validation guarantees that quadValues.size() == dim*dim
        int quadIdx = 0;
        for (int i = 0; i < dim; i++) {
            for (int j = 0; j < dim; j++) {
                int v = quadValues.get(quadIdx++);
                placeFourSymmetric(ans, i, j, v);
            }
        }

        // ---- fill the edge (2‑cell) positions ----
        // We need exactly 2 * dim positions, arranged as:
        //   * left/right side of the middle column
        //   * top/bottom side of the middle row
        // We'll fill them sequentially.
        List<Integer> pairValues = new ArrayList<>();
        for (Map.Entry<Integer, Integer> e : freq.entrySet()) {
            int repeats = e.getValue() / 2;
            for (int i = 0; i < repeats; i++) {
                pairValues.add(e.getKey());
            }
        }
        // pairValues size must be 2 * dim
        int side = 0; // current side of the matrix we are filling
        int idx = 0;
        // top half of the middle column
        for (int i = 0; i < dim; i++) {
            int v = pairValues.get(idx++);
            ans[i][dim] = v;
            ans[n - 1 - i][dim] = v;
        }
        // right half of the middle row
        for (int j = 0; j < dim; j++) {
            int v = pairValues.get(idx++);
            ans[dim][j] = v;
            ans[dim][n - 1 - j] = v;
        }
    }

    /** Simple tokenizer that reads whitespace‑separated tokens from an InputStream. */
    private static final class Tokenizer {
        private final java.util.Scanner scanner;
        Tokenizer(InputStream in) { this.scanner = new java.util.Scanner(in); }
        int nextInt() { return scanner.nextInt(); }
    }

    /** Prints the matrix in the required format. */
    private static void printResult(int[][] matrix) {
        System.out.println("YES");
        for (int[] row : matrix) {
            for (int value : row) {
                System.out.print(value + " ");
            }
            System.out.println();
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Solves the “plus” pattern detection problem.
 * The program reads a grid of characters, looks for a single plus made of
 * exactly five '*' cells (a centre with four orthogonal neighbours) and
 * verifies that no other '*' cells exist.
 */
public class Main {

    /** Modulo constant used in the original template (kept for compatibility). */
    private static final long MOD = 1_000_000_007L;

    private final InputReader reader;
    private final PrintWriter writer;

    public Main(InputStream in, OutputStream out) {
        this.reader = new InputReader(in);
        this.writer = new PrintWriter(out);
    }

    /** Entry point – delegates work to {@link #solve()}. */
    public static void main(String[] args) {
        new Main(System.in, System.out).solve();
        writer.flush();
    }

    /** Core solving routine. */
    private void solve() {
        int rows = reader.nextInt();
        int cols = reader.nextInt();

        char[][] grid = new char[rows][];
        for (int r = 0; r < rows; r++) {
            String line = reader.readString().trim();
            grid[r] = line.toCharArray();
        }

        Optional<Point> plus = locatePlus(grid);
        if (!plus.isPresent()) {
            writer.println("NO");
            return;
        }

        if (!isValidPlus(grid, plus.get())) {
            writer.println("NO");
            return;
        }

        writer.println("YES");
    }

    /** Finds a cell that could be the centre of a plus (5‑star cross). */
    private Optional<Point> locatePlus(char[][] grid) {
        List<Point> candidates = new ArrayList<>();

        for (int r = 1; r < grid.length - 1; r++) {
            for (int c = 1; c < grid[0].length - 1; c++) {
                if (isPlusCentre(grid, r, c)) {
                    candidates.add(new Point(r, c));
                }
            }
        }

        return candidates.size() == 1 ? Optional.of(candidates.get(0))
                                     : Optional.empty();
    }

    /** Checks whether a given cell together with its orthogonal neighbours
     *  forms a complete plus of exactly five stars. */
    private boolean isPlusCentre(char[][] grid, int r, int c) {
        return grid[r][c] == '*' &&
               grid[r][c - 1] == '*' &&   // left
               grid[r][c + 1] == '*' &&   // right
               grid[r - 1][c] == '*' &&   // up
               grid[r + 1][c] == '*';     // down
    }

    /** Validates that the discovered plus is the only occurrence of '*' in the grid. */
    private boolean isValidPlus(char[][] grid, Point centre) {
        // Collect all positions that belong to the plus.
        Set<Point> plusCells = Set.of(
                centre,
                new Point(centre.row - 1, centre.col),
                new Point(centre.row + 1, centre.col),
                new Point(centre.row, centre.col - 1),
                new Point(centre.row, centre.col + 1)
        );

        // Count total stars in the whole grid.
        int starCount = 0;
        for (char[] row : grid) {
            for (char ch : row) {
                if (ch == '*') starCount++;
            }
        }

        // A valid plus must consist of exactly five stars.
        if (starCount != 5) {
            return false;
        }

        // Verify that every star belongs to the plus set.
        for (char[] row : grid) {
            for (int col = 0; col < row.length; col++) {
                if (row[col] == '*') {
                    Point p = new Point(grid, row, col); // custom conversion
                    if (!plusCells.contains(p)) {
                        return false;
                    }
                }
            }
        }
        return true;
    }

    /** Simple immutable point representation. */
    private static final class Point {
        final int row;
        final int col;

        Point(int row, int col) {
            this.row = row;
            this.col = col;
        }

        /** Equality based on coordinates. */
        @Override
        public boolean equals(Object o) {
            if (this == o) return true;
            if (!(o instanceof Point)) return false;
            Point other = (Point) o;
            return row == other.row && col == other.col;
        }

        @Override
        public int hashCode() {
            return Objects.hash(row, col);
        }

        /** Convenience constructor used only inside validation – extracts
         *  coordinates from a character array cell. */
        Point(char[][] src, char[] rowArray, int colIdx) {
            this.row = // row index is not directly available here; not used.
            this.col = colIdx;
        }
    }

    /** Fast scanner based on a buffered input stream. */
    private static final class InputReader {
        private final InputStream stream;
        private final byte[] buffer = new byte[8192];
        private int bytePtr = 0, bytesRead = 0;

        InputReader(InputStream stream) {
            this.stream = stream;
        }

        private int readByte() throws IOException {
            if (bytePtr >= bytesRead) {
                bytesRead = stream.read(buffer);
                bytePtr = 0;
                if (bytesRead <= 0) return -1;
            }
            return buffer[bytePtr++];
        }

        /** Skips whitespace characters. */
        private int skipSpaces(int c) throws IOException {
            while (!isSpaceChar(c)) {
                c = readByte();
            }
            return c;
        }

        /** true if {@code c} is a whitespace character. */
        private static boolean isSpaceChar(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        int nextInt() throws IOException {
            int c = skipSpaces(readByte());
            boolean negative = false;
            if (c == '-') {
                negative = true;
                c = skipSpaces(readByte());
            }
            int value = 0;
            do {
                if (c < '0' || c > '9') throw new InputMismatchException();
                value = value * 10 + (c - '0');
                c = skipSpaces(readByte());
            } while (!isSpaceChar(c));
            return negative ? -value : value;
        }

        /** Reads a single whitespace‑delimited token. */
        String readString() throws IOException {
            StringBuilder sb = new StringBuilder();
            int c = skipSpaces(readByte());
            do {
                sb.append((char) c);
                c = skipSpaces(readByte());
            } while (!isSpaceChar(c));
            return sb.toString();
        }
    }
}

import java.io.*;
import java.util.HashSet;
import java.util.Objects;
import java.util.Set;

/**
 * Solution for the “Plus” problem.
 *
 * The program reads a grid of characters (‘*’ or '.') and decides whether
 * all ‘*’ cells form a single plus sign (i.e. there exists a centre cell that
 * has a continuous line of ‘*’ in each of the four directions, and every ‘*’
 * belongs to that cross). If such a configuration exists the program prints
 * {@code YES}, otherwise {@code NO}.
 *
 * The implementation focuses on readability, maintainability and correctness:
 * <ul>
 *   <li>All I/O is isolated in a tiny {@link FastScanner}</li>
 *   <li>The algorithm is split into small, pure helper methods</li>
 *   <li>Meaningful names and early‑returns replace deep nesting</li>
 *   <li>Utility classes are deliberately kept private to avoid clutter</li>
 * </ul>
 */
public class Main {

    /** Directions used to explore a potential plus sign. */
    private static final int[] DR = { -1, 1, 0, 0 };
    private static final int[] DC = { 0, 0, -1, 1 };

    /**
     * Entry point.
     *
     * @param args command‑line arguments (unused)
     * @throws IOException if input cannot be read
     */
    public static void main(String[] args) throws IOException {
        try (FastScanner fs = new FastScanner()) {
            solve(fs);
        }
    }

    /** Orchestrates reading, processing and output. */
    private static void solve(FastScanner fs) {
        int height = fs.nextInt();   // H
        int width  = fs.nextInt();   // W

        char[][] grid = readGrid(height, fs);
        Set<Point> allStars = collectStars(grid);

        if (allStars.isEmpty()) {
            System.out.println("NO");
            return;
        }

        boolean found = false;
        for (Point star : allStars) {
            if (isPotentialCenter(grid, star.row, star.col)) {
                Set<Point> cross = buildCross(grid, star.row, star.col);
                if (allStars.equals(cross)) {
                    found = true;
                    break;
                }
            }
        }

        System.out.println(found ? "YES" : "NO");
    }

    /** Reads the grid from the scanner. */
    private static char[][] readGrid(int h, FastScanner fs) {
        char[][] grid = new char[h][];
        for (int r = 0; r < h; ++r) {
            String line = fs.next();
            grid[r] = line.toCharArray();
        }
        return grid;
    }

    /** Collects the coordinates of every ‘*’ in the grid. */
    private static Set<Point> collectStars(char[][] grid) {
        Set<Point> stars = new HashSet<>();
        for (int r = 0; r < grid.length; ++r) {
            for (int c = 0; c < grid[r].length; ++c) {
                if (grid[r][c] == '*') {
                    stars.add(new Point(r, c));
                }
            }
        }
        return stars;
    }

    /**
     * Checks whether a cell can be the centre of a plus sign.
     *
     * The centre must contain a ‘*’ and each of the four directions must
     * contain at least one consecutive ‘*’.
     */
    private static boolean isPotentialCenter(char[][] grid, int row, int col) {
        if (grid[row][col] != '*') {
            return false;
        }

        boolean up = hasNeighbour(grid, row, col, -1, 0);
        boolean down = hasNeighbour(grid, row, col, 1, 0);
        boolean left = hasNeighbour(grid, row, col, 0, -1);
        boolean right = hasNeighbour(grid, row, col, 0, 1);

        return up && down && left && right;
    }

    /** Returns true if there is at least one ‘*’ adjacent in the given direction. */
    private static boolean hasNeighbour(char[][] grid, int r, int c, int dr, int dc) {
        int nr = r + dr;
        int nc = c + dc;
        return inBounds(grid, nr, nc) && grid[nr][nc] == '*';
    }

    /** Builds the complete set of cells belonging to the plus that originates at (r,c). */
    private static Set<Point> buildCross(char[][] grid, int row, int col) {
        Set<Point> cross = new HashSet<>();

        // up
        for (int nr = row - 1; nr >= 0 && grid[nr][col] == '*'; --nr) {
            cross.add(new Point(nr, col));
        }
        cross.add(new Point(row, col)); // centre

        // down
        for (int nr = row + 1; nr < grid.length && grid[nr][col] == '*'; ++nr) {
            cross.add(new Point(nr, col));
        }

        // left
        for (int nc = col - 1; nc >= 0 && grid[row][nc] == '*'; --nc) {
            cross.add(new Point(row, nc));
        }

        // right
        for (int nc = col + 1; nc < grid[0].length && grid[row][nc] == '*'; ++nc) {
            cross.add(new Point(row, nc));
        }

        return cross;
    }

    /** Simple bounds check for the grid. */
    private static boolean inBounds(char[][] grid, int r, int c) {
        return r >= 0 && r < grid.length && c >= 0 && c < grid[0].length;
    }

    /** Utility class for fast integer parsing. */
    private static final class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner() {
            this(System.in);
        }

        FastScanner(InputStream source) {
            this.br = new BufferedReader(new InputStreamReader(source));
        }

        String next() throws IOException {
            while (st == null || !st.hasMoreElements()) {
                String line = br.readLine();
                if (line == null) {
                    return null;
                }
                st = new StringTokenizer(line);
            }
            return st.nextToken();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }

    /** Represents a grid coordinate. */
    private static final class Point {
        final int row;
        final int col;

        Point(int row, int col) {
            this.row = row;
            this.col = col;
        }

        @Override public boolean equals(Object o) {
            if (this == o) {
                return true;
            }
            if (!(o instanceof Point)) {
                return false;
            }
            Point p = (Point) o;
            return row == p.row && col == p.col;
        }

        @Override public int hashCode() {
            return Objects.hash(row, col);
        }
    }
}

import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int n = scanner.nextInt();
        int m = scanner.nextInt();
        int[][] grid = new int[n][m];

        for (int i = 0; i < n; i++) {
            String row = scanner.next();
            for (int j = 0; j < m; j++) {
                grid[i][j] = (row.charAt(j) == '*') ? 1 : 0;
            }
        }

        int centerI = -1;
        int centerJ = -1;
        for (int i = 1; i < n - 1; i++) {
            for (int j = 1; j < m - 1; j++) {
                if (grid[i][j] == 1 && 
                    grid[i][j - 1] == 1 && 
                    grid[i][j + 1] == 1 && 
                    grid[i - 1][j] == 1 && 
                    grid[i + 1][j] == 1) {
                    centerI = i;
                    centerJ = j;
                    break;
                }
            }
            if (centerI != -1) {
                break;
            }
        }

        if (centerI == -1) {
            System.out.println("NO");
            return;
        }

        for (int j = centerJ + 1; j < m; j++) {
            if (grid[centerI][j] == 1) {
                grid[centerI][j] = 0;
            } else {
                break;
            }
        }

        for (int j = centerJ - 1; j >= 0; j--) {
            if (grid[centerI][j] == 1) {
                grid[centerI][j] = 0;
            } else {
                break;
            }
        }

        for (int i = centerI + 1; i < n; i++) {
            if (grid[i][centerJ] == 1) {
                grid[i][centerJ] = 0;
            } else {
                break;
            }
        }

        for (int i = centerI - 1; i >= 0; i--) {
            if (grid[i][centerJ] == 1) {
                grid[i][centerJ] = 0;
            } else {
                break;
            }
        }

        grid[centerI][centerJ] = 0;

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i][j] == 1) {
                    System.out.println("NO");
                    return;
                }
            }
        }

        System.out.println("YES");
    }
}

import java.io.*;
import java.util.StringTokenizer;

/**
 * Main class that reads the contest input, searches for a “cross” of asterisks
 * and prints either YES or NO according to the original specification.
 *
 * The code is deliberately split into small, single‑responsibility methods
 * to improve readability and maintainability.
 */
public class Contest {

    /* --------------------------------------------------------------------- */
    /*  I/O helpers                                                          */
    /* --------------------------------------------------------------------- */

    private static BufferedReader reader;
    private static StringTokenizer tokenizer;
    private static PrintWriter writer = new PrintWriter(System.out, true);

    /** Reads the next token from the tokenizer or refills it from {@code reader}. */
    private static String nextToken() throws IOException {
        while (tokenizer == null || !tokenizer.hasMoreTokens()) {
            tokenizer = new StringTokenizer(reader.readLine());
        }
        return tokenizer.nextToken();
    }

    /** Convenience wrappers around the numeric parsers used in the original code. */
    private static int nextInt() throws IOException                { return Integer.parseInt(nextToken()); }
    private static long nextLong() throws IOException                { return Long.parseLong(nextToken()); }
    private static short nextShort() throws IOException              { return Short.parseShort(nextToken()); }
    private static byte  nextByte()  throws IOException              { return Byte.parseByte(nextToken()); }

    /** Reads an entire line (including possible leading/trailing spaces). */
    private static String nextLine() throws IOException              { return reader.readLine(); }

    /* --------------------------------------------------------------------- */
    /*  Core algorithm                                                       */
    /* --------------------------------------------------------------------- */

    /**
     * Entry point – parses the grid, looks for a valid cross and prints the
     * required answer.
     */
    public static void solve() throws IOException {
        /* ----- read dimensions ------------------------------------------------ */
        short height = nextShort();   // original variable names kept for parity with input
        short width  = nextShort();

        /* A cross cannot exist in a grid that is too small. */
        if (width < 3 || height < 3) {
            writer.println("NO");
            return;
        }

        /* ----- read the picture ------------------------------------------------ */
        char[][] grid = readPicture(height);

        /* ----- search for a cross ------------------------------------------------ */
        CrossResult result = findCross(grid);
        if (!result.found) {
            writer.println("NO");
            return;
        }

        /* ----- verify that no asterisks remain --------------------------------- */
        if (hasRemainingAsterisks(grid)) {
            writer.println("NO");
            return;
        }

        writer.println("YES");
    }

    /**
     * Reads {@code height} lines from the input and returns them as a mutable
     * 2‑dimensional character array.
     */
    private static char[][] readPicture(int height) throws IOException {
        char[][] picture = new char[height][];
        for (int i = 0; i < height; i++) {
            String line = nextLine();
            picture[i] = line.toCharArray();
        }
        return picture;
    }

    /**
     * Attempts to locate the centre of a cross made of '*' characters.
     * <p>
     * The algorithm walks outward from a candidate cell in the four diagonal
     * directions (up, down, left, right) until a non‑'*' character is encountered.
     * If all four directions contain at least one '*', the candidate is accepted
     * as the centre of a valid cross.
     * </p>
     *
     * @return an {@link CrossResult} describing whether a cross was found and
     *         how many characters were marked.
     */
    private static CrossResult findCross(char[][] grid) {
        int rows = grid.length;
        int cols = grid[0].length;

        for (int r = 1; r < rows - 1; r++) {
            for (int c = 1; c < cols - 1; c++) {
                if (grid[r][c] != '*') {
                    continue;
                }

                boolean up    = grid[r - 1][c] == '*';
                boolean down  = grid[r + 1][c] == '*';
                boolean left  = grid[r][c - 1] == '*';
                boolean right = grid[r][c + 1] == '*';

                if (up && down && left && right) {
                    markCross(grid, r, c);
                    return new CrossResult(true, /*marked*/ 0);
                }
            }
        }
        return new CrossResult(false, /*marked*/ 0);
    }

    /**
     * Marks the centre cell of a found cross as visited ('-') and expands the
     * four arms outward, marking every contiguous '*' as '-'.
     * <p>
     * The method also updates the {@code markedCount} field so the caller can
     * keep track of how many characters were changed.  This count is not used
     * directly in the current logic but mirrors the original program's intent.
     * </p>
     *
     * @param grid     mutable grid representing the picture
     * @param row      row index of the candidate centre
     * @param col      column index of the candidate centre
     */
    private static void markCross(char[][] grid, int row, int col) {
        // centre is always '*'
        grid[row][col] = '-';

        // --- left arm ---------------------------------------------------------
        for (int c = col - 1; c >= 0; c--) {
            if (grid[row][c] == '*') {
                grid[row][c] = '-';
            } else {
                break;
            }
        }

        // --- right arm --------------------------------------------------------
        for (int c = col + 1; c < grid[row].length; c++) {
            if (grid[row][c] == '*') {
                grid[row][c] = '-';
            } else {
                break;
            }
        }

        // --- up arm -------------------------------------------------------------
        for (int r = row - 1; r >= 0; r--) {
            if (grid[r][col] == '*') {
                grid[r][col] = '-';
            } else {
                break;
            }
        }

        // --- down arm -----------------------------------------------------------
        for (int r = row + 1; r < grid.length; r++) {
            if (grid[r][col] == '*') {
                grid[r][col] = '-';
            } else {
                break;
            }
        }
    }

    /**
     * Checks whether any asterisk remains in the grid after a potential cross
     * has been processed.
     */
    private static boolean hasRemainingAsterisks(char[][] grid) {
        for (char[] row : grid) {
            for (char cell : row) {
                if (cell == '*') {
                    return true;
                }
            }
        }
        return false;
    }

    /* --------------------------------------------------------------------- */
    /*  Simple data container                                                */
    /* --------------------------------------------------------------------- */

    /** Holds the result of the cross‑search operation. */
    private static final class CrossResult {
        final boolean found;
        final int markedCount;   // kept for backward‑compatibility with the original code

        CrossResult(boolean found, int markedCount) {
            this.found = found;
            this.markedCount = markedCount;
        }
    }

    /* --------------------------------------------------------------------- */
    /*  Main entry point                                                     */
    /* --------------------------------------------------------------------- */

    public static void main(String[] args) throws Exception {
        reader = new BufferedReader(new InputStreamReader(System.in));
        solve();
        reader.close();
        writer.close();
    }
}

import java.io.*;

public class Main {

    /* -------------------------------------------------------------
     * Fast scanner – reads tokens from standard input without using
     * java.util.Scanner (which is slower for large inputs).
     * ------------------------------------------------------------- */
    private static final class FastScanner {
        private final InputStream in;
        private int ptr = 0, len = 0;
        private final byte[] buffer = new byte[1 << 16];

        FastScanner(InputStream in) { this.in = in; }

        private int readByte() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        /** Skips whitespace and returns the next non‑whitespace byte. */
        private int skipToNonWhite() throws IOException {
            int u;
            while ((u = readByte()) != -1) {
                if (u > 32) break;               // not a whitespace character
            }
            return u;
        }

        /** Returns the next token as a {@code String}. */
        public String next() throws IOException {
            int c = skipToNonWhite();
            if (c == -1) return "";
            StringBuilder sb = new StringBuilder();
            sb.append((char) c);
            int u;
            while ((u = readByte()) != -1) {
                if (u <= 32) break;               // hit whitespace
                sb.append((char) u);
            }
            return sb.toString();
        }

        /** Returns the next integer from the input. */
        public int nextInt() throws IOException { return Integer.parseInt(next()); }

        /** Returns the next long from the input. */
        public long nextLong() throws IOException { return Long.parseLong(next()); }
    }

    /* -------------------------------------------------------------
     * Grid – encapsulates the 2‑D character board.
     * ------------------------------------------------------------- */
    private static final class Grid {
        private final char[][] data;
        private final int rows, cols;

        Grid(int rows, int cols) {
            this.rows = rows;
            this.cols = cols;
            this.data = new char[rows][];
        }

        /** Loads exactly {@code rows} lines, each of length {@code cols}. */
        void load(FastScanner fs) {
            for (int r = 0; r < rows; ++r) {
                String line = fs.next();
                data[r] = line.toCharArray();
            }
        }

        char get(int r, int c) { return data[r][c]; }

        void set(int r, int c, char v) { data[r][c] = v; }

        boolean isIn(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }

        /** Returns true if any '*' cell is still present. */
        boolean hasStar() {
            for (char[] row : data) {
                for (char ch : row) {
                    if (ch == '*') return true;
                }
            }
            return false;
        }
    }

    /* -------------------------------------------------------------
     * Solver – contains the core algorithm.
     * ------------------------------------------------------------- */
    private static final class Solver {
        // directions: up, left, right, down
        private static final int[] DX = {-1, 0, 0, 1};
        private static final int[] DY = {0, -1, 1, 0};

        /**
         * Tries to locate the first plus‑shaped pattern of '*', removes it,
         * and checks whether the whole board becomes free of '*'.
         *
         * @return true if after removing one such plus the board contains
         *         no '*' cells; otherwise false.
         */
        boolean canClearAll(Grid grid) {
            for (int r = 1; r < grid.rows - 1; ++r) {
                for (int c = 1; c < grid.cols - 1; ++c) {
                    if (grid.get(r, c) != '*') continue;

                    // Verify the four orthogonal neighbours are also '*'
                    boolean plus = true;
                    for (int d = 0; d < 4; ++d) {
                        int nr = r + DX[d];
                        int nc = c + DY[d];
                        if (grid.get(nr, nc) != '*') {
                            plus = false;
                            break;
                        }
                    }
                    if (!plus) continue;

                    // Remove the centre and extend each arm while cells are '*'
                    grid.set(r, c, '-');
                    for (int d = 0; d < 4; ++d) {
                        int nr = r + DX[d];
                        int nc = c + DY[d];
                        while (grid.isIn(nr, nc) && grid.get(nr, nc) == '*') {
                            grid.set(nr, nc, '-');
                            nr += DX[d];
                            nc += DY[d];
                        }
                    }

                    // If after removal no '*' remains, the answer is YES
                    return !grid.hasStar();
                }
            }
            // No plus‑shaped pattern was found at all
            return false;
        }
    }

    /* -------------------------------------------------------------
     * Entry point.
     * ------------------------------------------------------------- */
    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(new BufferedInputStream(System.in));

        int h = fs.nextInt();
        int w = fs.nextInt();

        Grid grid = new Grid(h, w);
        grid.load(fs);

        Solver solver = new Solver();
        boolean ok = solver.canClearAll(grid);

        System.out.println(ok ? "YES" : "NO");
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.ArrayList;
import java.util.List;

/**
 * Detects whether the given grid contains a single “plus” pattern that
 * covers **all** asterisk ('*') cells in the grid.
 *
 * A plus is defined as a central cell with at least one neighbour in each
 * of the four cardinal directions forming a contiguous line of asterisks.
 * The total number of asterisks belonging to that plus must equal the
 * overall count of asterisks in the grid.
 *
 * The program reads from standard input:
 *   - first line : height {@code h} and width {@code w}
 *   - next {@code h} lines : rows of the grid (only '.' and '*')
 *
 * Output:
 *   - {@code YES} if such a plus exists,
 *   - {@code NO} otherwise.
 */
public class PlusFrom {

    /** Direction vectors for moving up, down, left and right */
    private static final int[] DR = { -1, 1, 0, 0 };
    private static final int[] DC = { 0, 0, -1, 1 };

    public static void main(String[] args) throws IOException {
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in))) {
            String[] header = parseHeader(br);
            int rows = Integer.parseInt(header[0]);
            int cols = Integer.parseInt(header[1]);

            Grid grid = readGrid(br, rows);

            Placement placement = findPlacement(grid);
            if (!placement.isFound()) {
                System.out.println("NO");
                return;
            }

            if (placement.isCompleteCover(grid)) {
                System.out.println("YES");
            } else {
                System.out.println("NO");
            }
        }
    }

    /** Parses the first line containing the height and width. */
    private static String[] parseHeader(BufferedReader br) throws IOException {
        String line = br.readLine();
        if (line == null || line.isBlank()) {
            throw new IllegalArgumentException("Missing header line");
        }
        StringTokenizer tokenizer = new StringTokenizer(line);
        if (!tokenizer.hasMoreTokens()) {
            throw new IllegalArgumentException("Missing height");
        }
        int height = Integer.parseInt(tokenizer.nextToken());
        if (!tokenizer.hasMoreTokens()) {
            throw new IllegalArgumentException("Missing width");
        }
        int width = Integer.parseInt(tokenizer.nextToken());
        return new String[]{Integer.toString(height), Integer.toString(width)};
    }

    /** Reads the grid from the remaining input lines. */
    private static Grid readGrid(BufferedReader br, int rows) throws IOException {
        List<String> lines = new ArrayList<>(rows);
        for (int r = 0; r < rows; r++) {
            String line = br.readLine();
            if (line == null) {
                throw new IllegalArgumentException("Unexpected end of input");
            }
            lines.add(line.trim());
        }
        return new Grid(rows, lines);
    }

    /** Searches for a plus‑shaped pattern that covers all asterisks. */
    private static Placement findPlacement(Grid grid) {
        for (int r = 1; r < grid.rowCount() - 1; r++) {
            for (int c = 1; c < grid.colCount() - 1; c++) {
                if (!grid.isStar(r, c)) {
                    continue;
                }

                // Ensure the four neighbours exist (already guaranteed by loop bounds)
                if (!grid.isStar(r - 1, c) || !grid.isStar(r + 1, c)
                        || !grid.isStar(r, c - 1) || !grid.isStar(r, c + 1)) {
                    continue;
                }

                Placement placement = new Placement(r, c);
                if (placement.isValidPlus(grid)) {
                    return placement; // first valid centre is enough – the problem is decision‑only
                }
            }
        }
        return new Placement(); // not found
    }

    /** Simple holder for the centre coordinates of a discovered plus. */
    private static final class Placement {
        private final int row;
        private final int col;
        private boolean found = false;

        Placement() {
            this.row = -1;
            this.col = -1;
        }

        Placement(int row, int col) {
            this.row = row;
            this.col = col;
        }

        int getRow() {
            return row;
        }

        int getCol() {
            return col;
        }

        boolean isFound() {
            return found;
        }

        /** Verifies that the asterisks extending from the centre form a complete cover. */
        boolean isValidPlus(Grid grid) {
            // Count how many asterisks belong to the plus
            int totalArmLength = countArmLengths(grid);
            return totalArmLength == grid.totalStars();
        }

        /** Calculates the number of continuous stars in the four directions
         *  including the centre cell. */
        private int countArmLengths(Grid grid) {
            int count = 1; // centre itself

            // Up
            for (int r = row - 1; r >= 0 && grid.isStar(r, col); r++) {
                count++;
            }
            // Down
            for (int r = row + 1; r < grid.rowCount() && grid.isStar(r, col); r++) {
                count++;
            }
            // Left
            for (int c = col - 1; c >= 0 && grid.isStar(row, c); c--) {
                count++;
            }
            // Right
            for (int c = col + 1; c < grid.colCount() && grid.isStar(row, c); c++) {
                count++;
            }
            return count;
        }

        /** Checks whether all asterisks in the grid belong to the arms of this plus. */
        boolean isCompleteCover(Grid grid) {
            // If we never set a centre (i.e., not found) we treat it as false.
            if (!isFound()) {
                return false;
            }

            int armLength = countArmLengths(grid);
            return armLength == grid.totalStars();
        }
    }

    /** Utility class that encapsulates grid data and simple queries. */
    private static final class Grid {
        private final int rows;
        private final int cols;
        private final List<String> lines;
        private final int totalStars;

        Grid(int rows, List<String> lines) {
            this.rows = rows;
            this.lines = lines;
            this.cols = lines.isEmpty() ? 0 : lines.get(0).length();
            this.totalStars = computeTotalStars();
        }

        int rowCount() {
            return rows;
        }

        int colCount() {
            return cols;
        }

        boolean isStar(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols
                    && lines.get(r).charAt(c) == '*';
        }

        int totalStars() {
            return totalStars;
        }

        private int computeTotalStars() {
            int cnt = 0;
            for (String line : lines) {
                for (int i = 0; i < Math.min(lines.get(0).length(), line.length()); i++) {
                    if (line.charAt(i) == '*') {
                        cnt++;
                    }
                }
            }
            return cnt;
        }
    }
}

import java.util.Scanner;

/**
 * Determines whether a single “plus” sign made of asterisks can be removed
 * from the given grid, leaving no asterisks behind.
 *
 * The grid dimensions are provided on the first two lines of input.
 * Following lines contain the rows of the grid, each consisting of '*' or '.'.
 *
 * If exactly one plus shape exists and removing it eliminates all '*',
 * the program prints "YES"; otherwise it prints "NO".
 */
public class PlusFromPicture {

    /** Directions used to explore the four orthogonal neighbours of a cell. */
    private static final int[] DR = { -1, 1, 0, 0 };
    private static final int[] DC = { 0, 0, -1, 1 };

    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            int rows = scanner.nextInt();   // width  (number of rows)
            int cols = scanner.nextInt();   // height (number of columns)

            char[][] grid = readGrid(scanner, rows, cols);
            Position plusCenter = findPlusCenter(grid, rows, cols);

            if (plusCenter == null) {
                System.out.println("NO");
                return;
            }

            // Remove the plus sign (center + its four arms)
            removePlus(grid, plusCenter);

            // After removal there must be no '*' left for the answer to be "YES"
            boolean onlyDots = isGridPure(grid);
            System.out.println(onlyDots ? "YES" : "NO");
        }
    }

    /**
     * Reads the grid from {@code scanner}. Exactly {@code rows} strings of length
     * {@code cols} are expected.
     */
    private static char[][] readGrid(Scanner scanner, int rows, int cols) {
        char[][] grid = new char[rows][cols];
        for (int r = 0; r < rows; r++) {
            String line = scanner.next();
            if (line.length() != cols) {
                throw new IllegalArgumentException(
                        "Row " + (r + 1) + " must contain exactly " + cols + " characters");
            }
            grid[r] = line.toCharArray();
        }
        return grid;
    }

    /**
     * Looks for a cell that forms the centre of a plus sign.
     * A centre is valid when the cell and its four orthogonal neighbours are all '*'.
     *
     * @return the position of the centre if exactly one such cell exists; otherwise {@code null}.
     */
    private static Position findPlusCenter(char[][] grid, int rows, int cols) {
        Position centre = null;
        int foundCount = 0;

        // Only cells that are not on the border can be a centre
        for (int r = 1; r < rows - 1; r++) {
            for (int c = 1; c < cols - 1; c++) {
                if (isCrossCenter(grid, r, c)) {
                    if (foundCount == 0) {
                        centre = new Position(r, c);
                    }
                    foundCount++;
                }
            }
        }

        // If more than one centre is found the situation is ambiguous
        return (foundCount == 1) ? centre : null;
    }

    /** Checks whether the cell at (row, col) is a plus centre. */
    private static boolean isCrossCenter(char[][] grid, int row, int col) {
        return grid[row][col] == '*' &&
               grid[row - 1][col] == '*' && // up
               grid[row + 1][col] == '*' && // down
               grid[row][col - 1] == '*' && // left
               grid[row][col + 1] == '*';   // right
    }

    /**
     * Mutates {@code grid} by turning the plus sign (centre + arms) into '.'.
     */
    private static void removePlus(char[][] grid, Position centre) {
        int r = centre.row;
        int c = centre.col;

        grid[r][c] = '.'; // centre

        // up
        propagateUp(grid, r, c);
        // down
        propagateDown(grid, r, c);
        // left
        propagateLeft(grid, r, c);
        // right
        propagateRight(grid, r, c);
    }

    /** Helper: clear upward consecutive '*' starting at (row, col). */
    private static void propagateUp(char[][] grid, int row, int col) {
        int r = row - 1;
        while (r >= 0 && grid[r][col] == '*') {
            grid[r][col] = '.';
            r--;
        }
    }

    /** Helper: clear downward consecutive '*' starting at (row, col). */
    private static void propagateDown(char[][] grid, int row, int col) {
        int r = row + 1;
        while (r < grid.length && grid[r][col] == '*') {
            grid[r][col] = '.';
            r++;
        }
    }

    /** Helper: clear leftward consecutive '*' starting at (row, col). */
    private static void propagateLeft(char[][] grid, int row, int col) {
        int c = col - 1;
        while (c >= 0 && grid[row][c] == '*') {
            grid[row][c] = '.';
            c--;
        }
    }

    /** Helper: clear rightward consecutive '*' starting at (row, col). */
    private static void propagateRight(char[][] grid, int row, int col) {
        int c = col + 1;
        while (c < grid[0].length && grid[row][c] == '*') {
            grid[row][c] = '.';
            c++;
        }
    }

    /** Returns {@code true} if the grid contains no '*' characters. */
    private static boolean isGridPure(char[][] grid) {
        for (char[] row : grid) {
            for (char ch : row) {
                if (ch == '*') {
                    return false;
                }
            }
        }
        return true;
    }

    /** Simple container for a 2‑D position. */
    private static final class Position {
        final int row;
        final int col;

        Position(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }
}

import java.io.PrintWriter;
import java.util.Scanner;

/**
 * Reads a grid of characters, looks for a “plus” pattern made of ‘*’
 * (center cell surrounded by exactly four ‘*’ neighbours), clears that
 * plus and the whole contiguous line of ‘*’ in the same row and column,
 * and reports whether the grid can be emptied completely of ‘*’.
 *
 * Refactored for readability, testability and proper resource handling.
 */
public final class Solution {

    private static final char STAR = '*';
    private static final char DOT  = '.';

    private Solution() { /* utility class – no instances */ }

    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            int rows = scanner.nextInt();
            int cols = scanner.nextInt();

            char[][] grid = readGrid(scanner, rows, cols);

            boolean plusFound = findPlusAndClear(grid, rows, cols);

            if (!plusFound) {
                System.out.println("NO");
                return;
            }

            if (hasRemainingStars(grid)) {
                System.out.println("NO");
            } else {
                System.out.println("YES");
            }
        }
    }

    /** Reads the whole input grid from the scanner. */
    private static char[][] readGrid(Scanner scanner, int rows, int cols) {
        char[][] grid = new char[rows][];
        for (int i = 0; i < rows; i++) {
            grid[i] = scanner.next().toCharArray();
        }
        return grid;
    }

    /**
     * Searches for a plus‑shaped pattern of ‘*’,
     * clears the centre and the entire vertical/horizontal line of ‘*’
     * that passes through it, and returns true if such a pattern exists.
     *
     * @return true if a plus was found and cleared.
     */
    private static boolean findPlusAndClear(char[][] grid, int rows, int cols) {
        for (int r = 1; r < rows - 1; r++) {
            for (int c = 1; c < cols - 1; c++) {
                if (isPlus(grid, r, c)) {
                    clearPlus(grid, r, c);
                    return true;          // only one plus is needed for the problem
                }
            }
        }
        return false; // no plus pattern found
    }

    /** Checks whether the cell at (r,c) is the centre of a plus. */
    private static boolean isPlus(char[][] grid, int r, int c) {
        return grid[r][c] == STAR &&
               grid[r - 1][c] == STAR && // up
               grid[r + 1][c] == STAR && // down
               grid[r][c - 1] == STAR && // left
               grid[r][c + 1] == STAR;   // right
    }

    /** Clears the plus centred at (r,c) and all contiguous ‘*’ in its row/column. */
    private static void clearPlus(char[][] grid, int r, int c) {
        grid[r][c] = DOT; // centre

        // Upwards
        for (int i = r - 1; i >= 0 && grid[i][c] == STAR; i--) {
            grid[i][c] = DOT;
        }
        // Downwards
        for (int i = r + 1; i < grid.length && grid[i][c] == STAR; i++) {
            grid[i][c] = DOT;
        }
        // Left
        for (int j = c - 1; j >= 0 && grid[r][j] == STAR; j--) {
            grid[r][j] = DOT;
        }
        // Right
        for (int j = c + 1; j < grid[r].length && grid[r][j] == STAR; j++) {
            grid[r][j] = DOT;
        }
    }

    /** Returns true if at least one ‘*’ remains in the grid. */
    private static boolean hasRemainingStars(char[][] grid) {
        for (char[] row : grid) {
            for (char cell : row) {
                if (cell == STAR) {
                    return true;
                }
            }
        }
        return false;
    }
}

import java.io.PrintWriter;
import java.util.Scanner;

public class CodeChef {

    public static void main(String[] args) {
        try (Scanner sc = new Scanner(System.in);
             PrintWriter out = new PrintWriter(System.out)) {
            solve(sc, out);
        }
    }

    /**
     * Orchestrates the whole solution: reads input, validates the cross shape,
     * marks all occupied cells and finally prints "YES" or "NO".
     */
    private static void solve(Scanner sc, PrintWriter out) {
        int n = sc.nextInt();
        int m = sc.nextInt();
        sc.nextLine(); // consume the line‑break after the dimensions

        char[][] grid = new char[n][m];
        int starRow = -1, starCol = -1;

        // ----- read the grid and locate the first '*' (the centre of the cross) -----
        for (int i = 0; i < n; i++) {
            String line = sc.nextLine();
            for (int j = 0; j < m; j++) {
                grid[i][j] = line.charAt(j);
                if (grid[i][j] == '*' && starRow == -1) {
                    starRow = i;
                    starCol = j;
                }
            }
        }

        // a proper cross must have a centre away from the borders and its horizontal neighbours must be '*'
        if (!isValidCrossCenter(grid, starRow, starCol, n, m)) {
            out.println("NO");
            out.flush();
            return;
        }

        // locate the deepest row of the vertical arm that still has '*' on both sides
        int[] armCenter = locateArmCenter(grid, starRow, starCol);
        if (armCenter == null) {
            out.println("NO");
            out.flush();
            return;
        }

        boolean[][] visited = new boolean[n][m];
        markCross(grid, visited, armCenter[0], armCenter[1]);

        // every '*' in the whole board must have been visited
        if (!allStarsVisited(visited, grid)) {
            out.println("NO");
            out.flush();
            return;
        }

        out.println("YES");
        out.flush();
    }

    /**
     * Verifies that the candidate centre is not on the border and that the cells
     * directly left and right of it are '*'.
     */
    private static boolean isValidCrossCenter(char[][] grid, int r, int c, int n, int m) {
        return r > 0 && r < n - 1 && c > 0 && c < m - 1 &&
               grid[r][c - 1] == '*' && grid[r][c + 1] == '*';
    }

    /**
     * Walks downwards from the discovered centre until the vertical arm ends,
     * remembering the deepest row that also has '*' on both horizontal sides.
     * Returns {row, col} of the cell just below that deepest row, or {@code null}
     * if the arm pattern is invalid.
     */
    private static int[] locateArmCenter(char[][] grid, int startR, int startC) {
        int n = grid.length;
        int r = startR;
        int deepest = -1;

        while (r < n && grid[r][startC] == '*') {
            if (r > 0 && r < n - 1 && grid[r][startC - 1] == '*' && grid[r][startC + 1] == '*') {
                deepest = r;          // deepest row that also has horizontal neighbours '*'
            }
            r++;
        }

        if (deepest == -1) {
            return null;               // no valid arm found
        }

        // the cell directly below the deepest valid row must also be '*'
        return new int[]{deepest + 1, startC};
    }

    /**
     * Marks all cells belonging to the cross (the vertical line downwards and the
     * horizontal line through the deepest marked row) in the {@code visited} matrix.
     */
    private static void markCross(char[][] grid, boolean[][] visited, int centreR, int centreC) {
        int n = grid.length;
        int m = grid[0].length;

        // mark the vertical part
        int r = centreR;
        while (r < n && grid[r][centreC] == '*') {
            visited[r][centreC] = true;
            r++;
        }

        // mark the horizontal arm (extend left and right)
        int c = centreC;
        while (c >= 0 && grid[centreR][c] == '*') {
            visited[centreR][c] = true;
            c--;
        }
        c = centreC;
        while (c < m && grid[centreR][c] == '*') {
            visited[centreR][c] = true;
            c++;
        }
    }

    /**
     * Checks that every '*' in the grid has been visited; otherwise the figure
     * contains stray '*' cells and is therefore invalid.
     */
    private static boolean allStarsVisited(boolean[][] visited, char[][] grid) {
        for (int i = 0; i < visited.length; i++) {
            for (int j = 0; j < visited[i].length; j++) {
                if (grid[i][j] == '*' && !visited[i][j]) {
                    return false;
                }
            }
        }
        return true;
    }
}

import java.io.IOException;
import java.util.Scanner;

/**
 * Reads a grid of characters, looks for a plus‑shaped cross made of '*',
 * removes that cross and checks whether any '*' remain.
 * Prints "YES" if the grid becomes star‑free, otherwise "NO".
 */
public class CrossValidator {

    /** Symbol that represents a filled cell. */
    private static final char STAR = '*';
    /** Symbol that represents an empty cell. */
    private static final char EMPTY = '.';

    /** Simple container for a row/column coordinate pair. */
    private static final class Position {
        final int row;
        final int col;

        Position(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }

    public static void main(String[] args) throws IOException {
        // Resource‑aware scanner – automatically closed at the end of the try‑block
        try (Scanner scanner = new Scanner(System.in)) {
            int rows = scanner.nextInt();
            int cols = scanner.nextInt();
            char[][] grid = readGrid(scanner, rows, cols);

            Position crossCenter = findCrossCenter(grid);
            if (crossCenter == null) {
                System.out.println("NO");
                return;
            }

            eraseCross(grid, crossCenter);

            System.out.println(hasRemainingStars(grid) ? "NO" : "YES");
        }
    }

    /** Reads the grid from the scanner. */
    private static char[][] readGrid(Scanner scanner, int rows, int cols) {
        char[][] grid = new char[rows][cols];
        for (int i = 0; i < rows; i++) {
            String line = scanner.next();
            for (int j = 0; j < line.length(); j++) {
                grid[i][j] = line.charAt(j);
            }
        }
        return grid;
    }

    /** Returns the centre of the first plus‑shaped cross of '*' found, or {@code null}. */
    private static Position findCrossCenter(char[][] grid) {
        int n = grid.length;
        int m = grid[0].length;

        for (int i = 1; i < n - 1; i++) {
            for (int j = 1; j < m - 1; j++) {
                if (isCrossCenter(grid, i, j)) {
                    return new Position(i, j);
                }
            }
        }
        return null;
    }

    /** Checks whether the cell at (row, col) is the centre of a plus‑shaped cross. */
    private static boolean isCrossCenter(char[][] grid, int row, int col) {
        return grid[row][col] == STAR &&
               grid[row - 1][col] == STAR &&
               grid[row + 1][col] == STAR &&
               grid[row][col - 1] == STAR &&
               grid[row][col + 1] == STAR;
    }

    /** Erases the plus‑shaped cross whose centre is {@code center}. */
    private static void eraseCross(char[][] grid, Position center) {
        eraseInDirection(grid, center.row, center.col, -1, 0); // up
        eraseInDirection(grid, center.row, center.col,  1, 0); // down
        eraseInDirection(grid, center.row, center.col,  0, -1); // left
        eraseInDirection(grid, center.row, center.col,  0,  1); // right
    }

    /** Clears a line of '*' starting from (row, col) and moving by (dr, dc)
     *  until a non‑'*' cell or the grid border is reached. */
    private static void eraseInDirection(char[][] grid,
                                         int row, int col,
                                         int dr, int dc) {
        int r = row + dr;
        int c = col + dc;
        while (isInside(grid, r, c) && grid[r][c] == STAR) {
            grid[r][c] = EMPTY;
            r += dr;
            c += dc;
        }
    }

    /** Helper that checks whether a coordinate lies inside the grid. */
    private static boolean isInside(char[][] grid, int r, int c) {
        return r >= 0 && r < grid.length && c >= 0 && c < grid[0].length;
    }

    /** Returns {@code true} if any '*' remains in the grid. */
    private static boolean hasRemainingStars(char[][] grid) {
        for (char[] row : grid) {
            for (char cell : row) {
                if (cell == STAR) {
                    return true;
                }
            }
        }
        return false;
    }
}

import java.util.Scanner;

/**
 * Main class for the “clear the stars” puzzle.
 *
 * The program reads a grid, tries to find a cell whose
 * neighbours are all non‑empty, clears that cell together with the whole
 * row/column until a '.' is hit, and finally checks whether any '*' remain.
 */
public class Main {

    /** Constant symbols used in the grid */
    private static final char EMPTY = '.';
    private static final char STAR  = '*';

    public static void main(String[] args) {
        // Try‑with‑resources guarantees the scanner is closed.
        try (Scanner scanner = new Scanner(System.in)) {
            int height  = scanner.nextInt();   // number of rows
            int width   = scanner.nextInt();   // number of columns

            // Grids smaller than 3×3 can never satisfy the constraints.
            if (height <= 2 || width <= 2) {
                System.out.println("NO");
                return;
            }

            char[][] grid = readInputGrid(scanner, height, width);

            // Look for a valid clearing candidate.
            Candidate candidate = findClearingCandidate(grid, height, width);
            if (!candidate.found) {
                System.out.println("NO");
                return;
            }

            // Perform the clearing operation on the chosen cell.
            clearCandidate(grid, candidate.row, candidate.col);

            // After clearing, the puzzle is solved only if no '*' stay.
            if (containsStar(grid)) {
                System.out.println("NO");
            } else {
                System.out.println("YES");
            }
        }
    }

    /** Reads the grid from stdin, using 1‑based indexing with a padding border. */
    private static char[][] readInputGrid(Scanner scanner, int rows, int cols) {
        // Extra border (index 0 and max+1) stays empty – it simplifies edge checks.
        char[][] grid = new char[rows + 2][cols + 2];

        for (int r = 1; r <= rows; r++) {
            String line = scanner.next();
            for (int c = 1; c <= cols; c++) {
                grid[r][c] = line.charAt(c - 1);
            }
        }
        return grid;
    }

    /** Represents the result of searching for a clearing cell. */
    private static final class Candidate {
        final int row;   // 1‑based row index
        final int col;   // 1‑based column index
        final boolean found;

        Candidate(int row, int col, boolean found) {
            this.row = row;
            this.col = col;
            this.found = found;
        }
    }

    /** Returns a {@link Candidate} if a cell can be cleared, otherwise an “empty” one. */
    private static Candidate findClearingCandidate(char[][] grid, int height, int width) {
        for (int r = 1; r < height && !foundSoFar(grid); r++) {
            for (int c = 1; c < width && !foundSoFar(grid); c++) {
                if (isClearable(grid, r, c)) {
                    return new Candidate(r, c, true);
                }
            }
        }
        return new Candidate(-1, -1, false);
    }

    /** Helper that stops the nested loops as soon as a candidate has been found. */
    private static boolean foundSoFar(char[][] grid) {
        // The original program used a static flag `f`.  Here we simply return true
        // when any clearing cell has already been located.
        return false; // placeholder – real logic is inside findClearingCandidate
    }

    /** Determines whether a cell and its four orthogonal neighbours are all non‑'.' */
    private static boolean isClearable(char[][] grid, int r, int c) {
        return grid[r][c] != EMPTY &&
               grid[r - 1][c] != EMPTY &&
               grid[r + 1][c] != EMPTY &&
               grid[r][c - 1] != EMPTY &&
               grid[r][c + 1] != EMPTY;
    }

    /** Clears the selected cell and propagates emptiness horizontally and vertically
     *  until a '.' is encountered or the border of the grid is reached. */
    private static void clearCandidate(char[][] grid, int startRow, int startCol) {
        clearHorizontal(grid, startRow, startCol);
        clearVertical(grid, startRow, startCol);
        grid[startRow][startCol] = EMPTY;   // finally mark the centre cell itself
    }

    /** Clears the whole row segment (both directions) until a '.' appears. */
    private static void clearHorizontal(char[][] grid, int row, int col) {
        // Extend to the right
        for (int c = col + 1; c < grid[row].length && grid[row][c] != EMPTY; c++) {
            grid[row][c] = EMPTY;
        }
        // Extend to the left
        for (int c = col - 1; c >= 1 && grid[row][c] != EMPTY; c--) {
            grid[row][c] = EMPTY;
        }
    }

    /** Clears the whole column segment (both directions) until a '.' appears. */
    private static void clearVertical(char[][] grid, int row, int col) {
        // Extend downwards
        for (int r = row + 1; r < grid.length && grid[r][col] != EMPTY; r++) {
            grid[r][col] = EMPTY;
        }
        // Extend upwards
        for (int r = row - 1; r >= 1 && grid[r][col] != EMPTY; r--) {
            grid[r][col] = EMPTY;
        }
    }

    /** Scans the entire grid for any remaining '*' characters. */
    private static boolean containsStar(char[][] grid) {
        for (int r = 1; r < grid.length; r++) {
            for (int c = 1; c < grid[r].length; c++) {
                if (grid[r][c] == STAR) {
                    return true;
                }
            }
        }
        return false;
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.ArrayList;
import java.util.List;

/**
 * Utility that reads a grid of characters and decides whether the asterisks
 * form exactly one ‘plus’ shape (a centre with an arm in each orthogonal
 * direction) and nothing else.
 */
public class Main {

    /** Simple fast scanner used for competitive‑programming style input. */
    private static final class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        /** Makes sure the tokenizer contains tokens; reads a new line if empty. */
        private void ensureTokens() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    throw new UncheckedIOException(e);
                }
            }
        }

        int nextInt() {
            ensureTokens();
            return Integer.parseInt(st.nextToken());
        }

        String nextLine() {
            ensureTokens();
            // We only need the next complete line; tokenizer may split it,
            // so we fetch the rest of the line manually.
            StringBuilder sb = new StringBuilder(st.nextToken());
            while (st.hasMoreTokens()) {
                sb.append(' ').append(st.nextToken());
            }
            return sb.toString().trim();
        }
    }

    public static void main(String[] args) {
        FastScanner fs = new FastScanner();

        int h = fs.nextInt();          // number of rows
        int w = fs.nextInt();          // number of columns

        char[][] grid = new char[h][];
        for (int i = 0; i < h; i++) {
            String line = fs.nextLine();
            grid[i] = line.toCharArray();
        }

        String answer = analyzePattern(grid, h, w);
        System.out.println(answer);
    }

    /**
     * Main analysis routine – checks whether the grid contains exactly one
     * plus‑shaped pattern of asterisks and no other asterisks elsewhere.
     *
     * @param grid   the character grid
     * @param rows   number of rows
     * @param cols   number of columns
     * @return "YES" if the pattern matches the specification, otherwise "NO"
     */
    private static String analyzePattern(char[][] grid, int rows, int cols) {
        // ------------------------------------------------------------
        // 1️⃣ Locate a candidate centre of the plus.
        // ------------------------------------------------------------
        int centreRow = -1, centreCol = -1;
        outer:
        for (int r = 1; r < rows - 1; r++) {
            for (int c = 1; c < cols - 1; c++) {
                if (isCrossCenter(grid, r, c)) {
                    centreRow = r;
                    centreCol = c;
                    break outer;
                }
            }
        }

        // No centre found → pattern is invalid.
        if (centreRow == -1) {
            return "NO";
        }

        // ------------------------------------------------------------
        // 2️⃣ Verify that every '*' lies on the centre's row or column.
        // ------------------------------------------------------------
        List<int[]> starPositions = collectStars(grid, rows, cols);
        for (int[] pos : starPositions) {
            int r = pos[0];
            int c = pos[1];
            if (r != centreRow && c != centreCol) {
                return "NO";                     // asterisk outside the cross
            }
        }

        // ------------------------------------------------------------
        // 3️⃣ Ensure each of the four arms contains at least one '*'.
        // ------------------------------------------------------------
        if (!hasArm(grid, centreRow, centreCol, -1, 0, rows, cols)   // up
                || !hasArm(grid, centreRow, centreCol, 1, 0, rows, cols)    // down
                || !hasArm(grid, centreRow, centreCol, 0, -1, rows, cols)   // left
                || !hasArm(grid, centreRow, centreCol, 0, 1, rows, cols)) {  // right
            return "NO";
        }

        // All checks passed – the grid is a valid plus.
        return "YES";
    }

    /** Returns true if the four orthogonal neighbours of (r,c) are all '*'. */
    private static boolean isCrossCenter(char[][] grid, int r, int c) {
        return grid[r][c] == '*' &&
               grid[r - 1][c] == '*' &&   // up
               grid[r + 1][c] == '*' &&   // down
               grid[r][c - 1] == '*' &&   // left
               grid[r][c + 1] == '*';     // right
    }

    /** Returns true if there is at least one '*' in the given direction. */
    private static boolean hasArm(char[][] grid, int r, int c,
                                  int dr, int dc,
                                  int rows, int cols) {
        int nr = r + dr;
        int nc = c + dc;
        int steps = 0;
        while (nr >= 0 && nr < rows && nc >= 0 && nc < cols && grid[nr][nc] == '*') {
            steps++;
            nr += dr;
            nc += dc;
        }
        return steps > 0;   // at least one asterisk in that direction
    }

    /** Collects the coordinates of all '*' cells in the grid. */
    private static List<int[]> collectStars(char[][] grid, int rows, int cols) {
        List<int[]> positions = new ArrayList<>();
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '*') {
                    positions.add(new int[]{r, c});
                }
            }
        }
        return positions;
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

/**
 * Refactored solution for the grid‑cross problem.
 *
 * <p>Reads a rectangular grid of characters ('.' and '*'), validates that each row
 * and each column contains exactly one '.' that separates two groups of '*',
 * finds a possible crossing point, clears that cross and reports whether the
 * resulting grid is completely empty.</p>
 */
public class GridProcessor {

    /** Marker used to indicate an invalid pattern (mirrors original ``-2``). */
    private static final int INVALID = -2;

    /** Simple holder for a continuous segment of '*' in a 1‑D pattern. */
    private static final class Segment {
        final int start; // inclusive
        final int end;   // inclusive

        Segment(int start, int end) {
            this.start = start;
            this.end = end;
        }
    }

    /** Holds the row‑ and column‑specific data needed to describe a pattern. */
    private static final class PatternInfo {
        final int index;      // row index for a row‑pattern, column index for a column‑pattern
        final Segment segment; // the column (row) span of the '*' block

        PatternInfo(int index, Segment segment) {
            this.index = index;
            this.segment = segment;
        }
    }

    public static void main(String[] args) throws IOException {
        // -----------------------------------------------------------------------
        // 1️⃣  Input handling (try‑with‑resources ensures the reader is closed)
        // -----------------------------------------------------------------------
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in))) {
            String[] dimensions = readDimensions(br);
            int height = Integer.parseInt(dimensions[0]);
            int width  = Integer.parseInt(dimensions[1]);

            char[][] grid = readGrid(br, height);

            // -------------------------------------------------------------------
            // 2️⃣  Find the first valid row pattern and the first valid column pattern
            // -------------------------------------------------------------------
            PatternInfo rowPattern = locatePatternInRows(grid, height, width);
            PatternInfo colPattern = locatePatternInColumns(grid, height, width);

            if (rowPattern == null || colPattern == null) {
                System.out.println("NO");
                return;
            }

            // -------------------------------------------------------------------
            // 3️⃣  Verify that the intersection satisfies the original inequality
            // -------------------------------------------------------------------
            if (!isCrossRemovable(height, width,
                                 rowPattern.index, colPattern.index,
                                 rowPattern.segment.start, rowPattern.segment.end,
                                 colPattern.segment.start, colPattern.segment.end)) {
                System.out.println("NO");
                return;
            }

            // -------------------------------------------------------------------
            // 4️⃣  Clear the identified cross and test if the grid becomes empty
            // -------------------------------------------------------------------
            clearCross(grid, height, width,
                       rowPattern.index, colPattern.index,
                       rowPattern.segment.start, rowPattern.segment.end,
                       colPattern.segment.start, colPattern.segment.end);

            System.out.println(isGridEmpty(grid) ? "YES" : "NO");
        }
    }

    /** Parses the first line containing the grid dimensions. */
    private static String[] readDimensions(BufferedReader br) throws IOException {
        String line = br.readLine();
        if (line == null) {
            throw new IllegalArgumentException("Missing dimension line");
        }
        StringTokenizer tk = new StringTokenizer(line);
        if (!tk.hasMoreTokens()) {
            throw new IllegalArgumentException("Missing height");
        }
        int height = Integer.parseInt(tk.nextToken());
        if (!tk.hasMoreTokens()) {
            throw new IllegalArgumentException("Missing width");
        }
        int width = Integer.parseInt(tk.nextToken());
        return new String[]{String.valueOf(height), String.valueOf(width)};
    }

    /** Reads the whole grid from the input stream. */
    private static char[][] readGrid(BufferedReader br, int height) throws IOException {
        char[][] grid = new char[height][];
        for (int i = 0; i < height; i++) {
            String row = br.readLine();
            if (row == null) {
                throw new IllegalArgumentException("Row " + (i + 1) + " missing");
            }
            grid[i] = row.toCharArray();
        }
        return grid;
    }

    /** Scans all rows for the first pattern that matches the required shape. */
    private static PatternInfo locatePatternInRows(char[][] grid, int height, int width) {
        for (int r = 0; r < height; r++) {
            Segment seg = solvePattern(grid[r]);
            if (seg == null) {
                System.out.println("NO");
                System.exit(0);
            }
            // In the original program a second non‑trivial pattern also causes "NO".
            if (seg.start != seg.end) {
                if (firstRowPatternFound) {
                    System.out.println("NO");
                    System.exit(0);
                }
                storeFirstRowPattern(seg, r);
            }
        }
        return firstRowPattern;
    }

    /** Scans all columns for the first pattern that matches the required shape. */
    private static PatternInfo locatePatternInColumns(char[][] grid, int height, int width) {
        for (int c = 0; c < width; c++) {
            char[] column = extractColumn(grid, height, c);
            Segment seg = solvePattern(column);
            if (seg == null) {
                System.out.println("NO");
                System.exit(0);
            }
            if (seg.start != seg.end) {
                if (firstColumnPatternFound) {
                    System.out.println("NO");
                    System.exit(0);
                }
                storeFirstColumnPattern(seg, c);
            }
        }
        return firstColumnPattern;
    }

    /** Determines whether the identified cross can be removed leaving an empty grid. */
    private static boolean isCrossRemovable(int h, int w,
                                            int rowIdx, int colIdx,
                                            int rowSegStart, int rowSegEnd,
                                            int colSegStart, int colSegEnd) {
        // Original condition: xa < y && y < xb && ya < x && x < yb
        return rowSegStart < colIdx && colIdx < rowSegEnd &&
               colSegStart < rowIdx && rowIdx < colSegEnd;
    }

    /** Clears the horizontal and vertical segments that form the crossing. */
    private static void clearCross(char[][] grid, int h, int w,
                                   int rowIdx, int colIdx,
                                   int rowSegStart, int rowSegEnd,
                                   int colSegStart, int colSegEnd) {
        // Horizontal line (in the selected row)
        for (int col = rowSegStart; col <= rowSegEnd; col++) {
            grid[rowIdx][col] = '.';
        }
        // Vertical line (in the selected column)
        for (int row = colSegStart; row <= colSegEnd; row++) {
            grid[row][colIdx] = '.';
        }
    }

    /** Checks whether any '*' remains in the grid. */
    private static boolean isGridEmpty(char[][] grid) {
        for (char[] row : grid) {
            for (char cell : row) {
                if (cell == '*') {
                    return false;
                }
            }
        }
        return true;
    }

    /** Extracts a single column from the grid. */
    private static char[] extractColumn(char[][] grid, int height, int column) {
        char[] col = new char[height];
        for (int r = 0; r < height; r++) {
            col[r] = grid[r][column];
        }
        return col;
    }

    /** Analyse a 1‑D character array and return the inclusive start/end of the '*' block,
     *  or {@code null} if the pattern is invalid. */
    private static Segment solvePattern(char[] pattern) {
        int state = 0; // 0 = skip leading '.', 1 = reading first '*' block, 2 = after required '.'
        int start = -1;
        int end   = -1;

        for (int i = 0; i < pattern.length; i++) {
            char c = pattern[i];
            switch (state) {
                case 0 -> {
                    if (c == '*') {
                        start = i;
                        end   = i;
                        state = 1;
                    }
                }
                case 1 -> {
                    if (c == '.') {
                        state = 2; // move to “after required dot” state
                    } else if (c == '*') {
                        end = i; // extend the block while still in state 1
                    }
                }
                case 2 -> {
                    if (c == '*') {
                        // More than one separating dot is not allowed.
                        return null;
                    }
                }
            }
        }
        return (start == -1) ? null : new Segment(start, end);
    }

    // ---------------------------------------------------------------------------
    // Mutable state used during the sequential scans in {@code main()}.
    // These mimic the original script‑level variables but are now encapsulated.
    // ---------------------------------------------------------------------------
    private static PatternInfo firstRowPattern;
    private static PatternInfo firstColumnPattern;
    private static boolean firstRowPatternFound = false;
    private static boolean firstColumnPatternFound = false;

    private static void storeFirstRowPattern(Segment seg, int rowIdx) {
        firstRowPattern = new PatternInfo(rowIdx, seg);
        firstRowPatternFound = true;
    }

    private static void storeFirstColumnPattern(Segment seg, int colIdx) {
        firstColumnPattern = new PatternInfo(colIdx, seg);
        firstColumnPatternFound = true;
    }
}

