import java.io.*;
import java.util.StringTokenizer;

/**
 * SymbolValidator checks whether the given grid contains a single,
 * connected “plus‑like” star pattern that uses all the star symbols
 * (‘#’ or any character other than ‘.’).  The algorithm follows the
 * original logic but is reorganized for readability, maintainability
 * and testability.
 */
public class SymbolValidator {

    /** Output stream used for the answer. */
    private static final PrintWriter OUT = new PrintWriter(System.out);

    /** Simple fast scanner that reads whitespace‑separated tokens. */
    private static final FastScanner IN = new FastScanner(System.in);

    public static void main(String[] args) throws IOException {
        /* ----- read dimensions ------------------------------------------------ */
        int height = IN.nextInt();
        int width  = IN.nextInt();

        /* A valid pattern must be at least 3×3. */
        if (height < 3 || width < 3) {
            OUT.println("NO");
            return;
        }

        /* ----- read the grid --------------------------------------------------- */
        int[][] grid = new int[height][];
        int totalStars = 0;          // total number of ‘#’
        int[] rowStars = new int[height]; // stars per row

        for (int r = 0; r < height; r++) {
            String line = IN.next();
            grid[r] = new int[width];
            for (int c = 0; c < width; c++) {
                // '.' → 0 (empty), anything else → 1 (star)
                grid[r][c] = (line.charAt(c) == '.') ? 0 : 1;
                totalStars += grid[r][c];
                rowStars[r] += grid[r][c];
            }
        }

        /* ----- locate a candidate centre row ----------------------------------- */
        int centreRow = -1;
        for (int r = 1; r < height - 1; r++) {
            if (rowStars[r] >= 3) {          // a row with at least three stars can be the centre
                centreRow = r;
                break;
            }
        }
        if (centreRow == -1) {
            OUT.println("NO");
            return;
        }

        /* ----- determine the horizontal segment of stars in the centre row ----- */
        int left  = findFirstStar(centreRow, grid);
        int right = findLastStar (centreRow, grid);
        if (left == -1 || right == -1 || left > right) {
            OUT.println("NO");
            return;
        }

        int horizontalStars = right - left + 1;   // length of the contiguous segment
        // there may be an extra star immediately left of the segment
        if (grid[centreRow][left - 1] == 1) {
            horizontalStars++;
        } else {
            left++;                                 // shift left border rightwards
        }
        if (left > right) {
            OUT.println("NO");
            return;
        }

        /* ----- validate each column of the segment as a vertical line ---------- */
        for (int col = left; col <= right; col++) {
            int up   = countConsecutiveUp(centreRow, col, grid);
            int down = countConsecutiveDown(centreRow, col, grid);
            if (up == 0 || down == 0) {
                continue;   // not a full vertical column – will be rejected later
            }
            int verticalStarsHere = up + down + 1; // centre cell counted once
            // The expected total number of stars if this column is the correct one:
            int expectedTotal = verticalStarsHere + horizontalStars - 1; // centre cell overlaps
            if (expectedTotal == totalStars) {
                OUT.println("YES");
                return;
            }
        }

        /* ----- nothing matched – pattern is invalid --------------------------- */
        OUT.println("NO");
    }

    /** Returns the index of the first star ('1') in the given row, or -1. */
    private static int findFirstStar(int row, int[][] grid) {
        for (int c = 0; c < grid[row].length; c++) {
            if (grid[row][c] == 1) {
                return c;
            }
        }
        return -1;
    }

    /** Returns the index of the last star ('1') in the given row, or -1. */
    private static int findLastStar(int row, int[][] grid) {
        for (int c = grid[row].length - 1; c >= 0; c--) {
            if (grid[row][c] == 1) {
                return c;
            }
        }
        return -1;
    }

    /** Counts consecutive stars upward from (row,col). */
    private static int countConsecutiveUp(int row, int col, int[][] grid) {
        int cnt = 0;
        for (int r = row - 1; r >= 0; r--) {
            if (grid[r][col] == 1) {
                cnt++;
            } else {
                break;
            }
        }
        return cnt;
    }

    /** Counts consecutive stars downward from (row,col). */
    private static int countConsecutiveDown(int row, int col, int[][] grid) {
        int cnt = 0;
        for (int r = row + 1; r < grid.length; r++) {
            if (grid[r][col] == 1) {
                cnt++;
            } else {
                break;
            }
        }
        return cnt;
    }

    /** Minimal scanner that returns the next whitespace‑separated token. */
    private static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner(InputStream stream) {
            br = new BufferedReader(new InputStreamReader(stream));
        }

        String next() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                String line = br.readLine();
                if (line == null) {
                    return null;
                }
                st = new StringTokenizer(line);
            }
            return st.nextToken();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }
}

