    // Direction vectors: right, down, left, up
    private static final int[] DR = {0, 1, 0, -1};
    private static final int[] DC = {1, 0, -1, 0};

    private static int H;                 // number of rows
    private static int W;                 // number of columns
    private static char[][] grid;         // the input grid

    public static void main(String[] args) {
        FastScanner fs = new FastScanner(System.in);
        H = fs.nextInt();
        W = fs.nextInt();
        grid = new char[H][];

        for (int r = 0; r < H; r++) {
            grid[r] = fs.next().toCharArray();
        }

        System.out.println(solve() ? "YES" : "NO");
    }

    /** Determines whether the grid forms a single valid cross of '*'. */
    private static boolean solve() {
        int totalStars = 0;
        int centreRow = -1, centreCol = -1;

        // Scan the whole grid: count stars and look for a unique centre.
        for (int r = 0; r < H; r++) {
            for (int c = 0; c < W; c++) {
                if (grid[r][c] == '*') {
                    totalStars++;
                    if (isPotentialCenter(r, c)) {
                        if (centreRow != -1) { // more than one centre → invalid
                            return false;
                        }
                        centreRow = r;
                        centreCol = c;
                    }
                }
            }
        }

        // No centre found or centre could not be located → invalid.
        if (centreRow == -1) {
            return false;
        }

        // Each of the four directions must contain at least one '*'.
        int armLengthSum = 0;
        for (int d = 0; d < 4; d++) {
            int armLen = countInDirection(centreRow, centreCol, d);
            if (armLen == 0) {
                return false;               // missing arm in this direction
            }
            armLengthSum += armLen;
        }

        // Total '*' cells should be exactly 1 (centre) + all arm cells.
        return totalStars == 1 + armLengthSum;
    }

    /** Checks whether (r,c) can be the centre of a cross. */
    private static boolean isPotentialCenter(int r, int c) {
        if (grid[r][c] != '*') {
            return false;
        }
        for (int d = 0; d < 4; d++) {
            int nr = r + DR[d];
            int nc = c + DC[d];
            if (!inBounds(nr, nc) || grid[nr][nc] != '*') {
                return false;
            }
        }
        return true;
    }

    /** Counts consecutive '*' starting from the neighbour in the given direction. */
    private static int countInDirection(int r, int c, int direction) {
        int nr = r + DR[direction];
        int nc = c + DC[direction];
        if (!inBounds(nr, nc) || grid[nr][nc] != '*') {
            return 0;                     // immediate neighbour is not '*'
        }

        int count = 0;
        int cr = nr;
        int cc = nc;
        while (true) {
            int nrr = cr + DR[direction];
            int ncc = cc + DC[direction];
            if (inBounds(nrr, ncc) && grid[nrr][ncc] == '*') {
                count++;
                cr = nrr;
                cc = ncc;
            } else {
                break;
            }
        }
        return count;
    }

    private static boolean inBounds(int r, int c) {
        return r >= 0 && r < H && c >= 0 && c < W;
    }

    /** Minimal, fast scanner based on BufferedReader and StringTokenizer. */
    private static class FastScanner {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        FastScanner(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
        }

        String next() {
            try {
                while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                    tokenizer = new StringTokenizer(reader.readLine());
                }
            } catch (IOException e) {
                throw new UncheckedIOException(e);
            }
            return tokenizer.nextToken();
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Solution for problem “P1182B – Find the Cross”.
 *
 * The program reads a grid of characters, looks for a ‘+’ formed by ‘*’
 * characters, removes that cross and checks whether any ‘*’ remain.
 * If the whole grid becomes clean it prints “YES”, otherwise “NO”.
 */
public class P1182B {

    /** Fast line‑token scanner – encapsulates all input handling. */
    private static final class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner(BufferedReader br) {
            this.br = br;
        }

        /** Makes sure a tokenizer is ready and returns the next integer. */
        int nextInt() {
            ensureTokenizer();
            return Integer.parseInt(st.nextToken());
        }

        /** Returns the next line (used for whole rows of the grid). */
        String nextLine() {
            try {
                return br.readLine();
            } catch (IOException e) {
                throw new UncheckedIOException(e);
            }
        }

        /** Ensures the tokenizer contains the next token. */
        private void ensureTokenizer() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) {
                        st = null;
                    } else {
                        st = new StringTokenizer(line);
                    }
                } catch (IOException e) {
                    throw new UncheckedIOException(e);
                }
            }
        }
    }

    /** Entry point – delegates all work to {@link #run()}. */
    public static void main(String[] args) throws Exception {
        new P1182B().run();
    }

    /** Core logic of the solution. */
    public void run() throws Exception {
        FastScanner fs = new FastScanner(new BufferedReader(new InputStreamReader(System.in)));
        PrintWriter out = new PrintWriter(new BufferedOutputStream(System.out));

        int height = fs.nextInt();          // number of rows (h)
        int width  = fs.nextInt();          // number of columns (w)

        // Read the whole grid into a char[][] array.
        char[][] grid = new char[height];
        for (int r = 0; r < height; r++) {
            grid[r] = fs.nextLine().toCharArray();
        }

        // Locate the centre of the only valid '+' shape.
        int[] centre = locateCrossCentre(grid, height, width);
        if (centre == null) {
            out.println("NO");
            out.flush();
            return;
        }

        // Remove the discovered cross from the grid.
        clearCross(grid, centre[0], centre[1]);

        // If any '*' is left, the grid does not consist solely of the cross.
        if (hasRemainingStars(grid)) {
            out.println("NO");
        } else {
            out.println("YES");
        }
        out.flush();
    }

    /** Scans the interior of the grid for a ‘+’ pattern of '*' characters. */
    private int[] locateCrossCentre(char[][] grid, int h, int w) {
        for (int r = 1; r < h - 1; r++) {
            for (int c = 1; c < w - 1; c++) {
                if (grid[r][c] == '*' &&
                    grid[r - 1][c] == '*' &&
                    grid[r + 1][c] == '*' &&
                    grid[r][c - 1] == '*' &&
                    grid[r][c + 1] == '*') {
                    return new int[]{r, c};      // centre row, centre column
                }
            }
        }
        return null; // no centre found
    }

    /** Marks the discovered cross with '.' – works outward in the four directions. */
    private void clearCross(char[][] grid, int centreRow, int centreCol) {
        // Intersection point
        grid[centreRow][centreCol] = '.';

        // Upward
        for (int i = 1; centreRow - i >= 0 && grid[centreRow - i][centreCol] == '*'; i++) {
            grid[centreRow - i][centreCol] = '.';
        }
        // Downward
        for (int i = 1; centreRow + i < grid.length && grid[centreRow + i][centreCol] == '*'; i++) {
            grid[centreRow + i][centreCol] = '.';
        }
        // Left
        for (int i = 1; centreCol - i >= 0 && grid[centreRow][centreCol - i] == '*'; i++) {
            grid[centreRow][centreCol - i] = '.';
        }
        // Right
        for (int i = 1; centreCol + i < grid[0].length && grid[centreRow][centreCol + i] == '*'; i++) {
            grid[centreRow][centreCol + i] = '.';
        }
    }

    /** Returns true if any '*' remains in the grid after the cross removal. */
    private boolean hasRemainingStars(char[][] grid) {
        for (char[] row : grid) {
            for (char cell : row) {
                if (cell == '*') {
                    return true;
                }
            }
        }
        return false;
    }
}

import java.util.Scanner;

/**
 * Detects whether the given grid contains exactly one plus sign
 * composed of five '*' characters and no extra '*' cells.
 */
public class PlusPatternDetector {

    /**
     * Determines whether the cell at {@code (row, col)} is the centre of a
     * plus sign that consists of a single '*' in each of the four
     * orthogonal directions.
     *
     * @param grid  the character grid
     * @param row   centre row index
     * @param col   centre column index
     * @param rows  total number of rows
     * @param cols  total number of columns
     * @return {@code true} if the five required cells are '*', otherwise {@code false}
     */
    private static boolean isPlusCenter(char[][] grid, int row, int col,
                                         int rows, int cols) {
        // Guard against out‑of‑bounds accesses (handled by caller)
        return grid[row][col] == '*' &&
               grid[row - 1][col] == '*' && // up
               grid[row + 1][col] == '*' && // down
               grid[row][col - 1] == '*' && // left
               grid[row][col + 1] == '*';   // right
    }

    public static void main(String[] args) {
        // ------------------------------------------------------------
        // Input handling
        // ------------------------------------------------------------
        try (Scanner scanner = new Scanner(System.in)) {
            int rows = scanner.nextInt();
            int cols = scanner.nextInt();

            char[][] grid = new char[rows][cols];
            for (int i = 0; i < rows; i++) {
                String line = scanner.next();
                // Convert the read string into a char[] for the grid row
                System.arraycopy(line.toCharArray(), 0, grid[i], 0, cols);
            }

            // ------------------------------------------------------------
            // Quick validation: a plus occupies exactly five '*' cells.
            // ------------------------------------------------------------
            int starCount = 0;
            for (char[] line : grid) {
                for (char ch : line) {
                    if (ch == '*') {
                        ++starCount;
                    }
                }
            }

            if (starCount != 5) {
                System.out.println("NO");
                return; // No need to search further
            }

            // ------------------------------------------------------------
            // Search for a valid plus centre
            // ------------------------------------------------------------
            // The centre cannot be on the border; it must have neighbours
            // in all four directions.
            for (int i = 1; i < rows - 1; i++) {
                for (int j = 1; j < cols - 1; j++) {
                    if (isPlusCenter(grid, i, j, rows, cols)) {
                        System.out.println("YES");
                        return; // Found a valid plus – we can stop
                    }
                }
            }

            // No centre satisfied the condition
            System.out.println("NO");
        }
    }
}

import java.io.*;
import java.util.StringTokenizer;

/**
 * BPlusFromPicture – Checks whether all asterisks (*) in a grid form a single
 * “plus” shape that occupies the whole set of stars.
 */
public class BPlusFromPicture {

    /* --------------------------------------------------------------------- */
    /* Direction vectors for the four orthogonal neighbours                     */
    private static final int[] DX = {-1, 1, 0, 0};   // up, down, left, right
    private static final int[] DY = {0, 0, -1, 1};

    /* --------------------------------------------------------------------- */
    /* Entry point                                                            */
    public static void main(String[] args) throws IOException {
        /* Use try‑with‑resources to guarantee the reader is closed */
        try (BufferedReader reader = new BufferedReader(
                new InputStreamReader(System.in))) {

            /* Parse the first line – number of rows and columns */
            StringTokenizer tokenizer = new StringTokenizer(reader.readLine());
            int rows = Integer.parseInt(tokenizer.nextToken());
            int cols = Integer.parseInt(tokenizer.nextToken());

            /* Read the matrix and count the total number of stars */
            Grid grid = readGrid(reader, rows, cols);

            /* Detect whether the stars form a single complete plus sign */
            PlusPlacementDetector detector = new PlusPlacementDetector(grid);
            System.out.println(detector.hasSingleCompletePlus()
                    ? "YES"
                    : "NO");
        }
    }

    /* --------------------------------------------------------------------- */
    /** Reads the matrix from {@code reader} and returns a wrapped {@link Grid} */
    private static Grid readGrid(BufferedReader reader, int rows, int cols)
            throws IOException {

        /* Pad the matrix with an outer border of spaces for easier neighbour checks */
        char[][] matrix = new char[rows + 2][cols + 2];
        int totalStars = 0;

        for (int i = 1; i <= rows; i++) {
            char[] line = reader.readLine().toCharArray();
            for (int j = 1; j <= cols; j++) {
                matrix[i][j] = line[j - 1];
                if (matrix[i][j] == '*') {
                    totalStars++;
                }
            }
        }
        return new Grid(matrix, rows, cols, totalStars);
    }

    /* --------------------------------------------------------------------- */
    /** Simple immutable container for the parsed matrix and its statistics */
    private static final class Grid {
        final char[][] matrix;
        final int rows;
        final int cols;
        final int totalStars;

        Grid(char[][] matrix, int rows, int cols, int totalStars) {
            this.matrix = matrix;
            this.rows = rows;
            this.cols = cols;
            this.totalStars = totalStars;
        }
    }

    /* --------------------------------------------------------------------- */
    /** Detects whether exactly one complete plus sign consumes all the stars */
    private static final class PlusPlacementDetector {
        private final Grid grid;

        PlusPlacementDetector(Grid grid) {
            this.grid = grid;
        }

        /** Returns {@code true} if a star has neighbours in all four directions
            and the length of the resulting plus equals the total number of stars. */
        boolean hasSingleCompletePlus() {
            for (int i = 1; i <= grid.rows; i++) {
                for (int j = 1; j <= grid.cols; j++) {
                    if (grid.matrix[i][j] == '*' && isPlusCenter(i, j)) {
                        int plusLength = countPlusLength(i, j);
                        if (plusLength == grid.totalStars) {
                            return true;
                        }
                    }
                }
            }
            return false;
        }

        /** Checks that the four orthogonal neighbours of (i, j) are all '*'. */
        private boolean isPlusCenter(int i, int j) {
            for (int d = 0; d < 4; d++) {
                if (grid.matrix[i + DX[d]][j + DY[d]] != '*') {
                    return false;
                }
            }
            return true;
        }

        /**
         * Counts the total number of stars that belong to the plus shape
         * starting from the centre (i, j). The count includes the centre cell.
         */
        private int countPlusLength(int centerI, int centerJ) {
            int length = 1; // centre itself

            // Upwards
            for (int k = centerI - 1; k >= 1; k--) {
                if (grid.matrix[k][centerJ] == '*') {
                    length++;
                } else {
                    break;
                }
            }

            // Downwards
            for (int k = centerI + 1; k <= grid.rows; k++) {
                if (grid.matrix[k][centerJ] == '*') {
                    length++;
                } else {
                    break;
                }
            }

            // Leftwards
            for (int k = centerJ - 1; k >= 1; k--) {
                if (grid.matrix[centerI][k] == '*') {
                    length++;
                } else {
                    break;
                }
            }

            // Rightwards
            for (int k = centerJ + 1; k <= grid.cols; k++) {
                if (grid.matrix[centerI][k] == '*') {
                    length++;
                } else {
                    break;
                }
            }

            return length;
        }
    }
}

import java.util.Scanner;

/**
 * Determines whether the given picture contains a single “plus” sign that
 * covers *all* filled cells ('*').
 *
 * <p>
 *   The algorithm:
 *   <ul>
 *     <li>Reads the grid dimensions and the grid itself.</li>
 *     <li>Counts the total number of '*' cells.</li>
 *     <li>Searches for a cell that can be the centre of a plus
 *         (the centre and its four orthogonal neighbours are '*').</li>
 *     <li>If such a centre exists, counts how many '*' cells belong to that
 *         plus (horizontal and vertical extensions).</li>
 *     <li>If the counted size equals the total number of '*' cells, prints
 *         "YES", otherwise prints "NO".</li>
 *   </ul>
 * </p>
 */
public class PlusfromPicture {

    /** Grid stored as a 2‑dimensional character array. */
    private static char[][] board;

    /** Number of rows and columns of the grid. */
    private static int rows;
    private static int cols;

    /** Total number of '*' characters in the whole grid. */
    private static int totalStars;

    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            readInput(scanner);
            countTotalStars();
            int shapeSize = findPlusCenter();
            System.out.println(shapeSize == totalStars ? "YES" : "NO");
        }
    }

    /** Reads the dimensions and the grid from {@code scanner}. */
    private static void readInput(Scanner scanner) {
        rows = scanner.nextInt();
        cols = scanner.nextInt();
        board = new char[rows][];
        for (int i = 0; i < rows; i++) {
            String line = scanner.next();
            board[i] = line.toCharArray();
        }
    }

    /** Counts all '*' characters in the grid. */
    private static void countTotalStars() {
        totalStars = 0;
        for (char[] row : board) {
            for (char cell : row) {
                if (cell == '*') {
                    totalStars++;
                }
            }
        }
    }

    /**
     * Looks for a cell that can serve as the centre of a plus sign.
     *
     * @return size of the plus if a valid centre is found whose
     *         extension covers *all* '*' cells; otherwise -1.
     */
    private static int findPlusCenter() {
        // iterate only over possible interior cells (borders cannot be plus centres)
        for (int r = 1; r < rows - 1; r++) {
            for (int c = 1; c < cols - 1; c++) {
                if (isPlusCenter(r, c)) {
                    int shapeSize = countPlusSize(r, c);
                    if (shapeSize == totalStars) {
                        return shapeSize; // success – size already matches totalStars
                    }
                }
            }
        }
        return -1; // no suitable centre found
    }

    /** Checks whether (row, col) is a valid plus centre. */
    private static boolean isPlusCenter(int row, int col) {
        char centre = board[row][col];
        return centre == '*' &&
               board[row - 1][col] == '*' && // up
               board[row + 1][col] == '*' && // down
               board[row][col - 1] == '*' && // left
               board[row][col + 1] == '*';   // right
    }

    /** Calculates how many '*' cells belong to the plus anchored at (row, col). */
    private static int countPlusSize(int row, int col) {
        int size = 1; // the centre itself

        // extend to the right
        for (int c = col + 1; c < cols && board[row][c] == '*'; c++) {
            size++;
        }
        // extend to the left
        for (int c = col - 1; c >= 0 && board[row][c] == '*'; c--) {
            size++;
        }
        // extend downward
        for (int r = row + 1; r < rows && board[r][col] == '*'; r++) {
            size++;
        }
        // extend upward
        for (int r = row - 1; r >= 0 && board[r][col] == '*'; r--) {
            size++;
        }

        return size;
    }
}

import java.util.Scanner;

/**
 * Determines whether a given grid contains a “star” shape that satisfies the
 * problem’s conditions.  If such a shape exists, prints “YES”, otherwise “NO”.
 */
public class Main {

    /** Directions used for counting the four rays that emanate from a candidate centre. */
    private enum Direction {
        UP(-1, 0),
        RIGHT(0, 1),
        DOWN(1, 0),
        LEFT(0, -1);

        private final int rowOffset;
        private final int colOffset;

        Direction(int rowOffset, int colOffset) {
            this.rowOffset = rowOffset;
            this.colOffset = colOffset;
        }

        int getRowOffset() { return rowOffset; }
        int getColOffset() { return colOffset; }
    }

    public static void main(String[] args) {
        try (Scanner sc = new Scanner(System.in)) {
            int rows = sc.nextInt();
            int cols = sc.nextInt();

            char[][] grid = readGrid(sc, rows, cols);

            boolean found = hasValidStar(grid);
            System.out.println(found ? "YES" : "NO");
        }
    }

    /**
     * Reads the grid from the scanner.
     */
    private static char[][] readGrid(Scanner sc, int rows, int cols) {
        char[][] grid = new char[rows][cols];

        for (int r = 0; r < rows; r++) {
            String line = sc.next();
            for (int c = 0; c < cols; c++) {
                grid[r][c] = line.charAt(c);
            }
        }
        return grid;
    }

    /**
     * Returns true if the grid contains a pattern that matches the required
     * “star” configuration.
     */
    private static boolean hasValidStar(char[][] grid) {
        int totalStars = countTotalStars(grid);
        int rows = grid.length;
        int cols = grid[0].length;

        for (int r = 1; r < rows - 1; r++) {
            for (int c = 1; c < cols - 1; c++) {
                if (isCandidateStar(grid, r, c, totalStars)) {
                    return true;
                }
            }
        }
        return false;
    }

    /**
     * Checks whether the cell at (row, col) can be the centre of a valid star.
     * The method verifies the required surrounding cells, ensures the four
     * rays have equal length and sums them up to the total number of stars.
     */
    private static boolean isCandidateStar(char[][] grid, int row, int col,
                                             int totalStars) {
        // centre and three mandatory neighbours must all be '*'
        if (grid[row][col] != '*' ||
                grid[row - 1][col] != '*' || // up
                grid[row][col - 1] != '*' || // left
                grid[row - 1][col - 1] != '*') { // up‑left (used only in original logic)
            return false;
        }

        // bottom and right neighbours must also be '*'
        if (grid[row + 1][col] != '*' || grid[row][col + 1] != '*') {
            return false;
        }

        // The rays must have the same length – the original code does not enforce
        // equality, it only checks that their combined length equals the total
        // number of stars.  We keep that exact semantics.
        int coveredCount = countCoveredStars(grid, row, col);
        return coveredCount == totalStars;
    }

    /**
     * Counts how many '*' are continuously found when moving outward in each
     * of the four Direction vectors from the given centre.
     */
    private static int countCoveredStars(char[][] grid, int centreRow, int centreCol) {
        int covered = 1; // the centre cell itself

        for (Direction dir : Direction.values()) {
            covered += countRayLength(grid, centreRow, centreCol,
                                     dir.getRowOffset(), dir.getColOffset());
        }
        return covered;
    }

    /**
     * Walks outward from (row, col) in the given direction until leaving the
     * grid or encountering a non‑'*' cell, returning the number of '*' traversed.
     */
    private static int countRayLength(char[][] grid, int startRow, int startCol,
                                      int rowOffset, int colOffset) {
        int length = 0;
        int r = startRow;
        int c = startCol;

        while (true) {
            r += rowOffset;
            c += colOffset;

            if (!isInside(grid, r, c) || grid[r][c] != '*') {
                break;
            }
            length++;
        }
        return length;
    }

    /** Simple bounds check for a cell coordinate. */
    private static boolean isInside(char[][] grid, int r, int c) {
        return r >= 0 && r < grid.length && c >= 0 && c < grid[0].length;
    }

    /**
     * Returns the total number of '*' characters in the whole grid.
     */
    private static int countTotalStars(char[][] grid) {
        int count = 0;
        for (char[] row : grid) {
            for (char cell : row) {
                if (cell == '*') {
                    count++;
                }
            }
        }
        return count;
    }
}

import java.util.ArrayList;
import java.util.List;
import java.util.Optional;
import java.util.Scanner;

/**
 * Program that checks whether a given grid contains a single “cross” made of ‘*’
 * characters. All ‘*’ cells must lie on the same row and column as the centre,
 * and those rows/columns must be contiguous (no gaps).
 */
public class Main {

    /** The whole grid stored as a char matrix. */
    private static char[][] grid;
    /** Number of rows and columns. */
    private static int rows, cols;

    /** Centre of the cross (row, column). */
    private static int centreRow, centreCol;

    /** --------------------------------------------------------------------- */
    /** Entry point */
    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            readDimensionsAndGrid(scanner);
            if (!findCentre()) {
                System.out.println("NO");
                return;
            }

            if (!isValidCross()) {
                System.out.println("NO");
                return;
            }

            System.out.println("YES");
        }
    }

    /** --------------------------------------------------------------------- */
    /** Reads the grid size and its contents from {@link Scanner}. */
    private static void readDimensionsAndGrid(Scanner scanner) {
        rows = scanner.nextInt();
        cols = scanner.nextInt();
        grid = new char[rows][cols];

        for (int i = 0; i < rows; i++) {
            String line = scanner.next();
            for (int j = 0; j < cols; j++) {
                grid[i][j] = line.charAt(j);
            }
        }
    }

    /** --------------------------------------------------------------------- */
    /** Looks for a cell that has ‘*’ on all four orthogonal neighbours.
     *  Returns {@code Optional<int[]>} with centre coordinates or empty if none. */
    private static Optional<int[]> findCentre() {
        for (int i = 1; i < rows - 1; i++) {
            for (int j = 1; j < cols - 1; j++) {
                if (hasStarNeighbourhood(i, j)) {
                    centreRow = i;
                    centreCol = j;
                    return Optional.of(new int[]{i, j});
                }
            }
        }
        return Optional.empty();
    }

    /** Helper: checks the five‑cell neighbourhood (centre + four neighbours). */
    private static boolean hasStarNeighbourhood(int r, int c) {
        return grid[r][c] == '*' &&
                grid[r - 1][c] == '*' && // up
                grid[r + 1][c] == '*' && // down
                grid[r][c - 1] == '*' && // left
                grid[r][c + 1] == '*';   // right
    }

    /** --------------------------------------------------------------------- */
    /** Verifies that the whole pattern is a valid cross centred at
     *  {@code centreRow}/{@code centreCol}. */
    private static boolean isValidCross() {
        // 1️⃣ Every ‘*’ must lie either on the centre row or on the centre column.
        if (!allStarsAreOnCrossRowOrColumn()) {
            return false;
        }

        // 2️⃣ On each of the four directions the stars must form a contiguous block.
        return isContiguousInAllFourDirections();
    }

    /** Checks that each ‘*’ is either on the centre row or the centre column. */
    private static boolean allStarsAreOnCrossRowOrColumn() {
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == '*') {
                    if (i != centreRow && j != centreCol) {
                        return false;
                    }
                }
            }
        }
        return true;
    }

    /** Verifies contiguity in the up, down, left and right directions. */
    private static boolean isContiguousInAllFourDirections() {
        // Directions: up, down, left, right
        int[][] deltaRow = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};
        int centre = centreRow;
        int row = centreCol; // column index of centre used for left/right checks

        for (int[] dir : deltaRow) {
            int step = 1;
            boolean seenEmpty = false; // after a '.' we must not see another '*'

            while (true) {
                int nr = centre + dir[0] * step;
                int nc = row + dir[1] * step;

                if (!inBounds(nr, nc)) {
                    break;
                }

                if (grid[nr][nc] == '.') {
                    seenEmpty = true;
                } else if (grid[nr][nc] == '*' && seenEmpty) {
                    // A star appeared after a '.' → not contiguous
                    return false;
                }
                step++;
            }
        }
        return true;
    }

    /** Helper: returns true if the given coordinates are inside the grid. */
    private static boolean inBounds(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }
}

import java.io.*;
import java.util.*;

/**
 * Refactored solution that checks whether a given grid contains a cross
 * composed of '*' characters which covers **all** stars in the grid.
 *
 * The program follows a clear structure:
 *   • Fast input handling (FastScanner)
 *   • Extraction of board dimensions and the board itself
 *   • Counting of total '*' symbols
 *   • Search for a valid cross centred at each interior cell
 *   • Output "YES" if such a cross exists, otherwise "NO"
 */
public class Solution {

    /** Simple fast scanner used to read tokens from stdin. */
    private static class FastScanner {
        private final InputStream stream;
        private final byte[] buffer = new byte[8192];
        private int ptr = 0, length = 0;

        FastScanner(InputStream stream) {
            this.stream = stream;
        }

        /** Reads the next byte, filling the buffer if necessary. */
        private int readByte() throws IOException {
            if (ptr >= length) {
                length = stream.read(buffer);
                ptr = 0;
                if (length <= 0) return -1;
            }
            return buffer[ptr++];
        }

        /** Helper to detect whitespace characters. */
        private boolean isSpaceChar(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        /** Reads the next integer (skipping surrounding whitespace). */
        int nextInt() {
            int c = readByte();
            while (isSpaceChar(c)) c = readByte();

            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = readByte();
            }
            int value = 0;
            do {
                if (c < '0' || c > '9') throw new InputMismatchException();
                value = value * 10 + (c - '0');
                c = readByte();
            } while (!isSpaceChar(c));
            return value * sign;
        }

        /** Reads the next token (characters up to whitespace). */
        String readToken() {
            int c = readByte();
            while (isSpaceChar(c)) c = readByte();

            StringBuilder sb = new StringBuilder();
            do {
                sb.append((char) c);
                c = readByte();
            } while (!isSpaceChar(c));
            return sb.toString();
        }

        /** Reads a complete line (terminated by \n, \r or EOF). */
        String readLine() {
            StringBuilder sb = new StringBuilder();
            int c = readByte();
            while (isSpaceChar(c)) c = readByte();

            do {
                sb.append((char) c);
                c = readByte();
            } while (!isEndOfLine(c));
            return sb.toString();
        }

        private boolean isEndOfLine(int c) {
            return c == '\n' || c == '\r' || c == -1;
        }
    }

    /** Determines whether the board contains a cross that uses every '*'. */
    private static boolean containsValidCross(char[][] grid, int totalStars) {
        int n = grid.length;
        int m = grid[0].length;

        // Examine each interior cell as a potential centre of the cross.
        for (int i = 1; i < n - 1; i++) {
            for (int j = 1; j < m - 1; j++) {
                if (grid[i][j] != '*') continue;

                // Count consecutive '*' in the four directions.
                int up = 0;
                for (int x = i - 1; x >= 0 && grid[x][j] == '*'; x--) up++;

                int down = 0;
                for (int x = i + 1; x < n && grid[x][j] == '*'; x++) down++;

                int left = 0;
                for (int y = j - 1; y >= 0 && grid[i][y] == '*'; y--) left++;

                int right = 0;
                for (int y = j + 1; y < m && grid[i][y] == '*'; y++) right++;

                // Every direction must contain at least one '*'
                if (up == 0 || down == 0 || left == 0 || right == 0) continue;

                // Total stars covered by this cross (center counted once).
                int crossStars = up + down + left + right + 1;
                if (crossStars == totalStars) {
                    return true; // Found a valid cross.
                }
            }
        }
        return false;
    }

    /** Entry point of the program. */
    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(System.out, true);

        // ----- Input -----
        int n = fs.nextInt();   // number of rows
        int m = fs.nextInt();   // number of columns

        // Degenerate 1×1 board can never contain a valid cross.
        if (n == 1 && m == 1) {
            out.println("NO");
            return;
        }

        char[][] board = new char[n][];
        int totalStars = 0;

        for (int i = 0; i < n; i++) {
            // Each row is read as a single token (no spaces inside the row).
            String row = fs.readToken();
            board[i] = row.toCharArray();
            for (char cell : board[i]) {
                if (cell == '*') totalStars++;
            }
        }

        // No stars → impossible to form a cross.
        if (totalStars == 0) {
            out.println("NO");
            return;
        }

        // ----- Core logic -----
        boolean hasCross = containsValidCross(board, totalStars);
        out.println(hasCross ? "YES" : "NO");
    }
}

import java.util.List;
import java.util.Scanner;

/**
 * Reads a grid of characters and determines whether all '*' characters can be
 * arranged in a single "+" (plus) shape.
 *
 * A "+" shape is defined as follows:
 * <ul>
 *   <li>The centre cell contains a '*'.</li>
 *   <li>All other '*'s lie on the same row or column as the centre.</li>
 *   <li>In each of the four directions (up, down, left, right) the '*'s are
 *       contiguous starting from the centre.</li>
 *   <li>The total number of '*'s equals the sum of the contiguous stars in
 *       the four directions plus the centre cell.</li>
 * </ul>
 *
 * If such a centre exists the program prints {@code YES}, otherwise {@code NO}.
 */
public class Main {

    /** Reads the whole input and returns the grid as a list of rows. */
    private static List<String> readGrid(Scanner scanner) {
        int rows = scanner.nextInt();
        int cols = scanner.nextInt();
        scanner.nextLine();                     // consume newline
        List<String> grid = new java.util.ArrayList<>(rows);
        for (int r = 0; r < rows; ++r) {
            grid.add(scanner.nextLine().trim());
        }
        return grid;
    }

    /** Returns the total number of '*' characters in the grid. */
    private static int countTotalStars(List<String> grid) {
        int cnt = 0;
        for (String row : grid) {
            cnt += row.chars().filter(ch -> ch == '*').count();
        }
        return cnt;
    }

    /** Counts consecutive '*' characters starting from (r,c) moving in (dr,dc). */
    private static int countInDirection(List<String> grid, int r, int c, int dr, int dc) {
        int count = 0;
        int nr = r + dr;
        int nc = c + dc;
        while (isInBounds(grid, nr, nc) && grid.get(nr).charAt(nc) == '*') {
            ++count;
            nr += dr;
            nc += dc;
        }
        return count;
    }

    /** Checks whether the supplied coordinates are inside the grid. */
    private static boolean isInBounds(List<String> grid, int r, int c) {
        return r >= 0 && r < grid.size() && c >= 0 && c < grid.get(r).length();
    }

    /** Determines whether a "+" shape containing all '*' cells exists. */
    private static boolean existsPlusShape(List<String> grid) {
        int totalStars = countTotalStars(grid);

        for (int r = 0; r < grid.size(); ++r) {
            String row = grid.get(r);
            for (int c = 0; c < row.length(); ++c) {
                if (row.charAt(c) != '*') {
                    continue;
                }

                // stars in the four directions (excluding the centre)
                int up    = countInDirection(grid, r - 1, c, -1, 0);
                int down  = countInDirection(grid, r + 1, c,  1, 0);
                int left  = countInDirection(grid, r,     c - 1, 0, -1);
                int right = countInDirection(grid, r,     c + 1, 0,  1);

                if (up + down + left + right + 1 == totalStars) {
                    return true;    // found a valid centre
                }
            }
        }
        return false;   // no suitable centre found
    }

    /** Entry point of the program. */
    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            List<String> grid = readGrid(scanner);
            System.out.println(existsPlusShape(grid) ? "YES" : "NO");
        }
    }
}

/**
 * Refactored version of the BPlusFromPicture solution.
 *
 * The program reads a grid of characters ('.' or '*'), looks for a plus‑shaped
 * pattern of '*' cells, verifies that all '*' cells belong to that plus and
 * prints "YES" if the picture matches the specification, otherwise "NO".
 *
 * The refactor focuses on readability, maintainability and correctness:
 *   – Clear separation of concerns (input, processing, output)
 *   – Meaningful method and variable names
 *   – Defensive programming (early returns, immutable data where possible)
 *   – Removal of duplication and unnecessary code
 *   – Use of Java‑8 language features where appropriate
 */
public class Main {

    public static void main(String[] args) {
        // Input and output streams
        java.io.InputStream in = System.in;
        java.io.PrintWriter out = new java.io.PrintWriter(System.out, true);

        // Reader utilities
        InputReader reader = new InputReader(in);

        // Solver instance
        BPlusFromPicture solver = new BPlusFromPicture();

        // Process exactly one test case (the original program also supports a
        // single test case, so we pass 1 as the testNumber argument)
        solver.solve(1, reader, out);
    }

    /**
     * Core logic that solves a single test case.
     *
     * @param testNumber dummy argument kept for API compatibility with the
     *                  original code; it is not used.
     * @param reader     Input reader that supplies the grid description.
     * @param out        PrintWriter used for writing the result.
     */
    static class BPlusFromPicture {

        /** Entry point for a single test case. */
        void solve(int testNumber, InputReader reader, PrintWriter out) {
            int rows = reader.nextInt();   // N
            int cols = reader.nextInt();   // M

            // Read the whole grid at once
            boolean[][] grid = readGrid(rows, reader);

            // Find the center of a potential plus, if any
            Position plusCenter = locatePlusCenter(grid);
            if (plusCenter == null) {
                out.println("NO");
                return;
            }

            // Verify that every '*' belongs to the plus centred at plusCenter
            if (!isValidPlus(grid, plusCenter)) {
                out.println("NO");
                return;
            }

            // All checks passed
            out.println("YES");
        }

        /**
         * Reads `rows` lines from the input, each line containing exactly `cols`
         * characters. Returns a boolean matrix where {@code true} marks a '*'
         * cell.
         */
        private static boolean[][] readGrid(int rows, InputReader reader) {
            boolean[][] grid = new boolean[rows][];
            for (int i = 0; i < rows; i++) {
                String line = reader.next();
                char[] chars = line.toCharArray();
                boolean[] rowData = new boolean[cols];
                for (int j = 0; j < cols; j++) {
                    rowData[j] = (chars[j] == '*');
                }
                grid[i] = rowData;
            }
            return grid;
        }

        /**
         * Searches for a cell that could be the centre of a plus.
         * The centre must be surrounded by at least one '*' in each of the four
         * cardinal directions.
         *
         * @return the centre position if found; {@code null} otherwise.
         */
        private static Position locatePlusCenter(boolean[][] grid) {
            int rows = grid.length;
            int cols = grid[0].length;

            // Scan cells that are guaranteed to have neighbours in all four
            // directions (i.e. exclude the outer border)
            for (int i = 1; i < rows - 1; i++) {
                for (int j = 1; j < cols - 1; j++) {
                    if (isPlusCenter(grid, i, j)) {
                        return new Position(i, j);
                    }
                }
            }
            return null; // no plus centre found
        }

        /**
         * Determines whether the cell at (row, col) can serve as the centre of
         * a plus. The pattern must be:
         *   * (row, col) is '*'
         *   * All four orthogonal neighbours are also '*'
         */
        private static boolean isPlusCenter(boolean[][] grid, int row, int col) {
            return grid[row][col]
                    && grid[row - 1][col]   // up
                    && grid[row + 1][col]   // down
                    && grid[row][col - 1]   // left
                    && grid[row][col + 1];  // right
        }

        /**
         * Validates that every '*' in the grid belongs to the plus whose centre
         * is {@code centre}. The plus consists of the centre cell and all cells
         * that are directly reachable by moving horizontally or vertically from
         * the centre until a non‑'*' cell or the border is encountered.
         *
         * @return {@code true} if the grid contains exactly the cells of one plus.
         */
        private static boolean isValidPlus(boolean[][] grid, Position centre) {
            // Collect all cells that belong to the plus
            java.util.Set<Position> plusCells = collectPlusCells(grid, centre);

            // Ensure that every '*' in the grid is part of that set
            for (int i = 0; i < grid.length; i++) {
                for (int j = 0; j < grid[i].length; j++) {
                    if (grid[i][j] && !plusCells.contains(new Position(i, j))) {
                        return false;
                    }
                }
            }
            return true;
        }

        /**
         * Gathers all cells belonging to the plus centred at {@code centre}.
         * The plus extends in four directions (up, down, left, right) until a
         * non‑'*' cell or the grid border is reached.
         */
        private static java.util.Set<Position> collectPlusCells(boolean[][] grid, Position centre) {
            java.util.Set<Position> cells = new java.util.HashSet<>();

            // Move upward from the centre
            for (int r = centre.row; r >= 0 && grid[r][centre.col]; r--) {
                cells.add(new Position(r, centre.col));
            }

            // Move downward
            for (int r = centre.row; r < grid.length && grid[r][centre.col]; r++) {
                cells.add(new Position(r, centre.col));
            }

            // Move leftwards
            for (int c = centre.col; c >= 0 && grid[centre.row][c]; c--) {
                cells.add(new Position(centre.row, c));
            }

            // Move rightwards
            for (int c = centre.col; c < grid[0].length && grid[centre.row][c]; c++) {
                cells.add(new Position(centre.row, c));
            }

            return cells;
        }
    }

    /**
     * Small utility class that represents a grid coordinate.
     * It implements {@code equals} and {@code hashCode} so that it can be
     * stored efficiently in a {@link java.util.HashSet}.
     */
    private static final class Position {
        final int row;
        final int col;

        Position(int row, int col) {
            this.row = row;
            this.col = col;
        }

        @Override
        public boolean equals(Object o) {
            if (this == o) return true;
            if (!(o instanceof Position)) return false;
            Position that = (Position) o;
            return row == that.row && col == that.col;
        }

        @Override
        public int hashCode() {
            int result = 31;
            result = 31 * result + row;
            result = 31 * result + col;
            return result;
        }

        @Override
        public String toString() {
            return "(" + row + "," + col + ")";
        }
    }

    /**
     * Helper class that wraps a {@link BufferedReader} and provides convenient
     * tokenised reading methods.
     */
    private static final class InputReader {
        private final BufferedReader reader;

        InputReader(InputStream stream) {
            this.reader = new BufferedReader(
                    new InputStreamReader(stream), 32768);
        }

        /** Returns the next non‑empty token from the input. */
        String next() {
            try {
                while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                    tokenizer = new StringTokenizer(reader.readLine());
                }
            } catch (IOException e) {
                throw new UncheckedIOException(e);
            }
            return tokenizer.nextToken();
        }

        /** Reads the next token and parses it as an {@code int}. */
        int nextInt() {
            return Integer.parseInt(next());
        }

        // Lazily initialised tokenizer
        private StringTokenizer tokenizer;
    }
}

import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.util.Scanner;

/**
 * Detects whether the given grid consists of exactly one plus‑shaped pattern made of '*'
 * characters that covers all '*' cells in the grid.
 * The implementation is deliberately split into small, well‑named methods to improve
 * readability and maintainability.
 */
public class Main {

    /* -------------------------------------------------------------------------- */
    /*  Constants                                                               */
    /* -------------------------------------------------------------------------- */
    private static final char CLOSE = '*';
    private static final String YES = "YES";
    private static final String NO = "NO";

    /* -------------------------------------------------------------------------- */
    /*  Direction representation                                                   */
    /* -------------------------------------------------------------------------- */
    private enum Direction {
        UP(-1, 0),
        DOWN(1, 0),
        LEFT(0, -1),
        RIGHT(0, 1);

        final int dx;
        final int dy;

        Direction(int dx, int dy) {
            this.dx = dx;
            this.dy = dy;
        }
    }

    /* -------------------------------------------------------------------------- */
    /*  Small immutable helper class for coordinates                               */
    /* -------------------------------------------------------------------------- */
    private static final class Point {
        final int row;
        final int col;

        Point(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }

    /* -------------------------------------------------------------------------- */
    /*  Entry point                                                                */
    /* -------------------------------------------------------------------------- */
    public static void main(String[] args) {
        /* Try‑with‑resources ensures the scanner is closed even on exceptions.      */
        try (Scanner scanner = new Scanner(new BufferedReader(new InputStreamReader(System.in)))) {
            int rows = scanner.nextInt();
            int cols = scanner.nextInt();

            char[][] grid = new char[rows][cols];
            for (int r = 0; r < rows; r++) {
                String line = scanner.next();
                System.arraycopy(line.toCharArray(), 0, grid[r], 0, cols);
            }

            System.out.println(solve(grid, rows, cols));
        }
    }

    /* -------------------------------------------------------------------------- */
    /*  Public solve method                                                         */
    /* -------------------------------------------------------------------------- */
    private static String solve(char[][] grid, int rows, int cols) {
        /* A plus cannot exist on a grid that is too small.                         */
        if (rows < 3 || cols < 3) {
            return NO;
        }

        Point center = findPlusCenter(grid, rows, cols);
        if (center == null) {
            return NO;
        }

        boolean[][] visited = markAllArms(grid, rows, cols, center);
        return allCloseVisited(grid, visited, rows, cols) ? YES : NO;
    }

    /* -------------------------------------------------------------------------- */
    /*  Locate the centre of a potential plus shape                                 */
    /* -------------------------------------------------------------------------- */
    private static Point findPlusCenter(char[][] grid, int rows, int cols) {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] != CLOSE) {
                    continue;
                }
                if (isPlusShapeCenter(r, c, grid, rows, cols)) {
                    return new Point(r, c);
                }
            }
        }
        return null; // no centre found
    }

    /* -------------------------------------------------------------------------- */
    /*  Verify that the cell at (r,c) is a plus centre (has a neighbour '*' in     */
    /*  all four directions).                                                    */
    /* -------------------------------------------------------------------------- */
    private static boolean isPlusShapeCenter(int r, int c, char[][] grid,
                                             int rows, int cols) {
        for (Direction dir : Direction.values()) {
            int nr = r + dir.dx;
            int nc = c + dir.dy;
            if (!inGrid(nr, nc, rows, cols) || grid[nr][nc] != CLOSE) {
                return false;
            }
        }
        return true;
    }

    /* -------------------------------------------------------------------------- */
    /*  From the centre, walk outwards in each of the four directions and mark   */
    /*  every '*' we encounter as visited.                                        */
    /* -------------------------------------------------------------------------- */
    private static boolean[][] markAllArms(char[][] grid, int rows, int cols,
                                           Point center) {
        boolean[][] visited = new boolean[rows][cols];
        visited[center.row][center.col] = true; // centre itself

        for (Direction dir : Direction.values()) {
            int nr = center.row + dir.dx;
            int nc = center.col + dir.dy;
            while (inGrid(nr, nc, rows, cols) && grid[nr][nc] == CLOSE) {
                visited[nr][nc] = true;
                nr += dir.dx;
                nc += dir.dy;
            }
        }
        return visited;
    }

    /* -------------------------------------------------------------------------- */
    /*  Ensure that every '*' in the original grid has been visited; otherwise    */
    /*  the pattern is not a pure plus.                                          */
    /* -------------------------------------------------------------------------- */
    private static boolean allCloseVisited(char[][] grid, boolean[][] visited,
                                           int rows, int cols) {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == CLOSE && !visited[r][c]) {
                    return false;
                }
            }
        }
        return true;
    }

    /* -------------------------------------------------------------------------- */
    /*  Helper: quick bounds check                                                 */
    /* -------------------------------------------------------------------------- */
    private static boolean inGrid(int r, int c, int rows, int cols) {
        return r >= 0 && c >= 0 && r < rows && c < cols;
    }
}

import java.util.Scanner;

/**
 * Reads a grid of characters ('.' or any other character) and determines whether
 * all filled cells ('#'‑like characters) form a single connected component that
 * contains at least one "cross" cell (a cell whose four orthogonal neighbours are
 * also filled).  The program prints {@code "YES"} if the condition is satisfied,
 * otherwise it prints {@code "NO"}.
 *
 * <p>Refactored for readability, maintainability and proper resource handling.</p>
 */
public class StarPatternChecker {

    /** Directions used for depth‑first traversal. */
    private enum Direction {
        UP(-1, 0), DOWN(1, 0), LEFT(0, -1), RIGHT(0, 1);

        private final int deltaRow;
        private final int deltaCol;

        Direction(int deltaRow, int deltaCol) {
            this.deltaRow = deltaRow;
            this.deltaCol = deltaCol;
        }

        int[] offsets() {
            return new int[]{deltaRow, deltaCol};
        }
    }

    /** Entry point of the program. */
    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            int height = scanner.nextInt();
            int width = scanner.nextInt();
            scanner.nextLine(); // consume end‑of‑line

            int[][] grid = readGrid(scanner, height, width);
            if (isGridEmpty(grid)) {
                System.out.println("NO");
                return;
            }

            boolean[][] visited = new boolean[height][width];
            int[] crossCenter = findCrossCenter(grid, height, width);

            if (crossCenter == null) {
                System.out.println("NO");
                return;
            }

            int startRow = crossCenter[0];
            int startCol = crossCenter[1];
            dfs(grid, visited, startRow, startCol);

            // Any filled cell that was never visited means the filled cells
            // are not all connected to the discovered cross centre.
            for (int i = 0; i < height; i++) {
                for (int j = 0; j < width; j++) {
                    if (grid[i][j] == 1 && !visited[i][j]) {
                        System.out.println("NO");
                        return;
                    }
                }
            }

            System.out.println("YES");
        }
    }

    /**
     * Reads {@code height} lines of input, each containing {@code width}
     * characters, and builds a 0/1 matrix where {@code 1} represents a non‑'.'
     * cell.
     *
     * @param scanner   Scanner reading the input.
     * @param height    Number of rows.
     * @param width     Number of columns.
     * @return a matrix representing the grid.
     */
    private static int[][] readGrid(Scanner scanner, int height, int width) {
        int[][] grid = new int[height][width];
        boolean hasFilledCell = false;

        for (int row = 0; row < height; row++) {
            String line = scanner.nextLine();
            for (int col = 0; col < width; col++) {
                boolean filled = line.charAt(col) != '.';
                grid[row][col] = filled ? 1 : 0;
                if (filled) {
                    hasFilledCell = true;
                }
            }
        }

        // The original program prints "NO" when the grid contains no filled cells.
        if (!hasFilledCell) {
            System.out.println("NO");
            System.exit(0);
        }

        return grid;
    }

    /** @return true if the grid contains no '1' cells. */
    private static boolean isGridEmpty(int[][] grid) {
        for (int[] row : grid) {
            for (int cell : row) {
                if (cell == 1) {
                    return false;
                }
            }
        }
        return true;
    }

    /**
     * Locates a cell that together with its four orthogonal neighbours are all
     * filled (value {@code 1}).  The search is performed only inside the inner
     * rectangle that excludes the outer border.
     *
     * @param grid      The grid to search.
     * @param rows      Number of rows.
     * @param cols      Number of columns.
     * @return an int[2] containing {@code [row, col]} of the first matching cell,
     *         or {@code null} if none exists.
     */
    private static int[] findCrossCenter(int[][] grid, int rows, int cols) {
        for (int row = 1; row < rows - 1; row++) {
            for (int col = 1; col < cols - 1; col++) {
                if (isCross(cellAt(grid, row, col),               // centre
                           cellAt(grid, row - 1, col),             // up
                           cellAt(grid, row + 1, col),             // down
                           cellAt(grid, row, col - 1),             // left
                           cellAt(grid, row, col + 1))) {            // right
                    return new int[]{row, col};
                }
            }
        }
        return null;
    }

    /** Returns the value (0 or 1) stored at {@code matrix[row][col]}. */
    private static int cellAt(int[][] matrix, int row, int col) {
        return matrix[row][col];
    }

    /**
     * Determines whether five cells form a plus sign (centre + four neighbours).
     *
     * @param centre   value of the centre cell.
     * @param up       value of the cell above the centre.
     * @param down     value of the cell below the centre.
     * @param left     value of the cell to the left of the centre.
     * @param right    value of the cell to the right of the centre.
     * @return {@code true} if all five values are {@code 1}.
     */
    private static boolean isCross(int centre, int up, int down, int left, int right) {
        return centre == 1 && up == 1 && down == 1 && left == 1 && right == 1;
    }

    /**
     * Depth‑first search that marks all cells reachable from {@code startRow},
     * {@code startCol} moving in any of the four cardinal directions.
     *
     * @param grid      The grid being traversed.
     * @param visited   Boolean matrix that records visited cells.
     * @param startRow  Starting row index.
     * @param startCol  Starting column index.
     */
    private static void dfs(int[][] grid, boolean[][] visited, int startRow, int startCol) {
        visitCell(grid, visited, startRow, startCol);
        for (Direction dir : Direction.values()) {
            int nextRow = startRow + dir.offsets()[0];
            int nextCol = startCol + dir.offsets()[1];
            if (canVisit(grid, visited, nextRow, nextCol)) {
                dfs(grid, visited, nextRow, nextCol);
            }
        }
    }

    /** Marks the current cell as visited. */
    private static void visitCell(int[][] grid, boolean[][] visited, int row, int col) {
        visited[row][col] = true;
    }

    /** Checks whether a neighbour cell is inside the grid, filled and unvisited. */
    private static boolean canVisit(int[][] grid, boolean[][] visited, int row, int col) {
        return row >= 0 && row < grid.length
                && col >= 0 && col < grid[0].length
                && grid[row][col] == 1
                && !visited[row][col];
    }
}

import java.io.IOException;
import java.util.Scanner;

/**
 * Refactored version of the original program that checks whether a given
 * grid contains exactly one cross made of '*' characters.
 *
 * The refactoring focuses on:
 *   • Clear naming and separation of concerns.
 *   • Removal of the custom Scanner implementation.
 *   • Use of try‑with‑resources for automatic resource handling.
 *   • Extraction of helper methods to improve readability and testability.
 */
public class Main {

    public static void main(String[] args) {
        // The grid dimensions are read from standard input.
        try (Scanner scanner = new Scanner(System.in)) {
            int rows = scanner.nextInt();
            int cols = scanner.nextInt();

            char[][] grid = readGrid(scanner, rows);
            int totalStars = countStars(grid);

            boolean hasCross = findCross(grid, rows, cols, totalStars);
            System.out.println(hasCross ? "YES" : "NO");
        }
    }

    /** Reads the grid from the scanner. */
    private static char[][] readGrid(Scanner scanner, int n) {
        char[][] grid = new char[n][];
        for (int i = 0; i < n; i++) {
            String line = scanner.next();
            grid[i] = line.toCharArray();
        }
        return grid;
    }

    /** Counts the total number of '*' characters in the grid. */
    private static int countStars(char[][] grid) {
        int count = 0;
        for (char[] row : grid) {
            for (char cell : row) {
                if (cell == '*') {
                    count++;
                }
            }
        }
        return count;
    }

    /**
     * Determines whether the grid contains a single cross that uses all '*'
     * characters exactly once.
     *
     * @return true if such a cross exists, false otherwise.
     */
    private static boolean findCross(char[][] grid, int rows, int cols, int totalStars) {
        // Only interior cells can be the centre of a cross.
        for (int i = 1; i < rows - 1; i++) {
            for (int j = 1; j < cols - 1; j++) {
                if (grid[i][j] != '*') {
                    continue;
                }

                int up = countDirection(grid, i, j, -1, 0);
                int down = countDirection(grid, i, j, 1, 0);
                int left = countDirection(grid, i, j, 0, -1);
                int right = countDirection(grid, i, j, 0, 1);

                // All four arms must be present.
                if (up == 0 || down == 0 || left == 0 || right == 0) {
                    continue;
                }

                int crossLength = 1 + up + down + left + right;
                if (crossLength == totalStars) {
                    return true;
                }
            }
        }
        return false;
    }

    /**
     * Counts consecutive '*' cells in the given direction starting from the
     * neighbour of the centre cell.
     *
     * @param grid      the grid array.
     * @param r, c      coordinates of the centre cell.
     * @param dr, dc    step increments for the direction.
     * @return the number of '*' cells encountered before hitting a non‑'*'
     *         cell or the grid boundary.
     */
    private static int countDirection(char[][] grid, int r, int c,
                                      int dr, int dc) {
        int count = 0;
        int nr = r + dr;
        int nc = c + dc;
        while (isInside(grid, nr, nc) && grid[nr][nc] == '*') {
            count++;
            nr += dr;
            nc += dc;
        }
        return count;
    }

    /** Helper that checks whether a cell coordinate lies inside the grid. */
    private static boolean isInside(char[][] grid, int r, int c) {
        return r >= 0 && r < grid.length && c >= 0 && c < grid[0].length;
    }
}

import java.util.Optional;
import java.util.Scanner;

/**
 * Reads a rectangular grid, looks for a single ‘+’ shaped cross formed by '*'
 * characters, removes it and verifies that no other '*' remain.
 * Prints “YES” if the board becomes clean, otherwise prints “NO”.
 */
public class Solution {

    private static final String YES = "YES";
    private static final String NO  = "NO";

    public static void main(String[] args) {
        /* -------------------------------------------------------------
         * 1️⃣  Input handling – try‑with‑resources guarantees proper closing.
         * ------------------------------------------------------------- */
        try (Scanner sc = new Scanner(System.in)) {
            int rows = sc.nextInt();
            int cols = sc.nextInt();
            sc.nextLine();                     // consume end‑of‑line after the dimensions
            char[][] board = readBoard(sc, rows, cols);

            /* -------------------------------------------------------------
             * 2️⃣  Find the centre of the unique cross.
             * ------------------------------------------------------------- */
            Optional<Point> centre = findCrossCenter(board);
            if (!centre.isPresent() || countPossibleCenters(board) != 1) {
                System.out.println(NO);
                return;
            }

            /* -------------------------------------------------------------
             * 3️⃣  Remove every '*' that belongs to that cross.
             * ------------------------------------------------------------- */
            removeCross(board, centre.get());

            /* -------------------------------------------------------------
             * 4️⃣  Verify that no stray '*' remain.
             * ------------------------------------------------------------- */
            if (hasRemainingStars(board)) {
                System.out.println(NO);
            } else {
                System.out.println(YES);
            }
        }
    }

    /** Reads `rows` lines of length `cols` from the scanner. */
    private static char[][] readBoard(Scanner sc, int rows, int cols) {
        char[][] board = new char[rows][cols];
        for (int r = 0; r < rows; r++) {
            String line = sc.nextLine();
            board[r] = line.toCharArray();
        }
        return board;
    }

    /** Counts how many cells could serve as the centre of a ‘+’ cross. */
    private static int countPossibleCenters(char[][] board) {
        int count = 0;
        for (int i = 1; i < board.length - 1; i++) {
            for (int j = 1; j < board[i].length - 1; j++) {
                if (isCross(board, i, j)) {
                    count++;
                }
            }
        }
        return count;
    }

    /** Returns true if cell (i,j) together with its four neighbours form a ‘+’ of '*'. */
    private static boolean isCross(char[][] board, int i, int j) {
        return board[i][j] == '*' &&
               board[i - 1][j] == '*' &&
               board[i + 1][j] == '*' &&
               board[i][j - 1] == '*' &&
               board[i][j + 1] == '*';
    }

    /** Returns an Optional containing the coordinates of the unique cross centre, if any. */
    private static Optional<Point> findCrossCenter(char[][] board) {
        for (int i = 1; i < board.length - 1; i++) {
            for (int j = 1; j < board[i].length - 1; j++) {
                if (isCross(board, i, j)) {
                    return Optional.of(new Point(i, j));
                }
            }
        }
        return Optional.empty();
    }

    /** Mutates `board` by replacing the centre and its arms of '*' with '.'. */
    private static void removeCross(char[][] board, Point centre) {
        int i = centre.row;
        int j = centre.col;

        board[i][j] = '.';
        // up
        for (int r = i - 1; r >= 0 && board[r][j] == '*'; r--) board[r][j] = '.';
        // down
        for (int r = i + 1; r < board.length && board[r][j] == '*'; r++) board[r][j] = '.';
        // left
        for (int c = j - 1; c >= 0 && board[i][c] == '*'; c--) board[i][c] = '.';
        // right
        for (int c = j + 1; c < board[i].length && board[i][c] == '*'; c++) board[i][c] = '.';
    }

    /** Checks whether any '*' cells are left on the board. */
    private static boolean hasRemainingStars(char[][] board) {
        for (char[] row : board) {
            for (char cell : row) {
                if (cell == '*') {
                    return true;
                }
            }
        }
        return false;
    }

    /** Simple immutable container for a board coordinate. */
    private static final class Point {
        final int row;
        final int col;

        Point(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Reads a grid of characters and checks whether all '*' cells belong to a single
 * plus‑shaped star (a centre with four orthogonal arms). If such a star exists
 * and every '*' is visited during the traversal, the answer is "YES", otherwise
 * "NO".
 */
public class Main {

    /** Four orthogonal directions: down, up, left, right */
    private static final int[][] DIRECTIONS = {{1, 0}, {-1, 0}, {0, -1}, {0, 1}};

    private static FastReader scanner;
    private static char[][] grid;      // input grid
    private static boolean[][] visited; // tracks visited '*' cells
    private static int rows, cols;     // grid dimensions

    public static void main(String[] args) {
        scanner = new FastReader();

        readDimensions();
        readGrid();

        Arrays.fill(visited[0], false); // initialise visited matrix

        boolean starFound = locateStarCenter();
        if (starFound) {
            traverseAllArms();
        }

        System.out.println(starFound && noUnvisitedStars() ? "YES" : "NO");
    }

    /** Reads the number of rows and columns from the input. */
    private static void readDimensions() {
        rows = scanner.nextInt();
        cols = scanner.nextInt();
    }

    /** Reads the grid itself. */
    private static void readGrid() {
        grid = new char[rows][];
        for (int i = 0; i < rows; i++) {
            grid[i] = scanner.next().toCharArray();
        }
    }

    /** Returns true if the cell (i, j) is the centre of a plus‑shaped star. */
    private static boolean isStarCenter(int i, int j) {
        if (!isInside(i, j) || grid[i][j] != '*') {
            return false;
        }
        for (int[] dir : DIRECTIONS) {
            int ni = i + dir[0];
            int nj = j + dir[1];
            if (!isInside(ni, nj) || grid[ni][nj] != '*') {
                return false;
            }
        }
        return true;
    }

    /** Explores a single arm starting from (i, j) moving in (dx, dy) direction,
     *  marking every visited '*' cell. */
    private static void exploreArm(int i, int j, int dx, int dy) {
        int ni = i + dx;
        int nj = j + dy;
        while (isInside(ni, nj) && grid[ni][nj] == '*' && !visited[ni][nj]) {
            visited[ni][nj] = true;
            i = ni;
            j = nj;
            ni = i + dx;
            nj = j + dy;
        }
    }

    /** Traverses the four arms of the detected star centre. */
    private static void traverseAllArms() {
        for (int[] dir : DIRECTIONS) {
            exploreArm(findStarCenterRow(), findStarCenterCol(), dir[0], dir[1]);
        }
    }

    /** Helper that returns the centre row of the first found star, or -1 if none. */
    private static int findStarCenterRow() {
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (isStarCenter(i, j)) {
                    return i;
                }
            }
        }
        return -1;
    }

    /** Helper that returns the centre column of the first found star, or -1 if none. */
    private static int findStarCenterCol() {
        for (int j = 0; j < cols; j++) {
            for (int i = 0; i < rows; i++) {
                if (isStarCenter(i, j)) {
                    return j;
                }
            }
        }
        return -1;
    }

    /** Checks whether any '*' cell was never visited – indicates an invalid grid. */
    private static boolean hasUnvisitedStars() {
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == '*' && !visited[i][j]) {
                    return true;
                }
            }
        }
        return false;
    }

    /** Returns true if (i, j) lies inside the grid bounds. */
    private static boolean isInside(int i, int j) {
        return i >= 0 && i < rows && j >= 0 && j < cols;
    }

    /* --------------------------------------------------------------
     *  Simple fast input reader (unchanged but kept private)
     * -------------------------------------------------------------- */
    private static class FastReader {
        private final BufferedReader br;
        private StringTokenizer st;

        FastReader() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    throw new UncheckedIOException(e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.io.PrintWriter;
import java.util.Scanner;

/**
 * Reads a grid of characters and decides whether it consists exclusively of a single
 * plus sign made of asterisks ('*').  All other cells must be dots ('.').
 *
 * The solution is split into small, well‑named methods that each perform a single
 * responsibility, making the code easier to test, understand and maintain.
 */
public class Solution {

    /** Grid dimensions */
    private final int height;
    /** Grid dimensions */
    private final int width;
    /** 2‑D representation of the input picture */
    private final char[][] grid;

    /**
     * Constructs a {@link Solution} from a {@link Scanner} that supplies the
     * height, width and the picture rows.
     *
     * @param scanner a scanner positioned at the beginning of the input
     * @throws IllegalArgumentException if the scanner does not contain sufficient data
     */
    public Solution(Scanner scanner) {
        this.height = scanner.nextInt();
        this.width = scanner.nextInt();

        this.grid = readGrid(scanner);
    }

    /** Reads exactly {@code height} rows from the scanner and returns a char matrix. */
    private static char[][] readGrid(Scanner scanner) {
        char[][] grid = new char[scanner.nextInt()][scanner.nextInt()];
        // The dimensions have already been consumed, so we now read the rows.
        // The original code assumes the next tokens are the rows themselves.
        // To keep the same semantics we read `height` lines.
        // NOTE: The original code used `height` and `width` just read, so we reuse them.
        // However, because they were overwritten locally, we need to read again.
        // A more straightforward approach is to read the remaining tokens directly:
        char[][] result = new char[SolutionHolder.HEIGHT][SolutionHolder.WIDTH];
        // The static holders are filled by the constructor; to avoid coupling we simply
        // read using the previously stored dimensions.
        for (int r = 0; r < SolutionHolder.HEIGHT; r++) {
            String line = scanner.next();
            result[r] = line.toCharArray();
        }
        return result;
    }

    /**
     * Finds the first plus sign in the grid.
     *
     * <p>A plus is defined as a contiguous cross of asterisks where the centre cell
     * has at least one asterisk in each of the four orthogonal directions.
     *
     * @return a boolean mask of the same size as the grid where {@code true}
     *         marks cells belonging to the discovered plus, or {@code null}
     *         if no plus exists.
     */
    private boolean[][] findFirstPlusMask() {
        // Scan all possible centre positions.  The centre must be surrounded
        // by at least one cell on each side, therefore we start at 1 and stop
        // before the last row/column.
        for (int row = 1; row < height - 1; row++) {
            for (int col = 1; col < width - 1; col++) {
                if (isPotentialCentre(row, col)) {
                    return buildPlusMask(row, col);
                }
            }
        }
        return null; // no plus found
    }

    /** Checks whether (row, col) can be the centre of a plus. */
    private boolean isPotentialCentre(int row, int col) {
        char centre = grid[row][col];
        if (centre != '*') {
            return false;
        }
        // The centre must have a '*' in each of the four neighbours to even qualify.
        return grid[row - 1][col] == '*' &&   // up
               grid[row + 1][col] == '*' &&   // down
               grid[row][col - 1] == '*' &&   // left
               grid[row][col + 1] == '*';     // right
    }

    /**
     * Constructs a boolean mask that marks every cell belonging to the plus
     * whose centre is at (centreRow, centreCol).
     */
    private boolean[][] buildPlusMask(int centreRow, int centreCol) {
        boolean[][] mask = new boolean[height][width];
        extendHorizontally(mask, centreRow, centreCol);
        extendVertically(mask, centreRow, centreCol);
        return mask;
    }

    /** Marks all contiguous '*' cells to the left and right of the centre in the same row. */
    private void extendHorizontally(boolean[][] mask, int row, int col) {
        // Expand leftwards
        for (int c = col; c >= 0 && grid[row][c] == '*'; c--) {
            mask[row][c] = true;
        }
        // Expand rightwards
        for (int c = col; c < width && grid[row][c] == '*'; c++) {
            mask[row][c] = true;
        }
    }

    /** Marks all contiguous '*' cells above and below the centre in the same column. */
    private void extendVertically(boolean[][] mask, int row, int col) {
        // Expand upwards
        for (int r = row; r >= 0 && grid[r][col] == '*'; r--) {
            mask[r][col] = true;
        }
        // Expand downwards
        for (int r = row; r < height && grid[r][col] == '*'; r++) {
            mask[r][col] = true;
        }
    }

    /**
     * Verifies that every asterisk in the grid belongs to the discovered plus.
     *
     * @return {@code true} if the mask covers all '*' cells and nothing else is
     *         required; {@code false} otherwise.
     */
    private boolean validatesAllStars(boolean[][] plusMask) {
        for (int r = 0; r < height; r++) {
            for (int c = 0; c < width; c++) {
                char ch = grid[r][c];
                if (ch == '*' && !plusMask[r][c]) {
                    // An asterisk is not part of the plus → invalid configuration.
                    return false;
                }
                // '.' cells are ignored – they may appear anywhere.
            }
        }
        return true;
    }

    /**
     * Solves the problem: returns {@code "YES"} if the input consists exclusively
     * of a single plus sign, otherwise {@code "NO"}.
     */
    public String solve() {
        boolean[][] plusMask = findFirstPlusMask();
        if (plusMask == null) {
            return "NO";
        }
        if (!validatesAllStars(plusMask)) {
            return "NO";
        }
        return "YES";
    }

    /** Main entry point – reads from STDIN and writes the answer to STDOUT. */
    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in);
                PrintWriter out = new PrintWriter(System.out)) {
            Solution solution = new Solution(scanner);
            out.println(solution.solve());
        }
        // Explicit exit status is unnecessary; the program ends naturally.
    }
}

import java.util.Scanner;

/**
 * Refactored solution for Codeforces problem 566B (IT City Day).
 * The program checks whether the given '*'-pattern can be a single
 * plus sign (i.e., exactly one central cell with arms extending in the
 * four cardinal directions and no extra stars elsewhere).
 */
public class Div2_566B {

    /** Scanner used for reading input – kept static to avoid repeated allocation. */
    private static final Scanner SCANNER = new Scanner(System.in);

    /** Entry point of the program. */
    public static void main(String[] args) {
        int rows = SCANNER.nextInt();
        int cols = SCANNER.nextInt();

        char[][] grid = readGrid(rows, cols);
        int totalStars = countStars(grid);

        // A plus sign can contain at most (rows + cols - 1) stars.
        if (totalStars > rows + cols - 1) {
            System.out.println("NO");
            return;
        }

        boolean isPlus = findPlusCenter(grid, totalStars);
        System.out.println(isPlus ? "YES" : "NO");
    }

    /**
     * Reads the grid from standard input.
     */
    private static char[][] readGrid(int n, int m) {
        char[][] grid = new char[n][m];
        for (int i = 0; i < n; i++) {
            String line = SCANNER.next();
            for (int j = 0; j < m; j++) {
                grid[i][j] = line.charAt(j);
            }
        }
        return grid;
    }

    /**
     * Counts the total number of '*' characters in the grid.
     */
    private static int countStars(char[][] grid) {
        int count = 0;
        for (char[] row : grid) {
            for (char cell : row) {
                if (cell == '*') {
                    count++;
                }
            }
        }
        return count;
    }

    /**
     * Determines whether the pattern forms a valid plus sign.
     *
     * @param grid       The grid to inspect.
     * @param totalStars The total number of stars in the grid.
     * @return {@code true} if a valid plus shape is found; otherwise {@code false}.
     */
    private static boolean findPlusCenter(char[][] grid, int totalStars) {
        for (int i = 0; i < grid.length; i++) {
            for (int j = 0; j < grid[i].length; j++) {
                if (grid[i][j] == '*') {
                    int up    = countConsecutive(grid, i, j, -1, 0);
                    int down  = countConsecutive(grid, i, j,  1, 0);
                    int left  = countConsecutive(grid, i, j,  0, -1);
                    int right = countConsecutive(grid, i, j,  0,  1);

                    int plusLength = up + down + left + right + 1; // centre + arms

                    // Conditions matching the original logic:
                    // 1) The counted length must equal the total number of stars.
                    // 2) All four directions must contain at least one star.
                    if (plusLength == totalStars && plusLength > 1
                            && up > 0 && down > 0 && left > 0 && right > 0) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    /**
     * Counts consecutive '*' cells starting from (row, col) and moving
     * in the given direction (dRow, dCol) until a non‑star cell or a
     * grid boundary is reached.
     */
    private static int countConsecutive(char[][] grid, int row, int col,
                                        int dRow, int dCol) {
        int count = 0;
        int r = row + dRow;
        int c = col + dCol;
        while (isInBounds(grid, r, c) && grid[r][c] == '*') {
            count++;
            r += dRow;
            c += dCol;
        }
        return count;
    }

    /**
     * Checks whether the supplied coordinates are inside the grid.
     */
    private static boolean isInBounds(char[][] grid, int r, int c) {
        return r >= 0 && r < grid.length && c >= 0 && c < grid[0].length;
    }
}

import java.io.PrintWriter;
import java.util.Scanner;

/**
 * Reads a grid of characters and determines whether exactly one
 * “star” pattern appears and no other '*' cells are present.
 *
 * The pattern is defined as follows (indices are 0‑based):
 *
 *   - There is a vertical line of three '*'.
 *   - Those three cells occupy rows r, r‑1 and r‑2 in the same column c.
 *   - In the middle row (r‑1) the cells to the left and right of column c
 *     are also '*'.
 *
 * If exactly one such pattern exists and it is the only occurrence of '*'
 * in the whole grid, the answer is “YES”, otherwise “NO”.
 */
public class Main {

    /** Symbol used for stars. */
    private static final char STAR = '*';

    /** Finds the single star centre that satisfies the pattern requirements.
     *
     * @param grid   array of rows from the input
     * @param h      number of rows
     * @param w      number of columns
     * @return       row and column of the centre of a valid star, or {@code null}
     *               if none or more than one centre matches.
     */
    private static StarCenter findStarCenter(char[][] grid, int h, int w) {
        StarCenter candidate = null;

        outer:
        for (int r = 0; r < h; r++) {
            for (int c = 0; c < w; c++) {
                if (grid[r][c] != STAR) {
                    continue;
                }

                // Ensure there are enough rows above to fulfil the pattern.
                if (r - 2 < 0) {
                    continue;
                }

                int midRow = r - 1;               // the middle of the three‑row column
                // Check column cells
                if (grid[midRow][c] != STAR || grid[r - 2][c] != STAR) {
                    continue;
                }

                // Check side neighbours in the middle row
                if (c - 1 < 0 || c + 1 >= w) {
                    continue;
                }
                if (grid[midRow][c - 1] != STAR || grid[midRow][c + 1] != STAR) {
                    continue;
                }

                // This centre satisfies the pattern.
                if (candidate != null) {
                    // More than one centre => invalid.
                    return null;
                }
                candidate = new StarCenter(midRow, c);
            }
        }
        return candidate;   // may be null if no centre was found
    }

    /** Simple holder for the coordinates of a found star centre. */
    private static final class StarCenter {
        final int centreRow;
        final int centreCol;

        StarCenter(int row, int col) {
            this.centreRow = row;
            this.centreCol = col;
        }
    }

    /** Checks that the grid contains only the stars that form the identified centre. */
    private static boolean isGridConsistentWithStar(char[][] grid,
                                                    int h,
                                                    int w,
                                                    StarCenter centre) {
        boolean extraStarFound = false;

        for (int r = 0; r < h; r++) {
            for (int c = 0; c < w; c++) {
                if (grid[r][c] != STAR) {
                    continue;
                }

                // The star centre itself and its two vertical neighbours belong to the pattern.
                if ((r == centre.centreRow && c == centre.centreCol) ||
                    (r == centre.centreRow - 1 && c == centre.centreCol) ||
                    (r == centre.centreRow - 2 && c == centre.centreCol) ||
                    (r == centre.centreRow - 1 && (c == centre.centreCol - 1 ||
                                                   c == centre.centreCol + 1))) {
                    continue;   // allowed position
                }

                // Any other '*' breaks the condition.
                extraStarFound = true;
                break outer;
            }
        }
        return !extraStarFound;
    }

    public static void main(String[] args) throws Exception {
        try (Scanner scanner = new Scanner(System.in)) {
            int h = scanner.nextInt();
            int w = scanner.nextInt();

            char[][] grid = new char[h][w];
            for (int i = 0; i < h; i++) {
                grid[i] = scanner.next().toCharArray();
            }

            StarCenter centre = findStarCenter(grid, h, w);

            if (centre == null || !isGridConsistentWithStar(grid, h, w, centre)) {
                System.out.println("NO");
                return;
            }

            System.out.println("YES");
        }
    }
}

import java.io.*;
import java.text.DecimalFormat;
import java.util.*;

public class Main {

    /* ---------- I/O helpers ---------- */
    private final FastScanner fs;
    private final PrintWriter out;

    /** Constructor used by the driver code. */
    public Main(FastScanner fs, PrintWriter out) {
        this.fs = fs;
        this.out = out;
    }

    /* ---------- Constants ---------- */
    private static final long MOD = 1_000_000_007L;
    private static final long INF_LONG = 1L << 60;
    private static final int INF_INT = Integer.MAX_VALUE / 2;
    private static final int MAX_DEGREE = 200_000 + 5;

    private static final DecimalFormat DF = new DecimalFormat("0.00000000000");
    private static final double PI = Math.PI;
    private static final double EPS = 1e-8;

    /* ---------- Program entry point ---------- */
    public static void main(String[] args) throws Exception {
        boolean useCustomMemory = false;               // left as‑is for original behaviour
        FastScanner fs = new FastScanner();

        if (useCustomMemory) {
            new Thread(null,
                    new Runnable() {
                        @Override
                        public void run() {
                            try {
                                new Main(fs, new PrintWriter(System.out)).run();
                            } catch (Exception e) {
                                e.printStackTrace();
                            }
                        }
                    }, "1", 1 << 28).start();
        } else {
            new Main(fs, new PrintWriter(System.out)).run();
        }
    }

    /* ---------- Core solving logic ---------- */
    public void solve() throws Exception {
        // The original implementation used multiple test cases; keep the same flexibility.
        int tests = fs.hasNextToken() ? 1 : 1; // for single‑TC problems replace with ni()
        for (int tc = 0; tc < tests; tc++) {
            boolean answer = analyseCase();
            out.println(answer ? "YES" : "NO");
        }
    }

    /**
     * Reads a single test case and returns {@code true} if the required pattern is found.
     */
    private boolean analyseCase() throws IOException {
        int h = fs.nextInt();
        int w = fs.nextInt();
        boolean[][] stars = new boolean[h][w];

        int totalStars = 0;
        for (int r = 0; r < h; r++) {
            String line = fs.nextLine();
            for (int c = 0; c < w; c++) {
                stars[r][c] = line.charAt(c) == '*';
                totalStars += stars[r][c] ? 1 : 0;
            }
        }

        // Look for a star that can serve as the centre of a perfect cross.
        for (int r = 0; r < h; r++) {
            for (int c = 0; c < w; c++) {
                if (!stars[r][c]) continue;               // only cells that contain a star can be a centre

                int[] crosses = countContinuousStars(stars, r, c);
                // At least one star in each direction and the whole cross must contain all stars.
                if (isValidCross(crosses, totalStars)) {
                    return true;
                }
            }
        }
        return false;
    }

    /**
     * Returns an int array {up, down, left, right} containing the number of contiguous stars
     * in each direction, stopping at the first empty cell or border.
     */
    private int[] countContinuousStars(boolean[][] grid, int row, int col) {
        int[] dirs = new int[4]; // 0 = up, 1 = down, 2 = left, 3 = right

        // Up
        for (int r = row - 1; r >= 0; r--) {
            if (grid[r][col]) dirs[0]++; else break;
        }
        // Down
        for (int r = row + 1; r < grid.length; r++) {
            if (grid[r][col]) dirs[1]++; else break;
        }
        // Left
        for (int c = col - 1; c >= 0; c--) {
            if (grid[row][c]) dirs[2]++; else break;
        }
        // Right
        for (int c = col + 1; c < grid[row].length; c++) {
            if (grid[row][c]) dirs[3]++; else break;
        }
        return dirs;
    }

    /** Checks whether the given cross length satisfies the two conditions of the original problem. */
    private boolean isValidCross(int[] crossLengths, int totalStars) {
        // Minimum length in any direction must be at least 1
        if (Math.min(Math.min(crossLengths[0], crossLengths[1]),
                     Math.min(crossLengths[2], crossLengths[3])) < 1) {
            return false;
        }
        // The centre cell plus the four arms must equal the total number of stars in the grid.
        return crossLengths[0] + crossLengths[1] + crossLengths[2] + crossLengths[3] + 1 == totalStars;
    }

    /* ---------- FastScanner (identical to the original) ---------- */
    private static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner(String filePath) throws IOException {
            br = new BufferedReader(new FileReader(filePath));
        }

        FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() throws IOException {
            while (st == null || !st.hasMoreElements()) {
                st = new StringTokenizer(br.readLine());
            }
            return st.nextToken();
        }

        String nextLine() throws IOException {
            return br.readLine();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }
}

import java.util.Scanner;

/**
 * Reads a rectangular grid of characters and checks whether it consists
 * solely of a single “plus” made of '*' symbols (with possible extensions
 * along the four cardinal directions).  If the whole grid can be cleared
 * by removing that plus and all contiguous stars belonging to it, the
 * program prints {@code YES}; otherwise it prints {@code NO}.
 *
 * The implementation is deliberately split into small, well‑named
 * methods to improve readability, testability and future maintenance.
 */
public class Main {

    /** Directions used for removing the plus – up, down, left, right. */
    private static final int[][] DIRECTIONS = {
            { -1, 0 }, // up
            { 1, 0 },  // down
            { 0, -1 }, // left
            { 0, 1 }   // right
    };

    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            int rows = scanner.nextInt();
            int cols = scanner.nextInt();

            char[][] grid = readGrid(scanner, rows, cols);

            boolean plusFound = false;
            boolean allStarsRemoved = true; // will be set to false if any '*' remains

            // Search only the inner cells – a plus cannot touch the border.
            for (int r = 1; r < rows - 1 && !plusFound; r++) {
                for (int c = 1; c < cols - 1 && !plusFound; c++) {
                    if (isPlusCenter(grid, r, c)) {
                        plusFound = true;
                        removePlusAndConnectedStars(grid, r, c);
                        allStarsRemoved = noStarRemaining(grid);
                    }
                }
            }

            System.out.println((plusFound && allStarsRemoved) ? "YES" : "NO");
        }
    }

    /** Reads the grid from the scanner. */
    private static char[][] readGrid(Scanner scanner, int n, int m) {
        char[][] grid = new char[n][];
        for (int i = 0; i < n; i++) {
            grid[i] = scanner.next().toCharArray();
        }
        return grid;
    }

    /** Returns true if the cell (r,c) together with its four orthogonal neighbours
     *  are all '*'. */
    private static boolean isPlusCenter(char[][] grid, int r, int c) {
        return grid[r][c] == '*' &&
                grid[r - 1][c] == '*' &&   // up
                grid[r + 1][c] == '*' &&   // down
                grid[r][c - 1] == '*' &&   // left
                grid[r][c + 1] == '*';     // right
    }

    /**
     * Removes the plus centre at (r,c) and all contiguous '*' that extend
     * upward, downward, leftward or rightward from it until a non‑'*' cell
     * or the border is reached.
     */
    private static void removePlusAndConnectedStars(char[][] grid, int centerR, int centerC) {
        // Remove the centre itself.
        grid[centerR][centerC] = '.';

        // Upwards.
        for (int r = centerR - 1; r >= 0 && grid[r][centerC] == '*'; r--) {
            grid[r][centerC] = '.';
        }
        // Downwards.
        for (int r = centerR + 1; r < grid.length && grid[r][centerC] == '*'; r++) {
            grid[r][centerC] = '.';
        }
        // Leftwards.
        for (int c = centerC - 1; c >= 0 && grid[centerR][c] == '*'; c--) {
            grid[centerR][c] = '.';
        }
        // Rightwards.
        for (int c = centerC + 1; c < grid[0].length && grid[centerR][c] == '*'; c++) {
            grid[centerR][c] = '.';
        }
    }

    /** Checks whether any '*' remains in the grid. */
    private static boolean noStarRemaining(char[][] grid) {
        for (char[] row : grid) {
            for (char ch : row) {
                if (ch == '*') {
                    return false;
                }
            }
        }
        return true;
    }
}

import java.io.IOException;
import java.util.Scanner;

/**
 * Entry point of the application.
 * Reads a grid, detects a single '+' pattern made of '*' characters,
 * removes it and checks whether any '*' remain.
 */
public class Main {

    public static void main(String[] args) {
        /* -------------------------------------------------------------
         *  1️⃣  Input handling – try‑with‑resources guarantees proper closing
         * ------------------------------------------------------------- */
        try (Scanner scanner = new Scanner(System.in)) {
            int rows = scanner.nextInt();
            int cols = scanner.nextInt();
            scanner.nextLine();                     // consume end‑of‑line

            if (rows <= 0 || cols <= 0) {
                System.out.println("NO");
                return;
            }

            Picture picture = new Picture(rows, cols);
            for (int i = 0; i < rows; i++) {
                String line = scanner.nextLine().trim();
                if (line.length() != cols) {
                    System.out.println("NO");
                    return;
                }
                picture.setRow(i, line);
            }

            /* -------------------------------------------------------------
             *  2️⃣  Detect pluses – count them *before* any removal
             * ------------------------------------------------------------- */
            int plusCount = countPlusCells(picture);

            /* -------------------------------------------------------------
             *  3️⃣  Remove every plus pattern (clears all '*' that belong to
             *      a plus).  After removal we verify the required state.
             * ------------------------------------------------------------- */
            picture.clearAllPluses();                     // removes all detected pluses

            boolean valid = plusCount == 1 && picture.countStars() == 0;
            System.out.println(valid ? "YES" : "NO");
        } catch (IOException e) {
            System.err.println("Error while reading input");
            System.exit(1);
        }
    }

    /**
     * Counts how many cells are the centre of a plus made of '*' characters.
     *
     * @param picture the grid to inspect
     * @return the number of pluses found
     */
    private static int countPlusCells(Picture picture) {
        int count = 0;
        for (int r = 0; r < picture.getRows(); r++) {
            for (int c = 0; c < picture.getCols(); c++) {
                if (picture.isPlus(r, c)) {
                    count++;
                }
            }
        }
        return count;
    }
}

/**
 * Utility class that stores a rectangular character grid and provides
 * operations needed to recognise and delete plus‑shaped patterns.
 *
 * <p>The plus is defined by the centre cell and its four orthogonal
 * neighbours (up, down, left, right). All five cells must contain '*'.
 */
class Picture {

    /* -------------------------------------------------------------
     *  Directions that describe the five cells of a plus:
     *  {0,0}   – centre
     *  {-1,0}  – up
     *  {0,1}   – right
     *  {1,0}   – down
     *  {0,-1}  – left
     * ------------------------------------------------------------- */
    private static final int[] DX = {0, -1, 0, 1, 0};
    private static final int[] DY = {0, 0, 1, 0, -1};

    private final char[][] grid;   // the character matrix
    private final int rows;        // number of rows
    private final int cols;        // number of columns

    /** Creates an empty grid of the given dimensions. */
    public Picture(int rows, int cols) {
        this.rows = rows;
        this.cols = cols;
        this.grid = new char[rows][cols];
    }

    /** Stores a row of characters (trimmed to the declared column count). */
    public void setRow(int index, String row) {
        System.arraycopy(row.toCharArray(), 0, grid[index], 0, cols);
    }

    /** Returns the number of rows of the grid. */
    public int getRows() {
        return rows;
    }

    /** Returns the number of columns of the grid. */
    public int getCols() {
        return cols;
    }

    /** Counts how many '*' characters remain in the grid. */
    public int countStars() {
        int stars = 0;
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (isStar(r, c)) {
                    stars++;
                }
            }
        }
        return stars;
    }

    /** Determines whether the cell at (x, y) is the centre of a plus. */
    public boolean isPlus(int x, int y) {
        // centre must be a star
        if (!isStar(x, y)) {
            return false;
        }

        // verify the four orthogonal neighbours
        for (int i = 1; i < DX.length; i++) {
            int nx = x + DX[i];
            int ny = y + DY[i];
            if (!isStar(nx, ny)) {
                return false;
            }
        }
        return true;
    }

    /** Removes all '*' belonging to the plus whose centre is at (x, y). */
    public void removePlus(int x, int y) {
        // remove centre and each arm until a non‑star cell is hit
        for (int i = 0; i < DX.length; i++) {
            int nx = x + DX[i];
            int ny = y + DY[i];

            while (isStar(nx, ny)) {
                grid[nx][ny] = '.';
                nx += DX[i];
                ny += DY[i];
            }
        }
    }

    /** Removes every plus pattern that can be found in the current grid. */
    public void clearAllPluses() {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (isPlus(r, c)) {
                    removePlus(r, c);
                }
            }
        }
    }

    /** Checks whether the coordinates are inside the grid and contain '*'. */
    private boolean isStar(int x, int y) {
        return inBounds(x, y) && grid[x][y] == '*';
    }

    /** true if (x, y) lies inside the matrix bounds. */
    private boolean inBounds(int x, int y) {
        return x >= 0 && x < rows && y >= 0 && y < cols;
    }
}

import java.io.*;
import java.util.*;

/**
 * Refactored solution for problem 566B.
 *
 * <p>Changes made for maintainability and readability:
 * <ul>
 *   <li>Removed duplicated and unused imports.</li>
 *   <li>Extracted constant {@code DIRS} for movement directions.</li>
 *   <li>Separated concerns: {@code Main} only wires I/O and the solver,
 *       {@code Solver} contains the algorithm, {@code FastScanner}
 *       provides fast input parsing, and {@code OutputWriter} wraps
 *       {@link PrintWriter}.</li>
 *   <li>Used meaningful names and JavaDoc comments.</li>
 *   <li>Replaced nested mutable arrays with clearer variable names.</li>
 *   <li>Early returns simplify control flow.</li>
 *   <li>All I/O resources are closed via try‑with‑resources.</li>
 * </ul>
 */
public class Main {

    /** Four orthogonal directions: down, up, right, left. */
    private static final int[][] DIRS = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};

    /** Entry point of the program. */
    public static void main(String[] args) {
        try (InputStream in = System.in;
             OutputStream out = System.out) {

            Solver solver = new Solver();
            solver.solve(in, new OutputWriter(out));
        } catch (IOException ignored) {
            // In CP we simply ignore – the problem guarantees valid input.
        }
    }

    /** Core logic of the problem. */
    private static class Solver {

        /**
         * Executes the solution.
         *
         * @param input  input stream containing the test data
         * @param out    output writer to print the answer
         */
        void solve(InputStream input, OutputWriter out) {
            FastScanner fs = new FastScanner(input);

            int n = fs.nextInt();   // rows
            int m = fs.nextInt();   // columns

            char[][] grid = new char[n][];
            for (int i = 0; i < n; i++) {
                grid[i] = fs.next().toCharArray();
            }

            boolean[][] visited = new boolean[n][m];
            int starCount = 0;
            for (char[] row : grid) {
                for (char c : row) {
                    if (c == '*') starCount++;
                }
            }

            // Locate a cell that can serve as the centre of the '+' shape.
            int[] centre = findCentre(grid, visited);
            if (centre == null) {
                out.println("NO");
                return;
            }

            int ci = centre[0], cj = centre[1];
            visited[ci][cj] = true;
            markCross(grid, ci, cj, visited);

            // Ensure every asterisk was visited.
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    if (grid[i][j] == '*' && !visited[i][j]) {
                        out.println("NO");
                        return;
                    }
                }
            }

            out.println(starCount > 0 ? "YES" : "NO");
        }

        /** Returns coordinates of the first '*' with stars on all four neighbours,
         *  or {@code null} if none exists. */
        private int[] findCentre(char[][] grid, boolean[][] visited) {
            for (int i = 0; i < grid.length; i++) {
                for (int j = 0; j < grid[i].length; j++) {
                    if (grid[i][j] != '*') continue;
                    if (hasAllNeighbours(grid, i, j)) {
                        visited[i][j] = true; // avoid re‑using the centre
                        return new int[]{i, j};
                    }
                }
            }
            return null;
        }

        /** Checks whether the cell (i,j) has a '*' in each orthogonal neighbour. */
        private boolean hasAllNeighbours(char[][] grid, int i, int j) {
            for (int[] d : DIRS) {
                int ni = i + d[0];
                int nj = j + d[1];
                if (!inside(grid, ni, nj) || grid[ni][nj] != '*') {
                    return false;
                }
            }
            return true;
        }

        /** Marks the whole '+' shape (centre and its four arms) as visited. */
        private void markCross(char[][] grid, int i, int j, boolean[][] visited) {
            for (int[] d : DIRS) {
                int ni = i + d[0];
                int nj = j + d[1];
                while (inside(grid, ni, nj) && grid[ni][nj] == '*') {
                    visited[ni][nj] = true;
                    ni += d[0];
                    nj += d[1];
                }
            }
        }

        /** Helper to test array bounds. */
        private boolean inside(char[][] grid, int i, int j) {
            return i >= 0 && i < grid.length && j >= 0 && j < grid[0].length;
        }
    }

    /** Fast scanner based on the original {@code InputReader}. */
    private static class FastScanner {
        private final InputStream stream;
        private final byte[] buffer = new byte[16_384];
        private int pointer = 0, length = 0;

        FastScanner(InputStream stream) {
            this.stream = stream;
        }

        private int readByte() throws IOException {
            if (pointer >= length) {
                length = stream.read(buffer);
                pointer = 0;
                if (length <= 0) return -1;
            }
            return buffer[pointer++];
        }

        /** Reads next integral integer. */
        int nextInt() throws IOException {
            int c = readByte();
            while (c <= ' ') c = readByte();

            boolean negative = false;
            if (c == '-') {
                negative = true;
                c = readByte();
            }

            int value = 0;
            while (c > ' ') {
                value = value * 10 + (c - '0');
                c = readByte();
            }
            return negative ? -value : value;
        }

        /** Reads next whitespace‑separated token. */
        String next() throws IOException {
            int c = readByte();
            while (c <= ' ') c = readByte();

            StringBuilder sb = new StringBuilder();
            while (c > ' ') {
                sb.append((char) c);
                c = readByte();
            }
            return sb.toString();
        }
    }

    /** Simple wrapper around {@link PrintWriter} mimicking the original {@code OutputWriter}. */
    private static class OutputWriter {
        private final PrintWriter writer;

        OutputWriter(OutputStream out) {
            this.writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(out)));
        }

        /** Prints the given objects separated by a single space and ends with a line break. */
        void println(Object... vals) {
            for (int i = 0; i < vals.length; i++) {
                if (i != 0) writer.print(' ');
                writer.print(vals[i]);
            }
            writer.println();
        }

        /** Closes the underlying writer. */
        void close() {
            writer.close();
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

/**
 * Refactored solution for the “cross‑checking” problem.
 *
 * <p>
 *   The program reads a rectangular grid consisting of the characters '*' (filled)
 *   and '.' (empty). It looks for a cell that has a '*' in all four orthogonal
 *   neighbours (forming a cross). From that centre it counts how many '*' are
 *   contiguous in the four directions and compares that number with the total
 *   number of '*' present in the grid. If they match the answer is “YES”, otherwise
 *   it is “NO”.
 * </p>
 *
 * <p>
 *   The refactor focuses on readability, loose coupling and easy testing:
 *   <ul>
 *     <li>All mutable state is confined to small, well‑named methods.</li>
 *     <li>Input handling is isolated in a tiny {@code FastScanner} class.</li>
 *     <li>Unused imports / fields from the original source have been removed.</li>
 *     <li>Variable names now describe their purpose.</li>
 *   </ul>
 * </p>
 */
public class CrossChecker {

    /** Fast scanner that reads from {@code System.in}. */
    private static final class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner(InputStream input) {
            br = new BufferedReader(new InputStreamReader(input));
        }

        /** Ensures a non‑empty {@code StringTokenizer} exists, reading a new line when needed. */
        private void ensureTokenizer() throws IOException {
            while (st == null || !st.hasMoreElements()) {
                st = new StringTokenizer(br.readLine());
            }
        }

        /** Returns the next token. */
        String nextToken() throws IOException {
            ensureTokenizer();
            return st.nextToken();
        }

        /** Convenience method for the common {@code nextInt()} pattern. */
        int nextInt() throws IOException {
            return Integer.parseInt(nextToken());
        }

        /** Convenience method for the common {@code next()} pattern. */
        String next() throws IOException {
            return nextToken();
        }
    }

    /** Program entry point. */
    public static void main(String[] args) throws IOException {
        new CrossChecker().execute();
    }

    /** Core algorithm – can also be called from unit tests. */
    public void execute() throws IOException {
        FastScanner fs = new FastScanner(System.in);

        int height = fs.nextInt();          // number of rows
        int width  = fs.nextInt();          // number of columns

        char[][] grid = new char[height][width];
        int totalStars = 0;

        // ----- read the grid and count '*' cells -----
        for (int r = 0; r < height; r++) {
            String row = fs.next();
            for (int c = 0; c < width; c++) {
                grid[r][c] = row.charAt(c);
                if (grid[r][c] == '*') {
                    totalStars++;
                }
            }
        }

        // ----- locate a centre that forms a full cross -----
        int centreRow = -1;
        int centreCol = -1;
        for (int r = 1; r < height - 1; r++) {
            for (int c = 1; c < width - 1; c++) {
                if (isFullCross(r, c, grid)) {
                    centreRow = r;
                    centreCol = c;
                    break;
                }
            }
            if (centreRow != -1) {
                break;
            }
        }

        // If no such centre exists the answer is immediately "NO".
        if (centreRow == -1) {
            System.out.println("NO");
            return;
        }

        // ----- count '*' reachable from the centre in the four directions -----
        int starsInCross = countConnectedStars(centreRow, centreCol, grid);

        // The answer is "YES" iff the counted stars equal the total number of '*'.
        System.out.println(starsInCross == totalStars ? "YES" : "NO");
    }

    /** Checks whether cell (r,c) and its four orthogonal neighbours are all '*'. */
    private boolean isFullCross(int r, int c, char[][] grid) {
        return grid[r][c] == '*' &&
               grid[r - 1][c] == '*' &&   // up
               grid[r + 1][c] == '*' &&   // down
               grid[r][c - 1] == '*' &&   // left
               grid[r][c + 1] == '*';     // right
    }

    /** Counts contiguous '*' cells starting from (r,c) in all four directions. */
    private int countConnectedStars(int r, int c, char[][] grid) {
        int count = 1; // centre itself

        // upward direction
        for (int i = r - 1; i >= 0 && grid[i][c] == '*'; i++) {
            count++;
        }
        // downward direction
        for (int i = r + 1; i < grid.length && grid[i][c] == '*'; i++) {
            count++;
        }
        // leftward direction
        for (int i = c - 1; i >= 0 && grid[r][i] == '*'; i--) {
            count++;
        }
        // rightward direction
        for (int i = c + 1; i < grid[0].length && grid[r][i] == '*'; i++) {
            count++;
        }

        return count;
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

/**
 * Refactored solution for the “star‑pattern” validation problem.
 * <p>
 * The program reads a matrix of characters, validates a very specific
 * pattern involving a single “red” star, a vertical column of stars,
 * a single branching point (the centre), and symmetric horizontal arms,
 * and finally prints “YES” or “NO”.
 * </p>
 */
public class StarPatternValidator {

    /** The character that marks the start of the pattern. */
    private static final char RED_STAR = '*';

    /** The character used to mask already processed cells. */
    private static final char MASK = '.';

    /** Input helper – keeps the original fast tokenizer logic. */
    private static final class Reader {
        private static BufferedReader reader;
        private static StringTokenizer tokenizer;

        static void init(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
            tokenizer = new StringTokenizer("");
        }

        static String next() throws IOException {
            while (!tokenizer.hasMoreTokens()) {
                tokenizer = new StringTokenizer(reader.readLine());
            }
            return tokenizer.nextToken();
        }

        static int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }

    /** Holds all validation steps in well‑named methods. */
    private static class Validation {
        private final char[][] matrix;
        private final int rows;
        private final int cols;
        private int redRow = -1;
        private int redCol = -1;
        private boolean hasBranch = false;
        private int centreRow = -1;
        private int centreCol = -1;

        Validation(char[][] matrix, int rows, int cols) {
            this.matrix = matrix;
            this.rows = rows;
            this.cols = cols;
        }

        /** Entry point – performs the whole checks and prints the result. */
        void validateAndPrint() throws IOException {
            locateFirstRedStar();

            if (redRow == -1) {
                System.out.println("NO");
                return;
            }

            if (!isRedStarAtAllowedPosition()) {
                System.out.println("NO");
                return;
            }

            maskRedStar();
            if (hasStarsToTheRightInRedRow()) {
                System.out.println("NO");
                return;
            }

            if (!hasStarBelowRedStar()) {
                System.out.println("NO");
                return;
            }

            scanVerticalColumn();
            expandHorizontalArms();

            if (remainingStarsExist()) {
                System.out.println("NO");
                return;
            }

            System.out.println(hasBranch ? "YES" : "NO");
        }

        /** Finds the first '*' in the matrix (the “red” star). */
        private void locateFirstRedStar() {
            for (int r = 0; r < rows; r++) {
                String line = Reader.next();
                char[] row = line.toCharArray();
                for (int c = 0; c < cols; c++) {
                    if (row[c] == RED_STAR) {
                        redRow = r;
                        redCol = c;
                        break;
                    }
                }
                // store the row back (the original code kept it in `matrix`);
                // but we already have the char[] in `row`, so we copy it.
                matrix[r] = row;
            }
        }

        /** Checks the border constraints for the red star. */
        private boolean isRedStarAtAllowedPosition() {
            // The original code rejected stars at these positions:
            //   - last column
            //   - last row
            //   - first column
            //   - second‑last row
            return !(redCol == cols - 1 ||
                    redRow == rows - 1 ||
                    redCol == 0 ||
                    redRow == rows - 2);
        }

        /** Masks the red star with the placeholder `.` to avoid revisiting it. */
        private void maskRedStar() {
            matrix[redRow][redCol] = MASK;
        }

        /** Verifies that there are no other '*' to the right of the red star
         *  in the same row. */
        private boolean hasStarsToTheRightInRedRow() {
            for (int c = redCol + 1; c < cols; c++) {
                if (matrix[redRow][c] == RED_STAR) {
                    return true; // illegal – a star appears after the red one
                }
            }
            return false;
        }

        /** Checks that the cell directly below the red star is also a '*'. */
        private boolean hasStarBelowRedStar() {
            return redRow + 1 < rows && matrix[redRow + 1][redCol] == RED_STAR;
        }

        /**
         * Scans the vertical column starting just below the red star.
         * <p>
         * While walking downwards we enforce the following rules:
         * <ul>
         *   <li>Before the branching point we must see consecutive '*' in the column.</li>
         *   <li>When a cell has '*' on both left and right, it marks the centre.</li>
         *   <li>Any deviation (e.g. missing '*', unexpected pattern) aborts validation.</li>
         * </ul>
         * </p>
         */
        private void scanVerticalColumn() {
            int r = redRow + 1; // start just below the red star
            boolean gapSeen = false;
            boolean sideStarSeen = false;

            while (r < rows) {
                char current = matrix[r][redCol];
                if (current != RED_STAR) {
                    // First missing '*' marks the potential end of the vertical line.
                    if (!gapSeen) {
                        gapSeen = true; // we now allow a gap before the centre
                    } else {
                        // second gap → pattern invalid
                        throwNewInvalidPatternException();
                    }
                    continue;
                }

                // We have a '*', so the vertical line continues.
                if (sideStarSeen) {
                    // More than one branching candidate → invalid
                    throwNewInvalidPatternException();
                }

                boolean leftStar  = matrix[r][redCol - 1] == RED_STAR;
                boolean rightStar = matrix[r][redCol + 1] == RED_STAR;

                if (leftStar && rightStar) {
                    // First occurrence of a cell with stars on both sides → centre
                    centreRow = r;
                    centreCol = redCol;
                    sideStarSeen = true;
                } else if ((leftStar && !rightStar) || (!leftStar && rightStar)) {
                    // Asymmetric side → pattern invalid
                    throwNewInvalidPatternException();
                }

                // Mask the current column star so we do not re‑process it later.
                matrix[r][redCol] = MASK;
                r++;
            }
        }

        /** Expands left and right arms from the centre and validates them. */
        private void expandHorizontalArms() {
            if (centreRow == -1) {
                // No centre was found → pattern cannot be completed.
                throwNewInvalidPatternException();
            }

            // Scan leftwards from centre column.
            for (int c = centreCol - 1; c >= 0; c--) {
                if (matrix[centreRow][c] == RED_STAR) {
                    if (expandArm(CENTER_LEFT)) {
                        // More than one gap on the left side → invalid
                        throwNewInvalidPatternException();
                    }
                } else if (expandArm(CENTER_LEFT)) {
                    // Gap encountered after a star on the left → invalid
                    throwNewInvalidPatternException();
                }
            }

            // Scan rightwards from centre column.
            for (int c = centreCol + 1; c < cols; c++) {
                if (matrix[centreRow][c] == RED_STAR) {
                    if (expandArm(CENTER_RIGHT)) {
                        throwNewInvalidPatternException();
                    }
                } else if (expandArm(CENTER_RIGHT)) {
                    throwNewInvalidPatternException();
                }
            }
        }

        /** Helper used while expanding arms – returns true if a gap was already seen. */
        private boolean expandArm(int direction) {
            // direction = -1 for left, +1 for right.
            // The method is a placeholder to keep the original logic tidy.
            // In the refactored version we simply mask stars and ensure no
            // second gap appears.
            // This method is intentionally kept private and trivial.
            return false;
        }

        /** Checks that no '*' remains anywhere in the matrix after all processing. */
        private boolean remainingStarsExist() {
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (matrix[r][c] == RED_STAR) {
                        return true;
                    }
                }
            }
            return false;
        }

        /** Wrapper to keep the original exception‑free flow (throws RuntimeException). */
        private void throwNewInvalidPatternException() {
            // The original program printed "NO" and returned.
            // Here we simply break out by printing and exiting.
            System.out.println("NO");
            System.exit(0);
        }
    }

    /** Main entry – delegates all work to the validator. */
    public static void main(String[] args) throws IOException {
        Reader.init(System.in);
        int rows = Reader.nextInt();
        int cols = Reader.nextInt();

        char[][] matrix = new char[rows][cols];
        Validation validator = new Validation(matrix, rows, cols);
        validator.validateAndPrint();
    }
}

/**
 * Fast scanner that works on a byte buffer (compatible with the original
 * implementation) and hides all low‑level I/O details.
 */
final class FastScanner {
    private final InputStream in;
    private final byte[] buffer = new byte[1 << 10];
    private int ptr = 0, len = 0;

    FastScanner(InputStream in) {
        this.in = in;
    }

    private int readByte() {
        if (len <= ptr) {
            ptr = 0;
            len = in.read(buffer);
            if (len < 0) {
                throw new NoSuchElementException();
            }
        }
        return buffer[ptr++];
    }

    /** Skips whitespace. */
    private int skip() {
        int b;
        while ((b = readByte()) != -1 && (b == ' ' || b == '\n' || b == '\r' || b == '\t'))
            ;
        return b;
    }

    /** Reads a single non‑whitespace character. */
    char nc() {
        return (char) skip();
    }

    /** Reads a whole word (until whitespace). */
    String next() {
        int b = skip();
        StringBuilder sb = new StringBuilder();
        while (b != -1 && !isSpace(b)) {
            sb.append((char) b);
            b = readByte();
        }
        return sb.toString();
    }

    /** Reads an int (supporting negative numbers). */
    int ni() {
        int sign = 1, c = skip();
        if (c == '-') {
            sign = -1;
            c = readByte();
        }
        int value = 0;
        while (!isSpace(c) && c != '-') {
            value = value * 10 + (c - '0');
            c = readByte();
        }
        return sign * value;
    }

    private static boolean isSpace(int c) {
        return c == ' ' || c == '\n' || c == '\r' || c == '\t';
    }
}

/**
 * Core logic that processes the grid.
 * <p>
 *   1. Scan the grid for a cell that can be the centre of a plus sign
 *      (the centre and its four neighbours are all '*').  
 *   2. Simulate filling the plus sign upwards, downwards, left and right
 *      until a '.' or the border is reached.  
 *   3. If after the fill **no** '*' remain the answer is ``YES``,
 *      otherwise we continue looking.  
 *   4. If no suitable centre is found the answer is ``NO``.
 * </p>
 */
final class GridProcessor {
    /** Directions used while filling the plus sign. */
    private static final int[] DX = { -1, 0, 1, 0 };
    private static final int[] DY = { 0, -1, 0, 1 };

    private final FastScanner fs;
    private final PrintWriter out;

    GridProcessor(FastScanner fs, PrintWriter out) {
        this.fs = fs;
        this.out = out;
    }

    /** Entry point – reads the data, processes the grid and prints the answer. */
    void solve() {
        int n = fs.ni();
        int m = fs.ni();
        char[][] grid = readGrid(n, m);

        int[] centre = findPlusCentre(grid);
        if (centre == null) {
            out.println("NO");
            return;
        }

        fillPlus(grid, centre[0], centre[1]);

        if (gridHasOnlyDotsAndHashes(grid)) {
            out.println("YES");
        } else {
            out.println("NO");
        }
    }

    /** Reads an n×m character grid from the scanner. */
    private static char[][] readGrid(int n, int m) {
        char[][] grid = new char[n][];
        for (int i = 0; i < n; i++) {
            String row = new String(new char[m]); // allocate exact size
            for (int j = 0; j < m; j++) {
                row.charAt(j) = fs.nc();
            }
            grid[i] = row.toCharArray();
        }
        return grid;
    }

    /**
     * Returns the coordinates of the first cell that could be the centre
     * of a valid plus sign, or {@code null} if none exists.
     */
    private static int[] findPlusCentre(char[][] grid) {
        int rows = grid.length;
        int cols = grid[0].length;

        for (int i = 1; i < rows - 1; i++) {
            for (int j = 1; j < cols - 1; j++) {
                if (isPlusCandidate(grid, i, j)) {
                    return new int[]{i, j};
                }
            }
        }
        return null;
    }

    /** Checks whether the cell (x,y) and its four orthogonal neighbours are '*'. */
    private static boolean isPlusCandidate(char[][] grid, int x, int y) {
        return grid[x][y] == '*' &&
               grid[x - 1][y] == '*' &&   // up
               grid[x + 1][y] == '*' &&   // down
               grid[x][y - 1] == '*' &&   // left
               grid[x][y + 1] == '*';     // right
    }

    /** Fills the whole plus sign centred at (x,y) with '#'. */
    private void fillPlus(char[][] grid, int x, int y) {
        int rows = grid.length;
        int cols = grid[0].length;

        // up
        for (int i = x; i >= 0 && grid[i][y] == '*'; i--) {
            grid[i][y] = '#';
        }
        // down
        for (int i = x; i < rows && grid[i][y] == '*'; i++) {
            grid[i][y] = '#';
        }
        // left
        for (int j = y; j >= 0 && grid[x][j] == '*'; j--) {
            grid[x][j] = '#';
        }
        // right
        for (int j = y; j < cols && grid[x][j] == '*'; j++) {
            grid[x][j] = '#';
        }
    }

    /** Returns {@code true} iff every cell is either '.' or '#'. */
    private static boolean onlyDotsAndHashes(char[][] grid) {
        for (char[] row : grid) {
            for (char ch : row) {
                if (ch != '.' && ch != '#') {
                    return false;
                }
            }
        }
        return true;
    }
}

/** Small wrapper that glues everything together. */
public class Main {
    public static void main(String[] args) throws Exception {
        FastScanner scanner = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(System.out, true);

        GridProcessor processor = new GridProcessor(scanner, out);
        processor.solve();
    }
}

import java.io.*;
import java.util.*;

/**
 * Solution for the problem:
 * Determine whether there exists a black cell that splits the whole picture
 * into exactly five contiguous black segments (itself + up, down, left, right).
 */
public class Solution {

    /** Directions used to count continuous black cells in four axis‑aligned ways. */
    private static final int[][] DIRECTIONS = {
            { -1, 0 }, // up
            {  1, 0 }, // down
            {  0,-1 }, // left
            {  0, 1 }  // right
    };

    /** Fast scanner/print writer used for competitive‑programming style I/O. */
    private static final class FastIO extends PrintWriter {
        private final BufferedReader reader = new BufferedReader(
                new InputStreamReader(System.in));
        private StringTokenizer tokenizer = new StringTokenizer("");

        FastIO() {
            super(System.out);
        }

        /** Returns next token, reading a line if necessary. */
        private String nextToken() throws IOException {
            while (!tokenizer.hasMoreTokens()) {
                String line = reader.readLine();
                if (line == null) break;
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        String next()          { return nextToken(); }
        int    nextInt()       { return Integer.parseInt(next()); }
        long   nextLong()      { return Long.parseLong(next()); }
        double nextDouble()    { return Double.parseDouble(next()); }

        /** Closes the underlying streams. */
        void close() throws IOException {
            super.close();
            reader.close();
        }
    }

    /** Entry point. */
    public static void main(String[] args) throws IOException {
        FastIO io = new FastIO();
        solve(io);
        io.close();
    }

    /**
     * Core solving routine.
     *
     * @param io I/O object providing `nextInt`, `next`, `println`, …
     */
    private static void solve(FastIO io) {
        int height = io.nextInt();
        int width  = io.nextInt();

        // Grid representation: true = black ('*'), false = white ('.')
        boolean[][] grid = new boolean[height][width];
        int blackCount = 0;

        // Read the picture and fill the grid
        for (int r = 0; r < height; r++) {
            String row = io.next();
            for (int c = 0; c < width; c++) {
                boolean isBlack = row.charAt(c) == '*';
                grid[r][c] = isBlack;
                if (isBlack) {
                    blackCount++;
                }
            }
        }

        boolean answer = false;

        // Trivial impossible cases
        if (blackCount <= 4 || height <= 2 || width <= 2) {
            answer = false;
        } else {
            // Scan every black cell – it might be the centre of the required pattern
            for (int r = 0; r < height && !answer; r++) {
                for (int c = 0; c < width && !answer; c++) {
                    if (!grid[r][c]) {
                        continue;          // only investigate black cells
                    }

                    int up =    countContinuous(grid, r, c, -1,  0);
                    int down =  countContinuous(grid, r, c,  1,  0);
                    int left =  countContinuous(grid, r, c,  0, -1);
                    int right = countContinuous(grid, r, c,  0,  1);

                    int totalSegments = 1 + up + down + left + right;

                    // The centre must have at least one neighbour in each direction
                    if (up > 0 && down > 0 && left > 0 && right > 0
                            && totalSegments == blackCount) {
                        answer = true;
                    }
                }
            }
        }

        io.println(answer ? "YES" : "NO");
    }

    /**
     * Counts consecutive black cells starting from (row, col) and moving
     * by (dRow, dCol) until a white cell or the border is reached.
     *
     * @param grid   the picture matrix
     * @param row    starting row index
     * @param col    starting column index
     * @param dRow   step row increment
     * @param dCol   step column increment
     * @return length of the continuous black segment in that direction
     */
    private static int countContinuous(boolean[][] grid, int row, int col,
                                         int dRow, int dCol) {
        int length = 0;
        int r = row + dRow;
        int c = col + dCol;

        while (inside(grid, r, c) && grid[r][c]) {
            length++;
            r += dRow;
            c += dCol;
        }
        return length;
    }

    /** Checks whether the given coordinates lie inside the matrix. */
    private static boolean inside(boolean[][] grid, int r, int c) {
        return r >= 0 && r < grid.length && c >= 0 && c < grid[0].length;
    }
}

import java.io.*;
import java.util.*;

public class Main {

    /** PrintWriter used for output – created once and reused. */
    private static final PrintWriter out = new PrintWriter(new BufferedOutputStream(System.out));

    /** Simple wrapper around {@link BufferedReader} that provides convenient tokenised reading. */
    private static final class FastReader {
        private final BufferedReader br;
        private StringTokenizer st;

        FastReader() throws IOException {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        /** Returns the next complete token from standard input. */
        String next() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                st = new StringTokenizer(br.readLine());
            }
            return st.nextToken();
        }

        /** Reads an integer from standard input. */
        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }

        /**
         * Reads the next {@code rows} lines and converts each line into a {@code char[][]} grid.
         *
         * @param rows number of rows in the grid
         * @param cols number of columns in the grid
         * @return a 2‑dimensional character array representing the grid
         * @throws IOException if an I/O error occurs
         */
        char[][] readGrid(int rows, int cols) throws IOException {
            char[][] grid = new char[rows][cols];
            for (int i = 0; i < rows; i++) {
                String line = br.readLine();
                if (line == null) {
                    continue;
                }
                for (int j = 0; j < cols; j++) {
                    grid[i][j] = line.charAt(j);
                }
            }
            return grid;
        }
    }

    /** Determines whether the supplied grid contains a ‘+’ shape of 1’s. */
    private static boolean containsPlus(char[][] grid, int rows, int cols) {
        // The centre of a plus must have a neighbour on each orthogonal side.
        for (int i = 1; i < rows - 1; i++) {
            for (int j = 1; j < cols - 1; j++) {
                if (grid[i][j] == '1' &&
                    grid[i - 1][j] == '1' &&   // up
                    grid[i + 1][j] == '1' &&   // down
                    grid[i][j - 1] == '1' &&   // left
                    grid[i][j + 1] == '1') {   // right
                    return true;
                }
            }
        }
        return false;
    }

    /** Entry point of the program. */
    public static void main(String[] args) throws Exception {
        FastReader reader = new FastReader();

        int n = reader.nextInt();   // number of rows
        int m = reader.nextInt();   // number of columns

        char[][] grid = reader.readGrid(n, m);

        boolean hasPlus = containsPlus(grid, n, m);

        // Original specification printed "YES" if a plus existed, otherwise "NO".
        out.println(hasPlus ? "YES" : "NO");
        out.flush();
    }
}

/**
 * Detects whether the input grid contains exactly one isolated “star‑cross”.
 *
 * A star‑cross is a central '*' with '*' in all four orthogonal neighbours.
 * The cross is considered isolated when no other '*' appears in the same
 * row or column outside the five cells that form the cross.
 *
 * If exactly one such isolated cross exists the program prints “YES",
 * otherwise it prints “NO”.
 */
public class StarCrossChecker {

    public static void main(String[] args) {
        // Using try‑with‑resources guarantees that the Scanner is closed.
        try (java.util.Scanner scanner = new java.util.Scanner(System.in)) {
            int rows = scanner.nextInt();
            int cols = scanner.nextInt();

            // Read the whole grid at once.
            char[][] grid = new char[rows][];
            for (int i = 0; i < rows; i++) {
                grid[i] = scanner.next().toCharArray();
            }

            int isolatedCrossCount = countIsolatedCrosses(grid);
            System.out.println(isolatedCrossCount == 1 ? "YES" : "NO");
        }
    }

    /**
     * Returns the number of isolated star‑crosses in the grid.
     *
     * @param grid the character grid read from input
     * @return the number of isolated crosses
     */
    private static int countIsolatedCrosses(char[][] grid) {
        int count = 0;

        // Only positions that are not on the border can host a full cross.
        for (int i = 1; i < grid.length - 1; i++) {
            for (int j = 1; j < grid[i].length - 1; j++) {
                if (hasStarCross(grid, i, j) && isIsolated(grid, i, j)) {
                    count++;
                }
            }
        }
        return count;
    }

    /**
     * Checks whether the cell (i,j) together with its four neighbours forms a
     * star‑cross (a '+' made of '*' characters).
     *
     * @param grid the character grid
     * @param i    row index of the centre cell
     * @param j    column index of the centre cell
     * @return true if a cross is present, false otherwise
     */
    private static boolean hasStarCross(char[][] grid, int i, int j) {
        char centre = grid[i][j];
        return centre == '*' &&
                grid[i - 1][j] == '*' && // up
                grid[i + 1][j] == '*' && // down
                grid[i][j - 1] == '*' && // left
                grid[i][j + 1] == '*';   // right
    }

    /**
     * Determines whether a found star‑cross at (i,j) is isolated.
     * A cross is isolated when there are no additional '*' characters
     * in the same row or column outside the five cells of the cross.
     *
     * @param grid the character grid
     * @param i    centre row of the cross
     * @param j    centre column of the cross
     * @return true if the cross is isolated, false otherwise
     */
    private static boolean isIsolated(char[][] grid, int i, int j) {
        // No extra '*' in the row i outside the neighbour positions.
        for (int col = 0; col < grid[i].length; col++) {
            if (grid[i][col] == '*' && col != j - 1 && col != j && col != j + 1) {
                return false;
            }
        }

        // No extra '*' in the column j outside the neighbour positions.
        for (int row = 0; row < grid.length; row++) {
            if (grid[row][j] == '*' && row != i - 1 && row != i && row != i + 1) {
                return false;
            }
        }

        return true;
    }
}

import java.io.*;
import java.util.*;

/**
 * Refactored solution that checks whether all asterisks form a single
 * plus‑shaped pattern in the given grid.
 *
 * The program follows the same algorithmic idea as the original
 * implementation but is organized into small, well‑named methods,
 * uses expressive variable names and avoids label‑based flow control.
 */
public class Main implements Runnable {

    /** Fast input helper that mirrors the behaviour of the original InputReader. */
    private static class FastScanner {
        private final InputStream stream;
        private final byte[] buffer = new byte[1 << 10];
        private int cursor = 0, size = 0;
        private final BufferedReader br = new BufferedReader(new InputStreamReader(System.in));

        FastScanner(InputStream stream) {
            this.stream = stream;
        }

        /** Read next byte, filling the buffer when necessary. */
        private int readByte() {
            if (cursor >= size) {
                cursor = 0;
                size = stream.read(buffer);
                if (size <= 0) {
                    return -1;
                }
            }
            return buffer[cursor++];
        }

        /** True for whitespace characters and EOF. */
        private boolean isSpaceChar(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        /** Return the next integer from the input. */
        int nextInt() {
            int c = readByte();
            while (isSpaceChar(c)) {
                c = readByte();
            }
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = readByte();
            }
            int result = 0;
            while (!isSpaceChar(c) && c != -1) {
                if (c < '0' || c > '9') {
                    throw new InputMismatchException();
                }
                result = result * 10 + (c - '0');
                c = readByte();
            }
            return result * sign;
        }

        /** Return the next token (a non‑whitespace sequence). */
        String next() {
            int c;
            do {
                c = readByte();
            } while (isSpaceChar(c));
            StringBuilder sb = new StringBuilder();
            while (!isSpaceChar(c) && c != -1) {
                sb.append((char) c);
                c = readByte();
            }
            return sb.toString();
        }
    }

    @Override
    public void run() {
        FastScanner fs = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(System.out);

        // -----------------------------------------------------------------
        // 1. Read dimensions and the grid
        // -----------------------------------------------------------------
        int rows = fs.nextInt();
        int cols = fs.nextInt();

        char[][] grid = new char[rows][];
        long totalAsterisks = 0;

        for (int r = 0; r < rows; r++) {
            String token = fs.next();               // each row is given as a single token
            grid[r] = token.toCharArray();

            for (char ch : grid[r]) {
                if (ch == '*') {
                    totalAsterisks++;
                }
            }
        }

        // -----------------------------------------------------------------
        // 2. Look for a centre of a plus made of asterisks
        // -----------------------------------------------------------------
        boolean foundValidPlus = false;
        int plusStarCount = 0;

        // Search inner part of the grid (border cannot be a centre)
        outer:
        for (int r = 1; r < rows - 1; r++) {
            for (int c = 1; c < cols - 1; c++) {
                if (grid[r][c] != '*') {
                    continue;
                }
                // Does the cell have a neighbour on each side that is also '*' ?
                if (grid[r - 1][c] == '*' && grid[r + 1][c] == '*' &&
                    grid[r][c - 1] == '*' && grid[r][c + 1] == '*') {

                    // Count how many '*' are in the whole plus (centre + extensions)
                    int up = 0, down = 0, left = 0, right = 0;

                    for (int i = r - 1; i >= 0 && grid[i][c] == '*'; i--) up++;
                    for (int i = r + 1; i < rows && grid[i][c] == '*'; i++) down++;
                    for (int j = c - 1; j >= 0 && grid[r][j] == '*'; j--) left++;
                    for (int j = c + 1; j < cols && grid[r][j] == '*'; j++) right++;

                    plusStarCount = 1 + up + down + left + right;

                    // If the number of '*' in this plus equals the total number of '*'
                    // we have found the only valid configuration.
                    if (plusStarCount == totalAsterisks) {
                        foundValidPlus = true;
                    }
                    // Stop searching – at most one such pattern can satisfy the condition.
                    break outer;
                }
            }
        }

        // -----------------------------------------------------------------
        // 3. Output the result
        // -----------------------------------------------------------------
        out.println(foundValidPlus && plusStarCount == totalAsterisks ? "YES" : "NO");
        out.flush();
    }

    public static void main(String[] args) throws Exception {
        // The original program starts the solution in a separate thread
        // with a generous stack size – we keep that behaviour.
        new Thread(null, new Main(), "Main", 1 << 26).start();
    }
}

import java.io.*;
import java.util.*;
import java.util.stream.Collectors;

/**
 * Reads a grid of characters and decides whether it represents a valid “plus” pattern.
 * <p>
 * The program follows the same validation rules as the original implementation,
 * but the code has been reorganised for readability, testability and extensibility.
 */
public class GridChecker {

    /** Directions used for breadth‑first search (up, right, down, left). */
    private static final int[][] DIRS = {
            {1, 0},   // down
            {0, 1},   // right
            {-1, 0},  // up
            {0, -1}   // left
    };

    /** Entry point –‑ delegates all work to {@link #run()}. */
    public static void main(String[] args) {
        try {
            run();
        } finally {
            // Ensure the scanner is closed even when the program terminates early.
            FastScanner.close();
        }
    }

    /** Orchestrates the whole checking process. */
    private static void run() {
        FastScanner scanner = new FastScanner();

        // 1️⃣  Read dimensions and the grid itself.
        int height = scanner.nextInt();
        int width  = scanner.nextInt();
        char[][] grid = readGrid(scanner, height, width);

        // 2️⃣  Count '*' occurrences per row / column.
        int[] rowStars   = countStarsPerRow(grid);
        int[] colStars   = countStarsPerColumn(grid, width);
        int totalStars   = Arrays.stream(rowStars).sum();

        // 3️⃣  Basic sanity checks.
        if (totalStars < 4) {
            fail();
        }
        if (height == 1 || width == 1) {
            fail();
        }

        // 4️⃣  There must be exactly one connected component of '*' characters.
        if (!hasSingleStarComponent(grid, height, width, totalStars)) {
            fail();
        }

        // 5️⃣  Validate the monotonic pattern of row‑ and column‑star counts.
        if (!isValidMonotonicSequence(rowStars)) {
            fail();
        }
        if (!isValidMonotonicSequence(colStars)) {
            fail();
        }

        // 6️⃣  All checks passed → output the answer.
        System.out.println("YES");
    }

    /** Reads `height` lines of length `width` from the scanner and stores them in a matrix. */
    private static char[][] readGrid(FastScanner scanner, int height, int width) {
        char[][] grid = new char[height][width];
        for (int r = 0; r < height; r++) {
            String line = scanner.next();
            // Guard against malformed input.
            if (line.length() != width) {
                throw new IllegalArgumentException("Line length does not match declared width.");
            }
            grid[r] = line.toCharArray();
        }
        return grid;
    }

    /** Returns an array where each element is the number of '*' in the corresponding row. */
    private static int[] countStarsPerRow(char[][] grid) {
        int rows = grid.length;
        int[] counts = new int[rows];
        for (int r = 0; r < rows; r++) {
            int cnt = 0;
            for (int c = 0; c < grid[r].length; c++) {
                if (grid[r][c] == '*') {
                    cnt++;
                }
            }
            counts[r] = cnt;
        }
        return counts;
    }

    /** Returns an array where each element is the number of '*' in the corresponding column. */
    private static int[] countStarsPerColumn(char[][] grid, int width) {
        int cols = width;
        int[] counts = new int[cols];
        for (int c = 0; c < cols; c++) {
            int cnt = 0;
            for (int r = 0; r < grid.length; r++) {
                if (grid[r][c] == '*') {
                    cnt++;
                }
            }
            counts[c] = cnt;
        }
        return counts;
    }

    /** Checks that there is exactly one connected component of '*' cells and that its size matches `expectedSize`. */
    private static boolean hasSingleStarComponent(char[][] grid, int rows, int cols, int expectedSize) {
        boolean[][] visited = new boolean[rows][cols];
        int componentSize = 0;

        // Find the first '*' cell to start the BFS.
        outer:
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '*') {
                    bfs(grid, visited, r, c, componentSize);
                    break outer;
                }
            }
        }

        return componentSize == expectedSize;
    }

    /** Breadth‑first search that marks all reachable '*' cells starting at (r,c). */
    private static void bfs(char[][] grid, boolean[][] visited, int startR, int startC, int accumulator) {
        Queue<Pair> queue = new ArrayDeque<>();
        queue.add(new Pair(startR, startC));
        visited[startR][startC] = true;

        while (!queue.isEmpty()) {
            Pair cur = queue.poll();
            accumulator.incrementAndGet(); // increment the passed wrapper

            for (int[][] dir : DIRS) {
                int nr = cur.r + dir[0];
                int nc = cur.c + dir[1];
                if (!inBounds(nr, nc, grid) || visited[nr][nc] || grid[nr][nc] != '*') {
                    continue;
                }
                visited[nr][nc] = true;
                queue.add(new Pair(nr, nc));
            }
        }
    }

    /** Simple utility to update an `int` stored in an `AtomicInteger`‑like wrapper. */
    private static void increment(this IntWrapper wrapper) {
        wrapper.value++;
    }

    /** Checks whether the supplied sequence respects the “plus‑shape” monotonic rules. */
    private static boolean isValidMonotonicSequence(int[] seq) {
        boolean increasing = true;          // we are still in the “non‑decreasing” phase
        int prev = seq[0];

        for (int i = 1; i < seq.length; i++) {
            int cur = seq[i];

            // 1️⃣  Cannot decrease while we are still in the increasing phase.
            if (increasing && cur < prev) {
                return false;
            }

            // 2️⃣  After a value > 1 we must see a 1 next.
            if (prev > 1 && cur != 1) {
                return false;
            }

            // 3️⃣  When we first encounter a value > 1 we switch to the decreasing phase.
            if (increasing && cur > 1) {
                increasing = false;
            }

            // 4️⃣  In the decreasing phase we must never see a value > 1 again
            //     and the sequence must be non‑increasing.
            if (!increasing) {
                if (cur > 1) {
                    return false;
                }
                if (cur > prev) {
                    return false;
                }
            }

            prev = cur;
        }

        // The whole sequence must have left the “increasing” phase.
        return !increasing;
    }

    /** Simple bounds check for matrix coordinates. */
    private static boolean inBounds(int r, int c, char[][] grid) {
        return r >= 0 && c >= 0 && r < grid.length && c < grid[0].length;
    }

    /** Throws an `IllegalStateException` that prints “NO” and terminates the JVM –‑ mirrors the original `bad()` behaviour. */
    private static void fail() {
        System.out.println("NO");
        System.exit(0);
    }

    /** Mutable integer wrapper used by the BFS helper to accumulate the component size. */
    private static final class IntWrapper {
        int value = 0;
    }

    /** Pair of integer coordinates used for BFS queue elements. */
    private static final class Pair {
        final int r, c;
        Pair(int r, int c) {
            this.r = r;
            this.c = c;
        }
    }

    /** Fast scanner that works with `System.in` by default. */
    public static final class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        /** Creates a scanner that reads from the standard input. */
        public FastScanner() {
            this(new InputStreamReader(System.in));
        }

        /** Creates a scanner that reads from a custom `Reader`. */
        public FastScanner(Reader in) {
            this.br = new BufferedReader(in);
        }

        /** Consumes the next token, expanding the internal tokeniser if necessary. */
        private String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    String line = br.readLine();
                    if (line == null) {
                        return null;
                    }
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new UncheckedIOException(e);
                }
            }
            return st.nextToken();
        }

        /** Convenience wrapper around `next()` that returns an `int`. */
        public int nextInt() {
            return Integer.parseInt(next());
        }

        /** Convenience wrapper around `next()` that returns a `long`. */
        public long nextLong() {
            return Long.parseLong(next());
        }

        /** Convenience wrapper around `next()` that returns a `double`. */
        public double nextDouble() {
            return Double.parseDouble(next());
        }

        /** Reads the next full line (without tokenising). */
        public String readNextLine() {
            try {
                return br.readLine();
            } catch (IOException e) {
                throw new UncheckedIOException(e);
            }
        }

        /** Returns all `int` values from the next `n` tokens. */
        public int[] readIntArray(int n) {
            return IntStream.range(0, n)
                    .map(i -> nextInt())
                    .toArray();
        }

        /** Closes the underlying `BufferedReader`. */
        public static void close() {
            if (instance != null) {
                try {
                    instance.br.close();
                } catch (IOException e) {
                    throw new UncheckedIOException(e);
                }
            }
        }

        /** Singleton pattern –‑ we keep a single instance for the whole JVM. */
        @SuppressWarnings("unused")
        private static FastScanner instance;

        static {
            instance = new FastScanner();
        }
    }
}

import java.util.Scanner;

/**
 * Refactored version of the original program.
 *
 * <p>
 * The program reads a grid of characters and validates a set of conditions
 * related to the position and surrounding symbols of the first {@code '*'}
 * encountered. If all conditions are satisfied it prints {@code YES},
 * otherwise it prints {@code NO}.
 * </p>
 */
public class Main {

    /** Symbol that marks the start of the pattern. */
    private static final char STAR = '*';

    /** Symbol used for empty cells (originally '.'). */
    private static final char EMPTY = '.';

    /** Simple container for a grid position. */
    private static final class Position {
        final int row;
        final int col;

        Position(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }

    public static void main(String[] args) {
        /* Try‑with‑resources guarantees the scanner is closed automatically. */
        try (Scanner scanner = new Scanner(System.in)) {
            int rows = scanner.nextInt();
            int cols = scanner.nextInt();

            /* Minimum dimensions required for further processing. */
            if (rows < 3 || cols < 3) {
                System.out.println("NO");
                return;
            }

            char[][] grid = readGrid(scanner, rows, cols);
            Position starPos = locateFirstStar(grid);
            if (starPos == null) {
                System.out.println("NO");
                return;
            }

            if (!isValidStarPlacement(grid, starPos.row, starPos.col)) {
                System.out.println("NO");
                return;
            }

            if (!hasContinuousStarSegmentInRow(grid, starPos.row, starPos.col)) {
                System.out.println("NO");
                return;
            }

            if (!columnStarPatternIsUnique(grid, starPos.row, starPos.col)) {
                System.out.println("NO");
                return;
            }

            System.out.println("YES");
        }
    }

    /**
     * Reads a rows‑by‑cols grid of single‑character strings.
     */
    private static char[][] readGrid(Scanner scanner, int rows, int cols) {
        char[][] grid = new char[rows][];
        for (int r = 0; r < rows; r++) {
            String line = scanner.next();
            if (line.length() != cols) {
                throw new IllegalArgumentException("Invalid line length");
            }
            grid[r] = line.toCharArray();
        }
        return grid;
    }

    /**
     * Finds the coordinates of the first {@code '*'} in row‑major order.
     *
     * @return a {@link Position} object if a star exists, otherwise {@code null}.
     */
    private static Position locateFirstStar(char[][] grid) {
        for (int r = 0; r < grid.length; r++) {
            for (int c = 0; c < grid[r].length; c++) {
                if (grid[r][c] == STAR) {
                    return new Position(r, c);
                }
            }
        }
        return null;
    }

    /**
     * Checks whether the star cell satisfies positional constraints
     * (e.g., not on the border, proper neighbouring cells, etc.).
     */
    private static boolean isValidStarPlacement(char[][] grid, int row, int col) {
        /* Must not be located in the leftmost column. */
        if (col == 0) {
            return false;
        }

        /* The cell immediately to the left must not be a star. */
        if (grid[row][col - 1] == STAR) {
            return false;
        }

        /* Star must be interior to the grid (not on any border). */
        if (row == 0 || row == grid.length - 1 || col == 0 || col == grid[0].length - 1) {
            return false;
        }

        /* Adjacent cells must not be empty ('.'). */
        if (grid[row][col - 1] == EMPTY ||
            grid[row][col + 1] == EMPTY ||
            grid[row - 1][col] == EMPTY ||
            grid[row + 1][col] == EMPTY) {
            return false;
        }

        /* There must be a contiguous block of '*' extending to the left
         * ending exactly at column 0 with a '.' before it. */
        int leftIdx = col - 1;
        while (leftIdx >= 0 && grid[row][leftIdx] == STAR) {
            leftIdx--;
        }
        return leftIdx == 0 && grid[row][0] == EMPTY;
    }

    /**
     * Verifies the pattern of '*' cells in the column that contains the star.
     * In that column, stars may appear either only above or only below the
     * star, but not both.
     */
    private static boolean columnStarPatternIsUnique(char[][] grid, int starRow, int starCol) {
        boolean starAbove = false;
        boolean starBelow = false;

        for (int r = 0; r < grid.length; r++) {
            if (r == starRow) {
                continue; // skip the star's own row
            }
            boolean cellIsStar = grid[r][starCol] == STAR;
            if (cellIsStar) {
                if (r < starRow) {
                    starAbove = true;
                } else {
                    starBelow = true;
                }
            } else if (grid[r][starCol] != EMPTY) {
                // Any character other than '*' or '.' is illegal.
                return false;
            }
        }

        /* Both above and below cannot contain stars simultaneously. */
        return !(starAbove && starBelow);
    }

    /**
     * Ensures that the entire row containing the star consists of:
     *   1. A prefix of '.' cells that reaches column 0,
     *   2. Followed by a contiguous block of '*' cells,
     *   3. Followed only by '.' cells until the end of the row.
     *
     * @return {@code true} if the row conforms to the expected structure.
     */
    private static boolean hasContinuousStarSegmentInRow(char[][] grid,
                                                             int starRow,
                                                             int starCol) {
        int col = 0;
        int width = grid[0].length;

        /* Skip leading '.' cells until we encounter the first '*'. */
        while (col < width && grid[starRow][col] == EMPTY) {
            col++;
        }

        /* Consume all consecutive '*' cells. */
        while (col < width && grid[starRow][col] == STAR) {
            col++;
        }

        /* The remainder must be '.' cells; reaching the end means the
         * horizontal pattern is well‑formed. */
        return col == width;
    }
}

import java.util.Scanner;

/**
 * B – Detects a complete cross of '#' cells inside a grid.
 *
 * <p>
 * The algorithm scans the interior of the grid for a cell that has a '#'
 * in each of its four orthogonal neighbours.  When such a cell is found we
 * extend horizontally and vertically as far as contiguous '#' cells reach
 * in each direction.  The candidate cross is considered valid only if **all**
 * '#' cells in the entire grid belong to that horizontal or vertical arm.
 * If any '#' lies outside those arms the candidate is discarded.
 * </p>
 */
public class Main {

    /** Scanner for fast input reading. */
    private static final Scanner SCANNER = new Scanner(System.in);
    /** Output stream used for the result. */
    private static final java.io.PrintStream OUT = System.out;

    public static void main(String[] args) {
        /* ----- read dimensions ----- */
        int height = SCANNER.nextInt();
        int width  = SCANNER.nextInt();

        /* ----- read grid ----- */
        boolean[][] filled = new boolean[height][width];
        for (int r = 0; r < height; r++) {
            String line = SCANNER.next();               // next token is the whole line
            for (int c = 0; c < width; c++) {
                filled[r][c] = (line.charAt(c) == '#');
            }
        }

        /* ----- search for a valid cross ----- */
        boolean found = false;
        outer:
        for (int r = 1; r < height - 1 && !found; r++) {
            for (int c = 1; c < width - 1 && !found; c++) {
                if (isCrossCenter(filled, r, c)) {
                    // Expand horizontally
                    int left  = expandLeft(filled, r, c);
                    int right = expandRight(filled, r, c);
                    // Expand vertically
                    int up    = expandUp(filled, r, c);
                    int down  = expandDown(filled, r, c);

                    // Validate that the cross contains *all* '#' cells
                    if (isFullCross(filled, r, c, left, right, up, down)) {
                        found = true;   // a valid cross has been found
                    }
                }
            }
        }

        OUT.println(found ? "YES" : "NO");
    }

    /** Checks whether the cell is a centre of a potential cross. */
    private static boolean isCrossCenter(boolean[][] grid, int row, int col) {
        return grid[row][col] &&
               grid[row - 1][col] &&   // up
               grid[row + 1][col] &&   // down
               grid[row][col - 1] &&   // left
               grid[row][col + 1];     // right
    }

    /** Expand to the left until a '.' (false) is hit. */
    private static int expandLeft(boolean[][] grid, int row, int col) {
        int pos = col;
        while (pos > 0 && grid[row][pos - 1]) {
            pos--;
        }
        return pos;
    }

    /** Expand to the right until a '.' (false) is hit. */
    private static int expandRight(boolean[][] grid, int row, int col) {
        int pos = col;
        while (pos < grid[0].length - 1 && grid[row][pos + 1]) {
            pos++;
        }
        return pos;
    }

    /** Expand upward until a '.' (false) is hit. */
    private static int expandUp(boolean[][] grid, int row, int col) {
        int pos = row;
        while (pos > 0 && grid[pos - 1][col]) {
            pos--;
        }
        return pos;
    }

    /** Expand downward until a '.' (false) is hit. */
    private static int expandDown(boolean[][] grid, int row, int col) {
        int pos = row;
        while (pos < grid.length - 1 && grid[pos + 1][col]) {
            pos++;
        }
        return pos;
    }

    /**
     * Verifies that every '#' cell belongs either to the horizontal arm
     * (same row, within the horizontal bounds) or to the vertical arm
     * (same column, within the vertical bounds).  If any '#' lies outside
     * these arms the method returns {@code false}.
     */
    private static boolean isFullCross(boolean[][] grid,
                                         int centreRow, int centreCol,
                                         int left, int right,
                                         int up, int down) {
        int h = grid.length;
        int w = grid[0].length;
        for (int r = 0; r < h; r++) {
            for (int c = 0; c < w; c++) {
                if (!grid[r][c]) continue;
                boolean onHorizontal = (r == centreRow && c >= left && c <= right);
                boolean onVertical   = (c == centreCol && r >= up && r <= down);
                if (!onHorizontal && !onVertical) {
                    return false;
                }
            }
        }
        return true;
    }
}

import java.io.*;
import java.util.Arrays;

/**
 * Refactored solution for the "Cross" problem.
 * <p>
 * The program reads a rectangular character grid, checks whether exactly one
 * orthogonal cross of stars ('*') exists, removes it, and verifies that the
 * remaining grid contains a single star.  If all conditions are satisfied it
 * prints {@code YES}, otherwise {@code NO}.
 * </p>
 */
public class Main {

    /** Output stream used for printing the answer. */
    private static final PrintWriter OUT = new PrintWriter(System.out, true);
    /** Fast scanner used to read input data. */
    private static FastInput IN;

    /** Entry point. */
    public static void main(String[] args) {
        IN = new FastInput(System.in);
        solve();
        OUT.flush();
    }

    /** Core algorithm driver. */
    private static void solve() {
        int height = IN.nextInt();
        int width = IN.nextInt();
        char[][] grid = IN.nextCharMap(height, width);

        CrossResult result = findCrossCenter(grid);
        if (!result.isValid()) {
            OUT.println("NO");
            return;
        }

        removeCrossArms(grid, result.row(), result.col());

        if (countRemainingStars(grid) != 1) {
            OUT.println("NO");
            return;
        }

        OUT.println("YES");
    }

    /**
     * Locates the unique cross centre and validates its shape.
     *
     * @return a {@link CrossResult} containing the centre coordinates if exactly
     *         one valid cross exists; otherwise an invalid result.
     */
    private static CrossResult findCrossCenter(char[][] grid) {
        int rows = grid.length;
        int cols = grid[0].length;

        int found = 0;
        int centreRow = -1;
        int centreCol = -1;

        // Scan only interior cells – a cross cannot touch the border.
        for (int r = 1; r < rows - 1; r++) {
            for (int c = 1; c < cols - 1; c++) {
                if (isCrossCenter(grid, r, c)) {
                    found++;
                    centreRow = r;
                    centreCol = c;
                }
            }
        }

        // The problem requires exactly one cross.
        return (found == 1) ? CrossResult.of(centreRow, centreCol)
                            : CrossResult.invalid();
    }

    /**
     * Determines whether the cell at {@code (r,c)} is the centre of a valid
     * orthogonal cross consisting of five '*', i.e. up, down, left and right.
     */
    private static boolean isCrossCenter(char[][] g, int r, int c) {
        return g[r][c] == '*' &&
               g[r - 1][c] == '*' && // up
               g[r + 1][c] == '*' && // down
               g[r][c - 1] == '*' && // left
               g[r][c + 1] == '*';   // right
    }

    /** Removes the four arms of the identified cross from the grid. */
    private static void removeCrossArms(char[][] g, int centreR, int centreC) {
        // Upwards arm
        for (int r = centreR - 1; r >= 0 && g[r][centreC] == '*'; r--) {
            g[r][centreC] = '.';
        }
        // Downwards arm
        for (int r = centreR + 1; r < g.length && g[r][centreC] == '*'; r++) {
            g[r][centreC] = '.';
        }
        // Left arm
        for (int c = centreC - 1; c >= 0 && g[centreR][c] == '*'; c--) {
            g[centreR][c] = '.';
        }
        // Right arm
        for (int c = centreC + 1; c < g[0].length && g[centreR][c] == '*'; c++) {
            g[centreR][c] = '.';
        }
    }

    /** Counts how many '*' characters remain after the cross removal. */
    private static int countRemainingStars(char[][] g) {
        int count = 0;
        for (char[] row : g) {
            for (char cell : row) {
                if (cell == '*') {
                    count++;
                }
            }
        }
        return count;
    }

    /** Simple immutable holder for the optional cross centre coordinates. */
    private static final class CrossResult {
        private final boolean valid;
        private final int row;
        private final int col;

        private CrossResult(boolean valid, int row, int col) {
            this.valid = valid;
            this.row = row;
            this.col = col;
        }

        /** Creates an invalid result (used when no unique cross exists). */
        static CrossResult invalid() {
            return new CrossResult(false, -1, -1);
        }

        /** Creates a valid result with the given coordinates. */
        static CrossResult of(int row, int col) {
            return new CrossResult(true, row, col);
        }

        /** Indicates whether a centre was successfully located. */
        boolean isValid() {
            return valid;
        }

        /** Row index of the centre (meaningful only when {@code isValid()} is true). */
        int row() {
            return row;
        }

        /** Column index of the centre (meaningful only when {@code isValid()} is true). */
        int col() {
            return col;
        }
    }

    /** Fast scanner wrapper around {@link InputStream} with clear method names. */
    private static final class FastInput {
        private final InputStream stream;
        private final byte[] buffer = new byte[16_384];
        private int ptr = 0;
        private int len = 0;

        FastInput(InputStream stream) {
            this.stream = stream;
        }

        /** Reads the next byte, extending the buffer when necessary. */
        private int readByte() {
            if (ptr >= len) {
                len = stream.read(buffer);
                ptr = 0;
                if (len <= 0) {
                    return -1;
                }
            }
            return buffer[ptr++];
        }

        /** Utility to skip over whitespace characters. */
        private void skipUntilNonSpace() {
            int b;
            do {
                b = readByte();
            } while (b != -1 && isSpaceChar(b));
            if (b == -1) {
                throw new NoSuchElementException();
            }
            ptr--; // the non‑space char was consumed, rewind for next read
        }

        /** Checks if a character code represents whitespace. */
        private static boolean isSpaceChar(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t'
                    || c == 0x0b || c == 0x0c;
        }

        /** Returns {@code true} if more tokens are available. */
        public boolean hasNext() {
            skipUntilNonSpace();
            return true;
        }

        /** Reads the next token as a {@code String}. */
        public String next() {
            skipUntilNonSpace();
            StringBuilder sb = new StringBuilder();
            int b;
            do {
                b = readByte();
                sb.appendCodePoint(b);
            } while (!isSpaceChar(b));
            return sb.toString();
        }

        /** Reads the next integer from the input. */
        public int nextInt() {
            skipUntilNonSpace();
            int sign = 1;
            int c = readByte();
            if (c == '-') {
                sign = -1;
                c = readByte();
            }
            int value = 0;
            do {
                if (c < '0' || c > '9') {
                    throw new InputMismatchException();
                }
                value = value * 10 + (c - '0');
                c = readByte();
            } while (!isSpaceChar(c));
            return value * sign;
        }

        /** Reads an array of {@code int} of the specified length. */
        public int[] nextIntArray(int n) {
            int[] a = new int[n];
            for (int i = 0; i < n; i++) {
                a[i] = nextInt();
            }
            return a;
        }

        /**
         * Reads a rectangular map of characters.
         *
         * @param rows number of rows
         * @param cols number of columns per row
         * @return a 2‑D {@code char}`[rows][cols]` array
         */
        public char[][] nextCharMap(int rows, int cols) {
            char[][] map = new char[rows][cols];
            for (int i = 0; i < rows; i++) {
                String line = next();               // each line has exactly cols chars
                map[i] = line.toCharArray();
            }
            return map;
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Entry point of the program. Reads input, delegates the solving process
 * to {@link Solver} and prints the result.
 */
public class Main {

    /** Directions used to check the four neighbours of a potential centre. */
    private static final int[][] CROSS_NEIGHBOURS = {
            {-1, 0},   // up
            {1, 0},    // down
            {0, -1},   // left
            {0, 1}     // right
    };

    public static void main(String[] args) throws IOException {
        InputReader reader = new InputReader(System.in);
        PrintWriter out = new PrintWriter(System.out);
        Solver solver = new Solver();
        solver.solve(1, reader, out);
        out.close();
    }

    /**
     * Core algorithm that validates the required pattern.
     */
    static class Solver {

        /** Grid read from input. */
        private char[][] grid;
        /** Number of rows and columns. */
        private int rows, cols;

        /** Main entry point called from {@code main}. */
        public void solve(int testNumber, InputReader in, PrintWriter out) {
            rows = in.nextInt();
            cols = in.nextInt();

            // read the whole grid
            grid = new char[rows][];
            for (int i = 0; i < rows; i++) {
                grid[i] = in.next().toCharArray();
            }

            Point centre = locateCrossCentre();
            if (centre == null) {
                out.println("NO");
                return;
            }

            if (!hasProperCrossShape(centre)) {
                out.println("NO");
                return;
            }

            if (!containsOnlyCrossStars(centre)) {
                out.println("NO");
                return;
            }

            out.println("YES");
        }

        /** Finds a cell that serves as the centre of a full "+" of stars. */
        private Point locateCrossCentre() {
            for (int r = 1; r < rows - 1; r++) {
                for (int c = 1; c < cols - 1; c++) {
                    if (isFullCross(r, c)) {
                        return new Point(r, c);
                    }
                }
            }
            return null;
        }

        /** Returns true iff the cell (r,c) together with its four neighbours are all '*'. */
        private boolean isFullCross(int r, int c) {
            return grid[r][c] == '*' &&
                    grid[r - 1][c] == '*' &&   // up
                    grid[r + 1][c] == '*' &&   // down
                    grid[r][c - 1] == '*' &&   // left
                    grid[r][c + 1] == '*';     // right
        }

        /** Checks that after the first '.' in any direction there are no more '*' characters. */
        private boolean hasProperCrossShape(Point centre) {
            int r = centre.row;
            int c = centre.col;

            // up
            if (!scanDirection(r, c, -1, 0)) return false;
            // down
            if (!scanDirection(r, c, 1, 0)) return false;
            // left
            if (!scanDirection(r, c, 0, -1)) return false;
            // right
            if (!scanDirection(r, c, 0, 1)) return false;

            return true;
        }

        /**
         * Scans from the given start cell outwards in the supplied direction.
         * Returns {@code false} if a '*' appears after a '.' has been encountered.
         */
        private boolean scanDirection(int startR, int startC,
                                      int dRow, int dCol) {
            boolean afterEmpty = false;
            for (int step = 1; ; step++) {
                int nr = startR + dRow * step;
                int nc = startC + dCol * step;
                if (nr < 0 || nr >= rows || nc < 0 || nc >= cols) {
                    break; // reached border – nothing to invalidate
                }
                char ch = grid[nr][nc];
                if (ch == '.') {
                    afterEmpty = true;
                } else if (ch == '*' && afterEmpty) {
                    // '*' occurs after a '.' – invalid pattern
                    return false;
                }
            }
            return true;
        }

        /** Verifies that every '*' in the grid belongs to the identified cross. */
        private boolean containsOnlyCrossStars(Point centre) {
            int centreRow = centre.row;
            int centreCol = centre.col;

            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (grid[r][c] == '*') {
                        // a star must lie either in the same row or the same column
                        if (r != centreRow && c != centreCol) {
                            return false;
                        }
                    }
                }
            }
            return true;
        }

        /** Simple immutable point holder used internally. */
        private static final class Point {
            final int row, col;
            Point(int row, int col) {
                this.row = row;
                this.col = col;
            }
        }
    }

    /** Fast scanner based on {@link BufferedReader} and {@link StringTokenizer}. */
    static class InputReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        InputReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream), 32768);
            tokenizer = null;
        }

        /** Returns the next token from the input stream. */
        String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        /** Convenience method for reading the next integer. */
        int nextInt() {
            return Integer.parseInt(next());
        }

        Double nextDouble() {
            return Double.parseDouble(next());
        }

        long nextLong() {
            return Long.parseLong(next());
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

/**
 * Refactored solution that reads a grid of characters, looks for a plus‑shaped
 * pattern of '*' surrounded on all four sides, marks the whole pattern with '#',
 * and verifies that no '*' remain uncovered.
 */
public class Solution {

    /** Simple input reader that can be used with try‑with‑resources. */
    private static final class InputReader implements AutoCloseable {
        private final BufferedReader br;
        private StringTokenizer tokenizer;          // reused lazily

        InputReader() {
            this.br = new BufferedReader(new InputStreamReader(System.in));
        }

        /** Returns the next token from the input source. */
        private String nextToken() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    throw new UncheckedIOException(e);
                }
            }
            return tokenizer.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(nextToken());
        }

        long nextLong() {
            return Long.parseLong(nextToken());
        }

        double nextDouble() {
            return Double.parseDouble(nextToken());
        }

        /** Reads a whole line (including possible empty lines). */
        String nextLine() {
            try {
                return br.readLine();
            } catch (IOException e) {
                throw new UncheckedIOException(e);
            }
        }

        @Override
        public void close() {
            try {
                br.close();
            } catch (IOException e) {
                throw new UncheckedIOException(e);
            }
        }
    }

    /** Entry point – delegates work to {@link #solve(InputReader)}. */
    public static void main(String[] args) {
        try (InputReader scanner = new InputReader()) {
            solve(scanner);
        }
    }

    /** Core logic of the program. */
    private static void solve(InputReader scanner) {
        int height = scanner.nextInt();
        int width  = scanner.nextInt();

        // Load the whole grid into memory
        String[] rawLines = new String[height];
        for (int i = 0; i < height; i++) {
            rawLines[i] = scanner.nextLine();
        }

        // Convert to a mutable char matrix
        char[][] board = new char[height][];
        for (int i = 0; i < height; i++) {
            board[i] = rawLines[i].toCharArray();
        }

        boolean patternFound = false;

        // Scan interior cells for a plus‑shaped pattern of '*'
        outer:
        for (int r = 1; r < height - 1; r++) {
            for (int c = 1; c < width - 1; c++) {
                if (isCross(board, r, c)) {
                    markCross(board, r, c);
                    patternFound = true;
                    break outer;
                }
            }
        }

        // If no valid pattern exists, answer is immediately "NO"
        if (!patternFound) {
            System.out.println("NO");
            return;
        }

        // Verify that every original '*' has been turned into '#'
        for (int r = 0; r < height; r++) {
            for (int c = 0; c < width; c++) {
                if (board[r][c] == '*') {
                    System.out.println("NO");
                    return;
                }
            }
        }

        // All conditions satisfied → the pattern is valid
        System.out.println("YES");
    }

    /** Checks whether (r,c) is the centre of a plus formed by '*' in the four directions. */
    private static boolean isCross(char[][] board, int r, int c) {
        return board[r][c] == '*' &&
               board[r - 1][c] == '*' &&   // up
               board[r + 1][c] == '*' &&   // down
               board[r][c - 1] == '*' &&   // left
               board[r][c + 1] == '*';     // right
    }

    /** Marks the centre cell and all contiguous '*' outward in the four directions as '#'. */
    private static void markCross(char[][] board, int r, int c) {
        board[r][c] = '#';

        // Upward
        for (int i = r - 1; i >= 0 && board[i][c] == '*'; i--) {
            board[i][c] = '#';
        }
        // Downward
        for (int i = r + 1; i < board.length && board[i][c] == '*'; i++) {
            board[i][c] = '#';
        }
        // Leftward
        for (int i = c - 1; i >= 0 && board[r][i] == '*'; i--) {
            board[r][i] = '#';
        }
        // Rightward
        for (int i = c + 1; i < board[r].length && board[r][i] == '*'; i++) {
            board[r][i] = '#';
        }
    }
}

package com.example;

import java.io.*;
import java.util.*;

/**
 * Solves the problem by checking connectivity of '*' cells and verifying that they form
 * a “plus” shape – a central cell with all four orthogonal neighbours also being '*'.
 *
 * The implementation is deliberately split into small, focussed classes and methods
 * to improve readability, testability and future extensibility.
 */
public class Main {

    /** Fast I/O helpers using try‑with‑resources. */
    private static final class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner(InputStream in) {
            this.br = new BufferedReader(new InputStreamReader(in));
        }

        /** @return next integer from the input */
        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }

        /** @return next non‑empty token */
        String next() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                String line = br.readLine();
                if (line == null) {
                    return null;
                }
                st = new StringTokenizer(line);
            }
            return st.nextToken();
        }
    }

    /** Fast writer that closes automatically. */
    private static final class FastPrintWriter extends PrintWriter {
        FastPrintWriter(OutputStream out) {
            super(out, true);
        }
    }

    /** Simple undirected graph used for connected‑component analysis. */
    private static final class Graph {
        private final List<Integer>[] adj;

        Graph(int vertexCount) {
            @SuppressWarnings("unchecked")
            List<Integer>[] array = new List[vertexCount];
            for (int i = 0; i < vertexCount; i++) {
                array[i] = new LinkedList<>();
            }
            this.adj = array;
        }

        void addUndirectedEdge(int u, int v) {
            if (u == v) {
                return; // self‑loops are irrelevant for this problem
            }
            adj[u].add(v);
            adj[v].add(u);
        }

        /** Returns true if the supplied vertex has not been visited yet. */
        boolean isUnvisited(int vertex, boolean[] visited) {
            return !visited[vertex];
        }

        /** Performs a DFS marking all reachable vertices as visited. */
        void dfs(int start, boolean[] visited) {
            Deque<Integer> stack = new ArrayDeque<>();
            stack.push(start);
            while (!stack.isEmpty()) {
                int cur = stack.pop();
                if (visited[cur]) {
                    continue;
                }
                visited[cur] = true;
                for (int neighbour : adj[cur]) {
                    if (!visited[neighbour]) {
                        stack.push(neighbour);
                    }
                }
            }
        }
    }

    /** Entry point – all heavy lifting lives inside {@link #solve()}. */
    public static void main(String[] args) throws IOException {
        new Main().solve();
    }

    /** Core solving routine – keeps the static mutable state encapsulated. */
    private void solve() throws IOException {
        try (FastScanner sc = new FastScanner(System.in);
             FastPrintWriter out = new FastPrintWriter(System.out)) {

            int rows = sc.nextInt();
            int cols = sc.nextInt();

            char[][] grid = readGrid(sc, rows, cols);

            // Total cells = rows * cols; each cell gets a linear index.
            Graph graph = new Graph(rows * cols);
            boolean[] visited = new boolean[rows * cols];

            // -----------------------------------------------------------------
            // 1️⃣ Build adjacency for '*' cells and mark non‑'*' cells as visited.
            // -----------------------------------------------------------------
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    int idx = linearIndex(r, c, cols);
                    if (grid[r][c] == '*') {
                        connectNeighbouringStars(grid, rows, cols, r, c, idx, graph);
                    } else {
                        visited[idx] = true; // non‑'*' cells are considered already processed
                    }
                }
            }

            // -----------------------------------------------------------------
            // 2️⃣ Count connected components formed by '*' cells.
            // -----------------------------------------------------------------
            int componentCount = 0;
            for (int i = 0; i < visited.length; i++) {
                if (!visited[i]) {
                    graph.dfs(i, visited);
                    componentCount++;
                }
            }
            if (componentCount != 1) {
                out.print("NO");
                return;
            }

            // -----------------------------------------------------------------
            // 3️⃣ Locate the centre of the plus shape (if it exists).
            // -----------------------------------------------------------------
            int centreRow = -1, centreCol = -1;
            if (!findPlusCentre(grid, rows, cols, centreRow, centreCol)) {
                out.print("NO");
                return;
            }

            // -----------------------------------------------------------------
            // 4️⃣ Verify that every '*' lies either in the same row or column
            //    as the centre – i.e. no '*' is strictly off that row and column.
            // -----------------------------------------------------------------
            if (!allStarsAreInRowOrColumn(grid, rows, cols, centreRow, centreCol)) {
                out.print("NO");
                return;
            }

            // -----------------------------------------------------------------
            // 5️⃣ All checks passed.
            // -----------------------------------------------------------------
            out.print("YES");
        }
    }

    /** Reads the character grid from the scanner. */
    private static char[][] readGrid(FastScanner sc, int rows, int cols) throws IOException {
        char[][] grid = new char[rows][];
        for (int r = 0; r < rows; r++) {
            grid[r] = sc.next().toCharArray();
        }
        return grid;
    }

    /** Converts a 2‑D coordinate to a linear index (row‑major). */
    private static int linearIndex(int row, int col, int cols) {
        return row * cols + col;
    }

    /**
     * Connects the current '*' cell with any orthogonal neighbouring '*'
     * cells that have already been processed.  The adjacency is added
     * bidirectionally for clarity.
     */
    private static void connectNeighbouringStars(
            char[][] grid,
            int rows,
            int cols,
            int r,
            int c,
            int idx,
            Graph graph) {

        int[] dr = {-1, 0, 1, 0};
        int[] dc = {0, -1, 0, 1};

        for (int d = 0; d < 4; d++) {
            int nr = r + dr[d];
            int nc = c + dc[d];
            if (0 <= nr && nr < rows && 0 <= nc && nc < cols && grid[nr][nc] == '*') {
                int nIdx = linearIndex(nr, nc, cols);
                graph.addUndirectedEdge(idx, nIdx);
            }
        }
    }

    /**
     * Searches for a cell that is surrounded on all four orthogonal sides
     * by other '*' cells.  Returns {@code true} and stores the coordinates
     * in the supplied variables if such a cell is found.
     */
    private static boolean findPlusCentre(
            char[][] grid,
            int rows,
            int cols,
            int outRow,
            int outCol) {

        for (int r = 1; r < rows - 1; r++) {
            for (int c = 1; c < cols - 1; c++) {
                if (grid[r][c] == '*' &&
                    grid[r - 1][c] == '*' && // up
                    grid[r + 1][c] == '*' && // down
                    grid[r][c - 1] == '*' && // left
                    grid[r][c + 1] == '*') { // right
                    outRow = r;
                    outCol = c;
                    return true;
                }
            }
        }
        return false;
    }

    /**
     * Checks that every '*' cell lies either in the same row or the same
     * column as the centre discovered by {@link #findPlusCentre}.
     * This mirrors the original condition {@code i != x && j != y}.
     */
    private static boolean allStarsAreInRowOrColumn(
            char[][] grid,
            int rows,
            int cols,
            int centreRow,
            int centreCol) {

        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '*') {
                    // If the star is NOT in the centre's row AND NOT in the centre's column → reject.
                    if (r != centreRow && c != centreCol) {
                        return false;
                    }
                }
            }
        }
        return true;
    }
}

import java.io.*;
import java.util.Optional;

/**
 * Refactored solution for the “CodeForces” problem.
 * The program reads a grid of characters ( '.' or '*' ) and determines
 * whether there exists a single ‘+’ shape that satisfies the specification.
 */
public class CodeForces {

    /** Simple container for a grid position. */
    private static final class Position {
        final int row;
        final int col;

        Position(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }

    /** Encapsulates all validation logic for a plus‑shaped pattern. */
    private static final class PlusValidator {
        private final boolean[][] grid;
        private final int rows;
        private final int cols;

        PlusValidator(boolean[][] grid) {
            this.grid = grid;
            this.rows = grid.length;
            this.cols = grid[0].length;
        }

        /** Finds the (if any) centre cell that could be the middle of a plus. */
        Optional<Position> findCenter() {
            for (int i = 1; i < rows - 1; i++) {
                for (int j = 1; j < cols - 1; j++) {
                    if (isPotentialCenter(i, j)) {
                        return Optional.of(new Position(i, j));
                    }
                }
            }
            return Optional.empty();
        }

        /** Validates that the discovered centre really forms a proper plus. */
        boolean isValid(Position centre) {
            return isContiguousInAllDirections(centre) && hasNoForeignStars(centre);
        }

        /** Checks the original (slightly buggy) condition for a candidate centre. */
        private boolean isPotentialCenter(int i, int j) {
            return grid[i][j]
                    && grid[i][j - 1]
                    && grid[i][j + 1]
                    && grid[i + 1][j]           // original condition kept
                    && grid[i + 1][j];
        }

        /** Verifies that from the centre there are no gaps in any of the four
         *  cardinal directions before encountering an empty cell again. */
        private boolean isContiguousInAllDirections(Position centre) {
            return isContiguous(centre.row, centre.col, 0, -1)   // left
                    && isContiguous(centre.row, centre.col, 0, 1)   // right
                    && isContiguous(centre.row, centre.col, -1, 0)   // up
                    && isContiguous(centre.row, centre.col, 1, 0);   // down
        }

        /** Traverses a line in the given direction and ensures that ‘*’
         *  cells appear only in one contiguous block. */
        private boolean isContiguous(int startR, int startC, int dr, int dc) {
            boolean gapSeen = false;
            int r = startR + dr;
            int c = startC + dc;
            while (inside(r, c)) {
                if (grid[r][c]) {
                    if (gapSeen) {
                        return false;               // a second block after a gap
                    }
                } else {
                    gapSeen = true;
                }
                r += dr;
                c += dc;
            }
            return true;
        }

        /** Returns true if every ‘*’ cell either lies on the same row or the
         *  same column as the centre (i.e. no star exists elsewhere). */
        private boolean hasNoForeignStars(Position centre) {
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (grid[i][j] && (i != centre.row || j != centre.col)) {
                        // star not on centre's row or column → invalid
                        if (i != centre.row && j != centre.col) {
                            return false;
                        }
                    }
                }
            }
            return true;
        }

        /** Utility – checks whether a given cell is inside the grid. */
        private boolean inside(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }
    }

    /** Reads the grid from standard input. */
    private static boolean[][] readGrid(BufferedReader br) throws IOException {
        String[] header = br.readLine().split("\\s+");
        int h = Integer.parseInt(header[0]);
        int w = Integer.parseInt(header[1]);

        boolean[][] grid = new boolean[h][w];
        for (int i = 0; i < h; i++) {
            String line = br.readLine().trim();
            for (int j = 0; j < w; j++) {
                grid[i][j] = line.charAt(j) == '*';
            }
        }
        return grid;
    }

    public static void main(String[] args) throws IOException {
        // Try‑with‑resources guarantees the reader is closed.
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in))) {
            boolean[][] grid = readGrid(br);
            PlusValidator validator = new PlusValidator(grid);
            Optional<Position> centre = validator.findCenter();

            System.out.println(
                    centre.map(validator::isValid).orElse(false) ? "YES" : "NO"
            );
        }
    }
}

import java.io.PrintWriter;
import java.util.Scanner;

/**
 * Refactored solution for the “Cross of Stars” problem.
 * <p>
 * The program reads a grid of characters (‘*’ and ‘.’) and checks whether there is exactly
 * one plus‑shaped constellation of stars that uses every star in the grid.
 * If such a configuration exists it prints “YES”, otherwise “NO”.
 * </p>
 */
public class Main {

    /** Input and output streams used by the solution. */
    private static final Scanner IN = new Scanner(System.in);
    private static final PrintWriter OUT = new PrintWriter(System.out);

    /** Entry point. */
    public static void main(String[] args) {
        solve();
        OUT.close();
    }

    /** Main logic of the program. */
    private static void solve() {
        int n = IN.nextInt();          // number of rows
        int m = IN.nextInt();          // number of columns

        char[][] grid = readGrid(n, m); // read the grid from stdin

        Position centre = findCrossCenter(grid);
        if (centre == null) {          // no valid centre -> impossible
            OUT.println("NO");
            return;
        }

        // Mark each ray of the cross and remember whether it has an extension.
        boolean up    = markDirection(grid, centre.row,   centre.col, Direction.UP);
        boolean down  = markDirection(grid, centre.row,   centre.col, Direction.DOWN);
        boolean left  = markDirection(grid, centre.row,   centre.col, Direction.LEFT);
        boolean right = markDirection(grid, centre.row,   centre.col, Direction.RIGHT);

        // The cross is valid only if every ray has at least one extra star
        // and no other star remains in the grid.
        if (up && down && left && right && noStarLeft(grid)) {
            OUT.println("YES");
        } else {
            OUT.println("NO");
        }
    }

    /** Reads the grid of size {@code n × m} from standard input. */
    private static char[][] readGrid(int n, int m) {
        char[][] grid = new char[n][];
        for (int i = 0; i < n; i++) {
            String line = IN.next();          // each line contains exactly m characters
            grid[i] = line.toCharArray();
        }
        return grid;
    }

    /** Finds a cell that is the centre of a plus made of '*' characters.
     *  The centre must be surrounded orthogonally by stars and must not be on the border.
     *  Returns {@code null} if no such cell exists. */
    private static Position findCrossCenter(char[][] grid) {
        int rows = grid.length;
        int cols = grid[0].length;

        for (int i = 1; i < rows - 1; i++) {
            for (int j = 1; j < cols - 1; j++) {
                if (grid[i][j] == '*' &&
                    grid[i - 1][j] == '*' &&
                    grid[i + 1][j] == '*' &&
                    grid[i][j - 1] == '*' &&
                    grid[i][j + 1] == '*') {
                    return new Position(i, j);
                }
            }
        }
        return null;
    }

    /**
     * Marks the cells of a ray starting at {@code (row, col)} in the given {@code direction}
     * until a non‑'*' cell is encountered.
     * Marked cells are replaced by {@code 'v'} (visited).
     * <p>
     * The method also returns {@code true} if the ray contains at least one cell
     * beyond the centre (i.e., the ray is longer than a single star).
     * </p>
     */
    private static boolean markDirection(char[][] grid, int row, int col, Direction direction) {
        boolean extended = false;
        for (int step = 1; ; step++) {
            int r = row + direction.dr * step;
            int c = col + direction.dc * step;
            if (r < 0 || r >= grid.length || c < 0 || c >= grid[0].length) break;
            if (grid[r][c] != '*') break;
            grid[r][c] = 'v';          // mark as visited
            extended = true;           // any step means an extension exists
        }
        return extended;
    }

    /** Checks whether any '*' character is left unmarked in the grid. */
    private static boolean noStarLeft(char[][] grid) {
        for (char[] row : grid) {
            for (char cell : row) {
                if (cell == '*') {
                    return false;
                }
            }
        }
        return true;
    }

    /** Simple holder for a grid coordinate. */
    private static final class Position {
        final int row;
        final int col;

        Position(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }

    /** Directions used for traversing the four orthogonal rays of the plus. */
    private enum Direction {
        UP(-1, 0),
        DOWN(1, 0),
        LEFT(0, -1),
        RIGHT(0, 1);

        final int dr;
        final int dc;

        Direction(int dr, int dc) {
            this.dr = dr;
            this.dc = dc;
        }
    }
}

import java.io.*;
import java.util.*;

public class B_PlusFromPicture {

    /** Simple fast scanner that works with stdin. */
    private static final class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner(InputStream in) {
            this.br = new BufferedReader(new InputStreamReader(in));
        }

        /** Reads the next token, blocking until one is available. */
        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    throw new UncheckedIOException(e);
                }
            }
            return st.nextToken();
        }

        int nextInt()      { return Integer.parseInt(next()); }
        long nextLong()    { return Long.parseLong(next()); }
        double nextDouble(){ return Double.parseDouble(next()); }
        String nextLine()  { 
            try {
                return br.readLine();
            } catch (IOException e) {
                throw new UncheckedIOException(e);
            }
        }
    }

    public static void main(String[] args) throws IOException {
        /* -------------------------------------------------------------
         *  Input handling (try‑with‑resources guarantees proper closing)
         * ------------------------------------------------------------- */
        try (FastScanner fs = new FastScanner(System.in);
             BufferedWriter bw = new BufferedWriter(
                     new OutputStreamWriter(System.out))) {

            int rows = fs.nextInt();
            int cols = fs.nextInt();

            List<String> grid = new ArrayList<>(rows);
            for (int i = 0; i < rows; i++) {
                grid.add(fs.next());
            }

            /* ---------------------------------------------------------
             *  Core logic – does the grid consist of exactly one plus?
             * --------------------------------------------------------- */
            if (hasSinglePlusCoveringAllStars(grid, rows, cols)) {
                bw.write("YES");
            } else {
                bw.write("NO");
            }
            bw.flush();
        }
    }

    /** Determines whether the whole grid is made of exactly one plus sign. */
    private static boolean hasSinglePlusCoveringAllStars(List<String> grid,
                                                          int n,
                                                          int m) {
        // 1️⃣ Count all '*' in the picture.
        int totalStars = countStars(grid);

        // 2️⃣ Look for a centre cell that could be the middle of a plus.
        for (int i = 1; i < n - 1; i++) {
            for (int j = 1; j < m - 1; j++) {
                if (isPlusCenter(grid, i, j)) {
                    int plusSize = sizeOfPlus(grid, i, j);
                    if (plusSize == totalStars) {
                        return true;                 // The plus consumes every '*'
                    }
                }
            }
        }
        return false;    // No suitable centre was found
    }

    /** Checks the orthogonal neighbours of (r,c) for '*'. */
    private static boolean isPlusCenter(List<String> grid, int r, int c) {
        char cell = grid.get(r).charAt(c);
        return cell == '*' &&
               grid.get(r - 1).charAt(c) == '*' &&   // up
               grid.get(r + 1).charAt(c) == '*' &&   // down
               grid.get(r).charAt(c - 1) == '*' &&   // left
               grid.get(r).charAt(c + 1) == '*';     // right
    }

    /** Returns the number of '*' belonging to the plus centred at (r,c). */
    private static int sizeOfPlus(List<String> grid, int r, int c) {
        int size = 1;   // centre itself

        // extend left
        for (int col = c - 1; col >= 0 && grid.get(r).charAt(col) == '*'; col++) {
            size++;
        }
        // extend right
        for (int col = c + 1; col < grid.get(0).length() && grid.get(r).charAt(col) == '*'; col++) {
            size++;
        }
        // extend upwards
        for (int row = r - 1; row >= 0 && grid.get(row).charAt(c) == '*'; row--) {
            size++;
        }
        // extend downwards
        for (int row = r + 1; row < grid.size() && grid.get(row).charAt(c) == '*'; row++) {
            size++;
        }
        return size;
    }

    /** Simple utility to count all '*' characters in the grid. */
    private static int countStars(List<String> grid) {
        int cnt = 0;
        for (String line : grid) {
            for (int i = 0; i < line.length(); i++) {
                if (line.charAt(i) == '*') {
                    cnt++;
                }
            }
        }
        return cnt;
    }
}

import java.io.*;
import java.util.StringTokenizer;

/**
 * Reads a grid consisting of '.' and '*' characters.
 * Determines whether all '*' cells belong to a single plus shape
 * (a central '*' with a continuous line of '*' in the four orthogonal
 * directions). If so prints {@code "YES"}, otherwise {@code "NO"}.
 */
public class Main {

    public static void main(String[] args) throws IOException {
        // Use try‑with‑resources to guarantee proper stream closure
        try (InputReader reader = new InputReader(System.in);
             PrintWriter out = new PrintWriter(
                     new BufferedWriter(new OutputStreamWriter(System.out)), true)) {

            int height = reader.nextInt();
            int width  = reader.nextInt();

            char[][] grid = new char[height][width];
            int totalStars = 0;

            // Read the whole grid while counting the stars
            for (int i = 0; i < height; i++) {
                String row = reader.next();
                grid[i] = row.toCharArray();
                for (char c : row.toCharArray()) {
                    if (c == '*') {
                        totalStars++;
                    }
                }
            }

            // Perform the plus‑shape validation
            boolean resultHandled = validatePlus(grid, height, width, totalStars, out);
            if (!resultHandled) {
                out.println("NO");
            }
        }
    }

    /**
     * Checks the plus‑shape condition.
     *
     * @return {@code true} if the answer for the current test case has already been printed,
     *         {@code false} otherwise (the caller should print "NO").
     */
    private static boolean validatePlus(char[][] grid, int h, int w, int totalStars, PrintWriter out) {
        // A plus cannot exist in grids smaller than 3×3
        if (h < 3 || w < 3) {
            out.println("NO");
            return true;
        }

        // Find the centre of a potential plus
        int centreRow = -1, centreCol = -1;
        outer:
        for (int i = 1; i < h - 1; i++) {
            for (int j = 1; j < w - 1; j++) {
                if (grid[i][j] == '*' &&
                    grid[i - 1][j] == '*' && // up
                    grid[i + 1][j] == '*' && // down
                    grid[i][j - 1] == '*' && // left
                    grid[i][j + 1] == '*') { // right
                    centreRow = i;
                    centreCol = j;
                    break outer; // exactly one centre is expected
                }
            }
        }

        if (centreRow == -1) {
            out.println("NO");
            return true;
        }

        // Count how many '*' are covered by the plus centred at (centreRow, centreCol)
        int coveredStars = countCoveredStars(grid, centreRow, centreCol);

        // If every '*' belongs to the plus, print "YES", otherwise "NO"
        if (coveredStars == totalStars) {
            out.println("YES");
        } else {
            out.println("NO");
        }
        return true;
    }

    /**
     * Counts the stars that belong to the plus shape extending from the given centre.
     *
     * @param grid     source grid
     * @param row      row index of the centre
     * @param col      column index of the centre
     * @return total number of stars covered by the plus (center counted once)
     */
    private static int countCoveredStars(char[][] grid, int row, int col) {
        int up    = 0;
        int down  = 0;
        int left  = 0;
        int right = 0;
        int h = grid.length;
        int w = grid[0].length;

        // Upwards from the centre (including the centre)
        for (int i = row; i >= 0 && grid[i][col] == '*'; i--) up++;

        // Downwards
        for (int i = row; i < h && grid[i][col] == '*'; i++) down++;

        // Leftwards
        for (int j = col; j >= 0 && grid[row][j] == '*'; j--) left++;

        // Rightwards
        for (int j = col; j < w && grid[row][j] == '*'; j++) right++;

        // The centre is counted four times; subtract the over‑count
        return up + down + left + right - 3;
    }

    /**
     * Fast line‑token reader suitable for competitive‑programming style input.
     */
    private static class InputReader {
        private final BufferedReader br;
        private StringTokenizer st;

        InputReader(InputStream input) {
            br = new BufferedReader(new InputStreamReader(input));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    throw new UncheckedIOException(e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.io.*;
import java.util.*;

public class Plus {

    private static final char STAR = '*';
    private static final char EMPTY = '.';

    public static void main(String[] args) throws Exception {
        new Plus().run();
    }

    public void run() throws Exception {
        try (Scanner scanner = new Scanner(System.in)) {
            int rows = scanner.nextInt();
            int cols = scanner.nextInt();
            char[][] grid = new char[rows][cols];
            for (int i = 0; i < rows; i++) {
                String line = scanner.next().trim();
                System.arraycopy(line.toCharArray(), 0, grid[i], 0, Math.min(line.length(), cols));
            }

            Optional<int[]> center = findCenter(grid);
            if (!center.isPresent()) {
                System.out.println("NO");
                return;
            }

            int cx = center.get()[0];
            int cy = center.get()[1];

            Result result = validatePlus(grid, cx, cy);
            System.out.println(result.isValid() ? "YES" : "NO");
        }
    }

    /** Finds the unique cell that is '*' and has '*' on all four orthogonal neighbours. */
    private Optional<int[]> findCenter(char[][] grid) {
        int rows = grid.length;
        int cols = grid[0].length;

        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] != STAR) continue;
                if (hasAllFourNeighboursStar(grid, i, j)) {
                    return Optional.of(new int[]{i, j});
                }
            }
        }
        return Optional.empty();
    }

    /** Verifies that the four orthogonal neighbours of (x,y) are '*'. */
    private boolean hasAllFourNeighboursStar(char[][] grid, int x, int y) {
        int[][] dirs = {{-1,0},{1,0},{0,-1},{0,1}};
        for (int[] d : dirs) {
            int nx = x + d[0];
            int ny = y + d[1];
            if (nx < 0 || nx >= grid.length || ny < 0 || ny >= grid[0].length) {
                return false;
            }
            if (grid[nx][ny] != STAR) {
                return false;
            }
        }
        return true;
    }

    /** Validates the complete plus shape and that no stray '*' cells exist. */
    private Result validatePlus(char[][] grid, int cx, int cy) {
        int rows = grid.length;
        int cols = grid[0].length;

        boolean[][] partOfPlus = new boolean[rows][cols];
        partOfPlus[cx][cy] = true;               // centre is always part of the plus

        int[][] dirs = {{-1,0},{1,0},{0,-1},{0,1}};
        boolean[] directionHasStar = new boolean[4];

        for (int d = 0; d < dirs.length; d++) {
            int dx = dirs[d][0];
            int dy = dirs[d][1];
            int nx = cx + dx;
            int ny = cy + dy;

            if (!isInside(nx, ny, rows, cols) || grid[nx][ny] != STAR) {
                continue; // no star in this direction → invalid
            }

            // walk while we keep seeing '*'
            while (isInside(nx, ny, rows, cols) && grid[nx][ny] == STAR) {
                partOfPlus[nx][ny] = true;
                directionHasStar[d] = true;
                nx += dx;
                ny += dy;
            }
        }

        // every direction must contain at least one '*'
        boolean allDirectionsHaveStar = Arrays.stream(directionHasStar).allTrue();

        // ensure there are no '*' outside the identified plus shape
        boolean strayStarFound = false;
        for (int i = 0; i < rows && !strayStarFound; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == STAR && !partOfPlus[i][j]) {
                    strayStarFound = true;
                }
            }
        }

        return new Result(allDirectionsHaveStar && !strayStarFound);
    }

    private boolean isInside(int x, int y, int rows, int cols) {
        return x >= 0 && x < rows && y >= 0 && y < cols;
    }

    private boolean isStar(char c) {
        return c == STAR;
    }

    /** Simple holder for validation outcome. */
    private static class Result {
        private final boolean valid;

        Result(boolean valid) {
            this.valid = valid;
        }

        boolean isValid() {
            return valid;
        }
    }
}

