    }

    /** Reads the n × m board from the fast scanner. */
    private static char[][] readBoard(FastScanner fs, int n, int m) {
        char[][] board = new char[n][m];
        for (int i = 0; i < n; i++) {
            String line = fs.next();
            for (int j = 0; j < m; j++) {
                board[i][j] = line.charAt(j);
            }
        }
        return board;
    }

    /**
     * Determines whether the board can be cleared by removing exactly one
     * plus‑shaped group of '*' cells.
     *
     * @return true if the board can be completely cleared, false otherwise.
     */
    private static boolean canBeSolved(char[][] board) {
        if (!containsStar(board)) {
            // No '*' at all → answer must be NO (same behaviour as original code).
            return false;
        }

        // Locate the first centre that can start a plus pattern.
        int ci = -1, cj = -1;
        outer:
        for (int i = 0; i < board.length; i++) {
            for (int j = 0; j < board[i].length; j++) {
                if (board[i][j] != '*') continue;
                // centre must be interior
                if (i == 0 || i == board.length - 1 || j == 0 || j == board[i].length - 1) continue;
                // all four orthogonal neighbours must not be '.'
                if (board[i - 1][j] == '.' || board[i + 1][j] == '.' ||
                    board[i][j - 1] == '.' || board[i][j + 1] == '.') continue;
                ci = i;
                cj = j;
                break outer;
            }
        }

        if (ci == -1) {
            // No valid centre found → answer NO.
            return false;
        }

        // Remove the whole plus centred at (ci, cj).
        clearPlus(board, ci, cj);

        // If after removal there is no '*' left, the board was solvable.
        return isEmptyOfStars(board);
    }

    /** Returns true iff the board contains at least one '*'. */
    private static boolean containsStar(char[][] board) {
        for (char[] row : board) {
            for (char c : row) {
                if (c == '*') return true;
            }
        }
        return false;
    }

    /** Clears the plus pattern that starts at (centerRow, centerCol). */
    private static void clearPlus(char[][] board, int centerRow, int centerCol) {
        int n = board.length;
        int m = board[0].length;

        // Upwards
        for (int r = centerRow - 1; r >= 0 && board[r][centerCol] == '*'; r--) {
            board[r][centerCol] = '.';
        }
        // Downwards
        for (int r = centerRow + 1; r < n && board[r][centerCol] == '*'; r++) {
            board[r][centerCol] = '.';
        }
        // Leftwards
        for (int c = centerCol - 1; c >= 0 && board[centerRow][c] == '*'; c--) {
            board[centerRow][c] = '.';
        }
        // Rightwards
        for (int c = centerCol + 1; c < m && board[centerRow][c] == '*'; c++) {
            board[centerRow][c] = '.';
        }

        // Finally clear the centre cell itself.
        board[centerRow][centerCol] = '.';
    }

    /** Checks whether the board contains any '*' character. */
    private static boolean isEmptyOfStars(char[][] board) {
        for (char[] row : board) {
            for (char c : row) {
                if (c == '*') return false;
            }
        }
        return true;
    }

    /** Fast scanner replacement for java.util.Scanner (preserves original speed). */
    private static final class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int bufferPos = 0, bufferLen = 0;

        FastScanner() {
            in = new BufferedInputStream(System.in);
        }

        private int readByte() throws IOException {
            if (bufferPos >= bufferLen) {
                bufferLen = in.read(buffer);
                bufferPos = 0;
                if (bufferLen <= 0) return -1;
            }
            return buffer[bufferPos++];
        }

        private long readLong() throws IOException {
            int c;
            do {
                c = readByte();
            } while (c <= ' ' && c != -1);
            boolean neg = false;
            if (c == '-') {
                neg = true;
                c = readByte();
            }
            long result = 0;
            while (c > ' ') {
                result = result * 10 + (c - '0');
                c = readByte();
            }
            return neg ? -result : result;
        }

        public int nextInt() throws IOException {
            return (int) readLong();
        }

        public String next() throws IOException {
            StringBuilder sb = new StringBuilder();
            int c;
            // skip whitespace
            do {
                c = readByte();
            } while (c <= ' ' && c != -1);
            // read non‑whitespace
            while (c > ' ') {
                sb.append((char) c);
                c = readByte();
            }
            return sb.toString();
        }

        public boolean hasNext() throws IOException {
            int c;
            do {
                c = readByte();
                if (c == -1) return false;
            } while (c <= ' ');
            // push back the first non‑whitespace character
            System.arraycopy(new byte[]{(byte) c}, 0, buffer, 0, 1);
            bufferPos = 1;
            bufferLen = 1;
            return true;
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.ArrayList;
import java.util.List;

public class PlusPicture {

    /** Simple fast scanner that reads whitespace‑separated tokens. */
    private static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        /** Returns the next token, reading a new line if necessary. */
        String next() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                st = new StringTokenizer(br.readLine());
            }
            return st.nextToken();
        }

        /** Reads the next line (useful when the whole line must be consumed). */
        String nextLine() throws IOException {
            return br.readLine();
        }

        /** Convenience wrapper for parsing an int. */
        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }

    /** Holds the outcome of the validation step. */
    private static class PlusResult {
        final boolean valid;
        final char[][] output;               // mutable grid to be printed

        PlusResult(boolean valid, char[][] output) {
            this.valid = valid;
            this.output = output;
        }
    }

    /** Main driver – parses input, validates the picture and prints the result. */
    public static void main(String[] args) throws Exception {
        try (FastScanner sc = new FastScanner()) {
            int h = sc.nextInt();       // number of rows
            int w = sc.nextInt();       // number of columns

            // Read the whole grid (each row is a single token without spaces)
            String[] rows = new String[h];
            for (int i = 0; i < h; i++) {
                rows[i] = sc.next();
            }

            PlusResult res = validateAndBuild(rows);
            if (res.valid) {
                printResult(res.output);
            } else {
                System.out.println("NO");
            }
        }
    }

    /**
     * Checks whether the supplied grid contains exactly one ‘+’ made of '*'
     * characters and builds the output grid where those '*' are replaced by '#'.
     * @param rows Array of input rows.
     * @return A PlusResult indicating validity and the resulting grid.
     */
    private static PlusResult validateAndBuild(String[] rows) {
        int h = rows.length;
        int w = rows[0].length();

        // Convert rows to a mutable char[][] and count all '*' occurrences.
        char[][] grid = new char[h][];
        int starCount = 0;
        for (int i = 0; i < h; i++) {
            grid[i] = rows[i].toCharArray();
            for (int j = 0; j < w; j++) {
                if (grid[i][j] == '*') {
                    starCount++;
                }
            }
        }

        // Directions: up, down, left, right
        final int[] dr = {-1, 1, 0, 0};
        final int[] dc = {0, 0, -1, 1};

        // -------------------------------------------------------------------------
        // 1. Locate a candidate centre – a '*' that has '*' on all four orthogonal
        //    neighbours.
        // -------------------------------------------------------------------------
        List<int[]> candidates = new ArrayList<>();
        for (int i = 1; i < h - 1; i++) {
            for (int j = 1; j < w - 1; j++) {
                if (grid[i][j] != '*') continue;

                boolean allNeighboursStar = true;
                for (int d = 0; d < 4; d++) {
                    int ni = i + dr[d];
                    int nj = j + dc[d];
                    if (grid[ni][nj] != '*') {
                        allNeighboursStar = false;
                        break;
                    }
                }
                if (allNeighboursStar) {
                    candidates.add(new int[]{i, j});
                }
            }
        }

        // There must be exactly one centre; otherwise the picture cannot be a '+'
        if (candidates.size() != 1) {
            return new PlusResult(false, null);
        }

        int ci = candidates.get(0)[0];
        int cj = candidates.get(0)[1];

        // -------------------------------------------------------------------------
        // 2. Measure the length of each arm (excluding the centre cell).
        // -------------------------------------------------------------------------
        int[] armLengths = new int[4];               // up, down, left, right
        for (int d = 0; d < 4; d++) {
            int ni = ci + dr[d];
            int nj = cj + dc[d];
            int len = 0;
            while (ni >= 0 && ni < h && nj >= 0 && nj < w && grid[ni][nj] == '*') {
                len++;
                ni += dr[d];
                nj += dc[d];
            }
            armLengths[d] = len;
        }

        // Total '*''s that belong to the plus = centre + sum of arm lengths
        int coveredStars = 1 + armLengths[0] + armLengths[1] + armLengths[2] + armLengths[3];

        // The plus must consume **all** '*' in the grid.
        if (coveredStars != starCount) {
            return new PlusResult(false, null);
        }

        // -------------------------------------------------------------------------
        // 3. Build the result grid – replace every '*' that belongs to the plus
        //    with '#'.
        // -------------------------------------------------------------------------
        char[][] result = new char[h][];
        for (int i = 0; i < h; i++) {
            result[i] = rows[i].toCharArray();      // copy original characters
        }

        // centre
        result[ci][cj] = '#';

        // vertical arms
        for (int step = 1; step <= armLengths[0]; step++) { // up
            result[ci - step][cj] = '#';
        }
        for (int step = 1; step <= armLengths[1]; step++) { // down
            result[ci + step][cj] = '#';
        }

        // horizontal arms
        for (int step = 1; step <= armLengths[2]; step++) { // left
            result[ci][cj - step] = '#';
        }
        for (int step = 1; step <= armLengths[3]; step++) { // right
            result[ci][cj + step] = '#';
        }

        return new PlusResult(true, result);
    }

    /** Prints the final grid line‑by‑line. */
    private static void printResult(char[][] grid) {
        StringBuilder sb = new StringBuilder();
        for (char[] row : grid) {
            sb.append(row);
            sb.append('\n');
        }
        System.out.print(sb.toString());
    }
}

package plus;

import java.io.IOException;
import java.util.ArrayList;
import java.util.List;
import java.util.Optional;
import java.util.Scanner;

/**
 * Checks whether the given character grid contains exactly one connected component
 * of '*' that forms a plus sign (a central cell with four orthogonal neighbours)
 * and nothing else.
 *
 * <p>Input format:</p>
 * <pre>
 *   width height
 *   row1
 *   row2
 *   …
 * </pre>
 *
 * <p>Output is either {@code YES} or {@code NO}.</p>
 */
public class Solution {

    /** Four‑directional movement vectors used for DFS traversal. */
    private static final int[][] DIRECTIONS = {
            { -1, 0 },   // up
            { 0, -1 },   // left
            { 0, 1 },    // right
            { 1, 0 }     // down
    };

    /** --------------------------------------------------------------------- */
    /**  Input handling                                                           */
    /**  --------------------------------------------------------------------- */

    /**
     * Reads the grid dimensions and the character grid from {@link Scanner}.
     *
     * @param scanner a scanner that supplies the input
     * @return a two‑dimensional {@code char}`[][]` containing the grid
     */
    private static char[][] readGrid(Scanner scanner) {
        int rows = scanner.nextInt();
        int cols = scanner.nextInt();
        char[][] grid = new char[rows][];
        for (int i = 0; i < rows; i++) {
            grid[i] = scanner.next().toCharArray();
        }
        return grid;
    }

    /** --------------------------------------------------------------------- */
    /**  Core algorithm                                                            */
    /**  --------------------------------------------------------------------- */

    /**
     * Finds the unique connected component of '*' symbols.
     *
     * @param grid the character grid
     * @return an {@link Optional} containing the first discovered component,
     *         or empty if there is no '*' or more than one component
     */
    private static Optional<List<Coordinate>> findUniqueStarComponent(char[][] grid) {
        boolean[][] visited = new boolean[grid.length][grid[0].length];
        List<Coordinate> component = new ArrayList<>();

        for (int i = 0; i < grid.length; i++) {
            for (int j = 0; j < grid[i].length; j++) {
                if (!visited[i][j] && grid[i][j] == '*') {
                    dfs(i, j, grid, visited, component);
                    // If we already collected more than one cell, the input is invalid.
                    if (component.size() > 1) {
                        return Optional.empty();
                    }
                }
            }
        }

        // Empty list → no '*' at all.
        return component.isEmpty() ? Optional.empty() : Optional.of(component);
    }

    /**
     * Depth‑first search that populates {@code component} with all cells of the
     * current '*' region.
     *
     * @param i        starting row index
     * @param j        starting column index
     * @param grid     the character grid
     * @param visited  matrix tracking visited cells
     * @param component list that will receive the discovered coordinates
     */
    private static void dfs(int i, int j, char[][] grid,
                            boolean[][] visited, List<Coordinate> component) {
        visited[i][j] = true;
        component.add(new Coordinate(i, j));

        for (int[] dir : DIRECTIONS) {
            int ni = i + dir[0];
            int nj = j + dir[1];
            if (inside(grid, ni, nj) && !visited[ni][nj] && grid[ni][nj] == '*') {
                dfs(ni, nj, grid, visited, component);
            }
        }
    }

    /** Utility: checks whether a coordinate lies inside the grid. */
    private static boolean inside(char[][] grid, int i, int j) {
        return i >= 0 && i < grid.length && j >= 0 && j < grid[i].length;
    }

    /**
     * Determines whether the discovered '*' component forms a single plus sign.
     *
     * @param grid   the character grid
     * @param centre a mutable wrapper used to store the centre coordinate
     * @return {@code true} if the grid contains exactly one plus sign,
     *         {@code false} otherwise
     */
    private static boolean isValidPlus(char[][] grid, Coordinate centre) {
        int rows = grid.length;
        int cols = grid[0].length;
        int centreCount = 0;

        // Locate the centre cell of the plus (must have neighbours on all four sides).
        for (int i = 1; i < rows - 1; i++) {
            for (int j = 1; j < cols - 1; j++) {
                if (grid[i][j] == '*' &&
                        grid[i - 1][j] == '*' &&
                        grid[i][j - 1] == '*' &&
                        grid[i][j + 1] == '*' &&
                        grid[i + 1][j] == '*') {
                    centreCount++;
                    // Remember the first centre we encounter.
                    if (centre.x < 0) {
                        centre.x = i;
                        centre.y = j;
                    }
                }
            }
        }

        // There must be **exactly** one centre.
        if (centreCount != 1) {
            return false;
        }

        // Every '*' must belong to the centre cell or one of its four neighbours.
        int cx = centre.x;
        int cy = centre.y;
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == '*') {
                    boolean isPartOfPlus = (i == cx && j == cy) ||
                                            (i == cx - 1 && j == cy) ||
                                            (i == cx + 1 && j == cy) ||
                                            (i == cx && j == cy - 1) ||
                                            (i == cx && j == cy + 1);
                    if (!isPartOfPlus) {
                        return false;
                    }
                }
            }
        }
        return true;
    }

    /** Simple immutable holder for a grid coordinate. */
    private static final class Coordinate {
        final int x;
        final int y;

        Coordinate(int x, int y) {
            this.x = x;
            this.y = y;
        }
    }

    /** --------------------------------------------------------------------- */
    /**  Entry point                                                             */
    /**  --------------------------------------------------------------------- */

    /**
     * Program entry point. Reads input, validates it, and prints {@code YES}
     * if the grid contains a single plus sign of '*', otherwise prints {@code NO}.
     *
     * @throws IOException if an I/O error occurs while reading input
     */
    public static void main(String[] args) throws IOException {
        // Scanner opened via try‑with‑resources to guarantee closure.
        try (Scanner scanner = new Scanner(System.in)) {
            char[][] grid = readGrid(scanner);

            // A plus sign cannot exist in grids smaller than 3×3.
            if (grid.length < 3 || grid[0].length < 3) {
                System.out.println("NO");
                return;
            }

            Optional<List<Coordinate>> maybeComponent = findUniqueStarComponent(grid);
            if (!maybeComponent.isPresent()) {
                System.out.println("NO");
                return;
            }

            // The centre coordinate holder is initialised with sentinel values.
            Coordinate centre = new Coordinate(-1, -1);

            if (!isValidPlus(grid, centre)) {
                System.out.println("NO");
                return;
            }

            System.out.println("YES");
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Refactored version of the original program.
 * <p>
 * The refactor improves readability, naming, and structure while preserving the
 * original behaviour.  All mutable state is confined to small, well‑named
 * helper classes and methods, making future maintenance easier.
 */
public class Main {

    /** Simple wrapper around {@link BufferedReader} that supplies token parsing. */
    private static final class InputReader implements AutoCloseable {
        private final BufferedReader br;

        public InputReader() {
            this.br = new BufferedReader(new InputStreamReader(System.in));
        }

        /** Reads the next integer token from stdin. */
        int nextInt() throws IOException {
            return Integer.parseInt(nextToken());
        }

        /** Reads the next full line from stdin. */
        String nextLine() throws IOException {
            return br.readLine();
        }

        /** Returns the next token, reading a new line when necessary. */
        private String nextToken() throws IOException {
            while (true) {
                StringTokenizer tokenizer = new StringTokenizer(br.readLine());
                if (tokenizer.hasMoreTokens()) {
                    return tokenizer.nextToken();
                }
            }
        }

        @Override
        public void close() throws IOException {
            br.close();
        }
    }

    /** Holds the logic that decides whether the input grid matches the required pattern. */
    private static final class PatternAnalyzer {

        /** Sentinel values taken from the original source code when no meaningful data exists. */
        private static final int SENTINEL = Integer.MAX_VALUE;

        private final String[] grid;
        private final int columns;

        public PatternAnalyzer(String[] grid) {
            this.grid = grid;
            this.columns = grid.length > 0 ? grid[0].length() : 0;
        }

        /**
         * Executes the pattern detection algorithm.
         *
         * @return {@code true} when the grid satisfies all conditions that caused the
         *         original program to print {@code "YES"}; otherwise {@code false}.
         */
        public boolean detectValidPattern() {
            // Flags that correspond to original variable names
            boolean patternDetected = false; // "l"
            boolean over = false;            // "over"
            boolean bad = false;             // "bad"
            boolean singleStarFound = false; // "s"
            int lastColumnWithSingleStar = -1;
            int consecutiveSingleStarRows = 0; // "cont"
            int rowIndexOfFirstSingleStar = -1; // stored in "cont" after first detection

            for (int row = 0; row < grid.length; row++) {
                RowInfo info = analyseRow(row);

                // 1. Exactly one star in the row – first occurrence
                if (info.starCount == 1 && !singleStarFound) {
                    singleStarFound = true;
                    lastColumnWithSingleStar = info.lastStar;
                    rowIndexOfFirstSingleStar = row;
                    consecutiveSingleStarRows = 1;
                    continue;
                }

                // 2. Consecutive rows containing exactly one star
                if (info.starCount == 1 && info.lastStar == lastColumnWithSingleStar
                        && row - rowIndexOfFirstSingleStar == 1) {
                    consecutiveSingleStarRows++;
                    // The original code set `over = true` when this condition was met
                    over = true;
                    continue;
                }

                // 3. Three or more stars, minimum gap of 1 and within the expected bounds
                if (!patternDetected && info.starCount >= 3
                        && info.maxGap == 1 && info.firstStar < info.lastStar
                        && info.firstStar != SENTINEL) {
                    patternDetected = true;
                    continue;
                }

                // Any other non‑empty row invalidates the whole input
                if (info.starCount > 0) {
                    bad = true;
                    break;
                }
            }

            // Final decision mirrors the original output rule:
            // YES only when all affirmative flags are set and no negative flag is set.
            return over && !bad && singleStarFound && patternDetected;
        }

        /**
         * Scans a single row and returns useful statistics about the positions of '*'
         * characters.
         */
        private RowInfo analyseRow(int rowIndex) {
            String line = grid[rowIndex];
            int firstStar = SENTINEL;
            int lastStar = -1;
            int starCount = 0;

            int previousCandidate = -1; // mimics original `prv`
            int currentCandidate = -1;  // mimics original `cur`
            int maxGap = 0;

            for (int col = 0; col < line.length(); col++) {
                if (line.charAt(col) == '*') {
                    if (firstStar == SENTINEL) {
                        firstStar = col;
                    }
                    lastStar = col;
                    starCount++;

                    if (previousCandidate != -1) {
                        int gap = currentCandidate - previousCandidate;
                        maxGap = Math.max(gap, maxGap);
                    }

                    previousCandidate = currentCandidate;
                    currentCandidate = col;
                }
            }

            return new RowInfo(starCount, firstStar, lastStar, maxGap);
        }

        /** Immutable container for the metrics derived from scanning a row. */
        private static final class RowInfo {
            final int starCount;   // number of '*' in the row
            final int firstStar;   // column index of the first '*'
            final int lastStar;    // column index of the last '*'
            final int maxGap;      // maximum distance between consecutive '*' positions

            RowInfo(int starCount, int firstStar, int lastStar, int maxGap) {
                this.starCount = starCount;
                this.firstStar = firstStar;
                this.lastStar = lastStar;
                this.maxGap = maxGap;
            }
        }
    }

    /** Entry point of the program. */
    public static void main(String[] args) throws IOException {
        // AutoCloseable ensures the InputReader releases system resources properly.
        try (InputReader reader = new InputReader()) {
            int height = reader.nextInt();
            int width = reader.nextInt();
            String[] grid = new String[height];

            for (int i = 0; i < height; i++) {
                grid[i] = reader.nextLine().trim();
            }

            PatternAnalyzer analyzer = new PatternAnalyzer(grid);
            boolean valid = analyzer.detectValidPattern();

            System.out.println(valid ? "YES" : "NO");
        }
    }
}

import java.io.*;
import java.util.*;

public class TaskE implements Runnable {

    /* -------------------------------------------------------------
     *  Configuration & constants
     * ------------------------------------------------------------- */
    private static final char STAR = '*';
    private static final char EMPTY = '.';
    private static final int MAX_ROWS = 500;   // upper bound for fast allocation
    private static final int MAX_COLS = 500;   // upper bound for fast allocation

    /* -------------------------------------------------------------
     *  Entry point
     * ------------------------------------------------------------- */
    public static void main(String[] args) throws Exception {
        new Thread(null, new TaskE(), "TaskE", 1 << 26).start();
    }

    /* -------------------------------------------------------------
     *  Core algorithm
     * ------------------------------------------------------------- */
    @Override
    public void run() {
        FastScanner scanner = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(System.out, true);

        // ----- read input -------------------------------------------------
        int rows = scanner.nextInt();
        int cols = scanner.nextInt();
        char[][] grid = readGrid(scanner, rows, cols);

        int totalStars = countStars(grid);
        if (tryBuildFullCross(grid, rows, cols, totalStars)) {
            out.println("YES");
        } else {
            out.println("NO");
        }

        out.close();
    }

    /* -------------------------------------------------------------
     *  Input handling
     * ------------------------------------------------------------- */
    private static char[][] readGrid(FastScanner in, int n, int m) {
        char[][] grid = new char[n][];
        for (int i = 0; i < n; i++) {
            grid[i] = in.next().toCharArray();
        }
        return grid;
    }

    private static int countStars(char[][] grid) {
        int count = 0;
        for (char[] row : grid) {
            for (char cell : row) {
                if (cell == STAR) {
                    count++;
                }
            }
        }
        return count;
    }

    /* -------------------------------------------------------------
     *  Cross detection logic
     * ------------------------------------------------------------- */
    /**
     * Tries to find a cell that can be the centre of a cross that uses
     * every '*' in the grid. Returns {@code true} if such a cross can be
     * built, {@code false} otherwise.
     */
    private static boolean tryBuildFullCross(char[][] grid, int rows, int cols, int totalStars) {
        for (int i = 1; i < rows - 1; i++) {
            for (int j = 1; j < cols - 1; j++) {
                if (isPotentialCrossCenter(grid, i, j)) {
                    int armsLength = computeCrossLengths(grid, i, j);
                    if (armsLength + 1 == totalStars) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    /** Returns true if the cell can possibly be the centre of a cross. */
    private static boolean isPotentialCrossCenter(char[][] grid, int i, int j) {
        return grid[i][j] == EMPTY &&
               grid[i - 1][j] == STAR &&   // up
               grid[i][j - 1] == STAR &&   // left
               grid[i][j + 1] == STAR &&   // right
               grid[i + 1][j] == STAR;     // down
    }

    /** Computes the total number of '*' that belong to the cross arms
     *  (excluding the centre). */
    private static int computeCrossLengths(char[][] grid, int centreRow, int centreCol) {
        int length = 0;

        // up
        for (int r = centreRow - 1; r >= 0 && grid[r][centreCol] == STAR; r--) {
            length++;
        }
        // left
        for (int c = centreCol - 1; c >= 0 && grid[centreRow][c] == STAR; c--) {
            length++;
        }
        // down
        for (int r = centreRow + 1; r < grid.length && grid[r][centreCol] == STAR; r++) {
            length++;
        }
        // right
        for (int c = centreCol + 1; c < grid[0].length && grid[centreRow][c] == STAR; c++) {
            length++;
        }
        return length;
    }

    /* -------------------------------------------------------------
     *  Fast I/O utilities (kept minimal and self‑contained)
     * ------------------------------------------------------------- */
    /** A tiny, high‑performance scanner based on BufferedInputStream. */
    private static class FastScanner {
        private final byte[] buffer = new byte[1 << 16];
        private int pointer = 0, length = 0;
        private final InputStream in;

        FastScanner(InputStream stream) {
            this.in = new BufferedInputStream(stream);
        }

        private int readByte() throws IOException {
            if (pointer >= length) {
                length = in.read(buffer);
                pointer = 0;
                if (length <= 0) {
                    return -1;
                }
            }
            return buffer[pointer++];
        }

        /** Skips whitespace characters. */
        private static int skipWhiteSpace(int b) {
            while (b == ' ' || b == '\n' || b == '\r' || b == '\t') {
                b = readByte();
            }
            return b;
        }

        /** Reads the next signed integer. */
        int nextInt() throws IOException {
            int c = skipWhiteSpace(readByte());
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = readByte();
            }
            int result = 0;
            while (c >= '0' && c <= '9') {
                result = result * 10 + (c - '0');
                c = readByte();
            }
            return result * sign;
        }

        /** Reads the next token (non‑whitespace characters). */
        String next() throws IOException {
            StringBuilder sb = new StringBuilder();
            int c = skipWhiteSpace(readByte());
            while (c != -1 && !(c == ' ' || c == '\n' || c == '\r' || c == '\t')) {
                sb.appendCodePoint(c);
                c = readByte();
            }
            return sb.toString();
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Reads a grid of characters ('*' and others) and determines whether the
 * positions of '*' form a single cross (a plus sign) that covers *all* stars.
 *
 * <p>If such a cross exists the program prints {@code YES}, otherwise it prints
 * {@code NO}.</p>
 */
public class Main {

    /** Directions to explore from a candidate centre. */
    private static final int[] DR = { -1, 1, 0, 0 };
    private static final int[] DC = { 0, 0, -1, 1 };

    public static void main(String[] args) throws IOException {
        // --------------------------------------------------------------
        // 1️⃣  Input handling – try‑with‑resources guarantees closure
        // --------------------------------------------------------------
        try (BufferedReader br = new BufferedReader(
                new InputStreamReader(System.in));
             PrintWriter out = new PrintWriter(System.out)) {

            // --------------------------------------------------------------
            // 2️⃣  Parse first line → dimensions
            // --------------------------------------------------------------
            StringTokenizer st = new StringTokenizer(br.readLine());
            int rows = Integer.parseInt(st.nextToken());
            int cols = Integer.parseInt(st.nextToken());

            // --------------------------------------------------------------
            // 3️⃣  Build boolean matrix and count stars
            // --------------------------------------------------------------
            boolean[][] grid = new boolean[rows][cols];
            int totalStars = 0;

            for (int r = 0; r < rows; r++) {
                String line = br.readLine();
                if (line == null) {
                    break;
                }
                for (int c = 0; c < cols; c++) {
                    grid[r][c] = line.charAt(c) == '*';
                    if (grid[r][c]) {
                        totalStars++;
                    }
                }
            }

            // --------------------------------------------------------------
            // 4️⃣  Look for a centre that can start a plus sign
            // --------------------------------------------------------------
            boolean foundCross = false;

            for (int r = 1; r < rows - 1 && !foundCross; r++) {
                for (int c = 1; c < cols - 1 && !foundCross; c++) {
                    if (isPotentialCentre(grid, r, c)) {
                        foundCross = validateCross(grid, r, c, totalStars);
                    }
                }
            }

            // --------------------------------------------------------------
            // 5️⃣  Output result
            // --------------------------------------------------------------
            out.println(foundCross ? "YES" : "NO");
        }
    }

    /**
     * Returns {@code true} if the cell (r,c) has stars on its four orthogonal
     * neighbours – a necessary condition to be the centre of a cross.
     */
    private static boolean isPotentialCentre(boolean[][] grid, int r, int c) {
        return grid[r][c]
                && grid[r - 1][c]
                && grid[r + 1][c]
                && grid[r][c - 1]
                && grid[r][c + 1];
    }

    /**
     * Checks whether all stars in the grid belong to a single cross whose
     * centre is at (r,c).  The method returns {@code true} as soon as the
     * condition is satisfied.
     *
     * @return {@code true} if the whole star pattern is exactly a plus sign
     *         whose total number of stars equals the computed cross size.
     */
    private static boolean validateCross(boolean[][] grid, int r, int c, int totalStars) {
        // Length of each arm *excluding* the centre
        int up = countArm(grid, r, c, -1, 0);
        int down = countArm(grid, r, c, 1, 0);
        int left = countArm(grid, r, c, 0, -1);
        int right = countArm(grid, r, c, 0, 1);

        int starsInCross = 1 + up + down + left + right; // centre + four arms

        return starsInCross == totalStars;
    }

    /**
     * Counts how many consecutive stars exist starting from the neighbour
     * (r+dr, c+dc) and moving in the direction (dr,dc) until a non‑star or the
     * border is reached.
     *
     * @param dr row step (e.g. -1 for upward)
     * @param dc column step (e.g. 1 for rightward)
     */
    private static int countArm(boolean[][] grid, int centreR, int centreC,
                                int dr, int dc) {
        int cnt = 0;
        int r = centreR + dr;
        int c = centreC + dc;
        while (inBounds(grid, r, c) && grid[r][c]) {
            cnt++;
            r += dr;
            c += dc;
        }
        return cnt;
    }

    /** Helper that checks whether a cell lies inside the matrix. */
    private static boolean inBounds(boolean[][] grid, int r, int c) {
        return r >= 0 && r < grid.length && c >= 0 && c < grid[0].length;
    }
}

import java.io.*;
import java.util.*;

/**
 * Entry point of the application.
 *
 * <p>It creates the necessary I/O streams, builds a {@link Solver} and
 * delegates the work to it. The program prints either "YES" or "NO"
 * describing whether the picture contains exactly one valid
 * B+ cross made of '*' characters.</p>
 */
public class Main {

    public static void main(String[] args) {
        // Using try‑with‑resources guarantees that the streams are closed
        // even when an exception occurs.
        try (InputStream in = System.in;
             PrintWriter out = new PrintWriter(System.out)) {

            new Solver().solve(in, out);
        }
    }

    /**
     * Solves a single test case.
     *
     * <p>The method reads the board dimensions, the board itself and hands
     * the data over to {@link BPlusValidator}.  After validation it prints
     * either "YES" (exactly one valid cross and no stray '*') or "NO".</p>
     */
    static final class Solver {

        /** Reads everything from the supplied {@link InputStream} and starts processing. */
        void solve(InputStream input, PrintWriter out) {
            FastScanner scanner = new FastScanner(input);

            int width  = scanner.nextInt();
            int height = scanner.nextInt();

            char[][] board = readBoard(scanner, width, height);

            BPlusValidator validator = new BPlusValidator(board);
            validator.process();                 // prints the answer

            out.flush();
        }

        /** Populates a {@code char[][]} from the scanner according to the declared size. */
        private char[][] readBoard(FastScanner fs, int w, int h) {
            char[][] board = new char[w][h];
            for (int i = 0; i < w; i++) {
                for (int j = 0; j < h; j++) {
                    board[i][j] = fs.nextCharacter();
                }
            }
            return board;
        }
    }

    /**
     * Fast, low‑level scanner that skips whitespace characters.
     *
     * <p>It is deliberately simple and does not allocate a new {@code String}
     * for each token, which keeps the parsing overhead minimal.</p>
     */
    static final class FastScanner {

        private final InputStream stream;
        private final byte[] buffer = new byte[16_384];
        private int pointer = 0, limit = 0;

        FastScanner(InputStream stream) {
            this.stream = stream;
        }

        /** Reads a single byte from the underlying stream (with buffering). */
        private int readByte() throws IOException {
            if (pointer >= limit) {
                limit = stream.read(buffer);
                pointer = 0;
                if (limit <= 0) return -1;
            }
            return buffer[pointer++];
        }

        /** Returns the next non‑whitespace character. */
        char nextCharacter() throws IOException {
            int c;
            while ((c = readByte()) <= ' ') {}
            return (char) c;
        }

        /** Reads the next signed integer from the input. */
        int nextInt() throws IOException {
            int sign = 1;
            int c = readByte();
            while (c <= ' ') c = readByte();               // skip whitespace

            if (c == '-') {                                 // handle optional sign
                sign = -1;
                c = readByte();
            }

            int result = 0;
            while (c > ' ') {                               // accumulate digits
                result = result * 10 + (c - '0');
                c = readByte();
            }
            return result * sign;
        }
    }

    /**
     * Encapsulates the algorithm that validates a B+ cross pattern.
     *
     * <p>It scans the board for a possible centre, marks all asterisks that
     * belong to the discovered cross and finally checks that no stray '*'
     * remains and that exactly one centre was found.</p>
     */
    static final class BPlusValidator {

        private final char[][] board;   // the picture read from input
        private final boolean[][] used; // tracks which '*' has been consumed by a cross
        private int centreCount = 0;      // how many valid centres we discovered

        BPlusValidator(char[][] board) {
            this.board = board;
            this.used  = new boolean[board.length][board[0].length];
        }

        /** Main entry point – performs the scan and prints the result. */
        void process() {
            int rows = board.length;
            int cols = board[0].length;

            // 1️⃣  Look for a centre that can start a '+' shape.
            for (int r = 1; r < rows - 1; r++) {
                for (int c = 1; c < cols - 1; c++) {
                    if (isPotentialCentre(r, c)) {
                        consumeCross(r, c);
                        centreCount++;
                    }
                }
            }

            // 2️⃣  If any asterisk was never consumed, the picture is invalid.
            if (hasUnusedAsterisk()) {
                System.out.println("NO");
                return;
            }

            // 3️⃣  Exactly one centre must have been found.
            System.out.println(centreCount == 1 ? "YES" : "NO");
        }

        /** Checks whether (r,c) can be the centre of a valid '+' shape. */
        private boolean isPotentialCentre(int r, int c) {
            return board[r][c] == '*' &&
                   board[r - 1][c] == '*' &&
                   board[r + 1][c] == '*' &&
                   board[r][c - 1] == '*' &&
                   board[r][c + 1] == '*';
        }

        /**
         * Marks the centre and all connected asterisks in the four orthogonal
         * directions.  This method is deliberately split into small helpers
         * for readability.
         */
        private void consumeCross(int centreRow, int centreCol) {
            markVertical(centreRow, centreCol);
            markHorizontal(centreRow, centreCol);
        }

        /** Marks all '*' upward and downward from the given cell in the same column. */
        private void markVertical(int row, int col) {
            // upward direction
            for (int r = row; r >= 0 && board[r][col] == '*'; r--) {
                used[r][col] = true;
            }
            // downward direction
            for (int r = row; r < board.length && board[r][col] == '*'; r++) {
                used[r][col] = true;
            }
        }

        /** Marks all '*' to the left and right of the given cell in the same row. */
        private void markHorizontal(int row, int col) {
            // leftward direction
            for (int c = col; c >= 0 && board[row][c] == '*'; c--) {
                used[row][c] = true;
            }
            // rightward direction
            for (int c = col; c < board[0].length && board[row][c] == '*'; c++) {
                used[row][c] = true;
            }
        }

        /** Returns {@code true} if any asterisk in the board was never marked. */
        private boolean hasUnusedAsterisk() {
            for (int r = 0; r < board.length; r++) {
                for (int c = 0; c < board[r].length; c++) {
                    if (board[r][c] == '*' && !used[r][c]) {
                        return true;
                    }
                }
            }
            return false;
        }
    }
}

import java.io.BufferedReader;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.Scanner;

public class codeforcesreturn {
    private static final int[] DX = {1, -1, 0, 0};
    private static final int[] DY = {0, 0, 1, -1};

    public static void main(String[] args) throws Exception {
        try (PrintWriter pw = new PrintWriter(System.out)) {
            Scanner sc = new Scanner(System.in);
            int h = sc.nextInt();
            int w = sc.nextInt();
            boolean[][] grid = readGrid(sc, h, w);

            int[] center = findCenter(grid, h, w);
            if (center[0] == -1) {
                pw.println("NO");
                return;
            }

            int R = center[0];
            int C = center[1];

            if (!isValidGrid(grid, R, C, h, w)) {
                pw.println("NO");
                return;
            }

            pw.println("YES");
        }
    }

    private static boolean[][] readGrid(Scanner sc, int h, int w) {
        boolean[][] grid = new boolean[h][w];
        for (int i = 0; i < h; i++) {
            String row = sc.next();
            for (int j = 0; j < w; j++) {
                grid[i][j] = (row.charAt(j) == '*');
            }
        }
        return grid;
    }

    private static int[] findCenter(boolean[][] grid, int h, int w) {
        for (int i = 1; i < h - 1; i++) {
            for (int j = 1; j < w - 1; j++) {
                if (grid[i][j] && hasAllNeighborsObstacle(grid, i, j)) {
                    return new int[]{i, j};
                }
            }
        }
        return new int[]{-1, -1};
    }

    private static boolean hasAllNeighborsObstacle(boolean[][] grid, int i, int j) {
        for (int d = 0; d < 4; d++) {
            int ni = i + DX[d];
            int nj = j + DY[d];
            if (!grid[ni][nj]) {
                return false;
            }
        }
        return true;
    }

    private static boolean isValidGrid(boolean[][] grid, int R, int C, int h, int w) {
        // Check all obstacles are in row R or column C
        for (int i = 0; i < h; i++) {
            for (int j = 0; j < w; j++) {
                if (grid[i][j] && i != R && j != C) {
                    return false;
                }
            }
        }

        // Check row R has contiguous obstacles
        if (!isContiguousRow(grid, R, w)) {
            return false;
        }

        // Check column C has contiguous obstacles
        if (!isContiguousColumn(grid, C, h)) {
            return false;
        }

        return true;
    }

    private static boolean isContiguousRow(boolean[][] grid, int row, int width) {
        boolean inSegment = false;
        boolean endedSegment = false;

        for (int j = 0; j < width; j++) {
            if (grid[row][j]) {
                if (!inSegment) {
                    inSegment = true;
                } else if (endedSegment) {
                    return false;
                }
            } else {
                if (inSegment && !endedSegment) {
                    endedSegment = true;
                }
            }
        }
        return true;
    }

    private static boolean isContiguousColumn(boolean[][] grid, int col, int height) {
        boolean inSegment = false;
        boolean endedSegment = false;

        for (int i = 0; i < height; i++) {
            if (grid[i][col]) {
                if (!inSegment) {
                    inSegment = true;
                } else if (endedSegment) {
                    return false;
                }
            } else {
                if (inSegment && !endedSegment) {
                    endedSegment = true;
                }
            }
        }
        return true;
    }
}

package com.example;

/**
 * Refactored version of the original program.
 * <p>
 * The program reads a rectangular grid of characters ('*' or '.') and checks
 * whether there is exactly one connected component of '*' that contains
 * precisely one cell with four orthogonal neighbours (a “cross” centre) and
 * no other cell with more than one neighbour.
 * </p>
 * <p>
 * The implementation is split into small, cohesive classes to improve
 * readability, testability and maintainability.
 * </p>
 */
public class Main {

    /** Entry point of the application. */
    public static void main(String[] args) throws IOException {
        // The try‑with‑resources block guarantees that the underlying stream is closed.
        try (FastReader reader = new FastReader()) {
            int rows = reader.nextInt();
            int cols = reader.nextInt();

            // Read the grid row by row.
            char[][] grid = new char[rows][cols];
            for (int r = 0; r < rows; r++) {
                String line = reader.next();
                System.arraycopy(line.toCharArray(), 0, grid[r], 0, cols);
            }

            // Analyse the grid and produce the required result.
            Analyzer analyzer = new Analyzer(grid);
            analyzer.analyze();

            // Apply the specification‑driven output condition.
            if (analyzer.hasExactlyOneComponent()
                    && analyzer.exactlyOneCellWithDegreeFour()
                    && analyzer.exactlyOneCellWithDegreeGreaterThanOne()) {
                System.out.println("YES");
            } else {
                System.out.println("NO");
            }
        }
    }

    /** A tiny, fast scanner that works with {@link System#in}. */
    private static final class FastReader {
        private final BufferedReader br;
        private StringTokenizer st;

        FastReader() {
            this.br = new BufferedReader(new InputStreamReader(System.in));
        }

        /** Returns the next token, reading a new line if necessary. */
        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    throw new UncheckedIOException(e);
                }
            }
            return st.nextToken();
        }

        /** Reads the next integer token. */
        int nextInt() {
            return Integer.parseInt(next());
        }
    }

    /**
     * Encapsulates all the processing that is required on the grid:
     * DFS traversal, neighbour counting and the final condition checks.
     */
    private static final class Analyzer {
        private final char[][] grid;
        private final boolean[][] visited;
        private final int rows;
        private final int cols;

        // Counters that are needed for the final decision.
        private int componentCount = 0;
        private int degreeGreaterThanOne = 0; // cells with > 1 neighbour
        private int degreeExactlyFour = 0;    // cells with exactly 4 neighbours

        Analyzer(char[][] grid) {
            this.grid = grid;
            this.rows = grid.length;
            this.cols = grid[0].length;
            this.visited = new boolean[rows][cols];
        }

        /** Starts the analysis from every unvisited '*' cell. */
        void analyze() {
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (!visited[r][c] && grid[r][c] == '*') {
                        dfs(r, c);
                        componentCount++;
                    }
                }
            }
        }

        /** Depth‑first search that also updates the counters. */
        private void dfs(int r, int c) {
            visited[r][c] = true;

            int degree = countStarNeighbours(r, c);
            if (degree > 1) {
                degreeGreaterThanOne++;
            }
            if (degree == 4) {
                degreeExactlyFour++;
            }

            // Explore the four orthogonal neighbours.
            for (int[] dir : DIRS) {
                int nr = r + dir[0];
                int nc = c + dir[1];
                if (isInBounds(nr, nc) && grid[nr][nc] == '*' && !visited[nr][nc]) {
                    dfs(nr, nc);
                }
            }
        }

        /** Returns how many orthogonal '*' neighbours a cell has. */
        private int countStarNeighbours(int r, int c) {
            int count = 0;
            for (int[] dir : DIRS) {
                int nr = r + dir[0];
                int nc = c + dir[1];
                if (isInBounds(nr, nc)) {
                    count++;
                }
            }
            return count;
        }

        /** Helper that checks array bounds and that the neighbour is '*'. */
        private boolean isInBounds(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols && grid[r][c] == '*';
        }

        /** Queries whether there is exactly one connected component of '*'. */
        boolean hasExactlyOneComponent() {
            return componentCount == 1;
        }

        /** Queries whether there is exactly one cell with four neighbours. */
        boolean exactlyOneCellWithDegreeFour() {
            return degreeExactlyFour == 1;
        }

        /** Queries whether there is exactly one cell that has more than one neighbour. */
        boolean exactlyOneCellWithDegreeGreaterThanOne() {
            return degreeGreaterThanOne == 1;
        }
    }

    /** Directions: down, right, up, left – used for orthogonal movement. */
    private static final int[][] DIRS = {
            {1, 0},   // down
            {0, 1},   // right
            {-1, 0},  // up
            {0, -1}   // left
    };
}

import java.util.Scanner;

/**
 * Refactored version of the original program.
 * <p>
 * The program reads a rectangular grid of characters (only '*' and '.' are expected),
 * looks for a single '+' made of '*' symbols, removes that whole plus,
 * and then checks whether any '*' remain in the grid.
 * If no stars are left after removal it prints {@code "YES"}, otherwise {@code "NO"}.
 * </p>
 */
public class Main {

    private static final Scanner SCANNER = new Scanner(System.in);

    public static void main(String[] args) {
        int height = readInt();
        int width  = readInt();
        String[] rows = readLines(height);

        char[][] grid = buildGrid(rows);

        if (processPlusAndCheck(grid, height, width)) {
            System.out.println("YES");
        } else {
            System.out.println("NO");
        }
    }

    /** Reads an integer from standard input. */
    private static int readInt() {
        return SCANNER.nextInt();
    }

    /** Reads the next {@code count} lines from standard input. */
    private static String[] readLines(int count) {
        SCANNER.nextLine();               // consume the newline left by nextInt()
        String[] lines = new String[count];
        for (int i = 0; i < count; i++) {
            lines[i] = SCANNER.nextLine();
        }
        return lines;
    }

    /** Converts the read strings into a 2‑dimensional char array. */
    private static char[][] buildGrid(String[] rows) {
        char[][] grid = new char[rows.length][rows[0].length()];
        for (int i = 0; i < rows.length; i++) {
            for (int j = 0; j < rows[i].length(); j++) {
                grid[i][j] = rows[i].charAt(j);
            }
        }
        return grid;
    }

    /** Determines whether a plus sign can be found, cleared, and leaves no '*' behind. */
    private static boolean processPlusAndCheck(char[][] grid, int h, int w) {
        for (int i = 1; i < h - 1; i++) {
            for (int j = 1; j < w - 1; j++) {
                if (isPlusCenter(grid, i, j)) {
                    clearPlus(grid, i, j);
                    return noStarsRemain(grid);
                }
            }
        }
        return false;   // no valid plus was found
    }

    /** Checks if the cell at (row, col) is the centre of a '+' made of '*'. */
    private static boolean isPlusCenter(char[][] grid, int row, int col) {
        return grid[row][col] == '*' &&
               grid[row - 1][col] == '*' && // up
               grid[row + 1][col] == '*' && // down
               grid[row][col - 1] == '*' && // left
               grid[row][col + 1] == '*';   // right
    }

    /** Clears the whole plus sign whose centre is at (centerRow, centerCol). */
    private static void clearPlus(char[][] grid, int centerRow, int centerCol) {
        clearVerticalArm(grid, centerCol);
        clearHorizontalArm(grid, centerRow);
        grid[centerRow][centerCol] = '.'; // clear the centre itself
    }

    /** Clears a vertical column of '*' starting from the given column index. */
    private static void clearVerticalArm(char[][] grid, int col) {
        // upward sweep
        for (int r = 0; r < grid.length; r++) {
            if (grid[r][col] == '*') {
                grid[r][col] = '.';
            } else {
                break;
            }
        }
        // downward sweep
        for (int r = grid.length - 1; r >= 0; r--) {
            if (grid[r][col] == '*') {
                grid[r][col] = '.';
            } else {
                break;
            }
        }
    }

    /** Clears a horizontal row of '*' starting from the given row index. */
    private static void clearHorizontalArm(char[][] grid, int row) {
        // left sweep
        for (int c = 0; c < grid[row].length; c++) {
            if (grid[row][c] == '*') {
                grid[row][c] = '.';
            } else {
                break;
            }
        }
        // right sweep
        for (int c = grid[row].length - 1; c >= 0; c--) {
            if (grid[row][c] == '*') {
                grid[row][c] = '.';
            } else {
                break;
            }
        }
    }

    /** Returns {@code true} if the grid contains no '*' characters any more. */
    private static boolean noStarsRemain(char[][] grid) {
        for (char[] row : grid) {
            for (char cell : row) {
                if (cell == '*') {
                    return false;
                }
            }
        }
        return true;
    }
}

import java.io.*;
import java.util.*;

/**
 * Refactored solution for the “cross of stars” validation problem.
 *
 * <p>Key improvements over the original code:
 * <ul>
 *   <li>Clear separation of concerns (scanning, centre detection, collection, validation).</li>
 *   <li>Descriptive naming and removal of unnecessary wrappers (no {@code Pair} class, no manual {@code HashSet} look‑ups).</li>
 *   <li>Robust {@code FastScanner} that handles tokens and lines cleanly.</li>
 *   <li>Use of a tiny immutable {@code Point} class with proper {@code equals} / {@code hashCode}.</li>
 *   <li>Early failure with an explicit exception when the pattern is broken, making the flow easier to read.</li>
 *   <li>Comments and section headers that explain the purpose of each method.</li>
 * </ul>
 */
public class B {

    /** Simple immutable point used as a key in a {@link HashSet}. */
    private static final class Point {
        final int row;
        final int col;

        Point(int row, int col) {
            this.row = row;
            this.col = col;
        }

        @Override public boolean equals(Object o) {
            if (this == o) return true;
            if (!(o instanceof Point)) return false;
            Point p = (Point) o;
            return row == p.row && col == p.col;
        }

        @Override public int hashCode() {
            return Objects.hash(row, col);
        }
    }

    /** Fast scanner that lazily tokenises lines from {@code System.in}. */
    private static final class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner(InputStream stream) {
            br = new BufferedReader(new InputStreamReader(stream));
        }

        /** Returns the next token, creating a new {@link StringTokenizer} when needed. */
        private String nextToken() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                String line = br.readLine();
                if (line == null) return null;          // EOF
                st = new StringTokenizer(line);
            }
            return st.nextToken();
        }

        int nextInt() throws IOException               { return Integer.parseInt(nextToken()); }
        long nextLong() throws IOException             { return Long.parseLong(nextToken()); }
        double nextDouble() throws IOException         { return Double.parseDouble(nextToken()); }

        /** Returns the remainder of the current line (may be empty). */
        String nextLine() throws IOException {
            return br.readLine();
        }
    }

    public static void main(String[] args) throws Exception {
        try (FastScanner fs = new FastScanner(System.in)) {
            int n = Integer.parseInt(fs.nextToken());
            int m = Integer.parseInt(fs.nextToken());

            String[] grid = new String[n];
            for (int i = 0; i < n; i++) {
                grid[i] = fs.nextLine();
            }

            Point centre = locateCrossCentre(grid);
            if (centre == null) {
                System.out.println("NO");
                return;
            }

            Set<Point> stars;
            try {
                stars = collectStars(grid, centre);
            } catch (IllegalStateException e) {
                // Gap detected – pattern is not a single continuous cross.
                System.out.println("NO");
                return;
            }

            if (validatePattern(grid, stars, centre)) {
                System.out.println("YES");
            } else {
                System.out.println("NO");
            }
        }
    }

    /** Finds a cell that has a '*' on all five positions of a plus shape. */
    private static Point locateCrossCentre(String[] grid) {
        int rows = grid.length;
        int cols = grid[0].length();

        for (int r = 1; r < rows - 1; r++) {
            String row = grid[r];
            for (int c = 1; c < cols - 1; c++) {
                char cell = row.charAt(c);
                if (cell == '*' &&
                        cell == grid[r - 1].charAt(c) &&               // up
                        cell == grid[r + 1].charAt(c) &&               // down
                        cell == row.charAt(c - 1) &&                   // left
                        cell == row.charAt(c + 1)) {                   // right
                    return new Point(r, c);
                }
            }
        }
        return null; // no plus found
    }

    /** Collects all '*' belonging to the horizontal and vertical arms of the plus. */
    private static Set<Point> collectStars(String[] grid, Point centre) {
        Set<Point> stars = new HashSet<>();

        // ---- horizontal arm ----
        String row = grid[centre.row];
        collectHorizontalArm(row, centre.col, stars);

        // ---- vertical arm ----
        for (int r = 0; r < grid.length; r++) {
            if (grid[r].charAt(centre.col) == '*') {
                stars.add(new Point(r, centre.col));
            }
        }

        return stars;
    }

    /**
     * Scans the row that contains the centre and adds every '*' that appears contiguously.
     * If a gap (a '.' after at least one '*') is observed, an {@link IllegalStateException}
     * is thrown to signal an invalid pattern.
     */
    private static void collectHorizontalArm(String row, int centreCol, Set<Point> stars) {
        boolean found = false;   // have we met the first '*' of the arm?
        boolean stopped = false; // have we passed that first block?

        for (int c = 0; c < row.length(); c++) {
            char ch = row.charAt(c);
            if (found) {
                if (ch == '*') {
                    if (stopped) {
                        // A '*' appears after we already saw a '.' → broken arm.
                        throw new IllegalStateException("Gap detected in horizontal arm");
                    }
                    stars.add(new Point(centre.row, c));
                } else {
                    stopped = true; // we left the contiguous '*' block
                }
            } else {
                if (ch == '*') {
                    found = true;
                    stars.add(new Point(centre.row, c));
                }
            }
        }
    }

    /** Verifies that every '*' in the whole grid belongs to the collected set. */
    private static boolean validatePattern(String[] grid, Set<Point> stars, Point centre) {
        for (int r = 0; r < grid.length; r++) {
            String row = grid[r];
            for (int c = 0; c < row.length(); c++) {
                if (row.charAt(c) == '*') {
                    if (!stars.contains(new Point(r, c))) {
                        // A star is not part of the defined arms → invalid.
                        return false;
                    }
                }
            }
        }
        return true;
    }
}

import java.io.IOException;
import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;

/**
 * Reads a grid of characters and checks whether all '*' cells form a single
 * plus‑shaped (cross) pattern. The program prints "YES" if such a cross exists,
 * otherwise it prints "NO".
 *
 * <p>All operations are deliberately separated into small, well‑named static
 * methods to improve readability, testability and maintainability.</p>
 */
public class GridAnalyzer {

    /** Symbol that marks a filled cell. */
    private static final char STAR = '*';

    /**
     * Entry point of the program.
     *
     * @param args command line arguments (unused)
     * @throws IOException if an I/O error occurs while reading input
     */
    public static void main(String[] args) throws IOException {
        // Use try‑with‑resources to guarantee the Scanner is closed.
        try (Scanner scanner = new Scanner(System.in)) {
            // -----------------------------------------------------------------
            // 1. Read dimensions and the grid itself
            // -----------------------------------------------------------------
            int width  = scanner.nextInt();   // number of rows
            int height = scanner.nextInt();   // number of columns
            scanner.nextLine();               // consume the rest of the line

            List<String> grid = new ArrayList<>(width);
            for (int r = 0; r < width; r++) {
                String line = scanner.nextLine().trim();
                grid.add(line);
            }

            // -----------------------------------------------------------------
            // 2. Count total '*' occurrences
            // -----------------------------------------------------------------
            int totalStars = countStars(grid);

            // -----------------------------------------------------------------
            // 3. Search for a valid plus‑shaped cross
            // -----------------------------------------------------------------
            boolean found = hasValidCross(grid, totalStars);

            // -----------------------------------------------------------------
            // 4. Output the result
            // -----------------------------------------------------------------
            System.out.println(found ? "YES" : "NO");
        }
    }

    /**
     * Counts how many cells contain the '*' character in the supplied grid.
     *
     * @param grid list of rows, each row being a string
     * @return total number of '*' characters
     */
    private static int countStars(List<String> grid) {
        int count = 0;
        for (String row : grid) {
            for (int c = 0; c < row.length(); c++) {
                if (row.charAt(c) == STAR) {
                    count++;
                }
            }
        }
        return count;
    }

    /**
     * Determines whether the collection of '*' cells constitutes a single
     * continuous cross (arms extending in all four cardinal directions).
     *
     * @param grid     the rectangular grid to inspect
     * @param totalStars the exact number of '*' cells expected
     * @return {@code true} if a valid cross is found, otherwise {@code false}
     */
    private static boolean hasValidCross(List<String> grid, int totalStars) {
        int rows = grid.size();
        int cols = grid.get(0).length();

        for (int r = 0; r < rows; r++) {
            String line = grid.get(r);
            for (int c = 0; c < cols; c++) {
                if (line.charAt(c) != STAR) {
                    continue; // only cells containing '*' can be the centre of a cross
                }

                // measure the length of each arm of the potential cross
                int right  = countRight(line, c);
                int left   = countLeft(line, c);
                int down   = countDown(grid, r, c);
                int up     = countUp(grid, r, c);

                int armLength = 1 + right + left + down + up; // centre + 4 arms

                // The cross is valid only if it uses *all* stars and every arm
                // contains at least one additional '*'
                if (armLength == totalStars && right > 0 && left > 0 && down > 0 && up > 0) {
                    return true;
                }
            }
        }
        return false;
    }

    /** Counts consecutive '*' to the right of {@code start} in the given line. */
    private static int countRight(String line, int start) {
        int cnt = 0;
        for (int i = start + 1; i < line.length(); i++) {
            if (line.charAt(i) == STAR) {
                cnt++;
            } else {
                break;
            }
        }
        return cnt;
    }

    /** Counts consecutive '*' to the left of {@code start} in the given line. */
    private static int countLeft(String line, int start) {
        int cnt = 0;
        for (int i = start - 1; i >= 0; i--) {
            if (line.charAt(i) == STAR) {
                cnt++;
            } else {
                break;
            }
        }
        return cnt;
    }

    /** Counts consecutive '*' downward from (row, col) in the grid. */
    private static int countDown(List<String> grid, int row, int col) {
        int cnt = 0;
        for (int r = row + 1; r < grid.size(); r++) {
            String nextLine = grid.get(r);
            if (col >= nextLine.length() || nextLine.charAt(col) != STAR) {
                break;
            }
            cnt++;
        }
        return cnt;
    }

    /** Counts consecutive '*' upward from (row, col) in the grid. */
    private static int countUp(List<String> grid, int row, int col) {
        int cnt = 0;
        for (int r = row - 1; r >= 0; r--) {
            String prevLine = grid.get(r);
            if (col >= prevLine.length() || prevLine.charAt(col) != STAR) {
                break;
            }
            cnt++;
        }
        return cnt;
    }
}

/**
 * Refactored version of the original program.
 *
 * <p>This program reads a grid of characters, checks whether a single '+' shape
 * (consisting of a central cell with non‑zero length extensions in the four
 * orthogonal directions) contains **all** the '*' cells in the grid, and prints
 * {@code YES} if such a plus exists, otherwise {@code NO}.
 *
 * <p>The implementation focuses on readability, maintainability and correctness
 * by separating concerns, using well‑named methods, and avoiding deep nesting.
 */
public class Main {

    /** Entry point of the program. */
    public static void main(String[] args) {
        try (InputReader reader = new InputReader(System.in);
             PrintWriter writer = new PrintWriter(System.out)) {

            int height = reader.nextInt();
            int width  = reader.nextInt();

            String[] grid = reader.nextStringArray(height);
            BPlusFromPicture solver = new BPlusFromPicture();

            solver.solve(1, reader, writer, grid);
        }
