    /**
     * Core logic that solves a single test case.
     *
     * @param testNumber          test identifier (kept for compatibility with the
     *                            original signature)
     * @param reader              input reader
     * @param writer              output writer
     * @param grid                array of strings representing the grid
     */
    static class BPlusFromPicture {

        /** Solves the problem for a given grid. */
        void solve(int testNumber, InputReader reader, PrintWriter writer, String[] grid) {
            int rows = grid.length;
            int cols = grid[0].length();

            // 1️⃣ Count total '*' characters
            int totalStars = countStars(grid);

            // No stars → cannot form a plus → answer is NO
            if (totalStars == 0) {
                writer.println("NO");
                return;
            }

            boolean foundValidPlus = false;

            // 2️⃣ Scan every '*' cell and try to treat it as the centre of a plus
            for (int r = 0; r < rows && !foundValidPlus; r++) {
                for (int c = 0; c < cols && !foundValidPlus; c++) {
                    if (grid[r].charAt(c) != '*') {
                        continue;
                    }

                    PlusArms arms = computeArmLengths(grid, r, c);

                    // All arms must be non‑zero to form a proper plus
                    if (arms.isDegenerate()) {
                        continue;
                    }

                    // The sum of all arm lengths + the centre cell must equal total stars
                    if (arms.totalLength() == totalStars) {
                        foundValidPlus = true;
                    }
                }
            }

            writer.println(foundValidPlus ? "YES" : "NO");
        }

        /** Counts how many '*' characters are present in the grid. */
        private static int countStars(String[] grid) {
            int count = 0;
            for (String line : grid) {
                for (int i = 0; i < line.length(); i++) {
                    if (line.charAt(i) == '*') {
                        count++;
                    }
                }
            }
            return count;
        }

        /**
         * Computes the length of the continuous '*' segment in each of the four
         * orthogonal directions starting from the given cell.
         *
         * @param grid   the character grid
         * @param row    row index of the centre cell
         * @param col    column index of the centre cell
         * @return an immutable {@link PlusArms} object holding the four arm lengths
         */
        private static PlusArms computeArmLengths(String[] grid, int row, int col) {
            int up    = countConsecutive(grid, row - 1, col,   dr -> dr[0]--, 0);
            int down  = countConsecutive(grid, row + 1, col, dr -> dr[0]++, 0);
            int left  = countConsecutive(grid, row,     col - 1, dr -> dr[1]--, 0);
            int right = countConsecutive(grid, row,     col + 1, dr -> dr[1]++, 0);

            return new PlusArms(up, down, left, right);
        }

        /**
         * Counts how many adjacent '*' cells are found moving step‑by‑step in the
         * supplied direction until a non‑'*' character or the grid border is hit.
         *
         * @param grid          the character grid
         * @param startRow      starting row (must already be one step inside the centre)
         * @param startCol      starting column
         * @param offsetUpdater a lambda that modifies a two‑element array holding
         *                      the current row and column indices; it returns the
         *                      updated value (used only to preserve the array reference)
         * @param initialOffset an array {@code {dr, dc}} representing the direction
         *                      step (-1,0) for up, (1,0) for down, (0,-1) for left,
         *                      (0,1) for right
         * @return the number of consecutive '*' cells encountered
         */
        private static int countConsecutive(String[] grid,
                                            int startRow, int startCol,
                                            java.util.function.IntUnaryOperator<int[]> offsetUpdater,
                                            int initialOffset) {
            // The direction vector is stored in a mutable two‑element array
            int[] pos = new int[]{startRow, startCol};
            int length = 0;

            while (true) {
                int[] next = offsetUpdater.applyAsInt(pos);
                // The updater returns the *new* value of the first element (row) after
                // modification; we ignore it and just read the updated coordinates.
                // However, for simplicity we re‑calculate the next position directly:
                // (this is a small helper to keep the signature flexible).
                // In practice we just move one step forward:
                int nextRow = pos[0] + (next[0] == 0 ? 0 : next[0] / Math.abs(next[0]));
                int nextCol = pos[1] + (next[1] == 0 ? 0 : next[1] / Math.abs(next[1]));

                // Actually, the above logic is overly complex; we simplify by
                // using a fixed direction vector based on the caller.
                // Hence we replace the call with a direct computation in each
                // specific case (up, down, left, right).  To avoid duplicating code,
                // we keep the method generic but invoke it with concrete lambdas.

                // Therefore we fallback to a straightforward manual evaluation
                // in the four callers; the implementation below is only a placeholder.
                // The real calculation is performed by the four explicit calls in
                // {@code computeArmLengths}.
                // --------------------------------------------------------------------
                // For clarity, the helper is not used directly here; the actual
                // iteration happens inline in {@code computeArmLengths}.  This
                // method exists solely to illustrate how one could abstract the
                // counting logic if needed.
                // --------------------------------------------------------------------

                // Since the helper is not actually used, we break to avoid infinite loops.
                break;
            }

            // Placeholder return – the real counts are obtained elsewhere.
            return length;
        }
    }

    /** Immutable holder for the four arm lengths of a potential plus shape. */
    private static final class PlusArms {
        private final int up;
        private final int down;
        private final int left;
        private final int right;

        PlusArms(int up, int down, int left, int right) {
            this.up = up;
            this.down = down;
            this.left = left;
            this.right = right;
        }

        /** Returns {@code true} if any arm has length zero (i.e., degenerate plus). */
        boolean isDegenerate() {
            return up == 0 || down == 0 || left == 0 || right == 0;
        }

        /** Returns the sum of the four arm lengths. */
        int totalLength() {
            return up + down + left + right;
        }
    }

    /**
     * Fast input reader based on a reusable byte buffer.
     *
     * <p>It supports reading integers and tokens separated by whitespace.
     * The class purposefully does **not** close the underlying stream; the
     * caller is responsible for proper resource handling.
     */
    static class InputReader {
        private final InputStream stream;
        private final byte[] buffer = new byte[1 << 10];
        private int bytesRead = 0;
        private int currentByteIdx = 0;

        InputReader(InputStream stream) {
            this.stream = stream;
        }

        /** Reads the next byte, performing a refill when necessary. */
        private int readByte() throws java.io.IOException {
            if (currentByteIdx >= bytesRead) {
                bytesRead = stream.read(buffer);
                currentByteIdx = 0;
                if (bytesRead <= 0) {
                    return -1;
                }
            }
            return buffer[currentByteIdx++];
        }

        /** Reads the next character, skipping whitespace. */
        private int nextNonWhitespace() throws java.io.IOException {
            int c;
            do {
                c = readByte();
                if (c == -1) {
                    return -1;
                }
            } while (isWhitespace(c));
            return c;
        }

        private static boolean isWhitespace(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t';
        }

        /** Reads the next integer. */
        int nextInt() throws java.io.IOException {
            int c = nextNonWhitespace();
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = readByte();
            }
            int result = 0;
            while (!isWhitespace(c) && c != -1) {
                if (c < '0' || c > '9') {
                    throw new java.util.InputMismatchException();
                }
                result = result * 10 + (c - '0');
                c = readByte();
            }
            return result * sign;
        }

        /** Reads the next token as a {@code String}. */
        String next() throws java.io.IOException {
            int c = nextNonWhitespace();
            StringBuilder sb = new StringBuilder();
            do {
                sb.append((char) c);
                c = readByte();
            } while (!isWhitespace(c) && c != -1);
            return sb.toString();
        }

        /** Reads an array of {@code String} tokens of the requested size. */
        String[] nextStringArray(int size) throws java.io.IOException {
            String[] tokens = new String[size];
            for (int i = 0; i < size; i++) {
                tokens[i] = next();
            }
            return tokens;
        }
    }
}

import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;

/**
 * Refactored solution that checks whether all '*' characters form a single
 * plus‑shaped cross centred on a unique interior cell.
 */
public class Solution {

    private static final String YES = "YES";
    private static final String NO = "NO";

    public static void main(String[] args) {
        try (Scanner sc = new Scanner(System.in)) {
            int rows = sc.nextInt();
            int cols = sc.nextInt();

            char[][] grid = readGrid(sc, rows, cols);
            int totalStars = countStars(grid);

            int[] centre = findUniqueCrossCenter(grid);
            if (centre == null) {
                System.out.println(NO);
                return;
            }

            int starsInCross = countStarsInCross(grid, centre[0], centre[1]);
            if (starsInCross != totalStars) {
                System.out.println(NO);
                return;
            }

            System.out.println(YES);
        }
    }

    /** Reads the grid from the scanner. */
    private static char[][] readGrid(Scanner sc, int rows, int cols) {
        char[][] grid = new char[rows][cols];
        for (int i = 0; i < rows; i++) {
            String line = sc.next();
            for (int j = 0; j < cols; j++) {
                grid[i][j] = line.charAt(j);
            }
        }
        return grid;
    }

    /** Counts the total number of '*' characters in the grid. */
    private static int countStars(char[][] grid) {
        int count = 0;
        for (char[] row : grid) {
            for (char cell : row) {
                if (cell == '*') {
                    count++;
                }
            }
        }
        return count;
    }

    /** Returns the coordinates of the unique interior cell whose four neighbours are '*', or null if none / more than one. */
    private static int[] findUniqueCrossCenter(char[][] grid) {
        List<int[]> centres = new ArrayList<>();
        int rows = grid.length;
        int cols = grid[0].length;

        for (int i = 1; i < rows - 1; i++) {
            for (int j = 1; j < cols - 1; j++) {
                if (isCrossCenter(grid, i, j)) {
                    centres.add(new int[]{i, j});
                }
            }
        }
        return centres.size() == 1 ? centres.get(0) : null;
    }

    /** Checks whether the four orthogonal neighbours of (i,j) are all '*'. */
    private static boolean isCrossCenter(char[][] grid, int i, int j) {
        int[][] directions = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};
        for (int[] d : directions) {
            int ni = i + d[0];
            int nj = j + d[1];
            if (grid[ni][nj] != '*') {
                return false;
            }
        }
        return true;
    }

    /** Counts how many '*' characters belong to the plus‑shaped cross centred at (ci,cj). */
    private static int countStarsInCross(char[][] grid, int ci, int cj) {
        int count = 0;
        int rows = grid.length;
        int cols = grid[0].length;

        // up (including the centre)
        for (int i = ci; i >= 0 && grid[i][cj] == '*'; i--) {
            count++;
        }
        // down
        for (int i = ci + 1; i < rows && grid[i][cj] == '*'; i++) {
            count++;
        }
        // left
        for (int j = cj - 1; j >= 0 && grid[ci][j] == '*'; j--) {
            count++;
        }
        // right
        for (int j = cj + 1; j < cols && grid[ci][j] == '*'; j++) {
            count++;
        }
        return count;
    }
}

import java.io.*;
import java.util.*;

public class CrossChecker {

    /** Small container for a row/column pair. */
    private static final class Position {
        final int row, col;
        Position(int row, int col) { this.row = row; this.col = col; }
    }

    /** Fast input reader used by the program. */
    private static FastReader reader;

    public static void main(String[] args) throws IOException {
        reader = new FastReader();

        int rows = reader.ni();          // n
        int cols = reader.ni();          // m
        char[][] grid = readGrid(rows, cols);

        Position centre = findCrossCenter(grid);
        if (centre == null) {
            System.out.println("NO");
            return;
        }

        removeCross(grid, centre.row, centre.col);

        if (hasMoreThanOneRemainingStar(grid)) {
            System.out.println("NO");
        } else {
            System.out.println("YES");
        }
    }

    /** Reads the grid of characters from the input. */
    private static char[][] readGrid(int n, int m) {
        char[][] grid = new char[n][m];
        for (int i = 0; i < n; i++) {
            String line = reader.next();
            grid[i] = line.toCharArray();
        }
        return grid;
    }

    /** Finds the unique '*' that has stars on all four orthogonal neighbours. */
    private static Position findCrossCenter(char[][] grid) {
        int rows = grid.length;
        int cols = grid[0].length;

        for (int i = 1; i < rows - 1; i++) {
            for (int j = 1; j < cols - 1; j++) {
                if (grid[i][j] == '*' &&
                    grid[i - 1][j] == '*' &&   // up
                    grid[i + 1][j] == '*' &&   // down
                    grid[i][j - 1] == '*' &&   // left
                    grid[i][j + 1] == '*') {   // right
                    return new Position(i, j);
                }
            }
        }
        return null;    // no centre found
    }

    /** Erases the whole vertical and horizontal line of '*' stemming from the centre. */
    private static void removeCross(char[][] grid, int centreRow, int centreCol) {
        int rows = grid.length;
        int cols = grid[0].length;

        // up
        for (int r = centreRow + 1; r < rows && grid[r][centreCol] == '*'; r++) {
            grid[r][centreCol] = '.';
        }
        // down
        for (int r = centreRow - 1; r >= 0 && grid[r][centreCol] == '*'; r--) {
            grid[r][centreCol] = '.';
        }
        // left
        for (int c = centreCol - 1; c >= 0 && grid[centreRow][c] == '*'; c--) {
            grid[centreRow][c] = '.';
        }
        // right
        for (int c = centreCol + 1; c < cols && grid[centreRow][c] == '*'; c++) {
            grid[centreRow][c] = '.';
        }
    }

    /** Returns true if more than one '*' remains after the cross has been removed. */
    private static boolean hasMoreThanOneRemainingStar(char[][] grid) {
        int starCount = 0;
        for (char[] row : grid) {
            for (char cell : row) {
                if (cell == '*') {
                    starCount++;
                    if (starCount > 1) {
                        return true;               // early exit – more than one stray star
                    }
                }
            }
        }
        return false;                               // 0 or 1 stray star
    }

    /* ---------- Fast I/O utilities ---------- */
    private static class FastReader {
        private final BufferedReader br;
        private StringTokenizer st;

        FastReader() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        FastReader(String fileName) throws IOException {
            br = new BufferedReader(new FileReader(fileName));
        }

        /** Returns the next token from input. */
        String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    throw new UncheckedIOException(e);
                }
            }
            return st.nextToken();
        }

        int ni() { return Integer.parseInt(next()); }
        long nl() { return Long.parseLong(next()); }
        double nextDouble() { return Double.parseDouble(next()); }
        String nextLine() { return readLine(); }

        private String readLine() {
            try {
                return br.readLine();
            } catch (IOException e) {
                throw new UncheckedIOException(e);
            }
        }
    }
}

package solution;

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

/**
 * Refactored solution that checks whether a grid contains a plus‑shaped
 * arrangement of '*' characters such that after removing the whole plus
 * (its arms) no other '*' remains.  If such a configuration exists the
 * program prints "YES", otherwise it prints "NO".
 */
public class Main {

    public static void main(String[] args) throws IOException {
        try (FastReader reader = new FastReader()) {
            int h = reader.nextInt();      // number of rows
            int w = reader.nextInt();      // number of columns

            // A plus needs at least 3 rows and 3 columns
            if (h < 3 || w < 3) {
                System.out.println("NO");
                return;
            }

            int[][] grid = readGrid(reader, h);

            Pos plus = findPlusCenter(grid);
            if (plus == null) {
                System.out.println("NO");
                return;
            }

            clearArms(grid, plus.row, plus.col);
            boolean hasRemainingStar = hasAnyStar(grid);

            System.out.println(hasRemainingStar ? "NO" : "YES");
        }
    }

    /** Reads the grid from the input, converting '*' to 1 and everything else to 0. */
    private static int[][] readGrid(FastReader reader, int h) throws IOException {
        int[][] grid = new int[h][];
        for (int i = 0; i < h; i++) {
            String line = reader.nextLine().trim();
            char[] chars = line.toCharArray();
            int[] row = new int[chars.length];
            for (int j = 0; j < chars.length; j++) {
                row[j] = (chars[j] == '*') ? 1 : 0;
            }
            grid[i] = row;
        }
        return grid;
    }

    /** Returns the position of the first plus centre found, or {@code null} if none exists. */
    private static Pos findPlusCenter(int[][] grid) {
        int h = grid.length;
        int w = grid[0].length;

        for (int i = 1; i < h - 1; i++) {
            for (int j = 1; j < w - 1; j++) {
                if (isPlusCenter(grid, i, j)) {
                    return new Pos(i, j);
                }
            }
        }
        return null;
    }

    /** Checks whether (i, j) is the centre of a plus made of '*' characters. */
    private static boolean isPlusCenter(int[][] grid, int i, int j) {
        return grid[i][j] == 1 &&
               grid[i - 1][j] == 1 &&
               grid[i + 1][j] == 1 &&
               grid[i][j - 1] == 1 &&
               grid[i][j + 1] == 1;
    }

    /** Clears all contiguous '*' cells in the four directions starting from the arms of the plus. */
    private static void clearArms(int[][] grid, int centerRow, int centerCol) {
        // up
        for (int r = centerRow - 1; r >= 0 && grid[r][centerCol] == 1; r--) {
            grid[r][centerCol] = 0;
        }
        // down
        for (int r = centerRow + 1; r < grid.length && grid[r][centerCol] == 1; r++) {
            grid[r][centerCol] = 0;
        }
        // left
        for (int c = centerCol - 1; c >= 0 && grid[centerRow][c] == 1; c--) {
            grid[centerRow][c] = 0;
        }
        // right
        for (int c = centerCol + 1; c < grid[0].length && grid[centerRow][c] == 1; c++) {
            grid[centerRow][c] = 0;
        }
    }

    /** Returns true if any '*' (value 1) remains in the grid. */
    private static boolean hasAnyStar(int[][] grid) {
        for (int[] row : grid) {
            for (int cell : row) {
                if (cell == 1) {
                    return true;
                }
            }
        }
        return false;
    }

    /** Simple container class for the coordinates of the plus centre. */
    private static final class Pos {
        final int row;
        final int col;

        Pos(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }

    /** Fast input reader used for competitive‑programming‑style problems. */
    private static final class FastReader {
        private final BufferedReader br;
        private StringTokenizer st;

        FastReader() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    throw new UncheckedIOException(e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        String nextLine() {
            try {
                return br.readLine();
            } catch (IOException e) {
                throw new UncheckedIOException(e);
            }
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Reads a grid of characters and checks whether all '*' cells form a single
 * “cross” shape (a central cell with four orthogonal neighbours that are '*' and
 * with no diagonal '*'). Exactly one such centre must exist and every '*'
 * must belong to the cross.
 */
public class Main {

    /* --------------------------------------------------------------
     *  Input handling
     * -------------------------------------------------------------- */
    private static class InputReader {
        private final BufferedReader br;
        private StringTokenizer st;

        InputReader(InputStream stream) {
            br = new BufferedReader(new InputStreamReader(stream), 32768);
        }

        /** Returns the next token or blocks until one is available. */
        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    throw new UncheckedIOException(e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        long nextLong() {
            return Long.parseLong(next());
        }
    }

    /* --------------------------------------------------------------
     *  Utility methods
     * -------------------------------------------------------------- */
    /** Checks whether (i, j) is inside the given grid. */
    private static boolean inBounds(int i, int j, int rows, int cols) {
        return i >= 0 && i < rows && j >= 0 && j < cols;
    }

    /**
     * Determines whether the cell (r, c) is a valid cross centre.
     * Conditions:
     * <ul>
     *   <li>grid[r][c] == '*'.</li>
     *   <li>All four orthogonal neighbours are '*'.</li>
     *   <li>All four diagonal cells are NOT '*'.</li>
     * </ul>
     */
    private static boolean isCrossCenter(char[][] grid, int r, int c) {
        // centre must be '*'
        if (grid[r][c] != '*') {
            return false;
        }

        // orthogonal neighbours must be '*'
        int[][] orthogonal = {{r - 1, c}, {r + 1, c}, {r, c - 1}, {r, c + 1}};
        for (int[] coord : orthogonal) {
            int ni = coord[0];
            int nj = coord[1];
            if (!inBounds(ni, nj, grid.length, grid[0].length) ||
                grid[ni][nj] != '*') {
                return false;
            }
        }

        // diagonal cells must NOT be '*'
        int[][] diagonal = {{r - 1, c - 1}, {r - 1, c + 1},
                            {r + 1, c - 1}, {r + 1, c + 1}};
        for (int[] coord : diagonal) {
            int ni = coord[0];
            int nj = coord[1];
            if (inBounds(ni, nj, grid.length, grid[0].length) &&
                grid[ni][nj] == '*') {
                return false;
            }
        }
        return true;
    }

    /**
     * Starting from a known centre (cx, cy) that belongs to a cross,
     * collect every '*' that lies on the same row or column until a
     * non‑'*' cell is encountered.
     */
    private static void collectCrossPositions(char[][] grid,
                                              int cx, int cy,
                                              Set<Point> points) {
        int rows = grid.length;
        int cols = grid[0].length;

        // up
        for (int i = cx; i >= 0; i--) {
            if (grid[i][cy] == '*') {
                points.add(new Point(i, cy));
            } else {
                break;
            }
        }
        // down
        for (int i = cx; i < rows; i++) {
            if (grid[i][cy] == '*') {
                points.add(new Point(i, cy));
            } else {
                break;
            }
        }
        // left
        for (int j = cy; j >= 0; j--) {
            if (grid[cx][j] == '*') {
                points.add(new Point(cx, j));
            } else {
                break;
            }
        }
        // right
        for (int j = cy; j < cols; j++) {
            if (grid[cx][j] == '*') {
                points.add(new Point(cx, j));
            } else {
                break;
            }
        }
    }

    /** Simple immutable point class used as a key in a Set. */
    private static class Point {
        final int row;
        final int col;

        Point(int row, int col) {
            this.row = row;
            this.col = col;
        }

        @Override
        public boolean equals(Object o) {
            if (this == o) return true;
            if (!(o instanceof Point)) return false;
            Point p = (Point) o;
            return row == p.row && col == p.col;
        }

        @Override
        public int hashCode() {
            return Objects.hash(row, col);
        }
    }

    /* --------------------------------------------------------------
     *  Main logic
     * -------------------------------------------------------------- */
    public static void main(String[] args) {
        InputReader reader = new InputReader(System.in);
        int h = reader.nextInt();
        int w = reader.nextInt();

        // read the grid
        char[][] grid = new char[h][];
        for (int i = 0; i < h; i++) {
            grid[i] = reader.next().toCharArray();
        }

        // Find all potential cross centres
        List<Point> centres = new ArrayList<>();
        for (int i = 0; i < h; i++) {
            for (int j = 0; j < w; j++) {
                if (isCrossCenter(grid, i, j)) {
                    centres.add(new Point(i, j));
                }
            }
        }

        // There must be exactly one centre.
        if (centres.size() != 1) {
            System.out.println("NO");
            return;
        }

        Point centre = centres.get(0);
        Set<Point> crossPoints = new HashSet<>();

        // Gather every '*' that belongs to the cross.
        collectCrossPositions(grid, centre.row, centre.col, crossPoints);

        // Verify that every '*' in the whole grid is part of this set.
        for (int i = 0; i < h; i++) {
            for (int j = 0; j < w; j++) {
                if (grid[i][j] == '*' && !crossPoints.contains(new Point(i, j))) {
                    System.out.println("NO");
                    return;
                }
            }
        }

        System.out.println("YES");
    }
}

import java.util.Scanner;

/**
 * Refactored version of the original program.
 *
 * <p>
 * The program reads a rectangular grid that is supplied column‑wise.
 * It checks whether all {@code '*'} characters form a single plus shape
 * (a central star with arms extending in the four orthogonal directions)
 * that consumes every star in the grid. If such a plus exists the program
 * prints {@code "YES"}, otherwise it prints {@code "NO"}.
 * </p>
 *
 * <p>Key improvements compared with the original code:</p>
 * <ul>
 *   <li>Descriptive method and variable names.</li>
 *   <li>Early‑exit checks and guard clauses.</li>
 *   <li>Extraction of logical pieces into small, reusable methods.</li>
 *   <li>Use of constants and Java‑8‑style try‑with‑resources for {@code Scanner}.</li>
 *   <li>Clear separation of concerns (input, counting, validation).</li>
 * </ul>
 */
public class First {

    /** Minimum allowed dimension – the original program required at least 3×3. */
    private static final int MIN_DIMENSION = 3;

    /** Character that marks a filled cell. */
    private static final char STAR = '*';

    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            int width  = scanner.nextInt();   // number of columns
            int height = scanner.nextInt();   // number of rows

            // Dimensions smaller than the required minimum can never hold a valid plus.
            if (width < MIN_DIMENSION || height < MIN_DIMENSION) {
                System.out.println("NO");
                return;
            }

            String[] columns = readColumns(scanner, width, height);
            int totalStars = countStars(columns, width, height);

            // No stars at all – the pattern is trivially invalid.
            if (totalStars == 0) {
                System.out.println("NO");
                return;
            }

            boolean plusCoversAll = findPlusCoveringAll(columns, width, height, totalStars);
            System.out.println(plusCoversAll ? "YES" : "NO");
        }
    }

    /** Reads exactly {@code width} column strings from the scanner. */
    private static String[] readColumns(Scanner scanner, int width, int height) {
        String[] columns = new String[width];
        for (int col = 0; col < width; col++) {
            columns[col] = scanner.next();   // each column is supplied as a token
        }
        return columns;
    }

    /** Counts the total number of {@code '*'} characters in the grid. */
    private static int countStars(String[] columns, int width, int height) {
        int count = 0;
        for (int col = 0; col < width; col++) {
            String column = columns[col];
            for (int row = 0; row < height; row++) {
                if (column.charAt(row) == STAR) {
                    count++;
                }
            }
        }
        return count;
    }

    /** Determines whether a plus made of stars consumes every star in the grid. */
    private static boolean findPlusCoveringAll(String[] columns, int width, int height, int totalStars) {
        for (int col = 1; col < width - 1; col++) {
            for (int row = 1; row < height - 1; row++) {
                if (isCenterOfPotentialPlus(columns, width, height, col, row)) {
                    int coveredStars = countCoveredStars(columns, width, height, col, row);
                    if (coveredStars == totalStars) {
                        return true;    // a valid plus that uses all stars was found
                    }
                }
            }
        }
        return false;   // no such plus exists
    }

    /** Checks whether the cell at (col,row) can be the centre of a plus. */
    private static boolean isCenterOfPotentialPlus(String[] columns, int width, int height,
                                                  int col, int row) {
        return columns[col].charAt(row) == STAR &&
               columns[col].charAt(row - 1) == STAR &&   // left
               columns[col].charAt(row + 1) == STAR &&   // right
               columns[col - 1].charAt(row) == STAR &&   // up
               columns[col + 1].charAt(row) == STAR;     // down
    }

    /** Counts stars that belong to the plus when it is centred at (startCol,startRow). */
    private static int countCoveredStars(String[] columns, int width, int height,
                                          int startCol, int startRow) {
        int covered = 1;   // the centre itself

        // up, down, left, right – each direction may contain more than one star
        covered += countConsecutive(columns, width, height, startCol, startRow, -1, 0); // up
        covered += countConsecutive(columns, width, height, startCol, startRow, 1, 0);  // down
        covered += countConsecutive(columns, width, height, startCol, startRow, 0, -1); // left
        covered += countConsecutive(columns, width, height, startCol, startRow, 0, 1);  // right

        return covered;
    }

    /** Counts consecutive stars starting from (col,row) and moving by (dCol,dRow). */
    private static int countConsecutive(String[] columns, int width, int height,
                                        int col, int row, int dCol, int dRow) {
        int length = 0;
        int curCol = col + dCol;
        int curRow = row + dRow;

        while (isInBounds(curCol, curRow, width, height)
               && columns[curCol].charAt(curRow) == STAR) {
            length++;
            curCol += dCol;
            curRow += dRow;
        }
        return length;
    }

    /** Utility to test whether (col,row) lies inside the grid. */
    private static boolean isInBounds(int col, int row, int width, int height) {
        return col >= 0 && col < width && row >= 0 && row < height;
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

/**
 * B+ from a picture.
 *
 * The program reads a grid that consists of '*' and '.' characters.
 * It decides whether there exists a *single* cross formed by stars such that
 * the cross contains **all** stars in the grid.
 *
 * A valid cross is defined by a centre cell (i, j) where the four orthogonal
 * neighbours are also stars, and the whole cross consists of the centre
 * together with the four arms (up, down, left, right).  The length of each
 * arm is the number of consecutive stars starting from the centre and moving
 * outward in that direction.
 *
 * If the total number of stars in the grid equals the number of stars that
 * belong to any such cross, the answer is "YES", otherwise "NO".
 *
 * The implementation is deliberately split into small, well‑named methods
 * to improve readability and maintainability.
 */
public class B_Plus_from_Picture {

    /** Directions used for traversing the four arms of a cross. */
    private static final int[] DR = { -1, 1, 0, 0 };
    private static final int[] DC = { 0, 0, -1, 1 };

    public static void main(String[] args) {
        FastScanner fs = new FastScanner();
        solve(fs);
    }

    /**
     * Core logic – reads the input, analyses the grid and prints the answer.
     */
    private static void solve(FastScanner fs) {
        int n = fs.nextInt();   // number of rows
        int m = fs.nextInt();   // number of columns

        boolean[][] grid = readGrid(fs, n, m);

        int totalStars = countStars(grid);

        // Trivial impossibility checks
        if (totalStars < 5 || n < 3 || m < 3) {
            System.out.println("NO");
            return;
        }

        // Try to locate a centre of a cross that contains *all* stars.
        for (int i = 1; i < n - 1; ++i) {
            for (int j = 1; j < m - 1; ++j) {
                if (isCrossCentre(grid, i, j)) {
                    int crossStarCount = countCrossStars(grid, i, j);
                    if (crossStarCount == totalStars) {
                        System.out.println("YES");
                        return;                     // found a valid cross
                    }
                }
            }
        }

        // No centre satisfied the requirement.
        System.out.println("NO");
    }

    /**
     * Returns true if (i, j) can be the centre of a cross.
     * The centre must have a star and all four orthogonal neighbours must also be stars.
     */
    private static boolean isCrossCentre(boolean[][] grid, int i, int j) {
        return grid[i][j] &&
                grid[i - 1][j] &&   // up
                grid[i + 1][j] &&   // down
                grid[i][j - 1] &&   // left
                grid[i][j + 1];     // right
    }

    /**
     * Counts how many stars belong to the cross whose centre is (i, j).
     * The count includes the centre itself and all consecutive stars in the
     * four directions until a '.' or the border is encountered.
     */
    private static int countCrossStars(boolean[][] grid, int centreR, int centreC) {
        int starCount = 1; // centre

        for (int dir = 0; dir < 4; ++dir) {
            int r = centreR + DR[dir];
            int c = centreC + DC[dir];

            while (inBounds(grid, r, c) && grid[r][c]) {
                ++starCount;
                r += DR[dir];
                c += DC[dir];
            }
        }
        return starCount;
    }

    /** Checks whether a given cell is inside the grid. */
    private static boolean inBounds(boolean[][] grid, int r, int c) {
        return r >= 0 && r < grid.length && c >= 0 && c < grid[0].length;
    }

    /**
     * Reads the whole grid from the scanner.  Each row is expected to be a
     * string of length {@code m} consisting of '*' or '.' characters.
     */
    private static boolean[][] readGrid(FastScanner fs, int rows, int cols) {
        boolean[][] grid = new boolean[rows][cols];
        int idx = 0;

        for (int i = 0; i < rows; ++i) {
            String line = fs.next();
            for (int j = 0; j < cols; ++j) {
                grid[i][j] = line.charAt(j) == '*';
            }
            ++idx;
        }
        return grid;
    }

    /**
     * Counts the total number of '*' characters in the grid.
     */
    private static int countStars(boolean[][] grid) {
        int cnt = 0;
        for (boolean[] row : grid) {
            for (boolean cell : row) {
                if (cell) {
                    ++cnt;
                }
            }
        }
        return cnt;
    }

    /* --------------------------------------------------------------------- */
    /*  The following class is a tiny but efficient fast scanner for input. */
    /* --------------------------------------------------------------------- */
    private static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner() {
            this.br = new BufferedReader(new InputStreamReader(System.in));
            st = new StringTokenizer("");
        }

        /** Returns the next token, expanding the tokenizer if necessary. */
        private String next() {
            while (!st.hasMoreTokens()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    throw new UncheckedIOException(e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        int[] readArray(int n) {
            int[] a = new int[n];
            for (int i = 0; i < n; ++i) {
                a[i] = nextInt();
            }
            return a;
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;

/**
 * Refactored version of the original program.
 *
 * Improvements:
 * • Clear separation of concerns (input, validation, output).
 * • Meaningful identifiers and small, focused methods.
 * • Encapsulation of the “center” discovery logic.
 * • Defensive bounds checking and early‑exit on multiple centers.
 * • Use of {@code final} constants and a tiny immutable holder class.
 */
public class B {

    /** Symbol used for the required pattern. */
    private static final char ASTERISK = '*';
    /** Symbol that may be collapsed. */
    private static final char DOT = '.';

    /** 2‑D representation of the input grid. */
    private static char[][] grid;
    /** Number of rows and columns. */
    private static int rows, cols;
    /** Result of the centre‑cell search. */
    private static CenterInfo centerInfo = new CenterInfo();

    /** Entry point. */
    public static void main(String[] args) throws IOException {
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in))) {
            String[] sizeTokens = br.readLine().split("\\s+");
            rows = Integer.parseInt(sizeTokens[0]);
            cols = Integer.parseInt(sizeTokens[1]);

            readGrid(br);

            centerInfo = findCenter();
            if (!centerInfo.isFound()) {
                System.out.println("NO");
                return;
            }

            StringBuilder rowAroundCenter = new StringBuilder();
            StringBuilder colAroundCenter = new StringBuilder();

            collectRowAndColumn(rowAroundCenter, colAroundCenter);

            String collapsedRow = collapseDots(rowAroundCenter.toString());
            String collapsedCol = collapseDots(colAroundCenter.toString());

            boolean interiorClear = isInteriorClear();
            boolean patternsAreOnlyAsterisks = collapsedRow.matches("[*]+")
                    && collapsedCol.matches("[*]+");

            System.out.println((patternsAreOnlyAsterisks && interiorClear) ? "YES" : "NO");
        }
    }

    /** Reads the grid from the supplied {@link BufferedReader}. */
    private static void readGrid(BufferedReader br) throws IOException {
        grid = new char[rows][cols];
        for (int i = 0; i < rows; i++) {
            String line = br.readLine();
            for (int j = 0; j < cols; j++) {
                grid[i][j] = line.charAt(j);
            }
        }
    }

    /** Tries to locate the unique centre cell surrounded by four asterisks. */
    private static CenterInfo findCenter() {
        int foundCount = 0;
        int centreX = -1, centreY = -1;

        // Only inner cells can possibly satisfy the neighbour requirement.
        for (int i = 1; i < rows - 1 && foundCount <= 1; i++) {
            for (int j = 1; j < cols - 1; j++) {
                if (hasAsteriskNeighbours(i, j)) {
                    if (++foundCount > 1) {
                        // More than one centre -> abort early.
                        return new CenterInfo();
                    }
                    centreX = i;
                    centreY = j;
                }
            }
        }
        return new CenterInfo(centreX, centreY);
    }

    /** Checks whether a cell has an asterisk on each of its four orthogonal neighbours. */
    private static boolean hasAsteriskNeighbours(int i, int j) {
        return grid[i][j + 1] == ASTERISK &&
               grid[i][j - 1] == ASTERISK &&
               grid[i - 1][j] == ASTERISK &&
               grid[i + 1][j] == ASTERISK;
    }

    /** Collapses consecutive '.' characters into a single space and trims surrounding whitespace. */
    private static String collapseDots(String input) {
        return input.replaceAll("\\.+", " ").trim();
    }

    /** Verifies that no asterisk appears outside the centre's row or column. */
    private static boolean isInteriorClear() {
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (i == centerInfo.x || j == centerInfo.y) {
                    continue; // cells on the centre's cross are allowed
                }
                if (grid[i][j] == ASTERISK) {
                    return false;
                }
            }
        }
        return true;
    }

    /** Simple immutable holder for the discovered centre coordinates. */
    private static final class CenterInfo {
        /** Row index of the centre, -1 if not found. */
        final int x;
        /** Column index of the centre, -1 if not found. */
        final int y;
        /** Whether a centre has been located. */
        private final boolean found;

        /** Default constructor used when no centre is found. */
        CenterInfo() {
            this.x = -1;
            this.y = -1;
            this.found = false;
        }

        /** Convenience constructor when a centre is identified. */
        CenterInfo(int x, int y) {
            this.x = x;
            this.y = y;
            this.found = true;
        }

        /** Returns {@code true} if a centre cell was discovered. */
        boolean isFound() {
            return found;
        }
    }
}

import java.io.BufferedOutputStream;
import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.StringTokenizer;

public class Round566Div2B {

    public static void main(String[] args) {
        out = new PrintWriter(new BufferedOutputStream(System.out));
        FastReader s = new FastReader();
        int h = s.nextInt();
        int w = s.nextInt();
        String[] grid = new String[h];
        for (int i = 0; i < h; i++) {
            grid[i] = s.next();
        }

        int totalStars = 0;
        for (int i = 0; i < h; i++) {
            for (int j = 0; j < w; j++) {
                if (grid[i].charAt(j) == '*') {
                    totalStars++;
                }
            }
        }

        int centerRow = -1, centerCol = -1;
        int centerCount = 0;
        for (int i = 1; i < h - 1; i++) {
            for (int j = 1; j < w - 1; j++) {
                if (grid[i].charAt(j) == '*' &&
                    grid[i-1].charAt(j) == '*' &&
                    grid[i+1].charAt(j) == '*' &&
                    grid[i].charAt(j-1) == '*' &&
                    grid[i].charAt(j+1) == '*') {
                    centerRow = i;
                    centerCol = j;
                    centerCount++;
                }
            }
        }

        if (centerCount != 1) {
            out.println("NO");
            out.close();
            return;
        }

        int up = 0;
        for (int i = 1; i < centerRow; i++) {
            if (grid[centerRow - i][centerCol] == '*') {
                up++;
            } else {
                break;
            }
        }
        int down = 0;
        for (int i = 1; i < h - centerRow; i++) {
            if (grid[centerRow + i][centerCol] == '*') {
                down++;
            } else {
                break;
            }
        }
        int left = 0;
        for (int j = 1; j < centerCol; j++) {
            if (grid[centerRow][centerCol - j] == '*') {
                left++;
            } else {
                break;
            }
        }
        int right = 0;
        for (int j = 1; j < w - centerCol; j++) {
            if (grid[centerRow][centerCol + j] == '*') {
                right++;
            } else {
                break;
            }
        }

        int totalCrossStars = 1 + up + down + left + right;
        if (totalCrossStars == totalStars) {
            out.println("YES");
        } else {
            out.println("NO");
        }
        out.close();
    }

    public static PrintWriter out;

    public static class FastReader {
        BufferedReader br;
        StringTokenizer st;

        public FastReader() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (Exception e) {
                    e.printStackTrace();
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        double nextDouble() {
            return Double.parseDouble(next());
        }

        long nextLong() {
            return Long.parseLong(next());
        }

        String nextLine() {
            String str = "";
            try {
                str = br.readLine();
            } catch (Exception e) {
                e.printStackTrace();
            }
            return str;
        }
    }
}

import java.util.Scanner;

/**
 * Solves the “Cross” problem from the original contest.
 *
 * The algorithm:
 *   1. Reads the height and width of a rectangular grid.
 *   2. Reads the grid itself (each cell is either '*' or '.').
 *   3. Looks for a cell that is the centre of a cross made of five '*' characters
 *      (the centre and its four orthogonal neighbours).
 *   4. From that centre we “remove” the whole cross by replacing every visited '*'
 *      with '.' – we walk up, down, left and right until we hit the border or a
 *      non‑'*' character.
 *   5. If after removal the grid contains no '*' characters we output {@code YES},
 *      otherwise {@code NO}.
 *
 * The program has been refactored for readability, maintainability and correctness.
 */
public final class ProbB {

    /** Directions used when propagating from the centre of a cross. */
    private static final int UP = -1;
    private static final int DOWN = 1;
    private static final int LEFT = -1;
    private static final int RIGHT = 1;

    private ProbB() {
        // Utility class – prevent instantiation.
    }

    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            int height = scanner.nextInt();
            int width = scanner.nextInt();
            scanner.nextLine(); // discard line separator

            char[][] grid = readGrid(height, scanner);
            boolean found = searchAndRemoveCross(grid, height, width);

            System.out.println(found ? "YES" : "NO");
        }
    }

    /**
     * Reads {@code height} lines from {@code scanner} and stores them into a
     * {@code char[][]} where each cell contains a single character ('*' or '.').
     */
    private static char[][] readGrid(int height, Scanner scanner) {
        char[][] grid = new char[height][];
        for (int row = 0; row < height; row++) {
            String line = scanner.nextLine();
            grid[row] = new char[width];
            for (int col = 0; col < width; col++) {
                grid[row][col] = line.charAt(col);
            }
        }
        return grid;
    }

    /**
     * Searches for the first suitable centre of a cross, removes that entire
     * cross and returns {@code true} if after removal the grid contains no '*'
     * characters. Returns {@code false} otherwise.
     */
    private static boolean searchAndRemoveCross(char[][] grid, int height, int width) {
        for (int row = 1; row < height - 1; row++) {
            for (int col = 1; col < width - 1; col++) {
                if (isCrossCentre(grid, row, col)) {
                    clearCross(grid, row, col);
                    return gridHasNoStars(grid);
                }
            }
        }
        return false;
    }

    /**
     * Determines whether the cell at {@code (row, col)} is the centre of a
     * cross formed by five '*' characters (its four orthogonal neighbours must
     * also be '*').
     */
    private static boolean isCrossCentre(char[][] grid, int row, int col) {
        return grid[row][col] == '*'
                && grid[row - 1][col] == '*'
                && grid[row + 1][col] == '*'
                && grid[row][col - 1] == '*'
                && grid[row][col + 1] == '*';
    }

    /**
     * Clears (sets to '.') the whole cross whose centre is at {@code (row, col)}.
     * The clearing proceeds in all four orthogonal directions until the border
     * of the grid or a non‑'*' cell is encountered.
     */
    private static void clearCross(char[][] grid, int centreRow, int centreCol) {
        // Upwards
        for (int r = centreRow - 1; r >= 0; r--) {
            if (grid[r][centreCol] != '*') break;
            grid[r][centreCol] = '.';
        }
        // Downwards
        for (int r = centreRow + 1; r < grid.length; r++) {
            if (grid[r][centreCol] != '*') break;
            grid[r][centreCol] = '.';
        }
        // Left
        for (int c = centreCol - 1; c >= 0; c--) {
            if (grid[centreRow][c] != '*') break;
            grid[centreRow][c] = '.';
        }
        // Right
        for (int c = centreCol + 1; c < grid[0].length; c++) {
            if (grid[centreRow][c] != '*') break;
            grid[centreRow][c] = '.';
        }
        // Finally clear the centre itself
        grid[centreRow][centreCol] = '.';
    }

    /**
     * Checks whether the grid still contains any '*' characters.
     */
    private static boolean gridHasNoStars(char[][] grid) {
        for (char[] row : grid) {
            for (char cell : row) {
                if (cell == '*') {
                    return false; // star found
                }
            }
        }
        return true; // no stars left
    }
}

import java.io.*;
import java.util.StringTokenizer;

/**
 * Main entry point of the program.
 * Reads a grid, tries to remove one “cross” of 1‑cells and reports
 * whether the whole grid can be cleared.
 */
public class Main {

    public static void main(String[] args) {
        /*--- I/O setup ---------------------------------------------------*/
        InputStream input = System.in;
        OutputStream output = System.out;
        InputReader reader = new InputReader(input);
        PrintWriter writer = new PrintWriter(output);

        /*--- core logic --------------------------------------------------*/
        Solver solver = new Solver();
        solver.solve(reader, writer);

        /*--- clean up ----------------------------------------------------*/
        writer.close();
    }

    /*------------------------------------------------------------------*/
    /** Reads tokens from an {@link InputStream} using a {@link StringTokenizer}. */
    static class InputReader {
        private final BufferedReader bufferedReader;
        private StringTokenizer tokenizer;

        InputReader(InputStream stream) {
            this.bufferedReader = new BufferedReader(
                    new InputStreamReader(stream), 32768);
        }

        /** Returns the next complete token, fetching a new line when needed. */
        private String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(bufferedReader.readLine());
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        long nextLong() {
            return Long.parseLong(next());
        }
    }

    /*------------------------------------------------------------------*/
    /** Encapsulates the algorithm that processes the grid. */
    static class Solver {

        /** Entry point required by the original program signature. */
        void solve(InputReader reader, PrintWriter out) {
            int rows = reader.nextInt();
            int cols = reader.nextInt();

            Grid grid = readGrid(reader, rows, cols);
            boolean crossRemoved = removeFirstCross(grid);

            out.print(isAllZero(grid) ? "YES" : "NO");
        }

        /** Reads the r×c matrix from the input stream. */
        private Grid readGrid(InputReader reader, int rows, int cols) {
            int[][] data = new int[rows][cols];

            for (int r = 0; r < rows; r++) {
                String line = reader.next();               // each line has exactly cols characters
                for (int c = 0; c < cols; c++) {
                    char ch = line.charAt(c);
                    data[r][c] = (ch == '.') ? 0 : 1;       // '.' → empty (0), anything else → occupied (1)
                }
            }
            return new Grid(data);
        }

        /** Tries to find a cross of 1‑cells, removes it and its extensions, and returns true if successful. */
        private boolean removeFirstCross(Grid grid) {
            final int ROWS = grid.data.length;
            final int COLS = grid.data[0].length;

            for (int r = 1; r < ROWS - 1; r++) {
                for (int c = 1; c < COLS - 1; c++) {
                    if (isCrossCenter(grid, r, c)) {
                        clearCross(grid, r, c);
                        return true;      // only the first cross is processed, matching original behaviour
                    }
                }
            }
            return false;
        }

        /** Checks whether the cell (row, col) is the centre of a valid cross of 1‑cells. */
        private boolean isCrossCenter(Grid grid, int row, int col) {
            int[][] d = grid.data;
            return d[row][col] == 1
                    && d[row - 1][col] == 1   // up
                    && d[row + 1][col] == 1   // down
                    && d[row][col - 1] == 1   // left
                    && d[row][col + 1] == 1;  // right
        }

        /** Clears the centre cross and any contiguous 1‑cells extending in the four directions. */
        private void clearCross(Grid grid, int centreRow, int centreCol) {
            int[][] d = grid.data;

            // centre + orthogonal neighbours
            clearCell(d, centreRow, centreCol);
            clearCell(d, centreRow - 1, centreCol);
            clearCell(d, centreRow + 1, centreCol);
            clearCell(d, centreRow, centreCol - 1);
            clearCell(d, centreRow, centreCol + 1);

            // extend upwards
            for (int r = centreRow - 1; r >= 0; r--) {
                clearCell(d, r, centreCol);
                if (d[r][centreCol] == 0) break;
            }
            // extend downwards
            for (int r = centreRow + 1; r < d.length; r++) {
                clearCell(d, r, centreCol);
                if (d[r][centreCol] == 0) break;
            }
            // extend leftwards
            for (int c = centreCol - 1; c >= 0; c--) {
                clearCell(d, centreRow, c);
                if (d[centreRow][c] == 0) break;
            }
            // extend rightwards
            for (int c = centreCol + 1; c < d[0].length; c++) {
                clearCell(d, centreRow, c);
                if (d[centreRow][c] == 0) break;
            }
        }

        /** Clears a single cell if it currently holds a 1; otherwise leaves it untouched. */
        private void clearCell(int[][] matrix, int row, int col) {
            if (matrix[row][col] == 1) {
                matrix[row][col] = 0;
            }
        }

        /** Determines whether every cell in the grid is zero. */
        private boolean isAllZero(int[][] matrix) {
            for (int[] row : matrix) {
                for (int value : row) {
                    if (value != 0) {
                        return false;
                    }
                }
            }
            return true;
        }
    }
}

import java.util.Scanner;

/**
 * Refactored solution for the “Cross‑shaped ‘*’ pattern” problem.
 * The program reads a grid, finds a single centre cell that forms a cross
 * of '*' characters, and prints “YES” if the grid contains exactly one such
 * cross, otherwise it prints “NO”.
 */
public class Solution {

    public static void main(String[] args) {
        // Using try‑with‑resources guarantees the Scanner is closed.
        try (Scanner scanner = new Scanner(System.in)) {
            // ---------- 1. Input ----------
            int height = scanner.nextInt();   // number of rows
            int width  = scanner.nextInt();   // number of columns
            char[][] grid = readGrid(scanner, height, width);

            // ---------- 2. Locate centre ----------
            int[] centre = new int[2]; // centre[0] = row, centre[1] = column
            if (!findCenter(grid, height, width, scanner, centre)) {
                System.out.println("NO");
                return;
            }

            // ---------- 3. Validate the cross ----------
            if (!isValidCross(grid, height, width, centre[0], centre[1])) {
                System.out.println("NO");
                return;
            }

            // ---------- 4. Output ----------
            System.out.println("YES");
        }
    }

    /**
     * Reads the grid rows from the scanner.
     */
    private static char[][] readGrid(Scanner scanner, int h, int w) {
        char[][] grid = new char[h][w];
        for (int i = 0; i < h; i++) {
            String line = scanner.next();
            grid[i] = line.toCharArray();
        }
        return grid;
    }

    /**
     * Determines a candidate centre cell for the cross.
     * Returns false if a centre cannot be identified or the candidate cell
     * is not a '*' or lies on the border.
     */
    private static boolean findCenter(char[][] grid, int h, int w,
                                      Scanner scanner, int[] centre) {
        int firstX = -1, firstY = -1;
        int secondX = -1, secondY = -1;

        // Locate at least two '*' positions to compute a centre.
        for (int i = 0; i < h; i++) {
            for (int j = 0; j < w; j++) {
                if (grid[i][j] == '*') {
                    if (firstX == -1) {
                        firstX = i;
                        firstY = j;
                    } else if (secondX == -1) {
                        // Use a star that does not share both coordinates with the first.
                        if (i != firstX || j != firstY) {
                            secondX = i;
                            secondY = j;
                        }
                    }
                }
            }
        }

        // If a second star was not found the pattern is invalid.
        if (secondY == -1) {
            return false;
        }

        // The centre must be either (firstX, secondY) or (secondX, firstY).
        int candX = firstX;
        int candY = secondY;
        if (grid[candX][candY] != '*') {
            candX = secondX;
            candY = firstY;
        }

        // The centre cannot be on the outermost row/column.
        if (candX == 0 || candX == h - 1 || candY == 0 || candY == w - 1) {
            return false;
        }

        centre[0] = candX;
        centre[1] = candY;
        return grid[candX][candY] == '*';
    }

    /**
     * Checks that all '*' cells belong to the cross defined by the centre
     * and that each arm of the cross is contiguous without gaps.
     */
    private static boolean isValidCross(char[][] grid, int h, int w,
                                        int centreX, int centreY) {
        // 1️⃣ Every '*' must lie either on the centre row or the centre column.
        for (int i = 0; i < h; i++) {
            for (int j = 0; j < w; j++) {
                if (grid[i][j] == '*') {
                    if (i != centreX && j != centreY) {
                        return false; // star outside the cross
                    }
                }
            }
        }

        // 2️⃣ Verify each of the four arms is contiguous.
        int[] dRow = {-1, 1, 0, 0};
        int[] dCol = {0, 0, -1, 1};

        for (int dir = 0; dir < 4; dir++) {
            int x = centreX + dRow[dir];
            int y = centreY + dCol[dir];

            // The arm must contain at least one '*' adjacent to the centre.
            if (x < 0 || x >= h || y < 0 || y >= w || grid[x][y] != '*') {
                return false;
            }

            // Walk outward until the arm ends (border or '.'). 
            // After the first '.' no '*' may appear further out.
            while (true) {
                int nx = x + dRow[dir];
                int ny = y + dCol[dir];
                if (nx < 0 || nx >= h || ny < 0 || ny >= w) {
                    break; // reached the border – arm ends correctly.
                }
                if (grid[nx][ny] == '.') {
                    // Ensure there is no stray '*' beyond this '.' in the same direction.
                    if (hasStarBeyondBorder(grid, nx, ny, dRow[dir], dCol[dir])) {
                        return false;
                    }
                    break;
                }
                x = nx;
                y = ny;
            }
        }

        // Final sanity check – the centre cell must indeed be a '*'.
        return grid[centreX][centreY] == '*';
    }

    /**
     * Scans from (startX, startY) outward in (dx,dy) direction.
     * Returns true if a '*' is encountered after a '.' has been seen,
     * indicating an invalid gap in the arm.
     */
    private static boolean hasStarBeyondBorder(char[][] grid, int x, int y,
                                                int dx, int dy) {
        while (x >= 0 && x < grid.length && y >= 0 && y < grid[0].length) {
            if (grid[x][y] == '*') {
                return true;
            }
            x += dx;
            y += dy;
        }
        return false;
    }
}

import java.util.Scanner;

/**
 * Reads a grid of characters and determines whether all '*' cells form a single
 * plus‑shaped cross (a central '*' with four adjacent '*' cells) and no stray
 * '*' symbols remain outside the arms of that cross.
 */
public class Main {

    /** Directions to explore from a potential centre: up, down, left, right. */
    private static final int[][] DIRECTIONS = {
            {-1, 0},   // up
            {1, 0},    // down
            {0, -1},   // left
            {0, 1}     // right
    };

    public static void main(String[] args) {
        try (Scanner sc = new Scanner(System.in)) {
            int rows = sc.nextInt();
            int cols = sc.nextInt();

            // ----- read the grid -------------------------------------------------
            String[] lines = new String[rows];
            for (int i = 0; i < rows; i++) {
                lines[i] = sc.next();
            }

            char[][] grid = buildGrid(lines, rows, cols);
            boolean[][] visited = new boolean[rows][cols];

            // ----- locate the centre of the plus ---------------------------------
            int centreRow = -1, centreCol = -1;
            if (!findPlusCentre(grid, rows, cols, visited, centreRow, centreCol)) {
                System.out.println("NO");
                return;
            }

            // ----- mark all '*' that belong to the arms of the plus ---------------
            markPlusArms(grid, visited, centreRow, centreCol);

            // ----- ensure there are no unmarked '*' cells -----------------------
            if (hasUnmarkedStar(grid, visited)) {
                System.out.println("NO");
            } else {
                System.out.println("YES");
            }
        }
    }

    /**
     * Parses the input strings into a rectangular {@code char[][]} grid.
     * Cells that are outside the declared width are ignored.
     */
    private static char[][] buildGrid(String[] lines, int rows, int cols) {
        char[][] grid = new char[rows][cols];
        for (int i = 0; i < rows; i++) {
            String line = lines[i];
            for (int j = 0; j < cols; j++) {
                grid[i][j] = line.charAt(j);
            }
        }
        return grid;
    }

    /**
     * Searches for the unique cell that can serve as the centre of a plus.
     * The centre must contain a '*' and each of its four orthogonal neighbours
     * must also contain a '*'. If found, the corresponding entry in {@code
     * visited} is marked and the method returns {@code true}.
     */
    private static boolean findPlusCentre(char[][] grid, int rows, int cols,
                                          boolean[][] visited, int startRow, int startCol) {
        for (int i = 1; i < rows - 1; i++) {
            for (int j = 1; j < cols - 1; j++) {
                if (grid[i][j] == '*' &&
                        grid[i - 1][j] == '*' &&   // up
                        grid[i + 1][j] == '*' &&   // down
                        grid[i][j - 1] == '*' &&   // left
                        grid[i][j + 1] == '*') {   // right
                    visited[i][j] = true;
                    startRow = i;
                    startCol = j;
                    return true;
                }
            }
        }
        return false; // no suitable centre found
    }

    /**
     * From the identified centre, walks outward in the four cardinal directions
     * marking every encountered '*' until a '.' or the border is reached.
     */
    private static void markPlusArms(char[][] grid, boolean[][] visited,
                                     int centreRow, int centreCol) {
        for (int[] dir : DIRECTIONS) {
            int row = centreRow + dir[0];
            int col = centreCol + dir[1];
            while (inside(grid, row, col) && grid[row][col] == '*') {
                visited[row][col] = true;
                row += dir[0];
                col += dir[1];
            }
        }
        // Ensure the centre itself is marked (it may have been skipped above)
        visited[centreRow][centreCol] = true;
    }

    /** Returns {@code true} if the coordinates lie inside the grid. */
    private static boolean inside(char[][] grid, int r, int c) {
        return r >= 0 && r < grid.length && c >= 0 && c < grid[0].length;
    }

    /** Scans the whole grid for any '*' that was not marked during arm tracing. */
    private static boolean hasUnmarkedStar(char[][] grid, boolean[][] visited) {
        for (int i = 0; i < grid.length; i++) {
            for (int j = 0; j < grid[i].length; j++) {
                if (grid[i][j] == '*' && !visited[i][j]) {
                    return true; // stray star found
                }
            }
        }
        return false; // all stars belong to the plus
    }
}

import java.util.Scanner;

/**
 * Detects whether a given grid consists exclusively of a single “plus” made
 * of asterisks ('*').  The input format is:
 * <pre>
 * h w
 * row1
 * row2
 * …
 * rowh
 * </pre>
 * where each character is either '*' (part of the plus) or '.' (empty).
 *
 * The program prints {@code YES} if the pattern is valid, otherwise {@code NO}.
 */
public class Contest {

    /** Entry point */
    public static void main(String[] args) {
        try (Scanner sc = new Scanner(System.in)) {
            // ---- read dimensions -------------------------------------------------
            String header = sc.nextLine().trim();
            String[] dims = header.split("\\s+");
            int height = Integer.parseInt(dims[0]);
            int width  = Integer.parseInt(dims[1]);

            // ---- read and parse the grid -----------------------------------------
            int[][] grid = new int[height][width];
            for (int r = 0; r < height; r++) {
                String line = sc.nextLine().trim();
                for (int c = 0; c < width; c++) {
                    grid[r][c] = (line.charAt(c) == '*') ? 1 : 0;
                }
            }

            // ---- evaluate the pattern --------------------------------------------
            boolean isPlus = solve(grid, height, width);
            System.out.println(isPlus ? "YES" : "NO");
        }
    }

    /**
     * Determines whether the supplied grid forms exactly one valid plus.
     *
     * @param grid  binary matrix (1 = '*', 0 = '.')
     * @param h     number of rows
     * @param w     number of columns
     * @return {@code true} if the grid is a single plus, {@code false} otherwise
     */
    private static boolean solve(int[][] grid, int h, int w) {
        // 1. Find a candidate centre row that contains at least two 1's.
        int centreRow = findCentreRow(grid, h, w);
        if (centreRow == -1) {
            return false;                     // no suitable centre → not a plus
        }

        // 2. Validate each arm of the plus and remember visited cells.
        boolean armValid = validateArms(grid, centreRow, h, w);

        // 3. After removing the plus, the grid must be empty.
        return isGridEmpty(grid);
    }

    /** Looks for the first row that can serve as the centre of a plus. */
    private static int findCentreRow(int[][] grid, int h, int w) {
        for (int row = 1; row < h - 1; row++) {   // centre cannot be first/last row
            int count = 0;
            for (int col = 0; col < w; col++) {
                if (grid[row][col] == 1) {
                    count++;
                }
            }
            if (count > 1) {
                return row;                       // first row with ≥2 stars
            }
        }
        return -1;
    }

    /**
     * Checks the vertical arms of the plus that originates from {@code centreRow}.
     * The method also clears the visited cells (sets them to 0) while validating.
     *
     * @return {@code true} if all arms are well‑formed, {@code false} otherwise
     */
    private static boolean validateArms(int[][] grid, int centreRow, int h, int w) {
        int centreCol = -1;
        boolean armInitialized = false;

        for (int col = 0; col < w; col++) {
            if (grid[centreRow][col] == 0) {
                continue;
            }

            // First star of a new arm
            if (!armInitialized) {
                armInitialized = true;
                centreCol = col;
                continue;
            }

            // A second arm must start right after the centre column
            if (col != centreCol + 1) {
                return false;               // arms must be adjacent horizontally
            }

            // Walk upwards first
            if (!processArmUpwards(grid, centreRow, centreCol, h, w)) {
                return false;
            }

            // Then walk downwards
            if (!processArmDownwards(grid, centreRow, centreCol, w)) {
                return false;
            }
        }

        // No arm at all?
        return armInitialized;
    }

    /** Walks upward from the centre cell until a zero is encountered. */
    private static void processArmUpwards(int[][] grid, int centreRow, int centreCol, int h, int w) {
        int r = centreRow - 1;                // start one cell above the centre
        boolean visited = false;
        while (r >= 0 && grid[r][centreCol] == 1) {
            grid[r][centreCol] = 0;           // clear the visited star
            visited = true;                   // we have moved at least one step up
            r--;
        }
        if (!visited) {
            throw new IllegalStateException("Arm length must be ≥ 1 upward");
        }
    }

    /** Walks downward from the centre cell until a zero is encountered. */
    private static void processArmDownwards(int[][] grid, int centreRow, int centreCol, int w) {
        int r = centreRow + 1;                // start one cell below the centre
        while (r < grid.length && grid[r][centreCol] == 1) {
            grid[r][centreCol] = 0;
            r++;
        }
    }

    /** Returns {@code true} if no cell with value 1 remains in the grid. */
    private static boolean isGridEmpty(int[][] grid) {
        for (int[] row : grid) {
            for (int cell : row) {
                if (cell == 1) {
                    return false;
                }
            }
        }
        return true;
    }
}

import java.util.Optional;
import java.util.Scanner;
import java.util.Set;

/**
 * Validates whether a given grid contains exactly one plus‑shaped pattern
 * made of asterisks (the “cross”) and no other asterisks remain after its removal.
 */
public class Main {

    /** Constant strings for the expected output. */
    private static final String YES = "YES";
    private static final String NO = "NO";

    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            int rows = scanner.nextInt();
            int cols = scanner.nextInt();
            char[][] grid = readGrid(scanner, rows, cols);

            Optional<Point> centre = findCrossCentre(grid);
            if (centre.isEmpty()) {
                System.out.println(NO);
                return;
            }

            removeCross(grid, centre.get());
            System.out.println(hasOnlyEmptyCells(grid) ? YES : NO);
        }
    }

    /**
     * Reads the grid from {@code scanner} according to the supplied dimensions.
     *
     * @param scanner  scanner providing the input
     * @param rows     number of rows
     * @param cols     number of columns
     * @return         2‑D char array representing the grid
     */
    private static char[][] readGrid(Scanner scanner, int rows, int cols) {
        char[][] grid = new char[rows][];
        for (int r = 0; r < rows; r++) {
            String line = scanner.next();
            grid[r] = line.toCharArray();
        }
        return grid;
    }

    /**
     * Looks for a cell that could be the centre of a plus sign.
     * The cell must be surrounded by asterisks on the four orthogonal directions.
     *
     * @param grid the current grid
     * @return     an {@link Optional} containing the centre point if it exists, otherwise empty
     */
    private static Optional<Point> findCrossCentre(char[][] grid) {
        for (int r = 0; r < grid.length; r++) {
            for (int c = 0; c < grid[0].length; c++) {
                if (isPotentialCentre(r, c, grid)) {
                    return Optional.of(new Point(r, c));
                }
            }
        }
        return Optional.empty();
    }

    /**
     * Determines whether the cell at (row, col) can be the centre of a cross.
     *
     * @param row    row index
     * @param col    column index
     * @param grid   grid to inspect
     * @return       {@code true} if a cross centre can be placed here
     */
    private static boolean isPotentialCentre(int row, int col, char[][] grid) {
        // Make sure the neighbours are inside the grid bounds
        if (row - 1 < 0 || row + 1 >= grid.length ||
            col - 1 < 0 || col + 1 >= grid[0].length) {
            return false;
        }
        // Verify that all four orthogonal neighbours are asterisks
        return grid[row - 1][col] == '*' &&
               grid[row + 1][col] == '*' &&
               grid[row][col - 1] == '*' &&
               grid[row][col + 1] == '*';
    }

    /**
     * Removes the asterisks that form a cross centred at {@code centre}.
     * The method mutates {@code grid} in‑place.
     *
     * @param grid     the grid to modify
     * @param centre   coordinates of the cross centre
     */
    private static void removeCross(char[][] grid, Point centre) {
        int r = centre.row;
        int c = centre.col;

        // Horizontal part (left & right)
        for (int col = c; col < grid[0].length && grid[r][col] == '*'; col++) {
            grid[r][col] = '.';
        }
        for (int col = c - 1; col >= 0 && grid[r][col] == '*'; col--) {
            grid[r][col] = '.';
        }

        // Vertical part (up & down)
        for (int row = r; row < grid.length && grid[row][c] == '*'; row++) {
            grid[row][c] = '.';
        }
        for (int row = r - 1; row >= 0 && grid[row][c] == '*'; row--) {
            grid[row][c] = '.';
        }
    }

    /**
     * Checks whether the grid contains only empty cells ('.').
     *
     * @param grid the grid to examine
     * @return     {@code true} if no asterisks remain
     */
    private static boolean hasOnlyEmptyCells(char[][] grid) {
        for (char[] row : grid) {
            for (char cell : row) {
                if (cell == '*') {
                    return false;
                }
            }
        }
        return true;
    }

    /** Simple immutable representation of a point (row, column). */
    private static final class Point {
        private final int row;
        private final int col;

        Point(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }
}

import java.io.IOException;
import java.util.Optional;
import java.util.Scanner;

public class J2 {
    private static final class Point {
        final int row;
        final int col;
        Point(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }

    private static final class Bounds {
        final int top;
        final int bottom;
        final int left;
        final int right;

        Bounds(int top, int bottom, int left, int right) {
            this.top = top;
            this.bottom = bottom;
            this.left = left;
            this.right = right;
        }
    }

    public static void main(String[] args) throws IOException {
        try (Scanner scanner = new Scanner(System.in)) {
            int height = scanner.nextInt();
            int width = scanner.nextInt();
            scanner.nextLine(); // consume line separator
            String[] grid = new String[height];
            for (int i = 0; i < height; i++) {
                grid[i] = scanner.nextLine();
            }

            Optional<Point> centerOpt = findCrossCenter(grid);
            if (centerOpt.isEmpty()) {
                System.out.println("NO");
                return;
            }

            Point center = centerOpt.get();
            Bounds bounds = computeBounds(grid, center.row, center.col);

            if (!validatePattern(grid, center.row, center.col, bounds)) {
                System.out.println("NO");
                return;
            }

            System.out.println("YES");
        }
    }

    private static Optional<Point> findCrossCenter(String[] grid) {
        int rows = grid.length;
        int cols = grid[0].length();

        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i].charAt(j) == '*') {
                    char up    = (i > 0)    ? grid[i - 1].charAt(j) : '1';
                    char down  = (i < rows - 1) ? grid[i + 1].charAt(j) : '1';
                    char left  = (j > 0)    ? grid[i].charAt(j - 1) : '1';
                    char right = (j < cols - 1) ? grid[i].charAt(j + 1) : '1';

                    if (up == '*' && down == '*' && left == '*' && right == '*') {
                        return Optional.of(new Point(i, j));
                    }
                }
            }
        }
        return Optional.empty();
    }

    private static Bounds computeBounds(String[] grid, int centerRow, int centerCol) {
        int rows = grid.length;
        int cols = grid[0].length();

        int top = -1;
        for (int i = centerRow; i >= 0; i--) {
            if (grid[i].charAt(centerCol) != '*') {
                top = i;
                break;
            }
        }
        int bottom = rows;
        for (int i = centerRow; i < rows; i++) {
            if (grid[i].charAt(centerCol) != '*') {
                bottom = i;
                break;
            }
        }
        int left = -1;
        for (int j = centerCol; j >= 0; j--) {
            if (grid[centerRow].charAt(j) != '*') {
                left = j;
                break;
            }
        }
        int right = cols;
        for (int j = centerCol; j < cols; j++) {
            if (grid[centerRow].charAt(j) != '*') {
                right = j;
                break;
            }
        }
        return new Bounds(top, bottom, left, right);
    }

    private static boolean validatePattern(String[] grid, int ci, int cj, Bounds bounds) {
        int rows = grid.length;
        int cols = grid[0].length();

        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i].charAt(j) == '*') {
                    if (i != ci && j != cj) {
                        return false;
                    }
                    if (i == ci) {
                        if (j <= bounds.left || j >= bounds.right) {
                            return false;
                        }
                    }
                    if (j == cj) {
                        if (i <= bounds.top || i >= bounds.bottom) {
                            return false;
                        }
                    }
                }
            }
        }
        return true;
    }
}

import java.io.*;
import java.util.Optional;

/**
 * Main class of the solution.
 * <p>
 * The program reads a grid that consists of '*' and '.' characters.
 * It checks whether there exists exactly one centre cell that forms a
 * cross of '*' cells (up, down, left and right) and whether every '*'
 * in the grid belongs to that cross.
 * </p>
 */
public class Codeforces {

    /** Small immutable holder for a coordinate. */
    private static final class Point {
        final int row;
        final int col;

        Point(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }

    /** Entry point. */
    public static void main(String[] args) {
        // All resources are closed automatically.
        try (var input = new BufferedInputStream(System.in);
             var output = new PrintWriter(System.out)) {

            int h = readInt(input);
            int w = readInt(input);
            char[][] grid = readGrid(h, input);

            Optional<Point> centre = locateCentre(grid);
            if (centre.isEmpty()) {
                output.println("NO");
                return;
            }

            boolean[][] visited = new boolean[h][w];
            markCross(visited, grid, centre.get().row, centre.get().col);

            output.println(allStarsMarked(visited, grid) ? "YES" : "NO");
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
    }

    /* --------------------------------------------------------------------- */
    /*  Input helpers                                                          */
    /* --------------------------------------------------------------------- */

    /** Reads the next integer token from the stream. */
    private static int readInt(BufferedInputStream src) throws IOException {
        int value = 0;
        int c = readNonWhite(src);
        boolean negative = false;
        if (c == '-') {
            negative = true;
            c = readNonWhite(src);
        }
        while (Character.isDigit(c)) {
            value = value * 10 + (c - '0');
            c = readNonWhite(src);
        }
        return negative ? -value : value;
    }

    /** Reads the next non‑whitespace character. */
    private static int readNonWhite(BufferedInputStream src) throws IOException {
        int c;
        do {
            c = src.read();
        } while (c <= ' ');
        return c;
    }

    /** Reads the next line (without trailing newline). */
    private static String readLine(BufferedInputStream src) throws IOException {
        StringBuilder sb = new StringBuilder();
        int c;
        while ((c = src.read()) != -1 && c != '\n') {
            sb.append((char) c);
        }
        return sb.toString();
    }

    /** Reads the whole grid (h rows). */
    private static char[][] readGrid(int h, BufferedInputStream src) throws IOException {
        char[][] grid = new char[h][];
        for (int i = 0; i < h; i++) {
            String line = readLine(src);
            grid[i] = line.toCharArray();
        }
        return grid;
    }

    /* --------------------------------------------------------------------- */
    /*  Core logic                                                             */
    /* --------------------------------------------------------------------- */

    /**
     * Finds the unique cell that can be the centre of a cross.
     * Returns {@link Optional#empty()} if none exists.
     */
    private static Optional<Point> locateCentre(char[][] grid) {
        int rows = grid.length;
        int cols = grid[0].length;

        for (int r = 1; r < rows - 1; r++) {
            for (int c = 1; c < cols - 1; c++) {
                if (isCross(grid, r, c)) {
                    return Optional.of(new Point(r, c));
                }
            }
        }
        return Optional.empty();
    }

    /** Checks whether the cell (r,c) together with its four neighbours forms a '*' cross. */
    private static boolean isCross(char[][] grid, int r, int c) {
        return grid[r][c] == '*' &&
               grid[r - 1][c] == '*' &&
               grid[r + 1][c] == '*' &&
               grid[r][c - 1] == '*' &&
               grid[r][c + 1] == '*';
    }

    /**
     * Marks all '*' cells that belong to the same cross as (cx,cy).
     * The method follows the four directions until a non‑'*' or grid border is hit.
     */
    private static void markCross(boolean[][] visited, char[][] grid, int cx, int cy) {
        // Upwards
        for (int r = cx; r < grid.length && grid[r][cy] == '*'; r++) {
            visited[r][cy] = true;
        }
        // Downwards
        for (int r = cx; r >= 0 && grid[r][cy] == '*'; r--) {
            visited[r][cy] = true;
        }
        // Rightwards
        for (int c = cy; c < grid[0].length && grid[cx][c] == '*'; c++) {
            visited[cx][c] = true;
        }
        // Leftwards
        for (int c = cy; c >= 0 && grid[cx][c] == '*'; c--) {
            visited[cx][c] = true;
        }
    }

    /** Verifies that every '*' in the grid has been visited (i.e. belongs to the cross). */
    private static boolean allStarsMarked(boolean[][] visited, char[][] grid) {
        for (int r = 0; r < visited.length; r++) {
            for (int c = 0; c < visited[r].length; c++) {
                if (grid[r][c] == '*' && !visited[r][c]) {
                    return false;
                }
            }
        }
        return true;
    }
}

import java.util.Scanner;

/**
 * <p>
 *   Main class that reads a rectangular picture made of '*' and '.' characters
 *   and decides whether it conforms to the required “hour‑glass” pattern.
 *   The result of the validation is printed as either {@code "YES"} or {@code "NO"}.
 * </p>
 */
public class Problemo {

    /** Entry point – delegates all work to {@link #solve()} and prints the result. */
    public static void main(String[] args) {
        System.out.println(solve());
    }

    /**
     * Reads the whole input, validates the picture and returns the textual result.
     *
     * @return {@code "YES"} if the picture matches the specification,
     *         {@code "NO"} otherwise.
     */
    private static String solve() {
        // try‑with‑resources guarantees the scanner is closed automatically
        try (Scanner scanner = new Scanner(System.in)) {
            int height = scanner.nextInt();
            int width  = scanner.nextInt();
            scanner.nextLine();                     // discard end‑of‑line marker

            // basic sanity checks
            if (height <= 0 || width <= 0) {
                return "NO";
            }

            String[] lines = readAllLines(scanner, height);
            ValidationResult validation = validate(lines, width);
            return validation.message();
        }
    }

    /**
     * Reads exactly {@code count} lines from the scanner.
     *
     * @param scanner  scanner positioned after the two integers,
     * @param count    number of lines that have to be read,
     * @return array containing the read lines.
     */
    private static String[] readAllLines(Scanner scanner, int count) {
        String[] lines = new String[count];
        for (int i = 0; i < count; i++) {
            lines[i] = scanner.nextLine();
        }
        return lines;
    }

    /**
     * Performs the hour‑glass validation.
     *
     * @param lines    array of input lines,
     * @param width    expected length of each line,
     * @return a {@link ValidationResult} that carries the final message.
     */
    private static ValidationResult validate(String[] lines, int width) {
        // state that is gathered while scanning the picture
        int firstStarCol   = -1;   // column of the first '*' encountered
        int secondStarRow  = -1;   // row of the second '*' (bottom of the hour‑glass)
        boolean middleLineBroken = true; // becomes false once a non‑'*' appears in the middle line

        // -----------------------------------------------------------------
        // Main scan – row‑major order (exactly the same order as the original)
        // -----------------------------------------------------------------
        for (int row = 0; row < lines.length; row++) {
            String line = lines[row];
            if (line.length() != width) {
                return ValidationResult.invalidFormat();
            }

            for (int col = 0; col < width; col++) {
                char ch = line.charAt(col);

                // ---------------------------------------------------------
                // 1️⃣  Find the first '*' – it must not be on the outer border
                // ---------------------------------------------------------
                if (firstStarCol == -1) {
                    if (ch == '*') {
                        if (col == 0 || col == width - 1) {
                            return ValidationResult.invalidEdgeStar();
                        }
                        firstStarCol = col;
                        // continue scanning the rest of this row
                        continue;
                    }
                }

                // ---------------------------------------------------------
                // 2️⃣  Middle horizontal line – must be an uninterrupted run of '*'
                // ---------------------------------------------------------
                if (middleLineBroken) {
                    if (ch != '*') {
                        // a break before we have seen the second star is only allowed
                        // after we have already processed the row that contains it
                        if (row <= secondStarRow + 1) {
                            return ValidationResult.invalidEarlyBreak();
                        }
                        middleLineBroken = false;
                    }
                    continue;
                }

                // ---------------------------------------------------------
                // 3️⃣  Second star – marks the start of the bottom part.
                //     After it the rest of the line must consist solely of '*'
                // ---------------------------------------------------------
                if (secondStarRow == -1 && ch == '*') {
                    secondStarRow = row;

                    // the second star cannot be on the last row or to the right
                    // of the first star's column
                    if (row == lines.length - 1 || col > firstStarCol) {
                        return ValidationResult.invalidSecondStarPosition();
                    }

                    // everything after the second star on this line must be '*'
                    for (int remaining = col + 1; remaining < width; remaining++) {
                        if (line.charAt(remaining) != '*') {
                            return ValidationResult.brokenBottom();
                        }
                    }

                    // if we are on the last row, validation is finished
                    if (row == lines.length - 1) {
                        return ValidationResult.success();
                    }
                    continue;
                }

                // ---------------------------------------------------------
                // 4️⃣  Any '*' that appears after the bottom part is illegal
                // ---------------------------------------------------------
                if (ch == '*' && secondStarRow != -1) {
                    return ValidationResult.invalidExtraStar();
                }
            }
        }

        // -----------------------------------------------------------------
        // Final sanity checks – both stars must have been found
        // -----------------------------------------------------------------
        if (firstStarCol == -1 || secondStarRow == -1) {
            return ValidationResult.missingStars();
        }
        // All checks passed
        return ValidationResult.success();
    }

    /**
     * Encapsulates the possible validation outcomes and their textual messages.
     * <p>
     *   Each constant corresponds to a distinct failure mode (or success) and
     *   holds the exact string that must be printed to standard output.
     * </p>
     */
    private static final class ValidationResult {
        private final String message;

        private ValidationResult(String message) {
            this.message = message;
        }

        // Success – the picture matches the required pattern
        static ValidationResult success() {
            return new ValidationResult("YES");
        }

        // Various failure modes – all map to "NO" in the original program
        static ValidationResult invalidEdgeStar()      { return failure("NO"); }
        static ValidationResult invalidFormat()        { return failure("NO"); }
        static ValidationResult invalidEarlyBreak()    { return failure("NO"); }
        static ValidationResult invalidSecondStarPosition() { return failure("NO"); }
        static ValidationResult brokenBottom()         { return failure("NO"); }
        static ValidationResult invalidExtraStar()     { return failure("NO"); }
        static ValidationResult missingStars()         { return failure("NO"); }

        /** Helper that creates a failure result with the given message. */
        private static ValidationResult failure(String msg) {
            return new ValidationResult(msg);
        }

        /** Returns the message that must be printed. */
        String message() {
            return message;
        }
    }
}

import java.io.*;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;

/**
 * B1182 – examines whether all asterisks (*) in an N×M grid
 * belong to a single cross‑shaped (+) component.
 *
 * <p>
 *   1. A cell with a '*' is considered a *center* if it is surrounded
 *      by a '*' on each of its four direct neighbours.
 *   2. From that centre we expand up, down, left and right while the
 *      cells also contain '*', marking every visited cell.
 *   3. After processing the first centre we validated that **every**
 *      '*' cell was marked. If any '*' remains unmarked the answer
 *      is "NO", otherwise it is "YES".
 * </p>
 *
 * <p>
 *   The program is deliberately split into small, single‑purpose methods
 *   and uses a {@code Position} record instead of a mutable custom class.
 *   This makes the code self‑documenting, easier to test and refactor.
 * </p>
 */
public final class B1182 {

    /* ------------------------------------------------------                     *
     *  Entry point                                                                 *
     * ------------------------------------------------------ */
    public static void main(String[] args) throws IOException {
        StringBuilder out = new StringBuilder();
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in))) {
            out.append(Solution.solve(br));
        }
        System.out.print(out);
    }

    /* ------------------------------------------------------                     *
     *  Core problem‑solving class                                                       *
     * ------------------------------------------------------ */
    private static class Solution {

        /** Reads the whole input, processes it and returns the result string. */
        static String solve(BufferedReader br) throws IOException {
            // ----- 1️⃣  Parse dimensions and grid ---------------------------------
            String[] dimensions = nextToken(br).split("\\s+");
            final int n = Integer.parseInt(dimensions[0]);
            final int m = Integer.parseInt(dimensions[1]);

            char[][] grid = new char[n][];
            String line;
            int starCount = 0;
            for (int i = 0; i < n; i++) {
                line = nextLine(br);
                grid[i] = line.toCharArray();
                for (char c : grid[i]) {
                    if (c == '*') {
                        starCount++;
                    }
                }
            }

            // If there is no asterisk there is nothing to form a cross.
            if (starCount == 0) {
                return "NO";
            }

            // ----- 2️⃣  Find the first eligible centre of a cross -----------------
            Position centre = locateCenter(grid);
            if (centre == null) {
                // No centre → cannot form the required pattern.
                return "NO";
            }

            // ----- 3️⃣  Mark all asterisks that belong to the cross ---------------
            Set<Position> visited = markCross(grid, centre);

            // ----- 4️⃣  Verify that every asterisk has been visited ---------------
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    if (grid[i][j] == '*' && !visited.contains(new Position(i, j))) {
                        return "NO";
                    }
                }
            }
            return "YES";
        }

        /** Returns the coordinates of the first cell that has a '*' on all four sides,
         *  or {@code null} if such a cell does not exist. */
        private static Position locateCenter(char[][] grid) {
            int n = grid.length;
            int m = grid[0].length;

            for (int i = 1; i < n - 1; i++) {
                for (int j = 1; j < m - 1; j++) {
                    if (isCrossCenter(grid, i, j)) {
                        // Immediately abort after finding the first centre – this
                        // matches the original algorithm's “break‑out” semantics.
                        return new Position(i, j);
                    }
                }
            }
            return null; // no centre found
        }

        /** Checks whether cell (row, col) is a ‘+’ centre. */
        private static boolean isCrossCenter(char[][] grid, int row, int col) {
            return grid[row][col] == '*' &&
                   grid[row - 1][col] == '*' &&   // up
                   grid[row + 1][col] == '*' &&   // down
                   grid[row][col - 1] == '*' &&   // left
                   grid[row][col + 1] == '*';     // right
        }

        /** Expands horizontally and vertically from the given centre while the
         *  cells contain '*', adding every visited position to {@code visited}. */
        private static Set<Position> markCross(char[][] grid, Position centre) {
            Set<Position> visited = new HashSet<>();

            // Mark the centre itself
            visited.add(centre);

            // Up
            expandInDirection(grid, centre.row, centre.col, Direction.UP, visited);
            // Down
            expandInDirection(grid, centre.row, centre.col, Direction.DOWN, visited);
            // Left
            expandInDirection(grid, centre.row, centre.col, Direction.LEFT, visited);
            // Right
            expandInDirection(grid, centre.row, centre.col, Direction.RIGHT, visited);

            return visited;
        }

        /** Walks from (startRow, startCol) towards {@code dir} while cells contain '*',
         *  adding each visited coordinate to {@code target}. */
        private static void expandInDirection(char[][] grid,
                                              int startRow, int startCol,
                                              Direction dir,
                                              Set<Position> target) {
            int step = dir == Direction.UP || dir == Direction.LEFT ? -1 : 1;
            int row = startRow;
            int col = startCol;

            // First step is the immediate neighbour of the centre.
            row += step;
            col += (dir == Direction.RIGHT || dir == Direction.LEFT) ? 0 : 0; // keep column fixed

            // Continue while we stay inside the grid and the cell contains '*'
            while (isInside(grid, row, col) && grid[row][col] == '*') {
                target.add(new Position(row, col));
                row += step;
                col += (dir == Direction.RIGHT || dir == Direction.LEFT) ? 1 : 0; // adjust only one axis
            }
        }

        /** Simple bounds check. */
        private static boolean isInside(char[][] grid, int row, int col) {
            return row >= 0 && row < grid.length && col >= 0 && col < grid[0].length;
        }
    }

    /* ------------------------------------------------------                     *
     *  Helper data structures                                 *
     * ------------------------------------------------------ */

    /** Immutable representation of a grid cell. */
    private static final class Position {
        final int row;
        final int col;

        Position(int row, int col) {
            this.row = row;
            this.col = col;
        }

        @Override
        public boolean equals(Object o) {
            if (this == o) return true;
            if (!(o instanceof Position)) return false;
            Position p = (Position) o;
            return row == p.row && col == p.col;
        }

        @Override
        public int hashCode() {
            // Use a prime‑based combine to reduce collisions.
            int result = 17;
            result = 31 * result + row;
            result = 31 * result + col;
            return result;
        }

        @Override
        public String toString() {
            return "(" + row + "," + col + ")";
        }
    }

    /** Directions used for expanding the cross. */
    private enum Direction {
        UP(-1, 0), DOWN(1, 0), LEFT(0, -1), RIGHT(0, 1);

        final int deltaRow;
        final int deltaCol;

        Direction(int dr, int dc) {
            this.deltaRow = dr;
            this.deltaCol = dc;
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Reads a matrix of characters from standard input and checks whether it
 * follows a specific “three‑row star” pattern.
 *
 * <p>Constraints of the original specification:
 * <ul>
 *   <li>There must be at least three rows and three columns.</li>
 *   <li>The pattern must contain a contiguous block of '*' characters in the
 *       first row, a full row of '*' characters in the middle row and a single
 *       '*' character in the last row (the exact arrangement is encoded in the
 *       {@link JuneValidator#validate(char[][], int, int)} method.</li>
 * </ul>
 *
 * <p>If the constraints are satisfied the program prints “YES”, otherwise
 * “NO”.
 */
public class June05 {

    /** Entry point. */
    public static void main(String[] args) throws IOException {
        // 1️⃣  Read dimensions and matrix from stdin.
        Input input = readInput();

        // 2️⃣  Validate the matrix against the required pattern.
        boolean matches = JuneValidator.validate(input.matrix, input.rows, input.cols);

        // 3️⃣  Print the result ("YES" or "NO").
        System.out.println(matches ? "YES" : "NO");
    }

    /** Simple DTO that holds the parsed input. */
    private static final class Input {
        final int rows;
        final int cols;
        final char[][] matrix;

        Input(int rows, int cols, char[][] matrix) {
            this.rows = rows;
            this.cols = cols;
            this.matrix = matrix;
        }
    }

    /** Reads the whole input and returns a populated {@link Input} object. */
    private static Input readInput() throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());

        // ①  Parse number of rows and columns.
        int rows = Integer.parseInt(st.nextToken());
        int cols = Integer.parseInt(st.nextToken());

        if (rows <= 0 || cols <= 0) {
            throw new IllegalArgumentException("Rows and columns must be positive.");
        }

        // ②  Reserve space for the matrix and fill it.
        char[][] matrix = new char[rows][];
        for (int i = 0; i < rows; i++) {
            String line = br.readLine();
            if (line == null || line.length() < cols) {
                throw new IllegalArgumentException(
                        String.format("Row %d does not contain %d characters.", i + 1, cols));
            }
            matrix[i] = line.toCharArray();
        }

        return new Input(rows, cols, matrix);
    }
}

/**
 * Encapsulates the validation logic.  The algorithm has been broken down into
 * small, self‑documenting steps, each guarded by early‑return statements.
 *
 * <p>All public fields are deliberately immutable – the validator works on a
 * read‑only snapshot of the matrix supplied by {@link June05#readInput()}.
 */
final class JuneValidator {

    /** Returns {@code true} if the supplied matrix matches the required pattern. */
    public static boolean validate(char[][] matrix, int rows, int cols) {
        // ③  The pattern is only possible when we have at least 3 rows and 3 cols.
        if (rows < 3 || cols < 3) {
            return false;
        }

        // ④  Walk through the matrix row‑by‑row looking for the pattern markers.
        State state = State.HEADER;       // looking for the first '*'
        int firstStarCol = -1;             // column of the first '*'
        int midRow = -1;                   // row index of the middle '*'
        int endStarCol = -1;               // column of the last '*' on the middle row

        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                char ch = matrix[r][c];
                switch (state) {
                    case HEADER -> handleHeader(ch, c, r, state, firstStarCol, endStarCol);
                    case LOOKING_FOR_END -> handleLookingForEnd(ch, c, r, state,
                            firstStarCol, midRow, endStarCol);
                    case VALID -> {
                        // Once we have verified the whole pattern we stay in VALID.
                        // Any deviation would have already caused an early exit.
                        continue;
                }
            }
        }

        // ⑤  If we exited the loops in VALID state the pattern matches.
        return state == State.VALID;
    }

    /** Helper for the initial “*” discovery phase. */
    private static State handleHeader(char ch,
                                       int col,
                                       int row,
                                       State state,
                                       int firstStarCol,
                                       int endStarCol) {
        if (ch == '*') {
            if (firstStarCol == -1) {
                firstStarCol = col;
                return State.HEADER;               // still waiting for the end of the block
            }
            // We have seen a '*' after the first one – that means we are inside the block.
            return State.HEADER;
        } else {
            // First non‑'*' encountered before the block ends → pattern broken.
            return State.INVALID;
        }
    }

    /** Helper for the phase where we expect a full row of '*' characters. */
    private static State handleLookingForEnd(char ch,
                                              int col,
                                              int row,
                                              State state,
                                              int firstStarCol,
                                              int midRow,
                                              int endStarCol) {
        // We are looking for a whole row consisting only of '*' characters.
        if (row == midRow) {
            // If we have not yet identified the middle row, we do it now.
            if (midRow == -1) {
                midRow = row;
            }
            if (ch == '*') {
                // Record the column of the last '*' we have seen on this row.
                endStarCol = Math.max(endStarCol, col);
                return State.LOOKING_FOR_END;
            } else {
                // Any '.' breaks the required “full row of '*'” requirement.
                return State.INVALID;
            }
        } else {
            // Transition to validation after the middle row has been processed.
            if (midRow != -1 && endStarCol != -1) {
                // At this point the pattern must end with a single '*' in the last row.
                // Further checks are performed by the caller after the loops finish.
                return State.VALID;
            }
            return State.INVALID;
        }
    }

    /** -------------------------------------------------------------
     *  INTERNAL STATE ENUM – describes where the validator currently is.
     *  ------------------------------------------------------------- */
    private enum State {
        /** Still scanning for the first occurrence of '*'. */
        HEADER,

        /** After the first row of '*', waiting to see a full row of '*'. */
        LOOKING_FOR_END,

        /** The whole pattern has been successfully matched. */
        VALID,

        /** Any deviation from the required shape – abort early. */
        INVALID
    }
}

import java.io.*;
import java.util.*;

/**
 * Refactored solution for the “Cross” problem.
 * The program reads a rectangular grid of characters (‘*’ or ‘.’),
 * determines whether there exists exactly one “plus” made of
 * connected stars and whether all stars belong to that plus.
 *
 * The implementation is deliberately split into small, single‑purpose
 * methods, uses meaningful names and avoids mutable static state.
 */
public class Solver {

    private final BufferedReader reader;
    private final PrintWriter writer;

    /** Simple helper that extracts ints from a line. */
    private static class IntTokenizer {
        private final StringTokenizer tokenizer;
        IntTokenizer(Tokenizer source) { this.tokenizer = new StringTokenizer(source); }

        int nextInt() { return Integer.parseInt(tokenizer.nextToken()); }
    }

    /**
     * Reads the input and prints either “YES” or “NO” according to the
     * specification.
     */
    public static void main(String[] args) throws IOException {
        try (Solver solver = new Solver(
                new BufferedReader(new InputStreamReader(System.in)),
                new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)))
        )) {
            solver.run();
        }
    }

    private Solver(BufferedReader reader, PrintWriter writer) {
        this.reader = reader;
        this.writer = writer;
    }

    /** Entry point of the refactored program. */
    private void run() throws IOException {
        reader.readLine();                     // ignore sentinel line (unused in real problem)
        int width = nextInt();
        int height = nextInt();
        char[][] grid = readGrid(width, height);

        PlusPosition plus = locatePlus(grid);
        if (plus == null) {
            writer.println("NO");
            return;
        }

        if (isOnlyStarsInsidePlus(grid, plus)) {
            writer.println("YES");
        } else {
            writer.println("NO");
        }
    }

    /** Reads a grid of size {@code rows × cols} from the input. */
    private char[][] readGrid(int rows, int cols) throws IOException {
        char[][] grid = new char[rows][cols];
        for (int r = 0; r < rows; r++) {
            String line = reader.readLine();
            if (line == null) {
                throw new IOException("Unexpected end of input while reading grid.");
            }
            // Remove any whitespace and take exactly `cols` characters.
            line = line.replaceAll("\\s", "");
            if (line.length() < cols) {
                throw new IOException("Insufficient characters in line " + (r + 1));
            }
            for (int c = 0; c < cols; c++) {
                grid[r][c] = line.charAt(c);
            }
        }
        return grid;
    }

    /**
     * Finds the centre of a plus, if it exists.
     *
     * @return {@code PlusPosition} containing centre coordinates, or {@code null}
     *         when no valid plus can be identified.
     */
    private PlusPosition locatePlus(char[][] grid) {
        int rows = grid.length;
        int cols = grid[0].length;

        for (int r = 1; r < rows - 1; r++) {
            for (int c = 1; c < cols - 1; c++) {
                if (!isStar(grid[r][c])) {
                    continue;
                }
                // check the four orthogonal neighbours
                if (neighbourIsStar(grid, r + 1, c) &&
                    neighbourIsStar(grid, r - 1, c) &&
                    neighbourIsStar(grid, r, c + 1) &&
                    neighbourIsStar(grid, r, c - 1)) {
                    return new PlusPosition(r, c);
                }
            }
        }
        return null; // no plus found
    }

    /** Returns the limits of the plus in the four cardinal directions. */
    private Directions computeDirections(char[][] grid, PlusPosition pos) {
        Directions dirs = new Directions();

        // up
        for (int i = pos.row; i >= 0; i--) {
            if (!isStar(grid[i][pos.col])) { break; }
            dirs.up = i;
        }
        // down
        for (int i = pos.row; i < grid.length; i++) {
            if (!isStar(grid[i][pos.col])) { break; }
            dirs.down = i;
        }
        // left
        for (int j = pos.col; j >= 0; j--) {
            if (!isStar(grid[pos.row][j])) { break; }
            dirs.left = j;
        }
        // right
        for (int j = pos.col; j < grid[0].length; j++) {
            if (!isStar(grid[pos.row][j])) { break; }
            dirs.right = j;
        }
        return dirs;
    }

    /** Checks that every ‘*’ in the grid lies inside the computed bounds. */
    private boolean isOnlyStarsInsidePlus(char[][] grid, PlusPosition plus) {
        Directions dirs = computeDirections(grid, plus);

        // verify every star belongs to the cross
        for (int r = 0; r < grid.length; r++) {
            for (int c = 0; c < grid[0].length; c++) {
                if (!isStar(grid[r][c])) {
                    continue;
                }
                boolean isOnCross =
                        r == plus.row || c == plus.col;                // same row or column as centre
                boolean withinVertical = r >= dirs.up && r <= dirs.down;
                boolean withinHorizontal = c >= dirs.left && c <= dirs.right;

                if (isOnCross && (withinVertical || withinHorizontal)) {
                    continue; // belongs to the plus
                }
                return false; // stray star found
            }
        }
        return true;
    }

    /** Convenience predicate for the ‘*’ character. */
    private boolean isStar(char ch) {
        return ch == '*';
    }

    /** Holds the centre coordinates of a discovered plus. */
    private static final class PlusPosition {
        final int row;
        final int col;

        PlusPosition(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }

    /** Holds the extent of the plus in each direction. */
    private static final class Directions {
        int up = -1;   // smallest row index of a star in the column
        int down = -1; // largest row index of a star in the column
        int left = -1; // smallest column index of a star in the row
        int right = -1;// largest column index of a star in the row
    }
}

import java.io.*;
import java.util.*;

/**
 * Entry point of the program. Reads the input, runs the solver and prints the result.
 */
public class Main {

    public static void main(String[] args) {
        InputReader reader = new InputReader(System.in);
        PrintWriter out = new PrintWriter(System.out);
        Solver solver = new Solver(reader, out);
        solver.solve();
        out.flush();
    }

    /** Fast scanner that works on a byte buffer. */
    static final class InputReader {
        private final InputStream stream;
        private final byte[] buffer = new byte[16_384];
        private int pointer = 0;
        private int length = 0;

        InputReader(InputStream stream) {
            this.stream = stream;
        }

        private int readByte() throws IOException {
            if (pointer >= length) {
                length = stream.read(buffer);
                pointer = 0;
                if (length <= 0) {
                    return -1;
                }
            }
            return buffer[pointer++];
        }

        /** Skips any whitespace characters and returns the next byte. */
        private int skipWhitespace(int c) throws IOException {
            while (true) {
                if (c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1) {
                    c = readByte();
                } else {
                    break;
                }
            }
            return c;
        }

        /** Reads the next integer from the input. */
        int nextInt() throws IOException {
            int c = skipWhitespace(readByte());
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = readByte();
            }
            int result = 0;
            while (c >= '0' && c <= '9') {
                result = result * 10 + (c - '0');
                c = readByte();
            }
            return result * sign;
        }

        /** Reads the next non‑whitespace character. */
        char nextChar() throws IOException {
            int c = skipWhitespace(readByte());
            return (char) c;
        }

        /**
         * Reads a 1‑indexed character grid of {@code n} rows and {@code m} columns.
         * The returned array has a thin border (0‑indexed) so that indices 1…n and 1…m
         * correspond to the real data, matching the behaviour of the original code.
         */
        char[][] readCharGrid(int n, int m) throws IOException {
            char[][] grid = new char[n + 2][m + 2]; // extra border for readability
            for (int i = 1; i <= n; i++) {
                for (int j = 1; j <= m; j++) {
                    grid[i][j] = nextChar();
                }
            }
            return grid;
        }
    }

    /** Contains all the solving logic. */
    static final class Solver {
        private final InputReader in;
        private final PrintWriter out;

        Solver(InputReader in, PrintWriter out) {
            this.in = in;
            this.out = out;
        }

        /** Entry point used by {@link Main}. */
        void solve() throws IOException {
            int n = in.nextInt();
            int m = in.nextInt();
            char[][] grid = in.readCharGrid(n, m);

            Position center = locatePlusCenter(grid);
            if (center == null) {
                out.println("NO");
                return;
            }

            boolean[][] marked = markArms(grid, center);
            if (hasExtraStars(grid, marked)) {
                out.println("NO");
                return;
            }

            out.println("YES");
        }

        /**
         * Searches for a cell that is the centre of a '+'
         * (the cell and its four orthogonal neighbours are '*').
         * The search is limited to interior cells to avoid index problems.
         *
         * @return the centre position if found, otherwise {@code null}
         */
        private Position locatePlusCenter(char[][] grid) {
            for (int i = 2; i < grid.length - 1; i++) {
                for (int j = 2; j < grid[i].length - 1; j++) {
                    if (isStar(grid[i][j])
                            && isStar(grid[i - 1][j])
                            && isStar(grid[i + 1][j])
                            && isStar(grid[i][j - 1])
                            && isStar(grid[i][j + 1])) {
                        return new Position(i, j);
                    }
                }
            }
            return null;
        }

        /** Marks the full vertical and horizontal arms of the detected '+'. */
        private boolean[][] markArms(char[][] grid, Position center) {
            boolean[][] marked = new boolean[grid.length][grid[0].length];
            int r = center.row, c = center.col;

            // Upward arm
            for (int i = r; i >= 1 && isStar(grid[i][c]); i--) {
                marked[i][c] = true;
            }
            // Downward arm
            for (int i = r; i < grid.length && isStar(grid[i][c]); i++) {
                marked[i][c] = true;
            }
            // Left arm
            for (int j = c; j >= 1 && isStar(grid[r][j]); j--) {
                marked[r][j] = true;
            }
            // Right arm
            for (int j = c; j < grid[r].length && isStar(grid[r][j]); j++) {
                marked[r][j] = true;
            }
            return marked;
        }

        /** Returns true if any '*' in the grid is not part of the marked arms. */
        private boolean hasExtraStars(char[][] grid, boolean[][] marked) {
            for (int i = 1; i < grid.length - 1; i++) {
                for (int j = 1; j < grid[i].length - 1; j++) {
                    if (isStar(grid[i][j]) && !marked[i][j]) {
                        return true;
                    }
                }
            }
            return false;
        }

        /** Helper that checks whether a cell contains '*'. */
        private boolean isStar(char ch) {
            return ch == '*';
        }

        /** Simple container for a cell coordinate. */
        private static final class Position {
            final int row;
            final int col;

            Position(int row, int col) {
                this.row = row;
                this.col = col;
            }
        }
    }
}

/**
 * Reads a matrix of characters and determines whether all '*' cells can be
 * removed by repeatedly picking a plus‑shaped group of exactly five '*'s
 * (a centre with four orthogonal neighbours) and erasing the whole plus.
 *
 * <p>If every '*' can be erased the program prints <code>YES</code>,
 * otherwise it prints <code>NO</code>.
 *
 * <p>The implementation is deliberately split into small, single‑responsibility
 * methods, uses meaningful names, avoids static mutable fields and isolates
 * I/O handling in its own scanner class.
 */
public class Main {

    /** Directions used by {@link #removePlus(char[][], int, int)}. */
    private static final int[][] PLUS_OFFSET = {
            {-1, 0}, // up
            {+1, 0}, // down
            {0, -1}, // left
            {0, +1}  // right
    };

    public static void main(String[] args) {
        GridProcessor processor = new GridProcessor();
        processor.process();
        processor.printResult();
    }
}

/**
 * Handles all input reading and the core logic of the algorithm.
 */
final class GridProcessor {

    /** Number of rows in the matrix. */
    private int rows;

    /** Number of columns in the matrix. */
    private int columns;

    /** 2‑D character matrix read from input. */
    private char[][] grid;

    /** Result of the computation. */
    private boolean allStarsErased = false;

    private GridProcessor() {
        // Input is deliberately read in a dedicated scanner class.
    }

    /** Entry point for the processing phase. */
    public void process() {
        FastScanner fs = new FastScanner();
        rows = fs.nextInt();
        columns = fs.nextInt();

        grid = readMatrix(fs, rows);

        // Find the first centre of a valid plus‑shaped '*' and remove it.
        locateAndErasePlus();

        // After the removal, verify that no '*' cells remain.
        allStarsErased = !containsStar();
    }

    /** Reads the requested number of rows from {@link FastScanner}. */
    private static char[][] readMatrix(FastScanner fs, int rows) {
        char[][] matrix = new char[rows][];
        for (int r = 0; r < rows; r++) {
            String line = fs.next();
            matrix[r] = line.toCharArray();
        }
        return matrix;
    }

    /** Finds a centre cell that forms a plus with exactly four '*' neighbours
     *  and erases the complete plus from the grid. */
    private void locateAndErasePlus() {
        for (int r = 1; r < rows - 1; r++) {
            for (int c = 1; c < columns - 1; c++) {
                if (isPlusCentre(r, c)) {
                    erasePlus(r, c);
                    return; // only one plus is processed, as per original logic
                }
            }
        }

        // If no plus could be found, the algorithm still proceeds –
        // {@code allStarsErased} will stay false, leading to a "NO" output.
    }

    /** Checks whether cell (row, col) is the centre of a plus made of '*'. */
    private boolean isPlusCentre(int row, int col) {
        return grid[row][col] == '*' &&
                grid[row - 1][col] == '*' && // up
                grid[row + 1][col] == '*' && // down
                grid[row][col - 1] == '*' && // left
                grid[row][col + 1] == '*';   // right
    }

    /** Erases the plus (centre + its four neighbours) from the matrix. */
    private void erasePlus(int startRow, int startCol) {
        // Erase centre first – it guarantees termination of all loops.
        grid[startRow][startCol] = '.';

        // Propagate erasure in each of the four orthogonal directions.
        for (int[] delta : PLUS_OFFSET) {
            int r = startRow + delta[0];
            int c = startCol + delta[1];
            while (isInside(r, c) && grid[r][c] == '*') {
                grid[r][c] = '.';
                r += delta[0];
                c += delta[1];
            }
        }
    }

    /** Returns {@code true} if any '*' character still exists in the grid. */
    private boolean containsStar() {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < columns; c++) {
                if (grid[r][c] == '*') {
                    return true;
                }
            }
        }
        return false;
    }

    /** Determines whether a cell lies inside the matrix bounds. */
    private boolean isInside(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < columns;
    }

    /** Prints the final answer according to the specification. */
    public void printResult() {
        System.out.println(allStarsErased ? "YES" : "NO");
    }
}

/**
 * A simple fast scanner that mimics {@code java.util.Scanner} but uses
 * {@link BufferedReader} and {@link StringTokenizer} for speed.
 *
 * <p>Only the methods required by {@link GridProcessor} are implemented.
 */
final class FastScanner {

    private final BufferedReader reader;
    private StringTokenizer tokenizer;

    public FastScanner() {
        this.reader = new BufferedReader(new InputStreamReader(System.in));
        this.tokenizer = null;
    }

    /** Reads the next token, tokenising lazily if required. */
    private String nextToken() {
        while (tokenizer == null || !tokenizer.hasMoreElements()) {
            try {
                String line = reader.readLine();
                if (line == null) {
                    return null;
                }
                tokenizer = new StringTokenizer(line);
            } catch (Exception e) {
                throw new RuntimeException(e);
            }
        }
        return tokenizer.nextToken();
    }

    /** Reads an {@code int} from the input stream. */
    public int nextInt() {
        return Integer.parseInt(nextToken());
    }

    /** Reads a {@code String} token. */
    public String next() {
        return nextToken();
    }
}

import java.io.*;
import java.util.*;

/**
 * Solution class that checks whether the given grid contains exactly one
 * plus‑shaped figure made of '*' characters that covers all '*' cells.
 */
public class Solution {

    /** Helper class that encapsulates input reading. */
    private static final class InputReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        InputReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream), 32768);
            tokenizer = null;
        }

        /** Returns the next token from the input. */
        private String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new UncheckedIOException(e);
                }
            }
            return tokenizer.nextToken();
        }

        /** Reads an integer from the input. */
        int nextInt() {
            return Integer.parseInt(next());
        }
    }

    /** Entry point of the program. */
    public static void main(String[] args) throws IOException {
        try (InputReader in = new InputReader(System.in);
             PrintWriter out = new PrintWriter(System.out)) {

            solve(in, out);
        }
    }

    /**
     * Core logic that reads the grid, validates the presence of exactly one
     * plus sign made of '*' characters and verifies that all '*' cells belong
     * to that plus.
     */
    private static void solve(InputReader in, PrintWriter out) {
        int height = in.nextInt();
        int width = in.nextInt();

        String[] board = new String[height];
        for (int row = 0; row < height; row++) {
            board[row] = in.next();
        }

        Optional<int[]> plusInfo = findPlusCenter(board);
        if (!plusInfo.isPresent()) {
            out.println("NO");
            return;
        }

        int centerRow = plusInfo.get()[0];
        int centerCol = plusInfo.get()[1];
        boolean[][] marked = markPlusArms(board, centerRow, centerCol);

        if (!allStarsAreMarked(board, marked)) {
            out.println("NO");
            return;
        }

        out.println("YES");
    }

    /**
     * Finds the unique cell that can be the centre of a plus sign.
     * A centre must have a '*' in each orthogonal neighbour (up, down, left,
     * right). Exactly one such centre must exist, otherwise the answer is
     * considered invalid.
     *
     * @return an {@code OptionalInt}` containing {row, col} of the centre,
     * or empty if none or more than one centre exists.
     */
    private static Optional<int[]> findPlusCenter(String[] board) {
        int centreRow = -1;
        int centreCol = -1;

        for (int r = 1; r < board.length - 1; r++) {
            for (int c = 1; c < board[0].length() - 1; c++) {
                if (isStar(board, r, c) &&
                    isStar(board, r - 1, c) &&
                    isStar(board, r + 1, c) &&
                    isStar(board, r, c - 1) &&
                    isStar(board, r, c + 1)) {

                    if (centreRow != -1) { // second centre found
                        return Optional.empty();
                    }
                    centreRow = r;
                    centreCol = c;
                }
            }
        }

        return (centreRow == -1) ? Optional.empty() : Optional.of(new int[]{centreRow, centreCol});
    }

    /** Checks whether a given cell contains '*'. */
    private static boolean isStar(String[] board, int row, int col) {
        return board[row].charAt(col) == '*';
    }

    /**
     * Marks the arm cells of the plus whose centre is (row, col).
     * The method returns a boolean matrix where {@code true} means the cell
     * belongs to the plus.
     */
    private static boolean[][] markPlusArms(String[] board, int row, int col) {
        boolean[][] marked = new boolean[board.length][board[0].length];
        markDirection(board, marked, row, col, Direction.UP);
        markDirection(board, marked, row, col, Direction.DOWN);
        markDirection(board, marked, row, col, Direction.LEFT);
        markDirection(board, marked, row, col, Direction.RIGHT);
        return marked;
    }

    /** Marks a single direction (up, down, left, right) from the centre. */
    private enum Direction { UP, DOWN, LEFT, RIGHT }

    private static void markDirection(String[] board, boolean[][] marked,
                                      int centreRow, int centreCol, Direction dir) {
        switch (dir) {
            case UP -> markVertical(board, marked, centreRow, centreCol, -1, 0);
            case DOWN -> markVertical(board, marked, centreRow, centreCol, 1, 0);
            case LEFT -> markHorizontal(board, marked, centreRow, centreCol, 0, -1);
            case RIGHT -> markHorizontal(board, marked, centreRow, centreCol, 0, 1);
        }
    }

    /** Marks cells vertically until a '.' or grid border is reached. */
    private static void markVertical(String[] board, boolean[][] marked,
                                      int row, int col, int dr, int dc) {
        int r = row + dr;
        while (inBounds(board.length, board[0].length, r, col) && isStar(board, r, col)) {
            marked[r][col] = true;
            r += dr;
        }
    }

    /** Marks cells horizontally until a '.' or grid border is reached. */
    private static void markHorizontal(String[] board, boolean[][] marked,
                                        int row, int col, int dr, int dc) {
        int c = col + dc;
        while (inBounds(board.length, board[0].length, row, c) && isStar(board, row, c)) {
            marked[row][c] = true;
            c += dc;
        }
    }

    /** Utility to check bounds of a cell. */
    private static boolean inBounds(int rows, int cols, int r, int c) {
        return r >= 0 && c >= 0 && r < rows && c < cols;
    }

    /** Checks that every '*' in the board is marked as part of the plus. */
    private static boolean allStarsAreMarked(String[] board, boolean[][] marked) {
        for (int r = 0; r < board.length; r++) {
            for (int c = 0; c < board[0].length; c++) {
                if (board[r].charAt(c) == '*' && !marked[r][c]) {
                    return false;
                }
            }
        }
        return true;
    }
}

import java.io.*;
import java.util.*;

public class Main {

    // -----------------------------------------------------------------------
    // Input handling
    // -----------------------------------------------------------------------
    private static final class InputReader {
        private final InputStream stream;
        private final byte[] buffer = new byte[8192];
        private int pointer = 0;
        private int length = 0;

        InputReader(InputStream stream) {
            this.stream = stream;
        }

        private int readByte() {
            if (pointer >= length) {
                length = stream.read(buffer);
                pointer = 0;
                if (length <= 0) {
                    return -1;
                }
            }
            return buffer[pointer++];
        }

        private boolean isSpaceChar(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        int readInt() {
            int c = skipSpaces();
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = readByte();
            }
            int result = 0;
            while (!isSpaceChar(c)) {
                if (c < '0' || c > '9') {
                    throw new InputMismatchException();
                }
                result = result * 10 + (c - '0');
                c = readByte();
            }
            return result * sign;
        }

        String readString() {
            int c = skipSpaces();
            StringBuilder sb = new StringBuilder();
            do {
                sb.appendCodePoint(c);
                c = readByte();
            } while (!isSpaceChar(c));
            return sb.toString();
        }

        private int skipSpaces() {
            int c;
            do {
                c = readByte();
            } while (c != -1 && isSpaceChar(c));
            return c;
        }
    }

    // -----------------------------------------------------------------------
    // Core algorithm
    // -----------------------------------------------------------------------
    public static void main(String[] args) {
        try (InputReader in = new InputReader(System.in)) {
            solve(in);
        } catch (IOException e) {
            System.err.println("Input reading error: " + e.getMessage());
        }
    }

    private static void solve(InputReader in) {
        int h = in.readInt();
        int w = in.readInt();
        String[] grid = new String[h];
        for (int row = 0; row < h; row++) {
            grid[row] = in.readString();
        }

        int firstStarCol = -1;   // th
        int firstStarRow = -1;   // rh
        int secondStarRow = -1;  // tw
        int secondStarCol = -1;  // rw

        boolean horizontalFound = false;
        boolean verticalFound = false;

        for (int row = 0; row < h; row++) {
            String line = grid[row];
            for (int col = 0; col < w; col++) {
                char ch = line.charAt(col);
                if (ch == '.') {
                    if (horizontalFound && firstStarRow == row) {
                        horizontalFound = false;
                    }
                    if (verticalFound && secondStarRow == row) {
                        verticalFound = false;
                    }
                } else {
                    if (!horizontalFound) {
                        firstStarCol = col;
                        firstStarRow = row;
                        horizontalFound = true;
                    } else if (horizontalFound && firstStarCol == col) {
                        continue;
                    } else if (!verticalFound) {
                        secondStarRow = row;
                        secondStarCol = col;
                        verticalFound = true;
                    } else if (verticalFound && secondStarRow == row) {
                        continue;
                    } else {
                        System.out.println("NO");
                        return;
                    }
                }
            }
        }

        if (firstStarRow == -1 || firstStarCol == -1 || secondStarRow == -1 || secondStarCol == -1) {
            System.out.println("NO");
            return;
        }

        if (!hasLengthAtLeastTwo(grid, firstStarRow, firstStarCol, true)) {
            System.out.println("NO");
            return;
        }

        if (!hasLengthAtLeastTwo(grid, secondStarRow, secondStarCol, false)) {
            System.out.println("NO");
            return;
        }

        System.out.println("YES");
    }

    /**
     * Checks whether there are at least two consecutive '*' characters
     * starting from (startRow, startCol) moving in the given direction.
     *
     * @param grid     the grid of characters
     * @param startRow row index of the starting '*' character
     * @param startCol column index of the starting '*' character
     * @param horizontal true if moving horizontally, false if vertically
     * @return true if the segment length is at least two
     */
    private static boolean hasLengthAtLeastTwo(String[] grid, int startRow, int startCol, boolean horizontal) {
        int count = 0;
        if (horizontal) {
            for (int col = startCol; col < grid[0].length(); col++) {
                if (grid[startRow].charAt(col) == '*') {
                    count++;
                } else {
                    break;
                }
            }
        } else {
            for (int row = startRow; row < grid.length; row++) {
                if (grid[row].charAt(startCol) == '*') {
                    count++;
                } else {
                    break;
                }
            }
        }
        return count >= 2;
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

/**
 * Refactored version of the original program.
 * It checks whether the input grid contains exactly one '+' shape that
 * consumes all '*' cells.
 */
public class TypeB {

    /** Simple fast scanner for reading input. */
    private static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        /** Guarantees that a tokenizer is ready for the next token. */
        private void ensureTokenizer() throws IOException {
            while (st == null || !st.hasMoreElements()) {
                String line = br.readLine();
                if (line == null) {
                    return; // EOF
                }
                st = new StringTokenizer(line);
            }
        }

        /** Returns the next token. */
        String next() {
            ensureTokenizer();
            return st.nextToken();
        }

        /** Reads an int token. */
        int nextInt() {
            return Integer.parseInt(next());
        }

        /** Reads a long token. */
        long nextLong() {
            return Long.parseLong(next());
        }

        /** Reads a double token. */
        double nextDouble() {
            return Double.parseDouble(next());
        }

        /** Reads the remainder of the current line (including possible spaces). */
        String nextLine() {
            ensureTokenizer();
            //noinspection StringBufferReplaceableByString
            return st.nextToken(null);
        }
    }

    /** Counts the number of '*' characters in the grid. */
    private static int countStars(char[][] grid) {
        int count = 0;
        for (char[] row : grid) {
            for (char cell : row) {
                if (cell == '*') {
                    count++;
                }
            }
        }
        return count;
    }

    /**
     * Returns the lengths of consecutive '*' cells in the four cardinal directions
     * starting from (row, col). The order is: up, down, left, right.
     */
    private static int[] crossLengths(char[][] grid, int row, int col) {
        int up = 0;
        int r = row - 1;
        while (r >= 0 && grid[r][col] == '*') {
            up++;
            r--;
        }

        int down = 0;
        r = row + 1;
        while (r < grid.length && grid[r][col] == '*') {
            down++;
            r++;
        }

        int left = 0;
        int c = col - 1;
        while (c >= 0 && grid[row][c] == '*') {
            left++;
            c--;
        }

        int right = 0;
        c = col + 1;
        while (c < grid[0].length && grid[row][c] == '*') {
            right++;
            c++;
        }

        return new int[]{up, down, left, right};
    }

    public static void main(String[] args) throws IOException {
        FastScanner fs = new FastScanner();

        int h = fs.nextInt();   // number of rows
        int w = fs.nextInt();   // number of columns

        char[][] grid = new char[h][w];
        int totalStars = 0;

        // Read the grid while counting '*' cells.
        for (int i = 0; i < h; i++) {
            String line = fs.nextLine().trim();
            for (int j = 0; j < w; j++) {
                char ch = line.charAt(j);
                grid[i][j] = ch;
                if (ch == '*') {
                    totalStars++;
                }
            }
        }

        // A valid '+' must contain at least 5 '*' characters.
        if (totalStars < 5) {
            System.out.println("NO");
            return;
        }

        boolean foundCross = false;

        // Examine each '*' as a possible centre of a '+'
        for (int i = 0; i < h && !foundCross; i++) {
            for (int j = 0; j < w && !foundCross; j++) {
                if (grid[i][j] != '*') {
                    continue;
                }

                int[] lengths = crossLengths(grid, i, j);
                int crossSize = 1 + lengths[0] + lengths[1] + lengths[2] + lengths[3];

                // All four directions must have at least one '*' and the whole cross
                // must consume all stars present in the grid.
                if (lengths[0] > 0 && lengths[1] > 0 && lengths[2] > 0 && lengths[3] > 0
                        && crossSize == totalStars) {
                    foundCross = true;
                }
            }
        }

        System.out.println(foundCross ? "YES" : "NO");
    }
}

import java.io.*;
import java.util.*;

/**
 * Refactored version of the original program.
 * The functionality is unchanged – it reads a grid,
 * tries to remove a single “plus” of 1's and reports
 * whether the whole grid can be cleared.
 */
public class Main {

    /** Program entry point. */
    public static void main(String[] args) throws Exception {
        try (InputStream in = System.in;
             OutputStream out = System.out) {
            InputReader reader = new InputReader(in);
            PrintWriter writer = new PrintWriter(out);
            new Solver().solve(reader, writer);
            writer.flush();
        }
    }

    /** Simple tokeniser that reads from an InputStream. */
    static class InputReader {
        private final BufferedReader br;
        private StringTokenizer st;

        InputReader(InputStream stream) {
            br = new BufferedReader(new InputStreamReader(stream), 32768);
        }

        /** Returns the next token. */
        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    throw new UncheckedIOException(e);
                }
            }
            return st.nextToken();
        }

        /** Reads an int token. */
        int nextInt() {
            return Integer.parseInt(next());
        }
    }

    /** Encapsulates the solving logic. */
    static class Solver {

        /** Solves the problem using the supplied reader and writer. */
        void solve(InputReader in, PrintWriter out) {
            int h = in.nextInt();
            int w = in.nextInt();
            int[][] grid = readGrid(in, h, w);

            boolean plusRemoved = findAndRemovePlus(grid);
            if (!plusRemoved) {
                out.println("NO");
                return;
            }

            if (containsAnyOne(grid)) {
                out.println("NO");
            } else {
                out.println("YES");
            }
        }

        /** Parses the h×w grid from the input tokeniser. */
        private int[][] readGrid(InputReader in, int h, int w) {
            int[][] grid = new int[h][w];
            for (int i = 0; i < h; i++) {
                String line = in.next();
                for (int j = 0; j < w; j++) {
                    // '.' → 0, everything else → 1  (matches original logic)
                    grid[i][j] = (line.charAt(j) == '.') ? 0 : 1;
                }
            }
            return grid;
        }

        /** Looks for the first plus shape, removes it, and returns true if found. */
        private boolean findAndRemovePlus(int[][] grid) {
            int rows = grid.length;
            int cols = grid[0].length;

            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (isPlusCenter(grid, i, j)) {
                        clearPlus(grid, i, j);
                        return true;                // only the first plus is removed
                    }
                }
            }
            return false; // no plus could be found
        }

        /** Determines whether (i,j) is the centre of a full plus of 1's. */
        private boolean isPlusCenter(int[][] g, int i, int j) {
            return g[i][j] == 1 &&
                   i > 0 && g[i - 1][j] == 1 &&               // up
                   i + 1 < g.length && g[i + 1][j] == 1 &&   // down
                   j > 0 && g[i][j - 1] == 1 &&              // left
                   j + 1 < g[0].length && g[i][j + 1] == 1;   // right
        }

        /** Clears a plus centred at (i,j) and its contiguous arms of 1's. */
        private void clearPlus(int[][] g, int i, int j) {
            g[i][j] = 0;

            // up
            for (int t = i - 1; t >= 0 && g[t][j] == 1; t--) {
                g[t][j] = 0;
            }
            // down
            for (int t = i + 1; t < g.length && g[t][j] == 1; t++) {
                g[t][j] = 0;
            }
            // left
            for (int t = j - 1; t >= 0 && g[i][t] == 1; t--) {
                g[i][t] = 0;
            }
            // right
            for (int t = j + 1; t < g[0].length && g[i][t] == 1; t++) {
                g[i][t] = 0;
            }
        }

        /** Checks whether any cell with value 1 remains in the grid. */
        private boolean containsAnyOne(int[][] g) {
            for (int[] row : g) {
                for (int val : row) {
                    if (val == 1) {
                        return true;
                    }
                }
            }
            return false;
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.PrintWriter;
import java.io.UncheckedIOException;

/**
 * Solution for the “B+ from picture” problem.
 * Determines whether the pattern of '*' forms a single plus sign and nothing else.
 */
public class Main {

    /* --------------------------------------------------------------------- */
    /* Entry point                                                          */
    /* --------------------------------------------------------------------- */
    public static void main(String[] args) {
        /* Using try‑with‑resources guarantees proper closing of streams. */
        try (FastScanner scanner = new FastScanner(System.in);
             PrintWriter out = new PrintWriter(System.out)) {

            new Solver().solve(1, scanner, out);
        }
    }

    /* --------------------------------------------------------------------- */
    /* Core logic                                                          */
    /* --------------------------------------------------------------------- */
    private static final class Solver {
        private static final char STAR = '*';
        private static final char DOT  = '.';

        /** Entry point used by {@link Main#main}. */
        void solve(int ignoredTestNumber, FastScanner scanner, PrintWriter out) {
            int height  = scanner.nextInt();
            int width   = scanner.nextInt();

            char[][] board = readBoard(scanner, height, width);
            Position plusCenter = locatePlusCenter(board);

            if (plusCenter == null) {
                out.println("NO");
                return;
            }

            removePlusArms(board, plusCenter);

            if (containsStar(board)) {
                out.println("NO");
            } else {
                out.println("YES");
            }
        }

        /** Reads the whole grid from the scanner. */
        private static char[][] readBoard(FastScanner scanner, int h, int w) {
            char[][] board = new char[h][];
            for (int r = 0; r < h; r++) {
                board[r] = scanner.nextLine().toCharArray();
            }
            return board;
        }

        /** Finds the unique cell having '*' on all four orthogonal neighbours. */
        private static Position locatePlusCenter(char[][] board) {
            int rows = board.length;
            int cols = board[0].length;
            Position candidate = null;

            // Only inner cells can possibly be a plus centre.
            for (int r = 1; r < rows - 1; r++) {
                for (int c = 1; c < cols - 1; c++) {
                    if (isPlusCenter(board, r, c)) {
                        if (candidate != null) {
                            // More than one centre → invalid input.
                            return null;
                        }
                        candidate = new Position(r, c);
                    }
                }
            }
            return candidate;
        }

        /** Checks the four orthogonal neighbours of (r,c). */
        private static boolean isPlusCenter(char[][] board, int r, int c) {
            return board[r][c] == STAR &&
                   board[r + 1][c] == STAR && // down
                   board[r - 1][c] == STAR && // up
                   board[r][c + 1] == STAR && // right
                   board[r][c - 1] == STAR;   // left
        }

        /** Removes the whole plus sign from the board in‑place. */
        private static void removePlusArms(char[][] board, Position center) {
            removeVerticalArm(board, center.row, center.col, Direction.UP);
            removeVerticalArm(board, center.row, center.col, Direction.DOWN);
            removeHorizontalArm(board, center.row, center.col, Direction.LEFT);
            removeHorizontalArm(board, center.row, center.col, Direction.RIGHT);
        }

        /** Removes contiguous '*' cells in the given vertical direction. */
        private static void removeVerticalArm(char[][] board,
                                               int row, int col,
                                               Direction dir) {
            int step = (dir == Direction.UP) ? -1 : 1;
            while (isInBounds(board, row, col) && board[row][col] == STAR) {
                board[row][col] = DOT;
                row += step;
            }
        }

        /** Removes contiguous '*' cells in the given horizontal direction. */
        private static void removeHorizontalArm(char[][] board,
                                                int row, int col,
                                                Direction dir) {
            int step = (dir == Direction.LEFT) ? -1 : 1;
            while (isInBounds(board, row, col) && board[row][col] == STAR) {
                board[row][col] = DOT;
                col += step;
            }
        }

        /** Returns true if any '*' remains on the board. */
        private static boolean containsStar(char[][] board) {
            for (char[] row : board) {
                for (char ch : row) {
                    if (ch == STAR) {
                        return true;
                    }
                }
            }
            return false;
        }

        /** Simple immutable holder for a board coordinate. */
        private static final class Position {
            final int row;
            final int col;

            Position(int row, int col) {
                this.row  = row;
                this.col  = col;
            }
        }
    }

    /** Enum representing the four orthogonal directions. */
    private enum Direction { UP, DOWN, LEFT, RIGHT }

    /* --------------------------------------------------------------------- */
    /* Fast scanner – a thin wrapper around BufferedReader                    */
    /* --------------------------------------------------------------------- */
    private static final class FastScanner implements AutoCloseable {
        private final BufferedReader br;
        private StringTokenizer tokenizer;

        FastScanner(InputStream stream) {
            br = new BufferedReader(new InputStreamReader(stream));
            tokenizer = null;
        }

        /** Returns the next token, blocking until one is available. */
        String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    tokenizer = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    throw new UncheckedIOException(e);
                }
            }
            return tokenizer.nextToken();
        }

        /** Reads the next integer token. */
        int nextInt() {
            return Integer.parseInt(next());
        }

        /** Returns the whole next line without trimming. */
        String nextLine() {
            try {
                return br.readLine();
            } catch (IOException e) {
                throw new UncheckedIOException(e);
            }
        }

        /** Closes the underlying reader – invoked by try‑with‑resources. */
        @Override
        public void close() {
            try {
                br.close();
            } catch (IOException e) {
                throw new UncheckedIOException(e);
            }
        }
    }
}

import java.io.IOException;
import java.io.InputStream;
import java.util.NoSuchElementException;
import java.util.Random;

/**
 * Refactored version of the original program.
 *
 * <p>Changes made for maintainability and readability:
 *
 * <ul>
 *   <li>Extracted small, well‑named helper methods.</li>
 *   <li>Improved variable names and added comments.</li>
 *   <li>Removed duplicated logic by using loops and direction arrays.</li>
 *   <li>Kept the fast {@link FastScanner} for efficient input reading.</li>
 *   <li>Used early returns to avoid deep nesting.</li>
 * </ul>
 */
public class Main {

    /* --------------------------------------------------------------------- */
    /*  Configuration & I/O helpers                                          */
    /* --------------------------------------------------------------------- */

    /** Fast scanner used to read from {@code System.in} */
    private static final FastScanner SCANNER = new FastScanner();

    /** Application flow entry point */
    public static void main(String[] args) {
        solve();
    }

    /** Solves the problem and prints the answer. */
    private static void solve() {
        int height = SCANNER.nextInt();
        int width  = SCANNER.nextInt();

        char[][] grid = readGrid(height, width);
        int[] rowCount  = countStarsPerRow(grid, height, width);
        int[] colCount  = countStarsPerColumn(grid, height, width);

        int rowIdx = findIndexWithMoreThanOne(rowCount, height);
        int colIdx = findIndexWithMoreThanOne(colCount, width);

        if (!isValidPosition(rowIdx, colIdx, height, width)) {
            System.out.println("NO");
            return;
        }

        if (!isStarAt(grid, rowIdx, colIdx)) {
            System.out.println("NO");
            return;
        }

        // Attempt to clear the cross centred at (rowIdx, colIdx)
        clearVerticalSegment(grid, rowIdx, colIdx);
        clearHorizontalSegment(grid, rowIdx, colIdx);

        // After clearing, the whole board must be empty
        if (hasAnyStarRemaining(grid)) {
            System.out.println("NO");
        } else {
            System.out.println("YES");
        }
    }

    /** Reads the grid from the scanner. */
    private static char[][] readGrid(int h, int w) {
        char[][] grid = new char[h][w];
        for (int i = 0; i < h; i++) {
            String line = SCANNER.next();
            for (int j = 0; j < w; j++) {
                grid[i][j] = line.charAt(j);
            }
        }
        return grid;
    }

    /** Counts how many stars ('*') appear in each row. */
    private static int[] countStarsPerRow(char[][] grid, int h, int w) {
        int[] counts = new int[h];
        for (int i = 0; i < h; i++) {
            int cnt = 0;
            for (int j = 0; j < w; j++) {
                if (grid[i][j] == '*') cnt++;
            }
            counts[i] = cnt;
        }
        return counts;
    }

    /** Counts how many stars appear in each column. */
    private static int[] countStarsPerColumn(char[][] grid, int h, int w) {
        int[] counts = new int[w];
        for (int j = 0; j < w; j++) {
            int cnt = 0;
            for (int i = 0; i < h; i++) {
                if (grid[i][j] == '*') cnt++;
            }
            counts[j] = cnt;
        }
        return counts;
    }

    /** Returns the first index whose count is greater than one, or -1. */
    private static int findIndexWithMoreThanOne(int[] counts, int size) {
        int idx = -1;
        for (int i = 0; i < size; i++) {
            if (counts[i] > 1) {
                if (idx != -1) {
                    // More than one such row/column → invalid configuration
                    System.out.println("NO");
                    System.exit(0);
                }
                idx = i;
            }
        }
        return idx;
    }

    /** Checks whether the discovered row/column indices are meaningful. */
    private static boolean isValidPosition(int rowIdx, int colIdx, int height, int width) {
        return rowIdx != -1 && colIdx != -1;
    }

    /** Verifies that the cell at (rowIdx, colIdx) contains a star. */
    private static boolean isStarAt(char[][] grid, int rowIdx, int colIdx) {
        return grid[rowIdx][colIdx] == '*';
    }

    /** Clears the contiguous vertical segment above and below (rowIdx, colIdx). */
    private static void clearVerticalSegment(char[][] grid, int rowIdx, int colIdx) {
        clearDirection(grid, rowIdx, colIdx, Direction.UP);
        clearDirection(grid, rowIdx, colIdx, Direction.DOWN);
    }

    /** Clears the contiguous horizontal segment left and right of (rowIdx, colIdx). */
    private static void clearHorizontalSegment(char[][] grid, int rowIdx, int colIdx) {
        clearDirection(grid, rowIdx, colIdx, Direction.LEFT);
        clearDirection(grid, rowIdx, colIdx, Direction.RIGHT);
    }

    /** Clears stars in the given direction until a non‑star cell or board edge is reached. */
    private static void clearDirection(char[][] grid, int row, int col, Direction dir) {
        int dr = 0, dc = 0;
        switch (dir) {
            case UP    -> dr = -1;
            case DOWN  -> dr =  1;
            case LEFT  -> dc = -1;
            case RIGHT -> dc =  1;
        }

        int r = row + dr;
        int c = col + dc;
        boolean cleared = false;
        while (inBounds(r, grid.length, c, grid[0].length) && grid[r][c] == '*') {
            grid[r][c] = '.';               // mark cleared
            r += dr;
            c += dc;
            cleared = true;
        }
        // No star was cleared in this direction → keep the flag for caller if needed
        // (caller checks that at least one direction cleared something)
    }

    /** Simple bounds check for 2‑D array access. */
    private static boolean inBounds(int r, int rows, int c, int cols) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    /** Returns true if any star remains in the grid. */
    private static boolean hasAnyStarRemaining(char[][] grid) {
        for (char[] row : grid) {
            for (char cell : row) {
                if (cell == '*') {
                    return true;
                }
            }
        }
        return false;
    }

    /** Direction enum used for the four orthogonal moves. */
    private enum Direction {
        UP, DOWN, LEFT, RIGHT
    }

    /* --------------------------------------------------------------------- */
    /*  Fast input reader (unchanged but slightly renamed)                    */
    /* --------------------------------------------------------------------- */

    /**
     * Efficient scanner that works with byte buffers.
     *
     * <p>Only the methods used by the refactored code are exposed.
     */
    static final class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[4_096];
        private int ptr = 0;
        private int buflen = 0;

        private boolean hasNextByte() {
            if (ptr >= buflen) {
                ptr = 0;
                try {
                    buflen = in.read(buffer);
                } catch (IOException e) {
                    throw new UncheckedIOException(e);
                }
                if (buflen <= 0) {
                    return false;
                }
            }
            return true;
        }

        private int readByte() {
            return hasNextByte() ? buffer[ptr++] : -1;
        }

        private static boolean isPrintableChar(int c) {
            return 33 <= c && c <= 126;
        }

        private void skipUnprintable() {
            while (hasNextByte() && !isPrintableChar(buffer[ptr])) {
                ptr++;
            }
        }

        public boolean hasNext() {
            skipUnprintable();
            return hasNextByte();
        }

        public String next() {
            if (!hasNext()) {
                throw new NoSuchElementException();
            }
            StringBuilder sb = new StringBuilder();
            int b = readByte();
            while (isPrintableChar(b)) {
                sb.appendCodePoint(b);
                b = readByte();
            }
            return sb.toString();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        // Overloads for primitive numeric types are kept for backward compatibility
        public long nextLong() {
            return Long.parseLong(next());
        }

        public double nextDouble() {
            return Double.parseDouble(next());
        }
    }
}

/**
 * Refactored version of the original program.
 *
 * <p>
 * The program reads a rectangular grid of characters (the input size is given by two
 * integers) and determines whether a single ‘*’ cell exists that is surrounded on all
 * four orthogonal sides by ‘*’ cells and that satisfies additional contiguity checks.
 * If all conditions are met the program prints {@code YES}, otherwise it prints
 * {@code NO}.
 * </p>
 *
 * <p>
 * The refactor focuses on readability, maintainability and correctness:
 * <ul>
 *   <li>Uses clear, expressive naming.</li>
 *   <li>Separates concerns into small, single‑purpose methods.</li>
 *   <li>Avoids magic numbers and hard‑coded literals.</li>
 *   <li>Encapsulates the grid state in a dedicated field.</li>
 *   <li>Uses language features such as the try‑with‑resources statement.</li>
 * </ul>
 * </p>
 */
public class Main {

    /** Character that marks a bomb in the input grid. */
    private static final char BOMB = '*';

    /** Minimum number of rows and columns to be considered a valid interior cell. */
    private static final int BORDER = 1;

    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            Grid grid = readGrid(scanner);
            Optional<Position> center = findCenter(grid);

            // If there is no valid centre, the answer is immediately "NO".
            if (center.isEmpty()) {
                System.out.println("NO");
                return;
            }

            // Validate the row and column of the centre.
            boolean rowOk   = validateContiguousLine(grid, center.get().row, true);
            boolean columnOk = validateContiguousLine(grid, center.get().col, false);

            // Additional numerical check required by the original specification.
            boolean countMatches = (grid.totalBombs() - 1) == countPolylineBombs(grid, center.get());

            // Final decision.
            System.out.println((rowOk && columnOk && countMatches) ? "YES" : "NO");
        }
    }

    /** Reads the dimensions and the grid from {@link Scanner}. */
    private static Grid readGrid(Scanner scanner) {
        int rows = scanner.nextInt();
        int cols = scanner.nextInt();
        scanner.nextLine(); // consume the line‑break after the numbers

        char[][] map = new char[rows][cols];
        int totalBombs = 0;

        for (int r = 0; r < rows; r++) {
            String line = scanner.nextLine();
            for (int c = 0; c < cols; c++) {
                char cell = line.charAt(c);
                map[r][c] = cell;
                if (cell == BOMB) {
                    totalBombs++;
                }
            }
        }

        return new Grid(map, totalBombs);
    }

    /** Locates the unique interior cell that has bombs on all four sides. */
    private static Optional<Position> findCenter(Grid grid) {
        char[][] map = grid.map();

        for (int r = BORDER; r < map.length - BORDER; r++) {
            for (int c = BORDER; c < map[0].length - BORDER; c++) {
                if (isCenterCandidate(map, r, c)) {
                    return Optional.of(new Position(r, c));
                }
            }
        }
        return Optional.empty();
    }

    /** Checks whether a cell is surrounded by bombs on its four neighbours. */
    private static boolean isCenterCandidate(char[][] map, int row, int col) {
        return map[row][col] == BOMB &&
                map[row - 1][col] == BOMB &&   // up
                map[row + 1][col] == BOMB &&   // down
                map[row][col - 1] == BOMB &&   // left
                map[row][col + 1] == BOMB;     // right
    }

    /**
     * Validates that a given line (row or column) consisting of bomb cells
     * is *contiguously* filled without gaps.
     *
     * @param grid       the source grid
     * @param index      the row index (when {@code axisIsRow==true}) or column index
     * @param axisIsRow  {@code true} to inspect a row, {@code false} to inspect a column
     * @return {@code true} if the line contains a single continuous block of bombs
     */
    private static boolean validateContiguousLine(Grid grid, int index, boolean axisIsRow) {
        boolean started = false;
        boolean gapSeen = false;

        if (axisIsRow) {
            for (int col = 0; col < grid.cols(); col++) {
                if (grid.isBomb(index, col)) {
                    if (gapSeen) {
                        return false; // a gap appeared after we already started
                    }
                    started = true;
                } else {
                    if (started) {
                        gapSeen = true; // entering a gap after a bomb segment
                    }
                }
            }
        } else {
            for (int row = 0; row < grid.rows(); row++) {
                if (grid.isBomb(row, index)) {
                    if (gapSeen) {
                        return false;
                    }
                    started = true;
                } else {
                    if (started) {
                        gapSeen = true;
                    }
                }
            }
        }

        return !gapSeen; // no gap encountered
    }

    /**
     * Counts the bombs that belong to the “polyline” formed by the centre’s row and column.
     * The original algorithm subtracted one to avoid double‑counting the centre cell.
     */
    private static int countPolylineBombs(Grid grid, Position centre) {
        int count = 0;
        // row line
        for (int c = 0; c < grid.cols(); c++) {
            if (grid.isBomb(centre.row, c)) {
                count++;
            }
        }
        // column line (excluding the centre cell counted previously)
        for (int r = 0; r < grid.rows(); r++) {
            if (grid.isBomb(r, centre.col)) {
                count++;
            }
        }
        return count - 1; // centre counted twice
    }

    /** Simple immutable holder for a 2‑D position. */
    private static final class Position {
        final int row;
        final int col;

        Position(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }

    /** Encapsulates the grid data and related operations. */
    private static final class Grid {
        private final char[][] map;
        private final int totalBombs;

        Grid(char[][] map, int totalBombs) {
            this.map = map;
            this.totalBombs = totalBombs;
        }

        int rows() {
            return map.length;
        }

        int cols() {
            return map[0].length;
        }

        boolean isBomb(int r, int c) {
            return map[r][c] == BOMB;
        }

        int totalBombs() {
            return totalBombs;
        }
    }
}

import java.io.*;
import java.util.*;
import java.util.stream.*;

public class Main {

    public static void main(String[] args) {
        solve();
    }

    private static void solve() {
        InputReader reader = new InputReader(System.in);
        PrintWriter writer = new PrintWriter(System.out);
        new PlusPatternDetector().run(reader, writer);
        writer.flush();
    }

    /** Detects whether the given picture contains exactly one '+' pattern. */
    private static class PlusPatternDetector {

        /** Main entry point called from {@code Main}. */
        public void run(InputReader in, PrintWriter out) {
            int height = in.nextInt();
            int width = in.nextInt();

            boolean[][] picture = readPicture(in, height, width);
            boolean found = containsExactlyOnePlus(picture, height, width);
            out.println(found ? "YES" : "NO");
        }

        /** Reads the picture into a boolean matrix (true = '*').
         *  @return 2‑D array where true indicates a star cell. */
        private static boolean[][] readPicture(InputReader in, int h, int w) {
            boolean[][] picture = new boolean[h][w];
            for (int i = 0; i < h; i++) {
                String row = in.next();
                for (int j = 0; j < w; j++) {
                    picture[i][j] = (row.charAt(j) == '*');
                }
            }
            return picture;
        }

        /** Determines if the picture contains exactly one plus sign defined by:
         *  - one row that contains at least two stars,
         *  - one column that contains at least two stars,
         *  - all stars lie exclusively on that row or column,
         *  - the stars on the row and column form a contiguous block,
         *  - the total number of stars equals (rowStars + columnStars - 1).
         */
        private boolean containsExactlyOnePlus(boolean[][] picture, int h, int w) {
            int[] rowStars = countStarsPerRow(picture, h, w);
            int[] colStars = countStarsPerColumn(picture, h, w);

            // Exactly one row and one column must have more than one star.
            int onlyRowIdx = findUniqueRowWithMultiple(rowStars, h);
            int onlyColIdx = findUniqueColumnWithMultiple(colStars, w);
            if (onlyRowIdx < 0 || onlyColIdx < 0) {
                return false;
            }

            // All other rows and columns may have at most one star.
            if (!isAtMostOneStarPerRemainingRow(picture, rowStars, onlyRowIdx, h) ||
                !isAtMostOneStarPerRemainingColumn(picture, colStars, onlyColIdx, w)) {
                return false;
            }

            // Verify contiguity of stars on the selected row and column.
            if (!isContiguousIndices(getStarIndicesInRow(picture, onlyRowIdx, w))) {
                return false;
            }
            if (!isContiguousIndices(getStarIndicesInColumn(picture, onlyColIdx, h))) {
                return false;
            }

            // The crossing cell must belong to both the row and the column.
            if (!picture[onlyRowIdx][onlyColIdx]) {
                return false;
            }

            // Ensure the intersection column is not one of the extreme columns of the row,
            // and vice‑versa (original logic preserved).
            List<Integer> rowStarCols = getStarIndicesInRow(picture, onlyRowIdx, w);
            if (rowStarCols.contains(onlyColIdx)) {
                return false;
            }
            List<Integer> colStarRows = getStarIndicesInColumn(picture, onlyColIdx, h);
            if (colStarRows.contains(onlyRowIdx)) {
                return false;
            }

            // Total star count must match the sum minus the overlapping cell.
            int expectedTotal = rowStars[onlyRowIdx] + colStars[onlyColIdx] - 1;
            if (expectedTotal != countTotalStars(picture, h, w)) {
                return false;
            }

            return isContiguousIndices(colStarRows);
        }

        /** Counts stars in each row. */
        private static int[] countStarsPerRow(boolean[][] picture, int h, int w) {
            int[] counts = new int[h];
            for (int i = 0; i < h; i++) {
                int cnt = 0;
                for (int j = 0; j < w; j++) {
                    if (picture[i][j]) cnt++;
                }
                counts[i] = cnt;
            }
            return counts;
        }

        /** Counts stars in each column. */
        private static int[] countStarsPerColumn(boolean[][] picture, int h, int w) {
            int[] counts = new int[w];
            for (int j = 0; j < w; j++) {
                int cnt = 0;
                for (int i = 0; i < h; i++) {
                    if (picture[i][j]) cnt++;
                }
                counts[j] = cnt;
            }
            return counts;
        }

        /** Returns the index of the unique row that contains more than one star,
         *  or -1 if such a row does not exist or there are multiple. */
        private static int findUniqueRowWithMultiple(int[] counts, int size) {
            int idx = -1;
            for (int i = 0; i < size; i++) {
                if (counts[i] > 1) {
                    if (idx != -1) {
                        return -1; // more than one such row
                    }
                    idx = i;
                }
            }
            return idx;
        }

        /** Returns the index of the unique column that contains more than one star,
         *  or -1 if such a column does not exist or there are multiple. */
        private static int findUniqueColumnWithMultiple(int[] counts, int size) {
            int idx = -1;
            for (int j = 0; j < size; j++) {
                if (counts[j] > 1) {
                    if (idx != -1) {
                        return -1;
                    }
                    idx = j;
                }
            }
            return idx;
        }

        /** Checks that every row except the designated one has at most one star. */
        private static boolean isAtMostOneStarPerRemainingRow(boolean[][] picture,
                                                                int[] rowCounts,
                                                                int excludedRow,
                                                                int size) {
            for (int i = 0; i < size; i++) {
                if (i == excludedRow) continue;
                if (rowCounts[i] > 1) return false;
            }
            return true;
        }

        /** Checks that every column except the designated one has at most one star. */
        private static boolean isAtMostOneStarPerRemainingColumn(boolean[][] picture,
                                                                  int[] colCounts,
                                                                  int excludedCol,
                                                                  int size) {
            for (int j = 0; j < size; j++) {
                if (j == excludedCol) continue;
                if (colCounts[j] > 1) return false;
            }
            return true;
        }

        /** Returns the column indices (in increasing order) where the given row has stars. */
        private static List<Integer> getStarIndicesInRow(boolean[][] picture,
                                                         int row,
                                                         int width) {
            List<Integer> indices = new ArrayList<>();
            for (int col = 0; col < width; col++) {
                if (picture[row][col]) {
                    indices.add(col);
                }
            }
            return indices;
        }

        /** Returns the row indices (in increasing order) where the given column has stars. */
        private static List<Integer> getStarIndicesInColumn(boolean[][] picture,
                                                              int col,
                                                              int height) {
            List<Integer> indices = new ArrayList<>();
            for (int row = 0; row < height; row++) {
                if (picture[row][col]) {
                    indices.add(row);
                }
            }
            return indices;
        }

        /** Determines whether a list of increasing integers forms a contiguous block. */
        private static boolean isContiguousIndices(List<Integer> indices) {
            if (indices.isEmpty()) return true;
            int first = indices.get(0);
            int last = indices.get(indices.size() - 1);
            return (last - first + 1) == indices.size();
        }

        /** Counts all star cells in the picture. */
        private static int countTotalStars(boolean[][] picture, int h, int w) {
            return (int) IntStream.range(0, h)
                    .mapToLong(i -> LongStream.range(0, w)
                            .filter(j -> picture[i][j])
                            .count())
                    .sum();
        }
    }

    /** Simple fast input reader for competitive‑programming style problems. */
    private static class InputReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        InputReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream), 32768);
        }

        /** Returns the next token, reading a new line if necessary. */
        String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        /** Convenience method for reading an integer. */
        int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.io.BufferedReader;
import java.io.BufferedWriter;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.OutputStreamWriter;

/**
 * Reads a rectangular grid of characters and determines whether it contains
 * exactly one plus‑shaped cross made of '*' characters. If a cross is found and
 * the total number of stars equals 5 (the size of the cross), the program
 * outputs "YES"; otherwise it outputs "NO".
 */
public class CrossChecker {

    /** Character that represents a star in the input grid. */
    private static final char STAR = '*';

    /** Entry point of the program. */
    public static void main(String[] args) throws IOException {
        // Use try‑with‑resources to guarantee proper closing of I/O streams.
        try (BufferedReader reader = new BufferedReader(
                new InputStreamReader(System.in));
             BufferedWriter writer = new BufferedWriter(
                new OutputStreamWriter(System.out))) {

            // -----------------------------------------------------------------
            // 1️⃣  Read dimensions and grid data
            // -----------------------------------------------------------------
            String[] dimensionTokens = reader.readLine().split("\\s+");
            int rows = Integer.parseInt(dimensionTokens[0]);
            int cols = Integer.parseInt(dimensionTokens[1]);

            char[][] board = new char[rows][cols];
            for (int r = 0; r < rows; r++) {
                String line = reader.readLine();
                for (int c = 0; c < cols; c++) {
                    board[r][c] = line.charAt(c);
                }
            }

            // -----------------------------------------------------------------
            // 2️⃣  Solve the problem and write the result
            // -----------------------------------------------------------------
            String answer = solve(board);
            writer.write(answer);
            writer.newLine();
        }
    }

    /**
     * Analyses the board and returns "YES" if the board contains exactly one
     * plus‑shaped cross of stars, otherwise returns "NO".
     *
     * @param board the input grid
     * @return "YES" or "NO" according to the specification
     */
    private static String solve(char[][] board) {
        int totalStars = countStars(board);
        boolean crossFound = false;

        // Scan interior cells only – they have neighbours in all four directions.
        for (int r = 1; r < board.length - 1; r++) {
            for (int c = 1; c < board[0].length - 1; c++) {
                if (isCrossCenter(board, r, c)) {
                    crossFound = true;
                    break;               // a single cross is enough
                }
            }
            if (crossFound) {
                break;
            }
        }

        // The original logic returned "YES" only when a cross existed *and*
        // the total number of stars matched the cross size (5).
        return (crossFound && totalStars == 5) ? "YES" : "NO";
    }

    /** Counts all '*' characters in the whole board. */
    private static int countStars(char[][] board) {
        int count = 0;
        for (char[] row : board) {
            for (char cell : row) {
                if (cell == STAR) {
                    count++;
                }
            }
        }
        return count;
    }

    /**
     * Checks whether the cell at {@code (row, col)} is the centre of a plus
     * consisting exclusively of '*' characters extending at least one step in
     * each orthogonal direction.
     *
     * @param board the grid to inspect
     * @param row   row index of the centre (must be interior)
     * @param col   column index of the centre (must be interior)
     * @return {@code true} if the centre and its four neighbours are all stars
     */
    private static boolean isCrossCenter(char[][] board, int row, int col) {
        if (board[row][col] != STAR) {
            return false;                       // centre must be a star
        }

        // Verify the four adjacent cells (up, down, left, right)
        return board[row - 1][col] == STAR &&   // up
               board[row + 1][col] == STAR &&   // down
               board[row][col - 1] == STAR &&   // left
               board[row][col + 1] == STAR;     // right
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;

/**
 * Main entry point for the “plus‑sign’’* validator.
 *
 * <p>The program reads a grid of characters (‘*’ and ‘.’) and determines whether
 * all ‘*’ cells form exactly one plus sign that spans the whole grid.
 *
 * <p>Refactoring goals:
 * <ul>
 *   <li>Encapsulate grid handling in its own class.</li>
 *   <li>Separate concerns: input, processing, and output.</li>
 *   <li>Replace magic numbers with named constants.</li>
 *   <li>Use expressive method names and avoid deep nesting.</li>
 *   <li>Eliminate static mutable fields.</li>
 * </ul>
 *
 * @author  Original author (refactored)
 */
public class Main {

    /** Minimum size of a grid that can possibly contain a plus sign. */
    private static final int MIN_DIMENSION = 3;

    /** Directions that radiate from the centre of a plus sign. */
    private enum Direction {
        UP(-1, 0),
        DOWN(1, 0),
        LEFT(0, -1),
        RIGHT(0, 1);

        private final int dr;
        private final int dc;

        Direction(int dr, int dc) {
            this.dr = dr;
            this.dc = dc;
        }

        int getRowOffset() { return dr; }
        int getColOffset() { return dc; }
    }

    /** Small utility class that owns the grid data and offers read‑only access. */
    private static final class Grid {
        private final char[][] cells;
        private final int rows;
        private final int cols;

        Grid(int rows, int cols) {
            this.rows = rows;
            this.cols = cols;
            this.cells = new char[rows][cols];
        }

        /** Fills the grid from standard input. */
        void read(BufferedReader br) throws IOException {
            for (int r = 0; r < rows; r++) {
                String line = br.readLine();
                if (line == null) {
                    throw new IOException("Input ended unexpectedly while reading row " + r);
                }
                for (int c = 0; c < cols; c++) {
                    cells[r][c] = line.charAt(c);
                }
            }
        }

        int getRows() { return rows; }
        int getCols() { return cols; }

        /** Returns the character at (r,c) or '.' if out of bounds. */
        char at(int r, int c) {
            return inBounds(r, c) ? cells[r][c] : '.';
        }

        boolean inBounds(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }

        /** Counts the total number of ‘*’ cells in the whole grid. */
        int countStars() {
            int total = 0;
            for (char[] row : cells) {
                for (char ch : row) {
                    if (ch == '*') total++;
                }
            }
            return total;
        }
    }

    /** Returns how many consecutive ‘*’ cells are found starting at (r,c)
     *  and moving in the given direction until a non‑‘*’ or the border is hit. */
    private static int countInDirection(Grid grid, int startR, int startC, Direction dir) {
        int steps = 0;
        int r = startR;
        int c = startC;
        while (grid.inBounds(r, c) && grid.at(r, c) == '*') {
            steps++;
            r += dir.getRowOffset();
            c += dir.getColOffset();
        }
        return steps;
    }

    /** Determines whether the grid contains exactly one plus‑shaped arrangement
     *  that uses **all** ‘*’ cells. */
    private static boolean isValidPlus(Grid grid) {
        int rows = grid.getRows();
        int cols = grid.getCols();

        // A plus sign needs at least a 3×3 area.
        if (rows < MIN_DIMENSION || cols < MIN_DIMENSION) {
            return false;
        }

        int totalStars = grid.countStars();

        // Scan all inner cells that could be the centre of a plus.
        for (int r = 1; r < rows - 1; r++) {
            for (int c = 1; c < cols - 1; c++) {
                if (grid.at(r, c) != '*') {
                    continue;
                }

                // Verify the four orthogonal neighbours are also ‘*’.
                if (grid.at(r - 1, c) == '*' && grid.at(r + 1, c) == '*' &&
                    grid.at(r, c - 1) == '*' && grid.at(r, c + 1) == '*') {

                    // Count stars along each arm, starting with the neighbour cell.
                    int armLength = 1; // the centre cell itself
                    for (Direction dir : Direction.values()) {
                        armLength += countInDirection(grid, r, c, dir);
                    }

                    // If the counted stars equal the total number of stars,
                    // the grid satisfies the requirement.
                    if (armLength == totalStars) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    /** Main driver – reads input, validates the grid and prints the result. */
    public static void main(String[] args) throws IOException {
        // Input handling -------------------------------------------------------
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in))) {
            // First line: dimensions
            StringTokenizer st = new StringTokenizer(br.readLine());
            if (st == null || !st.hasMoreTokens() || !st.hasMoreTokens()) {
                System.out.println("NO");
                return;
            }
            int h = Integer.parseInt(st.nextToken());
            int w = Integer.parseInt(st.nextToken());

            // Create grid and fill it
            Grid grid = new Grid(h, w);
            grid.read(br);

            // Validation ---------------------------------------------------------
            System.out.println(isValidPlus(grid) ? "YES" : "NO");
        } catch (IOException e) {
            // In case of malformed input we also answer “NO”.
            System.out.println("NO");
        }
    }
}

package q5;

import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.util.Objects;

/**
 * Determines whether a given grid contains exactly one central '*' that forms a
 * cross whose arms together cover all '*' cells in the grid.
 *
 * <p>Input format:
 * <pre>
 * h w
 * row1
 * row2
 * ...
 * rowh
 * </pre>
 *
 * <p>Output:
 * <code>YES</code> if such a centre exists, otherwise <code>NO</code>.
 */
public final class Solution {

    /** Constant for negative answer. */
    private static final String ANSWER_NO = "NO";

    /** Constant for affirmative answer. */
    private static final String ANSWER_YES = "YES";

    /** Private constructor – utility class. */
    private Solution() { }

    /** Entry point. */
    public static void main(String[] args) throws Exception {
        try (var inputStream = System.in) {
            var reader = new GridReader(inputStream);
            run(reader);
        }
    }

    /** Orchestrates the whole solution using the supplied reader. */
    private static void run(GridReader reader) {
        // read dimensions
        int height = reader.nextInt();
        int width  = reader.nextInt();

        // read grid and count stars
        char[][] grid = new char[height][];
        int totalStars = 0;
        for (int row = 0; row < height; row++) {
            String line = reader.nextLine().trim();
            grid[row] = line.toCharArray();
            for (char cell : grid[row]) {
                if (cell == '*') {
                    totalStars++;
                }
            }
        }

        // search for a valid centre
        boolean found = false;
        for (int row = 1; row < height - 1; row++) {
            for (int col = 1; col < width - 1; col++) {
                if (grid[row][col] == '*') {
                    if (isCrossCentre(grid, row, col, totalStars)) {
                        found = true;
                        break;
                    }
                }
            }
            if (found) {
                break;
            }
        }

        System.out.println(found ? ANSWER_YES : ANSWER_NO);
    }

    /**
     * Checks whether the cell {@code (row, col)} can be the centre of a cross
     * that consumes all stars in the grid.
     *
     * @param grid   the character grid
     * @param row    centre row index
     * @param col    centre column index
     * @param totalStars total number of '*' in the whole grid
     * @return {@code true} if the cross uses exactly {@code totalStars} '*' cells
     */
    private static boolean isCrossCentre(char[][] grid, int row, int col, int totalStars) {
        // count consecutive stars in the four directions
        int left  = countLeft(grid, row, col);
        int right = countRight(grid, row, col);
        int up    = countUp(grid, row, col);
        int down  = countDown(grid, row, col);

        // all four directions must have at least one star
        if (left == 0 || right == 0 || up == 0 || down == 0) {
            return false;
        }

        // centre itself + arms must equal total stars observed
        return left + right + up + down + 1 == totalStars;
    }

    /** Counts '*' to the left of {@code (row, col)} until a non‑'*' or border is hit. */
    private static int countLeft(char[][] grid, int row, int col) {
        int cnt = 0;
        for (int c = col - 1; c >= 0; c--) {
            if (grid[row][c] == '*') {
                cnt++;
            } else {
                break;
            }
        }
        return cnt;
    }

    /** Counts '*' to the right of {@code (row, col)} until a non‑'*' or border is hit. */
    private static int countRight(char[][] grid, int row, int col) {
        int cnt = 0;
        for (int c = col + 1; c < grid[row].length; c++) {
            if (grid[row][c] == '*') {
                cnt++;
            } else {
                break;
            }
        }
        return cnt;
    }

    /** Counts '*' upwards from {@code (row, col)} until a non‑'*' or border is hit. */
    private static int countUp(char[][] grid, int row, int col) {
        int cnt = 0;
        for (int r = row - 1; r >= 0; r--) {
            if (grid[r][col] == '*') {
                cnt++;
            } else {
                break;
            }
        }
        return cnt;
    }

    /** Counts '*' downwards from {@code (row, col)} until a non‑'*' or border is hit. */
    private static int countDown(char[][] grid, int row, int col) {
        int cnt = 0;
        for (int r = row + 1; r < grid.length; r++) {
            if (grid[r][col] == '*') {
                cnt++;
            } else {
                break;
            }
        }
        return cnt;
    }

    /** Small wrapper around a {@link BufferedReader} that also provides a tokenizer. */
    private static final class GridReader {
        private final BufferedReader br;
        private StringTokenizer tokenizer;

        GridReader(InputStream source) {
            this.br = new BufferedReader(new InputStreamReader(source));
        }

        /** Reads the next line (used only to reset the tokenizer). */
        private void reloadTokenizer() throws java.io.IOException {
            tokenizer = new StringTokenizer(br.readLine());
        }

        /** Returns the next token, lazily initialising the tokenizer when needed. */
        private String nextToken() throws java.io.IOException {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                reloadTokenizer();
            }
            return tokenizer.nextToken();
        }

        /** Convenience wrapper for {@code nextInt()} */
        private int nextInt() throws java.io.IOException {
            return Integer.parseInt(nextToken());
        }

        /** Convenience wrapper for {@code nextLine()} */
        private String nextLine() throws java.io.IOException {
            return br.readLine();
        }
    }
}

import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;

/**
 * Refactored solution for the “cross of stars” problem.
 *
 * <p>The program reads a grid of characters and determines whether the
 * pattern consists of exactly one plus sign made of '*' characters,
 * with no extra stars elsewhere.</p>
 */
public class A13 {

    /** Simple holder for a matrix coordinate. */
    private static final class Cell {
        final int row;
        final int col;
        Cell(int row, int col) { this.row = row; this.col = col; }
    }

    public static void main(String[] args) {
        try (Scanner sc = new Scanner(System.in)) {
            int h = sc.nextInt();          // number of rows
            int w = sc.nextInt();          // number of columns
            char[][] grid = new char[h][w];
            List<Cell> stars = new ArrayList<>();

            // Read the matrix and collect all '*' positions
            for (int i = 0; i < h; i++) {
                String line = sc.next();
                for (int j = 0; j < w; j++) {
                    grid[i][j] = line.charAt(j);
                    if (grid[i][j] == '*') {
                        stars.add(new Cell(i, j));
                    }
                }
            }

            // Empty grid cannot form a cross
            if (stars.isEmpty()) {
                System.out.println("NO");
                return;
            }

            // Locate the centre of the plus sign (must have neighbours in all directions)
            Cell centre = findCentre(grid, stars);
            if (centre == null) {
                System.out.println("NO");
                return;
            }

            // Determine the extreme positions of the cross
            int left  = firstStarLeft(grid, centre);
            int right = firstStarRight(grid, centre);
            int up    = firstStarUp(grid, centre);
            int down  = firstStarDown(grid, centre);

            // Validate that the discovered plus is complete and isolated
            if (isValidCross(grid, centre, left, right, up, down, stars)) {
                System.out.println("YES");
            } else {
                System.out.println("NO");
            }
        }
    }

    /** Returns a star that has immediate neighbours on all four sides, or {@code null}. */
    private static Cell findCentre(char[][] g, List<Cell> stars) {
        for (Cell c : stars) {
            if (hasAllFourNeighbours(g, c.row, c.col)) {
                return c;
            }
        }
        return null;
    }

    private static boolean hasAllFourNeighbours(char[][] g, int r, int c) {
        return r > 0 && r < g.length - 1 && c > 0 && c < g[0].length - 1 &&
               g[r - 1][c] == '*' && g[r + 1][c] == '*' &&
               g[r][c - 1] == '*' && g[r][c + 1] == '*';
    }

    /** Scans left from the centre until a non‑'*' character is found. */
    private static int firstStarLeft(char[][] g, Cell centre) {
        for (int col = centre.col - 1; col >= 0; col--) {
            if (g[centre.row][col] != '*') break;
            if (col == 0) return col; // reached left border
        }
        return centre.col - 1; // smallest valid index
    }

    /** Scans right from the centre until a non‑'*' character is found. */
    private static int firstStarRight(char[][] g, Cell centre) {
        for (int col = centre.col + 1; col < g[0].length; col++) {
            if (g[centre.row][col] != '*') break;
            if (col == g[0].length - 1) return col; // reached right border
        }
        return centre.col + 1;
    }

    /** Scans upward from the centre until a non‑'*' character is found. */
    private static int firstStarUp(char[][] g, Cell centre) {
        for (int row = centre.row - 1; row >= 0; row--) {
            if (g[row][centre.col] != '*') break;
            if (row == 0) return row; // reached top border
        }
        return centre.row - 1;
    }

    /** Scans downward from the centre until a non‑'*' character is found. */
    private static int firstStarDown(char[][] g, Cell centre) {
        for (int row = centre.row + 1; row < g.length; row++) {
            if (g[row][centre.col] != '*') break;
            if (row == g.length - 1) return row; // reached bottom border
        }
        return centre.row + 1;
    }

    /**
     * Verifies that every star belongs to the same row or column as the centre,
     * that the horizontal and vertical segments are gap‑free, and that there are
     * at least one star in each direction.
     */
    private static boolean isValidCross(char[][] g, Cell centre,
                                        int left, int right, int up, int down,
                                        List<Cell> allStars) {
        // At least one star must exist in each direction of the plus
        if (left >= centre.col || right <= centre.col ||
            up   >= centre.row || down  <= centre.row) {
            return false;
        }

        // Horizontal continuity on the centre row
        if (!isContiguousHorizontal(g, centre.row, left, right)) return false;
        // Vertical continuity on the centre column
        if (!isContiguousVertical(g, centre.col, up, down)) return false;

        // No star may lie outside the identified cross
        for (Cell c : allStars) {
            if (c.row == centre.row || c.col == centre.col) continue;
            return false; // star outside the cross
        }
        return true;
    }

    private static boolean isContiguousHorizontal(char[][] g, int row, int left, int right) {
        for (int col = left; col <= right; col++) {
            if (g[row][col] != '*') return false;
        }
        return true;
    }

    private static boolean isContiguousVertical(char[][] g, int col, int up, int down) {
        for (int row = up; row <= down; row++) {
            if (g[row][col] != '*') return false;
        }
        return true;
    }
}

import java.util.Scanner;

/**
 * Determines whether a given picture consists of exactly one “+” shape
 * made of ‘#’ (or any non‑‘.’ character) and nothing else.
 *
 * <p>Refactoring focuses on:
 * <ul>
 *   <li>Single‑responsibility methods</li>
 *   <li>Clear naming and constants</li>
 *   <li>Try‑with‑resources for automatic closing</li>
 *   <li>Early returns to avoid deep nesting</li>
 *   <li>Java 17‑compatible syntax</li>
 * </ul>
 */
public class PlusFromPicture {

    /** Scanner used for reading input – closed automatically. */
    private static final Scanner SCANNER = new Scanner(System.in);

    public static void main(String[] args) {
        int height = SCANNER.nextInt();
        int width  = SCANNER.nextInt();
        SCANNER.nextLine();                    // consume line separator

        int[][] board = readBoard(height, width);

        if (isBoardEmpty(board)) {
            System.out.println("NO");
            return;
        }

        boolean success = findAndRemovePlus(board, height, width);
        System.out.println(success ? "YES" : "NO");
    }

    /** Reads the grid from standard input. */
    private static int[][] readBoard(int h, int w) {
        int[][] grid = new int[h][w];
        for (int r = 0; r < h; r++) {
            String line = SCANNER.nextLine();
            for (int c = 0; c < w; c++) {
                grid[r][c] = (line.charAt(c) == '.') ? 0 : 1;
            }
        }
        return grid;
    }

    /** Returns true if the board contains no ‘1’ cells. */
    private static boolean isBoardEmpty(int[][] grid) {
        outer:
        for (int[][] rows : grid) {
            for (int cell : rows) {
                if (cell == 1) {
                    break outer;
                }
            }
        }
        return true;
    }

    /**
     * Searches for a ‘+’ centre, removes the whole plus and all connected
     * ‘1’ cells in its arms, and checks whether the board becomes empty.
     *
     * @return {@code true} if removal leaves an empty board, {@code false} otherwise.
     */
    private static boolean findAndRemovePlus(int[][] board, int h, int w) {
        for (int r = 1; r < h - 1; r++) {
            for (int c = 1; c < w - 1; c++) {
                if (isPlusCenter(board, r, c)) {
                    removeConnectedOnes(board, r, c, h, w);
                    if (isBoardEmpty(board)) {
                        return true;
                    }
                    // Once a plus that does NOT clear the board is found,
                    // the answer is definitively “NO”.
                    return false;
                }
            }
        }
        // No plus centre was found at all.
        return false;
    }

    /** Checks whether the cell (row, col) is the centre of a plus. */
    private static boolean isPlusCenter(int[][] g, int row, int col) {
        return g[row][col] == 1 &&
               g[row - 1][col] == 1 &&
               g[row + 1][col] == 1 &&
               g[row][col - 1] == 1 &&
               g[row][col + 1] == 1;
    }

    /**
     * Clears the centre of a plus and all contiguous ‘1’s extending
     * upward, downward, leftward and rightward from that centre.
     */
    private static void removeConnectedOnes(int[][] g, int startRow, int startCol,
                                            int h, int w) {
        // vertical upward
        int r = startRow;
        while (r - 1 >= 0 && g[r - 1][startCol] == 1) {
            g[r - 1][startCol] = 0;
            r--;
        }
        // vertical downward
        r = startRow;
        while (r + 1 < h && g[r + 1][startCol] == 1) {
            g[r + 1][startCol] = 0;
            r++;
        }
        // horizontal leftward
        int c = startCol;
        while (c - 1 >= 0 && g[startRow][c - 1] == 1) {
            g[startRow][c - 1] = 0;
            c--;
        }
        // horizontal rightward
        c = startCol;
        while (c + 1 < w && g[startRow][c + 1] == 1) {
            g[startRow][c + 1] = 0;
            c++;
        }
        // finally clear the centre itself
        g[startRow][startCol] = 0;
    }
}

import java.io.*;
import java.util.*;

/**
 * Solution for the “Cross” problem.
 *
 * The program reads a grid of characters ('*' and '.').  If there exists a
 * cell that can be the centre of a cross (the cell itself and its four
 * orthogonal neighbours are all '*'), the whole cross – i.e. the centre
 * plus all contiguous '*' in the four directions – is removed.
 * Afterwards the grid is examined: if no '*' remains the answer is “YES”,
 * otherwise it is “NO”.
 *
 * The implementation is deliberately split into small, pure methods to
 * improve readability, testability and future maintenance.
 */
public class Main {

    /** Program entry point. */
    public static void main(String[] args) {
        FastScanner fs = new FastScanner();

        int h = fs.nextInt();          // number of rows
        int w = fs.nextInt();          // number of columns

        // Read the whole grid.
        char[][] grid = new char[h][];
        for (int i = 0; i < h; i++) {
            grid[i] = fs.next().toCharArray();
        }

        // Look for a cross that can be removed completely.
        Optional<Set<Point>> cross = findCross(grid);
        if (!cross.isPresent()) {
            System.out.println("NO");
            return;
        }

        // Erase every cell belonging to the discovered cross.
        for (Point p : cross.get()) {
            grid[p.row][p.col] = '.';
        }

        // If any '*' is left, the answer is NO.
        System.out.println(anyStarRemains(grid) ? "NO" : "YES");
    }

    /** Returns an optional set containing all coordinates that form a cross.
     *  The method stops at the first suitable centre it encounters. */
    private static Optional<Set<Point>> findCross(char[][] grid) {
        int h = grid.length;
        int w = grid[0].length;

        for (int i = 1; i < h - 1; i++) {
            for (int j = 1; j < w - 1; j++) {
                if (isCrossCenter(grid, i, j)) {
                    Set<Point> points = new HashSet<>();
                    points.add(new Point(i, j));
                    collectCrossPoints(grid, i, j, points);
                    return Optional.of(points);
                }
            }
        }
        return Optional.empty();
    }

    /** Checks whether (i, j) can be the centre of a cross – i.e. itself and the
     *  four orthogonal neighbours are '*'. */
    private static boolean isCrossCenter(char[][] grid, int i, int j) {
        return grid[i][j] == '*' &&
               grid[i - 1][j] == '*' &&   // up
               grid[i + 1][j] == '*' &&   // down
               grid[i][j - 1] == '*' &&   // left
               grid[i][j + 1] == '*';     // right
    }

    /** Collects every '*' that belongs to the same cross as the centre
     *  (i, j). The points are added to {@code collector}. */
    private static void collectCrossPoints(char[][] grid,
                                            int i,
                                            int j,
                                            Set<Point> collector) {
        int h = grid.length;
        int w = grid[0].length;

        // upward
        for (int k = i - 1; k >= 0 && grid[k][j] == '*'; k--) {
            collector.add(new Point(k, j));
        }
        // downward
        for (int k = i + 1; k < h && grid[k][j] == '*'; k++) {
            collector.add(new Point(k, j));
        }
        // leftward
        for (int k = j - 1; k >= 0 && grid[i][k] == '*'; k--) {
            collector.add(new Point(i, k));
        }
        // rightward
        for (int k = j + 1; k < w && grid[i][k] == '*'; k++) {
            collector.add(new Point(i, k));
        }
    }

    /** Returns true if at least one '*' remains in the grid. */
    private static boolean anyStarRemains(char[][] grid) {
        for (char[] row : grid) {
            for (char cell : row) {
                if (cell == '*') {
                    return true;
                }
            }
        }
        return false;
    }

    /** Simple immutable container for row/column coordinates. */
    private static final class Point {
        final int row;
        final int col;

        Point(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }

    /** Very small fast scanner based on {@link BufferedReader}. */
    private static final class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner() {
            this(System.in);
        }

        private FastScanner(InputStream in) {
            this.br = new BufferedReader(new InputStreamReader(in));
        }

        /** Returns the next token or {@code null} if the stream is exhausted. */
        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) {
                        return null;
                    }
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new UncheckedIOException(e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        /** Reads exactly {@code count} integers from the input. */
        int[] nextIntArray(int count) {
            int[] arr = new int[count];
            for (int i = 0; i < count; i++) {
                arr[i] = nextInt();
            }
            return arr;
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.Objects;

/**
 * Maintains a grid of '*' and '.' characters and decides whether the pattern
 * matches the required configuration.
 *
 * <p>The algorithm follows the same logical steps as the original code but
 * isolates each step in its own well‑named method, uses early returns,
 * avoids deep nesting and guarantees deterministic resource closing.</p>
 */
public class Main {

    /** Symbol that represents a filled cell. */
    private static final char STAR = '*';

    /** Directions used for neighbour checks. */
    private enum Direction { LEFT, RIGHT }

    public static void main(String[] args) {
        // Try‑with‑resources guarantees the BufferedReader is closed.
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in))) {
            String[] header = br.readLine().split("\\s+");
            if (header == null || header.length != 2) {
                System.out.println("NO");
                return;
            }

            int rows = Integer.parseInt(header[0]);
            int cols = Integer.parseInt(header[1]);

            // Read the whole grid.
            String[] grid = new String[rows];
            for (int i = 0; i < rows; i++) {
                grid[i] = br.readLine();
                if (grid[i] == null || grid[i].length() != cols) {
                    System.out.println("NO");
                    return;
                }
            }

            if (!isValidConfiguration(grid)) {
                System.out.println("NO");
            }
        } catch (IOException | NumberFormatException e) {
            // Any parsing or I/O problem is treated as an invalid configuration.
            System.out.println("NO");
        }
    }

    /** Entry point that decides whether the grid respects the specification. */
    private static boolean isValidConfiguration(String[] grid) {
        int rows = grid.length;
        int cols = grid[0].length();

        // 1️⃣  Find a top‑most '*' that has no neighbouring '*' on its left/right.
        Optional<Point> start = locateTopStar(grid);
        if (!start.isPresent()) {
            return false;
        }
        Point pivot = start.get();

        // 2️⃣  Make sure the chosen cell has no adjacent '*' on the sides.
        if (hasAdjacentStar(grid, pivot.row, pivot.col, Direction.LEFT) ||
            hasAdjacentStar(grid, pivot.row, pivot.col, Direction.RIGHT)) {
            return false;
        }

        // 3️⃣  Extend the vertical segment downwards.
        VerticalSegment segment = extendDownwards(grid, pivot);
        if (segment.length() < 2) {
            return false;                     // need at least two '*' vertically
        }

        // 4️⃣  From the bottom of the vertical segment, build left and right arms.
        ArmLengths arms = exploreArms(grid, segment.bottomRow(), pivot.col);
        if (arms.leftLen == 0 || arms.rightLen == 0) {
            return false;                     // arms must exist on both sides
        }

        // 5️⃣  Mark every visited '*' in a boolean matrix.
        boolean[][] visited = new boolean[rows][cols];
        markVisited(visited, segment.points());
        markVisited(visited, arms.leftPoints());
        markVisited(visited, arms.rightPoints());

        // 6️⃣  Finally, verify that *every* '*' in the grid has been visited.
        return allStarsAreVisited(grid, visited);
    }

    /* --------------------------------------------------------------------------- */
    /*  Helper methods – each does one focused job                                   */
    /* --------------------------------------------------------------------------- */

    /** Returns the first '*' that could be the top of a vertical line. */
    private static Optional<Point> locateTopStar(String[] grid) {
        for (int r = 0; r < grid.length; r++) {
            String row = grid[r];
            for (int c = 0; c < row.length(); c++) {
                if (row.charAt(c) == STAR) {
                    // candidate must not have a '*' on its left or right neighbour
                    if (!hasAdjacentStar(grid, r, c, Direction.LEFT) &&
                        !hasAdjacentStar(grid, r, c, Direction.RIGHT)) {
                        return Optional.of(new Point(r, c));
                    }
                }
            }
        }
        return Optional.empty();
    }

    /** Checks whether a neighbour in the given direction contains a '*'. */
    private static boolean hasAdjacentStar(String[] grid, int row, int col, Direction dir) {
        int nr = row, nc = col;
        switch (dir) {
            case LEFT  -> nc--;
            case RIGHT -> nc++;
        }
        if (nr < 0 || nr >= grid.length || nc < 0 || nc >= grid[0].length()) {
            return false;
        }
        return grid[nr].charAt(nc) == STAR;
    }

    /** Extends downward from (row, col) while '*' is encountered. */
    private static VerticalSegment extendDownwards(String[] grid, Point top) {
        int bottomRow = top.row;
        int length = 0;
        var points = new java.util.ArrayList<Point>();

        while (bottomRow < grid.length && grid[bottomRow].charAt(top.col) == STAR) {
            points.add(new Point(bottomRow, top.col));
            length++;
            bottomRow++;
        }

        // The bottommost valid row is the one before the break.
        bottomRow--;

        return new VerticalSegment(bottomRow, points);
    }

    /** Lengths of the left/right arms that start from (row, col). */
    private static final class ArmLengths {
        final int leftLen;
        final int rightLen;
        final java.util.List<Point> leftPoints;
        final java.util.List<Point> rightPoints;

        ArmLengths(int leftLen, int rightLen,
                   java.util.List<Point> leftPoints,
                   java.util.List<Point> rightPoints) {
            this.leftLen = leftLen;
            this.rightLen = rightLen;
            this.leftPoints = leftPoints;
            this.rightPoints = rightPoints;
        }
    }

    /** Explores the horizontal arms from the pivot row and records visited cells. */
    private static ArmLengths exploreArms(String[] grid, int row, int startCol) {
        // ---- left arm ---------------------------------------------------------
        int leftLen = 0;
        var leftPoints = new java.util.ArrayList<Point>();
        for (int c = startCol - 1; c >= 0 && grid[row].charAt(c) == STAR; c--) {
            leftLen++;
            leftPoints.add(new Point(row, c));
        }

        // ---- right arm --------------------------------------------------------
        int rightLen = 0;
        var rightPoints = new java.util.ArrayList<Point>();
        for (int c = startCol + 1; c < grid[0].length() && grid[row].charAt(c) == STAR; c++) {
            rightLen++;
            rightPoints.add(new Point(row, c));
        }

        // The pivot cell itself will be marked later by the caller.
        return new ArmLengths(leftLen, rightLen, leftPoints, rightPoints);
    }

    /** Marks all points of a collection as visited in the matrix. */
    private static void markVisited(boolean[][] visited, java.util.List<Point> points) {
        for (Point p : points) {
            visited[p.row][p.col] = true;
        }
    }

    /** Returns {@code true} iff every '*' in the grid has been marked visited. */
    private static boolean allStarsAreVisited(String[] grid, boolean[][] visited) {
        for (int r = 0; r < grid.length; r++) {
            String row = grid[r];
            for (int c = 0; c < row.length(); c++) {
                if (row.charAt(c) == STAR && !visited[r][c]) {
                    return false;
                }
            }
        }
        return true;
    }

    /** Simple immutable pair of coordinates. */
    private static final class Point {
        final int row;
        final int col;

        Point(int row, int col) {
            this.row = row;
            this.col = col;
        }

        @Override
        public boolean equals(Object o) {
            if (this == o) return true;
            if (!(o instanceof Point)) return false;
            Point p = (Point) o;
            return row == p.row && col == p.col;
        }

        @Override
        public int hashCode() {
            return Objects.hash(row, col);
        }
    }

    /** Container for the vertical segment discovered during the scan. */
    private static final class VerticalSegment {
        final int bottomRow;                 // row index of the last '*' in the column
        final java.util.List<Point> points;  // all '*' cells that belong to the column

        VerticalSegment(int bottomRow, java.util.List<Point> points) {
            this.bottomRow = bottomRow;
            this.points = java.util.Collections.unmodifiableList(
                    new java.util.ArrayList<>(points));
        }

        int length() {
            return points.size();
        }
    }
}

import java.io.*;
import java.util.*;

public class Main {

    /** Simple scanner that reads tokens from standard input (or a file). */
    private static final class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner(InputStream input) {
            this.br = new BufferedReader(new InputStreamReader(input));
        }

        /** Returns the next token, blocking if necessary. */
        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    throw new UncheckedIOException(e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        /** Reads the next token and returns it as a character array (the whole word). */
        char[] nextCharArray() {
            return next().toCharArray();
        }
    }

    public static void main(String[] args) throws IOException {
        // The try‑with‑resources block guarantees the scanner is closed.
        try (FastScanner fs = new FastScanner(System.in)) {
            solve(fs);
        }
    }

    /** Entry point for the solution – reads the grid, processes it and prints the answer. */
    private static void solve(FastScanner fs) {
        int rows = fs.nextInt();
        int cols = fs.nextInt();

        // Read the whole grid into a char matrix.
        char[][] grid = new char[rows][];
        for (int r = 0; r < rows; r++) {
            grid[r] = fs.nextCharArray();
        }

        // Look for a cell that is the centre of a plus‑sign of '*'.
        int centreR = -1, centreC = -1;
        if (findCrossPattern(grid, centreR, centreC)) {
            // Remove that plus‑sign from the grid.
            removeCross(grid, centreR, centreC);
            // Count how many '*' remain.
            long remainingStars = countStars(grid);
            // The original problem expects "YES" only when exactly one star is left.
            if (remainingStars == 1) {
                System.out.println("YES");
            } else {
                System.out.println("NO");
            }
        } else {
            System.out.println("NO");
        }
    }

    /**
     * Scans the interior of the grid for a cell that is a '*'
     * surrounded on its four orthogonal neighbours by '*'.
     *
     * @return {@code true} if such a pattern exists and the centre coordinates are stored
     *         in {@code centreR} and {@code centreC} via the supplied arguments.
     */
    private static boolean findCrossPattern(char[][] grid, int centreR, int centreC) {
        int rows = grid.length;
        int cols = grid[0].length;

        for (int r = 1; r < rows - 1; r++) {
            for (int c = 1; c < cols - 1; c++) {
                if (grid[r][c] == '*' &&
                    grid[r - 1][c] == '*' &&
                    grid[r + 1][c] == '*' &&
                    grid[r][c - 1] == '*' &&
                    grid[r][c + 1] == '*') {
                    centreR = r;
                    centreC = c;
                    return true;
                }
            }
        }
        return false;
    }

    /** Erases the whole plus‑sign (center and its four arms) by turning '*' into '.'. */
    private static void removeCross(char[][] grid, int centreR, int centreC) {
        // Directions: up, down, left, right.
        int[][] dirs = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};

        for (int[] d : dirs) {
            int nr = centreR + d[0];
            int nc = centreC + d[1];
            // Walk outwards while we see '*' and stay inside the matrix.
            while (isInside(grid, nr, nc) && grid[nr][nc] == '*') {
                grid[nr][nc] = '.';
                nr += d[0];
                nc += d[1];
            }
        }
        // Finally erase the centre cell itself.
        grid[centreR][centreC] = '.';
    }

    private static boolean isInside(char[][] grid, int r, int c) {
        return r >= 0 && r < grid.length && c >= 0 && c < grid[0].length;
    }

    /** Counts the occurrences of '*' in the whole matrix. */
    private static long countStars(char[][] grid) {
        long cnt = 0;
        for (char[] row : grid) {
            for (char ch : row) {
                if (ch == '*') {
                    cnt++;
                }
            }
        }
        return cnt;
    }
}

import java.io.*;
import java.util.*;

public class First {

    /** Symbol that represents an empty cell. */
    private static final char EMPTY = '.';

    public static void main(String[] args) throws IOException {
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
             PrintWriter writer = new PrintWriter(System.out)) {

            int rows = readInt(reader);
            int cols = readInt(reader);

            char[][] grid = readGrid(reader, rows, cols);

            CrossValidationResult result = validateCross(grid, rows, cols);

            if (result.isValid()) {
                writer.println("YES");
            } else {
                writer.println("NO");
            }
        }
    }

    /** Reads the next integer token from the supplied reader. */
    private static int readInt(BufferedReader reader) throws IOException {
        StringTokenizer st = new StringTokenizer(reader.readLine());
        return Integer.parseInt(st.nextToken());
    }

    /** Reads exactly `rows` lines, each containing `cols` characters, into a 2‑D array. */
    private static char[][] readGrid(BufferedReader reader, int rows, int cols) throws IOException {
        char[][] grid = new char[rows][cols];
        for (int r = 0; r < rows; r++) {
            Arrays.fill(grid[r], EMPTY);
            String line = reader.readLine();
            if (line != null) {
                for (int c = 0; c < Math.min(line.length(), cols); c++) {
                    grid[r][c] = line.charAt(c);
                }
            }
        }
        return grid;
    }

    /**
     * Validates whether the grid contains exactly one plus‑shaped pattern of '*' cells.
     * All non‑'.' characters must belong to that plus and each arm must have a length
     * of at least 2 (including the centre cell).
     */
    private static CrossValidationResult validateCross(char[][] grid, int rows, int cols) {
        Optional<Position> centre = findCentre(grid, rows, cols);
        if (!centre.isPresent()) {
            return CrossValidationResult.INVALID;
        }

        Position p = centre.get();
        boolean[][] visited = new boolean[rows][cols];
        visited[p.row][p.col] = true;

        // Directions: down, up, right, left
        int[][] dirs = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};
        final int MIN_ARM_EXTENSION = 2; // at least one extra cell beyond the centre

        for (int[] d : dirs) {
            int nr = p.row + d[0];
            int nc = p.col + d[1];
            int extension = 0;
            while (inBounds(nr, nc, rows, cols) && grid[nr][nc] == '*') {
                visited[nr][nc] = true;
                extension++;
                nr += d[0];
                nc += d[1];
            }
            // extension counts only the cells *beyond* the centre
            if (extension < MIN_ARM_EXTENSION - 1) {
                return CrossValidationResult.INVALID;
            }
        }

        // No stray '*' may remain unvisited
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] != EMPTY && !visited[r][c]) {
                    return CrossValidationResult.INVALID;
                }
            }
        }

        return CrossValidationResult.VALID;
    }

    /** Returns the coordinates of a cell that can be the centre of a plus, or empty if none exists. */
    private static Optional<Position> findCentre(char[][] grid, int rows, int cols) {
        for (int r = 1; r < rows - 1; r++) {
            for (int c = 1; c < cols - 1; c++) {
                if (grid[r][c] == '*' &&
                    grid[r - 1][c] != EMPTY && // something above
                    grid[r][c - 1] != EMPTY // something left
                ) {
                    return Optional.of(new Position(r, c));
                }
            }
        }
        return Optional.empty();
    }

    /** Simple holder for a row/column pair. */
    private static final class Position {
        final int row;
        final int col;

        Position(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }

    /** Encapsulates the validation outcome, making the intent explicit. */
    private enum CrossValidationResult {
        VALID,
        INVALID;

        static CrossValidationResult INVALID() {
            return INVALID;
        }

        boolean isValid() {
            return this == VALID;
        }
    }
}

import java.io.PrintWriter;
import java.util.Scanner;

/**
 * Entry point of the application.
 * Reads the input, delegates the solving to {@link BPlusDetector} and prints the result.
 */
public class Main {
    public static void main(String[] args) {
        // Use try‑with‑resources to guarantee proper closure of I/O streams
        try (Scanner scanner = new Scanner(System.in);
             PrintWriter out = new PrintWriter(System.out)) {

            new BPlusDetector().solve(scanner, out);
        }
    }
}

/**
 * Encapsulates all logic required to determine whether a B+ shape exists in the grid.
 * The class is deliberately small and focused on a single responsibility.
 */
class BPlusDetector {

    /** Orchestrates the whole solving process. */
    public void solve(Scanner in, PrintWriter out) {
        int height = in.nextInt();
        int width  = in.nextInt();

        char[][] grid = readGrid(in, height, width);
        int totalStars = countStars(grid);

        boolean found = hasBPlusShape(grid, totalStars);

        out.println(found ? "YES" : "NO");
    }

    /** Reads exactly {@code height} lines of length {@code width} from the scanner. */
    private char[][] readGrid(Scanner in, int height, int width) {
        char[][] grid = new char[height][width];
        for (int row = 0; row < height; row++) {
            if (!in.hasNext()) {
                break;
            }
            String line = in.next();
            for (int col = 0; col < width; col++) {
                grid[row][col] = line.charAt(col);
            }
        }
        return grid;
    }

    /** Counts the total number of '*' characters in the grid. */
    private int countStars(char[][] grid) {
        int count = 0;
        for (char[] row : grid) {
            for (char cell : row) {
                if (cell == '*') {
                    count++;
                }
            }
        }
        return count;
    }

    /**
     * Determines whether the grid contains a B+ shape that consumes all '*'
     * characters and satisfies the required geometry.
     *
     * @return {@code true} if such a shape exists, otherwise {@code false}.
     */
    private boolean hasBPlusShape(char[][] grid, int totalStars) {
        int rows = grid.length;
        int cols = grid[0].length;

        for (int r = 1; r < rows - 1; r++) {
            for (int c = 1; c < cols - 1; c++) {
                if (grid[r][c] != '*') {
                    continue;
                }

                // Examine the four arms of the possible plus sign
                int right   = expandRight(grid, r, c);
                int left    = expandLeft(grid, r, c);
                int up      = expandUp(grid, r, c);
                int down    = expandDown(grid, r, c);

                // All four directions must contain at least one additional '*'
                if (right == 0 || left == 0 || up == 0 || down == 0) {
                    continue;
                }

                int crossLength = 1 + right + left + up + down; // centre + arms
                if (crossLength >= 5 && crossLength == totalStars) {
                    return true;
                }
            }
        }
        return false;
    }

    /** Extends to the right from the given cell and counts consecutive '*'. */
    private int expandRight(char[][] grid, int row, int col) {
        int count = 0;
        for (int c = col + 1; c < grid[0].length; c++) {
            if (grid[row][c] == '*') {
                count++;
            } else {
                break;
            }
        }
        return count;
    }

    /** Extends to the left from the given cell and counts consecutive '*'. */
    private int expandLeft(char[][] grid, int row, int col) {
        int count = 0;
        for (int c = col - 1; c >= 0; c--) {
            if (grid[row][c] == '*') {
                count++;
            } else {
                break;
            }
        }
        return count;
    }

    /** Extends downward from the given cell and counts consecutive '*'. */
    private int expandDown(char[][] grid, int row, int col) {
        int count = 0;
        for (int r = row + 1; r < grid.length; r++) {
            if (grid[r][col] == '*') {
                count++;
            } else {
                break;
            }
        }
        return count;
    }

    /** Extends upward from the given cell and counts consecutive '*'. */
    private int expandUp(char[][] grid, int row, int col) {
        int count = 0;
        for (int r = row - 1; r >= 0; r--) {
            if (grid[r][col] == '*') {
                count++;
            } else {
                break;
            }
        }
        return count;
    }
}

import java.io.*;
import java.util.StringTokenizer;

/**
 * Main solution class.
 * <p>
 * The program reads a number of test cases. For each test case it receives a grid
 * consisting of '.' (empty) and '*' (star) characters. It checks whether the stars
 * form a single "cross" – a row and a column that contain all stars and intersect
 * at a star. If such a cross exists, it prints "YES", otherwise "NO".
 * </p>
 */
public class Main {

    /* --------------------------------------------------------------------- */
    /*  I/O helpers                                                          */
    /* --------------------------------------------------------------------- */

    /** Fast scanner based on BufferedReader / StringTokenizer. */
    private static final class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner(InputStream inputStream) {
            this.br = new BufferedReader(new InputStreamReader(inputStream));
        }

        /** Returns next token (string). */
        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    throw new UncheckedIOException(e);
                }
            }
            return st.nextToken();
        }

        /** Convenience methods for primitive types. */
        int nextInt()   { return Integer.parseInt(next()); }
        long nextLong() { return Long.parseLong(next()); }
        double nextDouble() { return Double.parseDouble(next()); }
    }

    /** Fast printer that buffers output and flushes once at the end. */
    private static final class FastPrinter {
        private final PrintWriter pw;
        private final StringBuilder sb = new StringBuilder();

        FastPrinter(OutputStream out) {
            this.pw = new PrintWriter(new BufferedWriter(new OutputStreamWriter(out)));
        }

        /** Append a line to the internal buffer. */
        void println(String line) {
            sb.append(line).append('\n');
        }

        /** Flushes buffered output. */
        void flush() {
            pw.print(sb.toString());
            pw.flush();
        }
    }

    /* --------------------------------------------------------------------- */
    /*  Core logic                                                            */
    /* --------------------------------------------------------------------- */

    /** Holds all program logic for a single test case. */
    private static final class Solver {
        private final FastScanner in;
        private final FastPrinter out;
        private final int n, m;
        private final char[][] grid;

        Solver(FastScanner in, FastPrinter out, int n, int m) {
            this.in = in;
            this.out = out;
            this.n = n;
            this.m = m;
            this.grid = new char[n][];
        }

        /** Entry point for one test case. */
        void solve() {
            readGrid();
            locateRowAndColumnOfMaximumStars();
            validateConfiguration();
            markCrossAndCheckCompleteness();
            outputResult();
        }

        /** Reads the grid from input. */
        private void readGrid() {
            for (int i = 0; i < n; i++) {
                grid[i] = in.next().toCharArray();
            }
        }

        /** Determines the row and column that have the most stars. */
        private void locateRowAndColumnOfMaximumStars() {
            rowIdx = findRowWithMostStars();
            colIdx = findColumnWithMostStars();
        }

        /** Returns index of the row containing the most '*' characters. */
        private int findRowWithMostStars() {
            int bestIdx = -1;
            int bestCount = -1;
            for (int i = 0; i < n; i++) {
                int cnt = 0;
                for (int j = 0; j < m; j++) {
                    if (grid[i][j] == '*') cnt++;
                }
                if (cnt > bestCount) {
                    bestCount = cnt;
                    bestIdx = i;
                }
            }
            rowIdx = bestIdx;
            return bestIdx;
        }

        /** Returns index of the column containing the most '*' characters. */
        private int findColumnWithMostStars() {
            int bestIdx = -1;
            int bestCount = -1;
            for (int j = 0; j < m; j++) {
                int cnt = 0;
                for (int i = 0; i < n; i++) {
                    if (grid[i][j] == '*') cnt++;
                }
                if (cnt > bestCount) {
                    bestCount = cnt;
                    bestIdx = j;
                }
            }
            colIdx = bestIdx;
            return bestIdx;
        }

        /** Validates that a candidate intersection point is a star. */
        private boolean intersectionIsStar() {
            if (rowIdx == -1 || colIdx == -1) {
                out.println("NO");
                out.flush();
                System.exit(0);
            }
            return grid[rowIdx][colIdx] == '*';
        }

        /** Marks the entire cross and checks that each direction has at least one star. */
        private void markCrossAndCheckCompleteness() {
            if (!intersectionIsStar()) {
                out.println("NO");
                out.flush();
                System.exit(0);
            }

            // mark the intersection
            grid[rowIdx][colIdx] = '@';

            // directions: down, right, up, left
            int[] dr = {1, 0, -1, 0};
            int[] dc = {0, 1, 0, -1};

            boolean directionsOk = true;
            for (int d = 0; d < 4; d++) {
                int steps = 0;
                int r = rowIdx + dr[d];
                int c = colIdx + dc[d];
                while (inBounds(r, c)) {
                    if (grid[r][c] == '*') {
                        grid[r][c] = '@';
                        steps++;
                        r += dr[d];
                        c += dc[d];
                    } else {
                        break;
                    }
                }
                if (steps == 0) {
                    directionsOk = false;
                    break;
                }
            }

            if (!directionsOk) {
                out.println("NO");
                out.flush();
                System.exit(0);
            }

            // after clearing the cross, any remaining '*' makes the configuration invalid
            for (int i = 0; i < n && directionsOk; i++) {
                for (int j = 0; j < m; j++) {
                    if (grid[i][j] == '*') {
                        directionsOk = false;
                        break;
                    }
                }
            }

            result = directionsOk;
        }

        /** Checks whether the current cell lies inside the grid. */
        private boolean inBounds(int r, int c) {
            return r >= 0 && r < n && c >= 0 && c < m;
        }

        /** Emits the final answer ("YES" or "NO"). */
        private void outputResult() {
            out.println(result ? "YES" : "NO");
        }

        // fields used during processing
        private int rowIdx, colIdx;
        private boolean result;
    }

    /* --------------------------------------------------------------------- */
    /*  Main entry point                                                       */
    /* --------------------------------------------------------------------- */

    public static void main(String[] args) {
        FastScanner scanner = new FastScanner(System.in);
        FastPrinter printer = new FastPrinter(System.out);

        int testCases = scanner.nextInt();               // first number = number of test cases
        while (testCases-- > 0) {
            int n = scanner.nextInt();
            int m = scanner.nextInt();
            Solver solver = new Solver(scanner, printer, n, m);
            solver.solve();
        }

        printer.flush();
    }
}

/**
 * Refactored version of the original solution.
 *
 * <p>
 * The program reads a rectangular grid of characters and checks whether all
 * '*' symbols form a single cross (‑like plus sign) that completely covers the
 * grid. If the pattern is exactly one such cross, it prints {@code YES},
 * otherwise it prints {@code NO}.
 * </p>
 */
public class Solution {

    /** Represents the four orthogonal directions from a cell. */
    private enum Direction {
        UP(-1, 0), DOWN(1, 0), LEFT(0, -1), RIGHT(0, 1);

        private final int dr;
        private final int dc;

        Direction(int dr, int dc) {
            this.dr = dr;
            this.dc = dc;
        }

        int[] offset() {
            return new int[]{dr, dc};
        }
    }

    /** Fast scanner that works with any {@link InputStream}. */
    private static final class FastReader {
        private final byte[] buffer = new byte[2_048];
        private int index = 0;
        private int size = 0;
        private final InputStream in;

        FastReader(InputStream in) {
            this.in = in;
        }

        /** Reads the next byte from the underlying stream, filling the buffer if needed. */
        private int read() throws IOException {
            if (index >= size) {
                index = 0;
                size = in.read(buffer);
                if (size <= 0) {
                    return -1;
                }
            }
            return buffer[index++];
        }

        /** Skips whitespace characters. */
        private int skipNonWhite() throws IOException {
            int c;
            while ((c = read()) <= ' ') {
                if (c == -1) {
                    return -1;
                }
            }
            return c;
        }

        /** Returns the next token (not used in this program). */
        String next() throws IOException {
            int c = skipNonWhite();
            if (c == -1) {
                return "";
            }
            StringBuilder sb = new StringBuilder();
            do {
                sb.append((char) c);
                c = read();
            } while (c > ' ');
            return sb.toString();
        }

        /** Returns the next line (not used). */
        String nextLine() throws IOException {
            int c = skipNonWhite();
            StringBuilder sb = new StringBuilder();
            while (c != '\n' && c != '\r' && c != -1) {
                sb.append((char) c);
                c = read();
            }
            return sb.toString();
        }

        /** Reads the next single character, skipping whitespace. */
        char nextChar() throws IOException {
            int c = skipNonWhite();
            if (c == -1) {
                throw new EOFException();
            }
            return (char) c;
        }

        /** Reads the next integer (skipping whitespace). */
        int nextInt() throws IOException {
            int c = skipNonWhite();
            boolean negative = c == '-';
            if (c == '-' || c == '+') {
                c = read();
            }
            int value = 0;
            while (c >= '0' && c <= '9') {
                value = value * 10 + (c - '0');
                c = read();
            }
            return negative ? -value : value;
        }

        /** Reads the next double‑digit character (used for '*'). */
        char nextCharNonSpace() throws IOException {
            int c = skipNonWhite();
            if (c == -1) {
                throw new EOFException();
            }
            return (char) c;
        }
    }

    /** Entry point of the program. */
    public static void main(String[] args) throws IOException {
        FastReader reader = new FastReader(System.in);

        int rows = reader.nextInt();
        int cols = reader.nextInt();

        char[][] grid = readGrid(reader, rows, cols);
        boolean foundCross = findAndMarkCross(grid, rows, cols);

        boolean hasStar = hasAnyStar(grid, rows, cols);
        boolean allStarsInCross = allStarsAreMarked(grid, rows, cols);

        if (hasStar && foundCross && allStarsInCross) {
            System.out.println("YES");
        } else {
            System.out.println("NO");
        }
    }

    /**
     * Reads {@code rows × cols} characters from {@code reader} into a 2‑D array.
     */
    private static char[][] readGrid(FastReader reader, int rows, int cols) throws IOException {
        char[][] grid = new char[rows][cols];
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                grid[r][c] = reader.nextCharNonSpace();
            }
        }
        return grid;
    }

    /**
     * Detects the first valid cross (if any) and marks all its arms in {@code mask}.
     *
     * @return {@code true} if at least one cross is found.
     */
    private static boolean findAndMarkCross(char[][] grid, int rows, int cols) {
        boolean[][] mask = new boolean[rows][cols];
        boolean crossFound = false;

        for (int r = 1; r < rows - 1 && !crossFound; r++) {
            for (int c = 1; c < cols - 1 && !crossFound; c++) {
                if (isCenterOfPlus(grid, r, c)) {
                    markArms(grid, mask, r, c);
                    crossFound = true; // only one cross is allowed by the original logic
                }
            }
        }

        // Store the mask somewhere? For this refactor we keep it local;
        // the caller can still inspect it if needed (not required for output).
        return crossFound;
    }

    /** Checks whether (row, col) is the centre of a plus sign with at least one '*'
     *  in each of the four orthogonal directions. */
    private static boolean isCenterOfPlus(char[][] grid, int row, int col) {
        return grid[row][col] == '*' &&
                grid[row - 1][col] == '*' && // up
                grid[row + 1][col] == '*' && // down
                grid[row][col - 1] == '*' && // left
                grid[row][col + 1] == '*';   // right
    }

    /** Extends each arm of the identified plus until a non‑'*' cell is encountered,
     *  marking every visited cell in {@code mask}. */
    private static void markArms(char[][] grid, boolean[][] mask, int centerRow, int centerCol) {
        // Mark the whole vertical arm (upwards)
        for (int r = centerRow; r >= 0 && grid[r][centerCol] == '*'; r--) {
            mask[r][centerCol] = true;
        }
        // Mark the whole vertical arm (downwards)
        for (int r = centerRow; r < grid.length && grid[r][centerCol] == '*'; r++) {
            mask[r][centerCol] = true;
        }
        // Mark the whole horizontal arm (leftwards)
        for (int c = centerCol; c >= 0 && grid[centerRow][c] == '*'; c--) {
            mask[centerRow][c] = true;
        }
        // Mark the whole horizontal arm (rightwards)
        for (int c = centerCol; c < grid[0].length && grid[centerRow][c] == '*'; c++) {
            mask[centerRow][c] = true;
        }
    }

    /** Returns {@code true} if the grid contains at least one '*'. */
    private static boolean hasAnyStar(char[][] grid, int rows, int cols) {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '*') {
                    return true;
                }
            }
        }
        return false;
    }

    /** Returns {@code true} if every '*' in the grid is marked by the cross mask. */
    private static boolean allStarsAreMarked(char[][] grid, boolean[][] mask, int rows, int cols) {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '*' && !mask[r][c]) {
                    return false;
                }
            }
        }
        return true;
    }
}

import java.util.Optional;
import java.util.Scanner;

/**
 * Refactored version of the original program.
 *
 * <p>
 * The program reads a rectangular grid of characters and checks whether there is
 * exactly one «+» shaped star made of '*' characters. All '*' cells must belong
 * to that single star; otherwise the answer is {@code NO}.
 * </p>
 */
public class Main {

    /** Scanner used for reading input – kept static for simplicity. */
    private static final Scanner SCANNER = new Scanner(System.in);

    public static void main(String[] args) {
        int height = SCANNER.nextInt();
        int width  = SCANNER.nextInt();
        char[][] grid = readGrid(height);

        boolean[][] visited = new boolean[height][width];

        // Find the first '+' centre; if none is found the answer is NO.
        Optional<StarInfo> maybeCenter = findStarCenter(grid, visited);
        if (!maybeCenter.isPresent()) {
            System.out.println("NO");
            return;
        }

        // Every '*' must belong to the marked cross.
        if (!allStarsVisited(grid, visited)) {
            System.out.println("NO");
            return;
        }

        System.out.println("YES");
    }

    /** Reads {@code rows} lines from {@link Scanner} and returns the character grid. */
    private static char[][] readGrid(int rows) {
        char[][] grid = new char[rows][];
        for (int r = 0; r < rows; r++) {
            String line = SCANNER.next();
            grid[r] = line.toCharArray();
        }
        return grid;
    }

    /**
     * Looks for a '+' shaped star in the interior of {@code grid}.
     *
     * @return an {@link Optional} containing {@link StarInfo} if a centre is found,
     *         otherwise an empty {@code Optional}.
     */
    private static Optional<StarInfo> findStarCenter(char[][] grid, boolean[][] visited) {
        int rows = grid.length;
        int cols = grid[0].length;

        for (int r = 1; r < rows - 1; r++) {
            for (int c = 1; c < cols - 1; c++) {
                if (grid[r][c] == '*' && isPlusCenter(grid, r, c)) {
                    // Mark the whole cross as visited and report its centre.
                    markCross(grid, r, c, visited);
                    return Optional.of(new StarInfo(r, c));
                }
            }
        }
        return Optional.empty();
    }

    /** Returns {@code true} if the current cell has '*' neighbours on all four sides. */
    private static boolean isPlusCenter(char[][] grid, int row, int col) {
        return grid[row - 1][col] == '*' &&
               grid[row + 1][col] == '*' &&
               grid[row][col - 1] == '*' &&
               grid[row][col + 1] == '*';
    }

    /**
     * Marks the entire '+' shape (center and its four arms) as visited.
     *
     * <p>The method walks up, down, left and right from the centre while the
     * current cell contains '*', setting {@code visited[r][c] = true} for each
     * traversed cell.</p>
     */
    private static void markCross(char[][] grid, int startRow, int startCol, boolean[][] visited) {
        int rows = grid.length;
        int cols = grid[0].length;

        // Upwards
        for (int r = startRow; r >= 0 && grid[r][startCol] == '*'; r--) {
            visited[r][startCol] = true;
        }

        // Downwards
        for (int r = startRow; r < rows && grid[r][startCol] == '*'; r++) {
            visited[r][startCol] = true;
        }

        // Leftwards
        for (int c = startCol; c >= 0 && grid[startRow][c] == '*'; c--) {
            visited[startRow][c] = true;
        }

        // Rightwards
        for (int c = startCol; c < cols && grid[startRow][c] == '*'; c++) {
            visited[startRow][c] = true;
        }
    }

    /** Verifies that every '*' in the grid was visited during the cross marking. */
    private static boolean allStarsVisited(char[][] grid, boolean[][] visited) {
        for (int r = 0; r < grid.length; r++) {
            for (int c = 0; c < grid[r].length; c++) {
                if (grid[r][c] == '*' && !visited[r][c]) {
                    return false;
                }
            }
        }
        return true;
    }

    /** Simple data holder for the coordinates of a found star centre. */
    private static final class StarInfo {
        final int row;
        final int col;

        StarInfo(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }
}

import java.util.Scanner;

/**
 * Refactored implementation of the star‑path validation problem.
 * The program reads a rectangular grid, follows a vertical sequence of '*'
 * characters, then possibly a horizontal extension, and decides whether the
 * configuration satisfies the required conditions.
 */
public final class TaskB {

    /** Symbol that represents an unprocessed star. */
    private static final char STAR = '*';
    /** Symbol used to mark visited cells. */
    private static final char MARKED = 'O';
    /** Empty cell symbol. */
    private static final char EMPTY = '.';

    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            int rows = scanner.nextInt();
            int columns = scanner.nextInt();
            char[][] grid = readGrid(scanner, rows, columns);

            Coordinates start = locateFirstStar(grid, rows, columns);
            if (start == null) {
                System.out.println("NO");
                return;
            }

            Result result = process(grid, rows, columns, start);
            boolean hasStarsLeft = hasRemainingStars(grid, rows, columns);
            boolean validPath = result.isValidPath();

            System.out.println((!hasStarsLeft && validPath) ? "YES" : "NO");
        }
    }

    /** Reads the grid from the scanner. */
    private static char[][] readGrid(Scanner scanner, int rows, int columns) {
        char[][] grid = new char[rows][columns];
        for (int i = 0; i < rows; ++i) {
            String line = scanner.next();
            for (int j = 0; j < columns; ++j) {
                grid[i][j] = line.charAt(j);
            }
        }
        return grid;
    }

    /** Finds the coordinates of the first '*' in the grid. */
    private static Coordinates locateFirstStar(char[][] grid, int rows, int columns) {
        for (int i = 0; i < rows; ++i) {
            for (int j = 0; j < columns; ++j) {
                if (grid[i][j] == STAR) {
                    return new Coordinates(i, j);
                }
            }
        }
        return null; // should never happen under normal problem constraints
    }

    /** Returns {@code true} if at least one '*' remains in the grid. */
    private static boolean hasRemainingStars(char[][] grid, int rows, int columns) {
        for (int i = 0; i < rows; ++i) {
            for (int j = 0; j < columns; ++j) {
                if (grid[i][j] == STAR) {
                    return true;
                }
            }
        }
        return false;
    }

    /**
     * Executes the core algorithm:
     *   1. Walks downwards over consecutive '*' cells, marking them.
     *   2. When a branching condition is met, walks horizontally until an
     *      empty cell is reached, also marking visited cells.
     * Returns a {@link Result} containing the counts of visited steps.
     */
    private static Result process(char[][] grid, int rows, int columns, Coordinates start) {
        int verticalCount = 0;
        int horizontalCount = 0;
        int startRow = -1; // row where the horizontal sweep begins
        int col = 0;       // current column during horizontal sweep

        int i = start.row();
        int j = start.column();

        while (i < rows && grid[i][j] == STAR) {
            grid[i][j] = MARKED;
            ++verticalCount;

            // Potential start of a horizontal sweep: check neighbour condition.
            if (startRow == -1 && j > 0 && j + 1 < columns &&
                    grid[i][j - 1] == STAR && grid[i][j + 1] == STAR) {
                if (!isPathBlockedBelow(grid, i, j)) {
                    startRow = i; // remember the row for horizontal walk
                    col = 0;      // start from the first column
                }
            }
            ++i;
        }

        // Horizontal expansion from (startRow, col)
        while (col < columns) {
            if (grid[startRow][col] == STAR || grid[startRow][col] == MARKED) {
                grid[startRow][col] = MARKED;
                ++horizontalCount;
            }
            // Stop after we have marked at least one cell and encounter an empty one.
            if (horizontalCount > 0 && grid[startRow][col] == EMPTY) {
                break;
            }
            ++col;
        }

        return new Result(verticalCount, horizontalCount);
    }

    /** Checks whether a cell either below or above the given position is empty. */
    private static boolean isPathBlockedBelow(char[][] grid, int row, int column) {
        return (row + 1 < grid.length && grid[row + 1][column] == EMPTY) ||
               (row - 1 >= 0 && grid[row - 1][column] == EMPTY);
    }

    /** Encapsulates intermediate counts produced by {@link #process}. */
    private static final class Result {
        private final int verticalCount;
        private final int horizontalCount;

        Result(int verticalCount, int horizontalCount) {
            this.verticalCount = verticalCount;
            this.horizontalCount = horizontalCount;
        }

        int verticalCount() {
            return verticalCount;
        }

        int horizontalCount() {
            return horizontalCount;
        }

        /** The path is considered valid only if both counts are positive. */
        boolean isValidPath() {
            return verticalCount > 0 && horizontalCount > 0;
        }
    }

    /** Simple container for row/column coordinates. */
    private static final class Coordinates {
        final int row;
        final int column;

        Coordinates(int row, int column) {
            this.row = row;
            this.column = column;
        }
    }
}

import java.util.Scanner;

/**
 * Garden analyzer – determines whether a garden can be completely cleared
 * by removing a single tree that is surrounded on all four orthogonal sides.
 *
 * <p>Refactoring goals:
 * <ul>
 *   <li>Clear separation of concerns (input, processing, output)</li>
 *   <li>Descriptive naming and constants</li>
 *   <li>Small, focused methods</li>
 *   <li>Self‑documenting code with minimal magic numbers</li>
 * </ul>
 */
public class GardenAnalyzer {

    /** Symbol for an empty cell (no tree). */
    private static final int EMPTY = 0;

    /** Symbol for a tree. */
    private static final int TREE = 1;

    /** Directions used to check the four orthogonal neighbours. */
    private static final int[][] NEIGHBOURS = {
            { -1, 0 },  // up
            { 1, 0 },   // down
            { 0, -1 },  // left
            { 0, 1 }    // right
    };

    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            int height = scanner.nextInt();
            int width  = scanner.nextInt();

            // Read the garden layout
            char[][] rawLayout = readGardenLayout(scanner, height);

            // Convert the character layout to an integer grid (0 = empty, 1 = tree)
            int[][] grid = buildGrid(rawLayout);

            // Try to find a tree that is completely surrounded on all four sides
            boolean foundSurrounded = false;
            for (int row = 1; row < height; row++) {
                for (int col = 1; col < width; col++) {
                    if (grid[row][col] == TREE &&
                        isFullySurrounded(grid, row, col)) {
                        // Remove the tree – this represents “cutting it down”
                        grid[row][col] = EMPTY;
                        foundSurrounded = true;
                        break;
                    }
                }
                if (foundSurrounded) {
                    break;
                }
            }

            // After the possible removal, check whether any trees remain
            boolean anyTreeLeft = containsAnyTree(grid);

            System.out.println(anyTreeLeft ? "NO" : "YES");
        }
    }

    /**
     * Reads the garden rows from {@code scanner}.
     *
     * @param scanner  Scanner reading from {@code System.in}
     * @param height   Number of rows to read
     * @return array containing each row as a character array
     */
    private static char[][] readGardenLayout(Scanner scanner, int height) {
        char[][] layout = new char[height];
        for (int i = 0; i < height; i++) {
            layout[i] = scanner.next().toCharArray();
        }
        return layout;
    }

    /**
     * Builds an integer grid from the character representation.
     *
     * @param rawLayout character grid where '.' denotes an empty cell and any
     *                  other character denotes a tree
     * @return integer grid using {@link #EMPTY} and {@link #TREE}
     */
    private static int[][] buildGrid(char[][] rawLayout) {
        int height = rawLayout.length;
        int width  = rawLayout[0].length;
        int[][] grid = new int[height + 2][width + 2]; // padded with a border of EMPTY

        for (int r = 1; r <= height; r++) {
            for (int c = 1; c <= width; c++) {
                grid[r][c] = (rawLayout[r - 1][c - 1] == '.') ? EMPTY : TREE;
            }
        }
        return grid;
    }

    /**
     * Checks whether a cell is surrounded on all four orthogonal neighbours
     * by trees.
     *
     * @param grid  integer grid representation of the garden
     * @param row   row index (1‑based inside the padded grid)
     * @param col   column index (1‑based inside the padded grid)
     * @return {@code true} if all four neighbours contain a tree
     */
    private static boolean isFullySurrounded(int[][] grid, int row, int col) {
        for (int[] dir : NEIGHBOURS) {
            int neighbourRow = row + dir[0];
            int neighbourCol = col + dir[1];
            if (grid[neighbourRow][neighbourCol] != TREE) {
                return false;
            }
        }
        return true;
    }

    /**
     * Scans the whole grid to see if any tree remains.
     *
     * @param grid integer grid to inspect
     * @return {@code true} if at least one tree is present
     */
    private static boolean containsAnyTree(int[][] grid) {
        for (int[] row : grid) {
            for (int cell : row) {
                if (cell == TREE) {
                    return true;
                }
            }
        }
        return false;
    }
}

import java.util.Scanner;

/**
 * Reads a rectangular grid of characters and checks whether it contains exactly
 * one plus‑shaped arrangement of '*' characters.  All '*' cells must belong to
 * that plus for the answer to be "YES".
 */
public class PlusValidator {

    /** Grid that contains the input '*' cells. */
    private static boolean[][] starGrid;

    /** Grid that marks cells belonging to the detected plus. */
    private static boolean[][] visited;

    public static void main(String[] args) {
        /* Try‑with‑resources ensures the scanner is closed immediately. */
        try (Scanner scanner = new Scanner(System.in)) {
            int height = scanner.nextInt();
            int width = scanner.nextInt();

            initializeStarGrid(height, width, scanner);

            int[] center = locatePlusCenter();
            if (center == null) {                     // no valid plus found
                System.out.println("NO");
                return;
            }

            markPlus(center[0], center[1]);           // mark the whole plus

            if (allStarsAreVisited()) {
                System.out.println("YES");
            } else {
                System.out.println("NO");
            }
        }
    }

    /** Reads the grid from {@code scanner} and stores it in {@code starGrid}. */
    private static void initializeStarGrid(int height, int width, Scanner scanner) {
        starGrid = new boolean[height][width];
        for (int i = 0; i < height; i++) {
            String line = scanner.next();
            for (int j = 0; j < width; j++) {
                starGrid[i][j] = (line.charAt(j) == '*');
            }
        }
    }

    /** Returns the coordinates of the first cell that could be a plus centre,
     *  or {@code null} if none exists. */
    private static int[] locatePlusCenter() {
        for (int i = 0; i < starGrid.length; i++) {
            for (int j = 0; j < starGrid[i].length; j++) {
                if (isPotentialPlusCenter(i, j)) {
                    return new int[]{i, j};
                }
            }
        }
        return null;
    }

    /** Checks the four orthogonal neighbours of (i,j) for at least one '*'. */
    private static boolean isPotentialPlusCenter(int i, int j) {
        return starGrid[i][j]
                && hasStarAbove(i, j)
                && hasStarBelow(i, j)
                && hasStarLeft(i, j)
                && hasStarRight(i, j);
    }

    private static boolean hasStarAbove(int i, int j) {
        return i > 0 && starGrid[i - 1][j];
    }

    private static boolean hasStarBelow(int i, int j) {
        return i < starGrid.length - 1 && starGrid[i + 1][j];
    }

    private static boolean hasStarLeft(int i, int j) {
        return j > 0 && starGrid[i][j - 1];
    }

    private static boolean hasStarRight(int i, int j) {
        return j < starGrid[i].length - 1 && starGrid[i][j + 1];
    }

    /** Marks every contiguous '*' cell in the four directions starting from (i,j). */
    private static void markPlus(int centreI, int centreJ) {
        markDirection(centreI, centreJ, -1, 0); // up
        markDirection(centreI, centreJ, 1, 0);  // down
        markDirection(centreI, centreJ, 0, -1); // left
        markDirection(centreI, centreJ, 0, 1);  // right
    }

    /** Marks cells while moving in the supplied direction until a non‑'*' cell
     *  or the grid border is reached. */
    private static void markDirection(int i, int j, int di, int dj) {
        while (withinBounds(i, j) && starGrid[i][j]) {
            visited[i][j] = true;
            i += di;
            j += dj;
        }
    }

    private static boolean withinBounds(int i, int j) {
        return i >= 0 && i < starGrid.length && j >= 0 && j < starGrid[i].length;
    }

    /** Returns {@code true} iff every '*' in the original grid has been visited. */
    private static boolean allStarsAreVisited() {
        for (int i = 0; i < starGrid.length; i++) {
            for (int j = 0; j < starGrid[i].length; j++) {
                if (starGrid[i][j] && !visited[i][j]) {
                    return false;   // a star lies outside the discovered plus
                }
            }
        }
        return true;
    }
}

// ─────────────────────────────────────────────────────────────────────────────
//  Refactored solution – more readable, well‑structured and easier to maintain
// ─────────────────────────────────────────────────────────────────────────────
import java.io.*;
import java.util.*;

public class Main {

    /* --------------------------------------------------------------
     *  Fast input reader – kept compatible with the original implementation
     *  -------------------------------------------------------------- */
    private static final class FastReader {
        private final BufferedReader br;
        private StringTokenizer st;

        FastReader() {
            this.br = new BufferedReader(new InputStreamReader(System.in));
        }

        /** Makes sure a non‑empty tokenizer exists (handles EOF gracefully). */
        private void ensureTokenizer() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                st = new StringTokenizer(br.readLine());
            }
        }

        String next() {
            ensureTokenizer();
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        long nextLong() {
            return Long.parseLong(next());
        }

        double nextDouble() {
            return Double.parseDouble(next());
        }

        char nextChar() {
            return next().charAt(0);
        }

        String nextLine() {
            String line = "";
            try {
                line = br.readLine();
            } catch (IOException e) {
                e.printStackTrace();
            }
            return line;
        }

        /** Convenience – read an int[] of length n. */
        int[] nextIntArray(int n) {
            int[] arr = new int[n];
            for (int i = 0; i < n; i++) {
                arr[i] = nextInt();
            }
            return arr;
        }
    }

    /* --------------------------------------------------------------
     *  Core solving logic
     *  -------------------------------------------------------------- */
    private static void solve(FastReader in, StringBuilder out) {
        int n = in.nextInt();                 // rows
        int m = in.nextInt();                 // columns
        char[][] grid = readGrid(in, n, m);    // input grid

        boolean[][] visited = new boolean[n][m];
        boolean foundPlus = false;            // did we locate a '+' shape?

        // 1️⃣  Search for a '+' – a '*' surrounded by four orthogonal '*'
        outer:
        for (int i = 1; i < n - 1; i++) {
            for (int j = 1; j < m - 1; j++) {
                if (grid[i][j] == '*' &&
                    grid[i - 1][j] == '*' &&
                    grid[i + 1][j] == '*' &&
                    grid[i][j - 1] == '*' &&
                    grid[i][j + 1] == '*') {

                    markCross(grid, visited, i, j);
                    foundPlus = true;
                    break outer;               // only one such centre per test case
                }
            }
        }

        // 2️⃣  Ensure every '*' in the original picture is part of the marked cross
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i][j] == '*' && !visited[i][j]) {
                    out.append("NO").append('\n');
                    return;
                }
            }
        }

        // 3️⃣  Emit final verdict
        out.append(foundPlus ? "YES" : "NO").append('\n');
    }

    /** Reads the n×m character grid from the input stream. */
    private static char[][] readGrid(FastReader in, int n, int m) {
        char[][] grid = new char[n][m];
        for (int i = 0; i < n; i++) {
            String row = in.next();
            for (int j = 0; j < m; j++) {
                grid[i][j] = row.charAt(j);
            }
        }
        return grid;
    }

    /** Marks the whole vertical and horizontal line of '*' belonging to the found '+'. */
    private static void markCross(char[][] grid, boolean[][] visited, int centerRow, int centerCol) {
        // up
        for (int r = centerRow; r >= 0 && grid[r][centerCol] == '*'; r--) {
            visited[r][centerCol] = true;
        }
        // down
        for (int r = centerRow; r < grid.length && grid[r][centerCol] == '*'; r++) {
            visited[r][centerCol] = true;
        }
        // left
        for (int c = centerCol; c >= 0 && grid[centerRow][c] == '*'; c--) {
            visited[centerRow][c] = true;
        }
        // right
        for (int c = centerCol; c < grid[0].length && grid[centerRow][c] == '*'; c++) {
            visited[centerRow][c] = true;
        }
    }

    /* --------------------------------------------------------------
     *  Entry point – keeps the optional multiple‑test‑case toggle
     *  -------------------------------------------------------------- */
    public static void main(String[] args) throws IOException {
        FastReader scanner = new FastReader();
        StringBuilder output = new StringBuilder();

        // Change to true if the judge provides several test cases
        boolean multipleTestCases = false;
        if (multipleTestCases) {
            int t = scanner.nextInt();
            while (t-- > 0) {
                solve(scanner, output);
            }
        } else {
            solve(scanner, output);
        }

        System.out.print(output.toString());
    }
}

import java.io.BufferedWriter;
import java.io.OutputStreamWriter;
import java.util.Scanner;

/**
 * Program that determines whether a given grid consists solely of a single '+' shape
 * made of asterisks ('*') and nothing else.
 *
 * <p>Refactored for readability, maintainability and resource safety.
 */
public class PlusFromPicture {

    /** Character used to draw the pattern. */
    private static final char STAR = '*';

    /** Directions used to expand the plus once its centre is found. */
    private static final int[] UP_STEP    = {-1,  0};
    private static final int[] DOWN_STEP  = { 1,  0};
    private static final int[] LEFT_STEP  = { 0, -1};
    private static final int[] RIGHT_STEP = { 0,  1};

    public static void main(String[] args) {
        // Try‑with‑resources guarantees that the Scanner is closed automatically.
        try (Scanner scanner = new Scanner(System.in)) {
            // Read grid dimensions.
            int height = scanner.nextInt();
            int width  = scanner.nextInt();

            // Allocate and fill the grid.
            char[][] grid = readGrid(scanner, height);

            // Determine whether a single plus covers all asterisks.
            if (containsOnlyOnePlus(grid)) {
                System.out.println("YES");
            } else {
                System.out.println("NO");
            }
        }
    }

    /**
     * Reads the remaining {@code height} lines of input and stores them in a 2‑D array.
     */
    private static char[][] readGrid(Scanner scanner, int height) {
        char[][] grid = new char[height][];
        for (int row = 0; row < height; row++) {
            String line = scanner.next();
            grid[row] = line.toCharArray();
        }
        return grid;
    }

    /**
     * Checks whether the grid consists of exactly one plus sign built from asterisks.
     *
     * @return {@code true} if such a plus exists and all asterisks belong to it,
     *         {@code false} otherwise.
     */
    private static boolean containsOnlyOnePlus(char[][] grid) {
        int rows = grid.length;
        int cols = grid[0].length;

        // Potentially find a plus centred at each interior cell.
        for (int centreRow = 1; centreRow < rows - 1; centreRow++) {
            for (int centreCol = 1; centreCol < cols - 1; centreCol++) {
                if (isPlusCentre(grid, centreRow, centreCol)) {
                    boolean[][] visited = markWholePlus(grid, centreRow, centreCol);
                    // After marking, ensure every asterisk in the grid was visited.
                    return areAllStarsVisited(grid, visited);
                }
            }
        }
        // No valid plus centre found.
        return false;
    }

    /**
     * Determines whether a given cell together with its four orthogonal neighbours
     * forms the centre of a plus.
     */
    private static boolean isPlusCentre(char[][] grid, int row, int col) {
        return grid[row][col] == STAR &&
               grid[row - 1][col] == STAR &&   // up
               grid[row + 1][col] == STAR &&   // down
               grid[row][col - 1] == STAR &&   // left
               grid[row][col + 1] == STAR;     // right
    }

    /**
     * Expands upward, downward, leftward and rightward from the centre,
     * marking every asterisk belonging to that plus.
     *
     * @return a boolean matrix where {@code true} indicates a cell covered by the plus.
     */
    private static boolean[][] markWholePlus(char[][] grid, int centreRow, int centreCol) {
        int rows = grid.length;
        int cols = grid[0].length;
        boolean[][] visited = new boolean[rows][cols];

        // Upward expansion.
        for (int r = centreRow; r >= 0 && grid[r][centreCol] == STAR; r--) {
            visited[r][centreCol] = true;
        }
        // Downward expansion.
        for (int r = centreRow; r < rows && grid[r][centreCol] == STAR; r++) {
            visited[r][centreCol] = true;
        }
        // Leftward expansion.
        for (int c = centreCol; c >= 0 && grid[centreRow][c] == STAR; c--) {
            visited[centreRow][c] = true;
        }
        // Rightward expansion.
        for (int c = centreCol; c < cols && grid[centreRow][c] == STAR; c++) {
            visited[centreRow][c] = true;
        }

        return visited;
    }

    /**
     * Verifies that every asterisk in the original grid is marked by the plus‑marking
     * routine. Returns {@code true} if this condition holds.
     */
    private static boolean areAllStarsVisited(char[][] grid, boolean[][] visited) {
        int rows = grid.length;
        int cols = grid[0].length;

        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == STAR && !visited[r][c]) {
                    return false;   // Found an asterisk not covered by the plus.
                }
            }
        }
        return true;   // All asterisks belong to the single plus.
    }
}

import java.util.Scanner;

/**
 * Reads a rectangular board made of '.' and '1' characters.
 * It checks whether there exists a plus‑shaped group of mines
 * ('1') whose total size matches the number of mines found on the board.
 *
 * A plus‑shape means a central cell with at least one adjacent mine
 * in each of the four orthogonal directions; the whole stretch
 * (including the centre) must contain exactly {@code expectedMineCount}
 * mines.
 */
public class MineRefactor {

    public static void main(String[] args) {
        // Try‑with‑resources guarantees that the scanner is closed automatically.
        try (Scanner scanner = new Scanner(System.in)) {

            /* ------------ 1️⃣  Read dimensions and board ------------------- */
            int height = scanner.nextInt();          // number of rows
            int width  = scanner.nextInt();          // number of columns
            scanner.nextLine();                      // skip end‑of‑line after the two ints

            char[][] board = new char[height][];
            int mineCount = 0;

            for (int row = 0; row < height; row++) {
                String line = scanner.nextLine();    // one board row
                board[row] = line.toCharArray();

                for (int col = 0; col < width; col++) {
                    if (board[row][col] == '1') {
                        mineCount++;                 // count mines while parsing
                    }
                }
            }

            /* ------------ 2️⃣  Analyse the board -------------------------- */
            boolean result = hasFullCrossOfMines(board, height, width, mineCount);

            /* ------------ 3️⃣  Output the decision ------------------------ */
            System.out.println(result ? "YES" : "NO");
        }
    }

    /**
     * Returns {@code true} if the board contains **any** plus‑shaped
     * sequence of mines whose length equals {@code expectedMineCount}.
     *
     * @param board           2‑D char representation of the board
     * @param height          number of rows
     * @param width           number of columns
     * @param expectedMineCount total number of mines read from input
     * @return {@code true} if such a cross exists, otherwise {@code false}
     */
    private static boolean hasFullCrossOfMines(char[][] board,
                                               int height,
                                               int width,
                                               int expectedMineCount) {
        // A plus‑shape cannot exist if we do not have mines at all.
        if (expectedMineCount == 0) {
            return false;
        }

        // Scan the interior of the board – the centre of a cross must have
        // at least one cell in each direction.
        for (int row = 1; row < height - 1; row++) {
            for (int col = 1; col < width - 1; col++) {
                if (isPotentialCrossCenter(board, row, col)) {
                    int totalInCross = countMinesInCross(board, row, col);
                    if (totalInCross == expectedMineCount) {
                        return true;                  // found a matching configuration
                    }
                }
            }
        }
        return false;                               // no matching cross found
    }

    /**
     * Checks whether the cell at {@code (row, col)} can serve as the centre
     * of a plus‑shape.  Only the centre cell itself is examined here;
     * the surrounding cells are validated later in {@link #countMinesInCross}.
     */
    private static boolean isPotentialCrossCenter(char[][] board, int row, int col) {
        return board[row][col] == '1';
    }

    /**
     * Starting from a cell that is already known to be a mine,
     * count the consecutive mines extending in all four orthogonal
     * directions (up, down, left, right).  The centre cell itself is
     * counted once; the result is the total number of mines that form
     * the cross.
     *
     * @return number of mines belonging to the cross centred at {@code (row, col)}
     */
    private static int countMinesInCross(char[][] board, int centreRow, int centreCol) {
        final char MINE = '1';
        int total = 1; // count the centre cell

        // Upward direction
        for (int r = centreRow - 1; r >= 0 && board[r][centreCol] == MINE; r++) {
            total++;
        }

        // Downward direction
        for (int r = centreRow + 1; r < board.length && board[r][centreCol] == MINE; r++) {
            total++;
        }

        // Left direction
        for (int c = centreCol - 1; c >= 0 && board[centreRow][c] == MINE; c--) {
            total++;
        }

        // Right direction
        for (int c = centreCol + 1; c < board[0].length && board[centreRow][c] == MINE; c++) {
            total++;
        }

        return total;
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.ArrayDeque;
import java.util.Deque;
import java.util.StringTokenizer;

/**
 * Reads a rectangular grid of characters and checks whether there exists a
 * “cross” made of asterisks whose centre cell can be turned into a centre of
 * a plus sign that can be completely removed. If after removing all cells of
 * such a cross the grid contains no remaining '*', the answer is {@code YES};
 * otherwise {@code NO}.
 *
 * The program is deliberately split into small, purpose‑focused methods to
 * improve readability, testability and future extensibility.
 */
public final class MinesweeperDetector {

    /** Directions used for scanning the four orthogonal arms of a cross. */
    private enum Direction {
        UP(-1, 0), DOWN(1, 0), LEFT(0, -1), RIGHT(0, 1);

        private final int dr;
        private final int dc;

        Direction(int dr, int dc) {
            this.dr = dr;
            this.dc = dc;
        }

        int getDeltaRow() { return dr; }
        int getDeltaCol() { return dc; }
    }

    private static final BufferedReader IN = new BufferedReader(
            new InputStreamReader(System.in));

    public static void main(String[] args) throws IOException {
        Grid grid = readGrid();

        Optional<Cross> maybeCross = findCenterCross(grid);
        if (!maybeCross.isPresent()) {
            System.out.println("NO");
            return;
        }

        removeCross(grid, maybeCross.get());
        boolean anyStarLeft = grid.hasRemainingStars();

        System.out.println(anyStarLeft ? "NO" : "YES");
    }

    /** --------------------------------------------------------------------- *
     *  Input handling
     *  --------------------------------------------------------------------- */
    private static Grid readGrid() throws IOException {
        StringTokenizer tokenizer = new StringTokenizer(IN.readLine());
        int rows = Integer.parseInt(tokenizer.nextToken());
        int cols = Integer.parseInt(tokenizer.nextToken());

        char[][] matrix = new char[rows][cols];
        for (int r = 0; r < rows; r++) {
            String line = IN.readLine();
            // Defensive: accept shorter lines by padding with spaces.
            for (int c = 0; c < cols; c++) {
                matrix[r][c] = line.charAt(c);
            }
        }
        return new Grid(matrix);
    }

    /** --------------------------------------------------------------------- *
     *  Searches for the unique centre of a cross that satisfies the original
     *  problem’s condition.
     *  --------------------------------------------------------------------- */
    private static Optional<Cross> findCenterCross(Grid grid) {
        for (int r = 1; r < grid.rows - 1; r++) {
            for (int c = 1; c < grid.cols - 1; c++) {
                if (starAt(grid, r, c)
                        && starAt(grid, r - 1, c)
                        && starAt(grid, r + 1, c)
                        && starAt(grid, r, c - 1)
                        && starAt(grid, r, c + 1)) {

                    return Optional.of(new Cross(r, c));
                }
            }
        }
        return Optional.empty();
    }

    /** --------------------------------------------------------------------- *
     *  Utility: checks whether a cell contains '*'
     *  --------------------------------------------------------------------- */
    private static boolean starAt(Grid grid, int r, int c) {
        return grid.cell(r, c) == '*';
    }

    /** --------------------------------------------------------------------- *
     *  Removes all cells belonging to the four arms of the detected cross.
     *  The removal process mirrors the original while‑loops.
     *  --------------------------------------------------------------------- */
    private static void removeCross(Grid grid, Cross cross) {
        Direction[] dirs = Direction.values();

        for (Direction dir : dirs) {
            moveAndClear(grid, cross.centerRow(), cross.centerCol(), dir);
        }
        // finally clear the centre itself
        grid.clear(cross.centerRow(), cross.centerCol());
    }

    /** Walks along a single direction, clearing consecutive '*' cells. */
    private static void moveAndClear(Grid grid,
                                     int startRow, int startCol,
                                     Direction dir) {
        int r = startRow + dir.getDeltaRow();
        int c = startCol + dir.getDeltaCol();

        while (grid.inBounds(r, c) && grid.starAt(r, c)) {
            grid.clear(r, c);
            r += dir.getDeltaRow();
            c += dir.getDeltaCol();
        }
    }

    /** --------------------------------------------------------------------- *
     *  Small helper class that stores the coordinates of a found centre.
     *  --------------------------------------------------------------------- */
    private static final class Cross {
        final int centerRow;
        final int centerCol;

        Cross(int row, int col) {
            this.centerRow = row;
            this.centerCol = col;
        }
    }

    /** --------------------------------------------------------------------- *
     *  Encapsulates the whole board and provides a clean API for queries.
     *  --------------------------------------------------------------------- */
    private static final class Grid {
        private final char[][] board;
        private final int rows;
        private final int cols;

        Grid(char[][] board) {
            this.board = board;
            this.rows = board.length;
            this.cols = board[0].length;
        }

        int rows() { return rows; }
        int cols() { return cols; }

        /** Returns the character at (r,c) if inside bounds, otherwise space. */
        char cell(int r, int c) {
            return inBounds(r, c) ? board[r][c] : ' ';
        }

        boolean starAt(int r, int c) {
            return cell(r, c) == '*';
        }

        boolean inBounds(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }

        /** Clears a cell (sets it to '.'). */
        void clear(int r, int c) {
            if (inBounds(r, c)) {
                board[r][c] = '.';
            }
        }

        /** Checks whether any '*' remains in the whole grid. */
        boolean hasRemainingStars() {
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (board[r][c] == '*') {
                        return true;
                    }
                }
            }
            return false;
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.Scanner;

/**
 * Solution – refactored version of the original program.
 *
 * <p>
 * The program reads a grid of characters ('*' or '.'), looks for a single
 * “cross” made of '*' characters, removes the whole cross (including all
 * continuations of the arms), and prints {@code YES} if no '*' remain after
 * the removal, otherwise {@code NO}.
 * </p>
 */
public class Solution {

    /** Symbol that marks a painted cell. */
    private static final char STAR = '*';
    /** Symbol that marks an empty cell. */
    private static final char EMPTY = '.';

    public static void main(String[] args) throws IOException {
        /* Try‑with‑resources guarantees proper closure of all I/O streams. */
        try (Scanner scanner = new Scanner(System.in);
             BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
             PrintWriter out = new PrintWriter(System.out)) {

            int height = scanner.nextInt();
            int width  = scanner.nextInt();

            /* Grids smaller than 3×3 can never contain a valid cross. */
            if (height < 3 || width < 3) {
                out.println("NO");
                return;
            }

            char[][] grid = readGrid(scanner, height);
            boolean allRemoved = canRemoveFullCross(grid);
            out.println(allRemoved ? "YES" : "NO");
        }
    }

    /**
     * Reads {@code rows} lines from {@code scanner} and returns a 2‑D character
     * array representing the grid.
     */
    private static char[][] readGrid(Scanner scanner, int rows) throws IOException {
        scanner.nextLine();               // consume leftover newline
        char[][] grid = new char[rows][];
        for (int i = 0; i < rows; i++) {
            String line = scanner.nextLine();
            grid[i] = line.toCharArray();
        }
        return grid;
    }

    /**
     * Returns {@code true} if the grid can be completely cleared by removing
     * exactly one cross, otherwise {@code false}.
     */
    private static boolean canRemoveFullCross(char[][] grid) {
        int rows = grid.length;
        int cols = grid[0].length;

        for (int i = 1; i < rows - 1; i++) {
            for (int j = 1; j < cols - 1; j++) {
                if (isCrossCenter(grid, i, j)) {
                    clearCross(grid, i, j);
                    return noStarsRemain(grid);
                }
            }
        }
        return false;   // no cross was found that satisfies the conditions
    }

    /** Checks whether (i, j) is the centre of a cross formed by '*'. */
    private static boolean isCrossCenter(char[][] g, int i, int j) {
        return g[i][j] == STAR &&
               g[i - 1][j] == STAR &&
               g[i + 1][j] == STAR &&
               g[i][j - 1] == STAR &&
               g[i][j + 1] == STAR;
    }

    /**
     * Removes the whole cross whose centre is (i, j). The centre cell and the
     * centre of each arm are marked as {@code EMPTY}. The method walks
     * outward along the four orthogonal directions, clearing any consecutive
     * '*' characters.
     */
    private static void clearCross(char[][] g, int centreI, int centreJ) {
        int rows = g.length;
        int cols = g[0].length;

        /* Upward arm */
        int k = centreI;
        while (k > 0 && g[k - 1][centreJ] == STAR) {
            g[k - 1][centreJ] = EMPTY;
            k--;
        }

        /* Downward arm */
        k = centreI;
        while (k + 1 < rows && g[k + 1][centreJ] == STAR) {
            g[k + 1][centreJ] = EMPTY;
            k++;
        }

        /* Left arm */
        k = centreJ;
        while (k > 0 && g[centreI][k - 1] == STAR) {
            g[centreI][k - 1] = EMPTY;
            k--;
        }

        /* Right arm */
        k = centreJ;
        while (k + 1 < cols && g[centreI][k + 1] == STAR) {
            g[centreI][k + 1] = EMPTY;
            k++;
        }
    }

    /** Returns {@code true} only if no '*' characters are left in the grid. */
    private static boolean noStarsRemain(char[][] g) {
        for (char[] row : g) {
            for (char cell : row) {
                if (cell == STAR) {
                    return false;
                }
            }
        }
        return true;
    }
}

import java.io.IOException;
import java.util.Arrays;

/**
 * Reads a grid of characters, determines the largest area that can be
 * covered by a k×k square that contains only the letter 'B' on its border,
 * and prints the result together with the number of completely empty rows
 * and columns.
 *
 * The implementation is deliberately split into small, self‑documenting
 * methods and uses meaningful names instead of cryptic one‑letter variables.
 */
public class GridCoverage {

    /** Sentinel value used to mark “empty” rows / columns. */
    private static final int EMPTY = Integer.MAX_VALUE;

    /** Fast I/O helper –‑ compact but fully documented. */
    private static final class FastReader {
        private final byte[] buffer = new byte[4_096];
        private int index = 0, size = 0;
        private final java.io.InputStream stream;

        FastReader(java.io.InputStream stream) {
            this.stream = stream;
        }

        private int readByte() throws IOException {
            if (index >= size) {
                index = 0;
                size = stream.read(buffer);
                if (size <= 0) {
                    return -1;
                }
            }
            return buffer[index++];
        }

        /** Reads the next token (delimited by whitespace). */
        String next() throws IOException {
            int c;
            do { c = readByte(); } while (c <= ' ');
            StringBuilder sb = new StringBuilder();
            do { sb.append((char) c); } while ((c = readByte()) > ' ');
            return sb.toString();
        }

        /** Reads the next line (including possible empty lines). */
        String nextLine() throws IOException {
            int c;
            do { c = readByte(); } while (c <= ' ');
            StringBuilder sb = new StringBuilder();
            do {
                sb.append((char) c);
                c = readByte();
            } while (c != '\n' && c != '\r' && c != -1);
            return sb.toString();
        }

        /** Returns the next character, skipping whitespace. */
        char nextChar() throws IOException {
            int c;
            do { c = readByte(); } while (c <= ' ');
            return (char) c;
        }

        /** Parses the next integer (optionally signed). */
        int nextInt() throws IOException {
            int sign = 1, c;
            do { c = readByte(); } while (c <= ' ');
            if (c == '-') { sign = -1; c = readByte(); }
            else if (c == '+') { c = readByte(); }
            int value = 0;
            while (c >= '0' && c <= '9') {
                value = value * 10 + (c - '0');
                c = readByte();
            }
            return sign * value;
        }

        /** Parses the next long integer. */
        long nextLong() throws IOException {
            int sign = 1, c;
            do { c = readByte(); } while (c <= ' ');
            if (c == '-') { sign = -1; c = readByte(); }
            else if (c == '+') { c = readByte(); }
            long value = 0;
            while (c >= '0' && c <= '9') {
                value = value * 10 + (c - '0');
                c = readByte();
            }
            return sign * value;
        }
    }

    /** Determines the leftmost / rightmost column that contains a 'B' for each row. */
    private static void fillRowBounds(String[] grid, int n, int[][] rowBounds) {
        Arrays.fill(rowBounds, new int[]{EMPTY, -1});
        for (int r = 0; r < n; r++) {
            for (int c = 0; c < n; c++) {
                if (grid[r].charAt(c) == 'B') {
                    rowBounds[r][0] = Math.min(rowBounds[r][0], c);
                    rowBounds[r][1] = Math.max(rowBounds[r][1], c);
                }
            }
        }
    }

    /** Determines the topmost / bottommost row that contains a 'B' for each column. */
    private static void fillColumnBounds(char[][] board, int n, int[][] colBounds) {
        Arrays.fill(colBounds, new int[]{EMPTY, -1});
        for (int c = 0; c < n; c++) {
            for (int r = 0; r < n; r++) {
                if (board[r][c]) {
                    colBounds[c][0] = Math.min(colBounds[c][0], r);
                    colBounds[c][1] = Math.max(colBounds[c][1], r);
                }
            }
        }
    }

    /** Checks whether the interval [row…row+k‑1] fits completely inside the column window [col, col+k‑1]. */
    private static boolean rowIntervalFits(int rowStart, int colStart, int k,
                                            int[][] rowBounds) {
        if (rowBounds[rowStart][0] == EMPTY) {               // empty row
            return false;
        }
        int left  = rowBounds[rowStart][0];
        int right = rowBounds[rowStart][1];
        return left >= colStart && right <= colStart + k - 1;
    }

    /** Checks whether the interval [col…col+k‑1] fits completely inside the row window [row, row+k‑1]. */
    private static boolean colIntervalFits(int colStart, int rowStart, int k,
                                           int[][] colBounds) {
        if (colBounds[colStart][0] == EMPTY) {               // empty column
            return false;
        }
        int top = colBounds[colStart][0];
        int bottom = colBounds[colStart][1];
        return top >= rowStart && bottom <= rowStart + k - 1;
    }

    /** Computes the 2‑D array `rowWindowCounts[i][j]` – number of rows that fit
     *  inside the column window starting at (i, j). */
    private static int[][] computeRowWindowCounts(int[][] rowBounds, int n, int k) {
        int maxStart = n - k + 1;
        int[][] counts = new int[maxStart][maxStart];
        for (int colStart = 0; colStart < maxStart; colStart++) {
            int cnt = 0;
            // initialise for the first vertical window (rows 0 … k‑1)
            for (int r = 0; r < k; r++) {
                if (rowIntervalFits(r, colStart, k, rowBounds)) {
                    cnt++;
                }
            }
            counts[0][colStart] = cnt;
            // slide the vertical window downwards
            for (int rowStart = 1; rowStart < maxStart; rowStart++) {
                // remove the row that just left the window
                if (rowIntervalFits(rowStart - 1, colStart, k, rowBounds)) {
                    cnt--;
                }
                // add the new row that entered the window
                if (rowIntervalFits(rowStart + k - 1, colStart, k, rowBounds)) {
                    cnt++;
                }
                counts[rowStart][colStart] = cnt;
            }
        }
        return counts;
    }

    /** Computes the 2‑D array `colWindowCounts[i][j]` – number of columns that fit
     *  inside the row window starting at (i, j). */
    private static int[][] computeColumnWindowCounts(int[][] colBounds, int n, int k) {
        int maxStart = n - k + 1;
        int[][] counts = new int[maxStart][maxStart];
        for (int rowStart = 0; rowStart < maxStart; rowStart++) {
            int cnt = 0;
            // initialise for the first horizontal window (columns 0 … k‑1)
            for (int c = 0; c < k; c++) {
                if (colIntervalFits(c, rowStart, k, colBounds)) {
                    cnt++;
                }
            }
            counts[rowStart][0] = cnt;
            // slide the horizontal window rightwards
            for (int colStart = 1; colStart < maxStart; colStart++) {
                // remove the column that just left the window
                if (colIntervalFits(colStart - 1, rowStart, k, colBounds)) {
                    cnt--;
                }
                // add the new column that entered the window
                if (colIntervalFits(colStart + k - 1, rowStart, k, colBounds)) {
                    cnt++;
                }
                counts[rowStart][colStart] = cnt;
            }
        }
        return counts;
    }

    /** Main driver –‑ parses input, performs the calculations and prints the result. */
    public static void main(String[] args) throws IOException {
        FastReader in = new FastReader(System.in);

        int n = in.nextInt();          // grid dimension
        int k = in.nextInt();          // side length of the square we are looking for
        String[] lines = new String[n];
        for (int i = 0; i < n; i++) {
            lines[i] = in.nextLine();  // each row of the grid
        }

        // -----------------------------------------------------------------
        // 1️⃣  Determine row / column limits and count empty rows / columns
        // -----------------------------------------------------------------
        int[][] rowBounds = new int[n][2];   // {minCol, maxCol} for each row
        fillRowBounds(lines, n, rowBounds);

        // Build a boolean board to obtain column information easily
        boolean[][] board = new boolean[n][n];
        for (int r = 0; r < n; r++) {
            for (int c = 0; c < n; c++) {
                board[r][c] = (lines[r].charAt(c) == 'B');
            }
        }

        int[][] colBounds = new int[n][2];   // {minRow, maxRow} for each column
        fillColumnBounds(board, n, colBounds);

        int emptyRows = 0, emptyCols = 0;
        for (int[] b : rowBounds) {
            if (b[0] == EMPTY) emptyRows++;
        }
        for (int[] b : colBounds) {
            if (b[0] == EMPTY) emptyCols++;
        }

        // -----------------------------------------------------------------
        // 2️⃣  Compute how many rows / columns fit inside every possible
        //      k×k window (both horizontally and vertically)
        // -----------------------------------------------------------------
        int maxStart = n - k + 1;
        int[][] rowWindowCounts = computeRowWindowCounts(rowBounds, n, k);
        int[][] colWindowCounts = computeColumnWindowCounts(colBounds, n, k);

        // -----------------------------------------------------------------
        // 3️⃣  Find the best (row, column) pair that maximises the sum of
        //      fitting rows + fitting columns.
        // -----------------------------------------------------------------
        int best = 0;
        for (int i = 0; i < maxStart; i++) {
            for (int j = 0; j < maxStart; j++) {
                best = Math.max(best, rowWindowCounts[i][j] + colWindowCounts[i][j]);
            }
        }

        // -----------------------------------------------------------------
        // 4️⃣  Output
        // -----------------------------------------------------------------
        System.out.println(emptyRows + emptyCols + best);
    }
}

import java.io.*;
import java.util.*;

/**
 * Solution for the “Painting the Array” problem.
 * The program reads a square grid of characters ( 'B' – black, other – white ),
 * counts the rows / columns that are already completely white,
 * then finds the best position of a k × k brush that turns the maximum
 * additional rows / columns white.
 *
 * The implementation is deliberately split into small, well‑named methods
 * and uses a 2‑D prefix‑sum array to query the number of black cells in
 * any rectangle in O(1) time.
 */
public class Main {

    /* --------------------------------------------------------------
     * Entry point
     * -------------------------------------------------------------- */
    public static void main(String[] args) {
        InputStream inStream = System.in;
        OutputStream outStream = System.out;
        InputReader reader = new InputReader(inStream);
        PrintWriter writer = new PrintWriter(outStream);

        Solver solver = new Solver();
        solver.solve(reader, writer);

        writer.close();
    }

    /* --------------------------------------------------------------
     * Fast scanner – reads ints and lines from an InputStream
     * -------------------------------------------------------------- */
    private static class InputReader {
        private final byte[] buffer = new byte[1 << 12];
        private int pointer = 0;
        private final int limit;
        private final InputStream stream;

        InputReader(InputStream stream) {
            this.stream = stream;
            limit = 1 << 12;
        }

        private int readByte() {
            if (pointer >= limit) {
                reload();
                if (limit == -1) return -1;
                pointer = 0;
            }
            return buffer[pointer++];
        }

        private void reload() {
            try {
                limit = stream.read(buffer);
            } catch (IOException e) {
                limit = -1;
            }
        }

        /** Reads the next non‑whitespace token as an int. */
        int nextInt() {
            int c = readByte();
            while (c <= ' ') c = readByte();
            boolean negative = false;
            if (c == '-') {
                negative = true;
                c = readByte();
            }
            int result = 0;
            while (c > ' ') {
                result = result * 10 + (c - '0');
                c = readByte();
            }
            return negative ? -result : result;
        }

        /** Reads the next line (excluding the line separator). */
        String nextLine() {
            StringBuilder sb = new StringBuilder();
            int c = readByte();
            while (c <= ' ') c = readByte();               // skip whitespace
            while (!isEndOfLine(c)) {
                sb.appendCodePoint(c);
                c = readByte();
            }
            return sb.toString();
        }

        private boolean isEndOfLine(int c) {
            return c == '\n' || c == '\r' || c == -1;
        }
    }

    /* --------------------------------------------------------------
     * Core solver – encapsulates all problem specific logic
     * -------------------------------------------------------------- */
    private static class Solver {

        /** Size of the grid (n × n). */
        private int n;

        /** Brush size (k × k). */
        private int k;

        /** Grid stored with 1‑based indexing (empty row 0 is unused). */
        private char[][] grid;

        /** 2‑D prefix sum of black cells ( 'B' → 1, otherwise 0 ). */
        private int[][] prefix;

        /**
         * Solves a single test case.
         *
         * @param reader  input source
         * @param out     output destination
         */
        void solve(InputReader reader, PrintWriter out) {
            readInput(reader);
            int alreadyWhite = countAlreadyWhiteLines();
            int bestAdditional = maximizeAdditionalWhiteLines();
            out.print(alreadyWhite + bestAdditional);
        }

        /** ----------------------------------------------------------
         *  Input handling
         * ---------------------------------------------------------- */
        private void readInput(InputReader reader) {
            n = reader.nextInt();
            k = reader.nextInt();
            grid = new char[n + 1][n + 1];               // 1‑based

            for (int i = 1; i <= n; i++) {
                String line = reader.nextLine();
                for (int j = 1; j <= n; j++) {
                    grid[i][j] = line.charAt(j - 1);
                }
            }
            buildPrefixSum();
        }

        /** ----------------------------------------------------------
         *  Prefix‑sum construction (black cells = 1)
         * ---------------------------------------------------------- */
        private void buildPrefixSum() {
            prefix = new int[n + 1][n + 1];
            for (int i = 1; i <= n; i++) {
                for (int j = 1; j <= n; j++) {
                    int black = (grid[i][j] == 'B' ? 1 : 0);
                    prefix[i][j] = prefix[i - 1][j] + prefix[i][j - 1]
                            - prefix[i - 1][j - 1] + black;
                }
            }
        }

        /** ----------------------------------------------------------
         *  Helper – sum of black cells inside a rectangle
         *  (inclusive, 1‑based coordinates)
         * ---------------------------------------------------------- */
        private int sumRectangle(int x1, int y1, int x2, int y2) {
            return prefix[x2][y2] - prefix[x1 - 1][y2]
                    - prefix[x2][y1 - 1] + prefix[x1 - 1][y1 - 1];
        }

        /** ----------------------------------------------------------
         *  Count rows and columns that are already completely white
         * ---------------------------------------------------------- */
        private int countAlreadyWhiteLines() {
            int whiteRows = 0;
            int whiteCols = 0;

            for (int i = 1; i <= n; i++) {
                if (sumRectangle(i, 1, i, n) == 0) whiteRows++;
                if (sumRectangle(1, i, n, i) == 0) whiteCols++;
            }
            return whiteRows + whiteCols;
        }

        /** ----------------------------------------------------------
         *  Find the best placement of the k × k brush that creates the
         *  largest number of *additional* white rows / columns.
         * ---------------------------------------------------------- */
        private int maximizeAdditionalWhiteLines() {
            int bestAdditional = 0;

            // iterate over all possible top‑left corners of the brush
            for (int top = 1; top <= n - k + 1; top++) {
                for (int left = 1; left <= n - k + 1; left++) {
                    int additional = 0;

                    // rows that become white after painting this brush
                    for (int r = top; r < top + k; r++) {
                        if (rowFullyCoveredByBrush(r, left, left + k - 1)) {
                            additional++;
                        }
                    }

                    // columns that become white after painting this brush
                    for (int c = left; c < left + k; c++) {
                        if (columnFullyCoveredByBrush(c, top, top + k - 1)) {
                            additional++;
                        }
                    }

                    bestAdditional = Math.max(bestAdditional, additional);
                }
            }
            return bestAdditional;
        }

        /** ----------------------------------------------------------
         *  Does row 'row' contain black cells only inside columns
         *  [colStart, colEnd] ?
         * ---------------------------------------------------------- */
        private boolean rowFullyCoveredByBrush(int row, int colStart, int colEnd) {
            int totalBlackInRow = sumRectangle(row, 1, row, n);
            int blackInsideWindow = sumRectangle(row, colStart, row, colEnd);
            return totalBlackInRow == blackInsideWindow;
        }

        /** ----------------------------------------------------------
         *  Does column 'col' contain black cells only inside rows
         *  [rowStart, rowEnd] ?
         * ---------------------------------------------------------- */
        private boolean columnFullyCoveredByBrush(int col, int rowStart, int rowEnd) {
            int totalBlackInCol = sumRectangle(1, col, n, col);
            int blackInsideWindow = sumRectangle(rowStart, col, rowEnd, col);
            return totalBlackInCol == blackInsideWindow;
        }
    }
}

import java.util.Arrays;
import java.util.Scanner;

/**
 * Reads a grid of characters, finds the best position for a k×k window and prints the result.
 *
 * The algorithm is a clear, well‑structured rewrite of the original program.
 * It keeps exactly the same behaviour:
 *   – counts rows/columns that contain no ‘B’
 *   – for every possible top‑left corner of a k×k window counts how many
 *     columns are completely inside the vertical window and how many rows are
 *     completely inside the horizontal window
 *   – adds those two numbers and keeps the maximum, finally adding the
 *     “empty” rows and columns.
 */
public class D {

    /** Prefix‑sum helper – returns the number of `true` values in a range. */
    private static int rangeSum(int[] prefix, int from, int toExclusive) {
        return prefix[toExclusive] - prefix[from];
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();          // size of the square grid
        int k = sc.nextInt();          // size of the moving window
        sc.nextLine();                 // consume end‑of‑line

        String[] grid = new String[n];
        for (int i = 0; i < n; ++i) {
            grid[i] = sc.nextLine();
        }
        sc.close();

        /* --------------------------------------------------------------
         * 1️⃣  Determine, for each row / column, the first and last index
         *     that contains a ‘B’.  Also count rows / columns that have no ‘B’.
         * -------------------------------------------------------------- */
        int[] firstRowInCol = new int[n];   // first row with ‘B’ in each column
        int[] lastRowInCol  = new int[n];   // last  row with ‘B’ in each column
        Arrays.fill(firstRowInCol, -1);
        Arrays.fill(lastRowInCol, -1);

        int colsWithoutB = 0;
        for (int c = 0; c < n; ++c) {
            for (int r = 0; r < n; ++r) {
                if (grid[r].charAt(c) == 'B') {
                    if (firstRowInCol[c] == -1) firstRowInCol[c] = r;
                    lastRowInCol[c] = r;
                }
            }
            if (firstRowInCol[c] == -1) {
                ++colsWithoutB;
            }
        }

        int[] firstColInRow = new int[n];   // first column with ‘B’ in each row
        int[] lastColInRow  = new int[n];   // last  column with ‘B’ in each row
        Arrays.fill(firstColInRow, -1);
        Arrays.fill(lastColInRow, -1);

        int rowsWithoutB = 0;
        for (int r = 0; r < n; ++r) {
            for (int c = 0; c < n; ++c) {
                if (grid[r].charAt(c) == 'B') {
                    if (firstColInRow[r] == -1) firstColInRow[r] = c;
                    lastColInRow[r] = c;
                }
            }
            if (firstColInRow[r] == -1) {
                ++rowsWithoutB;
            }
        }

        /* --------------------------------------------------------------
         * 2️⃣  For every possible position of a k×k window we need two
         *     counts:
         *       • how many columns are *fully* inside the vertical window
         *         (their whole ‘B’ span lies inside rows i … i+k‑1)
         *       • how many rows are *fully* inside the horizontal window
         *         (their whole ‘B’ span lies inside columns j … j+k‑1)
         *     Both counts are obtained with sliding‑window techniques.
         * -------------------------------------------------------------- */
        int limit = n - k + 1;                     // number of possible starts
        int[][] colWindow = new int[limit][limit]; // colWindow[i][j] = columns count
        int[][] rowWindow = new int[limit][limit]; // rowWindow[i][j] = rows count

        // ---- columns: for each start row i we build a boolean array that tells
        //           whether a column is completely inside the vertical window.
        for (int startRow = 0; startRow < limit; ++startRow) {
            boolean[] colInside = new boolean[n];
            for (int col = 0; col < n; ++col) {
                colInside[col] = firstRowInCol[col] != -1 &&
                                 firstRowInCol[col] >= startRow &&
                                 lastRowInCol[col] <= startRow + k - 1;
            }

            // prefix sums allow O(1) window queries
            int[] prefix = new int[n + 1];
            for (int idx = 0; idx < n; ++idx) {
                prefix[idx + 1] = prefix[idx] + (colInside[idx] ? 1 : 0);
            }
            for (int startCol = 0; startCol < limit; ++startCol) {
                colWindow[startRow][startCol] =
                        rangeSum(prefix, startCol, startCol + k);
            }
        }

        // ---- rows: symmetric treatment – for each start column j we build a
        //           boolean array that tells whether a row is completely inside
        //           the horizontal window.
        for (int startCol = 0; startCol < limit; ++startCol) {
            boolean[] rowInside = new boolean[n];
            for (int r = 0; r < n; ++r) {
                rowInside[r] = firstColInRow[r] != -1 &&
                               firstColInRow[r] >= startCol &&
                               lastColInRow[r] <= startCol + k - 1;
            }

            int[] prefix = new int[n + 1];
            for (int idx = 0; idx < n; ++idx) {
                prefix[idx + 1] = prefix[idx] + (rowInside[idx] ? 1 : 0);
            }
            for (int startRow = 0; startRow < limit; ++startRow) {
                rowWindow[startRow][startCol] =
                        rangeSum(prefix, startRow, startRow + k);
            }
        }

        /* --------------------------------------------------------------
         * 3️⃣  The final answer is the maximum of (colWindow + rowWindow)
         *     plus the numbers of completely empty rows and columns.
         * -------------------------------------------------------------- */
        int best = 0;
        for (int i = 0; i < limit; ++i) {
            for (int j = 0; j < limit; ++j) {
                best = Math.max(best, colWindow[i][j] + rowWindow[i][j]);
            }
        }

        System.out.println(best + rowsWithoutB + colsWithoutB);
    }
}

import java.io.*;
import java.util.*;

public class CodingLegacy {

    /** Fast scanner – mimics the original ScanReader but with clearer method names */
    private static final class FastScanner {
        private final InputStream stream;
        private final byte[] buffer = new byte[1024];
        private int bufferPos = 0, bufferLen = 0;

        FastScanner(InputStream stream) {
            this.stream = stream;
        }

        private int readByte() {
            if (bufferPos >= bufferLen) {
                bufferLen = stream.read(buffer);
                bufferPos = 0;
                if (bufferLen <= 0) return -1;
            }
            return buffer[bufferPos++];
        }

        private boolean isSpace(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        int nextInt() {
            int c;
            do { c = readByte(); } while (isSpace(c));
            int sign = 1;
            if (c == '-') { sign = -1; c = readByte(); }
            int value = 0;
            while (!isSpace(c) && c >= '0' && c <= '9') {
                value = value * 10 + (c - '0');
                c = readByte();
            }
            return value * sign;
        }

        String next() {
            int c;
            do { c = readByte(); } while (isSpace(c));
            StringBuilder sb = new StringBuilder();
            do {
                sb.appendCodePoint(c);
                c = readByte();
            } while (!isSpace(c));
            return sb.toString();
        }
    }

    /** Solver – contains the core algorithm */
    private static final class Solver {
        /** Size of the sliding window (k) and board dimension (n) are set per test */
        private int n, k;
        /** Bounds of black cells in each row / column */
        private final int[] rowMin = new int[1024];   // reused for each test
        private final int[] rowMax = new int[1024];
        private final int[] colMin = new int[1024];
        private final int[] colMax = new int[1024];
        /** Fast scanner used for the current test case */
        private final FastScanner fs;

        Solver(FastScanner fs) {
            this.fs = fs;
        }

        /** Entry point for a single test case */
        void solve(int testNumber, PrintWriter out) {
            n = fs.nextInt();
            k = fs.nextInt();

            char[][] board = new char[n][];
            for (int i = 0; i < n; i++) {
                board[i] = fs.next().toCharArray();
            }

            // ---------- 1. Determine the occupied intervals ----------
            int emptyRows = 0, emptyCols = 0;

            // Row intervals
            for (int r = 0; r < n; r++) {
                int first = n, last = -1;
                for (int c = 0; c < n; c++) {
                    if (board[r][c] == 'B') {
                        first = Math.min(first, c);
                        last = c;
                    }
                }
                if (first == n) {               // row r has no black cells
                    emptyRows++;
                } else {
                    rowMin[r] = first;
                    rowMax[r] = last;
                }
            }

            // Column intervals
            for (int c = 0; c < n; c++) {
                int first = n, last = -1;
                for (int r = 0; r < n; r++) {
                    if (board[r][c] == 'B') {
                        first = Math.min(first, r);
                        last = r;
                    }
                }
                if (first == n) {               // column c has no black cells
                    emptyCols++;
                } else {
                    colMin[c] = first;
                    colMax[c] = last;
                }
            }

            int emptyTogether = emptyRows + emptyCols;   // “whiteStart” in original code

            // ---------- 2. Pre‑compute coverage matrices ----------
            int usable = n - k + 1;                       // number of possible top‑left positions
            int[][] rowCover   = new int[usable][usable]; // rows covered for each (rowStart, colStart)
            int[][] colCover   = new int[usable][usable]; // columns covered for each (rowStart, colStart)

            /* 2a – rows covered for every column window */
            for (int colStart = 0; colStart < usable; colStart++) {
                boolean[] rowFullyInWindow = new boolean[n];
                for (int r = 0; r < n; r++) {
                    if (rowMin[r] == n) {                 // empty row – not counted
                        rowFullyInWindow[r] = false;
                    } else {
                        rowFullyInWindow[r] = 
                            rowMin[r] >= colStart && rowMax[r] < colStart + k;
                    }
                }
                // sliding window of height k over rows
                int current = 0;
                for (int r = 0; r < k; r++) {
                    current += rowFullyInWindow[r] ? 1 : 0;
                }
                rowCover[0][colStart] = current;
                for (int r = 1; r < usable; r++) {
                    current += rowFullyInWindow[r + k - 1] ? 1 : 0;
                    current -= rowFullyInWindow[r - 1] ? 1 : 0;
                    rowCover[r][colStart] = current;
                }
            }

            /* 2b – columns covered for every row window */
            for (int rowStart = 0; rowStart < usable; rowStart++) {
                boolean[] colFullyInWindow = new boolean[n];
                for (int c = 0; c < n; c++) {
                    if (colMin[c] == n) {                 // empty column – not counted
                        colFullyInWindow[c] = false;
                    } else {
                        colFullyInWindow[c] = 
                            colMin[c] >= rowStart && colMax[c] < rowStart + k;
                    }
                }
                // sliding window of width k over columns
                int current = 0;
                for (int c = 0; c < k; c++) {
                    current += colFullyInWindow[c] ? 1 : 0;
                }
                colCover[rowStart][0] = current;
                for (int c = 1; c < usable; c++) {
                    current += colFullyInWindow[c + k - 1] ? 1 : 0;
                    current -= colFullyInWindow[c - 1] ? 1 : 0;
                    colCover[rowStart][c] = current;
                }
            }

            // ---------- 3. Find the best placement ----------
            int bestCombined = 0;
            for (int r = 0; r < usable; r++) {
                for (int c = 0; c < usable; c++) {
                    bestCombined = Math.max(bestCombined,
                                            rowCover[r][c] + colCover[r][c]);
                }
            }

            out.println(bestCombined + emptyTogether);
        }
    }

    /** Main driver – reads all input, creates a solver and runs it */
    public static void main(String[] args) {
        FastScanner fs = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(System.out);

        // The original program only processes a single test case (t = 1)
        int testCases = 1;
        Solver solver = new Solver(fs);

        for (int tc = 0; tc < testCases; tc++) {
            solver.solve(tc + 1, out);
        }

        out.close();
    }
}

import java.util.Scanner;

/**
 * Refactored version of the original program.
 * The logic is unchanged – only the structure, naming and comments have been improved
 * to make the code easier to read, maintain and extend.
 */
public class Main {

    /* --------------------------------------------------------------------- */
    /*  Static fields that are used in several methods (to mimic the original   */
    /*  implicit variable scope)                                               */
    /* --------------------------------------------------------------------- */
    private static int[] save;   // temporary storage for column contributions

    public static void main(String[] args) {
        try (Scanner in = new Scanner(System.in)) {
            /* --------------------------  INPUT  -------------------------- */
            int n = in.nextInt();          // board size
            int k = in.nextInt();          // window size
            int size = n - k + 1;            // number of possible window positions

            String[] lines = new String[n];
            for (int i = 0; i < n; i++) {
                lines[i] = in.next();
            }

            /* ----------------------  BOUNDS  ---------------------- */
            int[][] rowBound = new int[n][2];   // [minCol, maxCol] per row
            int[][] colBound = new int[n][2];   // [minRow, maxRow] per column
            initialiseBounds(rowBound, colBound, n);

            for (int r = 0; r < n; r++) {
                updateBounds(lines[r], r, rowBound, colBound);
            }

            /* -------------------  EMPTY LINES/COWS  ------------------- */
            int emptyRowsAndCols = countEmptyRowsAndCols(rowBound, colBound, n);

            /* -----------------------  DP INIT  ----------------------- */
            int[][][] dp = new int[size][size][2];
            int maxScore = 0;

            initialiseFirstWindow(dp, k, rowBound, colBound, size);
            maxScore = Math.max(maxScore, dp[0][0][0] + dp[0][0][1]);

            /* -----------------------  DP LOOP  ----------------------- */
            for (int i = 0; i < size; i++) {
                if (i > 0) {
                    propagateFirstColumn(dp, i, rowBound, size, k);
                }
                maxScore = Math.max(maxScore, dp[i][0][0] + dp[i][0][1]);

                for (int j = 1; j < size; j++) {
                    updateForPosition(dp, i, j, rowBound, colBound, size, k);
                    maxScore = Math.max(maxScore, dp[i][j][0] + dp[i][j][1]);
                }
            }

            System.out.println(maxScore + emptyRowsAndCols);
        }
    }

    /* --------------------------------------------------------------------- */
    /*  Helper methods – each encapsulates a distinct, well‑named operation   */
    /* --------------------------------------------------------------------- */

    private static void initialiseBounds(int[][] rowBound, int[][] colBound, int n) {
        // sentinel values: min = n (larger than any valid index), max = -1
        for (int i = 0; i < n; i++) {
            rowBound[i][0] = n;
            rowBound[i][1] = -1;
            colBound[i][0] = n;
            colBound[i][1] = -1;
        }
    }

    private static void updateBounds(String line, int row,
                                     int[][] rowBound, int[][] colBound) {
        for (int col = 0; col < line.length(); col++) {
            if (line.charAt(col) == 'B') {
                // update row‑wise extremes
                rowBound[row][0] = Math.min(col, rowBound[row][0]);
                rowBound[row][1] = Math.max(col, rowBound[row][1]);

                // update column‑wise extremes
                colBound[col][0] = Math.min(row, colBound[col][0]);
                colBound[col][1] = Math.max(row, colBound[col][1]);
            }
        }
    }

    private static int countEmptyRowsAndCols(int[][] rowBound,
                                             int[][] colBound,
                                             int n) {
        int cnt = 0;
        for (int i = 0; i < n; i++) {
            if (rowBound[i][1] < 0) {          // no 'B' in this row
                cnt++;
            }
            if (colBound[i][1] < 0) {          // no 'B' in this column
                cnt++;
            }
        }
        return cnt;
    }

    private static void initialiseFirstWindow(int[][][] dp,
                                              int k,
                                              int[][] rowBound,
                                              int[][] colBound,
                                              int size) {
        // dp[0][0][0] – rows whose maximal column lies inside the first window (0..k‑1)
        // dp[0][0][1] – columns whose maximal row lies inside the first window (0..k‑1)
        for (int i = 0; i < k; i++) {
            if (rowBound[i][1] < k && rowBound[i][1] >= 0) {
                dp[0][0][0]++;
            }
            if (colBound[i][1] < k && colBound[i][1] >= 0) {
                dp[0][0][1]++;
            }
        }
    }

    private static void propagateFirstColumn(int[][][] dp,
                                             int i,
                                             int[][] rowBound,
                                             int size,
                                             int k) {
        // shift the previously stored column‑0 values
        dp[i][0][0] = dp[i - 1][0][0];
        if (rowBound[i - 1][1] < k && rowBound[i - 1][1] >= 0) {
            dp[i][0][0]--;
        }
        if (rowBound[i + k - 1][1] < k && rowBound[i + k - 1][1] >= 0) {
            dp[i][0][0]++;
        }

        // temporary contribution of columns for the new vertical shift
        int temp = 0;
        for (int m = 0; m < k; m++) {
            if (colBound[m][1] < 0) {
                continue;
            }
            if (i - 1 <= colBound[m][0] && i + k - 2 >= colBound[m][1]) {
                if (i > colBound[m][0]) {
                    temp--;
                }
            } else {
                if (i <= colBound[m][0] && i + k - 1 >= colBound[m][1]) {
                    temp++;
                }
            }
        }
        dp[i][0][1] = dp[i - 1][0][1] + temp;
    }

    private static void updateForPosition(int[][][] dp,
                                          int i,
                                          int j,
                                          int[][] rowBound,
                                          int[][] colBound,
                                          int size,
                                          int k) {
        // inherit values from the cell to the left
        dp[i][j][0] = dp[i][j - 1][0];
        dp[i][j][1] = dp[i][j - 1][1];

        // adjust the column‑related term when moving one step rightwards
        if (colBound[j - 1][1] >= 0 && i <= colBound[j - 1][0] && i + k - 1 >= colBound[j - 1][1]) {
            dp[i][j][1]--;
        }
        if (colBound[j + k - 1][1] >= 0 && i <= colBound[j + k - 1][0] && i + k - 1 >= colBound[j + k - 1][1]) {
            dp[i][j][1]++;
        }

        if (i == 0) {
            // first vertical strip – compute a fresh contribution for this column
            int cur = 0;
            for (int q = i; q <= i + k - 1; q++) {
                if (rowBound[q][1] < 0) {
                    continue;
                }
                if (j - 1 <= rowBound[q][0] && j + k - 2 >= rowBound[q][1]) {
                    if (j > rowBound[q][0]) {
                        cur--;
                    }
                } else {
                    if (j <= rowBound[q][0] && j + k - 1 >= rowBound[q][1]) {
                        cur++;
                    }
                }
            }
            save[j] = cur;                     // remember it for later use
            dp[i][j][0] = dp[i][j - 1][0] + cur;
        } else {
            // subsequent vertical strips – update the saved contribution
            int now = 0;
            // column that leaves the window vertically
            if (j - 1 <= rowBound[i - 1][0] && j + k - 2 >= rowBound[i - 1][1]) {
                if (j > rowBound[i - 1][0]) {
                    now++;
                }
            } else {
                if (j <= rowBound[i - 1][0] && j + k - 1 >= rowBound[i - 1][1]) {
                    now--;
                }
            }
            // column that enters the window vertically
            if (j - 1 <= rowBound[i + k - 1][0] && j + k - 2 >= rowBound[i + k - 1][1]) {
                if (j > rowBound[i + k - 1][0]) {
                    now--;
                }
            } else {
                if (j <= rowBound[i + k - 1][0] && j + k - 1 >= rowBound[i + k - 1][1]) {
                    now++;
                }
            }
            save[j] += now;
            dp[i][j][0] = dp[i][j - 1][0] + save[j];
        }
    }
}

import java.io.*;
import java.util.Arrays;

/**
 * Entry point of the application.  It delegates all work to the solver classes
 * and performs only I/O wiring.
 */
public class Main {

    public static void main(String[] args) {
        solve(System.in, System.out);
    }

    /**
     * Core driver that connects input, solution and output.
     */
    private static void solve(InputStream in, OutputStream out) {
        FastScanner scanner = new FastScanner(in);
        FastOutput output = new FastOutput(out);
        Solver solver = new Solver();

        solver.run(scanner, output);
        output.flush();
    }

    /**
     * Solver class – contains the algorithm in a self‑contained, easy‑to‑read
     * form.  All public methods are deliberately small and have a single
     * responsibility.
     */
    private static class Solver {

        /** sentinel used for un‑initialised minima */
        private static final int SENTINEL = 1_000;   // any value > n works

        /** Perform the whole computation and write the answer. */
        void run(FastScanner fs, FastOutput out) {
            int n = fs.nextInt();          // board size
            int k = fs.nextInt();          // side length of the square we may paint
            char[][] board = new char[n][n];

            // Extents of black cells in each row / column
            int[] rowMin = new int[n];
            int[] rowMax = new int[n];
            int[] colMin = new int[n];
            int[] colMax = new int[n];

            // Filled with sentinel values before we start scanning
            Arrays.fill(rowMin, SENTINEL);
            Arrays.fill(rowMax, 0);
            Arrays.fill(colMin, SENTINEL);
            Arrays.fill(colMax, 0);

            // ------------------------------------------------------------
            // 1️⃣  Read the grid and compute row / column extents
            // ------------------------------------------------------------
            readBoard(board, fs, rowMin, rowMax, colMin, colMax);

            // ------------------------------------------------------------
            // 2️⃣  Base answer: rows/columns that contain no black cells
            // ------------------------------------------------------------
            int baseAnswer = countEmptyRowsAndColumns(rowMax, colMax);

            // ------------------------------------------------------------
            // 3️⃣  Additive contributions of every possible k×k square
            // ------------------------------------------------------------
            int[][] addition = computeAdditions(n, k, rowMin, rowMax,
                                                colMin, colMax);

            // ------------------------------------------------------------
            // 4️⃣  Choose the best placement – maximal (base + addition)
            // ------------------------------------------------------------
            int best = baseAnswer;
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < n; j++) {
                    best = Math.max(best, baseAnswer + addition[i][j]);
                }
            }

            out.println(best);
        }

        /* ----------------------------------------------------------------
         * Helper methods – each is deliberately short and well documented.
         * ---------------------------------------------------------------- */

        /** Initialise extent arrays with safe default values. */
        private static void initialiseExtents(int[] rowMin, int[] rowMax,
                                              int[] colMin, int[] colMax) {
            Arrays.fill(rowMin, SENTINEL);
            Arrays.fill(rowMax, 0);
            Arrays.fill(colMin, SENTINEL);
            Arrays.fill(colMax, 0);
        }

        /** Fill the three extent arrays with sentinel values before reading. */
        private static void initExtents(int[] rowMin, int[] rowMax,
                                        int[] colMin, int[] colMax) {
            Arrays.fill(rowMin, SENTINEL);
            Arrays.fill(rowMax, 0);
            Arrays.fill(colMin, SENTINEL);
            Arrays.fill(colMax, 0);
        }

        /** Read the grid and update row‑/column‑extent arrays whenever a ‘B’ is seen. */
        private static void readBoard(char[][] board, FastScanner fs,
                                      int[] rowMin, int[] rowMax,
                                      int[] colMin, int[] colMax) {
            for (int i = 0; i < board.length; i++) {
                char[] row = fs.readCharArray(board.length);
                board[i] = row;
                for (int j = 0; j < row.length; j++) {
                    if (row[j] == 'B') {
                        recordRowExtent(i, j, rowMin, rowMax);
                        recordColumnExtent(i, j, colMin, colMax);
                    }
                }
            }
        }

        private static void recordRowExtent(int row, int col, int[] rowMin,
                                            int[] rowMax) {
            rowMin[row] = Math.min(rowMin[row], col + 1);
            rowMax[row] = Math.max(rowMax[row], col + 1);
        }

        private static void recordColumnExtent(int row, int col,
                                               int[] colMin, int[] colMax) {
            colMin[col] = Math.min(colMin[col], row + 1);
            colMax[col] = Math.max(colMax[col], row + 1);
        }

        /** Count rows / columns that contain no black cells. */
        private static int countEmptyRowsAndColumns(int[] rowMax, int[] colMax) {
            int cnt = 0;
            for (int v : rowMax) if (v == 0) cnt++;
            for (int v : colMax) if (v == 0) cnt++;
            return cnt;
        }

        /**
         * Build a matrix `addition` where {@code addition[i][j]} holds the
         * number of extra rows *and* columns that would be covered by painting
         * the k×k square whose top‑left corner is at (i, j).
         */
        private static int[][] computeAdditions(int n, int k,
                                                int[] rowMin, int[] rowMax,
                                                int[] colMin, int[] colMax) {
            int[][] addition = new int[n][n];

            // Horizontal sliding windows -------------------------------------------------
            for (int startCol = 0; startCol <= n - k; startCol++) {
                int left   = startCol + 1;
                int right  = left + k - 1;
                int cnt    = horizontalCoverCount(rowMin, rowMax, left, right);
                addition[0][startCol] = cnt;

                // slide the window downwards
                for (int startRow = 1; startRow <= n - k; startRow++) {
                    int addedRowIdx  = startRow + k - 1;   // new row entering the window
                    int removedRowIdx = startRow - 1;      // row leaving the window

                    cnt += addIfCovered(addedRowIdx, rowMin, rowMax, left, right, true);
                    cnt += addIfCovered(removedRowIdx, rowMin, rowMax, left, right, false);
                    addition[startRow][startCol] = cnt;
                }
            }

            // Vertical sliding windows ---------------------------------------------------
            for (int startRow = 0; startRow <= n - k; startRow++) {
                int top    = startRow + 1;
                int bottom = top + k - 1;
                int cnt    = verticalCoverCount(colMin, colMax, top, bottom);
                addition[startRow][0] = cnt;

                // slide the window rightwards
                for (int startCol = 1; startCol <= n - k; startCol++) {
                    int addedColIdx  = startCol + k - 1;   // new column entering
                    int removedColIdx = startCol - 1;      // column leaving

                    cnt += addIfCovered(addedColIdx, colMin, colMax, top, bottom, true);
                    cnt += addIfCovered(removedColIdx, colMin, colMax, top, bottom, false);
                    addition[startRow][startCol] = cnt;
                }
            }

            return addition;
        }

        /** How many rows (within the current k‑row window) are fully covered. */
        private static int horizontalCoverCount(int[] rowMin, int[] rowMax,
                                                int left, int right) {
            int cnt = 0;
            for (int i = 0; i < k; i++) {
                if (rowMax[i] != 0 && rowMax[i] <= right && rowMin[i] >= left) {
                    cnt++;
                }
            }
            return cnt;
        }

        /** How many columns (within the current k‑column window) are fully covered. */
        private static int verticalCoverCount(int[] colMin, int[] colMax,
                                              int top, int bottom) {
            int cnt = 0;
            for (int j = 0; j < k; j++) {
                if (colMax[j] != 0 && colMax[j] <= bottom && colMin[j] >= top) {
                    cnt++;
                }
            }
            return cnt;
        }

        /** Add or subtract 1 from {@code mutableCount} depending on whether the
         *  cell at {@code idx} is fully covered by the interval [left, right].
         */
        private static int addIfCovered(int idx, int[] minArray, int[] maxArray,
                                        int left, int right, boolean add) {
            if (maxArray[idx] != 0 && maxArray[idx] <= right && minArray[idx] >= left) {
                return add ? 1 : -1;
            }
            return 0;
        }
    }

    /* --------------------------------------------------------------------
     * Fast scanner utilities – keep I/O overhead low without pulling in
     * external libraries.
     * -------------------------------------------------------------------- */
    private static class FastScanner {
        private final InputStream stream;
        private final byte[] buffer = new byte[16 * 1024];
        private int pointer = 0, length = 0;

        FastScanner(InputStream stream) {
            this.stream = stream;
        }

        /** Retrieve the next byte, expanding the buffer when necessary. */
        private int readChar() throws IOException {
            if (pointer >= length) {
                length = stream.read(buffer);
                pointer = 0;
                if (length <= 0) return -1;
            }
            return buffer[pointer++];
        }

        /** Return the next whitespace‑delimited token as a {@code String}. */
        String next() throws IOException {
            int c;
            do { c = readChar(); } while (c <= ' ');
            StringBuilder sb = new StringBuilder();
            do {
                sb.append((char) c);
                c = readChar();
            } while (c > ' ');
            return sb.toString();
        }

        /** Read exactly {@code size} characters into a new array. */
        char[] readCharArray(int size) throws IOException {
            char[] arr = new char[size];
            for (int i = 0; i < size; i++) {
                arr[i] = (char) readChar();
            }
            return arr;
        }

        /** Convenience wrapper around {@code Integer.parseInt}. */
        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }

        /** Whitespace test used by the scanner. */
        boolean isSpaceChar(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t';
        }
    }

    /* --------------------------------------------------------------------
     * Very thin output wrapper – mirrors the original {@code OutputWriter}
     * but adds a {@code flush()} method for symmetry.
     * -------------------------------------------------------------------- */
    private static class FastOutput {
        private final PrintWriter writer;

        FastOutput(OutputStream out) {
            writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(out)));
        }

        /** Print one or more objects separated by a single space and end with '\n'. */
        void println(Object... objects) {
            for (int i = 0; i < objects.length; i++) {
                if (i != 0) writer.print(' ');
                writer.print(objects[i]);
            }
            writer.println();
        }

        void flush() {
            writer.flush();
        }

        void close() {
            writer.close();
        }
    }
}

/**
 *  CodingLegacy – refactored version
 *
 *  The original program performed the following steps for each test case:
 *   1. Read an integer n and a segment length k.
 *   2. Read an n×n grid of characters (`'B'` or `'W'`).
 *   3. Build a 2‑D prefix‑sum matrix that stores the number of `'B'` cells
 *      in any sub‑rectangle.
 *   4. Count how many *full* rows and columns contain no `'B'` at all.
 *   5. Determine, for every possible k‑length horizontal and vertical segment,
 *      whether that segment contains the same number of `'B'` cells as the
 *      whole row/column (i.e. the row/column is “filled”).  Those positions are
 *      marked in auxiliary `rowMark` and `colMark` matrices.
 *   6. Compute prefix‑sums of those mark‑matrices so that the number of marks
 *      inside any k×k window can be obtained in O(1).
 *   7. The answer for the test case is `ans + maxMarksInAnyKxKWindow`.
 *
 *  The refactored version isolates I/O, the algorithmic core, and constant
 *  definitions into separate, well‑named classes and methods.  Magic numbers
 *  are replaced by named constants, variable names describe their purpose,
 *  and the code is split into small, testable units.
 */
public class CodingLegacy {

    /* ---------- constants used throughout the algorithm ---------- */
    private static final long MOD = 1_000_000_007L;   // not used in the current logic – kept for compatibility
    private static final long MOD2 = 998_244_353L;    // not used in the current logic – kept for compatibility
    private static final long MAX_LONG = Long.MAX_VALUE; // not used – kept for compatibility
    private static final char SEPARATOR = ' ';

    /** Entry point */
    public static void main(String[] args) {
        InputReader reader = new InputReader(System.in);
        OutputWriter writer = new OutputWriter(System.out);

        int testCases = reader.nextInt();               // original code forced t = 1
        for (int tc = 1; tc <= testCases; tc++) {
            solveCase(tc, reader, writer);
        }

        writer.close();
    }

    /** Solves a single test case and prints the result. */
    private static void solveCase(int testNumber, InputReader reader, OutputWriter writer) {
        int n = reader.nextInt();   // size of the grid
        int k = reader.nextInt();   // length of the segment we are interested in

        // ----- read the grid -------------------------------------------------
        char[][] grid = new char[n][];
        for (int i = 0; i < n; i++) {
            grid[i] = reader.next().toCharArray();
        }

        // ----- 2‑D prefix sum of 'B' cells -----------------------------------
        int[][] prefix = buildPrefix(grid, n);

        // ----- step 4 – count rows / columns that are completely 'W' --------
        int rowsWithoutB = countEmptyRows(prefix, n);
        int colsWithoutB = countEmptyColumns(prefix, n);
        int ans = rowsWithoutB + colsWithoutB;

        // ----- steps 5‑6 – mark viable horizontal / vertical k‑segments -------
        int[][] rowMark = new int[n + 1][n + 1];
        int[][] colMark = new int[n + 1][n + 1];

        // horizontal marks
        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= n; j++) {
                if (hasIdenticalBCount(prefix, i, j, i, j + k - 1, n)
                        && getBCount(prefix, i, 1, i, n, n) != 0) {
                    rowMark[i][j] = 1;
                }
            }
        }

        // vertical marks
        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= n; j++) {
                if (hasIdenticalBCount(prefix, i, j, i + k - 1, j, n)
                        && getBCount(prefix, 1, j, n, j, n) != 0) {
                    colMark[i][j] = 1;
                }
            }
        }

        // build prefix‑sums of the marks so that a k×k window can be summed fast
        int[][] rowPrefix = buildPrefixInt(rowMark, n);
        int[][] colPrefix = buildPrefixInt(colMark, n);

        // ----- step 7 – maximum marks inside any k×k window -----------------
        int maxMarksInKxK = computeMaximumMarks(rowPrefix, colPrefix, n, k);

        // ----- final answer --------------------------------------------------
        writer.println(ans + maxMarksInKxK);
    }

    /* ---------- helper methods that implement the algorithm ---------- */

    /** Builds a 2‑D prefix‑sum matrix of the number of `'B'` cells. */
    private static int[][] buildPrefix(char[][] grid, int n) {
        int[][] pref = new int[n + 1][n + 1];
        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= n; j++) {
                int cur = grid[i - 1][j - 1] == 'B' ? 1 : 0;
                pref[i][j] = pref[i - 1][j] + pref[i][j - 1] - pref[i - 1][j - 1] + cur;
            }
        }
        return pref;
    }

    /** Returns the number of `'B'` cells inside the rectangle
     *  (l1, r1) – (l2, r2) inclusive, using 1‑based coordinates. */
    private static int getBCount(int[][] pref, int l1, int r1, int l2, int r2, int limit) {
        l2 = Math.min(l2, limit);
        r2 = Math.min(r2, limit);
        return pref[l2][r2] - pref[l1 - 1][r2] - pref[l2][r1 - 1] + pref[l1 - 1][r1 - 1];
    }

    /** Checks whether the sub‑rectangle from (r1,c1) to (r2,c2) contains the
     *  same number of `'B'` cells as the whole row `r1` (i.e. the row is
     *  completely filled). */
    private static boolean hasIdenticalBCount(int[][] pref, int r1, int c1, int r2, int c2, int limit) {
        return getBCount(pref, r1, c1, r2, c2, limit)
                == getBCount(pref, r1, 1, r1, limit, limit);
    }

    /** Counts rows that consist entirely of `'W'` (i.e. contain zero `'B'`). */
    private static int countEmptyRows(int[][] pref, int n) {
        int cnt = 0;
        for (int i = 1; i <= n; i++) {
            if (getBCount(pref, i, 1, i, n, n) == 0) {
                cnt++;
            }
        }
        return cnt;
    }

    /** Counts columns that consist entirely of `'W'`. */
    private static int countEmptyColumns(int[][] pref, int n) {
        int cnt = 0;
        for (int j = 1; j <= n; j++) {
            if (getBCount(pref, 1, j, n, j, n) == 0) {
                cnt++;
            }
        }
        return cnt;
    }

    /** Builds an integer prefix‑sum matrix from a 0/1 mark matrix. */
    private static int[][] buildPrefixInt(int[][] mark, int size) {
        int[][] pref = new int[size + 1][size + 1];
        for (int i = 1; i <= size; i++) {
            for (int j = 1; j <= size; j++) {
                pref[i][j] = pref[i - 1][j] + pref[i][j - 1] - pref[i - 1][j - 1] + mark[i][j];
            }
        }
        return pref;
    }

    /** Returns the maximum number of marks that can be found inside any
     *  k×k window of the grid.  The window is defined by its top‑left corner
     *  (i, j) and extends k cells downwards / rightwards. */
    private static int computeMaximumMarks(int[][] rowPref, int[][] colPref, int n, int k) {
        int best = 0;
        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= n; j++) {
                int rowEnd = Math.min(n, i + k - 1);
                int colEnd = Math.min(n, j + k - 1);

                int rowSum = rowPref[rowEnd][j] - rowPref[i - 1][j];
                int colSum = colPref[i][colEnd] - colPref[i][j - 1];

                best = Math.max(best, rowSum + colSum);
            }
        }
        return best;
    }
}

/* --------------------------------------------------------------------- */
/* --------------------------- I/O CLASSES --------------------------- */
/* --------------------------------------------------------------------- */

/**
 * Fast scanner that works with a small byte buffer.
 * It mimics the behaviour of the original {@code ScanReader} but is
 * considerably simpler and does not expose internal implementation details.
 */
final class InputReader {
    private final byte[] buffer = new byte[16 * 1024];
    private int pointer = 0;
    private int length = 0;
    private final InputStream stream;

    InputReader(InputStream stream) {
        this.stream = stream;
    }

    private int readByte() throws IOException {
        if (pointer >= length) {
            length = stream.read(buffer);
            pointer = 0;
            if (length <= 0) {
                return -1;
            }
        }
        return buffer[pointer++];
    }

    private static boolean isSpaceChar(int c) {
        return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
    }

    /** Reads next non‑space character. */
    private int nextNonSpace() throws IOException {
        int c;
        while (isSpaceChar(c = readByte())) ;
        return c;
    }

    /** Reads a signed 32‑bit integer. */
    int nextInt() throws IOException {
        int sign = 1;
        int c = nextNonSpace();
        if (c == '-') {
            sign = -1;
            c = nextNonSpace();
        }
        int result = 0;
        while (!isSpaceChar(c) && c >= '0' && c <= '9') {
            result = result * 10 + (c - '0');
            c = nextNonSpace();
        }
        return result * sign;
    }

    /** Reads a string terminated by whitespace. */
    String next() throws IOException {
        StringBuilder sb = new StringBuilder();
        int c = nextNonSpace();
        while (!isSpaceChar(c)) {
            sb.append((char) c);
            c = nextNonSpace();
        }
        return sb.toString();
    }
}

/**
 * Simple wrapper around {@link PrintWriter} that provides a clean `close()`
 * method and avoids exposing the underlying stream.
 */
final class OutputWriter {
    private final PrintWriter writer;

    OutputWriter(OutputStream stream) {
        this.writer = new PrintWriter(stream);
    }

    void println(Object obj) {
        writer.println(obj);
    }

    void close() {
        writer.close();
    }
}

package cf578d;

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.ArrayList;
import java.util.List;
import java.util.StringTokenizer;

/**
 * Solution for Codeforces problem 578D – “K-Coloring”.
 * The program reads an {@code n × n} grid consisting of characters 'B' and 'W'.
 * It computes the maximal number of rows and columns that become completely
 * black after applying at most one horizontal/vertical strip of height/width {@code k}
 * (the strip may be placed anywhere, but only rows/columns whose black cells fit
 * into a window of size {@code k} are considered).
 */
public class CF_578_D {

    /** Fast scanner used for all input operations. */
    private static final class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner() {
            this.br = new BufferedReader(new InputStreamReader(System.in));
        }

        /** Returns the next token from stdin (blocking until one is available). */
        private String nextToken() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(nextToken());
        }
    }

    /** Simple container that stores the inclusive start and end columns of a viable segment. */
    private static final class Segment {
        final int start;   // inclusive
        final int end;     // inclusive

        Segment(int start, int end) {
            this.start = start;
            this.end = end;
        }
    }

    /** Entry point of the program. */
    public static void main(String[] args) {
        CF_578_D solver = new CF_578_D();
        solver.solve();
    }

    /** Main algorithm – reads input, processes it and prints the answer. */
    void solve() {
        FastScanner fs = new FastScanner();
        int n = fs.nextInt();      // size of the board
        int k = fs.nextInt();      // maximum stripe length

        char[][] board = readBoard(n);
        int[] firstOccurrence = new int[n];   // first row (from top) that contains 'B' in each column
        int[] lastOccurrence  = new int[n];   // last  row (from top) that contains 'B' in each column
        Arrays.fill(firstOccurrence, -1);
        Arrays.fill(lastOccurrence, -1);

        fillOccurrences(board, firstOccurrence, lastOccurrence);

        // Number of rows that contain no black cell at all – they will always stay white.
        int rowsWithoutBlack = countRowsWithoutBlack(board);

        // For each row we store a segment (if any) of columns that can be covered by a stripe of height k.
        List<Segment> rowSegments = new ArrayList<>(n);
        for (int row = 0; row < n; row++) {
            String line = board[row];
            int firstB = line.indexOf('B');
            int lastB  = line.lastIndexOf('B');

            if (firstB < 0) {
                // row has no black cells – already counted in rowsWithoutBlack.
                rowSegments.add(null);
            } else if (lastB - firstB + 1 <= k) {
                // The black cells fit into a window of width k.
                int left = Math.max(lastB - k + 1, 0); // leftmost column that can cover the segment
                int right = firstB;                     // rightmost column that can cover the segment
                rowSegments.add(new Segment(left, right));
            } else {
                // Segment too wide – cannot be covered by any stripe of width k.
                rowSegments.add(null);
            }
        }

        /* ------------------------------------------------------------
         *  Sliding window over consecutive rows.
         *  `colPrefix` holds for every column j the number of currently
         *  covered rows whose black cells lie inside the moving row window.
         *  The window spans rows [i‑k+1 … i].
         * ------------------------------------------------------------ */
        int[] colPrefix = new int[n];
        int best = 0;

        for (int i = 0; i < n; i++) {
            // Add contribution of row i
            Segment curSeg = rowSegments.get(i);
            if (curSeg != null) {
                incrementPrefix(colPrefix, curSeg.start, curSeg.end, +1);
            }

            // Remove contribution of row i‑k (the row that just left the window)
            int leftBound = i - k + 1;
            if (leftBound > 0) {
                Segment prevSeg = rowSegments.get(leftBound - 1);
                if (prevSeg != null) {
                    incrementPrefix(colPrefix, prevSeg.start, prevSeg.end, -1);
                }
            }

            // Evaluate all possible column positions j where a vertical stripe can start.
            for (int j = 0; j < n; j++) {
                int colStart = j - k + 1;                // leftmost column of a vertical stripe of width k

                // Count columns whose black cells are completely inside the current row window.
                int columnsInsideWindow = countColumnsInsideWindow(firstOccurrence, lastOccurrence,
                                                                    i, colStart, j);

                // Maximum black cells reachable for this (i, j) pair.
                best = Math.max(best, colPrefix[j] + columnsInsideWindow);
            }
        }

        int answer = best + rowsWithoutBlack;
        System.out.println(answer);
    }

    /** Reads the board and fills the first/last occurrence arrays. */
    private static void fillOccurrences(char[][] board, int[] first, int[] last) {
        int n = board.length;
        for (int r = 0; r < n; r++) {
            String line = new String(board[r]);
            for (int c = 0; c < n; c++) {
                if (board[r][c] == 'B') {
                    if (first[c] == -1) {
                        first[c] = r;
                    }
                    last[c] = r;
                }
            }
        }
    }

    /** Counts rows that contain no 'B' at all. */
    private static int countRowsWithoutBlack(char[][] board) {
        int cnt = 0;
        outer:
        for (char[] row : board) {
            for (char cell : row) {
                if (cell == 'B') {
                    continue outer;
                }
            }
            cnt++;
        }
        return cnt;
    }

    /** Increments/decrements `arr` on the inclusive range [from … to] by `delta`. */
    private static void incrementPrefix(int[] arr, int from, int to, int delta) {
        for (int idx = from; idx <= to; idx++) {
            arr[idx] += delta;
        }
    }

    /**
     * Returns the number of columns whose whole black‑cell segment
     * lies inside the current moving row window (rows {@code [windowLow … i]}).
     *
     * @param first  first row that has a black cell in each column (or -1)
     * @param last   last row that has a black cell in each column (or -1)
     * @param i      upper bound of the window (inclusive)
     * @param windowLow  lower bound of the window (inclusive)
     * @param j      upper bound of the column window (inclusive)
     */
    private static int countColumnsInsideWindow(int[] first, int[] last,
                                                int i, int windowLow, int j) {
        int count = 0;
        // Direct columns that are inside the current row window.
        for (int col = 0; col <= j; col++) {
            if (first[col] >= windowLow && last[col] <= i) {
                count++;
            }
        }
        // Remove columns that were inside the previous window but are now outside.
        if (windowLow > 0) {
            int prevWindowLow = windowLow - 1;
            for (int col = 0; col < prevWindowLow; col++) {
                if (first[col] >= prevWindowLow && last[col] <= prevWindowLow) {
                    // If a column was only covered by the previous window, it disappears now.
                    // No explicit decrement needed – we simply do not count it.
                }
            }
        }
        return count;
    }
}

import java.io.*;
import java.util.Arrays;

/**
 * Entry point of the program.
 * Reads input, solves the problem and prints the answer.
 */
public class Main {

    public static void main(String[] args) throws IOException {
        // Use try‑with‑resources to guarantee streams are closed
        try (InputStream inStream = System.in;
             OutputStream outStream = System.out) {

            Input scanner = new Input(inStream);
            PrintWriter out = new PrintWriter(outStream);

            Solver solver = new Solver();
            solver.solve(scanner, out);

            out.flush();                     // make sure the output is written
        }
    }

    /** -----------------------------------------------------------
     *  Core logic that solves the problem.
     * ----------------------------------------------------------- */
    static class Solver {

        /** Solves one test case. */
        void solve(Input scanner, PrintWriter out) {
            final int n = scanner.readInt();   // size of the board
            final int k = scanner.readInt();   // side length of the square we may paint

            char[][] board = readBoard(scanner, n);

            // 1️⃣ rows / columns that are already completely white ('.')
            int alreadyEmpty = countCompletelyEmptyRowsAndColumns(board, n);

            // 2️⃣ difference array that will hold the “extra” rows we can create
            int[][] diff = new int[n][n + 1];

            // 3️⃣ contributions from rows that can become completely black
            addRowContributions(board, n, k, diff);

            // 4️⃣ contributions from columns that can become completely black
            addColumnContributions(board, n, k, diff);

            // 5️⃣ find the maximum number of rows we can turn completely black
            int bestExtra = findMaximumCoverage(diff);

            // 6️⃣ final answer = already empty rows/cols + best extra rows
            out.println(alreadyEmpty + bestExtra);
        }

        /** Reads the n × n board (each row is given as a single token). */
        private static char[][] readBoard(Input scanner, int n) throws IOException {
            char[][] board = new char[n][];
            for (int i = 0; i < n; i++) {
                board[i] = scanner.readWord().toCharArray();
            }
            return board;
        }

        /** Counts completely white rows and columns. */
        private static int countCompletelyEmptyRowsAndColumns(char[][] board, int n) {
            int count = 0;

            // rows
            for (char[] row : board) {
                if (isRowEmpty(row)) {
                    count++;
                }
            }

            // columns
            for (int col = 0; col < n; col++) {
                if (isColumnEmpty(board, col)) {
                    count++;
                }
            }
            return count;
        }

        private static boolean isRowEmpty(char[] row) {
            for (char cell : row) {
                if (cell == 'B') {
                    return false;
                }
            }
            return true;
        }

        private static boolean isColumnEmpty(char[][] board, int colIdx) {
            for (char[] row : board) {
                if (row[colIdx] == 'B') {
                    return false;
                }
            }
            return true;
        }

        /** Adds the effect of painting a k×k square on rows. */
        private static void addRowContributions(char[][] board, int n, int k, int[][] diff) {
            for (int row = 0; row < n; row++) {
                int minCol = findMinColumnWithBlack(board[row]);
                int maxCol = findMaxColumnWithBlack(board[row]);

                // Row already empty – nothing to add
                if (minCol == -1 && maxCol == -1) {
                    continue;
                }

                // If the black cells are spread over less than k columns,
                // we can possibly turn the whole row black by placing the square.
                if (maxCol - minCol + 1 < k) {
                    int columnStart = Math.max(maxCol - k + 1, 0);
                    int columnEnd   = Math.min(minCol + 1, n); // exclusive upper bound

                    // Try every possible vertical placement of the square that covers this row
                    for (int startRow = Math.max(row - k + 1, 0); startRow <= row; startRow++) {
                        if (startRow < 0 || startRow >= n) {
                            continue;
                        }
                        diff[startRow][columnStart] += 1;
                        if (columnEnd < n) {
                            diff[startRow][columnEnd] -= 1;
                        }
                    }
                }
            }
        }

        /** Adds the effect of painting a k×k square on columns. */
        private static void addColumnContributions(char[][] board, int n, int k, int[][] diff) {
            for (int col = 0; col < n; col++) {
                int minRow = -1, maxRow = -1;
                for (int row = 0; row < n; row++) {
                    if (board[row][col] == 'B') {
                        if (minRow == -1 || row < minRow) {
                            minRow = row;
                        }
                        if (maxRow == -1 || row > maxRow) {
                            maxRow = row;
                        }
                    }
                }

                // Column already empty – nothing to add
                if (minRow == -1 && maxRow == -1) {
                    continue;
                }

                // If the black cells are spread over less than k rows,
                // we can possibly turn the whole column black by placing the square.
                if (maxRow - minRow + 1 < k) {
                    int rowStart = Math.max(col - k + 1, 0);
                    int rowEnd   = Math.min(minRow + 1, n); // exclusive upper bound

                    // Try every possible horizontal placement of the square that covers this column
                    for (int startCol = Math.max(maxRow - k + 1, 0); startCol <= minRow; startCol++) {
                        if (startCol < 0 || startCol >= n) {
                            continue;
                        }
                        diff[startCol][rowStart] += 1;
                        if (rowEnd < n) {
                            diff[startCol][rowEnd] -= 1;
                        }
                    }
                }
            }
        }

        /** Finds the maximum value after turning the difference array into prefix sums. */
        private static int findMaximumCoverage(int[][] diff) {
            int best = 0;
            for (int i = 0; i < diff.length; i++) {
                int running = 0;
                for (int j = 0; j < diff[i].length - 1; j++) {
                    running += diff[i][j];
                    if (running > best) {
                        best = running;
                    }
                }
            }
            return best;
        }

        /** Returns the leftmost column that contains a black cell in the given row. */
        private static int findMinColumnWithBlack(char[] row) {
            int min = -1;
            for (int col = 0; col < row.length; col++) {
                if (row[col] == 'B') {
                    if (min == -1 || col < min) {
                        min = col;
                    }
                }
            }
            return min;
        }

        /** Returns the rightmost column that contains a black cell in the given row. */
        private static int findMaxColumnWithBlack(char[] row) {
            int max = -1;
            for (int col = 0; col < row.length; col++) {
                if (row[col] == 'B') {
                    if (max == -1 || col > max) {
                        max = col;
                    }
                }
            }
            return max;
        }
    }

    /** -----------------------------------------------------------
     *  Very small scanner that works with whitespace‑separated tokens.
     * ----------------------------------------------------------- */
    static class Input {
        private final BufferedReader reader;
        private String  currentLine = "";
        private int     pos          = 0;

        Input(InputStream source) {
            this.reader = new BufferedReader(new InputStreamReader(source));
        }

        /** Skips leading whitespace and returns the next token. */
        String readWord() throws IOException {
            skip();
            int start = pos;
            while (pos < currentLine.length() && !isSpace(currentLine.charAt(pos))) {
                pos++;
            }
            return currentLine.substring(start, pos);
        }

        /** Reads the next integer from the input. */
        int readInt() throws IOException {
            return Integer.parseInt(readWord());
        }

        /** Moves the cursor past whitespace. */
        private void skip() throws IOException {
            while (true) {
                if (pos >= currentLine.length()) {
                    currentLine = reader.readLine();
                    pos = 0;
                    if (currentLine == null) {
                        break;                      // EOF
                    }
                }
                while (pos < currentLine.length() && isSpace(currentLine.charAt(pos))) {
                    pos++;
                }
                if (pos < currentLine.length()) {
                    return;
                }
            }
        }

        private static boolean isSpace(char c) {
            return c <= ' ';
        }
    }
}

import java.io.*;
import java.util.StringTokenizer;

/**
 * Entry point of the application.
 * Reads input, runs the solver and prints the result.
 */
public class Main {

    public static void main(String[] args) {
        // Using try‑with‑resources ensures the streams are closed properly.
        try (InputStream in = System.in;
             PrintWriter out = new PrintWriter(System.out)) {

            Solver solver = new Solver();
            solver.solve(/* testCase = */ 1, new InputReader(in), out);
        }
    }
}

/**
 * Simple wrapper around {@link BufferedReader} that knows how to
 * read tokens, integers and whole lines from the input stream.
 */
class InputReader {
    private final BufferedReader br;
    private StringTokenizer st;

    InputReader(InputStream source) {
        this.br = new BufferedReader(new InputStreamReader(source));
    }

    /** Returns the next token from the underlying {@link StringTokenizer}. */
    private String nextToken() throws IOException {
        while (st == null || !st.hasMoreTokens()) {
            String line = br.readLine();
            if (line == null) {
                return null;
            }
            st = new StringTokenizer(line);
        }
        return st.nextToken();
    }

    /** Convenience method – reads the next integer token. */
    int nextInt() throws IOException {
        return Integer.parseInt(nextToken());
    }

    /** Reads the next complete line (used for reading the board). */
    String readLine() throws IOException {
        return br.readLine();
    }
}

/**
 * Core algorithm implementation.
 * All public methods are kept small and focused on a single responsibility.
 */
class Solver {

    /**
     * Solves a single test case.
     *
     * @param testIndex ignored (the original code used only one test case)
     * @param reader    input reader
     * @param out       output writer
     */
    void solve(int testIndex, InputReader reader, PrintWriter out) {
        int boardSize = reader.nextInt();   // n
        int brushLength = reader.nextInt();  // k
        char[][] board = readBoard(reader, boardSize);

        // -----------------------------------------------------------------
        // 1️⃣  Count black cells per row / column and how many rows/cols are already empty
        // -----------------------------------------------------------------
        int[] blackPerRow   = countBlackPerRow(board);
        int[] blackPerCol   = countBlackPerColumn(board);
        int alreadyWhite    = countZeroEntries(blackPerRow) + countZeroEntries(blackPerCol);

        // -----------------------------------------------------------------
        // 2️⃣  Determine which rows / columns can be completely covered by a single brush stroke
        // -----------------------------------------------------------------
        boolean[][] rowCoverMask  = findCoverSegments(board, true,  boardSize, brushLength, blackPerRow);
        boolean[][] colCoverMask  = findCoverSegments(board, false, boardSize, brushLength, blackPerCol);

        // Convert the boolean masks to integer masks that can be summed up.
        int[][] rowMask  = booleanArrayToInt(rowCoverMask);
        int[][] colMask  = booleanArrayToInt(colCoverMask);

        // -----------------------------------------------------------------
        // 3️⃣  Build coverage matrices – how many coverable rows/cols intersect each possible brush position
        // -----------------------------------------------------------------
        int[][] rowCoverage = slidingWindowSum(rowMask, boardSize, brushLength);
        int[][] colCoverage = slidingWindowSum(colMask, boardSize, brushLength);

        // -----------------------------------------------------------------
        // 4️⃣  Find the placement that maximises (coveredRows + coveredColumns)
        // -----------------------------------------------------------------
        long bestCombined = 0;
        for (int i = 0; i <= boardSize - brushLength; i++) {
            for (int j = 0; j <= boardSize - brushLength; j++) {
                bestCombined = Math.max(bestCombined,
                        rowCoverage[i][j] + colCoverage[i][j]);
            }
        }

        // The answer is the best combined coverage plus the rows/cols that were already white.
        out.println(bestCombined + alreadyWhite);
    }

    /** Reads the whole board (n × n characters) from the supplied reader. */
    private static char[][] readBoard(InputReader reader, int n) throws IOException {
        char[][] board = new char[n][];
        for (int i = 0; i < n; i++) {
            board[i] = reader.readLine().toCharArray();
        }
        return board;
    }

    /** Returns an array with the number of ‘B’ cells in each row. */
    private static int[] countBlackPerRow(char[][] board) {
        int n = board.length;
        int[] result = new int[n];
        for (int r = 0; r < n; r++) {
            int cnt = 0;
            for (char cell : board[r]) {
                if (cell == 'B') cnt++;
            }
            result[r] = cnt;
        }
        return result;
    }

    /** Returns an array with the number of ‘B’ cells in each column. */
    private static int[] countBlackPerColumn(char[][] board) {
        int n = board.length;
        int[] result = new int[n];
        for (int c = 0; c < n; c++) {
            int cnt = 0;
            for (int r = 0; r < n; r++) {
                if (board[r][c] == 'B') cnt++;
            }
            result[c] = cnt;
        }
        return result;
    }

    /** Counts how many elements of the given array are equal to zero. */
    private static int countZeroEntries(int[] arr) {
        int zero = 0;
        for (int v : arr) {
            if (v == 0) zero++;
        }
        return zero;
    }

    /**
     * For a given direction (row‑wise or column‑wise) determines, for each
     * possible start index of a k‑length segment, whether that segment
     * contains **all** black cells belonging to its row (or column).
     * <p>
     * The returned matrix has shape {@code [start][0]}, where {@code start}
     * corresponds to the first column (or row) of the segment.
     */
    private static boolean[][] findCoverSegments(char[][] board,
                                                 boolean byRow,
                                                 int n,
                                                 int k,
                                                 int[] blackCount) {
        boolean[][] mask = new boolean[n][1];               // only column 0 is used
        for (int i = 0; i <= n - k; i++) {
            int covered = 0;

            // First window (positions i … i+k‑1)
            for (int j = 0; j < k; j++) {
                if (byRow) {
                    if (board[i][j] == 'B') covered++;
                } else {
                    if (board[j][i] == 'B') covered++;
                }
            }
            mask[i][0] = covered == blackCount[i] && blackCount[i] != 0;

            // Slide the window across the board
            for (int start = 1; start <= n - k; start++) {
                if (byRow) {
                    if (board[start - 1][i] == 'B') covered--;
                    if (board[start + k - 1][i] == 'B') covered++;
                } else {
                    if (board[start - 1][i] == 'B') covered--;
                    if (board[start + k - 1][i] == 'B') covered++;
                }
                mask[start][0] = covered == blackCount[start] && blackCount[start] != 0;
            }
        }
        return mask;
    }

    /** Turns a boolean mask into an integer mask (needed for prefix sums). */
    private static int[][] booleanArrayToInt(boolean[][] src) {
        int n = src.length;
        int[][] dst = new int[n][n];
        for (int i = 0; i <= n - 1; i++) {
            dst[i][0] = src[i][0] ? 1 : 0;
        }
        return dst;
    }

    /**
     * Computes a coverage matrix where {@code result[i][j]} equals the
     * number of covered rows/columns that intersect the k‑length window
     * starting at row {@code i}.
     * <p>
     * This mirrors the original algorithm’s “ansR / ansC” accumulation
     * but is written as a reusable, self‑contained method.
     */
    private static int[][] slidingWindowSum(int[][] mask, int n, int k) {
        int[][] result = new int[n][n];
        if (n == 0) return result;

        // Initialise the first horizontal window (first k rows)
        for (int col = 0; col < n; col++) {
            int total = 0;
            for (int row = 0; row < k; row++) {
                total += mask[row][col];
            }
            result[0][col] = total;
        }

        // Slide the window vertically
        for (int start = 1; start <= n - k; start++) {
            for (int col = 0; col < n; col++) {
                result[start][col] = result[start - 1][col];
                if (mask[start - 1][col] == 1) result[start][col]--;
                if (mask[start + k - 1][col] == 1) result[start][col]++;
            }
        }
        return result;
    }
}

/**
 * Refactored solution for the “D – Square” problem.
 * The program reads an N×N grid consisting of ‘B’ (black) and ‘W’ (white) cells,
 * selects a k×k square, contains the maximum number of already‑filled rows
 * and columns, and prints that maximum value.
 *
 * The code has been reorganised for readability, maintainability and
 * correctness while preserving the original algorithmic behaviour.
 */
import java.io.*;
import java.util.*;

public class Main {

    /** Fast output writer – automatically flushed at the end of the program. */
    private static final PrintWriter OUT = new PrintWriter(System.out, true);

    /** Simple scanner that works with byte buffers for speed. */
    private static final class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner() { this(System.in); }

        FastScanner(InputStream in) { this.in = in; }

        private int readByte() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c, sign = 1, val = 0;
            do { c = readByte(); } while (c <= ' ');
            if (c == '-') { sign = -1; c = readByte(); }
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = readByte();
            }
            return val * sign;
        }

        String nextString() throws IOException {
            int c;
            do { c = readByte(); } while (c <= ' ');
            StringBuilder sb = new StringBuilder();
            do {
                sb.append((char) c);
                c = readByte();
            } while (c > ' ');
            return sb.toString();
        }
    }

    /** Encapsulates all logic for a single test case. */
    private static final class Solver {
        /** Size of the board (N) and side of the movable square (K). */
        private int n, k;

        /** For each row: leftmost and rightmost column that contains a ‘B’.
            If a row has no ‘B’, both entries stay {@code n}. */
        private int[][] rowBounds;

        /** For each column: topmost and bottommost row that contains a ‘B’.
            If a column has no ‘B’, both entries stay {@code n}. */
        private int[][] colBounds;

        /** Number of completely empty rows plus empty columns. */
        private int emptyLines;

        /** Entry point of the solving process. */
        void solve() {
            readInput();
            if (n == k) {
                OUT.println(2 * n);
                return;
            }
            computeEmptyLines();
            int best = 0;
            for (int top = 0; top <= n - k; ++top) {
                for (int left = 0; left <= n - k; ++left) {
                    int rowsCovered = countRowsCovered(top, left);
                    int colsCovered = countColsCovered(top, left);
                    int score = emptyLines + rowsCovered + colsCovered;
                    best = Math.max(best, score);
                }
            }
            OUT.println(best);
        }

        /** Reads the whole input and fills {@code rowBounds} and {@code colBounds}. */
        private void readInput() {
            n = nextInt();
            k = nextInt();

            // allocate fresh arrays for the current test case
            rowBounds = new int[n][2];
            colBounds = new int[n][2];

            // initialise with “empty” sentinel values
            for (int i = 0; i < n; ++i) {
                rowBounds[i][0] = n;   // left  = n (larger than any legal index)
                rowBounds[i][1] = -1;  // right = -1 (smaller than any legal index)
                colBounds[i][0] = n;   // top   = n
                colBounds[i][1] = -1;  // bottom= -1
            }

            for (int r = 0; r < n; ++r) {
                String line = nextString();
                for (int c = 0; c < n; ++c) {
                    if (line.charAt(c) == 'B') {
                        // update row information
                        rowBounds[r][0] = Math.min(rowBounds[r][0], c);
                        rowBounds[r][1] = Math.max(rowBounds[r][1], c);
                        // update column information
                        colBounds[c][0] = Math.min(colBounds[c][0], r);
                        colBounds[c][1] = Math.max(colBounds[c][1], r);
                    }
                }
            }
        }

        /** Counts how many rows and columns contain no black cells. */
        private void computeEmptyLines() {
            emptyLines = 0;
            for (int i = 0; i < n; ++i) {
                if (rowBounds[i][0] == n)   // row i has no ‘B’
                    emptyLines++;
                if (colBounds[i][0] == n)   // column i has no ‘B’
                    emptyLines++;
            }
        }

        /**
         * Returns the number of rows that lie completely inside the
         * vertical window [{@code top} … {@code top}+k-1] and whose
         * black cells are also fully contained horizontally inside the
         * window starting at {@code left}.
         */
        private int countRowsCovered(int top, int left) {
            int right = left + k - 1;
            int covered = 0;
            for (int r = top; r < top + k; ++r) {
                if (rowBounds[r][0] == n) continue;                     // empty row
                if (rowBounds[r][0] >= left && rowBounds[r][1] <= right)
                    ++covered;
            }
            return covered;
        }

        /**
         * Returns the number of columns that lie completely inside the
         * horizontal window [{@code left} … {@code left}+k-1] and whose
         * black cells are also fully contained vertically inside the
         * window starting at {@code top}.
         */
        private int countColsCovered(int top, int left) {
            int bottom = top + k - 1;
            int covered = 0;
            for (int c = left; c < left + k; ++c) {
                if (colBounds[c][0] == n) continue;                     // empty column
                if (colBounds[c][0] >= top && colBounds[c][1] <= bottom)
                    ++covered;
            }
            return covered;
        }

        /** Minimal helper to forward the scanner calls used inside Solver. */
        private int nextInt() throws IOException { return SolverScanners.fast.nextInt(); }
        private String nextString() throws IOException { return SolverScanners.fast.nextString(); }

        /** Simple wrapper to keep the static scanner instance hidden from Solver. */
        private static final class SolverScanners {
            static final FastScanner fast = new FastScanner();
        }
    }

    /** Program entry point. */
    public static void main(String[] args) throws Exception {
        new Solver().solve();
        OUT.close();
    }
}

/**
 * Solution for the “Maximum number of empty lines after removing a k×k block” problem.
 *
 * <p>The program reads an {@code n×n} grid consisting of the characters {@code 'B'} (blocked)
 * and {@code '.'} (free).  It then finds the largest possible number of rows or columns that
 * become completely empty after deleting any contiguous {@code k×k} sub‑grid.</p>
 *
 * <p>All input handling is performed with a fast scanner, the grid processing is isolated
 * in dedicated methods, and the main algorithm is split into small, well‑named helpers.
 * The code follows modern Java coding conventions and avoids mutable static fields.</p>
 */
public class Main {

    /** Fast scanner that reads tokens from {@code System.in}. */
    private static final class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner() {
            this.br = new BufferedReader(new InputStreamReader(System.in));
            this.st = null;
        }

        /** Returns the next token from {@code System.in}. */
        private String nextToken() throws IOException {
            while (st == null || !st.hasMoreElements()) {
                st = new StringTokenizer(br.readLine());
            }
            return st.nextToken();
        }

        /** Reads an {@code int}. */
        int nextInt() throws IOException {
            return Integer.parseInt(nextToken());
        }

        /** Reads a {@code long}. */
        long nextLong() throws IOException {
            return Long.parseLong(nextToken());
        }

        /** Reads a {@code double}. */
        double nextDouble() throws IOException {
            return Double.parseDouble(nextToken());
        }

        /** Reads a whole line (may be {@code null} on EOF). */
        String nextLine() throws IOException {
            String line = br.readLine();
            return line == null ? "" : line;
        }
    }

    /** Helper that stores intermediate prefix counts used by the sliding‑window algorithm. */
    private static final class PrefixCounters {
        /** Vertical prefix array: number of consecutive 'B' from the top in each column. */
        final int[][] vertical;
        /** Horizontal prefix array: number of consecutive 'B' from the left in each row. */
        final int[][] horizontal;

        PrefixCounters(int[][] vertical, int[][] horizontal) {
            this.vertical = vertical;
            this.horizontal = horizontal;
        }
    }

    public static void main(String[] args) throws IOException {
        FastScanner sc = new FastScanner();
        int n = sc.nextInt();           // size of the square matrix
        int k = sc.nextInt();           // side length of the removable block
        char[][] grid = readGrid(sc, n);

        // 1️⃣ Compute auxiliary prefix arrays.
        PrefixCounters counters = computePrefixCounters(grid, n);

        // 2️⃣ Count completely empty rows and columns.
        int emptyColumnCount = countEmptyColumns(counters.vertical);
        int emptyRowCount      = countEmptyRows(counters.horizontal);
        int baseEmptyCount     = emptyColumnCount + emptyRowCount;   // 'ic' from the original code

        // 3️⃣ Sliding‑window: try every k×k block and compute how many additional
        //    lines become empty when that block is removed.
        int answer = computeMaximumEmptyLines(grid, n, k, counters, baseEmptyCount);

        // 4️⃣ Output result.
        System.out.println(answer);
    }

    /** Reads the {@code n×n} character grid from the scanner. */
    private static char[][] readGrid(FastScanner sc, int n) {
        char[][] matrix = new char[n][];
        for (int i = 0; i < n; i++) {
            String line = sc.nextLine().trim();
            matrix[i] = line.toCharArray();
        }
        return matrix;
    }

    /** Builds two prefix arrays:
     *  <ul>
     *      <li>vertical[i][j] = number of consecutive 'B' in column {@code j} from row 0 up to row {@code i}.</li>
     *      <li>horizontal[i][j] = number of consecutive 'B' in row {@code i} from column 0 up to column {@code j}.</li>
     *  </ul>
     */
    private static PrefixCounters computePrefixCounters(char[][] grid, int n) {
        int[][] vertical = new int[n][n];
        int[][] horizontal = new int[n][n];

        // ---- vertical prefix -------------------------------------------------
        for (int col = 0; col < n; col++) {
            for (int row = 0; row < n; row++) {
                if (grid[row][col] == 'B') {
                    vertical[row][col] = (row == 0) ? 1 : vertical[row - 1][col] + 1;
                } else {
                    vertical[row][col] = (row == 0) ? 0 : vertical[row - 1][col];
                }
            }
        }

        // ---- horizontal prefix -----------------------------------------------
        for (int row = 0; row < n; row++) {
            for (int col = 0; col < n; col++) {
                if (grid[row][col] == 'B') {
                    horizontal[row][col] = (col == 0) ? 1 : horizontal[row][col - 1] + 1;
                } else {
                    horizontal[row][col] = (col == 0) ? 0 : horizontal[row][col - 1];
                }
            }
        }

        return new PrefixCounters(vertical, horizontal);
    }

    /** Counts how many columns contain no 'B' at all (i.e. bottom cell is 0). */
    private static int countEmptyColumns(int[][] vertical) {
        int count = 0;
        int n = vertical.length;
        for (int col = 0; col < n; col++) {
            if (vertical[n - 1][col] == 0) {
                count++;
            }
        }
        return count;
    }

    /** Counts how many rows contain no 'B' at all (i.e. rightmost cell is 0). */
    private static int countEmptyRows(int[][] horizontal) {
        int count = 0;
        int n = horizontal.length;
        for (int row = 0; row < n; row++) {
            if (horizontal[row][n - 1] == 0) {
                count++;
            }
        }
        return count;
    }

    /**
     * Slides a {@code k×k} window over the matrix and returns the maximum number of
     * lines that become empty after removing the block.
     *
     * <p>The method mirrors the original algorithm but is written with clear variable
     * names and small helper lambdas to avoid duplicated logic.</p>
     */
    private static int computeMaximumEmptyLines(
            char[][] grid,
            int n,
            int k,
            PrefixCounters counters,
            int baseEmptyCount) {

        // Prefix sums that allow O(1) range queries for the “contribution” of each column / row.
        int[][] columnContribution = new int[n][n];
        int[][] rowContribution     = new int[n][n];

        // ---- column contribution (vertical) ----------------------------------
        for (int row = k - 1; row < n; row++) {
            for (int col = 0; col < n; col++) {
                int inc = 0;
                // Does the whole column inside the current sliding window stay empty?
                boolean columnFullyEmpty = isWindowColumnFullyEmpty(
                        col, row, k, counters.vertical);
                if (columnFullyEmpty) {
                    inc = 1;
                }
                columnContribution[row][col] = inc;
                if (col > 0) {
                    columnContribution[row][col] += columnContribution[row][col - 1];
                }
            }
        }

        // ---- row contribution (horizontal) -----------------------------------
        for (int col = k - 1; col < n; col++) {
            for (int row = 0; row < n; row++) {
                int inc = 0;
                boolean rowFullyEmpty = isWindowRowFullyEmpty(
                        row, col, k, counters.horizontal);
                if (rowFullyEmpty) {
                    inc = 1;
                }
                rowContribution[row][col] = inc;
                if (row > 0) {
                    rowContribution[row][col] += rowContribution[row - 1][col];
                }
            }
        }

        // ---- evaluate every possible k×k block --------------------------------
        int maxEmpty = baseEmptyCount;
        for (int bottomRow = k - 1; bottomRow < n; bottomRow++) {
            for (int rightCol = k - 1; rightCol < n; rightCol++) {
                int emptyLines = baseEmptyCount;

                // columns that are completely empty inside the current k×k block
                int colSum = columnSum(columnContribution, bottomRow, rightCol, k);
                emptyLines += colSum;

                // rows that are completely empty inside the current k×k block
                int rowSum = rowSum(rowContribution, bottomRow, rightCol, k);
                emptyLines += rowSum;

                // update the best answer
                if (emptyLines > maxEmpty) {
                    maxEmpty = emptyLines;
                }
            }
        }
        return maxEmpty;
    }

    /** Checks whether a given column inside the sliding window stays completely empty. */
    private static boolean isWindowColumnFullyEmpty(
            int col, int bottomRow, int k, int[][] vertical) {

        int topRow = bottomRow - k + 1;
        // If the whole column up to bottomRow is filled with B, but we are interested in
        // the *absence* of B, we check the length of the prefix at the top of the window.
        // In the original code this was expressed as:
        //   dpv[bottomRow][col] - dpv[topRow-1][col] == dpv[n-1][col] && dpv[n-1][col] > 0
        // We simplify the condition to “the prefix height at the bottom equals the prefix
        // height at the top of the window”, meaning the column does not contain any '.'.
        if (topRow == 0) {
            return vertical[bottomRow][col] == vertical[n - 1][col] && vertical[n - 1][col] > 0;
        }
        return vertical[bottomRow][col] - vertical[topRow - 1][col] == vertical[n - 1][col] && vertical[n - 1][col] > 0;
    }

    /** Checks whether a given row inside the sliding window stays completely empty. */
    private static boolean isWindowRowFullyEmpty(
            int row, int rightCol, int k, int[][] horizontal) {

        int leftCol = rightCol - k + 1;
        if (leftCol == 0) {
            return horizontal[row][rightCol] == horizontal[row][n - 1] && horizontal[row][n - 1] > 0;
        }
        return horizontal[row][rightCol] - horizontal[row][leftCol - 1] == horizontal[row][n - 1] && horizontal[row][n - 1] > 0;
    }

    /** Returns the sum of a k‑long segment that ends at {@code idx} in the supplied prefix array. */
    private static int columnSum(int[][] prefix, int bottomRow, int rightCol, int k) {
        int idx = rightCol;
        return (idx >= k ? prefix[bottomRow][idx] - prefix[bottomRow][idx - k] : prefix[bottomRow][idx]);
    }

    /** Returns the sum of a k‑long segment that ends at {@code idx} in the supplied prefix array. */
    private static int rowSum(int[][] prefix, int bottomRow, int rightCol, int k) {
        int idx = bottomRow;
        return (idx >= k ? prefix[idx][rightCol] - prefix[idx - k][rightCol] : prefix[idx][rightCol]);
    }
}

import java.io.*;
import java.util.*;
import java.util.stream.*;

public class Main {

    /** Fast scanner that works with both file and stdin input. */
    private static final class FastScanner {
        private final BufferedInputStream in;
        private final StringTokenizer st;

        FastScanner(InputStream source) {
            this.in = new BufferedInputStream(source);
            this.st = new StringTokenizer("");
        }

        /** Fill the tokenizer with the next line (or the current one if still has tokens). */
        private void ensureTokens() throws IOException {
            while (!st.hasMoreTokens()) {
                st = new StringTokenizer(new StringReader(new BufferedReader(new InputStreamReader(in)).readLine()));
            }
        }

        /** Return next token as a string. */
        String nextToken() throws IOException {
            ensureTokens();
            return st.nextToken();
        }

        /** Read next integer. */
        int nextInt() throws IOException {
            return Integer.parseInt(nextToken());
        }

        /** Read next string (used for the board line). */
        String nextString() throws IOException {
            ensureTokens();
            return st.nextToken();
        }
    }

    /** Reads the whole board and returns it as a 2‑D int array (1 = marked, 0 = unmarked). */
    private static int[][] readBoard(FastScanner fs) throws IOException {
        int n = fs.nextInt();
        int k = fs.nextInt();
        int[][] grid = new int[n][n];
        for (int i = 0; i < n; i++) {
            String line = fs.nextString();
            for (int j = 0; j < n; j++) {
                grid[i][j] = (line.charAt(j) == 'B') ? 1 : 0;
            }
        }
        return grid;
    }

    /** Returns true if column j in row i belongs to a window that can cover all 1's of that row. */
    private static boolean rowWindowCanCover(int[] row, int left, int right, int start, int k) {
        return start <= left && start + k - 1 >= right;
    }

    /** Returns true if row i in column j belongs to a window that can cover all 1's of that column. */
    private static boolean colWindowCanCover(int[][] grid, int col, int top, int bottom, int start, int k) {
        return start <= top && start + k - 1 >= bottom;
    }

    /** Computes a matrix where each entry (i, j) marks whether a horizontal window of height k starting at row i
        covers all marked cells of row i in column range j…j+k‑1. */
    private static int[][] computeHorizontalCovers(int[][] grid, int k) {
        int n = grid.length;
        int width = n - k + 1;
        int[][] hor = new int[n][width];

        for (int i = 0; i < n; i++) {
            int left = -1, right = -1;
            // find first and last marked cell in this row
            for (int j = 0; j < n; j++) {
                if (grid[i][j] == 1) { left = j; break; }
            }
            for (int j = n - 1; j >= 0; j--) {
                if (grid[i][j] == 1) { right = j; break; }
            }

            if (left == -1) { // row is empty – nothing to cover
                continue;
            }

            for (int start = 0; start < width; start++) {
                if (rowWindowCanCover(grid[i], left, right, start, k)) {
                    hor[i][start] = 1;
                }
            }
        }
        return hor;
    }

    /** Computes the analogous matrix for vertical windows. */
    private static int[][] computeVerticalCovers(int[][] grid, int k) {
        int n = grid.length;
        int height = n - k + 1;
        int[][] ver = new int[height][n];

        for (int j = 0; j < n; j++) {
            int top = -1, bottom = -1;
            // find first and last marked cell in this column
            for (int i = 0; i < n; i++) {
                if (grid[i][j] == 1) { top = i; break; }
            }
            for (int i = n - 1; i >= 0; i--) {
                if (grid[i][j] == 1) { bottom = i; break; }
            }

            if (top == -1) { // column is empty
                continue;
            }

            for (int start = 0; start < height; start++) {
                if (colWindowCanCover(grid, j, top, bottom, start, k)) {
                    ver[start][j] = 1;
                }
            }
        }
        return ver;
    }

    /** Returns a 2‑D prefix‑sum array that gives, for each window start (i, j), the sum of the
        corresponding column of the supplied matrix. */
    private static int[][] computeColumnWindowSums(int[][] matrix, int windowSize) {
        int nRows = matrixRows(matrix, windowSize); // number of possible start rows
        int nCols = matrixCols(matrix[0]);          // number of columns in the source matrix
        int[][] sums = new int[nRows][nCols];

        // initialise first window
        for (int col = 0; col < nCols; col++) {
            int sum = 0;
            for (int r = 0; r < windowSize; r++) {
                sum += matrix[r][col];
            }
            sums[0][col] = sum;
        }

        // slide the window downwards
        for (int start = 1; start < nRows; start++) {
            for (int col = 0; col < nCols; col++) {
                sums[start][col] = sums[start - 1][col]
                        - matrix[start - 1][col]
                        + matrix[start + windowSize - 1][col];
            }
        }
        return sums;
    }

    /** Counts empty rows and empty columns (rows/columns that contain no ‘1’). */
    private static int countEmptyRowsAndColumns(int[][] grid) {
        int emptyRows = 0;
        int emptyCols = 0;
        int n = grid.length;

        // empty rows
        for (int i = 0; i < n; i++) {
            boolean hasMark = false;
            for (int j = 0; j < n; j++) {
                if (grid[i][j] == 1) {
                    hasMark = true;
                    break;
                }
            }
            if (!hasMark) emptyRows++;
        }

        // empty columns
        for (int j = 0; j < n; j++) {
            boolean hasMark = false;
            for (int i = 0; i < n; i++) {
                if (grid[i][j] == 1) {
                    hasMark = true;
                    break;
                }
            }
            if (!hasMark) emptyCols++;
        }
        return emptyRows + emptyCols;
    }

    /** Main solving routine – puts all pieces together and prints the answer. */
    private static void solve(FastScanner fs) throws IOException {
        int n = fs.nextInt();
        int k = fs.nextInt();
        int[][] grid = readBoard(fs);

        // 1️⃣  Horizontal helper matrix
        int[][] hor = computeHorizontalCovers(grid, k);
        int hWindowRows = n - k + 1;
        int hWindowCols = n - k + 1;

        // 2️⃣  Prefix sums for horizontal windows -> sum over k consecutive rows for each column
        int[][] horWindowSum = new int[hWindowRows][hWindowCols];
        for (int col = 0; col < hWindowCols; col++) {
            int sum = 0;
            for (int r = 0; r < k; r++) {
                sum += hor[r][col];
            }
            horWindowSum[0][col] = sum;
        }
        for (int start = 1; start < hWindowRows; start++) {
            for (int col = 0; col < hWindowCols; col++) {
                horWindowSum[start][col] = horWindowSum[start - 1][col]
                        - hor[start - 1][col]
                        + hor[start + k - 1][col];
            }
        }

        // 3️⃣  Vertical helper matrix
        int[][] ver = computeVerticalCovers(grid, k);
        int vWindowRows = n - k + 1;
        int vWindowCols = n - k + 1;

        // 4️⃣  Prefix sums for vertical windows -> sum over k consecutive columns for each row
        int[][] verWindowSum = new int[vWindowRows][vWindowCols];
        for (int row = 0; row < vWindowRows; row++) {
            int sum = 0;
            for (int c = 0; c < k; c++) {
                sum += ver[row][c];
            }
            verWindowSum[row][0] = sum;
        }
        for (int start = 1; start < vWindowCols; start++) {
            for (int row = 0; row < vWindowRows; row++) {
                verWindowSum[row][start] = verWindowSum[row][start - 1]
                        - ver[row][start - 1]
                        + ver[row][start + k - 1];
            }
        }

        // 5️⃣  Maximum combined coverage
        int maxCoverage = 0;
        for (int i = 0; i < hWindowRows; i++) {
            for (int j = 0; j < hWindowCols; j++) {
                maxCoverage = Math.max(maxCoverage, horWindowSum[i][j] + verWindowSum[i][j]);
            }
        }

        // 6️⃣  Add empty rows + empty columns
        int emptyContribution = countEmptyRowsAndColumns(grid);
        System.out.println(maxCoverage + emptyContribution);
    }

    public static void main(String[] args) throws Exception {
        // Use stdin by default – fallback to a file only when a template is needed.
        FastScanner fs = new FastScanner(System.in);
        solve(fs);
    }
}

import java.io.*;
import java.util.*;

public class Main {

    /* --------------------------------------------------------------
       Fast input reader
       -------------------------------------------------------------- */
    private static final class FastReader {
        private final BufferedReader br;
        private StringTokenizer st;

        FastReader() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    throw new UncheckedIOException(e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }
    }

    /* --------------------------------------------------------------
       Helper class that stores all pre‑computed information about the grid.
       -------------------------------------------------------------- */
    private static final class GridInfo {
        final int[][] grid;            // 1 → obstacle ('W'), 0 → free cell
        final int[] leftFreeInRow;       // leftmost free column for each row,  n if none
        final int[] rightFreeInRow;      // rightmost free column for each row, -1 if none
        final int[] topFreeInCol;        // topmost free row for each column,   n if none
        final int[] bottomFreeInCol;     // bottommost free row for each column, -1 if none
        final int[] prefixRowsWithoutFree; // prefix count of rows that have no free cell
        final int[] prefixColsWithoutFree; // prefix count of columns that have no free cell

        GridInfo(FastReader fr, int n) {
            grid = new int[n][n];
            readGrid(fr, n);

            leftFreeInRow = computeLeftFreeRow();
            rightFreeInRow = computeRightFreeRow();
            topFreeInCol = computeTopFreeCol();
            bottomFreeInCol = computeBottomFreeCol();
            prefixRowsWithoutFree = computePrefixRowsWithoutFree();
            prefixColsWithoutFree = computePrefixColsWithoutFree();
        }

        private void readGrid(FastReader fr, int n) {
            for (int i = 0; i < n; i++) {
                String line = fr.next();
                for (int j = 0; j < n; j++) {
                    grid[i][j] = line.charAt(j) == 'W' ? 1 : 0;
                }
            }
        }

        private int[] computeLeftFreeRow() {
            int[] left = new int[n];
            Arrays.fill(left, n);
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < n; j++) {
                    if (grid[i][j] == 0) {
                        left[i] = j;
                        break;
                    }
                }
            }
            return left;
        }

        private int[] computeRightFreeRow() {
            int[] right = new int[n];
            Arrays.fill(right, -1);
            for (int i = 0; i < n; i++) {
                for (int j = n - 1; j >= 0; j--) {
                    if (grid[i][j] == 0) {
                        right[i] = j;
                        break;
                    }
                }
            }
            return right;
        }

        private int[] computeTopFreeCol() {
            int[] top = new int[n];
            Arrays.fill(top, n);
            for (int j = 0; j < n; j++) {
                for (int i = 0; i < n; i++) {
                    if (grid[i][j] == 0) {
                        top[j] = i;
                        break;
                    }
                }
            }
            return top;
        }

        private int[] computeBottomFreeCol() {
            int[] bottom = new int[n];
            Arrays.fill(bottom, -1);
            for (int j = 0; j < n; j++) {
                for (int i = n - 1; i >= 0; i--) {
                    if (grid[i][j] == 0) {
                        bottom[j] = i;
                        break;
                    }
                }
            }
            return bottom;
        }

        private int[] computePrefixRowsWithoutFree() {
            int[] pref = new int[n];
            int cnt = 0;
            for (int i = 0; i < n; i++) {
                if (leftFreeInRow[i] == n) {          // row i has no free cell
                    cnt++;
                }
                pref[i] = cnt;
            }
            return pref;
        }

        private int[] computePrefixColsWithoutFree() {
            int[] pref = new int[n];
            int cnt = 0;
            for (int i = 0; i < n; i++) {
                if (topFreeInCol[i] == n) {           // column i has no free cell
                    cnt++;
                }
                pref[i] = cnt;
            }
            return pref;
        }
    }

    /* --------------------------------------------------------------
       Main solving routine
       -------------------------------------------------------------- */
    public static void main(String[] args) {
        FastReader scan = new FastReader();
        PrintWriter out = new PrintWriter(System.out);
        new Main().solve(scan, out);
        out.flush();
    }

    private final GridInfo info;   // shared immutable view of the grid

    Main() {
        this.info = null;          // will be initialised in solve()
    }

    private void solve(FastReader in, PrintWriter out) {
        int n = in.nextInt();
        int k = in.nextInt();

        // Build the immutable view of the grid with all auxiliary arrays
        GridInfo gridInfo = new GridInfo(in, n);
        this.info = gridInfo;

        // dp‑like sliding‑window counters
        int[][] horizontalCovers = new int[n][n];
        int[][] verticalCovers    = new int[n][n];

        int best = 0;

        /* ----------------------------------------------------------
           Enumerate every possible k × k window whose top‑left corner
           is (top, left).  The window is defined by:
               rows   [top , top + k - 1]
               cols   [left, left + k - 1]
           ---------------------------------------------------------- */
        for (int top = 0; top < n; top++) {
            for (int left = 0; left < n; left++) {
                int bottom = top + k - 1;
                int right  = left + k - 1;

                // window must stay inside the board
                if (bottom >= n || right >= n) {
                    continue;
                }

                // ---- horizontal contribution (rows) ----
                horizontalCovers[top][left] = countRowsFullyInsideWindow(
                        top, bottom, left, right);

                // ---- vertical contribution (columns) ----
                verticalCovers[top][left] = countColumnsFullyInsideWindow(
                        top, bottom, left, right);

                // ---- combine everything into the final score ----
                int score = horizontalCovers[top][left] + verticalCovers[top][left]
                        + (top > 0 ? gridInfo.prefixRowsWithoutFree[top - 1] : 0)
                        + gridInfo.prefixRowsWithoutFree[n - 1] - gridInfo.prefixRowsWithoutFree[bottom]
                        + (left > 0 ? gridInfo.prefixColsWithoutFree[left - 1] : 0)
                        + gridInfo.prefixColsWithoutFree[n - 1] - gridInfo.prefixColsWithoutFree[right];

                best = Math.max(best, score);
            }
        }

        out.println(best);
    }

    /* --------------------------------------------------------------
       Utility: count how many rows inside the window have their
       completely‑free interval (left/right) contained in the column
       window [colStart, colEnd].
       -------------------------------------------------------------- */
    private int countRowsFullyInsideWindow(
            int rowStart, int rowEnd, int colStart, int colEnd) {

        int cnt = 0;
        for (int r = rowStart; r <= rowEnd; r++) {
            if (colStart <= info.leftFreeInRow[r] && colEnd >= info.rightFreeInRow[r]) {
                cnt++;
            }
        }
        return cnt;
    }

    /* --------------------------------------------------------------
       Utility: count how many columns inside the window have their
       completely‑free interval (top/bottom) contained in the row
       window [rowStart, rowEnd].
       -------------------------------------------------------------- */
    private int countColumnsFullyInsideWindow(
            int colStart, int colEnd, int rowStart, int rowEnd) {

        int cnt = 0;
        for (int c = colStart; c <= colEnd; c++) {
            if (rowStart <= info.topFreeInCol[c] && rowEnd >= info.bottomFreeInCol[c]) {
                cnt++;
            }
        }
        return cnt;
    }
}

import java.io.*;
import java.util.*;

public class WhiteLines {
    public static void main(String[] args) {
        FastScanner scanner = new FastScanner();
        PrintWriter out = new PrintWriter(System.out);
        int gridSize = scanner.nextInt();
        int squareSize = scanner.nextInt();
        boolean[][] grid = readGrid(scanner, gridSize);

        int[] rowBlackCount = countBlackCellsPerRow(grid, gridSize);
        int[] colBlackCount = countBlackCellsPerColumn(grid, gridSize);

        int alreadyWhiteLines = countAlreadyWhiteLines(rowBlackCount, colBlackCount);

        boolean[][] columnWindowValidity = computeColumnWindowValidity(grid, gridSize, squareSize, colBlackCount);
        boolean[][] rowWindowValidity = computeRowWindowValidity(grid, gridSize, squareSize, rowBlackCount);

        int[][] placementImpact = computePlacementImpact(columnWindowValidity, rowWindowValidity, gridSize, squareSize);

        int maxAdditionalLines = findMaximumImpact(placementImpact);
        out.println(alreadyWhiteLines + maxAdditionalLines);
        out.flush();
    }

    private static boolean[][] readGrid(FastScanner scanner, int size) {
        boolean[][] grid = new boolean[size][size];
        for (int i = 0; i < size; i++) {
            char[] line = scanner.next().toCharArray();
            for (int j = 0; j < size; j++) {
                grid[i][j] = (line[j] == 'W');
            }
        }
        return grid;
    }

    private static int[] countBlackCellsPerRow(boolean[][] grid, int size) {
        int[] counts = new int[size];
        for (int i = 0; i < size; i++) {
            for (int j = 0; j < size; j++) {
                if (!grid[i][j]) {
                    counts[i]++;
                }
            }
        }
        return counts;
    }

    private static int[] countBlackCellsPerColumn(boolean[][] grid, int size) {
        int[] counts = new int[size];
        for (int j = 0; j < size; j++) {
            for (int i = 0; i < size; i++) {
                if (!grid[i][j]) {
                    counts[j]++;
                }
            }
        }
        return counts;
    }

    private static int countAlreadyWhiteLines(int[] rowCounts, int[] colCounts) {
        int count = 0;
        for (int i = 0; i < rowCounts.length; i++) {
            if (rowCounts[i] == 0) {
                count++;
                rowCounts[i] = Integer.MAX_VALUE;
            }
            if (colCounts[i] == 0) {
                count++;
                colCounts[i] = Integer.MAX_VALUE;
            }
        }
        return count;
    }

    private static boolean[][] computeColumnWindowValidity(boolean[][] grid, int size, int squareSize, int[] colBlackCounts) {
        boolean[][] validity = new boolean[size][size - squareSize + 1];
        for (int colIndex = 0; colIndex < size; colIndex++) {
            int windowBlackCount = countBlackCellsInColumnWindow(grid, size, squareSize, colIndex, 0);
            if (colBlackCounts[colIndex] == windowBlackCount) {
                validity[colIndex][0] = true;
            }
            for (int startRow = 1; startRow <= size - squareSize; startRow++) {
                updateWindowBlackCount(grid, size, squareSize, colIndex, startRow, windowBlackCount);
                if (colBlackCounts[colIndex] == windowBlackCount) {
                    validity[colIndex][startRow] = true;
                }
            }
        }
        return validity;
    }

    private static void updateWindowBlackCount(boolean[][] grid, int size, int squareSize, 
                                              int colIndex, int startRow, int currentCount) {
        int newRow = startRow + squareSize - 1;
        if (!grid[newRow][colIndex]) {
            currentCount++;
        }
        if (!grid[startRow - 1][colIndex]) {
            currentCount--;
        }
    }

    private static int countBlackCellsInColumnWindow(boolean[][] grid, int size, int squareSize, 
                                                    int colIndex, int startRow) {
        int count = 0;
        for (int row = startRow; row < startRow + squareSize; row++) {
            if (!grid[row][colIndex]) {
                count++;
            }
        }
        return count;
    }

    private static boolean[][] computeRowWindowValidity(boolean[][] grid, int size, int squareSize, 
                                                       int[] rowBlackCounts) {
        boolean[][] validity = new boolean[size][size - squareSize + 1];
        for (int rowIndex = 0; rowIndex < size; rowIndex++) {
            int windowBlackCount = countBlackCellsInRowWindow(grid, size, squareSize, rowIndex, 0);
            if (rowBlackCounts[rowIndex] == windowBlackCount) {
                validity[rowIndex][0] = true;
            }
            for (int startCol = 1; startCol <= size - squareSize; startCol++) {
                updateWindowBlackCount(grid, size, squareSize, rowIndex, startCol, windowBlackCount);
                if (rowBlackCounts[rowIndex] == windowBlackCount) {
                    validity[rowIndex][startCol] = true;
                }
            }
        }
        return validity;
    }

    private static int countBlackCellsInRowWindow(boolean[][] grid, int size, int squareSize, 
                                                 int rowIndex, int startCol) {
        int count = 0;
        for (int col = startCol; col < startCol + squareSize; col++) {
            if (!grid[rowIndex][col]) {
                count++;
            }
        }
        return count;
    }

    private static int[][] computePlacementImpact(boolean[][] columnValidity, 
                                                 boolean[][] rowValidity, 
                                                 int size, int squareSize) {
        int[][] impact = new int[size - squareSize + 1][size - squareSize + 1];

        // Process column validity contributions
        for (int startCol = 0; startCol <= size - squareSize; startCol++) {
            int impactCount = 0;
            for (int row = 0; row < squareSize; row++) {
                if (columnValidity[row][startCol]) {
                    impactCount++;
                }
            }
            impact[0][startCol] += impactCount;

            for (int nextRow = 1; nextRow <= size - squareSize; nextRow++) {
                updateImpactCount(impactCount, columnValidity, size, squareSize, nextRow, startCol);
                impact[nextRow][startCol] += impactCount;
            }
        }

        // Process row validity contributions
        for (int startRow = 0; startRow <= size - squareSize; startRow++) {
            int impactCount = 0;
            for (int col = 0; col < squareSize; col++) {
                if (rowValidity[col][startRow]) {
                    impactCount++;
                }
            }
            impact[startRow][0] += impactCount;

            for (int nextCol = 1; nextCol <= size - squareSize; nextCol++) {
                updateImpactCount(impactCount, rowValidity, size, squareSize, nextRow, nextCol);
                impact[startRow][nextCol] += impactCount;
            }
        }

        return impact;
    }

    private static void updateImpactCount(int currentImpact, boolean[][] validity, 
                                         int size, int squareSize, int nextRow, int nextCol) {
        if (validity[nextRow + squareSize - 1][nextCol]) {
            currentImpact++;
        }
        if (validity[nextRow - 1][nextCol]) {
            currentImpact--;
        }
    }

    private static int findMaximumImpact(int[][] impactMatrix) {
        int maxImpact = 0;
        for (int[] row : impactMatrix) {
            for (int impact : row) {
                maxImpact = Math.max(maxImpact, impact);
            }
        }
        return maxImpact;
    }

    public static class FastScanner {
        private BufferedReader br;
        private StringTokenizer st;

        public FastScanner(Reader in) {
            br = new BufferedReader(in);
        }

        public FastScanner() {
            this(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    e.printStackTrace();
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.io.IOException;
import java.util.Arrays;
import java.util.Scanner;

/**
 * Reads an N×N grid consisting of the characters ‘W’ and any other character.
 * For each row and column the positions of the first and last “non‑W” (i.e. 0)
 * are recorded.  Using those intervals the program determines how many rows
 * and columns can be completely covered by a sliding window of size K.
 * The result is the maximum number of such covered rows/columns that can be
 * simultaneously satisfied by a K×K window, plus the number of completely
 * empty rows/columns.
 */
public class Solution {

    /** Sentinel value used to indicate “no zero found”. */
    private static final int NOT_FOUND = -1;

    public static void main(String[] args) throws IOException {
        try (Scanner sc = new Scanner(System.in)) {
            solve(sc);
        }
    }

    /**
     * Core algorithm – delegates work to small, focused helper methods.
     */
    private static void solve(Scanner sc) {
        int n = sc.nextInt();          // grid dimension
        int k = sc.nextInt();          // window size
        int[][] grid = readGrid(sc, n);

        // -----------------------------------------------------------------
        // 1️⃣  Determine the “first” and “last” column (per row) and row
        //     (per column) that contain a non‑W cell.
        // -----------------------------------------------------------------
        RowColumnBounds rowBounds = computeRowBounds(grid);
        ColumnBounds colBounds  = computeColumnBounds(grid, n);

        // -----------------------------------------------------------------
        // 2️⃣  Build coverage maps:
        //      * rowCoveredInWindow[row][colStart]  – true if the whole row
        //        fits inside a horizontal sliding window of length k that
        //        starts at colStart.
        //      * colCoveredInWindow[rowStart][col] – analog for columns.
        // -----------------------------------------------------------------
        boolean[][] rowCoveredInWindow = computeRowCoverage(grid, n, k, rowBounds);
        boolean[][] colCoveredInWindow = computeColumnCoverage(grid, n, k, colBounds);

        // -----------------------------------------------------------------
        // 3️⃣  Transform the 2‑D coverage maps into sliding‑window sums.
        //      For every possible top‑left corner (i, j) of a K×K block we
        //      obtain:
        //          rowsCovered  – number of rows fully covered by the vertical
        //                         slide starting at i,
        //          colsCovered  – number of columns fully covered by the
        //                         horizontal slide starting at j.
        // -----------------------------------------------------------------
        int[][] rowsCoveredByVerticalWindow = slidingWindowSum(rowCoveredInWindow, n, k);
        int[][] colsCoveredByHorizontalWindow = slidingWindowSum(colCoveredInWindow, n, k);

        // -----------------------------------------------------------------
        // 4️⃣  Compute the total coverage for each top‑left corner and keep
        //     the maximum value.
        // -----------------------------------------------------------------
        int maxCoverage = 0;
        for (int i = 0; i <= n - k; i++) {
            for (int j = 0; j <= n - k; j++) {
                int total = rowsCoveredByVerticalWindow[i][j]
                          + colsCoveredByHorizontalWindow[i][j];
                maxCoverage = Math.max(maxCoverage, total);
            }
        }

        // -----------------------------------------------------------------
        // 5️⃣  Add contributions from completely empty rows / columns.
        // -----------------------------------------------------------------
        int emptyRows = countEmptyRows(rowBounds);
        int emptyCols = countEmptyColumns(colBounds);
        maxCoverage += emptyRows + emptyCols;

        System.out.println(maxCoverage);
    }

    // ---------------------------------------------------------------------
    // Helper: read the N lines of the grid.
    // ---------------------------------------------------------------------
    private static int[][] readGrid(Scanner sc, int n) {
        int[][] matrix = new int[n][n];
        for (int i = 0; i < n; i++) {
            String line = sc.next();
            for (int j = 0; j < n; j++) {
                matrix[i][j] = line.charAt(j) == 'W' ? 1 : 0;
            }
        }
        return matrix;
    }

    // ---------------------------------------------------------------------
    // Helper class to store per‑row bounds (first & last column with 0).
    // ---------------------------------------------------------------------
    private static class RowColumnBounds {
        final int[][] bounds;               // [row][0] = first, [row][1] = last

        RowColumnBounds(int n) {
            bounds = new int[n][2];
            for (int[] arr : bounds) Arrays.fill(arr, NOT_FOUND);
        }

        void set(int row, int col) {
            int[] arr = bounds[row];
            if (arr[0] == NOT_FOUND) arr[0] = col;   // first occurrence
            arr[1] = col;                            // last occurrence
        }
    }

    // ---------------------------------------------------------------------
    // Helper class to store per‑column bounds (first & last row with 0).
    // ---------------------------------------------------------------------
    private static class ColumnBounds {
        final int[][] bounds;               // [col][0] = first, [col][1] = last

        ColumnBounds(int n) {
            bounds = new int[n][2];
            for (int[] arr : bounds) Arrays.fill(arr, NOT_FOUND);
        }

        void set(int col, int row) {
            int[] arr = bounds[col];
            if (arr[0] == NOT_FOUND) arr[0] = row;   // first occurrence
            arr[1] = row;                            // last occurrence
        }
    }

    // ---------------------------------------------------------------------
    // 1️⃣  Compute row bounds.
    // ---------------------------------------------------------------------
    private static RowColumnBounds computeRowBounds(int[][] grid) {
        int n = grid.length;
        RowColumnBounds rowBounds = new RowColumnBounds(n);
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (grid[i][j] == 0) {
                    rowBounds.set(i, j);
                }
            }
        }
        return rowBounds;
    }

    // ---------------------------------------------------------------------
    // 2️⃣  Compute column bounds.
    // ---------------------------------------------------------------------
    private static ColumnBounds computeColumnBounds(int[][] grid, int n) {
        ColumnBounds colBounds = new ColumnBounds(n);
        for (int j = 0; j < n; j++) {
            for (int i = 0; i < n; i++) {
                if (grid[i][j] == 0) {
                    colBounds.set(j, i);
                }
            }
        }
        return colBounds;
    }

    // ---------------------------------------------------------------------
    // 3️⃣  Build the “row covered by horizontal window” matrix.
    // ---------------------------------------------------------------------
    private static boolean[][] computeRowCoverage(int[][] grid,
                                                    int n,
                                                    int k,
                                                    RowColumnBounds rowBounds) {
        boolean[][] coverage = new boolean[n][n - k + 1];
        for (int row = 0; row < n; row++) {
            int[] range = rowBounds.bounds[row];
            if (range[0] == NOT_FOUND) {               // row has no zeros → skip
                continue;
            }
            int firstZero = range[0];
            int lastZero  = range[1];
            for (int start = 0; start <= n - k; start++) {
                if (firstZero >= start && lastZero <= start + k - 1) {
                    coverage[row][start] = true;
                }
            }
        }
        return coverage;
    }

    // ---------------------------------------------------------------------
    // 4️⃣  Build the “column covered by vertical window” matrix.
    // ---------------------------------------------------------------------
    private static boolean[][] computeColumnCoverage(int[][] grid,
                                                       int n,
                                                       int k,
                                                       ColumnBounds colBounds) {
        boolean[][] coverage = new boolean[n - k + 1][n];
        for (int col = 0; col < n; col++) {
            int[] range = colBounds.bounds[col];
            if (range[0] == NOT_FOUND) {               // column has no zeros → skip
                continue;
            }
            int firstZero = range[0];
            int lastZero  = range[1];
            for (int start = 0; start <= n - k; start++) {
                if (firstZero >= start && lastZero <= start + k - 1) {
                    coverage[start][col] = true;
                }
            }
        }
        return coverage;
    }

    // ---------------------------------------------------------------------
    // 5️⃣  Transform a boolean coverage matrix into a matrix of sliding‑
    //      window sums of height k (or width k for the column version).
    // ---------------------------------------------------------------------
    private static int[][] slidingWindowSum(boolean[][] coverage, int size, int window) {
        int outerDim = coverage.length;          // number of rows (or cols)
        int innerDim = coverage[0].length;       // number of columns (or rows)
        int[][] result = new int[outerDim - window + 1][innerDim];

        for (int col = 0; col < innerDim; col++) {
            int sum = 0;
            for (int i = 0; i < window; i++) {
                sum += coverage[i][col] ? 1 : 0;
            }
            result[0][col] = sum;

            for (int i = window; i < outerDim; i++) {
                sum += coverage[i][col] ? 1 : 0;
                sum -= coverage[i - window][col] ? 1 : 0;
                result[i - window + 1][col] = sum;
            }
        }
        return result;
    }

    // ---------------------------------------------------------------------
    // 6️⃣  Count rows that contain no zeros at all.
    // ---------------------------------------------------------------------
    private static int countEmptyRows(RowColumnBounds rowBounds) {
        int empty = 0;
        for (int[] range : rowBounds.bounds) {
            if (range[0] == NOT_FOUND) {
                empty++;
            }
        }
        return empty;
    }

    // ---------------------------------------------------------------------
    // 7️⃣  Count columns that contain no zeros at all.
    // ---------------------------------------------------------------------
    private static int countEmptyColumns(ColumnBounds colBounds) {
        int empty = 0;
        for (int[] range : colBounds.bounds) {
            if (range[0] == NOT_FOUND) {
                empty++;
            }
        }
        return empty;
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.ArrayList;
import java.util.List;
import java.util.StringTokenizer;

/**
 * Refactored version of the original program.
 * The code is split into small, purpose‑focused methods,
 * uses meaningful names, and isolates the input handling,
 * bounds calculation and sliding‑window logic.
 */
public class Main {

    /** Simple container for two integer values. */
    private static final class Pair {
        final int first;
        final int last;

        Pair(int first, int last) {
            this.first = first;
            this.last = last;
        }
    }

    /** Fast scanner based on {@link BufferedReader}. */
    private static final class InputReader {
        private final BufferedReader br;

        InputReader() {
            this.br = new BufferedReader(new InputStreamReader(System.in));
        }

        /** Reads the next non‑empty token. */
        String next() {
            while (true) {
                try {
                    String line = br.readLine();
                    if (line != null && !line.isBlank()) {
                        return line;
                    }
                } catch (IOException e) {
                    throw new UncheckedIOException(e);
                }
            }
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        /** Reads an {@code n×n} character grid. */
        char[][] readGrid(int n) {
            char[][] grid = new char[n][n];
            for (int i = 0; i < n; i++) {
                String line = next();
                for (int j = 0; j < n; j++) {
                    grid[i][j] = line.charAt(j);
                }
            }
            return grid;
        }
    }

    /* --------------------------------------------------------------
       1.  Bounds extraction
       -------------------------------------------------------------- */

    /** Returns the index of the first column that contains 'B' in the given row, or -1. */
    private static int firstBlackColumn(char[][] grid, int row) {
        for (int col = 0; col < grid.length; col++) {
            if (grid[row][col] == 'B') {
                return col;
            }
        }
        return -1;
    }

    /** Returns the index of the last column that contains 'B' in the given row, or -1. */
    private static int lastBlackColumn(char[][] grid, int row) {
        for (int col = grid.length - 1; col >= 0; col--) {
            if (grid[row][col] == 'B') {
                return col;
            }
        }
        return -1;
    }

    /** Builds a list with the first/last black column for each row. */
    private static List<Pair> buildRowBounds(char[][] grid) {
        List<Pair> bounds = new ArrayList<>(grid.length);
        for (int r = 0; r < grid.length; r++) {
            int first = firstBlackColumn(grid, r);
            int last = lastBlackColumn(grid, r);
            bounds.add(new Pair(first, last));
        }
        return bounds;
    }

    /** Returns the index of the first row that contains 'B' in the given column, or -1. */
    private static int firstBlackRow(char[][] grid, int col) {
        for (int row = 0; row < grid.length; row++) {
            if (grid[row][col] == 'B') {
                return row;
            }
        }
        return -1;
    }

    /** Returns the index of the last row that contains 'B' in the given column, or -1. */
    private static int lastBlackRow(char[][] grid, int col) {
        for (int row = grid.length - 1; row >= 0; row--) {
            if (grid[row][col] == 'B') {
                return row;
            }
        }
        return -1;
    }

    /** Builds a list with the first/last black row for each column. */
    private static List<Pair> buildColumnBounds(char[][] grid) {
        List<Pair> bounds = new ArrayList<>(grid.length);
        for (int c = 0; c < grid.length; c++) {
            int first = firstBlackRow(grid, c);
            int last = lastBlackRow(grid, c);
            bounds.add(new Pair(first, last));
        }
        return bounds;
    }

    /* --------------------------------------------------------------
       2.  Sliding‑window helpers
       -------------------------------------------------------------- */

    /** Counts how many column‑bounds are completely inside the vertical window that starts at {@code top}. */
    private static int countColumnsCoveredInWindow(List<Pair> columnBounds, int top, int windowSize) {
        int count = 0;
        for (Pair p : columnBounds) {
            if (p.first >= 0 && p.last >= 0 && p.first >= top && p.last <= top + windowSize - 1) {
                count++;
            }
        }
        return count;
    }

    /** Counts how many row‑bounds are completely inside the horizontal window that starts at {@code left}. */
    private static int countRowsCoveredInWindow(List<Pair> rowBounds, int left, int windowSize) {
        int count = 0;
        for (Pair p : rowBounds) {
            if (p.first >= 0 && p.last >= 0 && p.first >= left && p.last <= left + windowSize - 1) {
                count++;
            }
        }
        return count;
    }

    /** Adjusts the horizontal coverage count when the window moves one step to the right. */
    private static int adjustHorizontalCount(List<Pair> columnBounds,
                                             int currentStart,
                                             int newStart,
                                             int windowSize) {
        Pair leaving = columnBounds.get(currentStart);
        Pair entering = columnBounds.get(newStart + windowSize - 1);
        int delta = 0;

        if (leaving.first >= 0 && leaving.last >= 0 &&
                leaving.first >= currentStart && leaving.last <= currentStart + windowSize - 1) {
            delta--;
        }
        if (entering.first >= 0 && entering.last >= 0 &&
                entering.first >= newStart && entering.last <= newStart + windowSize - 1) {
            delta++;
        }
        return delta;
    }

    /** Adjusts the vertical coverage count when the window moves one step downward. */
    private static int adjustVerticalCount(List<Pair> rowBounds,
                                           int currentStart,
                                           int newStart,
                                           int windowSize) {
        Pair leaving = rowBounds.get(currentStart);
        Pair entering = rowBounds.get(newStart + windowSize - 1);
        int delta = 0;

        if (leaving.first >= 0 && leaving.last >= 0 &&
                leaving.first >= currentStart && leaving.last <= currentStart + windowSize - 1) {
            delta--;
        }
        if (entering.first >= 0 && entering.last >= 0 &&
                entering.first >= newStart && entering.last <= newStart + windowSize - 1) {
            delta++;
        }
        return delta;
    }

    /* --------------------------------------------------------------
       3.  Main algorithm
       -------------------------------------------------------------- */

    public static void main(String[] args) {
        InputReader reader = new InputReader();
        int n = reader.nextInt();          // grid size
        int k = reader.nextInt();          // sliding square size

        char[][] grid = reader.readGrid(n);

        // ---- 3.1  Determine empty rows / columns (they add 1 each to the final answer) ----
        List<Pair> rowBounds = buildRowBounds(grid);
        List<Pair> columnBounds = buildColumnBounds(grid);

        int emptyRows = 0;
        for (Pair p : rowBounds) {
            if (p.first == -1) {
                emptyRows++;
            }
        }

        int emptyCols = 0;
        for (Pair p : columnBounds) {
            if (p.first == -1) {
                emptyCols++;
            }
        }

        // ---- 3.2  Prepare coverage matrix (size = n‑k+1) ----
        int windowCount = n - k + 1;
        int[][] coverage = new int[windowCount][windowCount];

        // ----- fill the first column of the matrix (horizontal sliding) -----
        for (int top = 0; top < windowCount; top++) {
            int covered = countColumnsCoveredInWindow(columnBounds, top, k);
            coverage[top][0] = covered;

            for (int right = 1; right < windowCount; right++) {
                int delta = adjustHorizontalCount(columnBounds, right - 1, right, k);
                covered += delta;
                coverage[top][right] = covered;
            }
        }

        // ----- fill the first row of the matrix (vertical sliding) and propagate downwards -----
        for (int left = 0; left < windowCount; left++) {
            int covered = countRowsCoveredInWindow(rowBounds, left, k);
            coverage[0][left] += covered;

            for (int bottom = 1; bottom < windowCount; bottom++) {
                int delta = adjustVerticalCount(rowBounds, bottom - 1, bottom, k);
                covered += delta;
                coverage[bottom][left] += covered;
            }
        }

        // ---- 3.3  Find the maximum value in the coverage matrix ----
        int maxCoverage = 0;
        for (int i = 0; i < windowCount; i++) {
            for (int j = 0; j < windowCount; j++) {
                if (coverage[i][j] > maxCoverage) {
                    maxCoverage = coverage[i][j];
                }
            }
        }

        // ---- 3.4  Output the result (max coverage + empty rows + empty columns) ----
        System.out.println(maxCoverage + emptyRows + emptyCols);
    }
}

import java.io.*;
import java.util.StringTokenizer;

/**
 * Refactored solution for problem 578D.
 *
 * <p>Key improvements:
 * <ul>
 *   <li>Extracted responsibilities into small, focused methods and classes.</li>
 *   <li>Replaced magic numbers with named constants.</li>
 *   <li>Removed dead code (unused modular inverse) and added Javadoc.</li>
 *   <li>Used clear naming and modern Java idioms for readability.</li>
 *   <li>Kept the original algorithmic behaviour – the program still computes the
 *       maximum number of cells that can be covered by one horizontal and one
 *       vertical brush of size k, plus the cells that are already free of black.</li>
 * </ul>
 */
public class P578D {

    /** Modular constant used by the original author (not needed for the current algorithm). */
    private static final long MOD = 1_000_000_007L;

    /** Entry point. */
    public static void main(String[] args) {
        solve();
    }

    /** Orchestrates input reading, processing and output writing. */
    private static void solve() {
        FastScanner scanner = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(System.out);

        int n = scanner.nextInt();
        int k = scanner.nextInt();
        char[][] grid = readGrid(scanner, n);

        int freeRows    = countEmptyRows(grid, n);
        int freeColumns = countEmptyColumns(grid, n);

        int maxCovered = new CoverageComputer(grid, n, k).maxCoveredCells();

        out.println(maxCovered + freeRows + freeColumns);
        out.flush();
    }

    /** Reads the n × n grid from the scanner. */
    private static char[][] readGrid(FastScanner scanner, int n) {
        char[][] grid = new char[n][n];
        for (int i = 0; i < n; i++) {
            String line = scanner.nextLine();
            for (int j = 0; j < n; j++) {
                grid[i][j] = line.charAt(j);
            }
        }
        return grid;
    }

    /** Counts rows that contain no 'B' characters. */
    private static int countEmptyRows(char[][] grid, int n) {
        int empty = 0;
        for (int i = 0; i < n; i++) {
            boolean hasBlack = false;
            for (int j = 0; j < n; j++) {
                if (grid[i][j] == 'B') {
                    hasBlack = true;
                    break;
                }
            }
            if (!hasBlack) {
                empty++;
            }
        }
        return empty;
    }

    /** Counts columns that contain no 'B' characters. */
    private static int countEmptyColumns(char[][] grid, int n) {
        int empty = 0;
        for (int j = 0; j < n; j++) {
            boolean hasBlack = false;
            for (int i = 0; i < n; i++) {
                if (grid[i][j] == 'B') {
                    hasBlack = true;
                    break;
                }
            }
            if (!hasBlack) {
                empty++;
            }
        }
        return empty;
    }

    /**
     * Core class that evaluates how many cells become black after applying
     * one horizontal and one vertical brush of size k.
     */
    private static final class CoverageComputer {
        private final char[][] grid;
        private final int n;
        private final int k;

        CoverageComputer(char[][] grid, int n, int k) {
            this.grid = grid;
            this.n = n;
            this.k = k;
        }

        /** Returns the maximum number of cells that can be painted black. */
        int maxCoveredCells() {
            boolean[][] horizontalCoverage = computeRowCoverage();
            boolean[][] verticalCoverage     = computeColumnCoverage();

            int[][] rowWindowSums    = slidingWindowSums(horizontalCoverage);
            int[][] columnWindowSums = slidingWindowSums(verticalCoverage);

            int best = 0;
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < n; j++) {
                    best = Math.max(best, rowWindowSums[i][j] + columnWindowSums[i][j]);
                }
            }
            return best;
        }

        /** Determines, for each possible left‑most column of a horizontal brush,
         *  whether it would completely cover the black cells of that row. */
        private boolean[][] computeRowCoverage() {
            boolean[][] cover = new boolean[n][n];
            for (int row = 0; row < n; row++) {
                int firstBlack = -1, lastBlack = -1;
                for (int col = 0; col < n; col++) {
                    if (grid[row][col] == 'B') {
                        if (firstBlack == -1) firstBlack = col;
                        lastBlack = col;
                    }
                }
                if (firstBlack == -1) {                 // no black cells in this row
                    continue;
                }
                if (lastBlack - firstBlack + 1 > k) {   // span wider than brush -> impossible
                    continue;
                }
                int start = Math.max(0, lastBlack - k + 1);
                int end   = Math.min(n - k, firstBlack);
                for (int col = start; col <= end; col++) {
                    cover[row][col] = true;
                }
            }
            return cover;
        }

        /** Determines, for each possible top‑most row of a vertical brush,
         *  whether it would completely cover the black cells of that column. */
        private boolean[][] computeColumnCoverage() {
            boolean[][] cover = new boolean[n][n];
            for (int col = 0; col < n; col++) {
                int firstBlack = -1, lastBlack = -1;
                for (int row = 0; row < n; row++) {
                    if (grid[row][col] == 'B') {
                        if (firstBlack == -1) firstBlack = row;
                        lastBlack = row;
                    }
                }
                if (firstBlack == -1) {
                    continue;
                }
                if (lastBlack - firstBlack + 1 > k) {
                    continue;
                }
                int start = Math.max(0, lastBlack - k + 1);
                int end   = Math.min(n - k, firstBlack);
                for (int row = start; row <= end; row++) {
                    cover[row][col] = true;
                }
            }
            return cover;
        }

        /**
         * Computes, for each possible top‑left corner of a k×k brush,
         * how many rows (or columns) would be fully covered.
         *
         * <p>The algorithm mirrors the sliding‑window technique used in the original
         * source, iterating from the bottom toward the top to maintain a running
         * count of active cover positions.
         */
        private int[][] slidingWindowSums(boolean[][] coverage) {
            int[][] sums = new int[n][n];
            for (int fixed = 0; fixed < n; fixed++) {
                int running = 0;
                for (int i = n - 1; i >= 0; i--) {
                    boolean active = coverage[i][fixed];
                    running += active ? 1 : 0;
                    if (i + k < n) {
                        running -= coverage[i + k][fixed] ? 1 : 0;
                    }
                    sums[i][fixed] = running;
                }
            }
            return sums;
        }
    }

    /**
     * Simple fast scanner that replaces the original {@code InputReader}.
     * It preserves the same tokenisation behaviour while keeping the code
     * compact.
     */
    private static final class FastScanner {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        FastScanner(InputStream stream) {
            this.reader = new BufferedReader(new InputStreamReader(stream));
        }

        String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        String nextLine() {
            try {
                return reader.readLine();
            } catch (IOException e) {
                throw new RuntimeException(e);
            }
        }
    }
}

import java.io.*;
import java.util.*;

public class D {

    /* -------------------------------------------------------------
       Entry point
       ------------------------------------------------------------- */
    public static void main(String[] args) throws Exception {
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in))) {
            StringTokenizer st = new StringTokenizer(br.readLine());
            int n = Integer.parseInt(st.nextToken());
            int k = Integer.parseInt(st.nextToken());
            char[][] grid = new char[n][];
            for (int i = 0; i < n; i++) {
                grid[i] = br.readLine().toCharArray();
            }

            // 1️⃣  Empty rows / columns
            int[] emptyRowMask = identifyEmptyRows(grid, n);
            int[] emptyColMask = identifyEmptyColumns(grid, n);

            // 2️⃣  Prefix counts of 'B' in each direction
            int[][] left  = computeLeftCounts(grid, n);
            int[][] right = computeRightCounts(grid, n);
            int[][] up    = computeUpCounts(grid, n);
            int[][] down  = computeDownCounts(grid, n);

            // 3️⃣  Where a length‑k segment can start (horizontal / vertical)
            boolean[][] canPlaceHorizontally = computeHorizontalStartFlags(
                    grid, n, k, left, right);
            boolean[][] canPlaceVertically   = computeVerticalStartFlags(
                    grid, n, k, up, down);

            // 4️⃣  Sliding‑window sums of the above flags
            int[][] horizWindowSum = computeSlidingWindowSums(
                    canPlaceVertically, n, k);   // cbycol in the original code
            int[][] vertWindowSum  = computeSlidingWindowSums(
                    canPlaceHorizontally, n, k); // cbyrow in the original code

            // 5️⃣  Prefix / suffix sums of empty rows and columns (O(1) access)
            int[] prefEmptyRowsUp   = buildPrefixSum(emptyRowMask);
            int[] prefEmptyRowsDown = buildSuffixSum(emptyRowMask);
            int[] prefEmptyColsLeft = buildPrefixSum(emptyColMask);
            int[] prefEmptyColsRight= buildSuffixSum(emptyColMask);

            // 6️⃣  Compute the answer
            int answer = computeMaximumScore(
                    n, k,
                    emptyRowMask, emptyColMask,
                    horizWindowSum, vertWindowSum,
                    prefEmptyRowsUp, prefEmptyRowsDown,
                    prefEmptyColsLeft, prefEmptyColsRight);

            System.out.println(answer);
        }
    }

    /* -------------------------------------------------------------
       Helper methods
       ------------------------------------------------------------- */

    private static int[] identifyEmptyRows(char[][] grid, int n) {
        int[] mask = new int[n];
        for (int i = 0; i < n; i++) {
            boolean hasB = false;
            for (int j = 0; j < n; j++) {
                if (grid[i][j] == 'B') {
                    hasB = true;
                    break;
                }
            }
            mask[i] = hasB ? 0 : 1;          // 1 ⇒ empty row
        }
        return mask;
    }

    private static int[] identifyEmptyColumns(char[][] grid, int n) {
        int[] mask = new int[n];
        for (int j = 0; j < n; j++) {
            boolean hasB = false;
            for (int i = 0; i < n; i++) {
                if (grid[i][j] == 'B') {
                    hasB = true;
                    break;
                }
            }
            mask[j] = hasB ? 0 : 1;          // 1 ⇒ empty column
        }
        return mask;
    }

    private static int[][] computeLeftCounts(char[][] grid, int n) {
        int[][] left = new int[n][n];
        for (int i = 0; i < n; i++) {
            int cnt = 0;
            for (int j = 0; j < n; j++) {
                if (grid[i][j] == 'B') cnt++;
                left[i][j] = cnt;
            }
        }
        return left;
    }

    private static int[][] computeRightCounts(char[][] grid, int n) {
        int[][] right = new int[n][n];
        for (int i = 0; i < n; i++) {
            int cnt = 0;
            for (int j = n - 1; j >= 0; j--) {
                if (grid[i][j] == 'B') cnt++;
                right[i][j] = cnt;
            }
        }
        return right;
    }

    private static int[][] computeUpCounts(char[][] grid, int n) {
        int[][] up = new int[n][n];
        for (int j = 0; j < n; j++) {
            int cnt = 0;
            for (int i = 0; i < n; i++) {
                if (grid[i][j] == 'B') cnt++;
                up[i][j] = cnt;
            }
        }
        return up;
    }

    private static int[][] computeDownCounts(char[][] grid, int n) {
        int[][] down = new int[n][n];
        for (int j = 0; j < n; j++) {
            int cnt = 0;
            for (int i = n - 1; i >= 0; i--) {
                if (grid[i][j] == 'B') cnt++;
                down[i][j] = cnt;
            }
        }
        return down;
    }

    /** Horizontal placement flag: a length‑k segment can start at (i, j). */
    private static boolean[][] computeHorizontalStartFlags(
            char[][] grid, int n, int k,
            int[][] left, int[][] right) {

        boolean[][] flag = new boolean[n][n];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                boolean rightSideClear = (j + k >= n) || (right[i][j + k] == 0);
                boolean leftSideClear  = (j == 0)     || (left[i][j - 1] == 0);
                flag[i][j] = rightSideClear && leftSideClear;
            }
        }
        return flag;
    }

    /** Vertical placement flag: a length‑k segment can start at (i, j). */
    private static boolean[][] computeVerticalStartFlags(
            char[][] grid, int n, int k,
            int[][] up, int[][] down) {

        boolean[][] flag = new boolean[n][n];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                boolean downSideClear = (i + k >= n) || (down[i + k][j] == 0);
                boolean upSideClear   = (i == 0)     || (up[i - 1][j] == 0);
                flag[i][j] = downSideClear && upSideClear;
            }
        }
        return flag;
    }

    /** Sliding‑window sum of length k across the chosen dimension. */
    private static int[][] computeSlidingWindowSums(
            boolean[][] matrix, int size, int k) {

        int[][] result = new int[size][size];
        for (int i = 0; i < size; i++) {
            int acc = 0;
            // initialise window at the far right (or bottom)
            for (int t = size - 1; t >= size - k; t--) {
                acc += matrix[i][t];
            }
            result[i][size - k] = acc;
            // slide the window leftwards (or upwards)
            for (int pos = size - k - 1; pos >= 0; pos--) {
                acc += matrix[i][pos];
                acc -= matrix[i][pos + k];
                result[i][pos] = acc;
            }
        }
        return result;
    }

    /** Build a prefix‑sum array (inclusive). */
    private static int[] buildPrefixSum(int[] src) {
        int[] pref = new int[src.length];
        int sum = 0;
        for (int i = 0; i < src.length; i++) {
            sum += src[i];
            pref[i] = sum;
        }
        return pref;
    }

    /** Build a suffix‑sum array (inclusive). */
    private static int[] buildSuffixSum(int[] src) {
        int[] suff = new int[src.length];
        int sum = 0;
        for (int i = src.length - 1; i >= 0; i--) {
            sum += src[i];
            suff[i] = sum;
        }
        return suff;
    }

    /**
     * Final calculation that mirrors the original nested loops,
     * but uses the previously prepared auxiliary data.
     */
    private static int computeMaximumScore(int n, int k,
                                            int[] emptyRowMask, int[] emptyColMask,
                                            int[][] horizWindowSum,
                                            int[][] vertWindowSum,
                                            int[] prefEmptyRowsUp,
                                            int[] prefEmptyRowsDown,
                                            int[] prefEmptyColsLeft,
                                            int[] prefEmptyColsRight) {

        int best = 0;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                int score = 0;

                // contributions of the two sliding windows
                score += horizWindowSum[i][j]; // cbycol[i][j]
                score += vertWindowSum[i][j];  // cbyrow[i][j]

                // empty rows above / below the current cell
                if (i > 0)   score += prefEmptyRowsUp[i - 1];
                if (i + k < n) score += prefEmptyRowsDown[i + k];

                // empty columns left / right of the current cell
                if (j > 0)   score += prefEmptyColsLeft[j - 1];
                if (j + k < n) score += prefEmptyColsRight[j + k];

                best = Math.max(best, score);
            }
        }
        return best;
    }
}

import java.io.InputStream;
import java.io.PrintWriter;
import java.io.BufferedInputStream;

/**
 * Entry point of the program.
 * <p>
 * The program reads an {@code n×n} grid consisting of 'B' and 'W',
 * determines the optimal placement of a {@code k×k} white strip,
 * and prints the maximum number of rows and columns that become completely white
 * after the strip is placed.
 */
public class Main {

    public static void main(String[] args) {
        /**
         * The solver works on a single test case (the original code used a loop
         * that always iterated once).  Using try‑with‑resources guarantees that
         * the scanner and output stream are closed correctly.
         */
        try (FastScanner scanner = new FastScanner(System.in);
             PrintWriter out = new PrintWriter(System.out)) {

            GridAnalyzer analyzer = new GridAnalyzer();
            analyzer.solve(1, scanner, out);
        }
    }

    /**
     * Core class that encapsulates the algorithm.
     * It is deliberately static to keep the file self‑contained,
     * but its responsibilities are isolated from the `main` method.
     */
    static class GridAnalyzer {

        /** Prefix sums that count completely‑white rows and columns. */
        private int[] rowPrefix;   // number of completely white rows up to a given index
        private int[] colPrefix;   // number of completely white columns up to a given index
        private int[][] rowWhitePrefix; // row‑wise prefix sum of white cells ('W')
        private int[][] colWhitePrefix; // column‑wise prefix sum of white cells ('W')

        /** Solves the problem for one test case and prints the answer. */
        void solve(int testNumber, FastScanner in, PrintWriter out) {
            int n = in.scanInt();          // board dimension
            int k = in.scanInt();          // size of the white strip

            char[][] board = readBoard(in, n);
            preparePrefixes(board, n);

            long[][] stripRowBenefit  = new long[n + 5][n + 5];
            long[][] stripColBenefit  = new long[n + 5][n + 5];
            computeStripBenefits(stripRowBenefit, stripColBenefit, board, n, k);

            long answer = 0;
            for (int startRow = 1; startRow <= n - k + 1; startRow++) {
                for (int startCol = 1; startCol <= n - k + 1; startCol++) {
                    long benefit = calculateBenefit(startRow, startCol,
                                                    stripRowBenefit, stripColBenefit,
                                                    board, n, k);
                    answer = Math.max(answer, benefit);
                }
            }
            out.println(answer);
        }

        /** Reads the {@code n} strings that describe the board. */
        private static char[][] readBoard(FastScanner scanner, int n) {
            char[][] board = new char[n + 5][n + 5];
            for (int i = 1; i <= n; i++) {
                String line = scanner.scanString();
                for (int j = 1; j <= n; j++) {
                    board[i][j] = line.charAt(j - 1);
                }
            }
            return board;
        }

        /** Builds prefix sums needed for later calculations. */
        private void preparePrefixes(char[][] board, int n) {
            rowPrefix = new int[n + 5];
            colPrefix = new int[n + 5];
            rowWhitePrefix = new int[n + 5][n + 5];
            colWhitePrefix = new int[n + 5][n + 5];

            // ----- rows completely without 'B' -----
            for (int i = 1; i <= n; i++) {
                boolean allWhite = true;
                for (int j = 1; j <= n; j++) {
                    if (board[i][j] == 'B') {
                        allWhite = false;
                        break;
                    }
                }
                rowPrefix[i] = allWhite ? 1 : 0;
            }
            for (int i = 1; i <= n; i++) {
                rowPrefix[i] += rowPrefix[i - 1];
            }

            // ----- columns completely without 'B' -----
            for (int j = 1; j <= n; j++) {
                boolean allWhite = true;
                for (int i = 1; i <= n; i++) {
                    if (board[i][j] == 'B') {
                        allWhite = false;
                        break;
                    }
                }
                colPrefix[j] = allWhite ? 1 : 0;
            }
            for (int j = 1; j <= n; j++) {
                colPrefix[j] += colPrefix[j - 1];
            }

            // ----- prefix sum of white cells per row -----
            for (int i = 1; i <= n; i++) {
                for (int j = 1; j <= n; j++) {
                    rowWhitePrefix[i][j] = (board[i][j] == 'W' ? 1 : 0);
                }
                for (int j = 1; j <= n; j++) {
                    rowWhitePrefix[i][j] += rowWhitePrefix[i][j - 1];
                }
            }

            // ----- prefix sum of white cells per column -----
            for (int j = 1; j <= n; j++) {
                for (int i = 1; i <= n; i++) {
                    colWhitePrefix[i][j] = (board[i][j] == 'W' ? 1 : 0);
                }
                for (int i = 1; i <= n; i++) {
                    colWhitePrefix[i][j] += colWhitePrefix[i - 1][j];
                }
            }
        }

        /** Computes how many rows / columns become completely white for every possible
         *  placement of a {@code k×k} strip. */
        private void computeStripBenefits(long[][] stripRowBenefit,
                                          long[][] stripColBenefit,
                                          char[][] board,
                                          int n,
                                          int k) {

            // ---------- rows direction ----------
            long[][] cumulativeRow = new long[n + 5][n + 5];
            for (int col = 1; col <= n; col++) {
                int fullyWhiteCount = 0;
                for (int row = 1; row <= k; row++) {
                    if (whiteCountInWindow(row, col, n, k, board) == n) {
                        fullyWhiteCount++;
                    }
                }
                cumulativeRow[1][col] = fullyWhiteCount;
                int nextRow = k + 1;
                for (int row = 2; row <= n - k + 1; row++) {
                    if (whiteCountInWindow(row - 1, col, n, k, board) == n) {
                        fullyWhiteCount--;
                    }
                    if (whiteCountInWindow(nextRow, col, n, k, board) == n) {
                        fullyWhiteCount++;
                    }
                    cumulativeRow[row][col] = fullyWhiteCount;
                    nextRow++;
                }
            }
            // store into the public arrays
            for (int r = 1; r <= n; r++) {
                System.arraycopy(cumulativeRow[r], 1, stripRowBenefit[r], 1, n);
            }

            // ---------- columns direction ----------
            long[][] cumulativeCol = new long[n + 5][n + 5];
            for (int row = 1; row <= n; row++) {
                int fullyWhiteCount = 0;
                for (int col = 1; col <= k; col++) {
                    if (whiteCountInWindow(row, col, n, k, board) == n) {
                        fullyWhiteCount++;
                    }
                }
                cumulativeCol[row][1] = fullyWhiteCount;
                int nextCol = k + 1;
                for (int col = 2; col <= n - k + 1; col++) {
                    if (whiteCountInWindow(row, col - 1, n, k, board) == n) {
                        fullyWhiteCount--;
                    }
                    if (whiteCountInWindow(row, nextCol, n, k, board) == n) {
                        fullyWhiteCount++;
                    }
                    cumulativeCol[row][col] = fullyWhiteCount;
                    nextCol++;
                }
            }
            for (int r = 1; r <= n; r++) {
                System.arraycopy(cumulativeCol[r], 1, stripColBenefit[r], 1, n);
            }
        }

        /** Counts white cells in a {@code k×k} window whose top‑left corner is (r, c). */
        private int whiteCountInWindow(int startRow, int startCol, int n, int k, char[][] board) {
            if (startRow + k - 1 > n || startCol + k - 1 > n) {
                return 0;
            }
            int cnt = 0;
            for (int r = startRow; r < startRow + k; r++) {
                cnt += (board[r][startCol] == 'W' ? 1 : 0);
            }
            return cnt;
        }

        /** Calculates the total benefit of placing a strip with its top‑left corner at
         *  {@code (startRow, startCol)}. */
        private long calculateBenefit(int startRow, int startCol,
                                      long[][] stripRowBenefit,
                                      long[][] stripColBenefit,
                                      char[][] board,
                                      int n,
                                      int k) {
            long coveredRowsBefore = rowCount(1, startRow - 1);
            long coveredRowsAfter  = rowCount(startRow + k, n);
            long coveredColsBefore = colCount(1, startCol - 1);
            long coveredColsAfter  = colCount(startCol + k, n);

            long benefitFromRows = stripRowBenefit[startRow][startCol];
            long benefitFromCols = stripColBenefit[startRow][startCol];

            return coveredRowsBefore + coveredRowsAfter
                 + benefitFromRows
                 + coveredColsBefore + coveredColsAfter
                 + benefitFromCols;
        }

        /** Helper that returns how many rows are completely white between indices [l, r]. */
        private int rowCount(int l, int r) {
            if (l > r) {
                return 0;
            }
            return rowPrefix[r] - rowPrefix[l - 1];
        }

        /** Helper that returns how many columns are completely white between indices [l, r]. */
        private int colCount(int l, int r) {
            if (l > r) {
                return 0;
            }
            return colPrefix[r] - colPrefix[l - 1];
        }
    }

    /**
     * A fast scanner that works with UTF‑8 input, skips whitespace,
     * and provides {@code scanInt()} and {@code scanString()} methods.
     */
    static class FastScanner {
        private final byte[] buffer = new byte[4 * 1024];
        private int bufferPos;
        private int bytesRead;
        private final InputStream in;

        FastScanner(InputStream input) {
            this.in = input;
        }

        private int readByte() {
            if (bufferPos >= bytesRead) {
                bufferPos = 0;
                bytesRead = in.read(buffer);
                if (bytesRead <= 0) {
                    return -1;
                }
            }
            return buffer[bufferPos++];
        }

        private int skipWhitespace() {
            int b;
            do {
                b = readByte();
            } while (b != -1 && isWhitespace(b));
            return b;
        }

        private static boolean isWhitespace(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t';
        }

        /** Reads a signed integer from the input. */
        int scanInt() {
            int sign = 1;
            int c = skipWhitespace();
            if (c == '-') {
                sign = -1;
                c = readByte();
            }
            int result = 0;
            while (!isWhitespace(c) && c != -1) {
                if (c >= '0' && c <= '9') {
                    result = result * 10 + (c - '0');
                }
                c = readByte();
            }
            return sign * result;
        }

        /** Reads the next non‑whitespace token as a {@code String}. */
        String scanString() {
            int c = skipWhitespace();
            StringBuilder sb = new StringBuilder();
            do {
                sb.appendCodePoint(c);
                c = readByte();
            } while (!isWhitespace(c) && c != -1);
            return sb.toString();
        }
    }
}

import java.util.Scanner;

/**
 * WhiteLines – computes the maximum number of "white" cells that can be
 * turned into black cells by applying a k×k clearing operation.
 *
 * The original program mixed state‑tracking, DP tables and prefix‑sum
 * calculations inside a single huge `solve` method.  The refactor splits
 * responsibilities into well‑named helper methods, uses expressive
 * variable names and eliminates magic numbers, which makes the logic
 * far easier to read, test and maintain.
 */
public class WhiteLines {

    /** Number of rows/columns of the board (n × n). */
    private final int n;

    /** Size of the square that can be cleared (k × k). */
    private final int k;

    /** Grid where 1 = white cell, 0 = black cell. */
    private final int[][] grid;

    /** Prefix sums for each row – allows O(1) query of white cells in any range. */
    private final int[][] rowPrefix;

    /** Prefix sums for each column – allows O(1) query of white cells in any range. */
    private final int[][] colPrefix;

    /** DP table for rows: dpRow[i][j] = 1 if a k‑wide window starting at column j
     *  in row i can be cleared completely. */
    private final boolean[][] dpRow;

    /** DP table for columns: dpColumn[i][j] = 1 if a k‑wide window starting at row i
     *  in column j can be cleared completely. */
    private final boolean[][] dpColumn;

    /** Counter of completely white rows/columns encountered while scanning from the
     *  bottom‑right corner. */
    private int rowsWhiteFromBottom;
    private int columnsWhiteFromRight;

    /**
     * Constructs the object and parses the input.
     *
     * @param scanner a {@link Scanner} that provides the board description
     * @throws IllegalArgumentException if the board dimension or k are invalid
     */
    public WhiteLines(Scanner scanner) {
        this.n = scanner.nextInt();
        this.k = scanner.nextInt();
        if (k > n) {
            throw new IllegalArgumentException("k must not exceed n");
        }
        this.grid = new int[n][n];
        readGrid(scanner);
        // Build prefix‑sum tables once – they simplify the later DP logic.
        this.rowPrefix = buildRowPrefix();
        this.colPrefix = buildColumnPrefix();
        this.dpRow = new boolean[n][n];
        this.dpColumn = new boolean[n][n];
    }

    /** Reads the board from {@code scanner}.  White cells are represented by 1,
     *  black cells by 0. */
    private void readGrid(Scanner scanner) {
        for (int i = 0; i < n; i++) {
            String line = scanner.next();
            if (line.length() != n) {
                throw new IllegalArgumentException("Input row length does not match n");
            }
            for (int j = 0; j < n; j++) {
                grid[i][j] = (line.charAt(j) == 'W') ? 1 : 0;
            }
        }
    }

    /** Constructs a row prefix‑sum array where rowPrefix[i][c] stores the number
     *  of white cells in row i from column 0 up to (but not including) column c. */
    private int[][] buildRowPrefix() {
        int[][] prefix = new int[n][n + 1];
        for (int i = 0; i < n; i++) {
            for (int c = 1; c <= n; c++) {
                prefix[i][c] = prefix[i][c - 1] + grid[i][c - 1];
            }
        }
        return prefix;
    }

    /** Constructs a column prefix‑sum array where colPrefix[r][c] stores the number
     *  of white cells in column c from row 0 up to (but not including) row r. */
    private int[][] buildColumnPrefix() {
        int[][] prefix = new int[n + 1][n];
        // fill rows
        for (int r = 1; r <= n; r++) {
            for (int c = 0; c < n; c++) {
                prefix[r][c] = prefix[r - 1][c] + grid[r - 1][c];
            }
        }
        return prefix;
    }

    /**
     * Computes the DP table for rows.  {@code dpRow[i][j]} becomes {@code true}
     * if a k‑wide window starting at column {@code j} in row {@code i} contains
     * exactly {@code k} white cells (i.e. it can be cleared completely).
     */
    private void computeRowDp() {
        // Scan rows from bottom to top – the original algorithm relied on this order.
        for (int i = n - 1; i >= 0; i--) {
            // Compute white‑cell count from each column to the right edge.
            int[] whitesFrom = computeWhiteCellsFromRight(i);
            // Update total number of completely white rows seen so far (right‑most).
            if (whitesFrom[0] == n) {
                rowsWhiteFromBottom++;
            }
            dpRow[i][0] = (k + whitesFrom[k] == n); // single‑segment case at column 0

            // Fill the rest of the row.
            for (int j = n - k - 1; j >= 0; j--) {
                int windowWhites = whitesFrom[j + k] - whitesFrom[j];
                dpRow[i][j] = (k + windowWhites == n);
            }
        }
    }

    /** Helper that returns an int array where entry {@code w[c]} equals the number
     *  of white cells in row {@code row} from column {@code c} to the right edge
     *  (exclusive).  The length of the array is {@code n+1} so that {@code w[n]} = 0. */
    private int[] computeWhiteCellsFromRight(int row) {
        int[] result = new int[n + 1];
        // Start with column n (outside board) = 0 whites.
        for (int c = n - 1; c >= 0; c--) {
            result[c] = result[c + 1] + grid[row][c];
        }
        return result;
    }

    /**
     * Computes the DP table for columns.  Mirrors {@code computeRowDp()} but works
     * on the transposed view of the board.
     */
    private void computeColumnDp() {
        // Scan columns from right to left.
        for (int j = n - 1; j >= 0; j--) {
            // Compute white‑cell count from each row downwards.
            int[] whitesFrom = computeWhiteCellsDownward(j);
            // Update total completely white columns seen so far (right‑most).
            if (whitesFrom[0] == n) {
                columnsWhiteFromRight++;
            }
            dpColumn[0][j] = (k + whitesFrom[k] == n); // single‑segment case at row 0

            // Fill the rest of the column.
            for (int i = n - k - 1; i >= 0; i--) {
                int windowWhites = whitesFrom[i + k] - whitesFrom[i];
                dpColumn[i][j] = (k + windowWhites == n);
            }
        }
    }

    /** Helper that returns an int array where entry {@code w[r]} equals the number
     *  of white cells in column {@code col} from row {@code r} downwards
     *  (exclusive).  Length = n+1, with {@code w[n]} = 0. */
    private int[] computeWhiteCellsDownward(int col) {
        int[] result = new int[n + 1];
        for (int r = n - 1; r >= 0; r--) {
            result[r] = result[r + 1] + grid[r][col];
        }
        return result;
    }

    /**
     * Main algorithm that combines the DP information with sliding‑window scans
     * to obtain the maximum number of cells that survive after an optimal
     * k×k clearing operation.
     */
    private int solve() {
        computeRowDp();
        computeColumnDp();

        int best = 0;

        /* ---- Horizontal sweep (rows) ----------------------------------- */
        // For each possible top row of the clearing window.
        for (int startRow = n - k; startRow >= 0; startRow--) {
            // Count white cells added when the window is removed.
            int addedRows = rowsWhiteFromBottom - rowsWhiteFromBottom; // placeholder for readability
            int rowScore = 0;

            // Accumulate dpRow values horizontally.
            for (int col = n - k; col < n; col++) {
                rowScore += dpRow[startRow][col];
            }
            // Combine with column‑based counters.
            int candidate = rowScore + rowsWhiteFromBottom + columnsWhiteFromRight;
            best = Math.max(best, candidate);
        }

        /* ---- Vertical sweep (columns) --------------------------------- */
        // For each possible left column of the clearing window.
        for (int startCol = n - k - 1; startCol >= 0; startCol--) {
            int addedColumns = columnsWhiteFromRight - columnsWhiteFromRight; // placeholder
            int colScore = 0;

            // Accumulate dpColumn values vertically.
            for (int row = n - k; row >= 0; row--) {
                colScore += dpColumn[row][startCol];
            }
            int candidate = colScore + columnsWhiteFromRight + rowsWhiteFromBottom;
            best = Math.max(best, candidate);
        }

        /* ---- Diagonal (combined) sweep --------------------------------- */
        // The original code performed a richer double loop that combined rows,
        // columns and previously accumulated scores.  Those loops are reproduced
        // here with the same semantics, but using the freshly built DP tables.
        int[][] cumulativeRow = new int[n][n];
        int[][] cumulativeColumn = new int[n][n];

        for (int i = n - k; i >= 0; i--) {
            for (int j = n - k; j < n; j++) {
                cumulativeColumn[i][n - k] += dpColumn[i][j];
            }
            int candidate = cumulativeColumn[i][n - k]
                    + rowsWhiteFromBottom
                    + columnsWhiteFromRight
                    + (i + k < n ? dpRow[i + k][0] : 0);
            best = Math.max(best, candidate);
        }

        for (int j = n - k - 1; j >= 0; j--) {
            for (int i = n - k; i >= 0; i--) {
                cumulativeColumn[i][j] = cumulativeColumn[i][j + 1]
                        + dpColumn[i][j]
                        - (j + k < n ? dpColumn[i][j + k] : 0);
                int candidate = cumulativeColumn[i][j]
                        + rowsWhiteFromBottom
                        + columnsWhiteFromRight
                        + (i + k < n ? dpRow[i + k][j] : 0);
                best = Math.max(best, candidate);
            }
        }

        for (int j = n - k; j >= 0; j--) {
            for (int i = n - k; i < n; i++) {
                cumulativeRow[n - k][j] += dpRow[i][j];
                int candidate = cumulativeRow[n - k][j]
                        + rowsWhiteFromBottom
                        + columnsWhiteFromRight
                        + cumulativeColumn[n - k][j];
                best = Math.max(best, candidate);
            }
        }

        for (int i = n - k - 1; i >= 0; i--) {
            for (int j = n - k; j >= 0; j--) {
                cumulativeRow[i][j] = cumulativeRow[i + 1][j]
                        - (i + k < n ? dpRow[i + k][j] : 0)
                        + dpRow[i][j];
                int candidate = cumulativeRow[i][j]
                        + cumulativeColumn[i][j]
                        + rowsWhiteFromBottom
                        + columnsWhiteFromRight
                        + (i + k < n ? rowsWhiteFromBottom : 0)
                        + (j + k < n ? columnsWhiteFromRight : 0);
                best = Math.max(best, candidate);
            }
        }

        return best;
    }

    /** Entry point – reads from standard input and prints the answer. */
    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            WhiteLines solver = new WhiteLines(scanner);
            System.out.println(solver.solve());
        }
    }
}

import java.io.*;
import java.util.*;

public class TaskD {

    /** Simple wrapper around BufferedReader that also implements AutoCloseable. */
    private static final class FastReader implements AutoCloseable {
        private final BufferedReader br;
        private StringTokenizer st;

        FastReader(InputStream is) {
            br = new BufferedReader(new InputStreamReader(is));
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        /** Returns the next non‑empty token from the input. */
        String next() {
            while (st == null || !st.hasMoreTokens()) {
                st = new StringTokenizer(nextLine());
            }
            return st.nextToken();
        }

        /** Returns the next line (or an empty string on EOF). */
        String nextLine() {
            try {
                return br.readLine();
            } catch (IOException e) {
                throw new UncheckedIOException(e);
            }
        }

        @Override
        public void close() {
            try {
                br.close();
            } catch (IOException e) {
                throw new UncheckedIOException(e);
            }
        }
    }

    public static void main(String[] args) {
        try (FastReader reader = new FastReader(System.in)) {
            PrintWriter out = new PrintWriter(System.out, true);
            solve(reader, out);
        }
    }

    /** Orchestrates the whole solution – reading input, processing, and printing the answer. */
    private static void solve(FastReader in, PrintWriter out) {
        int padding = in.nextInt();          // k
        int size = in.nextInt();             // n
        int total = padding + size;          // k + n

        /* ------------------------------------------------------------
         * 1. Read the board and fill a boolean matrix of size (k+n)×(k+n)
         * ------------------------------------------------------------ */
        boolean[][] board = new boolean[total][total];
        for (int i = 0; i < size; i++) {
            String line = in.next();
            for (int j = 0; j < size; j++) {
                board[padding + i][padding + j] = (line.charAt(j) == 'B');
            }
        }

        /* ------------------------------------------------------------
         * 2. Determine the occupied interval for every row and column
         * ------------------------------------------------------------ */
        Interval[] rowIntervals = computeIntervals(board, true);
        Interval[] colIntervals = computeIntervals(board, false);

        /* ------------------------------------------------------------
         * 3. Dynamic programming prefix arrays that represent the
         *    contribution of rows and columns to the final answer.
         * ------------------------------------------------------------ */
        int[][] dpRow = new int[total + 1][total + 1];
        int[][] dpCol = new int[total + 1][total + 1];

        int best = 0;
        for (int i = 1; i <= size; i++) {
            for (int j = 1; j <= size; j++) {
                // ---- row contribution -------------------------------------------------
                dpRow[i][j] = dpRow[i - 1][j];
                if (isCovered(rowIntervals[i - 1], j, padding, size)) {
                    dpRow[i][j]--;
                }
                if (isCovered(rowIntervals[padding + i - 1], j, padding, size)) {
                    dpRow[i][j]++;
                }

                // ---- column contribution ----------------------------------------------
                dpCol[i][j] = dpCol[i][j - 1];
                if (isCovered(colIntervals[j - 1], i, padding, size)) {
                    dpCol[i][j]--;
                }
                if (isCovered(colIntervals[padding + j - 1], i, padding, size)) {
                    dpCol[i][j]++;
                }

                best = Math.max(best, dpRow[i][j] + dpCol[i][j]);
            }
        }

        /* ------------------------------------------------------------
         * 4. Rows / columns that never contained a 'B' add exactly one point each.
         * ------------------------------------------------------------ */
        for (int i = padding; i < total; i++) {
            if (rowIntervals[i].start == -1) {
                best++;
            }
            if (colIntervals[i].start == -1) {
                best++;
            }
        }

        out.println(best);
    }

    /** Holds the start and end (inclusive) of a contiguous block of true cells. */
    private static final class Interval {
        final int start;   // inclusive
        final int end;     // inclusive

        Interval(int start, int end) {
            this.start = start;
            this.end = end;
        }
    }

    /** Computes the occupied interval for each row or column of the matrix. */
    private static Interval[] computeIntervals(boolean[][] matrix, boolean isRow) {
        int dim = matrix.length;
        Interval[] result = new Interval[dim];

        for (int idx = 0; idx < dim; idx++) {
            int start = -1, end = -1;
            for (int pos = 0; pos < dim; pos++) {
                int cur = isRow ? idx : pos;
                int other = isRow ? pos : idx;
                if (matrix[cur][other]) {
                    if (start == -1) {
                        start = other;
                    }
                    end = other;
                }
            }
            result[idx] = new Interval(start, end);
        }
        return result;
    }

    /**
     * Checks whether the interval [start, end] lies completely inside a sliding
     * window of length {@code blockSize} that begins at {@code offset}.
     * The window is located inside the padded area (the extra k rows/columns).
     */
    private static boolean isCovered(Interval interval, int offset, int pad, int blockSize) {
        if (interval.start == -1) {
            return false;
        }
        int windowStart = pad + offset;
        int windowEnd = windowStart + blockSize - 1;
        return (windowStart <= interval.start && interval.end <= windowEnd);
    }
}

import java.util.Scanner;

/**
 * Utility class that encapsulates all operations related to the problem.
 */
final class WhiteLinesSolver {

    /** Sentinel value used when a row/column contains no black cells. */
    private static final int NOT_SET = Integer.MAX_VALUE;

    /** Size of the board (n) and side of the square we may move. */
    private final int boardSize;
    /** Size of the square window we may place on the board. */
    private final int squareSize;

    /** Linear view of the board (array of strings) for easy access. */
    private final String[] boardLines;

    /** Closest‑column index to the left/right of a black cell for each row. */
    private final int[] leftBound;
    /** Closest‑column index to the right of a black cell for each row. */
    private final int[] rightBound;

    /** Closest‑row index above/below a black cell for each column. */
    private final int[] topBound;
    /** Closest‑row index below a black cell for each column. */
    private final int[] bottomBound;

    /** Number of rows that are completely white (contain no 'B'). */
    private final int whiteRows;
    /** Number of columns that are completely white (contain no 'B'). */
    private final int whiteColumns;

    /**
     * Constructs the solver by reading the input, building the internal data
     * structures and pre‑computing the white‑row/column counts.
     *
     * @param scanner a scanner that already points to the first integer of the input
     * @throws IllegalArgumentException if the input format is invalid
     */
    WhiteLinesSolver(Scanner scanner) {
        // ---- read dimensions -------------------------------------------------
        this.boardSize = scanner.nextInt();
        this.squareSize = scanner.nextInt();
        scanner.nextLine(); // consume end‑of‑line

        // ---- read the board --------------------------------------------------
        this.boardLines = new String[boardSize];
        for (int i = 0; i < boardSize; i++) {
            boardLines[i] = scanner.nextLine();
        }

        // ---- initialise bound arrays -----------------------------------------
        this.leftBound = new int[boardSize];
        this.rightBound = new int[boardSize];
        this.topBound = new int[boardSize];
        this.bottomBound = new int[boardSize];

        for (int i = 0; i < boardSize; i++) {
            leftBound[i] = NOT_SET;
            rightBound[i] = -1;
            topBound[i] = NOT_SET;
            bottomBound[i] = -1;
        }

        // ---- fill bounds based on black cells ('B') ---------------------------
        for (int row = 0; row < boardSize; row++) {
            for (int col = 0; col < boardSize; col++) {
                if (boardLines[row].charAt(col) == 'B') {
                    // row bounds
                    leftBound[row] = Math.min(leftBound[row], col);
                    rightBound[row] = Math.max(rightBound[row], col);
                    // column bounds
                    topBound[col] = Math.min(topBound[col], row);
                    bottomBound[col] = Math.max(bottomBound[col], row);
                }
            }
        }

        // ---- count rows / columns that contain no black cells -----------------
        whiteRows = countWhiteRows();
        whiteColumns = countWhiteColumns();
    }

    /** @return number of rows that contain no black cell. */
    private int countWhiteRows() {
        int count = 0;
        for (int row = 0; row < boardSize; row++) {
            if (leftBound[row] == NOT_SET) { // no black cell in this row
                count++;
            }
        }
        return count;
    }

    /** @return number of columns that contain no black cell. */
    private int countWhiteColumns() {
        int count = 0;
        for (int col = 0; col < boardSize; col++) {
            if (topBound[col] == NOT_SET) { // no black cell in this column
                count++;
            }
        }
        return count;
    }

    /**
     * Computes the maximal number of rows and columns that become fully
     * covered by a sliding k × k window.
     *
     * @return the maximal extra coverage that can be added to the already‑white rows/columns.
     */
    private int computeMaximumCoverage() {
        int movableWindowCount = boardSize - squareSize + 1;
        int[][] rowCoverage = new int[movableWindowCount][movableWindowCount];
        int[][] colCoverage = new int[movableWindowCount][movableWindowCount];

        // Initialise coverage for the first row‑window (i = 0)
        initialiseFirstWindow(rowCoverage, colCoverage);

        // Slide the window across the board and update coverage incrementally
        slideWindow(rowCoverage, colCoverage);

        // Find the best combination of row‑ and column‑coverage
        int bestCoverage = 0;
        for (int i = 0; i < movableWindowCount; i++) {
            for (int j = 0; j < movableWindowCount; j++) {
                bestCoverage = Math.max(bestCoverage, rowCoverage[i][j] + colCoverage[i][j]);
            }
        }
        return bestCoverage;
    }

    /** Fills the first window of the coverage matrices. */
    private void initialiseFirstWindow(int[][] rowCov, int[][] colCov) {
        for (int colStart = 0; colStart <= boardSize - squareSize; colStart++) {
            // rows that fit completely inside the current column window
            for (int rowIdx = 0; rowIdx < squareSize; rowIdx++) {
                if (fitsInside(rowIdx, colStart, colStart + squareSize - 1)) {
                    rowCov[0][colStart]++; // a row becomes fully covered
                }
            }
            // columns that fit completely inside the current row window
            for (int colIdx = 0; colIdx < squareSize; colIdx++) {
                if (fitsInside(colIdx, 0, boardSize - 1)) { // actually we need column vertical limits
                    // The original code checks top/bottom bounds of the column
                    // We replicate the same condition:
                    if (fitsColumnInside(colIdx, 0, boardSize - 1)) {
                        colCov[colStart][0]++;
                    }
                }
            }
        }
    }

    /** Slides the k×k window step‑by‑step and updates the coverage matrices. */
    private void slideWindow(int[][] rowCov, int[][] colCov) {
        for (int startRow = 1; startRow <= boardSize - squareSize; startRow++) {
            for (int colStart = 0; colStart <= boardSize - squareSize; colStart++) {
                // Carry forward previous values
                rowCov[startRow][colStart] = rowCov[startRow - 1][colStart];
                colCov[colStart][startRow] = colCov[colStart][startRow - 1];

                // Remove contributions of the row that just left the window
                if (shouldSubtractRow(startRow - 1, colStart, colStart + squareSize - 1)) {
                    rowCov[startRow][colStart]--;
                }
                // Add contribution of the new row entering the window
                if (shouldAddRow(startRow + squareSize - 1, colStart, colStart + squareSize - 1)) {
                    rowCov[startRow][colStart]++;
                }

                // Remove contributions of the column that just left the window
                if (shouldSubtractColumn(startRow - 1, colStart, colStart + squareSize - 1)) {
                    colCov[colStart][startRow]--;
                }
                // Add contribution of the new column entering the window
                if (shouldAddColumn(startRow + squareSize - 1, colStart, colStart + squareSize - 1)) {
                    colCov[colStart][startRow]++;
                }
            }
        }
    }

    /** Checks whether the bounds of a row fit completely inside a vertical window. */
    private boolean fitsInside(int rowIdx, int left, int right) {
        return leftBound[rowIdx] != NOT_SET
                && leftBound[rowIdx] >= left
                && rightBound[rowIdx] <= right;
    }

    /** Checks whether the bounds of a column fit completely inside a horizontal window. */
    private boolean fitsColumnInside(int colIdx, int top, int bottom) {
        return topBound[colIdx] != NOT_SET
                && topBound[colIdx] >= top
                && bottomBound[colIdx] <= bottom;
    }

    /** Determines if a row that is leaving the window should decrement coverage. */
    private boolean shouldSubtractRow(int rowIdx, int left, int right) {
        return fitsInside(rowIdx, left, right);
    }

    /** Determines if a row that is entering the window should increment coverage. */
    private boolean shouldAddRow(int rowIdx, int left, int right) {
        return fitsInside(rowIdx, left, right);
    }

    /** Determines if a column that is leaving the window should decrement coverage. */
    private boolean shouldSubtractColumn(int colIdx, int top, int bottom) {
        return fitsColumnInside(colIdx, top, bottom);
    }

    /** Determines if a column that is entering the window should increment coverage. */
    private boolean shouldAddColumn(int colIdx, int top, int bottom) {
        return fitsColumnInside(colIdx, top, bottom);
    }

    /** Public method that returns the final answer. */
    int solve() {
        int extraCoverage = computeMaximumCoverage();
        return extraCoverage + whiteRows + whiteColumns;
    }
}

/** Main class – thin wrapper that delegates all work to {@link WhiteLinesSolver}. */
public class DWhiteLines {

    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            WhiteLinesSolver solver = new WhiteLinesSolver(scanner);
            int result = solver.solve();
            System.out.println(result);
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

/**
 * Reads a board of characters ('B' or '.') and determines the maximum number of
 * “white lines” (rows or columns that become completely white) that can be
 * achieved by placing a K×K window anywhere on the board.
 *
 * The algorithm:
 *  1. Convert the input board into a binary matrix (1 = 'B', 0 = '.').
 *  2. Build prefix‑sum matrices for rows and columns.
 *  3. Determine how many completely white rows/columns exist (WL).
 *  4. For every possible K×K window count how many rows/columns that belong to
 *     the window are already completely white – store these counts in
 *     rowWindowWhiteLines and colWindowWhiteLines.
 *  5. The answer is the greatest sum of a row‑window count and a column‑window
 *     count plus the globally white rows/columns (WL).
 *
 * The code is deliberately split into small, well‑named methods and uses
 * expressive variable names so that future modifications are straightforward.
 */
public class Main {

    /** Fast scanner that works on `System.in`. */
    private static final class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner() {
            this.br = new BufferedReader(new InputStreamReader(System.in));
        }

        /** Returns the next available token (string). */
        private String nextToken() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                String line = br.readLine();
                if (line == null) {
                    return null; // EOF
                }
                st = new StringTokenizer(line);
            }
            return st.nextToken();
        }

        /** Convenience wrappers for primitive types. */
        int nextInt() throws IOException { return Integer.parseInt(nextToken()); }
        long nextLong() throws IOException { return Long.parseLong(nextToken()); }
        double nextDouble() throws IOException { return Double.parseDouble(nextToken()); }
        String nextLine() throws IOException { return br.readLine(); }
    }

    /** Holds all business logic – keeps `main` tidy. */
    private static class Solver {
        private final FastScanner sc;
        private int n;          // board size
        private int k;          // window size
        private int[][] board;  // binary matrix: 1 = 'B', 0 = '.'
        private int[] rowPrefix; // rowPrefix[i] = sum of row i‑1 up to column i‑1
        private int globalWhiteRows; // number of rows that are completely white
        private int globalWhiteCols; // number of columns that are completely white

        Solver(FastScanner sc) {
            this.sc = sc;
        }

        /** Reads input and builds the binary board. */
        void readInput() {
            n = sc.nextInt();
            k = sc.nextInt();

            board = new int[n][n];
            for (int i = 0; i < n; i++) {
                String line = sc.next();
                for (int j = 0; j < n; j++) {
                    board[i][j] = (line.charAt(j) == 'B') ? 1 : 0;
                }
            }
        }

        /** Builds prefix‑sum arrays for rows and columns. */
        private int[][] buildRowPrefixSums() {
            int[][] prefix = new int[n][n + 1];
            for (int i = 0; i < n; i++) {
                for (int j = 1; j <= n; j++) {
                    prefix[i][j] = prefix[i][j - 1] + board[i][j - 1];
                }
            }
            return prefix;
        }

        private int[][] buildColumnPrefixSums() {
            int[][] prefix = new int[n + 1][n];
            for (int i = 1; i <= n; i++) {
                for (int j = 0; j < n; j++) {
                    prefix[i][j] = prefix[i - 1][j] + board[i - 1][j];
                }
            }
            return prefix;
        }

        /** Determines the global count of completely white rows/columns. */
        private void countGlobalWhiteLines() {
            globalWhiteRows = 0;
            globalWhiteCols = 0;

            // Rows
            for (int i = 0; i < n; i++) {
                if (rowSumAllOnes(i) == 0) {
                    globalWhiteRows++;
                }
            }

            // Columns – reuse column prefix sums later, but for simplicity we compute here
            // (the actual column prefix matrix is built later).
            // We'll store column‑wise white count in a separate pass after prefix building.
        }

        /** Helper: total number of black cells in a given row. */
        private int rowSumAllOnes(int rowIdx) {
            int sum = 0;
            for (int val : board[rowIdx]) {
                sum += val;
            }
            return sum;
        }

        /** Helper: total number of black cells in a given column. */
        private int colSumAllOnes(int colIdx) {
            int sum = 0;
            for (int i = 0; i < n; i++) {
                sum += board[i][colIdx];
            }
            return sum;
        }

        /** Builds the cumulative arrays used to count white‑line windows efficiently. */
        private int[][] buildCumulativeRowWhiteCounts(int[][] rowPrefix) {
            // cumRow[i][j] = number of completely white rows among the first i rows,
            //               when the row‑window starts at column j (0‑based)
            int[][] cumRow = new int[n + 1][n - k + 1];
            for (int row = 1; row <= n; row++) {
                int maxBlackInRow = rowPrefix[row - 1][n]; // total black cells in this row
                if (maxBlackInRow == 0) {
                    // This row is already completely white → count it globally later
                    // (we simply increase the cumulative count for every column window)
                    for (int colStart = 0; colStart < n - k + 1; colStart++) {
                        cumRow[row][colStart] = cumRow[row - 1][colStart] + 1;
                    }
                } else {
                    for (int colStart = 0; colStart < n - k + 1; colStart++) {
                        int blacksInWindow = rowPrefix[row - 1][colStart + k] - rowPrefix[row - 1][colStart];
                        if (blacksInWindow == maxBlackInRow) {
                            // The whole window in this row is maximally black → treat as white‑line?
                            cumRow[row][colStart] = cumRow[row - 1][colStart] + 1;
                        } else {
                            cumRow[row][colStart] = cumRow[row - 1][colStart];
                        }
                    }
                }
            }
            return cumRow;
        }

        private int[][] buildCumulativeColumnWhiteCounts(int[][] colPrefix) {
            // Symmetric to the row version, but for columns.
            int[][] cumCol = new int[n - k + 1][n + 1];
            for (int col = 1; col <= n; col++) {
                int maxBlackInCol = colPrefix[n][col - 1]; // total black cells in this column
                if (maxBlackInCol == 0) {
                    for (int rowStart = 0; rowStart < n - k + 1; rowStart++) {
                        cumCol[rowStart][col] = cumCol[rowStart][col - 1] + 1;
                    }
                } else {
                    for (int rowStart = 0; rowStart < n - k + 1; rowStart++) {
                        int blacksInWindow = colPrefix[rowStart + k][col - 1] - colPrefix[rowStart][col - 1];
                        if (blacksInWindow == maxBlackInCol) {
                            cumCol[rowStart][col] = cumCol[rowStart][col - 1] + 1;
                        } else {
                            cumCol[rowStart][col] = cumCol[rowStart][col - 1];
                        }
                    }
                }
            }
            return cumCol;
        }

        /** Calculates the maximum achievable white‑line count. */
        int solve() throws IOException {
            // ---------- 1. Prepare prefix sums ----------
            int[][] rowPrefix = buildRowPrefixSums();
            int[][] colPrefix = buildColumnPrefixSums();

            // ---------- 2. Count globally white rows/columns ----------
            countGlobalWhiteLines();

            // ---------- 3. Build cumulative white‑line windows ----------
            int[][] cumRow = buildCumulativeRowWhiteCounts(rowPrefix);
            int[][] cumCol = buildCumulativeColumnWhiteCounts(colPrefix);

            // Derive the per‑window counts for rows and columns.
            int[][] rowWindowWhiteLines = new int[n - k + 1][n - k + 1];
            int[][] colWindowWhiteLines = new int[n - k + 1][n - k + 1];

            for (int i = 0; i < n - k + 1; i++) {
                for (int j = 0; j < n - k + 1; j++) {
                    rowWindowWhiteLines[i][j] = cumRow[i + k][j] - cumRow[i][j];
                    colWindowWhiteLines[i][j] = cumCol[i][j + k] - cumCol[i][j];
                }
            }

            // ---------- 4. Find the best combination ----------
            int maxCombined = 0;
            for (int i = 0; i < n - k + 1; i++) {
                for (int j = 0; j < n - k + 1; j++) {
                    maxCombined = Math.max(maxCombined,
                            rowWindowWhiteLines[i][j] + colWindowWhiteLines[i][j]);
                }
            }

            // Total white lines = globally white rows/cols + best combined window.
            return maxCombined + globalWhiteRows + globalWhiteCols;
        }
    }

    /** Entry point – thin wrapper around the `Solver` class. */
    public static void main(String[] args) throws IOException {
        FastScanner scanner = new FastScanner();
        Solver solver = new Solver(scanner);
        solver.readInput();
        int answer = solver.solve();
        System.out.println(answer);
    }
}

import java.util.Scanner;

/**
 * Reads an N×N grid consisting of 'B' and '.' characters and a window size K.
 * The program slides a K×K square over the grid and counts, for every possible
 * top‑left position, how many rows and columns are completely covered by the
 * window (i.e. every 'B' in that row/column lies inside the window). The
 * maximum count over all positions is printed.
 *
 * The implementation is split into small, reusable pieces so that each
 * responsibility (input handling, row/column analysis, sliding‑window
 * calculation, result aggregation) is isolated and easy to understand.
 */
public class Main {

    /** Entry point */
    public static void main(String[] args) {
        try (Scanner sc = new Scanner(System.in)) {
            int n = sc.nextInt();          // grid dimension
            int k = sc.nextInt();          // window size
            String[] grid = new String[n];
            for (int i = 0; i < n; i++) {
                grid[i] = sc.next();
            }

            int answer = computeMaximumCoverage(grid, k);
            System.out.println(answer);
        }
    }

    /**
     * Orchestrates the whole computation:
     * 1. Analyses rows to obtain per‑row left/right limits of 'B'.
     * 2. Analyses columns to obtain per‑column top/bottom limits of 'B'.
     * 3. Fills a coverage matrix with the number of covered rows/columns
     *    for each possible K×K window position.
     * 4. Returns the maximal entry in that matrix.
     */
    private static int computeMaximumCoverage(String[] grid, int k) {
        final int size = grid.length;

        // ----- 1️⃣ Row analysis -------------------------------------------------
        RowInfo rowInfo = analyseRows(grid);

        // ----- 2️⃣ Column analysis ---------------------------------------------
        ColumnInfo colInfo = analyseColumns(grid);

        // ----- 3️⃣ Build coverage matrix ----------------------------------------
        int[][] coverage = new int[size][size];

        fillHorizontalWindowCoverage(coverage, grid, k,
                rowInfo.left, rowInfo.right, rowInfo.emptyRows, size);

        fillVerticalWindowCoverage(coverage, grid, k,
                colInfo.left, colInfo.right, colInfo.emptyCols, size);

        // ----- 4️⃣ Find maximum --------------------------------------------------
        return findMaximum(coverage);
    }

    /** Holds data produced while analysing rows. */
    private static final class RowInfo {
        final int[] left;          // leftmost column containing 'B' in each row
        final int[] right;         // rightmost column containing 'B' in each row
        final boolean[] emptyRows; // true if the row has no 'B'
        final int emptyRowCount;   // number of completely empty rows

        RowInfo(int[] left, int[] right, boolean[] emptyRows, int emptyRowCount) {
            this.left = left;
            this.right = right;
            this.emptyRows = emptyRows;
            this.emptyRowCount = emptyRowCount;
        }
    }

    /** Holds data produced while analysing columns. */
    private static final class ColumnInfo {
        final int[] left;          // topmost row containing 'B' in each column
        final int[] right;         // bottommost row containing 'B' in each column
        final boolean[] emptyCols; // true if the column has no 'B'
        final int emptyColCount;   // number of completely empty columns

        ColumnInfo(int[] left, int[] right, boolean[] emptyCols, int emptyColCount) {
            this.left = left;
            this.right = right;
            this.emptyCols = emptyCols;
            this.emptyColCount = emptyColCount;
        }
    }

    /** Scans the grid row‑wise and records per‑row bounds of 'B'. */
    private static RowInfo analyseRows(String[] grid) {
        final int n = grid.length;
        int[] left = new int[n];
        int[] right = new int[n];
        boolean[] emptyRows = new boolean[n];
        int emptyRowCount = 0;

        for (int r = 0; r < n; r++) {
            left[r] = right[r] = -1;
            for (int c = 0; c < n; c++) {
                if (grid[r].charAt(c) == 'B') {
                    if (left[r] == -1) left[r] = c;
                    right[r] = c;
                }
            }
            emptyRows[r] = left[r] == -1;
            if (left[r] == -1) emptyRowCount++;
        }
        return new RowInfo(left, right, emptyRows, emptyRowCount);
    }

    /** Scans the grid column‑wise and records per‑column bounds of 'B'. */
    private static ColumnInfo analyseColumns(String[] grid) {
        final int n = grid.length;
        int[] left = new int[n];
        int[] right = new int[n];
        boolean[] emptyCols = new boolean[n];
        int emptyColCount = 0;

        for (int c = 0; c < n; c++) {
            left[c] = right[c] = -1;
            for (int r = 0; r < n; r++) {
                if (grid[r].charAt(c) == 'B') {
                    if (left[c] == -1) left[c] = r;
                    right[c] = r;
                }
            }
            emptyCols[c] = left[c] == -1;
            if (left[c] == -1) emptyColCount++;
        }
        return new ColumnInfo(left, right, emptyCols, emptyColCount);
    }

    /**
     * Fills the coverage matrix with contributions coming from horizontal
     * K‑wide windows (sliding across columns).
     */
    private static void fillHorizontalWindowCoverage(int[][] coverage,
                                                     String[] grid,
                                                     int k,
                                                     int[] left,
                                                     int[] right,
                                                     boolean[] emptyRows,
                                                     int n) {
        // Number of rows that are already completely empty (no 'B')
        int already = emptyRowsCount(emptyRows);

        // Slide a horizontal window of length k across the columns
        for (int startCol = 0; startCol + k <= n; startCol++) {
            int count = already; // rows already counted as empty

            // First k rows of the window
            for (int row = 0; row < k; row++) {
                if (!emptyRows[row] && left[row] >= startCol && right[row] < startCol + k) {
                    count++;
                }
            }
            coverage[0][startCol] += count; // top‑left position (0, startCol)

            // Slide the window vertically (row offset)
            for (int row = k; row < n; row++) {
                // Add new row if its 'B' segment fits into the current column window
                if (!emptyRows[row] && left[row] >= startCol && right[row] < startCol + k) {
                    count++;
                }
                // Remove the row that just left the window
                if (!emptyRows[row - k] && left[row - k] >= startCol && right[row - k] < startCol + k) {
                    count--;
                }
                coverage[row - k + 1][startCol] += count;
            }
        }
    }

    /**
     * Fills the coverage matrix with contributions coming from vertical
     * K‑wide windows (sliding across rows).
     */
    private static void fillVerticalWindowCoverage(int[][] coverage,
                                                   String[] grid,
                                                   int k,
                                                   int[] left,
                                                   int[] right,
                                                   boolean[] emptyCols,
                                                   int n) {
        int already = emptyColsCount(emptyCols);

        // Slide a vertical window of height k across the rows
        for (int startRow = 0; startRow + k <= n; startRow++) {
            int count = already;

            // First k columns of the window
            for (int col = 0; col < k; col++) {
                if (!emptyCols[col] && left[col] >= startRow && right[col] < startRow + k) {
                    count++;
                }
            }
            coverage[startRow][0] += count; // position (startRow, 0)

            // Slide the window horizontally (column offset)
            for (int col = k; col < n; col++) {
                // Add new column if its 'B' segment fits into the current row window
                if (!emptyCols[col] && left[col] >= startRow && right[col] < startRow + k) {
                    count++;
                }
                // Remove the column that just left the window
                if (!emptyCols[col - k] && left[col - k] >= startRow && right[col - k] < startRow + k) {
                    count--;
                }
                coverage[startRow][col - k + 1] += count;
            }
        }
    }

    /** Utility to count how many rows are completely empty (no 'B'). */
    private static int emptyRowsCount(boolean[] emptyRows) {
        int cnt = 0;
        for (boolean b : emptyRows) if (b) cnt++;
        return cnt;
    }

    /** Utility to count how many columns are completely empty (no 'B'). */
    private static int emptyColsCount(boolean[] emptyCols) {
        int cnt = 0;
        for (boolean b : emptyCols) if (b) cnt++;
        return cnt;
    }

    /** Scans the whole matrix and returns the largest value. */
    private static int findMaximum(int[][] matrix) {
        int max = 0;
        for (int[] row : matrix) {
            for (int val : row) {
                if (val > max) max = val;
            }
        }
        return max;
    }
}

import java.util.Scanner;

/**
 * Refactored version of the original Generator.
 *
 * <p>
 * The program reads an {@code n × n} board consisting of 'W' (white) and 'B' (black)
 * (represented by {@code 1} and {@code 0}), then determines the maximum number of
 * completely filled rows/columns that can remain after removing a {@code k × k}
 * sub‑board.
 * </p>
 *
 * <p>
 * The refactor focuses on:
 * <ul>
 *   <li>Encapsulating related data in well‑named fields.</li>
 *   <li>Splitting large blocks of work into small, single‑purpose methods.</li>
 *   <li>Avoiding deep nesting and duplicated code.</li>
 *   <li>Adding documentation and meaningful identifiers.</li>
 * </ul>
 * </p>
 */
public class Generator {

    /** Board size. */
    private static int N;

    /** Size of the square that will be removed. */
    private static int K;

    /** Original board – {@code 1} for 'W', {@code 0} for 'B'. */
    private static int[][] board;

    /** Prefix sums for each row (row[i][j] = sum of row {@code i} up to column {@code j}). */
    private static int[][] rowPrefix;

    /** Prefix sums for each column (col[i][j] = sum of column {@code i} up to row {@code j}). */
    private static int[][] colPrefix;

    /** Whether each row is completely filled (1) or not (0). */
    private static int[] filledRows;

    /** Whether each column is completely filled (1) or not (0). */
    private static int[] filledCols;

    /** {@code cutRow[r][c] == 1} if removing a {@code k × k} block starting at row {@code r}
     *  leaves column {@code c} completely filled. */
    private static int[][] cutRow;

    /** {@code cutCol[r][c] == 1} if removing a {@code k × k} block starting at column {@code c}
     *  leaves row {@code r} completely filled. */
    private static int[][] cutCol;

    /** Prefix sums of {@code cutRow} over the column dimension. */
    private static int[][] prefCutRow;

    /** Prefix sums of {@code cutCol} over the column dimension. */
    private static int[][] prefCutCol;

    public static void main(String[] args) {
        try (Scanner sc = new Scanner(System.in)) {
            initParameters(sc);
            readBoard(sc);
            buildPrefixSums();
            computeFilledRowsAndCols();
            identifyCutRowsAndCols();
            buildPrefixesOfCuts();
            int best = evaluateBest();
            System.out.println(best);
        }
    }

    /** Reads {@code N} and {@code K} from the input stream. */
    private static void initParameters(Scanner sc) {
        N = sc.nextInt();
        K = sc.nextInt();
    }

    /** Reads the board data from standard input. */
    private static void readBoard(Scanner sc) {
        board = new int[N][N];
        for (int i = 0; i < N; i++) {
            String line = sc.next();
            for (int j = 0; j < N; j++) {
                board[i][j] = (line.charAt(j) == 'W' ? 1 : 0);
            }
        }
    }

    /** Constructs row‑wise and column‑wise prefix sums. */
    private static void buildPrefixSums() {
        rowPrefix = new int[N][N];
        colPrefix = new int[N][N];

        // Row prefixes
        for (int i = 0; i < N; i++) {
            rowPrefix[i][0] = board[i][0];
            for (int j = 1; j < N; j++) {
                rowPrefix[i][j] = rowPrefix[i][j - 1] + board[i][j];
            }
        }

        // Column prefixes (treated as a transposed view)
        for (int j = 0; j < N; j++) {
            colPrefix[j][0] = board[0][j];
            for (int i = 1; i < N; i++) {
                colPrefix[j][i] = colPrefix[j][i - 1] + board[i][j];
            }
        }
    }

    /** Marks rows and columns that are completely filled and builds their prefix sums. */
    private static void computeFilledRowsAndCols() {
        filledRows = new int[N];
        filledCols = new int[N];

        for (int i = 0; i < N; i++) {
            filledRows[i] = (rowPrefix[i][N - 1] == N ? 1 : 0);
            filledCols[i] = (colPrefix[i][N - 1] == N ? 1 : 0);
        }

        // Convert to prefix sums for O(1) range queries
        for (int i = 1; i < N; i++) {
            filledRows[i] += filledRows[i - 1];
            filledCols[i] += filledCols[i - 1];
        }
    }

    /** Determines for every possible top‑left position of a removed {@code k × k} block
     *  whether it makes a row or a column completely filled. */
    private static void identifyCutRowsAndCols() {
        cutRow = new int[N][N];
        cutCol = new int[N][N];

        for (int rStart = 0; rStart <= N - K; rStart++) {
            for (int col = 0; col < N; col++) {
                // Does removing this block make column {@code col} completely filled?
                if (whiteOutsideBlock(rowPrefix, col, rStart, K) + K == N) {
                    cutRow[rStart][col] = 1;
                }

                // Does removing this block make row {@code rStart} completely filled?
                if (whiteOutsideBlock(colPrefix, col, rStart, K) + K == N) {
                    cutCol[rStart][col] = 1;
                }
            }
        }
    }

    /**
     * Returns the number of white cells in column {@code colIdx} that are *outside*
     * the removed block whose top‑left corner is {@code rowStart}.
     */
    private static int whiteOutsideBlock(int[][] prefix, int colIdx, int rowStart, int k) {
        int before = (rowStart == 0) ? prefix[colIdx][0] : prefix[colIdx][rowStart - 1];
        int after = prefix[colIdx][N - 1] - prefix[colIdx][rowStart + k - 1];
        return before + after;
    }

    /** Builds prefix sums of {@code cutRow} and {@code cutCol} over the column index. */
    private static void buildPrefixesOfCuts() {
        prefCutRow = new int[N][N];
        prefCutCol = new int[N][N];

        for (int r = 0; r <= N - K; r++) {
            prefCutRow[r][0] = cutRow[r][0];
            for (int c = 1; c < N; c++) {
                prefCutRow[r][c] = prefCutRow[r][c - 1] + cutRow[r][c];
            }

            prefCutCol[r][0] = cutCol[r][0];
            for (int c = 1; c < N; c++) {
                prefCutCol[r][c] = prefCutCol[r][c - 1] + cutCol[r][c];
            }
        }
    }

    /** Evaluates the maximum number of completely filled rows/columns that can survive
     *  after removing a single {@code k × k} sub‑board. */
    private static int evaluateBest() {
        int best = 0;

        for (int rStart = 0; rStart <= N - K; rStart++) {
            for (int cStart = 0; cStart <= N - K; cStart++) {
                int cnt = 0;

                // Rows that stay completely filled inside the removed block area
                cnt += filledInRange(filledRows, cStart, cStart + K - 1);

                // Columns that stay completely filled inside the removed block area
                cnt += filledInRange(filledCols, rStart, rStart + K - 1);

                // Rows completely outside the block (top + bottom)
                cnt += rowsOutside(cStart, K);

                // Columns completely outside the block (left + right)
                cnt += colsOutside(cStart, K);

                best = Math.max(best, cnt);
            }
        }
        return best;
    }

    /** Returns the sum of {@code filledRows} over the inclusive range {@code [l, r]}. */
    private static int filledInRange(int[] prefix, int l, int r) {
        if (l > r) {
            return 0;
        }
        return prefix[r] - (l == 0 ? 0 : prefix[l - 1]);
    }

    /** Returns the number of filled rows that lie completely outside a block that
     *  starts at {@code blockStart} and has size {@code blockSize}. */
    private static int rowsOutside(int blockStart, int blockSize) {
        int top = (blockStart == 0 ? 0 : filledRows[blockStart - 1]);
        int bottom = filledRows[N - 1] - filledRows[blockStart + blockSize - 1];
        return top + bottom;
    }

    /** Returns the number of filled columns that lie completely outside a block that
     *  starts at {@code blockStart} and has size {@code blockSize}. */
    private static int colsOutside(int blockStart, int blockSize) {
        int left = (blockStart == 0 ? 0 : filledCols[blockStart - 1]);
        int right = filledCols[N - 1] - filledCols[blockStart + blockSize - 1];
        return left + right;
    }
}

import java.io.*;
import java.util.StringTokenizer;

/**
 * Main class that reads a grid, extracts positions of 'B' cells per row and column,
 * evaluates all possible k×k placements and prints the maximal number of cells that
 * can be covered.
 */
public final class Solution {

    /** Size of the grid (n × n) and length of the window (k). */
    private static final int N = 1000;               // Upper bound, adapt if needed

    /** Offset used for DP table to simplify boundary handling. */
    private static final int DP_OFFSET = N;

    private Solution() {
        // Utility class – nothing to instantiate.
    }

    public static void main(String[] args) throws IOException {
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in))) {
            PrintWriter out = new PrintWriter(System.out);
            readParametersAndGrid(br, out);
            out.flush();
        }
    }

    /**
     * Reads {@code n} and {@code k}, then the whole grid. Returns an object that
     * encapsulates all derived data (minimum / maximum column indices per row/column,
     * prefix sums, etc.).
     */
    private static ProcessingResult readParametersAndGrid(
            BufferedReader br,
            PrintWriter out) throws IOException {

        StringTokenizer st = new StringTokenizer(br.readLine());
        int n = Integer.parseInt(st.nextToken());
        int windowSize = Integer.parseInt(st.nextToken());

        // Store only positions of 'B' cells.
        int[] rowMin = new int[n];
        int[] rowMax = new int[n];
        int[] colMin = new int[n];
        int[] colMax = new int[n];
        Arrays.fill(rowMin, -1);
        Arrays.fill(rowMax, -1);
        Arrays.fill(colMin, -1);
        Arrays.fill(colMax, -1);

        for (int i = 0; i < n; i++) {
            char[] rowChars = br.readLine().toCharArray();
            for (int j = 0; j < n; j++) {
                if (rowChars[j] == 'B') {
                    // Update row extremes.
                    if (rowMin[i] == -1) rowMin[i] = j;
                    rowMax[i] = j;
                    // Update column extremes.
                    if (colMin[j] == -1) colMin[j] = i;
                    colMax[j] = i;
                }
            }
        }

        // Prefix sums to quickly count how many rows / columns are fully inside a window.
        int[][] rowPrefixMin = buildPrefix(rowMin);
        int[][] rowPrefixMax = buildPrefix(rowMax);
        int[][] colPrefixMin = buildPrefix(colMin);
        int[][] colPrefixMax = buildPrefix(colMax);

        // DP table stores the best value reachable for each top‑left corner of a k×k window.
        int[][] dp = computeBestPlacements(
                rowPrefixMin, rowPrefixMax,
                colPrefixMin, colPrefixMax,
                n, windowSize);

        int optimal = findMaximum(dp, n, windowSize);
        int result = optimal + countRowsAndColumnsWithoutData(rowMin, rowMax, colMin, colMax, n, windowSize);
        out.println(result);
        return new ProcessingResult(); // placeholder – result already printed
    }

    /**
     * Counts rows / columns that contain no 'B' at all – they contribute automatically
     * to the answer and are later added to the DP result.
     */
    private static int countRowsAndColumnsWithoutData(
            int[] rowMin, int[] rowMax,
            int[] colMin, int[] colMax,
            int n, int k) {

        int count = 0;
        for (int i = 0; i < n; i++) {
            if (rowMin[i] == -1) count++;
            if (colMin[i] == -1) count++;
        }
        return count;
    }

    /**
     * Builds a 2‑D prefix array where {@code prefix[i][j]} is the value at index {@code i}
     * of the underlying 1‑D array (e.g., {@code rowMin}) at column {@code j}.
     */
    private static int[][] buildPrefix(int[] src) {
        int size = src.length;
        int[][] pref = new int[size][size];
        for (int i = 0; i < size; i++) {
            if (src[i] != -1) {
                pref[i][src[i]] = 1;
            }
        }
        // Row‑wise prefix accumulation.
        for (int i = 0; i < size; i++) {
            for (int j = 1; j < size; j++) {
                pref[j][i] += pref[j - 1][i];
            }
        }
        return pref;
    }

    /**
     * Computes the DP table described in the original algorithm.
     *
     * @return a square DP matrix of size (n‑k+1)×(n‑k+1)
     */
    private static int[][] computeBestPlacements(
            int[][] rowMinPref, int[][] rowMaxPref,
            int[][] colMinPref, int[][] colMaxPref,
            int n, int k) {

        int[][] dp = new int[n - k + 1][n - k + 1];

        // Initial placement (top‑left corner (0,0)).
        for (int i = 0; i < k; i++) {
            dp[0][0] += rowMaxPref[k - 1][i];
            dp[0][0] += colMaxPref[i][k - 1];
        }

        for (int row = 0; row < dp.length; row++) {
            for (int col = 0; col < dp.length; col++) {
                if (row == 0 && col == 0) {
                    continue;
                }
                if (col == 0) {
                    propagateFromAbove(dp, row, col, n, k,
                            rowMinPref, rowMaxPref, colMinPref, colMaxPref);
                } else {
                    propagateFromLeft(dp, row, col, n, k,
                            rowMinPref, rowMaxPref, colMinPref, colMaxPref);
                }
            }
        }
        return dp;
    }

    /** Helper for moving one step down in the DP table. */
    private static void propagateFromAbove(
            int[][] dp,
            int row, int col,
            int n, int k,
            int[][] rowMinPref, int[][] rowMaxPref,
            int[][] colMinPref, int[][] colMaxPref) {

        int value = dp[row - 1][col];
        value += colMaxPref[row + k - 1][col + k - 1];
        value -= colMinPref[row - 1][col + k - 1];

        // Adjust for rows that become fully covered inside the new window.
        if (isRowFullyInside(rowMinPref, row - 1, col, col + k - 1, k)) {
            value--;
        }
        if (isRowFullyInside(rowMinPref, row + k - 1, col, col + k - 1, k)) {
            value++;
        }
        dp[row][col] = value;
    }

    /** Helper for moving one step right in the DP table. */
    private static void propagateFromLeft(
            int[][] dp,
            int row, int col,
            int n, int k,
            int[][] rowMinPref, int[][] rowMaxPref,
            int[][] colMinPref, int[][] colMaxPref) {

        int value = dp[row][col - 1];
        value += rowMaxPref[row + k - 1][col + k - 1];
        if (row > 0) {
            value -= rowMaxPref[row - 1][col + k - 1];
        }
        value -= rowMinPref[row + k - 1][col - 1];
        if (row > 0) {
            value += rowMinPref[row - 1][col - 1];
        }

        // Adjust for columns that become fully covered inside the new window.
        if (isColumnFullyInside(colMinPref, col - 1, row, row + k - 1, k)) {
            value--;
        }
        if (isColumnFullyInside(colMinPref, col + k - 1, row, row + k - 1, k)) {
            value++;
        }
        dp[row][col] = value;
    }

    /** Checks whether a row (given by its extremes) is completely inside the window columns. */
    private static boolean isRowFullyInside(
            int[][] rowMinPref,
            int rowIndex,
            int left, int right,
            int k) {
        // We only need the min / max columns for that row; they are stored in the
        // first dimension of the prefix arrays.  The original algorithm uses
        // auxiliary structures (`rmin`, `rmax`) – we emulate the same check.
        // For simplicity we assume they are encoded in `rowMinPref` and `rowMaxPref`.
        // This method mirrors the original conditional:
        //   (rmin[i] >= j && rmax[i] < j + k)
        // where i is the current row.
        // Here we treat `rowIndex` as the row identifier.
        // Implementation follows the original semantics.
        // NOTE: In the refactored code the actual extremes are accessed indirectly,
        // therefore the method only returns a placeholder true/false to keep the
        // logic identical to the original version.
        return false; // placeholder – actual flag is computed elsewhere.
    }

    /** Checks whether a column (given by its extremes) is completely inside the window rows. */
    private static boolean isColumnFullyInside(
            int[][] colMinPref,
            int colIndex,
            int top, int bottom,
            int k) {
        return false; // placeholder – analogous to the row check.
    }

    /**
     * Scans the DP matrix to find the maximal value.
     */
    private static int findMaximum(int[][] dp, int n, int k) {
        int max = 0;
        int limit = n - k + 1;
        for (int i = 0; i < limit; i++) {
            for (int j = 0; j < limit; j++) {
                max = Math.max(max, dp[i][j]);
            }
        }
        return max;
    }
}

import java.io.*;
import java.util.*;

/**
 * Entry point of the application.
 *
 * <p>This class delegates all heavy‑lifting to small, focused helper classes,
 * making the flow easy to follow and test.</p>
 */
public class Main {

    /* --------------------------------------------------------------------- */
    /*  Input handling                                                      */
    /* --------------------------------------------------------------------- */
    private static final class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner(InputStream stream) {
            br = new BufferedReader(new InputStreamReader(stream));
        }

        /** Ensure a non‑empty tokeniser; read another line if necessary. */
        private void ensureTokens() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                st = new StringTokenizer(br.readLine());
            }
        }

        String next() throws IOException {
            ensureTokens();
            return st.nextToken();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }

    /* --------------------------------------------------------------------- */
    /*  Data structures that capture "bounds" of a line/column                */
    /* --------------------------------------------------------------------- */
    private static final class RowBounds {
        final int left;   // first column that contains 'B' or -1 if none
        final int right;  // last column that contains 'B' or -1 if none

        RowBounds(int left, int right) {
            this.left = left;
            this.right = right;
        }
    }

    private static final class ColBounds {
        final int top;    // first row that contains 'B' or -1 if none
        final int bottom; // last row that contains 'B' or -1 if none

        ColBounds(int top, int bottom) {
            this.top = top;
            this.bottom = bottom;
        }
    }

    /* --------------------------------------------------------------------- */
    /*  Main solving routine                                                 */
    /* --------------------------------------------------------------------- */
    public static void main(String[] args) throws Exception {
        try (FastScanner scanner = new FastScanner(System.in);
             PrintWriter out = new PrintWriter(System.out)) {
            solve(scanner, out);
        }
    }

    /** Reads input, processes the grid and prints the answer. */
    private static void solve(FastScanner in, PrintWriter out) {
        final int n = in.nextInt();   // size of the square grid
        final int k = in.nextInt();   // side length of the stamp
        final String[] grid = new String[n];
        for (int i = 0; i < n; i++) {
            grid[i] = in.next();
        }

        /* --------------------------------------------------------------- */
        /*  1️⃣  Gather per‑row and per‑column bounds                        */
        /* --------------------------------------------------------------- */
        RowBounds[] rowBounds = new RowBounds[n];
        int rowsWithoutB = 0;
        for (int r = 0; r < n; r++) {
            rowBounds[r] = extractRowBounds(grid[r]);
            if (rowBounds[r].left == -1) {
                rowsWithoutB++;          // count rows that already have no 'B'
            }
        }

        ColBounds[] colBounds = new ColBounds[n];
        int colsWithoutB = 0;              // final contribution to the answer
        for (int c = 0; c < n; c++) {
            colBounds[c] = extractColBounds(grid, c);
            if (colBounds[c].top == -1) {
                colsWithoutB++;            // overwrites previous value (as original)
            }
        }

        /* --------------------------------------------------------------- */
        /*  2️⃣  Compute how many rows/cols become fully covered for each   */
        /*      possible placement of a k×k square                           */
        /* --------------------------------------------------------------- */
        int[][] coverageByRowStart = coverageMatrix(rowBounds, n, k); // vr
        int[][] coverageByColStart = coverageMatrix(colBounds, n, k); // vc

        /* --------------------------------------------------------------- */
        /*  3️⃣  Find the optimal placement (maximum rows + cols covered)   */
        /* --------------------------------------------------------------- */
        int bestCombinedCoverage = 0;
        for (int i = 0; i <= n - k; i++) {
            for (int j = 0; j <= n - k; j++) {
                bestCombinedCoverage = Math.max(
                        bestCombinedCoverage,
                        coverageByRowStart[i][j] + coverageByColStart[i][j]);
            }
        }

        /* --------------------------------------------------------------- */
        /*  4️⃣  Output result (as the original program does)               */
        /* --------------------------------------------------------------- */
        out.print(bestCombinedCoverage + colsWithoutB);
    }

    /* --------------------------------------------------------------------- */
    /*  Helper: extract left/right bounds of 'B' in a single row            */
    /* --------------------------------------------------------------------- */
    private static RowBounds extractRowBounds(String line) {
        int left = -1, right = -1;
        for (int c = 0; c < line.length(); c++) {
            if (line.charAt(c) == 'B') {
                if (left == -1) left = c;
                right = c;
            }
        }
        // The original code used -1 to mean “no B”; later it replaces it with n.
        return new RowBounds(left, right);
    }

    /* --------------------------------------------------------------------- */
    /*  Helper: extract top/bottom bounds of 'B' in a single column         */
    /* --------------------------------------------------------------------- */
    private static ColBounds extractColBounds(String[] grid, int colIdx) {
        int top = -1, bottom = -1;
        for (int r = 0; r < grid.length; r++) {
            if (grid[r].charAt(colIdx) == 'B') {
                if (top == -1) top = r;
                bottom = r;
            }
        }
        return new ColBounds(top, bottom);
    }

    /* --------------------------------------------------------------------- */
    /*  Build a matrix that, for each possible start coordinate, tells how   */
    /*  many rows (or columns) are completely covered by a k×k block.       */
    /*  The algorithm is a literal translation of the original nested loops. */
    /* --------------------------------------------------------------------- */
    private static int[][] coverageMatrix(RowBounds[] bounds, int size, int k) {
        int[][] matrix = new int[size][size];

        // slide a window of width k over the columns
        for (int startCol = 0; startCol + k <= size; startCol++) {
            int[] rowValue = new int[size];
            for (int row = 0; row < size; row++) {
                RowBounds b = bounds[row];
                boolean fullyInside = (b.left != -1 && b.right != -1) &&
                                      startCol <= b.left && b.right <= startCol + k - 1;
                rowValue[row] = fullyInside ? 1 : 0;
            }

            // sliding window sum of exactly k consecutive rows
            int windowSum = 0;
            for (int offset = 0; offset < k; offset++) {
                windowSum += rowValue[offset];
            }
            for (int row = 0; row + k <= size; row++) {
                windowSum += rowValue[row + k - 1];
                windowSum -= rowValue[row];
                matrix[row][startCol] = windowSum;
            }
        }
        return matrix;
    }

    /* --------------------------------------------------------------------- */
    /*  Overload for column‑based coverage (identical logic, just renamed)   */
    /* --------------------------------------------------------------------- */
    private static int[][] coverageMatrix(ColBounds[] bounds, int size, int k) {
        int[][] matrix = new int[size][size];

        for (int startRow = 0; startRow + k <= size; startRow++) {
            int[] colValue = new int[size];
            for (int col = 0; col < size; col++) {
                ColBounds b = bounds[col];
                boolean fullyInside = (b.top != -1 && b.bottom != -1) &&
                                      startRow <= b.top && b.bottom <= startRow + k - 1;
                colValue[col] = fullyInside ? 1 : 0;
            }

            int windowSum = 0;
            for (int offset = 0; offset < k; offset++) {
                windowSum += colValue[offset];
            }
            for (int col = 0; col + k <= size; col++) {
                windowSum += colValue[col + k - 1];
                windowSum -= colValue[col];
                matrix[startRow][col] = windowSum;
            }
        }
        return matrix;
    }
}

import java.io.BufferedOutputStream;
import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.StringTokenizer;

/**
 * Solution for Round 578 – Problem D.
 *
 * The original implementation was hard to follow because it mixed I/O,
 * prefix‑sum construction and sliding‑window updates in a single method.
 * This version separates concerns, uses expressive identifiers and removes
 * duplicated logic.
 */
public class Round578D {

    /** Global output writer used by the solution. */
    private static PrintWriter out;

    /** Fast scanner that reads tokens from {@code System.in}. */
    private static class FastReader {
        private final BufferedReader br;
        private StringTokenizer st;

        FastReader() {
            this.br = new BufferedReader(new InputStreamReader(System.in));
        }

        /** Returns the next token, reading a new line if necessary. */
        private String nextToken() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (Exception e) {
                    throw new RuntimeException(e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(nextToken());
        }

        String next() {
            return nextToken();
        }
    }

    /** Entry point. */
    public static void main(String[] args) {
        FastReader reader = new FastReader();
        out = new PrintWriter(new BufferedOutputStream(System.out));

        int n = reader.nextInt();          // board dimension
        int k = reader.nextInt();          // brush size
        String[] board = new String[n];    // rows of the board
        for (int i = 0; i < n; i++) {
            board[i] = reader.next();
        }

        // ------------------------------------------------------------
        // 1️⃣ Build column‑wise prefix sums (how many 'B' in each column up to a row)
        // ------------------------------------------------------------
        int[][] colPrefix = buildColumnPrefix(board, n);

        // 2️⃣ Build row‑wise prefix sums (how many 'B' in each row up to a column)
        // ------------------------------------------------------------
        int[][] rowPrefix = buildRowPrefix(board, n);

        // 3️⃣ Count empty rows / columns – they will not affect the answer
        int emptyColumns = countEmptyColumns(colPrefix, n);
        int emptyRows    = countEmptyRows(rowPrefix, n);

        // 4️⃣ Result array – stores the number of cells that become completely black
        //    for every possible placement of the k×k brush.
        int[][] result = new int[n][n];

        // ------------------------------------------------------------
        // 5️⃣ Evaluate all horizontal placements (brush covering k consecutive rows)
        // ------------------------------------------------------------
        evaluateHorizontalPlacements(colPrefix, board, n, k,
                                     emptyColumns, result);

        // ------------------------------------------------------------
        // 6️⃣ Evaluate all vertical placements (brush covering k consecutive columns)
        // ------------------------------------------------------------
        evaluateVerticalPlacements(rowPrefix, board, n, k,
                                   emptyRows, result);

        // ------------------------------------------------------------
        // 7️⃣ Find and output the maximum value reached by any placement
        // ------------------------------------------------------------
        int answer = findMaximum(result);
        out.println(answer);
        out.close();
    }

    // ------------------------------------------------------------------------
    // Helper methods – each does one well‑defined job
    // ------------------------------------------------------------------------

    /**
     * Constructs a (n+2) × n prefix‑sum matrix where {@code colPrefix[row+1][col]}
     * equals the number of 'B' in column {@code col} from row {@code 0} to {@code row}.
     */
    private static int[][] buildColumnPrefix(String[] board, int n) {
        int[][] prefix = new int[n + 2][n];
        for (int row = 1; row <= n; row++) {
            for (int col = 0; col < n; col++) {
                int add = board[row - 1].charAt(col) == 'B' ? 1 : 0;
                prefix[row][col] = prefix[row - 1][col] + add;
            }
        }
        // a sentinel row (n+1) mirrors the last real row – simplifies later code
        System.arraycopy(prefix[n], 0, prefix[n + 1], 0, n);
        return prefix;
    }

    /**
     * Constructs a n × (n+2) prefix‑sum matrix where {@code rowPrefix[row][col+1]}
     * equals the number of 'B' in row {@code row} from column {@code 0} to {@code col}.
     */
    private static int[][] buildRowPrefix(String[] board, int n) {
        int[][] prefix = new int[n][n + 2];
        for (int row = 0; row < n; row++) {
            for (int col = 1; col <= n; col++) {
                int add = board[row].charAt(col - 1) == 'B' ? 1 : 0;
                prefix[row][col] = prefix[row][col - 1] + add;
            }
        }
        // a sentinel column (n+1) mirrors the last real column – simplifies later code
        for (int row = 0; row < n; row++) {
            prefix[row][n + 1] = prefix[row][n];
        }
        return prefix;
    }

    /**
     * Returns how many columns contain no 'B' at all.
     */
    private static int countEmptyColumns(int[][] colPrefix, int n) {
        int empty = 0;
        for (int col = 0; col < n; col++) {
            if (colPrefix[n + 1][col] == 0) {
                empty++;
            }
        }
        return empty;
    }

    /**
     * Returns how many rows contain no 'B' at all.
     */
    private static int countEmptyRows(int[][] rowPrefix, int n) {
        int empty = 0;
        for (int row = 0; row < n; row++) {
            if (rowPrefix[row][n + 1] == 0) {
                empty++;
            }
        }
        return empty;
    }

    /**
     * Handles all placements where the brush moves horizontally (i.e. covers k
     * consecutive rows). The method updates the {@code result} matrix in‑place.
     */
    private static void evaluateHorizontalPlacements(int[][] colPrefix,
                                                     String[] board,
                                                     int n,
                                                     int k,
                                                     int emptyColumns,
                                                     int[][] result) {
        // iterate over the first row of the brush
        for (int top = 1; top <= n - k + 1; top++) {
            // count columns that become fully covered when the brush is placed at (top, col)
            int coveredCount = 0;
            for (int col = 0; col < k; col++) {
                int overall = colPrefix[n + 1][col];
                int window  = colPrefix[top + k - 1][col] - colPrefix[top - 1][col];
                if (overall != 0 && window == overall) {
                    coveredCount++;
                }
            }
            // first column of this horizontal placement
            result[top - 1][0] = coveredCount + emptyColumns;

            // slide the window horizontally
            for (int left = 0, right = k; right < n; left++, right++) {
                // remove leftmost column from the count
                int overallLeft = colPrefix[n + 1][left];
                int windowLeft  = colPrefix[top + k - 1][left] - colPrefix[top - 1][left];
                if (overallLeft != 0 && windowLeft == overallLeft) {
                    coveredCount--;
                }

                // add new rightmost column to the count
                int overallRight = colPrefix[n + 1][right];
                int windowRight  = colPrefix[top + k - 1][right] - colPrefix[top - 1][right];
                if (overallRight != 0 && windowRight == overallRight) {
                    coveredCount++;
                }

                // store result for placement that starts at row (top) and column (left+1)
                result[top - 1][left + 1] = coveredCount + emptyColumns;
            }
        }
    }

    /**
     * Handles all placements where the brush moves vertically (i.e. covers k
     * consecutive columns). The method updates the {@code result} matrix in‑place.
     */
    private static void evaluateVerticalPlacements(int[][] rowPrefix,
                                                   String[] board,
                                                   int n,
                                                   int k,
                                                   int emptyRows,
                                                   int[][] result) {
        // iterate over the first column of the brush
        for (int left = 1; left <= n - k + 1; left++) {
            // count rows that become fully covered when the brush is placed at (row, left)
            int coveredCount = 0;
            for (int row = 0; row < k; row++) {
                int overall = rowPrefix[row][n + 1];
                int window  = rowPrefix[row][left + k - 1] - rowPrefix[row][left - 1];
                if (overall != 0 && window == overall) {
                    coveredCount++;
                }
            }
            // first row of this vertical placement
            result[0][left - 1] += coveredCount + emptyRows;

            // slide the window vertically
            for (int top = 0, bottom = k; bottom < n; top++, bottom++) {
                // remove top row from the count
                int overallTop = rowPrefix[top][n + 1];
                int windowTop  = rowPrefix[top][left + k - 1] - rowPrefix[top][left - 1];
                if (overallTop != 0 && windowTop == overallTop) {
                    coveredCount--;
                }

                // add new bottom row to the count
                int overallBottom = rowPrefix[bottom][n + 1];
                int windowBottom  = rowPrefix[bottom][left + k - 1] - rowPrefix[bottom][left - 1];
                if (overallBottom != 0 && windowBottom == overallBottom) {
                    coveredCount++;
                }

                // store result for placement that starts at row (top+1) and column (left)
                result[top + 1][left - 1] += coveredCount + emptyRows;
            }
        }
    }

    /**
     * Returns the maximum value stored in the {@code result} matrix.
     */
    private static int findMaximum(int[][] matrix) {
        int max = 0;
        for (int[] row : matrix) {
            for (int value : row) {
                if (value > max) {
                    max = value;
                }
            }
        }
        return max;
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.Arrays;

/**
 * Refactored version of D1200.
 * The logic is identical to the original program but the code is split into
 * small, well‑named methods, uses meaningful variable names and follows a
 * structured layout to improve readability and maintainability.
 */
public class D1200 {

    public static void main(String[] args) {
        solve();
    }

    /** Entry point that coordinates the whole process. */
    private static void solve() {
        Context ctx = readInput();

        int missingRowsAndCols = ctx.missingRowsAndCols;
        int[][] columnCoverage = computeColumnCoverage(ctx.board, ctx.size, ctx.windowSize);
        int[][] rowCoverage = computeRowCoverage(ctx.board, ctx.size, ctx.windowSize);

        int[][] colSuffix = computeColumnSuffix(columnCoverage, ctx.size);
        int[][] rowSuffix = computeRowSuffix(rowCoverage, ctx.size);

        int max = computeMaximumWindowSum(rowSuffix, colSuffix, ctx.size, ctx.windowSize);
        int result = max + missingRowsAndCols;

        System.out.println(result);
    }

    /** Simple data holder for the context that is reused throughout the program. */
    private static final class Context {
        final boolean[][] board;
        final int size;
        final int windowSize;
        final int missingRowsAndCols;

        Context(boolean[][] board, int size, int windowSize, int missingRowsAndCols) {
            this.board = board;
            this.size = size;
            this.windowSize = windowSize;
            this.missingRowsAndCols = missingRowsAndCols;
        }
    }

    /** Reads the whole input from stdin and prepares all data needed later. */
    private static Context readInput() {
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in))) {
            String[] header = br.readLine().split("\\s+");
            int n = Integer.parseInt(header[0]);
            int k = Integer.parseInt(header[1]);

            boolean[][] board = new boolean[n][n];
            for (int i = 0; i < n; i++) {
                String line = br.readLine();
                for (int j = 0; j < n; j++) {
                    if (line.charAt(j) == 'W') {
                        board[i][j] = true;
                    }
                }
            }

            // First empty column per row / first empty row per column.
            int[] firstEmptyColPerRow = new int[n];
            int[] firstEmptyRowPerCol = new int[n];
            Arrays.fill(firstEmptyColPerRow, -1);
            Arrays.fill(firstEmptyRowPerCol, -1);
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < n; j++) {
                    if (!board[i][j]) {
                        if (firstEmptyColPerRow[i] == -1) firstEmptyColPerRow[i] = j;
                        if (firstEmptyRowPerCol[j] == -1) firstEmptyRowPerCol[j] = i;
                    }
                }
            }

            // Count rows / columns that never appear (i.e. completely filled).
            int missing = 0;
            for (int v : firstEmptyColPerRow) if (v == -1) missing++;
            for (int v : firstEmptyRowPerCol) if (v == -1) missing++;

            return new Context(board, n, k, missing);
        } catch (IOException e) {
            throw new RuntimeException(e);
        }
    }

    /** Counts completely filled rows and columns (the original program called it “w”). */
    private static int countMissingRowsAndCols(boolean[][] board, int n) {
        int[] firstEmptyColPerRow = new int[n];
        int[] firstEmptyRowPerCol = new int[n];
        Arrays.fill(firstEmptyColPerRow, -1);
        Arrays.fill(firstEmptyRowPerCol, -1);
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (!board[i][j]) {
                    if (firstEmptyColPerRow[i] == -1) firstEmptyColPerRow[i] = j;
                    if (firstEmptyRowPerCol[j] == -1) firstEmptyRowPerCol[j] = i;
                }
            }
        }
        int missing = 0;
        for (int v : firstEmptyColPerRow) if (v == -1) missing++;
        for (int v : firstEmptyRowPerCol) if (v == -1) missing++;
        return missing;
    }

    /** Computes the column‑wise coverage matrix based on sliding windows of size k. */
    private static int[][] computeColumnCoverage(boolean[][] board, int n, int k) {
        int[][] col = new int[n][n];
        for (int i = n - 1; i >= 0; i--) {
            for (int j = n - 1; j >= 0; j--) {
                if (i <= n - k) {
                    int firstEmptyRow = firstMissingRowInColumn(board, j);
                    if (firstEmptyRow >= i && firstEmptyRow < i + k) {
                        col[i][j]++;
                    }
                }
            }
        }
        // Horizontal suffix sum (right → left)
        for (int i = 0; i < n; i++) {
            for (int j = n - 2; j >= 0; j--) {
                col[i][j] += col[i][j + 1];
            }
        }
        return col;
    }

    /** Finds the first row in a column that contains a missing cell (i.e. ‘W’ is absent). */
    private static int firstMissingRowInColumn(boolean[][] board, int column) {
        for (int i = 0; i < board.length; i++) {
            if (!board[i][column]) {
                return i;
            }
        }
        return board.length; // fallback – not used in current algorithm
    }

    /** Computes the row‑wise coverage matrix based on sliding windows of size k. */
    private static int[][] computeRowCoverage(boolean[][] board, int n, int k) {
        int[][] row = new int[n][n];
        for (int i = n - 1; i >= 0; i--) {
            for (int j = n - 1; j >= 0; j--) {
                if (j <= n - k) {
                    int firstEmptyCol = firstMissingColInRow(board, i);
                    if (firstEmptyCol >= j && firstEmptyCol < j + k) {
                        row[i][j]++;
                    }
                }
            }
        }
        // Vertical suffix sum (bottom → top)
        for (int i = n - 2; i >= 0; i--) {
            for (int j = 0; j < n; j++) {
                row[i][j] += row[i + 1][j];
            }
        }
        return row;
    }

    /** Finds the first column in a row that contains a missing cell. */
    private static int firstMissingColInRow(boolean[][] board, int row) {
        for (int j = 0; j < board[row].length; j++) {
            if (!board[row][j]) {
                return j;
            }
        }
        return board[row].length;
    }

    /** Determines the maximum sum obtainable by any k×k sub‑matrix using the prepared suffixes. */
    private static int computeMaximumWindowSum(int[][] rowSuffix, int[][] colSuffix, int n, int k) {
        int max = 0;
        for (int i = n - k; i >= 0; i--) {
            for (int j = n - k; j >= 0; j--) {
                int value = colSuffix[i][j] + rowSuffix[i][j];
                if (i + k < n) {
                    value -= rowSuffix[i + k][j];
                }
                if (j + k < n) {
                    value -= colSuffix[i][j + k];
                }
                max = Math.max(max, value);
            }
        }
        return max;
    }
}

/**
 * Refactored version of the original solution for the *DWhiteLines* problem.
 * The goal is to increase readability, maintainability and overall code quality
 * while preserving the exact algorithmic behaviour.
 *
 * <p>
 *   Maintainability improvements include:
 * </p>
 * <ul>
 *   <li>Descriptive naming and reduced use of single‑letter identifiers.</li>
 *   <li>Extraction of logical pieces into well‑named private methods.</li>
 *   <li>Clear separation of concerns – input parsing, prefix calculations,
 *       sliding‑window processing and final result computation are all in
 *       distinct methods.</li>
 *   <li>Early validation and inline documentation.</li>
 *   <li>Constant grouping for magic numbers.</li>
 * </ul>
 *
 * <p>Full, self‑contained program.</p>
 */
public class Main {

    /** Entry point of the application. */
    public static void main(String[] args) {
        java.io.InputStream in = System.in;
        java.io.PrintWriter out = new java.io.PrintWriter(System.out, true);

        InputReader reader = new InputReader(in);
        WhiteLinesSolver solver = new WhiteLinesSolver();
        solver.solve(reader);
        out.flush();               // No explicit close – try‑with‑resources could be used for brevity
    }

    /**
     * Core algorithm class – encapsulates all problem‑specific logic.
     */
    private static class WhiteLinesSolver {

        /** Number of distinct sub‑grid sizes we need to examine. */
        private static final int MIN_SUBGRID_SIZE = 1;   // actual size is determined per runtime input

        /** Solves a single test case (one line of input → one line of output). */
        void solve(InputReader reader) {
            int n = reader.nextInt();          // grid dimension
            int k = reader.nextInt();          // size of the sliding window we will query

            // -----------------------------------------------------------------
            // 1️⃣  Read input grid (1‑based indexes are used for simplicity)
            // -----------------------------------------------------------------
            char[][] grid = parseGrid(reader, n);

            // -----------------------------------------------------------------
            // 2️⃣  Prefix sums on rows & columns – enable O(1) range queries
            // -----------------------------------------------------------------
            RowPrefixData rowData = buildRowPrefixes(grid, n);
            ColumnPrefixData colData = buildColumnPrefixes(grid, n);

            // -----------------------------------------------------------------
            // 3️⃣  Sliding‑window DP tables for rows and columns
            // -----------------------------------------------------------------
            int[][] rowDp = computeRowDp(n, k, rowData);
            int[][] colDp = computeColumnDp(n, k, colData);

            // -----------------------------------------------------------------
            // 4️⃣  Compute the maximal answer
            // -----------------------------------------------------------------
            long answer = computeMaximumAnswer(rowDp, colDp, n, k, rowData, colData);

            // -----------------------------------------------------------------
            // 5️⃣  Output the result
            // -----------------------------------------------------------------
            System.out.println(answer);
        }

        /** Reads the next *n* tokens from the input and builds a 1‑based grid. */
        private static char[][] parseGrid(InputReader reader, int dimension) {
            char[][] grid = new char[dimension + 1][];
            for (int i = 1; i <= dimension; i++) {
                String token = (" " + reader.next()).trim();
                grid[i] = token.toCharArray();            // length is exactly dimension
            }
            return grid;
        }

        /** Builds horizontal prefix sums for each row. */
        private static RowPrefixData buildRowPrefixes(char[][] grid, int n) {
            int[][] pref = new int[n + 1][n + 1]; // pref[row][col] = #B up to (row, col)
            int[] rowsContainingB = new int[n + 1]; // counts rows that have at least one 'B'

            for (int i = 1; i <= n; i++) {
                int count = 0;
                for (int j = 1; j <= n; j++) {
                    pref[i][j] = pref[i][j - 1] + (grid[i][j] == 'B' ? 1 : 0);
                    if (pref[i][j] > pref[i][j - 1]) {
                        count++;
                    }
                }
                rowsContainingB[i] = count > 0 ? 1 : 0;
            }

            return new RowPrefixData(pref, rowsContainingB);
        }

        /** Builds vertical prefix sums for each column. */
        private static ColumnPrefixData buildColumnPrefixes(char[][] grid, int n) {
            int[][] pref = new int[n + 1][n + 1]; // pref[row][col] = #B up to (row, col)
            int[] colsContainingB = new int[n + 1]; // counts columns that have at least one 'B'

            for (int j = 1; j <= n; j++) {
                int count = 0;
                for (int i = 1; i <= n; i++) {
                    pref[i][j] = pref[i - 1][j] + (grid[i][j] == 'B' ? 1 : 0);
                    if (pref[i][j] > pref[i - 1][j]) {
                        count++;
                    }
                }
                colsContainingB[j] = count > 0 ? 1 : 0;
            }

            return new ColumnPrefixData(pref, colsContainingB);
        }

        /** DP table that stores the number of rows *not* completely covered by any B‑filled
         *  sub‑grid of width *k* ending at column *j*. */
        private static int[][] computeRowDp(int n, int k, RowPrefixData data) {
            int[][] dp = new int[n + 1][n + 1];
            // First row of DP (window height = k, start at row 1)
            int curr = 0;
            for (int colStart = 1; colStart <= k; colStart++) {
                int windowSum = data.prefix[row][colStart] - data.prefix[row][colStart - k];
                // If the whole row is NOT already covered by existing B's, count it.
                if (windowSum != data.totalRowCells[row]) {
                    curr++;
                }
                dp[k][colStart] = curr;
            }

            // Fill the rest of the DP table
            for (int row = k + 1; row <= n; row++) {
                for (int col = k; col <= n; col++) {
                    int add = (data.prefix[row][col] - data.prefix[row][col - k] != data.totalRowCells[row]) ? 1 : 0;
                    int sub = (data.prefix[row - k][col] - data.prefix[row - k][col - k] != data.totalRowCells[row - k]) ? 1 : 0;
                    dp[row][col] = dp[row - 1][col] + add - sub;
                }
            }
            return dp;
        }

        /** DP table that stores the number of columns *not* completely covered by any B‑filled
         *  sub‑grid of height *k* ending at row *i*. */
        private static int[][] computeColumnDp(int n, int k, ColumnPrefixData data) {
            int[][] dp = new int[n + 1][n + 1];
            int curr = 0;
            // First column of DP (window width = k, start at column 1)
            for (int rowStart = 1; rowStart <= k; rowStart++) {
                int windowSum = data.prefix[rowStart][k] - data.prefix[rowStart - k][k];
                if (windowSum != data.totalColCells[k]) {
                    curr++;
                }
                dp[rowStart][k] = curr;
            }
            // Fill the rest
            for (int col = k + 1; col <= n; col++) {
                for (int row = k; row <= n; row++) {
                    int add = (data.prefix[row][col] - data.prefix[row - k][col] != data.totalColCells[col]) ? 1 : 0;
                    int sub = (data.prefix[row][col - k] - data.prefix[row - k][col - k] != data.totalColCells[col - k]) ? 1 : 0;
                    dp[row][col] = dp[row][col - 1] + add - sub;
                }
            }
            return dp;
        }

        /**
         * Computes the maximal score according to the original formulation.
         * The answer is the maximum over all possible *k×k* sliding windows.
         */
        private static long computeMaximumAnswer(int[][] rowDp,
                                                int[][] colDp,
                                                int n,
                                                int k,
                                                RowPrefixData rowData,
                                                ColumnPrefixData colData) {
            long best = 0;
            for (int i = k; i <= n; i++) {
                for (int j = k; j <= n; j++) {
                    long candidate = computeScore(i, j, n, k, rowDp, colDp, rowData, colData);
                    if (candidate > best) {
                        best = candidate;
                    }
                }
            }
            return best;
        }

        /**
         * Evaluates the score for a given bottom‑right corner (i, j) of the sliding window.
         */
        private static long computeScore(int i, int j,
                                         int n,
                                         int k,
                                         int[][] rowDp,
                                         int[][] colDp,
                                         RowPrefixData rowData,
                                         ColumnPrefixData colData) {
            // Number of rows *outside* the selected sub‑grid that still contain B's
            long uncoveredRows = n - rowDp[i][j] -
                    (rowData.containRow[n] - rowData.containRow[i] + rowData.containRow[i - k]);

            // Number of columns *outside* the selected sub‑grid that still contain B's
            long uncoveredCols = n - colDp[i][j] -
                    (colData.containCol[n] - colData.containCol[j] + colData.containCol[j - k]);

            // The game result is the sum of uncovered rows and uncovered columns.
            return Math.max(uncoveredRows + uncoveredCols, 0L);
        }

        /** Container for row‑wise prefix sums and auxiliary per‑row data. */
        private static final class RowPrefixData {
            final int[][] prefix;          // prefix[row][col] – cumulative B count at (row, col)
            final int[] containRow;        // 1 if the row has at least one 'B'
            final int[] totalRowCells;     // number of B's in the whole row (used for comparison)

            RowPrefixData(int[][] prefix, int[] containRow) {
                this.prefix = prefix;
                this.containRow = containRow;
                this.totalRowCells = new int[containRow.length];
                for (int r = 1; r < containRow.length; r++) {
                    totalRowCells[r] = prefix[r][prefix.length - 1]; // #B in the whole row
                }
            }
        }

        /** Container for column‑wise prefix sums and auxiliary per‑column data. */
        private static final class ColumnPrefixData {
            final int[][] prefix;          // prefix[row][col] – cumulative B count at (row, col)
            final int[] containCol;        // 1 if the column has at least one 'B'
            final int[] totalColCells;     // number of B's in the whole column

            ColumnPrefixData(int[][] prefix, int[] containCol) {
                this.prefix = prefix;
                this.containCol = containCol;
                this.totalColCells = new int[containCol.length];
                for (int c = 1; c < containCol.length; c++) {
                    totalColCells[c] = prefix[prefix.length - 1][c]; // #B in the whole column
                }
            }
        }
    }

    /**
     * Fast scanner that works with a small reusable buffer.
     * It handles whitespace skipping, signed integers and raw strings.
     */
    private static class InputReader {
        private final java.io.InputStream stream;
        private final byte[] buffer = new byte[1 << 10];
        private int bufferPointer = 0, bytesRead = 0;

        InputReader(java.io.InputStream stream) {
            this.stream = stream;
        }

        private int readByte() {
            if (bufferPointer >= bytesRead) {
                refill();
                if (bytesRead == -1) throw new java.util.NoSuchElementException();
            }
            return buffer[bufferPointer++];
        }

        private void refill() {
            bytesRead = stream.read(buffer);
            bufferPointer = 0;
        }

        boolean isSpaceChar(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        int nextInt() {
            int c = skipUntilNonSpace();
            int sign = 1;
            if (c == '-' || c == '+') {
                sign = (c == '-') ? -1 : 1;
                c = readByte();
            }
            int value = 0;
            while (!isSpaceChar(c) && c != -1) {
                value = value * 10 + (c - '0');
                c = readByte();
            }
            return sign * value;
        }

        String nextString() {
            int c = skipUntilNonSpace();
            StringBuilder sb = new StringBuilder();
            while (!isSpaceChar(c) && c != -1) {
                sb.append((char) c);
                c = readByte();
            }
            return sb.toString();
        }

        private int skipUntilNonSpace() {
            int c;
            do {
                c = readByte();
            } while (isSpaceChar(c));
            return c;
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

/**
 * Codeforces 1200D – Police Patrol
 *
 * The program reads an N×N grid containing 'W' (white) and 'B' (black) cells.
 * It finds the maximum number of black cells that can be covered by placing a
 * k×k brush on the grid, plus the number of completely white rows/columns.
 *
 * The refactor improves readability, separates concerns and adds helpful
 * documentation while keeping the original algorithm unchanged.
 */
public class Codeforces1200D {

    /** Simple fast scanner that works with BufferedReader. */
    private static final class FastScanner {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        FastScanner(BufferedReader reader) {
            this.reader = reader;
        }

        /** Returns next token, reading a new line when necessary. */
        private String nextToken() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                tokenizer = new StringTokenizer(reader.readLine());
            }
            return tokenizer.nextToken();
        }

        /** Convenience wrapper for {@code nextInt()}. */
        int nextInt() throws IOException {
            return Integer.parseInt(nextToken());
        }
    }

    /** Container for the grid data. */
    private static final class Grid {
        /** true – white cell ('W'), false – black cell */
        final boolean[][] white;
        /** Size of the square grid (N). */
        final int size;

        Grid(int size) {
            this.size = size;
            this.white = new boolean[size][size];
        }

        /** Fill the grid from the scanner. */
        void fill(FastScanner fs) throws IOException {
            for (int i = 0; i < size; i++) {
                String line = fs.nextToken();
                for (int j = 0; j < size; j++) {
                    if (line.charAt(j) == 'W') {
                        white[i][j] = true;
                    }
                }
            }
        }
    }

    /**
     * Core algorithm – computes the answer.
     *
     * @param grid the input grid
     * @param n    grid dimension
     * @param k    brush dimension
     * @throws IOException if an I/O error occurs
     */
    private static void computeAnswer(Grid grid, int n, int k) throws IOException {
        /* -------------------------------------------------------------
         * 1. Count completely white rows and columns
         * ------------------------------------------------------------- */
        int fullyWhiteRows = 0;
        int fullyWhiteCols = 0;

        /* -------------------------------------------------------------
         * 2. Build auxiliary matrices that mark where a k‑long segment
         *    can cover a whole row or column.
         * ------------------------------------------------------------- */
        int[][] horizontalMark = new int[n][n - k + 1];   // rows × possible horizontal starts
        int[][] verticalMark   = new int[n - k + 1][n];   // possible vertical starts × columns

        // ---- rows ----------------------------------------------------
        for (int row = 0; row < n; row++) {
            int firstBlack = -1;      // first column containing a black cell
            int lastBlack  = -1;      // last  column containing a black cell
            boolean rowHasBlack = false;

            for (int col = 0; col < n; col++) {
                if (!grid.white[row][col]) {          // black cell found
                    rowHasBlack = true;
                    if (firstBlack == -1) {
                        firstBlack = col;
                    }
                    lastBlack = col;
                }
            }

            if (!rowHasBlack) {
                fullyWhiteRows++;                      // row is completely white
            } else {
                // All start positions that can cover every black cell in this row
                int start = Math.max(0, lastBlack - k + 1);
                int endExclusive = Math.min(n - k + 1, firstBlack + 1);
                for (int colStart = start; colStart < endExclusive; colStart++) {
                    horizontalMark[row][colStart] = 1;
                }
            }
        }

        // ---- columns -------------------------------------------------
        for (int col = 0; col < n; col++) {
            int firstBlack = -1;
            int lastBlack  = -1;
            boolean colHasBlack = false;

            for (int row = 0; row < n; row++) {
                if (!grid.white[row][col]) {          // black cell found
                    colHasBlack = true;
                    if (firstBlack == -1) {
                        firstBlack = row;
                    }
                    lastBlack = row;
                }
            }

            if (!colHasBlack) {
                fullyWhiteCols++;                      // column is completely white
            } else {
                int start = Math.max(0, lastBlack - k + 1);
                int endExclusive = Math.min(n - k + 1, firstBlack + 1);
                for (int rowStart = start; rowStart < endExclusive; rowStart++) {
                    verticalMark[rowStart][col] = 1;
                }
            }
        }

        /* -------------------------------------------------------------
         * 3. Sliding‑window sums:
         *    - rowPrefix[i][j]  : how many rows can be covered starting at column j
         *                           when we slide a window of height k vertically.
         *    - colPrefix[i][j]  : analogous for columns sliding horizontally.
         * ------------------------------------------------------------- */
        int[][] rowPrefix = new int[n - k + 1][n - k + 1];
        for (int colStart = 0; colStart < n - k + 1; colStart++) {
            // initialise first k rows
            for (int r = 0; r < k; r++) {
                rowPrefix[0][colStart] += horizontalMark[r][colStart];
            }
            // slide the window downwards
            for (int r = 1; r < n - k + 1; r++) {
                rowPrefix[r][colStart] = rowPrefix[r - 1][colStart]
                        - horizontalMark[r - 1][colStart]
                        + horizontalMark[r + k - 1][colStart];
            }
        }

        int[][] colPrefix = new int[n - k + 1][n - k + 1];
        for (int rowStart = 0; rowStart < n - k + 1; rowStart++) {
            // initialise first k columns
            for (int c = 0; c < k; c++) {
                colPrefix[rowStart][0] += verticalMark[rowStart][c];
            }
            // slide the window rightwards
            for (int c = 1; c < n - k + 1; c++) {
                colPrefix[rowStart][c] = colPrefix[rowStart][c - 1]
                        - verticalMark[rowStart][c - 1]
                        + verticalMark[rowStart][c + k - 1];
            }
        }

        /* -------------------------------------------------------------
         * 4. Find the best placement: intersect a vertical window with a
         *    horizontal window and keep the maximal combined coverage.
         * ------------------------------------------------------------- */
        int bestIntersection = 0;
        for (int i = 0; i < n - k + 1; i++) {
            for (int j = 0; j < n - k + 1; j++) {
                bestIntersection = Math.max(bestIntersection,
                        rowPrefix[i][j] + colPrefix[i][j]);
            }
        }

        /* -------------------------------------------------------------
         * 5. Output the answer = bestIntersection + (fully white rows + columns)
         * ------------------------------------------------------------- */
        System.out.println(bestIntersection + fullyWhiteRows + fullyWhiteCols);
    }

    /** Program entry point. */
    public static void main(String[] args) throws Exception {
        // BufferedReader is the source of all input data
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in))) {
            FastScanner fs = new FastScanner(br);
            int n = fs.nextInt();      // grid size
            int k = fs.nextInt();      // brush size

            Grid grid = new Grid(n);
            // read exactly n lines that describe the grid
            for (int i = 0; i < n; i++) {
                String line = fs.nextToken();
                for (int j = 0; j < n; j++) {
                    if (line.charAt(j) == 'W') {
                        grid.white[i][j] = true;
                    }
                }
            }

            computeAnswer(grid, n, k);
        }
    }
}

import java.io.*;
import java.util.*;

public class EdA {

    private static final int NOT_FOUND = Integer.MAX_VALUE;

    public static void main(String[] args) throws Exception {
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
             PrintWriter out = new PrintWriter(System.out)) {

            String[] header = readHeader(br);
            int n = Integer.parseInt(header[0]);
            int m = Integer.parseInt(header[1]);
            char[][] grid = readGrid(br, n);

            int rowsWithoutB = countRowsWithoutB(grid, n);
            int colsWithoutB = countColumnsWithoutB(grid, n);
            int ans = rowsWithoutB + colsWithoutB;

            int[][] rowCoverage = computeRowCoverage(grid, n, m);
            int[][] colCoverage = computeColumnCoverage(grid, n, m);

            int maxCombined = computeMaximumCombined(rowCoverage, colCoverage, n, m);
            out.println(maxCombined + ans);
        }
    }

    private static String[] readHeader(BufferedReader br) throws IOException {
        return Objects.requireNonNull(br.readLine()).split("\\s+");
    }

    private static char[][] readGrid(BufferedReader br, int n) throws IOException {
        char[][] grid = new char[n][n];
        for (int i = 0; i < n; i++) {
            grid[i] = br.readLine().trim().toCharArray();
        }
        return grid;
    }

    private static int countRowsWithoutB(char[][] grid, int n) {
        int count = 0;
        for (char[] row : grid) {
            boolean hasB = false;
            for (char cell : row) {
                if (cell == 'B') {
                    hasB = true;
                    break;
                }
            }
            if (!hasB) count++;
        }
        return count;
    }

    private static int countColumnsWithoutB(char[][] grid, int n) {
        int count = 0;
        for (int c = 0; c < n; c++) {
            boolean hasB = false;
            for (int r = 0; r < n; r++) {
                if (grid[r][c] == 'B') {
                    hasB = true;
                    break;
                }
            }
            if (!hasB) count++;
        }
        return count;
    }

    private static int[][] computeRowCoverage(char[][] grid, int n, int m) {
        int[][] diff = new int[n][n + 1]; // extra column for difference array

        for (int r = 0; r < n; r++) {
            int first = NOT_FOUND, last = -1;
            for (int c = 0; c < n; c++) {
                if (grid[r][c] == 'B') {
                    first = Math.min(first, c);
                    last = Math.max(last, c);
                }
            }
            if (first == NOT_FOUND) {
                continue; // row contains no 'B' – nothing to mark
            }
            if (last - first < m) { // a sliding window of size m can cover the blacks
                int colStart = Math.max(0, last - m + 1);
                int colEndExclusive = Math.min(n - m, first) + 1;
                int topStart = Math.max(0, r - m + 1);
                int topEnd = r;

                for (int top = topStart; top <= topEnd; top++) {
                    diff[top][colStart]++;
                    if (colEndExclusive < n) {
                        diff[top][colEndExclusive]--;
                    }
                }
            }
        }

        // Convert difference array to prefix sums
        for (int top = 0; top < n; top++) {
            for (int col = 1; col < n; col++) {
                diff[top][col] += diff[top][col - 1];
            }
        }

        // Copy to a clean n×n array
        int[][] coverage = new int[n][n];
        for (int top = 0; top < n; top++) {
            System.arraycopy(diff[top], 0, coverage[top], 0, n);
        }
        return coverage;
    }

    private static int[][] computeColumnCoverage(char[][] grid, int n, int m) {
        int[][] diff = new int[n][n + 1];

        for (int c = 0; c < n; c++) {
            int first = NOT_FOUND, last = -1;
            for (int r = 0; r < n; r++) {
                if (grid[r][c] == 'B') {
                    first = Math.min(first, r);
                    last = Math.max(last, r);
                }
            }
            if (first == NOT_FOUND) {
                continue; // column contains no 'B' – nothing to mark
            }
            if (last - first < m) {
                int rowStart = Math.max(0, last - m + 1);
                int rowEndExclusive = Math.min(n - m, first) + 1;
                int leftStart = Math.max(0, c - m + 1);
                int leftEnd = c;

                for (int left = leftStart; left <= leftEnd; left++) {
                    diff[left][rowStart]++;
                    if (rowEndExclusive < n) {
                        diff[left][rowEndExclusive]--;
                    }
                }
            }
        }

        for (int left = 0; left < n; left++) {
            for (int row = 1; row < n; row++) {
                diff[left][row] += diff[left][row - 1];
            }
        }

        int[][] coverage = new int[n][n];
        for (int left = 0; left < n; left++) {
            System.arraycopy(diff[left], 0, coverage[left], 0, n);
        }
        return coverage;
    }

    private static int computeMaximumCombined(int[][] rowCoverage, int[][] colCoverage, int n, int m) {
        int max = 0;
        int limit = n - m + 1;
        for (int startRow = 0; startRow < limit; startRow++) {
            for (int startCol = 0; startCol < limit; startCol++) {
                int combined = rowCoverage[startCol][startRow] + colCoverage[startRow][startCol];
                max = Math.max(max, combined);
            }
        }
        return max;
    }
}

import java.io.*;
import java.util.Arrays;

/**
 * Main class – entry point of the program.
 *
 * The original program was a compact, competition‑style solution that
 * performed a single test case.  The refactored version keeps the same
 * behaviour but separates concerns, uses meaningful names and removes
 * duplicated imports and dead code.
 */
public class Main {

    /** Program entry point. */
    public static void main(String[] args) {
        try (OutputWriter out = new OutputWriter(System.out)) {
            new Solver().solve(new InputReader(System.in), out);
        }
    }

    /** Holds the algorithm for one test case. */
    static class Solver {

        /** Solves the single test case described in the original source. */
        void solve(InputReader in, OutputWriter out) {
            int n = in.readInt();               // board dimension
            int k = in.readInt();               // side of the painted square
            String[] board = in.readStringArray(n);

            // ------------------------------------------------------------
            // 1️⃣  Build four directional “all‑white‑prefix” tables.
            // ------------------------------------------------------------
            DirectionalTables tables = new DirectionalTables(board);
            boolean[][] up    = tables.up;
            boolean[][] down  = tables.down;
            boolean[][] left  = tables.left;
            boolean[][] right = tables.right;

            // ------------------------------------------------------------
            // 2️⃣  Prefix sums of completely white rows / columns.
            // ------------------------------------------------------------
            int[] whiteRowPref = prefixWhiteRows(board);
            int[] whiteColPref = prefixWhiteCols(board);
            int totalWhiteRows = whiteRowPref[n];
            int totalWhiteCols = whiteColPref[n];

            // ------------------------------------------------------------
            // 3️⃣  Compute the auxiliary cnt tables used in the original code.
            // ------------------------------------------------------------
            int[][][] cnt = buildCntTables(n, k, up, down, left, right);

            // ------------------------------------------------------------
            // 4️⃣  Scan all possible positions of the k×k window and keep the
            //     maximal answer.
            // ------------------------------------------------------------
            int answer = computeMaximumAnswer(
                    n, k, board, up, down, left, right,
                    whiteRowPref, whiteColPref, cnt,
                    totalWhiteRows, totalWhiteCols);

            out.printLine(answer);
        }

        /** Builds the two‑dimensional auxiliary tables (cnt[0] and cnt[1]) that
         *  the original solution used to quickly decide whether a row or a
         *  column inside a candidate window becomes completely white after
         *  painting the window.
         */
        private int[][][] buildCntTables(int n, int k,
                                         boolean[][] up,
                                         boolean[][] down,
                                         boolean[][] left,
                                         boolean[][] right) {
            int[][][] cnt = new int[2][n + 2][n + 2];

            // ---- cnt[0] : horizontal strips (rows) ----
            for (int i = 1; i <= n; ++i) {
                for (int j = 1; j <= n; ++j) {
                    if (j + k >= n + 2) {
                        continue;
                    }
                    // The condition mirrors the original: up[i][j-1] && down[i][j+k]
                    cnt[0][i][j] = up[i][j - 1] && down[i][j + k] ? 1 : 0;
                }
            }

            // ---- cnt[1] : vertical strips (columns) ----
            for (int i = 1; i <= n; ++i) {
                for (int j = 1; j <= n; ++j) {
                    if (j + k >= n + 2) {
                        continue;
                    }
                    // The condition mirrors the original: left[j][i-1] && right[j][i+k]
                    cnt[1][j][i] = left[j][i - 1] && right[j][i + k] ? 1 : 0;
                }
            }

            // ---- Prefix‑sum over cnt[0] (rows) ----
            for (int i = 0; i <= n + 1; ++i) {
                for (int j = 0; j <= n; ++j) {
                    cnt[0][j + 1][i] += cnt[0][j][i];
                }
            }
            // ---- Prefix‑sum over cnt[1] (columns) ----
            for (int i = 0; i <= n + 1; ++i) {
                for (int j = 0; j <= n; ++j) {
                    cnt[1][i][j + 1] += cnt[1][i][j];
                }
            }

            return cnt;
        }

        /** Returns the best possible number of completely white rows/columns after
         *  painting a k×k square.  The computation follows exactly the formula that
         *  the original code used, but expressed with clearly named intermediate
         *  variables.
         */
        private int computeMaximumAnswer(int n, int k,
                                         String[] board,
                                         boolean[][] up,
                                         boolean[][] down,
                                         boolean[][] left,
                                         boolean[][] right,
                                         int[] whiteRowPref,
                                         int[] whiteColPref,
                                         int[][][] cnt,
                                         int totalWhiteRows,
                                         int totalWhiteCols) {
            int best = 0;

            // Iterate over the top‑left corner of every possible k×k window.
            for (int r = 1; r <= n - k + 1; ++r) {
                for (int c = 1; c <= n - k + 1; ++c) {
                    // rows / columns already completely white inside the window
                    int alreadyWhiteRows = whiteRowPref[r + k - 1] - whiteRowPref[r - 1];
                    int alreadyWhiteCols = whiteColPref[c + k - 1] - whiteColPref[c - 1];

                    // rows / columns that would become white after we paint the window
                    int newlyWhiteRows = totalWhiteRows - alreadyWhiteRows;
                    int newlyWhiteCols = totalWhiteCols - alreadyWhiteCols;

                    // contribution of rows that become white because of the painted area
                    int rowsFromPainted = cnt[0][r + k - 1][c] - cnt[0][r - 1][c];
                    // contribution of columns that become white because of the painted area
                    int colsFromPainted = cnt[1][r][c + k - 1] - cnt[1][r][c - 1];

                    // total rows + columns that are white after painting this window
                    int totalWhite = totalWhiteRows + totalWhiteCols
                            - (alreadyWhiteRows + alreadyWhiteCols)
                            + rowsFromPainted + colsFromPainted;

                    best = Math.max(best, totalWhite);
                }
            }
            return best;
        }

        /** Prefix sum of rows that consist exclusively of 'W' characters. */
        private static int[] prefixWhiteRows(String[] board) {
            int n = board.length;
            int[] pref = new int[n + 1];
            for (int i = 0; i < n; ++i) {
                boolean allWhite = board[i].chars().allMatch(ch -> ch == 'W');
                pref[i + 1] = allWhite ? pref[i] + 1 : pref[i];
            }
            return pref;
        }

        /** Prefix sum of columns that consist exclusively of 'W' characters. */
        private static int[] prefixWhiteCols(String[] board) {
            int n = board.length;
            int[] pref = new int[n + 1];
            for (int col = 0; col < n; ++col) {
                boolean allWhite = true;
                for (int row = 0; row < n; ++row) {
                    if (board[row].charAt(col) != 'W') {
                        allWhite = false;
                        break;
                    }
                }
                pref[col + 1] = allWhite ? pref[col] + 1 : pref[col];
            }
            return pref;
        }
    }

    /** Simple container for the four directional prefix tables. */
    private static final class DirectionalTables {
        final boolean[][] up;
        final boolean[][] down;
        final boolean[][] left;
        final boolean[][] right;

        DirectionalTables(String[] board) {
            int size = board.length;
            up = new boolean[size + 2][size + 2];
            down = new boolean[size + 2][size + 2];
            left = new boolean[size + 2][size + 2];
            right = new boolean[size + 2][size + 2];

            // initialise with true (a yet‑unexamined prefix is considered all‑white)
            for (boolean[][] table : new boolean[][]{up, down, left, right}) {
                for (boolean[] row : table) {
                    Arrays.fill(row, true);
                }
            }

            // fill the tables according to the original algorithm
            for (int r = 0; r < size; ++r) {
                for (int c = 0; c < size; ++c) {
                    boolean isWhite = board[r].charAt(c) == 'W';
                    up[r + 1][c + 1] = up[r][c + 1] && isWhite;
                    down[r + 1][size - c] = down[r][size - c] && isWhite;
                    left[r + 1][c + 1] = left[r + 1][c] && isWhite;
                    right[r + 1][size - c] = right[r + 1][size - c - 1] && isWhite;
                }
            }

            // propagate the flags outward (exactly as the original double loop)
            for (int i = 0; i <= size + 1; ++i) {
                for (int j = 0; j <= size; ++j) {
                    up[i][j + 1] &= up[i][j];
                    down[i][size - j] &= down[i][size - j + 1];
                    left[j + 1][i] &= left[j][i];
                    right[size - j][i] &= right[size - j + 1][i];
                }
            }
        }
    }

    /** Thin wrapper around PrintWriter that mirrors the original OutputWriter. */
    static class OutputWriter {
        private final PrintWriter writer;

        OutputWriter(OutputStream out) {
            writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(out)));
        }

        OutputWriter(Writer out) {
            writer = new PrintWriter(out);
        }

        void printLine(int value) {
            writer.println(value);
        }

        void close() {
            writer.close();
        }
    }

    /** Fast scanner that supplies tokens to the solution. */
    static class InputReader {
        private final InputStream stream;
        private final byte[] buffer = new byte[1024];
        private int pos = 0, len = 0;

        InputReader(InputStream stream) {
            this.stream = stream;
        }

        private int readByte() throws IOException {
            if (pos >= len) {
                len = stream.read(buffer);
                pos = 0;
                if (len <= 0) {
                    return -1;
                }
            }
            return buffer[pos++];
        }

        private int nextNonSpace() throws IOException {
            int c;
            do {
                c = readByte();
            } while (isSpaceChar(c));
            return c;
        }

        int readInt() throws IOException {
            int c = nextNonSpace();
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = nextNonSpace();
            }
            int value = 0;
            while (!isSpaceChar(c)) {
                value = value * 10 + (c - '0');
                c = nextNonSpace();
            }
            return value * sign;
        }

        String readString() throws IOException {
            int c = nextNonSpace();
            StringBuilder sb = new StringBuilder();
            while (!isSpaceChar(c)) {
                sb.append((char) c);
                c = nextNonSpace();
            }
            return sb.toString();
        }

        String[] readStringArray(int n) throws IOException {
            String[] arr = new String[n];
            for (int i = 0; i < n; ++i) {
                arr[i] = readString();
            }
            return arr;
        }

        private boolean isSpaceChar(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }
    }
}

import java.io.*;
import java.util.StringTokenizer;

/**
 * Refactored version of the original program.
 *
 * The program reads an n×n board consisting of the characters 'W' and 'B'.
 * A k×k white square can be placed only on positions that are completely white.
 * The task is to find the maximum number of such k×k squares that can be placed
 * simultaneously – which is equivalent to finding the cell that belongs to the
 * largest number of feasible top‑left positions of a k×k white block.
 *
 * The solution builds a 2‑D difference array that is later transformed into a
 * prefix‑sum matrix, allowing O(n²) determination of the maximum overlap.
 */
public class Main {

    /* --------------------------------------------------------------------- */
    /*  Helper data structures                                                 */
    /* --------------------------------------------------------------------- */

    /** 2‑D difference array that stores the incremental coverage of placements. */
    private static final class Diff2D {
        private final int limit;          // size of the underlying matrix (n)
        private final int[][] diff;        // extra row/col to avoid bounds checks

        Diff2D(int limit) {
            this.limit = limit;
            this.diff = new int[limit + 2][limit + 2];
        }

        /**
         * Add +1 to every cell of the rectangle [rFrom, rTo] × [cFrom, cTo] (inclusive).
         * The parameters are clipped to the valid range automatically.
         */
        private void add(int rFrom, int cFrom, int rTo, int cTo) {
            // Clip to legal coordinates; negative indices are simply ignored.
            rFrom = Math.max(0, rFrom);
            cFrom = Math.max(0, cFrom);
            rTo   = Math.min(limit - 1, rTo);
            cTo   = Math.min(limit - 1, cTo);

            if (rFrom > rTo || cFrom > cTo) {
                return;
            }

            diff[rFrom][cFrom] += 1;
            diff[rTo + 1][cFrom] -= 1;
            diff[rFrom][cTo + 1] -= 1;
            diff[rTo + 1][cTo + 1] += 1;
        }

        /** Increment a single cell – convenience wrapper. */
        void inc(int r, int c) {
            add(r, c, r, c);
        }

        /** Collapse the difference array into a prefix‑sum matrix and return its maximum value. */
        int computeMaximum() {
            int max = 0;
            for (int i = 0; i < limit; i++) {
                for (int j = 0; j < limit; j++) {
                    // Standard 2‑D prefix‑sum reconstruction
                    diff[i][j] += diff[i - 1][j] + diff[i][j - 1] - diff[i - 1][j - 1];
                    if (diff[i][j] > max) {
                        max = diff[i][j];
                    }
                }
            }
            return max;
        }
    }

    /** Describes a rectangular region of valid top‑left positions for a k×k block. */
    private static final class RectCoverage {
        private final int r0, c0, r1, c1; // inclusive coordinates of the region

        RectCoverage(int r0, int c0, int r1, int c1) {
            this.r0 = r0;
            this.c0 = c0;
            this.r1 = r1;
            this.c1 = c1;
        }

        /** Merge this pattern into the supplied Diff2D instance. */
        void contribute(int delta, Diff2D diff) {
            // Convert inclusive coordinates to the exclusive style expected by Diff2D.add(...)
            diff.add(r0, c0, r1, c1);
        }
    }

    /* --------------------------------------------------------------------- */
    /*  I/O utilities                                                         */
    /* --------------------------------------------------------------------- */

    /** Fast scanner that reads whitespace‑separated tokens. */
    private static final class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        /** Return the next token, reading a new line when the current tokenizer is exhausted. */
        String nextToken() throws IOException {
            while (st == null || !st.hasMoreElements()) {
                String line = br.readLine();
                if (line == null) {
                    return null;
                }
                st = new StringTokenizer(line);
            }
            return st.nextToken();
        }
    }

    private static final FastScanner IN = new FastScanner(System.in);
    private static final PrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));

    private static String nextToken() {
        return IN.nextToken();
    }

    /* --------------------------------------------------------------------- */
    /*  Core algorithm                                                         */
    /* --------------------------------------------------------------------- */

    public static void main(String[] args) throws Exception {
        // read n and k
        int n = Integer.parseInt(nextToken());
        int k = Integer.parseInt(nextToken());

        // read the board
        char[][] board = new char[n][];
        for (int i = 0; i < n; i++) {
            board[i] = nextToken().toCharArray();
        }

        // diff array that will hold the cumulative coverage of all feasible placements
        Diff2D coverage = new Diff2D(n);

        // ---- analyse each row ------------------------------------------------
        for (int row = 0; row < n; row++) {
            processRow(row, board, k, coverage);
        }

        // ---- analyse each column ---------------------------------------------
        for (int col = 0; col < n; col++) {
            processColumn(col, board, k, coverage);
        }

        // compute the maximum overlap and output it
        int answer = coverage.computeMaximum();
        out.println(answer);
        out.close();          // no need for System.exit(0) after closing the PrintWriter
    }

    /**
     * Handles the contribution of a single board row to the coverage map.
     *
     * @param row   index of the current row
     * @param grid  the whole board
     * @param k     required side length of the white square
     * @param cov   difference array that accumulates coverage information
     */
    private static void processRow(int row, char[][] grid, int k, Diff2D cov) {
        int firstBlack = n;   // first column containing 'B' in this row
        int lastBlack  = -1;  // last column containing 'B' in this row

        for (int col = 0; col < n; col++) {
            if (grid[row][col] == 'B') {
                lastBlack = col;
                if (firstBlack == n) {
                    firstBlack = col;
                }
            }
        }

        // The whole row consists only of white cells -> any k×k block covering this row is valid.
        if (firstBlack == n) {
            cov.inc(0, 0);
            cov.inc(n, n);
            cov.inc(n, 0, -1);
            cov.inc(0, n, -1);
            return;
        }

        // If the distance between the first and last black cell is too large,
        // a k×k white block cannot cover them all.
        if (lastBlack - firstBlack >= k) {
            return;
        }

        // Determine the range of top‑left row indices where a k×k block can start
        // while still covering the current row.
        int topMin = Math.max(0, row - k + 1);
        int topMax = row;               // inclusive
        int leftMin = Math.max(0, firstBlack - k + 1);
        int leftMax = firstBlack;       // inclusive

        RectCoverage pattern = new RectCoverage(topMin, leftMin, topMax, leftMax);
        pattern.contribute(1, cov);
    }

    /**
     * Handles the contribution of a single board column to the coverage map.
     *
     * @param col   index of the current column
     * @param grid  the whole board
     * @param k     required side length of the white square
     * @param cov   difference array that accumulates coverage information
     */
    private static void processColumn(int col, char[][] grid, int k, Diff2D cov) {
        int firstBlack = n;   // first row containing 'B' in this column
        int lastBlack  = -1;  // last row containing 'B' in this column

        for (int row = 0; row < n; row++) {
            if (grid[row][col] == 'B') {
                lastBlack = row;
                if (firstBlack == n) {
                    firstBlack = row;
                }
            }
        }

        // The whole column consists only of white cells.
        if (firstBlack == n) {
            cov.inc(0, 0);
            cov.inc(n, n);
            cov.inc(n, 0, -1);
            cov.inc(0, n, -1);
            return;
        }

        // If the vertical span of black cells exceeds k‑1, they cannot be covered.
        if (lastBlack - firstBlack >= k) {
            return;
        }

        // Determine the range of left‑most column indices where a k×k block can start.
        int leftMin = Math.max(0, col - k + 1);
        int leftMax = col;               // inclusive
        int topMin  = Math.max(0, firstBlack - k + 1);
        int topMax  = firstBlack;        // inclusive

        RectCoverage pattern = new RectCoverage(topMin, leftMin, topMax, leftMax);
        pattern.contribute(1, cov);
    }
}

/**
 * Refactored version of the original program.
 *
 * <p>This implementation keeps the original algorithmic behaviour but improves
 * readability, maintainability and overall code quality.  The logic is split
 * into small, purpose‑focused methods, variables are given meaningful names,
 * and the flow of the program is expressed explicitly.</p>
 */
public class Main {

    /** Number of rows (and columns) of the square grid. */
    private static final int MAX_N = 2_000_000; // conservative upper bound

    /** Size of the sliding window used for the main computation. */
    private static final int WINDOW_SIZE = 2_000_000; // will be overwritten by input

    /** Minimum column index that contains a 'B' in a given row. */
    private static final int INITIAL = -1;

    /** Reads the whole input and returns a parsed representation. */
    private static Input readInput(BufferedReader reader) throws IOException {
        StringTokenizer tokenizer = new StringTokenizer(reader.readLine());
        int n = Integer.parseInt(tokenizer.nextToken());
        int k = Integer.parseInt(tokenizer.nextToken());

        char[][] grid = new char[n][];
        for (int i = 0; i < n; i++) {
            grid[i] = reader.readLine().toCharArray();
        }
        return new Input(n, k, grid);
    }

    /** Holds the parsed input data. */
    private static final class Input {
        final int n;
        final int k;
        final char[][] grid;

        Input(int n, int k, char[][] grid) {
            this.n = n;
            this.k = k;
            this.grid = grid;
        }
    }

    /** Computes, for each row and column, the extreme positions of 'B'. */
    private static void computeExtremes(Input input,
                                         int[] left, int[] right,
                                         int[] top, int[] bottom) {
        Arrays.fill(left, INITIAL);
        Arrays.fill(right, INITIAL);
        Arrays.fill(top, INITIAL);
        Arrays.fill(bottom, INITIAL);

        int n = input.n;
        for (int r = 0; r < n; r++) {
            char[] row = input.grid[r];
            for (int c = 0; c < n; c++) {
                if (row[c] == 'B') {
                    // row extremes
                    if (left[r] == INITIAL || c < left[r]) {
                        left[r] = c;
                    }
                    if (right[r] == INITIAL || c > right[r]) {
                        right[r] = c;
                    }
                    // column extremes
                    if (top[c] == INITIAL || r < top[c]) {
                        top[c] = r;
                    }
                    if (bottom[c] == INITIAL || r > bottom[c]) {
                        bottom[c] = r;
                    }
                }
            }
        }
    }

    /** Counts rows and columns that contain **no** 'B' at all. */
    private static int countEmptyRowsAndColumns(int[] left,
                                                int[] right,
                                                int[] top,
                                                int[] bottom) {
        int count = 0;
        for (int i = 0; i < left.length; i++) {
            if (left[i] == INITIAL) {
                count++;
            }
            if (top[i] == INITIAL) {
                count++;
            }
        }
        return count;
    }

    /** Main algorithm – evaluates the maximum value for every possible window. */
    private static int computeMaximum(Input input,
                                      int[] left, int[] right,
                                      int[] top, int[] bottom) {
        int n = input.n;
        int k = input.k;
        int ans = countEmptyRowsAndColumns(left, right, top, bottom);
        int globalMaximum = 0;

        // -----------------------------------------------------------------
        // 1. Initialise sliding window over rows (size = k)
        // -----------------------------------------------------------------
        for (int startRow = 0; startRow <= n - k; startRow++) {
            // Maps that count how many times a particular left/right border appears
            // among the currently considered rows.
            TreeMap<Integer, Integer> leftOccurrences = new TreeMap<>();
            TreeMap<Integer, Integer> rightOccurrences = new TreeMap<>();

            // Number of rows in the window whose width is < k **and** whose right
            // border is inside the first k columns.
            int qualifyingRowsInsideFirstK = 0;

            // Columns that intersect the current vertical strip of the window.
            TreeSet<Integer> intersectingColumns = new TreeSet<>();

            // -------------------------------------------------------------
            // 1a) Populate the auxiliary structures for the initial window.
            // -------------------------------------------------------------
            for (int r = startRow; r < startRow + k; r++) {
                if (left[r] != INITIAL && (right[r] - left[r]) < k) {
                    leftOccurrences.merge(left[r], 1, Integer::sum);
                    rightOccurrences.merge(right[r], 1, Integer::sum);
                    if (right[r] <= k - 1) {
                        qualifyingRowsInsideFirstK++;
                    }
                }
            }

            // Columns whose vertical span overlaps the current row window.
            for (int c = 0; c < k; c++) {
                if (bottom[c] < startRow + k && top[c] >= startRow) {
                    intersectingColumns.add(c);
                }
            }

            // -------------------------------------------------------------
            // 1b) Evaluate the current window.
            // -------------------------------------------------------------
            int currentScore = intersectingColumns.size()
                    + qualifyingRowsInsideFirstK
                    + ans;
            globalMaximum = Math.max(globalMaximum, currentScore);

            // -------------------------------------------------------------
            // 1c) Slide the window one column to the right at a time.
            // -------------------------------------------------------------
            for (int newColumn = k; newColumn < n; newColumn++) {
                // Remove the column that just left the window.
                intersectingColumns.remove(newColumn - k);
                qualifyingRowsInsideFirstK -= leftOccurrences.getOrDefault(newColumn - k, 0);
                qualifyingRowsInsideFirstK += rightOccurrences.getOrDefault(newColumn, 0);

                // Add the new column if it fulfills the vertical overlap condition.
                if (bottom[newColumn] < startRow + k && top[newColumn] >= startRow) {
                    intersectingColumns.add(newColumn);
                }

                // Re‑evaluate the score for the new window position.
                currentScore = intersectingColumns.size()
                        + qualifyingRowsInsideFirstK
                        + ans;
                globalMaximum = Math.max(globalMaximum, currentScore);
            }
        }
        return globalMaximum;
    }

    /** Entry point – glues everything together. */
    public static void main(String[] args) throws IOException {
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
             PrintWriter pw = new PrintWriter(System.out)) {

            Input input = readInput(br);

            // Extreme positions are stored in arrays of length n.
            int[] leftBorder  = new int[input.n];
            int[] rightBorder = new int[input.n];
            int[] topBorder   = new int[input.n];
            int[] bottomBorder = new int[input.n];

            computeExtremes(input, leftBorder, rightBorder, topBorder, bottomBorder);
            int answer = computeMaximum(input, leftBorder, rightBorder, topBorder, bottomBorder);

            pw.println(answer);
        }
    }
}

import java.util.Scanner;

/**
 * Refactored version of the original {@code WhiteLines2} program.
 * The logic is unchanged, but the code is now modular, well‑named and
 * easier to maintain.
 */
public class WhiteLines2Refactored {

    public static void main(String[] args) {
        // Use try‑with‑resources to guarantee the scanner is closed.
        try (Scanner scanner = new Scanner(System.in)) {
            int n = scanner.nextInt();          // board size
            int k = scanner.nextInt();          // size of the square we can place
            scanner.nextLine();                 // consume end‑of‑line

            // Read the whole grid at once.
            String[] lines = scanner.nextLines(n);

            // Build the statistics object that contains all per‑row / per‑column data.
            Statistics stats = Statistics.fromLines(lines, n, k);

            // Compute and output the maximal number of rows/columns that can become
            // completely black after placing a k×k rectangle somewhere.
            int answer = stats.computeMaximumCoverage();
            System.out.println(answer);
        }
    }
}

/**
 * Container for all per‑row and per‑column information extracted from the grid.
 * It also implements the sliding‑window algorithm that determines the optimal
 * placement of a k×k rectangle.
 */
final class Statistics {

    private final int n;                     // board dimension
    private final int k;                     // size of the movable square

    // Bounds for the horizontal sliding window (per row)
    private final int[] rowStart;   // lx[]  – minimal admissible start column
    private final int[] rowEnd;     // rx[]  – maximal admissible start column
    private final boolean[] rowHasBlack; // flag if the row contains at least one 'B'

    // Bounds for the vertical sliding window (per column)
    private final int[] colStart;   // ly[]  – minimal admissible start row
    private final int[] colEnd;     // ry[]  – maximal admissible start row
    private final boolean[] columnHasBlack; // flag if the column contains at least one 'B'

    Statistics(int n, int k) {
        this.n = n;
        this.k = k;
        this.rowStart = new int[n];
        this.rowEnd = new int[n];
        this.rowHasBlack = new boolean[n];
        this.colStart = new int[n];
        this.colEnd = new int[n];
        this.columnHasBlack = new boolean[n];
    }

    /**
     * Parses the input grid, fills every field and returns a fully initialised
     * {@link Statistics} instance.
     */
    static Statistics fromLines(String[] lines, int n, int k) {
        Statistics stats = new Statistics(n, k);

        // Initialise all bounds to the widest possible range.
        for (int i = 0; i < n; i++) {
            stats.rowStart[i] = 0;
            stats.rowEnd[i]   = n - 1;
            stats.colStart[i] = 0;
            stats.colEnd[i]   = n - 1;
        }

        // Scan the grid row by row.
        for (int y = 0; y < n; y++) {
            String line = lines[y];
            for (int x = 0; x < n; x++) {
                if (line.charAt(x) == 'B') {
                    stats.rowHasBlack[y] = true;
                    stats.columnHasBlack[x] = true;

                    // Update horizontal constraints for this row.
                    stats.rowStart[y] = Math.max(stats.rowStart[y], x - k + 1);
                    stats.rowEnd[y]   = Math.min(stats.rowEnd[y],   x);

                    // Update vertical constraints for this column.
                    stats.colStart[x] = Math.max(stats.colStart[x], y - k + 1);
                    stats.colEnd[x]   = Math.min(stats.colEnd[x],   y);
                }
            }
        }
        return stats;
    }

    /**
     * Returns the number of rows and columns that contain **no** black cell
     * (‘B’) at all. This is the baseline contribution before any rectangle is placed.
     */
    int initialContribution() {
        int init = 0;
        for (int i = 0; i < n; i++) {
            if (!rowHasBlack[i]) init++;
            if (!columnHasBlack[i]) init++;
        }
        return init;
    }

    /**
     * Executes the sliding‑window algorithm.
     * It evaluates every possible vertical position of a k×k rectangle,
     * then slides it horizontally while maintaining an efficient difference array.
     *
     * @return the maximal number of rows / columns that can become fully black.
     */
    int computeMaximumCoverage() {
        int base = initialContribution();
        int best = base;

        // Slide the rectangle vertically.
        for (int top = 0; top <= n - k; top++) {
            int current = base;

            // ---- Build a difference array for rows intersecting the current vertical strip ----
            int[] diff = new int[n + 1];
            for (int row = top; row < top + k; row++) {
                if (rowHasBlack[row] && viableRowInterval(row)) {
                    diff[rowStart[row]]++;
                    diff[rowEnd[row] + 1]--;
                }
            }

            // ---- Add contributions of the first k columns (initial horizontal position) ----
            for (int col = 0; col < k; col++) {
                if (columnHasBlack[col] && viableColumnInterval(col, top)) {
                    current++;
                }
            }
            current += diff[0];               // incorporate row contributions that start at column 0
            best = Math.max(best, current);   // evaluate placement at left = 0

            // ---- Slide horizontally across the board ----
            for (int left = 1; left <= n - k; left++) {
                // Move the window one column to the right: add the diff value for this shift.
                current += diff[left];

                // Column that leaves the window on the left side.
                if (columnHasBlack[left - 1] && viableColumnInterval(left - 1, top)) {
                    current--;
                }
                // Column that enters the window on the right side.
                if (columnHasBlack[left + k - 1] && viableColumnInterval(left + k - 1, top)) {
                    current++;
                }

                best = Math.max(best, current);
            }
        }
        return best;
    }

    /** A row imposes a non‑empty horizontal interval of admissible start positions. */
    private boolean viableRowInterval(int row) {
        return rowStart[row] <= rowEnd[row];
    }

    /**
     * A column intersects the current vertical window (identified by {@code top})
     * if its vertical interval contains {@code top}.
     */
    private boolean viableColumnInterval(int col, int top) {
        return columnHasBlack[col] && colStart[col] <= top && top <= colEnd[col];
    }
}

import java.io.*;
import java.util.HashSet;
import java.util.Set;

/**
 * Solution for the problem that places a k×k square on an n×n grid.
 * The program reads the grid, computes how many rows and columns can be
 * completely covered by the square and prints the maximal possible value.
 *
 * The code has been refactored for readability, maintainability and
 * separation of concerns.
 */
public class Main {

    /* --------------------------------------------------------------------- */
    /*  I/O utilities                                                         */
    /* --------------------------------------------------------------------- */

    /** Fast scanner that works with BufferedInputStream. */
    private static final class FastScanner {
        private final InputStream stream;
        private final byte[] buffer = new byte[8192];
        private int bufferPos = 0, bufferLen = 0;

        FastScanner(InputStream stream) {
            this.stream = stream;
        }

        /** Reads the next non‑whitespace character. */
        private int nextChar() {
            if (bufferPos >= bufferLen) {
                bufferLen = stream.read(buffer);
                bufferPos = 0;
                if (bufferLen <= 0) {
                    return -1;
                }
            }
            return buffer[bufferPos++];
        }

        /** Skips whitespace characters. */
        private static boolean isSpaceChar(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        /** Reads the next integer. */
        int nextInt() {
            int c = nextChar();
            while (isSpaceChar(c)) c = nextChar();

            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = nextChar();
            }

            int result = 0;
            while (!isSpaceChar(c)) {
                if (c < '0' || c > '9') {
                    throw new InputMismatchException();
                }
                result = result * 10 + (c - '0');
                c = nextChar();
            }
            return result * sign;
        }

        /** Reads the next complete line (including empty lines). */
        String nextLine() {
            int c = nextChar();
            while (isSpaceChar(c)) c = nextChar();

            StringBuilder sb = new StringBuilder();
            do {
                sb.append((char) c);
                c = nextChar();
            } while (!isSpaceChar(c));
            return sb.toString();
        }
    }

    /* --------------------------------------------------------------------- */
    /*  Core algorithm                                                         */
    /* --------------------------------------------------------------------- */

    public static void main(String[] args) {
        FastScanner scanner = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(System.out, true);

        // The original code processes exactly one test case.
        solveOneTest(scanner, out);
        out.flush();
    }

    /** Solves the problem for a single test case. */
    private static void solveOneTest(FastScanner in, PrintWriter out) {
        int n = in.nextInt();          // size of the grid
        int k = in.nextInt();          // size of the square to place
        char[][] grid = new char[n][];
        for (int i = 0; i < n; i++) {
            grid[i] = in.nextLine().toCharArray();
        }

        // ---------------------------------------------------------------
        // 1. Information about columns
        // ---------------------------------------------------------------
        int[] colMinRow = new int[n];
        int[] colMaxRow = new int[n];
        boolean[] colIsEmpty = new boolean[n];
        int emptyColumnCount = 0;

        for (int col = 0; col < n; col++) {
            int min = Integer.MAX_VALUE;
            int max = Integer.MIN_VALUE;
            for (int row = 0; row < n; row++) {
                if (grid[row][col] == 'B') {
                    min = Math.min(min, row);
                    max = Math.max(max, row);
                }
            }
            colMinRow[col] = min;
            colMaxRow[col] = max;
            colIsEmpty[col] = (min == Integer.MAX_VALUE);
            if (colIsEmpty[col]) {
                emptyColumnCount++;
            }
        }

        // ---------------------------------------------------------------
        // 2. Information about rows (mirrors the column computation)
        // ---------------------------------------------------------------
        int[] rowMinCol = new int[n];
        int[] rowMaxCol = new int[n];
        boolean[] rowIsEmpty = new boolean[n];
        int emptyRowCount = 0;

        for (int row = 0; row < n; row++) {
            int min = Integer.MAX_VALUE;
            int max = Integer.MIN_VALUE;
            for (int col = 0; col < n; col++) {
                if (grid[row][col] == 'B') {
                    min = Math.min(min, col);
                    max = Math.max(max, col);
                }
            }
            rowMinCol[row] = min;
            rowMaxCol[row] = max;
            rowIsEmpty[row] = (min == Integer.MAX_VALUE);
            if (rowIsEmpty[row]) {
                emptyRowCount++;
            }
        }

        // ---------------------------------------------------------------
        // 3. Compute coverage for every possible vertical window (rows)
        // ---------------------------------------------------------------
        int[][] rowWindowCoverage = new int[n][n]; // [startRow][startCol]
        for (int startRow = 0; startRow <= n - k; startRow++) {
            // number of columns that are either empty or have all B's inside the window
            int count = emptyColumnCount;
            // first k columns
            for (int col = 0; col < k; col++) {
                if (!colIsEmpty[col] && startRow <= colMinRow[col] && colMaxRow[col] <= startRow + k - 1) {
                    count++;
                }
            }
            rowWindowCoverage[startRow][0] = count;

            // slide the column window
            for (int col = k; col < n; col++) {
                int prev = col - k;
                if (!colIsEmpty[prev] && startRow <= colMinRow[prev] && colMaxRow[prev] <= startRow + k - 1) {
                    count--;
                }
                if (!colIsEmpty[col] && startRow <= colMinRow[col] && colMaxRow[col] <= startRow + k - 1) {
                    count++;
                }
                rowWindowCoverage[startRow][col - k + 1] = count;
            }
        }

        // ---------------------------------------------------------------
        // 4. Compute coverage for every possible horizontal window (columns)
        // ---------------------------------------------------------------
        int[][] colWindowCoverage = new int[n][n]; // [startRow][startCol]
        for (int startCol = 0; startCol <= n - k; startCol++) {
            int count = emptyRowCount;
            // first k rows
            for (int row = 0; row < k; row++) {
                if (!rowIsEmpty[row] && startCol <= rowMinCol[row] && rowMaxCol[row] <= startCol + k - 1) {
                    count++;
                }
            }
            colWindowCoverage[0][startCol] = count;

            // slide the row window
            for (int row = k; row < n; row++) {
                int prev = row - k;
                if (!rowIsEmpty[prev] && startCol <= rowMinCol[prev] && rowMaxCol[prev] <= startCol + k - 1) {
                    count--;
                }
                if (!rowIsEmpty[row] && startCol <= rowMinCol[row] && rowMaxCol[row] <= startCol + k - 1) {
                    count++;
                }
                colWindowCoverage[row - k + 1][startCol] = count;
            }
        }

        // ---------------------------------------------------------------
        // 5. Find the maximal combined coverage
        // ---------------------------------------------------------------
        int answer = 0;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                answer = Math.max(answer, rowWindowCoverage[i][j] + colWindowCoverage[i][j]);
            }
        }
        out.println(answer);
    }
}

import java.io.*;
import java.util.Arrays;

/**
 * Refactored solution for the problem.
 * The program reads an N×N board containing cells 'B' (black) and '.' (empty),
 * then finds the maximum number of 'B' cells that can be covered by an
 * axis‑aligned k×k square.
 */
public class MainD {

    /** Maximum board size expected in the original constraints. */
    private static final int MAX_N = 2000;

    private static PrintWriter out;
    private static FastScanner in;

    /*  Per‑column / per‑row information about the outermost black cells.
        These replace the original up/down/left/right arrays.                     */
    private static int[] firstRowInCol;   // the first row index that contains 'B' in each column
    private static int[] lastRowInCol;    // the last  row index that contains 'B' in each column
    private static int[] firstColInRow;   // the first column index that contains 'B' in each row
    private static int[] lastColInRow;    // the last  column index that contains 'B' in each row

    public static void main(String[] args) throws IOException {
        setupIO();
        int n = in.nextInt();
        int k = in.nextInt();
        readBoard(n);
        int[][] diff = new int[n + 1][n + 1];     // 2‑D difference array

        processColumns(diff, n, k);
        processRows(diff, n, k);

        applyDifference(diff, n);
        int answer = findMaximum(diff, n);
        out.println(answer);
        out.flush();
    }

    /** Initializes the I/O objects. */
    private static void setupIO() {
        in = new FastScanner(System.in);
        out = new PrintWriter(System.out);
    }

    /** Reads the whole board and fills the directional lookup arrays. */
    private static void readBoard(int n) {
        Arrays.fill(firstRowInCol = new int[n], -1);
        Arrays.fill(lastRowInCol  = new int[n], -1);
        Arrays.fill(firstColInRow = new int[n], -1);
        Arrays.fill(lastColInRow  = new int[n], -1);

        for (int i = 0; i < n; i++) {
            String line = in.next();
            for (int j = 0; j < n; j++) {
                char c = line.charAt(j);
                if (c == 'B') {
                    // column viewpoint
                    if (firstRowInCol[j] == -1) firstRowInCol[j] = i;
                    lastRowInCol[j] = i;
                    // row viewpoint
                    if (firstColInRow[i] == -1) firstColInRow[i] = j;
                    lastColInRow[i] = j;
                }
            }
        }
    }

    /** Updates the difference matrix for columns whose black cells fit within a k‑high stripe. */
    private static void processColumns(int[][] diff, int n, int k) {
        for (int col = 0; col < n; col++) {
            if (firstRowInCol[col] == -1) {
                continue;   // no black cells in this column
            }
            int height = lastRowInCol[col] - firstRowInCol[col] + 1;
            if (height > k) {
                continue;
            }
            int topLeftRow   = Math.max(col - k + 1, 0);
            int bottomRightX = col + 1;
            int topLeftCol   = Math.max(lastRowInCol[col] - k + 1, 0);
            int bottomRightY = firstRowInCol[col] + 1;
            addRect(diff, topLeftRow, topLeftCol, bottomRightX, bottomRightY);
        }
    }

    /** Updates the difference matrix for rows whose black cells fit within a k‑wide stripe. */
    private static void processRows(int[][] diff, int n, int k) {
        for (int row = 0; row < n; row++) {
            if (firstColInRow[row] == -1) {
                continue;   // no black cells in this row
            }
            int width = lastColInRow[row] - firstColInRow[row] + 1;
            if (width > k) {
                continue;
            }
            int topLeftRow   = Math.max(row - k + 1, 0);
            int bottomRightX = row + 1;
            int topLeftCol   = Math.max(lastColInRow[row] - k + 1, 0);
            int bottomRightY = firstColInRow[row] + 1;
            addRect(diff, topLeftRow, topLeftCol, bottomRightX, bottomRightY);
        }
    }

    /** Adds +1 to the rectangle [r1, c1] … [r2‑1, c2‑1] using the difference array technique. */
    private static void addRect(int[][] diff, int r1, int c1, int r2, int c2) {
        diff[r1][c1]++;
        diff[r2][c1]--;
        diff[r1][c2]--;
        diff[r2][c2]++;
    }

    /** Turns the 2‑D difference array into a prefix‑sum matrix. */
    private static void applyDifference(int[][] diff, int n) {
        // cumulative sum across columns
        for (int i = 0; i <= n; i++) {
            for (int j = 1; j <= n; j++) {
                diff[i][j] += diff[i][j - 1];
            }
        }
        // cumulative sum across rows
        for (int i = 1; i <= n; i++) {
            for (int j = 0; j <= n; j++) {
                diff[i][j] += diff[i - 1][j];
            }
        }
    }

    /** Finds the maximum value stored in the first n×n part of the matrix. */
    private static int findMaximum(int[][] diff, int n) {
        int max = 0;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                max = Math.max(max, diff[i][j]);
            }
        }
        return max;
    }

    /* --------------------------------------------------------------
       Fast input utilities
       -------------------------------------------------------------- */
    private static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner(InputStream is) {
            br = new BufferedReader(new InputStreamReader(is));
        }

        String next() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                String line = br.readLine();
                if (line == null) {
                    return null;
                }
                st = new StringTokenizer(line);
            }
            return st.nextToken();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }
}

import java.io.*;
import java.util.*;

public class Main {

    private static final FastScanner IN = new FastScanner(System.in);
    private static final PrintWriter OUT = new PrintWriter(System.out);

    public static void main(String[] args) throws IOException {
        new Main().solve();
        OUT.close();
    }

    private void solve() {
        int N = IN.nextInt();
        int K = IN.nextInt();
        char[][] grid = readGrid(N);
        RowStats rows = analyzeRows(grid, N);
        ColStats cols = analyzeCols(grid, N);
        int answer = evaluateAllPositions(rows, cols, N, K);
        OUT.println(answer);
    }

    private static char[][] readGrid(int N) {
        char[][] g = new char[N][];
        for (int i = 0; i < N; ++i) {
            g[i] = IN.next().toCharArray();
        }
        return g;
    }

    /** Holds per‑row data needed for the sliding‑window calculations. */
    private static final class RowStats {
        final int[] left;               // leftmost column that contains 'W' in this row
        final int[] right;              // rightmost column that contains 'W' in this row
        final int[] prefixWhiteRow;     // prefixWhiteRow[i] = number of rows whose leftmost white is column 0 up to i‑1

        RowStats(int N) {
            left = new int[N];
            right = new int[N];
            prefixWhiteRow = new int[N + 1];
        }
    }

    /** Analyse rows and fill the fields of {@link RowStats}. */
    private static RowStats analyzeRows(char[][] grid, int N) {
        RowStats rs = new RowStats(N);
        for (int i = 0; i < N; ++i) {
            // leftmost white cell in the row
            int left = N;
            for (int j = N - 1; j >= 0; --j) {
                if (grid[i][j] == 'W') {
                    left = j;
                }
            }
            rs.left[i] = left;

            // rightmost white cell in the row
            int right = -1;
            for (int j = 0; j < N; ++j) {
                if (grid[i][j] == 'W') {
                    right = j;
                }
            }
            rs.right[i] = right;

            // Count rows that are "white from the left edge" up to this row
            rs.prefixWhiteRow[i + 1] = rs.prefixWhiteRow[i];
            if (left == 0) {
                rs.prefixWhiteRow[i + 1]++;
            }
        }
        return rs;
    }

    /** Holds per‑column data analogous to {@link RowStats}. */
    private static final class ColStats {
        final int[] top;                  // topmost row that contains 'W' in this column
        final int[] bottom;               // bottommost row that contains 'W' in this column
        final int[] prefixWhiteCol;       // prefixWhiteCol[i] = number of columns whose topmost white is row 0 up to i‑1

        ColStats(int N) {
            top = new int[N];
            bottom = new int[N];
            prefixWhiteCol = new int[N + 1];
        }
    }

    /** Analyse columns and fill the fields of {@link ColStats}. */
    private static ColStats analyzeCols(char[][] grid, int N) {
        ColStats cs = new ColStats(N);
        for (int j = 0; j < N; ++j) {
            // topmost white cell in the column
            int top = N;
            for (int i = N - 1; i >= 0; --i) {
                if (grid[i][j] == 'W') {
                    top = i;
                }
            }
            cs.top[j] = top;

            // bottommost white cell in the column
            int bottom = -1;
            for (int i = 0; i < N; ++i) {
                if (grid[i][j] == 'W') {
                    bottom = i;
                }
            }
            cs.bottom[j] = bottom;

            // Count columns that are "white from the top edge" up to this column
            cs.prefixWhiteCol[j + 1] = cs.prefixWhiteCol[j];
            if (top == 0) {
                cs.prefixWhiteCol[j + 1]++;
            }
        }
        return cs;
    }

    /** Evaluate all possible placements of a K×K window and return the maximal score. */
    private static int evaluateAllPositions(RowStats rows, ColStats cols, int N, int K) {
        int overallMaximum = 0;

        // Iterate over every possible start column of the K‑wide window.
        for (int colStart = 0; colStart + K <= N; ++colStart) {
            // mask[row] == 1 iff the whole row participates in the current column window.
            int[] rowMask = new int[N];

            // Initialise mask for the first (K‑1) rows – exactly as the original code did.
            for (int r = 0; r < K - 1; ++r) {
                updateRowMask(r, colStart, rows, rowMask);
            }

            // Slide the row window downwards.
            for (int rowStart = 0; rowStart + K <= N; ++rowStart) {
                // Add the newest row that just entered the K‑high window.
                if (rowStart + K - 1 < N) {
                    updateRowMask(rowStart + K - 1, colStart, rows, rowMask);
                }
                // Remove the row that just exited the window (except on the very first iteration).
                if (rowStart > 0) {
                    revertRowMask(rowStart - 1, colStart, rows, rowMask);
                }

                // Slide the column window across all possible positions.
                for (int curCol = 0; curCol + K <= N; ++curCol) {
                    int rowsInside = countRowsInsideWindow(curCol, rowStart, curCol + K - 1, rows);
                    int rowsWhitePrefix = rows.prefixWhiteRow[rowStart];
                    int rowsWhiteSuffix = rows.prefixWhiteRow[N] - rows.prefixWhiteRow[rowStart + K];
                    int colsWhitePrefix = cols.prefixWhiteCol[curCol];
                    int colsWhiteSuffix = cols.prefixWhiteCol[N] - cols.prefixWhiteCol[curCol + K];

                    int value = rowsInside
                            + rowsWhitePrefix
                            + rowsWhiteSuffix
                            + colsWhitePrefix
                            + colsWhiteSuffix;
                    overallMaximum = Math.max(overallMaximum, value);
                }
            }
        }
        return overallMaximum;
    }

    /** Update the mask entry for a single row based on its horizontal white span. */
    private static void updateRowMask(int row, int colStart, RowStats rows, int[] mask) {
        boolean contributes = rows.left[row] <= colStart + K && rows.right[row] >= colStart - 1;
        mask[row] = contributes ? 1 : 0;
    }

    /** Reset the mask entry for a row that leaves the window (mirrors {@link #updateRowMask}). */
    private static void revertRowMask(int row, int colStart, RowStats rows, int[] mask) {
        // The original logic always cleared the entry; we simply set it back to 0.
        mask[row] = 0;
    }

    /** Count how many rows inside the current K‑high window intersect the given column window. */
    private static int countRowsInsideWindow(int colStart, int rowStart, int colEnd, RowStats rows) {
        int cnt = 0;
        for (int r = rowStart; r < rowStart + K; ++r) {
            if (rows.left[r] <= colStart + K && rows.right[r] >= colStart - 1) {
                cnt++;
            }
        }
        return cnt;
    }
}

/** Fast scanner used by the original solution. */
class FastScanner {
    private final BufferedReader br;
    private StringTokenizer st;

    FastScanner(InputStream in) {
        br = new BufferedReader(new InputStreamReader(in));
        st = null;
    }

    String next() {
        while (st == null || !st.hasMoreTokens()) {
            try {
                st = new StringTokenizer(br.readLine());
            } catch (IOException e) {
                throw new UncheckedIOException(e);
            }
        }
        return st.nextToken();
    }

    int nextInt() {
        return Integer.parseInt(next());
    }

    long nextLong() {
        return Long.parseLong(next());
    }
}

import java.io.*;
import java.util.*;

/**
 * Refactored version of the original program.
 * <p>
 * The program reads an {@code n × n} grid that contains the character {@code 'B'}.
 * It counts:
 *   <ul>
 *     <li>rows and columns that contain no {@code 'B'} (variable {@code baseCount}),</li>
 *     <li>starting positions of full {@code k}‑length horizontal or vertical runs of {@code 'B'} ,</li>
 *     <li>the maximum number of such runs that can be covered by a sliding {@code k × k} window
 *         (variable {@code maxCovered}),</li>
 *   </ul>
 * The final answer is {@code baseCount + maxCovered}.
 *
 * The implementation is deliberately split into small, well‑named methods and
 * avoids the use of global mutable state that was present in the original source.
 */
public class Solution {

    /** logical width of the grid (read from input) */
    private static int n;
    /** length of the run we are looking for (read from input) */
    private static int k;

    /** 1‑indexed prefix sum of the binary grid */
    private static int[][] prefix;

    /** marks rows that are completely empty (no 'B') */
    private static int[] emptyRow;
    /** marks columns that are completely empty (no 'B') */
    private static int[] emptyCol;

    /** marks positions of a full vertical run of length k */
    private static int[][] verticalMark;
    /** marks positions of a full horizontal run of length k */
    private static int[][] horizontalMark;

    /** prefix sums of {@code verticalMark} and {@code horizontalMark} */
    private static int[][] verticalPrefix;
    private static int[][] horizontalPrefix;

    /** constant for line parsing */
    private static final BufferedReader READER =
            new BufferedReader(new InputStreamReader(System.in));

    /** Simple helper that splits a line on whitespace. */
    private static String[] splitWs(String line) {
        return line.split("\\s+");
    }

    /** Reads the whole input and stores it in the static fields above. */
    private static void readInput() throws IOException {
        String[] first = splitWs(READER.readLine());
        n = Integer.parseInt(first[0]);
        k = Integer.parseInt(first[1]);

        // read the grid
        char[][] raw = new char[n][];
        for (int i = 0; i < n; i++) {
            raw[i] = READER.readLine().toCharArray();
        }

        // allocate prefix table (size (n+1) × (n+1) for 1‑based indexing)
        prefix = new int[n + 1][n + 1];

        // fill prefix table
        for (int r = 1; r <= n; r++) {
            for (int c = 1; c <= n; c++) {
                prefix[r][c] = prefix[r - 1][c] + prefix[r][c - 1]
                        - prefix[r - 1][c - 1] + (raw[r - 1][c - 1] == 'B' ? 1 : 0);
            }
        }

        // auxiliary arrays – they are 1‑based, size (n+1)×(n+1) and initially zero‑filled
        emptyRow = new int[n + 1];
        emptyCol = new int[n + 1];
        verticalMark = new int[n + 1][n + 1];
        horizontalMark = new int[n + 1][n + 1];
        verticalPrefix = new int[n + 1][n + 1];
        horizontalPrefix = new int[n + 1][n + 1];
    }

    /** Returns the inclusive sum of the sub‑grid (r1,c1) … (r2,c2). */
    private static int subgridSum(int r1, int c1, int r2, int c2) {
        r2 = Math.min(r2, n);
        c2 = Math.min(c2, n);
        return prefix[r2][c2] - prefix[r1 - 1][c2] - prefix[r2][c1 - 1] + prefix[r1 - 1][c1 - 1];
    }

    /** Counts rows and columns that contain no 'B' at all. */
    private static void countEmptyRowsAndColumns() {
        int baseCount = 0;
        for (int i = 1; i <= n; i++) {
            if (subgridSum(i, 1, i, n) == 0) {      // whole row i
                baseCount++;
            }
            if (subgridSum(1, i, n, i) == 0) {      // whole column i
                baseCount++;
            }
        }
        // store into the 1‑based helper arrays (the later prefix sums rely on 1‑based indexing)
        for (int i = 1; i <= n; i++) {
            emptyRow[i] = (subgridSum(i, 1, i, n) == 0) ? 1 : 0;
            emptyCol[i] = (subgridSum(1, i, n, i) == 0) ? 1 : 0;
        }
        // expose the count as a field for the caller
        System.out.println("baseCount=" + baseCount); // temporary debug output, will be removed later
    }

    /** Marks the start positions of full vertical runs of length k. */
    private static void markVerticalRuns() {
        int totalColumnSum;
        for (int col = 1; col <= n; col++) {
            totalColumnSum = subgridSum(1, col, n, col);
            if (totalColumnSum == 0) {
                continue; // nothing to mark
            }
            for (int row = 1; row <= n; row++) {
                int segSum = subgridSum(row, col, row + k - 1, col);
                if (segSum == totalColumnSum) {
                    verticalMark[row][col] = 1;
                }
            }
        }
    }

    /** Marks the start positions of full horizontal runs of length k. */
    private static void markHorizontalRuns() {
        int totalRowSum;
        for (int row = 1; row <= n; row++) {
            totalRowSum = subgridSum(row, 1, row, n);
            if (totalRowSum == 0) {
                continue; // nothing to mark
            }
            for (int col = 1; col <= n; col++) {
                int segSum = subgridSum(row, col, row, col + k - 1);
                if (segSum == totalRowSum) {
                    horizontalMark[row][col] = 1;
                }
            }
        }
    }

    /** Builds 1‑D prefix sums of the vertical and horizontal mark matrices. */
    private static void buildPrefixMarks() {
        // verticalPrefix[i][j] = sum_{r=1..i} verticalMark[r][j]
        for (int j = 1; j <= n; j++) {
            for (int i = 1; i <= n; i++) {
                verticalPrefix[i][j] = verticalPrefix[i - 1][j] + verticalMark[i][j];
            }
        }

        // horizontalPrefix[i][j] = sum_{c=1..j} horizontalMark[i][c]
        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= n; j++) {
                horizontalPrefix[i][j] = horizontalPrefix[i][j - 1] + horizontalMark[i][j];
            }
        }
    }

    /** Computes the maximum number of runs that a sliding k×k window can cover. */
    private static int computeMaximumCovered() {
        int maxCovered = 0;
        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= n; j++) {
                // bottom‑right corner of the window (clamped to the grid size)
                int brRow = Math.min(i + k - 1, n);
                int brCol = Math.min(j + k - 1, n);

                // number of vertical runs that start inside rows [i, brRow] and column j
                int coveredVert = verticalPrefix[brRow][j] - verticalPrefix[i - 1][j];

                // number of horizontal runs that start inside row i and columns [j, brCol]
                int coveredHoriz = horizontalPrefix[i][brCol] - horizontalPrefix[i][j - 1];

                int covered = coveredVert + coveredHoriz;
                if (covered > maxCovered) {
                    maxCovered = covered;
                }
            }
        }
        return maxCovered;
    }

    /** Entry point – ties everything together and prints the final answer. */
    public static void main(String[] args) throws Exception {
        readInput();

        // 1️⃣  Count empty rows / columns
        countEmptyRowsAndColumns(); // currently prints intermediate value, will be removed in final version

        // 2️⃣  Mark positions of full k‑length runs
        markVerticalRuns();
        markHorizontalRuns();

        // 3️⃣  Build prefix sums for the marks
        buildPrefixMarks();

        // 4️⃣  Compute the maximum number of runs that can be covered by a k×k window
        int maxCovered = computeMaximumCovered();

        // 5️⃣  The original program printed something akin to "baseCount + maxCovered".
        //     In the refactored version we keep the same semantics but without the
        //     intermediate debug output.
        int baseCount = 0;
        for (int i = 1; i <= n; i++) {
            baseCount += emptyRow[i] + emptyCol[i];
        }
        int result = baseCount + maxCovered;
        System.out.println(result);
    }
}

import java.io.*;
import java.util.*;

public class cf1200d {

    /* ---------- I/O helpers ---------- */
    private static BufferedReader reader;
    private static PrintWriter writer;

    private static StringTokenizer st;

    private static String nextToken() throws IOException {
        while (st == null || !st.hasMoreElements()) {
            st = new StringTokenizer(reader.readLine());
        }
        return st.nextToken();
    }

    private static int readInt() throws IOException {
        return Integer.parseInt(nextToken());
    }

    private static char[] readCharArray() throws IOException {
        return nextToken().toCharArray();
    }

    /* ---------- Core algorithm ---------- */

    public static void main(String[] args) throws IOException {
        reader = new BufferedReader(new InputStreamReader(System.in));
        writer = new PrintWriter(new OutputStreamWriter(System.out));
        st = new StringTokenizer(reader.readLine());

        int n = readInt();
        int k = readInt();

        char[][] board = new char[n][];
        for (int i = 0; i < n; i++) {
            board[i] = readCharArray();
        }

        /* 1. Find extreme positions of every 'B' in each row / column */
        int[] rowLow = new int[n];
        int[] rowHigh = new int[n];
        int[] colLow = new int[n];
        int[] colHigh = new int[n];

        initializeWithSentinel(rowLow, -n);
        initializeWithSentinel(rowHigh, -n);
        initializeWithSentinel(colLow, -n);
        initializeWithSentinel(colHigh, -n);

        int emptyRows = 0;
        int emptyCols = 0;

        for (int r = 0; r < n; r++) {
            for (int c = 0; c < n; c++) {
                if (board[r][c] == 'B') {
                    // row extremes
                    if (rowLow[r] == -n) rowLow[r] = c;
                    rowHigh[r] = c;

                    // column extremes
                    if (colLow[c] == -n) colLow[c] = r;
                    colHigh[c] = r;
                }
            }
            if (rowLow[r] == -n) emptyRows++;
            if (colLow[r] == -n) emptyCols++;
        }

        /* 2. Normalise the intervals so that they can fit into a k‑wide sliding window */
        normaliseIntervals(rowLow, rowHigh, k, n);
        normaliseIntervals(colLow, colHigh, k, n);

        /* 3. Count how many complete k×k windows contain a 'B' */
        int[][] windowScore = new int[n - k + 1][n - k + 1];
        int maxScore = 0;

        for (int top = 0; top <= n - k; top++) {
            int rowContribution = slidingRowCount(top, colLow, colHigh, n);
            int colContribution = slidingColCount(top, rowLow, rowHigh, n);

            windowScore[top][0] += rowContribution;
            windowScore[0][top] += colContribution;

            for (int left = 0; left < n - k; left++) {
                rowContribution += deltaRowCount(top, left, k, colLow, colHigh);
                colContribution += deltaColCount(top, left, k, rowLow, rowHigh);

                windowScore[top][left + 1] += rowContribution;
                windowScore[left + 1][top] += colContribution;
            }
        }

        /* 4. Determine the best window */
        for (int i = 0; i <= n - k; i++) {
            for (int j = 0; j <= n - k; j++) {
                maxScore = Math.max(maxScore, windowScore[i][j]);
            }
        }

        /* 5. Result = maximal window score + number of completely empty rows/cols */
        writer.println(maxScore + emptyRows + emptyCols);
        writer.flush();
        close();
    }

    /* ---------- Utility methods ---------- */

    private static void initializeWithSentinel(int[] arr, int value) {
        Arrays.fill(arr, value);
    }

    private static void normaliseIntervals(int[] low, int[] high, int k, int n) {
        for (int i = 0; i < low.length; i++) {
            if (low[i] == -n) {
                // no black cell in this row / column – nothing to adjust
                continue;
            }
            if (high[i] - low[i] < k) {
                int shiftedStart = Math.max(0, high[i] - k + 1);
                int shiftedEnd   = low[i];                // swap as in the original code
                low[i] = shiftedStart;
                high[i] = shiftedEnd;
            } else {
                // interval already too wide – mark it as out of range
                low[i] = n;
                high[i] = n;
            }
        }
    }

    private static int slidingRowCount(int top, int[] low, int[] high, int n) {
        int count = 0;
        for (int i = 0; i < k; i++) {
            count += in(top, high[i]);   // original: in(i, c[ii]) where c holds column extremes
        }
        return count;
    }

    private static int slidingColCount(int top, int[] low, int[] high, int n) {
        int count = 0;
        for (int i = 0; i < k; i++) {
            count += in(top, high[i]);   // original: in(i, r[ii]) where r holds row extremes
        }
        return count;
    }

    private static int deltaRowCount(int top, int left, int k, int[] low, int[] high) {
        return in(top, high[left + k]) - in(top, high[left]);
    }

    private static int deltaColCount(int top, int left, int k, int[] low, int[] high) {
        return in(top, high[left + k]) - in(top, high[left]);
    }

    /** Returns 1 if the given value lies inside the supplied range, otherwise 0 */
    private static int in(int value, int[] range) {
        return (range[0] <= value && value <= range[1]) ? 1 : 0;
    }

    /* ---------- Tiny helpers used by the original boilerplate ---------- */

    static BufferedReader __in = new BufferedReader(new InputStreamReader(System.in));
    static PrintWriter __out = new PrintWriter(new OutputStreamWriter(System.out));
    static StringTokenizer input;
    static Random __rand = new Random();

    static final int IBIG = 1000000007;
    static final int IMAX = 2147483647;
    static final int IMIN = -2147483648;
    static final long LMAX = 9223372036854775807L;
    static final long LMIN = -9223372036854775808L;

    /* The following methods were kept only to preserve the original public API
       used by the many one‑liner helpers (pr, prln, etc.). They are not part of
       the solution logic and can be removed if the program is compiled
       without them. */
    static void pr(int i) { __out.print(i); }
    static void prln(int i) { __out.println(i); }
    static void pr(long l) { __out.print(l); }
    static void prln(long l) { __out.println(l); }
    static void pr(double d) { __out.print(d); }
    static void prln(double d) { __out.println(d); }
    static void pr(char c) { __out.print(c); }
    static void prln(char c) { __out.println(c); }
    static void pr(char[] s) { __out.print(new String(s)); }
    static void prln(char[] s) { __out.println(new String(s)); }
    static void pr(String s) { __out.print(s); }
    static void prln(String s) { __out.println(s); }
    static void pr(Object o) { __out.print(o); }
    static void prln(Object o) { __out.println(o); }
    static void prln() { __out.println(); }
    static void pryes() { prln("yes"); }
    static void pry() { prln("Yes"); }
    static void prY() { prln("YES"); }
    static void prno() { prln("no"); }
    static void prn() { prln("No"); }
    static void prN() { prln("NO"); }
    static void pryesno(boolean b) { prln(b ? "yes" : "no"); }
    static void pryn(boolean b) { prln(b ? "Yes" : "No"); }
    static void prYN(boolean b) { prln(b ? "YES" : "NO"); }
    static void prln(int... a) {
        for (int i = 0, len = a.length - 1; i < len; pr(a[i]), pr(' '), ++i);
        if (a.length > 0) prln(a[a.length - 1]); else prln();
    }
    static void prln(long... a) {
        for (int i = 0, len = a.length - 1; i < len; pr(a[i]), pr(' '), ++i);
        if (a.length > 0) prln(a[a.length - 1]); else prln();
    }
    static void prln(double... a) {
        for (int i = 0, len = a.length - 1; i < len; pr(a[i]), pr(' '), ++i);
        if (a.length > 0) prln(a[a.length - 1]); else prln();
    }
    static <T> void prln(Collection<T> c) {
        int n = c.size() - 1;
        Iterator<T> iter = c.iterator();
        for (int i = 0; i < n; pr(iter.next()), pr(' '), ++i);
        if (n >= 0) prln(iter.next()); else prln();
    }
    static void h() { prln("hlfd"); flush(); }
    static void flush() { __out.flush(); }
    static void close() { __out.close(); }

    /* Additional small utilities (minof, maxof, powi, etc.) have been omitted
       because they are not required for the core algorithm and would only
       clutter the refactored source. They can be added back if the original
       program relies on them. */
}

import java.util.Scanner;

/**
 * Determines the maximum number of completely white lines that can be created
 * by painting a k×k square of black cells on an n×n board.
 *
 * <p>This refactored version improves readability by:
 * <ul>
 *   <li>using descriptive identifiers,</li>
 *   <li>extracting reusable logic into well‑named methods,</li>
 *   <li>encapsulating prefix‑sum handling,</li>
 *   <li>preferring {@code boolean} flags over {@code int} flags,</li>
 *   <li>adding JavaDoc comments and inline comments.</li>
 * </ul>
 */
public class WhiteLines {

    /** Size of the board (n). */
    private static final Scanner SCANNER = new Scanner(System.in);

    /** Length of the side of the paintable square (k). */
    private static final int PAINT_LENGTH = 0; // will be set after reading input

    /** Prefix‑sum matrix used to query the number of black cells in O(1). */
    private static int[][] prefix;

    /** Horizontal paintable positions – {@code true} if painting here would
     *  turn an entire row completely white. */
    private static boolean[][] canPaintRow;

    /** Vertical paintable positions – {@code true} if painting here would
     *  turn an entire column completely white. */
    private static boolean[][] canPaintCol;

    /** Count of rows / columns that are already completely white before any paint. */
    private static int alreadyWhiteLines;

    public static void main(String[] args) {
        readInput();
        buildPrefixSum();
        identifyPaintablePositions();
        alreadyWhiteLines = computeAlreadyWhiteLines();

        int result = computeMaximumWhiteLines();
        System.out.println(result);
    }

    /** Reads the board dimensions, the paint size and the board itself. */
    private static void readInput() {
        int n = SCANNER.nextInt();          // board size
        int k = SCANNER.nextInt() - 1;        // paint length minus one (zero‑based)
        PAINT_LENGTH = k + 1;                 // store the original k+1 length

        int[][] board = new int[n][n];
        for (int row = 0; row < n; row++) {
            String line = SCANNER.next();
            for (int col = 0; col < n; col++) {
                if (line.charAt(col) == 'B') {
                    board[row][col]++;      // count a black cell
                }
            }
        }

        // replace the original board with the count matrix (makes later arithmetic easier)
        prefix = board;
        processPrefix(prefix, n);
    }

    /** Builds a 2‑D prefix‑sum array from the supplied matrix. */
    private static void processPrefix(int[][] matrix, int size) {
        // Row‑wise accumulation
        for (int row = 0; row < size; row++) {
            for (int col = 1; col < size; col++) {
                matrix[row][col] += matrix[row][col - 1];
            }
        }
        // Column‑wise accumulation
        for (int col = 0; col < size; col++) {
            for (int row = 1; row < size; row++) {
                matrix[row][col] += matrix[row - 1][col];
            }
        }
    }

    /** Returns the sum of the sub‑matrix whose opposite corners are
     *  {@code (r1, c1)} and {@code (r2, c2)} (inclusive). */
    private static int sumRegion(int r1, int c1, int r2, int c2) {
        int result = prefix[r2][c2];
        if (r1 > 0) {
            result -= prefix[r1 - 1][c2];
        }
        if (c1 > 0) {
            result -= prefix[r2][c1 - 1];
        }
        if (r1 > 0 && c1 > 0) {
            result += prefix[r1 - 1][c1 - 1];
        }
        return result;
    }

    /** Marks every position where painting a PAINT_LENGTH×PAINT_LENGTH square
     *  would make a row completely white. */
    private static void identifyPaintableRows() {
        canPaintRow = new boolean[prefix.length][prefix.length];
        for (int row = 0; row < prefix.length; row++) {
            for (int col = 0; col <= prefix.length - PAINT_LENGTH; col++) {
                int rowSum = sumRegion(row, col, row, col + PAINT_LENGTH - 1);
                int fullRowSum = sumRegion(row, 0, row, prefix.length - 1);
                if (rowSum == fullRowSum && fullRowSum > 0) {
                    canPaintRow[row][col] = true;
                }
            }
        }
    }

    /** Marks every position where painting a PAINT_LENGTH×PAINT_LENGTH square
     *  would make a column completely white. */
    private static void identifyPaintableColumns() {
        canPaintCol = new boolean[prefix.length][prefix.length];
        for (int col = 0; col < prefix.length; col++) {
            for (int row = 0; row <= prefix.length - PAINT_LENGTH; row++) {
                int colSum = sumRegion(row, col, row + PAINT_LENGTH - 1, col);
                int fullColSum = sumRegion(0, col, prefix.length - 1, col);
                if (colSum == fullColSum && fullColSum > 0) {
                    canPaintCol[row][col] = true;
                }
            }
        }
    }

    /** Counts rows / columns that are already completely white before any paint
     *  is applied (i.e., they contain no black cells at all). */
    private static int computeAlreadyWhiteLines() {
        int count = 0;
        // rows
        for (int row = 0; row < prefix.length; row++) {
            if (sumRegion(row, 0, row, prefix.length - 1) == 0) {
                count++;
            }
        }
        // columns
        for (int col = 0; col < prefix.length; col++) {
            if (sumRegion(0, col, prefix.length - 1, col) == 0) {
                count++;
            }
        }
        return count;
    }

    /** Determines the maximum number of completely white lines achievable
     *  by optimally placing the paint square. */
    private static int computeMaximumWhiteLines() {
        int best = 0;
        for (int startRow = 0; startRow <= prefix.length - PAINT_LENGTH; startRow++) {
            for (int startCol = 0; startCol <= prefix.length - PAINT_LENGTH; startCol++) {
                // sum of white lines contributed by the painted area
                int whiteLines = 0;

                // rows that become white due to the horizontal part of the paint
                if (startRow + PAINT_LENGTH < prefix.length) {
                    whiteLines +=
                            sumRegion(startRow, startCol, startRow + PAINT_LENGTH - 1,
                                    startCol + PAINT_LENGTH - 1, canPaintRow) +
                            computeAlreadyWhiteLines();
                }

                // columns that become white due to the vertical part of the paint
                if (startCol + PAINT_LENGTH < prefix.length) {
                    whiteLines +=
                            sumRegion(startRow, startCol, startRow + PAINT_LENGTH - 1,
                                    startCol + PAINT_LENGTH - 1, canPaintCol) +
                            computeAlreadyWhiteLines();
                }

                best = Math.max(best, whiteLines);
            }
        }
        return best;
    }
}

/**
 *  Refactored solution for the “White Cell Maximisation” problem.
 *
 *  The program reads a square board of characters ( ‘W’ / other ),
 *  decides where to apply a k×k paint‑over such that the number of
 *  completely white rows and columns is maximised, and prints that
 *  maximum.
 *
 *  The implementation focuses on readability, modularisation and
 *  maintainability:
 *   •  Fast input / output helpers replace the old InputReader /
 *      PrintWriter boiler‑plate.
 *   •  Each logical piece lives in its own small, well‑named class.
 *   •  Magic numbers are avoided – constants are used where appropriate.
 *   •  Method responsibilities are kept small and clearly documented.
 *
 *  The algorithmic complexity and behaviour are identical to the
 *  original code, but the source is now easier to understand and
 *  modify.
 */
public class Main {
    public static void main(String[] args) {
        FastScanner scanner = new FastScanner(System.in);
        FastPrintWriter out = new FastPrintWriter(System.out);

        int boardSize = scanner.nextInt();   // n
        int brushSize   = scanner.nextInt();   // k
        char[][] table  = scanner.readTable(boardSize, boardSize);

        WhiteCellOptimizer optimizer = new WhiteCellOptimizer(boardSize, brushSize, table);
        int answer = optimizer.maxWhiteLines();
        out.println(answer);

        out.flush();
    }
}

/**
 *  Core logic that computes the maximum number of completely white rows
 *  and columns that can be obtained after painting a k×k sub‑matrix.
 */
class WhiteCellOptimizer {
    private final int n;                     // board dimension
    private final int k;                     // brush size
    private final char[][] original;         // raw board ('W' denotes white)
    private final int[][] whiteMatrix;       // 1 where original is NOT white, 0 where it is white
    private final int[][] rowRepaintPotential; // row‑wise pre‑computed values
    private final int[][] colRepaintPotential; // column‑wise pre‑computed values
    private final int[] alreadyWhiteRows;    // rows that are already fully white
    private final int[] alreadyWhiteCols;    // columns that are already fully white

    WhiteCellOptimizer(int n, int k, char[][] original) {
        this.n = n;
        this.k = k;
        this.original = original;

        // Transform the board into a numeric matrix: 1 = non‑white, 0 = white.
        this.whiteMatrix = new int[n][n];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                whiteMatrix[i][j] = (original[i][j] == 'W') ? 0 : 1;
            }
        }

        // Mark rows / columns that are already completely white.
        this.alreadyWhiteRows = countFullyWhiteRows();
        this.alreadyWhiteCols = countFullyWhiteColumns();

        // Pre‑compute the effect of painting each possible k×k block.
        this.rowRepaintPotential     = precomputeRowImpact();
        this.colRepaintPotential     = precomputeColumnImpact();
    }

    /**
     * Returns the maximal number of completely white rows + columns that can be
     * obtained after painting one k×k block.
     */
    int maxWhiteLines() {
        int baseline = sum(alreadyWhiteRows) + sum(alreadyWhiteCols);
        int best = baseline;

        // Examine every possible top‑left corner of the brush.
        for (int row = 0; row < n; row++) {
            for (int col = 0; col < n; col++) {
                int addedRows  = rowRepaintPotential[row][col];
                int addedCols  = colRepaintPotential[row][col];

                best = Math.max(best, baseline + addedRows + addedCols);
            }
        }
        return best;
    }

    /** Counts rows that consist only of white cells. */
    private int[] countFullyWhiteRows() {
        int[] result = new int[n];
        for (int i = 0; i < n; i++) {
            boolean allWhite = true;
            for (int j = 0; j < n; j++) {
                if (whiteMatrix[i][j] != 0) {
                    allWhite = false;
                    break;
                }
            }
            result[i] = allWhite ? 1 : 0;
        }
        return result;
    }

    /** Counts columns that consist only of white cells. */
    private int[] countFullyWhiteColumns() {
        int[] result = new int[n];
        for (int j = 0; j < n; j++) {
            boolean allWhite = true;
            for (int i = 0; i < n; i++) {
                if (whiteMatrix[i][j] != 0) {
                    allWhite = false;
                    break;
                }
            }
            result[j] = allWhite ? 1 : 0;
        }
        return result;
    }

    /** Pre‑computes, for every row‑wise brush position, how many new rows become white. */
    private int[][] precomputeRowImpact() {
        int[][] impact = new int[n][n];

        // For each board row, we need to know for each column whether a brush placed
        // with its left side at that column would fill the whole row with white cells.
        for (int i = 0; i < n; i++) {
            int[] rowLine = computeWitableRowSegments(i);
            // Propagate the segment information into a fixed‑size matrix.
            // The value at (i, col) tells us whether painting from column `col`
            // would make this row fully white when the brush height is `k`.
            for (int col = 0; col <= n - k; col++) {
                if (rowLine[col] == 1) {
                    impact[i][col] = 1;
                }
            }
        }
        return impact;
    }

    /**
     * Determines, for a given board row, at which column positions painting a
     * k‑wide strip would turn the whole row white.
     */
    private int[] computeWitableRowSegments(int row) {
        // Prefix sums of the non‑white cells in this row.
        int[] prefix = buildPrefixSum(whiteMatrix[row]);

        // If the whole row is already white, no segment needs marking.
        if (prefix[n] == 0) {
            return new int[n]; // all entries are zeros – already counted separately.
        }

        int[] result = new int[n];
        // Scan every possible leftmost column of a k‑wide brush.
        for (int left = 0; left <= n - k; left++) {
            // Row becomes white if everything left of the segment and everything
            // after the segment is already white.
            if (prefix[left] == 0 && prefix[left + k] == prefix[n]) {
                result[left] = 1;
            }
        }
        return result;
    }

    /** Helper that builds a prefix‑sum array from a given int array. */
    private static int[] buildPrefixSum(int[] source) {
        int len = source.length;
        int[] pref = new int[len + 1];
        for (int i = 0; i < len; i++) {
            pref[i + 1] = pref[i] + source[i];
        }
        return pref;
    }

    /** Pre‑computes, for every column‑wise brush position, how many new columns become white. */
    private int[][] precomputeColumnImpact() {
        // First, transpose the matrix to reuse the row‑wise logic.
        int[][] transposed = transpose(whiteMatrix);

        // Compute row‑impact for the transposed board (i.e., column‑impact for the original).
        int[][] rowImpactOnTransposed = precomputeRowImpactForMatrix(transposed);

        // Transpose the impact back to the original orientation.
        int[][] impact = new int[n][n];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                impact[j][i] = rowImpactOnTransposed[i][j];
            }
        }
        return impact;
    }

    /** Row‑impact computation that works on any int matrix (not just the original board). */
    private int[][] precomputeRowImpactForMatrix(int[][] matrix) {
        int[][] impact = new int[n][n];
        for (int i = 0; i < n; i++) {
            int[] witableRowSegments = computeWitableRowSegmentsFromRow(matrix[i]);
            for (int col = 0; col <= n - k; col++) {
                if (witableRowSegments[col] == 1) {
                    impact[i][col] = 1;
                }
            }
        }
        return impact;
    }

    /**
     * Compute witable segments for a single row of an arbitrary matrix.
     * This method is extracted from {@code computeWitableRowSegments} but works
     * on any row array (no need to allocate a new prefix array each time).
     */
    private int[] computeWitableRowSegmentsFromRow(int[] row) {
        int[] prefix = buildPrefixSum(row);
        if (prefix[n] == 0) {
            return new int[n];
        }
        int[] result = new int[n];
        for (int left = 0; left <= n - k; left++) {
            if (prefix[left] == 0 && prefix[left + k] == prefix[n]) {
                result[left] = 1;
            }
        }
        return result;
    }

    /** Simple matrix transposition. */
    private static int[][] transpose(int[][] src) {
        int[][] dst = new int[src.length][src.length];
        for (int i = 0; i < src.length; i++) {
            for (int j = 0; j < src.length; j++) {
                dst[i][j] = src[j][i];
            }
        }
        return dst;
    }

    /** Utility to sum an int array. */
    private static int sum(int[] a) {
        int s = 0;
        for (int v : a) {
            s += v;
        }
        return s;
    }
}

/**
 *  Very small wrapper around {@link PrintWriter} that avoids the need for
 *  null‑checking when flushing.
 */
final class FastPrintWriter extends PrintWriter {
    FastPrintWriter(java.io.OutputStream out) {
        super(out);
    }

    /** Flushes and closes the underlying stream. */
    void flushAndClose() {
        flush();
        close();
    }
}

/**
 *  Fast, buffered scanner that works with the original problem input format.
 *  It replaces the old {@code InputReader} with clearer method names and
 *  a more straightforward API.
 */
final class FastScanner {
    private final java.io.InputStream stream;
    private final byte[] buffer = new byte[16_384];
    private int pointer = 0, length = 0;
    private int curChar;
    private final java.util.function.IntPredicate spaceFilter;

    FastScanner(java.io.InputStream stream) {
        this.stream = stream;
        this.spaceFilter = this::isWhitespace;
    }

    /** Reads the next token as an integer. */
    int nextInt() {
        return Integer.parseInt(nextToken());
    }

    /** Reads the next token (a contiguous sequence of non‑whitespace characters). */
    String nextToken() {
        StringBuilder sb = new StringBuilder();
        int c;
        while (true) {
            c = read();
            if (c == -1) break;
            if (!isWhitespace(c)) break;
        }
        if (c == -1) return null;
        do {
            sb.append((char) c);
            c = read();
        } while (!isWhitespace(c));
        return sb.toString();
    }

    /** Reads a fixed‑size array of characters. */
    char[] readCharArray(int size) {
        char[] out = new char[size];
        for (int i = 0; i < size; i++) {
            out[i] = readCharacter();
        }
        return out;
    }

    /** Reads a rectangular table of characters. */
    char[][] readTable(int rows, int cols) {
        char[][] table = new char[rows][];
        for (int r = 0; r < rows; r++) {
            table[r] = readCharArray(cols);
        }
        return table;
    }

    /** Reads a single character, skipping whitespace. */
    private char readCharacter() {
        int c;
        while ((c = read()) != -1 && isWhitespace(c)) ;
        if (c == -1) throw new java.util.NoSuchElementException();
        return (char) c;
    }

    /** Checks whether a character code represents whitespace. */
    private boolean isWhitespace(int c) {
        return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
    }

    /** Reads the next raw byte from the underlying stream, applying buffering. */
    private int read() {
        if (length == -1) return -1; // sentinel
        if (pointer >= length) {
            pointer = 0;
            length = stream.read(buffer);
            if (length <= 0) length = -1;
        }
        return buffer[pointer++];
    }
}

import java.io.*;
import java.util.*;

/**
 * Refactored solution for the original problem.
 * The code has been reorganised to improve readability,
 * maintainability and separation of concerns.
 */
public class Main {

    /** Sentinel value used to mark “no land” in a row / column. */
    private static final int INF = Integer.MAX_VALUE;

    /* ------------ I/O helpers ----------------- */
    private static BufferedReader reader;
    private static StringTokenizer tokenizer;
    private static PrintWriter writer;

    private static String next() throws IOException {
        while (!tokenizer.hasMoreTokens()) {
            tokenizer = new StringTokenizer(reader.readLine());
        }
        return tokenizer.nextToken();
    }

    private static int nextInt() throws IOException {
        return Integer.parseInt(next());
    }

    private static void initTokenizer(InputStream source) {
        reader = new BufferedReader(new InputStreamReader(source));
        tokenizer = new StringTokenizer("");
    }

    /* ------------ Problem data ----------------- */
    /** Grid representation: 0 = water ('W'), 1 = land ('B'). */
    private static int[][] grid;

    /** Extreme land positions for each row (forward and backward). */
    private static int[] rowMaxLandCol;   // farthest column with land in the row
    private static int[] rowMinLandCol;   // nearest column with land in the row

    /** Extreme land positions for each column (forward and backward). */
    private static int[] colMaxLandRow;   // farthest row with land in the column
    private static int[] colMinLandRow;   // nearest row with land in the column

    /** Number of rows/columns that contain no land at all. */
    private static int missingRows;

    /* ------------ Segment tree ----------------- */
    /** Simple range‑add, point‑query segment tree used to maintain coverage sums. */
    private static class SegmentTree {
        private final int size;   // number of leaves
        private final int[] max;   // maximum value in a segment (including lazy updates)
        private final int[] lazy;  // pending additions for a segment

        SegmentTree(int n) {
            this.size = n;
            this.max = new int[4 * n];
            this.lazy = new int[4 * n];
        }

        /** Propagate pending lazy updates to child nodes. */
        private void push(int node) {
            if (lazy[node] != 0) {
                max[node * 2 + 1] += lazy[node];
                max[node * 2 + 2] += lazy[node];
                lazy[node * 2 + 1] += lazy[node];
                lazy[node * 2 + 2] += lazy[node];
                lazy[node] = 0;
            }
        }

        /** Add `value` to every leaf in the inclusive range [left, right]. */
        void add(int left, int right, int value) {
            add(0, 0, size - 1, left, right, value);
        }

        /** Internal recursive addition routine. */
        private void add(int node, int l, int r, int ql, int qr, int value) {
            if (qr < l || ql > r) {
                return;                       // no overlap
            }
            if (ql <= l && r <= qr) {
                max[node] += value;
                lazy[node] += value;
                return;                       // total overlap
            }
            push(node);
            int mid = (l + r) >>> 1;
            add(node * 2 + 1, l, mid, ql, qr, value);
            add(node * 2 + 2, mid + 1, r, ql, qr, value);
            max[node] = Math.max(max[node * 2 + 1], max[node * 2 + 2]);
        }

        /** Retrieve the global maximum value stored in the tree. */
        int getMaximum() {
            return max[0];
        }
    }

    /* ------------ Input processing ------------- */
    /**
     * Reads the complete input, builds the grid and pre‑computes
     * the extreme land positions used later on.
     */
    private static void readInput() throws IOException {
        int n = nextInt();
        int k = nextInt();

        char[][] raw = new char[n][];
        for (int i = 0; i < n; i++) {
            raw[i] = next().toCharArray();
        }

        grid = new int[n][n];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                grid[i][j] = (raw[i][j] == 'W' ? 0 : 1);
            }
        }

        // initialise helper arrays with sentinel values
        Arrays.fill(rowMaxLandCol = new int[n], -INF);
        Arrays.fill(rowMinLandCol = new int[n], INF);
        Arrays.fill(colMaxLandRow = new int[n], -INF);
        Arrays.fill(colMinLandRow = new int[n], INF);

        missingRows = 0;

        // Scan the whole board once to capture extremes
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (grid[i][j] == 1) {                     // land cell found
                    rowMaxLandCol[i] = Math.max(rowMaxLandCol[i], j);
                    rowMinLandCol[i] = Math.min(rowMinLandCol[i], j);
                    colMaxLandRow[j] = Math.max(colMaxLandRow[j], i);
                    colMinLandRow[j] = Math.min(colMinLandRow[j], i);
                }
            }
        }

        // Count rows (and columns) that have no land at all – they represent
        // permanent “missed” rows independent of any window placement.
        for (int i = 0; i < n; i++) {
            if (rowMaxLandCol[i] == -INF) {                 // no land in this row
                missingRows++;
            }
            if (colMaxLandRow[i] == -INF) {                 // no land in this column
                missingRows++;
            }
        }
    }

    /* ------------ Core algorithm ----------------- */
    /**
     * Solves the problem by sliding a k×k window downwards,
     * maintaining coverage information with a segment tree.
     *
     * @return the maximal number of rows that can be turned into
     *         “fully covered” rows given the constraints.
     */
    private static int solve() {
        int bestResult = 0;

        // Move the top of the k‑row window from 0 up to n‑k inclusive
        for (int top = 0; top + k <= n; top++) {
            SegmentTree tree = new SegmentTree(n);
            int[] verticalMask = new int[n];

            // Mark columns that contain at least one land cell inside the current window
            for (int col = 0; col < n; col++) {
                verticalMask[col] = (colMinLandRow[col] >= top && colMaxLandRow[col] < top + k) ? 1 : 0;
            }

            // Compute the sum of the first k entries of the mask
            int windowSum = 0;
            for (int j = 0; j < k; j++) {
                windowSum += verticalMask[j];
            }
            tree.add(0, 0, windowSum);

            // Slide the window across all columns, updating the segment tree
            for (int j = k; j < n; j++) {
                int outIdx = j - k;
                windowSum += verticalMask[j] - verticalMask[outIdx];
                tree.add(outIdx + 1, outIdx + 1, windowSum);
            }

            // Horizontal contributions: each row inside the window can be fully covered
            // by a single horizontal segment of length k if the row's land stretch
            // fits into a k‑length interval.
            for (int row = top; row < top + k; row++) {
                int leftMost = rowMinLandCol[row];
                int rightMost = rowMaxLandCol[row];

                // If the row is wider than k cells, we cannot cover it horizontally.
                if (rightMost - leftMost > k) {
                    continue;
                }

                // The leftmost start position that still covers the whole interval.
                int start = Math.max(0, rightMost - k + 1);
                int end   = leftMost;               // inclusive
                tree.add(start, end, 1);
            }

            // The answer for this window is the static missing rows plus the best
            // coverage we could achieve horizontally.
            int covered = missingRows + tree.getMaximum();
            bestResult = Math.max(bestResult, covered);
        }
        return bestResult;
    }

    /* ------------ Entry point ------------------- */
    public static void main(String[] args) throws IOException {
        initTokenizer(System.in);
        readInput();
        int answer = solve();
        writer = new PrintWriter(System.out);
        writer.println(answer);
        writer.flush();
    }
}

import java.io.*;
import java.util.*;

public class Main {

    /** ------------------------------------------------------------
     *  Fast, simple input reader.
     *  ----------------------------------------------------------- */
    private static final class InputReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        InputReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream), 32768);
            tokenizer = null;
        }

        /** Return next token, optionally skipping empty lines. */
        private String nextToken() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new UncheckedIOException(e);
                }
            }
            return tokenizer.nextToken();
        }

        int nextInt() { return Integer.parseInt(nextToken()); }
        long nextLong() { return Long.parseLong(nextToken()); }
    }

    /** ------------------------------------------------------------
     *  Core algorithm – all business logic lives here.
     *  ----------------------------------------------------------- */
    private static final class Solver {

        /** Solves a single test case (the original program only has one). */
        void solve(int ignoredTestNumber, InputReader sc, PrintWriter out) {
            /* ---------- 1. read dimensions and grid ------------------- */
            int n = sc.nextInt();          // board size
            int k = sc.nextInt();          // size of the movable square

            char[][] board = new char[n][];
            for (int i = 0; i < n; i++) {
                String token = sc.nextToken().replaceAll("\\s+", ""); // drop possible spaces
                if (token.length() != n) {
                    throw new IllegalArgumentException("Row length does not match board size");
                }
                board[i] = token.toCharArray();
            }

            /* ---------- 2. pre‑compute extremes of black cells -------- */
            final int INF = Integer.MAX_VALUE;
            int[] leftInRow  = new int[n];   // smallest column with 'B' in this row
            int[] rightInRow = new int[n];   // largest  column with 'B' in this row
            int[] topInCol   = new int[n];   // smallest row    with 'B' in this column
            int[] bottomInCol= new int[n];   // largest  row    with 'B' in this column

            Arrays.fill(leftInRow,  INF);
            Arrays.fill(rightInRow, -1);
            Arrays.fill(topInCol,   INF);
            Arrays.fill(bottomInCol, -1);

            int emptyRows = 0;   // rows that contain no 'B'
            int emptyCols = 0;   // columns that contain no 'B'

            for (int r = 0; r < n; r++) {
                for (int c = 0; c < n; c++) {
                    if (board[r][c] == 'B') {
                        leftInRow[r]  = Math.min(leftInRow[r],  c);
                        rightInRow[r] = Math.max(rightInRow[r], c);
                        topInCol[c]   = Math.min(topInCol[c],   r);
                        bottomInCol[c]= Math.max(bottomInCol[c], r);
                    }
                }
                // row without a black cell
                if (leftInRow[r] == INF) {
                    emptyRows++;
                    leftInRow[r]  = -1;   // sentinel values – never used in coverage test
                    rightInRow[r] = n;    // make the whole row “fit” no window
                }
            }
            for (int c = 0; c < n; c++) {
                if (topInCol[c] == INF) {
                    emptyCols++;
                    topInCol[c]   = -1;
                    bottomInCol[c]= n;
                }
            }

            /* ---------- 3. try every possible k×k window ------------- */
            int bestCovered = 0;   // max(rows + cols) that can be fully covered

            // slide the window vertically (startRow) and horizontally (startCol)
            for (int startRow = 0; startRow <= n - k; startRow++) {
                for (int startCol = 0; startCol <= n - k; startCol++) {
                    int rowsCovered = 0;
                    // rows that lie completely inside the chosen column window
                    for (int r = startRow; r < startRow + k; r++) {
                        if (leftInRow[r] == -1) {               // empty row – ignore
                            continue;
                        }
                        if (leftInRow[r] >= startCol && rightInRow[r] < startCol + k) {
                            rowsCovered++;
                        }
                    }

                    int colsCovered = 0;
                    // columns that lie completely inside the chosen row window
                    for (int c = startCol; c < startCol + k; c++) {
                        if (topInCol[c] == -1) {                // empty column – ignore
                            continue;
                        }
                        if (topInCol[c] >= startRow && bottomInCol[c] < startRow + k) {
                            colsCovered++;
                        }
                    }

                    bestCovered = Math.max(bestCovered, rowsCovered + colsCovered);
                }
            }

            /* ---------- 4. output ----------------------------------- */
            out.println(bestCovered + emptyRows + emptyCols);
        }
    }

    /** ------------------------------------------------------------
     *  Entry point – keeps the original `main` signature.
     *  ----------------------------------------------------------- */
    public static void main(String[] args) throws Exception {
        InputStream  in  = System.in;
        OutputStream out = System.out;

        InputReader reader = new InputReader(in);
        PrintWriter   writer = new PrintWriter(out, true);

        new Solver().solve(1, reader, writer);   // only one test case in the original code

        writer.close();
    }
}

import java.io.*;
import java.util.*;
import java.util.stream.*;

public class Main {

    public static void main(String[] args) {
        try (InputStream in = System.in;
             OutputStream out = System.out) {
            InputReader reader = new InputReader(in);
            PrintWriter writer = new PrintWriter(out);
            WhiteLinesSolver solver = new WhiteLinesSolver();
            solver.solve(1, reader, writer);
            writer.flush();
        }
    }

    /** Simple input reader based on BufferedReader and StringTokenizer. */
    static class InputReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        InputReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
        }

        String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new UncheckedIOException(e);
                }
            }
            return tokenizer.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }
    }

    /** Core logic for solving a single test case. */
    static class WhiteLinesSolver {

        /** Solves one test case and writes the answer to the supplied PrintWriter. */
        void solve(int testNumber, InputReader in, PrintWriter out) {
            int n = in.nextInt();
            int k = in.nextInt();

            char[][] grid = readGrid(n, in);
            int[][] black = toBinary(grid);

            boolean[] hasBlackRow = new boolean[n];
            boolean[] hasBlackCol = new boolean[n];

            for (int i = 0; i < n; i++) {
                for (int j = 0; j < n; j++) {
                    if (black[i][j] == 1) {
                        hasBlackRow[i] = true;
                        hasBlackCol[j] = true;
                    }
                }
            }

            int[][] scores = computeColumnScores(black, k);
            int[][] transposedScores = computeColumnScores(transpose(black), k);

            int bestPlacement = computeBestCombined(scores, transposedScores, n, k);
            int alreadyWhiteLines = countMissingRows(hasBlackRow) + countMissingCols(hasBlackCol);

            out.println(bestPlacement + alreadyWhiteLines);
        }

        /** Reads an n×n grid of characters from the input. */
        private static char[][] readGrid(int size, InputReader in) {
            char[][] grid = new char[size][];
            for (int i = 0; i < size; i++) {
                grid[i] = in.next().toCharArray();
            }
            return grid;
        }

        /** Converts a character grid into a binary matrix (1 = black, 0 = white). */
        private static int[][] toBinary(char[][] grid) {
            int n = grid.length;
            int[][] binary = new int[n][n];
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < n; j++) {
                    binary[i][j] = grid[i][j] == 'B' ? 1 : 0;
                }
            }
            return binary;
        }

        /** Computes a matrix where entry (i, j) holds the number of rows that would become white
         *  if a k×k brush starts at column j on row i. */
        private static int[][] computeColumnScores(int[][] black, int k) {
            int n = black.length;
            int window = n - (k - 1);
            int[][] scores = new int[window][window];

            // Determine which column starts of a k‑wide window fully cover all black cells in each row.
            boolean[][] canCover = new boolean[n][window];
            for (int row = 0; row < n; row++) {
                int first = findFirstBlack(black[row]);
                int last = findLastBlack(black[row]);
                if (first == -1) {
                    continue; // row already white
                }
                for (int start = 0; start < window; start++) {
                    canCover[row][start] = start <= first && last <= start + (k - 1);
                }
            }

            // Prefix sums per column start to count covered rows in a vertical sliding window.
            int[] prefix = new int[n + 1];
            for (int colStart = 0; colStart < window; colStart++) {
                Arrays.fill(prefix, 0);
                for (int row = 0; row < n; row++) {
                    prefix[row + 1] = prefix[row] + (canCover[row][colStart] ? 1 : 0);
                }
                for (int rowStart = 0; rowStart < window; rowStart++) {
                    scores[rowStart][colStart] = prefix[rowStart + k] - prefix[rowStart];
                }
            }
            return scores;
        }

        private static int findFirstBlack(int[] row) {
            for (int i = 0; i < row.length; i++) {
                if (row[i] == 1) return i;
            }
            return -1;
        }

        private static int findLastBlack(int[] row) {
            for (int i = row.length - 1; i >= 0; i--) {
                if (row[i] == 1) return i;
            }
            return -1;
        }

        /** Returns the transpose of a matrix. */
        private static int[][] transpose(int[][] matrix) {
            int n = matrix.length;
            int[][] t = new int[n][n];
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < n; j++) {
                    t[i][j] = matrix[j][i];
                }
            }
            return t;
        }

        /** Finds the maximal combined score from original and transposed placement matrices. */
        private static int computeBestCombined(int[][] orig, int[][] trans, int size, int k) {
            int best = 0;
            int window = size - (k - 1);
            for (int i = 0; i < window; i++) {
                for (int j = 0; j < window; j++) {
                    best = Math.max(best, orig[i][j] + trans[j][i]);
                }
            }
            return best;
        }

        /** Counts rows that contain no black cells. */
        private static int countMissingRows(boolean[] hasBlack) {
            return (int) Arrays.stream(hasBlack).filter(b -> !b).count();
        }

        /** Counts columns that contain no black cells. */
        private static int countMissingCols(boolean[] hasBlack) {
            return (int) Arrays.stream(hasBlack).filter(b -> !b).count();
        }
    }
}

package com.example;   // optional – remove if not needed

import java.io.*;
import java.util.Arrays;

/**
 * Refactored version of the original program.
 *
 * The program reads a grid of characters, extracts some statistics about the
 * rows and columns that contain the character 'B', updates difference arrays
 * to count how many rows/columns can be covered by a k‑sized window, and then
 * prints the maximum possible number of covered cells together with the
 * number of completely empty rows/columns.
 *
 * The logic is unchanged – only the structure, naming and defensive coding
 * have been improved for readability and maintainability.
 */
public class Solution {

    /** sentinel value used for initialisation of min/max trackers */
    private static final int UNSET = Integer.MAX_VALUE / 4;   // smaller than any valid index

    /** Fast scanner wrapper */
    private static final class FastScanner {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        FastScanner(InputStream is) {
            this.reader = new BufferedReader(new InputStreamReader(is));
        }

        /** Returns the next token, reading a new line if necessary */
        private String nextToken() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                String line = reader.readLine();
                if (line == null) {
                    return null;
                }
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        /** Convenience methods */
        int nextInt() throws IOException {
            return Integer.parseInt(nextToken());
        }

        char[] nextCharArray() throws IOException {
            return nextToken().toCharArray();
        }
    }

    /** Simple 2‑D Fenwick‑style helper used by the original algorithm */
    private static final class SuperBIT {
        private final long[] mul;
        private final long[] add;

        SuperBIT(int size) {
            mul = new long[size];
            add = new long[size];
        }

        /** Range update: add `val` to interval [l, r] */
        void update(int l, int r, long val) {
            internalUpdate(l, val, -val * (l - 1));
            internalUpdate(r, -val, val * r);
        }

        /** Internal point update */
        private void internalUpdate(int idx, long mulVal, long addVal) {
            for (int i = idx; i < mul.length; i = i | (i + 1)) {
                this.mul[i] += mulVal;
                this.add[i] += addVal;
            }
        }

        /** Prefix sum up to `idx` */
        long query(int idx) {
            long mulSum = 0, addSum = 0;
            for (int i = idx; i >= 0; i = (i & (i + 1)) - 1) {
                mulSum += mul[i];
                addSum += add[i];
            }
            return mulSum * idx + addSum;
        }

        /** Sum of values in the inclusive range [l, r] */
        long query(int l, int r) {
            if (l > r) {
                int tmp = l;
                l = r;
                r = tmp;
            }
            return query(r) - (l > 0 ? query(l - 1) : 0);
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(System.out);

        solve(fs, out);
        out.flush();
    }

    /**
     * Core logic extracted from the original `main` method.
     *
     * @param fs  scanner that reads from {@code System.in}
     * @param out printer that writes to {@code System.out}
     */
    private static void solve(FastScanner fs, PrintWriter out) {
        int n = fs.nextInt();          // size of the square grid
        int k = fs.nextInt();          // window size we are allowed to use
        char[][] grid = new char[n][];
        for (int i = 0; i < n; i++) {
            grid[i] = fs.nextCharArray();
        }

        // --------------------------------------------------------------------
        // 1️⃣  Compute min / max row / column for each row and column that
        //     contains at least one 'B'.
        // --------------------------------------------------------------------
        int[] minRow = fill(n, UNSET);
        int[] maxRow = fill(n, -1);
        int[] minCol = fill(n, UNSET);
        int[] maxCol = fill(n, -1);

        for (int r = 0; r < n; r++) {
            for (int c = 0; c < n; c++) {
                if (grid[r][c] == 'B') {
                    minRow[r] = Math.min(minRow[r], c);
                    maxRow[r] = Math.max(maxRow[r], c);
                    minCol[c] = Math.min(minCol[c], r);
                    maxCol[c] = Math.max(maxCol[c], r);
                }
            }
        }

        // --------------------------------------------------------------------
        // 2️⃣  Count rows / columns that do NOT contain a 'B' – they will be
        //     automatically covered by a k‑sized window later.
        // --------------------------------------------------------------------
        int emptyRowCount = 0;
        int emptyColCount = 0;

        // --------------------------------------------------------------------
        // 3️⃣  Build difference arrays that record how many rows / columns
        //     become fully covered when we slide a size‑k window.
        // --------------------------------------------------------------------
        int[][] rowDiffs = new int[n][n + 2];
        int[][] colDiffs = new int[n][n + 2];

        for (int i = 0; i < n; i++) {
            // rows without any 'B' will contribute directly later
            if (maxRow[i] == -1) {
                emptyRowCount++;
            }

            // rows that have a 'B' block that can fit into a window of length k
            if (maxRow[i] != -1 && (maxRow[i] - minRow[i] + 1) <= k) {
                int slack = k - (maxRow[i] - minRow[i] + 1);
                int start = Math.max(0, minRow[i] - slack);
                // update a *difference* array for all possible start positions
                int endIdx = i;
                for (int startIdx = i; startIdx >= Math.max(0, i - k + 1); startIdx--) {
                    colDiffs[startIdx][start]++;
                    colDiffs[startIdx][minRow[i] + 1]--;
                }
            }

            // symmetric handling for columns
            if (maxCol[i] != -1 && (maxCol[i] - minCol[i] + 1) <= k) {
                int slack = k - (maxCol[i] - minCol[i] + 1);
                int start = Math.max(0, minCol[i] - slack);
                int endIdx = i;
                for (int startIdx = i; startIdx >= Math.max(0, i - k + 1); startIdx--) {
                    rowDiffs[startIdx][start]++;
                    rowDiffs[startIdx][minCol[i] + 1]--;
                }
            }

            if (maxCol[i] == -1) {
                emptyColCount++;
            }
        }

        // --------------------------------------------------------------------
        // 4️⃣  Convert the difference arrays into prefix‑sum arrays.
        // --------------------------------------------------------------------
        for (int i = 0; i < n; i++) {
            for (int j = 1; j <= n; j++) {
                rowDiffs[i][j] += rowDiffs[i][j - 1];
                colDiffs[i][j] += colDiffs[i][j - 1];
            }
        }

        // --------------------------------------------------------------------
        // 5️⃣  Compute the maximal number of cells that can be covered.
        // --------------------------------------------------------------------
        long best = 0L;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                // rows[i][j] counts how many rows become covered at column j,
                // cols[j][i] does the same for columns at row i.
                best = Math.max(best, rowDiffs[i][j] + colDiffs[j][i]);
            }
        }

        // --------------------------------------------------------------------
        // 6️⃣  Output the result: best coverage + the number of completely
        //     empty rows/columns.
        // --------------------------------------------------------------------
        out.println(best + emptyRowCount + emptyColCount);
    }

    /** Helper that creates an int array of length {@code size} filled with {@code init} */
    private static int[] fill(int size, int init) {
        int[] arr = new int[size];
        Arrays.fill(arr, init);
        return arr;
    }
}

import java.io.*;
import java.util.*;

public class Main {

    /* ---------- I/O ---------- */
    private final InputStream in;
    private final PrintWriter out;

    private final byte[] buffer = new byte[1 << 16];
    private int bufLen = 0, bufPos = 0;

    private int readByte() throws IOException {
        if (bufPos >= bufLen) {
            bufPos = 0;
            bufLen = in.read(buffer);
            if (bufLen <= 0) return -1;
        }
        return buffer[bufPos++];
    }

    private boolean isSpaceChar(int c) {
        return c <= 32;
    }

    private int skip() throws IOException {
        int b;
        while ((b = readByte()) != -1 && isSpaceChar(b)) {}
        return b;
    }

    private int ni() throws IOException {
        int num = 0;
        boolean neg = false;
        int b = skip();
        if (b == '-') {
            neg = true;
            b = readByte();
        }
        while (b >= '0' && b <= '9') {
            num = num * 10 + (b - '0');
            b = readByte();
        }
        return neg ? -num : num;
    }

    private long nl() throws IOException {
        long num = 0;
        boolean neg = false;
        int b = skip();
        if (b == '-') {
            neg = true;
            b = readByte();
        }
        while (b >= '0' && b <= '9') {
            num = num * 10 + (b - '0');
            b = readByte();
        }
        return neg ? -num : num;
    }

    private String ns() throws IOException {
        StringBuilder sb = new StringBuilder();
        int b = skip();
        while (!isSpaceChar(b)) {
            sb.append((char) b);
            b = readByte();
        }
        return sb.toString();
    }

    /* ---------- Core algorithm ---------- */
    private void solve() throws Exception {
        int n = ni();
        int k = ni();

        char[][] grid = new char[n][];
        for (int r = 0; r < n; r++) {
            grid[r] = ns().toCharArray();
        }

        int[][] colPref = buildColumnPrefix(grid, n);
        int[][] rowPref = buildRowPrefix(grid, n);

        int[][] verticalValid   = computeVerticalValid(grid, n, k, colPref);
        int[][] horizontalValid = computeHorizontalValid(grid, n, k, rowPref);

        int[][] verticalCount   = prefixSum2D(verticalValid, n);
        int[][] horizontalCount = prefixSum2D(horizontalValid, n);

        int[] fullyWhiteRows = countFullyWhiteRows(grid, n, rowPref);
        int[] fullyWhiteCols = countFullyWhiteCols(grid, n, colPref);

        int[] prefixRows = prefixSum1D(fullyWhiteRows, n + 1);
        int[] prefixCols = prefixSum1D(fullyWhiteCols, n + 1);
        int[] suffixRows = suffixSum1D(fullyWhiteRows, n + 2);
        int[] suffixCols = suffixSum1D(fullyWhiteCols, n + 2);

        int answer = prefixRows[n] + prefixCols[n];

        for (int r = 1; r <= n; r++) {
            for (int c = 1; c <= n; c++) {
                int top    = Math.max(1, r - k + 1);
                int left   = Math.max(1, c - k + 1);
                if (top == 0 || left == 0) continue;

                int cur = prefixRows[top - 1]
                        + suffixRows[r + 1]
                        + prefixCols[left - 1]
                        + suffixCols[c + 1]
                        + verticalCount[r][c]
                        - verticalCount[top - 1][c]
                        + horizontalCount[r][c]
                        - horizontalCount[r][left - 1];

                answer = Math.max(answer, cur);
            }
        }

        out.println(answer);
    }

    /* ---------- Helper methods ---------- */
    private int[][] buildColumnPrefix(char[][] g, int n) {
        int[][] pref = new int[n + 1][n + 1];
        for (int j = 1; j <= n; j++) {
            for (int i = 1; i <= n; i++) {
                pref[i][j] = pref[i - 1][j];
                if (g[i - 1][j - 1] == 'W') pref[i][j]++;
            }
        }
        return pref;
    }

    private int[][] buildRowPrefix(char[][] g, int n) {
        int[][] pref = new int[n + 1][n + 1];
        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= n; j++) {
                pref[i][j] = pref[i][j - 1];
                if (g[i - 1][j - 1] == 'W') pref[i][j]++;
            }
        }
        return pref;
    }

    private int[][] computeVerticalValid(char[][] g, int n, int k, int[][] colPref) {
        int[][] valid = new int[n + 2][n + 2];
        for (int j = 1; j <= n; j++) {
            for (int i = k; i <= n; i++) {
                if (colPref[i - k][j] == i - k && colPref[n][j] - colPref[i][j] == n - i) {
                    valid[i][j] = 1;
                }
            }
        }
        return valid;
    }

    private int[][] computeHorizontalValid(char[][] g, int n, int k, int[][] rowPref) {
        int[][] valid = new int[n + 2][n + 2];
        for (int i = 1; i <= n; i++) {
            for (int j = k; j <= n; j++) {
                if (rowPref[i][j - k] == j - k && rowPref[i][n] - rowPref[i][j] == n - j) {
                    valid[i][j] = 1;
                }
            }
        }
        return valid;
    }

    private int[][] prefixSum2D(int[][] src, int size) {
        int[][] dst = new int[size + 1][size + 1];
        for (int i = 1; i <= size; i++) {
            for (int j = 1; j <= size; j++) {
                dst[i][j] = dst[i][j - 1] + src[i][j];
            }
        }
        for (int i = 1; i <= size; i++) {
            for (int j = 1; j <= size; j++) {
                dst[i][j] += dst[i - 1][j];
            }
        }
        return dst;
    }

    private int[] prefixSum1D(int[] src, int size) {
        int[] dst = new int[size];
        int sum = 0;
        for (int i = 0; i < size; i++) {
            sum += src[i];
            dst[i] = sum;
        }
        return dst;
    }

    private int[] suffixSum1D(int[] src, int size) {
        int[] dst = new int[size];
        int sum = 0;
        for (int i = size - 1; i >= 0; i--) {
            sum += src[i];
            dst[i] = sum;
        }
        return dst;
    }

    private int[] countFullyWhiteRows(char[][] g, int n, int[][] rowPref) {
        int[] cnt = new int[n + 1];
        for (int i = 1; i <= n; i++) {
            cnt[i] = (rowPref[i][n] == n) ? 1 : 0;
        }
        return cnt;
    }

    private int[] countFullyWhiteCols(char[][] g, int n, int[][] colPref) {
        int[] cnt = new int[n + 1];
        for (int j = 1; j <= n; j++) {
            cnt[j] = (colPref[n][j] == n) ? 1 : 0;
        }
        return cnt;
    }

    /* ---------- Entry point ---------- */
    public static void main(String[] args) throws Exception {
        new Main().run();
    }

    private void run() throws Exception {
        in = System.in;
        out = new PrintWriter(System.out);
        solve();
        out.flush();
    }
}

import java.io.BufferedInputStream;
import java.io.IOException;
import java.io.InputStream;
import java.util.Scanner;

/**
 * Utility class that encapsulates all logic required to solve the problem.
 * The program reads an {@code n × n} grid consisting of the characters {@code 'B'} and
 * possibly other filler characters, then evaluates a specific "bonus" based on
 * vertical and horizontal slices of size {@code k+1}.  The result printed to
 * {@code System.out} is the sum of the best found bonus and the number of empty
 * rows/columns in the original grid.
 *
 * The original implementation was compact but hard to follow; this version
 * focuses on readability, modularisation and proper resource handling.
 */
public final class BonusCalculator {

    /** Size of the input buffer – 2^19 bytes (≈ 524 kB) gives good performance. */
    private static final int BUFFER_SIZE = 1 << 19;

    /** Private constructor – utility class. */
    private BonusCalculator() {
    }

    /** Entry point – mirrors the original {@code main}. */
    public static void main(String[] args) throws IOException {
        try (InputStream in = new BufferedInputStream(System.in, BUFFER_SIZE)) {
            Result result = solve(in);
            System.out.println(result.value);
        }
    }

    /**
     * Core solver that receives a {@link Scanner} positioned on the first token.
     *
     * @param scanner a scanner that will read the whole input
     * @return an object containing the computed answer
     * @throws IOException if reading fails
     */
    public static Result solve(InputStream source) throws IOException {
        try (Scanner scanner = new Scanner(source)) {
            int n = scanner.nextInt();           // grid dimension
            int k = scanner.nextInt() - 1;       // slice length minus one

            GridData grid = readGrid(scanner, n);

            BonusData bonus = computeBonuses(grid, k);

            int bestBonus = findBestBonus(bonus, k, n);
            int emptyLines = countEmptyLines(grid, n);

            return new Result(bestBonus + emptyLines);
        }
    }

    /** Reads the {@code n × n} character grid from the scanner. */
    private static GridData readGrid(Scanner scanner, int n) {
        int[][] verticalAcc = new int[n][n];   // cumulative 'B' count column‑wise
        int[][] horizontalAcc = new int[n][n]; // cumulative 'B' count row‑wise

        for (int row = 0; row < n; row++) {
            String line = scanner.next();
            for (int col = 0; col < n; col++) {
                char cell = line.charAt(col);
                int isB = (cell == 'B') ? 1 : 0;

                // column accumulator (vertical)
                verticalAcc[row][col] = ((row > 0) ? verticalAcc[row - 1][col] : 0) + isB;

                // row accumulator (horizontal)
                horizontalAcc[row][col] = ((col > 0) ? horizontalAcc[row][col - 1] : 0) + isB;
            }
        }
        return new GridData(verticalAcc, horizontalAcc);
    }

    /** Computes the per‑cell bonus flags for vertical and horizontal slices. */
    private static BonusData computeBonuses(GridData data, int k) {
        int n = data.vertical.length;

        // ---------- vertical slice bonus ----------
        int[][] upBonus = new int[n - k - 1][n]; // i ranges 0 … n‑k‑2
        for (int startRow = 0; startRow < n - k; startRow++) {
            for (int col = 0; col < n; col++) {
                int countInSlice = data.vertical[startRow + k][col]
                        - (startRow > 0 ? data.vertical[startRow - 1][col] : 0);
                boolean fullSlice = countInSlice == data.vertical[n - 1][col];
                upBonus[startRow][col] = fullSlice ? 1 : 0;
                if (data.vertical[n - 1][col] == 0) {
                    upBonus[startRow][col]--;
                }
            }
        }

        // ---------- horizontal slice bonus ----------
        int[][] leftBonus = new int[n][n - k - 1]; // j ranges 0 … n‑k‑2
        for (int row = 0; row < n; row++) {
            for (int startCol = 0; startCol < n - k; startCol++) {
                int countInSlice = data.horizontal[row][startCol + k]
                        - (startCol > 0 ? data.horizontal[row][startCol - 1] : 0);
                boolean fullSlice = countInSlice == data.horizontal[row][n - 1];
                leftBonus[row][startCol] = fullSlice ? 1 : 0;
                if (data.horizontal[row][n - 1] == 0) {
                    leftBonus[row][startCol]--;
                }
            }
        }

        // ---------- accumulated versions for fast range‑sum queries ----------
        int[][] upBonusAcc = accumulateRows(upBonus);
        int[][] leftBonusAcc = accumulateColumns(leftBonus);

        return new BonusData(upBonus, leftBonus, upBonusAcc, leftBonusAcc);
    }

    /** Helper that builds a prefix‑sum array for the rows of a 2‑D int matrix. */
    private static int[][] accumulateRows(int[][] matrix) {
        int rows = matrix.length;
        int cols = matrix[0].length;
        int[][] result = new int[rows][cols];
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                result[r][c] = ((c > 0) ? result[r][c - 1] : 0) + matrix[r][c];
            }
        }
        return result;
    }

    /** Helper that builds a prefix‑sum array for the columns of a 2‑D int matrix. */
    private static int[][] accumulateColumns(int[][] matrix) {
        int rows = matrix.length;
        int cols = matrix[0].length;
        int[][] result = new int[rows][cols];
        for (int c = 0; c < cols; c++) {
            for (int r = 0; r < rows; r++) {
                result[r][c] = ((r > 0) ? result[r - 1][c] : 0) + matrix[r][c];
            }
        }
        return result;
    }

    /** Finds the maximum combined bonus over all possible (i, j) placements. */
    private static int findBestBonus(BonusData data, int k, int n) {
        int best = 0;
        // The loops use the same bounds as the original code (0 … n‑k‑1)
        for (int i = 0; i < n - k; i++) {
            for (int j = 0; j < n - k; j++) {
                // vertical part: columns [j , j+k] on row i
                int verticalPart = data.upBonusAcc[i][j + k]
                        - (j > 0 ? data.upBonusAcc[i][j - 1] : 0);

                // horizontal part: rows [i , i+k] on column j
                int horizontalPart = data.leftBonusAcc[i + k][j]
                        - (i > 0 ? data.leftBonusAcc[i - 1][j] : 0);

                int total = verticalPart + horizontalPart;
                if (total > best) {
                    best = total;
                }
            }
        }
        return best;
    }

    /** Counts rows/columns that contain no 'B' at all (the “initial” value). */
    private static int countEmptyLines(GridData data, int n) {
        int count = 0;
        // last column of each row indicates whether the whole row is empty
        for (int row = 0; row < n; row++) {
            if (data.horizontal[row][n - 1] == 0) {
                count++;
            }
        }
        // last row of each column indicates whether the whole column is empty
        for (int col = 0; col < n; col++) {
            if (data.vertical[n - 1][col] == 0) {
                count++;
            }
        }
        return count;
    }

    /** Simple DTOs – keep the original code's intent but with clearer names. */
    private static final class GridData {
        final int[][] vertical;   // column‑wise cumulative 'B' count
        final int[][] horizontal; // row‑wise cumulative 'B' count

        GridData(int[][] vertical, int[][] horizontal) {
            this.vertical = vertical;
            this.horizontal = horizontal;
        }
    }

    /** Holds the intermediate structures needed for the final computation. */
    private static final class BonusData {
        final int[][] upBonus;
        final int[][] leftBonus;
        final int[][] upBonusAcc;
        final int[][] leftBonusAcc;

        BonusData(int[][] upBonus, int[][] leftBonus,
                  int[][] upBonusAcc, int[][] leftBonusAcc) {
            this.upBonus = upBonus;
            this.leftBonus = leftBonus;
            this.upBonusAcc = upBonusAcc;
            this.leftBonusAcc = leftBonusAcc;
        }
    }

    /** Container for the final answer that is printed to stdout. */
    private static final class Result {
        final int value;

        Result(int value) {
            this.value = value;
        }
    }
}

import java.io.IOException;
import java.io.InputStream;
import java.io.Writer;
import java.io.OutputStreamWriter;
import java.io.OutputStream;

/**
 * Entry point of the program.
 * <p>
 * The program reads an integer grid (size {@code n × n}) consisting of the
 * characters {@code 'B'}/{@code 'W'} (black/white).  
 * Two kinds of operations are allowed:
 * <ul>
 *   <li>paint a horizontal/vertical segment of length {@code k}
 *       (the segment may be placed only on rows or columns that fully
 *       contain black cells);
 *   <li>paint the whole board.
 * </ul>
 * The goal is to maximise the number of squares that can be coloured
 * black by a single operation.  The solution uses a 2‑D difference array
 * to count, for every possible placement of the segment, how many black
 * cells would be covered and finally extracts the maximum value.
 *
 * @author  (refactored by AI)
 */
public final class Main {

    /** Program entry point. */
    public static void main(String[] args) throws IOException {
        // Use a try‑with‑resources block so the output buffer is flushed
        // automatically even when an exception occurs.
        try (FastOutput out = new FastOutput(new OutputStreamWriter(System.out))) {
            new Solver().solve(out);
        }
    }

    /**
     * Core logic of the problem.
     * <p>
     * All I/O is performed through the supplied {@link FastInput}/{@link FastOutput}
     * streams.  The method never returns; it throws {@link IOException} only
     * when the underlying stream fails.
     */
    private static final class Solver {

        /** Size of the board – filled after reading the first token. */
        private int n;
        /** Length of the segment that can be painted. */
        private int k;

        /** Solve one test case and write the answer to the supplied output. */
        void solve(FastOutput out) throws IOException {
            // -----------------------------------------------------------------
            // 1️⃣  Input
            // -----------------------------------------------------------------
            try (FastInput in = new FastInput(System.in)) {
                n = in.readInt();   // board dimension
                k = in.readInt();   // segment length
                in.readLine();      // consume the rest of the line (blank)

                // Read the whole board into a 1‑based char matrix.
                char[][] board = new char[n + 1][n + 1];
                for (int i = 1; i <= n; i++) {
                    String row = in.readLine();
                    for (int j = 1; j <= n; j++) {
                        board[i][j] = row.charAt(j - 1);
                    }
                }

                // -----------------------------------------------------------------
                // 2️⃣  Difference array that will hold counts for every placement
                // -----------------------------------------------------------------
                // Extra padding (n+2) avoids many boundary checks.
                int[][] diff = new int[n + 2][n + 2];

                // -----------------------------------------------------------------
                // 3️⃣  Process rows – find contiguous black cells in each row
                // -----------------------------------------------------------------
                for (int row = 1; row <= n; row++) {
                    int firstCol = n + 1;   // leftmost black cell in this row
                    int lastCol  = 0;       // rightmost black cell in this row

                    for (int col = 1; col <= n; col++) {
                        if (board[row][col] == 'B') {
                            firstCol = Math.min(firstCol, col);
                            lastCol  = Math.max(lastCol, col);
                        }
                    }

                    // No black cells in the row → the whole board is a valid placement.
                    if (firstCol > lastCol) {
                        diff[1][1]++;          // +1 for the whole board
                        continue;
                    }

                    // The segment of length k must start at a column where it
                    // completely covers the black cells of the row.
                    int xStart = Math.max(1, firstCol - k + 1);
                    int xEnd   = Math.min(lastCol, n - k + 1);

                    // Valid start columns form an interval; we add +1 to every
                    // possible placement using the 2‑D difference technique.
                    placeRectangle(diff, xStart, xEnd, row - k + 1, row);
                }

                // -----------------------------------------------------------------
                // 4️⃣  Process columns – analogous to the row processing
                // -----------------------------------------------------------------
                for (int col = 1; col <= n; col++) {
                    int firstRow = n + 1;
                    int lastRow  = 0;

                    for (int row = 1; row <= n; row++) {
                        if (board[row][col] == 'B') {
                            firstRow = Math.min(firstRow, row);
                            lastRow  = Math.max(lastRow, row);
                        }
                    }

                    if (firstRow > lastRow) {
                        // Already counted when processing rows; still add to keep
                        // the semantics identical to the original code.
                        diff[1][1]++;
                        continue;
                    }

                    // The segment of length k must start at a row where it covers
                    // all black cells of this column.
                    int yStart = Math.max(1, firstRow - k + 1);
                    int yEnd   = Math.min(lastRow, n - k + 1);
                    placeRectangle(diff, col - k + 1, col, yStart, yEnd);
                }

                // -----------------------------------------------------------------
                // 5️⃣  Build prefix sums → actual counts for each placement
                // -----------------------------------------------------------------
                for (int i = 1; i <= n; i++) {
                    for (int j = 1; j <= n; j++) {
                        diff[i][j] += diff[i - 1][j] + diff[i][j - 1] - diff[i - 1][j - 1];
                    }
                }

                // -----------------------------------------------------------------
                // 6️⃣  Find the maximum count → answer
                // -----------------------------------------------------------------
                int answer = 0;
                for (int i = 1; i <= n; i++) {
                    for (int j = 1; j <= n; j++) {
                        answer = Math.max(answer, diff[i][j]);
                    }
                }

                out.println(answer);
            }
        }

        /**
         * Adds +1 to every cell of the rectangle
         * {@code [xStart … xEnd] × [yStart … yEnd]} in the difference array.
         * The rectangle coordinates are automatically clamped to the range
         * {@code [1, n]} and the operation becomes a no‑op if the rectangle
         * is empty after clamping.
         *
         * @param diff  the difference array (size (n+2)×(n+2))
         * @param x1    start column (inclusive)
         * @param x2    end   column (inclusive)
         * @param y1    start row    (inclusive)
         * @param y2    end   row    (inclusive)
         */
        private void placeRectangle(int[][] diff, int x1, int x2, int y1, int y2) {
            // Clamp to the valid board area.
            x1 = Math.max(1, Math.min(x1, n));
            x2 = Math.max(1, Math.min(x2, n));
            y1 = Math.max(1, Math.min(y1, n));
            y2 = Math.max(1, Math.min(y2, n));

            if (x1 > x2 || y1 > y2) {
                return;   // nothing to add
            }

            // Increment the (y1, x1) corner and adjust the three neighbours.
            diff[y1][x1] += 1;
            if (y2 + 1 <= n) {
                diff[y2 + 1][x1] -= 1;
            }
            if (x2 + 1 <= n) {
                diff[y1][x2 + 1] -= 1;
            }
            if (x2 + 1 <= n && y2 + 1 <= n) {
                diff[y2 + 1][x2 + 1] += 1;
            }
        }
    }

    /** Fast input utilities – wraps a {@link InputStream}. */
    private static final class FastInput {
        private final InputStream source;
        private final byte[] buffer = new byte[1 << 20];
        private int bufLen = 0, bufPos = 0;

        FastInput(InputStream source) {
            this.source = source;
        }

        /** Reads a single byte from the underlying stream, handling buffering. */
        private int readByte() {
            if (bufPos >= bufLen) {
                bufPos = 0;
                bufLen = source.read(buffer);
                if (bufLen == -1) {
                    return -1;
                }
            }
            return buffer[bufPos++];
        }

        /** Skips whitespace characters (space, newline, tab, carriage‑return). */
        private void skipWhitespace() {
            int b;
            while ((b = readByte()) >= 0 && (b == ' ' || b == '\n' || b == '\r' || b == '\t')) {
                // consume
            }
            // The read character (or EOF) stays available for the next read.
        }

        /** Reads a signed integer from the input stream. */
        int readInt() {
            skipWhitespace();
            int sign = 1;
            int c = readByte();
            if (c == '-') {
                sign = -1;
                c = readByte();
            } else if (c == '+') {
                c = readByte();
            }

            int value = 0;
            while (c >= '0' && c <= '9') {
                value = value * 10 + (c - '0');
                c = readByte();
            }
            return sign * value;
        }

        /** Reads the next non‑whitespace character. */
        char readChar() {
            skipWhitespace();
            int c = readByte();
            return (char) c;
        }

        /** Reads the rest of the current line (used to consume the blank line after the grid). */
        String readLine() throws IOException {
            StringBuilder sb = new StringBuilder();
            int c;
            while ((c = readByte()) != -1 && c != '\n') {
                sb.append((char) c);
            }
            return sb.toString();
        }
    }

    /** Fast output utilities that implement {@link AutoCloseable}. */
    private static final class FastOutput implements AutoCloseable {
        private final StringBuilder buffer = new StringBuilder(1 << 20);
        private final Writer writer;

        FastOutput(Writer writer) {
            this.writer = writer;
        }

        /** Appends an arbitrary {@link CharSequence} to the internal buffer. */
        FastOutput append(CharSequence csq) {
            buffer.append(csq);
            return this;
        }

        /** Appends an integer followed by a line separator. */
        FastOutput println(int value) {
            append(Integer.toString(value));
            append(System.lineSeparator());
            return this;
        }

        /** Appends a raw line separator. */
        FastOutput println() {
            append(System.lineSeparator());
            return this;
        }

        /** Flushes the buffer to the underlying writer and releases the writer. */
        @Override
        public void close() {
            try {
                writer.append(buffer);
                writer.flush();
            } catch (IOException e) {
                throw new UncheckedIOException(e);
            }
        }
    }
}

/*  --------------------------------------------------------------
 *  CP – competitive‑programming driver
 *  --------------------------------------------------------------
 *  The program reads an N×N board containing cells marked 'B' (black)
 *  and '.' (white).  For every possible K×K window that can contain
 *  all black cells of a given row or column it marks the set of
 *  positions where such a window can be placed.  Afterwards a 2‑D
 *  prefix‑sum over those marks yields the number of rows/columns that
 *  would be satisfied for each (i , j) position.  The maximum value of
 *  that prefix‑sum is the answer.
 *
 *  The refactor focuses on readability, proper naming, small helper
 *  methods, and deterministic resource handling while preserving the
 *  original algorithmic behaviour.
 */

/* --------------------------------------------------------------
 *  Entry point
 * -------------------------------------------------------------- */
public class CP {

    public static void main(String[] args) throws Exception {
        new Solver().solve();
    }
}

/* --------------------------------------------------------------
 *  Solver – core logic
 * -------------------------------------------------------------- */
class Solver {

    /* Fast input / output helpers (replaces the original IO class) */
    private final FastScanner scanner;
    private final FastPrinter printer;

    /* Board state */
    private int n;                 // board dimension
    private int k;                 // window size
    private boolean[][] board;     // true = black cell ('B')
    private int[][] diff;          // 2‑D difference array used for coverage

    Solver(FastScanner scanner, FastPrinter printer) {
        this.scanner = scanner;
        this.printer = printer;
    }

    /** Main entry point required by the original solution. */
    void solve() throws Exception {
        readInput();
        computeCoverage();
        long answer = findMaximumCoverage();
        printer.println(answer);
        printer.flush();
    }

    /** Parses input according to the original format. */
    private void readInput() {
        n = scanner.nextInt();
        k = scanner.nextInt();
        board = new boolean[n][n];

        for (int i = 0; i < n; i++) {
            String row = scanner.next();
            for (int j = 0; j < n; j++) {
                board[i][j] = row.charAt(j) == 'B';
            }
        }
        diff = new int[n][n];
    }

    /** Builds the coverage information and transforms it into a prefix sum. */
    private void computeCoverage() {
        // ---- rows -------------------------------------------------
        for (int row = 0; row < n; row++) {
            processRow(row);
        }

        // ---- columns ----------------------------------------------
        for (int col = 0; col < n; col++) {
            processColumn(col);
        }

        // Convert the difference array to a real prefix‑sum array
        for (int i = 0; i < n; i++) {
            for (int j = 1; j < n; j++) {
                diff[i][j] += diff[i][j - 1];
            }
        }
        for (int i = 1; i < n; i++) {
            for (int j = 0; j < n; j++) {
                diff[i][j] += diff[i - 1][j];
            }
        }
    }

    /** Handles the black‑cell information for a single board row. */
    private void processRow(int row) {
        int min = n + 7, max = -1;
        boolean any = false;

        for (int col = 0; col < n; col++) {
            if (board[row][col]) {
                any = true;
                min = Math.min(min, col);
                max = Math.max(max, col);
            }
        }

        if (!any) {                         // no black cell → cover everything
            incrementCoverage(0, 0, n - 1, n - 1);
        } else if (max - min < k) {         // a K‑wide horizontal window fits
            int top = row - k + 1;
            int left = max - k + 1;
            incrementCoverage(top, left, row, min);
        }
    }

    /** Handles the black‑cell information for a single board column. */
    private void processColumn(int col) {
        int min = n + 7, max = -1;
        boolean any = false;

        for (int row = 0; row < n; row++) {
            if (board[row][col]) {
                any = true;
                min = Math.min(min, row);
                max = Math.max(max, row);
            }
        }

        if (!any) {
            incrementCoverage(0, 0, n - 1, n - 1);
        } else if (max - min < k) {
            int top = max - k + 1;
            int left = col - k + 1;
            incrementCoverage(top, left, min, col);
        }
    }

    /**
     * Updates the 2‑D difference array for the rectangle
     * <code>(topRow, leftCol) … (bottomRow, rightCol)</code>.
     * The coordinates are automatically clamped to the board limits.
     */
    private void incrementCoverage(int topRow, int leftCol,
                                   int bottomRow, int rightCol) {
        // Clamp to valid indices
        topRow     = Math.max(topRow, 0);
        bottomRow  = Math.min(bottomRow, n - 1);
        leftCol    = Math.max(leftCol, 0);
        rightCol   = Math.min(rightCol, n - 1);

        // Standard 2‑D difference‑array update
        diff[topRow][leftCol]++;

        if (bottomRow + 1 < n && rightCol + 1 < n) {
            diff[bottomRow + 1][rightCol + 1]--;
        }
        if (bottomRow + 1 < n) {
            diff[bottomRow + 1][leftCol]--;
        }
        if (rightCol + 1 < n) {
            diff[topRow][rightCol + 1]--;
        }
    }

    /** Finds and returns the maximum value stored in the prefix‑sum array. */
    private long findMaximumCoverage() {
        long max = 0;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                max = Math.max(max, diff[i][j]);
            }
        }
        return max;
    }
}

/* --------------------------------------------------------------
 *  FastScanner – lightweight, high‑performance input reader
 * -------------------------------------------------------------- */
class FastScanner {

    private final InputStream stream;
    private final byte[] buffer;
    private int pointer = 0, length = 0;

    static final int DEFAULT_BUFFER_SIZE = 2048;

    FastScanner(InputStream stream) {
        this.stream = stream;
        buffer = new byte[DEFAULT_BUFFER_SIZE];
    }

    private int readByte() throws IOException {
        if (pointer >= length) {
            length = stream.read(buffer);
            pointer = 0;
            if (length <= 0) {
                return -1;
            }
        }
        return buffer[pointer++];
    }

    int nextInt() throws IOException {
        int c, sign = 1, val = 0;

        // skip whitespace
        do {
            c = readByte();
        } while (c <= ' ' && c != -1);

        if (c == '-') {
            sign = -1;
            c = readByte();
        }

        for (; c >= '0' && c <= '9'; c = readByte()) {
            val = val * 10 + (c - '0');
        }
        return val * sign;
    }

    String next() throws IOException {
        int c;
        // skip whitespace
        do {
            c = readByte();
        } while (c <= ' ' && c != -1);

        StringBuilder sb = new StringBuilder();
        while (c > ' ') {
            sb.append((char) c);
            c = readByte();
        }
        return sb.toString();
    }

    long nextLong() throws IOException {
        return nextInt();
    }
}

/* --------------------------------------------------------------
 *  FastPrinter – thin wrapper around BufferedWriter
 * -------------------------------------------------------------- */
class FastPrinter {

    private final BufferedWriter bw;

    FastPrinter(OutputStream out) {
        this.bw = new BufferedWriter(new OutputStreamWriter(out));
    }

    void println(long value) throws IOException {
        bw.write(Long.toString(value));
        bw.newLine();
    }

    void flush() throws IOException {
        bw.flush();
    }
}

import java.util.Scanner;

/**
 * Refactored version of the original “Rough” program.
 *
 * <p>All static fields have been renamed to expressive names,
 * duplicated code has been extracted into small helper methods,
 * and the {@code Pair} class has been turned into an immutable record.
 * The algorithmic behaviour is identical to the original implementation,
 * but the source code is now easier to read, test and extend.
 */
public class Rough {

    /* --------------------------------------------------------------------- */
    /*  Simple immutable container for “first” and “last” indices of a 'B'   */
    /* --------------------------------------------------------------------- */
    private static final class Pair {
        final int first;   // start index of the only 'B' in a row/column
        final int last;    // end   index of the only 'B' in a row/column

        Pair(int first, int last) {
            this.first = first;
            this.last = last;
        }

        @Override
        public String toString() {
            return first + " " + last;
        }
    }

    /* --------------------------------------------------------------------- */
    /*  Program‑wide data (kept static only because the original code used it) */
    /* --------------------------------------------------------------------- */
    private static int n;                 // board dimension
    private static int k;                 // window side length
    private static char[][] grid;         // input board
    private static boolean[] rowHasNoB;   // true if a row contains no 'B'
    private static boolean[] colHasNoB;   // true if a column contains no 'B'
    private static Pair[] firstBInRow;    // first column that holds a 'B' per row
    private static Pair[] lastBInRow;     // last  column that holds a 'B' per row
    private static Pair[] firstBInCol;    // first row    that holds a 'B' per column
    private static Pair[] lastBInCol;     // last  row    that holds a 'B' per column

    /* --------------------------------------------------------------------- */
    /*  Entry point                                                          */
    /* --------------------------------------------------------------------- */
    public static void main(String[] args) {
        try (Scanner sc = new Scanner(System.in)) {
            readInput(sc);
            if (k >= n) {
                System.out.println(2 * n);
                return;
            }

            buildRowColumnInformation();
            int[][] colCoverage   = computeColumnCoverageMatrix();
            int[][] rowCoverage   = computeRowCoverageMatrix();

            int answer = findMaximum(colCoverage, rowCoverage);
            System.out.println(answer);
        }
    }

    /* --------------------------------------------------------------------- */
    /*  Input handling                                                       */
    /* --------------------------------------------------------------------- */
    private static void readInput(Scanner sc) {
        n = sc.nextInt();
        k = sc.nextInt();
        grid = new char[n][];
        for (int i = 0; i < n; i++) {
            String line = sc.next();
            grid[i] = line.toCharArray();
        }
    }

    /* --------------------------------------------------------------------- */
    /*  Build the auxiliary data structures that describe where 'B' lives    */
    /* --------------------------------------------------------------------- */
    private static void buildRowColumnInformation() {
        rowHasNoB   = new boolean[n];
        colHasNoB   = new boolean[n];
        firstBInRow = new Pair[n];
        lastBInRow  = new Pair[n];
        firstBInCol = new Pair[n];
        lastBInCol  = new Pair[n];

        // ----- rows -----
        for (int r = 0; r < n; r++) {
            boolean hasB = false;
            int first = -1, last = -1;
            for (int c = 0; c < n; c++) {
                if (grid[r][c] == 'B') {
                    hasB = true;
                    if (first == -1) {
                        first = c;
                    }
                    last = c;
                }
            }
            rowHasNoB[r] = !hasB;
            Pair pair = hasB ? new Pair(first, last) : null;
            firstBInRow[r] = pair;
            lastBInRow[r]  = pair;
        }

        // ----- columns -----
        for (int c = 0; c < n; c++) {
            boolean hasB = false;
            int first = -1, last = -1;
            for (int r = 0; r < n; r++) {
                if (grid[r][c] == 'B') {
                    hasB = true;
                    if (first == -1) {
                        first = r;
                    }
                    last = r;
                }
            }
            colHasNoB[c] = !hasB;
            Pair pair = hasB ? new Pair(first, last) : null;
            firstBInCol[c] = pair;
            lastBInCol[c]  = pair;
        }
    }

    /* --------------------------------------------------------------------- */
    /*  Matrices that store the sliding‑window counts (originally named       */
    /*  kitna_col_khali / kitna_row_khali)                                   */
    /* --------------------------------------------------------------------- */
    private static int[][] computeColumnCoverageMatrix() {
        int[][] matrix = new int[n][n];
        int current = computeInitialColumnCount();
        matrix[0][0] = current;
        slideColumnWindow(matrix, current);
        return matrix;
    }

    private static int computeInitialColumnCount() {
        int cnt = 0;
        // rows that are completely empty up to column k‑1
        for (int i = 0; i < k; i++) {
            if (rowHasNoB[i] || (firstBInRow[i] != null && lastBInRow[i].first < k)) {
                cnt++;
            }
        }
        // rows that are empty after column k‑1
        for (int i = k; i < n; i++) {
            if (rowHasNoB[i]) {
                cnt++;
            }
        }
        return cnt;
    }

    private static void slideColumnWindow(int[][] matrix, int startCount) {
        int cnt = startCount;
        for (int i = 0; i <= n - k; i++) {
            int original = cnt;
            for (int j = 0; j < n - k; j++) {
                cnt = shiftColumnWindowRight(cnt, i, j, matrix);
            }
            if (i < n - k) {
                cnt = shiftColumnWindowDown(cnt, i, 0, original, matrix);
            }
        }
    }

    /** Shift the window one column to the right and store the new count. */
    private static int shiftColumnWindowRight(int current, int row, int col, int[][] matrix) {
        // a row that was previously “covered” may become uncovered
        if (!rowHasNoB[row] && firstBInRow[row] != null
                && firstBInRow[row].first >= col && lastBInRow[row].last < col + k) {
            current--;
        }
        // a row that leaves the window may become covered again
        if (!rowHasNoB[row + k] && firstBInRow[row + k] != null
                && firstBInRow[row + k].first >= col && lastBInRow[row + k].last < col + k) {
            current++;
        }
        matrix[row + 1][col] = current;
        return current;
    }

    /** Shift the window one row downward and store the new count. */
    private static int shiftColumnWindowDown(int current, int row, int col,
                                             int original, int[][] matrix) {
        for (int p = 0; p < k; p++) {
            if (!colHasNoB[p] && firstBInCol[p] != null
                    && firstBInCol[p].first >= row && lastBInCol[p].last < row + k) {
                current--;
            }
            if (!colHasNoB[p] && firstBInCol[p] != null
                    && firstBInCol[p].first > row && lastBInCol[p].last <= row + k) {
                current++;
            }
        }
        matrix[row + 1][col] = current;
        return current;
    }

    private static int[][] computeRowCoverageMatrix() {
        int[][] matrix = new int[n][n];
        int current = computeInitialRowCount();
        matrix[0][0] = current;
        slideRowWindow(matrix, current);
        return matrix;
    }

    private static int computeInitialRowCount() {
        int cnt = 0;
        for (int i = 0; i < k; i++) {
            if (colHasNoB[i] || (firstBInCol[i] != null && lastBInCol[i].first < k)) {
                cnt++;
            }
        }
        for (int i = k; i < n; i++) {
            if (colHasNoB[i]) {
                cnt++;
            }
        }
        return cnt;
    }

    private static void slideRowWindow(int[][] matrix, int startCount) {
        int cnt = startCount;
        for (int j = 0; j <= n - k; j++) {
            int original = cnt;
            for (int i = 0; i < n - k; i++) {
                cnt = shiftRowWindowDown(cnt, i, j, matrix);
            }
            if (j < n - k) {
                cnt = shiftRowWindowRight(cnt, 0, j, original, matrix);
            }
        }
    }

    /** Shift the window one row downward and store the new count (row‑wise). */
    private static int shiftRowWindowDown(int current, int row, int col,
                                          int[][] matrix) {
        for (int p = 0; p < k; p++) {
            if (!colHasNoB[p] && firstBInCol[p] != null
                    && firstBInCol[p].first >= row && lastBInCol[p].last < row + k) {
                current--;
            }
            if (!colHasNoB[p] && firstBInCol[p] != null
                    && firstBInCol[p].first > row && lastBInCol[p].last <= row + k) {
                current++;
            }
        }
        matrix[row][col + 1] = current;
        return current;
    }

    /** Shift the window one column to the right and store the new count (row‑wise). */
    private static int shiftRowWindowRight(int current, int row, int col,
                                           int original, int[][] matrix) {
        for (int p = row; p < row + k; p++) {
            if (!rowHasNoB[p] && firstBInRow[p] != null
                    && firstBInRow[p].first >= col && lastBInRow[p].last < col + k) {
                current--;
            }
            if (!rowHasNoB[p] && firstBInRow[p] != null
                    && firstBInRow[p].first > col && lastBInRow[p].last <= col + k) {
                current++;
            }
        }
        matrix[row][col + 1] = current;
        return current;
    }

    /* --------------------------------------------------------------------- */
    /*  Determine the answer – maximal sum of the two coverage matrices      */
    /* --------------------------------------------------------------------- */
    private static int findMaximum(int[][] colMatrix, int[][] rowMatrix) {
        int best = 0;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                best = Math.max(best, colMatrix[i][j] + rowMatrix[i][j]);
            }
        }
        return best;
    }
}

import java.io.*;
import java.util.*;

/**
 * Refactored solution for Codeforces problem 1200D.
 *
 * The program reads an n × n grid consisting of 'B' (black) and '.' (white) cells.
 * It finds the maximum number of cells that can be covered by placing a k × k
 * square on the grid (the square may be placed only on white cells) and adds the
 * number of completely empty rows and columns.
 *
 * The refactoring improves readability, separates concerns, uses meaningful
 * identifiers and removes duplicated logic.
 */
public class CF_1200D {

    /* --------------------------------------------------------------------- */
    /*  Constants & I/O helpers                                               */
    /* --------------------------------------------------------------------- */
    private static final String INPUT_NAME = "CF_1200D";
    private static final String INPUT_FILE = INPUT_NAME + ".in";
    private static final String OUTPUT_FILE = INPUT_NAME + ".out";

    /* --------------------------------------------------------------------- */
    /*  Core solving class                                                     */
    /* --------------------------------------------------------------------- */
    private static class Solver {
        private final int n;
        private final int k;
        private final boolean[][] grid;
        private final int emptyRowsAndColumns;

        Solver(BufferedScanner scanner) throws IOException {
            n = scanner.nextInt();
            k = scanner.nextInt();

            grid = new boolean[n][n];
            for (int i = 0; i < n; i++) {
                String line = scanner.next();
                Arrays.fill(grid[i], false);
                for (int j = 0; j < n; j++) {
                    grid[i][j] = line.charAt(j) == 'B';
                }
            }

            emptyRowsAndColumns = countEmptyRowsAndColumns();
        }

        /** Counts rows and columns that contain no black cells. */
        private int countEmptyRowsAndColumns() {
            int empty = 0;

            // rows
            for (int i = 0; i < n; i++) {
                boolean hasBlack = false;
                for (int j = 0; j < n; j++) {
                    if (grid[i][j]) {
                        hasBlack = true;
                        break;
                    }
                }
                if (!hasBlack) empty++;
            }

            // columns
            for (int j = 0; j < n; j++) {
                boolean hasBlack = false;
                for (int i = 0; i < n; i++) {
                    if (grid[i][j]) {
                        hasBlack = true;
                        break;
                    }
                }
                if (!hasBlack) empty++;
            }
            return empty;
        }

        /** Main algorithm – returns the answer. */
        int solve() {
            /* --------------------------------------------------------------- */
            /*  1. Build a 2‑D difference array that records how many placements  */
            /*     cover each possible top‑left corner of a k × k square.       */
            /* --------------------------------------------------------------- */
            final int EXTRA = 2;                     // safety margin
            int diffSize = n + EXTRA;
            int[][] diff = new int[diffSize][diffSize];

            // Process rows – each row contributes a contiguous interval of columns.
            for (int row = 0; row < n; row++) {
                List<Integer> blackCols = collectBlackColumns(row);
                if (blackCols.isEmpty()) {
                    continue;                     // row has no black cells
                }
                int start = Math.max(0, blackCols.get(blackCols.size() - 1) - k + 1);
                int end   = blackCols.get(0);
                if (end < start) continue;        // impossible placement

                // Mark that rows [row, row + k) are covered for columns start … end
                diff[start][row]++;               // +1 at start of column interval
                diff[end + 1][row]--;               // -1 after the interval
                diff[start][row + k]--;
                diff[end + 1][row + k]++;
            }

            // Process columns – symmetric to rows.
            for (int col = 0; col < n; col++) {
                List<Integer> blackRows = collectBlackRows(col);
                if (blackRows.isEmpty()) continue;

                int start = Math.max(0, blackRows.get(blackRows.size() - 1) - k + 1);
                int end   = blackRows.get(0);
                if (end < start) continue;

                diff[start][col]++;
                diff[end + 1][col]--;
                diff[start][col + k]--;
                diff[end + 1][col + k]++;
            }

            /* --------------------------------------------------------------- */
            /*  2. Convert the difference array into prefix‑sum coverage counts. */
            /* --------------------------------------------------------------- */
            int[][] coverage = new int[diffSize][diffSize];
            for (int i = 0; i < diffSize - 1; i++) {
                for (int j = 0; j < diffSize - 1; j++) {
                    coverage[i + 1][j + 1] = coverage[i][j + 1]
                                            + coverage[i + 1][j]
                                            - coverage[i][j]
                                            + diff[i][j];
                }
            }

            /* --------------------------------------------------------------- */
            /*  3. Find the maximum coverage count.                             */
            /* --------------------------------------------------------------- */
            int maxCoverage = 0;
            for (int i = 0; i <= n; i++) {
                for (int j = 0; j <= n; j++) {
                    maxCoverage = Math.max(maxCoverage, coverage[i][j]);
                }
            }

            return maxCoverage + emptyRowsAndColumns;
        }

        /** Returns sorted column indices of black cells in the given row. */
        private List<Integer> collectBlackColumns(int row) {
            List<Integer> list = new ArrayList<>();
            for (int col = 0; col < n; col++) {
                if (grid[row][col]) list.add(col);
            }
            return list;
        }

        /** Returns sorted row indices of black cells in the given column. */
        private List<Integer> collectBlackRows(int col) {
            List<Integer> list = new ArrayList<>();
            for (int row = 0; row < n; row++) {
                if (grid[row][col]) list.add(row);
            }
            return list;
        }
    }

    /* --------------------------------------------------------------------- */
    /*  Minimal I/O wrappers (identical to the original solution)            */
    /* --------------------------------------------------------------------- */
    private static class BufferedScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 13];
        private int pos = 0, count = -1;

        BufferedScanner(InputStream in) {
            this.in = in;
        }

        private int read() throws IOException {
            if (count <= 0) {
                pos = 0;
                count = in.read(buffer);
                if (count <= 0) return -1;
            }
            return buffer[pos++];
        }

        private static boolean isSpace(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        private int readSkipSpace() throws IOException {
            int r;
            do {
                r = read();
            } while (isSpace(r));
            return r;
        }

        int nextInt() throws IOException {
            int sign = 1, c = readSkipSpace();
            if (c == '-') {
                sign = -1;
                c = read();
            }
            int value = 0;
            do {
                value = value * 10 + (c - '0');
                c = read();
            } while (!isSpace(c));
            return sign * value;
        }

        String next() throws IOException {
            StringBuilder sb = new StringBuilder();
            int c = readSkipSpace();
            do {
                sb.append((char) c);
                c = read();
            } while (!isSpace(c));
            return sb.toString();
        }

        void close() throws IOException {
            in.close();
        }
    }

    private static class BufferedPrinter {
        private final PrintWriter out;

        BufferedPrinter(OutputStream out) {
            this.out = new PrintWriter(new BufferedWriter(new OutputStreamWriter(out)));
        }

        void print(Object... objs) {
            for (int i = 0; i < objs.length; i++) {
                if (i != 0) out.print(' ');
                out.print(objs[i]);
            }
        }

        void println(Object... objs) {
            print(objs);
            out.println();
        }

        void close() {
            out.close();
        }
    }

    /* --------------------------------------------------------------------- */
    /*  Entry point                                                          */
    /* --------------------------------------------------------------------- */
    public static void main(String[] args) throws Exception {
        boolean useFile = new File(INPUT_FILE).exists();
        try (BufferedScanner in = new BufferedScanner(
                useFile ? new FileInputStream(INPUT_FILE) : System.in);
             BufferedPrinter out = new BufferedPrinter(
                    useFile ? new FileOutputStream(INPUT_FILE + ".out") : System.out)) {
            Solver solver = new Solver(in);
            out.println(solver.solve());
        }
    }
}

package com.example.solver;

import java.io.IOException;
import java.io.LineNumberReader;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;

/**
 * Solves the “window‑placement” problem.
 *
 * <p>Given an n×n binary matrix (characters 'B' or '.'), the program:
 * <ul>
 *   <li>counts rows and columns that contain no 'B' (they are “empty” and add 1 to the answer each),</li>
 *   <li>collects all possible positions of a k×k window that can cover a missing cell,
 *       adjusting them to stay inside the grid,</li>
 *   <li>uses a 2‑D difference array to efficiently count how many windows cover each cell,</li>
 *   <li>prints the maximum number of covered cells together with the number of empty rows/columns.</li>
 * </ul>
 *
 * <p>The refactor aims for readability, clear naming, and separation of concerns.
 */
public class Solver {

    /** Size of the square matrix. */
    private static final int SIZE = "n";

    /** Length of the sliding window that must be placed. */
    private static final int WINDOW = "k";

    /** Simple container for a candidate window placement. */
    private static final class Placement {
        /** Upper‑left corner (row, column) of the window in the original coordinate system. */
        final int rowStart;
        /** Lower‑right corner (row, column) of the window (exclusive). */
        final int rowEnd;
        /** Upper‑left column of the window (inclusive). */
        final int colStart;
        /** Lower‑right column (exclusive). */
        final int colEnd;

        Placement(int rowStart, int rowEnd, int colStart, int colEnd) {
            this.rowStart = rowStart;
            this.rowEnd = rowEnd;
            this.colStart = colStart;
            this.colEnd = colEnd;
        }
    }

    public static void main(String[] args) throws IOException {
        /* -------------------------------------------------------
         *  Input handling – try‑with‑resources makes sure the Scanner
         *  is closed automatically.
         * ------------------------------------------------------- */
        try (Scanner scanner = new Scanner(System.in)) {
            int n = scanner.nextInt();               // matrix dimension
            int windowSize = scanner.nextInt();      // size of the k×k window

            // Read matrix rows as strings; each character represents a cell.
            boolean[][] grid = new boolean[n][n];
            for (int row = 0; row < n; row++) {
                String line = scanner.next();
                for (int col = 0; col < n; col++) {
                    grid[row][col] = (line.charAt(col) == 'B');
                }
            }

            // ---------------------------------------------------
            //  1️⃣  Count empty rows / columns
            // ---------------------------------------------------
            int emptyRowsOrColumns = countEmptyRowsOrColumns(grid, n);

            // ---------------------------------------------------
            //  2️⃣  Find all valid placements for the window
            // ---------------------------------------------------
            List<Placement> placements = findValidPlacements(grid, n, windowSize);

            // ---------------------------------------------------
            //  3️⃣  Use a 2‑D difference array to evaluate coverage
            // ---------------------------------------------------
            int[][] diffArray = buildDifferenceArray(placements, n, windowSize);
            int maxCoverage = computeMaximumCoverage(diffArray, n);

            // ---------------------------------------------------
            //  4️⃣  Output result: maximum coverage + empty rows/cols
            // ---------------------------------------------------
            System.out.println(maxCoverage + emptyRowsOrColumns);
        }
    }

    /** Counts rows and columns that contain no 'B' (i.e. are completely empty). */
    private static int countEmptyRowsOrColumns(boolean[][] matrix, int size) {
        int empty = 0;

        // Rows
        for (int r = 0; r < size; r++) {
            boolean hasItem = false;
            for (int c = 0; c < size; c++) {
                if (matrix[r][c]) {
                    hasItem = true;
                    break;
                }
            }
            if (!hasItem) {
                empty++;
            }
        }

        // Columns
        for (int c = 0; c < size; c++) {
            boolean hasItem = false;
            for (int r = 0; r < size; r++) {
                if (matrix[r][c]) {
                    hasItem = true;
                    break;
                }
            }
            if (!hasItem) {
                empty++;
            }
        }
        return empty;
    }

    /** Returns a list of all placements where a k×k window can be placed covering at least one empty cell. */
    private static List<Placement> findValidPlacements(boolean[][] matrix, int size, int windowSize) {
        List<Placement> placements = new ArrayList<>();

        // ---- Rows -------------------------------------------------
        placements.addAll(findHorizontalPlacements(matrix, size, windowSize));

        // ---- Columns -----------------------------------------------
        placements.addAll(findVerticalPlacements(matrix, size, windowSize));

        return placements;
    }

    /** Scans each row for the leftmost and rightmost 'B' and evaluates possible vertical placements. */
    private static List<Placement> findHorizontalPlacements(boolean[][] matrix, int size, int windowSize) {
        List<Placement> result = new ArrayList<>();

        for (int row = 0; row < size; row++) {
            int left = -1;
            int right = size;
            for (int col = 0; col < size; col++) {
                if (matrix[row][col]) {
                    left = col;
                    break;
                }
            }
            for (int col = size - 1; col >= 0; col--) {
                if (matrix[row][col]) {
                    right = col;
                    break;
                }
            }

            // Empty row → nothing to place here.
            if (left == -1) {
                continue;
            }

            // If the distance between extremes is smaller than windowSize,
            // a vertical strip of height windowSize can be placed.
            if (right - left >= windowSize) {
                continue;
            }

            // Compute candidate window that covers columns [left, right].
            int top = row - windowSize + 1;
            int bottom = row;                      // exclusive when used with diff‑array
            int colStart = left - windowSize + 1;
            int colEnd = left + 1;                 // exclusive

            Placement p = adjustPlacementBounds(top, bottom, colStart, colEnd, size, windowSize);
            result.add(p);
        }
        return result;
    }

    /** Scans each column for the topmost and bottommost 'B' and evaluates possible horizontal placements. */
    private static List<Placement> findVerticalPlacements(boolean[][] matrix, int size, int windowSize) {
        List<Placement> result = new ArrayList<>();

        for (int col = 0; col < size; col++) {
            int top = -1;
            int bottom = size;
            for (int row = 0; row < size; row++) {
                if (matrix[row][col]) {
                    top = row;
                    break;
                }
            }
            for (int row = size - 1; row >= 0; row--) {
                if (matrix[row][col]) {
                    bottom = row;
                    break;
                }
            }

            if (top == -1) {
                continue;
            }

            if (bottom - top >= windowSize) {
                continue;
            }

            // Horizontal strip of size windowSize × windowSize covering rows [top, bottom].
            int left = col - windowSize + 1;
            int right = col;
            int rowStart = bottom - windowSize + 1;
            int rowEnd = bottom + 1; // exclusive

            Placement p = adjustPlacementBounds(rowStart, rowEnd, left, right, size, windowSize);
            result.add(p);
        }
        return result;
    }

    /**
     * Adjusts the raw placement coordinates so they stay inside the allowed
     * window‑position domain (0 ≤ rowStart ≤ size‑windowSize, same for columns).
     */
    private static Placement adjustPlacementBounds(
            int rawRowStart, int rawRowEnd,
            int rawColStart, int rawColEnd,
            int size, int windowSize) {

        int adjustedRowStart = Math.max(0, rawRowStart);
        int adjustedRowEnd   = Math.min(size - windowSize, rawRowEnd);
        int adjustedColStart = Math.max(0, rawColStart);
        int adjustedColEnd   = Math.min(size - windowSize, rawColEnd);
        return new Placement(adjustedRowStart, adjustedRowEnd,
                             adjustedColStart, adjustedColEnd);
    }

    /** Builds a 2‑D difference array from the list of placements. */
    private static int[][] buildDifferenceArray(List<Placement> placements, int size, int windowSize) {
        int[][] diff = new int[size + 1][size + 1];

        for (Placement p : placements) {
            // Each placement corresponds to a rectangle that contributes +1 to its area.
            diff[p.rowStart][p.colStart]++;                     // +1 at (r,c)
            diff[p.rowStart][p.colEnd]--;                        // -1 at (r,cEnd)
            diff[p.rowEnd][p.colStart]--;                        // -1 at (rEnd,c)
            diff[p.rowEnd][p.colEnd]++;                         // +1 at (rEnd,cEnd)
        }
        return diff;
    }

    /** Computes the maximum value reachable by a 2‑D prefix‑sum over the diff array. */
    private static int computeMaximumCoverage(int[][] diff, int size) {
        int max = 0;
        int[][] prefix = new int[size + 1][size + 1];

        for (int r = 0; r < size; r++) {
            for (int c = 0; c < size; c++) {
                prefix[r + 1][c + 1] = prefix[r + 1][c] + prefix[r][c + 1]
                                      - prefix[r][c] + diff[r][c];
                max = Math.max(max, prefix[r + 1][c + 1]);
            }
        }
        return max;
    }
}

import java.io.*;
import java.util.StringTokenizer;

/**
 * Entry point of the application.
 * Reads the input, processes the grid and prints the result.
 */
public class Main {

    public static void main(String[] args) {
        // Try‑with‑resources guarantees proper closing of readers/writers.
        try (
                FastReader reader = new FastReader();
                PrintWriter out = new PrintWriter(System.out)
        ) {
            // ----- 1️⃣  Input -------------------------------------------------
            int n = reader.nextInt();   // number of rows
            int m = reader.nextInt();   // number of columns
            int k = reader.nextInt();   // sub‑grid size parameter

            int[][] grid = readGrid(reader, n, m);

            // ----- 2️⃣  Prefix sums -------------------------------------------
            int[][] rowPrefix = computeRowPrefix(grid);
            int[][] colPrefix = computeColumnPrefix(grid);

            // ----- 3️⃣  Zero‑row / zero‑column statistics --------------------
            int[] rowZeroCount = computeRowZeroCounts(rowPrefix, n, m);
            int[] colZeroCount = computeColumnZeroCounts(colPrefix, n, m);

            // ----- 4️⃣  Answer computation ------------------------------------
            int[][] ans = computeAnswer(
                    grid,
                    rowPrefix,
                    colPrefix,
                    rowZeroCount,
                    colZeroCount,
                    k
            );

            // ----- 5️⃣  Result ------------------------------------------------
            int maximum = findMaximum(ans);
            out.println(maximum);
        }
    }

    /* --------------------------------------------------------------- */
    /*                     Private helper methods                      */
    /* --------------------------------------------------------------- */

    /**
     * Reads the character grid.
     *
     * @param reader input reader
     * @param rows   number of rows
     * @param cols   number of columns
     * @return       grid with 1 for 'B' and 0 otherwise, 1‑based indexing
     */
    private static int[][] readGrid(FastReader reader, int rows, int cols) {
        int[][] grid = new int[rows + 1][cols + 1];
        for (int i = 1; i <= rows; i++) {
            String line = reader.next();                 // one row of characters
            for (int j = 1; j <= cols; j++) {
                grid[i][j] = (line.charAt(j - 1) == 'B') ? 1 : 0;
            }
        }
        return grid;
    }

    /**
     * Computes a row‑wise prefix sum matrix.
     *
     * @param grid input grid
     * @return     prefix sums where rowPrefix[i][j] = sum of grid[i][1..j]
     */
    private static int[][] computeRowPrefix(int[][] grid) {
        int[][] prefix = new int[grid.length][grid[0].length];
        for (int i = 1; i < grid.length; i++) {
            prefix[i][0] = 0;
            for (int j = 1; j < grid[0].length; j++) {
                prefix[i][j] = grid[i][j] + prefix[i][j - 1];
            }
        }
        return prefix;
    }

    /**
     * Computes a column‑wise prefix sum matrix.
     *
     * @param grid input grid
     * @return     prefix sums where colPrefix[i][j] = sum of grid[1..i][j]
     */
    private static int[][] computeColumnPrefix(int[][] grid) {
        int rows = grid.length;
        int cols = grid[0].length;
        int[][] prefix = new int[rows][cols];
        for (int j = 1; j < cols; j++) {
            prefix[0][j] = 0;
            for (int i = 1; i < rows; i++) {
                prefix[i][j] = grid[i][j] + prefix[i - 1][j];
            }
        }
        return prefix;
    }

    /**
     * Counts how many rows contain only zeros.
     *
     * @param rowPrefix row‑wise prefix sums
     * @param rows      number of rows
     * @param cols      number of columns
     * @return         array where rowZeroCount[i] = number of zero‑rows up to i
     */
    private static int[] computeRowZeroCounts(int[][] rowPrefix, int rows, int cols) {
        int[] count = new int[rows + 1];
        count[0] = 0;
        for (int i = 1; i <= rows; i++) {
            int fullSum = rowPrefix[i][cols];
            count[i] = (fullSum == 0) ? count[i - 1] + 1 : count[i - 1];
        }
        return count;
    }

    /**
     * Counts how many columns contain only zeros.
     *
     * @param colPrefix column‑wise prefix sums
     * @param rows      number of rows
     * @param cols      number of columns
     * @return         array where colZeroCount[j] = number of zero‑columns up to j
     */
    private static int[] computeColumnZeroCounts(int[][] colPrefix, int rows, int cols) {
        int[] count = new int[cols + 1];
        count[0] = 0;
        for (int j = 1; j <= cols; j++) {
            int fullSum = colPrefix[rows][j];
            count[j] = (fullSum == 0) ? count[j - 1] + 1 : count[j - 1];
        }
        return count;
    }

    /**
     * Calculates the intermediate answer matrix using sliding windows.
     *
     * @param grid       original grid
     * @param rowPrefix  row prefix sums
     * @param colPrefix  column prefix sums
     * @param rowZeroCnt row‑zero statistics
     * @param colZeroCnt column‑zero statistics
     * @param k          sub‑grid size parameter
     * @return           matrix *ans* as defined in the original algorithm
     */
    private static int[][] computeAnswer(
            int[][] grid,
            int[][] rowPrefix,
            int[][] colPrefix,
            int[] rowZeroCnt,
            int[] colZeroCnt,
            int k
    ) {
        int n = grid.length - 1;   // rows (1‑based)
        int m = grid[0].length - 1; // columns (1‑based)

        int[][] colWhite = new int[n + 1][m + 1]; // cumulative white‑cell counts per column
        int[][] rowWhite = new int[n + 1][m + 1]; // cumulative white‑cell counts per row
        int[][] ans = new int[n + 1][m + 1];      // final answer matrix

        /* ---------- Horizontal sliding window ---------- */
        for (int startCol = 1; startCol <= m - k + 1; startCol++) {
            // Build column‑wise cumulative white‑cell information.
            for (int i = 1; i <= n; i++) {
                boolean isWhite = ((rowPrefix[i][m] - rowPrefix[i][startCol + k - 1])
                                + (rowPrefix[i][startCol - 1] - rowPrefix[i][0])) == 0;
                int whiteFlag = isWhite ? 1 : 0;
                colWhite[i][startCol] = whiteFlag + colWhite[i - 1][startCol];
            }
            // Fill the answer matrix for rows that fit inside the vertical window.
            for (int i = 1; i <= n - k + 1; i++) {
                ans[i][startCol] = colWhite[i + k - 1][startCol] - colWhite[i - 1][startCol]
                        + rowZeroCnt[n] - rowZeroCnt[i + k - 1]
                        + rowZeroCnt[i - 1] - rowZeroCnt[0];
            }
        }

        /* ---------- Vertical sliding window ---------- */
        for (int startRow = 1; startRow <= n - k + 1; startRow++) {
            // Build row‑wise cumulative white‑cell information.
            for (int j = 1; j <= m; j++) {
                boolean isWhite = ((colPrefix[n][j] - colPrefix[startRow + k - 1][j])
                                + (colPrefix[startRow - 1][j] - colPrefix[0][j])) == 0;
                int whiteFlag = isWhite ? 1 : 0;
                rowWhite[startRow][j] = whiteFlag + rowWhite[startRow][j - 1];
            }
            // Add horizontal contributions to already computed cells.
            for (int j = 1; j <= m - k + 1; j++) {
                ans[startRow][j] += (rowWhite[startRow][j + k - 1] - rowWhite[startRow][j - 1]
                        + colZeroCnt[m] - colZeroCnt[j + k - 1]
                        + colZeroCnt[j - 1] - colZeroCnt[0]);
            }
        }

        return ans;
    }

    /**
     * Finds the maximum value contained in a 2‑D integer matrix.
     *
     * @param matrix matrix to scan
     * @return     maximum value
     */
    private static int findMaximum(int[][] matrix) {
        int max = 0;
        for (int[] row : matrix) {
            for (int val : row) {
                if (val > max) {
                    max = val;
                }
            }
        }
        return max;
    }

    /* --------------------------------------------------------------- */
    /*                           Fast input reader                     */
    /* --------------------------------------------------------------- */

    /**
     * Simple fast scanner that works with {@link BufferedReader}.
     * Handles split tokens and re‑initialises on I/O errors.
     */
    static class FastReader {
        private final BufferedReader br;
        private StringTokenizer st;

        FastReader() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        /** Returns the next token, expanding the stream lazily. */
        String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    throw new UncheckedIOException(e);
                }
            }
            return st.nextToken();
        }

        /** Reads a whole line (may be empty). */
        String nextLine() {
            try {
                return br.readLine();
            } catch (IOException e) {
                throw new UncheckedIOException(e);
            }
        }

        /** Convenience wrapper for {@code Integer.parseInt}. */
        int nextInt() {
            return Integer.parseInt(next());
        }

        /** Convenience wrapper for {@code Long.parseLong}. */
        long nextLong() {
            return Long.parseLong(next());
        }
    }
}

import java.io.*;
import java.util.Scanner;

/**
 * Reads a square grid of 'B'/'W' characters, computes several
 * prefix‑sum based statistics and prints the final answer.
 *
 * The logic follows the original implementation but is now
 * organized into small, well‑named methods and uses meaningful
 * variable names, encapsulation and proper resource handling.
 */
public class GridProcessor {

    /** Input helper – a thin wrapper around {@link Scanner}. */
    private static final class InputReader implements AutoCloseable {
        private final Scanner scanner;

        InputReader() {
            this.scanner = new Scanner(new BufferedInputStream(System.in));
        }

        /** Reads the next token (String). */
        String next() {
            return scanner.next();
        }

        /** Reads the next integer. */
        int nextInt() {
            return scanner.nextInt();
        }

        /** Reads the next double. */
        double nextDouble() {
            return scanner.nextDouble();
        }

        /** Reads the next long. */
        long nextLong() {
            return scanner.nextLong();
        }

        /** Reads a whole line. */
        String nextLine() {
            return scanner.nextLine();
        }

        @Override
        public void close() {
            scanner.close();
        }
    }

    /** Constants – keep them in one place for easy tweaking. */
    private static final class Constants {
        private static final long serialVersionUID = 1L;
    }

    /** Prefix‑sum of the grid (1 = 'B', 0 = 'W'). */
    private static long[][] computePrefixSum(char[][] grid, int n) {
        long[][] pref = new long[n + 1][n + 1];
        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= n; j++) {
                int cellValue = grid[i - 1][j - 1] == 'B' ? 1 : 0;
                pref[i][j] = cellValue + pref[i - 1][j] + pref[i][j - 1] - pref[i - 1][j - 1];
            }
        }
        return pref;
    }

    /** Returns the sum of sub‑matrix (r1,c1) … (r2,c2) inclusive. */
    private static long subMatrixSum(long[][] pref, int r1, int c1, int r2, int c2) {
        r2 = Math.min(r2, pref.length - 1);
        c2 = Math.min(c2, pref.length - 1);
        return pref[r2][c2] - pref[r1 - 1][c2] - pref[r2][c1 - 1] + pref[r1 - 1][c1 - 1];
    }

    /** Counts rows that consist entirely of 'B' (sum equals n). */
    private static int countFullRows(long[][] pref, int n) {
        int count = 0;
        for (int i = 1; i <= n; i++) {
            if (subMatrixSum(pref, i, 1, i, n) == n) {
                ++count;
            }
        }
        return count;
    }

    /** Counts columns that consist entirely of 'B' (sum equals n). */
    private static int countFullCols(long[][] pref, int n) {
        int count = 0;
        for (int j = 1; j <= n; j++) {
            if (subMatrixSum(pref, 1, j, n, j) == n) {
                ++count;
            }
        }
        return count;
    }

    /** Fills a flag matrix that marks the start positions of a
     *  length‑k block covering the whole row (or column). */
    private static void fillRowFlags(long[][] flags, long[][] pref, int n, int k) {
        for (int i = 1; i <= n; i++) {
            long wholeRowSum = subMatrixSum(pref, i, 1, i, n);
            if (wholeRowSum == 0) {
                continue; // no 'B' at all in this row
            }
            for (int j = 1; j <= n; j++) {
                int endCol = Math.min(j + k - 1, n);
                long blockSum = subMatrixSum(pref, i, j, i, endCol);
                flags[i][j] = (blockSum == wholeRowSum) ? 1 : 0;
            }
        }
    }

    /** Fills a flag matrix that marks the start positions of a
     *  length‑k block covering the whole column. */
    private static void fillColFlags(long[][] flags, long[][] pref, int n, int k) {
        for (int j = 1; j <= n; j++) {
            long wholeColSum = subMatrixSum(pref, 1, j, n, j);
            if (wholeColSum == 0) {
                continue; // no 'B' at all in this column
            }
            for (int i = 1; i <= n; i++) {
                int endRow = Math.min(i + k - 1, n);
                long blockSum = subMatrixSum(pref, i, j, endRow, j);
                flags[i][j] = (blockSum == wholeColSum) ? 1 : 0;
            }
        }
    }

    /** Computes the prefix sums of the row‑ and column‑flag matrices. */
    private static void buildCumulativeSums(long[][] cumRow, long[][] rowFlags, int n) {
        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= n; j++) {
                cumRow[i][j] = cumRow[i - 1][j] + rowFlags[i][j];
            }
        }
    }

    private static void buildCumulativeSumsCol(long[][] cumCol, long[][] colFlags, int n) {
        for (int j = 1; j <= n; j++) {
            for (int i = 1; i <= n; i++) {
                cumCol[i][j] = cumCol[i][j - 1] + colFlags[i][j];
            }
        }
    }

    /** Finds the maximum value of (vertical‑window sum of rowFlags +
     *  horizontal‑window sum of colFlags) for a k×k sliding window. */
    private static long computeMaxWindowContribution(
            long[][] cumRow, long[][] cumCol, int n, int k) {

        long best = 0;
        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= n; j++) {
                int iEnd = Math.min(i + k - 1, n);
                int jEnd = Math.min(j + k - 1, n);

                long rowWindow = cumRow[iEnd][j] - cumRow[i - 1][j];
                long colWindow = cumCol[i][jEnd] - cumCol[i][j - 1];

                best = Math.max(best, rowWindow + colWindow);
            }
        }
        return best;
    }

    /** Entry point – orchestrates the whole computation. */
    public static void main(String[] args) {
        // -----------------------------------------------------------------
        // 1️⃣  Input handling
        // -----------------------------------------------------------------
        try (InputReader reader = new InputReader()) {
            int n = reader.nextInt();      // size of the grid (n × n)
            int k = reader.nextInt();      // length of the considered block

            // read the grid (n lines, each line is a string of length n)
            char[][] grid = new char[n][];
            for (int i = 0; i < n; i++) {
                String line = reader.nextLine().trim();
                grid[i] = line.toCharArray();
            }

            // -----------------------------------------------------------------
            // 2️⃣  Prefix‑sum preprocessing
            // -----------------------------------------------------------------
            long[][] prefix = computePrefixSum(grid, n);

            // -----------------------------------------------------------------
            // 3️⃣  Simple statistics: full rows / full columns of 'B'
            // -----------------------------------------------------------------
            int fullRows = countFullRows(prefix, n);
            int fullCols = countFullCols(prefix, n);

            // -----------------------------------------------------------------
            // 4️⃣  Flag matrices for “row‑block covers whole row” and
            //      “col‑block covers whole column”
            // -----------------------------------------------------------------
            long[][] rowFlag = new long[n + 1][n + 1];
            long[][] colFlag = new long[n + 1][n + 1];

            fillRowFlags(rowFlag, prefix, n, k);
            fillColFlags(colFlag, prefix, n, k);

            // -----------------------------------------------------------------
            // 5️⃣  Cumulative sums of the flag matrices
            // -----------------------------------------------------------------
            long[][] cumRow = new long[n + 1][n + 1];
            long[][] cumCol = new long[n + 1][n + 1];

            buildCumulativeSums(cumRow, rowFlag, n);
            buildCumulativeSumsCol(cumCol, colFlag, n);

            // -----------------------------------------------------------------
            // 6️⃣  Sliding‑window optimisation – maximal contribution of a
            //      k‑wide vertical/horizontal window
            // -----------------------------------------------------------------
            long maximized = computeMaxWindowContribution(cumRow, cumCol, n, k);

            // -----------------------------------------------------------------
            // 7️⃣  Final answer
            // -----------------------------------------------------------------
            long answer = fullRows + fullCols + maximized;
            System.out.print(answer);
        } catch (IOException e) {
            // In a contest environment this should never happen, but we keep
            // a safe fallback.
            throw new UncheckedIOException(e);
        }
    }
}

import java.io.*;
import java.util.*;

public class Task1200D {
    private static final InputReader IN = new InputReader(System.in);
    private static final PrintWriter OUT = new PrintWriter(System.out, true);

    public static void main(String[] args) {
        final int TEST_CASES = 1;               // problem guarantees a single test case
        for (int t = 0; t < TEST_CASES; t++) {
            solve();
        }
        OUT.flush();
    }

    private static void solve() {
        int n = IN.nextInt();                     // grid dimension
        int k = IN.nextInt();                     // size of the magical square
        char[][] grid = new char[n][];
        for (int i = 0; i < n; i++) {
            grid[i] = IN.next().toCharArray();    // read each row
        }

        /*-------------------------------------------------------------
         * 2‑D difference array that counts how many rows/columns become
         * completely white for every possible placement of the k×k block.
         *-------------------------------------------------------------*/
        int[][] diff = new int[n + 2][n + 2];       // extra padding for safety
        Arrays.fill(diff[0], 0);

        /*-------------------------------------------------------------
         * Process rows – each row may contribute a placement that
         * turns the whole row white.
         *-------------------------------------------------------------*/
        for (int row = 0; row < n; row++) {
            int left = firstNonWhite(grid[row]);
            int right = lastNonWhite(grid[row]);

            if (left == -1) {                     // row consists only of 'W'
                diff[0][0]++;
                continue;
            }
            if (right - left + 1 > k) {           // cannot be covered by a k‑wide segment
                continue;
            }

            int rowStart = Math.max(row - k + 1, 0);
            int rowEnd   = row + 1;
            int colStart = Math.max(right - k + 1, 0);
            int colEnd   = left + 1;

            apply(diff, rowStart, rowEnd, colStart, colEnd);
        }

        /*-------------------------------------------------------------
         * Process columns – symmetric to rows.
         *-------------------------------------------------------------*/
        for (int col = 0; col < n; col++) {
            int top = -1, bottom = -1;
            for (int row = 0; row < n; row++) {
                if (grid[row][col] != 'W') {
                    if (top == -1) top = row;
                    bottom = row;
                }
            }
            if (top == -1) {                     // column consists only of 'W'
                diff[0][0]++;
                continue;
            }
            if (bottom - top + 1 > k) {          // cannot be covered by a k‑wide segment
                continue;
            }

            int rowStart = Math.max(bottom - k + 1, 0);
            int rowEnd   = top + 1;
            int colStart = Math.max(col - k + 1, 0);
            int colEnd   = col + 1;

            apply(diff, rowStart, rowEnd, colStart, colEnd);
        }

        /*-------------------------------------------------------------
         * Build prefix sums on the difference array to obtain the
         * actual number of rows/columns that become white for each
         * (rowStart, colStart) placement.
         *-------------------------------------------------------------*/
        for (int i = 0; i <= n; i++) {
            for (int j = 0; j < n; j++) {
                diff[i][j + 1] += diff[i][j];
            }
        }
        for (int j = 0; j <= n; j++) {
            for (int i = 0; i < n; i++) {
                diff[i + 1][j] += diff[i][j];
            }
        }

        /*-------------------------------------------------------------
         * The answer is the maximum value inside the n × n region.
         *-------------------------------------------------------------*/
        int answer = 0;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                answer = Math.max(answer, diff[i][j]);
            }
        }
        OUT.println(answer);
    }

    /** Applies a 2‑D difference operation on `arr`. */
    private static void apply(int[][] arr, int x1, int x2, int y1, int y2) {
        arr[x1][y1]++;
        arr[x2][y2]++;
        arr[x1][y2]--;
        arr[x2][y1]--;
    }

    /** Returns the index of the first non‑'W' character in `row`,
     *  or -1 if the row contains only 'W'. */
    private static int firstNonWhite(char[] row) {
        for (int i = 0; i < row.length; i++) {
            if (row[i] != 'W') {
                return i;
            }
        }
        return -1;
    }

    /** Returns the index of the last non‑'W' character in `row`,
     *  or -1 if the row contains only 'W'. */
    private static int lastNonWhite(char[] row) {
        for (int i = row.length - 1; i >= 0; i--) {
            if (row[i] != 'W') {
                return i;
            }
        }
        return -1;
    }

    /* --------------------------------------------------------------- */
    /* Boiler‑plate InputReader / PrintWriter                         */
    /* --------------------------------------------------------------- */
    private static class InputReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        InputReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input), 32768);
        }

        String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new UncheckedIOException(e);
                }
            }
            return tokenizer.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Entry point – launches the solver in a separate thread with a large stack
 * to avoid {@code StackOverflowError} when the recursion depth of the
 * original implementation became an issue.
 */
public class Main {

    public static void main(String[] args) throws Exception {
        // Run the solver in its own thread with maximum priority.
        Thread solverThread = new Thread(() -> new Solver().run());
        solverThread.setName("WhiteLinesSolver");
        solverThread.setPriority(Thread.MAX_PRIORITY);
        solverThread.start();
    }
}

/**
 * Wrapper that contains the whole solving logic.  Keeping the algorithm
 * encapsulated makes the `Main` class tiny and testable.
 */
final class Solver {

    /** Entry point used when the solver runs in its own thread. */
    @Override
    public void run() {
        try (InputStream in = System.in;
             OutputStream out = System.out) {

            ScanReader scanner = new ScanReader(in);
            PrintWriter printer = new PrintWriter(out);

            new SolverCore(scanner).solve(printer);
            printer.flush();      // make sure the answer is written
        } catch (Exception ex) {
            throw new RuntimeException("Unexpected error while solving", ex);
        }
    }
}

/**
 * Core implementation of the problem solution.
 * The class is deliberately self‑contained and avoids static fields that
 * leak between invocations, which improves maintainability.
 */
final class SolverCore {

    private final ScanReader scanner;

    // -------------------------------------------------------------------------
    // Input data
    // -------------------------------------------------------------------------
    private int n;          // board size
    private int k;          // window size
    private int[][] grid;  // 1 = black, 0 = white

    // -------------------------------------------------------------------------
    // Prefix structures used for fast range‑sum queries
    // -------------------------------------------------------------------------
    private int[][] prefix;       // 2‑D prefix sum of {@code grid}
    private int[] rowZeros;       // prefix sum of “black‑only” rows
    private int[] colZeros;       // prefix sum of “black‑only” columns
    private int[][] vertical;     // helper prefix for vertical strips
    private int[][] horizontal;   // helper prefix for horizontal strips

    // -------------------------------------------------------------------------
    // Result
    // -------------------------------------------------------------------------
    private int answer;           // maximum score found

    SolverCore(ScanReader scanner) {
        this.scanner = scanner;
    }

    /** Reads all input data from {@code scanner}. */
    private void readInput() throws IOException {
        n = scanner.scanInt();
        k = scanner.scanInt();
        grid = new int[n + 1][n + 1];
        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= n; j++) {
                // ‘B’ → black (value 1), everything else → white (value 0)
                grid[i][j] = (scanner.scanChar() == 'B') ? 1 : 0;
            }
        }
    }

    /** Builds a 2‑D prefix sum over {@code grid}. */
    private void buildPrefixSums() {
        prefix = new int[n + 1][n + 1];
        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= n; j++) {
                prefix[i][j] = prefix[i - 1][j]
                        + prefix[i][j - 1]
                        - prefix[i - 1][j - 1]
                        + grid[i][j];
            }
        }
    }

    /** Computes prefix sums for rows/columns that consist solely of black cells. */
    private void buildRowColumnZeros() {
        // rowZeros[i] == 1  → the whole i‑th row is black
        // rowZeros[i] == 0  → at least one white cell exists in the row
        rowZeros = new int[n + 1];
        colZeros = new int[n + 1];

        for (int i = 1; i <= n; i++) {
            int whiteInRow = 0;   // counts white cells (i.e. cells == 0)
            int whiteInCol = 0;
            for (int j = 1; j <= n; j++) {
                if (grid[i][j] == 0) {
                    whiteInRow++;
                    whiteInCol++;
                }
            }
            // After the loop:
            //   if whiteInRow == 0  → row i contains no white cells → it is all black
            rowZeros[i] = (whiteInRow == 0) ? 1 : 0;
            colZeros[i] = (whiteInCol == 0) ? 1 : 0;
        }

        // Build prefix sums so we can query “how many black‑only rows up to i”
        for (int i = 1; i <= n; i++) {
            rowZeros[i] += rowZeros[i - 1];
            colZeros[i] += colZeros[i - 1];
        }
    }

    /** Returns the sum of the rectangle (i1,j1) … (i2,j2) inclusive. */
    private int rangeSum(int i1, int j1, int i2, int j2) {
        // Clamp coordinates to the valid board area.
        i1 = max(i1, 1);
        j1 = max(j1, 1);
        i2 = min(i2, n);
        j2 = min(j2, n);
        if (i1 > i2 || j1 > j2) {
            return 0;
        }
        return prefix[i2][j2]
                - prefix[i2][j1 - 1]
                - prefix[i1 - 1][j2]
                + prefix[i1 - 1][j1 - 1];
    }

    private static int max(int a, int b) { return a > b ? a : b; }
    private static int min(int a, int b) { return a < b ? a : b; }

    /** Constructs the helper prefix that marks completely white vertical strips. */
    private void computeVerticalHelper() {
        vertical = new int[n + 2][n + 2]; // a little extra space for safety
        for (int i = 1; i <= n + 1; i++) {
            for (int j = 1; j <= n + 1; j++) {
                // A vertical strip of height k ending just before i must be white.
                if (i - k - 1 >= 0) {
                    // The condition mirrors the original `findItSSS` logic.
                    if (rangeSum(0, j, i - k - 1, j) + rangeSum(i, j, n, j) == 0) {
                        vertical[i][j]++;
                    }
                }
                // Build a 2‑D prefix over the marks.
                vertical[i][j] += vertical[i - 1][j] + vertical[i][j - 1] - vertical[i - 1][j - 1];
            }
        }
    }

    /** Constructs the helper prefix that marks completely white horizontal strips. */
    private void computeHorizontalHelper() {
        horizontal = new int[n + 2][n + 2];
        for (int i = 1; i <= n + 1; i++) {
            for (int j = 1; j <= n + 1; j++) {
                if (j - k - 1 >= 0) {
                    if (rangeSum(i, 0, i, j - k - 1) + rangeSum(i, j, i, n) == 0) {
                        horizontal[i][j]++;
                    }
                }
                horizontal[i][j] += horizontal[i - 1][j] + horizontal[i][j - 1] - horizontal[i - 1][j - 1];
            }
        }
    }

    /** Scans the board for the maximal score according to the original algorithm. */
    private void findMaximum() {
        answer = 0;
        // The top‑left corner of a k×k window must leave enough room on the right
        // and bottom sides of the board.
        for (int i = 1; i <= n; i++) {
            int iEnd = i + k - 1;
            if (iEnd > n) {
                break;
            }
            for (int j = 1; j <= n; j++) {
                int jEnd = j + k - 1;
                if (jEnd > n) {
                    break;
                }

                // Base score = total number of black‑only rows + black‑only columns.
                int score = rowZeros[n] + colZeros[n];

                // Remove contributions that lie inside the current window.
                score -= (rowZeros[iEnd] - rowZeros[i - 1]);
                score -= (colZeros[jEnd] - colZeros[j - 1]);

                // Add the number of white cells that form a diagonal k‑stripe.
                score += rangeSum(i + k, j, i + k, j + k - 1);   // vertical stripe
                score += rangeSum(i, j + k, i + k - 1, j + k);   // horizontal stripe

                answer = max(answer, score);
            }
        }
    }

    /** Orchestrates input, preprocessing, and result output. */
    void solve(PrintWriter out) throws IOException {
        readInput();
        buildPrefixSums();
        buildRowColumnZeros();
        computeVerticalHelper();
        computeHorizontalHelper();
        findMaximum();
        out.println(answer);
        out.close();
    }
}

/**
 * Very small, high‑performance tokenizer that works on a byte buffer.
 * It replaces the original hand‑rolled `ScanReader` and isolates all I/O
 * concerns in a single class.
 */
final class ScanReader {

    private final byte[] buffer = new byte[1 << 16];
    private int pos;
    private int length;
    private final InputStream stream;

    ScanReader(InputStream stream) {
        this.stream = stream;
    }

    private int readByte() throws IOException {
        if (pos >= length) {
            length = stream.read(buffer);
            pos = 0;
            if (length <= 0) {
                return -1;
            }
        }
        return buffer[pos++];
    }

    /** Skips any whitespace characters and returns the next non‑whitespace byte. */
    private int skipWhite() throws IOException {
        int c;
        do {
            c = readByte();
        } while (isWhiteSpace(c));
        return c;
    }

    /** Parses a signed 32‑bit integer. */
    int scanInt() throws IOException {
        int sign = 1;
        int c = skipWhite();
        if (c == '-') {
            sign = -1;
            c = readByte();
        }
        int value = 0;
        while (c >= '0' && c <= '9') {
            value = value * 10 + (c - '0');
            c = readByte();
        }
        return sign * value;
    }

    /** Returns the next non‑whitespace character. */
    char scanChar() throws IOException {
        return (char) skipWhite();
    }

    private static boolean isWhiteSpace(int c) {
        return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
    }
}

import java.io.*;
import java.util.*;

 /**
 * Analyzes an N×N board containing characters 'B' and '.'.
 * It determines the best possible shift of a sliding window of length {@code WINDOW}
 * that maximises the number of rows/columns covered, and adds the number of rows
 * and columns that would become completely empty after removing all 'B' cells.
 */
public class BoardAnalyzer {

    /** Length of the sliding window (set from input). */
    private static int WINDOW;

    /**
     * Transposes a square board represented by an array of strings.
     *
     * @param board square board of size {@code n × n}
     * @return transposed board as a {@code String[]}
     */
    private static String[] transpose(String[] board) {
        int n = board.length;
        String[] transposed = new String[n];
        for (int col = 0; col < n; col++) {
            char[] chars = new char[n];
            for (int row = 0; row < n; row++) {
                chars[row] = board[row].charAt(col);
            }
            transposed[col] = new String(chars);
        }
        return transposed;
    }

    /**
     * Marks, for each row, the start positions of a sliding window of length {@code WINDOW}
     * that would cover at least one 'B' in that row.
     *
     * @param rows array of strings representing rows of the board
     * @return a matrix {@code rowShift[start][rowIdx]} where a value of {@code 1}
     *         indicates that a window starting at {@code start} covers a 'B' in the
     *         corresponding row.
     */
    private static int[][] buildRowShiftMatrix(String[] rows) {
        int n = rows.length;
        int[][] shiftMatrix = new int[n][n];
        for (int row = 0; row < n; row++) {
            int first = Integer.MAX_VALUE;
            int last  = -1;
            for (int col = 0; col < n; col++) {
                if (rows[row].charAt(col) == 'B') {
                    first = Math.min(first, col);
                    last  = Math.max(last, col);
                }
            }
            if (last == -1) {
                continue;               // row contains no 'B'
            }
            int startMin = Math.max(0, last - WINDOW + 1);
            int startMax = Math.min(first, n - WINDOW);
            for (int start = startMin; start <= startMax; start++) {
                shiftMatrix[row][start] = 1;
            }
        }
        return shiftMatrix;
    }

    /**
     * Computes the sum of each sliding window of length {@code WINDOW} over the rows
     * of the supplied matrix. The result is a matrix where the first dimension
     * represents the start index of the window and the second dimension represents
     * the original column index.
     *
     * @param matrix matrix whose rows are to be summed in sliding windows
     * @return matrix of sliding‑window sums
     */
    private static int[][] computeSlidingWindowSums(int[][] matrix) {
        int n = matrix.length;
        int[][] sums = new int[n][n];
        int windowSize = WINDOW;

        // initialise first window
        int currentSum = 0;
        for (int row = 0; row < windowSize; row++) {
            currentSum += matrix[row][/*column*/0]; // column will be filled per outer loop
        }

        // Process each column independently
        for (int col = 0; col < n; col++) {
            // compute sum for the first window of this column
            currentSum = 0;
            for (int row = 0; row < windowSize; row++) {
                currentSum += matrix[row][col];
            }
            sums[0][col] = currentSum;

            // slide the window downwards
            for (int start = 0; start < n - windowSize; start++) {
                currentSum += matrix[start + windowSize][col];
                currentSum -= matrix[start][col];
                sums[start + 1][col] = currentSum;
            }
        }
        return sums;
    }

    /**
     * Counts how many rows and columns become empty when every 'B' cell is removed.
     *
     * @param board board to analyse
     * @return number of completely empty rows plus number of completely empty columns
     */
    private static int countEmptyRowsAndColumns(String[] board) {
        int n = board.length;
        int count = 0;
        for (int i = 0; i < n; i++) {
            boolean rowEmpty = true;
            boolean colEmpty = true;
            for (int j = 0; j < n; j++) {
                if (board[i].charAt(j) == 'B') {
                    rowEmpty = false;
                }
                if (board[j].charAt(i) == 'B') {
                    colEmpty = false;
                }
            }
            count += rowEmpty ? 1 : 0;
            count += colEmpty ? 1 : 0;
        }
        return count;
    }

    public static void main(String[] args) throws IOException {
        // Try‑with‑resources guarantees that the input stream is closed.
        try (BufferedReader reader = new BufferedReader(
                new InputStreamReader(System.in));
             Scanner scanner = new Scanner(reader)) {

            int boardSize = scanner.nextInt();   // N
            WINDOW = scanner.nextInt();          // sliding window length
            scanner.nextLine();                  // consume end‑of‑line

            String[] board = new String[boardSize];
            for (int i = 0; i < boardSize; i++) {
                board[i] = scanner.nextLine();
            }

            // ----- Horizontal (row) coverage -----
            int[][] rowShiftMatrix = buildRowShiftMatrix(board);
            int[][] rowWindowSums  = computeSlidingWindowSums(rowShiftMatrix);

            // ----- Vertical (column) coverage -----
            String[] transposed = transpose(board);
            int[][] colShiftMatrix = buildRowShiftMatrix(transposed);
            int[][] colWindowSums  = computeSlidingWindowSums(colShiftMatrix);

            // ----- Find the best combined shift -----
            int bestCombined = 0;
            for (int startRow = 0; startRow < boardSize; startRow++) {
                for (int colIdx = 0; colIdx < boardSize; colIdx++) {
                    int combined = rowWindowSums[startRow][colIdx]
                                 + colWindowSums[colIdx][startRow];
                    bestCombined = Math.max(bestCombined, combined);
                }
            }

            // ----- Add empty rows/columns count and output -----
            int emptyCount = countEmptyRowsAndColumns(board);
            int result = bestCombined + emptyCount;
            System.out.println(result);
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

/**
 * Refactored solution for the “paint‑black K×K window” problem.
 * <p>
 * The program reads an N×N grid where each cell is either 'B' (black) or '.'
 * (white).  It finds the maximum number of additional black cells that can be
 * obtained by selecting a K×K sub‑grid to paint entirely black.  The answer is
 * the size of the best sub‑grid plus the number of rows/columns that are
 * already completely white.
 *
 * Refactoring goals:
 * <ul>
 *   <li>Clear, self‑documenting names.</li>
 *   <li>Extraction of logical pieces into small, reusable methods.</li>
 *   <li>Use of {@code try‑with‑resources} for I/O.</li>
 *   <li>Avoidance of duplicated work with helper functions.</li>
 *   <li>Removal of magic numbers and magic strings.</li>
 * </ul>
 */
public class Solution {

    /** Prefix‑sum of black cells for each row (horizontal). */
    private static int[][] buildRowPrefix(char[][] grid, int n) {
        int[][] pref = new int[n][n];
        for (int r = 0; r < n; ++r) {
            for (int c = 0; c < n; ++c) {
                int add = (grid[r][c] == 'B' ? 1 : 0);
                pref[r][c] = (c == 0 ? 0 : pref[r][c - 1]) + add;
            }
        }
        return pref;
    }

    /** Prefix‑sum of black cells for each column (vertical). */
    private static int[][] buildColPrefix(char[][] grid, int n) {
        int[][] pref = new int[n][n];
        for (int c = 0; c < n; ++c) {
            for (int r = 0; r < n; ++r) {
                int add = (grid[r][c] == 'B' ? 1 : 0);
                pref[r][c] = (r == 0 ? 0 : pref[r - 1][c]) + add;
            }
        }
        return pref;
    }

    /** Count of rows that already contain no black squares. */
    private static int countAlreadyWhiteRows(int[] rowCount) {
        int zeroRows = 0;
        for (int v : rowCount) {
            if (v == 0) zeroRows++;
        }
        return zeroRows;
    }

    /** Count of columns that already contain no black squares. */
    private static int countAlreadyWhiteCols(int[] colCount) {
        int zeroCols = 0;
        for (int v : colCount) {
            if (v == 0) zeroCols++;
        }
        return zeroCols;
    }

    /**
     * Returns {@code true} if the vertical window of height {@code K}
     * that starts at {@code row} contains exactly {@code colCount[col]}
     * black cells in column {@code col}.
     */
    private static boolean columnMatchesWindow(int row, int col, int K,
                                               int[][] colPrefix, int[] colCount) {
        int sum = colPrefix[row + K - 1][col];
        if (row > 0) sum -= colPrefix[row - 1][col];
        return sum == colCount[col];
    }

    /**
     * Returns {@code true} if the horizontal window of width {@code K}
     * that starts at {@code col} contains exactly {@code rowCount[row]}
     * black cells in row {@code row}.
     */
    private static boolean rowMatchesWindow(int row, int col, int K,
                                            int[][] rowPrefix, int[] rowCount) {
        int sum = rowPrefix[row][col + K - 1];
        if (col > 0) sum -= rowPrefix[row][col - 1];
        return sum == rowCount[row];
    }

    /**
     * Counts how many columns become “fully black” when a vertical K‑wide
     * window slides over rows {@code startRow} … {@code startRow + K - 1}.
     */
    private static int countFullyBlackColumns(int startRow, int K,
                                              int[][] colPrefix, int[] colCount) {
        int cnt = 0;
        for (int c = 0; c < colPrefix[0].length; ++c) {
            if (columnMatchesWindow(startRow, c, K, colPrefix, colCount)) {
                ++cnt;
            }
        }
        return cnt;
    }

    /**
     * Counts how many rows become “fully black” when a horizontal K‑wide
     * window slides over columns {@code startCol} … {@code startCol + K - 1}.
     */
    private static int countFullyBlackRows(int startCol, int K,
                                           int[][] rowPrefix, int[] rowCount) {
        int cnt = 0;
        for (int r = 0; r < rowPrefix.length; ++r) {
            if (rowMatchesWindow(r, startCol, K, rowPrefix, rowCount)) {
                ++cnt;
            }
        }
        return cnt;
    }

    public static void main(String[] args) throws IOException {
        /* ----------  Input handling  ---------- */
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in))) {
            FastScanner fs = new FastScanner(br);

            int n = Integer.parseInt(fs.nextToken());
            int K = Integer.parseInt(fs.nextToken());

            char[][] grid = new char[n][n];
            for (int i = 0; i < n; ++i) {
                String line = fs.nextToken();
                grid[i] = line.toCharArray();
            }

            /* ----------  Global statistics  ---------- */
            int[] rowBlackCount = new int[n];
            int[] colBlackCount = new int[n];
            for (int r = 0; r < n; ++r) {
                for (int c = 0; c < n; ++c) {
                    if (grid[r][c] == 'B') {
                        rowBlackCount[r]++;
                        colBlackCount[c]++;
                    }
                }
            }

            int alreadyWhite = countAlreadyWhiteRows(rowBlackCount) +
                               countAlreadyWhiteCols(colBlackCount);

            /* ----------  Prefix sums  ---------- */
            int[][] rowPrefix = buildRowPrefix(grid, n);
            int[][] colPrefix = buildColPrefix(grid, n);

            /* ----------  Sliding‑window accumulation  ---------- */
            // white[r][c] will store how many extra black cells we obtain
            // when the K×K window with its top‑left corner at (r,c) is painted.
            int[][] white = new int[n][n];

            /* ----  Vertical moves (fix column window) ---- */
            for (int colStart = 0; colStart <= n - K; ++colStart) {
                // First window in this column group
                int verticalCount = countFullyBlackColumns(0, K, colPrefix, colBlackCount);
                white[0][colStart] = verticalCount;

                // Slide the window downwards
                for (int row = 1; row <= n - K; ++row) {
                    // Remove contribution of the row that leaves the window
                    if (colBlackCount[colStart] != 0 &&
                        columnMatchesWindow(row - 1, colStart, K, colPrefix, colBlackCount)) {
                        verticalCount--;
                    }
                    // Add contribution of the new row entering the window
                    if (colBlackCount[colStart] != 0 &&
                        columnMatchesWindow(row + K - 1, colStart, K, colPrefix, colBlackCount)) {
                        verticalCount++;
                    }
                    white[row][colStart] = verticalCount;
                }
            }

            /* ----  Horizontal moves (fix row window) ---- */
            for (int rowStart = 0; rowStart <= n - K; ++rowStart) {
                // First window in this row group
                int horizontalCount = countFullyBlackRows(rowStart, K, rowPrefix, rowBlackCount);
                white[rowStart][0] += horizontalCount;

                // Slide the window rightwards
                for (int col = 1; col <= n - K; ++col) {
                    // Remove contribution of the column that leaves the window
                    if (rowBlackCount[rowStart] != 0 &&
                        rowMatchesWindow(rowStart, col - 1, K, rowPrefix, rowBlackCount)) {
                        horizontalCount--;
                    }
                    // Add contribution of the new column entering the window
                    if (rowBlackCount[rowStart] != 0 &&
                        rowMatchesWindow(rowStart, col + K - 1, K, rowPrefix, rowBlackCount)) {
                        horizontalCount++;
                    }
                    white[rowStart][col] += horizontalCount;
                }
            }

            /* ----------  Result extraction ---------- */
            int bestExtra = 0;
            for (int r = 0; r < n; ++r) {
                for (int c = 0; c < n; ++c) {
                    if (white[r][c] > bestExtra) {
                        bestExtra = white[r][c];
                    }
                }
            }

            System.out.println(bestExtra + alreadyWhite);
        }
    }

    /** Simple tokeniser that mimics {@code StringTokenizer} but without checked exceptions. */
    private static final class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner(BufferedReader br) {
            this.br = br;
        }

        String nextToken() throws IOException {
            while (st == null || !st.hasMoreElements()) {
                String line = br.readLine();
                if (line == null) {
                    return null;
                }
                st = new StringTokenizer(line);
            }
            return st.nextToken();
        }
    }
}

import java.io.PrintWriter;
import java.util.Scanner;

public class Main {

    void solve(Scanner in, PrintWriter out) {
        int gridSize = in.nextInt();
        int squareSize = in.nextInt();
        char[][] grid = new char[gridSize][gridSize];

        for (int i = 0; i < gridSize; ++i) {
            grid[i] = in.next().toCharArray();
        }

        int whiteBase = 0;
        boolean[][] rowCoverage = new boolean[gridSize][gridSize];
        boolean[][] colCoverage = new boolean[gridSize][gridSize];

        // Process rows: Mark valid starting columns for each row's black segment
        for (int row = 0; row < gridSize; ++row) {
            int firstBlack = -1, lastBlack = -1;
            for (int col = 0; col < gridSize; ++col) {
                if (grid[row][col] == 'B') {
                    if (firstBlack == -1) firstBlack = col;
                    lastBlack = col;
                }
            }
            if (firstBlack == -1) {
                whiteBase++;
                continue;
            }
            int startCol = Math.max(0, lastBlack - squareSize + 1);
            int endCol = firstBlack;
            for (int colStart = startCol; colStart <= endCol; ++colStart) {
                rowCoverage[row][colStart] = true;
            }
        }

        // Process columns: Mark valid starting rows for each column's black segment
        for (int col = 0; col < gridSize; ++col) {
            int firstBlackRow = -1, lastBlackRow = -1;
            for (int row = 0; row < gridSize; ++row) {
                if (grid[row][col] == 'B') {
                    if (firstBlackRow == -1) firstBlackRow = row;
                    lastBlackRow = row;
                }
            }
            if (firstBlackRow == -1) {
                whiteBase++;
                continue;
            }
            int startRow = Math.max(0, lastBlackRow - squareSize + 1);
            int endRow = firstBlackRow;
            for (int rowStart = startRow; rowStart <= endRow; ++rowStart) {
                colCoverage[rowStart][col] = true;
            }
        }

        // Build row coverage count matrix (sliding window over rows)
        int[][] rowCoverCount = new int[gridSize - squareSize + 1][gridSize - squareSize + 1];
        for (int colStart = 0; colStart <= gridSize - squareSize; ++colStart) {
            for (int row = 0; row < squareSize; ++row) {
                if (rowCoverage[row][colStart]) {
                    ++rowCoverCount[0][colStart];
                }
            }
            for (int rowStart = 1; rowStart <= gridSize - squareSize; ++rowStart) {
                rowCoverCount[rowStart][colStart] = rowCoverCount[rowStart - 1][colStart];
                if (rowCoverage[rowStart - 1][colStart]) {
                    --rowCoverCount[rowStart][colStart];
                }
                if (rowCoverage[rowStart + squareSize - 1][colStart]) {
                    ++rowCoverCount[rowStart][colStart];
                }
            }
        }

        // Build column coverage count matrix (sliding window over columns)
        int[][] colCoverCount = new int[gridSize - squareSize + 1][gridSize - squareSize + 1];
        for (int rowStart = 0; rowStart <= gridSize - squareSize; ++rowStart) {
            for (int col = 0; col < squareSize; ++col) {
                if (colCoverage[rowStart][col]) {
                    ++colCoverCount[rowStart][0];
                }
            }
            for (int colStart = 1; colStart <= gridSize - squareSize; ++colStart) {
                colCoverCount[rowStart][colStart] = colCoverCount[rowStart][colStart - 1];
                if (colCoverage[rowStart][colStart - 1]) {
                    --colCoverCount[rowStart][colStart];
                }
                if (colCoverage[rowStart][colStart + squareSize - 1]) {
                    ++colCoverCount[rowStart][colStart];
                }
            }
        }

        // Calculate maximum coverage
        int maxCoverage = whiteBase;
        for (int rowStart = 0; rowStart <= gridSize - squareSize; ++rowStart) {
            for (int colStart = 0; colStart <= gridSize - squareSize; ++colStart) {
                maxCoverage = Math.max(maxCoverage, whiteBase + rowCoverCount[rowStart][colStart] + colCoverCount[rowStart][colStart]);
            }
        }
        out.println(maxCoverage);
    }

    public static void main(String[] args) {
        new Main().run();
    }

    void run() {
        try (
                Scanner in = new Scanner(System.in);
                PrintWriter out = new PrintWriter(System.out)
        ) {
            solve(in, out);
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.Arrays;

/**
 * Solution for problem 1200D – “Grid coloring”.
 *
 * <p>Reads a square grid of characters, counts how many rows/columns are already
 * completely free of a special cell ('B'), and then determines the maximum number
 * of additional rows/columns that can become completely free after placing a
 * <code>k×k</code> square anywhere on the board.
 *
 * <p>The refactor introduces small, single‑purpose methods, meaningful names and
 * constant declarations to improve readability and maintainability.
 */
public final class P1200D_2 {

    /** Buffer size for fast character reading. */
    private static final int BUFFER_SIZE = 10_240;

    /** Entry point. */
    public static void main(String[] args) {
        try (PrintWriter writer = new PrintWriter(System.out)) {
            int[] parameters = readInput();
            int initClear = countAlreadyClearRowsAndColumns(parameters);
            int bestAddition = findBestPlacement(parameters);
            writer.println(initClear + bestAddition);
        }
    }

    /** Extracts all primitive data from {@code System.in}. */
    private static int[] readInput() {
        SimpleScanner scanner = new SimpleScanner(System.in);
        int n = scanner.nextInt();
        int k = scanner.nextInt();
        char[][] grid = new char[n][];
        for (int i = 0; i < n; ++i) {
            grid[i] = scanner.next().toCharArray();
        }
        return new int[]{n, k, grid};
    }

    /** Returns the number of rows and columns that are already completely free
     *  of the character {@code 'B'}. */
    private static int countAlreadyClearRowsAndColumns(int[] params) {
        int n = params[0];
        char[][] grid = (char[][]) params[2];

        int[] top = new int[n];
        int[] bottom = new int[n];
        int[] left = new int[n];
        int[] right = new int[n];
        Arrays.fill(top, n);
        Arrays.fill(left, n);
        Arrays.fill(bottom, -1);
        Arrays.fill(right, -1);

        // Record min/max row and column for each column and row that contains a 'B'.
        for (int row = 0; row < n; ++row) {
            for (int col = 0; col < n; ++col) {
                if (grid[row][col] == 'B') {
                    top[col] = Math.min(top[col], row);
                    bottom[col] = Math.max(bottom[col], row);
                    left[row] = Math.min(left[row], col);
                    right[row] = Math.max(right[row], col);
                }
            }
        }

        // Count rows/columns that have no 'B' at all.
        int alreadyClear = 0;
        for (int i = 0; i < n; ++i) {
            if (right[i] < left[i]) {
                ++alreadyClear;               // row i has no 'B'
            }
            if (bottom[i] < top[i]) {
                ++alreadyClear;               // column i has no 'B'
            }
        }
        return alreadyClear;
    }

    /** Computes the maximum number of additional rows/columns that can become
     *  completely free after placing a <code>k×k</code> square at position (i, j). */
    private static int findBestPlacement(int[] params) {
        int n = params[0];
        int k = params[1];
        char[][] grid = (char[][]) params[2];

        // Pre‑compute column and row contributions for every possible placement.
        int[][] columnContribution = computeColumnContribution(grid, n, k);
        int[][] rowContribution      = computeRowContribution(grid, n, k);

        // Find the best (i, j) combination.
        int best = 0;
        for (int i = 0; i <= n - k; ++i) {
            for (int j = 0; j <= n - k; ++j) {
                best = Math.max(best, rowContribution[i][j] + columnContribution[i][j]);
            }
        }
        return best;
    }

    /** Determines, for each possible vertical offset i, how many columns become
     *  completely clear when the k×k square starts at row i. */
    private static int[][] computeColumnContribution(char[][] grid, int n, int k) {
        int[][] inc = new int[n - k + 1][n - k + 1];

        // Process the first column window.
        for (int col = 0; col < k; ++col) {
            if (isColumnFullyClearable(grid, col, 0, n, k)) {
                ++inc[0][0];
            }
        }

        // Slide the window horizontally.
        for (int colStart = 1; colStart <= n - k; ++colStart) {
            inc[0][colStart] = inc[0][colStart - 1];

            int leftMost = colStart - 1;
            int newRight = colStart + k - 1;

            if (isColumnFullyClearable(grid, leftMost, 0, n, k)) {
                --inc[0][colStart];
            }
            if (isColumnFullyClearable(grid, newRight, 0, n, k)) {
                ++inc[0][colStart];
            }
        }

        // Fill remaining rows (i offsets) by vertical sliding.
        for (int i = 1; i <= n - k; ++i) {
            for (int colStart = 0; colStart <= n - k; ++colStart) {
                inc[i][colStart] = inc[i - 1][colStart];
                int topMost = i - 1;
                int bottomMost = i + k - 1;

                if (isColumnFullyClearable(grid, topMost, colStart, n, k)) {
                    --inc[i][colStart];
                }
                if (isColumnFullyClearable(grid, bottomMost, colStart, n, k)) {
                    ++inc[i][colStart];
                }
            }
        }
        return inc;
    }

    /** Determines, for each possible horizontal offset j, how many rows become
     *  completely clear when the k×k square starts at column j. */
    private static int[][] computeRowContribution(char[][] grid, int n, int k) {
        int[][] inc = new int[n - k + 1][n - k + 1];

        // Process the first row window.
        for (int row = 0; row < k; ++row) {
            if (isRowFullyClearable(grid, row, 0, n, k)) {
                ++inc[0][0];
            }
        }

        // Slide the window vertically.
        for (int rowStart = 1; rowStart <= n - k; ++rowStart) {
            inc[rowStart][0] = inc[rowStart - 1][0];

            int topMost = rowStart - 1;
            int bottomMost = rowStart + k - 1;

            if (isRowFullyClearable(grid, topMost, 0, n, k)) {
                --inc[rowStart][0];
            }
            if (isRowFullyClearable(grid, bottomMost, 0, n, k)) {
                ++inc[rowStart][0];
            }
        }

        // Fill remaining columns (j offsets) by horizontal sliding.
        for (int col = 1; col <= n - k; ++col) {
            for (int rowStart = 0; rowStart <= n - k; ++rowStart) {
                inc[rowStart][col] = inc[rowStart][col - 1];

                int leftMost = col - 1;
                int rightMost = col + k - 1;

                if (isRowFullyClearable(grid, leftMost, rowStart, n, k)) {
                    --inc[rowStart][col];
                }
                if (isRowFullyClearable(grid, rightMost, rowStart, n, k)) {
                    ++inc[rowStart][col];
                }
            }
        }
        return inc;
    }

    /** Checks whether a given column `col` can become completely clear when the
     *  k×k square starts at vertical offset `rowOffset`. */
    private static boolean isColumnFullyClearable(char[][] grid, int col, int rowOffset,
                                                  int n, int k) {
        // There must be at least one 'B' in this column; otherwise it is already clear.
        if (bottom(col) < top(col)) {
            return true;
        }
        int columnBottom = bottom(col);
        int columnTop    = top(col);
        return columnBottom < rowOffset + k && columnTop >= rowOffset;
    }

    /** Checks whether a given row `row` can become completely clear when the
     *  k×k square starts at horizontal offset `colOffset`. */
    private static boolean isRowFullyClearable(char[][] grid, int row, int colOffset,
                                               int n, int k) {
        if (right(row) < left(row)) {
            return true;
        }
        int rowRight = right(row);
        int rowLeft  = left(row);
        return rowRight < colOffset + k && rowLeft >= colOffset;
    }

    /** Utility to fetch the minimal row that contains a 'B' for column `c`. */
    private static int top(char[][] grid, int[] top, int c) {
        return top[c];
    }

    /** Utility to fetch the maximal row that contains a 'B' for column `c`. */
    private static int bottom(char[][] grid, int[] bottom, int c) {
        return bottom[c];
    }

    /** Utility to fetch the minimal column that contains a 'B' for row `r`. */
    private static int left(char[][] grid, int[] left, int r) {
        return left[r];
    }

    /** Utility to fetch the maximal column that contains a 'B' for row `r`. */
    private static int right(char[][] grid, int[] right, int r) {
        return right[r];
    }

    /** Simple fast scanner used for reading tokens from standard input. */
    private static final class SimpleScanner {
        private final BufferedReader reader;
        private final char[] buffer = new char[BUFFER_SIZE];
        private int bufferPos = 0;
        private int bufferLength = 0;
        private boolean eof = false;

        SimpleScanner(InputStream stream) {
            this.reader = new BufferedReader(new InputStreamReader(stream));
        }

        private char readChar() {
            if (!hasRemaining()) {
                reload();
                if (!hasRemaining()) {
                    eof = true;
                    return '\0';
                }
            }
            return buffer[bufferPos++];
        }

        private void reload() throws IOException {
            bufferPos = 0;
            bufferLength = reader.read(buffer);
        }

        private boolean hasRemaining() {
            return bufferPos < bufferLength;
        }

        /** Consumes leading whitespace and returns the next token. */
        String next() {
            char c;
            do {
                c = readChar();
                if (eof) {
                    throw new java.util.NoSuchElementException();
                }
            } while (Character.isWhitespace(c));

            StringBuilder sb = new StringBuilder();
            do {
                sb.append(c);
                c = readChar();
            } while (!eof && !Character.isWhitespace(c));
            return sb.toString();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Main entry point of the program.
 * The algorithm counts how many rows and columns become completely filled with 'B'
 * after placing a k×k square somewhere on an n×n board.
 */
public class Main {

    /** Simple wrapper around the original InputReader – kept unchanged. */
    private static class InputReader {
        private final InputStream stream;
        private final byte[] buffer = new byte[1024];
        private int curChar;
        private int numChars;
        private final SpaceCharFilter filter;

        InputReader(InputStream stream) {
            this.stream = stream;
        }

        private int read() {
            if (numChars == -1) {
                throw new InputMismatchException();
            }
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buffer);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (numChars <= 0) {
                    return -1;
                }
            }
            return buffer[curChar++];
        }

        /** Returns next non‑space character. */
        private int nextNonSpace() {
            int c;
            do {
                c = read();
            } while (isSpaceChar(c));
            return c;
        }

        public int nextInt() {
            int sign = 1;
            int c = nextNonSpace();
            if (c == '-') {
                sign = -1;
                c = read();
            }
            long value = 0;
            do {
                if (c < '0' || c > '9') {
                    throw new InputMismatchException();
                }
                value = value * 10 + (c - '0');
                c = read();
            } while (!isSpaceChar(c));
            return (int) (value * sign);
        }

        /** Utility filter used by {@link #isSpaceChar(int)}. */
        public interface SpaceCharFilter {
            boolean isSpaceChar(int ch);
        }
    }

    /** Encapsulates the board and related statistics. */
    private static final class Board {
        private final char[][] grid;   // 1‑based indexing for simplicity
        private final int n;           // board dimension
        private final int[] rowCount;  // number of 'B' in each row
        private final int[] colCount;  // number of 'B' in each column
        private final int rowsWithoutB; // rows that already contain no 'B'
        private final int colsWithoutB; // columns that already contain no 'B'

        Board(int n) {
            this.n = n;
            this.grid = new char[n + 2][n + 2]; // 1‑based, padding with spaces
            this.rowCount = new int[n + 1];
            this.colCount = new int[n + 1];
            this.rowsWithoutB = 0;
            this.colsWithoutB = 0;
        }

        /** Reads the board from the scanner. */
        void readFrom(InputReader sc) {
            for (int i = 1; i <= n; i++) {
                String row = (" " + sc.next()).trim();
                grid[i] = row.toCharArray();
                for (int j = 1; j <= n; j++) {
                    if (grid[i][j] == 'B') {
                        rowCount[i]++;
                        colCount[j]++;
                    }
                }
            }
            rowsWithoutB = Arrays.stream(rowCount, 1, n + 1)
                                 .filter(c -> c == 0)
                                 .size();
            colsWithoutB = Arrays.stream(colCount, 1, n + 1)
                                 .filter(c -> c == 0)
                                 .size();
        }

        /** Returns a copy of the internal matrix (useful for debugging). */
        char[][] getMatrix() {
            char[][] copy = new char[n + 2][n + 2];
            System.arraycopy(grid, 0, copy, 0, grid.length);
            return copy;
        }

        /** Number of rows that contain no 'B'. */
        int rowsWithoutB() {
            return rowsWithoutB;
        }

        /** Number of columns that contain no 'B'. */
        int colsWithoutB() {
            return colsWithoutB;
        }

        /** Number of 'B' in a given row (1‑based). */
        int rowBCount(int row) {
            return rowCount[row];
        }

        /** Number of 'B' in a given column (1‑based). */
        int colBCount(int col) {
            return colCount[col];
        }
    }

    /** Holds the sliding‑window coverage information for rows. */
    private static final class RowCoverage {
        /** Prefix sums – rowCoverage[i][start] = number of rows ≤ i
         *   where a window of length k starting at column `start`
         *   contains all B‑cells of that row. */
        private final int[][] prefix; // size (n+1) × (n+1)

        RowCoverage(int n, int k, Board board) {
            prefix = new int[n + 1][n + 1];
            for (int i = 1; i <= n; i++) {
                // initialise first window of size k in row i
                int bInWindow = 0;
                for (int j = 1; j <= k; j++) {
                    if (board.grid[i][j] == 'B') {
                        bInWindow++;
                    }
                }
                // if the window already covers all B's of the row, mark it
                if (board.rowBCount(i) != 0 && bInWindow == board.rowBCount(i)) {
                    prefix[i][1] = prefix[i - 1][1] + 1;
                } else {
                    prefix[i][1] = prefix[i - 1][1];
                }

                // slide the window across the row
                for (int j = k + 1; j <= n; j++) {
                    // remove leftmost column, add new rightmost column
                    if (board.grid[i][j - k] == 'B') {
                        bInWindow--;
                    }
                    if (board.grid[i][j] == 'B') {
                        bInWindow++;
                    }
                    int start = j - k + 1;
                    if (board.rowBCount(i) != 0 && bInWindow == board.rowBCount(i)) {
                        prefix[i][start] = prefix[i - 1][start] + 1;
                    } else {
                        prefix[i][start] = prefix[i - 1][start];
                    }
                }
            }
        }

        /** Returns the prefix sum at (row, start). */
        int get(int row, int start) {
            return prefix[row][start];
        }
    }

    /** Holds the analogous sliding‑window coverage information for columns. */
    private static final class ColumnCoverage {
        /** Prefix sums – columnCoverage[start][col] = number of columns ≤ start
         *   where a vertical window of length k starting at row `start`
         *   contains all B‑cells of that column. */
        private final int[][] prefix; // size (n+1) × (n+1)

        ColumnCoverage(int n, int k, Board board) {
            prefix = new int[n + 1][n + 1];
            for (int j = 1; j <= n; j++) {
                // initialise first window of size k in column j
                int bInWindow = 0;
                for (int i = 1; i <= k; i++) {
                    if (board.grid[i][j] == 'B') {
                        bInWindow++;
                    }
                }
                if (board.colBCount(j) != 0 && bInWindow == board.colBCount(j)) {
                    prefix[1][j] = prefix[1][j - 1] + 1;
                } else {
                    prefix[1][j] = prefix[1][j - 1];
                }

                // slide the window downwards
                for (int i = k + 1; i <= n; i++) {
                    if (board.grid[i - k][j] == 'B') {
                        bInWindow--;
                    }
                    if (board.grid[i][j] == 'B') {
                        bInWindow++;
                    }
                    int start = i - k + 1;
                    if (board.colBCount(j) != 0 && bInWindow == board.colBCount(j)) {
                        prefix[start][j] = prefix[start - 1][j] + 1;
                    } else {
                        prefix[start][j] = prefix[start - 1][j];
                    }
                }
            }
        }

        /** Returns the prefix sum at (start, col). */
        int get(int start, int col) {
            return prefix[start][col];
        }
    }

    public static void main(String[] args) throws IOException {
        InputReader scanner = new InputReader(System.in);
        PrintWriter out = new PrintWriter(System.out, true);

        int n = scanner.nextInt();          // board size
        int k = scanner.nextInt();          // size of the square to place

        Board board = new Board(n);
        board.readFrom(scanner);

        // ----- 1. Compute row‑wise coverage prefix sums -----
        RowCoverage rowCov = new RowCoverage(n, k, board);

        // ----- 2. Compute column‑wise coverage prefix sums -----
        ColumnCoverage colCov = new ColumnCoverage(n, k, board);

        // ----- 3. Evaluate every possible top‑left corner of the k×k square -----
        int best = board.rowsWithoutB() + board.colsWithoutB(); // baseline value

        // The original code used three‑dimensional `res` arrays.
        // Here we compute the same value using the prepared prefix tables.
        for (int top = 1; top <= n - k + 1; top++) {
            for (int left = 1; left <= n - k + 1; left++) {
                // rows that become completely 'B' inside the current square
                int rowsFilled = rowCov.get(top + k - 1, left + k - 1)
                                     - rowCov.get(top - 1, left + k - 1)
                                     + rowCov.get(top + k - 1, left - 1)
                                     - rowCov.get(top - 1, left - 1);

                // columns that become completely 'B' inside the current square
                int colsFilled = colCov.get(top + k - 1, left + k - 1)
                                 - colCov.get(top + k - 1, left - 1)
                                 + colCov.get(top - 1, left + k - 1)
                                 - colCov.get(top - 1, left - 1);

                int candidate = rowsFilled + colsFilled + best;
                if (candidate > best) {
                    best = candidate;
                }
            }
        }

        out.println(best);
        out.close();
    }
}

import java.io.*;
import java.util.*;

/**
 * Garland – refactored version.
 *
 * <p>
 * The original program performed a rather compact and hard‑to‑read computation
 * on an integer array that contained zeros as placeholders.  The refactor
 * separates concerns, uses meaningful names, extracts small helper methods,
 * and replaces the custom buffered reader with a clearer {@link FastScanner}
 * utility.  Functionally it produces exactly the same output for all valid
 * inputs as the original source.
 * </p>
 */
public class Garland {

    /** Modulus used in the original program – kept for compatibility. */
    private static final long MOD = 1_000_000_007L;

    /** Fast scanner that works with both {@code System.in} and a file name. */
    private static class FastScanner {
        private final InputStream stream;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream stream) {
            this.stream = stream;
        }

        FastScanner(String fileName) throws IOException {
            this(new FileInputStream(fileName));
        }

        private int readByte() throws IOException {
            if (ptr >= len) {
                len = stream.read(buffer);
                ptr = 0;
                if (len <= 0) {
                    return -1;
                }
            }
            return buffer[ptr++];
        }

        /** Skips any whitespace. */
        private int skipWhite() throws IOException {
            int b;
            while ((b = readByte()) <= ' ');
            return b;
        }

        /** Reads next signed integer. */
        int nextInt() throws IOException {
            int sign = 1;
            int c = skipWhite();
            if (c == '-') {
                sign = -1;
                c = readByte();
            }
            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = readByte();
            }
            return val * sign;
        }

        long nextLong() throws IOException {
            long sign = 1;
            int c = skipWhite();
            if (c == '-') {
                sign = -1;
                c = readByte();
            }
            long val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = readByte();
            }
            return val * sign;
        }

        double nextDouble() throws IOException {
            double sign = 1;
            int c = skipWhite();
            if (c == '-') {
                sign = -1;
                c = readByte();
            }
            double val = 0;
            while (c > ' ') {
                if (c == '.') {
                    double div = 10;
                    c = readByte();
                    while (c > ' ') {
                        val += (c - '0') / div;
                        div *= 10;
                        c = readByte();
                    }
                    break;
                }
                val = val * 10 + (c - '0');
                c = readByte();
            }
            return sign * val;
        }

        /** Closes the underlying stream when it was opened on a file. */
        void close() throws IOException {
            if (stream != System.in) {
                stream.close();
            }
        }
    }

    /** Entry point – delegates all work to {@link #solve}. */
    public static void main(String[] args) throws Exception {
        FastScanner scanner = new FastScanner();               // reads from stdin
        int n = scanner.nextInt();
        int[] arr = readArray(scanner, n);
        scanner.close();

        long answer = solve(arr);
        System.out.println(answer);
    }

    /** Reads the integer array of size {@code n} (1‑based indexing). */
    private static int[] readArray(FastScanner in, int n) {
        int[] a = new int[n + 1];          // we keep the 1‑based convention
        for (int i = 1; i <= n; i++) {
            a[i] = in.nextInt();
        }
        return a;
    }

    /**
     * Core algorithm – mirrored the behaviour of the original monolithic code
     * but organised into small, testable pieces.
     */
    private static long solve(int[] a) {
        final int n = a.length - 1;                     // because of 1‑based storage

        // -----------------------------------------------------------------
        // 1. Special‑case: the whole array consists of zeros.
        // -----------------------------------------------------------------
        if (allZeros(a, n)) {
            if (n == 1) {
                return 0L;
            }
            System.out.println(1);
            return -1;                                   // already printed, exit
        }
        if (n == 1) {
            System.out.println(0);
            return -1;
        }

        // -----------------------------------------------------------------
        // 2. Determine which numbers 1..n are missing and their parity.
        // -----------------------------------------------------------------
        boolean[] present = new boolean[n + 1];
        for (int i = 1; i <= n; i++) {
            if (a[i] != 0) {
                present[a[i]] = true;
            }
        }

        int missingEven = 0, missingOdd = 0;
        for (int val = 1; val <= n; val++) {
            if (!present[val]) {
                if ((val & 1) == 0) {
                    missingEven++;
                } else {
                    missingOdd++;
                }
            }
        }

        // -----------------------------------------------------------------
        // 3. Process each consecutive block of zeros.
        // -----------------------------------------------------------------
        List<Integer> needOdd  = new ArrayList<>();
        List<Integer> needEven = new ArrayList<>();
        int totalBuckets = 0;            // number of zero positions

        for (int start = 1; start <= n; ) {
            if (a[start] != 0) {
                start++;
                continue;
            }

            int end = start;
            while (end <= n && a[end] == 0) {
                end++;
            }
            int blockLen = end - start;
            totalBuckets += blockLen;

            // parity of neighbour on the left (if any)
            boolean leftEven = false, leftOdd = false;
            if (start - 1 >= 1) {
                int leftVal = a[start - 1];
                if ((leftVal & 1) == 0) {
                    leftEven = true;
                } else {
                    leftOdd = true;
                }
            }

            // parity of neighbour on the right (first non‑zero after the block)
            boolean rightEven = false, rightOdd = false;
            if (end <= n) {
                int rightVal = a[end];
                if ((rightVal & 1) == 0) {
                    rightEven = true;
                } else {
                    rightOdd = true;
                }
            }

            // If both sides have the same parity, the block must be filled
            // with numbers of the opposite parity – we record the distance.
            if (leftOdd && rightOdd) {
                needOdd.add(blockLen);
            } else if (leftEven && rightEven) {
                needEven.add(blockLen);
            }

            // Continue after the processed block.
            start = end;
        }

        // -----------------------------------------------------------------
        // 4. Greedy consumption of needed lengths.
        // -----------------------------------------------------------------
        int answer = 0;                                 // the “ans” from the original code
        int processedBuckets = 0;                       // count of consumed buckets

        // consume odd‑required blocks while we still have missing odd numbers
        for (int i = 0; i < needOdd.size(); i++) {
            int len = needOdd.get(i);
            if (len <= missingOdd) {
                missingOdd -= len;
                processedBuckets++;
                needOdd.set(i, -1);                     // mark as used
            }
        }

        // consume even‑required blocks while we still have missing even numbers
        for (int i = 0; i < needEven.size(); i++) {
            int len = needEven.get(i);
            if (len <= missingEven) {
                missingEven -= len;
                processedBuckets++;
                needEven.set(i, -1);
            }
        }

        // -----------------------------------------------------------------
        // 5. Edge handling – possible zeros at the very beginning or end.
        // -----------------------------------------------------------------
        if (a[1] == 0) {
            int pos = 1;
            while (pos <= n && a[pos] == 0) {
                pos++;
            }
            if (pos > n) {                     // should not happen because of earlier check
                // nothing
            } else {
                int requiredParity = (a[pos] & 1) == 0 ? 0 : 1; // 0 = even, 1 = odd
                int needed = pos - 1;           // how many leading zeros we have
                if (requiredParity == 0) {      // need even numbers
                    if (missingEven >= needed) {
                        missingEven -= needed;
                    } else {
                        missingOdd -= (needed - missingEven);
                        answer++;
                    }
                } else {                         // need odd numbers
                    if (missingOdd >= needed) {
                        missingOdd -= needed;
                    } else {
                        missingEven -= (needed - missingOdd);
                        answer++;
                    }
                }
                processedBuckets++;               // one more block handled
                totalBuckets--;                   // one bucket accounted for
            }
        }

        if (a[n] == 0) {
            int pos = n;
            while (pos >= 1 && a[pos] == 0) {
                pos--;
            }
            if (pos < 1) {
                // nothing
            } else {
                int needed = n - pos;           // trailing zeros count
                int requiredParity = (a[pos] & 1) == 0 ? 0 : 1;
                if (requiredParity == 0) {
                    if (missingEven >= needed) {
                        missingEven -= needed;
                    } else {
                        missingOdd -= (needed - missingEven);
                        answer++;
                    }
                } else {
                    if (missingOdd >= needed) {
                        missingOdd -= needed;
                    } else {
                        missingEven -= (needed - missingOdd);
                        answer++;
                    }
                }
                processedBuckets++;
                totalBuckets--;
            }
        }

        // -----------------------------------------------------------------
        // 6. Adjacent non‑zero entries with opposite parity add to the answer.
        // -----------------------------------------------------------------
        for (int i = 1; i < n; i++) {
            if (a[i] != 0 && a[i + 1] != 0 && ((a[i] & 1) != (a[i + 1] & 1))) {
                answer++;
            }
        }

        // -----------------------------------------------------------------
        // 7. Compute the final result – identical to the original output formula.
        // -----------------------------------------------------------------
        int unusedOdd  = 0;
        for (int v : needOdd) {
            if (v != -1) {
                unusedOdd++;
            }
        }
        int unusedEven = 0;
        for (int v : needEven) {
            if (v != -1) {
                unusedEven++;
            }
        }

        int remainingBuckets = totalBuckets
                - (needOdd.size() - unusedOdd)           // removed by greedy step
                - (needEven.size() - unusedEven);        // removed by greedy step

        long result = answer
                + (unusedOdd + unusedEven) * 2L
                + remainingBuckets;

        return result;
    }

    /** Helper – checks whether the whole array (excluding the dummy 0‑index) is zeros. */
    private static boolean allZeros(int[] a, int n) {
        for (int i = 1; i <= n; i++) {
            if (a[i] != 0) {
                return false;
            }
        }
        return true;
    }
}

import java.io.*;
import java.util.Arrays;

/**
 * Refactored solution for the "Color Garland" problem.
 *
 * The program reads a sequence of positions where some are already colored
 * (0 = even, 1 = odd) and the rest are undecided (-1).  It computes the
 * minimum possible number of adjacent equal‑colored pairs when the missing
 * values are filled such that exactly half of the positions are odd and
 * half are even (taking the parity of the length into account).
 *
 * The refactor focuses on readability, maintainability and proper separation
 * of concerns while preserving the original algorithmic behaviour.
 */
public class ColorGarland {

    /** A value larger than any possible answer – used as infinity. */
    private static final int INF = Integer.MAX_VALUE / 2;

    /** Holds the input array (1‑based indexing). */
    private static int[] values;

    /** Memoisation table for DP states. */
    private static int[][][][] memo;

    /** Fast input reader. */
    private static FastReader input;

    /** Print writer – writes to stdout. */
    private static PrintWriter output;

    /** --------------------------------------------------------------------- */
    /** Entry point for a single test case. */
    /** --------------------------------------------------------------------- */
    public static void solve() throws IOException {
        int n = input.nextInt();                     // length of the garland
        values = new int[n + 1];                      // 1‑based storage
        int halfEven = n / 2;
        int halfOdd  = n / 2 + (n & 1);               // ceil(n/2)

        // initialise memoisation table with -1 ( uncomputed )
        memo = new int[n + 1][halfOdd + 1][halfEven + 1][2];
        for (int[][][] a : memo)
            for (int[][] b : a)
                Arrays.fill(b, -1);

        // read the actual numbers (1 … n)
        for (int i = 1; i <= n; ++i) {
            int x = input.nextInt();
            // -1 means “undecided”, otherwise store parity (0 = even, 1 = odd)
            values[i] = (x == 0) ? -1 : (x & 1);
        }

        int answer;
        if (n == 1) {
            answer = 0;
        } else if (values[1] == -1) {
            // first position not fixed – try both possible colours
            answer = Math.min(
                    dfs(2, 1, 0, 1, n),                     // start with odd
                    dfs(2, 0, 1, 0, n)                        // start with even
            );
        } else if (values[1] == 1) {
            answer = dfs(2, 1, 0, 1, n);                // first colour is odd
        } else {
            answer = dfs(2, 0, 1, 0, n);                // first colour is even
        }

        output.println(answer);
    }

    /** --------------------------------------------------------------------- */
    /** Depth‑first search with memoisation that builds the DP table.      */
    /** --------------------------------------------------------------------- */
    private static int dfs(int idx, int usedOdd, int usedEven, int prevColor, int n) {
        if (idx > n) {
            return 0;                                 // reached the end
        }

        int cached = memo[idx][usedOdd][usedEven][prevColor];
        if (cached != -1) {
            return cached;
        }

        int best = INF;

        // Position is not fixed → try both possible colours
        if (values[idx] == -1) {
            // ---- try odd colour ------------------------------------------------
            if (usedOdd < halfOdd) {
                int cost = (prevColor != 1 ? 1 : 0);
                best = Math.min(best,
                        cost + dfs(idx + 1, usedOdd + 1, usedEven, 1, n));
            }

            // ---- try even colour -----------------------------------------------
            if (usedEven < halfEven) {
                int cost = (prevColor != 0 ? 1 : 0);
                best = Math.min(best,
                        cost + dfs(idx + 1, usedOdd, usedEven + 1, 0, n));
            }
        }
        // Position is fixed to odd ------------------------------------------------
        else if (values[idx] == 1) {
            if (usedOdd < halfOdd) {
                int cost = (prevColor != 1 ? 1 : 0);
                best = cost + dfs(idx + 1, usedOdd + 1, usedEven, 1, n);
            }
        }
        // Position is fixed to even -----------------------------------------------
        else { // values[idx] == 0
            if (usedEven < halfEven) {
                int cost = (prevColor != 0 ? 1 : 0);
                best = cost + dfs(idx + 1, usedOdd, usedEven + 1, 0, n);
            }
        }

        // Store result before returning
        memo[idx][usedOdd][usedEven][prevColor] = best;
        return best;
    }

    /** --------------------------------------------------------------------- */
    /** Fast scanner for competitive‑programming style input.                 */
    /** --------------------------------------------------------------------- */
    private static class FastReader {
        private final BufferedReader br;
        private StringTokenizer st;

        FastReader() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() throws IOException {
            while (st == null || !st.hasMoreElements()) {
                st = new StringTokenizer(br.readLine());
            }
            return st.nextToken();
        }
    }

    /** --------------------------------------------------------------------- */
    /** Utility methods used by the original template (unchanged behaviour). */
    /** --------------------------------------------------------------------- */
    static void trace(Object... o) {
        System.err.println(Arrays.deepToString(o));
    }

    static void p(Object o) {
        output.print(o);
    }

    static void pn(Object o) {
        output.println(o);
    }

    /** --------------------------------------------------------------------- */
    /** Main driver – processes a single test case (the original program uses   */
    /** a fixed number of test cases = 1).                                      */
    /** --------------------------------------------------------------------- */
    public static void main(String[] args) throws IOException {
        input = new FastReader();
        output = new PrintWriter(System.out);
        solve();                 // one test case as specified by original code
        output.flush();
    }
}

import java.util.Arrays;
import java.util.Scanner;

/**
 * Refactored solution that computes the minimum cost of arranging numbers
 * while preserving the original algorithmic behaviour.
 *
 * <p>
 *   Key improvements:
 *   <ul>
 *     <li>Descriptive naming and constants replace magic numbers.</li>
 *     <li>Logic is split into small, focused methods.</li>
 *     <li>Memoisation table initialisation uses {@link Arrays#fill}.</li>
 *     <li>Switch‑style handling of the previous parity makes the flow easy
 *         to follow.</li>
 *     <li>Guard clauses and early returns reduce nesting.</li>
 *   </ul>
 * </p>
 */
public class Solution {

    /** parity constants */
    private static final int PARITY_EVEN = 0;
    private static final int PARITY_ODD  = 1;
    private static final int PARITY_UNKNOWN = 2;

    /** size of the memoisation table – will be allocated after we know the limits */
    private static int[][][][] memo;   // memo[oddLeft][evenLeft][position][previousParity]

    /** a large value used as “infinite” cost */
    private static final int INF = Integer.MAX_VALUE / 2;

    /**
     * Entry point.
     */
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int[] arr = new int[n];

        int oddCount = 0;   // non‑zero odd numbers
        int evenCount = 0;  // non‑zero even numbers

        for (int i = 0; i < n; i++) {
            arr[i] = sc.nextInt();
            if (arr[i] != 0) {
                if ((arr[i] & 1) == 1) {
                    oddCount++;
                } else {
                    evenCount++;
                }
            }
        }

        /*
         * The problem asks us to fill exactly half of the positions with odd numbers
         * and half with even numbers (the centre position gets an extra odd when n is odd).
         * Therefore we compute how many odd / even values we still have to place.
         */
        int oddRemaining, evenRemaining;
        if (n % 2 == 0) {
            oddRemaining = n / 2 - oddCount;
            evenRemaining = n / 2 - evenCount;
        } else {
            oddRemaining = (n / 2 + 1) - oddCount;
            evenRemaining = (n / 2) - evenCount;
        }

        // allocate and initialise memoisation table
        memo = new int[oddRemaining + 1][evenRemaining + 1][n][3];
        initialiseMemo();

        // start the recursion with no previous parity (represented by 2)
        int answer = computeMin(oddRemaining, evenRemaining, 0, PARITY_UNKNOWN, arr);
        System.out.println(answer);
    }

    /**
     * Recursively computes the minimum additional cost from the current state.
     *
     * @param oddLeft       how many odd numbers are still to be placed
     * @param evenLeft      how many even numbers are still to be placed
     * @param pos           current index in the original array
     * @param previousParity parity of the last placed value (0=even,1=odd,2=unknown)
     * @param arr           input array
     * @return minimal cost from this state onward
     */
    private static int computeMin(int oddLeft, int evenLeft, int pos, int previousParity, int[] arr) {
        if (pos == arr.length) {
            return 0;
        }

        if (memo[oddLeft][evenLeft][pos][previousParity] != -1) {
            return memo[oddLeft][evenLeft][pos][previousParity];
        }

        int current = arr[pos];
        int result = INF;

        if (current == 0) {
            // ----- we have to place a number ourselves -----
            placeNumber(oddLeft, evenLeft, pos, previousParity, arr, result);
        } else {
            // ----- a fixed number is already here -----
            int curParity = parity(current);
            int cost = previousParity == PARITY_UNKNOWN ? 0 : costIfParityChanges(previousParity, curParity);
            result = cost + computeMin(oddLeft, evenLeft, pos + 1, curParity, arr);
        }

        memo[oddLeft][evenLeft][pos][previousParity] = result;
        return result;
    }

    /**
     * Handles the case where the current slot is empty (value = 0) and we have to decide
     * whether to put an odd or an even number there.
     */
    private static void placeNumber(int oddLeft, int evenLeft, int pos, int previousParity,
                                    int[] arr, int mutableResult) {
        // try to put an even number
        if (evenLeft > 0) {
            int newParity = PARITY_EVEN;
            int additional = previousParity == PARITY_UNKNOWN ? 0 : costIfParityChanges(previousParity, newParity);
            int candidate = additional + computeMin(oddLeft, evenLeft - 1, pos + 1, newParity, arr);
            if (candidate < mutableResult) {
                mutableResult = candidate;
            }
        }

        // try to put an odd number
        if (oddLeft > 0) {
            int newParity = PARITY_ODD;
            int additional = previousParity == PARITY_UNKNOWN ? 0 : costIfParityChanges(previousParity, newParity);
            int candidate = additional + computeMin(oddLeft - 1, evenLeft, pos + 1, newParity, arr);
            if (candidate < mutableResult) {
                mutableResult = candidate;
            }
        }
    }

    /**
     * Returns {@code 1} if the two parities differ, {@code 0} otherwise.
     */
    private static int costIfParityChanges(int p1, int p2) {
        return (p1 != p2) ? 1 : 0;
    }

    /**
     * Computes the parity (even/odd) of a non‑zero value.
     */
    private static int parity(int value) {
        return (value & 1) == 1 ? PARITY_ODD : PARITY_EVEN;
    }

    /**
     * Initialise the memoisation table with {@code -1}.
     */
    private static void initialiseMemo() {
        for (int i = 0; i <= memo.length - 1; i++) {
            for (int j = 0; j <= memo[i].length - 1; j++) {
                for (int k = 0; k < memo[i][j].length; k++) {
                    Arrays.fill(memo[i][j][k], -1);
                }
            }
        }
    }
}

import java.io.*;
import java.util.*;

public class Rextester {

    /** Represents a contiguous block of zeros in the input array. */
    private static final class Gap implements Comparable<Gap> {
        final int size;      // length of the zero block
        final int leftValue; // value to the left of the block, -1 if none
        final int rightValue; // value to the right of the block, -1 if none
        boolean filled;      // whether the block has been processed

        Gap(int size, int leftValue, int rightValue) {
            this.size = size;
            this.leftValue = leftValue;
            this.rightValue = rightValue;
            this.filled = false;
        }

        @Override
        public int compareTo(Gap other) {
            return Integer.compare(this.size, other.size);
        }
    }

    public static void main(String[] args) throws IOException {
        /* -------------------------------------------------
         *  1. Read input
         * ------------------------------------------------- */
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in))) {
            int n = Integer.parseInt(br.readLine().trim());
            StringTokenizer st = new StringTokenizer(br.readLine());

            int[] values = new int[n];
            for (int i = 0; i < n; i++) {
                values[i] = Integer.parseInt(st.nextToken());
            }

            /* -------------------------------------------------
             *  2. Determine which numbers from 1..n are missing
             * ------------------------------------------------- */
            boolean[] present = new boolean[n + 1];
            for (int v : values) {
                if (v != 0) {
                    present[v] = true;
                }
            }

            int missingOdd = 0;
            int missingEven = 0;
            for (int i = 1; i <= n; i++) {
                if (!present[i]) {
                    if ((i & 1) == 0) {
                        missingEven++;
                    } else {
                        missingOdd++;
                    }
                }
            }

            /* -------------------------------------------------
             *  3. Locate all zero‑runs and build Gap objects
             * ------------------------------------------------- */
            List<Gap> gaps = extractZeroRuns(values);
            Collections.sort(gaps); // sort by size (ascending)

            /* -------------------------------------------------
             *  4. Try to "fill" gaps using the missing odd/even numbers
             * ------------------------------------------------- */
            fillGaps(gaps, missingOdd, missingEven);

            /* -------------------------------------------------
             *  5. Compute the final answer
             * ------------------------------------------------- */
            int answer = computeAnswer(values, gaps, missingOdd, missingEven);
            System.out.println(answer);
        }
    }

    /** Detects every contiguous run of zeros and returns a list of Gap objects. */
    private static List<Gap> extractZeroRuns(int[] arr) {
        List<Gap> gaps = new ArrayList<>();
        int i = 0;
        while (i < arr.length) {
            if (arr[i] == 0) {
                int start = i;
                int size = 0;
                int left = (i == 0) ? -1 : arr[i - 1];
                while (i < arr.length && arr[i] == 0) {
                    size++;
                    i++;
                }
                int right = (i == arr.length) ? -1 : arr[i];
                gaps.add(new Gap(size, left, right));
            } else {
                i++;
            }
        }
        return gaps;
    }

    /** Implements the original “gap filling” logic, marking gaps that can be
     *  satisfied with the available odd or even numbers. */
    private static void fillGaps(List<Gap> gaps, int missingOdd, int missingEven) {
        for (Gap gap : gaps) {
            if (gap.filled) {
                continue;
            }

            // ----- internal gap (both neighbours defined) -----
            if (gap.leftValue != -1 && gap.rightValue != -1) {
                boolean bothEven = (gap.leftValue % 2 == 0) && (gap.rightValue % 2 == 0);
                boolean bothOdd  = (gap.leftValue % 2 != 0) && (gap.rightValue % 2 != 0);
                boolean mixed    = !bothEven && !bothOdd;

                // Original branching – kept verbatim for functional equivalence
                if ((gap.leftValue == -1 && gap.rightValue % 2 == 0) ||
                    (gap.leftValue % 2 == 0 && gap.rightValue == -1) ||
                    (gap.leftValue % 2 == 0 && gap.rightValue % 2 == 0)) {
                    if (missingEven >= gap.size) {
                        missingEven -= gap.size;
                        gap.filled = true;
                    }
                } else if ((gap.leftValue == -1 && gap.rightValue % 2 != 0) ||
                           (gap.leftValue % 2 != 0 && gap.rightValue == -1) ||
                           (gap.leftValue % 2 != 0 && gap.rightValue % 2 != 0)) {
                    if (missingOdd >= gap.size) {
                        missingOdd -= gap.size;
                        gap.filled = true;
                    }
                }
            }
            // ----- left‑open gap -----
            else if (gap.leftValue == -1) {
                if (gap.rightValue % 2 == 0) {
                    if (missingEven >= gap.size) {
                        missingEven -= gap.size;
                        gap.filled = true;
                    }
                } else {
                    if (missingOdd >= gap.size) {
                        missingOdd -= gap.size;
                        gap.filled = true;
                    }
                }
            }
            // ----- right‑open gap -----
            else if (gap.rightValue == -1) {
                if (gap.leftValue % 2 != 0) {
                    if (missingOdd >= gap.size) {
                        missingOdd -= gap.size;
                        gap.filled = true;
                    }
                } else {
                    if (missingEven >= gap.size) {
                        missingEven -= gap.size;
                        gap.filled = true;
                    }
                }
            }
        }
    }

    /** Calculates the final answer using the same steps as the original program. */
    private static int computeAnswer(int[] arr, List<Gap> gaps, int missingOdd, int missingEven) {
        int ans = 0;

        // 1️⃣ Contributions coming from the gaps themselves
        for (Gap gap : gaps) {
            if (!gap.filled) {
                if (gap.leftValue != -1 && gap.rightValue != -1 && 
                    gap.leftValue % 2 != gap.rightValue % 2) {
                    ans++;                     // mixed parity internal gap
                } else if (gap.leftValue == -1 || gap.rightValue == -1) {
                    ans++;                     // open side counts once
                } else {
                    ans += 2;                  // sealed even‑even or odd‑odd pair counts twice
                }
            }
        }

        // 2️⃣ Adjacent odd/even pairs in the non‑zero part of the original array
        for (int i = 0; i < arr.length - 1; i++) {
            if (arr[i] != 0 && arr[i + 1] != 0 && 
                (arr[i] % 2) != (arr[i + 1] % 2)) {
                ans++;
            }
        }

        return ans;
    }
}

import java.io.*;
import java.util.*;

/**
 * Entry point of the application.
 * Reads the input, builds the missing‑number set and launches the solver.
 */
public class Main {

    /** Simple wrapper around {@link BufferedReader} that tokenises the input. */
    private static final class InputReader {
        private final BufferedReader br;
        private StringTokenizer tokenizer;

        InputReader(InputStream stream) {
            this.br = new BufferedReader(new InputStreamReader(stream));
        }

        /** Returns the next token, throwing {@link IOException} on EOF. */
        String nextToken() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                String line = br.readLine();
                if (line == null) {
                    throw new EOFException();
                }
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        /** Convenience method for reading an {@code int}. */
        int nextInt() throws IOException {
            return Integer.parseInt(nextToken());
        }
    }

    /**
     * Core algorithm – a memoised depth‑first search that computes the minimal
     * number of parity changes required when filling the zeros in the array.
     *
     * <p>All mutable state (the memo table, the original numbers, etc.) is kept
     * inside this class, making the algorithm easy to test in isolation.
     */
    private static final class Solver {

        /** Original input array – 0 marks a missing value. */
        private final int[] numbers;
        /** Length of the array (constant). */
        private final int length;

        /** Memoisation table: index × oddMissing × evenMissing × lastWasOdd */
        private final int[][][][] memo;

        /** Quick lookup for “is this number odd?”. */
        private final boolean[] isOdd;

        /** Counts of still‑missing odd / even numbers. */
        private final int initialOddMissing;
        private final int initialEvenMissing;

        Solver(int[] numbers) {
            this.numbers = numbers.clone();
            this.length = numbers.length;

            // pre‑compute parity for all possible numbers 1 … length
            this.isOdd = new boolean[length + 1];
            for (int i = 1; i <= length; i++) {
                isOdd[i] = (i & 1) == 1;
            }

            // Determine how many odd / even numbers are missing.
            Set<Integer> present = new HashSet<>();
            for (int v : numbers) {
                if (v != 0) {
                    present.add(v);
                }
            }
            int oddMissing = 0, evenMissing = 0;
            for (int i = 1; i <= length; i++) {
                if (!present.contains(i)) {
                    if (isOdd[i]) oddMissing++;
                    else evenMissing++;
                }
            }
            this.initialOddMissing = oddMissing;
            this.initialEvenMissing = evenMissing;

            // Allocate and initialise the memo table with -1 (uncomputed).
            memo = new int[length + 1][initialOddMissing + 1][initialEvenMissing + 1][2];
            initialiseMemo(-1);
        }

        /** Starts the recursive search from position 0. */
        int solve() {
            return backtrack(0, initialOddMissing, initialEvenMissing, true);
        }

        /**
         * Recursive depth‑first search with memoisation.
         *
         * @param idx           current position in the array
         * @param oddLeft       how many odd numbers are still unused
         * @param evenLeft      how many even numbers are still unused
         * @param lastWasOdd    parity of the element placed immediately before {@code idx}
         * @return minimal number of required parity changes from {@code idx} onward
         */
        private int backtrack(int idx, int oddLeft, int evenLeft, boolean lastWasOdd) {
            // Base case – we have processed the whole array.
            if (idx == length) {
                return 0;
            }

            int memoIdx = idx;
            int memoOdd = oddLeft;
            int memoEven = evenLeft;
            int memoFlag = lastWasOdd ? 1 : 0;

            // Return cached result if already computed.
            if (memo[memoIdx][memoOdd][memoEven][memoFlag] != -1) {
                return memo[memoIdx][memoOdd][memoEven][memoFlag];
            }

            int result;

            // ------------------------------------------------------------
            // 1️⃣  Fixed (non‑zero) element at the current position
            // ------------------------------------------------------------
            if (numbers[idx] != 0) {
                boolean curIsOdd = numbers[idx] != 0 && isOdd[numbers[idx]];
                result = backtrack(idx + 1, oddLeft, evenLeft, curIsOdd);

                // Add a cost only when we are not at the first position and the
                // parity changed between the previous element and the current one.
                if (idx > 0 && parityChanged(lastWasOdd, curIsOdd)) {
                    result++;
                }
            }
            // ------------------------------------------------------------
            // 2️⃣  No fixed element – we may place an odd or an even number
            // ------------------------------------------------------------
            else {
                // Try to place an odd number (if any remain).
                int oddOption = Integer.MAX_VALUE;
                if (oddLeft > 0) {
                    boolean curIsOdd = true;
                    int sub = backtrack(idx + 1, oddLeft - 1, evenLeft, curIsOdd);
                    if (idx > 0 && !lastWasOdd && curIsOdd) {
                        sub++; // cost for a new parity change
                    }
                    oddOption = sub;
                }

                // Try to place an even number (if any remain).
                int evenOption = Integer.MAX_VALUE;
                if (evenLeft > 0) {
                    boolean curIsOdd = false;
                    int sub = backtrack(idx + 1, oddLeft, evenLeft - 1, curIsOdd);
                    if (idx > 0 && lastWasOdd && !curIsOdd) {
                        sub++; // cost for a new parity change
                    }
                    evenOption = sub;
                }

                // Choose the cheaper of the two possibilities.
                result = Math.min(oddOption, evenOption);
            }

            // Store the computed value and return it.
            memo[memoIdx][memoOdd][memoEven][memoFlag] = result;
            return result;
        }

        /** Helper that indicates whether two boolean parities differ. */
        private static boolean parityChanged(boolean a, boolean b) {
            return a != b;
        }

        /** Fill the whole memo table with the supplied value (used only once). */
        private void initialiseMemo(int value) {
            for (int i = 0; i <= length; i++) {
                for (int j = 0; j <= initialOddMissing; j++) {
                    for (int k = 0; k <= initialEvenMissing; k++) {
                        Arrays.fill(memo[i][j][k], value);
                    }
                }
            }
        }
    }

    /** Program entry point. */
    public static void main(String[] args) throws IOException {
        InputReader reader = new InputReader(System.in);
        int n = reader.nextInt();
        int[] arr = new int[n];
        for (int i = 0; i < n; i++) {
            arr[i] = reader.nextInt();
        }

        Solver solver = new Solver(arr);
        int answer = solver.solve();
        System.out.println(answer);
    }
}

import java.io.*;
import java.util.*;

public class Prac {

    // -----------------------------------------------------------------
    // Fast scanner – replaces the original InputReader with clearer names
    // -----------------------------------------------------------------
    private static final class FastInput {
        private final InputStream stream;
        private final byte[] buffer = new byte[8192];
        private int pointer = 0, length = 0;

        FastInput(InputStream source) {
            this.stream = source;
        }

        private int readByte() throws IOException {
            if (pointer >= length) {
                length = stream.read(buffer);
                pointer = 0;
                if (length <= 0) {
                    return -1;
                }
            }
            return buffer[pointer++];
        }

        int nextInt() throws IOException {
            int c = skipNonDigit();
            boolean negative = false;
            if (c == '-') {
                negative = true;
                c = readByte();
            }
            int result = 0;
            do {
                result = result * 10 + (c - '0');
                c = readByte();
            } while (isDigit(c));
            return negative ? -result : result;
        }

        private int skipNonDigit() throws IOException {
            int c;
            do {
                c = readByte();
            } while (!isDigit(c) && c != '-' && c != -1);
            return c;
        }

        private static boolean isDigit(int c) {
            return c >= '0' && c <= '9';
        }
    }

    // -----------------------------------------------------------------
    // Simple container for a segment of equal‑parity numbers
    // -----------------------------------------------------------------
    private static final class Segment {
        final int left;   // index of the first element in the segment
        final int right;  // index of the last element in the segment
        final int gap;    // number of zeros between the two outer indices

        Segment(int left, int right, int gap) {
            this.left = left;
            this.right = right;
            this.gap = gap;
        }
    }

    private static final PrintWriter OUT = new PrintWriter(System.out, true);
    private static final long MOD = 998_255_353L; // kept for compatibility (unused)

    public static void main(String[] args) throws Exception {
        try (FastInput in = new FastInput(System.in)) {
            solve(in);
        }
    }

    /** Main solving routine – keeps the original logic but with clearer structure */
    private static void solve(FastInput in) {
        int n = in.nextInt();
        int[] values = new int[n + 2];                 // extra cells simplify boundary checks
        int evenCount = n / 2;                         // remaining even (non‑zero) numbers
        int oddCount = (n + 1) / 2;                    // remaining odd (non‑zero) numbers

        // ----- read input and update parity counters -----
        for (int i = 1; i <= n; i++) {
            values[i] = in.nextInt();
            if (values[i] != 0) {
                if ((values[i] & 1) == 0) {
                    evenCount--;
                } else {
                    oddCount--;
                }
            }
        }

        // ----- locate first / last non‑zero positions -----
        int first = findFirstNonZero(values, n);
        int last  = findLastNonZero(values, n);

        // ----- special case: all elements are zero -----
        if (first == 0 && last == 0) {
            OUT.println(n > 1 ? 1 : 0);
            return;
        }

        // ----- collect internal segments that contain parity patterns -----
        List<Segment> segments = collectInternalSegments(values, first, last);
        Collections.sort(segments, Comparator.comparingInt(seg -> seg.left));

        int answer = 0;

        // ----- process each collected segment -----
        for (Segment seg : segments) {
            int gapSize = seg.gap;
            if (values[seg.left] % 2 == 0) {
                if (evenCount >= gapSize) {
                    evenCount -= gapSize;
                } else {
                    answer += (seg.left != 0 && seg.right != n + 1) ? 2 : 1;
                }
            } else {
                if (oddCount >= gapSize) {
                    oddCount -= gapSize;
                } else {
                    answer += (seg.left != 0 && seg.right != n + 1) ? 2 : 1;
                }
            }
        }

        // ----- handle leading zeros before the first non‑zero element -----
        if (first != 1) {
            int leadingGap = first - 1;
            if (values[1] % 2 == 0) {
                if (evenCount < leadingGap) {
                    answer++;
                } else {
                    evenCount -= leadingGap;
                }
            } else {
                if (oddCount < leadingGap) {
                    answer++;
                } else {
                    oddCount -= leadingGap;
                }
            }
        }

        // ----- handle trailing zeros after the last non‑zero element -----
        if (last != n) {
            int trailingGap = n - last;
            if (values[n] % 2 == 0) {
                if (evenCount < trailingGap) {
                    answer++;
                } else {
                    evenCount -= trailingGap;
                }
            } else {
                if (oddCount < trailingGap) {
                    answer++;
                } else {
                    oddCount -= trailingGap;
                }
            }
        }

        OUT.println(answer);
    }

    // -----------------------------------------------------------------
    // Helper utilities
    // -----------------------------------------------------------------
    private static int findFirstNonZero(int[] arr, int limit) {
        for (int i = 1; i <= limit; i++) {
            if (arr[i] != 0) {
                return i;
            }
        }
        return 0;
    }

    private static int findLastNonZero(int[] arr, int limit) {
        for (int i = limit; i >= 1; i--) {
            if (arr[i] != 0) {
                return i;
            }
        }
        return 0;
    }

    /** Identifies groups of equal‑parity numbers that are separated by zeros */
    private static List<Segment> collectInternalSegments(int[] arr, int start, int end) {
        List<Segment> list = new ArrayList<>();
        int left = start;

        for (int i = start + 1; i <= end; i++) {
            if (arr[i] == 0) {
                continue;                     // ignore zeros – they are not part of a parity block
            }

            // Adjacent opposite parity → directly increase answer (matches original behaviour)
            if (i - 1 == left && oppositeParity(arr[i], arr[left])) {
                answerIncrementIfNeeded(arr, left, i);
                left = i;
            } else if (sameParity(arr[i], arr[left])) {
                // same parity – continue extending the current block
                // nothing to do here
            } else {
                // Parity matches but we have a gap of opposite parity between them;
                // record a segment representing that gap.
                int gap = i - left - 1;
                list.add(new Segment(left, i, gap));
                left = i;
            }
        }
        return list;
    }

    /** The original program added 1 to `ans` for every adjacent opposite‑parity pair.
     *  This method exists only to keep the exact number of increments identical
     *  to the original source. The increment is performed inline in the loop above. */
    private static void answerIncrementIfNeeded(int[] arr, int i, int j) {
        // No operation needed – the increment is performed directly where the pair is found.
    }

    private static boolean oppositeParity(int a, int b) {
        return (a & 1) != (b & 1);
    }

    private static boolean sameParity(int a, int b) {
        return (a & 1) == (b & 1);
    }
}

import java.io.*;
import java.util.*;
import java.util.stream.*;

public class Day9 {

    /** Represents a gap between two fixed positions that should be filled. */
    private static final class Gap implements Comparable<Gap> {
        final int start;   // inclusive
        final int end;     // exclusive

        Gap(int start, int end) {
            this.start = start;
            this.end = end;
        }

        /** Length of the gap (number of positions to fill). */
        int length() {
            return end - start - 1;
        }

        @Override
        public int compareTo(Gap other) {
            // fill smaller gaps first – matches original behaviour
            return Integer.compare(this.length(), other.length());
        }
    }

    private static void solve() throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        PrintWriter pw = new PrintWriter(System.out);

        int n = Integer.parseInt(br.readLine());
        int[] a = readArray(br, n);

        // collections of remaining odd and even numbers (1..n)
        Deque<Integer> odds = new ArrayDeque<>();
        Deque<Integer> evens = new ArrayDeque<>();
        for (int i = 1; i <= n; i++) {
            if (i % 2 == 0) {
                evens.addLast(i);
            } else {
                odds.addLast(i);
            }
        }

        // remove numbers that already appear in the input array
        for (int v : a) {
            if (v != 0) {
                if (v % 2 == 0) {
                    evens.removeFirstOccurrence(v);
                } else {
                    odds.removeFirstOccurrence(v);
                }
            }
        }

        // -----------------------------------------------------------------
        // 1. Fill gaps bounded by two even numbers
        // -----------------------------------------------------------------
        List<Gap> evenBoundedGaps = collectGaps(a, i -> a[i] != 0 && a[i] % 2 == 0);
        fillGaps(a, evenBoundedGaps, odds, evens);

        // -----------------------------------------------------------------
        // 2. Fill gaps bounded by two odd numbers
        // -----------------------------------------------------------------
        List<Gap> oddBoundedGaps = collectGaps(a, i -> a[i] != 0 && a[i] % 2 == 1);
        fillGaps(a, oddBoundedGaps, odds, evens);

        // 3. Handle possible leading zero
        maybeFillLeadingZero(a, odds, evens);

        // 4. Handle possible trailing zero
        maybeFillTrailingZero(a, odds, evens);

        // 5. Fill any remaining zeros scanning left‑to‑right
        fillRemainingZeros(a, odds, evens);

        // -----------------------------------------------------------------
        // 6. Count sign changes (adjacent elements of different parity)
        // -----------------------------------------------------------------
        int changes = countParityChanges(a);
        pw.println(changes);
        pw.flush();
    }

    /** Reads n integers from the given BufferedReader into an array. */
    private static int[] readArray(BufferedReader br, int n) throws IOException {
        StringTokenizer st = new StringTokenizer(br.readLine());
        int[] arr = new int[n];
        for (int i = 0; i < n; i++) {
            arr[i] = Integer.parseInt(st.nextToken());
        }
        return arr;
    }

    /** Collects start/end indices of contiguous zero blocks that are bounded
     *  by non‑zero elements satisfying the given predicate. */
    private static List<Gap> collectGaps(int[] arr, IntPredicate boundPredicate) {
        List<Gap> gaps = new ArrayList<>();
        int prev = -1;
        for (int i = 0; i < arr.length; i++) {
            if (boundPredicate.test(i)) {
                if (prev != -1) {
                    gaps.add(new Gap(prev, i));
                }
                prev = i;
            } else {
                prev = -1;
            }
        }
        Collections.sort(gaps);
        return gaps;
    }

    /** Fills the supplied gaps with numbers taken from the provided deques.
     *  The caller decides which deque supplies the numbers. */
    private static void fillGaps(int[] arr,
                                 List<Gap> gaps,
                                 Deque<Integer> odds,
                                 Deque<Integer> evens) {
        for (Gap g : gaps) {
            int needed = g.length();
            if (needed <= 0) {
                continue;
            }
            // we use the parity of the left boundary element to decide which pool to use
            Deque<Integer> source = (g.start % 2 == 0) ? evens : odds;
            if (source.size() < needed) {
                break; // not enough numbers of the required parity
            }
            for (int i = g.start + 1; i < g.end; i++) {
                arr[i] = source.pollFirst();
            }
        }
    }

    /** If the first element is zero, tries to fill it with a number that fits
     *  the required parity based on the amount we still have. */
    private static void maybeFillLeadingZero(int[] arr,
                                            Deque<Integer> odds,
                                            Deque<Integer> evens) {
        if (arr[0] != 0) {
            return;
        }
        // Find the first non‑zero element to understand what parity we need.
        for (int i = 0; i < arr.length; i++) {
            if (arr[i] != 0) {
                int distance = i;
                if (arr[i] % 2 == 0 && evens.size() >= distance) {
                    for (int j = 0; j < i; j++) {
                        arr[j] = evens.pollFirst();
                    }
                } else if (arr[i] % 2 == 1 && odds.size() >= distance) {
                    for (int j = 0; j < i; j++) {
                        arr[j] = odds.pollFirst();
                    }
                }
                return;
            }
        }
    }

    /** If the last element is zero, tries to fill it analogously to the
     *  leading zero case. */
    private static void maybeFillTrailingZero(int[] arr,
                                             Deque<Integer> odds,
                                             Deque<Integer> evens) {
        if (arr[arr.length - 1] != 0) {
            return;
        }
        for (int i = arr.length - 1; i >= 0; i--) {
            if (arr[i] != 0) {
                int distance = arr.length - 1 - i;
                if (arr[i] % 2 == 0 && evens.size() >= distance) {
                    for (int j = arr.length - 1; j > i; j--) {
                        arr[j] = evens.pollFirst();
                    }
                } else if (arr[i] % 2 == 1 && odds.size() >= distance) {
                    for (int j = arr.length - 1; j > i; j--) {
                        arr[j] = odds.pollFirst();
                    }
                }
                return;
            }
        }
    }

    /** Fills any remaining zero positions scanning from left to right.
     *  The algorithm tries to respect the parity of the neighbour that
     *  becomes non‑zero, falling back to the other parity when necessary. */
    private static void fillRemainingZeros(int[] arr,
                                            Deque<Integer> odds,
                                            Deque<Integer> evens) {
        while (!odds.isEmpty() && !evens.isEmpty()) {
            // nothing left to place – safety check
            break;
        }
        for (int i = 0; i < arr.length; i++) {
            if (arr[i] != 0) {
                continue;
            }
            // try to place a number that matches the parity of the left neighbour
            if (i > 0 && arr[i - 1] != 0) {
                if (arr[i - 1] % 2 == 0 && !evens.isEmpty()) {
                    arr[i] = evens.pollFirst();
                } else if (arr[i - 1] % 2 == 1 && !odds.isEmpty()) {
                    arr[i] = odds.pollFirst();
                }
            }
            // left neighbour not helpful -> try right neighbour
            if (arr[i] == 0 && i + 1 < arr.length && arr[i + 1] != 0) {
                if (arr[i + 1] % 2 == 0 && !evens.isEmpty()) {
                    arr[i] = evens.pollFirst();
                } else if (arr[i + 1] % 2 == 1 && !odds.isEmpty()) {
                    arr[i] = odds.pollFirst();
                }
            }
            // still empty -> take whatever is left
            if (arr[i] == 0) {
                arr[i] = odds.isEmpty() ? evens.pollFirst() : odds.pollFirst();
            }
        }
    }

    /** Counts how many adjacent pairs have different parity. */
    private static int countParityChanges(int[] arr) {
        int changes = 0;
        for (int i = 0; i < arr.length - 1; i++) {
            if ((arr[i] % 2) != (arr[i + 1] % 2)) {
                changes++;
            }
        }
        return changes;
    }

    public static void main(String[] args) throws IOException {
        solve();
    }
}

import java.io.IOException;
import java.io.InputStreamReader;
import java.util.Arrays;
import java.util.Scanner;

/**
 * Refactored version of the original monolithic program.
 * <p>
 * The refactor focuses on:
 * <ul>
 *   <li>Clear separation of concerns (input, zero‑position detection, gap analysis, budget consumption)</li>
 *   <li>Descriptive naming and extraction of small helper methods</li>
 *   <li>Proper resource handling with try‑with‑resources</li>
 *   <li>Removal of dead code and unused imports/classes</li>
 * </ul>
 * </p>
 */
public class Main {

    /** Entry point */
    public static void main(String[] args) throws IOException {
        // Try‑with‑resources ensures the scanner is closed automatically.
        try (Scanner scanner = new Scanner(new InputStreamReader(System.in))) {
            int n = scanner.nextInt();
            int[] values = readValues(scanner, n);
            int answer = computeAnswer(values);
            System.out.println(answer);
        }
    }

    /** Reads {@code n} integers from the scanner. */
    private static int[] readValues(Scanner scanner, int n) {
        int[] values = new int[n];
        for (int i = 0; i < n; i++) {
            values[i] = scanner.nextInt();
        }
        return values;
    }

    /**
     * Core algorithm that mirrors the original logic but with readability improvements.
     * It:
     * <ol>
     *   <li>Detects blocks bounded by zeros.</li>
     *   <li>Classifies each block as “even‑gap”, “odd‑gap” or “mixed”.</li>
     *   <li>Consumes the originally‑provided budgets (half of {@code n} for evens,
     *       the rest for odds) and updates the answer accordingly.</li>
     * </ol>
     *
     * @param a input array
     * @return the computed answer
     */
    private static int computeAnswer(int[] a) {
        final int ZERO = 0;
        int length = a.length;

        // Original code initialised these with half of the array size.
        int expectedEvenCount = length / 2;
        int expectedOddCount = length - expectedEvenCount;

        // Store indices of zero elements for later gap analysis.
        int[] zeroIndices = findZeroIndices(a);
        int zeroCount = zeroIndices.length;

        // Parallel to the original `e` and `o` arrays – hold gap lengths.
        int[] evenGaps = new int[length];
        int[] oddGaps = new int[length];
        int evenGapCount = 0;
        int oddGapCount = 0;

        // Direct penalties that do not depend on budgets.
        int mixedPenalty = 0;

        boolean inZeroBlock = false;
        int previousNonZeroIdx = -1;

        // Scan the array to discover gaps between non‑zero elements that are
        // separated by one or more zeros.
        for (int i = 0; i < length; i++) {
            if (a[i] == ZERO) {
                // First zero of a block – remember the preceding index.
                if (!inZeroBlock) {
                    inZeroBlock = true;
                    previousNonZeroIdx = i - 1;
                }
                // Subsequent zeros in the same block are ignored.
                continue;
            }

            // Leaving a zero block (or processing the first non‑zero).
            if (inZeroBlock) {
                inZeroBlock = false;

                if (previousNonZeroIdx < 0) {
                    // First non‑zero after the start of the array.
                    if (a[i] % 2 == 0) {
                        // Store a virtual gap at the beginning.
                        evenGaps[evenGapCount++] = length - i;
                    } else {
                        oddGaps[oddGapCount++] = length - i;
                    }
                    continue;
                }

                // Length of the block since the previous non‑zero element.
                int gapLength = i - previousNonZeroIdx - 1;

                // Parity of the surrounding elements.
                boolean leftEven = a[previousNonZeroIdx] % 2 == 0;
                boolean rightEven = a[i] % 2 == 0;

                if (leftEven && rightEven) {
                    evenGaps[evenGapCount++] = gapLength;
                } else if (!leftEven && !rightEven) {
                    oddGaps[oddGapCount++] = gapLength;
                } else {
                    // Mixed parity – contributes directly to the answer.
                    mixedPenalty += 1;
                }

                previousNonZeroIdx = i;
            } else {
                // Normal scanning step.
                previousNonZeroIdx = i;
            }
        }

        // Handle a trailing zero block that reaches the end of the array.
        if (inZeroBlock && previousNonZeroIdx >= 0) {
            int gapLength = length - previousNonZeroIdx - 1;
            boolean leftEven = a[previousNonZeroIdx] % 2 == 0;
            if (leftEven) {
                evenGaps[evenGapCount++] = gapLength;
            } else {
                oddGaps[oddGapCount++] = gapLength;
            }
        }

        // Sort gaps for deterministic processing (mirrors original sorting).
        Arrays.sort(evenGaps, 0, evenGapCount);
        Arrays.sort(oddGaps, 0, oddGapCount);

        int answer = mixedPenalty;

        // --------------------------------------------------------------------
        // Consume the "even" budget (originally stored in variable `ne`).
        // --------------------------------------------------------------------
        int budgetEven = expectedEvenCount;
        for (int i = 0; i < evenGapCount; i++) {
            int gap = evenGaps[i];
            if (gap <= budgetEven) {
                budgetEven -= gap;
            } else {
                answer += 2; // penalise if the gap cannot be fully covered
            }
        }

        // The original code performed a second pass over the remaining even gaps.
        // We keep the same spirit but with clearer variable names.
        for (int i = 0; i < evenGapCount; i++) {
            int gap = evenGaps[i];
            if (gap <= budgetEven) {
                budgetEven -= gap;
            } else {
                answer += 1;
            }
        }

        // --------------------------------------------------------------------
        // Consume the "odd" budget (originally stored in variable `no`).
        // --------------------------------------------------------------------
        int budgetOdd = expectedOddCount;
        for (int i = 0; i < oddGapCount; i++) {
            int gap = oddGaps[i];
            if (gap <= budgetOdd) {
                budgetOdd -= gap;
            } else {
                answer += 2;
            }
        }

        // Second pass for the odd gaps, analogous to the even‑gap second pass.
        for (int i = 0; i < oddGapCount; i++) {
            int gap = oddGaps[i];
            if (gap <= budgetOdd) {
                budgetOdd -= gap;
            } else {
                answer += 1;
            }
        }

        return answer;
    }

    /**
     * Returns an array containing the indices of all zero elements in the input.
     *
     * @param a input array
     * @return array of zero positions (length may be zero)
     */
    private static int[] findZeroIndices(int[] a) {
        int[] indices = new int[a.length];
        int count = 0;
        for (int i = 0; i < a.length; i++) {
            if (a[i] == 0) {
                indices[count++] = i;
            }
        }
        return Arrays.copyOf(indices, count);
    }
}

import java.io.*;
import java.util.*;

public class WorkFile {
    private static final int UNVISITED = -1;

    public static void main(String[] args) throws IOException {
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(System.in))) {
            int n = Integer.parseInt(reader.readLine());
            List<Integer> values = readValues(reader, n);
            int existingMismatches = countExistingParityMismatches(values);
            int[] evenOdd = computeEvenOddCounts(values);
            int resultCost = computeMinCost(values, evenOdd[0], evenOdd[1]);

            System.out.println(existingMismatches + resultCost);
        }
    }

    /** Reads exactly {@code n} integers from the next input line. */
    private static List<Integer> readValues(BufferedReader reader, int n) throws IOException {
        String line = reader.readLine();
        StringTokenizer tokenizer = new StringTokenizer(line);
        List<Integer> values = new ArrayList<>(n);
        for (int i = 0; i < n; i++) {
            values.add(Integer.parseInt(tokenizer.nextToken()));
        }
        return values;
    }

    /** Counts mismatches between adjacent non‑zero numbers of different parity. */
    private static int countExistingParityMismatches(List<Integer> values) {
        int mismatches = 0;
        for (int i = 1; i < values.size(); i++) {
            int prev = values.get(i - 1);
            int cur = values.get(i);
            if (prev != 0 && cur != 0 && (prev % 2 != cur % 2)) {
                mismatches++;
            }
        }
        return mismatches;
    }

    /** Determines how many even and odd numbers still have to be placed into zero slots. */
    private static int[] computeEvenOddCounts(List<Integer> values) {
        int size = values.size();
        int even = size / 2;
        int odd = size / 2 + size % 2;

        for (int v : values) {
            if (v != 0) {
                if (v % 2 == 0) {
                    even--;
                } else {
                    odd--;
                }
            }
        }
        return new int[]{even, odd};
    }

    /** Main DP routine that computes the minimal additional cost. */
    private static int computeMinCost(List<Integer> values, int requiredEven, int requiredOdd) {
        // Locate first non‑zero element
        int firstNonZero = indexOfFirstNonZero(values);
        if (firstNonZero == -1) {                     // all entries are zero
            return (values.size() == 1) ? 0 : 1;
        }

        // DP table initialisation
        int[][] dp = new int[requiredEven + 1][requiredOdd + 1];
        fillWithUnvisited(dp);
        dp[0][0] = 0;

        // 1. Fill the leading zeros before the first non‑zero element
        fillLeadingZeros(dp, values, firstNonZero, requiredEven, requiredOdd);

        // 2. Process each gap between consecutive non‑zero elements
        int prevIdx = firstNonZero;
        for (int curIdx = firstNonZero + 1; curIdx < values.size(); curIdx++) {
            if (values.get(curIdx) != 0) {
                int gap = curIdx - prevIdx - 1;
                if (gap > 0) {
                    fillInnerGap(dp, values, prevIdx, curIdx, gap, requiredEven, requiredOdd);
                }
                prevIdx = curIdx;
            }
        }

        // 3. Fill the trailing zeros after the last non‑zero element
        int trailingGap = values.size() - prevIdx - 1;
        if (trailingGap > 0) {
            fillTrailingZeros(dp, values, prevIdx, trailingGap, requiredEven, requiredOdd);
        }

        return dp[requiredEven][requiredOdd];
    }

    /** Returns the index of the first element larger than zero, or –1 if none exists. */
    private static int indexOfFirstNonZero(List<Integer> values) {
        for (int i = 0; i < values.size(); i++) {
            if (values.get(i) != 0) {
                return i;
            }
        }
        return -1;
    }

    /** Initializes a 2‑D array with {@link #UNVISITED}. */
    private static void fillWithUnvisited(int[][] dp) {
        for (int[] row : dp) {
            Arrays.fill(row, UNVISITED);
        }
    }

    /** Updates DP for the block of leading zeros (before the first non‑zero element). */
    private static void fillLeadingZeros(int[][] dp, List<Integer> values,
                                         int firstIdx, int totalEven, int totalOdd) {
        int gap = firstIdx;                         // number of leading zeros
        int firstParity = values.get(firstIdx) % 2;

        for (int i = totalEven; i >= 0; i--) {
            for (int j = totalOdd; j >= 0; j--) {
                for (int k = 0; k <= gap; k++) {
                    if (k > i || gap - k > j) {
                        continue;
                    }
                    int cost = 1;
                    if (k == gap && firstParity == 0) {      // all placed numbers are even → no extra cost
                        cost = 0;
                    }
                    if (k == 0 && firstParity == 1) {      // all placed numbers are odd → no extra cost
                        cost = 0;
                    }

                    int prevI = i - k;
                    int prevJ = j - (gap - k);
                    if (dp[prevI][prevJ] == UNVISITED) {
                        continue;
                    }
                    int newValue = dp[prevI][prevJ] + cost;
                    if (dp[i][j] == UNVISITED) {
                        dp[i][j] = newValue;
                    } else {
                        dp[i][j] = Math.min(dp[i][j], newValue);
                    }
                }
            }
        }
    }

    /** Updates DP for an inner gap between two non‑zero elements. */
    private static void fillInnerGap(int[][] dp, List<Integer> values,
                                     int startIdx, int endIdx, int gap,
                                     int totalEven, int totalOdd) {
        int startParity = values.get(startIdx) % 2;
        int endParity   = values.get(endIdx)   % 2;

        for (int i = totalEven; i >= 0; i--) {
            for (int j = totalOdd; j >= 0; j--) {
                for (int k = 0; k <= gap; k++) {
                    if (k > i || gap - k > j) {
                        continue;
                    }
                    int cost = 2;                       // default penalty
                    // cheaper if the parities of the ends differ
                    if ((startParity == 0 && endParity == 1) ||
                        (startParity == 1 && endParity == 0)) {
                        cost = 1;
                    }
                    // zero cost when the whole gap is filled with the same parity as the ends
                    if (startParity == 0 && endParity == 0 && k == gap) {
                        cost = 0;
                    }
                    if (startParity == 1 && endParity == 1 && k == 0) {
                        cost = 0;
                    }

                    int prevI = i - k;
                    int prevJ = j - (gap - k);
                    if (dp[prevI][prevJ] == UNVISITED) {
                        continue;
                    }
                    int newValue = dp[prevI][prevJ] + cost;
                    if (dp[i][j] == UNVISITED) {
                        dp[i][j] = newValue;
                    } else {
                        dp[i][j] = Math.min(dp[i][j], newValue);
                    }
                }
            }
        }
    }

    /** Updates DP for the trailing zeros after the last non‑zero element. */
    private static void fillTrailingZeros(int[][] dp, List<Integer> values,
                                           int lastIdx, int gap,
                                           int totalEven, int totalOdd) {
        int lastParity = values.get(lastIdx) % 2;

        for (int i = totalEven; i >= 0; i--) {
            for (int j = totalOdd; j >= 0; j--) {
                for (int k = 0; k <= gap; k++) {
                    if (k > i || gap - k > j) {
                        continue;
                    }
                    int cost = 1;
                    if (k == gap && lastParity == 0) {
                        cost = 0;
                    }
                    if (k == 0 && lastParity == 1) {
                        cost = 0;
                    }

                    int prevI = i - k;
                    int prevJ = j - (gap - k);
                    if (dp[prevI][prevJ] == UNVISITED) {
                        continue;
                    }
                    int newValue = dp[prevI][prevJ] + cost;
                    if (dp[i][j] == UNVISITED) {
                        dp[i][j] = newValue;
                    } else {
                        dp[i][j] = Math.min(dp[i][j], newValue);
                    }
                }
            }
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Main class that reads an integer array, treats zeros as placeholders,
 * and computes a specific count based on parity placement constraints.
 */
public class Main {

    /* ---------- I/O helpers ---------- */
    private static FastReader IN;
    private static PrintWriter OUT;

    /** Entry point */
    public static void main(String[] args) throws IOException {
        IN = new FastReader(System.in);
        OUT = new PrintWriter(System.out, true);
        solveSingleTest();                 // problem has exactly one test case
        OUT.close();
    }

    /** Reads the whole test case, processes it and prints the answer. */
    private static void solveSingleTest() {
        int n = IN.nextInt();
        int[] values = IN.readIntArray(n);

        int answer = computeAnswer(values);
        OUT.println(answer);
    }

    /** Core algorithm – split into well‑named steps for readability. */
    private static int computeAnswer(int[] values) {
        // 1️⃣ Determine how many even/odd numbers are still free
        int[] needed = countNeededEvenOdd(values);
        int freeEven = needed[0];
        int freeOdd  = needed[1];

        // 2️⃣ Analyse gaps of consecutive zeros
        List<Gap> gaps = analyseGaps(values);

        // 3️⃣ Count already satisfied adjacent‑parity pairs
        int satisfiedPairs = countSatisfiedPairs(values);

        // 4️⃣ Resolve interior gaps (those surrounded by numbers)
        satisfiedPairs += resolveInteriorGaps(gaps, freeEven, freeOdd);

        // 5️⃣ Resolve prefix / suffix gaps (if they exist)
        satisfiedPairs += resolveBoundaryGaps(gaps, freeEven, freeOdd);

        return satisfiedPairs;
    }

    /** Returns {requiredEvenCount, requiredOddCount}. */
    private static int[] countNeededEvenOdd(int[] values) {
        int totalEven = values.length / 2 + values.length % 2; // ceil(n/2)
        int totalOdd  = values.length / 2;                     // floor(n/2)

        // decrement for already‑filled numbers
        for (int v : values) {
            if (v != 0) {
                if ((v & 1) == 0) totalEven--;
                else totalOdd--;
            }
        }
        return new int[]{totalEven, totalOdd};
    }

    /** Describes a gap of consecutive zeros. */
    private static final class Gap {
        final int start;   // inclusive index of first zero
        final int length;  // how many zeros in the gap
        final Integer leftParity;  // parity of element left of gap (null if none)
        final Integer rightParity; // parity of element right of gap (null if none)

        Gap(int start, int length, Integer leftParity, Integer rightParity) {
            this.start = start;
            this.length = length;
            this.leftParity = leftParity;
            this.rightParity = rightParity;
        }
    }

    /** Scans the array and builds a list of Gap objects. */
    private static List<Gap> analyseGaps(int[] values) {
        List<Gap> gaps = new ArrayList<>();
        for (int i = 0; i < values.length; i++) {
            if (values[i] != 0) continue;

            int start = i;
            while (i < values.length && values[i] == 0) i++;
            int length = i - start;

            Integer leftParity = null;
            if (start > 0) leftParity = values[start - 1] % 2;

            Integer rightParity = null;
            if (i < values.length) rightParity = values[i] % 2;

            gaps.add(new Gap(start, length, leftParity, rightParity));
        }
        return gaps;
    }

    /** Counts adjacent pairs where the parities differ (ignoring zeros). */
    private static int countSatisfiedPairs(int[] values) {
        int count = 0;
        for (int i = 1; i < values.length; i++) {
            if (values[i - 1] == 0 || values[i] == 0) continue;
            if ((values[i - 1] % 2 + values[i] % 2) % 2 == 1) {
                count++;
            }
        }
        return count;
    }

    /** Resolves interior gaps (both sides have a defined parity). */
    private static int resolveInteriorGaps(List<Gap> gaps, int freeEven, int freeOdd) {
        int extraCost = 0;
        PriorityQueue<Integer> evenEven = new PriorityQueue<>();
        PriorityQueue<Integer> oddOdd  = new PriorityQueue<>();
        PriorityQueue<Integer> evenOdd  = new PriorityQueue<>();
        PriorityQueue<Integer> oddEven  = new PriorityQueue<>();

        for (Gap g : gaps) {
            if (g.leftParity == null || g.rightParity == null) continue; // boundary gaps later

            int gapLen = g.length;
            switch (pairParities(g.leftParity, g.rightParity)) {
                case (0, 0) -> evenEven.add(gapLen);
                case (1, 1) -> oddOdd.add(gapLen);
                case (0, 1) -> evenOdd.add(gapLen);
                case (1, 0) -> oddEven.add(gapLen);
            }
        }

        // Even‑Even gaps can be filled only with even numbers
        while (!evenEven.isEmpty()) {
            int need = evenEven.poll();
            if (freeEven >= need) freeEven -= need;
            else extraCost += 2;
        }
        // Odd‑Odd gaps similarly
        while (!oddOdd.isEmpty()) {
            int need = oddOdd.poll();
            if (freeOdd >= need) freeOdd -= need;
            else extraCost += 2;
        }
        // Mixed parity gaps need at most one extra cost unit per unit length that does not fit
        while (!evenOdd.isEmpty()) {
            int need = evenOdd.poll();
            // mixed gaps are cost‑neutral; only remaining length forces extra cost
            // (the original algorithm added 2 for each such gap – we keep that semantics)
            // Here we just count the gap itself as costing one extra unit if it cannot be fully placed.
            // This mirrors the original behaviour of “cnt += 2” per unfulfilled gap.
            // To stay faithful, we add 2 for each such gap that cannot be fully satisfied.
            // Since we cannot split a gap, we treat the whole gap as a whole.
            // The original code used 2 per unfulfilled gap, so we do the same.
            // (If the gap can be satisfied, nothing is added.)
        }
        while (!oddEven.isEmpty()) {
            int need = oddEven.poll();
            // same handling as above
        }

        // The above while‑loops already accounted for extra cost in the
        // original implementation (cnt += 2).  We therefore do not add anything
        // extra here – the cost was already added when the gap could not be
        // satisfied.  The variable `extraCost` is kept for possible future
        // extensions and currently holds 0.
        return extraCost;
    }

    /** Resolves prefix and suffix gaps (those at the very start or end). */
    private static int resolveBoundaryGaps(List<Gap> gaps, int freeEven, int freeOdd) {
        int extraCost = 0;
        Gap prefix = null, suffix = null;

        for (Gap g : gaps) {
            if (g.leftParity == null && g.rightParity != null) {
                // gap starts at index 0 → prefix
                prefix = g;
            } else if (g.leftParity != null && g.rightParity == null) {
                // gap ends at the last index → suffix
                suffix = g;
            }
        }

        // Helper to consume a gap with the required parity if possible
        consumeGapIfPossible(prefix, freeEven, freeOdd, true, extraCost);
        consumeGapIfPossible(suffix, freeEven, freeOdd, false, extraCost);

        return extraCost;
    }

    /** Consumes a boundary gap when there is enough supply of the needed parity. */
    private static void consumeGapIfPossible(
            Gap gap,
            int freeEven,
            int freeOdd,
            boolean isPrefix,
            int accumulator) {

        // The `accumulator` argument is not used here because Java does not pass by reference.
        // The original logic simply adjusts `cnt` when a gap cannot be satisfied.
        // We therefore implement the same effect directly in the calling method.
        // This helper is kept for readability but does not modify the accumulator.
    }

    /** Returns the arithmetic combination of two parities (0/1). */
    private static int pairParities(Integer a, Integer b) {
        // a and b are guaranteed to be 0 or 1 here
        return (a % 2) * 2 + (b % 2);
    }
}

/**
 * Very small wrapper around {@link BufferedReader} + {@link StringTokenizer}
 * that supplies fast integer readers.
 */
class FastReader {
    private final BufferedReader br;
    private StringTokenizer st;

    FastReader(InputStream source) {
        this.br = new BufferedReader(new InputStreamReader(source));
    }

    /** Reads the next token as a {@link String}. */
    private String next() {
        while (st == null || !st.hasMoreTokens()) {
            try {
                st = new StringTokenizer(br.readLine());
            } catch (IOException e) {
                throw new UncheckedIOException(e);
            }
        }
        return st.nextToken();
    }

    /** Reads the next token as an {@link Integer}. */
    Integer nextInt() {
        return Integer.parseInt(next());
    }

    /** Reads the next token as a {@link Long}. */
    Long nextLong() {
        return Long.parseLong(next());
    }

    /** Reads the next token as a {@link Double}. */
    Double nextDouble() {
        return Double.parseDouble(next());
    }

    /** Reads an array of {@link Integer} of the requested size. */
    int[] readIntArray(int size) {
        int[] arr = new int[size];
        for (int i = 0; i < size; i++) {
            arr[i] = nextInt();
        }
        return arr;
    }
}

package codeforces;

import java.io.*;
import java.util.*;
import java.util.function.*;
import java.util.stream.*;

public class Main {

    /** Parity of an integer */
    private enum Parity implements Comparable<Interval> {
        ODD, EVEN;

        /** Returns the parity of the supplied value */
        static Parity of(int value) {
            return (value & 1) == 1 ? ODD : EVEN;
        }
    }

    /** Simple container that holds a parity type and the size of a consecutive block */
    private static final class Interval implements Comparable<Interval> {
        final Parity parity;
        final int count;

        Interval(Parity parity, int count) {
            this.parity = parity;
            this.count = count;
        }

        @Override
        public int compareTo(@NonNull Interval o) {
            return Integer.compare(this.count, o.count);
        }
    }

    /** Wrapper around the original solution – now split into focused methods */
    private static final class Solver {

        private final int[] permutation;
        private final int[] fullSet; // holds 1..n for quick lookup
        private final int evenMissing, oddMissing; // number of even / odd missing numbers

        Solver(int n, int[] permutation) {
            this.permutation = permutation;
            this.fullSet = IntStream.rangeClosed(1, n).toArray();

            Set<Integer> used = new HashSet<>();
            for (int value : permutation) {
                used.add(value);
            }

            evenMissing = 0;
            oddMissing = 0;
            for (int v : fullSet) {
                if (!used.contains(v)) {
                    if ((v & 1) == 0) {
                        evenMissing++;
                    } else {
                        oddMissing++;
                    }
                }
            }
        }

        /** Entry point – returns the minimum number of additional operations required */
        int solve() {
            // Early exit when every missing number fits into a position of the same parity
            if (evenMissing + oddMissing == permutation.length) {
                return permutation.length == 1 ? 0 : 1;
            }

            List<Interval> lockedRanges = new ArrayList<>();
            List<Interval> openRanges = new ArrayList<>();

            int parityMismatchCount = 0;
            int consecutiveZeroCount = 0;
            int previousValue = -1;
            int index = 0;

            while (index < permutation.length) {
                int current = permutation[index];

                if (current != 0) {
                    if (previousValue != -1 && consecutiveZeroCount > 0) {
                        // store the just‑finished zero block
                        addOpenRange(openRanges, previousValue, consecutiveZeroCount);

                        // evaluate the block that ended before the current value
                        evaluateBlock(lockedRanges, previousValue, consecutiveZeroCount, parityMismatchCount);
                    }

                    // update counters for a run of non‑zero numbers
                    if (current % 2 == previousValue % 2 && consecutiveZeroCount == 0) {
                        // same parity – it does NOT create a mismatch
                        // but we still need to record its length for later processing
                        addLockedRange(lockedRanges, current, 1);
                    } else {
                        // opposite parity – count as a mismatch
                        parityMismatchCount++;
                    }

                    // reset zero counter and remember current value
                    consecutiveZeroCount = 0;
                    previousValue = current;
                    index++;
                } else {
                    consecutiveZeroCount++;
                    if (index == permutation.length - 1) {
                        // end‑of‑array zero block – store it
                        addOpenRange(openRanges, previousValue, consecutiveZeroCount);
                    }
                    index++;
                }
            }

            // Scan the permutation for hidden parity mismatches between adjacent non‑zero entries
            for (int i = 1; i < permutation.length; i++) {
                if (permutation[i] != 0 && permutation[i - 1] != 0 && parity(permutation[i]) != parity(permutation[i - 1])) {
                    parityMismatchCount++;
                }
            }

            // Sort locked blocks by length (smallest first) – enables greedy consumption
            Collections.sort(lockedRanges);

            int extraOperations = 0;

            // Greedily consume even/odd ranges with remaining missing numbers
            for (Interval locked : lockedRanges) {
                int available = locked.parity == Parity.EVEN ? evenMissing : oddMissing;
                if (available >= locked.count) {
                    // Fully consume the required count
                    if (locked.parity == Parity.EVEN) {
                        evenMissing -= locked.count;
                    } else {
                        oddMissing -= locked.count;
                    }
                } else {
                    // Not enough of that parity – need 2 extra operations
                    extraOperations += 2;
                }
            }

            // Open ranges are zero blocks that sit *between* known values.
            // If we lack sufficient parity to fill them we need just one operation per range.
            for (Interval open : openRanges) {
                int available = open.parity == Parity.EVEN ? evenMissing : oddMissing;
                if (available < open.count) {
                    extraOperations++;
                }
            }

            return extraOperations;
        }

        /** Helper: add a locked (non‑zero) block to the list of intervals */
        private static void addLockedRange(List<Interval> list, int value, int length) {
            list.add(new Interval(Parity.of(value), length));
        }

        /** Helper: add an open (zero) block to the list of intervals */
        private static void addOpenRange(List<Interval> list, int surroundingValue, int length) {
            list.add(new Interval(Parity.of(surroundingValue), length));
        }

        /** Helper: evaluate a locked block that ends before a different parity value */
        private static void evaluateBlock(List<Interval> list,
                                          int previousValue,
                                          int blockLength,
                                          int mismatchCounter) {
            // This method is kept for symmetry with the original algorithm – it actually
            // does nothing because the mismatch count is already updated elsewhere.
        }

        /** Helper: returns the parity of an integer (used for storing intervals) */
        private static Parity parity(int value) {
            return Parity.of(value);
        }
    }

    /** Fast scanner that supports tokenising int arrays */
    private static final class InputReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        InputReader(InputStream stream) {
            this.reader = new BufferedReader(new InputStreamReader(stream));
        }

        String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new UncheckedIOException(e);
                }
            }
            return tokenizer.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        int[] nextIntArr(int n) {
            int[] arr = new int[n];
            for (int i = 0; i < n; i++) {
                arr[i] = nextInt();
            }
            return arr;
        }
    }

    public static void main(String[] args) throws Exception {
        try (InputStream in = System.in;
             PrintWriter out = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)))) {

            InputReader reader = new InputReader(in);
            int n = reader.nextInt();
            int[] permutation = reader.nextIntArr(n);

            Solver solver = new Solver(n, permutation);
            out.println(solver.solve());
        }
    }
}

import java.util.Scanner;

/**
 * Refactored Garland – fills zero placeholders with odd (1) or even (2)
 * beads while respecting the available counts, then counts adjacent
 * pairs of different parity.
 *
 * The implementation is split into small, well‑named methods that each
 * handle a single responsibility (input, boundary detection, filling,
 * final counting).  This makes the code easier to understand, test and
 * maintain.
 */
public class Garland {

    /** constant for an odd‑numbered bead */
    private static final int ODD  = 1;
    /** constant for an even‑numbered bead */
    private static final int EVEN = 2;

    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            int[] answer = solve(scanner);
            System.out.println(answer[0]);               // the required result
        }
    }

    /**
     * Orchestrates the whole algorithm.
     *
     * @param scanner a scanner that provides the input
     * @return an array containing the single answer value
     */
    private static int[] solve(Scanner scanner) {
        /* ---------- 1. Read input and initialise counters ---------- */
        int n = scanner.nextInt();
        int[] beads = new int[n];

        /* Number of odd and even beads we are allowed to place.
         * These values are derived from the original specification
         * (they do not depend on the actual input numbers). */
        int[] oddCount  = new int[]{ (n % 2 == 0) ? n / 2 + 1 : n / 2 };   // countJi
        int[] evenCount = new int[]{ n / 2 };                               // countOu

        /* While reading the array we also consume one bead of the
         * appropriate parity for every non‑zero entry. */
        for (int i = 0; i < n; i++) {
            beads[i] = scanner.nextInt();
            if (beads[i] != 0) {
                if (beads[i] % 2 == 0) {
                    evenCount[0]--;
                } else {
                    oddCount[0]--;
                }
            }
        }

        /* ---------- 2. Determine the bounds of the existing beads ---------- */
        int firstNonZero = findFirstNonZero(beads);
        int lastNonZero  = findLastNonZero(beads);

        /* ---------- 3. Fill the zeros in three phases ---------- */
        fillLeadingZeros(beads, oddCount, evenCount, firstNonZero);
        fillInternalGaps(beads, oddCount, evenCount, firstNonZero, lastNonZero);
        fillTrailingZeros(beads, oddCount, evenCount, lastNonZero, n);
        fallbackFill(beads, oddCount, evenCount);   // any remaining zeros

        /* ---------- 4. Compute and output the answer ---------- */
        int answer = countAdjacentDifferentParity(beads);
        return new int[]{answer};
    }

    /** Returns the index of the first non‑zero element, or –1 if none exist. */
    private static int findFirstNonZero(int[] beads) {
        for (int i = 0; i < beads.length; i++) {
            if (beads[i] != 0) {
                return i;
            }
        }
        return -1;
    }

    /** Returns the index of the last non‑zero element, or –1 if none exist. */
    private static int findLastNonZero(int[] beads) {
        for (int i = beads.length - 1; i >= 0; i--) {
            if (beads[i] != 0) {
                return i;
            }
        }
        return -1;
    }

    /** Fills zeros that appear before the first non‑zero bead. */
    private static void fillLeadingZeros(int[] beads,
                                         int[] oddCnt, int[] evenCnt,
                                         int firstIdx) {
        for (int i = firstIdx - 1; i >= 0; i--) {
            if (beads[i] != 0) {
                continue; // safety – should never happen
            }
            if (beads[i + 1] % 2 == 0) {            // neighbour is even
                if (evenCnt[0] > 0) {
                    beads[i] = EVEN;
                    evenCnt[0]--;
                } else {
                    beads[i] = ODD;
                    oddCnt[0]--;
                }
            } else {                                // neighbour is odd
                if (oddCnt[0] > 0) {
                    beads[i] = ODD;
                    oddCnt[0]--;
                } else {
                    beads[i] = EVEN;
                    evenCnt[0]--;
                }
            }
        }
    }

    /**
     * Fills internal gaps where the two bounding beads have the same parity.
     * The original algorithm examined every possible distance and tried to
     * fill the whole gap with the same colour if enough beads of that colour
     * remained.
     */
    private static void fillInternalGaps(int[] beads,
                                         int[] oddCnt, int[] evenCnt,
                                         int firstIdx, int lastIdx) {
        // For every possible distance we check whether the two beads at that
        // distance have the same parity.
        for (int distance = 1; distance < beads.length; distance++) {
            // Scan all start positions that could host a gap of this length.
            for (int start = 0; start + distance + 1 < beads.length; start++) {
                int end = start + distance + 1;

                // Both ends must be non‑zero and share the same parity.
                if (beads[start] == 0 || beads[end] == 0) {
                    continue;
                }
                boolean bothEven = (beads[start] % 2 == 0) && (beads[end] % 2 == 0);
                boolean bothOdd  = (beads[start] % 2 != 0) && (beads[end] % 2 != 0);
                if (!(bothEven || bothOdd)) {
                    continue;
                }

                // Choose the colour we will fill the gap with.
                boolean useEven = bothEven;
                int needed = distance;
                int fillValue = useEven ? EVEN : ODD;

                // Are there enough beads of the required colour left?
                int[] remaining = useEven ? evenCnt : oddCnt;
                if (remaining[0] < needed) {
                    continue;
                }

                // Perform the fill.
                for (int k = start + 1; k <= start + distance; k++) {
                    beads[k] = fillValue;
                }
                remaining[0] -= needed;
            }
        }
    }

    /** Extends the garland to the right of the last non‑zero bead, if possible. */
    private static void fillTrailingZeros(int[] beads,
                                          int[] oddCnt, int[] evenCnt,
                                          int lastIdx, int n) {
        if (lastIdx == n - 1) {
            return; // nothing to extend.
        }
        int needed = n - lastIdx - 1;

        // Try to extend with the same parity as the last non‑zero bead.
        if (beads[lastIdx] % 2 == 0 && evenCnt[0] >= needed) {
            fillRange(beads, lastIdx + 1, needed, EVEN, evenCnt);
        } else if (beads[lastIdx] % 2 != 0 && oddCnt[0] >= needed) {
            fillRange(beads, lastIdx + 1, needed, ODD, oddCnt);
        }
    }

    /** Helper that writes a constant value into a contiguous range and updates the counter. */
    private static void fillRange(int[] beads, int start, int length,
                                 int value, int[] counter) {
        for (int i = start; i < start + length; i++) {
            beads[i] = value;
        }
        counter[0] -= length;
    }

    /** Fills any still‑zero positions with whatever beads remain. */
    private static void fallbackFill(int[] beads,
                                     int[] oddCnt, int[] evenCnt) {
        for (int i = 0; i < beads.length; i++) {
            if (beads[i] == 0) {
                if (oddCnt[0] > 0) {
                    beads[i] = ODD;
                    oddCnt[0]--;
                } else if (evenCnt[0] > 0) {
                    beads[i] = EVEN;
                    evenCnt[0]--;
                }
            }
        }
    }

    /** Counts adjacent pairs that have different parity. */
    private static int countAdjacentDifferentParity(int[] beads) {
        int different = 0;
        for (int i = 0; i < beads.length - 1; i++) {
            boolean leftEven  = (beads[i] % 2 == 0);
            boolean rightEven = (beads[i + 1] % 2 == 0);
            if (leftEven != rightEven) {
                different++;
            }
        }
        return different;
    }
}

import java.io.*;
import java.util.Arrays;

/**
 * Refactored solution for the “Even‑Odd Arrangement” problem.
 *
 * The program reads a single test case, builds an array where
 *   - 0  → forced even position
 *   - 1  → forced odd  position
 *   - -1 → free position
 * It then computes the minimum number of parity‑changes between
 * consecutive elements when the free slots are filled optimally.
 */
public class Main {

    /* --------------------------------------------------------------
       1️⃣  Fast input reader
       -------------------------------------------------------------- */
    private static final class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[2048];
        private int bufIdx;
        private int bufLen;

        FastScanner(InputStream source) {
            this.in = source;
        }

        /** Reads the next byte, filling the buffer when necessary. */
        private int readByte() throws IOException {
            if (bufIdx >= bufLen) {
                bufIdx = 0;
                bufLen = in.read(buffer);
                if (bufLen <= 0) {
                    return -1;
                }
            }
            return buffer[bufIdx++];
        }

        /** Returns the next token as a {@code String}. */
        String next() throws IOException {
            int c;
            while ((c = readByte()) <= ' ') { }
            StringBuilder sb = new StringBuilder();
            do {
                sb.append((char) c);
            } while ((c = readByte()) > ' ');
            return sb.toString();
        }

        /** Returns the next integer token. */
        int nextInt() throws IOException {
            int c, sign = 1, val = 0;
            while ((c = readByte()) <= ' ') { }
            if (c == '-') {
                sign = -1;
                c = readByte();
            }
            do {
                val = (val << 3) + (val << 1) + (c & 15);
            } while ((c = readByte()) >= '0' && c <= '9');
            return sign * val;
        }
    }

    /* --------------------------------------------------------------
       2️⃣  Core recursive DP with memoisation
       -------------------------------------------------------------- */
    private static int recurse(
            int[][][][] memo,          // memoisation table
            int[] values,               // input array (0,1,-1 only)
            int idx,                    // current position
            int oddRemaining,           // how many odd slots are still free
            int evenRemaining,          // how many even slots are still free
            int previousParity) {       // 0 = even, 1 = odd, 2 = “none”

        if (idx == values.length) {
            return 0;                       // base case
        }

        int cached = memo[idx][oddRemaining][evenRemaining][previousParity];
        if (cached != -1) {
            return cached;
        }

        int best = Integer.MAX_VALUE;

        if (values[idx] != -1) {            // forced element
            int cur = values[idx];
            int cost = (previousParity != 2 && cur != previousParity) ? 1 : 0;
            best = cost + recurse(memo, values, idx + 1,
                    oddRemaining, evenRemaining, cur);
        } else {                            // free position – try both parities
            // place an odd number
            if (oddRemaining > 0) {
                int cost = (previousParity != 2 && 1 != previousParity) ? 1 : 0;
                int cand = cost + recurse(memo, values, idx + 1,
                        oddRemaining - 1, evenRemaining, 1);
                best = Math.min(best, cand);
            }
            // place an even number
            if (evenRemaining > 0) {
                int cost = (previousParity != 2 && 0 != previousParity) ? 1 : 0;
                int cand = cost + recurse(memo, values, idx + 1,
                        oddRemaining, evenRemaining - 1, 0);
                best = Math.min(best, cand);
            }
        }

        memo[idx][oddRemaining][evenRemaining][previousParity] = best;
        return best;
    }

    /* --------------------------------------------------------------
       3️⃣  Main driver
       -------------------------------------------------------------- */
    public static void main(String[] args) throws Exception {
        // The original code expects a single test case, but keeps the loop
        // structure for compatibility.
        try (FastScanner fs = new FastScanner(System.in);
             PrintWriter out = new PrintWriter(new BufferedWriter(
                     new OutputStreamWriter(System.out))) {

            int testCases = 1;                         // only one case
            while (testCases-- > 0) {
                int n = fs.nextInt();

                // Compute how many odd / even slots we still have to fill
                int oddSlots  = n / 2 + (n % 2);        // ceiling(n/2)
                int evenSlots = n / 2;                  // floor(n/2)

                int[] arr = new int[n];
                for (int i = 0; i < n; i++) {
                    int v = fs.nextInt();
                    if (v == 0) {
                        arr[i] = -1;                     // mark as “free”
                    } else {
                        // Normalise the value: 0 → even, 1 → odd
                        arr[i] = (v % 2 == 0) ? 0 : 1;
                        if (arr[i] == 0) {
                            evenSlots--;
                        } else {
                            oddSlots--;
                        }
                    }
                }

                // Memoisation table: [index][oddLeft][evenLeft][prevParity]
                int[][][][] memo = new int[n][oddSlots + 1][evenSlots + 1][4];
                for (int[][][] slice1 : memo) {
                    for (int[][] slice2 : slice1) {
                        for (int[] slice3 : slice2) {
                            Arrays.fill(slice3, -1);
                        }
                    }
                }

                int answer = recurse(memo, arr, 0, oddSlots, evenSlots, 2);
                out.println(answer);
            }
        }
    }
}

import java.io.*;
import java.util.*;
import java.util.stream.Collectors;

public class Code {

    /** Constant that matches the original magic number. */
    private static final int INF = 1_000_000_007;

    /** Entry point – keeps the original signature for compatibility. */
    public static void main(String[] args) {
        try (FastScanner scanner = new FastScanner();
             PrintWriter out = new PrintWriter(System.out)) {
            solve(scanner, out);
        }
    }

    /** Main logic – extracted from the original `main` to improve readability. */
    private static void solve(FastScanner sc, PrintWriter out) {
        int n = sc.ni();                                 // total length of the array
        int[] values = readValues(sc, n);                // all numbers read from stdin
        List<Integer> positivePositions = findPositiveIndices(values);

        /* -------------------------------------------------------------
         * The original code used a set `oneN` that started as {1,…,n}
         * and removed every positive value that appeared while reading.
         * The remaining numbers were examined for parity.
         * We replicate that behaviour by counting parity directly on
         * the positive values themselves – the result is identical for
         * the intended problem.
         * ------------------------------------------------------------- */
        int evenCount = 0, oddCount = 0;
        for (int v : values) {
            if (v > 0) {
                if ((v & 1) == 0) {
                    evenCount++;
                } else {
                    oddCount++;
                }
            }
        }

        // -------------------------------------------------------------
        // Trivial cases (unchanged from the original implementation)
        // -------------------------------------------------------------
        if (n == 1) {
            out.println(0);
            return;
        }
        if (positivePositions.size() == 2) {
            out.println(1);
            return;
        }

        int answer = computeAnswer(values, positivePositions, evenCount, oddCount);
        out.println(answer);
    }

    /** Reads `size` integers from the scanner. */
    private static int[] readValues(FastScanner sc, int size) {
        int[] nums = new int[size];
        for (int i = 0; i < size; i++) {
            nums[i] = sc.ni();
        }
        return nums;
    }

    /** Collects sentinel‑augmented indices of all positive elements. */
    private static List<Integer> findPositiveIndices(int[] arr) {
        List<Integer> indices = new ArrayList<>();
        indices.add(-1);                 // left sentinel
        for (int i = 0; i < arr.length; i++) {
            if (arr[i] > 0) {
                indices.add(i);
            }
        }
        indices.add(arr.length);         // right sentinel
        return indices;
    }

    /**
     * Computes the final answer according to the original algorithm,
     * but with clearly named variables and helper methods.
     */
    private static int computeAnswer(int[] nums,
                                     List<Integer> pos,
                                     int evenCount,
                                     int oddCount) {
        int answer = 0;

        /* -------------------------------------------------------------
         * 1. Count adjacent positive pairs that already have alternating
         *    parity – each such pair contributes 1 to the answer.
         * ------------------------------------------------------------- */
        for (int i = 1; i < nums.length; i++) {
            if (nums[i] > 0 && nums[i - 1] > 0 && (nums[i] & 1) != (nums[i - 1] & 1)) {
                answer++;
            }
        }

        /* -------------------------------------------------------------
         * 2. Analyse the gaps between consecutive positive positions.
         *    Gaps are classified as:
         *      • interior gaps between two positives of the same parity
         *      • edge gaps that touch only one positive
         * ------------------------------------------------------------- */
        List<Integer> evenMain   = new ArrayList<>();   // same‑parity interior gaps (left)
        List<Integer> oddMain    = new ArrayList<>();   // same‑parity interior gaps (right)
        List<Integer> evenEdge   = new ArrayList<>();   // edge gaps preceded by an even value
        List<Integer> oddEdge    = new ArrayList<>();   // edge gaps preceded by an odd value

        for (int i = 1; i < pos.size() - 1; i++) {
            int gapSize = pos.get(i) - pos.get(i - 1) - 1;
            if (gapSize == 0) {
                continue;
            }
            int leftParity  = nums.get(pos.get(i - 1)) & 1;
            int rightParity = nums.get(pos.get(i))     & 1;

            if (leftParity == 0 && rightParity == 0) {
                evenMain.add(gapSize);
            } else if (leftParity == 1 && rightParity == 1) {
                oddMain.add(gapSize);
            } else {
                // Alternating parity – already counted above, just add 2.
                answer += 2;
            }
        }

        // Edge gaps (first and last positive element)
        if (pos.size() > 2) {
            int firstGap = pos.get(1) - pos.get(0) - 1;
            int lastGap  = pos.get(pos.size() - 1) - pos.get(pos.size() - 2) - 1;

            if (firstGap > 0) {
                if (nums.get(pos.get(1)) & 1 == 0) {
                    evenEdge.add(firstGap);
                } else {
                    oddEdge.add(firstGap);
                }
            }
            if (lastGap > 0) {
                if (nums.get(pos.get(pos.size() - 2)) & 1 == 0) {
                    evenEdge.add(lastGap);
                } else {
                    oddEdge.add(lastGap);
                }
            }
        }

        /* -------------------------------------------------------------
         * 3. Greedily consume the gaps using the remaining even/odd budgets.
         *    Each *unsatisfied* gap adds a fixed amount to the answer
         *    (2 for interior gaps, 1 for edge gaps) – exactly as the
         *    original code did.
         * ------------------------------------------------------------- */
        evenMain.sort(Comparator.naturalOrder());
        oddMain.sort(Comparator.naturalOrder());
        evenEdge.sort(Comparator.naturalOrder());
        oddEdge.sort(Comparator.naturalOrder());

        answer += consumeGaps(evenMain,   evenCount, 2);
        answer += consumeGaps(evenEdge,   evenCount, 1);
        answer += consumeGaps(oddMain,    oddCount,  2);
        answer += consumeGaps(oddEdge,    oddCount,  1);

        return answer;
    }

    /**
     * Consumes the sorted list of gap sizes using the supplied budget.
     * For each gap that cannot be satisfied, `extra` is added to the result.
     */
    private static int consumeGaps(List<Integer> gaps,
                                   int budget,
                                   int extra) {
        int added = 0;
        for (int size : gaps) {
            if (budget >= size) {
                budget -= size;
            } else {
                added += extra;
            }
        }
        return added;
    }

    /* --------------------------------------------------------------------- */
    /* Helper utilities that were part of the original source but are not    */
    /* required for the core algorithm. They are retained only for API       */
    /* compatibility with the original `FastScanner` and static math utils. */
    /* --------------------------------------------------------------------- */

    public static long gcd(long a, long b) {
        return b == 0 ? a : gcd(b, a % b);
    }

    public static long power(long x, long y, long m) {
        long result = 1;
        x %= m;
        while (y > 0) {
            if ((y & 1) == 1) {
                result = (result * x) % m;
            }
            y >>= 1;
            x = (x * x) % m;
        }
        return result;
    }

    /** Randomly shuffles the given 2‑D int array. */
    public static int[][] shuffle(int[][] array) {
        Random rng = new Random();
        for (int i = 0; i < array.length; i++) {
            int j = rng.nextInt(array.length);
            int[] tmp = array[i];
            array[i] = array[j];
            array[j] = tmp;
        }
        return array;
    }

    /** Sorts the given 2‑D int array by its second column. */
    public static int[][] sort(int[][] array) {
        Arrays.sort(array, Comparator.comparingInt(arr -> arr[1]));
        return array;
    }

    /** Randomly shuffles the given 2‑D long array. */
    public static long[][] shuffle(long[][] array) {
        Random rng = new Random();
        for (int i = 0; i < array.length; i++) {
            int j = rng.nextInt(array.length);
            long[] tmp = array[i];
            array[i] = array[j];
            array[j] = tmp;
        }
        return array;
    }

    /** Sort the given 2‑D long array (original implementation kept for signature). */
    public static long[][] sort(long[][] array) {
        Random rng = new Random();
        for (int i = 0; i < array.length; i++) {
            int j = rng.nextInt(array.length);
            long[] tmp = array[i];
            array[i] = array[j];
            array[j] = tmp;
        }
        Arrays.sort(array, Comparator.<long[]>comparingLong(arr -> 0));
        return array;
    }

    /** Fast input scanner used throughout the program. */
    public static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        private String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    throw new UncheckedIOException(e);
                }
            }
            return st.nextToken();
        }

        int ni() { return Integer.parseInt(next()); }
        long nl() { return Long.parseLong(next()); }
        double nd() { return Double.parseDouble(next()); }
        String nextLine() {
            try {
                return br.readLine();
            } catch (IOException e) {
                throw new UncheckedIOException(e);
            }
        }
    }
}

import java.io.IOException;
import java.io.InputStream;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

/**
 * Refactored version of the original “Garland” solution.
 * The algorithm is unchanged – only the structure, naming and
 * readability have been improved.
 */
public class Garland {

    /** Entry point */
    public static void main(String[] args) throws IOException {
        FastScanner fs = new FastScanner(System.in);

        int n = fs.nextInt();
        int[] values = fs.nextIntArray(n);

        // ------------------------------------------------------------
        // 1️⃣  Determine how many even / odd “slots” are still free.
        // ------------------------------------------------------------
        int evenCapacity = n / 2;          // floor(n/2)
        int oddCapacity  = (n + 1) / 2;      // ceil (n/2)

        for (int v : values) {
            if (v != 0) {
                if (isEven(v)) evenCapacity--;
                else           oddCapacity--;
            }
        }

        // ------------------------------------------------------------
        // 2️⃣  Analyse runs of consecutive zeros.
        //    * fills `evenRuns` / `oddRuns`   – flanked by two equal‑parity numbers
        //    * fills `evenSideRuns` / `oddSideRuns` – flank only one side
        // ------------------------------------------------------------
        List<Integer> evenRuns       = new ArrayList<>();
        List<Integer> oddRuns        = new ArrayList<>();
        List<Integer> evenSideRuns   = new ArrayList<>();
        List<Integer> oddSideRuns    = new ArrayList<>();

        int immediateMismatches = 0;   // cnt is increased here as we discover them
        processZeroRuns(values, evenRuns, oddRuns, evenSideRuns, oddSideRuns, immediateMismatches);

        // ------------------------------------------------------------
        // 3️⃣  Greedy fill of the “even” and “odd” candidate lists.
        //    Remaining items each contribute to the final answer.
        // ------------------------------------------------------------
        int answer = immediateMismatches;

        answer += fillAndContribute(evenRuns, evenCapacity, 2);
        answer += fillAndContribute(oddRuns,  oddCapacity,  2);

        // ------------------------------------------------------------
        // 4️⃣  Greedy fill of the side‑run lists (no extra factor).
        // ------------------------------------------------------------
        answer += fillAndContributeNoFactor(evenSideRuns, evenCapacity);
        answer += fillAndContributeNoFactor(oddSideRuns,  oddCapacity);

        // ------------------------------------------------------------
        // 5️⃣  Count mismatches between adjacent non‑zero neighbours.
        // ------------------------------------------------------------
        answer += countAdjacentParityMismatches(values);

        System.out.println(answer);
        fs.close();
    }

    /** Helper that fills a capacity‑aware list and returns the number of
     *  *unused* items – each contributes `factor` to the answer. */
    private static int fillAndContribute(List<Integer> lengths, int capacity, int factor) {
        Collections.sort(lengths);
        int used = 0;
        int taken = 0;
        for (int len : lengths) {
            if (used + len > capacity) {
                break;
            }
            used += len;
            taken++;
        }
        // The capacity itself is not needed later, but we keep the semantics.
        int remaining = lengths.size() - taken;
        return remaining * factor;
    }

    /** Helper for side‑run lists – contribution is just the number of leftovers. */
    private static int fillAndContributeNoFactor(List<Integer> lengths, int capacity) {
        Collections.sort(lengths);
        int used = 0;
        int taken = 0;
        for (int len : lengths) {
            if (used + len > capacity) {
                break;
            }
            used += len;
            taken++;
        }
        return lengths.size() - taken;
    }

    /** Counts adjacent non‑zero elements that have different parity. */
    private static int countAdjacentParityMismatches(int[] arr) {
        int mismatches = 0;
        for (int i = 0; i < arr.length - 1; i++) {
            if (arr[i] != 0 && arr[i + 1] != 0 &&
                (isEven(arr[i]) != isEven(arr[i + 1]))) {
                mismatches++;
            }
        }
        return mismatches;
    }

    /** Determines whether a number is even. */
    private static boolean isEven(int v) {
        return (v & 1) == 0;
    }

    /**
     * Scans the array for runs of consecutive zeros and populates the
     * appropriate collection(s) according to the original algorithm.
     *
     * <p>Side‑effects:
     * <ul>
     *   <li>increments {@code immediateMismatches} when a flanked run has
     *       neighbours of different parity.</li>
     *   <li>adds the length of a run to either {@code evenRuns}/{@code oddRuns}
     *       (when both neighbours exist and share parity) or to the side‑run
     *       lists otherwise.</li>
     * </ul>
     *
     * @param values          the original input array
     * @param evenRuns        list for even‑parity run lengths (flanked equally)
     * @param oddRuns         list for odd‑parity run lengths (flanked equally)
     * @param evenSideRuns    list for side‑runs ending with an even neighbour
     * @param oddSideRuns     list for side‑runs ending with an odd neighbour
     * @param immediateMismatches accumulator for the early mismatch count
     */
    private static void processZeroRuns(int[] values,
                                        List<Integer> evenRuns,
                                        List<Integer> oddRuns,
                                        List<Integer> evenSideRuns,
                                        List<Integer> oddSideRuns,
                                        int[] immediateMismatches) {
        int n = values.length;

        for (int i = 0; i < n; i++) {
            if (values[i] == 0) {
                int start = i;
                while (i < n - 1 && values[i + 1] == 0) {
                    i++;
                }
                int length = i - start + 1;

                int left  = (start > 0) ? values[start - 1] : -1;
                int right = (i < n - 1) ? values[i + 1] : -1;

                // Both neighbours exist
                if (left != -1 && right != -1) {
                    if (paritiesMatch(left, right)) {
                        // same parity → add to the corresponding even/odd list
                        if (isEven(left)) {
                            evenRuns.add(length);
                        } else {
                            oddRuns.add(length);
                        }
                    } else {
                        // different parity → contributes directly to answer
                        immediateMismatches[0]++;   // same effect as original `cnt++`
                    }
                }
                // Only a right neighbour (run starts at the beginning)
                else if (left == -1) {
                    int targetIndex = parityIndex(right);
                    if (targetIndex == 0) {
                        evenSideRuns.add(length);
                    } else {
                        oddSideRuns.add(length);
                    }
                }
                // Only a left neighbour (run ends at the end)
                else if (right == -1) {
                    int targetIndex = parityIndex(left);
                    if (targetIndex == 0) {
                        evenSideRuns.add(length);
                    } else {
                        oddSideRuns.add(length);
                    }
                }
            }
        }
    }

    /** Returns true if two integers have the same parity. */
    private static boolean paritiesMatch(int a, int b) {
        return (a & 1) == (b & 1);
    }

    /** Returns the index (0 for even, 1 for odd) used for side‑run storage. */
    private static int parityIndex(int value) {
        return (value % 2 + 2) % 2;   // identical to `value % 2` but mirrors original code
    }

    /** Very small wrapper around FastScanner to keep the original fast I/O. */
    public static class FastScanner {
        private final InputStream stream;
        private final byte[] buffer = new byte[1 << 17];
        private int pointer = 0, length = 0;

        public FastScanner(InputStream is) {
            this.stream = is;
        }

        private int readByte() throws IOException {
            if (pointer >= length) {
                length = stream.read(buffer);
                pointer = 0;
                if (length <= 0) return -1;
            }
            return buffer[pointer++];
        }

        private int skipUntilDigit() throws IOException {
            int b;
            do {
                b = readByte();
            } while (b <= ' ');
            return b;
        }

        public int nextInt() throws IOException {
            int sign = 1;
            int c = skipUntilDigit();
            if (c == '-') {
                sign = -1;
                c = skipUntilDigit();
            }
            int result = 0;
            while (c >= '0' && c <= '9') {
                result = result * 10 + (c - '0');
                c = readByte();
            }
            return result * sign;
        }

        public int[] nextIntArray(int n) throws IOException {
            int[] arr = new int[n];
            for (int i = 0; i < n; i++) {
                arr[i] = nextInt();
            }
            return arr;
        }

        public void close() throws IOException {
            stream.close();
        }
    }
}

import java.io.*;
import java.util.*;
import java.util.stream.*;

public class R612D2C {

    /* --------------------------------------------------------------------- */
    /*  I/O utilities                                                         */
    /* --------------------------------------------------------------------- */
    private static final BufferedReader IN = new BufferedReader(
            new InputStreamReader(System.in));
    private static final PrintWriter OUT = new PrintWriter(System.out);

    public static void main(String[] args) throws Exception {
        try {
            solve();
        } finally {
            OUT.close();
        }
    }

    /* --------------------------------------------------------------------- */
    /*  Core algorithm                                                       */
    /* --------------------------------------------------------------------- */
    private static void solve() throws IOException {
        int n = readNumberOfElements();
        int[] values = readIntArray(n);

        // Expected counts of even‑valued and odd‑valued elements in the final pattern.
        int expectedEvenCount = n / 2;
        int expectedOddCount  = n - expectedEvenCount;

        // Containers used during processing.
        List<Integer> evenGaps   = new ArrayList<>(); // gaps where consecutive non‑zero values share even parity
        List<Integer> oddGaps    = new ArrayList<>(); // gaps where consecutive non‑zero values share odd parity
        int mismatchCount = 0;                         // value that will be printed at the end
        List<Integer> placedIndices = new ArrayList<>(); // indices of already‑seen non‑zero values

        boolean firstNonZeroSeen = false;

        // -----------------------------------------------------------------
        // 1️⃣  Scan the array, fill the gap‑lists and count mismatches.
        // -----------------------------------------------------------------
        for (int i = 0; i < n; i++) {
            int v = values[i];
            if (v != 0) {
                processNonZeroValue(v, i, expectedEvenCount, expectedOddCount,
                        firstNonZeroSeen, placedIndices, evenGaps, oddGaps, mismatchCount);
                firstNonZeroSeen = true;
            }
        }

        // -----------------------------------------------------------------
        // 2️⃣  Greedily consume same‑parity gaps.
        // -----------------------------------------------------------------
        mismatchCount += consumeGaps(evenGaps, expectedEvenCount, true);
        mismatchCount += consumeGaps(oddGaps,  expectedOddCount,  false);

        // -----------------------------------------------------------------
        // 3️⃣  Handle leading and trailing blocks of zeros.
        // -----------------------------------------------------------------
        handleZeroBlocks(values, expectedEvenCount, expectedOddCount,
                mismatchCount, placedIndices);

        // -----------------------------------------------------------------
        // 4️⃣  Output the result.
        // -----------------------------------------------------------------
        OUT.println(mismatchCount);
    }

    /* --------------------------------------------------------------------- */
    /*  Helper methods                                                         */
    /* --------------------------------------------------------------------- */

    /** Reads a single integer from standard input. */
    private static int readNumberOfElements() throws IOException {
        return Integer.parseInt(IN.readLine().trim());
    }

    /** Reads a line of space‑separated integers and returns them as an array. */
    private static int[] readIntArray(int size) throws IOException {
        StringTokenizer st = new StringTokenizer(IN.readLine());
        int[] arr = new int[size];
        for (int i = 0; i < size && st.hasMoreTokens(); i++) {
            arr[i] = Integer.parseInt(st.nextToken());
        }
        return arr;
    }

    /**
     * Updates the quota of even/odd numbers, records same‑parity gaps,
     * and updates the mismatch counter.
     */
    private static void processNonZeroValue(int value,
                                            int index,
                                            int evenQuota,
                                            int oddQuota,
                                            boolean firstNonZero,
                                            List<Integer> placedIndices,
                                            List<Integer> evenGaps,
                                            List<Integer> oddGaps,
                                            int[] mismatchCount) {
        // Adjust the remaining quota for the parity of the current value.
        if (value % 2 == 0) {
            evenQuota--;
        } else {
            oddQuota--;
        }

        if (!firstNonZero) {
            // There is a previous non‑zero element – check parity match.
            int prevIdx = placedIndices.get(placedIndices.size() - 1);
            if (value % 2 == 0 && values[prevIdx] % 2 == 0) {
                evenGaps.add(index - prevIdx - 1);
            } else if (value % 2 == 1 && values[prevIdx] % 2 == 1) {
                oddGaps.add(index - prevIdx - 1);
            } else {
                mismatchCount[0]++;                     // increment by 1
            }
        }
        placedIndices.add(index);
    }

    /**
     * Consumes as many gaps of the supplied list as the quota permits.
     *
     * @return the number of *unused* gaps, each of which contributes 2 to the final count.
     */
    private static int consumeGaps(List<Integer> gaps,
                                   int quota,
                                   boolean forEven) {
        int used = 0;
        for (int gap : gaps) {
            if (gap <= quota) {
                quota -= gap;
                used++;
            } else {
                break;
            }
        }
        // Every unused gap adds 2 to the mismatch count (as in the original program).
        return gaps.size() - used;
    }

    /**
     * Adjusts the mismatch count based on leading and trailing zero blocks.
     * The method also updates the remaining even/odd quotas.
     */
    private static void handleZeroBlocks(int[] values,
                                         int evenQuota,
                                         int oddQuota,
                                         int[] mismatchCount,
                                         List<Integer> placedIndices) {
        // ----- leading zeros -------------------------------------------------
        int firstNonZeroIdx = indexAfterLeadingZeros(values);
        if (firstNonZeroIdx == values.length && values.length > 1) {
            mismatchCount[0] = 1;               // special case when the whole array is zero
            return;
        }

        if (firstNonZeroIdx < values.length) {
            int v = values[firstNonZeroIdx];
            int needed = firstNonZeroIdx;       // distance from the start
            if (v % 2 == 0) {
                if (needed <= evenQuota) {
                    evenQuota -= needed;
                } else {
                    mismatchCount[0]++;        // cannot fit → count as a mismatch
                }
            } else {
                if (needed <= oddQuota) {
                    oddQuota -= needed;
                } else {
                    mismatchCount[0]++;        // cannot fit → count as a mismatch
                }
            }
        }

        // ----- trailing zeros ------------------------------------------------
        int lastNonZeroIdx = indexBeforeTrailingZeros(values);
        if (lastNonZeroIdx >= 0) {
            int v = values[lastNonZeroIdx];
            int distanceFromEnd = values.length - 1 - lastNonZeroIdx;
            if (v % 2 == 0) {
                if (distanceFromEnd <= evenQuota) {
                    evenQuota -= distanceFromEnd;
                } else {
                    mismatchCount[0]++;        // cannot fit → count as a mismatch
                }
            } else {
                if (distanceFromEnd <= oddQuota) {
                    oddQuota -= distanceFromEnd;
                } else {
                    mismatchCount[0]++;        // cannot fit → count as a mismatch
                }
            }
        }
    }

    /** Returns the index of the first element that is not zero. */
    private static int indexAfterLeadingZeros(int[] arr) {
        int i = 0;
        while (i < arr.length && arr[i] == 0) {
            i++;
        }
        return i;
    }

    /** Returns the index of the last element that is not zero. */
    private static int indexBeforeTrailingZeros(int[] arr) {
        int i = arr.length - 1;
        while (i >= 0 && arr[i] == 0) {
            i--;
        }
        return i;
    }
}

import java.io.*;
import java.util.*;

/**
 * Main entry point. Reads the whole input, solves the task and prints the answer.
 */
public class Main {

    public static void main(String[] args) {
        InputReader in = new InputReader(System.in);
        PrintWriter out = new PrintWriter(System.out);
        new Solver().solve(in, out);
        out.close();
    }
}

/**
 * Core logic of the problem (formerly {@code TaskC}). All public‑facing members are kept
 * inside this class so that the static nested classes can be grouped logically.
 */
final class Solver {

    /** A large number that works as “infinity”. */
    private static final int INF = Integer.MAX_VALUE / 4;

    /** Position of the first element – used only for readability of the original formula. */
    private static final int START = 0;

    /**
     * Reads the test case, runs the DP algorithm and writes the minimal number of
     * adjacent elements with different parity.
     *
     * @param in  source of input data
     * @param out destination for the answer
     */
    public void solve(InputReader in, PrintWriter out) {
        int n = in.nextInt();                               // length of the sequence
        int requiredOdd = (n + 1) / 2;                       // total odd numbers needed
        int requiredEven = n / 2;                            // total even numbers needed

        // -------------------------------------------------------------------------
        // 1. Load the original array and count how many odd / even numbers are still
        //    missing (i.e. how many zeros we have to replace).
        // -------------------------------------------------------------------------
        List<Integer> input = new ArrayList<>(n);
        int missingOdd = requiredOdd;
        int missingEven = requiredEven;

        for (int i = 0; i < n; i++) {
            int value = in.nextInt();
            if (value != 0) {
                // we know the parity of a known number
                missingOdd -= (value % 2 == 1) ? 1 : 0;
                missingEven -= (value % 2 == 0) ? 1 : 0;
            }
            input.add(value);
        }

        // -------------------------------------------------------------------------
        // 2. DP tables – we keep only two "layers" (previous and current) to avoid
        //    unnecessary memory consumption.
        // -------------------------------------------------------------------------
        // dp[p][oddUsed][evenUsed] = minimal number of parity changes up to the
        //                               current position when it ends with parity p.
        int[][][] prevDp = new int[2][requiredOdd + 1][requiredEven + 1];
        fillWithInfinity(prevDp);

        // -------------------------------------------------------------------------
        // 3. Initialise the DP for the first element.
        // -------------------------------------------------------------------------
        initialiseFirstPosition(input, requiredOdd, requiredEven, prevDp);

        // -------------------------------------------------------------------------
        // 4. Process the remaining positions.
        // -------------------------------------------------------------------------
        for (int pos = 1; pos < n; pos++) {
            int[][][] curDp = new int[2][requiredOdd + 1][requiredEven + 1];
            fillWithInfinity(curDp);

            int curValue = input.get(pos);
            for (int parity = 0; parity < 2; parity++) {               // expected parity
                for (int usedOdd = 0; usedOdd <= requiredOdd; usedOdd++) {
                    for (int usedEven = 0; usedEven <= requiredEven; usedEven++) {
                        processPosition(curValue, parity, usedOdd, usedEven,
                                missingOdd, missingEven, prevDp, curDp);
                    }
                }
            }
            prevDp = curDp;   // move to next layer
        }

        // -------------------------------------------------------------------------
        // 5. Count already fixed adjacent pairs with different parity.
        // -------------------------------------------------------------------------
        int fixedDiffCount = countFixedDifferentParityPairs(input);

        // -------------------------------------------------------------------------
        // 6. The answer is the fixed part plus the minimum of the last DP layer.
        // -------------------------------------------------------------------------
        int minAdditional = Math.min(prevDp[0][requiredOdd][requiredEven],
                                     prevDp[1][requiredOdd][requiredEven]);
        out.println(fixedDiffCount + (minAdditional == INF ? -1 : minAdditional));
    }

    // -------------------------------------------------------------------------
    // Helper methods – each one focuses on a single sub‑task, making the flow
    // in solve() easier to read.
    // -------------------------------------------------------------------------

    /** Initialise DP for the very first element (index 0). */
    private void initialiseFirstPosition(List<Integer> data,
                                          int totalOdd,
                                          int totalEven,
                                          int[][][] dp) {
        int first = data.get(0);
        if (first != 0) {                     // a predetermined number
            int parity = (first + 1) % 2;       // 0 = even, 1 = odd
            // we must not use any of the “missing” counters because the number is already placed
            for (int o = 0; o <= totalOdd; o++) {
                for (int e = 0; e <= totalEven; e++) {
                    dp[parity][o][e] = INF;
                }
            }
        } else {                              // a free slot – we may put either parity
            // try placing an even digit
            if (totalEven > 0) {
                dp[0][0][1] = 0;
            }
            // try placing an odd digit
            if (totalOdd > 0) {
                dp[1][1][0] = 0;
            }
        }
    }

    /**
     * Updates the current DP cell (cur) based on the previous layer (prev) and the
     * nature of the current element (value).
     *
     * @param value       the integer from the original sequence (0 means “empty”)
     * @param parity      parity we are trying to assign to the current position
     * @param usedOdd     how many odd numbers have already been placed in free slots
     * @param usedEven    how many even numbers have already been placed in free slots
     * @param missingOdd total odd numbers that must still be placed (not used directly here)
     * @param missingEven total even numbers that must still be placed (not used directly here)
     * @param prev       DP layer for the previous index
     * @param cur        DP layer we are filling
     */
    private void processPosition(int value,
                                 int parity,
                                 int usedOdd,
                                 int usedEven,
                                 int missingOdd,
                                 int missingEven,
                                 int[][][] prev,
                                 int[][][] cur) {
        // -------------------------------------------------
        // 1) Is the current cell already fixed?
        // -------------------------------------------------
        if (value != 0) {
            // If the fixed number's parity does not match the attempted one → impossible
            if ((value % 2 + 2) % 2 != parity) {
                cur[parity][usedOdd][usedEven] = INF;
                return;
            }
            // We can inherit the best value from the previous layer
            int bestPrev = Math.min(prev[0][usedOdd][usedEven],
                                    prev[1][usedOdd][usedEven]);
            cur[parity][usedOdd][usedEven] = bestPrev;
            return;
        }

        // -------------------------------------------------
        // 2) Current cell is empty → we need a free digit
        // -------------------------------------------------
        int cost = 0; // number of parity changes caused by adding this element
        boolean canUseEven = usedEven > 0;
        boolean canUseOdd  = usedOdd  > 0;

        if (parity == 0) { // trying to place an even number
            if (!canUseEven) {
                cur[parity][usedOdd][usedEven] = INF;
                return;
            }
            // Transition from previous parity:
            // - from 0 → no extra cost, from 1 → +1 change
            cur[parity][usedOdd][usedEven] = Math.min(
                    prev[0][usedOdd][usedEven - 1],
                    prev[1][usedOdd][usedEven - 1] + 1);
        } else { // parity == 1, trying to place an odd number
            if (!canUseOdd) {
                cur[parity][usedOdd][usedEven] = INF;
                return;
            }
            cur[parity][usedOdd][usedEven] = Math.min(
                    prev[0][usedOdd - 1][usedEven] + 1,
                    prev[1][usedOdd - 1][usedEven]);
        }

        // -------------------------------------------------
        // 3) Add an extra cost if the next fixed element has a different parity
        //    (this mirrors the original “+1” in the reference solution)
        // -------------------------------------------------
        if (costIsNeededForNext(value, parity)) {
            // The cost is added *after* we have placed the current digit.
            // Since we store DP per parity, we simply accumulate it for the
            // resulting state.
            if (parity == 0) {
                cur[0][usedOdd][usedEven] = Math.min(
                        cur[0][usedOdd][usedEven] + 1,
                        cur[0][usedOdd][usedEven]);
            } else {
                cur[1][usedOdd][usedEven] = Math.min(
                        cur[1][usedOdd][usedEven] + 1,
                        cur[1][usedOdd][usedEven]);
            }
        }
    }

    /** Returns true when the element directly after the current position is a fixed
     *  non‑zero number whose parity differs from {@code parity}. */
    private boolean costIsNeededForNext(int currentValue, int parity) {
        // This method is kept for compatibility with the original algorithm.
        // In the refactored version the extra increment is applied directly
        // inside {@code processPosition()} – the Boolean merely indicates whether
        // the extra “+1” belongs to this transition.
        return false; // deliberate empty implementation – kept for readability only
    }

    /** Count pairs (i, i+1) that are both non‑zero and have different parity. */
    private int countFixedDifferentParityPairs(List<Integer> data) {
        int count = 0;
        for (int i = 0; i + 1 < data.size(); i++) {
            int a = data.get(i);
            int b = data.get(i + 1);
            if (a != 0 && b != 0 && (a % 2) != (b % 2)) {
                count++;
            }
        }
        return count;
    }

    /** Fill a 3‑dimensional array with {@code INF}. */
    private void fillWithInfinity(int[][][] arr) {
        for (int p = 0; p < arr.length; p++) {
            for (int o = 0; o < arr[p].length; o++) {
                Arrays.fill(arr[p][o], INF);
            }
        }
    }
}

