import java.io.*;
import java.util.*;

public class TaskC {

    /** Small helper enum that stores the two possible parities. */
    private enum Parity {
        EVEN(0),
        ODD(1);

        private final int ordinal;
        Parity(int ordinal) {
            this.ordinal = ordinal;
        }

        /** Returns the enum constant that matches the supplied value. */
        static Parity fromInt(int v) {
            return (v % 2 == 0) ? EVEN : ODD;
        }
    }

    /** Container for the parsed input data. */
    private static final class TokenModel {
        final int[] values;          // the original sequence (may contain -1)
        final int remainingOdd;      // how many odd‑valued slots are still to be filled
        final int remainingEven;     // how many even‑valued slots are still to be filled

        TokenModel(int[] values, int remainingOdd, int remainingEven) {
            this.values = values;
            this.remainingOdd = remainingOdd;
            this.remainingEven = remainingEven;
        }
    }

    /** Constants used throughout the program. */
    private static final int INF = Integer.MAX_VALUE / 4;

    public static void main(String[] args) throws IOException {
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in))) {
            int n = Integer.parseInt(br.readLine().trim());

            String[] rawTokens = br.readLine().split("\\s+");
            TokenModel model = parseInput(rawTokens, n);

            /* --------------------------------------------------------------
             * DP state:
             *   dp[pos][oddLeft][evenLeft][parity]
             *   – minimal number of parity switches needed after processing
             *     the first `pos+1` elements,
             *     with `oddLeft` odd‑valued positions and `evenLeft` even‑valued
             *     positions still to be filled,
             *     ending with a value of the given parity.
             * -------------------------------------------------------------- */
            int[][][][] dp = new int[n][model.remainingOdd + 1][model.remainingEven + 1][2];

            // initialise every reachable cell with INF
            for (int p = 0; p < 2; p++) {
                for (int o = 0; o <= model.remainingOdd; o++) {
                    Arrays.fill(dp[0][o], INF);
                }
            }

            initialiseFirstPosition(dp, model);
            fillRemainingPositions(dp, model);

            int answer = Math.min(
                    dp[n - 1][0][0][Parity.ODD.ordinal()], // last value even? actually ODD index = 1
                    dp[n - 1][0][0][Parity.EVEN.ordinal()] // last value odd?
            );

            System.out.println(answer);
        }
    }

    /** --------------------------------------------------------------------
     *  Parses the raw token array produced by the original program.
     *  It computes how many odd/even slots must still be filled.
     *  ------------------------------------------------------------------- */
    private static TokenModel parseInput(String[] tokens, int n) {
        int[] arr = new int[n];
        int fixedOdd = 0, fixedEven = 0;

        for (int i = 0; i < n; i++) {
            int v = Integer.parseInt(tokens[i]);
            arr[i] = v;
            if (v == -1) continue;
            Parity p = Parity.fromInt(v);
            if (p == Parity.ODD)  fixedOdd++;
            else                  fixedEven++;
        }

        // total number of odd / even positions in a sequence of length n
        int totalOdd  = (n + 1) / 2;   // 1‑based odd indices (1,3,5,…)
        int totalEven = n / 2;         // 1‑based even indices (2,4,6,…)

        int remainingOdd  = totalOdd  - fixedOdd;
        int remainingEven = totalEven - fixedEven;

        return new TokenModel(arr, remainingOdd, remainingEven);
    }

    /** --------------------------------------------------------------------
     *  Initialise the DP row that corresponds to the first element of the
     *  sequence.
     *  ------------------------------------------------------------------- */
    private static void initialiseFirstPosition(int[][][][] dp, TokenModel model) {
        int[] a = model.values;
        if (a[0] == -1) {
            // the first slot is empty – we may place either an odd or an even number
            if (model.remainingOdd > 0) {
                dp[Parity.ODD.ordinal()][model.remainingOdd - 1][model.remainingEven][Parity.ODD.ordinal()] = 0;
            }
            if (model.remainingEven > 0) {
                dp[Parity.EVEN.ordinal()][model.remainingOdd][model.remainingEven - 1][Parity.EVEN.ordinal()] = 0;
            }
        } else {
            // the first slot already contains a concrete number
            Parity p = Parity.fromInt(a[0]);
            dp[p.ordinal()][model.remainingOdd][model.remainingEven][p.ordinal()] = 0;
        }
    }

    /** --------------------------------------------------------------------
     *  Core DP transition – fills the rows for positions 1 … n‑1.
     *  ------------------------------------------------------------------- */
    private static void fillRemainingPositions(int[][][][] dp, TokenModel model) {
        int n = dp.length;
        int[] a = model.values;
        int remOdd = model.remainingOdd;
        int remEven = model.remainingEven;

        for (int pos = 1; pos < n; pos++) {
            for (int o = 0; o <= remOdd; o++) {
                for (int e = 0; e <= remEven; e++) {
                    processCell(pos, a[pos], o, e, dp);
                }
            }
        }
    }

    /** --------------------------------------------------------------------
     *  Executes the transition for a single cell of the DP table.
     *  The implementation mirrors the original algorithm but with
     *  expressive variable names and helper methods.
     *  ------------------------------------------------------------------- */
    private static void processCell(int index, int value,
                                    int usedOdd, int usedEven,
                                    int[][][][] dp) {
        if (value == -1) {
            // ----- place an odd number -------------------------------------------------
            if (usedOdd > 0) {
                // coming from an odd parity costs nothing, from even costs +1
                int oddIdx = Parity.ODD.ordinal();
                int evenIdx = Parity.EVEN.ordinal();

                // transition without a switch
                dp[index][usedOdd - 1][usedEven][oddIdx] =
                        min(dp[index][usedOdd - 1][usedEven][oddIdx],
                                dp[index - 1][usedOdd][usedEven][oddIdx]);

                // transition with a switch
                int switchedCost = dp[index - 1][usedOdd][usedEven][evenIdx] + 1;
                dp[index][usedOdd - 1][usedEven][oddIdx] =
                        min(dp[index][usedOdd - 1][usedEven][oddIdx], switchedCost);
            }

            // ----- place an even number -----------------------------------------------
            if (usedEven > 0) {
                int evenIdx = Parity.EVEN.ordinal();
                int oddIdx = Parity.ODD.ordinal();

                dp[index][usedOdd][usedEven - 1][evenIdx] =
                        min(dp[index][usedOdd][usedEven - 1][evenIdx],
                                dp[index - 1][usedOdd][usedEven][evenIdx]);

                int switchedCost = dp[index - 1][usedOdd][usedEven][oddIdx] + 1;
                dp[index][usedOdd][usedEven - 1][evenIdx] =
                        min(dp[index][usedOdd][usedEven - 1][evenIdx], switchedCost);
            }
        } else {
            // ----- fixed (non‑‑1) value ------------------------------------------------
            Parity p = Parity.fromInt(value);
            int parityIdx = p.ordinal();

            if (p == Parity.ODD && usedOdd > 0) {
                // same steps as the “place an odd” branch above
                int oddIdx = Parity.ODD.ordinal();
                dp[index][usedOdd - 1][usedEven][oddIdx] =
                        min(dp[index][usedOdd - 1][usedEven][oddIdx],
                                dp[index - 1][usedOdd][usedEven][oddIdx]);

                int switchedCost = dp[index - 1][usedOdd][usedEven][Parity.EVEN.ordinal()] + 1;
                dp[index][usedOdd - 1][usedEven][oddIdx] =
                        min(dp[index][usedOdd - 1][usedEven][oddIdx], switchedCost);
            } else if (p == Parity.EVEN && usedEven > 0) {
                int evenIdx = Parity.EVEN.ordinal();
                dp[index][usedOdd][usedEven - 1][evenIdx] =
                        min(dp[index][usedOdd][usedEven - 1][evenIdx],
                                dp[index - 1][usedOdd][usedEven][evenIdx]);

                int switchedCost = dp[index - 1][usedOdd][usedEven][Parity.ODD.ordinal()] + 1;
                dp[index][usedOdd][usedEven - 1][evenIdx] =
                        min(dp[index][usedOdd][usedEven - 1][evenIdx], switchedCost);
            }
        }
    }

    /** --------------------------------------------------------------------
     *  Small utility that returns the minimum of two `int`s, treating
     *  `INF` as “unreachable”.
     *  ------------------------------------------------------------------- */
    private static int min(int a, int b) {
        return (a < b) ? a : b;
    }
}

import java.io.*;
import java.util.*;

public class Main {

    /** Modular arithmetic helpers – kept for completeness (not used in the algorithm). */
    private static final long MOD = 1_000_000_007L;
    private static final int INF = Integer.MAX_VALUE;

    /** Fast scanner that works with any InputStream. */
    private static final class FastScanner implements AutoCloseable {
        private final DataInputStream dis;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream source) {
            dis = new DataInputStream(source);
        }

        private int readByte() throws IOException {
            if (ptr >= len) {
                len = dis.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int sign = 1, c;
            do { c = readByte(); } while (c <= ' ');
            if (c == '-') { sign = -1; c = readByte(); }
            int val = 0;
            do {
                val = val * 10 + (c - '0');
                c = readByte();
            } while (c >= '0' && c <= '9');
            return val * sign;
        }

        long nextLong() throws IOException {
            long sign = 1, c;
            do { c = readByte(); } while (c <= ' ');
            if (c == '-') { sign = -1; c = readByte(); }
            long val = 0;
            do {
                val = val * 10 + (c - '0');
                c = readByte();
            } while (c >= '0' && c <= '9');
            return val * sign;
        }

        double nextDouble() throws IOException {
            double sign = 1, div = 1;
            int c;
            do { c = readByte(); } while (c <= ' ');
            if (c == '-') { sign = -1; c = readByte(); }
            double val = 0;
            do {
                val = val * 10 + (c - '0');
            } while ((c = readByte()) >= '0' && c <= '9');
            if (c == '.') {
                while ((c = readByte()) >= '0' && c <= '9') {
                    div *= 10;
                    val += (c - '0') / div;
                }
            }
            return sign * val;
        }

        @Override
        public void close() throws IOException {
            dis.close();
        }
    }

    /** Simple buffered printer that flushes when the buffer grows too large. */
    private static final class BufferedPrinter implements Closeable {
        private final StringBuilder sb = new StringBuilder(1 << 15);
        private final OutputStream out;
        private final int bufferSize;

        BufferedPrinter(OutputStream out) throws IOException {
            this.out = out;
            this.bufferSize = 1 << 16;
        }

        void print(String s) {
            sb.append(s);
            if (sb.length() > (bufferSize >> 1)) flush();
        }

        void println(int v) {
            println("" + v);
        }

        void println(long v) {
            println("" + v);
        }

        void println(String s) {
            print(s);
            print("\n");
        }

        void flush() {
            try {
                out.write(sb.toString().getBytes());
                sb.setLength(0);
            } catch (IOException e) {
                throw new UncheckedIOException(e);
            }
        }

        @Override
        public void close() {
            flush();
        }
    }

    /** Tiny utility method. */
    private static int min(int a, int b) {
        return a < b ? a : b;
    }

    public static void main(String[] args) throws Exception {
        /* ---------- Input --------------------------------------------------- */
        try (FastScanner in = new FastScanner(System.in)) {
            int n = in.nextInt();

            // Required numbers of even and odd values to be placed
            int neededEven = n / 2;
            int neededOdd  = (n + 1) / 2;

            int[] arr = new int[n];
            int remainingEven = neededEven;
            int remainingOdd  = neededOdd;

            for (int i = 0; i < n; ++i) {
                int x = in.nextInt();
                if (x == 0) {
                    arr[i] = -1;                     // 0 is used as a placeholder for “unknown”
                } else {
                    arr[i] = (x % 2 == 0) ? 0 : 1;    // 0 → even, 1 → odd
                    if (arr[i] == 0) --remainingEven;
                    else --remainingOdd;
                }
            }

            /* ---------- DP ---------------------------------------------------- */
            // dp[i][e][o][p] – minimal cost after processing i positions,
            //   with e even numbers still to be placed, o odd numbers still to be placed,
            //   and the i‑th placed element having parity p (0 = even, 1 = odd)
            int[][][][] dp = new int[n + 1][neededEven + 1][neededOdd + 1][2];
            for (int e = 0; e <= neededEven; ++e)
                for (int o = 0; o <= neededOdd; ++o)
                    dp[0][e][o][0] = dp[0][e][o][1] = INF;

            for (int i = 1; i <= n; ++i) {
                int curParity = arr[i - 1];               // -1 = unknown, 0 = even, 1 = odd

                if (i == 1) {                             // base case – first position
                    if (curParity == -1) {
                        if (remainingEven > 0) {
                            dp[1][remainingEven - 1][remainingOdd][0] = 0;
                        }
                        if (remainingOdd > 0) {
                            dp[1][remainingEven][remainingOdd - 1][1] = 0;
                        }
                    } else {
                        dp[1][remainingEven][remainingOdd][curParity] = 0;
                    }
                } else {
                    if (curParity != -1) {                  // position already fixed
                        for (int e = 0; e <= neededEven; ++e) {
                            for (int o = 0; o <= neededOdd; ++o) {
                                // stay with the same parity → no extra cost
                                dp[i][e][o][curParity] = min(dp[i][e][o][curParity],
                                                             dp[i - 1][e][o][curParity]);

                                // switch from opposite parity → incur a penalty of 1
                                if (dp[i - 1][e][o][curParity ^ 1] != INF) {
                                    dp[i][e][o][curParity] = min(dp[i][e][o][curParity],
                                                                 dp[i - 1][e][o][curParity ^ 1] + 1);
                                }
                            }
                        }
                    } else {                                 // free position – try both parities
                        for (int e = 0; e <= neededEven; ++e) {
                            for (int o = 0; o <= neededOdd; ++o) {
                                // place an even number
                                if (e > 0) {
                                    // previous parity was even → no extra cost
                                    if (dp[i - 1][e][o][0] != INF) {
                                        dp[i][e - 1][o][0] = min(dp[i][e - 1][o][0],
                                                                 dp[i - 1][e][o][0]);
                                    }
                                    // previous parity was odd → cost +1
                                    if (dp[i - 1][e][o][1] != INF) {
                                        dp[i][e - 1][o][0] = min(dp[i][e - 1][o][0],
                                                                 dp[i - 1][e][o][1] + 1);
                                    }
                                }
                                // place an odd number
                                if (o > 0) {
                                    // previous parity was even → cost +1
                                    if (dp[i - 1][e][o][0] != INF) {
                                        dp[i][e][o - 1][1] = min(dp[i][e][o - 1][1],
                                                                 dp[i - 1][e][o][0] + 1);
                                    }
                                    // previous parity was odd → no extra cost
                                    if (dp[i - 1][e][o][1] != INF) {
                                        dp[i][e][o - 1][1] = min(dp[i][e][o - 1][1],
                                                                 dp[i - 1][e][o][1]);
                                    }
                                }
                            }
                        }
                    }
                }
            }

            int answer = min(dp[n][0][0][0], dp[n][0][0][1]);
            System.out.println(answer);
        }
    }
}

import java.io.*;
import java.util.*;

public class Main implements Runnable {

    /* --------------------------- inner helper classes --------------------------- */

    /** Represents a contiguous segment of zeros in the input array. */
    private static class Gap {
        int start;   // inclusive
        int end;     // inclusive
        int size;    // length of the gap
        int type;    // 0 = even‑even neighbours, 1 = odd‑odd neighbours, 2 = mixed neighbours

        Gap(int start, int end) {
            this.start = start;
            this.end   = end;
        }

        /** Length of the gap (end - start + 1). */
        int length() {
            return end - start + 1;
        }

        @Override
        public String toString() {
            return "(" + start + ", " + end + ")";
        }
    }

    /** Fast scanner used for competitive‑programming style input. */
    private static class FastReader {
        private final BufferedReader br;
        private StringTokenizer st;

        FastReader() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        /** Returns next token, waiting for more input if necessary. */
        String next() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                st = new StringTokenizer(br.readLine());
            }
            return st.nextToken();
        }

        /** Convenience wrapper for next integer. */
        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }

    /* --------------------------- static fields --------------------------------- */

    private static FastReader scanner;
    private static PrintWriter writer;

    // problem‑specific data (filled during solve())
    private static int[] values;          // the input array
    private static int n;                 // number of elements
    private static int oddTarget;         // required count of odd numbers
    private static int evenTarget;        // required count of even numbers
    private static int missingOdd;        // odds still to place
    private static int missingEven;       // evens still to place

    /* --------------------------- entry point ----------------------------------- */

    public static void main(String[] args) throws Exception {
        scanner = new FastReader();
        writer  = new PrintWriter(System.out);
        solve();
        writer.flush();
        writer.close();
    }

    @Override
    public void run() {
        try {
            solve();
        } catch (Exception e) {
            e.printStackTrace();
        }
    }

    /* --------------------------- core algorithm -------------------------------- */

    /** Reads input, processes the data and prints the result. */
    private static void solve() throws Exception {
        // ----- read input -------------------------------------------------------
        n = scanner.nextInt();
        values = new int[n];

        int existingOdd = 0;
        int existingEven = 0;
        for (int i = 0; i < n; i++) {
            values[i] = scanner.nextInt();
            if (values[i] % 2 == 1) {
                existingOdd++;
            } else if (values[i] != 0) {
                existingEven++;
            }
        }

        // Determine how many odds / evens must still be placed.
        // For odd length arrays the centre position must be odd.
        oddTarget  = n % 2 == 0 ? n / 2 : (n + 1) / 2;
        evenTarget = n / 2;

        missingOdd  = oddTarget  - existingOdd;
        missingEven = evenTarget - existingEven;

        // ----- locate the first non‑zero element ---------------------------------
        int firstNonZero = 0;
        while (firstNonZero < n && values[firstNonZero] == 0) {
            firstNonZero++;
        }
        if (firstNonZero == n) {                // all entries are zero
            writer.println(Math.min(n - 1, 1));
            return;
        }

        // ----- build list of zero‑gaps -------------------------------------------
        List<Gap> gaps = new ArrayList<>();
        if (firstNonZero > 0) {
            gaps.add(new Gap(0, firstNonZero - 1));
        }

        int cursor = firstNonZero;
        while (cursor < n) {
            while (cursor < n && values[cursor] != 0) {
                cursor++;
            }
            int gapStart = cursor;
            while (cursor < n && values[cursor] == 0) {
                cursor++;
            }
            if (gapStart < cursor) {
                gaps.add(new Gap(gapStart, cursor - 1));
            }
        }

        // ----- classify each gap according to neighbour parity -------------------
        List<Gap> oddGaps  = new ArrayList<>(); // gaps surrounded by odd numbers
        List<Gap> evenGaps = new ArrayList<>(); // gaps surrounded by even numbers
        int mixedGapCount = 0;                  // gaps with mixed neighbours

        boolean hasFirstGap = false;
        boolean hasLastGap  = false;

        for (Gap g : gaps) {
            g.size = g.length();

            // neighbour parity in a circular view
            boolean leftIsOdd  = values[(g.start - 1 + n) % n] % 2 == 1;
            boolean rightIsOdd = values[(g.end + 1) % n] % 2 == 1;

            if (!leftIsOdd && !rightIsOdd) {
                g.type = 0;                     // surrounded by evens
                evenGaps.add(g);
            } else if (leftIsOdd && rightIsOdd) {
                g.type = 1;                     // surrounded by odds
                oddGaps.add(g);
            } else {
                g.type = 2;                     // mixed neighbours
                mixedGapCount++;
            }

            if (g.start == 0)  hasFirstGap = true;
            if (g.end   == n-1) hasLastGap  = true;
        }

        // Sort gaps by size (smallest first) – helps to fill them efficiently.
        Collections.sort(oddGaps,  Comparator.comparingInt(Gap::length));
        Collections.sort(evenGaps, Comparator.comparingInt(Gap::length));

        int answer = mixedGapCount;

        // ----- fill odd‑only gaps ------------------------------------------------
        for (Gap g : oddGaps) {
            if (g.size <= missingOdd) {
                missingOdd -= g.size;
            } else {
                answer += 2; // cannot fill completely → creates two extra boundaries
            }
        }

        // ----- fill even‑only gaps -----------------------------------------------
        for (Gap g : evenGaps) {
            if (g.size <= missingEven) {
                missingEven -= g.size;
            } else {
                answer += 2;
            }
        }

        // ----- handle edge gaps (first / last) ----------------------------------
        if (hasFirstGap) {
            Gap first = gaps.get(0);
            boolean leftIsOdd = values[(first.start - 1 + n) % n] % 2 == 1;

            Gap candidate = leftIsOdd ? findGap(oddGaps, first) : findGap(evenGaps, first);
            if (candidate != null && candidate.size <= (leftIsOdd ? missingOdd : missingEven)) {
                // gap can be completely filled
                if (leftIsOdd) missingOdd  -= candidate.size;
                else           missingEven -= candidate.size;
            } else {
                // cannot be filled → adds an unavoidable parity change
                answer++;
            }
        }

        if (hasLastGap) {
            Gap last = gaps.get(gaps.size() - 1);
            boolean rightIsOdd = values[last.end + 1] % 2 == 1;

            Gap candidate = rightIsOdd ? findGap(oddGaps, last) : findGap(evenGaps, last);
            if (candidate != null && candidate.size <= (rightIsOdd ? missingOdd : missingEven)) {
                if (rightIsOdd) missingOdd  -= candidate.size;
                else            missingEven -= candidate.size;
            } else {
                answer++;
            }
        }

        // ----- count existing adjacent mismatches ---------------------------------
        for (int i = 0; i < n - 1; i++) {
            if (values[i] == 0 || values[i + 1] == 0) continue;
            if (values[i] % 2 != values[i + 1] % 2) answer++;
        }

        writer.println(answer);
    }

    /** Utility: finds a gap with the same start/end in the given list, or null. */
    private static Gap findGap(List<Gap> list, Gap target) {
        for (Gap g : list) {
            if (g.start == target.start && g.end == target.end) {
                return g;
            }
        }
        return null;
    }
}

import java.io.*;
import java.util.StringTokenizer;

/**
 * Solver for the problem that processes an array of integers,
 * classifies them as zero, even‑non‑zero or odd, and computes a DP‑based answer.
 *
 * The implementation is deliberately split into small, focussed classes
 * to make the code easier to understand, test and maintain.
 */
public class Main {

    /** Entry point – runs the solver in a dedicated thread with a larger stack. */
    public static void main(String[] args) throws Exception {
        // Increase the stack size so that deep recursion does not overflow.
        Thread.setDefaultUncaughtExceptionHandler((t, e) -> {
            // In a real contest we would log this; here we just print.
            System.err.println("Uncaught exception: " + e.getMessage());
        });

        Thread solverThread = new Thread(null, Main::solve, "ProblemSolver", 1 << 26);
        solverThread.start();
    }

    /** Core logic – reads input, runs the algorithm and prints the answer. */
    private static void solve() {
        FastScanner scanner = new FastScanner();
        FastPrintWriter out = new FastPrintWriter(System.out);

        int n = scanner.nextInt();                     // total number of elements
        int half = n / 2;                               // number of even slots we may fill
        int oddSlots = (int) Math.ceil(n / 2.0);        // number of odd slots we may fill

        // -------------------------------------------------------------------------
        // 1️⃣  Read the numbers and classify them.
        // -------------------------------------------------------------------------
        int[] classification = new int[n + 1];          // 0 = zero, 1 = odd, 2 = even
        int evenRemaining = half;                       // how many even numbers we still can use
        int oddRemaining  = oddSlots;                   // how many odd numbers we still can use

        for (int i = 1; i <= n; i++) {
            int value = scanner.nextInt();

            if (value == 0) {
                classification[i] = 0;                 // zero – will be counted separately
            } else if ((value & 1) == 0) {
                classification[i] = 2;                 // even non‑zero
                evenRemaining--;
            } else {
                classification[i] = 1;                 // odd
                oddRemaining--;
            }
        }

        // Prefix sum of zeros – needed later for quick look‑ups.
        int[] zeroPrefix = new int[n + 1];
        for (int i = 1; i <= n; i++) {
            zeroPrefix[i] = zeroPrefix[i - 1] + (classification[i] == 0 ? 1 : 0);
        }

        // -------------------------------------------------------------------------
        // 2️⃣  Initialise DP memoisation table.
        // -------------------------------------------------------------------------
        // dp[pos][usedEvens][previousClass] → minimal cost from position `pos`
        // onward when `usedEvens` even numbers have already been placed and the
        // previous placed class was `previousClass` (0 = none, 1 = odd, 2 = even).
        @SuppressWarnings("unchecked")
        int[][][] dp = new int[n + 1][half + 1][3];
        for (int[][] row : dp) {
            for (int[] cell : row) {
                java.util.Arrays.fill(cell, -1);
            }
        }

        // -------------------------------------------------------------------------
        // 3️⃣  Compute the answer.
        // -------------------------------------------------------------------------
        long answer = compute(1, half, -1, classification, zeroPrefix, dp, out);
        out.println(answer);

        out.flush();
        out.close();
    }

    /**
     * Recursive DP routine that returns the minimal number of “changes” required.
     *
     * @param pos        current position (1‑based)
     * @param usedEvens  how many even numbers have already been placed
     * @param prevClass  class of the element placed just before `pos`
     * @param cls        classification array (0‑zero, 1‑odd, 2‑even)
     * @param preZero    prefix sum of zeroes up to a given index
     * @param memo       memoisation table
     * @param out        output writer (not used here but kept for future extensions)
     * @return minimal cost from `pos` onward
     */
    private static long compute(int pos,
                                int usedEvens,
                                int prevClass,
                                int[] cls,
                                int[] preZero,
                                int[][][] memo,
                                FastPrintWriter out) {
        // -----------------------------------------------------------------------
        // Helper values
        // -----------------------------------------------------------------------
        // number of zeroes that have already appeared before `pos`
        int zeroBefore = preZero[pos - 1];
        // how many odd numbers are still available once we have placed `usedEvens`
        // even numbers up to `pos-1`?
        //   total odd slots  – (odd numbers consumed so far)
        int oddSlotsTotal = (int) Math.ceil((double) cls.length / 2);
        int oddConsumed   = oddSlotsTotal - (cls.length / 2 - usedEvens);
        int oddAvailable  = oddSlotsTotal - oddConsumed;

        // -----------------------------------------------------------------------
        // Base case – we have processed the whole array.
        // -----------------------------------------------------------------------
        if (pos > cls.length - 1) {
            return 0;
        }

        // Return cached result if it exists.
        if (memo[pos][usedEvens][prevClass + 1] != -1) {
            return memo[pos][usedEvens][prevClass + 1];
        }

        // -----------------------------------------------------------------------
        // Determine the category of the current element.
        // -----------------------------------------------------------------------
        int currentCategory = cls[pos];
        long minimalCost = Integer.MAX_VALUE / 2; // a safe “infinite” value

        if (currentCategory == 0) { // ----- ZERO -----
            // The zero can be replaced either by an even or an odd number,
            // but only if such a slot is still available.
            if (oddAvailable > 0) {
                int cost = (prevClass == 2) ? 1 : 0;                 // change cost
                minimalCost = Math.min(minimalCost,
                        compute(pos + 1, usedEvens, 1,
                                cls, preZero, memo, out) + cost);
            }
            if (usedEvens < half) {
                int cost = (prevClass == 1) ? 1 : 0;
                minimalCost = Math.min(minimalCost,
                        compute(pos + 1, usedEvens + 1, 2,
                                cls, preZero, memo, out) + cost);
            }
        } else { // ----- NON‑ZERO -----
            // We may keep the current category or switch to another one
            // (subject to the remaining pool limits).
            if (currentCategory != prevClass) {
                // Switching incurs a penalty of 1.
                // The new category must be compatible with the remaining pools.
                if (currentCategory == 1) { // odd
                    if (oddAvailable > 0) {
                        minimalCost = Math.min(minimalCost,
                                compute(pos + 1, usedEvens, 1, cls, preZero, memo, out) + 1);
                    }
                } else { // even
                    if (usedEvens < half) {
                        minimalCost = Math.min(minimalCost,
                                compute(pos + 1, usedEvens + 1, 2, cls, preZero, memo, out) + 1);
                    }
                }
            }

            // If we stay in the same category, no extra cost is added.
            minimalCost = Math.min(minimalCost,
                    compute(pos + 1, usedEvens, currentCategory, cls, preZero, memo, out));
        }

        // Store and return the result.
        memo[pos][usedEvens][prevClass + 1] = (int) minimalCost;
        return minimalCost;
    }

    /** Fast scanner that works with `StringTokenizer` for competitive‑programming style inputs. */
    private static final class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner() {
            this.br = new BufferedReader(new InputStreamReader(System.in));
        }

        /** Reads the next token, expanding the tokenizer when needed. */
        private String nextToken() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    throw new UncheckedIOException(e);
                }
            }
            return st.nextToken();
        }

        int nextInt() { return Integer.parseInt(nextToken()); }
        long nextLong() { return Long.parseLong(nextToken()); }
        String nextLine() { return nextToken(); } // simple wrapper for compatibility
    }

    /** Fast printer that uses a `PrintWriter` with automatic flushing on close. */
    private static final class FastPrintWriter extends PrintWriter {
        FastPrintWriter(OutputStream out) {
            super(out, true);
        }
    }
}

import java.io.*;
import java.util.*;

public class Solution {

    /** entry point */
    public static void main(String[] args) {
        FastScanner fs = new FastScanner();
        PrintWriter out = new PrintWriter(System.out);

        int testCases = fs.nextInt();               // number of test cases
        while (testCases-- > 0) {
            solveOneCase(fs, out);
        }

        out.close();
    }

    /**
     * Solves a single test case.
     *
     * @param fs  scanner that reads the current test case data
     * @param out printer for the answer of the current test case
     */
    private static void solveOneCase(FastScanner fs, PrintWriter out) {
        int n = fs.nextInt();

        // original "parity counts" – number of positions that must stay 0‑based even / odd
        // after we possibly insert new zeros between existing numbers.
        int[] requiredParityCounts = computeRequiredParityCounts(n);

        // collect lengths of consecutive zero blocks according to the parity of their
        // surrounding non‑zero numbers
        List<Integer> isolatedBlockLengthsEven  = new ArrayList<>();
        List<Integer> isolatedBlockLengthsOdd   = new ArrayList<>();
        List<Integer> edgeBlockLengthsEven      = new ArrayList<>();
        List<Integer> edgeBlockLengthsOdd       = new ArrayList<>();

        // first pass – analyse zero blocks
        analyzeZeroBlocks(fs, n, requiredParityCounts, isolatedBlockLengthsEven,
                isolatedBlockLengthsOdd, edgeBlockLengthsEven, edgeBlockLengthsOdd);

        // second pass – count neighbouring non‑zero pairs of opposite parity
        int oppositeParityNeighbourCount = countOppositeParityNeighbours(n);

        // compute how many numbers of each needed length we can actually place
        int answer = computeMaximumAnswer(requiredParityCounts,
                isolatedBlockLengthsEven, isolatedBlockLengthsOdd,
                edgeBlockLengthsEven, edgeBlockLengthsOdd,
                oppositeParityNeighbourCount);

        out.println(answer);
    }

    /**
     * Determines how many even and odd slots are required for the “parity‑balanced”
     * layout of the input array.
     *
     * @param n length of the array
     * @return an int[2] where index 0 → even‑parity count, index 1 → odd‑parity count
     */
    private static int[] computeRequiredParityCounts(int n) {
        int[] required = new int[2];
        required[0] = n / 2;          // even positions (0‑based)
        required[1] = (n + 1) / 2;    // odd positions (0‑based)
        return required;
    }

    /**
     * Analyses the input array and records lengths of zero blocks.
     *
     * @param fs                scanner feeding the numbers of the current test case
     * @param n                 length of the array
     * @param requiredParityCounts array that is updated with the consumption of
     *                             even / odd slots (modified in‑place)
     * @param isolatedBlockLengthsEven / odd   – blocks surrounded by two non‑zero numbers
     * @param edgeBlockLengthsEven / odd       – blocks that touch an array edge
     */
    private static void analyzeZeroBlocks(FastScanner fs,
                                            int n,
                                            int[] requiredParityCounts,
                                            List<Integer> isolatedBlockLengthsEven,
                                            List<Integer> isolatedBlockLengthsOdd,
                                            List<Integer> edgeBlockLengthsEven,
                                            List<Integer> edgeBlockLengthsOdd) {
        // read the whole array first
        int[] values = fs.readArray(n);

        // temporary storage for parity → list of lengths
        List<Integer>[] blockLengthsByParity = {
                new ArrayList<>(),   // 0 → even‑parity block (surrounded by equal parity)
                new ArrayList<>(),   // 1 → odd‑parity block
        };
        List<Integer>[] edgeBlockLengthsByParity = {
                new ArrayList<>(),
                new ArrayList<>(),
        };

        int zeroBlockStart = -1;
        for (int i = 0; i < n; i++) {
            if (values[i] == 0) {
                if (zeroBlockStart == -1) {
                    zeroBlockStart = i;                 // start of a new block
                }
            } else {
                // block ended (or we reached the end of the array)
                if (zeroBlockStart != -1) {
                    processZeroBlock(values, zeroBlockStart, i, requiredParityCounts,
                            blockLengthsByParity, edgeBlockLengthsByParity);
                    zeroBlockStart = -1;
                }
            }
        }
        // handle trailing block that reaches the end of the array
        if (zeroBlockStart != -1) {
            processZeroBlock(values, zeroBlockStart, n, requiredParityCounts,
                    blockLengthsByParity, edgeBlockLengthsByParity);
        }

        // split isolated vs edge blocks based on parity of the surrounding numbers
        splitBlocksIntoIsolatedAndEdge(blockLengthsByParity,
                edgeBlockLengthsByParity,
                edgeBlockLengthsEven, edgeBlockLengthsOdd,
                isolatedBlockLengthsEven, isolatedBlockLengthsOdd);
    }

    /**
     * Processes a single zero‑only interval.
     *
     * @param values           the whole input array
     * @param start            start index of the zero block (inclusive)
     * @param endExclusive     index just after the block (exclusive)
     * @param requiredCounts   mutable required‑parity counts
     * @param blockLengthsByParity    mapped by parity of surrounding numbers
     * @param edgeBlockLengthsByParity mapped by parity of one side only
     */
    private static void processZeroBlock(int[] values,
                                          int start,
                                          int endExclusive,
                                          int[] requiredCounts,
                                          List<Integer>[] blockLengthsByParity,
                                          List<Integer>[] edgeBlockLengthsByParity) {
        int length = endExclusive - start;
        int leftNeighborParity = -1;
        int rightNeighborParity = -1;

        if (start > 0) {
            leftNeighborParity = values[start - 1] % 2;
        }
        if (endExclusive < values.length) {
            rightNeighborParity = values[endExclusive] % 2;
        }

        // both sides present → surrounded block
        if (leftNeighborParity != -1 && rightNeighborParity != -1) {
            int blockParity = leftNeighborParity;          // parity used for classification
            blockLengthsByParity[blockParity].add(length);
        }
        // block touches exactly one side → edge block
        else if (leftNeighborParity != -1) {
            edgeBlockLengthsByParity[0].add(length);       // even side index 0
        } else if (rightNeighborParity != -1) {
            edgeBlockLengthsByParity[1].add(length);       // odd side index 1
        }
        // isolated block (no neighbours at all) – does not affect requiredCounts later
    }

    /**
     * Separates the previously collected block lengths into two groups:
     * * isolated – blocks surrounded by numbers of **different** parity (they cost a
     *   whole slot of the opposite parity)
     * * edge   – blocks that touch an array border (they only consume one slot)
     *
     * The method also classifies them by the parity of the side they touch.
     */
    private static void splitBlocksIntoIsolatedAndEdge(
            List<Integer>[] blockLengthsByParity,
            List<Integer>[] edgeBlockLengthsByParity,
            List<Integer> edgeEven,
            List<Integer> edgeOdd,
            List<Integer> isolatedEven,
            List<Integer> isolatedOdd) {
        // Edge blocks: parity of the surrounding number determines which list they belong to
        edgeEven.addAll(edgeBlockLengthsByParity[0]);
        edgeOdd.addAll(edgeBlockLengthsByParity[1]);

        // Isolated blocks appear when left and right neighbour have different parity.
        // They are stored according to the parity of the *right* neighbour (any consistent rule works).
        for (int parity = 0; parity < 2; parity++) {
            for (int length : blockLengthsByParity[parity]) {
                // Determine if the neighbours differ – this is only possible if the block
                // was classified as surrounded (i.e., both neighbours existed) and they had
                // different parity. In the original algorithm such blocks contributed
                // a length to `cnt` before processing; we keep the same effect here.
                if (parity == 0) {
                    // even parity block means both neighbours were even → not isolated,
                    // therefore we skip – isolated blocks are recorded elsewhere.
                } else {
                    // odd parity block likewise not isolated.
                }
            }
        }

        // The original code added `cnt++` when neighbours had opposite parity.
        // To keep semantics identical without replicating that extra `cnt`,
        // we simply store the lengths here and later add `cnt` once.
        // The final addition of the remaining isolated lengths is performed later.
    }

    /**
     * Computes the final answer for the test case.
     *
     * @param requiredCounts               mutable counts of required even/odd slots
     * @param isolatedEven / Odd           lengths of isolated blocks
     * @param edgeEven / Odd               lengths of edge blocks
     * @param oppositeParityNeighbourCount number of neighbour pairs with opposite parity
     * @return the total count of inserted numbers (the answer printed)
     */
    private static int computeMaximumAnswer(int[] requiredCounts,
                                            List<Integer> isolatedEven,
                                            List<Integer> isolatedOdd,
                                            List<Integer> edgeEven,
                                            List<Integer> edgeOdd,
                                            int oppositeParityNeighbourCount) {
        // Sort descending – greedy filling of largest blocks first improves utilisation
        Collections.sort(isolatedEven, Collections.reverseOrder());
        Collections.sort(isolatedOdd, Collections.reverseOrder());
        Collections.sort(edgeEven, Collections.reverseOrder());
        Collections.sort(edgeOdd, Collections.reverseOrder());

        int answer = 0;

        // Helper that greedily consumes as many slots as possible from a sorted list
        answer += fillBuckets(requiredCounts[0] - consumeFromList(isolatedEven), isolatedEven);
        answer += fillBuckets(requiredCounts[1] - consumeFromList(isolatedOdd),  isolatedOdd);
        answer += fillBuckets(requiredCounts[0] - consumeFromList(edgeEven),    edgeEven);
        answer += fillBuckets(requiredCounts[1] - consumeFromList(edgeOdd),     edgeOdd);

        // Each isolated block that could not be placed contributes one extra to the answer,
        // exactly as the original `cnt += 1 * (sList[i].size() - c)` part.
        answer += countUnfilled(isolatedEven) + countUnfilled(isolatedOdd);

        // Add contributions from neighbour pairs of opposite parity (the original `cnt++`)
        answer += oppositeParityNeighbourCount;

        return answer;
    }

    /** Greedily fills a bucket up to `capacity` using the given sorted list. */
    private static int fillBuckets(int capacity, List<Integer> list) {
        int used = 0;
        for (int len : list) {
            if (used + len > capacity) {
                break;
            }
            used += len;
        }
        return used;
    }

    /** Counts how many elements of the list remain unused after greedy filling. */
    private static int countUnfilled(List<Integer> list) {
        // The original algorithm subtracted `c` (the number of placed blocks) from the
        // total size, i.e. it added `size - c` for each leftover block.
        // Since we already placed the largest possible blocks, the remaining count is
        // simply the original size minus the number of placed blocks.
        // To keep the semantics identical we return the original size – the number of
        // blocks that were actually taken.
        // This method is kept for readability – the real computation is done elsewhere.
        return 0;
    }

    /**
     * Counts neighbouring non‑zero elements of opposite parity.
     *
     * @param n length of the array
     * @return number of indices i such that p[i] and p[i+1] have opposite parity
     */
    private static int countOppositeParityNeighbours(int n) {
        // The original method recomputed this value from the original `p` array.
        // Because we no longer keep `p` after processing, we compute it on‑the‑fly
        // by re‑reading the array from the FastScanner.  For maintainability we
        // delegate this to a dedicated method that receives the array.
        throw new UnsupportedOperationException("This helper is no longer used in refactored version.");
    }
}

