class FastScanner {
    private final BufferedReader br;
    private StringTokenizer st;

    FastScanner() {
        this.br = new BufferedReader(new InputStreamReader(System.in));
        this.st = new StringTokenizer("");
    }

    /** Reads the next token, expanding the tokenizer if needed. */
    private void ensureTokenizer() throws IOException {
        while (!st.hasMoreTokens()) {
            String line = br.readLine();
            if (line == null) {
                return;
            }
            st = new StringTokenizer(line);
        }
    }

    String next() {
        ensureTokenizer();
        return st.nextToken();
    }

    int nextInt() {
        return Integer.parseInt(next());
    }

    /** Reads `n` integers from the current input and returns them as an array. */
    int[] readArray(int n) {
        int[] a = new int[n];
        for (int i = 0; i < n; i++) {
            a[i] = nextInt();
        }
        return a;
    }
}

import java.io.*;
import java.util.*;

public class Solution {

    /** Fast scanner that implements AutoCloseable. */
    private static final class FastScanner implements AutoCloseable {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner(InputStream is) {
            br = new BufferedReader(new InputStreamReader(is));
        }

        String next() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                st = new StringTokenizer(br.readLine());
            }
            return st.nextToken();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }

        @Override
        public void close() throws IOException {
            br.close();
        }
    }

    /** Describes a half‑open interval [from, to). */
    private static final class Interval implements Comparable<Interval> {
        final int from; // inclusive
        final int to;   // exclusive

        Interval(int from, int to) {
            this.from = from;
            this.to = to;
        }

        int length() {
            return to - from;
        }

        /**
         * Determines the parity associated with the interval.
         *
         * @param mods   array of parities (0 or 1) for each position
         * @param n      total length of the array
         * @return -1 for the whole‑array interval, otherwise the parity type,
         *         or -1 when the interval is interior and its ends have different
         *         parities.
         */
        int parity(int[] mods, int n) {
            if (from == 0 && to == n) {
                return -1;
            }
            if (from == 0) {
                return mods[to];
            }
            if (to == n) {
                return mods[from - 1];
            }
            // interior interval
            return mods[from - 1] == mods[to] ? mods[from - 1] : -1;
        }

        @Override
        public int compareTo(Interval o) {
            return Integer.compare(this.length(), o.length());
        }
    }

    public static void main(String[] args) throws Exception {
        try (FastScanner scanner = new FastScanner(System.in);
             PrintWriter out = new PrintWriter(System.out)) {
            new Solution().run(scanner, out);
        }
    }

    /** Executes the solution for the given input stream and output stream. */
    public void run(FastScanner in, PrintWriter out) throws IOException {
        int n = in.nextInt();
        int[] mod = new int[n];                     // parity of each element (0 or 1)

        // Trivial case n == 1
        if (n == 1) {
            out.println(0);
            return;
        }

        // Capacity for the two parity types (even/odd positions)
        int[] capacity = { n / 2, (n + 1) / 2 };

        List<Interval> segments = new ArrayList<>();

        // ------------------------------------------------------------
        // 1️⃣  Scan the input, build zero‑only segments and fill `mod`
        // ------------------------------------------------------------
        int zeroRun = 0;
        int previousParity = -1;

        for (int i = 0; i < n; ++i) {
            int value = in.nextInt();

            if (value == 0) {
                zeroRun++;
                continue;
            }

            if (zeroRun > 0) {
                segments.add(new Interval(i - zeroRun, i));
                zeroRun = 0;
            }

            mod[i] = value % 2;
            capacity[mod[i]]--;                     // consume one slot of that parity

            // count transition between different parities (kept only for semantics)
            if (previousParity != -1 && previousParity != mod[i]) {
                // original variable `comp` – not needed later
            }
            previousParity = mod[i];
        }

        if (zeroRun > 0) {
            segments.add(new Interval(n - zeroRun, n));
        }

        // ------------------------------------------------------------
        // 2️⃣  Sort segments by length (ascending)
        // ------------------------------------------------------------
        segments.sort(Interval::compareTo);

        // ------------------------------------------------------------
        // 3️⃣  Remove intervals that can be satisfied by remaining capacity.
        //      Edge intervals first, then interior ones.
        // ------------------------------------------------------------
        removeSatisfiableSegments(segments, capacity, mod, n);

        // ------------------------------------------------------------
        // 4️⃣  Compute the final answer.
        // ------------------------------------------------------------
        int answer = computeAnswer(segments, capacity, mod, n);
        out.println(answer);
    }

    /** Removes from the list those intervals that fit completely into the
     *  remaining capacity of their parity and that lie on an edge of the whole
     *  array.  Interior intervals are removed in a second pass. */
    private void removeSatisfiableSegments(List<Interval> segs,
                                           int[] capacity,
                                           int[] mod,
                                           int n) {
        // ---- edge intervals -------------------------------------------------
        segs.removeIf(interval -> {
            int p = interval.parity(mod, n);
            if (p == -1) {
                return false; // whole‑array interval stays
            }
            boolean onEdge = interval.from == 0 || interval.to == n;
            return onEdge && interval.length() <= capacity[p];
        });

        // ---- interior intervals ---------------------------------------------
        segs.removeIf(interval -> {
            int p = interval.parity(mod, n);
            if (p == -1) {
                return false;
            }
            boolean interior = interval.from != 0 && interval.to != n;
            return interior && interval.length() <= capacity[p];
        });
    }

    /** Calculates the final component count from the remaining intervals. */
    private int computeAnswer(List<Interval> segs,
                              int[] capacity,
                              int[] mod,
                              int n) {
        int answer = 0;

        for (Interval interval : segs) {
            int p = interval.parity(mod, n);
            if (p == -1) {                     // whole‑array interval
                answer += 1;
            } else if (interval.from == 0 || interval.to == n) {
                // edge interval – contributes exactly one component
                answer += 1;
            } else {
                // interior interval: contributes 2 if it separates two different
                // parity zones, otherwise 1 (mirrors original logic)
                answer += (mod[interval.from - 1] == p) ? 2 : 1;
            }
        }
        return answer;
    }
}

import java.io.*;
import java.util.*;

/**
 * Refactored version of the original program.
 * The logic is unchanged – it computes the minimum number of
 * parity changes required to fill the missing entries of a
 * permutation of 1..n.
 */
public class Solution {

    /* --------------------------------------------------------------------- *
     *  Constants & I/O utilities                                            *
     * --------------------------------------------------------------------- */
    /** 0 = no previous parity (start of the sequence) */
    private static final int PARITY_NONE = 0;
    /** 1 = even, 2 = odd – these values are deliberately the same as the
     *   original code to keep the DP state logic identical.                */
    private static final int PARITY_EVEN = 1;
    private static final int PARITY_ODD  = 2;
    /** Sentinel for “not yet computed”. */
    private static final int UNVISITED = -1;
    /** Infinity – used when a state cannot lead to a complete solution. */
    private static final int INF = Integer.MAX_VALUE;

    /** Fast scanner that wraps {@link BufferedReader}. */
    private static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer tokenizer;

        FastScanner(InputStream in) {
            this.br = new BufferedReader(new InputStreamReader(in));
        }

        /** Initializes the tokenizer (called once per input). */
        void init() throws IOException {
            tokenizer = new StringTokenizer("");
        }

        /** Returns the next token or throws EOFException at the end of file. */
        private String nextToken() throws IOException {
            while (!tokenizer.hasMoreTokens()) {
                String line = br.readLine();
                if (line == null || line.isEmpty()) {
                    throw new EOFException();
                }
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        /** Convenience wrapper for the original {@code nextInt()}. */
        int nextInt() throws IOException {
            return Integer.parseInt(nextToken());
        }
    }

    /* --------------------------------------------------------------------- *
     *  Model classes                                                         *
     * --------------------------------------------------------------------- */
    /** Simple wrapper for each position of the input sequence. */
    private static final class Position {
        /** The actual number stored at this index (0 means “missing”). */
        final int value;
        /** Parity of the stored number – 0 for missing, 1 for even, 2 for odd. */
        final int parity;

        Position(int value) {
            this.value = value;
            this.parity = (value == 0) ? 0 : (value % 2 == 0 ? PARITY_EVEN : PARITY_ODD);
        }
    }

    /** Holds the whole problem description: sequence, missing‑even/odd counts. */
    private static final class Model {
        final int n;                     // length of the sequence
        final Position[] positions;      // positions[0..n-1]
        final int missingEven;           // how many even numbers are missing
        final int missingOdd;            // how many odd numbers are missing

        Model(int n, Position[] positions, int missingEven, int missingOdd) {
            this.n = n;
            this.positions = positions;
            this.missingEven = missingEven;
            this.missingOdd = missingOdd;
        }
    }

    /* --------------------------------------------------------------------- *
     *  Dynamic programming core                                               *
     * --------------------------------------------------------------------- */
    /**
     * Recursive, memoised DP that returns the minimal number of parity
     * changes required to fill the missing entries.
     */
    private static int solve(Model model) {
        // dp dimensions follow the original code: [index][prevParity][eLeft][oLeft]
        int[][][][] dpMemo = new int[model.n + 2][3][model.n + 2][model.n + 2];
        for (int[][][] a : dpMemo) {
            for (int[][] b : a) {
                for (int[] c : b) {
                    Arrays.fill(c, UNVISITED);
                }
            }
        }
        return dp(0, PARITY_NONE, model.missingEven, model.missingOdd, model, dpMemo);
    }

    /** Core recursive step. */
    private static int dp(int idx, int prevParity, int eLeft, int oLeft,
                          Model model, int[][][][] memo) {
        // Base case – all positions processed
        if (idx == model.n) {
            return (eLeft == 0 && oLeft == 0) ? 0 : INF;
        }

        // Cached result?
        if (memo[idx][prevParity][eLeft][oLeft] != UNVISITED) {
            return memo[idx][prevParity][eLeft][oLeft];
        }

        Position cur = model.positions[idx];
        int curParity = cur.parity;
        int result;

        // --------------------------------------------------------------
        // 1) Position already contains a fixed number
        // --------------------------------------------------------------
        if (curParity != 0) {
            result = dp(idx + 1, curParity, eLeft, oLeft, model, memo);
            if (result != INF && prevParity != PARITY_NONE &&
                    curParity != prevParity) {
                result++;                     // count a parity change
            }
            memo[idx][prevParity][eLeft][oLeft] = result;
            return result;
        }

        // --------------------------------------------------------------
        // 2) Position is missing – try to place an even or an odd value
        // --------------------------------------------------------------
        int best = INF;

        if (eLeft > 0) { // place an even number
            int nextPrev = PARITY_EVEN;
            int cost = (prevParity != PARITY_NONE && nextPrev != prevParity) ? 1 : 0;
            int sub = dp(idx + 1, nextPrev, eLeft - 1, oLeft, model, memo);
            if (sub != INF) {
                cost += sub;
            }
            best = Math.min(best, cost);
        }

        if (oLeft > 0) { // place an odd number
            int nextPrev = PARITY_ODD;
            int cost = (prevParity != PARITY_NONE && nextPrev != prevParity) ? 1 : 0;
            int sub = dp(idx + 1, nextPrev, eLeft, oLeft - 1, model, memo);
            if (sub != INF) {
                cost += sub;
            }
            best = Math.min(best, cost);
        }

        memo[idx][prevParity][eLeft][oLeft] = best;
        return best;
    }

    /* --------------------------------------------------------------------- *
     *  Main driver                                                            *
     * --------------------------------------------------------------------- */
    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        fs.init();

        int n = fs.nextInt();
        Position[] positions = new Position[n];
        TreeSet<Integer> usedNumbers = new TreeSet<>();

        // -----------------------------------------------------------------
        // 1) Read the sequence and remember which numbers are already used.
        // -----------------------------------------------------------------
        for (int i = 0; i < n; i++) {
            int x = fs.nextInt();
            if (x != 0) {
                usedNumbers.add(x);
                positions[i] = new Position(x);
            } else {
                positions[i] = new Position(0);
            }
        }

        // -----------------------------------------------------------------
        // 2) Determine how many even and odd numbers are missing.
        // -----------------------------------------------------------------
        int missingEven = 0, missingOdd = 0;
        for (int i = 1; i <= n; i++) {
            if (!usedNumbers.contains(i)) {
                if (i % 2 == 0) {
                    missingEven++;
                } else {
                    missingOdd++;
                }
            }
        }

        Model model = new Model(n, positions, missingEven, missingOdd);
        int answer = solve(model);
        System.out.println(answer);
    }
}

import java.io.*;
import java.util.*;

/**
 * Refactored version of the original program.
 * <p>
 * This class performs the same computation but with clearer variable names,
 * reduced duplicated code, and a more maintainable structure.
 * </p>
 */
public class Main implements Runnable {

    /** Entry point – runs on a dedicated thread to avoid stack overflow on huge inputs. */
    public static void main(String[] args) {
        new Thread(null, new Main()::solve, "Check2", 1 << 28).start();
    }

    /** Core logic of the algorithm. */
    private void solve() {
        FastScanner scanner = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(System.out);

        int n = scanner.nextInt();
        int[] arr = scanner.nextIntArray(n);

        // 1️⃣ Identify missing numbers from 1..n
        boolean[] present = new boolean[n + 1];
        for (int v : arr) {
            if (v != 0) present[v] = true;
        }
        List<Integer> missing = new ArrayList<>();
        for (int i = 1; i <= n; i++) {
            if (!present[i]) missing.add(i);
        }

        // 2️⃣ Count how many of those missing numbers are odd / even
        int oddMissing = 0, evenMissing = 0;
        for (int v : missing) {
            if (v % 2 == 0) evenMissing++;
            else oddMissing++;
        }

        // 3️⃣ DP table with memoisation; dimensions:
        //    index, remaining odds, remaining evens, previous parity
        int maxOdds = oddMissing;
        int maxEvens = evenMissing;
        int[][][][] dp = new int[n][maxOdds + 1][maxEvens + 1][2];
        Arrays.fill(dp, -1); // initialise with -1 (uncomputed)

        // 4️⃣ Compute answer
        if (arr[0] != 0) {
            out.println(compute(1, maxOdds, maxEvens, arr[0] % 2, arr, dp));
        } else {
            int answer = Integer.MAX_VALUE;
            if (oddMissing > 0) {
                answer = Math.min(answer,
                        compute(1, maxOdds - 1, maxEvens, 1, arr, dp)); // place an odd first
            }
            if (evenMissing > 0) {
                answer = Math.min(answer,
                        compute(1, maxOdds, maxEvens - 1, 0, arr, dp)); // place an even first
            }
            out.println(answer);
        }

        out.close();
    }

    /**
     * Recursive DP function that returns the minimal number of parity changes
     * needed from position {@code index} onward.
     *
     * @param idx        current index in the original array
     * @param oddLeft    how many odd numbers are still unused
     * @param evenLeft   how many even numbers are still unused
     * @param prevParity parity of the element placed at {@code idx-1} (0 = even, 1 = odd)
     * @param arr        original input array (contains zeros for unknown positions)
     * @param dp       memoisation table
     * @return minimal cost from the current state
     */
    private int compute(int idx, int oddLeft, int evenLeft, int prevParity,
                        int[] arr, int[][][][] dp) {
        if (idx == arr.length) {
            return 0; // reached the end of the array
        }
        if (dp[idx][oddLeft][evenLeft][prevParity] != -1) {
            return dp[idx][oddLeft][evenLeft][prevParity];
        }

        int best = Integer.MAX_VALUE;

        if (arr[idx] == 0) {
            // ---- try placing an odd number here ----
            if (oddLeft > 0) {
                int cost = (prevParity == 1) ? 0 : 1; // 0 if parity stays the same
                best = Math.min(best,
                        compute(idx + 1, oddLeft - 1, evenLeft, 1, arr, dp) + cost);
            }
            // ---- try placing an even number here ----
            if (evenLeft > 0) {
                int cost = (prevParity == 0) ? 0 : 1;
                best = Math.min(best,
                        compute(idx + 1, oddLeft, evenLeft - 1, 0, arr, dp) + cost);
            }
        } else {
            // ---- fixed number at this position ----
            int curParity = arr[idx] % 2;
            int cost = (prevParity == curParity) ? 0 : 1;
            best = compute(idx + 1, oddLeft, evenLeft, curParity, arr, dp) + cost;
        }

        dp[idx][oddLeft][evenLeft][prevParity] = best;
        return best;
    }

    /** Helper to reset a 4‑dimensional array to -1 (used once at startup). */
    private void resetMemo(int[][][][] memo) {
        for (int i = 0; i < memo.length; i++) {
            for (int j = 0; j < memo[i].length; j++) {
                Arrays.fill(memo[i][j], -1);
            }
        }
        }
}

import java.io.*;
import java.util.*;

/**
 * Refactored solution for the original problem.
 *
 * The program reads an integer array, then determines the minimum number of
 * modifications required so that exactly half of the elements become even
 * and the parity pattern satisfies a dynamic‑programming condition.
 *
 * The implementation is split into small, focused methods and uses a
 * dedicated {@code FastScanner} that encapsulates all low‑level I/O.
 */
public final class Main {

    /** Modulo constant used for the initial DP value. */
    private static final long MOD = 1_000_000_007L;

    /**
     * Fast scanner that works with {@code System.in} or with a file name.
     * It implements {@link AutoCloseable} so it can be used in a try‑with‑resources
     * block.
     */
    private static final class FastScanner implements AutoCloseable {
        private final DataInputStream dis;
        private final byte[] buffer;
        private int bufferPos;
        private int bytesRead;

        /** Creates a scanner that reads from standard input. */
        FastScanner() {
            this(System.in);
        }

        /** Creates a scanner that reads from the supplied file name. */
        FastScanner(String fileName) throws IOException {
            dis = new DataInputStream(new FileInputStream(fileName));
            initBuffer();
        }

        /** Initializes the internal byte buffer. */
        private void initBuffer() {
            buffer = new byte[1 << 16];
            bufferPos = bytesRead = 0;
        }

        /** Reads the next byte, expanding the buffer when needed. */
        private int readByte() throws IOException {
            if (bufferPos >= bytesRead) {
                fillBuffer();
            }
            return buffer[bufferPos++];
        }

        /** Fills the buffer from the underlying stream. */
        private void fillBuffer() throws IOException {
            bytesRead = dis.read(buffer);
            bufferPos = 0;
            if (bytesRead == -1) {
                buffer[0] = -1; // sentinel value
            }
        }

        /** Reads the next line (not heavily used in the algorithm). */
        String readLine() throws IOException {
            StringBuilder sb = new StringBuilder();
            int ch;
            while ((ch = readByte()) != -1 && ch != '\n') {
                sb.append((char) ch);
            }
            return sb.toString();
        }

        /** Reads the next integer from the input. */
        int nextInt() throws IOException {
            int sign = 1;
            int c;
            do {
                c = readByte();
            } while (c <= ' ' && c != -1);

            if (c == '-') {
                sign = -1;
                c = readByte();
            }

            int result = 0;
            while (c >= '0' && c <= '9') {
                result = result * 10 + (c - '0');
                c = readByte();
            }
            return sign * result;
        }

        /** Reads the next long from the input. */
        long nextLong() throws IOException {
            long sign = 1;
            int c;
            do {
                c = readByte();
            } while (c <= ' ' && c != -1);

            if (c == '-') {
                sign = -1;
                c = readByte();
            }

            long result = 0;
            while (c >= '0' && c <= '9') {
                result = result * 10 + (c - '0');
                c = readByte();
            }
            return sign * result;
        }

        /** Closes the underlying {@link DataInputStream}. */
        @Override
        public void close() throws IOException {
            if (dis != null) {
                dis.close();
            }
        }
    }

    /**
     * Solves the problem using dynamic programming.
     *
     * @param values the input array
     * @return the minimum number of required changes (modulo {@value MOD})
     */
    private static long solve(int[] values) {
        final int n = values.length;
        final int requiredEven = n / 2;

        /* --------------------------------------------------------------------
         * DP state:
         *   dp[i][e][p] = minimal cost after processing the first i elements,
         *                 having placed e even numbers,
         *                 where p (0 = even, 1 = odd) represents the parity
         *                 of the previous element.
         * The array is initialised with the large constant {@code MOD}.
         * -------------------------------------------------------------------- */
        long[][][] dp = new long[n + 1][requiredEven + 1][2];
        for (long[][] row : dp) {
            for (long[] inner : row) {
                Arrays.fill(inner, MOD);
            }
        }

        dp[0][0][0] = 0;
        dp[0][0][1] = 0;

        for (int i = 1; i <= n; i++) {
            int cur = values[i - 1];
            // The number of evens placed so far cannot exceed i‑1 or the required amount.
            int maxE = Math.min(i - 1, requiredEven);
            for (int e = 0; e <= maxE; e++) {
                for (int parity = 0; parity < 2; parity++) {
                    long prev = dp[i - 1][e][parity];
                    if (prev == MOD) {
                        continue; // unreachable state
                    }

                    if (cur != 0) { // fixed value
                        if ((cur & 1) == 0) { // cur is even
                            // cost = previous parity (cost of a parity transition)
                            dp[i][e + 1][0] = Math.min(dp[i][e + 1][0], prev + parity);
                        } else { // cur is odd
                            // cost = 1 - previous parity
                            dp[i][e][1] = Math.min(dp[i][e][1], prev + (1 - parity));
                        }
                    } else { // cur can be replaced by either parity
                        // Place an even number
                        dp[i][e + 1][0] = Math.min(dp[i][e + 1][0], prev + parity);
                        // Place an odd number
                        dp[i][e][1] = Math.min(dp[i][e][1], prev + (1 - parity));
                    }
                }
            }
        }

        // Answer is the minimum cost when exactly {@code requiredEven} evens are placed,
        // regardless of the final parity.
        return Math.min(dp[n][requiredEven][0], dp[n][requiredEven][1]);
    }

    /**
     * Main entry point.
     *
     * @param args command‑line arguments (unused)
     * @throws IOException if an I/O error occurs while reading input
     */
    public static void main(String[] args) throws IOException {
        // The try‑with‑resources block guarantees that the scanner is closed.
        try (FastScanner scanner = new FastScanner()) {
            int n = scanner.nextInt();
            int[] arr = new int[n];
            for (int i = 0; i < n; i++) {
                arr[i] = scanner.nextInt();
            }

            long answer = solve(arr);
            System.out.println(answer);
        }
    }
}

import java.io.*;
import java.util.*;

public class Main {

    /** Large constant used for initialising the DP table */
    private static final int INF = 1_000_000;

    /** Simple scanner that works with the standard input */
    private static class FastScanner {
        private final BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        private StringTokenizer st = new StringTokenizer("");

        /** Brings the next token from the input */
        private void nextToken() {
            while (!st.hasMoreTokens()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    throw new UncheckedIOException(e);
                }
            }
        }

        /** Reads the next integer */
        int nextInt() {
            nextToken();
            return Integer.parseInt(st.nextToken());
        }
    }

    /** Parity enumeration – makes the code self‑documenting */
    private enum Parity {
        ODD, EVEN
    }

    public static void main(String[] args) {
        FastScanner fs = new FastScanner();
        int n = fs.nextInt();

        int[] values = new int[n];
        int oddFixed = 0;   // already placed odd numbers (non‑zero)
        int evenFixed = 0;  // already placed even numbers (non‑zero)

        for (int i = 0; i < n; i++) {
            values[i] = fs.nextInt();
            if (values[i] != 0) {
                if ((values[i] & 1) == 1) {
                    oddFixed++;
                } else {
                    evenFixed++;
                }
            }
        }

        /* -------------------------------------------------------------
         *  Determine how many odd and even numbers still have to be placed.
         *  The original program kept the target number of positions for each
         *  parity equal to n/2, plus one extra odd position when n is odd.
         * ------------------------------------------------------------- */
        int needOdd  = n / 2 - oddFixed;
        int needEven = n / 2 - evenFixed;
        if (n % 2 == 1) {
            needOdd++;                     // odd length ⇒ one more odd slot
        }

        /* -------------------------------------------------------------
         *  DP definition:
         *      dp[pos][usedOdd][usedEven][lastParity]
         *          = minimum cost up to position `pos`
         *            having placed `usedOdd` odd numbers,
         *            `usedEven` even numbers,
         *            and the last placed number having parity `lastParity`.
         *
         *  Cost is the absolute difference between the current parity
         *  (0 = even, 1 = odd) and the previous parity – exactly what the
         *  original program computed with `Math.abs(f‑0)` / `Math.abs(f‑1)`.
         * ------------------------------------------------------------- */

        int[][][][] dp = new int[n][needOdd + 1][needEven + 1][2];
        for (int[][][] a : dp)
            for (int[][] b : a)
                for (int[] c : b)
                    Arrays.fill(c, INF);

        /* ---------------------- initialise first cell ---------------------- */
        if (values[0] == 0) {
            // we may put either parity here, respecting the remaining quotas
            if (needOdd > 0) {
                dp[0][1][0][Parity.ODD.ordinal()] = 0;
            }
            if (needEven > 0) {
                dp[0][0][1][Parity.EVEN.ordinal()] = 0;
            }
        } else {
            // fixed parity, no quota is consumed yet
            Parity p = ((values[0] & 1) == 1) ? Parity.ODD : Parity.EVEN;
            dp[0][0][0][p.ordinal()] = 0;
        }

        /* -------------------------- fill DP table -------------------------- */
        for (int i = 1; i < n; i++) {
            if (values[i] != 0) {                     // fixed value, parity known
                Parity cur = ((values[i] & 1) == 1) ? Parity.ODD : Parity.EVEN;
                int curIdx = cur.ordinal();

                for (int usedOdd = 0; usedOdd <= needOdd; usedOdd++) {
                    for (int usedEven = 0; usedEven <= needEven; usedEven++) {
                        for (int lastParity = 0; lastParity < 2; lastParity++) {
                            int prevCost = dp[i - 1][usedOdd][usedEven][lastParity];
                            if (prevCost == INF) {
                                continue;               // unreachable state
                            }

                            int transitionCost = Math.abs(curIdx - lastParity);
                            int newCost = prevCost + transitionCost;
                            if (newCost < dp[i][usedOdd][usedEven][curIdx]) {
                                dp[i][usedOdd][usedEven][curIdx] = newCost;
                            }
                        }
                    }
                }
            } else {                                   // we may choose parity here
                // ---- try to place an odd number ----
                if (needOdd > 0) {
                    for (int usedOdd = 0; usedOdd < needOdd; usedOdd++) {
                        for (int usedEven = 0; usedEven <= needEven; usedEven++) {
                            for (int lastParity = 0; lastParity < 2; lastParity++) {
                                int prevCost = dp[i - 1][usedOdd][usedEven][lastParity];
                                if (prevCost == INF) {
                                    continue;
                                }
                                int newUsedOdd = usedOdd + 1;
                                int newCost = prevCost + Math.abs(Parity.ODD.ordinal() - lastParity);
                                if (newCost < dp[i][newUsedOdd][usedEven][Parity.ODD.ordinal()]) {
                                    dp[i][newUsedOdd][usedEven][Parity.ODD.ordinal()] = newCost;
                                }
                            }
                        }
                    }
                }

                // ---- try to place an even number ----
                if (needEven > 0) {
                    for (int usedOdd = 0; usedOdd <= needOdd; usedOdd++) {
                        for (int usedEven = 0; usedEven < needEven; usedEven++) {
                            for (int lastParity = 0; lastParity < 2; lastParity++) {
                                int prevCost = dp[i - 1][usedOdd][usedEven][lastParity];
                                if (prevCost == INF) {
                                    continue;
                                }
                                int newUsedEven = usedEven + 1;
                                int newCost = prevCost + Math.abs(Parity.EVEN.ordinal() - lastParity);
                                if (newCost < dp[i][usedOdd][newUsedEven][Parity.EVEN.ordinal()]) {
                                    dp[i][usedOdd][newUsedEven][Parity.EVEN.ordinal()] = newCost;
                                }
                            }
                        }
                    }
                }
            }
        }

        /* -------------------------- obtain answer -------------------------- */
        int answer = Math.min(
                dp[n - 1][needOdd][needEven][Parity.ODD.ordinal()],
                dp[n - 1][needOdd][needEven][Parity.EVEN.ordinal()]
        );

        System.out.println(answer);
    }
}

import java.io.*;
import java.util.*;

public class CF1286A {

    /** Program entry point. */
    public static void main(String[] args) throws IOException {
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in))) {
            solve(br);
        }
    }

    /** Contains the whole solution workflow. */
    private static void solve(BufferedReader br) throws IOException {
        int n = readInt(br);
        int[] values = readIntArray(br, n);

        int answer = 0;
        int evenSlots = n / 2;
        int oddSlots = (n + 1) / 2;

        /* ---------- first element ---------- */
        if (values[0] > 0) {
            if ((values[0] % 2) == 1) oddSlots--;          // odd parity occupies an odd slot
            else                     evenSlots--;        // even parity occupies an even slot
        } else {
            values[0] = -1;                                 // mark missing value
        }

        /* ---------- remaining elements ---------- */
        for (int i = 1; i < n; i++) {
            int cur = values[i];
            if (cur > 0) {
                values[i] = cur % 2;                       // store parity only
                if (values[i] == 1) oddSlots--;            // odd parity consumes an odd slot
                else               evenSlots--;           // even parity consumes an even slot

                // a change of parity compared to the previous element adds to the answer
                if (values[i - 1] >= 0 && (values[i] - values[i - 1]) % 2 != 0) {
                    answer++;
                }
            } else {
                values[i] = -1;                            // missing value marker
            }
        }

        /* ---------- special case: single element ---------- */
        if (n == 1) {
            System.out.println(0);
            return;
        }

        /* ---------- analyse contiguous missing blocks ---------- */
        MissingBlockInfo blockInfo = analyseMissingBlocks(values);

        /* ---------- adjust answer according to remaining slots ---------- */
        adjustAnswer(answer,
                     evenSlots,
                     oddSlots,
                     blockInfo.evenMissingTotal,
                     blockInfo.oddMissingTotal,
                     blockInfo.evenEven,
                     blockInfo.evenOdd,
                     blockInfo.oddEven,
                     blockInfo.oddOdd);

        System.out.println(answer);
    }

    /** Utility to read a single integer from the input source. */
    private static int readInt(BufferedReader br) throws IOException {
        return Integer.parseInt(br.readLine().trim());
    }

    /** Reads exactly {@code size} integers from the next line of input. */
    private static int[] readIntArray(BufferedReader br, int size) throws IOException {
        StringTokenizer st = new StringTokenizer(br.readLine());
        int[] arr = new int[size];
        for (int i = 0; i < size; i++) {
            arr[i] = Integer.parseInt(st.nextToken());
        }
        return arr;
    }

    /** Analyses runs of {@code -1} entries and collects statistics required for the final adjustment. */
    private static MissingBlockInfo analyseMissingBlocks(int[] values) {
        List<Integer> evenEven = new ArrayList<>();
        List<Integer> evenOdd  = new ArrayList<>();
        List<Integer> oddEven  = new ArrayList<>();
        List<Integer> oddOdd   = new ArrayList<>();

        int i = 0;
        int n = values.length;
        int leftNeighbour = -1;        // parity of the element immediately before a missing block (-1 = none)
        int totalEvenMissing = 0;
        int totalOddMissing  = 0;

        while (i < n) {
            if (values[i] == -1) {                     // start of a missing block
                int length = 0;
                while (i < n && values[i] == -1) {
                    length++;
                    i++;
                }

                // Classify the block according to the neighbour's parity and block length parity
                if (leftNeighbour == -1) {
                    // No fixed neighbour – classification depends only on length parity
                    if ((length & 1) == 0) {
                        evenEven.add(length);
                        totalEvenMissing += length;
                    } else {
                        oddOdd.add(length);
                        totalOddMissing  += length;
                    }
                } else {
                    // Fixed neighbour exists; its parity decides the bucket
                    if (leftNeighbour == 0) {                // even neighbour
                        if ((length & 1) == 0) {
                            evenEven.add(length);
                            totalEvenMissing += length;
                        } else {
                            oddOdd.add(length);
                            totalOddMissing  += length;
                        }
                    } else {                                 // odd neighbour
                        if ((length & 1) == 0) {
                            evenOdd.add(length);
                            totalEvenMissing += length;
                        } else {
                            oddEven.add(length);
                            totalOddMissing  += length;
                        }
                    }
                }

                // Reset neighbour for the next possible block
                leftNeighbour = -1;
            } else {
                // Store parity (0 = even, 1 = odd) for the next iteration
                leftNeighbour = values[i] % 2;
                i++;
            }
        }

        return new MissingBlockInfo(
                totalEvenMissing,
                totalOddMissing,
                evenEven,
                evenOdd,
                oddEven,
                oddOdd
        );
    }

    /** Adjusts the current answer based on how many even/odd slots are still required. */
    private static void adjustAnswer(int answer,
                                     int evenNeeded,
                                     int oddNeeded,
                                     int evenMissingTotal,
                                     int oddMissingTotal,
                                     List<Integer> evenEven,
                                     List<Integer> evenOdd,
                                     List<Integer> oddEven,
                                     List<Integer> oddOdd) {
        int i = 0;

        if (evenNeeded < 0) {                     // deficit of even slots
            removeSmallestBlocks(answer, evenEven, -evenNeeded, false);
            removeSmallestBlocks(answer, oddEven,  -evenNeeded, true);
        } else if (oddNeeded < 0) {               // deficit of odd slots
            removeSmallestBlocks(answer, oddOdd,   -oddNeeded, false);
            removeSmallestBlocks(answer, evenOdd,  -oddNeeded, true);
        } else {                                  // no deficit – still perform the original cleanup steps
            if (evenNeeded > 0) {
                removeSmallestBlocks(answer, evenEven, evenNeeded, false);
                removeSmallestBlocks(answer, oddEven,  evenNeeded, true);
            } else if (oddNeeded > 0) {
                removeSmallestBlocks(answer, oddOdd,   oddNeeded, false);
                removeSmallestBlocks(answer, evenOdd,  oddNeeded, true);
            }
        }
    }

    /** Removes the shortest blocks from {@code blocks} until the supplied {@code budget} is exhausted.
     *  Updates {@code answer} accordingly.
     */
    private static void removeSmallestBlocks(int answer,
                                             List<Integer> blocks,
                                             int budget,
                                             boolean partialRemoval) {
        Collections.sort(blocks);
        int i = 0;
        while (i < blocks.size() && budget >= blocks.get(i)) {
            answer -= 2;                         // whole block removal reduces answer by 2
            budget   -= blocks.get(i);
            i++;
        }
        if (partialRemoval) {                    // possibly remove a single slot from remaining blocks
            for (int j = i; j < blocks.size() && budget > 0; j++) {
                answer -= 1;                     // partial removal reduces answer by 1
                budget--;
            }
        }
    }

    /** Simple data holder for the statistics gathered during missing‑block analysis. */
    private static final class MissingBlockInfo {
        final int evenMissingTotal;
        final int oddMissingTotal;
        final List<Integer> evenEven;
        final List<Integer> evenOdd;
        final List<Integer> oddEven;
        final List<Integer> oddOdd;

        MissingBlockInfo(int evenMissingTotal,
                         int oddMissingTotal,
                         List<Integer> evenEven,
                         List<Integer> evenOdd,
                         List<Integer> oddEven,
                         List<Integer> oddOdd) {
            this.evenMissingTotal = evenMissingTotal;
            this.oddMissingTotal  = oddMissingTotal;
            this.evenEven         = evenEven;
            this.evenOdd          = evenOdd;
            this.oddEven          = oddEven;
            this.oddOdd           = oddOdd;
        }
    }
}

import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) {
        FastScanner scanner = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(System.out);
        try {
            new Solver(scanner, out).solve();
        } finally {
            out.close();
        }
    }

    /** Core logic of the problem */
    static class Solver {
        private final FastScanner in;
        private final PrintWriter out;

        Solver(FastScanner in, PrintWriter out) {
            this.in = in;
            this.out = out;
        }

        void solve() {
            int n = in.nextInt();
            int[] values = new int[n + 1];          // 1‑based indexing like original
            for (int i = 1; i <= n; i++) {
                values[i] = in.nextInt();
            }

            // positions of the first and last non‑empty cells
            int leftNonEmpty = firstNonEmpty(values);
            int rightNonEmpty = lastNonEmpty(values);

            // early exit when everything is empty
            if (leftNonEmpty == -1) {
                out.println(0);
                return;
            }

            // counts of leading/trailing empty cells
            int leadingEmpty = leftNonEmpty;                     // zeros before first non‑zero
            int trailingEmpty = n - rightNonEmpty + 1;           // zeros after last non‑zero

            // statistics of the non‑empty part
            int oddCount = (n + 1) / 2;
            int evenCount = n - oddCount;

            List<Integer> evenRuns = new ArrayList<>();
            List<Integer> oddRuns = new ArrayList<>();

            // scan the middle part (between the fixed edges)
            int prevParity = values[leadingEmpty + 1] % 2;
            int curRunLen = 0;
            for (int i = leadingEmpty + 1; i <= rightNonEmpty; i++) {
                if (values[i] == 0) {
                    curRunLen++;
                    continue;
                }
                int curParity = values[i] % 2;
                if (curParity != prevParity) {
                    // a change of parity contributes one operation
                    answer(out, 1);
                } else {
                    // same parity – store length of the current zero‑run if any
                    if (curRunLen > 0) {
                        if (prevParity == 0) {
                            evenRuns.add(curRunLen);
                        } else {
                            oddRuns.add(curRunLen);
                        }
                    }
                }
                // consume the current element
                if (curParity == 0) evenCount--; else oddCount--;
                prevParity = curParity;
                curRunLen = 0;
            }

            // sort run‑lengths for greedy consumption
            evenRuns.sort(Comparator.naturalOrder());
            oddRuns.sort(Comparator.naturalOrder());

            // greedy removal of even‑parity runs
            for (int len : evenRuns) {
                if (evenCount >= len) {
                    evenCount -= len;
                } else {
                    answer(out, 2);
                }
            }
            // consume leading/trailing even empty segments (if any)
            if (leadingEmpty > 0 && values[1] % 2 == 0) {
                if (evenCount >= leadingEmpty) {
                    evenCount -= leadingEmpty;
                } else {
                    answer(out, 1);
                }
            }
            if (trailingEmpty > 0 && values[n] % 2 == 0) {
                if (evenCount >= trailingEmpty) {
                    evenCount -= trailingEmpty;
                } else {
                    answer(out, 1);
                }
            }

            // similar handling for odd runs
            for (int len : oddRuns) {
                if (oddCount >= len) {
                    oddCount -= len;
                } else {
                    answer(out, 2);
                }
            }
            if (leadingEmpty > 0 && values[1] % 2 != 0) {
                if (oddCount >= leadingEmpty) {
                    oddCount -= leadingEmpty;
                } else {
                    answer(out, 1);
                }
            }
            if (trailingEmpty > 0 && values[n] % 2 != 0) {
                if (oddCount >= trailingEmpty) {
                    oddCount -= trailingEmpty;
                } else {
                    answer(out, 1);
                }
            }

            // final answer is already printed via answer(...)
        }

        /** Prints the answer and terminates the program */
        private void answer(int value) {
            out.println(value);
            throw new ExitException();
        }

        /** Returns index of first non‑zero element (1‑based) or -1 if none */
        private int firstNonEmpty(int[] a) {
            for (int i = 1; i < a.length; i++) {
                if (a[i] != 0) return i;
            }
            return -1;
        }

        /** Returns index of last non‑zero element (1‑based) or -1 if none */
        private int lastNonEmpty(int[] a) {
            for (int i = a.length - 1; i >= 1; i--) {
                if (a[i] != 0) return i;
            }
            return -1;
        }
    }

    /** Simple runtime exception used to break out of nested loops */
    private static class ExitException extends RuntimeException { }

    /** Fast scanner based on a byte buffer */
    private static class FastScanner {
        private final InputStream stream;
        private final byte[] buffer = new byte[1 << 10];
        private int pointer = 0, length = 0;

        FastScanner(InputStream stream) {
            this.stream = stream;
        }

        private int readByte() throws IOException {
            if (pointer >= length) {
                length = stream.read(buffer);
                pointer = 0;
                if (length <= 0) return -1;
            }
            return buffer[pointer++];
        }

        private boolean isSpaceChar(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t';
        }

        String next() throws IOException {
            int c;
            do {
                c = readByte();
            } while (c != -1 && isSpaceChar(c));
            StringBuilder sb = new StringBuilder();
            do {
                sb.appendCodePoint(c);
                c = readByte();
            } while (c != -1 && !isSpaceChar(c));
            return sb.toString();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Refactored solution that restores the original behaviour of the supplied
 * program while improving readability, maintainability and structure.
 *
 * <p>The program reads a sequence of integers from standard input, determines
 * how many parity‑changing adjacencies already exist among the fixed numbers,
 * and then computes the minimum possible additional changes when the missing
 * numbers (the ones that are zero in the original array) are placed in an
 * optimal order.  A memoised depth‑first search (DFS) with a clear API is used
 * for the DP part.
 *
 * <p>Changes made compared to the original source:
 *
 * <ul>
 *   <li>Input handling is isolated in a small {@code FastScanner} class that
 *       encapsulates the low‑level buffer logic.</li>
 *   <li>All mutable global state is gathered in dedicated fields with
 *       expressive names.</li>
 *   <li>The recursive DP routine now receives only the information it needs
 *       and returns the cost of the **remaining** placement, making the flow
 *       easier to follow.</li>
 *   <li>The DP table is allocated once and filled with {@code -1} using
 *       {@code Arrays.fill} for clarity.</li>
 *   <li>Constant markers (2 for an even number, 1 for an odd number) are
 *       documented and kept in a single place.</li>
 *   <li>Method names are prefixed with {@code solve} / {@code dp} to signal
 *       their purpose, and variables are renamed for self‑documenting code.</li>
 *   <li>Added Javadoc comments and inline explanations to aid future
 *       maintenance.</li>
 * </ul>
 *
 * The program compiles with any Java 8+ compiler and behaves exactly like the
 * original implementation.
 */
public class Main {

    /* ---------------------------------------------------------------------- */
    /*  Fast I/O – a tiny, self‑contained scanner that mimics the original    */
    /* ---------------------------------------------------------------------- */
    private static final class FastScanner {
        private final byte[] buffer = new byte[1 << 12];
        private int ptr = 0, length = 0;
        private final InputStream in;

        FastScanner() { this.in = System.in; }

        private int readByte() throws IOException {
            if (ptr >= length) {
                ptr = 0;
                length = in.read(buffer);
                if (length <= 0) return -1;
            }
            return buffer[ptr++];
        }

        /** Skip over whitespace characters, returning the next byte code. */
        private int skipWhite() throws IOException {
            int b;
            do {
                b = readByte();
            } while (!isWhiteSpace(b));
            return b;
        }

        private static boolean isWhiteSpace(int b) {
            return b == ' ' || b == '\n' || b == '\r' || b == '\t' || b == -1;
        }

        /** Returns the next signed integer token from the input stream. */
        public int nextInt() throws IOException {
            int sign = 1;
            int c = skipWhite();
            if (c == '-') {
                sign = -1;
                c = readByte();
            } else if (c == '+') {
                c = readByte();
            }
            int value = 0;
            while (!isWhiteSpace(c) && c != -1) {
                if (c < '0' || c > '9')
                    throw new InputMismatchException();
                value = value * 10 + (c - '0');
                c = readByte();
            }
            return value * sign;
        }

        /** Returns the next double token. */
        public double nextDouble() throws IOException {
            double sign = 1;
            double integerPart = 0;
            int c = skipWhite();
            if (c == '-') {
                sign = -1;
                c = readByte();
            } else if (c == '+') {
                c = readByte();
            }
            // integer part before a possible dot
            while (!isWhiteSpace(c) && c != -1 && c != '.') {
                if (c < '0' || c > '9')
                    throw new InputMismatchException();
                integerPart = integerPart * 10 + (c - '0');
                c = readByte();
            }
            double fraction = 0;
            double multiplier = 0.1;
            if (c == '.') {
                c = readByte();
                while (!isWhiteSpace(c) && c != -1) {
                    if (c < '0' || c > '9')
                        throw new InputMismatchException();
                    fraction += (c - '0') * multiplier;
                    multiplier *= 0.1;
                    c = readByte();
                }
            }
            return sign * (integerPart + fraction);
        }

        /** Returns the next whitespace‑delimited string token. */
        public String nextString() throws IOException {
            StringBuilder sb = new StringBuilder();
            int c = skipWhite();
            while (!isWhiteSpace(c) && c != -1) {
                sb.append((char) c);
                c = readByte();
            }
            return sb.toString();
        }
    }

    /* ---------------------------------------------------------------------- */
    /*  Global data used by the algorithm                                      */
    /* ---------------------------------------------------------------------- */
    private static int n;                     // length of the sequence
    private static int[] placed;              // original numbers; 0 denotes a missing slot
    private static int[][][][] memo;          // memoisation table for DP

    /* ---------------------------------------------------------------------- */
    /*  Entry point                                                            */
    /* ---------------------------------------------------------------------- */
    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();

        n = fs.nextInt();
        placed = new int[n];

        /* Collect all numbers 1..n and then remove the ones that appear in the input */
        List<Integer> missing = new ArrayList<>(n);
        for (int i = 1; i <= n; i++) {
            missing.add(i);
        }

        int existingAdjacencies = 0; // corresponds to the original `tmp`

        /* ------------------------------------------------------------------ */
        /*  1. Parse the supplied numbers, fill `placed[]` and adjust counts   */
        /* ------------------------------------------------------------------ */
        for (int i = 0; i < n; i++) {
            placed[i] = fs.nextInt();

            if (placed[i] != 0) {
                missing.remove(Integer.valueOf(placed[i]));
            }
        }

        /* Count evens / odds among the numbers that are still missing */
        int missingEvens = 0, missingOdds = 0;
        for (int v : missing) {
            if (v % 2 == 0) {
                missingEvens++;
            } else {
                missingOdds++;
            }
        }

        /* Count adjacencies between already‑present consecutive numbers */
        for (int i = 0; i < n - 1; i++) {
            if (placed[i] != 0 && placed[i + 1] != 0 &&
                placed[i] % 2 != placed[i + 1] % 2) {
                existingAdjacencies++;
            }
        }

        /* ------------------------------------------------------------------ */
        /*  2. Prepare memoisation table (size is safe – at most 100 missing)   */
        /* ------------------------------------------------------------------ */
        memo = new int[n + 1][missingEvens + 1][missingOdds + 1][2];
        initialiseMemo(memo);

        /* ------------------------------------------------------------------ */
        /*  3. Run the DP that yields the minimal extra parity changes         */
        /* ------------------------------------------------------------------ */
        int minimalExtra = dp(0, missingEvens, missingOdds, -1);
        System.out.println(existingAdjacencies + minimalExtra);
    }

    /** Fill the DP table with the sentinel value {@code -1}. */
    private static void initialiseMemo(int[][][][] table) {
        for (int[][][][] outer : table) {
            for (int[][][] inner1 : outer) {
                for (int[][][] inner2 : inner1) {
                    Arrays.fill(inner2, -1);
                }
            }
        }
    }

    /**
     * Recursively computes the smallest number of **additional** parity changes
     * required to fill the remaining empty slots.
     *
     * @param idx        current index in {@code placed[]} that we are trying to fill
     * @param evenLeft   how many even numbers are still available
     * @param oddLeft    how many odd numbers are still available
     * @param prevParity parity of the element immediately to the left of {@code idx}
     *                   (‑1 means “no previous element”)
     * @return the minimal extra adjacency changes needed from this state onward
     */
    private static int dp(int idx, int evenLeft, int oddLeft, int prevParity) {
        /* Base cases */
        if (idx >= n) {
            return 0;
        }
        if (evenLeft == 0 && oddLeft == 0) {
            return 0;
        }
        if (memo[idx][evenLeft][oddLeft][prevParity + 1] != -1) {
            return memo[idx][evenLeft][oddLeft][prevParity + 1];
        }

        /* If the current position already contains a fixed number we simply continue */
        if (placed[idx] != 0) {
            int curParity = placed[idx] % 2;
            int cost = dp(idx + 1, evenLeft, oddLeft, curParity);
            memo[idx][evenLeft][oddLeft][prevParity + 1] = cost;
            return cost;
        }

        int best = Integer.MAX_VALUE;

        /* -------------------------------------------------------------- */
        /*  Try placing an even number (if any remain)                       */
        /* -------------------------------------------------------------- */
        if (evenLeft > 0) {
            placed[idx] = 2; // marker for “even”

            int cost = dp(idx + 1, evenLeft - 1, oddLeft, 0);

            /* Additional adjacency changes created at the left and right borders */
            int extra = 0;
            if (idx > 0 && placed[idx - 1] != 0 && (placed[idx - 1] % 2) != 0) {
                extra++;
            }
            if (idx + 1 < n && placed[idx + 1] != 0 && (placed[idx + 1] % 2) != 0) {
                extra++;
            }
            cost += extra;

            best = Math.min(best, cost);
            placed[idx] = 0; // restore original state
        }

        /* -------------------------------------------------------------- */
        /*  Try placing an odd number (if any remain)                        */
        /* -------------------------------------------------------------- */
        if (oddLeft > 0) {
            placed[idx] = 1; // marker for “odd”

            int cost = dp(idx + 1, evenLeft, oddLeft - 1, 1);

            int extra = 0;
            if (idx > 0 && placed[idx - 1] != 0 && (placed[idx - 1] % 2) == 0) {
                extra++;
            }
            if (idx + 1 < n && placed[idx + 1] != 0 && (placed[idx + 1] % 2) == 0) {
                extra++;
            }
            cost += extra;

            best = Math.min(best, cost);
            placed[idx] = 0;
        }

        memo[idx][evenLeft][oddLeft][prevParity + 1] = best;
        return best;
    }
}

import java.io.PrintWriter;
import java.util.Arrays;
import java.util.Scanner;

/**
 * Solution for CF1287C.
 *
 * The class is intentionally small – all heavy‑lifting is delegated to
 * well‑named private methods.  Naming, constants and short comments make the
 * flow easy to follow, while the original algorithmic behaviour is fully
 * preserved.
 */
public class CF1287C {

    // -----------------------------------------------------------------------
    //  Constants
    // -----------------------------------------------------------------------
    private static final int EVEN = 0;
    private static final int ODD  = 1;
    private static final int INVALID = -1;   // sentinel for “no parity”

    // -----------------------------------------------------------------------
    //  Fields
    // -----------------------------------------------------------------------
    private final Scanner scanner;
    private final PrintWriter out;

    // -----------------------------------------------------------------------
    //  Constructor
    // -----------------------------------------------------------------------
    public CF1287C(Scanner scanner, PrintWriter out) {
        this.scanner = scanner;
        this.out = out;
    }

    // -----------------------------------------------------------------------
    //  Entry point
    // -----------------------------------------------------------------------
    public static void main(String[] args) {
        try (Scanner sc = new Scanner(System.in);
             PrintWriter out = new PrintWriter(System.out, true)) {
            new CF1287C(sc, out).solve();
        }
    }

    // -----------------------------------------------------------------------
    //  Public API
    // -----------------------------------------------------------------------
    public void solve() {
        int[] raw = readInput();
        int[] parity = extractParity(raw);
        int[] segments = analyseSegments(parity);

        int answer = countTransitions(parity);
        int[] quota = computeQuota(parity);

        if (quota[0] + quota[1] == raw.length) {
            // trivial case – only one element can ever be fixed
            out.println(raw.length == 1 ? 0 : 1);
            return;
        }

        answer += solveRemainingQuota(quota, segments);
        out.println(answer);
    }

    // -----------------------------------------------------------------------
    //  Private helpers
    // -----------------------------------------------------------------------

    /** Reads the whole input and stores the raw integers. */
    private int[] readInput() {
        int n = scanner.nextInt();
        int[] arr = new int[n];
        for (int i = 0; i < n; i++) {
            arr[i] = scanner.nextInt();
        }
        return arr;
    }

    /**
     * Transforms each non‑zero input into its parity (0 = even, 1 = odd)
     * and places a sentinel (-1) where the original value was 0.
     */
    private int[] extractParity(int[] raw) {
        int[] parity = new int[raw.length];
        int evenAtOdd = 0;   // #even numbers that ended up on odd positions
        int oddAtEven = 0;   // #odd  numbers that ended up on even positions

        for (int i = 0; i < raw.length; i++) {
            int p = raw[i];
            if (p == 0) {
                parity[i] = INVALID;
            } else if ((parity[i] = p % 2) == 0) {
                // even number – it should sit on an odd index to be optimal
                if (i % 2 == 1) evenAtOdd++;
            } else {
                // odd number – it should sit on an even index to be optimal
                if (i % 2 == 0) oddAtEven++;
            }
        }

        // Desired numbers of even / odd placements
        int targetEven = raw.length / 2 - evenAtOdd;
        int targetOdd  = (raw.length + 1) / 2 - oddAtEven;

        // Store the targets for later usage (they become part of the quota)
        quotaEven = targetEven;
        quotaOdd  = targetOdd;

        return parity;
    }

    /** Holds the two quota values that were computed while reading the input. */
    private int quotaEven, quotaOdd;

    /**
     * Analyses the parity array and extracts all segment lengths that are
     * relevant for the later greedy computation.
     *
     * Returns an object that bundles the different segment collections.
     */
    private SegmentCollection analyseSegments(int[] parity) {
        SegInfo zeroSeg   = new SegInfo(); // segments that end with parity 0
        SegInfo oneSeg    = new SegInfo(); // segments that end with parity 1
        SegInfo mixedSeg  = new SegInfo(); // segments between different parities
        SegInfo singleSeg = new SegInfo(); // isolated segments of length 1 or 2

        int prev = -1; // previous valid (non‑INVALID) parity index
        int answer = 0; // counts transitions between different parities

        for (int i = 0; i < parity.length; i++) {
            if (parity[i] == INVALID) {
                continue;
            }

            int gap = i - prev - 1;
            if (gap > 0) {
                if (parity[i] == 0) {
                    if (prev == -1) {
                        singleSeg.add(gap);
                    } else if (parity[prev] == 0) {
                        zeroSeg.add(gap);
                    } else {
                        mixedSeg.add(gap);
                    }
                } else { // parity[i] == 1
                    if (prev == -1) {
                        singleSeg.add(gap);
                    } else if (parity[prev] == 1) {
                        oneSeg.add(gap);
                    } else {
                        mixedSeg.add(gap);
                    }
                }
            }

            // count a transition whenever the current and previous parity differ
            if (prev != -1 && parity[prev] != parity[i]) {
                answer++;
            }

            prev = i;
        }

        // Tail segment (after the last examined element)
        int tailGap = parity.length - prev - 1;
        if (tailGap > 0) {
            if (parity[prev] == 0) {
                singleSeg.add(tailGap);
            } else {
                singleSeg.add(tailGap);
            }
        }

        return new SegmentCollection(
                answer,
                zeroSeg.toArray(),
                zeroSeg.cnt,
                oneSeg.toArray(),
                oneSeg.cnt,
                mixedSeg.toArray(),
                mixedSeg.cnt,
                singleSeg.toArray(),
                singleSeg.cnt
        );
    }

    /** Simple holder for the four groups of segment lengths. */
    private static class SegmentCollection {
        final int transitionCount;
        final int[] zeroSeg, oneSeg, mixedSeg, singleSeg;
        final int cntZero, cntOne, cntMixed, cntSingle;

        SegmentCollection(int transitionCount,
                          int[] zeroSeg, int cntZero,
                          int[] oneSeg, int cntOne,
                          int[] mixedSeg, int cntMixed,
                          int[] singleSeg, int cntSingle) {
            this.transitionCount = transitionCount;
            this.zeroSeg = zeroSeg;
            this.cntZero = cntZero;
            this.oneSeg = oneSeg;
            this.cntOne = cntOne;
            this.mixedSeg = mixedSeg;
            this.cntMixed = cntMixed;
            this.singleSeg = singleSeg;
            this.cntSingle = cntSingle;
        }
    }

    /** Counts how many times the parity changes while scanning the array. */
    private int countTransitions(int[] parity) {
        // This value is already captured inside `analyseSegments`; we simply
        // return the stored field via the collection object.
        // The method is kept for readability – the real value lives in the
        // collection returned by `analyseSegments`.
        // (Implementation detail: the transition count is stored in the
        // `SegmentCollection` object.)
        throw new UnsupportedOperationException("Should not be called directly");
    }

    /** Computes the two quota numbers that describe how many even/odd
     *  placements still need to be fixed. */
    private int[] computeQuota(int[] parity) {
        // The quota values are already stored in the fields `quotaEven` and
        // `quotaOdd` after parsing the input.
        return new int[]{quotaEven, quotaOdd};
    }

    /**
     * Main driver that decides which of the two directions (fixing even
     * positions or fixing odd positions) is pursued and computes the extra
     * operations needed to satisfy the remaining quota.
     */
    private int solveRemainingQuota(SegmentCollection seg, int[] quota) {
        int remainingEven = quota[0];
        int remainingOdd  = quota[1];

        // ---------------------------------------------------------------
        //  Try to satisfy the "even" quota first
        // ---------------------------------------------------------------
        if (remainingEven - (sum(seg.zeroSeg, seg.cntZero) + sum(seg.singleSeg, seg.cntSingle)) >= 0) {
            if (remainingEven - (sum(seg.zeroSeg, seg.cntZero) + sum(seg.singleSeg, seg.cntSingle) +
                                 sum(seg.mixedSeg, seg.cntMixed)) > 0) {
                return computeOptimalCost(
                        remainingEven,
                        seg.oneSeg, seg.cntOne,
                        seg.mixedSeg, seg.cntMixed);
            }
        }
        // ---------------------------------------------------------------
        //  Otherwise try to satisfy the "odd" quota
        // ---------------------------------------------------------------
        else if (remainingOdd - (sum(seg.oneSeg, seg.cntOne) + sum(seg.singleSeg, seg.cntSingle)) >= 0) {
            if (remainingOdd - (sum(seg.oneSeg, seg.cntOne) + sum(seg.singleSeg, seg.cntSingle) +
                                 sum(seg.mixedSeg, seg.cntMixed)) > 0) {
                return computeOptimalCost(
                        remainingOdd,
                        seg.zeroSeg, seg.cntZero,
                        seg.mixedSeg, seg.cntMixed);
            }
        }

        // No extra work needed
        return 0;
    }

    /** Utility: sum of the first `count` elements of an array. */
    private static int sum(int[] arr, int count) {
        int s = 0;
        for (int i = 0; i < count; i++) {
            s += arr[i];
        }
        return s;
    }

    /**
     * Computes the minimal number of additional moves required to consume
     * exactly `k` units using the supplied segment arrays.
     *
     * The implementation mirrors the original `solve_` function but is
     * extracted into its own method with clearer parameter names.
     */
    private static int computeOptimalCost(int k,
                                          int[] qu1, int cnt1,
                                          int[] qu11, int cnt11) {
        // Sort the two groups of segment lengths
        Arrays.sort(qu1, 0, cnt1);
        Arrays.sort(qu11, 0, cnt11);

        int result;

        // Direct single‑segment usage
        if (cnt1 >= 1 && k <= qu1[cnt1 - 1]) {
            result = 1;
        }
        // Pair of the two smallest segments can be used together
        else if (cnt1 == 2 && k <= qu1[0] + qu1[1]) {
            result = 2;
        }
        else {
            int supply = sum(qu11, cnt11);          // total “free” capacity
            result = k * 2;                         // worst case (2 per unit)

            if (k <= supply) {
                // Try to improve the bound by using the sorted mixed segments
                result = Math.min(result, solveRecursive(k, qu11, cnt11) * 2);
            }
            if (cnt1 >= 1 && k - qu1[0] <= supply) {
                result = Math.min(result, 1 + solveRecursive(k - qu1[0], qu11, cnt11) * 2);
            }
            if (cnt1 == 2 && k - qu1[1] <= supply) {
                result = Math.min(result, 1 + solveRecursive(k - qu1[1], qu11, cnt11) * 2);
            }
            if (cnt1 == 2 && k - qu1[0] - qu1[1] <= supply) {
                result = Math.min(result, 2 + solveRecursive(k - qu1[0] - qu1[1], qu11, cnt11) * 2);
            }
        }
        return result;
    }

    /**
     * Greedy “coin‑change” style solver used by {@link #computeOptimalCost}.
     * It repeatedly consumes the largest available segment until the quota
     * is exhausted or no segments remain.
     */
    private static int solveRecursive(int k, int[] qu, int cnt) {
        int ans = 0;
        while (k > 0 && cnt > 0) {
            ans++;
            if (k >= qu[cnt - 1]) {
                k -= qu[--cnt];
            } else {
                k = 0;
            }
        }
        return ans;
    }
}

import java.io.*;
import java.util.Scanner;

/**
 * Solution – reads a single test case, processes an integer array and prints the
 * required result.  The original program was functional but hard to follow,
 * contained many magic numbers and mixed concerns.  The refactor separates
 * responsibilities, uses expressive naming, avoids duplicated code and makes
 * the intent of each step explicit.
 */
public class Solution {

    /** Entry point – creates an instance that runs the whole algorithm. */
    public static void main(String[] args) {
        new Solution().run();
    }

    /** Orchestrates the complete program flow. */
    private void run() {
        try (Scanner scanner = new Scanner(System.in)) {
            final int NUMBER_OF_TESTS = 1;
            for (int testIndex = 0; testIndex < NUMBER_OF_TESTS; testIndex++) {
                processSingleTestCase(scanner);
            }
        }
    }

    /** Reads the whole test case, solves it and prints the answer. */
    private void processSingleTestCase(Scanner sc) {
        int n = sc.nextInt();                     // size of the array
        int[] values = readArray(sc, n);          // the raw numbers

        // -----------------------------------------------------------------
        // 1️⃣  Count positive odd / even numbers and derive missing counts.
        // -----------------------------------------------------------------
        int positiveOddCount = countPositiveOdd(values);
        int positiveEvenCount = countPositiveEven(values);

        int totalEvenSlots = n / 2;                // theoretical number of evens
        int totalOddSlots = n - totalEvenSlots;    // theoretical number of odds

        int missingOdd  = totalOddSlots - positiveOddCount;   // how many odds we still need
        int missingEven = totalEvenSlots - positiveEvenCount; // how many evens we still need

        // -----------------------------------------------------------------
        // 2️⃣  Build auxiliary coefficient arrays that the original algorithm
        //     used for “required” quantities per index.
        // -----------------------------------------------------------------
        int[] requiredOdd  = new int[n];
        int[] requiredEven = new int[n];
        buildRequirementArrays(values, requiredOdd, requiredEven);

        // -----------------------------------------------------------------
        // 3️⃣  Apply the requirements – subtract what can be satisfied and
        //     accumulate the answer (res) for the unsatisfied part.
        // -----------------------------------------------------------------
        int answer = 0;
        applyRequirements(missingOdd, missingEven, requiredOdd, requiredEven, answer);

        // -----------------------------------------------------------------
        // 4️⃣  Handle leading and trailing zeros – they need special checks.
        // -----------------------------------------------------------------
        answer += handleBoundaryZeros(values, missingOdd, missingEven);

        // -----------------------------------------------------------------
        // 5️⃣  Output the result for this test case.
        // -----------------------------------------------------------------
        System.out.println(answer);
    }

    /** Reads exactly {@code size} integers from the scanner. */
    private static int[] readArray(Scanner scanner, int size) {
        int[] arr = new int[size];
        for (int i = 0; i < size; i++) {
            arr[i] = scanner.nextInt();
        }
        return arr;
    }

    /** Counts positive odd numbers in the supplied array. */
    private static int countPositiveOdd(int[] array) {
        int cnt = 0;
        for (int v : array) {
            if (v > 0 && (v & 1) == 1) {
                cnt++;
            }
        }
        return cnt;
    }

    /** Counts positive even numbers in the supplied array. */
    private static int countPositiveEven(int[] array) {
        int cnt = 0;
        for (int v : array) {
            if (v > 0 && (v & 1) == 0) {
                cnt++;
            }
        }
        return cnt;
    }

    /**
     * Replicates the original, rather opaque logic that fills {@code requiredOdd}
     * and {@code requiredEven} based on pairs of non‑zero neighbours.
     * The method is kept unchanged in behaviour but written with clearer
     * variable names and comments.
     */
    private static void buildRequirementArrays(
            int[] values,
            int[] requiredOdd,
            int[] requiredEven) {

        // Initialise the auxiliary arrays.
        Arrays.fill(requiredOdd, 1);
        Arrays.fill(requiredEven, 1);

        int n = values.length;
        for (int i = 0; i < n - 1; i++) {
            if (values[i] == 0) {
                continue;                     // skip zeros – they are placeholders
            }

            int j = i + 1;
            while (j < n && values[j] == 0) {
                j++;
            }
            if (j == n) {
                break;                        // reached the end without a partner
            }

            // Both neighbours are non‑zero – update the coefficient arrays.
            if ((values[i] & 1) == 0) {        // i‑th value is even
                if ((values[j] & 1) == 0) {    // neighbour is also even
                    requiredEven[j - i - 1]++; // distance‑based coefficient
                } else {
                    // odd neighbour – just count this pair
                    // (the original code only used this branch to increment res)
                }
            } else {                           // i‑th value is odd
                if ((values[j] & 1) == 1) {    // neighbour is odd
                    requiredOdd[j - i - 1]++;  // distance‑based coefficient
                } else {
                    // even neighbour – analogous to the even‑odd case above
                }
            }
        }
    }

    /**
     * Implements the rather involved requirement‑subtraction logic from the
     * original program.  It updates the mutable {@code answer} variable by
     * reference.
     */
    private static void applyRequirements(
            int totalMissingOdd,
            int totalMissingEven,
            int[] requiredOdd,
            int[] requiredEven,
            int answerRef) {

        // Process odd‑related requirements.
        for (int i = 1; i < requiredOdd.length; i++) {
            int required = i * requiredOdd[i];

            if (required <= totalMissingOdd) {
                totalMissingOdd -= required;
            } else {
                int groups = totalMissingOdd / i;
                requiredOdd[i] -= groups;
                answerRef += groups * 2;               // two operations per missing odd
                totalMissingOdd -= groups * i;
            }

            // Even‑related part – mirroring the odd‑branch.
            required = i * requiredEven[i];
            if (required <= totalMissingEven) {
                totalMissingEven -= required;
            } else {
                int groups = totalMissingEven / i;
                requiredEven[i] -= groups;
                answerRef += groups * 2;
                totalMissingEven -= groups * i;
            }
        }
    }

    /**
     * Handles leading and trailing zeroes.  The original program performed a
     * couple of boundary checks; this method isolates that logic and makes the
     * intent explicit.
     */
    private static int handleBoundaryZeros(
            int[] values,
            int missingOdd,
            int missingEven) {

        int answer = 0;
        int n = values.length;

        // -----------------------------------------------------------------
        // Leading element (first non‑zero)
        // -----------------------------------------------------------------
        int firstNonZeroIdx = findFirstNonZero(values);
        if (firstNonZeroIdx < n) {
            int value = values[firstNonZeroIdx];
            int distanceToStart = firstNonZeroIdx; // number of leading zeros

            if ((value & 1) == 0) { // even
                if (distanceToStart <= missingEven) {
                    missingEven -= distanceToStart;
                } else {
                    answer++; // could not satisfy – need an extra operation
                }
            } else { // odd
                if (distanceToStart <= missingOdd) {
                    missingOdd -= distanceToStart;
                } else {
                    answer++;
                }
            }
        }

        // -----------------------------------------------------------------
        // Trailing element (last non‑zero)
        // -----------------------------------------------------------------
        int lastNonZeroIdx = findLastNonZero(values);
        if (lastNonZeroIdx >= 0) {
            int value = values[lastNonZeroIdx];
            int distanceToEnd = n - 1 - lastNonZeroIdx; // trailing zeros count

            if ((value & 1) == 0) { // even
                if (distanceToEnd <= missingEven) {
                    missingEven -= distanceToEnd;
                } else {
                    answer++;
                }
            } else { // odd
                if (distanceToEnd <= missingOdd) {
                    missingOdd -= distanceToEnd;
                } else {
                    answer++;
                }
            }
        }

        return answer;
    }

    /** Returns the index of the first element that is not zero, or {@code length}. */
    private static int findFirstNonZero(int[] array) {
        for (int i = 0; i < array.length; i++) {
            if (array[i] != 0) {
                return i;
            }
        }
        return array.length;
    }

    /** Returns the index of the last element that is not zero, or {@code -1}. */
    private static int findLastNonZero(int[] array) {
        for (int i = array.length - 1; i >= 0; i--) {
            if (array[i] != 0) {
                return i;
            }
        }
        return -1;
    }
}

import java.util.Scanner;

/**
 * Refactored version of the original “Garland” program.
 *
 * The program reads an integer {@code n} followed by {@code n} numbers.
 * It treats the input as a garland with placeholders (zeros) that must be filled
 * with either an odd (Ji) or an even (Ou) number, respecting the limits derived
 * from {@code n}. After filling the placeholders it counts how many adjacent
 * pairs have different parity.
 *
 * The refactor focuses on readability, clear intent‑revealing names,
 * extraction of small helper methods and elimination of duplicated logic.
 */
public final class Garland {

    /* --------------------------------------------------------------------- */
    /*  Configuration & state                                                 */
    /* --------------------------------------------------------------------- */

    /** maximum number of odd (Ji) values we are allowed to insert */
    private static int maxJi;

    /** maximum number of even (Ou) values we are allowed to insert */
    private static int maxOu;

    /** input array */
    private static int[] numbers;

    /* --------------------------------------------------------------------- */
    /*  Helper methods                                                       */
    /* --------------------------------------------------------------------- */

    /** Returns {@code true} if two numbers share the same parity. */
    private static boolean sameParity(int a, int b) {
        return (a % 2 == 0 && b % 2 == 0) || (a % 2 != 0 && b % 2 != 0);
    }

    /** Returns {@code true} if all positions between {@code from} (inclusive)
     *  and {@code to} (inclusive) contain only zeros. */
    private static boolean segmentIsAllZeros(int from, int to) {
        for (int i = from; i <= to; i++) {
            if (numbers[i] != 0) {
                return false;
            }
        }
        return true;
    }

    /** Fills {@code count} consecutive positions starting at {@code start+1}
     *  with the given {@code value} (1‑odd or 2‑even) and updates the
     *  corresponding counter. */
    private static void fillSegmentWith(int start, int count, int value, int[] counter) {
        int offset = start + 1;
        for (int i = 0; i < count; i++) {
            numbers[offset + i] = value;
        }
        counter[0] -= count;
    }

    /** Decrements the supplied counter for each non‑zero element of a given
     *  parity that is encountered while scanning the input. */
    private static void adjustCountersWhileReading(int value) {
        if (value % 2 == 0) {
            maxOu--;
        } else {
            maxJi--;
        }
    }

    /** Returns {@code true} if the segment of length {@code distance}
     *  beginning at {@code index+1} contains only zeros. */
    private static boolean zerosBetween(int index, int distance) {
        return segmentIsAllZeros(index + 1, index + distance);
    }

    /** Places the appropriate value (odd or even) after the last non‑zero
     *  element, respecting the remaining limits. */
    private static void fillTrailingZeros(int lastIdx) {
        int remaining = numbers.length - lastIdx - 1;
        if (remaining <= 0) {
            return;
        }
        if (numbers[lastIdx] % 2 == 0 && maxOu >= remaining) {
            fillSegmentWith(lastIdx, remaining, 2, new int[]{maxOu});
        } else if (numbers[lastIdx] % 2 != 0 && maxJi >= remaining) {
            fillSegmentWith(lastIdx, remaining, 1, new int[]{maxJi});
        }
    }

    /** Places a value before the first non‑zero element, respecting limits. */
    private static void fillLeadingZeros(int firstIdx) {
        // This mirrors the original logic that walks backwards from firstIdx.
        for (int i = firstIdx - 1; i >= 0; i--) {
            insertAt(i, numbers[i + 1]);   // reuse the generic insertion logic
        }
    }

    /** Inserts a number at position {@code idx} based on parity rules and
     *  remaining counters. */
    private static void insertAt(int idx, int referenceValue) {
        // Prefer filling with the same parity as the reference value,
        // but only if enough capacity remains.
        if (referenceValue % 2 == 0 && maxOu > 0) {
            numbers[idx] = 2;
            maxOu--;
        } else if (referenceValue % 2 != 0 && maxJi > 0) {
            numbers[idx] = 1;
            maxJi--;
        } else {
            // fallback – take whichever counter still has capacity
            if (maxOu > 0) {
                numbers[idx] = 2;
                maxOu--;
            } else {
                numbers[idx] = 1;
                maxJi--;
            }
        }
    }

    /** Computes the answer – the number of adjacent pairs with different parity. */
    private static int countParityChanges() {
        int changes = 0;
        for (int i = 0; i < numbers.length - 1; i++) {
            if (!sameParity(numbers[i], numbers[i + 1])) {
                changes++;
            }
        }
        return changes;
    }

    /* --------------------------------------------------------------------- */
    /*  Main program                                                          */
    /* --------------------------------------------------------------------- */

    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            int n = scanner.nextInt();
            numbers = new int[n];

            // ---------- 1. read input ----------
            for (int i = 0; i < n; i++) {
                numbers[i] = scanner.nextInt();
                if (numbers[i] != 0) {
                    adjustCountersWhileReading(numbers[i]);
                }
            }

            // ---------- 2. derive the limits ----------
            // maxJi = ceil(n/2)  – maximum odd numbers we may place
            // maxOu = floor(n/2) – maximum even numbers we may place
            maxJi = (n % 2 == 0) ? n / 2 + 1 : n / 2 + 1;   // same as original
            maxOu = n / 2;

            // ---------- 3. first pass – locate first / last non‑zero ----------
            int firstIdx = -1;
            int lastIdx  = -1;
            for (int i = 0; i < n; i++) {
                if (numbers[i] != 0) {
                    lastIdx = i;
                    if (firstIdx == -1) {
                        firstIdx = i;
                    }
                }
            }

            // ---------- 4. core processing ----------
            int answer = 0;

            if (firstIdx == -1) {                     // all entries are zero
                answer = (n == 1) ? 0 : 1;
            } else {
                // ---- 4.1  handle gaps that are completely surrounded by non‑zeros ----
                for (int gapStart = 1; gapStart < n; gapStart++) {
                    if (numbers[gapStart] != 0) {
                        continue; // only look at positions that were originally zero
                    }
                    int distance = findNextNonZeroDistance(gapStart);
                    if (distance == 0) {
                        continue;
                    }
                    for (int j = 0; j <= n - distance - 2; j++) {
                        if (areSurroundedBySameParity(j, j + distance + 1)) {
                            if (segmentIsAllZeros(j + 1, j + distance)) {
                                // we have a completely empty gap
                                handleFullGap(j, distance);
                            }
                        }
                    }
                }

                // ---- 4.2  fill trailing zeros (after the last non‑zero) ----
                fillTrailingZeros(lastIdx);

                // ---- 4.3  insert values before the first non‑zero ----
                fillLeadingZeros(firstIdx);

                // ---- 4.4  fill any remaining isolated zeros ----
                for (int i = firstIdx + 1; i < n; i++) {
                    if (numbers[i] != 0) {
                        continue;
                    }
                    // keep going only if the neighbours differ in parity
                    if ((i != n - 1) && numbers[i - 1] != 0 && numbers[i + 1] != 0
                            && sameParity(numbers[i - 1], numbers[i + 1])) {
                        continue;
                    }
                    insertAt(i, numbers[i - 1]);   // reuse the generic inserter
                }

                // ---- 4.5  final fill of any still‑zero positions with odd numbers ----
                for (int i = firstIdx + 1; i < n; i++) {
                    if (numbers[i] == 0) {
                        numbers[i] = 1;   // default fill (mirrors original code)
                    }
                }

                // ---- 4.6  compute the answer (parity changes) ----
                answer = countParityChanges();
            }

            // ---------- 5. output ----------
            System.out.println(answer);
        }
    }

    /** Finds the distance to the next non‑zero element to the right of {@code start}. */
    private static int findNextNonZeroDistance(int start) {
        int distance = 0;
        int current = start;
        while (current < numbers.length && numbers[current] == 0) {
            distance++;
            current++;
        }
        return distance;
    }

    /** Returns {@code true} if the two numbers at positions {@code i} and {@code j}
     *  have the same parity. */
    private static boolean areSurroundedBySameParity(int i, int j) {
        return sameParity(numbers[i], numbers[j]);
    }

    /** Handles a completely empty gap that is surrounded by numbers of the same
     *  parity. It tries to fill the gap with the appropriate parity value,
     *  respecting the remaining capacity. */
    private static void handleFullGap(int start, int distance) {
        // The original loop iterates over possible “j” positions; we only need
        // to consider the first such opportunity because the gap is empty.
        if (distance > 0 && zerosBetween(start, distance)) {
            int valueToInsert = (numbers[start] % 2 == 0) ? 2 : 1;
            int remainingCapacity = (valueToInsert == 2) ? maxOu : maxJi;

            if (remainingCapacity >= distance) {
                fillSegmentWith(start, distance, valueToInsert,
                                new int[]{remainingCapacity});
            }
        }
    }
}

import java.io.*;
import java.util.*;

public class Main {

    /** Modulo constant – not used in the algorithm but kept for completeness */
    private static final long MOD = 1_000_000_007L;

    private PrintWriter out;
    private BufferedReader br;
    private StringTokenizer st;

    /** Entry point */
    public static void main(String[] args) throws Exception {
        new Main().run();
    }

    /** Sets up input / output streams */
    private void run() throws Exception {
        initStreams();
        solve();
        out.flush();
    }

    /** Initializes the scanner‑like input and print‑writer output */
    private void initStreams() {
        br = new BufferedReader(new InputStreamReader(System.in));
        out = new PrintWriter(System.out);
    }

    /** Core solving routine */
    private void solve() {
        int n = readInt();                           // size of the permutation
        int[] p = readPermutation(n);                // 1‑based permutation, 0 = missing
        int[] missingParityCounts = countMissingParities(p);
        int answer = solveDynamicProgramming(n, p, missingParityCounts);
        out.println(answer);
    }

    /** Reads the whole permutation into a 1‑based array */
    private int[] readPermutation(int n) {
        int[] p = new int[n + 1];
        for (int i = 1; i <= n; i++) {
            p[i] = readInt();
        }
        return p;
    }

    /**
     * Counts how many missing numbers are even and how many are odd.
     * The missing numbers are exactly those i ∈ [1, n] that never appear in {@code p}.
     */
    private int[] countMissingParities(int[] p) {
        int n = p.length - 1;
        int[] present = new int[n + 1];
        for (int i = 1; i <= n; i++) {
            present[p[i]] = 1;
        }
        int[] missing = new int[2];
        for (int i = 1; i <= n; i++) {
            if (present[i] == 0) {
                missing[i % 2]++;                     // parity of the missing number i
            }
        }
        return missing;
    }

    /**
     * Dynamic programming solution that minimises the number of
     * adjacent elements with different parity (i.e. odd transitions).
     */
    private int solveDynamicProgramming(int n, int[] p, int[] missing) {
        // dp[pos][usedEven][usedOdd][par] – minimal odd transitions up to position pos
        //   where {@code usedEven}/{@code usedOdd} numbers of each missing parity have been placed,
        //   and {@code par} is the parity of the element placed at position pos.
        int[][][][] dp = new int[n + 1][n + 1][n + 1][2];
        fillWithInfinity(dp);

        // ----- initialise the first position -----
        if (p[1] == 0) {
            // we have to place a missing number here
            if (missing[0] > 0) {
                dp[1][missing[0] - 1][missing[1]][0] = 0;   // place an even missing number
            }
            if (missing[1] > 0) {
                dp[1][missing[0]][missing[1] - 1][1] = 0;   // place an odd missing number
            }
        } else {
            // the first element is fixed
            int parity = p[1] % 2;
            dp[1][missing[0]][missing[1]][parity] = 0;
        }

        // ----- fill the DP table -----
        for (int pos = 2; pos <= n; pos++) {
            for (int usedEven = 0; usedEven <= missing[0]; usedEven++) {
                for (int usedOdd = 0; usedOdd <= missing[1]; usedOdd++) {
                    transitionForFixedNumber(pos, p, missing, usedEven, usedOdd, dp);
                    transitionForMissingNumber(pos, p, missing, usedEven, usedOdd, dp);
                }
            }
        }

        // The answer is the best value when all missing numbers have been used
        return Math.min(dp[n][0][0][0], dp[n][0][0][1]);
    }

    /** Handles the case where the current position already contains a fixed number */
    private void transitionForFixedNumber(int pos, int[] p, int[] missing,
                                            int usedEven, int usedOdd, int[][][][] dp) {
        if (p[pos] != 0) {
            int curParity = p[pos] % 2;

            // No extra cost when the parity stays the same as the previous position
            if (dp[pos - 1][usedEven][usedOdd][curParity] != Integer.MAX_VALUE) {
                dp[pos][usedEven][usedOdd][curParity] = Math.min(
                        dp[pos][usedEven][usedOdd][curParity],
                        dp[pos - 1][usedEven][usedOdd][curParity]);
            }

            // Cost of 1 when we switch parity relative to the previous position
            if (dp[pos - 1][usedEven][usedOdd][1 - curParity] != Integer.MAX_VALUE) {
                dp[pos][usedEven][usedOdd][curParity] = Math.min(
                        dp[pos][usedEven][usedOdd][curParity],
                        1 + dp[pos - 1][usedEven][usedOdd][1 - curParity]);
            }
        }
    }

    /** Handles the case where the current position is missing (value 0) */
    private void transitionForMissingNumber(int pos, int[] p, int[] missing,
                                            int usedEven, int usedOdd, int[][][][] dp) {
        if (p[pos] == 0) {
            // -------------------------------------------------
            // Place an even missing number (if any are left)
            // -------------------------------------------------
            if (usedEven < missing[0]) {
                int nextEven = usedEven + 1;
                int placedParity = 0;

                // staying in the same parity → no extra cost
                if (dp[pos - 1][nextEven][usedOdd][0] != Integer.MAX_VALUE) {
                    dp[pos][usedEven][usedOdd][0] = Math.min(
                            dp[pos][usedEven][usedOdd][0],
                            dp[pos - 1][nextEven][usedOdd][0]);
                }

                // switching parity → add one odd transition
                if (dp[pos - 1][nextEven][usedOdd][1] != Integer.MAX_VALUE) {
                    dp[pos][usedEven][usedOdd][0] = Math.min(
                            dp[pos][usedEven][usedOdd][0],
                            1 + dp[pos - 1][nextEven][usedOdd][1]);
                }
            }

            // -------------------------------------------------
            // Place an odd missing number (if any are left)
            // -------------------------------------------------
            if (usedOdd < missing[1]) {
                int nextOdd = usedOdd + 1;
                int placedParity = 1;

                // staying in the same parity → no extra cost
                if (dp[pos - 1][usedEven][nextOdd][1] != Integer.MAX_VALUE) {
                    dp[pos][usedEven][usedOdd][1] = Math.min(
                            dp[pos][usedEven][usedOdd][1],
                            dp[pos - 1][usedEven][nextOdd][1]);
                }

                // switching parity → add one odd transition
                if (dp[pos - 1][usedEven][nextOdd][0] != Integer.MAX_VALUE) {
                    dp[pos][usedEven][usedOdd][1] = Math.min(
                            dp[pos][usedEven][usedOdd][1],
                            1 + dp[pos - 1][usedEven][nextOdd][0]);
                }
            }
        }
    }

    /** Fills the whole DP array with {@link Integer#MAX_VALUE} */
    private void fillWithInfinity(int[][][][] arr) {
        int limit = arr.length;
        for (int i = 0; i < limit; i++) {
            for (int j = 0; j < limit; j++) {
                for (int k = 0; k < limit; k++) {
                    Arrays.fill(arr[i][j][k], Integer.MAX_VALUE);
                }
            }
        }
    }

    /** Reads the next integer token from the input stream */
    private int readInt() {
        return Integer.parseInt(nextToken());
    }

    /** Returns the next token, reading a new line if necessary */
    private String nextToken() {
        while (st == null || !st.hasMoreElements()) {
            try {
                st = new StringTokenizer(br.readLine());
            } catch (IOException e) {
                throw new UncheckedIOException(e);
            }
        }
        return st.nextToken();
    }
}

import java.io.*;
import java.util.*;

public class Main {

    /*---------------------------  Constants & Helpers  ---------------------------*/
    private static final int INF = 1_000_000_000;
    private static final int NO_PARITY = 2;               // sentinel for “no previous element”

    /** Simple wrapper around BufferedReader / StringTokenizer */
    private static class FastScanner {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        FastScanner(InputStream stream) {
            this.reader = new BufferedReader(new InputStreamReader(stream), 32768);
        }

        String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new UncheckedIOException(e);
                }
            }
            return tokenizer.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }
    }

    /** Entry point – delegates the actual solving to a dedicated solver class */
    public static void main(String[] args) {
        FastScanner in = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(System.out);
        new Solver().solve(in, out);
        out.close();
    }

    /*---------------------------  Solver Logic  ---------------------------*/
    private static class Solver {

        /** Solves a single test case */
        void solve(FastScanner in, PrintWriter out) {
            int n = in.nextInt();
            int[] values = new int[n + 1];               // 1‑based for easier DP indexing
            for (int i = 1; i <= n; i++) {
                values[i] = in.nextInt();
            }

            // -----------------------------------------------------------------
            // 1) Count how many even / odd numbers are already placed
            // -----------------------------------------------------------------
            int[] placedParityCount = countPlacedParity(values);
            int needEven = n / 2 - placedParityCount[0];
            int needOdd  = (n + 1) / 2 - placedParityCount[1];

            // -----------------------------------------------------------------
            // 2) DP initialisation
            // -----------------------------------------------------------------
            // dp[pos][evenUsed][oddUsed][lastParity] = minimal complexity
            // lastParity: 0 = even, 1 = odd, 2 = NO_PARITY (start of the sequence)
            int[][][][] dp = new int[n + 1][needEven + 1][needOdd + 1][3];
            fillWithInfinity(dp);

            // start state – nothing placed yet, lastParity = NO_PARITY, cost = 0
            dp[0][0][0][NO_PARITY] = 0;

            // -----------------------------------------------------------------
            // 3) Fill DP table
            // -----------------------------------------------------------------
            for (int pos = 1; pos <= n; pos++) {
                for (int usedEven = 0; usedEven <= needEven; usedEven++) {
                    for (int usedOdd = 0; usedOdd <= needOdd; usedOdd++) {
                        for (int prevParity = 0; prevParity < 3; prevParity++) {
                            if (dp[pos - 1][usedEven][usedOdd][prevParity] == INF) {
                                continue;
                            }

                            int currentValue = values[pos];

                            // ---------------------------------------------------------
                            // Fixed (already given) number at position 'pos'
                            // ---------------------------------------------------------
                            if (currentValue != 0) {
                                int curParity = currentValue % 2;
                                int additionalCost = (prevParity != NO_PARITY && prevParity != curParity) ? 1 : 0;
                                dp[pos][usedEven][usedOdd][curParity] =
                                        min(dp[pos][usedEven][usedOdd][curParity],
                                            dp[pos - 1][usedEven][usedOdd][prevParity] + additionalCost);
                            }
                            // ---------------------------------------------------------
                            // Empty slot – we may place an even or an odd number
                            // ---------------------------------------------------------
                            else {
                                // ----- place an even number -------------------------------------------------
                                if (usedEven < needEven) {
                                    int curParity = 0;
                                    int additionalCost = (prevParity != NO_PARITY && prevParity != curParity) ? 1 : 0;
                                    dp[pos][usedEven + 1][usedOdd][curParity] =
                                            min(dp[pos][usedEven + 1][usedOdd][curParity],
                                                dp[pos - 1][usedEven][usedOdd][prevParity] + additionalCost);
                                }

                                // ----- place an odd number --------------------------------------------------
                                if (usedOdd < needOdd) {
                                    int curParity = 1;
                                    int additionalCost = (prevParity != NO_PARITY && prevParity != curParity) ? 1 : 0;
                                    dp[pos][usedEven][usedOdd + 1][curParity] =
                                            min(dp[pos][usedEven][usedOdd + 1][curParity],
                                                dp[pos - 1][usedEven][usedOdd][prevParity] + additionalCost);
                                }
                            }
                        }
                    }
                }
            }

            // -----------------------------------------------------------------
            // 4) Extract answer – minimal complexity among the three possible last parities
            // -----------------------------------------------------------------
            int answer = min(
                    dp[n][needEven][needOdd][0],
                    min(dp[n][needEven][needOdd][1], dp[n][needEven][needOdd][2])
            );
            out.println(answer);
        }

        /** Counts how many even and odd numbers are already present in the input array */
        private static int[] countPlacedParity(int[] values) {
            int even = 0, odd = 0;
            // we consider only positions 1 .. values.length-1 because index 0 is unused
            for (int i = 1; i < values.length; i++) {
                if (values[i] != 0) {
                    if (values[i] % 2 == 0) {
                        even++;
                    } else {
                        odd++;
                    }
                }
            }
            return new int[]{even, odd};
        }

        /** Helper – returns the minimum of two integers */
        private static int min(int a, int b) {
            return Math.min(a, b);
        }

        /** Helper – replaces every element of a 4‑dimensional int array with INF */
        private static void fillWithInfinity(int[][][][] array) {
            Arrays.fill(array, 0);
            for (int[][][] slice1 : array) {
                for (int[][] slice2 : slice1) {
                    for (int[] slice3 : slice2) {
                        Arrays.fill(slice3, INF);
                    }
                }
            }
        }
    }
}

package solution;

import java.io.*;
import java.util.Arrays;

/**
 * Refactored version of the original program.
 * <p>
 * The program reads an integer {@code n} followed by {@code n} integers,
 * classifies every non‑zero element as even (0) or odd (1) and, if the element
 * is zero, treats it as a “wildcard” (-1).  Using a dynamic‑programming
 * approach it computes the minimum number of parity changes required to make
 * all elements end up with the same parity while respecting the available
 * slots for each parity class.
 *
 * The implementation is deliberately split into small, well‑named helper
 * methods and types to improve readability and maintainability.
 */
public class Main {

    /** entry point */
    public static void main(String[] args) {
        Solver solver = new Solver();
        // use try‑with‑resources to guarantee stream closure
        try (InputStream in = System.in;
             OutputStream out = System.out) {
            solver.solve(in, out);
        }
    }

    /** core logic – separates I/O from the algorithm */
    static class Solver {

        /** constant representing “infinite” distance */
        private static final int INF = 1_000_000_000;

        /** public entry point used by {@code main} */
        void solve(InputStream input, OutputStream output) {
            try (InputReader reader = new InputReader(input);
                 OutputWriter writer = new OutputWriter(output)) {

                int n = reader.nextInt();
                int[] values = readAndTransform(reader, n);
                int answer = computeMinimumOperations(values);
                writer.printLine(answer);
            }
        }

        /** converts raw input values into the compact representation used by the DP */
        private static int[] readAndTransform(InputReader r, int n) {
            int[] arr = new int[n];
            for (int i = 0; i < n; i++) {
                int v = r.nextInt();
                arr[i] = (v == 0) ? -1 : (v % 2); // -1 denotes a wildcard
            }
            return arr;
        }

        /**
         * Dynamic‑programming implementation that returns the minimal number of
         * parity adjustments needed.
         */
        private int computeMinimumOperations(int[] a) {
            int halfLen = (a.length + 1) / 2; // capacity for parity 0
            int otherLen  = a.length - halfLen; // capacity for parity 1

            int[][][] dp   = createDpArray(halfLen, otherLen);
            int[][][] next = createDpArray(halfLen, otherLen);
            int cur = 0; // not really used – kept for possible future extensions

            // initialise: both parity classes start with their full capacity
            dp[0][halfLen][otherLen] = 0;
            dp[1][halfLen][otherLen] = 0;

            for (int value : a) {
                reset(next);
                for (int curParity = 0; curParity < 2; curParity++) {
                    for (int usedEven = 0; usedEven <= halfLen; usedEven++) {
                        for (int usedOdd = 0; usedOdd <= otherLen; usedOdd++) {
                            if (dp[curParity][usedEven][usedOdd] == INF) {
                                continue;
                            }
                            // try placing 'value' into the even parity class
                            assign(next, curParity, usedEven, usedOdd, value, 0, dp[curParity][usedEven][usedOdd]);
                            // try placing 'value' into the odd parity class
                            assign(next, curParity, usedEven, usedOdd, value, 1, dp[curParity][usedEven][usedOdd]);
                        }
                    }
                }
                // swap the role of dp and next for the next iteration
                int[][][] tmp = dp;
                dp = next;
                next = tmp;
            }

            // answer is the best cost when all slots are used exactly
            return Math.min(dp[0][0][0], dp[1][0][0]);
        }

        /** core DP transition – decides whether a placement is legal and updates cost */
        private void assign(int[][][] target,
                            int currentParity,
                            int usedEven,
                            int usedOdd,
                            int value,
                            int nextParity,
                            int curCost) {

            // a wildcard (-1) can be placed anywhere; a concrete value must match the chosen parity
            if (value != -1 && value != nextParity) {
                return;
            }

            int cost = curCost;
            // a parity switch incurs an extra operation
            if (nextParity != currentParity) {
                cost++;
            }

            // consume one slot from the target parity
            int newEven = (nextParity == 0) ? usedEven - 1 : usedEven;
            int newOdd  = (nextParity == 1) ? usedOdd  - 1 : usedOdd;

            // illegal state if we run out of capacity
            if (newEven < 0 || newOdd < 0) {
                return;
            }

            // keep the minimal cost for the new state
            if (cost < target[nextParity][newEven][newOdd]) {
                target[nextParity][newEven][newOdd] = cost;
            }
        }

        /** creates a 3‑dimensional DP array with dimensions [2][maxEven+1][maxOdd+1] */
        private static int[][][] createDpArray(int maxEven, int maxOdd) {
            return new int[2][maxEven + 1][maxOdd + 1];
        }

        /** resets every cell of the supplied DP array to INF */
        private static void reset(int[][][] arr) {
            for (int[][] row : arr) {
                for (int[] column : row) {
                    Arrays.fill(column, INF);
                }
            }
        }
    }

    /** ---------------------------------------------------------------
     *  Utility I/O classes – kept minimal but functional.
     *  --------------------------------------------------------------- */
    static class InputReader {
        private final InputStream stream;
        private final byte[] buffer = new byte[10_000];
        private int cur = 0, count = 0;

        InputReader(InputStream stream) {
            this.stream = stream;
        }

        private int read() {
            if (count == -1) throw new InputMismatchException();
            try {
                if (cur >= count) {
                    cur = 0;
                    count = stream.read(buffer);
                }
            } catch (IOException e) {
                throw new InputMismatchException();
            }
            return (count <= 0) ? -1 : buffer[cur++];
        }

        private boolean isSpace(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        /** skips leading whitespace characters */
        private int skipSpaces() {
            int c;
            do {
                c = read();
            } while (isSpace(c));
            return c;
        }

        /** reads the next signed integer from the input stream */
        int nextInt() {
            int sign = 1;
            int c = skipSpaces();
            if (c == '-') {
                sign = -1;
                c = read();
            }
            int result = 0;
            do {
                if (c < '0' || c > '9') throw new InputMismatchException();
                result = result * 10 + (c - '0');
                c = read();
            } while (!isSpace(c));
            return result * sign;
        }
    }

    static class OutputWriter {
        private final PrintWriter writer;

        OutputWriter(OutputStream out) {
            writer = new PrintWriter(new BufferedWriter(
                    new OutputStreamWriter(out)));
        }

        /** prints the given objects separated by a single space */
        private void print(Object... objs) {
            for (int i = 0; i < objs.length; i++) {
                if (i != 0) writer.print(' ');
                writer.print(objs[i]);
            }
        }

        /** prints a line break after the supplied objects */
        void printLine(Object... objs) {
            print(objs);
            writer.println();
        }

        void close() {
            writer.close();
        }
    }
}

import java.io.IOException;
import java.io.PrintWriter;
import java.util.HashMap;
import java.util.Objects;
import java.util.Scanner;

/**
 * Solution for the problem that places missing even/odd numbers
 * into an array so that the number of parity changes is minimal.
 *
 * The algorithm uses a depth‑first search with memoisation.
 * All mutable state is encapsulated in a small {@link State} value object,
 * which makes the recursion easy to reason about and test.
 */
public class Main {

    /** A tiny immutable value object that represents a recursive DP state. */
    private static final class State {
        final int position;      // current index in the array
        final int evenLeft;      // how many even numbers we can still place
        final int oddLeft;       // how many odd numbers we can still place
        final boolean lastEven;  // parity of the previously placed element

        State(int position, int evenLeft, int oddLeft, boolean lastEven) {
            this.position = position;
            this.evenLeft = evenLeft;
            this.oddLeft = oddLeft;
            this.lastEven = lastEven;
        }

        @Override
        public boolean equals(Object o) {
            if (this == o) return true;
            if (!(o instanceof State)) return false;
            State state = (State) o;
            return position == state.position &&
                    evenLeft == state.evenLeft &&
                    oddLeft == state.oddLeft &&
                    lastEven == state.lastEven;
        }

        @Override
        public int hashCode() {
            return Objects.hash(position, evenLeft, oddLeft, lastEven);
        }
    }

    /** A large value that represents “infinite cost”. */
    private static final long INF = Long.MAX_VALUE;

    /** Entry point – delegates all work to {@link #solve(Scanner, PrintWriter)}. */
    public static void main(String[] args) throws IOException {
        try (Scanner scanner = new Scanner(System.in);
             PrintWriter writer = new PrintWriter(System.out)) {

            solve(scanner, writer);
        }
    }

    /**
     * Reads the input, prepares the required data and starts the DP computation.
     */
    private static void solve(Scanner sc, PrintWriter out) {
        int n = sc.nextInt();
        int[] numbers = new int[n];

        // total slots of each parity when positions are 1‑based
        int evenSlots = (n + 1) / 2;   // odd indices → even numbers
        int oddSlots  = n / 2;         // even indices → odd numbers

        // read the array and adjust the remaining slots count
        for (int i = 0; i < n; i++) {
            numbers[i] = sc.nextInt();
            if (numbers[i] != 0) {
                if ((numbers[i] & 1) == 0) {   // even
                    evenSlots--;
                } else {                       // odd
                    oddSlots--;
                }
            }
        }

        // memoisation map: state → minimal additional cost from that state
        HashMap<State, Long> memo = new HashMap<>();

        // two possibilities for the parity of the first (virtual) element:
        // false → “previous was odd”, true → “previous was even”
        long answer = Math.min(
                dfs(numbers, 0, evenSlots, oddSlots, true,  memo),
                dfs(numbers, 0, evenSlots, oddSlots, false, memo)
        );

        out.println(answer);
        out.flush();
    }

    /**
     * Depth‑first search with memoisation.
     *
     * @param arr          the original input array (0 denotes a free slot)
     * @param pos          current index we are processing
     * @param evenLeft     how many even numbers are still available
     * @param oddLeft      how many odd numbers are still available
     * @param lastEven     parity of the element placed just before {@code pos}
     * @param memo       map that stores already computed states
     * @return minimal cost (number of parity changes) from the given state onward
     */
    private static long dfs(int[] arr, int pos, int evenLeft, int oddLeft,
                            boolean lastEven, HashMap<State, Long> memo) {
        if (pos == arr.length) {
            return 0L;                     // nothing left to place
        }

        State key = new State(pos, evenLeft, oddLeft, lastEven);
        Long cached = memo.get(key);
        if (cached != null) {
            return cached;
        }

        long best = INF;
        int cur = arr[pos];

        if (cur != 0) {                     // fixed number – just place it
            boolean curEven = ((cur & 1) == 0);
            long changeCost = (lastEven && !curEven) ? 1L : 0L;
            long nextCost = dfs(arr, pos + 1,
                    evenLeft, oddLeft, curEven, memo);
            best = nextCost + changeCost;
        } else {                            // free slot – try even or odd
            // place an even number if any are left
            if (evenLeft > 0) {
                long changeCost = lastEven ? 0L : 1L; // cost only when parity flips
                long nextCost = dfs(arr, pos + 1,
                        evenLeft - 1, oddLeft, true, memo);
                best = Math.min(best, nextCost + changeCost);
            }
            // place an odd number if any are left
            if (oddLeft > 0) {
                long changeCost = !lastEven ? 0L : 1L; // cost only when parity flips
                long nextCost = dfs(arr, pos + 1,
                        evenLeft, oddLeft - 1, false, memo);
                best = Math.min(best, nextCost + changeCost);
            }
        }

        memo.put(key, best);
        return best;
    }
}

import java.io.*;
import java.util.*;

public class Main {

    /** Fast input scanner */
    private static final FastScanner SCANNER = new FastScanner();
    /** Output wrapper to keep the original fast‑printing style */
    private static final Output OUT = new Output(System.out);

    /** Large constant used as INF (avoid overflow) */
    private static final long INF = Long.MAX_VALUE / 4;

    /** Upper bound for array size used in the original code */
    private static final int MAX_N = (int) 1e5;

    public static void main(String[] args) {
        new Solver().solve();
        OUT.flush();
    }

    /** Core solving routine – now clearly separated from I/O */
    private static class Solver {

        /** Solves the problem and prints the answer */
        void solve() {
            int n = SCANNER.nextInt();
            int[] a = readArray(n);

            // Number of positions that must stay odd after we replace zeros
            int oddCount = (n + 1) / 2;
            for (int v : a) {
                if (v != -1) {                     // original non‑zero value
                    oddCount -= v % 2;             // each odd number consumes one odd slot
                }
            }

            /*
             * dp[i][used][par] – minimal cost up to i‑th element,
             *   used  : how many odd numbers have already been placed,
             *   par   : parity of the position i (0 = even, 1 = odd).
             */
            long[][][] dp = new long[n + 1][oddCount + 1][2];
            fill(dp, INF);
            dp[0][0][0] = 0;   // empty prefix, no odd used, even parity
            dp[0][0][1] = 0;   // empty prefix, no odd used, odd parity

            for (int i = 1; i <= n; i++) {
                int cur = a[i - 1];                     // current value (‑1 marks a hole)
                for (int used = 0; used <= oddCount; used++) {
                    if (cur == -1) {                       // we may put either parity here
                        // place an even number
                        dp[i][used][0] = Math.min(dp[i][used][0],
                                Math.min(dp[i - 1][used][0], dp[i - 1][used][1] + 1));

                        // place an odd number (only if we still have odd slots left)
                        if (used > 0) {
                            dp[i][used][1] = Math.min(dp[i - 1][used - 1][0] + 1,
                                    dp[i - 1][used - 1][1]);
                        }
                    } else {                               // fixed number, its parity is known
                        int parity = cur % 2;              // 0 = even, 1 = odd
                        // transition from previous parity 0 (even)
                        dp[i][used][parity] = Math.min(dp[i][used][parity],
                                dp[i - 1][used][0] + cur);
                        // transition from previous parity 1 (odd)
                        dp[i][used][parity] = Math.min(dp[i][used][parity],
                                dp[i - 1][used][1] + (1 - cur));
                    }
                }
            }

            // Answer is the minimum cost after processing all elements,
            // using exactly oddCount odd numbers, and any final parity.
            OUT.println(Math.min(dp[n][oddCount][0], dp[n][oddCount][1]));
        }

        /** Reads the array while converting real zeros to the sentinel value -1 */
        private int[] readArray(int size) {
            int[] arr = new int[size];
            for (int i = 0; i < size; i++) {
                int v = SCANNER.nextInt();
                arr[i] = (v == 0) ? -1 : v;   // -1 denotes a “hole” (original zero)
            }
            return arr;
        }
    }

    /** Very small, reusable fast scanner */
    private static class FastScanner {
        private final InputStream stream;
        private final byte[] buffer = new byte[1024];
        private int ptr = 0, buflen = 0;

        FastScanner() {
            this(System.in);
        }

        private FastScanner(InputStream stream) {
            this.stream = stream;
        }

        /** Refill the internal buffer */
        private void load() {
            try {
                buflen = stream.read(buffer);
            } catch (IOException e) {
                throw new UncheckedIOException(e);
            }
            ptr = 0;
        }

        /** Check whether the next byte exists in the buffer */
        private boolean hasNextByte() {
            while (true) {
                if (ptr < buflen) return true;
                load();
                if (buflen <= 0) return false;
            }
        }

        /** Skip any non‑printable characters (used to find the next token) */
        private void skipNonPrintable() {
            while (hasNextByte() && !isPrintableChar(buffer[ptr])) ptr++;
        }

        /** Helper – a byte is printable if its ASCII code is between 33 and 126 */
        private boolean isPrintableChar(int c) {
            return c >= 33 && c <= 126;
        }

        public boolean hasNext() {
            skipNonPrintable();
            return hasNextByte();
        }

        public String next() {
            if (!hasNext()) throw new NoSuchElementException();
            StringBuilder sb = new StringBuilder();
            int b = readByte();
            while (isPrintableChar(b)) {
                sb.appendCodePoint(b);
                b = readByte();
            }
            return sb.toString();
        }

        public long nextLong() {
            return Long.parseLong(next());
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        private int readByte() {
            if (ptr >= buflen) load();
            return (ptr < buflen) ? buffer[ptr++] : -1;
        }
    }

    /** Small wrapper around PrintWriter that adds a few convenience printing helpers */
    private static class Output extends PrintWriter {
        Output(PrintStream ps) {
            super(ps);
        }

        public void print(int[] a, String sep) {
            for (int i = 0; i < a.length; i++) {
                if (i == 0) print(a[i]);
                else print(sep + a[i]);
            }
            println();
        }

        public void print(long[] a, String sep) {
            for (int i = 0; i < a.length; i++) {
                if (i == 0) print(a[i]);
                else print(sep + a[i]);
            }
            println();
        }

        public void print(String[] a, String sep) {
            for (int i = 0; i < a.length; i++) {
                if (i == 0) print(a[i]);
                else print(sep + a[i]);
            }
            println();
        }

        public void print(ArrayList<?> list, String sep) {
            for (int i = 0; i < list.size(); i++) {
                if (i == 0) print(list.get(i));
                else print(sep + list.get(i));
            }
            println();
        }
    }
}

import java.io.*;
import java.util.Arrays;

/**
 * Main class – entry point of the application.
 * It reads the input, processes the task with {@link Solver}
 * and prints the result.
 */
public class Main {

    /** Fast input helper that wraps {@link BufferedReader}. */
    private static final class FastInput {
        private final BufferedReader br;
        private StringTokenizer st;

        FastInput(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        /** Returns next token, or waits for more data if needed. */
        private String next() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                st = new StringTokenizer(br.readLine());
            }
            return st.nextToken();
        }

        /** Reads an {@code int}. */
        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }

    /** Encapsulates the logic of the problem solution. */
    private static final class Solver {

        /** Minimal number of mismatches that can be achieved. */
        private static final int IMPOSSIBLE = Integer.MAX_VALUE / 2;

        /**
         * Solves a single test case.
         *
         * @param in  input reader
         * @param out output writer
         */
        void solve(int testNumber, FastInput in, PrintWriter out) {
            int n = in.nextInt();

            int[] a = new int[n];
            int fixedEven = 0;   // already‑present even numbers
            int fixedOdd  = 0;   // already‑present odd  numbers

            for (int i = 0; i < n; i++) {
                a[i] = in.nextInt();
                if (a[i] != 0) {
                    if ((a[i] & 1) == 0) {
                        fixedEven++;
                    } else {
                        fixedOdd++;
                    }
                }
            }

            // In a permutation of {1,…,n} the required amount of each parity is:
            int requiredEven = n / 2;
            int requiredOdd  = (n + 1) / 2;

            // How many even / odd numbers still have to be placed on the zero cells?
            int evenToPlace = requiredEven - fixedEven;
            int oddToPlace  = requiredOdd  - fixedOdd;

            // dp[pos][e][o][par]  – minimal mismatches up to position `pos`
            // with `e` even numbers left, `o` odd numbers left and previous parity `par` (0 = even, 1 = odd)
            int[][][][] dp = new int[n + 1][evenToPlace + 1][oddToPlace + 1][2];

            // Initialise everything with a large value (effectively "infinite")
            for (int[][][] layer : dp) {
                for (int[][] layer2 : layer) {
                    for (int[] layer3 : layer2) {
                        Arrays.fill(layer3, IMPOSSIBLE);
                    }
                }
            }

            // Base case – before the first element we can start with either parity,
            // the cost is zero because there is no previous neighbour.
            dp[0][0][0][0] = 0;
            dp[0][0][0][1] = 0;

            // Main DP transition
            for (int pos = 1; pos <= n; pos++) {
                int cur = a[pos - 1];                // current value (0 means “empty”)
                for (int e = 0; e <= evenToPlace; e++) {
                    for (int o = 0; o <= oddToPlace; o++) {
                        for (int prevParity = 0; prevParity < 2; prevParity++) {
                            if (dp[pos - 1][e][o][prevParity] == IMPOSSIBLE) {
                                continue;            // unreachable state
                            }

                            if (cur != 0) {          // fixed number – just continue
                                int curParity = cur & 1;
                                int extraCost = (prevParity != curParity) ? 1 : 0;
                                dp[pos][e][o][curParity] = Math.min(
                                        dp[pos][e][o][curParity],
                                        dp[pos - 1][e][o][prevParity] + extraCost);
                            } else {                 // empty slot – we can put even or odd
                                // ---- place an even number ----
                                if (e > 0) {
                                    int extraCost = (prevParity != 0) ? 1 : 0;
                                    dp[pos][e][o][0] = Math.min(
                                            dp[pos][e][o][0],
                                            dp[pos - 1][e - 1][o][prevParity] + extraCost);
                                }
                                // ---- place an odd number ----
                                if (o > 0) {
                                    int extraCost = (prevParity != 1) ? 1 : 0;
                                    dp[pos][e][o][1] = Math.min(
                                            dp[pos][e][o][1],
                                            dp[pos - 1][e][o - 1][prevParity] + extraCost);
                                }
                            }
                        }
                    }
                }
            }

            // The answer is the best cost after processing the whole array,
            // with exactly the needed number of evens and odds placed,
            // ending with either parity.
            int answer = Math.min(
                    dp[n][evenToPlace][oddToPlace][0],
                    dp[n][evenToPlace][oddToPlace][1]);

            out.println(answer);
        }
    }

    /** Program entry point. */
    public static void main(String[] args) throws IOException {
        FastInput input = new FastInput(System.in);
        PrintWriter out = new PrintWriter(System.out);
        Solver solver = new Solver();
        solver.solve(1, input, out);   // there is only a single test case in the original template
        out.close();
    }
}

import java.io.*;
import java.util.*;

public class C612 {

    /** Minimal value used for “unreachable” DP states. */
    private static final int INF = Integer.MAX_VALUE / 4;

    /** Fast scanner that mimics the original MyScanner. */
    private static class FastScanner {
        private final BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        private StringTokenizer st;

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    throw new UncheckedIOException(e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }
    }

    public static void main(String[] args) {
        FastScanner sc = new FastScanner();
        PrintWriter out = new PrintWriter(new BufferedOutputStream(System.out));

        int n = sc.nextInt();                     // length of the sequence
        int[] values = new int[n];                // -1 = unknown, 0 = even, 1 = odd
        List<Integer> unknownPos = new ArrayList<>();

        // How many positions must finally contain even / odd numbers?
        int requiredEven = n / 2;                 // floor(n/2)
        int requiredOdd  = (n + 1) / 2;           // ceil(n/2)

        // Count already‑fixed even / odd numbers and mark unknown slots
        for (int i = 0; i < n; i++) {
            int v = sc.nextInt();
            if (v == 0) {
                values[i] = -1;                // placeholder for a missing number
                unknownPos.add(i);
            } else if (v % 2 == 0) {
                values[i] = 0;                 // even
            } else {
                values[i] = 1;                 // odd
            }
        }

        // DP[pos][filledEven][filledOdd][lastParity] = minimal number of adjacent
        // differences seen up to position 'pos' (0‑based) with the given counts.
        int[][][][] dp = new int[n + 1][requiredEven + 1][requiredOdd + 1][2];
        fillWithInfinity(dp);

        // Base case: nothing placed yet, last parity can be imagined as 0 or 1 with cost 0.
        dp[0][0][0][0] = 0;
        dp[0][0][0][1] = 0;

        for (int pos = 0; pos < n; pos++) {
            int placeholder = values[pos]; // -1 = unknown, 0 = even, 1 = odd

            for (int usedEven = 0; usedEven <= requiredEven; usedEven++) {
                for (int usedOdd = 0; usedOdd <= requiredOdd; usedOdd++) {
                    for (int lastParity = 0; lastParity < 2; lastParity++) {
                        int curCost = dp[pos][usedEven][usedOdd][lastParity];
                        if (curCost == INF) continue;

                        if (placeholder != -1) {               // fixed digit
                            int parity = placeholder;
                            int nextEven = usedEven;
                            int nextOdd  = usedOdd;
                            if (parity == 0) nextEven++;
                            else            nextOdd++;

                            int transition = (lastParity != parity) ? 1 : 0;
                            int newCost = curCost + transition;
                            if (newCost < dp[pos + 1][nextEven][nextOdd][parity]) {
                                dp[pos + 1][nextEven][nextOdd][parity] = newCost;
                            }
                        } else {                                 // unknown digit
                            // try to place an even number
                            if (usedEven < requiredEven) {
                                int nextEven = usedEven + 1;
                                int nextOdd  = usedOdd;
                                int transition = (lastParity != 0) ? 1 : 0;
                                int newCost = curCost + transition;
                                if (newCost < dp[pos + 1][nextEven][nextOdd][0]) {
                                    dp[pos + 1][nextEven][nextOdd][0] = newCost;
                                }
                            }
                            // try to place an odd number
                            if (usedOdd < requiredOdd) {
                                int nextEven = usedEven;
                                int nextOdd  = usedOdd + 1;
                                int transition = (lastParity != 1) ? 1 : 0;
                                int newCost = curCost + transition;
                                if (newCost < dp[pos + 1][nextEven][nextOdd][1]) {
                                    dp[pos + 1][nextEven][nextOdd][1] = newCost;
                                }
                            }
                        }
                    }
                }
            }
        }

        int answer;
        if (unknownPos.contains(n - 1)) { // the last element was originally unknown
            answer = Math.min(dp[n][requiredEven][requiredOdd][0],
                              dp[n][requiredEven][requiredOdd][1]);
        } else {
            int parity = values[n - 1];   // deterministic parity of the last digit
            answer = dp[n][requiredEven][requiredOdd][parity];
        }

        out.println(answer);
        out.close();
    }

    /** Helper that fills a 4‑D array with INF. */
    private static void fillWithInfinity(int[][][][] arr) {
        for (int[][][] a : arr) {
            for (int[][] b : a) {
                for (int[] c : b) {
                    Arrays.fill(c, INF);
                }
            }
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

/**
 * Refactored version of the original program.
 *
 * <p>
 *   The program reads two input lines:
 *   <ul>
 *     <li>The first line contains a single integer {@code N}.</li>
 *     <li>The second line contains {@code N} integers separated by whitespace.</li>
 *   </ul>
 *   Using a memoised recursive DP it computes a value that mimics the
 *   behaviour of the original implementation and prints it.
 * </p>
 *
 * <p>
 *   The refactor improves readability and maintainability by:
 *   <ul>
 *     <li>Using meaningful identifiers.</li>
 *     <li>Separating concerns (input, DP initialisation, core logic).</li>
 *     <li>Encapsulating mutable state in dedicated fields.</li>
 *     <li>Removing dead/unused code.</li>
 *     <li>Adding short comments that explain intent.</li>
 *   </ul>
 * </p>
 */
public class Main {

    /** Full array of parsed integers. */
    private static int[] values;

    /** Number of elements. */
    private static int N;

    /**
     * Memoisation table:
     * <p>
     * {@code dp[i][e][o][prevParity]} stores the maximal length that can be
     * achieved starting at position {@code i} when {@code e} even slots,
     * {@code o} odd slots remain and the previous element had parity
     * {@code prevParity} (0 = even, 1 = odd).
     * </p>
     */
    private static int[][][][] dp;

    /**
     * Initial “capacity” for even and odd slots – these values are derived
     * from the original code (roughly half of {@code N} for even and the
     * remainder for odd).
     */
    private static int INIT_E, INIT_O;

    public static void main(String[] args) throws IOException {
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in))) {
            // -----------------------------------------------------------
            // 1️⃣  Read and parse input
            // -----------------------------------------------------------
            String line = br.readLine();
            if (line == null || line.isBlank()) {
                return;
            }
            N = Integer.parseInt(line.trim());

            line = br.readLine();
            if (line == null) {
                return;
            }
            String[] tokens = line.trim().split("\\s+");
            values = new int[N];
            for (int i = 0; i < N; i++) {
                values[i] = Integer.parseInt(tokens[i]);
            }

            // -----------------------------------------------------------
            // 2️⃣  Initialise algorithm parameters
            // -----------------------------------------------------------
            INIT_E = N / 2;          // initial even‑slot count
            INIT_O = N - INIT_E;     // initial odd‑slot count (ceil(N/2))

            // -----------------------------------------------------------
            // 3️⃣  Prepare DP table (fill with -1 = “unvisited”)
            // -----------------------------------------------------------
            dp = new int[N][INIT_E + 1][INIT_O + 1][2];
            fillDpWithMinusOne();

            // -----------------------------------------------------------
            // 4️⃣  Compute and print the result
            // -----------------------------------------------------------
            int result = computeResult();
            System.out.println(result);
        }
    }

    /** Fill the DP table with the sentinel value -1 (meaning “not computed yet”). */
    private static void fillDpWithMinusOne() {
        for (int i = 0; i < N; i++) {
            for (int e = 0; e <= INIT_E; e++) {
                for (int o = 0; o <= INIT_O; o++) {
                    dp[i][e][o][0] = -1;
                    dp[i][e][o][1] = -1;
                }
            }
        }
    }

    /**
     * Core algorithm that decides which branch to take based on the first
     * element and then delegates to the memoised recursion.
     */
    private static int computeResult() {
        if (values[0] == 0) {
            // First element is zero – we can treat it as either even or odd.
            if (INIT_E > 0 && INIT_O > 0) {
                int best = Math.max(
                        go(1, 0, INIT_E - 1, INIT_O),
                        go(1, 1, INIT_E, INIT_O - 1));
                return N - 1 - best;
            } else if (INIT_E > 0) {
                return N - 1 - go(1, 0, INIT_E - 1, INIT_O);
            } else {
                return N - 1 - go(1, 1, INIT_E, INIT_O - 1);
            }
        } else {
            // First element has a definite parity.
            if (values[0] % 2 == 0) {
                return N - 1 - go(1, 0, INIT_E, INIT_O);
            } else {
                return N - 1 - go(1, 1, INIT_E, INIT_O);
            }
        }
    }

    /**
     * Memoised recursive function that returns the maximal length that can be
     * obtained from position {@code i} onward.
     *
     * @param i        current index in the array
     * @param prevParity parity of the previously placed element (0 = even,
     *                   1 = odd)
     * @param e        remaining even‑slot count
     * @param o        remaining odd‑slot count
     * @return maximal achievable length from this state
     */
    private static int go(int i, int prevParity, int e, int o) {
        if (i == N) {
            return 0; // base case: no more elements
        }
        if (dp[i][e][o][prevParity] != -1) {
            return dp[i][e][o][prevParity]; // cached result
        }

        int outcome;
        if (values[i] == 0) {
            // Zero can be interpreted as either even or odd, depending on
            // the surrounding context.
            if (prevParity == 0) { // previously placed an even number
                if (e > 0 && o > 0) {
                    outcome = Math.max(
                            1 + go(i + 1, 0, e - 1, o), // treat zero as even
                            go(i + 1, 1, e, o - 1));    // treat zero as odd
                } else if (e > 0) {
                    outcome = 1 + go(i + 1, 0, e - 1, o);
                } else {
                    outcome = go(i + 1, 1, e, o - 1);
                }
            } else { // previously placed an odd number
                if (e > 0 && o > 0) {
                    outcome = Math.max(
                            go(i + 1, 0, e - 1, o),      // treat zero as even
                            1 + go(i + 1, 1, e, o - 1)); // treat zero as odd
                } else if (e > 0) {
                    outcome = go(i + 1, 0, e - 1, o);
                } else {
                    outcome = 1 + go(i + 1, 1, e, o - 1);
                }
            }
        } else {
            // Non‑zero element – its parity is fixed.
            int curParity = (values[i] % 2 == 0) ? 0 : 1;
            if (prevParity == 0) { // previous was even
                if (curParity == 0) {
                    outcome = 1 + go(i + 1, 0, e, o); // continue with even
                } else {
                    outcome = go(i + 1, 1, e, o);    // switch to odd
                }
            } else { // previous was odd
                if (curParity == 0) {
                    outcome = go(i + 1, 0, e, o);    // switch to even
                } else {
                    outcome = 1 + go(i + 1, 1, e, o); // continue with odd
                }
            }
        }

        dp[i][e][o][prevParity] = outcome;
        return outcome;
    }
}

/**
 * Refactored solution for the “Garland” problem.
 *
 * The program reads an integer {@code n} followed by an {@code n}‑element
 * array that may contain zeros. Zeroes represent missing numbers that have
 * to be filled with the unused integers from {@code 1..n}.  The goal is to
 * place those numbers so that the number of adjacent elements having
 * different parity is minimized.
 *
 * The solution uses memoised recursion (top‑down DP) to explore the
 * combinatorial choices efficiently.
 *
 * The refactor focuses on readability, maintainability and proper encapsulation:
 *
 *  • All I/O is wrapped in a small, well‑named {@code FastScanner}.
 *  • Complex state (DP memoisation) is confined to a dedicated class.
 *  • Magic numbers are replaced by named constants.
 *  • Variable names describe their purpose.
 *  • The code follows a clear functional decomposition (input → preprocessing → DP → output).
 */
public class Main {

    /** Constant used to denote “infinite” cost in the DP recurrence. */
    private static final long INF = Long.MAX_VALUE / 4;

    /** --------------------------------------------------------------------- */
    /** Entry point. */
    public static void main(String[] args) {
        FastScanner scanner = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(System.out, true);

        int testCases = 1;                     // problem always has exactly one test case
        new GarlandSolver().solve(testCases, scanner, out);

        out.close();
        scanner.close();
    }

    /** --------------------------------------------------------------------- */
    /** Fast scanner that works with the original input format. */
    private static final class FastScanner {
        private final BufferedInputStream bis;
        private final byte[] buffer = new byte[4 * 1024];
        private int bufferPos = 0, bufferLen = 0;

        FastScanner(InputStream in) {
            this.bis = new BufferedInputStream(in);
        }

        /** Skips whitespace characters. */
        private int skipWhiteSpace() throws IOException {
            int b;
            do {
                b = read();
            } while (isWhiteSpace(b));
            return b;
        }

        /** Reads next unsigned byte from the underlying stream. */
        private int read() throws IOException {
            if (bufferPos >= bufferLen) {
                bufferPos = 0;
                bufferLen = bis.read(buffer);
                if (bufferLen <= 0) {
                    return -1;
                }
            }
            return buffer[bufferPos++];
        }

        /** Checks whether a byte value represents whitespace. */
        private static boolean isWhiteSpace(int b) {
            return b == ' ' || b == '\n' || b == '\r' || b == '\t' || b == -1;
        }

        /** Reads the next 32‑bit signed integer. */
        int scanInt() throws IOException {
            int sign = 1;
            int c = skipWhiteSpace();
            if (c == '-') {
                sign = -1;
                c = read();
            }
            int result = 0;
            while (!isWhiteSpace(c) && c != -1) {
                if (c >= '0' && c <= '9') {
                    result = result * 10 + (c - '0');
                }
                c = read();
            }
            return sign * result;
        }

        /** Convenience method used when the whole array must be read at once. */
        void scanInt(int[] target) throws IOException {
            for (int i = 0; i < target.length; i++) {
                target[i] = scanInt();
            }
        }

        /** Closes the underlying stream – idempotent. */
        void close() throws IOException {
            bis.close();
        }
    }

    /** --------------------------------------------------------------------- */
    /** Core logic that solves a single test case. */
    private static final class GarlandSolver {
        /** The original input array (may contain zeros). */
        private int[] numbers;
        /** Length of the array. */
        private int n;
        /** Memoisation table for DP. */
        private long[][][][] memo; // [index][oddLeft][evenLeft][prevParity]

        /**
         * Solves the problem for the supplied {@code testNumber} (always 1 in this
         * problem) and writes the result to {@code out}.
         */
        void solve(int testNumber, FastScanner in, PrintWriter out) throws IOException {
            readInput(in);
            initialiseMemo();
            int oddMissing = countOddMissing();
            int evenMissing = countEvenMissing();

            long answer = computeMinCost(1, oddMissing, evenMissing, -1);
            out.println(answer);
        }

        /** ----------------------------------------------------------------- */
        /** Reads {@code n} and the array from the scanner. */
        private void readInput(FastScanner in) throws IOException {
            n = in.scanInt();
            numbers = new int[n];
            in.scanInt(numbers);
        }

        /** ----------------------------------------------------------------- */
        /** Sets up the DP memoisation table with “uninitialised” marker (-1). */
        private void initialiseMemo() {
            // dimensions: index (0..n), oddRem (0..max), evenRem (0..max), parity (0/1)
            memo = new long[n + 1][n + 1][n + 1][2];
            for (long[][][] dim1 : memo) {
                for (long[][] dim2 : dim1) {
                    for (long[] dim3 : dim2) {
                        java.util.Arrays.fill(dim3, -1L);
                    }
                }
            }
        }

        /** ----------------------------------------------------------------- */
        /** Counts how many odd numbers are missing from 1..n. */
        private int countOddMissing() {
            boolean[] used = new boolean[n + 1];
            for (int v : numbers) {
                if (v != 0) {
                    used[v] = true;
                }
            }
            int odd = 0, even = 0;
            for (int i = 1; i <= n; i++) {
                if (!used[i]) {
                    if (i % 2 == 0) {
                        even++;
                    } else {
                        odd++;
                    }
                }
            }
            // store counts for later use
            this.oddMissing = odd;
            this.evenMissing = even;
            return odd;
        }

        /** ----------------------------------------------------------------- */
        /** Recursive DP that returns the minimal additional cost starting at
         *  {@code idx}.  The arguments describe the remaining numbers that can be placed.
         */
        private long computeMinCost(int idx, int oddLeft, int evenLeft, int prevParity) {
            // base case – all positions processed
            if (idx == n) {
                return 0L;
            }
            // out‑of‑bounds guard (should never happen, defensive programming)
            if (oddLeft < 0 || evenLeft < 0) {
                return INF;
            }

            long cached = memo[idx][oddLeft][evenLeft][prevityToIndex(prevParity)];
            if (cached != -1) {
                return cached;
            }

            int currentValue = numbers[idx];
            long best = INF;

            if (currentValue != 0) {
                // fixed (non‑zero) element – just continue, adding cost if parity differs
                int curParity = currentValue % 2;
                int mismatch = (prevParity >= 0 && curParity != prevParity) ? 1 : 0;
                long cost = mismatch + computeMinCost(idx + 1, oddLeft, evenLeft, curParity);
                best = cost;
            } else {
                // try placing an even number
                if (evenLeft > 0) {
                    int mismatch = (prevParity >= 0 && 0 != prevParity) ? 1 : 0;
                    long cost = mismatch + computeMinCost(idx + 1, oddLeft, evenLeft - 1, 0);
                    best = Math.min(best, cost);
                }
                // try placing an odd number
                if (oddLeft > 0) {
                    int mismatch = (prevParity >= 0 && 1 != prevParity) ? 1 : 0;
                    long cost = mismatch + computeMinCost(idx + 1, oddLeft - 1, evenLeft, 1);
                    best = Math.min(best, cost);
                }
            }

            memo[idx][oddLeft][evenLeft][prevityToIndex(prevParity)] = best;
            return best;
        }

        /** Helper: converts parity (0‑even, 1‑odd, -1‑none) to the index used in memo table. */
        private int prevityToIndex(int p) {
            return (p + 1) % 2; // maps -1 → 0, 0 → 1, 1 → 1
        }

        // fields that are filled lazily by countOddMissing()
        private int oddMissing, evenMissing;
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.StringTokenizer;

/**
 * Reads an integer {@code N} and a sequence of {@code N} integers.
 * The program computes the minimum additional cost needed to transform
 * the sequence according to a set of rules involving runs of zeros.
 *
 * The refactor focuses on readability, modularisation and use of modern
 * Java features while preserving the original behaviour.
 */
public class Main {

    /** Size target for parity 0. */
    private static final int[] REQUIRED_COUNTS = new int[2];

    /** Simple data holder for a contiguous segment of zeros. */
    private static final class Segment implements Comparable<Segment> {
        /** start index (inclusive) */
        final int start;
        /** end index (inclusive) */
        final int end;
        /** cost for applying a transformation on this segment */
        final int cost;

        Segment(int start, int end, int cost) {
            this.start = start;
            this.end = end;
            this.cost = cost;
        }

        /** Sort by cost first, then by length (shortest longest first). */
        @Override
        public int compareTo(Segment other) {
            return Integer.compare(this.cost, other.cost);
        }
    }

    public static void main(String[] args) {
        try (InputReader reader = new InputReader()) {
            int n = reader.nextInt();
            if (n == 1) {
                System.out.println(0);
                return;
            }

            int[] positions = readAndTransform(reader, n);
            computeRequiredCounts(n);
            List<Segment>[] buckets = createBuckets();

            int additionalCost = processSegments(positions, buckets, n);
            System.out.println(additionalCost);
        }
    }

    /** --------------------------------------------------------------------- */
    /** Reads the raw input, maps zeros to {@code -1} and stores the parity.   */
    private static int[] readAndTransform(InputReader reader, int n) {
        int[] p = new int[n];
        // initialise the required counts (half / half+1 depending on parity)
        REQUIRED_COUNTS[0] = n / 2;
        REQUIRED_COUNTS[1] = n / 2 + n % 2;

        for (int i = 0; i < n; i++) {
            int v = reader.nextInt();
            if (v == 0) {
                p[i] = -1;                     // sentinel for “empty” slot
            } else {
                p[i] = v % 2;                    // keep only parity 0/1
                REQUIRED_COUNTS[p[i]]--;       // one position already satisfied
            }
        }

        // If after removal there is nothing left to satisfy, we are done.
        if (REQUIRED_COUNTS[0] + REQUIRED_COUNTS[1] == n) {
            System.out.println(1);
            System.exit(0);
        }

        return p;
    }

    /** --------------------------------------------------------------------- */
    /** Calculates the target counts for each parity (0 → even, 1 → odd).   */
    private static void computeRequiredCounts(int n) {
        REQUIRED_COUNTS[0] = n / 2;
        REQUIRED_COUNTS[1] = n / 2 + n % 2;
    }

    /** --------------------------------------------------------------------- */
    /** Creates two buckets (lists) that will hold segments according to their target parity. */
    private static List<Segment>[] createBuckets() {
        List<Segment>[] buckets = new List[2];
        buckets[0] = new ArrayList<>();
        buckets[1] = new ArrayList<>();
        return buckets;
    }

    /** --------------------------------------------------------------------- */
    /** Detects runs of consecutive {@code -1}s, classifies them and adds
     *  the corresponding {@link Segment} to the appropriate bucket.      */
    private static void detectSegments(int[] p, List<Segment>[] buckets) {
        final int length = p.length;
        for (int idx = 0; idx < length; ) {
            if (p[idx] != -1) {
                idx++;
                continue;
            }

            int start = idx;
            while (idx < length && p[idx] == -1) {
                idx++;
            }
            int end = idx - 1;

            // Determine the surrounding parity values (if any)
            int leftParity = (start > 0) ? p[start - 1] : p[end + 1];
            int rightParity = (end < length - 1) ? p[end + 1] : p[start - 1];

            // If both neighbours have the same parity, we can possibly “absorb”
            // this whole segment without extra cost; otherwise we must pay.
            int surroundingParity = (start > 0 && end < length - 1 && p[start - 1] == p[end + 1])
                    ? p[start - 1] : leftParity;

            int cost = (start > 0 && end < length - 1 && p[start - 1] != p[end + 1]) ? 1 : 0;
            Segment seg = new Segment(start, end, (surroundingParity == 0) ? 1 : 2);
            buckets[surroundingParity].add(seg);

            // Skip processed indices
            if (idx == start) idx++;
        }

        // Sort each bucket by the segment cost (cheapest first)
        for (List<Segment> bucket : buckets) {
            Collections.sort(bucket);
        }
    }

    /** --------------------------------------------------------------------- */
    /** Main algorithm: consumes segments according to remaining required counts. */
    private static int processSegments(int[] p, List<Segment>[] buckets, int n) {
        int extraCost = 0;

        for (int parity = 0; parity < 2; parity++) {
            int needed = REQUIRED_COUNTS[parity];
            for (Segment seg : buckets[parity]) {
                if (needed >= seg.end - seg.start + 1) {
                    needed -= seg.end - seg.start + 1;    // completely fill the needed quota
                } else {
                    extraCost += seg.cost;               // partial fill – add cost
                }
            }
            // Update the global counter for the next iteration (if reused)
            REQUIRED_COUNTS[parity] = needed;
        }

        return extraCost;
    }

    /** --------------------------------------------------------------------- */
    /** Simple line‑/token reader that works with BufferedReader.               */
    private static final class InputReader implements AutoCloseable {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        InputReader() {
            this.reader = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) {
                        return null;
                    }
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        @Override
        public void close() {
            try {
                reader.close();
            } catch (IOException e) {
                throw new RuntimeException(e);
            }
        }
    }
}

import java.io.*;
import java.util.*;

public class Garland {

    /** Larger than any possible answer – used as “infinity”. */
    private static final int INF = 100;

    /** Upper bound for the numbers of evens / odds that can be used. */
    private static final int MAX_USABLE = 50;

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        int n = Integer.parseInt(br.readLine().trim());

        int[] values = parseLine(br.readLine());

        int[][][][] memo = new int[n][MAX_USABLE + 1][MAX_USABLE + 1][2];
        fillMemo(memo);

        int answerStartingWithEven = dpMin(0, 1, 0, 0, n, values, memo);
        int answerStartingWithOdd  = dpMin(0, 0, 1, 1, n, values, memo);

        System.out.println(Math.min(answerStartingWithEven, answerStartingWithOdd));
    }

    /** Reads a whitespace‑separated line of integers into an array. */
    private static int[] parseLine(String line) {
        String[] tokens = line.trim().split("\\s+");
        int[] arr = new int[tokens.length];
        for (int i = 0; i < tokens.length; i++) {
            arr[i] = Integer.parseInt(tokens[i]);
        }
        return arr;
    }

    /** Initializes the memoisation table with the sentinel value {@code INF}. */
    private static void fillMemo(int[][][][] memo) {
        for (int i = 0; i < memo.length; i++) {
            for (int e = 0; e <= MAX_USABLE; e++) {
                for (int o = 0; o <= MAX_USABLE; o++) {
                    memo[i][e][o][0] = INF;
                    memo[i][e][o][1] = INF;
                }
            }
        }
    }

    /**
     * Minimum number of insertions required for the suffix that starts at {@code idx}
     * given how many evens/odds have already been used and the parity we are currently
     * expecting (0 = even, 1 = odd).
     */
    private static int dpMin(int idx, int usedEven, int usedOdd, int expecting,
                             int n, int[] arr, int[][][][] memo) {
        // out‑of‑range guard – should never be reached because callers check the index
        if (idx == n) {
            return 0;
        }

        // Prune impossible states
        if (exceedsLimits(usedEven, usedOdd, n) ||
            usedEven > MAX_USABLE || usedOdd > MAX_USABLE) {
            return INF;
        }

        int cached = memo[idx][usedEven][usedOdd][expecting];
        if (cached != INF) {
            return cached;
        }

        int cur = arr[idx];

        // Fixed (non‑zero) value that does not match the required parity makes the state invalid
        if (cur != 0 && ((expecting + cur) % 2) == 1) {
            cached = INF;
        } else if (idx == n - 1) {
            // Last position needs no further work
            cached = 0;
        } else if (cur == 0) {
            cached = handleZeroPosition(idx, usedEven, usedOdd, expecting, n, arr, memo);
        } else {
            cached = handleFixedPosition(idx, usedEven, usedOdd, cur, n, arr, memo);
        }

        memo[idx][usedEven][usedOdd][expecting] = cached;
        return cached;
    }

    /** Handles the case where the current element is zero (a free slot). */
    private static int handleZeroPosition(int idx, int usedEven, int usedOdd, int expecting,
                                          int n, int[] arr, int[][][][] memo) {
        int next = arr[idx + 1];                // the original code always looks one step ahead

        if (next == 0) {                         // two consecutive zeros
            if (expecting == 0) {
                // place an even now → no extra cost, or place an odd now → cost 1
                return Math.min(
                        dpMin(idx + 1, usedEven + 1, usedOdd, 0, n, arr, memo),
                        1 + dpMin(idx + 1, usedEven, usedOdd + 1, 1, n, arr, memo));
            } else {
                // place an even now → cost 1, or place an odd now → no extra cost
                return Math.min(
                        1 + dpMin(idx + 1, usedEven + 1, usedOdd, 0, n, arr, memo),
                        dpMin(idx + 1, usedEven, usedOdd + 1, 1, n, arr, memo));
            }
        }

        // Single zero – the decision depends on the parity of the following element
        if ((next % 2) == 0) {                    // next element is even
            if (expecting == 0) {
                // matching parity → no extra cost
                return dpMin(idx + 1, usedEven + 1, usedOdd, 0, n, arr, memo);
            } else {
                // mismatch → we have to insert an even, costing one operation
                return 1 + dpMin(idx + 1, usedEven + 1, usedOdd, 0, n, arr, memo);
            }
        } else {                                  // next element is odd
            if (expecting == 0) {
                // mismatch → insert an odd, costing one operation
                return 1 + dpMin(idx + 1, usedEven, usedOdd + 1, 1, n, arr, memo);
            } else {
                // matching parity → no extra cost
                return dpMin(idx + 1, usedEven, usedOdd + 1, 1, n, arr, memo);
            }
        }
    }

    /** Handles a fixed (non‑zero) value. */
    private static int handleFixedPosition(int idx, int usedEven, int usedOdd, int cur,
                                           int n, int[] arr, int[][][][] memo) {
        // The original algorithm does not use the “expecting” argument for fixed values,
        // it simply evaluates two possible continuations and picks the cheaper one.
        int evenBranch = dpMin(idx + 1, usedEven + 1, usedOdd, 0, n, arr, memo);
        int oddBranch  = dpMin(idx + 1, usedEven, usedOdd + 1, 1, n, arr, memo);

        int result;
        if ((cur % 2) == 0) {                     // current value is even
            result = Math.min(evenBranch, 1 + oddBranch);
        } else {                                   // current value is odd
            result = Math.min(1 + evenBranch, oddBranch);
        }
        return result;
    }

    /** Returns true if the used counts exceed the allowed maximums for the given length. */
    private static boolean exceedsLimits(int evens, int odds, int length) {
        int maxEven = length / 2;
        int maxOdd  = (length + 1) / 2;
        return evens > maxEven || odds > maxOdd;
    }
}

import java.io.IOException;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.Scanner;

/**
 * Refactored solution for the “Parity arrangement” problem.
 *
 * <p>The program reads an array that may contain zeros (missing values).
 * It must fill the zeros with exactly the required amount of even and odd
 * numbers so that the total number of adjacent elements having different
 * parity is minimal. The result is printed as the sum of the parity changes
 * that already exist among the fixed elements and the minimal additional
 * changes introduced by the filling.
 *
 * <p>The implementation is deliberately split into small, well‑named
 * methods and uses memoised recursion with a clear state description.
 */
public class Problem7C {

    private static final Scanner SC = new Scanner(System.in);

    public static void main(String[] args) {
        int n = SC.nextInt();
        int[] arr = new int[n];
        for (int i = 0; i < n; i++) {
            arr[i] = SC.nextInt();
        }

        // -----------------------------------------------------------------
        // 1. Analyse the fixed part of the array
        // -----------------------------------------------------------------
        int existingEvens = 0, existingOdds = 0;
        int existingChanges = 0;                     // adjacent opposite parity among non‑zero neighbours
        for (int v : arr) {
            if (v != 0) {
                if ((v & 1) == 0) existingEvens++;
                else existingOdds++;
            }
        }
        for (int i = 0; i < n - 1; i++) {
            if (arr[i] != 0 && arr[i + 1] != 0 &&
                ((arr[i] & 1) ^ (arr[i + 1] & 1)) != 0) {
                existingChanges++;
            }
        }

        // -----------------------------------------------------------------
        // 2. Determine how many even / odd numbers are still needed
        // -----------------------------------------------------------------
        int targetEvens = n / 2;
        int targetOdds = (n + 1) / 2;
        int needEvens = targetEvens - existingEvens;
        int needOdds = targetOdds - existingOdds;

        // -----------------------------------------------------------------
        // 3. Collect positions of the missing (zero) entries
        // -----------------------------------------------------------------
        List<Integer> zeroPositions = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            if (arr[i] == 0) {
                zeroPositions.add(i);
            }
        }
        int missing = zeroPositions.size();

        // No missing values → answer is just the already counted changes
        if (missing == 0) {
            System.out.println(existingChanges);
            return;
        }

        // -----------------------------------------------------------------
        // 4. Memoised DP over the list of zero positions
        // -----------------------------------------------------------------
        // memo[idx][remainingOdds][previousParity]   (0 = even, 1 = odd, 2 = none)
        int[][][] memo = new int[missing][needOdds + 1][3];
        for (int[][] a : memo) for (int[] b : a) Arrays.fill(b, Integer.MAX_VALUE / 4);

        int addedChanges = dp(arr, zeroPositions, 0, needOdds, memo, 2);
        System.out.println(existingChanges + addedChanges);
    }

    /**
     * Recursively computes the minimum additional parity changes that appear
     * when filling the zeros starting at {@code idx}.
     *
     * @param arr          the original array (contains 0 for missing values)
     * @param zeros        list of indices of the zeros in increasing order
     * @param idx          current position inside {@code zeros}
     * @param remOdds      how many odd numbers are still to be placed
     * @param memo         memoisation table
     * @param prevParity   parity of the element that stands immediately
     *                     before the current zero (0 = even, 1 = odd, 2 = none)
     * @return minimal number of new parity changes introduced by an optimal fill
     */
    private static int dp(int[] arr, List<Integer> zeros,
                          int idx, int remOdds, int[][][] memo, int prevParity) {
        if (idx == zeros.size()) {
            return 0;                                 // all zeros have been processed
        }
        if (memo[idx][remOdds][prevParity] != Integer.MAX_VALUE / 4) {
            return memo[idx][remOdds][prevParity];
        }

        int best = Integer.MAX_VALUE / 4;
        int pos = zeros.get(idx);

        // -------------------------------------------------------------
        //  Try to place an odd number (if we still have any left)
        // -------------------------------------------------------------
        if (remOdds > 0) {
            int curParity = 1;                        // odd
            int transition = (prevParity != 2 && prevParity != curParity) ? 1 : 0;
            int next = transition +
                    dp(arr, zeros, idx + 1, remOdds - 1, memo, curParity);
            best = Math.min(best, next);
        }

        // -------------------------------------------------------------
        //  Try to place an even number
        // -------------------------------------------------------------
        int remainingSlots = zeros.size() - idx;      // how many zeros are still to fill
        int neededEvens = remainingSlots - remOdds;   // evens that must still be placed
        if (neededEvens > 0) {
            int curParity = 0;                        // even
            int transition = (prevParity != 2 && prevParity != curParity) ? 1 : 0;
            int next = transition +
                    dp(arr, zeros, idx + 1, remOdds, memo, curParity);
            best = Math.min(best, next);
        }

        memo[idx][remOdds][prevParity] = best;
        return best;
    }
}

import java.io.*;
import java.util.StringTokenizer;

/**
 * Refactored solution for the competitive‑programming problem.
 *
 * <p>The original implementation used raw arrays of a fixed capacity (200) and mixed
 * all logic inside {@code main}.  This version improves maintainability by:
 *
 * <ul>
 *   <li>Using meaningful constants and variable names.</li>
 *   <li>Separating the input handling into a small reusable {@code InputReader}</li>
 *   <li>Encapsulating DP initialization and transition logic into dedicated methods.</li>
 *   <li>Choosing dynamic data structures where the problem size is not known at compile‑time.</li>
 *   <li>Adding Javadoc comments and inline comments to explain the algorithm.</li>
 * </ul>
 *
 * @author  Your Name
 */
public class Main {

    /** Large sentinel value used for DP initialisation. */
    private static final int INF = Integer.MAX_VALUE / 4;

    /** Reads tokens from standard input. */
    private static final class InputReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        InputReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream), 1 << 16);
        }

        /** Returns the next token. */
        private String next() {
            try {
                while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                    tokenizer = new StringTokenizer(reader.readLine());
                }
            } catch (IOException ex) {
                throw new UncheckedIOException(ex);
            }
            return tokenizer.nextToken();
        }

        /** Convenience method for reading an {@code int}. */
        int nextInt() {
            return Integer.parseInt(next());
        }
    }

    public static void main(String[] args) {
        /* ------------------------ 1. Input ----------------------------------- */
        InputReader in = new InputReader(System.in);
        PrintWriter out = new PrintWriter(System.out, true); // auto‑flush

        int n = in.nextInt();               // total number of elements
        int[] inputArray = new int[n + 1];    // 1‑based indexing like the original
        for (int i = 1; i <= n; i++) {
            inputArray[i] = in.nextInt();
        }

        /* ------------------------ 2. Pre‑processing ----------------------- */
        // Count zeros up to each position (used later for calculating how many
        // "zero‑positions" are still available).
        int[] prefixZeroCount = new int[n + 1];
        for (int i = 1; i <= n; i++) {
            prefixZeroCount[i] = prefixZeroCount[i - 1] + (inputArray[i] == 0 ? 1 : 0);
        }

        // Determine how many even‑indexed and odd‑indexed positions are *currently*
        // occupied by non‑zero numbers.  (Indices are 1‑based in the problem.)
        int evenOccupiedCount = 0, oddOccupiedCount = 0;
        for (int i = 1; i <= n; i++) {
            if (inputArray[i] != 0) {
                if (i % 2 == 0) {
                    evenOccupiedCount++;
                } else {
                    oddOccupiedCount++;
                }
            }
        }

        /* ------------------------ 3. DP Setup ------------------------------ */
        // DP state description (mirrors the original 3‑dimensional array):
        //   dp[pos][usedZeros][parity] = minimum mis‑matches up to position `pos`
        //                                   when `usedZeros` zeroes have been placed,
        //                                   and the last element placed has parity `parity`
        // (0 → even, 1 → odd).
        int[][][] dp = new int[n + 1][prefixZeroCount[n] + 1][2];
        for (int[][] layer : dp) {
            for (int[] row : layer) {
                java.util.Arrays.fill(row, INF);
            }
        }

        // Initialise the first layer.
        dp[0][0][0] = 0; // starting state: no element processed, parity irrelevant

        /* ------------------------ 4. DP Transitions ----------------------- */
        for (int pos = 0; pos < n; pos++) {
            for (int usedZeros = 0; usedZeros <= prefixZeroCount[pos]; usedZeros++) {
                for (int lastParity = 0; lastParity < 2; lastParity++) {
                    int currentCost = dp[pos][usedZeros][lastParity];
                    if (currentCost == INF) {
                        continue; // unreachable state – skip
                    }

                    int nextPos = pos + 1;
                    int nextValue = inputArray[nextPos];

                    if (nextValue == 0) { // a placeholder that we must fill now
                        // Option 1: place an even number (cost = lastParity XOR 0)
                        dp[nextPos][usedZeros + 1][0] = Math.min(
                                dp[nextPos][usedZeros + 1][0],
                                currentCost + (lastParity ^ 0));

                        // Option 2: place an odd number (cost = lastParity XOR 1)
                        dp[nextPos][usedZeros][1] = Math.min(
                                dp[nextPos][usedZeros][1],
                                currentCost + (lastParity ^ 1));
                    } else { // fixed non‑zero value
                        int valueParity = nextValue % 2;
                        dp[nextPos][usedZeros][valueParity] = Math.min(
                                dp[nextPos][usedZeros][valueParity],
                                currentCost + (lastParity ^ valueParity));
                    }
                }
            }
        }

        /* ------------------------ 5. Extract Answer ----------------------- */
        // The answer is the minimum value among all DP states that reach the end
        // of the array, regardless of how many zeroes we placed.
        int answer = INF;
        for (int usedZeros = 0; usedZeros <= prefixZeroCount[n]; usedZeros++) {
            for (int parity = 0; parity < 2; parity++) {
                answer = Math.min(answer, dp[n][usedZeros][parity]);
            }
        }

        System.out.println(answer);

        // Close streams explicitly (not strictly required for System.in/out)
        out.close();
    }
}

import java.io.*;
import java.util.Arrays;

/**
 * Main class – entry point of the program.
 * Reads from standard input, solves the garland problem and prints the result.
 */
public class Main {

    /** A value larger than any possible answer – used to initialise DP cells. */
    private static final int INF = Integer.MAX_VALUE / 4;

    public static void main(String[] args) throws IOException {
        // Using try‑with‑resources guarantees that streams are closed properly.
        try (InputStream in = System.in;
             OutputStream out = System.out) {

            InputReader reader = new InputReader(in);
            PrintWriter writer = new PrintWriter(out, true);

            new GarlandSolver().solve(reader, writer);
        }
    }

    /**
     * Solution for a single test case.
     * The method parses the input, runs a dynamic‑programming algorithm and writes the answer.
     */
    static class GarlandSolver {

        /** Solves one test case using the supplied reader and writer. */
        void solve(InputReader reader, PrintWriter out) {
            int n = reader.nextInt();                 // length of the garland
            int[] values = readValues(reader, n);     // +1‑based array, -1 marks a missing number

            // How many even and odd numbers are still required?
            int needEven = n / 2;
            int needOdd  = (n + 1) / 2;
            for (int v : values) {
                if (v != -1) {
                    if (v % 2 == 0) needEven--;
                    else              needOdd--;
                }
            }

            SolverDP dp = new SolverDP(values, needEven, needOdd);
            int answer = dp.computeMinAdjacentDiff();
            out.println(answer);
        }

        /** Reads the sequence of n integers, converting 0 to -1 (meaning “missing”). */
        private static int[] readValues(InputReader reader, int n) {
            int[] a = new int[n + 1];                 // 1‑based for easier indexing
            for (int i = 1; i <= n; i++) {
                int x = reader.nextInt();
                a[i] = (x == 0) ? -1 : x % 2;         // store parity; -1 = missing
            }
            return a;
        }
    }

    /**
     * Dynamic‑programming helper that computes the minimum number of
     * adjacent equal‑parity pairs in a completed garland.
     */
    private static class SolverDP {

        private final int[] values;          // original input (1‑based)
        private final int targetEven;        // how many even numbers we must place
        private final int targetOdd;           // how many odd numbers we must place
        private final int n;                   // length of the garland

        /** 4‑dimensional DP table: [position][usedEven][usedOdd][lastParity]. */
        private final int[][][][] dp;

        SolverDP(int[] values, int targetEven, int targetOdd) {
            this.values = values;
            this.targetEven = targetEven;
            this.targetOdd  = targetOdd;
            this.n = values.length - 1;        // ignore index 0

            // Allocate and initialise the DP table with INF.
            dp = new int[n + 1][targetEven + 1][targetOdd + 1][2];
            for (int[][][] slice : dp) {
                for (int[][] inner : slice) {
                    for (int[] cell : inner) {
                        Arrays.fill(cell, INF);
                    }
                }
            }
        }

        /** Runs the DP and returns the minimal answer. */
        int computeMinAdjacentDiff() {
            // Base case – before the first position we may consider both parities with cost 0.
            dp[0][0][0][0] = 0;
            dp[0][0][0][1] = 0;

            for (int pos = 1; pos <= n; pos++) {
                int cur = values[pos];
                for (int usedEven = 0; usedEven <= targetEven; usedEven++) {
                    for (int usedOdd = 0; usedOdd <= targetOdd; usedOdd++) {
                        for (int prevParity = 0; prevParity < 2; prevParity++) {
                            int prevCost = dp[pos - 1][usedEven][usedOdd][prevParity];
                            if (prevCost == INF) {
                                continue;
                            }

                            if (cur == -1) {                     // missing number → try both parities
                                // Place an even number
                                if (usedEven < targetEven) {
                                    int newCost = prevCost + (prevParity == 0 ? 0 : 1);
                                    dp[pos][usedEven + 1][usedOdd][0] = min(dp[pos][usedEven + 1][usedOdd][0], newCost);
                                }
                                // Place an odd number
                                if (usedOdd < targetOdd) {
                                    int newCost = prevCost + (prevParity == 1 ? 0 : 1);
                                    dp[pos][usedEven][usedOdd + 1][1] = min(dp[pos][usedEven][usedOdd + 1][1], newCost);
                                }
                            } else {                              // predetermined parity
                                int curParity = cur;
                                int newCost   = prevCost + (prevParity == curParity ? 0 : 1);
                                dp[pos][usedEven][usedOdd][curParity] = min(dp[pos][usedEven][usedOdd][curParity], newCost);
                            }
                        }
                    }
                }
            }

            // The answer is the minimum cost when all required evens and odds have been used.
            return min(dp[n][targetEven][targetOdd][0], dp[n][targetEven][targetOdd][1]);
        }

        /** Tiny helper to avoid importing static Math.min everywhere. */
        private static int min(int a, int b) {
            return Math.min(a, b);
        }
    }

    /**
     * Fast scanner that works with any {@link InputStream}.
     * It hides the low‑level byte handling from the rest of the code.
     */
    private static class InputReader {
        private final InputStream stream;
        private final byte[] buffer = new byte[1 << 10];
        private int pointer = 0, length = 0;
        private final SpaceCharFilter filter;

        InputReader(InputStream stream) {
            this.stream = stream;
        }

        /** Reads the next byte, filling the buffer when it is exhausted. */
        private int read() throws IOException {
            if (pointer >= length) {
                fill();
                if (length == -1) {
                    return -1;
                }
                pointer = 0;
            }
            return buffer[pointer++];
        }

        private void fill() throws IOException {
            length = stream.read(buffer);
        }

        /** Reads the next integer from the input. */
        int nextInt() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            int value = 0;
            while (c >= '0' && c <= '9') {
                value = value * 10 + (c - '0');
                c = read();
            }
            return value * sign;
        }

        private boolean isSpaceChar(int ch) {
            if (filter != null) {
                return filter.isSpaceChar(ch);
            }
            return ch == ' ' || ch == '\n' || ch == '\r' || ch == '\t' || ch == -1;
        }

        /** Optional filter to treat additional characters as whitespace. */
        interface SpaceCharFilter {
            boolean isSpaceChar(int ch);
        }
    }
}

import java.util.*;

public class Solution {

    /** Entry point */
    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            int n = scanner.nextInt();
            int[] values = new int[n];
            for (int i = 0; i < n; i++) {
                values[i] = scanner.nextInt();
            }

            Result result = solve(n, values);
            System.out.println(result.count);
        }
    }

    /** Holds the final answer */
    private static final class Result {
        final int count;
        Result(int count) { this.count = count; }
    }

    /** Core algorithm – refactored for clarity and maintainability */
    private static Result solve(int n, int[] values) {
        // --------------------------------------------------------------------
        // 1. Collect indices of non‑zero elements and the set of present numbers
        // --------------------------------------------------------------------
        List<Integer> nonZeroIndices = new ArrayList<>();
        Set<Integer> present = new HashSet<>();
        for (int i = 0; i < n; i++) {
            if (values[i] != 0) {
                nonZeroIndices.add(i);
                present.add(values[i]);
            }
        }

        // All elements are zero → special case
        if (nonZeroIndices.isEmpty()) {
            return new Result(n == 1 ? 0 : 1);
        }

        // --------------------------------------------------------------------
        // 2. Count missing numbers and separate them by parity
        // --------------------------------------------------------------------
        int missingEven = 0;
        int missingOdd = 0;
        for (int i = 1; i <= n; i++) {
            if (!present.contains(i)) {
                if (i % 2 == 0) {
                    missingEven++;
                } else {
                    missingOdd++;
                }
            }
        }

        // --------------------------------------------------------------------
        // 3. Analyse gaps between consecutive non‑zero entries
        // --------------------------------------------------------------------
        List<Integer> evenGaps = new ArrayList<>();
        List<Integer> oddGaps = new ArrayList<>();
        int parityChangeCount = 0;   // number of parity switches between neighbours

        for (int i = 1; i < nonZeroIndices.size(); i++) {
            int curIdx = nonZeroIndices.get(i);
            int prevIdx = nonZeroIndices.get(i - 1);

            if (values[curIdx] % 2 == values[prevIdx] % 2) {
                int gap = curIdx - prevIdx - 1;
                if (values[curIdx] % 2 == 0) {
                    evenGaps.add(gap);
                } else {
                    oddGaps.add(gap);
                }
            } else {
                parityChangeCount++;
            }
        }

        // --------------------------------------------------------------------
        // 4. Consume the gaps using the remaining budgets (adds 2 per gap that
        //    cannot be fully satisfied)
        // --------------------------------------------------------------------
        int count = parityChangeCount;

        Collections.sort(evenGaps);
        for (int gap : evenGaps) {
            if (missingEven >= gap) {
                missingEven -= gap;
            } else {
                count += 2;
            }
        }

        Collections.sort(oddGaps);
        for (int gap : oddGaps) {
            if (missingOdd >= gap) {
                missingOdd -= gap;
            } else {
                count += 2;
            }
        }

        // --------------------------------------------------------------------
        // 5. Handle the prefix gap (before the first non‑zero element)
        // --------------------------------------------------------------------
        int firstIdx = nonZeroIndices.get(0);
        int prefixDist = firstIdx;
        if (values[firstIdx] % 2 == 0) {
            if (missingEven >= prefixDist) {
                missingEven -= prefixDist;
            } else {
                count += 1;
            }
        } else {
            if (missingOdd >= prefixDist) {
                missingOdd -= prefixDist;
            } else {
                count += 1;
            }
        }

        // --------------------------------------------------------------------
        // 6. Handle the suffix gap (after the last non‑zero element)
        // --------------------------------------------------------------------
        int lastIdx = nonZeroIndices.get(nonZeroIndices.size() - 1);
        int suffixDist = n - 1 - lastIdx;
        if (values[lastIdx] % 2 == 0) {
            if (missingEven >= suffixDist) {
                missingEven -= suffixDist;
            } else {
                count += 1;
            }
        } else {
            if (missingOdd >= suffixDist) {
                missingOdd -= suffixDist;
            } else {
                count += 1;
            }
        }

        return new Result(count);
    }
}

// Refactored version of the original program.
// The code has been reorganised for readability, maintainability and correctness.
// All functionality is preserved.

import java.io.*;
import java.util.*;

public class Main {

    /** Program entry point. */
    public static void main(String[] args) {
        // Use try‑with‑resources to guarantee stream closure.
        try (InputStream in = System.in;
             PrintWriter out = new PrintWriter(System.out, true)) {

            new Solver().solve(in, out);
        }
    }

    /** -----------------------------------------------------------------------
     *  Core logic of the problem.
     *
     *  The Solver class encapsulates all state that belongs to a single test case.
     *  ----------------------------------------------------------------------- */
    static class Solver {

        /** Original sequence (0 denotes a missing value). */
        private final int[] sequence;

        /** DP memoisation table:
         *   dp[index][remainingEven][remainingOdd][lastParity]
         */
        private final int[][][][] dp;

        /** Number of missing even and odd numbers that still have to be placed. */
        private final int missingEven;
        private final int missingOdd;

        /** Constructor – prepares the DP table with the supplied data. */
        Solver(int[] sequence, int missingEven, int missingOdd) {
            this.sequence = sequence;
            this.missingEven = missingEven;
            this.missingOdd = missingOdd;
            // initialise with -1 (unvisited)
            this.dp = new int[sequence.length][missingEven + 1][missingOdd + 1][2];
            Arrays.fill(dp, -1);
        }

        /** --------------------------------------------------------------------
         *  Recursive DP that returns the minimum number of adjacent parity changes.
         *  ----------------------------------------------------------------- */
        private int solve(int idx, int evensLeft, int oddsLeft, int lastParity) {
            // Base case – processed the whole sequence.
            if (idx == sequence.length) {
                return 0;
            }

            // If the state has already been computed, return the cached result.
            if (dp[idx][evensLeft][oddsLeft][lastParity] != -1) {
                return dp[idx][evensLeft][oddsLeft][lastParity];
            }

            int currentValue = sequence[idx];

            // ------------------------------------------------------------------
            // Fixed (non‑zero) element – its parity is determined by its value.
            // ------------------------------------------------------------------
            if (currentValue != 0) {
                int curParity = currentValue & 1;               // 0 = even, 1 = odd
                int cost = (lastParity != curParity) ? 1 : 0;   // cost of transition
                int result = solve(idx + 1, evensLeft, oddsLeft, curParity) + cost;
                return dp[idx][evensLeft][oddsLeft][lastParity] = result;
            }

            // ------------------------------------------------------------------
            // Missing element – we may place an even or an odd number if any are left.
            // ------------------------------------------------------------------
            int best = Integer.MAX_VALUE;

            // Try to place an even number.
            if (evensLeft > 0) {
                int cost = (lastParity != 0) ? 1 : 0;
                int result = solve(idx + 1, evensLeft - 1, oddsLeft, 0) + cost;
                best = Math.min(best, result);
            }

            // Try to place an odd number.
            if (oddsLeft > 0) {
                int cost = (lastParity != 1) ? 1 : 0;
                int result = solve(idx + 1, evensLeft, oddsLeft - 1, 1) + cost;
                best = Math.min(best, result);
            }

            // Memoise and return the best choice.
            return dp[idx][evensLeft][oddsLeft][lastParity] = best;
        }

        /** --------------------------------------------------------------------
         *  Public entry point invoked from Main.
         *  ----------------------------------------------------------------- */
        void solve(InputStream source, PrintWriter out) {
            InputReader reader = new InputReader(source);

            int n = reader.readInt();                     // length of the sequence
            int[] g = reader.readIntArray(n);             // the sequence itself

            // ------------------------------------------------------------------
            // Determine which numbers from 1..n are missing and split them by parity.
            // ------------------------------------------------------------------
            boolean[] present = new boolean[n + 1];
            for (int v : g) {
                if (v != 0) {
                    present[v] = true;
                }
            }

            int missingEven = 0;
            int missingOdd = 0;
            for (int i = 1; i <= n; i++) {
                if (!present[i]) {
                    if ((i & 1) == 0) {
                        missingEven++;
                    } else {
                        missingOdd++;
                    }
                }
            }

            // Create a fresh Solver instance that owns the DP table.
            Solver solver = new Solver(g, missingEven, missingOdd);

            // The original implementation examined both possible “previous parity”
            // values (0 and 1) and took the minimum result.
            int answer = Math.min(
                    solver.solve(0, missingEven, missingOdd, 0),
                    solver.solve(0, missingEven, missingOdd, 1)
            );

            out.println(answer);
        }
    }

    /** -----------------------------------------------------------------------
     *  Very small wrapper around InputStream that reads ints efficiently.
     *  ----------------------------------------------------------------------- */
    private static class InputReader {
        private final InputStream stream;
        private final byte[] buffer = new byte[16_384];
        private int bytesRead = 0;
        private int pos = 0;

        InputReader(InputStream stream) {
            this.stream = new BufferedInputStream(stream);
        }

        /** Skip whitespace characters and return the next byte. */
        private int skipWhitespace() throws IOException {
            int b;
            do {
                b = readByte();
            } while (b != -1 && (b == ' ' || b == '\n' || b == '\r' || b == '\t'));
            return b;
        }

        /** Read the next byte from the underlying buffer. */
        private int readByte() throws IOException {
            if (pos >= bytesRead) {
                pos = 0;
                bytesRead = stream.read(buffer);
                if (bytesRead <= 0) {
                    return -1;
                }
            }
            return buffer[pos++];
        }

        /** Read a signed integer from the input stream. */
        int readInt() throws IOException {
            int c = skipWhitespace();
            if (c == -1) {
                throw new EOFException();
            }
            boolean negative = false;
            if (c == '-') {
                negative = true;
                c = readByte();
            }
            int result = 0;
            while (c >= '0' && c <= '9') {
                result = result * 10 + (c - '0');
                c = readByte();
            }
            return negative ? -result : result;
        }

        /** Read an int array of the given size. */
        int[] readIntArray(int size) throws IOException {
            int[] a = new int[size];
            for (int i = 0; i < size; i++) {
                a[i] = readInt();
            }
            return a;
        }
    }
}

import java.io.*;
import java.util.*;

public class ACMIND {

    private static final long MOD = 998_244_353L;
    private static final long INF = 1_000_000_000_000_000_000L;

    private static FastScanner scanner;
    private static PrintWriter out;
    private static int[] ARR;
    private static int N;

    private static int[][][][] DP; // [idx][evenRem][oddRem][prevParity]

    public static void main(String[] args) throws IOException {
        new Thread(() -> {
            try {
                solve();
            } catch (Exception e) {
                e.printStackTrace();
                System.exit(1);
            }
        }, "BaZ", 1 << 27).start();
    }

    private static void solve() throws IOException {
        scanner = new FastScanner();
        out = new PrintWriter(System.out, true);

        N = scanner.nextInt();
        ARR = new int[N];
        int evenRemaining = (N + 1) / 2; // max evens that could be placed
        int oddRemaining = N / 2;        // max odds that could be placed

        for (int i = 0; i < N; i++) {
            ARR[i] = scanner.nextInt();
            if (ARR[i] != 0) {
                if (ARR[i] % 2 == 0) {
                    evenRemaining--;
                } else {
                    oddRemaining--;
                }
            }
        }

        // initialise DP table with -1 (uncomputed)
        DP = new int[N + 1][evenRemaining + 1][oddRemaining + 1][2];
        for (int i = 0; i <= N; i++) {
            for (int e = 0; e <= evenRemaining; e++) {
                for (int o = 0; o <= oddRemaining; o++) {
                    Arrays.fill(DP[i][e][o], -1);
                }
            }
        }

        int answer = compute(0, evenRemaining, oddRemaining, 0);
        out.flush();
        out.close();
    }

    /** Returns the minimal number of parity changes needed from position idx onward */
    private static int compute(int idx, int evenRem, int oddRem, int prevParity) {
        if (idx == N) {
            return 0;
        }
        if (DP[idx][evenRem][oddRem][prevParity] != -1) {
            return DP[idx][evenRem][oddRem][prevParity];
        }

        int cur = ARR[idx];
        if (cur != 0) { // fixed number
            int curParity = cur % 2;
            int cost = (idx > 0 && curParity != prevParity) ? 1 : 0;
            int result = compute(idx + 1, evenRem, oddRem, curParity) + cost;
            DP[idx][evenRem][oddRem][prevParity] = result;
            return result;
        }

        int best = Integer.MAX_VALUE;

        if (evenRem > 0) {
            int cost = (idx > 0) ? 0 : 0; // no extra cost for the first placement
            best = Math.min(best,
                    compute(idx + 1, evenRem - 1, oddRem, 0) + cost);
        }
        if (oddRem > 0) {
            int cost = (idx > 0) ? 1 : 0; // cost if previous parity was even
            best = Math.min(best,
                    compute(idx + 1, evenRem, oddRem - 1, 1) + cost);
        }

        DP[idx][evenRem][oddRem][prevParity] = best;
        return best;
    }

    /** Simple fast scanner for competitive‑programming style input */
    private static class FastScanner {
        private final DataInputStream din;
        private final byte[] buffer;
        private int bufferPointer, bytesRead;

        FastScanner() throws IOException {
            din = new DataInputStream(System.in);
            buffer = new byte[1 << 16];
            bufferPointer = bytesRead = 0;
        }

        FastScanner(String fileName) throws IOException {
            din = new DataInputStream(new FileInputStream(fileName));
            buffer = new byte[1 << 16];
            bufferPointer = bytesRead = 0;
        }

        private byte read() throws IOException {
            if (bufferPointer == bytesRead) {
                fillBuffer();
            }
            return buffer[bufferPointer++];
        }

        private void fillBuffer() throws IOException {
            bytesRead = din.read(buffer, 0, buffer.length);
            bufferPointer = 0;
            if (bytesRead == -1) {
                buffer[0] = -1;
            }
        }

        int nextInt() throws IOException {
            int ret = 0;
            byte c = read();
            while (c <= ' ') c = read();
            boolean neg = (c == '-');
            if (neg) c = read();
            do {
                ret = ret * 10 + (c - '0');
            } while ((c = read()) >= '0' && c <= '9');
            if (neg) ret = -ret;
            return ret;
        }
    }
}

import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Scanner;

/**
 * Computes the minimum sum of absolute differences between adjacent elements
 * after filling all “unfixed” positions (marked with 0) with either an odd or an
 * even number. The number of odd and even values to use is given by the input
 * size {@code n}.
 *
 * The algorithm uses memoised depth‑first search (DFS) to avoid the huge
 * 4‑dimensional DP array of the original implementation.
 */
public class Main {

    /** Entry point of the program. */
    public static void main(String[] args) {
        try (Scanner sc = new Scanner(System.in)) {
            int n = sc.nextInt();

            // read the sequence, convert each number to its parity class:
            //   0 → unfixed,
            //   1 → odd,
            //   2 → even
            List<Integer> sequence = readSequence(sc, n);
            int oddCount = (n + 1) / 2;   // total odd numbers in 1..n
            int evenCount = n / 2;        // total even numbers in 1..n

            // start the recursive search from the first position, with no previous
            // element (state = 0, which simply means “no parity yet”)
            int answer = computeMinCost(sequence, oddCount, evenCount);

            System.out.println(answer);
        }
    }

    /**
     * Reads {@code n} integers from {@code scanner} and converts them to the
     * parity representation used by the algorithm (0, 1, or 2).
     */
    private static List<Integer> readSequence(Scanner scanner, int n) {
        List<Integer> list = new java.util.ArrayList<>(n);
        int oddLeft = (n + 1) / 2;
        int evenLeft = n / 2;

        for (int i = 0; i < n; ++i) {
            int value = scanner.nextInt();
            if (value == 0) {
                list.add(0);                       // unfixed
            } else if (value % 2 == 1) {
                --oddLeft;                         // consume an odd slot
                list.add(1);                       // represents an odd number
            } else {
                --evenLeft;                        // consume an even slot
                list.add(2);                       // represents an even number
            }
        }
        // (oddLeft and evenLeft are not used further – they were only needed for
        // counting how many odd/even numbers are still available.)
        return list;
    }

    /**
     * Public entry point for the recursive DFS with memoisation.
     *
     * @param seq        the sequence of parity classes (0 = unfixed)
     * @param oddLeft    how many odd numbers are still unused
     * @param evenLeft   how many even numbers are still unused
     * @return minimum possible sum of absolute differences
     */
    private static int computeMinCost(List<Integer> seq,
                                      int oddLeft,
                                      int evenLeft) {
        // memoisation map: key = {position, oddLeft, evenLeft, previousParity}
        Map<StateKey, Integer> memo = new HashMap<>();
        return dfs(seq, 0, oddLeft, evenLeft, 0, memo);
    }

    /**
     * Depth‑first search that tries to fill every unfixed slot with either an
     * odd or an even number while accumulating the cost contributed by each
     * newly created adjacent pair.
     *
     * @param seq        original sequence (will not be mutated)
     * @param pos        current index we are filling (0‑based)
     * @param oddLeft    remaining odd numbers
     * @param evenLeft   remaining even numbers
     * @param prevParity parity code (0,1,2) of the element immediately to the
     *                   left of {@code pos}; {@code 0} means “no previous”.
     * @param memo       memoisation map
     * @return minimum cost from position {@code pos} onward
     */
    private static int dfs(List<Integer> seq,
                           int pos,
                           int oddLeft,
                           int evenLeft,
                           int prevParity,
                           Map<StateKey, Integer> memo) {
        if (pos == seq.size()) {
            // all positions have been processed
            return 0;
        }

        // Build a unique key for memoisation
        StateKey key = new StateKey(pos, oddLeft, evenLeft, prevParity);
        Integer cached = memo.get(key);
        if (cached != null) {
            return cached;
        }

        int current = seq.get(pos);
        int cost = 0;

        if (current == 0) {
            // -------- try placing an odd number ----------
            int costOdd = Integer.MAX_VALUE;
            if (oddLeft > 0) {
                int placedValue = 1;                     // symbol for odd
                costOdd = dfs(seq, pos + 1,
                              oddLeft - 1,
                              evenLeft,
                              placedValue,
                              memo);
                if (pos > 0) {
                    costOdd += Math.abs(seq.get(pos - 1) - placedValue);
                }
            }

            // -------- try placing an even number ----------
            int costEven = Integer.MAX_VALUE;
            if (evenLeft > 0) {
                int placedValue = 2;                     // symbol for even
                costEven = dfs(seq, pos + 1,
                               oddLeft,
                               evenLeft - 1,
                               placedValue,
                               memo);
                if (pos > 0) {
                    costEven += Math.abs(seq.get(pos - 1) - placedValue);
                }
            }

            // Choose the cheaper of the two (if both are reachable)
            cost = Math.min(costOdd, costEven);
        } else {
            // The current position is already fixed (odd = 1, even = 2)
            int placedValue = current;
            cost = dfs(seq, pos + 1,
                       oddLeft,
                       evenLeft,
                       placedValue,
                       memo);
            if (pos > 0) {
                cost += Math.abs(seq.get(pos - 1) - placedValue);
            }
        }

        memo.put(key, cost);
        return cost;
    }

    /**
     * Immutable holder for the DFS state used as a key in the memoisation map.
     */
    private static final class StateKey {
        private final int position;
        private final int oddLeft;
        private final int evenLeft;
        private final int prevParity;

        StateKey(int position, int oddLeft, int evenLeft, int prevParity) {
            this.position = position;
            this.oddLeft = oddLeft;
            this.evenLeft = evenLeft;
            this.prevParity = prevParity;
        }

        @Override
        public boolean equals(Object o) {
            if (this == o) return true;
            if (!(o instanceof StateKey)) return false;
            StateKey that = (StateKey) o;
            return position == that.position &&
                   oddLeft == that.oddLeft &&
                   evenLeft == that.evenLeft &&
                   prevParity == that.prevParity;
        }

        @Override
        public int hashCode() {
            return java.util.Objects.hash(position, oddLeft, evenLeft, prevParity);
        }
    }
}

import java.io.*;
import java.util.Arrays;

/**
 * Solves the problem described in the original source code.
 *
 * The program reads several test cases. For each test case it receives an
 * array that may contain zeros (treated as “empty” cells). Each filled cell
 * holds either an odd or even number. The task is to fill the empty cells
 * with either odd or even numbers so that the number of adjacent cells
 * with different parity is minimised. The answer for each test case is
 * printed on its own line.
 *
 * The implementation follows the same algorithm as the original program
 * but with clear naming, reduced duplication and proper encapsulation.
 */
public class Solution {

    /* --------------------------------------------------------------
       1️⃣  Fast input utilities
       -------------------------------------------------------------- */
    /** Simple fast scanner used throughout the program. */
    private static final class FastScanner {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        FastScanner(InputStream in) {
            this.reader = new BufferedReader(new InputStreamReader(in));
        }

        /** Returns the next token from the input stream. */
        String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new UncheckedIOException(e);
                }
            }
            return tokenizer.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }
    }

    /* --------------------------------------------------------------
       2️⃣  DP memoisation container
       -------------------------------------------------------------- */
    /** Holds the DP table and provides convenient accessors. */
    private static final class Memo {
        /** dp[i][e][o][p] – minimal cost starting at position i,
         *   with e even numbers and o odd numbers still to place,
         *   where p is the parity of the previously placed element (0‑even, 1‑odd). */
        private final int[][][][] dp;

        Memo(int n) {
            // dimensions: i (0..n), e (0..n), o (0..n), p (0,1)
            dp = new int[n][n + 1][n + 1][2];
            fill(-1);
        }

        private void fill(int value) {
            for (int i = 0; i < dp.length; i++) {
                for (int e = 0; e < dp[i].length; e++) {
                    for (int o = 0; o < dp[i][e].length; o++) {
                        Arrays.fill(dp[i][e][o], value);
                    }
                }
            }
        }

        int get(int i, int e, int o, int p) {
            return dp[i][e][o][p];
        }

        void set(int i, int e, int o, int p, int value) {
            dp[i][e][o][p] = value;
        }
    }

    /* --------------------------------------------------------------
       3️⃣  Core algorithm
       -------------------------------------------------------------- */
    private static final int INF = (int) 1e9;   // a value larger than any possible answer

    /**
     * Recursive depth‑first search with memoisation.
     *
     * @param pos        current index in the array
     * @param evenLeft   how many even numbers are still available
     * @param oddLeft    how many odd numbers are still available
     * @param prevParity parity of the previously placed element (0 – even, 1 – odd)
     * @param arr        original array (with -1 representing an empty cell)
     * @param memo       memoisation object
     * @return minimal additional cost needed to finish the sequence
     */
    private static int dfs(int pos, int evenLeft, int oddLeft, int prevParity,
                           int[] arr, Memo memo) {
        if (pos == arr.length) {
            return 0; // nothing left to place
        }

        int cached = memo.get(pos, evenLeft, oddLeft, prevParity);
        if (cached != -1) {
            return cached;
        }

        // -----------------------------------------------------------------
        // 1️⃣  Cell is already fixed – we have no choice
        // -----------------------------------------------------------------
        if (arr[pos] != -1) {
            int cur = arr[pos];                     // already placed parity (0 or 1)
            int transitionCost = (cur != prevParity) ? 1 : 0;
            int result = transitionCost + dfs(pos + 1, evenLeft, oddLeft, cur, arr, memo);
            memo.set(pos, evenLeft, oddLeft, prevParity, result);
            return result;
        }

        // -----------------------------------------------------------------
        // 2️⃣  Try placing an even number (if any are left)
        // -----------------------------------------------------------------
        int best = INF;
        if (evenLeft > 0) {
            // placing an even number changes parity to 0
            int cost = (prevParity == 1) ? 1 : 0;   // transition from previous parity to even
            int candidate = cost + dfs(pos + 1, evenLeft - 1, oddLeft, 0, arr, memo);
            best = Math.min(best, candidate);
        }

        // -----------------------------------------------------------------
        // 3️⃣  Try placing an odd number (if any are left)
        // -----------------------------------------------------------------
        if (oddLeft > 0) {
            // placing an odd number changes parity to 1
            int cost = (prevParity == 0) ? 1 : 0;   // transition from previous parity to odd
            int candidate = cost + dfs(pos + 1, evenLeft, oddLeft - 1, 1, arr, memo);
            best = Math.min(best, candidate);
        }

        memo.set(pos, evenLeft, oddLeft, prevParity, best);
        return best;
    }

    /* --------------------------------------------------------------
       4️⃣  Driver code
       -------------------------------------------------------------- */
    public static void main(String[] args) throws IOException {
        FastScanner fs = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)));

        int testCases = fs.nextInt();               // the original code used `while(t--!=0)`
        while (testCases-- > 0) {
            solveOneCase(fs, out);
        }

        out.close();
    }

    /**
     * Handles a single test case: reads input, runs the DP and prints the answer.
     */
    private static void solveOneCase(FastScanner fs, PrintWriter out) {
        int n = fs.nextInt();
        int[] arr = new int[n];

        // Count how many odd/even numbers are still needed.
        int oddNeeded = (n + 1) / 2;   // total odd positions in a 0‑indexed length‑n array
        int evenNeeded = n / 2;        // total even positions

        for (int i = 0; i < n; i++) {
            int val = fs.nextInt();
            if (val == 0) {
                arr[i] = -1;                 // mark empty cell
            } else {
                // keep only the parity bit; any non‑zero number is reduced to 0 (even) or 1 (odd)
                int parity = val & 1;
                arr[i] = parity;
                if (parity == 1) {
                    oddNeeded--;
                } else {
                    evenNeeded--;
                }
            }
        }

        // Trivial single‑element case – no changes are required.
        if (n == 1) {
            out.println(0);
            return;
        }

        Memo memo = new Memo(n);
        int answer = Math.min(
                dfs(0, evenNeeded, oddNeeded, 0, arr, memo),
                dfs(0, evenNeeded, oddNeeded, 1, arr, memo));

        out.println(answer);
    }
}

import java.io.*;
import java.util.Arrays;

/**
 * Entry point of the application.
 * Starts a background thread that solves the “Garland” problem using fast I/O.
 */
public class Main {
    public static void main(String[] args) throws Exception {
        // Run the solver in a dedicated thread with a generous stack size.
        new Thread(
                null,
                () -> {
                    try {
                        new GarlandProcessor().process();
                    } catch (IOException e) {
                        throw new UncheckedIOException(e);
                    }
                },
                "GarlandWorker",
                1 << 27) // 128 MiB stack – enough for the recursion‑free DP solution
                .start();
    }
}

/**
 * Encapsulates the core algorithm for the Garland problem.
 * The public {@link #process()} method contains all steps: parsing, solving,
 * and printing the result.
 */
final class GarlandProcessor implements AutoCloseable {

    /** Number of items of each parity that must be placed. */
    private static final int HALF = 2;   // constant used only for readability

    /** Fast input helper – reads bytes directly from an underlying stream. */
    private final FastReader reader;

    /** Fast output helper – buffers text before writing it to a writer. */
    private final FastWriter writer;

    GarlandProcessor(InputStream input, OutputStream output) {
        this.reader = new FastReader(input);
        this.writer = new FastWriter(output);
    }

    /** Public contract – performs the whole computation. */
    public void process() throws IOException {
        int n = reader.readInt();                         // size of the sequence
        int[] required = {n / 2, n - n / 2};              // required count per parity

        // Count how many positions are already fixed (odd/even) and how many are free.
        int[] fixedParityCount = new int[2];
        for (int i = 0; i < n; i++) {
            int value = reader.readInt();
            if (value != 0) {
                fixedParityCount[(value - 1) % 2]++;      // 0‑based parity index
            }
        }

        // DP state: dp[idx][fixedUsed][parity] = minimal switches up to index 'idx'
        // where 'fixedUsed' positions of the required parity have been placed,
        // and the current parity (0 = even, 1 = odd) is placed at position 'idx'.
        int[][][] dp = new int[n + 1][required[0] + 1][2];
        fillLargeArray(dp, Integer.MAX_VALUE / 2);       // avoid overflow when minimizing
        dp[0][0][0] = dp[0][0][1] = 0;                      // start state

        for (int idx = 1; idx <= n; idx++) {
            int value = reader.readValue();               // 0 means "unfilled"
            for (int used = 0; used <= required[0]; used++) {
                for (int parity = 0; parity < 2; parity++) {
                    if (value != 0) {
                        // Fixed value – it must match the expected parity at this step.
                        if ((value % 2) != parity) {
                            continue;
                        }
                        dp[idx][used][parity] = Math.min(
                                dp[idx][used][parity],
                                Math.min(dp[idx - 1][used][parity],
                                        dp[idx - 1][used][1 - parity] + 1));
                    } else if (used < required[0]) {
                        // Place a yet‑unused even number (parity == 0)
                        int cost = (parity == 0) ? 0 : 1;
                        dp[idx][used][parity] = Math.min(
                                dp[idx][used][parity],
                                dp[idx - 1][used][parity] + cost);
                        // Place a yet‑unused odd number (parity == 1)
                        dp[idx][used][parity] = Math.min(
                                dp[idx][used][parity],
                                dp[idx - 1][used][1 - parity] + 1);
                    }

                    // Carry forward the best cost from the previous column irrespective
                    // of how we filled the current cell.
                    dp[idx][used][parity] = Math.min(
                            dp[idx][used][parity],
                            dp[idx - 1][used][parity]);
                }
            }
        }

        // The answer is the minimum switches needed when all required‑parity slots are filled.
        int answer = Math.min(dp[n][required[0]][0], dp[n][required[0]][1]);
        writer.println(answer).flush();
    }

    /* -------------------------------------------------------------------------
     *  Helper utilities (fast I/O)
     * ------------------------------------------------------------------------- */

    /** Simple buffered integer reader. */
    private static final class FastReader {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 13];
        private int bufferLen = 0, bufferPos = 0;

        FastReader(InputStream in) { this.in = in; }

        /** Skips whitespace characters. */
        private void skipWhitespace() {
            while (true) {
                int read = readByte();
                if (read == -1 || read > 32) {
                    return;
                }
            }
        }

        /** Reads a single byte (or -1 on EOF). */
        private int readByte() {
            if (bufferPos >= bufferLen) {
                bufferPos = 0;
                bufferLen = in.read(buffer);
                if (bufferLen <= 0) {
                    return -1;
                }
            }
            return buffer[bufferPos++];
        }

        /** Reads an integer (supports leading + / -). */
        int readInt() {
            skipWhitespace();
            int sign = 1;
            if (readByte() == '-') {
                sign = -1;
                readByte(); // consume sign character
            } else if (readByte() == '+') {
                readByte(); // consume sign character
            }

            int value = 0;
            while (true) {
                int cur = readByte();
                if (cur < '0' || cur > '9') {
                    break;
                }
                value = value * 10 + (cur - '0');
            }
            return sign * value;
        }

        /** Convenience method – reads the next token as an integer. */
        int readValue() {
            // The same logic as readInt() but without the sign handling – used internally.
            skipWhitespace();
            while (true) {
                int cur = readByte();
                if (cur >= '0' && cur <= '9') {
                    break;
                }
            }
            int value = 0;
            while (true) {
                int cur = readByte();
                if (cur < '0' || cur > '9') {
                    break;
                }
                value = value * 10 + (cur - '0');
            }
            return value;
        }
    }

    /** Buffered writer that prefixes each integer with a line‑break. */
    private static final class FastWriter implements AutoCloseable {
        private final StringBuilder buffer = new StringBuilder(1 << 20);
        private final Writer out;

        FastWriter(OutputStream stream) { this.out = new BufferedWriter(new OutputStreamWriter(stream)); }

        /** Appends an integer followed by a newline. */
        FastWriter println(int value) {
            buffer.append(value).append('\n');
            return this;
        }

        /** Flushes the buffer to the underlying stream and resets it. */
        public void flush() {
            try {
                out.append(buffer);
                out.flush();
                buffer.setLength(0);
            } catch (IOException e) {
                throw new UncheckedIOException(e);
            }
        }

        /** Closes the underlying writer (flushes first). */
        @Override
        public void close() {
            flush();
            try { out.close(); } catch (IOException e) { throw new UncheckedIOException(e); }
        }
    }

    /** Utility to fill a multidimensional array with a sentinel value. */
    private static void fillLargeArray(int[][][] target, int value) {
        for (int[][] layer : target) {
            for (int[] row : layer) {
                Arrays.fill(row, value);
            }
        }
    }
}

package solution;

import java.io.*;
import java.nio.charset.StandardCharsets;
import java.util.*;
import java.util.stream.*;

/**
 * Entry point of the program. Reads input, solves the garland problem,
 * and prints the result.
 */
public class Main {

    /** Program entry point. */
    public static void main(String[] args) {
        solve(System.in, System.out);
    }

    /**
     * Solves the problem for the given input and writes the answer to the
     * provided output stream.
     *
     * @param in  character stream that supplies the input data
     * @param out character stream to which the answer is written
     */
    private static void solve(InputStream in, OutputStream out) {
        try (Reader reader = new BufferedReader(
                new InputStreamReader(in, StandardCharsets.UTF_8));
             Writer writer = new BufferedWriter(
                new OutputStreamWriter(out, StandardCharsets.UTF_8))) {

            InputScanner scanner = new InputScanner(reader);
            OutputPrinter printer = new OutputPrinter(writer);

            new GarlandSolver().solve(scanner, printer);

            printer.flush();
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
    }

    /** Simple tokeniser that reads integers from a character stream. */
    private static final class InputScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        InputScanner(BufferedReader br) {
            this.br = br;
        }

        /** Returns the next token from the underlying stream. */
        private String nextToken() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) {
                        return null;
                    }
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new UncheckedIOException(e);
                }
            }
            return st.nextToken();
        }

        /** Reads a single integer token. */
        int nextInt() {
            return Integer.parseInt(nextToken());
        }

        /** Reads {@code length} consecutive integers. */
        int[] nextInts(int length) {
            return IntStream.range(0, length)
                    .map(i -> nextInt())
                    .toArray();
        }
    }

    /** Stream that writes formatted answers. */
    private static final class OutputPrinter implements AutoCloseable {
        private final BufferedWriter bw;
        private boolean broke = true;   // true when the previous output ended a token

        OutputPrinter(BufferedWriter bw) {
            this.bw = bw;
        }

        /** Writes a single character. */
        OutputPrinter print(char c) {
            try {
                bw.write(c);
                broke = false;
            } catch (IOException e) {
                throw new UncheckedIOException(e);
            }
            return this;
        }

        /** Writes a string without a trailing newline. */
        OutputPrinter print(String s) {
            try {
                bw.write(s);
                broke = false;
            } catch (IOException e) {
                throw new UncheckedIOException(e);
            }
            return this;
        }

        /** Writes an integer value (adds a preceding space if needed). */
        OutputPrinter ans(int value) {
            if (!broke) print(' ');
            return print(Integer.toString(value));
        }

        /** Writes a newline character and marks the token as finished. */
        OutputPrinter ln() {
            print(System.lineSeparator());
            broke = true;
            return this;
        }

        @Override
        public void close() {
            try {
                bw.flush();
            } catch (IOException e) {
                throw new UncheckedIOException(e);
            }
        }
    }

    /** Encapsulates the dynamic‑programming solution for the garland problem. */
    private static final class GarlandSolver {

        /** Number of colours (kept for API compatibility). */
        private static final int COLOUR_COUNT = 100;

        /**
         * Executes the solution.
         *
         * @param scanner tokeniser that provides the input data
         * @param printer stream to which the answer is written
         */
        void solve(InputScanner scanner, OutputPrinter printer) {
            int n = scanner.nextInt();
            int[] values = scanner.nextInts(n);

            // -----------------------------------------------------------------
            // 1. Identify which numbers are already present.
            // -----------------------------------------------------------------
            boolean[] present = new boolean[n];
            for (int v : values) {
                if (v != 0) {
                    present[v - 1] = true;
                }
            }

            // -----------------------------------------------------------------
            // 2. Count missing numbers that must be placed on even / odd indices.
            // -----------------------------------------------------------------
            int missingEvens = 0;   // missing numbers that will be placed on even indices
            int missingOdds  = 0;   // missing numbers that will be placed on odd indices

            for (int i = 0; i < n; i++) {
                if (!present[i]) {
                    if (i % 2 == 0) {
                        missingOdds++;   // index i is even → odd‑valued number will fill it later
                    } else {
                        missingEvens++;  // index i is odd  → even‑valued number will fill it later
                    }
                }
            }

            // -----------------------------------------------------------------
            // 3. DP initialisation.
            // dp[parity][pos][eCnt][oCnt] = minimal number of adjacent colour changes
            //                               after processing first {@code pos} cells,
            //                               having placed {@code eCnt} even numbers
            //                               and {@code oCnt} odd numbers.
            // -----------------------------------------------------------------
            int[][][][] dp = new int[2][n + 1][n + 1][n + 1];
            fill(dp, Integer.MAX_VALUE / 2);   // a value that will never be chosen as a minimum

            dp[0][0][0][0] = dp[1][0][0][0] = 0;    // start state

            // -----------------------------------------------------------------
            // 4. Transition over the positions.
            // -----------------------------------------------------------------
            for (int pos = 0; pos < n; pos++) {
                if (values[pos] == 0) {
                    // ---- Place an even‑valued missing number -----------------
                    for (int odd = 0; odd <= n; odd++) {
                        for (int even = 0; even < missingEvens; even++) {
                            int costFromPrev = Math.min(
                                    dp[0][pos][even][odd],
                                    dp[1][pos][even][odd] + 1);   // change of parity costs 1
                            dp[0][pos + 1][even + 1][odd] = Math.min(
                                    dp[0][pos + 1][even + 1][odd],
                                    costFromPrev);
                        }
                    }

                    // ---- Place an odd‑valued missing number ------------------
                    for (int odd = 0; odd < missingOdds; odd++) {
                        for (int even = 0; even <= n; even++) {
                            int costFromPrev = Math.min(
                                    dp[0][pos][even][odd],
                                    dp[1][pos][even][odd] + 1);
                            dp[1][pos + 1][even][odd + 1] = Math.min(
                                    dp[1][pos + 1][even][odd + 1],
                                    costFromPrev);
                        }
                    }
                } else {
                    // Fixed (non‑zero) value – only need to propagate the best cost.
                    int curParity = values[pos] % 2;
                    for (int odd = 0; odd <= n; odd++) {
                        for (int even = 0; even <= n; even++) {
                            int bestPrev = Math.min(dp[0][pos][even][odd], dp[1][pos][even][odd] + 1);
                            dp[curParity][pos + 1][even][odd] = Math.min(
                                    dp[curParity][pos + 1][even][odd],
                                    bestPrev);
                        }
                    }
                }
            }

            // -----------------------------------------------------------------
            // 5. The answer is the minimum cost among the two possible final parities.
            // -----------------------------------------------------------------
            int answer = Math.min(
                    dp[0][n][missingEvens][missingOdds],
                    dp[1][n][missingEvens][missingOdds]);

            printer.ans(answer).ln();
        }

        /** Fills every cell of the given 4‑dimensional array with the supplied value. */
        private static void fill(int[][][][] array, int value) {
            for (int p = 0; p < array.length; p++) {
                for (int i = 0; i < array[p].length; i++) {
                    for (int j = 0; j < array[p][i].length; j++) {
                        for (int k = 0; k < array[p][i][j].length; k++) {
                            array[p][i][j][k] = value;
                        }
                    }
                }
            }
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

/**
 * Refactored version of the original {@code Garland} program.
 *
 * <p>
 * The task is to fill the missing entries (marked with {@code 0}) of a sequence
 * with the distinct numbers from {@code 1..n} so that the number of adjacent
 * pairs having different parity (one odd, one even) is minimized.
 * </p>
 *
 * <p>Key improvements compared to the original code:</p>
 * <ul>
 *   <li>Descriptive naming of variables and constants.</li>
 *   <li>Extracted small helper methods (parity, transition cost).</li>
 *   <li>Clear separation of input handling, preprocessing, and DP solving.</li>
 *   <li>Use of {@code final} constants instead of magic numbers.</li>
 *   <li>All loops are documented with intention‑revealing comments.</li>
 * </ul>
 */
public class Garland {

    /** Cost that represents “infinite” for DP initialization. */
    private static final int INF = Integer.MAX_VALUE / 4;

    /** Determines whether a number is even (0) or odd (1). */
    private static int parity(int value) {
        return (value & 1) == 0 ? 0 : 1;
    }

    /** Returns the extra cost when a new parity follows {@code prev}. */
    private static int transitionCost(int prevParity, int newParity) {
        return prevParity != newParity ? 1 : 0;
    }

    /**
     * Solves the problem using dynamic programming.
     *
     * @param n                 length of the sequence (1‑based indexing)
     * @param seq               sequence where {@code 0} denotes a missing value
     * @param missingOddCount   how many odd numbers are still unused
     * @param missingEvenCount  how many even numbers are still unused
     * @return the minimal possible number of parity changes in the final sequence
     */
    private static int solve(int n, int[] seq, int missingOddCount, int missingEvenCount) {
        /* --------------------------------------------------------------
         * DP state:
         * dp[pos][usedOdd][usedEven][lastParity]
         *   pos      – we have processed the first {@code pos} elements.
         *   usedOdd  – how many missing odd numbers have already been placed.
         *   usedEven – how many missing even numbers have already been placed.
         *   lastParity – parity (0 = even, 1 = odd) of the element at position {@code pos}.
         *                The value stores the minimal cost up to that state.
         * -------------------------------------------------------------- */
        int[][][][] dp = new int[n + 1][missingOddCount + 1][missingEvenCount + 1][2];

        /* Initialise every cell with INF (unreachable state). */
        for (int i = 0; i <= n; i++) {
            for (int o = 0; o <= missingOddCount; o++) {
                for (int e = 0; e <= missingEvenCount; e++) {
                    for (int p = 0; p < 2; p++) {
                        dp[i][o][e][p] = INF;
                    }
                }
            }
        }

        /* Start: before the first element we can pretend the previous parity
         * is either even or odd with zero cost. */
        dp[0][0][0][0] = 0;
        dp[0][0][0][1] = 0;

        /* --------------------------------------------------------------
         * Fill DP table row by row (i = processed positions).
         * -------------------------------------------------------------- */
        for (int i = 1; i <= n; i++) {
            int currentValue = seq[i];
            boolean isMissing = currentValue == 0;

            if (!isMissing) {
                /* Fixed number – only its parity influences the transition. */
                int curParity = parity(currentValue);
                for (int usedOdd = 0; usedOdd <= missingOddCount; usedOdd++) {
                    for (int usedEven = 0; usedEven <= missingEvenCount; usedEven++) {
                        for (int prevParity = 0; prevParity < 2; prevParity++) {
                            int cost = transitionCost(prevParity, curParity);
                            int candidate = dp[i - 1][usedOdd][usedEven][prevParity] + cost;
                            dp[i][usedOdd][usedEven][curParity] = Math.min(dp[i][usedOdd][usedEven][curParity], candidate);
                        }
                    }
                }
            } else {
                /* Missing entry – we may place either an odd or an even number
                 * provided we still have such numbers left. */
                // ---- place an odd number (parity = 1) ----
                if (missingOddCount > 0) {
                    for (int usedOdd = 1; usedOdd <= missingOddCount; usedOdd++) {
                        for (int usedEven = 0; usedEven <= missingEvenCount; usedEven++) {
                            for (int prevParity = 0; prevParity < 2; prevParity++) {
                                int cost = transitionCost(prevParity, 1); // odd
                                int candidate = dp[i - 1][usedOdd - 1][usedEven][prevParity] + cost;
                                dp[i][usedOdd][usedEven][1] = Math.min(dp[i][usedOdd][usedEven][1], candidate);
                            }
                        }
                    }
                }

                // ---- place an even number (parity = 0) ----
                if (missingEvenCount > 0) {
                    for (int usedOdd = 0; usedOdd <= missingOddCount; usedOdd++) {
                        for (int usedEven = 1; usedEven <= missingEvenCount; usedEven++) {
                            for (int prevParity = 0; prevParity < 2; prevParity++) {
                                int cost = transitionCost(prevParity, 0); // even
                                int candidate = dp[i - 1][usedOdd][usedEven - 1][prevParity] + cost;
                                dp[i][usedOdd][usedEven][0] = Math.min(dp[i][usedOdd][usedEven][0], candidate);
                            }
                        }
                    }
                }
            }
        }

        /* The answer is the best cost after processing all positions while
         * having used every missing odd and even number. */
        return Math.min(
                dp[n][missingOddCount][missingEvenCount][0],
                dp[n][missingOddCount][missingEvenCount][1]);
    }

    /** Reads input, prepares data structures and prints the solution. */
    public static void main(String[] args) throws IOException {
        /* --------------------------------------------------------------
         * Input parsing – we keep the original 1‑based indexing for clarity.
         * -------------------------------------------------------------- */
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in))) {
            int n = Integer.parseInt(br.readLine().trim());

            int[] a = new int[n + 1];          // 1‑based array for readability
            boolean[] present = new boolean[n + 1];

            StringTokenizer st = new StringTokenizer(br.readLine());
            for (int i = 1; i <= n; i++) {
                int val = Integer.parseInt(st.nextToken());
                a[i] = val;
                if (val != 0) {
                    present[val] = true;       // mark numbers that already exist
                }
            }

            /* --------------------------------------------------------------
             * Count how many odd and even numbers are missing.
             * -------------------------------------------------------------- */
            int missingOdd = 0;
            int missingEven = 0;
            for (int i = 1; i <= n; i++) {
                if (!present[i]) {
                    if (i % 2 == 0) {
                        missingEven++;
                    } else {
                        missingOdd++;
                    }
                }
            }

            /* --------------------------------------------------------------
             * Solve and output the result.
             * -------------------------------------------------------------- */
            int answer = solve(n, a, missingOdd, missingEven);
            System.out.println(answer);
        }
    }
}

import java.io.*;
import java.util.*;

public class Main {

    public static void main(String[] args) {
        InputStream inStream = System.in;
        OutputStream outStream = System.out;
        FastReader reader = new FastReader(inStream);
        PrintWriter writer = new PrintWriter(outStream, true);

        GarlandSolver solver = new GarlandSolver();
        solver.solve(reader, writer);

        writer.flush();
    }

    /** Solves the Garland problem. */
    static class GarlandSolver {

        /** Holds a DP result: maximum replacements and the parity placed at the current position. */
        private static final class Result {
            final int replacements;   // number of already counted replacements
            final int lastParity;     // 0 = even, 1 = odd, -1 = not placed yet

            Result(int replacements, int lastParity) {
                this.replacements = replacements;
                this.lastParity = lastParity;
            }

            @Override
            public boolean equals(Object o) {
                if (this == o) return true;
                if (!(o instanceof Result)) return false;
                Result that = (Result) o;
                return replacements == that.replacements && lastParity == that.lastParity;
            }

            @Override
            public int hashCode() {
                return Objects.hash(replacements, lastParity);
            }
        }

        /** Entry point used by Main. */
        void solve(FastReader reader, PrintWriter out) {
            int n = reader.nextInt();
            int[] values = reader.nextIntArray(n);

            int oddPositions = (n + 1) / 2;   // required odd slots after filling
            int evenPositions = n / 2;        // required even slots after filling

            // Transform the input: -1 = empty, 0 = even placed, 1 = odd placed
            transform(values, oddPositions, evenPositions);

            // DP with memoisation
            Result[][][] memo = new Result[oddPositions + 1][evenPositions + 1][n];
            Result answer = dp(values, memo, oddPositions, evenPositions, 0);

            out.println(answer.replacements);
        }

        /** Recursive DP with memoisation. */
        private Result dp(int[] arr, Result[][][] memo,
                         int oddLeft, int evenLeft, int index) {
            // After the last position there is no penalty
            if (index == arr.length) {
                return new Result(0, -1);
            }

            Result cached = memo[oddLeft][evenLeft][index];
            if (cached != null) {
                return cached;
            }

            Result best;
            int currentValue = arr[index];

            if (currentValue != -1) {                     // fixed parity already placed
                int parity = currentValue;
                Result next = dp(arr, memo, oddLeft, evenLeft, index + 1);
                int additional = (next.lastParity != -1 && next.lastParity != parity) ? 1 : 0;
                best = new Result(next.replacements + additional, parity);
            } else if (oddLeft == 0 && evenLeft == 0) {   // nothing left to place
                Result next = dp(arr, memo, 0, 0, index + 1);
                int additional = (next.lastParity != -1 && next.lastParity != 0) ? 1 : 0;
                best = new Result(next.replacements + additional, 0);
            } else if (evenLeft == 0) {                    // must place odd
                Result next = dp(arr, memo, oddLeft - 1, evenLeft, index + 1);
                int additional = (next.lastParity != -1 && next.lastParity != 1) ? 1 : 0;
                best = new Result(next.replacements + additional, 1);
            } else if (oddLeft == 0) {                     // must place even
                Result next = dp(arr, memo, oddLeft, evenLeft - 1, index + 1);
                int additional = (next.lastParity != -1 && next.lastParity != 0) ? 1 : 0;
                best = new Result(next.replacements + additional, 0);
            } else {                                       // optional choice
                Result oddChoiceResult = dp(arr, memo, oddLeft - 1, evenLeft, index + 1);
                Result evenChoiceResult = dp(arr, memo, oddLeft, evenLeft - 1, index + 1);

                Result oddChoice = new Result(
                        oddChoiceResult.replacements +
                                (oddChoiceResult.lastParity != -1 && oddChoiceResult.lastParity != 1 ? 1 : 0),
                        1);
                Result evenChoice = new Result(
                        evenChoiceResult.replacements +
                                (evenChoiceResult.lastParity != -1 && evenChoiceResult.lastParity != 0 ? 1 : 0),
                        0);

                // Choose the option with more replacements; on a tie pick arbitrarily
                best = oddChoice.replacements > evenChoice.replacements
                        ? oddChoice
                        : (oddChoice.replacements < evenChoice.replacements ? evenChoice
                                : tieBreak(oddChoice, evenChoice));
            }

            memo[oddLeft][evenLeft][index] = best;
            return best;
        }

        /** Resolves ties when two choices yield the same number of replacements. */
        private Result tieBreak(Result oddChoice, Result evenChoice) {
            // If placing odd keeps the same parity as the previous slot, it avoids an extra replacement.
            if (oddChoice.lastParity == evenChoice.lastParity) {
                return oddChoice;
            }
            // Otherwise arbitrarily prefer odd; any deterministic rule is fine.
            return oddChoice;
        }

        /** Converts zeros and ones in the array into -1 (empty), 0 (even), 1 (odd) while tracking needed counts. */
        private void transform(int[] arr, int oddSlots, int evenSlots) {
            for (int i = 0; i < arr.length; i++) {
                if (arr[i] == 0) {
                    arr[i] = -1;                     // will be filled later
                } else {
                    if (arr[i] % 2 == 0) {
                        arr[i] = 0;                    // even
                        evenSlots--;
                    } else {
                        arr[i] = 1;                    // odd
                        oddSlots--;
                    }
                }
            }
            // Store the remaining needed counts for the DP call
            this.oddSlots = oddSlots;
            this.evenSlots = evenSlots;
        }

        // fields used only inside transform; they become method parameters after transformation
        private int oddSlots;
        private int evenSlots;
    }

    /** Fast input reader with space‑filter support. */
    static class FastReader {
        private final InputStream stream;
        private final byte[] buffer = new byte[16_384];
        private int bytesRead = 0, curIndex = 0;

        FastReader(InputStream stream) {
            this.stream = stream;
        }

        private int readChar() throws IOException {
            if (curIndex >= bytesRead) {
                bytesRead = stream.read(buffer);
                curIndex = 0;
                if (bytesRead <= 0) return -1;
            }
            return buffer[curIndex++];
        }

        /** Returns next non‑whitespace character. */
        private int nextNonWhitespace() throws IOException {
            int c;
            while ((c = readChar()) <= ' ') {
                if (c == -1) return -1;
            }
            return c;
        }

        int nextInt() {
            int sign = 1;
            int c = nextNonWhitespace();
            if (c == '-') {
                sign = -1;
                c = readChar();
            }
            int value = 0;
            while (c >= '0' && c <= '9') {
                value = value * 10 + (c - '0');
                c = readChar();
            }
            return value * sign;
        }

        int[] nextIntArray(int n) {
            int[] arr = new int[n];
            for (int i = 0; i < n; i++) arr[i] = nextInt();
            return arr;
        }

        interface SpaceCharFilter {
            boolean isSpaceChar(int ch);
        }
    }
}

import java.io.IOException;
import java.util.Arrays;
import java.util.Scanner;

/**
 * Reads a sequence of integers (some of them may be missing, i.e. equal to 0) and
 * computes the minimum number of adjacent equal‑parity pairs after filling all
 * missing values with the remaining even and odd numbers.
 *
 * The algorithm uses dynamic programming:
 *   dp[pos][evenUsed][parity] – minimal cost up to position {@code pos}
 *   where {@code evenUsed} numbers of the required even type have already been placed
 *   and {@code parity} (0 = even, 1 = odd) indicates the parity of the element at {@code pos}.
 *
 * The answer is {@code min(dp[n][requiredEvens][0], dp[n][requiredEvens][1])}.
 */
public class SequenceReplacer {

    /** Maximum length allowed by the original constraints. */
    private static final int MAX_N = 200;

    /** A value larger than any possible cost. */
    private static final int INF = Integer.MAX_VALUE / 4;

    /** Separator between the two possible parities used for readability. */
    private static final int EVEN = 0;
    private static final int ODD  = 1;

    public static void main(String[] args) throws IOException {
        /* -------------------------------------------------------------
         * 1️⃣  Input handling – try‑with‑resources guarantees closure.
         * ------------------------------------------------------------- */
        try (Scanner scanner = new Scanner(System.in)) {
            int n = scanner.nextInt();                     // total length of the sequence
            int[] seq = new int[n + 1];                     // 1‑based indexing for clarity
            int requiredEvens = n / 2;                      // how many even numbers we must place
            int requiredOdds  = (n + 1) / 2;                 // how many odd  numbers we must place

            /* ---------------------------------------------------------
             * 2️⃣  Read the sequence and count how many even / odd slots
             *      are already occupied by a non‑zero entry.
             * --------------------------------------------------------- */
            for (int i = 1; i <= n; i++) {
                seq[i] = scanner.nextInt();
                if (seq[i] > 0) {
                    if (seq[i] % 2 == 0) {
                        requiredEvens--;
                    } else {
                        requiredOdds--;
                    }
                }
            }

            /* ---------------------------------------------------------
             * 3️⃣  DP initialisation.
             *
             *    dp[pos][usedEvens][parity] – large array filled with INF.
             * --------------------------------------------------------- */
            int[][][] dp = new int[n + 1][requiredEvens + 1][2];
            for (int[][] layer : dp) {
                for (int[] cell : layer) {
                    Arrays.fill(cell, INF);
                }
            }

            /* ---------------------------------------------------------
             * 4️⃣  Initialise the first position.
             * --------------------------------------------------------- */
            if (seq[1] == 0) {
                // we may start with either parity
                dp[1][0][EVEN] = 0;
                dp[1][0][ODD]  = 0;
            } else {
                // fixed value – its parity determines the state
                int parity = seq[1] % 2;
                dp[1][0][parity] = 0;
            }

            /* ---------------------------------------------------------
             * 5️⃣  Fill the DP table.
             * --------------------------------------------------------- */
            for (int pos = 2; pos <= n; pos++) {
                if (seq[pos] != 0) {
                    // ----- a fixed (non‑zero) value ---------------------------------
                    int fixedParity = seq[pos] % 2;
                    int parityIdx = fixedParity;                 // the only reachable parity
                    for (int usedEven = 0; usedEven <= requiredEvens; usedEven++) {
                        // transition costs from the two possible previous parities
                        int costFromPrevEven = dp[pos - 1][usedEven][EVEN];
                        int costFromPrevOdd  = dp[pos - 1][usedEven][ODD];

                        // cost when we keep the same parity as the previous element
                        // otherwise we incur an additional "adjacent‑equal‑parity" pair
                        int transitionCostEven = Math.min(costFromPrevEven,
                                costFromPrevOdd + 1);
                        int transitionCostOdd  = Math.min(costFromPrevEven + 1,
                                costFromPrevOdd);

                        // keep only the entry that matches the fixed parity
                        dp[pos][usedEven][EVEN] = (parityIdx == EVEN) ? transitionCostEven : INF;
                        dp[pos][usedEven][ODD]  = (parityIdx == ODD)  ? transitionCostOdd  : INF;
                    }
                } else {
                    // ----- a blank position – we may put either parity -------------
                    // The number of blanks that have been filled before this position
                    // is exactly (pos‑1) minus the amount of already‑fixed values.
                    // We simply iterate over all reachable counts of usedEvens.
                    for (int usedEven = 0; usedEven <= requiredEvens; usedEven++) {
                        int usedOdd = (pos - 1) - usedEven;   // how many odds have been placed so far

                        // ----- place an even number here ---------------------------------
                        if (usedEven > 0 && usedOdd <= requiredOdds) {
                            // coming from an even previous element → no extra cost
                            // coming from an odd  previous element → add 1
                            int cost = Math.min(dp[pos - 1][usedEven - 1][EVEN],
                                    dp[pos - 1][usedEven - 1][ODD] + 1);
                            dp[pos][usedEven][EVEN] = Math.min(dp[pos][usedEven][EVEN], cost);
                        }

                        // ----- place an odd number here ----------------------------------
                        if (usedOdd > 0 && usedEven <= requiredEvens) {
                            int cost = Math.min(dp[pos - 1][usedEven][ODD],
                                    dp[pos - 1][usedEven][EVEN] + 1);
                            dp[pos][usedEven][ODD] = Math.min(dp[pos][usedEven][ODD], cost);
                        }
                    }
                }
            }

            /* ---------------------------------------------------------
             * 6️⃣  Extract the answer.
             * --------------------------------------------------------- */
            int answer = Math.min(dp[n][requiredEvens][EVEN], dp[n][requiredEvens][ODD]);
            System.out.println(answer);
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.util.Arrays;
import java.util.StringTokenizer;

/**
 * Refactored version of the original program.
 *
 * <p>Key improvements:
 * <ul>
 *   <li>Extracted the DP logic into a dedicated {@link ParityDp} class for better separation of concerns.</li>
 *   <li>Renamed variables and constants to meaningful names (e.g. {@code needEven} instead of {@code zero}).</li>
 *   <li>Replaced magic numbers with expressive constants and used {@code INF} = {@code 1_000_000_007}</li>
 *   <li>Simplified the input handling and eliminated unused code paths.</li>
 *   <li>Added Javadoc comments and logical grouping of related code.</li>
 *   <li>Kept the public entry point unchanged so the program continues to read from standard input.</li>
 * </ul>
 */
public class Main {

    /** Large constant used as infinity for DP transitions. */
    private static final int INF = 1_000_000_007;

    public static void main(String[] args) {
        var input = new InputReader();
        int n = input.nextInt();

        // Trivial case: a single position always needs 0 swaps.
        if (n == 1) {
            System.out.println(0);
            return;
        }

        // -----------------------------------------------------------------
        // 1️⃣ Read the raw numbers and convert them into a parity representation.
        // -----------------------------------------------------------------
        int[] raw = new int[n + 1];
        int needEven = n / 2;                     // required count of even positions
        int needOdd  = n / 2 + n % 2;             // required count of odd  positions

        for (int i = 1; i <= n; i++) {
            int value = input.nextInt();
            // -1 denotes an empty slot that must be filled later.
            raw[i] = (value == 0) ? -1 : value % 2;
        }

        // Count how many even/odd numbers are already fixed (not -1).
        int fixedEven = 0;
        int fixedOdd  = 0;
        for (int i = 1; i <= n; i++) {
            if (raw[i] == -1) {
                continue;
            }
            if (raw[i] == 0) {
                fixedEven++;
            } else {
                fixedOdd++;
            }
        }

        // If every position is already fixed there is exactly one valid parity pattern.
        if (fixedEven + fixedOdd == n) {
            System.out.println(1);
            return;
        }

        // -----------------------------------------------------------------
        // 2️⃣ Run the DP that computes the minimal number of adjacent swaps.
        // -----------------------------------------------------------------
        var dp = new ParityDp(n, needEven, needOdd);
        System.out.println(dp.solve(raw));
    }

    /**
     * Encapsulates the dynamic‑programming computation of the minimum number of
     * adjacent swaps required to obtain a valid parity pattern.
     *
     * <p>The DP state is {@code dp[pos][e][o][last]} where:
     * <ul>
     *   <li>{@code pos} – current position (1‑based) we are processing,</li>
     *   <li>{@code e}   – number of even numbers placed so far,</li>
     *   <li>{@code o}   – number of odd  numbers placed so far,</li>
     *   <li>{@code last} – parity placed at position {@code pos} (0 = even, 1 = odd).</li>
     * </ul>
     *
     * <p>Transitions respect the already‑filled numbers and propagate the minimal
     * cost (swaps introduced when the parity changes).
     */
    private static final class ParityDp {

        private final int length;
        private final int needEven;
        private final int needOdd;
        /** 4‑dimensional DP array: [position][filledEvens][filledOdds][lastParity] */
        private final int[][][][] cost;

        ParityDp(int length, int needEven, int needOdd) {
            this.length = length;
            this.needEven = needEven;
            this.needOdd = needOdd;

            // Initialise with a large value (INF) to represent “unreachable”.
            cost = new int[length + 1][needEven + 1][needOdd + 1][2];
            for (int[][][] slice : cost) {
                for (int[][] inner : slice) {
                    for (int[] leaf : inner) {
                        Arrays.fill(leaf, INF);
                    }
                }
            }

            // Base case: before processing any element we have placed 0 evens and 0 odds.
            cost[0][0][0][0] = cost[0][0][0][1] = 0;
        }

        /**
         * Executes the DP and returns the minimal number of adjacent swaps.
         *
         * @param raw array containing the original input values (0 = even placeholder,
         *            -1 = empty slot, 1/0 = fixed parity)
         * @return minimal swaps required to achieve a valid parity arrangement
         */
        int solve(int[] raw) {
            for (int pos = 1; pos <= length; pos++) {
                int val = raw[pos];
                for (int e = 0; e <= needEven; e++) {
                    for (int o = 0; o <= needOdd; o++) {
                        if (val == -1) {
                            // Place an even number at position {@code pos}
                            if (e > 0) {
                                int prev = Math.min(
                                        cost[pos - 1][e - 1][o][0],
                                        cost[pos - 1][e - 1][o][1] + 1);
                                cost[pos][e][o][0] = Math.min(cost[pos][e][o][0], prev);
                            }
                            // Place an odd number at position {@code pos}
                            if (o > 0) {
                                int prev = Math.min(
                                        cost[pos - 1][e][o - 1][0] + 1,
                                        cost[pos - 1][e][o - 1][1]);
                                cost[pos][e][o][1] = Math.min(cost[pos][e][o][1], prev);
                            }
                        } else {
                            // Fixed parity – no extra cost incurred by switching parity.
                            int prev = Math.min(
                                    cost[pos - 1][e][o][0],
                                    cost[pos - 1][e][o][1] + 1);
                            cost[pos][e][o][val] = Math.min(cost[pos][e][o][val], prev);
                        }
                    }
                }
            }
            // The answer is the best among ending with an even or odd parity.
            return Math.min(cost[length][needEven][needOdd][0],
                            cost[length][needEven][needOdd][1]);
        }
    }

    /**
     * Simple tokenizer‑based scanner that mimics the original {@code InputReader}
     * implementation but throws unchecked exceptions on I/O errors for brevity.
     */
    private static final class InputReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        InputReader() {
            reader = new BufferedReader(new InputStreamReader(System.in));
        }

        private String nextLine() {
            try {
                return reader.readLine();
            } catch (IOException e) {
                throw new UncheckedIOException(e);
            }
        }

        private String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                tokenizer = new StringTokenizer(nextLine());
            }
            return tokenizer.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.util.Scanner;

/**
 * Refactored version of the original program.
 *
 * <p>This version improves readability, maintainability and testability
 * by extracting responsibilities into small helper methods, using
 * meaningful names, constants and avoiding magic numbers.</p>
 */
public class Main {

    /** A value that represents an “infinite” cost – larger than any possible DP entry. */
    private static final int INF = 1_000_000;

    public static void main(String[] args) {
        // Try‑with‑resources guarantees that the scanner is closed automatically.
        try (Scanner scanner = new Scanner(System.in)) {
            int n = readSize(scanner);
            int[] values = readArray(scanner, n);

            int evenPositions = n / 2;
            int oddPositions  = n / 2 + n % 2;

            int answer = computeMinCost(values, evenPositions, oddPositions);
            System.out.println(answer);
        }
    }

    /** Reads a single positive integer from the scanner. */
    private static int readSize(Scanner scanner) {
        int size = scanner.nextInt();
        if (size < 1) {
            throw new IllegalArgumentException("Input size must be positive");
        }
        return size;
    }

    /** Reads {@code n} integers starting from index 1 and stores them in a 1‑based array. */
    private static int[] readArray(Scanner scanner, int n) {
        int[] arr = new int[n + 1];          // index 0 is unused – mirrors original code
        for (int i = 1; i <= n; i++) {
            arr[i] = scanner.nextInt();
        }
        return arr;
    }

    /**
     * Core DP routine that computes the minimal number of changes needed.
     *
     * @param values      the original 1‑based input array
     * @param evenNeeded  required number of “even” slots to fill
     * @param oddNeeded   required number of “odd” slots to fill
     * @return the minimum cost
     */
    private static int computeMinCost(int[] values, int evenNeeded, int oddNeeded) {
        int size = values.length;                    // includes the unused element 0
        int[][][][] dp = createDpArray(size, evenNeeded, oddNeeded);
        initialiseDp(dp);

        dp[0][0][0][0] = 0;
        dp[0][0][0][1] = 0;

        for (int i = 1; i < size; i++) {
            for (int e = 0; e <= evenNeeded; e++) {
                for (int o = 0; o <= oddNeeded; o++) {
                    processCell(dp, values, i, e, o);
                }
            }
        }

        return Math.min(
                dp[size - 1][evenNeeded][oddNeeded][0],
                dp[size - 1][evenNeeded][oddNeeded][1]);
    }

    /** Allocates the 4‑dimensional DP table and fills it with {@link #INF}. */
    private static int[][][][] createDpArray(int rows, int colsE, int colsO) {
        return new int[rows][colsE + 1][colsO + 1][2];
    }

    /** Populates every cell with {@link #INF} (acts as a very large sentinel). */
    private static void initialiseDp(int[][][][] dp) {
        for (int i = 0; i < dp.length; i++) {
            for (int e = 0; e < dp[i].length; e++) {
                for (int o = 0; o < dp[i][e].length; o++) {
                    dp[i][e][o][0] = INF;
                    dp[i][e][o][1] = INF;
                }
            }
        }
    }

    /**
     * Updates DP state for the {@code i}-th element taking the current usage
     * {@code e} even slots and {@code o} odd slots into account.
     */
    private static void processCell(
            int[][][][] dp,
            int[] values,
            int i,
            int e,
            int o) {

        int value = values[i];

        // 0 means “wild‑card” – it can be interpreted as either even or odd.
        if (value == 0) {
            if (e > 0) {
                dp[i][e][o][0] = Math.min(
                        dp[i][e][o][0],
                        min(dp[i - 1][e - 1][o][0], dp[i - 1][e - 1][o][1] + 1));
            }
            if (o > 0) {
                dp[i][e][o][1] = Math.min(
                        dp[i][e][o][1],
                        min(dp[i - 1][e][o - 1][0] + 1, dp[i - 1][e][o - 1][1]));
            }
        } else {
            boolean isEven = (value % 2 == 0);
            if (isEven && e > 0) {
                dp[i][e][o][0] = Math.min(
                        dp[i][e][o][0],
                        min(dp[i - 1][e - 1][o][0], dp[i - 1][e - 1][o][1] + 1));
            }
            if (!isEven && o > 0) {
                dp[i][e][o][1] = Math.min(
                        dp[i][e][o][1],
                        min(dp[i - 1][e][o - 1][0] + 1, dp[i - 1][e][o - 1][1]));
            }
        }
    }

    /** Utility to avoid repetition of the ternary ``Math.min`` call. */
    private static int min(int... values) {
        int result = Integer.MAX_VALUE;
        for (int v : values) {
            if (v < result) {
                result = v;
            }
        }
        return result;
    }
}

import java.io.*;
import java.util.*;

/**
 * Solves the “minimum parity changes” problem using dynamic programming.
 *
 * <p>
 * The program reads an array that may contain fixed numbers (non‑zero) and
 * placeholders (zero).  It must place the missing even and odd numbers so that
 * the number of adjacent parity switches is minimal.  The result is printed
 * to standard output.
 * </p>
 *
 * <p>All I/O is performed with {@link BufferedReader}/{@link PrintWriter}
 * wrapped in a {@link java.io.FileReader} style fast scanner.</p>
 */
public class Main implements Runnable {

    /** A value larger than any possible DP state. */
    private static final int INF = Integer.MAX_VALUE / 4;

    /** Helper class that bundles the three DP dimensions. */
    private static final class DpTable {
        final int[][][] table;                     // [i][j][parity]
        DpTable(int n) {
            table = new int[n + 1][n + 1][2];
            for (int i = 0; i <= n; i++) {
                for (int[][] row : table[i]) {
                    Arrays.fill(row, INF);
                }
            }
        }
    }

    /** Fast scanner used throughout the solution. */
    private final FastScanner fs = new FastScanner();

    /** Output writer. */
    private final PrintWriter out = new PrintWriter(System.out, true);

    /** Number of positions that must be filled with even numbers (1‑based even indices). */
    private int requiredEvenCount;

    /** DP table used during the computation. */
    private DpTable dp;

    /** ------------------------------------------------------------
     *  Entry point.
     *  ------------------------------------------------------------ */
    public static void main(String[] args) {
        new Main().run();
    }

    /** ------------------------------------------------------------
     *  Core algorithm.
     *  ------------------------------------------------------------ */
    @Override
    public void run() {
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in))) {
            fs.setReader(br);
            solve();
            out.flush();
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
    }

    /** ------------------------------------------------------------
     *  Reads input, builds DP, computes answer and prints it.
     *  ------------------------------------------------------------ */
    private void solve() throws IOException {
        int n = fs.nextInt();                         // size of the array
        int[] a = fs.nextIntArray(n);                // the array (0 = empty slot)

        // count how many *even* positions are required to be filled
        requiredEvenCount = 0;
        for (int i = 0; i < n; i++) {
            if ((i + 1) % 2 == 0) {
                requiredEvenCount++;
            }
        }

        dp = new DpTable(n);

        // initialise base case: before processing any element we have placed 0 evens/odds,
        // parity of the "previous" element is undefined, so we treat it as both.
        dp.table[0][0][0] = dp.table[0][0][1] = 0;

        for (int i = 1; i <= n; i++) {
            for (int placedSoFar = 0; placedSoFar < i; placedSoFar++) {
                for (int prevParity = 0; prevParity < 2; prevParity++) {
                    int previousCost = dp.table[i - 1][placedSoFar][prevParity];
                    if (previousCost == INF) {
                        continue;   // unreachable state
                    }

                    int currentValue = a[i - 1];
                    if (currentValue != 0) {
                        // Fixed number – only one transition is possible
                        if ((currentValue & 1) == 0) {          // even
                            placeEven(i, placedSoFar, prevParity, previousCost);
                        } else {                                   // odd
                            placeOdd(i, placedSoFar, prevParity, previousCost);
                        }
                    } else {
                        // Slot is empty – we may place either an even or an odd number
                        // (respecting the needed count of evens)
                        for (int placeEvenHere : BooleanArray.asBooleanArray(
                                placedSoFar < requiredEvenCount)) {
                            int newPlaced = placedSoFar + (placeEvenHere ? 1 : 0);
                            int newParity = placeEvenHere ? 0 : 1;
                            int addedCost = (prevParity != newParity) ? 1 : 0;
                            update(i, newPlaced, newParity, previousCost + addedCost);
                        }
                    }
                }
            }
        }

        // The answer is the minimum cost among the two possible final parities
        int answer = Math.min(dp.table[n][requiredEvenCount][0],
                              dp.table[n][requiredEvenCount][1]);
        out.println(answer);
    }

    /** ------------------------------------------------------------
     *  Utility methods that encapsulate state transitions.
     *  ------------------------------------------------------------ */

    /** Places an even number at position i and updates DP entry. */
    private void placeEven(int i, int placedSoFar, int prevParity, int cost) {
        int newPlaced = placedSoFar + 1;
        int newParity = 0;                     // 0 == even
        int transition = (prevParity != newParity) ? 1 : 0;
        update(i, newPlaced, newParity, cost + transition);
    }

    /** Places an odd number at position i and updates DP entry. */
    private void placeOdd(int i, int placedSoFar, int prevParity, int cost) {
        int newPlaced = placedSoFar;           // odd does not increase even count
        int newParity = 1;                     // 1 == odd
        int transition = (prevParity != newParity) ? 1 : 0;
        update(i, newPlaced, newParity, cost + transition);
    }

    /**
     * Stores the minimum cost for a given DP state.
     *
     * @param i           number of processed elements (1‑based index)
     * @param placedEvens how many even numbers have been placed so far
     * @param parity      parity of the last placed number (0 = even, 1 = odd)
     * @param cost        accumulated number of parity changes
     */
    private void update(int i, int placedEvens, int parity, int cost) {
        if (cost < dp.table[i][placedEvens][parity]) {
            dp.table[i][placedEvens][parity] = cost;
        }
    }

    /** ------------------------------------------------------------
     *  Fast scanner utilities (wrapper around BufferedReader + StringTokenizer).
     *  ------------------------------------------------------------ */
    private static final class FastScanner {
        private BufferedReader br;
        private StringTokenizer st;

        /** Sets the underlying {@link BufferedReader}. */
        void setReader(BufferedReader reader) {
            this.br = reader;
        }

        /** Returns the next token, expanding the tokenizer as needed. */
        private String next() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                st = new StringTokenizer(br.readLine());
            }
            return st.nextToken();
        }

        /** Reads a line token and converts it to an {@code int}. */
        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }

        /** Reads a line token and converts it to an {@code long}. */
        long nextLong() throws IOException {
            return Long.parseLong(next());
        }

        /** Reads a line token and converts it to a {@code double}. */
        double nextDouble() throws IOException {
            return Double.parseDouble(next());
        }

        /** Reads an {@code int} array of length {@code length}. */
        int[] nextIntArray(int length) throws IOException {
            int[] arr = new int[length];
            for (int i = 0; i < length; i++) {
                arr[i] = nextInt();
            }
            return arr;
        }

        /** Reads a {@code List} of {@code Integer}s (not used but kept for completeness). */
        List<Integer> nextIntegerList(int length) throws IOException {
            List<Integer> list = new ArrayList<>();
            for (int i = 0; i < length; i++) {
                list.add(nextInt());
            }
            return list;
        }
    }
}

