 * It solves the same algorithmic problem using a clearer structure.
 */
public class Main {

    /**
     * Simple wrapper around {@link BufferedReader} that provides convenient
     * tokenised input methods. Using try‑with‑resources guarantees the stream
     * is closed after use.
     */
    private static final class FastReader implements AutoCloseable {
        private final BufferedReader br;
        private StringTokenizer st;

        FastReader() throws IOException {
            this.br = new BufferedReader(new InputStreamReader(System.in));
        }

        /** Reads the next token. */
        String next() throws IOException {
            while (st == null || !st.hasMoreElements()) {
                st = new StringTokenizer(br.readLine());
            }
            return st.nextToken();
        }

        /** Reads the next integer. */
        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }

        /** Reads the next long. */
        long nextLong() throws IOException {
            return Long.parseLong(next());
        }

        /** Reads the next double. */
        double nextDouble() throws IOException {
            return Double.parseDouble(next());
        }

        /** Reads the next line. */
        String nextLine() throws IOException {
            return br.readLine();
        }

        @Override
        public void close() throws IOException {
            br.close();
        }
    }

    /**
     * Utility method that extracts vowels from a string.
     * The original method was renamed to better express its intent.
     */
    public static String filterVowels(String input) {
        StringBuilder sb = new StringBuilder();
        for (char ch : input.toCharArray()) {
            if ("aeiou".indexOf(ch) >= 0) {
                sb.append(ch);
            }
        }
        return sb.toString();
    }

    /**
     * Returns a new {@link Map} whose entries are sorted by their values in
     * ascending order while preserving insertion order of the sorted map.
     * The implementation uses streams for conciseness.
     */
    public static <K, V extends Comparable<V>> Map<K, V> sortByValues(Map<K, V> map) {
        return map.entrySet()
                .stream()
                .sorted(Comparator.comparingInt(Map.Entry::getValue))
                .collect(Collectors.toMap(
                        Map.Entry::getKey,
                        Map.Entry::getValue,
                        (e1, e2) -> e1,
                        LinkedHashMap::new));
    }

    /**
     * Entry point of the program.
     *
     * @param args command line arguments (unused)
     * @throws IOException if an I/O error occurs while reading input
     */
    public static void main(String[] args) throws IOException {
        // Try‑with‑resources ensures the FastReader is closed automatically.
        try (FastReader reader = new FastReader()) {
            int n = reader.nextInt();

            // Store values 1‑based as the original code expected.
            int[] values = new int[n + 1];
            for (int i = 1; i <= n; i++) {
                values[i] = reader.nextInt();
            }

            // Number of elements that must be placed in each "bucket".
            int half = n / 2;
            int other = n - half;

            // DP[i][j][k][l] – minimal cost up to index i,
            // j elements placed in the first bucket,
            // k elements placed in the second bucket,
            // l is a parity flag (0 or 1).
            int[][][][] dp = new int[n + 1][half + 1][other + 1][2];
            fillWithLargeValue(dp, n); // sentinel larger than any feasible answer

            // Base case – no elements processed yet.
            dp[0][0][0][0] = 0;
            dp[0][0][0][1] = 0;

            // Fill DP table.
            for (int i = 1; i <= n; i++) {
                for (int j = 0; j < i; j++) {
                    int k = i - j - 1; // derived index

                    if (values[i] == 0) {
                        // Place a vowel (or zero) in either bucket.
                        dp[i][j + 1][k][0] = min(
                                dp[i - 1][j][k][0],
                                dp[i - 1][j][k][1] + 1
                        );
                        dp[i][j][k + 1][1] = min(
                                dp[i - 1][j][k][1],
                                dp[i - 1][j][k][0] + 1
                        );
                    } else {
                        // Non‑zero values – treat parity specially.
                        if ((values[i] & 1) == 0) {
                            // Even number → first bucket.
                            dp[i][j + 1][k][0] = min(
                                    dp[i - 1][j][k][0],
                                    dp[i - 1][j][k][1] + 1
                            );
                        } else {
                            // Odd number → second bucket.
                            dp[i][j][k + 1][1] = min(
                                    dp[i - 1][j][k][1],
                                    dp[i - 1][j][k][0] + 1
                            );
                        }
                    }
                }
            }

            // Answer is the minimum cost among the two possible final states.
            int answer = Math.min(dp[n][half][other][0], dp[n][half][other][1]);
            System.out.println(answer);
        }
    }

    /**
     * Fills the four‑dimensional array with a large sentinel value.
     *
     * @param array the array to fill
     * @param sentinel the value used for initialization (typically {@code n})
     */
    private static void fillWithLargeValue(int[][][][] array, int sentinel) {
        for (int i = 0; i < array.length; i++) {
            for (int j = 0; j < array[i].length; j++) {
                for (int k = 0; k < array[i][j].length; k++) {
                    Arrays.fill(array[i][j][k], sentinel);
                }
            }
        }
    }

    /**
     * Convenience method to compute the minimum of two integers.
     */
    private static int min(int a, int b) {
        return Math.min(a, b);
    }
}

