import java.io.*;
import java.util.*;

/**
 * Entry point of the program. Delegates work to {@link TaskC} while handling I/O.
 */
public class Main {

    public static void main(String[] args) {
        solve(System.in, System.out);
    }

    /**
     * Core solving routine used by {@code main}. Keeps the {@code main} method tiny.
     */
    private static void solve(InputStream in, OutputStream out) {
        FastScanner scanner = new FastScanner(in);
        FastPrinter printer = new FastPrinter(out);
        new TaskC().solve(scanner, printer);
        printer.flush();
    }
}

/**
 * Contains the actual algorithm for the problem.
 */
class TaskC {

    /** Large sentinel value used for DP memoisation. */
    private static final int INF = Integer.MAX_VALUE / 2;

    /** DP table: [position][evenRemaining][oddRemaining][lastParity]. */
    private int[][][][] dp;

    /** Original array where {@code 0} marks an empty slot. */
    private int[] values;

    /** Number of even/odd values still missing to be placed. */
    private int[] missingCounts; // [0] = even, [1] = odd

    /** Reference to the input array for easier access inside the recursion. */
    private int[] valuesRef; // alias for readability inside recursion

    /**
     * Executes the solution: reads input, builds DP table, runs recursion and prints the answer.
     */
    public void solve(FastScanner fs, FastPrinter out) {
        int n = fs.nextInt();
        int[] a = new int[n];
        Set<Integer> present = new HashSet<>();

        // Load the array and collect already‑present numbers.
        for (int i = 0; i < n; i++) {
            a[i] = fs.nextInt();
            present.add(a[i]);
        }

        // Determine how many even and odd numbers are still missing.
        int missingEven = 0, missingOdd = 0;
        for (int i = 1; i <= n; i++) {
            if (!present.contains(i)) {
                if ((i & 1) == 0) {
                    missingEven++;
                } else {
                    missingOdd++;
                }
            }
        }

        // Allocate DP table with size based on the computed missing counts.
        dp = new int[n][missingEven + 1][missingOdd + 1][2];
        for (int[][] dp2 : dp) {
            for (int[][] dp3 : dp2) {
                Arrays.fill(dp3, INF);
            }
        }

        // Store the original array for later use in recursion.
        values = a;

        // Two virtual previous parities (0 and 1) ensure the first real element
        // never incurs a penalty for adjacency difference.
        int answer = Math.min(
                recurse(0, missingEven, missingOdd, 0),
                recurse(0, missingEven, missingOdd, 1)
        );
        out.println(answer);
    }

    /**
     * Recursive DP with memoisation.
     *
     * @param pos       Current index in the sequence.
     * @param evenRem   Remaining even numbers that can still be placed.
     * @param oddRem    Remaining odd numbers that can still be placed.
     * @param lastParity Parity (0 = even, 1 = odd) of the previously placed element.
     * @return Minimum cost (adjacent parity changes) from {@code pos} onward.
     */
    private int recurse(int pos, int evenRem, int oddRem, int lastParity) {
        if (pos == values.length) {
            return 0; // base case: no more positions left
        }

        int cached = dp[pos][evenRem][oddRem][lastParity];
        if (cached != INF) {
            return cached;
        }

        int costEven = INF, costOdd = INF;

        if (values[pos] == 0) { // Slot is empty – we may insert an even or odd number.
            if (evenRem > 0) {
                int penalty = (lastParity != 0) ? 1 : 0;
                costEven = recurse(pos + 1, evenRem - 1, oddRem, 0) + penalty;
            }
            if (oddRem > 0) {
                int penalty = (lastParity != 1) ? 1 : 0;
                costOdd = recurse(pos + 1, evenRem, oddRem - 1, 1) + penalty;
            }
        } else { // Fixed value – we simply follow its parity.
            int curParity = values[pos] & 1;
            int penalty = (lastParity != curParity) ? 1 : 0;
            costEven = recurse(pos + 1, evenRem, oddRem, curParity);
        }

        int best = Math.min(costEven, costOdd);
        dp[pos][evenRem][oddRem][lastParity] = best;
        return best;
    }
}

/**
 * Fast scanner based on {@link BufferedReader} and {@link StringTokenizer}.
 */
class FastScanner {
    private final BufferedReader br;
    private StringTokenizer st;

    FastScanner(InputStream stream) {
        br = new BufferedReader(new InputStreamReader(stream));
    }

    /** Returns the next token, or {@code null} if input is exhausted. */
    String next() {
        while (st == null || !st.hasMoreTokens()) {
            try {
                String line = br.readLine();
                if (line == null) {
                    return null;
                }
                st = new StringTokenizer(line);
            } catch (IOException e) {
                throw new UncheckedIOException(e);
            }
        }
        return st.nextToken();
    }

    /** Convenience method to read the next integer. */
    int nextInt() {
        return Integer.parseInt(next());
    }
}

/**
 * Simple wrapper around {@link PrintWriter} that offers pretty printing helpers.
 */
class FastPrinter {
    private final PrintWriter writer;

    FastPrinter(OutputStream stream) {
        writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(stream)));
    }

    /** Prints the given objects separated by a single space and adds a newline. */
    void println(Object... objs) {
        print(objs);
        writer.println();
    }

    /** Prints the given objects separated by a space (no trailing newline). */
    void print(Object... objs) {
        for (int i = 0; i < objs.length; i++) {
            if (i != 0) {
                writer.print(' ');
            }
            writer.print(objs[i]);
        }
    }

    /** Flushes the underlying writer. */
    void flush() {
        writer.flush();
    }
}

import java.io.*;
import java.util.*;

/**
 * OddEvenPlacement
 *
 * Reads a permutation with missing numbers (zeros) and places the missing odd/even numbers
 * so that the number of parity changes between consecutive positions is minimised.
 *
 * The solution is written with readability in mind:
 *   • meaningful identifiers,
 *   • constants instead of magic numbers,
 *   • separation of concerns (input, counting, solving),
 *   • a small memoisation cache instead of large 3‑D DP tables.
 */
public class OddEvenPlacement {

    /** Represents a state while recursing through the array. */
    private static final class State {
        final int index;          // current position in the array
        final int oddRemaining;   // how many odd numbers are still unused
        final int evenRemaining;  // how many even numbers are still unused
        final boolean previousWasOdd; // parity of the element placed just before index

        State(int index, int oddRemaining, int evenRemaining, boolean previousWasOdd) {
            this.index = index;
            this.oddRemaining = oddRemaining;
            this.evenRemaining = evenRemaining;
            this.previousWasOdd = previousWasOdd;
        }

        @Override
        public boolean equals(Object o) {
            if (this == o) return true;
            if (!(o instanceof State)) return false;
            State state = (State) o;
            return index == state.index &&
                   oddRemaining == state.oddRemaining &&
                   evenRemaining == state.evenRemaining &&
                   previousWasOdd == state.previousWasOdd;
        }

        @Override
        public int hashCode() {
            return Objects.hash(index, oddRemaining, evenRemaining, previousWasOdd);
        }
    }

    /** Holds all logic related to solving the problem. */
    private static final class Solver {

        private final int[] arr;          // original array (may contain zeros)
        private final int oddMissing;      // count of missing odd numbers 1..n
        private final int evenMissing;     // count of missing even numbers 1..n

        Solver(int[] arr, int oddMissing, int evenMissing) {
            this.arr = arr;
            this.oddMissing = oddMissing;
            this.evenMissing = evenMissing;
        }

        /** Entry point – tries both possibilities for the first placed parity. */
        int solve() {
            // Two possible starts: previous element considered odd or even
            int resultIfPrevIsOdd = memoisedRec(true, 0, oddMissing, evenMissing);
            int resultIfPrevIsEven = memoisedRec(false, 0, oddMissing, evenMissing);
            return Math.min(resultIfPrevIsOdd, resultIfPrevIsEven);
        }

        /**
         * Recursive memoised function.
         *
         * @param prevWasOdd   parity of the element placed just before {@code index}
         * @param index        current position in the array
         * @param oddLeft      remaining odd numbers to place
         * @param evenLeft     remaining even numbers to place
         * @return minimal number of additional parity changes needed from this state
         */
        private int memoisedRec(boolean prevWasOdd,
                                int index,
                                int oddLeft,
                                int evenLeft) {
            // Base case – whole array processed
            if (index == arr.length) {
                return 0;
            }

            State state = new State(index, oddLeft, evenLeft, prevWasOdd);
            Integer cached = memo.get(state);
            if (cached != null) {
                return cached;
            }

            int best;
            if (arr[index] != 0) { // positioned element, no choice
                boolean curIsOdd = (arr[index] & 1) == 1;
                int transitionCost = prevWasOdd != curIsOdd ? 1 : 0;
                best = memoisedRec(curIsOdd, index + 1, oddLeft, evenLeft) + transitionCost;
            } else { // we may place either an odd or an even number here
                best = Integer.MAX_VALUE;

                // Try placing an odd number
                if (oddLeft > 0) {
                    boolean curIsOdd = true;
                    int transitionCost = prevWasOdd != curIsOdd ? 1 : 0;
                    int cost = memoisedRec(curIsOdd, index + 1,
                                            oddLeft - 1, evenLeft) + transitionCost;
                    best = Math.min(best, cost);
                }

                // Try placing an even number
                if (evenLeft > 0) {
                    boolean curIsOdd = false;
                    int transitionCost = prevWasOdd != curIsOdd ? 1 : 0;
                    int cost = memoisedRec(curIsOdd, index + 1,
                                            oddLeft, evenLeft - 1) + transitionCost;
                    best = Math.min(best, cost);
                }
            }

            memo.put(state, best);
            return best;
        }

        // Simple cache used by the recursive method
        private final Map<State, Integer> memo = new HashMap<>();
    }

    /** -------------------------------------------------------------
     *  I/O handling – isolates scanner/reader usage from business logic.
     *  ------------------------------------------------------------- */
    private static final class InputReader {
        private final BufferedReader br;
        private final Scanner sc;

        InputReader() throws IOException {
            this.br = new BufferedReader(new InputStreamReader(System.in));
            this.sc = new Scanner(br);
        }

        /** Reads a single line as an integer. */
        int nextInt() {
            return Integer.parseInt(br.readLine());
        }

        /** Reads {@code n} integers and returns them in an array. */
        int[] nextArray(int n) {
            int[] a = new int[n];
            for (int i = 0; i < n; i++) {
                a[i] = sc.nextInt();
            }
            return a;
        }
    }

    /** -------------------------------------------------------------
     *  Main program driver.
     *  ------------------------------------------------------------- */
    public static void main(String[] args) throws Exception {
        try (InputReader reader = new InputReader()) {
            solve(reader);
        }
    }

    /** Core workflow – counts missing odds/even, creates solver, prints answer. */
    private static void solve(InputReader reader) {
        int n = reader.nextInt();               // size of the permutation
        int[] arr = reader.nextArray(n);        // the permutation (may contain 0)

        // -----------------------------------------------------------------
        // 1️⃣ Count how many odd / even numbers from 1..n are missing.
        // -----------------------------------------------------------------
        boolean[] present = new boolean[n + 1];
        for (int v : arr) {
            if (v != 0) {                         // ignore placeholders (0)
                present[v] = true;
            }
        }

        int oddMissing = 0;
        int evenMissing = 0;
        for (int value = 1; value <= n; value++) {
            if (!present[value]) {
                if ((value & 1) == 1) {
                    oddMissing++;
                } else {
                    evenMissing++;
                }
            }
        }

        // -----------------------------------------------------------------
        // 2️⃣ Solve the placement problem.
        // -----------------------------------------------------------------
        Solver solver = new Solver(arr, oddMissing, evenMissing);
        int answer = solver.solve();

        // -----------------------------------------------------------------
        // 3️⃣ Output result.
        // -----------------------------------------------------------------
        System.out.println(answer);
    }
}

import java.io.*;
import java.util.*;

 /**
  * Refactored solution for the CodeChef problem.
  *
  * Improvements made:
  *   • Clearer naming and separation of concerns.
  *   • Remove unused utility code (gcd, exponent, etc.).
  *   • Encapsulate I/O in a small {@code FastScanner}.
  *   • Use a memoisation table with expressive variable names.
  *   • Add comments explaining each logical block.
  *   • Keep the program self‑contained and fully compilable.
  */
public class Solution {

    /* ---------------------------------------------------------- */
    /*  Fast scanner – reads tokens from standard input           */
    /* ---------------------------------------------------------- */
    private static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner(InputStream stream) {
            this.br = new BufferedReader(new InputStreamReader(stream));
        }

        /** Returns the next token as a string. */
        private String next() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                String line = br.readLine();
                if (line == null) {
                    return null;
                }
                st = new StringTokenizer(line);
            }
            return st.nextToken();
        }

        /** Returns the next integer. */
        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }

    /* ---------------------------------------------------------- */
    /*  Global I/O handles                                         */
    /* ---------------------------------------------------------- */
    private static FastScanner in;
    private static PrintWriter out;

    /* ---------------------------------------------------------- */
    /*  DP memoisation table                                       */
    /* ---------------------------------------------------------- */
    private static int[][][][] memo;   // [index][evensLeft][oddsLeft][prevParity]

    /**
     * Recursive DP that returns the minimum cost from position {@code idx}
     * onward, given the remaining even/odd numbers to place and the parity
     * of the previously placed element.
     *
     * @param idx       current index in the transformed array
     * @param evensLeft remaining even numbers that have not been placed
     * @param oddsLeft  remaining odd numbers that have not been placed
     * @param prevParity parity (0 = even, 1 = odd) of the element placed just before {@code idx}
     * @param arr       transformed input where 0 = missing, 1 = odd, 2 = even
     * @return minimum cost from this state onward
     */
    private static int dp(int idx, int evensLeft, int oddsLeft, int prevParity, int[] arr) {
        if (memo[idx][evensLeft][oddsLeft][prevParity] != -1) {
            return memo[idx][evensLeft][oddsLeft][prevParity];
        }

        // Base case – all positions processed
        if (idx == arr.length) {
            memo[idx][evensLeft][oddsLeft][prevParity] = 0;
            return 0;
        }

        int current = arr[idx];

        // Fixed (non‑missing) element – just continue
        if (current != 0) {
            int curParity = (current == 1) ? 1 : 0; // 1 → odd, 0 → even
            int result = dp(idx + 1, evensLeft, oddsLeft, curParity, arr);
            memo[idx][evensLeft][oddsLeft][prevParity] = result;
            return result;
        }

        // Missing element – try placing an even or an odd
        int best = Integer.MAX_VALUE;

        if (evensLeft > 0) {
            int cost = dp(idx + 1, evensLeft - 1, oddsLeft, 0, arr)
                    + (prevParity + 0) % 2;           // extra cost when previous was odd
            best = Math.min(best, cost);
        }

        if (oddsLeft > 0) {
            int cost = dp(idx + 1, evensLeft, oddsLeft - 1, 1, arr)
                    + (prevParity + 1) % 2;           // extra cost when previous was even
            best = Math.min(best, cost);
        }

        memo[idx][evensLeft][oddsLeft][prevParity] = best;
        return best;
    }

    /* ---------------------------------------------------------- */
    /*  Main program                                               */
    /* ---------------------------------------------------------- */
    public static void main(String[] args) throws IOException {
        in = new FastScanner(System.in);
        out = new PrintWriter(System.out, true);

        solve();

        out.close();
    }

    /** Core logic – reads input, builds the DP state and prints the answer. */
    private static void solve() {
        int n = in.nextInt();
        int[] raw = new int[n];
        for (int i = 0; i < n; i++) {
            raw[i] = in.nextInt();
        }

        /* ------------------------------------------------------ */
        /*  Determine which numbers 1..n are missing and count      */
        /*  how many of those missing numbers are even / odd      */
        /* ------------------------------------------------------ */
        boolean[] present = new boolean[n + 1];
        for (int v : raw) {
            if (v != 0) {
                present[v] = true;
            }
        }

        int missingEvens = 0;
        int missingOdds = 0;
        for (int i = 1; i <= n; i++) {
            if (!present[i]) {
                if (i % 2 == 0) {
                    missingEvens++;
                } else {
                    missingOdds++;
                }
            }
        }

        /* ------------------------------------------------------ */
        /*  Transform the original array into a simpler representation:
            0 → missing slot
            1 → odd number
            2 → even number                                         */
        /* ------------------------------------------------------ */
        int[] transformed = new int[n];
        for (int i = 0; i < n; i++) {
            int v = raw[i];
            if (v == 0) {
                transformed[i] = 0;               // still missing
            } else if (v % 2 == 0) {
                transformed[i] = 2;               // even
            } else {
                transformed[i] = 1;               // odd
            }
        }

        /* ------------------------------------------------------ */
        /*  Initialise DP memoisation table with -1 (unvisited)   */
        /* ------------------------------------------------------ */
        memo = new int[n + 1][missingEvens + 1][missingOdds + 1][2];
        for (int[][][][] slice1 : memo) {
            for (int[][][] slice2 : slice1) {
                for (int[][] slice3 : slice2) {
                    Arrays.fill(slice3, -1);
                }
            }
        }

        /* ------------------------------------------------------ */
        /*  Run the DP and output the result                      */
        /* ------------------------------------------------------ */
        int answer = dp(0, missingEvens, missingOdds, 0, transformed);
        out.println(answer);
    }
}

import java.io.IOException;
import java.util.Arrays;

/**
 * Refactored solution that keeps the original algorithmic behaviour
 * but improves readability, modularity and overall code quality.
 *
 * The program computes, for each test case, the minimum number of
 * parity changes required when filling an array that contains
 * fixed numbers and zero placeholders.
 */
public class Main {

    /** sentinel value used to mark “unvisited” memoisation entries */
    private static final int UNVISITED = -1;

    /**
     * Top‑down dynamic programming that returns the minimal extra cost
     * from position {@code pos} onward.
     *
     * @param values       the complete input array (including fixed numbers and zeros)
     * @param evenLeft     remaining even‑valued placeholders
     * @param oddLeft      remaining odd‑valued placeholders
     * @param pos          current index to process
     * @param prevParity   parity (0 = even, 1 = odd) of the element placed just before {@code pos}
     * @param memo         4‑dimensional memoisation table
     * @return minimal additional cost from {@code pos} to the end
     */
    private static int dp(int[] values,
                          int evenLeft,
                          int oddLeft,
                          int pos,
                          int prevParity,
                          int[][][][] memo) {

        if (pos == values.length) {
            return 0;
        }

        if (memo[pos][evenLeft][oddLeft][prevParity] != UNVISITED) {
            return memo[pos][evenLeft][oddLeft][prevParity];
        }

        int current = values[pos];
        int curParity;
        int addedCost;

        /* --------------------------------------------------------------
         * Fixed (non‑zero) element – its parity is known.
         * -------------------------------------------------------------- */
        if (current != 0) {
            curParity = current & 1;                     // 0 → even, 1 → odd
            addedCost = (prevParity + curParity) % 2;    // 1 if parities differ
            int result = dp(values,
                           evenLeft,
                           oddLeft,
                           pos + 1,
                           curParity,
                           memo) + addedCost;
            memo[pos][evenLeft][oddLeft][prevParity] = result;
            return result;
        }

        /* --------------------------------------------------------------
         * Placeholder (zero) – we may fill it with an even or an odd
         * number, provided we still have placeholders of that type.
         * -------------------------------------------------------------- */
        int best = Integer.MAX_VALUE;

        // try to put an even number
        if (evenLeft > 0) {
            int costWhenEven = (prevParity + 0) % 2;                     // parity would become 0
            int candidate = dp(values,
                               evenLeft - 1,
                               oddLeft,
                               pos + 1,
                               0,
                               memo) + costWhenEven;
            best = Math.min(best, candidate);
        }

        // try to put an odd number
        if (oddLeft > 0) {
            int costWhenOdd = (prevParity + 1) % 2;                       // parity would become 1
            int candidate = dp(values,
                               evenLeft,
                               oddLeft - 1,
                               pos + 1,
                               1,
                               memo) + costWhenOdd;
            best = Math.min(best, candidate);
        }

        memo[pos][evenLeft][oddLeft][prevParity] = best;
        return best;
    }

    /** Utility method that fills a 4‑dimensional array with a given value. */
    private static void fillWith(int[][][][] target, int value) {
        Arrays.stream(target)
              .forEach(arr -> Arrays.stream(arr)
                                    .forEach(sub -> Arrays.stream(sub)
                                                          .forEach(sub2 -> Arrays.fill(sub2, value)));
    }

    public static void main(String[] args) throws IOException {
        try (Scanner scanner = new Scanner(System.in)) {

            int testCases = 1;                     // mimics the original `--t >= 0` loop

            while (testCases-- > 0) {
                int n = scanner.nextInt();

                int[] arr = new int[n];
                // Number of even / odd *slots* that must be filled in the final array
                int targetEven = n / 2;
                int targetOdd  = n - targetEven;

                // --------------------------------------------------------------
                // Read the array and update the remaining slot counters
                // --------------------------------------------------------------
                for (int i = 0; i < n; i++) {
                    arr[i] = scanner.nextInt();
                    if (arr[i] != 0) {
                        if ((arr[i] & 1) == 0) {
                            targetEven--;
                        } else {
                            targetOdd--;
                        }
                    }
                }

                // --------------------------------------------------------------
                // Memoisation tables – one for each possible starting parity
                // --------------------------------------------------------------
                int[][][][] memoEvenStart = new int[n + 1][targetEven + 1][targetOdd + 1][2];
                int[][][][] memoOddStart  = new int[n + 1][targetEven + 1][targetOdd + 1][2];

                fillWith(memoEvenStart, UNVISITED);
                fillWith(memoOddStart,  UNVISITED);

                // --------------------------------------------------------------
                // Run the DP twice: once assuming the previous parity is even (0)
                // and once assuming it is odd (1). The answer is the smaller cost.
                // --------------------------------------------------------------
                int costEvenStart = dp(arr, targetEven + 1, targetOdd, 0, 0, memoEvenStart);
                int costOddStart  = dp(arr, targetEven, targetOdd + 1, 0, 1, memoOddStart);

                System.out.println(Math.min(costEvenStart, costOddStart));
            }
        }
    }
}

import java.io.IOException;
import java.util.Arrays;
import java.util.Scanner;

/**
 * Maintainable version of the original DP solution.
 *
 * <p>Key improvements:
 * <ul>
 *   <li>Descriptive method and variable names.</li>
 *   <li>Separation of concerns – DP logic, memo‑initialisation and I/O are isolated.</li>
 *   <li>Clear handling of parity (even/odd) using boolean‑style comments.</li>
 *   <li>Removed dead imports and magic numbers.</li>
 *   <li>Explicit resetting of the memoisation table for each test case.</li>
 *   <li>Added short Javadoc comments for every public method.</li>
 * </ul>
 */
public class Main {

    /** Memoisation table: dp[pos][remainingEvens][prevParity]. */
    private static int[][][] memo;

    /**
     * Recursive DP that mirrors the original algorithm but uses
     * expressive parameter names and a straightforward control flow.
     *
     * @param nums      the original input array (only parity matters)
     * @param evenLeft  how many even numbers we may still place
     * @param oddLeft   how many odd numbers we may still place
     * @param idx       current position in the array
     * @param prevParity parity of the previously placed element (0 = even, 1 = odd)
     * @return minimal number of parity changes from this state onward
     */
    private static int solve(int[] nums, int evenLeft, int oddLeft,
                             int idx, int prevParity) {
        // Base case – processed the whole array
        if (idx == nums.length) {
            return 0;
        }

        // Return cached result if already computed
        if (memo[idx][evenLeft][prevParity] != -1) {
            return memo[idx][evenLeft][prevParity];
        }

        int current = nums[idx];
        int best;

        /*--------------------------------------------------------------
         *  Three distinct branches correspond to the original `if … else`
         *  ladder:
         *
         *  1. Keep the current value (non‑zero) – its parity is fixed.
         *  2. Only even numbers are left to place.
         *  3. Only odd numbers are left to place.
         *--------------------------------------------------------------*/
        if (current > 0 || (evenLeft <= 0 && oddLeft <= 0)) {
            // The parity of the element we keep
            int curParity = current % 2;
            int transition = (prevParity + curParity) % 2;          // 1 if parity changes
            best = transition + solve(nums, evenLeft, oddLeft, idx + 1, curParity);
        } else if (evenLeft <= 0) {
            // Only odd numbers can be placed now
            best = solve(nums, evenLeft, oddLeft - 1, idx + 1, 1)
                   + (prevParity + 1) % 2;                           // transition to odd
        } else if (oddLeft <= 0) {
            // Only even numbers can be placed now
            best = solve(nums, evenLeft - 1, oddLeft, idx + 1, 0)
                   + (prevParity + 0) % 2;                           // transition to even
        } else {
            // We may place either an even or an odd number.
            // The original code had a subtle distinction based on `prevParity`.
            int costIfEven  = solve(nums, evenLeft - 1, oddLeft, idx + 1, 0);
            int costIfOdd   = solve(nums, evenLeft, oddLeft - 1, idx + 1, 1);

            if (prevParity == 0) { // previous was even
                best = Math.min(costIfEven, costIfOdd + 1);
            } else {               // previous was odd
                best = Math.min(costIfEven + 1, costIfOdd);
            }
        }

        // Store result and return
        memo[idx][evenLeft][prevParity] = best;
        return best;
    }

    /**
     * Clears (re‑initialises) the memoisation table for a new test case.
     *
     * @param size      length of the current array (first dimension)
     * @param maxEven   maximal number of evens that can remain (second dimension)
     */
    private static void clearMemo(int size, int maxEven) {
        memo = new int[size][maxEven + 1][2];
        for (int[][] layer : memo) {
            for (int[] inner : layer) {
                Arrays.fill(inner, -1);
            }
        }
    }

    /** Entry point – reads input, runs the DP and prints the answer. */
    public static void main(String[] args) throws IOException {
        try (Scanner sc = new Scanner(System.in)) {
            /* The original stub used a “pre‑decrement while (--t >= 0)”.
             * We read the number of test cases explicitly for clarity. */
            int testCases = sc.nextInt();
            while (testCases-- > 0) {
                int n = sc.nextInt();
                int[] arr = new int[n];

                /* ---------------------------------------------------------
                 *  Count how many even / odd values we still need to place.
                 *  The original program stored these counts in variables `a`
                 *  and `b`.  We keep the same semantics but use meaningful
                 *  names.
                 * --------------------------------------------------------- */
                int needEven = n / 2;
                int needOdd  = n - needEven;

                for (int i = 0; i < n; i++) {
                    arr[i] = sc.nextInt();
                    if (arr[i] != 0) {
                        if (arr[i] % 2 == 0) {
                            needEven--;
                        } else {
                            needOdd--;
                        }
                    }
                }

                // The DP works with “how many we still may place”, not with the
                // numbers already consumed. Restore the original counters.
                int remainingEvens = n / 2;
                int remainingOdds  = n - remainingEvens;

                /* ---------------------------------------------------------
                 *  First run – assumes the previous element had even parity.
                 *  Second run – assumes the previous element had odd parity.
                 *  The memo table is cleared between the two runs.
                 * --------------------------------------------------------- */
                clearMemo(n, remainingEvens);
                int ansWithEvenPrev = solve(arr, remainingEvens, remainingOdds, 0, 0);

                clearMemo(n, remainingEvens);
                int ansWithOddPrev = solve(arr, remainingEvens, remainingOdds, 0, 1);

                System.out.println(Math.min(ansWithEvenPrev, ansWithOddPrev));
            }
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Refactored version of the original {@code TaskC} solution.
 * The program reads an integer {@code n} followed by {@code n} integers,
 * performs the same logical steps as the original implementation,
 * and prints a single integer result.
 *
 * The refactor focuses on:
 *   • Meaningful naming and clear separation of concerns
 *   • Removing duplication and magic numbers
 *   • Using modern Java constructs (generics, try‑with‑resources style)
 *   • Adding short comments that explain the intent of each block
 */
public class TaskC {

    /** Entry point – reads from standard input and prints the answer. */
    public static void main(String[] args) throws IOException {
        FastScanner scanner = new FastScanner(new InputStreamReader(System.in));
        System.out.println(solve(scanner));
    }

    /**
     * Core algorithm – mirrors the behaviour of the original code
     * but with clearer structure and variable names.
     *
     * @param in scanner that provides the input tokens
     * @return the answer as a {@link String} (as in the original program)
     */
    private static String solve(FastScanner in) {
        int n = in.nextInt();
        int[] values = in.readIntArray(n);

        // -----------------------------------------------------------------
        // 1️⃣  Trivial case – a single element always yields 0
        // -----------------------------------------------------------------
        if (n == 1) {
            return "0";
        }

        // -----------------------------------------------------------------
        // 2️⃣  Determine which positions are "visited" by non‑zero values
        // -----------------------------------------------------------------
        boolean[] visited = new boolean[n];
        for (int i = 0; i < n; i++) {
            if (values[i] != 0) {
                visited[values[i] - 1] = true;
            }
        }

        // -----------------------------------------------------------------
        // 3️⃣  Count how many *unvisited* indices belong to each parity
        // -----------------------------------------------------------------
        int[] unvisitedByParity = new int[2];
        for (int i = 0; i < n; i++) {
            if (!visited[i]) {
                unvisitedByParity[(i + 1) % 2]++;
            }
        }

        // -----------------------------------------------------------------
        // 4️⃣  Prepare collections used for the greedy segment analysis
        // -----------------------------------------------------------------
        // queues for distances that are "between" two non‑zero elements
        @SuppressWarnings("unchecked")
        PriorityQueue<Integer>[] twoSideQueues = (PriorityQueue<Integer>[]) new PriorityQueue[2];
        twoSideQueues[0] = new PriorityQueue<>();
        twoSideQueues[1] = new PriorityQueue<>();

        // queues for distances that stretch to the end of the array
        @SuppressWarnings("unchecked")
        PriorityQueue<Integer>[] oneSideQueues = (PriorityQueue<Integer>[]) new PriorityQueue[2];
        oneSideQueues[0] = new PriorityQueue<>();
        oneSideQueues[1] = new PriorityQueue<>();

        // -----------------------------------------------------------------
        // 5️⃣  Analyse the segments between consecutive non‑zero values
        // -----------------------------------------------------------------
        int firstNonZero = findFirstNonZero(values);
        if (firstNonZero == n) {                 // all numbers are zero
            return "1";
        }

        int segmentStart = firstNonZero;
        int curParity = values[firstNonZero] % 2; // parity of the element that starts the segment
        int index = firstNonZero + 1;
        int diff = 0;                             // counts parity‑changes between segments

        while (index < n) {
            if (values[index] == 0) {
                index++;
                continue;
            }

            int nextParity = values[index] % 2;
            if (nextParity != curParity) {
                diff++;                           // a change of parity contributes to the answer
            } else if (index > segmentStart + 1) {
                // distance (excluding the two ends) between the current and previous non‑zero element
                twoSideQueues[nextParity].add(index - segmentStart - 1);
            }

            segmentStart = index;
            curParity = nextParity;
            index++;
        }

        // Distance from the last non‑zero element to the end of the array
        if (segmentStart + 1 < n) {
            oneSideQueues[curParity].add(n - segmentStart - 1);
        }

        // -----------------------------------------------------------------
        // 6️⃣  Greedy removal of already‑covered distances
        // -----------------------------------------------------------------
        for (int side = 0; side < 2; side++) {
            int budget = unvisitedByParity[side];

            // Remove all entries that fit into the current budget – they are already "paid"
            while (!twoSideQueues[side].isEmpty() && twoSideQueues[side].peek() <= budget) {
                budget -= twoSideQueues[side].poll();
            }
            while (!oneSideQueues[side].isEmpty() && oneSideQueues[side].peek() <= budget) {
                budget -= oneSideQueues[side].poll();
            }

            // Remaining entries each represent two endpoints (hence *2) plus any single‑side entries
            diff += twoSideQueues[side].size() * 2 + oneSideQueues[side].size();
        }

        // -----------------------------------------------------------------
        // 7️⃣  Produce the final answer
        // -----------------------------------------------------------------
        return String.valueOf(diff);
    }

    /**
     * Returns the index of the first non‑zero element in the array,
     * or {@code arrayLength} if no such element exists.
     */
    private static int findFirstNonZero(int[] arr) {
        for (int i = 0; i < arr.length; i++) {
            if (arr[i] != 0) {
                return i;
            }
        }
        return arr.length;
    }

    /**
     * Simple fast scanner that mimics the original {@code MyReader}
     * but with clearer naming and no public exposure.
     */
    private static final class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner(Reader reader) {
            this.br = new BufferedReader(reader);
            reloadToken();
        }

        /** Load the next line and create a fresh tokenizer. */
        private void reloadToken() throws IOException {
            String line = br.readLine();
            st = new StringTokenizer(line != null ? line : "");
        }

        String nextToken() throws IOException {
            while (!st.hasMoreTokens()) {
                reloadToken();
            }
            return st.nextToken();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(nextToken());
        }

        /** Reads {@code n} integers from the input and returns them as an array. */
        int[] readIntArray(int n) throws IOException {
            int[] arr = new int[n];
            for (int i = 0; i < n; i++) {
                arr[i] = nextInt();
            }
            return arr;
        }
    }
}

import java.io.*;
import java.util.*;

public class Main {

    /** Parity identifiers used in the DP state. */
    private static final int UNKNOWN = 2; // start state – no previous element
    private static final int EVEN = 0;
    private static final int ODD = 1;

    /** A large but safe constant to represent “infinite” cost. */
    private static final int INF = Integer.MAX_VALUE / 4;

    /** The original input array (filled with 0 where numbers are missing). */
    private final int[] array;

    /** Length of the array. */
    private final int n;

    /** Number of even and odd values that are missing from the array. */
    private int missingEven;
    private int missingOdd;

    /** 4‑dimensional memoization table:
     *  [previous parity][even numbers left][odd numbers left][current index] */
    private final int[][][][] memo;

    /** Constructor – prepares the problem data and initializes memoization. */
    public Main(int[] arr) {
        this.array = arr;
        this.n = arr.length;
        computeMissingCounts();
        initializeMemo();
    }

    /** Count how many even and odd numbers from 1…n are absent (i.e. need to be placed). */
    private void computeMissingCounts() {
        boolean[] seen = new boolean[n + 1];
        for (int v : array) {
            if (v != 0) {
                seen[v] = true;
            }
        }
        for (int i = 1; i <= n; i++) {
            if (!seen[i]) {
                if (i % 2 == 0) {
                    missingEven++;
                } else {
                    missingOdd++;
                }
            }
        }
    }

    /** Allocate the memo table and fill it with –1 (unvisited). */
    private void initializeMemo() {
        memo = new int[3][missingEven + 1][missingOdd + 1][n];
        for (int i = 0; i < memo.length; i++) {
            for (int j = 0; j < memo[i].length; j++) {
                for (int k = 0; k < memo[i][j].length; k++) {
                    Arrays.fill(memo[i][j][k], -1);
                }
            }
        }
    }

    /** Entry point for the DP recursion. Returns the minimal odd‑pair count. */
    public int solve() {
        return dp(UNKNOWN, missingEven, missingOdd, 0);
    }

    /**
     * Recursive DP with memoization.
     *
     * @param prevParity   parity of the element placed immediately before {@code idx}
     * @param evenLeft     how many even numbers are still unused
     * @param oddLeft      how many odd numbers are still unused
     * @param idx          current position in the array
     * @return minimum number of odd pairs that will be formed from {@code idx} onward
     */
    private int dp(int prevParity, int evenLeft, int oddLeft, int idx) {
        if (idx == n) {
            return 0; // no more elements → no more pairs
        }
        if (memo[prevParity][evenLeft][oddLeft][idx] != -1) {
            return memo[prevParity][evenLeft][oddLeft][idx];
        }

        int best = INF;
        int currentValue = array[idx];

        if (currentValue != 0) {
            // Fixed (non‑missing) number – we only need to account for a possible odd pair
            int curParity = currentValue % 2; // 0 → even, 1 → odd
            int cost = (prevParity != UNKNOWN && curParity != prevParity ? 1 : 0);
            int nextPrev = curParity;
            best = dp(nextPrev, evenLeft, oddLeft, idx + 1) + cost;
        } else {
            // Try placing an even number (if any remain)
            if (evenLeft > 0) {
                int cost = (prevParity == ODD ? 1 : 0); // odd → even creates a pair
                best = Math.min(best,
                        dp(EVEN, evenLeft - 1, oddLeft, idx + 1) + cost);
            }
            // Try placing an odd number (if any remain)
            if (oddLeft > 0) {
                int cost = (prevParity == EVEN ? 1 : 0); // even → odd creates a pair
                best = Math.min(best,
                        dp(ODD, evenLeft, oddLeft - 1, idx + 1) + cost);
            }
        }

        memo[prevParity][evenLeft][oddLeft][idx] = best;
        return best;
    }

    /** Simple driver that reads input, runs the solver, and prints the answer. */
    public static void main(String[] args) throws IOException {
