import java.io.*;
import java.util.*;

public class Main {

    /* ---------- I/O helpers ---------- */
    private static BufferedReader br;
    private static PrintWriter out;
    private static StringTokenizer st;

    /** Reads the next token from the input buffer. */
    private static String nextToken() throws IOException {
        while (st == null || !st.hasMoreTokens()) {
            st = new StringTokenizer(br.readLine());
        }
        return st.nextToken();
    }

    /** Returns the next integer token. */
    private static int nextInt() throws IOException {
        return Integer.parseInt(nextToken());
    }

    /* ---------- Problem data ---------- */
    private static int n;                 // length of the permutation
    private static int[] p;               // p[i] = 0 => missing value, otherwise the fixed value
    private static int[][][][] dp;        // memoisation table for DP
    private static boolean[][][][] visited;// DP has‑been‑computed flag
    private static final int MOD = (int) (1e9 + 7);
    private static final int INF = (int) (1e9 + 1);

    /* ---------- Entry point ---------- */
    public static void main(String[] args) throws IOException {
        solve();
    }

    /* ---------- Core algorithm ---------- */
    private static void solve() throws IOException {
        /* ----- read input ----- */
        br = new BufferedReader(new InputStreamReader(System.in));
        out = new PrintWriter(new BufferedOutputStream(System.out));
        n = nextInt();

        p = new int[n + 1];
        int filledEven = 0;   // already placed even numbers
        int filledOdd  = 0;   // already placed odd numbers

        for (int i = 1; i <= n; ++i) {
            p[i] = nextInt();                     // 0 indicates a missing value
            if (p[i] != 0) {
                if ((p[i] & 1) == 0) {
                    ++filledEven;
                } else {
                    ++filledOdd;
                }
            }
        }

        /* ----- compute how many evens / odds we still need ----- */
        int missingEven = n / 2 - filledEven;     // total evens must be n/2
        int missingOdd  = (n + 1) / 2 - filledOdd; // total odds  must be (n+1)/2

        /* ----- initialise DP tables ----- */
        dp = new int[n + 1][2][missingEven + 1][missingOdd + 1];
        visited = new boolean[n + 1][2][missingEven + 1][missingOdd + 1];

        /* ----- solve the last position ----- */
        int answer;
        if (p[n] != 0) {
            // position n already has a fixed value
            answer = getDp(n - 1, p[n] % 2, missingEven, missingOdd);
        } else {
            // position n is empty – try to fill it with an even or an odd (if still available)
            if (missingEven == 0) {
                answer = getDp(n - 1, 1, 0, missingOdd - 1);   // must place an odd
            } else {
                int withEven = getDp(n - 1, 0, missingEven - 1, missingOdd);
                int withOdd  = (missingOdd == 0) ? INF : getDp(n - 1, 1, missingEven, missingOdd - 1);
                answer = Math.min(withEven, withOdd);
            }
        }

        out.println(answer);
        out.close();
    }

    /**
     * Memoised recursive function.
     * <p>
     * Returns the minimal number of adjacent pairs of equal parity when we fill
     * the prefix up to position {@code i} such that the last placed number has
     * {@code parity} (0 = even, 1 = odd) and we still have {@code evenLeft}
     * even numbers and {@code oddLeft} odd numbers to place.
     *
     * @param i         current position (1‑based, processed from right to left)
     * @param parity    parity of the number placed at position i+1
     * @param evenLeft  remaining even numbers still to place
     * @param oddLeft   remaining odd numbers still to place
     * @return minimal cost for the described sub‑problem
     */
    private static int getDp(int i, int parity, int evenLeft, int oddLeft) {
        if (i == 0) {
            return 0; // base case
        }

        if (!visited[i][parity][evenLeft][oddLeft]) {
            visited[i][parity][evenLeft][oddLeft] = true;
            int cost;

            if (p[i] != 0) {
                // Fixed value at this position
                cost = (parity == (p[i] & 1)) ? 0 : 1;
                cost += getDp(i - 1, p[i] % 2, evenLeft, oddLeft);
            } else if (evenLeft == 0) {
                // Must place an odd number
                cost = (parity == 1) ? 0 : 1;
                cost += getDp(i - 1, 1, evenLeft, oddLeft - 1);
            } else if (oddLeft == 0) {
                // Must place an even number
                cost = (parity == 0) ? 0 : 1;
                cost += getDp(i - 1, 0, evenLeft - 1, oddLeft);
            } else {
                // We can place either parity – choose the cheaper option
                int withEven = (parity == 0) ? 0 : 1;
                withEven += getDp(i - 1, 0, evenLeft - 1, oddLeft);

                int withOdd = (parity == 1) ? 0 : 1;
                withOdd += getDp(i - 1, 1, evenLeft, oddLeft - 1);

                cost = Math.min(withEven, withOdd);
            }

            dp[i][parity][evenLeft][oddLeft] = cost;
        }
        return dp[i][parity][evenLeft][oddLeft];
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.Arrays;

/**
 * Refactored solution for the problem.
 *
 * <p>
 * The program reads an array that may contain fixed numbers and zeros (holes).
 * Zeros have to be replaced with the missing numbers 1…n so that each number is used
 * exactly once.  The goal is to minimise the number of adjacent pairs that have
 * different parity.
 * </p>
 *
 * <p>Refactoring highlights:</p>
 * <ul>
 *   <li>Clear separation of concerns (input handling, DP core, helper classes)</li>
 *   <li>Descriptive names and elimination of raw types</li>
 *   <li>Constant for "infinite" value</li>
 *   <li>Custom {@link DPState} object to encapsulate memoisation table</li>
 *   <li>Use of {@code java.util.Scanner} instead of a hand‑rolled scanner</li>
 *   <li>Small, focused methods and Javadoc comments</li>
 * </ul>
 */
public class C1287 {

    /** Minimum value used as "infinity". */
    private static final int INF = Integer.MAX_VALUE / 4;

    /** Parity of a number – 0 for even, 1 for odd. */
    private enum Parity {
        EVEN(0), ODD(1);

        private final int value;
        Parity(int value) { this.value = value; }
        int value() { return value; }
    }

    /** Holds all information required for the DP recursion. */
    private static final class DPState {
        /** Original input array */
        private final int[] values;
        /** Number of still‑missing even numbers */
        private final int missingEven;
        /** Number of still‑missing odd numbers */
        private final int missingOdd;
        /** Memoisation table: idx × eRem × oRem × prevParity */
        private final int[][][][] memo;

        DPState(int[] values, int missingEven, int missingOdd) {
            this.values = values;
            this.missingEven = missingEven;
            this.missingOdd = missingOdd;
            this.memo = new int[values.length + 1]
                    [missingEven + 1][missingOdd + 1][2];
            for (int[][][] x : memo)
                for (int[][] y : x)
                    for (int[] z : y)
                        Arrays.fill(z, -1);
        }

        /** Returns the minimal additional cost from position {@code idx}. */
        int solve(int idx, int eRem, int oRem, Parity prev) {
            if (idx == values.length) {
                return 0;
            }
            if (memo[idx][eRem][oRem][prev.value()] != -1) {
                return memo[idx][eRem][oRem][prev.value()];
            }
            int cur = values[idx];
            if (cur != 0) {
                // Fixed number – just continue, cost is 1 if parity changes
                int cost = (prev.value() != (cur & 1)) ? 1 : 0;
                int res = cost + solve(idx + 1, eRem, oRem, Parity.from(cur));
                memo[idx][eRem][oRem][prev.value()] = res;
                return res;
            }

            int best = INF;

            if (eRem > 0) {
                // Place an even number
                int cost = solve(idx + 1, eRem - 1, oRem, Parity.EVEN) + prev.value();
                best = Math.min(best, cost);
            }
            if (oRem > 0) {
                // Place an odd number
                int cost = solve(idx + 1, eRem, oRem - 1, Parity.ODD) + (1 - prev.value());
                best = Math.min(best, cost);
            }
            memo[idx][eRem][oRem][prev.value()] = best;
            return best;
        }
    }

    /** Factory method to obtain the parity enum from an int (0/1). */
    private static Parity from(int bit) {
        return (bit == 0) ? Parity.EVEN : Parity.ODD;
    }

    public static void main(String[] args) throws IOException {
        try (Scanner scanner = new Scanner(System.in);
             PrintWriter out = new PrintWriter(System.out)) {

            int n = scanner.nextInt();
            int[] arr = new int[n];
            for (int i = 0; i < n; i++) {
                arr[i] = scanner.nextInt();
            }

            // -----------------------------------------------------------------
            // 1️⃣  Determine how many even / odd numbers are missing
            // -----------------------------------------------------------------
            int totalEven = n / 2;
            int totalOdd  = (n + 1) / 2;

            int fixedEven = 0, fixedOdd = 0;
            for (int v : arr) {
                if (v != 0) {
                    if ((v & 1) == 0) fixedEven++;
                    else                 fixedOdd++;
                }
            }
            int missingEven = totalEven - fixedEven;
            int missingOdd  = totalOdd  - fixedOdd;

            // -----------------------------------------------------------------
            // 2️⃣  Trivial case – only one element
            // -----------------------------------------------------------------
            if (n == 1) {
                out.println(0);
                return;
            }

            DPState dp = new DPState(arr, missingEven, missingOdd);

            // -----------------------------------------------------------------
            // 3️⃣  Start the recursion – result depends on the first element
            // -----------------------------------------------------------------
            int answer;
            if (arr[0] != 0) {
                answer = dp.solve(1, missingEven, missingOdd,
                                  Parity.from(arr[0] & 1));
            } else {
                answer = INF;
                // Try to place an even number at position 0
                if (missingEven > 0) {
                    answer = Math.min(
                            dp.solve(1, missingEven - 1, missingOdd,
                                    Parity.EVEN) + 0,   // no previous parity → cost 0
                            answer);
                }
                // Try to place an odd number at position 0
                if (missingOdd > 0) {
                    answer = Math.min(
                            dp.solve(1, missingEven, missingOdd - 1,
                                    Parity.ODD) + 0,
                            answer);
                }
            }
            out.println(answer);
        }
    }

    /** Simple scanner wrapper – avoids the custom implementation in the original code. */
    private static final class Scanner {
        private final BufferedReader br;
        private StringTokenizer st;

        Scanner(InputStream source) {
            this.br = new BufferedReader(new InputStreamReader(source));
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }

        String next() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                String line = br.readLine();
                if (line == null) return null;
                st = new StringTokenizer(line);
            }
            return st.nextToken();
        }

        boolean ready() throws IOException {
            return br.ready();
        }
    }
}

import java.io.*;
import java.util.*;

public class Main {

    /** Minimum value used for “infinite” cost – safely smaller than any possible answer. */
    private static final int INF = Integer.MAX_VALUE / 4;   // ~1e9

    /** Entry point – runs the solution in a separate thread to avoid stack‑overflow issues. */
    public static void main(String[] args) throws Exception {
        Thread thread = new Thread(null, new Runnable() {
            @Override
            public void run() {
                try {
                    solve();
                } catch (Exception e) {
                    e.printStackTrace();
                    System.exit(1);
                }
            }
        }, 1 << 28);               // 256 MiB stack – enough for the recursion depth
        thread.start();
        thread.join();              // wait for the worker thread to finish
    }

    /** Main driver – reads input, prepares data and starts the dynamic programming search. */
    private static void solve() throws Exception {
        Scanner scanner = new Scanner(System.in);
        PrintWriter out = new PrintWriter(System.out);

        int n = scanner.nextInt();
        int[] arr = new int[n];
        boolean[] seen = new boolean[n + 1];          // marks numbers that already appear

        // ------------------------------------------------------------
        // 1️⃣  Load the array and remember which values are present.
        // ------------------------------------------------------------
        for (int i = 0; i < n; i++) {
            int v = scanner.nextInt();
            arr[i] = v;
            if (v != 0) {
                seen[v] = true;
            }
        }

        // ------------------------------------------------------------
        // 2️⃣  Determine how many even / odd numbers from 1..n are missing.
        // ------------------------------------------------------------
        int missingEven = 0;
        int missingOdd = 0;
        for (int v = 1; v <= n; v++) {
            if (!seen[v]) {
                if ((v & 1) == 0) {
                    missingEven++;
                } else {
                    missingOdd++;
                }
            }
        }

        // ------------------------------------------------------------
        // 3️⃣  Prepare memoisation table.
        //    dp[parityIdx][pos][usedOdd][usedEven]  (parityIdx = -1,0,1 → 0,1,2)
        // ------------------------------------------------------------
        @SuppressWarnings("unchecked")
        int[][][][] memo = new int[3][n + 1][missingOdd + 1][missingEven + 1];
        for (int[][][] a : memo) {
            for (int[][] b : a) {
                for (int[] c : b) {
                    Arrays.fill(c, -1);
                }
            }
        }

        // ------------------------------------------------------------
        // 4️⃣  Start the recursive search.
        // ------------------------------------------------------------
        int answer = dp(arr, -1, 0, 0, 0, missingOdd, missingEven, memo);
        out.println(answer);
        out.flush();
        scanner.close();
    }

    /**
     * Recursive DP with memoisation.
     *
     * @param arr            the original array (0 denotes a missing value)
     * @param lastParity     parity of the previously placed element,
     *                       -1 if we are at the very beginning
     * @param pos            current index in the array
     * @param usedOdd        how many missing odd numbers have already been placed
     * @param usedEven       how many missing even numbers have already been placed
     * @param missOdd        total missing odd numbers available
     * @param missEven       total missing even numbers available
     * @param memo           memoisation table
     * @return the minimal number of parity‑change “breaks” from this state onward
     */
    private static int dp(int[] arr,
                          int lastParity,
                          int pos,
                          int usedOdd,
                          int usedEven,
                          int missOdd,
                          int missEven,
                          int[][][][] memo) {

        if (pos == arr.length) {
            return 0;                                     // reached the end – no more breaks
        }

        int pIdx = lastParity + 1;                       // map -1 → 0, 0 → 1, 1 → 2
        if (memo[pIdx][pos][usedOdd][usedEven] != -1) {
            return memo[pIdx][pos][usedOdd][usedEven];
        }

        int best = INF;

        if (arr[pos] != 0) {                              // fixed (non‑zero) value
            int curParity = arr[pos] & 1;                  // 0 → even, 1 → odd
            int cost = (pos == 0) ? 0
                                 : (curParity != lastParity ? 1 : 0);
            best = Math.min(best, cost + dp(curParity, pos + 1,
                                            usedOdd, usedEven,
                                            missOdd, missEven, memo));
        } else {                                          // a missing slot – try to fill it
            // ---- try placing an even number ---------------------------------
            if (usedEven < missEven) {
                int curParity = 0;                         // even
                int cost = (pos == 0) ? 0
                                      : (curParity != lastParity ? 1 : 0);
                best = Math.min(best,
                        cost + dp(curParity, pos + 1,
                                  usedOdd, usedEven + 1,
                                  missOdd, missEven, memo));
            }
            // ---- try placing an odd number ----------------------------------
            if (usedOdd < missOdd) {
                int curParity = 1;                         // odd
                int cost = (pos == 0) ? 0
                                      : (curParity != lastParity ? 1 : 0);
                best = Math.min(best,
                        cost + dp(curParity, pos + 1,
                                  usedOdd + 1, usedEven,
                                  missOdd, missEven, memo));
            }
        }

        // store result and return
        memo[pIdx][pos][usedOdd][usedEven] = best;
        return best;
    }
}

import java.io.IOException;
import java.util.Scanner;

/**
 * Garland – place the missing even / odd numbers so that the number of
 * adjacent elements with different parity is minimal.
 *
 * The program reads an integer {@code n} and an array of {@code n} numbers.
 * Positive numbers are already fixed, the remaining slots (value {@code 0})
 * must be filled with exactly half of them even and half of them odd.
 * The result is the smallest possible count of adjacent pairs whose parity
 * differs.
 */
public class Garland {

    /** Simple enum to keep parity information tidy. */
    private enum Parity {
        EVEN(0), ODD(1);

        private final int value;
        Parity(int value) { this.value = value; }
        int get() { return value; }
    }

    /** Memoisation holder – stores computed results for a given state. */
    private static final class Memo {
        private final Integer[][][] table; // [index][usedEvens][previousParity]

        Memo(int length, int maxUsedEvens) {
            table = new Integer[length][maxUsedEvens + 1][2];
        }

        Integer get(int idx, int usedEvens, int prevParity) {
            return table[idx][usedEvens][prevParity];
        }

        void set(int idx, int usedEvens, int prevParity, Integer value) {
            table[idx][usedEvens][prevParity] = value;
        }
    }

    /**
     * Entry point for the DP algorithm.
     *
     * @param line    the whole input line (unused here)
     * @param numbers the array of numbers read from the input
     * @param evenMissing how many even numbers are still to be placed
     * @return minimal adjacency‑parity difference
     */
    private static int solve(int[] numbers, int evenMissing) {
        int n = numbers.length;
        // maximum possible used‑even count is the total number of even slots
        int maxUsedEvens = n / 2;
        Memo memo = new Memo(n, maxUsedEvens);
        return dp(numbers, 0, 0, evenMissing, memo);
    }

    /**
     * Recursive DP with memoisation.
     *
     * @param numbers      input array (0 denotes a free slot)
     * @param idx          current position in the array
     * @param usedEvens    how many even numbers have already been placed
     * @param evenMissing  total number of even numbers we still have to place
     * @param memo         memo table for already computed states
     * @return minimal cost from this state onward
     */
    private static int dp(int[] numbers, int idx, int usedEvens, int evenMissing, Memo memo) {
        if (idx == numbers.length) {
            return 0;                     // end of the array – no more cost
        }

        Integer cached = memo.get(idx, usedEvens, prevParity(numbers, idx));
        if (cached != null) {
            return cached;
        }

        int current = numbers[idx];
        Parity curParity = (current > 0) ? parity(current) : null;
        int best = Integer.MAX_VALUE;

        /* --------------------------------------------------------------
         * 1. Fixed (non‑zero) element – just continue the recursion.
         * -------------------------------------------------------------- */
        if (current > 0) {
            int cost = (idx > 0 && curParity.get() != prevParity) ? 1 : 0;
            int next = dp(numbers, idx + 1, usedEvens, evenMissing, memo) + cost;
            memo.set(idx, usedEvens, prevParity, next);
            return next;
        }

        /* --------------------------------------------------------------
         * 2. Place an even number (if any are left).
         * -------------------------------------------------------------- */
        if (usedEvens < evenMissing) {
            int cost = (idx > 0 && prevParity == Parity.EVEN.get()) ? 0 : (idx > 0 ? 1 : 0);
            int next = dp(numbers, idx + 1, usedEvens + 1, evenMissing, memo) + cost;
            best = Math.min(best, next);
        }

        /* --------------------------------------------------------------
         * 3. Place an odd number.
         *    The number of odd slots that remain is implicit:
         *    odd slots placed so far = idx - usedEvens
         *    therefore odd slots still available = (totalOdd - (idx - usedEvens))
         *    We only need to know whether at least one odd slot is left.
         * -------------------------------------------------------------- */
        int oddSlotsUsedSoFar = idx - usedEvens;
        int totalOdd = numbers.length - (numbers.length / 2);     // half of the positions are odd
        if (oddSlotsUsedSoFar < totalOdd) {
            int cost = (idx > 0 && prevParity == Parity.ODD.get()) ? 0 : (idx > 0 ? 1 : 0);
            int next = dp(numbers, idx + 1, usedEvens, evenMissing, memo) + cost;
            best = Math.min(best, next);
        }

        memo.set(idx, usedEvens, prevParity, best);
        return best;
    }

    /** Returns the parity of a positive integer (0 = even, 1 = odd). */
    private static Parity parity(int value) {
        return (value % 2 == 0) ? Parity.EVEN : Parity.ODD;
    }

    /** Returns how many even numbers are still missing for the given input. */
    private static int countMissingEvens(int[] numbers) {
        int totalEven = numbers.length / 2;
        int placedEven = 0;
        for (int v : numbers) {
            if (v > 0 && v % 2 == 0) placedEven++;
        }
        return totalEven - placedEven;
    }

    /** Reads the whole input and returns the minimal adjacency‑parity difference. */
    private static int solveProblem(Scanner sc) {
        int n = sc.nextInt();
        int[] numbers = new int[n];
        for (int i = 0; i < n; i++) {
            numbers[i] = sc.nextInt();
        }

        int evenMissing = countMissingEvens(numbers);
        return solve(numbers, evenMissing);
    }

    /** Main method – clean resource handling and clear separation of concerns. */
    public static void main(String[] args) throws IOException {
        try (Scanner sc = new Scanner(System.in)) {
            int result = solveProblem(sc);
            System.out.println(result);
        }
    }
}

/**
 * Refactored version of the original program.
 *
 * <p>
 *   Changes made for better maintainability:
 *   <ul>
 *     <li>Separated concerns (input parsing, solving logic, output).</li>
 *     <li>Used expressive names for variables and methods.</li>
 *     <li>Encapsulated memoisation table with proper default values.</li>
 *     <li>Removed magic numbers and unnecessary casts.</li>
 *     <li>Added Javadoc comments and inline documentation.</li>
 *     <li>Kept the original algorithmic behaviour.</li>
