 */
import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.Arrays;

/**
 * Main entry point.
 */
public class Main {

    /**
     * Fast scanner that reads whitespace‑separated tokens from {@code System.in}.
     */
    private static final class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner(InputStreamReader source) {
            this.br = new BufferedReader(source);
        }

        /** Returns the next token, fetching a new line if necessary. */
        private String next() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                String line = br.readLine();
                if (line == null) {
                    return null;
                }
                st = new StringTokenizer(line);
            }
            return st.nextToken();
        }

        /** Reads the next integer token. */
        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }

    /**
     * Core solving logic.
     *
     * <p>This class implements a depth‑first search with memoisation to minimise
     * the number of parity changes required when filling the missing numbers.</p>
     */
    private static final class Solver {

        /** Length of the input sequence. */
        private int n;

        /** Original numbers from the input (0 represents a missing value). */
        private int[] values;

        /** Number of even (or odd) values still missing. */
        private int evenMissing;
        private int oddMissing;

        /**
         * DP table that stores the minimal number of parity changes needed.
         *
         * <p>
         *   {@code dp[idx][eLeft][oLeft][prevParity]}
         *   – {@code idx}: current position,
         *   – {@code eLeft}/{@code oLeft}: how many even/odd numbers are still unused,
         *   – {@code prevParity}: parity of the last placed element (null → -1)
         * </p>
         */
        private Integer[][][][] dp;

        /**
         * Entry point called from {@link Main#main(String)}.
         *
         * @param testNumber dummy – kept for compatibility with original signature.
         * @param in         scanner used for input.
         * @param out        printer for output.
         */
        void solve(int testNumber, FastScanner in, PrintWriter out) {
            try {
                readInput(in);
                if (values == null) {
                    return;                     // no input → nothing to do
                }
                computeResult(out);
            } catch (Exception e) {
                out.println("Error while solving");
                e.printStackTrace();
            }
        }

        /** Reads the entire test case from the scanner. */
        private void readInput(FastScanner in) throws IOException {
            n = in.nextInt();

            values = new int[n];
            boolean[] seen = new boolean[n + 1];   // 1‑based marking of existing numbers

            for (int i = 0; i < n; i++) {
                int v = in.nextInt();
                values[i] = v;
                if (v > 0) {
                    seen[v] = true;
                }
            }

            // -----------------------------------------------------------------
            // Count how many even and odd numbers are missing.
            // -----------------------------------------------------------------
            evenMissing = 0;
            oddMissing = 0;
            for (int i = 1; i <= n; i++) {
                if (!seen[i]) {
                    if ((i & 1) == 0) {   // even
                        evenMissing++;
                    } else {
                        oddMissing++;
                    }
                }
            }

            // -----------------------------------------------------------------
            // Initialise the memoisation table with {@code null} (meaning "unknown").
            // -----------------------------------------------------------------
            dp = new Integer[n][evenMissing + 1][oddMissing + 1][2];
            initialiseDpWithNulls();

            int answer = dfs(0, evenMissing, oddMissing, null);
            out.println(answer);
        }

        /** Fills the DP table with {@code null} values. */
        private void initialiseDpWithNulls() {
            for (Integer[][][][] slice1 : dp) {
                for (Integer[][][][] slice2 : slice1) {
                    for (Integer[][] slice3 : slice2) {
                        Arrays.fill(slice3, null);
                    }
                }
            }
        }

        /**
         * Depth‑first search with memoisation.
         *
         * @param idx       current index in {@code values}
         * @param eLeft     how many even numbers are still available
         * @param oLeft     how many odd numbers are still available
         * @param prevParity parity of the element placed right before {@code idx}
         * @return minimal number of parity changes needed from this state onward
         */
        private int dfs(int idx, int eLeft, int oLeft, Integer prevParity) {
            if (idx == n) {
                return 0;                     // reached the end of the sequence
            }

            int stateIdx = prevParity == null ? 0 : prevParity; // DP uses 0/1 as indices
            if (dp[idx][eLeft][oLeft][stateIdx] != null) {
                return dp[idx][eLeft][oLeft][stateIdx];
            }

            int minimalCost;

            // -----------------------------------------------------------------
            // Case 1 – the current cell already contains a fixed number.
            // -----------------------------------------------------------------
            if (values[idx] != 0) {
                int curParity = values[idx] % 2;
                int costWithPrev = (prevParity != null && curParity != prevParity) ? 1 : 0;
                minimalCost = costWithPrev + dfs(idx + 1, eLeft, oLeft, curParity);
            }
            // -----------------------------------------------------------------
            // Case 2 – cell is empty, we must fill it with an unused even or odd.
            // -----------------------------------------------------------------
            else {
                int costIfEven = Integer.MAX_VALUE;
                int costIfOdd  = Integer.MAX_VALUE;

                if (eLeft > 0) {
                    int costWithPrev = (prevParity != null && 0 != prevParity) ? 1 : 0;
                    costIfEven = costWithPrev + dfs(idx + 1, eLeft - 1, oLeft, 0);
                }

                if (oLeft > 0) {
                    int costWithPrev = (prevParity != null && 1 != prevParity) ? 1 : 0;
                    costIfOdd = costWithPrev + dfs(idx + 1, eLeft, oLeft - 1, 1);
                }

                minimalCost = Math.min(costIfEven, costIfOdd);
            }

            dp[idx][eLeft][oLeft][stateIdx] = minimalCost;
            return minimalCost;
        }

        /** Writes the computed result to the supplied printer. */
        private void computeResult(PrintWriter out) {
            // All heavy lifting happens in {@link #solve(int, FastScanner, PrintWriter)}.
        }
    }

    /** Program entry point. */
    public static void main(String[] args) throws Exception {
        // Read from standard input; replace with a file path if desired:
        // FastScanner scanner = new FastScanner(new FileReader("input.txt"));
        FastScanner scanner = new FastScanner(new InputStreamReader(System.in));
        PrintWriter out = new PrintWriter(System.out, true);

        new Solver().solve(1, scanner, out);
        out.close();
    }
}

