/**
 * Fast buffered scanner that reads tokens from an {@link InputStream}.
 * It mimics the behaviour of the original {@code InputReader} but is more compact.
 */
class FastScanner {
    private final InputStream stream;
    private final byte[] buffer = new byte[1 << 16];
    private int bytesRead = 0;
    private int currentByte = 0;

    FastScanner(InputStream stream) {
        this.stream = stream;
    }

    private int readByte() throws IOException {
        if (currentByte >= bytesRead) {
            bytesRead = stream.read(buffer);
            currentByte = 0;
            if (bytesRead == -1) {
                throw new EOFException();
            }
        }
        return buffer[currentByte++];
    }

    /** Reads the next integer from the input stream. */
    int nextInt() {
        int c = skipWhitespace();
        boolean negative = false;
        if (c == '-') {
            negative = true;
            c = nextNonWhitespace();
        }
        int value = 0;
        do {
            if (c < '0' || c > '9') {
                throw new NumberFormatException();
            }
            value = value * 10 + (c - '0');
            c = nextNonWhitespace();
        } while (true);
    }

    /** Advances until a non‑whitespace character is found. */
    private int skipWhitespace() throws IOException {
        int c;
        do {
            c = readByte();
        } while (isWhitespace(c));
        return c;
    }

    private static boolean isWhitespace(int c) {
        return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
    }

    /** Returns the next non‑whitespace character. */
    private int nextNonWhitespace() throws IOException {
        int c = readByte();
        while (isWhitespace(c)) {
            c = readByte();
        }
        return c;
    }
}

/**
 * Small wrapper around a {@link PrintWriter} that provides type‑safe printing.
 */
class Printer {
    private final PrintWriter writer;

    Printer(OutputStream stream) {
        this.writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(stream)));
    }

    /** Prints an integer followed by a newline. */
    void println(int value) {
        writer.println(value);
    }

    /** Flushes the underlying writer. */
    void flush() {
        writer.flush();
    }

    /** Closes the writer. */
    void close() {
        writer.close();
    }
}

/**
 * Core algorithm that solves the problem.
 * All public methods are documented to clarify their purpose.
 */
class Solver {

    /** Constants that represent the parity of the sentinel borders. */
    private static final int BORDER_ODD  = 1;
    private static final int BORDER_EVEN = 2;

    /** Upper bound used as a sentinel “infinite” answer. */
    private static final int INF = 1_000;

    /**
     * Solves a single test case.
     *
     * @param scanner input scanner
     * @param printer output printer
     */
    void solve(FastScanner scanner, Printer printer) {
        int n = scanner.nextInt();

        // Array is deliberately sized n+2 to hold two extra sentinel values (indices 0 and n+1).
        int[] values = new int[n + 2];

        // Fill positions 1..n with the supplied numbers.
        for (int i = 1; i <= n; i++) {
            values[i] = scanner.nextInt();
        }

        // Determine how many odd/even numbers are still missing.
        int oddMissing   = (n + 1) / 2;   // total required odd numbers
        int evenMissing  = n - oddMissing; // total required even numbers

        // Subtract numbers that are already present (non‑zero entries).
        for (int i = 1; i <= n; i++) {
            if (values[i] != 0) {
                if ((values[i] & 1) == 1) {
                    oddMissing--;
                } else {
                    evenMissing--;
                }
            }
        }

        // The answer starts with a large sentinel value; we will minimise it.
        int best = INF;

        // Try every combination of left/right border parity: odd (1) or even (2).
        for (int left : new int[]{BORDER_ODD, BORDER_EVEN}) {
            for (int right : new int[]{BORDER_ODD, BORDER_EVEN}) {
                values[0] = left;
                values[n + 1] = right;

                int candidate = computeResult(values, oddMissing, evenMissing);
                best = Math.min(best, candidate);
            }
        }

        printer.println(best);
    }

    /**
     * Computes the cost (penalty) for a particular border configuration.
     *
     * @param values      array already containing the left/right borders
     * @param oddLeft     remaining odd numbers to be placed
     * @param evenLeft    remaining even numbers to be placed
     * @return the minimal additional cost for this configuration
     */
    private int computeResult(int[] values, int oddLeft, int evenLeft) {
        List<Segment> oddSegments  = new ArrayList<>();
        List<Segment> evenSegments = new ArrayList<>();

        int i = 0;               // start of the current segment
        int transitions = 0;     // count of forced odd/even transitions

        // Walk through the array, skipping zeros.
        for (int j = 1; j < values.length; j++) {
            // Move j forward until a non‑zero element is found.
            while (j < values.length && values[j] == 0) {
                j++;
            }

            // Determine whether the current gap forces a parity transition.
            if ((values[i] + values[j]) % 2 != 0) {
                transitions++; // different parity → forced transition
            } else {
                // Same parity → store the gap length and its preceding parity.
                Segment seg = new Segment(j - i - 1, values[i] % 2);
                (seg.parity == 1 ? oddSegments : evenSegments).add(seg);
            }

            i = j; // advance the segment start
        }

        // Sort segments by length (ascending) – this yields the optimal placement order.
        oddSegments.sort(Comparator.comparingInt(s -> s.length));
        evenSegments.sort(Comparator.comparingInt(s -> s.length));

        int cost = transitions; // baseline cost from mandatory transitions

        // Allocate odd‑length gaps using the remaining odd numbers.
        for (Segment seg : oddSegments) {
            if (seg.length <= oddLeft) {
                oddLeft -= seg.length;
            } else {
                cost += 2; // cannot fill completely → penalty
            }
        }

        // Allocate even‑length gaps using the remaining even numbers.
        for (Segment seg : evenSegments) {
            if (seg.length <= evenLeft) {
                evenLeft -= seg.length;
            } else {
                cost += 2; // penalty again
            }
        }

        return cost;
    }

    /**
     * Simple data holder for a contiguous block of zeros (a gap).
     * Implements {@link Comparable} to allow sorting by length and parity.
     */
    private static final class Segment implements Comparable<Segment> {
        final int length;   // number of consecutive zeros in the gap
        final int parity;   // parity (odd/even) of the element right before the gap

        Segment(int length, int parity) {
            this.length = length;
            this.parity = parity;
        }

        @Override
        public int compareTo(Segment o) {
            int cmp = Integer.compare(this.length, o.length);
            return (cmp != 0) ? cmp : Integer.compare(this.parity, o.parity);
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Refactored solution for the “minimal alternating cost” problem.
 *
 * <p>Key improvements over the original code:
 *
 * <ul>
 *   <li>Descriptive class and variable names.</li>
 *   <li>Strict separation of input handling, business logic and the DP algorithm.</li>
 *   <li>Use of an {@link Enum} for parity.</li>
 *   <li>Self‑contained {@link FastScanner} that cleanly reads the whole input.</li>
 *   <li>Comments that explain the algorithmic steps.</li>
 *   <li>Pre‑allocation of the memoisation table with {@code java.util.Arrays}</li>
 *   <li>No static fields outside of static helper methods.</li>
 * </ul>
 */
public class Main {

    /** Enum representing the three possible parities used internally. */
    private enum Parity {
        EVEN, ODD, NONE;          // NONE is used only as the initial “previous” value

        /** Returns the numeric parity (0 for even, 1 for odd). */
        int value() {
            return this == EVEN ? 0 : 1;
        }
    }

    /** Holds all mutable state that belongs to a single test case. */
    private static final class State {
        final int[] values;                 // original input numbers
        final boolean[] present;            // which numbers 1..n already exist
        final int missingEvens;             // count of missing even numbers
        final int missingOdds;              // count of missing odd numbers

        State(int n, int[] values, boolean[] present) {
            this.values = values;
            this.present = present;
            this.missingEvens = countMissingEvens(n, values, present);
            this.missingOdds = countMissingOdds(n, values, present);
        }

        /** Count how many even numbers from 1..n are missing. */
        private static int countMissingEvens(int n, int[] vals, boolean[] present) {
            int cnt = 0;
            for (int i = 1; i <= n; ++i) {
                if (!present[i] && i % 2 == 0) ++cnt;
            }
            return cnt;
        }

        /** Count how many odd numbers from 1..n are missing. */
        private static int countMissingOdds(int n, int[] vals, boolean[] present) {
            int cnt = 0;
            for (int i = 1; i <= n; ++i) {
                if (!present[i] && i % 2 == 1) ++cnt;
            }
            return cnt;
        }
    }

    /** Memoisation table used by the DP routine. */
    private static int[][][][] memo; // [idx][missingEvens][missingOdds][prevParity]

    /**
     * Entry point – parses input, prepares the DP table and prints the result.
     */
    public static void main(String[] args) {
        State state = parseInput();
        initializeMemo(state);
        int answer = solve(state, 0, state.missingEvens, state.missingOdds, Parity.NONE);
        System.out.println(answer);
    }

    /** Reads the whole input and builds a {@link State} object. */
    private static State parseInput() {
        FastScanner fs = new FastScanner();
        int n = fs.nextInt();
        int[] arr = new int[n];
        boolean[] present = new boolean[n + 1]; // indices 1..n

        for (int i = 0; i < n; ++i) {
            arr[i] = fs.nextInt();
            if (arr[i] != 0) {
                present[arr[i]] = true;
            }
        }
        return new State(n, arr, present);
    }

    /** Allocates and initializes the memoisation table. */
    private static void initializeMemo(State state) {
        memo = new int[state.values.length + 1]
                [state.missingEvens + 1]
                [state.missingOdds + 1]
                [Parity.values().length];    // EVEN, ODD, NONE

        for (int[][][] outer : memo) {
            for (int[][] inner : outer) {
                for (int[] row : inner) {
                    Arrays.fill(row, -1);    // -1 == “not yet computed”
                }
            }
        }
    }

    /**
     * Recursive DP that returns the minimal cost.
     *
     * @param idx           current index in the original array
     * @param evensLeft     how many even numbers are still unused
     * @param oddsLeft      how many odd numbers are still unused
     * @param prevParity    parity of the previously placed element
     * @return minimal cost from this state onward
     */
    private static int solve(State state, int idx, int evensLeft, int oddsLeft, Parity prevParity) {
        if (memo[idx][evensLeft][oddsLeft][prevParity.value()] != -1) {
            return memo[idx][evensLeft][oddsLeft][prevParity.value()];
        }

        // Base case – reached the end of the array
        if (idx == state.values.length) {
            memo[idx][evensLeft][oddsLeft][prevParity.value()] = 0;
            return 0;
        }

        int result = -1;
        int current = state.values[idx];

        if (current != 0) {                                 // Fixed (non‑zero) number
            int curParity = Parity.valueOf(current % 2 == 0 ? "EVEN" : "ODD");
            int cost = (curParity == prevParity ? 0 : 1) + solve(state, idx + 1,
                    evensLeft, oddsLeft, curParity);
            result = cost;
        } else {                                            // Placeholder – can be even or odd
            int costIfEven = Integer.MAX_VALUE / 2;
            if (evensLeft > 0) {
                int curParity = Parity.EVEN;
                costIfEven = (curParity == prevParity ? 0 : 1) + solve(state,
                        idx + 1, evensLeft - 1, oddsLeft, curParity);
            }

            int costIfOdd = Integer.MAX_VALUE / 2;
            if (oddsLeft > 0) {
                int curParity = Parity.ODD;
                costIfOdd = (curParity == prevParity ? 0 : 1) + solve(state,
                        idx + 1, evensLeft, oddsLeft - 1, curParity);
            }

            result = Math.min(costIfEven, costIfOdd);
        }

        // Adjust for the artificial “NONE” initial parity (the first comparison must not count)
        if (prevParity == Parity.NONE) {
            result--;
        }

        memo[idx][evensLeft][oddsLeft][prevParity.value()] = result;
        return result;
    }

    /** Simple fast scanner used throughout the program. */
    private static final class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner() {
            this(System.in);
        }

        FastScanner(InputStream in) {
            this.br = new BufferedReader(new InputStreamReader(in));
        }

        /** Returns the next non‑empty token or reads a new line until one is obtained. */
        private String nextToken() throws IOException {
            while (st == null || !st.hasMoreElements()) {
                String line = br.readLine();
                if (line == null) {
                    return null;
                }
                st = new StringTokenizer(line);
            }
            return st.nextToken();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(nextToken());
        }
    }
}

import java.util.Scanner;

/**
 * Refactored implementation of the original combinatorial DP solution.
 *
 * <p>Key improvements over the original version:
 *
 * <ul>
 *   <li>All magic numbers are replaced by well‑named {@code static final} constants.</li>
 *   <li>The unused {@code pair} class has been removed.</li>
 *   <li>Method names, variable names and field names follow conventional Java naming.</li>
 *   <li>A dedicated {@code visited} table replaces the “zero‑means‑uncomputed” hack.</li>
 *   <li>Logging‑friendly comments and Javadoc explain the purpose of each logical block.</li>
 *   <li>Try‑with‑resources ensures the {@code Scanner} is closed automatically.</li>
 * </ul>
 *
 * <p>The algorithm still uses memoisation to avoid recomputations, but the code is now
 * easier to understand and extend.
 */
public final class Main {

    /** Maximum length of the input array that the algorithm can handle. */
    private static final int MAX_N = 105;

    /** Maximum number of “even‑type” slots (including zeros). */
    private static final int MAX_EVEN = 100;

    /** Maximum number of “odd‑type” slots. */
    private static final int MAX_ODD = 100;

    /** A sentinel value that is larger than any possible cost. */
    private static final int INF = Integer.MAX_VALUE;

    /** Memoisation table:  dp[pos][remainingEven][remainingOdd][lastParity]. */
    private static final int[][][][] dp = new int[MAX_N][MAX_EVEN][MAX_ODD][2];

    /** Visited flag table – tells whether a DP cell has already been computed. */
    private static final boolean[][][][] visited = new boolean[MAX_N][MAX_EVEN][MAX_ODD][2];

    /** Input sequence read from standard input. */
    private static int[] values;

    /** Private constructor – this class only contains static helpers. */
    private Main() { }

    /** Entry point of the program. */
    public static void main(String[] args) {
        try (Scanner sc = new Scanner(System.in)) {
            solve();
        }
    }

    /**
     * Reads the input, sets up the DP parameters and prints the minimal answer.
     */
    private static void solve() {
        int n = sc.nextInt();               // total length of the sequence
        values = new int[n];

        // The required number of even‑type and odd‑type positions.
        int requiredEven = n / 2;
        int requiredOdd  = n - requiredEven;

        // Fill the sequence and adjust the counters according to their parity.
        for (int i = 0; i < n; i++) {
            values[i] = sc.nextInt();
            if (values[i] == 0) {
                continue;                     // zeros do not affect the parity count
            }
            if (values[i] % 2 == 0) {
                requiredEven--;
            } else {
                requiredOdd--;
            }
        }

        // The answer is the minimum cost when we start with parity 0 or 1.
        int answer = Math.min(
                dpRecursive(0, requiredEven, requiredOdd, 0),
                dpRecursive(0, requiredEven, requiredOdd, 1));

        System.out.println(answer);
    }

    /**
     * Recursive DP that returns the minimal cost from the current state.
     *
     * @param idx        current position inside {@code values}
     * @param evenLeft   number of remaining even‑type slots
     * @param oddLeft    number of remaining odd‑type slots
     * @param lastParity parity (0 = even, 1 = odd) of the previously placed element
     * @return minimal additional cost, or {@link #INF} if the state cannot lead to a solution
     */
    private static int dpRecursive(int idx, int evenLeft, int oddLeft, int lastParity) {
        // Out‑of‑bounds – reached the end of the array.
        if (idx == values.length) {
            return 0;
        }

        // Invalid configuration – we have run out of a required parity.
        if (evenLeft < 0 || oddLeft < 0) {
            return INF;
        }

        // Return memoised result if it has already been computed.
        if (visited[idx][evenLeft][oddLeft][lastParity]) {
            return dp[idx][evenLeft][oddLeft][lastParity];
        }

        int current = values[idx];
        int result;

        if (current != 0) {
            // Fixed non‑zero value – we must place it and possibly pay a transition cost.
            int curParity = current % 2;
            result = dpRecursive(idx + 1, evenLeft, oddLeft, 0);
            result += (curParity == lastParity) ? 0 : 1;
        } else {
            // Option 1: place a zero as an even element.
            int costEven = dpRecursive(idx + 1, evenLeft - 1, oddLeft, 0);
            if (costEven != INF) {
                costEven += (0 == lastParity) ? 0 : 1;
            }

            // Option 2: place a zero as an odd element.
            int costOdd = dpRecursive(idx + 1, evenLeft, oddLeft - 1, 1);
            if (costOdd != INF) {
                costOdd += (1 == lastParity) ? 0 : 1;
            }

            result = Math.min(costEven, costOdd);
        }

        // Store the computed result and mark the cell as visited.
        dp[idx][evenLeft][oddLeft][lastParity] = result;
        visited[idx][evenLeft][oddLeft][lastParity] = true;
        return result;
    }
}

import java.io.Closeable;
import java.io.IOException;
import java.io.InputStream;
