/**
 * Garland – minimise the number of adjacent pairs having different parity.
 *
 * <p>The program reads an integer {@code n} followed by {@code n} integers.
 * Zeroes denote positions that must be filled with the missing numbers
 * {@code 1…n}.  The goal is to assign those missing numbers so that the
 * number of adjacent elements whose parity differs is minimal.</p>
 *
 * <p>This implementation focuses on readability, explicit naming and
 * separation of concerns while preserving the original algorithmic behaviour.</p>
 */
public class Garland implements Closeable {

    /* --------------------------------------------------------------------- */
    /*  Public I/O streams                                                    */
    /* --------------------------------------------------------------------- */
    private final FastScanner scanner;
    private final PrintWriter out;

    /* --------------------------------------------------------------------- */
    /*  Private fields used during processing                                 */
    /* --------------------------------------------------------------------- */
    private int[] numbers;                 // the input array (with 0 for blanks)
    private int oddMissing;                // how many odd numbers are still unused
    private int evenMissing;               // how many even numbers are still unused
    private int[][][][] memo;              // memoisation table

    /** Large sentinel value used instead of magic “1000”. */
    private static final int INF = 1_000;

    /* --------------------------------------------------------------------- */
    /*  Construction                                                          */
    /* --------------------------------------------------------------------- */
    /**
     * Creates a new {@code Garland} instance that reads from {@code input}
     * and writes to {@code output}.
     *
     * @param input  the source stream (normally {@code System.in})
     * @param output the destination stream (normally {@code System.out})
     */
    public Garland(InputStream input, PrintWriter output) {
        this.scanner = new FastScanner(input);
        this.out = output;
    }

    /* --------------------------------------------------------------------- */
    /*  Main solving routine                                                   */
    /* --------------------------------------------------------------------- */
    /**
     * Reads the data, computes the answer and prints it.
     *
     * <p>This method is deliberately small – all heavy lifting happens in
     * {@link #solve()}’s private helpers.</p>
     */
    public void solve() {
        readInput();
        allocateMemoTable();
        int answer = computeInitialAnswer();
        out.println(answer);
    }

    /* --------------------------------------------------------------------- */
    /*  Input handling                                                        */
    /* --------------------------------------------------------------------- */
    private void readInput() {
        int n = scanner.ni();
        numbers = new int[n];

        boolean[] present = new boolean[n + 1];
        for (int i = 0; i < n; i++) {
            numbers[i] = scanner.ni();
            if (numbers[i] != 0) {
                present[numbers[i]] = true;
            }
        }

        // Count how many odd / even numbers are still missing.
        oddMissing = 0;
        evenMissing = 0;
        for (int i = 1; i <= n; i++) {
            if (!present[i]) {
                if ((i & 1) == 0) {
                    evenMissing++;
                } else {
                    oddMissing++;
                }
            }
        }

        // Initialise memoisation table with “not yet computed” marker (-1).
        memo = new int[n][2][oddMissing + 1][evenMissing + 1];
        for (int[][][][] layer1 : memo) {
            for (int[][][] layer2 : layer1) {
                for (int[][] layer3 : layer2) {
                    Arrays.fill(layer3, -1);
                }
            }
        }
    }

    /** Allocates the memo table with the exact dimensions that are needed. */
    private void allocateMemoTable() {
        // The table has already been created with the right size in `readInput()`.
        // This method merely exists to make the intent explicit.
    }

    /** Computes the answer based on the first element of the array. */
    private int computeInitialAnswer() {
        int answer = INF;

        if (numbers[0] == 0) {
            // First position is blank – try both odd and even placements.
            if (oddMissing > 0) {
                answer = Math.min(answer,
                        dfs(1, 1, oddMissing - 1, evenMissing));   // place an odd number
            }
            if (evenMissing > 0) {
                answer = Math.min(answer,
                        dfs(1, 0, oddMissing, evenMissing - 1));   // place an even number
            }
        } else {
            // First position already contains a fixed number.
            answer = dfs(1, parity(numbers[0]), oddMissing, evenMissing);
        }
        return answer;
    }

    /* --------------------------------------------------------------------- */
    /*  Recursive search with memoisation                                      */
    /* --------------------------------------------------------------------- */
    /**
     * Depth‑first search that tries to fill the remaining blanks.
     *
     * @param idx        the current index (0‑based, {@code idx == n} terminates)
     * @param prevParity parity of the element placed just before {@code idx}
     *                   (0 = even, 1 = odd)
     * @param oddLeft    remaining odd numbers that can still be placed
     * @param evenLeft   remaining even numbers that can still be placed
     * @return the minimal additional cost from this state onward
     */
    private int dfs(int idx, int prevParity, int oddLeft, int evenLeft) {
        if (idx == numbers.length) {
            return 0; // reached the end – no further cost
        }

        int cached = memo[idx][prevParity][oddLeft][evenLeft];
        if (cached != -1) {
            return cached;
        }

        int best = INF;

        if (numbers[idx] != 0) {
            // Fixed value – just continue.
            int curParity = parity(numbers[idx]);
            int transitionCost = (prevParity == 0) ? 1 : 0; // same rule as original code
            best = transitionCost + dfs(idx + 1, curParity, oddLeft, evenLeft);
        } else {
            // Blank cell – try placing an odd or an even number if any are left.
            if (oddLeft > 0) {
                int transitionCost = (prevParity == 0) ? 1 : 0;
                best = Math.min(best, transitionCost + dfs(idx + 1, 1, oddLeft - 1, evenLeft));
            }
            if (evenLeft > 0) {
                int transitionCost = (prevParity == 0) ? 1 : 0;
                best = Math.min(best, transitionCost + dfs(idx + 1, 0, oddLeft, evenLeft - 1));
            }
        }

        memo[idx][prevParity][oddLeft][evenLeft] = best;
        return best;
    }

    /** Returns the parity of {@code value} (0 = even, 1 = odd). */
    private static int parity(int value) {
        return value & 1;
    }

    /* --------------------------------------------------------------------- */
    /*  Closeable implementation                                               */
    /* --------------------------------------------------------------------- */
    @Override
    public void close() throws IOException {
        scanner.close();
        out.close();
    }

    /* --------------------------------------------------------------------- */
    /*  Fast scanner – a tiny wrapper around BufferedReader                     */
    /* --------------------------------------------------------------------- */
    private static final class FastScanner implements Closeable {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        FastScanner(InputStream stream) {
            this.reader = new BufferedReader(new InputStreamReader(stream), 32768);
        }

        /** Returns the next token, expanding the underlying {@code StringTokenizer}. */
        private String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new UncheckedIOException(e);
                }
            }
            return tokenizer.nextToken();
        }

        /** Reads the next {@code int}. */
        int ni() {
            return Integer.parseInt(next());
        }

        /** Reads the next {@code long}. */
        long nl() {
            return Long.parseLong(next());
        }

        @Override
        public void close() throws IOException {
            reader.close();
        }
    }

    /* --------------------------------------------------------------------- */
    /*  Entry point                                                            */
    /* --------------------------------------------------------------------- */
    public static void main(String[] args) throws IOException {
        // Using try‑with‑resources guarantees that both streams are closed.
        try (Garland solver = new Garland(System.in, new PrintWriter(System.out, true))) {
            solver.solve();
        }
    }
}

import java.awt.Point;
import java.io.*;
import java.util.*;

/**
 * Solves the “Gold, Bombs and Maze” problem.
 *
 * <p>Key ideas of the refactor:
 *
 * <ul>
 *   <li>Clear separation of concerns – input handling, grid preparation,
 *       reachability checks and validation logic are each in their own method.</li>
 *   <li>Meaningful constant names and descriptive variable names instead of
 *       cryptic “a”, “b”, “cntt”, etc.</li>
 *   <li>Direction vectors are declared once and reused.</li>
 *   <li>Algorithmic steps are extracted into small, well‑named helper methods.</li>
 *   <li>All magic numbers are replaced by typed constants.</li>
 * </ul>
 *
 * <p>The program reads multiple test cases, each consisting of a rectangular
 * maze containing:
 *
 * <ul>
 *   <li>‘.’ – empty cell</li>
 *   <li>‘G’ – gold cell</li>
 *   <li>‘B’ – bomb cell</li>
 *   <li>‘#’ – wall (treated as immutable obstacle)</li>
 * </ul>
 *
 * <p>Output for each test case is either “Yes” or “No” according to the
 * validation rules described in the original code.
 */
public class Solution {

    /** Symbolic values used inside the grid. */
    private static final int EMPTY = 0;
    private static final int GOLD  = 2;
    private static final int BOMB  = 1;
    private static final int WALL  = -1;   // used only for cells that become blocked

    /** Four orthogonal movement directions. */
    private static final int[] DR = {1, -1, 0, 0};
    private static final int[] DC = {0, 0, 1, -1};

    /** Fast scanner that works on System.in. */
    private static final class FastReader {
        private final BufferedReader br;
        private StringTokenizer st;

        FastReader() throws IOException {
            this.br = new BufferedReader(new InputStreamReader(System.in));
            st = new StringTokenizer("");
        }

        /** Returns the next token, reading a new line if necessary. */
        private String nextToken() throws IOException {
            while (!st.hasMoreTokens() || st == null) {
                st = new StringTokenizer(br.readLine());
            }
            return st.nextToken();
        }

        /** Shortcut for reading an int. */
        int nextInt() throws IOException {
            return Integer.parseInt(nextToken());
        }
    }

    /** Entry point. */
    public static void main(String[] args) throws IOException {
        FastReader reader = new FastReader();
        PrintWriter out = new PrintWriter(System.out, true);

        int tests = reader.nextInt();
        StringBuilder ans = new StringBuilder();

        while (tests-- > 0) {
            int n = reader.nextInt();
            int m = reader.nextInt();

            char[][] raw = new char[n][];
            for (int i = 0; i < n; i++) {
                raw[i] = reader.next().toCharArray();
            }

            int[][] grid = buildNumericGrid(raw, n, m);
            int goldCount = countGold(grid, n, m);

            // Rule #1 – no gold and destination is not a bomb → answer is trivially “Yes”.
            if (goldCount == 0 && grid[n - 1][m - 1] != BOMB) {
                ans.append("Yes").append('\n');
                continue;
            }

            // Mark cells that are blocked by a bomb (adjacent empty cells become walls).
            markBombInfluence(grid, n, m);

            // If the destination is now blocked → “No”.
            if (grid[n - 1][m - 1] == WALL || grid[n - 1][m - 1] == BOMB) {
                ans.append("No").append('\n');
                continue;
            }

            // Reachability from the destination cell.
            boolean[][] reachable = bfsFromTarget(grid, n, m);

            // All gold cells must be reachable from the destination.
            if (!allGoldReachable(grid, reachable, n, m)) {
                ans.append("No").append('\n');
                continue;
            }

            // No bomb may be adjacent to any reachable cell.
            if (!bombsAdjacentToReachable(grid, reachable, n, m)) {
                ans.append("No").append('\n');
                continue;
            }

            // If we passed all checks → “Yes”.
            ans.append("Yes").append('\n');
        }

        out.print(ans.toString());
    }

    /** Translates the character matrix read from the input into the numeric representation. */
    private static int[][] buildNumericGrid(char[][] chars, int n, int m) {
        int[][] grid = new int[n][m];
        int goldCount = 0;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                char c = chars[i][j];
                if (c == '.') {
                    grid[i][j] = EMPTY;
                } else if (c == 'G') {
                    grid[i][j] = GOLD;
                    goldCount++;
                } else if (c == 'B') {
                    grid[i][j] = BOMB;
                } else { // treat any other character as a wall
                    grid[i][j] = WALL;
                }
            }
        }
        // expose gold count for the early‑exit rule
        // (stored in a local variable of the loop, not as a field)
        // No side‑effect needed here.
        return grid;
    }

    /** Counts the number of gold cells in the grid. */
    private static int countGold(int[][] grid, int n, int m) {
        int cnt = 0;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i][j] == GOLD) cnt++;
            }
        }
        return cnt;
    }

    /**
     * Cells that are orthogonally adjacent to a bomb and currently empty become
     * permanent walls (value {@value #WALL}). This models the rule “a bomb blocks
     * its neighbours”.
     */
    private static void markBombInfluence(int[][] grid, int n, int m) {
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i][j] == BOMB) {
                    for (int d = 0; d < 4; d++) {
                        int ni = i + DR[d];
                        int nj = j + DC[d];
                        if (valid(ni, nj, n, m) && grid[ni][nj] == EMPTY) {
                            grid[ni][nj] = WALL;
                        }
                    }
                }
            }
        }
    }

    private static boolean valid(int r, int c, int n, int m) {
        return r >= 0 && r < n && c >= 0 && c < m;
    }

    /**
     * Breadth‑first search starting from the destination cell (n‑1, m‑1).
     *
     * @return a boolean matrix where {@code reachable[r][c] == true}
     *         iff the cell can be reached without stepping on a wall or a bomb.
     */
    private static boolean[][] bfsFromTarget(int[][] grid, int n, int m) {
        boolean[][] visited = new boolean[n][m];
        Queue<Point> q = new LinkedList<>();

        // start from the target cell
        q.add(new Point(n - 1, m - 1));
        visited[n - 1][m - 1] = true;

        while (!q.isEmpty()) {
            Point cur = q.remove();
            int r = cur.x;
            int c = cur.y;

            for (int d = 0; d < 4; d++) {
                int nr = r + DR[d];
                int nc = c + DC[d];
                if (valid(nr, nc, n, m) && !visited[nr][nc] && grid[nr][nc] != WALL) {
                    visited[nr][nc] = true;
                    q.add(new Point(nr, nc));
                }
            }
        }
        return visited;
    }

    /** All gold cells must be marked as reachable. */
    private static boolean allGoldReachable(int[][] grid, boolean[][] reachable, int n, int m) {
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i][j] == GOLD && !reachable[i][j]) {
                    return false;
                }
            }
        }
        return true;
    }

    /**
     * Verifies that no bomb is orthogonal to a reachable cell.
     *
     * @return {@code true} if every bomb is isolated from all reachable cells.
     */
    private static boolean bombsAdjacentToReachable(int[][] grid, boolean[][] reachable, int n, int m) {
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i][j] == BOMB) {
                    for (int d = 0; d < 4; d++) {
                        int ni = i + DR[d];
                        int nj = j + DC[d];
                        if (valid(ni, nj, n, m) && reachable[ni][nj]) {
                            return false;
                        }
                    }
                }
            }
        }
        return true;
    }
}

import java.io.*;
import java.util.*;

/**
 * Solution for the “Mario and the Grid” problem.
 *
 * <p>Refactoring goals:
 * <ul>
 *   <li>Separate concerns (input, processing, output)</li>
 *   <li>Use expressive naming and small, single‑purpose methods</li>
 *   <li>Avoid magic numbers and scattered boolean flags</li>
 *   <li>Keep the original algorithmic behaviour while improving readability</li>
 * </ul>
 */
public class Main {

    /** Constant symbols used in the grid. */
    private static final char WALL   = '#';
    private static final char GOLD   = 'G';
    private static final char BOMB   = 'B';
    private static final char EMPTY  = '.';

    /** Directions for adjacent cells (up, down, left, right). */
    private static final int[][] ADJACENTS = {
            {-1, 0}, {1, 0}, {0, -1}, {0, 1}
    };

    /** Fast scanner – handles tokenisation of the input. */
    private static final class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner() {
            try {
                br = new BufferedReader(new InputStreamReader(System.in));
                st = new StringTokenizer(br.readLine());
            } catch (IOException e) {
                throw new UncheckedIOException(e);
            }
        }

        String next() {
            while (!st.hasMoreTokens()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    throw new UncheckedIOException(e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }
    }

    /** Entry point – processes multiple test cases. */
    public static void main(String[] args) {
        FastScanner sc = new FastScanner();
        PrintWriter out = new PrintWriter(System.out);

        int tests = sc.nextInt();
        while (tests-- > 0) {
            solveOneTest(sc, out);
        }

        out.close();
    }

    /** Handles a single test case – reads input, runs checks, writes answer. */
    private static void solveOneTest(FastScanner sc, PrintWriter out) {
        int rows = sc.nextInt();
        int cols = sc.nextInt();

        char[][] grid = readGrid(sc, rows, cols);

        boolean hasGold   = false;   // at least one 'G' exists in the grid
        boolean cannotProceed = false; // becomes true if some illegal bomb placement is detected

        // Scan the whole grid to locate bombs ('B') and verify their neighbourhood.
        for (int r = 0; r < rows && !cannotProceed; ++r) {
            for (int c = 0; c < cols; ++c) {
                char cell = grid[r][c];
                if (cell == GOLD) {
                    hasGold = true;
                }
                if (cell == EMPTY) {
                    continue; // nothing to do for empty cells
                }
                if (cell == BOMB) {
                    if (!isSafeToPlaceBomb(grid, r, c, rows, cols)) {
                        cannotProceed = true;
                        break;
                    }
                }
            }
        }

        // The original code marks the destination as blocked when at least one gold exists.
        // This mirrors the behaviour of the original solution.
        if (grid[rows - 1][cols - 1] == WALL && hasGold) {
            cannotProceed = true;
        }

        // If any violation was discovered, the answer is “No”.
        if (cannotProceed) {
            out.println("No");
            return;
        }

        // Verify that every gold cell is reachable from the destination cell
        // (using a flood‑fill that respects walls). If some gold stays unreachable,
        // the answer also becomes “No”.
        boolean allGoldVisited = bfsFromDestination(grid, rows, cols);
        out.println(allGoldVisited ? "Yes" : "No");
    }

    /**
     * Reads a rectangular grid of characters from the scanner.
     */
    private static char[][] readGrid(FastScanner sc, int rows, int cols) {
        char[][] grid = new char[rows][cols];
        for (int r = 0; r < rows; ++r) {
            String line = sc.next();
            for (int c = 0; c < cols; ++c) {
                grid[r][c] = line.charAt(c);
            }
        }
        return grid;
    }

    /**
     * Checks whether a bomb can be placed at (r, c) without destroying adjacent gold cells.
     * The original algorithm:
     * <ul>
     *   <li>If any adjacent cell contains 'G', placement is illegal.</li>
     *   <li>If an adjacent empty cell ('.') exists, it is turned into a wall ('#')</li>
     * </ul>
     *
     * @return {@code true} if the placement is safe.
     */
    private static boolean isSafeToPlaceBomb(char[][] grid, int r, int c,
                                               int rows, int cols) {
        for (int[] dir : ADJACENTS) {
            int nr = r + dir[0];
            int nc = c + dir[1];

            // Guard against out‑of‑bounds accesses – the original code used slightly
            // different bounds, but the intention is to look at the four neighbours.
            if (!isInside(nr, nc, rows, cols)) {
                continue;
            }

            char neighbour = grid[nr][nc];
            if (neighbour == GOLD) {
                // Adjacent gold would be destroyed → illegal placement.
                return false;
            }
            if (neighbour == EMPTY) {
                // Turn empty neighbour into a wall (same effect as original code).
                grid[nr][nc] = WALL;
            }
        }
        return true;
    }

    /** Simple bounds check used by {@link #isSafeToPlaceBomb}. */
    private static boolean isInside(int row, int col, int rows, int cols) {
        return row >= 0 && row < rows && col >= 0 && col < cols;
    }

    /**
     * Flood‑fill (BFS/DFS) starting from the bottom‑right cell.
     * Returns {@code true} iff every 'G' cell is visited (i.e., reachable).
     */
    private static boolean bfsFromDestination(char[][] grid, int rows, int cols) {
        boolean[][] visited = new boolean[rows][cols];
        dfsVisit(visited, rows - 1, cols - 1, grid, rows, cols);
        for (int r = 0; r < rows; ++r) {
            for (int c = 0; c < cols; ++c) {
                if (grid[r][c] == GOLD && !visited[r][c]) {
                    return false; // unreachable gold found
                }
            }
        }
        return true;
    }

    /** DFS helper that explores all four directions respecting walls and visited cells. */
    private static void dfsVisit(boolean[][] visited, int r, int c,
                                 char[][] grid, int rows, int cols) {
        if (r < 0 || r >= rows || c < 0 || c >= cols) {
            return;
        }
        if (visited[r][c] || grid[r][c] == WALL) {
            return;
        }
        visited[r][c] = true;
        dfsVisit(visited, r - 1, c, grid, rows, cols);
        dfsVisit(visited, r + 1, c, grid, rows, cols);
        dfsVisit(visited, r, c - 1, grid, rows, cols);
        dfsVisit(visited, r, c + 1, grid, rows, cols);
    }
}

import java.io.*;
import java.util.*;

public class Main {

    /* ---------- Constants representing cell types ---------- */
    private static final int EMPTY = 0;   // '.'
    private static final int WALL  = 1;   // '#'
    private static final int GOAL  = 2;   // 'G'
    private static final int START = 3;   // any other character

    /* ---------- Global state ---------- */
    private static PrintWriter out;
    private static BufferedReader reader;
    private static StringTokenizer tokenizer;

    private static int n, m;                     // grid dimensions
    private static int[][] grid;                 // 0=empty, 1=wall, 2=goal, 3=start
    private static boolean[][] visited;          // visited flag for DFS

    public static void main(String[] args) throws IOException {
        reader = new BufferedReader(new InputStreamReader(System.in));
        out = new PrintWriter(System.out);
        int t = nextInt();                       // number of test cases
        for (int tc = 0; tc < t; ++tc) {
            solveCase();
        }
        out.close();
    }

    /** Reads a test case, processes it and prints the answer. */
    private static void solveCase() {
        readDimensionsAndGrid();

        /* 1️⃣  The exit cell (bottom‑right) must not be a start cell. */
        if (grid[n - 1][m - 1] == START) {
            out.println("No");
            return;
        }

        /* 2️⃣  Block all empty neighbours of start cells.
         *      If a start cell touches a goal, the case becomes impossible. */
        if (! blockNeighboursOfStarts()) {
            out.println("No");
            return;
        }

        /* 3️⃣  Explore reachable area from the exit. */
        dfsFromExit();

        /* 4️⃣  Verify that every goal cell is reachable from the exit. */
        boolean allGoalsReachable = allGoalsReachable();
        out.println(allGoalsReachable ? "Yes" : "No");
    }

    /** Parses the size of the grid and the grid itself. */
    private static void readDimensionsAndGrid() throws IOException {
        n = nextInt();
        m = nextInt();

        grid = new int[n][m];
        visited = new boolean[n][m];

        for (int i = 0; i < n; ++i) {
            String line = next();
            for (int j = 0; j < m; ++j) {
                char ch = line.charAt(j);
                if (ch == '.') {
                    grid[i][j] = EMPTY;
                } else if (ch == '#') {
                    grid[i][j] = WALL;
                } else if (ch == 'G') {
                    grid[i][j] = GOAL;
                } else {
                    // any other character denotes a start cell
                    grid[i][j] = START;
                }
            }
        }
    }

    /** Turns every empty cell adjacent to a start cell into a wall.
     *  Returns `false` if any start cell is directly adjacent to a goal. */
    private static boolean blockNeighboursOfStarts() {
        int[] di = {-1, 0, 1, 0};
        int[] dj = {0, 1, 0, -1};

        for (int i = 0; i < n; ++i) {
            for (int j = 0; j < m; ++j) {
                if (grid[i][j] == START) {
                    for (int d = 0; d < 4; ++d) {
                        int ni = i + di[d];
                        int nj = j + dj[d];
                        if (isInBounds(ni, nj)) {
                            if (grid[ni][nj] == EMPTY) {
                                grid[ni][nj] = WALL;               // block empty neighbour
                            }
                            if (grid[ni][nj] == GOAL) {
                                return false;                       // start touches a goal → impossible
                            }
                        }
                    }
                }
            }
        }
        return true;
    }

    /** Depth‑first Search that marks every cell reachable from (startX,startY). */
    private static void dfsFromExit() {
        Arrays.fill(visited, false);
        dfsVisit(n - 1, m - 1);
    }

    private static void dfsVisit(int i, int j) {
        if (!isInBounds(i, j)) return;
        if (grid[i][j] == WALL) return;
        if (visited[i][j]) return;

        visited[i][j] = true;
        dfsVisit(i + 1, j);
        dfsVisit(i, j + 1);
        dfsVisit(i - 1, j);
        dfsVisit(i, j - 1);
    }

    /** Returns `true` iff each goal cell has been visited by the DFS. */
    private static boolean allGoalsReachable() {
        for (int i = 0; i < n; ++i) {
            for (int j = 0; j < m; ++j) {
                if (grid[i][j] == GOAL && !visited[i][j]) {
                    return false;
                }
            }
        }
        return true;
    }

    /* ---------- Simple I/O helpers ---------- */
    private static String next() throws IOException {
        while (tokenizer == null || !tokenizer.hasMoreTokens()) {
            String line = reader.readLine();
            if (line == null) return null;
            tokenizer = new StringTokenizer(line);
        }
        return tokenizer.nextToken();
    }

    private static int nextInt() {
        return Integer.parseInt(next());
    }
}

import java.io.*;
import java.util.Arrays;

/**
 * Solution for CF 648D2 D – refactored for readability and maintainability.
 */
public final class CF_648_D2_D {

    /** Directions: up, right, down, left */
    private static final int[][] DIRS = {
            {-1, 0},
            { 0, 1},
            { 1, 0},
            { 0,-1}
    };

    /** Modulus used in the original code (kept for compatibility). */
    private static final long MOD = 1_000_000_007L;

    /** Buffered writer used for output. */
    private static BufferedWriter writer;

    /** Input helper – a thin wrapper around {@link InputStream}. */
    private static final class InputReader {
        private final InputStream stream;
        private final byte[] buffer = new byte[1 << 10];
        private int pointer = 0, length = 0;

        InputReader(InputStream stream) {
            this.stream = stream;
        }

        private int readByte() throws IOException {
            if (pointer >= length) {
                length = stream.read(buffer);
                pointer = 0;
                if (length <= 0) {
                    return -1;
                }
            }
            return buffer[pointer++];
        }

        /** Reads next non‑whitespace character. */
        private int skipWhitespace() throws IOException {
            int c;
            while ((c = readByte()) <= ' ') {
                if (c == -1) return -1;
            }
            return c;
        }

        /** Reads a line (up to newline). */
        String readLine() throws IOException {
            StringBuilder sb = new StringBuilder();
            int c;
            while ((c = skipWhitespace()) != -1 && c != '\n') {
                sb.append((char) c);
            }
            return sb.toString();
        }

        /** Reads a string of arbitrary length (stops at whitespace). */
        String readString() throws IOException {
            StringBuilder sb = new StringBuilder();
            int c;
            while ((c = skipWhitespace()) != -1 && c != ' ' && c != '\n') {
                sb.append((char) c);
            }
            return sb.toString();
        }

        int readInt() throws IOException {
            int sign = 1;
            int c = readByte();
            if (c == '-') {
                sign = -1;
                c = readByte();
            }
            int value = 0;
            while (c >= '0' && c <= '9') {
                value = value * 10 + (c - '0');
                c = readByte();
            }
            return value * sign;
        }

        long readLong() throws IOException {
            long sign = 1;
            int c = readByte();
            if (c == '-') {
                sign = -1;
                c = readByte();
            }
            long value = 0;
            while (c >= '0' && c <= '9') {
                value = value * 10 + (c - '0');
                c = readByte();
            }
            return value * sign;
        }
    }

    /**
     * Core solving routine.
     *
     * @throws Exception if an I/O error occurs
     */
    private static void solve() throws Exception {
        // Input handling
        InputReader reader = new InputReader(System.in);
        writer = new BufferedWriter(new OutputStreamWriter(System.out));

        int t = reader.readInt();
        for (int test = 0; test < t; test++) {
            final int MAX = 51;
            // Stack used for DFS (size limited to MAX*MAX, enough for given constraints)
            int[][] stack = new int[MAX * MAX][2];
            // Visited flag per cell – reuse the same array each test case
            int[][] visited = new int[MAX][MAX];
            int timestamp = 0;

            int n = reader.readInt();
            int m = reader.readInt();
            char[][] grid = new char[n][];
            for (int i = 0; i < n; i++) {
                String line = reader.readString();
                grid[i] = line.toCharArray();
            }

            boolean impossible = false;
            int good = 0;

            // Scan grid to detect adjacency of a cat ('B') to a goat ('G')
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    if (grid[i][j] == 'B') {
                        for (int[] dir : DIRS) {
                            int ni = i + dir[0];
                            int nj = j + dir[1];
                            if (isInside(ni, m, nj, n) && grid[ni][nj] == 'G') {
                                impossible = true;
                                break;
                            }
                            if (grid[ni][nj] == '.') {
                                grid[ni][nj] = '#';
                            }
                        }
                        if (impossible) {
                            break;
                        }
                    } else if (grid[i][j] == 'G') {
                        good++;
                    }
                }
                if (impossible) {
                    break;
                }
            }

            String result = "No";

            if (!impossible) {
                // Perform DFS from the bottom‑right corner if it is empty
                if (grid[n - 1][m - 1] == '.') {
                    int top = 0;
                    stack[top][0] = n - 1;
                    stack[top][1] = m - 1;
                    visited[n - 1][m - 1] = ++timestamp;

                    int stackSize = 1;
                    while (stackSize > 0) {
                        int x = stack[stackSize - 1][0];
                        int y = stack[stackSize - 1][1];
                        stackSize--;

                        for (int[] dir : DIRS) {
                            int nx = x + dir[0];
                            int ny = y + dir[1];
                            if (isInside(ny, m, nx, n) && visited[nx][ny] != timestamp) {
                                if (grid[nx][ny] != '#') {
                                    // Move to next free slot
                                    stackSize++;
                                    stack[stackSize][0] = nx;
                                    stack[stackSize][1] = ny;
                                    visited[nx][ny] = timestamp;

                                    if (grid[nx][ny] == 'G') {
                                        good--;
                                    }
                                }
                            }
                        }
                    }
                }

                if (good == 0) {
                    result = "Yes";
                }
            }

            writer.write(result + "\n");
        }

        writer.flush();
        writer.close();
    }

    /** Helper to check array bounds. */
    private static boolean isInside(int col, int cols, int row, int rows) {
        return row >= 0 && row < rows && col >= 0 && col < cols;
    }

    /** Entry point – delegating to the solving routine. */
    public static void main(String[] args) throws Exception {
        solve();
    }
}

import java.io.*;
import java.util.*;

/**
 * Solves the “three” problem with clearer structure, proper encapsulation and
 * meaningful naming. The algorithm is unchanged, but the code is now
 * maintainable and self‑documenting.
 */
public class Main {

    /* --------------------------------------------------------------------- */
    /*                     CONSTANTS & DIRECTIONS                            */
    /* --------------------------------------------------------------------- */
    private static final char WALL   = '#';
    private static final char GOOD   = 'G';
    private static final char BAD    = 'B';
    private static final char FREE   = '.';

    /** Four orthogonal directions. */
    private static final List<Direction> DIRECTIONS = List.of(
            new Direction(-1, 0),
            new Direction( 1, 0),
            new Direction( 0,-1),
            new Direction( 0, 1)
    );

    /* --------------------------------------------------------------------- */
    /*                         SIMPLE VALUE OBJECTS                         */
    /* --------------------------------------------------------------------- */
    /** One cell coordinate. */
    private static final class Point {
        final int r, c;
        Point(int r, int c) { this.r = r; this.c = c; }
    }

    /** Holds the grid and related meta‑information. */
    private static final class Grid {
        final char[][] cells;   // raw grid
        final int rows, cols;   // dimensions
        final int totalGood;    // number of 'G' cells

        Grid(char[][] cells, int rows, int cols) {
            this.cells = cells;
            this.rows = rows;
            this.cols = cols;
            this.totalGood = countGood();
        }

        /** Counts all 'G' cells in the grid. */
        private int countGood() {
            int cnt = 0;
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (cells[r][c] == GOOD) cnt++;
                }
            }
            return cnt;
        }

        /**
         * Breadth‑first search that starts at (sr, sc) and returns how many
         * 'G' cells are reachable without crossing walls.
         */
        int countReachableGood(int sr, int sc) {
            boolean[][] visited = new boolean[rows][cols];
            Queue<Point> q = new ArrayDeque<>();
            q.add(new Point(sr, sc));
            visited[sr][sc] = true;

            int reachableGood = 0;

            while (!q.isEmpty()) {
                Point cur = q.poll();
                if (cells[cur.r][cur.c] == GOOD) reachableGood++;

                for (Direction d : DIRECTIONS) {
                    int nr = cur.r + d.dx;
                    int nc = cur.c + d.dy;
                    if (inside(nr, nc) && !visited[nr][nc] && cells[nr][nc] != WALL) {
                        visited[nr][nc] = true;
                        q.add(new Point(nr, nc));
                    }
                }
            }
            return reachableGood;
        }

        /** Utility – checks whether (r,c) lies inside the grid. */
        private boolean inside(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }
    }

    /** Direction holder – kept immutable and small. */
    private static final class Direction {
        final int dx, dy;
        Direction(int dx, int dy) { this.dx = dx; this.dy = dy; }
    }

    /* --------------------------------------------------------------------- */
    /*                     PRE‑PROCESSING HELPERS                           */
    /* --------------------------------------------------------------------- */
    /**
     * For every 'B' cell we:
     *   1. Fail fast if any neighbour is a good cell (makes the answer impossible).
     *   2. Convert every non‑bad neighbour that is not a wall into a wall.
     *
     * @return {@code true} if the transformation succeeded without early failure.
     */
    private static boolean isolateBadAndCheckAdjacency(Grid grid) {
        char[][] cells = grid.cells;
        int rows = grid.rows;
        int cols = grid.cols;

        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (cells[r][c] == BAD) {
                    for (Direction d : DIRECTIONS) {
                        int nr = r + d.dx;
                        int nc = c + d.dy;
                        if (grid.inside(nr, nc)) {
                            // 1️⃣  A good cell adjacent to a bad cell -> impossible.
                            if (cells[nr][nc] == GOOD) {
                                return false;
                            }
                            // 2️⃣  Turn any non‑bad, non‑wall neighbour into a wall.
                            if (cells[nr][nc] != BAD) {
                                cells[nr][nc] = WALL;
                            }
                        }
                    }
                }
            }
        }
        return true;
    }

    /* --------------------------------------------------------------------- */
    /*                               SCANNER                                 */
    /* --------------------------------------------------------------------- */
    /** Fast wrapper around {@link BufferedReader} that tokenises line by line. */
    private static final class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner(InputStream is) {
            this.br = new BufferedReader(new InputStreamReader(is));
            tokenizer = new StringTokenizer("");
        }

        String next() throws IOException {
            while (!tokenizer.hasMoreTokens()) {
                String line = br.readLine();
                if (line == null) return null;
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        int nextInt() throws IOException { return Integer.parseInt(next()); }
        long nextLong() throws IOException { return Long.parseLong(next()); }
        double nextDouble() throws IOException { return Double.parseDouble(next()); }
    }

    /* --------------------------------------------------------------------- */
    /*                                 MAIN                                  */
    /* --------------------------------------------------------------------- */
    public static void main(String[] args) throws IOException {
        FastScanner fs = new FastScanner(System.in);
        StringBuilder output = new StringBuilder();

        int t = fs.nextInt();                     // number of test cases
        for (int ti = 0; ti < t; ti++) {
            int n = fs.nextInt();
            int m = fs.nextInt();

            // ----- read the grid -------------------------------------------------
            char[][] raw = new char[n][];
            for (int i = 0; i < n; i++) {
                raw[i] = fs.next().toCharArray();
            }

            Grid grid = new Grid(raw, n, m);

            // ----- 1️⃣  Isolate bad cells and detect impossible adjacency -------
            if (!isolateBadAndCheckAdjacency(grid)) {
                output.append("No\n");
                continue;                          // next test case
            }

            // ----- 2️⃣  Trivial case – no good cells at all --------------------
            if (grid.totalGood == 0) {
                output.append("Yes\n");
                continue;
            }

            // ----- 3️⃣  BFS from the bottom‑right corner -------------------------
            int reachableGood = grid.countReachableGood(n - 1, m - 1);

            // ----- 4️⃣  Decision logic -------------------------------------------
            boolean answer = (reachableGood == grid.totalGood) &&
                             (grid.cells[n - 1][m - 1] != WALL);

            output.append(answer ? "Yes\n" : "No\n");
        }

        System.out.print(output.toString());
    }
}

