import java.util.ArrayDeque;
import java.util.Queue;

/**
 * Entry point of the program.
 * Reads input using {@link FastReader}, processes each test case with {@link Solver},
 * and writes the results using a {@link PrintWriter}.
 */
public class Main {

    public static void main(String[] args) {
        // Use try‑with‑resources to guarantee proper closing of the streams.
        try (PrintWriter out = new PrintWriter(System.out)) {
            FastReader reader = new FastReader(System.in);
            Solver solver = new Solver();
            solver.solve(reader, out);
        }
    }
