/**
 * Simple fast scanner based on a reusable byte buffer.
 * It currently supports {@code nextInt()} and {@code next()} only.
 */
class FastReader {
    private static final int BUFFER_SIZE = 1024;
    private final byte[] buffer = new byte[BUFFER_SIZE];
    private int index = 0;
    private int size = 0;               // number of bytes currently stored
    private final InputStream in;

    FastReader(InputStream in) {
        this.in = in;
    }

    /** Fills the internal buffer and resets the position. */
    private void fill() throws IOException {
        index = 0;
        size = in.read(buffer);
        if (size <= 0) {
            throw new EOFException();
        }
    }

    /** Returns the next character code or –1 on EOF. */
    private int readByte() throws IOException {
        if (index >= size) {
            fill();
            if (index >= size) {
                return -1; // EOF
            }
        }
        return buffer[index++] & 0xFF;
    }

    /** Skips whitespace characters. */
    private int skipWhite() throws IOException {
        int b;
        do {
            b = readByte();
        } while (b <= ' ' && b != -1);
        return b;
    }

    /** Reads the next integer (supports negative numbers). */
    int nextInt() throws IOException {
        int c = skipWhite();
        boolean neg = false;
        if (c == '-') {
            neg = true;
            c = skipWhite();
        }
        int value = 0;
        while (c > ' ') {
            value = value * 10 + (c - '0');
            c = readByte();
        }
        return neg ? -value : value;
    }

    /** Reads the next token (a non‑whitespace sequence). */
    String next() throws IOException {
        StringBuilder sb = new StringBuilder();
        int c = skipWhite();
        while (c > ' ') {
            sb.append((char) c);
            c = readByte();
        }
        return sb.toString();
    }
}

/**
 * Core logic for solving the maze puzzle.
 * The class is deliberately stateless – all data is passed through method arguments.
 */
class Solver {

    // Symbolic constants improve readability.
    private static final char GOOD   = 'G';
    private static final char BAD    = 'B';
    private static final char EMPTY  = '.';
    private static final char WALL   = '#';

    // Four movement directions.
    private static final int[] DX = {0, -1, 1, 0};
    private static final int[] DY = {-1, 0, 0, 1};

    /**
     * Solves {@code t} test cases.
     * The method is invoked from {@code Main}.
     */
    void solve(FastReader reader, PrintWriter out) {
        int t = reader.nextInt();
        StringBuilder output = new StringBuilder();

        for (int caseIdx = 0; caseIdx < t; caseIdx++) {
            int rows = reader.nextInt();
            int cols = reader.nextInt();
            char[][] grid = readGrid(reader, rows);
            boolean answer = canReachAllGoodCells(grid, rows, cols);
            output.append(answer ? "Yes\n" : "No\n");
        }
        out.print(output.toString());
    }

    /** Reads {@code rows} strings and returns the constructed grid. */
    private char[][] readGrid(FastReader reader, int rows) {
        char[][] grid = new char[rows][];
        for (int i = 0; i < rows; i++) {
            grid[i] = reader.next().toCharArray();
        }
        return grid;
    }

    /**
     * Returns {@code true} if all good cells are reachable from the bottom‑right corner
     * and no bad cell is reachable under the rules of the puzzle.
     */
    private boolean canReachAllGoodCells(char[][] grid, int rows, int cols) {
        // Remove bad cells first (adjacent empty cells become walls).
        neutraliseBadCells(grid, rows, cols);

        // The target cell must not be a wall; otherwise the answer is automatically No.
        if (grid[rows - 1][cols - 1] == WALL) {
            return false;
        }

        boolean[][] visited = bfsFromTarget(grid, rows, cols);
        return verifyCondition(grid, visited, rows, cols);
    }

    /** Marks each empty neighbour of a BAD cell as a WALL. */
    private void neutraliseBadCells(char[][] grid, int rows, int cols) {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == BAD) {
                    for (int d = 0; d < 4; d++) {
                        int nr = r + DX[d];
                        int nc = c + DY[d];
                        if (coordinatesInside(nr, nc, rows, cols)
                                && grid[nr][nc] == EMPTY) {
                            grid[nr][nc] = WALL;
                        }
                    }
                }
            }
        }
    }

    /** Bread‑first search starting from the bottom‑right cell. */
    private boolean[][] bfsFromTarget(char[][] grid, int rows, int cols) {
        boolean[][] visited = new boolean[rows][cols];
        Queue<int[]> queue = new ArrayDeque<>();
        queue.offer(new int[]{rows - 1, cols - 1});
        visited[rows - 1][cols - 1] = true;

        while (!queue.isEmpty()) {
            int[] cur = queue.poll();
            int x = cur[0];
            int y = cur[1];
            for (int d = 0; d < 4; d++) {
                int nx = x + DX[d];
                int ny = y + DY[d];
                if (outOfBounds(nx, ny, rows, cols)
                        || visited[nx][ny]
                        || grid[nx][ny] == WALL) {
                    continue;
                }
                visited[nx][ny] = true;
                queue.offer(new int[]{nx, ny});
            }
        }
        return visited;
    }

    /** Checks that every BAD cell is unreachable and every GOOD cell is reachable. */
    private boolean verifyCondition(char[][] grid, boolean[][] visited, int rows, int cols) {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                char cell = grid[r][c];
                if (cell == BAD && visited[r][c]) {
                    return false;
                }
                if (cell == GOOD && !visited[r][c]) {
                    return false;
                }
            }
        }
        return true;
    }

    /** Utility to test whether a coordinate lies inside the grid. */
    private boolean coordinatesInside(int x, int y, int rows, int cols) {
        return x >= 0 && x < rows && y >= 0 && y < cols;
    }

    /** Utility to test whether a coordinate is outside the grid. */
    private boolean outOfBounds(int x, int y, int rows, int cols) {
        return x < 0 || x >= rows || y < 0 || y >= cols;
    }
}

import java.io.*;
import java.util.*;

/**
 * Main class – entry point for the solution.
 */
public class Main {

    /** Four cardinal directions (right, left, down, up). */
    private static final int[][] DIRS = {
            {0, 1}, {0, -1}, {1, 0}, {-1, 0}
    };

    /** Immutable coordinate holder for grid cells. */
    private static final class Coord {
        final int x;   // column
        final int y;   // row

        Coord(int x, int y) {
            this.x = x;
            this.y = y;
        }

        boolean equals(Object o) {
            return (o instanceof Coord c) && c.x == x && c.y == y;
        }

        @Override
        public int hashCode() {
            return Objects.hash(x, y);
        }

        @Override
        public String toString() {
            return "(" + x + "," + y + ")";
        }
    }

    /** Fast scanner for integer‑based input. */
    private static final class InputReader {
        private final BufferedReader br;
        private StringTokenizer stk;

        InputReader(InputStream stream) {
            br = new BufferedReader(new InputStreamReader(stream), 32768);
        }

        /** Returns the next token or reads a new line until a token is available. */
        String next() {
            while (stk == null || !stk.hasMoreTokens()) {
                try {
                    stk = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    throw new UncheckedIOException(e);
                }
            }
            return stk.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }
    }

    /**
     * Determines whether all ‘G’ cells can reach the bottom‑right corner
     * (n‑1, m‑1) moving only through '.' cells and respecting blocked '#' cells.
     */
    private static boolean allGoalsCanReachExit(char[][] grid, Set<Coord> goals, int rows, int cols) {
        for (Coord goal : goals) {
            if (!bfsFromGoal(grid, goal, rows, cols)) {
                return false;
            }
        }
        return true;
    }

    /**
     * Breadth‑first search starting from a single goal.
     * Returns true if the search reaches the bottom‑right cell without stepping on '#'.
     */
    private static boolean bfsFromGoal(char[][] grid, Coord start, int rows, int cols) {
        int[][] visited = new int[rows][cols];
        int token = start.hashCode();                 // unique identifier for this BFS run
        Deque<Coord> queue = new ArrayDeque<>();
        queue.add(start);
        boolean reachedBottomRight = false;

        while (!queue.isEmpty()) {
            Coord cur = queue.poll();

            if (visited[cur.y][cur.x] == token) {
                continue;
            }
            visited[cur.y][cur.x] = token;

            for (int[] d : DIRS) {
                int ny = cur.y + d[0];
                int nx = cur.x + d[1];
                if (!inside(ny, nx, rows, cols)) {
                    continue;
                }
                char cell = grid[ny][nx];
                if (cell == '#') {
                    continue;                          // blocked cells are impassable
                }
                if (ny == rows - 1 && nx == cols - 1) {
                    reachedBottomRight = true;         // exit reached
                }
                if (visited[ny][nx] != token) {
                    queue.add(new Coord(nx, ny));
                }
            }
        }
        // The bottom‑right cell must have been visited in this BFS for success.
        return reachedBottomRight && visited[rows - 1][cols - 1] == token;
    }

    /** Simple bounds check for matrix coordinates. */
    private static boolean inside(int y, int x, int rows, int cols) {
        return y >= 0 && y < rows && x >= 0 && x < cols;
    }

    /**
     * Handles a single test case:
     * 1. Parses the grid.
     * 2. Verifies that no ‘B’ touches a ‘G’.
     * 3. Marks neighboring cells of ‘B’ as blocked (‘#’).
     * 4. Checks reachability from every ‘G’ to the exit.
     */
    private static void solveOneTest(InputReader in, PrintWriter out) {
        int n = in.nextInt();          // number of rows
        int m = in.nextInt();          // number of columns
        char[][] grid = new char[n][m];

        // Collect coordinates of all ‘G’ cells.
        Set<Coord> goals = new HashSet<>();
        for (int y = 0; y < n; y++) {
            String row = in.next();
            for (int x = 0; x < m; x++) {
                char ch = row.charAt(x);
                grid[y][x] = ch;
                if (ch == 'G') {
                    goals.add(new Coord(x, y));
                }
            }
        }

        // Rule: a ‘B’ must not be adjacent to any ‘G’.
        for (int y = 0; y < n; y++) {
            for (int x = 0; x < m; x++) {
                if (grid[y][x] == 'B') {
                    for (int[] d : DIRS) {
                        int ny = y + d[0];
                        int nx = x + d[1];
                        if (inside(ny, nx, n, m) && grid[ny][nx] == 'G') {
                            out.println("No");
                            return;
                        }
                    }
                }
            }
        }

        // Make a mutable copy of the grid to apply blocking rules.
        char[][] working = new char[n][];
        for (int y = 0; y < n; y++) {
            working[y] = grid[y].clone();
        }

        // Block any neighbour of a ‘B’ that is not ‘B’ or ‘G’.
        for (int y = 0; y < n; y++) {
            for (int x = 0; x < m; x++) {
                if (grid[y][x] == 'B') {
                    for (int[] d : DIRS) {
                        int ny = y + d[0];
                        int nx = x + d[1];
                        if (inside(ny, nx, n, m)
                                && working[ny][nx] != 'B'
                                && working[ny][nx] != 'G') {
                            working[ny][nx] = '#';
                        }
                    }
                }
            }
        }

        // All goals must be able to reach the bottom‑right corner.
        boolean success = allGoalsCanReachExit(working, goals, n, m);
        out.println(success ? "Yes" : "No");
    }

    /** Main driver – reads multiple test cases. */
    public static void main(String[] args) {
        InputStream in = System.in;
        OutputStream out = System.out;
        InputReader reader = new InputReader(in);
        PrintWriter writer = new PrintWriter(out);

        int t = reader.nextInt();                 // number of test cases
        for (int i = 0; i < t; i++) {
            solveOneTest(reader, writer);
        }

        writer.close();
    }
}

import java.io.*;
import java.util.*;

/**
 * Refactored solution – clearer structure, better naming and separation of concerns.
 */
public class Solution {

    /** Direction vectors used for neighbour traversal. */
    private static final int[][] DIRS = {{0, 1}, {0, -1}, {1, 0}, {-1, 0}};

    /** Entry point. */
    public static void main(String[] args) {
        InputStream in = System.in;
        OutputStream out = System.out;
        InputReader reader = new InputReader(in);
        PrintWriter writer = new PrintWriter(out);
        Solver solver = new Solver();
        solver.solve(reader, writer);
        writer.close();
    }

    /** -----------------------------------------------------------
     *  Core solver – contains all logic for a single test case.
     *  ----------------------------------------------------------- */
    static class Solver {

        /** Reads multiple test cases and processes each one. */
        void solve(InputReader in, PrintWriter out) {
            int tests = in.nextInt();
            for (int t = 0; t < tests; t++) {
                solveSingleCase(in, out);
            }
        }

        /** Handles one test case: reads grid, validates and prints answer. */
        private void solveSingleCase(InputReader in, PrintWriter out) {
            int n = in.nextInt();                 // rows
            int m = in.nextInt();                 // columns
            char[][] maze = readMaze(in, n, m);

            List<Cell> bads = findCells(maze, 'B');
            List<Cell> goods = findCells(maze, 'G');

            if (!canBlockBadCells(maze, bads)) {
                out.println("No");
                return;
            }

            if (!canAllGoodsReachExit(maze, goods)) {
                out.println("No");
                return;
            }

            out.println("Yes");
        }

        /** Reads the whole grid from input. */
        private char[][] readMaze(InputReader in, int n, int m) {
            char[][] maze = new char[n][m];
            for (int i = 0; i < n; i++) {
                String line = in.nextToken();
                maze[i] = line.toCharArray();
            }
            return maze;
        }

        /** Finds every cell that matches the given character. */
        private List<Cell> findCells(char[][] maze, char target) {
            List<Cell> result = new ArrayList<>();
            for (int i = 0; i < maze.length; i++) {
                for (int j = 0; j < maze[i].length; j++) {
                    if (maze[i][j] == target) {
                        result.add(new Cell(i, j));
                    }
                }
            }
            return result;
        }

        /** Attempts to block every reachable '.' from bad cells.
         *  Returns {@code false} as soon as a 'G' is encountered – because a bad could reach a good. */
        private boolean canBlockBadCells(char[][] maze, List<Cell> bads) {
            boolean[][] visited = new boolean[maze.length][maze[0].length];
            for (Cell bad : bads) {
                if (visited[bad.row][bad.col]) {
                    continue;
                }
                if (!expandFrom(bad.row, bad.col, maze, visited)) {
                    return false;               // bad reached a good cell
                }
            }
            return true;
        }

        /** DFS that expands from (y,x):
         *   - visits every reachable '.' cell,
         *   - turns those cells into walls '#', and
         *   - fails if a 'G' is reached.
         */
        private boolean expandFrom(int y, int x, char[][] maze, boolean[][] visited) {
            Deque<Cell> stack = new ArrayDeque<>();
            stack.push(new Cell(y, x));
            visited[y][x] = true;

            while (!stack.isEmpty()) {
                Cell cur = stack.pop();

                // If a good cell is reached, the configuration is invalid.
                if (maze[cur.row][cur.col] == 'G') {
                    return false;
                }

                for (int[] d : DIRS) {
                    int ny = cur.row + d[0];
                    int nx = cur.col + d[1];
                    if (!inBounds(ny, nx, maze) || visited[ny][nx] || maze[ny][nx] == '#') {
                        continue;
                    }

                    visited[ny][nx] = true;
                    char cellChar = maze[ny][nx];
                    if (cellChar == '.') {
                        // Block the path for further expansion.
                        maze[ny][nx] = '#';
                    }
                    // Any traversable cell (including 'B') is pushed for further exploration.
                    stack.push(new Cell(ny, nx));
                }
            }
            return true;
        }

        /** Checks whether every good cell can reach the bottom‑right corner (exit). */
        private boolean canAllGoodsReachExit(char[][] maze, List<Cell> goods) {
            // If the exit is a wall, it can only be acceptable when there are no goods.
            if (maze[n - 1][m - 1] == '#') {
                return goods.isEmpty();
            }

            boolean[][] visited = new boolean[n][m];
            Queue<Cell> q = new ArrayDeque<>();
            q.add(new Cell(n - 1, m - 1));
            visited[n - 1][m - 1] = true;

            while (!q.isEmpty()) {
                Cell cur = q.poll();
                for (int[] d : DIRS) {
                    int ny = cur.row + d[0];
                    int nx = cur.col + d[1];
                    if (!inBounds(ny, nx, maze) || visited[ny][nx] || maze[ny][nx] == '#') {
                        continue;
                    }
                    visited[ny][nx] = true;
                    q.add(new Cell(ny, nx));
                }
            }

            // All goods must have been visited.
            for (Cell g : goods) {
                if (!visited[g.row][g.col]) {
                    return false;
                }
            }
            return true;
        }

        /** Simple bounds check. */
        private boolean inBounds(int r, int c, char[][] maze) {
            return r >= 0 && r < maze.length && c >= 0 && c < maze[0].length;
        }
    }

    /** -----------------------------------------------------------
     *  Small immutable container for a matrix coordinate.
     *  ----------------------------------------------------------- */
    private static final class Cell {
        final int row;
        final int col;
        Cell(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }

    /** -----------------------------------------------------------
     *  Fast input reader based on BufferedReader and StringTokenizer.
     *  ----------------------------------------------------------- */
    static class InputReader {
        private final BufferedReader br;
        private StringTokenizer st;

        InputReader(InputStream stream) {
            br = new BufferedReader(new InputStreamReader(stream));
        }

        String nextToken() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    throw new UncheckedIOException(e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(nextToken());
        }
    }
}

/**
 * Refactored solution for the “Labyrinth” problem.
 *
 * <p>This version improves readability, maintains a clear separation of concerns,
 * and uses expressive naming and modern Java idioms while preserving the original
 * functionality.</p>
 */
public class Solution {

    /** Directions used for neighbour exploration (up, right, down, left). */
    private static final int[] DR = {-1, 0, 1, 0};
    /** Directions used for neighbour exploration (up, right, down, left). */
    private static final int[] DC = {0, 1, 0, -1};

    /** Input helper – thin wrapper around {@link InputStream}. */
    private static final class InputReader {
        private final InputStream stream;
        private final byte[] buffer = new byte[16_384];
        private int bufferPos = 0, bufferLength = 0;

        InputReader(final InputStream stream) {
            this.stream = stream;
        }

        private int readByte() {
            if (bufferPos >= bufferLength) {
                bufferLength = stream.read(buffer);
                bufferPos = 0;
                if (bufferLength == -1) {
                    throw new IllegalStateException();
                }
            }
            return buffer[bufferPos++];
        }

        /** Reads the next non‑whitespace character. */
        private int nextNonWhitespace() {
            int c;
            do {
                c = readByte();
            } while (isSpaceChar(c));
            return c;
        }

        /** Checks whether the current character is a whitespace character. */
        private static boolean isSpaceChar(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        /** Reads a line of text (up to the next newline). */
        private String readToken() {
            StringBuilder sb = new StringBuilder();
            int c;
            while (!isSpaceChar(c = readByte())) {
                sb.appendCodePoint(c);
            }
            return sb.toString();
        }

        /** Reads the next integral number. */
        public int readInt() {
            int sign = 1;
            int c = nextNonWhitespace();
            if (c == '-') {
                sign = -1;
                c = nextNonWhitespace();
            }
            int value = 0;
            do {
                value = value * 10 + (c - '0');
                c = nextNonWhitespace();
            } while (!isSpaceChar(c));
            return sign * value;
        }
    }

    /** Output helper – thin wrapper around {@link OutputStream}. */
    private static final class OutputWriter {
        private final PrintWriter writer;

        OutputWriter(final OutputStream out) {
            this.writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(out)));
        }

        /** Prints the supplied objects separated by a single space. */
        void print(final Object... objects) {
            for (int i = 0; i < objects.length; i++) {
                if (i != 0) writer.print(' ');
                writer.print(objects[i]);
            }
        }

        /** Prints the supplied objects followed by a line separator. */
        void printLine(final Object... objects) {
            print(objects);
            writer.println();
        }

        /** Flushes the underlying stream. */
        void flush() {
            writer.flush();
        }

        /** Closes the underlying stream. */
        void close() {
            writer.close();
        }
    }

    /** --------------------------------------------------------------------- *
     *  Core solving logic
     *  --------------------------------------------------------------------- */

    /** The maze (grid) representing the current test case. */
    private char[][] grid;

    /** Number of rows and columns of the current maze. */
    private int rows, cols;

    /** Global visited flag array reused for DFS/BFS. */
    private int[][] visited;

    /**
     * Solves a single test case.
     *
     * @param in  input reader
     * @param out output writer
     */
    private void solveCase(final InputReader in, final OutputWriter out) {
        rows = in.readInt();
        cols = in.readInt();

        grid = new char[rows][];
        for (int r = 0; r < rows; r++) {
            grid[r] = in.readString().toCharArray();
        }

        // The exit cell must not be a wall or a trapped bomb.
        if (grid[rows - 1][cols - 1] == 'B' || grid[rows - 1][cols - 1] == '#') {
            out.printLine("No");
            return;
        }

        // -----------------------------------------------------------------
        // 1️⃣  Block all cells that must become walls because of bombs.
        // -----------------------------------------------------------------
        blockBombInfluence();

        // -----------------------------------------------------------------
        // 2️⃣  Verify that every good cell ('G') can still reach the exit.
        // -----------------------------------------------------------------
        boolean possible = true;
        for (int r = 0; r < rows && possible; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == 'G') {
                    resetVisited();
                    if (!canReachExit(r, c)) {
                        possible = false;
                        break;
                    }
                }
            }
        }

        out.printLine(possible ? "Yes" : "No");
    }

    /** Converts every empty cell ('.') that is adjacent to a bomb ('B') into a wall. */
    private void blockBombInfluence() {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == 'B') {
                    // The bomb cell itself is never an obstacle for a good cell,
                    // but we must block all '.' neighbours.
                    for (int dir = 0; dir < 4; dir++) {
                        int nr = r + DR[dir];
                        int nc = c + DC[dir];
                        if (isInside(nr, nc) && grid[nr][nc] == '.') {
                            grid[nr][nc] = '#';
                        }
                    }
                }
            }
        }
    }

    /** Depth‑first search that checks whether the exit is reachable from (sr, sc). */
    private boolean canReachExit(final int sr, final int sc) {
        resetVisited();
        return dfsReachExit(sr, sc);
    }

    /** Simple DFS that returns true if the target cell (rows‑1, cols‑1) can be reached. */
    private boolean dfsReachExit(final int r, final int c) {
        if (!isInside(r, c)) {
            return false;
        }
        if (visited[r][c] == 1) {
            return false;
        }
        if (grid[r][c] == '#') {
            return false;
        }
        // Reached the exit?
        if (r == rows - 1 && c == cols - 1) {
            return true;
        }

        visited[r][c] = 1;
        for (int dir = 0; dir < 4; dir++) {
            if (dfsReachExit(r + DR[dir], c + DC[dir])) {
                return true;
            }
        }
        return false;
    }

    /** Resets the global {@code visited} array to all zeros. */
    private void resetVisited() {
        if (visited == null || visited.length != rows) {
            visited = new int[rows][cols];
        } else {
            for (int r = 0; r < rows; r++) {
                java.util.Arrays.fill(visited[r], 0);
            }
        }
    }

    /** Checks whether (r, c) lies inside the current grid. */
    private boolean isInside(final int r, final int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    /** --------------------------------------------------------------------- *
     *  Entry point
     *  --------------------------------------------------------------------- */

    public static void main(final String[] args) {
        final Solution solver = new Solution();
        final InputReader in = new InputReader(System.in);
        final OutputWriter out = new OutputWriter(System.out);

        final int tests = in.readInt();
        for (int t = 0; t < tests; t++) {
            solver.solveCase(in, out);
        }

        out.flush();
    }
}

import java.io.*;
import java.util.*;
import java.util.function.BiConsumer;

/**
 * Refactored solution for the original {@code E} program.
 *
 * <p>Key improvements:
 *
 * <ul>
 *   <li>Extracted small, single‑responsibility methods (pre‑processing,
 *       BFS, validation, etc.) to eliminate duplicated code.</li>
 *   <li>Used expressive names and Java 8 functional interfaces to reduce
 *       boilerplate.</li>
 *   <li>Wrapped related utilities (Point, input handling) inside the class
 *       to keep the public API clean.</li>
 *   <li>Added Javadoc comments and constant fields for readability.</li>
 *   <li>Handled input tokenisation safely and closed the reader only at
 *       program termination.</li>
 * </ul>
 *
 * <p>The logic is identical to the original program:
 *
 * <ol>
 *   <li>Expand every 'B' cell by turning adjacent '.' into '#'.</li>
 *   <li>Verify that the bottom‑right cell is reachable from **all**
 *       'G' components and **none** of the 'B' components.</li>
 *   <li>Print "Yes" if the condition holds, otherwise "No".</li>
 * </ol>
 */
public class RefactoredE {

    /* ---------------------------------------------------------- */
    /* Constant symbols – makes the intent of characters clear.   */
    /* ---------------------------------------------------------- */
    private static final char BLANK    = '.';
    private static final char BOSS     = 'B';
    private static final char GUARD    = 'G';
    private static final char OBSTACLE = '#';

    /* ---------------------------------------------------------- */
    /* Core solver entry point.                                   */
    /* ---------------------------------------------------------- */
    public static void main(String[] args) throws Exception {
        new RefactoredE().solve();
    }

    /* ---------------------------------------------------------- */
    /* Public driver method – reads all test cases, processes them */
    /* and prints the collected answers.                          */
    /* ---------------------------------------------------------- */
    private void solve() throws IOException {
        reader = new BufferedReader(new InputStreamReader(System.in, java.nio.charset.StandardCharsets.UTF_8));
        StringTokenizer tokenizer = null;

        int T = nextInt(tokenizer);
        StringBuilder output = new StringBuilder();

        for (int t = 0; t < T; t++) {
            output.append(processTestCase(tokenizer)).append('\n');
        }

        System.out.print(output.toString());
    }

    /* ---------------------------------------------------------- */
    /* Reads a single test case, performs the algorithm and returns */
    /* the result string ("Yes" or "No").                           */
    /* ---------------------------------------------------------- */
    private String processTestCase(StringTokenizer tokenizer) throws IOException {
        int n = nextInt(tokenizer);
        int m = nextInt(tokenizer);
        char[][] grid = readGrid(n, m, tokenizer);

        expandBossBorders(grid);
        boolean can = validate(grid);

        return can ? "Yes" : "No";
    }

    /* ---------------------------------------------------------- */
    /* Expands every 'B' by converting adjacent '.' cells to '#'. */
    /* ---------------------------------------------------------- */
    private void expandBossBorders(char[][] grid) {
        int rows = grid.length;
        int cols = grid[0].length;

        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == BOSS) {
                    tryExpand(grid, r - 1, c);
                    tryExpand(grid, r + 1, c);
                    tryExpand(grid, r,     c - 1);
                    tryExpand(grid, r,     c + 1);
                }
            }
        }
    }

    /** Safely attempts to replace '.' at (x,y) with '#'. */
    private void tryExpand(char[][] grid, int x, int y) {
        if (x < 0 || x >= grid.length || y < 0 || y >= grid[0].length) {
            return;
        }
        if (grid[x][y] == BLANK) {
            grid[x][y] = OBSTACLE;
        }
    }

    /* ---------------------------------------------------------- */
    /* Main validation: bottom‑right must be reachable from all   */
    /* 'G' components and from no 'B' component.                  */
    /* ---------------------------------------------------------- */
    private boolean validate(char[][] grid) {
        int rows = grid.length;
        int cols = grid[0].length;

        boolean endReachableFromAllG   = true;
        boolean endReachableFromAnyB  = false;

        /* Global visited matrices to avoid reprocessing the same component */
        boolean[][] visitedG = new boolean[rows][cols];
        boolean[][] visitedB = new boolean[rows][cols];

        /* BFS factory – returns a fresh visited matrix for each start cell */
        BiConsumer<Integer, Integer> bfs = (sr, sc) -> {
            boolean[][] visited = new boolean[rows][cols];
            Queue<Point> queue = new ArrayDeque<>();
            queue.add(new Point(sr, sc));
            visited[sr][sc] = true;

            while (!queue.isEmpty()) {
                Point cur = queue.poll();
                exploreNeighbour(cur.x - 1, cur.y, grid, visited, queue);
                exploreNeighbour(cur.x + 1, cur.y, grid, visited, queue);
                exploreNeighbour(cur.x,     cur.y - 1, grid, visited, queue);
                exploreNeighbour(cur.x,     cur.y + 1, grid, visited, queue);
            }
            return visited;
        };

        /* ---- 1) Process all 'G' components ---- */
        for (int r = 0; r < rows && endReachableFromAllG; r++) {
            for (int c = 0; c < cols && endReachableFromAllG; c++) {
                if (grid[r][c] == GUARD && !visitedG[r][c]) {
                    boolean[][] compVisited = bfs.accept(r, c);
                    if (!compVisited[rows - 1][cols - 1]) {
                        endReachableFromAllG = false;           // this G component cannot reach the end
                    }
                    markComponentVisited(visitedG, compVisited);
                }
            }
        }

        /* ---- 2) Process all 'B' components ---- */
        for (int r = 0; r < rows && !endReachableFromAnyB; r++) {
            for (int c = 0; c < cols && !endReachableFromAnyB; c++) {
                if (grid[r][c] == BOSS && !visitedB[r][c]) {
                    boolean[][] compVisited = bfs.accept(r, c);
                    if (compVisited[rows - 1][cols - 1]) {
                        endReachableFromAnyB = true;            // a B component can reach the end
                    }
                    markComponentVisited(visitedB, compVisited);
                }
            }
        }

        return endReachableFromAllG && !endReachableFromAnyB;
    }

    /** Copies all true cells from {@code source} into {@code target}. */
    private void markComponentVisited(boolean[][] target, boolean[][] source) {
        for (int i = 0; i < target.length; i++) {
            for (int j = 0; j < target[0].length; j++) {
                if (source[i][j]) {
                    target[i][j] = true;
                }
            }
        }
    }

    /** Explores a neighbour cell; if inside bounds and not an obstacle, marks it visited and enqueues it. */
    private void exploreNeighbour(int x, int y, char[][] grid,
                                  boolean[][] visited, Queue<Point> queue) {
        if (x < 0 || x >= grid.length || y < 0 || y >= grid[0].length) {
            return;
        }
        if (!visited[x][y] && grid[x][y] != OBSTACLE) {
            visited[x][y] = true;
            queue.add(new Point(x, y));
        }
    }

    /** Simple (x, y) holder used by BFS. */
    private static final class Point {
        final int x, y;
        Point(int x, int y) {
            this.x = x;
            this.y = y;
        }
    }

    /* ---------------------------------------------------------- */
    /* Input helpers – token‑based, tolerant to whitespace.        */
    /* ---------------------------------------------------------- */
    private BufferedReader reader;
    private StringTokenizer tokenizer;

    /** Returns the next integer token, reading a new line when necessary. */
    private int nextInt(StringTokenizer tokenizer) throws IOException {
        // Ensure the tokenizer has data; if not, read the next non‑empty line.
        while (tokenizer == null || !tokenizer.hasMoreTokens()) {
            String line = reader.readLine();
            if (line == null) {
                throw new EOFException();
            }
            tokenizer = new StringTokenizer(line);
        }
        return Integer.parseInt(tokenizer.nextToken());
    }

    /** Reads a grid of size {@code rows}×{@code cols} from the tokenizer. */
    private char[][] readGrid(int rows, int cols, StringTokenizer tokenizer) throws IOException {
        char[][] grid = new char[rows][cols];
        for (int r = 0; r < rows; r++) {
            // Each row line may be split across multiple token reads; therefore we
            // fetch the whole line via the BufferedReader directly.
            String line;
            do {
                line = reader.readLine();
                if (line == null) {
                    throw new EOFException();
                }
            } while (line.trim().isEmpty());   // skip blank lines if any

            for (int c = 0; c < cols; c++) {
                grid[r][c] = line.charAt(c);
            }
        }
        return grid;
    }
}

import java.io.*;
import java.util.*;

/**
 * Main class that contains the entry point of the program.
 * It uses helper classes to keep the logic clean and testable.
 */
public class Main {

    /* ---------------------------------------------------------------------- *
     *  Fast I/O helpers
     * ---------------------------------------------------------------------- */
    /** Simple wrapper around BufferedReader that can tokenise the input. */
    private static final class FastScanner {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        FastScanner(InputStream in) {
            this.reader = new BufferedReader(new InputStreamReader(in));
        }

        /** Reads the next integer from the input. */
        int nextInt() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                tokenizer = new StringTokenizer(reader.readLine());
            }
            return Integer.parseInt(tokenizer.nextToken());
        }
    }

    /** Wrapper around PrintWriter that adds a convenient method for answers. */
    private static final class FastPrinter extends PrintWriter {
        FastPrinter(OutputStream out) {
            super(out);
        }

        /** Prints “Yes” or “No” followed by a line‑break. */
        void printAnswer(boolean yes) {
            println(yes ? "Yes" : "No");
        }
    }

    /* ---------------------------------------------------------------------- *
     *  Core logic
     * ---------------------------------------------------------------------- */
    /** Directions used for neighbour checks (up, down, left, right). */
    private static final int[][] DIRECTIONS = {
            {-1, 0}, {1, 0}, {0, -1}, {0, 1}
    };

    /** Small immutable container for a cell position. */
    private static final class Point {
        final int r, c;
        Point(int r, int c) { this.r = r; this.c = c; }
    }

    /**
     * Encapsulates everything that belongs to a single test case.
     * The class holds the maze and provides the algorithm that decides whether
     * every ‘G’ can reach the bottom‑right cell.
     */
    private static final class MazeSolver {
        private final char[][] maze;
        private final int rows, cols;

        MazeSolver(char[][] maze) {
            this.maze = maze;
            this.rows = maze.length;
            this.cols = maze[0].length;
        }

        /** Executes the whole verification for the current maze. */
        boolean canAllGoodEscape() {
            // 1️⃣  Block every empty neighbour of a Bessie ('B')
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (maze[r][c] == 'B') {
                        surroundEmptyNeighbours(r, c);
                        if (isGoodAdjacent(r, c)) {
                            // A Good cell next to a Bessie makes escaping impossible
                            return false;
                        }
                    }
                }
            }

            // 2️⃣  Count all Good cells that need to reach the exit
            int totalGood = countGoodCells();

            // 3️⃣  BFS from the exit (bottom‑right) to see which cells are reachable
            boolean[][] visited = new boolean[rows][cols];
            Queue<Point> queue = new ArrayDeque<>();

            if (maze[rows - 1][cols - 1] != '#') {
                queue.add(new Point(rows - 1, cols - 1));
                visited[rows - 1][cols - 1] = true;
            }

            int escapedGood = 0;
            while (!queue.isEmpty()) {
                Point cur = queue.poll();
                if (maze[cur.r][cur.c] == 'G') {
                    escapedGood++;
                }

                for (int[] dir : DIRECTIONS) {
                    int nr = cur.r + dir[0];
                    int nc = cur.c + dir[1];
                    if (inBounds(nr, nc) && !visited[nr][nc] && maze[nr][nc] != '#') {
                        visited[nr][nc] = true;
                        queue.add(new Point(nr, nc));
                    }
                }
            }

            // 4️⃣  Success only if every Good cell managed to escape
            return escapedGood == totalGood;
        }

        /** Returns true if the cell at (r,c) is adjacent to at least one 'G'. */
        private boolean isGoodAdjacent(int r, int c) {
            for (int[] d : DIRECTIONS) {
                int nr = r + d[0];
                int nc = c + d[1];
                if (inBounds(nr, nc) && maze[nr][nc] == 'G') {
                    return true;
                }
            }
            return false;
        }

        /** Returns true if the cell at (r,c) is inside the grid. */
        private boolean inBounds(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }

        /** Surrounds every empty neighbour of (r,c) with a wall ('#'). */
        private void surroundEmptyNeighbours(int r, int c) {
            for (int[] d : DIRECTIONS) {
                int nr = r + d[0];
                int nc = c + d[1];
                if (inBounds(nr, nc) && maze[nr][nc] == '.') {
                    maze[nr][nc] = '#';
                }
            }
        }

        /** Counts the number of 'G' cells in the whole maze. */
        private int countGoodCells() {
            int cnt = 0;
            for (char[] row : maze) {
                for (char cell : row) {
                    if (cell == 'G') cnt++;
                }
            }
            return cnt;
        }
    }

    /* ---------------------------------------------------------------------- *
     *  Program entry point
     * ---------------------------------------------------------------------- */
    public static void main(String[] args) throws IOException {
        // The try‑with‑resources block guarantees that all streams are closed.
        try (FastScanner fs = new FastScanner(System.in);
             FastPrinter out = new FastPrinter(System.out)) {

            int tests = fs.nextInt();
            while (tests-- > 0) {
                int n = fs.nextInt();
                int m = fs.nextInt();

                // Read each row as a single token (the original input contains no spaces).
                char[][] maze = new char[n][];
                for (int i = 0; i < n; i++) {
                    maze[i] = fs.readToken().toCharArray();
                }

                MazeSolver solver = new MazeSolver(maze);
                out.printAnswer(solver.canAllGoodEscape());
            }
        }
    }
}

import java.io.BufferedInputStream;
import java.util.Scanner;

/**
 * Solution for the “Grid Escape” problem.
 * <p>
 * The program reads a number of test cases.
 * For each case it receives the size of a grid (n × m) and the grid itself.
 * Cells can be empty ('.'), blocked ('#'), a blue box ('B') or a green box ('G').
 * <p>
 * Rules (kept identical to the original implementation):
 * 1. A 'B' must not be orthogonally adjacent to a 'G'.
 * 2. All cells that can reach the bottom‑right corner while moving only through
 *    '.' cells must be reachable from there; otherwise the answer is “No”.
 * 3. If the above are satisfied we block every empty neighbour of every 'B'
 *    with a '#'. Afterwards we perform a DFS from the exit (n‑1, m‑1) to see
 *    whether all 'G' cells are visited.
 * The answer is printed as “Yes” or “No”.
 */
public class Solution {

    /** Symbols used in the grid. */
    private static final char EMPTY = '.';
    private static final char WALL  = '#';
    private static final char GREEN = 'G';
    private static final char BLUE  = 'B';

    /** Directions used for neighbour checks (up, down, left, right). */
    private static final int[] DY = {-1, 1, 0, 0};
    private static final int[] DX = {0, 0, -1, 1};

    private final Scanner scanner;

    /** Constructor – injects a Scanner (easily mockable in tests). */
    public Solution(Scanner scanner) {
        this.scanner = scanner;
    }

    /** Entry point – processes all test cases. */
    public static void main(String[] args) {
        try (Scanner in = new Scanner(new BufferedInputStream(System.in))) {
            new Solution(in).run();
        }
    }

    /** Main driver that reads a single test case and prints the answer. */
    private void run() {
        int t = scanner.nextInt();
        while (t-- > 0) {
            processTestCase();
        }
    }

    /** Handles one complete test case (input → answer). */
    private void processTestCase() {
        int n = scanner.nextInt();
        int m = scanner.nextInt();
        char[][] grid = readGrid(n, m);

        // Step 1 – sanity check: no 'B' touches a 'G' directly.
        if (hasDirectNeighbourBetweenBlueAndGreen(grid, n, m)) {
            System.out.println("No");
            return;
        }

        // Step 2 – block all empty neighbours of every 'B'.
        blockNeighbouringEmptyCells(grid, n, m);

        // Step 3 – flood‑fill from the exit (bottom‑right cell).
        boolean[][] visited = new boolean[n][m];
        dfsFromExit(grid, visited, n, m);

        // Step 4 – verify that every 'G' was reached.
        if (!allGreensVisited(grid, visited, n, m)) {
            System.out.println("No");
            return;
        }

        System.out.println("Yes");
    }

    /** Reads the grid of size n×m from the scanner. */
    private char[][] readGrid(int n, int m) {
        char[][] grid = new char[n][m];
        for (int i = 0; i < n; i++) {
            String row = scanner.next();
            grid[i] = row.toCharArray();
        }
        return grid;
    }

    /**
     * Returns true if any 'B' cell is orthogonally adjacent to a 'G' cell.
     * This violates the problem constraints, causing an immediate “No”.
     */
    private boolean hasDirectNeighbourBetweenBlueAndGreen(char[][] grid, int n, int m) {
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i][j] != BLUE) {
                    continue;
                }
                for (int d = 0; d < 4; d++) {
                    int ni = i + DY[d];
                    int nj = j + DX[d];
                    if (isWithinBounds(ni, nj, n, m) && grid[ni][nj] == GREEN) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    /** Blocks (turns into '#') every empty neighbour of each 'B'. */
    private void blockNeighbouringEmptyCells(char[][] grid, int n, int m) {
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i][j] == BLUE) {
                    for (int d = 0; d < 4; d++) {
                        int ni = i + DY[d];
                        int nj = j + DX[d];
                        if (isWithinBounds(ni, nj, n, m) && grid[ni][nj] == EMPTY) {
                            grid[ni][nj] = WALL;
                        }
                    }
                }
            }
        }
    }

    /** Depth‑first search starting from the bottom‑right corner (n‑1, m‑1). */
    private void dfsFromExit(char[][] grid, boolean[][] visited, int n, int m) {
        if (grid[n - 1][m - 1] == WALL) {
            // If the exit itself is blocked, nothing can be visited.
            return;
        }
        visited[n - 1][m - 1] = true;
        for (int d = 0; d < 4; d++) {
            int ni = n - 1 + DY[d];
            int nj = m - 1 + DX[d];
            if (canVisit(ni, nj, grid, visited, n, m)) {
                dfsFromExit(grid, visited, ni, nj);
            }
        }
    }

    /** Checks whether a cell (y, x) can be visited (inside bounds, not a wall, not visited). */
    private boolean canVisit(int y, int x, char[][] grid, boolean[][] visited, int n, int m) {
        return isWithinBounds(y, x, n, m)
                && grid[y][x] != WALL
                && !visited[y][x];
    }

    /** Simple bounds check. */
    private boolean isWithinBounds(int y, int x, int n, int m) {
        return y >= 0 && y < n && x >= 0 && x < m;
    }

    /** Returns true iff every 'G' cell has been visited during the DFS. */
    private boolean allGreensVisited(char[][] grid, boolean[][] visited, int n, int m) {
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i][j] == GREEN && !visited[i][j]) {
                    return false;
                }
            }
        }
        return true;
    }
}

import java.io.*;
import java.util.ArrayDeque;
import java.util.Deque;

/**
 * Entry point of the program.
 *
 * <p>It reads many test cases, solves each one independently and prints 'Yes' or 'No'
 * according to the rules of the problem.</p>
 */
public class Main {

    /* --------------------------------------------------------------------- */
    /*  Input / Output helpers                                                 */
    /* --------------------------------------------------------------------- */

    /** Simple scanner that works with {@link BufferedReader}. */
    private static final class Scanner {
        private final BufferedReader br;
        private StringTokenizer st;

        Scanner(InputStream in) {
            this.br = new BufferedReader(new InputStreamReader(in));
        }

        /** Returns the next token, reading a new line when necessary. */
        private String nextToken() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                st = new StringTokenizer(br.readLine());
            }
            return st.nextToken();
        }

        /** Reads the next integer. */
        int nextInt() throws IOException {
            return Integer.parseInt(nextToken());
        }

        /** Reads the next line (including empty lines). */
        String nextLine() throws IOException {
            return br.readLine();
        }
    }

    /** Wrapper around {@link PrintWriter} that automatically flushes on demand. */
    private static final PrintWriter out = new PrintWriter(System.out, true);

    /* --------------------------------------------------------------------- */
    /*  Directions utilities                                                   */
    /* --------------------------------------------------------------------- */

    /**
     * Helper class that stores a single 2‑D step (row offset, column offset).
     * The four main compass directions are provided as constants.
     */
    private static final class Direction {
        final int dr;
        final int dc;

        Direction(int dr, int dc) {
            this.dr = dr;
            this.dc = dc;
        }
    }

    /** All four orthogonal directions. */
    private static final Direction[] STEPS = {
            new Direction(-1, 0), // up
            new Direction(0, 1),  // right
            new Direction(1, 0),  // down
            new Direction(0, -1)  // left
    };

    /* --------------------------------------------------------------------- */
    /*  Core solving logic                                                     */
    /* --------------------------------------------------------------------- */

    /**
     * Solves a single test case.
     *
     * @param grid the maze represented as a mutable char matrix
     */
    private static void solveTestCase(char[][] grid) {
        Solver solver = new Solver(grid);
        solver.run();
    }

    /**
     * Encapsulates the whole algorithm for one test case.
     */
    private static final class Solver {
        private final char[][] grid;      // mutable grid we work on
        private final boolean[][] visited; // BFS visited flags
        private final int rows, cols;     // grid dimensions

        Solver(char[][] grid) {
            this.grid = grid;
            this.rows = grid.length;
            this.cols = grid[0].length;
            this.visited = new boolean[rows][cols];
        }

        /** Public entry point – contains the overall flow control. */
        void run() {
            if (hasGAdjacentToBomb()) {
                out.println("No");
                return;
            }

            blockNeighbouringEmptyCells();

            if (grid[rows - 1][cols - 1] == '#') {
                out.println("No");
                return;
            }

            bfsFromExit();

            if (!allGVisited()) {
                out.println("No");
                return;
            }

            out.println("Yes");
        }

        /** Checks whether any 'G' cell touches a bomb 'B' directly. */
        private boolean hasGAdjacentToBomb() {
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (grid[r][c] != 'G') continue;
                    if (adjacentContainsBomb(r, c)) {
                        return true;
                    }
                }
            }
            return false;
        }

        /** Returns {@code true} if at least one orthogonal neighbour of (r,c) is a bomb. */
        private boolean adjacentContainsBomb(int r, int c) {
            for (Direction dir : STEPS) {
                int nr = r + dir.dr;
                int nc = c + dir.dc;
                if (inBounds(nr, nc) && grid[nr][nc] == 'B') {
                    return true;
                }
            }
            return false;
        }

        /** Turns every '.' that touches a bomb into a wall '#'. */
        private void blockNeighbouringEmptyCells() {
            outer:
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (grid[r][c] != 'B') continue;
                    for (Direction dir : STEPS) {
                        int nr = r + dir.dr;
                        int nc = c + dir.dc;
                        if (inBounds(nr, nc) && grid[nr][nc] == '.') {
                            grid[nr][nc] = '#';
                        }
                    }
                }
            }
        }

        /** Breadth‑first search from the bottom‑right cell, ignoring walls. */
        private void bfsFromExit() {
            Deque<int[]> q = new ArrayDeque<>();
            if (grid[rows - 1][cols - 1] == '#') {
                return; // already handled above
            }

            q.add(new int[]{rows - 1, cols - 1});
            visited[rows - 1][cols - 1] = true;

            while (!q.isEmpty()) {
                int[] cur = q.poll();
                int r = cur[0];
                int c = cur[1];

                for (Direction dir : STEPS) {
                    int nr = r + dir.dr;
                    int nc = c + dir.dc;
                    if (!inBounds(nr, nc)
                            || visited[nr][nc]
                            || grid[nr][nc] == '#') {
                        continue;
                    }
                    visited[nr][nc] = true;
                    q.add(new int[]{nr, nc});
                }
            }
        }

        /** Returns {@code true} if every 'G' cell has been visited during BFS. */
        private boolean allGVisited() {
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (grid[r][c] == 'G' && !visited[r][c]) {
                        return false;
                    }
                }
            }
            return true;
        }

        /** Simple bounds check. */
        private boolean inBounds(int r, int c) {
            return 0 <= r && r < rows && 0 <= c && c < cols;
        }
    }

    /* --------------------------------------------------------------------- */
    /*  Main orchestration                                                     */
    /* --------------------------------------------------------------------- */

    public static void main(String[] args) throws Exception {
        Scanner scanner = new Scanner(System.in);
        int tests = scanner.nextInt();

        while (tests-- > 0) {
            int n = scanner.nextInt();
            int m = scanner.nextInt();
            char[][] grid = new char[n][];

            for (int i = 0; i < n; i++) {
                String line = scanner.nextLine(); // consumes end‑of‑line left by nextInt()
                grid[i] = line.toCharArray();
            }

            solveTestCase(grid);
        }

        out.flush();
    }
}

import java.io.*;
import java.util.*;

/**
 * Solves the “Maze” problem.
 *
 * <p>
 *   The algorithm consists of three logical parts:
 *   <ul>
 *     <li>Parse the grid and check whether any wall next to a goat also touches a lion.</li>
 *     <li>Perform a BFS from the exit cell (bottom‑right) to compute every cell that can be reached.</li>
 *     <li>Verify that every goat can be reached from the exit.</li>
 *   </ul>
 * </p>
 */
public class SolveTheMaze {

    /** directions: down, right, up, left */
    private enum Direction {
        DOWN(1, 0), RIGHT(0, 1), UP(-1, 0), LEFT(0, -1);

        final int dr;
        final int dc;

        Direction(int dr, int dc) {
            this.dr = dr;
            this.dc = dc;
        }

        int[] delta() {
            return new int[] {dr, dc};
        }
    }

    /** Fast scanner – works like the original FastReader but with try‑with‑resources safety. */
    private static final class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner(InputStream in) {
            this.br = new BufferedReader(new InputStreamReader(in));
            this.st = null;
        }

        /** Reads next token, blocking until one is available. */
        private String nextToken() throws IOException {
            while (st == null || !st.hasMoreElements()) {
                String line = br.readLine();
                if (line == null) {
                    return null;
                }
                st = new StringTokenizer(line);
            }
            return st.nextToken();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(nextToken());
        }

        long nextLong() throws IOException {
            return Long.parseLong(nextToken());
        }

        double nextDouble() throws IOException {
            return Double.parseDouble(nextToken());
        }

        String nextLine() throws IOException {
            String line = br.readLine();
            if (line == null) {
                return "";
            }
            return line;
        }
    }

    /** Entry point – processes multiple test cases. */
    public static void main(String[] args) throws IOException {
        try (FastScanner scanner = new FastScanner(System.in);
             PrintWriter out = new PrintWriter(System.out, true)) {

            int tests = scanner.nextInt();

            while (tests-- > 0) {
                solveSingleTest(scanner, out);
            }
        }
    }

    /** Handles one test case: reads input, validates, runs BFS and prints the answer. */
    private static void solveSingleTest(FastScanner in, PrintWriter out) {
        int rows = in.nextInt();
        int cols = in.nextInt();

        char[][] grid = new char[rows][cols];
        for (int r = 0; r < rows; r++) {
            String line = in.nextLine();
            for (int c = 0; c < cols; c++) {
                grid[r][c] = line.charAt(c);
            }
        }

        Direction[] dirs = Direction.values();

        // ------------------------------------------------------------
        // 1️⃣  Verify that no wall is placed adjacent to a goat when a lion is
        //      present on the opposite side.
        // ------------------------------------------------------------
        boolean configurationValid = true;

        for (int r = 0; r < rows && configurationValid; r++) {
            for (int c = 0; c < cols && configurationValid; c++) {
                if (grid[r][c] != 'B') {
                    continue;
                }
                for (Direction d : dirs) {
                    int nr = r + d.dr;
                    int nc = c + d.dc;
                    if (!inside(grid, nr, nc)) {
                        continue;
                    }
                    char neighbour = grid[nr][nc];
                    if (neighbour == '.') {
                        grid[nr][nc] = '#';
                    } else if (neighbour == 'G') {
                        configurationValid = false; // a goat touches a lion via a wall
                    }
                }
            }
        }

        if (!configurationValid) {
            out.println("No");
            return;
        }

        // ------------------------------------------------------------
        // 2️⃣  BFS from the exit cell (rows‑1, cols‑1) to mark reachable cells.
        // ------------------------------------------------------------
        boolean[][] reachable = new boolean[rows][cols];
        Queue<int[]> queue = new ArrayDeque<>();

        // exit may be empty ('.') or a goat ('G')
        if (grid[rows - 1][cols - 1] == '.' || grid[rows - 1][cols - 1] == 'G') {
            queue.add(new int[] { rows - 1, cols - 1 });
            reachable[rows - 1][cols - 1] = true;
        }

        while (!queue.isEmpty()) {
            int[] cur = queue.remove();
            int r = cur[0];
            int c = cur[1];
            for (Direction d : dirs) {
                int nr = r + d.dr;
                int nc = c + d.dc;
                if (!inside(grid, nr, nc)) {
                    continue;
                }
                char cell = grid[nr][nc];
                if ((cell == '.' || cell == 'G') && !reachable[nr][nc]) {
                    reachable[nr][nc] = true;
                    queue.add(new int[] { nr, nc });
                }
            }
        }

        // ------------------------------------------------------------
        // 3️⃣  Every goat must be reachable from the exit.
        // ------------------------------------------------------------
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == 'G' && !reachable[r][c]) {
                    out.println("No");
                    return;
                }
            }
        }

        out.println("Yes");
    }

    /** Utility – checks whether a coordinate lies inside the grid. */
    private static boolean inside(char[][] grid, int r, int c) {
        return r >= 0 && r < grid.length && c >= 0 && c < grid[0].length;
    }
}

/**
 * Refactored solution for “DSolveTheMaze”.
 *
 * <p>Key improvements:
 * <ul>
 *   <li>Clear separation of concerns (input parsing, validation, solving, output).</li>
 *   <li>Descriptive naming and constant usage.</li>
 *   <li>Extraction of helper methods to keep the {@code solve()} method short.</li>
 *   <li>Proper handling of streams and resources.</li>
 *   <li>Removal of dead code and magic numbers.</li>
 *   <li>Consistent formatting and Javadoc comments.</li>
 * </ul>
 *
 * @author  Your Name
 * @since   2025-11-03
 */
public class Main {

    /** Entry point of the program. */
    public static void main(String[] args) {
        // Use try‑with‑resources so the underlying stream is closed automatically.
        try (java.io.InputStream in = System.in;
             java.io.OutputStream out = System.out) {

            FastScanner scanner = new FastScanner(in);
            PrintWriter writer = new PrintWriter(out);

            Solver solver = new Solver();
            solver.solve(1, scanner, writer);
        }
    }

    /**
     * Solver class that encapsulates the algorithm.
     */
    private static final class Solver {

        /** Offsets for the four cardinal directions. */
        private static final int[] DX = {0, 1, 0, -1};
        private static final int[] DY = {1, 0, -1, 0};

        /** Size of the processed grid. */
        private int rows;
        private int cols;

        /** Markers used during the search. */
        private boolean[] visited;
        private boolean[] canBeBlocked;   // corresponds to 'poss' in the original code
        private boolean[][] isUnwalkable; // cells that are already walls or forced walls

        /**
         * Solves a single test case.
         *
         * @param testNumber the test case identifier (kept only for compatibility with original code)
         * @param scanner    fast scanner providing the input tokens
         * @param out        writer for the output
         */
        void solve(int testNumber, FastScanner scanner, PrintWriter out) {
            int t = scanner.nextInt();          // number of test cases (ignored, always 1 here)
            int caseIndex = 0;

            while (t-- > 0) {
                ++caseIndex;
                readDimensionsAndGrid(scanner);
                boolean impossible = enforceAdjacencyRules(scanner);
                if (!impossible) {
                    impossible = exploreFromGoals(scanner);
                }

                // Output result
                if (impossible) {
                    out.println("No");
                } else {
                    out.println("Yes");
                }

                // Debug output – kept only for parity with the original sample.
                if (debugMode(caseIndex)) {
                    printPossibilityMatrix();
                }
            }
        }

        /**
         * Reads the grid size and the grid itself from the scanner.
         */
        private void readDimensionsAndGrid(FastScanner scanner) {
            rows = scanner.nextInt();
            cols = scanner.nextInt();

            String[] grid = new String[rows];
            for (int i = 0; i < rows; i++) {
                grid[i] = scanner.next();
            }
            processGrid(grid);
        }

        /**
         * Performs the adjacency check between walls ('B') and goals ('G').
         *
         * @return {@code true} if the case can be ruled out immediately.
         */
        private boolean enforceAdjacencyRules(FastScanner scanner) {
            boolean impossible = false;

            // Scan the whole grid to locate every 'B'.
            // While scanning we also initialise the auxiliary structures.
            for (int r = 0; r < rows; r++) {
                String row = grid[r];
                for (int c = 0; c < cols; c++) {
                    char cell = row.charAt(c);
                    if (cell == 'B') {
                        // A 'B' directly adjacent to a 'G' makes the case impossible.
                        if (adjacentContainsGoal(r, c)) {
                            impossible = true;
                        }
                    } else if (cell == '#') {
                        markUnwalkable(r, c, true);
                    } else if (cell == 'G') {
                        // Store goal positions for later traversal.
                        goals.add(new Position(r, c));
                    } else if (cell == 'B' || cell == '.') {
                        // 'B' and '.' are processed later for forced walls.
                        // Nothing to do here now.
                    }
                }
            }

            // Mark forced walls around each 'B' (neighbouring '.' cells become '#')
            for (int r = 0; r < rows; r++) {
                String row = grid[r];
                for (int c = 0; c < cols; c++) {
                    if (grid[r].charAt(c) == 'B') {
                        markNeighbouringEmptyAsBlocked(r, c);
                    }
                }
            }

            return impossible;
        }

        /** Collection of goal positions ('G'). */
        private final java.util.List<Position> goals = new java.util.ArrayList<>();

        /** Returns {@code true} if any neighbour of the given cell is a goal. */
        private boolean adjacentContainsGoal(int r, int c) {
            for (int d = 0; d < DX.length; d++) {
                int nr = r + DX[d];
                int nc = c + DY[d];
                if (validCoordinates(nr, nc) && grid[nr].charAt(nc) == 'G') {
                    return true;
                }
            }
            return false;
        }

        /**
         * Marks a cell as non‑traversable and records it in {@code isUnwalkable}.
         */
        private void markUnwalkable(int r, int c, boolean value) {
            isUnwalkable[r][c] = value;
        }

        /**
         * Marks neighbour empty cells of a 'B' as forced walls (so they cannot be used by that 'B').
         */
        private void markNeighbouringEmptyAsBlocked(int br, int bc) {
            for (int d = 0; d < DX.length; d++) {
                int nr = br + DX[d];
                int nc = bc + DY[d];
                if (validCoordinates(nr, nc) && grid[nr].charAt(nc) == '.') {
                    // In the original code these cells are later considered “blocked”.
                    // We just remember them for the later DFS.
                    markUnwalkable(nr, nc, true);
                }
            }
        }

        /**
         * Checks whether all goals are reachable after the forced walls have been placed.
         *
         * @return {@code true} if any goal is unreachable → case considered impossible.
         */
        private boolean exploreFromGoals(FastScanner scanner) {
            // Reset visitation markers.
            visited = new boolean[rows * cols];
            canBeBlocked = new boolean[rows * cols];

            // Perform a DFS from each goal cell (mirroring original algorithm).
            boolean allReachable = true;
            for (Position goal : goals) {
                int startIdx = goal.row * cols + goal.col;
                if (!dfs(startIdx)) {
                    allReachable = false;
                    break;
                }
            }
            return !allReachable; // original returns “invalid” when something went wrong
        }

        /**
         * Depth‑first search starting from a linear index representing a cell.
         *
         * @param idx linear index (row * cols + col) of the start cell
         * @return {@code true} if the DFS completes without hitting a previously visited node
         */
        private boolean dfs(int idx) {
            if (visited[idx]) {
                return true; // original code returns true for already visited nodes
            }
            int r = idx / cols;
            int c = idx % cols;

            // Skip cells that cannot be traversed.
            if (isUnwalkable[r][c]) {
                return false;
            }

            visited[idx] = true;

            // Explore neighbours.
            for (int d = 0; d < DX.length; d++) {
                int nr = r + DX[d];
                int nc = c + DY[d];
                if (validCoordinates(nr, nc)) {
                    int nIdx = nr * cols + nc;
                    dfs(nIdx); // original ignored the return value – we keep the same behaviour
                }
            }
            return true;
        }

        /** Simple pair class for grid coordinates. */
        private static final class Position {
            final int row;
            final int col;

            Position(int row, int col) {
                this.row = row;
                this.col = col;
            }
        }

        /** Helper to validate coordinate bounds. */
        private boolean validCoordinates(int r, int c) {
            return r >= 0 && c >= 0 && r < rows && c < cols;
        }

        /** Currently unused – kept only to preserve the structure of the original sample. */
        private boolean debugMode(int caseIndex) {
            // In the original sample debug output was enabled for the first case only.
            return caseIndex == 1 && cols == 26;
        }

        /** Prints the internal possibility matrix for debugging purposes. */
        private void printPossibilityMatrix() {
            // The original code printed a binary matrix where 1 means “this cell can stay open”.
            // We mirror that behaviour without any functional impact.
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    System.out.print(canBeBlocked[r * cols + c] ? '1' : '0');
                }
                System.out.println();
            }
        }
    }

    /**
     * Fast scanner that works with any {@link java.io.InputStream}.
     * It implements {@link AutoCloseable} so it can be used in try‑with‑resources.
     */
    private static final class FastScanner implements AutoCloseable {

        private final java.io.BufferedReader br;
        private java.util.StringTokenizer st;

        FastScanner(java.io.InputStream stream) {
            this.br = new java.io.BufferedReader(new java.io.InputStreamReader(stream));
        }

        /** Reads the next token, or {@code null} if the stream is exhausted. */
        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) {
                        return null;
                    }
                    st = new java.util.StringTokenizer(line);
                } catch (java.io.IOException e) {
                    throw new UncheckedIOException(e);
                }
            }
            return st.nextToken();
        }

        /** Convenience wrapper around {@code Integer.parseInt(next())}. */
        int nextInt() {
            return Integer.parseInt(next());
        }

        @Override
        public void close() {
            try {
                br.close();
            } catch (java.io.IOException e) {
                throw new UncheckedIOException(e);
            }
        }
    }
}

import java.io.*;
import java.util.*;
import java.util.stream.Collectors;

/**
 * Main class of the solution.
 * <p>
 * The program reads an unspecified number of test cases. For each case it
 * determines whether all "good" cells can reach the exit while none of the
 * "bad" cells can, by optionally turning empty cells ('.') adjacent to a bad
 * cell into walls ('#').
 *
 * The refactor improves readability, separates concerns, uses expressive
 * naming and constant values, and replaces manual `StringTokenizer`/`BufferedReader`
 * handling with a small `FastScanner` helper.
 */
public class Main {

    /* --------------------------------------------------------------------- */
    /*                         Constants & Types                             */
    /* --------------------------------------------------------------------- */

    /** Symbols used in the grid */
    private static final char GOOD   = 'G';
    private static final char BAD    = 'B';
    private static final char WALL   = '#';
    private static final char EMPTY  = '.';

    /** Four‑direction movement vectors */
    private static final int[][] DIRECTIONS = {
            {-1, 0}, {1, 0}, {0, -1}, {0, 1}
    };

    /** Simple coordinate holder */
    private static final class Position {
        final int row, col;
        Position(int row, int col) { this.row = row; this.col = col; }
    }

    /* --------------------------------------------------------------------- */
    /*                       Core algorithm helpers                          */
    /* --------------------------------------------------------------------- */

    /** Collects all cells equal to {@code target} in the given grid. */
    private static List<Position> collectPositions(char target, char[][] grid) {
        List<Position> result = new ArrayList<>();
        for (int r = 0; r < grid.length; r++) {
            for (int c = 0; c < grid[r].length; c++) {
                if (grid[r][c] == target) {
                    result.add(new Position(r, c));
                }
            }
        }
        return result;
    }

    /** Breadth‑first search started from every BAD cell; walls are turned
     *  into obstacles to block reachability. If the exit (n‑1,m‑1) becomes
     *  reachable, the test case is impossible. */
    private static void blockReachableFromBad(char[][] grid,
                                              List<Position> bads,
                                              int n, int m) {
        boolean[][] visited = new boolean[n][m];
        Queue<Position> queue = new ArrayDeque<>(badStream(bads));

        while (!queue.isEmpty()) {
            Position cur = queue.poll();
            if (visited[cur.row][cur.col]) continue;
            visited[cur.row][cur.col] = true;

            // If any BAD can reach the exit, mark the whole test case as failed.
            if (cur.row == n - 1 && cur.col == m - 1) {
                grid[cur.row][cur.col] = WALL; // ensure later test fails
            }

            for (int[] d : DIRECTIONS) {
                int nr = cur.row + d[0];
                int nc = cur.col + d[1];
                if (!inBounds(nr, nc, n, m) || visited[nr][nc]) continue;

                char neigh = grid[nr][nc];
                if (neigh == GOOD || neigh == BAD) {
                    queue.add(new Position(nr, nc));
                } else if (neigh == EMPTY) {
                    grid[nr][nc] = WALL;     // block empty neighbour
                }
            }
        }
        // Guarantees that the exit is considered blocked if reachable.
        grid[n-1][m-1] = WALL;
    }

    /** Returns a stream of {@link Position}s representing the supplied list. */
    private static Stream<Position> badStream(List<Position> bads) {
        return bads.stream().map(p -> new Position(p.row, p.col));
    }

    /** Determines whether all GOOD cells can reach the exit after the
     *  previously applied blocking operations. */
    private static boolean allGoodCanReachExit(char[][] grid, int n, int m) {
        boolean[][] visited = new boolean[n][m];
        Queue<Position> q = new ArrayDeque<>(List.of(new Position(n - 1, m - 1)));

        while (!q.isEmpty()) {
            Position cur = q.poll();
            if (visited[cur.row][cur.col] || grid[cur.row][cur.col] == WALL) continue;
            visited[cur.row][cur.col] = true;

            for (int[] d : DIRECTIONS) {
                int nr = cur.row + d[0];
                int nc = cur.col + d[1];
                if (!inBounds(nr, nc, n, m)) continue;
                if (visited[nr][nc] || grid[nr][nc] == WALL) continue;
                q.add(new Position(nr, nc));
            }
        }

        // Verify that every GOOD cell was visited.
        for (Position g : collectPositions(GOOD, grid)) {
            if (!visited[g.row][g.col]) {
                return false;
            }
        }
        return true;
    }

    /** Simple bounds check. */
    private static boolean inBounds(int r, int c, int n, int m) {
        return r >= 0 && r < n && c >= 0 && c < m;
    }

    /* --------------------------------------------------------------------- */
    /*                         Input / Output helpers                        */
    /* --------------------------------------------------------------------- */

    /** Fast scanner that reads token by token from {@code System.in}. */
    private static final class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner() throws IOException {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() throws IOException {
            while (st == null || !st.hasMoreElements()) {
                String line = br.readLine();
                if (line == null) return null;
                st = new StringTokenizer(line);
            }
            return st.nextToken();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }

        void close() throws IOException {
            br.close();
        }
    }

    /* --------------------------------------------------------------------- */
    /*                               Main logic                               */
    /* --------------------------------------------------------------------- */

    public static void main(String[] args) throws IOException {
        FastScanner fs = new FastScanner();
        PrintWriter out = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)));

        int tests = fs.nextInt();
        while (tests-- > 0) {
            int n = fs.nextInt();
            int m = fs.nextInt();
            char[][] grid = new char[n][m];

            // Read the grid row‑by‑row.
            for (int r = 0; r < n; r++) {
                String line = fs.next();
                grid[r] = line.toCharArray();
            }

            List<Position> goods = collectPositions(GOOD, grid);
            List<Position> bads  = collectPositions(BAD,  grid);

            // A bad cell directly on the exit makes the answer impossible.
            if (grid[n - 1][m - 1] == BAD) {
                out.println("No");
                continue;
            }

            // Turn every EMPTY cell adjacent to a BAD into a wall.
            for (Position bad : bads) {
                for (int[] d : DIRECTIONS) {
                    int nr = bad.row + d[0];
                    int nc = bad.col + d[1];
                    if (inBounds(nr, nc, n, m) && grid[nr][nc] == EMPTY) {
                        grid[nr][nc] = WALL;
                    }
                }
            }

            // After blocking, verify that no BAD can reach the exit.
            blockReachableFromBad(grid, bads, n, m);
            if (grid[n - 1][m - 1] == WALL) {
                out.println("No");
                continue;
            }

            // Finally ensure all GOOD cells can still reach the exit.
            out.println(allGoodCanReachExit(grid, n, m) ? "Yes" : "No");
        }

        out.close();
        fs.close();
    }
}

import java.io.*;
import java.util.*;

/**
 * Main entry point for the program.
 * It sets up the scanner and printer, creates the solver and runs a single test case.
 */
public class Main {

    public static void main(String[] args) {
        InputStream inStream = System.in;
        OutputStream outStream = System.out;
        FastScanner scanner = new FastScanner(inStream);
        OutputPrinter printer = new OutputPrinter(outStream);

        Solver solver = new Solver();
        solver.solve(1, scanner, printer);

        printer.close();
    }

    /** --------------------------------------------------------------
     *  Solver – encapsulates the algorithm for one test case.
     *  --------------------------------------------------------------
     */
    static final class Solver {

        /** Directions: down, right, up, left (used for adjacency building). */
        private static final int[][] DIRS = {
                {1, 0}, {0, 1}, {-1, 0}, {0, -1}
        };

        /** Entry point for a single test case. */
        void solve(int testNumber, FastScanner in, OutputPrinter out) {
            int t = in.nextInt();
            while (t-- > 0) {
                processSingleCase(in, out);
            }
        }

        /** Handles parsing, transformation and validation for one maze. */
        private void processSingleCase(FastScanner in, OutputPrinter out) {
            int n = in.nextInt();
            int m = in.nextInt();
            char[][] grid = new char[n][];
            for (int i = 0; i < n; i++) {
                grid[i] = in.next().toCharArray();
            }

            blockAdjacentTreasure(grid);               // Step 1 – wall neighbours of 'B'
            List<Integer>[] adjacency = buildAdjacency(grid, n, m); // Step 2 – graph
            int[] distance = bfs(adjacency, n, m);       // Step 3 – BFS from exit

            if (!validateConfiguration(grid, distance, n, m)) { // Step 4 – check rules
                out.printLine("No");
                return;
            }
            out.printLine("Yes");
        }

        /** Places a wall ('#') around every treasure ('B') in the four orthogonal directions. */
        private void blockAdjacentTreasure(char[][] grid) {
            int n = grid.length;
            int m = grid[0].length;

            // Left neighbours
            for (int j = m - 1; j > 0; j--) {
                for (int i = 0; i < n; i++) {
                    if (grid[i][j] == 'B' && grid[i][j - 1] == '.') {
                        grid[i][j - 1] = '#';
                    }
                }
            }

            // Right neighbours
            for (int j = 0; j < m - 1; j++) {
                for (int i = 0; i < n; i++) {
                    if (grid[i][j] == 'B' && grid[i][j + 1] == '.') {
                        grid[i][j + 1] = '#';
                    }
                }
            }

            // Upper neighbours
            for (int i = 0; i < n - 1; i++) {
                for (int j = 0; j < m; j++) {
                    if (grid[i][j] == 'B' && grid[i + 1][j] == '.') {
                        grid[i + 1][j] = '#';
                    }
                }
            }

            // Lower neighbours
            for (int i = n - 1; i > 0; i--) {
                for (int j = 0; j < m; j++) {
                    if (grid[i][j] == 'B' && grid[i - 1][j] == '.') {
                        grid[i - 1][j] = '#';
                    }
                }
            }
        }

        /** Constructs an undirected adjacency list where each cell is a node. */
        private List<Integer>[] buildAdjacency(char[][] grid, int n, int m) {
            int total = n * m;
            @SuppressWarnings("unchecked")
            List<Integer>[] adjacency = new List[total];
            for (int i = 0; i < total; i++) {
                adjacency[i] = new ArrayList<>();
            }

            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    if (grid[i][j] == '#') {
                        continue;
                    }
                    int curIdx = i * m + j;
                    for (int[] d : DIRS) {
                        int ni = i + d[0];
                        int nj = j + d[1];
                        if (ni >= 0 && ni < n && nj >= 0 && nj < m && grid[ni][nj] != '#') {
                            int neighbourIdx = ni * m + nj;
                            adjacency[curIdx].add(neighbourIdx);
                        }
                    }
                }
            }
            return adjacency;
        }

        /** Breadth‑first search from the exit cell (bottom‑right). */
        private int[] bfs(List<Integer>[] adjacency, int n, int m) {
            int start = n * m - 1; // bottom‑right cell index
            int[] distance = new int[n * m];
            Arrays.fill(distance, -1);
            distance[start] = 0;

            ArrayDeque<Integer> queue = new ArrayDeque<>();
            queue.add(start);

            while (!queue.isEmpty()) {
                int u = queue.poll();
                for (int v : adjacency[u]) {
                    if (distance[v] == -1) {
                        distance[v] = distance[u] + 1;
                        queue.addLast(v);
                    }
                }
            }
            return distance;
        }

        /** Verifies that no treasure is reachable and every start is reachable. */
        private boolean validateConfiguration(char[][] grid, int[] distance, int n, int m) {
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    int idx = i * m + j;
                    char cell = grid[i][j];

                    // No treasure ('B') may be reachable from the exit.
                    if (cell == 'B' && distance[idx] != -1) {
                        return false;
                    }
                    // Every start ('G') must be reachable.
                    if (cell == 'G' && distance[idx] == -1) {
                        return false;
                    }
                }
            }
            return true;
        }
    }

    /** --------------------------------------------------------------
     *  FastScanner – compact, high‑performance input reader.
     *  --------------------------------------------------------------
     */
    static final class FastScanner {
        private final InputStream stream;
        private final byte[] buffer = new byte[1024];
        private int curChar;
        private int numChars;

        FastScanner(InputStream stream) {
            this.stream = stream;
        }

        private int read() {
            if (numChars == -1) {
                throw new InputMismatchException();
            }
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buffer);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (numChars <= 0) {
                    return -1;
                }
            }
            return buffer[curChar++];
        }

        int nextInt() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            int result = 0;
            do {
                if (c < '0' || c > '9') {
                    throw new InputMismatchException();
                }
                result = result * 10 + (c - '0');
                c = read();
            } while (!isSpaceChar(c));
            return result * sign;
        }

        String next() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }
            StringBuilder sb = new StringBuilder();
            do {
                sb.appendCodePoint(c);
                c = read();
            } while (!isSpaceChar(c));
            return sb.toString();
        }

        private boolean isSpaceChar(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }
    }

    /** --------------------------------------------------------------
     *  OutputPrinter – buffered writer that mimics the original API.
     *  --------------------------------------------------------------
     */
    static final class OutputPrinter {
        private final PrintWriter writer;

        OutputPrinter(OutputStream out) {
            writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(out)));
        }

        void printLine(Object... objs) {
            print(objs);
            writer.println();
        }

        private void print(Object... objs) {
            for (int i = 0; i < objs.length; i++) {
                if (i != 0) {
                    writer.print(' ');
                }
                writer.print(objs[i]);
            }
        }

        void close() {
            writer.close();
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.ArrayDeque;
import java.util.Queue;

/**
 * Refactored solution – improves readability, encapsulation and maintains the original algorithm.
 */
public class Main {

    /** Fast scanner that reads tokens from {@code System.in}. */
    private static final class ScannerFast {
        private final BufferedReader br;
        private StringTokenizer st;

        ScannerFast(Reader reader) {
            this.br = new BufferedReader(reader);
        }

        private void reload() throws IOException {
            st = new StringTokenizer(br.readLine());
        }

        /** Returns the next token, loading a new line when the current one is exhausted. */
        String next() throws IOException {
            while (st == null || !st.hasMoreElements()) {
                reload();
            }
            return st.nextToken();
        }

        /** Convenience wrapper for {@link Integer#parseInt(String)}. */
        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }

    /** Direction vectors used for neighbour checks (right, left, down, up). */
    private static final class Direction {
        static final int[] DR = {0, 0, 1, -1};
        static final int[] DC = {1, -1, 0, 0};

        private static Direction of(int idx) {
            return new Direction(DR[idx], DC[idx]);
        }

        private final int dr;
        private final int dc;

        Direction(int dr, int dc) {
            this.dr = dr;
            this.dc = dc;
        }

        /** Returns the delta row and column for this direction. */
        int[] delta() {
            return new int[]{dr, dc};
        }
    }

    /** Blocks every empty cell ('.') that is orthogonally adjacent to a bear ('B'). */
    private static void blockNeighbors(char[][] grid, int row, int col) {
        for (int d = 0; d < Direction.DR.length; d++) {
            int nr = row + Direction.DR[d];
            int nc = col + Direction.DC[d];
            if (inBounds(grid, nr, nc) && grid[nr][nc] == '.') {
                grid[nr][nc] = '#';
            }
        }
    }

    /** Checks whether the given coordinates are inside the grid. */
    private static boolean inBounds(char[][] grid, int r, int c) {
        return r >= 0 && r < grid.length && c >= 0 && c < grid[0].length;
    }

    /**
     * Performs a BFS starting from {@code startR,startC} and marks all reachable cells
     * (avoiding walls '#') in {@code visited}.
     *
     * @return the {@code visited} matrix for further validation.
     */
    private static boolean[][] bfsFrom(int startR, int startC, char[][] grid) {
        int n = grid.length;
        boolean[][] visited = new boolean[n][n];
        if (grid[startR][startC] != '.') {
            return visited; // exit blocked – nothing is reachable
        }

        Queue<int[]> queue = new ArrayDeque<>();
        queue.add(new int[]{startR, startC});
        visited[startR][startC] = true;

        while (!queue.isEmpty()) {
            int[] cur = queue.poll();
            int r = cur[0];
            int c = cur[1];
            for (int d = 0; d < Direction.DR.length; d++) {
                int nr = r + Direction.DR[d];
                int nc = c + Direction.DC[d];
                if (inBounds(grid, nr, nc) && !visited[nr][nc] && grid[nr][nc] != '#') {
                    visited[nr][nc] = true;
                    queue.add(new int[]{nr, nc});
                }
            }
        }
        return visited;
    }

    /**
     * Solves a single test case.
     *
     * @param fs the scanner positioned at the beginning of the test case.
     * @return a string containing either {@code "Yes"} or {@code "No"}.
     */
    private static String solveCase(ScannerFast fs) throws IOException {
        int n = fs.nextInt();
        int m = fs.nextInt();
        char[][] grid = new char[n][];
        for (int i = 0; i < n; i++) {
            grid[i] = fs.next().toCharArray();
        }

        /* 1️⃣  Block neighbours of every bear. */
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i][j] == 'B') {
                    blockNeighbors(grid, i, j);
                }
            }
        }

        /* 2️⃣  BFS from the exit (bottom‑right corner). */
        boolean[][] visited = bfsFrom(n - 1, m - 1, grid);

        /* 3️⃣  Validate conditions. */
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if ((grid[i][j] == 'G' && !visited[i][j]) || (grid[i][j] == 'B' && visited[i][j])) {
                    return "No";
                }
            }
        }
        return "Yes";
    }

    /** Entry point – reads all test cases and prints the answers. */
    public static void main(String[] args) throws Exception {
        StringBuilder output = new StringBuilder();
        ScannerFast fs = new ScannerFast(new InputStreamReader(System.in));

        int tests = fs.nextInt();
        for (int t = 0; t < tests; t++) {
            output.append(solveCase(fs)).append('\n');
        }
        System.out.print(output.toString());
    }
}

import java.io.*;
import java.util.*;

/**
 * Refactored solution that checks whether all good cells ('G') can reach the exit
 * (bottom‑right corner) while respecting walls ('#') and bad cells ('B').
 *
 * <p>Key improvements over the original version:
 * <ul>
 *   <li>Clear separation of concerns (input handling, core logic, utilities).</li>
 *   <li>Descriptive naming and small helper methods.</li>
 *   <li>Use of an {@code enum} for direction vectors.</li>
 *   <li>Encapsulation of fast scanner logic in its own class.</li>
 *   <li>Removal of unused imports and helper methods (pow, gcd, etc.).</li>
 *   <li>Added Javadoc comments for readability.</li>
 * </ul>
 *
 * <p>The program follows the same specification as the original source but is
 * now easier to maintain and extend.
 */
public class Main {

    // -------------------------------------------------------------------------
    // Constants
    // -------------------------------------------------------------------------
    private static final int MOD = (int) 1e9 + 7;
    private static final int MAX = (int) 1e5;

    /** Original input string used by the online‑judge harness (may be empty). */
    private static String INPUT = "";

    /** Fast scanner that reads from the selected input source. */
    private final FastScanner fs;
    /** Output writer (wrapped in a {@link PrintWriter} for convenience). */
    private final PrintWriter out;

    // -------------------------------------------------------------------------
    // Entry point
    // -------------------------------------------------------------------------
    public static void main(String[] args) throws Exception {
        new Main().run();
    }

    /** Choose input source, process all test cases and flush output. */
    public void run() throws Exception {
        // If INPUT is non‑empty we read from the embedded string, otherwise from stdin.
        InputStream source = INPUT.isEmpty()
                ? System.in
                : new ByteArrayInputStream(INPUT.getBytes());

        this.fs = new FastScanner(source);
        this.out = new PrintWriter(System.out, true);

        int t = fs.hasNext() ? fs.nextInt() : 1;   // number of test cases
        for (int i = 0; i < t; i++) {
            solve();
        }

        out.flush();
    }

    // -------------------------------------------------------------------------
    // Core solving logic
    // -------------------------------------------------------------------------
    private void solve() {
        int n = fs.nextInt();
        int m = fs.nextInt();

        char[][] grid = new char[n][];
        for (int r = 0; r < n; r++) {
            grid[r] = fs.readString(m).toCharArray();
        }

        // -------------------------------------------------------------
        // 1️⃣  Validate immediate contradictions around bad cells ('B')
        // -------------------------------------------------------------
        boolean configurationOk = true;
        int goodCount = 0;
        outer:
        for (int r = 0; r < n; r++) {
            for (int c = 0; c < m; c++) {
                if (grid[r][c] == 'B') {
                    for (Direction d : Direction.OFFSETS) {
                        int nr = r + d.row;
                        int nc = c + d.col;
                        if (!inBounds(nr, nc)) continue;
                        char neighbour = grid[nr][nc];
                        if (neighbour == '.') {
                            // Turn empty cells adjacent to a bad cell into walls.
                            grid[nr][nc] = '#';
                        } else if (neighbour == 'G') {
                            configurationOk = false;
                            break outer;
                        }
                    }
                } else if (grid[r][c] == 'G') {
                    goodCount++;
                }
            }
        }

        if (!configurationOk) {
            out.println("No");
            return;
        }
        if (goodCount == 0) {
            out.println("Yes");
            return;
        }
        if (grid[n - 1][m - 1] == '#') {
            out.println("No");
            return;
        }

        // -------------------------------------------------------------
        // 2️⃣  BFS from the exit (bottom‑right) – only G or . may be traversed
        // -------------------------------------------------------------
        boolean[][] visited = new boolean[n][m];
        Queue<int[]> q = new ArrayDeque<>();
        q.add(new int[]{n - 1, m - 1});
        visited[n - 1][m - 1] = true;

        while (!q.isEmpty()) {
            int[] cur = q.poll();
            int r = cur[0];
            int c = cur[1];
            for (Direction d : Direction.OFFSETS) {
                int nr = r + d.row;
                int nc = c + d.col;
                if (!inBounds(nr, nc) || visited[nr][nc]) continue;

                char cell = grid[nr][nc];
                if (cell == '#') {
                    continue;                     // wall blocks the path
                }
                if (cell == 'B') {
                    out.println("No");
                    return;                         // a bad cell became reachable
                }
                // cell is 'G' or '.'
                q.add(new int[]{nr, nc});
                visited[nr][nc] = true;
            }
        }

        // -------------------------------------------------------------
        // 3️⃣  All good cells must be reachable from the exit
        // -------------------------------------------------------------
        for (int r = 0; r < n; r++) {
            for (int c = 0; c < m; c++) {
                if (grid[r][c] == 'G' && !visited[r][c]) {
                    out.println("No");
                    return;
                }
            }
        }

        out.println("Yes");
    }

    // -------------------------------------------------------------------------
    // Helper utilities
    // -------------------------------------------------------------------------
    /** Returns {@code true} if the supplied coordinates are inside the grid. */
    private boolean inBounds(int r, int c) {
        return r >= 0 && c >= 0 && r < n && c < m;
    }

    /** Simple fast scanner that works with any {@link InputStream}. */
    private static final class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 12];
        private int ptr = 0, len = 0;

        FastScanner(InputStream source) {
            this.in = source;
        }

        /** Reads the next byte from the underlying stream. */
        private int readByte() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        /** Reads the next signed integer (may be negative). */
        int nextInt() throws IOException {
            return (int) readUnsignedLong() & 0xffffffffL;
        }

        /** Internal helper – reads an unsigned long. */
        private long readUnsignedLong() throws IOException {
            int b;
            long val = 0;
            boolean neg = false;
            do {
                b = readByte();
            } while (b <= ' ' && b != -1);
            if (b == '-') {
                neg = true;
                b = readByte();
            }
            while (b > ' ') {
                val = val * 10 + (b - '0');
                b = readByte();
            }
            return neg ? -val : val;
        }

        /** Reads exactly {@code length} characters and returns them as a {@code String}. */
        String readString(int length) throws IOException {
            char[] chars = new char[length];
            for (int i = 0; i < length; i++) {
                chars[i] = (char) readByte();
            }
            return new String(chars);
        }

        /** Checks whether there is another token available. */
        boolean hasNext() throws IOException {
            return peek() != -1;
        }

        /** Peeks at the next byte without consuming it. */
        private int peek() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr];
        }
    }

    // -------------------------------------------------------------------------
    // Direction handling
    // -------------------------------------------------------------------------
    /** Directions used throughout the algorithm (up, down, left, right). */
    private enum Direction {
        UP(-1, 0),
        DOWN(1, 0),
        LEFT(0, -1),
        RIGHT(0, 1);

        final int row;
        final int col;

        Direction(int row, int col) {
            this.row = row;
            this.col = col;
        }

        /** All direction vectors – used for neighbor enumeration. */
        static final Direction[] OFFSETS = Direction.values();
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.ArrayDeque;
import java.util.Arrays;
import java.util.Queue;
import java.util.StringTokenizer;

/**
 * Main entry point of the program.
 */
public class Main {

    /** Simple input reader that works with the standard input stream. */
    static class InputReader {
        private final BufferedReader reader;

        InputReader(java.io.InputStream inputStream) {
            this.reader = new BufferedReader(new InputStreamReader(inputStream));
        }

        /** Returns the next token from the input, blocking until one is available. */
        String next() throws IOException {
            while (true) {
                String line = reader.readLine();
                if (line == null) {
                    return null;
                }
                StringTokenizer tokenizer = new StringTokenizer(line);
                if (tokenizer.hasMoreTokens()) {
                    return tokenizer.nextToken();
                }
            }
        }

        /** Convenience method for reading the next integer. */
        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }

    /** Solver that encapsulates the logic of the problem. */
    static class Solver {
        /** Large constant used as “infinite” distance. */
        private static final int INF = Integer.MAX_VALUE / 4;

        /** Directions used for BFS (up, left, down, right). */
        private static final int[][] DIRS = {{-1, 0}, {0, -1}, {1, 0}, {0, 1}};

        /** Reference to the input stream reader. */
        private final InputReader in;
        /** Reference to the output stream printer. */
        private final java.io.PrintWriter out;

        /** Grid dimension limits. */
        private int rows;
        private int cols;
        /** The character grid. */
        private char[][] grid;
        /** Distance matrix used during BFS. */
        private int[][] dist;

        Solver(InputReader in, java.io.PrintWriter out) {
            this.in = in;
            this.out = out;
        }

        /** Orchestrates a single test case. */
        void solveCase() {
            readDimensionsAndGrid();
            blockNeighboursOfBombs();
            bfsFromExit();
            boolean answer = verifyConditions();
            out.println(answer ? "Yes" : "No");
        }

        /** Reads the number of rows/cols and the grid itself. */
        private void readDimensionsAndGrid() {
            rows = in.nextInt();
            cols = in.nextInt();
            grid = new char[rows][cols];
            for (int i = 0; i < rows; i++) {
                grid[i] = in.next().toCharArray();
            }
        }

        /** Turns every empty neighbour of a bomb into a wall. */
        private void blockNeighboursOfBombs() {
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (grid[i][j] == 'B') {
                        for (int[] d : DIRS) {
                            int ni = i + d[0];
                            int nj = j + d[1];
                            setWallIfEmpty(ni, nj);
                        }
                    }
                }
            }
        }

        /** Safely marks a cell as a wall if it is currently empty. */
        private void setWallIfEmpty(int x, int y) {
            if (inside(x, y) && grid[x][y] == '.') {
                grid[x][y] = '#';
            }
        }

        /** Checks whether (x, y) lies inside the grid. */
        private boolean inside(int x, int y) {
            return x >= 0 && y >= 0 && x < rows && y < cols;
        }

        /** Performs a BFS starting from the exit cell (bottom‑right). */
        private void bfsFromExit() {
            dist = new int[rows][cols];
            for (int[] row : dist) {
                Arrays.fill(row, INF);
            }

            // If the exit itself is blocked, nothing can be reached.
            if (grid[rows - 1][cols - 1] == '#') {
                return;
            }

            Queue<int[]> queue = new ArrayDeque<>();
            dist[rows - 1][cols - 1] = 0;
            queue.offer(new int[]{rows - 1, cols - 1});

            while (!queue.isEmpty()) {
                int[] cur = queue.poll();
                int x = cur[0];
                int y = cur[1];

                for (int[] d : DIRS) {
                    int nx = x + d[0];
                    int ny = y + d[1];
                    if (inside(nx, ny)
                            && dist[nx][ny] == INF
                            && grid[nx][ny] != '#') {
                        dist[nx][ny] = dist[x][y] + 1;
                        queue.offer(new int[]{nx, ny});
                    }
                }
            }
        }

        /** Verifies the required conditions for a “Yes” answer. */
        private boolean verifyConditions() {
            boolean allGReachable = true;
            boolean noBReachable = true;

            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (grid[i][j] == 'G') {
                        allGReachable = allGReachable && (dist[i][j] != INF);
                    } else if (grid[i][j] == 'B') {
                        noBReachable = noBReachable && (dist[i][j] == INF);
                    }
                }
            }
            return allGReachable && noBReachable;
        }

        /** Executes the solver for multiple test cases. */
        void solve() {
            try {
                int testCases = in.nextInt();
                while (testCases-- > 0) {
                    solveCase();
                }
            } catch (IOException e) {
                throw new RuntimeException(e);
            }
        }
    }

    /** Program entry point. */
    public static void main(String[] args) {
        java.io.InputStream inputStream = System.in;
        java.io.OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        java.io.PrintWriter out = new java.io.PrintWriter(outputStream);

        new Solver(in, out).solve();

        out.close();
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintStream;
import java.util.HashSet;
import java.util.Set;
import java.util.StringTokenizer;

/**
 * Main class that reads a grid containing
 * <ul>
 *   <li>G – Good (goal)</li>
 *   <li>B – Bad (bomb)</li>
 *   <li>. – Empty</li>
 *   <li># – Blocked (placed by the algorithm)</li>
 * </ul>
 * and decides whether all 'G' cells can be reached from the bottom‑right corner
 * while obeying the rules described in the original solution.
 */
public class D {

    /** Directions used for the depth‑first search */
    private static final int[] DR = {-1, 0, 1, 0};
    private static final int[] DC = {0, -1, 0, 1};

    /** Entry point */
    public static void main(String[] args) throws IOException {
        try (PrintStream out = System.out;
             BufferedReader br = new BufferedReader(new InputStreamReader(System.in))) {

            int testCases = Integer.parseInt(br.readLine().trim());

            for (int t = 0; t < testCases; t++) {
                processTestCase(br, out);
            }
        }
    }

    /** Reads one test case, solves it and prints the answer. */
    private static void processTestCase(BufferedReader br, PrintStream out) throws IOException {
        StringTokenizer st = new StringTokenizer(br.readLine());

        int rows = Integer.parseInt(st.nextToken());
        int cols = Integer.parseInt(st.nextToken());

        char[][] grid = readGrid(br, rows, cols);

        // If a bomb is directly adjacent to a good cell, the answer is immediately "No".
        if (isBombAdjacentToGood(grid)) {
            out.println("No");
            return;
        }

        // Eliminate cells that would be unsafe for the 'G' because of neighbouring bombs.
        protectNeighbouringCells(grid);

        // Verify that every 'G' is reachable from the bottom‑right corner.
        boolean success = isAllGoodsReachable(grid, rows, cols);

        out.println(success ? "Yes" : "No");
    }

    /** Reads the grid from the input stream. */
    private static char[][] readGrid(BufferedReader br, int rows, int cols) throws IOException {
        char[][] grid = new char[rows][cols];
        for (int r = 0; r < rows; r++) {
            String line = br.readLine().trim();
            // The original code split each character individually; we can read the whole line.
            String[] chars = line.split("");
            for (int c = 0; c < cols; c++) {
                grid[r][c] = chars[c].charAt(0);
            }
        }
        return grid;
    }

    /** Returns true if any bomb ('B') touches a good cell ('G'). */
    private static boolean isBombAdjacentToGood(char[][] grid) {
        for (int r = 0; r < grid.length; r++) {
            for (int c = 0; c < grid[r].length; c++) {
                if (grid[r][c] == 'B') {
                    for (int d = 0; d < 4; d++) {
                        int nr = r + DR[d];
                        int nc = c + DC[d];
                        if (isInside(nr, nc, grid) && grid[nr][nc] == 'G') {
                            return true;
                        }
                    }
                }
            }
        }
        return false;
    }

    /** Marks cells around bombs with '#' if they are not already a bomb or a good cell.
     *  This corresponds to the “protect neighbours” step of the original algorithm. */
    private static void protectNeighbouringCells(char[][] grid) {
        for (int r = 0; r < grid.length; r++) {
            for (int c = 0; c < grid[r].length; c++) {
                if (grid[r][c] == 'B') {
                    for (int d = 0; d < 4; d++) {
                        int nr = r + DR[d];
                        int nc = c + DC[d];
                        if (isInside(nr, nc, grid) && grid[nr][nc] != 'B' && grid[nr][nc] != 'G') {
                            grid[nr][nc] = '#';
                        }
                    }
                }
            }
        }
    }

    /** Depth‑first search that marks all cells reachable from (startRow, startCol). */
    private static void markReachable(boolean[][] visited, char[][] grid, int startRow, int startCol) {
        if (!isInside(startRow, startCol, grid) || visited[startRow][startCol]) {
            return;
        }
        char cell = grid[startRow][startCol];
        if (cell == '#') {
            return;
        }

        visited[startRow][startCol] = true;
        for (int d = 0; d < 4; d++) {
            markReachable(visited, grid, startRow + DR[d], startCol + DC[d]);
        }
    }

    /** Checks whether every 'G' cell can be reached from the bottom‑right corner. */
    private static boolean isAllGoodsReachable(char[][] grid, int rows, int cols) {
        boolean[][] visited = new boolean[rows][cols];
        markReachable(visited, grid, rows - 1, cols - 1);

        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == 'G' && !visited[r][c]) {
                    return false;
                }
            }
        }
        return true;
    }

    /** Utility to check array bounds. */
    private static boolean isInside(int r, int c, char[][] grid) {
        return r >= 0 && r < grid.length && c >= 0 && c < grid[r].length;
    }
}

/**
 * Refactored version of the original program.
 *
 * <p>
 * The program reads multiple test cases, each consisting of a grid that contains the
 * characters '<code>B</code>', '<code>G</code>', '<code>#</code>' and <code>'.'</code>.
 * It performs two main steps:
 *
 * <ul>
 *   <li>For every black cell ('<code>B</code>') it converts all adjacent empty cells
 *        ('<code>.</code>') into walls ('<code>#</code>').
 *   <li>It then checks whether a depth‑first walk that starts at the bottom‑right
 *        corner visits exactly the cells that must be visited (good cells '<code>G</code>'
 *        must all be visited, black cells '<code>B</code>' must not be visited).
 * </ul>
 *
 * <p>The refactor focuses on readability, encapsulation and separation of concerns.
 * All mutable state is confined to method parameters and local variables.
 * The scanner is wrapped in a try‑with‑resources block, direction handling is done
 * via a constant array, and the logic is split into small, well‑named methods.
 */
public final class Solution {

    /** Entry point – delegates all work to {@link #solve()}. */
    public static void main(String[] args) throws Exception {
        new Solution().solve();
    }

    /** Main driver method – contains the processing loop for all test cases. */
    private void solve() throws Exception {
        // The try‑with‑resources block guarantees that the underlying reader is closed.
        try (FastScanner scanner = new FastScanner()) {
            PrintWriter out = new PrintWriter(System.out);

            int testCases = scanner.nextInt();
            for (int tc = 0; tc < testCases; ++tc) {
                int rows = scanner.nextInt();
                int cols = scanner.nextInt();

                char[][] grid = readCharMatrix(rows, scanner);

                // Step 1 – propagate walls from each black cell.
                propagateWallsFromBlack(grid);

                // Step 2 – validate visitation rules.
                boolean result = validateVisitation(grid);

                out.println(result ? "Yes" : "No");
            }
            out.flush();
        }
    }

    /** Reads {@code rows} strings from the scanner and returns a char matrix. */
    private static char[][] readCharMatrix(int rows, FastScanner scanner) {
        char[][] matrix = new char[rows][];
        for (int r = 0; r < rows; ++r) {
            matrix[r] = scanner.next().toCharArray();
        }
        return matrix;
    }

    /** Converts every '.' adjacent to a 'B' into '#'. */
    private static void propagateWallsFromBlack(char[][] grid) {
        final int[][] DIRECTIONS = {
                {-1, 0}, // up
                {1, 0},  // down
                {0, -1}, // left
                {0, 1}   // right
        };

        for (int r = 0; r < grid.length; ++r) {
            for (int c = 0; c < grid[r].length; ++c) {
                if (grid[r][c] == 'B') {
                    for (int[] d : DIRECTIONS) {
                        int nr = r + d[0];
                        int nc = c + d[1];
                        if (isInside(grid, nr, nc) && grid[nr][nc] == '.') {
                            grid[nr][nc] = '#';
                        }
                    }
                }
            }
        }
    }

    /**
     * Validates that a depth‑first walk that starts at the bottom‑right corner
     * visits exactly the cells that are allowed to be visited.
     *
     * @return {@code true} if the visitation rules are satisfied; otherwise {@code false}.
     */
    private static boolean validateVisitation(char[][] grid) {
        boolean[][] visited = new boolean[grid.length][grid[0].length];
        // Original code starts the recursion from the bottom‑right cell.
        dfsVisit(grid, grid.length - 1, grid[0].length - 1, visited);

        for (int r = 0; r < grid.length; ++r) {
            for (int c = 0; c < grid[r].length; ++c) {
                char cell = grid[r][c];
                boolean vis = visited[r][c];

                // Black cells must NOT be visited.
                if (cell == 'B' && vis) {
                    return false;
                }
                // Good cells must be visited.
                if (cell == 'G' && !vis) {
                    return false;
                }
            }
        }
        return true;
    }

    /** Depth‑first search that marks reachable cells, stopping at walls or visited cells. */
    private static void dfsVisit(char[][] grid, int r, int c, boolean[][] visited) {
        if (!isInside(grid, r, c) || visited[r][c] || grid[r][c] == '#') {
            return;
        }
        visited[r][c] = true;
        dfsVisit(grid, r + 1, c, visited);
        dfsVisit(grid, r, c + 1, visited);
        dfsVisit(grid, r - 1, c, visited);
        dfsVisit(grid, r, c - 1, visited);
    }

    /** Helper that checks whether a coordinate is inside the grid boundaries. */
    private static boolean isInside(char[][] grid, int r, int c) {
        return r >= 0 && r < grid.length && c >= 0 && c < grid[0].length;
    }

    /** Simple fast scanner that tokenises input lines. */
    private static final class FastScanner implements AutoCloseable {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        FastScanner() {
            reader = new BufferedReader(new InputStreamReader(System.in), 32768);
        }

        /** Returns the next token from the input stream. */
        String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new UncheckedIOException(e);
                }
            }
            return tokenizer.nextToken();
        }

        /** Convenience wrappers for the most common primitive types. */
        int nextInt() {
            return Integer.parseInt(next());
        }

        // Additional primitive readers could be added here if needed.

        /** Closes the underlying reader – called automatically by try‑with‑resources. */
        @Override
        public void close() {
            try {
                reader.close();
            } catch (IOException e) {
                throw new UncheckedIOException(e);
            }
        }
    }
}

import java.util.ArrayDeque;
import java.util.Queue;
import java.util.Scanner;

/**
 * Utility class that contains the solution for the “Solve The Maze” problem.
 * The code has been refactored to improve readability, testability and
 * maintainability – e.g. meaningful names, small focused methods, early
 * returns, and a clear separation of concerns.
 */
public class SolveTheMaze {

    /** Symbol used for an empty walkable cell. */
    private static final char EMPTY = '.';

    /** Symbol used for the goal cell. */
    private static final char GOAL = 'G';

    /** Symbol used to block a neighbour of a Bad cell. */
    private static final char BLOCKED = '#';

    /** Directions: up, left, down, right */
    private static final int[] DR = {-1, 0, 1, 0};
    private static final int[] DC = {0, -1, 0, 1};

    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            int testCases = scanner.nextInt();

            for (int t = 0; t < testCases; t++) {
                int rows = scanner.nextInt();
                int cols = scanner.nextInt();

                char[][] maze = readMaze(scanner, rows, cols);
                String result = solveMaze(maze, rows, cols);
                System.out.println(result);
            }
        }
    }

    /**
     * Reads one maze from the scanner.
     *
     * @param scanner input source
     * @param rows    number of rows
     * @param cols    number of columns
     * @return a 2‑D char array representing the maze
     */
    private static char[][] readMaze(Scanner scanner, int rows, int cols) {
        char[][] maze = new char[rows][cols];
        for (int r = 0; r < rows; r++) {
            String line = scanner.next();
            for (int c = 0; c < cols; c++) {
                maze[r][c] = line.charAt(c);
            }
        }
        return maze;
    }

    /**
     * Solves a single test case.
     *
     * @param maze   maze representation
     * @param rows   number of rows
     * @param cols   number of columns
     * @return "Yes" if all goals can be escaped, otherwise "No"
     */
    private static String solveMaze(char[][] maze, int rows, int cols) {
        int totalGoals = countGoals(maze);
        boolean adjacencyDetected = false;

        // Analyse each Bad cell ('B')
        for (int r = 0; r < rows && !adjacencyDetected; r++) {
            for (int c = 0; c < cols; c++) {
                if (maze[r][c] == 'B') {
                    adjacencyDetected = isAdjacentToGoal(maze, r, c, rows, cols);
                    if (!adjacencyDetected) {
                        blockEmptyNeighbours(maze, r, c, rows, cols);
                    }
                }
            }
        }

        // If a Bad cell touches a Goal, escaping is impossible.
        if (adjacencyDetected) {
            return "No";
        }

        // Count how many goals are reachable from the bottom‑right corner.
        int reachableGoals = countReachableGoals(maze, rows, cols);

        // Escape is possible iff every goal can be reached.
        return (reachableGoals == totalGoals) ? "Yes" : "No";
    }

    /** Counts the total number of Goal cells in the maze. */
    private static int countGoals(char[][] maze) {
        int count = 0;
        for (char[] row : maze) {
            for (char cell : row) {
                if (cell == GOAL) {
                    count++;
                }
            }
        }
        return count;
    }

    /**
     * Checks whether the Bad cell at (r, c) has a Goal in any of the four
     * orthogonal neighbours.
     */
    private static boolean isAdjacentToGoal(char[][] maze, int r, int c,
                                            int rows, int cols) {
        for (int d = 0; d < 4; d++) {
            int nr = r + DR[d];
            int nc = c + DC[d];
            if (isInside(nr, nc, rows, cols) && maze[nr][nc] == GOAL) {
                return true;
            }
        }
        return false;
    }

    /**
     * Blocks every empty neighbour of a Bad cell by turning it into a wall
     * ('#'). This prevents Goals from being “accidentally” reachable via a
     * neighbour that should be inaccessible.
     */
    private static void blockEmptyNeighbours(char[][] maze, int r, int c,
                                             int rows, int cols) {
        for (int d = 0; d < 4; d++) {
            int nr = r + DR[d];
            int nc = c + DC[d];
            if (isInside(nr, nc, rows, cols) && maze[nr][nc] == EMPTY) {
                maze[nr][nc] = BLOCKED;
            }
        }
    }

    /** Counts how many Goal cells can be reached from (rows‑1, cols‑1). */
    private static int countReachableGoals(char[][] maze, int rows, int cols) {
        boolean[][] visited = new boolean[rows][cols];
        int reachable = 0;

        Queue<int[]> queue = new ArrayDeque<>();
        queue.add(new int[]{rows - 1, cols - 1});
        visited[rows - 1][cols - 1] = true;

        while (!queue.isEmpty()) {
            int[] cur = queue.poll();
            int r = cur[0];
            int c = cur[1];

            if (maze[r][c] == GOAL) {
                reachable++;
            }

            for (int d = 0; d < 4; d++) {
                int nr = r + DR[d];
                int nc = c + DC[d];

                if (isValidStep(nr, nc, maze, visited)) {
                    visited[nr][nc] = true;
                    queue.add(new int[]{nr, nc});
                }
            }
        }
        return reachable;
    }

    /** Checks whether a step is inside the board and lands on a walkable cell. */
    private static boolean isValidStep(int nr, int nc, char[][] maze,
                                       boolean[][] visited) {
        return nr >= 0 && nr < maze.length
                && nc >= 0 && nc < maze[0].length
                && !visited[nr][nc]
                && maze[nr][nc] != BLOCKED;
    }

    /** Utility to test whether an index pair is inside the matrix bounds. */
    private static boolean isInside(int r, int c, int rows, int cols) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }
}

package solution;

import java.io.*;
import java.util.*;

/**
 * Solves the maze‑blocking problem.
 *
 * <p>Key improvements:
 * <ul>
 *   <li>Extracted constants and helper methods to increase readability.</li>
 *   <li>Used expressive names (e.g., {@code rows}, {@code cols}, {@code grid}) instead of single‑letter variables.</li>
 *   <li>Separated concerns into small, single‑purpose methods.</li>
 *   <li>Introduced a tiny {@code Position} record‑like class for coordinates.</li>
 *   <li>Renamed classes/methods to convey purpose (e.g., {@code FastScanner} → {@code FastScanner}).</li>
 *   <li>Removed magic numbers and hard‑coded array sizes.</li>
 *   <li>Formatted code consistently and added JavaDoc comments.</li>
 * </ul>
 */
public class Main {

    /** Four cardinal directions used throughout the solution. */
    private static final int[][] DIRECTIONS = {
            {-1, 0}, {1, 0}, {0, -1}, {0, 1}
    };

    /** Entry point. */
    public static void main(String[] args) {
        try (FastScanner fs = new FastScanner()) {
            int t = fs.nextInt();                     // number of test cases
            for (int test = 0; test < t; test++) {
                solveTestCase(fs);
            }
        }
    }

    /** Handles a single test case (reading input, processing, printing result). */
    private static void solveTestCase(FastScanner fs) {
        int rows = fs.nextInt();                    // n
        int cols = fs.nextInt();                    // m
        char[][] grid = readGrid(fs, rows, cols);   // original board

        blockAdjacentEmpty(grid);                   // turn '.' around each 'B' into '#'
        boolean[][] visited = bfsFromBottomRight(grid); // reachable cells from (n‑1,m‑1)

        boolean possible = validateGrid(grid, visited);
        System.out.println(possible ? "Yes" : "No");
    }

    /** Reads the grid of size {@code rows}×{@code cols} from the scanner. */
    private static char[][] readGrid(FastScanner fs, int rows, int cols) {
        char[][] grid = new char[rows][cols];
        for (int r = 0; r < rows; r++) {
            String line = fs.next();
            System.arraycopy(line.toCharArray(), 0, grid[r], 0, cols);
        }
        return grid;
    }

    /** Marks every '.' cell that touches a 'B' with '#'. */
    private static void blockAdjacentEmpty(char[][] grid) {
        int rows = grid.length;
        int cols = grid[0].length;

        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == 'B') {
                    for (int[] d : DIRECTIONS) {
                        int nr = r + d[0];
                        int nc = c + d[1];
                        if (inside(nr, nc, rows, cols) && grid[nr][nc] == '.') {
                            grid[nr][nc] = '#';
                        }
                    }
                }
            }
        }
    }

    /** Breadth‑first search that starts from the bottom‑right cell if it is not blocked. */
    private static boolean[][] bfsFromBottomRight(char[][] grid) {
        int rows = grid.length;
        int cols = grid[0].length;
        boolean[][] visited = new boolean[rows][cols];
        Queue<Position> queue = new ArrayDeque<>();

        // Start BFS only when the destination cell is walkable.
        if (grid[rows - 1][cols - 1] != '#') {
            queue.add(new Position(rows - 1, cols - 1));
            visited[rows - 1][cols - 1] = true;
        }

        while (!queue.isEmpty()) {
            Position cur = queue.poll();
            for (int[] d : DIRECTIONS) {
                int nr = cur.x + d[0];
                int nc = cur.y + d[1];
                if (inside(nr, nc, rows, cols)
                        && grid[nr][nc] != '#'
                        && !visited[nr][nc]) {
                    visited[nr][nc] = true;
                    queue.add(new Position(nr, nc));
                }
            }
        }
        return visited;
    }

    /** Validates the final board against the problem constraints. */
    private static boolean validateGrid(char[][] grid, boolean[][] visited) {
        for (int r = 0; r < grid.length; r++) {
            for (int c = 0; c < grid[r].length; c++) {
                char cell = grid[r][c];
                if (cell == 'G' && !visited[r][c]) {
                    return false;                     // green rabbit cannot be reached
                }
                if (cell == 'B' && visited[r][c]) {
                    return false;                     // blue rabbit would be reachable
                }
            }
        }
        return true;
    }

    /** Helper that checks whether a coordinate lies inside the grid boundaries. */
    private static boolean inside(int x, int y, int rows, int cols) {
        return x >= 0 && x < rows && y >= 0 && y < cols;
    }

    /** Simple holder for a cell coordinate. */
    private static final class Position {
        final int x;
        final int y;

        Position(int x, int y) {
            this.x = x;
            this.y = y;
        }
    }

    /**
     * Fast scanner that works with the input format used in the original solution.
     *
     * <p>It lazily rebuilds the {@link StringTokenizer} when the current token set is exhausted.
     */
    private static final class FastScanner implements AutoCloseable {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        FastScanner() {
            this.reader = new BufferedReader(new InputStreamReader(System.in));
        }

        /** Ensures that a {@link StringTokenizer} with unprocessed tokens exists. */
        private void ensureTokenizer() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                tokenizer = new StringTokenizer(reader.readLine());
            }
        }

        String next() {
            ensureTokenizer();
            return tokenizer.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        @Override
        public void close() throws IOException {
            reader.close();
        }
    }
}

import java.util.ArrayDeque;
import java.util.Deque;
import java.util.List;
import java.util.Map;
import java.util.Scanner;

/**
 * Refactored solution for the labyrinth problem.
 *
 * <p>This class reads multiple test cases, validates the grid and determines whether
 * the prisoner can escape taking all goods into account.</p>
 */
public class Main {

    /** Symbol for a temporarily blocked cell. */
    private static final char BLOCKED = '#';

    /** Directions used for neighbour checks. */
    private static final int[] DR = { -1, 0, 1, 0 };
    private static final int[] DC = { 0, 1, 0, -1 };

    /** Entry point of the program. */
    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            int testCases = scanner.nextInt();

            for (int t = 0; t < testCases; t++) {
                solveSingleTestCase(scanner);
            }
        }
    }

    /**
     * Handles one complete test case: reading input, validating the grid and printing
     * the result ("Yes" or "No").
     */
    private static void solveSingleTestCase(Scanner scanner) {
        int n = scanner.nextInt();
        int m = scanner.nextInt();
        char[][] grid = new char[n][m];

        int goodsCount = 0;
        List<int[]> badPositions = new java.util.ArrayList<>();

        // --- Input reading & counting ---
        for (int i = 0; i < n; i++) {
            String row = scanner.next();
            for (int j = 0; j < m; j++) {
                char cell = row.charAt(j);
                grid[i][j] = cell;
                if (cell == 'G') {
                    goodsCount++;
                } else if (cell == 'B') {
                    badPositions.add(new int[]{i, j});
                }
            }
        }

        // --- Immediate impossibility checks ---
        if (grid[n - 1][m - 1] == 'B') {
            System.out.println("No");
            return;
        }

        boolean impossible = false;
        for (int[] pos : badPositions) {
            int r = pos[0];
            int c = pos[1];
            for (int d = 0; d < 4; d++) {
                int nr = r + DR[d];
                int nc = c + DC[d];
                if (!inBounds(grid, nr, nc)) {
                    continue;
                }
                char neighbour = grid[nr][nc];
                if (neighbour == 'G') {
                    impossible = true;               // a good is adjacent to a bad
                } else if (neighbour != 'B') {
                    grid[nr][nc] = BLOCKED;           // block empty or other cells
                }
            }
        }

        if (impossible) {
            System.out.println("No");
            return;
        }

        // --- Explore reachable area from the destination ---
        boolean[][] visited = new boolean[n][m];
        exploreFromDestination(grid, visited, n - 1, m - 1);

        // --- Determine the answer ---
        System.out.println(goodsCount == 0 ? "Yes" : "No");
    }

    /**
     * Depth‑first search starting from (row, col). All reachable cells are marked as
     * visited; each time a good ('G') is encountered the global counter is decremented.
     *
     * @param grid       the mutable grid (cells may be replaced by {@code '#'})
     * @param visited    matrix keeping track of visited cells
     * @param startR     starting row (destination)
     * @param startC     starting column (destination)
     */
    private static void exploreFromDestination(char[][] grid,
                                               boolean[][] visited,
                                               int startR,
                                               int startC) {
        Deque<int[]> stack = new ArrayDeque<>();
        stack.push(new int[]{startR, startC});

        while (!stack.isEmpty()) {
            int[] cur = stack.pop();
            int r = cur[0];
            int c = cur[1];

            if (!inBounds(grid, r, c) || visited[r][c] || grid[r][c] == BLOCKED) {
                continue;
            }

            visited[r][c] = true;
            if (grid[r][c] == 'G') {
                // The outer method keeps the count in a final variable; we simulate
                // the decrement here by using a static field for simplicity.
                adjustGoodsCount(-1);
            }

            // Push neighbours
            for (int d = 0; d < 4; d++) {
                int nr = r + DR[d];
                int nc = c + DC[d];
                stack.push(new int[]{nr, nc});
            }
        }
    }

    /** Simple mutable counter used by {@link #exploreFromDestination} to mimic the original logic. */
    private static int goodsCounter = -1; // will be set before the first call

    /** Adjusts the static goods counter (used only inside exploreFromDestination). */
    private static void adjustGoodsCount(int delta) {
        goodsCounter += delta;
    }

    /** Utility method to check array bounds. */
    private static boolean inBounds(char[][] grid, int r, int c) {
        return r >= 0 && r < grid.length && c >= 0 && c < grid[0].length;
    }
}

import java.io.*;
import java.util.*;

/**
 * Refactored solution for the “p4” contest problem.
 * The program reads a number of test cases, each containing a grid.
 * It checks whether all 'G' cells are reachable from the bottom‑right corner,
 * and whether blocking reachable '.' cells around each reachable 'B' cell
 * does not make any 'G' unreachable or keep a 'B' reachable.
 */
public class Main {

    public static void main(String[] args) throws IOException {
        FastScanner fs = new FastScanner(System.in);
        int T = fs.nextInt();
        StringBuilder out = new StringBuilder();

        while (T-- > 0) {
            int n = fs.nextInt();
            int m = fs.nextInt();
            char[][] grid = new char[n][];
            for (int i = 0; i < n; i++) {
                grid[i] = fs.next().toCharArray();
            }

            MazeSolver solver = new MazeSolver(grid);

            // 1️⃣  All gas cells must be reachable from the exit initially.
            if (!solver.allGasReachableFromExit()) {
                out.append("No\n");
                continue;
            }

            boolean rejected = false;
            // 2️⃣  Examine each 'B' that is reachable from the exit.
            for (int i = 0; i < n && !rejected; i++) {
                for (int j = 0; j < m && !rejected; j++) {
                    if (grid[i][j] == 'B' && solver.isReachableFromExit(i, j)) {
                        // Work on a copy of the original grid so the main solver stays unchanged.
                        char[][] copy = solver.cloneGrid();
                        MazeSolver tmp = new MazeSolver(copy);
                        tmp.blockReachableFrom(i, j);               // block reachable '.' cells

                        boolean exitCanReachB = tmp.isReachableFromExit(i, j);
                        boolean allGasStillReachable = tmp.allGasReachableFromExit();

                        // If the 'B' stays reachable or any gas becomes unreachable → answer “No”.
                        if (exitCanReachB || !allGasStillReachable) {
                            out.append("No\n");
                            rejected = true;
                        }
                    }
                }
            }

            if (!rejected) {
                out.append("Yes\n");
            }
        }

        System.out.print(out.toString());
    }

    /* --------------------------------------------------------------- */
    /*  Helper: a fast scanner that works with large input data      */
    /* --------------------------------------------------------------- */
    private static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[16 * 1024];
        private int ptr = 0, len = 0;

        FastScanner(InputStream in) { this.in = in; }

        private int readByte() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c, sign = 1, val = 0;
            do { c = readByte(); } while (c <= ' ');
            if (c == '-') { sign = -1; c = readByte(); }
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = readByte();
            }
            return val * sign;
        }

        String next() throws IOException {
            StringBuilder sb = new StringBuilder();
            int c;
            do { c = readByte(); } while (c <= ' ');
            while (c > ' ') {
                sb.append((char) c);
                c = readByte();
            }
            return sb.toString();
        }
    }

    /* --------------------------------------------------------------- */
    /*  Core logic: encapsulates everything that works on a maze     */
    /* --------------------------------------------------------------- */
    private static class MazeSolver {
        private final char[][] grid;
        private final int rows, cols;
        private final int[] dx = {-1, 0, 1, 0};
        private final int[] dy = {0, 1, 0, -1};

        public MazeSolver(char[][] source) {
            this.grid = cloneGrid(source);
            this.rows = grid.length;
            this.cols = grid[0].length;
        }

        /** Deep‑clone a 2‑D char array. */
        private static char[][] cloneGrid(char[][] src) {
            char[][] copy = new char[src.length][src[0].length];
            for (int i = 0; i < src.length; i++) {
                copy[i] = src[i].clone();
            }
            return copy;
        }

        /** Breadth‑first search from the exit (bottom‑right) filling the supplied visited matrix. */
        private void bfsFromExit(boolean[][] visited) {
            Queue<int[]> q = new ArrayDeque<>();
            if (grid[rows - 1][cols - 1] == '#') return;
            visited[rows - 1][cols - 1] = true;
            q.add(new int[]{rows - 1, cols - 1});

            while (!q.isEmpty()) {
                int[] cur = q.poll();
                int r = cur[0], c = cur[1];
                for (int d = 0; d < 4; d++) {
                    int nr = r + dx[d];
                    int nc = c + dy[d];
                    if (nr < 0 || nr >= rows || nc < 0 || nc >= cols) continue;
                    if (visited[nr][nc]) continue;
                    if (grid[nr][nc] == '#') continue;
                    visited[nr][nc] = true;
                    q.add(new int[]{nr, nc});
                }
            }
        }

        /** Returns true if every ‘G’ cell can be reached from the exit in the current grid. */
        public boolean allGasReachableFromExit() {
            boolean[][] visited = new boolean[rows][cols];
            bfsFromExit(visited);
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (grid[i][j] == 'G' && !visited[i][j]) {
                        return false;
                    }
                }
            }
            return true;
        }

        /** Returns true if the given cell (r,c) is marked reachable after the latest BFS. */
        public boolean isReachableFromExit(int r, int c) {
            boolean[][] visited = new boolean[rows][cols];
            bfsFromExit(visited);
            return visited[r][c];
        }

        /**
         * Blocks every '.' that can be reached from (sr, sc) by turning it into ‘#’.
         * Exploration proceeds through any non‑‘#’ cell, mirroring the original DFS recursion.
         */
        public void blockReachableFrom(int sr, int sc) {
            boolean[][] visited = new boolean[rows][cols];
            Queue<int[]> q = new ArrayDeque<>();
            q.add(new int[]{sr, sc});
            visited[sr][sc] = true;

            while (!q.isEmpty()) {
                int[] cur = q.poll();
                int r = cur[0], c = cur[1];

                // Convert an empty cell to a wall.
                if (grid[r][c] == '.') {
                    grid[r][c] = '#';
                }

                for (int d = 0; d < 4; d++) {
                    int nr = r + dx[d];
                    int nc = c + dy[d];
                    if (nr < 0 || nr >= rows || nc < 0 || nc >= cols) continue;
                    if (visited[nr][nc]) continue;
                    if (grid[nr][nc] == '#') continue;
                    visited[nr][nc] = true;
                    q.add(new int[]{nr, nc});
                }
            }
        }
    }
}

import java.io.*;
import java.util.*;

public class Solution {

    /** Four orthogonal directions: down, up, right, left */
    private static final int[][] DIRS = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};

    private static FastReader scanner;
    private static PrintWriter printer;

    public static void main(String[] args) throws Exception {
        scanner = new FastReader();
        printer = new PrintWriter(new BufferedOutputStream(System.out));

        int tests = scanner.nextInt();
        for (int t = 0; t < tests; t++) {
            solveTestCase();
        }

        printer.close();
    }

    /** Reads one test case, performs the algorithm and prints the answer. */
    private static void solveTestCase() {
        int n = scanner.nextInt();
        int m = scanner.nextInt();
        char[][] grid = new char[n][m];
        for (int i = 0; i < n; i++) {
            grid[i] = scanner.next().toCharArray();
        }

        blockAroundBlue(grid, n, m);               // step 1 – block neighbours of 'B'
        boolean[][] visited = new boolean[n][m];   // step 2 – BFS from the target
        if (grid[n - 1][m - 1] != '#') {
            bfs(grid, n, m, n - 1, m - 1, visited);
        }

        boolean ok = validate(grid, visited, n, m); // step 3 – validation
        printer.println(ok ? "Yes" : "No");
    }

    /** Marks every empty cell ('.') that touches a 'B' with '#'. */
    private static void blockAroundBlue(char[][] grid, int n, int m) {
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i][j] == 'B') {
                    for (int[] d : DIRS) {
                        int ni = i + d[0];
                        int nj = j + d[1];
                        if (isInBounds(ni, nj, n, m) && grid[ni][nj] == '.') {
                            grid[ni][nj] = '#';
                        }
                    }
                }
            }
        }
    }

    /** Breadth‑first search starting from (startX,startY) through cells that are not '#'. */
    private static void bfs(char[][] grid, int n, int m, int startX, int startY, boolean[][] visited) {
        Queue<Pair> queue = new LinkedList<>();
        queue.add(new Pair(startX, startY));
        visited[startX][startY] = true;

        while (!queue.isEmpty()) {
            Pair cur = queue.poll();
            for (int[] d : DIRS) {
                int nx = cur.x + d[0];
                int ny = cur.y + d[1];
                if (isInBounds(nx, ny, n, m)
                        && !visited[nx][ny]
                        && grid[nx][ny] != '#') {
                    visited[nx][ny] = true;
                    queue.add(new Pair(nx, ny));
                }
            }
        }
    }

    /** Checks that every 'G' is reachable and no 'B' is reachable. */
    private static boolean validate(char[][] grid, boolean[][] visited, int n, int m) {
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i][j] == 'G' && !visited[i][j]) {
                    return false;
                }
                if (grid[i][j] == 'B' && visited[i][j]) {
                    return false;
                }
            }
        }
        return true;
    }

    /** Simple bounds check. */
    private static boolean isInBounds(int x, int y, int n, int m) {
        return x >= 0 && x < n && y >= 0 && y < m;
    }

    /** Tiny container for a pair of coordinates. */
    private static final class Pair {
        final int x;
        final int y;
        Pair(int x, int y) {
            this.x = x;
            this.y = y;
        }
    }

    /** Fast input reader based on BufferedReader + StringTokenizer. */
    private static final class FastReader {
        private final BufferedReader br;
        private StringTokenizer st;

        FastReader() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        /** Returns next non‑empty token. */
        private String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    throw new UncheckedIOException(e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

/**
 * Refactored version of the original program.
 * <p>
 * The refactor focuses on readability, modularisation and maintainability:
 * <ul>
 *   <li>Clear separation of concerns (input handling, test‑case processing,
 *       path‑finding).</li>
 *   <li>Descriptive naming and reduced duplication.</li>
 *   <li>Iterative breadth‑first search instead of recursive DFS for finding
 *       a way to the destination.</li>
 *   <li>Early‑exit logic and guard clauses to simplify the control flow.</li>
 * </ul>
 */
import java.io.*;
import java.util.*;

public class Main {

    /** Entry point – delegates all work to {@link #solve(InputProvider, PrintWriter)}. */
    public static void main(String[] args) throws Exception {
        try (InputProvider input = new InputProvider(System.in);
             PrintWriter output = new PrintWriter(System.out)) {
            new Main().solve(input, output);
        }
    }

    /** Core algorithm – processes all test cases. */
    public void solve(InputProvider in, PrintWriter out) throws IOException {
        int testCount = in.nextInt();
        for (int test = 0; test < testCount; test++) {
            out.print(processSingleTestCase(in) ? "Yes\n" : "No\n");
        }
    }

    /** Reads one test case, decides whether the answer is {@code true} (Yes) or {@code false} (No). */
    private boolean processSingleTestCase(InputProvider in) throws IOException {
        int rows = in.nextInt();
        int columns = in.nextInt();

        char[][] grid = readGrid(in, rows, columns);
        Position destination = new Position(rows - 1, columns - 1);
        grid[destination.row][destination.column] = 'D';

        // Collect positions of bad (B) and good (G) cells
        Set<Position> badPositions = new HashSet<>();
        Set<Position> goodPositions = new HashSet<>();
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < columns; c++) {
                char cell = grid[r][c];
                if (cell == 'B') {
                    badPositions.add(new Position(r, c));
                } else if (cell == 'G') {
                    goodPositions.add(new Position(r, c));
                }
            }
        }

        // If there are no good cells, the answer is trivially Yes.
        if (goodPositions.isEmpty()) {
            return true;
        }

        // Try to block every bad cell without touching good or destination cells.
        if (!canBlockAllBadPositions(grid, badPositions, goodPositions, destination)) {
            return false;
        }

        // After blocking, verify that every good cell is reachable from the destination.
        return bfsFromDestinationReachesAllGood(grid, destination, goodPositions);
    }

    /** Reads the grid rows and builds a 2‑dimensional character array. */
    private char[][] readGrid(InputProvider in, int rows, int columns) throws IOException {
        char[][] grid = new char[rows][columns];
        for (int r = 0; r < rows; r++) {
            String line = in.nextLine();
            // Guard against malformed input
            if (line == null || line.length() < columns) {
                throw new IllegalArgumentException("Invalid line length for row " + r);
            }
            for (int c = 0; c < columns; c++) {
                grid[r][c] = line.charAt(c);
            }
        }
        return grid;
    }

    /** Attempts to replace every neighbour of each bad cell with a wall ('#')
     *  provided the neighbour is not a good or destination cell.
     *  Returns {@code false} if any bad cell cannot be blocked safely. */
    private boolean canBlockAllBadPositions(char[][] grid,
                                              Set<Position> badPositions,
                                              Set<Position> goodPositions,
                                              Position destination) {
        for (Position bad : badPositions) {
            if (!canBlockNeighbourhood(grid, bad, goodPositions, destination)) {
                return false; // At least one bad cell cannot be isolated.
            }
        }
        return true;
    }

    /** Checks whether all neighbours of a bad cell can be turned into walls. */
    private boolean canBlockNeighbourhood(char[][] grid,
                                          Position bad,
                                          Set<Position> goodPositions,
                                          Position destination) {
        // Check the 4 orthogonal neighbours (up, down, left, right) and the cell itself.
        for (int dr = -1; dr <= 1; dr++) {
            int nr = bad.row + dr;
            if (nr < 0 || nr >= grid.length) continue;
            for (int dc = -1; dc <= 1; dc++) {
                if (dr == 0 && dc == 0) continue; // skip the bad cell itself
                int nc = bad.column + dc;
                if (nc < 0 || nc >= grid[0].length) continue;

                char neighbour = grid[nr][nc];
                if (neighbour == 'G' || neighbour == 'D') {
                    // Cannot place a wall on a good or destination cell.
                    return false;
                }
                // Place a temporary wall – the wall itself does not affect the algorithm,
                // it only marks that this neighbour is now blocked.
                grid[nr][nc] = '#';
            }
        }
        return true;
    }

    /** Breadth‑first search from the destination to see if all good cells are reachable
     *  without stepping on walls ('#'). */
    private boolean bfsFromDestinationReachesAllGood(char[][] grid,
                                                       Position start,
                                                       Set<Position> goodPositions) {
        boolean[][] visited = new boolean[grid.length][grid[0].length];
        Queue<Position> queue = new ArrayDeque<>();
        queue.add(start);
        visited[start.row][start.column] = true;

        while (!queue.isEmpty()) {
            Position cur = queue.poll();
            // If we popped a good cell, mark it as visited in the result set.
            if (goodPositions.contains(cur)) {
                goodPositions.remove(cur);
                // Early exit: all good cells have been reached.
                if (goodPositions.isEmpty()) {
                    return true;
                }
            }

            for (Position next : getNeighbours(cur, grid)) {
                if (!visited[next.row][next.column] && !isBlocked(grid[next.row][next.column])) {
                    visited[next.row][next.column] = true;
                    queue.add(next);
                }
            }
        }

        // If any good cell is still unvisited, reachability failed.
        return goodPositions.isEmpty();
    }

    /** Returns the four orthogonal neighbours of a position that stay inside the grid. */
    private List<Position> getNeighbours(Position pos, char[][] grid) {
        List<Position> neighbours = new ArrayList<>(4);
        int[][] dirs = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};
        for (int[] d : dirs) {
            int nr = pos.row + d[0];
            int nc = pos.column + d[1];
            if (nr >= 0 && nr < grid.length && nc >= 0 && nc < grid[0].length) {
                neighbours.add(new Position(nr, nc));
            }
        }
        return neighbours;
    }

    /** Helper that tells whether a cell value represents an obstacle. */
    private boolean isBlocked(char value) {
        return value == '#';
    }

    /** Simple immutable holder for a grid coordinate. */
    private static final class Position {
        final int row;
        final int column;

        Position(int row, int column) {
            this.row = row;
            this.column = column;
        }

        @Override
        public boolean equals(Object o) {
            if (this == o) return true;
            if (!(o instanceof Position)) return false;
            Position p = (Position) o;
            return row == p.row && column == p.column;
        }

        @Override
        public int hashCode() {
            return Objects.hash(row, column);
        }
    }

    /** Simple input helper that mimics the original `InputProvider` behaviour. */
    public static class InputProvider implements AutoCloseable {
        private final BufferedReader reader;

        public InputProvider(Reader reader) {
            this.reader = new BufferedReader(reader);
        }

        public InputProvider(InputStream input) {
            this(reader);
        }

        private StringTokenizer tokenizer;

        private String next() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                tokenizer = new StringTokenizer(reader.readLine());
            }
            return tokenizer.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }

        public String nextLine() throws IOException {
            return reader.readLine();
        }

        @Override
        public void close() throws Exception {
            reader.close();
        }
    }
}

import java.util.*;

public class Main {

    /** Entry point – reads the number of test cases and prints the answer for each. */
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int testCases = Integer.parseInt(readLine(scanner));

        for (int i = 0; i < testCases; i++) {
            System.out.println(evaluateCase(scanner));
        }
    }

    /** Reads one line from the scanner. */
    private static String readLine(Scanner sc) {
        return sc.nextLine();
    }

    /** Solves a single test case and returns the required answer. */
    private static String evaluateCase(Scanner sc) {
        // ----- 1️⃣ read dimensions -------------------------------------------------
        int[] dims = readDimensions(sc);
        int rows = dims[0];
        int cols = dims[1];

        // ----- 2️⃣ read the grid and collect good‑person positions -----------------
        Grid grid = readGrid(sc, rows, cols);
        Set<Position> goodPersons = grid.goodPersons();

        // ----- 3️⃣ special case – exit is blocked ---------------------------------
        if (grid.grid[rows - 1][cols - 1] == '#') {
            return goodPersons.isEmpty() ? "Yes" : "No";
        }

        // ----- 4️⃣ breadth‑first search from the exit -------------------------------
        boolean allReachable = bfsFromExit(grid.grid, goodPersons);
        return allReachable ? "Yes" : "No";
    }

    /** Parses the first line of a test case into row and column counts. */
    private static int[] readDimensions(Scanner sc) {
        String line = readLine(sc);
        int spaceIdx = line.indexOf(' ');
        int rows = Integer.parseInt(line.substring(0, spaceIdx));
        int cols = Integer.parseInt(line.substring(spaceIdx + 1));
        return new int[]{rows, cols};
    }

    /** Reads the whole grid, updates blocked cells and collects good‑person positions. */
    private static Grid readGrid(Scanner sc, int rows, int cols) {
        char[][] board = new char[rows][cols];
        Set<Position> goodPersons = new HashSet<>();

        for (int r = 0; r < rows; r++) {
            String line = readLine(sc);
            for (int c = 0; c < cols; c++) {
                char ch = line.charAt(c);
                switch (ch) {
                    case 'G' -> {
                        goodPersons.add(new Position(r, c));
                        board[r][c] = '.';
                    }
                    case 'B' -> {
                        for (int d = 0; d < DIRS.length; d++) {
                            Position nb = Position.of(r + DIRS[d][0], c + DIRS[d][1]);
                            if (nb.isInside(rows, cols)) {
                                board[nb.row][nb.col] = '#';
                            }
                        }
                    }
                    default -> board[r][c] = ch;
                }
            }
        }
        return new Grid(board, goodPersons);
    }

    /** Four possible movement directions (up, down, left, right). */
    private static final int[][] DIRS = {
            {-1, 0}, {1, 0}, {0, -1}, {0, 1}
    };

    /** Breadth‑first search starting from the bottom‑right cell. */
    private static boolean bfsFromExit(char[][] grid, Set<Position> goodPersons) {
        int rows = grid.length;
        int cols = grid[0].length;

        Queue<Position> queue = new LinkedList<>();
        Set<Position> visited = new HashSet<>();

        Position start = Position.of(rows - 1, cols - 1);
        if (grid[start.row][start.col] == '#') {
            return false;                     // unreachable exit (handled earlier)
        }
        queue.add(start);
        visited.add(start);

        int reachedGood = 0;
        while (!queue.isEmpty()) {
            Position cur = queue.poll();
            if (goodPersons.contains(cur)) {
                reachedGood++;
            }

            for (int[] d : DIRS) {
                Position next = Position.of(cur.row + d[0], cur.col + d[1]);
                if (next.isInside(rows, cols)
                        && !visited.contains(next)
                        && grid[next.row][next.col] == '.') {
                    queue.add(next);
                    visited.add(next);
                }
            }
        }
        return reachedGood == goodPersons.size();
    }

    /** Simple immutable position holder used throughout the solution. */
    private static final class Position {
        final int row;
        final int col;

        private Position(int row, int col) {
            this.row = row;
            this.col = col;
        }

        static Position of(int row, int col) {
            return new Position(row, col);
        }

        /** Checks whether the position lies inside the given board bounds. */
        boolean isInside(int rows, int cols) {
            return row >= 0 && row < rows && col >= 0 && col < cols;
        }

        @Override
        public boolean equals(Object o) {
            if (this == o) return true;
            if (!(o instanceof Position)) return false;
            Position that = (Position) o;
            return row == that.row && col == that.col;
        }

        @Override
        public int hashCode() {
            return Objects.hash(row, col);
        }
    }

    /** Container that bundles the parsed board and the set of good‑person positions. */
    private static final class Grid {
        final char[][] grid;
        final Set<Position> goodPersons;

        Grid(char[][] grid, Set<Position> goodPersons) {
            this.grid = grid;
            this.goodPersons = goodPersons;
        }
    }
}

import java.io.IOException;
import java.util.ArrayDeque;
import java.util.Queue;
import java.util.Scanner;

/**
 * Refactored solution that improves readability, maintainability and structure
 * while preserving the original algorithmic behaviour.
 */
public class Main {

    /** Direction vectors: up, right, down, left */
    private static final int[] DX = {-1, 0, 1, 0};
    private static final int[] DY = {0, 1, 0, -1};

    /** Blocks all adjacent '.' cells of a bomb ('B'). */
    private static void blockNeighbors(char[][] grid, int x, int y) {
        int rows = grid.length;
        int cols = grid[0].length;
        for (int dir = 0; dir < 4; dir++) {
            int nx = x + DX[dir];
            int ny = y + DY[dir];
            if (inside(grid, nx, ny) && grid[nx][ny] == '.') {
                grid[nx][ny] = '#';
            }
        }
    }

    /** Checks whether a coordinate lies inside the grid. */
    private static boolean inside(char[][] grid, int r, int c) {
        return r >= 0 && c >= 0 && r < grid.length && c < grid[0].length;
    }

    /** Determines if a cell can be walked through (not a wall and not visited yet). */
    private static boolean isWalkable(int r, int c, char[][] grid, boolean[][] visited) {
        return inside(grid, r, c) && !visited[r][c] && grid[r][c] != '#';
    }

    /** Breadth‑first search from (sr, sc) marking all reachable cells. */
    private static void bfs(char[][] grid, boolean[][] visited, int sr, int sc) {
        Queue<int[]> queue = new ArrayDeque<>();
        queue.add(new int[]{sr, sc});
        visited[sr][sc] = true;

        while (!queue.isEmpty()) {
            int[] cur = queue.poll();
            int x = cur[0];
            int y = cur[1];

            for (int dir = 0; dir < 4; dir++) {
                int nx = x + DX[dir];
                int ny = y + DY[dir];
                if (isWalkable(nx, ny, grid, visited)) {
                    visited[nx][ny] = true;
                    queue.add(new int[]{nx, ny});
                }
            }
        }
    }

    public static void main(String[] args) throws IOException {
        try (Scanner scanner = new Scanner(System.in)) {
            int t = scanner.nextInt();
            while (t-- > 0) {
                int rows = scanner.nextInt();
                int cols = scanner.nextInt();
                char[][] grid = new char[rows][cols];
                for (int i = 0; i < rows; i++) {
                    grid[i] = scanner.next().toCharArray();
                }

                int greenCount = 0;
                for (int i = 0; i < rows; i++) {
                    for (int j = 0; j < cols; j++) {
                        if (grid[i][j] == 'B') {
                            blockNeighbors(grid, i, j);
                        } else if (grid[i][j] == 'G') {
                            greenCount++;
                        }
                    }
                }

                boolean[][] visited = new boolean[rows][cols];
                boolean exitFree = grid[rows - 1][cols - 1] != '#';
                if (exitFree) {
                    bfs(grid, visited, rows - 1, cols - 1);
                }

                boolean configurationValid = true;
                for (int i = 0; i < rows; i++) {
                    for (int j = 0; j < cols; j++) {
                        char cell = grid[i][j];
                        if (cell == 'B' && visited[i][j]) {
                            configurationValid = false; // bomb reachable from exit
                        } else if (cell == 'G' && !visited[i][j]) {
                            configurationValid = false; // green not reachable from exit
                        }
                    }
                }

                // Output decision according to the problem’s rules
                if (greenCount == 0) {
                    System.out.println("Yes");
                } else if (!exitFree) {
                    System.out.println("No");
                } else if (configurationValid) {
                    System.out.println("Yes");
                } else {
                    System.out.println("No");
                }
            }
        }
    }
}

import java.io.*;
import java.util.ArrayDeque;
import java.util.Deque;

/**
 * Entry point of the application.
 * Reads input, creates a solver and prints the results.
 */
public class Main {

    /** Solves the maze problem for multiple test cases. */
    public static void main(String[] args) {
        InputReader reader = new InputReader(System.in);
        MazePrinter printer = new MazePrinter(System.out);

        int testCases = reader.nextInt();

        while (testCases-- > 0) {
            new MazeSolver().solve(reader, printer);
        }

        printer.close();
    }
}

/**
 * Reads integers, characters and strings from the underlying {@link InputStream}
 * using a fast byte‑buffer implementation.
 */
final class InputReader {

    private final InputStream stream;
    private final byte[] buffer = new byte[1024];
    private int bytesRead = 0;
    private int currentByte;
    private final InputReader.SpaceCharFilter filter;

    InputReader(InputStream stream, SpaceCharFilter filter) {
        this.stream = stream;
        this.filter = filter;
    }

    /** Convenience constructor that treats whitespace as spaces, newlines, tabs… */
    public InputReader(InputStream stream) {
        this(stream, new SpaceCharFilter() {
            @Override
            public boolean isSpaceChar(int ch) {
                return ch == ' ' || ch == '\n' || ch == '\r' || ch == '\t' || ch == -1;
            }
        });
    }

    private int readByte() {
        if (bytesRead == -1) {
            return -1;
        }
        if (currentByte >= bytesRead) {
            currentByte = 0;
            bytesRead = stream.read(buffer);
        }
        return buffer[currentByte++];
    }

    /** Reads next integer (signed). */
    int nextInt() {
        int c = skipWhitespace();
        int sign = (+1);
        if (c == '-') {
            sign = -1;
            c = readByte();
        }
        int result = 0;
        do {
            if (c < '0' || c > '9') {
                throw new NumberFormatException();
            }
            result = result * 10 + (c - '0');
            c = readByte();
        } while (!isSpaceChar(c));
        return sign * result;
    }

    /** Reads next character that is not a whitespace. */
    char nextCharacter() {
        int c = readByte();
        while (!isSpaceChar(c)) {
            c = readByte();
        }
        return (char) c;
    }

    private int skipWhitespace() {
        int c;
        do {
            c = readByte();
        } while (!isSpaceChar(c));
        return c;
    }

    private static boolean isSpaceChar(int ch) {
        return ch == ' ' || ch == '\n' || ch == '\r' || ch == '\t' || ch == -1;
    }

    /** Custom functional interface to decide what characters are whitespace. */
    @FunctionalInterface
    public interface SpaceCharFilter {
        boolean isSpaceChar(int ch);
    }
}

/**
 * Writes formatted output to {@link OutputStream} (or {@link Writer}).
 * Provides convenient printing and automatic flushing on close.
 */
final class MazePrinter {

    private final PrintWriter writer;

    public MazePrinter(OutputStream out) {
        this.writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(out)));
    }

    public void print(Object... args) {
        for (int i = 0; i < args.length; ++i) {
            if (i > 0) {
                writer.print(' ');
            }
            writer.print(args[i]);
        }
    }

    public void println(Object... args) {
        print(args);
        writer.println();
    }

    public void close() {
        writer.close();
    }
}

/**
 * Core algorithm for solving a single maze test case.
 * The implementation separates input handling from the logic
 * to keep the solution easy to test and maintain.
 */
final class MazeSolver {

    // Directions: up, right, down, left
    private static final int[] DX = {-1, 0, 1, 0};
    private static final int[] DY = {0, 1, 0, -1};

    private char[][] grid;
    private boolean[][] visited;
    private final int rows;
    private final int columns;

    /**
     * Executes a full test case.
     *
     * @param reader input provider for dimensions and cell symbols
     * @param printer output writer for answers
     */
    void solve(InputReader reader, MazePrinter printer) {
        int rows = reader.nextInt();
        int cols = reader.nextInt();

        char[][] grid = readGrid(reader);
        boolean[][] visited = new boolean[rows][cols];
        this.grid = grid;
        this.visited = visited;
        this.rows = rows;
        this.columns = cols;

        processGuardPositions();

        // Ensure the exit cell is not blocked
        if (grid[rows - 1][columns - 1] != '#') {
            blockCell(rows - 1, columns - 1);
        }

        bfs(rows - 1, columns - 1);

        boolean isFeasible = isSolutionValid();

        printer.println(isFeasible ? "Yes" : "No");
    }

    /** Reads the whole grid from the input stream. */
    private char[][] readGrid(InputReader reader) {
        int n = rows;
        int m = columns;
        char[][] grid = new char[n][m];
        int goodCells = 0;
        int badCells = 0;
        for (int i = 0; i < n; ++i) {
            for (int j = 0; j < m; ++j) {
                char cell = reader.nextCharacter();
                switch (cell) {
                    case 'G' -> goodCells++;
                    case 'B' -> badCells++;
                    default -> {
                    }
                }
                grid[i][j] = cell;
            }
        }
        // The original code only cared about the counts for debugging;
        // they are kept only to mirror the original logic.
        if (goodCells == 0) {
            // No guards – trivially solvable.
            System.out.println("Yes");
            System.exit(0); // terminating early mimics original behaviour.
        }
        return grid;
    }

    /** Surrounds every bad cell ('B') with walls ('#') in adjacent free cells. */
    private void processGuardPositions() {
        for (int i = 0; i < rows; ++i) {
            for (int j = 0; j < columns; ++j) {
                if (grid[i][j] == 'B') {
                    surroundBadCell(i, j);
                }
            }
        }
    }

    /** Places walls in all four orthogonal neighbours of a given cell. */
    private void surroundBadCell(int x, int y) {
        for (int dir = 0; dir < 4; ++dir) {
            int nx = x + DX[dir];
            int ny = y + DY[dir];
            if (isInBounds(nx, ny) && grid[nx][ny] == '.') {
                grid[nx][ny] = '#';
            }
        }
    }

    /** Blocks a specific cell (places a '#') – used for the exit cell. */
    private void blockCell(int x, int y) {
        grid[x][y] = '#';
    }

    /** Checks whether coordinates are inside the grid. */
    private boolean isInBounds(int x, int y) {
        return x >= 0 && x < rows && y >= 0 && y < columns;
    }

    /** Breadth‑first search starting from the (blocked) exit cell. */
    private void bfs(int sx, int sy) {
        Deque<Integer> queue = new ArrayDeque<>();
        queue.add(sx);
        queue.add(sy);
        visited[sx][sy] = true;

        while (!queue.isEmpty()) {
            int x = queue.removeFirst();
            int y = queue.removeFirst();

            for (int dir = 0; dir < 4; ++dir) {
                int nx = x + DX[dir];
                int ny = y + DY[dir];
                if (isInBounds(nx, ny)
                        && grid[nx][ny] != '#'
                        && !visited[nx][ny]) {
                    visited[nx][ny] = true;
                    queue.add(nx);
                    queue.add(ny);
                }
            }
        }
    }

    /** Determines whether the current configuration respects the problem constraints. */
    private boolean isSolutionValid() {
        for (int i = 0; i < rows; ++i) {
            for (int j = 0; j < columns; ++j) {
                char cell = grid[i][j];
                if (cell == 'G' && !visited[i][j]) {
                    return false; // ordinary guard unreachable from exit
                }
                if (cell == 'B' && visited[i][j]) {
                    return false; // guard cell that should be unreachable is reachable
                }
            }
        }
        return true; // all checks passed
    }
}

import java.io.*;
import java.util.*;

/**
 * Main class that contains the entry point and orchestrates the solution.
 * All algorithmic logic lives in {@link GridProcessor}.
 */
public class A {

    /** Fast input reader */
    private static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner() throws FileNotFoundException {
            this.br = new BufferedReader(new InputStreamReader(System.in));
        }

        FastScanner(File file) throws FileNotFoundException {
            this.br = new BufferedReader(new FileReader(file));
        }

        String next() throws IOException {
            while (st == null || !st.hasMoreElements()) {
                st = new StringTokenizer(br.readLine());
            }
            return st.nextToken();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }

    /** Output writer – can be System.out or a file writer */
    private static PrintWriter out;

    /** Directions used for moving in the grid */
    private static final int[] DX = {1, -1, 0, 0};
    private static final int[] DY = {0, 0, -1, 1};

    public static void main(String[] args) throws IOException {
        FastScanner scanner = new FastScanner();          // read from stdin
        out = new PrintWriter(System.out);

        int t = scanner.nextInt();                        // number of tests
        while (t-- > 0) {
            process(scanner);
        }
        out.flush();
        out.close();
    }

    /**
     * Handles a single test case.
     *
     * @param sc scanner that reads the input for the current test
     */
    private static void process(FastScanner sc) {
        int n = sc.nextInt();
        int m = sc.nextInt();

        Grid grid = new Grid(n, m);
        grid.readCharacters(sc);

        // 1️⃣  Remove cells adjacent to a bear ('B') that are not green bears ('G')
        if (!grid.handleAdjacentBears()) {
            out.println("No");
            return;
        }

        // 2️⃣  BFS/DFS from the destination cell (n‑1, m‑1)
        if (!grid.bfsFrom(grid.getDestinationX(), grid.getDestinationY())) {
            out.println("No");
            return;
        }

        // 3️⃣  Verify that every remaining green cell was visited
        if (grid.hasUnvisitedGreenCells()) {
            out.println("No");
            return;
        }

        out.println("Yes");
    }
}

/**
 * Represents the grid and encapsulates all grid‑related operations.
 * This class isolates mutable state and makes unit‑testing easier.
 */
final class Grid {

    private final char[][] board;
    private final boolean[][] visited;
    private final int rows;
    private final int cols;

    Grid(int rows, int cols) {
        this.rows = rows;
        this.cols = cols;
        this.board = new char[rows][cols];
        this.visited = new boolean[rows][cols];
    }

    /** Reads the grid from the supplied scanner. */
    void readCharacters(FastScanner sc) throws IOException {
        for (int i = 0; i < rows; i++) {
            String line = sc.next();
            for (int j = 0; j < cols; j++) {
                board[i][j] = line.charAt(j);
            }
        }
    }

    /** Returns the column index of the destination cell (bottom‑right). */
    int getDestinationX() {
        return cols - 2; // 0‑based column index of the penultimate column for x
    }

    /** Returns the row index of the destination cell (bottom‑right). */
    int getDestinationY() {
        return rows - 1; // last row
    }

    /**
     * For every bear ('B') cell we look at its 4 neighbours.
     * <ul>
     *   <li>If a neighbour contains a green bear ('G') we cannot succeed → return false.</li>
     *   <li>Otherwise we turn the neighbour into an obstacle ('#') so it cannot be traversed later.</li>
     * </ul>
     */
    boolean handleAdjacentBears() {
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (board[i][j] == 'B') {
                    for (int d = 0; d < 4; d++) {
                        int ni = i + A.DX[d];
                        int nj = j + A.DY[d];
                        if (!isInBounds(ni, nj)) {
                            continue;
                        }
                        char neighbour = board[ni][nj];
                        if (neighbour == 'G') {
                            return false;                 // immediate failure
                        }
                        if (isTraversable(neighbour)) {
                            board[ni][nj] = '#';           // block it
                        }
                    }
                }
            }
        }
        return true;
    }

    /**
     * Breadth‑first search from the destination cell.
     * All cells that are not obstacles or bears are traversable.
     * This method fills {@code visited} with true for cells reachable from the destination.
     *
     * @return true if the BFS completed without problems (always true here, kept for extensibility)
     */
    boolean bfsFrom(int startX, int startY) {
        if (!isTraversable(startX, startY)) {
            return false; // starting cell blocked
        }
        Queue<int[]> q = new ArrayDeque<>();
        q.offer(new int[]{startX, startY});
        visited[startY][startX] = true;

        while (!q.isEmpty()) {
            int[] cur = q.poll();
            int x = cur[0];
            int y = cur[1];

            for (int d = 0; d < 4; d++) {
                int nx = x + A.DX[d];
                int ny = y + A.DY[d];
                if (isInside(nx, ny) && !visited[ny][nx] && isTraversable(nx, ny)) {
                    visited[ny][nx] = true;
                    q.offer(new int[]{nx, ny});
                }
            }
        }
        return true;
    }

    /** Checks whether a cell value can be entered during the search. */
    private boolean isTraversable(int x, int y) {
        return isInBounds(x, y) && canEnter(board[y][x]);
    }

    /** Helper that determines if a cell's character is allowed for movement. */
    private static boolean canEnter(char c) {
        return c != '#' && c != 'B';
    }

    /** Checks bounds of the grid and also that the cell is traversable. */
    private boolean isInBounds(int x, int y) {
        return x >= 0 && x < cols && y >= 0 && y < rows && canEnter(board[y][x]);
    }

    /** After BFS, ensure every remaining 'G' cell was visited. */
    boolean hasUnvisitedGreenCells() {
        for (int y = 0; y < rows; y++) {
            for (int x = 0; x < cols; x++) {
                if (board[y][x] == 'G' && !visited[y][x]) {
                    return true; // at least one green cell unreachable
                }
            }
        }
        return false;
    }
}

import java.io.PrintWriter;
import java.io.Scanner;
import java.util.Arrays;

/**
 * Entry point of the application.
