/**
 * Core logic for validating a grid that contains the characters
 * {@code 'B'}, {@code 'G'} and empty cells.
 *
 * <p>The algorithm consists of two phases:
 * <ol>
 *   <li>Every {@code 'B'} must be able to “convert’’ its neighbours
 *       (replace them with ‘#’), without ever touching a {@code 'G'}</li>
 *   <li>Every {@code 'G'} must be able to reach the bottom‑right cell
 *       moving only through cells that are not blocked.</li>
 * </ol>
 * If any validation fails the answer for the current test case is
 * {@code "No"}, otherwise it is {@code "Yes"}.
 */
class GridValidator {

    /** Symbol used to mark a cell that has been processed by a {@code 'B'} */
    private static final char BLOCKED = '#';

    /** Directions used for neighbour traversal */
    private static final int[][] DIRECTIONS = {
            {-1, 0}, {1, 0}, {0, -1}, {0, 1}
    };

    /** Grid representation */
    private char[][] grid;

    /** Size of the grid */
    private int rows;
    private int columns;

    /**
     * Solves a single test case.
     *
     * @param testNumber the test case number (1‑based, only used for debugging)
     * @param scanner    scanner that reads the input
     * @param out        writer that receives the answer
     */
    public void solve(int testNumber, Scanner scanner, PrintWriter out) {
        readGrid(scanner);
        if (!processAllBs()) {
            out.println("No");
            return;
        }
        if (!processAllGs()) {
            out.println("No");
            return;
        }
        out.println("Yes");
    }

    /** Reads the grid dimensions and the grid itself from the scanner. */
    private void readGrid(Scanner scanner) {
        rows = scanner.nextInt();
        columns = scanner.nextInt();
        grid = new char[rows];
        for (int i = 0; i < rows; i++) {
            grid[i] = scanner.next().toCharArray();
        }
    }

    /** Attempts to convert every ‘B’ cell according to the problem rules. */
    private boolean processAllBs() {
        boolean[][] visited = new boolean[rows][columns];
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < columns; j++) {
                if (grid[i][j] == 'B' && !convertFrom(i, j, visited)) {
                    return false; // conversion failed for this ‘B’
                }
            }
        }
        return true;
    }

    /**
     * Recursively converts neighbours of a ‘B’ cell.
     *
     * <p>The conversion is allowed only if:
     * <ul>
     *   <li>the neighbour is not a ‘G’,
     *   <li>the neighbour can itself be converted (recursively),
     *   <li>the neighbour is replaced by ‘#’ after successful conversion.
     * </ul>
     *
     * @param r row index of the current cell
     * @param c column index of the current cell
     * @param visited matrix that tracks already processed cells
     * @return {@code true} if the whole connected component can be converted,
     *         {@code false} otherwise.
     */
    private boolean convertFrom(int r, int c, boolean[][] visited) {
        if (visited[r][c]) {
            return true;
        }
        visited[r][c] = true;

        // Check all four neighbours
        for (int[] dir : DIRECTIONS) {
            int nr = r + dir[0];
            int nc = c + dir[1];

            if (!isInside(nr, nc)) {
                continue;
            }

            char neighbour = grid[nr][nc];
            if (neighbour == 'G') {
                return false; // a 'G' blocks conversion
            }
            if (neighbour == 'B') {
                if (!convertFrom(nr, nc, visited)) {
                    return false; // conversion of a neighbouring 'B' failed
                }
            }
            // Mark the neighbour as processed (blocked) after successful check
            grid[nr][nc] = BLOCKED;
        }
        return true;
    }

    /** Checks whether all ‘G’ cells can reach the bottom‑right corner. */
    private boolean processAllGs() {
        boolean[][] visited = new boolean[rows][columns];
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < columns; j++) {
                if (grid[i][j] == 'G' && !canReachBottomRight(i, j, visited)) {
                    return false; // a ‘G’ cannot reach the destination
                }
            }
        }
        return true;
    }

    /**
     * Depth‑first search that determines if the cell (r,c) can reach the
     * bottom‑right corner while avoiding already processed cells.
     *
     * @param r row index of the current cell
     * @param c column index of the current cell
     * @param visited matrix used to detect cycles
     * @return {@code true} if a path to the destination exists,
     *         {@code false} otherwise.
     */
    private boolean canReachBottomRight(int r, int c, boolean[][] visited) {
        if (!isInside(r, c)) {
            return false;
        }
        if (grid[r][c] == BLOCKED) {
            return false;
        }
        if (r == rows - 1 && c == columns - 1) {
            return true; // reached destination
        }
        if (visited[r][c]) {
            return false; // cycle detection
        }

        visited[r][c] = true;

        // Explore all four directions
        for (int[] dir : DIRECTIONS) {
            int nr = r + dir[0];
            int nc = c + dir[1];
            if (canReachBottomRight(nr, nc, visited)) {
                return true;
            }
        }
        return false;
    }

    /** Helper that checks whether a coordinate lies inside the grid. */
    private boolean isInside(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < columns;
    }
}

import java.io.*;
import java.util.*;

public class Task4 {

    /* -------------------------------------------------------------
     *  Small immutable helpers
     * ------------------------------------------------------------- */
    private static final class Position {
        final int row;
        final int col;

        Position(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }

    private static final class Direction {
        final int dr;
        final int dc;

        Direction(int dr, int dc) {
            this.dr = dr;
            this.dc = dc;
        }

        Position apply(Position p) {
            return new Position(p.row + dr, p.col + dc);
        }
    }

    // Four orthogonal directions: up, down, left, right
    private static final Direction[] NEIGHBORS = {
            new Direction(-1, 0),
            new Direction(1, 0),
            new Direction(0, -1),
            new Direction(0, 1)
    };

    /* -------------------------------------------------------------
     *  Entry point
     * ------------------------------------------------------------- */
    public static void main(String[] args) throws IOException {
        // try‑with‑resources guarantees proper closing of streams
        try (BufferedReader reader = new BufferedReader(
                new InputStreamReader(System.in));
             PrintWriter writer = new PrintWriter(System.out)) {

            int t = Integer.parseInt(reader.readLine());
            for (int testCase = 0; testCase < t; testCase++) {
                solveOneCase(reader, writer, testCase);
            }
        }
    }

    /* -------------------------------------------------------------
     *  Solves a single test case
     * ------------------------------------------------------------- */
    private static void solveOneCase(BufferedReader reader,
                                     PrintWriter writer,
                                     int testCaseIdx) throws IOException {
        StringTokenizer tokenizer = new StringTokenizer(reader.readLine());
        int n = Integer.parseInt(tokenizer.nextToken());
        int m = Integer.parseInt(tokenizer.nextToken());

        char[][] map = readMap(reader, n, m);

        // 1️⃣  Validate the placement of every 'B'
        if (!isBConfigurationValid(map)) {
            writer.println("No");
            return;
        }

        // 2️⃣  Propagate reachability from the bottom‑right corner
        boolean[][] canExit = computeReachableFromBottomRight(map);

        // 3️⃣  Ensure every 'G' can reach the exit
        if (hasGreenWithoutExit(map, canExit)) {
            writer.println("No");
        } else {
            writer.println("Yes");
        }
    }

    /* -------------------------------------------------------------
     *  Input helpers
     * ------------------------------------------------------------- */
    private static char[][] readMap(BufferedReader reader, int n, int m) throws IOException {
        char[][] map = new char[n][];
        for (int i = 0; i < n; i++) {
            String line = reader.readLine();
            map[i] = line.toCharArray();         // store the raw characters
        }
        return map;
    }

    /* -------------------------------------------------------------
     *  Validation of 'B' cells
     * ------------------------------------------------------------- */
    private static boolean isBConfigurationValid(char[][] map) {
        int rows = map.length;
        int cols = map[0].length;

        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (map[r][c] == 'B' && !hasOnlyEmptyOrBoundaryNeighbors(map, r, c)) {
                    return false;
                }
            }
        }
        return true;
    }

    private static boolean hasOnlyEmptyOrBoundaryNeighbors(char[][] map, int r, int c) {
        for (Direction dir : NEIGHBORS) {
            int nr = r + dir.dr;
            int nc = c + dir.dc;

            // Outside the grid → considered acceptable
            if (nr < 0 || nr >= map.length || nc < 0 || nc >= map[0].length) {
                continue;
            }

            char neighbour = map[nr][nc];
            if (neighbour == 'G') {
                // A wall next to a green is forbidden
                return false;
            }
            if (neighbour == '.') {
                // Original logic: temporarily turn '.' into a wall
                map[nr][nc] = '#';
            }
        }
        return true;
    }

    /* -------------------------------------------------------------
     *  Reachability analysis from the exit cell (bottom‑right)
     * ------------------------------------------------------------- */
    private static boolean[][] computeReachableFromBottomRight(char[][] map) {
        int rows = map.length;
        int cols = map[0].length;

        boolean[][] reachable = new boolean[rows][cols];

        // If the exit itself is a wall, nothing can be reached
        if (map[rows - 1][cols - 1] == '#') {
            return reachable;
        }

        Deque<Position> stack = new ArrayDeque<>();
        stack.push(new Position(rows - 1, cols - 1));
        reachable[rows - 1][cols - 1] = true;

        while (!stack.isEmpty()) {
            Position cur = stack.pop();
            for (Direction dir : NEIGHBORS) {
                Position next = dir.apply(cur);
                if (tryVisit(map, reachable, next)) {
                    stack.push(next);
                }
            }
        }
        return reachable;
    }

    private static boolean tryVisit(char[][] map,
                                    boolean[][] reachable,
                                    Position p) {
        int r = p.row;
        int c = p.col;

        // Bounds check
        if (r < 0 || r >= map.length || c < 0 || c >= map[0].length) {
            return false;
        }

        // Already processed or blocked by a wall?
        if (reachable[r][c] || map[r][c] == '#') {
            return false;
        }

        reachable[r][c] = true;
        return true;
    }

    /* -------------------------------------------------------------
     *  Final correctness check – every 'G' must be reachable
     * ------------------------------------------------------------- */
    private static boolean hasGreenWithoutExit(char[][] map,
                                               boolean[][] reachable) {
        for (int r = 0; r < map.length; r++) {
            for (int c = 0; c < map[0].length; c++) {
                if (map[r][c] == 'G' && !reachable[r][c]) {
                    return true;   // found a green that cannot exit
                }
            }
        }
        return false;            // all greens can exit
    }
}

import java.util.ArrayDeque;
import java.util.Deque;
import java.util.Scanner;

/**
 * Refactored version of the original program.
 * The logic is unchanged – it reads multiple test cases,
 * analyses a grid containing 'B' (bombs), 'G' (goals), '.' (empty)
 * and '#' (walls) and prints “Yes” or “No” for each case.
 *
 * The code is split into small, well‑named methods and uses
 * final/static constants to improve readability and maintainability.
 */
public class Main {

    /** Four possible movement directions (right, left, down, up). */
    private static final int[][] DIR = {{0, 1}, {0, -1}, {1, 0}, {-1, 0}};

    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            int testCases = scanner.nextInt();

            for (int caseIdx = 0; caseIdx < testCases; ++caseIdx) {
                solveSingleTestCase(scanner);
            }
        }
    }

    /**
     * Reads one test case, processes the grid and prints the answer.
     */
    private static void solveSingleTestCase(Scanner scanner) {
        int n = scanner.nextInt();
        int m = scanner.nextInt();

        // read the whole grid as an array of characters
        char[][] grid = readGrid(scanner, n, m);

        // count how many 'G' cells are present
        int goalCount = countGoals(grid, n, m);

        // analyse bombs and possibly block neighbouring empty cells
        boolean unsolvableDueToAdjacency = analyseBombs(grid, n, m);

        // if the exit cell (bottom‑right) is already a wall we cannot start a BFS
        boolean exitBlocked = grid[n - 1][m - 1] == '#';

        if (unsolvableDueToAdjacency || exitBlocked) {
            // In this situation the answer is “Yes” only when there are no goals left.
            System.out.println(goalCount == 0 ? "Yes" : "No");
            return;
        }

        // otherwise try to reach all goals from the exit cell
        int remainingGoals = bfsFromExit(grid, n, m);
        System.out.println(remainingGoals == 0 ? "Yes" : "No");
    }

    /**
     * Reads {@code n} strings, each of length {@code m}, and stores the
     * characters into a 2‑dimensional array.
     */
    private static char[][] readGrid(Scanner scanner, int n, int m) {
        char[][] grid = new char[n][m];
        for (int i = 0; i < n; ++i) {
            String line = scanner.next();
            for (int j = 0; j < m; ++j) {
                grid[i][j] = line.charAt(j);
                if (grid[i][j] == 'G') {
                    // counted later in countGoals()
                }
            }
        }
        return grid;
    }

    /**
     * Scans the grid for bombs ('B'). For each bomb the neighbouring empty
     * cells ('.') are turned into walls('#'). If a bomb is adjacent to a
     * goal ('G') the method returns {@code true}.
     *
     * @return {@code true} if any bomb is directly next to a goal.
     */
    private static boolean analyseBombs(char[][] grid, int n, int m) {
        for (int i = 0; i < n; ++i) {
            for (int j = 0; j < m; ++j) {
                if (grid[i][j] == 'B') {
                    for (int[] d : DIR) {
                        int ni = i + d[0];
                        int nj = j + d[1];
                        if (!inside(ni, nj, n, m)) {
                            continue;
                        }
                        char neighbour = grid[ni][nj];
                        if (neighbour == 'G') {
                            return true; // bomb touching a goal → unsolvable
                        }
                        if (neighbour == '.') {
                            grid[ni][nj] = '#'; // block the empty cell
                        }
                    }
                }
            }
        }
        return false;
    }

    /** Simple bounds check for array indices. */
    private static boolean inside(int x, int y, int n, int m) {
        return x >= 0 && x < n && y >= 0 && y < m;
    }

    /** Counts the number of 'G' cells in the grid. */
    private static int countGoals(char[][] grid, int n, int m) {
        int count = 0;
        for (int i = 0; i < n; ++i) {
            for (int j = 0; j < m; ++j) {
                if (grid[i][j] == 'G') {
                    ++count;
                }
            }
        }
        return count;
    }

    /**
     * Performs a breadth‑first search starting from the bottom‑right cell
     * (n‑1, m‑1). Every traversable cell is marked as visited by turning it
     * into '#'. Whenever a 'G' cell is encountered it is counted as visited
     * and the global goal counter is decremented.
     *
     * @return the number of 'G' cells that remain unvisited after the BFS.
     */
    private static int bfsFromExit(char[][] grid, int n, int m) {
        Deque<Node> queue = new ArrayDeque<>();
        queue.add(new Node(n - 1, m - 1));

        // Mark the start cell as visited
        grid[n - 1][m - 1] = '#';

        while (!queue.isEmpty()) {
            Node cur = queue.poll();

            for (int[] d : DIR) {
                int nx = cur.x + d[0];
                int ny = cur.y + d[1];
                if (!inside(nx, ny, n, m) || grid[nx][ny] == '#') {
                    continue;
                }
                if (grid[nx][ny] == 'G') {
                    // we have reached a goal – consider it visited
                    // (the outer method keeps a separate counter, so we just continue)
                }
                grid[nx][ny] = '#'; // mark as visited
                queue.add(new Node(nx, ny));
            }
        }

        // After BFS we recount remaining goals.
        // This is a straightforward way to keep the original semantics
        // without exposing the counter to the BFS routine.
        int remaining = 0;
        for (int i = 0; i < n; ++i) {
            for (int j = 0; j < m; ++j) {
                if (grid[i][j] == 'G') {
                    ++remaining;
                }
            }
        }
        return remaining;
    }

    /** Simple container class for a grid coordinate. */
    private static final class Node {
        final int x;
        final int y;

        Node(int x, int y) {
            this.x = x;
            this.y = y;
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

/**
 * Reads multiple grids and determines whether every 'G' can reach the bottom‑right
 * corner without stepping on a blocked cell.
 */
public final class GridPathChecker {

    /** Private constructor – utility class does not need instances. */
    private GridPathChecker() {
    }

    public static void main(String[] args) throws IOException {
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in))) {
            int numberOfDatasets = Integer.parseInt(br.readLine());

            for (int dataset = 0; dataset < numberOfDatasets; dataset++) {
                Result result = processSingleDataset(br);
                System.out.println(result == Result.YES ? "Yes" : "No");
            }
        }
    }

    /**
     * Parses one dataset, checks the reachability of every 'G' and returns the result.
     */
    private static Result processSingleDataset(BufferedReader br) throws IOException {
        StringTokenizer st = new StringTokenizer(br.readLine(), " \t");
        int rows = Integer.parseInt(st.nextToken());
        int cols = Integer.parseInt(st.nextToken());

        char[][] grid = readGrid(br, rows);
        boolean[][] blocked = computeBlockedCells(grid, rows, cols);

        boolean allGoodHavePath = true;
        for (int r = 0; r < rows && allGoodHavePath; r++) {
            for (int c = 0; c < cols && allGoodHavePath; c++) {
                if (grid[r][c] == 'G') {
                    allGoodHavePath = hasPathToBottomRight(grid, blocked, r, c);
                }
            }
        }
        return allGoodHavePath ? Result.YES : Result.NO;
    }

    /** Reads the grid characters from the input stream. */
    private static char[][] readGrid(BufferedReader br, int rows) throws IOException {
        char[][] grid = new char[rows][];
        for (int r = 0; r < rows; r++) {
            grid[r] = br.readLine().toCharArray();
        }
        return grid;
    }

    /**
     * Marks cells that are blocked directly or indirectly by any 'B'.
     * <ul>
     *   <li> cell containing 'B' itself,</li>
     *   <li> its orthogonal neighbours,</li>
     * </ul>
     */
    private static boolean[][] computeBlockedCells(char[][] grid, int rows, int cols) {
        boolean[][] blocked = new boolean[rows][cols];
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == 'B') {
                    blockCellAndNeighbours(blocked, r, c, rows, cols);
                }
            }
        }
        return blocked;
    }

    /** Helper that marks a cell and its four orthogonal neighbours (if inside bounds). */
    private static void blockCellAndNeighbours(boolean[][] blocked, int r, int c,
                                               int rows, int cols) {
        blocked[r][c] = true;
        if (r > 0)     blocked[r - 1][c] = true;
        if (c > 0)     blocked[r][c - 1] = true;
        if (r < rows - 1) blocked[r + 1][c] = true;
        if (c < cols - 1) blocked[r][c + 1] = true;
    }

    /**
     * Determines whether there exists a path from the given start cell to the
     * bottom‑right corner that avoids blocked cells.
     * Returns {@code true} if a path exists, {@code false} otherwise.
     */
    private static boolean hasPathToBottomRight(char[][] grid,
                                                boolean[][] blocked,
                                                int startRow,
                                                int startCol) {
        return dfs(grid, blocked, startRow, startCol, rows = grid.length,
                                                          cols = grid[0].length);
    }

    /**
     * Depth‑first search that explores reachable cells.
     *
     * @return {@code true} if the bottom‑right corner can be reached, {@code false} otherwise.
     */
    private static boolean dfs(char[][] grid,
                               boolean[][] blocked,
                               int r,
                               int c,
                               int rows,
                               int cols) {
        if (r < 0 || c < 0 || r >= rows || c >= cols) {
            return false;
        }
        if (visited[r][c]) {
            return false;
        }
        if (blocked[r][c]) {
            return false;
        }

        visited[r][c] = true;

        // Reached the destination?
        if (r == rows - 1 && c == cols - 1) {
            return true;
        }

        return dfs(grid, blocked, r - 1, c, rows, cols) ||
               dfs(grid, blocked, r + 1, c, rows, cols) ||
               dfs(grid, blocked, r, c - 1, rows, cols) ||
               dfs(grid, blocked, r, c + 1, rows, cols);
    }

    /** Holds the constants used for output. */
    private enum Result {
        YES, NO;
    }

    /** Visited matrix – reused for every DFS call (cleared after each use). */
    private static final boolean[][] VISITED = new boolean[1000][1000]; // assumed max size
}

import java.util.LinkedList;
import java.util.Queue;
import java.util.Scanner;

/**
 * Solution for the “walls spreading” problem.
 * The program reads a grid, propagates walls outward from blocked cells,
 * and decides whether all good cells can be reached from the bottom‑right
 * corner without stepping on a wall.
 */
public class D1365 {

    /* --------------------------------------------------------------------- */
    /*                         Constant definitions                         */
    /* --------------------------------------------------------------------- */
    private static final int EMPTY  = 0;   // '.'  – free cell
    private static final int WALL   = 1;   // '#'  – original wall
    private static final int GOOD   = 2;   // 'G'  – good cell that must be reached
    private static final int BLOCKED = 3;  // any other character – treated as a blocker

    /** Four‑direction movement vectors (right, left, down, up). */
    private static final int[][] DIRECTIONS = {
            { 1,  0},   // down
            { -1, 0},   // up
            { 0,  1},   // right
            { 0, -1}    // left
    };

    /* --------------------------------------------------------------------- */
    /*                           Helper types                                 */
    /* --------------------------------------------------------------------- */
    /** Simple container for BFS result (count of reachable good cells,
     *  and flag indicating whether a blocked cell was encountered). */
    private static final class BfsResult {
        final int reachableGood;
        final boolean blockedEncountered;

        BfsResult(int reachableGood, boolean blockedEncountered) {
            this.reachableGood = reachableGood;
            this.blockedEncountered = blockedEncountered;
        }
    }

    /* --------------------------------------------------------------------- */
    /*                            Core logic methods                           */
    /* --------------------------------------------------------------------- */

    /** Translates a character from the input into the internal numeric code. */
    private static int toCell(char ch) {
        return switch (ch) {
            case '.' -> EMPTY;
            case '#' -> WALL;
            case 'G' -> GOOD;
            default  -> BLOCKED;
        };
    }

    /** Marks every empty cell that is orthogonal neighbour of a blocked cell
     *  as a wall, thereby spreading walls outward. */
    private static void propagateBlocks(int[][] grid, int rows, int cols) {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == BLOCKED) {
                    for (int[] d : DIRECTIONS) {
                        int nr = r + d[0];
                        int nc = c + d[1];
                        if (isInside(nr, nc, rows, cols) && grid[nr][nc] == EMPTY) {
                            grid[nr][nc] = WALL;
                        }
                    }
                }
            }
        }
    }

    /** Simple bound check for matrix coordinates. */
    private static boolean isInside(int x, int y, int rows, int cols) {
        return x >= 0 && x < rows && y >= 0 && y < cols;
    }

    /** Breadth‑first search from the exit (bottom‑right) counting how many
     *  good cells are reachable before hitting a blocked cell. */
    private static BfsResult bfsFromExit(int[][] grid, int startR, int startC,
                                         int rows, int cols) {
        Queue<int[]> queue = new LinkedList<>();
        boolean[][] visited = new boolean[rows][cols];
        int reachableGood = 0;
        boolean blockedMet = false;

        queue.add(new int[]{startR, startC});
        visited[startR][startC] = true;

        while (!queue.isEmpty()) {
            int[] cur = queue.poll();
            for (int[] d : DIRECTIONS) {
                int nr = cur[0] + d[0];
                int nc = cur[1] + d[1];
                if (!isInside(nr, nc, rows, cols) || visited[nr][nc]) {
                    continue;
                }
                int cell = grid[nr][nc];
                if (cell == WALL) {
                    continue;                     // cannot pass through walls
                }
                if (cell == BLOCKED) {
                    blockedMet = true;            // hitting a blocker stops expansion
                    queue.clear();                // abort further BFS
                    break;
                }
                if (cell == GOOD) {
                    reachableGood++;
                }
                queue.add(new int[]{nr, nc});
                visited[nr][nc] = true;
            }
        }
        return new BfsResult(reachableGood, blockedMet);
    }

    /* --------------------------------------------------------------------- */
    /*                               Main entry                               */
    /* --------------------------------------------------------------------- */
    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            int testCases = scanner.nextInt();

            while (testCases-- > 0) {
                int n = scanner.nextInt();          // rows
                int m = scanner.nextInt();          // columns

                int[][] grid = new int[n][m];
                int goodCount = 0;                    // total number of 'G' cells

                // ---- read the grid -------------------------------------------------
                for (int r = 0; r < n; r++) {
                    String row = scanner.next();      // each row is a token without spaces
                    for (int c = 0; c < m; c++) {
                        int cellValue = toCell(row.charAt(c));
                        grid[r][c] = cellValue;
                        if (cellValue == GOOD) {
                            goodCount++;
                        }
                    }
                }

                // ---- spread walls from blocked cells -------------------------------
                propagateBlocks(grid, n, m);

                // ---- decide answer -------------------------------------------------
                // If the exit cell itself is a wall, the answer depends only on
                // whether there are any good cells to rescue.
                if (grid[n - 1][m - 1] == WALL) {
                    System.out.println(goodCount == 0 ? "Yes" : "No");
                    continue;
                }

                // Otherwise explore reachable area from the exit.
                BfsResult result = bfsFromExit(grid, n - 1, m - 1, n, m);
                if (result.blockedEncountered) {
                    System.out.println("No");
                } else if (result.reachableGood == goodCount) {
                    System.out.println("Yes");
                } else {
                    System.out.println("No");
                }
            }
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Refactored version of the original program.
 *
 * <p>
 *   • Input handling is isolated in {@link InputReader}.
 *   • Grid processing is performed by {@code Solver} methods.
 *   • All mutable static state has been eliminated – the DFS returns the number of
 *     reachable 'G' cells directly.
 *   • Constants and helper methods are named descriptively.
 *   • Unused imports and helper classes (e.g. {@code Debugger}, {@code Pair}) have been
 *     removed to keep the code focused.
 * </p>
 */
public class Main {

    /** Directions used during DFS – up, down, left, right. */
    private static final int[][] DIRS = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};

    /** --------------------------------------------------------------------- */
    /**                         Core algorithm                               */
    /** --------------------------------------------------------------------- */

    /** Checks whether the given cell coordinates are inside the grid. */
    private static boolean isInBounds(int i, int j, int rows, int cols) {
        return i >= 0 && i < rows && j >= 0 && j < cols;
    }

    /**
     * Depth‑first search that starts from {@code startRow},{@code startCol}.
     *
     * @return the number of 'G' cells that can be reached from the start cell
     *         without stepping on '#' or adjacent to a 'B'.
     */
    private static int dfs(int startRow, int startCol,
                           boolean[][] visited,
                           char[][] grid) {
        if (grid[startRow][startCol] == '#') {
            return 0;
        }
        if (adjacentContainsB(startRow, startCol, grid)) {
            return 0;
        }

        int gathered = 0;
        if (grid[startRow][startCol] == 'G') {
            gathered = 1;
        }
        visited[startRow][startCol] = true;

        for (int[] dir : DIRS) {
            int ni = startRow + dir[0];
            int nj = startCol + dir[1];
            if (isInBounds(ni, nj, grid.length, grid[0].length)
                    && !visited[ni][nj]) {
                gathered += dfs(ni, nj, visited, grid);
            }
        }
        return gathered;
    }

    /** Returns {@code true} if any orthogonal neighbour of (i,j) holds a 'B'. */
    private static boolean adjacentContainsB(int i, int j, char[][] grid) {
        int rows = grid.length;
        int cols = grid[0].length;
        for (int[] d : DIRS) {
            int ni = i + d[0];
            int nj = j + d[1];
            if (isInBounds(ni, nj, rows, cols) && grid[ni][nj] == 'B') {
                return true;
            }
        }
        return false;
    }

    /** --------------------------------------------------------------------- */
    /**                         Input handling                                 */
    /** --------------------------------------------------------------------- */

    /**
     * Simple fast scanner based on the original implementation.
     * It is kept private because it is only used inside {@link Main}.
     */
    private static final class InputReader {
        private final InputStream stream;
        private final byte[] buffer = new byte[8192];
        private int currentChar;
        private int charsRead;
        private SpaceCharFilter filter;

        public InputReader(InputStream stream) {
            this.stream = stream;
        }

        private int nextChar() {
            if (charsRead == -1) {
                throw new InputMismatchException();
            }
            if (currentChar >= charsRead) {
                currentChar = 0;
                try {
                    charsRead = stream.read(buffer);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (charsRead <= 0) {
                    return -1;
                }
            }
            return buffer[currentChar++];
        }

        private boolean isSpaceChar(int c) {
            if (filter != null) {
                return filter.isSpaceChar(c);
            }
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        public int nextInt() {
            int c = nextChar();
            while (isSpaceChar(c)) {
                c = nextChar();
            }
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = nextChar();
            }
            int result = 0;
            do {
                if (c < '0' || c > '9') {
                    throw new InputMismatchException();
                }
                result = result * 10 + (c - '0');
                c = nextChar();
            } while (!isSpaceChar(c));
            return result * sign;
        }

        public long nextLong() {
            int c = nextChar();
            while (isSpaceChar(c)) {
                c = nextChar();
            }
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = nextChar();
            }
            long result = 0;
            do {
                if (c < '0' || c > '9') {
                    throw new InputMismatchException();
                }
                result = result * 10 + (c - '0');
                c = nextChar();
            } while (!isSpaceChar(c));
            return result * sign;
        }

        public String readString() {
            int c = nextChar();
            while (isSpaceChar(c)) {
                c = nextChar();
            }
            StringBuilder sb = new StringBuilder();
            do {
                sb.appendCodePoint(c);
                c = nextChar();
            } while (!isSpaceChar(c));
            return sb.toString();
        }

        public String nextLine() {
            int c = nextChar();
            while (isSpaceChar(c)) {
                c = nextChar();
            }
            StringBuilder sb = new StringBuilder();
            do {
                sb.appendCodePoint(c);
                c = nextChar();
            } while (!isEndOfLine(c));
            return sb.toString();
        }

        private boolean isEndOfLine(int c) {
            return c == '\n' || c == '\r' || c == -1;
        }
    }
}

import java.util.Scanner;

/**
 * Refactored solution for problem CF1365D.
 *
 * <p>This version improves readability, separates concerns, and uses meaningful
 * names while preserving the original algorithmic behaviour.</p>
 */
public class CF1365D {

    // -------------------------------------------------------------------------
    // Character constants – make the code self‑documenting
    // -------------------------------------------------------------------------
    private static final char BOSS   = 'B';
    private static final char GOLD   = 'G';
    private static final char EMPTY  = '.';
    private static final char WALL   = '#';
    private static final char VISITED = '$';

    /** Global flag used by the DFS routine to signal an invalid configuration. */
    private boolean possible;

    // -------------------------------------------------------------------------
    // Entry point
    // -------------------------------------------------------------------------
    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            int testCases = scanner.nextInt();

            for (int caseIdx = 1; caseIdx <= testCases; caseIdx++) {
                int rows = scanner.nextInt();
                int cols = scanner.nextInt();

                char[][] maze = readMaze(scanner, rows, cols);

                // 1. Turn every empty neighbour of a boss into a wall.
                fillNeighbourhoodOfBoss(maze);

                // 2. The original code always starts with a hopeful assumption.
                possible = true;

                // 3. If the exit cell (bottom‑right) is still empty, run DFS from it.
                if (maze[rows - 1][cols - 1] == EMPTY) {
                    dfs(rows - 1, cols - 1, maze);
                }

                // 4. Finally, scan the whole maze for any remaining gold pieces.
                scanForGold(maze);

                System.out.println(possible ? "yes" : "No");
            }
        }
    }

    // -------------------------------------------------------------------------
    // Input handling
    // -------------------------------------------------------------------------
    /** Reads the maze from the scanner. */
    private static char[][] readMaze(Scanner scanner, int rows, int cols) {
        char[][] maze = new char[rows][];
        for (int r = 0; r < rows; r++) {
            maze[r] = scanner.next().toCharArray();
        }
        return maze;
    }

    // -------------------------------------------------------------------------
    // Core algorithm pieces
    // -------------------------------------------------------------------------
    /** Places a wall on every empty cell that touches a boss. */
    private static void fillNeighbourhoodOfBoss(char[][] maze) {
        for (int r = 0; r < maze.length; r++) {
            for (int c = 0; c < maze[r].length; c++) {
                if (maze[r][c] == BOSS) {
                    placeWallIfEmpty(maze, r, c - 1);
                    placeWallIfEmpty(maze, r, c + 1);
                    placeWallIfEmpty(maze, r - 1, c);
                    placeWallIfEmpty(maze, r + 1, c);
                }
            }
        }
    }

    /** Places a wall at (r,c) if the cell exists and currently holds EMPTY. */
    private static void placeWallIfEmpty(char[][] maze, int r, int c) {
        if (isInBounds(maze, r, c) && maze[r][c] == EMPTY) {
            maze[r][c] = WALL;
        }
    }

    /** Simple bounds check for a 2‑D char array. */
    private static boolean isInBounds(char[][] maze, int r, int c) {
        return r >= 0 && r < maze.length && c >= 0 && c < maze[r].length;
    }

    /**
     * Depth‑first search that marks reachable empty cells with {@code VISITED}.
     * The search updates the {@code possible} flag when a boss is encountered.
     */
    private void dfs(int row, int col, char[][] maze) {
        // Out‑of‑bounds or already processed cells are ignored.
        if (!isInBounds(maze, row, col)) {
            return;
        }

        char cur = maze[row][col];
        if (cur == WALL || cur == VISITED || cur == BOSS) {
            // Hitting a boss makes the whole scenario invalid.
            if (cur == BOSS) {
                possible = false;
            }
            return;
        }

        // Mark the current empty cell as visited.
        maze[row][col] = VISITED;

        // Explore the four orthogonal neighbours.
        dfs(row - 1, col, maze); // up
        dfs(row + 1, col, maze); // down
        dfs(row, col - 1, maze); // left
        dfs(row, col + 1, maze); // right

        // After unwinding the recursion the cell may have transformed into a boss,
        // mirroring the original post‑recursion check.
        if (maze[row][col] == BOSS) {
            possible = false;
        }
    }

    /**
     * Scans the maze from bottom‑right to top‑left looking for any remaining gold.
     * If at least one gold piece is found, {@code possible} is set to {@code false}.
     */
    private void scanForGold(char[][] maze) {
        for (int r = maze.length - 1; r >= 0; r--) {
            for (int c = maze[r].length - 1; c >= 0; c--) {
                if (maze[r][c] == GOLD) {
                    possible = false;
                    return;
                }
            }
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * R648Q4 – checks whether a grid satisfies two constraints:
 *   1. No 'B' (barrier) is directly adjacent (up, down, left, right) to a 'G' (goal).
 *      Adjacent non‑'B' cells are turned into a wall '#'.
 *   2. Every 'G' can reach the bottom‑right cell (rows‑1, cols‑1) moving only
 *      through non‑'#' cells.
 *
 * The program is deliberately written for clarity, with small, focused
 * methods and meaningful naming.
 */
public class R648Q4 {

    /** Directions used for neighbour checks (up, down, left, right). */
    private static final int[][] DIRS = {
            {-1, 0}, {1, 0}, {0, -1}, {0, 1}
    };

    /** Fast input reader. */
    private static final class FastScanner {
        private final BufferedReader br = new BufferedReader(
                new InputStreamReader(System.in));
        private StringTokenizer st = new StringTokenizer("");

        /** Returns the next token from the input stream. */
        private String next() {
            while (!st.hasMoreTokens()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    throw new UncheckedIOException(e);
                }
            }
            return st.nextToken();
        }

        /** Reads an {@code int}. */
        private int nextInt() {
            return Integer.parseInt(next());
        }
    }

    /** Entry point – parses input and processes each test case. */
    public static void main(String[] args) {
        FastScanner fs = new FastScanner();
        PrintWriter out = new PrintWriter(System.out);

        int testCases = fs.nextInt();

        for (int tc = 1; tc <= testCases; tc++) {
            int rows = fs.nextInt();
            int cols = fs.nextInt();

            char[][] grid = readGrid(fs, rows, cols);

            if (!isGridValid(grid, rows, cols)) {
                out.println("No");
                continue;
            }

            if (!hasPathFromAllGoals(grid, rows, cols)) {
                out.println("No");
                continue;
            }

            out.println("Yes");
        }

        out.flush();
    }

    /** Reads {@code rows} lines of length {@code cols} from the scanner. */
    private static char[][] readGrid(FastScanner fs, int rows, int cols) {
        char[][] grid = new char[rows][];
        for (int r = 0; r < rows; r++) {
            grid[r] = fs.next().toCharArray();
        }
        return grid;
    }

    /**
     * Returns {@code true} if the grid respects the adjacency rule:
     * <ul>
     *   <li>A 'B' must not be adjacent to a 'G'.</li>
     *   <li>All cells adjacent to a 'B' that are not themselves 'B' become '#'.</li>
     * </ul>
     * If a violation is found the method returns {@code false}.
     */
    private static boolean isGridValid(char[][] grid, int rows, int cols) {
        boolean foundViolation = false;

        for (int r = 0; r < rows && !foundViolation; r++) {
            for (int c = 0; c < cols && !foundViolation; c++) {
                if (grid[r][c] == 'B') {
                    foundViolation = checkBarrierAdjacency(grid, rows, cols, r, c);
                }
            }
        }

        // If a violation was found we already know the answer is "No".
        // Otherwise we need to continue with the connectivity test.
        return !foundViolation;
    }

    /**
     * Checks the four neighbours of a barrier cell {@code (r,c)}.
     * Turns any non‑'B' neighbour that is not an adjacent 'G' into a wall '#'.
     * Returns {@code true} if a violation (adjacent 'G') is discovered.
     */
    private static boolean checkBarrierAdjacency(char[][] grid,
                                                  int rows,
                                                  int cols,
                                                  int r,
                                                  int c) {
        for (int[] d : DIRS) {
            int nr = r + d[0];
            int nc = c + d[1];

            if (!isInside(grid, nr, nc)) {
                continue;
            }

            char neighbour = grid[nr][nc];

            if (neighbour == 'G') {
                // Direct adjacency between a barrier and a goal → invalid.
                return true;
            }

            // If the neighbour is not a barrier, replace it with a wall.
            if (neighbour != 'B') {
                grid[nr][nc] = '#';
            }
        }
        return false; // No adjacent goal found.
    }

    /** Simple bounds check used by {@link #checkBarrierAdjacency}. */
    private static boolean isInside(char[][] grid, int r, int c) {
        return r >= 0 && r < grid.length && c >= 0 && c < grid[0].length;
    }

    /**
     * Verifies that every goal ('G') cell can reach the bottom‑right
     * corner (rows‑1, cols‑1) moving only through non‑'#' cells.
     *
     * @return {@code true} if all goals are reachable, {@code false} otherwise.
     */
    private static boolean hasPathFromAllGoals(char[][] grid,
                                               int rows,
                                               int cols) {
        boolean[][] visited = new boolean[rows][cols];

        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == 'G' && !visited[r][c]) {
                    if (!bfsFromGoal(grid, rows, cols, r, c, visited)) {
                        return false;
                    }
                }
            }
        }
        return true;
    }

    /**
     * Breadth‑first search starting from a given goal cell {@code (sr, sc)}.
     *
     * The method marks every visited goal cell in {@code visited} and returns
     * {@code true} if the destination (rows‑1, cols‑1) is reached.
     */
    private static boolean bfsFromGoal(char[][] grid,
                                       int rows,
                                       int cols,
                                       int sr,
                                       int sc,
                                       boolean[][] visited) {
        Queue<int[]> queue = new ArrayDeque<>();
        boolean[][] inQueueVisited = new boolean[rows][cols];

        queue.add(new int[]{sr, sc});
        inQueueVisited[sr][sc] = true;

        while (!queue.isEmpty()) {
            int[] cur = queue.poll();
            int r = cur[0];
            int c = cur[1];

            // Destination reached?
            if (r == rows - 1 && c == cols - 1) {
                return true;
            }

            // Explore all neighbours.
            for (int[] d : DIRS) {
                int nr = r + d[0];
                int nc = c + d[1];

                if (!isInside(grid, nr, nc)) {
                    continue;
                }
                if (inQueueVisited[nr][nc]) {
                    continue;
                }
                char cell = grid[nr][nc];
                if (cell == '#') {
                    continue; // Walls block movement.
                }

                boolean justVisitedGoal = cell == 'G';
                if (justVisitedGoal) {
                    visited[nr][nc] = true;
                }

                inQueueVisited[nr][nc] = true;
                queue.add(new int[]{nr, nc});
            }
        }

        return false; // Destination not reachable.
    }
}

/**
 * Refactored version of `SolveTheMaze`.
 *
 * The program reads multiple test cases, each describing a grid that contains:
 *   - '.' : empty cell
 *   - '#' : wall
 *   - 'B' : boulder
 *   - 'G' : goal
 *
 * A solution exists when every goal can be reached from the bottom‑right cell
 * (n‑1, m‑1) after temporarily blocking all empty cells that are directly
 * adjacent to a boulder.
 *
 * The refactor improves readability, reduces the use of static mutable fields,
 * isolates the algorithmic logic from I/O, and follows Java naming conventions.
 */
import java.io.*;
import java.util.*;

public class SolveTheMaze {

    /* -------------------------------------------------------------------------
     *  Fast I/O wrapper (kept compatible with the original Kattis judge)
     * ---------------------------------------------------------------------- */
    private static class FastScanner extends PrintWriter {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        FastScanner(InputStream in, PrintWriter out) {
            super(out);
            reader = new BufferedReader(new InputStreamReader(in));
        }

        FastScanner(String problemName) throws IOException {
            super(new FileWriter(problemName + ".out"));
            reader = new BufferedReader(new FileReader(problemName + ".in"));
        }

        String next() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                tokenizer = new StringTokenizer(reader.readLine());
            }
            return tokenizer.nextToken();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }

        double nextDouble() throws IOException {
            return Double.parseDouble(next());
        }

        long nextLong() throws IOException {
            return Long.parseLong(next());
        }

        /** Close the underlying streams – called from `main`. */
        @Override
        public void close() {
            super.close();
            try { reader.close(); } catch (IOException ignored) {}
        }
    }

    /* -------------------------------------------------------------------------
     *  Core solving logic – completely independent from I/O
     * ---------------------------------------------------------------------- */
    private static final int[][] DIRECTIONS = {
            {0, 1},   // right
            {1, 0},   // down
            {0, -1},  // left
            {-1, 0}   // up
    };

    /** Replace every '.' that touches a 'B' with '#'. */
    private static void blockCellsAdjacentToBoulders(char[][] grid) {
        int rows = grid.length;
        int cols = grid[0].length;

        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] != 'B') {
                    continue;
                }
                // explore the four neighbours
                for (int[] dir : DIRECTIONS) {
                    int nr = r + dir[0];
                    int nc = c + dir[1];
                    if (isInBounds(nr, nc, rows, cols) && grid[nr][nc] == '.') {
                        grid[nr][nc] = '#';
                    }
                }
            }
        }
    }

    /** Depth‑first flood fill starting from (startRow, startCol). */
    private static void floodFill(char[][] grid,
                                   boolean[][] visited,
                                   int startRow,
                                   int startCol) {
        visited[startRow][startCol] = true;
        for (int[] dir : DIRECTIONS) {
            int nr = startRow + dir[0];
            int nc = startCol + dir[1];
            if (isInBounds(nr, nc, grid.length, grid[0].length)
                    && !visited[nr][nc]
                    && grid[nr][nc] != '#') {
                floodFill(grid, visited, nr, nc);
            }
        }
    }

    /** Return true if every 'G' cell is reachable from the bottom‑right corner. */
    private static boolean allGoalsReachable(char[][] grid,
                                               boolean[][] visited) {
        int rows = grid.length;
        int cols = grid[0].length;

        // The exit may be blocked by the previous step – only continue if it is open.
        if (grid[rows - 1][cols - 1] != '#') {
            floodFill(grid, visited, rows - 1, cols - 1);
        }

        // Verify that each goal cell was visited.
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == 'G' && !visited[r][c]) {
                    return false;
                }
            }
        }
        return true;
    }

    /** Validate a single test case according to the problem rules. */
    private static String solve(char[][] grid, boolean[][] visited) {
        // 1. Block empty cells that are directly next to any boulder.
        blockCellsAdjacentToBoulders(grid);

        // 2. If any neighbour of a boulder is a goal, the instance is impossible.
        int rows = grid.length;
        int cols = grid[0].length;
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == 'B') {
                    for (int[] dir : DIRECTIONS) {
                        int nr = r + dir[0];
                        int nc = c + dir[1];
                        if (isInBounds(nr, nc, rows, cols)) {
                            if (grid[nr][nc] == 'G') {
                                return "No";
                            }
                            // The neighbour was already turned into '#', nothing else to do.
                        }
                    }
                }
            }
        }

        // 3. Ensure all goals can be reached from the exit cell.
        if (!allGoalsReachable(grid, visited)) {
            return "No";
        }
        return "Yes";
    }

    private static boolean isInBounds(int r, int c,
                                        int rows, int cols) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    /* -------------------------------------------------------------------------
     *  Entry point – handles input / output only
     * ---------------------------------------------------------------------- */
    public static void main(String[] args) throws IOException {
        FastScanner io = new FastScanner();
        int testCases = io.nextInt();

        for (int t = 0; t < testCases; t++) {
            int rows = io.nextInt();
            int cols = io.nextInt();

            char[][] grid = new char[rows][cols];
            boolean[][] visited = new boolean[rows][cols];

            for (int r = 0; r < rows; r++) {
                String line = io.next();
                for (int c = 0; c < cols; c++) {
                    grid[r][c] = line.charAt(c);
                }
            }

            String answer = solve(grid, visited);
            io.println(answer);
        }
        io.close();
    }
}

/**
 * Solves a maze‑analysis problem where we need to determine whether every good
 * (cell marked 'G') is reachable from the bottom‑right corner while no bad
 * (cell marked 'B') is reachable, after converting every empty cell ('.')
 * adjacent to a bad cell into walls ('#').
 *
 * <p>This implementation focuses on readability, maintainability and
 * separation of concerns.  The main logic is split into small, well‑named
 * methods; magic numbers are replaced by named constants; and the BFS uses
 * the modern {@link java.util.ArrayDeque} API.</p>
 */
public class Solve {

    /** Direction vectors: right, left, up, down */
    private static final int[] DY = {0, 0, -1, 1};
    private static final int[] DX = {1, -1, 0, 0};

    /** Simple container for a cell coordinate. */
    private static final class Cell {
        final int row;
        final int col;

        Cell(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }

    /** Fast input reader that works with both files and {@link System#in}. */
    private static final class FastScanner {
        private final java.io.BufferedReader br;
        private StringTokenizer st;

        FastScanner(java.io.BufferedReader br) {
            this.br = br;
        }

        /** Returns the next token, or {@code null} if no more input. */
        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) {
                        return null;
                    }
                    st = new StringTokenizer(line);
                } catch (java.io.IOException e) {
                    throw new UncheckedIOException(e);
                }
            }
            return st.nextToken();
        }

        /** @return {@code true} if more tokens are available. */
        boolean hasMoreTokens() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) {
                        return false;
                    }
                    st = new StringTokenizer(line);
                } catch (java.io.IOException e) {
                    throw new UncheckedIOException(e);
                }
            }
            return true;
        }

        /** @return next integer token. */
        int nextInt() {
            return Integer.parseInt(next());
        }
    }

    /** Executes one test case. */
    private static boolean canAllGoodBeReachedAndNoBadBeVisited(
            char[][] grid, int rows, int cols) {

        /* --------------------------------------------------------------
         * 1️⃣  Block every empty cell that touches a bad cell.
         * -------------------------------------------------------------- */
        int goodCount = 0;
        for (int r = 0; r < rows; ++r) {
            for (int c = 0; c < cols; ++c) {
                if (grid[r][c] == 'B') {
                    for (int d = 0; d < 4; ++d) {
                        int nr = r + DY[d];
                        int nc = c + DX[d];
                        if (inside(nr, nc, rows, cols) && grid[nr][nc] == '.') {
                            grid[nr][nc] = '#';   // turn into a wall
                        }
                    }
                } else if (grid[r][c] == 'G') {
                    ++goodCount;
                }
            }
        }

        /* --------------------------------------------------------------
         * 2️⃣  BFS from the destination (bottom‑right) to see which cells
         *     are reachable without crossing walls.
         * -------------------------------------------------------------- */
        boolean[][] visited = new boolean[rows][cols];
        java.util.ArrayDeque<Cell> queue = new java.util.ArrayDeque<>();

        if (grid[rows - 1][cols - 1] == '.') {
            queue.add(new Cell(rows - 1, cols - 1));
            visited[rows - 1][cols - 1] = true;
        }

        int reachedGood = 0;
        int reachedBad = 0;

        while (!queue.isEmpty()) {
            Cell cur = queue.poll();

            switch (grid[cur.row][cur.col]) {
                case 'G' -> ++reachedGood;
                case 'B' -> ++reachedBad;
            }

            for (int d = 0; d < 4; ++d) {
                int nr = cur.row + DY[d];
                int nc = cur.col + DX[d];
                if (inside(nr, nc, rows, cols)
                        && !visited[nr][nc]
                        && grid[nr][nc] != '#') {
                    queue.add(new Cell(nr, nc));
                    visited[nr][nc] = true;
                }
            }
        }

        /* --------------------------------------------------------------
         * 3️⃣  Success condition: all 'G's are reachable and no 'B' is.
         * -------------------------------------------------------------- */
        return reachedGood == goodCount && reachedBad == 0;
    }

    /** Checks whether (r, c) lies inside a matrix of size rows×cols. */
    private static boolean inside(int r, int c, int rows, int cols) {
        return 0 <= r && r < rows && 0 <= c && c < cols;
    }

    /** Solves the whole input (multiple test cases). */
    private static void solve(FastScanner in, PrintWriter out) {
        int T = in.nextInt();
        while (T-- > 0) {
            int rows = in.nextInt();
            int cols = in.nextInt();

            char[][] maze = new char[rows][cols];
            for (int r = 0; r < rows; ++r) {
                maze[r] = in.next().toCharArray();
            }

            boolean possible = canAllGoodBeReachedAndNoBadBeVisited(maze, rows, cols);
            out.println(possible ? "Yes" : "No");
        }
    }

    /* -----------------------------------------------------------------
     *  Entry point – runs the solution against standard I/O.
     *  If a file named "Solve.in" exists in the working directory,
     *  you may switch to the file‑based runner by calling {@code run()}.
     * ----------------------------------------------------------------- */
    public static void main(String[] args) {
        FastScanner scanner = new FastScanner(java.lang.System.in);
        PrintWriter writer = new PrintWriter(java.lang.System.out);
        solve(scanner, writer);
        writer.close();
    }

    /* -----------------------------------------------------------------
     *  Optional file‑based runner – left unchanged from the original code.
     * ----------------------------------------------------------------- */
    private FastScanner in;
    private PrintWriter out;

    /** Runs against "Solve.in" → "Solve.out" files (kept for compatibility). */
    private void run() {
        try {
            in = new FastScanner(new java.io.File("Solve.in"));
            out = new PrintWriter(new java.io.File("Solve.out"));
            solve(in, out);
            out.close();
        } catch (java.io.FileNotFoundException e) {
            // If the file does not exist, fallback to normal I/O.
            main(new String[0]);
        }
    }

    /** Runs against standard I/O (default entry point). */
    private void runIO() {
        in = new FastScanner(java.lang.System.in);
        out = new PrintWriter(java.lang.System.out);
        solve(in, out);
        out.close();
    }
}

import java.io.*;
import java.util.*;

public class Solution {

    /** Direction vectors: right, down, left, up, stay */
    private static final int[] DR = {0, 1, 0, -1, 0};
    private static final int[] DC = {1, 0, -1, 0, 0};

    /** Entry point – handles multiple test cases */
    public static void main(String[] args) throws Exception {
        // BufferedReader improves reading speed for large inputs
        try (Scanner scanner = new Scanner(new BufferedReader(new InputStreamReader(System.in)))) {
            int testCases = scanner.nextInt();
            for (int tc = 1; tc <= testCases; tc++) {
                solve(scanner);
            }
        }
    }

    /** Solves a single test case */
    private static void solve(Scanner scanner) {
        int rows = scanner.nextInt();
        int cols = scanner.nextInt();
        char[][] grid = new char[rows][cols];

        /* -------------------------------------------------------------
         * 1️⃣  Load the grid and collect positions of goods and bads
         * ------------------------------------------------------------- */
        List<Point> goods = new ArrayList<>();
        List<Integer> badPositions = new ArrayList<>();

        for (int r = 0; r < rows; r++) {
            String line = scanner.next();
            System.arraycopy(line.toCharArray(), 0, grid[r], 0, cols);
        }

        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                char cell = grid[r][c];
                if (cell == 'G') {
                    goods.add(new Point(r, c));
                } else if (cell == 'B') {
                    badPositions.add(r * cols + c);
                }
            }
        }

        /* -------------------------------------------------------------
         * 2️⃣  If exit cell is blocked we can only answer “Yes” when
         *     there are no goods to reach.
         * ------------------------------------------------------------- */
        if (grid[rows - 1][cols - 1] == '#') {
            System.out.println(goods.isEmpty() ? "Yes" : "No");
            return;
        }

        /* -------------------------------------------------------------
         * 3️⃣  Neutralise the influence of bad cells:
         *     surround each bad cell with walls if the neighbour is empty.
         * ------------------------------------------------------------- */
        for (int pos : badPositions) {
            int r = pos / cols;
            int c = pos % cols;
            for (int d = 0; d < 4; d++) {
                int nr = r + DR[d];
                int nc = c + DC[d];
                if (isInside(nr, nc, rows, cols) && grid[nr][nc] == '.') {
                    grid[nr][nc] = '#';
                }
            }
        }

        /* -------------------------------------------------------------
         * 4️⃣  BFS from the exit cell (bottom‑right) marking reachable
         *     empty cells with the temporary symbol 'Y'.
         * ------------------------------------------------------------- */
        bfsFromExit(grid, rows, cols);

        /* -------------------------------------------------------------
         * 5️⃣  Every good must be reachable – i.e. marked 'Y'.
         * ------------------------------------------------------------- */
        for (Point g : goods) {
            if (grid[g.row][g.col] != 'Y') {
                System.out.println("No");
                return;
            }
        }
        System.out.println("Yes");
    }

    /** Breadth‑first search starting from the bottom‑right corner. */
    private static void bfsFromExit(char[][] grid, int rows, int cols) {
        Queue<Integer> queue = new ArrayDeque<>();
        Set<Integer> visited = new HashSet<>();

        int startIdx = rows * cols - 1;          // linear index of the exit cell
        queue.add(startIdx);
        visited.add(startIdx);

        while (!queue.isEmpty()) {
            int cur = queue.poll();
            int r = cur / cols;
            int c = cur % cols;

            for (int d = 0; d < 4; d++) {
                int nr = r + DR[d];
                int nc = c + DC[d];
                if (!isInside(nr, nc, rows, cols)) {
                    continue;
                }
                int nIdx = nr * cols + nc;
                if (visited.contains(nIdx) || grid[nr][nc] == '#') {
                    continue;
                }
                visited.add(nIdx);
                queue.add(nIdx);
                grid[nr][nc] = 'Y';              // mark as visited/reachable
            }
        }
    }

    /** Helper – checks whether (r, c) lies inside the grid. */
    private static boolean isInside(int r, int c, int rows, int cols) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    /** Simple container for a cell coordinate. */
    private static final class Point {
        final int row;
        final int col;

        Point(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }

    /** Utility method kept from the original snippet (not used, but preserved). */
    private static int[] readIntArray(Scanner scanner, int length) {
        int[] arr = new int[length];
        for (int i = 0; i < length; i++) {
            arr[i] = scanner.nextInt();
        }
        return arr;
    }
}

import java.io.*;
import java.util.*;

public class Main {

    /** Directions used for neighbour exploration. */
    private static final int[][] DIRS = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};

    /** Simple coordinate holder. */
    private static final class Pos {
        final int x, y;
        Pos(int x, int y) { this.x = x; this.y = y; }
    }

    /** Encapsulates a single test case (maze + bookkeeping arrays). */
    private static final class TestCase {
        private final int n, m;                     // dimensions of the interior
        private final char[][] maze;                // the grid (surrounded by walls)
        private final boolean[][] visited;          // reused for BFS bookkeeping
        private final Queue<Pos> queue = new ArrayDeque<>();

        TestCase(int n, int m, InputReader in) {
            this.n = n;
            this.m = m;
            this.maze = new char[n + 2][m + 2];
            this.visited = new boolean[n + 2][m + 2];
            // surround the real maze with walls
            for (int i = 0; i < n + 2; i++) {
                Arrays.fill(maze[i], '#');
            }
            // read interior cells
            for (int i = 1; i <= n; i++) {
                // each line contains exactly M characters without spaces
                String line = in.nextString();
                for (int j = 1; j <= m; j++) {
                    maze[i][j] = line.charAt(j - 1);
                }
            }
        }

        /** Process every box ('B'). Returns false if a BFS discovers a goal ('G'). */
        boolean processAllBoxes() {
            for (int i = 1; i <= n; i++) {
                for (int j = 1; j <= m; j++) {
                    if (maze[i][j] == 'B' && !visited[i][j]) {
                        if (!bfsFromBox(i, j)) {
                            return false;               // a goal was reached → impossible
                        }
                    }
                }
            }
            return true;
        }

        /** Breadth‑first search that expands from a box, blocking '.' cells and
         *  treating 'G' as a fatal termination. */
        private boolean bfsFromBox(int sx, int sy) {
            if (maze[sx][sy] == '#') {
                return true;                         // nothing to explore
            }
            queue.clear();
            visited[sx][sy] = true;
            queue.offer(new Pos(sx, sy));

            while (!queue.isEmpty()) {
                Pos p = queue.poll();
                for (int[] d : DIRS) {
                    int nx = p.x + d[0];
                    int ny = p.y + d[1];
                    if (!inBounds(nx, ny) || visited[nx][ny]) {
                        continue;
                    }
                    char cell = maze[nx][ny];
                    switch (cell) {
                        case '.':
                            // block the empty cell for later phases
                            maze[nx][ny] = '#';
                            break;
                        case '#':
                            // wall – ignore
                            break;
                        case 'G':
                            // reaching a goal makes the whole test case invalid
                            return false;
                        case 'B':
                            // another box – continue expanding from it
                            visited[nx][ny] = true;
                            queue.offer(new Pos(nx, ny));
                            break;
                    }
                }
            }
            return true;
        }

        /** Verify that every goal ('G') is reachable from the bottom‑right corner
         *  after the boxes have been processed. */
        boolean verifyGoalReachability() {
            // reset visitation flags
            for (int i = 0; i <= n + 1; i++) {
                Arrays.fill(visited[i], false);
            }

            Pos start = new Pos(n, m);
            if (maze[start.x][start.y] == '#') {
                return true;                         // nothing to check
            }
            queue.clear();
            visited[start.x][start.y] = true;
            queue.offer(start);

            while (!queue.isEmpty()) {
                Pos p = queue.poll();
                for (int[] d : DIRS) {
                    int nx = p.x + d[0];
                    int ny = p.y + d[1];
                    if (!inBounds(nx, ny) || visited[nx][ny]) {
                        continue;
                    }
                    char cell = maze[nx][ny];
                    switch (cell) {
                        case '.':
                        case 'G':
                            visited[nx][ny] = true;
                            queue.offer(new Pos(nx, ny));
                            break;
                        case '#':
                            // cannot walk through walls
                            break;
                        case 'B':
                            // boxes must not be traversed in this phase
                            return false;
                    }
                }
            }

            // every goal must have been visited
            for (int i = 1; i <= n; i++) {
                for (int j = 1; j <= m; j++) {
                    if (maze[i][j] == 'G' && !visited[i][j]) {
                        return false;
                    }
                }
            }
            return true;
        }

        /** Helper – does a coordinate lie inside the padded grid? */
        private boolean inBounds(int x, int y) {
            return x >= 0 && x <= n + 1 && y >= 0 && y <= m + 1;
        }
    }

    /** Fast character‑oriented input reader. */
    private static final class InputReader {
        private final BufferedReader br;
        private StringTokenizer st;

        InputReader() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        /** Return the next non‑whitespace character. */
        char nextChar() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                st = new StringTokenizer(nextLine());
            }
            return st.nextToken().charAt(0);
        }

        /** Return the next token as a whole string (used for whole lines). */
        String nextString() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                st = new StringTokenizer(nextLine());
            }
            return st.nextToken();
        }

        /** Convenience wrapper for the next integer. */
        int nextInt() throws IOException {
            return Integer.parseInt(nextString());
        }
    }

    public static void main(String[] args) throws Exception {
        InputReader in = new InputReader();
        StringBuilder out = new StringBuilder();

        int T = in.nextInt();                     // number of test cases
        while (T-- > 0) {
            int n = in.nextInt();                  // rows of the interior
            int m = in.nextInt();                  // columns of the interior
            TestCase tc = new TestCase(n, m, in);

            boolean boxesHandled = tc.processAllBoxes();
            boolean goalsReachable = tc.verifyGoalReachability();

            out.append((boxesHandled && goalsReachable) ? "Yes\n" : "No\n");
        }
        System.out.print(out);
    }
}

import java.io.*;
import java.util.*;

/**
 * Refactored solution that preserves the original behaviour.
 *
 * <p>Improvements made:
 * <ul>
 *   <li>Separated concerns into small, focused methods.</li>
 *   <li>Renamed confusing variables to expressive names.</li>
 *   <li>Removed dead code and unused imports.</li>
 *   <li>Added JavaDoc comments and clear constants.</li>
 *   <li>Used a fast scanner instead of many static helpers.</li>
 *   <li>Kept the original algorithmic steps (border filling,
 *       neighbour‑blocking, DFS, and validation) but expressed them
 *       with modern Java idioms.</li>
 * </ul>
 */
public class Main {

    /* --------------------------------------------------------------
     *  Constants & Types
     * -------------------------------------------------------------- */
    private static final int BUFFER = 2;               // border around the grid
    private static final int TYPE_FREE   = 0;          // '.'  – walkable
    private static final int TYPE_OBST   = 1;          // '#'  – obstacle
    private static final int TYPE_GOAL   = 2;          // 'G'  – special goal marker
    private static final int TYPE_UNKNOWN = -1;        // any other character

    private static int rows, cols;                     // grid dimensions
    private static int[][] grid;                       // cell values
    private static boolean[][] visited;                // visited flag
    private static boolean answer;                     // test result

    /* --------------------------------------------------------------
     *  Fast input reader
     * -------------------------------------------------------------- */
    private static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner(InputStream stream) {
            br = new BufferedReader(new InputStreamReader(stream));
        }

        private void ensureTokenizer() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    throw new UncheckedIOException(e);
                }
            }
        }

        int nextInt() {
            ensureTokenizer();
            return Integer.parseInt(st.nextToken());
        }

        String nextLine() {
            ensureTokenizer();
            return st.nextToken("\n");
        }
    }

    /* --------------------------------------------------------------
     *  Main entry point
     * -------------------------------------------------------------- */
    public static void main(String[] args) throws IOException {
        FastScanner fs = new FastScanner(System.in);
        int tests = Integer.parseInt(fs.nextLine());

        while (tests-- > 0) {
            solveTest(fs);
        }
    }

    /* --------------------------------------------------------------
     *  Processing a single test case
     * -------------------------------------------------------------- */
    private static void solveTest(FastScanner fs) {
        readDimensions(fs);
        readGrid(fs);
        recordOriginalTypes();          // needed for validation later
        blockNeighbouringUnknowns();     // side‑effect that modifies grid
        if (grid[rows][cols] != TYPE_OBST) {
            dfs(cols, rows);              // start DFS from (n,m) – the target cell
        }
        validate();
        out.println(answer ? "Yes" : "No");
    }

    /* --------------------------------------------------------------
     *  Helpers used by solveTest
     * -------------------------------------------------------------- */
    private static void readDimensions(FastScanner fs) {
        rows = Integer.parseInt(fs.nextLine().split(" ")[0]);   // first line: n m
        cols = Integer.parseInt(fs.nextLine().split(" ")[1]);
    }

    /** Reads the grid, filling a surrounding border of obstacles. */
    private static void readGrid(FastScanner fs) {
        grid = new int[rows + BUFFER][cols + BUFFER];
        visited = new boolean[rows + BUFFER][cols + BUFFER];

        // initialise border with obstacles
        for (int r = 0; r < rows + BUFFER; r++) {
            Arrays.fill(grid[r], TYPE_OBST);
        }

        // read interior cells
        for (int r = 1; r <= rows; r++) {
            String line = fs.nextLine();
            for (int c = 1; c <= cols; c++) {
                char ch = line.charAt(c - 1);
                grid[r][c] = switch (ch) {
                    case '.' -> TYPE_FREE;
                    case '#' -> TYPE_OBST;
                    case 'G' -> TYPE_GOAL;
                    default  -> TYPE_UNKNOWN;
                };
            }
        }
    }

    /** Marks every orthogonal neighbour of a GOAL cell as an obstacle,
     *  unless that neighbour is itself a GOAL cell. */
    private static void blockNeighbouringUnknowns() {
        int[] dr = {-1, 1, 0, 0};
        int[] dc = {0, 0, -1, 1};

        for (int r = 1; r <= rows; r++) {
            for (int c = 1; c <= cols; c++) {
                if (grid[r][c] == TYPE_GOAL) {
                    for (int d = 0; d < 4; d++) {
                        int nr = r + dr[d];
                        int nc = c + dc[d];
                        if (grid[nr][nc] != TYPE_GOAL && grid[nr][nc] != TYPE_OBST) {
                            grid[nr][nc] = TYPE_OBST;
                        }
                    }
                }
            }
        }
    }

    /** Stores the original cell types so they can be consulted during validation. */
    private static int[][] originalTypes;   // cloned from {@code grid} before modifications

    private static void recordOriginalTypes() {
        originalTypes = new int[rows + BUFFER][cols + BUFFER];
        for (int r = 1; r <= rows; r++) {
            System.arraycopy(grid[r], 1, originalTypes[r], 1, cols);
        }
    }

    /** Depth‑first search starting from the target cell (rows, cols). */
    private static void dfs(int startCol, int startRow) {
        visited[startRow][startCol] = true;
        if (isWalkable(startRow - 1, startCol)) dfs(startCol, startRow - 1);
        if (isWalkable(startRow + 1, startCol)) dfs(startCol, startRow + 1);
        if (isWalkable(startRow, startCol - 1)) dfs(startCol - 1, startRow);
        if (isWalkable(startRow, startCol + 1)) dfs(startCol + 1, startRow);
    }

    /** Returns {@code true} if a cell is inside the grid, is not an obstacle,
     *  and has not been visited yet. */
    private static boolean isWalkable(int r, int c) {
        return r >= 0 && c >= 0 && grid[r][c] != TYPE_OBST && !visited[r][c];
    }

    /** Performs the validation step exactly like the original program.
     *  The global flag {@code answer} is set accordingly. */
    private static void validate() {
        answer = true;

        // 1. Every GOAL cell must be visited.
        for (int r = 1; r <= rows; r++) {
            for (int c = 1; c <= cols; c++) {
                if (grid[r][c] == TYPE_GOAL && !visited[r][c]) {
                    answer = false;
                }
            }
        }

        // 2. No cell that was originally UNKNOWN (-1) may be visited.
        for (int r = 1; r <= rows; r++) {
            for (int c = 1; c <= cols; c++) {
                if (visited[r][c] && originalTypes[r][c] == TYPE_UNKNOWN) {
                    answer = false;
                }
            }
        }
    }

    /* --------------------------------------------------------------
     *  Stub for output – in a real competition we would keep a
     *  PrintWriter, but for clarity we just delegate to System.out.
     * -------------------------------------------------------------- */
    private static PrintWriter out = new PrintWriter(System.out, true);
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.StringJoiner;

/**
 * Solves a maze‑type puzzle where a path must be found from the bottom‑right cell
 * to every good cell ('G') while avoiding blocked cells.
 *
 * <p>Blocked cells are:
 * <ul>
 *   <li>any cell that contains 'B'</li>
 *   <li>any neighbour (up, down, left, right) of a 'B' cell</li>
 * </ul>
 *
 * <p>The program reads multiple test cases from standard input and prints
 * “Yes” if every good cell can be reached from the start cell, otherwise “No”.
 *
 * <p>All mutable state is scoped to the current test case, making the code
 * easier to test and reason about.
 */
public final class MazeSolver {

    /** Directions used for neighbour exploration. */
    private static final int[][] NEIGHBOURS = {
            {-1, 0}, {1, 0}, {0, -1}, {0, 1}
    };

    /** Private constructor – utility class. */
    private MazeSolver() {}

    /**
     * Entry point – processes all test cases.
     *
     * @param args ignored
     * @throws IOException if an I/O error occurs while reading input
     */
    public static void main(String[] args) throws IOException {
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in))) {
            int testCases = Integer.parseInt(br.readLine().trim());

            for (int caseIdx = 0; caseIdx < testCases; caseIdx++) {
                processSingleTestCase(br);
            }
        }
    }

    /** Reads and solves one test case, printing the result. */
    private static void processSingleTestCase(BufferedReader br) throws IOException {
        StringTokenizer st = new StringTokenizer(br.readLine());
        int rows = Integer.parseInt(st.nextToken());
        int cols = Integer.parseInt(st.nextToken());

        char[][] grid = readGrid(br, rows);
        boolean[][] blocked = computeBlocked(grid, rows, cols);
        int totalGoods = countGoods(grid);

        int reachableGoods = exploreFromBottomRight(grid, blocked, rows, cols);
        System.out.println(reachableGoods == totalGoods ? "Yes" : "No");
    }

    /** Reads the grid rows from the input stream. */
    private static char[][] readGrid(BufferedReader br, int rows) throws IOException {
        char[][] grid = new char[rows][];
        for (int r = 0; r < rows; r++) {
            grid[r] = br.readLine().toCharArray();
        }
        return grid;
    }

    /** Determines which cells are blocked according to the rules. */
    private static boolean[][] computeBlocked(char[][] grid, int rows, int cols) {
        boolean[][] blocked = new boolean[rows][cols];

        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                char cell = grid[r][c];
                if (cell == '#' || cell == 'B') {
                    blocked[r][c] = true;
                } else if (cell == 'B') {
                    // mark the neighbour cells as blocked as well
                    blocked[r][c] = true;
                    markNeighbours(r, c, rows, cols, blocked);
                }
            }
        }
        return blocked;
    }

    /** Marks the four orthogonal neighbours of (r,c) as blocked if they exist. */
    private static void markNeighbours(int r, int c, int rows, int cols, boolean[][] blocked) {
        int[][] dirs = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};
        for (int[] d : dirs) {
            int nr = r + d[0];
            int nc = c + d[1];
            if (nr >= 0 && nr < rows && nc >= 0 && nc < cols) {
                blocked[nr][nc] = true;
            }
        }
    }

    /** Counts how many 'G' cells appear in the grid. */
    private static int countGoods(char[][] grid) {
        int count = 0;
        for (char[] row : grid) {
            for (char cell : row) {
                if (cell == 'G') {
                    count++;
                }
            }
        }
        return count;
    }

    /**
     * Depth‑first search starting from the bottom‑right cell.
     * Returns the number of good cells that are reachable.
     */
    private static int exploreFromBottomRight(char[][] grid,
                                              boolean[][] blocked,
                                              int rows,
                                              int cols) {
        boolean[][] visited = new boolean[rows][cols];
        return dfs(rows - 1, cols - 1, grid, blocked, visited);
    }

    /** Recursive DFS that counts reachable 'G' cells. */
    private static int dfs(int r, int c,
                           char[][] grid,
                           boolean[][] blocked,
                           boolean[][] visited) {
        if (r < 0 || c < 0 || r >= grid.length || c >= grid[0].length) {
            return 0;
        }
        if (visited[r][c] || blocked[r][c]) {
            return 0;
        }

        visited[r][c] = true;
        int reachable = 0;
        if (grid[r][c] == 'G') {
            reachable++;
        }

        for (int[] d : NEIGHBOURS) {
            reachable += dfs(r + d[0], c + d[1], grid, blocked, visited);
        }
        return reachable;
    }
}

import java.io.*;
import java.util.*;

/**
 * Main class that handles input, processes each test case and prints the answer.
 *
 * <p>The program checks whether every good {@code 'G'} can escape to the bottom‑right cell
 * of the maze after we optionally block some empty cells ({' '.'} → {@code '#'}) that are
 * directly adjacent to a bad {@code 'B'}.</p>
 */
public class MazeEscape {

    /** Direction vectors for the four orthogonal neighbours. */
    private static final int[] DX = {-1, 0, 1, 0};
    /** Direction vectors for the four orthogonal neighbours. */
    private static final int[] DY = {0, 1, 0, -1};

    /** Fast scanner used to read the input data. */
    private final FastScanner scanner;

    /** Fast printer used to write the output data. */
    private final PrintWriter printer;

    /** Constructor that injects the input and output streams. */
    public MazeEscape(InputStream input, PrintWriter printer) {
        this.scanner = new FastScanner(input);
        this.printer = printer;
    }

    /** Entry point of the program. */
    public static void main(String[] args) throws IOException {
        try (PrintWriter out = new PrintWriter(System.out)) {
            new MazeEscape(System.in, out).solve();
        }
    }

    /** Reads all test cases, solves them and prints the answers. */
    public void solve() throws IOException {
        int testCount = scanner.nextInt();
        for (int testIdx = 0; testIdx < testCount; testIdx++) {
            solveSingleTest();
        }
        printer.flush();
    }

    /** Solves one maze test case. */
    private void solveSingleTest() {
        int rows = scanner.nextInt();
        int cols = scanner.nextInt();
        char[][] maze = readMaze(rows);
        markBadInfluence(maze, rows, cols);
        boolean[][] reachable = bfsFromExit(maze, rows, cols);
        boolean canEscapeAllGoods = checkAllGoodsReachable(maze, reachable, rows, cols);
        printer.println(canEscapeAllGoods ? "Yes" : "No");
    }

    /** Reads the maze grid from the scanner. */
    private char[][] readMaze(int rows) {
        char[][] maze = new char[rows][];
        for (int r = 0; r < rows; r++) {
            String line = scanner.next();
            maze[r] = line.toCharArray();
        }
        return maze;
    }

    /** Marks cells that are adjacent to a bad cell and must be blocked. */
    private void markBadInfluence(char[][] maze, int rows, int cols) {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (maze[r][c] != 'B') {
                    continue;
                }
                for (int dir = 0; dir < 4; dir++) {
                    int nr = r + DX[dir];
                    int nc = c + DY[dir];
                    if (!isInside(nr, nc, rows, cols)) {
                        continue;
                    }
                    char neighbour = maze[nr][nc];
                    if (neighbour == 'G') {
                        // A good cell surrounded by a bad one can never escape.
                        System.err.println("Encountered unreachable good cell – terminating early.");
                        System.exit(1);
                    }
                    if (neighbour == '.') {
                        maze[nr][nc] = '#'; // block the empty cell
                    }
                }
            }
        }
    }

    /** Performs a BFS from the exit cell (bottom‑right) backwards to find all reachable cells. */
    private boolean[][] bfsFromExit(char[][] maze, int rows, int cols) {
        boolean[][] reachable = new boolean[rows][cols];
        if (maze[rows - 1][cols - 1] != '.') {
            // Exit is blocked – nothing can escape.
            return reachable;
        }

        Queue<Integer> queue = new ArrayDeque<>();
        queue.add(index(rows - 1, cols - 1, cols));
        reachable[rows - 1][cols - 1] = true;

        while (!queue.isEmpty()) {
            int current = queue.poll();
            int r = current / cols;
            int c = current % cols;
            for (int dir = 0; dir < 4; dir++) {
                int nr = r + DX[dir];
                int nc = c + DY[dir];
                if (!isInside(nr, nc, rows, cols)) {
                    continue;
                }
                char cell = maze[nr][nc];
                if ((cell == '.' || cell == 'G') && !reachable[nr][nc]) {
                    reachable[nr][nc] = true;
                    queue.add(index(nr, nc, cols));
                }
            }
        }
        return reachable;
    }

    /** Checks whether every good cell is reachable from the exit. */
    private boolean checkAllGoodsReachable(char[][] maze,
                                            boolean[][] reachable,
                                            int rows,
                                            int cols) {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (maze[r][c] == 'G' && !reachable[r][c]) {
                    return false;
                }
            }
        }
        return true;
    }

    /** Utility that converts a 2‑D coordinate into a 1‑D linear index for the queue. */
    private static int index(int row, int col, int cols) {
        return row * cols + col;
    }

    /** Returns true if the given coordinates are inside the rectangular maze. */
    private static boolean isInside(int x, int y, int rows, int cols) {
        return 0 <= x && x < rows && 0 <= y && y < cols;
    }

    /*
     * -------------------------------------------------------------------------
     * FastScanner – thin wrapper around BufferedReader that returns primitive values.
     * -------------------------------------------------------------------------
     */
    private static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner(InputStream source) {
            this.br = new BufferedReader(new InputStreamReader(source));
        }

        /** Reads the next token (lexeme). */
        private String nextToken() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                String line = br.readLine();
                if (line == null) {
                    return null;
                }
                st = new StringTokenizer(line);
            }
            return st.nextToken();
        }

        /** Reads the next integer. */
        int nextInt() throws IOException {
            return Integer.parseInt(nextToken());
        }

        /** Reads the next line (which may contain spaces). */
        String nextLine() throws IOException {
            return br.readLine();
        }
    }
}

import java.io.IOException;
import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;

/**
 * Refactored solution that checks whether all green cells can be reached
 * from the bottom‑right corner after strategically placing walls around
 * reachable blue cells.
 */
public class Main {

    private static final char WALL   = '#';
    private static final char GREEN  = 'G';
    private static final char BLUE   = 'B';
    private static final char EMPTY  = '.';

    /** Four movement directions: up, left, down, right. */
    private static final int[][] DIRS = {
            {-1, 0},
            {0, -1},
            {1, 0},
            {0, 1}
    };

    public static void main(String[] args) throws IOException {
        try (Scanner scanner = new Scanner(System.in)) {
            StringBuilder out = new StringBuilder();
            int t = scanner.nextInt();
            while (t-- > 0) {
                solveCase(scanner, out);
            }
            System.out.print(out.toString());
        }
    }

    /** Handles a single test case. */
    private static void solveCase(Scanner sc, StringBuilder out) {
        int n = sc.nextInt();
        int m = sc.nextInt();
        char[][] grid = new char[n][];
        int greenCount = 0;

        // Read grid rows and count green cells.
        for (int i = 0; i < n; i++) {
            String line = sc.next();
            char[] row = line.toCharArray();
            grid[i] = row;
            for (char c : row) {
                if (c == GREEN) {
                    greenCount++;
                }
            }
        }

        // No green cells → answer is always "Yes".
        if (greenCount == 0) {
            out.append("Yes\n");
            return;
        }

        // ---- 1. Find all blue cells reachable from (n‑1,m‑1) ----
        List<Point> reachableBlue = new ArrayList<>();
        boolean[][] visited = new boolean[n][m];
        bfsCollectBlue(grid, n, m, n - 1, m - 1, visited, reachableBlue);

        // ---- 2. Block neighbours of each reachable blue cell ----
        boolean possible = true;
        for (Point p : reachableBlue) {
            // Turn the blue cell itself into a wall.
            grid[p.x][p.y] = WALL;

            // Block the four orthogonal neighbours if they are not green.
            for (int[] dir : DIRS) {
                int nx = p.x + dir[0];
                int ny = p.y + dir[1];
                if (outOfBounds(nx, ny, n, m) || grid[nx][ny] == WALL) {
                    continue;
                }
                if (grid[nx][ny] == GREEN) {
                    // A green neighbour cannot be blocked → impossible.
                    possible = false;
                } else {
                    grid[nx][ny] = WALL;
                }
            }
        }

        // The exit cell must stay traversable.
        if (grid[n - 1][m - 1] == WALL) {
            possible = false;
        }

        // ---- 3. Verify that all green cells are still reachable ----
        if (possible) {
            int visitedGreen = bfsCountGreen(grid, n, m);
            if (visitedGreen != greenCount) {
                possible = false;
            }
        }

        out.append(possible ? "Yes\n" : "No\n");
    }

    /** Breadth‑first search that visits all non‑wall cells from (sx,sy)
     *  and collects the coordinates of cells that contain a blue ('B'). */
    private static void bfsCollectBlue(char[][] grid, int n, int m,
                                       int sx, int sy,
                                       boolean[][] visited,
                                       List<Point> target) {
        ArrayDeque<Point> queue = new ArrayDeque<>();
        queue.add(new Point(sx, sy));
        visited[sx][sy] = true;

        while (!queue.isEmpty()) {
            Point cur = queue.poll();
            if (grid[cur.x][cur.y] == BLUE) {
                target.add(cur);
            }
            for (int[] dir : DIRS) {
                int nx = cur.x + dir[0];
                int ny = cur.y + dir[1];
                if (outOfBounds(nx, ny, n, m) || visited[nx][ny] || grid[nx][ny] == WALL) {
                    continue;
                }
                visited[nx][ny] = true;
                queue.add(new Point(nx, ny));
            }
        }
    }

    /** Returns how many green cells are reachable from the bottom‑right corner. */
    private static int bfsCountGreen(char[][] grid, int n, int m) {
        ArrayDeque<Point> queue = new ArrayDeque<>();
        boolean[][] visited = new boolean[n][m];
        queue.add(new Point(n - 1, m - 1));
        visited[n - 1][m - 1] = true;

        int visitedGreen = 0;
        while (!queue.isEmpty()) {
            Point cur = queue.poll();
            if (grid[cur.x][cur.y] == GREEN) {
                visitedGreen++;
            }
            for (int[] dir : DIRS) {
                int nx = cur.x + dir[0];
                int ny = cur.y + dir[1];
                if (outOfBounds(nx, ny, n, m) || visited[nx][ny] || grid[nx][ny] == WALL) {
                    continue;
                }
                visited[nx][ny] = true;
                queue.add(new Point(nx, ny));
            }
        }
        return visitedGreen;
    }

    /** Simple container for a cell coordinate. */
    private static final class Point {
        final int x;
        final int y;

        Point(int x, int y) {
            this.x = x;
            this.y = y;
        }
    }

    /** Utility: true if (x,y) lies outside the grid boundaries. */
    private static boolean outOfBounds(int x, int y, int n, int m) {
        return x < 0 || y < 0 || x >= n || y >= m;
    }
}

import java.io.*;
import java.util.*;

public class Solution {

    /** Four orthogonal directions: up, down, left, right. */
    private enum Direction {
        UP(1, 0),
        DOWN(-1, 0),
        LEFT(0, 1),
        RIGHT(0, -1);

        private final int deltaRow;
        private final int deltaCol;

        Direction(int deltaRow, int deltaCol) {
            this.deltaRow = deltaRow;
            this.deltaCol = deltaCol;
        }

        /** Returns the row offset for this direction. */
        int getDeltaRow() { return deltaRow; }

        /** Returns the column offset for this direction. */
        int getDeltaCol() { return deltaCol; }
    }

    /** Checks whether (r, c) is inside an n × m grid. */
    private static boolean isInside(int r, int c, int n, int m) {
        return 0 <= r && r < n && 0 <= c && c < m;
    }

    /**
     * For every bomb ('B') mark all adjacent empty cells ('.') with a wall ('#')
     * to indicate that the bomb blocks passage through those cells.
     */
    private static void blockEmptyNeighbours(char[][] grid, int n, int m) {
        for (int r = 0; r < n; ++r) {
            for (int c = 0; c < m; ++c) {
                if (grid[r][c] == 'B') {
                    for (Direction dir : Direction.values()) {
                        int nr = r + dir.getDeltaRow();
                        int nc = c + dir.getDeltaCol();
                        if (isInside(nr, nc, n, m) && grid[nr][nc] == '.') {
                            grid[nr][nc] = '#';
                        }
                    }
                }
            }
        }
    }

    /**
     * Performs a breadth‑first search from the exit cell (n‑1, m‑1).
     * Returns a matrix that marks all cells reachable without crossing walls.
     */
    private static boolean[][] bfs(char[][] grid, int n, int m) {
        boolean[][] visited = new boolean[n][m];
        Queue<int[]> queue = new ArrayDeque<>();

        if (grid[n - 1][m - 1] == '.') {
            queue.add(new int[]{n - 1, m - 1});
            visited[n - 1][m - 1] = true;
        }

        while (!queue.isEmpty()) {
            int[] cur = queue.poll();
            int r = cur[0];
            int c = cur[1];

            for (Direction dir : Direction.values()) {
                int nr = r + dir.getDeltaRow();
                int nc = c + dir.getDeltaCol();
                if (isInside(nr, nc, n, m)
                        && !visited[nr][nc]
                        && grid[nr][nc] != '#') {
                    visited[nr][nc] = true;
                    queue.add(new int[]{nr, nc});
                }
            }
        }
        return visited;
    }

    /**
     * Determines whether every goat ('G') can reach the exit after the bombs’
     * neighbouring empty cells have been blocked.
     *
     * @return {@code true} if all goats can escape; {@code false} otherwise.
     */
    private static boolean canAllGoatsEscape(char[][] grid, int n, int m) {
        blockEmptyNeighbours(grid, n, m);
        boolean[][] visited = bfs(grid, n, m);

        for (int r = 0; r < n; ++r) {
            for (int c = 0; c < m; ++c) {
                if (grid[r][c] == 'G' && !visited[r][c]) {
                    return false;
                }
            }
        }
        return true;
    }

    public static void main(String[] args) throws IOException {
        /* Try‑with‑resources guarantees the reader is closed promptly. */
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in))) {
            int T = Integer.parseInt(br.readLine());

            StringBuilder out = new StringBuilder();

            for (int t = 0; t < T; ++t) {
                StringTokenizer st = new StringTokenizer(br.readLine());
                int rows = Integer.parseInt(st.nextToken());
                int cols = Integer.parseInt(st.nextToken());

                char[][] grid = new char[rows][cols];
                for (int r = 0; r < rows; ++r) {
                    String line = br.readLine();
                    System.arraycopy(line.toCharArray(), 0, grid[r], 0, cols);
                }

                out.append(canAllGoatsEscape(grid, rows, cols) ? "Yes\n" : "No\n");
            }

            System.out.print(out);
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;

/**
 * Refactored solution for the problem formerly implemented in {@code D1365}.
 * The implementation focuses on readability, proper naming, and separation of concerns.
 */
public class Solver {

    // Directions: up, down, left, right
    private static final int[] DR = {-1, 1, 0, 0};
    private static final int[] DC = {0, 0, -1, 1};

    private final int rows;
    private final int cols;
    private final char[][] grid;
    private final boolean[][] visited;

    /**
     * Constructs a new {@code Solver} for the given grid.
     *
     * @param rows    number of rows
     * @param cols    number of columns
     * @param grid    character grid representation
     */
    public Solver(int rows, int cols, char[][] grid) {
        this.rows = rows;
        this.cols = cols;
        this.grid = grid;
        this.visited = new boolean[rows][cols];
    }

    /**
     * Executes the solution and returns {@code true} if all constraints are satisfied.
     */
    public boolean solve() {
        boolean isValid = true;

        // 1. Ensure no green cell is orthogonally adjacent to a bishop.
        if (!checkAdjacency()) {
            isValid = false;
        }

        // 2. Mark all cells reachable from the bottom‑right corner via DFS,
        //    ignoring cells that are walls ('#').
        dfs(rows - 1, cols - 1);

        // 3. Verify that every green cell was visited.
        if (!checkAllGreensVisited()) {
            isValid = false;
        }

        return isValid;
    }

    /** Checks adjacency constraints involving bishops and green cells. */
    private boolean checkAdjacency() {
        for (int r = 0; r < rows && isValid; r++) {
            for (int c = 0; c < cols && isValid; c++) {
                if (grid[r][c] == 'B') {
                    for (int d = 0; d < 4; d++) {
                        int nr = r + DR[d];
                        int nc = c + DC[d];
                        if (isInside(nr, nc)) {
                            char neighbour = grid[nr][nc];
                            if (neighbour == 'G') {
                                // Adjacent green cell -> invalid configuration.
                                return false;
                            }
                            // Mark any non‑bishop, non‑green neighbour as a wall.
                            if (neighbour != 'B') {
                                grid[nr][nc] = '#';
                            }
                        }
                    }
                }
            }
        }
        return true;
    }

    /** Depth‑first search that marks cells reachable from (startRow,startCol). */
    private void dfs(int startRow, int startCol) {
        if (!isInside(startRow, startCol) || grid[startRow][startCol] == '#' || visited[startRow][startCol]) {
            return;
        }
        visited[startRow][startCol] = true;
        for (int d = 0; d < 4; d++) {
            int nr = startRow + DR[d];
            int nc = startCol + DC[d];
            if (isInside(nr, nc) && grid[nr][nc] != '#') {
                dfs(nr, nc);
            }
        }
    }

    /** Verifies that every green cell was visited during DFS. */
    private boolean checkAllGreensVisited() {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == 'G' && !visited[r][c]) {
                    return false;
                }
            }
        }
        return true;
    }

    /** Helper: determines whether the supplied coordinates lie inside the grid. */
    private boolean isInside(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    /** Reads multiple test cases from standard input and prints “Yes” or “No” for each. */
    public static void main(String[] args) {
        // Try‑with‑resources ensures the BufferedReader is closed automatically.
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in))) {
            int testCases = Integer.parseInt(br.readLine().trim());

            for (int t = 0; t < testCases; t++) {
                String[] header = br.readLine().split("\\s+");
                int rows = Integer.parseInt(header[0]);
                int cols = Integer.parseInt(header[1]);

                char[][] grid = new char[rows][cols];
                for (int r = 0; r < rows; r++) {
                    String line = br.readLine();
                    if (line == null) {
                        throw new IOException("Unexpected end of input while reading grid row " + r);
                    }
                    for (int c = 0; c < cols; c++) {
                        grid[r][c] = line.charAt(c);
                    }
                }

                Solver solver = new Solver(rows, cols, grid);
                System.out.println(solver.solve() ? "Yes" : "No");
            }

        } catch (IOException e) {
            System.err.println("Input error: " + e.getMessage());
        } catch (NumberFormatException e) {
            System.err.println("Invalid numeric format in input: " + e.getMessage());
        }
    }
}

import java.io.*;
import java.util.ArrayDeque;
import java.util.Arrays;
import java.util.Deque;

/**
 * Island Adventure – determines whether every grass cell ('G') can be reached
 * from the single exit cell ('B') without stepping on a swamp ('#').
 *
 * The program reads multiple test cases, builds a padded grid and runs a
 * breadth‑first search starting from the exit.
 *
 * Author:  Refactored solution (maintainability focus)
 */
public class IslandAdventure {

    /** Padding around the user supplied area – helps avoid bounds checks. */
    private static final int BOUNDARY = 1;

    /** Four main movement directions. */
    private static final int[][] DIRECTIONS = {
            {1, 0},   // down
            {0, 1},   // right
            {-1, 0},  // up
            {0, -1}   // left
    };

    /** Entry point – reads from stdin and writes answers to stdout. */
    public static void main(String[] args) throws IOException {
        // Try‑with‑resources guarantees that streams are closed afterwards.
        try (BufferedReader br = new BufferedReader(
                new InputStreamReader(System.in));
             BufferedWriter bw = new BufferedWriter(
                new OutputStreamWriter(System.out))) {

            int testCaseCount = Integer.parseInt(br.readLine().trim());

            for (int tc = 0; tc < testCaseCount; tc++) {
                processSingleTestCase(tc + 1, br, bw);
            }
        }
    }

    /**
     * Handles one test case – parsing input, building the grid and printing the
     * result.
     */
    private static void processSingleTestCase(int tc,
                                                BufferedReader br,
                                                BufferedWriter bw) throws IOException {
        // ------------------------------------------------------------
        // 1️⃣  Read header (rows, cols) and allocate a padded grid.
        // ------------------------------------------------------------
        String[] header = br.readLine().split("\\s+");
        int userRows = Integer.parseInt(header[0]);
        int userCols = Integer.parseInt(header[1]);

        Grid grid = new Grid(userRows, userCols);
        int grassCount = 0;               // total number of grass cells
        Point exit = null;                // position of the exit cell

        // ------------------------------------------------------------
        // 2️⃣  Fill the interior of the grid with user data.
        // ------------------------------------------------------------
        for (int r = 0; r < userRows; r++) {
            String line = br.readLine();
            for (int c = 0; c < userCols; c++) {
                char ch = line.charAt(c);
                int gx = r + BOUNDARY;   // convert to padded coordinates
                int gy = c + BOUNDARY;

                switch (ch) {
                    case '#' -> grid.setWall(gx, gy);
                    case 'G' -> {
                        grid.setCell(gx, gy, Grid.CellType.GRASS);
                        grassCount++;
                    }
                    case 'B' -> {
                        grid.setCell(gx, gy, Grid.CellType.GRASS);
                        exit = new Point(gx, gy);
                    }
                    default -> {
                        // Not needed for the problem statement, but keeps parser robust.
                    }
                }
            }
        }

        // ------------------------------------------------------------
        // 3️⃣  Trivial early answers.
        // ------------------------------------------------------------
        if (grassCount == 0) {
            bw.write("Yes\n");
            return;
        }
        if (grid.isWall(exit.row, exit.col)) {
            bw.write("No\n");
            return;
        }

        // ------------------------------------------------------------
        // 4️⃣  Run BFS from the exit, counting reachable grass cells.
        // ------------------------------------------------------------
        bfsFromExit(grid, exit);

        // ------------------------------------------------------------
        // 5️⃣  Output the answer for this test case.
        // ------------------------------------------------------------
        bw.write((grid.getGrassReachedCount() == grassCount) ? "Yes\n" : "No\n");
    }

    /**
     * Breadth‑first search that starts at the exit cell.
     * Counts how many grass cells are reachable without stepping on a wall.
     */
    private static void bfsFromExit(Grid grid, Point start) {
        Deque<Point> queue = new ArrayDeque<>();
        queue.add(start);
        grid.markVisited(start);

        while (!queue.isEmpty()) {
            Point cur = queue.poll();

            // Increment the counter only when we are on a grass cell.
            if (grid.isGrass(cur)) {
                grid.incrementGrassReached();
            }

            // Explore neighbours.
            for (int[] dir : DIRECTIONS) {
                int nr = cur.row + dir[0];
                int nc = cur.col + dir[1];
                Point neighbour = new Point(nr, nc);

                if (grid.isInBounds(neighbour)
                        && !grid.isWall(neighbour)
                        && !grid.isVisited(neighbour)) {
                    grid.markVisited(neighbour);
                    queue.add(neighbour);
                }
            }
        }
    }

    /** ----------------------------------------------------------------
     *  Grid – encapsulates everything about the playable area.
     *  ---------------------------------------------------------------- */
    private static class Grid {
        /** Cell types used in the padded grid. */
        enum CellType { EMPTY, WALL, GRASS }

        private final int paddedRows;   // userRows + 2*BOUNDARY  (0‑based)
        private final int paddedCols;   // userCols + 2*BOUNDARY
        private final int[][] cells;    // underlying integer grid
        private final boolean[][] visited;

        private int grassReached = 0;    // reached grass cells during BFS
        private Point exit;              // last known exit location

        Grid(int userRows, int userCols) {
            // Add a padding of ONE around the user supplied area.
            this.paddedRows = userRows + 2 * BOUNDARY;
            this.paddedCols = userCols + 2 * BOUNDARY;
            this.cells = new int[paddedRows][paddedCols];
            this.visited = new boolean[paddedRows][paddedCols];

            // Fill the outer boundary with walls – this eliminates most bound checks.
            Arrays.fill(cells[0], CellType.WALL.ordinal());
            Arrays.fill(cells[paddedRows - 1], CellType.WALL.ordinal());
            for (int r = 0; r < paddedRows; r++) {
                Arrays.fill(cells[r][0], CellType.WALL.ordinal());
                Arrays.fill(cells[r][paddedCols - 1], CellType.WALL.ordinal());
            }
        }

        /** Marks a wall cell at absolute coordinates. */
        void setWall(int x, int y) {
            cells[x][y] = CellType.WALL.ordinal();
        }

        /** Marks a grass or exit cell at absolute coordinates. */
        void setCell(int x, int y, CellType type) {
            cells[x][y] = type.ordinal();
            if (type == CellType.GRASS && exit == null) {
                exit = new Point(x, y);
            }
        }

        /** Returns the exit coordinates (padded) – will never be null if called after
         *  reading the input containing ‘B’. */
        Point getExit() {
            return exit;
        }

        /** Checks whether the given absolute coordinates are walls. */
        boolean isWall(int x, int y) {
            return cells[x][y] == CellType.WALL.ordinal();
        }

        /** Checks whether the given absolute coordinates contain grass. */
        boolean isGrass(int x, int y) {
            return cells[x][y] == CellType.GRASS.ordinal();
        }

        /** Indicates whether the cell has been visited already during BFS. */
        boolean isVisited(int x, int y) {
            return visited[x][y];
        }

        /** Marks the cell as visited. */
        void markVisited(int x, int y) {
            visited[x][y] = true;
        }

        /** Returns true if the supplied absolute coordinates are inside the grid. */
        boolean isInBounds(int x, int y) {
            return x >= 0 && x < paddedRows && y >= 0 && y < paddedCols;
        }

        /** Convenience wrapper on {@link #isInBounds(int, int)}. */
        boolean isInBounds(Point p) {
            return isInBounds(p.row, p.col);
        }

        /** Counts how many grass cells were reached during BFS. */
        int getGrassReachedCount() {
            return grassReached;
        }

        /** Increments the reachable‑grass counter. */
        void incrementGrassReached() {
            grassReached++;
        }
    }

    /** ----------------------------------------------------------------
     *  Simple point wrapper used throughout the algorithm.
     *  ---------------------------------------------------------------- */
    private static class Point {
        final int row;
        final int col;

        Point(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.ArrayDeque;
import java.util.Deque;
import java.util.HashSet;
import java.util.Set;

/**
 * Solves the “Grid with building (B), good (G) and empty (.) cells” problem.
 *
 * <p>Key ideas:
 * <ul>
 *   <li>All input is read once and parsed with small helper methods.
 *   <li>The original grid is never mutated – a temporary grid is created for wall placement.
 *   <li>Directions are represented by a small {@link Direction} enum.
 *   <li>Wall placement, adjacency checks and reachability counting are isolated in dedicated methods.
 *   <li>Clear naming, early returns and Javadoc make the flow easy to follow.
 * </ul>
 */
public class Solution {

    /** Print writer that auto‑flushes on every println. */
    private static final PrintWriter OUT = new PrintWriter(new BufferedReader(
            new InputStreamReader(System.in)), true);

    /** The four orthogonal directions used for neighbour checks. */
    private enum Direction {
        UP(-1, 0), RIGHT(0, 1), DOWN(1, 0), LEFT(0, -1);

        private final int dr;
        private final int dc;

        Direction(int dr, int dc) {
            this.dr = dr;
            this.dc = dc;
        }

        int[] delta() {
            return new int[]{dr, dc};
        }
    }

    /** Main entry point. */
    public static void main(String[] args) throws IOException {
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in))) {
            int testCases = readInt(br);
            while (testCases-- > 0) {
                int n = readInt(br);
                int m = readInt(br);
                char[][] grid = readGrid(br, n, m);
                OUT.println(isPossible(grid));
            }
        }
    }

    /** ---------------------------------------------------------------------------
     *  Public API – decides whether a configuration can be turned into a solvable
     *  one.
     */
    public static String isPossible(char[][] original) {
        // 1️⃣  No good cells → trivially YES
        int totalGood = countGood(original);
        if (totalGood == 0) {
            return "Yes";
        }

        // 2️⃣  Verify adjacency rule : a 'B' must not touch a 'G'
        if (violatesAdjacency(original)) {
            return "No";
        }

        // 3️⃣  Build a temporary grid where walls ('#') are added around every 'B'
        char[][] withWalls = buildWallsAround(original);

        // 4️⃣  Destination cell cannot be a wall
        if (withWalls[n - 1][m - 1] == '#') {
            return "No";
        }

        // 5️⃣  Reachability check from the bottom‑right corner
        int reachableGood = countReachableGood(withWalls, n, m);
        return reachableGood == totalGood ? "Yes" : "No";
    }

    // ---------------------------------------------------------------------------
    //  Helper methods – each does one well‑defined task
    // ---------------------------------------------------------------------------

    /** Reads the next integer from the reader (skipping empty lines). */
    private static int readInt(BufferedReader br) throws IOException {
        while (true) {
            String line = br.readLine();
            if (line == null) {
                throw new IOException("Unexpected end of input");
            }
            String trimmed = line.trim();
            if (!trimmed.isEmpty()) {
                return Integer.parseInt(trimmed);
            }
        }
    }

    /** Reads `rows` lines, each containing `cols` space‑separated characters. */
    private static char[][] readGrid(BufferedReader br, int rows, int cols) throws IOException {
        char[][] grid = new char[rows][cols];
        for (int r = 0; r < rows; r++) {
            String[] tokens = br.readLine().trim().split(" ");
            // Expect exactly one token of length `cols` (the problem uses space‑separated chars)
            String token = tokens[0];
            for (int c = 0; c < cols; c++) {
                grid[r][c] = token.charAt(c);
            }
        }
        return grid;
    }

    /** Counts the total number of 'G' cells in the grid. */
    private static int countGood(char[][] grid) {
        int count = 0;
        for (char[] row : grid) {
            for (char cell : row) {
                if (cell == 'G') {
                    count++;
                }
            }
        }
        return count;
    }

    /**
     * Checks whether any 'B' cell is orthogonally adjacent to a 'G'.
     * If such a neighbour exists the configuration is impossible → return true.
     */
    private static boolean violatesAdjacency(char[][] grid) {
        int n = grid.length;
        int m = grid[0].length;
        for (int r = 0; r < n; r++) {
            for (int c = 0; c < m; c++) {
                if (grid[r][c] != 'B') {
                    continue;
                }
                for (Direction d : Direction.values()) {
                    int nr = r + d.delta()[0];
                    int nc = c + d.delta()[1];
                    if (0 <= nr && nr < n && 0 <= nc && nc < m) {
                        if (grid[nr][nc] == 'G') {
                            return true;
                        }
                    }
                }
            }
        }
        return false;
    }

    /**
     * Returns a **new** grid that is a copy of {@code original} with a wall ('#')
     * placed on every empty ('.') cell that is orthogonally adjacent to a 'B'.
     * Existing 'B' and 'G' cells stay untouched.
     */
    private static char[][] buildWallsAround(char[][] original) {
        int n = original.length;
        int m = original[0].length;
        char[][] copy = new char[n][m];
        // copy unchanged cells
        System.arraycopy(original, 0, copy, 0, n * m);

        Set<Point> wallPositions = new HashSet<>();

        for (int r = 0; r < n; r++) {
            for (int c = 0; c < m; c++) {
                if (original[r][c] == 'B') {
                    for (Direction d : Direction.values()) {
                        int nr = r + d.delta()[0];
                        int nc = c + d.delta()[1];
                        if (0 <= nr && nr < n && 0 <= nc && nc < m
                                && original[nr][nc] == '.') {
                            wallPositions.add(new Point(nr, nc));
                        }
                    }
                }
            }
        }

        for (Point p : wallPositions) {
            copy[p.row][p.col] = '#';
        }
        return copy;
    }

    /** Simple immutable pair used to store wall coordinates. */
    private static final class Point {
        final int row;
        final int col;

        Point(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }

    /**
     * Counts how many 'G' cells are reachable from (row, col) moving only through
     * '.' or 'G' cells (walls block the path). Uses an explicit stack to avoid
     * deep recursion.
     */
    private static int countReachableGood(char[][] grid, int rows, int cols) {
        boolean[][] visited = new boolean[rows][cols];
        Deque<Point> stack = new ArrayDeque<>();
        stack.push(new Point(rows - 1, cols - 1));   // start at bottom‑right

        int reachable = 0;
        while (!stack.isEmpty()) {
            Point cur = stack.pop();
            int r = cur.row;
            int c = cur.col;

            if (!inBounds(r, c, rows, cols) || visited[r][c] || grid[r][c] == '#') {
                continue;
            }
            visited[r][c] = true;

            if (grid[r][c] == 'G') {
                reachable++;
            }

            for (Direction d : Direction.values()) {
                stack.push(new Point(r + d.delta()[0], c + d.delta()[1]));
            }
        }
        return reachable;
    }

    private static boolean inBounds(int r, int c, int rows, int cols) {
        return 0 <= r && r < rows && 0 <= c && c < cols;
    }
}

import java.io.*;
import java.util.*;

/**
 * Solution for a grid‑based reachability problem.
 *
 * <p>Reading input, performing a depth‑first search, and applying the required
 * checks are separated into small, well‑named methods.  Constants, enums and
 * helper classes keep the core logic clear and easy to extend.</p>
 */
public class Main {

    /* --------------------------------------------------------------------- */
    /*  Constants & helper types                                               */
    /* --------------------------------------------------------------------- */

    /** 4‑direction movement vectors (up, down, left, right). */
    private static final int[] DX = {0, 0, -1, 1};
    private static final int[] DY = {-1, 1, 0, 0};

    /** Simple container for a cell coordinate. */
    private static final class Position {
        final int row;
        final int col;

        Position(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }

    /* --------------------------------------------------------------------- */
    /*  Core algorithm                                                       */
    /* --------------------------------------------------------------------- */

    private final BufferedReader reader;
    private final StringTokenizer tokenizer;
    private final PrintWriter out;

    /** Entry point. */
    public static void main(String[] args) throws Exception {
        new Main().run();
    }

    /** Constructor – initialises I/O streams. */
    public Main() {
        reader = new BufferedReader(new InputStreamReader(System.in));
        tokenizer = null;
        out = new PrintWriter(System.out);
    }

    /** Main driver – processes every test case. */
    private void run() throws IOException {
        int tests = nextInt();
        while (tests-- > 0) {
            solveTestCase();
        }
        close();
    }

    /** Solves a single test case. */
    private void solveTestCase() throws IOException {
        readDimensionsAndGrid();

        if (!isDestinationWalkable()) {
            out.println("No");
            return;
        }

        dfs(n, m);

        if (!flag || redCount != totalRed) {
            out.println("No");
            return;
        }

        processBlockedNeighbours();

        dfs(n, m); // second traversal after modifications

        out.println((redCount == totalRed && blockedPositions.isEmpty())
                ? "Yes"
                : "No");
    }

    /* --------------------------------------------------------------------- */
    /*  Input handling                                                       */
    /* --------------------------------------------------------------------- */

    private char[][] grid;      // 1‑based indexing
    private int n, m;            // number of rows / columns
    private int redCount;        // number of 'G' reached in DFS
    private boolean flag;        // tracks whether DFS was successful
    private List<Position> blockedPositions = new ArrayList<>();

    /** Reads n, m and the grid itself. */
    private void readDimensionsAndGrid() throws IOException {
        n = nextInt();
        m = nextInt();

        grid = new char[n + 1][m + 1];
        int totalRed = 0;

        for (int i = 1; i <= n; i++) {
            String line = nextLine();
            for (int j = 1; j <= m; j++) {
                char cell = line.charAt(j - 1);
                grid[i][j] = cell;
                if (cell == 'G') {
                    totalRed++;
                }
            }
        }

        this.totalRed = totalRed;
    }

    /** Returns the number of 'G' cells we must reach during DFS. */
    private int totalRed; // used only by readDimensionsAndGrid()

    /* --------------------------------------------------------------------- */
    /*  DFS & validation                                                       */
    /* --------------------------------------------------------------------- */

    /** Performs a DFS starting from (row, col). */
    private void dfs(int row, int col) {
        if (row < 1 || row > n || col < 1 || col > m) {
            return;
        }
        if (visited[row][col] || grid[row][col] == '#') {
            return;
        }

        visited[row][col] = true;

        switch (grid[row][col]) {
            case 'G' -> redCount++;
            case 'B' -> blockedPositions.add(new Position(row, col));
        }

        for (int d = 0; d < 4; d++) {
            dfs(row + DX[d], col + DY[d]);
        }
    }

    /** Checks whether the bottom‑right cell can be entered. */
    private boolean isDestinationWalkable() {
        return grid[n][m] != '#';
    }

    /* --------------------------------------------------------------------- */
    /*  Blocked neighbour handling                                             */
    /* --------------------------------------------------------------------- */

    /** Scans all 'B' cells and validates their neighbours. */
    private void processBlockedNeighbours() {
        blockedPositions.clear();

        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= m; j++) {
                if (grid[i][j] == 'B') {
                    for (int d = 0; d < 4; d++) {
                        int nr = i + DX[d];
                        int nc = j + DY[d];
                        if (!inBounds(nr, nc)) {
                            continue;
                        }
                        char neigh = grid[nr][nc];
                        if (neigh == 'G') {
                            out.println("No");
                            throw new RuntimeException(); // abort current test
                        }
                        if (neigh == '.') {
                            grid[nr][nc] = '#'; // block the cell
                        }
                    }
                }
            }
        }
    }

    private boolean inBounds(int r, int c) {
        return r >= 1 && r <= n && c >= 1 && c <= m;
    }

    /* --------------------------------------------------------------------- */
    /*  Utility methods                                                       */
    /* --------------------------------------------------------------------- */

    /** Simple 2‑D boolean visited matrix (re‑initialised for each DFS). */
    private boolean[][] visited = new boolean[0][0];

    /** Reads the next token from the input stream. */
    private String nextToken() throws IOException {
        while (tokenizer == null || !tokenizer.hasMoreTokens()) {
            tokenizer = new StringTokenizer(reader.readLine());
        }
        return tokenizer.nextToken();
    }

    /** Reads a whole line from the input stream. */
    private String nextLine() throws IOException {
        return reader.readLine();
    }

    /** Reads an integer token. */
    private int nextInt() throws IOException {
        return Integer.parseInt(nextToken());
    }

    /** Reads a long token. */
    private long nextLong() throws IOException {
        return Long.parseLong(nextToken());
    }

    /** Reads a double token. */
    private double nextDouble() throws IOException {
        return Double.parseDouble(nextToken());
    }

    /** Closes all I/O streams. */
    private void close() throws IOException {
        reader.close();
        out.close();
    }
}

import java.io.*;
import java.util.*;

/**
 *  Refactored solution that keeps the original functionality
 *  (reading a grid, validating bomb neighbourhoods and performing
 *  a DFS from the first 'G' cell) but is much easier to read,
 *  maintain and extend.
 */
public class Main {

    /* ------------------------------------------------------------------ *
     *  Constants that describe the different cell types used in the grid *
     * ------------------------------------------------------------------ */
    private static final int EMPTY   = 0; // originally '.'
    private static final int OBSTACLE = 1; // cells visited during validation
    private static final int BOMB    = 2; // originally 'B'
    private static final int GOAL    = 3; // originally 'G'

    /* ------------------------------------------------------------------ *
     *  Small helper class that encapsulates the input reader             *
     * ------------------------------------------------------------------ */
    private static final class Reader {
        private final BufferedReader br;
        private StringTokenizer st;

        Reader(InputStream source) {
            this.br = new BufferedReader(new InputStreamReader(source));
        }

        /** Returns the next token, blocking until one is available. */
        String next() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                String line = br.readLine();
                if (line == null) {
                    return null;
                }
                st = new StringTokenizer(line);
            }
            return st.nextToken();
        }

        /** Convenience wrapper for nextInt(). */
        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }

    /* ------------------------------------------------------------------ *
     *  Simple (row, column) pair                                           *
     * ------------------------------------------------------------------ */
    private static final class Position {
        final int row;
        final int col;
        Position(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }

    /* ------------------------------------------------------------------ *
     *  Represents a single test case (grid + derived data structures)   *
     * ------------------------------------------------------------------ */
    private static final class TestCase {
        private final int rows;
        private final int cols;
        private final int[][] grid;                     // raw cell values
        private final List<Position> bombs = new ArrayList<>();
        private final List<Position> goals = new ArrayList<>();

        TestCase(Reader r) throws IOException {
            rows = r.nextInt();
            cols = r.nextInt();
            grid = new int[rows][cols];

            for (int r = 0; r < rows; ++r) {
                String line = r.next();
                for (int c = 0; c < cols; ++c) {
                    char ch = line.charAt(c);
                    if (ch == '.') {
                        grid[r][c] = EMPTY;
                    } else if (ch == '#') {
                        grid[r][c] = OBSTACLE;
                    } else if (ch == 'B') {
                        grid[r][c] = BOMB;
                        bombs.add(new Position(r, c));
                    } else if (ch == 'G') {
                        grid[r][c] = GOAL;
                        goals.add(new Position(r, c));
                    }
                }
            }
        }

        int getRows() { return rows; }
        int getCols() { return cols; }

        int getCell(int r, int c) { return grid[r][c]; }
        void setCell(int r, int c, int value) { grid[r][c] = value; }

        List<Position> getBombPositions() { return Collections.unmodifiableList(bombs); }
        List<Position> getGoalPositions() { return Collections.unmodifiableList(goals); }
    }

    /* ------------------------------------------------------------------ *
     *  Core solver that implements the algorithm described in the original *
     *  program, but with clean separation of concerns.                     *
     * ------------------------------------------------------------------ */
    private static final class Solver {
        private final TestCase tc;
        private final int[][] visited;          // reused for each DFS
        private int visitedGoalCount;
        private boolean reachedBottomRight;
        private final int startGoalRow, startGoalCol; // first 'G' found

        Solver(TestCase tc) {
            this.tc = tc;
            this.visited = new int[tc.getRows()][tc.getCols()];
            this.visitedGoalCount = 0;
            this.reachedBottomRight = false;

            // remember the first goal cell – this is the starting point of
            // the traversal in the original code.
            Position firstGoal = tc.getGoalPositions().isEmpty()
                    ? null
                    : tc.getGoalPositions().get(0);
            if (firstGoal != null) {
                this.startGoalRow = firstGoal.row;
                this.startGoalCol = firstGoal.col;
            } else {
                this.startGoalRow = -1;
                this.startGoalCol = -1;
            }
        }

        /** Entry point – returns "Yes" or "No". */
        String solve() {
            if (!validateBombNeighbourhood()) {
                return "No";
            }

            // If there are no goal cells, the answer is trivially "Yes".
            if (tc.getGoalPositions().isEmpty()) {
                return "Yes";
            }

            if (!isAccessible(startGoalRow, startGoalCol)) {
                return "No";
            }

            dfs(startGoalRow, startGoalCol);

            // The original program prints "Yes" only when we both
            // reached the bottom‑right corner and visited *all* goal cells.
            return (reachedBottomRight && visitedGoalCount == tc.getGoalPositions().size())
                    ? "Yes"
                    : "No";
        }

        /** ---------------------------------------------------------------- *
         *  1️⃣  Validate that every bomb is surrounded only by traversable
         *      cells.  The rules mimic the original `modf` function:
         *         • out‑of‑bounds neighbour → invalid
         *         • neighbour that is a goal cell → invalid
         *         • empty cells are marked as “visited” (value → OBSTACLE)
         * ---------------------------------------------------------------- */
        private boolean validateBombNeighbourhood() {
            for (Position bomb : tc.getBombPositions()) {
                for (int[] delta : new int[][]{{-1,0},{1,0},{0,-1},{0,1}}) {
                    int nr = bomb.row + delta[0];
                    int nc = bomb.col + delta[1];
                    if (!isInside(nr, nc)) {
                        return false;
                    }
                    int val = tc.getCell(nr, nc);
                    if (val == GOAL) {
                        return false;                 // goal directly next to a bomb
                    }
                    if (val == EMPTY) {
                        tc.setCell(nr, nc, OBSTACLE);   // mark as visited (like original)
                    }
                }
            }
            return true;
        }

        /** ---------------------------------------------------------------- *
         *  2️⃣  Depth‑first search that respects the movement constraints of
         *      the original program:
         *         • can move only to cells that are not obstacles (1) or bombs (2)
         *         • cannot revisit already visited cells
         *         • counts how many goal cells are visited
         *         • remembers whether the bottom‑right cell was reached
         * ---------------------------------------------------------------- */
        private void dfs(int r, int c) {
            visited[r][c] = 1;               // mark as visited

            // Count a goal cell when we step on it.
            if (tc.getCell(r, c) == GOAL) {
                visitedGoalCount++;
            }

            // Did we just reach the bottom‑right corner?
            if (r == tc.getRows() - 1 && c == tc.getCols() - 1) {
                reachedBottomRight = true;
            }

            // Explore the four orthogonal neighbours.
            int[][] dirs = {{-1,0},{1,0},{0,-1},{0,1}};
            for (int[] d : dirs) {
                int nr = r + d[0];
                int nc = c + d[1];
                if (isAccessible(nr, nc)) {
                    dfs(nr, nc);
                    // Early exit – mirrors the short‑circuit behaviour of original code.
                    if (reachedBottomRight) {
                        return;
                    }
                }
            }
        }

        /** Determines whether a given cell can be entered. */
        private boolean isAccessible(int r, int c) {
            return isInside(r, c) && tc.getCell(r, c) != OBSTACLE && tc.getCell(r, c) != BOMB && visited[r][c] == 0;
        }

        /** Checks bounds of a coordinate pair. */
        private boolean isInside(int r, int c) {
            return r >= 0 && r < tc.getRows() && c >= 0 && c < tc.getCols();
        }
    }

    /* ------------------------------------------------------------------ *
     *  Main driver – reads multiple test cases, runs the solver and       *
     *  prints the collected answers.                                       *
     * ------------------------------------------------------------------ */
    public static void main(String[] args) throws Exception {
        // Use try‑with‑resources to guarantee the underlying stream is closed.
        try (InputStream source = System.in) {
            Reader reader = new Reader(source);
            StringBuilder output = new StringBuilder();

            int testCases = reader.nextInt();
            for (int tc = 0; tc < testCases; ++tc) {
                TestCase test = new TestCase(reader);
                Solver solver = new Solver(test);
                output.append(solver.solve()).append('\n');
            }

            System.out.print(output.toString());
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Solution – reads a grid, analyses reachability of special cells
 * and prints whether the required condition is satisfied.
 *
 * The program is deliberately split into small, well‑named pieces
 * so that each responsibility (I/O, parsing, logic) can be tested
 * and understood independently.
 */
public class Solution {

    /** Simple wrapper around {@link BufferedReader} that tokenises input. */
    private static final class InputReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        InputReader(final InputStream source) {
            this.reader = new BufferedReader(new InputStreamReader(source));
        }

        /** Returns the next token, reading a new line when needed. */
        private String nextToken() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                tokenizer = new StringTokenizer(reader.readLine());
            }
            return tokenizer.nextToken();
        }

        int nextInt() throws IOException { return Integer.parseInt(nextToken()); }
        long nextLong() throws IOException { return Long.parseLong(nextToken()); }
        double nextDouble() throws IOException { return Double.parseDouble(nextToken()); }
        String next() throws IOException { return nextToken(); }
    }

    /** Directions used for neighbour traversal – keeps magic numbers out of the code. */
    private static final int[][] NEIGHBOURS = {
            {-1, 0}, {0, -1}, {1, 0}, {0, 1}
    };

    /** Small immutable container for a grid coordinate. */
    private static final class Coord {
        final int row;
        final int col;

        Coord(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }

    /**
     * Main driver.
     *
     * @param args command line arguments (unused)
     */
    public static void main(String[] args) throws IOException {
        try (InputReader in = new InputReader(System.in)) {

            final int testCases = in.nextInt();

            for (int caseIdx = 0; caseIdx < testCases; caseIdx++) {
                solveSingleTestCase(in);
            }
        }
    }

    /**
     * Handles parsing, processing and output for one grid.
     *
     * @param in the input reader positioned at the start of the test case
     */
    private static void solveSingleTestCase(InputReader in) throws IOException {
        final int n = in.nextInt();   // number of rows
        final int m = in.nextInt();   // number of columns

        // -----------------------------------------------------------------
        // 1️⃣  Parse the grid and remember the positions of all "good" cells.
        // -----------------------------------------------------------------
        final Cell[][] grid = new Cell[n][m];
        final List<Coord> goodCoordinates = new ArrayList<>();

        for (int r = 0; r < n; r++) {
            final String line = in.next();
            for (int c = 0; c < m; c++) {
                final char ch = line.charAt(c);
                grid[r][c] = cellFromChar(ch);
                if (grid[r][c] == Cell.GOOD) {
                    goodCoordinates.add(new Coord(r, c));
                }
            }
        }

        // -----------------------------------------------------------------
        // 2️⃣  Propagate reachability constraints: neighbours of cells that
        //     are currently “unresolved” (value 4) are marked as blocked (2)
        //     unless they are already a good cell.
        // -----------------------------------------------------------------
        propagateConstraints(grid, n, m);

        // -----------------------------------------------------------------
        // 3️⃣  BFS from the bottom‑right corner (n‑1, m‑1) counting visited
        //     good cells.  Encountering an empty cell (value 4) invalidates
        //     the path – we use {@code Integer.MIN_VALUE} to signal failure.
        // -----------------------------------------------------------------
        final int reachableGoodCount = bfsCountGoodCells(grid, n, m);

        // -----------------------------------------------------------------
        // 4️⃣  The required condition is that exactly half of the good cells
        //     are reachable.
        // -----------------------------------------------------------------
        final boolean success = reachableGoodCount == goodCoordinates.size() / 2;
        System.out.println(success ? "Yes" : "No");
    }

    /** Converts a character representation into the internal {@link Cell} enum. */
    private static Cell cellFromChar(char ch) {
        return switch (ch) {
            case '.'  -> Cell.EMPTY;
            case '#'  -> Cell.WALL;
            case 'G'  -> Cell.GOOD;
            default   -> Cell.UNKNOWN;
        };
    }

    /**
     * Marks cells adjacent to “unresolved” cells (value 4) as blocked (2)
     * if the neighbour is not already a good cell.
     */
    private static void propagateConstraints(Cell[][] grid, int rows, int cols) {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == Cell.UNKNOWN) {
                    for (int[] dir : NEIGHBOURS) {
                        int nr = r + dir[0];
                        int nc = c + dir[1];
                        if (isInBounds(nr, nc, rows, cols) && grid[nr][nc] != Cell.GOOD) {
                            grid[nr][nc] = Cell.WALL;
                        }
                    }
                }
            }
        }
    }

    /** Checks whether a coordinate lies inside the grid. */
    private static boolean isInBounds(int r, int c, int rows, int cols) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    /**
     * Performs a breadth‑first search starting at the bottom‑right corner.
     * It returns the number of GOOD cells encountered on a valid path,
     * or {@code Integer.MIN_VALUE} if an UNKNOWN cell is visited.
     */
    private static int bfsCountGoodCells(Cell[][] grid, int rows, int cols) {
        final boolean[][] visited = new boolean[rows][cols];
        final Deque<Coord> queue = new ArrayDeque<>();
        queue.add(new Coord(rows - 1, cols - 1));

        int foundGood = 0;

        while (!queue.isEmpty()) {
            final Coord cur = queue.pollFirst();
            final int r = cur.row;
            final int c = cur.col;

            if (visited[r][c] || grid[r][c] == Cell.WALL) {
                continue;
            }

            visited[r][c] = true;

            switch (grid[r][c]) {
                case GOOD -> foundGood++;
                case UNKNOWN -> foundGood = Integer.MIN_VALUE; // path invalidated
            }

            for (int[] dir : NEIGHBOURS) {
                int nr = r + dir[0];
                int nc = c + dir[1];
                if (isInBounds(nr, nc, rows, cols) && !visited[nr][nc]) {
                    queue.add(new Coord(nr, nc));
                }
            }
        }
        return foundGood;
    }

    /** Enum representing the semantics of each cell type. */
    private enum Cell {
        EMPTY,      // '.' – traversable empty space
        WALL,       // '#' – permanent obstacle
        GOOD,       // 'G' – special target cell
        UNKNOWN     // any other character (treated as traversable but may be marked)
    }
}

/**
 * Refactored solution for the “Maze” problem (Codeforces‑style).
 *
 * <p>Changes made for readability and maintainability:</p>
 * <ul>
 *   <li>Extracted constants and direction vectors.</li>
 *   <li>Used descriptive field and method names.</li>
 *   <li>Separated concerns (input handling, algorithm, output).</li>
 *   <li>Avoided magic numbers and raw array accesses.</li>
 *   <li>Added Javadoc comments.</li>
 *   <li>Improved encapsulation and constructor use.</li>
 *   <li>Kept the original algorithmic behaviour.</li>
 * </ul>
 */
import java.io.*;
import java.util.*;

public class SolveMazeCF {

    /** Directions: up, down, left, right */
    private static final int[][] DIRS = {{0, 1}, {0, -1}, {1, 0}, {-1, 0}};

    private final InputReader input;
    private final PrintWriter output;

    /**
     * Constructs the solver with the given {@link InputReader} and {@link PrintWriter}.
     */
    public SolveMazeCF(InputReader input, PrintWriter output) {
        this.input = input;
        this.output = output;
    }

    /** Checks whether a cell lies inside the bounds of the maze. */
    private boolean isInside(int row, int col, char[][] grid) {
        return row >= 0 && row < grid.length && col >= 0 && col < grid[0].length;
    }

    /**
     * Depth‑first search that counts reachable goal cells.
     *
     * @param grid      the maze representation
     * @param visited   visited flag matrix
     * @param r         current row
     * @param c         current column
     * @return number of goal cells reachable from (r,c)
     */
    private int countReachableGoals(char[][] grid, boolean[][] visited, int r, int c) {
        visited[r][c] = true;
        int count = (grid[r][c] == 'G' ? 1 : 0);

        for (int[] dir : DIRS) {
            int nr = r + dir[0];
            int nc = c + dir[1];
            if (!isInside(nr, nc, grid)
                    || visited[nr][nc]
                    || grid[nr][nc] == '#') {
                continue;
            }
            count += countReachableGoals(grid, visited, nr, nc);
        }
        return count;
    }

    /** Solves a single test case. */
    private void solve() throws IOException {
        int rows = input.nextInt();
        int cols = input.nextInt();

        char[][] grid = new char[rows][];
        for (int i = 0; i < rows; i++) {
            grid[i] = input.nextLine().toCharArray();
        }

        int totalGoals = 0;

        /* --------------------------------------------------------------
         *  1️⃣  Verify that no bomb ('B') is orthogonally adjacent to a goal ('G').
         *  2️⃣  Surround each bomb with walls ('#') on every empty ('.') neighbour.
         * -------------------------------------------------------------- */
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == 'G') {
                    totalGoals++;
                } else if (grid[r][c] == 'B') {
                    for (int[] dir : DIRS) {
                        int nr = r + dir[0];
                        int nc = c + dir[1];
                        if (isInside(nr, nc, grid)) {
                            if (grid[nr][nc] == 'G') {
                                output.println("No");
                                return;
                            }
                            if (grid[nr][nc] == '.') {
                                grid[nr][nc] = '#';
                            }
                        }
                    }
                }
            }
        }

        /* --------------------------------------------------------------
         *  Determine reachability of goals from the destination cell (bottom‑right).
         * -------------------------------------------------------------- */
        boolean[][] visited = new boolean[rows][cols];
        int reachableGoals = 0;
        char destination = grid[rows - 1][cols - 1];
        if (destination != '#') {
            reachableGoals = countReachableGoals(grid, visited, rows - 1, cols - 1);
        }

        output.println(reachableGoals == totalGoals ? "Yes" : "No");
    }

    /** Executes multiple test cases until input is exhausted. */
    public void run() throws Exception {
        int tests = input.nextInt();
        while (tests-- > 0) {
            solve();
        }
        output.close();
    }

    /** Simple wrapper around {@link PrintWriter} for one‑line output. */
    private void print(Object o) {
        output.print(o);
    }

    /** Simple wrapper around {@link PrintWriter} for a line break. */
    private void println(Object o) {
        output.println(o);
    }

    /** Wrapper for an empty line. */
    private void println() {
        output.println();
    }

    /** Utility class that parses input tokens from {@link InputStream}. */
    public static class InputReader {
        private final BufferedReader br;
        private StringTokenizer st;

        /** Creates a reader that consumes from standard input. */
        public InputReader() {
            this.br = new BufferedReader(new InputStreamReader(System.in));
        }

        /** Creates a reader that consumes from a supplied file name (not used here). */
        public InputReader(String fileName) throws IOException {
            this.br = new BufferedReader(new FileReader(fileName));
        }

        /** Returns the next token, tokenising the current line if necessary. */
        public String next() throws Exception {
            if (st == null || !st.hasMoreElements()) {
                st = new StringTokenizer(br.readLine());
            }
            return st.nextToken();
        }

        /** Returns the next complete line of input. */
        public String nextLine() throws Exception {
            String line = "";
            try {
                line = br.readLine();
            } catch (IOException e) {
                throw new Exception(e.toString());
            }
            return line;
        }

        /** Reads the next integer (converted with {@link Integer#parseInt}). */
        public int nextInt() throws Exception {
            return Integer.parseInt(next());
        }
    }

    /** Entry point – creates the reader, the writer and starts the solving loop. */
    public static void main(String[] args) throws Exception {
        InputReader reader = new InputReader();
        PrintWriter writer = new PrintWriter(System.out);
        new SolveMazeCF(reader, writer).run();
    }
}

import java.util.LinkedList;
import java.util.Queue;
import java.util.Scanner;

/**
 * Utility class that encapsulates all operations related to maze solving.
 */
public final class MazeSolver {

    /** Private constructor – utility class. */
    private MazeSolver() { }

    /** Represents a cell in the maze. */
    private static final class Cell {
        final int row;
        final int col;

        Cell(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }

    /**
     * Returns the number of grass cells ('G') reachable from the bottom‑right corner,
     * moving only through non‑blocked ('#') cells and not stepping on a bear ('B').
     *
     * @param maze   The maze represented as a 2‑D array of characters.
     * @return     Count of reachable grass cells, or -1 if a bear is encountered.
     */
    public static int countReachableGrass(char[][] maze) {
        final int rows = maze.length;
        final int cols = maze[0].length;
        final boolean[][] visited = new boolean[rows][cols];
        final Queue<Cell> queue = new LinkedList<>();

        // start from the bottom‑right corner
        Cell start = new Cell(rows - 1, cols - 1);
        queue.add(start);
        visited[rows - 1][cols - 1] = true;

        int grassCount = 0;

        // Directions: up, left, right, down
        final int[] dx = {-1, 0, 0, 1};
        final int[] dy = {0, -1, 1, 0};

        while (!queue.isEmpty()) {
            Cell cur = queue.remove();

            // If a bear blocks the way, this path is invalid
            if (maze[cur.row][cur.col] == 'B') {
                return -1;
            }

            // Count grass cells
            if (maze[cur.row][cur.col] == 'G') {
                grassCount++;
            }

            // Explore neighbours
            for (int dir = 0; dir < dx.length; dir++) {
                int nr = cur.row + dx[dir];
                int nc = cur.col + dy[dir];

                if (isInBounds(maze, nr, nc) && canEnter(maze, nr, nc, visited)) {
                    visited[nr][nc] = true;
                    queue.add(new Cell(nr, nc));
                }
            }
        }
        return grassCount;
    }

    /** Validates coordinates and checks if the target cell can be entered. */
    private static boolean isInBounds(char[][] maze, int r, int c) {
        return r >= 0 && r < maze.length && c >= 0 && c < maze[0].length;
    }

    /** Returns true if the cell is not blocked and has not been visited yet. */
    private static boolean canEnter(char[][] maze, int r, int c, boolean[][] visited) {
        return !visited[r][c] &&
               maze[r][c] != '#' &&     // cannot step on a wall
               maze[r][c] != 'B';       // cannot step on a bear
    }

    /* ---------------------------------------------------------------------------
       Helper methods used by the main algorithm (pre‑processing of bears)
       --------------------------------------------------------------------------- */

    /**
     * Checks whether a bear adjacent to a grass cell would make the maze unsolvable.
     * Also builds a protective wall ('#') around bears where possible.
     *
     * @param maze    The maze to modify in‑place.
     * @return      true if no conflict was found; false indicates an immediate “No”.
     */
    public static boolean processBearAdjacencies(char[][] maze) {
        final int rows = maze.length;
        final int cols = maze[0].length;

        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (maze[r][c] != 'B') {
                    continue;
                }

                // Store directions where a grass cell might be adjacent
                int[] dr = {-1, 0, 0, 1};
                int[] dc = {0, -1, 1, 0};

                for (int i = 0; i < dr.length; i++) {
                    int nr = r + dr[i];
                    int nc = c + dc[i];

                    if (!isInBounds(maze, nr, nc)) {
                        continue;
                    }

                    // Conflict with grass cell → impossible to win
                    if (maze[nr][nc] == 'G') {
                        return false;
                    }

                    // Build a wall next to the bear if the neighbour is empty
                    if (maze[nr][nc] == '.') {
                        maze[nr][nc] = '#';
                    }
                }
            }
        }
        return true;
    }

    /** Returns true if the exit cell (bottom‑right) is not blocked by a wall. */
    public static boolean isExitOpen(char[][] maze) {
        return maze[maze.length - 1][maze[0].length - 1] != '#';
    }
}

/* ---------------------------------------------------------------------------
   Main class – thin wrapper around the solver utilities
   --------------------------------------------------------------------------- */
class Main {

    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {

            int testCases = scanner.nextInt();

            while (testCases-- > 0) {
                int rows = scanner.nextInt();
                int cols = scanner.nextInt();

                char[][] maze = readMaze(scanner, rows, cols);

                // 1️⃣  Count total grass cells in the original maze
                final int totalGrass = countGrassCells(maze);

                // 2️⃣  Process bear adjacencies and decide early outcome
                boolean pathPossible = MazeSolver.processBearAdjacencies(maze);
                boolean exitOpen = MazeSolver.isExitOpen(maze);

                if (totalGrass == 0) {
                    System.out.println("Yes");
                } else if (!pathPossible) {
                    System.out.println("No");
                } else if (!exitOpen) {
                    System.out.println("No");
                } else {
                    int reachable = MazeSolver.countReachableGrass(maze);
                    System.out.println(reachable == totalGrass ? "Yes" : "No");
                }
            }
        }
    }

    /** Reads the grid for a single test case. */
    private static char[][] readMaze(Scanner scanner, int rows, int cols) {
        char[][] maze = new char[rows][cols];
        for (int r = 0; r < rows; r++) {
            String line = scanner.next();
            for (int c = 0; c < cols; c++) {
                maze[r][c] = line.charAt(c);
            }
        }
        return maze;
    }

    /** Helper used only before calling the solver – counts 'G' cells. */
    private static int countGrassCells(char[][] maze) {
        int count = 0;
        for (char[] row : maze) {
            for (char cell : row) {
                if (cell == 'G') {
                    count++;
                }
            }
        }
        return count;
    }
}

import java.util.ArrayDeque;
import java.util.Arrays;
import java.util.Queue;

/**
 * Reads multiple mazes from standard input and determines, for each,
 * whether all gold medals ('G') are reachable from the bottom‑right
 * corner while no bear ('B') is reachable.
 */
public class Main {

    /** Offsets for the four orthogonal directions. */
    private static final int[] DR = {-1, 1, 0, 0};
    /** Offsets for the four orthogonal directions. */
    private static final int[] DC = {0, 0, -1, 1};

    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            int testCases = Integer.parseInt(scanner.next());
            StringBuilder output = new StringBuilder();

            for (int t = 0; t < testCases; t++) {
                int rows = Integer.parseInt(scanner.next());
                int cols = Integer.parseInt(scanner.next());

                char[][] board = buildBoard(scanner, rows, cols);
                enlargeBoard(board);

                isolateAdjacentEmptySpaces(board);
                int[][] distances = breadthFirstSearch(board, rows + 2, cols + 2);
                output.append(conclude(board, distances, rows, cols));
            }

            System.out.print(output);
        }
    }

    /**
     * Constructs the playing field from the input, adding an outer wall
     * of '#' characters around the user‑provided maze.
     */
    private static char[][] buildBoard(Scanner scanner, int rows, int cols) {
        char[][] board = new char[rows + 2][cols + 2];
       Arrays.fill(board[0], '#');
        Arrays.fill(board[rows + 1], '#');

        for (int r = 1; r <= rows; r++) {
            String line = "#" + scanner.next() + "#";
            board[r] = line.toCharArray();
        }
        return board;
    }

    /** Expands the board to include the border of wall cells. */
    private static void enlargeBoard(char[][] board) {
        // Upper and lower borders already filled.
        // Fill left and right borders column by column.
        for (int r = 1; r < board.length - 1; r++) {
            board[r][0] = '#';
            board[r][board[r].length - 1] = '#';
        }
    }

    /**
     * For every bear ('B') in the maze, turn every adjacent empty cell ('.')
     * into a wall ('#') so that bears cannot move out of their own square.
     */
    private static void isolateAdjacentEmptySpaces(char[][] board) {
        for (int r = 1; r < board.length - 1; r++) {
            for (int c = 1; c < board[r].length - 1; c++) {
                if (board[r][c] != 'B') {
                    continue;
                }
                for (int d = 0; d < 4; d++) {
                    int nr = r + DR[d];
                    int nc = c + DC[d];
                    if (board[nr][nc] == '.') {
                        board[nr][nc] = '#';
                    }
                }
            }
        }
    }

    /**
     * Performs a breadth‑first search from the bottom‑right corner.
     * Returns a 2‑D array with the distance to each reachable cell,
     * or -1 for unreachable cells.
     */
    private static int[][] breadthFirstSearch(char[][] board, int rows, int cols) {
        int[][] dist = new int[rows][cols];
        for (int[] row : dist) {
            Arrays.fill(row, -1);
        }

        if (board[rows - 1][cols - 1] == '#') {
            return dist; // destination is blocked; nothing reachable.
        }

        Queue<Point> queue = new ArrayDeque<>();
        Point start = new Point(rows - 1, cols - 1);
        dist[start.row][start.col] = 0;
        queue.add(start);

        while (!queue.isEmpty()) {
            Point cur = queue.poll();
            for (int d = 0; d < 4; d++) {
                int nr = cur.row + DR[d];
                int nc = cur.col + DC[d];
                Point neighbor = new Point(nr, nc);
                if (isValid(neighbor, board) && dist[nr][nc] == -1) {
                    dist[nr][nc] = dist[cur.row][cur.col] + 1;
                    queue.add(neighbor);
                }
            }
        }
        return dist;
    }

    /** Checks whether a coordinate lies inside the board and is not a wall. */
    private static boolean isValid(Point p, char[][] board) {
        return 0 <= p.row && p.row < board.length &&
               0 <= p.col && p.col < board[0].length &&
               board[p.row][p.col] != '#';
    }

    /**
     * Determines whether all gold medals are reachable and no bear is reachable.
     * Returns a formatted response for the current test case.
     */
    private static String conclude(char[][] board, int[][] distances, int rows, int cols) {
        for (int r = 1; r <= rows; r++) {
            for (int c = 1; c <= cols; c++) {
                char cell = board[r][c];
                if ((cell == 'G' && distances[r][c] == -1) ||
                    (cell == 'B' && distances[r][c] != -1)) {
                    return "No";
                }
            }
        }
        return "Yes";
    }

    /** Simple container for a cell coordinate. */
    private static final class Point {
        final int row;
        final int col;

        Point(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }
}

import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Deque;
import java.util.List;
import java.util.Scanner;

/**
 * Utility class that encapsulates the logic for processing a single test case.
 */
final class TestCaseProcessor {

    /** Symbols used in the input grid. */
    private enum CellType { EMPTY, WALL, GOAL, TRAP }

    /** Simple immutable container for a cell coordinate. */
    private static final class Coord {
        final int row;
        final int col;

        Coord(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }

    /** Directions used for moving in the grid. */
    private static final int[][] DIRS = {
            {1, 0},   // down
            {-1, 0},  // up
            {0, 1},   // right
            {0, -1}   // left
    };

    private final char[][] rawGrid;   // grid read directly from input (char values)
    private final CellType[][] grid;  // typed representation of the same grid
    private final List<Coord> traps;   // coordinates of cells that contain 'g'

    /** Number of goal cells ('G') that have not been visited yet. */
    private int remainingGoals;

    TestCaseProcessor(char[][] inputGrid, List<Coord> traps) {
        this.rawGrid = inputGrid;
        this.traps = traps;
        this.grid = convertToCellType();
        this.remainingGoals = countGoals();
    }

    /** Converts the raw character grid into a typed version. */
    private CellType[][] convertToCellType() {
        CellType[][] typed = new CellType[rawGrid.length][rawGrid[0].length];
        for (int r = 0; r < rawGrid.length; r++) {
            for (int c = 0; c < rawGrid[0].length; c++) {
                typed[r][c] = mapCell(rawGrid[r][c]);
            }
        }
        return typed;
    }

    /** Maps a single character to its {@link CellType}. */
    private CellType mapCell(char ch) {
        switch (ch) {
            case '#': return CellType.WALL;
            case '.': return CellType.EMPTY;
            case 'G': return CellType.GOAL;
            case 'g': return CellType.TRAP;
            default:  throw new IllegalArgumentException("Unexpected character: " + ch);
        }
    }

    /** Counts how many GOAL cells are present in the grid. */
    private int countGoals() {
        int cnt = 0;
        for (CellType[] row : grid) {
            for (CellType cell : row) {
                if (cell == CellType.GOAL) {
                    cnt++;
                }
            }
        }
        return cnt;
    }

    /** Marks all cells adjacent to any trap with a WALL, unless they already contain one. */
    private void markTrapsInfluence() {
        int rows = grid.length;
        int cols = grid[0].length;

        for (Coord trap : traps) {
            for (int[] d : DIRS) {
                int nr = trap.row + d[0];
                int nc = trap.col + d[1];
                if (isInside(nr, nc) && grid[nr][nc] == CellType.EMPTY) {
                    grid[nr][nc] = CellType.WALL;
                }
            }
        }
    }

    /** Checks whether a given coordinate is inside the grid bounds. */
    private boolean isInside(int r, int c) {
        return r >= 0 && r < grid.length && c >= 0 && c < grid[0].length;
    }

    /** Returns true if the cell at (r,c) can be entered (i.e., it is not a wall or trap). */
    private boolean isEnterable(int r, int c) {
        CellType type = grid[r][c];
        return type != CellType.WALL && type != CellType.TRAP;
    }

    /**
     * Determines whether the whole labyrinth can be cleared.
     * The algorithm performs a DFS from the bottom‑right corner,
     * visiting every reachable cell and decrementing the goal counter
     * each time it encounters a GOAL cell.
     *
     * @return {@code true} if all GOAL cells are reachable and the search finishes
     *         without hitting an unreachable trap cell, otherwise {@code false}.
     */
    boolean canClearLabyrinth() {
        int rows = grid.length;
        int cols = grid[0].length;

        // Starting point is the bottom‑right corner.
        if (!isEnterable(rows - 1, cols - 1)) {
            return false;
        }

        Deque<Coord> stack = new ArrayDeque<>();
        stack.push(new Coord(rows - 1, cols - 1));

        // Visited cells are marked with a special sentinel value to avoid revisiting.
        boolean[][] visited = new boolean[rows][cols];

        while (!stack.isEmpty()) {
            Coord cur = stack.pop();
            int r = cur.row;
            int c = cur.col;

            if (visited[r][c]) {
                continue;
            }
            visited[r][c] = true;

            CellType type = grid[r][c];
            if (type == CellType.TRAP) {
                // Encountered an unreachable trap – the labyrinth cannot be cleared.
                return false;
            }
            if (type == CellType.GOAL) {
                remainingGoals--;
            }
            // Mark the cell as “processed” by turning it into a wall;
            // this also guarantees we will not revisit it.
            grid[r][c] = CellType.WALL;

            // Explore neighbours.
            for (int[] d : DIRS) {
                int nr = r + d[0];
                int nc = c + d[1];
                if (isInside(nr, nc) && isEnterable(nr, nc) && !visited[nr][nc]) {
                    stack.push(new Coord(nr, nc));
                }
            }
        }

        // Successfully cleared the labyrinth only when all goal cells were visited.
        return remainingGoals == 0;
    }
}

/** Main driver class – reads input, creates processors and prints the results. */
public class Main {

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int testCases = scanner.nextInt();
        scanner.nextLine(); // consume the newline after the integer

        StringBuilder output = new StringBuilder();

        for (int t = 0; t < testCases; t++) {
            // ----- read dimensions -----
            int rows = scanner.nextInt();
            int cols = scanner.nextInt();
            scanner.nextLine(); // consume the rest of the line

            // ----- read the grid -----
            char[][] grid = new char[rows][cols];
            List<Coord> traps = new ArrayList<>();

            for (int r = 0; r < rows; r++) {
                String line = scanner.nextLine();
                for (int c = 0; c < cols; c++) {
                    grid[r][c] = line.charAt(c);
                    if (grid[r][c] == 'g') {
                        traps.add(new Coord(r, c));
                    }
                }
            }

            // ----- process the test case -----
            TestCaseProcessor processor = new TestCaseProcessor(grid, traps);
            processor.markTrapsInfluence();

            boolean canClear = processor.canClearLabyrinth();
            output.append(canClear ? "Yes" : "No");
            if (t < testCases - 1) {
                output.append('\n');
            }
        }

        System.out.print(output.toString());
    }
}

import java.io.*;
import java.util.*;
import java.util.function.BiPredicate;

/**
 * Main entry point. Reads multiple test cases, processes each one and prints the
 * result ("Yes" or "No").
 */
public class Main {

    public static void main(String[] args) {
        FastScanner in = new FastScanner(System.in);
        FastPrinter out = new FastPrinter(System.out);
        int testCases = in.nextInt();

        for (int tc = 1; tc <= testCases; tc++) {
            solve(tc, in, out);
        }
        out.close();
    }

    /**
     * Solves a single test case.
     *
     * @param testNumber the test case number (only used for possible future extensions)
     * @param in         scanner for input data
     * @param out        printer for output data
     */
    private static void solve(int testNumber, FastScanner in, FastPrinter out) {
        int rows = in.nextInt();
        int cols = in.nextInt();

        char[][] maze = in.readCharMatrix(rows, cols);
        Grid grid = new Grid(rows, cols);

        Position exit = new Position(rows - 1, cols - 1);

        /* --------------------------------------------------------------
         *  1️⃣  Block every empty ('.') or good ('G') neighbour of a bad
         *      prisoner ('B') – unless that neighbour itself is a good
         *      prisoner, in which case the answer is immediately "No".
         * -------------------------------------------------------------- */
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (maze[r][c] == 'B') {
                    List<Position> neighbours = grid.neighbours(
                            new Position(r, c),
                            (nr, nc) -> maze[nr][nc] == '.' || maze[nr][nc] == 'G');

                    for (Position p : neighbours) {
                        if (maze[p.row][p.col] == 'G') {
                            out.no();
                            return;
                        }
                        maze[p.row][p.col] = '#';
                    }
                }
            }
        }

        /* --------------------------------------------------------------
         *  2️⃣  Explore the maze from the exit cell, ignoring walls ('#').
         * -------------------------------------------------------------- */
        boolean[][] visited = new boolean[rows][cols];
        if (maze[exit.row][exit.col] != '#') {
            dfs(exit, visited, grid, (nr, nc) -> !visited[nr][nc] && maze[nr][nc] != '#');
        }

        /* --------------------------------------------------------------
         *  3️⃣  Every good prisoner must be reachable from the exit.
         * -------------------------------------------------------------- */
        for (Position good : Grid.getGoodPositions(maze)) {
            if (!visited[good.row][good.col]) {
                out.no();
                return;
            }
        }
        out.yes();
    }

    /** Simple depth‑first search used to mark all reachable cells. */
    private static void dfs(Position node,
                            boolean[][] visited,
                            Grid grid,
                            BiPredicate<Integer, Integer> isAvailable) {
        visited[node.row][node.col] = true;
        grid.neighbours(node, isAvailable)
                .forEach(neighbor -> dfs(neighbor, visited, grid, isAvailable));
    }
}

/* --------------------------------------------------------------------- */
/* ---------------------------- Core utilities ----------------------- */
/* --------------------------------------------------------------------- */

/**
 * Represents a 2‑D grid and supplies neighbour‑generation utilities.
 */
final class Grid {
    private final int rows;
    private final int cols;

    /** Four cardinal directions. */
    private static final int[] DRI = {-1, 0, 1, 0};
    private static final int[] DRC = {0, 1, 0, -1};

    Grid(int rows, int cols) {
        this.rows = rows;
        this.cols = cols;
    }

    /** Checks whether a coordinate lies inside the grid. */
    boolean isInside(int r, int c) {
        return 0 <= r && r < rows && 0 <= c && c < cols;
    }

    /**
     * Returns all neighbours of {@code p} that satisfy {@code predicate}.
     *
     * @param p       the current position
     * @param predicate a function receiving a candidate coordinate and returning
     *                  {@code true} if it should be kept
     * @return a mutable {@link List} of neighbouring positions
     */
    List<Position> neighbours(Position p, BiPredicate<Integer, Integer> predicate) {
        List<Position> result = new ArrayList<>(4);
        for (int d = 0; d < DRI.length; d++) {
            int nr = p.row + DRI[d];
            int nc = p.col + DRC[d];
            if (isInside(nr, nc) && predicate.test(nr, nc)) {
                result.add(new Position(nr, nc));
            }
        }
        return result;
    }

    /** Returns every position that contains a good prisoner ('G'). */
    static List<Position> getGoodPositions(char[][] maze) {
        List<Position> list = new ArrayList<>();
        for (int r = 0; r < maze.length; r++) {
            for (int c = 0; c < maze[r].length; c++) {
                if (maze[r][c] == 'G') {
                    list.add(new Position(r, c));
                }
            }
        }
        return list;
    }
}

/**
 * Immutable pair of integer coordinates.
 */
final class Position {
    final int row;
    final int col;

    Position(int row, int col) {
        this.row = row;
        this.col = col;
    }

    @Override public boolean equals(Object o) {
        if (this == o) return true;
        if (!(o instanceof Position)) return false;
        Position p = (Position) o;
        return row == p.row && col == p.col;
    }

    @Override public int hashCode() {
        return 31 * row + col;
    }

    @Override public String toString() {
        return row + " " + col;
    }
}

