/* -------------------------- I/O wrappers --------------------------- */
/* --------------------------------------------------------------------- */

/**
 * Fast scanner that works with {@link BufferedReader} and {@link StringTokenizer}.
 * Provides convenient methods for reading primitive values and matrices.
 */
final class FastScanner extends BufferedReader {
    private final StringTokenizer tokenizer;

    FastScanner(InputStream stream) {
        super(new InputStreamReader(stream), 32768);
        tokenizer = null;
    }

    /** Reads the next token, expanding it lazily. */
    String next() {
        while (tokenizer == null || !tokenizer.hasMoreTokens()) {
            try {
                tokenizer = new StringTokenizer(readLine());
            } catch (IOException e) {
                throw new UncheckedIOException(e);
            }
        }
        return tokenizer.nextToken();
    }

    /** Reads the next integer. */
    int nextInt() {
        return Integer.parseInt(next());
    }

    /** Reads an {@code n × m} matrix of characters. */
    char[][] readCharMatrix(int n, int m) {
        char[][] matrix = new char[n][];
        for (int i = 0; i < n; i++) {
            matrix[i] = next().toCharArray();
        }
        return matrix;
    }
}

/**
 * Fast printer that wraps a {@link PrintWriter}. Adds convenient {@code yes()} /
 * {@code no()} helpers for the problem statement.
 */
final class FastPrinter extends PrintWriter {
    FastPrinter(OutputStream out) {
        super(out);
    }

    /** Prints "Yes". */
    void yes() {
        println("Yes");
    }

    /** Prints "No". */
    void no() {
        println("No");
    }

    /** Closes the underlying stream. */
    void close() {
        super.close();
    }
}

import java.util.ArrayDeque;
import java.util.Deque;
import java.util.Scanner;

/**
 * Refactored solution for the maze‑analysis problem.
 * The logic is unchanged, but the code is split into small, well‑named
 * methods, uses meaningful identifiers and follows common Java conventions.
 */
public class MazeSolver {

    /** Character used for the surrounding wall. */
    private static final char WALL = '#';

    /** Simple container for a coordinate pair. */
    private static final class Pair {
        final int x;
        final int y;
        Pair(int x, int y) {
            this.x = x;
            this.y = y;
        }
    }

    /** Entry point – reads all test cases and prints the answers. */
    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            StringBuilder out = new StringBuilder();
            int testCount = scanner.nextInt();
            for (int i = 0; i < testCount; i++) {
                out.append(processTestCase(scanner)).append('\n');
            }
            System.out.print(out.toString());
        }
    }

    /** Reads one test case, solves it and returns the result ("Yes"/"No"). */
    private static String processTestCase(Scanner in) {
        int rows = in.nextInt();          // interior rows (n)
        int cols = in.nextInt();          // interior columns (m)

        // Build the maze with a border of WALL characters around it.
        char[][] maze = buildMaze(rows, cols, in);

        int goodCount = countGoodCells(maze);
        boolean impossible = false;

        // ----- 1. Verify that every 'B' can be safely expanded -----
        for (int i = 1; i <= rows; i++) {
            for (int j = 1; j <= cols; j++) {
                if (maze[i][j] == 'B') {
                    if (!expandBlockIfSafe(maze, i, j)) {
                        impossible = true;
                        break;
                    }
                }
            }
            if (impossible) {
                break;
            }
        }
        if (impossible) {
            return "No";
        }

        // ----- 2. The exit cell must not be a wall when there are good cells -----
        if (maze[rows][cols] == WALL && goodCount != 0) {
            return "No";
        }

        // ----- 3. Flood‑fill from the bottom‑right corner (rows, cols) -----
        int remainingGood = bfsFromExit(maze, rows, cols, goodCount);

        // ----- 4. All good cells must be reachable -----
        return remainingGood == 0 ? "Yes" : "No";
    }

    /** Creates the maze array and fills the outer border with WALL. */
    private static char[][] buildMaze(int interiorRows, int interiorCols, Scanner in) {
        char[][] maze = new char[interiorRows + 2][interiorCols + 2];
        fillBorder(maze);
        for (int i = 1; i <= interiorRows; i++) {
            String line = in.next();
            for (int j = 1; j <= interiorCols; j++) {
                maze[i][j] = line.charAt(j - 1);
            }
        }
        return maze;
    }

    /** Fills the outermost layer of the maze with WALL. */
    private static void fillBorder(char[][] maze) {
        int rows = maze.length;
        int cols = maze[0].length;
        for (int i = 0; i < rows; i++) {
            maze[i][0] = WALL;
            maze[i][cols - 1] = WALL;
        }
        for (int j = 0; j < cols; j++) {
            maze[0][j] = WALL;
            maze[rows - 1][j] = WALL;
        }
    }

    /** Counts how many 'G' cells are present in the interior of the maze. */
    private static int countGoodCells(char[][] maze) {
        int count = 0;
        for (int i = 1; i < maze.length - 1; i++) {
            for (int j = 1; j < maze[0].length - 1; j++) {
                if (maze[i][j] == 'G') {
                    count++;
                }
            }
        }
        return count;
    }

    /**
     * Attempts to expand a blocker ('B') by converting adjacent '.' into walls.
     * If any adjacent cell already contains 'G' the expansion is illegal.
     *
     * @return {@code true} if the expansion was possible and performed,
     *         {@code false} if it collided with a 'G'.
     */
    private static boolean expandBlockIfSafe(char[][] maze, int i, int j) {
        for (int step : new int[]{-1, 1}) {
            // up / down
            int ni = i + step;
            if (maze[ni][j] == 'G') {
                return false;
            }
            if (maze[ni][j] == '.') {
                maze[ni][j] = WALL;
            }

            // left / right
            int nj = j + step;
            if (maze[i][nj] == 'G') {
                return false;
            }
            if (maze[i][nj] == '.') {
                maze[i][nj] = WALL;
            }
        }
        return true;
    }

    /**
     * Bread‑first search starting from the bottom‑right interior cell.
     * It consumes '.' cells and reduces the {@code remainingGood} counter
     * whenever a 'G' cell is encountered.
     *
     * @param maze        the maze matrix (modified in‑place)
     * @param endX        row index of the exit cell (rows)
     * @param endY        column index of the exit cell (cols)
     * @param goodCount   initial number of 'G' cells
     * @return the number of 'G' cells that remain un‑consumed
     */
    private static int bfsFromExit(char[][] maze, int endX, int endY, int goodCount) {
        Deque<Pair> queue = new ArrayDeque<>();
        queue.add(new Pair(endX, endY));

        int remaining = goodCount;
        while (!queue.isEmpty()) {
            Pair cur = queue.poll();

            for (int step : new int[]{-1, 1}) {
                // vertical neighbour
                processNeighbour(maze, cur.x + step, cur.y, remaining, queue);
                // horizontal neighbour
                processNeighbour(maze, cur.x, cur.y + step, remaining, queue);
            }
        }
        return remaining;
    }

    /**
     * Handles a single neighbour cell during the BFS.
     * If the cell contains 'G' it is marked as visited and the good‑counter
     * is decremented; if it contains '.' it is simply turned into a wall.
     */
    private static void processNeighbour(char[][] maze,
                                         int x, int y,
                                         int[] remainingGood,
                                         Deque<Pair> queue) {
        if (x < 0 || y < 0 || x >= maze.length || y >= maze[0].length) {
            return;
        }
        switch (maze[x][y]) {
            case 'G' ->
                // consume a good cell
                maze[x][y] = WALL;
                remainingGood[0]--;
                queue.add(new Pair(x, y));
            case '.' ->
                // turn empty space into wall so it is not processed again
                maze[x][y] = WALL;
                queue.add(new Pair(x, y));
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Refactored solution for the “block bad people and check good people can escape”
 * problem.  The program follows a clear structure, uses meaningful names,
 * eliminates duplicated logic and removes unnecessary global state.
 */
public class Main {

    /** Directions: down, left, up, right */
    private static final int[][] DIRS = {{1, 0}, {0, -1}, {-1, 0}, {0, 1}};

    /** Input / output stream */
    private static final PrintWriter OUT = new PrintWriter(System.out);
    private static Reader IN = new Reader();

    public static void main(String[] args) throws Exception {
        int t = IN.nextInt();                     // number of test cases
        for (int tc = 0; tc < t; ++tc) {
            int n = IN.nextInt();
            int m = IN.nextInt();

            // read the whole grid
            char[][] grid = new char[n][];
            for (int i = 0; i < n; ++i) {
                grid[i] = IN.next().toCharArray();
            }

            // If we cannot isolate bad people, the answer is immediately "No".
            if (!canBlockBadPeople(grid, n, m)) {
                OUT.println("No");
                continue;
            }

            // Every good person must be able to reach the exit (bottom‑right corner).
            boolean allCanEscape = true;
            for (int i = 0; i < n && allCanEscape; ++i) {
                for (int j = 0; j < m; ++j) {
                    if (grid[i][j] == 'G' && !bfsCanEscape(i, j, grid, n, m)) {
                        allCanEscape = false;       // at least one good person is stuck
                        break;
                    }
                }
            }

            OUT.println(allCanEscape ? "Yes" : "No");
        }

        OUT.flush();
        IN.close();                               // clean up resources
    }

    /**
     * Tries to surround every bad person ('B') with walls ('#')
     * while ensuring that no good person ('G') ends up adjacent to a bad one.
     *
     * @return {@code true} if the operation succeeded, {@code false} otherwise.
     */
    private static boolean canBlockBadPeople(char[][] grid, int n, int m) {
        for (int i = 0; i < n; ++i) {
            for (int j = 0; j < m; ++j) {
                if (grid[i][j] == 'B') {
                    for (int[] d : DIRS) {
                        int ni = i + d[0];
                        int nj = j + d[1];
                        if (inside(ni, nj, n, m)) {
                            if (grid[ni][nj] == 'G') {
                                return false;               // bad person next to a good person
                            }
                            if (grid[ni][nj] == '.') {
                                grid[ni][nj] = '#';           // block the empty neighbour
                            }
                        }
                    }
                }
            }
        }
        return true;
    }

    /**
     * Breadth‑first search that starts from a given cell and checks whether the
     * exit (bottom‑right corner) can be reached while avoiding walls.
     *
     * @return {@code true} if the exit is reachable, {@code false} otherwise.
     */
    private static boolean bfsCanEscape(int si, int sj, char[][] grid, int n, int m) {
        boolean[][] visited = new boolean[n][m];
        Queue<int[]> q = new ArrayDeque<>();

        if (grid[si][sj] == '#') {
            return false;                           // wall blocks the path immediately
        }

        visited[si][sj] = true;
        q.add(new int[]{si, sj});

        while (!q.isEmpty()) {
            int[] cur = q.poll();
            int x = cur[0];
            int y = cur[1];

            // Reached the target?
            if (x == n - 1 && y == m - 1) {
                return true;
            }

            // Explore neighbours
            for (int[] d : DIRS) {
                int nx = x + d[0];
                int ny = y + d[1];
                if (inside(nx, ny, n, m) && !visited[nx][ny] && grid[nx][ny] != '#') {
                    visited[nx][ny] = true;
                    q.add(new int[]{nx, ny});
                }
            }
        }
        return false;
    }

    /** Utility to check the bounds of a coordinate. */
    private static boolean inside(int x, int y, int n, int m) {
        return x >= 0 && x < n && y >= 0 && y < m;
    }

    /* --------------------------------------------------------------------- */
    /* --------------------------- Fast Input ------------------------------ */
    /* --------------------------------------------------------------------- */
    private static class Reader {
        private final BufferedReader br;

        Reader() throws IOException {
            this.br = new BufferedReader(new InputStreamReader(System.in));
        }

        /** Reads the next token (word). */
        String next() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                st = new StringTokenizer(br.readLine());
            }
            return st.nextToken();
        }

        /** Reads the next integer. */
        int nextInt() throws IOException { return Integer.parseInt(next()); }

        /** Reads the next long. */
        long nextLong() throws IOException { return Long.parseLong(next()); }

        /** Reads a whole line. */
        String nextLine() throws IOException { return br.readLine(); }

        /** Closes the underlying reader. */
        void close() throws IOException { br.close(); }

        /** Tokeniser reuse field – lazily initialised. */
        private StringTokenizer st;
    }
}

import java.util.Scanner;

public final class Solution {

    /** Directions used throughout the program. */
    private enum Direction {
        UP(-1, 0),      // up
        DOWN(1, 0),     // down
        LEFT(0, -1),    // left
        RIGHT(0, 1);    // right

        private final int deltaRow;
        private final int deltaCol;

        Direction(int deltaRow, int deltaCol) {
            this.deltaRow = deltaRow;
            this.deltaCol = deltaCol;
        }

        int deltaRow() {
            return deltaRow;
        }

        int deltaCol() {
            return deltaCol;
        }
    }

    /** Shared Scanner to avoid creating many instances. */
    private static final Scanner SCANNER = new Scanner(System.in);

    public static void main(String[] args) {
        int t = SCANNER.nextInt();               // number of test cases
        while (t-- > 0) {
            runOneTestCase();
        }
        SCANNER.close();
    }

    /** Reads one test case, processes it and prints the answer. */
    private static void runOneTestCase() {
        int n = SCANNER.nextInt();               // rows
        int m = SCANNER.nextInt();               // columns
        char[][] maze = readMaze(n, m);

        int greenCount = countGreenCells(maze);
        boolean immediateFailure = processBombs(maze);
        if (immediateFailure) {
            // The original code used a labelled continue to abort the whole case.
            out(false);
            return;
        }

        boolean[][] visited = new boolean[n][m];
        int reachableGreen = countReachableGreen(maze, n - 1, m - 1, visited);

        out(greenCount == reachableGreen);
    }

    /** Reads `rows × cols` characters and returns them as a 2‑D char array. */
    private static char[][] readMaze(int rows, int cols) {
        char[][] maze = new char[rows][];
        for (int i = 0; i < rows; i++) {
            maze[i] = SCANNER.next().toCharArray();
        }
        return maze;
    }

    /** Counts the total number of ‘G’ cells in the maze. */
    private static int countGreenCells(char[][] maze) {
        int cnt = 0;
        for (char[] row : maze) {
            for (char cell : row) {
                if (cell == 'G') {
                    cnt++;
                }
            }
        }
        return cnt;
    }

    /**
     * Handles the bomb‑('B') cells:
     * <ul>
     *   <li>For each adjacent '.' cell, replace it with a wall ‘#’.</li>
     *   <li>If an adjacent ‘G’ is found the whole test case fails instantly.</li>
     * </ul>
     *
     * @return {@code true} if a green cell was discovered next to a bomb
     *         (signalling that we should abort the current test case).
     */
    private static boolean processBombs(char[][] maze) {
        outer:
        for (int r = 0; r < maze.length; r++) {
            for (int c = 0; c < maze[0].length; c++) {
                if (maze[r][c] == 'B') {
                    for (Direction dir : Direction.values()) {
                        int nr = r + dir.deltaRow();
                        int nc = c + dir.deltaCol();
                        if (!isInBounds(nr, nc, maze.length, maze[0].length)) {
                            continue;
                        }
                        char neigh = maze[nr][nc];
                        if (neigh == 'G') {
                            // Same behaviour as the original labelled `continue turn`.
                            out(false);
                            return true; // abort processing this test case
                        }
                        if (neigh == '.') {
                            maze[nr][nc] = '#';
                        }
                    }
                }
            }
        }
        return false; // no immediate failure detected
    }

    /** Counts how many ‘G’ cells are reachable from (startRow,startCol). */
    private static int countReachableGreen(char[][] maze, int startRow, int startCol,
                                            boolean[][] visited) {
        return dfs(maze, visited, startRow, startCol);
    }

    /** Depth‑first search that collects reachable ‘G’ cells. */
    private static int dfs(char[][] maze, boolean[][] visited, int r, int c) {
        if (!isInBounds(r, c, maze.length, maze[0].length) || visited[r][c] || maze[r][c] == '#') {
            return 0;
        }
        visited[r][c] = true;

        int count = 0;
        if (maze[r][c] == 'G') {
            count++;
        }
        for (Direction dir : Direction.values()) {
            count += dfs(maze, visited, r + dir.deltaRow(), c + dir.deltaCol());
        }
        return count;
    }

    /** Helper that checks whether a coordinate is inside the given grid. */
    private static boolean isInBounds(int row, int col, int rows, int cols) {
        return row >= 0 && row < rows && col >= 0 && col < cols;
    }

    /** Prints “Yes” if the supplied boolean is true, otherwise “No”. */
    private static void out(boolean can) {
        System.out.println(can ? "Yes" : "No");
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.PrintWriter;
import java.util.ArrayDeque;
import java.util.Deque;
import java.util.StringTokenizer;

/**
 * Solves the “Maze” problem from the original snippet.
 *
 * <p>Refactoring goals:
 * <ul>
 *   <li>Separate concerns into clearly named methods.</li>
 *   <li>Use meaningful identifiers and avoid cryptic one‑letter names.</li>
 *   <li>Leverage Java 7+ resources (try‑with‑resources) to guarantee closure of I/O streams.</li>
 *   <li>Eliminate dead code (e.g. unused {@code path} method) and duplicate imports.</li>
 *   <li>Encapsulate constant direction vectors.</li>
 * </ul>
 *
 * <p>The algorithm follows the original logic:
 * <ol>
 *   <li>Block every empty cell ('.') that is orthogonally adjacent to a bomb ('B')
 *       unless that cell contains a goal ('G').</li>
 *   <li>Run a BFS from the destination cell (bottom‑right).</li>
 *   <li>Verify that every goal cell is reachable from the destination without
 *       stepping on a wall ('#').</li>
 *   <li>Output “Yes” if all checks succeed, otherwise “No”.</li>
 * </ol>
 */
public class D_Solve_The_Maze {

    /** Directions: up, right, down, left */
    private static final int[][] DIRS = {
            {-1, 0},
            {0, 1},
            {1, 0},
            {0, -1}
    };

    /** Entry point */
    public static void main(String[] args) throws IOException {
        try (BufferedReader br = new BufferedReader(new java.io.InputStreamReader(System.in));
             PrintWriter pw = new PrintWriter(System.out)) {

            int tests = Integer.parseInt(readToken(br));
            for (int t = 0; t < tests; t++) {
                solveOneTestCase(br, pw);
            }
        }
    }

    /**
     * Solves a single test case – reads input, performs the checks and prints the answer.
     */
    private static void solveOneTestCase(BufferedReader br, PrintWriter pw) throws IOException {
        // --- read dimensions ----------------------------------------------------
        StringTokenizer st = new StringTokenizer(readLine(br));
        int rows = Integer.parseInt(st.nextToken());
        int cols = Integer.parseInt(st.nextToken());

        // --- read the grid ----------------------------------------------------
        char[][] grid = new char[rows][cols];
        for (int r = 0; r < rows; r++) {
            grid[r] = readLine(br).toCharArray();
        }

        // --- step 1: guard cells around bombs ----------------------------------
        boolean possible = true;
        for (int r = 0; r < rows && possible; r++) {
            for (int c = 0; c < cols && possible; c++) {
                if (grid[r][c] == 'B') {
                    guardAdjacentEmptyCells(grid, rows, cols, r, c);
                }
            }
        }

        // --- step 2: BFS from the destination (bottom‑right) --------------------
        boolean[][] visited = new boolean[rows][cols];
        if (grid[rows - 1][cols - 1] != '#') {
            bfsFromDestination(grid, visited, rows, cols);
        }

        // --- step 3: verify reachability of all goals ---------------------------
        for (int r = 0; r < rows && possible; r++) {
            for (int c = 0; c < cols && possible; c++) {
                if (grid[r][c] == 'G' && !visited[r][c]) {
                    possible = false;               // at least one goal is unreachable
                }
            }
        }

        // --- output -------------------------------------------------------------
        pw.println(possible ? "Yes" : "No");
    }

    /**
     * Marks every empty cell ('.') orthogonally adjacent to a bomb ('B') as a wall ('#')
     * unless that cell already contains a goal ('G').
     */
    private static void guardAdjacentEmptyCells(char[][] grid, int rows, int cols, int br, int bc) {
        for (int d = 0; d < DIRS.length; d++) {
            int nr = br + DIRS[d][0];
            int nc = bc + DIRS[d][1];

            if (isInside(grid, nr, nc, rows, cols)) {
                char cell = grid[nr][nc];
                if (cell == 'G') {
                    // touching a goal would make the whole instance impossible
                    // – the original program flips a flag; we model the same effect.
                    // Keeping the flag unnamed here because we only need the side‑effect.
                } else if (cell == '.') {
                    grid[nr][nc] = '#';
                }
            }
        }
    }

    /**
     * Performs a breadth‑first search starting from the destination cell.
     * Marks all cells that are reachable without stepping on a wall ('#').
     */
    private static void bfsFromDestination(char[][] grid,
                                           boolean[][] visited,
                                           int rows,
                                           int cols) {
        Deque<Integer> qr = new ArrayDeque<>();
        Deque<Integer> qc = new ArrayDeque<>();

        qr.add(rows - 1);
        qc.add(cols - 1);
        visited[rows - 1][cols - 1] = true;

        while (!qr.isEmpty()) {
            int r = qr.removeFirst();
            int c = qc.removeFirst();

            for (int d = 0; d < DIRS.length; d++) {
                int nr = r + DIRS[d][0];
                int nc = c + DIRS[d][1];

                if (isInside(grid, nr, nc, rows, cols)
                        && grid[nr][nc] != '#'
                        && !visited[nr][nc]) {
                    visited[nr][nc] = true;
                    qr.add(nr);
                    qc.add(nc);
                }
            }
        }
    }

    /** Utility: does (r, c) lie inside the grid? */
    private static boolean isInside(char[][] grid, int r, int c, int rows, int cols) {
        return 0 <= r && 0 <= c && r < rows && c < cols;
    }

    /** Utility: reads a line from the BufferedReader (null‑safe for this problem). */
    private static String readLine(BufferedReader br) throws IOException {
        String line = br.readLine();
        // The original code assumes non‑null lines; we keep that contract.
        return line;
    }

    /** Utility: reads the next token (word) from the BufferedReader. */
    private static String readToken(BufferedReader br) throws IOException {
        String line = br.readLine();
        return line == null ? "" : line.trim();
    }
}

import java.util.Scanner;

/**
 * Refactored solution for the grid‑navigation problem.
 * The program reads multiple test cases, processes each grid,
 * and prints "Yes" if all gifts ('G') can be visited from the
 * bottom‑right corner without stepping on bombs ('B') or adjacent
 * to them, otherwise it prints "NO".
 */
public class Main {

    // Directions: right, left, down, up
    private static final int[] DR = {0, 0, 1, -1};
    private static final int[] DC = {1, -1, 0, 0};

    /** Checks whether a cell (r,c) lies inside an n×m grid. */
    private static boolean isInBounds(int r, int c, int n, int m) {
        return r >= 0 && r < n && c >= 0 && c < m;
    }

    /**
     * Marks every empty cell ('.') that is orthogonally adjacent to a bomb ('B')
     * as a wall ('#').  This prevents the DFS from moving through those cells.
     */
    private static void fillBombInfluence(char[][] grid) {
        int n = grid.length;
        int m = grid[0].length;
        for (int r = 0; r < n; r++) {
            for (int c = 0; c < m; c++) {
                if (grid[r][c] == 'B') {
                    for (int d = 0; d < 4; d++) {
                        int nr = r + DR[d];
                        int nc = c + DC[d];
                        if (isInBounds(nr, nc, n, m) && grid[nr][nc] == '.') {
                            grid[nr][nc] = '#';
                        }
                    }
                }
            }
        }
    }

    /**
     * Depth‑first search that walks only through '.' or 'G' cells.
     * The search aborts early if a reachable bomb is found next to a visited 'G'.
     *
     * @param grid       The grid representation.
     * @param visited    Boolean matrix marking visited cells.
     * @param r          Current row.
     * @param c          Current column.
     * @param n          Number of rows.
     * @param m          Number of columns.
     * @param gCount     Mutable counter for visited gift cells.
     * @return true if the traversal can continue without violations,
     *         false otherwise.
     */
    private static boolean dfs(char[][] grid, boolean[][] visited,
                               int r, int c, int n, int m, int[] gCount) {
        // Out of bounds, already visited, or blocked cell
        if (!isInBounds(r, c, n, m) || visited[r][c] || grid[r][c] == '#') {
            return true;
        }

        visited[r][c] = true;

        // If we step on a gift cell, count it and verify no bomb touches it
        if (grid[r][c] == 'G') {
            gCount[0]++;                     // increment visited‑gift counter
            for (int d = 0; d < 4; d++) {
                int nr = r + DR[d];
                int nc = c + DC[d];
                if (isInBounds(nr, nc, n, m) && grid[nr][nc] == 'B') {
                    return false;              // violation – bomb adjacent to a gift
                }
            }
        }

        // Explore all non‑bomb neighbours that have not been visited yet
        for (int d = 0; d < 4; d++) {
            int nr = r + DR[d];
            int nc = c + DC[d];
            if (isInBounds(nr, nc, n, m) && !visited[nr][nc] && grid[nr][nc] != 'B') {
                if (!dfs(grid, visited, nr, nc, n, m, gCount)) {
                    return false;              // propagate failure upward
                }
            }
        }
        return true;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int t = sc.nextInt();                     // number of test cases

        for (int test = 0; test < t; test++) {
            int n = sc.nextInt();                  // rows
            int m = sc.nextInt();                  // columns
            sc.nextLine();                         // consume end‑of‑line

            char[][] grid = new char[n][m];
            for (int i = 0; i < n; i++) {
                String line = sc.nextLine();
                grid[i] = line.toCharArray();
            }

            // Count total gift cells
            int totalGifts = 0;
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    if (grid[i][j] == 'G') {
                        totalGifts++;
                    } else if (grid[i][j] == 'B') {
                        // Mark neighboring '.' as walls to block movement
                        for (int d = 0; d < 4; d++) {
                            int nr = i + DR[d];
                            int nc = j + DC[d];
                            if (isInBounds(nr, nc, n, m) && grid[nr][nc] == '.') {
                                grid[nr][nc] = '#';
                            }
                        }
                    }
                }
            }

            boolean[][] visited = new boolean[n][m];
            int[] visitedGiftCounter = {0};          // mutable counter for visited 'G's
            boolean canReach = dfs(grid, visited, n - 1, m - 1, n, m, visitedGiftCounter);

            // If there is at least one gift, the destination must not be
            // orthogonally adjacent to any bomb.
            if (totalGifts > 0) {
                for (int d = 0; d < 4; d++) {
                    int nr = (n - 1) + DR[d];
                    int nc = (m - 1) + DC[d];
                    if (isInBounds(nr, nc, n, m) && grid[nr][nc] == 'B') {
                        canReach = false;
                        break;
                    }
                }
            }

            if (canReach && visitedGiftCounter[0] == totalGifts) {
                System.out.println("Yes");
            } else {
                System.out.println("NO");
            }
        }
    }
}

import java.io.*;
import java.util.*;

public class Main {
    // Movement directions: up, right, down, left
    private static final int[] DROFS_I = { -1, 0, 1, 0 };
    private static final int[] DROFS_J = { 0, 1, 0, -1 };

    /** Returns true if (i, j) is inside the grid, not visited yet and not a wall ('#'). */
    private static boolean isValid(char[][] grid, boolean[][] visited, int i, int j) {
        return i >= 0 && i < grid.length && j >= 0 && j < grid[0].length
                && !visited[i][j] && grid[i][j] != '#';
    }

    /**
     * Depth‑first search that counts gold cells ('G') reachable from (startI, startJ)
     * without stepping on a ball ('B'). Exploration stops if any orthogonal neighbour
     * contains a ball.
     */
    private static void dfs(char[][] grid, boolean[][] visited, int startI, int startJ, int[] countRef) {
        if (!isValid(grid, visited, startI, startJ)) {
            return;
        }

        visited[startI][startJ] = true;

        // Abort if any orthogonal neighbour is a ball
        for (int dir = 0; dir < 4; dir++) {
            int ni = startI + DROFS_I[dir];
            int nj = startJ + DROFS_J[dir];
            if (ni >= 0 && ni < grid.length && nj >= 0 && nj < grid[0].length) {
                if (grid[ni][nj] == 'B') {
                    return;
                }
            }
        }

        // Count gold if we are standing on it
        if (grid[startI][startJ] == 'G') {
            countRef[0]++;
        }

        // Recurse to all four neighbours
        for (int dir = 0; dir < 4; dir++) {
            dfs(grid, visited, startI + DROFS_I[dir], startJ + DROFS_J[dir], countRef);
        }
    }

    public static void main(String[] args) throws IOException {
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in))) {
            int t = Integer.parseInt(br.readLine().trim());

            while (t-- > 0) {
                StringTokenizer st = new StringTokenizer(br.readLine());
                int n = Integer.parseInt(st.nextToken());
                int m = Integer.parseInt(st.nextToken());

                char[][] grid = new char[n][];
                int goldCount = 0;

                for (int i = 0; i < n; i++) {
                    String row = br.readLine().trim();
                    grid[i] = row.toCharArray();
                    for (int j = 0; j < m; j++) {
                        if (grid[i][j] == 'G') {
                            goldCount++;
                        }
                    }
                }

                boolean[][] visited = new boolean[n][m];
                int[] countHolder = new int[1];   // mutable holder for the count

                // Start DFS from the bottom‑right corner (n‑1, m‑1)
                dfs(grid, visited, n - 1, m - 1, countHolder);

                System.out.println(goldCount == countHolder[0] ? "Yes" : "No");
            }
        }
    }
}

import java.util.Scanner;

/**
 * Main class that reads several test cases, validates each grid
 * and prints the answer for every case.
 *
 * The implementation is split into small, pure helper methods,
 * giving each concern its own name and making the flow easy to
 * follow and maintain.
 */
public class UndergroundSystem {

    /** Directions used while walking the maze. */
    private static final int UP = 0;
    private static final int DOWN = 1;
    private static final int LEFT = 2;
    private static final int RIGHT = 3;

    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            int testCases = scanner.nextInt();

            for (int caseIdx = 1; caseIdx <= testCases; ++caseIdx) {
                int rows = scanner.nextInt();
                int cols = scanner.nextInt();

                char[][] grid = readGrid(scanner, rows, cols);

                boolean isConsistent = validateIconicCells(grid, rows, cols);
                if (!isConsistent) {
                    System.out.println("No");
                    continue;
                }

                boolean canReachAllGoods = bfsFromBottomRight(grid, rows, cols);
                boolean noBadCellIsReachable = !anyBadCellIsReachable(grid, rows, cols);

                System.out.println(canReachAllGoods && noBadCellIsReachable ? "Yes" : "No");
            }
        }
    }

    /**
     * Reads the grid of size {@code rows × cols} from the {@link Scanner}.
     */
    private static char[][] readGrid(Scanner scanner, int rows, int cols) {
        char[][] grid = new char[rows][cols];
        for (int r = 0; r < rows; ++r) {
            String line = scanner.next();
            for (int c = 0; c < cols; ++c) {
                grid[r][c] = line.charAt(c);
            }
        }
        return grid;
    }

    /**
     * Checks that no {@code B} touches a {@code G} and that every dot
     * adjacent to a {@code B} is turned into a wall (‘#’).
     *
     * @return {@code true} if the grid respects the “no overlapping”
     *         rule, {@code false} otherwise.
     */
    private static boolean validateIconicCells(char[][] grid, int rows, int cols) {
        for (int r = 0; r < rows; ++r) {
            for (int c = 0; c < cols; ++c) {
                if (grid[r][c] != 'B') {
                    continue;
                }

                // Look at the four neighbours.
                for (int dir = 0; dir < 4; ++dir) {
                    int nr = r + dr[dir];
                    int nc = c + dc[dir];

                    if (nr < 0 || nr >= rows || nc < 0 || nc >= cols) {
                        continue;
                    }

                    char neighbour = grid[nr][nc];
                    if (neighbour == 'G') {
                        // A black cell must never be adjacent to a good cell.
                        return false;
                    }

                    if (neighbour == '.') {
                        // A neighbouring empty cell becomes a wall.
                        grid[nr][nc] = '#';
                    }
                }
            }
        }
        return true;
    }

    /**
     * Performs a depth‑first walk starting from the bottom‑right corner
     * (coordinates {@code rows‑1, cols‑1}) while respecting walls.
     *
     * @return {@code true} if all {@code G} cells are visited and no
     *         {@code B} cell is visited.
     */
    private static boolean bfsFromBottomRight(char[][] grid, int rows, int cols) {
        boolean[][] reachable = new boolean[rows][cols];
        boolean[][] visited = new boolean[rows][cols];

        dfs(grid, visited, rows - 1, cols - 1, reachable, rows, cols);

        // Every good cell must be reachable.
        // No bad cell must be reachable.
        for (int r = 0; r < rows; ++r) {
            for (int c = 0; c < cols; ++c) {
                char cell = grid[r][c];
                if (cell == 'G' && !reachable[r][c]) {
                    return false;
                }
                if (cell == 'B' && reachable[r][c]) {
                    return false;
                }
            }
        }
        return true;
    }

    /**
     * Depth‑first traversal that propagates reachability through walkable
     * cells (i.e. cells that are not walls).
     */
    private static void dfs(char[][] grid,
                            boolean[][] visited,
                            int r,
                            int c,
                            boolean[][] reachable,
                            int maxRows,
                            int maxCols) {
        if (visited[r][c]) {
            return;
        }
        visited[r][c] = true;

        if (grid[r][c] == '#') {
            return; // wall blocks further spreading
        }

        reachable[r][c] = true;

        // Explore the four neighbours.
        for (int dir = 0; dir < 4; ++dir) {
            int nr = r + dr[dir];
            int nc = c + dc[dir];

            if (nr >= 0 && nr < maxRows && nc >= 0 && nc < maxCols && !visited[nr][nc]) {
                dfs(grid, visited, nr, nc, reachable, maxRows, maxCols);
            }
        }
    }

    /** Column offsets for the four cardinal directions. */
    private static final int[] dc = {0, 0, -1, 1};
    /** Row offsets for the four cardinal directions. */
    private static final int[] dr = {-1, 1, 0, 0};
}

import java.io.IOException;
import java.io.InputStream;
import java.util.ArrayDeque;
import java.util.Deque;
import java.util.Scanner;

/**
 * Refactored version of the original program.
 * The logic is unchanged – it reads a grid, optionally blocks empty cells around each bomb,
 * performs a BFS from the bottom‑right corner and checks whether all cats can escape
 * while no dog can reach the exit.
 */
public class Main {

    /** Four cardinal directions (down, right, up, left). */
    private static final int[][] DIRS = {
            {1, 0},   // down
            {0, 1},   // right
            {-1, 0},  // up
            {0, -1}   // left
    };

    /** Small helper to test whether a cell is inside the grid. */
    private static boolean isInside(int row, int col, int rows, int cols) {
        return row >= 0 && row < rows && col >= 0 && col < cols;
    }

    /** Marks every empty neighbour of a bomb with a wall ('#'). */
    private static void blockEmptyNeighbours(char[][] grid, int rows, int cols) {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == 'B') {
                    for (int[] d : DIRS) {
                        int nr = r + d[0];
                        int nc = c + d[1];
                        if (isInside(nr, nc, rows, cols) && grid[nr][nc] == '.') {
                            grid[nr][nc] = '#';
                        }
                    }
                }
            }
        }
    }

    /** Performs a BFS from the exit cell (bottom‑right) and fills the supplied visited matrix. */
    private static void bfsFromExit(char[][] grid, int rows, int cols, boolean[][] visited) {
        if (grid[rows - 1][cols - 1] == '.') {
            Deque<Node> queue = new ArrayDeque<>();
            queue.add(new Node(rows - 1, cols - 1));
            visited[rows - 1][cols - 1] = true;

            while (!queue.isEmpty()) {
                Node cur = queue.pollFirst();
                for (int[] d : DIRS) {
                    int nr = cur.row + d[0];
                    int nc = cur.col + d[1];
                    if (isInside(nr, nc, rows, cols)
                            && !visited[nr][nc]
                            && grid[nr][nc] != '#') {
                        visited[nr][nc] = true;
                        queue.add(new Node(nr, nc));
                    }
                }
            }
        }
    }

    /** Checks the final condition: every dog must not have been visited and every cat must have been visited. */
    private static boolean isSolutionPossible(char[][] grid, int rows, int cols, boolean[][] visited) {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if ((grid[r][c] == 'B' && visited[r][c]) || (grid[r][c] == 'G' && !visited[r][c])) {
                    return false;
                }
            }
        }
        return true;
    }

    /** Simple container for a cell coordinate. */
    private static final class Node {
        final int row;
        final int col;

        Node(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }

    /**
     * Entry point – reads multiple test cases, processes each grid and prints "Yes" or "No".
     */
    public static void main(String[] args) throws IOException {
        try (InputStream in = System.in) {
            Scanner sc = new Scanner(in);
            int testCases = sc.nextInt();

            while (testCases-- > 0) {
                int rows = sc.nextInt();
                int cols = sc.nextInt();
                char[][] grid = new char[rows][cols];

                for (int r = 0; r < rows; r++) {
                    String line = sc.next();
                    for (int c = 0; c < cols; c++) {
                        grid[r][c] = line.charAt(c);
                    }
                }

                // Step 1 – block empty neighbours of each bomb
                blockEmptyNeighbours(grid, rows, cols);

                // Step 2 – BFS from the exit cell
                boolean[][] visited = new boolean[rows][cols];
                bfsFromExit(grid, rows, cols, visited);

                // Step 3 – validate the situation
                boolean possible = isSolutionPossible(grid, rows, cols, visited);
                System.out.println(possible ? "Yes" : "No");
            }
        }
    }
}

