// Refactored version of NeighborGrid with improved maintainability
// ---------------------------------------------------------------
public class NeighborGrid {

    /* ----------  Constants describing allowed values  ---------- */
    private static final int MAX_CORNER   = 2;   // cells in the four corners
    private static final int MAX_EDGE     = 3;   // cells on the border (non‑corner)
    private static final int MAX_INNER    = 4;   // all other interior cells

    /* -----------------------  Main entry point  ----------------- */
    public static void main(String[] args) {
        FastReader reader = new FastReader();

        int testCases = reader.nextInt();
        for (int tc = 0; tc < testCases; tc++) {
            int rows = reader.nextInt();
            int cols = reader.nextInt();

            int[][] grid = readGrid(reader, rows, cols);

            if (!isValid(grid, rows, cols)) {
                System.out.println("NO");
                continue;                // move to the next test case
            }

            System.out.println("YES");
            printTemplate(rows, cols);
        }
    }

    /* ---------------------  Input handling  ---------------------- */
    /** Reads a single grid from the FastReader. */
    private static int[][] readGrid(FastReader reader, int rows, int cols) {
        int[][] grid = new int[rows][cols];
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                grid[i][j] = reader.nextInt();
            }
        }
        return grid;
    }

    /* -------------------  Validation logic  -------------------- */
    /** Checks whether the supplied grid respects the required limits. */
    private static boolean isValid(int[][] grid, int rows, int cols) {
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                int value = grid[i][j];

                if (isCorner(i, j, rows, cols)) {
                    if (value > MAX_CORNER) return false;
                } else if (isEdge(i, j, rows, cols)) {
                    if (value > MAX_EDGE) return false;
                } else { // interior cell
                    if (value > MAX_INNER) return false;
                }
            }
        }
        return true;
    }

    /** True if the cell is one of the four corners of the rectangle. */
    private static boolean isCorner(int i, int j, int rows, int cols) {
        return (i == 0 && j == 0) ||
               (i == 0 && j == cols - 1) ||
               (i == rows - 1 && j == 0) ||
               (i == rows - 1 && j == cols - 1);
    }

    /** True if the cell lies on the border but is not a corner. */
    private static boolean isEdge(int i, int j, int rows, int cols) {
        return (i == 0 && j > 0 && j < cols - 1) ||
               (i == rows - 1 && j > 0 && j < cols - 1) ||
               (j == 0 && i > 0 && i < rows - 1) ||
               (j == cols - 1 && i > 0 && i < rows - 1);
    }

    /* --------------------  Template output  -------------------- */
    /** Prints the required pattern of 2,3,4 depending on cell position. */
    private static void printTemplate(int rows, int cols) {
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (isCorner(i, j, rows, cols)) {
                    System.out.print(2 + " ");
                } else if (isEdge(i, j, rows, cols)) {
                    System.out.print(3 + " ");
                } else {
                    System.out.print(4 + " ");
                }
            }
            System.out.println();
        }
    }

    /* ----------------------  Fast input parser  ----------------- */
    static class FastReader {
        private final BufferedReader br;
        private StringTokenizer st;

        FastReader() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    e.printStackTrace();
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        long nextLong() {
            return Long.parseLong(next());
        }

        double nextDouble() {
            return Double.parseDouble(next());
        }

        String nextLine() {
            String str = "";
            try {
                str = br.readLine();
            } catch (IOException e) {
                e.printStackTrace();
            }
            return str;
        }
    }
}

import java.io.*;
import java.util.*;

public class CP {

    /** Fast input scanner – wraps a BufferedReader with a StringTokenizer. */
    private static final class FastReader {
        private final BufferedReader br;
        private StringTokenizer st;

        FastReader() throws IOException {
            this.br = new BufferedReader(new InputStreamReader(System.in));
        }

        /** Returns next token, reading a new line if necessary. */
        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    throw new UncheckedIOException(e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        long nextLong() {
            return Long.parseLong(next());
        }

        double nextDouble() {
            return Double.parseDouble(next());
        }

        String nextLine() {
            try {
                return br.readLine();
            } catch (IOException e) {
                throw new UncheckedIOException(e);
            }
        }
    }

    /** Collection of pure‑math utilities. */
    private static final class MathUtils {
        private MathUtils() {}

        public static long gcd(long a, long b) {
            return b == 0 ? a : gcd(b, a % b);
        }

        /** Number of positive divisors of *n* (including 1 and n). */
        public static long countDivisors(long n) {
            if (n <= 0) return 0;
            long limit = (long) Math.sqrt(n);
            int cnt = 0;
            for (long i = 1; i <= limit; i++) {
                if (n % i == 0) cnt++;
            }
            cnt *= 2;
            return limit * limit == n ? cnt - 1 : cnt;
        }

        /** Simple primality test (good enough for the ranges used here). */
        public static boolean isPrime(long x) {
            if (x < 2) return false;
            int limit = (int) Math.sqrt(x);
            for (int i = 2; i <= limit; i++) {
                if (x % i == 0) return false;
            }
            return true;
        }
    }

    /** Creates a boolean[] sieve up to *limit* (inclusive). */
    private static final class PrimeSieve {
        private final boolean[] isPrime;

        PrimeSieve(int limit) {
            isPrime = new boolean[limit + 1];
            Arrays.fill(isPrime, true);
            isPrime[0] = isPrime[1] = false;
            for (int i = 2; i * i <= limit; i++) {
                if (isPrime[i]) {
                    for (int j = i * i; j <= limit; j += i) {
                        isPrime[j] = false;
                    }
                }
            }
        }

        public boolean[] getArray() {
            return isPrime;
        }
    }

    /** Validates the given matrix against the problem’s prefix constraints. */
    private static final class MatrixValidator {
        private static final int MIN_VAL = 1;
        private static final int MAX_VAL = 4;

        private final int rows;
        private final int cols;
        private final int[][] data;

        MatrixValidator(int[][] data) {
            this.data = data;
            this.rows = data.length;
            this.cols = data[0].length;
        }

        /** Returns *true* if the matrix obeys all “prefix” rules. */
        boolean isValid() {
            // 1️⃣ every cell must be in the range [1, 4]
            for (int[] row : data) {
                for (int v : row) {
                    if (v < MIN_VAL || v > MAX_VAL) {
                        return false;
                    }
                }
            }

            // 2️⃣ value 3 must never appear on a border cell
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (data[i][j] == 3 && isBorder(i, j)) {
                        return false;
                    }
                }
            }

            // 3️⃣ value 4 must never appear on a border cell
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (data[i][j] == 4 && isBorder(i, j)) {
                        return false;
                    }
                }
            }

            // 4️⃣ the four corner cells must not contain a 3 (original code rejected them)
            for (int i : new int[]{0, rows - 1}) {
                for (int j : new int[]{0, cols - 1}) {
                    if (data[i][j] == 3) {
                        return false;
                    }
                }
            }

            return true;
        }

        /** Helper – a cell is on the outer border when its row index or column index is 0 or the last index. */
        private boolean isBorder(int i, int j) {
            return i == 0 || i == rows - 1 || j == 0 || j == cols - 1;
        }
    }

    /** Builds the final pattern matrix once the validation succeeded. */
    private static final class MatrixBuilder {
        private final int[][] matrix;

        MatrixBuilder(int rows, int cols) {
            this.matrix = new int[rows][cols];
        }

        /** Fills the matrix with the required constants (3 on the border, 4 inside, 2 on the corners). */
        void fillWithConstants() {
            // Fill everything with 4 first
            for (int i = 0; i < matrix.length; i++) {
                for (int j = 0; j < matrix[i].length; j++) {
                    matrix[i][j] = 4;
                }
            }

            // Turn the outer border into 3
            for (int i = 0; i < matrix.length; i++) {
                for (int j = 0; j < matrix[i].length; j++) {
                    if (i == 0 || i == matrix.length - 1 || j == 0 || j == matrix[i].length - 1) {
                        matrix[i][j] = 3;
                    }
                }
            }

            // Convert the four corners to 2
            matrix[0][0] = matrix[matrix.length - 1][0] =
                    matrix[0][matrix[0].length - 1] = matrix[matrix.length - 1][matrix[0].length - 1] = 2;
        }

        int[][] getMatrix() {
            return matrix;
        }
    }

    /** Formats a matrix as a single string with spaces and line‑breaks. */
    private static String formatMatrix(int[][] mat) {
        StringBuilder sb = new StringBuilder();
        for (int[] row : mat) {
            for (int val : row) {
                sb.append(val).append(' ');
            }
            sb.append('\n');
        }
        return sb.toString();
    }

    /** Solves a single test case. Returns the answer as a ready‑to‑print string. */
    private static String solveCase(FastReader sc) {
        int n = sc.nextInt();      // number of rows
        int m = sc.nextInt();      // number of columns

        int[][] input = readMatrix(sc, n, m);

        // ---- validation ----------------------------------------------------
        if (!new MatrixValidator(input).isValid()) {
            return "NO";
        }

        // ---- construction -------------------------------------------------
        MatrixBuilder builder = new MatrixBuilder(n, m);
        builder.fillWithConstants();
        int[][] result = builder.getMatrix();

        // ---- output -------------------------------------------------------
        return "YES\n" + formatMatrix(result);
    }

    /** Reads an n×m integer matrix from the scanner. */
    private static int[][] readMatrix(FastReader sc, int n, int m) {
        int[][] mat = new int[n][m];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                mat[i][j] = sc.nextInt();
            }
        }
        return mat;
    }

    /** Entry point – processes *T* test cases. */
    public static void main(String[] args) throws IOException {
        // The original program measured execution time; we keep the logic but hide it.
        try (FastReader sc = new FastReader()) {
            int T = sc.nextInt();
            StringBuilder out = new StringBuilder();
            while (T-- > 0) {
                out.append(solveCase(sc));
            }
            System.out.print(out.toString());
        }
    }
}

import java.io.IOException;
import java.io.InputStream;
import java.util.Scanner;

/**
 * Refactored solution that reads several test cases,
 * validates the constraints on the matrix cells and,
 * if the constraints are satisfied, prints the transformed matrix.
 */
public class Main {

    /* -------------------------------------------------
     *  Constants that describe allowed maximum values
     * ------------------------------------------------- */
    private static final int MAX_CORNER = 2;   // corner cells
    private static final int MAX_EDGE   = 3;   // non‑corner border cells
    private static final int MAX_INNER  = 4;   // inner cells

    /** Role of a cell inside the rectangular matrix. */
    private enum CellRole { CORNER, EDGE, INNER }

    public static void main(String[] args) throws IOException {
        // Use try‑with‑resources to auto‑close the scanner
        try (Scanner scanner = new Scanner(System.in)) {
            int testCases = scanner.nextInt();
            StringBuilder output = new StringBuilder();

            for (int tc = 0; tc < testCases; tc++) {
                processTestCase(scanner, output);
            }

            // Print everything at once (more efficient than many println calls)
            System.out.print(output.toString());
        }
    }

    /** Reads one test case, validates it and appends the result to the output builder. */
    private static void processTestCase(Scanner sc, StringBuilder out) {
        int n = sc.nextInt();      // number of rows
        int m = sc.nextInt();      // number of columns
        int[][] grid = new int[n][m];

        // ------------------- read the matrix -------------------
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                grid[i][j] = sc.nextInt();
            }
        }

        // ------------------- validate and possibly transform -------------------
        boolean valid = true;
        int[][] transformed = new int[n][m];

        for (int i = 0; i < n && valid; i++) {
            for (int j = 0; j < m; j++) {
                CellRole role = getCellRole(i, j, n, m);
                int maxAllowed = switch (role) {
                    case CORNER -> MAX_CORNER;
                    case EDGE   -> MAX_EDGE;
                    case INNER  -> MAX_INNER;
                };

                if (grid[i][j] > maxAllowed) {
                    valid = false;                     // constraint violated
                    out.append("NO\n");                  // print once and stop further checks
                    break;                               // exit inner loop
                }
                transformed[i][j] = maxAllowed;        // store the allowed maximum for later printing
            }
        }

        // If the case was already marked "NO", just return to the next test case.
        if (!valid) {
            return;
        }

        // ------------------- successful case: print YES and the transformed matrix -------------------
        out.append("YES\n");
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                out.append(transformed[i][j]).append(' ');
            }
            out.append('\n');
        }
    }

    /** Determines whether a cell is a corner, edge or inner cell. */
    private static CellRole getCellRole(int row, int col, int n, int m) {
        if ((row == 0 || row == n - 1) && (col == 0 || col == m - 1)) {
            return CellRole.CORNER;                     // four corners
        }
        if (row == 0 || row == n - 1 || col == 0 || col == m - 1) {
            return CellRole.EDGE;                       // border but not corner
        }
        return CellRole.INNER;                          // completely interior
    }
}

import java.io.*;
import java.util.*;

/**
 * Refactored solution that reads a grid, builds a “need” matrix,
 * checks feasibility and prints the result.
 *
 * The refactor focuses on:
 *   • Meaningful naming
 *   • Separation of concerns (reading, building, validation, output)
 *   • Constants instead of magic numbers
 *   • Small helper methods that are easy to test
 */
public class Main {

    /*  Border cost constants – replace magic numbers with expressive names */
    private static final int CORNER_COST = 2;
    private static final int EDGE_COST   = 3;
    private static final int INTERIOR_COST = 4;

    public static void main(String[] args) throws IOException {
        FastScanner fs = new FastScanner();
        PrintWriter out = new PrintWriter(System.out);

        int t = fs.nextInt();                     // number of test cases
        for (int tt = 0; tt < t; tt++) {
            int n = fs.nextInt();                   // rows
            int m = fs.nextInt();                   // columns

            int[][] grid = readGrid(fs, n, m);      // input values
            int[][] need = buildNeedMatrix(n, m);   // required cost matrix

            if (!isFeasible(grid, need)) {
                out.println("NO");
                continue;
            }

            out.println("YES");
            printNeedMatrix(out, need);
        }

        out.close();
    }

    /** Reads an n×m integer grid from the scanner. */
    private static int[][] readGrid(FastScanner fs, int n, int m) {
        int[][] grid = new int[n][m];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                grid[i][j] = fs.nextInt();
            }
        }
        return grid;
    }

    /** Constructs the “need” matrix according to the problem’s rules. */
    private static int[][] buildNeedMatrix(int n, int m) {
        int[][] need = new int[n][m];

        // corners
        need[0][0] = need[0][m - 1] = need[n - 1][0] = need[n - 1][m - 1] = CORNER_COST;

        // top & bottom borders (excluding corners)
        for (int j = 1; j < m - 1; j++) {
            need[0][j] = EDGE_COST;
            need[n - 1][j] = EDGE_COST;
        }

        // left & right borders (excluding corners)
        for (int i = 1; i < n - 1; i++) {
            need[i][0] = EDGE_COST;
            need[i][m - 1] = EDGE_COST;
        }

        // interior cells
        for (int i = 1; i < n - 1; i++) {
            for (int j = 1; j < m - 1; j++) {
                need[i][j] = INTERIOR_COST;
            }
        }
        return need;
    }

    /** Returns true if every cell of the input grid is ≤ the corresponding need value. */
    private static boolean isFeasible(int[][] grid, int[][] need) {
        for (int i = 0; i < grid.length; i++) {
            for (int j = 0; j < grid[i].length; j++) {
                if (grid[i][j] > need[i][j]) {
                    return false;
                }
            }
        }
        return true;
    }

    /** Prints the need matrix row‑by‑row, space‑separated, ending each row with a newline. */
    private static void printNeedMatrix(PrintWriter out, int[][] need) {
        for (int[] row : need) {
            for (int val : row) {
                out.print(val + " ");
            }
            out.println();
        }
    }

    /** Fast scanner that tokenises input lines lazily. */
    static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner() {
            this(System.in);
        }

        private FastScanner(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        /** Returns the next token, reading a new line if the current tokenizer is exhausted. */
        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    throw new UncheckedIOException(e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        /** Reads the next n integers into an array (convenient for future extensions). */
        int[] readArray(int n) {
            int[] a = new int[n];
            for (int i = 0; i < n; i++) {
                a[i] = nextInt();
            }
            return a;
        }
    }
}

import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.StringTokenizer;

/**
 * Reads multiple test cases, validates a matrix and prints a fixed neighbour‑count pattern.
 *
 * <p>Refactored for readability, maintainability and testability.
 */
public class BorderChecker {

    /** The fast scanner used for tokenised input. */
    private static FastScanner scanner;

    /** Buffered reader for efficient input reading. */
    private static BufferedReader bufferedReader;

    /** Print writer that outputs to the console. */
    private static PrintWriter writer;

    /** Entry point. */
    public static void main(String[] args) throws Exception {
        // Using try‑with‑resources guarantees that resources are closed properly.
        try (bufferedReader = new BufferedReader(new InputStreamReader(System.in));
             writer = new PrintWriter(System.out)) {

            scanner = new FastScanner(bufferedReader);

            int t = scanner.nextInt();                     // number of test cases
            while (t-- > 0) {
                solve();
            }
        } finally {
            // Ensure writer is flushed even if an exception occurs.
            writer.flush();
        }
    }

    /** Solves one test case. */
    private static void solve() {
        int rows = scanner.nextInt();   // n
        int cols = scanner.nextInt();   // m

        // Read the matrix – its values are not used for output, only validation.
        int[][] matrix = new int[rows][cols];
        boolean valid = true;

        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                matrix[i][j] = scanner.nextInt();

                int maxAllowed = neighbourCapacity(i, j, rows, cols);
                if (matrix[i][j] > maxAllowed) {
                    valid = false;          // a value exceeds the permissible neighbour count
                }
            }
        }

        if (!valid) {
            writer.println("NO");
            return;
        }

        writer.println("YES");
        printPattern(rows, cols);
    }

    /** Prints the required neighbour‑capacity pattern. */
    private static void printPattern(int rows, int cols) {
        for (int i = 0; i < rows; i++) {
            StringBuilder line = new StringBuilder();
            for (int j = 0; j < cols; j++) {
                line.append(neighbourCapacity(i, j, rows, cols));
                if (j < cols - 1) {
                    line.append(' ');
                }
            }
            writer.println(line);
        }
    }

    /**
     * Returns the maximum neighbour count for a cell at (i, j) in a {@code rows × cols} grid.
     * <p>
     * Corner cells have 2 neighbours, edge‑but‑not‑corner cells have 3 neighbours,
     * and inner cells have 4 neighbours.
     *
     * @param i      row index (0‑based)
     * @param j      column index (0‑based)
     * @param rows   total rows of the matrix
     * @param cols   total columns of the matrix
     * @return neighbour count (2, 3 or 4)
     */
    private static int neighbourCapacity(int i, int j, int rows, int cols) {
        int capacity = 4;

        if (i == 0 || i == rows - 1) {
            capacity--;                // top or bottom edge
        }
        if (j == 0 || j == cols - 1) {
            capacity--;                // left or right edge
        }
        return capacity;
    }

    /**
     * Simple tokeniser wrapper around a {@link BufferedReader}.
     */
    private static class FastScanner {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        FastScanner(BufferedReader reader) {
            this.reader = reader;
        }

        /** Returns the next token from the input, expanding the tokenizer as needed. */
        private String nextToken() throws Exception {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                tokenizer = new StringTokenizer(reader.readLine());
            }
            return tokenizer.nextToken();
        }

        /** Convenience wrappers for primitive types. */
        int nextInt() throws Exception { return Integer.parseInt(nextToken()); }
        long nextLong() throws Exception { return Long.parseLong(nextToken()); }
        double nextDouble() throws Exception { return Double.parseDouble(nextToken()); }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.PrintWriter;
import java.util.StringTokenizer;

/**
 * Solution – entry point for the problem.
 *
 * <p>This class refactors the original code for better maintainability:
 * <ul>
 *   <li>Descriptive identifiers and method names.</li>
 *   <li>Single‑responsibility methods (input handling, validation, output).</li>
 *   <li>Clear separation of concerns – logic is isolated from I/O.</li>
 *   <li>Early returns and reduced nesting instead of many flags.</li>
 *   <li>Helper {@code FastReader} for fast parsing of standard input.</li>
 * </ul>
 */
public class Solution {

    /* --------------------------------------------------------------------- */
    /*  Helper: fast tokenized input                                           */
    /* --------------------------------------------------------------------- */
    private static final class FastReader {
        private final BufferedReader br;
        private StringTokenizer st;

        FastReader() {
            br = new BufferedReader(new java.io.InputStreamReader(System.in));
        }

        /** Returns the next token from the input stream. */
        String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    throw new UncheckedIOException(e);
                }
            }
            return st.nextToken();
        }

        /** Convenience method for the most common token type. */
        int nextInt() {
            return Integer.parseInt(next());
        }
    }

    /* --------------------------------------------------------------------- */
    /*  Main driver                                                            */
    /* --------------------------------------------------------------------- */
    public static void main(String[] args) {
        FastReader reader = new FastReader();
        PrintWriter out = new PrintWriter(System.out);

        int testCases = reader.nextInt();
        for (int t = 0; t < testCases; t++) {
            solveOneTestCase(reader, out);
        }

        out.flush();               // flush any buffered output
    }

    /** Handles a single test case: reads, processes, and prints the answer. */
    private static void solveOneTestCase(FastReader reader, PrintWriter out) {
        int rows = reader.nextInt();
        int cols = reader.nextInt();

        int[][] grid = new int[rows][cols];
        fillGrid(reader, grid);

        if (canTransform(grid, rows, cols)) {
            out.println("YES");
            printGrid(grid, out);
        } else {
            out.println("NO");
        }
    }

    /** Reads the numeric grid from the input tokenizer. */
    private static void fillGrid(FastReader reader, int[][] grid) {
        for (int i = 0; i < grid.length; i++) {
            for (int j = 0; j < grid[i].length; j++) {
                grid[i][j] = reader.nextInt();
            }
        }
    }

    /** Determines whether the grid can be transformed to satisfy the neighbour rule. */
    private static boolean canTransform(int[][] grid, int rows, int cols) {
        // Compute the number of orthogonal neighbours for each cell.
        int[][] neighbourCount = new int[rows][cols];
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                int cnt = 0;
                if (i - 1 >= 0) cnt++;
                if (j - 1 >= 0) cnt++;
                if (j + 1 < cols) cnt++;
                if (i + 1 < rows) cnt++;
                neighbourCount[i][j] = cnt;
            }
        }

        // Verify condition and replace with neighbour count.
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] > neighbourCount[i][j]) {
                    return false;               // impossible to satisfy
                }
                grid[i][j] = neighbourCount[i][j];
            }
        }
        return true;                         // all cells satisfied
    }

    /** Prints the transformed grid in the required format. */
    private static void printGrid(int[][] grid, PrintWriter out) {
        for (int[] row : grid) {
            StringBuilder sb = new StringBuilder();
            for (int val : row) {
                sb.append(val).append(' ');
            }
            out.println(sb.toString().trim());
        }
    }
}

package solution;

import java.util.Scanner;

/**
 * Reads multiple test cases, validates each matrix against the neighbour‑count rule,
 * and outputs either "NO" or "YES" followed by the transformed matrix.
 */
public class Solution {

    /** Modifies the matrix in‑place to store neighbour counts for each cell. */
    private static boolean fillNeighbourCounts(int[][] grid, int rows, int cols) {
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                int neighbourCount = countNeighbouringCells(rows, cols, i, j);
                if (grid[i][j] > neighbourCount) {
                    // Rule violation – transformation impossible.
                    return false;
                }
                grid[i][j] = neighbourCount;
            }
        }
        return true;
    }

    /** Returns how many orthogonal neighbours a cell at (row, col) can have. */
    private static int countNeighbouringCells(int rows, int cols, int row, int col) {
        int count = 0;
        if (row > 0)        count++;
        if (row < rows - 1) count++;
        if (col > 0)        count++;
        if (col < cols - 1) count++;
        return count;
    }

    /** Reads a matrix of the given dimensions from the scanner. */
    private static int[][] readMatrix(Scanner scanner, int rows, int cols) {
        int[][] matrix = new int[rows][cols];
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                matrix[i][j] = scanner.nextInt();
            }
        }
        return matrix;
    }

    /** Prints the matrix row‑by‑row. */
    private static void printMatrix(int[][] matrix) {
        for (int[] row : matrix) {
            for (int value : row) {
                System.out.print(value + " ");
            }
            System.out.println();
        }
    }

    /** Entry point – processes all test cases. */
    public static void main(String[] args) {
        // try‑with‑resources guarantees the Scanner is closed automatically.
        try (Scanner scanner = new Scanner(System.in)) {
            int testCases = scanner.nextInt();

            while (testCases-- > 0) {
                int rows = scanner.nextInt();
                int cols = scanner.nextInt();
                int[][] values = readMatrix(scanner, rows, cols);

                boolean possible = fillNeighbourCounts(values, rows, cols);

                if (!possible) {
                    System.out.println("NO");
                } else {
                    System.out.println("YES");
                    printMatrix(values);
                }
            }
        }
    }
}

import java.io.PrintWriter;
import java.util.Scanner;

/**
 * Refactored solution for the original algorithm.
 * <p>
 * The program reads multiple test cases, each consisting of a matrix {@code a}.
 * It builds a matrix {@code ans} with predefined border values and checks whether
 * {@code ans[i][j] >= a[i][j] for all cells}. If the condition holds, the matrix
 * {@code ans} is printed together with "YES", otherwise only "NO" is printed.
 * </p>
 */
public class codeforces {

    /** Minimum value that can be assigned to a corner cell. */
    private static final int CORNER_MIN = 2;

    /** Minimum value that can be assigned to an edge (non‑corner boundary) cell. */
    private static final int EDGE_MIN = 3;

    /** Minimum value that can be assigned to an interior cell. */
    private static final int INTERIOR_MIN = 4;

    public static void main(String[] args) {
        // Use try‑with‑resources to guarantee proper closing of streams
        try (Scanner scanner = new Scanner(System.in);
             PrintWriter out = new PrintWriter(System.out)) {

            int t = scanner.nextInt();
            for (int testCase = 0; testCase < t; testCase++) {
                solveCase(scanner, out);
            }
        }
    }

    /**
     * Handles one test case: reads the matrix, builds the candidate answer,
     * validates it and prints the result.
     */
    private static void solveCase(Scanner scanner, PrintWriter out) {
        int n = scanner.nextInt();
        int m = scanner.nextInt();

        int[][] source = readMatrix(scanner, n, m);
        int[][] answer = buildAnswerMatrix(n, m);

        if (!isValid(source, answer)) {
            out.println("NO");
            return;
        }

        out.println("YES");
        printMatrix(answer, out);
    }

    /**
     * Reads an {@code n × m} integer matrix from the scanner.
     */
    private static int[][] readMatrix(Scanner scanner, int n, int m) {
        int[][] matrix = new int[n][m];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                matrix[i][j] = scanner.nextInt();
            }
        }
        return matrix;
    }

    /**
     * Constructs the candidate answer matrix with fixed border values.
     * Interior cells receive {@link #INTERIOR_MIN}.
     */
    private static int[][] buildAnswerMatrix(int n, int m) {
        int[][] ans = new int[n][m];

        // Fill borders
        for (int i = 0; i < n; i++) {
            ans[i][0] = (i == 0 || i == n - 1) ? CORNER_MIN : EDGE_MIN;
            ans[i][m - 1] = (i == 0 || i == n - 1) ? CORNER_MIN : EDGE_MIN;
        }
        for (int j = 0; j < m; j++) {
            ans[0][j] = (j == 0 || j == m - 1) ? CORNER_MIN : EDGE_MIN;
            ans[n - 1][j] = (j == 0 || j == m - 1) ? CORNER_MIN : EDGE_MIN;
        }

        // Corners are explicitly set (may be overwritten by the loops above)
        ans[0][0] = CORNER_MIN;
        ans[0][m - 1] = CORNER_MIN;
        ans[n - 1][m - 1] = CORNER_MIN;
        ans[n - 1][0] = CORNER_MIN;

        // Interior cells
        for (int i = 1; i < n - 1; i++) {
            for (int j = 1; j < m - 1; j++) {
                ans[i][j] = INTERIOR_MIN;
            }
        }

        return ans;
    }

    /**
     * Checks whether every element of {@code source} is less than or equal to the
     * corresponding element of {@code candidate}.
     */
    private static boolean isValid(int[][] source, int[][] candidate) {
        for (int i = 0; i < source.length; i++) {
            for (int j = 0; j < source[i].length; j++) {
                if (source[i][j] > candidate[i][j]) {
                    return false;
                }
            }
        }
        return true;
    }

    /**
     * Prints the matrix to the supplied {@link PrintWriter} using a single space
     * between elements and a line break after each row.
     */
    private static void printMatrix(int[][] matrix, PrintWriter out) {
        for (int[] row : matrix) {
            for (int value : row) {
                out.print(value);
                out.print(' ');
            }
            out.println();
        }
    }
}

import java.io.*;
import java.util.StringTokenizer;

/**
 * Refactored version of the original {@code TaskB} solution.
 *
 * <p>Changes made for maintainability and readability:
 * <ul>
 *   <li>Extracted parsing and solving logic into dedicated helper methods.</li>
 *   <li>Used {@code try‑with‑resources} for automatic resource management.</li>
 *   <li>Renamed variables to expressive names (e.g., {@code rows}, {@code cols}).</li>
 *   <li>Isolated neighbor‑count calculation in its own method.</li>
 *   <li>Separated input reading, processing, and output generation.</li>
 *   <li>Removed unnecessary mutable state and kept Kotlin‑style immutability where possible.</li>
 *   <li>Added Javadoc comments and clear method boundaries.</li>
 * </ul>
 */
public class TaskB {

    /** Solver encapsulates all logic required for a single test case. */
    private static final class Solver {

        private final BufferedReader reader;
        private final PrintWriter writer;

        Solver(BufferedReader reader, PrintWriter writer) {
            this.reader = reader;
            this.writer = writer;
        }

        /** Entry point for processing all test cases. */
        void solve() throws IOException {
            int testCases = readInt();
            for (int t = 0; t < testCases; t++) {
                boolean possible = solveTestCase();
                writer.println(possible ? "YES" : "NO");
                if (possible) {
                    outputGrid();
                }
            }
        }

        /** Reads one test case, performs validation and writes the result. */
        private boolean solveTestCase() throws IOException {
            int rows = readInt();
            int cols = readInt();
            int[][] grid = readIntMatrix(rows, cols);

            int[][] transformed = new int[rows][cols];
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    int neighborCount = countNeighbors(i, j, rows, cols);
                    if (grid[i][j] > neighborCount) {
                        return false;               // Impossible condition detected
                    }
                    transformed[i][j] = neighborCount;
                }
            }
            outputGrid(transformed);
            return true;
        }

        /** Reads a matrix of size {@code rows × cols} from the input stream. */
        private int[][] readIntMatrix(int rows, int cols) throws IOException {
            int[][] matrix = new int[rows][cols];
            for (int i = 0; i < rows; i++) {
                StringTokenizer st = new StringTokenizer(reader.readLine());
                for (int j = 0; j < cols; j++) {
                    matrix[i][j] = readInt(st);
                }
            }
            return matrix;
        }

        /** Returns the number of orthogonal neighbors for cell (i, j). */
        private int countNeighbors(int i, int j, int rows, int cols) {
            int count = 0;
            if (i > 0) count++;                 // top
            if (i + 1 < rows) count++;          // bottom
            if (j > 0) count++;                 // left
            if (j + 1 < cols) count++;          // right
            return count;
        }

        /** Convenience wrapper around {@link StringTokenizer} for reading ints. */
        private int readInt(StringTokenizer st) {
            return Integer.parseInt(st.nextToken());
        }

        /** Writes the entire matrix to the output stream, preserving format. */
        private void outputGrid(int[][] matrix) {
            StringBuilder sb = new StringBuilder();
            for (int[] row : matrix) {
                for (int value : row) {
                    sb.append(value).append(' ');
                }
                sb.append('\n');
            }
            writer.print(sb.toString());
        }
    }

    /** Program entry point. */
    public static void main(String[] args) throws Exception {
        // try‑with‑resources guarantees proper closure of I/O streams.
        try (BufferedReader br = new BufferedReader(
                new InputStreamReader(System.in));
             PrintWriter pw = new PrintWriter(System.out)) {

            new Solver(br, pw).solve();
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Reads a grid, computes how many orthogonal neighbours each cell has,
 * and checks whether every cell can be satisfied by that neighbour count.
 *
 * <p>This refactor improves readability, separates concerns into small
 * pure methods and uses more expressive naming.</p>
 */
public class NeighborGrid {

    /** Small wrapper around a 2‑dimensional integer matrix. */
    private static final class Grid {
        private final int rows;
        private final int columns;
        private final int[][] values;

        Grid(int rows, int columns) {
            this.rows = rows;
            this.columns = columns;
            this.values = new int[rows][columns];
        }

        /** Returns the element at (row, col). */
        int get(int row, int col) {
            return values[row][col];
        }

        /** Stores a value at (row, col). */
        void set(int row, int col, int value) {
            values[row][col] = value;
        }

        int rows() {
            return rows;
        }

        int columns() {
            return columns;
        }
    }

    /** Reads a matrix of the given size from the supplied BufferedReader. */
    private static Grid readGrid(BufferedReader reader, int rows, int columns) throws IOException {
        Grid grid = new Grid(rows, columns);
        for (int r = 0; r < rows; r++) {
            StringTokenizer st = new StringTokenizer(reader.readLine());
            if (st.countTokens() < columns) {
                throw new IllegalArgumentException(
                    "Row " + (r + 1) + " does not contain enough numbers");
            }
            for (int c = 0; c < columns; c++) {
                grid.set(r, c, Integer.parseInt(st.nextToken()));
            }
        }
        return grid;
    }

    /** Computes, for each cell, the number of orthogonal neighbours it has. */
    private static Grid computeNeighborDegrees(Grid original) {
        int rows = original.rows();
        int cols = original.columns();
        Grid degrees = new Grid(rows, cols);

        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                int neighborCount = 4;                     // max possible
                if (r == 0)                                 // top edge
                    neighborCount--;
                if (c == 0)                                 // left edge
                    neighborCount--;
                if (r == rows - 1)                          // bottom edge
                    neighborCount--;
                if (c == cols - 1)                          // right edge
                    neighborCount--;

                degrees.set(r, c, neighborCount);
            }
        }
        return degrees;
    }

    /** Checks whether every cell’s neighbour‑count is at least its original value. */
    private static boolean isFeasible(Grid original, Grid degrees) {
        for (int r = 0; r < original.rows(); r++) {
            for (int c = 0; c < original.columns(); c++) {
                if (degrees.get(r, c) < original.get(r, c)) {
                    return false;
                }
            }
        }
        return true;
    }

    /** Prints a matrix row‑by‑row to standard output. */
    private static void printMatrix(Grid grid) {
        for (int r = 0; r < grid.rows(); r++) {
            StringBuilder sb = new StringBuilder();
            for (int c = 0; c < grid.columns(); c++) {
                sb.append(grid.get(r, c)).append(' ');
            }
            System.out.println(sb.toString().trim());
        }
    }

    /** Main driver – processes multiple test cases from stdin. */
    public static void main(String[] args) throws IOException {
        // Try‑with‑resources ensures the reader is closed automatically.
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in))) {
            int testCases = Integer.parseInt(br.readLine().trim());

            while (testCases-- > 0) {
                // ----- read dimensions -----
                StringTokenizer dimTok = new StringTokenizer(br.readLine());
                int rows = Integer.parseInt(dimTok.nextToken());
                int columns = Integer.parseInt(dimTok.nextToken());

                // ----- read the original grid -----
                Grid original = readGrid(br, rows, columns);

                // ----- compute neighbour‑degree matrix -----
                Grid neighborDegrees = computeNeighborDegrees(original);

                // ----- validate and output -----
                if (isFeasible(original, neighborDegrees)) {
                    System.out.println("YES");
                    printMatrix(neighborDegrees);
                } else {
                    System.out.println("NO");
                }
            }
        }
    }
}

import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

/**
 * Fast input scanner based on BufferedReader + StringTokenizer.
 */
final class FastScanner {
    private final BufferedReader br;

    public FastScanner(InputStream input) {
        this.br = new BufferedReader(new InputStreamReader(input));
    }

    /** Ensures a non‑empty StringTokenizer is available, reading a new line if needed. */
    private void prepareTokenizer() throws IOException {
        while (tokenizer == null || !tokenizer.hasMoreTokens()) {
            String line = br.readLine();
            if (line == null) {
                return; // EOF
            }
            tokenizer = new StringTokenizer(line);
        }
    }

    private StringTokenizer tokenizer;

    /** Returns the next integer token, throwing IOException on EOF. */
    int nextInt() throws IOException {
        prepareTokenizer();
        return Integer.parseInt(tokenizer.nextToken());
    }

    /** Returns the next double token, throwing IOException on EOF. */
    double nextDouble() throws IOException {
        prepareTokenizer();
        return Double.parseDouble(tokenizer.nextToken());
    }

    /** Returns the next non‑whitespace string token, throwing IOException on EOF. */
    String next() throws IOException {
        prepareTokenizer();
        return tokenizer.nextToken();
    }

    /** True if more tokens are available. */
    boolean hasNext() throws IOException {
        prepareTokenizer();
        return tokenizer.hasMoreTokens();
    }
}

/**
 * Main class containing the solution logic.
 *
 * <p>Refactored goals:
 * <ul>
 *   <li>Separate I/O from business logic.</li>
 *   <li>Use meaningful identifiers and constants.</li>
 *   <li>Extract small helper methods to improve readability.</li>
 *   <li>Make the algorithm’s intent explicit.</li>
 * </ul>
 */
public class Main {

    /** Value placed at the four corners of the pattern matrix. */
    private static final int CORNER = 2;

    /** Value placed on the border but not on a corner. */
    private static final int EDGE = 3;

    /** Value placed in the interior of the matrix. */
    private static final int INTERIOR = 4;

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        StringBuilder output = new StringBuilder();

        int tests = fs.nextInt();
        for (int t = 0; t < tests; t++) {
            int n = fs.nextInt();
            int m = fs.nextInt();
            int[][] data = readMatrix(fs, n, m);
            String result = solveAndPrint(n, m, data);
            output.append(result).append('\n');
        }

        System.out.print(output.toString());
    }

    /** Reads an n × m integer matrix from the scanner. */
    private static int[][] readMatrix(FastScanner fs, int n, int m) {
        int[][] matrix = new int[n][m];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                matrix[i][j] = fs.nextInt();
            }
        }
        return matrix;
    }

    /**
     * Builds the required pattern matrix, checks the constraints,
     * and formats the answer.
     *
     * @return "YES\\n" followed by the pattern matrix if valid,
     *         otherwise "NO".
     */
    private static String solveAndPrint(int n, int m, int[][] data) {
        int[][] pattern = new int[n][m];

        assignPatternValues(pattern);
        fillRemainingWithInterior(pattern);

        if (violates(data, pattern)) {
            return "NO";
        }

        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                sb.append(pattern[i][j]);
                if (j < m - 1) {
                    sb.append(' ');
                }
            }
            sb.append('\n');
        }
        return "YES\n" + sb.toString();
    }

    /** Sets the corner and edge positions of the pattern matrix. */
    private static void assignPatternValues(int[][] pattern) {
        int rows = pattern.length;
        int cols = pattern[0].length;

        // corners
        pattern[0][0] = pattern[rows - 1][0] = pattern[0][cols - 1] = pattern[rows - 1][cols - 1] = CORNER;

        // top & bottom borders (except corners)
        for (int j = 1; j < cols - 1; j++) {
            pattern[0][j] = EDGE;
            pattern[rows - 1][j] = EDGE;
        }

        // left & right borders (except corners)
        for (int i = 1; i < rows - 1; i++) {
            pattern[i][0] = EDGE;
            pattern[i][cols - 1] = EDGE;
        }
    }

    /** Fills every still‑zero cell with the interior value. */
    private static void fillRemainingWithInterior(int[][] pattern) {
        for (int i = 0; i < pattern.length; i++) {
            for (int j = 0; j < pattern[i].length; j++) {
                if (pattern[i][j] == 0) {
                    pattern[i][j] = INTERIOR;
                }
            }
        }
    }

    /** Checks whether any data element exceeds the corresponding pattern element. */
    private static boolean violates(int[][] data, int[][] pattern) {
        for (int i = 0; i < data.length; i++) {
            for (int j = 0; j < data[i].length; j++) {
                if (data[i][j] > pattern[i][j]) {
                    return true;
                }
            }
        }
        return false;
    }
}

