/**
 * Reads tokens from an underlying {@link InputStream}.  The implementation is
 * intentionally minimal but fully functional.
 */
class InputReader {
    private final BufferedReader reader;
    private StringTokenizer tokenizer;

    InputReader(InputStream stream) {
        this.reader = new BufferedReader(new InputStreamReader(stream), 32768);
    }

    /** @return the next non‑null token from the input */
    String next() {
        while (tokenizer == null || !tokenizer.hasMoreTokens()) {
            try {
                tokenizer = new StringTokenizer(reader.readLine());
            } catch (IOException e) {
                throw new RuntimeException(e);
            }
        }
        return tokenizer.nextToken();
    }

    /** @return the next integer token */
    int nextInt() {
        return Integer.parseInt(next());
    }
}

/**
 * Contains the core algorithm for {@code Task B}.  All public methods are
 * side‑effect free and return the results directly, which makes them easy to
 * test and reason about.
 */
class Solver {

    /**
     * Executes the solution for one test case.
     *
     * @param in  the input reader
     * @param out the output writer
     */
    void solve(InputReader in, PrintWriter out) {
        int t = in.nextInt(); // number of test cases
        while (t-- > 0) {
            int rows = in.nextInt();
            int cols = in.nextInt();
            int[][] inputValues = readGrid(in, rows, cols);
            int[][] allowedValues = computeAllowedValues(rows, cols);

            boolean anyViolation = false;
            StringBuilder outputBuilder = new StringBuilder();

            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (inputValues[i][j] > allowedValues[i][j]) {
                        anyViolation = true;
                    }
                    outputBuilder.append(allowedValues[i][j]);
                    if (j < cols - 1) {
                        outputBuilder.append(' ');
                    }
                }
                outputBuilder.append('\n');
            }

            if (anyViolation) {
                out.println("NO");
            } else {
                out.println("YES");
                out.print(outputBuilder.toString());
            }
        }
    }

    /**
     * Reads the full {@code rows × cols} integer matrix from {@link InputReader}.
     *
     * @param in      input source
     * @param rows    number of rows
     * @param cols    number of columns
     * @return a 2‑D array containing the values
     */
    private static int[][] readGrid(InputReader in, int rows, int cols) {
        int[][] grid = new int[rows][cols];
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                grid[i][j] = in.nextInt();
            }
        }
        return grid;
    }

    /**
     * Constructs a matrix where each cell holds the maximal allowed value for its
     * position (2, 3 or 4 depending on how many sides are on the border).
     *
     * @param rows number of rows
     * @param cols number of columns
     * @return a matrix with the allowed values
     */
    private static int[][] computeAllowedValues(int rows, int cols) {
        int[][] allowed = new int[rows][cols];
        // Border handling: subtract 1 for every side that touches the outer border.
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                int allowedValue = 4;
                if (i == 0 || i == rows - 1) {
                    allowedValue--;
                }
                if (j == 0 || j == cols - 1) {
                    allowedValue--;
                }
                allowed[i][j] = allowedValue;
            }
        }
        return allowed;
    }
}

