import java.io.*;
import java.util.*;

public class Main {

    /** Direction vectors for up, down, left, right. */
    private static final int[][] DIRECTIONS = {
            {-1, 0},
            {1, 0},
            {0, -1},
            {0, 1}
    };

    /** Fast scanner for reading input data. */
    private static final FastScanner FS = new FastScanner();

    /** Returns the number of adjacent cells of (row, col) inside a matrix
     *  with the given dimensions. */
    private static int neighborCount(int row, int col, int rows, int cols) {
        int count = 0;
        for (int[] d : DIRECTIONS) {
            int nr = row + d[0];
            int nc = col + d[1];
            if (nr >= 0 && nr < rows && nc >= 0 && nc < cols) {
                count++;
            }
        }
        return count;
    }

    /** Checks whether a matrix obeys the problem constraint:
     *  each cell value must not exceed the number of its neighboring cells.
     */
    private static boolean isValid(int[][] matrix, int rows, int cols) {
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                int allowed = neighborCount(i, j, rows, cols);
                if (matrix[i][j] > allowed) {
                    return false;
                }
            }
        }
        return true;
    }

    /** Replaces each cell with the count of its neighboring cells (its degree). */
    private static void fillDegrees(int[][] matrix, int rows, int cols) {
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                matrix[i][j] = neighborCount(i, j, rows, cols);
            }
        }
    }

    public static void main(String[] args) throws IOException {
        PrintWriter out = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)));
        int t = FS.nextInt();

        while (t-- > 0) {
            int rows = FS.nextInt();
            int cols = FS.nextInt();
            int[][] matrix = FS.readMatrix(rows, cols);

            if (!isValid(matrix, rows, cols)) {
                out.println("NO");
                continue;
            }

            fillDegrees(matrix, rows, cols);
            out.println("YES");
            out.printMatrix(matrix);
        }

        out.flush();
    }

    /** Simple fast scanner that supports reading ints, longs and matrices. */
    static final class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner() {
            this(System.in);
        }

        FastScanner(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        /** Retrieves the next token, expanding the tokenizer when needed. */
        private String next() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                String line = br.readLine();
                if (line == null) {
                    return null;
                }
                st = new StringTokenizer(line);
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        long nextLong() {
            return Long.parseLong(next());
        }

        /** Reads an int matrix of size rows × cols. */
        int[][] readMatrix(int rows, int cols) {
            int[][] matrix = new int[rows][cols];
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    matrix[i][j] = nextInt();
                }
            }
            return matrix;
        }

        /** Writes a matrix to System.out; kept as a convenience method. */
        void printMatrix(int[][] matrix) {
            for (int[] row : matrix) {
                for (int value : row) {
                    System.out.print(value + " ");
                }
                System.out.println();
            }
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.StringTokenizer;

/**
 * Refactored solution for the “Neighbor Count” problem.
 *
 * <p>
 * The algorithm:
 * <ol>
 *   <li>Read a test case consisting of a matrix {@code a} of size {@code R × C}.</li>
 *   <li>For each cell compute the number of orthogonal neighbours that exist
 *       inside the matrix (i.e. cells reachable by moving one step up, down,
 *       left or right). This value is stored in {@code neighborCount[row][col]}.</li>
 *   <li>If any cell value {@code a[row][col]} is larger than its neighbour count,
 *       the answer for the test case is {@code NO}.</li>
 *   <li>Otherwise the answer is {@code YES} and the neighbour‑count matrix is
 *       printed.</li>
 * </ol>
 * </p>
 *
 * The refactor focuses on readability, separation of concerns and defensive
 * programming while preserving the original behaviour.
 */
public class Solver {

    /** Directions: right, up, left, down */
    private static final int[][] DIRS = {
            {0, 1},  // right
            {-1, 0}, // up
            {0, -1}, // left
            {1, 0}   // down
    };

    /** Fast scanner used for all test cases */
    private static final InputReader IN = new InputReader();

    /** PrintWriter that writes to standard output */
    private static final PrintWriter OUT = new PrintWriter(System.out, true);

    /** Number of rows of the current matrix */
    private static int rows;

    /** Number of columns of the current matrix */
    private static int cols;

    /** Input matrix supplied by the problem */
    private static int[][] input;

    /** Matrix containing the number of valid neighbours for each cell */
    private static int[][] neighbourCount;

    public static void main(String[] args) throws IOException {
        int testCases = IN.nextInt();

        for (int tc = 1; tc <= testCases; ++tc) {
            readMatrix();
            buildNeighbourCount();
            if (!isValid()) {
                OUT.println("NO");
            } else {
                OUT.println("YES");
                printNeighbourCount();
            }
        }

        OUT.flush();
    }

    /** Reads {@code rows} and {@code cols} and the following {@code rows × cols}
     *  integers into {@link #input}. */
    private static void readMatrix() {
        rows = IN.nextInt();
        cols = IN.nextInt();

        input = new int[rows][cols];
        for (int r = 0; r < rows; ++r) {
            for (int c = 0; c < cols; ++c) {
                input[r][c] = IN.nextInt();
            }
        }
    }

    /** Fills {@link #neighbourCount} with the count of orthogonal neighbours
     *  that exist for each cell. */
    private static void buildNeighbourCount() {
        neighbourCount = new int[rows][cols];

        for (int r = 0; r < rows; ++r) {
            for (int c = 0; c < cols; ++c) {
                int count = 0;
                for (int[] dir : DIRS) {
                    int nr = r + dir[0];
                    int nc = c + dir[1];
                    if (isInBounds(nr, nc)) {
                        ++count;
                    }
                }
                neighbourCount[r][c] = count;
            }
        }
    }

    /** Returns {@code true} if every cell value is not larger than its neighbour
     *  count, i.e. the matrix satisfies the problem constraints. */
    private static boolean isValid() {
        for (int r = 0; r < rows; ++r) {
            for (int c = 0; c < cols; ++c) {
                if (input[r][c] > neighbourCount[r][c]) {
                    return false;
                }
            }
        }
        return true;
    }

    /** Prints the neighbour‑count matrix row by row. */
    private static void printNeighbourCount() {
        for (int r = 0; r < rows; ++r) {
            StringBuilder line = new StringBuilder();
            for (int c = 0; c < cols; ++c) {
                line.append(neighbourCount[r][c]).append(' ');
            }
            OUT.println(line.toString().trim());
        }
    }

    /** Utility class that encapsulates fast tokenised input. */
    private static class InputReader {
        private final BufferedReader br;
        private StringTokenizer st;

        InputReader() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        /** Returns the next non‑empty token. */
        private String nextToken() throws IOException {
            while (st == null || !st.hasMoreElements()) {
                String line = br.readLine();
                if (line == null) {
                    return null;
                }
                st = new StringTokenizer(line);
            }
            return st.nextToken();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(nextToken());
        }

        long nextLong() throws IOException {
            return Long.parseLong(nextToken());
        }
    }
}

import java.io.*;
import java.util.StringTokenizer;

/**
 * CF1375B – Walls Fractal
 *
 * <p>Refactored for readability, maintainability and clarity.</p>
 */
public class CF1375B {

    /** Upper bound for each cell in the generated grid. */
    private static final int MAX_VAL = 4;

    /** Fast input helper used by the solution. */
    private static final class FastInput {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        FastInput(InputStream stream) {
            this.reader = new BufferedReader(new InputStreamReader(stream));
        }

        /** Reads the next token from the input. */
        private String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new UncheckedIOException(e);
                }
            }
            return tokenizer.nextToken();
        }

        /** Reads the next integer from the input. */
        int nextInt() {
            return Integer.parseInt(next());
        }

        /** Closes the underlying reader. */
        void close() {
            try {
                reader.close();
            } catch (IOException e) {
                throw new UncheckedIOException(e);
            }
        }
    }

    /** Entry point. */
    public static void main(String[] args) throws Exception {
        new CF1375B().solve();
    }

    /** Solves one test case suite. */
    private void solve() throws Exception {
        try (FastInput in = new FastInput(System.in);
             PrintWriter out = new PrintWriter(System.out)) {

            int testCases = in.nextInt();

            while (testCases-- > 0) {
                solveSingleCase(in, out);
            }

            out.flush();
        }
    }

    /** Handles a single test case: reading input, processing and printing the answer. */
    private void solveSingleCase(FastInput in, PrintWriter out) {
        int rows = in.nextInt();
        int cols = in.nextInt();

        int[][] original = readOriginal(in, rows, cols);
        int[][] generated = createGeneratedGrid(rows, cols);

        if (isValid(original, generated, rows, cols)) {
            printYes(out);
            printGrid(generated, out);
        } else {
            printNo(out);
        }
    }

    /** Reads the provided grid from the input. */
    private static int[][] readOriginal(FastInput in, int rows, int cols) {
        int[][] data = new int[rows][cols];
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                data[i][j] = in.nextInt();
            }
        }
        return data;
    }

    /** Creates a grid where each cell equals MAX_VAL minus one for every border it touches. */
    private static int[][] createGeneratedGrid(int rows, int cols) {
        int[][] grid = new int[rows][cols];

        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                int value = MAX_VAL;

                if (i == 0 || i == rows - 1) {
                    value--;
                }
                if (j == 0 || j == cols - 1) {
                    value--;
                }

                grid[i][j] = value;
            }
        }

        return grid;
    }

    /**
     * Checks whether every cell of {@code original} is ≤ the corresponding cell in {@code generated}.
     *
     * @return {@code true} if the generated grid can satisfy the original constraints.
     */
    private static boolean isValid(int[][] original, int[][] generated, int rows, int cols) {
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (generated[i][j] < original[i][j]) {
                    return false;
                }
            }
        }
        return true;
    }

    /** Prints "YES" to the output stream. */
    private static void printYes(PrintWriter out) {
        out.println("YES");
    }

    /** Prints "NO" to the output stream. */
    private static void printNo(PrintWriter out) {
        out.println("NO");
    }

    /** Prints a grid to the output stream, row by row. */
    private static void printGrid(int[][] grid, PrintWriter out) {
        for (int[] row : grid) {
            StringBuilder sb = new StringBuilder();
            for (int cell : row) {
                sb.append(cell).append(' ');
            }
            out.println(sb.toString().trim());
        }
    }
}

import java.util.Scanner;

/**
 * Reads one or more test cases, each consisting of a rectangular integer matrix.
 * For every cell it computes the number of orthogonal neighbours the cell has.
 * If every cell value is less than or equal to its neighbour count, the matrix is
 * transformed by replacing each value with that count; otherwise the word “NO”
 * is printed.  When the transformation succeeds, the word “YES” followed by the
 * transformed matrix is printed.
 *
 * The program has been refactored for readability, proper naming, separation of
 * concerns and robust resource handling.
 */
public class NeighbourhoodProcessor {

    /** Counts the orthogonal neighbours of cell (i, j) in an {@code rows×cols} grid. */
    private static int neighbourCount(int i, int j, int rows, int cols) {
        int count = 0;
        if (i > 0)               count++;      // top
        if (i < rows - 1)        count++;      // bottom
        if (j > 0)               count++;      // left
        if (j < cols - 1)        count++;      // right
        return count;
    }

    /**
     * Attempts to transform the supplied matrix according to the problem rules.
     *
     * @param matrix the matrix to transform (modified in‑place)
     * @return {@code true} if every element satisfied the transformation condition,
     *         {@code false} otherwise
     */
    private static boolean tryTransform(int[][] matrix) {
        final int rows = matrix.length;
        final int cols = matrix[0].length;
        boolean anyUpdated = false;                 // mimics original variable {@code k}

        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                int neigh = neighbourCount(i, j, rows, cols);

                // Update only if the current value is ≤ neighbour count
                // and at least one element has already passed the check.
                if (anyUpdated && matrix[i][j] <= neigh) {
                    matrix[i][j] = neigh;
                } else {
                    // Condition failed → transformation invalid for this test case.
                    return false;
                }
            }
        }
        return true;                                 // all elements satisfied the condition
    }

    /** Prints the matrix row by row, separating values with a single space. */
    private static void printMatrix(int[][] matrix) {
        for (int[] row : matrix) {
            for (int value : row) {
                System.out.print(value + " ");
            }
            System.out.println();
        }
    }

    /** Entry point – processes multiple test cases until the input is exhausted. */
    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            int testCases = scanner.nextInt();

            while (testCases-- > 0) {
                int rows = scanner.nextInt();
                int cols = scanner.nextInt();
                int[][] grid = new int[rows][cols];

                // Read the matrix data
                for (int i = 0; i < rows; i++) {
                    for (int j = 0; j < cols; j++) {
                        grid[i][j] = scanner.nextInt();
                    }
                }

                // Attempt the transformation
                boolean success = tryTransform(grid);

                if (!success) {
                    System.out.println("NO");
                } else {
                    System.out.println("YES");
                    printMatrix(grid);
                }
            }
        }
        // If the input stream ends unexpectedly (e.g., malformed input) we simply stop.
        catch (NoSuchElementException ignored) {
        }
    }
}

/**
 * Refactored version of the original program.
 * - Reads multiple test cases, each consisting of an n×m integer matrix.
 * - For every cell it counts how many orthogonal neighbours it has.
 * - If any cell value is larger than its neighbour count the answer is "NO".
 * - Otherwise the answer is "YES" followed by the matrix of neighbour counts.
 */
public class Main {

    /* -------------------------------------------------------------
     *  Simple scanner that works with BufferedReader.
     * ------------------------------------------------------------- */
    private static final class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner() {
            this.br = new BufferedReader(new java.io.InputStreamReader(System.in));
        }

        /** Returns the next token, retrying until one is available. */
        private String nextToken() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) {
                        return null;               // EOF
                    }
                    st = new StringTokenizer(line);
                } catch (Exception e) {
                    throw new RuntimeException(e);
                }
            }
            return st.nextToken();
        }

        /** Convenience wrappers for typical token types. */
        int nextInt() {
            return Integer.parseInt(nextToken());
        }

        long nextLong() {
            return Long.parseLong(nextToken());
        }

        /** Reads exactly n integers from the input and returns them as an array. */
        int[] nextIntArray(int n) {
            int[] arr = new int[n];
            for (int i = 0; i < n; i++) {
                arr[i] = nextInt();
            }
            return arr;
        }
    }

    /* -------------------------------------------------------------
     *  Utility class that encapsulates the neighbour‑count logic.
     * ------------------------------------------------------------- */
    private static final class NeighbourCounter {
        /** Returns the number of orthogonal neighbours a cell (i,j) has
         *  inside a matrix of size rows × cols. */
        static int count(int i, int j, int rows, int cols) {
            int sides = 0;
            if (i > 0)            sides++;
            if (j > 0)            sides++;
            if (i < rows - 1)     sides++;
            if (j < cols - 1)     sides++;
            return sides;
        }
    }

    /* -------------------------------------------------------------
     *  Core solving routine.
     * ------------------------------------------------------------- */
    private static void solve(FastScanner fs, PrintWriter out) {
        int testCases = fs.nextInt();
        for (int t = 0; t < testCases; t++) {
            int n = fs.nextInt();          // rows
            int m = fs.nextInt();          // columns
            int[][] values = new int[n][m];
            for (int i = 0; i < n; i++) {
                values[i] = fs.nextIntArray(m);
            }

            // Build the neighbour‑count matrix.
            int[][] neighbourCounts = new int[n][m];
            boolean invalid = false;
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    int cnt = NeighbourCounter.count(i, j, n, m);
                    neighbourCounts[i][j] = cnt;
                    // Original value must not exceed allowed neighbour count.
                    if (values[i][j] > cnt) {
                        invalid = true;
                    }
                }
            }

            if (invalid) {
                out.println("NO");
                continue;
            }

            // All constraints satisfied → output "YES" and the matrix.
            out.println("YES");
            out2dArray(out, neighbourCounts);
        }
    }

    /** Helper that prints a 2‑D int array using the supplied PrintWriter. */
    private static void out2dArray(PrintWriter out, int[][] arr) {
        for (int[] row : arr) {
            for (int val : row) {
                out.print(val + " ");
            }
            out.println();
        }
    }

    /* -------------------------------------------------------------
     *  Entry point – delegates all work to the Solver.
     * ------------------------------------------------------------- */
    public static void main(String[] args) {
        try (PrintWriter out = new PrintWriter(System.out)) {
            solve(new FastScanner(), out);
        }
    }
}

import java.io.PrintWriter;
import java.util.Scanner;

public class Main {

    /** Corner cells of the result matrix */
    private static final int CORNER = 2;
    /** Edge cells (excluding corners) of the result matrix */
    private static final int EDGE_NON_CORNER = 3;
    /** Interior cells of the result matrix */
    private static final int INTERIOR = 4;

    public static void main(String[] args) {
        // Try‑with‑resources ensures resources are closed automatically
        try (Scanner scanner = new Scanner(System.in);
             PrintWriter out = new PrintWriter(System.out, true)) {

            int testCases = scanner.nextInt();
            while (testCases-- > 0) {
                int rows = scanner.nextInt();
                int cols = scanner.nextInt();

                int[][] input = readMatrix(scanner, rows, cols);
                solveAndOutput(input, rows, cols, out);
            }
        }
    }

    /** Reads a matrix of the given dimensions from the scanner. */
    private static int[][] readMatrix(Scanner scanner, int rows, int cols) {
        int[][] matrix = new int[rows][cols];
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                matrix[i][j] = scanner.nextInt();
            }
        }
        return matrix;
    }

    /** Orchestrates solving one test case and writing the result. */
    private static void solveAndOutput(int[][] input, int rows, int cols, PrintWriter out) {
        int[][] result = buildResultMatrix(rows, cols);

        if (!isValid(input, result, rows, cols)) {
            out.println("NO");
            return;
        }

        out.println("YES");
        printMatrix(result, out);
    }

    /** Constructs the result matrix according to the problem rules. */
    private static int[][] buildResultMatrix(int rows, int cols) {
        int[][] matrix = new int[rows][cols];

        // Fill corners
        matrix[0][0] = matrix[0][cols - 1] = matrix[rows - 1][0] = matrix[rows - 1][cols - 1] = CORNER;

        // Fill edges and interior
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (i == 0 || i == rows - 1 || j == 0 || j == cols - 1) {
                    if (matrix[i][j] != CORNER) {
                        matrix[i][j] = EDGE_NON_CORNER;
                    }
                } else {
                    matrix[i][j] = INTERIOR;
                }
            }
        }
        return matrix;
    }

    /** Checks whether the input matrix respects the constructed result matrix. */
    private static boolean isValid(int[][] input, int[][] result, int rows, int cols) {
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (input[i][j] > result[i][j]) {
                    return false;
                }
            }
        }
        return true;
    }

    /** Prints a matrix to the supplied PrintWriter. */
    private static void printMatrix(int[][] matrix, PrintWriter out) {
        for (int i = 0; i < matrix.length; i++) {
            for (int j = 0; j < matrix[i].length; j++) {
                if (j != 0) {
                    out.print(' ');
                }
                out.print(matrix[i][j]);
            }
            out.println();
        }
    }
}

import java.util.Scanner;

/**
 * Utility class that validates and transforms a grid according to the
 * neighbor‑count rule described in the original program.
 */
public final class NeighborGridValidator {

    private NeighborGridValidator() {
        // Prevent instantiation of this utility class.
    }

    /**
     * Validates the given grid. If the grid is valid, the method returns a
     * new grid where each cell contains the number of its existing neighbours.
     * If the grid is invalid, {@code null} is returned.
     *
     * @param rows    number of rows
     * @param columns number of columns
     * @param values  initial cell values
     * @return transformed grid if validation succeeds, otherwise {@code null}
     */
    public static int[][] validateAndTransform(int rows, int columns, int[][] values) {
        int[][] transformed = new int[rows][columns];
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < columns; j++) {
                int neighbourCount = calculateNeighbourCount(values, i, j, rows, columns);
                if (neighbourCount < values[i][j]) {
                    // Validation fails – early exit
                    return null;
                }
                transformed[i][j] = neighbourCount;
            }
        }
        return transformed;
    }

    /**
     * Calculates how many orthogonal neighbours a cell at (row, col) has.
     *
     * @param grid    the source grid (not modified)
     * @param row     row index
     * @param col     column index
     * @param rows    total rows
     * @param columns total columns
     * @return number of existing orthogonal neighbours (0‑4)
     */
    private static int calculateNeighbourCount(int[][] grid, int row, int col,
                                               int rows, int columns) {
        int count = 0;
        if (row > 0) {
            count++;
        }
        if (row < rows - 1) {
            count++;
        }
        if (col > 0) {
            count++;
        }
        if (col < columns - 1) {
            count++;
        }
        return count;
    }
}

/**
 * Main class containing the entry point. It handles input parsing and output.
 */
public final class Main {

    private Main() {
        // Prevent instantiation of this class.
    }

    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            int testCases = scanner.nextInt();
            while (testCases-- > 0) {
                int rows = scanner.nextInt();
                int columns = scanner.nextInt();
                int[][] grid = readGrid(scanner, rows, columns);
                int[][] transformed = NeighborGridValidator.validateAndTransform(
                        rows, columns, grid);
                if (transformed == null) {
                    System.out.println("NO");
                } else {
                    System.out.println("YES");
                    printGrid(transformed);
                }
            }
        }
    }

    private static int[][] readGrid(Scanner scanner, int rows, int columns) {
        int[][] grid = new int[rows][columns];
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < columns; j++) {
                grid[i][j] = scanner.nextInt();
            }
        }
        return grid;
    }

    private static void printGrid(int[][] grid) {
        StringBuilder output = new StringBuilder();
        for (int i = 0; i < grid.length; i++) {
            for (int j = 0; j < grid[i].length; j++) {
                output.append(grid[i][j]);
                if (j < grid[i].length - 1) {
                    output.append(' ');
                }
            }
            if (i < grid.length - 1) {
                output.append('\n');
            }
        }
        System.out.println(output);
    }
}

