/**
 * Refactored solution that determines whether a given grid respects the
 * "neighbor count" constraint and, if possible, outputs the grid where each
 * cell contains the number of orthogonal neighbours it has.
 *
 * <p>Changes made for maintainability:
 * <ul>
 *   <li>Renamed ambiguous identifiers (e.g., {@code sc} → {@code scanner},
 *       {@code pw} → {@code out})</li>
 *   <li>Extracted neighbor‑count logic into its own method</li>
 *   <li>Removed unused classes, methods, and fields</li>
 *   <li>Simplified input handling with a lightweight {@code FastScanner}</li>
 *   <li>Improved method cohesion – each method now has a single, clear purpose</li>
 *   <li>Added brief Javadoc comments for clarity</li>
 * </ul>
 *
 * <p>The algorithm:
 * <ol>
 *   <li>Read the grid dimensions and values.</li>
 *   <li>For each cell verify that its value does not exceed the number of
 *       orthogonal neighbours it can have. If it does, print {@code NO} and
 *       abort.</li>
 *   <li>Otherwise replace every cell with its neighbour count and print
 *       {@code YES} followed by the transformed grid.</li>
 * </ol>
 */
public class Main {

    /** PrintWriter used for output (auto‑flush configured). */
    private static PrintWriter out;

    /** Fast scanner that reads tokens from standard input. */
    private static FastScanner scanner;

    public static void main(String[] args) throws IOException {
        out = new PrintWriter(System.out, true);   // auto‑flush
        scanner = new FastScanner(System.in);

        int testCases = scanner.nextInt();
        while (testCases-- > 0) {
            solve();
        }
        out.flush();   // explicit flush for safety
    }

    /**
     * Handles a single test case:
     * <ol>
     *   <li>Reads the matrix.</li>
     *   <li>Validates the neighbour‑count constraint.</li>
     *   <li>Prints the result.</li>
     * </ol>
     */
    private static void solve() {
        int rows = scanner.nextInt();
        int cols = scanner.nextInt();

        int[][] grid = new int[rows][cols];
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                grid[i][j] = scanner.nextInt();
            }
        }

        // Compute neighbour counts and validate the constraint.
        int[][] neighbourCounts = new int[rows][cols];
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                int cnt = orthogonalNeighbourCount(rows, cols, i, j);
                if (grid[i][j] > cnt) {
                    out.println("NO");
                    return;
                }
                neighbourCounts[i][j] = cnt;
            }
        }

        // Output the affirmative answer and the transformed grid.
        out.println("YES");
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                out.print(neighbourCounts[i][j]);
                if (j + 1 < cols) {
                    out.print(' ');
                }
            }
            out.println();
        }
    }

    /**
     * Returns the number of orthogonal neighbours (up, down, left, right)
     * a cell at position {@code (i, j)} has inside a {@code rows × cols}
     * grid.
     */
    private static int orthogonalNeighbourCount(int rows, int cols, int i, int j) {
        int count = 0;
        if (i > 0) count++;          // up
        if (j > 0) count++;          // left
        if (i + 1 < rows) count++;   // down
        if (j + 1 < cols) count++;   // right
        return count;
    }

    /**
     * Minimal scanner that tokenises the input stream.
     * Only the operations required by this solution are implemented.
     */
    private static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner(InputStream stream) {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        /** Returns the next token, expanding the current line if necessary. */
        private String next() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                st = new StringTokenizer(br.readLine());
            }
            return st.nextToken();
        }

        /** Reads the next integer token from the input. */
        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }
}

import java.util.Scanner;

/**
 * Refactored version of the original program.
 * Improves readability, separates concerns, and removes magic numbers.
 */
public class Main {

    /** Maximum allowed value for corner cells. */
    private static final int CORNER_LIMIT = 2;
    /** Maximum allowed value for edge (non‑corner) cells. */
    private static final int EDGE_LIMIT = 3;
    /** Maximum allowed value for interior cells. */
    private static final int INTERIOR_LIMIT = 4;

    public static void main(String[] args) {
        // Try‑with‑resources ensures the scanner is closed automatically.
        try (Scanner sc = new Scanner(System.in)) {
            int testCases = sc.nextInt();
            while (testCases-- > 0) {
                int rows = sc.nextInt();
                int cols = sc.nextInt();
                int[][] matrix = readMatrix(sc, rows, cols);

                if (hasViolation(matrix)) {
                    System.out.println("NO");
                } else {
                    System.out.println("YES");
                    printPattern(rows, cols);
                }
            }
        }
    }

    /**
     * Reads a matrix of the given dimensions from the scanner.
     */
    private static int[][] readMatrix(Scanner sc, int rows, int cols) {
        int[][] matrix = new int[rows][cols];
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                matrix[i][j] = sc.nextInt();
            }
        }
        return matrix;
    }

    /**
     * Determines whether any cell violates the limits defined by its position.
     *
     * @return {@code true} if a violation is found, otherwise {@code false}.
     */
    private static boolean hasViolation(int[][] matrix) {
        int rows = matrix.length;
        int cols = matrix[0].length;

        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                int value = matrix[i][j];
                if (isCorner(i, j, rows, cols)) {
                    if (value > CORNER_LIMIT) {
                        return true;
                    }
                } else if (isEdge(i, j, rows, cols)) {
                    if (value > EDGE_LIMIT) {
                        return true;
                    }
                } else {
                    if (value > INTERIOR_LIMIT) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    /** Checks whether the cell occupies one of the four corners. */
    private static boolean isCorner(int i, int j, int rows, int cols) {
        return (i == 0 && j == 0) ||
               (i == rows - 1 && j == 0) ||
               (i == 0 && j == cols - 1) ||
               (i == rows - 1 && j == cols - 1);
    }

    /** Checks whether the cell lies on the border but is not a corner. */
    private static boolean isEdge(int i, int j, int rows, int cols) {
        return i == 0 || i == rows - 1 || j == 0 || j == cols - 1;
    }

    /**
     * Prints the pattern of limits (2 for corners, 3 for edges, 4 for interior)
     * using the dimensions supplied.
     */
    private static void printPattern(int rows, int cols) {
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                int value = switchPosition(i, j, rows, cols);
                System.out.print(value);
                if (j < cols - 1) {
                    System.out.print(' ');
                }
            }
            System.out.println();
        }
    }

    /** Returns the appropriate limit value for a given position. */
    private static int switchPosition(int i, int j, int rows, int cols) {
        if (isCorner(i, j, rows, cols)) {
            return CORNER_LIMIT;
        }
        if (isEdge(i, j, rows, cols)) {
            return EDGE_LIMIT;
        }
        return INTERIOR_LIMIT;
    }
}

import java.io.*;
import java.util.StringTokenizer;

/**
 * Main entry point for the solution.
 * The program reads several test cases, validates each grid and either
 * prints "NO" or "YES" followed by the neighbour‑count matrix.
 */
public class Main {

    public static void main(String[] args) throws IOException {
        /* Try‑with‑resources ensures that the PrintWriter is closed automatically. */
        try (PrintWriter out = new PrintWriter(System.out)) {
            Solver solver = new Solver(out);
            int t = solver.nextInt();                 // number of test cases
            for (int tc = 1; tc <= t; tc++) {
                solver.solve(tc, new FastScanner(System.in), out);
            }
        }
    }

    /**
     * Handles the logic for a single test case.
     */
    static class Solver {
        private final PrintWriter out;
        private final FastScanner scanner;

        Solver(PrintWriter out) {
            this.out = out;
            this.scanner = new FastScanner(System.in);
        }

        /**
         * Solve one test case.
         *
         * @param testNumber 1‑based index of the test case (used only for readability)
         * @param in         input source
         * @param out        output destination
         */
        void solve(int testNumber, FastScanner in, PrintWriter out) {
            int n = in.nextInt();                     // rows
            int m = in.nextInt();                     // columns

            int[][] grid = new int[n][m];
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    grid[i][j] = in.nextInt();
                }
            }

            boolean possible = true;
            int[][] neighbourCount = new int[n][m];

            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    int cnt = neighbourCount(i, j, n, m);
                    if (grid[i][j] > cnt) {
                        possible = false;           // the cell value is too large
                    }
                    neighbourCount[i][j] = cnt;      // store for output if possible
                }
            }

            if (!possible) {
                out.println("NO");
                return;
            }

            out.println("YES");
            printNeighbourMatrix(neighbourCount, out);
        }

        /** Returns how many orthogonal neighbours cell (i,j) has inside an n×m grid. */
        private static int neighbourCount(int i, int j, int n, int m) {
            int count = 0;
            if (i > 0) count++;                      // up
            if (j > 0) count++;                      // left
            if (i + 1 < n) count++;                  // down
            if (j + 1 < m) count++;                  // right
            return count;
        }

        /** Prints the neighbour‑count matrix row by row. */
        private static void printNeighbourMatrix(int[][] matrix, PrintWriter out) {
            for (int[] row : matrix) {
                StringBuilder line = new StringBuilder();
                for (int v : row) {
                    line.append(v).append(' ');
                }
                out.println(line.toString().trim());
            }
        }
    }

    /**
     * Lightweight scanner that tokenises the input stream using {@link StringTokenizer}.
     * It provides the methods needed for the problem (next, nextInt, nextLong).
     */
    static class FastScanner {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        FastScanner(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
        }

        /** Returns the next token from the input, blocking until one is available. */
        String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new UncheckedIOException(e);
                }
            }
            return tokenizer.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        long nextLong() {
            return Long.parseLong(next());
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Refactored solution for the problem.
 *
 * <p>Changes:
 * <ul>
 *   <li>Renamed the class to a more meaningful name {@code Main}.</li>
 *   <li>Extracted magic numbers into clear constants.</li>
 *   <li>Separated boundary checking and neighbor counting into dedicated methods.</li>
 *   <li>Improved variable naming and reduced duplication.</li>
 *   <li>Used a {@code StringBuilder} to build the output before printing, which reduces I/O overhead.</li>
 *   <li>Made helper methods {@code static} where possible to clarify they do not rely on instance state.</li>
 *   <li>Added brief comments for readability.</li>
 * </ul>
 */
public class Main {

    /** Row offset of the four possible neighbour directions. */
    private static final int[] DR = { -1, 1, 0, 0 };
    /** Column offset of the four possible neighbour directions. */
    private static final int[] DC = { 0, 0, -1, 1 };

    private final FastScanner scanner;
    private final PrintWriter out;

    /** Entry point. */
    public static void main(String[] args) throws Exception {
        new Main().run();
    }

    /** Constructor – prepares scanners and output streams. */
    public Main() {
        scanner = new FastScanner();
        out = new PrintWriter(System.out);
    }

    /** Executes the test case loop. */
    public void run() throws Exception {
        int testCount = scanner.nextInt();
        while (testCount-- > 0) {
            solve();
        }
        out.close();
    }

    /**
     * Solves a single test case.
     *
     * <p>Reads the grid dimensions and values, validates the condition
     * {@code neighboursCount ≥ value}, replaces each value with its neighbour
     * count if valid, otherwise prints {@code NO} and returns.</p>
     */
    private void solve() {
        int rows = scanner.nextInt();
        int cols = scanner.nextInt();

        int[][] grid = new int[rows][cols];
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                grid[i][j] = scanner.nextInt();
            }
        }

        // Validate the whole grid before producing any output.
        StringBuilder outLines = new StringBuilder();
        boolean allValid = true;

        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                int neighbourCount = countNeighbors(i, j, rows, cols);
                if (neighbourCount >= grid[i][j]) {
                    grid[i][j] = neighbourCount; // replace with neighbour count
                } else {
                    allValid = false;
                    break;
                }
            }
            if (!allValid) {
                break;
            }
        }

        if (!allValid) {
            out.println("NO");
            return;
        }

        out.println("YES");
        for (int[] row : grid) {
            for (int value : row) {
                out.print(value);
                out.print(' ');
            }
            out.println();
        }
    }

    /**
     * Returns how many orthogonal neighbours of {@code (x, y)} lie inside the
     * {@code rows × cols} grid.
     */
    private static int countNeighbors(int x, int y, int rows, int cols) {
        int count = 0;
        for (int dir = 0; dir < 4; dir++) {
            int nx = x + DR[dir];
            int ny = y + DC[dir];
            if (isInsideGrid(nx, ny, rows, cols)) {
                count++;
            }
        }
        return count;
    }

    /** Checks whether a cell coordinate is within the grid boundaries. */
    private static boolean isInsideGrid(int x, int y, int rows, int cols) {
        return x >= 0 && x < rows && y >= 0 && y < cols;
    }

    /** Fast scanner wrapper around {@link BufferedReader} / {@link StringTokenizer}. */
    private static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner() {
            this(null);
        }

        FastScanner(String filePath) throws IOException {
            br = (filePath == null)
                    ? new BufferedReader(new InputStreamReader(System.in))
                    : new BufferedReader(new FileReader(filePath));
        }

        /** Reads next token, expanding the tokenizer if necessary. */
        String next() throws IOException {
            while (st == null || !st.hasMoreElements()) {
                String line = br.readLine();
                if (line == null) {
                    return null;
                }
                st = new StringTokenizer(line);
            }
            return st.nextToken();
        }

        /** Reads the next line (useful for debugging). */
        String nextLine() throws IOException {
            return br.readLine();
        }

        /** Convenience methods for primitive types. */
        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }

    /* --------------------------------------------------------------------- */
    /*  The following printing helpers mimic the original style but are now  */
    /*  thin wrappers around the shared {@code PrintWriter}.                  */
    /* --------------------------------------------------------------------- */
    private void print(Object o) {
        out.print(o);
    }

    private void println(Object o) {
        out.println(o);
    }

    /** Prints a newline without any argument. */
    private void println() {
        out.println();
    }

    /** Debug helper – prints to console, keeping the original name. */
    private void spn(Object o) {
        System.out.println(o);
    }
}

import java.io.*;
import java.util.*;

/**
 * Refactored solution for the “grid‑value” problem.
 *
 * <p>
 *   The original implementation mixed I/O, business logic and mutable
 *   static state, making it hard to read and maintain.  The refactored
 *   version:
 *   <ul>
 *     <li>Encapsulates all I/O in a small {@link FastScanner} class.</li>
 *     <li>Keeps mutable state local to {@code solve}</li>
 *     <li>Splits the algorithm into well‑named private methods.</li>
 *     <li>Uses {@link try‑with‑resources} to guarantee proper stream closing.</li>
 *     <li>Adds javadoc comments and meaningful identifiers.</li>
 *   </ul>
 * </p>
 */
public class Main {

    /** Small wrapper around {@link BufferedReader} that tokenises input. */
    private static final class FastScanner implements Closeable {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner(InputStream in) {
            this.br = new BufferedReader(new InputStreamReader(in));
        }

        /** Retrieves the next available token, waiting for more lines if necessary. */
        String next() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                st = new StringTokenizer(br.readLine());
            }
            return st.nextToken();
        }

        /** Convenience method for reading a whole int[] of length {@code n}. */
        int[] nextIntArray(int n) throws IOException {
            int[] arr = new int[n];
            for (int i = 0; i < n; i++) {
                arr[i] = nextInt();
            }
            return arr;
        }

        /** Reads a single {@code int}. */
        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }

        /** Closes the underlying {@link BufferedReader}. */
        @Override
        public void close() throws IOException {
            br.close();
        }
    }

    /** Holds all logic required to process a single test case. */
    private static void solve(FastScanner sc, PrintWriter out) throws IOException {
        int tests = sc.nextInt();

        while (tests-- > 0) {
            int rows = sc.nextInt();
            int cols = sc.nextInt();

            int[][] grid = new int[rows][cols];
            for (int r = 0; r < rows; r++) {
                grid[r] = sc.nextIntArray(cols);
            }

            if (!applyMaximumConstraints(grid)) {
                out.println("NO");
                continue;
            }

            out.println("YES");
            for (int[] row : grid) {
                for (int val : row) {
                    out.print(val);
                    out.print(' ');
                }
                out.println();
            }
        }
    }

    /**
     * Checks whether the grid obeys the problem's maximum‑value constraints.
     * While checking it also clamps each cell to its allowed maximum.
     *
     * @return {@code true} if the grid satisfies all constraints, {@code false}
     *         otherwise.  In the latter case the caller should print "NO".
     */
    private static boolean applyMaximumConstraints(int[][] grid) {
        int rows = grid.length;
        int cols = grid[0].length;

        // ----- 1. Interior cells (strictly surrounded) -----
        // Maximum allowed value inside the grid is 4.
        for (int r = 1; r < rows - 1; r++) {
            for (int c = 1; c < cols - 1; c++) {
                if (grid[r][c] > 4) {
                    return false;
                }
                grid[r][c] = 4;               // clamp to maximal permitted value
            }
        }

        // ----- 2. Corner cells -----
        // Corners may hold at most 2.
        int[][] corners = {
                {0, 0},
                {rows - 1, cols - 1},
                {rows - 1, 0},
                {0, cols - 1}
        };
        for (int[] idx : corners) {
            int r = idx[0];
            int c = idx[1];
            if (grid[r][c] > 2) {
                return false;
            }
            grid[r][c] = 2;
        }

        // ----- 3. Edge cells (excluding corners) -----
        // Edge cells may hold at most 3.
        // Top & bottom edges
        for (int c = 1; c < cols - 1; c++) {
            enforceMax(grid, 0, c, 3);
            enforceMax(grid, rows - 1, c, 3);
        }
        // Left & right edges
        for (int r = 1; r < rows - 1; r++) {
            enforceMax(grid, r, 0, 3);
            enforceMax(grid, r, cols - 1, 3);
        }

        return true;
    }

    /**
     * Sets the cell {@code (r,c)} to {@code maxAllowed} if its current value
     * does not exceed that limit; otherwise returns {@code false} to signal a
     * constraint violation.
     */
    private static boolean enforceMax(int[][] grid, int r, int c, int maxAllowed) {
        if (grid[r][c] > maxAllowed) {
            return false;
        }
        grid[r][c] = maxAllowed;
        return true;
    }

    /** Entry point – uses try‑with‑resources for safe closure of streams. */
    public static void main(String[] args) throws IOException {
        try (FastScanner scanner = new FastScanner(System.in);
             PrintWriter out = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)))) {
            solve(scanner, out);
        }
    }
}

import java.io.PrintWriter;
import java.util.Scanner;

/**
 * Entry point of the application.
 */
public class Main {

    public static void main(String[] args) {
        // Using try‑with‑resources guarantees that resources are closed cleanly.
        try (Scanner scanner = new Scanner(System.in);
             PrintWriter out = new PrintWriter(System.out)) {

            int testCases = scanner.nextInt();
            MatrixProcessor processor = new MatrixProcessor();

            for (int t = 0; t < testCases; t++) {
                processor.process(scanner, out);
            }
        }
    }
