/**
 * Handles everything related to reading the matrix, validating it and,
 * when possible, rewriting it according to the original specification.
 *
 * <p>All exceptions that stem from an invalid input are translated into
 * {@link IllegalArgumentException} so that the caller only has to deal with a
 * single, well‑defined failure mode.</p>
 */
final class MatrixProcessor {

    /** Minimum allowed value – kept here for easy tuning. */
    private static final int MIN_VAL = 1;

    /** First "step‑size" used by the original algorithm. */
    private static final int STEP_BOUNDARY = 2;

    /** Second "step‑size" used by the original algorithm. */
    private static final int STEP_INNER = 1;

    /**
     * Reads one test case from the supplied {@link Scanner}, validates the
     * matrix and, if it passes, prints "YES" followed by the transformed matrix.
     * Otherwise prints "NO".
     */
    void process(Scanner scanner, PrintWriter out) {
        int rows = scanner.nextInt();
        int cols = scanner.nextInt();
        int[][] matrix = readMatrix(scanner, rows, cols);

        Result result = validateAndTransform(matrix, rows, cols);
        if (result.isSuccess()) {
            out.println("YES");
            printMatrix(result.matrix(), out);
        } else {
            out.println("NO");
        }
    }

    /** Parses the matrix from the scanner according to the declared dimensions. */
    private static int[][] readMatrix(Scanner scanner, int rows, int cols) {
        int[][] matrix = new int[rows][cols];
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                matrix[i][j] = scanner.nextInt();
            }
        }
        return matrix;
    }

    /**
     * Executes the transformation described in the original code and returns
     * either the transformed matrix wrapped in a {@link Result} or a failure
     * indicator.
     *
     * @throws IllegalArgumentException if any of the constraints are violated
     */
    private Result validateAndTransform(int[][] matrix, int rows, int cols) {
        try {
            // Process the first and last rows using the boundary step.
            processRow(matrix[0], cols, STEP_BOUNDARY);
            processRow(matrix[rows - 1], cols, STEP_BOUNDARY);

            // Process all interior rows using the inner step.
            for (int r = 1; r < rows - 1; r++) {
                processRow(matrix[r], cols, STEP_INNER);
            }
            return new Result(true, matrix);
        } catch (IllegalArgumentException e) {
            // The original code caught a generic Exception – we convert it to a
            // more specific, domain‑specific exception for clearer intent.
            return new Result(false, null);
        }
    }

    /** Performs a single row transformation according to the original logic. */
    private void processRow(int[] row, int cols, int startNumber) {
        // The first column must not exceed the step value.
        if (row[0] > startNumber) {
            throw new IllegalArgumentException("First column value exceeds allowed bound");
        }
        row[0] = startNumber;

        // The last column follows the same rule.
        if (row[cols - 1] > startNumber) {
            throw new IllegalArgumentException("Last column value exceeds allowed bound");
        }
        row[cols - 1] = startNumber;

        // All inner elements must be exactly one more than the step value.
        for (int c = 1; c < cols - 1; c++) {
            if (row[c] > startNumber + 1) {
                throw new IllegalArgumentException("Inner column value violates required range");
            }
            row[c] = startNumber + 1;
        }
    }

    /** Utility to pretty‑print a matrix using a space as separator. */
    private void printMatrix(int[][] matrix, PrintWriter out) {
        for (int[] row : matrix) {
            for (int j = 0; j < matrix[0].length; j++) {
                out.print(row[j]);
                if (j < matrix[0].length - 1) {
                    out.print(' ');
                }
            }
            out.println();
        }
    }

    /** Simple immutable holder that indicates success or failure of processing. */
    private static final class Result {
        private final boolean success;
        private final int[][] matrix;

        Result(boolean success, int[][] matrix) {
            this.success = success;
            this.matrix = matrix;
        }

        boolean isSuccess() {
            return success;
        }

        int[][] matrix() {
            return matrix;
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

/**
 * Main class that processes multiple test cases.
 * For each test case it reads a matrix and verifies that every element
 * does not exceed the number of its adjacent cells (up, down, left, right).
 * If the condition holds, the matrix is transformed so that each cell
 * contains exactly its neighbor count; otherwise "NO" is printed.
 */
public class Main {

    private static final class FastScanner {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        FastScanner() {
            reader = new BufferedReader(new InputStreamReader(System.in), 32768);
            tokenizer = null;
        }

        /** Returns the next token from standard input. */
        private String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        /** Reads an {@code int} from input. */
        int nextInt() {
            return Integer.parseInt(next());
        }
    }

    /** Number of directions (up, down, left, right). */
    private static final int DIRECTION_COUNT = 4;

    public static void main(String[] args) throws IOException {
        FastScanner scanner = new FastScanner();
        int t = scanner.nextInt();

        while (t-- > 0) {
            solveOneTestCase(scanner);
        }
    }

    /**
     * Handles a single test case: reads the matrix, validates it,
     * possibly transforms it, and prints the result.
     */
    private static void solveOneTestCase(FastScanner scanner) throws IOException {
        int n = scanner.nextInt();          // number of rows
        int m = scanner.nextInt();          // number of columns

        int[][] matrix = readMatrix(scanner, n, m);

        if (!isMatrixValid(matrix, n, m)) {
            System.out.println("NO");
            return;
        }

        System.out.println("YES");
        transformMatrix(matrix, n, m);
        printMatrix(matrix);
    }

    /**
     * Reads an {@code n × m} matrix from the scanner.
     */
    private static int[][] readMatrix(FastScanner scanner, int n, int m) {
        int[][] matrix = new int[n][m];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                matrix[i][j] = scanner.nextInt();
            }
        }
        return matrix;
    }

    /**
     * Determines whether every cell value is not larger than the number of
     * its orthogonal neighbours.
     */
    private static boolean isMatrixValid(int[][] matrix, int n, int m) {
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (!isCellPossible(matrix[i][j], i, j, n, m)) {
                    return false;
                }
            }
        }
        return true;
    }

    /**
     * Checks if a single cell value satisfies the neighbour‑count condition.
     */
    private static boolean isCellPossible(int value, int i, int j, int n, int m) {
        int neighbourCount = countNeighbourhoodSize(i, j, n, m);
        return value <= neighbourCount;
    }

    /**
     * Returns how many orthogonal neighbours a cell at (i,j) has.
     */
    private static int countNeighbourhoodSize(int i, int j, int n, int m) {
        int count = 0;
        if (i > 0) count++;          // up
        if (j > 0) count++;          // left
        if (i < n - 1) count++;      // down
        if (j < m - 1) count++;      // right
        return count;
    }

    /**
     * Transforms each cell to the number of its orthogonal neighbours.
     */
    private static void transformMatrix(int[][] matrix, int n, int m) {
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                matrix[i][j] = countNeighbourhoodSize(i, j, n, m);
            }
        }
    }

    /** Prints the matrix to standard output. */
    private static void printMatrix(int[][] matrix) {
        for (int[] row : matrix) {
            StringBuilder sb = new StringBuilder();
            for (int value : row) {
                sb.append(value).append(' ');
            }
            System.out.println(sb.toString().trim());
        }
    }
}

import java.io.BufferedReader;
import java.io.BufferedWriter;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.OutputStreamWriter;
import java.io.PrintWriter;
import java.io.StreamTokenizer;

/**
 * Refactored solution for the “border‑cell value” problem.
 *
 * <p>Key improvements:
 *
 * <ul>
 *   <li>Clear separation between I/O, validation and transformation logic.
 *   <li>Descriptive naming and constants instead of magic numbers.
 *   <li>Straight‑forward token parsing using {@link StreamTokenizer}.
 *   <li>Methods are short and focused, making unit‑testing easier.
 *   <li>Resources are closed with try‑with‑resources to guarantee proper cleanup.
 * </ul>
 */
public class Main {

    /** Maximum allowed value for any corner cell. */
    private static final int CORNER_MAX = 2;
    /** Maximum allowed value for any non‑corner border cell. */
    private static final int EDGE_MAX = 3;
    /** Maximum allowed value for any interior cell. */
    private static final int INTERIOR_MAX = 4;

    /** Simple wrapper around the input parsing utilities. */
    private static final class Solver {

        private final StreamTokenizer st;
        private final PrintWriter out;

        Solver(StreamTokenizer st, PrintWriter out) {
            this.st = st;
            this.out = out;
        }

        /** Executes one test case. */
        void solveCase() throws IOException {
            int n = nextInt();
            int m = nextInt();
            int[][] grid = new int[n][m];
            readMatrix(grid, n, m);

            if (!isValidAndNormalize(grid)) {
                out.println("NO");
                return;
            }

            out.println("YES");
            writeMatrix(grid);
        }

        /** Reads an n×m integer matrix from the tokenizer. */
        private void readMatrix(int[][] dst, int n, int m) throws IOException {
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    dst[i][j] = nextInt();
                }
            }
        }

        /** Validates the matrix respecting the required caps and writes those caps back. */
        private boolean isValidAndNormalize(int[][] grid) {
            int rows = grid.length;
            int cols = grid[0].length;

            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (isCorner(i, rows, j, cols)) {
                        if (grid[i][j] > CORNER_MAX) return false;
                        grid[i][j] = CORNER_MAX;
                    } else if (isBorder(i, rows, j, cols)) {
                        if (grid[i][j] > EDGE_MAX) return false;
                        grid[i][j] = EDGE_MAX;
                    } else {
                        if (grid[i][j] > INTERIOR_MAX) return false;
                        grid[i][j] = INTERIOR_MAX;
                    }
                }
            }
            return true;
        }

        private boolean isCorner(int i, int rows, int j, int cols) {
            return (i == 0 && j == 0) ||
                   (i == rows - 1 && j == cols - 1) ||
                   (i == 0 && j == cols - 1) ||
                   (i == rows - 1 && j == 0);
        }

        private boolean isBorder(int i, int rows, int j, int cols) {
            return i == 0 || i == rows - 1 || j == 0 || j == cols - 1;
        }

        /** Returns the next non‑whitespace token as an integer. */
        private int nextInt() throws IOException {
            return Integer.parseInt(st.nextToken());
        }

        /** Writes the whole matrix to the output writer. */
        private void writeMatrix(int[][] matrix) {
            int n = matrix.length;
            int m = matrix[0].length;
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    out.print(matrix[i][j]);
                    if (j + 1 < m) out.print(' ');
                }
                out.println();
            }
        }
    }

    /** Entry point of the program. */
    public static void main(String[] args) throws Exception {
        // StreamTokenizer handles tokenisation without the need for manual byte handling.
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
             BufferedWriter bw = new BufferedWriter(new OutputStreamWriter(System.out));
             PrintWriter out = new PrintWriter(bw);
             StreamTokenizer st = new StreamTokenizer(new BufferedReader(new InputStreamReader(System.in))) {

            new Solver(st, out).solveCase();   // process all test cases automatically
        }
    }
}

import java.io.PrintWriter;
import java.io.InputStream;
import java.util.ArrayList;
import java.util.List;

/**
 * Main entry point for the B‑Neighbor‑Grid problem.
 *
 * <p>This version focuses on readability, modularisation and proper resource handling.
 * The algorithm itself is unchanged.</p>
 */
public class Main {

    /** Directions used to inspect neighbours (up, down, left, right). */
    private static final int[][] DIRS = {
            {1, 0}, {-1, 0}, {0, 1}, {0, -1}
    };

    /**
     * Entry point of the program.
     *
     * @param args command line arguments (unused)
     */
    public static void main(String[] args) {
        try (InputStream inStream = System.in;
             PrintWriter outStream = new PrintWriter(System.out)) {

            FastScanner scanner = new FastScanner(inStream);
            Solver solver = new Solver();

            // According to the original code the first value tells how many test cases
            // will follow.  We read it and delegate the actual solving to the solver.
            int testCaseCount = scanner.nextInt();
            solver.solve(testCaseCount, scanner, outStream);
        }
    }

    /**
     * Core solver for the problem.
     *
     * <p>It processes {@code testCaseCount} independent test cases,
     * writes “YES”/“NO” for each and – when possible – the resulting grid.</p>
     *
     * @param testCaseCount number of test cases to process
     * @param scanner       input source wrapped in a {@link FastScanner}
     * @param out           output destination {@link PrintWriter}
     */
    static class Solver {

        /** @param testCaseCount see {@link #solve(int, FastScanner, PrintWriter)} */
        void solve(int testCaseCount, FastScanner scanner, PrintWriter out) {
            for (int t = 0; t < testCaseCount; t++) {
                solveSingleCase(scanner, out);
            }
        }

        /**
         * Handles one test case.
         *
         * @param scanner input source
         * @param out     output destination
         */
        private void solveSingleCase(FastScanner scanner, PrintWriter out) {
            int n = scanner.nextInt();
            int m = scanner.nextInt();

            int[][] grid = readGrid(scanner, n, m);

            // Count neighbours for each cell and validate the constraints.
            boolean impossible = false;
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    int neighborCount = countValidNeighbours(grid, i, j, n, m);
                    if (grid[i][j] > neighborCount) {
                        out.println("NO");
                        impossible = true;
                        break;
                    }
                    grid[i][j] = neighborCount;
                }
                if (impossible) {
                    break;
                }
            }

            // If we haven't printed “NO” yet, the grid can be output.
            if (!impossible) {
                out.println("YES");
                printGrid(out, grid);
            }
        }

        /**
         * Reads an {@code n × m} integer grid from the scanner.
         *
         * @param scanner input source
         * @param n       number of rows
         * @param m       number of columns
         * @return the read grid as a 2‑D array
         */
        private static int[][] readGrid(FastScanner scanner, int n, int m) {
            int[][] result = new int[n][m];
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    result[i][j] = scanner.nextInt();
                }
            }
            return result;
        }

        /**
         * Counts how many of the four orthogonal neighbours of cell (i, j) lie inside the grid.
         *
         * @param grid      the current grid (used only for dimensions)
         * @param i         row index
         * @param j         column index
         * @param rows      total rows
         * @param cols      total columns
         * @return number of in‑bounds neighbours
         */
        private static int countValidNeighbours(int[][] grid, int i, int j, int rows, int cols) {
            int cnt = 0;
            for (int[] d : DIRS) {
                int ni = i + d[0];
                int nj = j + d[1];
                if (ni >= 0 && ni < rows && nj >= 0 && nj < cols) {
                    cnt++;
                }
            }
            return cnt;
        }

        /**
         * Prints the grid to the supplied output writer.
         *
         * @param out     output destination
         * @param grid    grid to print
         */
        private static void printGrid(PrintWriter out, int[][] grid) {
            StringBuilder sb = new StringBuilder();
            for (int[] row : grid) {
                for (int cell : row) {
                    sb.append(cell).append(' ');
                }
                sb.append('\n');
            }
            out.print(sb.toString());
        }
    }

    /**
     * Fast scanner that reads bytes from an {@link InputStream} and extracts primitive
     * values without the overhead of {@link java.util.Scanner}.  It mimics the behaviour
     * of the original {@code InputReader} implementation.
     */
    static class FastScanner {

        private final InputStream stream;
        private final byte[] buffer = new byte[1024];
        private int bytesRead = 0;
        private int currentByte;
        private int bufferIndex;
        private boolean hasNext;

        FastScanner(InputStream stream) {
            this.stream = stream;
        }

        private int readByte() {
            if (bufferIndex >= bytesRead) {
                bytesRead = stream.read(buffer);
                bufferIndex = 0;
                if (bytesRead <= 0) {
                    return -1;
                }
            }
            return buffer[bufferIndex++];
        }

        /** Skips whitespace characters. */
        private int skipWhitespace(int start) {
            int c;
            do {
                c = readByte();
            } while (!isSpaceChar(c) && c != -1);
            return c;
        }

        /** @return true if the character is a whitespace delimiter. */
        private static boolean isSpaceChar(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        /** Reads the next signed integer from the input. */
        int nextInt() {
            int c = skipWhitespace(readByte());

            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = readByte();
            }

            int value = 0;
            do {
                if (c < '0' || c > '9') {
                    throw new IllegalStateException("Invalid numeric character: " + (char) c);
                }
                value = value * 10 + (c - '0');
                c = readByte();
            } while (!isSpaceChar(c));

            return value * sign;
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

/**
 * Reads the input, validates each cell of a grid and optionally prints an updated
 * grid. The program implements the same logic as the original version but
 * with clearer naming, separated concerns and better overall maintainability.
 *
 * <p>The grid is valid when every cell's original value does not exceed the
 * number of orthogonal neighbours (up, down, left, right) that exist inside the
 * grid. If a cell is invalid the answer for the test case is {@code NO}; otherwise
 * the answer is {@code YES} and the updated grid – where each cell holds its
 * neighbour count – is printed.</p>
 */
public class NeighborGrid {

    /** Directions: right, up, left, down */
    private static final int[] DX = {0, -1, 0, 1};
    private static final int[] DY = {1, 0, -1, 0};

    public static void main(String[] args) {
        InputReader reader = new InputReader();
        StringBuilder output = new StringBuilder();

        int t = reader.nextInt();                       // number of test cases
        for (int testCase = 0; testCase < t; testCase++) {
            int rows = reader.nextInt();
            int cols = reader.nextInt();

            int[][] grid = readGrid(reader, rows, cols);
            boolean isValid = validateAndTransform(grid, rows, cols);

            if (!isValid) {
                output.append("NO\n");
            } else {
                output.append("YES\n");
                for (int i = 0; i < rows; i++) {
                    for (int j = 0; j < cols; j++) {
                        output.append(grid[i][j]).append(' ');
                    }
                    output.append('\n');
                }
            }
        }

        System.out.print(output);
    }

    /**
     * Reads the whole grid from the provided {@link InputReader}.
     */
    private static int[][] readGrid(InputReader reader, int rows, int cols) {
        int[][] grid = new int[rows][cols];
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                grid[i][j] = reader.nextInt();
            }
        }
        return grid;
    }

    /**
     * Validates the grid according to the problem rules.
     *
     * @return {@code true} if the grid is valid; {@code false} otherwise.
     *         When {@code true} the grid is mutated so that each cell contains
     *         the count of its orthogonal neighbours.
     */
    private static boolean validateAndTransform(int[][] grid, int rows, int cols) {
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                int neighbourCount = countExistingNeighbours(i, j, rows, cols);
                int originalValue = grid[i][j];

                if (originalValue > neighbourCount) {
                    return false;                     // cell cannot be satisfied
                }

                // Update the cell with its neighbour count for the final output
                grid[i][j] = neighbourCount;
            }
        }
        return true;
    }

    /**
     * Counts how many orthogonal neighbours of cell (x, y) lie inside the
     * {@code rows × cols} board.
     */
    private static int countExistingNeighbours(int x, int y, int rows, int cols) {
        int count = 0;
        for (int dir = 0; dir < DX.length; dir++) {
            int nx = x + DX[dir];
            int ny = y + DY[dir];

            if (nx >= 0 && nx < rows && ny >= 0 && ny < cols) {
                count++;
            }
        }
        return count;
    }

    /**
     * Simple fast scanner for competitive‑programming style input.
     */
    private static final class InputReader {
        private final BufferedReader br;
        private StringTokenizer st;

        InputReader() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        /** Returns next token as {@link String}. */
        private String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return st.nextToken();
        }

        /** Convenience method returning {@code int}. */
        int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.io.PrintWriter;
import java.util.Scanner;
import java.util.streamIntStream;

/**
 * Reads multiple grids, checks whether each cell satisfies a neighbourhood‑size
 * constraint and prints the result.  The logic is isolated in small, well‑named
 * methods to improve readability and testability.
 */
public class NeighborGrid {

    /** Messages used in the output. */
    private static final String YES = "YES";
    private static final String NO = "NO";

    /** Directions that represent the four orthogonal neighbours. */
    private enum Neighbor {
        UP, RIGHT, DOWN, LEFT;

        /** Number of orthogonal neighbours a cell has. */
        static int count(int row, int col, int rows, int cols) {
            int count = 0;
            if (row - 1 >= 0)               count++; // UP
            if (col + 1 < cols)             count++; // RIGHT
            if (row + 1 < rows)             count++; // DOWN
            if (col - 1 >= 0)               count++; // LEFT
            return count;
        }
    }

    /**
     * Reads a single integer matrix from {@link Scanner}.
     *
     * @param scanner a scanner positioned at the first grid dimension
     * @param rows    number of rows
     * @param cols    number of columns
     * @return the matrix read from the scanner
     */
    private static int[][] readMatrix(Scanner scanner, int rows, int cols) {
        int[][] matrix = new int[rows][cols];
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                matrix[r][c] = scanner.nextInt();
            }
        }
        return matrix;
    }

    /**
     * Checks the whole grid.  For each cell the method verifies that its value
     * does not exceed the number of orthogonal neighbours it possesses.
     * While checking, the cell's value is *replaced* by that neighbour count,
     * exactly like the original implementation.
     *
     * @param grid     mutable grid to validate
     * @param rows     number of rows
     * @param cols     number of columns
     * @return {@code true} if every cell satisfies the constraint,
     *         {@code false} otherwise
     */
    private static boolean validateGrid(int[][] grid, int rows, int cols) {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                int neighbourCount = Neighbor.count(r, c, rows, cols);
                if (grid[r][c] > neighbourCount) {
                    return false;                     // constraint violated
                }
                // Update the cell to the neighbour count (mirrors original behaviour)
                grid[r][c] = neighbourCount;
            }
        }
        return true; // all cells satisfied the constraint
    }

    /**
     * Formats a matrix as whitespace‑separated rows ending with a newline.
     *
     * @param grid matrix to format
     * @return the formatted string
     */
    private static String formatMatrix(int[][] grid) {
        StringBuilder sb = new StringBuilder();
        for (int r = 0; r < grid.length; r++) {
            for (int c = 0; c < grid[r].length; c++) {
                sb.append(grid[r][c]);
                if (c < grid[r].length - 1) {
                    sb.append(' ');
                }
            }
            sb.append('\n');
        }
        return sb.toString();
    }

    public static void main(String[] args) {
        // Use try‑with‑resources to guarantee streams are closed.
        try (Scanner in = new Scanner(System.in);
             PrintWriter out = new PrintWriter(System.out)) {

            int testCases = in.nextInt();
            for (int tc = 0; tc < testCases; tc++) {
                int rows = in.nextInt();
                int cols = in.nextInt();

                int[][] grid = readMatrix(in, rows, cols);

                boolean allValid = validateGrid(grid, rows, cols);

                if (!allValid) {
                    out.println(NO);
                } else {
                    out.println(YES);
                    out.print(formatMatrix(grid));
                }
            }
        }
    }
}

import java.io.*;
import java.util.*;

public class Practice {

    /** Fast input reader – single shared instance */
    private static final FastReader SC = new FastReader();

    /** Entry point */
    public static void main(String[] args) {
        int t = SC.nextInt();                 // number of test cases
        while (t-- > 0) {
            solveSingleTestCase();
        }
    }

    /** Handles one test case: reads, validates and prints the answer */
    private static void solveSingleTestCase() {
        int n = SC.nextInt();
        int m = SC.nextInt();
        int[][] input = readMatrix(n, m);

        if (!validate(input, n, m)) {
            System.out.println("NO");
            return;
        }

        System.out.println("YES");
        int[][] output = buildOutputMatrix(n, m);
        printMatrix(output);
    }

    /** Reads an n × m integer matrix from the FastReader */
    private static int[][] readMatrix(int rows, int cols) {
        int[][] matrix = new int[rows][cols];
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                matrix[r][c] = SC.nextInt();
            }
        }
        return matrix;
    }

    /** Checks the constraints on the supplied matrix */
    private static boolean validate(int[][] a, int n, int m) {
        final int CORNER_MAX = 2;
        final int EDGE_MAX   = 3;
        final int INTERIOR_MAX = 4;

        for (int r = 0; r < n; r++) {
            for (int c = 0; c < m; c++) {
                int value = a[r][c];
                boolean isCorner = (r == 0 && c == 0) ||
                                   (r == 0 && c == m - 1) ||
                                   (r == n - 1 && c == 0) ||
                                   (r == n - 1 && c == m - 1);
                boolean isEdge   = !isCorner && (r == 0 || r == n - 1 || c == 0 || c == m - 1);
                boolean isInterior = !isCorner && !isEdge;

                int limit = isCorner ? CORNER_MAX : (isEdge ? EDGE_MAX : INTERIOR_MAX);
                if (value > limit) {
                    return false;
                }
            }
        }
        return true;
    }

    /** Constructs the output matrix where every corner = 2, edge = 3, interior = 4 */
    private static int[][] buildOutputMatrix(int n, int m) {
        int[][] out = new int[n][m];
        final int CORNER_VAL = 2;
        final int EDGE_VAL   = 3;
        final int INTERIOR_VAL = 4;

        for (int r = 0; r < n; r++) {
            for (int c = 0; c < m; c++) {
                boolean isCorner = (r == 0 && c == 0) ||
                                   (r == 0 && c == m - 1) ||
                                   (r == n - 1 && c == 0) ||
                                   (r == n - 1 && c == m - 1);
                boolean isEdge   = !isCorner && (r == 0 || r == n - 1 || c == 0 || c == m - 1);
                boolean isInterior = !isCorner && !isEdge;

                out[r][c] = isCorner ? CORNER_VAL : (isEdge ? EDGE_VAL : INTERIOR_VAL);
            }
        }
        return out;
    }

    /** Pretty‑prints a matrix to stdout */
    private static void printMatrix(int[][] matrix) {
        for (int[] row : matrix) {
            StringBuilder sb = new StringBuilder();
            for (int v : row) {
                sb.append(v).append(' ');
            }
            System.out.println(sb.toString().trim());
        }
    }

    /* -------------------------------------------------
       Fast input utilities – no external dependencies
       ------------------------------------------------- */
    static class FastReader {
        private final BufferedReader br;
        private StringTokenizer st;

        FastReader() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        /** Returns next token, reading a new line if needed */
        String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    throw new UncheckedIOException(e);
                }
            }
            return st.nextToken();
        }

        int nextInt()          { return Integer.parseInt(next()); }
        long nextLong()        { return Long.parseLong(next()); }
        double nextDouble()    { return Double.parseDouble(next()); }
        String nextLine()      { try { return br.readLine(); } catch (IOException e) { throw new UncheckedIOException(e); } }
    }
}

import java.io.*;
import java.util.StringTokenizer;

/**
 * Solves a grid‑validation problem.
 * <p>
 * The algorithm checks whether a given {@code m × n} matrix can be turned
 * into a “header‑only” grid where border cells are limited to certain values.
 * If the validation succeeds the grid is printed with the header numbers
 * (2 for the four corners, 3 for the remaining border cells and 4 for inner
 * cells). Otherwise only “NO” is printed.
 *
 * The original code has been refactored to improve readability,
 * separation of concerns and testability.
 */
public class Main {

    /* --------------------------------------------------------------
     *  Fast input reader – encapsulates all token handling.
     * -------------------------------------------------------------- */
    private static final class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner(BufferedReader br) {
            this.br = br;
        }

        /** Pops the next token, reading a new line if necessary. */
        private void ensureTokenizer() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                st = new StringTokenizer(br.readLine());
            }
        }

        int nextInt() throws IOException { return Integer.parseInt(nextToken()); }
        float nextFloat() throws IOException { return Float.parseFloat(nextToken()); }
        long nextLong() throws IOException { return Long.parseLong(nextToken()); }

        /** Returns the next token without consuming it. */
        private String nextToken() throws IOException {
            ensureTokenizer();
            return st.nextToken();
        }

        /** Advances to the next line. */
        void nextLine() throws IOException { br.readLine(); }
    }

    /* --------------------------------------------------------------
     *  Validation logic – each check is a separate, named method.
     * -------------------------------------------------------------- */
    private static final class GridValidator {

        private static final int CORNER_VALUE = 2;
        private static final int EDGE_VALUE   = 3;
        private static final int INNER_VALUE  = 4;

        /**
         * Checks the four corner cells.
         */
        static boolean cornersAreValid(int[][] grid, int rows, int cols) {
            int[] corners = {
                    grid[0][0],
                    grid[rows - 1][cols - 1],
                    grid[0][cols - 1],
                    grid[rows - 1][0]
            };
            for (int v : corners) {
                if (v > CORNER_VALUE) {
                    return false;
                }
            }
            return true;
        }

        /**
         * Checks the remaining cells on the outer border (first/last row
         * and first/last column, excluding the corners).
         */
        static boolean bordersAreValid(int[][] grid, int rows, int cols) {
            // first and last row (excluding corners)
            for (int col = 1; col < cols - 1; col++) {
                if (grid[0][col] > EDGE_VALUE || grid[rows - 1][col] > EDGE_VALUE) {
                    return false;
                }
            }
            // first and last column (excluding corners)
            for (int row = 1; row < rows - 1; row++) {
                if (grid[row][0] > EDGE_VALUE || grid[row][cols - 1] > EDGE_VALUE) {
                    return false;
                }
            }
            return true;
        }

        /**
         * Checks interior cells (not on any border).
         */
        static boolean interiorAreValid(int[][] grid, int rows, int cols) {
            for (int row = 1; row < rows - 1; row++) {
                for (int col = 1; col < cols - 1; col++) {
                    if (grid[row][col] > INNER_VALUE) {
                        return false;
                    }
                }
            }
            return true;
        }

        /**
         * Returns {@code true} if the whole grid satisfies the constraints.
         */
        static boolean isValid(int[][] grid, int rows, int cols) {
            return cornersAreValid(grid, rows, cols)
                    && bordersAreValid(grid, rows, cols)
                    && interiorAreValid(grid, rows, cols);
        }
    }

    /* --------------------------------------------------------------
     *  Formatter – builds the output grid when validation succeeded.
     * -------------------------------------------------------------- */
    private static final class GridFormatter {

        private static final int CORNER_VALUE = 2;
        private static final int EDGE_VALUE   = 3;
        private static final int INNER_VALUE  = 4;

        static String buildOutput(int[][] grid, int rows, int cols) {
            StringBuilder sb = new StringBuilder();
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if ((i == 0 && j == 0) ||
                        (i == rows - 1 && j == cols - 1) ||
                        (i == 0 && j == cols - 1) ||
                        (i == rows - 1 && j == 0)) {
                        sb.append(CORNER_VALUE).append(' ');
                    } else if (i == 0 || j == 0 || i == rows - 1 || j == cols - 1) {
                        sb.append(EDGE_VALUE).append(' ');
                    } else {
                        sb.append(INNER_VALUE).append(' ');
                    }
                }
                sb.append('\n');
            }
            return sb.toString();
        }
    }

    /* --------------------------------------------------------------
     *  Core solving routine – orchestrates input, validation and output.
     * -------------------------------------------------------------- */
    private static void solve(FastScanner sc, PrintWriter out) throws IOException {
        int t = sc.nextInt();
        StringBuilder answers = new StringBuilder();

        while (t-- > 0) {
            int rows = sc.nextInt();
            int cols = sc.nextInt();

            int[][] grid = new int[rows][cols];
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    grid[i][j] = sc.nextInt();
                }
            }

            boolean ok = GridValidator.isValid(grid, rows, cols);
            answers.append(ok ? "YES" : "NO").append('\n');

            if (ok) {
                answers.append(GridFormatter.buildOutput(grid, rows, cols));
            }
        }

        out.print(answers.toString());
    }

    /* --------------------------------------------------------------
     *  Entry point – proper resource handling.
     * -------------------------------------------------------------- */
    public static void main(String[] args) {
        try (FastScanner scanner = new FastScanner(new BufferedReader(new InputStreamReader(System.in)));
             PrintWriter writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)))) {

            solve(scanner, writer);
        } catch (IOException e) {
            // In production we might log the exception; here we simply ignore it
            // to stay compatible with the original skeleton.
        }
    }
}

import java.util.Scanner;

/**
 * Reads multiple test cases and validates “neighbor‑grid” configurations.
 * If a configuration is valid, prints "YES" followed by a deterministic
 * pattern (2 on corners, 3 on edges, 4 inside); otherwise prints "NO".
 */
public class NeighborGrid {

    // -----------------------------------------------------------------------
    // Constants that capture the problem limits – easier to change / document.
    // -----------------------------------------------------------------------
    private static final int MAX_CORNER_VALUE = 2;   // allowed max on corners
    private static final int MAX_EDGE_VALUE   = 3;   // allowed max on edges (non‑corner)
    private static final int MAX_INNER_VALUE  = 4;   // allowed max on interior cells

    /** Entry point – processes each test case sequentially. */
    public static void main(String[] args) {
        /* Try‑with‑resources automatically closes the Scanner. */
        try (Scanner scanner = new Scanner(System.in)) {
            int caseCount = scanner.nextInt();
            for (int i = 0; i < caseCount; i++) {
                processSingleCase(scanner);
            }
        }
    }

    /** Reads one grid, validates it and prints the appropriate result. */
    private static void processSingleCase(Scanner sc) {
        int rows = scanner.nextInt();   // m from the original code
        int cols = scanner.nextInt();   // n from the original code

        int[][] grid = new int[rows][cols];

        /* ---------------------------------------------------------------
         * Read the grid in row‑major order – this matches typical matrix
         * input and avoids the confusing column‑first loop of the original.
         * --------------------------------------------------------------- */
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                grid[r][c] = scanner.nextInt();
            }
        }

        if (isValidConfiguration(grid, rows, cols)) {
            System.out.println("YES");
            printDeterministicPattern(rows, cols);
        } else {
            System.out.println("NO");
        }
    }

    /** Checks that every cell respects the neighbour‑grid rules. */
    private static boolean isValidConfiguration(int[][] grid, int rows, int cols) {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                int value = grid[r][c];

                // Interior cells are limited to 4 (checked first for early exit)
                if (value > MAX_INNER_VALUE) {
                    return false;
                }

                if (isCorner(r, c, rows, cols)) {
                    if (value > MAX_CORNER_VALUE) {
                        return false;
                    }
                } else if (isEdge(r, c, rows, cols)) {
                    if (value > MAX_EDGE_VALUE) {
                        return false;
                    }
                }
                // Interior cells have already been validated by the first test.
            }
        }
        return true;
    }

    /** Returns true if the cell lies on a corner of the grid. */
    private static boolean isCorner(int r, int c, int rows, int cols) {
        return (r == 0 || r == rows - 1) && (c == 0 || c == cols - 1);
    }

    /** Returns true if the cell lies on an edge but not a corner. */
    private static boolean isEdge(int r, int c, int rows, int cols) {
        return r == 0 || r == rows - 1 || c == 0 || c == cols - 1;
    }

    /** Prints the fixed pattern required when the configuration is valid. */
    private static void printDeterministicPattern(int rows, int cols) {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (isCorner(r, c, rows, cols)) {
                    System.out.print(2 + " ");
                } else if (isEdge(r, c, rows, cols)) {
                    System.out.print(3 + " ");
                } else {
                    System.out.print(4 + " ");
                }
            }
            System.out.println();   // end of row
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

/**
 * Refactored solution that improves readability, naming, and structure
 * while preserving the original functionality.
 */
public class Solution {

    /** Fast scanner that wraps a BufferedReader for efficient token parsing. */
    private static final class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner(BufferedReader br) {
            this.br = br;
        }

        /** Ensures a non‑null tokenizer and fills it with remaining tokens. */
        private void ensureTokenizer() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                st = new StringTokenizer(br.readLine());
            }
        }

        /** Returns the next token, or reads a new line if needed. */
        String next() throws IOException {
            ensureTokenizer();
            return st.nextToken();
        }

        /** Convenience method for reading integers. */
        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }

    /** Central place for immutable constants that describe allowed cell values. */
    private static final class Limits {
        /** Maximum value for corner cells. */
        static final int CORNER = 2;
        /** Maximum value for edge (non‑corner border) cells. */
        static final int EDGE = 3;
        /** Maximum value for interior cells. */
        static final int INTERIOR = 4;
    }

    /** Determines whether a cell is located at a corner of the matrix. */
    private static boolean isCorner(int row, int col, int rows, int cols) {
        return (row == 0 || row == rows - 1) && (col == 0 || col == cols - 1);
    }

    /** Determines whether a cell lies on the border (edge) of the matrix. */
    private static boolean isEdge(int row, int col, int rows, int cols) {
        return row == 0 || row == rows - 1 || col == 0 || col == cols - 1;
    }

    /** Returns the maximum permissible value for a cell based on its position. */
    private static int maxAllowed(int row, int col, int rows, int cols) {
        if (isCorner(row, col, rows, cols)) {
            return Limits.CORNER;
        }
        if (isEdge(row, col, rows, cols)) {
            return Limits.EDGE;
        }
        return Limits.INTERIOR;
    }

    /** Entry point of the program. */
    public static void main(String[] args) throws IOException {
        try (FastScanner scanner = new FastScanner(new BufferedReader(new InputStreamReader(System.in)))) {
            int testCases = scanner.nextInt();
            StringBuilder allOutput = new StringBuilder();

            while (testCases-- > 0) {
                allOutput.append(processTestCase(scanner));
            }

            System.out.print(allOutput.toString());
        }
    }

    /**
     * Handles a single test case:
     * <ul>
     *   <li>Reads matrix dimensions and values.</li>
     *   <li>Validates that each value does not exceed its positional limit.</li>
     *   <li>If valid, outputs "YES" followed by a matrix filled with the
     *       prescribed corner/edge/interior values.</li>
     * </ul>
     */
    private static String processTestCase(FastScanner scanner) throws IOException {
        int rows = scanner.nextInt();
        int cols = scanner.nextInt();
        int[][] matrix = new int[rows][cols];

        // ---- Validation ---------------------------------------------------------
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                matrix[i][j] = scanner.nextInt();
                int limit = maxAllowed(i, j, rows, cols);
                if (matrix[i][j] > limit) {
                    return "NO";
                }
            }
        }

        // ---- Construction of output matrix --------------------------------------
        StringBuilder result = new StringBuilder("YES\n");
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                int value = maxAllowed(i, j, rows, cols);
                result.append(value).append(' ');
            }
            result.append('\n');
        }
        return result.toString();
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

/**
 * Refactored solution for the neighbour‑grid problem.
 *
 * <p>Key improvements:
 * <ul>
 *   <li>Clear separation of concerns (input handling, grid construction,
 *       validation, output).</li>
 *   <li>Named constants instead of magic numbers.</li>
 *   <li>Small, well‑named helper methods.</li>
 *   <li>Fast but safe input reader.</li>
 *   <li>Self‑documenting code and minimal nesting.</li>
 * </ul>
 */
public final class NeighbourGrid {

    /* --------------------------------------------------------------------- */
    /* Constants – replace magic numbers with meaningful names               */
    /* --------------------------------------------------------------------- */
    private static final int CORNER_VALUE      = 2;
    private static final int EDGE_VALUE        = 3;
    private static final int INTERIOR_VALUE    = 4;

    private static final class FastScanner {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        FastScanner(InputStream stream) {
            this.reader = new BufferedReader(new InputStreamReader(stream));
        }

        /** Ensures a non‑empty tokenizer; reads another line if necessary. */
        private void ensureTokenizer() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                String line = reader.readLine();
                if (line == null) {
                    break;
                }
                tokenizer = new StringTokenizer(line);
            }
        }

        String next() {
            try {
                ensureTokenizer();
            } catch (IOException e) {
                throw new UncheckedIOException(e);
            }
            return tokenizer.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }
    }

    /* --------------------------------------------------------------------- */
    /* Helper – decides which constant a cell must receive                    */
    /* --------------------------------------------------------------------- */
    private static int requiredValue(int row, int col, int n, int m) {
        // Corner cells
        if ((row == 0 && col == 0) ||
            (row == 0 && col == m - 1) ||
            (row == n - 1 && col == 0) ||
            (row == n - 1 && col == m - 1)) {
            return CORNER_VALUE;
        }
        // Edge (but not corner) cells
        if ((row == 0 || row == n - 1) && (col > 0 && col < m - 1) ||
            (col == 0 || col == m - 1) && (row > 0 && row < n - 1)) {
            return EDGE_VALUE;
        }
        // Interior cells
        return INTERIOR_VALUE;
    }

    /* --------------------------------------------------------------------- */
    /* Core solving routine for a single test case                            */
    /* --------------------------------------------------------------------- */
    private static void solve(FastScanner fs) {
        int n = fs.nextInt();          // number of rows
        int m = fs.nextInt();          // number of columns

        int[][] grid = new int[n][m];
        boolean possible = true;       // will stay true only if all checks pass

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                int required = requiredValue(i, j, n, m);
                int input    = fs.nextInt();   // value supplied for this cell

                // Validation: required must NOT be smaller than the supplied value
                if (required < input) {
                    possible = false;
                }

                grid[i][j] = required;   // store the constant to be printed later
            }
        }

        // -----------------------------------------------------------------
        // Output handling
        // -----------------------------------------------------------------
        if (!possible) {
            System.out.println("NO");
            return;
        }

        System.out.println("YES");
        for (int[] row : grid) {
            for (int cell : row) {
                System.out.print(cell + " ");
            }
            System.out.println();
        }
    }

    /* --------------------------------------------------------------------- */
    /* Entry point – processes multiple test cases                           */
    /* --------------------------------------------------------------------- */
    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        int t = fs.nextInt();               // number of test cases

        while (t-- > 0) {
            solve(fs);
        }
    }
}

import java.util.Scanner;

/**
 * Refactored solution that checks whether a matrix respects position‑based
 * limits and, if valid, fills it with the appropriate maximum values.
 *
 * <p>Constraints per cell:
 * <ul>
 *   <li>Corner cells      → maximum 2</li>
 *   <li>Border (non‑corner) cells → maximum 3</li>
 *   <li>Interior cells    → maximum 4</li>
 * </ul>
 *
 * <p>If any cell exceeds its allowed maximum the whole test case is rejected
 * with the output {@code NO}. Otherwise the matrix is replaced with the
 * maximum values and printed prefixed by {@code YES}.
 */
public class Solution {

    /* --------------------------------------------------------------------- */
    /*  Constants                                                            */
    /* --------------------------------------------------------------------- */
    private static final int CORNER_MAX      = 2;
    private static final int BORDER_MAX      = 3;
    private static final int INTERIOR_MAX    = 4;

    /* --------------------------------------------------------------------- */
    /*  Position type helpers                                                */
    /* --------------------------------------------------------------------- */
    private enum PositionType { CORNER, BORDER, INTERIOR }

    /**
     * Determines the position type of a cell.
     *
     * @param row    current row index
     * @param col    current column index
     * @param rows   total number of rows
     * @param cols   total number of columns
     * @return the {@link PositionType} of the cell
     */
    private static PositionType determinePosition(int row, int col, int rows, int cols) {
        // Corner → both row and column are on the edge
        if ((row == 0 || row == rows - 1) && (col == 0 || col == cols - 1)) {
            return PositionType.CORNER;
        }
        // Border (but not corner)
        if (row == 0 || row == rows - 1 || col == 0 || col == cols - 1) {
            return PositionType.BORDER;
        }
        // Interior
        return PositionType.INTERIOR;
    }

    /**
     * Returns the allowed maximum value for a given position type.
     */
    private static int getMaxAllowed(PositionType type) {
        return switch (type) {
            case CORNER -> CORNER_MAX;
            case BORDER -> BORDER_MAX;
            case INTERIOR -> INTERIOR_MAX;
        };
    }

    /* --------------------------------------------------------------------- */
    /*  Validation & transformation logic                                    */
    /* --------------------------------------------------------------------- */

    /**
     * Checks whether every cell respects its position‑specific limit.
     *
     * @param matrix the input matrix
     * @param rows   number of rows
     * @param cols   number of columns
     * @return {@code true} if the matrix is valid, {@code false} otherwise
     */
    private static boolean isValid(int[][] matrix, int rows, int cols) {
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                int value = matrix[i][j];
                PositionType type = determinePosition(i, j, rows, cols);
                int maxAllowed = getMaxAllowed(type);
                if (value > maxAllowed) {
                    return false;
                }
            }
        }
        return true;
    }

    /**
     * Fills the matrix with the appropriate maximum value for each cell.
     *
     * @param rows number of rows
     * @param cols number of columns
     * @return a new matrix containing the maximum values per position
     */
    private static int[][] fillMatrix(int rows, int cols) {
        int[][] filled = new int[rows][cols];
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                filled[i][j] = getMaxAllowed(determinePosition(i, j, rows, cols));
            }
        }
        return filled;
    }

    /* --------------------------------------------------------------------- */
    /*  Core solving routine                                                  */
    /* --------------------------------------------------------------------- */

    private static void solve() {
        Scanner scanner = new Scanner(System.in);
        int testCases = scanner.nextInt();

        while (testCases-- > 0) {
            int n = scanner.nextInt();
            int m = scanner.nextInt();
            int[][] input = new int[n][m];

            // Read the matrix
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    input[i][j] = scanner.nextInt();
                }
            }

            // Validate the matrix according to the derived rules
            if (isValid(input, n, m)) {
                int[][] output = fillMatrix(n, m);
                System.out.println("YES");
                printMatrix(output);
            } else {
                System.out.println("NO");
            }
        }

        scanner.close();
    }

    /** Helper to print a matrix row‑by‑row. */
    private static void printMatrix(int[][] matrix) {
        for (int[] row : matrix) {
            for (int value : row) {
                System.out.print(value + " ");
            }
            System.out.println();
        }
    }

    /* --------------------------------------------------------------------- */
    /*  Entry point                                                            */
    /* --------------------------------------------------------------------- */
    public static void main(String[] args) {
        solve();
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

/**
 * Refactored solution for matrix border validation and pattern generation.
 */
public class Main {

    /** Minimum allowed value for corner cells (top‑left, top‑right, bottom‑left, bottom‑right). */
    private static final int MIN_CORNER = 2;

    /** Minimum allowed value for edge (non‑corner) cells on the border. */
    private static final int MIN_EDGE = 3;

    /** Minimum allowed value for interior cells. */
    private static final int MIN_INTERNAL = 4;

    /** Simple fast input reader. */
    private static final class FastReader {
        private final BufferedReader br;
        private StringTokenizer st;

        FastReader() {
            this.br = new BufferedReader(new InputStreamReader(System.in));
        }

        /** Reads the next token, retrying on I/O errors. */
        private String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return st.nextToken();
        }

        int nextInt() { return Integer.parseInt(next()); }
        long nextLong() { return Long.parseLong(next()); }
        double nextDouble() { return Double.parseDouble(next()); }
        String nextLine() { return next(); }
    }

    /** Describes the classification of a cell in the border of a matrix. */
    private enum BorderType { CORNER, EDGE, INTERNAL }

    /**
     * Determines the border type of position (i, j) inside an {@code rows × cols} matrix.
     */
    private static BorderType determineBorderType(int i, int j, int rows, int cols) {
        if ((i == 0 && j == 0) ||
            (i == 0 && j == cols - 1) ||
            (i == rows - 1 && j == cols - 1) ||
            (i == rows - 1 && j == 0)) {
            return BorderType.CORNER;
        }
        if (i == 0 || i == rows - 1 || j == 0 || j == cols - 1) {
            return BorderType.EDGE;
        }
        return BorderType.INTERNAL;
    }

    /**
     * Checks whether {@code value} satisfies the minimum requirement for the given {@code type}.
     */
    private static boolean isValid(int value, BorderType type) {
        return switch (type) {
            case CORNER -> value <= MIN_CORNER;
            case EDGE -> value <= MIN_EDGE;
            case INTERNAL -> value <= MIN_INTERNAL;
        };
    }

    /**
     * Builds the pattern that should be printed when the matrix passes validation.
     */
    private static String generatePattern(int rows, int cols) {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                sb.append(valueFor(determineBorderType(i, j, rows, cols))).append(' ');
            }
            sb.append('\n');
        }
        return sb.toString();
    }

    /** Returns the character to output for a given {@link BorderType}. */
    private static String valueFor(BorderType type) {
        return switch (type) {
            case CORNER -> "2";
            case EDGE -> "3";
            case INTERNAL -> "4";
        };
    }

    /** Handles a single test case: reads the matrix, validates it, and prints the result. */
    private static void solveTestCase(FastReader reader) {
        int n = reader.nextInt();
        int m = reader.nextInt();

        int[][] matrix = new int[n][m];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                matrix[i][j] = reader.nextInt();
            }
        }

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                BorderType type = determineBorderType(i, j, n, m);
                if (!isValid(matrix[i][j], type)) {
                    System.out.println("NO");
                    return;
                }
            }
        }

        System.out.println("YES");
        System.out.print(generatePattern(n, m));
    }

    /** Entry point – reads the number of test cases and processes each sequentially. */
    public static void main(String[] args) {
        FastReader reader = new FastReader();
        int t = reader.nextInt();

        while (t-- > 0) {
            solveTestCase(reader);
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
