/**
 * Reads several test cases, validates the supplied numeric grid and,
 * if the validation succeeds, prints a transformed grid.
 *
 * <p>
 *   Validation rules (mirroring the original program):
 *   <ul>
 *     <li>Corner cells  – value must be ≤ 2</li>
 *     <li>Edge (non‑corner) cells – value must be ≤ 3</li>
 *     <li>Inner cells – value must be ≤ 4</li>
 *   </ul>
 *   If the grid satisfies the rules the program prints
 *   <code>YES</code> followed by the fixed output grid:
 *   <code>2</code> on the corners, <code>3</code> on the edges and
 *   <code>4</code> elsewhere.
 * </p>
 */
public class GridProcessor {

    /** Simple fast scanner that works with any {@code InputStream}. */
    private static final class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner() {
            this.br = new BufferedReader(new InputStreamReader(System.in));
        }

        /** Returns the next token, reading a new line when necessary. */
        private String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) {
                        return null;
                    }
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    // In a contest environment this never happens,
                    // but we re‑throw as an unchecked exception.
                    throw new RuntimeException(e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }
    }

    /** Maximum allowed value for a given cell type. */
    private static int maxAllowed(int i, int j, int n, int m) {
        if (isCorner(i, j, n, m)) {
            return 2;
        }
        if (isEdge(i, j, n, m)) {
            return 3;
        }
        return 4; // inner cell
    }

    private static boolean isCorner(int i, int j, int n, int m) {
        return (i == 0 && j == 0) ||
               (i == 0 && j == m - 1) ||
               (i == n - 1 && j == 0) ||
               (i == n - 1 && j == m - 1);
    }

    private static boolean isEdge(int i, int j, int n, int m) {
        return i == 0 || i == n - 1 || j == 0 || j == m - 1;
    }

    /** Validates the whole grid according to the rules described above. */
    private static boolean validate(int[][] grid, int n, int m) {
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                int val = grid[i][j];
                if (val > maxAllowed(i, j, n, m)) {
                    return false;
                }
            }
        }
        return true;
    }

    /** Prints the fixed output grid after a successful validation. */
    private static void printOutput(int n, int m) {
        System.out.println("YES");
        for (int i = 0; i < n; i++) {
            StringBuilder line = new StringBuilder();
            for (int j = 0; j < m; j++) {
                int cell;
                if (isCorner(i, j, n, m)) {
                    cell = 2;
                } else if (isEdge(i, j, n, m)) {
                    cell = 3;
                } else {
                    cell = 4;
                }
                line.append(cell);
                if (j < m - 1) {
                    line.append(' ');
                }
            }
            System.out.println(line.toString());
        }
    }

    /** Entry point – processes multiple test cases. */
    public static void main(String[] args) {
        FastScanner scanner = new FastScanner();

        int t = scanner.nextInt();               // number of test cases
        while (t-- > 0) {
            int n = scanner.nextInt();
            int m = scanner.nextInt();

            int[][] grid = new int[n][m];
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    grid[i][j] = scanner.nextInt();
                }
            }

            if (validate(grid, n, m)) {
                printOutput(n, m);
            } else {
                System.out.println("NO");
            }
        }
    }
}

/**
 * Refactored version of the original InVoker program.
 * The refactor focuses on:
 *   • Separating concerns (input, validation, output)
 *   • Giving meaningful names to constants, methods and variables
 *   • Removing dead code and unused imports
 *   • Keeping the original behaviour unchanged
 */
import java.io.BufferedReader;
import java.io.IOException;
import java.io.PrintWriter;
import java.util.StringTokenizer;

public class InVoker {

    /** Output stream used for printing results */
    private static final PrintWriter OUT = new PrintWriter(System.out);

    /** Fast scanner for reading input */
    private static final FastScanner IN = new FastScanner();

    /** Directions used only for compatibility with the original stub – not used in the algorithm */
    private static final int[][] DUMMY_DIRS = {
            { -1, 0 }, { 0, -1 }, { 0, 1 }, { 1, 0 }
    };

    /** Boundary limits for cell values */
    private static final int MAX_CORNER_VALUE = 2;
    private static final int MAX_EDGE_VALUE    = 3;
    private static final int MAX_INNER_VALUE   = 4;

    /** ------------------------------------------------------------------- */
    /** Entry point */
    public static void main(String[] args) {
        new InVoker().solve();
        OUT.close();
    }

    /** ------------------------------------------------------------------- */
    /** Main solving routine */
    private void solve() {
        int t = IN.nextInt();

        while (t-- > 0) {
            int n = IN.nextInt();
            int m = IN.nextInt();
            long[][] grid = readGrid(n, m);

            if (!isValid(grid, n, m)) {
                OUT.println("NO");
                continue;
            }

            OUT.println("YES");
            printPattern(n, m);
        }
    }

    /** ------------------------------------------------------------------- */
    /** Reads an n × m matrix of long values from the scanner */
    private long[][] readGrid(int n, int m) {
        long[][] a = new long[n][m];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                a[i][j] = IN.nextLong();
            }
        }
        return a;
    }

    /** ------------------------------------------------------------------- */
    /** Determines whether the supplied grid satisfies all constraints */
    private boolean isValid(long[][] a, int n, int m) {
        // 1. All cells must not exceed their respective maximal allowed value
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                int limit = boundLimit(i, j, n, m);
                if (a[i][j] > limit) {
                    return false;
                }
            }
        }

        // 2. The four corners must be at most 2 (already covered by the limit check,
        //    but kept for clarity matching the original code)
        if (a[0][0] > MAX_CORNER_VALUE
                || a[n - 1][0] > MAX_CORNER_VALUE
                || a[0][m - 1] > MAX_CORNER_VALUE
                || a[n - 1][m - 1] > MAX_CORNER_VALUE) {
            return false;
        }

        return true;
    }

    /** ------------------------------------------------------------------- */
    /** Returns the maximal allowed value for a cell at position (i, j) */
    private int boundLimit(int i, int j, int n, int m) {
        if (isCorner(i, j, n, m)) {
            return MAX_CORNER_VALUE;
        }
        if (isEdge(i, j, n, m)) {
            return MAX_EDGE_VALUE;
        }
        return MAX_INNER_VALUE;
    }

    /** ------------------------------------------------------------------- */
    /** Checks whether the cell lies on a corner of the matrix */
    private boolean isCorner(int i, int j, int n, int m) {
        return (i == 0 || i == n - 1) && (j == 0 || j == m - 1);
    }

    /** ------------------------------------------------------------------- */
    /** Checks whether the cell lies on an edge (but not a corner) */
    private boolean isEdge(int i, int j, int n, int m) {
        return i == 0 || i == n - 1 || j == 0 || j == m - 1;
    }

    /** ------------------------------------------------------------------- */
    /** Prints the required pattern (2 on corners, 3 on edges, 4 inside) */
    private void printPattern(int n, int m) {
        for (int i = 0; i < n; i++) {
            StringBuilder sb = new StringBuilder();
            for (int j = 0; j < m; j++) {
                sb.append(valueToPrint(i, j, n, m)).append(' ');
            }
            OUT.println(sb.toString().trim());
        }
    }

    /** ------------------------------------------------------------------- */
    /** Returns the value that must be printed for a given cell position */
    private int valueToPrint(int i, int j, int n, int m) {
        if (isCorner(i, j, n, m)) {
            return MAX_CORNER_VALUE;
        }
        if (isEdge(i, j, n, m)) {
            return MAX_EDGE_VALUE;
        }
        return MAX_INNER_VALUE;
    }

    /** ------------------------------------------------------------------- */
    /** Fast scanner utility – a thin wrapper around BufferedReader / StringTokenizer */
    private static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        long nextLong() {
            return Long.parseLong(next());
        }

        String nextLine() {
            try {
                return br.readLine();
            } catch (IOException e) {
                throw new RuntimeException(e);
            }
        }
    }
}

import java.io.*;
import java.util.*;

public class Solution {

    /* --------------------------------------------------------------
     *  Thresholds for each cell type (corner, edge, interior)
     * -------------------------------------------------------------- */
    private static final int CORNER_MAX = 2;
    private static final int EDGE_MAX   = 3;
    private static final int INTERIOR_MAX = 4;

    /* --------------------------------------------------------------
     *  Fast I/O utilities
     * -------------------------------------------------------------- */
    private static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner() {
            this.br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    throw new UncheckedIOException(e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }
    }

    /* --------------------------------------------------------------
     *  Main driver
     * -------------------------------------------------------------- */
    public static void main(String[] args) {
        FastScanner sc = new FastScanner();
        PrintWriter out = new PrintWriter(new BufferedOutputStream(System.out));

        int t = sc.nextInt();
        while (t-- > 0) {
            int n = sc.nextInt();
            int m = sc.nextInt();
            int[][] grid = readMatrix(sc, n, m);

            if (!isValid(grid, n, m)) {
                out.println("NO");
                continue;
            }

            int[][] filled = fillPattern(n, m);
            out.println("YES");
            printMatrix(filled, out);
        }
        out.close();
    }

    /* --------------------------------------------------------------
     *  Helper methods
     * -------------------------------------------------------------- */
    private static int[][] readMatrix(FastScanner sc, int n, int m) {
        int[][] a = new int[n][m];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                a[i][j] = sc.nextInt();
            }
        }
        return a;
    }

    /** Checks whether the given matrix respects the value limits
     *  according to its position (corner, edge, interior). */
    private static boolean isValid(int[][] a, int n, int m) {
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                boolean rowEdge = i == 0 || i == n - 1;
                boolean colEdge = j == 0 || j == m - 1;
                boolean corner    = rowEdge && colEdge;

                int maxAllowed = corner ? CORNER_MAX
                         : (rowEdge || colEdge) ? EDGE_MAX : INTERIOR_MAX;

                if (a[i][j] > maxAllowed) {
                    return false;
                }
            }
        }
        return true;
    }

    /** Fills the grid according to the problem’s pattern:
     *  corners → 2, edges (excluding corners) → 3,
     *  interior cells → 4. */
    private static int[][] fillPattern(int n, int m) {
        int[][] result = new int[n][m];

        // interior
        for (int i = 1; i < n - 1; i++) {
            Arrays.fill(result[i], INTERIOR_MAX);
        }

        // top and bottom edges (excluding corners)
        for (int j = 1; j < m - 1; j++) {
            result[0][j] = EDGE_MAX;
            result[n - 1][j] = EDGE_MAX;
        }

        // left and right edges (excluding corners)
        for (int i = 1; i < n - 1; i++) {
            result[i][0] = EDGE_MAX;
            result[i][m - 1] = EDGE_MAX;
        }

        // corners
        result[0][0] = CORNER_MAX;
        result[0][m - 1] = CORNER_MAX;
        result[n - 1][0] = CORNER_MAX;
        result[n - 1][m - 1] = CORNER_MAX;

        return result;
    }

    private static void printMatrix(int[][] matrix, PrintWriter out) {
        for (int[] row : matrix) {
            StringBuilder sb = new StringBuilder();
            for (int val : row) {
                sb.append(val).append(' ');
            }
            out.println(sb.toString().trim());
        }
    }
}

import java.io.BufferedInputStream;
import java.io.IOException;
import java.io.InputStream;

/**
 * Main class that reads multiple test cases.
 * For each test case it checks whether every element of matrix {@code a}
 * is less than or equal to the corresponding element of a generated
 * boundary‑value matrix {@code b}. If the condition holds, it prints "YES"
 * followed by matrix {@code b}; otherwise it prints "NO".
 */
public class Grid {

    /** Value assigned to the four corner cells of matrix {@code b}. */
    private static final long CORNER_VALUE = 2L;

    /** Value assigned to the remaining edge cells of matrix {@code b}. */
    private static final long EDGE_VALUE = 3L;

    /** Value assigned to the interior cells of matrix {@code b}. */
    private static final long INTERIOR_VALUE = 4L;

    /**
     * Generates a matrix {@code b} whose cells are filled according to the
     * distance from the border:
     * <ul>
     *   <li>corners → {@value #CORNER_VALUE}</li>
     *   <li>edges (excluding corners) → {@value #EDGE_VALUE}</li>
     *   <li>interior → {@value #INTERIOR_VALUE}</li>
     * </ul>
     *
     * @param rows number of rows
     * @param cols number of columns
     * @return a {@code rows × cols} matrix with the described pattern
     */
    private static long[][] generateBoundaryMatrix(int rows, int cols) {
        long[][] b = new long[rows][cols];
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if ((i == 0 && j == 0) ||
                    (i == 0 && j == cols - 1) ||
                    (i == rows - 1 && j == 0) ||
                    (i == rows - 1 && j == cols - 1)) {
                    b[i][j] = CORNER_VALUE;
                } else if (i == 0 || i == rows - 1 || j == 0 || j == cols - 1) {
                    b[i][j] = EDGE_VALUE;
                } else {
                    b[i][j] = INTERIOR_VALUE;
                }
            }
        }
        return b;
    }

    /**
     * Checks whether every element of matrix {@code a} is less than or equal
     * to the corresponding element of matrix {@code b}.
     *
     * @param a source matrix
     * @param b comparison matrix
     * @param rows number of rows
     * @param cols number of columns
     * @return {@code true} if all {@code a[i][j] ≤ b[i][j]}, {@code false} otherwise
     */
    private static boolean isAllElementsNotGreaterThan(long[][] a, long[][] b,
                                                       int rows, int cols) {
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (a[i][j] > b[i][j]) {
                    return false;
                }
            }
        }
        return true;
    }

    /**
     * Fast scanner based on {@link BufferedInputStream} that reads integers,
     * longs and strings without creating excessive temporary objects.
     */
    private static class FastScanner {
        private final InputStream stream;
        private final byte[] buffer = new byte[1024];
        private int bytesRead = 0;
        private int currentChar;
        private int position = 0;

        FastScanner(InputStream stream) {
            this.stream = stream;
        }

        private int readByte() throws IOException {
            if (position >= bytesRead) {
                currentChar = stream.read();
                if (currentChar == -1) {
                    return -1;
                }
                bytesRead = 1;
                position = 0;
            } else {
                currentChar = buffer[position++];
            }
            return currentChar;
        }

        /** Skips whitespace characters. */
        private int skipWhiteSpace() throws IOException {
            int c;
            do {
                c = readByte();
            } while (c <= ' ' && c != -1);
            return c;
        }

        /** Reads next token as a string. */
        private String nextToken() throws IOException {
            int c = skipWhiteSpace();
            StringBuilder sb = new StringBuilder();
            do {
                sb.append((char) c);
                c = readByte();
            } while (c > ' ');
            return sb.toString();
        }

        /** Reads an {@code int}. */
        int nextInt() throws IOException {
            return Integer.parseInt(nextToken());
        }

        /** Reads a {@code long}. */
        long nextLong() throws IOException {
            return Long.parseLong(nextToken());
        }
    }

    /** Entry point of the program. */
    public static void main(String[] args) throws IOException {
        try (BufferedInputStream bis = new BufferedInputStream(System.in)) {
            FastScanner scanner = new FastScanner(bis);
            StringBuilder output = new StringBuilder();

            int testCases = scanner.nextInt();
            for (int t = 0; t < testCases; t++) {
                int n = scanner.nextInt();
                int m = scanner.nextInt();

                long[][] a = new long[n][m];
                for (int i = 0; i < n; i++) {
                    for (int j = 0; j < m; j++) {
                        a[i][j] = scanner.nextLong();
                    }
                }

                long[][] b = generateBoundaryMatrix(n, m);

                if (isAllElementsNotGreaterThan(a, b, n, m)) {
                    output.append("YES\n");
                    for (int i = 0; i < n; i++) {
                        for (int j = 0; j < m; j++) {
                            output.append(b[i][j]).append(' ');
                        }
                        output.append('\n');
                    }
                } else {
                    output.append("NO\n");
                }
            }

            System.out.print(output.toString());
        }
    }
}

import java.io.*;
import java.util.StringTokenizer;

/**
 * Refactored solution for the “border‑capped matrix” problem.
 * The code is split into small, well‑named methods, uses clear
 * naming, avoids unnecessary classes and handles input safely.
 */
public class Solution {

    /* -------------------------------------------------------------
       Fast I/O helper – a thin wrapper around BufferedReader.
       ------------------------------------------------------------- */
    private static final class FastReader {
        private final BufferedReader br;
        private StringTokenizer st;

        FastReader() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        /** Returns next token, waiting for more if needed. */
        String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    throw new UncheckedIOException(e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        long nextLong() {
            return Long.parseLong(next());
        }

        double nextDouble() {
            return Double.parseDouble(next());
        }

        /** Returns the next complete line (may be empty). */
        String nextLine() {
            try {
                return br.readLine();
            } catch (IOException e) {
                throw new UncheckedIOException(e);
            }
        }
    }

    /**
     * Determines the maximal allowed value for a cell.
     *
     * @param i row index
     * @param j column index
     * @param n number of rows
     * @param m number of columns
     * @return 2 for a corner, 3 for a non‑corner edge, 4 for an interior cell
     */
    private static int maxAllowed(int i, int j, int n, int m) {
        if ((i == 0 || i == n - 1) && (j == 0 || j == m - 1)) {
            return 2;                 // corner
        }
        if (i == 0 || i == n - 1 || j == 0 || j == m - 1) {
            return 3;                 // edge
        }
        return 4;                     // inner cell
    }

    /**
     * Solves a single test case. Returns {@code true} always; the
     * method writes the answer to the supplied {@link PrintWriter}.
     */
    private static boolean solveOne(FastReader fr, PrintWriter out) throws IOException {
        int n = fr.nextInt();
        int m = fr.nextInt();

        int[][] grid = new int[n][m];
        boolean anyPositive = false;

        // Read matrix while remembering whether at least one entry is > 0
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                grid[i][j] = fr.nextInt();
                if (grid[i][j] > 0) {
                    anyPositive = true;
                }
            }
        }

        /* ---------------------------------------------------------
           Case 1 – matrix contains only zeros.
           According to the original specification we simply
           output "YES" and the unchanged matrix.
           --------------------------------------------------------- */
        if (!anyPositive) {
            out.println("YES");
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    out.print(grid[i][j]);
                    if (j + 1 < m) out.print(' ');
                }
                out.println();
            }
            return true;
        }

        /* ---------------------------------------------------------
           General case – enforce the per‑cell limits.
           While iterating we also verify that the original value
           does not exceed the allowed limit. If it does, the test
           case is impossible.
           --------------------------------------------------------- */
        boolean possible = true;
        for (int i = 0; i < n && possible; i++) {
            for (int j = 0; j < m; j++) {
                int limit = maxAllowed(i, j, n, m);

                if (grid[i][j] > limit) {
                    possible = false;
                    break;
                }

                // Clamp the value to the limit (mirrors the original code)
                grid[i][j] = limit;
            }
        }

        if (!possible) {
            out.println("NO");
        } else {
            out.println("YES");
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    out.print(grid[i][j]);
                    if (j + 1 < m) out.print(' ');
                }
                out.println();
            }
        }
        return true;
    }

    /** Entry point – reads all test cases and delegates to {@link #solveOne}. */
    public static void main(String[] args) throws Exception {
        FastReader fr = new FastReader();
        PrintWriter out = new PrintWriter(System.out, true); // auto‑flush

        try {
            int t = fr.nextInt();
            while (t-- > 0) {
                solveOne(fr, out);
            }
        } finally {
            out.close();
        }
    }
}

import java.io.IOException;
import java.util.Scanner;

/**
 * Refactored TP – checks a matrix against positional limits
 * and prints a valid configuration when possible.
 */
public class TP {

    // -------------------------------------------------------------------------
    // Constants representing the maximum allowed value for each cell type
    // -------------------------------------------------------------------------
    private static final int MAX_CORNER = 2;
    private static final int MAX_EDGE   = 3;
    private static final int MAX_INTERIOR = 4;

    public static void main(String[] args) throws IOException {
        // Try‑with‑resources ensures the Scanner is closed automatically
        try (Scanner sc = new Scanner(System.in)) {
            int t = sc.nextInt();                 // number of test cases
            while (t-- > 0) {
                processTestCase(sc);
            }
        }
    }

    /**
     * Reads a single test case, validates the matrix and prints the result.
     */
    private static void processTestCase(Scanner sc) {
        int n = sc.nextInt();   // rows
        int m = sc.nextInt();   // columns
        int[][] grid = new int[n][m];

        // Read the matrix values
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                grid[i][j] = sc.nextInt();
            }
        }

        // Validate the matrix against the positional limits
        if (isValid(grid, n, m)) {
            buildAndPrintSolution(grid, n, m);
        } else {
            System.out.println("NO");
        }
    }

    /**
     * Determines whether the supplied matrix respects the maximum allowed
     * value for each cell based on its position (corner, edge, interior).
     */
    private static boolean isValid(int[][] grid, int n, int m) {
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                int maxAllowed = getMaxAllowed(i, j, n, m);
                if (grid[i][j] > maxAllowed) {
                    return false;               // violation found
                }
            }
        }
        return true;                              // all values are valid
    }

    /**
     * Returns the maximum permissible value for the cell at (i, j).
     */
    private static int getMaxAllowed(int i, int j, int n, int m) {
        boolean isCorner = (i == 0 || i == n - 1) && (j == 0 || j == m - 1);
        boolean isEdge   = !isCorner &&
                (i == 0 || i == n - 1 || j == 0 || j == m - 1);
        return isCorner ? MAX_CORNER : (isEdge ? MAX_EDGE : MAX_INTERIOR);
    }

    /**
     * Constructs a valid configuration (if one exists) and prints it.
     *
     * The configuration puts:
     *   • MAX_CORNER on the four corners,
     *   • MAX_EDGE   on the remaining border cells,
     *   • MAX_INTERIOR on all inner cells.
     */
    private static void buildAndPrintSolution(int[][] grid, int n, int m) {
        // Place the required values on the borders
        grid[0][0] = MAX_CORNER;
        grid[0][m - 1] = MAX_CORNER;
        grid[n - 1][0] = MAX_CORNER;
        grid[n - 1][m - 1] = MAX_CORNER;

        for (int i = 1; i < n - 1; i++) {
            grid[i][0] = MAX_EDGE;
            grid[i][m - 1] = MAX_EDGE;
        }
        for (int j = 1; j < m - 1; j++) {
            grid[0][j] = MAX_EDGE;
            grid[n - 1][j] = MAX_EDGE;
        }

        for (int i = 1; i < n - 1; i++) {
            for (int j = 1; j < m - 1; j++) {
                grid[i][j] = MAX_INTERIOR;
            }
        }

        // Output the resulting matrix
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                System.out.print(grid[i][j] + " ");
            }
            System.out.println();
        }
    }
}

import java.util.Scanner;

/**
 * Utility that reads test cases, validates neighbour‑grid matrices and,
 * when valid, prints the transformed matrix.
 */
public class NeighbourGrid {

    private static final String YES = "YES";
    private static final String NO  = "NO";

    public static void main(String[] args) {
        // Try‑with‑resources guarantees the scanner is closed automatically.
        try (Scanner scanner = new Scanner(System.in)) {

            int testCases = readInt(scanner,
                    "Number of test cases",
                    () -> Integer.parseInt(scanner.nextLine()));

            while (testCases-- > 0) {
                // ----- read matrix dimensions -------------------------------------------------
                String[] dims = scanner.nextLine().split("\\s+");
                int rows = Integer.parseInt(dims[0]);
                int cols = Integer.parseInt(dims[1]);

                // ----- read the matrix ---------------------------------------------------------
                int[][] matrix = readMatrix(scanner, rows, cols);

                // ----- validate and (if needed) output -----------------------------------------
                processMatrix(matrix);
            }
        }
    }

    /** Reads a whole matrix of the given size from the scanner. */
    private static int[][] readMatrix(Scanner scanner, int rows, int cols) {
        int[][] matrix = new int[rows][cols];
        for (int r = 0; r < rows; r++) {
            String line = scanner.nextLine();
            String[] tokens = line.split("\\s+");
            if (tokens.length != cols) {
                throw new IllegalArgumentException(
                        "Expected " + cols + " numbers on line " + (r + 1) +
                        " but got " + tokens.length);
            }
            for (int c = 0; c < cols; c++) {
                matrix[r][c] = Integer.parseInt(tokens[c]);
            }
        }
        return matrix;
    }

    /** Checks whether the matrix respects the neighbour‑grid constraints. */
    private static boolean isInvalid(int[][] matrix) {
        int rows = matrix.length;
        int cols = matrix[0].length;

        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                int maxAllowed = allowedValue(r, c, rows, cols);
                if (matrix[r][c] > maxAllowed) {
                    return true;
                }
            }
        }
        return false;
    }

    /** Returns the maximal allowed value for a cell at (row, col). */
    private static int allowedValue(int row, int col, int rows, int cols) {
        boolean topRow    = row == 0;
        boolean bottomRow = row == rows - 1;
        boolean leftCol   = col == 0;
        boolean rightCol  = col == cols - 1;

        // corners → max 2
        if ((topRow && leftCol)   || (topRow && rightCol) ||
            (bottomRow && leftCol) || (bottomRow && rightCol)) {
            return 2;
        }

        // edges (but not corners) → max 3
        if (topRow || bottomRow || leftCol || rightCol) {
            return 3;
        }

        // interior cells → max 4
        return 4;
    }

    /** Creates the result matrix where each cell holds its allowed maximum value. */
    private static int[][] createResultMatrix(int[][] original) {
        int[][] result = new int[original.length][original[0].length];
        for (int r = 0; r < original.length; r++) {
            for (int c = 0; c < original[0].length; c++) {
                result[r][c] = allowedValue(r, c,
                        original.length, original[0].length);
            }
        }
        return result;
    }

    /** Prints the matrix, one row per line, numbers separated by a single space. */
    private static void printMatrix(int[][] matrix) {
        for (int[] row : matrix) {
            for (int value : row) {
                System.out.print(value + " ");
            }
            System.out.println();
        }
    }

    /** Executes the validation and output for a given matrix. */
    private static void processMatrix(int[][] matrix) {
        if (isInvalid(matrix)) {
            System.out.println(NO);
            return;
        }

        System.out.println(YES);
        int[][] result = createResultMatrix(matrix);
        printMatrix(result);
    }

    /** Small helper to read an int from the scanner – kept for possible future extension. */
    private static int readInt(Scanner scanner, String prompt,
                               java.util.function.Supplier<Integer> reader) {
        return reader.get();
    }
}

import java.util.Scanner;

/**
 * Refactored solution that reads a grid, checks whether the values satisfy
 * the required minimum (2 on corners, 3 on edges, 4 inside) and either
 * prints "NO" or prints "YES" together with the required values.
 *
 * The implementation focuses on readability, proper resource handling and
 * separation of concerns.
 */
public class Main {

    /** Minimum values that each cell type must have. */
    private static final int CORNER_MIN = 2;
    private static final int EDGE_MIN   = 3;
    private static final int INNER_MIN  = 4;

    public static void main(String[] args) throws Exception {
        // Try‑with‑resources guarantees that the Scanner is closed.
        try (Scanner sc = new Scanner(System.in)) {
            StringBuilder output = new StringBuilder();

            int t = sc.nextInt();                     // number of test cases
            while (t-- > 0) {
                int n = sc.nextInt();                   // rows
                int m = sc.nextInt();                   // columns
                int[][] grid = new int[n][m];
                readGrid(sc, grid);

                boolean possible = true;
                int[][] result = new int[n][m];

                for (int i = 0; i < n && possible; i++) {
                    for (int j = 0; j < m; j++) {
                        int required = requiredValue(i, n, j, m);
                        if (grid[i][j] > required) {
                            possible = false;          // value too large → impossible
                        }
                        result[i][j] = required;       // store the value we will output
                    }
                }

                if (!possible) {
                    output.append("NO\n");
                } else {
                    output.append("YES\n");
                    appendGrid(result, output);
                }
            }

            System.out.print(output.toString());
        }
    }

    /**
     * Reads the whole grid from the given scanner.
     */
    private static void readGrid(Scanner sc, int[][] grid) {
        int n = grid.length;
        int m = grid[0].length;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                grid[i][j] = sc.nextInt();
            }
        }
    }

    /**
     * Determines the required minimum value for the cell at (i, j) based on its
     * position in an {@code n × m} grid.
     *
     * @return CORNER_MIN for corners, EDGE_MIN for edges, INNER_MIN otherwise.
     */
    private static int requiredValue(int i, int n, int j, int m) {
        // corner (intersection of first/last row and first/last column)
        if ((i == 0 || i == n - 1) && (j == 0 || j == m - 1)) {
            return CORNER_MIN;
        }
        // any other cell on the border
        if (i == 0 || i == n - 1 || j == 0 || j == m - 1) {
            return EDGE_MIN;
        }
        // interior cell
        return INNER_MIN;
    }

    /**
     * Appends the formatted grid to the supplied {@link StringBuilder}.
     */
    private static void appendGrid(int[][] grid, StringBuilder out) {
        int n = grid.length;
        int m = grid[0].length;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                out.append(grid[i][j]);
                if (j < m - 1) {
                    out.append(' ');
                }
            }
            out.append('\n');
        }
    }
}

/**
 * Refactored version of the original “B” program.
 * <p>
 * The program reads test cases from a file named "<SimpleClassName>.in" if it exists,
 * otherwise from standard input. It writes either to a file whose name is stored in
 * {@code OUTPUT_NAME} or to standard output.
 * <p>
 * Functionality is unchanged:
 * <ul>
 *   <li>It validates border constraints for each cell.</li>
 *   <li>It expands the grid by filling neighbouring empty cells with {@code 1}
 *       until each positive cell meets its required count.</li>
 *   <li>If a cell ends up with more required neighbours than available, its
 *       value is reduced to that count.</li>
 *   <li>When the process stabilises, it prints “YES” (or “NO”) and, for “YES”
 *       cases, the final grid.</li>
 * </ul>
 *
 * The refactor focuses on readability, encapsulation, and maintainability:
 * <ul>
 *   <li>Constants and I/O handling are centralized.</li>
 *   <li>Border‑validation logic is extracted to {@code isAllowed}.</li>
 *   <li>Neighbour‑direction handling uses an {@code enum} instead of magic
 *       integers.</li>
 *   <li>Core algorithm steps are broken into small, well‑named methods.</li>
 *   <li>All mutable state is confined to the method that needs it.</li>
 * </ul>
 */
public class B {

    /** Input file name (if it exists). */
    private static final String INPUT_NAME = B.class.getSimpleName() + ".in";

    /** Optional output file name; {@code null} means write to console. */
    private static final String OUTPUT_NAME = null;

    /** Entry point. */
    public static void main(String[] args) throws IOException {
        new B().solve();
    }

    /** Orchestrates reading, processing, and writing of all test cases. */
    private void solve() throws IOException {
        // Open the appropriate input and output streams.
        try (InputStream in = openInput();
             BufferedReader reader = new BufferedReader(new InputStreamReader(in));
             PrintWriter out = openOutput()) {

            process(reader, out);
        }
    }

    /** Returns {@code System.in} if the default input file does not exist,
     * otherwise opens that file. */
    private InputStream openInput() {
        File file = new File(INPUT_NAME);
        return file.exists() ? file : System.in;
    }

    /** Returns a {@code PrintWriter} that writes to the optional output file
     * or to {@code System.out}. */
    private PrintWriter openOutput() throws FileNotFoundException {
        return OUTPUT_NAME != null ? new PrintWriter(OUTPUT_NAME) : new PrintWriter(System.out);
    }

    /** Reads all test cases and delegates the solving of each to {@code solveCase}. */
    private void process(BufferedReader br, PrintWriter pw) throws IOException {
        int cases = Integer.parseInt(br.readLine().trim());

        for (int caseIdx = 0; caseIdx < cases; caseIdx++) {
            int[] dims = parseInts(br.readLine());
            int n = dims[0];
            int m = dims[1];
            int[][] grid = new int[n][];
            for (int i = 0; i < n; i++) {
                grid[i] = parseInts(br.readLine());
            }

            boolean possible = solveCase(n, m, grid);
            if (possible) {
                pw.println("YES");
                // Output the final board exactly as the original program did.
                for (int i = 0; i < n; i++) {
                    pw.println(
                            Arrays.stream(grid[i])
                                    .mapToObj(Integer::toString)
                                    .collect(Collectors.joining(" "))
                    );
                }
            } else {
                pw.println("NO");
            }
        }
    }

    /** Parses a line of whitespace‑separated integers. */
    private static int[] parseInts(String line) {
        return Arrays.stream(line.trim().split("\\s+"))
                .mapToInt(Integer::parseInt)
                .toArray();
    }

    /**
     * Core solving routine.
     * <p>
     * Repeatedly adjusts the grid until no further changes are required or a
     * border constraint is violated.
     *
     * @return {@code true} if the board can be completed according to the rules.
     */
    private boolean solveCase(int n, int m, int[][] grid) {
        boolean changed;
        do {
            changed = false;
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    if (!isAllowed(grid[i][j], i, j, n, m)) {
                        return false; // violates a border constraint
                    }
                    if (grid[i][j] > 0) {
                        adjustNeighbours(i, j, grid);
                        changed = true;
                    }
                }
            }
        } while (changed);
        return true;
    }

    /** Checks border constraints for a given cell. */
    private boolean isAllowed(int value, int i, int j, int n, int m) {
        if ((i == 0 || i == n - 1) && (j == 0 || j == m - 1)) {
            return value <= 2;
        }
        if (i == 0 || i == n - 1 || j == 0 || j == m - 1) {
            return value <= 3;
        }
        return value <= 4;
    }

    /**
     * Ensures that every positive cell has exactly the required number of
     * non‑zero neighbours.  Empty neighbours are filled with {@code 1} until the
     * count matches the required amount; if there are too many neighbours, the
     * cell's value is reduced to that count.
     */
    private void adjustNeighbours(int i, int j, int[][] grid) {
        List<Direction> needed = collectNeededDirections(i, j, grid);
        int currentCount = needed.size();

        if (currentCount < grid[i][j]) {
            // Need more neighbours – fill the first missing ones.
            for (int k = 0; k < grid[i][j] - currentCount; k++) {
                setCell(grid, needed.get(k), i, j, 1);
            }
        } else if (currentCount > grid[i][j]) {
            // Too many neighbours – shrink the cell's value.
            grid[i][j] = currentCount;
        }
    }

    /** Returns a list of directions (up, left, down, right) that point to empty cells. */
    private List<Direction> collectNeededDirections(int i, int j, int[][] grid) {
        List<Direction> dirs = new ArrayList<>();
        if (i - 1 >= 0 && grid[i - 1][j] == 0) dirs.add(Direction.UP);
        if (j - 1 >= 0 && grid[i][j - 1] == 0) dirs.add(Direction.LEFT);
        if (i + 1 < grid.length && grid[i + 1][j] == 0) dirs.add(Direction.DOWN);
        if (j + 1 < grid[0].length && grid[i][j + 1] == 0) dirs.add(Direction.RIGHT);
        return dirs;
    }

    /** Sets the neighbour in the given {@link Direction} to {@code val}. */
    private void setCell(int[][] grid, Direction dir, int i, int j, int val) {
        switch (dir) {
            case UP -> grid[i - 1][j] = val;
            case LEFT -> grid[i][j - 1] = val;
            case DOWN -> grid[i + 1][j] = val;
            case RIGHT -> grid[i][j + 1] = val;
        }
    }

    /** Simple identifier for the four compass directions. */
    private enum Direction {
        UP, LEFT, DOWN, RIGHT
    }
}

import java.io.*;
import java.util.*;

/**
 * Solves the “Neighbour‑Grid” problem.
 *
 * The algorithm works as follows:
 *   1. Read the number of test cases.
 *   2. For each test case read a matrix (m × n).
 *   3. Verify that every element respects the maximum allowed value
 *      for its position:
 *          • corner  → max 2
 *          • edge    → max 3
 *          • interior→ max 4
 *   4. If all elements are valid print “YES” and output a matrix that
 *      contains exactly those maximal values at every position.
 *      Otherwise print “NO”.
 *
 * The code is split into small, self‑contained helper classes so that
 * responsibilities are clearly separated and the program is easy to
 * maintain or extend.
 */
public class Main {

    /* --------------------------------------------------------------------- *
     *  Input handling
     * --------------------------------------------------------------------- */
    /** Fast scanner that works with any {@link InputStream}. */
    private static final class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner(InputStream in) {
            this.br = new BufferedReader(new InputStreamReader(in));
        }

        /** Returns the next token, reading a new line if necessary. */
        private String nextToken() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                st = new StringTokenizer(br.readLine());
            }
            return st.nextToken();
        }

        /** Convenience wrappers for primitive types. */
        int nextInt() throws IOException {
            return Integer.parseInt(nextToken());
        }

        long nextLong() throws IOException {
            return Long.parseLong(nextToken());
        }
    }

    /* --------------------------------------------------------------------- *
     *  Position classification
     * --------------------------------------------------------------------- */
    /** Describes where a cell lies inside the matrix. */
    private enum Position {
        CORNER {
            @Override int allowedMax(int rows, int cols) {
                return 2;
            }
        },
        EDGE {
            @Override int allowedMax(int rows, int cols) {
                return 3;
            }
        },
        INTERIOR {
            @Override int allowedMax(int rows, int cols) {
                return 4;
            }
        };

        /** Determines the maximal value allowed at a given coordinate. */
        abstract int allowedMax(int rows, int cols);
    }

    /** Helper that knows how to classify a cell. */
    private static final class PositionClassifier {
        /** Returns the enum value describing the cell's position. */
        static Position classify(int row, int col, int rows, int cols) {
            boolean isTopOrBottom = row == 0 || row == rows - 1;
            boolean isLeftOrRight = col == 0 || col == cols - 1;

            if (isTopOrBottom && isLeftOrRight) {
                return Position.CORNER;
            } else if (isTopOrBottom || isLeftOrRight) {
                return Position.EDGE;
            } else {
                return Position.INTERIOR;
            }
        }
    }

    /* --------------------------------------------------------------------- *
     *  Grid validation & construction
     * --------------------------------------------------------------------- */
    /** Holds a single test‑case's data and all operations on it. */
    private static final class GridProcessor {
        private final int rows;
        private final int cols;
        private final int[][] values;
        private final int[][] expected; // matrix we will output when YES

        GridProcessor(int rows, int cols) {
            this.rows = rows;
            this.cols = cols;
            this.values = new int[rows][cols];
            this.expected = new int[rows][cols];
        }

        /** Reads the matrix from the supplied scanner. */
        void readValues(FastScanner fs) throws IOException {
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    values[r][c] = fs.nextInt();
                }
            }
        }

        /** Checks whether every element respects its position‑dependent limit. */
        boolean isValid() {
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    int limit = PositionClassifier.classify(r, c, rows, cols)
                               .allowedMax(rows, cols);
                    if (values[r][c] > limit) {
                        return false;
                    }
                }
            }
            return true;
        }

        /** Fills {@code expected} with the maximal allowed value for each cell. */
        void fillExpected() {
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    expected[r][c] = PositionClassifier.classify(r, c, rows, cols)
                                   .allowedMax(rows, cols);
                }
            }
        }

        /** Prints the expected matrix to the supplied writer. */
        void printTo(PrintWriter out) {
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    out.print(expected[r][c]);
                    if (c < cols - 1) {
                        out.print(' ');
                    }
                }
                out.println();
            }
        }
    }

    /* --------------------------------------------------------------------- *
     *  Main driver
     * --------------------------------------------------------------------- */
    public static void main(String[] args) throws Exception {
        /* Use try‑with‑resources to guarantee proper closure of streams. */
        try (FastScanner scanner = new FastScanner(System.in);
             PrintWriter out = new PrintWriter(
                     new BufferedWriter(new OutputStreamWriter(System.out)))) {

            int tests = scanner.nextInt();

            StringBuilder overallOutput = new StringBuilder();

            for (int t = 0; t < tests; t++) {
                int m = scanner.nextInt();
                int n = scanner.nextInt();
                GridProcessor grid = new GridProcessor(m, n);
                grid.readValues(scanner);

                if (grid.isValid()) {
                    overallOutput.append("YES\n");
                    grid.fillExpected();
                    grid.printTo(out);
                } else {
                    overallOutput.append("NO\n");
                }
            }

            out.print(overallOutput.toString());
            out.flush();          // ensure all data is sent before closing
        }
    }
}

/* ----------------------------------------------------------------------
 *  Refactored solution for the "Matrix validity" problem.
 *
 *  The program reads several test cases, each consisting of an n × m grid.
 *  For every non‑zero cell it checks that the cell value does not exceed the
 *  maximal possible number of neighbours.  Cells whose value differs from the
 *  neighbour count are stored for later adjustment.  Zero cells adjacent to
 *  such cells are filled with their own neighbour count until the required
 *  amount is reached.  Finally every non‑zero cell is replaced by the number
 *  of its non‑zero neighbours.
 *
 *  The refactor focuses on readability, maintainability and correctness:
 *    • Meaningful identifiers and Javadoc comments
 *    • Small, single‑purpose helper methods
 *    • Extraction of auxiliary data structures (Direction, Adjustment)
 *    • Proper resource handling for the fast scanner
 *    • Removed duplicated logic and magic numbers
 * ---------------------------------------------------------------------- */

import java.io.DataInputStream;
import java.io.IOException;
import java.util.ArrayList;
import java.util.List;

public class Main {

    /* ------------------------------------------------------------------
     *  Directions: right, left, down, up
     * ------------------------------------------------------------------ */
    private static final int[][] DIRS = {{0, 1}, {0, -1}, {1, 0}, {-1, 0}};

    /** Checks whether (x, y) lies inside a matrix of size rows × cols. */
    private static boolean isInBounds(int x, int y, int rows, int cols) {
        return x >= 0 && x < rows && y >= 0 && y < cols;
    }

    /**
     * Returns how many of the four orthogonal neighbours of (x, y) contain a
     * non‑zero value.
     */
    private static int countNeighbouringNonZero(int[][] grid, int x, int y) {
        int cnt = 0;
        for (int[] d : DIRS) {
            int nx = x + d[0];
            int ny = y + d[1];
            if (isInBounds(nx, ny, grid.length, grid[0].length)
                    && grid[nx][ny] > 0) {
                ++cnt;
            }
        }
        return cnt;
    }

    /** Simple container for a cell that needs to be adjusted later. */
    private static final class Adjustment {
        final int x, y;
        final int requiredCount;

        Adjustment(int x, int y, int requiredCount) {
            this.x = x;
            this.y = y;
            this.requiredCount = requiredCount;
        }
    }

    /* ------------------------------------------------------------------
     *  Entry point – reads all test cases, processes each one and writes the
     *  result to standard output.
     * ------------------------------------------------------------------ */
    public static void main(String[] args) throws IOException {
        /* Try‑with‑resources guarantees that the scanner is closed. */
        try (Reader scanner = new Reader()) {
            StringBuilder output = new StringBuilder();

            int tests = scanner.nextInt();
            while (tests-- > 0) {
                int n = scanner.nextInt();
                int m = scanner.nextInt();
                int[][] grid = new int[n][m];

                for (int i = 0; i < n; ++i) {
                    for (int j = 0; j < m; ++j) {
                        grid[i][j] = scanner.nextInt();
                    }
                }

                /* If the case is valid we will later print "YES" and the final grid. */
                if (processCase(grid)) {
                    output.append("YES\n");
                    for (int i = 0; i < n; ++i) {
                        for (int j = 0; j < m; ++j) {
                            output.append(grid[i][j]).append(' ');
                        }
                        output.append('\n');
                    }
                }
            }

            System.out.print(output.toString());
        }
    }

    /**
     * Executes the validation / adjustment algorithm for a single test case.
     *
     * @return {@code true} if the case is valid and must be printed as "YES",
     *         {@code false} if the case is invalid (print "NO").
     */
    private static boolean processCase(int[][] grid) {
        int rows = grid.length;
        int cols = grid[0].length;

        /* --------------------------------------------------------------
         *  1️⃣  Validation and collection of cells that need adjustment.
         * -------------------------------------------------------------- */
        List<Adjustment> adjustments = new ArrayList<>();
        boolean invalid = false;

        for (int i = 0; i < rows && !invalid; ++i) {
            for (int j = 0; j < cols; ++j) {
                if (grid[i][j] == 0) {
                    continue;
                }

                int maxPossible = 0;      // maximal neighbours a cell can have
                int actualNonZero = 0;    // neighbours that are currently non‑zero

                for (int[] d : DIRS) {
                    int ni = i + d[0];
                    int nj = j + d[1];
                    if (isInBounds(ni, nj, rows, cols)) {
                        ++maxPossible;
                        if (grid[ni][nj] > 0) {
                            ++actualNonZero;
                        }
                    }
                }

                /* If a cell's value exceeds the maximal possible neighbours,
                 * the whole test case is impossible. */
                if (grid[i][j] > maxPossible) {
                    invalid = true;
                    break;
                }

                /* Store cells whose current value does NOT equal the neighbour count. */
                if (grid[i][j] != actualNonZero) {
                    adjustments.add(new Adjustment(i, j, actualNonZero));
                }
            }
        }

        if (invalid) {
            System.out.print("NO\n");          // mandatory output for the judge
            return false;
        }

        /* --------------------------------------------------------------
         *  2️⃣  Fill missing neighbour‑counts into adjacent zero cells.
         * -------------------------------------------------------------- */
        for (Adjustment adj : adjustments) {
            int x = adj.x;
            int y = adj.y;
            int required = adj.requiredCount;

            if (grid[x][y] == required) {
                continue;                      // already correct
            }

            int remaining = required - grid[x][y];
            if (remaining <= 0) {
                continue;
            }

            /* Try to satisfy the remaining amount by assigning neighbour counts
             * to adjacent zero cells. */
            for (int[] d : DIRS) {
                int nx = x + d[0];
                int ny = y + d[1];
                if (!isInBounds(nx, ny, rows, cols) || grid[nx][ny] != 0) {
                    continue;
                }

                int fillValue = countNeighbouringNonZero(grid, nx, ny);
                grid[nx][ny] = fillValue;
                --remaining;
                if (remaining == 0) {
                    break;
                }
            }
        }

        /* --------------------------------------------------------------
         *  3️⃣  Final pass – replace every non‑zero cell by its neighbour count.
         * -------------------------------------------------------------- */
        for (int i = 0; i < rows; ++i) {
            for (int j = 0; j < cols; ++j) {
                if (grid[i][j] != 0) {
                    grid[i][j] = countNeighbouringNonZero(grid, i, j);
                }
            }
        }

        return true;
    }

    /* ------------------------------------------------------------------
     *  Fast scanner that works with standard input.
     * ------------------------------------------------------------------ */
    private static final class Reader implements AutoCloseable {
        private final DataInputStream din;
        private final byte[] buffer;
        private int bufferPointer = 0, bytesRead = 0;

        Reader() throws IOException {
            this(new DataInputStream(System.in));
        }

        Reader(DataInputStream din) {
            this.din = din;
            buffer = new byte[1 << 16];
        }

        private byte read() throws IOException {
            if (bufferPointer == bytesRead) {
                fillBuffer();
            }
            return bufferPointer < bytesRead ? buffer[bufferPointer++] : (byte) -1;
        }

        private void fillBuffer() throws IOException {
            bytesRead = din.read(buffer);
            bufferPointer = 0;
            if (bytesRead == -1) {
                buffer[0] = -1;
            }
        }

        /** Reads the next integer from the input. */
        int nextInt() throws IOException {
            int sign = 1;
            int c;
            do {
                c = read();
            } while (c <= ' ');
            if (c == '-') {
                sign = -1;
                c = read();
            }
            int result = 0;
            while (c > ' ') {
                result = result * 10 + (c - '0');
                c = read();
            }
            return sign * result;
        }

        @Override
        public void close() throws IOException {
            if (din != null) {
                din.close();
            }
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.PrintWriter;
import java.util.StringTokenizer;

/**
 * Main entry point of the application.
 * The program reads multiple test cases, validates constraints on a matrix,
 * and either outputs "NO" or prints a predefined pattern for valid cases.
 */
public class Main {

    /* --------------------------------------------------------------------- */
    /*  Configuration constants – change them in a single place if needed   */
    /* --------------------------------------------------------------------- */
    private static final int CORNER_THRESHOLD = 3;   // allowed value in corners
    private static final int EDGE_THRESHOLD   = 3;   // allowed value on edges (excluding corners)
    private static final int INTERIOR_THRESHOLD = 4; // allowed value inside the matrix

    private static final PrintWriter OUT = new PrintWriter(System.out, true);

    public static void main(String[] args) {
        // try‑with‑resources guarantees proper closing of the scanner
        try (FastScanner scanner = new FastScanner()) {
            int t = scanner.nextInt();                     // number of test cases
            for (int test = 0; test < t; test++) {
                int n = scanner.nextInt();
                int m = scanner.nextInt();
                int[][] grid = new int[n][m];
                boolean possible = true;

                // read the matrix while checking constraints on‑the‑fly
                for (int i = 0; i < n && possible; i++) {
                    for (int j = 0; j < m; j++) {
                        grid[i][j] = scanner.nextInt();

                        if (isCorner(i, j, n, m)) {
                            if (grid[i][j] >= CORNER_THRESHOLD) {
                                possible = false;
                            }
                        } else if (isEdge(i, j, n, m)) {
                            if (grid[i][j] > EDGE_THRESHOLD) {
                                possible = false;
                            }
                        } else {
                            if (grid[i][j] > INTERIOR_THRESHOLD) {
                                possible = false;
                            }
                        }
                    }
                }

                // produce the required output
                if (!possible) {
                    OUT.println("NO");
                } else {
                    solve(grid, n, m);
                }
            }
        }
        OUT.flush();   // ensure all output is emitted before the program ends
    }

    /* --------------------------------------------------------------------- */
    /*  Helper methods                                                         */
    /* --------------------------------------------------------------------- */

    /** Determines whether the cell (i, j) is a corner of the matrix. */
    private static boolean isCorner(int i, int j, int n, int m) {
        return (i == 0 && j == 0) ||
               (i == n - 1 && j == 0) ||
               (i == n - 1 && j == m - 1) ||
               (i == 0 && j == m - 1);
    }

    /** Determines whether the cell (i, j) lies on the border but is not a corner. */
    private static boolean isEdge(int i, int j, int n, int m) {
        return i == 0 || i == n - 1 || j == 0 || j == m - 1;
    }

    /**
     * Prints a predefined numeric pattern based on the cell's position.
     * This reproduces the original program's output when a valid matrix is supplied.
     */
    private static void solve(int[][] grid, int n, int m) {
        OUT.println("YES");
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (isCorner(i, j, n, m)) {
                    OUT.print(CORNER_THRESHOLD + " ");
                } else if (isEdge(i, j, n, m)) {
                    OUT.print(EDGE_THRESHOLD + " ");
                } else {
                    OUT.print(INTERIOR_THRESHOLD + " ");
                }
            }
            OUT.println();
        }
    }

    /* --------------------------------------------------------------------- */
    /*  FastScanner – a lightweight wrapper around BufferedReader            */
    /* --------------------------------------------------------------------- */
    private static class FastScanner implements AutoCloseable {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        /** Returns the next token from standard input. */
        String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    throw new UncheckedIOException(e);
                }
            }
            return st.nextToken();
        }

        /** Convenience methods for common primitive types. */
        int nextInt()   { return Integer.parseInt(next()); }
        long nextLong() { return Long.parseLong(next()); }
        double nextDouble() { return Double.parseDouble(next()); }
        String nextLine() {
            try {
                return br.readLine();
            } catch (IOException e) {
                throw new UncheckedIOException(e);
            }
        }

        /** Close the underlying reader – invoked automatically by try‑with‑resources. */
        @Override
        public void close() throws IOException {
            br.close();
        }
    }
}

import java.io.*;
import java.util.*;

public class Main {

    // -------------------------------------------------------------------------
    // Constants describing the maximum allowed value for each cell type
    // -------------------------------------------------------------------------
    private static final int CORNER_MAX   = 2;
    private static final int EDGE_MAX     = 3;
    private static final int INNER_MAX    = 4;

    /** Entry point – reads input, processes each test case and writes output. */
    public static void main(String[] args) {
        try (OutputWriter out = new OutputWriter(System.out)) {
            new Solver(out).run();
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
    }

    /** -----------------------------------------------------------------------
     *  Solver – coordinates the whole program flow:
     *   1. Reads the number of test cases.
     *   2. For each case reads dimensions and the raw grid.
     *   3. Delegates to GridAdjuster.
     *   4. Prints “NO” if adjustment fails, otherwise “YES” and the new grid.
     *  ----------------------------------------------------------------------- */
    static class Solver {
        private final InputReader in;
        private final OutputWriter out;

        Solver(OutputWriter out) {
            this.out = out;
            this.in = new InputReader(System.in);
        }

        void run() {
            int tests = in.nextInt();
            while (tests-- > 0) {
                processSingleTestCase();
            }
        }

        private void processSingleTestCase() {
            int rows = in.nextInt();
            int cols = in.nextInt();
            int[][] original = in.readMatrix(rows, cols);

            GridAdjuster adjuster = new GridAdjuster(rows, cols, original);
            int[][] adjusted = adjuster.adjust();

            if (adjusted == null) {
                out.println("NO");
            } else {
                out.println("YES");
                out.printMatrix(adjusted);
            }
        }
    }

    /** -----------------------------------------------------------------------
     *  GridAdjuster – encapsulates all per‑cell logic:
     *   • Determines the target value based on the cell’s location.
     *   • Validates that the original value does not exceed that target.
     *   • Returns a new matrix or `null` when validation fails.
     *  ----------------------------------------------------------------------- */
    static class GridAdjuster {
        private final int rows;
        private final int cols;
        private final int[][] original;

        GridAdjuster(int rows, int cols, int[][] original) {
            this.rows = rows;
            this.cols = cols;
            this.original = original;
        }

        /** Returns a fully‑filled, validated matrix, or `null` if any rule is broken. */
        int[][] adjust() {
            int[][] result = new int[rows][cols];

            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    result[r][c] = valueForCell(r, c);
                    if (!isValid(original[r][c], result[r][c])) {
                        return null;               // early exit on failure
                    }
                }
            }
            return result;
        }

        /** The value that must be placed at (r, c) according to the problem rules. */
        private int valueForCell(int r, int c) {
            if (isCorner(r, c)) {
                return CORNER_MAX;
            }
            if (isEdge(r, c)) {
                return EDGE_MAX;
            }
            return INNER_MAX;                     // interior cell
        }

        /** Checks whether the original entry can be replaced by `target`. */
        private boolean isValid(int originalValue, int target) {
            // The only rule enforced by the original code was “original ≤ target”.
            return originalValue <= target;
        }

        /** Returns true for the four corners of the matrix. */
        private boolean isCorner(int r, int c) {
            return (r == 0 && c == 0) ||
                   (r == rows - 1 && c == cols - 1) ||
                   (r == rows - 1 && c == 0) ||
                   (r == 0 && c == cols - 1);
        }

        /** Returns true for non‑corner edge cells. */
        private boolean isEdge(int r, int c) {
            return (r == 0 || r == rows - 1 || c == 0 || c == cols - 1)
                   && !isCorner(r, c);
        }

        /** Utility – fill the provided OutputWriter with a matrix representation. */
        static void printMatrix(OutputWriter out, int[][] matrix) {
            for (int[] row : matrix) {
                for (int val : row) {
                    out.print(val + " ");
                }
                out.println();
            }
        }
    }

    /** -----------------------------------------------------------------------
     *  InputReader – fast token based scanner.
     *  ----------------------------------------------------------------------- */
    static class InputReader {
        private final InputStream stream;
        private final byte[] buffer = new byte[16 * 1024];
        private int ptr = 0, len = 0;

        InputReader(InputStream stream) {
            this.stream = stream;
        }

        private int readByte() throws IOException {
            if (len <= ptr) {
                len = stream.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() {
            int c = skipNonDigits();
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = readByte();
            }
            int value = 0;
            while (c >= '0' && c <= '9') {
                value = value * 10 + (c - '0');
                c = readByte();
            }
            return value * sign;
        }

        private int skipNonDigits() throws IOException {
            int c;
            do {
                c = readByte();
            } while (c <= ' ');
            return c;
        }

        /** Reads a whole matrix of the given size using the same token semantics. */
        int[][] readMatrix(int rows, int cols) {
            int[][] matrix = new int[rows][cols];
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    matrix[i][j] = nextInt();
                }
            }
            return matrix;
        }
    }

    /** -----------------------------------------------------------------------
     *  OutputWriter – thin wrapper around PrintWriter that supplies convenient
     *                 printing helpers.
     *  ----------------------------------------------------------------------- */
    static class OutputWriter {
        private final PrintWriter writer;

        OutputWriter(OutputStream out) {
            writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(out)));
        }

        void print(Object... objects) {
            for (int i = 0; i < objects.length; i++) {
                if (i != 0) writer.print(' ');
                writer.print(objects[i]);
            }
        }

        void println(Object... objects) {
            print(objects);
            writer.println();
        }

        void close() {
            writer.close();
        }
    }
}

import java.util.Scanner;

/**
 * Refactored version of BGR9 that reads matrices, validates and normalizes their values,
 * then prints "YES" together with the normalized matrix or "NO" if validation fails.
 *
 * Changes made for maintainability and readability:
 *   • Meaningful constant names for the different maximum thresholds.
 *   • Small helper methods instead of nested loops with mutable flags.
 *   • Try‑with‑resources for the Scanner to guarantee proper closing.
 *   • Descriptive variable and method names.
 *   • Separation of concerns (reading, validation, printing).
 */
public class Solution {

    /* -------------------------------------------------------------------------
     *  Threshold constants – these express the intent of the original magic numbers.
     * ------------------------------------------------------------------------- */
    private static final int CORNER_MAX = 2;   // corners (four cells) must be ≤ 2
    private static final int EDGE_MAX   = 3;   // non‑corner border cells must be ≤ 3
    private static final int INNER_MAX  = 4;   // inner cells must be ≤ 4

    public static void main(String[] args) {
        /* --------------------------------------------------------------
         *  Input handling – try‑with‑resources ensures the scanner is closed.
         * -------------------------------------------------------------- */
        try (Scanner scanner = new Scanner(System.in)) {
            int testCases = scanner.nextInt();
            while (testCases-- > 0) {
                int rows = scanner.nextInt();
                int cols = scanner.nextInt();

                long[][] matrix = new long[rows][cols];
                readMatrix(scanner, matrix);

                if (validateAndNormalize(matrix)) {
                    System.out.println("YES");
                    printMatrix(matrix);
                } else {
                    System.out.println("NO");
                }
            }
        }
    }

    /**
     * Reads a {@code rows × cols} matrix of {@code long} values from {@code scanner}.
     */
    private static long[][] readMatrix(Scanner scanner, long[][] matrix) {
        for (int i = 0; i < matrix.length; i++) {
            for (int j = 0; j < matrix[i].length; j++) {
                matrix[i][j] = scanner.nextLong();
            }
        }
        return matrix;
    }

    /**
     * Validates each cell of {@code grid} according to its position:
     *   • corners      → must be ≤ {@link #CORNER_MAX}
     *   • edges (non‑corner) → must be ≤ {@link #EDGE_MAX}
     *   • inner cells      → must be ≤ {@link #INNER_MAX}
     *
     * If a cell exceeds the allowed maximum the method returns {@code false}
     * and the grid is left unchanged. Otherwise the method normalizes the cell
     * to its allowed maximum and returns {@code true}.
     */
    private static boolean validateAndNormalize(long[][] grid) {
        int n = grid.length;
        int m = grid[0].length;

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                int allowedMax = determineAllowedMaximum(i, j, n, m);
                if (grid[i][j] > allowedMax) {
                    return false;
                }
                grid[i][j] = allowedMax; // normalize (same effect as original logic)
            }
        }
        return true;
    }

    /**
     * Returns the maximum value a cell at position {@code (i,j)} may have,
     * depending on whether it is a corner, an edge, or an inner cell.
     */
    private static int determineAllowedMaximum(int i, int j, int rows, int cols) {
        boolean isCorner = (i == 0 && j == 0) ||
                           (i == rows - 1 && j == cols - 1) ||
                           (i == rows - 1 && j == 0) ||
                           (i == 0 && j == cols - 1);
        if (isCorner) {
            return CORNER_MAX;
        }
        if (i == 0 || i == rows - 1 || j == 0 || j == cols - 1) {
            return EDGE_MAX;
        }
        return INNER_MAX;
    }

    /** Prints the given matrix row‑by‑row with a space after each value. */
    private static void printMatrix(long[][] matrix) {
        for (long[] row : matrix) {
            for (long value : row) {
                System.out.print(value + " ");
            }
            System.out.println();
        }
    }
}

import java.io.*;
import java.util.*;

public class Solution {

    /** Types of cells based on their position in the matrix. */
    private enum CellType {
        CORNER,        // corners of the matrix
        EDGE,          // edges but not corners
        INTERIOR       // all other cells
    }

    /** Maximum allowed value for each cell type. */
    private static final int MAX_CORNER   = 2;
    private static final int MAX_EDGE     = 3;
    private static final int MAX_INTERIOR = 4;

    /**
     * Determines the allowed maximum value for a cell at (row, col) in a matrix
     * of size {@code rows x cols}.
     */
    private static int allowedMax(int rows, int cols, int row, int col) {
        if ((row == 0 || row == rows - 1) && (col == 0 || col == cols - 1)) {
            return MAX_CORNER;
        }
        if (row == 0 || row == rows - 1 || col == 0 || col == cols - 1) {
            return MAX_EDGE;
        }
        return MAX_INTERIOR;
    }

    /**
     * Processes a single test case.
     *
     * @param br  BufferedReader used to read input
     * @param bw  BufferedWriter used to write output
     * @throws IOException if an I/O error occurs
     */
    private static void solveOneCase(BufferedReader br, BufferedWriter bw) throws IOException {
        // ---- read dimensions -------------------------------------------------
        String[] dims = br.readLine().split("\\s+");
        int rows = Integer.parseInt(dims[0]);
        int cols = Integer.parseInt(dims[1]);

        // ---- read matrix -----------------------------------------------------
        int[][] grid = new int[rows][cols];
        for (int i = 0; i < rows; i++) {
            String[] rowTokens = br.readLine().split("\\s+");
            for (int j = 0; j < cols; j++) {
                grid[i][j] = Integer.parseInt(rowTokens[j]);
            }
        }

        // ---- process each cell ------------------------------------------------
        boolean possible = true;
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                int allowed = allowedMax(rows, cols, i, j);

                if (grid[i][j] > allowed) {
                    possible = false;
                }
                // Overwrite with the allowed maximum as required by the specification
                grid[i][j] = allowed;
            }
        }

        // ---- output result ----------------------------------------------------
        if (possible) {
            bw.write("YES\n");
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    bw.write(grid[i][j] + (j == cols - 1 ? "" : " "));
                }
                bw.newLine();
            }
        } else {
            bw.write("NO\n");
        }
    }

    public static void main(String[] args) throws IOException {
        // Try‑with‑resources guarantees that the streams are closed properly.
        try (BufferedReader br = new BufferedReader(
                new InputStreamReader(System.in));
             BufferedWriter bw = new BufferedWriter(
                new OutputStreamWriter(System.out))) {

            int testCases = Integer.parseInt(br.readLine());

            for (int t = 0; t < testCases; t++) {
                solveOneCase(br, bw);
            }
        }
    }
}

