import java.io.*;
import java.util.*;

public class Main {

    /* ----------------------------------------------------------------
     *  Entry point
     * ---------------------------------------------------------------- */
    public static void main(String[] args) {
        solve();
        OUT.close();
    }

    /* ----------------------------------------------------------------
     *  Core logic
     * ---------------------------------------------------------------- */
    private static void solve() {
        int rows = scanner.nextInt();
        int cols = scanner.nextInt();

        int[][] grid = readGrid(rows, cols);
        validateAndPrepare(grid, rows, cols);

        StringBuilder builder = new StringBuilder();
        for (int[] row : grid) {
            for (int cell : row) {
                builder.append(cell).append(' ');
            }
            builder.append('\n');
        }

        OUT.println("YES");
        OUT.print(builder.toString());
    }

    /* ----------------------------------------------------------------
     *  Reads a rectangular grid of integers
     * ---------------------------------------------------------------- */
    private static int[][] readGrid(int rows, int cols) {
        int[][] grid = new int[rows][cols];
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                grid[r][c] = scanner.nextInt();
            }
        }
        return grid;
    }

    /* ----------------------------------------------------------------
     *  Validates each cell against its allowed maximum value.
     *  If a cell exceeds the limit, prints "NO" and returns.
     * ---------------------------------------------------------------- */
    private static void validateAndPrepare(int[][] grid, int rows, int cols) {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                int value = grid[r][c];
                int maxAllowed = getMaximumAllowed(r, c, rows, cols);
                if (value > maxAllowed) {
                    OUT.println("NO");
                    System.exit(0);
                }
                grid[r][c] = maxAllowed;
            }
        }
    }

    /* ----------------------------------------------------------------
     *  Determines the maximum allowed value for a given cell.
     *  Categories:
     *      • Corner   → 2
     *      • Edge (but not corner) → 3
     *      • Interior → 4
     * ---------------------------------------------------------------- */
    private static int getMaximumAllowed(int row, int col, int rows, int cols) {
        if (isCorner(row, col, rows, cols)) {
            return CORNER_MAX;
        }
        if (isEdge(row, col, rows, cols)) {
            return EDGE_MAX;
        }
        return INTERIOR_MAX;
    }

    /* ----------------------------------------------------------------
     *  Simple predicates to identify cell type
     * ---------------------------------------------------------------- */
    private static boolean isCorner(int r, int c, int rows, int cols) {
        return (r == 0 || r == rows - 1) && (c == 0 || c == cols - 1);
    }

    private static boolean isEdge(int r, int c, int rows, int cols) {
        return r == 0 || r == rows - 1 || c == 0 || c == cols - 1;
    }

    /* ----------------------------------------------------------------
     *  Constants – maximum allowed values for each cell category
     * ---------------------------------------------------------------- */
    private static final int CORNER_MAX   = 2;
    private static final int EDGE_MAX     = 3;
    private static final int INTERIOR_MAX = 4;

    /* ----------------------------------------------------------------
     *  Fast I/O helpers
     * ---------------------------------------------------------------- */
    private static final PrintWriter OUT = new PrintWriter(
            new BufferedOutputStream(System.out));
    private static final FastScanner scanner = new FastScanner();

    /* ----------------------------------------------------------------
     *  Very small, reusable scanner implementation
     * ---------------------------------------------------------------- */
    private static class FastScanner {
        private final BufferedReader br = new BufferedReader(
                new InputStreamReader(System.in));
        private StringTokenizer st = new StringTokenizer("");

        String next() {
            while (!st.hasMoreTokens()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.io.IOException;
import java.util.Scanner;

/**
 * Refactored solution for the CodeForces‑style grid transformation problem.
 */
public class Solution {

    /* -------------------------------------------------------------------------
     *  Constants that describe the maximum allowed value for each cell type.
     * ------------------------------------------------------------------------- */
    private static final int CORNER_MAX        = 2;   // cells at the four corners
    private static final int EDGE_MAX          = 3;   // cells on the border but not corners
    private static final int INNER_MAX         = 4;   // all interior cells

    public static void main(String[] args) throws IOException {
        /* -------------------------------------------------------------
         *  Read input safely using try‑with‑resources.
         * ------------------------------------------------------------- */
        try (Scanner scanner = new Scanner(System.in)) {
            int t = scanner.nextInt();

            while (t-- > 0) {
                int n = scanner.nextInt();
                int m = scanner.nextInt();
                int[][] grid = readGrid(scanner, n, m);

                boolean possible = validateAndTransform(grid, n, m);

                if (!possible) {
                    System.out.println("NO");
                } else {
                    System.out.println("YES");
                    printGrid(grid);
                }
            }
        }
    }

    /**
     * Reads an {@code n × m} integer grid from the scanner.
     */
    private static int[][] readGrid(Scanner scanner, int n, int m) {
        int[][] grid = new int[n][m];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                grid[i][j] = scanner.nextInt();
            }
        }
        return grid;
    }

    /**
     * Checks whether the current grid respects the transformation rules.
     * For each cell the new allowed maximum is computed; if the original value
     * exceeds that maximum the method returns {@code false}.
     *
     * @return {@code true} if the grid can be transformed, {@code false} otherwise.
     */
    private static boolean validateAndTransform(int[][] grid, int n, int m) {
        boolean possible = true;

        for (int i = 0; i < n && possible; i++) {
            for (int j = 0; j < m; j++) {
                int newMax = computeAllowedMaximum(i, j, n, m);
                if (grid[i][j] > newMax) {
                    possible = false;
                    break;          // no need to continue processing this test case
                }
                // Replace the value with the allowed maximum for later output
                grid[i][j] = newMax;
            }
        }
        return possible;
    }

    /**
     * Determines the allowed maximum value for a cell based on its position.
     *
     * @param i   row index
     * @param j   column index
     * @param n   total rows
     * @param m   total columns
     * @return    the maximum permissible value for the cell.
     */
    private static int computeAllowedMaximum(int i, int j, int n, int m) {
        // Corner cells (there are four of them)
        if ((i == 0 || i == n - 1) && (j == 0 || j == m - 1)) {
            return CORNER_MAX;
        }
        // Edge cells that are not corners
        if (i == 0 || i == n - 1 || j == 0 || j == m - 1) {
            return EDGE_MAX;
        }
        // Interior cells
        return INNER_MAX;
    }

    /** Prints the transformed grid row by row. */
    private static void printGrid(int[][] grid) {
        for (int[] row : grid) {
            for (int cell : row) {
                System.out.print(cell + " ");
            }
            System.out.println();
        }
    }
}

