/**
 * Refactored solution for the grid‑validation problem.
 *
 * <p>
 *   The program reads several test cases. For each test case it receives an {@code n × m}
 *   grid of integers. Each cell has a positional limit:
 *   <ul>
 *     <li>corner cells → at most 2</li>
 *     <li>edge (non‑corner) cells → at most 3</li>
 *     <li>interior cells → at most 4</li>
 *   </ul>
 *   If any input value exceeds its limit the whole test case is rejected (outputs {@code NO}),
 *   otherwise the grid is replaced by the maximal permissible values and printed prefixed
 *   with {@code YES}.
 * </p>
 *
 * <p>All input/output handling, validation and transformation logic are isolated into small
 * helper methods, making the code easier to read, test and maintain.</p>
 */
public class Main {

    /** Maximum value allowed for an interior cell. */
    private static final int INTERIOR_MAX = 4;
    /** Maximum value allowed for an edge (non‑corner) cell. */
    private static final int EDGE_MAX = 3;
    /** Maximum value allowed for a corner cell. */
    private static final int CORNER_MAX = 2;

    /** Simple fast scanner for competitive‑style input. */
    private static final class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        /** Returns the next token, blocking until one is available. */
        private String nextToken() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    throw new UncheckedIOException(e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(nextToken());
        }
    }

    /** Determines the maximal permissible value for a cell based on its coordinates. */
    private static int getMaxValue(int row, int col, int n, int m) {
        // corner cells
        if ((row == 0 || row == n - 1) && (col == 0 || col == m - 1)) {
            return CORNER_MAX;
        }
        // edge cells (but not corner)
        if (row == 0 || row == n - 1 || col == 0 || col == m - 1) {
            return EDGE_MAX;
        }
        // interior cells
        return INTERIOR_MAX;
    }

    /**
     * Processes a single test case.
     *
     * @param scanner  the scanner reading the current test case
     * @param out      the output stream used for answering
     * @param n        number of rows
     * @param m        number of columns
     * @return {@code true} if the grid is valid (printed), {@code false} otherwise
     */
    private static boolean processTestCase(FastScanner scanner, PrintWriter out,
                                           int n, int m) {
        int[][] grid = new int[n][m];
        boolean valid = true;

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                int value = scanner.nextInt();
                int maxAllowed = getMaxValue(i, j, n, m);

                // If the supplied value exceeds the allowed maximum, the whole test case fails.
                if (value > maxAllowed) {
                    valid = false;
                }
                // Overwrite with the maximal permissible value (as required by the original logic).
                grid[i][j] = maxAllowed;
            }
        }

        if (!valid) {
            out.println("NO");
            return false;
        }

        // Grid respects all limits – output YES and the transformed grid.
        out.println("YES");
        for (int i = 0; i < n; i++) {
            StringBuilder line = new StringBuilder();
            for (int j = 0; j < m; j++) {
                line.append(grid[i][j]).append(' ');
            }
            out.println(line.toString().trim());
        }
        return true;
    }

    /** Program entry point. */
    public static void main(String[] args) {
        FastScanner scanner = new FastScanner();
        PrintWriter out = new PrintWriter(System.out);

        int t = scanner.nextInt();                     // number of test cases
        while (t-- > 0) {
            int n = scanner.nextInt();                 // rows
            int m = scanner.nextInt();                 // columns
            processTestCase(scanner, out, n, m);
        }

        out.flush();
    }
}

import java.io.PrintWriter;
import java.util.NoSuchElementException;

/**
 * Solution for the contest problem.
 * Reads multiple test cases, checks feasibility and prints the required grid.
 */
public class Main {

    public static void main(String[] args) {
        new Main().run();
    }

    /** Entry point logic – delegates all processing to Solver. */
    public void run() {
        InputReader reader = new InputReader();
        PrintWriter out = new PrintWriter(System.out);
        solve(reader, out);
        out.flush();
    }

    /**
     * Solves a single test case and writes the answer using the provided writer.
     *
     * @param reader  input reader
     * @param out     output writer
     */
    private void solve(InputReader reader, PrintWriter out) {
        int t = reader.nextInt();
        while (t-- > 0) {
            int n = reader.nextInt();
            int m = reader.nextInt();
            int[][] heights = new int[n][m];
            for (int y = 0; y < n; ++y) {
                for (int x = 0; x < m; ++x) {
                    heights[y][x] = reader.nextInt();
                }
            }

            boolean possible = isFeasible(heights);
            out.println(possible ? "YES" : "NO");
            if (possible) {
                for (int y = 0; y < n; ++y) {
                    for (int x = 0; x < m; ++x) {
                        if (x != 0) out.print(' ');
                        out.print(computeBoundaryCount(y, x, n, m));
                    }
                    out.println();
                }
            }
        }
    }

    /**
     * Determines whether a valid layout can be produced.
     *
     * @param heights matrix of requested cell values
     * @return true if every cell can be satisfied, false otherwise
     */
    private boolean isFeasible(int[][] heights) {
        int n = heights.length;
        int m = heights[0].length;
        for (int y = 0; y < n; ++y) {
            for (int x = 0; x < m; ++x) {
                int needed = computeBoundaryCount(y, x, n, m);
                if (needed < heights[y][x]) {
                    return false;
                }
            }
        }
        return true;
    }

    /**
     * Calculates the number of neighboring cells (adjacent by side) that are inside the grid.
     *
     * @param y row index
     * @param x column index
     * @param rows total number of rows
     * @param cols total number of columns
     * @return neighbor count
     */
    private int computeBoundaryCount(int y, int x, int rows, int cols) {
        int count = 4;
        if (y == 0 || y == rows - 1) count--;
        if (x == 0 || x == cols - 1) count--;
        return count;
    }
}

/**
 * Simple fast scanner for competitive‑programming style input.
 * It does not try to be overly clever – it just reads bytes efficiently.
 */
class InputReader {
    private final java.io.InputStream in = System.in;
    private final byte[] buffer = new byte[1024];
    private int ptr = 0;
    private int buflen = 0;

    private boolean hasNextByte() {
        if (ptr < buflen) return true;
        ptr = 0;
        try {
            buflen = in.read(buffer);
        } catch (java.io.IOException e) {
            throw new UncheckedIOException(e);
        }
        return buflen != -1;
    }

    private byte readByte() {
        return hasNextByte() ? buffer[ptr++] : (byte) -1;
    }

    /** @return true if there is another token available */
    private boolean hasNextToken() {
        while (hasNextByte() && !isPrintable(buffer[ptr])) ptr++;
        return hasNextByte();
    }

    /** @return next integer parsed from input */
    public int nextInt() {
        return nextLong();
    }

    /** @return next long parsed from input */
    public long nextLong() {
        if (!hasNextToken()) throw new NoSuchElementException();
        long v = 0;
        boolean neg = false;
        byte b = readByte();
        while (b != '-' && (b < '0' || b > '9')) {
            if (!hasNextByte()) throw new NoSuchElementException();
            b = readByte();
        }
        if (b == '-') {
            neg = true;
            if (!hasNextByte()) throw new NoSuchElementException();
            b = readByte();
        }
        while (b >= '0' && b <= '9') {
            v = v * 10 + (b - '0');
            if (!hasNextByte()) break;
            b = readByte();
        }
        return neg ? -v : v;
    }

    /** @return next printable token as {@link String} */
    public String next() {
        if (!hasNextToken()) throw new NoSuchElementException();
        StringBuilder sb = new StringBuilder();
        byte b = readByte();
        while (isPrintable(b)) {
            sb.append((char) b);
            if (!hasNextByte()) break;
            b = readByte();
        }
        return sb.toString();
    }

    private static boolean isPrintable(byte c) {
        return c >= 32 && c <= 126;
    }
}

import java.io.*;
