/**
 * Refactored solution for the “Global 9 – B” problem.
 *
 * <p>
 * The program reads a test case count, then for each test case it reads an {@code n × m}
 * integer matrix and decides whether a valid configuration exists.  If the matrix can be
 * transformed, it prints {@code YES} followed by the reference pattern; otherwise it prints
 * {@code NO}.
 * </p>
 * <p>
 * The refactor focuses on readability, encapsulation of magic numbers, small helper methods,
 * and proper resource handling.
 * </p>
 */
public final class Main {

    /* --------------------------------------------------------------------- */
    /*  Constants – capture the problem‑specific limits                        */
    /* --------------------------------------------------------------------- */
    private static final int CORNER_MAX   = 2;   // cells at the four corners
    private static final int EDGE_MAX     = 3;   // cells on the border but not corners
    private static final int INTERIOR_MAX = 4;   // all other cells

    /* --------------------------------------------------------------------- */
    /*  Entry point                                                          */
    /* --------------------------------------------------------------------- */
    public static void main(String[] args) throws Exception {
        // Use try‑with‑resources so the reader is closed automatically
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(System.in))) {
            FastScanner fs = new FastScanner(reader);
            StringBuilder output = new StringBuilder();

            int tests = fs.nextInt();
            for (int t = 0; t < tests; t++) {
                int n = fs.nextInt();
                int m = fs.nextInt();
                int[][] grid = readMatrix(reader, n, m);

                if (!isValidConfiguration(grid, n, m)) {
                    output.append("NO").append('\n');
                    continue;
                }

                int[][] pattern = buildReferencePattern(n, m);
                output.append("YES").append('\n');
                appendMatrix(pattern, output);
            }

            System.out.print(output.toString());
        }
    }

    /* --------------------------------------------------------------------- */
    /*  Input utilities                                                       */
    /* --------------------------------------------------------------------- */
    private static int[][] readMatrix(BufferedReader br, int rows, int cols) throws IOException {
        int[][] matrix = new int[rows][];
        StringTokenizer st;
        for (int i = 0; i < rows; i++) {
            st = new StringTokenizer(br.readLine());
            matrix[i] = new int[cols];
            for (int j = 0; j < cols; j++) {
                matrix[i][j] = fsNextInt(st);
            }
        }
        return matrix;
    }

    private static int fsNextInt(StringTokenizer st) {
        return Integer.parseInt(st.nextToken());
    }

    /* --------------------------------------------------------------------- */
    /*  Validation                                                            */
    /* --------------------------------------------------------------------- */
    /**
     * Checks whether the supplied matrix respects the problem constraints.
     *
     * @return {@code true} if the matrix can be transformed, {@code false} otherwise
     */
    private static boolean isValidConfiguration(int[][] a, int n, int m) {
        // corners – must not exceed CORNER_MAX
        if (a[0][0] > CORNER_MAX || a[0][m - 1] > CORNER_MAX
                || a[n - 1][0] > CORNER_MAX || a[n - 1][m - 1] > CORNER_MAX) {
            return false;
        }

        // top & bottom edges (excluding corners)
        for (int j = 1; j < m - 1; j++) {
            if (a[0][j] > EDGE_MAX || a[n - 1][j] > EDGE_MAX) {
                return false;
            }
        }

        // left & right edges (excluding corners)
        for (int i = 1; i < n - 1; i++) {
            if (a[i][0] > EDGE_MAX || a[i][m - 1] > EDGE_MAX) {
                return false;
            }
        }

        // interior cells
        for (int i = 1; i < n - 1; i++) {
            for (int j = 1; j < m - 1; j++) {
                if (a[i][j] > INTERIOR_MAX) {
                    return false;
                }
            }
        }
        return true;
    }

    /* --------------------------------------------------------------------- */
    /*  Reference pattern construction                                         */
    /* --------------------------------------------------------------------- */
    /**
     * Builds the canonical reference pattern that the validated matrix must match.
     */
    private static int[][] buildReferencePattern(int rows, int cols) {
        int[][] pattern = new int[rows][cols];

        // corners -> 2
        pattern[0][0] = pattern[0][cols - 1] = pattern[rows - 1][0] = pattern[rows - 1][cols - 1] = CORNER_MAX;

        // top & bottom rows (excluding corners) -> 3
        for (int j = 1; j < cols - 1; j++) {
            pattern[0][j] = pattern[rows - 1][j] = EDGE_MAX;
        }

        // left & right columns (excluding corners) -> 3
        for (int i = 1; i < rows - 1; i++) {
            pattern[i][0] = pattern[i][cols - 1] = EDGE_MAX;
        }

        // interior -> 4
        for (int i = 1; i < rows - 1; i++) {
            for (int j = 1; j < cols - 1; j++) {
                pattern[i][j] = INTERIOR_MAX;
            }
        }
        return pattern;
    }

    /* --------------------------------------------------------------------- */
    /*  Output helpers                                                         */
    /* --------------------------------------------------------------------- */
    private static void appendMatrix(int[][] matrix, StringBuilder sb) {
        for (int[] row : matrix) {
            for (int val : row) {
                sb.append(val).append(' ');
            }
            sb.append('\n');
        }
    }

    /* --------------------------------------------------------------------- */
    /*  Fast scanner – minimal wrapper around StringTokenizer                    */
    /* --------------------------------------------------------------------- */
    private static final class FastScanner {
        private final BufferedReader br;
        private StringTokenizer tokenizer;

        FastScanner(BufferedReader br) {
            this.br = br;
        }

        /** Consume the next line and initialise the tokenizer. */
        private void nextToken() throws IOException {
            tokenizer = new StringTokenizer(br.readLine());
        }

        /** Return the next integer token (throws if not available). */
        int nextInt() throws IOException {
            if (tokenizer == null || !tokenizer.hasMoreTokens()) {
                nextToken();
            }
            return Integer.parseInt(tokenizer.nextToken());
        }
    }
}

import java.util.Scanner;

/**
 * Refactored version of the original program.
 * The algorithm is unchanged – it reads a matrix, tries to “balance” it,
 * and prints YES together with the balanced matrix or NO if balancing is impossible.
 */
public class Main {

    /** Number of test cases. */
    private static int testCaseCount;

    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            readTestCaseCount(scanner);
            processAllTestCases(scanner);
        }
    }

    /** Reads the number of test cases from the scanner. */
    private static void readTestCaseCount(Scanner scanner) {
        testCaseCount = scanner.nextInt();
    }

    /** Reads each test case, attempts to balance the matrix and prints the result. */
    private static void processAllTestCases(Scanner scanner) {
        for (int caseIndex = 0; caseIndex < testCaseCount; caseIndex++) {
            solveCase(scanner);
        }
    }

    /**
     * Solves a single test case.
     * Reads the matrix dimensions and values, tries to balance it,
     * and prints either “YES” with the balanced matrix or “NO”.
     */
    private static void solveCase(Scanner scanner) {
        int rows = scanner.nextInt();
        int cols = scanner.nextInt();
        int[][] matrix = readMatrix(scanner, rows, cols);

        boolean hasSolution = true;
        boolean madeChanges = true;

        while (madeChanges) {
            madeChanges = false;

            for (int r = 0; r < rows && hasSolution; r++) {
                for (int c = 0; c < cols && hasSolution; c++) {
                    int cellValue = matrix[r][c];

                    // If a corner cell has more than 4 neighbours, balancing is impossible.
                    if (cellValue + neighboursInBounds(r, c, rows, cols) > 4) {
                        hasSolution = false;
                        break;
                    }

                    int surplus = computeSurplus(matrix, r, c, rows, cols);
                    if (surplus < 0) {
                        // Directly adjust the cell if we can remove the surplus.
                        if (surplus != -1 || cellValue != 0) {
                            matrix[r][c] -= surplus;   // surplus is negative → add its absolute value
                            madeChanges = true;
                        }
                    } else if (surplus != 0) {
                        // Move surplus to adjacent zero cells (up, down, left, right).
                        if (r > 0 && matrix[r - 1][c] == 0) {
                            transferSurplus(matrix, r, c, surplus, Direction.UP);
                            madeChanges = true;
                        }
                        if (surplus > 0 && r < rows - 1 && matrix[r + 1][c] == 0) {
                            transferSurplus(matrix, r, c, surplus, Direction.DOWN);
                            madeChanges = true;
                        }
                        if (surplus > 0 && c > 0 && matrix[r][c - 1] == 0) {
                            transferSurplus(matrix, r, c, surplus, Direction.LEFT);
                            madeChanges = true;
                        }
                        if (surplus > 0 && c < cols - 1 && matrix[r][c + 1] == 0) {
                            transferSurplus(matrix, r, c, surplus, Direction.RIGHT);
                            madeChanges = true;
                        }
                    }
                }
            }
        }

        if (hasSolution) {
            System.out.println("YES");
            printMatrix(matrix);
        } else {
            System.out.println("NO");
        }
    }

    /** Returns the number of neighbour cells that lie on the border of the matrix. */
    private static int neighboursInBounds(int row, int col, int rows, int cols) {
        int count = 0;
        if (row == 0 || row == rows - 1) {
            count++;
        }
        if (col == 0 || col == cols - 1) {
            count++;
        }
        return count;
    }

    /**
     * Computes how much the current cell exceeds the desired amount
     * after accounting for its non‑zero neighbours.
     */
    private static int computeSurplus(int[][] mat, int r, int c, int rows, int cols) {
        int value = mat[r][c];

        // Subtract neighbours that are currently non‑zero.
        if (r > 0 && mat[r - 1][c] > 0) value--;
        if (r < rows - 1 && mat[r + 1][c] > 0) value--;
        if (c > 0 && mat[r][c - 1] > 0) value--;
        if (c < cols - 1 && mat[r][c + 1] > 0) value--;

        return value;
    }

    /**
     * Moves one unit of surplus from the current cell to the neighbour in the given direction.
     * The neighbour must be a zero cell.
     */
    private static void transferSurplus(int[][] mat, int r, int c, int surplus, Direction dir) {
        // One unit can only be moved at a time – this mirrors the original logic.
        mat[r][c]--;
        switch (dir) {
            case UP -> mat[r - 1][c]++;
            case DOWN -> mat[r + 1][c]++;
            case LEFT -> mat[r][c - 1]++;
            case RIGHT -> mat[r][c + 1]++;
        }
    }

    /** Simple enum to make direction handling clearer. */
    private enum Direction {
        UP, DOWN, LEFT, RIGHT
    }

    /** Reads the matrix from the scanner according to the given dimensions. */
    private static int[][] readMatrix(Scanner scanner, int rows, int cols) {
        int[][] matrix = new int[rows][cols];
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                matrix[r][c] = scanner.nextInt();
            }
        }
        return matrix;
    }

    /** Utility method that prints a 2‑D int array with a single space between columns. */
    private static void printMatrix(int[][] matrix) {
        for (int[] row : matrix) {
            StringBuilder sb = new StringBuilder();
            for (int i = 0; i < row.length; i++) {
                if (i > 0) sb.append(' ');
                sb.append(row[i]);
            }
            System.out.println(sb);
        }
    }
}

import java.awt.*;
import java.io.*;
import java.util.*;

public class B9 {

    /** Upper bounds for different cell positions */
    private static final int MAX_CENTER = 4;   // interior cells
    private static final int MAX_EDGE    = 3;   // edge (non‑corner) cells
    private static final int MAX_CORNER  = 2;   // corner cells

    public static void main(String[] args) {
        FastReader reader = new FastReader();
        PrintWriter out = new PrintWriter(System.out);

        int t = reader.nextInt();
        while (t-- > 0) {
            solveOneCase(reader, out);
        }

        out.close();
    }

    /** Handles reading, validation and printing for a single test case */
    private static void solveOneCase(FastReader reader, PrintWriter out) {
        int w = reader.nextInt();   // width  (columns)
        int h = reader.nextInt();   // height (rows)

        int[][] grid = readGrid(reader, w, h);

        if (!isValidGrid(grid, w, h)) {
            out.println("NO");
            return;
        }

        out.println("YES");
        writeAnswer(out, w, h);
    }

    /** Reads the numeric grid – stored as [col][row] */
    private static int[][] readGrid(FastReader reader, int w, int h) {
        int[][] grid = new int[w][h];
        for (int y = 0; y < h; y++) {
            for (int x = 0; x < w; x++) {
                grid[x][y] = reader.nextInt();
            }
        }
        return grid;
    }

    /** Checks all constraints described in the original program */
    private static boolean isValidGrid(int[][] grid, int w, int h) {
        // corners must not exceed 2
        if (grid[0][0] > MAX_CORNER ||
            grid[w - 1][0] > MAX_CORNER ||
            grid[0][h - 1] > MAX_CORNER ||
            grid[w - 1][h - 1] > MAX_CORNER) {
            return false;
        }

        // every cell must be ≤ 4
        for (int x = 0; x < w; x++) {
            for (int y = 0; y < h; y++) {
                if (grid[x][y] > MAX_CENTER) {
                    return false;
                }
                // edge (non‑corner) cells must be ≤ 3
                if ((x == 0 || x == w - 1 || y == 0 || y == h - 1)
                        && grid[x][y] > MAX_EDGE) {
                    return false;
                }
            }
        }
        return true;
    }

    /** Prints the required answer grid (2/3/4 according to position) */
    private static void writeAnswer(PrintWriter out, int w, int h) {
        for (int y = 0; y < h; y++) {
            for (int x = 0; x < w; x++) {
                int value = MAX_CENTER;
                if (x == 0 || x == w - 1) {          // left or right edge
                    value--;
                }
                if (y == 0 || y == h - 1) {          // top or bottom edge
                    value--;
                }
                out.print(value);
                if (x < w - 1) {
                    out.print(' ');
                }
            }
            out.println();
        }
    }

    /** Fast scanner used for input reading */
    static class FastReader {
        private final BufferedReader br;
        private StringTokenizer st;

        FastReader() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    throw new UncheckedIOException(e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Refactored solution for Codeforces Global Round 9, problem B.
 * <p>
 * The program reads multiple test cases, each consisting of a grid.
 * It validates the grid according to the degree of each cell and,
 * if the validation succeeds, transforms the grid and prints the
 * resulting matrix. All input/output handling is performed via custom
 * fast scanner / printer utilities.
 */
public class GlobalRound9B {

    /** Fast scanner used to read the input efficiently. */
    private static FastScanner scanner;

    /** PrintWriter that writes the result using a buffered output stream. */
    private static PrintWriter printer;

    public static void main(String[] args) throws Exception {
        new Thread(() -> {
            try {
                printer = new PrintWriter(new BufferedOutputStream(System.out));
                scanner = new FastScanner(System.in);
                solve();
                printer.close();
            } catch (Exception ex) {
                ex.printStackTrace();
                System.exit(1);
            }
        }, "Solver", 1 << 27).start();
    }

    /** Main entry point – iterates over all test cases. */
    private static void solve() {
        int t = scanner.nextInt();
        while (t-- > 0) {
            processSingleTestCase();
        }
    }

    /** Reads the grid, validates it and produces the output if the test passes. */
    private static void processSingleTestCase() {
        int rows = scanner.nextInt();
        int cols = scanner.nextInt();
        int[][] grid = readGrid(rows, cols);

        if (!validateAndPrepare(grid, rows, cols)) {
            printer.println("NO");
            return;
        }

        // Replace cells that are still zero (should not happen after validation,
        // but we keep the original behaviour for safety).
        replaceZeros(grid, rows, cols);

        printer.println("YES");
        printGrid(grid);
    }

    /** Reads the whole grid from the scanner. */
    private static int[][] readGrid(int n, int m) {
        int[][] grid = new int[n][m];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                grid[i][j] = scanner.nextInt();
            }
        }
        return grid;
    }

    /** Validates each cell against its degree and overwrites the cell with the degree. */
    private static boolean validateAndPrepare(int[][] grid, int n, int m) {
        boolean ok = true;
        for (int i = 0; i < n && ok; i++) {
            for (int j = 0; j < m && ok; j++) {
                int degree = neighbourCount(i, j, n, m);
                if (grid[i][j] > degree) {
                    ok = false;
                } else {
                    grid[i][j] = degree;          // store degree for later use
                }
            }
        }
        return ok;
    }

    /** Returns the number of orthogonal neighbours a cell can have. */
    private static int neighbourCount(int i, int j, int rows, int cols) {
        int count = 0;
        if (i > 0) count++;
        if (i + 1 < rows) count++;
        if (j > 0) count++;
        if (j + 1 < cols) count++;
        return count;
    }

    /** Replaces every cell that still contains zero with the count of its non‑zero neighbours. */
    private static void replaceZeros(int[][] grid, int n, int m) {
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i][j] == 0) {
                    int neighbourSum = neighbourSum(grid, i, j, n, m);
                    grid[i][j] = neighbourSum;
                }
            }
        }
    }

    /** Returns the number of orthogonal neighbours that are currently non‑zero. */
    private static int neighbourSum(int[][] grid, int i, int j, int rows, int cols) {
        int sum = 0;
        if (i > 0 && grid[i - 1][j] != 0) sum++;
        if (i + 1 < rows && grid[i + 1][j] != 0) sum++;
        if (j > 0 && grid[i][j - 1] != 0) sum++;
        if (j + 1 < cols && grid[i][j + 1] != 0) sum++;
        return sum;
    }

    /** Prints the whole matrix to the provided PrintWriter. */
    private static void printGrid(int[][] grid) {
        for (int[] row : grid) {
            StringBuilder line = new StringBuilder();
            for (int value : row) {
                line.append(value).append(' ');
            }
            printer.println(line.toString().trim());
        }
    }

    /* --------------------------------------------------------------------- */
    /*   Fast I/O utilities (copied unchanged from the original submission)   */
    /* --------------------------------------------------------------------- */

    /** Simple fast scanner that reads tokens from standard input. */
    private static class FastScanner {
        private final InputStream stream;
        private final byte[] buffer = new byte[4096];
        private int bufferPos = 0, bufferLen = 0;

        FastScanner(InputStream stream) {
            this.stream = stream;
        }

        private int readByte() {
            if (bufferPos >= bufferLen) {
                bufferLen = stream.read(buffer);
                bufferPos = 0;
                if (bufferLen <= 0) return -1;
            }
            return buffer[bufferPos++];
        }

        private static boolean isSpaceChar(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        private static boolean isEndOfLine(int c) {
            return c == '\n' || c == '\r' || c == -1;
        }

        private int skipSpaces() {
            int c;
            while (!isSpaceChar(c = readByte())) ;
            return c;
        }

        /** Reads the next integer from the input. */
        int nextInt() {
            int c = skipSpaces();
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = readByte();
            }
            int number = 0;
            do {
                number *= 10;
                number += c - '0';
                c = readByte();
            } while (!isSpaceChar(c));
            return number * sign;
        }

        /** Reads the next line (not heavily used in this solution). */
        String nextLine() {
            int c = readByte();
            while (isSpaceChar(c)) c = readByte();
            StringBuilder sb = new StringBuilder();
            do {
                sb.appendCodePoint(c);
                c = readByte();
            } while (!isEndOfLine(c));
            return sb.toString();
        }

        // Additional helpers (nextLong, nextIntArray, …) can be added if needed,
        // but they are not required for the current logic.
    }
}

import java.io.*;
import java.util.*;

/**
 * Refactored solution for the "B" problem.
 *
 * The program reads multiple test cases, each consisting of an {@code n × m}
 * integer matrix. For every cell it checks whether the required number of
 * adjacent cells (up to four) can accommodate at least the value written in
 * that cell. If the check succeeds the matrix is replaced with the count of
 * neighbours for each cell and printed as {@code YES} followed by the new
 * matrix; otherwise {@code NO} is printed.
 *
 * The refactor focuses on readability, maintainability and separation of
 * concerns:
 *   • Clear naming and constants.
 *   • Small, single‑purpose methods.
 *   • Removal of dead code (unused power implementations).
 *   • Proper resource handling with try‑with‑resources.
 */
public class Main {

    /** Simple fast scanner that reads integers from {@code InputStream}. */
    private static final class InputReader {
        private final InputStream stream;
        private final byte[] buffer = new byte[16_384];
        private int ptr = 0, len = 0;

        public InputReader(InputStream stream) {
            this.stream = stream;
        }

        /** Reads the next byte, filling the buffer when necessary. */
        private int readByte() throws IOException {
            if (ptr >= len) {
                len = stream.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        private boolean isSpace(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        /** Reads the next integer (handles sign and whitespace). */
        public int nextInt() throws IOException {
            int c = readByte();
            while (!isSpace(c)) c = readByte();

            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = readByte();
            }

            int val = 0;
            while (c >= '0' && c <= '9') {
                val = val * 10 + (c - '0');
                c = readByte();
            }
            return val * sign;
        }

        /** Reads an {@code int}[n] from the input. */
        public int[] intArray(int n) throws IOException {
            int[] a = new int[n];
            for (int i = 0; i < n; ++i) a[i] = nextInt();
            return a;
        }

        /** Reads an {@code int}[rows][cols] matrix. */
        public int[][] intMatrix(int rows, int cols) throws IOException {
            int[][] m = new int[rows][cols];
            for (int i = 0; i < rows; ++i) {
                m[i] = intArray(cols);
            }
            return m;
        }
    }

    /** Counts how many orthogonal neighbours a cell (i, j) has. */
    private static int neighbourCount(int i, int j, int n, int m) {
        int count = 0;
        if (i > 0)      count++;
        if (j > 0)      count++;
        if (i < n - 1)  count++;
        if (j < m - 1)  count++;
        return count;
    }

    /** Prints a matrix to the supplied {@link PrintWriter}. */
    private static void printMatrix(int[][] matrix, PrintWriter out) {
        for (int[] row : matrix) {
            for (int val : row) {
                out.print(val);
                out.print(' ');
            }
            out.println();
        }
    }

    public static void main(String[] args) throws Exception {
        /* Try‑with‑resources guarantees the PrintWriter is closed automatically. */
        try (PrintWriter out = new PrintWriter(System.out)) {
            InputReader reader = new InputReader(System.in);
            int T = reader.nextInt();

            while (T-- > 0) {
                int n = reader.nextInt();
                int m = reader.nextInt();
                int[][] grid = new int[n][m];
                for (int i = 0; i < n; ++i) {
                    grid[i] = reader.intArray(m);
                }

                int[][] answer = new int[n][m];
                boolean valid = true;

                outer:
                for (int i = 0; i < n && valid; ++i) {
                    for (int j = 0; j < m; ++j) {
                        int neighbours = neighbourCount(i, j, n, m);
                        if (grid[i][j] > neighbours) {
                            valid = false;
                            break outer;
                        }
                        answer[i][j] = neighbours;
                    }
                }

                if (!valid) {
                    out.println("NO");
                } else {
                    out.println("YES");
                    printMatrix(answer, out);
                }
            }
        }
    }
}

import java.io.*;
import java.util.StringTokenizer;

/**
 * Solves the problem by validating border values and, if possible,
 * rewriting the matrix with the required pattern.
 *
 * The core idea:
 *   • Corners must not exceed 2  → set to 2
 *   • Edge (non‑corner) cells must not exceed 3 → set to 3
 *   • Inner cells must not exceed 4 → set to 4
 *   • If any cell violates its limit → answer is "NO"
 *   • Otherwise answer is "YES" and the transformed matrix is printed.
 *
 * The implementation is split into small, pure methods to improve
 * readability, testability and maintainability.
 */
public class Solution {

    /** Maximum allowed value for each cell type. */
    private static final int MAX_CORNER_VAL = 2;
    private static final int MAX_EDGE_VAL   = 3;
    private static final int MAX_INNER_VAL  = 4;

    public static void main(String[] args) {
        FastScanner fs = new FastScanner();
        int t = fs.nextInt();

        while (t-- > 0) {
            solveOneTestCase(fs);
        }
    }

    /** Reads a test case, processes it and prints the result. */
    private static void solveOneTestCase(FastScanner fs) {
        int n = fs.nextInt();
        int m = fs.nextInt();

        int[][] matrix = readMatrix(fs, n, m);

        // 1️⃣ Validate (and optionally rewrite) the four corners.
        if (!processCorners(matrix, n, m)) {
            System.out.println("NO");
            return;
        }

        // 2️⃣ Validate top/bottom rows (excluding corners) and first/last columns (excluding corners).
        if (!processEdges(matrix, n, m)) {
            System.out.println("NO");
            return;
        }

        // 3️⃣ Validate and fill the inner part.
        if (!processInner(matrix, n, m)) {
            System.out.println("NO");
            return;
        }

        // All checks passed → answer YES and print the transformed matrix.
        System.out.println("YES");
        printMatrix(matrix);
    }

    /** Reads an n×m matrix from the scanner. */
    private static int[][] readMatrix(FastScanner fs, int n, int m) {
        int[][] arr = new int[n][m];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                arr[i][j] = fs.nextInt();
            }
        }
        return arr;
    }

    /** Sets corners to MAX_CORNER_VAL and checks they were ≤ that value originally. */
    private static boolean processCorners(int[][] mat, int n, int m) {
        int[] corners = {
                mat[0][0],
                mat[n - 1][m - 1],
                mat[n - 1][0],
                mat[0][m - 1]
        };

        for (int i = 0; i < corners.length; i++) {
            if (corners[i] > MAX_CORNER_VAL) {
                return false; // violation → abort whole test case
            }
            // rewrite the corner with the required value (2)
            switch (i) {
                case 0 -> mat[0][0] = MAX_CORNER_VAL;
                case 1 -> mat[n - 1][m - 1] = MAX_CORNER_VAL;
                case 2 -> mat[n - 1][0] = MAX_CORNER_VAL;
                case 3 -> mat[0][m - 1] = MAX_CORNER_VAL;
            }
        }
        return true;
    }

    /** Sets edge (non‑corner) cells to MAX_EDGE_VAL and validates limits. */
    private static boolean processEdges(int[][] mat, int n, int m) {
        boolean violation = false;

        // first and last column (excluding corners)
        for (int i = 1; i < n - 1; i++) {
            int top = mat[i][0];
            int bottom = mat[i][m - 1];
            if (top > MAX_EDGE_VAL || bottom > MAX_EDGE_VAL) {
                violation = true;
                break;
            }
            mat[i][0] = MAX_EDGE_VAL;
            mat[i][m - 1] = MAX_EDGE_VAL;
        }
        if (violation) {
            return false;
        }

        // first and last row (excluding corners)
        for (int j = 1; j < m - 1; j++) {
            int left = mat[0][j];
            int right = mat[n - 1][j];
            if (left > MAX_EDGE_VAL || right > MAX_EDGE_VAL) {
                violation = true;
                break;
            }
            mat[0][j] = MAX_EDGE_VAL;
            mat[n - 1][j] = MAX_EDGE_VAL;
        }
        return !violation;
    }

    /** Sets inner cells to MAX_INNER_VAL and validates they are ≤ 4. */
    private static boolean processInner(int[][] mat, int n, int m) {
        boolean violation = false;
        for (int i = 1; i < n - 1; i++) {
            for (int j = 1; j < m - 1; j++) {
                int val = mat[i][j];
                if (val > MAX_INNER_VAL) {
                    violation = true;
                    break;
                }
                mat[i][j] = MAX_INNER_VAL;
            }
            if (violation) {
                break;
            }
        }
        return !violation;
    }

    /** Prints the matrix to stdout using the same format as the original solution. */
    private static void printMatrix(int[][] mat) {
        StringBuilder out = new StringBuilder();
        for (int i = 0; i < mat.length; i++) {
            for (int j = 0; j < mat[i].length; j++) {
                out.append(mat[i][j]).append(' ');
            }
            out.append('\n');
        }
        System.out.print(out.toString());
    }

    /** Fast scanner exposing only the methods we need. */
    private static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        private String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    throw new UncheckedIOException(e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        long nextLong() {
            return Long.parseLong(next());
        }

        double nextDouble() {
            return Double.parseDouble(next());
        }

        String nextLine() {
            try {
                return br.readLine();
            } catch (IOException e) {
                throw new UncheckedIOException(e);
            }
        }
    }
}

import java.io.*;
import java.util.StringTokenizer;

/**
 * Refactored solution that checks whether a given matrix can be transformed
 * into a "valid" matrix respecting perimeter constraints.
 *
 * The program separates concerns into small, reusable components, uses
 * meaningful naming, and avoids duplicated code.
 */
public class Main {

    /* --------------------------------------------------------------------- */
    /* I/O utilities                                                         */
    /* --------------------------------------------------------------------- */

    /** Simple wrapper around BufferedReader that supplies tokens. */
    private static final class InputReader {
        private final BufferedReader br;

        InputReader(InputStream in) {
            this.br = new BufferedReader(new InputStreamReader(in));
        }

        /** Returns next non‑empty token. */
        private String nextToken() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                st = new StringTokenizer(br.readLine());
            }
            return st.nextToken();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(nextToken());
        }

        long nextLong() throws IOException {
            return Long.parseLong(nextToken());
        }

        /** Convenience method for a whole line (not needed by the algorithm). */
        String readLine() throws IOException {
            return br.readLine();
        }

        // Reusable tokenizer instance – initialized lazily.
        private StringTokenizer st;
    }

    /** Helper that writes to stdout (auto‑flushes). */
    private static final class OutputWriter {
        private final PrintWriter out;
        OutputWriter(OutputStream stream) {
            this.out = new PrintWriter(stream, true);
        }
        void print(StringBuilder sb) {
            out.print(sb.toString());
        }
        void println() {
            out.println();
        }
    }

    /* --------------------------------------------------------------------- */
    /* Constants                                                             */
    /* --------------------------------------------------------------------- */

    /** Maximum allowed value for a corner cell (0,0), (0,m‑1), (n‑1,0), (n‑1,m‑1). */
    private static final int CORNER_MAX = 2;
    /** Maximum allowed value for an edge (but not corner) cell. */
    private static final int EDGE_MAX = 3;
    /** Maximum allowed value for an inner cell. */
    private static final int INNER_MAX = 4;

    /* --------------------------------------------------------------------- */
    /* Validation utilities                                                   */
    /* --------------------------------------------------------------------- */

    /** Describes the type of a cell based on its position. */
    private enum CellKind {
        CORNER,
        EDGE,
        INNER
    }

    /** Returns the kind of cell for given indices and dimensions. */
    private static CellKind cellKind(int i, int j, int n, int m) {
        if ((i == 0 && (j == 0 || j == m - 1)) ||
            (i == n - 1 && (j == 0 || j == m - 1))) {
            return CellKind.CORNER;
        }
        if (i == 0 || i == n - 1 || j == 0 || j == m - 1) {
            return CellKind.EDGE;
        }
        return CellKind.INNER;
    }

    /** Validates that a value respects its cell's allowed maximum.
     *  @throws IllegalArgumentException if the value is too large. */
    private static void validate(int value, CellKind kind) {
        switch (kind) {
            case CORNER -> {
                if (value > CORNER_MAX) throw new IllegalArgumentException();
            }
            case EDGE -> {
                if (value > EDGE_MAX) throw new IllegalArgumentException();
            }
            case INNER -> {
                if (value > INNER_MAX) throw new IllegalArgumentException();
            }
        }
    }

    /* --------------------------------------------------------------------- */
    /* Core algorithm                                                         */
    /* --------------------------------------------------------------------- */

    /** Checks whether the matrix can be turned into a valid matrix. */
    private static boolean canBeValidated(int[][] grid, int n, int m) {
        boolean valid = true;

        for (int i = 0; i < n && valid; i++) {
            for (int j = 0; j < m && valid; j++) {
                CellKind kind = cellKind(i, j, n, m);
                int maxAllowed = switch (kind) {
                    case CORNER -> CORNER_MAX;
                    case EDGE -> EDGE_MAX;
                    case INNER -> INNER_MAX;
                };
                try {
                    validate(grid[i][j], kind);
                } catch (IllegalArgumentException e) {
                    valid = false;      // cell cannot be adjusted to a permissible value
                }
                if (valid) {
                    grid[i][j] = maxAllowed;   // assign the maximum permissible value
                }
            }
        }
        return valid;
    }

    /** Reads an n×m integer matrix from the input stream. */
    private static int[][] readIntMatrix(InputReader in, int n, int m) throws IOException {
        int[][] mat = new int[n][m];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                mat[i][j] = in.nextInt();
            }
        }
        return mat;
    }

    /* --------------------------------------------------------------------- */
    /* Simple prime test (kept for completeness, not used by the algorithm) */
    /* --------------------------------------------------------------------- */

    private static boolean isPrime(int n) {
        if (n < 2) return false;
        if (n % 2 == 0) return n == 2;
        for (int d = 3; d * d <= n; d += 2) {
            if (n % d == 0) return false;
        }
        return true;
    }

    /* --------------------------------------------------------------------- */
    /* Entry point                                                           */
    /* --------------------------------------------------------------------- */

    public static void main(String[] args) throws Exception {
        try (InputReader reader = new InputReader(System.in);
             OutputWriter writer = new OutputWriter(System.out)) {

            StringBuilder answer = new StringBuilder();
            int t = reader.nextInt();

            while (t-- > 0) {
                int n = reader.nextInt();
                int m = reader.nextInt();
                int[][] matrix = readIntMatrix(reader, n, m);

                boolean possible = canBeValidated(matrix, n, m);

                if (possible) {
                    answer.append("YES\n");
                    for (int i = 0; i < n; i++) {
                        for (int j = 0; j < m; j++) {
                            answer.append(matrix[i][j]).append(' ');
                        }
                        answer.append('\n');
                    }
                } else {
                    answer.append("NO\n");
                }
            }

            writer.print(answer);
        }
    }
}

import java.io.BufferedReader;
import java.io.BufferedWriter;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.OutputStreamWriter;
import java.util.StringTokenizer;

/**
 * Refactored version of the original {@code Grid} class.
 * The program reads multiple test cases, each consisting of a matrix,
 * validates the matrix and, if possible, reduces each positive
 * cell by the count of its positive neighbours.  The result is
 * printed as "YES" followed by the transformed matrix, or "NO"
 * when the transformation cannot be performed.
 */
public class GridProcessor {

    /* ---------------------------------------------------------------------- */
    /*                           Core Processing Logic                         */
    /* ---------------------------------------------------------------------- */

    /**
     * Attempts to increment a cell that currently holds {@code 0} to {@code 1}.
     *
     * @return {@code true} if the increment succeeded, {@code false} otherwise
     */
    private static boolean tryIncrementIfZero(int[][] grid, int rows, int cols, int r, int c) {
        if (grid[r][c] == 0) {
            grid[r][c] = 1;
            return true;
        }
        return false;
    }

    /**
     * Counts how many of the four orthogonal neighbours of {@code (r,c)} are
     * currently positive.  The current cell's own value is also part of the
     * initial count (mimicking the original {@code getNumInc} logic).
     *
     * @return the computed count
     */
    private static int countAdjacentPositive(int[][] grid, int rows, int cols, int r, int c) {
        int value = grid[r][c];

        if (r > 0 && grid[r - 1][c] > 0) value--;
        if (r < rows - 1 && grid[r + 1][c] > 0) value--;
        if (c > 0 && grid[r][c - 1] > 0) value--;
        if (c < cols - 1 && grid[r][c + 1] > 0) value--;

        return value;
    }

    /**
     * Validates a single cell according to the rules implemented in the
     * original {@code checkNBors} method.
     *
     * @return {@code true} if the cell can be processed successfully
     */
    private static boolean validateCell(int[][] grid, int rows, int cols, int r, int c) {
        int adjacent = countAdjacentPositive(grid, rows, cols, r, c);

        // If more than four neighbours are positive the cell is invalid.
        if (adjacent > 4) {
            return false;
        }

        // Normalise negative counts – they represent “deficit” that must be
        // compensated by turning zeros into ones.
        if (adjacent < 0) {
            grid[r][c] -= adjacent;   // make the cell non‑negative
            adjacent = 0;
        }

        // Try to consume positive neighbours by converting adjacent zeros.
        // The order mirrors the original nested conditional logic.
        if (r < rows - 1 && adjacent > 0 && tryIncrementIfZero(grid, rows, cols, r + 1, c)) {
            adjacent--;
        }
        if (c < cols - 1 && adjacent > 0 && tryIncrementIfZero(grid, rows, cols, r, c + 1)) {
            adjacent--;
        }
        if (c > 0 && adjacent > 0 && tryIncrementIfZero(grid, rows, cols, r, c - 1)) {
            adjacent--;
        }
        if (r > 0 && adjacent > 0 && tryIncrementIfZero(grid, rows, cols, r - 1, c)) {
            adjacent--;
        }

        // The cell is valid only when all required increments have been
        // performed (i.e. no surplus adjacent values remain).
        return adjacent == 0;
    }

    /**
     * Checks whether every positive cell in the grid can be validated.
     *
     * @return {@code true} if the whole grid passes validation
     */
    private static boolean validateAll(int[][] grid, int rows, int cols) {
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] > 0 && !validateCell(grid, rows, cols, i, j)) {
                    return false;
                }
            }
        }
        return true;
    }

    /**
     * Performs the actual reduction step for each positive cell.
     *
     * @return a new grid after reduction, or an empty 0×0 array if the
     *         transformation cannot be carried out.
     */
    private static int[][] reduceGrid(int[][] original, int rows, int cols) {
        // First phase – validation.  If any cell fails validation we abort.
        if (!validateAll(original, rows, cols)) {
            return new int[0][0];
        }

        // Second phase – actual arithmetic reduction.
        int[][] grid = copy(original, rows, cols);
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] > 0) {
                    int toReduce = countAdjacentPositive(grid, rows, cols, i, j);
                    grid[i][j] -= toReduce;
                }
            }
        }
        return grid;
    }

    /** Simple deep copy of a 2‑D int array. */
    private static int[][] copy(int[][] src, int rows, int cols) {
        int[][] dst = new int[rows][cols];
        for (int i = 0; i < rows; i++) {
            System.arraycopy(src[i], 0, dst[i], 0, cols);
        }
        return dst;
    }

    /* ---------------------------------------------------------------------- */
    /*                       Input / Output Utilities                        */
    /* ---------------------------------------------------------------------- */

    /**
     * Parses a whitespace‑separated line of integers into an {@code Integer[]}.
     */
    private static Integer[] parseIntArray(String line) {
        StringTokenizer tokenizer = new StringTokenizer(line.trim());
        int length = tokenizer.countTokens();
        Integer[] result = new Integer[length];
        for (int i = 0; i < length; i++) {
            result[i] = Integer.parseInt(tokenizer.nextToken());
        }
        return result;
    }

    /* ---------------------------------------------------------------------- */
    /*                               Main Entry Point                           */
    /* ---------------------------------------------------------------------- */

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        BufferedWriter bw = new BufferedWriter(new OutputStreamWriter(System.out));

        int testCases = Integer.parseInt(br.readLine().trim());

        for (int t = 0; t < testCases; t++) {
            Integer[] dims = parseIntArray(br.readLine());
            int rows = dims[0];
            int cols = dims[1];

            int[][] grid = new int[rows][cols];
            for (int r = 0; r < rows; r++) {
                Integer[] rowVals = parseIntArray(br.readLine());
                for (int c = 0; c < cols; c++) {
                    grid[r][c] = rowVals[c];
                }
            }

            int[][] transformed = reduceGrid(grid, rows, cols);

            // Output YES/NO according to whether a transformation succeeded.
            bw.write(transformed.length == 0 ? "NO" : "YES");
            bw.newLine();
            bw.flush();

            // If successful, print the resulting matrix.
            if (transformed.length > 0) {
                for (int r = 0; r < rows; r++) {
                    StringBuilder line = new StringBuilder();
                    for (int c = 0; c < cols; c++) {
                        line.append(transformed[r][c]);
                        if (c < cols - 1) {
                            line.append(' ');
                        }
                    }
                    bw.write(line.toString());
                    bw.newLine();
                    bw.flush();
                }
            }
        }

        br.close();
        bw.close();
    }
}

import java.io.*;
import java.util.*;

public class MatrixProcessor {

    /** Fast scanner that reads tokens from standard input. */
    private static final class FastScanner {
        private final byte[] buffer = new byte[1 << 12];
        private int ptr = 0;
        private int len = 0;
        private final InputStream in;

        FastScanner(InputStream in) {
            this.in = in;
        }

        private int readByte() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        private boolean isSpace(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        /** Reads next token as an int. */
        int nextInt() throws IOException {
            int c;
            do {
                c = readByte();
            } while (c <= ' ' && c != -1);
            boolean negative = false;
            if (c == '-') {
                negative = true;
                c = readByte();
            }
            int value = 0;
            while (c > ' ') {
                value = value * 10 + (c - '0');
                c = readByte();
            }
            return negative ? -value : value;
        }

        /** Reads next token as a long. */
        long nextLong() throws IOException {
            long number = 0;
            int b;
            boolean negative = false;
            do {
                b = readByte();
            } while ((b < '0' && b > '9') && b != '-');
            if (b == '-') {
                negative = true;
                b = readByte();
            }
            while (true) {
                if (b >= '0' && b <= '9') {
                    number = number * 10 + (b - '0');
                } else {
                    return negative ? -number : number;
                }
                b = readByte();
            }
        }
    }

    /** Determines whether the cell (i,j) lies on the border of an n×m matrix. */
    private static boolean isBorder(int i, int j, int n, int m) {
        return i == 0 || j == 0 || i == n - 1 || j == m - 1;
    }

    /** Returns the required value for a border cell according to the problem statement. */
    private static int borderValue(int i, int j, int n, int m) {
        // corners are a special subset of borders
        if ((i == 0 && j == 0) ||
            (i == 0 && j == m - 1) ||
            (i == n - 1 && j == 0) ||
            (i == n - 1 && j == m - 1)) {
            return 2;
        }
        return 3; // non‑corner border cells
    }

    /** Solves a single test case. */
    private void solve(FastScanner fs, PrintWriter out) {
        int tests = fs.nextInt();
        for (int t = 0; t < tests; ++t) {
            int n = fs.nextInt();
            int m = fs.nextInt();
            int[][] matrix = new int[n][m];
            boolean invalid = false;

            // Read the matrix and check the allowed maximum values.
            for (int i = 0; i < n; ++i) {
                for (int j = 0; j < m; ++j) {
                    matrix[i][j] = fs.nextInt();
                    if (isBorder(i, j, n, m)) {
                        // Corner cells must be <= 2
                        if ((i == 0 && j == 0) ||
                            (i == 0 && j == m - 1) ||
                            (i == n - 1 && j == 0) ||
                            (i == n - 1 && j == m - 1)) {
                            if (matrix[i][j] > 2) {
                                invalid = true;
                            }
                        } else {
                            // Other border cells must be <= 3
                            if (matrix[i][j] > 3) {
                                invalid = true;
                            }
                        }
                    } else {
                        // Interior cells must be <= 4
                        if (matrix[i][j] > 4) {
                            invalid = true;
                        }
                    }
                }
            }

            if (invalid) {
                out.println("NO");
                continue;
            }

            // Output the constructed matrix.
            out.println("YES");
            for (int i = 0; i < n; ++i) {
                for (int j = 0; j < m; ++j) {
                    out.print(borderValue(i, j, n, m) + " ");
                }
                out.println();
            }
        }
    }

    /** Entry point of the program. */
    public static void main(String[] args) throws Exception {
        FastScanner scanner = new FastScanner(System.in);
        PrintWriter writer = new PrintWriter(System.out);
        new MatrixProcessor().solve(scanner, writer);
        writer.flush();
    }
}

import java.io.*;
import java.util.StringTokenizer;

/**
 * Solves the “Neighbor Grid” problem.
 *
 * The program reads multiple test cases. For each test case it reads a matrix
 * size {@code r × c} and the values that would be placed on that grid.
 * Depending on the cell position it needs to place a fixed number:
 *   • corners   → 2
 *   • edges     → 3
 *   • interior  → 4
 * If any input value exceeds the required number the answer is “NO”,
 * otherwise the answer is “YES” followed by the generated grid.
 *
 * The implementation focuses on readability, separation of concerns
 * and proper resource handling.
 */
public class B_Neighbor_Grid {

    /** Fast scanner that reads tokens from {@code System.in}. */
    private static final class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner() {
            this.br = new BufferedReader(new InputStreamReader(System.in));
        }

        /** Returns the next token, retrying until input is exhausted. */
        private String nextToken() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    String line = br.readLine();
                    if (line == null) {
                        return null;
                    }
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new UncheckedIOException(e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(nextToken());
        }

        long nextLong() {
            return Long.parseLong(nextToken());
        }

        double nextDouble() {
            return Double.parseDouble(nextToken());
        }

        String nextLine() {
            try {
                return br.readLine();
            } catch (IOException e) {
                throw new UncheckedIOException(e);
            }
        }
    }

    /** Determines whether a cell is a corner of the matrix. */
    private static boolean isCorner(int row, int col, int rows, int cols) {
        return (row == 0 || row == rows - 1) && (col == 0 || col == cols - 1);
    }

    /** Determines whether a cell lies on the border (including corners). */
    private static boolean isBorder(int row, int col, int rows, int cols) {
        return row == 0 || row == rows - 1 || col == 0 || col == cols - 1;
    }

    /** Returns the mandatory value for a cell based on its position. */
    private static int requiredValue(int row, int col, int rows, int cols) {
        if (isCorner(row, col, rows, cols)) {
            return 2;
        }
        if (isBorder(row, col, rows, cols)) {
            return 3;
        }
        return 4;
    }

    /** Solves a single test case and writes the result to the supplied writer. */
    private static void solveOne(FastScanner fs, PrintWriter out) {
        int rows = fs.nextInt();
        int cols = fs.nextInt();

        boolean impossible = false;
        int[][] result = new int[rows][cols];

        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                int input = fs.nextInt();
                int required = requiredValue(i, j, rows, cols);
                result[i][j] = required;
                if (input > required) {
                    impossible = true;
                }
            }
        }

        if (impossible) {
            out.println("NO");
        } else {
            out.println("YES");
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    out.print(result[i][j] + " ");
                }
                out.println();
            }
        }
    }

    /** Entry point of the program. */
    public static void main(String[] args) throws IOException {
        FastScanner scanner = new FastScanner();
        // Use BufferedWriter for a single write at the end (more efficient)
        BufferedWriter bw = new BufferedWriter(new OutputStreamWriter(System.out));
        PrintWriter out = new PrintWriter(bw);

        int t = scanner.nextInt();
        while (t-- > 0) {
            solveOne(scanner, out);
        }

        out.flush();
    }
}

import java.io.*;
import java.util.*;

public class Solution {
    private static final String YES = "YES";
    private static final String NO = "NO";

    private static final BufferedReader IN = new BufferedReader(new InputStreamReader(System.in));
    private static final PrintWriter OUT = new PrintWriter(System.out);
    private static StringTokenizer tokenizer;

    /** Entry point */
    public static void main(String[] args) throws Exception {
        solve();
        OUT.close();
    }

    /** Reads all test cases and processes them */
    private static void solve() throws Exception {
        int tests = nextInt();
        while (tests-- > 0) {
            int rows = nextInt();
            int cols = nextInt();
            int[][] grid = readGrid(rows, cols);

            Result result = checkAndTransform(grid);
            if (!result.success) {
                OUT.println(NO);
            } else {
                OUT.println(YES);
                printGrid(result.transformed);
            }
        }
    }

    /** Reads a rectangular grid of the given dimensions */
    private static int[][] readGrid(int rows, int cols) throws IOException {
        int[][] grid = new int[rows][cols];
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                grid[r][c] = nextInt();
            }
        }
        return grid;
    }

    /** Checks the limits for each cell and builds the transformed grid.
     *  Returns a {@link Result} that contains the transformed grid only if the
     *  limits are not exceeded. */
    private static Result checkAndTransform(int[][] grid) {
        int rows = grid.length;
        int cols = grid[0].length;
        int[][] transformed = new int[rows][cols];
        boolean valid = true;

        for (int r = 0; r < rows && valid; r++) {
            for (int c = 0; c < cols; c++) {
                int limit = computeLimit(r, c, rows, cols);
                if (grid[r][c] > limit) {
                    valid = false;
                } else {
                    transformed[r][c] = limit;
                }
            }
        }

        return new Result(valid, valid ? transformed : null);
    }

    /** Calculates the allowed limit for a given cell based on its position. */
    private static int computeLimit(int i, int j, int rows, int cols) {
        // Corner cells have 2 neighbouring cells (top‑left, top‑right, …)
        if ((i == 0 || i == rows - 1) && (j == 0 || j == cols - 1)) {
            return 2;
        }
        // Edge (but not corner) cells have 3 neighbours
        if (i == 0 || i == rows - 1 || j == 0 || j == cols - 1) {
            return 3;
        }
        // Interior cells have 4 neighbours
        return 4;
    }

    /** Prints a 2‑D int array row‑by‑row, separating numbers with a single space. */
    private static void printGrid(int[][] grid) {
        for (int[] row : grid) {
            StringBuilder sb = new StringBuilder();
            for (int c = 0; c < row.length; c++) {
                if (c > 0) sb.append(' ');
                sb.append(row[c]);
            }
            OUT.println(sb);
        }
    }

    /** Small container for the outcome of the checking/transform step. */
    private static final class Result {
        final boolean success;
        final int[][] transformed;

        Result(boolean success, int[][] transformed) {
            this.success = success;
            this.transformed = transformed;
        }
    }

    // -------------------------------------------------------------------------
    // Fast input helpers
    // -------------------------------------------------------------------------
    private static String next() throws IOException {
        while (tokenizer == null || !tokenizer.hasMoreTokens()) {
            tokenizer = new StringTokenizer(IN.readLine());
        }
        return tokenizer.nextToken();
    }

    private static int nextInt() throws IOException {
        return Integer.parseInt(next());
    }
}

import java.util.Scanner;

/**
 * Refactored version of NeighborGrid.
 *
 * <p> This class reads multiple test cases, validates the input matrix against
 * specific bounds for corners, edges and interior cells, and, when valid,
 * prints a filled matrix where:
 * <ul>
 *   <li>corner cells contain 2</li>
 *   <li>edge (non‑corner) cells contain 3</li>
 *   <li>interior cells contain 4</li>
 * </ul>
 * If any validation fails the program prints "NO".
 *
 * <p> The refactor introduces:
 * <ul>
 *   <li>named constants for the limits</li>
 *   <li>small, focused helper methods</li>
 *   <li>early‑exit validation</li>
 *   <li>a tiny DTO (`Result`) to separate success/failure states</li>
 *   <li>clear naming and reduced duplication</li>
 * </ul>
 */
public class NeighborGrid {

    /** Maximum allowed value for the four corner cells */
    private static final int CORNER_MAX = 2;

    /** Maximum allowed value for edge cells that are not corners */
    private static final int EDGE_MAX = 3;

    /** Maximum allowed value for interior cells */
    private static final int INTERIOR_MAX = 4;

    public static void main(String[] args) {
        // Try‑with‑resources ensures the scanner is closed automatically
        try (Scanner sc = new Scanner(System.in)) {
            int t = sc.nextInt();                       // number of test cases
            for (int testCase = 0; testCase < t; testCase++) {
                solveTestCase(sc);
            }
        }
    }

    /** Handles one test case: reads the matrix, validates it and prints the result. */
    private static void solveTestCase(Scanner sc) {
        int n = sc.nextInt();   // number of rows
        int m = sc.nextInt();   // number of columns

        int[][] matrix = readMatrix(sc, n, m);
        Result evaluation = evaluate(matrix);

        if (evaluation.isValid()) {
            System.out.println("YES");
            printFilledMatrix(evaluation.filled);
        } else {
            System.out.println("NO");
        }
    }

    /** Reads an n × m integer matrix from the scanner. */
    private static int[][] readMatrix(Scanner sc, int rows, int cols) {
        int[][] matrix = new int[rows][cols];
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                matrix[i][j] = sc.nextInt();
            }
        }
        return matrix;
    }

    /** Evaluates the matrix against the problem constraints. */
    private static Result evaluate(int[][] matrix) {
        int n = matrix.length;
        int m = matrix[0].length;

        // 1️⃣  Corner validation
        if (exceeds(matrix[0][0], CORNER_MAX) ||
            exceeds(matrix[0][m - 1], CORNER_MAX) ||
            exceeds(matrix[n - 1][0], CORNER_MAX) ||
            exceeds(matrix[n - 1][m - 1], CORNER_MAX)) {
            return Result.invalid();
        }

        // 2️⃣  Edge (non‑corner) validation
        if (hasExcessiveEdgeValue(matrix, EDGE_MAX)) {
            return Result.invalid();
        }

        // 3️⃣  Interior validation
        if (hasExcessiveInteriorValue(matrix, INTERIOR_MAX)) {
            return Result.invalid();
        }

        // 4️⃣  Build the filled matrix with the required pattern
        int[][] filled = new int[n][m];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                filled[i][j] = valueForPosition(i, j, n, m);
            }
        }
        // Overwrite corners with the exact required value (2)
        filled[0][0] = filled[0][m - 1] = filled[n - 1][0] = filled[n - 1][m - 1] = CORNER_MAX;

        return new Result(true, filled);
    }

    /** Returns true if the given value is greater than the supplied limit. */
    private static boolean exceeds(int value, int limit) {
        return value > limit;
    }

    /** Checks whether any edge (non‑corner) cell exceeds the edge limit. */
    private static boolean hasExcessiveEdgeValue(int[][] matrix, int limit) {
        int n = matrix.length;
        int m = matrix[0].length;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (isEdge(i, j, n, m) && exceeds(matrix[i][j], limit)) {
                    return true;
                }
            }
        }
        return false;
    }

    /** Checks whether any interior cell exceeds the interior limit. */
    private static boolean hasExcessiveInteriorValue(int[][] matrix, int limit) {
        int n = matrix.length;
        int m = matrix[0].length;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (isInterior(i, j, n, m) && exceeds(matrix[i][j], limit)) {
                    return true;
                }
            }
        }
        return false;
    }

    /** Determines whether a cell lies on the border of the matrix (including corners). */
    private static boolean isEdge(int i, int j, int n, int m) {
        return i == 0 || i == n - 1 || j == 0 || j == m - 1;
    }

    /** Determines whether a cell is strictly inside the matrix (not on any border). */
    private static boolean isInterior(int i, int j, int n, int m) {
        return i > 0 && i < n - 1 && j > 0 && j < m - 1;
    }

    /** Returns the value that should be placed at position (i,j) in the filled matrix. */
    private static int valueForPosition(int i, int j, int n, int m) {
        // Corners are handled separately later, but we keep the limit value for completeness
        if ((i == 0 || i == n - 1) && (j == 0 || j == m - 1)) {
            return CORNER_MAX;
        }
        if (isEdge(i, j, n, m)) {
            return EDGE_MAX;
        }
        return INTERIOR_MAX; // interior
    }

    /** Simple DTO to carry the outcome of the evaluation. */
    private static final class Result {
        final boolean valid;
        final int[][] filled;   // meaningful only when {@code valid} is true

        private Result(boolean valid, int[][] filled) {
            this.valid = valid;
            this.filled = filled;
        }

        static Result invalid() {
            return new Result(false, null);
        }
    }

    /** Utility method to print a matrix row‑by‑row. */
    private static void printFilledMatrix(int[][] matrix) {
        for (int[] row : matrix) {
            for (int val : row) {
                System.out.print(val + " ");
            }
            System.out.println();
        }
    }
}

import java.io.*;
import java.util.*;

public class Solution {
    /** Maximum allowed value on each cell type */
    private static final int CORNER_MAX = 2;
    private static final int EDGE_MAX = 3;
    private static final int INTERIOR_MAX = 4;

    /** Fast input reader */
    private static final FastReader SCANNER = new FastReader();

    public static void main(String[] args) throws Exception {
        int t = SCANNER.nextInt();

        while (t-- > 0) {
            int n = SCANNER.nextInt();
            int m = SCANNER.nextInt();

            boolean possible = true;
            int[][] result = new int[n][m];

            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    int value = SCANNER.nextInt();
                    int maxAllowed = getMaxAllowed(i, j, n, m);

                    if (value > maxAllowed) {
                        possible = false;
                    } else {
                        result[i][j] = maxAllowed;
                    }
                }
            }

            if (possible) {
                System.out.println("YES");
                printMatrix(result);
            } else {
                System.out.println("NO");
            }
        }
    }

    /** Determines the maximum value that may be placed at (i, j) */
    private static int getMaxAllowed(int i, int j, int n, int m) {
        // Corner cells
        if ((i == 0 && j == 0) ||
            (i == 0 && j == m - 1) ||
            (i == n - 1 && j == 0) ||
            (i == n - 1 && j == m - 1)) {
            return CORNER_MAX;
        }
        // Edge cells (excluding corners)
        if (i == 0 || i == n - 1 || j == 0 || j == m - 1) {
            return EDGE_MAX;
        }
        // Interior cells
        return INTERIOR_MAX;
    }

    /** Utility to output a matrix */
    private static void printMatrix(int[][] matrix) {
        for (int[] row : matrix) {
            for (int val : row) {
                System.out.print(val + " ");
            }
            System.out.println();
        }
    }
}

/** Fast input reader using BufferedReader and StringTokenizer */
class FastReader {
    private final BufferedReader br;
    private StringTokenizer st;

    public FastReader() {
        br = new BufferedReader(new InputStreamReader(System.in));
    }

    /** Returns next token */
    String next() {
        while (st == null || !st.hasMoreTokens()) {
            try {
                st = new StringTokenizer(br.readLine());
            } catch (IOException e) {
                throw new UncheckedIOException(e);
            }
        }
        return st.nextToken();
    }

    /** Reads an int */
    int nextInt() {
        return Integer.parseInt(next());
    }

    /** Reads a long */
    long nextLong() {
        return Long.parseLong(next());
    }

    /** Reads a double */
    double nextDouble() {
        return Double.parseDouble(next());
    }

    /** Reads a whole line */
    String nextLine() {
        try {
            return br.readLine();
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
    }
}

import java.util.Scanner;

/**
 * Solution that reads several test cases.
 * For each test case it validates a matrix against specific limits
 * and, if the matrix is valid, prints a formatted representation of it.
 *
 * <p>Refactoring goals:
 * <ul>
 *   <li>Clear separation of concerns (input, validation, output)</li>
 *   <li>Descriptive naming and constants</li>
 *   <li>Early‑exit validation returning a boolean</li>
 *   <li>Highly readable control flow</li>
 * </ul>
 */
public class Demo01 {

    /** Maximum allowed value for a cell depending on its position. */
    private static final int CORNER_MAX = 2;
    private static final int EDGE_MAX   = 3;
    private static final int INNER_MAX  = 4;

    /**
     * Validates the matrix according to the problem rules.
     *
     * @param matrix the matrix to validate
     * @param rows   number of rows
     * @param cols   number of columns
     * @return {@code true} if every cell respects its limit, {@code false} otherwise
     */
    private static boolean isMatrixValid(int[][] matrix, int rows, int cols) {
        for (int i = 0; i < rows; i++) {
            boolean firstRow = i == 0;
            boolean lastRow  = i == rows - 1;

            for (int j = 0; j < cols; j++) {
                boolean firstCol = j == 0;
                boolean lastCol  = j == cols - 1;

                // Determine the expected maximum value for the current cell
                int maxAllowed;
                if (firstRow && firstCol) {               // corner
                    maxAllowed = CORNER_MAX;
                } else if (firstRow || lastRow) {         // top / bottom edge (non‑corner)
                    maxAllowed = EDGE_MAX;
                } else if (firstCol || lastCol) {         // left / right edge (non‑corner)
                    maxAllowed = EDGE_MAX;
                } else {                                  // inner cell
                    maxAllowed = INNER_MAX;
                }

                if (matrix[i][j] > maxAllowed) {
                    System.out.println("NO");
                    return false;
                }
            }
        }
        return true;
    }

    /**
     * Prints the formatted matrix representation.
     * Each cell is printed with a trailing space, exactly like the original program.
     */
    private static void printFormattedMatrix(int[][] matrix, int rows, int cols) {
        for (int i = 0; i < rows; i++) {
            boolean firstRow = i == 0;
            boolean lastRow  = i == rows - 1;

            for (int j = 0; j < cols; j++) {
                boolean firstCol = j == 0;
                boolean lastCol  = j == cols - 1;

                if (firstRow && firstCol) {               // corner
                    System.out.print("2 ");
                } else if (firstRow || lastRow) {         // top / bottom edge
                    System.out.print("3 ");
                } else if (firstCol || lastCol) {         // left / right edge
                    System.out.print("3 ");
                } else {                                  // inner cell
                    System.out.print("4 ");
                }
            }
            System.out.println(); // move to next line after each row
        }
    }

    /**
     * Handles a single test case: reading input, validating, and printing the result.
     */
    private static void processTestCase(Scanner scanner) {
        int rows = scanner.nextInt();
        int cols = scanner.nextInt();

        int[][] matrix = new int[rows][cols];
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                matrix[i][j] = scanner.nextInt();
            }
        }

        if (isMatrixValid(matrix, rows, cols)) {
            System.out.println("YES");
            printFormattedMatrix(matrix, rows, cols);
        }
        // If the matrix is invalid, {@code isMatrixValid} already printed "NO".
    }

    /** Entry point – reads the number of test cases and processes each one. */
    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            int testCases = scanner.nextInt();
            for (int t = 0; t < testCases; t++) {
                processTestCase(scanner);
            }
        }
    }
}

import java.util.Scanner;

/**
 * Reads a grid, validates that each cell value does not exceed the number of
 * adjacent cells it has, standardizes each cell to that neighbor count, and
 * prints the result.
 *
 * <p>Refactored for readability, maintainability and separation of concerns:
 * <ul>
 *   <li>Input handling is isolated in {@code readGrid}</li>
 *   <li>Validation and standardization logic lives in {@code validateAndStandardize}</li>
 *   <li>Neighbor count calculation is encapsulated in {@code getNeighborCount}</li>
 *   <li>Constants replace magic numbers</li>
 *   <li>Resources are managed with try‑with‑resources</li>
 * </ul>
 */
public class NeighborhoodGrid {

    /** Maximum allowed value for a corner cell (2 adjacent cells). */
    private static final int CORNER_MAX = 2;
    /** Maximum allowed value for an edge (non‑corner) cell (3 adjacent cells). */
    private static final int EDGE_MAX = 3;
    /** Maximum allowed value for an interior cell (4 adjacent cells). */
    private static final int INTERIOR_MAX = 4;

    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            int testCases = scanner.nextInt();

            for (int t = 0; t < testCases; t++) {
                int rows = scanner.nextInt();
                int cols = scanner.nextInt();
                long[][] grid = readGrid(scanner, rows, cols);

                boolean valid = validateAndStandardize(grid, rows, cols);
                if (!valid) {
                    System.out.println("NO");
                    continue;
                }

                System.out.println("YES");
                printGrid(grid);
            }
        }
    }

    /**
     * Reads a {@code rows × cols} grid of {@code long} values from the scanner.
     */
    private static long[][] readGrid(Scanner scanner, int rows, int cols) {
        long[][] grid = new long[rows][cols];
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                grid[r][c] = scanner.nextLong();
            }
        }
        return grid;
    }

    /**
     * Validates each cell against its permissible neighbor count and
     * overwrites the cell with that count.
     *
     * @return {@code true} if all cells satisfy the constraint, otherwise {@code false}
     */
    private static boolean validateAndStandardize(long[][] grid, int n, int m) {
        for (int r = 0; r < n; r++) {
            for (int c = 0; c < m; c++) {
                int neighborCount = getNeighborCount(r, c, n, m);
                if (grid[r][c] > neighborCount) {
                    return false;               // constraint violated
                }
                grid[r][c] = neighborCount;       // standardize the value
            }
        }
        return true;
    }

    /**
     * Computes how many distinct orthogonal neighbours a cell at (row, col)
     * has inside an {@code n × m} grid.
     */
    private static int getNeighborCount(int row, int col, int n, int m) {
        int count = 0;
        if (row > 0) count++;          // cell above exists
        if (row < n - 1) count++;      // cell below exists
        if (col > 0) count++;          // cell to the left exists
        if (col < m - 1) count++;      // cell to the right exists
        return count;
    }

    /**
     * Prints the grid, one value per line, in row‑major order.
     */
    private static void printGrid(long[][] grid) {
        for (long[] row : grid) {
            for (long value : row) {
                System.out.println(value);
            }
        }
    }
}

import java.util.Scanner;

/**
 * Reads multiple test cases. For each case it reads a matrix of integers,
 * validates that every element does not exceed the maximum value allowed for
 * its position (corner ≤2, edge ≤3, interior ≤4) and, if the validation passes,
 * prints "YES" followed by a matrix where corners are 2, edges are 3 and
 * interior cells are 4.
 */
public class Main {

    private static final Scanner SCANNER = new Scanner(System.in);

    public static void main(String[] args) {
        int testCases = SCANNER.nextInt();
        while (testCases-- > 0) {
            processCase();
        }
        SCANNER.close();
    }

    private static void processCase() {
        int n = SCANNER.nextInt();
        int m = SCANNER.nextInt();

        int[][] input = readMatrix(n, m);
        if (!isValid(input, n, m)) {
            System.out.println("NO");
            return;
        }

        int[][] result = buildResultMatrix(n, m);
        System.out.println("YES");
        printMatrix(result);
    }

    private static int[][] readMatrix(int rows, int cols) {
        int[][] matrix = new int[rows][cols];
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                matrix[i][j] = SCANNER.nextInt();
            }
        }
        return matrix;
    }

    private static boolean isValid(int[][] src, int n, int m) {
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                int maxAllowed = maxAllowedFor(i, j, n, m);
                if (src[i][j] > maxAllowed) {
                    return false;
                }
            }
        }
        return true;
    }

    private static int maxAllowedFor(int i, int j, int n, int m) {
        if (isCorner(i, j, n, m)) {
            return 2;
        }
        if (isEdge(i, j, n, m)) {
            return 3;
        }
        // interior cell
        return 4;
    }

    private static boolean isCorner(int i, int j, int n, int m) {
        return (i == 0 || i == n - 1) && (j == 0 || j == m - 1);
    }

    private static boolean isEdge(int i, int j, int n, int m) {
        return (i == 0 || i == n - 1 || j == 0 || j == m - 1)
                && !isCorner(i, j, n, m);
    }

    private static int[][] buildResultMatrix(int n, int m) {
        int[][] out = new int[n][m];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                out[i][j] = maxAllowedFor(i, j, n, m);
            }
        }
        return out;
    }

    private static void printMatrix(int[][] matrix) {
        for (int[] row : matrix) {
            for (int val : row) {
                System.out.print(val + " ");
            }
            System.out.println();
        }
    }
}

import java.io.*;
import java.util.StringTokenizer;

/**
 * Fast scanner that wraps a BufferedReader and a StringTokenizer.
 */
final class FastScanner {
    private final BufferedReader br;
    private StringTokenizer st;

    FastScanner(Reader reader) {
        this.br = new BufferedReader(reader);
    }

    /** Returns the next token or reads a new line if the current tokenizer is empty. */
    private String nextToken() {
        while (st == null || !st.hasMoreTokens()) {
            try {
                String line = br.readLine();
                if (line == null) {
                    return null;
                }
                st = new StringTokenizer(line);
            } catch (IOException e) {
                throw new UncheckedIOException(e);
            }
        }
        return st.nextToken();
    }

    /** Reads the next {@code int}. */
    int nextInt() {
        return Integer.parseInt(nextToken());
    }

    /** Reads the next {@code long}. */
    long nextLong() {
        return Long.parseLong(nextToken());
    }

    /** Reads the next {@code double}. */
    double nextDouble() {
        return Double.parseDouble(nextToken());
    }

    /** Reads the next line (may be {@code null} at EOF). */
    String nextLine() {
        try {
            return br.readLine();
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
    }

    /** @return {@code true} if more tokens are available. */
    boolean hasNext() {
        String token = nextToken();
        if (token == null) {
            return false;
        }
        // Put the token back so it is not lost.
        st = new StringTokenizer(token);
        return true;
    }
}

/**
 * Holds all the logic that validates and transforms the matrix.
 * The constants represent the maximal allowed value for each border type.
 */
final class BorderProcessor {
    private static final int CORNER_MAX = 2;
    private static final int EDGE_MAX   = 3;
    private static final int INTERIOR_MAX = 4;

    private BorderProcessor() { /* utility class */ }

    /**
     * Validates the supplied matrix and, when possible, transforms it into the
     * required form. The transformation modifies the matrix in‑place.
     *
     * @param grid   rectangular integer matrix to be examined
     * @return {@code true} if the matrix satisfies all constraints,
     *         {@code false} otherwise.
     */
    static boolean validateAndTransform(int[][] grid) {
        int n = grid.length;
        int m = grid[0].length;
        boolean possible = true;

        // ---- interior cells (i = 1 .. n‑2, j = 1 .. m‑2) ----
        for (int i = 1; i < n - 1; i++) {
            for (int j = 1; j < m - 1; j++) {
                if (grid[i][j] > INTERIOR_MAX) {
                    possible = false;
                } else {
                    grid[i][j] = INTERIOR_MAX;
                }
            }
        }

        // ---- left and right edges (excluding corners) ----
        for (int i = 1; i < n - 1; i++) {
            if (grid[i][0] > EDGE_MAX) {
                possible = false;
            } else {
                grid[i][0] = EDGE_MAX;
            }
            if (grid[i][m - 1] > EDGE_MAX) {
                possible = false;
            } else {
                grid[i][m - 1] = EDGE_MAX;
            }
        }

        // ---- top and bottom edges (excluding corners) ----
        for (int j = 1; j < m - 1; j++) {
            if (grid[0][j] > EDGE_MAX) {
                possible = false;
            } else {
                grid[0][j] = EDGE_MAX;
            }
            if (grid[n - 1][j] > EDGE_MAX) {
                possible = false;
            } else {
                grid[n - 1][j] = EDGE_MAX;
            }
        }

        // ---- corners ----
        if (grid[0][0] > CORNER_MAX) {
            possible = false;
        } else {
            grid[0][0] = CORNER_MAX;
        }
        if (grid[0][m - 1] > CORNER_MAX) {
            possible = false;
        } else {
            grid[0][m - 1] = CORNER_MAX;
        }
        if (grid[n - 1][0] > CORNER_MAX) {
            possible = false;
        } else {
            grid[n - 1][0] = CORNER_MAX;
        }
        if (grid[n - 1][m - 1] > CORNER_MAX) {
            possible = false;
        } else {
            grid[n - 1][m - 1] = CORNER_MAX;
        }

        return possible;
    }
}

