/**
 * Solution for the “border‑value limits” problem.
 *
 * <p>For each test case the program reads an {@code n × m} matrix of integers.
 * It checks whether every element respects the allowed maximum depending on its
 * position:
 *
 * <ul>
 *   <li>Corners – at most {@code 2}
 *   <li>Edges (but not corners) – at most {@code 3}
 *   <li>Inner cells – at most {@code 4}
 * </ul>
 *
 * <p>If the matrix violates any of those limits the program prints {@code NO};
 * otherwise it prints {@code YES} followed by a pattern that fills the matrix
 * with the same limits (2 for corners, 3 for edges, 4 for inner cells).
 *
 * <p>The implementation is deliberately split into small, well‑named methods
 * and uses clear constants, making it easier to maintain and extend.
 */
public class Main {

    /** Maximum value allowed at a corner of the matrix. */
    private static final int MAX_CORNER = 2;

    /** Maximum value allowed on a non‑corner edge. */
    private static final int MAX_EDGE = 3;

    /** Maximum value allowed in the interior of the matrix. */
    private static final int MAX_INNER = 4;

    /** Enum to describe the position type of a cell. */
    private enum PositionType {
        CORNER,
        EDGE,
        INNER
    }

    /** Fast input helper – mirrors the original {@code FastReader} class. */
    private static final class InputReader {
        private final BufferedReader br;
        private StringTokenizer st;

        InputReader() {
            this.br = new BufferedReader(new InputStreamReader(System.in));
        }

        /** Reads the next token, blocking until one is available. */
        private String nextToken() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    throw new UncheckedIOException(e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(nextToken());
        }

        long nextLong() {
            return Long.parseLong(nextToken());
        }
    }

    /**
     * Determines the type of the cell (corner / edge / inner) and returns the
     * corresponding {@link PositionType}.
     */
    private static PositionType determinePosition(int i, int j, int n, int m) {
        if ((i == 0 && j == 0) || (i == 0 && j == m - 1) ||
            (i == n - 1 && j == 0) || (i == n - 1 && j == m - 1)) {
            return PositionType.CORNER;
        }
        if (i == 0 || j == 0 || i == n - 1 || j == m - 1) {
            return PositionType.EDGE;
        }
        return PositionType.INNER;
    }

    /**
     * Validates the matrix according to the limits described in {@link PositionType}.
     *
     * @param grid the matrix to validate
     * @param n    number of rows
     * @param m    number of columns
     * @return {@code true} if the matrix respects all limits, {@code false} otherwise
     */
    private static boolean isValid(long[][] grid, int n, int m) {
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                PositionType type = determinePosition(i, j, n, m);
                int limit;
                switch (type) {
                    case CORNER -> limit = MAX_CORNER;
                    case EDGE -> limit = MAX_EDGE;
                    case INNER -> limit = MAX_INNER;
                }
                if (grid[i][j] > limit) {
                    return false;
                }
            }
        }
        return true;
    }

    /**
     * Prints the required output for a single test case.
     *
     * @param n number of rows
     * @param m number of columns
     */
    private static void outputSolution(int n, int m) {
        System.out.println("YES");
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                PositionType type = determinePosition(i, j, n, m);
                int value;
                switch (type) {
                    case CORNER -> value = MAX_CORNER;
                    case EDGE -> value = MAX_EDGE;
                    case INNER -> value = MAX_INNER;
                }
                System.out.print(value + " ");
            }
            System.out.println();
        }
    }

    /** Main entry point – processes multiple test cases. */
    public static void main(String[] args) throws IOException {
        InputReader reader = new InputReader();
        PrintWriter out = new PrintWriter(System.out);
        int t = reader.nextInt();

        while (t-- > 0) {
            int n = reader.nextInt();
            int m = reader.nextInt();
            long[][] arr = new long[n][m];

            // read the whole matrix
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    arr[i][j] = reader.nextLong();
                }
            }

            // check if the matrix respects the limits
            if (!isValid(arr, n, m)) {
                out.println("NO");
                continue;
            }

            // everything is fine → print the solution pattern
            outputSolution(n, m);
        }
        out.flush();
    }
}

/**
 * Reads multiple test cases and determines for each if a modified matrix can be built.
 * The modification rule: for each cell, if the count of adjacent cells is smaller than the
 * current value, the value must be kept; otherwise we can replace it with the neighbor count.
 *
 * Maintainability improvements:
 * - Descriptive class and method names.
 * - Extracted helper methods.
 * - Clear separation of concerns (input, processing, output).
 * - Proper exception handling.
 */
public class MatrixProcessor {

    /** Entry point. */
    public static void main(String[] args) {
        try (FastScanner fs = new FastScanner(System.in)) {
            int t = fs.nextInt();
            while (t-- > 0) {
                solveSingleCase(fs);
            }
        } catch (IOException e) {
            // In a contest environment we can ignore, but logging would be better.
            e.printStackTrace();
        }
    }

    /** Reads one test case, processes it and prints the answer. */
    private static void solveSingleCase(FastScanner fs) throws IOException {
        int n = fs.nextInt();
        int m = fs.nextInt();

        boolean canBeFixed = true;
        int[][] result = new int[n][m];

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                int current = fs.nextInt();
                int neighborCount = neighborCount(i, j, n, m);

                if (neighborCount < current) {
                    canBeFixed = false;          // cannot reduce this cell
                    result[i][j] = current;      // keep original value
                } else {
                    result[i][j] = neighborCount; // replace with allowed count
                }
            }
        }

        if (canBeFixed) {
            System.out.println("YES");
            printMatrix(result);
        } else {
            System.out.println("NO");
        }
    }

    /** Returns the number of orthogonal neighbours a cell (i,j) has inside an n×m grid. */
    private static int neighborCount(int i, int j, int n, int m) {
        int count = 0;
        if (i > 0) count++;
        if (i < n - 1) count++;
        if (j > 0) count++;
        if (j < m - 1) count++;
        return count;
    }

    /** Prints the given matrix row by row. */
    private static void printMatrix(int[][] matrix) {
        for (int[] row : matrix) {
            for (int value : row) {
                System.out.print(value + " ");
            }
            System.out.println();
        }
    }

    /**
     * Fast scanner based on a reusable byte buffer.
     * Provides nextInt, nextLong, next and generic next token methods.
     */
    private static final class FastScanner {
        private final byte[] buffer = new byte[2048];
        private int bufferIndex = 0;
        private int bufferLength = 0;
        private final InputStream input;

        FastScanner(InputStream input) {
            this.input = input;
        }

        private int read() throws IOException {
            if (bufferIndex >= bufferLength) {
                bufferLength = input.read(buffer);
                bufferIndex = 0;
                if (bufferLength <= 0) {
                    return -1;
                }
            }
            return buffer[bufferIndex++];
        }

        /** Skips whitespace characters. */
        private int skipWhitespace() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ');
            return c;
        }

        /** Reads the next token as a string. */
        String next() throws IOException {
            int c = skipWhitespace();
            StringBuilder sb = new StringBuilder();
            while (c > ' ') {
                sb.append((char) c);
                c = read();
            }
            return sb.toString();
        }

        /** Reads next token as int. */
        int nextInt() throws IOException {
            int sign = 1;
            int c = skipWhitespace();
            if (c == '-' || c == '+') {
                sign = (c == '-') ? -1 : 1;
                c = read();
            }
            int value = 0;
            while (c >= '0' && c <= '9') {
                value = value * 10 + (c - '0');
                c = read();
            }
            return sign * value;
        }

        long nextLong() throws IOException {
            long sign = 1;
            int c = skipWhitespace();
            if (c == '-' || c == '+') {
                sign = (c == '-') ? -1 : 1;
                c = read();
            }
            long value = 0;
            while (c >= '0' && c <= '9') {
                value = value * 10 + (c - '0');
                c = read();
            }
            return sign * value;
        }
    }
}

import java.util.Scanner;

/**
 * Refactored solution for the problem.
 * The program reads several test cases, validates the input matrix against
 * specific constraints and, when valid, prints a predefined pattern.
 */
public class Solve {

    /** Maximum value that may appear inside the matrix. */
    private static final int MAX_VALUE = 4;

    /** Maximum value allowed at the four corners of the matrix. */
    private static final int MAX_CORNER = 2;

    /** Maximum value allowed on the inner cells of each border (excluding corners). */
    private static final int MAX_BORDER_INTERIOR = 3;

    public static void main(String[] args) {
        // Try‑with‑resources guarantees the Scanner is closed automatically.
        try (Scanner scanner = new Scanner(System.in)) {
            int testCases = scanner.nextInt();
            for (int tc = 0; tc < testCases; tc++) {
                solveCase(scanner);
            }
        }
    }

    /**
     * Handles a single test case:
     * reads the matrix dimensions and the matrix itself,
     * checks the validation rules, and prints the appropriate output.
     */
    private static void solveCase(Scanner sc) {
        int rows = sc.nextInt();
        int cols = sc.nextInt();
        int[][] grid = new int[rows][cols];

        // Populate the matrix.
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                grid[i][j] = sc.nextInt();
            }
        }

        // If the matrix does not satisfy the validation rules, print "NO".
        if (!isValid(grid, rows, cols)) {
            System.out.println("NO");
            return;
        }

        // Otherwise print "YES" followed by the required pattern.
        System.out.println("YES");
        printPattern(rows, cols);
    }

    /**
     * Determines whether the supplied matrix complies with all constraints.
     *
     * @param grid   the matrix to validate
     * @param n      number of rows
     * @param m      number of columns
     * @return {@code true} if the matrix is valid, {@code false} otherwise
     */
    private static boolean isValid(int[][] grid, int n, int m) {
        // 1. No element may be larger than the global maximum.
        for (int[] row : grid) {
            for (int val : row) {
                if (val > MAX_VALUE) {
                    return false;
                }
            }
        }

        // 2. Corner cells must not exceed MAX_CORNER.
        if (grid[0][0] > MAX_CORNER ||
            grid[n - 1][0] > MAX_CORNER ||
            grid[0][m - 1] > MAX_CORNER ||
            grid[n - 1][m - 1] > MAX_CORNER) {
            return false;
        }

        // 3. Interior cells of each border (edges without corners) must not exceed MAX_BORDER_INTERIOR.
        // Top and bottom borders (excluding corners).
        for (int j = 1; j < m - 1; j++) {
            if (grid[0][j] > MAX_BORDER_INTERIOR) return false;          // top border
            if (grid[n - 1][j] > MAX_BORDER_INTERIOR) return false;      // bottom border
        }
        // Left and right borders (excluding corners).
        for (int i = 1; i < n - 1; i++) {
            if (grid[i][0] > MAX_BORDER_INTERIOR) return false;          // left border
            if (grid[i][m - 1] > MAX_BORDER_INTERIOR) return false;      // right border
        }

        return true;
    }

    /**
     * Prints the fixed pattern that depends only on the matrix dimensions.
     * Interior cells are 4, edge (but not corner) cells are 3,
     * and corner cells are 2.
     */
    private static void printPattern(int n, int m) {
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                int value = MAX_VALUE;
                // Subtract 1 for each border the cell belongs to.
                if (i == 0 || i == n - 1) {
                    value--;
                }
                if (j == 0 || j == m - 1) {
                    value--;
                }
                System.out.print(value + " ");
            }
            System.out.println();
        }
    }
}

/**
 * Fast scanner that works with {@link InputStream}. It provides
 * convenient methods to read primitive values without using
 * {@link Scanner}.
 */
final class FastScanner {
    private final InputStream in;
    private final byte[] buffer = new byte[16_384];
    private int ptr = 0, len = 0;

    FastScanner(InputStream in) {
        this.in = new BufferedInputStream(in);
    }

    /** Skip leading whitespace and return next byte. */
    private int nextByte() {
        if (ptr >= len) {
            len = in.read(buffer);
            ptr = 0;
            if (len <= 0) throw new EOFException();
        }
        return buffer[ptr++];
    }

    /** Skip whitespace and return next non‑whitespace character. */
    private int skip() {
        int b;
        while ((b = nextByte()) != -1 && Character.isWhitespace(b)) { }
        return b;
    }

    /** Read next signed/unsigned integer. */
    int nextInt() {
        int sign = 1, c = skip();
        if (c == '-') {
            sign = -1;
            c = nextByte();
        }
        int value = 0;
        while (c >= '0' && c <= '9') {
            value = value * 10 + (c - '0');
            c = nextByte();
        }
        return sign * value;
    }

    /** Read next line (including spaces). */
    String nextLine() {
        StringBuilder sb = new StringBuilder();
        int c;
        while ((c = nextByte()) != -1 && !Character.isWhitespace(c)) {
            sb.append((char) c);
        }
        return sb.toString();
    }
}

/**
 * Core solver for the “adjacent cells” problem.
 * It reads the test case, decides whether a feasible “ideal” matrix exists,
 * and prints the result.
 */
final class Solver {
    /** Directions used to count neighboring cells. */
    private static final int[][] DIRS = {
            { -1, 0 }, { 1, 0 }, { 0, -1 }, { 0, 1 }
    };

    /** Reads a single test case and prints the answer. */
    private void solve(FastScanner fs, PrintWriter out) {
        int rows = fs.nextInt();
        int cols = fs.nextInt();

        int[][] demand = new int[rows][cols];
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                demand[r][c] = fs.nextInt();
            }
        }

        // Build the “ideal” matrix where each cell holds the count of its neighbours.
        int[][] ideal = computeIdeal(rows, cols);

        // Verify that every demand is satisfied.
        boolean feasible = true;
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (ideal[r][c] < demand[r][c]) {
                    feasible = false;
                    break;
                }
            }
            if (!feasible) break;
        }

        if (feasible) {
            out.println("YES");
            for (int r = 0; r < rows; r++) {
                StringBuilder line = new StringBuilder();
                for (int c = 0; c < cols; c++) {
                    line.append(ideal[r][c]).append(' ');
                }
                out.println(line.toString().trim());
            }
        } else {
            out.println("NO");
        }
    }

    /**
     * Constructs the ideal matrix.
     *
     * @param rows number of rows
     * @param cols number of columns
     * @return a 2‑D array where each cell equals the number of adjacent cells
     *         (up, down, left, right) that exist inside the grid.
     */
    private int[][] computeIdeal(int rows, int cols) {
        int[][] ideal = new int[rows][cols];
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                int neighbourCount = 0;
                for (int[] d : DIRS) {
                    int nr = r + d[0];
                    int nc = c + d[1];
                    if (nr >= 0 && nr < rows && nc >= 0 && nc < cols) {
                        neighbourCount++;
                    }
                }
                ideal[r][c] = neighbourCount;
            }
        }
        return ideal;
    }
}

/**
 * Program entry point. It wires everything together.
 */
public final class Main {
    private final FastScanner scanner;
    private final PrintWriter writer;

    /** Constructor used when running from the command line with standard I/O. */
    public Main() {
        this(null, System.out);
    }

    /** Private constructor for programmatic testing (allows custom I/O). */
    private Main(FastScanner scanner, PrintWriter writer) {
        this.scanner = scanner == null ? new FastScanner(System.in) : scanner;
        this.writer = new PrintWriter(new OutputStreamWriter(System.out), true);
    }

    /** Main logic – iterates over test cases. */
    public void run() {
        int t = scanner.nextInt();
        while (t-- > 0) {
            solveSingleCase();
        }
        writer.flush();
    }

    /** Reads one test case and delegates to {@link Solver}. */
    private void solveSingleCase() {
        // The solver itself does not need the FastScanner object,
        // it only needs to read from it – therefore we expose a small helper.
        Solver solver = new Solver();
        solver.solve(scanner, writer);
    }

    /** Simple demonstration driver – mimics original behaviour. */
    public static void main(String[] args) {
        new Main().run();
    }
}

import java.util.Scanner;

/**
 * Refactored version of the original program.
 * The logic is unchanged but the code is now split into small,
 * well‑named methods, uses meaningful constants and avoids
 * magic numbers throughout.
 */
public class Solution {

    /** Thresholds used for validation and transformation */
    private static final int CORNER_THRESHOLD = 3;   // corner cells must be < 3
    private static final int EDGE_THRESHOLD     = 4;   // edge (non‑corner) cells must be < 4
    private static final int INNER_THRESHOLD    = 5;   // inner cells must be < 5

    /** Values we assign when a cell meets its threshold */
    private static final int CORNER_VALUE   = 2;   // set when < CORNER_THRESHOLD
    private static final int EDGE_VALUE     = 3;   // set when < EDGE_THRESHOLD
    private static final int INNER_VALUE    = 4;   // set when < INNER_THRESHOLD

    /** Main entry point */
    public static void main(String[] args) {
        try (Scanner sc = new Scanner(System.in)) {
            int t = sc.nextInt();
            for (int caseIdx = 0; caseIdx < t; caseIdx++) {
                int rows = sc.nextInt();
                int cols = sc.nextInt();
                int[][] board = readMatrix(sc, rows, cols);

                boolean ok = validateAndTransform(board, rows, cols);
                if (!ok) {
                    System.out.println("NO");
                } else {
                    System.out.println("YES");
                    printBoard(board);
                }
            }
        }
    }

    /**
     * Reads a matrix of {@code rows} × {@code cols} from the scanner.
     */
    private static int[][] readMatrix(Scanner sc, int rows, int cols) {
        int[][] matrix = new int[rows][cols];
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                matrix[r][c] = sc.nextInt();
            }
        }
        return matrix;
    }

    /**
     * Performs the validation steps and in‑place transformation.
     *
     * @return {@code true} if the board satisfies all constraints,
     *         {@code false} otherwise (and the board may be partially
     *         transformed).
     */
    private static boolean validateAndTransform(int[][] board, int rows, int cols) {
        // ----- 1. Corner cells -------------------------------------------------
        if (!processCorners(board)) {
            return false;
        }

        // ----- 2. First & last column (excluding corners) ----------------------
        if (!processEdges(board, rows, cols, true)) { // true = first column
            return false;
        }
        if (!processEdges(board, rows, cols, false)) { // false = last column
            return false;
        }

        // ----- 3. First & last row (excluding corners) -------------------------
        if (!processEdges(board, rows, cols, true, false)) { // first row, not first column
            return false;
        }
        if (!processEdges(board, rows, cols, false, false)) { // last row, not first column
            return false;
        }

        // ----- 4. Interior cells -----------------------------------------------
        return processInterior(board, rows, cols);
    }

    /** Processes the four corner cells. */
    private static boolean processCorners(int[][] board) {
        int r = 0;
        int[] cols = {0, board[0].length - 1};
        for (int c : cols) {
            if (board[r][c] >= CORNER_THRESHOLD) {
                return false;
            }
            board[r][c] = CORNER_VALUE;
        }

        // bottom row corners
        r = board.length - 1;
        for (int c : cols) {
            if (board[r][c] >= CORNER_THRESHOLD) {
                return false;
            }
            board[r][c] = CORNER_VALUE;
        }
        return true;
    }

    /**
     * Processes a set of cells that belong to a given edge.
     *
     * @param first indicates whether the edge is the first side (true) or the last side (false)
     * @param isColumn indicates whether the edge is a column edge (true) or a row edge (false)
     */
    private static boolean processEdges(int[][] board, int rows, int cols,
                                        boolean firstEdge, boolean isColumn) {
        int start, end, step;
        if (isColumn) { // processing a column (first or last)
            start = firstEdge ? 1 : 1;                     // row start (skip corners)
            end   = rows - 1;                              // row end (skip last row corner)
            step  = 1;
        } else {        // processing a row (first or last)
            start = firstEdge ? 1 : 1;                     // column start (skip corners)
            end   = cols - 1;                              // column end (skip last column corner)
            step  = 1;
        }

        // The loop bounds are the same regardless of direction; we just vary the index variable.
        for (int i = start; i < end; i++) {
            int valIdx = isColumn ? i : start; // actually we need the column/row index differently
            // Simpler: directly use the correct cell based on parameters
            int row = isColumn ? i : (firstEdge ? 0 : rows - 1);
            int col = isColumn ? (firstEdge ? 0 : cols - 1) : i;

            if (board[row][col] >= EDGE_THRESHOLD) {
                return false;
            }
            board[row][col] = EDGE_VALUE;
        }
        return true;
    }

    /** Convenience overload for processing row edges (first/last row). */
    private static boolean processEdges(int[][] board, int rows, int cols,
                                        boolean firstEdge, boolean rowEdge) {
        // firstEdge is ignored here; we always iterate over the inner part of the selected row
        int fixedRow = firstEdge ? 0 : rows - 1;
        for (int col = 1; col < cols - 1; col++) {
            if (board[fixedRow][col] >= EDGE_THRESHOLD) {
                return false;
            }
            board[fixedRow][col] = EDGE_VALUE;
        }
        return true;
    }

    /** Processes the interior (non‑border) cells. */
    private static boolean processInterior(int[][] board, int rows, int cols) {
        for (int r = 1; r < rows - 1; r++) {
            for (int c = 1; c < cols - 1; c++) {
                if (board[r][c] >= INNER_THRESHOLD) {
                    return false;
                }
                board[r][c] = INNER_VALUE;
            }
        }
        return true;
    }

    /** Prints the board row by row. */
    private static void printBoard(int[][] board) {
        for (int[] row : board) {
            for (int value : row) {
                System.out.print(value + " ");
            }
            System.out.println();
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Solution for the problem.
 * Reads multiple test cases, each consisting of a matrix size n × m and the matrix values.
 * Determines whether a valid filling exists and prints the filled matrix if so.
 */
public class Main {

    /** Fast scanner using BufferedReader and StringTokenizer */
    private static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner() throws IOException {
            this.br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    throw new UncheckedIOException(e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        long nextLong() {
            return Long.parseLong(next());
        }

        double nextDouble() {
            return Double.parseDouble(next());
        }

        String nextLine() {
            try {
                return br.readLine();
            } catch (IOException e) {
                throw new UncheckedIOException(e);
            }
        }
    }

    /** Constants representing cell values */
    private static final int CORNER_VALUE = 2;
    private static final int EDGE_VALUE = 3;
    private static final int INTERIOR_VALUE = 4;

    public static void main(String[] args) throws IOException {
        try (FastScanner fs = new FastScanner();
             PrintWriter out = new PrintWriter(System.out)) {

            int T = fs.nextInt();

            while (T-- > 0) {
                solveCase(fs, out);
            }
        }
    }

    /** Handles a single test case. */
    private static void solveCase(FastScanner fs, PrintWriter out) {
        int n = fs.nextInt();
        int m = fs.nextInt();

        // Read matrix
        int[][] grid = readMatrix(fs, n, m);

        // Preliminary checks
        if (!isValid(grid)) {
            out.println("NO");
            return;
        }

        // Set corner cells to the required value
        setCorners(grid);

        // Fill remaining border cells with 3, ensuring we never exceed the allowed maximum
        if (!fillBorders(grid)) {
            out.println("NO");
            return;
        }

        // Fill interior with 4
        fillInterior(grid);

        // If we reach here, a valid configuration exists
        out.println("YES");
        printMatrix(grid, out);
    }

    /** Reads the n × m integer matrix from the scanner. */
    private static int[][] readMatrix(FastScanner fs, int n, int m) {
        int[][] mat = new int[n][m];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                mat[i][j] = fs.nextInt();
            }
        }
        return mat;
    }

    /**
     * Checks the preliminary constraints:
     * <ul>
     *   <li>Maximum value in the whole matrix must not exceed 4.</li>
     *   <li>All four corner cells must be at most 2.</li>
     * </ul>
     */
    private static boolean isValid(int[][] grid) {
        int max = 0;
        for (int[] row : grid) {
            for (int val : row) {
                if (val > max) {
                    max = val;
                }
            }
        }
        if (max > 4) {
            return false;
        }

        int rows = grid.length;
        int cols = grid[0].length;
        if (grid[0][0] > 2 || grid[0][cols - 1] > 2
                || grid[rows - 1][0] > 2 || grid[rows - 1][cols - 1] > 2) {
            return false;
        }
        return true;
    }

    /** Sets the four corner cells to the constant CORNER_VALUE. */
    private static void setCorners(int[][] grid) {
        grid[0][0] = CORNER_VALUE;
        grid[0][grid[0].length - 1] = CORNER_VALUE;
        grid[grid.length - 1][0] = CORNER_VALUE;
        grid[grid.length - 1][grid[0].length - 1] = CORNER_VALUE;
    }

    /**
     * Attempts to fill the remaining border cells with EDGE_VALUE (3).
     * Returns false if at any point the maximum value would exceed the allowed limit (3 for edges).
     */
    private static boolean fillBorders(int[][] grid) {
        int rows = grid.length;
        int cols = grid[0].length;

        int currentMax = 0;

        // Top and bottom rows, excluding corners
        for (int j = 1; j < cols - 1; j++) {
            currentMax = Math.max(currentMax, grid[0][j]);
            if (currentMax < 4) {
                grid[0][j] = EDGE_VALUE;
            } else {
                break;
            }

            currentMax = Math.max(currentMax, grid[rows - 1][j]);
            if (currentMax < 4) {
                grid[rows - 1][j] = EDGE_VALUE;
            } else {
                break;
            }
        }

        // Left and right columns, excluding corners
        for (int i = 1; i < rows - 1; i++) {
            currentMax = Math.max(currentMax, grid[i][0]);
            if (currentMax < 4) {
                grid[i][0] = EDGE_VALUE;
            } else {
                break;
            }

            currentMax = Math.max(currentMax, grid[i][cols - 1]);
            if (currentMax < 4) {
                grid[i][cols - 1] = EDGE_VALUE;
            } else {
                break;
            }
        }

        // After filling, ensure no cell exceeds the allowed maximum for its category
        // (edges must be <= 3, interior will be set to 4 later)
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if ((i == 0 || i == rows - 1 || j == 0 || j == cols - 1) && grid[i][j] > 3) {
                    return false;
                }
            }
        }
        return true;
    }

    /** Fills every non‑border cell with the interior constant (4). */
    private static void fillInterior(int[][] grid) {
        int rows = grid.length;
        int cols = grid[0].length;
        for (int i = 1; i < rows - 1; i++) {
            for (int j = 1; j < cols - 1; j++) {
                grid[i][j] = INTERIOR_VALUE;
            }
        }
    }

    /** Prints the matrix to the provided PrintWriter, separating values by a space and rows by newline. */
    private static void printMatrix(int[][] grid, PrintWriter out) {
        for (int[] row : grid) {
            for (int j = 0; j < grid[0].length; j++) {
                out.print(row[j]);
                if (j < grid[0].length - 1) {
                    out.print(' ');
                }
            }
            out.println();
        }
    }
}

