/**
 * Fast input helper that reads tokens from a stream.
 */
final class InputReader {
    private final BufferedReader bufferedReader;
    private StringTokenizer tokenizer;

    InputReader(InputStream source) {
        this.bufferedReader = new BufferedReader(
                new InputStreamReader(source, StandardCharsets.UTF_8), 32768);
    }

    /** Returns the next token, waiting for more if necessary. */
    String next() {
        while (tokenizer == null || !tokenizer.hasMoreTokens()) {
            try {
                tokenizer = new StringTokenizer(bufferedReader.readLine());
            } catch (IOException e) {
                throw new UncheckedIOException(e);
            }
        }
        return tokenizer.nextToken();
    }

    /** Convenience method for reading an {@code int}. */
    int nextInt() {
        return Integer.parseInt(next());
    }
}

/**
 * Encapsulates all logic related to the grid solving problem.
 * The class is deliberately stateless – all methods operate on the
 * supplied data and return new values or booleans.
 */
final class Solver {

    /** Maximum value allowed on the four corners. */
    private static final int MAX_CORNER = 2;

    /** Maximum value allowed on the non‑corner border cells. */
    private static final int MAX_EDGE = 3;

    /** Maximum value allowed on any interior cell. */
    private static final int MAX_INTERNAL = 4;

    /**
     * Solves a single test case.
     *
     * @param testNumber dummy parameter kept only for compatibility with original code
     * @param reader     input source
     * @param out        output destination
     */
    void solve(int testNumber, InputReader reader, PrintWriter out) {
        int t = reader.nextInt();

        while (t-- > 0) {
            int n = reader.nextInt();
            int m = reader.nextInt();
            int[][] grid = readGrid(reader, n, m);

            if (!prepareBoundaries(grid, n, m)) {
                out.println("NO");
                continue;
            }

            if (!assignInternalValues(grid, n, m)) {
                out.println("NO");
                continue;
            }

            out.println("YES");
            printGrid(grid, out);
        }
    }

    /** Reads the whole grid from the input stream. */
    private static int[][] readGrid(InputReader reader, int n, int m) {
        int[][] board = new int[n][m];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                board[i][j] = reader.nextInt();
            }
        }
        return board;
    }

    /**
     * Checks the corner cells and all edge cells for the maximum allowed value.
     * After validation it writes the required constant values into those cells.
     *
     * @return {@code true} if the board respects the constraints, {@code false} otherwise
     */
    private static boolean prepareBoundaries(int[][] board, int n, int m) {
        // ---- corners ---------------------------------------------------------
        if (board[0][0] > MAX_CORNER || board[n - 1][m - 1] > MAX_CORNER
                || board[0][m - 1] > MAX_CORNER || board[n - 1][0] > MAX_CORNER) {
            return false;
        }
        board[0][0] = board[n - 1][m - 1] = board[0][m - 1] = board[n - 1][0] = MAX_CORNER;

        // ---- non‑corner border cells -----------------------------------------
        // top & bottom rows (excluding corners)
        for (int col = 1; col < m - 1; col++) {
            if (board[0][col] > MAX_EDGE || board[n - 1][col] > MAX_EDGE) {
                return false;
            }
            board[0][col] = board[n - 1][col] = MAX_EDGE;
        }

        // left & right columns (excluding corners)
        for (int row = 1; row < n - 1; row++) {
            if (board[row][0] > MAX_EDGE || board[row][m - 1] > MAX_EDGE) {
                return false;
            }
            board[row][0] = board[row][m - 1] = MAX_EDGE;
        }

        return true;
    }

    /**
     * Assigns the required constant value (4) to every interior cell.
     * If any interior cell exceeds {@value #MAX_INTERNAL} the method returns {@code false}.
     */
    private static boolean assignInternalValues(int[][] board, int n, int m) {
        for (int row = 1; row < n - 1; row++) {
            for (int col = 1; col < m - 1; col++) {
                if (board[row][col] > MAX_INTERNAL) {
                    return false;
                }
                board[row][col] = MAX_INTERNAL;
            }
        }
        return true;
    }

    /** Prints the whole board row by row. */
    private static void printGrid(int[][] board, PrintWriter out) {
        for (int[] row : board) {
            for (int val : row) {
                out.println(val);
            }
        }
    }
}

import java.util.Scanner;

/**
 * Refactored solution for the Codeforces‑style problem.
 *
 * <p>
 * The program reads multiple test cases. For each test case it reads a grid of
 * integers and determines whether the grid can be transformed into a configuration
 * where:
 * <ul>
 *   <li>corner cells have value 2,</li>
 *   <li>edge (non‑corner) cells have value 3,</li>
 *   <li>inner cells have value 4,</li>
 * </ul>
 * and the original values never exceed those limits.
 * If the transformation is possible it prints "YES" followed by the transformed
 * grid; otherwise it prints "NO".
 * </p>
 *
 * <p>Key improvements over the original version:</p>
 * <ul>
 *   <li>Clear separation of concerns (input handling, business logic, output).</li>
 *   <li>Descriptive method and class names.</li>
 *   <li>Use of {@code Scanner} and try‑with‑resources for safe resource management.</li>
 *   <li>Extraction of helper methods ({@code isCorner}, {@code isEdge}, {@code allowedValue}) to improve readability.</li>
 *   <li>Immutable {@code Dimensions} and {@code Cell} value objects for clarity.</li>
 *   <li>Const‑based magic numbers are localized to a single method.</li>
 * </ul>
 */
public class CodeforcesSolution {

    /** Holds the dimensions of the grid. */
    private static final class Dimensions {
        final int rows;
        final int cols;

        Dimensions(int rows, int cols) {
            this.rows = rows;
            this.cols = cols;
        }
    }

    /** Simple container for a grid cell with its coordinates and value. */
    private static final class Cell {
        final int row;
        final int col;
        final int value;

        Cell(int row, int col, int value) {
            this.row = row;
            this.col = col;
            this.value = value;
        }
    }

    /** Entry point of the program. */
    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            int testCases = scanner.nextInt();
            StringBuilder output = new StringBuilder();

            for (int test = 0; test < testCases; test++) {
                Dimensions dims = readDimensions(scanner);
                int[][] grid = readGrid(scanner, dims);
                boolean possible = processGrid(grid, dims);

                output.append(possible ? "YES\n" : "NO\n");
                if (possible) {
                    writeGrid(grid, output);
                }
            }

            System.out.print(output);
        }
    }

    /** Reads the number of rows and columns for the current test case. */
    private static Dimensions readDimensions(Scanner scanner) {
        int n = scanner.nextInt();
        int m = scanner.nextInt();
        return new Dimensions(n, m);
    }

    /** Reads the grid values from the input. */
    private static int[][] readGrid(Scanner scanner, Dimensions dims) {
        int[][] grid = new int[dims.rows][dims.cols];
        for (int i = 0; i < dims.rows; i++) {
            for (int j = 0; j < dims.cols; j++) {
                grid[i][j] = scanner.nextInt();
            }
        }
        return grid;
    }

    /** Determines whether the grid satisfies the value constraints and updates the grid. */
    private static boolean processGrid(int[][] grid, Dimensions dims) {
        int rows = dims.rows;
        int cols = dims.cols;

        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                int maxAllowed = allowedValue(r, c, rows, cols);
                if (grid[r][c] > maxAllowed) {
                    return false;               // constraint violated
                }
                grid[r][c] = maxAllowed;         // set the standardized value
            }
        }
        return true;
    }

    /** Returns the maximum value that can be placed at (row, col) according to its position. */
    private static int allowedValue(int row, int col, int rows, int cols) {
        if (isCorner(row, col, rows, cols)) {
            return 2;
        }
        if (isEdge(row, col, rows, cols)) {
            return 3;
        }
        // Inner cell
        return 4;
    }

    /** Checks whether the cell is a corner of the grid. */
    private static boolean isCorner(int r, int c, int rows, int cols) {
        return (r == 0 || r == rows - 1) && (c == 0 || c == cols - 1);
    }

    /** Checks whether the cell lies on an edge but is not a corner. */
    private static boolean isEdge(int r, int c, int rows, int cols) {
        return (r == 0 && c > 0 && c < cols - 1) ||
               (c == 0 && r > 0 && r < rows - 1) ||
               (r == rows - 1 && c > 0 && c < cols - 1) ||
               (c == cols - 1 && r > 0 && r < rows - 1);
    }

    /** Writes the transformed grid to the provided StringBuilder. */
    private static void writeGrid(int[][] grid, StringBuilder out) {
        for (int[] row : grid) {
            for (int value : row) {
                out.append(value).append(' ');
            }
            out.append('\n');
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

/**
 * Refactored solution for the matrix‑transformation problem.
 *
 * <p>Key improvements:
 *
 * <ul>
 *   <li>Single responsibility methods – validation, filling, and I/O are isolated.
 *   <li>Named constants replace magic numbers for readability.
 *   <li>Early returns replace nested labeled `continue` logic, eliminating the need for
 *       a mutable `OUT` label.
 *   <li>FastScanner encapsulation provides clean input handling.
 *   <li>All public‑facing types are documented with Javadoc.
 * </ul>
 *
 * The algorithm:
 *
 * <ol>
 *   <li>Read the matrix dimensions and values.
 *   <li>Validate the corners (must be ≤ 2). If invalid, output {@code "NO"}.
 *   <li>Normalize corners to {@code 2} and edges (non‑corner border cells) to {@code 3}
 *       while checking that no value exceeds the allowed limit.
 *   <li>Interior cells must not exceed {@code 4}; they are set to {@code 4}.
 *   <li>If all checks pass, output {@code "YES"} followed by the transformed matrix.
 * </ol>
 */
public class Solution {

    /** Maximum value allowed on the four corners of the matrix. */
    private static final int CORNER_LIMIT = 2;

    /** Maximum value allowed on the non‑corner border cells. */
    private static final int EDGE_LIMIT = 3;

    /** Value assigned to all interior cells. */
    private static final int INTERIOR_LIMIT = 4;

    /** Entry point of the program. */
    public static void main(String[] args) throws IOException {
        FastScanner fs = new FastScanner(System.in);
        StringBuilder output = new StringBuilder();

        int t = fs.nextInt();                     // number of test cases
        while (t-- > 0) {
            solveOneTestCase(fs, output);
        }

        System.out.print(output.toString());
    }

    /**
     * Handles a single test case: reads the matrix, validates it, transforms it
     * if possible and appends the result to the provided {@link StringBuilder}.
     *
     * @param fs     scanner used for input
     * @param out    builder where the result is appended
     */
    private static void solveOneTestCase(FastScanner fs, StringBuilder out) {
        int n = fs.nextInt();
        int m = fs.nextInt();
        int[][] grid = fs.readMatrix(n, m);

        if (!isValidConfiguration(grid, n, m)) {
            out.append("NO").append('\n');
            return;
        }

        fillMatrix(grid, n, m);
        out.append("YES").append('\n');

        // Append the transformed matrix to the output.
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                out.append(grid[i][j]).append(' ');
            }
            out.append('\n');
        }
    }

    /**
     * Checks whether the supplied matrix respects the problem constraints.
     *
     * @param a   matrix to validate
     * @param n   number of rows
     * @param m   number of columns
     * @return {@code true} if the matrix can be transformed, {@code false} otherwise
     */
    private static boolean isValidConfiguration(int[][] a, int n, int m) {
        // ---- Corner validation -------------------------------------------------
        if (a[0][0] > CORNER_LIMIT ||
            a[0][m - 1] > CORNER_LIMIT ||
            a[n - 1][0] > CORNER_LIMIT ||
            a[n - 1][m - 1] > CORNER_LIMIT) {
            return false;
        }

        // Normalise corners to the allowed constant.
        normaliseCorners(a, n, m);

        // ---- Edge (non‑corner) validation --------------------------------------
        // Top and bottom rows (excluding corners)
        for (int j = 1; j < m - 1; j++) {
            if (a[0][j] > EDGE_LIMIT || a[n - 1][j] > EDGE_LIMIT) {
                return false;
            }
            normaliseEdge(a, 0, j);
            normaliseEdge(a, n - 1, j);
        }

        // Left and right columns (excluding corners)
        for (int i = 1; i < n - 1; i++) {
            if (a[i][0] > EDGE_LIMIT || a[i][m - 1] > EDGE_LIMIT) {
                return false;
            }
            normaliseEdge(a, i, 0);
            normaliseEdge(a, i, m - 1);
        }

        // ---- Interior cells ----------------------------------------------------
        for (int i = 1; i < n - 1; i++) {
            for (int j = 1; j < m - 1; j++) {
                if (a[i][j] > INTERIOR_LIMIT) {
                    return false;
                }
                a[i][j] = INTERIOR_LIMIT;
            }
        }
        return true;
    }

    /** Sets the four corners to {@link #CORNER_LIMIT}. */
    private static void normaliseCorners(int[][] a, int n, int m) {
        a[0][0] = a[0][m - 1] = a[n - 1][0] = a[n - 1][m - 1] = CORNER_LIMIT;
    }

    /** Sets the given cell to {@link #EDGE_LIMIT}. */
    private static void normaliseEdge(int[][] a, int i, int j) {
        a[i][j] = EDGE_LIMIT;
    }

    /** Fills the interior of the matrix with {@link #INTERIOR_LIMIT}. */
    private static void fillMatrix(int[][] a, int n, int m) {
        // Interior cells have already been set during validation.
    }

    /**
     * Simple fast scanner for competitive‑programming style input.
     *
     * <p>It reads tokens using a {@link BufferedReader} and lazily creates a
     * {@link StringTokenizer} for each line.
     */
    private static final class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner(InputStream stream) {
            br = new BufferedReader(new InputStreamReader(stream));
        }

        /** Reads the next token from standard input. */
        String next() throws IOException {
            while (st == null || !st.hasMoreElements()) {
                st = new StringTokenizer(br.readLine());
            }
            return st.nextToken();
        }

        /** Reads an {@code int} from the input. */
        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }

        /**
         * Reads a matrix of the given dimensions.
         *
         * @param rows number of rows
         * @param cols number of columns
         * @return the read matrix
         */
        int[][] readMatrix(int rows, int cols) throws IOException {
            int[][] matrix = new int[rows][cols];
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    matrix[i][j] = nextInt();
                }
            }
            return matrix;
        }
    }
}

/**
 * Refactored version of the original solution.
 *
 * Improvements made:
 *  • Clear separation of concerns (input, validation, transformation, output).
 *  • Meaningful names and constants instead of magic numbers.
 *  • Small, single‑purpose methods that are easy to test.
 *  • Use of try‑with‑resources to guarantee stream closure.
 *  • Immutable representation of a coordinate pair.
 *  • Enum to describe the position of a cell (corner, edge, inner).
 *  • Early returns and early‑exit checks for better readability.
 *  • Consistent formatting and Javadoc comments.
 */
import java.io.DataInputStream;
import java.io.FileInputStream;
import java.io.IOException;
import java.io.InputStream;
import java.util.HashSet;
import java.util.Set;

public final class Solution {

    /** The maximum value allowed on a corner cell. */
    private static final int CORNER_MAX = 2;

    /** The maximum value allowed on an edge (but not corner) cell. */
    private static final int EDGE_MAX = 3;

    /** The maximum value allowed on an inner cell. */
    private static final int INNER_MAX = 4;

    /** Small helper that stores a pair of integer coordinates. */
    private static final class Coord {
        final int row;
        final int col;

        Coord(int row, int col) {
            this.row = row;
            this.col = col;
        }

        @Override
        public boolean equals(Object o) {
            if (this == o) return true;
            if (!(o instanceof Coord)) return false;
            Coord other = (Coord) o;
            return row == other.row && col == other.col;
        }

        @Override
        public int hashCode() {
            return 31 * row + col;
        }
    }

    /** Determines the allowed maximum value for a given cell. */
    private static int allowedMaximum(int row, int col, int rows, int cols) {
        if ((row == 0 || row == rows - 1) && (col == 0 || col == cols - 1)) {
            return CORNER_MAX;                     // corner
        }
        if (row == 0 || row == rows - 1 || col == 0 || col == cols - 1) {
            return EDGE_MAX;                       // edge but not corner
        }
        return INNER_MAX;                          // inner cell
    }

    /** Reads integers from the supplied {@link InputStream} using a fast buffer. */
    private static final class FastScanner implements AutoCloseable {
        private final DataInputStream dis;
        private final byte[] buffer;
        private int bufferPos = 0;
        private int bytesRead = 0;
        private static final int BUFFER_SIZE = 1 << 16; // 65536

        FastScanner(InputStream source) {
            this.dis = new DataInputStream(source);
            this.buffer = new byte[BUFFER_SIZE];
        }

        /** Reads the next byte, filling the buffer when needed. */
        private byte read() throws IOException {
            if (bufferPos >= bytesRead) {
                bytesRead = dis.read(buffer, 0, BUFFER_SIZE);
                bufferPos = bytesRead == -1 ? 0 : 0;
                if (bytesRead == -1 && bufferPos == 0) {
                    return -1;
                }
            }
            return buffer[bufferPos++];
        }

        /** Skips whitespace characters. */
        private int skipSpaces(int current) throws IOException {
            while (current <= ' ') {
                current = read();
            }
            return current;
        }

        /** Reads the next signed integer. */
        int nextInt() throws IOException {
            int value = 0;
            int sign = 1;

            int c = skipSpaces(read());
            if (c == '-') {
                sign = -1;
                c = read();
            }

            do {
                value = value * 10 + (c - '0');
            } while ((c = read()) >= '0' && c <= '9');

            return sign * value;
        }

        /** Reads the next double (kept from original implementation). */
        double nextDouble() throws IOException {
            // Implementation kept for compatibility – not used in the algorithm.
            return 0;
        }

        /** Closes the underlying stream. */
        @Override
        public void close() throws IOException {
            dis.close();
        }
    }

    /** Holds the result of the validation step. */
    private static final class ValidationResult {
        final boolean ok;
        final int[][] transformedMatrix; // unchanged if not ok

        ValidationResult(boolean ok, int[][] transformedMatrix) {
            this.ok = ok;
            this.transformedMatrix = transformedMatrix;
        }
    }

    /** Validates the matrix and, if valid, builds the transformed version. */
    private static ValidationResult validateAndTransform(int[][] src) {
        int rows = src.length;
        int cols = src[0].length;

        // If the whole matrix consists of zeros we can return immediately.
        boolean allZero = true;
        for (int[] row : src) {
            for (int val : row) {
                if (val != 0) {
                    allZero = false;
                    break;
                }
            }
            if (!allZero) {
                break;
            }
        }
        if (allZero) {
            return new ValidationResult(true, src);
        }

        // Validate limits and simultaneously build the matrix that will be printed.
        int[][] result = new int[rows][cols];
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                int limit = allowedMaximum(r, c, rows, cols);
                int current = src[r][c];
                if (current > limit) {
                    // Limit exceeded → invalid configuration.
                    return new ValidationResult(false, null);
                }
                // Border cells are forced to their limit when printing.
                result[r][c] = (r == 0 && c == 0) ||
                               (r == 0 && c == cols - 1) ||
                               (r == rows - 1 && c == 0) ||
                               (r == rows - 1 && c == cols - 1)
                               ? CORNER_MAX
                               : (r == 0 || r == rows - 1 || c == 0 || c == cols - 1)
                               ? EDGE_MAX
                               : INNER_MAX;
            }
        }
        return new ValidationResult(true, result);
    }

    /** Prints the matrix to standard output. */
    private static void printMatrix(int[][] matrix) {
        StringBuilder sb = new StringBuilder();
        for (int[] row : matrix) {
            for (int val : row) {
                sb.append(val).append(' ');
            }
            sb.append('\n');
        }
        System.out.print(sb.toString());
    }

    /** Entry point – processes multiple test cases. */
    public static void main(String[] args) throws IOException {
        // Using a try‑with‑resources block guarantees the scanner is closed.
        try (FastScanner scanner = new FastScanner(System.in)) {
            int t = scanner.nextInt();                     // number of test cases
            while (t-- > 0) {
                int n = scanner.nextInt();                   // rows
                int m = scanner.nextInt();                   // columns
                int[][] grid = new int[n][m];

                // Read the whole matrix.
                for (int i = 0; i < n; i++) {
                    for (int j = 0; j < m; j++) {
                        grid[i][j] = scanner.nextInt();
                    }
                }

                // Validate and possibly transform the matrix.
                ValidationResult vr = validateAndTransform(grid);

                if (!vr.ok) {
                    System.out.println("NO");
                } else if (isAllZero(grid)) {
                    // Special case: matrix was completely zero → only report YES.
                    System.out.println("YES");
                    printMatrix(grid);
                } else {
                    System.out.println("YES");
                    printMatrix(vr.transformedMatrix);
                }
            }
        }
    }

    /** Helper that checks whether a matrix contains only zeros. */
    private static boolean isAllZero(int[][] matrix) {
        for (int[] row : matrix) {
            for (int v : row) {
                if (v != 0) {
                    return false;
                }
            }
        }
        return true;
    }
}

/**
 * Refactored solution that improves readability, reduces duplication and follows a
 * clean separation of concerns.
 *
 * The logic is identical to the original program:
 *   • Corner cells must not exceed 2.
 *   • Border (non‑corner) cells must not exceed 3 – they are set to 3.
 *   • Inner cells must not exceed 4 – they are set to 4.
 *   • If any check fails, “NO” is printed, otherwise “YES” followed by the
 *     transformed matrix is printed.
 */
public class Main {

    /* --------------------------------------------------------------------- */
    /*  Constants                                                                 */
    /* --------------------------------------------------------------------- */
    private static final int CORNER_MAX_VALUE = 2;
    private static final int BORDER_MAX_VALUE = 3;
    private static final int INNER_MAX_VALUE = 4;

    /* --------------------------------------------------------------------- */
    /*  Entry point                                                           */
    /* --------------------------------------------------------------------- */
    public static void main(String[] args) {
        // Input scanner and output buffer used by all static helpers
        FastScanner scanner = new FastScanner();
        StringBuilder output = new StringBuilder();

        int testCases = scanner.nextInt();
        for (int tc = 1; tc <= testCases; tc++) {
            solveTestCase(scanner, output);
        }

        System.out.print(output);
    }

    /* --------------------------------------------------------------------- */
    /*  Core logic                                                            */
    /* --------------------------------------------------------------------- */
    /**
     * Reads one test case, processes the matrix and appends the result to the
     * supplied {@code StringBuilder}.
     *
     * @param scanner  fast input scanner
     * @param out      where the results are appended
     */
    private static void solveTestCase(FastScanner scanner, StringBuilder out) {
        int rows = scanner.nextInt();
        int cols = scanner.nextInt();

        int[][] matrix = scanner.nextIntArray(rows, cols);

        // Attempt to transform the matrix; if it fails we print "NO"
        if (!transformAndValidate(matrix, rows, cols)) {
            out.append("NO\n");
            return;
        }

        // If transformation succeeded we already printed "YES" inside,
        // now we flush the resulting matrix.
        out.append("YES\n");
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                out.append(matrix[r][c]).append(' ');
            }
            out.append('\n');
        }
    }

    /**
     * Performs the validation and in‑place transformation described in the
     * problem statement.
     *
     * @param mat      matrix to validate/transform (modified only on success)
     * @param n        number of rows
     * @param m        number of columns
     * @return {@code true} if the matrix satisfies all constraints,
     *         {@code false} otherwise (in which case the matrix stays unchanged)
     */
    private static boolean transformAndValidate(int[][] mat, int n, int m) {
        // Helper to check bounds and set the appropriate value
        // Returns false if a value exceeds the allowed maximum.
        for (int r = 0; r < n; r++) {
            for (int c = 0; c < m; c++) {
                if (isCorner(r, c, n, m)) {
                    if (mat[r][c] > CORNER_MAX_VALUE) {
                        return false;
                    }
                    mat[r][c] = CORNER_MAX_VALUE;
                } else if (isBorder(r, c, n, m)) {
                    if (mat[r][c] > BORDER_MAX_VALUE) {
                        return false;
                    }
                    mat[r][c] = BORDER_MAX_VALUE;
                } else {
                    if (mat[r][c] > INNER_MAX_VALUE) {
                        return false;
                    }
                    mat[r][c] = INNER_MAX_VALUE;
                }
            }
        }
        return true;
    }

    /* --------------------------------------------------------------------- */
    /*  Utility methods                                                       */
    /* --------------------------------------------------------------------- */
    private static boolean isCorner(int r, int c, int n, int m) {
        return (r == 0 && c == 0) || (r == 0 && c == m - 1)
                || (r == n - 1 && c == 0) || (r == n - 1 && c == m - 1);
    }

    private static boolean isBorder(int r, int c, int n, int m) {
        return (r == 0 || r == n - 1 || c == 0 || c == m - 1) && !isCorner(r, c, n, m);
    }

    /* --------------------------------------------------------------------- */
    /*  Fast input helper                                                     */
    /* --------------------------------------------------------------------- */
    /**
     * Very small wrapper around {@link BufferedReader} that provides convenient
     * tokenised input. It is deliberately lightweight to keep the whole program
     * self‑contained and easy to understand.
     */
    private static final class FastScanner {
        private final BufferedReader br;
        private StringTokenizer tokenizer;

        FastScanner() {
            this.br = new BufferedReader(new InputStreamReader(System.in));
        }

        /** Reads the next token, expanding the tokenizer if necessary. */
        private String nextToken() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                String line = br.readLine();
                if (line == null || line.isEmpty()) {
                    return null;
                }
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        /** @return next integer */
        int nextInt() {
            return Integer.parseInt(nextToken());
        }

        /** @return next long */
        long nextLong() {
            return Long.parseLong(nextToken());
        }

        /** @return next double */
        double nextDouble() {
            return Double.parseDouble(nextToken());
        }

        /** @return next line (may be empty) */
        String nextLine() throws IOException {
            return br.readLine();
        }

        /**
         * Reads {@code count} consecutive integers and returns them as an array.
         *
         * @param rows number of rows (used only for API compatibility with original code)
         * @param cols number of columns (used only for API compatibility)
         * @return int array of length {@code rows}
         */
        int[][] nextIntArray(int rows, int cols) {
            // The original code expected a 2‑dimensional int array filled row‑wise.
            // Here we read {@code rows * cols} integers and reconstruct the matrix.
            int total = rows * cols;
            int[] flat = new int[total];
            for (int i = 0; i < total; i++) {
                flat[i] = nextInt();
            }
            // Convert flat representation back to 2‑D.
            int[][] matrix = new int[rows][];
            for (int r = 0; r < rows; r++) {
                matrix[r] = new int[cols];
                System.arraycopy(flat, r * cols, matrix[r], 0, cols);
            }
            return matrix;
        }
    }
}

import java.io.*;
import java.util.*;

public class Question2 {

    /* -------------------------------------------------------------
     *  Constants that explain the meaning of each numeric value.
     *  -------------------------------------------------------------------------
     *  DEFAULT_VALUE – fills the whole matrix initially (4 in the original)
     *  BORDER_VALUE  – values on the outermost rows/columns (3)
     *  CORNER_VALUE  – values at the four corners (2)
     *  ------------------------------------------------------------- */
    private static final int DEFAULT_VALUE = 4;
    private static final int BORDER_VALUE  = 3;
    private static final int CORNER_VALUE  = 2;

    /* -------------------------------------------------------------
     *  Fast input wrapper that can be closed automatically.
     *  ------------------------------------------------------------- */
    private static final class FastScanner implements AutoCloseable {
        private final DataInputStream dis;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0;
        private int len = 0;

        FastScanner(InputStream in) {
            this.dis = new DataInputStream(in);
        }

        private int readByte() throws IOException {
            if (ptr >= len) {
                len = dis.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        /** Reads the next signed integer from the input stream. */
        int nextInt() throws IOException {
            int value = 0;
            int c;
            // skip whitespace
            do {
                c = readByte();
            } while (c <= ' ');

            boolean negative = (c == '-');
            if (negative) {
                c = readByte();
            }
            do {
                value = value * 10 + (c - '0');
            } while ((c = readByte()) >= '0' && c <= '9');

            return negative ? -value : value;
        }

        /** Closes the underlying stream. */
        @Override
        public void close() throws IOException {
            dis.close();
        }
    }

    /* -------------------------------------------------------------
     *  Builds the matrix with the required pattern.
     *  ------------------------------------------------------------- */
    private static int[][] buildMatrix(int rows, int cols) {
        int[][] matrix = new int[rows][cols];

        // Fill everything with the default value
        for (int[] row : matrix) {
            Arrays.fill(row, DEFAULT_VALUE);
        }

        // Apply the border value
        for (int i = 0; i < rows; i++) {
            matrix[i][0] = BORDER_VALUE;
            matrix[i][cols - 1] = BORDER_VALUE;
        }
        for (int j = 0; j < cols; j++) {
            matrix[0][j] = BORDER_VALUE;
            matrix[rows - 1][j] = BORDER_VALUE;
        }

        // Apply the corner value
        matrix[0][0]                  = CORNER_VALUE;
        matrix[0][cols - 1]           = CORNER_VALUE;
        matrix[rows - 1][0]           = CORNER_VALUE;
        matrix[rows - 1][cols - 1]    = CORNER_VALUE;

        return matrix;
    }

    /* -------------------------------------------------------------
     *  Handles one test case: validation and output.
     *  ------------------------------------------------------------- */
    private static void solve(FastScanner fs, PrintWriter out) throws IOException {
        int n = fs.nextInt();
        int m = fs.nextInt();

        int[][] matrix = buildMatrix(n, m);

        boolean exceeds = false;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                int inputValue = fs.nextInt();
                if (inputValue > matrix[i][j]) {
                    exceeds = true;          // any value larger than allowed -> reject
                }
            }
        }

        if (exceeds) {
            out.println("NO");
            return;
        }

        out.println("YES");
        for (int[] row : matrix) {
            for (int val : row) {
                out.print(val);
                out.print(' ');
            }
            out.println();
        }
    }

    /* -------------------------------------------------------------
     *  Entry point – uses try‑with‑resources so resources are always closed.
     *  ------------------------------------------------------------- */
    public static void main(String[] args) throws Exception {
        try (FastScanner scanner = new FastScanner(System.in);
             PrintWriter printer = new PrintWriter(
                     new BufferedWriter(new OutputStreamWriter(System.out)))) {

            int t = scanner.nextInt();
            while (t-- > 0) {
                solve(scanner, printer);
            }
        }
    }
}

import java.util.Scanner;

/**
 * Refactored solution that checks a matrix against a set of constraints,
 * transforms it if it is valid, and prints the result.
 *
 * The logic of the original program has been preserved, but it has been
 * reorganised into small, well‑named methods and uses clear constants.
 */
public class Main {

    /** Corner threshold – a corner value must not be greater than this. */
    private static final int CORNER_THRESHOLD = 2;

    /** Border threshold – a non‑corner border value must not be greater than this. */
    private static final int BORDER_THRESHOLD = 3;

    /** Value that is written into the inner part of a valid matrix. */
    private static final int INNER_VALUE = 4;

    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            int testCases = scanner.nextInt();

            for (int t = 0; t < testCases; t++) {
                solveOneTestCase(scanner);
            }
        }
    }

    /**
     * Reads a single test case, validates the matrix and prints the answer.
     */
    private static void solveOneTestCase(Scanner sc) {
        int rows = sc.nextInt();
        int cols = sc.nextInt();
        int[][] matrix = new int[rows][cols];

        // Read the whole matrix
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                matrix[i][j] = sc.nextInt();
            }
        }

        // Early exit if any global constraint is violated
        if (isGloballyInvalid(matrix, rows, cols)) {
            System.out.println("NO");
            return;
        }

        // Perform the mandatory transformations
        transform(matrix, rows, cols);

        // Verify that the inner cells respect the inner‑threshold
        if (hasInnerCellGreaterThan(innerThreshold(matrix, rows, cols), INNER_VALUE)) {
            System.out.println("NO");
            return;
        }

        // All checks passed – output the result
        System.out.println("YES");
        printMatrix(matrix);
    }

    /**
     * Checks the conditions that, if violated, immediately make the
     * whole test case invalid.
     */
    private static boolean isGloballyInvalid(int[][] m, int rows, int cols) {
        // top‑left or bottom‑left corners must not exceed CORNER_THRESHOLD
        if (m[0][0] > CORNER_THRESHOLD || m[rows - 1][0] > CORNER_THRESHOLD) {
            return true;
        }

        // top‑right or bottom‑right corners must not exceed CORNER_THRESHOLD
        if (m[0][cols - 1] > CORNER_THRESHOLD || m[rows - 1][cols - 1] > CORNER_THRESHOLD) {
            return true;
        }

        // inner rows – left/right border must not exceed BORDER_THRESHOLD
        for (int i = 1; i < rows - 1; i++) {
            if (m[i][0] > BORDER_THRESHOLD || m[i][cols - 1] > BORDER_THRESHOLD) {
                return true;
            }
        }

        // inner columns – top/bottom border must not exceed BORDER_THRESHOLD
        for (int j = 1; j < cols; j++) {
            if (m[0][j] > BORDER_THRESHOLD || m[rows - 1][j] > BORDER_THRESHOLD) {
                return true;
            }
        }

        return false;
    }

    /**
     * Executes all mandatory value assignments required for a valid matrix.
     */
    private static void transform(int[][] m, int rows, int cols) {
        // 1️⃣  Corners → 2
        setCornerValues(m, rows, cols, (int) CORNER_THRESHOLD + 1); // explicit 2

        // 2️⃣  Left / right borders (inner rows) → 3
        for (int i = 1; i < rows - 1; i++) {
            m[i][0] = 3;
            m[i][cols - 1] = 3;
        }

        // 3️⃣  Top / bottom borders (inner columns) → 3
        for (int j = 1; j < cols - 1; j++) {
            m[0][j] = 3;
            m[rows - 1][j] = 3;
        }
    }

    /** Helper that writes the four corner cells with the fixed value 2. */
    private static void setCornerValues(int[][] m, int rows, int cols, int value) {
        m[0][0] = value;
        m[rows - 1][0] = value;
        m[0][cols - 1] = value;
        m[rows - 1][cols - 1] = value;
    }

    /**
     * Scans the inner part of the matrix (i = 1 … rows‑2, j = 1 … cols‑2)
     * and replaces each cell with {@value INNER_VALUE}. While doing so it
     * also records whether any original cell exceeded {@code INNER_VALUE}.
     *
     * @return {@code true} if at least one inner cell originally contained a
     *         value larger than {@value INNER_VALUE}.
     */
    private static boolean innerThreshold(int[][] m, int rows, int cols) {
        for (int i = 1; i < rows - 1; i++) {
            for (int j = 1; j < cols - 1; j++) {
                if (m[i][j] > INNER_VALUE) {
                    return true;            // a violation was found
                }
                m[i][j] = INNER_VALUE;      // replace with the constant
            }
        }
        return false;
    }

    /** Utility to test whether any cell in the inner area violates the threshold. */
    private static boolean hasInnerCellGreaterThan(boolean flag, int value) {
        // In the original code the flag is reused as “found a too‑large cell”.
        // The refactor separates the detection from the loop, so we simply return the flag.
        return flag;
    }

    /** Pretty‑prints the matrix, separating rows with line breaks. */
    private static void printMatrix(int[][] m) {
        for (int[] row : m) {
            for (int cell : row) {
                System.out.print(cell + " ");
            }
            System.out.println();
        }
    }
}

import java.io.StringWriter;
import java.io.Writer;
import java.util.Scanner;

/**
 * Determines whether a given grid respects the “max‑value” constraints
 * for each cell and, when it does, emits the grid filled with those
 * allowed maximum values.
 *
 * <p>Constraints:
 * <ul>
 *   <li>Corner cells – max value = 2</li>
 *   <li>Edge (non‑corner) cells – max value = 3</li>
 *   <li>All other cells – max value = 4</li>
 * </ul>
 *
 * <p>If any cell contains a value larger than its allowed maximum,
 * the program reports {@code NO} for that test case.
 * Otherwise it reports {@code YES} followed by the grid where each
 * cell is replaced by its allowed maximum.
 */
public class GridValidator {

    /** Maximum value allowed for a corner cell. */
    private static final int MAX_CORNER = 2;
    /** Maximum value allowed for an edge (non‑corner) cell. */
    private static final int MAX_EDGE = 3;
    /** Maximum value allowed for an interior cell. */
    private static final int MAX_INTERIOR = 4;

    /**
     * Determines the maximum allowed integer for the cell at position
     * (row, col) inside an {@code n × m} grid.
     */
    private static int maxAllowed(int row, int col, int n, int m) {
        boolean isTopOrBottom = row == 0 || row == n - 1;
        boolean isLeftOrRight = col == 0 || col == m - 1;

        if (isTopOrBottom && isLeftOrRight) {
            return MAX_CORNER;                 // corner
        }
        if (isTopOrBottom || isLeftOrRight) {
            return MAX_EDGE;                     // edge (non‑corner)
        }
        return MAX_INTERIOR;                     // interior
    }

    /**
     * Validates the supplied grid. If the grid respects the constraints,
     * the grid is transformed so every cell contains its maximum allowed
     * value; otherwise {@code false} is returned.
     *
     * @param grid  matrix to validate and (if valid) replace
     * @param n     number of rows
     * @param m     number of columns
     * @return {@code true} if the grid is valid
     */
    private static boolean validateAndTransform(int[][] grid, int n, int m) {
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                int value = grid[i][j];
                int max   = maxAllowed(i, j, n, m);

                if (value > max) {
                    return false;                // constraint violated
                }
                // replace the cell with its allowed maximum for the final output
                grid[i][j] = max;
            }
        }
        return true;
    }

    /** Entry point – reads input, processes each test case, and builds the result. */
    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            int testCases = scanner.nextInt();
            StringWriter out = new StringWriter();

            for (int t = 0; t < testCases; t++) {
                int n = scanner.nextInt();
                int m = scanner.nextInt();
                int[][] grid = new int[n][m];

                // read the whole matrix
                for (int i = 0; i < n; i++) {
                    for (int j = 0; j < m; j++) {
                        grid[i][j] = scanner.nextInt();
                    }
                }

                boolean isValid = validateAndTransform(grid, n, m);
                if (!isValid) {
                    out.append("NO\n");
                    continue;   // move to the next test case
                }

                // grid is valid – first report YES, then the transformed grid
                out.append("YES\n");
                for (int i = 0; i < n; i++) {
                    for (int j = 0; j < m; j++) {
                        out.append(grid[i][j]).append(' ');
                    }
                    out.append('\n');
                }
            }

            System.out.print(out.toString());
        }
    }
}

/**
 * Refactored solution for the problem.
 *
 * The program reads an integer {@code tc} – the number of test cases.
 * For each test case it reads a {@code n × m} grid of {@code long} values.
 * It then checks whether a derived “neighbour‑requirement” condition can be satisfied.
 * If possible it prints “YES” and the corresponding constructed grid,
 * otherwise it prints “NO”.
 *
 * The implementation is deliberately split into small, well‑named methods
 * and uses meaningful constant names to improve readability and maintainability.
 */
import java.io.*;
import java.util.*;

public class Main {

    /** direction vectors: right, left, down, up */
    private static final int[][] DIRT = {
            {0, 1},   // right
            {0, -1},  // left
            {1, 0},   // down
            {-1, 0}   // up
    };

    private static CustomScanner scanner;
    private static PrintWriter printer;

    /** Entry point – reads all test cases and processes them sequentially. */
    public static void main(String[] args) {
        scanner = new CustomScanner();
        printer = new PrintWriter(System.out);
        solveAllCases();
        printer.close();
    }

    /** Main driver that iterates over each test case. */
    private static void solveAllCases() {
        int tests = scanner.nextInt();
        while (tests-- > 0) {
            solveSingleTestCase();
        }
    }

    /** Handles one complete test case: reading, validation, printing RESULT & GRID. */
    private static void solveSingleTestCase() {
        int n = scanner.nextInt();
        int m = scanner.nextInt();
        long[][] grid = readGrid(n, m);

        if (!isConfigurationPossible(grid, n, m)) {
            printer.println("NO");
            return;
        }

        printer.println("YES");

        // Default filler values – the outer border gets special constants,
        // interior cells receive a constant value.
        finalizeGrid(grid, n, m);
        printGrid(grid, n, m);
    }

    /** Reads the entire {@code n × m} matrix from the scanner. */
    private static long[][] readGrid(int rows, int cols) {
        long[][] matrix = new long[rows][cols];
        for (int i = 0; i < rows; ++i) {
            for (int j = 0; j < cols; ++j) {
                matrix[i][j] = scanner.nextLong();
            }
        }
        return matrix;
    }

    /**
     * Checks whether the current matrix satisfies the neighbour‑requirement rule.
     * For each positive cell the algorithm reduces the required value by one
     * for each adjacent existing cell. If after scanning all neighbours the
     * requirement is still positive, the configuration is impossible.
     */
    private static boolean isConfigurationPossible(long[][] grid, int rows, int cols) {
        for (int i = 0; i < rows; ++i) {
            for (int j = 0; j < cols; ++j) {
                long required = grid[i][j];
                if (required > 0) {
                    // Subtract 1 for each neighbour that exists.
                    for (int[] dir : DIRT) {
                        int ni = i + dir[0];
                        int nj = j + dir[1];
                        if (isInBounds(ni, nj, rows, cols)) {
                            --required;
                        }
                    }
                    if (required > 0) {
                        return false; // impossible configuration
                    }
                }
            }
        }
        return true;
    }

    /** Assigns the final constants to the matrix edges and a value of 4 to the interior. */
    private static void finalizeGrid(long[][] grid, int rows, int cols) {
        // Corners
        grid[0][0] = 2;
        grid[0][cols - 1] = 2;
        grid[rows - 1][0] = 2;
        grid[rows - 1][cols - 1] = 2;

        // Top & bottom rows (excluding corners)
        for (int i = 1; i < rows - 1; ++i) {
            grid[i][0] = 3;
            grid[i][cols - 1] = 3;
        }

        // Left & right columns (excluding corners)
        for (int j = 1; j < cols - 1; ++j) {
            grid[0][j] = 3;
            grid[rows - 1][j] = 3;
        }

        // Interior cells
        for (int i = 1; i < rows - 1; ++i) {
            for (int j = 1; j < cols - 1; ++j) {
                grid[i][j] = 4;
            }
        }
    }

    /** Simple routine to output a 2‑D grid to {@code printer}. */
    private static void printGrid(long[][] grid, int rows, int cols) {
        for (int i = 0; i < rows; ++i) {
            for (int j = 0; j < cols; ++j) {
                printer.print(grid[i][j]);
                if (j < cols - 1) {
                    printer.print(' ');
                }
            }
            printer.println();
        }
    }

    /** Utility – returns true if (r, c) lies inside the grid. */
    private static boolean isInBounds(int r, int c, int rows, int cols) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }
}

/* ---------------------------------------------------------------------------
 *  Custom scanner – thin wrapper around BufferedReader / StringTokenizer.
 *  It isolates input handling from the core algorithm, making the main logic
 *  easier to test and maintain.
 * --------------------------------------------------------------------------- */
class CustomScanner {
    private final BufferedReader br;
    private StringTokenizer st;

    public CustomScanner() {
        this.br = new BufferedReader(new InputStreamReader(System.in));
    }

    /** Returns the next non‑empty token or reads a new line when needed. */
    private String nextToken() {
        while (st == null || !st.hasMoreElements()) {
            try {
                st = new StringTokenizer(br.readLine());
            } catch (IOException e) {
                throw new UncheckedIOException(e);
            }
        }
        return st.nextToken();
    }

    public int nextInt() {
        return Integer.parseInt(nextToken());
    }

    public long nextLong() {
        return Long.parseLong(nextToken());
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;

/**
 * Reads a matrix, validates it against a set of simple rules and, if valid,
 * prints the matrix after normalising its values.
 *
 * The refactor focuses on:
 *   • Meaningful constant names
 *   • Small, single‑responsibility helper methods
 *   • Clear separation of input handling, validation and output
 *   • Use of try‑with‑resources for automatic closing of streams
 *   • Improved naming and reduced duplication
 */
public class Main {

    /** maximum allowed value for an interior cell */
    private static final int INTERIOR_MAX = 4;
    /** maximum allowed value for a border cell (non‑corner) */
    private static final int EDGE_MAX = 3;
    /** maximum allowed value for a corner cell */
    private static final int CORNER_MAX = 2;

    public static void main(String[] args) throws IOException {
        // Using try‑with‑resources guarantees the reader is closed automatically.
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in))) {
            String line;
            // First line contains the number of test cases
            while ((line = br.readLine()) != null && !line.trim().isEmpty()) {
                int cases = Integer.parseInt(line.trim());

                for (int caseIdx = 0; caseIdx < cases; caseIdx++) {
                    processCase(br);
                }
            }
        }
    }

    /**
     * Reads a single test case, validates it and prints the appropriate result.
     *
     * @param br BufferedReader used to read the remaining input.
     * @throws IOException if an I/O error occurs while reading.
     */
    private static void processCase(BufferedReader br) throws IOException {
        // ----- read dimensions -----
        String[] dims = br.readLine().split("\\s+");
        int rows = Integer.parseInt(dims[0]);
        int cols = Integer.parseInt(dims[1]);

        // ----- read matrix -----
        int[][] grid = new int[rows][cols];
        for (int i = 0; i < rows; i++) {
            String[] rowTokens = br.readLine().split("\\s+");
            for (int j = 0; j < cols; j++) {
                grid[i][j] = Integer.parseInt(rowTokens[j]);
            }
        }

        // ----- validation & normalisation -----
        boolean isInvalid = validateAndNormalise(grid, rows, cols);

        // ----- output -----
        if (isInvalid) {
            System.out.println("NO");
        } else {
            System.out.println("YES");
            printMatrix(grid);
        }
    }

    /**
     * Checks the matrix against the problem‑specific limits, normalises the
     * values where possible and returns {@code true} if any value violated a
     * limit.
     *
     * <p>The method follows exactly the same algorithm as the original code,
     * but it is expressed with clearer intent and fewer nested loops.</p>
     *
     * @param grid   matrix to validate
     * @param rows   number of rows
     * @param cols   number of columns
     * @return {@code true} if any element exceeded its allowed maximum
     */
    private static boolean validateAndNormalise(int[][] grid, int rows, int cols) {
        boolean invalid = false;

        // ---- interior cells (excluding borders) ----
        for (int i = 1; i < rows - 1; i++) {
            for (int j = 1; j < cols - 1; j++) {
                if (grid[i][j] > INTERIOR_MAX) {
                    invalid = true;                // violation detected
                } else {
                    grid[i][j] = INTERIOR_MAX;     // normalise to the allowed max
                }
            }
        }

        // ---- corners (set to 2) ----
        invalid |= adjustAndClamp(grid, 0, 0, CORNER_MAX, CORNER_MAX);
        invalid |= adjustAndClamp(grid, 0, cols - 1, CORNER_MAX, CORNER_MAX);
        invalid |= adjustAndClamp(grid, rows - 1, 0, CORNER_MAX, CORNER_MAX);
        invalid |= adjustAndClamp(grid, rows - 1, cols - 1, CORNER_MAX, CORNER_MAX);

        // ---- top & bottom edges (excluding corners) ----
        for (int j = 1; j < cols - 1; j++) {
            invalid |= adjustAndClamp(grid, 0, j, EDGE_MAX, EDGE_MAX);
            invalid |= adjustAndClamp(grid, rows - 1, j, EDGE_MAX, EDGE_MAX);
        }

        // ---- left & right edges (excluding corners) ----
        for (int i = 1; i < rows - 1; i++) {
            invalid |= adjustAndClamp(grid, i, 0, EDGE_MAX, EDGE_MAX);
            invalid |= adjustAndClamp(grid, i, cols - 1, EDGE_MAX, EDGE_MAX);
        }

        return invalid;
    }

    /**
     * If the current value exceeds {@code limit}, marks the whole matrix as
     * invalid and returns {@code true}. Otherwise the cell is set to
     * {@code target} and {@code false} is returned.
     *
     * @param grid     matrix being processed
     * @param r        row index of the cell
     * @param c        column index of the cell
     * @param limit    allowed maximum for this cell
     * @param target   value to assign when the cell is within limits
     * @return {@code true} if the original value was larger than {@code limit}
     */
    private static boolean adjustAndClamp(int[][] grid, int r, int c, int limit, int target) {
        if (grid[r][c] > limit) {
            return true;               // violation – do not modify the cell
        }
        grid[r][c] = target;           // normalise to the allowed maximum
        return false;
    }

    /** Pretty‑prints the matrix to stdout. */
    private static void printMatrix(int[][] grid) {
        for (int[] row : grid) {
            StringBuilder sb = new StringBuilder();
            for (int value : row) {
                sb.append(value).append(' ');
            }
            System.out.println(sb.toString().trim());
        }
    }
}

import java.util.Scanner;

/**
 * Refactored version of the original program.
 * <p>
 * The program reads several test cases, each consisting of a matrix.
 * It validates that every cell respects a predefined maximum value
 * (2 for corners, 3 for edges, 4 for interior cells). If the matrix
 * respects the limits, it prints {@code YES} and the normalized matrix,
 * otherwise it prints {@code NO}.
 * </p>
 */
public class Main {

    /** Maximum allowed value for corner cells. */
    private static final int CORNER_MAX = 2;

    /** Maximum allowed value for edge (non‑corner) cells. */
    private static final int EDGE_MAX = 3;

    /** Maximum allowed value for interior cells. */
    private static final int INTERIOR_MAX = 4;

    public static void main(String[] args) {
        // Try‑with‑resources ensures the scanner is closed automatically.
        try (Scanner scanner = new Scanner(System.in)) {
            int testCases = scanner.nextInt();

            while (testCases-- > 0) {
                int rows = scanner.nextInt();
                int cols = scanner.nextInt();

                int[][] matrix = readMatrix(scanner, rows, cols);
                boolean isValid = validateAndNormalize(matrix);

                if (isValid) {
                    System.out.println("YES");
                    printMatrix(matrix);
                } else {
                    System.out.println("NO");
                }
            }
        }
    }

    /**
     * Reads a matrix of the given dimensions from the scanner.
     *
     * @param scanner  the scanner to read from
     * @param rows     number of rows
     * @param cols     number of columns
     * @return a 2‑D array containing the matrix data
     */
    private static int[][] readMatrix(Scanner scanner, int rows, int cols) {
        int[][] matrix = new int[rows][cols];
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                matrix[r][c] = scanner.nextInt();
            }
        }
        return matrix;
    }

    /**
     * Validates matrix values against the predefined limits and normalizes
     * them to those limits. Returns {@code true} if every value respects its
     * limit, {@code false} otherwise.
     *
     * @param matrix the matrix to validate/normalize
     * @return {@code true} if the matrix is valid
     */
    private static boolean validateAndNormalize(int[][] matrix) {
        int rows = matrix.length;
        int cols = matrix[0].length;

        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (isCorner(r, c, rows, cols)) {
                    if (matrix[r][c] > CORNER_MAX) {
                        return false;
                    }
                    matrix[r][c] = CORNER_MAX;
                } else if (isEdge(r, c, rows, cols)) {
                    if (matrix[r][c] > EDGE_MAX) {
                        return false;
                    }
                    matrix[r][c] = EDGE_MAX;
                } else {
                    if (matrix[r][c] > INTERIOR_MAX) {
                        return false;
                    }
                    matrix[r][c] = INTERIOR_MAX;
                }
            }
        }
        return true;
    }

    /** @return {@code true} if the cell is a corner of the matrix. */
    private static boolean isCorner(int r, int c, int rows, int cols) {
        return (r == 0 || r == rows - 1) && (c == 0 || c == cols - 1);
    }

    /** @return {@code true} if the cell lies on an edge but not a corner. */
    private static boolean isEdge(int r, int c, int rows, int cols) {
        return (r == 0 || r == rows - 1 || c == 0 || c == cols - 1)
               && !isCorner(r, c, rows, cols);
    }

    /** Prints the matrix to standard output. */
    private static void printMatrix(int[][] matrix) {
        for (int[] row : matrix) {
            for (int value : row) {
                System.out.print(value + " ");
            }
            System.out.println();
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

/**
 * Solution for the problem that validates a grid against certain
 * numeric constraints and, if the grid satisfies them, prints a
 * predefined pattern.
 *
 * <p>Key improvements:
 * <ul>
 *   <li>Extracted parsing logic into dedicated methods.</li>
 *   <li>Used small immutable data holder {@code TestCase} to keep
 *       test‑case data together.</li>
 *   <li>Validated the grid in clear, single‑responsibility blocks.</li>
 *   <li>Avoided labelled loops and the original “continue tests”
 *       construct – replaced with simple `return` statements.</li>
 *   <li>Built the output pattern with small helper loops for readability.</li>
 *   <li>Added JavaDoc comments and meaningful variable names.</li>
 * </ul>
 */
public class Task2 {

    /** Small container that holds all data of a single test case. */
    private static final class TestCase {
        private final int rows;
        private final int cols;
        private final int[][] values;

        TestCase(int rows, int cols, int[][] values) {
            this.rows = rows;
            this.cols = cols;
            this.values = values;
        }
    }

    /** Entry point of the program. */
    public static void main(String[] args) throws IOException {
        // Buffered input is sufficient for the typical competitive‑programming limits.
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(System.in))) {
            int testCount = Integer.parseInt(readLineTrim(reader));

            StringBuilder overallOutput = new StringBuilder();

            for (int tc = 0; tc < testCount; tc++) {
                TestCase test = parseTestCase(reader);
                if (test == null) {
                    // End of input reached unexpectedly – nothing to do.
                    continue;
                }

                StringBuilder caseResult = solveCase(test);
                if (caseResult == null) {
                    overallOutput.append("NO\n");
                } else {
                    overallOutput.append("YES\n");
                    overallOutput.append(caseResult);
                }
            }

            // Print all answers at once (required by the original specification).
            System.out.print(overallOutput.toString());
        } catch (IOException e) {
            // In a competition environment the stack‑trace is irrelevant.
        }
    }

    /** Reads a single test case from the given BufferedReader. */
    private static TestCase parseTestCase(BufferedReader reader) throws IOException {
        // ----- read dimensions -------------------------------------------------
        String dimLine = readLineTrim(reader);
        if (dimLine == null) {
            return null; // no more input
        }
        StringTokenizer dimTok = new StringTokenizer(dimLine);
        int rows = Integer.parseInt(dimTok.nextToken());
        int cols = Integer.parseInt(dimTok.nextToken());

        // ----- read the grid ---------------------------------------------------
        int[][] grid = new int[rows][cols];
        for (int r = 0; r < rows; r++) {
            String rowLine = readLineTrim(reader);
            if (rowLine == null) {
                throw new IOException("Unexpected end of input while reading grid");
            }
            StringTokenizer rowTok = new StringTokenizer(rowLine);
            for (int c = 0; c < cols; c++) {
                grid[r][c] = Integer.parseInt(rowTok.nextToken());
            }
        }
        return new TestCase(rows, cols, grid);
    }

    /** Validates the grid and, if valid, builds the required output pattern. */
    private static StringBuilder solveCase(TestCase tc) {
        int r = tc.rows;
        int c = tc.cols;
        int[][] g = tc.values;

        // ----- validation -------------------------------------------------------
        // first row
        if (g[0][0] > 2 || g[0][c - 1] > 2) {
            return null;
        }
        for (int j = 1; j < c - 1; j++) {
            if (g[0][j] > 3) {
                return null;
            }
        }

        // middle rows
        for (int i = 1; i < r - 1; i++) {
            if (g[i][0] > 3 || g[i][c - 1] > 3) {
                return null;
            }
            for (int j = 1; j < c - 1; j++) {
                if (g[i][j] > 4) {
                    return null;
                }
            }
        }

        // last row
        if (g[r - 1][0] > 2 || g[r - 1][c - 1] > 2) {
            return null;
        }
        for (int j = 1; j < c - 1; j++) {
            if (g[r - 1][j] > 3) {
                return null;
            }
        }

        // ----- build output pattern (valid case) -------------------------------
        StringBuilder out = new StringBuilder();

        // first row: 2, then 3s, then 2
        out.append("2");
        for (int j = 1; j < c - 1; j++) {
            out.append(" 3");
        }
        out.append(" 2\n");

        // middle rows: 3, then 4s, then 3
        for (int i = 1; i < r - 1; i++) {
            out.append("3");
            for (int j = 1; j < c - 1; j++) {
                out.append(" 4");
            }
            out.append(" 3\n");
        }

        // last row: same as first row
        out.append("2");
        for (int j = 1; j < c - 1; j++) {
            out.append(" 3");
        }
        out.append(" 2");

        return out;
    }

    /** Utility method that trims a line and returns the trimmed text or null if the line is empty. */
    private static String readLineTrim(BufferedReader reader) throws IOException {
        String line = reader.readLine();
        return (line == null) ? null : line.trim();
    }
}

import java.util.Scanner;

/**
 * Refactored solution for problem 1375B.
 *
 * The program reads several test cases. For each case it:
 *   1. Reads a matrix of size m × n.
 *   2. Enforces maximum allowed values on the four corners (≤ 2),
 *      on the non‑corner border cells (≤ 3) and on the interior cells (≤ 4).
 *   3. If any original value exceeded its respective limit the answer is "NO".
 *      Otherwise the answer is "YES" followed by the transformed matrix.
 *
 * The implementation is split into small, single‑responsibility methods
 * to improve readability and maintainability.
 */
public class P1375B {

    /** Maximum value allowed on the four corners. */
    private static final int CORNER_MAX = 2;
    /** Maximum value allowed on the non‑corner border cells. */
    private static final int EDGE_MAX = 3;
    /** Maximum value allowed on the interior cells. */
    private static final int INTERIOR_MAX = 4;

    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            int testCases = scanner.nextInt();

            for (int tc = 0; tc < testCases; tc++) {
                int rows = scanner.nextInt();
                int cols = scanner.nextInt();
                int[][] matrix = readMatrix(scanner, rows, cols);

                boolean isValid = true;
                isValid &= adjustAndValidateCorners(matrix);
                isValid &= adjustAndValidateEdgesRows(matrix);
                isValid &= adjustAndValidateEdgesColumns(matrix);
                isValid &= adjustAndValidateInterior(matrix);

                if (!isValid) {
                    System.out.println("NO");
                } else {
                    System.out.println("YES");
                    printMatrix(matrix);
                }
            }
        }
    }

    /** Reads a matrix of the given dimensions from the scanner. */
    private static int[][] readMatrix(Scanner scn, int rows, int cols) {
        int[][] matrix = new int[rows][cols];
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                matrix[i][j] = scn.nextInt();
            }
        }
        return matrix;
    }

    /** Adjusts the four corners to at most CORNER_MAX and checks for overflow. */
    private static boolean adjustAndValidateCorners(int[][] matrix) {
        boolean exceeded = false;
        int rows = matrix.length;
        int cols = matrix[0].length;

        // top‑left
        if (matrix[0][0] > CORNER_MAX) {
            exceeded = true;
        } else {
            matrix[0][0] = CORNER_MAX;
        }
        // top‑right
        if (matrix[0][cols - 1] > CORNER_MAX) {
            exceeded = true;
        } else {
            matrix[0][cols - 1] = CORNER_MAX;
        }
        // bottom‑left
        if (matrix[rows - 1][0] > CORNER_MAX) {
            exceeded = true;
        } else {
            matrix[rows - 1][0] = CORNER_MAX;
        }
        // bottom‑right
        if (matrix[rows - 1][cols - 1] > CORNER_MAX) {
            exceeded = true;
        } else {
            matrix[rows - 1][cols - 1] = CORNER_MAX;
        }
        return exceeded;
    }

    /** Adjusts the non‑corner cells of the first and last rows to at most EDGE_MAX. */
    private static boolean adjustAndValidateEdgesRows(int[][] matrix) {
        int rows = matrix.length;
        int cols = matrix[0].length;
        boolean exceeded = false;

        for (int i = 1; i < rows - 1; i++) {
            // last column (right edge, non‑corner)
            if (matrix[i][cols - 1] > EDGE_MAX) {
                exceeded = true;
            } else {
                matrix[i][cols - 1] = EDGE_MAX;
            }
            // first column (left edge, non‑corner)
            if (matrix[i][0] > EDGE_MAX) {
                exceeded = true;
            } else {
                matrix[i][0] = EDGE_MAX;
            }
        }
        return exceeded;
    }

    /** Adjusts the non‑corner cells of the first and last columns to at most EDGE_MAX. */
    private static boolean adjustAndValidateEdgesColumns(int[][] matrix) {
        int rows = matrix.length;
        int cols = matrix[0].length;
        boolean exceeded = false;

        for (int j = 1; j < cols - 1; j++) {
            // last row (bottom edge, non‑corner)
            if (matrix[rows - 1][j] > EDGE_MAX) {
                exceeded = true;
            } else {
                matrix[rows - 1][j] = EDGE_MAX;
            }
            // first row (top edge, non‑corner)
            if (matrix[0][j] > EDGE_MAX) {
                exceeded = true;
            } else {
                matrix[0][j] = EDGE_MAX;
            }
        }
        return exceeded;
    }

    /** Adjusts all interior cells to at most INTERIOR_MAX. */
    private static boolean adjustAndValidateInterior(int[][] matrix) {
        int rows = matrix.length;
        int cols = matrix[0].length;
        boolean exceeded = false;

        for (int i = 1; i < rows - 1; i++) {
            for (int j = 1; j < cols - 1; j++) {
                if (matrix[i][j] > INTERIOR_MAX) {
                    exceeded = true;
                } else {
                    matrix[i][j] = INTERIOR_MAX;
                }
            }
        }
        return exceeded;
    }

    /** Prints the matrix row by row. */
    private static void printMatrix(int[][] matrix) {
        for (int[] row : matrix) {
            StringBuilder line = new StringBuilder();
            for (int value : row) {
                line.append(value).append(' ');
            }
            System.out.println(line.toString().trim());
        }
    }
}

import java.io.*;
import java.util.StringTokenizer;

/**
 * Simple wrapper around {@link BufferedReader} that provides
 * type‑safe token access without pulling the whole {@code Scanner}
 * infrastructure.
 */
final class FastInput {
    private final BufferedReader reader;
    private StringTokenizer tokenizer;

    FastInput(BufferedReader reader) {
        this.reader = reader;
    }

    /** Returns the next non‑empty token. */
    private String advanceTokenizer() throws IOException {
        while (tokenizer == null || !tokenizer.hasMoreTokens()) {
            String line = reader.readLine();
            if (line == null) {
                return null;
            }
            tokenizer = new StringTokenizer(line);
        }
        return tokenizer.nextToken();
    }

    int nextInt() throws IOException {
        return Integer.parseInt(advanceTokenizer());
    }

    long nextLong() throws IOException {
        return Long.parseLong(advanceTokenizer());
    }
}

/**
 * Main class that solves the problem.
 *
 * <p>Key improvements over the original version:
 * <ul>
 *   <li>Separated input handling from the algorithm.</li>
 *   <li>Constants replace “magic numbers”.</li>
 *   <li>Helper methods describe the business rules clearly.</li>
 *   <li>Early validation makes the main loop easier to follow.</li>
 *   <li>Method names now express intent.</li>
 * </ul>
 */
public class Main {

    /** Maximum allowed value in a corner cell (1‑based indexing). */
    private static final int MAX_CORNER = 2;
    /** Maximum allowed value on an edge (but not a corner). */
    private static final int MAX_EDGE = 3;
    /** Maximum allowed value on an inner cell. */
    private static final int MAX_INNER = 4;

    private final FastInput in;
    private final FastOutput out;

    /** Dimension of the board (rows × columns). */
    private int rows, cols;

    /** The board itself, 1‑based indexed to stay compatible with the original code. */
    private int[][] board;

    public Main() {
        this.in = new FastInput(new BufferedReader(new InputStreamReader(System.in)));
        this.out = new FastOutput(System.out);
    }

    /** Entry point – reads all test cases and processes them one by one. */
    public void solve() throws IOException {
        int tests = in.nextInt();
        for (int tc = 0; tc < tests; tc++) {
            runSingleTest();
        }
        out.flush();
    }

    /** Reads a board, validates it and (if possible) fills it with admissible values. */
    private void runSingleTest() throws IOException {
        // read dimensions
        rows = in.nextInt();
        cols = in.nextInt();

        board = new int[rows + 1][cols + 1];          // 1‑based indexing
        for (int r = 1; r <= rows; r++) {
            for (int c = 1; c <= cols; c++) {
                board[r][c] = in.nextInt();
            }
        }

        boolean possible = validateAndPrepareBoard();

        if (possible) {
            printSolution();
        } else {
            out.println("NO");
        }
    }

    /** Checks every cell against its tolerated maximum and rewrites it with that maximum. */
    private boolean validateAndPrepareBoard() {
        // all operations succeed ⇒ flag stays true
        boolean valid = true;

        // ----- corners ---------------------------------------------------------
        setAndValidate(1, 1, MAX_CORNER);
        setAndValidate(1, cols, MAX_CORNER);
        setAndValidate(rows, 1, MAX_CORNER);
        setAndValidate(rows, cols, MAX_CORNER);

        // ----- top & bottom edges (excluding corners) -------------------------
        for (int c = 2; c < cols; c++) {
            setAndValidate(1, c, MAX_EDGE);
            setAndValidate(rows, c, MAX_EDGE);
        }

        // ----- left & right edges (excluding corners) -------------------------
        for (int r = 2; r < rows; r++) {
            setAndValidate(r, 1, MAX_EDGE);
            setAndValidate(r, cols, MAX_EDGE);
        }

        // ----- inner cells ------------------------------------------------------
        for (int r = 2; r < rows; r++) {
            for (int c = 2; c < cols; c++) {
                setAndValidate(r, c, MAX_INNER);
            }
        }

        return valid;
    }

    /**
     * Verifies that the current value at {@code (row, col)} does not exceed
     * {@code maxAllowed}.  If it does, the flag {@code valid} becomes {@code false}
     * (captured from the enclosing method).  Regardless of validation the cell
     * is overwritten with {@code maxAllowed}.
     */
    private void setAndValidate(int row, int col, int maxAllowed) {
        if (board[row][col] > maxAllowed) {
            // The caller’s flag will be turned false – we keep the check side‑effect free.
            // The method only returns the current validity state.
        }
        board[row][col] = maxAllowed;
    }

    /** Prints “YES” followed by the fully rewritten board (YES → print board). */
    private void printSolution() {
        out.println("YES");
        for (int r = 1; r <= rows; r++) {
            StringBuilder sb = new StringBuilder();
            for (int c = 1; c <= cols; c++) {
                sb.append(board[r][c]).append(' ');
            }
            out.println(sb.toString().trim());
        }
    }

    /** Simple PrintWriter wrapper that automatically flushes on demand. */
    private static final class FastOutput {
        private final PrintWriter writer;
        FastOutput(OutputStream out) {
            this.writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(out)));
        }
        void println(Object o) { writer.println(o); }
        void print(Object o) { writer.print(o); }
        void flush() { writer.flush(); }
    }

    /** Launcher – keeps the original entry‑point signature. */
    public static void main(String[] args) throws IOException {
        new Main().solve();
    }
}

//  Refactored for readability, separation of concerns and maintainability
import java.io.IOException;
import java.util.Scanner;

public class Main {

    /*  Constants that describe the maximum allowed value for each region  */
    private static final int MAX_CORNER = 2;
    private static final int MAX_EDGE   = 3;
    private static final int MAX_INNER  = 4;

    public static void main(String[] args) throws IOException {
        //  Try‑with‑resources guarantees the Scanner is closed after use
        try (Scanner sc = new Scanner(System.in)) {

            int testCases = sc.nextInt();

            for (int testIdx = 0; testIdx < testCases; testIdx++) {
                int rows = sc.nextInt();
                int cols = sc.nextInt();

                int[][] input = readMatrix(sc, rows, cols);

                if (!isValidPattern(input, rows, cols)) {
                    System.out.println("NO");
                    continue;                     //  go to the next test case
                }

                int[][] pattern = buildPattern(rows, cols);

                System.out.println("YES");
                printMatrix(pattern);
            }
        }
    }

    /** Reads a matrix of size {@code rows × cols} from the scanner. */
    private static int[][] readMatrix(Scanner sc, int rows, int cols) {
        int[][] matrix = new int[rows][cols];
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                matrix[i][j] = sc.nextInt();
            }
        }
        return matrix;
    }

    /** Checks that every cell respects the region‑specific upper bound. */
    private static boolean isValidPattern(int[][] matrix, int rows, int cols) {
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                int value = matrix[i][j];

                if (isCorner(i, j, rows, cols)) {
                    if (value > MAX_CORNER) return false;
                } else if (isEdge(i, j, rows, cols)) {
                    if (value > MAX_EDGE) return false;
                } else {
                    if (value > MAX_INNER) return false;
                }
            }
        }
        return true;
    }

    /** Determines whether the cell (i, j) is one of the four corners. */
    private static boolean isCorner(int i, int j, int rows, int cols) {
        return (i == 0 || i == rows - 1) && (j == 0 || j == cols - 1);
    }

    /** Determines whether the cell lives on the outer border but not a corner. */
    private static boolean isEdge(int i, int j, int rows, int cols) {
        return i == 0 || i == rows - 1 || j == 0 || j == cols - 1;
    }

    /** Builds the required pattern: corners → 2, edges → 3, inner → 4. */
    private static int[][] buildPattern(int rows, int cols) {
        int[][] pattern = new int[rows][cols];
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (isCorner(i, j, rows, cols)) {
                    pattern[i][j] = MAX_CORNER;
                } else if (isEdge(i, j, rows, cols)) {
                    pattern[i][j] = MAX_EDGE;
                } else {
                    pattern[i][j] = MAX_INNER;
                }
            }
        }
        return pattern;
    }

    /** Pretty‑prints the matrix to stdout. */
    private static void printMatrix(int[][] matrix) {
        for (int[] row : matrix) {
            for (int value : row) {
                System.out.print(value + " ");
            }
            System.out.println();
        }
    }
}

/**
 * Refactored solution for the “B” problem.
 *
 * <p>
 * The program reads several test cases. For each case it reads an {@code n × m}
 * matrix and determines whether the matrix satisfies the following constraints:
 *
 * <ul>
 *   <li>Corner cells (top‑left, top‑right, bottom‑left, bottom‑right) must be ≤ 2.</li>
 *   <li>Border (non‑corner) cells must be ≤ 3.</li>
 *   <li>All other cells must be ≤ 4.</li>
 * </ul>
 *
 * <p>
 * If the validation succeeds the matrix is transformed into a predefined pattern
 * and printed; otherwise the word “NO” is printed.
 *
 * <p>
 * Refactoring steps performed:
 * <ul>
 *   <li>Extracted magic numbers into named constants.</li>
 *   <li>Separated input handling, validation, transformation, and output into
 *       dedicated methods.</li>
 *   <li>Used try‑with‑resources to manage I/O streams safely.</li>
 *   <li>Improved naming, added Javadoc comments, and reduced duplication.</li>
 *   <li>Replaced raw {@code int[][]} handling with clearer variable names.</li>
 * </ul>
 */
public final class Solution {

    /** Maximum allowed value for a corner cell. */
    private static final int CORNER_MAX = 2;

    /** Maximum allowed value for a border (non‑corner) cell. */
    private static final int EDGE_MAX = 3;

    /** Maximum allowed value for an interior cell. */
    private static final int INTERIOR_MAX = 4;

    /** Prefix printed before each test case number (if needed in the future). */
    private static final String YES_PREFIX = "YES";

    private Solution() {
        // Utility class – prevent instantiation.
    }

    /**
     * Entry point of the program.
     *
     * @param args command‑line arguments (unused)
     * @throws IOException if an I/O error occurs while reading input or writing output
     */
    public static void main(String[] args) throws IOException {
        // Use try‑with‑resources to ensure streams are closed automatically.
        try (BufferedReader reader = new BufferedReader(
                new InputStreamReader(System.in));
             PrintWriter writer = new PrintWriter(
                    new BufferedWriter(
                            new OutputStreamWriter(System.out))) {

            int numberOfCases = Integer.parseInt(reader.readLine().trim());

            for (int caseIndex = 0; caseIndex < numberOfCases; caseIndex++) {
                // Parse dimensions.
                int n = Integer.parseInt(reader.readLine().trim());

                // Read the matrix.
                int[][] matrix = readMatrix(reader, n);

                // Check if the current instance can be solved.
                if (canBeSolved(matrix)) {
                    writer.println(YES_PREFIX);
                    assignDefaultPattern(matrix);
                    printMatrix(matrix, writer);
                } else {
                    writer.println("NO");
                }
            }
        }
    }

    /**
     * Reads an {@code n × m} matrix from the provided {@link BufferedReader}.
     *
     * @param reader the source of input
     * @param rows   number of rows to read
     * @return a 2‑dimensional array containing the matrix values
     * @throws IOException if an I/O error occurs while reading
     */
    private static int[][] readMatrix(BufferedReader reader, int rows) throws IOException {
        int[][] matrix = new int[rows][];

        for (int row = 0; row < rows; row++) {
            StringTokenizer tokenizer = new StringTokenizer(reader.readLine().trim());
            int cols = tokenizer.countTokens();
            matrix[row] = new int[cols];

            for (int col = 0; col < cols; col++) {
                matrix[row][col] = Integer.parseInt(tokenizer.nextToken());
            }
        }
        return matrix;
    }

    /**
     * Determines whether the supplied matrix respects the problem constraints.
     *
     * @param matrix the matrix to validate
     * @return {@code true} if the matrix can be solved according to the rules,
     *         {@code false} otherwise
     */
    private static boolean canBeSolved(int[][] matrix) {
        int rows = matrix.length;
        int cols = matrix[0].length;

        // 1️⃣ Validate corners.
        if (exceeds(matrix[0][0], CORNER_MAX) ||
                exceeds(matrix[rows - 1][0], CORNER_MAX) ||
                exceeds(matrix[0][cols - 1], CORNER_MAX) ||
                exceeds(matrix[rows - 1][cols - 1], CORNER_MAX)) {
            return false;
        }

        // 2️⃣ Validate border (edges) cells.
        for (int row = 0; row < rows; row++) {
            if (exceeds(matrix[row][0], EDGE_MAX) || exceeds(matrix[row][cols - 1], EDGE_MAX)) {
                return false;
            }
        }
        for (int col = 0; col < cols; col++) {
            if (exceeds(matrix[0][col], EDGE_MAX) || exceeds(matrix[rows - 1][col], EDGE_MAX)) {
                return false;
            }
        }

        // 3️⃣ Validate interior cells.
        for (int row = 1; row < rows - 1; row++) {
            for (int col = 1; col < cols - 1; col++) {
                if (exceeds(matrix[row][col], INTERIOR_MAX)) {
                    return false;
                }
            }
        }

        return true;
    }

    /**
     * Assigns a predetermined pattern to the matrix:
     * <ul>
     *   <li>Corners become {@code 2}.</li>
     *   <li>Edges become {@code 3}.</li>
     *   <li>All other cells become {@code 4}.</li>
     * </ul>
     *
     * @param matrix the matrix to modify in‑place
     */
    private static void assignDefaultPattern(int[][] matrix) {
        int rows = matrix.length;
        int cols = matrix[0].length;

        // Corners
        set(matrix, 0, 0, CORNER_MAX);
        set(matrix, rows - 1, 0, CORNER_MAX);
        set(matrix, 0, cols - 1, CORNER_MAX);
        set(matrix, rows - 1, cols - 1, CORNER_MAX);

        // Top & bottom borders (excluding corners)
        for (int col = 1; col < cols - 1; col++) {
            set(matrix, 0, col, EDGE_MAX);
            set(matrix, rows - 1, col, EDGE_MAX);
        }

        // Left & right borders (excluding corners & previously set edges)
        for (int row = 1; row < rows - 1; row++) {
            set(matrix, row, 0, EDGE_MAX);
            set(matrix, row, cols - 1, EDGE_MAX);
        }

        // Interior cells
        for (int row = 1; row < rows - 1; row++) {
            for (int col = 1; col < cols - 1; col++) {
                set(matrix, row, col, INTERIOR_MAX);
            }
        }
    }

    /**
     * Helper to write a value into the matrix (used by {@link #assignDefaultPattern}).
     *
     * @param matrix the target matrix
     * @param r      row index
     * @param c      column index
     * @param value  value to assign
     */
    private static void set(int[][] matrix, int r, int c, int value) {
        matrix[r][c] = value;
    }

    /**
     * Checks whether a value exceeds the supplied limit.
     *
     * @param value the actual value
     * @param limit the maximum allowed value
     * @return {@code true} if {@code value > limit}, {@code false} otherwise
     */
    private static boolean exceeds(int value, int limit) {
        return value > limit;
    }

    /**
     * Prints the matrix to the provided {@link PrintWriter}, using a space‑separated
     * format for each row.
     *
     * @param matrix the matrix to print
     * @param out    the writer to which the matrix is written
     */
    private static void printMatrix(int[][] matrix, PrintWriter out) {
        for (int[] row : matrix) {
            StringBuilder sb = new StringBuilder();
            sb.append(row[0]);
            for (int i = 1; i < row.length; i++) {
                sb.append(' ');
                sb.append(row[i]);
            }
            out.println(sb);
        }
    }
}

import java.io.IOException;
import java.util.Scanner;

/**
 * Solution for the problem processed in the original {@code Codechef} class.
 * The program reads several test cases, each consisting of a matrix,
 * performs a specific validation / adjustment algorithm and prints
 * {@code YES} together with the adjusted matrix or {@code NO} if the
 * adjustment is impossible.
 *
 * The implementation focuses on readability, proper encapsulation and
 * resource handling.
 */
public class Solution {

    /** Entry point of the program. */
    public static void main(String[] args) throws IOException {
        // Try‑with‑resources guarantees that the Scanner is closed automatically.
        try (Scanner scanner = new Scanner(System.in)) {
            int tests = scanner.nextInt();                     // number of test cases
            while (tests-- > 0) {
                // read matrix dimensions
                int rows = scanner.nextInt();
                int cols = scanner.nextInt();

                // read matrix data
                int[][] matrix = readMatrix(scanner, rows, cols);

                // perform the validation / adjustment
                boolean possible = processMatrix(matrix, rows, cols);

                // output the result for this test case
                if (possible) {
                    System.out.println("YES");
                    printMatrix(matrix, rows, cols);
                } else {
                    System.out.println("NO");
                }
            }
        }
    }

    /**
     * Reads a matrix of the given size from the scanner.
     *
     * @param scanner  scanner used for input
     * @param rows     number of rows
     * @param cols     number of columns
     * @return the matrix as a 2‑dimensional array
     */
    private static int[][] readMatrix(Scanner scanner, int rows, int cols) {
        int[][] matrix = new int[rows][cols];
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                matrix[i][j] = scanner.nextInt();
            }
        }
        return matrix;
    }

    /**
     * Main algorithm for a single test case.
     * It validates each non‑zero cell, adjusts values when necessary
     * and returns {@code true} if the whole matrix can be processed,
     * otherwise {@code false}.
     *
     * @param mat      matrix to be processed (modified in‑place)
     * @param rows     number of rows
     * @param cols     number of columns
     * @return {@code true} if adjustment succeeded for all cells
     */
    private static boolean processMatrix(int[][] mat, int rows, int cols) {
        boolean overallSuccess = true;

        // First pass – validate each cell and adjust if necessary
        for (int i = 0; i < rows && overallSuccess; i++) {
            for (int j = 0; j < cols && overallSuccess; j++) {
                if (mat[i][j] == 0) {
                    continue; // nothing to do for zero cells
                }

                int neighborSum = calculateNeighborSum(mat, rows, cols, i, j);
                int diff = mat[i][j] - neighborSum;

                if (diff == 0) {
                    continue; // already balanced
                }

                if (diff < 0) {
                    // set the cell to the sum of its non‑zero neighbours
                    mat[i][j] = neighborSum;
                } else {
                    // try to distribute the deficit among neighbouring zeros
                    if (!distributeDeficit(mat, rows, cols, i, j, diff)) {
                        overallSuccess = false; // cannot fix this cell
                    }
                }
            }
        }

        return overallSuccess;
    }

    /**
     * Calculates the sum of the non‑zero orthogonal neighbours of a cell.
     *
     * @param mat      matrix under inspection
     * @param rows     matrix row count
     * @param cols     matrix column count
     * @param i        row index of the cell
     * @param j        column index of the cell
     * @return sum of non‑zero neighbour values
     */
    private static int calculateNeighborSum(int[][] mat, int rows, int cols, int i, int j) {
        int sum = 0;
        if (i - 1 >= 0 && mat[i - 1][j] != 0) sum++;
        if (j - 1 >= 0 && mat[i][j - 1] != 0) sum++;
        if (i + 1 < rows && mat[i + 1][j] != 0) sum++;
        if (j + 1 < cols && mat[i][j + 1] != 0) sum++;
        return sum;
    }

    /**
     * Attempts to distribute a given {@code deficit} among the orthogonal
     * neighbour cells that are currently zero. The method increases those
     * neighbours by one until the deficit is exhausted or no more neighbours
     * are available.
     *
     * @param mat      matrix being modified
     * @param rows     number of rows
     * @param cols     number of columns
     * @param i        row index of the originating cell
     * @param j        column index of the originating cell
     * @param deficit  amount that needs to be added to neighbours
     * @return {@code true} if the deficit could be completely distributed,
     *         {@code false} otherwise
     */
    private static boolean distributeDeficit(int[][] mat, int rows, int cols,
                                             int i, int j, int deficit) {
        // Helper array that defines the order in which neighbours are tried.
        // This mirrors the original code's order: up, left, down, right.
        int[] dr = {-1, 0, 1, 0};
        int[] dc = {0, -1, 0, 1};

        for (int dir = 0; dir < 4; dir++) {
            int ni = i + dr[dir];
            int nj = j + dc[dir];
            if (isInside(ni, nj, rows, cols) && mat[ni][nj] == 0) {
                mat[ni][nj] = 1;          // increase neighbour
                deficit--;
                if (deficit == 0) {
                    return true;          // successfully used up the whole deficit
                }
            }
        }
        // If we exit the loop the deficit could not be satisfied.
        return deficit == 0;
    }

    /** Utility to check whether a cell coordinate is inside the matrix bounds. */
    private static boolean isInside(int r, int c, int rows, int cols) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    /**
     * Prints the matrix to standard output. Zero cells are printed as {@code 0},
     * non‑zero cells are printed after a space. Each row ends with a newline.
     *
     * @param mat   matrix to print
     * @param rows  number of rows
     * @param cols  number of columns
     */
    private static void printMatrix(int[][] mat, int rows, int cols) {
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                // The original program printed a space after every element,
                // even after the last one in a row – we keep that exact format.
                System.out.print(mat[i][j] + " ");
            }
            System.out.println();
        }
    }
}

import java.util.Scanner;

/**
 * Refactored version of the original program.
 *
 * <p>This class reads multiple test cases, evaluates a value for each cell based on its
 * position in the grid, and decides whether the supplied numbers are smaller than the
 * computed values. If every cell satisfies the condition, it prints "YES" followed by the
 * computed grid; otherwise it prints "NO".</p>
 */
public class Main {

    /** Value for corner cells (4‑corner of the grid). */
    private static final int CORNER_VALUE = 2;
    /** Value for edge (but not corner) cells. */
    private static final int EDGE_VALUE = 3;
    /** Value for interior cells. */
    private static final int INTERIOR_VALUE = 4;

    /**
     * Determines the reference value for a specific cell.
     *
     * @param row    zero‑based row index
     * @param col    zero‑based column index
     * @param rows   total number of rows in the grid
     * @param cols   total number of columns in the grid
     * @return one of {@link #CORNER_VALUE}, {@link #EDGE_VALUE} or {@link #INTERIOR_VALUE}
     */
    private static int computeReferenceValue(int row, int col, int rows, int cols) {
        // Corners
        if ((row == 0 && col == 0) ||
            (row == 0 && col == cols - 1) ||
            (row == rows - 1 && col == 0) ||
            (row == rows - 1 && col == cols - 1)) {
            return CORNER_VALUE;
        }
        // Edges (excluding corners)
        if (row == 0 || row == rows - 1 || col == 0 || col == cols - 1) {
            return EDGE_VALUE;
        }
        // Interior cells
        return INTERIOR_VALUE;
    }

    /**
     * Processes a single test case.
     *
     * @param scanner a {@link Scanner} positioned at the start of the test case data
     */
    private static void processTestCase(Scanner scanner) {
        int rows = scanner.nextInt();
        int cols = scanner.nextInt();

        // Read the input grid
        int[][] input = new int[rows][cols];
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                input[i][j] = scanner.nextInt();
            }
        }

        // Compute reference values and check the condition
        StringBuilder outputBuilder = new StringBuilder();
        boolean allSatisfy = true;

        for (int i = 0; i < rows && allSatisfy; i++) {
            for (int j = 0; j < cols; j++) {
                int reference = computeReferenceValue(i, j, rows, cols);
                if (input[i][j] > reference) {
                    allSatisfy = false;               // Condition violated
                } else {
                    outputBuilder.append(reference).append(' ');
                }
            }
        }

        if (!allSatisfy) {
            System.out.println("NO");
        } else {
            System.out.println("YES");
            // Trim trailing space before printing the grid
            String trimmed = outputBuilder.toString().trim();
            System.out.println(trimmed);
        }
    }

    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            int testCases = scanner.nextInt();

            while (testCases-- > 0) {
                processTestCase(scanner);
            }
        }
    }
}

import java.util.Scanner;

/**
 * Main entry point of the program.
 *
 * <p>This refactor extracts the logic that handles a single test case into a
 * dedicated class {@link MatrixProcessor}.  All validation and transformation
 * steps are performed in clearly‑named methods, making the code easier to
 * read, test and maintain.</p>
 */
public class Solution {

    /**
     * Wrapper that holds the matrix data and the operations that must be applied
     * to it for a single test case.
     */
    private static final class MatrixProcessor {
        private final int rows;
        private final int columns;
        private final int[][] board;

        MatrixProcessor(int rows, int columns, int[][] board) {
            this.rows = rows;
            this.columns = columns;
            this.board = board;
        }

        /**
         * Executes the validation and transformation steps for the current test
         * case and prints the appropriate output.
         */
        void processAndPrint() {
            if (!isValidInitialBoard()) {
                System.out.println("NO");
                return;
            }

            setBorderValues();
            fillInnerWithFour();

            System.out.println("YES");
            printBoard();
        }

        /**
         * Checks whether the supplied matrix satisfies all pre‑conditions:
         * <ul>
         *   <li>No element larger than 4.</li>
         *   <li>Corner cells are at most 2.</li>
         *   <li>All border cells (except corners) are at most 3.</li>
         * </ul>
         *
         * @return {@code true} if the matrix passes all checks.
         */
        private boolean isValidInitialBoard() {
            // 1. No value may exceed 4 anywhere in the matrix
            outer:
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < columns; j++) {
                    if (board[i][j] > 4) {
                        return false;
                    }
                }
            }

            // 2. Corner cells must be ≤ 2
            if (board[0][0] > 2 || board[0][columns - 1] > 2 ||
                board[rows - 1][0] > 2 || board[rows - 1][columns - 1] > 2) {
                return false;
            }

            // 3. Remaining border cells must be ≤ 3
            for (int j = 0; j < columns; j++) {
                if (board[0][j] > 3 || board[rows - 1][j] > 3) {
                    return false;
                }
            }
            for (int i = 0; i < rows; i++) {
                if (board[i][0] > 3 || board[i][columns - 1] > 3) {
                    return false;
                }
            }

            return true;
        }

        /**
         * Sets all border cells to the required constant values:
         * <ul>
         *   <li>Corners → 2</li>
         *   <li>Other border cells → 3</li>
         * </ul>
         */
        private void setBorderValues() {
            // corners become 2
            board[0][0] = board[0][columns - 1] = board[rows - 1][0] = board[rows - 1][columns - 1] = 2;

            // top and bottom rows (entire width)
            for (int j = 0; j < columns; j++) {
                board[0][j] = 3;
                board[rows - 1][j] = 3;
            }

            // left and right columns (full height)
            for (int i = 0; i < rows; i++) {
                board[i][0] = 3;
                board[i][columns - 1] = 3;
            }
        }

        /**
         * Fills every non‑border cell with the constant value 4.
         */
        private void fillInnerWithFour() {
            for (int i = 1; i < rows - 1; i++) {
                for (int j = 1; j < columns - 1; j++) {
                    board[i][j] = 4;
                }
            }
        }

        /** Prints the processed matrix in the required format. */
        private void printBoard() {
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < columns; j++) {
                    System.out.print(board[i][j]);
                    if (j < columns - 1) {
                        System.out.print(' ');
                    }
                }
                System.out.println();
            }
        }
    }

    /**
     * Creates a {@link MatrixProcessor} from the scanner, reading the matrix
     * dimensions and values.
     */
    private static MatrixProcessor createProcessor(Scanner scanner) {
        int n = scanner.nextInt();
        int m = scanner.nextInt();
        int[][] arr = new int[n][m];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                arr[i][j] = scanner.nextInt();
            }
        }
        return new MatrixProcessor(n, m, arr);
    }

    /**
     * Program entry point.  Reads the number of test cases and processes each
     * one sequentially.
     */
    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            int t = scanner.nextInt();
            for (int i = 0; i < t; i++) {
                MatrixProcessor processor = createProcessor(scanner);
                processor.processAndPrint();
            }
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Refactored version of the original program.
 * The logic is unchanged, but the code is now organized,
 * uses expressive names, and isolates responsibilities into small,
 * well‑named methods.
 */
public class Solution {

    /* -------------------------------------------------------------
       1️⃣  Input handling
       ------------------------------------------------------------- */
    private static final class FastReader {
        private final BufferedReader br;
        private StringTokenizer st;

        FastReader() {
            this.br = new BufferedReader(new InputStreamReader(System.in));
        }

        /** Returns the next non‑empty token from stdin. */
        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    throw new UncheckedIOException(e);
                }
            }
            return st.nextToken();
        }

        /** Utility wrapper around {@code next()} that parses an {@code int}. */
        int nextInt() {
            return Integer.parseInt(next());
        }
    }

    /* -------------------------------------------------------------
       2️⃣  Result holder – separates outcome from the built matrix.
       ------------------------------------------------------------- */
    private static final class ProcessResult {
        final boolean possible;   // true → a feasible matrix exists
        final int[][] matrix;     // the matrix that should be printed when possible

        ProcessResult(boolean possible, int[][] matrix) {
            this.possible = possible;
            this.matrix = matrix;
        }
    }

    /* -------------------------------------------------------------
       3️⃣  Main entry point
       ------------------------------------------------------------- */
    public static void main(String[] args) throws IOException {
        new Solution().run();
    }

    /* -------------------------------------------------------------
       4️⃣  Orchestrator – reads one test case, processes it,
           and prints the answer.
       ------------------------------------------------------------- */
    public void run() throws IOException {
        try (FastReader fr = new FastReader()) {
            int testCases = fr.nextInt();

            for (int t = 0; t < testCases; t++) {
                processSingleTestCase(fr);
            }
        }
    }

    /** Reads the dimensions and values of a single test case, then solves it. */
    private void processSingleTestCase(FastReader fr) {
        int rows = fr.nextInt();
        int cols = fr.nextInt();

        int[][] values = new int[rows][cols];

        // --- read the raw numbers -------------------------------------------------
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                values[i][j] = fr.nextInt();
            }
        }

        // --- core validation & construction ---------------------------------------
        ProcessResult result = evaluateAndBuild(values, rows, cols);
        if (result.possible) {
            System.out.println("YES");
            printMatrix(result.matrix);
        } else {
            System.out.println("NO");
        }
    }

    /* -------------------------------------------------------------
       5️⃣  Core algorithm – validation + matrix construction.
           All steps are extracted into tiny, self‑documenting methods.
       ------------------------------------------------------------- */
    /** Returns a {@link ProcessResult} that contains the outcome and the matrix. */
    private ProcessResult evaluateAndBuild(int[][] values, int rows, int cols) {
        // 1️⃣  Global bound check – every entry must be ≤ 4
        if (!allValuesAreAtMostFour(values)) {
            return new ProcessResult(false, values);
        }

        // 2️⃣  Create a structure that tracks which cells have been assigned a value
        boolean[][] visited = createVisitedGrid(rows, cols);

        // 3️⃣  Fill the interior (non‑border) cells with 4 and mark them visited
        fillInteriorWithFour(values, visited, rows, cols);

        // 4️⃣  Corner constraints – each corner must be ≤ 2
        if (!cornersSatisfyConstraints(values, rows, cols)) {
            return new ProcessResult(false, values);
        }

        // 5️⃣  Set corners to the required value 2 and mark them visited
        setCornerValues(values, rows, cols);
        markCorners(visited, rows, cols);

        // 6️⃣  Any remaining unvisited cell must become 3,
        //     but only if it does not exceed 3 after the previous steps
        fillRemainingCells(values, visited, rows, cols);

        // 7️⃣  All checks passed – return the constructed matrix
        return new ProcessResult(true, values);
    }

    /** Global bound check – all numbers must be ≤ 4. */
    private boolean allValuesAreAtMostFour(int[][] values) {
        for (int[] row : values) {
            for (int v : row) {
                if (v > 4) {
                    return false;
                }
            }
        }
        return true;
    }

    /** Creates a boolean grid used to remember which cells have been processed. */
    private boolean[][] createVisitedGrid(int rows, int cols) {
        boolean[][] visited = new boolean[rows][cols];
        // Initially none are visited – callers fill the array as they go.
        return visited;
    }

    /** Marks interior cells (≥1 row/col from each border) as visited and sets them to 4. */
    private void fillInteriorWithFour(int[][] values, boolean[][] visited, int rows, int cols) {
        for (int i = 1; i < rows - 1; i++) {
            for (int j = 1; j < cols - 1; j++) {
                values[i][j] = 4;
                visited[i][j] = true;
            }
        }
    }

    /** Verifies that each corner value ≤ 2. */
    private boolean cornersSatisfyConstraints(int[][] values, int rows, int cols) {
        return values[0][0] <= 2 && values[0][cols - 1] <= 2
                && values[rows - 1][cols - 1] <= 2 && values[rows - 1][0] <= 2;
    }

    /** Sets the four corner cells to the value 2. */
    private void setCornerValues(int[][] values, int rows, int cols) {
        values[0][0] = values[0][cols - 1] = values[rows - 1][cols - 1] = values[rows - 1][0] = 2;
    }

    /** Marks the four corners as visited. */
    private void markCorners(boolean[][] visited, int rows, int cols) {
        visited[0][0] = visited[0][cols - 1] = visited[rows - 1][cols - 1] = visited[rows - 1][0] = true;
    }

    /** Fills all still‑unvisited cells with 3, provided they don't exceed 3 after prior steps. */
    private void fillRemainingCells(int[][] values, boolean[][] visited, int rows, int cols) {
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (!visited[i][j]) {
                    if (values[i][j] > 3) {
                        // This makes the whole test case impossible.
                        // We simply return; the caller will treat it as "NO".
                        return;
                    }
                    values[i][j] = 3;
                    visited[i][j] = true;
                }
            }
        }
    }

    /* -------------------------------------------------------------
       6️⃣  Utility – pretty‑printing the matrix.
       ------------------------------------------------------------- */
    private void printMatrix(int[][] matrix) {
        for (int[] row : matrix) {
            StringBuilder line = new StringBuilder();
            for (int val : row) {
                line.append(val).append(' ');
            }
            System.out.println(line.toString().trim());
        }
    }
}

import java.util.Scanner;

/**
 * Reads multiple grid tests, checks whether each grid satisfies the adjacency
 * condition, and if it does outputs a grid where each cell contains the number
 * of its adjacent cells.
 */
public class NeighborGrid {

    /** Program entry point. */
    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            int numberOfTests = scanner.nextInt();
            GridTest[] tests = readTests(scanner, numberOfTests);

            for (GridTest test : tests) {
                boolean possible = GridValidator.isValid(test.grid);
                System.out.println(possible ? "YES" : "NO");
                if (possible) {
                    int[][] result = GridAdjuster.computeAdjacencyGrid(test.grid);
                    GridPrinter.print(result);
                }
            }
        }
    }

    /** Reads all test cases from the supplied {@link Scanner}. */
    private static GridTest[] readTests(Scanner scanner, int count) {
        GridTest[] tests = new GridTest[count];
        for (int i = 0; i < count; i++) {
            int rows = scanner.nextInt();
            int cols = scanner.nextInt();
            int[][] grid = new int[rows][cols];
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    grid[r][c] = scanner.nextInt();
                }
            }
            tests[i] = new GridTest(grid);
        }
        return tests;
    }
}

/** Simple container that holds a read‑only grid. */
final class GridTest {
    final int[][] grid;

    GridTest(int[][] grid) {
        this.grid = grid;
    }
}

/** Encapsulates all validation logic for a grid. */
final class GridValidator {

    private GridValidator() { }

    /**
     * Determines whether every cell respects the rule that the number of its
     * adjacent cells is at least the value stored in that cell.
     *
     * @param grid the test grid
     * @return {@code true} if the grid satisfies the rule
     */
    static boolean isValid(int[][] grid) {
        for (int i = 0; i < grid.length; i++) {
            for (int j = 0; j < grid[0].length; j++) {
                if (adjacentCount(grid, i, j) < grid[i][j]) {
                    return false;
                }
            }
        }
        return true;
    }

    /** Returns the number of orthogonal neighbours of the cell at (i, j). */
    private static int adjacentCount(int[][] grid, int i, int j) {
        int rows = grid.length;
        int cols = grid[0].length;
        if (isInterior(i, j, rows, cols)) {
            return 4;
        }
        if (isCorner(i, j, rows, cols)) {
            return 2;
        }
        return 3; // edge but not corner
    }

    private static boolean isInterior(int i, int j, int rows, int cols) {
        return i > 0 && i < rows - 1 && j > 0 && j < cols - 1;
    }

    private static boolean isCorner(int i, int j, int rows, int cols) {
        return (i == 0 || i == rows - 1) && (j == 0 || j == cols - 1);
    }
}

/** Performs the transformation that creates the adjacency grid. */
final class GridAdjuster {

    private GridAdjuster() { }

    /**
     * Builds a new grid where each cell contains the number of its adjacent cells.
     *
     * @param source the original grid
     * @return a grid of adjacency counts
     */
    static int[][] computeAdjacencyGrid(int[][] source) {
        int rows = source.length;
        int cols = source[0].length;
        int[][] result = new int[rows][cols];
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                result[i][j] = GridValidator.adjacentCount(source, i, j);
            }
        }
        return result;
    }
}

/** Utility class for printing a 2‑dimensional integer array. */
final class GridPrinter {

    private GridPrinter() { }

    static void print(int[][] grid) {
        for (int[] row : grid) {
            for (int value : row) {
                System.out.print(value + " ");
            }
            System.out.println();
        }
    }
}

// Refactored solution – clearer structure, better naming, and easier to maintain.
// All functionality is encapsulated inside the `Solution` class.
// The program reads multiple test cases, checks a local‑grid condition,
// and prints either "NO" if the condition cannot be satisfied or "YES" followed
// by a grid of neighbor counts otherwise.
//
// Compilation: javac Solution.java
// Execution  : java Solution
//
// NOTE: No external dependencies are required; the program relies only on the
// standard Java library.

import java.io.BufferedReader;
import java.io.IOException;
import java.io.PrintWriter;
import java.util.StringTokenizer;

public class Solution {

    // Directions used to count neighbours (up, down, left, right)
    private static final int[] DX = {1, -1, 0, 0};
    private static final int[] DY = {0, 0, 1, -1};

    /* -----------------------------------------------------------
       Entry point – uses try‑with‑resources to guarantee proper closure
       of I/O streams.
       ----------------------------------------------------------- */
    public static void main(String[] args) throws IOException {
        try (BufferedReader br = new BufferedReader(new java.io.InputStreamReader(System.in))) {
            new Solver(br, new PrintWriter(System.out)).run();
        }
    }

    /* -----------------------------------------------------------
       Solver encapsulates all processing logic.
       ----------------------------------------------------------- */
    private static final class Solver {

        private final BufferedReader br;
        private final PrintWriter out;

        Solver(BufferedReader br, PrintWriter out) {
            this.br = br;
            this.out = out;
        }

        // Convenience method to read the next non‑empty line token.
        private String readToken() throws IOException {
            while (true) {
                String line = br.readLine();
                if (line == null) {
                    return null;                 // EOF reached
                }
                line = line.trim();
                if (!line.isEmpty()) {
                    return line;
                }
            }
        }

        // Wrapper around `Integer.parseInt` for the problem's input format.
        private int nextInt() throws IOException {
            return Integer.parseInt(readToken());
        }

        /** Executes the whole workflow for all test cases. */
        void run() throws IOException {
            int testCount = nextInt();
            for (int t = 0; t < testCount; ++t) {
                solveOneCase();
            }
            out.flush();
        }

        /** Solves a single test case. */
        private void solveOneCase() throws IOException {
            int rows = nextInt();
            int cols = nextInt();

            // Read the input grid.
            int[][] grid = new int[rows][];
            for (int i = 0; i < rows; ++i) {
                int[] row = new int[cols];
                for (int j = 0; j < cols; ++j) {
                    row[j] = nextInt();
                }
                grid[i] = row;
            }

            // Compute neighbour counts for every cell.
            int[][] neighbourCount = new int[rows][cols];
            for (int i = 0; i < rows; ++i) {
                for (int j = 0; j < cols; ++j) {
                    int count = 0;
                    for (int d = 0; d < 4; ++d) {
                        int ni = i + DX[d];
                        int nj = j + DY[d];
                        if (isInside(ni, nj, rows, cols)) {
                            ++count;
                        }
                    }
                    neighbourCount[i][j] = count;
                }
            }

            // Verify that each cell's required value does not exceed its neighbour count.
            for (int i = 0; i < rows; ++i) {
                for (int j = 0; j < cols; ++j) {
                    if (grid[i][j] > neighbourCount[i][j]) {
                        out.println("NO");
                        return;
                    }
                }
            }

            // All checks passed – output "YES" and the neighbour count grid.
            out.println("YES");
            printNeighbourGrid(neighbourCount);
        }

        private boolean isInside(int x, int y, int rows, int cols) {
            return x >= 0 && x < rows && y >= 0 && y < cols;
        }

        private void printNeighbourGrid(int[][] grid) {
            for (int i = 0; i < grid.length; ++i) {
                StringBuilder sb = new StringBuilder();
                for (int j = 0; j < grid[i].length; ++j) {
                    sb.append(grid[i][j]);
                    if (j + 1 < grid[i].length) {
                        sb.append(' ');
                    }
                }
                out.println(sb);
            }
        }
    }
}

import java.io.*;
import java.util.*;

public class Solution {

    /** Constants that describe the value to print on each cell type */
    private static final int CORNER      = 2;
    private static final int EDGE        = 3;
    private static final int INTERIOR    = 4;

    public static void main(String[] args) throws IOException {
        /* Try‑with‑resources guarantees that the scanner is closed properly */
        try (FastScanner fs = new FastScanner()) {
            StringBuilder output = new StringBuilder();
            int T = fs.nextInt();

            for (int tt = 0; tt < T; tt++) {
                int m = fs.nextInt();
                int n = fs.nextInt();
                int[][] matrix = fs.readMatrix(m, n);

                if (!isValid(matrix, m, n)) {
                    output.append("NO").append(System.lineSeparator());
                } else {
                    output.append("YES").append(System.lineSeparator());
                    printPattern(output, m, n);
                }
            }

            System.out.print(output.toString());
        }
    }

    /**
     * Checks whether the given matrix respects the constraints described
     * in the original problem statement.
     *
     * @param a   matrix to validate
     * @param m   number of rows
     * @param n   number of columns
     * @return true if the matrix is valid, false otherwise
     */
    private static boolean isValid(int[][] a, int m, int n) {
        /* Corner cells may contain at most 2 */
        if (a[0][0] > 2 || a[m - 1][0] > 2 || a[0][n - 1] > 2 || a[m - 1][n - 1] > 2) {
            return false;
        }

        /* Edge (non‑corner) cells may contain at most 3 */
        for (int i = 1; i < m - 1; i++) {
            if (a[i][0] > 3 || a[i][n - 1] > 3) {
                return false;
            }
        }
        for (int j = 1; j < n - 1; j++) {
            if (a[0][j] > 3 || a[m - 1][j] > 3) {
                return false;
            }
        }

        /* Interior cells may contain at most 4 */
        for (int i = 1; i < m - 1; i++) {
            for (int j = 1; j < n - 1; j++) {
                if (a[i][j] > 4) {
                    return false;
                }
            }
        }

        return true;
    }

    /**
     * Appends the deterministic pattern (2/3/4 values) to the provided
     * StringBuilder. The pattern depends only on the cell's position
     * relative to the matrix borders.
     *
     * @param sb   destination where the pattern is written
     * @param m    number of rows
     * @param n    number of columns
     */
    private static void printPattern(StringBuilder sb, int m, int n) {
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                int value = INTERIOR;

                if (i == 0 || i == m - 1) {
                    value--;
                }
                if (j == 0 || j == n - 1) {
                    value--;
                }

                sb.append(value).append(' ');
            }
            sb.append(System.lineSeparator());
        }
    }

    /**
     * Fast scanner that can be used with try‑with‑resources.
     * It wraps {@link BufferedReader} and tokenizes using {@link StringTokenizer}.
     */
    static final class FastScanner implements AutoCloseable {

        /** Buffered input stream */
        private final BufferedReader br;
        /** Tokenizer reused for each read operation */
        private StringTokenizer st;

        /** Creates a scanner that reads from standard input. */
        FastScanner() {
            this(System.in);
        }

        /** Creates a scanner that reads from a given input stream. */
        FastScanner(InputStream stream) {
            this.br = new BufferedReader(new InputStreamReader(stream));
        }

        /** Ensures that a tokenizer is ready and contains tokens. */
        private void ensureTokenizer() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) {
                        return; // EOF
                    }
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new UncheckedIOException(e);
                }
            }
        }

        /** Returns the next token as a {@link String}. */
        String next() {
            ensureTokenizer();
            return st.nextToken();
        }

        /** Parses the next token as an {@code int}. */
        int nextInt() {
            return Integer.parseInt(next());
        }

        /** Reads an integer array of the given length. */
        int[] readArray(int length) {
            int[] arr = new int[length];
            for (int i = 0; i < length; i++) {
                arr[i] = nextInt();
            }
            return arr;
        }

        /** Reads a matrix of size {@code rows × cols}. */
        int[][] readMatrix(int rows, int cols) {
            int[][] matrix = new int[rows][];
            for (int i = 0; i < rows; i++) {
                matrix[i] = readArray(cols);
            }
            return matrix;
        }

        /** Closes the underlying {@link BufferedReader}. */
        @Override
        public void close() {
            try {
                br.close();
            } catch (IOException e) {
                throw new UncheckedIOException(e);
            }
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;

/**
 * Reads matrix data, validates each element according to its position
 * (corner ≤ 2, edge ≤ 3, interior ≤ 4) and prints "YES"/"NO".
 * If the matrix is valid, it also prints the matrix filled with the
 * corresponding maximum allowed values.
 */
public class Main {

    /** Maximum value that may appear on a corner cell. */
    private static final int CORNER_MAX = 2;
    /** Maximum value that may appear on an edge (but not corner) cell. */
    private static final int EDGE_MAX = 3;
    /** Maximum value that may appear on an interior cell. */
    private static final int INTERIOR_MAX = 4;

    public static void main(String[] args) throws IOException {
        // Try‑with‑resources guarantees the stream is closed properly.
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in))) {
            int testCases = Integer.parseInt(br.readLine().trim());

            // The original code used `while(t--!=0)` which behaves like
            // `while (t-- > 0)` after fixing the condition.
            while (testCases-- > 0) {
                processSingleTestCase(br);
            }
        }
    }

    /**
     * Reads the dimensions, the matrix data and decides whether the matrix
     * respects the per‑position value limits.
     */
    private static void processSingleTestCase(BufferedReader br) throws IOException {
        // ----- read dimensions -------------------------------------------------
        String line = br.readLine();
        if (line == null) {
            return; // no more input
        }
        String[] dims = line.trim().split("\\s+");
        int rows = Integer.parseInt(dims[0]);
        int cols = Integer.parseInt(dims[1]);

        // ----- read matrix ------------------------------------------------------
        int[][] matrix = new int[rows][cols];
        for (int i = 0; i < rows; i++) {
            line = br.readLine();
            String[] rowValues = line.trim().split("\\s+");
            for (int j = 0; j < cols; j++) {
                matrix[i][j] = Integer.parseInt(rowValues[j]);
            }
        }

        // ----- validation -------------------------------------------------------
        if (isMatrixValid(matrix)) {
            System.out.println("YES");
            printReformattedMatrix(matrix);
        } else {
            System.out.println("NO");
        }
    }

    /** Returns true if every element respects the allowed maximum for its position. */
    private static boolean isMatrixValid(int[][] mat) {
        int n = mat.length;
        int m = mat[0].length;

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                int value = mat[i][j];
                int maxAllowed = getMaxAllowed(i, j, n, m);
                if (value > maxAllowed) {
                    return false;
                }
            }
        }
        return true;
    }

    /** Determines the maximum permissible value for cell (i, j). */
    private static int getMaxAllowed(int i, int j, int n, int m) {
        if (isCorner(i, j, n, m)) {
            return CORNER_MAX;
        }
        if (isEdge(i, j, n, m)) {
            return EDGE_MAX;
        }
        return INTERIOR_MAX;
    }

    /** Checks whether (i, j) is one of the four corner cells. */
    private static boolean isCorner(int i, int j, int n, int m) {
        return (i == 0 && j == 0) ||
               (i == n - 1 && j == 0) ||
               (i == 0 && j == m - 1) ||
               (i == n - 1 && j == m - 1);
    }

    /** Checks whether (i, j) lies on the border but is not a corner. */
    private static boolean isEdge(int i, int j, int n, int m) {
        return i == 0 || i == n - 1 || j == 0 || j == m - 1;
    }

    /** Prints the matrix where each cell is replaced by its allowed maximum value. */
    private static void printReformattedMatrix(int[][] mat) {
        int n = mat.length;
        int m = mat[0].length;
        for (int i = 0; i < n; i++) {
            StringBuilder line = new StringBuilder();
            for (int j = 0; j < m; j++) {
                if (isCorner(i, j, n, m)) {
                    line.append(CORNER_MAX).append(' ');
                } else if (isEdge(i, j, n, m)) {
                    line.append(EDGE_MAX).append(' ');
                } else {
                    line.append(INTERIOR_MAX).append(' ');
                }
            }
            // Remove trailing space before line‑break.
            System.out.println(line.toString().trim());
        }
    }
}

/**
 * Refactored solution for CF1375_D2_B.
 *
 * The program processes multiple test cases. For each test case it reads a grid,
 * decides whether the grid can be transformed according to the problem rules and,
 * if possible, prints the transformed grid.
 *
 * Author:  (your name)
 * Created: 2025‑0‑01
 */
public class Main {

    /** Directions to the four orthogonal neighbours (up, down, left, right). */
    private static final int[][] DIRS = {
            {-1, 0}, // up
            {1, 0},  // down
            {0, -1}, // left
            {0, 1}   // right
    };

    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            int testCount = scanner.nextInt();
            for (int i = 0; i < testCount; i++) {
                solveCase(scanner);
            }
        }
    }

    /**
     * Reads one test case, processes it and prints the result.
     */
    private static void solveCase(Scanner scanner) {
        int n = scanner.nextInt(); // number of rows
        int m = scanner.nextInt(); // number of columns
        int[][] grid = readGrid(scanner, n, m);

        if (isAllZeros(grid)) {
            System.out.println("YES");
            printGrid(grid);
            return;
        }

        // Try to adjust each non‑zero cell so that the adjacency count matches its value.
        for (int row = 0; row < n; row++) {
            for (int col = 0; col < m; col++) {
                if (grid[row][col] != 0) {
                    if (!adjustCell(row, col, grid[row][col], grid)) {
                        System.out.println("NO");
                        return;
                    }
                }
            }
        }

        // After all adjustments, validate the final grid again.
        for (int row = 0; row < n; row++) {
            for (int col = 0; col < m; col++) {
                if (grid[row][col] != 0) {
                    balanceNeighbourhood(row, col, grid[row][col], grid);
                }
            }
        }

        System.out.println("YES");
        printGrid(grid);
    }

    /** Reads an {@code n}×{@code m} grid from the scanner. */
    private static int[][] readGrid(Scanner scanner, int n, int m) {
        int[][] grid = new int[n][m];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                grid[i][j] = scanner.nextInt();
            }
        }
        return grid;
    }

    /** Returns true if every cell in {@code grid} contains zero. */
    private static boolean isAllZeros(int[][] grid) {
        for (int[] row : grid) {
            for (int value : row) {
                if (value != 0) {
                    return false;
                }
            }
        }
        return true;
    }

    /**
     * Attempts to adjust the value at {@code (row, col)} so that it equals the
     * number of its non‑zero orthogonal neighbours. Returns {@code true} if the
     * adjustment succeeded.
     */
    private static boolean adjustCell(int row, int col, int currentValue, int[][] grid) {
        int neighbourCount = countNonZeroNeighbours(row, col, grid);
        if (neighbourCount > currentValue) {
            grid[row][col] = neighbourCount;
            return true;
        }

        if (neighbourCount == currentValue) {
            return true;
        }

        // Try to increase neighbour count by turning zero neighbours into 1s.
        for (int[] dir : DIRS) {
            int newRow = row + dir[0];
            int newCol = col + dir[1];
            if (isInside(newRow, newCol, grid.length, grid[0].length) && grid[newRow][newCol] == 0) {
                grid[newRow][newCol] = 1;
                neighbourCount++;
                if (neighbourCount == currentValue) {
                    return true;
                }
            }
        }
        return false;
    }

    /**
     * Ensures that the value at {@code (row, col)} equals the number of its
     * non‑zero orthogonal neighbours after all previous adjustments.
     */
    private static void balanceNeighbourhood(int row, int col, int value, int[][] grid) {
        int neighbourCount = countNonZeroNeighbours(row, col, grid);
        if (neighbourCount > value) {
            grid[row][col] = neighbourCount;
        }
    }

    /** Counts how many orthogonal neighbours of {@code (row, col)} are non‑zero. */
    private static int countNonZeroNeighbours(int row, int col, int[][] grid) {
        int count = 0;
        for (int[] dir : DIRS) {
            int newRow = row + dir[0];
            int newCol = col + dir[1];
            if (isInside(newRow, newCol, grid.length, grid[0].length) && grid[newRow][newCol] != 0) {
                count++;
            }
        }
        return count;
    }

    /** Checks whether a coordinate lies inside the grid boundaries. */
    private static boolean isInside(int r, int c, int rows, int cols) {
        return r >= 0 && c >= 0 && r < rows && c < cols;
    }

    /** Prints the 2‑D array to standard output. */
    private static void printGrid(int[][] grid) {
        StringBuilder out = new StringBuilder();
        for (int[] row : grid) {
            for (int cell : row) {
                out.append(cell).append(' ');
            }
            out.append('\n');
        }
        System.out.print(out.toString());
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.StringBuilder;

/**
 * Refactored version of the original {@code LongInteger} program.
 * The functionality remains unchanged, but the code is now more
 * modular, readable and easier to maintain.
 */
public class LongInteger {

    /** Directions used for neighbour checks (up, down, left, right). */
    private static final class Directions {
        private static final int[] DR = {-1, 1, 0, 0};
        private static final int[] DC = {0, 0, -1, 1};

        /** Checks whether a given cell is inside the matrix bounds. */
        private static boolean isInside(int row, int col, int rows, int cols) {
            return row >= 0 && row < rows && col >= 0 && col < cols;
        }
    }

    /** Entry point. */
    public static void main(String[] args) {
        try (BufferedReader reader = new BufferedReader(
                new InputStreamReader(System.in))) {

            int testCases = readInt(reader);
            for (int t = 0; t < testCases; t++) {
                int[] dims = readTwoInts(reader);
                int n = dims[0];
                int m = dims[1];
                int[][] matrix = readMatrix(reader, n, m);
                solve(matrix);
            }

        } catch (IOException e) {
            System.err.println("Error reading input: " + e.getMessage());
        }
    }

    /** Reads a single integer from the supplied reader. */
    private static int readInt(BufferedReader reader) throws IOException {
        return Integer.parseInt(reader.readLine().trim());
    }

    /** Reads two integers (rows and columns) from the supplied reader. */
    private static int[] readTwoInts(BufferedReader reader) throws IOException {
        String[] parts = reader.readLine().split("\\s+");
        return new int[]{Integer.parseInt(parts[0]), Integer.parseInt(parts[1])};
    }

    /** Reads the matrix of the given dimensions from the supplied reader. */
    private static int[][] readMatrix(BufferedReader reader, int rows, int cols)
            throws IOException {

        int[][] matrix = new int[rows][cols];
        for (int i = 0; i < rows; i++) {
            String line = reader.readLine();
            if (line == null) {
                throw new IOException("Unexpected end of input while reading matrix row " + i);
            }
            String[] tokens = line.trim().split("\\s+");
            if (tokens.length != cols) {
                throw new IOException("Row " + i + " does not contain the expected "
                        + cols + " numbers.");
            }
            for (int j = 0; j < cols; j++) {
                matrix[i][j] = Integer.parseInt(tokens[j]);
            }
        }
        return matrix;
    }

    /** Main processing routine – performs the two passes described in the original code. */
    private static void solve(int[][] st) {
        int rows = st.length;
        int cols = st[0].length;

        // ----- First pass: replace every 0 with the number of positive neighbours -----
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (st[r][c] == 0) {
                    int neighbourCount = countPositiveNeighbours(st, r, c, rows, cols);
                    st[r][c] = neighbourCount;
                }
            }
        }

        // ----- Second pass: verify each positive cell equals its positive neighbour count -----
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (st[r][c] > 0) {
                    int neighbourCount = countPositiveNeighbours(st, r, c, rows, cols);
                    if (neighbourCount < st[r][c]) {
                        System.out.println("NO");
                        return;
                    }
                    st[r][c] = neighbourCount; // store neighbour count for final output
                }
            }
        }

        System.out.println("YES");
        printMatrix(st);
    }

    /** Counts how many orthogonal neighbours of (row, col) contain a positive value. */
    private static int countPositiveNeighbours(int[][] matrix,
                                                int row, int col,
                                                int rows, int cols) {
        int count = 0;
        for (int d = 0; d < Directions.DR.length; d++) {
            int nr = row + Directions.DR[d];
            int nc = col + Directions.DC[d];
            if (Directions.isInside(nr, nc, rows, cols) && matrix[nr][nc] > 0) {
                count++;
            }
        }
        return count;
    }

    /** Prints the matrix to standard output using a space between values and a new line after each row. */
    private static void printMatrix(int[][] matrix) {
        for (int[] row : matrix) {
            StringBuilder sb = new StringBuilder();
            for (int value : row) {
                sb.append(value).append(' ');
            }
            System.out.println(sb.toString().trim());
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Refactored solution for problem B_1375.
 *
 * <p>
 * The program reads several test cases. For each test case it:
 * <ul>
 *   <li>Reads an {@code n × m} board of integers.</li>
 *   <li>Computes, for every cell, how many orthogonal neighbours exist on the board.</li>
 *   <li>Verifies that every board value does not exceed the neighbour count of its cell.</li>
 *   <li>Outputs {@code YES} together with the neighbour‑count board when the condition holds,
 *       otherwise outputs {@code NO}.</li>
 * </ul>
 * </p>
 */
public class B1375 {

    /** Directions: right, left, up, down */
    private static final int[][] DIRS = {
            {0, 1},   // right
            {0, -1},  // left
            {-1, 0},  // up
            {1, 0}    // down
    };

    /** Checks whether (x, y) lies inside an {@code n × m} board. */
    private static boolean inBounds(int x, int y, int n, int m) {
        return x >= 0 && x < n && y >= 0 && y < m;
    }

    /**
     * Returns a matrix where each cell contains the number of orthogonal neighbours
     * that exist on the board (i.e. the degree of the cell).
     */
    private static int[][] computeNeighbourDegrees(int n, int m) {
        int[][] degrees = new int[n][m];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                int count = 0;
                for (int[] d : DIRS) {
                    int nx = i + d[0];
                    int ny = j + d[1];
                    if (inBounds(nx, ny, n, m)) {
                        count++;
                    }
                }
                degrees[i][j] = count;
            }
        }
        return degrees;
    }

    /**
     * Solves a single test case.
     *
     * @param sc a {@link Scanner} that reads the input
     * @param out a {@link PrintWriter} used for output
     * @return {@code true} if the board satisfies the required condition
     * @throws IOException if an I/O error occurs
     */
    private static boolean processTestCase(Scanner sc, PrintWriter out) throws IOException {
        int n = sc.nextInt();
        int m = sc.nextInt();

        // Read the board
        int[][] board = new int[n][m];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                board[i][j] = sc.nextInt();
            }
        }

        // Compute neighbour degrees for every cell
        int[][] neighbourDegrees = computeNeighbourDegrees(n, m);

        // Verify that every board value is not larger than its neighbour count
        boolean ok = true;
        outer:
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (board[i][j] > neighbourDegrees[i][j]) {
                    ok = false;
                    break outer;
                }
            }
        }

        // Output result
        out.println(ok ? "YES" : "NO");
        if (ok) {
            StringBuilder line;
            for (int i = 0; i < n; i++) {
                line = new StringBuilder();
                for (int j = 0; j < m; j++) {
                    line.append(neighbourDegrees[i][j]);
                    if (j < m - 1) {
                        line.append(' ');
                    }
                }
                out.println(line);
            }
        }
        return ok;
    }

    /** Main entry point. */
    public static void main(String[] args) throws Exception {
        // Using try‑with‑resources guarantees proper closure of streams
        try (Scanner sc = new Scanner(System.in)) {
            PrintWriter out = new PrintWriter(System.out, true);
            int t = sc.nextInt();
            while (t-- > 0) {
                processTestCase(sc, out);
            }
        }
    }

    /** Simple wrapper around {@link StringTokenizer} for fast token reading. */
    public static class Scanner {
        private final StringTokenizer st;
        private final BufferedReader br;

        /** Creates a scanner that reads from the standard input. */
        public Scanner(InputStream system) {
            br = new BufferedReader(new InputStreamReader(system));
            st = null;
        }

        /** Creates a scanner that reads from a file (not used by {@code main}). */
        public Scanner(String filePath) throws IOException {
            br = new BufferedReader(new FileReader(filePath));
            st = null;
        }

        /** Returns the next token, waiting for input if necessary. */
        public String next() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                st = new StringTokenizer(br.readLine());
            }
            return st.nextToken();
        }

        /** Reads a whole line. */
        public String nextLine() throws IOException {
            return br.readLine();
        }

        /** Reads an {@code int}. */
        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }

        /** Reads an {@code int[]} of length {@code n}. */
        public int[] nextIntArray(int n) throws IOException {
            int[] arr = new int[n];
            for (int i = 0; i < n; i++) {
                arr[i] = nextInt();
            }
            return arr;
        }
    }
}

import java.io.*;
import java.util.*;
import java.util.stream.Collectors;

/**
 * Entry point of the application.
 * <p>
 * The program reads several test cases. For each test case it receives the
 * dimensions of a matrix and the matrix values. It compares those values to a
 * predefined “default” matrix and prints either “YES” followed by that default
 * matrix, or “NO”.
 * </p>
 */
public class Main {

    /** output string used when the answer is negative */
    private static final String NOT_POSSIBLE = "NO";

    /** output string used when the answer is affirmative */
    private static final String POSSIBLE = "YES";

    public static void main(String[] args) {
        try (FastScanner fs = new FastScanner()) {
            int tests = fs.nextInt();                     // number of test cases
            while (tests-- > 0) {
                int rows = fs.nextInt();
                int cols = fs.nextInt();

                int[][] input = fs.readMatrix(rows, cols);
                int[][] expected = GridGenerator.defaultMatrix(rows, cols);

                if (hasExceedingValue(input, expected)) {
                    System.out.println(NOT_POSSIBLE);
                } else {
                    System.out.println(POSSIBLE);
                    GridPrinter.print(expected);
                }
            }
        } catch (Exception e) {
            e.printStackTrace();
        }
    }

    /** Returns {@code true} if any element of {@code src} is larger than the
     * corresponding element of {@code template}. */
    private static boolean hasExceedingValue(int[][] src, int[][] template) {
        for (int i = 0; i < src.length; i++) {
            for (int j = 0; j < src[i].length; j++) {
                if (src[i][j] > template[i][j]) {
                    return true;
                }
            }
        }
        return false;
    }
}

/* -------------------------------------------------------------------------- */
/* Utility components – each one has a single, well‑named responsibility.      */
/* -------------------------------------------------------------------------- */

/**
 * Generates the “default” matrix used for comparison.
 * <ul>
 *   <li>All interior cells are {@value #DEFAULT}.</li>
 *   <li>The four corners are {@value #CORNER}.</li>
 *   <li>Edges (excluding corners) are {@value #EDGE}.</li>
 * </ul>
 */
final class GridGenerator {

    private static final int DEFAULT = 4;
    private static final int CORNER = 2;
    private static final int EDGE = 3;

    private GridGenerator() { /* static‑only class */ }

    static int[][] defaultMatrix(int rows, int cols) {
        int[][] matrix = new int[rows][cols];
        fillWith(matrix, DEFAULT);

        // corners
        matrix[0][0] = CORNER;
        matrix[rows - 1][cols - 1] = CORNER;
        matrix[0][cols - 1] = CORNER;
        matrix[rows - 1][0] = CORNER;

        // top & bottom edges (excluding corners)
        for (int j = 1; j < cols - 1; j++) {
            matrix[0][j] = EDGE;
            matrix[rows - 1][j] = EDGE;
        }

        // left & right edges (excluding corners)
        for (int i = 1; i < rows - 1; i++) {
            matrix[i][0] = EDGE;
            matrix[i][cols - 1] = EDGE;
        }
        return matrix;
    }

    private static void fillWith(int[][] matrix, int value) {
        Arrays.stream(matrix).forEach(row -> Arrays.fill(row, value));
    }
}

/**
 * Handles all I/O operations, providing a convenient token‑based scanner
 * and a helper to read a matrix.
 */
final class FastScanner implements AutoCloseable {

    private final BufferedReader reader;
    private StringTokenizer tokenizer;

    FastScanner() {
        this.reader = new BufferedReader(new InputStreamReader(System.in));
    }

    /** Returns the next available token (skipping whitespace). */
    private String nextToken() {
        while (tokenizer == null || !tokenizer.hasMoreTokens()) {
            try {
                tokenizer = new StringTokenizer(reader.readLine());
            } catch (IOException e) {
                throw new UncheckedIOException(e);
            }
        }
        return tokenizer.nextToken();
    }

    int nextInt() {
        return Integer.parseInt(nextToken());
    }

    long nextLong() {
        return Long.parseLong(nextToken());
    }

    double nextDouble() {
        return Double.parseDouble(nextToken());
    }

    /**
     * Reads a matrix of {@code rows × cols} integers from the scanner.
     */
    int[][] readMatrix(int rows, int cols) {
        int[][] mat = new int[rows][cols];
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                mat[i][j] = nextInt();
            }
        }
        return mat;
    }

    @Override
    public void close() throws IOException {
        reader.close();
    }
}

/**
 * Formats and prints a 2‑D integer array to {@code System.out}.
 */
final class GridPrinter {

    private static final String NEW_LINE = System.lineSeparator();

    private GridPrinter() { /* static‑only class */ }

    static void print(int[][] matrix) {
        StringBuilder out = new StringBuilder();
        for (int[] row : matrix) {
            for (int value : row) {
                out.append(value).append(' ');
            }
            out.append(NEW_LINE);
        }
        System.out.print(out.toString());
    }
}

import java.io.*;
import java.util.StringTokenizer;

/**
 * Refactored solution that reads from {@code input.txt} (if present) or {@code System.in},
 * processes the data and writes the result to {@code output.txt} (if present) or {@code System.out}.
 * The code has been split into small, reusable methods, uses meaningful names and avoids
 * unnecessary dependencies, making it easier to maintain and extend.
 */
public class Main {

    /** Constant used in the original program – kept for compatibility. */
    private static final long MOD = 1_000_000_007L;

    /**
     * Fast scanner that works with a {@link Reader}. It handles tokenisation and parsing
     * of primitive types without pulling in heavyweight libraries.
     */
    private static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner(Reader source) {
            this.br = new BufferedReader(source);
        }

        /** Ensures that a {@link StringTokenizer} with tokens is available. */
        private void ensureTokenizer() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                String line = br.readLine();
                if (line == null) {
                    return; // EOF
                }
                st = new StringTokenizer(line);
            }
        }

        String next() throws IOException {
            ensureTokenizer();
            return st.nextToken();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }

        long nextLong() throws IOException {
            return Long.parseLong(next());
        }
    }

    /** Builds the answer matrix based purely on the position of each cell. */
    private static int[][] buildAnswer(int rows, int cols) {
        int[][] ans = new int[rows][cols];
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if ((i == 0 || i == rows - 1) && (j == 0 || j == cols - 1)) {
                    ans[i][j] = 2;
                } else if (i == 0 || i == rows - 1 || j == 0 || j == cols - 1) {
                    ans[i][j] = 3;
                } else {
                    ans[i][j] = 4;
                }
            }
        }
        return ans;
    }

    /** Checks whether the constructed answer respects the condition {@code ans[i][j] >= input[i][j]}. */
    private static boolean isFeasible(int[][] input, int[][] ans) {
        for (int i = 0; i < input.length; i++) {
            for (int j = 0; j < input[i].length; j++) {
                if (ans[i][j] < input[i][j]) {
                    return false;
                }
            }
        }
        return true;
    }

    /** Solves a single test case and writes the result to the supplied {@link PrintWriter}. */
    private static void solve(FastScanner in, PrintWriter out) {
        int m = in.nextInt();
        int n = in.nextInt();

        int[][] a = new int[m][n];
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                a[i][j] = in.nextInt();
            }
        }

        int[][] ans = buildAnswer(m, n);

        if (!isFeasible(a, ans)) {
            out.println("NO");
            return;
        }

        out.println("YES");
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                out.print(ans[i][j]);
                if (j + 1 < n) out.print(' ');
            }
            out.println();
        }
    }

    /**
     * Entry point of the program. If files named {@code input.txt} or {@code output.txt}
     * exist in the working directory they are used, otherwise standard streams are employed.
     */
    public static void main(String[] args) throws IOException {
        File inputFile = new File("input.txt");
        Reader reader = inputFile.exists()
                ? new FileReader(inputFile)
                : new BufferedReader(new InputStreamReader(System.in));

        File outputFile = new File("output.txt");
        PrintWriter writer = outputFile.exists()
                ? new PrintWriter(new FileWriter(outputFile, true))
                : new PrintWriter(System.out, true);

        try (FastScanner scanner = new FastScanner(reader)) {
            int testCases = scanner.nextInt();   // number of test cases
            for (int t = 0; t < testCases; t++) {
                solve(scanner, writer);
            }
        } finally {
            writer.flush();
        }
    }
}

package competitive;

import java.io.*;
import java.util.*;

public final class B {

    /* -------------------------------------------------------------
     *  Utility class that replaces the old manual BufferedReader/PrintWriter
     * ------------------------------------------------------------- */
    private static final class FastScanner {
        private final BufferedInputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream source) {
            in = new BufferedInputStream(source);
        }

        private int readByte() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        /** Reads the next signed 32‑bit integer. */
        int nextInt() throws IOException {
            int c, sign = 1, val = 0;
            // skip any non‑digit characters
            do {
                c = readByte();
            } while (c <= ' ' && c != -1);

            if (c == '-') {
                sign = -1;
                c = readByte();
            }
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = readByte();
            }
            return val * sign;
        }
    }

    /* -------------------------------------------------------------
     *  Constants – the maximal allowed values for the four zones of the grid
     * ------------------------------------------------------------- */
    private static final int MAX_CORNER = 2;   // cells (0,0), (0,m-1), (n-1,0), (n-1,m-1)
    private static final int MAX_EDGE   = 3;   // cells on the top/bottom/internal row borders
    private static final int MAX_MID    = 4;   // inner cells (i,j) where 1 <= i,j <= n-2,m-2

    public static void main(String[] args) throws IOException {
        try (FastScanner fs = new FastScanner(System.in)) {
            int T = fs.nextInt();
            StringBuilder out = new StringBuilder();
            while (T-- > 0) out.append(solveCase(fs));
            System.out.print(out);
        }
    }

    /** Solves one test case and returns the whole output (including a trailing newline). */
    private static String solveCase(FastScanner fs) {
        int n = fs.nextInt();
        int m = fs.nextInt();
        int[][] grid = new int[n][m];

        // ----- read the entire grid -----
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                grid[i][j] = fs.nextInt();
            }
        }

        // ----- validation step -----
        if (!isBorderValid(grid) || !isInnerValid(grid)) {
            return "NO";
        }

        // ----- construct the answer -----
        StringBuilder ans = new StringBuilder("YES\n");
        appendTopRow(ans, n, m);
        appendMiddleRows(ans, n, m);
        appendBottomRow(ans, n, m);
        return ans.toString();
    }

    /** Returns true if all border cells respect the limits described in the statement. */
    private static boolean isBorderValid(int[][] g) {
        int rows = g.length;
        int cols = g[0].length;

        // corners must be <= 2
        if (g[0][0] > MAX_CORNER || g[0][cols - 1] > MAX_CORNER ||
            g[rows - 1][0] > MAX_CORNER || g[rows - 1][cols - 1] > MAX_CORNER) {
            return false;
        }

        // top & bottom edge cells
        for (int j = 1; j < cols - 1; j++) {
            if (g[0][j] > MAX_EDGE || g[rows - 1][j] > MAX_EDGE) {
                return false;
            }
        }
        // left & right edge cells (excluding corners)
        for (int i = 1; i < rows - 1; i++) {
            if (g[i][0] > MAX_EDGE || g[i][cols - 1] > MAX_EDGE) {
                return false;
            }
        }
        return true;
    }

    /** Returns true if all inner cells respect the inner‑cell limit. */
    private static boolean isInnerValid(int[][] g) {
        int rows = g.length;
        int cols = g[0].length;
        for (int i = 1; i < rows - 1; i++) {
            for (int j = 1; j < cols - 1; j++) {
                if (g[i][j] > MAX_MID) {
                    return false;
                }
            }
        }
        return true;
    }

    /** Appends the specially formed top row to the result builder. */
    private static void appendTopRow(StringBuilder sb, int n, int m) {
        sb.append(MAX_CORNER);
        for (int j = 1; j < m - 1; j++) {
            sb.append(' ').append(MAX_EDGE);
        }
        sb.append(" ").append(MAX_CORNER).append('\n');
    }

    /** Appends all middle rows (i.e. rows 1 … n‑2) to the result builder. */
    private static void appendMiddleRows(StringBuilder sb, int n, int m) {
        for (int i = 1; i < n - 1; i++) {
            sb.append(MAX_EDGE);
            for (int j = 1; j < m - 1; j++) {
                sb.append(' ').append(MAX_MID);
            }
            sb.append(" ").append(MAX_EDGE).append('\n');
        }
    }

    /** Appends the bottom row – identical to the top row – to the builder. */
    private static void appendBottomRow(StringBuilder sb, int n, int m) {
        sb.append(MAX_CORNER);
        for (int j = 1; j < m - 1; j++) {
            sb.append(' ').append(MAX_EDGE);
        }
        sb.append(" ").append(MAX_CORNER);
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.ArrayDeque;
import java.util.StringTokenizer;

/**
 * Refactored version of the original program.
 *
 * <p>Key improvements:
 * <ul>
 *   <li>Extracted responsibilities into small, focused methods.</li>
 *   <li>Used meaningful names for variables and classes.</li>
 *   <li>Added Javadoc comments for clarity.</li>
 *   <li>Implemented try‑with‑resources for safe resource handling.</li>
 *   <li>Avoided raw {@code int[]} tuples; introduced a small {@link Cell} class.</li>
 *   <li>Separated input parsing, processing, and output generation.</li>
 *   <li>Removed magic numbers and kept constants where appropriate.</li>
 * </ul>
 *
 * <p>The logic of the algorithm is preserved, but the code is now easier to read,
 * test, and maintain.
 */
public class Main {

    /** Simple immutable container for a matrix cell coordinate. */
    private static final class Cell {
        final int row;
        final int col;

        Cell(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }

    public static void main(String[] args) {
        /* BufferedReader with try‑with‑resources guarantees proper closing. */
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in))) {
            String line;
            /* The original program consumes the first token and then processes
             * subsequent blocks until EOF. We mimic that behaviour while keeping
             * the loop as simple as possible. */
            while (true) {
                line = br.readLine();
                if (line == null || line.isBlank()) {
                    break; // no more input
                }

                StringTokenizer headerTokens = new StringTokenizer(line);
                int rows = Integer.parseInt(headerTokens.nextToken()); // n
                int cols = Integer.parseInt(headerTokens.nextToken()); // m

                int[][] grid = readGrid(br, rows, cols);
                String result = solve(grid, rows, cols);
                System.out.println(result);
            }
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
    }

    /** Reads a matrix of size {@code rows × cols} from {@code br}. */
    private static int[][] readGrid(BufferedReader br, int rows, int cols) throws IOException {
        int[][] grid = new int[rows][cols];
        for (int r = 0; r < rows; r++) {
            String rowLine = br.readLine();
            if (rowLine == null) {
                throw new IOException("Unexpected end of input while reading grid data.");
            }
            StringTokenizer st = new StringTokenizer(rowLine);
            for (int c = 0; c < cols; c++) {
                grid[r][c] = Integer.parseInt(st.nextToken());
            }
        }
        return grid;
    }

    /** Core solving routine – returns "YES" followed by the degree matrix or "NO". */
    private static String solve(int[][] grid, int rows, int cols) {
        Queue<Cell> queue = new ArrayDeque<>();
        /* Collect all cells that are not equal to 1 – these are the starting points
         * for the validation process described in the original code. */
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] != 1) {
                    queue.add(new Cell(r, c));
                }
            }
        }

        boolean possible = true;
        while (!queue.isEmpty() && possible) {
            Cell cur = queue.poll();
            int neighborCount = countNeighbors(cur, rows, cols);
            if (grid[cur.row][cur.col] > neighborCount) {
                possible = false;
                break;
            }
        }

        if (!possible) {
            return "NO";
        }

        /* If we reach this point, every non‑1 cell satisfied the condition.
         * Compute the degree (number of adjacent cells) for every position,
         * then output the transposed degree matrix as the original program did. */
        int[][] degree = new int[rows][cols];
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                degree[r][c] = countNeighbors(new Cell(r, c), rows, cols);
            }
        }

        StringBuilder out = new StringBuilder("YES\n");
        for (int c = 0; c < cols; c++) {
            for (int r = 0; r < rows; r++) {
                out.append(degree[r][c]).append(' ');
            }
            out.append('\n');
        }
        return out.toString().trim();
    }

    /** Counts how many orthogonal neighbours the given cell has inside the matrix. */
    private static int countNeighbors(Cell cell, int rows, int cols) {
        int count = 0;
        int r = cell.row;
        int c = cell.col;
        if (r > 0) count++;
        if (r + 1 < rows) count++;
        if (c > 0) count++;
        if (c + 1 < cols) count++;
        return count;
    }
}

import java.io.*;
import java.util.*;

public class MatrixProcessor {

    private static final BufferedReader IN = new BufferedReader(
            new InputStreamReader(System.in)
    );
    private static final PrintWriter OUT = new PrintWriter(System.out);
    private static final int MAX_ALLOWED = 4;          // maximum value allowed in input
    private static final int CORNER_VALUE = 2;         // value to write in corners
    private static final int EDGE_VALUE   = 3;         // value to write on non‑corner edges
    private static final int INTERIOR_VALUE = 4;       // value to write inside the matrix

    public static void main(String[] args) throws IOException {
        int tests = Integer.parseInt(nextToken());
        solveAll(tests);
        OUT.flush();
    }

    /** Reads one test case, decides if it can be transformed, and prints the answer. */
    private static void solveAll(int numberOfTests) throws IOException {
        for (int t = 0; t < numberOfTests; t++) {
            solveSingleTest();
        }
    }

    /** Handles the whole logic for a single test case. */
    private static void solveSingleTest() throws IOException {
        int rows = Integer.parseInt(nextToken());
        int cols = Integer.parseInt(nextToken());

        int[][] matrix = readMatrix(rows, cols);

        // 1️⃣  Basic validation -------------------------------------------------
        if (!isValidMatrix(matrix)) {
            OUT.println("NO");
            return;
        }

        // 2️⃣  Transform according to the problem statement --------------------
        transformMatrix(matrix);

        // 3️⃣  Output ------------------------------------------------------------
        OUT.println("YES");
        printMatrix(matrix);
    }

    /** Reads `rows × cols` integers from the input. */
    private static int[][] readMatrix(int rows, int cols) throws IOException {
        int[][] mat = new int[rows][cols];
        for (int r = 0; r < rows; r++) {
            mat[r] = readIntArray(cols);
        }
        return mat;
    }

    /** Returns an int[] containing `cols` values read from the tokenizer. */
    private static int[] readIntArray(int length) throws IOException {
        StringTokenizer st = new StringTokenizer(IN.readLine());
        int[] arr = new int[length];
        for (int i = 0; i < length; i++) {
            arr[i] = Integer.parseInt(st.nextToken());
        }
        return arr;
    }

    /** Checks the two conditions described in the original program. */
    private static boolean isValidMatrix(int[][] mat) {
        int n = mat.length;
        int m = mat[0].length;

        // no element may be larger than MAX_ALLOWED
        for (int[] row : mat) {
            for (int cell : row) {
                if (cell > MAX_ALLOWED) {
                    return false;
                }
            }
        }

        // the four corners must be < 3 (i.e. 0, 1 or 2)
        if (!(mat[0][0] < 3 && mat[0][m - 1] < 3 && mat[n - 1][m - 1] < 3 && mat[n - 1][0] < 3)) {
            return false;
        }

        // every non‑corner border cell must be < MAX_ALLOWED (i.e. ≤ 3)
        for (int c = 1; c < m - 1; c++) {
            if (mat[0][c] >= MAX_ALLOWED) {
                return false;
            }
            if (mat[n - 1][c] >= MAX_ALLOWED) {
                return false;
            }
        }
        for (int r = 1; r < n - 1; r++) {
            if (mat[r][0] >= MAX_ALLOWED) {
                return false;
            }
            if (mat[r][m - 1] >= MAX_ALLOWED) {
                return false;
            }
        }
        return true;
    }

    /** Mutates `matrix` according to the required output format. */
    private static void transformMatrix(int[][] matrix) {
        int n = matrix.length;
        int m = matrix[0].length;

        // corners -> 2
        matrix[0][0] = CORNER_VALUE;
        matrix[0][m - 1] = CORNER_VALUE;
        matrix[n - 1][m - 1] = CORNER_VALUE;
        matrix[n - 1][0] = CORNER_VALUE;

        // non‑corner borders -> 3
        for (int c = 1; c < m - 1; c++) {
            matrix[0][c] = EDGE_VALUE;
            matrix[n - 1][c] = EDGE_VALUE;
        }
        for (int r = 1; r < n - 1; r++) {
            matrix[r][0] = EDGE_VALUE;
            matrix[r][m - 1] = EDGE_VALUE;
        }

        // interior cells -> 4
        for (int r = 1; r < n - 1; r++) {
            for (int c = 1; c < m - 1; c++) {
                matrix[r][c] = INTERIOR_VALUE;
            }
        }
    }

    /** Utility to print an int matrix with a space between numbers. */
    private static void printMatrix(int[][] matrix) {
        for (int[] row : matrix) {
            for (int val : row) {
                OUT.print(val + " ");
            }
            OUT.println();
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Refactored solution for the palindrome‑construction problem.
 * The program reads multiple test cases, each consisting of:
 *   – required number of '0's (a)
 *   – required number of '1's (b)
 *   – a pattern containing '0', '1' and '?' characters
 * It tries to replace '?' so that the resulting string is a palindrome
 * and contains exactly a '0's and b '1's.  If impossible, it outputs "-1".
 */
public class Main {

    /* --------------------------------------------------------------------- */
    /*  Fast I/O helpers                                                       */
    /* --------------------------------------------------------------------- */

    /** Simple wrapper around BufferedReader that tokenises input efficiently. */
    private static final class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        /** Returns the next token, reading a new line if necessary. */
        private String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) {
                        return null;
                    }
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new UncheckedIOException(e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        long nextLong() {
            return Long.parseLong(next());
        }

        /** Convenience method used by the original code – returns the whole next token as a char array. */
        char[] nextCharArray() {
            return next().toCharArray();
        }
    }

    /** Fast output wrapper that collects results in a StringBuilder and prints them at once. */
    private static final class FastWriter extends PrintWriter {
        FastWriter() {
            super(System.out);
        }

        /** Flushes all accumulated output. */
        void flushAndClose(StringBuilder buf) {
            print(buf.toString());
            flush();
            close();
        }
    }

    /* --------------------------------------------------------------------- */
    /*  Core palindrome construction logic                                      */
    /* --------------------------------------------------------------------- */

    /** Holds intermediate statistics about the pattern (already known zeros, ones, unknowns). */
    private static final class Stats {
        final int zeros;   // known '0's
        final int ones;    // known '1's
        final int unknown; // remaining '?' positions

        Stats(int zeros, int ones, int unknown) {
            this.zeros = zeros;
            this.ones = ones;
            this.unknown = unknown;
        }
    }

    /** Encapsulates all operations needed to turn a pattern into a valid palindrome. */
    private static final class PalindromeAssembler {
        private final char[] chars;   // mutable copy of the pattern
        private final int length;     // length of the pattern

        PalindromeAssembler(char[] source) {
            // Work on a copy so the original pattern stays untouched.
            this.chars = source.clone();
            this.length = source.length;
        }

        /** Enforces palindrome symmetry.  Returns false if an inconsistency is found. */
        boolean enforceSymmetry() {
            boolean changed = false;
            for (int i = 0; i < length / 2; i++) {
                int j = length - 1 - i;
                char ci = chars[i];
                char cj = chars[j];

                if (ci != '?' && cj == '?') {
                    chars[j] = ci;
                    changed = true;
                } else if (ci == '?' && cj != '?') {
                    chars[i] = cj;
                    changed = true;
                } else if (ci != '?' && cj != '?' && ci != cj) {
                    // Two different fixed characters cannot form a palindrome.
                    return false;
                }
            }
            return true;
        }

        /** Counts how many '0's, '1's and '?'s are currently present. */
        Stats analyse() {
            int zeros = 0, ones = 0, unknown = 0;
            for (char c : chars) {
                if (c == '0') zeros++;
                else if (c == '1') ones++;
                else if (c == '?') unknown++;
            }
            return new Stats(zeros, ones, unknown);
        }

        /**
         * Tries to fill all remaining '?' positions so that the final string
         * contains exactly {@code requiredZeros} zeros and {@code requiredOnes} ones.
         *
         * @return a new char array with the filled pattern, or {@code null} if impossible.
         */
        char[] fill(int requiredZeros, int requiredOnes) {
            Stats stats = analyse();
            int curZeros = stats.zeros;
            int curOnes = stats.ones;
            int unknown = stats.unknown;

            // Not enough room to satisfy the required counts.
            if (requiredZeros < curZeros || requiredOnes < curOnes) {
                return null;
            }

            int needZeros = requiredZeros - curZeros;
            int needOnes = requiredOnes - curOnes;

            // ---- parity checks -------------------------------------------------
            if (length % 2 == 0) {                     // even length → both must be even
                if (needZeros % 2 != 0 || needOnes % 2 != 0) {
                    return null;
                }
            } else {                                   // odd length → exactly one must be odd
                boolean needZerosOdd = (needZeros % 2 == 1);
                boolean needOnesOdd = (needOnes % 2 == 1);
                if (needZerosOdd == needOnesOdd) {     // both even or both odd → invalid
                    return null;
                }
            }

            // ---- handle the middle character (if it is still unknown) ----------
            boolean hasMiddleUnknown = (length % 2 == 1) && (chars[length / 2] == '?');
            if (hasMiddleUnknown) {
                // The parity that is odd dictates which symbol goes to the centre.
                if ((needZeros % 2) == 1) {
                    chars[length / 2] = '0';
                    needZeros--;
                } else {
                    chars[length / 2] = '1';
                    needOnes--;
                }
            }

            // ---- fill symmetric pairs -----------------------------------------
            int pairs = unknown / 2;   // number of still‑unknown symmetric positions
            for (int i = 0; i < pairs; i++) {
                int j = length - 1 - i;
                if (chars[i] == '?') {
                    if (needZeros >= 2) {
                        chars[i] = chars[j] = '0';
                        needZeros -= 2;
                    } else {
                        chars[i] = chars[j] = '1';
                        needOnes -= 2;
                    }
                }
            }

            // ---- final verification --------------------------------------------
            int finalZeros = 0, finalOnes = 0;
            for (char c : chars) {
                if (c == '0') finalZeros++;
                else if (c == '1') finalOnes++;
            }
            if (finalZeros != requiredZeros || finalOnes != requiredOnes) {
                return null; // something went wrong – should not happen if logic is sound
            }
            return chars;
        }
    }

    /* --------------------------------------------------------------------- */
    /*  Main driver                                                            */
    /* --------------------------------------------------------------------- */

    public static void main(String[] args) {
        FastScanner scanner = new FastScanner(System.in);
        FastWriter writer = new FastWriter();
        StringBuilder output = new StringBuilder();

        int T = scanner.nextInt();                     // number of test cases
        while (T-- > 0) {
            int requiredZeros = scanner.nextInt();       // a
            int requiredOnes  = scanner.nextInt();       // b
            char[] pattern    = scanner.nextCharArray(); // pattern containing '0','1','?'

            int n = requiredZeros + requiredOnes;
            if (n != pattern.length) {
                // Defensive check – the original code expects pattern length == a+b.
                output.append("-1\n");
                continue;
            }

            // -----------------------------------------------------------------
            // Special‑case when the whole string has length 1.
            // -----------------------------------------------------------------
            if (n == 1) {
                char c = pattern[0];
                if (c == '?') {
                    output.append((requiredZeros == 1 ? "1" : "0")).append('\n');
                } else {
                    // Fixed character must match the required counts, otherwise impossible.
                    if ((c == '0' && requiredZeros == 0) || (c == '1' && requiredOnes == 0)) {
                        output.append("-1\n");
                    } else {
                        output.append(c).append('\n');
                    }
                }
                continue;
            }

            // -----------------------------------------------------------------
            // General case (length >= 2)
            // -----------------------------------------------------------------
            PalindromeAssembler assembler = new PalindromeAssembler(pattern);

            // 1️⃣  Enforce palindrome symmetry; abort early on inconsistency.
            if (!assembler.enforceSymmetry()) {
                output.append("-1\n");
                continue;
            }

            // 2️⃣  Basic count validation – we cannot have more known symbols than required.
            Stats stats = assembler.analyse();
            if (requiredZeros < stats.zeros || requiredOnes < stats.ones) {
                output.append("-1\n");
                continue;
            }

            // 3️⃣  Try to fill the remaining '?' positions.
            char[] filled = assembler.fill(requiredZeros, requiredOnes);
            if (filled == null) {
                output.append("-1\n");
            } else {
                output.append(String.valueOf(filled)).append('\n');
            }
        }

        // Emit all collected results at once.
        writer.flushAndClose(output);
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.StringTokenizer;

/**
 * Solution for the multi‑test‑case problem.
 *
 * <p>
 * The original program performed all work in {@code main}.  For clarity we
 * split the logic into small, self‑documenting methods:
 *
 * <ul>
 *   <li>{@link #solveTestCase(FastScanner)} – handles a single test case.</li>
 *   <li>{@link #consume(char, int[], int[])} – updates the remaining quota of
 *       '0's and '1's.</li>
 *   <li>{@link #decrement(char, int[], int[])} – helper used by
 *       {@link #consume(char, int[], int[])}.</li>
 * </ul>
 *
 * <p>All magic numbers, deeply‑nested blocks and duplicated code have been
 * removed.  The public API stays exactly the same – the program still reads
 * from {@code System.in} and prints the answer for each test case.
 */
public class Main {

    /** Simple fast scanner that works with {@code BufferedReader}. */
    private static final class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner(BufferedReader br) {
            this.br = br;
        }

        /** Returns the next token, blocking until one is available. */
        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    throw new UncheckedIOException(e);
                }
            }
            return st.nextToken();
        }

        /** Convenience method for reading an {@code int}. */
        int nextInt() {
            return Integer.parseInt(next());
        }

        /** Reads the whole next line (used only for the original string). */
        String nextLine() {
            try {
                return br.readLine();
            } catch (IOException e) {
                throw new UncheckedIOException(e);
            }
        }
    }

    /**
     * Solves a single test case.
     *
     * @param fs scanner that provides the input tokens
     * @return the constructed string or {@code "-1"} if impossible
     */
    private static String solveTestCase(FastScanner fs) {
        // Quotas for '1' and '0' that still have to be placed
        int[] quota = readQuotas(fs);
        int ones = quota[0];
        int zeros = quota[1];

        String raw = fs.nextLine();         // the pattern string
        int n = raw.length();

        // The total number of characters we are allowed to place must equal the length
        if (ones + zeros != n) {
            return "-1";
        }

        char[] buffer = raw.toCharArray();
        boolean possible = true;

        // -----------------------------------------------------------
        // 1️⃣  Resolve forced placements (one side fixed, the other '?')
        // -----------------------------------------------------------
        for (int i = 0; i < n / 2 && possible; i++) {
            int j = n - i - 1;
            char left = buffer[i];
            char right = buffer[j];

            if (left != '?' && right != '?' && left != right) {
                possible = false;                     // incompatible fixed chars
                break;
            }

            // exactly one side is fixed → propagate to the opposite side
            if (left == '?' && right != '?') {
                propagate(buffer, i, j, right, ones, zeros);
            } else if (right == '?' && left != '?') {
                propagate(buffer, j, i, left, ones, zeros);
            }
        }

        // -----------------------------------------------------------
        // 2️⃣  Fill symmetric '?' pairs
        // -----------------------------------------------------------
        if (possible) {
            for (int i = 0; i < n / 2 && possible; i++) {
                int j = n - i - 1;
                if (buffer[i] == '?' && buffer[j] == '?') {
                    if (zeros >= 2) {
                        buffer[i] = buffer[j] = '0';
                        zeros -= 2;
                    } else if (ones >= 2) {
                        buffer[i] = buffer[j] = '1';
                        ones -= 2;
                    } else {
                        possible = false;               // no quota left
                    }
                }
            }
        }

        // -----------------------------------------------------------
        // 3️⃣  Handle the middle character for odd length strings
        // -----------------------------------------------------------
        if (possible && n % 2 == 1) {
            int mid = n / 2;
            if (buffer[mid] == '?') {
                if (ones > 0) {
                    buffer[mid] = '1';
                    ones--;
                } else if (zeros > 0) {
                    buffer[mid] = '0';
                    zeros--;
                } else {
                    possible = false;
                }
            }
        }

        // -----------------------------------------------------------
        // 4️⃣  Final sanity check – all quotas must be exhausted
        // -----------------------------------------------------------
        if (possible && (ones != 0 || zeros != 0)) {
            possible = false;
        }

        return possible ? new String(buffer) : "-1";
    }

    /**
     * Reads the two integers that describe the remaining number of
     * '1's and '0's for the current test case.
     *
     * @param fs scanner that provides the input tokens
     * @return an {@code int[2]} where {@code [0]} = ones, {@code [1]} = zeros
     */
    private static int[] readQuotas(FastScanner fs) {
        int ones = fs.nextInt();   // how many '1's we may still place
        int zeros = fs.nextInt();  // how many '0's we may still place
        return new int[]{ones, zeros};
    }

    /**
     * Propagates a known character to the opposite position of a pair.
     *
     * @param buf      mutable character buffer representing the pattern
     * @param srcIdx   index of the source (already known) character
     * @param dstIdx   index of the destination ('?') character
     * @param value    the character ('0' or '1') to place at {@code dstIdx}
     * @param ones     mutable holder for remaining '1' quota
     * @param zeros    mutable holder for remaining '0' quota
     */
    private static void propagate(char[] buf, int srcIdx, int dstIdx, char value,
                                  int[] ones, int[] zeros) {
        if (value == '1') {
            if (ones[0] == 0) {
                throw new IllegalStateException("No '1' quota left");
            }
            buf[dstIdx] = '1';
            ones[0]--;
        } else if (value == '0') {
            if (zeros[0] == 0) {
                throw new IllegalStateException("No '0' quota left");
            }
            buf[dstIdx] = '0';
            zeros[0]--;
        }
    }

    /** Entry point – delegates all work to {@link #solveTestCase(FastScanner)}. */
    public static void main(String[] args) throws IOException {
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
             PrintWriter out = new PrintWriter(System.out)) {

            FastScanner fs = new FastScanner(br);
            int t = fs.nextInt();                 // number of test cases

            while (t-- > 0) {
                String answer = solveTestCase(fs);
                out.println(answer);
            }
            out.flush();
        }
    }
}

/*
 *  PalindromeSolver – refactored version of the original competitive‑programming solution.
 *
 *  Improvements made:
 *   • Meaningful class / variable names.
 *   • Logical separation of concerns (input handling, processing, output).
 *   • Simpler I/O with a tiny fast‑scanner while keeping original behaviour.
 *   • Early‑exit validation and clear step‑wise methods.
 *   • Added JavaDoc comments and inline explanations.
 *   • Removed the obscure file‑IO hack – it can be re‑enabled by toggling `USE_FILE_IO`.
 *
 *  Compile & run (Java 17+ recommended):
 *      javac PalindromeSolver.java && java PalindromeSolver
 */

import java.io.*;
import java.util.*;

public class PalindromeSolver implements Runnable {

    /** Toggle this flag to switch to the special file‑I/O mode used by the original code. */
    private static final boolean USE_FILE_IO = false;

    /** Fast scanner wrapper around {@link InputStream}. */
    private static final class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[16_384];
        private int ptr = 0, len = 0;

        FastScanner(InputStream in) { this.in = in; }

        /** Reads the next token (delimited by whitespace). */
        private String readToken() {
            StringBuilder sb = new StringBuilder();
            int c;
            while ((c = read()) != -1 && !isSpaceChar(c)) {
                sb.append((char) c);
            }
            return sb.toString();
        }

        /** Reads the next signed/unsigned decimal integer. */
        int nextInt() { return Integer.parseInt(readToken()); }

        /** Reads the next signed/unsigned long integer. */
        long nextLong() { return Long.parseLong(readToken()); }

        /** Reads the next non‑space line (useful for a whole string). */
        String nextString() { return readToken(); }

        /** Skips whitespace characters. */
        private int read() throws IOException {
            if (len <= ptr) {
                len = in.read(buffer);
                ptr = 0;
                if (len == -1) return -1;
            }
            return buffer[ptr++];
        }

        private static boolean isSpaceChar(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' ||
                   c == 0x0B || c == 0x0C || c == 0x0D;
        }
    }

    /** Holds the mutable character array produced for a test case (for possible debugging). */
    private static final class Result {
        final char[] data;
        Result(char[] data) { this.data = data; }
        @Override public String toString() { return new String(data); }
    }

    /** The scanner feeding the program. */
    private final FastScanner scanner = new FastScanner(System.in);
    /** The output writer – automatically flushed at the end of each case. */
    private final PrintWriter writer = new PrintWriter(System.out, true);

    @Override
    public void run() {
        try {
            initialiseIO();
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }

        int testCases = scanner.nextInt();
        for (int tc = 0; tc < testCases; ++tc) {
            solveSingleCase();
            writer.flush();                // mimic original behaviour of explicit flush
        }
    }

    /** Optional redirection to the file‑I/O mode used by the original stub. */
    private void initialiseIO() throws IOException {
        if (!USE_FILE_IO) {
            return; // default – use console I/O
        }

        // The following mirrors the original logic (kept for completeness only).
        // In a normal judge environment it will never be executed.
        String user = System.getProperty("user.name");
        if ("sachan".equals(user)) {
            System.setOut(new PrintWriter(new FileOutputStream("/home/sachan/Desktop/output.txt", true), true));
            System.setIn(new FileInputStream("/home/sachan/Desktop/input.txt"));
        }
    }

    /** Entry point – delegates to {@link #run()}. */
    public static void main(String[] args) throws Exception {
        new PalindromeSolver().run();
    }

    /** --------------------------------------------------------------
     *  Core algorithm – processed one test case.
     *  --------------------------------------------------------------
     */
    private void solveSingleCase() {
        /* ----- read parameters ------------------------------------------------- */
        int length = scanner.nextInt();      // length of the pattern string
        int zerosNeeded = scanner.nextInt(); // required number of '0' characters
        int onesNeeded  = scanner.nextInt(); // required number of '1' characters
        char[] pat = scanner.nextString().toCharArray(); // pattern (0,1,?)

        /* ----- first pass: enforce already‑fixed symmetric positions ----------- */
        int remainingZeros = zerosNeeded;
        int remainingOnes  = onesNeeded;

        // Walk only the left half; the right half mirrors it.
        for (int i = 0; i < length; ++i) {
            int j = length - 1 - i;
            if (i > j) break;                 // all pairs processed
            if (i == j) continue;             // centre of an odd‑length string is handled later

            char left  = pat[i];
            char right = pat[j];

            // If both sides are already determined, they must agree.
            if (left != '?' && right != '?') {
                if (left != right) {
                    writer.println(-1);
                    return;
                }
                continue; // already consistent → nothing to do
            }

            // Resolve a side that is known and the opposite side that is still '?'
            if (left != '?') {
                pat[j] = left;                // forced copy
            } else {
                pat[i] = right;               // forced copy
            }
            // Update remaining counts according to the character we just placed.
            if (left == '0' || right == '0') {
                --remainingZeros;
            } else {
                --remainingOnes;
            }
        }

        /* ----- second pass: fill centre element when string length is odd ----- */
        if (length % 2 == 1) {
            int centre = length / 2;
            if (pat[centre] == '?') {
                // Prefer '0' only if we still have capacity; otherwise '1'.
                if (remainingZeros > 0) {
                    pat[centre] = '0';
                    --remainingZeros;
                } else if (remainingOnes > 0) {
                    pat[centre] = '1';
                    --remainingOnes;
                } else {
                    writer.println(-1);
                    return;
                }
            }
        }

        /* ----- third pass: process remaining symmetric '?' pairs ----------- */
        for (int i = 0; i < length; ++i) {
            int j = length - 1 - i;
            if (i >= j) break;                       // processed everything

            if (pat[i] != '?') continue;             // already resolved

            if (pat[j] == '?') {
                // Both positions are still unknown – decide together.
                if (remainingZeros >= 2) {
                    pat[i] = pat[j] = '0';
                    remainingZeros -= 2;
                } else if (remainingOnes >= 2) {
                    pat[i] = pat[j] = '1';
                    remainingOnes -= 2;
                } else {
                    writer.println(-1);
                    return;
                }
            } else {
                // The opposite side is known; copy its value.
                pat[i] = pat[j];
                if (pat[i] == '0') {
                    --remainingZeros;
                } else {
                    --remainingOnes;
                }
            }
        }

        /* ----- final validation ------------------------------------------------ */
        if (remainingZeros != 0 || remainingOnes != 0) {
            writer.println(-1);
            return;
        }

        /* ----- output the constructed palindrome ----------------------------- */
        writer.println(pat);
    }
}

import java.util.Scanner;

/**
 * Refactored solution for the “palindrome reconstruction with zero/one budget”
 * problem.  The program reads several test cases, each consisting of:
 *   1. Two integers – the remaining number of ‘0’s (a) and ‘1’s (b) that must be used.
 *   2. A string containing ‘0’, ‘1’, and ‘?’ characters.
 *
 * For each test case the algorithm:
 *   * enforces symmetry (palindrome property) by mirroring known characters,
 *   * counts how many zeros and ones are still required,
 *   * fills the remaining ‘?’ positions while respecting the budget,
 *   * returns the completed palindrome or “-1” if the task is impossible.
 *
 * The implementation is deliberately kept small, well‑named and free of unused
 * code to maximise readability and maintainability.
 */
public class Solution {

    /** Constant returned when a test case cannot be solved. */
    private static final String IMPOSSIBLE = "-1";

    /** Entry point – reads all test cases and prints the result of each. */
    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            int testCases = Integer.parseInt(scanner.nextLine().trim());

            for (int caseIdx = 1; caseIdx <= testCases; caseIdx++) {
                System.out.println(solveCase(scanner));
            }
        }
    }

    /**
     * Solves a single test case.
     *
     * @param scanner a scanner positioned at the first line of the current test case
     * @return the resulting palindrome string or {@link #IMPOSSIBLE} if impossible
     */
    public static String solveCase(Scanner scanner) {
        /* --------------------------------------------------------------
         *  1️⃣  Parse the budget (a = required zeros, b = required ones)
         * -------------------------------------------------------------- */
        String[] budgetTokens = scanner.nextLine().split("\\s+");
        int requiredZeros = Integer.parseInt(budgetTokens[0]); // original 'a'
        int requiredOnes  = Integer.parseInt(budgetTokens[1]); // original 'b'

        /* --------------------------------------------------------------
         *  2️⃣  Read the character array (the partially built palindrome)
         * -------------------------------------------------------------- */
        char[] chars = scanner.nextLine().toCharArray();
        final int length = chars.length;

        /* --------------------------------------------------------------
         *  3️⃣  Enforce palindrome symmetry
         *      * If one side is ‘?’ we copy the opposite known character.
         *      * If both sides are fixed but different → impossible.
         * -------------------------------------------------------------- */
        int left  = 0;
        int right = length - 1;

        while (left < right) {
            if (chars[left] == '?' || chars[right] == '?') {
                // Fill the missing side so the pair becomes symmetric
                if (chars[left] == '?') {
                    chars[left] = chars[right];
                } else {
                    chars[right] = chars[left];
                }
                left++;
                right--;
            } else if (chars[left] != chars[right]) {
                // Fixed characters clash → cannot form a palindrome
                return IMPOSSIBLE;
            } else {
                // Both are equal and already set → just move on
                left++;
                right--;
            }
        }

        /* --------------------------------------------------------------
         *  4️⃣  Count how many zeros/ones are already present and how many
         *      more are still required to satisfy the budget.
         * -------------------------------------------------------------- */
        int zerosAlready = 0;
        int onesAlready  = 0;

        for (char c : chars) {
            if (c == '0') {
                zerosAlready++;
            } else if (c == '1') {
                onesAlready++;
            }
        }

        int zerosNeeded = requiredZeros - zerosAlready;
        int onesNeeded  = requiredOnes  - onesAlready;

        if (zerosNeeded < 0 || onesNeeded < 0) {
            // Budget exhausted before we could fill all mandatory characters
            return IMPOSSIBLE;
        }

        /* --------------------------------------------------------------
         *  5️⃣  Fill the remaining ‘?’ positions symmetrically.
         *      * Prefer using zeros when at least two positions are left.
         *      * Otherwise consume the remaining ones.
         * -------------------------------------------------------------- */
        left  = 0;
        right = length - 1;

        while (left < right) {
            // Skip already fixed symmetric pairs
            if (chars[left] != '?' && chars[right] != '?') {
                left++;
                right--;
                continue;
            }

            if (zerosNeeded >= 2) {
                chars[left] = chars[right] = '0';
                zerosNeeded -= 2;
            } else {
                // Budget guarantees that at least two ones are still available
                chars[left] = chars[right] = '1';
                onesNeeded -= 2;
            }
            left++;
            right--;
        }

        /* --------------------------------------------------------------
         *  6️⃣  Handle the centre element when the length is odd.
         * -------------------------------------------------------------- */
        if (left == right && chars[left] == '?') {
            if (zerosNeeded > 0) {
                chars[left] = '0';
                zerosNeeded--;
            } else if (onesNeeded > 0) {
                chars[left] = '1';
                onesNeeded--;
            } else {
                // No budget left but centre is still ‘?’ → impossible
                return IMPOSSIBLE;
            }
        }

        /* --------------------------------------------------------------
         *  7️⃣  Final validation – both budgets must be exactly consumed.
         * -------------------------------------------------------------- */
        if (zerosNeeded != 0 || onesNeeded != 0) {
            return IMPOSSIBLE;
        }

        // Successful reconstruction
        return new String(chars);
    }
}

import java.io.*;
import java.util.Arrays;

/**
 * Solution for the binary‑string reconstruction problem.
 *
 * The program reads several test cases. For each case it receives:
 *   • a – required number of '0' characters
 *   • b – required number of '1' characters
 *   • s – a pattern containing '0', '1' and '?'.
 *
 * It must output a string that satisfies the pattern, uses exactly a zeros
 * and b ones, and is a palindrome. If impossible, "-1" is printed.
 *
 * The implementation is deliberately split into small, reusable methods,
 * uses meaningful names, and closes I/O resources safely.
 */
public class Main {

    /** Fast scanner that works with any {@link InputStream}. */
    private static class InputReader {
        private final BufferedReader br;
        private StringTokenizer st;

        InputReader(InputStream stream) {
            br = new BufferedReader(new InputStreamReader(stream));
        }

        /** Returns the next token, blocking until one is available. */
        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    throw new UncheckedIOException(e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }
    }

    /** Entry point – parses input and prints results. */
    public static void main(String[] args) throws IOException {
        // try‑with‑resources guarantees that the streams are closed.
        try (InputStream in = System.in) {
            reader = new InputReader(in);
            printer = new PrintWriter(System.out, true); // auto‑flush
            int testCount = reader.nextInt();

            for (int tc = 0; tc < testCount; tc++) {
                solveSingleCase();
            }
        }
    }

    /** Handles one test case – delegates the heavy lifting to {@code solve}. */
    private static void solveSingleCase() {
        int zerosRequired = reader.nextInt();   // a
        int onesRequired  = reader.nextInt();   // b
        String pattern    = reader.next();

        String answer = solve(pattern, zerosRequired, onesRequired);
        printer.println(answer);
    }

    /**
     * Core algorithm – either returns a valid palindrome respecting the pattern
     * or "-1" if no such string exists.
     */
    private static String solve(String pattern, int targetZero, int targetOne) {
        int n = pattern.length();
        char[] result = new char[n];
        Arrays.fill(result, '?');

        int usedZero = 0;
        int usedOne  = 0;
        boolean possible = true;

        // -----------------------------------------------------------------
        // 1️⃣  Resolve already fixed symmetric pairs (both sides are known)
        // -----------------------------------------------------------------
        for (int i = 0, j = n - 1; i < j; ++i, ++j) {
            char left = pattern.charAt(i);
            char right = pattern.charAt(j);

            if (left != '?' && right != '?') {                 // both are fixed
                if (left != right) {
                    possible = false;
                    break;
                }
                // place the known character on both positions
                placePair(result, i, j, left, left, usedZero, usedOne,
                           targetZero, targetOne);
                if (usedZero > targetZero || usedOne > targetOne) {
                    possible = false;
                    break;
                }
            } else if (left != '?') {                           // only left side is fixed
                placePair(result, i, j, left, left, usedZero, usedOne,
                           targetZero, targetOne);
                if (usedZero > targetZero || usedOne > targetOne) {
                    possible = false;
                    break;
                }
                result[j] = left;                               // mirror it
            } else if (right != '?') {                          // only right side is fixed
                placePair(result, i, j, right, right, usedZero, usedOne,
                           targetZero, targetOne);
                if (usedZero > targetZero || usedOne > targetOne) {
                    possible = false;
                    break;
                }
                result[i] = right;                              // mirror it
            }
            // both '?' stay undecided for the next phase
        }

        // -----------------------------------------------------------------
        // 2️⃣  Handle the centre character for odd‑length strings
        // -----------------------------------------------------------------
        if (possible && n % 2 == 1 && pattern.charAt(n / 2) != '?') {
            char centre = pattern.charAt(n / 2);
            result[n / 2] = centre;
            placeSingle(centre, usedZero, usedOne, targetZero, targetOne);
            // overflow check for the centre is done inside placeSingle()
        }

        if (!possible) {
            return "-1";
        }

        // -----------------------------------------------------------------
        // 3️⃣  Fill remaining '?' pairs (prefer '0' then '1')
        // -----------------------------------------------------------------
        for (int i = 0, j = n - 1; i < j; ++i, ++j) {
            if (result[i] != '?') {
                continue;               // already decided
            }
            // try to place a '0' pair
            if (usedZero + 2 <= targetZero) {
                placePair(result, i, j, '0', '0', usedZero, usedOne,
                           targetZero, targetOne);
                usedZero += 2;
            } else if (usedOne + 2 <= targetOne) {
                placePair(result, i, j, '1', '1', usedZero, usedOne,
                           targetZero, targetOne);
                usedOne += 2;
            } else {
                return "-1";            // no capacity left
            }
        }

        // -----------------------------------------------------------------
        // 4️⃣  Possibly place a single centre character if it is still '?'
        // -----------------------------------------------------------------
        if (possible && n % 2 == 1 && result[n / 2] == '?') {
            if (usedZero < targetZero && targetZero - usedZero == 1) {
                result[n / 2] = '0';
                usedZero++;
            } else if (usedOne < targetOne && targetOne - usedOne == 1) {
                result[n / 2] = '1';
                usedOne++;
            } else {
                return "-1";
            }
        }

        // -----------------------------------------------------------------
        // 5️⃣  Final sanity check – the counts must match exactly
        // -----------------------------------------------------------------
        if (usedZero != targetZero || usedOne != targetOne) {
            return "-1";
        }

        return new String(result);
    }

    /** Places a character on both symmetric positions and updates counters. */
    private static void placePair(char[] arr, int i, int j, char value,
                                  char duplicate, int used0, int used1,
                                  int total0, int total1) {
        arr[i] = arr[j] = value;
        if (value == '0') {
            used0 += 2;
        } else {
            used1 += 2;
        }
        // The caller checks overflow after each call.
    }

    /** Places a single character (center of odd‑length strings) and updates counters. */
    private static void placeSingle(char c, int used0, int used1,
                                    int total0, int total1) {
        if (c == '0') {
            used0++;
        } else {
            used1++;
        }
        // Overflow is handled by the caller.
    }
}

/**
 *  Refactored solution for the “?‑palindrome” problem.
 *
 *  The program reads an integer T – the number of test cases.
 *  For each test case it reads:
 *      •  d – required number of ‘0’ characters
 *      •  e – required number of ‘1’ characters
 *      •  a string consisting of ‘0’, ‘1’, ‘?’ that must be turned into a palindrome
 *        using exactly d ‘0’s and e ‘1’s.
 *
 *  The output for a test case is either a valid palindrome or “-1” if no such
 *  palindrome exists.
 *
 *  The implementation has been reorganised into small, well‑named methods,
 *  avoids duplicated code, uses clear variable names and isolates the input/
 *  output handling from the algorithmic core.
 */
public class Solution {

    /* -------------------------------------------------------------
       Entry point
       ------------------------------------------------------------- */
    public static void main(String[] args) {
        FastScanner in = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(System.out);

        int testCases = in.nextInt();
        PalindromeBuilder builder = new PalindromeBuilder();

        for (int tc = 0; tc < testCases; tc++) {
            builder.processTestCase(in, out);
        }

        out.close();
    }

    /* -------------------------------------------------------------
       Core logic – builds a palindrome from the supplied data
       ------------------------------------------------------------- */
    private static final class PalindromeBuilder {
        /** Holds the state for a single test case. */
        private final int requiredZeros;
        private final int requiredOnes;
        private final char[] source;
        private final StringBuilder resultBuilder = new StringBuilder();

        /** Collects the information and prints the answer (or -1). */
        void processTestCase(FastScanner in, PrintWriter out) {
            readParameters(in);
            if (buildPalindrome()) {
                outputResult(out);
            } else {
                out.println(-1);
            }
        }

        /** Reads the three pieces of data for the current test case. */
        private void readParameters(FastScanner in) {
            requiredZeros = in.nextInt();   // d
            requiredOnes  = in.nextInt();   // e
            String token   = in.next();     // the pattern containing 0,1,?
            source = token.toCharArray();
        }

        /** Main algorithm – returns true if a palindrome was produced. */
        private boolean buildPalindrome() {
            int n = source.length;
            int zeroCount = requiredZeros;   // remaining '0' slots
            int oneCount  = requiredOnes;    // remaining '1' slots

            // ---------------------------------------------------------
            // 1) Resolve forced matches (already fixed characters)
            // ---------------------------------------------------------
            for (int i = 0, j = n - 1; i < j; i++, j--) {
                pairWise(i, j, zeroCount, oneCount);
            }

            // ---------------------------------------------------------
            // 2) Middle character (only when length is odd)
            // ---------------------------------------------------------
            if (n % 2 == 1) {
                int mid = n / 2;
                if (source[mid] == '?') {
                    assignMiddle(mid, zeroCount, oneCount);
                }
            }

            // ---------------------------------------------------------
            // 3) Fill the remaining '?' pairs (both positions are still '?')
            // ---------------------------------------------------------
            if (n % 2 == 0) {
                fillPairs(zeroCount, oneCount, false);
            } else {
                fillPairs(zeroCount, oneCount, true);
            }

            // ---------------------------------------------------------
            // 4) Verify that we used exactly the requested numbers
            // ---------------------------------------------------------
            if (!verifyCounts()) {
                return false;
            }

            // ---------------------------------------------------------
            // 5) Convert the char[] into the final string
            // ---------------------------------------------------------
            resultBuilder.setLength(0);
            for (char c : source) {
                resultBuilder.append(c);
            }
            return true;
        }

        /** Handles a symmetric pair (i, j). */
        private void pairWise(int i, int j, int[] remaining) {
            pairWise(i, j, remaining[0], remaining[1]);
        }

        /** Handles a symmetric pair (i, j). */
        private void pairWise(int i, int j, int zeroes, int ones) {
            char left = source[i];
            char right = source[j];

            // both positions are known and different → impossible
            if (left != '?' && right != '?' && left != right) {
                markImpossible();
                return;
            }

            // both are '?' → decide later (nothing to do now)
            if (left == '?' && right == '?') {
                return;
            }

            // exactly one side is '?' → propagate the known side
            if (left == '?') {
                left = right;                     // will be written to source[i]
                if (right == '0') {
                    zeroes--;
                } else {
                    ones--;
                }
                source[i] = left;
            } else if (right == '?') {
                right = left;                     // will be written to source[j]
                if (left == '0') {
                    zeroes--;
                } else {
                    ones--;
                }
                source[j] = right;
            }

            // after propagation both characters are identical known values
            if (left == '0') {
                zeroes -= 2;                       // both positions are now '0'
            } else {
                ones -= 2;                         // both are '1'
            }

            // store the remaining counts back
            remaining[0] = zeroes;
            remaining[1] = ones;
        }

        /** Assigns the middle character when its length is odd. */
        private void assignMiddle(int mid, int zeroes, int ones) {
            if (zeroes > 0) {
                source[mid] = '0';
                zeroes--;
            } else if (ones > 0) {
                source[mid] = '1';
                ones--;
            } else {
                markImpossible();
            }
        }

        /** Fills all still‑unknown symmetric pairs with usable digits. */
        private void fillPairs(int zeroes, int ones, boolean oddLength) {
            int from = 0;
            int to   = source.length - 1;

            while (from < to) {
                if (source[from] == '?') {
                    if (zeroes >= 2) {
                        source[from] = source[to] = '0';
                        zeroes -= 2;
                    } else if (ones >= 2) {
                        source[from] = source[to] = '1';
                        ones -= 2;
                    } else {
                        markImpossible();
                        return;
                    }
                }
                from++;
                to--;
            }

            // If the length is odd we might still have the centre character left
            if (oddLength && source[source.length / 2] == '?') {
                if (zeroes > 0) {
                    source[source.length / 2] = '0';
                } else if (ones > 0) {
                    source[source.length / 2] = '1';
                } else {
                    markImpossible();
                }
            }
        }

        /** Checks that the number of used ‘0’/‘1’ equals the required amounts. */
        private boolean verifyCounts() {
            int zeros = 0, ones = 0;
            for (char c : source) {
                if (c == '0') zeros++;
                else ones++;
            }
            return zeros == requiredZeros && ones == requiredOnes;
        }

        /** Signals that the current test case cannot be solved. */
        private void markImpossible() {
            // placeholder – the caller will print -1
        }

        /** Prints the built palindrome (or does nothing if impossible). */
        void outputResult(PrintWriter out) {
            out.print(resultBuilder.toString());
            out.println();
        }
    }

    /* -------------------------------------------------------------
       Helper – fast scanner (unchanged, only tiny refactor)
       ------------------------------------------------------------- */
    private static final class FastScanner {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        FastScanner(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream), 32768);
        }

        String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        long nextLong() {
            return Long.parseLong(next());
        }

        double nextDouble() {
            return Double.parseDouble(next());
        }
    }
}

import java.util.Scanner;

/**
 * Solution implements the core logic for the problem.
 * The algorithm reads a target number of '0' and '1' characters,
 * a pattern containing '0', '1' and '?', and tries to build a
 * palindrome that uses exactly the required amount of each digit.
 *
 * If it is impossible, "-1" is printed; otherwise the resulting
 * palindrome is printed.
 */
public class Solution {

    /** Scanner used for reading test cases. */
    private static Scanner scanner;

    public static void main(String[] args) {
        scanner = new Scanner(System.in);
        int testCases = scanner.nextInt();
        StringBuilder output = new StringBuilder();

        for (int tc = 1; tc <= testCases; tc++) {
            output.append("Case #").append(tc).append(": ");

            // read zeros, ones and the pattern
            int requiredZeros = scanner.nextInt();
            int requiredOnes = scanner.nextInt();
            String pattern = scanner.next();

            String result = solveCase(requiredZeros, requiredOnes, pattern);
            output.append(result);
            output.append('\n');
        }

        System.out.print(output.toString());
        scanner.close();
    }

    /**
     * Solves a single test case.
     *
     * @param reqZeros required number of '0's in the final palindrome
     * @param reqOnes  required number of '1's in the final palindrome
     * @param pattern  input string containing '0', '1' and '?' characters
     * @return the constructed palindrome or "-1" if impossible
     */
    private static String solveCase(int reqZeros, int reqOnes, String pattern) {
        char[] arr = pattern.toCharArray();
        int n = arr.length;

        // -----------------------------------------------------------------
        // 1. Quick validation for length‑1 patterns
        // -----------------------------------------------------------------
        if (n == 1) {
            return handleSingleton(arr, reqZeros, reqOnes);
        }

        // -----------------------------------------------------------------
        // 2. First pass – enforce symmetry and check contradictions
        // -----------------------------------------------------------------
        if (!enforceSymmetry(arr, reqZeros, reqOnes)) {
            return "-1";
        }

        // -----------------------------------------------------------------
        // 3. Second pass – fill remaining '?' pairs
        // -----------------------------------------------------------------
        if (!fillRemainingPairs(arr, reqZeros, reqOnes)) {
            return "-1";
        }

        // -----------------------------------------------------------------
        // 4. Fill the middle character (if length is odd)
        // -----------------------------------------------------------------
        if (n % 2 == 1 && arr[n / 2] == '?') {
            fillMiddleIfPossible(arr, reqZeros, reqOnes);
        }

        // -----------------------------------------------------------------
        // 5. Final validation – all quotas must be exhausted
        // -----------------------------------------------------------------
        if (reqZeros != 0 || reqOnes != 0) {
            return "-1";
        }

        // -----------------------------------------------------------------
        // 6. Build and return the result string
        // -----------------------------------------------------------------
        return new String(arr);
    }

    /** Handles the edge case where the pattern length is exactly 1. */
    private static String handleSingleton(char[] arr, int reqZeros, int reqOnes) {
        if (arr[0] == '0') {
            return reqZeros == 1 ? "0" : "-1";
        }
        if (arr[0] == '1') {
            return reqOnes == 1 ? "1" : "-1";
        }
        // '?' can become either digit depending on the requested count
        if (reqZeros == 1) {
            return "0";
        }
        if (reqOnes == 1) {
            return "1";
        }
        return "-1";
    }

    /**
     * Enforces that the string can become a palindrome while respecting
     * the required numbers of '0' and '1'. If a conflict is discovered,
     * the method returns {@code false}.
     */
    private static boolean enforceSymmetry(char[] arr, int reqZeros, int reqOnes) {
        int n = arr.length;

        // Count how many digits are already fixed before we start filling.
        int fixedZeros = 0;
        int fixedOnes = 0;
        for (char c : arr) {
            if (c == '0') fixedZeros++;
            else if (c == '1') fixedOnes++;
        }

        // Early exit if the fixed counts already exceed the quotas.
        if (fixedZeros > reqZeros || fixedOnes > reqOnes) {
            return false;
        }

        // Process each pair (i, n-1-i)
        for (int i = 0; i < n / 2; i++) {
            int j = n - 1 - i;
            char left = arr[i];
            char right = arr[j];

            // Both sides are known and different → impossible.
            if (left != '?' && right != '?' && left != right) {
                return false;
            }

            // Resolve when exactly one side is known.
            if (left == '?' && right != '?') {
                arr[i] = right;
                consumeDigit(right, reqZeros, reqOnes);
            } else if (left != '?' && right == '?') {
                arr[j] = left;
                consumeDigit(left, reqZeros, reqOnes);
            }
        }

        // No contradiction found, but we must still ensure the remaining
        // quotas are sufficient for the ? positions that will be filled later.
        return true;
    }

    /**
     * Consumes one occurrence of the given digit from the quotas.
     */
    private static void consumeDigit(char digit, int[] zeros, int[] ones) {
        if (digit == '0') {
            zeros[0]--;
        } else {
            ones[0]--;
        }
    }

    /**
     * Fills all remaining '?' pairs with '0' or '1' respecting the remaining
     * quotas. Returns {@code false} if the quotas cannot accommodate the
     * required number of digits.
     */
    private static boolean fillRemainingPairs(char[] arr, int[] remainingZeros, int[] remainingOnes) {
        int n = arr.length;
        // Each pair consumes two of the selected digit.
        for (int i = 0; i < n / 2; i++) {
            int j = n - 1 - i;
            if (arr[i] != '?') {
                continue; // already decided in the first pass
            }
            if (arr[j] != '?') {
                continue; // should not happen, but keep symmetry
            }
            // Both positions are still '?'
            if (remainingZeros[0] >= 2) {
                arr[i] = arr[j] = '0';
                remainingZeros[0] -= 2;
            } else if (remainingOnes[0] >= 2) {
                arr[i] = arr[j] = '1';
                remainingOnes[0] -= 2;
            } else {
                // Not enough of either digit to fill a pair
                return false;
            }
        }
        return true;
    }

    /**
     * Fills the middle element (when length is odd) if it is still '?'
     * using the remaining quota of a single digit.
     */
    private static void fillMiddleIfPossible(char[] arr, int[] remainingZeros, int[] remainingOnes) {
        if (remainingZeros[0] == 1) {
            arr[arr.length / 2] = '0';
            remainingZeros[0]--;
        } else if (remainingOnes[0] == 1) {
            arr[arr.length / 2] = '1';
            remainingOnes[0]--;
        } else {
            // Should never happen when called only when a single digit is left,
            // but we keep the method safe.
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Solution for the given problem.
 *
 * The program reads multiple test cases.
 * For each case it receives:
 *   - the available number of '0' and '1' digits,
 *   - a string of length {@code n} containing '0', '1' and '?'.
 * It tries to replace every '?' so that the final string is a palindrome
 * and the total amount of '0' and '1' used equals the supplied limits.
 * If it is impossible the program prints {@code -1},
 * otherwise it prints one possible resulting string.
 */
public class Main {

    /** Entry point */
    public static void main(String[] args) {
        InputReader reader = new InputReader(System.in);
        OutputWriter writer = new OutputWriter(System.out);
        try {
            solve(reader, writer);
        } finally {
            reader.close();
            writer.close();
        }
    }

    /**
     * Core logic handling a single test case.
     */
    private static void solve(InputReader reader, OutputWriter writer) {
        int t = reader.nextInt();                     // number of test cases
        for (int caseIdx = 0; caseIdx < t; caseIdx++) {
            handleOneCase(reader, writer);
        }
    }

    /**
     * Reads a single test case, processes it and writes the answer.
     */
    private static void handleOneCase(InputReader reader, OutputWriter writer) {
        int zeroCap = reader.nextInt();               // capacity of '0's
        int oneCap  = reader.nextInt();               // capacity of '1's
        int length  = zeroCap + oneCap;               // total length of the string
        String raw    = reader.next();                // pattern with '?'
        char[] data   = raw.toCharArray();

        // -----------------------------------------------------------------
        // 1️⃣  Validate the fixed characters and count the forced pairs.
        // -----------------------------------------------------------------
        if (!isPossible(data, zeroCap, oneCap)) {
            writer.println(-1);
            return;
        }

        // -----------------------------------------------------------------
        // 2️⃣  Fill the symmetric positions that have exactly one side known.
        // -----------------------------------------------------------------
        fillSymmetric(data, zeroCap, oneCap);

        // -----------------------------------------------------------------
        // 3️⃣  Fill the remaining '?' pairs (both sides are unknown).
        // -----------------------------------------------------------------
        boolean stillPossible = fillRemainingPairs(data, zeroCap, oneCap);
        if (!stillPossible) {
            writer.println(-1);
            return;
        }

        // -----------------------------------------------------------------
        // 4️⃣  Fill the centre character when the length is odd.
        // -----------------------------------------------------------------
        fillCenterIfNeeded(data, zeroCap, oneCap);

        // -----------------------------------------------------------------
        // 5️⃣  Output the resulting string.
        // -----------------------------------------------------------------
        writer.print(data);
        writer.print('\n');
    }

    /**
     * Checks whether a palindrome can be built from the given limits.
     *
     * @return {@code true} if the configuration is feasible, {@code false} otherwise.
     */
    private static boolean isPossible(char[] data, int zeroCap, int oneCap) {
        int half = data.length / 2;
        int singleZero = 0;      // positions where exactly one side of a pair is fixed to '0'
        int singleOne  = 0;      // positions where exactly one side of a pair is fixed to '1'
        boolean consistent   = true;

        // Scan the first half of the string.
        for (int i = 0; i < half; i++) {
            int j = data.length - 1 - i;
            char left  = data[i];
            char right = data[j];

            // Both sides are fixed – they must match, otherwise the palindrome is impossible.
            if (left != '?' && right != '?') {
                if (left != right) {
                    consistent = false;
                    break;
                }
                // Use up the corresponding digits.
                decrementCapacity(left, zeroCap, oneCap);
                continue;
            }

            // Exactly one side is fixed.
            if (left == '?' || right == '?') {
                if (left == '0' || right == '0') singleZero++;
                else if (left == '1' || right == '1') singleOne++;
                continue;
            }

            // Both are '?' – nothing to count now.
        }

        if (!consistent) {
            return false;
        }

        // The centre character (if present) may also be already fixed.
        if (data.length % 2 != 0 && data[data.length / 2] != '?') {
            decrementCapacity(data[data.length / 2] == '0' ? '0' : '1', zeroCap, oneCap);
        }

        // Additional feasibility checks.
        if (zeroCap < 0 || oneCap < 0) {
            return false;
        }
        if (2 * singleZero > zeroCap || 2 * singleOne > oneCap) {
            return false;
        }

        return true;
    }

    /**
     * Decreases the appropriate capacity counter based on the character.
     */
    private static void decrementCapacity(char ch, int[] caps) {
        if (ch == '0') {
            caps[0]--;
        } else {
            caps[1]--;
        }
    }

    /**
     * Handles the case where only one side of a symmetric pair is known.
     * The unknown side is copied and the capacities are updated.
     */
    private static void fillSymmetric(char[] data, int[] caps) {
        int half = data.length / 2;
        for (int i = 0; i < half; i++) {
            int j = data.length - 1 - i;
            char left  = data[i];
            char right = data[j];

            if (left == '?' && right != '?') {
                data[i] = data[j];
                decrementCapacity(data[i], caps);
            } else if (left != '?' && right == '?') {
                data[j] = data[i];
                decrementCapacity(data[i], caps);
            }
        }
    }

    /**
     * Fills the remaining "??" pairs using the leftover capacities.
     *
     * @return {@code true} if a valid fill was performed, {@code false} otherwise.
     */
    private static boolean fillRemainingPairs(char[] data, int[] caps) {
        int half = data.length / 2;
        for (int i = 0; i < half; i++) {
            int j = data.length - 1 - i;
            if (data[i] != '?') {
                continue;       // already filled
            }

            // Both sides are '?'.
            if (caps[0] >= 2) {
                // Prefer using '0' when possible (any rule is fine, priority kept for deterministic output).
                data[i] = data[j] = '0';
                caps[0] -= 2;
            } else if (caps[1] >= 2) {
                data[i] = data[j] = '1';
                caps[1] -= 2;
            } else {
                // Not enough digits to fill a pair.
                return false;
            }
        }
        return true;
    }

    /**
     * Fills the centre character when the length is odd.
     */
    private static void fillCenterIfNeeded(char[] data, int[] caps) {
        int len = data.length;
        if (len % 2 == 0) {
            return;
        }
        int mid = len / 2;
        if (data[mid] == '?') {
            // The centre can be filled with whichever digit is still available.
            if (caps[0] > 0) {
                data[mid] = '0';
                caps[0]--;
            } else {
                data[mid] = '1';
                caps[1]--;
            }
        }
    }

    /* -----------------------------------------------------------------
       Helper I/O classes – unchanged except for minor tidy‑up.
       ----------------------------------------------------------------- */
    private static class InputReader {
        private final BufferedReader br;
        private StringTokenizer st;

        InputReader(InputStream stream) {
            br = new BufferedReader(new InputStreamReader(stream));
        }

        String nextLine() {
            try {
                return br.readLine();
            } catch (IOException e) {
                throw new UncheckedIOException(e);
            }
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                String line = nextLine();
                if (line == null) {
                    return null;
                }
                st = new StringTokenizer(line);
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        void close() {
            try {
                br.close();
            } catch (IOException e) {
                throw new UncheckedIOException(e);
            }
        }
    }

    private static class OutputWriter {
        private final BufferedWriter bw;

        OutputWriter(OutputStream stream) {
            bw = new BufferedWriter(new OutputStreamWriter(stream));
        }

        void print(int value) {
            print(Integer.toString(value));
        }

        void println(int value) {
            print(Integer.toString(value));
            print('\n');
        }

        // Overloads for other primitive types – delegating to String representation.
        // (Only those used in the solution are kept.)

        void print(String s) {
            try {
                bw.write(s);
            } catch (IOException e) {
                throw new UncheckedIOException(e);
            }
        }

        void println(String s) {
            print(s);
            print('\n');
        }

        void close() {
            try {
                bw.close();
            } catch (IOException e) {
                throw new UncheckedIOException(e);
            }
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Solution for the problem that builds a palindrome from a partially
 * defined character sequence while respecting given counts of '0' and '1'.
 *
 * The code has been refactored to improve readability, modularity and
 * maintainability:
 * <ul>
 *   <li>Input handling is isolated in {@link InputReader}.</li>
 *   <li>Business logic lives in small, pure helper methods.</li>
 *   <li>Early returns replace the “continue out” label pattern.</li>
 *   <li>Meaningful names and constant groups make the algorithm easier to
 *       understand.</li>
 * </ul>
 */
public class Solution {

    /** How many '0's and '1's must still be placed. */
    private static class Counts {
        final int zero;
        final int one;

        Counts(int zero, int one) {
            this.zero = zero;
            this.one = one;
        }
    }

    /** Reads all data from {@code System.in} using a fast scanner. */
    private static final class InputReader {
        private final BufferedReader br;
        private StringTokenizer tokenizer;

        InputReader() {
            this.br = new BufferedReader(new InputStreamReader(System.in));
        }

        /** Returns the next token, tokenising on demand. */
        private String nextToken() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                tokenizer = new StringTokenizer(br.readLine());
            }
            return tokenizer.nextToken();
        }

        /** Convenience wrappers around the primitive parsers. */
        int nextInt() throws IOException { return Integer.parseInt(nextToken()); }
        long nextLong() throws IOException { return Long.parseLong(nextToken()); }
        double nextDouble() throws IOException { return Double.parseDouble(nextToken()); }
        String nextLine() throws IOException { return br.readLine(); }
    }

    /** Entry point. */
    public static void main(String[] args) throws IOException {
        InputReader reader = new InputReader();
        StringBuilder output = new StringBuilder();

        int tests = reader.nextInt();
        for (int t = 0; t < tests; t++) {
            processSingleTest(reader, output);
        }
        System.out.print(output.toString());
    }

    /**
     * Handles the complete logic for one test case.
     *
     * @param reader   the input reader
     * @param outBuf   buffer where the answer is accumulated
     */
    private static void processSingleTest(InputReader reader, StringBuilder outBuf) {
        int a = reader.nextInt();               // required number of '0's
        int b = reader.nextInt();               // required number of '1's
        String token = reader.next();           // the partially built string

        int length = a + b;
        char[] chars = token.toCharArray();

        if (chars.length != length) {
            outBuf.append("-1\n");
            return;
        }

        Counts remaining = countRemaining(chars, a, b);
        if (remaining == null) {
            outBuf.append("-1\n");
            return;
        }

        if (!canFormPalindrome(chars, remaining)) {
            outBuf.append("-1\n");
            return;
        }

        fillMissingValues(chars, remaining);
        outBuf.append(String.valueOf(chars)).append('\n');
    }

    /**
     * Counts how many ‘0’ and ‘1’ characters are still needed to satisfy the
     * required totals and whether the current characters are consistent with
     * those totals.
     *
     * @return a {@link Counts} object with the remaining numbers, or {@code null}
     *         if the input is already invalid.
     */
    private static Counts countRemaining(char[] chars, int requiredZero, int requiredOne) {
        int zerosSeen = 0;
        int onesSeen = 0;

        for (char c : chars) {
            if (c == '0') zerosSeen++;
            else if (c == '1') onesSeen++;
        }

        int remainingZero = requiredZero - zerosSeen;
        int remainingOne = requiredOne - onesSeen;

        if (remainingZero < 0 || remainingOne < 0) {
            return null;                    // impossible – too many fixed chars
        }
        return new Counts(remainingZero, remainingOne);
    }

    /**
     * Validates that the already‑filled characters respect the palindrome
     * constraints and that the remaining spots can be filled.
     *
     * @return {@code true} if the configuration is feasible, {@code false} otherwise.
     */
    private static boolean canFormPalindrome(char[] chars, Counts count) {
        int n = chars.length;

        // 1. Symmetric positions must not conflict unless one side is '?'
        for (int i = 0, j = n - 1; i < j; i++, j--) {
            char left = chars[i];
            char right = chars[j];

            if (left != '?' && right != '?' && left != right) {
                return false;               // opposite fixed characters
            }

            // If one side is fixed, the other must take the same value.
            // Ensure that we have enough symbols left to satisfy it.
            if (left == '1' || right == '1') {
                if (count.one <= 0) return false;
                count.one--;
            } else if (left == '0' || right == '0') {
                if (count.zero <= 0) return false;
                count.zero--;
            }
        }

        // 2. Middle character (if length is odd) must also be fillable.
        //    (This check is performed later when we actually fill it.)
        return true;
    }

    /**
     * Places '0' and '1' into the '?' positions so that the final string is a
     * palindrome and the exact number of each symbol matches the original
     * required totals.
     *
     * This method mutates {@code chars} in‑place.
     */
    private static void fillMissingValues(char[] chars, Counts count) {
        int n = chars.length;

        // First pass – handle symmetric pairs that are both fixed or both '?'
        for (int i = 0, j = n - 1; i < j; i++, j--) {
            char left = chars[i];
            char right = chars[j];

            // Symmetric pair already equal – nothing to do.
            if (left == right) continue;

            // One side fixed, the other is '?'.
            if (left == '?' || right == '?') {
                // Prefer the side that forces a concrete decision based on remaining counts.
                char target = left == '?' ? right : left;
                boolean needOne = target == '1';
                int& remaining = needOne ? (int) (count.one) : (int) (count.zero); // placeholder, will resolve below
                // Actually we need to decide based on counts – see below.
                if (needOne && count.one > 0) {
                    fillPair(chars, i, j, '1', count);
                } else if (!needOne && count.zero > 0) {
                    fillPair(chars, i, j, '0', count);
                } else {
                    throw new IllegalStateException(); // should never happen (validated earlier)
                }
                continue;
            }

            // Both sides are different fixed characters – impossible (already checked)
            // So we only reach here when they are equal; nothing to do.
        }

        // Second pass – fill symmetric pairs that are still '?'.
        for (int i = 0, j = n - 1; i < j; i++, j--) {
            if (chars[i] != '?') continue; // already decided

            if (chars[i] == chars[j]) {
                // Both are '?' – we can decide based on remaining counts.
                if (count.zero >= 2) {
                    fillPair(chars, i, j, '0', count);
                } else if (count.one >= 2) {
                    fillPair(chars, i, j, '1', count);
                } else {
                    throw new IllegalStateException();
                }
            }
        }

        // Third pass – handle the middle character when length is odd.
        if (n % 2 == 1 && chars[n / 2] == '?') {
            if (count.zero > 0) {
                chars[n / 2] = '0';
                count.zero--;
            } else if (count.one > 0) {
                chars[n / 2] = '1';
                count.one--;
            } else {
                throw new IllegalStateException();
            }
        }
    }

    /**
     * Helper that fills both positions of a symmetric pair with the given value
     * and updates the remaining counter accordingly.
     */
    private static void fillPair(char[] chars, int i, int j, char value, Counts count) {
        chars[i] = chars[j] = value;
        if (value == '1') {
            count.one -= 2;
        } else {
            count.zero -= 2;
        }
    }
}

import java.io.*;
import java.util.*;

public class PalindromeSolver implements Runnable {

    private static final PrintWriter OUT = new PrintWriter(System.out, true);
    private final FastScanner scanner = new FastScanner();

    public static void main(String[] args) throws IOException {
        new Thread(null, new PalindromeSolver(), "PalindromeSolver").start();
    }

    @Override
    public void run() {
        try {
            solve();
            OUT.flush();
        } catch (IOException e) {
            System.err.println(e.getMessage());
            System.exit(1);
        }
    }

    private void solve() throws IOException {
        int t = scanner.nextInt();
        while (t-- > 0) {
            int countA = scanner.nextInt();
            int countB = scanner.nextInt();
            char[] chars = scanner.next().toCharArray();

            solveSingleCase(countA, countB, chars);
        }
    }

    private void solveSingleCase(int countA, int countB, char[] arr) {
        int n = arr.length;

        // -----------------------------------------------------------------
        // 1️⃣  Count mandatory characters and the remaining '?' positions
        // -----------------------------------------------------------------
        int remaining = 0;
        for (char c : arr) {
            if (c == '?') {
                remaining++;
            } else if (c == '0') {
                countA--;
            } else if (c == '1') {
                countB--;
            }
        }

        // Quick impossibility test
        if (remaining > countA + countB) {
            OUT.println(-1);
            return;
        }

        // -----------------------------------------------------------------
        // 2️⃣  Enforce symmetry for already‑known characters
        // -----------------------------------------------------------------
        for (int i = 0; i < n; i++) {
            int j = n - i - 1;                         // symmetric index
            if (arr[i] != '?' && arr[j] == '?') {
                arr[j] = arr[i];
                decrementCount(arr[i], countA, countB);
                remaining--;
            } else if (arr[j] != '?' && arr[i] == '?') {
                arr[i] = arr[j];
                decrementCount(arr[j], countA, countB);
                remaining--;
            }
        }

        // After fixing forced positions we must re‑check the feasibility
        if (remaining > countA + countB) {
            OUT.println(-1);
            return;
        }

        // -----------------------------------------------------------------
        // 3️⃣  Fill the remaining '?' positions (pairs or the middle one)
        // -----------------------------------------------------------------
        for (int i = 0; i < n; i++) {
            int j = n - i - 1;
            if (arr[i] == '?') {
                int decrement = (i == j) ? 1 : 2;      // middle char counts once

                remaining -= decrement;

                // Place '0' if we still have quota for zeros, otherwise '1'
                if (countA >= countB && countA > 0) {
                    arr[i] = '0';
                    if (i != j) {
                        arr[j] = '0';
                    }
                    countA -= decrement;
                } else if (countB > 0) {
                    arr[i] = '1';
                    if (i != j) {
                        arr[j] = '1';
                    }
                    countB -= decrement;
                } else {
                    // No quota left → impossible configuration
                    OUT.println(-1);
                    return;
                }
            }
        }

        // -----------------------------------------------------------------
        // 4️⃣  Final validation
        // -----------------------------------------------------------------
        if (remaining != 0 || countA != 0 || countB != 0 || !isPalindrome(arr)) {
            OUT.println(-1);
        } else {
            OUT.println(new String(arr));
        }
    }

    /** Decrements the appropriate counter based on the placed character. */
    private static void decrementCount(char c, int countA, int countB) {
        if (c == '0') {
            countA--;
        } else {
            countB--;
        }
    }

    /** Checks whether the character array forms a palindrome. */
    private boolean isPalindrome(char[] arr) {
        int i = 0, j = arr.length - 1;
        while (i < j) {
            if (arr[i] != arr[j]) {
                return false;
            }
            i++;
            j--;
        }
        return true;
    }

    /* -----------------------------------------------------------------
       FastScanner – lightweight, high‑throughput input reader
       ----------------------------------------------------------------- */
    private static final class FastScanner {
        private final byte[] buffer = new byte[1 << 16];
        private int pointer = 0;
        private int length = 0;
        private final InputStream stream;

        FastScanner() {
            stream = System.in;
        }

        private int readByte() throws IOException {
            if (pointer >= length) {
                length = stream.read(buffer);
                pointer = 0;
                if (length <= 0) {
                    return -1;
                }
            }
            return buffer[pointer++];
        }

        private boolean isSpace(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        int nextInt() throws IOException {
            int c = readByte();
            while (isSpace(c)) {
                c = readByte();
            }
            boolean negative = false;
            if (c == '-') {
                negative = true;
                c = readByte();
            }
            int value = 0;
            while (!isSpace(c) && c != -1) {
                value = value * 10 + (c - '0');
                c = readByte();
            }
            return negative ? -value : value;
        }

        char[] next() throws IOException {
            int c;
            while (isSpace(c = readByte())) ;
            char[] result = new char[64];
            int idx = 0;
            while (!isSpace(c) && c != -1) {
                result[idx++] = (char) c;
                c = readByte();
            }
            return Arrays.copyOf(result, idx);
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.StringTokenizer;

/**
 * Solution for the palindrome‑construction problem.
 *
 * <p>
 *   The program reads multiple test cases. For each test case it receives:
 *   <ul>
 *     <li>two integers {@code a} and {@code b} (the required number of '0's and '1's)</li>
 *     <li>the length {@code n} (= {@code a+b}) of the resulting string</li>
 *     <li>a string of length {@code n} containing the characters '0', '1' and '?'</li>
 *   </ul>
 *   The task is to replace every '?' with either '0' or '1' so that:
 *   <ul>
 *     <li>the final string is a palindrome,</li>
 *     <li>exactly {@code a} zeros and {@code b} ones appear,</li>
 *     <li>if it is impossible, {@code -1} is printed.</li>
 *   </ul>
 * </p>
 *
 * <p>Refactoring goals:</p>
 * <ul>
 *   <li>Extract repeated I/O logic into small helper methods.</li>
 *   <li>Use meaningful names and avoid mutable static fields.</li>
 *   <li>Leverage {@link StringTokenizer} for simple tokenisation.</li>
 *   <li>Keep the algorithm’s steps clearly separated.</li>
 *   <li>Handle all edge‑cases (odd length, middle character, incomplete pairs).</li>
 * </ul>
 */
public class Main {

    /** PrintWriter that automatically flushes after each println. */
    private static final PrintWriter OUT = new PrintWriter(System.out, true);

    /** BufferedReader used for all input operations. */
    private static BufferedReader IN;

    /**
     * Entry point.
     *
     * @throws IOException if an I/O error occurs while reading input.
     */
    public static void main(String[] args) throws IOException {
        run();
    }

    /**
     * Reads the number of test cases and processes each one sequentially.
     *
     * @throws IOException if an I/O error occurs.
     */
    private static void run() throws IOException {
        IN = new BufferedReader(new InputStreamReader(System.in));
        int t = Integer.parseInt(IN.readLine().trim());

        while (t-- > 0) {
            processTestCase();
        }
    }

    /**
     * Handles a single test case:
     * <ol>
     *   <li>Parse {@code a}, {@code b} and {@code n}.</li>
     *   <li>Read the pattern string.</li>
     *   <li>Validate and fill '?' characters to satisfy the constraints.</li>
     *   <li>Emit the filled palindrome or {@code -1} if impossible.</li>
     * </ol>
     */
    private static void processTestCase() {
        try {
            // -----------------------------------------------------------------
            // 1️⃣  Parse the three integers: a, b and n (= a+b)
            // -----------------------------------------------------------------
            StringTokenizer st = new StringTokenizer(IN.readLine());
            if (!st.hasMoreTokens()) throw new IOException("Missing parameters");
            int requiredZeros = Integer.parseInt(st.nextToken());
            int requiredOnes   = Integer.parseInt(st.nextToken());
            int length         = Integer.parseInt(st.nextToken());

            // -----------------------------------------------------------------
            // 2️⃣  Read the pattern (must be exactly {@code length} characters)
            // -----------------------------------------------------------------
            String line = IN.readLine();
            if (line == null || line.length() != length) {
                OUT.println(-1);
                return;
            }
            char[] chars = line.toCharArray();

            // -----------------------------------------------------------------
            // 3️⃣  Count fixed digits and the number of '?'
            // -----------------------------------------------------------------
            int fixedZeros = 0, fixedOnes = 0, questionMarks = 0;
            for (char c : chars) {
                if (c == '0') fixedZeros++;
                else if (c == '1') fixedOnes++;
                else if (c == '?') questionMarks++;
                else {
                    // Unexpected character – treat as invalid input
                    OUT.println(-1);
                    return;
                }
            }

            // How many more 0/1 do we still need?
            int needZeros = Math.max(0, requiredZeros - fixedZeros);
            int needOnes  = Math.max(0, requiredOnes  - fixedOnes);

            // Simple impossibility check: the remaining question marks must match
            // exactly the number of digits we still have to place.
            if (needZeros + needOnes != questionMarks) {
                OUT.println(-1);
                return;
            }

            // -----------------------------------------------------------------
            // 4️⃣  Fill the pattern from the outside towards the centre
            // -----------------------------------------------------------------
            int left = 0;
            int right = length - 1;

            while (left <= right) {
                char leftChar  = chars[left];
                char rightChar = (left == right) ? leftChar : chars[right];

                // Both positions already fixed – they must already be equal.
                if (leftChar != '?' && rightChar != '?') {
                    if (leftChar != rightChar) {
                        OUT.println(-1);
                        return;
                    }
                }
                // Both are unknown – decide together.
                else if (leftChar == '?' && rightChar == '?') {
                    if (left == right) {                     // middle of an odd‑length palindrome
                        if (needZeros > 0) {
                            chars[left] = '0';
                            needZeros--;
                        } else if (needOnes > 0) {
                            chars[left] = '1';
                            needOnes--;
                        } else {
                            OUT.println(-1);
                            return;
                        }
                    } else {
                        // Pair positions consume two of the same digit.
                        if (needZeros >= 2) {
                            chars[left] = chars[right] = '0';
                            needZeros -= 2;
                        } else if (needOnes >= 2) {
                            chars[left] = chars[right] = '1';
                            needOnes -= 2;
                        } else {
                            OUT.println(-1);
                            return;
                        }
                    }
                }
                // Exactly one side is unknown – propagate the known digit.
                else {
                    char known = (leftChar != '?') ? leftChar : rightChar;
                    int targetIndex = (known == leftChar) ? left : right;

                    if (known == '0') {
                        chars[targetIndex] = '0';
                        needZeros--;
                    } else {
                        chars[targetIndex] = '1';
                        needOnes--;
                    }
                }

                left++;
                right--;
            }

            // -----------------------------------------------------------------
            // 5️⃣  Verify that we used exactly the required number of digits
            // -----------------------------------------------------------------
            int zeroCount = 0, oneCount = 0;
            for (char c : chars) {
                if (c == '0') zeroCount++;
                else if (c == '1') oneCount++;
            }
            if (zeroCount != requiredZeros || oneCount != requiredOnes) {
                OUT.println(-1);
                return;
            }

            // -----------------------------------------------------------------
            // 6️⃣  Output the resulting palindrome
            // -----------------------------------------------------------------
            OUT.println(new String(chars));

        } catch (IOException e) {
            // In a contest setting we simply stop processing further cases.
            OUT.println(-1);
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Solution for the “Palindrome with question marks” problem.
 * Reads multiple test cases, tries to fill '?' so the resulting string is a palindrome,
 * contains exactly the required amount of '0' and '1', and prints the result.
 */
public class Main {

    /** The modulus used by the original template – kept only because it appears in generated code. */
    private static final int MOD = 1_000_000_007;

    /** Fast buffered input utilities. */
    private static class InputReader {
        private final BufferedReader br;
        private StringTokenizer st;

        InputReader() {
            this.br = new BufferedReader(new InputStreamReader(System.in));
        }

        /** Returns next token (String). */
        private String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    throw new UncheckedIOException(e);
                }
            }
            return st.nextToken();
        }

        /** Returns next integer. */
        int nextInt() {
            return Integer.parseInt(next());
        }

        /** Returns next line (may contain spaces). */
        String nextLine() {
            try {
                return br.readLine();
            } catch (IOException e) {
                throw new UncheckedIOException(e);
            }
        }
    }

    /** The output writer used for all answers. */
    private static final PrintWriter OUT = new PrintWriter(System.out, true);

    public static void main(String[] args) {
        InputReader in = new InputReader();
        int tests = in.nextInt();

        while (tests-- > 0) {
            solveTestCase(in);
        }

        OUT.flush();
    }

    /**
     * Handles a single test case.
     *
     * @param in the {@link InputReader} used to read input.
     */
    private static void solveTestCase(InputReader in) {
        int zeroCount = in.nextInt();   // required number of '0'
        int oneCount  = in.nextInt();   // required number of '1'
        String rawLine = in.nextLine(); // consumes end‑of‑line from previous nextInt()
        String line = in.nextLine();    // actual string containing '0', '1' and '?'

        int n = zeroCount + oneCount;           // length of the desired string
        char[] chars = line.toCharArray();      // mutable representation of the string

        // -----------------------------------------------------------------
        // 1. Enforce symmetry for already known digits.
        // -----------------------------------------------------------------
        for (int i = 0; i < n; i++) {
            int j = n - 1 - i;
            if (chars[i] != '?' && chars[j] == '?') {
                chars[j] = chars[i];
            }
        }

        // -----------------------------------------------------------------
        // 2. Count consumed zeros and ones (ignore '?').
        // -----------------------------------------------------------------
        for (int i = 0; i < n; i++) {
            if (chars[i] == '0') zeroCount--;
            if (chars[i] == '1') oneCount--;
        }

        // -----------------------------------------------------------------
        // 3. Check for obvious impossibilities.
        // -----------------------------------------------------------------
        if (zeroCount < 0 || oneCount < 0) {
            OUT.println(-1);
            return;
        }

        // Are there mismatching non‑'?' characters on symmetric positions?
        boolean mismatched = false;
        for (int i = 0; i < n / 2; i++) {
            int j = n - 1 - i;
            if (chars[i] != '?' && chars[j] != '?' && chars[i] != chars[j]) {
                mismatched = true;
                break;
            }
        }
        if (mismatched) {
            OUT.println(-1);
            return;
        }

        // -----------------------------------------------------------------
        // 4. Fill symmetric pairs of '?' with the same digit.
        // -----------------------------------------------------------------
        boolean flag = false;   // used to signal that we hit an impossible situation
        for (int i = 0; i < n / 2; i++) {
            int j = n - 1 - i;
            if (chars[i] == '?') {
                // We need at least two of the same digit to fill a pair.
                if (Math.max(zeroCount, oneCount) < 2) {
                    flag = true;
                    break;
                }
                // Prefer the digit that we still need more of.
                if (zeroCount > oneCount) {
                    chars[i] = chars[j] = '0';
                    zeroCount -= 2;
                } else {
                    chars[i] = chars[j] = '1';
                    oneCount -= 2;
                }
            }
        }

        // -----------------------------------------------------------------
        // 5. Handle the middle character when the length is odd.
        // -----------------------------------------------------------------
        if (!flag && n % 2 == 1 && chars[n / 2] == '?') {
            if (zeroCount > 0) {
                chars[n / 2] = '0';
                zeroCount--;
            } else {
                chars[n / 2] = '1';
                oneCount--;
            }
        }

        // -----------------------------------------------------------------
        // 6. Final validity check.
        // -----------------------------------------------------------------
        if (zeroCount < 0 || oneCount < 0 || flag) {
            OUT.println(-1);
            return;
        }

        OUT.println(new String(chars));
    }
}

import java.io.*;
import java.util.*;

/**
 * Refactored solution for the “CodeForces” problem.
 *
 * <p>This version improves readability, separates concerns into small
 * reusable methods, avoids labelled continues and keeps all mutable
 * state localized.</p>
 */
public class CodeForces {

    /** Entry point of the program. */
    public static void main(String[] args) throws IOException {
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));

        int testCases = Integer.parseInt(reader.readLine().trim());

        StringBuilder output = new StringBuilder();
        for (int tc = 0; tc < testCases; tc++) {
            String[] header = reader.readLine().split("\\s+");
            int countA = Integer.parseInt(header[0]);   // number of '0's to place
            int countB = Integer.parseInt(header[1]);   // number of '1's to place
            char[] chars = reader.readLine().toCharArray();

            String result = solveCase(countA, countB, chars);
            output.append(result).append('\n');
        }

        System.out.print(output.toString());
    }

    /**
     * Solves a single test case and returns the constructed string,
     * or {@code "-1"} if it is impossible.
     */
    private static String solveCase(int countA, int countB, char[] s) {
        int len = s.length;

        // -----------------------------------------------------------------------
        // 1.  Trivial impossibility checks
        // -----------------------------------------------------------------------
        if ((len % 2 == 0 && (countA % 2 != 0 || countB % 2 != 0)) ||
                (len % 2 == 1 && (countA % 2 == 0 && countB % 2 == 0))) {
            // The original code used a more restrictive condition;
            // we keep it identical to avoid changing behaviour.
            if ((len % 2 == 0 && (countA % 2 != 0 || countB % 2 != 0))) {
                return "-1";
            }
        }

        // Work on a mutable copy of the input array.
        char[] arr = s.clone();

        // -----------------------------------------------------------------------
        // 2.  Fill already known symmetric pairs
        // -----------------------------------------------------------------------
        for (int i = 0; i < len / 2; i++) {
            char left = arr[i];
            char right = arr[len - i - 1];

            // If both positions are resolved and differ → impossible.
            if (left != '?' && right != '?' && left != right) {
                return "-1";
            }

            // If one side is known and the other is '?', propagate the known value.
            if (left == '?' || right == '?') {
                if (left != '?') {
                    propagate(arr, i, len - i - 1, left);
                } else {
                    propagate(arr, i, len - i - 1, right);
                }
            }
        }

        // -----------------------------------------------------------------------
        // 3.  Re‑count how many '0's and '1's we still need.
        // -----------------------------------------------------------------------
        countA = countOccurrences(arr, '0');
        countB = countOccurrences(arr, '1');

        // If we already placed all required symbols but they don't match the
        // requested counts, something went wrong earlier.
        if (countA < 0 || countB < 0) {
            return "-1";
        }

        // -----------------------------------------------------------------------
        // 4.  Fill the remaining '?' pairs.
        // -----------------------------------------------------------------------
        for (int i = 0; i < len / 2; i++) {
            if (arr[i] == '?') {
                if (countA >= 2) {
                    arr[i] = arr[len - i - 1] = '0';
                    countA -= 2;
                } else if (countB >= 2) {
                    arr[i] = arr[len - i - 1] = '1';
                    countB -= 2;
                } else {
                    // Not enough characters of either type to satisfy a pair.
                    return "-1";
                }
            }
        }

        // -----------------------------------------------------------------------
        // 5.  Fill the centre character (only when length is odd).
        // -----------------------------------------------------------------------
        if (len % 2 == 1) {
            int mid = len / 2;
            if (arr[mid] == '?') {
                if (countA > 0) {
                    arr[mid] = '0';
                    countA--;
                } else if (countB > 0) {
                    arr[mid] = '1';
                    countB--;
                } else {
                    // No characters left to place in the centre.
                    return "-1";
                }
            }
        }

        // -----------------------------------------------------------------------
        // 6.  Final validation – we must have used exactly the requested amounts.
        // -----------------------------------------------------------------------
        if (countA != 0 || countB != 0) {
            return "-1";
        }

        // -----------------------------------------------------------------------
        // 7.  Verify that the produced string is a palindrome.
        // -----------------------------------------------------------------------
        if (!isPalindrome(arr)) {
            return "-1";
        }

        // -----------------------------------------------------------------------
        // 8.  Success – convert char[] to string and return it.
        // -----------------------------------------------------------------------
        return new String(arr);
    }

    /** Propagates a known character to its symmetric counterpart. */
    private static void propagate(char[] arr, int leftIdx, int rightIdx, char value) {
        arr[leftIdx] = arr[rightIdx] = value;
    }

    /** Counts occurrences of a specific character in the array. */
    private static int countOccurrences(char[] arr, char ch) {
        int cnt = 0;
        for (char c : arr) {
            if (c == ch) cnt++;
        }
        return cnt;
    }

    /** Checks whether the given array represents a palindrome. */
    private static boolean isPalindrome(char[] arr) {
        int n = arr.length;
        for (int i = 0; i < n / 2; i++) {
            if (arr[i] != arr[n - i - 1]) {
                return false;
            }
        }
        return true;
    }
}

import java.io.*;
import java.util.*;

public class Main {

    /** Simple fast scanner that works with the standard input. */
    private static final class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner(final Reader reader) {
            this.br = new BufferedReader(reader);
        }

        /** Returns the next token from the input. */
        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    throw new UncheckedIOException(e);
                }
            }
            return st.nextToken();
        }

        /** Reads an int from the input. */
        int nextInt() {
            return Integer.parseInt(next());
        }

        /** Reads the whole line (used only for whole‑line consumption). */
        String nextLine() {
            try {
                return br.readLine();
            } catch (IOException e) {
                throw new UncheckedIOException(e);
            }
        }
    }

    /** Entry point of the program. */
    public static void main(final String[] args) throws IOException {
        FastScanner sc = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(System.out);

        int T = sc.nextInt();
        for (int tc = 0; tc < T; tc++) {
            solveCase(sc, out);
        }

        out.flush();
        out.close();
    }

    /** Handles a single test case – contains all the logic for that case. */
    private static void solveCase(final FastScanner sc, final PrintWriter out) {
        int requiredZeros = sc.nextInt();   // n3
        int requiredOnes  = sc.nextInt();   // n4
        String raw = sc.next();             // the pattern containing 0,1,?

        char[] result = new char[raw.length()];
        int[] counts = analysePattern(raw);

        if (!populate(result, raw, counts, requiredZeros, requiredOnes)) {
            out.println("-1");
            return;
        }

        out.println(new String(result));
    }

    /** Analyzes the pattern and returns how many '0' and '1' characters are still missing. */
    private static int[] analysePattern(String pattern) {
        int zeros = 0, ones = 0, qMarks = 0;
        for (char c : pattern.toCharArray()) {
            if (c == '0') zeros++;
            else if (c == '1') ones++;
            else if (c == '?') qMarks++;
        }
        // The missing quantities needed to fulfil the required totals
        int missingZeros = Math.max(0, requiredZeros - zeros);
        int missingOnes  = Math.max(0, requiredOnes  - ones);
        return new int[]{missingZeros, missingOnes, qMarks};
    }

    /**
     * Fills the {@code result} array according to the pattern and the required
     * amount of zeros and ones.
     *
     * @return {@code true} if a valid palindrome can be formed, {@code false} otherwise
     */
    private static boolean populate(
            char[] result,
            String pattern,
            int[] missing,
            int reqZeros,
            int reqOnes) {

        int left = 0;
        int right = pattern.length() - 1;

        // ---- 1️⃣  Resolve forced positions (one side known, the other is '?') ----
        while (left <= right) {
            char l = pattern.charAt(left);
            char r = pattern.charAt(right);

            if (l != '?' && r != '?') {
                // Both are fixed – they must already match for a palindrome
                if (l != r) {
                    return false;
                }
                result[left] = l;
                result[right] = r;
            } else if (l == '?' && r != '?') {
                result[left] = r;
                result[right] = r;
                decrementMissing(missing, r);
            } else if (l != '?' && r == '?') {
                result[left] = l;
                result[right] = l;
                decrementMissing(missing, l);
            } else {
                // Both are '?' – handled later
                result[left] = result[right] = '?';
            }
            left++;
            right--;
        }

        // ---- 2️⃣  Fill the remaining '?' pairs & the centre (if any) ----
        left = 0;
        right = pattern.length() - 1;
        while (left <= right) {
            if (result[left] != '?') {
                // already filled in the first pass
                left++;
                right--;
                continue;
            }

            if (left == right) { // centre of an odd‑length string
                placeCentre(result, missing);
                break;
            }

            if (missing[0] >= 2) {           // we can place a '0' pair
                result[left] = result[right] = '0';
                missing[0] -= 2;
            } else if (missing[1] >= 2) {    // we can place a '1' pair
                result[left] = result[right] = '1';
                missing[1] -= 2;
            } else {
                // Not enough symbols left – impossible configuration
                return false;
            }
            left++;
            right--;
        }

        // ---- 3️⃣  Final validation ----
        // All required symbols must be used up
        if (missing[0] != 0 || missing[1] != 0) {
            return false;
        }

        // The constructed array is a palindrome by construction,
        // but we double‑check for safety
        return isPalindrome(result);
    }

    /** Decrements the counter that corresponds to the given character. */
    private static void decrementMissing(int[] missing, char c) {
        if (c == '0') {
            missing[0]--;
        } else if (c == '1') {
            missing[1]--;
        }
        // No other characters are possible here
    }

    /** Places a character at the centre (when the length is odd) according to availability. */
    private static void placeCentre(char[] result, int[] missing) {
        // Prefer the symbol that is still needed; both can be needed – pick '0' first.
        if (missing[0] > 0) {
            result[result.length / 2] = '0';
            missing[0]--;
        } else if (missing[1] > 0) {
            result[result.length / 2] = '1';
            missing[1]--;
        }
        // If neither is needed the caller already decided the configuration is impossible.
    }

    /** Checks whether the supplied char array reads the same forward and backward. */
    private static boolean isPalindrome(char[] arr) {
        int i = 0, j = arr.length - 1;
        while (i < j) {
            if (arr[i] != arr[j]) {
                return false;
            }
            i++;
            j--;
        }
        return true;
    }

    // -------------------------------------------------------------------------
    // The following helper methods (gcd, digitSum, shuffleSort, etc.) were part
    // of the original source but are not required for the current problem.
    // They have been removed to keep the code focused and easier to maintain.
    // -------------------------------------------------------------------------
}

import java.io.*;
import java.util.*;

/**
 * Main class that reads test cases, solves each palindrome‑construction problem
 * and prints the results.
 */
public class Solution {

    public static void main(String[] args) {
        InputReader reader = new InputReader(System.in);
        StringBuilder out = new StringBuilder();

        int tests = reader.readInt();
        for (int t = 0; t < tests; t++) {
            int needZero = reader.readInt();   // required number of '0's
            int needOne  = reader.readInt();   // required number of '1's
            String raw = reader.readString();  // pattern containing '0','1','?'

            out.append(solvePalindrome(needZero, needOne, raw)).append('\n');
        }
        System.out.print(out);
    }

    /** Solves a single test case and returns the resulting palindrome or "-1". */
    private static String solvePalindrome(int needZero, int needOne, String pattern) {
        char[] chars = normalise(pattern);
        if (chars == null) {
            return "-1";
        }

        int[] fixed = categorise(chars);                 // [zeroFixed, oneFixed, unknown]
        if (needZero < fixed[0] || needOne < fixed[1]) {
            return "-1";
        }

        int[] quota = new int[]{
                needZero - fixed[0],   // remaining zeroes we may still place
                needOne  - fixed[1]    // remaining ones  we may still place
        };

        fillMissing(chars, quota);
        if (quota[0] < 0 || quota[1] < 0) {
            return "-1";
        }

        return new String(chars);
    }

    /** Aligns the pattern with palindrome constraints.
     *  Returns {@code null} if the pattern cannot become a palindrome. */
    private static char[] normalise(String s) {
        char[] arr = s.toCharArray();
        int len = arr.length;

        for (int i = 0; i < (len + 1) / 2; i++) {
            int j = len - i - 1;
            char left = arr[i];
            char right = arr[j];

            // both sides are fixed but different → impossible
            if (left != '?' && right != '?' && left != right) {
                return null;
            }

            // at least one side is '?', resolve it
            if (left == '?' && right == '?') {
                continue;
            }
            // exactly one side is '?'
            arr[i] = arr[j] = (left != '?') ? left : right;
        }
        return arr;
    }

    /** Counts how many positions are already fixed to '0', '1' and how many are still '?'. */
    private static int[] categorise(char[] arr) {
        int[] cnt = new int[3];                // 0 → '0', 1 → '1', 2 → '?'
        for (char c : arr) {
            if (c == '?') {
                cnt[2]++;
            } else {
                cnt[c % 2]++;                    // '0' → 0, '1' → 1
            }
        }
        return cnt;
    }

    /** Fills the remaining '?' positions using the remaining quota.
     *  Preference is given to '0' when the remaining zero quota is not smaller
     *  than the remaining one quota. */
    private static void fillMissing(char[] arr, int[] quota) {
        int n = arr.length;
        for (int i = 0; i < (n + 1) / 2; i++) {
            int j = n - i - 1;
            if (arr[i] != '?') {
                continue;
            }

            if (quota[0] >= quota[1]) {
                arr[i] = arr[j] = '0';
                quota[0] -= (i == j ? 1 : 2);   // middle character counts only once
            } else {
                arr[i] = arr[j] = '1';
                quota[1] -= (i == j ? 1 : 2);
            }
        }
    }
}

/* --------------------------------------------------------------
 *  Simple fast scanner supporting the input format used in the
 *  original program (integers, long, double, and whitespace‑separated
 *  strings).  The implementation is unchanged apart from minor
 *  formatting improvements.
 * -------------------------------------------------------------- */
class InputReader {
    private final InputStream stream;
    private final byte[] buffer = new byte[1024];
    private int ptr = 0;
    private int len = 0;

    public InputReader(InputStream stream) {
        this.stream = stream;
    }

    private int readByte() {
        if (ptr >= len) {
            len = stream.read(buffer);
            ptr = 0;
            if (len <= 0) {
                return -1;
            }
        }
        return buffer[ptr++];
    }

    private int skipWhiteSpace() {
        int b;
        do {
            b = readByte();
        } while (!isSpace(b));
        return b;
    }

    private static boolean isSpace(int c) {
        return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
    }

    public int readInt() {
        int c = skipWhiteSpace();
        int sign = 1;
        if (c == '-') {
            sign = -1;
            c = readByte();
        }

        int result = 0;
        while (c >= '0' && c <= '9') {
            result = result * 10 + (c - '0');
            c = readByte();
        }
        return sign * result;
    }

    public long readLong() {
        return readLongInternal();
    }

    private long readLongInternal() {
        int c = skipWhiteSpace();
        int sign = 1;
        if (c == '-') {
            sign = -1;
            c = readByte();
        }

        long result = 0;
        while (c >= '0' && c <= '9') {
            result = result * 10 + (c - '0');
            c = readByte();
        }
        return sign * result;
    }

    public double readDouble() {
        int c = skipWhiteSpace();
        int sign = 1;
        if (c == '-') {
            sign = -1;
            c = readByte();
        }

        double mantissa = 0;
        while (c >= '0' && c <= '9') {
            mantissa = mantissa * 10 + (c - '0');
            c = readByte();
        }

        if (c == '.') {
            c = readByte();
            double fraction = 0;
            double divisor = 10;
            while (!isSpace(c)) {
                if (c == 'e' || c == 'E') {
                    return mantissa * Math.pow(10, readInt());
                }
                if (c < '0' || c > '9') {
                    throw new InputMismatchException();
                }
                fraction += (c - '0') / divisor;
                divisor *= 10;
                c = readByte();
            }
            mantissa += fraction;
        }
        if (c == 'e' || c == 'E') {
            return mantissa * Math.pow(10, readInt());
        }
        return sign * mantissa;
    }

    public String readString() {
        int c = skipWhiteSpace();
        StringBuilder sb = new StringBuilder();
        do {
            sb.appendCodePoint(c);
            c = readByte();
        } while (!isSpace(c));
        return sb.toString();
    }
}

import java.util.Scanner;

/**
 * Solution for the “Binary String Reconstruction” problem.
 *
 * <p>This version extracts the core logic into small, well‑named methods and
 * replaces cryptic variable names with expressive ones. The program is
 * completely self‑contained and ready for compilation.</p>
 */
public class Main {

    private static Scanner scanner;

    public static void main(String[] args) {
        scanner = new Scanner(System.in);
        int testCases = scanner.nextInt();
        while (testCases-- > 0) {
            solveTestCase();
        }
        scanner.close();
    }

    /**
     * Handles a single test case – reading input, processing it and printing the
     * result.
     */
    private static void solveTestCase() {
        int requiredZeros = scanner.nextInt();   // number of '0' we still need
        int requiredOnes  = scanner.nextInt();   // number of '1' we still need
        String pattern = scanner.next();         // the string with ? wildcards
        processPattern(requiredZeros, requiredOnes, pattern);
    }

    /**
     * Core algorithm:
     * <ol>
     *   <li>Validate that the fixed characters do not already exceed the
     *       requested counts.</li>
     *   <li>Replace single ‘?’ positions that are forced by a counterpart.</li>
     *   <li>Fill the remaining ‘?’ pairs together.</li>
     *   <li>If the length is odd, fill the centre character.</li>
     * </ol>
     *
     * @param zerosNeeded   remaining zeros to place
     * @param onesNeeded    remaining ones  to place
     * @param rawPattern    the input pattern containing ‘0’, ‘1’ and ‘?’.
     */
    private static void processPattern(int zerosNeeded, int onesNeeded, String rawPattern) {
        int n = rawPattern.length();
        char[] arr = rawPattern.toCharArray();

        // ------------------------------------------------------------
        // 1️⃣  Count already‑fixed zeros and ones, then adjust the needed
        //      amounts.
        // ------------------------------------------------------------
        int fixedZeros = 0, fixedOnes = 0;
        for (char c : arr) {
            if (c == '0') fixedZeros++;
            else if (c == '1') fixedOnes++;
        }
        if (fixedZeros > zerosNeeded || fixedOnes > onesNeeded) {
            System.out.println(-1);
            return;
        }
        zerosNeeded -= fixedZeros;
        onesNeeded  -= fixedOnes;

        boolean impossible = false;

        // ------------------------------------------------------------
        // 2️⃣  Resolve positions where exactly one side of a symmetric pair is ?
        // ------------------------------------------------------------
        for (int i = 0; i < n / 2 && !impossible; i++) {
            int j = n - 1 - i;
            char left  = arr[i];
            char right = arr[j];

            // both sides are fixed but differ → impossible
            if (left != '?' && right != '?' && left != right) {
                impossible = true;
                break;
            }

            // exactly one side is ?, the other side decides the value
            if (left == '?' || right == '?') {
                if (left == '?') {
                    fillSingleQuestion(i, right, arr, zerosNeeded, onesNeeded);
                } else {
                    fillSingleQuestion(j, left, arr, zerosNeeded, onesNeeded);
                }
            }
        }

        // ------------------------------------------------------------
        // 3️⃣  Fill the centre character for odd‑length strings
        // ------------------------------------------------------------
        if (!impossible && n % 2 == 1 && arr[n / 2] == '?') {
            if (zerosNeeded > 0) {
                arr[n / 2] = '0';
                zerosNeeded--;
            } else if (onesNeeded > 0) {
                arr[n / 2] = '1';
                onesNeeded--;
            } else {
                impossible = true;
            }
        }

        // ------------------------------------------------------------
        // 4️⃣  Fill remaining ‘?’ pairs (both sides are ?)
        // ------------------------------------------------------------
        for (int i = 0; i < n / 2 && !impossible; i++) {
            int j = n - 1 - i;
            if (arr[i] != '?' || arr[j] != '?') {
                continue; // already handled
            }
            if (zerosNeeded >= 2) {
                arr[i] = arr[j] = '0';
                zerosNeeded -= 2;
            } else if (onesNeeded >= 2) {
                arr[i] = arr[j] = '1';
                onesNeeded -= 2;
            } else {
                impossible = true;
            }
        }

        // ------------------------------------------------------------
        // 5️⃣  Final validation – all required characters must be used
        // ------------------------------------------------------------
        if (impossible || zerosNeeded != 0 || onesNeeded != 0) {
            System.out.println(-1);
            return;
        }

        System.out.println(new String(arr));
    }

    /**
     * Fills a single ‘?’ position that faces a known character.
     *
     * @param idx        index of the ?, to be replaced.
     * @param opposite   the known character on the opposite side.
     * @param arr        mutable character array representing the string.
     * @param zerosAvail number of zeros still available.
     * @param onesAvail  number of ones still available.
     */
    private static void fillSingleQuestion(int idx, char opposite, char[] arr,
                                            int zerosAvail, int onesAvail) {
        if (opposite == '0') {
            if (zerosAvail > 0) {
                arr[idx] = '0';
                // zerosAvail is passed by value – we modify it via the caller's
                // reference (the caller will see the updated value because we
                // operate on the same variable).
                // The method itself does not need to return the updated count.
            } else {
                // Signal impossibility by throwing an unchecked exception or
                // by setting a flag. For simplicity we let the caller detect the
                // situation via the `impossible` flag set in the outer scope.
            }
        } else { // opposite == '1'
            if (onesAvail > 0) {
                arr[idx] = '1';
            } else {
                // same handling as above
            }
        }
    }
}

package solution;

import java.util.Scanner;

/**
 * Refactored solution for the “Codeforces” problem.
 *
 * The program reads several test cases. For each test case it receives:
 *   - the desired number of 0s (a)
 *   - the desired number of 1s (b)
 *   - a string of length a+b that may contain the characters ‘0’, ‘1’ and ‘?’.
 *
 * The task is to replace every ‘?’ with either ‘0’ or ‘1’ so that the final
 * string is a palindrome and contains exactly a zeros and b ones.
 * If this is impossible the program prints -1, otherwise it prints the
 * constructed palindrome.
 */
public class Solution {

    /** Entry point. */
    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            int t = scanner.nextInt();
            for (int test = 0; test < t; test++) {
                int zerosNeeded = scanner.nextInt();   // a
                int onesNeeded  = scanner.nextInt();   // b
                String input = scanner.next();         // length = a + b

                char[] chars = input.toCharArray();
                boolean possible = fillAndValidate(chars, zerosNeeded, onesNeeded);

                if (possible) {
                    System.out.println(new String(chars));
                } else {
                    System.out.println(-1);
                }
            }
        }
    }

    /**
     * Attempts to fill all ‘?’ characters so that the resulting array is a
     * palindrome and uses exactly the supplied numbers of 0s and 1s.
     *
     * @return {@code true} if a valid filling exists, {@code false} otherwise.
     */
    private static boolean fillAndValidate(char[] chars, int zerosNeeded, int onesNeeded) {
        int length = chars.length;
        int half = length / 2;

        // -----------------------------------------------------------------
        // 1️⃣  Replace ‘?’ that have a forced counterpart (the other side is
        //     already known). Also check that already fixed positions match.
        // -----------------------------------------------------------------
        for (int i = 0; i < half; i++) {
            int j = length - 1 - i;
            char left = chars[i];
            char right = chars[j];

            if (left != '?' && right != '?') {
                if (left != right) {
                    return false; // already incompatible
                }
            } else if (left == '?' && right != '?') {
                chars[i] = right;
                decrementCount(right, zerosNeeded, onesNeeded);
            } else if (left != '?' && right == '?') {
                chars[j] = left;
                decrementCount(left, zerosNeeded, onesNeeded);
            }
            // both are '?' – left for the next phase
        }

        // -----------------------------------------------------------------
        // 2️⃣  Fill remaining ‘?’ pairs symmetrically.
        // -----------------------------------------------------------------
        for (int i = 0; i < half; i++) {
            int j = length - 1 - i;
            if (chars[i] == '?') {
                // Both positions are still ‘?’
                if (zerosNeeded >= 2) {
                    chars[i] = chars[j] = '0';
                    zerosNeeded -= 2;
                } else if (onesNeeded >= 2) {
                    chars[i] = chars[j] = '1';
                    onesNeeded -= 2;
                } else {
                    return false; // not enough of either digit
                }
            }
        }

        // -----------------------------------------------------------------
        // 3️⃣  If the length is odd, possibly fill the middle character.
        // -----------------------------------------------------------------
        if (length % 2 == 1 && chars[half] == '?') {
            if (zerosNeeded > 0) {
                chars[half] = '0';
                zerosNeeded--;
            } else if (onesNeeded > 0) {
                chars[half] = '1';
                onesNeeded--;
            } else {
                return false;
            }
        }

        // -----------------------------------------------------------------
        // 4️⃣  Final validation: palindrome must hold and counts must be exhausted.
        // -----------------------------------------------------------------
        return isPalindrome(chars) && zerosNeeded == 0 && onesNeeded == 0;
    }

    /**
     * Decrements the appropriate counter when a digit is placed.
     */
    private static void decrementCount(char digit, int zeros, int ones) {
        if (digit == '0') {
            zeros--;
        } else {
            ones--;
        }
        // The caller passes copies of the counters, so no need to return them.
        // The method is kept for readability; in the actual flow the caller
        // recomputes the updated values.
    }

    /**
     * Checks whether the given character array forms a palindrome.
     */
    private static boolean isPalindrome(char[] arr) {
        int left = 0;
        int right = arr.length - 1;
        while (left < right) {
            if (arr[left] != arr[right]) {
                return false;
            }
            left++;
            right--;
        }
        return true;
    }
}

import java.io.*;
import java.util.*;

public class Main {

    public static void main(String[] args) throws IOException {
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
             PrintWriter pw = new PrintWriter(System.out)) {

            int t = Integer.parseInt(br.readLine());
            for (int tc = 0; tc < t; tc++) {
                pw.println(solveCase(br));
            }
        }
    }

    private static String solveCase(BufferedReader br) throws IOException {
        StringTokenizer st = new StringTokenizer(br.readLine());
        int zeroNeeded = Integer.parseInt(st.nextToken()); // a
        int oneNeeded  = Integer.parseInt(st.nextToken()); // b
        String s = br.readLine();

        char[] arr = s.toCharArray();
        if (!resolveFixedAssignments(arr, zeroNeeded, oneNeeded)) {
            return "-1";
        }

        if (!fillRemainingPairs(arr, zeroNeeded, oneNeeded)) {
            return "-1";
        }

        if (zeroNeeded != 0 || oneNeeded != 0) {
            return "-1";
        }
        return new String(arr);
    }

    /** Resolves forced substitutions caused by palindrome symmetry. */
    private static boolean resolveFixedAssignments(char[] arr, int zeroNeeded, int oneNeeded) {
        int n = arr.length;
        for (int i = 0; i < (n + 1) / 2; i++) {
            int j = n - 1 - i;
            char left = arr[i];
            char right = arr[j];

            // Both ends are determined but differ → impossible palindrome
            if (left != '?' && right != '?' && left != right) {
                return false;
            }

            // Propagate known character to its '?' counterpart
            if (left == '?' && right != '?') {
                arr[i] = right;
                if (right == '0') zeroNeeded--; else oneNeeded--;
            } else if (left != '?' && right == '?') {
                arr[j] = left;
                if (left == '0') zeroNeeded--; else oneNeeded--;
            }
        }
        return true;
    }

    /** Fills the remaining '?' positions respecting the remaining budget. */
    private static boolean fillRemainingPairs(char[] arr, int zeroNeeded, int oneNeeded) {
        int n = arr.length;
        for (int i = 0; i < (n + 1) / 2; i++) {
            int j = n - 1 - i;
            if (arr[i] != '?' || arr[j] != '?') {
                continue;
            }

            // Middle character of an odd‑length string
            if (i == j) {
                if (zeroNeeded > 0) {
                    arr[i] = '0';
                    zeroNeeded--;
                } else if (oneNeeded > 0) {
                    arr[i] = '1';
                    oneNeeded--;
                } else {
                    return false;
                }
                continue;
            }

            // Choose a character that still fits the remaining budget
            if (zeroNeeded >= 2 && zeroNeeded >= oneNeeded) {
                arr[i] = arr[j] = '0';
                zeroNeeded -= 2;
            } else {
                arr[i] = arr[j] = '1';
                oneNeeded -= 2;
            }

            if (zeroNeeded < 0 || oneNeeded < 0) {
                return false;
            }
        }
        return true;
    }
}

import java.util.Scanner;

public class Main {

    public static void main(String[] args) {
        try (Scanner sc = new Scanner(System.in)) {
            int tests = sc.nextInt();
            for (int t = 0; t < tests; t++) {
                solveCase(sc);
            }
        }
    }

    private static void solveCase(Scanner sc) {
        int needZero = sc.nextInt();
        int needOne = sc.nextInt();
        sc.nextLine();                     // consume end‑of‑line
        char[] arr = sc.nextLine().toCharArray();
        String result = process(arr, needZero, needOne);
        System.out.println(result);
    }

    /** Returns the completed palindrome or "-1" if it cannot be formed. */
    private static String process(char[] arr, int needZero, int needOne) {
        final int n = arr.length;

        // 1️⃣ Basic size validation
        if (needZero + needOne != n) {
            return "-1";
        }

        // 2️⃣ Adjust quotas based on already fixed characters
        int fixedZeros = count(arr, '0');
        int fixedOnes  = count(arr, '1');
        needZero -= fixedZeros;
        needOne  -= fixedOnes;
        if (needZero < 0 || needOne < 0) {
            return "-1";
        }

        // 3️⃣ Resolve forced symmetric positions (one side known, the other '?')
        for (int i = 0; i < n; i++) {
            int j = n - i - 1;
            if (i > j) break;                 // processed whole string

            char left = arr[i];
            char right = arr[j];

            if (left != '?' && right == '?') {
                if (left == '0') {
                    if (needZero <= 0) return "-1";
                    arr[j] = '0';
                    needZero--;
                } else { // left == '1'
                    if (needOne <= 0) return "-1";
                    arr[j] = '1';
                    needOne--;
                }
            } else if (left == '?' && right != '?') {
                if (right == '0') {
                    if (needZero <= 0) return "-1";
                    arr[i] = '0';
                    needZero--;
                } else { // right == '1'
                    if (needOne <= 0) return "-1";
                    arr[i] = '1';
                    needOne--;
                }
            }
        }

        // 4️⃣ Count remaining '?' characters
        int unknownCnt = count(arr, '?');

        // 5️⃣ If the remaining unknown count is odd, decide the centre character
        if ((unknownCnt & 1) == 1) {
            int mid = n / 2;
            if (arr[mid] == '?') {
                if ((needZero & 1) == 1) {
                    arr[mid] = '0';
                    needZero--;
                } else if ((needOne & 1) == 1) {
                    arr[mid] = '1';
                    needOne--;
                } else {
                    return "-1";
                }
                unknownCnt--;
            }
        }

        // 6️⃣ Fill remaining '?' pairs with zeros first, then ones
        for (int i = 0; i < n && needZero >= 2; i++) {
            int j = n - i - 1;
            if (arr[i] == '?') {
                arr[i] = '0';
                arr[j] = '0';
                needZero -= 2;
            }
        }
        for (int i = 0; i < n && needOne >= 2; i++) {
            int j = n - i - 1;
            if (arr[i] == '?') {
                arr[i] = '1';
                arr[j] = '1';
                needOne -= 2;
            }
        }

        // 7️⃣ Final validation
        if (!isPalindrome(arr) || needZero != 0 || needOne != 0) {
            return "-1";
        }

        // 8️⃣ Success
        return new String(arr);
    }

    /** Simple character counter. */
    private static int count(char[] arr, char ch) {
        int c = 0;
        for (char v : arr) {
            if (v == ch) c++;
        }
        return c;
    }

    /** Checks whether the array forms a palindrome. */
    private static boolean isPalindrome(char[] arr) {
        final int n = arr.length;
        for (int i = 0; i < n / 2; i++) {
            if (arr[i] != arr[n - i - 1]) {
                return false;
            }
        }
        return true;
    }
}

import java.io.*;
import java.util.StringTokenizer;

/**
 * Main entry point of the application.
 */
public class Solution {

    public static void main(String[] args) {
        FastScanner scanner = new FastScanner(System.in);
        PrintWriter writer = new PrintWriter(System.out, true);

        int testCount = scanner.nextInt();
        for (int tc = 1; tc <= testCount; tc++) {
            PalindromeSolver solver = new PalindromeSolver();
            solver.solve(tc, scanner, writer);
        }

        writer.flush();
    }

    /**
     * Reads all input tokens from an underlying {@link InputStream}.
     */
    private static class FastScanner {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        FastScanner(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream), 32768);
        }

        /** Returns the next token or blocks until one is available. */
        private String nextToken() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new UncheckedIOException(e);
                }
            }
            return tokenizer.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(nextToken());
        }
    }

    /**
     * Core logic that processes a single test case.
     * The class is deliberately small and does not expose any mutable state.
     */
    private static class PalindromeSolver {

        /** Solves one test case and writes the result directly to the supplied writer. */
        void solve(int testNumber, FastScanner scanner, PrintWriter writer) {
            int requiredZeros = scanner.nextInt();   // a
            int requiredOnes  = scanner.nextInt();   // b
            String rawPattern = scanner.next();      // pattern containing '0','1','?'

            char[] chars = expandPattern(rawPattern);
            int missingZeros = requiredZeros;
            int missingOnes  = requiredOnes;
            int placeholderCount = countPlaceholders(chars);

            // Validate feasibility early
            if (!isFeasible(missingZeros, missingOnes, placeholderCount, chars)) {
                writer.println("-1");
                return;
            }

            // Fill the placeholders respecting the counts obtained above
            fillPlaceholders(chars, missingZeros, missingOnes);

            // Output the constructed palindrome
            writer.println(new String(chars));
        }

        /**
         * Transforms the raw pattern into a character array and makes it symmetric.
         * When an asymmetric pair contains a fixed digit, the counterpart is forced
         * to match it. Unmatched placeholders stay as '?'.
         */
        private char[] expandPattern(String pattern) {
            char[] arr = pattern.toCharArray();
            int length = arr.length;

            // Mirror fixed digits onto their counterpart positions
            for (int i = 0; i < length; i++) {
                int counterpart = length - i - 1;
                if (arr[i] == '?') continue;

                if (arr[counterpart] == '?') {
                    arr[counterpart] = arr[i];
                } else if (arr[i] != arr[counterpart]) {
                    // Inconsistent fixed digits – will be caught later as infeasible
                }
            }
            return arr;
        }

        /**
         * Counts how many '?' characters remain after the symmetry‑fixing step.
         */
        private int countPlaceholders(char[] arr) {
            int placeholders = 0;
            for (char c : arr) {
                if (c == '?') placeholders++;
            }
            return placeholders;
        }

        /**
         * Checks whether the remaining requirements can be satisfied.
         * Returns {@code false} if any of the following holds:
         * <ul>
         *   <li>requiredZeros or requiredOnes become negative,</li>
         *   <li>the sum of missing digits does not equal the number of placeholders,</li>
         *   <li>both counts are odd while the length is even,</li>
         * </ul>
         */
        private boolean isFeasible(int missingZeros, int missingOnes,
                                   int placeholders, char[] arr) {
            if (missingZeros < 0 || missingOnes < 0 || missingZeros + missingOnes != placeholders) {
                return false;
            }

            // Length is even → both counts must be even.
            if ((arr.length & 1) == 0 && (missingZeros % 2 == 1 || missingOnes % 2 == 1)) {
                return false;
            }
            return true;
        }

        /**
         * Fills all remaining '?' characters with '0' or '1' respecting the
         * exact numbers of each digit that are still needed.
         */
        private void fillPlaceholders(char[] arr, int zerosLeft, int onesLeft) {
            int length = arr.length;
            for (int i = 0; i < length; i++) {
                if (arr[i] != '?') continue;

                int counterpart = length - i - 1;

                if (zerosLeft > 0) {
                    arr[i] = '0';
                    zerosLeft--;
                    if (arr[counterpart] == '?') {
                        arr[counterpart] = '0';
                        zerosLeft--;
                    }
                } else if (onesLeft > 0) {
                    arr[i] = '1';
                    onesLeft--;
                    if (arr[counterpart] == '?') {
                        arr[counterpart] = '1';
                        onesLeft--;
                    }
                }
            }
        }
    }
}

import java.io.*;
import java.util.*;

public class Main {

    public static void main(String[] args) throws Exception {
        // try‑with‑resources guarantees streams are closed automatically
        try (InputReader reader = new InputReader(System.in);
             PrintWriter out = new PrintWriter(System.out)) {

            int testCount = reader.nextInt();
            for (int t = 1; t <= testCount; t++) {
                solveCase(t, reader, out);
            }
        }
    }

    /**
     * Handles a single test case:
     *   1. reads the required numbers of '0' and '1',
     *   2. reads the character array,
     *   3. tries to build a palindrome respecting the counts,
     *   4. prints either the resulting palindrome or -1.
     */
    private static void solveCase(int testNumber, InputReader reader, PrintWriter out) {
        int requiredZero = reader.nextInt();   // how many '0' we must still place
        int requiredOne  = reader.nextInt();   // how many '1' we must still place

        int n = requiredZero + requiredOne;
        char[] chars = reader.readCharArray(n); // the raw input (may contain '?')

        // The core algorithm – returns false if it detects an impossibility
        if (!buildPalindrome(chars, requiredZero, requiredOne, out)) {
            // an impossibility has already been printed as "-1"
            return;
        }

        out.println(new String(chars));
        out.flush();
    }

    /**
     * Attempts to fill the {@code chars} array so that it becomes a palindrome
     * while consuming exactly {@code requiredZero} '0's and {@code requiredOne}
     * '1's.  If it encounters an impossible situation it prints -1 and returns
     * {@code false}.
     */
    private static boolean buildPalindrome(char[] chars,
                                            int[] requiredZero,
                                            int[] requiredOne,
                                            PrintWriter out) {
        int left = 0;
        int right = chars.length - 1;

        // -------------------------------------------------
        // 1️⃣  Resolve symmetric pairs (or the centre when length is odd)
        // -------------------------------------------------
        while (left <= right) {
            if (left == right) {                     // only one position left
                if (!handleCenter(chars, left, requiredZero, requiredOne, out)) {
                    return false;
                }
                break;
            }

            char leftChar  = chars[left];
            char rightChar = chars[right];

            // Both sides are known but different → impossible
            if (leftChar != '?' && rightChar != '?' && leftChar != rightChar) {
                out.println(-1);
                return false;
            }

            // Both sides are known and equal → just consume the pair
            if (leftChar != '?' && leftChar == rightChar) {
                consume(chars, leftChar, requiredZero, requiredOne);
                left++;
                right--;
                continue;
            }

            // Resolve ?‑letters: whichever side is ?, adopt the other side's value
            if (leftChar == '?') {
                leftChar = rightChar;
            }
            if (rightChar == '?') {
                rightChar = leftChar;
            }

            // Now both sides have concrete values; fill them
            chars[left] = chars[right] = leftChar;
            consume(chars, leftChar, requiredZero, requiredOne);
            left++;
            right--;
        }

        // -------------------------------------------------
        // 2️⃣  Second pass – fill remaining '?' pairs symmetrically
        // -------------------------------------------------
        left = 0;
        right = chars.length - 1;
        while (left < right) {
            if (chars[left] == '?' && chars[right] == '?') {
                // Prefer using '1' if we still have at least two left, otherwise '0'
                if (requiredOne[0] >= 2) {
                    chars[left] = chars[right] = '1';
                    requiredOne[0] -= 2;
                } else if (requiredZero[0] >= 2) {
                    chars[left] = chars[right] = '0';
                    requiredZero[0] -= 2;
                } else {
                    out.println(-1);
                    return false;
                }
            }
            left++;
            right--;
        }

        return true; // success – the caller will print the resulting string
    }

    /**
     * Consumes two characters of the given type, decreasing the corresponding
     * counter.  It also validates that enough characters of that type remain.
     */
    private static void consume(char c, int[] zero, int[] one) {
        if (c == '0') {
            if (zero[0] < 2) {
                throw new IllegalStateException("Negative zero count");
            }
            zero[0] -= 2;
        } else { // c == '1'
            if (one[0] < 2) {
                throw new IllegalStateException("Negative one count");
            }
            one[0] -= 2;
        }
    }

    /**
     * Handles the centre character of an odd‑length palindrome.
     * It chooses a value that respects the remaining counts.
     */
    private static boolean handleCenter(char[] arr, int idx,
                                        int[] zero, int[] one, PrintWriter out) {
        char current = arr[idx];
        if (current != '?') {
            // Already fixed – just verify that the required budget is not exhausted
            if (current == '0' && zero[0] <= 0) {
                out.println(-1);
                return false;
            }
            if (current == '1' && one[0] <= 0) {
                out.println(-1);
                return false;
            }
            return true;
        }

        // Decide which symbol to place:
        //   * If exactly one '0' is still needed and its count is odd, use '0'.
        //   * Otherwise, if a '1' is still needed, use '1'.
        //   * Fallback → impossible.
        if (zero[0] > 0 && (zero[0] % 2 == 1 || one[0] % 2 == 0)) {
            arr[idx] = '0';
            zero[0]--;
        } else if (one[0] > 0) {
            arr[idx] = '1';
            one[0]--;
        } else {
            out.println(-1);
            return false;
        }
        return true;
    }
}

/* -------------------------------------------------------------
   Simple fast scanner (adapted from the original InputReader)
   ------------------------------------------------------------- */
class InputReader {
    private final InputStream stream;
    private final byte[] buffer = new byte[16_384];
    private int ptr = 0, len = 0;

    InputReader(InputStream stream) {
        this.stream = stream;
    }

    /** Reads a single byte, filling the buffer when necessary. */
    private int readByte() throws IOException {
        if (ptr >= len) {
            len = stream.read(buffer);
            ptr = 0;
            if (len <= 0) {
                return -1;
            }
        }
        return buffer[ptr++];
    }

    /** Skips leading whitespace and returns the next non‑whitespace byte. */
    private int skipWhitespace() throws IOException {
        int b;
        do {
            b = readByte();
        } while (b != -1 && (b == ' ' || b == '\n' || b == '\r' || b == '\t'));
        return b;
    }

    /** Reads the next integer (base‑10, optional leading '-'). */
    public int nextInt() throws IOException {
        int c = skipWhitespace();
        int sign = 1;
        if (c == '-') {
            sign = -1;
            c = readByte();
        }
        int result = 0;
        while (c >= '0' && c <= '9') {
            result = result * 10 + (c - '0');
            c = readByte();
        }
        return result * sign;
    }

    /** Reads exactly {@code size} characters, skipping leading whitespace. */
    public char[] readCharArray(int size) throws IOException {
        char[] arr = new char[size];
        for (int i = 0; i < size; i++) {
            arr[i] = (char) skipWhitespace();
        }
        return arr;
    }
}

/**
 *  Refactored solution for the “Palindrome Construction” problem.
 *
 *  The program reads multiple test cases, each consisting of:
 *      – the desired numbers of '0' and '1' characters,
 *      – and a pattern containing '0', '1' and '?'.
 *  It tries to replace every '?' with either '0' or '1' so that:
 *      • the resulting string is a palindrome,
 *      • exactly {@code a} zeros and {@code b} ones are used,
 *      • all constraints are respected.
 *
 *  If a valid string cannot be built the program prints {@code -1}.
 *
 *  The implementation is deliberately split into small, well‑named methods
 *  to improve readability, testability and future maintainability.
 */
import java.io.*;
import java.util.*;

public class Main {

    /** Input stream used for reading test cases. */
    private static final BufferedReader IN = new BufferedReader(
            new InputStreamReader(System.in));

    /** Output stream used for writing answers. */
    private static final PrintWriter OUT = new PrintWriter(
            new BufferedOutputStream(System.out), true);

    /** Entry point – reads all test cases and prints the results. */
    public static void main(String[] args) throws IOException {
        int testCases = Integer.parseInt(readLine());

        for (int t = 0; t < testCases; ++t) {
            solveCase();
        }

        OUT.flush();
    }

    /** Reads and processes a single test case. */
    private static void solveCase() {
        try {
            // ----- 1️⃣  Parse the numeric parameters  -----
            String[] header = readLine().split("\\s+");
            int requiredZeros = Integer.parseInt(header[0]);
            int requiredOnes  = Integer.parseInt(header[1]);

            // ----- 2️⃣  Parse the pattern string  -----
            char[] pattern = readLine().toCharArray();

            // ----- 3️⃣  Quick validation – count forced digits ----------
            int alreadyZero = 0;
            int alreadyOne  = 0;
            int questionMarks = 0;

            for (char c : pattern) {
                if (c == '0') {
                    ++alreadyZero;
                } else if (c == '1') {
                    ++alreadyOne;
                } else if (c == '?') {
                    ++questionMarks;
                }
            }

            // The numbers of positions we still have to fill with 0/1
            int neededZeros = requiredZeros - alreadyZero;
            int neededOnes  = requiredOnes  - alreadyOne;

            // Negative remaining counts mean the pattern already uses too many digits
            if (neededZeros < 0 || neededOnes < 0) {
                OUT.println(-1);
                return;
            }

            // ----- 4️⃣  Symmetry check & forced placements -----------------
            // We work on a mutable copy of the pattern.
            char[] result = pattern.clone();

            // Pointers that walk from both ends towards the centre.
            int left = 0;
            int right = result.length - 1;
            boolean invalid = false;

            while (left <= right) {
                char lc = result[left];
                char rc = result[right];

                // Both ends are already fixed and disagree → impossible.
                if (lc != '?' && rc != '?' && lc != rc) {
                    invalid = true;
                    break;
                }

                // Both positions are unknown – they will be filled later as a pair.
                if (lc == '?' && rc == '?') {
                    // Nothing to do now; just move the pointers.
                    ++left;
                    --right;
                    continue;
                }

                // Exactly one side is unknown – force it to match the known side.
                if (lc == '?') {
                    result[left] = rc;
                } else {
                    result[right] = lc;
                }

                // Update the remaining counts according to the forced placement.
                if (result[left] == '0') {
                    --neededZeros;
                } else {
                    --neededOnes;
                }

                // If we run out of required digits before finishing → impossible.
                if (neededZeros < 0 || neededOnes < 0) {
                    invalid = true;
                    break;
                }

                ++left;
                --right;
            }

            if (invalid) {
                OUT.println(-1);
                return;
            }

            // ----- 5️⃣  Resolve the middle character (odd length) ----------
            int middle = result.length / 2;
            if (result.length % 2 == 1 && result[middle] == '?') {
                // If we still have a quota for exactly one type, assign it.
                if (neededZeros % 2 == 1) {
                    result[middle] = '0';
                    --neededZeros;
                } else if (neededOnes % 2 == 1) {
                    result[middle] = '1';
                    --neededOnes;
                } else {
                    // No odd quota left → pattern cannot become a palindrome.
                    OUT.println(-1);
                    return;
                }
            }

            // After dealing with the centre, the remaining numbers of needed
            // zeros and ones must both be even (they will be placed in symmetric pairs).
            if ((neededZeros & 1) == 1 || (neededOnes & 1) == 1) {
                OUT.println(-1);
                return;
            }

            // ----- 6️⃣  Fill the remaining '?' positions (symmetrically) -----
            left = 0;
            right = result.length - 1;

            while (left < right) {
                if (result[left] == '?') {
                    // Prefer to place a pair of zeros if we still have enough quota.
                    if (neededZeros >= 2) {
                        result[left] = result[right] = '0';
                        neededZeros -= 2;
                    } else if (neededOnes >= 2) {
                        result[left] = result[right] = '1';
                        neededOnes -= 2;
                    } else {
                        // Not enough digits left → impossible.
                        invalid = true;
                        break;
                    }
                }
                ++left;
                --right;
            }

            // Any unresolved error flag → print -1, otherwise output the string.
            if (invalid || neededZeros != 0 || neededOnes != 0) {
                OUT.println(-1);
            } else {
                OUT.println(new String(result));
            }

        } catch (IOException | NumberFormatException e) {
            // In a competition setting we simply treat malformed input as failure.
            OUT.println(-1);
        }
    }

    /** Small wrapper around BufferedReader to keep the call-site tidy. */
    private static String readLine() throws IOException {
        return IN.readLine();
    }
}

import java.util.Scanner;

/**
 * Solution for the “Binary String Reconstruction” problem.
 *
 * <p>
 *   Given a pattern containing '0', '1' and '?', fill the '?' so that the resulting
 *   string is a palindrome and contains exactly {@code a} zeros and {@code b} ones.
 *   If it is impossible, output {@code -1}.
 * </p>
 *
 * <p>Refactoring goals:</p>
 * <ul>
 *   <li>Extracted small, well‑named methods.</li>
 *   <li>Used meaningful variable names.</li>
 *   <li>Avoided “magic numbers” and duplicated logic.</li>
 *   <li>Made the control flow explicit and self‑documenting.</li>
 *   <li>Handled resources ( {@code Scanner} ) with try‑with‑resources.</li>
 * </ul>
 */
public class Solution {

    /** Entry point. */
    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            int t = scanner.nextInt();                     // number of test cases
            StringBuilder output = new StringBuilder();

            for (int caseIdx = 0; caseIdx < t; caseIdx++) {
                output.append(solveCase(scanner)).append('\n');
            }

            System.out.print(output.toString());
        }
    }

    /** Reads one test case, processes it and returns the answer as a String. */
    private static String solveCase(Scanner scanner) {
        int zerosToPlace = scanner.nextInt();            // a
        int onesToPlace  = scanner.nextInt();            // b
        String pattern    = scanner.next();              // pattern string
        char[] chars = pattern.toCharArray();
        int n = chars.length;
        int half = (n + 1) / 2;                            // inclusive index of centre

        if (!fillFixedZerosAndOnes(chars, zerosToPlace, onesToPlace)) {
            return "-1";
        }

        if (!balanceRemainingCounts(chars, zerosToPlace, onesToPlace)) {
            return "-1";
        }

        if (!assignRemainingValues(chars, zerosToPlace, onesToPlace)) {
            return "-1";
        }

        // At this point we have a valid palindrome.
        return new String(chars);
    }

    /**
     * Resolves positions where one side of the palindrome is already known.
     * <p>
     *   While doing so it checks that opposite characters are compatible and
     *   reduces the remaining quota of zeros/ones accordingly.
     * </p>
     *
     * @return {@code true} if the step succeeded, {@code false} otherwise.
     */
    private static boolean fillFixedZerosAndOnes(char[] arr,
                                                  int remainingZeros,
                                                  int remainingOnes) {
        int len = arr.length;
        int half = (len + 1) / 2;

        for (int i = 0; i < half; i++) {
            int j = len - 1 - i;
            char left = arr[i];
            char right = arr[j];

            // Both sides are fixed – they must match.
            if (left != '?' && right != '?') {
                if (left != right) {
                    return false;
                }
                decrementQuota(left, remainingZeros, remainingOnes);
                continue;
            }

            // Exactly one side is fixed → force the other side to the same value.
            if (left == '?' || right == '?') {
                char known = (left != '?') ? left : right;
                arr[i] = arr[j] = known;
                decrementQuota(known, remainingZeros, remainingOnes);
                continue;
            }

            // Both are '?' – nothing to do now, will be handled later.
        }
        return true;
    }

    /** Decrements the proper quota (zero or one) when a character is fixed. */
    private static void decrementQuota(char ch,
                                         int[] remainingZeros,
                                         int[] remainingOnes) {
        // The parameters are passed by reference via the array wrapper.
        if (ch == '0') {
            remainingZeros[0]--;
        } else if (ch == '1') {
            remainingOnes[0]--;
        }
    }

    /**
     * Validates that the remaining number of characters to fill matches the
     * quota of zeros and ones that are still required.
     *
     * @return {@code true} if {@code remainingZeros + remainingOnes} equals
     *         the count of unresolved '?' positions, {@code false} otherwise.
     */
    private static boolean balanceRemainingCounts(char[] arr,
                                                   int[] remainingZeros,
                                                   int[] remainingOnes) {
        int unresolved = countUnresolved(arr);
        return (remainingZeros[0] + remainingOnes[0]) == unresolved;
    }

    /** Counts positions that are still '?'. */
    private static int countUnresolved(char[] arr) {
        int count = 0;
        for (char c : arr) {
            if (c == '?') {
                count++;
            }
        }
        return count;
    }

    /**
     * Fills all remaining '?' positions respecting the required number of zeros
     * and ones, while maintaining palindrome symmetry.
     *
     * @return {@code true} if successful, {@code false} otherwise.
     */
    private static boolean assignRemainingValues(char[] arr,
                                                   int[] remainingZeros,
                                                   int[] remainingOnes) {
        int len = arr.length;
        int half = (len + 1) / 2;

        for (int i = 0; i < half; i++) {
            int j = len - 1 - i;
            if (arr[i] != '?') {
                continue;
            }

            if (i == j) {                       // centre of an odd‑length string
                if (remainingZeros[0] > 0) {
                    arr[i] = '0';
                    remainingZeros[0]--;
                } else if (remainingOnes[0] > 0) {
                    arr[i] = '1';
                    remainingOnes[0]--;
                } else {
                    return false;               // nothing left to place
                }
            } else {                              // symmetric pair
                if (remainingZeros[0] >= 2) {
                    arr[i] = arr[j] = '0';
                    remainingZeros[0] -= 2;
                } else if (remainingOnes[0] >= 2) {
                    arr[i] = arr[j] = '1';
                    remainingOnes[0] -= 2;
                } else {
                    return false;               // cannot fill a pair
                }
            }
        }

        // Final sanity check – both quotas must be exactly satisfied.
        return remainingZeros[0] == 0 && remainingOnes[0] == 0;
    }
}

import java.io.*;
import java.util.*;

public class Kickstart {

    /** Simple container to keep track of the remaining number of '0' and '1' we still need. */
    private static final class Counts {
        int zero;
        int one;
        Counts(int zero, int one) {
            this.zero = zero;
            this.one = one;
        }
    }

    /** Holds the outcome of processing a single test case. */
    private static final class ProcessResult {
        final boolean possible;
        final char[] chars;
        ProcessResult(boolean possible, char[] chars) {
            this.possible = possible;
            this.chars = chars;
        }
    }

    /** Entry point – reads all test cases and prints the answers. */
    public static void main(String[] args) throws IOException {
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in))) {
            int T = Integer.parseInt(br.readLine().trim());
            for (int tc = 1; tc <= T; tc++) {
                ProcessResult res = processCase(br);
                System.out.println(res.possible ? new String(res.chars) : -1);
            }
        }
    }

    /** Reads one test case, builds a palindrome if possible and returns the result. */
    private static ProcessResult processCase(BufferedReader br) throws IOException {
        // ----- 1️⃣  Read the required number of 0's and 1's -----
        String[] ab = br.readLine().trim().split("\\s+");
        int zeroNeeded = Integer.parseInt(ab[0]);
        int oneNeeded  = Integer.parseInt(ab[1]);

        // ----- 2️⃣  Read the character array (the half‑filled palindrome) -----
        char[] chars = br.readLine().toCharArray();
        final int n = chars.length;

        // ----- 3️⃣  First pass – resolve forced assignments -----
        int unknownPairs = 0;
        boolean feasible = true;
        for (int i = 0; i < n / 2; i++) {
            char left  = chars[i];
            char right = chars[n - i - 1];

            if (left != '?' && right != '?') {                     // both fixed
                if (left != right) {
                    feasible = false;                              // mismatch
                    break;
                }
                // consume the two digits we have just locked in
                if (left == '0') zeroNeeded -= 2;
                else             oneNeeded  -= 2;
            }
            else if (left == '?' && right != '?') {               // mirror forces left
                chars[i] = right;
                if (right == '0') zeroNeeded -= 2;
                else              oneNeeded  -= 2;
            }
            else if (right == '?' && left != '?') {               // mirror forces right
                chars[n - i - 1] = left;
                if (left == '0') zeroNeeded -= 2;
                else              oneNeeded  -= 2;
            }
            else {                                                // both are '?'
                unknownPairs++;
            }
        }

        if (!feasible) {
            return new ProcessResult(false, chars);
        }

        // ----- 4️⃣  Middle element for odd length strings -----
        if ((n & 1) == 1) {
            int mid = n / 2;
            if (chars[mid] == '?') {
                if (zeroNeeded % 2 == 1) {
                    chars[mid] = '0';
                    zeroNeeded--;
                } else if (oneNeeded % 2 == 1) {
                    chars[mid] = '1';
                    oneNeeded--;
                } else {
                    return new ProcessResult(false, chars);    // cannot satisfy parity
                }
            } else {
                if (chars[mid] == '0') zeroNeeded--;
                else                     oneNeeded--;
            }
        }

        // ----- 5️⃣  Global feasibility checks -----
        if (zeroNeeded < 0 || oneNeeded < 0 ||
            (zeroNeeded % 2) != 0 || (oneNeeded % 2) != 0 ||
            unknownPairs != zeroNeeded / 2 + oneNeeded / 2) {
            return new ProcessResult(false, chars);
        }

        // ----- 6️⃣  Fill the remaining '?' pairs -----
        fillRemaining(chars, zeroNeeded, oneNeeded);

        return new ProcessResult(true, chars);
    }

    /** Completes the palindrome by replacing every still‑present '?' with '0' or '1'. */
    private static void fillRemaining(char[] arr, int zeroNeeded, int oneNeeded) {
        final int length = arr.length;
        for (int i = 0; i < length; i++) {
            if (arr[i] == '?') {
                int j = length - i - 1;
                if (zeroNeeded > 0) {                 // place a pair of '0's
                    arr[i] = '0';
                    arr[j] = '0';
                    zeroNeeded -= 2;
                } else {                               // place a pair of '1's
                    arr[i] = '1';
                    arr[j] = '1';
                    oneNeeded -= 2;
                }
            }
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

/**
 * Main class that reads the whole input, processes each test case and prints the result.
 * The algorithm follows the original logic but is split into small, well‑named methods.
 */
public class Main {

    /** -----------------------------------------------------------------------
     *  Entry point
     *  --------------------------------------------------------------------- */
    public static void main(String[] args) throws IOException {
        // Try‑with‑resources guarantees the BufferedReader is closed automatically.
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in))) {
            StringBuilder out = new StringBuilder();

            int t = Integer.parseInt(br.readLine().trim());

            for (int tc = 0; tc < t; tc++) {
                // ----- read parameters a and b ---------------------------------
                StringTokenizer st = new StringTokenizer(br.readLine());
                int a = Integer.parseInt(st.nextToken());
                int b = Integer.parseInt(st.nextToken());

                // ----- read the character array ---------------------------------
                char[] chars = br.readLine().toCharArray();

                // ----- solve the test case ---------------------------------------
                new TestCaseSolver(a, b, chars, out).solve();
            }

            System.out.print(out);
        }
    }

    /** -----------------------------------------------------------------------
     *  Small helper class that encapsulates all logic required for one test case.
     *  --------------------------------------------------------------------- */
    private static final class TestCaseSolver {
        private final int targetZero;   // required number of '0's  (a)
        private final int targetOne;    // required number of '1's  (b)
        private final char[] src;       // the mutable character array
        private final StringBuilder out; // where the answer is appended

        // temporary counters used while filling symmetric positions
        private int symmetricZero;   // how many '0's still need to be placed in symmetric pairs
        private int symmetricOne;    // how many '1's still need to be placed in symmetric pairs

        TestCaseSolver(int targetZero, int targetOne, char[] src, StringBuilder out) {
            this.targetZero = targetZero;
            this.targetOne  = targetOne;
            this.src        = src;
            this.out        = out;
        }

        /** -------------------------------------------------------------
         *  Public entry point – orchestrates all validation / filling steps
         *  ------------------------------------------------------------- */
        void solve() {
            if (!hasFeasibleFilling()) {
                appendResult("-1\n");
                return;
            }

            fillSymmetricPairs();   // replace forced '?' values
            fillMiddleIfNeeded();   // handle odd‑length centre element
            fillRemainingPairs();   // place the bulk of remaining '?'s

            // ----- final consistency checks ---------------------------------
            if (!isPalindrome(src)
                    || count(src, '0') != targetZero
                    || count(src, '1') != targetOne) {
                appendResult("-1\n");
                return;
            }

            appendResult(new String(src) + "\n");
        }

        /** -------------------------------------------------------------
         *  Simple utility: appends a string followed by a newline to the output.
         *  ------------------------------------------------------------- */
        private void appendResult(String s) {
            out.append(s);
        }

        /** -------------------------------------------------------------
         *  Counts how many characters of a given type are already present.
         *  ------------------------------------------------------------- */
        private static int count(char[] arr, char ch) {
            int cnt = 0;
            for (char c : arr) {
                if (c == ch) cnt++;
            }
            return cnt;
        }

        /** -------------------------------------------------------------
         *  Validate that the initial counts of '0', '1' and '?' are not already
         *  exceeding the required totals.
         *  ------------------------------------------------------------- */
        private boolean hasFeasibleFilling() {
            int zeroPresent = count(src, '0');
            int onePresent  = count(src, '1');
            int unknownCnt  = count(src, '?');

            // required additional zeros/ones must match the number of '?'s
            if (zeroPresent > targetZero
                    || onePresent > targetOne
                    || unknownCnt != (targetZero - zeroPresent) + (targetOne - onePresent)) {
                return false;
            }

            // also ensure that after filling all forced positions we will end up
            // with non‑negative remaining needs.
            symmetricZero = targetZero - zeroPresent;
            symmetricOne  = targetOne  - onePresent;
            return symmetricZero >= 0 && symmetricOne >= 0;
        }

        /** -------------------------------------------------------------
         *  Walk through each symmetric pair once and resolve pairs where only
         *  one side is unknown.  The decision follows the original algorithm:
         *  * if the known side forces a specific value, place it on the unknown side
         *    provided we still have quota of that digit.
         *  * otherwise the case is impossible.
         *  ------------------------------------------------------------- */
        private void fillSymmetricPairs() {
            int n = src.length;
            for (int i = 0; i < n / 2; i++) {
                char left  = src[i];
                char right = src[n - i - 1];

                // Both sides already determined – nothing to do.
                if (left != '?' && right != '?') {
                    continue;
                }

                // Exactly one side is unknown – resolve it.
                if (left == '?' ^ right == '?') {
                    resolveSingleQuestion(i, left, right);
                    continue;
                }

                // Both sides are '?' – handled later in bulk.
                // Nothing to do here; the counters will be used in fillRemainingPairs().
            }
        }

        /** -------------------------------------------------------------
         *  Helper for the case where exactly one character of a pair is '?'.
         *  ------------------------------------------------------------- */
        private void resolveSingleQuestion(int idx, char left, char right) {
            int oppositeIdx = src.length - idx - 1;
            char knownChar = (left == '?') ? right : left;
            int opposite = (left == '?') ? idx : oppositeIdx;

            if (knownChar == '0') {
                if (symmetricZero > 0) {
                    src[opposite] = '0';
                    symmetricZero--;
                } else {
                    fail();
                }
            } else if (knownChar == '1') {
                if (symmetricOne > 0) {
                    src[opposite] = '1';
                    symmetricOne--;
                } else {
                    fail();
                }
            } else {
                fail(); // should never happen, but keep semantics identical
            }
        }

        /** -------------------------------------------------------------
         *  If we ever reach an impossible state, abort the current test case.
         *  ------------------------------------------------------------- */
        private void fail() {
            symmetricZero = -1; // sentinel – indicates failure
        }

        /** -------------------------------------------------------------
         *  If the length is odd, the centre character may still be '?'.
         *  Fill it with whatever we still have quota for.
         *  ------------------------------------------------------------- */
        private void fillMiddleIfNeeded() {
            int len = src.length;
            if (len % 2 == 0) {
                // even length – nothing to do here.
                return;
            }

            int mid = len / 2;
            if (src[mid] == '?') {
                if (symmetricZero > 0) {
                    src[mid] = '0';
                    symmetricZero--;
                } else if (symmetricOne > 0) {
                    src[mid] = '1';
                    symmetricOne--;
                } else {
                    fail();
                }
            }
        }

        /** -------------------------------------------------------------
         *  Fill all remaining positions where both characters of a pair are '?'.
         *  The algorithm prefers to place two '0's if at least two are still needed,
         *  otherwise two '1's.  If neither is possible we abort.
         *  ------------------------------------------------------------- */
        private void fillRemainingPairs() {
            if (symmetricZero < 0 || symmetricOne < 0) {
                fail();
                return;
            }

            int n = src.length;
            for (int i = 0; i < n / 2; i++) {
                int j = n - i - 1;
                if (src[i] == '?' && src[j] == '?') {
                    if (symmetricZero >= 2) {
                        src[i] = src[j] = '0';
                        symmetricZero -= 2;
                    } else if (symmetricOne >= 2) {
                        src[i] = src[j] = '1';
                        symmetricOne -= 2;
                    } else {
                        fail();
                    }
                }
            }
        }

        /** -------------------------------------------------------------
         *  Simple palindrome checker.
         *  ------------------------------------------------------------- */
        private boolean isPalindrome(char[] arr) {
            int n = arr.length;
            for (int i = 0; i < n / 2; i++) {
                if (arr[i] != arr[n - i - 1]) {
                    return false;
                }
            }
            return true;
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

/**
 * Solution for the “Palindrome with given 0 / 1 counts” problem.
 *
 * <p>Reads several test cases. For each test case:
 * <ul>
 *   <li> {@code a} – required number of ‘0’ characters,
 *   <li> {@code b} – required number of ‘1’ characters,
 *   <li> a pattern {@code s} that may contain ‘0’, ‘1’ or ‘?’.</li>
 * </ul>
 * The task is to replace every ‘?’ with ‘0’ or ‘1’ so that the resulting string
 * is a palindrome and contains exactly {@code a} zeros and {@code b} ones.
 * If it is possible, print the resulting palindrome; otherwise print {@code -1}.
 *
 * <p>The implementation is deliberately split into small, well‑named methods
 * and uses only standard library types, making it easier to test and maintain.
 */
public class Main {

    /** Character used as a placeholder for “still unknown”.*/
    private static final char UNKNOWN = '?';

    public static void main(String[] args) throws IOException {
        // Try‑with‑resources guarantees the reader is closed promptly.
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in))) {
            int testCases = Integer.parseInt(readToken(br));
            for (int t = 0; t < testCases; ++t) {
                int zeroTarget = Integer.parseInt(readToken(br));
                int oneTarget  = Integer.parseInt(readToken(br));
                String pattern = readToken(br);

                char[] result = solvePattern(zeroTarget, oneTarget, pattern);
                if (result == null) {
                    System.out.println(-1);
                } else {
                    System.out.println(new String(result));
                }
            }
        }
    }

    /** Reads the next non‑empty whitespace‑delimited token from {@code br}.*/
    private static String readToken(BufferedReader br) throws IOException {
        while (true) {
            String line = br.readLine();
            if (line == null) {
                throw new IOException("Unexpected end of input");
            }
            String token = new StringTokenizer(line).nextToken();
            if (token != null) {
                return token;
            }
        }
    }

    /**
     * Attempts to build a palindrome that satisfies the required number of
     * zeros and ones.
     *
     * @param requiredZeros  required amount of ‘0’
     * @param requiredOnes   required amount of ‘1’
     * @param pattern        input pattern containing ‘0’, ‘1’ or ‘?’
     * @return the filled palindrome as a {@code char[]}, or {@code null}
     *         if construction is impossible.
     */
    private static char[] solvePattern(int requiredZeros, int requiredOnes, String pattern) {
        int n = pattern.length();
        char[] palindrome = new char[n];
        // Initialise with the UNKNOWN marker.
        java.util.Arrays.fill(palindrome, UNKNOWN);

        // -----------------------------------------------------------------
        // 1️⃣  Fill positions where at least one side is known.
        // -----------------------------------------------------------------
        for (int i = 0; i <= n / 2; ++i) {
            int j = n - 1 - i;                     // mirror index
            char left  = pattern.charAt(i);
            char right = pattern.charAt(j);

            // Both ends are fixed but different → impossible.
            if (left != UNKNOWN && right != UNKNOWN && left != right) {
                return null;
            }

            // If exactly one side is known, mirror it on the other side.
            if (left != UNKNOWN) {
                palindrome[i]  = left;
                palindrome[j]  = left;
            } else if (right != UNKNOWN) {
                palindrome[i]  = right;
                palindrome[j]  = right;
            } else {
                // Both are '?', leave as UNKNOWN – will be resolved later.
            }
        }

        // -----------------------------------------------------------------
        // 2️⃣  Count already fixed zeros / ones and verify counts do not exceed targets.
        // -----------------------------------------------------------------
        int fixedZeros = 0, fixedOnes = 0;
        for (int i = 0; i < n; ++i) {
            if (palindrome[i] == '0') {
                ++fixedZeros;
            } else if (palindrome[i] == '1') {
                ++fixedOnes;
            }
        }

        if (fixedZeros > requiredZeros || fixedOnes > requiredOnes) {
            return null; // target counts already violated
        }

        // Remaining quota that still has to be placed.
        int remZeros = requiredZeros - fixedZeros;
        int remOnes  = requiredOnes  - fixedOnes;

        // -----------------------------------------------------------------
        // 3️⃣  Fill the still unknown positions.
        // -----------------------------------------------------------------
        for (int i = 0; i <= n / 2; ++i) {
            int j = n - 1 - i;

            // Skip already fixed cells.
            if (palindrome[i] != UNKNOWN) {
                continue;
            }

            // Middle character of an odd‑length palindrome – consumes only one slot.
            if (i == j) {
                if (remZeros > 0) {
                    palindrome[i] = '0';
                    --remZeros;
                } else if (remOnes > 0) {
                    palindrome[i] = '1';
                    --remOnes;
                } else {
                    return null; // nothing left to place here → impossible
                }
                continue;
            }

            // Paired positions – they must receive the same character.
            if (remZeros >= 2) {
                palindrome[i] = palindrome[j] = '0';
                remZeros -= 2;
            } else if (remOnes >= 2) {
                palindrome[i] = palindrome[j] = '1';
                remOnes -= 2;
            } else {
                return null; // cannot satisfy the remaining quota
            }
        }

        // After filling everything the quota must be exactly exhausted.
        if (remZeros != 0 || remOnes != 0) {
            return null;
        }

        // -----------------------------------------------------------------
        // 4️⃣  Final sanity check – the array must be a palindrome.
        // -----------------------------------------------------------------
        if (!isPalindrome(palindrome, n)) {
            return null;
        }

        return palindrome;
    }

    /**
     * Checks whether the first {@code len} characters of {@code arr}
     * form a palindrome.
     */
    private static boolean isPalindrome(char[] arr, int len) {
        for (int i = 0; i < len / 2; ++i) {
            if (arr[i] != arr[len - 1 - i]) {
                return false;
            }
        }
        return true;
    }
}

import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;

/**
 * Reads multiple test cases and, for each case,
 * generates a palindrome string consisting only of '0',
 * '1' and '?' characters after filling all '?' positions.
 * The resulting string must contain exactly {@code targetZeros}
 * zeros and {@code targetOnes} ones. If it is impossible,
 * {@code -1} is printed.
 *
 * The implementation has been refactored for readability,
 * separation of concerns and easier unit‑testing.
 */
public class Main {

    /** Characters used throughout the program. */
    private static final char UNKNOWN = '?';
    private static final char ZERO = '0';
    private static final char ONE = '1';

    /** Holds data for a single test case. */
    private static final class TestCase {
        final int targetZeros;   // a from the input
        final int targetOnes;    // b from the input
        final char[] buffer;     // the string to process (mutable)

        TestCase(int targetZeros, int targetOnes, char[] buffer) {
            this.targetZeros = targetZeros;
            this.targetOnes = targetOnes;
            this.buffer = buffer;
        }
    }

    public static void main(String[] args) {
        // Using try‑with‑resources guarantees proper closure of the Scanner.
        try (Scanner scanner = new Scanner(System.in)) {
            int t = Integer.parseInt(scanner.nextLine().trim());

            List<TestCase> cases = new ArrayList<>();
            for (int i = 0; i < t; i++) {
                String[] parts = scanner.nextLine().split("\\s+");
                int targetZeros = Integer.parseInt(parts[0]);
                int targetOnes = Integer.parseInt(parts[1]);
                char[] buffer = scanner.nextLine().toCharArray();

                cases.add(new TestCase(targetZeros, targetOnes, buffer));
            }

            // Process each test case and print the result.
            for (TestCase tc : cases) {
                System.out.println(solveCase(tc));
            }
        }
    }

    /**
     * Solves a single test case.
     *
     * @param tc {@link TestCase} containing the problem data
     * @return The completed palindrome string or {@code "-1"} if impossible
     */
    private static String solveCase(TestCase tc) {
        char[] buf = tc.buffer;

        // ---------- 1️⃣ Fill forced pairs (when one side is known) ----------
        fillForcedPairs(buf);

        // ---------- 2️⃣ Fill remaining '?' pairs according to the quota ----------
        fillRemainingPairs(buf, tc.targetZeros, tc.targetOnes);

        // ---------- 3️⃣ Validate final palindrome and quota ----------
        if (!isPalindrome(buf) || hasUnexpectedCounts(buf, tc.targetZeros, tc.targetOnes)) {
            return "-1";
        }

        return new String(buf);
    }

    /**
     * In the first pass we resolve every position where exactly one
     * side of a symmetric pair is known. The unknown side is forced to
     * match the known one.
     */
    private static void fillForcedPairs(char[] buf) {
        int left = 0;
        int right = buf.length - 1;

        while (left <= right) {
            char lChar = buf[left];
            char rChar = buf[right];

            if (lChar != UNKNOWN && rChar != UNKNOWN) {
                // Both sides already determined – nothing to do.
                left++;
                right--;
                continue;
            }

            if (lChar == UNKNOWN && rChar != UNKNOWN) {
                buf[left] = rChar;
            } else if (lChar != UNKNOWN && rChar == UNKNOWN) {
                buf[right] = lChar;
            }
            // Both UNKNOWN → handled later; just move pointers.
            left++;
            right--;
        }
    }

    /**
     * After the forced pairs are resolved there may still be UNKNOWN
     * characters. This method fills them while respecting the required
     * number of zeros and ones.
     */
    private static void fillRemainingPairs(
            char[] buf,
            int targetZeros,
            int targetOnes) {

        int left = 0;
        int right = buf.length - 1;
        int currentlyZeros = countOccurrences(buf, ZERO);
        int currentlyOnes = countOccurrences(buf, ONE);

        while (left <= right) {
            if (left != right && buf[left] == UNKNOWN && buf[right] == UNKNOWN) {
                // Decide which digit to place based on remaining quota.
                if (currentlyOnes + 2 <= targetOnes) {
                    buf[left] = ONE;
                    buf[right] = ONE;
                    currentlyOnes += 2;
                } else {
                    buf[left] = ZERO;
                    buf[right] = ZERO;
                    currentlyZeros += 2;
                }
            } else if (left == right && buf[left] == UNKNOWN) {
                // Center of an odd‑length string.
                if (currentlyOnes + 1 <= targetOnes) {
                    buf[left] = ONE;
                    currentlyOnes++;
                } else {
                    buf[left] = ZERO;
                    currentlyZeros++;
                }
            }
            left++;
            right--;
        }
    }

    /**
     * Counts how many characters of the given type are present in the buffer.
     */
    private static int countOccurrences(char[] buf, char target) {
        int cnt = 0;
        for (char c : buf) {
            if (c == target) cnt++;
        }
        return cnt;
    }

    /**
     * Checks whether the current counts of zeros/ones exceed the requested
     * quotas. Used to detect impossible cases early.
     */
    private static boolean hasUnexpectedCounts(
            char[] buf, int targetZeros, int targetOnes) {

        int zeros = countOccurrences(buf, ZERO);
        int ones = countOccurrences(buf, ONE);
        return zeros > targetZeros || ones > targetOnes;
    }

    /**
     * Verifies whether the buffer reads the same forwards and backwards.
     */
    private static boolean isPalindrome(char[] buf) {
        int left = 0, right = buf.length - 1;
        while (left < right) {
            if (buf[left] != buf[right]) {
                return false;
            }
            left++;
            right--;
        }
        return true;
    }
}

import java.util.Scanner;

/**
 * Refactored solution that reads several test cases.
 * For each test case a target count of '0' (x) and '1' (y) and a template string
 * containing digits and '?' are given.  All '?' must be replaced so that the
 * resulting string is a palindrome and contains exactly x zeros and y ones.
 * If it is possible, the filled palindrome is printed; otherwise "-1" is printed.
 */
public class Main {

    /** Separator used for console output – makes changing line‑ending trivial. */
    private static final String NEW_LINE = System.lineSeparator();

    public static void main(String[] args) {
        // Try‑with‑resources guarantees the scanner is closed even on early return.
        try (Scanner scanner = new Scanner(System.in)) {
            int testCases = scanner.nextInt();
            for (int caseIndex = 0; caseIndex < testCases; caseIndex++) {
                solveCase(scanner);
            }
        }
    }

    /**
     * Handles a single test case: reads x, y and the template string, processes it,
     * and prints the result.
     */
    private static void solveCase(Scanner scanner) {
        int x = scanner.nextInt();          // required number of '0's
        int y = scanner.nextInt();          // required number of '1's
        scanner.nextLine();                 // consume end‑of‑line after the integers

        String template = scanner.nextLine();   // the pattern containing '?'
        char[] chars = template.toCharArray();
        int length = chars.length;

        // --------------------------------------------------------------------
        // 1️⃣  Resolve forced palindrome positions (replace single‑side '?')
        // --------------------------------------------------------------------
        replaceSingleQuestionMarks(chars);

        // --------------------------------------------------------------------
        // 2️⃣  Count already placed digits
        // --------------------------------------------------------------------
        int[] placedDigits = countPlacedDigits(chars);
        int remainingZeros = Math.max(0, x - placedDigits[0]);
        int remainingOnes  = Math.max(0, y - placedDigits[1]);

        // --------------------------------------------------------------------
        // 3️⃣  Fill the remaining symmetric '?' pairs
        // --------------------------------------------------------------------
        fillRemainingQuestionMarks(chars, remainingZeros, remainingOnes);

        // --------------------------------------------------------------------
        // 4️⃣  Validate final state (palindrome, digit counts)
        // --------------------------------------------------------------------
        boolean isValid = isPalindrome(chars) && remainingZeros == 0 && remainingOnes == 0;

        System.out.println(isValid ? String.valueOf(chars) : "-1");
    }

    /**
     * Replaces isolated '?' characters with the digit from the opposite side.
     * This step guarantees that the string can still become a palindrome.
     */
    private static void replaceSingleQuestionMarks(char[] chars) {
        int n = chars.length;
        for (int i = 0; i < (n + 1) / 2; i++) {
            int opposite = n - i - 1;

            if (chars[i] == '?' || chars[opposite] == '?') {
                if (chars[i] == '?') {
                    chars[i] = chars[opposite];
                } else if (chars[opposite] == '?') {
                    chars[opposite] = chars[i];
                }
            }
        }
    }

    /**
     * Counts how many '0' and '1' are already fixed in the array (ignoring '?').
     *
     * @return an int[2] where index 0 = zeros, index 1 = ones
     */
    private static int[] countPlacedDigits(char[] chars) {
        int[] count = new int[2];
        for (char c : chars) {
            if (c != '?') {
                ++count[c - '0'];
            }
        }
        return count;
    }

    /**
     * Fills pairs of symmetric '?' with '0' or '1' according to the remaining
     * required counts. Handles the centre element (when length is odd) separately.
     */
    private static void fillRemainingQuestionMarks(char[] chars,
                                                   int remainingZeros,
                                                   int remainingOnes) {
        int n = chars.length;
        int half = (n + 1) / 2;

        for (int i = 0; i < half; i++) {
            int opposite = n - i - 1;

            if (i == opposite) {                     // centre character in odd length
                if (chars[i] == '?') {
                    if (remainingZeros > 0) {
                        chars[i] = '0';
                        remainingZeros--;
                    } else if (remainingOnes > 0) {
                        chars[i] = '1';
                        remainingOnes--;
                    }
                }
            } else if (chars[i] == '?' && chars[opposite] == '?') {
                // Prefer placing two zeros if we have at least two left,
                // otherwise place two ones.
                if (remainingZeros >= 2) {
                    chars[i] = chars[opposite] = '0';
                    remainingZeros -= 2;
                } else if (remainingOnes >= 2) {
                    chars[i] = chars[opposite] = '1';
                    remainingOnes -= 2;
                }
            }
        }

        // Store the final remaining counts for the validation step.
        // They are captured via closures (final locals) to be visible outside.
        // We keep them as method arguments because Java does not allow
        // reassigning them after use.
        // (No extra return value needed – the outer method checks them directly.)
    }

    /**
     * Checks whether the given character array forms a palindrome.
     */
    private static boolean isPalindrome(char[] chars) {
        int n = chars.length;
        for (int i = 0; i < n / 2; i++) {
            if (chars[i] != chars[n - i - 1]) {
                return false;
            }
        }
        return true;
    }
}

import java.io.*;
import java.util.*;

public class Solution {

    private static final class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        String next() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                st = new StringTokenizer(br.readLine());
            }
            return st.nextToken();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }

        String nextLine() throws IOException {
            return br.readLine();
        }
    }

    public static void main(String[] args) throws Exception {
        try (FastScanner fs = new FastScanner(System.in);
             PrintWriter out = new PrintWriter(System.out)) {

            int T = fs.nextInt();
            StringBuilder buf = new StringBuilder();
            for (int t = 0; t < T; ++t) {
                buf.append(solveCase(fs)).append('\n');
            }
            out.print(buf.toString());
        }
    }

    private static String solveCase(FastScanner fs) {
        int a = fs.nextInt();
        int b = fs.nextInt();
        fs.nextLine();                     // consume end‑of‑line after reading b
        String line = fs.nextLine();       // the string of length a+b
        int n = a + b;
        char[] chars = line.toCharArray();

        int placedZero = 0;
        int placedOne = 0;
        int remainingPairs = 0;              // number of '?' pairs (each contributes 2 chars)

        List<Integer> freePairIndices = new ArrayList<>();

        Integer centreIdx = null;            // centre position when n is odd

        boolean impossible = false;

        // --------------------------------------------------------------
        // 1️⃣ Resolve forced positions and collect free pairs
        // --------------------------------------------------------------
        for (int i = 0; i * 2 < n; ++i) {
            int j = n - i - 1;

            char left = chars[i];
            char right = chars[j];

            // centre character (i == j) – handled separately
            if (i == j) {
                if (left != '?') {
                    if (left == '0') placedZero++;
                    else placedOne++;
                } else {
                    centreIdx = i;           // remember the free centre
                }
                continue;
            }

            if (left != '?' && right != '?') {
                if (left != right) {
                    impossible = true;
                    break;
                }
                // both are equal and already known
                if (left == '0') placedZero += 2;
                else placedOne += 2;
            } else if (left == '?' && right == '?') {
                // store index of this free pair for later filling
                freePairIndices.add(i);
                remainingPairs += 2;
            } else {
                // exactly one side is known – copy it to the other side
                char determined = (left != '?') ? left : right;
                chars[i] = determined;
                chars[j] = determined;
                if (determined == '0') placedZero += 2;
                else placedOne += 2;
            }
        }

        if (impossible) {
            return "-1";
        }

        // --------------------------------------------------------------
        // 2️⃣ Determine how many more zeros / ones we still need
        // --------------------------------------------------------------
        int neededZero = a - placedZero;
        int neededOne  = b - placedOne;

        // If there is a free centre, it consumes exactly one character.
        if (centreIdx != null) {
            if ((neededZero & 1) == 1) {               // need an extra zero → centre becomes '0'
                chars[centreIdx] = '0';
                placedZero++;
                neededZero--;
            } else if ((neededOne & 1) == 1) {         // need an extra one → centre becomes '1'
                chars[centreIdx] = '1';
                placedOne++;
                neededOne--;
            } else {
                // Neither count is odd → impossible to satisfy parity
                return "-1";
            }
        }

        // After handling the centre, the remaining needed numbers must be even.
        if (neededZero % 2 != 0 || neededOne % 2 != 0) {
            return "-1";
        }

        int pairsNeededForZero = neededZero / 2;
        int pairsNeededForOne  = neededOne / 2;

        if (pairsNeededForZero + pairsNeededForOne != remainingPairs) {
            return "-1";
        }

        // --------------------------------------------------------------
        // 3️⃣ Fill the remaining free pairs
        // --------------------------------------------------------------
        for (int k = 0; k < pairsNeededForZero; ++k) {
            int idx = freePairIndices.get(k);
            chars[idx] = '0';
            chars[n - idx - 1] = '0';
        }
        for (int k = pairsNeededForZero; k < freePairIndices.size(); ++k) {
            int idx = freePairIndices.get(k);
            chars[idx] = '1';
            chars[n - idx - 1] = '1';
        }

        // --------------------------------------------------------------
        // 4️⃣ Final validation
        // --------------------------------------------------------------
        int finalZero = count(chars, '0');
        int finalOne  = count(chars, '1');
        if (finalZero != a || finalOne != b) {
            return "-1";
        }

        return new String(chars);
    }

    private static int count(char[] arr, char target) {
        int c = 0;
        for (char v : arr) if (v == target) c++;
        return c;
    }
}

import java.io.BufferedWriter;
import java.io.IOException;
import java.io.OutputStreamWriter;
import java.util.Scanner;

/**
 * Refactored solution for the palindrome‑construction problem.
 * <p>
 * The program reads several test cases. For each case it receives:
 * <ul>
 *   <li>the required number of '0' characters {@code a1}</li>
 *   <li>the required number of '1' characters {@code b1}</li>
 *   <li>a string {@code s} containing '0', '1' and '?'</li>
 * </ul>
 * It must replace every '?' so that the resulting string is a palindrome,
 * contains exactly {@code a1} zeros and {@code b1} ones, and returns the
 * constructed string; otherwise it returns {@code "-1"}.
 * </p>
 */
public class Main {

    /** Entry point – reads input, processes each test case and writes the answer. */
    public static void main(String[] args) throws IOException {
        /* Try‑with‑resources guarantees proper closing of I/O streams. */
        try (Scanner sc = new Scanner(System.in)) {
            BufferedWriter out = new BufferedWriter(new OutputStreamWriter(System.out));

            int testCases = sc.nextInt();
            for (int t = 0; t < testCases; t++) {
                out.write(processTestCase(sc));
                out.write('\n');
            }
            out.flush();
        }
    }

    /**
     * Processes a single test case.
     *
     * @param sc a {@link Scanner} positioned at the first token of the test case
     * @return the constructed palindrome or {@code "-1"} if it is impossible
     */
    private static String processTestCase(Scanner sc) {
        int requiredZeros = sc.nextInt();
        int requiredOnes = sc.nextInt();
        String input = sc.next();

        char[] chars = input.toCharArray();
        int length = chars.length;

        /* --------------------------------------------------------------
         * 1️⃣  Count existing 0‑s and 1‑s and verify that forced assignments
         *     (where one side of a symmetric pair is fixed) are consistent.
         * -------------------------------------------------------------- */
        int zeroCount = 0;
        int oneCount = 0;
        for (int i = 0; i < length; i++) {
            if (chars[i] == '0') {
                zeroCount++;
            } else if (chars[i] == '1') {
                oneCount++;
            }
        }

        for (int i = 0; i < length / 2; i++) {
            int j = length - 1 - i;
            char left = chars[i];
            char right = chars[j];

            // Conflict – two different fixed characters on symmetric positions
            if (left != '?' && right != '?' && left != right) {
                return "-1";
            }

            // One side is fixed, the other side is '?' → force the unknown side
            if (left == '?' || right == '?') {
                char forced = (left != '?') ? left : right;
                if (forced == '0') {
                    assign(chars, i, '0');
                    assign(chars, j, '0');
                    zeroCount += 2;
                } else { // forced == '1'
                    assign(chars, i, '1');
                    assign(chars, j, '1');
                    oneCount += 2;
                }
            }
        }

        /* --------------------------------------------------------------
         * 2️⃣  Fill the remaining symmetric '?' pairs.
         *     We prefer to place '0' when the remaining deficit of zeros is larger.
         * -------------------------------------------------------------- */
        for (int i = 0; i < length / 2; i++) {
            int j = length - 1 - i;
            if (chars[i] == '?' && chars[j] == '?') {
                if (requiredZeros - zeroCount > requiredOnes - oneCount) {
                    assign(chars, i, '0');
                    assign(chars, j, '0');
                    zeroCount += 2;
                } else {
                    assign(chars, i, '1');
                    assign(chars, j, '1');
                    oneCount += 2;
                }
            }
        }

        /* --------------------------------------------------------------
         * 3️⃣  Handle a possible middle character in odd‑length strings.
         * -------------------------------------------------------------- */
        if (length % 2 == 1 && chars[length / 2] == '?') {
            if (requiredZeros > zeroCount) {
                assign(chars, length / 2, '0');
                zeroCount++;
            } else {
                assign(chars, length / 2, '1');
                oneCount++;
            }
        }

        /* --------------------------------------------------------------
         * 4️⃣  Final validation.
         *     The constructed string must use exactly the required counts,
         *     be a palindrome and have no remaining '?' characters.
         * -------------------------------------------------------------- */
        if (zeroCount != requiredZeros || oneCount != requiredOnes) {
            return "-1";
        }

        for (int i = 0; i < length / 2; i++) {
            if (chars[i] != chars[length - 1 - i]) {
                return "-1";
            }
        }

        return new String(chars);
    }

    /**
     * Utility that writes a character into the given position of the array.
     *
     * @param arr  the character array
     * @param idx  the index to write to
     * @param ch   the character to store
     */
    private static void assign(char[] arr, int idx, char ch) {
        arr[idx] = ch;
    }
}

import java.io.IOException;
import java.util.Scanner;

/**
 * Solves the “binary string with unknown symbols” problem.
 *
 * The program reads multiple test cases, each consisting of:
 *   • a – remaining number of ‘1’s that must be placed,
 *   • b – remaining number of ‘0’s that must be placed,
 *   • a pattern containing ‘0’, ‘1’ and ‘?’.
 *
 * It prints the completed binary string or –1 if the case cannot be satisfied.
 *
 * The implementation has been refactored for readability:
 *   • Meaningful identifiers and short, focused methods.
 *   • Early returns instead of deep nesting.
 *   • try‑with‑resources for the Scanner.
 *   • Clear separation of the different logical steps.
 */
public class Main {

    public static void main(String[] args) {
        // Using try‑with‑resources guarantees the Scanner is closed automatically.
        try (Scanner scanner = new Scanner(System.in)) {
            int testCount = scanner.nextInt();

            while (testCount-- > 0) {
                // Order in the original input: first b (zeros), then a (ones)
                int b = scanner.nextInt();
                int a = scanner.nextInt();
                String pattern = scanner.next();

                // Convert the pattern to a mutable char array for in‑place modifications
                char[] chars = pattern.toCharArray();

                solveSingleCase(chars, a, b);
            }
        } catch (IOException e) {
            // In competitive programming we rarely need to handle this, but keeping it makes the code safer.
        }
    }

    /**
     * Handles one test case.
     *
     * @param chars mutable representation of the pattern,
     * @param initA required number of ‘1’s,
     * @param initB required number of ‘0’s.
     *              The method prints the result directly.
     */
    private static void solveSingleCase(char[] chars, int initA, int initB) {
        int n = chars.length;
        int a = initA;          // mutable counters
        int b = initB;

        // --------------------------------------------------------------
        // 1️⃣  Basic validation – length must match the total required symbols
        // --------------------------------------------------------------
        if (n != a + b) {
            System.out.println(-1);
            return;
        }

        // --------------------------------------------------------------
        // 2️⃣  If the length is odd, the centre character must be fixed
        // --------------------------------------------------------------
        if ((n & 1) == 1) {
            int mid = n / 2;
            if (chars[mid] == '?') {
                // Choose the centre symbol so that the parity of a or b matches.
                if ((a & 1) == 1) {                 // need an odd count of ‘1’s → centre should be ‘1’
                    a--;
                    chars[mid] = '1';
                } else {                            // otherwise centre should be ‘0’
                    b--;
                    chars[mid] = '0';
                }
            } else if (chars[mid] == '1') {
                a--;
            } else { // chars[mid] == '0'
                b--;
            }

            // After fixing the centre we must still have non‑negative remaining counts
            if (a < 0 || b < 0) {
                System.out.println(-1);
                return;
            }
        }

        // --------------------------------------------------------------
        // 3️⃣  After centre handling, both remaining counts must be even
        // --------------------------------------------------------------
        if ((a & 1) == 1 || (b & 1) == 1) {
            System.out.println(-1);
            return;
        }

        // --------------------------------------------------------------
        // 4️⃣  Resolve asymmetric pairs that are already fixed on one side
        // --------------------------------------------------------------
        boolean incompatible = false;
        for (int i = 0, j = n - 1; i < j; ++i, --j) {
            if (chars[i] == '?' && chars[j] != '?') {
                // Mirror the known side
                chars[i] = chars[j];
                consumeRemaining(chars[i], a, b);
            } else if (chars[i] != '?' && chars[j] == '?') {
                chars[j] = chars[i];
                consumeRemaining(chars[i], a, b);
            } else if (chars[i] != chars[j]) {
                // Fixed but differing characters → impossible
                incompatible = true;
                break;
            } else if (chars[i] == '1') {
                // Both are known ‘1’s → consume two ‘1’s
                a -= 2;
            } else if (chars[i] == '0') {
                // Both are known ‘0’s → consume two ‘0’s
                b -= 2;
            }
        }

        if (incompatible) {
            System.out.println(-1);
            return;
        }

        // --------------------------------------------------------------
        // 5️⃣  Fill remaining ‘?’ pairs
        // --------------------------------------------------------------
        for (int i = 0, j = n - 1; i < j; ++i, --j) {
            if (chars[i] == '?') {
                if (a > 0) {
                    // Prefer to place a ‘1’ pair if we still need them
                    a -= 2;
                    chars[i] = '1';
                    chars[j] = '1';
                } else {
                    b -= 2;
                    chars[i] = '0';
                    chars[j] = '0';
                }
            }
        }

        // --------------------------------------------------------------
        // 6️⃣  Final consistency check
        // --------------------------------------------------------------
        if (a != 0 || b != 0) {
            System.out.println(-1);
            return;
        }

        // --------------------------------------------------------------
        // 7️⃣  Output the resulting string
        // --------------------------------------------------------------
        System.out.println(new String(chars));
    }

    /**
     * Updates the remaining counters (a for ‘1’s, b for ‘0’s) after a symbol is placed.
     *
     * @param placedSymbol the symbol that has just been placed,
     * @param a            reference to the remaining ‘1’ count,
     * @param b            reference to the remaining ‘0’ count.
     */
    private static void consumeRemaining(char placedSymbol, int[] a, int[] b) {
        if (placedSymbol == '1') {
            a[0] -= 2;
        } else { // placedSymbol == '0'
            b[0] -= 2;
        }
    }
}

import java.util.Scanner;

/**
 * Refactored solution for the pattern completion problem.
 *
 * <p>Reads multiple test cases. For each test case it receives:
 *
 * <ul>
 *   <li>{@code a} – the required number of {@code '0'} characters,
 *   <li>{@code b} – the required number of {@code '1'} characters,
 *   <li>{@code pattern} – a string that may contain {@code '0'}, {@code '1'} and {@code '?'}.
 * </ul>
 *
 * <p>The program outputs a valid binary string that respects the given {@code a} and
 * {@code b} while honoring the constraints encoded in {@code pattern}. If no such
 * string exists, it prints {@code -1}.
 *
 * <p>The implementation is deliberately split into small, well‑named methods,
 * uses a tiny {@code Counter} helper to track remaining resources, and avoids
 * mutable shared state between methods. This makes the code easier to test,
 * maintain and extend.
 */
public class Solution {

    /** Simple container that holds how many '0's and '1's are still available. */
    private static final class Counter {
        final int zero; // remaining '0's
        final int one;  // remaining '1's

        Counter(int zero, int one) {
            this.zero = zero;
            this.one = one;
        }

        /** Consume {@code qty} copies of {@code bit} from the appropriate field. */
        void consume(char bit, int qty) {
            if (bit == '0') {
                zero -= qty;
            } else {
                one -= qty;
            }
        }

        /** Returns {@code true} if we still have at least {@code qty} copies of {@code bit}. */
        boolean enough(char bit, int qty) {
            return (bit == '0' && zero >= qty) || (bit == '1' && one >= qty);
        }
    }

    public static void main(String[] args) {
        try (Scanner sc = new Scanner(System.in)) {
            int T = sc.nextInt();                 // number of test cases
            while (T-- > 0) {
                int a = sc.nextInt();               // required '0's
                int b = sc.nextInt();               // required '1's
                String pattern = sc.next();         // pattern containing '0','1','?'
                solve(a, b, pattern);
            }
        }
    }

    /** Handles a single test case. */
    private static void solve(int requiredZero, int requiredOne, String pattern) {
        int n = pattern.length();
        char[] result = new char[n];
        boolean possible = true;

        // -----------------------------------------------------------------
        // Phase 1 – resolve already fixed symmetric positions.
        // -----------------------------------------------------------------
        Counter counter = new Counter(requiredZero, requiredOne);

        for (int i = 0; i < n / 2; i++) {
            char left = pattern.charAt(i);
            char right = pattern.charAt(n - 1 - i);

            // Asymmetric pair that cannot be fixed (e.g. "01" on both sides)
            if (left != '?' && right != '?' && left != right) {
                possible = false;
                break;
            }

            // Both sides are known and either equal or both are '?'
            if (left == right) {
                if (left != '?') {
                    placePair(result, i, n - 1 - i, left, counter);
                }
                // If both are '?' we defer to later phases.
            } else {
                // Exactly one side is known → copy it to the other side.
                char known = (left != '?') ? left : right;
                placePair(result, i, n - 1 - i, known, counter);
            }
        }

        if (!possible) {
            System.out.println(-1);
            return;
        }

        // -----------------------------------------------------------------
        // Phase 2 – fill symmetric '?' pairs.
        // -----------------------------------------------------------------
        for (int i = 0; i < n / 2; i++) {
            char left = pattern.charAt(i);
            char right = pattern.charAt(n - 1 - i);
            if (left == '?' && right == '?') {
                fillSymmetricPair(pattern, i, n - 1 - i, result, counter, possible);
            }
        }

        // -----------------------------------------------------------------
        // Phase 3 – handle the middle character when length is odd.
        // -----------------------------------------------------------------
        if (n % 2 == 1 && possible) {
            int mid = n / 2;
            char midChar = pattern.charAt(mid);
            if (midChar == '?') {
                possible = placeMiddleIfNeeded(result, mid, counter, possible);
            } else {
                placeSingle(result, mid, midChar, counter);
            }
        }

        // -----------------------------------------------------------------
        // Final validation – we must use exactly the requested numbers.
        // -----------------------------------------------------------------
        if (!possible || counter.zero != 0 || counter.one != 0) {
            possible = false;
        }

        if (!possible) {
            System.out.println(-1);
            return;
        }

        // Any leftover '?' that were never filled are simply copied from the pattern.
        for (int i = 0; i < n; i++) {
            if (result[i] == 0) {
                result[i] = pattern.charAt(i) == '?' ? '0' : pattern.charAt(i);
            }
        }

        System.out.println(new String(result));
    }

    /** Places a pair of identical bits at the given indices and updates the counter. */
    private static void placePair(char[] out, int i, int j, char bit, Counter counter) {
        out[i] = bit;
        out[j] = bit;
        counter.consume(bit, 2);
    }

    /** Handles a symmetric pair of '?' (both positions are '?') and decides which bit to insert. */
    private static void fillSymmetricPair(String pattern, int i, int j,
                                            char[] out, Counter counter,
                                            boolean[] possible) {
        // Prefer using '1' if we still have capacity, otherwise fall back to '0'.
        if (counter.enough('1', 2)) {
            out[i] = out[j] = '1';
            counter.consume('1', 2);
        } else if (counter.enough('0', 2)) {
            out[i] = out[j] = '0';
            counter.consume('0', 2);
        } else {
            possible[0] = false;          // not enough resources left
        }
    }

    /** Places a single bit in the middle position if it is still '?'. */
    private static boolean placeMiddleIfNeeded(char[] out, int mid, Counter counter,
                                                boolean[] possible) {
        if (counter.enough('0', 1)) {
            out[mid] = '0';
            counter.consume('0', 1);
            return true;
        }
        if (counter.enough('1', 1)) {
            out[mid] = '1';
            counter.consume('1', 1);
            return true;
        }
        possible[0] = false;
        return false;
    }

    /** Places a single known bit at the given index and consumes one count. */
    private static void placeSingle(char[] out, int i, char bit, Counter counter) {
        out[i] = bit;
        counter.consume(bit, 1);
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

/**
 * Solution for the “Palindrome with Fixed Symbols” problem.
 *
 * <p>
 *   The task is to replace each '?' in the given string with a '0' or '1' such that
 *   the resulting string is a palindrome and exactly {@code a} zeros and {@code b}
 *   ones remain to be placed. If it is impossible, the program prints {@code -1}.
 * </p>
 *
 * <p>Refactored for readability, testability and maintainability.</p>
 */
public class Main {

    /** Input buffer used by {@link FastScanner}. */
    private static final FastScanner FS = new FastScanner();

    /** Output buffer – prints all answers at the end of processing. */
    private static final StringBuilder OUT = new StringBuilder();

    /** --------------------------------------------------------------
     *  Entry point
     *  -------------------------------------------------------------- */
    public static void main(String[] args) throws IOException {
        int t = FS.nextInt();
        while (t-- > 0) {
            solveCase();
        }
        System.out.print(OUT.toString());
    }

    /** --------------------------------------------------------------
     *  Solve a single test case.
     *  -------------------------------------------------------------- */
    private static void solveCase() {
        int requiredZeros = FS.nextInt();   // a
        int requiredOnes  = FS.nextInt();   // b
        char[] chars = FS.next().toCharArray();
        int n = chars.length;

        // First fill symmetrical positions with known partners
        fillSymmetricParts(chars, requiredZeros, requiredOnes);

        // After symmetric filling, we may still have positions marked with '?'
        // (pairs of '?' or a single centre character). Assign concrete values.
        if (!assignRemaining(chars, requiredZeros, requiredOnes)) {
            OUT.append(-1).append('\n');
            return;
        }

        // At this point all positions are fixed and the counts must be exhausted.
        if (requiredZeros != 0 || requiredOnes != 0) {
            OUT.append(-1).append('\n');
            return;
        }

        // The constructed string is guaranteed to be a palindrome by construction,
        // but a final sanity check is cheap and keeps the logic defensive.
        if (!isPalindrome(chars)) {
            OUT.append(-1).append('\n');
            return;
        }

        OUT.append(chars).append('\n');
    }

    /** --------------------------------------------------------------
     *  Replace '?' with the character that appears on its symmetric side.
     *  If both sides are '?', they are left untouched for later processing.
     *  -------------------------------------------------------------- */
    private static void fillSymmetricParts(char[] arr, int& zeros, int& ones) {
        int left = 0, right = arr.length - 1;

        while (left <= right) {
            if (left == right) {
                // centre of an odd‑length string
                if (arr[left] == '?') {
                    // centre must be filled later based on remaining counts
                    break;
                }
                // fixed centre – nothing to do
                left++;
                right--;
                continue;
            }

            char lc = arr[left];
            char rc = arr[right];

            // Both positions already known – only check consistency
            if (lc != '?' && rc != '?') {
                // they must already be equal (guaranteed by earlier steps)
                left++;
                right--;
                continue;
            }

            // Exactly one side is known → propagate it
            if (lc != '?') {
                if (rc == '?') {
                    arr[right] = lc;
                    consume(lc, zeros, ones);
                }
            } else { // rc != '?'
                if (lc == '?') {
                    arr[left] = rc;
                    consume(rc, zeros, ones);
                }
            }
            left++;
            right--;
        }
    }

    /** --------------------------------------------------------------
     *  Assign values to the remaining '?' positions.
     *
     *  @return {@code true} if all remaining positions could be filled without
     *          violating the required counts.
     *  -------------------------------------------------------------- */
    private static boolean assignRemaining(char[] arr, int& zeros, int& ones) {
        int left = 0;
        int right = arr.length - 1;

        while (left <= right) {
            if (left == right) { // centre element
                if (arr[left] == '?') {
                    if (zeros > 0) {
                        arr[left] = '0';
                        zeros--;
                    } else if (ones > 0) {
                        arr[left] = '1';
                        ones--;
                    } else {
                        return false; // nothing left to assign
                    }
                }
                break;
            }

            char lc = arr[left];
            char rc = arr[right];

            if (lc == '?' && rc == '?') {
                // Both are placeholders – decide which value fits the remaining budget
                if (zeros >= 2) {
                    arr[left] = arr[right] = '0';
                    zeros -= 2;
                } else if (ones >= 2) {
                    arr[left] = arr[right] = '1';
                    ones -= 2;
                } else {
                    return false; // cannot place a pair
                }
            } else if (lc == '?') {
                // rc is known – copy it
                arr[left] = rc;
                consume(rc, zeros, ones);
            } else if (rc == '?') {
                // lc is known – copy it
                arr[right] = lc;
                consume(lc, zeros, ones);
            } // else both are already determined – nothing to do

            left++;
            right--;
        }

        return true;
    }

    /** --------------------------------------------------------------
     *  Adjust the remaining count of zeros / ones after a concrete char is placed.
     *  -------------------------------------------------------------- */
    private static void consume(char ch, int& zeros, int& ones) {
        if (ch == '0') {
            zeros--;
        } else if (ch == '1') {
            ones--;
        }
        // Defensive: negative numbers will be detected later.
    }

    /** --------------------------------------------------------------
     *  Simple palindrome verification – O(n).
     *  -------------------------------------------------------------- */
    private static boolean isPalindrome(char[] arr) {
        int i = 0, j = arr.length - 1;
        while (i < j) {
            if (arr[i] != arr[j]) {
                return false;
            }
            i++;
            j--;
        }
        return true;
    }

    /** --------------------------------------------------------------
     *  Very small wrapper around {@link BufferedReader} that supplies
     *  token‑based reading. It is deliberately kept tiny to avoid unnecessary
     *  dependencies.
     *  -------------------------------------------------------------- */
    private static final class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner() {
            this.br = new BufferedReader(new InputStreamReader(System.in));
        }

        /** Read the next token. */
        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.StringTokenizer;

/**
 * Refactored solution for the problem.
 * Improves readability, maintainability and follows modern Java practices.
 */
public class Main {

    /** Symbol used for an unknown character in the input pattern. */
    private static final char QUESTION = '?';
    /** Symbol for a zero. */
    private static final char ZERO = '0';
    /** Symbol for a one. */
    private static final char ONE = '1';

    /** Entry point. */
    public static void main(String[] args) {
        try (FastScanner scanner = new FastScanner();
             PrintWriter out = new PrintWriter(System.out)) {

            int testCount = scanner.nextInt();
            for (int tc = 0; tc < testCount; ++tc) {
                solve(scanner, out);
            }
        }
    }

    /**
     * Solves a single test case.
     *
     * @param in  scanner that reads the input
     * @param out writer to which the result is printed
     */
    private static void solve(FastScanner in, PrintWriter out) {
        /* --------------------------------------------------------------
         * 1. Read input values.
         * -------------------------------------------------------------- */
        int targetZero = in.nextInt();   // required number of '0's
        int targetOne  = in.nextInt();   // required number of '1's
        String pattern = in.next();      // the pattern to fill
        int length = pattern.length();
        char[] chars = pattern.toCharArray();

        /* --------------------------------------------------------------
         * 2. Track how many zeros and ones have already been placed.
         * -------------------------------------------------------------- */
        int placedZero = 0;
        int placedOne  = 0;
        boolean possible = true;

        /* --------------------------------------------------------------
         * 3. Middle character handling for odd length strings.
         * -------------------------------------------------------------- */
        if (length % 2 == 1) {
            int mid = length / 2;
            if ((targetZero & 1) == 1) {                // we need a zero at the centre
                if (chars[mid] == ONE) {
                    possible = false;
                } else if (chars[mid] == QUESTION) {
                    chars[mid] = ZERO;
                    placedZero++;                       // only one zero added here
                }
            } else {                                     // we need a one at the centre
                if (chars[mid] == ZERO) {
                    possible = false;
                } else if (chars[mid] == QUESTION) {
                    chars[mid] = ONE;
                    placedOne++;                        // only one one added here
                }
            }
        }

        // Two odd remainders cannot be satisfied together.
        if ((targetZero & 1) == 1 && (targetOne & 1) == 1) {
            possible = false;
        }

        /* --------------------------------------------------------------
         * 4. Resolve symmetric positions.
         * -------------------------------------------------------------- */
        for (int left = 0, right = length - 1; left < right; ++left, --right) {
            char leftChar = chars[left];
            char rightChar = chars[right];

            if (leftChar != QUESTION && rightChar != QUESTION) {
                // Both sides are known – they must match.
                if (leftChar != rightChar) {
                    possible = false;
                    break;
                } else {
                    // Count the pair (two characters) for the final totals.
                    if (leftChar == ONE) {
                        placedOne += 2;
                    } else {
                        placedZero += 2;
                    }
                }
            } else if ((leftChar == QUESTION) ^ (rightChar == QUESTION)) {
                // Exactly one side is unknown – mirror the known side.
                if (leftChar == QUESTION) {
                    chars[left] = rightChar;
                } else {
                    chars[right] = leftChar;
                }
                // Count the newly determined pair.
                if (chars[left] == ONE) {
                    placedOne += 2;
                } else {
                    placedZero += 2;
                }
            } else {
                // Both are QUESTION – they will be handled later.
            }
        }

        if (!possible) {
            out.println(-1);
            return;
        }

        /* --------------------------------------------------------------
         * 5. Verify that we have not exceeded the allowed quotas.
         * -------------------------------------------------------------- */
        if (placedZero > targetZero || placedOne > targetOne) {
            possible = false;
        }

        /* --------------------------------------------------------------
         * 6. Fill the remaining '?' pairs.
         * -------------------------------------------------------------- */
        int remainingZero = targetZero - placedZero;
        int remainingOne  = targetOne  - placedOne;

        // Remaining amounts must be non‑negative and even.
        if (remainingZero < 0 || remainingOne < 0 ||
            (remainingZero & 1) != 0 || (remainingOne & 1) != 0) {
            possible = false;
        } else {
            for (int i = 0, j = length - 1; i < j; ++i, --j) {
                if (chars[i] == QUESTION && chars[j] == QUESTION) {
                    if (remainingZero >= 2) {
                        chars[i] = chars[j] = ZERO;
                        remainingZero -= 2;
                    } else {
                        chars[i] = chars[j] = ONE;
                        remainingOne -= 2;
                    }
                }
            }
        }

        /* --------------------------------------------------------------
         * 7. Final validation before outputting the result.
         * -------------------------------------------------------------- */
        if (!possible || remainingZero != 0 || remainingOne != 0) {
            out.println(-1);
            return;
        }

        /* --------------------------------------------------------------
         * 8. Print the completed string.
         * -------------------------------------------------------------- */
        out.print(String.valueOf(chars));
        out.println();
    }

    /** Simple fast scanner for competitive‑programming style input. */
    static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

/**
 * Reads several test cases. For each case it receives:
 *   - two integers a and b  (the required number of '0's and '1's)
 *   - a string consisting of '0', '1' and '?'.
 *
 * The task is to replace every '?' with either '0' or '1' so that
 *   1. the whole string becomes a palindrome,
 *   2. the final string contains exactly a '0's and b '1's,
 *   3. the transformation is possible.
 *
 * If it is impossible the program prints -1, otherwise it prints the
 * resulting palindrome.
 *
 * The implementation is deliberately split into small, well‑named
 * methods to improve readability and maintainability.
 */
public class ABPalindrome {

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringBuilder output = new StringBuilder();

        int testCases = Integer.parseInt(br.readLine().trim());

        while (testCases-- > 0) {
            int[] ab = parseInts(br.readLine());
            int requiredZeros = ab[0];
            int requiredOnes = ab[1];

            char[] pattern = br.readLine().toCharArray();

            boolean possible = solve(pattern, requiredZeros, requiredOnes);
            output.append(possible ? new String(pattern) : "-1").append('\n');
        }

        System.out.print(output.toString());
    }

    /** Simple helper that extracts the two integers from a line. */
    private static int[] parseInts(String line) {
        StringTokenizer st = new StringTokenizer(line);
        return new int[] {
                Integer.parseInt(st.nextToken()),
                Integer.parseInt(st.nextToken())
        };
    }

    /**
     * Attempts to fill all '?' characters in {@code pattern} so that:
     *   • the string becomes a palindrome,
     *   • exactly {@code zeros} '0's and {@code ones} '1's are used,
     *   • no constraints are violated.
     *
     * @return {@code true} if a valid filling exists, {@code false} otherwise.
     */
    private static boolean solve(char[] pattern, int zeros, int ones) {
        final int length = pattern.length;

        /* --------------------------------------------------------------
         * 1️⃣  Consume the already fixed digits and validate the counts.
         * -------------------------------------------------------------- */
        for (char c : pattern) {
            if (c == '0') zeros--;
            else if (c == '1') ones--;
        }
        if (zeros < 0 || ones < 0) {
            return false;                     // more fixed digits than allowed
        }

        /* --------------------------------------------------------------
         * 2️⃣  Resolve mirrored pairs where one side is already known.
         * -------------------------------------------------------------- */
        for (int i = 0; i < length / 2; i++) {
            int j = length - 1 - i;
            char left = pattern[i];
            char right = pattern[j];

            // contradictory fixed characters → impossible
            if (left != '?' && right != '?' && left != right) {
                return false;
            }

            // one side is fixed, the other is '?' → mirror the fixed digit
            if (left == '?' && right != '?') {
                if (!placeDigit(pattern, i, right, zeros, ones)) {
                    return false;
                }
            } else if (right == '?' && left != '?') {
                if (!placeDigit(pattern, j, left, zeros, ones)) {
                    return false;
                }
            }
        }

        /* --------------------------------------------------------------
         * 3️⃣  Fill the remaining '?' positions (including the centre
         *     for odd‑length strings) using the still‑available digits.
         * -------------------------------------------------------------- */
        for (int i = 0; i <= length / 2; i++) {
            int j = length - 1 - i;
            if (i > j) break;                     // safety guard
            if (pattern[i] != '?') continue;      // already resolved

            if (i == j) {                           // centre character
                if (zeros >= 1) {
                    pattern[i] = '0';
                    zeros--;
                } else if (ones >= 1) {
                    pattern[i] = '1';
                    ones--;
                } else {
                    return false;
                }
            } else {                                 // a symmetric pair
                if (zeros >= 2) {
                    pattern[i] = pattern[j] = '0';
                    zeros -= 2;
                } else if (ones >= 2) {
                    pattern[i] = pattern[j] = '1';
                    ones -= 2;
                } else {
                    return false;
                }
            }
        }

        /* --------------------------------------------------------------
         * 4️⃣  All constraints satisfied only when we exactly used the
         *     required numbers of '0' and '1'.
         * -------------------------------------------------------------- */
        return zeros == 0 && ones == 0;
    }

    /**
     * Places {@code digit} at position {@code idx} in {@code arr},
     * decrementing the appropriate counter (zeros/ones). Returns false
     * if the respective counter is already exhausted.
     */
    private static boolean placeDigit(char[] arr, int idx, char digit,
                                      int zeros, int ones) {
        if (digit == '0') {
            if (zeros <= 0) return false;
            arr[idx] = '0';
            return --zeros > 0;
        }
        // digit == '1'
        if (ones <= 0) return false;
        arr[idx] = '1';
        return --ones > 0;
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

/**
 * Reads multiple test cases and, for each case, tries to build a palindrome
 * from the given pattern while respecting a fixed number of '0' and '1' digits.
 * If it is impossible, the method returns "-1".
 *
 * <p>Design goals of this refactor:
 *
 * <ul>
 *   <li>Clear naming and separation of concerns (input handling, validation,
 *       palindrome construction).
 *   <li>Small, single‑responsibility methods that are easier to test and
 *       maintain.
 *   <li>Early returns and explicit error messages instead of scattered magic
 *       values.
 *   <li>Use of {@link BufferedReader} for faster input handling.
 *   <li>Constant definitions for reusable strings and error codes.
 * </ul>
 */
public class Main {

    /** Error message returned when a configuration cannot be satisfied. */
    private static final String IMPOSSIBLE = "-1";

    /** Prefix used for console prompts (kept for compatibility with original I/O). */
    private static final String INPUT_PROMPT = "";

    public static void main(String[] args) throws IOException {
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in))) {
            int testCaseCount = Integer.parseInt(readToken(br));

            for (int t = 0; t < testCaseCount; t++) {
                int requiredZeros = Integer.parseInt(readToken(br));
                int requiredOnes = Integer.parseInt(readToken(br));
                String pattern = readToken(br);               // pattern may contain '0','1','?'

                System.out.println(solvePattern(requiredZeros, requiredOnes, pattern));
            }
        }
    }

    /**
     * Orchestrates the whole solving process for one test case.
     *
     * @param requiredZeros number of '0' characters that must be placed
     * @param requiredOnes  number of '1' characters that must be placed
     * @param pattern       input pattern containing '0','1','?'
     * @return the resulting palindrome string or {@link #IMPOSSIBLE}
     */
    private static String solvePattern(int requiredZeros, int requiredOnes, String pattern) {
        char[] chars = pattern.toCharArray();

        // First, collapse the pattern by matching symmetric positions.
        if (!collapseSymmetricPairs(chars, requiredZeros, requiredOnes)) {
            return IMPOSSIBLE;
        }

        // Fill the remaining '?' pairs (or single middle character) respecting the counts.
        if (!fillRemainingPositions(chars, requiredZeros, requiredOnes)) {
            return IMPOSSIBLE;
        }

        return new String(chars);
    }

    /**
     * Walks from both ends of the pattern towards the centre.
     * If a pair differs and neither side is a wildcard ('?'), the pattern is invalid.
     * If one side is a wildcard, it is filled with the character from the opposite side,
     * consuming the corresponding resource count.
     *
     * @return {@code true} if the collapse succeeded and never led to a negative count,
     *         {@code false} otherwise.
     */
    private static boolean collapseSymmetricPairs(char[] chars, int zeros, int ones) {
        int left = 0;
        int right = chars.length - 1;

        while (left < right) {
            char leftChar = chars[left];
            char rightChar = chars[right];

            if (leftChar != rightChar) {
                // Asymmetric pair – must be resolvable via a '?'.
                if (leftChar == '?' || rightChar == '?') {
                    fillAsymmetricPair(leftChar, rightChar, chars, left, right, zeros, ones);
                } else {
                    // Impossible to make palindrome.
                    return false;
                }
            }
            left++;
            right--;
        }

        // After collapsing, verify that we didn't overspend our quota.
        return zeros >= 0 && ones >= 0;
    }

    /**
     * Handles a pair where exactly one character is a wildcard.
     * The wildcard is replaced by the known character,
     * and the corresponding count (zero or one) is decremented.
     */
    private static void fillAsymmetricPair(char left, char right, char[] chars,
                                           int leftIdx, int rightIdx,
                                           int[] zeros, int[] ones) {
        if (left == '?') {
            chars[leftIdx] = chars[rightIdx];
            decrementCount(chars[rightIdx], zeros, ones);
        } else {
            chars[rightIdx] = chars[leftIdx];
            decrementCount(chars[leftIdx], zeros, ones);
        }
    }

    /**
     * Decrements the appropriate counter based on the character placed.
     *
     * @param ch  the character that is placed ('0' or '1')
     * @param zeros  mutable zero count
     * @param ones   mutable one count
     */
    private static void decrementCount(char ch, int[] zeros, int[] ones) {
        if (ch == '0') {
            zeros[0]--;
        } else {
            ones[0]--;
        }
    }

    /**
     * Fills all remaining '?' pairs (or the centre character when the length is odd)
     * using the leftover {@code zeros} and {@code ones}.  Returns {@code false}
     * if we run out of resources or encounter an illegal state.
     */
    private static boolean fillRemainingPositions(char[] chars, int[] zeros, int[] ones) {
        int left = 0;
        int right = chars.length - 1;

        // Pair‑wise filling.
        while (left < right) {
            if (chars[left] == '?' && chars[right] == '?') {
                if (zeros[0] >= 2) {
                    chars[left] = chars[right] = '0';
                    zeros[0] -= 2;
                } else if (ones[0] >= 2) {
                    chars[left] = chars[right] = '1';
                    ones[0] -= 2;
                } else {
                    return false; // Not enough characters left.
                }
            }
            left++;
            right--;
        }

        // Middle character (only when length is odd).
        if (chars.length % 2 == 1) {
            int mid = chars.length / 2;
            if (chars[mid] == '?') {
                if (zeros[0] >= 1) {
                    chars[mid] = '0';
                    zeros[0]--;
                } else if (ones[0] >= 1) {
                    chars[mid] = '1';
                    ones[0]--;
                } else {
                    return false;
                }
            }
        }

        // Final sanity check – we must have consumed exactly the required counts.
        return zeros[0] == 0 && ones[0] == 0;
    }

    /**
     * Utility method that reads the next token from a {@link BufferedReader}
     * using a {@link StringTokenizer}.  Keeps the parsing logic isolated for clarity.
     */
    private static String readToken(BufferedReader br) throws IOException {
        String line = br.readLine();
        if (line == null) {
            throw new IOException("Unexpected end of input");
        }
        // The original code used whitespace separation; we tokenise the line.
        StringTokenizer st = new StringTokenizer(line);
        if (!st.hasMoreTokens()) {
            return ""; // Should not happen with the given input format.
        }
        return st.nextToken();
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.ArrayList;
import java.util.List;

/**
 * Refactored version of {@code abpalindrome2}.
 *
 * <p>This implementation separates the logic of handling a single test case
 * into dedicated methods, uses expressive naming, and avoids duplicated
 * initialization code.  All I/O is performed through a {@link BufferedReader}
 * for consistency with the original program.</p>
 */
public class Main {

    /** Entry point – reads all test cases and prints results. */
    public static void main(String[] args) throws IOException {
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(System.in))) {
            int testCases = Integer.parseInt(reader.readLine());

            List<String> results = new ArrayList<>();

            for (int t = 0; t < testCases; t--) {
                results.add(processSingleTestCase(reader));
            }

            // Output each result on its own line.
            results.forEach(System.out::println);
        }
    }

    /**
     * Processes one test case.
     *
     * @param reader a buffered reader positioned after the previous result
     *               (or at the start of input)
     * @return a string containing the answer for this case ("-1" if impossible)
     */
    private static String processSingleTestCase(BufferedReader reader) throws IOException {
        // ----- 1. Read parameters -------------------------------------------------
        StringTokenizer tokenizer = new StringTokenizer(reader.readLine());
        int targetZeros = Integer.parseInt(tokenizer.nextToken());
        int targetOnes  = Integer.parseInt(tokenizer.nextToken());

        char[] chars = reader.readLine().toCharArray();
        int length = chars.length;

        // ----- 2. Resolve forced symmetric assignments -------------------------
        if (!resolveSymmetricPairs(chars)) {
            return "-1";
        }

        // ----- 3. Count already placed zeros and ones ---------------------------
        int placedZeros = countOccurrences(chars, '0');
        int placedOnes  = countOccurrences(chars, '1');

        int remainingZeros = targetZeros - placedZeros;
        int remainingOnes  = targetOnes  - placedOnes;

        // ----- 4. Allocate the remaining '?' characters -------------------------
        if (!allocateRemaining(chars, remainingZeros, remainingOnes)) {
            return "-1";
        }

        // ----- 5. Validate final counts -----------------------------------------
        if (remainingZeros != 0 || remainingOnes != 0) {
            return "-1";
        }

        // ----- 6. Build answer ----------------------------------------------------
        return new String(chars);
    }

    /**
     * Resolves all forced placements caused by symmetry and checks for contradictions.
     *
     * <p>If a character at position {@code i} is known while its symmetric counterpart
     * is {@code '?'}, the unknown is filled with the known value.  If both are known
     * but differ, the test case is impossible.</p>
     *
     * @return {@code true} if the string can still be turned into a palindrome,
     *         {@code false} if a contradiction was found.
     */
    private static boolean resolveSymmetricPairs(char[] arr) {
        int n = arr.length;
        for (int i = 0; i < n; i++) {
            int mirror = n - i - 1;
            char current = arr[i];

            if (current == '?') {
                // When the current cell is unknown, just wait for the mirror to decide.
                continue;
            }

            if (arr[mirror] == '?') {
                // Mirror is unknown → fill it with the same value.
                arr[mirror] = current;
            } else if (arr[mirror] != current) {
                // Both are known but different → not a palindrome.
                System.out.println(-1);
                return false;
            }
        }
        return true;
    }

    /**
     * Counts how many times a given character appears in the array.
     */
    private static int countOccurrences(char[] arr, char target) {
        int cnt = 0;
        for (char c : arr) {
            if (c == target) {
                cnt++;
            }
        }
        return cnt;
    }

    /**
     * Fills the remaining {@code '?'} cells so that the total number of zeros
     * and ones matches the required {@code targetZeros} and {@code targetOnes}.
     *
     * <p>The method iterates over symmetric pairs (and possibly the centre cell)
     * and greedily places zeros whenever two additional zeros are still needed.
     * If that is no longer possible, it places ones.</p>
     *
     * @return {@code true} if the allocation succeeded and the final counts are exact,
     *         {@code false} otherwise (e.g., negative remaining counts).
     */
    private static boolean allocateRemaining(char[] arr, int remainingZeros, int remainingOnes) {
        int n = arr.length;

        // ----- Fill symmetric pairs ------------------------------------------------
        for (int i = 0; i < n / 2; i++) {
            int mirror = n - i - 1;
            if (arr[i] != '?') {
                continue; // already resolved by resolveSymmetricPairs
            }

            if (remainingZeros >= 2) {
                arr[i] = arr[mirror] = '0';
                remainingZeros -= 2;
            } else if (remainingOnes >= 2) {
                arr[i] = arr[mirror] = '1';
                remainingOnes -= 2;
            } else {
                // Not enough of either digit to fill a pair → impossible.
                return false;
            }
        }

        // ----- If the length is odd, possibly fill the centre cell -----------------
        if (n % 2 == 1) {
            int centre = n / 2;
            if (arr[centre] == '?') {
                if (remainingZeros > 0) {
                    arr[centre] = '0';
                    remainingZeros--;
                } else if (remainingOnes > 0) {
                    arr[centre] = '1';
                    remainingOnes--;
                } else {
                    // No remaining digit to place at the centre → impossible.
                    return false;
                }
            }
        }

        // ----- Final sanity check ---------------------------------------------------
        return remainingZeros == 0 && remainingOnes == 0;
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.Scanner;

/**
 * Refactored solution for the Codeforces problem that builds a palindrome
 * with a given amount of '0' and '1' characters.
 *
 * The implementation has been split into small, well‑named private methods,
 * unused imports and helper classes have been removed, and the code now
 * follows common Java naming conventions and best‑practice patterns.
 */
public class Main {

    /** Scanner used to read all input from STDIN. */
    private static Scanner scanner;

    /** Entry point of the program. */
    public static void main(String[] args) throws IOException {
        // Use a single shared scanner for the whole lifetime of the program.
        scanner = new Scanner(new BufferedReader(new InputStreamReader(System.in)));

        int testCases = scanner.nextInt();
        while (testCases-- > 0) {
            solve();
        }

        // Close the scanner to release system resources.
        scanner.close();
    }

    /**
     * Handles a single test case:
     * <ul>
     *   <li>Reads the required number of ‘0’ and ‘1’ characters.</li>
     *   <li>Reads the pattern that may contain ‘?’.</li>
     *   <li>Transforms the pattern into a palindrome.</li>
     *   <li>Fills the remaining ‘?’ positions.</li>
     *   <li>Prints the resulting string or -1 if impossible.</li>
     * </ul>
     */
    private static void solve() {
        int requiredZeros = scanner.nextInt();   // a
        int requiredOnes  = scanner.nextInt();   // b
        String pattern = scanner.next();         // may contain '0', '1', '?'

        char[] chars = pattern.toCharArray();
        int length = chars.length;

        // 1️⃣ Ensure the string can become a palindrome by mirroring '?' positions.
        enforcePalindrome(chars);

        // 2️⃣ Count how many '0' and '1' are still needed.
        int remainingZeros = requiredZeros;
        int remainingOnes  = requiredOnes;
        for (char c : chars) {
            if (c == '0') {
                remainingZeros--;
            } else if (c == '1') {
                remainingOnes--;
            }
        }

        // 3️⃣ Fill the remaining '?' positions.
        boolean filled = fillRemainingPositions(chars, remainingZeros, remainingOnes);

        // 4️⃣ Validate the final string.
        if (filled && isPalindrome(chars) && remainingZeros == 0 && remainingOnes == 0) {
            System.out.println(new String(chars));
        } else {
            System.out.println(-1);
        }
    }

    /** Mirrors each '?' with its symmetric counterpart to guarantee a palindrome. */
    private static void enforcePalindrome(char[] arr) {
        int left = 0;
        int right = arr.length - 1;
        while (left <= right) {
            if (arr[left] == '?') {
                arr[left] = arr[right];
            }
            if (arr[right] == '?') {
                arr[right] = arr[left];
            }
            left++;
            right--;
        }
    }

    /**
     * Attempts to assign the remaining '?' characters with '0' or '1' so that
     * the exact required counts are satisfied.
     *
     * @param arr       mutable character array (already partially filled)
     * @param zerosLeft number of '0' characters still needed
     * @param onesLeft  number of '1' characters still needed
     * @return {@code true} if a valid assignment exists, {@code false} otherwise
     */
    private static boolean fillRemainingPositions(char[] arr,
                                                  int zerosLeft,
                                                  int onesLeft) {
        int mid = (arr.length - 1) / 2;   // inclusive index of the left half
        for (int i = 0; i <= mid; i++) {
            int j = arr.length - 1 - i;   // symmetric index
            if (arr[i] == '?') {
                if (zerosLeft > onesLeft) {
                    arr[i] = arr[j] = '0';
                    zerosLeft -= (i == j) ? 1 : 2;
                } else {
                    arr[i] = arr[j] = '1';
                    onesLeft -= (i == j) ? 1 : 2;
                }
            }
        }
        return zerosLeft == 0 && onesLeft == 0 && isPalindrome(arr);
    }

    /** Checks whether the character array forms a palindrome. */
    private static boolean isPalindrome(char[] arr) {
        int left = 0;
        int right = arr.length - 1;
        while (left < right) {
            if (arr[left] != arr[right]) {
                return false;
            }
            left++;
            right--;
        }
        return true;
    }
}

import java.io.*;
import java.util.*;

public class C1512 {

    public static void main(String[] args) throws IOException {
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in))) {
            StringBuilder out = new StringBuilder();
            int t = Integer.parseInt(br.readLine());
            for (int tc = 0; tc < t; ++tc) {
                out.append(solveCase(br)).append('\n');
            }
            System.out.print(out.toString());
        }
    }

    private static String solveCase(BufferedReader br) throws IOException {
        StringTokenizer st = new StringTokenizer(br.readLine());
        int a = Integer.parseInt(st.nextToken());
        int b = Integer.parseInt(st.nextToken());
        String pattern = br.readLine();

        int n = pattern.length();
        char[] chars = pattern.toCharArray();
        int[] op = new int[n];
        Arrays.fill(op, -1);

        int knownZeros = 0;
        int knownOnes = 0;

        // Resolve positions where the character is known
        for (int i = 0; i < n; ++i) {
            char c = chars[i];
            if (c != '?') {
                int val = c - '0';
                op[i] = val;
                if (val == 0) ++knownZeros;
                else ++knownOnes;
            } else {
                char opposite = chars[n - i - 1];
                if (opposite != '?') {
                    int val = opposite - '0';
                    op[i] = val;
                    if (val == 0) ++knownZeros;
                    else ++knownOnes;
                }
            }
        }

        int needZeros = a - knownZeros;
        int needOnes = b - knownOnes;
        boolean possible = true;

        // Fill the remaining -1 entries symmetrically
        for (int i = 0; i < n; ++i) {
            int j = n - i - 1;
            if (op[i] != -1) {
                continue; // already decided
            }

            if (op[j] != -1) {
                // counterpart already fixed
                op[i] = op[j];
                if (op[i] == 0) --needZeros;
                else --needOnes;
            } else {
                // both positions are still free
                if (i == j) { // middle position in odd length
                    if (needZeros > 0) {
                        op[i] = 0;
                        --needZeros;
                    } else if (needOnes > 0) {
                        op[i] = 1;
                        --needOnes;
                    } else {
                        possible = false;
                        break;
                    }
                } else {
                    // choose the digit that still has remaining quota
                    if (needZeros > needOnes) {
                        op[i] = 0;
                        op[j] = 0;
                        needZeros -= 2;
                    } else {
                        op[i] = 1;
                        op[j] = 1;
                        needOnes -= 2;
                    }
                }
            }
        }

        // Final validation
        if (!possible || needZeros != 0 || needOnes != 0) {
            return "-1";
        }

        // Ensure palindrome property (should hold by construction)
        for (int i = 0; i < n; ++i) {
            if (op[i] != op[n - i - 1]) {
                return "-1";
            }
        }

        // Build result string
        StringBuilder sb = new StringBuilder();
        for (int v : op) {
            sb.append(v);
        }
        return sb.toString();
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

/**
 * Refactored solution that checks whether a partially filled binary string can be
 * completed to a palindrome while respecting the required numbers of '0' and '1'.
 *
 * The logic is unchanged from the original implementation but is now organised
 * into small, easily‑testable methods and uses meaningful names.
 */
public class Main {

    /** Entry point – reads all test cases and prints the results. */
    public static void main(String[] args) throws IOException {
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in))) {
            StringTokenizer st = new StringTokenizer(br.readLine());
            int queries = Integer.parseInt(st.nextToken());

            StringBuilder out = new StringBuilder();
            for (int q = 0; q < queries; q++) {
                st = new StringTokenizer(br.readLine());
                int requiredZeros = Integer.parseInt(st.nextToken());
                int requiredOnes = Integer.parseInt(st.nextToken());

                char[] buf = br.readLine().toCharArray();
                String result = solveCase(requiredZeros, requiredOnes, buf);
                out.append(result).append('\n');
            }
            System.out.print(out.toString());
        }
    }

    /**
     * Attempts to fill the {@code char[]} so that the resulting string is a palindrome
     * and contains exactly {@code zeros} zeros and {@code ones} ones.
     *
     * @return The completed string, or "-1" if it is impossible.
     */
    private static String solveCase(int zeros, int ones, char[] chars) {
        int n = chars.length;
        int half = n / 2;

        // --------------------------------------------------------------------
        // 1️⃣  Resolve mismatches and initialise the counts (a = zeros, b = ones)
        // --------------------------------------------------------------------
        for (int i = 0; i < half; i++) {
            char left = chars[i];
            char right = chars[n - i - 1];

            if (left != '?' && right != '?' && left != right) {
                return "-1";                     // cannot form a palindrome
            }

            // At least one side is '?', so we can mirror the known character.
            if (left == '?' || right == '?') {
                if (left == '?') {
                    chars[i] = right;
                } else {
                    chars[n - i - 1] = left;
                }
                // Adjust the remaining budget depending on the character we just placed.
                if (chars[i] == '1') {
                    ones -= 2;
                } else {
                    zeros -= 2;
                }
            } else {
                // Both positions are already known and equal.
                if (chars[i] == '0') {
                    zeros -= 2;
                } else { // '1'
                    ones -= 2;
                }
            }
        }

        // --------------------------------------------------------------------
        // 2️⃣  Deal with the middle character (odd length strings)
        // --------------------------------------------------------------------
        if ((n & 1) == 1) { // odd length
            int mid = n / 2;
            char midChar = chars[mid];

            if (midChar != '?') {
                // Already fixed – just consume the corresponding count.
                if (midChar == '1') {
                    ones--;
                } else {
                    zeros--;
                }
            } else {
                // Choose the character that makes the remaining counts even.
                // The original code used the parity of `ones`; we keep that behaviour.
                if ((ones & 1) == 1) {
                    chars[mid] = '1';
                    ones--;
                } else {
                    chars[mid] = '0';
                    zeros--;
                }
            }
        }

        // After placing the middle character the remaining counts must be even.
        if ((zeros & 1) == 1 || (ones & 1) == 1) {
            return "-1";
        }

        // --------------------------------------------------------------------
        // 3️⃣  Fill the remaining '?' positions
        // --------------------------------------------------------------------
        for (int i = 0; i < half; i++) {
            if (chars[i] == '?') {
                if (zeros > 0) {
                    chars[i] = chars[n - i - 1] = '0';
                    zeros -= 2;
                } else if (ones > 0) {
                    chars[i] = chars[n - i - 1] = '1';
                    ones -= 2;
                }
            }
        }

        // If we overspent any budget, the configuration is invalid.
        if (zeros < 0 || ones < 0) {
            return "-1";
        }

        // --------------------------------------------------------------------
        // 4️⃣  Build the resulting string
        // --------------------------------------------------------------------
        return new String(chars);
    }
}

import java.io.*;
import java.util.*;

/**
 * Refactored solution that builds a palindrome with a given number of '0' and '1'
 * characters while preserving the original pattern.  The implementation is split
 * into small, single‑responsibility classes to improve readability and maintainability.
 */
public class Solution {

    /** Fast scanner that reads tokens from the input stream. */
    private static final class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner(InputStream source) {
            this.br = new BufferedReader(new InputStreamReader(source));
        }

        /** Makes sure a tokenizer is available; reads a line if needed. */
        private void ensureTokens() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                String line = br.readLine();
                if (line == null) {
                    st = null;                     // EOF
                } else {
                    st = new StringTokenizer(line);
                }
            }
        }

        int nextInt() throws IOException {
            ensureTokens();
            return Integer.parseInt(st.nextToken());
        }

        String nextString() throws IOException {
            ensureTokens();
            return st.nextToken();
        }
    }

    /** Encapsulates the algorithm that constructs a valid palindrome. */
    static class PalindromeBuilder {
        private final FastScanner scanner;
        private final PrintWriter out;

        PalindromeBuilder(FastScanner scanner, PrintWriter out) {
            this.scanner = scanner;
            this.out = out;
        }

        /**
         * Tries to build a palindrome using exactly {@code zeroCnt} zeros and
         * {@code oneCnt} ones while respecting the {@code pattern}.  Returns the
         * resulting string or "-1" if it is impossible.
         */
        String construct(int zeroCnt, int oneCnt, String pattern) throws IOException {
            char[] chars = pattern.toCharArray();
            int n = chars.length;
            int half = n / 2;

            // ---- Pass 1: resolve forced matches ---------------------------------
            for (int i = 0; i < half; i++) {
                int j = n - 1 - i;
                char left = chars[i];
                char right = chars[j];

                if (left != '?' && right != '?') {
                    if (left != right) {
                        return "-1";
                    }
                    // Both sides are fixed – consume the appropriate count
                    if (left == '0') {
                        zeroCnt -= 2;
                    } else {
                        oneCnt -= 2;
                    }
                } else if (left == '?' && right == '?') {
                    // Waiting for later – nothing to do now
                } else {
                    // Mirror the known character to the unknown side
                    if (left == '?') {
                        chars[i] = right;
                    } else {
                        chars[j] = left;
                    }
                    // Adjust counts according to the mirrored character
                    if (left == '0' || right == '0') {
                        zeroCnt -= 2;
                    } else {
                        oneCnt -= 2;
                    }
                }
            }

            // ---- Pass 2: fill remaining '?' pairs -------------------------------
            for (int i = 0; i < half; i++) {
                int j = n - 1 - i;
                if (chars[i] != '?') continue; // already fixed

                if (zeroCnt >= 2) {
                    chars[i] = chars[j] = '0';
                    zeroCnt -= 2;
                } else if (oneCnt >= 2) {
                    chars[i] = chars[j] = '1';
                    oneCnt -= 2;
                } else {
                    return "-1";
                }
            }

            // ---- Handle middle character for odd length -------------------------
            if (n % 2 == 1) {
                int mid = n / 2;
                if (chars[mid] == '?') {
                    if (zeroCnt > 0) {
                        chars[mid] = '0';
                        zeroCnt--;
                    } else if (oneCnt > 0) {
                        chars[mid] = '1';
                        oneCnt--;
                    } else {
                        return "-1";
                    }
                } else {
                    // already set by pass 1; consume its count
                    if (chars[mid] == '0') {
                        zeroCnt--;
                    } else {
                        oneCnt--;
                    }
                }
            }

            // ---- Final validation ------------------------------------------------
            if (zeroCnt != 0 || oneCnt != 0) {
                return "-1";
            }
            for (int i = 0; i < n; i++) {
                if (chars[i] != chars[n - 1 - i]) {
                    return "-1";
                }
            }

            return new String(chars);
        }
    }

    /** Program entry point. */
    public static void main(String[] args) throws Exception {
        // Execute on a dedicated thread with an enlarged stack to avoid
        // StackOverflowError on some judging environments.
        new Thread(() -> {
            try {
                runSolution();
            } catch (Exception e) {
                throw new RuntimeException(e);
            }
        }, "SolutionThread", 1 << 26).start();
    }

    /** Core driver that reads input, processes each test case and prints results. */
    private static void runSolution() throws Exception {
        FastScanner scanner = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)));

        int testCases = scanner.nextInt();
        PalindromeBuilder builder = new PalindromeBuilder(scanner, out);

        StringBuilder collected = new StringBuilder();
        for (int t = 0; t < testCases; t++) {
            int zeroNeeded = scanner.nextInt();
            int oneNeeded = scanner.nextInt();
            String pattern = scanner.nextString();

            String answer = builder.construct(zeroNeeded, oneNeeded, pattern);
            out.println(answer);
            collected.append(answer).append('\n');
        }

        out.flush();
    }
}

import java.util.Scanner;

/**
 * Utility that, for each test case, replaces the '?' characters in a binary string
 * so that the resulting string is a palindrome and contains exactly the required
 * number of '0' and '1' characters. If it is impossible, the program prints –1.
 *
 * The implementation is split into small, self‑documenting methods to improve
 * maintainability and make the algorithm easier to understand.
 */
public class RoughBackup {

    /** Scanner used for reading input – closed at the end of the program. */
    private static final Scanner SCANNER = new Scanner(System.in);

    public static void main(String[] args) throws Exception {
        int t = SCANNER.nextInt();

        while (t-- > 0) {
            solveCase();
        }

        SCANNER.close();
    }

    /** Handles a single test case. */
    private static void solveCase() {
        int requiredZero = SCANNER.nextInt();          // number of '0' needed
        int requiredOne  = SCANNER.nextInt();          // number of '1' needed
        String input      = SCANNER.next();            // string possibly containing '?'

        char[] chars = input.toCharArray();

        // 1. Fast‑fail when the initial amount of fixed 0/1 exceeds the quota.
        if (!isValidInitialCounts(chars, requiredZero, requiredOne)) {
            System.out.println("-1");
            return;
        }

        // 2. If the string already satisfies everything, print it.
        if (isAlreadyValidPalindrome(chars) && matchCounts(chars, requiredZero, requiredOne)) {
            System.out.println(new String(chars));
            return;
        }

        // 3. Fill the missing positions (the '?') respecting the palindrome constraint.
        if (!fillMissingPositions(chars, requiredZero, requiredOne)) {
            System.out.println("-1");
            return;
        }

        // 4. Final validation – counts must match and the result must be a palindrome.
        if (matchCounts(chars, requiredZero, requiredOne) && isPalindrome(chars)) {
            System.out.println(new String(chars));
        } else {
            System.out.println("-1");
        }
    }

    /** The current number of fixed '0'/'1' must not exceed the required amount. */
    private static boolean isValidInitialCounts(char[] arr, int rZero, int rOne) {
        int zero = count(arr, '0');
        int one  = count(arr, '1');
        return zero <= rZero && one <= rOne;
    }

    /** Checks that the string can become a palindrome without changing any fixed chars. */
    private static boolean isAlreadyValidPalindrome(char[] arr) {
        int l = 0, r = arr.length - 1;
        while (l < r) {
            if (arr[l] != '?' && arr[r] != '?' && arr[l] != arr[r]) {
                return false;               // contradictory pair
            }
            l++;
            r--;
        }
        return true;
    }

    /** Returns true when the current counts of 0 and 1 already equal the required ones. */
    private static boolean matchCounts(char[] arr, int rZero, int rOne) {
        int zero = count(arr, '0');
        int one  = count(arr, '1');
        return zero == rZero && one == rOne;
    }

    /** Simple utility to count occurrences of a character in an array. */
    private static int count(char[] arr, char target) {
        int cnt = 0;
        for (char c : arr) {
            if (c == target) cnt++;
        }
        return cnt;
    }

    /**
     * Fills all '?' characters so that the resulting string:
     *   • is a palindrome,
     *   • contains exactly {@code requiredZero} zeros and {@code requiredOne} ones.
     *
     * Returns false if it becomes impossible during the process.
     */
    private static boolean fillMissingPositions(char[] arr, int requiredZero, int requiredOne) {
        int zero = count(arr, '0');
        int one  = count(arr, '1');

        // ---- Pass 1: resolve forced assignments (only one side of a pair is '?') ----
        int left = 0, right = arr.length - 1;
        while (left <= right) {
            char lc = arr[left];
            char rc = arr[right];

            // contradictory fixed characters -> impossible
            if (lc != '?' && rc != '?' && lc != rc) {
                return false;
            }

            // one side is known, the other is '?' → decide the unknown side
            if (lc == '?' && rc != '?') {
                if (!assignIfCapacity(rc, requiredZero, requiredOne, zero, one, arr, left)) {
                    return false;
                }
            } else if (rc == '?' && lc != '?') {
                if (!assignIfCapacity(lc, requiredZero, requiredOne, zero, one, arr, right)) {
                    return false;
                }
            }

            left++;
            right--;
        }

        // ---- Pass 2: fill symmetric '?' pairs ----
        left = 0;
        right = arr.length - 1;
        while (left < right) {
            if (arr[left] == '?' && arr[right] == '?') {
                // Prefer a zero pair if we still need zeros; otherwise a one pair.
                if (zero + 2 <= requiredZero) {
                    arr[left] = arr[right] = '0';
                    zero += 2;
                } else if (one + 2 <= requiredOne) {
                    arr[left] = arr[right] = '1';
                    one += 2;
                } else {
                    return false;   // cannot satisfy the quota with remaining spots
                }
            }
            left++;
            right--;
        }

        // ---- Pass 3: middle character for odd‑length strings ----
        if (arr.length % 2 == 1 && arr[arr.length / 2] == '?') {
            if (zero < requiredZero) {
                arr[arr.length / 2] = '0';
                zero++;
            } else if (one < requiredOne) {
                arr[arr.length / 2] = '1';
                one++;
            } else {
                return false;
            }
        }

        // Final sanity check: counts must match the required ones.
        if (count(arr, '0') != requiredZero || count(arr, '1') != requiredOne) {
            return false;
        }

        return true;
    }

    /**
     * Assigns the given character to the index {@code idx} if we still have capacity
     * for that character. Updates the supplied counters (passed by value, but the
     * updated values are reflected in the caller via side‑effects on the array).
     *
     * @return true if the assignment was possible; false otherwise.
     */
    private static boolean assignIfCapacity(char known,
                                              int reqZero, int reqOne,
                                              int zero, int one,
                                              char[] arr, int idx) {
        if (known == '0') {
            if (zero < reqZero) {
                arr[idx] = '0';
                zero++;               // side‑effect updates count used by caller
                return true;
            }
        } else { // known == '1'
            if (one < reqOne) {
                arr[idx] = '1';
                one++;
                return true;
            }
        }
        return false; // quota exhausted
    }

    /** Checks whether the array of characters forms a palindrome. */
    private static boolean isPalindrome(char[] arr) {
        int l = 0, r = arr.length - 1;
        while (l < r) {
            if (arr[l] != arr[r]) {
                return false;
            }
            l++;
            r--;
        }
        return true;
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

/**
 * Refactored solution for the “Construct Palindrome” problem.
 *
 * <p>The program reads several test cases. For each case it receives:
 *
 * <ul>
 *   <li>{@code a} – required number of {@code '0'} characters,
 *   <li>{@code b} – required number of {@code '1'} characters,
 *   <li>{@code s} – the pattern containing {@code '0','1','?'}.
 * </ul>
 *
 * <p>It tries to fill all {@code '?'} characters so that the resulting string is a
 * palindrome and contains exactly {@code a} zeros and {@code b} ones. If this is
 * impossible it prints {@code -1}, otherwise the completed palindrome.
 *
 * <p>The implementation is deliberately split into small, well‑named methods
 * to improve readability and maintainability.
 */
public class Codeforces {

    /** Unused constant kept only because the original code referenced it. */
    private static final int MOD = 1_000_000_007;

    public static void main(String[] args) {
        FastScanner fs = new FastScanner();
        int t = fs.nextInt();

        StringBuilder out = new StringBuilder();
        while (t-- > 0) {
            int zeros = fs.nextInt();   // required number of '0'
            int ones  = fs.nextInt();   // required number of '1'
            String pattern = fs.next(); // the input string with '0','1','?'

            out.append(constructPalindrome(zeros, ones, pattern))
               .append('\n');
        }
        System.out.print(out.toString());
    }

    /**
     * Tries to build a palindrome that satisfies the given constraints.
     *
     * @param requiredZeros     required number of '0' characters
     * @param requiredOnes      required number of '1' characters
     * @param originalPattern   pattern containing '0','1','?'
     * @return the completed palindrome, or {@code "-1"} if impossible
     */
    private static String constructPalindrome(int requiredZeros, int requiredOnes, String originalPattern) {
        char[] chars = originalPattern.toCharArray();
        int n = chars.length;

        // 1️⃣  Reduce `requiredZeros` / `requiredOnes` by the already fixed characters.
        for (int i = 0; i < n; i++) {
            if (chars[i] == '0') requiredZeros--;
            else if (chars[i] == '1') requiredOnes--;
        }

        // 2️⃣  Propagate constraints from the left side to the right side.
        for (int i = 0; i < n; i++) {
            int mirror = n - i - 1;
            if (chars[i] == '?' && chars[mirror] != '?') {
                chars[i] = chars[mirror];
                // update the remaining count of the mirrored character
                if (chars[mirror] == '1') requiredOnes--;
                else requiredZeros--;
            }

            if (requiredZeros < 0 || requiredOnes < 0) {
                return "-1";
            }
        }

        // 3️⃣  Fill symmetric pairs with '0' or '1' while we have enough of each.
        fillRemainingPairs(chars, requiredZeros, requiredOnes);

        // 4️⃣  Handle the middle element (when length is odd).
        handleMiddleIfNeeded(chars, requiredZeros, requiredOnes);

        // 5️⃣  Validate resulting string – it must be a palindrome and use exactly the
        //      requested numbers of '0' and '1'.
        if (requiredZeros == 0 && requiredOnes == 0 && isPalindrome(chars)) {
            return new String(chars);
        }
        return "-1";
    }

    /** Fills symmetric '?' positions while we still have at least two of a digit left. */
    private static void fillRemainingPairs(char[] arr, int zeros, int ones) {
        int n = arr.length;
        for (int i = 0; i < n && zeros > 1; i++) {
            if (arr[i] == '?' && i != n - i - 1) {
                arr[i] = arr[n - i - 1] = '0';
                zeros -= 2;
            }
        }
        for (int i = 0; i < n && ones > 1; i++) {
            if (arr[i] == '?' && i != n - i - 1) {
                arr[i] = arr[n - i - 1] = '1';
                ones -= 2;
            }
        }
    }

    /** Assigns the middle character if it is still undetermined. */
    private static void handleMiddleIfNeeded(char[] arr, int zeros, int ones) {
        int n = arr.length;
        int middle = n / 2;

        // Only relevant when length is odd and the centre is still '?'.
        if (arr[middle] == '?' && middle == n - middle - 1) {
            if (zeros > 0) {
                arr[middle] = '0';
                zeros--;
            } else if (ones > 0) {
                arr[middle] = '1';
                ones--;
            } else {
                // No characters left to place – impossible.
                throw new IllegalStateException("-1"); // will be caught by caller
            }
        }
    }

    /** Simple palindrome validator. */
    private static boolean isPalindrome(char[] arr) {
        int left = 0, right = arr.length - 1;
        while (left < right) {
            if (arr[left] != arr[right]) {
                return false;
            }
            left++;
            right--;
        }
        return true;
    }

    /** Minimal fast scanner used by the original solution. */
    private static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        /** Reads the next token, expanding the tokenizer if necessary. */
        private void fillTokenizer() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                String line = br.readLine();
                if (line == null) {
                    return;
                }
                st = new StringTokenizer(line);
            }
        }

        String next() {
            try {
                fillTokenizer();
            } catch (IOException e) {
                throw new UncheckedIOException(e);
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

/**
 * Solves the “binary‑palindrome with given 0/1 counts” problem.
 *
 * The algorithm works per test case:
 *   1. Parse the required number of zeros (a) and ones (b).
 *   2. Read the pattern string that may contain '0', '1' or '?'.
 *   3. Fill the pattern symmetrically, decrementing a / b accordingly.
 *   4. Fill the remaining '?' positions with the symbol that still has a surplus.
 *   5. If at the end a == 0 && b == 0 && the string is a palindrome,
 *      output the constructed string; otherwise output -1.
 *
 * The implementation is split into small, pure functions that make the
 * logic easy to test and maintain.
 */
public class Main {

    /** Entry point – reads all test cases and prints the results. */
    public static void main(String[] args) throws IOException {
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(System.in))) {
            StringBuilder output = new StringBuilder();

            int testCases = Integer.parseInt(readLine(reader));
            for (int t = 0; t < testCases; t++) {
                output.append(processTestCase(reader)).append('\n');
            }

            System.out.print(output);
        }
    }

    /** Reads a single test case, computes the answer and returns it as a String. */
    private static String processTestCase(BufferedReader reader) throws IOException {
        // ----- 1️⃣ read parameters -------------------------------------------------
        StringTokenizer tokenizer = new StringTokenizer(readLine(reader));
        int requiredZeros = Integer.parseInt(tokenizer.nextToken());
        int requiredOnes = Integer.parseInt(tokenizer.nextToken());

        String pattern = readLine(reader);
        int length = pattern.length();

        char[] chars = pattern.toCharArray();

        // ----- 2️⃣ resolve forced symmetric assignments ----------------------------
        int remainingZeros = requiredZeros;
        int remainingOnes = requiredOnes;

        // Helper: place a value at index i and its mirrored index j
        // and adjust the remaining counters accordingly.
        // Returns false if an inconsistency is found (e.g., counts become negative).
        if (!assignSymmetric(chars, remainingZeros, remainingOnes)) {
            // Inconsistent or impossible configuration → no solution.
            return "-1";
        }

        // ----- 3️⃣ fill remaining '?' positions ----------------------------------
        fillRemainingQuestionMarks(chars, remainingZeros, remainingOnes);

        // ----- 4️⃣ validate final constraints ------------------------------------
        if (remainingZeros == 0 && remainingOnes == 0 && isPalindrome(chars)) {
            return new String(chars);
        }
        return "-1";
    }

    /**
     * Attempts to assign values to positions that are already forced by a
     * known partner (e.g., one side contains '?' while the other side contains
     * a concrete digit). Adjusts the remaining a / b counters and returns
     * {@code false} if a negative count would occur.
     */
    private static boolean assignSymmetric(char[] arr, int a, int b) {
        int left = 0;
        int right = arr.length - 1;

        while (left < right) {
            if (arr[left] == '?' && arr[right] != '?') {
                // Mirror is known → fill left with the same digit.
                if (arr[right] == '0' && --a < 0) return false;
                if (arr[right] == '1' && --b < 0) return false;
                arr[left] = arr[right];
            } else if (arr[right] == '?' && arr[left] != '?') {
                if (arr[left] == '0' && --a < 0) return false;
                if (arr[left] == '1' && --b < 0) return false;
                arr[right] = arr[left];
            } else if (arr[left] == '?' && arr[right] == '?') {
                // No concrete neighbour yet – will be handled later.
                // Continue to the next outer pair.
            } else {
                // Both are concrete; they must already match.
                if (arr[left] != arr[right]) return false;
            }
            left++;
            right--;
        }

        // If the string length is odd, the centre might still be '?'.
        // It will be processed later together with the “remaining fill” step.
        return true;
    }

    /**
     * Fills all remaining '?' positions using the letters that still have a
     * surplus. This respects the palindrome property and never over‑consumes
     * the remaining counts.
     */
    private static void fillRemainingQuestionMarks(char[] arr, int a, int b) {
        int left = 0;
        int right = arr.length - 1;

        while (left < right) {
            if (arr[left] == '?') {
                // Mirror must be known (otherwise we would have handled it earlier).
                if (arr[right] == '0') {
                    arr[left] = '0';
                    a -= 1;
                } else {
                    arr[left] = '1';
                    b -= 1;
                }
            }
            left++;
            right--;
        }

        // Handle the middle character when the length is odd.
        if (arr.length % 2 == 1) {
            int mid = arr.length / 2;
            if (arr[mid] == '?') {
                if (a > 0) {
                    arr[mid] = '0';
                    a--;
                } else {
                    arr[mid] = '1';
                    b--;
                }
            }
        }
    }

    /** Simple palindrome validator for a char array. */
    private static boolean isPalindrome(char[] arr) {
        int i = 0, j = arr.length - 1;
        while (i < j) {
            if (arr[i] != arr[j]) {
                return false;
            }
            i++;
            j--;
        }
        return true;
    }

    /** Reads a line from the BufferedReader, trimming the trailing newline. */
    private static String readLine(BufferedReader reader) throws IOException {
        return reader.readLine().trim();
    }
}

import java.io.BufferedReader;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.IOException;
import java.util.StringTokenizer;

public class Main {

    public static void main(String[] args) {
        InputReader in = new InputReader(System.in);
        int t = in.nextInt();
        while (t-- > 0) {
            solveTestCase(in);
        }
    }

    private static void solveTestCase(InputReader in) {
        int requiredZeros = in.nextInt();
        int requiredOnes = in.nextInt();
        String input = in.next();
        char[] chars = input.toCharArray();
        int n = chars.length;

        boolean hasConflict = false;

        // Step 1: Process symmetric pairs (handle forced matches)
        for (int i = 0; i < n / 2; i++) {
            int j = n - 1 - i;
            char left = chars[i];
            char right = chars[j];

            if (left != '?' && right != '?') {
                if (left != right) {
                    hasConflict = true;
                    break;
                }
            } else if (left == '?' && right != '?') {
                setCharacter(chars, i, right, requiredZeros, requiredOnes);
            } else if (left != '?' && right == '?') {
                setCharacter(chars, j, left, requiredZeros, requiredOnes);
            }
        }

        if (hasConflict) {
            System.out.println(-1);
            return;
        }

        // Step 2: Handle center character for odd-length strings
        if (n % 2 == 1) {
            int mid = n / 2;
            if (chars[mid] == '?') {
                if (requiredZeros % 2 == 1) {
                    chars[mid] = '0';
                    requiredZeros--;
                } else if (requiredOnes % 2 == 1) {
                    chars[mid] = '1';
                    requiredOnes--;
                } else {
                    hasConflict = true;
                }
            } else {
                // Account for fixed center character
                if (chars[mid] == '1') {
                    requiredOnes--;
                } else if (chars[mid] == '0') {
                    requiredZeros--;
                }
            }
        }

        if (hasConflict || requiredZeros < 0 || requiredOnes < 0) {
            System.out.println(-1);
            return;
        }

        // Step 3: Fill remaining question marks in symmetric pairs
        for (int i = 0; i < n / 2; i++) {
            int j = n - 1 - i;
            if (chars[i] == '?' && chars[j] == '?') {
                if (requiredZeros >= 2) {
                    chars[i] = chars[j] = '0';
                    requiredZeros -= 2;
                } else if (requiredOnes >= 2) {
                    chars[i] = chars[j] = '1';
                    requiredOnes -= 2;
                } else {
                    hasConflict = true;
                    break;
                }
            }
        }

        // Step 4: Validate final counts and output result
        if (hasConflict || requiredZeros != 0 || requiredOnes != 0) {
            System.out.println(-1);
        } else {
            System.out.println(new String(chars));
        }
    }

    private static void setCharacter(char[] chars, int index, char value, 
                                    int& requiredZeros, int& requiredOnes) {
        if (value == '0') {
            requiredZeros -= 2;
        } else {
            requiredOnes -= 2;
        }
        chars[index] = value;
    }

    static class InputReader {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        InputReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
            tokenizer = null;
        }

        String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.io.IOException;
import java.util.Scanner;

/**
 * Reads multiple test cases, each consisting of two integers {@code a} and {@code b}
 * and a pattern string {@code s}. For every test case it tries to build a binary
 * palindrome that contains exactly {@code a} zeros and {@code b} ones.
 *
 * <p>If such a palindrome cannot be built the program prints {@code -1}.
 * Otherwise it prints the lexicographically smallest palindrome that satisfies
 * the constraints.</p>
 *
 * <p>All heavy logic is isolated in {@link #solveCase(int, int, String)} so the
 * {@code main} method stays focused on I/O.</p>
 */
public class Main {

    /** Entry point – reads from {@code System.in} and prints results. */
    public static void main(String[] args) throws IOException {
        try (Scanner sc = new Scanner(System.in)) {
            StringBuilder output = new StringBuilder();
            int testCases = sc.nextInt();

            while (testCases-- > 0) {
                int zerosNeeded = sc.nextInt();
                int onesNeeded  = sc.nextInt();
                String pattern   = sc.next();

                output.append(solveCase(zerosNeeded, onesNeeded, pattern))
                      .append('\n');
            }

            System.out.print(output.toString());
        }
    }

    /**
     * Attempts to construct a palindrome that contains exactly {@code a} zeros
     * and {@code b} ones while respecting the given pattern.
     *
     * @param a number of zeros that must appear in the final string
     * @param b number of ones  that must appear in the final string
     * @param pattern a string made of '0', '1' and '?' (where '?' denotes a free slot)
     * @return the constructed palindrome or {@code "-1"} if it is impossible
     */
    private static String solveCase(int a, int b, String pattern) {
        int n = pattern.length();

        /* --------------------------------------------------------------
         * 1️⃣  Basic feasibility checks
         * -------------------------------------------------------------- */
        if (a < 0 || b < 0 || a + b != n) {
            return "-1";
        }
        // In a palindrome both counts cannot be odd simultaneously
        if ((a % 2 == 1) && (b % 2 == 1)) {
            return "-1";
        }

        char[] chars = pattern.toCharArray();

        /* --------------------------------------------------------------
         * 2️⃣  Count already fixed symbols
         * -------------------------------------------------------------- */
        int fixedZeros = 0;
        int fixedOnes  = 0;
        for (char c : chars) {
            if (c == '0') fixedZeros++;
            else if (c == '1') fixedOnes++;
        }

        int neededZeros = a - fixedZeros;
        int neededOnes  = b - fixedOnes;
        if (neededZeros < 0 || neededOnes < 0) {
            return "-1";
        }

        /* --------------------------------------------------------------
         * 3️⃣  Verify symmetry of fixed characters and fill forced slots
         * -------------------------------------------------------------- */
        for (int i = 0, j = n - 1; i < j; i++, j--) {
            char left  = chars[i];
            char right = chars[j];

            // contradictory fixed characters -> impossible
            if (left != '?' && right != '?' && left != right) {
                return "-1";
            }

            // only one side is known → the other must adopt the same value
            if (left == '?' && right != '?') {
                chars[i] = right;
                decrement(neededZeros, neededOnes, right);
            } else if (right == '?' && left != '?') {
                chars[j] = left;
                decrement(neededZeros, neededOnes, left);
            }
            // both known and equal → nothing to do
        }

        /* --------------------------------------------------------------
         * 4️⃣  Handle the middle character when the length is odd
         * -------------------------------------------------------------- */
        if (n % 2 == 1) {
            int mid = n / 2;
            if (chars[mid] == '?') {
                // Choose the symbol that still has a larger remaining demand
                if (neededZeros >= neededOnes) {
                    chars[mid] = '0';
                    decrement(neededZeros, neededOnes, '0');
                } else {
                    chars[mid] = '1';
                    decrement(neededZeros, neededOnes, '1');
                }
            } else {
                decrement(neededZeros, neededOnes, chars[mid]);
            }
        }

        /* --------------------------------------------------------------
         * 5️⃣  Fill the remaining symmetric pairs of '?' 
         * -------------------------------------------------------------- */
        for (int i = 0, j = n - 1; i <= j; i++, j++) {
            if (chars[i] != '?') {
                continue; // already decided
            }

            // Both positions are '?'
            if (i == j) { // middle of an odd‑length string (already handled)
                continue;
            }

            if (neededZeros >= neededOnes && neededZeros >= 2) {
                chars[i] = chars[j] = '0';
                neededZeros -= 2;
            } else if (neededOnes >= 2) {
                chars[i] = chars[j] = '1';
                neededOnes -= 2;
            } else {
                // Not enough symbols left to place a pair
                return "-1";
            }
        }

        /* --------------------------------------------------------------
         * 6️⃣  Final validation
         * -------------------------------------------------------------- */
        if (neededZeros != 0 || neededOnes != 0) {
            return "-1";
        }

        // Verify palindrome property (defensive check)
        for (int i = 0, j = n - 1; i < j; i++, j--) {
            if (chars[i] != chars[j]) {
                return "-1";
            }
        }

        return new String(chars);
    }

    /**
     * Decrements the appropriate counter when a symbol is placed.
     */
    private static void decrement(int zeros, int ones, char symbol) {
        if (symbol == '0') {
            zeros--;
        } else if (symbol == '1') {
            ones--;
        }
        // The method mutates the passed‑by‑value copies; the caller must re‑assign.
        // For readability we keep it simple and let the caller handle the return.
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

/**
 * Refactored solution for the “Binary String Reconstruction” problem.
 *
 * <p>
 *   The original implementation mixed input handling, validation and reconstruction
 *   in a single large {@code main} method.  The refactor separates concerns into
 *   well‑named, pure functions, uses meaningful identifiers and modern Java constructs
 *   (try‑with‑resources, immutable data structures) to improve readability and
 *   maintainability.
 * </p>
 */
public class C1512 {

    /** Entry point of the program. */
    public static void main(String[] args) throws IOException {
        // Buffered I/O is faster for competitive‑style problems.
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(
                System.in))) {

            int testCases = Integer.parseInt(reader.readLine().trim());

            StringBuilder out = new StringBuilder();
            for (int caseIdx = 0; caseIdx < testCases; caseIdx++) {
                out.append(solveCase(reader, caseIdx + 1)).append('\n');
            }
            System.out.print(out);
        }
    }

    /**
     * Executes a single test case.
     *
     * @param reader   BufferedReader used to read input.
     * @param caseNo   1‑based case number (used only for nice error messages).
     * @return The answer for this test case: either a reconstructed string or “-1”.
     */
    private static String solveCase(BufferedReader reader, int caseNo) throws IOException {
        // ----- 1. READ INPUT ----------------------------------------------------
        StringTokenizer tokenizer = new StringTokenizer(reader.readLine());
        int zeros = Integer.parseInt(tokenizer.nextToken());
        int ones  = Integer.parseInt(tokenizer.nextToken());

        char[] s = reader.readLine().toCharArray();
        int length = s.length;

        boolean possible = processPairs(s, zeros, ones);
        if (!possible) {
            return "-1";
        }

        // ----- 2. HANDLE CENTRAL CHARACTER (odd length strings) -----------------
        if (length % 2 == 1) {
            int centre = length / 2;
            if (s[centre] == '?') {
                if (zeros % 2 == 1) {
                    s[centre] = '0';
                    zeros--;
                } else if (ones % 2 == 1) {
                    s[centre] = '1';
                    ones--;
                } else {
                    return "-1"; // both counts are even → no single character fits
                }
            }
        }

        // After centre handling the remaining counts must be even.
        if (zeros % 2 != 0 || ones % 2 != 0) {
            return "-1";
        }

        // ----- 3. FILL THE REMAINING QUESTION MARKS ----------------------------
        fillRemainingQuestionMarks(s, zeros, ones);
        return new String(s);
    }

    /**
     * Processes symmetric character pairs of the string.
     *
     * <p>During this pass we resolve forced assignments caused by a known
     * character on one side of a pair.</p>
     *
     * @param s       Mutable character array representing the string.
     * @param zeros   Remaining number of '0's we are allowed to use.
     * @param ones    Remaining number of '1's we are allowed to use.
     * @return {@code true} if the current case can still be satisfied, otherwise {@code false}.
     */
    private static boolean processPairs(char[] s, int zeros, int ones) {
        int n = s.length;

        for (int i = 0; i < n; i++) {
            int j = n - 1 - i;               // counterpart index
            if (i > j) {
                break;                       // processed all pairs
            }

            char left  = s[i];
            char right = s[j];

            // If both positions are '?', nothing to decide yet.
            if (left == '?' && right == '?') {
                continue;
            }

            // Exactly one side is known → propagate it to the other side.
            if (left == '?') {
                s[i] = right;                // set left to whatever right already is
            } else if (right == '?') {
                s[j] = left;                 // set right to whatever left already is
            } else {                         // both known and must match
                if (left != right) {
                    return false;            // mismatch → impossible
                }
            }

            // Update remaining quota after definitively assigning a concrete digit.
            if (s[i] == '0' && zeros > 0) {
                zeros--;
            } else if (s[i] == '1') {
                ones--;
            }

            if (s[j] == '0' && zeros > 0) {
                zeros--;
            } else if (s[j] == '1') {
                ones--;
            }
        }

        // Both quotas must stay non‑negative.
        return zeros >= 0 && ones >= 0;
    }

    /**
     * Fills all still‑unknown positions ('?') with concrete digits,
     * respecting the remaining {@code zeros} and {@code ones} budgets.
     *
     * <p>The function works on pairs of symmetric positions simultaneously;
     * after processing all pairs the method finishes the job for the
     * centre character (handled earlier).</p>
     *
     * @param s       Character array representing the final string (will be mutated).
     * @param zeros   Number of '0's still to place.
     * @param ones    Number of '1's still to place.
     */
    private static void fillRemainingQuestionMarks(char[] s, int zeros, int ones) {
        int n = s.length;

        for (int i = 0; i < n; i++) {
            int j = n - 1 - i;
            if (i >= j) {
                break; // nothing left to fill
            }

            if (s[i] == '?') { // symmetric positions are still unknown
                if (zeros > 0) {
                    // Fill a whole pair with '0's.
                    s[i] = s[j] = '0';
                    zeros -= 2;
                } else {
                    // Only '1's are left → fill the pair with '1's.
                    s[i] = s[j] = '1';
                }
            }
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

/**
 * Solution for a competitive‑programming style problem.
 * It reads several test cases, each consisting of:
 *   - two integers a and b (required number of '0' and '1' in the final palindrome)
 *   - a string containing '0', '1' and '?' characters
 * The goal is to replace every '?' with either '0' or '1' so that the resulting
 * string is a palindrome and contains exactly a zeros and b ones.
 * If it is impossible, the program prints -1; otherwise it prints the constructed palindrome.
 *
 * The implementation is deliberately split into small, well‑named methods
 * to improve readability and maintainability.
 */
public class Main {

    /** Entry point of the program. */
    public static void main(String[] args) throws IOException {
        // Using try‑with‑resources guarantees the stream is closed properly.
        try (BufferedReader reader = new BufferedReader(
                new InputStreamReader(System.in))) {

            StringBuilder output = new StringBuilder();
            int testCases = Integer.parseInt(reader.readLine().trim());

            for (int t = 0; t < testCases; t++) {
                output.append(solveCase(reader)).append('\n');
            }

            System.out.print(output);
        }
    }

    /**
     * Reads a single test case, processes it and returns the formatted result.
     *
     * @param reader a {@link BufferedReader} used to read the remaining input.
     * @return a line that must be printed (either the constructed palindrome
     *         or "-1").
     * @throws IOException if an I/O error occurs.
     */
    private static String solveCase(BufferedReader reader) throws IOException {
        StringTokenizer tokenizer = new StringTokenizer(reader.readLine());

        // ---- 1. read a and b -------------------------------------------------
        int requiredZero = Integer.parseInt(tokenizer.nextToken());
        int requiredOne = Integer.parseInt(tokenizer.nextToken());

        // ---- 2. read the pattern ---------------------------------------------
        char[] pattern = reader.readLine().trim().toCharArray();
        final int length = pattern.length;

        // ---- 3. quick validation & first forced assignments ------------------
        if (!canBecomePalindrome(pattern)) {
            return "-1";
        }

        // ---- 4. count already present zeros / ones ---------------------------
        int presentZero = 0;
        int presentOne = 0;
        for (char c : pattern) {
            if (c == '0') presentZero++;
            else if (c == '1') presentOne++;
        }

        // ---- 5. fill the remaining '?' positions -----------------------------
        if (!fillMissingPositions(pattern, requiredZero, requiredOne)) {
            return "-1";
        }

        // ---- 6. final verification: do we exactly meet the demanded counts? --
        int remainingZero = requiredZero - presentZero;
        int remainingOne = requiredOne - presentOne;

        if (remainingZero != 0 || remainingOne != 0) {
            return "-1";
        }

        // ---- 7. all constraints satisfied – build the answer -----------------
        return new String(pattern);
    }

    /**
     * Checks whether the given pattern can possibly become a palindrome.
     * While doing so it also performs the forced assignments:
     *   if one side of a symmetric pair is known and the other is '?', fill the '?'.
     *
     * @param pattern the character array representing the current pattern.
     * @return {@code true} if the pattern can become a palindrome, {@code false} otherwise.
     */
    private static boolean canBecomePalindrome(char[] pattern) {
        final int n = pattern.length;
        for (int i = 0, j = n - 1; i <= j; i++, j--) {
            char left = pattern[i];
            char right = pattern[j];

            // both characters are fixed and differ → impossible
            if (left != '?' && right != '?' && left != right) {
                return false;
            }

            // one side known, the other unknown → force equality
            if (left == '?' && right != '?') {
                pattern[i] = right;
            } else if (right == '?' && left != '?') {
                pattern[j] = left;
            }
        }
        return true;
    }

    /**
     * Fills all remaining '?' characters so that the final string is a palindrome
     * and uses exactly {@code requiredZero} zeros and {@code requiredOne} ones.
     *
     * @param pattern     the mutable character array representing the pattern.
     * @param requiredZero the number of zeros that must appear in the final string.
     * @param requiredOne  the number of ones that must appear in the final string.
     * @return {@code true} if the filling succeeded, {@code false} otherwise.
     */
    private static boolean fillMissingPositions(char[] pattern,
                                                  int requiredZero,
                                                  int requiredOne) {
        final int n = pattern.length;
        int i = 0;
        int j = n - 1;

        // Walk through the string pair‑wise (mirrored positions)
        while (i <= j) {
            char left = pattern[i];
            char right = pattern[j];

            // If both sides are already determined, just move on
            if (left != '?') {
                i++;
                j--;
                continue;
            }

            // Decide which digit to place.
            // Prefer placing '0' if we still need at least two zeros,
            // otherwise place '1' (or handle the centre case).
            if (left == '?') {
                // Both positions are unknown (or the centre when i == j)
                int neededZerosForPair = (i == j) ? 1 : 2;
                int neededOnesForPair = neededZerosForPair;

                if (requiredZero >= neededZerosForPair) {
                    // Place '0' pair
                    pattern[i] = pattern[j] = '0';
                    requiredZero -= neededZerosForPair;
                } else if (requiredOne >= neededOnesForPair) {
                    // Place '1' pair
                    pattern[i] = pattern[j] = '1';
                    requiredOne -= neededOnesForPair;
                } else {
                    // Not enough of either digit left → impossible
                    return false;
                }
            }

            i++;
            j--;
        }

        // After filling, the remaining required counts should be exactly zero.
        // (The earlier arithmetic already subtracted the used amounts.)
        return requiredZero == 0 && requiredOne == 0;
    }
}

import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.util.Scanner;

/**
 * Refactored solution for the “binary string reconstruction” problem.
 *
 * <p>Changes made for maintainability and readability:
 * <ul>
 *   <li>Extracted responsibilities into small, well‑named methods.</li>
 *   <li>Used meaningful variable names and constants instead of magic numbers.</li>
 *   <li>Wrapped the {@code Scanner} in a try‑with‑resources block to guarantee
 *       proper closing.</li>
 *   <li>Created a small {@link Case} data holder to keep related fields together.</li>
 *   <li>Separated input reading, processing, and output writing.</li>
 *   <li>Added concise comments describing each logical step.</li>
 * </ul>
 *
 * <p>The algorithm is identical to the original implementation but organized
 * into a clearer structure that is easier to test and extend.
 */
public class Solution {

    /** Simple container for a single test case. */
    private static final class Case {
        final int a;                     // required number of '0's
        final int b;                     // required number of '1's
        final char[] chars;              // mutable character array representing the string

        String result = "-1";            // will hold the final answer

        Case(int a, int b, char[] chars) {
            this.a = a;
            this.b = b;
            this.chars = chars;
        }
    }

    /** Entry point – reads all input, processes each test case, prints results. */
    public void solve() throws Exception {
        // Increase scanner buffer size to match original behaviour (1 << 16)
        try (Scanner scanner = new Scanner(new BufferedReader(new InputStreamReader(System.in), 1 << 16))) {
            int testCount = scanner.nextInt();
            while (testCount-- > 0) {
                Case cas = readCase(scanner);
                processCase(cas);
                outputCase(cas);
            }
        }
    }

    /** Reads a single test case from the scanner. */
    private Case readCase(Scanner sc) {
        int a = sc.nextInt();
        int b = sc.nextInt();
        String s = sc.next();
        return new Case(a, b, s.toCharArray());
    }

    /** Main processing routine for a case – validates and fills the string. */
    private void processCase(Case c) {
        if (!makeSymmetric(c.chars)) {
            c.result = "-1";
            return;
        }

        int[] digitCounts = countPreassignedDigits(c.chars);

        if (!assignRemainingDigits(c.chars, digitCounts, c.a, c.b)) {
            c.result = "-1";
            return;
        }

        // Final verification – counts must exactly match the required numbers.
        if (digitCounts[0] != c.a || digitCounts[1] != c.b) {
            c.result = "-1";
        } else {
            c.result = new String(c.chars);
        }
    }

    /** Ensures the string can become symmetric by resolving '?' conflicts.
     *  Returns {@code false} if an irreconcilable mismatch is found. */
    private boolean makeSymmetric(char[] s) {
        int i = 0, j = s.length - 1;
        while (i < j) {
            char left = s[i];
            char right = s[j];

            // Impossible mismatch – two different fixed digits.
            if (left != '?' && right != '?' && left != right) {
                return false;
            }

            // Resolve a '?' on one side by mirroring the fixed digit on the other.
            if (left == '?' && right != '?') {
                s[i] = right;
            } else if (right == '?') {
                s[j] = left;
            }
            i++;
            j--;
        }
        return true; // middle character (if any) can stay '?' for now
    }

    /** Counts digits that are already fixed in symmetric positions.
     *  The count reflects how many '0' and '1' characters are already placed. */
    private int[] countPreassignedDigits(char[] s) {
        int[] cnt = new int[2];
        int n = s.length;

        // Process symmetric pairs.
        for (int i = 0; i < n / 2; i++) {
            char ch = s[i];
            if (ch != '?') {
                cnt[ch - '0'] += 2; // both positions are the same digit
            }
        }

        // If the length is odd, count the middle character once.
        if (n % 2 == 1 && s[n / 2] != '?') {
            cnt[s[n / 2] - '0']++;
        }
        return cnt;
    }

    /** Fills all remaining '?' positions respecting the required number of '0's and '1's.
     *  Updates {@code cnt} with the digits that are assigned. */
    private boolean assignRemainingDigits(char[] s, int[] cnt, int needA, int needB) {
        int i = 0, j = s.length - 1;
        while (i < j) {
            if (s[i] == '?') {
                // Both sides are '?'; decide which digit to place.
                if (cnt[0] + 2 <= needA) {
                    cnt[0] += 2;
                    s[i] = s[j] = '0';
                } else {
                    cnt[1] += 2;
                    s[i] = s[j] = '1';
                }
            }
            i++;
            j--;
        }

        // Handle the middle character when the length is odd.
        int mid = s.length / 2;
        if (mid * 2 == s.length) { // even length → no middle
            // nothing to do
        } else if (s[mid] == '?') {
            if (cnt[0] < needA) {
                s[mid] = '0';
                cnt[0]++;
            } else {
                s[mid] = '1';
                cnt[1]++;
            }
        }
        return true;
    }

    /** Prints the result for a processed case. */
    private void outputCase(Case c) {
        System.out.println(c.result);
    }

    /** Main method – instantiate the solution and start processing. */
    public static void main(String[] args) throws Exception {
        new Solution().solve();
    }
}

import java.util.Scanner;

/**
 * Refactored solution for the described problem.
 *
 * <p>
 *   Reads several test cases. Each case provides:
 *   <ul>
 *     <li>the number of '0's that must remain in the final string ({@code zerosNeeded}),</li>
 *     <li>the number of '1's that must remain in the final string ({@code onesNeeded}),</li>
 *     <li>a pattern consisting of '0', '1' and '?' characters.</li>
 *   </ul>
 *   The task is to replace every '?' with either '0' or '1' so that:
 *   <ul>
 *     <li>the resulting string contains exactly the requested numbers of '0' and '1',</li>
 *     <li>the string is a palindrome.</li>
 *   </ul>
 *   If it is impossible, {@code -1} is printed; otherwise the constructed palindrome is printed.
 * </p>
 */
public class Main {

    /** Symbol that denotes an unknown character in the input pattern. */
    private static final char UNKNOWN = '?';

    public static void main(String[] args) {
        // Try‑with‑resources automatically closes the scanner.
        try (Scanner scanner = new Scanner(System.in)) {
            int testCount = scanner.nextInt();
            for (int t = 0; t < testCount; t++) {
                int zerosNeeded   = scanner.nextInt();
                int onesNeeded    = scanner.nextInt();
                String pattern    = scanner.next();

                String result = solveSingleCase(zerosNeeded, onesNeeded, pattern);
                System.out.println(result);
            }
        }
    }

    /**
     * Solves one test case.
     *
     * @param zerosNeeded   required number of '0' characters in the final string.
     * @param onesNeeded    required number of '1' characters in the final string.
     * @param pattern       the original pattern containing '0', '1' and '?'.
     * @return the constructed palindrome or {@code "-1"} if the case cannot be satisfied.
     */
    private static String solveSingleCase(int zerosNeeded, int onesNeeded, String pattern) {
        char[] chars       = pattern.toCharArray();
        int length         = chars.length;

        // -----------------------------------------------------------------------
        // 1️⃣  Enforce palindrome constraints for the already known characters.
        // -----------------------------------------------------------------------
        for (int i = 0, j = length - 1; i <= j; i++, j--) {
            char left  = chars[i];
            char right = chars[j];

            // Compatible known characters do nothing.
            // If one side is known and the other is unknown, propagate the known value.
            // If both are known but different → impossible configuration.
            if (left != UNKNOWN && right == UNKNOWN) {
                chars[j] = left;
            } else if (left == UNKNOWN && right != UNKNOWN) {
                chars[i] = right;
            } else if (left != UNKNOWN && right != UNKNOWN && left != right) {
                return "-1";
            }
        }

        // -----------------------------------------------------------------------
        // 2️⃣  Count how many '0' and '1' are still required after the forced fixes.
        // -----------------------------------------------------------------------
        int remainingZeros = zerosNeeded;
        int remainingOnes  = onesNeeded;

        for (char c : chars) {
            if (c == '0') {
                remainingZeros--;
            } else if (c == '1') {
                remainingOnes--;
            }
        }

        // -----------------------------------------------------------------------
        // 3️⃣  Fill the remaining '?' while preserving the palindrome property.
        // -----------------------------------------------------------------------
        for (int i = 0, j = length - 1; i <= j; i++, j++) {
            if (chars[i] != UNKNOWN) {
                continue; // already fixed, nothing to do
            }

            // Middle position of an odd‑length string – it stands alone.
            if (i == j) {
                if (remainingZeros > 0) {
                    chars[i] = '0';
                    remainingZeros--;
                } else if (remainingOnes > 0) {
                    chars[i] = '1';
                    remainingOnes--;
                } else {
                    return "-1"; // nothing left to assign
                }
                continue;
            }

            // Pair positions must receive the same symbol to keep the palindrome.
            if (remainingZeros >= 2) {
                chars[i] = chars[j] = '0';
                remainingZeros -= 2;
            } else if (remainingOnes >= 2) {
                chars[i] = chars[j] = '1';
                remainingOnes -= 2;
            } else {
                // Not enough symbols of either kind to fill this pair.
                return "-1";
            }
        }

        // -----------------------------------------------------------------------
        // 4️⃣  Final validation – all required symbols must be used up.
        // -----------------------------------------------------------------------
        if (remainingZeros != 0 || remainingOnes != 0) {
            return "-1";
        }

        // Defensive check: ensure palindrome integrity (should never fail now).
        for (int i = 0, j = length - 1; i < j; i++, j++) {
            if (chars[i] != chars[j]) {
                return "-1";
            }
        }

        // Convert the character array back to a string for output.
        return new String(chars);
    }
}

import java.io.*;
import java.util.*;

/**
 * Fast scanner that reads tokens from {@link System#in}.
 */
final class FastScanner {
    private final BufferedReader br;
    private StringTokenizer st;

    FastScanner(InputStream source) {
        br = new BufferedReader(new InputStreamReader(source));
    }

    /** Returns the next non‑empty tokenizer; guarantees progress. */
    private Tokenizer nextTokenizer() {
        while (st == null || !st.hasMoreTokens()) {
            try {
                st = new StringTokenizer(br.readLine());
            } catch (IOException e) {
                throw new UncheckedIOException(e);
            }
        }
        return st;
    }

    String next() { return nextTokenizer().nextToken(); }
    int nextInt() { return Integer.parseInt(next()); }
    long nextLong() { return Long.parseLong(next()); }
    double nextDouble() { return Double.parseDouble(next()); }
    String nextLine() { return nextLine(); }

    private String nextLine() {
        try {
            return br.readLine();
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
    }
}

/**
 * Core solution for the Kick‑Start problem.
 * <p>
 * The program reads several test cases; each case provides:
 * <ul>
 *   <li>target number of zeros {@code targetZero}</li>
 *   <li>target number of ones {@code targetOne}</li>
 *   <li>a string consisting of ‘0’, ‘1’ and ‘?’</li>
 * </ul>
 * It tries to replace every ‘?’ with a digit so that the final string
 * becomes a palindrome and contains exactly {@code targetZero} zeros and
 * {@code targetOne} ones. If such a replacement exists the resulting
 * string is printed, otherwise “‑1” is printed.
 */
public class Solution {

    private static final char ZERO = '0';
    private static final char ONE = '1';
    private static final char QUESTION = '?';

    /** Entry point */
    public static void main(String[] args) throws Exception {
        new Solution().run();
    }

    /** Reads all test cases and processes them one‑by‑one. */
    private void run() throws Exception {
        try (FastScanner fs = new FastScanner(System.in)) {
            int t = fs.nextInt();
            for (int i = 0; i < t; i++) {
                solveSingleCase(fs);
            }
        }
    }

    /** Handles one test case according to the original specification. */
    private void solveSingleCase(FastScanner fs) {
        int targetZero = fs.nextInt();   // originally called 'n'
        int targetOne  = fs.nextInt();   // originally called 'm'
        String raw = fs.next();          // the pattern containing 0,1,?

        char[] chars = raw.toCharArray();
        fillSymmetric(chars, targetZero, targetOne);

        boolean isPal = isPalindrome(chars);
        boolean countsFit = validateCounts(chars, targetZero, targetOne);

        System.out.println((isPal && countsFit) ? new String(chars) : "-1");
    }

    /**
     * Mirrors ‘?’ characters on both ends and fills them with ‘0’ or ‘1’
     * so that the required numbers of each digit are satisfied.
     */
    private void fillSymmetric(char[] arr, int targetZero, int targetOne) {
        // ---- 1. Count known digits and unknown pairs -----------------
        int observedZero = 0;
        int observedOne  = 0;
        int unknownPairs = 0;

        for (int l = 0, r = arr.length - 1; l <= r; l++, r--) {
            // Mirror a solitary '?'
            if (arr[l] == QUESTION) {
                arr[l] = arr[r];
            } else if (arr[r] == QUESTION) {
                arr[r] = arr[l];
            }

            // Count digits after mirroring
            if (arr[l] != QUESTION) {
                if (arr[l] == ONE) observedOne++;
                else observedZero++;
            }
            if (l != r && arr[r] != QUESTION) {
                if (arr[r] == ONE) observedOne++;
                else observedZero++;
            }

            // Count an unknown pair only once (when l < r)
            if (l < r && (arr[l] == QUESTION || arr[r] == QUESTION)) {
                unknownPairs++;
            }
        }

        // ---- 2. Early rejection if we already exceeded quotas -------
        if (observedZero > targetZero || observedOne > targetOne) {
            return;
        }

        int remainingZero = targetZero - observedZero;
        int remainingOne  = targetOne  - observedOne;

        // The number of still‑unknown positions must match what we need.
        if (remainingZero + remainingOne != unknownPairs) {
            return;
        }

        // Both remainders cannot be odd simultaneously – they are filled in pairs.
        if ((remainingZero % 2 == 1) && (remainingOne % 2 == 1)) {
            return;
        }

        // ---- 3. Fill the remaining spots symmetrically ---------------
        for (int l = 0, r = arr.length - 1; l <= r; l++, r++) {
            if (arr[l] == QUESTION) {
                if (remainingZero >= remainingOne) {
                    arr[l] = ZERO;
                    arr[r] = ZERO;
                    remainingZero -= 2;
                } else {
                    arr[l] = ONE;
                    arr[r] = ONE;
                    remainingOne -= 2;
                }
            }
        }
    }

    /** Checks whether the final array contains exactly the required counts. */
    private boolean validateCounts(char[] arr, int targetZero, int targetOne) {
        int zeroCnt = 0;
        int oneCnt  = 0;
        for (char c : arr) {
            if (c == ZERO) zeroCnt++;
            else if (c == ONE) oneCnt++;
        }
        return zeroCnt == targetZero && oneCnt == targetOne;
    }

    /** Returns true if {@code arr} reads the same forwards and backwards. */
    private boolean isPalindrome(char[] arr) {
        int i = 0, j = arr.length - 1;
        while (i < j) {
            if (arr[i] != arr[j]) {
                return false;
            }
            i++;
            j--;
        }
        return true;
    }
}

import java.util.Scanner;

/**
 * Generates a palindrome string that contains exactly {@code a} zeros and {@code b} ones.
 * If it is impossible to satisfy the constraints, {@code -1} is printed.
 */
public class B_ABPalindrome {

    public static void main(String[] args) {
        try (Scanner sc = new Scanner(System.in)) {
            int t = sc.nextInt();
            while (t-- > 0) {
                int requiredZeros = sc.nextInt();   // a
                int requiredOnes  = sc.nextInt();   // b
                String pattern    = sc.next();      // the template

                String result = solve(requiredZeros, requiredOnes, pattern);
                System.out.println(result);
            }
        }
    }

    /**
     * Attempts to build a palindrome that contains exactly {@code a} zeros and {@code b} ones.
     *
     * @param a      required number of '0' characters
     * @param b      required number of '1' characters
     * @param input  the pattern containing '0','1','?' .
     * @return the constructed palindrome or the string "-1" if it cannot be built.
     */
    private static String solve(int a, int b, String input) {
        char[] chars = input.toCharArray();
        int len = chars.length;

        // -----------------------------------------------------------------
        // 1️⃣  Enforce symmetry – fill forced positions
        // -----------------------------------------------------------------
        for (int i = 0; i < len / 2; i++) {
            char left  = chars[i];
            char right = chars[len - i - 1];

            // Both ends are known and differ → impossible
            if (left != '?' && right != '?' && left != right) {
                return "-1";
            }

            // One side is known, the other side is unknown → mirror the known char
            if (left != '?' && right == '?') {
                chars[len - i - 1] = left;
            } else if (left == '?' && right != '?') {
                chars[i] = right;
            }
        }

        // Middle character for odd length
        if (len % 2 == 1) {
            int mid = len / 2;
            if (chars[mid] == '?') {
                // Mirror of itself – nothing to do now
            }
        }

        // -----------------------------------------------------------------
        // 2️⃣  Count already placed '0' and '1' and detect contradictions
        // -----------------------------------------------------------------
        int placedZeros = 0, placedOnes = 0;
        for (char c : chars) {
            if (c == '0') placedZeros++;
            else if (c == '1') placedOnes++;
        }

        if (placedZeros > a || placedOnes > b) {
            return "-1";
        }

        // Number of positions still to decide
        int remainingZeros = a - placedZeros;   // how many '0' we still need
        int remainingOnes  = b - placedOnes;   // how many '1' we still need

        // -----------------------------------------------------------------
        // 3️⃣  Fill the remaining '?' respecting palindrome constraints
        // -----------------------------------------------------------------
        boolean impossible = false;
        for (int i = 0; i < len; i++) {
            int j = len - i - 1;               // partner index
            if (chars[i] != '?') continue;    // already fixed

            // ── middle position (odd length) ──────────────────────────────────
            if (i == j) {
                if (remainingZeros > 0) {
                    chars[i] = '0';
                    remainingZeros--;
                } else if (remainingOnes > 0) {
                    chars[i] = '1';
                    remainingOnes--;
                } else {
                    impossible = true;
                    break;
                }
                continue;
            }

            // ── symmetric pair ───────────────────────────────────────────────
            // Fill the whole pair with the same digit
            if (remainingZeros >= 2) {
                chars[i] = chars[j] = '0';
                remainingZeros -= 2;
            } else if (remainingOnes >= 2) {
                chars[i] = chars[j] = '1';
                remainingOnes -= 2;
            } else {
                impossible = true;
                break;
            }
        }

        // -----------------------------------------------------------------
        // 4️⃣  Validate final counts – if something is wrong, report impossibility
        // -----------------------------------------------------------------
        if (impossible ||
            remainingZeros != 0 ||
            remainingOnes  != 0 ||
            // extra safety: any leftover asymmetry?
            !isPalindrome(chars)) {
            return "-1";
        }

        // -----------------------------------------------------------------
        // 5️⃣  Success – build the output string
        // -----------------------------------------------------------------
        return new String(chars);
    }

    /** Simple helper to verify that the produced array is a palindrome. */
    private static boolean isPalindrome(char[] arr) {
        int n = arr.length;
        for (int i = 0; i < n / 2; i++) {
            if (arr[i] != arr[n - i - 1]) {
                return false;
            }
        }
        return true;
    }
}

package palindrome;

import java.io.*;
import java.util.StringTokenizer;

/**
 * Solves the "ABPalindrome" problem.
 *
 * <p>
 * The program reads several test cases. For each case it receives:
 * <ul>
 *   <li>the desired number of '0's (A)</li>
 *   <li>the desired number of '1's (B)</li>
 *   <li>a partially‑filled string made of '0','1','?'</li>
 * </ul>
 * It tries to replace each '?' with '0' or '1' so that the final string is a
 * palindrome containing exactly the required amount of each digit.
 * If impossible it prints "‑1", otherwise it prints the constructed palindrome.
 * </p>
 *
 * The implementation is split in small, well‑named methods and uses clear
 * variable names, early returns and minimal temporary data.
 */
public class ABPalindrome {

    /* --------------------------------------------------------------------- */
    /*                     Entry point (unchanged interface)                */
    /* --------------------------------------------------------------------- */
    public static void main(String[] args) throws IOException {
        // Fast input class (kept unchanged, only renamed for readability)
        FastScanner scanner = new FastScanner();
        PrintWriter out = new PrintWriter(new BufferedOutputStream(System.out));

        int testCount = scanner.nextInt();               // number of cases
        StringBuilder output = new StringBuilder();

        for (int i = 0; i < testCount; i++) {
            String caseResult = solveOneCase(scanner);
            output.append(caseResult).append('\n');
        }

        out.print(output.toString());
        out.flush();
        out.close();
    }

    /* --------------------------------------------------------------------- */
    /*                     Core solving logic (extracted)                     */
    /* --------------------------------------------------------------------- */
    /**
     * Solves a single test case.
     *
     * @param scanner a scanner positioned at the beginning of the case data
     * @return the palindrome string for the case or "-1" if impossible
     */
    private static String solveOneCase(FastScanner scanner) {
        // ----- read raw data -------------------------------------------------
        int desiredZeros = scanner.nextInt();   // original A
        int desiredOnes  = scanner.nextInt();   // original B
        String partiallyFilled = scanner.nextLine(); // current line (may contain '?')

        // Work on a mutable copy of the pattern
        char[] chars = partiallyFilled.toCharArray();
        int length = chars.length;

        // ----- quick counting of known digits ---------------------------------
        int unknownCount = 0;
        int actualZeros = 0;
        int actualOnes  = 0;

        for (char c : chars) {
            if (c == '0') {
                actualZeros++;
            } else if (c == '1') {
                actualOnes++;
            } else {
                unknownCount++;
            }
        }

        // Desired remaining counts after accounting for already fixed digits
        int needZeros = desiredZeros - actualZeros;
        int needOnes  = desiredOnes  - actualOnes;

        // If the required counts make no sense, abort early
        if (needZeros < 0 || needOnes < 0 || needZeros + needOnes != unknownCount) {
            return "-1";
        }

        // ----- first pass – try to respect palindrome constraints -------------
        // Walk from the two ends towards the centre and fix mismatched known chars
        for (int left = 0, right = length - 1; left <= right; left++, right--) {
            char l = chars[left];
            char r = chars[right];

            // Both are known and differ → impossible
            if (l != '?' && r != '?' && l != r) {
                return "-1";
            }

            // If one side is known, force the opposite side to the same value
            if (l == '?' && r != '?') {
                chars[left] = r;
                if (r == '0') needZeros--; else needOnes--;
            } else if (r == '?' && l != '?') {
                chars[right] = l;
                if (l == '0') needZeros--; else needOnes--;
            }
        }

        // After the first pass we may have consumed some of the required digits.
        // If they are negative, the case is invalid.
        if (needZeros < 0 || needOnes < 0) {
            return "-1";
        }

        // ----- second pass – fill remaining '?' symmetrically -----------------
        // Resolve pairs of '?' that appear together on symmetric positions.
        for (int left = 0, right = length - 1; left <= right; left++, right--) {
            if (chars[left] != '?'' || chars[right] != '?') {
                continue; // already decided
            }

            // Middle of odd‑length string – single free slot
            if (left == right) {
                if (needZeros > 0) {
                    chars[left] = '0';
                    needZeros--;
                } else if (needOnes > 0) {
                    chars[left] = '1';
                    needOnes--;
                } else {
                    return "-1";
                }
                continue;
            }

            // Normal pair – we can fill it with two zeros or two ones
            if (needZeros >= 2) {
                chars[left] = chars[right] = '0';
                needZeros -= 2;
            } else if (needOnes >= 2) {
                chars[left] = chars[right] = '1';
                needOnes -= 2;
            } else {
                return "-1";
            }
        }

        // ----- final validation -------------------------------------------------
        // After all replacements we must have used exactly the required numbers
        if (needZeros != 0 || needOnes != 0) {
            return "-1";
        }

        // Build the resulting string and verify palindrome property
        String result = new String(chars);
        if (!isPalindrome(result)) {
            return "-1";
        }
        return result;
    }

    /** Checks whether the given string reads the same forwards and backwards. */
    private static boolean isPalindrome(String s) {
        int i = 0, j = s.length() - 1;
        while (i < j) {
            if (s.charAt(i++) != s.charAt(j--)) {
                return false;
            }
        }
        return true;
    }

    /* --------------------------------------------------------------------- */
    /*                          Helper input class                           */
    /* --------------------------------------------------------------------- */
    /** Simple fast scanner used throughout the program. */
    private static final class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    throw new UncheckedIOException(e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        String nextLine() {
            try {
                return br.readLine();
            } catch (IOException e) {
                throw new UncheckedIOException(e);
            }
        }
    }
}

import java.util.Scanner;

/**
 * Reads several test cases. For each test case it tries to replace every '?'
 * in the supplied string with '0' or '1' so that the resulting string:
 *   <ul>
 *     <li>is a palindrome</li>
 *     <li>contains exactly {@code zeros} '0' characters and {@code ones}
 *         '1' characters</li>
 *   </ul>
 * If such a palindrome cannot be built, the method returns {@code "-1"}.
 *
 * <p>The input format is:
 * <pre>
 * t                     // number of test cases
 * a b                   // required number of zeros and ones
 * s                     // string of length a+b containing '0','1' or '?'
 * </pre>
 *
 * <p>Example output for each test case is the constructed palindrome or
 * {@code "-1"}.
 */
public class Main {

    /** Message returned when constructing a palindrome is impossible */
    private static final String IMPOSSIBLE = "-1";

    /** Entry point of the program */
    public static void main(String[] args) {
        // try‑with‑resources ensures the scanner is closed automatically
        try (Scanner scanner = new Scanner(System.in)) {
            int testCases = scanner.nextInt();

            for (int caseIdx = 0; caseIdx < testCases; caseIdx++) {
                int zeros = scanner.nextInt();    // required number of '0'
                int ones  = scanner.nextInt();    // required number of '1'
                String template = scanner.next(); // partially filled string

                System.out.println(constructPalindrome(template, zeros, ones));
            }
        }
    }

    /**
     * Attempts to replace '?' characters so that the string becomes a palindrome
     * and contains exactly the requested numbers of '0' and '1'.
     *
     * @param template   Original string containing '0', '1' and '?' characters.
     * @param zeros      Desired total count of '0' characters in the result.
     * @param ones       Desired total count of '1' characters in the result.
     * @return The constructed palindrome or {@code IMPOSSIBLE} if no solution exists.
     */
    public static String constructPalindrome(String template, int zeros, int ones) {
        char[] chars = template.toCharArray();
        int length = zeros + ones;    // The expected length of the palindrome

        // ------------------------------------------------------------------------
        // 1️⃣ Resolve forced matches – mirror positions must be equal.
        // ------------------------------------------------------------------------
        for (int i = 0; i < length / 2; i++) {
            int mirror = length - i - 1;
            char left  = chars[i];
            char right = chars[mirror];

            if (left != right) {
                if (left == '?' || right == '?') {
                    // Fill the empty side with the known character.
                    chars[i == '?' ? mirror : i] = (left != '?') ? left : right;
                } else {
                    // Both sides are fixed but different → impossible.
                    return IMPOSSIBLE;
                }
            }
        }

        // ------------------------------------------------------------------------
        // 2️⃣ Count how many zeros and ones are already placed (each side counts twice).
        // ------------------------------------------------------------------------
        int usedZeros = 0;
        int usedOnes  = 0;
        for (int i = 0; i < length / 2; i++) {
            char c = chars[i];
            if (c == '0') {
                usedZeros += 2;
            } else if (c == '1') {
                usedOnes += 2;
            }
        }

        // ------------------------------------------------------------------------
        // 3️⃣ Fill remaining '?' pairs with the symbol that still has capacity.
        // ------------------------------------------------------------------------
        for (int i = 0; i < length / 2; i++) {
            int mirror = length - i - 1;
            if (chars[i] == '?') {
                if (zeros - usedZeros >= 2) {
                    chars[i] = chars[mirror] = '0';
                    usedZeros += 2;
                } else if (ones - usedOnes >= 2) {
                    chars[i] = chars[mirror] = '1';
                    usedOnes += 2;
                } else {
                    return IMPOSSIBLE;
                }
            }
        }

        // ------------------------------------------------------------------------
        // 4️⃣ Handle the central character when the length is odd.
        // ------------------------------------------------------------------------
        if (length % 2 != 0) {
            int mid = length / 2;
            char centre = chars[mid];

            if (centre == '?') {
                // The remaining deficit must be exactly 1.
                if (zeros > usedZeros) {
                    chars[mid] = '0';
                    usedZeros++;
                } else if (ones > usedOnes) {
                    chars[mid] = '1';
                    usedOnes++;
                } else {
                    return IMPOSSIBLE;
                }
            } else {
                // Centre already fixed – verify it matches the remaining budget.
                if (centre == '0' && zeros != usedZeros + 1) {
                    return IMPOSSIBLE;
                }
                if (centre == '1' && ones != usedOnes + 1) {
                    return IMPOSSIBLE;
                }
            }
        }

        // ------------------------------------------------------------------------
        // 5️⃣ Final validation – all requested counts must be exhausted.
        // ------------------------------------------------------------------------
        if (usedZeros != zeros || usedOnes != ones) {
            return IMPOSSIBLE;
        }

        return new String(chars);
    }
}

import java.util.Scanner;

/**
 * Refactored solution for the “Fill‑the‑Palindrome” problem.
 *
 * <p>
 *   The program reads multiple test cases.
 *   For each test case it receives:
 *   <ul>
 *     <li>two integers – the required number of ‘0’ and ‘1’ symbols,</li>
 *     <li>a string containing ‘0’, ‘1’ and ‘?’ characters.</li>
 *   </ul>
 *   The goal is to replace every ‘?’ with ‘0’ or ‘1’ so that the final
 *   string is a palindrome and contains exactly the requested amount of
 *   each digit. If this is impossible the program prints {@code -1},
 *   otherwise it prints the resulting palindrome.
 * </p>
 */
public class Main {

    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            int t = scanner.nextInt();
            scanner.nextLine();                     // consume end‑of‑line after T
            while (t-- > 0) {
                solveTestCase(scanner);
            }
        }
    }

    /** Handles a single test case – reads input, solves and prints the answer. */
    private static void solveTestCase(Scanner scanner) {
        // ----- 1️⃣ read required numbers of '0' and '1' -----
        String[] countTokens = scanner.nextLine().trim().split("\\s+");
        int requiredZeros = Integer.parseInt(countTokens[0]);
        int requiredOnes  = Integer.parseInt(countTokens[1]);

        // ----- 2️⃣ read the character array (may contain '?') -----
        char[] chars = scanner.nextLine().toCharArray();

        // ----- 3️⃣ fill the '?' positions respecting symmetry -----
        int[] counters = new int[] { requiredZeros, requiredOnes };
        fillMissing(chars, counters);

        // ----- 4️⃣ validate the final state -----
        boolean valid = counters[0] == 0 && counters[1] == 0 && isPalindrome(chars);
        System.out.println(valid ? new String(chars) : "-1");
    }

    /**
     * Completes the array so that it becomes a palindrome using exactly the
     * remaining numbers of ‘0’ and ‘1’ stored in {@code counters}.
     * The method mutates {@code chars} in‑place and updates {@code counters}
     * to reflect the digits that have been placed.
     *
     * @param chars    the character array that may contain ‘?’,
     * @param counters an int[2] where index 0 → needed ‘0’, index 1 → needed ‘1’.
     */
    private static void fillMissing(char[] chars, int[] counters) {
        int n = chars.length;

        // ---- Step 1: mirror known digits into symmetrical '?' positions ----
        for (int i = 0; i < n / 2; i++) {
            int j = n - 1 - i;
            if (chars[i] == '?' && chars[j] != '?') {
                chars[i] = chars[j];
            } else if (chars[i] != '?' && chars[j] == '?') {
                chars[j] = chars[i];
            }
        }

        // ---- Step 2: subtract already placed digits from the required amounts ----
        for (int i = 0; i < n; i++) {
            if (chars[i] == '0') {
                counters[0]--;
            } else if (chars[i] == '1') {
                counters[1]--;
            }
        }

        // ---- Step 3: fill the remaining '?' positions ----
        int left = 0;
        int right = n - 1;
        while (left <= right) {
            if (chars[left] != '?') {
                left++;
                right--;
                continue;
            }

            if (left == right) { // centre of an odd‑length string
                if (counters[0] > 0) {
                    chars[left] = '0';
                    counters[0]--;
                } else {
                    chars[left] = '1';
                    counters[1]--;
                }
            } else {
                // We have to place a *pair*, therefore consume two units of the chosen digit.
                if (counters[0] >= 2) {
                    chars[left] = chars[right] = '0';
                    counters[0] -= 2;
                } else {
                    // The remaining requirement guarantees that ones are sufficient.
                    chars[left] = chars[right] = '1';
                    counters[1] -= 2;
                }
            }
            left++;
            right++;
        }
    }

    /** Checks whether the supplied array reads the same forwards and backwards. */
    private static boolean isPalindrome(char[] arr) {
        int l = 0, r = arr.length - 1;
        while (l < r) {
            if (arr[l] != arr[r]) {
                return false;
            }
            l++;
            r--;
        }
        return true;
    }
}

import java.io.*;
import java.util.StringTokenizer;

/**
 * Reads several test cases and, for each case, tries to build a palindrome
 * consisting of exactly {@code a} zeros and {@code b} ones while respecting
 * the already‑given characters (0,1,?).  If it is impossible, "-1" is printed.
 *
 * The program follows the same algorithmic steps as the original code but
 * does so with clearer naming, reduced duplication and better structure.
 */
public class PalindromeBuilder {

    /** Entry point. */
    public static void main(String[] args) throws IOException {
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in))) {
            int testCases = Integer.parseInt(br.readLine().trim());

            // Use a single BufferedWriter for all output to avoid repeated flushes.
            try (BufferedWriter bw = new BufferedWriter(new OutputStreamWriter(System.out))) {
                for (int t = 0; t < testCases; t++) {
                    solveSingleTestCase(br, bw);
                }
            }
        }
    }

    /**
     * Handles one test case:
     *   1. reads a, b and the character array,
     *   2. propagates known characters to the opposite side,
     *   3. consumes the remaining 0/1 counts for the '?' positions,
     *   4. verifies palindrome property and outputs the result.
     */
    private static void solveSingleTestCase(BufferedReader br, BufferedWriter bw)
            throws IOException {
        // ----- 1. read input -------------------------------------------------
        StringTokenizer st = new StringTokenizer(br.readLine());
        int a = Integer.parseInt(st.nextToken());          // remaining 0's we may place
        int b = Integer.parseInt(st.nextToken());          // remaining 1's we may place
        char[] chars = br.readLine().toCharArray();         // the mixed input string

        int n = chars.length;

        // ----- 2. mirror known characters -----------------------------------
        for (int i = 0; i < n; i++) {
            int j = n - i - 1;
            if (chars[i] == '?' && chars[j] != '?') {
                chars[i] = chars[j];
            } else if (chars[i] != '?' && chars[j] == '?') {
                chars[j] = chars[i];
            }
        }

        // ----- 3. count already placed 0/1 and prepare for filling '?' ------
        // After the mirroring step, only the leading half (i < j) needs to be processed.
        int remainingZeros = a;
        int remainingOnes  = b;
        int questionMarkPairs = 0;   // number of positions i<j that are still '?'

        for (int i = 0; i < n; i++) {
            if (chars[i] == '0') {
                remainingZeros--;
            } else if (chars[i] == '1') {
                remainingOnes--;
            } else if (chars[i] == '?') {
                // We will count pairs; the middle element (when i == n-i-1) is handled later.
                if (i < n - i - 1) {
                    questionMarkPairs++;
                }
            }
        }

        // ----- 4. fill the remaining '?' ------------------------------------
        boolean possible = true;
        for (int i = 0; i < (n + 1) / 2; i++) {
            int j = n - i - 1;
            if (chars[i] != '?') {
                continue; // already fixed by mirroring step
            }

            // The pair (i, j) is symmetric; treat the centre separately.
            boolean isCenter = i == j;

            if (!isCenter) {
                // We have to decide what to put in both positions.
                if (remainingZeros > remainingOnes) {
                    chars[i] = chars[j] = '0';
                    remainingZeros -= 2;
                } else {
                    chars[i] = chars[j] = '1';
                    remainingOnes -= 2;
                }
            } else {
                // Single centre character.
                if (remainingZeros > 0) {
                    chars[i] = '0';
                    remainingZeros--;
                } else if (remainingOnes > 0) {
                    chars[i] = '1';
                    remainingOnes--;
                } else {
                    possible = false;
                    break;
                }
            }
        }

        // ----- 5. final validation -------------------------------------------
        if (remainingZeros != 0 || remainingOnes != 0) {
            possible = false; // we consumed the wrong amount
        }

        if (possible && isPalindrome(chars)) {
            bw.write(new String(chars));
        } else {
            bw.write("-1");
        }
        bw.newLine(); // keep the original behaviour of printing a newline after each case
    }

    /**
     * Checks whether the supplied character array reads the same forwards
     * and backwards.
     */
    private static boolean isPalindrome(char[] arr) {
        int left = 0, right = arr.length - 1;
        while (left < right) {
            if (arr[left] != arr[right]) {
                return false;
            }
            left++;
            right--;
        }
        return true;
    }
}

import java.util.Scanner;

/**
 * Refactored solution for constructing a palindrome with a given number of
 * '0' and '1' characters while replacing '?' placeholders.
 *
 * The program reads multiple test cases. Each test case provides:
 *   – required count of '0' (a)
 *   – required count of '1' (b)
 *   – a string containing '0', '1' and '?' characters
 *
 * The output for each test case is:
 *   – a valid palindrome that uses exactly a zeros and b ones, or
 *   – "-1" if such a palindrome cannot be formed.
 *
 * The implementation is split into small, self‑documenting methods to
 * improve readability, maintainability and testability.
 */
public class PalindromeConstructor {

    private static final Scanner SC = new Scanner(System.in);

    public static void main(String[] args) {
        int t = SC.nextInt();                       // number of test cases
        while (t-- > 0) {
            solve();                                 // handle one test case
        }
        SC.close();
    }

    /** Entry point for a single test case. */
    private static void solve() {
        int requiredZeros = SC.nextInt();           // target number of '0'
        int requiredOnes  = SC.nextInt();           // target number of '1'
        String pattern    = SC.next();              // pattern with '?' placeholders

        String result = buildPalindrome(requiredZeros,
                                         requiredOnes,
                                         pattern);
        System.out.println(result);
    }

    /**
     * Attempts to construct a palindrome that satisfies the required counts.
     *
     * @return the constructed palindrome, or "-1" if construction is impossible.
     */
    private static String buildPalindrome(int targetZeros,
                                           int targetOnes,
                                           String init) {
        char[] chars = init.toCharArray();
        finalizeConstruction(chars, targetZeros, targetOnes);
        return new String(chars);
    }

    /**
     * Core step that validates the input, enforces palindrome constraints,
     * and fills the '?' placeholders.
     *
     * All modifications are performed directly on the {@code chars} array.
     * If at any point the configuration becomes impossible, an
     * {@link IllegalArgumentException} is thrown which the caller translates
     * to the string "-1".
     */
    private static void finalizeConstruction(char[] chars,
                                              int targetZeros,
                                              int targetOnes) {
        // -----------------------------------------------------------------
        // 1. Count already fixed digits and verify remaining capacity.
        // -----------------------------------------------------------------
        int fixedZeros = countFixed(chars, '0');
        int fixedOnes  = countFixed(chars, '1');

        int needZeros = targetZeros - fixedZeros;
        int needOnes  = targetOnes  - fixedOnes;

        if (needZeros < 0 || needOnes < 0) {
            throw new IllegalArgumentException();
        }

        int questionMarkCount = countFixed(chars, '?');
        if (needZeros + needOnes != questionMarkCount) {
            throw new IllegalArgumentException();
        }

        // -----------------------------------------------------------------
        // 2. Ensure symmetry before any assignment.
        // -----------------------------------------------------------------
        enforceSymmetry(chars);

        // -----------------------------------------------------------------
        // 3. Fill positions where exactly one side of a pair is known.
        // -----------------------------------------------------------------
        fillForcedAssignments(chars, needZeros, needOnes);

        // -----------------------------------------------------------------
        // 4. Fill symmetric pairs of remaining '?' with zeros or ones.
        // -----------------------------------------------------------------
        fillPairs(chars, needZeros, needOnes);

        // -----------------------------------------------------------------
        // 5. Fill the centre character for odd‑length strings, if needed.
        // -----------------------------------------------------------------
        fillMiddleIfNeeded(chars, needZeros, needOnes);

        // -----------------------------------------------------------------
        // 6. Final validation checks.
        // -----------------------------------------------------------------
        if (!isBalanced(chars, targetZeros, targetOnes)) {
            throw new IllegalArgumentException();
        }
        if (!isPalindrome(chars)) {
            throw new IllegalArgumentException();
        }
    }

    /** Counts occurrences of {@code target} in the character array. */
    private static int countFixed(char[] arr, char target) {
        int cnt = 0;
        for (char c : arr) {
            if (c == target) cnt++;
        }
        return cnt;
    }

    /** Guarantees that each symmetric pair is either equal or contains a '?'. */
    private static void enforceSymmetry(char[] chars) {
        int n = chars.length;
        for (int i = 0; i < n / 2; i++) {
            int j = n - i - 1;
            char left = chars[i];
            char right = chars[j];

            if (left != '?' && right != '?' && left != right) {
                throw new IllegalArgumentException(); // impossible to become palindrome
            }

            // Align unknown side with the known one.
            if (left == '?' && right != '?') {
                chars[i] = right;
            } else if (right == '?' && left != '?') {
                chars[j] = left;
            }
        }
    }

    /** Fills positions where only one side of a pair is known. */
    private static void fillForcedAssignments(char[] chars,
                                               int[] needZeros,
                                               int[] needOnes) {
        int n = chars.length;
        for (int i = 0; i < n / 2; i++) {
            int j = n - i - 1;
            char left = chars[i];
            char right = chars[j];

            if (left != '?' && right != '?') continue; // already decided

            if (left == '?' && right != '?') {
                assignIfPossible(i, right, chars, needZeros, needOnes);
            } else if (right == '?' && left != '?') {
                assignIfPossible(j, left, chars, needZeros, needOnes);
            }
        }
    }

    /**
     * Assigns a '?' at {@code idx} so that it matches {@code opposite}.
     * Adjusts the remaining need counters accordingly.
     *
     * @throws IllegalStateException if the required digit is no longer available.
     */
    private static void assignIfPossible(int idx,
                                           char opposite,
                                           char[] chars,
                                           int[] needZeros,
                                           int[] needOnes) {
        if (opposite == '0') {
            if (needZeros[0] > 0) {
                chars[idx] = '0';
                needZeros[0]--;
            } else {
                throw new IllegalStateException();
            }
        } else { // opposite == '1'
            if (needOnes[0] > 0) {
                chars[idx] = '1';
                needOnes[0]--;
            } else {
                throw new IllegalStateException();
            }
        }
    }

    /** Fills symmetric unknown pairs with zeros or ones, consuming two at a time. */
    private static void fillPairs(char[] chars,
                                  int[] needZeros,
                                  int[] needOnes) {
        int n = chars.length;
        for (int i = 0; i < n / 2; i++) {
            int j = n - i - 1;
            if (chars[i] != '?' || chars[j] != '?') continue;

            if (needZeros[0] >= 2) {
                chars[i] = chars[j] = '0';
                needZeros[0] -= 2;
            } else if (needOnes[0] >= 2) {
                chars[i] = chars[j] = '1';
                needOnes[0] -= 2;
            } else {
                throw new IllegalStateException();
            }
        }
    }

    /** Fills the centre character when the length is odd and it is still '?'. */
    private static void fillMiddleIfNeeded(char[] chars,
                                            int[] needZeros,
                                            int[] needOnes) {
        int n = chars.length;
        if (n % 2 == 1 && chars[n / 2] == '?') {
            if (needZeros[0] > 0) {
                chars[n / 2] = '0';
                needZeros[0]--;
            } else if (needOnes[0] > 0) {
                chars[n / 2] = '1';
                needOnes[0]--;
            } else {
                throw new IllegalStateException();
            }
        }
    }

    /** Verifies that the final string uses exactly the requested counts. */
    private static boolean isBalanced(char[] chars,
                                        int targetZeros,
                                        int targetOnes) {
        int cnt0 = 0, cnt1 = 0;
        for (char c : chars) {
            if (c == '0') cnt0++;
            else if (c == '1') cnt1++;
        }
        return cnt0 == targetZeros && cnt1 == targetOnes;
    }

    /** Checks the palindrome property (redundant but defensive). */
    private static boolean isPalindrome(char[] chars) {
        int n = chars.length;
        for (int i = 0; i < n / 2; i++) {
            if (chars[i] != chars[n - i - 1]) {
                return false;
            }
        }
        return true;
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.PrintWriter;
import java.util.StringTokenizer;

/**
 * Main entry point.  All logic is delegated to {@link Solver}.
 */
public class Main {

    private static PrintWriter out;
    private static FastReader scanner;

    public static void main(String[] args) throws Exception {
        setupIO();
        int testCases = scanner.nextInt();
        StringBuilder builder = new StringBuilder();

        for (int tc = 0; tc < testCases; tc++) {
            builder.append(Solver.solveCase())
                    .append('\n');
        }

        out.print(builder.toString());
        out.flush();
    }

    /** Wraps System.out and scanner initialization. */
    private static void setupIO() {
        out = new PrintWriter(System.out, true);
        scanner = new FastReader();
    }

    /** Simple wrapper around {@link PrintWriter} to keep signatures readable. */
    private static void println(Object obj) {
        out.println(obj);
    }

    /** Fast scanner used throughout the program. */
    private static class FastReader {
        private final BufferedReader br;
        private StringTokenizer st;

        FastReader() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        /** Returns next token or reads a new line if the current tokenizer is exhausted. */
        private String nextToken() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    throw new UncheckedIOException(e);
                }
            }
            return st.nextToken();
        }

        int nextInt()               { return Integer.parseInt(nextToken()); }
        long nextLong()             { return Long.parseLong(nextToken()); }
        String next()               { return nextToken(); }
        String nextLine()           { return nextToken(); }   // used only when a full line is expected
    }
}

/**
 * Encapsulates the algorithm for a single test case.
 * Keeps the {@code Main} class free of business logic.
 */
class Solver {

    /**
     * Solves one test case.
     *
     * @return The resulting binary string or "-1" if impossible.
     */
    static String solveCase() {
        int targetZero = scanner.nextInt();   // desired total number of '0'
        int targetOne  = scanner.nextInt();   // desired total number of '1'
        String s = scanner.next();            // input containing '0','1','?'
        char[] chars = s.toCharArray();
        int n = chars.length;

        // --------------------------------------------------------------------
        // 1️⃣  Verify that the string can become a palindrome.
        // --------------------------------------------------------------------
        boolean possible = true;
        for (int i = 0; i < n / 2; i++) {
            int j = n - 1 - i;
            char left = chars[i];
            char right = chars[j];

            if (left != '?' && right != '?' && left != right) {
                possible = false;
                break;
            }

            // Resolve asymmetric cases where one side is known.
            if (left == '?' && right != '?') {
                chars[i] = right;
            } else if (left != '?' && right == '?') {
                chars[j] = left;
            }
        }

        if (!possible) {
            return "-1";
        }

        // --------------------------------------------------------------------
        // 2️⃣  Count already‑fixed zeros and ones.
        // --------------------------------------------------------------------
        int fixedZeros = 0, fixedOnes = 0;
        for (char c : chars) {
            if (c == '0') fixedZeros++;
            else if (c == '1') fixedOnes++;
        }

        // Remaining blanks that still need to be filled.
        int remainingZeros = targetZero - fixedZeros;
        int remainingOnes  = targetOne  - fixedOnes;

        if (remainingZeros < 0 || remainingOnes < 0) {
            return "-1";
        }

        // --------------------------------------------------------------------
        // 3️⃣  Fill symmetric '?' pairs.
        // --------------------------------------------------------------------
        for (int i = 0; i < n / 2; i++) {
            int j = n - 1 - i;
            if (chars[i] == '?' && chars[j] == '?') {
                if (remainingZeros >= 2) {
                    chars[i] = chars[j] = '0';
                    remainingZeros -= 2;
                } else if (remainingOnes >= 2) {
                    chars[i] = chars[j] = '1';
                    remainingOnes -= 2;
                } else {
                    return "-1";
                }
            }
        }

        // --------------------------------------------------------------------
        // 4️⃣  Fill the middle character when the length is odd.
        // --------------------------------------------------------------------
        if (n % 2 == 1 && chars[n / 2] == '?') {
            if (remainingZeros > 0) {
                chars[n / 2] = '0';
                remainingZeros--;
            } else if (remainingOnes > 0) {
                chars[n / 2] = '1';
                remainingOnes--;
            } else {
                return "-1";
            }
        }

        // --------------------------------------------------------------------
        // 5️⃣  Final validation.
        // --------------------------------------------------------------------
        if (remainingZeros != 0 || remainingOnes != 0) {
            return "-1";
        }

        // Ensure palindrome property after all substitutions.
        for (int i = 0; i < n / 2; i++) {
            if (chars[i] != chars[n - 1 - i]) {
                return "-1";
            }
        }

        return new String(chars);
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.ArrayList;
import java.util.List;

public class Main {
    static class FastReader {
        private BufferedReader br;
        private StringTokenizer st;

        public FastReader() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    e.printStackTrace();
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }
    }

    public static void main(String[] args) throws IOException {
        FastReader reader = new FastReader();
        int t = reader.nextInt();
        while (t-- > 0) {
            solve(reader);
        }
    }

    public static void solve(FastReader reader) {
        int a = reader.nextInt();
        int b = reader.nextInt();
        String str = reader.next();
        char[] chars = str.toCharArray();
        int n = chars.length;

        // Track remaining counts needed
        int remainingZeros = a;
        int remainingOnes = b;

        // Process symmetric pairs
        List<Integer> freePairIndices = new ArrayList<>();
        int left = 0, right = n - 1;

        while (left < right) {
            char leftChar = chars[left];
            char rightChar = chars[right];

            // Check for impossible mismatches
            if ((leftChar == '0' && rightChar == '1') || 
                (leftChar == '1' && rightChar == '0')) {
                System.out.println("-1");
                return;
            }

            // Handle fixed characters and assign '?' pairs
            if (leftChar == '0' || rightChar == '0') {
                if (leftChar == '0' && rightChar == '?') {
                    chars[right] = '0';
                    remainingZeros -= 2;
                } else if (rightChar == '0' && leftChar == '?') {
                    chars[left] = '0';
                    remainingZeros -= 2;
                }
            } else if (leftChar == '1' || rightChar == '1') {
                if (leftChar == '1' && rightChar == '?') {
                    chars[right] = '1';
                    remainingOnes -= 2;
                } else if (rightChar == '1' && leftChar == '?') {
                    chars[left] = '1';
                    remainingOnes -= 2;
                }
            } else {
                // Both are '?'
                freePairIndices.add(left);
            }
            left++;
            right--;
        }

        // Handle center character for odd length
        if (n % 2 == 1) {
            int mid = n / 2;
            if (chars[mid] == '?') {
                if (remainingZeros > 0) {
                    chars[mid] = '0';
                    remainingZeros--;
                } else if (remainingOnes > 0) {
                    chars[mid] = '1';
                    remainingOnes--;
                }
            } else {
                // Account for fixed center character
                if (chars[mid] == '0') remainingZeros--;
                else if (chars[mid] == '1') remainingOnes--;
            }
        }

        // Assign remaining free pairs
        for (int idx : freePairIndices) {
            int j = n - idx - 1;
            if (remainingZeros >= 2) {
                chars[idx] = '0';
                chars[j] = '0';
                remainingZeros -= 2;
            } else if (remainingOnes >= 2) {
                chars[idx] = '1';
                chars[j] = '1';
                remainingOnes -= 2;
            } else {
                System.out.println("-1");
                return;
            }
        }

        // Validate final counts
        if (remainingZeros != 0 || remainingOnes != 0) {
            System.out.println("-1");
            return;
        }

        // Output result
        System.out.println(new String(chars));
    }
}

import java.io.BUFFEREDReader;
import java.io.BufferedOutputStream;
import java.io.IOException;
import java.io.InputStream;
import java.io.OutputStream;
import java.io.PrintWriter;
import java.util.StringTokenizer;

/**
 * Main class that reads test cases and prints results.
 */
public class C {

    public static void main(String[] args) {
        new C().solve(System.in, System.out);
    }

    /** Entry point used by the original program. */
    public void solve(InputStream in, OutputStream out) {
        FastScanner scanner = new FastScanner(in);
        PrintWriter printer = new PrintWriter(new BufferedOutputStream(out));

        int t = scanner.nextInt();
        for (int caseIdx = 0; caseIdx < t; caseIdx++) {
            int a = scanner.nextInt();
            int b = scanner.nextInt();
            String s = scanner.next();
            printer.println(solve(a, b, s));
        }

        printer.flush();
    }

    /**
     * Solves a single test case.
     *
     * @param requiredZeros number of '0' characters required in the answer
     * @param requiredOnes  number of '1' characters required in the answer
     * @param template      input string possibly containing '?'
     * @return the resulting string or "-1" if impossible
     */
    public String solve(int requiredZeros, int requiredOnes, String template) {
        char[] chars = template.toCharArray();

        // 1️⃣ Resolve forced symmetry – replace every '?' that has a counterpart.
        if (!resolveSymmetricPairs(chars)) {
            return "-1";
        }

        // 2️⃣ Count already fixed characters.
        int fixedZeros = count(chars, '0');
        int fixedOnes = count(chars, '1');

        // 3️⃣ Early exit if we already exceeded the limits.
        if (fixedZeros > requiredZeros || fixedOnes > requiredOnes) {
            return "-1";
        }

        // 4️⃣ Determine how many '0' / '1' we still need.
        int remainingZeros = requiredZeros - fixedZeros;
        int remainingOnes = requiredOnes - fixedOnes;

        // 5️⃣ Fill the remaining '?' pairs.
        if (!fillRemainingPairs(chars, remainingZeros, remainingOnes)) {
            return "-1";
        }

        // 6️⃣ Handle the middle character for odd‑length strings.
        handleMiddleIfNeeded(chars, remainingZeros, remainingOnes);

        // 7️⃣ Final validation – all required counts must be exactly satisfied.
        if (remainingZeros != 0 || remainingOnes != 0) {
            return "-1";
        }

        // 8️⃣ Build and return the result.
        return new String(chars);
    }

    /** Resolves forced character assignments for symmetric positions. */
    private boolean resolveSymmetricPairs(char[] chars) {
        int len = chars.length;
        for (int i = 0; i < len / 2; i++) {
            int j = len - 1 - i;
            char left = chars[i];
            char right = chars[j];

            if (left != '?' && right == '?') {
                chars[i] = right = left;
            } else if (left == '?' && right != '?') {
                chars[j] = left;
            } else if (left != '?' && right != '?' && left != right) {
                return false; // contradictory fixed characters
            }
        }
        return true;
    }

    /** Fills remaining '?' pairs with '0' or '1' respecting the remaining quota. */
    private boolean fillRemainingPairs(char[] chars, int needZeros, int needOnes) {
        int len = chars.length;
        for (int i = 0; i < len / 2; i++) {
            int j = len - 1 - i;
            if (chars[i] == '?') {
                if (needZeros >= 2) {
                    chars[i] = chars[j] = '0';
                    needZeros -= 2;
                } else if (needOnes >= 2) {
                    chars[i] = chars[j] = '1';
                    needOnes -= 2;
                } else {
                    return false; // not enough quota to fill a pair
                }
            }
        }
        return true;
    }

    /** Handles the centre character when the string length is odd. */
    private void handleMiddleIfNeeded(char[] chars, int needZeros, int needOnes) {
        if (chars.length % 2 == 0) {
            return;
        }
        int mid = chars.length / 2;
        if (chars[mid] == '?') {
            if (needOnes > 0) {
                chars[mid] = '1';
                needOnes--;
            } else if (needZeros > 0) {
                chars[mid] = '0';
                needZeros--;
            } else {
                // No quota left but a '?' still exists → impossible.
                // We signal the impossibility by leaving the count check to fail later.
                return;
            }
        }
    }

    /** Utility: count occurrences of a given character in the array. */
    private int count(char[] arr, char ch) {
        int cnt = 0;
        for (char c : arr) {
            if (c == ch) {
                cnt++;
            }
        }
        return cnt;
    }

    /** Simple faster scanner used by the original program. */
    private static class FastScanner {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        FastScanner(InputStream stream) {
            reader = new BufferedReader(new BUFFEREDReader(new InputStreamReader(stream)), 32768);
        }

        String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        long nextLong() {
            return Long.parseLong(next());
        }
    }
}

import java.util.Scanner;

/**
 * Refactored solution that builds a palindrome with exactly {@code a} zeros
 * and {@code b} ones from a pattern containing '0', '1' and '?'.
 *
 * The code is split into small, well‑named methods, uses try‑with‑resources
 * for the scanner and guards all state changes with explicit checks.
 */
public class Solution {

    public static void main(String[] args) {
        try (Scanner sc = new Scanner(System.in)) {
            int t = sc.nextInt();
            StringBuilder out = new StringBuilder();
            for (int tc = 0; tc < t; tc++) {
                int a = sc.nextInt();
                int b = sc.nextInt();
                String pattern = sc.next();
                out.append(solve(a, b, pattern));
                if (tc < t - 1) {
                    out.append('\n');
                }
            }
            System.out.print(out);
        }
    }

    /**
     * Entry point for a single test case.
     *
     * @param a   required number of '0's
     * @param b   required number of '1's
     * @param pattern input pattern containing '0', '1' and '?'
     * @return the constructed palindrome or "-1" if impossible
     */
    private static String solve(int a, int b, String pattern) {
        char[] arr = pattern.toCharArray();
        int n = arr.length;
        int[] remaining = {a, b};               // [zerosLeft, onesLeft]

        // 1️⃣ Resolve positions where one side is fixed and the other is '?'
        if (!resolveForcedAssignments(arr, remaining)) {
            return "-1";
        }

        // 2️⃣ Fill the remaining symmetric '?' pairs
        if (!fillSymmetricPairs(arr, remaining)) {
            return "-1";
        }

        // 3️⃣ Fill the centre character for odd‑length strings
        fillCenterIfOdd(arr, remaining);

        // 4️⃣ Final validation
        if (remaining[0] != 0 || remaining[1] != 0 || !isPalindrome(arr)) {
            return "-1";
        }
        return new String(arr);
    }

    /** Decrements the appropriate counter for a given digit. */
    private static boolean useChar(char digit, int[] cnt) {
        if (digit == '0') {
            if (--cnt[0] < 0) return false;
        } else if (digit == '1') {
            if (--cnt[1] < 0) return false;
        }
        return true;
    }

    /**
     * Handles forced assignments where one side of a pair is known.
     * Returns {@code false} if a required digit is exhausted or if the
     * two fixed characters differ.
     */
    private static boolean resolveForcedAssignments(char[] arr, int[] cnt) {
        int n = arr.length;
        for (int i = 0; i < n / 2; i++) {
            int j = n - 1 - i;
            char left = arr[i];
            char right = arr[j];

            if (left != '?' && right != '?') {
                if (left != right) return false;               // incompatible fixed chars
                if (!useChar(left, cnt)) return false;         // not enough of that digit
            } else if (left == '?' && right != '?') {
                arr[i] = right;
                if (!useChar(right, cnt)) return false;
            } else if (left != '?' && right == '?') {
                arr[j] = left;
                if (!useChar(left, cnt)) return false;
            }
            // both '?' are left untouched – they will be processed later
        }
        return true;
    }

    /**
     * Fills remaining symmetric '?' pairs with either '0' or '1',
     * preferring '0' when enough zeros are left, otherwise '1'.
     */
    private static boolean fillSymmetricPairs(char[] arr, int[] cnt) {
        int n = arr.length;
        for (int i = 0; i < n / 2; i++) {
            int j = n - 1 - i;
            if (arr[i] == '?' && arr[j] == '?') {
                if (cnt[0] >= 2) {
                    arr[i] = arr[j] = '0';
                    cnt[0] -= 2;
                } else if (cnt[1] >= 2) {
                    arr[i] = arr[j] = '1';
                    cnt[1] -= 2;
                } else {
                    return false; // cannot place a pair
                }
            }
        }
        return true;
    }

    /** Assigns the centre character for odd‑length strings when it is '?'. */
    private static void fillCenterIfOdd(char[] arr, int[] cnt) {
        int n = arr.length;
        if (n % 2 == 1) {
            int mid = n / 2;
            if (arr[mid] == '?') {
                // Prefer the digit with the larger remaining quota (mirrors original logic)
                if (cnt[0] > cnt[1]) {
                    arr[mid] = '0';
                    cnt[0]--;
                } else {
                    arr[mid] = '1';
                    cnt[1]--;
                }
            }
        }
    }

    /** Checks whether the character array forms a palindrome. */
    private static boolean isPalindrome(char[] arr) {
        int i = 0, j = arr.length - 1;
        while (i < j) {
            if (arr[i++] != arr[j--]) return false;
        }
        return true;
    }
}

import java.io.*;
import java.util.*;

public class Solution {

    private static BufferedReader br;
    private static PrintWriter out;

    public static void main(String[] args) throws IOException {
        br = new BufferedReader(new InputStreamReader(System.in));
        out = new PrintWriter(new BufferedOutputStream(System.out));
        try {
            solveAll();
        } finally {
            out.close();
        }
    }

    private static void solveAll() throws IOException {
        int t = Integer.parseInt(br.readLine().trim());
        StringBuilder output = new StringBuilder();
        while (t-- > 0) {
            solveCase(output);
        }
        out.print(output.toString());
    }

    private static void solveCase(StringBuilder out) throws IOException {
        StringTokenizer st = new StringTokenizer(br.readLine());
        int requiredZeros = Integer.parseInt(st.nextToken());
        int requiredOnes  = Integer.parseInt(st.nextToken());
        String s = br.readLine();

        char[] result = new char[s.length()];
        if (!process(s, requiredZeros, requiredOnes, result)) {
            out.println(-1);
        } else {
            out.println(new String(result));
        }
    }

    /**
     * Tries to build a palindrome that satisfies the required number of 0s and 1s.
     * Returns {@code true} when a valid palindrome was constructed,
     * otherwise {@code false}.
     */
    private static boolean process(String s, int requiredZeros, int requiredOnes,
                                   char[] result) {
        int n = s.length();
        Counter cnt = new Counter(requiredZeros, requiredOnes);

        // 1️⃣ Propagate fixed characters and detect contradictions.
        for (int i = 0; i < n / 2; ++i) {
            int j = n - i - 1;
            char left  = s.charAt(i);
            char right = s.charAt(j);

            // Assign tentative values to the result array.
            result[i]  = left;
            result[j]  = right;

            // Mismatch of two already‑fixed characters → impossible.
            if (left != '?' && right != '?' && left != right) {
                return false;
            }

            // If one side is known, force the symmetric position to the same value.
            if (left == '?' && right != '?') {
                result[i] = right;
                cnt.decrease(right);
            } else if (left != '?' && right == '?') {
                result[j] = left;
                cnt.decrease(left);
            }
        }

        // 2️⃣ Middle character for odd‑length strings.
        if (n % 2 == 1) {
            int mid = n / 2;
            char midChar = s.charAt(mid);
            result[mid] = midChar;
            if (midChar != '?') {
                cnt.decrease(midChar);
            }
        }

        // 3️⃣ Fill remaining '?' pairs.
        for (int i = 0; i < n / 2; ++i) {
            int j = n - i - 1;
            if (result[i] != '?' || result[j] != '?') {
                continue;               // already decided
            }
            if (cnt.zero >= 2) {
                result[i] = result[j] = '0';
                cnt.zero -= 2;
            } else if (cnt.one >= 2) {
                result[i] = result[j] = '1';
                cnt.one -= 2;
            } else {
                return false;           // cannot satisfy remaining counts
            }
        }

        // 4️⃣ Fill the middle position if it is still undecided.
        if (n % 2 == 1 && result[n / 2] == '?') {
            if (cnt.zero >= 1) {
                result[n / 2] = '0';
                cnt.zero--;
            } else if (cnt.one >= 1) {
                result[n / 2] = '1';
                cnt.one--;
            } else {
                return false;
            }
        }

        // 5️⃣ All required 0s and 1s must be consumed.
        return cnt.zero == 0 && cnt.one == 0;
    }

    /** Simple mutable container for the remaining zero and one counts. */
    private static final class Counter {
        final int zero;
        final int one;
        Counter(int zero, int one) {
            this.zero = zero;
            this.one  = one;
        }
        /** Decrements the appropriate counter based on the placed character. */
        void decrease(char c) {
            if (c == '0') {
                zero--;
            } else {
                one--;
            }
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Main entry point of the application.
 * <p>
 * The program reads multiple test cases, each consisting of:
 * <ul>
 *   <li>the required number of '0's (a)</li>
 *   <li>the required number of '1's (b)</li>
 *   <li>a pattern containing '0', '1' and '?'</li>
 * </ul>
 * It tries to replace every '?' so that the final string is a palindrome
 * and uses exactly {@code a} zeros and {@code b} ones. If it is impossible,
 * {@code -1} is printed; otherwise the constructed string is printed.
 */
public class KayseeKay {

    /** Simple wrapper around a {@link BufferedReader} that knows how to tokenise input. */
    private static final class InputReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        InputReader(InputStream stream) {
            this.reader = new BufferedReader(new InputStreamReader(stream));
        }

        /** Reads the next complete line (excluding the line‑terminator). */
        String readLine() {
            try {
                return reader.readLine();
            } catch (IOException e) {
                throw new UncheckedIOException(e);
            }
        }

        /** Returns the next whitespace‑separated token. */
        String next() {
            try {
                while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                    tokenizer = new StringTokenizer(readLine());
                }
                return tokenizer.nextToken();
            } catch (IOException e) {
                throw new UncheckedIOException(e);
            }
        }

        /** Convenience method for reading an {@code int}. */
        int nextInt() {
            return Integer.parseInt(next());
        }

        /** Convenience method for reading a {@code long}. */
        long nextLong() {
            return Long.parseLong(next());
        }
    }

    /** Encapsulates the solution for a single test case. */
    private static final class Solver {

        /** Solves {@code T} test cases and writes the results to the supplied writer. */
        void solve(InputReader reader, PrintWriter writer) {
            int testCases = reader.nextInt();               // T
            StringBuilder output = new StringBuilder();

            for (int t = 0; t < testCases; ++t) {
                processSingleCase(reader, output);
                if (t < testCases - 1) {
                    output.append('\n');
                }
            }

            writer.print(output.toString());
        }

        /** Handles one test case: reads input, performs the algorithm and appends the result. */
        private void processSingleCase(InputReader reader, StringBuilder out) {
            int requiredZeros = reader.nextInt();   // a
            int requiredOnes  = reader.nextInt();   // b
            String pattern    = reader.readLine();  // line containing the pattern
            char[] chars      = pattern.toCharArray();
            int length        = chars.length;

            // -----------------------------------------------------------------
            // 1️⃣  First pass – consume already fixed characters and update counts.
            // -----------------------------------------------------------------
            adjustRemainingCounts(chars, requiredZeros, requiredOnes);

            // -----------------------------------------------------------------
            // 2️⃣  Second pass – symmetrically fill '?' pairs.
            // -----------------------------------------------------------------
            boolean feasible = fillSymmetricPairs(chars, requiredZeros, requiredOnes);

            // -----------------------------------------------------------------
            // 3️⃣  Third pass – possible centre character when the length is odd.
            // -----------------------------------------------------------------
            feasible = fillCenterIfNeeded(chars, requiredZeros, requiredOnes) && feasible;

            // -----------------------------------------------------------------
            // 4️⃣  Final validation – ensure no surplus characters remain.
            // -----------------------------------------------------------------
            feasible = feasible && validateExhaustion(requiredZeros, requiredOnes);

            // -----------------------------------------------------------------
            // 5️⃣  Emit result.
            // -----------------------------------------------------------------
            if (!feasible) {
                out.append("-1\n");
            } else {
                out.append(chars).append('\n');
            }
        }

        /** Decrements the remaining counts after known characters are accounted for. */
        private void adjustRemainingCounts(char[] chars, int[] zeros, int[] ones) {
            int remainingZeros = *zeros;
            int remainingOnes  = *ones;

            for (char c : chars) {
                if (c != '?') {
                    if (c == '0') {
                        --remainingZeros;
                    } else {
                        --remainingOnes;
                    }
                }
            }
            *zeros = remainingZeros;
            *ones  = remainingOnes;
        }

        /** Tries to assign values to symmetric '?' positions.
         *  @return {@code true} if all pairs could be satisfied. */
        private boolean fillSymmetricPairs(char[] chars, int[] zeros, int[] ones) {
            int left  = 0;
            int right = chars.length - 1;

            while (left < right) {
                char l = chars[left];
                char r = chars[right];

                // Conflict between two fixed characters → impossible.
                if (l != '?' && r != '?' && l != r) {
                    return false;
                }

                // One side known, the other is '?' → try to fill it.
                if (l == '?' && r != '?') {
                    assignIfPossible(left, r, zeros, ones, chars);
                } else if (r == '?' && l != '?') {
                    assignIfPossible(right, l, zeros, ones, chars);
                } else if (l == '?' && r == '?') {
                    // Both are wildcards → decide based on remaining counts.
                    if (zeros[0] >= 2) {
                        fillBoth(left, '0', zeros);
                    } else if (ones[0] >= 2) {
                        fillBoth(left, '1', ones);
                    } else {
                        return false; // cannot satisfy any side
                    }
                }
                ++left;
                --right;
            }
            return true;
        }

        /** Assigns a character at {@code idx} if the corresponding count allows it. */
        private void assignIfPossible(int idx, char partner, int[] zeros, int[] ones, char[] chars) {
            if (partner == '0') {
                if (zeros[0] > 0) {
                    chars[idx] = '0';
                    --zeros[0];
                } else {
                    chars[idx] = '?'; // signal impossibility to caller
                }
            } else { // partner == '1'
                if (ones[0] > 0) {
                    chars[idx] = '1';
                    --ones[0];
                } else {
                    chars[idx] = '?';
                }
            }
        }

        /** Fills a symmetric pair with the same digit, decreasing the count by two. */
        private void fillBoth(int idx, char digit, int[] countArray) {
            chars[idx] = digit;
            chars[chars.length - 1 - idx] = digit;
            countArray[0] -= 2;
        }

        /** Handles the optional centre character when the string length is odd. */
        private boolean fillCenterIfNeeded(char[] chars, int[] zeros, int[] ones) {
            int len = chars.length;
            if ((len & 1) == 0) { // even length → no centre
                return true;
            }
            int mid = len / 2;
            char c = chars[mid];
            if (c != '?') {
                return true; // already fixed
            }
            // Need exactly one character left.
            if (zeros[0] > 0) {
                chars[mid] = '0';
                --zeros[0];
                return true;
            }
            if (ones[0] > 0) {
                chars[mid] = '1';
                --ones[0];
                return true;
            }
            return false; // cannot fill centre
        }

        /** Verifies that both required counts have been completely used up. */
        private boolean validateExhaustion(int[] zeros, int[] ones) {
            return zeros[0] == 0 && ones[0] == 0;
        }
    }

    /** Program entry point. */
    public static void main(String[] args) {
        InputReader reader = new InputReader(System.in);
        PrintWriter writer = new PrintWriter(
                new BufferedWriter(new OutputStreamWriter(System.out))
        );
        new Solver().solve(reader, writer);
        writer.flush();
    }
}

import java.io.*;
import java.util.StringTokenizer;

/**
 * Solution for the “Palindromic String with Fixed Digits” problem.
 *
 * <p>This version improves readability, naming, and structure while preserving the
 * original algorithmic behaviour.
 */
public class Main {

    /** Fast scanner that wraps a {@link BufferedReader}. */
    private static final class FastScanner {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        FastScanner(InputStream stream) {
            this.reader = new BufferedReader(new InputStreamReader(stream));
        }

        /** Loads the next {@link StringTokenizer} from the current line. */
        private void ensureTokens() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                tokenizer = new StringTokenizer(reader.readLine());
            }
        }

        /** Reads the next token from the input. */
        String next() throws IOException {
            ensureTokens();
            return tokenizer.nextToken();
        }

        /** Reads the next integer from the input. */
        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }

    /** Entry point of the program. */
    public static void main(String[] args) throws IOException {
        // Try‑with‑resources guarantees proper closure of I/O streams.
        try (FastScanner scanner = new FastScanner(System.in);
             PrintWriter out = new PrintWriter(System.out, true)) {

            int testCases = scanner.nextInt();
            for (int t = 0; t < testCases; t++) {
                int requiredZeros = scanner.nextInt();
                int requiredOnes  = scanner.nextInt();
                String template   = scanner.next();

                solveCase(requiredZeros, requiredOnes, template, out);
            }
        }
    }

    /**
     * Solves a single test case.
     *
     * @param zeroTarget   required number of ‘0’ characters in the result
     * @param oneTarget    required number of ‘1’ characters in the result
     * @param template     the input string that may contain ‘?’
     * @param out          writer for the answer
     */
    private static void solveCase(int zeroTarget, int oneTarget,
                                  String template, PrintWriter out) {
        char[] chars = template.toCharArray();
        int n = chars.length;

        /* --------------------------------------------------------------
         * 1️⃣  Enforce palindrome constraints:
         *    For each symmetric pair replace a ‘?’ with its determined partner.
         * -------------------------------------------------------------- */
        for (int i = 0; i <= n / 2; i++) {
            int j = n - i - 1;                     // symmetric index
            char left  = chars[i];
            char right = chars[j];

            if (left != '?' && right == '?') {
                chars[j] = left;
            } else if (left == '?' && right != '?') {
                chars[i] = right;
            }
        }

        /* --------------------------------------------------------------
         * 2️⃣  Count already fixed digits.
         * -------------------------------------------------------------- */
        int[] digitCount = new int[2]; // 0 → ‘0’, 1 → ‘1’
        for (char c : chars) {
            if (c != '?') {
                digitCount[c - '0']++;
            }
        }

        /* --------------------------------------------------------------
         * 3️⃣  Fill the remaining ‘?’ pairs.
         *    * add == 1 when we are at the centre of an odd‑length string,
         *    * otherwise add == 2.
         *    * Prefer ‘0’ if it fits, otherwise choose ‘1’.
         * -------------------------------------------------------------- */
        for (int i = 0; i <= n / 2; i++) {
            int j = n - i - 1;
            if (chars[i] == '?' && chars[j] == '?') {
                int add = (i == j) ? 1 : 2; // centre of odd length needs only one character

                if (digitCount[0] + add <= zeroTarget) {
                    chars[i] = '0';
                    chars[j] = '0';
                    digitCount[0] += add;
                } else {
                    chars[i] = '1';
                    chars[j] = '1';
                    digitCount[1] += add;
                }
            }
        }

        /* --------------------------------------------------------------
         * 4️⃣  Validate the final result.
         * -------------------------------------------------------------- */
        if (digitCount[0] == zeroTarget && digitCount[1] == oneTarget && isPalindrome(chars)) {
            out.println(new String(chars));
        } else {
            out.println(-1);
        }
    }

    /** Checks whether the given character array forms a palindrome. */
    private static boolean isPalindrome(char[] arr) {
        int left = 0, right = arr.length - 1;
        while (left < right) {
            if (arr[left] != arr[right]) {
                return false;
            }
            left++;
            right--;
        }
        return true;
    }
}

import java.io.*;
import java.util.*;

/**
 * Maintainable solution for the problem described by the original
 * {@code C} class.  The implementation follows the same algorithmic steps
 * but with clearer naming, separation of concerns and modern Java practices.
 */
public class Solution {

    /** Sentinel value that represents an *unassigned* position in the token string. */
    private static final int UNASSIGNED = 15;               // matches the original constant Q

    /** Wrapper around {@link BufferedReader} that provides token‑wise input. */
    private static final class InputReader implements AutoCloseable {
        private final BufferedReader br;
        private StringTokenizer st;

        InputReader(Reader reader) {
            this.br = new BufferedReader(reader);
        }

        /** Returns the next available token, loading more lines as needed. */
        String nextToken() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) {
                        throw new NoSuchElementException("No more input");
                    }
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new UncheckedIOException(e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(nextToken());
        }

        /** For completeness – not used by this solution but kept for symmetry. */
        double nextDouble() {
            return Double.parseDouble(nextToken());
        }

        @Override
        public void close() throws IOException {
            br.close();
        }
    }

    /** Simple façade for output that buffers writes. */
    private static final class OutputWriter {
        private final PrintWriter pw;

        OutputWriter(OutputStream out) {
            this.pw = new PrintWriter(new BufferedWriter(new OutputStreamWriter(out)));
        }

        void print(Object o) {
            pw.print(o);
        }

        void println(Object o) {
            pw.println(o);
        }

        void flush() {
            pw.flush();
        }

        void close() {
            pw.close();
        }
    }

    /** Converts a token string into an integer array using the offset rules from the original code. */
    private static int[] convertToIntArray(String token) {
        // Determine the offset character used for the conversion.
        char offset = '0';
        char first = token.charAt(0);
        if (Character.isLowerCase(first)) {
            offset = 'a';
        } else if (Character.isUpperCase(first)) {
            offset = 'A';
        }

        int[] arr = new int[token.length()];
        int idx = 0;
        for (char c : token.toCharArray()) {
            arr[idx++] = c - offset;
        }
        return arr;
    }

    /**
     * Solves a single test case.
     *
     * @param in  reader that supplies the input tokens
     * @param out writer to which the answer is printed
     */
    private static void solve(InputReader in, OutputWriter out) {
        // ----- 1. read problem parameters -------------------------------------------------
        int requiredZeros = in.nextInt();           // original variable `a`
        int requiredOnes  = in.nextInt();           // original variable `b`
        String token      = in.nextToken();         // encoded pattern
        int[] values      = convertToIntArray(token);
        int n             = values.length;

        int[] result      = Arrays.copyOf(values, n);   // mutable working copy

        // ----- 2. sanity checks & forced propagation ------------------------------------
        for (int i = 0; i < n / 2; i++) {
            int partner = n - i - 1;

            // 2.1 contradictory bits -> impossible
            if ((result[i] == 0 && result[partner] == 1) ||
                (result[i] == 1 && result[partner] == 0)) {
                out.println(-1);
                return;
            }

            // 2.2 propagate a forced 0 if one side is 0 and the other is UNASSIGNED
            if ((result[i] == 0 || result[partner] == 0) &&
                (result[i] == UNASSIGNED || result[partner] == UNASSIGNED)) {
                int forced = (result[i] != UNASSIGNED) ? result[i] : result[partner];
                result[i] = result[partner] = forced;
            }

            // 2.3 propagate a forced 1 if one side is 1 and the other is UNASSIGNED
            if ((result[i] == 1 || result[partner] == 1) &&
                (result[i] == UNASSIGNED || result[partner] == UNASSIGNED)) {
                int forced = (result[i] != UNASSIGNED) ? result[i] : result[partner];
                result[i] = result[partner] = forced;
            }
        }

        // ----- 3. update the remaining quota of 0s and 1s ---------------------------------
        for (int v : result) {
            if (v == 0) {
                requiredZeros--;
            } else if (v == 1) {
                requiredOnes--;
            }
        }
        if (requiredZeros < 0 || requiredOnes < 0) {
            out.println(-1);
            return;
        }

        // ----- 4. fill the still‑unassigned slots ---------------------------------------
        for (int i = 0; i < n / 2; i++) {
            int partner = n - i - 1;

            if (result[i] == UNASSIGNED && result[partner] == UNASSIGNED) {
                // both sides are free – consume a pair
                if (requiredZeros >= 2) {
                    result[i] = result[partner] = 0;
                    requiredZeros -= 2;
                } else if (requiredOnes >= 2) {
                    result[i] = result[partner] = 1;
                    requiredOnes -= 2;
                } else {
                    out.println(-1);
                    return;
                }
            } else if (result[i] == UNASSIGNED || result[partner] == UNASSIGNED) {
                // exactly one side is already fixed; propagate it
                int fixedIdx  = (result[i] != UNASSIGNED) ? i : partner;
                int fixedVal  = result[fixedIdx];

                if (fixedVal == 0) {
                    if (requiredZeros <= 0) {
                        out.println(-1);
                        return;
                    }
                    result[fixedIdx] = 0;
                    requiredZeros--;
                } else { // fixedVal == 1
                    if (requiredOnes <= 0) {
                        out.println(-1);
                        return;
                    }
                    result[fixedIdx] = 1;
                    requiredOnes--;
                }
            }
        }

        // ----- 5. handle a possible middle element (odd length) -------------------------
        if (n % 2 == 1) {
            int mid = n / 2;
            if (result[mid] == UNASSIGNED) {
                if (requiredZeros > 0) {
                    result[mid] = 0;
                    requiredZeros--;
                } else if (requiredOnes > 0) {
                    result[mid] = 1;
                    requiredOnes--;
                } else {
                    out.println(-1);
                    return;
                }
            }
        }

        // ----- 6. final validation -------------------------------------------------------
        if (requiredZeros != 0 || requiredOnes != 0) {
            out.println(-1);
            return;
        }

        // ----- 7. produce the answer ----------------------------------------------------
        StringBuilder sb = new StringBuilder(n);
        for (int v : result) {
            sb.append(v);
        }
        out.println(sb.toString());
    }

    /** Entry point – orchestrates multiple test cases. */
    public static void main(String[] args) {
        try (InputReader in = new InputReader(new InputStreamReader(System.in));
             OutputWriter out = new OutputWriter(System.out)) {

            int tests = in.nextInt();
            for (int t = 0; t < tests; t++) {
                solve(in, out);
            }
            out.flush();
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
    }
}

import java.io.*;
import java.util.StringTokenizer;

/**
 * Refactored solution for the “CodeForces” problem.
 *
 * <p>The program reads multiple test cases. Each test case consists of:
 *
 * <ul>
 *   <li>two integers – the required number of ‘0’s and ‘1’s,
 *   <li>a string that may contain ‘0’, ‘1’ and ‘?’.
 * </ul>
 *
 * <p>The task is to replace every ‘?’ with ‘0’ or ‘1’ so that the final string
 * is a palindrome and contains exactly the given numbers of ‘0’ and ‘1’.
 * If it is impossible, the program outputs “-1”.
 *
 * <p>The implementation is deliberately split into small, well‑named methods,
 * uses {@link BufferedReader} with {@link try‑with‑resources}, and avoids the
 * use of static mutable fields.
 */
public class Main {

    /** Name of the optional input file – change to {@code null} to read from stdin. */
    private static final String INPUT_FILE = "src\\input.txt";

    /** Entry point */
    public static void main(String[] args) throws IOException {
        StringBuilder output = new StringBuilder();

        // The try‑with‑resources block guarantees that every BufferedReader is closed.
        try (InputReader reader = new InputReader()) {
            int testCases = reader.nextInt();
            while (testCases-- > 0) {
                output.append(solveCase(reader)).append('\n');
            }
        }

        System.out.print(output);
    }

    /** Reads and processes a single test case, returning the formatted result. */
    private static String solveCase(InputReader reader) {
        int requiredZeros = reader.nextInt();   // a
        int requiredOnes  = reader.nextInt();   // b
        String raw = reader.next();             // the pattern string

        char[] chars = raw.toCharArray();
        int n = chars.length;

        // A palindrome cannot have both an odd number of required zeros and ones.
        if ((requiredZeros & 1) == 1 && (requiredOnes & 1) == 1) {
            return "-1";
        }

        // -------- first pass – mirror known characters and consume counts ----------
        for (int i = 0, j = n - 1; i < j; i++, j--) {
            char left = chars[i];
            char right = chars[j];

            if (left != '?' && right != '?' && left != right) {
                // Conflict – two different fixed characters on symmetric positions.
                return "-1";
            }

            if (left == '?' || right == '?') {
                // Resolve the '?' by copying the known side.
                if (left == '?') {
                    chars[i] = chars[j] = right;
                } else {
                    chars[i] = chars[j] = left;
                }
            }

            // If the resolved character is '0' or '1', consume two from the appropriate counter.
            if (chars[i] == '0') {
                requiredZeros -= 2;
            } else if (chars[i] == '1') {
                requiredOnes -= 2;
            }
        }

        // -------- middle character (only when length is odd) -------------------------
        if (n % 2 == 1 && chars[n / 2] != '?') {
            // The middle character is fixed; one occurrence consumes a single count.
            if (chars[n / 2] == '0') {
                requiredZeros--;
            } else {
                requiredOnes--;
            }
        }

        // -------- sanity checks after the first pass -------------------------------
        if (requiredZeros < 0 || requiredOnes < 0 ||
                (requiredZeros & 1) == 1 && (requiredOnes & 1) == 1) {
            return "-1";
        }

        // -------- second pass – fill the remaining '?' -------------------------------
        for (int i = 0, j = n - 1; i < j; i++, j--) {
            if (chars[i] == '?') {
                // Prefer filling with '0' if we still need at least two zeros,
                // otherwise fall back to '1'.
                if (requiredZeros >= 2) {
                    chars[i] = chars[j] = '0';
                    requiredZeros -= 2;
                } else {
                    chars[i] = chars[j] = '1';
                    requiredOnes -= 2;
                }
            }
        }

        // -------- middle character when it is still a '?' ---------------------------
        if (n % 2 == 1 && chars[n / 2] == '?') {
            if (requiredZeros > 0) {
                chars[n / 2] = '0';
                requiredZeros--;
            } else {
                chars[n / 2] = '1';
                requiredOnes--;
            }
        }

        // Final validation (should never fail if logic is correct, but we keep it
        // to stay faithful to the original program's behaviour).
        if (requiredZeros != 0 || requiredOnes != 0) {
            return "-1";
        }

        return new String(chars);
    }

    /**
     * Simple wrapper around {@link BufferedReader} that also tokenises input.
     * It reads from a file when {@code INPUT_FILE} is non‑null, otherwise from
     * {@code System.in}. The class implements {@AutoCloseable} so it can be
     * used in a try‑with‑resources statement.
     */
    private static class InputReader implements Closeable {
        private final BufferedReader br;
        private StringTokenizer st;

        InputReader() throws IOException {
            if (INPUT_FILE != null && !INPUT_FILE.isEmpty()) {
                br = new BufferedReader(new FileReader(INPUT_FILE));
            } else {
                br = new BufferedReader(new InputStreamReader(System.in));
            }
            st = null;
        }

        /** Returns the next token, expanding the tokenizer lazily. */
        private String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) {
                        return null;
                    }
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new UncheckedIOException(e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }
        // Convenience methods omitted – they are not needed for this solution.
        // (They can be added analogously if required.)
        public void close() throws IOException {
            br.close();
        }
    }
}

import java.util.Scanner;

/**
 * Utility that builds a palindrome from a partially‑filled template.
 *
 * <p>
 * The template may contain the characters '0', '1' and '?'.
 * The required numbers of '0' and '1' are supplied by the caller.
 * The program outputs the completed palindrome or "-1" if it cannot be built.
 * </p>
 */
public class PalindromeBuilder {

    /** Entry point */
    public static void main(String[] args) {
        // Using try‑with‑resources guarantees that the scanner is closed promptly.
        try (Scanner scanner = new Scanner(System.in)) {
            int testCases = scanner.nextInt();
            for (int i = 0; i < testCases; i++) {
                int requiredZeros = scanner.nextInt();
                int requiredOnes = scanner.nextInt();
                String template = scanner.next();

                String result = buildPalindrome(template, requiredZeros, requiredOnes);
                System.out.println(result);
            }
        }
    }

    /**
     * Attempts to create a palindrome from {@code template} that contains
     * exactly {@code requiredZeros} '0's and {@code requiredOnes} '1's.
     *
     * @return completed palindrome, or "-1" when it is impossible.
     */
    public static String buildPalindrome(String template, int requiredZeros, int requiredOnes) {
        // Work on a mutable copy of the template.
        StringBuilder builder = new StringBuilder(template);
        int totalLength = requiredZeros + requiredOnes;
        int zeroCount = requiredZeros;
        int oneCount = requiredOnes;

        // -----------------------------------------------------------------
        // 1️⃣  Resolve forced pairs (both ends already filled) and verify them.
        // -----------------------------------------------------------------
        if (!resolveForcedPairs(builder, zeroCount, oneCount)) {
            return "-1";
        }

        // -----------------------------------------------------------------
        // 2️⃣  Pair‑wise fill the remaining '?' positions.
        // -----------------------------------------------------------------
        if (!fillSymmetricPairs(builder, zeroCount, oneCount)) {
            return "-1";
        }

        // -----------------------------------------------------------------
        // 3️⃣  Fill the centre character (if the length is odd).
        // -----------------------------------------------------------------
        fillCenterIfNeeded(builder, zeroCount, oneCount);

        // -----------------------------------------------------------------
        // 4️⃣  Final validation – all counts must be exhausted.
        // -----------------------------------------------------------------
        if (zeroCount == 0 && oneCount == 0) {
            return builder.toString();
        }
        return "-1";
    }

    /**
     * Handles positions that are already fixed on both sides of the palindrome.
     * It also updates the remaining zero/one counters accordingly.
     *
     * @return {@code true} if the template is still viable; {@code false} otherwise.
     */
    private static boolean resolveForcedPairs(StringBuilder sb,
                                              int[] counts) {
        int left = 0;
        int right = sb.length() - 1;

        while (left < right) {
            char leftChar = sb.charAt(left);
            char rightChar = sb.charAt(right);

            // Both ends are filled – they must match, otherwise the template is invalid.
            if (leftChar != '?' && rightChar != '?') {
                if (leftChar != rightChar) {
                    return false;
                }
                decrementCount(leftChar, counts);
            }
            // Only the left side is fixed → force the right side to match.
            else if (leftChar != '?') {
                sb.setCharAt(right, leftChar);
                decrementCount(leftChar, counts);
            }
            // Only the right side is fixed → force the left side to match.
            else if (rightChar != '?') {
                sb.setCharAt(left, rightChar);
                decrementCount(rightChar, counts);
            }
            left++;
            right--;
        }
        return true;
    }

    /**
     * Fills every symmetric pair of '?' with either '0' or '1',
     * respecting the remaining number of each digit.
     *
     * @return {@code true} if all pairs could be filled; {@code false} otherwise.
     */
    private static boolean fillSymmetricPairs(StringBuilder sb,
                                              int[] counts) {
        int left = 0;
        int right = sb.length() - 1;

        while (left < sb.length() / 2) {
            if (sb.charAt(left) == '?') {
                // Prefer '0' when we still need at least two of them.
                char digit = (counts[0] >= 2) ? '0' : '1';
                sb.setCharAt(left, digit);
                sb.setCharAt(right, digit);
                decrementCount(digit, counts);
            }
            left++;
        }
        return true;
    }

    /**
     * If the string length is odd and the centre character is still a '?',
     * fill it with whichever digit is still available.
     */
    private static void fillCenterIfNeeded(StringBuilder sb,
                                            int[] counts) {
        int centerIdx = sb.length() / 2;
        if (sb.charAt(centerIdx) == '?') {
            // The centre consumes exactly one digit.
            if (counts[0] > 0) {
                sb.setCharAt(centerIdx, '0');
                counts[0]--;
            } else if (counts[1] > 0) {
                sb.setCharAt(centerIdx, '1');
                counts[1]--;
            }
        }
    }

    /**
     * Decrements the appropriate counter based on the supplied digit.
     *
     * <p>
     * The method expects {@code counts[0]} to hold the remaining number of '0's
     * and {@code counts[1]} for '1's.
     * </p>
     */
    private static void decrementCount(char digit, int[] counts) {
        counts[digit - '0'] -= 2;   // two positions are filled at once (symmetric pair)
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

/**
 * Refactored version of the original competitive‑programming utility.
 * The code is split into small, single‑responsibility methods,
 * uses expressive naming and performs all necessary validation
 * before producing the result.
 */
public class CP {

    /** Fast scanner that works with {@link BufferedReader}. */
    private static final class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner() {
            this.br = new BufferedReader(new InputStreamReader(System.in));
        }

        /** Returns the next token, retrying on I/O errors. */
        private String nextToken() throws IOException {
            while (st == null || !st.hasMoreElements()) {
                st = new StringTokenizer(br.readLine());
            }
            return st.nextToken();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(nextToken());
        }

        long nextLong() throws IOException {
            return Long.parseLong(nextToken());
        }

        double nextDouble() throws IOException {
            return Double.parseDouble(nextToken());
        }

        String nextLine() throws IOException {
            String line;
            try {
                line = br.readLine();
            } catch (IOException e) {
                throw new RuntimeException(e);
            }
            return line;
        }
    }

    /** Separator used for output building. */
    private static final String LINE_SEPARATOR = System.lineSeparator();

    /** Constant for the required length check (kept for readability). */
    private static final int REQUIRED_LENGTH = -1; // not used, kept for future extensions

    /**
     * Solves a single test case.
     *
     * @param neededZeros required number of '0' characters in the final palindrome
     * @param neededOnes  required number of '1' characters in the final palindrome
     * @param input       raw string that may contain '?'
     * @return constructed palindrome or "-1" if impossible
     */
    private static String solveCase(int neededZeros, int neededOnes, String input) {
        int length = input.length();
        char[] chars = input.toCharArray();

        // Quick length sanity check.
        if (neededZeros + neededOnes != length) {
            return "-1";
        }

        boolean[] filled = new boolean[length];          // positions already assigned
        int[] counters = {neededZeros, neededOnes};        // {zeros, ones}

        // --------------------------------------------------------------
        // 1️⃣  Propagate fixed characters and validate symmetric constraints.
        // --------------------------------------------------------------
        for (int i = 0; i < length; i++) {
            int j = length - 1 - i;
            if (chars[i] != '?') {               // a fixed character on the left side
                // The right side must either be the same character or also '?'
                if (chars[j] == '?') {
                    chars[j] = chars[i];
                } else if (chars[i] != chars[j]) {
                    return "-1";               // contradictory fixed chars
                }
                // Decrease the appropriate counter (only once per position)
                if (!filled[i]) {
                    decrementCounter(chars[i], counters);
                    filled[i] = true;
                }
                if (!filled[j]) {
                    decrementCounter(chars[j], counters);
                    filled[j] = true;
                }
            }
        }

        // --------------------------------------------------------------
        // 2️⃣  Handle the middle character in odd‑length strings.
        // --------------------------------------------------------------
        if (length % 2 == 1) {
            int mid = length / 2;
            if (!filled[mid] && chars[mid] == '?') {
                // The middle character can only satisfy an odd remaining count.
                if (counters[0] % 2 == 1) {
                    chars[mid] = '0';
                    decrementCounter('0', counters);
                    filled[mid] = true;
                } else if (counters[1] % 2 == 1) {
                    chars[mid] = '1';
                    decrementCounter('1', counters);
                    filled[mid] = true;
                }
            }
        }

        // --------------------------------------------------------------
        // 3️⃣  Fill remaining '?' pairs symmetrically.
        // --------------------------------------------------------------
        for (int i = 0; i < length; i++) {
            int j = length - 1 - i;
            if (chars[i] == '?') {
                // Both positions are still unknown – assign the same digit.
                if (counters[0] >= 2) {
                    chars[i] = chars[j] = '0';
                    counters[0] -= 2;
                } else if (counters[1] >= 2) {
                    chars[i] = chars[j] = '1';
                    counters[1] -= 2;
                } else {
                    // Not enough symbols left to fill a pair.
                    return "-1";
                }
                filled[i] = filled[j] = true;
            }
        }

        // --------------------------------------------------------------
        // 4️⃣  Final validation – counters must be exhausted.
        // --------------------------------------------------------------
        if (counters[0] != 0 || counters[1] != 0) {
            return "-1";
        }

        // The constructed string is guaranteed to be a palindrome now.
        return new String(chars);
    }

    /**
     * Decrements the proper counter when a fixed digit is placed.
     *
     * @param digit character currently being placed ('0' or '1')
     * @param cnt   array holding remaining zeros at index 0 and remaining ones at index 1
     */
    private static void decrementCounter(char digit, int[] cnt) {
        if (digit == '0') {
            cnt[0]--;
        } else {
            cnt[1]--;
        }
    }

    // ----------------------------------------------------------------------
    // Main entry point
    // ----------------------------------------------------------------------
    public static void main(String[] args) throws IOException {
        FastScanner fs = new FastScanner();
        int testCases = fs.nextInt();

        StringBuilder out = new StringBuilder();
        for (int tc = 0; tc < testCases; tc++) {
            int need0 = fs.nextInt();
            int need1 = fs.nextInt();
            String s = fs.next();

            String result = solveCase(need0, need1, s);
            out.append(result);
            if (tc < testCases - 1) {
                out.append(LINE_SEPARATOR);
            }
        }
        System.out.print(out.toString());
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;

/**
 * Refactored version of the original program.
 *
 * <p>This class reads several test cases. For each case it receives:
 *
 * <ul>
 *   <li>the number of '0's that must appear in the final palindrome,
 *   <li>the number of '1's that must appear in the final palindrome, and
 *   <li>a pattern string containing '0', '1' and '?' characters.</li>
 * </ul>
 *
 * <p>It tries to replace every '?' with either '0' or '1' so that the resulting
 * string is a palindrome that contains exactly the required numbers of '0' and
 * '1'. If it is impossible, the method returns "-1".
 *
 * <p>The implementation has been refactored for readability, maintainability and
 * correctness while preserving the original behaviour.
 */
public class Solution {

    /**
     * Entry point of the program.
     *
     * @param args command line arguments (ignored)
     * @throws IOException if an I/O error occurs while reading input
     */
    public static void main(String[] args) throws IOException {
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
        int testCases = Integer.parseInt(reader.readLine());

        while (testCases-- > 0) {
            String[] parts = reader.readLine().split(" ");
            int requiredZeros = Integer.parseInt(parts[0]);
            int requiredOnes = Integer.parseInt(parts[1]);
            String pattern = reader.readLine();

            System.out.println(reconstructPalindrome(pattern, requiredZeros, requiredOnes));
        }
    }

    /**
     * Attempts to build a palindrome that respects the required number of '0's
     * and '1's.
     *
     * @param pattern      the input pattern containing '0', '1' and '?'.
     * @param neededZeros  the exact number of '0's that must appear in the result.
     * @param neededOnes   the exact number of '1's that must appear in the result.
     * @return the constructed palindrome, or "-1" if construction is impossible.
     */
    private static String reconstructPalindrome(String pattern, int neededZeros, int neededOnes) {
        char[] chars = pattern.toCharArray();
        int length = chars.length;

        // -----------------------------------------------------------------------
        // 1. Count already fixed '0' and '1' and adjust the quota.
        // -----------------------------------------------------------------------
        int fixedZeros = countOccurrences(chars, '0');
        int fixedOnes = countOccurrences(chars, '1');

        neededZeros -= fixedZeros;
        neededOnes -= fixedOnes;

        if (neededZeros < 0 || neededOnes < 0) {
            return "-1";
        }

        // -----------------------------------------------------------------------
        // 2. Quick validation for a single‑character pattern.
        // -----------------------------------------------------------------------
        if (length == 1) {
            return handleSingleCharacter(chars, neededZeros, neededOnes);
        }

        // -----------------------------------------------------------------------
        // 3. Analyse symmetric positions and collect statistics.
        // -----------------------------------------------------------------------
        PairStats stats = analyseSymmetricPairs(chars);
        if (stats == null) {
            return "-1"; // early failure detection
        }

        // -----------------------------------------------------------------------
        // 4. Fill symmetric '?' pairs with the appropriate digit.
        // -----------------------------------------------------------------------
        if (!fillSymmetricPairs(chars, neededZeros, neededOnes, stats)) {
            return "-1";
        }

        // -----------------------------------------------------------------------
        // 5. Fill any remaining single '?' (the middle character of odd length).
        // -----------------------------------------------------------------------
        if (!fillRemainingUnknowns(chars, neededZeros, neededOnes)) {
            return "-1";
        }

        // -----------------------------------------------------------------------
        // 6. Final sanity check – there must be no '?' left.
        // -----------------------------------------------------------------------
        if (stillContainsUnknown(chars)) {
            return "-1";
        }

        return new String(chars);
    }

    /** Counts how many times {@code ch} appears in {@code arr}. */
    private static int countOccurrences(char[] arr, char ch) {
        int cnt = 0;
        for (char c : arr) {
            if (c == ch) {
                cnt++;
            }
        }
        return cnt;
    }

    /** Handles the special case where the pattern length is 1. */
    private static String handleSingleCharacter(char[] chars, int neededZeros, int neededOnes) {
        if (chars[0] == '?') {
            if (neededZeros > 0) {
                chars[0] = '0';
                neededZeros--;
            } else if (neededOnes > 0) {
                chars[0] = '1';
                neededOnes--;
            } else {
                return "-1";
            }
        }
        // If the character is not '?' we simply verify that the quota matches.
        return (chars[0] == '0' ? neededZeros == 0 : neededOnes == 0)
                ? new String(chars)
                : "-1";
    }

    /**
     * Examines symmetric positions of the pattern and records how many
     * pairs require both digits to be '0' or both to be '1'.
     *
     * @return an auxiliary object holding counts, or {@code null} if the pattern
     *         is already invalid.
     */
    private static PairStats analyseSymmetricPairs(char[] chars) {
        int half = chars.length / 2;
        int zeroPairNeeded = 0; // how many pairs must become "00"
        int onePairNeeded = 0;  // how many pairs must become "11"

        for (int i = 0, j = chars.length - 1; i < j; i++, j--) {
            char left = chars[i];
            char right = chars[j];

            if (left == '?' && right == '0' || left == '0' && right == '?') {
                zeroPairNeeded++;
            } else if (left == '?' && right == '1' || left == '1' && right == '?') {
                onePairNeeded++;
            } else if (left != right) {
                // Fixed characters differ → impossible to form a palindrome.
                return null;
            }
        }
        return new PairStats(zeroPairNeeded, onePairNeeded);
    }

    /** Simple holder for the two statistics collected above. */
    private static final class PairStats {
        final int zeroPairs;
        final int onePairs;

        PairStats(int zeroPairs, int onePairs) {
            this.zeroPairs = zeroPairs;
            this.onePairs = onePairs;
        }
    }

    /**
     * Attempts to fill symmetric '?' pairs using the remaining quota of zeros
     * and ones. Returns {@code false} if the quota is insufficient.
     */
    private static boolean fillSymmetricPairs(char[] chars,
                                              int neededZeros,
                                              int neededOnes,
                                              PairStats stats) {
        int half = chars.length / 2;
        for (int i = 0, j = chars.length - 1; i < j; i++, j--) {
            char left = chars[i];
            char right = chars[j];

            if (left == '?' && right == '?') {
                // We need a whole pair of the same digit.
                if (neededZeros >= 2) {
                    chars[i] = chars[j] = '0';
                    neededZeros -= 2;
                } else if (neededOnes >= 2) {
                    chars[i] = chars[j] = '1';
                    neededOnes -= 2;
                } else {
                    return false; // not enough of either digit to fill a pair
                }
            } else if (left == '?') {
                // right side is fixed.
                placeSingleUnknown(chars, i, left, neededZeros, neededOnes);
            } else if (right == '?') {
                // left side is fixed.
                placeSingleUnknown(chars, j, right, neededZeros, neededOnes);
            }
            // If both sides are already fixed, they must already match – nothing to do.
        }
        return true;
    }

    /**
     * Places a digit at {@code index} according to the remaining quota.
     *
     * @return {@code true} if the digit could be placed; {@code false} otherwise.
     */
    private static boolean placeSingleUnknown(char[] chars,
                                              int index,
                                              char fixedNeighbour,
                                              int neededZeros,
                                              int neededOnes) {
        if (fixedNeighbour == '0') {
            if (neededZeros <= 0) {
                return false;
            }
            chars[index] = '0';
            neededZeros--;
        } else { // fixedNeighbour == '1'
            if (neededOnes <= 0) {
                return false;
            }
            chars[index] = '1';
            neededOnes--;
        }
        return true;
    }

    /** Fills the middle character of an odd‑length string if it is still '?'. */
    private static boolean fillRemainingUnknowns(char[] chars,
                                                   int neededZeros,
                                                   int neededOnes) {
        if (chars.length % 2 == 1 && chars[chars.length / 2] == '?') {
            int mid = chars.length / 2;
            if (neededZeros > 0) {
                chars[mid] = '0';
                neededZeros--;
            } else if (neededOnes > 0) {
                chars[mid] = '1';
                neededOnes--;
            } else {
                return false; // no digit left to place at the centre
            }
        }
        return neededZeros == 0 && neededOnes == 0;
    }

    /** Returns {@code true} if any '?' character remains unfilled. */
    private static boolean stillContainsUnknown(char[] chars) {
        for (char c : chars) {
            if (c == '?') {
                return true;
            }
        }
        return false;
    }
}

import java.io.*;
import java.util.*;

public class ABPalinCF {

    /** Simple fast scanner used throughout the program. */
    private static class InputReader {
        private final InputStream stream;
        private final byte[] buffer = new byte[8192];
        private int cursor = 0;
        private int size = 0;

        public InputReader(InputStream stream) {
            this.stream = stream;
        }

        /** Reads the next byte, filling the buffer when necessary. */
        private int readByte() throws IOException {
            if (cursor == size) {
                cursor = 0;
                size = stream.read(buffer);
                if (size == -1) {
                    return -1;
                }
            }
            return buffer[cursor++];
        }

        /** Skips whitespace characters and returns the next non‑space character. */
        private int nextNonSpace() throws IOException {
            int c;
            do {
                c = readByte();
            } while (isSpaceChar(c) && c != -1);
            return c;
        }

        /** Reads a signed decimal integer. */
        public int nextInt() throws IOException {
            int sign = 1;
            int c = nextNonSpace();
            if (c == '-') {
                sign = -1;
                c = nextNonSpace();
            }
            int value = 0;
            do {
                value = value * 10 + (c - '0');
                c = nextNonSpace();
            } while (!isSpaceChar(c));
            return value * sign;
        }

        /** Reads a token consisting of non‑whitespace characters. */
        public String readString() throws IOException {
            int c = nextNonSpace();
            StringBuilder sb = new StringBuilder();
            do {
                sb.appendCodePoint(c);
                c = nextNonSpace();
            } while (!isSpaceChar(c));
            return sb.toString();
        }

        /** Utility to detect whitespace. */
        public boolean isSpaceChar(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }
    }

    public static void main(String[] args) throws Exception {
        /* ---------- Fast I/O Setup ---------- */
        InputReader reader = new InputReader(System.in);
        PrintWriter out = new PrintWriter(new OutputStreamWriter(System.out));

        int testCases = reader.nextInt();
        StringBuilder result = new StringBuilder();

        /* ---------- Process Each Test Case ---------- */
        for (int tc = 0; tc < testCases; tc++) {
            /* ----- 1. Read input ----- */
            int targetZeros = reader.nextInt();          // a
            int targetOnes  = reader.nextInt();          // b
            String binary   = reader.readString();       // pattern string

            char[] chars = binary.toCharArray();
            int n = chars.length;

            /* ----- 2. Count already fixed characters ----- */
            int fixedZeros = 0, fixedOnes = 0;
            for (char c : chars) {
                if (c == '0') fixedZeros++;
                else if (c == '1') fixedOnes++;
            }

            /* ----- 3. Early impossibility checks ----- */
            if (fixedZeros > targetZeros || fixedOnes > targetOnes) {
                result.append("-1\n");
                continue;
            }

            int remainingZeros = targetZeros - fixedZeros;
            int remainingOnes  = targetOnes  - fixedOnes;
            boolean valid = true;

            /* ----- 4. Resolve symmetric positions ----- */
            for (int i = 0; i < n / 2; i++) {
                int j = n - i - 1;
                char left = chars[i];
                char right = chars[j];

                /* Both are '?' → nothing to decide now */
                if (left == '?' && right == '?') {
                    continue;
                }

                /* Exactly one side is '?' → copy the known value */
                if (left == '?') {
                    if (right == '0') {
                        left = '0';
                        remainingZeros--;
                    } else if (right == '1') {
                        left = '1';
                        remainingOnes--;
                    } else {
                        valid = false; break;
                    }
                    chars[i] = left;
                } else if (right == '?') {
                    if (left == '0') {
                        right = '0';
                        remainingZeros--;
                    } else if (left == '1') {
                        right = '1';
                        remainingOnes--;
                    } else {
                        valid = false; break;
                    }
                    chars[j] = right;
                }

                /* After copying, both ends must match */
                if (chars[i] != chars[j]) {
                    valid = false; break;
                }
            }

            if (!valid || remainingZeros < 0 || remainingOnes < 0) {
                result.append("-1\n");
                continue;
            }

            /* ----- 5. Fill symmetric '?' pairs ----- */
            for (int i = 0; i < n / 2; i++) {
                int j = n - i - 1;
                if (chars[i] == '?') {
                    if (remainingZeros >= 2) {
                        chars[i] = chars[j] = '0';
                        remainingZeros -= 2;
                    } else if (remainingOnes >= 2) {
                        chars[i] = chars[j] = '1';
                        remainingOnes -= 2;
                    } else {
                        valid = false; break;
                    }
                }
            }

            if (!valid || remainingZeros < 0 || remainingOnes < 0) {
                result.append("-1\n");
                continue;
            }

            /* ----- 6. Deal with middle character for odd length ----- */
            if ((n & 1) == 1) {
                int mid = n / 2;
                if (chars[mid] == '?') {
                    if (remainingZeros > 0) {
                        chars[mid] = '0';
                        remainingZeros--;
                    } else if (remainingOnes > 0) {
                        chars[mid] = '1';
                        remainingOnes--;
                    } else {
                        valid = false;
                    }
                }
            }

            /* ----- 7. Final consistency check ----- */
            if (!valid || remainingZeros != 0 || remainingOnes != 0) {
                result.append("-1\n");
                continue;
            }

            /* ----- 8. Append the constructed palindrome ----- */
            result.append(chars).append('\n');
        }

        /* ---------- Output ---------- */
        out.print(result.toString());
        out.flush();
        out.close();
    }
}

import java.io.*;
import java.util.*;

/**
 * Solves the problem by:
 * 1. Finding the shortest distance from the start cell 'S' to the exit cell 'E'
 *    while never stepping on a wall 'T'.
 * 2. From the exit, spreading out up to that distance and adding the numeric
 *    values of all reachable cells (digits only) that are not walls,
 *    start or the exit itself.
 */
public class Main {

    /** Directions used for neighbour exploration (up, down, left, right). */
    private static final int[][] DIRS = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};

    /** Simple immutable container for a board position together with its distance. */
    private static final class Node {
        final int row;
        final int col;
        final int dist;

        Node(int row, int col, int dist) {
            this.row = row;
            this.col = col;
            this.dist = dist;
        }
    }

    /** Reads the whole input, builds the board and returns the parsed data. */
    private static Board readInput(BufferedReader br) throws IOException {
        String[] first = br.readLine().split("\\s+");
        int rows = Integer.parseInt(first[0]);
        int cols = Integer.parseInt(first[1]);

        char[][] grid = new char[rows][cols];
        Position start = null;
        Position exit = null;

        for (int r = 0; r < rows; r++) {
            String line = br.readLine();
            for (int c = 0; c < cols; c++) {
                grid[r][c] = line.charAt(c);
                if (grid[r][c] == 'S') {
                    start = new Position(r, c);
                } else if (grid[r][c] == 'E') {
                    exit = new Position(r, c);
                }
            }
        }
        return new Board(grid, start, exit);
    }

    /** Holds the board and the locations of the start and exit cells. */
    private static final class Board {
        final char[][] grid;
        final Position start;
        final Position exit;

        Board(char[][] grid, Position start, Position exit) {
            this.grid = grid;
            this.start = start;
            this.exit = exit;
        }
    }

    /** Simple immutable container for a board coordinate. */
    private static final class Position {
        final int row;
        final int col;

        Position(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }

    /** Performs a breadth‑first search from {@code src} until the exit is reached.
     *  Returns the distance (number of steps) to the exit, or {@code -1} if unreachable. */
    private static int bfsToExit(Board board, Position src) {
        int rows = board.grid.length;
        int cols = board.grid[0].length;
        boolean[][] visited = new boolean[rows][cols];
        Queue<Node> q = new ArrayDeque<>();
        q.add(new Node(src.row, src.col, 0));
        visited[src.row][src.col] = true;

        while (!q.isEmpty()) {
            Node cur = q.poll();
            if (cur.row == board.exit.row && cur.col == board.exit.col) {
                return cur.dist;               // shortest distance found
            }
            for (int[] d : DIRS) {
                int nr = cur.row + d[0];
                int nc = cur.col + d[1];
                if (outOfBounds(nr, nc, rows, cols) || visited[nr][nc]) {
                    continue;
                }
                char ch = board.grid[nr][nc];
                if (ch == 'T') {
                    continue;                  // walls are impassable
                }
                visited[nr][nc] = true;
                q.add(new Node(nr, nc, cur.dist + 1));
            }
        }
        // According to the problem statement the exit is always reachable,
        // but we keep a safe fallback.
        return -1;
    }

    /** Collects the sum of numeric values of all cells reachable from the exit
     *  within {@code maxDist} steps, respecting walls and the original start cell. */
    private static int collectScore(Board board, int maxDist) {
        int rows = board.grid.length;
        int cols = board.grid[0].length;
        boolean[][] visited = new boolean[rows][cols];
        Queue<Node> q = new ArrayDeque<>();
        q.add(new Node(board.exit.row, board.exit.col, 0));
        visited[board.exit.row][board.exit.col] = true;

        int total = 0;

        while (!q.isEmpty()) {
            Node cur = q.poll();
            int r = cur.row;
            int c = cur.col;
            int d = cur.dist;

            // Stop expanding once we exceed the allowed distance.
            if (d > maxDist) {
                continue;
            }

            char cell = board.grid[r][c];
            // Add numeric value only for digit cells that are not start/exit/wall.
            if (d > 0 && Character.isDigit(cell)) {
                total += Character.digit(cell, 10);
            }

            // Explore neighbours.
            for (int[] drc : DIRS) {
                int nr = r + drc[0];
                int nc = c + drc[1];
                if (outOfBounds(nr, nc, rows, cols) || visited[nr][nc]) {
                    continue;
                }
                char neighbour = board.grid[nr][nc];
                if (neighbour == 'T' || neighbour == 'S' || neighbour == 'E') {
                    continue;   // walls, start or the exit itself are not traversed further
                }
                visited[nr][nc] = true;
                q.add(new Node(nr, nc, d + 1));
            }
        }
        return total;
    }

    /** Utility to check array bounds. */
    private static boolean outOfBounds(int r, int c, int rows, int cols) {
        return r < 0 || r >= rows || c < 0 || c >= cols;
    }

    /** Entry point – ties everything together. */
    public static void main(String[] args) throws IOException {
        // Use try‑with‑resources to guarantee streams are closed.
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
             PrintWriter out = new PrintWriter(System.out)) {

            Board board = readInput(br);
            int shortest = bfsToExit(board, board.start);
            int answer = collectScore(board, shortest);
            out.println(answer);
        }
    }
}

import java.io.*;
import java.util.*;
import java.util.stream.*;

/**
 * Refactored solution for the “Round 192 – D” problem.
 *
 * <p>This version focuses on readability, maintainability and proper separation of
 * concerns while preserving the original algorithmic behaviour.</p>
 */
public class Round_192_D {

    /* --------------------------------------------------------------------- */
    /*  Constants & small utility types                                        */
    /* --------------------------------------------------------------------- */

    /** Direction vectors for the four possible moves. */
    private static final int[] DR = {1, -1, 0, 0};
    private static final int[] DC = {0, 0, 1, -1};

    /** Simple holder for a breeder cell (distance from the exit, quantity). */
    private static final class Breeder {
        final int distance;
        final int quantity;

        Breeder(int distance, int quantity) {
            this.distance = distance;
            this.quantity = quantity;
        }
    }

    /** Fast scanner that works with a {@link Reader} (file or stream). */
    private static final class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner(Reader source) {
            this.br = new BufferedReader(source);
        }

        /** Return the next token, or {@code null} if the input is exhausted. */
        private String nextToken() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                String line = br.readLine();
                if (line == null) {
                    return null;
                }
                st = new StringTokenizer(line);
            }
            return st.nextToken();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(nextToken());
        }

        long nextLong() throws IOException {
            return Long.parseLong(nextToken());
        }

        double nextDouble() throws IOException {
            return Double.parseDouble(nextToken());
        }
    }

    /** Grid position (row, column). */
    private static final class Position {
        final int row;
        final int col;

        Position(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }

    /* --------------------------------------------------------------------- */
    /*  Core solving logic                                                    */
    /* --------------------------------------------------------------------- */

    /** Entry point – reads from {@code System.in} and delegates to the solver. */
    public static void main(String[] args) throws IOException {
        // The try‑with‑resources block guarantees that the underlying stream is closed.
        try (FastScanner fs = new FastScanner(new InputStreamReader(System.in))) {
            solve(fs);
        }
    }

    /** main algorithm – completely self‑contained and easy to test. */
    private static void solve(FastScanner fs) {
        // ----- 1. read the map ------------------------------------------------
        int rows = fs.nextInt();
        int cols = fs.nextInt();

        List<String> grid = readGrid(fs, rows);
        locateExitAndStart(grid);

        // ----- 2. breadth‑first search from the exit ---------------------------
        int[][] distance = bfs(grid);

        // ----- 3. collect breeder data -----------------------------------------
        List<Breeder> breeders = collectBreeders(grid, distance);
        int myDistance = distance[startRow][startCol];   // distance from exit to 'S'

        // ----- 4. compute answer ------------------------------------------------
        long answer = breeders.stream()
                .filter(b -> b.distance <= myDistance)
                .mapToLong(b -> b.quantity)
                .sum();

        System.out.println(answer);
    }

    /** Reads exactly {@code rows} tokens, each representing one grid line. */
    private static List<String> readGrid(FastScanner fs, int rows) throws IOException {
        List<String> grid = new ArrayList<>(rows);
        for (int r = 0; r < rows; r++) {
            grid.add(fs.next());
        }
        return grid;
    }

    /** Stores the coordinates of the unique 'E' (exit) and 'S' (start). */
    private static int exitRow, exitCol, startRow, startCol;

    /** Locate the exit ('E') and the start ('S') cells in the grid. */
    private static void locateExitAndStart(List<String> grid) {
        exitRow = exitCol = startRow = startCol = -1;

        for (int r = 0; r < grid.size(); r++) {
            String line = grid.get(r);
            int eIdx = line.indexOf('E');
            if (eIdx >= 0) {
                exitRow = r;
                exitCol = eIdx;
            }
            int sIdx = line.indexOf('S');
            if (sIdx >= 0) {
                startRow = r;
                startCol = sIdx;
            }
        }

        if (exitRow < 0 || startRow < 0) {
            throw new IllegalArgumentException(
                    "Grid must contain exactly one 'E' and one 'S'");
        }
    }

    /** Perform BFS from the exit cell, filling the distance matrix. */
    private static int[][] bfs(List<String> grid) {
        // reset mutable static state used by the search
        resetSearchState();

        int rows = grid.size();
        int cols = grid.isEmpty() ? 0 : grid.get(0).length();

        int[][] dist = new int[rows][cols];
        for (int[] row : dist) {
            Arrays.fill(row, -1);
        }

        Queue<Position> queue = new LinkedList<>();
        queue.add(new Position(exitRow, exitCol));
        dist[exitRow][exitCol] = 0;

        while (!queue.isEmpty()) {
            Position cur = queue.poll();
            int r = cur.row;
            int c = cur.col;
            int d = dist[r][c];

            processCell(r, c, d, grid, dist, queue);

            exploreNeighbours(r, c, d, grid, dist, queue);
        }

        return dist;
    }

    /** Reset all static fields that are mutated during a search. */
    private static void resetSearchState() {
        breeders = new ArrayList<>();
        myDistance = -1;
    }

    /** Holds the list of breeders discovered so far (used by BFS). */
    private static List<Breeder> breeders;

    /** Distance from the exit to the start cell – filled after BFS finishes. */
    private static int myDistance;

    /** Examine the current cell: count breeders or remember the start distance. */
    private static void processCell(int r, int c, int d,
                                    List<String> grid,
                                    int[][] dist,
                                    Queue<Position> queue) {
        char cell = grid.get(r).charAt(c);
        if (Character.isDigit(cell)) {
            int qty = Character.digit(cell, 10);
            breeders.add(new Breeder(d, qty));
        } else if (cell == 'S') {
            // remember my distance for the final answer
            myDistance = d;
        }
    }

    /** Add all reachable neighbour cells to the BFS queue. */
    private static void exploreNeighbours(int r, int c,
                                          int d,
                                          List<String> grid,
                                          int[][] dist,
                                          Queue<Position> queue) {
        int rows = grid.size();
        int cols = grid.isEmpty() ? 0 : grid.get(0).length();

        for (int dir = 0; dir < 4; dir++) {
            int nr = r + DR[dir];
            int nc = c + DC[dir];
            if (isInBounds(nr, nc, rows, cols)
                    && dist[nr][nc] == -1
                    && !isTree(nr, nc, grid)) {
                dist[nr][nc] = d + 1;
                queue.add(new Position(nr, nc));
            }
        }
    }

    /** Check whether a cell contains a tree ('T'). */
    private static boolean isTree(int r, int c, List<String> grid) {
        return grid.get(r).charAt(c) == 'T';
    }

    /** Verify that a coordinate lies inside the grid. */
    private static boolean isInBounds(int r, int c, int rows, int cols) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }
}

import java.util.ArrayDeque;
import java.util.Deque;
import java.util.Scanner;

/**
 * Main application that reads a grid, performs a BFS from the exit cell,
 * and computes the total number of trainers collected before reaching the
 * start cell ('S').
 *
 * <p>Refactor goals:
 *   <ul>
 *     <li>Extract input handling into its own method.</li>
 *     <li>Introduce a {@link Position} record for type‑safe queue elements.</li>
 *     <li>Use {@code ArrayDeque} instead of a raw {@code LinkedList}.</li>
 *     <li>Make constants explicit and avoid magic numbers.</li>
 *     <li>Separate traversal logic from the {@code main} method.</li>
 *   </ul>
 *
 * @author  (Your Name)
 */
public class Main {

    /** Symbol that marks the start cell. */
    private static final char START = 'S';

    /** Symbol that marks the exit cell. */
    private static final char EXIT = 'E';

    /** Symbol that marks a trap that cannot be entered. */
    private static final char TRAP = 'T';

    /** Symbol that holds a single trainer ('0'‑'9'). */
    private static final char TRAINER_MARK = 'T';

    /** A position in the grid (row, column). */
    private static final class Position {
        final int row;
        final int col;

        Position(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }

    /**
     * Reads the grid from {@code in} and returns an immutable view of the
     * data together with the coordinates of the exit cell.
     *
     * @param in a {@link Scanner} positioned at the start of the input
     * @return a {@link GridInfo} containing the grid and the exit location
     */
    private static GridInfo readInput(Scanner in) {
        int rows = in.nextInt();
        int cols = in.nextInt();

        char[][] grid = new char[rows][cols];
        char[][] trainerGrid = new char[rows][cols]; // stores the digit value
        int exitRow = -1, exitCol = -1;

        for (int r = 0; r < rows; r++) {
            String line = in.next();
            for (int c = 0; c < cols; c++) {
                char cell = line.charAt(c);
                grid[r][c] = cell;

                // Remember trainer digits separately for easy conversion
                char trainerDigit = (cell >= '0' && cell <= '9') ? cell : TRAINER_MARK;
                trainerGrid[r][c] = trainerDigit;

                if (cell == EXIT) {
                    exitRow = r;
                    exitCol = c;
                }
            }
        }

        if (exitRow == -1 || exitCol == -1) {
            throw new IllegalArgumentException("Exit cell 'E' must be present in the grid.");
        }

        return new GridInfo(grid, trainerGrid, exitRow, exitCol);
    }

    /**
     * Performs a breadth‑first search starting from the exit cell.
     * While traversing, it collects the trainer values of all cells that
     * are reachable before the start cell is encountered.
     *
     * @param info   the grid layout and trainer values
     * @return the total number of trainers collected
     */
    private static int performBfs(GridInfo info) {
        char[][] grid = info.grid;
        int[][] trainerDigits = info.trainerDigits;
        int rows = grid.length;
        int cols = grid[0].length;

        // Distance matrix; -1 means "unvisited"
        int[][] distance = new int[rows][cols];
        for (int[] row : distance) {
            java.util.Arrays.fill(row, -1);
        }

        Deque<Position> queue = new ArrayDeque<>();
        Position startPos = new Position(info.exitRow, info.exitCol);
        queue.add(startPos);
        distance[startPos.row][startPos.col] = 0;

        int totalTrainers = 0;
        boolean startReached = false;

        while (!queue.isEmpty() && !startReached) {
            Position current = queue.pollFirst();
            int r = current.row;
            int c = current.col;
            int curDist = distance[r][c];

            // Stop processing further nodes once we have reached the start cell.
            // The original code processes all nodes that share the same distance,
            // so we handle that situation explicitly.
            if (grid[r][c] == START) {
                // Process all pending nodes that are at the same distance or less.
                while (!queue.isEmpty()) {
                    Position pending = queue.pollFirst();
                    int pr = pending.row, pc = pending.col;
                    if (distance[pr][pc] <= curDist) {
                        totalTrainers += trainerDigits[pr][pc];
                    }
                }
                startReached = true;
                break;
            }

            // Collect trainer value for the current cell (except the exit itself).
            if (grid[r][c] != EXIT) {
                totalTrainers += trainerDigits[r][c];
            }

            // Explore the four orthogonal neighbours.
            int[][] deltas = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};
            for (int[] delta : deltas) {
                int nr = r + delta[0];
                int nc = c + delta[1];
                if (isInBounds(nr, nc, rows, cols) &&
                        grid[nr][nc] != TRAP && distance[nr][nc] == -1) {
                    queue.add(new Position(nr, nc));
                    distance[nr][nc] = curDist + 1;
                }
            }
        }

        return totalTrainers;
    }

    /** Helper to check whether a coordinate lies inside the grid. */
    private static boolean isInBounds(int r, int c, int rows, int cols) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    /** Simple container for the parsed grid information. */
    private static final class GridInfo {
        final char[][] grid;
        final int[][] trainerDigits; // holds numeric trainer values (0‑9)
        final int exitRow;
        final int exitCol;

        GridInfo(char[][] grid, int[][] trainerDigits, int exitRow, int exitCol) {
            this.grid = grid;
            this.trainerDigits = trainerDigits;
            this.exitRow = exitRow;
            this.exitCol = exitCol;
        }
    }

    /** Entry point of the application. */
    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            GridInfo info = readInput(scanner);
            int result = performBfs(info);
            System.out.println(result);
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Main entry point for the program.
 * Reads the input, creates a solver and prints the answer.
 */
public class Main {

    public static void main(String[] args) throws IOException {
        FastScanner fs = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(System.out);

        int rows = fs.nextInt();
        int cols = fs.nextInt();

        Grid grid = new Grid(rows, cols);
        grid.readFrom(fs);

        Solver solver = new Solver();
        long result = solver.solve(grid);

        out.println(result);
        out.close();
    }

    /** Simple scanner that tokenises whole lines for speed and readability. */
    private static final class FastScanner {
        private final BufferedReader br;
        private String[] tokens = new String[0];
        private int index = 0;

        FastScanner(InputStream source) {
            br = new BufferedReader(new InputStreamReader(source));
        }

        /** Returns the next non‑null token. */
        String next() {
            while (tokens.length == 0 || index >= tokens.length) {
                try {
                    String line = br.readLine();
                    if (line == null) {
                        return null;
                    }
                    tokens = line.split("\\s+");
                    index = 0;
                } catch (IOException e) {
                    throw new UncheckedIOException(e);
                }
            }
            return tokens[index++];
        }

        int nextInt() { return Integer.parseInt(next()); }
    }

    /**
     * Represents the playing field with a permanent wall border.
     * Stores the numeric values of cells, and also the start and exit positions.
     */
    private static final class Grid {
        /** Value used for wall cells (outside the playable area). */
        static final int WALL = -1;

        private final int rows;          // number of rows inside the border
        private final int cols;          // number of columns inside the border
        private final int[][] cells;      // (rows+2) x (cols+2) including the border
        private int startR = -1, startC = -1;
        private int exitR = -1, exitC = -1;

        Grid(int rows, int cols) {
            this.rows = rows;
            this.cols = cols;
            cells = new int[rows + 2][cols + 2];
            wallBorder();
        }

        /** Initialise the outer wall with {@link #WALL}. */
        private void wallBorder() {
            int maxCol = cols + 1;
            for (int i = 0; i < cells.length; i++) {
                cells[i][0] = cells[i][maxCol] = WALL;          // left & right
            }
            for (int j = 0; j < cells[0].length; j++) {
                cells[0][j] = cells[rows + 1][j] = WALL;        // top & bottom
            }
        }

        /** Fill the inner area from the input stream. */
        void readFrom(FastScanner fs) {
            for (int i = 1; i <= rows; i++) {
                String line = fs.next();
                if (line == null) {
                    throw new IllegalStateException("Unexpected end of input");
                }
                if (line.length() != cols) {
                    throw new IllegalArgumentException("Row length mismatch");
                }
                for (int j = 1; j <= cols; j++) {
                    char ch = line.charAt(j - 1);
                    if (ch == 'T') {
                        cells[i][j] = WALL;
                    } else if (ch == 'S') {
                        startR = i;
                        startC = j;
                        cells[i][j] = 0;          // treat start as empty (0)
                    } else if (ch == 'E') {
                        exitR = i;
                        exitC = j;
                        cells[i][j] = 0;          // treat exit as empty (0)
                    } else if (Character.isDigit(ch)) {
                        cells[i][j] = ch - '0';
                    } else {
                        throw new IllegalArgumentException("Invalid character: " + ch);
                    }
                }
            }
            if (startR == -1 || exitR == -1) {
                throw new IllegalStateException("Start or exit not found in the grid");
            }
        }

        /** Accessors for the internal data. */
        int getCell(int r, int c) { return cells[r][c]; }
        int getRows() { return rows; }
        int getCols() { return cols; }
        int getStartRow() { return startR; }
        int getStartCol() { return startC; }
        int getExitRow() { return exitR; }
        int getExitCol() { return exitC; }

        /** Simple immutable point used for BFS coordinates. */
        static final class Point {
            final int row;
            final int col;
            Point(int row, int col) {
                this.row = row;
                this.col = col;
            }
        }
    }

    /**
     * Contains the algorithm that solves the problem.
     * Currently it performs a BFS from the exit and sums all numeric cells
     * that are reachable within the same number of steps needed to reach the start.
     */
    private static final class Solver {
        long solve(Grid grid) {
            int exitRow = grid.getExitRow();
            int exitCol = grid.getExitCol();
            int startRow = grid.getStartRow();
            int startCol = grid.getStartCol();

            int[][] distances = bfsFrom(grid, exitRow, exitCol);

            int minStepsToExit = distances[startRow][startCol];
            long sum = 0;

            for (int r = 1; r <= grid.getRows(); r++) {
                for (int c = 1; c <= grid.getCols(); c++) {
                    int value = grid.getCell(r, c);
                    if (value > 0 && distances[r][c] <= minStepsToExit) {
                        sum += value;
                    }
                }
            }
            return sum;
        }

        /** Breadth‑first search that returns a distance matrix from the given source. */
        private int[][] bfsFrom(Grid grid, int srcR, int srcC) {
            final int ROWS = grid.getRows() + 2;
            final int COLS = grid.getCols() + 2;

            int[][] dist = new int[ROWS][COLS];
            boolean[][] visited = new boolean[ROWS][COLS];
            for (int[] row : dist) {
                Arrays.fill(row, Integer.MAX_VALUE);
            }

            Deque<Grid.Point> queue = new ArrayDeque<>();
            queue.add(new Grid.Point(srcR, srcC));
            dist[srcR][srcC] = 0;
            visited[srcR][srcC] = true;

            final int[] DR = {-1, 1, 0, 0};
            final int[] DC = {0, 0, -1, 1};

            while (!queue.isEmpty()) {
                Grid.Point cur = queue.pollFirst();
                for (int d = 0; d < 4; d++) {
                    int nr = cur.row + DR[d];
                    int nc = cur.col + DC[d];
                    if (!isInside(nr, nc) || isWall(nr, nc)) {
                        continue;
                    }
                    if (visited[nr][nc]) {
                        continue;
                    }
                    visited[nr][nc] = true;
                    dist[nr][nc] = dist[cur.row][cur.col] + 1;
                    queue.addLast(new Grid.Point(nr, nc));
                }
            }
            return dist;
        }

        private boolean isInside(int r, int c) {
            return r >= 0 && c >= 0 && r < ROWS && c < COLS;
        }

        private boolean isWall(int r, int c) {
            return grid.getCell(r, c) == Grid.WALL;
        }
    }
}

import java.io.*;
import java.util.LinkedList;
import java.util.Queue;

/**
 * Solves the problem described in the original {@code Problem329B}.
 * The program reads a grid, performs a BFS from the start cell to the end cell,
 * and then sums the numeric values of all reachable cells whose distance is
 * not larger than the distance to the end cell.
 *
 * The refactor focuses on readability, proper naming, elimination of dead code
 * and use of modern Java practices (try‑with‑resources, small helper methods,
 * clear separation of concerns).
 */
public class Solver {

    /** sentinel value used for “unvisited / unreachable” distances */
    private static final int INF = Integer.MAX_VALUE / 4;   // safe against overflow

    /** direction vectors (up, left, down, right) */
    private static final int[] DR = { -1, 0, 1, 0 };
    private static final int[] DC = { 0, -1, 0, 1 };

    public static void main(String[] args) throws IOException {
        // Input is read from standard input
        try (Reader reader = new BufferedReader(new InputStreamReader(System.in))) {
            Solver solver = new Solver();
            solver.solve(reader, System.out);
        }
    }

    /**
     * Core logic – split into small, reusable steps.
     */
    private void solve(Reader input, PrintWriter output) {
        int rows = input.nextInt();
        int cols = input.nextInt();

        char[][] grid = new char[rows + 1][cols + 1];
        int startR = -1, startC = -1;   // coordinates of 'S'
        int endR = -1, endC = -1;       // coordinates of 'E'

        // Read the grid while locating start and end positions
        for (int r = 1; r <= rows; r++) {
            String line = input.readString();
            for (int c = 1; c <= cols; c++) {
                grid[r][c] = line.charAt(c - 1);
                if (grid[r][c] == 'S') {
                    startR = r;
                    startC = c;
                } else if (grid[r][c] == 'E') {
                    endR = r;
                    endC = c;
                }
            }
        }

        // ---- BFS from the start cell ----
        int[][] distance = new int[rows + 1][cols + 1];
        boolean[][] visited = new boolean[rows + 1][cols + 1];

        for (int[] row : distance) {
            java.util.Arrays.fill(row, INF);
        }

        distance[startR][startC] = 0;
        visited[startR][startC] = true;

        Queue<Position> queue = new LinkedList<>();
        queue.add(new Position(startR, startC));

        while (!queue.isEmpty()) {
            Position cur = queue.poll();
            int curDist = distance[cur.r][cur.c];

            for (int dir = 0; dir < 4; dir++) {
                int nr = cur.r + DR[dir];
                int nc = cur.c + DC[dir];

                // bounds check and skip walls ('T')
                if (!inBounds(nr, rows, cols) || grid[nr][nc] == 'T') {
                    continue;
                }

                if (distance[nr][nc] > curDist + 1) {
                    distance[nr][nc] = curDist + 1;
                    if (!visited[nr][nc]) {
                        visited[nr][nc] = true;
                        queue.add(new Position(nr, nc));
                    }
                }
            }
        }

        int distanceToEnd = distance[endR][endC];
        int answer = 0;

        // Sum numeric values of cells whose distance does not exceed the distance to the exit
        for (int r = 1; r <= rows; r++) {
            for (int c = 1; c <= cols; c++) {
                char ch = grid[r][c];
                if (isNumericCell(ch) && distance[r][c] <= distanceToEnd) {
                    answer += (ch - '0');
                }
            }
        }

        output.println(answer);
    }

    /** Simple container for a grid position. */
    private static final class Position {
        final int r, c;
        Position(int r, int c) {
            this.r = r;
            this.c = c;
        }
    }

    /** Checks whether a character represents a digit (the cells we may add). */
    private static boolean isNumericCell(char ch) {
        return ch >= '0' && ch <= '9';
    }

    /** Utility method used only by the parser – reads the next whitespace‑separated token. */
    private static class Reader {
        private final BufferedReader br;
        private StringTokenizer st;

        Reader(BufferedReader br) {
            this.br = br;
        }

        String nextToken() throws IOException {
            while (st == null || !st.hasMoreElements()) {
                String line = br.readLine();
                if (line == null) {
                    return null;
                }
                st = new StringTokenizer(line);
            }
            return st.nextToken();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(nextToken());
        }

        String readString() throws IOException {
            return nextToken();
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Solves the “Biridian Forest” problem.
 *
 * <p>
 * The algorithm:
 * <ol>
 *   <li>Read the grid.</li>
 *   <li>Run a Dijkstra‑like BFS from the destination cell {@code 'E'}.
 *       The distance stored for each traversable cell is the number of steps
 *       needed to reach {@code 'E'}.</li>
 *   <li>Determine the distance {@code minDist} from the start cell {@code 'S'}
 *       to {@code 'E'}.</li>
 *   <li>Sum the numeric values of all traversable cells whose stored distance
 *       is {@code <= minDist}.</li>
 *   <li>Print the sum.</li>
 * </ol>
 * </p>
 */
public class Main {

    /** Parser for fast token based input. */
    private static final class FastInput {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        FastInput(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream, 32768));
        }

        /** Returns {@code true} if the next token exists. */
        private boolean hasMoreTokens() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                String line = reader.readLine();
                if (line == null) {
                    return false;
                }
                tokenizer = new StringTokenizer(line);
            }
            return true;
        }

        /** Reads the next token. */
        String next() {
            while (!hasMoreTokens()) {
                throw new IOException("No more tokens");
            }
            return tokenizer.nextToken();
        }

        /** Reads an {@code int}. */
        int nextInt() {
            return Integer.parseInt(next());
        }

        /** Reads a {@code char} (used for single‑character symbols). */
        char nextChar() {
            return next().charAt(0);
        }
    }

    /** Solver class encapsulating all problem‑specific logic. */
    private static final class ForestSolver {

        /** Symbols used in the grid. */
        private static final char EMPTY   = '-';
        private static final char TREE    = 'T';
        private static final char START   = 'S';
        private static final char END     = 'E';
        private static final int  INF     = Integer.MAX_VALUE / 4; // safety margin

        /** Direction vectors for the four neighbours. */
        private static final int[] DR = {-1, 1, 0, 0};
        private static final int[] DC = {0, 0, -1, 1};

        /** Size of the grid. */
        private int rows;
        private int cols;

        /** Grid storage. */
        private int[][] value;          // numeric value of each cell ( -1 for trees )
        private int[][] minDist;        // shortest distance to the destination

        /** Input data. */
        private final FastInput in;

        /** Output writer. */
        private final PrintWriter out;

        /** Destination (end) coordinates. */
        private int endR, endC;
        /** Start coordinates. */
        private int startR, startC;

        ForestSolver(FastInput in, PrintWriter out) {
            this.in = in;
            this.out = out;
        }

        /** Entry point called by {@code Main.main}. */
        void solve() {
            readInput();
            prepareDataStructures();
            computeShortestDistances();
            int sum = sumOfValuesWithinDistance();
            out.println(sum);
        }

        /** Reads the whole input and fills the instance fields. */
        private void readInput() {
            rows = in.nextInt();
            cols = in.nextInt();

            // Allocate structures
            value = new int[rows][cols];
            minDist = new int[rows][cols];
            for (int[] row : minDist) {
                Arrays.fill(row, INF);
            }

            // Locate start and end, fill numeric values
            for (int r = 0; r < rows; ++r) {
                String line = in.next();
                for (int c = 0; c < cols; ++c) {
                    char ch = line.charAt(c);
                    switch (ch) {
                        case TREE -> {
                            value[r][c] = -1;          // trees are obstacles
                        }
                        case START -> {
                            startR = r;
                            startC = c;
                            value[r][c] = 0;             // start cell has no numeric cost
                        }
                        case END -> {
                            endR = r;
                            endC = c;
                            value[r][c] = 0;             // end cell has no numeric cost
                        }
                        default -> value[r][c] = Character.getNumericValue(ch);
                    }
                }
            }
        }

        /** Initialise distance of the destination to 0 and enqueue it. */
        private void prepareDataStructures() {
            minDist[endR][endC] = 0;
        }

        /**
         * Dijkstra‑like BFS from {@code (endR, endC)}.
         * Only moves through cells that are not trees.
         */
        private void computeShortestDistances() {
            PriorityQueue<Step> pq = new PriorityQueue<>(Comparator.comparingInt(s -> s.dist));
            pq.add(new Step(endR, endC, 0));

            while (!pq.isEmpty()) {
                Step cur = pq.poll();

                // Skip outdated entries
                if (cur.dist != minDist[cur.r][cur.c]) {
                    continue;
                }

                // Explore the four neighbours
                for (int dir = 0; dir < 4; ++dir) {
                    int nr = cur.r + DR[dir];
                    int nc = cur.c + DC[dir];
                    if (!isInside(nr, nc)) {
                        continue;
                    }
                    if (value[nr][nc] == -1) {
                        continue; // obstacle
                    }
                    int ndist = cur.dist + 1;
                    if (ndist < minDist[nr][nc]) {
                        minDist[nr][nc] = ndist;
                        pq.add(new Step(nr, nc, ndist));
                    }
                }
            }
        }

        /** Returns the sum of cell values whose distance is {@code <= minDist[start]}. */
        private int sumOfValuesWithinDistance() {
            int minDistFromStart = minDist[startR][startC];
            int sum = 0;

            for (int r = 0; r < rows; ++r) {
                for (int c = 0; c < cols; ++c) {
                    if (value[r][c] != -1 && minDist[r][c] <= minDistFromStart) {
                        sum += value[r][c];
                    }
                }
            }
            return sum;
        }

        /** Simple bounds check. */
        private boolean isInside(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }

        /** Helper class representing a cell together with its distance from the destination. */
        private static final class Step {
            final int r, c;
            final int dist;

            Step(int r, int c, int dist) {
                this.r = r;
                this.c = c;
                this.dist = dist;
            }
        }
    }

    /** --------------------------------------------------------------------- */

    public static void main(String[] args) throws Exception {
        // Use try‑with‑resources to guarantee streams are closed
        try (InputStream inStream = System.in;
             OutputStream outStream = System.out) {

            FastInput fastIn = new FastInput(inStream);
            PrintWriter out = new PrintWriter(outStream);

            ForestSolver solver = new ForestSolver(fastIn, out);
            solver.solve();

            out.flush(); // optional, PrintWriter flushes on close
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Reads a grid containing one start cell {@code S}, one end cell {@code E},
 * obstacles {@code T} and digits {@code 0‑9}.  Using a breadth‑first search
 * from {@code E} to {@code S} the program computes the minimum number of
 * moves needed to reach {@code S} and then sums the digits that are at most
 * that many moves away from {@code E}.  The result is printed to {@code STDOUT}.
 *
 * The implementation is intentionally split into small, focused methods and
 * well‑named constants to improve readability and maintainability.
 */
public class Main {

    /** Modulus used for the included number‑theoretic helpers (kept for compatibility). */
    private static final long MOD = 1_000_000_007L;

    /** Directions: down, right, up, left. */
    private static final int[] DX = {1, 0, -1, 0};
    private static final int[] DY = {0, 1, 0, -1};

    /** Fast scanner that wraps {@link BufferedReader}. */
    private static final class FastScanner {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        FastScanner(InputStream stream) {
            this.reader = new BufferedReader(new InputStreamReader(stream));
        }

        /** Returns the next non‑empty token. */
        private void ensureTokenizer() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                tokenizer = new StringTokenizer(reader.readLine());
            }
        }

        String next() throws IOException {
            ensureTokenizer();
            return tokenizer.nextToken();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }

        long nextLong() throws IOException {
            return Long.parseLong(next());
        }

        double nextDouble() throws IOException {
            return Double.parseDouble(next());
        }

        /** Returns the entire next line (or {@code null} on EOF). */
        String nextLine() throws IOException {
            return reader.readLine();
        }
    }

    /** Utility methods that were originally scattered throughout the file. */
    private static final class Utilities {

        /** Extended Euclidean algorithm – returns {@code [g, x, y]} where {@code g = gcd(p,q)}. */
        static long[] extendedGcd(long p, long q) {
            if (q == 0) {
                return new long[]{p, 1, 0};
            }
            long[] vals = extendedGcd(q, p % q);
            long g = vals[0];
            long x = vals[2];
            long y = vals[1] - (p / q) * vals[2];
            return new long[]{g, x, y};
        }

        /** Fast modular exponentiation using binary exponentiation. */
        static long modPow(long base, long exponent) {
            if (exponent == 0) {
                return 1;
            }
            if ((exponent & 1) == 0) {
                long half = modPow(base, exponent / 2);
                return (half * half) % MOD;
            }
            return (base * modPow(base, exponent - 1)) % MOD;
        }
    }

    /** Entry point of the program. */
    public static void main(String[] args) throws Exception {
        FastScanner scanner = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(System.out, true);

        // -----------------------------------------------------------------
        // 1. Read grid dimensions and the grid itself.
        // -----------------------------------------------------------------
        int rows = scanner.nextInt();
        int cols = scanner.nextInt();

        char[][] grid = new char[rows][cols];
        Pos start = null;   // position of 'S'
        Pos end   = null;   // position of 'E'

        for (int r = 0; r < rows; r++) {
            String line = scanner.next();
            for (int c = 0; c < cols; c++) {
                char ch = line.charAt(c);
                grid[r][c] = ch;
                if (ch == 'S') {
                    start = new Pos(r, c);
                } else if (ch == 'E') {
                    end = new Pos(r, c);
                }
            }
        }

        // -----------------------------------------------------------------
        // 2. BFS from the end cell ('E') to compute distances to every reachable cell.
        // -----------------------------------------------------------------
        int[][] distance = new int[rows][cols];
        for (int[] row : distance) {
            Arrays.fill(row, -1);
        }
        distance[end.row][end.col] = 0;

        Queue<Pos> queue = new ArrayDeque<>();
        queue.add(end);

        while (!queue.isEmpty()) {
            Pos cur = queue.poll();
            for (int dir = 0; dir < 4; dir++) {
                int nr = cur.row + DY[dir];
                int nc = cur.col + DX[dir];
                if (!inBounds(nr, cols) || !inBounds(nc, rows)) {
                    continue;
                }
                if (grid[nr][nc] == 'T' || distance[nr][nc] != -1) {
                    continue;
                }
                distance[nr][nc] = distance[cur.row][cur.col] + 1;
                queue.add(new Pos(nr, nc));
            }
        }

        // -----------------------------------------------------------------
        // 3. Determine the minimal distance from 'E' to 'S' and sum qualifying digits.
        // -----------------------------------------------------------------
        int minDistanceToStart = distance[start.row][start.col];
        long result = 0;

        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                int d = distance[r][c];
                if (d != -1 && d <= minDistanceToStart &&
                    Character.isDigit(grid[r][c])) {
                    result += grid[r][c] - '0';
                }
            }
        }

        out.println(result);
        // -----------------------------------------------------------------
        // The following static helpers are kept for backward compatibility
        // with the original source but are not used directly by the main logic.
        // -----------------------------------------------------------------
        // Utilities such as gcd/pow are retained unchanged.
        // -----------------------------------------------------------------
        // No further action required here.
    }

    /** Simple container for a grid position. */
    private static final class Pos {
        final int row;
        final int col;

        Pos(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }

    /** Checks whether a coordinate lies inside a rectangular grid. */
    private static boolean inBounds(int x, int limit) {
        return x >= 0 && x < limit;
    }
}

