import java.awt.Point;
import java.io.*;
import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.List;
import java.util.StringTokenizer;

/**
 * Main class that contains the solution for the problem.
 * The program reads a grid, computes the shortest distance from the exit (E)
 * to every reachable cell, then sums all digit characters that are not farther
 * from the exit than the start cell (S).
 */
public class ProblemA {

    /** marker for a blocked cell (cannot be traversed) */
    private static final int BLOCKED = -2;

    /** marker for an unvisited cell */
    private static final int UNVISITED = -1;

    /** directions used for neighbour expansion */
    private static final int[] DR = { -1, 1, 0, 0 };
    private static final int[] DC = { 0, 0, -1, 1 };

    /** prefix printed for each sample when the program runs in “file” mode */
    private static final String SAMPLE_PREFIX = "Sample #";

    /** separates samples in the output file */
    private static final String SAMPLE_SEPARATOR = "\n";

    public static void main(String[] args) throws IOException {
        try (InputReader reader = new InputReader();
             PrintWriter writer = createOutputWriter(args);
             DebugWriter debug = new DebugWriter(true)) {

            int sampleIndex = 1;
            do {
                String prefix = SAMPLE_PREFIX + sampleIndex + ": ";
                writer.println(prefix);
                debug.println(prefix);

                solve(reader, writer, debug);

                writer.print(SAMPLE_SEPARATOR);
                debug.println(SAMPLE_SEPARATOR);

                sampleIndex++;
            } while (reader.hasMoreInput());

            debug.flush();
        }
    }

    /**
     * Reads the whole input, runs the algorithm and writes the answer.
     */
    private static void solve(InputReader reader,
                              PrintWriter writer,
                              DebugWriter debug) throws IOException {

        int rows = reader.nextInt();
        int columns = reader.nextInt();

        char[][] grid = readGrid(reader, rows, columns);
        int[][] distance = new int[rows][columns];

        // locate start (S) and exit (E) positions
        Point start = locateCell(grid, 'S');
        Point exit = locateCell(grid, 'E');

        // initialise distance matrix
        initialiseDistanceMatrix(distance, grid, start, exit);

        // perform multi‑source BFS from the exit
        bfsFromExit(grid, distance, exit);

        // distance from start to exit is stored in start's cell
        int distanceToExit = distance[start.x][start.y];
        debug.print("Distance from start to exit: " + distanceToExit + " ");

        // print the distance matrix if debugging is enabled
        debug.println();
        printDistanceMatrix(distance, debug);

        // count the sum of all digit cells that are not farther than the exit
        long digitSum = countDigitsWithinLimit(grid, distance, distanceToExit);
        writer.println(digitSum);
    }

    /**
     * Reads the grid rows from the input reader.
     */
    private static char[][] readGrid(InputReader reader, int rows, int columns) {
        char[][] grid = new char[rows][columns];
        for (int r = 0; r < rows; r++) {
            String line = reader.next();
            for (int c = 0; c < columns; c++) {
                grid[r][c] = line.charAt(c);
            }
        }
        return grid;
    }

    /**
     * Finds the first occurrence of a given character in the grid.
     */
    private static Point locateCell(char[][] grid, char target) {
        for (int r = 0; r < grid.length; r++) {
            for (int c = 0; c < grid[r].length; c++) {
                if (grid[r][c] == target) {
                    return new Point(r, c);
                }
            }
        }
        throw new IllegalArgumentException("Target cell not found");
    }

    /**
     * Initializes the distance matrix:
     *   - -2 (blocked) stays -2,
     *   - start cell gets a placeholder (will be overwritten later),
     *   - exit cell gets distance 0,
     *   - all other cells are marked UNVISITED (-1).
     */
    private static void initialiseDistanceMatrix(int[][] distance,
                                                  char[][] grid,
                                                  Point start,
                                                  Point exit) {
        for (int r = 0; r < grid.length; r++) {
            for (int c = 0; c < grid[r].length; c++) {
                distance[r][c] = UNVISITED;
                if (grid[r][c] == 'T') {
                    distance[r][c] = BLOCKED;
                }
            }
        }

        distance[exit.x][exit.y] = 0;               // exit is the BFS source
        // start cell will receive its distance after BFS finishes
    }

    /**
     * Bread‑first‑search starting from the exit cell.
     * All reachable cells receive their distance from the exit.
     */
    private static void bfsFromExit(char[][] grid, int[][] distance, Point startExit) {
        ArrayDeque<Point> queue = new ArrayDeque<>();
        queue.add(startExit);

        while (!queue.isEmpty()) {
            Point cur = queue.pollFirst();
            int curDist = distance[cur.x][cur.y];

            for (int dir = 0; dir < 4; dir++) {
                int nr = cur.x + DR[dir];
                int nc = cur.y + DC[dir];

                if (isInBounds(grid, nr, nc) && distance[nr][nc] == UNVISITED) {
                    distance[nr][nc] = curDist + 1;
                    queue.addLast(new Point(nr, nc));
                }
            }
        }
    }

    /** Returns true if the coordinates are inside the grid and the cell is not blocked. */
    private static boolean isInBounds(char[][] grid, int r, int c) {
        return r >= 0 && r < grid.length &&
               c >= 0 && c < grid[r].length &&
               grid[r][c] != 'T';
    }

    /** Prints the whole distance matrix when debugging is enabled. */
    private static void printDistanceMatrix(int[][] distance, DebugWriter debug) {
        for (int r = 0; r < distance.length; r++) {
            for (int c = 0; c < distance[r].length; c++) {
                debug.print((distance[r][c] >= 0 ? distance[r][c] : "*") + " ");
            }
            debug.println();
        }
    }

    /**
     * Counts the sum of all numeric characters whose distance to the exit
     * is **not larger** than the distance from the start to the exit.
     */
    private static long countDigitsWithinLimit(char[][] grid,
                                               int[][] distance,
                                               int limit) {
        long sum = 0;
        for (int r = 0; r < grid.length; r++) {
            for (int c = 0; c < grid[r].length; c++) {
                if (distance[r][c] >= 0 && distance[r][c] <= limit &&
                    Character.isDigit(grid[r][c])) {
                    sum += Character.digit(grid[r][c], 10);
                }
            }
        }
        return sum;
    }

    /** Creates an appropriate PrintWriter according to the execution mode. */
    private static PrintWriter createOutputWriter(String[] args) throws IOException {
        if (args.length > 0 && "file".equalsIgnoreCase(args[0])) {
            // file mode – write to explicit output file
            return new PrintWriter(new FileWriter("output.txt"));
        }

        // console mode – write to standard output
        return new PrintWriter(new OutputStreamWriter(System.out));
    }
}

