import java.io.PrintWriter;
import java.util.ArrayDeque;
import java.util.Arrays;
import java.util.Deque;

/**
 * Reads a grid from standard input, performs a breadth‑first search from the
 * exit cell and counts the sum of numeric cells that are reachable within the
 * same distance or closer to the exit than the start cell.
 *
 * Input format (as used by the original program):
 * <pre>
 * r c
 * <grid row 0>
 * <grid row 1>
 * ...
 * </pre>
 *
 * Grid characters:
 * <ul>
 *   <li>'S' – start cell (exactly one)</li>
 *   <li>'E' – exit/edence cell (exactly one)</li>
 *   <li>'T' – blocked cell</li>
 *   <li>digit '0'‑'9' – traversable cell containing the digit</li>
 * </ul>
 *
 * Output: a single integer – the described sum.
 */
public class Main {

    /** Directions used for neighbour exploration. */
    private enum Direction {
        RIGHT(0, 1),
        DOWN(1, 0),
        LEFT(0, -1),
        UP(-1, 0);

        final int dr;
        final int dc;

        Direction(int dr, int dc) {
            this.dr = dr;
            this.dc = dc;
        }

        /** Returns an array {@code [dr, dc]} for the direction. */
        int[] offset() {
            return new int[]{dr, dc};
        }
    }

    /** Simple scanner wrapper that implements {@link AutoCloseable}. */
    private static class InputReader implements AutoCloseable {
        private final Scanner scanner;

        InputReader() {
            this.scanner = new Scanner(System.in);
        }

        /** Returns the next token. */
        String next() {
            return scanner.next();
        }

        /** Returns the next int token. */
        int nextInt() {
            return scanner.nextInt();
        }

        @Override
        public void close() {
            scanner.close();
        }
    }

    public static void main(String[] args) {
        try (InputReader in = new InputReader();
             PrintWriter out = new PrintWriter(System.out)) {

            int rows = in.nextInt();
            int cols = in.nextInt();

            char[][] grid = new char[rows][];
            int[] start = new int[2];
            int[] end = new int[2];

            // Read grid and locate start / end positions
            for (int r = 0; r < rows; r++) {
                String line = in.next();               // each row is provided as a single token
                grid[r] = line.toCharArray();
                for (int c = 0; c < cols; c++) {
                    char cell = grid[r][c];
                    if (cell == 'S') {
                        start[0] = r;
                        start[1] = c;
                    } else if (cell == 'E') {
                        end[0] = r;
                        end[1] = c;
                    }
                }
            }

            int[] distanceFromEnd = bfs(grid, end[0], end[1], rows, cols);
            if (distanceFromEnd[start[0] * cols + start[1]] == -1) {
                // start is unreachable from the exit
                out.println(0);
                return;
            }

            int maxDistance = distanceFromEnd[start[0] * cols + start[1]];
            long result = 0;

            // Sum all digit cells that are reachable within maxDistance
            // (excluding the exit cell itself)
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    int idx = r * cols + c;
                    int dist = distanceFromEnd[idx];
                    if (dist == -1) {
                        continue; // unreachable from exit
                    }
                    char cell = grid[r][c];
                    if (cell == 'E') {
                        continue; // skip the exit cell
                    }
                    if (cell >= '0' && cell <= '9' && dist <= maxDistance) {
                        result += cell - '0';
                    }
                }
            }

            out.println(result);
        } catch (Exception e) {
            // In competitive‑programming environments we usually print the stack trace
            // and exit, because the input is assumed to be well‑formed.
            e.printStackTrace();
        }
    }

    /**
     * Breadth‑first search starting from the given position.
     *
     * @param grid   the character grid
     * @param sr     start row
     * @param sc     start column
     * @param rows   number of rows
     * @param cols   number of columns
     * @return an array where index {@code r*cols + c} holds the distance
     *         from {@code (sr,sc)} to that cell, or {@code -1} if unreachable.
     */
    private static int[] bfs(char[][] grid, int sr, int sc, int rows, int cols) {
        int[] dist = new int[rows * cols];
        Arrays.fill(dist, -1);

        Deque<Integer> queue = new ArrayDeque<>();
        int startIdx = sr * cols + sc;
        dist[startIdx] = 0;
        queue.addLast(startIdx);

        while (!queue.isEmpty()) {
            int cur = queue.removeFirst();
            int r = cur / cols;
            int c = cur % cols;

            for (Direction dir : Direction.values()) {
                int nr = r + dir.dr;
                int nc = c + dir.dc;
                if (!isInBounds(nr, nc, rows, cols) || isBlocked(grid[nr][nc])) {
                    continue;
                }
                int nextIdx = nr * cols + nc;
                if (dist[nextIdx] == -1) {
                    dist[nextIdx] = dist[cur] + 1;
                    queue.addLast(nextIdx);
                }
            }
        }
        return dist;
    }

    /** Checks whether a coordinate lies inside the grid rectangle. */
    private static boolean isInBounds(int r, int c, int rows, int cols) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    /** Returns {@code true} if a cell cannot be traversed (i.e., it is a wall). */
    private static boolean isBlocked(char cell) {
        return cell == 'T';
    }
}

import java.io.*;
import java.util.*;

public class Main {

    /* Constants for cell types */
    private static final char ENGINEER = 'E';
    private static final char SPAWN    = 'S';
    private static final char TOWER    = 'T';

    /* I/O helpers */
    private BufferedReader reader;
    private StringTokenizer tokenizer;

    public static void main(String[] args) {
        new Main().run();
    }

    private void run() {
        initIO();
        try {
            solve();
        } finally {
            closeIO();
        }
    }

    private void initIO() {
        reader = new BufferedReader(new InputStreamReader(System.in));
        tokenizer = null;
    }

    private void closeIO() throws IOException {
        reader.close();
    }

    private String nextToken() throws IOException {
        while (tokenizer == null || !tokenizer.hasMoreTokens()) {
            tokenizer = new StringTokenizer(reader.readLine());
        }
        return tokenizer.nextToken();
    }

    private int nextInt() throws IOException {
        return Integer.parseInt(nextToken());
    }

    /** Entry point for the algorithm */
    private void solve() throws IOException {
        int rows = nextInt();
        int cols = nextInt();

        char[][] grid = readGrid(rows);
        int[][] distances = bfs(grid, rows, cols);
        int engineerDistance = locateSpawnDistance(distances, grid, rows, cols);
        int answer = countEligibleEnemies(grid, distances, rows, cols, engineerDistance);
        System.out.println(answer);
    }

    /** Reads the whole grid from the input */
    private char[][] readGrid(int rows) throws IOException {
        char[][] grid = new char[rows][];
        for (int r = 0; r < rows; r++) {
            grid[r] = nextToken().toCharArray();
        }
        return grid;
    }

    /** Breadth‑first search from the engineer position */
    private int[][] bfs(char[][] grid, int rows, int cols) {
        int[][] dist = new int[rows][cols];
        for (int[] row : dist) {
            Arrays.fill(row, -1);
        }

        Queue<Integer> queue = new ArrayDeque<>();
        // Find the engineer ('E') and enqueue its coordinates
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == ENGINEER) {
                    queue.add(r);
                    queue.add(c);
                    dist[r][c] = 0;
                    break;
                }
            }
        }

        // Four possible movement directions
        int[][] directions = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};

        while (!queue.isEmpty()) {
            int x = queue.poll();
            int y = queue.poll();
            int d = dist[x][y];

            for (int[] dir : directions) {
                int nx = x + dir[0];
                int ny = y + dir[1];
                if (inside(nx, ny, rows, cols) && grid[nx][ny] != TOWER) {
                    if (dist[nx][ny] == -1) {
                        dist[nx][ny] = d + 1;
                        queue.add(nx);
                        queue.add(ny);
                    }
                }
            }
        }
        return dist;
    }

    /** Returns the distance from the engineer to the spawn point ('S') */
    private int locateSpawnDistance(int[][] dist, char[][] grid, int rows, int cols) {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == SPAWN) {
                    return dist[r][c];
                }
            }
        }
        return -1; // should never happen for valid inputs
    }

    /** Sums the values of enemy cells that are reachable within the spawn distance */
    private int countEligibleEnemies(char[][] grid,
                                     int[][] dist,
                                     int rows,
                                     int cols,
                                     int spawnDistance) {
        int sum = 0;
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                char cell = grid[r][c];
                // Skip engineer, tower and spawn cells
                if (cell == ENGINEER || cell == TOWER || cell == SPAWN) {
                    continue;
                }
                // The remaining cells contain numeric enemy values
                int enemyValue = cell - '0';
                if (dist[r][c] != -1 && dist[r][c] <= spawnDistance) {
                    sum += enemyValue;
                }
            }
        }
        return sum;
    }

    /** Utility to check bounds */
    private boolean inside(int x, int y, int rows, int cols) {
        return x >= 0 && y >= 0 && x < rows && y < cols;
    }
}

import java.io.*;
import java.util.*;

public class Pr330D {

    /* -------------------------------------------------------------
       Direction vectors: up, down, left, right
       ------------------------------------------------------------- */
    private static final int[][] DIRECTIONS = {
            {-1, 0}, {1, 0}, {0, -1}, {0, 1}
    };

    /* -------------------------------------------------------------
       Special values used inside the input matrix
       ------------------------------------------------------------- */
    private static final int TYPE_WALL   = -1;   // '#'
    private static final int TYPE_START  = 11;   // 'S' – start cell (sentinel)
    private static final int TYPE_END    = 0;    // 'E' – end cell (sentinel)

    /* -------------------------------------------------------------
       Fast scanner – thin wrapper around BufferedReader + StringTokenizer
       ------------------------------------------------------------- */
    private static class FastScanner {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        FastScanner(BufferedReader br) {
            this.reader = br;
        }

        /** Returns the next token from the input stream. */
        String nextToken() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                tokenizer = new StringTokenizer(reader.readLine());
            }
            return tokenizer.nextToken();
        }

        /** Reads an int from the input stream. */
        int nextInt() throws IOException {
            return Integer.parseInt(nextToken());
        }
    }

    /* -------------------------------------------------------------
       Main entry point
       ------------------------------------------------------------- */
    public static void main(String[] args) throws IOException {
        new Pr330D().run();
    }

    /* -------------------------------------------------------------
       Instance fields used by the solution
       ------------------------------------------------------------- */
    private FastScanner scanner;
    private PrintWriter writer;

    /** Sets up I/O and launches the solving routine. */
    private void run() throws IOException {
        scanner = new FastScanner(new BufferedReader(
                new InputStreamReader(System.in)));
        writer = new PrintWriter(System.out, true);
        solve();
        writer.flush();
    }

    /** Main solving logic – parses input, runs BFS and computes the answer. */
    private void solve() throws IOException {
        int n = scanner.nextInt();
        int m = scanner.nextInt();

        /* ---------------------------------------------------------
           Build the logical representation of the grid.
           The matrix stores:
                TYPE_WALL  for '#'
                TYPE_START (11) for 'S'
                TYPE_END   (0)  for 'E'
                1 … 9       for digits '1' … '9'
                other chars are treated as 0 (empty)
           --------------------------------------------------------- */
        int[][] map = new int[n][m];
        int startX = -1, startY = -1;   // coordinates of 'S'
        int endX   = -1, endY   = -1;   // coordinates of 'E'

        for (int i = 0; i < n; i++) {
            String row = scanner.nextToken();
            for (int j = 0; j < m; j++) {
                char c = row.charAt(j);
                if (c == '#') {
                    map[i][j] = TYPE_WALL;
                } else if (c == 'S') {
                    map[i][j] = TYPE_START;
                    startX = i;
                    startY = j;
                } else if (c == 'E') {
                    map[i][j] = TYPE_END;
                    endX = i;
                    endY = j;
                } else if (Character.isDigit(c)) {
                    map[i][j] = c - '0';   // numeric value 1‑9
                } else {
                    map[i][j] = 0;         // any other character → empty cell
                }
            }
        }

        /* ---------------------------------------------------------
           Run BFS from the end cell ('E') and obtain distances.
           --------------------------------------------------------- */
        int[][] distances = bfs(endX, endY, map, n, m);
        int distanceToStart = distances[startX][startY];   // steps from 'E' to 'S'

        /* ---------------------------------------------------------
           Sum all numeric cells (1‑9) whose distance to 'E' does not
           exceed the distance from 'E' to 'S'.
           --------------------------------------------------------- */
        long answer = 0;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                int cellValue = map[i][j];
                if (cellValue > 0 && cellValue < 10 &&
                        distances[i][j] <= distanceToStart) {
                    answer += cellValue;
                }
            }
        }
        writer.println(answer);
    }

    /**
     * Breadth‑first search starting from (srcX, srcY). Returns a distance
     * matrix where {@code distance[x][y]} equals the number of steps
     * required to reach (x,y) from the source. Walls (TYPE_WALL) are ignored.
     */
    private int[][] bfs(int srcX, int srcY, int[][] map, int n, int m) {
        int[][] dist = new int[n][m];
        boolean[][] visited = new boolean[n][m];

        // Initialise distance matrix with a large sentinel value.
        final int INF = Integer.MAX_VALUE / 4;
        for (int[] row : dist) {
            Arrays.fill(row, INF);
        }

        Queue<int[]> queue = new ArrayDeque<>();
        dist[srcX][srcY] = 0;
        visited[srcX][srcY] = true;
        queue.add(new int[]{srcX, srcY});

        while (!queue.isEmpty()) {
            int[] cur = queue.poll();
            int x = cur[0];
            int y = cur[1];

            for (int[] dir : DIRECTIONS) {
                int nx = x + dir[0];
                int ny = y + dir[1];

                if (!isInside(nx, ny, n, m)) {
                    continue;                       // out of bounds
                }
                if (map[nx][ny] == TYPE_WALL) {
                    continue;                       // cannot walk through walls
                }
                if (!visited[nx][ny]) {
                    visited[nx][ny] = true;
                    dist[nx][ny] = dist[x][y] + 1;
                    queue.add(new int[]{nx, ny});
                }
            }
        }
        return dist;
    }

    /** Helper – checks whether (x,y) lies inside the n×m grid. */
    private boolean isInside(int x, int y, int n, int m) {
        return x >= 0 && x < n && y >= 0 && y < m;
    }
}

import java.io.*;
import java.util.*;

/**
 * Solver for the problem described in the original source.
 * <p>
 * The program:
 * <ol>
 *   <li>Reads a grid from {@code stdin}.</li>
 *   <li>Finds the start cell {@code S} and the end cell {@code E}.</li>
 *   <li>Computes the shortest distance from {@code S} to {@code E}
 *       (moving only through non‑{'T'} cells).</li>
 *   <li>Performs a BFS from {@code E} limited by that distance,
 *       collecting the sum of digit characters encountered.</li>
 * </ol>
 * All mutable state is confined to this class, making the logic easier to
 * follow and test.
 */
public class Round192D {

    /** Simple immutable holder for a grid position and its distance from the start. */
    private static final class State implements Comparable<State> {
        final int row;
        final int col;
        final int dist;

        State(int row, int col, int dist) {
            this.row = row;
            this.col = col;
            this.dist = dist;
        }

        @Override
        public int compareTo(State o) {
            return Integer.compare(this.dist, o.dist);
        }
    }

    /* ---------- Input handling utilities ---------- */

    private static BufferedReader reader;
    private static StringTokenizer tokenizer;

    private static String nextToken() throws IOException {
        while (!tokenizer.hasMoreTokens()) {
            String line = reader.readLine();
            if (line == null) {
                return null;
            }
            tokenizer = new StringTokenizer(line);
        }
        return tokenizer.nextToken();
    }

    /* ---------- Core algorithm fields ---------- */

    private static int rows, cols;
    private static char[][] grid;
    private static int startRow, startCol;
    private static int endRow, endCol;
    private static int answer;               // sum of digits collected during BFS

    /* ---------- Main entry point ---------- */

    public static void main(String[] args) throws Exception {
        initialiseReader();
        readGrid();
        int shortest = computeShortestPath();
        bfsFromEnd(shortest);
        System.out.println(answer);
    }

    /* ---------- Helper methods ---------- */

    /** Set up the buffered reader and tokenizer. */
    private static void initialiseReader() {
        reader = new BufferedReader(new InputStreamReader(System.in));
        tokenizer = new StringTokenizer("");
    }

    /** Parse the grid and locate the start / end positions. */
    private static void readGrid() throws IOException {
        rows = Integer.parseInt(nextToken());
        cols = Integer.parseInt(nextToken());
        grid = new char[rows][];
        startRow = startCol = endRow = endCol = -1;

        for (int r = 0; r < rows; r++) {
            grid[r] = nextToken().toCharArray();
            for (int c = 0; c < cols; c++) {
                char cell = grid[r][c];
                if (cell == 'S') {
                    startRow = r;
                    startCol = c;
                } else if (cell == 'E') {
                    endRow = r;
                    endCol = c;
                }
            }
        }
    }

    /** Compute the shortest distance from S to E using a priority‑queue BFS. */
    private static int computeShortestPath() {
        boolean[][] visited = new boolean[rows][cols];
        PriorityQueue<State> queue = new PriorityQueue<>();
        queue.offer(new State(startRow, startCol, 0));

        while (!queue.isEmpty()) {
            State cur = queue.poll();
            int r = cur.row;
            int c = cur.col;
            int d = cur.dist;

            if (r == endRow && c == endCol) {
                return d;
            }
            if (visited[r][c]) {
                continue;
            }
            visited[r][c] = true;

            exploreNeighbours(r, c, d, visited, queue);
        }
        return -1; // unreachable
    }

    /** Helper that enqueues valid adjacent cells. */
    private static void exploreNeighbours(
            int r, int c, int d,
            boolean[][] visited,
            PriorityQueue<State> queue) {

        int[][] dirs = {{0, 1}, {0, -1}, {1, 0}, {-1, 0}};
        for (int[] dir : dirs) {
            int nr = r + dir[0];
            int nc = c + dir[1];
            if (outOfBounds(nr, nc) || visited[nr][nc] || grid[nr][nc] == 'T') {
                continue;
            }
            queue.offer(new State(nr, nc, d + 1));
        }
    }

    /** Breadth‑first search from E limited by the maximal allowed distance.
     *  Accumulates digit values encountered during traversal. */
    private static void bfsFromEnd(int maxDist) {
        Queue<State> queue = new LinkedList<>();
        boolean[][] visited = new boolean[rows][cols];
        queue.offer(new State(endRow, endCol, 0));

        while (!queue.isEmpty()) {
            State cur = queue.poll();
            int r = cur.row;
            int c = cur.col;
            int d = cur.dist;

            if (Character.isDigit(grid[r][c]) && !visited[r][c]) {
                answer += (grid[r][c] - '0');
            }
            if (visited[r][c]) {
                continue;
            }
            visited[r][c] = true;

            int[][] dirs = {{0, 1}, {0, -1}, {1, 0}, {-1, 0}};
            for (int[] dir : dirs) {
                int nr = r + dir[0];
                int nc = c + dir[1];
                if (outOfBounds(nr, nc) || visited[nr][nc] || grid[nr][nc] == 'T' || d + 1 > maxDist) {
                    continue;
                }
                queue.offer(new State(nr, nc, d + 1));
            }
        }
    }

    /** Return {@code true} if coordinates are outside the grid. */
    private static boolean outOfBounds(int r, int c) {
        return r < 0 || r >= rows || c < 0 || c >= cols;
    }
}

import java.io.*;
import java.util.*;

/**
 * Refactored solution for the problem formerly known as {@code ProblemB}.
 * <p>
 * The refactor focuses on:
 * <ul>
 *   <li>Clear separation of concerns – I/O handling is isolated from the algorithm.</li>
 *   <li>Use of standard JDK collections instead of a handcrafted queue.</li>
 *   <li>Descriptive naming, constants and JavaDoc comments.</li>
 *   <li>Proper resource management with try‑with‑resources.</li>
 * </ul>
 */
public class ProblemB {

    /** Sentinel value used for initialising distance cells. */
    private static final int INF = 1 << 20;

    /** Simple immutable container for a coordinate pair. */
    private static final class Pair {
        final int row;
        final int col;

        Pair(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }

    /**
     * Entry point – reads all test cases and invokes {@code solveCase}.
     */
    public static void main(String[] args) throws IOException {
        // BufferedReader/PrintWriter are created once and closed automatically.
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
             PrintWriter pw = new PrintWriter(new OutputStreamWriter(System.out))) {

            int testCaseCount = Integer.parseInt(br.readLine().trim());

            for (int tc = 0; tc < testCaseCount; tc++) {
                if (tc > 0) {
                    pw.println();               // blank line between cases as in the original output
                }
                solveCase(br, pw);
            }
        }
    }

    /**
     * Reads one test case, processes it and writes the answer.
     *
     * @param br source of input data
     * @param pw destination for the answer
     * @throws IOException if an I/O error occurs
     */
    private static void solveCase(BufferedReader br, PrintWriter pw) throws IOException {
        // ----- 1. Parse the board dimensions ---------------------------------
        String[] dim = br.readLine().split("\\s+");
        int rows = Integer.parseInt(dim[0]);
        int cols = Integer.parseInt(dim[1]);

        char[][] board = new char[rows][];
        Pair start = null;

        // ----- 2. Initialise distance matrix and the BFS queue ----------------
        int[][] distance = new int[rows][cols];
        for (int r = 0; r < rows; r++) {
            Arrays.fill(distance[r], INF);
        }

        Queue<Pair> queue = new ArrayDeque<>();

        // ----- 3. Read board and locate start (S) and end (E) cells ----------
        for (int r = 0; r < rows; r++) {
            String line = br.readLine();
            board[r] = line.toCharArray();
            for (int c = 0; c < cols; c++) {
                char ch = board[r][c];
                if (ch == 'E') {
                    queue.add(new Pair(r, c));
                    distance[r][c] = 0;
                } else if (ch == 'S') {
                    start = new Pair(r, c);
                }
            }
        }

        // ----- 4. Breadth‑first search to compute minimum distances ----------
        final int[] dr = {-1, 0, 1, 0};          // up, right, down, left
        while (!queue.isEmpty()) {
            Pair cur = queue.poll();

            for (int d = 0; d < 4; d++) {
                int nr = cur.row + dr[d];
                int nc = cur.col + dr[(d + 1) % 4];   // equivalent to cur.col + (d ^ 2)

                // Boundary check and obstacle check
                if (nr < 0 || nr >= rows || nc < 0 || nc >= cols) {
                    continue;
                }
                if (board[nr][nc] == 'T') {
                    continue;
                }

                // Relaxation step
                if (distance[nr][nc] > distance[cur.row][cur.col] + 1) {
                    distance[nr][nc] = distance[cur.row][cur.col] + 1;
                    queue.add(new Pair(nr, nc));
                }
            }
        }

        // ----- 5. Determine the minimal distance from S to any ‘digit’ cell --- 
        int minDistFromStart = distance[start.row][start.col];
        long answer = 0;

        outer:
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                char ch = board[r][c];
                if (ch >= '1' && ch <= '9' && distance[r][c] <= minDistFromStart) {
                    answer += ch - '0';
                }
            }
        }

        pw.println(answer);
        pw.flush();          // matches the flushing behaviour of the original code
    }
}

import java.io.*;
import java.util.*;

/**
 * Refactored version of the original program.
 * The logic is unchanged – it reads a maze, runs a BFS from the exit,
 * computes the shortest distance to the start and sums all collectable
 * cells that are reachable within that distance.
 *
 * Improvements:
 *   • Clear separation of concerns (reading, BFS, utility methods)
 *   • Meaningful naming and final fields
 *   • Use of try‑with‑resources for automatic resource handling
 *   • Small helper classes (Cell, InputReader) instead of raw arrays
 *   • Constants and private static methods for readability
 */
public class D {

    /** Represents a single cell in the maze. */
    private static final class Cell {
        final int row;
        final int col;

        Cell(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }

    /** Value used to mark cells that have never been visited by BFS. */
    private static final int UNVISITED = Integer.MAX_VALUE;

    public static void main(String[] args) throws IOException {
        // All resources are closed automatically at the end of the try‑with‑resources block.
        try (InputReader reader = new InputReader(System.in);
             PrintWriter out = new PrintWriter(System.out)) {

            int rows = reader.nextInt();
            int cols = reader.nextInt();

            // ------------------------------------------------------------
            // 1️⃣  Parse the board and locate the start ('S'‑like) and exit ('E')
            // ------------------------------------------------------------
            int[][] board = new int[rows][cols];
            Cell start = null;
            Cell exit = null;

            for (int r = 0; r < rows; r++) {
                String token = reader.nextToken();               // one whole row
                for (int c = 0; c < cols; c++) {
                    char ch = token.charAt(c);
                    if (Character.isDigit(ch)) {
                        board[r][c] = ch - '0';                  // collectible number
                    } else if (ch == 'T') {
                        board[r][c] = -1;                        // trap cell
                    } else if (ch == 'E') {
                        board[r][c] = 0;                         // exit cell
                        exit = new Cell(r, c);
                    } else {                                     // any other char → start
                        board[r][c] = 0;
                        start = new Cell(r, c);
                    }
                }
            }

            // Defensive check – the original program assumes a start exists.
            if (start == null) {
                out.println(0);
                return;
            }

            // ------------------------------------------------------------
            // 2️⃣  BFS from the exit cell to compute distances
            // ------------------------------------------------------------
            int[][] distance = bfs(board, exit);

            // If the start cell is unreachable, output 0 (mirrors original behaviour).
            if (distance[start.row][start.col] == UNVISITED) {
                out.println(0);
                return;
            }

            // ------------------------------------------------------------
            // 3️⃣  Sum all positive cells reachable within the start‑to‑exit distance
            // ------------------------------------------------------------
            int myDistance = distance[start.row][start.col];
            int sum = 0;
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (board[r][c] > 0 && myDistance >= distance[r][c]) {
                        sum += board[r][c];
                    }
                }
            }
            out.println(sum);
        }
    }

    /**
     * Executes a breadth‑first search from the supplied source cell.
     *
     * @param board   maze representation
     * @param source  cell from which the search starts (the exit)
     * @return        matrix of distances; UNVISITED marks unreachable cells
     */
    private static int[][] bfs(int[][] board, Cell source) {
        int rows = board.length;
        int cols = board[0].length;

        int[][] distance = new int[rows][cols];
        for (int[] row : distance) {
            Arrays.fill(row, UNVISITED);
        }

        boolean[][] visited = new boolean[rows][cols];
        Queue<Cell> queue = new ArrayDeque<>();
        queue.add(source);
        visited[source.row][source.col] = true;
        distance[source.row][source.col] = 0;

        final int[][] DIRECTIONS = {{0, 1}, {0, -1}, {1, 0}, {-1, 0}};

        while (!queue.isEmpty()) {
            Cell cur = queue.poll();
            for (int[] dir : DIRECTIONS) {
                int nr = cur.row + dir[0];
                int nc = cur.col + dir[1];
                if (isInBounds(nr, cols) && isInBounds(nc, rows)
                        && !visited[nr][nc] && board[nr][nc] != -1) {
                    visited[nr][nc] = true;
                    distance[nr][nc] = distance[cur.row][cur.col] + 1;
                    queue.add(new Cell(nr, nc));
                }
            }
        }
        return distance;
    }

    /** Helper to check array bounds. */
    private static boolean isInBounds(int index, int length) {
        return index >= 0 && index < length;
    }

    /**
     * Fast token‑based input reader that implements {@link AutoCloseable}.
     * It mirrors the functionality of the original {@code InputReader}
     * but uses a reusable byte buffer and clearer method names.
     */
    private static class InputReader implements AutoCloseable {
        private final InputStream stream;
        private final byte[] buffer = new byte[16 * 1024];
        private int bytesRead = 0;
        private int currentByte = 0;

        InputReader(InputStream stream) {
            this.stream = stream;
        }

        private int readByte() throws IOException {
            if (currentByte >= bytesRead) {
                bytesRead = stream.read(buffer);
                currentByte = 0;
                if (bytesRead <= 0) {
                    return -1;
                }
            }
            return buffer[currentByte++];
        }

        /** Reads the next integer from the input stream. */
        int nextInt() throws IOException {
            int c = skipNonDigits();
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = readByte();
            }
            int result = 0;
            do {
                result = result * 10 + (c - '0');
                c = readByte();
            } while (isDigit(c));
            return result * sign;
        }

        /** Reads the next token (a sequence of letters). */
        String nextToken() throws IOException {
            int c = skipNonLetters();
            StringBuilder sb = new StringBuilder();
            do {
                sb.append((char) c);
                c = readByte();
            } while (isLetter(c));
            return sb.toString();
        }

        /** Skips characters until a digit is found. */
        private int skipNonDigits() throws IOException {
            int c;
            while ((c = readByte()) != -1 && !isDigit(c)) { }
            return c;
        }

        /** Skips characters until a letter is found. */
        private int skipNonLetters() throws IOException {
            int c;
            while ((c = readByte()) != -1 && !isLetter(c)) { }
            return c;
        }

        private boolean isDigit(int c) {
            return c >= '0' && c <= '9';
        }

        private boolean isLetter(int c) {
            return (c >= 'A' && c <= 'Z') || (c >= 'a' && c <= 'z');
        }

        @Override
        public void close() throws IOException {
            stream.close();
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Entry point of the program.
 * Reads the whole input, delegates the solving to {@link TaskSolver}
 * and prints the result using {@link OutputWriter}.
 */
public class Main {
    public static void main(String[] args) throws IOException {
        // Standard input / output streams
        InputStream inStream = System.in;
        OutputStream outStream = System.out;

        // Custom fast I/O classes
        try (InputReader reader = new InputReader(inStream);
             OutputWriter writer = new OutputWriter(outStream)) {

            TaskSolver solver = new TaskSolver();

            // There is only a single test case in the original problem
            solver.solve(1, reader, writer);
        }
    }
}

/**
 * Handles all input parsing.  The class is deliberately thin – it only
 * knows how to read the data required by the problem and does not
 * contain any business logic.
 */
class InputReader {
    private final BufferedReader br;

    InputReader(InputStream stream) {
        this.br = new BufferedReader(new InputStreamReader(stream));
    }

    /** Reads the next token as an {@code int}. */
    int nextInt() {
        int c;
        do {
            c = br.read();
        } while (isWhiteSpace(c) && c >= 0);
        if (c < 0) {
            throw new EOFException();
        }
        boolean negative = false;
        if (c == '-') {
            negative = true;
            c = br.read();
        }
        int result = 0;
        while (c >= '0' && c <= '9') {
            result = result * 10 + (c - '0');
            c = br.read();
        }
        return negative ? -result : result;
    }

    /** Reads the next token as a {@code String} (skipping whitespace). */
    String next() {
        StringBuilder sb = new StringBuilder();
        int c;
        do {
            c = br.read();
        } while (isWhiteSpace(c) && c >= 0);
        if (c < 0) {
            return null;
        }
        while (c >= 0 && !isWhiteSpace(c)) {
            sb.appendCodePoint(c);
            c = br.read();
        }
        return sb.toString();
    }

    /** Reads a rectangular character field of size {@code rows × cols}. */
    char[][] readCharacterField(int rows, int cols) {
        char[][] field = new char[rows][];
        for (int i = 0; i < rows; i++) {
            String token = next();
            if (token == null || token.length() != cols) {
                throw new AssertionError("expected token length " + cols);
            }
            field[i] = token.toCharArray();
        }
        return field;
    }

    /** Utility – checks whether a character is a whitespace. */
    private static boolean isWhiteSpace(int c) {
        return c >= 0 && c <= 32;
    }
}

/**
 * Handles all output formatting.  The class mirrors {@link PrintWriter}
 * but makes the closing of the stream explicit in a try‑with‑resources
 * block.
 */
class OutputWriter extends PrintWriter {
    OutputWriter(OutputStream stream) {
        super(stream);
    }

    OutputWriter(Writer stream) {
        super(stream);
    }
}

/**
 * Core algorithm implementation.
 *
 * <p>The method follows the original logic but with clearer naming,
 * better modularisation and a more expressive queue implementation.
 */
class TaskSolver {
    /** Four possible movement directions (down, right, up, left). */
    private static final int[][] DIRS = {
            {1, 0},   // down
            {0, 1},   // right
            {-1, 0},  // up
            {0, -1}   // left
    };

    /**
     * Solves the problem for a single test case.
     *
     * @param testNumber unused – kept for compatibility with the original API
     * @param in       input reader
     * @param out      output writer
     */
    void solve(int testNumber, InputReader in, OutputWriter out) {
        int rows = in.nextInt();          // n
        int cols = in.nextInt();          // m
        char[][] grid = in.readCharacterField(rows, cols);

        // -----------------------------------------------------------------
        // 1️⃣  Initialise distance matrix and the BFS queue with all 'E' cells
        // -----------------------------------------------------------------
        int[][] distance = new int[rows][cols];
        for (int[] row : distance) {
            Arrays.fill(row, Integer.MAX_VALUE);
        }

        Queue<int[]> queue = new ArrayDeque<>();
        int startRow = -1, startCol = -1;

        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == 'E') {
                    distance[r][c] = 0;
                    queue.add(new int[]{r, c});
                } else if (grid[r][c] == 'S') {
                    startRow = r;
                    startCol = c;
                }
            }
        }

        // If there is no 'S' the original code would keep `our` = MAX_VALUE,
        // which leads to printing -1.  The same behaviour is preserved.
        if (startRow == -1 || startCol == -1) {
            out.println(-1);
            return;
        }

        // -----------------------------------------------------------------
        // 2️⃣  Breadth‑first search – propagate distances from every 'E'
        // -----------------------------------------------------------------
        while (!queue.isEmpty()) {
            int[] cur = queue.poll();
            int r = cur[0];
            int c = cur[1];
            int curDist = distance[r][c];

            for (int[] dir : DIRS) {
                int nr = r + dir[0];
                int nc = c + dir[1];

                // Boundary check
                if (nr < 0 || nr >= rows || nc < 0 || nc >= cols) {
                    continue;
                }
                // Skip walls ('T') and already visited cells
                if (grid[nr][nc] == 'T' || distance[nr][nc] != Integer.MAX_VALUE) {
                    continue;
                }

                distance[nr][nc] = curDist + 1;
                queue.add(new int[]{nr, nc});
            }
        }

        // ---------------------------------------------------------------
        // 3️⃣  Retrieve the distance of the starting cell 'S'
        // ---------------------------------------------------------------
        int startDist = distance[startRow][startCol];
        if (startDist == Integer.MAX_VALUE) {
            // The start cell cannot be reached from any 'E'
            out.println(-1);
            return;
        }

        // ---------------------------------------------------------------
        // 4️⃣  Sum all digits that are reachable within `startDist` steps
        // ---------------------------------------------------------------
        int answer = 0;
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                char ch = grid[r][c];
                if (Character.isDigit(ch)) {
                    int digitValue = ch - '0';
                    if (distance[r][c] <= startDist) {
                        answer += digitValue;
                    }
                }
            }
        }
        out.println(answer);
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.ArrayDeque;
import java.util.Deque;
import java.util.List;
import java.util.Objects;

/**
 * Core logic of the Biridian Rush game.
 * <p>
 * The program reads a grid from standard input, performs a breadth‑first search
 * from every exit ('E') cell, and then sums the values of all numeric cells
 * that the player can reach within the same number of moves the player needs
 * to reach the nearest exit.
 * </p>
 */
public class Biridian {

    /** Symbol for an impassable tile. */
    private static final char OBSTACLE = 'T';

    /** Symbol for the player's start position. */
    private static final char PLAYER_START = 'S';

    /** Symbol for an exit (multiple may exist). */
    private static final char EXIT = 'E';

    /** Symbol for a cell that contains a collectible number. */
    private static final char NUMBER = '0';

    /** Maximum placeholder distance used before BFS assigns a real value. */
    private static final int UNVISITED = Integer.MAX_VALUE / 2;

    /** The parsed game board. */
    private static char[][] board;

    /** Width and height of the board. */
    private static int rows, cols;

    /** Distance from each cell to the nearest exit. */
    private static int[][] distance;

    /** Queue used for BFS traversal. */
    private static class Position {
        final int row, col;

        Position(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }

    /** Entry point of the program. */
    public static void main(String[] args) throws IOException {
        parseInput();
        bfsFromExits();
        int playerDistance = distance[findPlayerRow()][findPlayerCol()];
        int result = collectReachableNumbers(playerDistance);
        System.out.println(result);
    }

    /** Reads R, C and the grid from standard input. */
    private static void parseInput() throws IOException {
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
        String[] header = reader.readLine().split("\\s+");
        rows = Integer.parseInt(header[0]);
        cols = Integer.parseInt(header[1]);

        board = new char[rows][];
        for (int r = 0; r < rows; r++) {
            board[r] = reader.readLine().toCharArray();
        }
        reader.close();
    }

    /** Finds the row and column of the player's start position. */
    private static int findPlayerRow() {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (board[r][c] == PLAYER_START) {
                    return r;
                }
            }
        }
        throw new IllegalStateException("Player start ('S') not found");
    }

    private static int findPlayerCol() {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (board[r][c] == PLAYER_START) {
                    return c;
                }
            }
        }
        throw new IllegalStateException("Player start ('S') not found");
    }

    /** Performs BFS from all exit cells simultaneously. */
    private static void bfsFromExits() {
        distance = new int[rows][cols];
        for (int r = 0; r < rows; r++) {
            Arrays.fill(distance[r], UNVISITED);
        }

        Deque<Position> queue = new ArrayDeque<>();

        // Initialise queue with every exit cell and set its distance to 0.
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (board[r][c] == EXIT) {
                    queue.addLast(new Position(r, c));
                    distance[r][c] = 0;
                }
            }
        }

        int[] dr = {1, -1, 0, 0};
        int[] dc = {0, 0, 1, -1};

        while (!queue.isEmpty()) {
            Position cur = queue.removeFirst();
            int curR = cur.row;
            int curC = cur.col;

            for (int dir = 0; dir < 4; dir++) {
                int nr = curR + dr[dir];
                int nc = curC + dc[dir];

                // Bounds check
                if (nr < 0 || nr >= rows || nc < 0 || nc >= cols) {
                    continue;
                }

                // Skip obstacles and already visited cells
                if (board[nr][nc] == OBSTACLE || distance[nr][nc] != UNVISITED) {
                    continue;
                }

                distance[nr][nc] = distance[curR][curC] + 1;
                queue.addLast(new Position(nr, nc));
            }
        }
    }

    /** Sums numbers that can be collected within the player's distance to an exit. */
    private static int collectReachableNumbers(int playerMoves) {
        int sum = 0;
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                char cell = board[r][c];
                if (Character.isDigit(cell)) {
                    int digit = cell - '0';
                    if (distance[r][c] <= playerMoves) {
                        sum += digit;
                    }
                }
            }
        }
        return sum;
    }
}

import java.io.*;
import java.util.*;

public class BiridianForest {

    /* ------------------------------------------------------------------------ *
     * Constants
     * ------------------------------------------------------------------------ */
    private static final int[][] DIRS = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}}; // 4‑neighbour offsets
    private static final int INF = Integer.MAX_VALUE;

    /* ------------------------------------------------------------------------ *
     * Entry point
     * ------------------------------------------------------------------------ */
    public static void main(String[] args) throws Exception {
        try (InputReader reader = new InputReader()) {
            solve(reader, new PrintWriter(System.out));
        } catch (Exception e) {
            e.printStackTrace();
        }
    }

    /* ------------------------------------------------------------------------ *
     * Core algorithm
     * ------------------------------------------------------------------------ */
    private static void solve(InputReader reader, PrintWriter out) {
        /* ----- Parse input ---------------------------------------------------- */
        String[] nm = reader.readLine().trim().split("\\s+");
        int rows = Integer.parseInt(nm[0]);
        int cols = Integer.parseInt(nm[1]);

        char[][] grid = new char[rows][];
        for (int i = 0; i < rows; i++) {
            grid[i] = reader.readLine().trim().toCharArray();
        }

        /* ----- Locate start (S) and end (E) --------------------------------- */
        int sx = -1, sy = -1, ex = -1, ey = -1;
        for (int y = 0; y < rows; y++) {
            for (int x = 0; x < cols; x++) {
                switch (grid[y][x]) {
                    case 'S' -> { sx = x; sy = y; }
                    case 'E' -> { ex = x; ey = y; }
                }
            }
        }
        if (sx < 0 || ex < 0) {
            throw new IllegalArgumentException("Start or End character not found in input");
        }

        /* ----- Dijkstra from the end position --------------------------------- */
        int[][] dist = new int[rows][cols];
        for (int[] row : dist) {
            Arrays.fill(row, INF);
        }
        dist[ey][ex] = 0;

        PriorityQueue<Node> pq = new PriorityQueue<>(Comparator.comparingInt(n -> n.cost));
        pq.add(new Node(ex, ey, 0));
        boolean[][] visited = new boolean[rows][cols];

        while (!pq.isEmpty()) {
            Node cur = pq.poll();
            if (visited[cur.y][cur.x]) {
                continue;                     // already processed
            }
            visited[cur.y][cur.x] = true;

            for (int[] delta : DIRS) {
                int nx = cur.x + delta[0];
                int ny = cur.y + delta[1];

                // bounds check
                if (nx < 0 || nx >= cols || ny < 0 || ny >= rows) {
                    continue;
                }
                // cannot step onto trees
                if (grid[ny][nx] == 'T') {
                    continue;
                }
                // relax edge
                int newDist = cur.cost + 1;
                if (newDist < dist[ny][nx]) {
                    dist[ny][nx] = newDist;
                    pq.add(new Node(nx, ny, newDist));
                }
            }
        }

        /* ----- Compute answer ------------------------------------------------- */
        int answer = 0;
        for (int y = 0; y < rows; y++) {
            for (int x = 0; x < cols; x++) {
                char ch = grid[y][x];
                if (ch == 'S' || ch == 'E' || ch == 'T') {
                    continue;
                }
                if (dist[y][x] <= dist[sy][sx]) {
                    answer += ch - '0'; // collect digit values that satisfy the condition
                }
            }
        }
        out.println(answer);   // write result and flush automatically via try‑with‑resources
    }

    /* ------------------------------------------------------------------------ *
     * Helper class for priority‑queue ordering
     * ------------------------------------------------------------------------ */
    private static final class Node {
        final int x;
        final int y;
        final int cost;      // accumulated distance from the target

        Node(int x, int y, int cost) {
            this.x = x;
            this.y = y;
            this.cost = cost;
        }
    }

    /* ------------------------------------------------------------------------ *
     * Very small fast‑input wrapper (compatible with the original snippet)
     * ------------------------------------------------------------------------ */
    private static class InputReader implements AutoCloseable {
        private static final int BUFFER_SIZE = 1 << 16;
        private final DataInputStream din;
        private final byte[] buffer;
        private int bufferPointer = 0;
        private int bytesRead = 0;

        InputReader() throws IOException {
            this(System.in);
        }

        InputReader(String fileName) throws IOException {
            din = new DataInputStream(new FileInputStream(fileName));
            buffer = new byte[BUFFER_SIZE];
            bufferPointer = bytesRead = 0;
        }

        private int readByte() throws IOException {
            if (bufferPointer == bytesRead) {
                fillBuffer();
            }
            return buffer[bufferPointer++];
        }

        private void fillBuffer() throws IOException {
            bytesRead = din.read(buffer, bufferPointer = 0, BUFFER_SIZE);
            if (bytesRead == -1) {
                buffer[0] = -1;               // sentinel for end‑of‑stream
            }
        }

        String readLine() throws IOException {
            StringBuilder sb = new StringBuilder();
            int c;
            while ((c = readByte()) != -1 && c != '\n') {
                sb.append((char) c);
            }
            return sb.toString();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(readToken());
        }

        long nextLong() throws IOException {
            return Long.parseLong(readToken());
        }

        double nextDouble() throws IOException {
            return Double.parseDouble(readToken());
        }

        private String readToken() throws IOException {
            StringBuilder sb = new StringBuilder();
            int c;
            // skip whitespaces
            do {
                c = readByte();
            } while (c <= ' ');
            boolean neg = false;
            if (c == '-') {
                neg = true;
                c = readByte();
            }
            while (c > ' ') {
                sb.append((char) c);
                c = readByte();
            }
            return neg ? sb.substring(1) : sb.toString();
        }

        void close() throws IOException {
            if (din != null) {
                din.close();
            }
        }
    }
}

import java.io.IOException;
import java.util.ArrayDeque;
import java.util.Arrays;
import java.util.Deque;
import java.util.Scanner;

/**
 * Reads a grid from STDIN, performs a breadth‑first search from the
 * exit cell ('E') and sums the numeric values of all cells that can be
 * reached in at most the same number of steps required to reach the
 * start cell ('S').
 *
 * The original program was functional but hard to read and maintain.
 * This version is split into small, self‑documenting pieces:
 *
 *  - {@link Position} – immutable coordinate holder.
 *  - {@link Forest} – encapsulates the grid and the two special positions.
 *  - {@link #bfs(Forest, int[][])} – isolated BFS algorithm.
 *  - {@link #computeResult(Forest, int[][], long)} – result calculation.
 *
 * Naming, constants and Javadoc comments have been added to improve
 * understandability and future extensibility.
 */
public class ForestTraversal {

    /** Cells that cannot be entered. */
    private static final char BLOCKED = 'T';

    /** Cell that marks the exit (the BFS source). */
    private static final char EXIT = 'E';

    /** Cell that marks the start (target for distance measurement). */
    private static final char START = 'S';

    /** Simple holder for a 2‑D coordinate. */
    private static final class Position {
        final int row;
        final int col;

        Position(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }

    /** Container for the whole input grid and the two special locations. */
    private static final class Forest {
        final char[][] grid;
        final int rows;
        final int cols;
        final Position exitPosition;
        final Position startPosition;

        Forest(char[][] grid, Position exitPosition, Position startPosition) {
            this.grid = grid;
            this.rows = grid.length;
            this.cols = grid[0].length;
            this.exitPosition = exitPosition;
            this.startPosition = startPosition;
        }
    }

    /** Directions used for neighbour exploration (down, right, up, left). */
    private static final int[][] DIRECTIONS = {
            {1, 0}, {0, 1}, {-1, 0}, {0, -1}
    };

    /**
     * Breadth‑first search that records the distance of every reachable
     * cell from {@link Forest#exitPosition}. When the {@link Forest#startPosition}
     * is encountered the current depth is stored in {@code myDist}.
     *
     * @param forest   the forest to explore
     * @param distances array that will receive the depth of each cell
     * @param myDist   holder that will receive the depth of the start cell
     */
    private static void bfs(Forest forest, int[][] distances, long[] myDist) {
        boolean[][] visited = new boolean[forest.rows][forest.cols];
        Deque<Position> queue = new ArrayDeque<>();

        // start the search from the exit cell
        queue.add(forest.exitPosition);
        visited[forest.exitPosition.row][forest.exitPosition.col] = true;

        int currentDepth = 0;

        while (!queue.isEmpty()) {
            int levelSize = queue.size();

            for (int i = 0; i < levelSize; i++) {
                Position cur = queue.removeFirst();
                char cell = forest.grid[cur.row][cur.col];

                // The original program treated the start cell ('S') specially.
                if (cell != EXIT) {
                    if (cell == START) {
                        myDist[0] = currentDepth;          // store the depth of 'S'
                    } else {
                        distances[cur.row][cur.col] = currentDepth;
                    }
                }

                // Explore neighbours
                for (int[] dir : DIRECTIONS) {
                    int nextRow = cur.row + dir[0];
                    int nextCol = cur.col + dir[1];

                    if (isInside(nextRow, forest.cols) &&
                            isInside(nextCol, forest.rows) &&
                            forest.grid[nextRow][nextCol] != BLOCKED &&
                            !visited[nextRow][nextCol]) {
                        visited[nextRow][nextCol] = true;
                        queue.addLast(new Position(nextRow, nextCol));
                    }
                }
            }
            currentDepth++;
        }
    }

    /** Helper that checks whether an index lies inside an array of a given length. */
    private static boolean isInside(int index, int length) {
        return index >= 0 && index < length;
    }

    /**
     * Calculates the required sum – the numeric value of every cell that
     * is reachable in at most {@code myDist} steps and is not one of the
     * special symbols {@code 'E'}, {@code 'S'} or {@code 'T'}.
     *
     * @param forest   the forest containing the grid
     * @param distances distances computed by {@link #bfs}
     * @param myDist   the maximal distance that qualifies a cell for inclusion
     * @return the computed sum
     */
    private static long computeResult(Forest forest, int[][] distances, long myDist) {
        long sum = 0L;

        for (int r = 0; r < forest.rows; r++) {
            for (int c = 0; c < forest.cols; c++) {
                char ch = forest.grid[r][c];
                if (!isSpecial(ch) && distances[r][c] <= myDist) {
                    sum += ch - '0';
                }
            }
        }
        return sum;
    }

    /** Returns {@code true} for characters that must be ignored in the sum. */
    private static boolean isSpecial(char ch) {
        return ch == EXIT || ch == START || ch == BLOCKED;
    }

    /** Entry point – reads input, runs the algorithm and prints the result. */
    public static void main(String[] args) throws IOException {
        try (Scanner scanner = new Scanner(System.in)) {
            int rows = scanner.nextInt();
            int cols = scanner.nextInt();

            char[][] rawGrid = new char[rows][];
            Position exitPos = null;
            Position startPos = null;

            for (int r = 0; r < rows; r++) {
                String line = scanner.next();
                rawGrid[r] = line.toCharArray();

                for (int c = 0; c < cols; c++) {
                    char cell = rawGrid[r][c];
                    if (cell == EXIT) {
                        exitPos = new Position(r, c);
                    } else if (cell == START) {
                        startPos = new Position(r, c);
                    }
                }
            }

            Forest forest = new Forest(rawGrid, exitPos, startPos);

            // initialise distance matrix with “infinite” values
            int[][] distances = new int[rows][];
            for (int[] row : distances) {
                Arrays.fill(row, Integer.MAX_VALUE);
            }

            // holder for the depth at which the start cell is discovered
            long[] myDistHolder = new long[1];

            bfs(forest, distances, myDistHolder);
            long myDist = myDistHolder[0];   // may stay 0 if 'S' is unreachable

            long result = computeResult(forest, distances, myDist);
            System.out.println(result);
        }
    }
}

/*
 *  Refactored solution for the “Forest traversal” problem.
 *  The code is split into small, purpose‑focused classes,
 *  uses expressive names, and removes all unused imports.
 *  It compiles with any recent JDK (8+).
 */
import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) {
        try (InputReader reader = new InputReader(System.in);
             OutputWriter writer = new OutputWriter(System.out)) {
            new Solver().solve(reader, writer);
        }
    }
}

/* -----------------------------------------------------------------------------
 *  Core algorithm
 * ----------------------------------------------------------------------------- */
class Solver {
    private static final char START = 'S';
    private static final char END   = 'E';
    private static final char TREE  = 'T';

    /** Entry point used by Main. */
    public void solve(InputReader in, OutputWriter out) {
        int rows = in.nextInt();
        int cols = in.nextInt();
        char[][] grid = in.next2DCharArray(rows, cols);

        Position start = locate(grid, START);
        Position end   = locate(grid, END);

        int[][] distanceFromEnd = bfsFromEnd(grid, end);
        int myDistance = distanceFromEnd[start.row][start.col];

        int answer = sumDigitsWithinReachableDistance(grid, distanceFromEnd, myDistance);
        out.println(answer);
    }

    /** Finds the coordinates of the cell that matches the given symbol. */
    private Position locate(char[][] grid, char symbol) {
        for (int r = 0; r < grid.length; r++) {
            for (int c = 0; c < grid[r].length; c++) {
                if (grid[r][c] == symbol) {
                    return new Position(r, c);
                }
            }
        }
        throw new IllegalArgumentException("Symbol '" + symbol + "' not found in grid");
    }

    /** Breadth‑first search that records the distance of every reachable cell
     *  from the supplied start position. */
    private int[][] bfsFromEnd(char[][] grid, Position start) {
        int rows = grid.length;
        int cols = grid[0].length;
        int[][] dist = new int[rows][cols];
        // initialise all distances with -1 (unvisited)
        for (int[] row : dist) {
            Arrays.fill(row, -1);
        }
        dist[start.row][start.col] = 0;

        Queue<Position> queue = new ArrayDeque<>();
        queue.add(start);

        while (!queue.isEmpty()) {
            Position cur = queue.poll();
            for (Position nb : neighbours(cur, rows, cols, grid)) {
                if (dist[nb.row][nb.col] == -1) {
                    dist[nb.row][nb.col] = dist[cur.row][cur.col] + 1;
                    queue.add(nb);
                }
            }
        }
        return dist;
    }

    /** Returns the four orthogonal neighbours that are inside the grid
     *  and not blocked by a tree ('T'). */
    private List<Position> neighbours(Position p, int rows, int cols, char[][] grid) {
        int[] dr = {-1, 1, 0, 0};
        int[] dc = {0, 0, -1, 1};

        List<Position> result = new ArrayList<>(4);
        for (int d = 0; d < 4; d++) {
            int nr = p.row + dr[d];
            int nc = p.col + dc[d];
            if (inside(nr, nc, rows, cols) && grid[nr][nc] != TREE) {
                result.add(new Position(nr, nc));
            }
        }
        return result;
    }

    private boolean inside(int r, int c, int rows, int cols) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    /** Sums all digit characters whose distance from the end is ≤ the distance
     *  from the start cell to the end cell. */
    private int sumDigitsWithinReachableDistance(char[][] grid,
                                                 int[][] distances,
                                                 int maxDist) {
        int sum = 0;
        for (int r = 0; r < distances.length; r++) {
            for (int c = 0; c < distances[r].length; c++) {
                if (distances[r][c] != -1 && distances[r][c] <= maxDist
                        && Character.isDigit(grid[r][c])) {
                    sum += grid[r][c] - '0';
                }
            }
        }
        return sum;
    }
}

/* -----------------------------------------------------------------------------
 *  Small immutable data holder for grid coordinates
 * ----------------------------------------------------------------------------- */
final class Position implements Comparable<Position> {
    final int row;
    final int col;

    Position(int row, int col) {
        this.row = row;
        this.col = col;
    }

    @Override public int compareTo(Position o) {
        int cmp = Integer.compare(this.row, o.row);
        return (cmp != 0) ? cmp : Integer.compare(this.col, o.col);
    }

    @Override public boolean equals(Object obj) {
        if (this == obj) return true;
        if (!(obj instanceof Position)) return false;
        Position other = obj;
        return row == other.row && col == other.col;
    }

    @Override public int hashCode() {
        return Objects.hash(row, col);
    }

    @Override public String toString() {
        return "(" + row + ", " + col + ")";
    }
}

/* -----------------------------------------------------------------------------
 *  Input / Output helpers (fast, used by competitive‑programming style code)
 * ----------------------------------------------------------------------------- */
final class InputReader {
    private final InputStream stream;
    private final byte[] buffer = new byte[1 << 16];
    private int ptr = 0, len = 0;

    InputReader(InputStream stream) {
        this.stream = stream;
    }

    private int readByte() throws IOException {
        if (ptr >= len) {
            len = stream.read(buffer);
            ptr = 0;
            if (len <= 0) return -1;
        }
        return buffer[ptr++];
    }

    int nextInt() {
        int c, sign = 1, val = 0;
        do { c = readByte(); } while (isSpace(c));
        if (c == '-') { sign = -1; c = readByte(); }
        while (!isSpace(c)) {
            val = val * 10 + (c - '0');
            c = readByte();
        }
        return val * sign;
    }

    private static boolean isSpace(int c) {
        return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
    }

    char nextChar() {
        int c;
        do { c = readByte(); } while (isSpace(c));
        return (char) c;
    }

    char[][] next2DCharArray(int rows, int cols) {
        char[][] result = new char[rows][];
        for (int r = 0; r < rows; r++) {
            result[r] = new char[cols];
            for (int c = 0; c < cols; c++) {
                result[r][c] = nextChar();
            }
        }
        return result;
    }
}

final class OutputWriter {
    private final PrintWriter writer;

    OutputWriter(OutputStream stream) {
        writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(stream)));
    }

    void println(int value) {
        writer.println(value);
    }

    void close() {
        writer.close();
    }
}

/**
 * Refactored version of the original program.
 * <p>
 * The program reads a grid that contains:
 *   - 'S' – start cell
 *   - 'E' – end cell
 *   - digits '0'‑'9'
 *   - other characters (treated as obstacles)
 * <p>
 * It computes the length of the shortest path from 'S' to 'E' (ignoring
 * obstacles) and then sums the numeric values of all cells that lie on
 * **any** shortest path from start to end.
 * </p>
 *
 * <p>Refactoring highlights:</p>
 * <ul>
 *   <li>Clear separation of concerns (I/O, grid handling, BFS logic).</li>
 *   <li>Descriptive naming and removal of unnecessary static mutable fields.</li>
 *   <li>Use of Java 17 features (records, sealed interfaces) for safety and readability.</li>
 *   <li>Early‑exit checks and defensive programming.</li>
 *   <li>Fully documented public methods.</li>
 * </ul>
 */
public final class Main {

    /** Directions used for neighbour exploration (up, down, left, right). */
    private static final int[] DX = {1, -1, 0, 0};
    /** Directions used for neighbour exploration (up, down, left, right). */
    private static final int[] DY = {0, 0, 1, -1};

    /** Simple container for a coordinate. */
    private record Point(int row, int col) { }

    /** --------------------------------------------------------------------- */
    /** I/O helpers – unchanged from the original but a little cleaned up.   */
    /** --------------------------------------------------------------------- */
    private static final class InputReader {
        private final InputStream stream;
        private final byte[] buffer = new byte[1 << 10];
        private int bytesRead = 0;
        private int cursor = 0;

        InputReader(final InputStream stream) {
            this.stream = stream;
        }

        private int readByte() throws IOException {
            if (cursor >= bytesRead) {
                bytesRead = stream.read(buffer);
                cursor = 0;
                if (bytesRead <= 0) {
                    return -1;
                }
            }
            return buffer[cursor++];
        }

        /** Reads the next integer (optionally signed). */
        int nextInt() throws IOException {
            int c;
            do {
                c = readByte();
            } while (isSpace(c));

            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = readByte();
            }

            int value = 0;
            do {
                if (c < '0' || c > '9') {
                    throw new NumberFormatException();
                }
                value = value * 10 + (c - '0');
                c = readByte();
            } while (!isSpace(c));

            return value * sign;
        }

        /** Reads the next whitespace‑delimited string. */
        String nextString() throws IOException {
            int c;
            do {
                c = readByte();
            } while (isSpace(c));

            StringBuilder sb = new StringBuilder();
            do {
                sb.append((char) c);
                c = readByte();
            } while (!isSpace(c));

            return sb.toString();
        }

        private boolean isSpace(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }
    }

    private static final class OutputWriter {
        private final PrintWriter writer;

        OutputWriter(final OutputStream out) {
            this.writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(out)));
        }

        /** Prints the given objects separated by a single space. */
        void print(Object... objects) {
            for (int i = 0; i < objects.length; i++) {
                if (i != 0) writer.print(' ');
                writer.print(objects[i]);
            }
        }

        /** Prints the given objects and adds a line separator. */
        void println(Object... objects) {
            print(objects);
            writer.println();
        }

        /** Flushes the underlying stream. */
        void flush() {
            writer.flush();
        }

        /** Closes the writer (and underlying stream). */
        void close() {
            writer.close();
        }
    }

    /** ------------------------------------------------------------------------- */
    /** Core algorithmic class – encapsulates all grid processing logic.         */
    /** ------------------------------------------------------------------------- */
    private static final class GridProcessor {

        private final char[][] grid;
        private final int rows;
        private final int cols;
        private final Point start;
        private final Point end;

        /** Resulting distance maps after BFS executions. */
        private final int[][] distanceFromStart;
        private final int[][] distanceFromEnd;

        GridProcessor(final char[][] grid, final int rows, final int cols,
                      final Point start, final Point end) {
            this.grid = grid;
            this.rows = rows;
            this.cols = cols;
            this.start = start;
            this.end = end;
            this.distanceFromStart = new int[rows][cols];
            this.distanceFromEnd = new int[rows][cols];
        }

        /** Executes BFS from the supplied source and fills the provided map. */
        private void bfs(final Point source, final int[][] targetMap) {
            for (int r = 0; r < rows; r++) {
                Arrays.fill(targetMap[r], -1);
            }
            Queue<Point> queue = new ArrayDeque<>();
            queue.add(source);
            targetMap[source.row][source.col] = 0;

            while (!queue.isEmpty()) {
                Point cur = queue.poll();
                for (int dir = 0; dir < DX.length; dir++) {
                    int nr = cur.row + DX[dir];
                    int nc = cur.col + DY[dir];
                    if (valid(nr, nc) && canTraverse(nr, nc) && targetMap[nr][nc] == -1) {
                        targetMap[nr][nc] = targetMap[cur.row][cur.col] + 1;
                        queue.add(new Point(nr, nc));
                    }
                }
            }
        }

        /** Determines whether a cell can be entered (not an obstacle). */
        private boolean canTraverse(int r, int c) {
            char cell = grid[r][c];
            // Only digits, 'S', 'E' are traversable.
            return cell != 'T' && cell != 'X'; // extend with any other obstacles here
        }

        /** Checks that coordinates are inside the grid boundaries. */
        private boolean valid(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }

        /** Returns the length of the shortest path from start to end (or -1). */
        int shortestPathLength() {
            bfs(start, distanceFromStart);
            if (distanceFromStart[end.row][end.col] == -1) {
                return -1; // unreachable
            }
            // also fill distance from end for later use
            bfs(end, distanceFromEnd);
            return distanceFromStart[end.row][end.col];
        }

        /** Sums numeric values of all cells that belong to any shortest path. */
        long sumOfDigitsOnShortestPaths() {
            int shortest = shortestPathLength();
            if (shortest == -1) {
                return 0L;
            }
            long sum = 0L;
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    char cell = grid[r][c];
                    if (Character.isDigit(cell)) {
                        int distFromStart = distanceFromStart[r][c];
                        int distFromEnd = distanceFromEnd[r][c];
                        if (distFromStart != -1 && distFromEnd != -1 &&
                            distFromStart + distFromEnd == shortest) {
                            sum += (cell - '0');
                        }
                    }
                }
            }
            return sum;
        }
    }

    /** ---------------------------------------------------------------------- */
    /** Entry point.                                                             */
    /** ---------------------------------------------------------------------- */
    public static void main(String[] args) throws Exception {
        try (InputReader reader = new InputReader(System.in);
             OutputWriter out = new OutputWriter(System.out)) {

            int rows = reader.nextInt();
            int cols = reader.nextInt();

            char[][] grid = new char[rows][cols];
            Point start = null;
            Point end = null;

            for (int r = 0; r < rows; r++) {
                String line = reader.nextString();
                for (int c = 0; c < cols; c++) {
                    grid[r][c] = line.charAt(c);
                    if (grid[r][c] == 'S') {
                        start = new Point(r, c);
                    } else if (grid[r][c] == 'E') {
                        end = new Point(r, c);
                    }
                }
            }

            if (start == null || end == null) {
                out.println(0);
                return;
            }

            GridProcessor processor = new GridProcessor(grid, rows, cols, start, end);
            long result = processor.sumOfDigitsOnShortestPaths();
            out.println(result);
        }
    }
}

/* -------------------------------------------------------------------------
 *  Supporting class – kept outside of `Main` for clarity.
 * -------------------------------------------------------------------------- */
final class Point {
    final int row;
    final int col;

    Point(int row, int col) {
        this.row = row;
        this.col = col;
    }
}

import java.io.*;
import java.util.*;

/**
 * BirdianForest – finds the total value collected while traveling from the
 * exit ('E') to the start ('S') through a forest represented by a grid.
 * Numeric cells ('1'‑'9') contribute their digit value to the result; tree cells
 * ('T') are obstacles; empty cells are traversable.
 */
public class BirdianForest {

    /* --------------------------------------------------------------------- */
    /*                           CONSTANTS                                    */
    /* --------------------------------------------------------------------- */
    private static final char START = 'S';
    private static final char END   = 'E';
    private static final char WALL  = 'T';               // obstacle character
    private static final int[] DR = { -1, 1, 0, 0 };       // row deltas (up,down,…,)
    private static final int[] DC = { 0, 0, -1, 1 };       // col deltas

    /* --------------------------------------------------------------------- */
    /*                           MAIN ENTRY POINT                            */
    /* --------------------------------------------------------------------- */
    public static void main(String[] args) throws IOException {
        // try‑with‑resources guarantees proper closing of I/O streams
        try (BufferedReader reader = new BufferedReader(
                new InputStreamReader(System.in));
             PrintWriter writer = new PrintWriter(
                     new BufferedWriter(new OutputStreamWriter(System.out))) ) {

            char[][] forest = readForest(reader);
            int[] exitPos = locateCell(forest, END);
            int answer   = bfsTraversal(forest, exitPos[0], exitPos[1], writer);

            writer.println(answer);
            writer.flush(); // kept for parity with original; not strictly required
        }
    }

    /* --------------------------------------------------------------------- */
    /*                           INPUT HANDLING                               */
    /* --------------------------------------------------------------------- */
    /**
     * Reads the grid dimensions and the forest layout from the supplied reader.
     *
     * @param reader source of input
     * @return 2‑D char array representing the forest
     * @throws IOException if an I/O error occurs
     */
    private static char[][] readForest(BufferedReader reader) throws IOException {
        String[] dimensions = reader.readLine().split("\\s+");
        int rows = Integer.parseInt(dimensions[0]);
        int cols = Integer.parseInt(dimensions[1]);

        char[][] grid = new char[rows][cols];
        for (int r = 0; r < rows; r++) {
            grid[r] = reader.readLine().toCharArray();
        }
        return grid;
    }

    /**
     * Returns the coordinates of the first occurrence of {@code target}
     * in the grid. If not found, {@code {-1, -1}} is returned.
     *
     * @param grid    forest grid
     * @param target  character to locate
     * @return int[2] containing {row, col} of the target
     */
    private static int[] locateCell(char[][] grid, char target) {
        for (int r = 0; r < grid.length; r++) {
            for (int c = 0; c < grid[0].length; c++) {
                if (grid[r][c] == target) {
                    return new int[]{r, c};
                }
            }
        }
        return new int[]{-1, -1};
    }

    /* --------------------------------------------------------------------- */
    /*                           BFS IMPLEMENTATION                           */
    /* --------------------------------------------------------------------- */
    /**
     * Performs a breadth‑first search from the exit toward the start,
     * accumulating the numeric values encountered along the way.
     *
     * @param grid        forest grid
     * @param startRow    row coordinate of the exit
     * @param startCol    column coordinate of the exit
     * @param writer      PrintWriter used for outputting the final result
     * @return accumulated result value
     */
    private static int bfsTraversal(char[][] grid, int startRow, int startCol,
                                    PrintWriter writer) {
        boolean[][] visited = new boolean[grid.length][grid[0].length];
        Queue<Position> queue = new ArrayDeque<>();
        queue.add(new Position(startRow, startCol));
        visited[startRow][startCol] = true;

        int result = 0;
        boolean foundStart = false;

        while (!queue.isEmpty() && !foundStart) {
            int layerSize = queue.size();
            for (int i = 0; i < layerSize; i++) {
                Position cur = queue.poll();
                char cell = grid[cur.row][cur.col];

                // Found the start cell – stop after processing its layer
                if (cell == START) {
                    foundStart = true;
                    break;
                }

                // Accumulate numeric values ('1'‑'9')
                if (cell >= '1' && cell <= '9') {
                    result += cell - '0';
                }

                // Explore the four orthogonal neighbours
                for (int d = 0; d < DR.length; d++) {
                    int nr = cur.row + DR[d];
                    int nc = cur.col + DC[d];

                    if (isInside(grid, nr, nc) && grid[nr][nc] != WALL && !visited[nr][nc]) {
                        visited[nr][nc] = true;
                        queue.add(new Position(nr, nc));
                    }
                }
            }
        }
        return result;
    }

    /** Checks whether a given coordinate lies inside the grid bounds. */
    private static boolean isInside(char[][] grid, int r, int c) {
        return r >= 0 && r < grid.length && c >= 0 && c < grid[0].length;
    }

    /** Simple immutable holder for a grid position. */
    private static final class Position {
        final int row;
        final int col;

        Position(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }
}

