import java.io.*;
import java.util.*;

public class Main {

    /* ---------- Constants & utility classes ---------- */

    /** Minimum distance that cannot be used for comparisons. */
    private static final int INF = Integer.MAX_VALUE / 4;

    /** Directions used for 4‑neighbour movement (up, down, left, right). */
    private static final int[][] DIRS = {
            {-1, 0},   // up
            { 1, 0},   // down
            { 0,-1},   // left
            { 0, 1}    // right
    };

    /** Simple container for a cell coordinate used during BFS. */
    private static final class State {
        final int x;
        final int y;

        State(int x, int y) {
            this.x = x;
            this.y = y;
        }
    }

    /* ---------- Entry point ---------- */

    public static void main(String[] args) throws IOException {
        /* Fast I/O with try‑with‑resources ensures proper closure of streams. */
        try (BufferedReader br = new BufferedReader(
                new InputStreamReader(System.in));
             PrintWriter out = new PrintWriter(
                     new BufferedWriter(
                             new OutputStreamWriter(System.out))) {

            int testCases = Integer.parseInt(readLine(br));

            for (int tc = 0; tc < testCases; tc++) {
                // read grid dimensions
                StringTokenizer dimTok = new StringTokenizer(readLine(br));
                int rows = Integer.parseInt(dimTok.nextToken());
                int cols = Integer.parseInt(dimTok.nextToken());

                // read grid contents
                char[][] grid = new char[rows][];
                for (int r = 0; r < rows; r++) {
                    grid[r] = readLine(br).toCharArray();
                }

                // BFS from all 'E' cells
                int[][] distance = bfsFromTargets(grid);

                // locate the single 'S' cell (the target distance we need)
                int ourDist = -1;
                for (int r = 0; r < rows && ourDist == -1; r++) {
                    for (int c = 0; c < cols; c++) {
                        if (grid[r][c] == 'S') {
                            ourDist = distance[r][c];
                            break;
                        }
                    }
                }

                // compute the required sum of digits
                int result = accumulateDigits(grid, distance, ourDist);

                out.println(result);
            }
            out.flush();
        }
    }

    /* ---------- Core algorithm ---------- */

    /**
     * Performs a multi‑source BFS starting from every cell containing 'E'.
     * Returns a matrix with the shortest distance from any 'E' to each cell.
     */
    private static int[][] bfsFromTargets(char[][] grid) {
        int rows = grid.length;
        int cols = grid[0].length;
        int[][] dist = new int[rows][cols];
        for (int[] row : dist) {
            Arrays.fill(row, INF);
        }

        Queue<State> queue = new ArrayDeque<>();

        // initialise queue with all target cells ('E')
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == 'E') {
                    dist[r][c] = 0;
                    queue.add(new State(r, c));
                }
            }
        }

        // standard BFS expansion
        while (!queue.isEmpty()) {
            State cur = queue.poll();
            for (int[] dir : DIRS) {
                int nr = cur.x + dir[0];
                int nc = cur.y + dir[1];
                if (isInside(nr, nc, rows, cols)
                        && grid[nr][nc] != 'T'          // cannot step on a trap
                        && dist[nr][nc] > dist[cur.x][cur.y] + 1) {
                    dist[nr][nc] = dist[cur.x][cur.y] + 1;
                    queue.add(new State(nr, nc));
                }
            }
        }
        return dist;
    }

    /**
     * Sums all digit characters whose distance to the nearest 'E' is
     * less than or equal to {@code maxDist}.
     */
    private static int accumulateDigits(char[][] grid,
                                           int[][] distance,
                                           int maxDist) {
        int sum = 0;
        for (int r = 0; r < grid.length; r++) {
            for (int c = 0; c < grid[r].length; c++) {
                char ch = grid[r][c];
                if (Character.isDigit(ch) && distance[r][c] <= maxDist) {
                    sum += ch - '0';
                }
            }
        }
        return sum;
    }

    /* ---------- Helper methods ---------- */

    /** Checks whether a coordinate lies inside the grid bounds. */
    private static boolean isInside(int x, int y, int rows, int cols) {
        return x >= 0 && x < rows && y >= 0 && y < cols;
    }

    /**
     * Reads a line from {@code br}, trimming trailing newline characters.
     * If the stream ends, the program terminates gracefully.
     */
    private static String readLine(BufferedReader br) throws IOException {
        String line = br.readLine();
        if (line == null) {
            System.exit(0);
        }
        return line;
    }
}

import java.io.*;
import java.util.*;

public class B {

    // Directions: down, up, left, right
    private static final int[] DIR_X = {1, -1, 0, 0};
    private static final int[] DIR_Y = {0, 0, -1, 1};

    private BufferedReader reader;
    private PrintWriter writer;
    private StringTokenizer tokenizer;

    public static void main(String[] args) throws IOException {
        new B().run();
    }

    /** Entry point for the solution. */
    public void run() throws IOException {
        initialize_io();
        solve();
        writer.close();
    }

    /** Sets up the input and output streams. */
    private void initialize_io() {
        reader = new BufferedReader(
                new InputStreamReader(System.in));
        writer = new PrintWriter(System.out);
        tokenizer = null;
    }

    /** Main logic: reads input, performs BFS, calculates answer. */
    public void solve() throws IOException {
        int rows = nextInt();
        int cols = nextInt();
        char[][] grid = readGrid(rows);
        int[][] distances = bfsFromExit(rows, cols, grid);
        int startDistance = findStartDistance(distances, grid);
        int sum = computeSumOfDigits(grid, distances, startDistance);
        writer.println(sum);
    }

    /** Reads the grid from the input. */
    private char[][] readGrid(int n, int m) throws IOException {
        char[][] grid = new char[n][];
        for (int i = 0; i < n; i++) {
            grid[i] = next().toCharArray();
        }
        return grid;
    }

    /** Performs a breadth‑first search from all 'E' cells and fills the distance matrix. */
    private int[][] bfsFromExit(int n, int m, char[][] grid) {
        int[][] dist = new int[n][m];
        Arrays.fill(dist, 0);
        int[] queueX = new int[n * m];
        int[] queueY = new int[n * m];
        int head = 0;
        int tail = 0;

        // Initialize queue with all exit cells ('E')
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i][j] == 'E') {
                    queueX[tail] = i;
                    queueY[tail] = j;
                    tail++;
                    dist[i][j] = 1; // distance of the exit cell itself
                }
            }
        }

        // Standard BFS
        while (head < tail) {
            int x = queueX[head];
            int y = queueY[head];
            head++;

            for (int d = 0; d < 4; d++) {
                int nx = x + DIR_X[d];
                int ny = y + DIR_Y[d];
                if (isInside(nx, ny, n, m) && dist[nx][ny] == 0 && grid[nx][ny] != 'T') {
                    dist[nx][ny] = dist[x][y] + 1;
                    queueX[tail] = nx;
                    queueY[tail] = ny;
                    tail++;
                }
            }
        }
        return dist;
    }

    /** Locates the cell containing 'S' and returns its distance from the BFS result. */
    private int findStartDistance(int[][] distances, char[][] grid) {
        for (int i = 0; i < distances.length; i++) {
            for (int j = 0; j < distances[i].length; j++) {
                if (grid[i][j] == 'S') {
                    return distances[i][j];
                }
            }
        }
        throw new IllegalStateException("Start position 'S' not found in the grid.");
    }

    /** Sums all numeric cells whose distance is non‑zero and does not exceed the start cell distance. */
    private int computeSumOfDigits(char[][] grid, int[][] distances, int maxDistance) {
        int sum = 0;
        for (int i = 0; i < distances.length; i++) {
            for (int j = 0; j < distances[i].length; j++) {
                char cell = grid[i][j];
                if (distances[i][j] != 0 && distances[i][j] <= maxDistance
                        && cell >= '0' && cell <= '9') {
                    sum += cell - '0';
                }
            }
        }
        return sum;
    }

    /** Utility to check array bounds. */
    private boolean isInside(int x, int y, int n, int m) {
        return x >= 0 && x < n && y >= 0 && y < m;
    }

    /** Fast token reader. */
    private String next() throws IOException {
        while (tokenizer == null || !tokenizer.hasMoreTokens()) {
            tokenizer = new StringTokenizer(reader.readLine());
        }
        return tokenizer.nextToken();
    }

    private int nextInt() throws IOException {
        return Integer.parseInt(next());
    }

    private double nextDouble() throws IOException {
        return Double.parseDouble(next());
    }

    private long nextLong() throws IOException {
        return Long.parseLong(next());
    }
}

