/**
 * Solves a single test case.
 * The logic is a refactored version of the original program
 * (originally named cf192d.TaskA) with improved naming,
 * separation of concerns and removal of duplicated fields.
 */
class Solver {
    /** Maximum matrix size used in the original code. */
    private static final int MAX = 2000;

    /** Grid values: 0‑9 are digits, -1='E', -2='S' (source), -3='T'. */
    private int[][] grid;
    /** Distance from the source cell computed by BFS. */
    private int[][] distance;
    /** Visited flag for BFS traversal. */
    private boolean[][] visited;
    /** Queue used for BFS. */
    private final Queue<Pos> queue = new ArrayDeque<>();

    /** Infinity constant for initialising distance matrix. */
    private static final int INF = Integer.MAX_VALUE;

    /** Reads the grid from the input and stores it internally. */
    public void solve(InputReader reader, PrintWriter out) {
        readGrid(reader);
        int answer = computeAnswer();
        out.println(answer);
    }

    /** Parses the input according to the original specification. */
    private void readGrid(InputReader reader) {
        int rows = reader.nextInt();
        int cols = reader.nextInt();

        grid = new int[rows + 1][cols + 1];
        distance = new int[rows + 1][cols + 1];
        visited = new boolean[rows + 1][cols + 1];

        String[] lines = new String[rows + 1];
        for (int i = 1; i <= rows; i++) {
            lines[i] = reader.next();
        }

        int startRow = -1, startCol = -1;

        for (int i = 1; i <= rows; i++) {
            for (int j = 0; j < lines[i].length(); j++) {
                char ch = lines[i].charAt(j);
                int value;
                if (Character.isDigit(ch)) {
                    value = ch - '0';
                } else if (ch == 'E') {
                    value = -1;
                } else if (ch == 'S') {
                    value = -2;
                    startRow = i;
                    startCol = j + 1;
                } else if (ch == 'T') {
                    value = -3;
                } else {
                    value = Integer.MAX_VALUE; // obstacle / unknown character
                }
                grid[i][j + 1] = value;
            }
        }

        if (startRow == -1 || startCol == -1) {
            throw new IllegalArgumentException("Source 'S' not found in the grid.");
        }

        // Initialise distance matrix with INF
        for (int i = 1; i <= rows; i++) {
            Arrays.fill(distance[i], INF);
        }

        bfsFrom(startRow, startCol);
        out.println(sumReachablePositiveValues(startRow, startCol));
    }

    /** Breadth‑first search starting from (sr, sc). */
    private void bfsFrom(int sr, int sc) {
        queue.clear();
        distance[sr][sc] = 0;
        queue.offer(new Pos(sr, sc));

        while (!queue.isEmpty()) {
            Pos cur = queue.poll();
            visited[cur.row][cur.col] = true;

            int[][] dirs = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};
            for (int[] d : dirs) {
                int nr = cur.row + d[0];
                int nc = cur.col + d[1];
                if (isInside(nr, nc) && canEnter(nr, nc) && !visited[nr][nc]) {
                    visited[nr][nc] = true;
                    distance[nr][nc] = distance[cur.row][cur.col] + 1;
                    queue.offer(new Pos(nr, nc));
                }
            }
        }
    }

    /** True if (r, c) lies inside the grid boundaries. */
    private boolean isInside(int r, int c) {
        return r >= 1 && r <= grid.length - 1 &&
               c >= 1 && c <= grid[0].length - 1;
    }

    /** Returns true if a cell can be traversed during BFS. */
    private boolean canEnter(int r, int c) {
        int val = grid[r][c];
        // Cells with value Integer.MAX_VALUE are obstacles.
        return val != Integer.MAX_VALUE;
    }

    /** Computes the answer according to the original algorithm. */
    private int sumReachablePositiveValues(int srcR, int srcC) {
        int answer = 0;
        int srcDist = distance[srcR][srcC];

        for (int i = 1; i < grid.length; i++) {
            for (int j = 1; j < grid[0].length; j++) {
                if (i == srcR && j == srcC) {
                    continue; // exclude the source cell itself
                }
                int cellValue = grid[i][j];
                if (cellValue > 0 && distance[i][j] <= srcDist) {
                    answer += cellValue;
                }
            }
        }
        return answer;
    }

    /** Simple container for a grid position used by BFS. */
    private static final class Pos {
        final int row;
        final int col;

        Pos(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }
}

