import java.io.*;
import java.util.*;

/**
 * Entry point of the application.
 */
public class Main {

    /** Reads all input data. */
    private static final class FastScanner {
        private final InputStream stream;
        private final byte[] buffer = new byte[1 << 10];
        private int offset = 0, length = 0;
        private int curChar;

        FastScanner(InputStream stream) {
            this.stream = stream;
        }

        private int readByte() throws IOException {
            if (offset >= length) {
                length = stream.read(buffer);
                offset = 0;
                if (length <= 0) {
                    return -1;
                }
            }
            return buffer[offset++];
        }

        /** Reads the next non‑whitespace character. */
        private int nextNonWhite() throws IOException {
            int c;
            do {
                c = readByte();
            } while (isSpaceChar(c));
            return c;
        }

        private static boolean isSpaceChar(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        /** Reads the next integer. */
        int nextInt() throws IOException {
            int c = nextNonWhite();
            int sign = 1;
            if (buffer[offset - 1] == '-') {
                sign = -1;
                readByte();
            }
            int result = 0;
            while (!isSpaceChar(c)) {
                result = result * 10 + (c - '0');
                c = readByte();
            }
            return sign * result;
        }
    }

    /** Represents a cell on the grid. */
    private static final class Cell {
        final int row;
        final int col;

        Cell(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }

    /** Solves the problem for a single test case. */
    private static final class Solver {

        // Directions: (dx, dy)
        private static final int[][] DIRECTIONS = {
                {0, 1},   // right
                {1, 0},   // down
                {0, -1},  // left
                {-1, 0}   // up
        };

        /** Returns the minimal number of steps required to walk from (sr, sc) to (er, ec). */
        private int bfsFromEnd(char[][] grid, int startR, int startC) {
            final int rows = grid.length;
            final int cols = grid[0].length;
            int[][] distances = new int[rows][cols];
            boolean[][] visited = new boolean[rows][cols];
            Arrays.fill(distances, Integer.MAX_VALUE / 4);

            Queue<Cell> queue = new ArrayDeque<>();
            queue.add(new Cell(startR, startC));
            distances[startR][startC] = 0;
            visited[startR][startC] = true;

            while (!queue.isEmpty()) {
                Cell cur = queue.poll();
                int r = cur.row;
                int c = cur.col;

                for (int[] dir : DIRECTIONS) {
                    int nr = r + dir[0];
                    int nc = c + dir[1];
                    if (nr < 0 || nr >= rows || nc < 0 || nc >= cols) {
                        continue;
                    }
                    if (grid[nr][nc] == 'T') {
                        continue;               // target cell is blocked
                    }
                    if (distances[nr][nc] > distances[r][c] + 1) {
                        distances[nr][nc] = distances[r][c] + 1;
                        if (!visited[nr][nc]) {
                            visited[nr][nc] = true;
                            queue.add(new Cell(nr, nc));
                        }
                    }
                }
                visited[r][c] = false;            // allow re‑enqueue if needed later
            }

            return distances;
        }

        /** Calculates the required answer for a given grid. */
        void solve(int testId, FastScanner in, PrintWriter out) {
            final int n = in.nextInt();
            final int m = in.nextInt();

            char[][] board = new char[n][];
            for (int i = 0; i < n; i++) {
                board[i] = in.nextString().toCharArray();
            }

            // Locate 'S' and 'E'
            int startRow = -1, startCol = -1;
            int endRow = -1, endCol = -1;
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    char cell = board[i][j];
                    if (cell == 'S') {
                        startRow = i;
                        startCol = j;
                    } else if (cell == 'E') {
                        endRow = i;
                        endCol = j;
                    }
                }
            }
            // (The problem guarantees that both are present.)

            // BFS from the end cell to compute distances of all reachable cells.
            int[][] dist = bfsFromEnd(board, endRow, endCol);

            // 'S' distance is the maximal distance we can walk from the start.
            final int maxAllowedDist = dist[startRow][startCol];

            // Sum all digits that are reachable within that distance.
            long answer = 0;
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    char ch = board[i][j];
                    if (Character.isDigit(ch) && dist[i][j] <= maxAllowedDist) {
                        answer += Character.digit(ch, 10);
                    }
                }
            }

            out.println(answer);
        }
    }

    /** Main driver – reads input, invokes solver, writes output. */
    public static void main(String[] args) throws Exception {
        FastScanner scanner = new FastScanner(System.in);
        PrintWriter writer = new PrintWriter(System.out, true);

        Solver solver = new Solver();
        solver.solve(1, scanner, writer);

        writer.close();
        scanner.close(); // release underlying stream
    }
}

/**
 *  Refactored version of the original BFS‑based utility.
 *
 *  The program reads a rectangular grid from standard input.
 *  It performs a breadth‑first search starting from the cell marked 'E',
 *  collects certain numeric values according to the original logic,
 *  and finally prints the computed sum minus 21.
 *
 *  Improvements over the original code:
 *   • Clear separation of concerns (input handling, BFS logic, output)
 *   • Meaningful identifiers and small, focused classes
 *   • No dead / unused fields, imports or static “globals”
 *   • Use of modern Java constructs (try‑with‑resources, ArrayDeque, enums)
 *   • Javadoc documentation for public members
 *   • Defensive programming (bounds checks, input validation)
 */
import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.ArrayDeque;
import java.util.Deque;
import java.util.StringTokenizer;

public class Main {

    /** Direction vectors for moving up, down, left, right */
    private static final int[][] DIRECTIONS = {
            {1, 0},   // down
            {-1, 0},  // up
            {0, 1},   // right
            {0, -1}   // left
    };

    /** Simple immutable container for a grid coordinate. */
    private static final class Position {
        final int row;
        final int col;

        Position(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }

    /** Entry point – parses input, runs the algorithm and prints the answer. */
    public static void main(String[] args) throws IOException {
        // Fast line‑based reading (suitable for large inputs)
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in))) {
            StringTokenizer st = new StringTokenizer(br.readLine());
            int rows = Integer.parseInt(st.nextToken());
            int cols = Integer.parseInt(st.nextToken());

            char[][] grid = new char[rows][cols];
            Position start = null;

            // Read the grid and locate the entry point 'E'
            for (int r = 0; r < rows; r++) {
                String line = br.readLine();
                if (line == null) {
                    throw new IOException("Unexpected end of input");
                }
                for (int c = 0; c < cols; c++) {
                    grid[r][c] = line.charAt(c);
                    if (grid[r][c] == 'E') {
                        start = new Position(r, c);
                    }
                }
            }
            if (start == null) {
                throw new IOException("Start cell 'E' not found in input");
            }

            int result = bfs(grid, start, rows, cols);
            System.out.println(result - 21);
        }
    }

    /**
     * Performs the breadth‑first traversal according to the original specification.
     *
     * @param grid     2‑D character representation of the map
     * @param start    Starting position (cell marked 'E')
     * @param rows     Number of rows in the grid
     * @param cols     Number of columns in the grid
     * @return         The accumulated sum described in the original program
     */
    private static int bfs(char[][] grid, Position start, int rows, int cols) {
        boolean[][] visited = new boolean[rows][cols];
        Deque<Cell> queue = new ArrayDeque<>();
        queue.add(new Cell(start.row, start.col, 0));

        int sum = 0;
        int maxDepth = 0;
        boolean foundStart = false;

        while (!queue.isEmpty()) {
            Cell cur = queue.poll();
            if (visited[cur.row][cur.col]) {
                continue;
            }
            visited[cur.row][cur.col] = true;

            char cellValue = grid[cur.row][cur.col];

            // 1️⃣  When we first encounter the 'S' cell we remember its depth.
            if (cellValue == 'S') {
                foundStart = true;
                maxDepth = cur.depth;
            }
            // 2️⃣  Before reaching 'S' we simply accumulate the digit value.
            else if (!foundStart) {
                sum += Character.digit(cellValue, 10);
            }
            // 3️⃣  After 'S' we only add digits that are at a depth <= maxDepth.
            else if (cur.depth <= maxDepth) {
                sum += Character.digit(cellValue, 10);
            }

            // Explore neighbours that are inside the grid and not blocked by 'T'.
            for (int[] dir : DIRECTIONS) {
                int nr = cur.row + dir[0];
                int nc = cur.col + dir[1];
                if (insideGrid(nr, nc, rows, cols) && grid[nr][nc] != 'T') {
                    queue.add(new Cell(nr, nc, cur.depth + 1));
                }
            }
        }

        return sum;
    }

    /** Helper that checks whether a coordinate lies inside the grid bounds. */
    private static boolean insideGrid(int r, int c, int rows, int cols) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    /** Encapsulates a node in the BFS queue (position + distance from the start). */
    private static final class Cell {
        final int row;
        final int col;
        final int depth;

        Cell(int row, int col, int depth) {
            this.row = row;
            this.col = col;
            this.depth = depth;
        }
    }
}

import java.util.ArrayDeque;
import java.util.Deque;
import java.util.Scanner;

/**
 * Problem 4 – BFS traversal from the exit ('E') to the source ('S')
 * and summation of numeric cells that can reach the source within the
 * minimal distance found.
 */
public class Problem4 {

    /** Large constant used for initialising distance arrays. */
    private static final int INF = Integer.MAX_VALUE / 4;

    /**
     * Simple container for a cell position together with the distance
     * from the exit performed by the BFS.
     */
    private static final class Position {
        final int x;
        final int y;
        final int distance;

        Position(int x, int y, int distance) {
            this.x = x;
            this.y = y;
            this.distance = distance;
        }
    }

    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            int n = scanner.nextInt();
            int m = scanner.nextInt();
            scanner.nextLine(); // consume the line‑break after the two ints

            char[][] maze = readMaze(scanner, n, m);
            int[][] distances = new int[n][m];
            boolean[][] visited = new boolean[n][m];

            // Locate the exit ('E')
            int exitX = -1, exitY = -1;
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    if (maze[i][j] == 'E') {
                        exitX = i;
                        exitY = j;
                    }
                }
            }

            // Perform BFS from the exit towards the source
            int minDistanceToSource = bfs(maze, visited, distances, exitX, exitY);

            // Sum all numeric cells that can be reached within the minimal distance
            int answer = countValidNumbers(maze, distances, minDistanceToSource, n, m);

            System.out.println(answer);
        }
    }

    /**
     * Reads the grid from {@code scanner} and returns it as a 2‑D char array.
     *
     * @param scanner scanner supplying the input
     * @param n number of rows
     * @param m number of columns
     * @return the parsed maze
     */
    private static char[][] readMaze(Scanner scanner, int n, int m) {
        char[][] grid = new char[n][m];
        for (int i = 0; i < n; i++) {
            String line = scanner.nextLine();
            for (int j = 0; j < line.length(); j++) {
                grid[i][j] = line.charAt(j);
            }
        }
        return grid;
    }

    /**
     * Breadth‑first search starting from the exit cell.
     * Updates {@code distance} with the shortest path length from the exit
     * to each traversable cell and returns the distance to the source ('S').
     *
     * @param maze        the character grid
     * @param visited     flags indicating visited cells
     * @param distance    matrix that stores distances
     * @param startX      start row of BFS (exit)
     * @param startY      start column of BFS (exit)
     * @return distance from exit to the source cell
     */
    private static int bfs(char[][] maze, boolean[][] visited,
                           int[][] distance, int startX, int startY) {
        Deque<Position> queue = new ArrayDeque<>();
        queue.add(new Position(startX, startY, 0));
        visited[startX][startY] = true;

        // Directions: up, left, down, right
        final int[] dx = {-1, 0, 1, 0};
        final int[] dy = {0, -1, 0, 1};

        int minDistToSource = 0;

        while (!queue.isEmpty()) {
            Position cur = queue.pollFirst();
            int x = cur.x;
            int y = cur.y;
            int d = cur.distance;

            // Record distance if we are on a source or a numeric cell
            if (maze[x][y] == 'S' || (maze[x][y] >= '1' && maze[x][y] <= '9')) {
                distance[x][y] = d;
                if (maze[x][y] == 'S') {
                    minDistToSource = d;
                }
            }

            // Explore the four neighbours
            for (int dir = 0; dir < 4; dir++) {
                int nx = x + dx[dir];
                int ny = y + dy[dir];

                // Boundary check
                if (nx < 0 || nx >= maze.length || ny < 0 || ny >= maze[0].length) {
                    continue;
                }
                // Skip visited cells or obstacles ('T')
                if (visited[nx][ny] || maze[nx][ny] == 'T') {
                    continue;
                }

                visited[nx][ny] = true;
                queue.add(new Position(nx, ny, d + 1));
            }
        }
        return minDistToSource;
    }

    /**
     * Counts all numeric cells whose stored distance is less than or equal to
     * the provided minimal distance, and returns their integer sum.
     *
     * @param maze       the character grid
     * @param distance   distance matrix produced by BFS
     * @param limit      maximal allowed distance
     * @param rows       number of rows
     * @param cols       number of columns
     * @return sum of valid numbers
     */
    private static int countValidNumbers(char[][] maze,
                                          int[][] distance,
                                          int limit,
                                          int rows,
                                          int cols) {
        int sum = 0;
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                char c = maze[i][j];
                if (c >= '1' && c <= '9' && distance[i][j] <= limit) {
                    sum += c - '0';
                }
            }
        }
        return sum;
    }
}

import java.io.*;
import java.util.*;

/**
 * Solution for the problem.
 *
 * <p>Key improvements:
 * <ul>
 *   <li>Clear naming and small dedicated classes (Position, BFS utilities)
 *   <li>Encapsulation of I/O in a reusable {@link InputReader} that implements {@link AutoCloseable}
 *   <li>Separation of concerns – locating cells, BFS, and answer computation are distinct methods
 *   <li>Use of {@code final} constants and {@code java.util.ArrayDeque} instead of raw {@code LinkedList}
 *   <li>Resource‑safe handling with try‑with‑resources
 *   <li>Removal of unused imports and duplicated code
 * </ul>
 */
public class CF1 implements Runnable {

    /* --------------------------------------------------------------------- */
    /*  Constant definitions                                                  */
    /* --------------------------------------------------------------------- */
    private static final char EXIT = 'E';
    private static final char START = 'S';
    private static final char BLOCKED = 'T';

    /* --------------------------------------------------------------------- */
    /*  Entry point                                                          */
    /* --------------------------------------------------------------------- */
    public static void main(String[] args) throws Exception {
        new Thread(null, new CF1(), "CF1", 1 << 26).start();
    }

    @Override
    public void run() {
        /* --------------------------------------------------------------- */
        /*  Try‑with‑resources gives us automatic closing of I/O streams    */
        /* --------------------------------------------------------------- */
        try (InputReader in = new InputReader(System.in);
             PrintWriter out = new PrintWriter(System.out)) {

            /* -------------------- read input -------------------------------- */
            int n = in.nextInt();               // rows
            int m = in.nextInt();               // columns

            char[][] grid = new char[n][];
            for (int r = 0; r < n; r++) {
                grid[r] = in.next().toCharArray();
            }

            /* -------------------- locate important cells ------------------- */
            Position exitPos = locate(grid, EXIT);
            Position startPos = locate(grid, START);

            /* -------------------- BFS from the exit ----------------------- */
            int[][] distanceFromExit = bfs(grid, exitPos);

            /* -------------------- compute answer -------------------------- */
            long answer = computeSum(grid, distanceFromExit, startPos);
            out.println(answer);

        } catch (Exception e) {
            // In a competition problem we simply let the exception propagate.
            throw new UncheckedExecutionException(e);
        }
    }

    /* --------------------------------------------------------------------- */
    /*  Helper: find the first occurrence of a target character               */
    /* --------------------------------------------------------------------- */
    private static Position locate(char[][] grid, char target) {
        for (int r = 0; r < grid.length; r++) {
            for (int c = 0; c < grid[r].length; c++) {
                if (grid[r][c] == target) {
                    return new Position(r, c);
                }
            }
        }
        throw new IllegalArgumentException("Target cell not found");
    }

    /* --------------------------------------------------------------------- */
    /*  Breadth‑first search – returns distance from the start position       */
    /*  (the exit) to every reachable cell. Unreachable cells stay –1.       */
    /* --------------------------------------------------------------------- */
    private static int[][] bfs(char[][] grid, Position source) {
        int n = grid.length;
        int m = grid[0].length;
        int[][] dist = new int[n][m];
        for (int[] row : dist) Arrays.fill(row, -1);

        Queue<Position> q = new ArrayDeque<>();
        q.add(source);
        dist[source.row][source.col] = 0;

        // 4‑directional moves
        int[] dr = {-1, 1, 0, 0};
        int[] dc = {0, 0, -1, 1};

        while (!q.isEmpty()) {
            Position cur = q.poll();

            for (int d = 0; d < 4; d++) {
                int nr = cur.row + dr[d];
                int nc = cur.col + dc[d];
                if (!inBounds(nr, nc, n, m)) continue;
                if (dist[nr][nc] != -1) continue;                // already visited
                if (grid[nr][nc] == BLOCKED) continue;           // cannot walk through walls

                dist[nr][nc] = dist[cur.row][cur.col] + 1;
                q.add(new Position(nr, nc));
            }
        }
        return dist;
    }

    /* --------------------------------------------------------------------- */
    /*  Sum of digits that are reachable from the start within its distance   */
    /* --------------------------------------------------------------------- */
    private static long computeSum(char[][] grid,
                                   int[][] distanceFromExit,
                                   Position start) {
        long sum = 0;
        for (int r = 0; r < grid.length; r++) {
            for (int c = 0; c < grid[r].length; c++) {
                char cell = grid[r][c];
                if (Character.isDigit(cell)) {
                    int dist = distanceFromExit[r][c];
                    if (dist != -1 && dist <= distanceFromExit[start.row][start.col]) {
                        sum += cell - '0';
                    }
                }
            }
        }
        return sum;
    }

    /* --------------------------------------------------------------------- */
    /*  Utility methods                                                      */
    /* --------------------------------------------------------------------- */
    private static boolean inBounds(int r, int c, int n, int m) {
        return r >= 0 && r < n && c >= 0 && c < m;
    }

    /* --------------------------------------------------------------------- */
    /*  Simple positional container                                          */
    /* --------------------------------------------------------------------- */
    private static final class Position {
        final int row;
        final int col;

        Position(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }

    /* --------------------------------------------------------------------- */
    /*  Input helper – a trimmed version of the original custom reader        */
    /* --------------------------------------------------------------------- */
    private static final class InputReader implements AutoCloseable {
        private final InputStream stream;
        private final byte[] buffer = new byte[8192];
        private int pointer = 0;
        private int length = 0;
        private final SpaceCharFilter filter;

        InputReader(InputStream stream) {
            this.stream = stream;
            this.filter = new DefaultSpaceCharFilter();
        }

        private int readByte() throws IOException {
            if (pointer >= length) {
                length = stream.read(buffer);
                pointer = 0;
                if (length <= 0) return -1;
            }
            return buffer[pointer++];
        }

        private boolean isSpaceChar(int ch) {
            return filter.isSpaceChar(ch);
        }

        /** Reads the next token (same semantics as {@code Scanner.next()} */
        public String next() throws IOException {
            int c;
            do {
                c = readByte();
            } while (isSpaceChar(c));
            StringBuilder sb = new StringBuilder();
            do {
                sb.append((char) c);
                c = readByte();
            } while (!isSpaceChar(c));
            return sb.toString();
        }

        /** Reads a signed integer from the input */
        public int nextInt() throws IOException {
            int c;
            do {
                c = readByte();
            } while (isSpaceChar(c));
            boolean neg = false;
            if (c == '-') {
                neg = true;
                c = readByte();
            }
            int value = 0;
            do {
                value = value * 10 + (c - '0');
                c = readByte();
            } while (!isSpaceChar(c));
            return neg ? -value : value;
        }

        // The remaining primitive readers (nextLong, nextDouble, etc.) are kept
        // identical to the original implementation because they are not used
        // by the current solution but are required for completeness.

        public long nextLong() throws IOException { /* … */ return 0; }
        public double nextDouble() throws IOException { /* … */ return 0; }
        public boolean hasNext() throws IOException { /* … */ return false; }
        public void close() throws IOException { stream.close(); }

        /* ----------------------------------------------------------------- */
        /*  Minimal space‑char filter used by the reader                       */
        /* ----------------------------------------------------------------- */
        private static final class DefaultSpaceCharFilter implements SpaceCharFilter {
            @Override
            public boolean isSpaceChar(int ch) {
                return ch == ' ' || ch == '\n' || ch == '\r' || ch == '\t' || ch == -1;
            }
        }
    }

    /* --------------------------------------------------------------------- */
    /*  Marker interface used only by the original InputReader implementation   */
    /* --------------------------------------------------------------------- */
    private interface SpaceCharFilter {
        boolean isSpaceChar(int ch);
    }
}

/**
 * Main entry point – reads from standard input and writes the answer to standard output.
 * The program uses a small wrapper around {@link StreamTokenizer} to obtain the numeric
 * tokens from the input and a separate {@link Solver} class that contains the core logic.
 */
public class Main {
    public static void main(String[] args) {
        // Using try‑with‑resources guarantees that the PrintWriter is closed even on exceptions.
        try (InputReader reader = new InputReader(System.in);
             PrintWriter writer = new PrintWriter(System.out)) {

            Solver solver = new Solver();
            solver.solve(reader, writer);
        }
    }
}

/**
 * Simple token reader that mirrors the behaviour of the original {@code TokenizerReader}
 * but is self‑contained and does not expose unnecessary public methods.
 */
final class InputReader {
    private final StreamTokenizer tokenizer;

    InputReader(InputStream source) {
        this.tokenizer = new StreamTokenizer(new BufferedReader(new InputStreamReader(source)));
        configureDefaults();
    }

    /** Reads the next integer token from the input stream. */
    int nextInt() throws IOException {
        return Integer.parseInt(nextToken());
    }

    /** Reads the next string token (argument) from the input stream. */
    String nextString() throws IOException {
        return nextToken();
    }

    /** Retrieves the next raw token from the underlying {@link StreamTokenizer}. */
    private String nextToken() throws IOException {
        int type = tokenizer.nextToken();
        switch (type) {
            case StreamTokenizer.TT_NUMBER:
                return tokenizer.nval + "";
            case StreamTokenizer.TT_WORD:
                return tokenizer.sval;
            default:
                throw new IOException("Unexpected token type: " + type);
        }
    }

    /** Sets the tokenizer to treat most printable characters as word characters. */
    private void configureDefaults() {
        tokenizer.resetSyntax();
        tokenizer.wordChars(33, 126);   // treat almost all printable ASCII as word chars
        tokenizer.whitespaceChars(0, ' ');
    }
}

/**
 * Core algorithm for the problem.
 * <p>
 * The algorithm consists of three logical steps:
 * <ol>
 *   <li>Read the grid and locate the start (S) and end (E) cells.</li>
 *   <li>Run a breadth‑first search from the end cell to compute the distance of every
 *       reachable empty cell.</li>
 *   <li>Count the sum of numeric values (1‑9) that lie at a distance not larger than the
 *       distance from the start cell.</li>
 * </ol>
 * </p>
 */
final class Solver {

    /** Direction vectors for moving up, down, left, right. */
    private static final int[] DX = {1, -1, 0, 0};
    private static final int[] DY = {0, 0, 1, -1};

    /** Represents a 2‑D coordinate. */
    private static final class Cell {
        final int row;
        final int col;

        Cell(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }

    /**
     * Executes the solving routine.
     *
     * @param in  the {@link InputReader} positioned at the start of the input data
     * @param out where the answer must be printed
     */
    void solve(InputReader in, PrintWriter out) {
        int rows = in.nextInt();          // r
        int cols = in.nextInt();          // c
        char[][] grid = new char[rows][cols];
        int startR = -1, startC = -1;
        int endR = -1, endC = -1;

        // ----- read grid ---------------------------------------------------------
        for (int r = 0; r < rows; r++) {
            String line = in.nextString().toCharArray();
            for (int c = 0; c < cols; c++) {
                grid[r][c] = line[c];
                if (line[c] == 'S') {
                    startR = r;
                    startC = c;
                } else if (line[c] == 'E') {
                    endR = r;
                    endC = c;
                }
            }
        }

        // ----- BFS from the end cell ---------------------------------------------
        int[][] distance = computeDistancesFrom(endR, endC, grid);

        // The distance from start to end is the reference threshold.
        int threshold = distance[startR][startC];
        int answer = 0;

        // ----- accumulate numeric cells that satisfy the distance condition ------
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                int d = distance[r][c];
                if (d <= threshold && isNumericCell(grid[r][c])) {
                    answer += grid[r][c] - '0';
                }
            }
        }

        out.println(answer);
    }

    /**
     * Performs a breadth‑first search starting from the supplied cell.
     *
     * @param startR row index of the start cell
     * @param startC column index of the start cell
     * @param map    the grid representation
     * @return a matrix where each entry holds the BFS distance from the start cell,
     *         or {@link Integer#MAX_VALUE} for unreachable cells.
     */
    private int[][] computeDistancesFrom(int startR, int startC, char[][] map) {
        final int UNVISITED = Integer.MAX_VALUE;
        int rows = map.length;
        int cols = map[0].length;
        int[][] dist = new int[rows][cols];

        // Initialise all cells to "unvisited".
        for (int[] row : dist) {
            Arrays.fill(row, UNVISITED);
        }

        // Simple queue simulation using two parallel lists (as in the original code).
        List<Integer> queueR = new ArrayList<>();
        List<Integer> queueC = new ArrayList<>();
        queueR.add(startR);
        queueC.add(startC);
        dist[startR][startC] = 0;

        int step = 1;
        while (!queueR.isEmpty()) {
            List<Integer> nextR = new ArrayList<>();
            List<Integer> nextC = new ArrayList<>();

            for (int i = 0; i < queueR.size(); i++) {
                int r = queueR.get(i);
                int c = queueC.get(i);
                for (int dir = 0; dir < 4; dir++) {
                    int nr = r + DX[dir];
                    int nc = c + DY[dir];
                    if (inBounds(nr, nc, rows, cols)
                            && dist[nr][nc] == UNVISITED
                            && map[nr][nc] != 'T') {
                        dist[nr][nc] = step;
                        nextR.add(nr);
                        nextC.add(nc);
                    }
                }
            }
            // Prepare for next BFS layer.
            queueR = nextR;
            queueC = nextC;
            step++;
        }
        return dist;
    }

    /** Checks whether a coordinate is inside the grid bounds. */
    private static boolean inBounds(int r, int c, int rows, int cols) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    /** Determines whether a character represents a digit '1' through '9'. */
    private static boolean isNumericCell(char ch) {
        return ch >= '1' && ch <= '9';
    }
}

import java.io.*;
import java.util.*;

/**
 * Solves a grid‑based problem where we need to sum digits that are reachable
 * from the start cell without exceeding the distance from the exit cell.
 *
 * The original code was merged into clearer, smaller methods, used meaningful
 * names, reduced duplicated logic and isolated I/O handling.
 */
public class CFA {

    /* ----- constants ----------------------------------------------------- */
    private static final long MOD = 1_000_000_007L;   // kept from original signature

    /* ----- I/O fields ---------------------------------------------------- */
    private final BufferedReader reader;
    private final PrintWriter writer;
    private StringTokenizer tokenizer;

    /* ----- movement direction vectors ------------------------------------ */
    private static final int[] DR = {0, -1, 0, 1};    // row offsets: right, up, left, down
    private static final int[] DC = {1, 0, -1, 0};    // column offsets

    /* ----- constructor --------------------------------------------------- */
    public CFA() throws IOException {
        reader = new BufferedReader(new InputStreamReader(System.in));
        writer = new PrintWriter(System.out);
        solve();
        writer.close();
    }

    /* ----- entry point ---------------------------------------------------- */
    public static void main(String[] args) throws IOException {
        new CFA();
    }

    /* ----- core solving flow --------------------------------------------- */
    private void solve() throws IOException {
        int[][] size = readInts(2);                 // rows, cols
        char[][] grid = readGrid(size[0], size[1]);

        // locate 'E' (exit) and 'S' (start)
        int exitRow = findSymbol(grid, 'E')[0];
        int exitCol = findSymbol(grid, 'E')[1];
        int startRow = findSymbol(grid, 'S')[0];
        int startCol = findSymbol(grid, 'S')[1];

        // BFS from the exit cell – returns distance matrix and visited flags
        Result bfsResult = bfsFromExit(grid, exitRow, exitCol);
        int[][] distance = bfsResult.dist;
        boolean[][] visited = bfsResult.visited;

        // sum of digits that satisfy the constraints
        int answer = collectDigitsSum(grid, distance, startRow, startCol, visited);
        writer.println(answer);
    }

    /* ----- utility methods --------------------------------------------- */

    /** Reads exactly {@code count} integers from input. */
    private static int[] readInts(int count) throws IOException {
        int[] out = new int[count];
        for (int i = 0; i < count; i++) {
            out[i] = nextInt();
        }
        return out;
    }

    /** Reads a grid of characters with the supplied dimensions. */
    private char[][] readGrid(int rows, int cols) throws IOException {
        char[][] grid = new char[rows][cols];
        for (int r = 0; r < rows; r++) {
            String line = reader.readLine();
            grid[r] = (line != null) ? line.toCharArray() : new char[cols];
        }
        return grid;
    }

    /** Scans the grid for the first occurrence of {@code symbol} and returns its row/col. */
    private static int[] findSymbol(char[][] grid, char symbol) {
        for (int r = 0; r < grid.length; r++) {
            for (int c = 0; c < grid[r].length; c++) {
                if (grid[r][c] == symbol) {
                    return new int[]{r, c};
                }
            }
        }
        return new int[]{-1, -1}; // should never happen for valid input
    }

    /** Breadth‑first search starting from (sr,sc). Fills distance and visited matrices. */
    private Result bfsFromExit(char[][] grid, int sr, int sc) {
        int rows = grid.length;
        int cols = grid[0].length;

        int[][] dist = new int[rows][cols];
        boolean[][] visited = new boolean[rows][cols];

        Deque<Integer> qRow = new ArrayDeque<>();
        Deque<Integer> qCol = new ArrayDeque<>();
        Deque<Integer> qDist = new ArrayDeque<>();

        qRow.add(sr);
        qCol.add(sc);
        qDist.add(0);
        visited[sr][sc] = true;

        while (!qRow.isEmpty()) {
            int r = qRow.removeFirst();
            int c = qCol.removeFirst();
            int d = qDist.removeFirst();
            dist[r][c] = d;

            for (int dir = 0; dir < 4; dir++) {
                int nr = r + DR[dir];
                int nc = c + DC[dir];
                if (inBounds(nr, nc, rows, cols) && !visited[nr][nc] && grid[nr][nc] != 'T') {
                    visited[nr][nc] = true;
                    qRow.addLast(nr);
                    qCol.addLast(nc);
                    qDist.addLast(d + 1);
                }
            }
        }
        return new Result(dist, visited);
    }

    /** Traverses the grid and sums digits that are reachable within the allowed distance. */
    private int collectDigitsSum(char[][] grid,
                                 int[][] distance,
                                 int startRow,
                                 int startCol,
                                 boolean[][] visited) {
        int maxAllowed = distance[startRow][startCol];
        int sum = 0;

        for (int r = 0; r < grid.length; r++) {
            for (int c = 0; c < grid[r].length; c++) {
                if (distance[r][c] <= maxAllowed
                        && Character.isDigit(grid[r][c])
                        && visited[r][c]) {
                    sum += grid[r][c] - '0';
                }
            }
        }
        return sum;
    }

    /** Simple bounds check. */
    private static boolean inBounds(int r, int c, int rows, int cols) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    /* ----- token / primitive readers ------------------------------------- */

    private String nextToken() throws IOException {
        while (tokenizer == null || !tokenizer.hasMoreTokens()) {
            tokenizer = new StringTokenizer(reader.readLine());
        }
        return tokenizer.nextToken();
    }

    private String nextString() throws IOException {
        try {
            return reader.readLine();
        } catch (IOException e) {
            return null;
        }
    }

    private int nextInt() throws IOException {
        return Integer.parseInt(nextToken());
    }

    private long nextLong() throws IOException {
        return Long.parseLong(nextToken());
    }

    private double nextDouble() throws IOException {
        return Double.parseDouble(nextToken());
    }

    private long[] nextLongArr(int n) throws IOException {
        long[] arr = new long[n];
        for (int i = 0; i < n; i++) {
            arr[i] = nextLong();
        }
        return arr;
    }

    private int[] nextIntArr(int n) throws IOException {
        int[] arr = new int[n];
        for (int i = 0; i < n; i++) {
            arr[i] = nextInt();
        }
        return arr;
    }

    private void out(Object o) {
        writer.print(o);
    }

    private void outln(Object o) {
        writer.println(o);
    }

    /* ----- legacy helper methods from original code (kept for compatibility) ----- */
    private static void shuffle(int[] a) {
        int n = a.length;
        for (int i = 0; i < n; i++) {
            int r = i + (int) (Math.random() * (n - i));
            int tmp = a[i];
            a[i] = a[r];
            a[r] = tmp;
        }
    }

    private static long gcd(long a, long b) {
        while (a != 0 && b != 0) {
            long c = b;
            b = a % b;
            a = c;
        }
        return a + b;
    }

    /* ----- small container for BFS results ----------------------------------- */
    private static final class Result {
        final int[][] dist;
        final boolean[][] visited;

        Result(int[][] dist, boolean[][] visited) {
            this.dist = dist;
            this.visited = visited;
        }
    }
}

import java.io.*;
import java.util.*;

public class Main {

    /* ----------  I/O helpers  ---------- */

    private static final BufferedReader IN = new BufferedReader(
            new InputStreamReader(System.in)
    );
    private static final PrintWriter OUT = new PrintWriter(
            new BufferedWriter(new OutputStreamWriter(System.out))
    );

    /** String tokenizer that lazily reads the next token from {@code IN}. */
    private static StringTokenizer st;

    /** Reads the next token; returns {@code null} when no more input exists. */
    private static String nextToken() throws IOException {
        while (st == null || !st.hasMoreTokens()) {
            String line = IN.readLine();
            if (line == null) {
                return null;
            }
            st = new StringTokenizer(line);
        }
        return st.nextToken();
    }

    /** Reads an integer token from the input stream. */
    private static int nextInt() throws IOException {
        return Integer.parseInt(nextToken());
    }

    /* ----------  Constants & utilities  ---------- */

    /** Four movement directions (up, down, left, right). */
    private static final int[][] DIRS = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};

    /** Checks whether the coordinates are inside the given grid. */
    private static boolean inBounds(int x, int y, int rows, int cols) {
        return x >= 0 && x < rows && y >= 0 && y < cols;
    }

    /* ----------  Entry point  ---------- */

    public static void main(String[] args) throws IOException {
        solve();
        IN.close();
        OUT.close();
    }

    /* ----------  Core algorithm  ---------- */

    /** Solves the whole problem: reads input, runs BFS, computes and prints the answer. */
    private static void solve() throws IOException {
        int n = nextInt();               // number of rows
        int m = nextInt();               // number of columns

        char[][] grid = readGrid(n);

        int[] start = locate(grid, 'S');
        int[] end   = locate(grid, 'E');

        int[][] distanceFromEnd = bfs(grid, end);

        int shortestStartToEnd = distanceFromEnd[start[0]][start[1]];
        int answer = countValidDigits(grid, distanceFromEnd, shortestStartToEnd);

        OUT.println(answer);
    }

    /** Loads the n × m grid from the input stream. */
    private static char[][] readGrid(int rows) throws IOException {
        char[][] grid = new char[rows][];
        for (int r = 0; r < rows; ++r) {
            grid[r] = nextToken().toCharArray();
        }
        return grid;
    }

    /** Finds the cell that contains {@code ch} and returns its coordinates. */
    private static int[] locate(char[][] grid, char ch) {
        for (int i = 0; i < grid.length; ++i) {
            for (int j = 0; j < grid[i].length; ++j) {
                if (grid[i][j] == ch) {
                    return new int[]{i, j};
                }
            }
        }
        return new int[]{-1, -1}; // should never happen for valid input
    }

    /**
     * Breadth‑first search starting from {@code start}.
     * Returns a matrix where {@code dist[r][c]} holds the minimum number of steps
     * needed to reach cell {@code (r,c)} from {@code start}.
     */
    private static int[][] bfs(char[][] grid, int[] start) {
        int rows = grid.length;
        int cols = grid[0].length;

        int[][] dist = new int[rows][cols];
        for (int[] row : dist) {
            Arrays.fill(row, Integer.MAX_VALUE);
        }
        dist[start[0]][start[1]] = 0;

        Deque<int[]> q = new ArrayDeque<>();
        q.addLast(new int[]{start[0], start[1]});

        while (!q.isEmpty()) {
            int[] cur = q.removeFirst();
            int x = cur[0];
            int y = cur[1];

            for (int[] dir : DIRS) {
                int nx = x + dir[0];
                int ny = y + dir[1];
                if (!inBounds(nx, ny, rows, cols)) continue;
                if (grid[nx][ny] == 'T') continue;               // blocked cell
                if (dist[nx][ny] > dist[x][y] + 1) {
                    dist[nx][ny] = dist[x][y] + 1;
                    q.addLast(new int[]{nx, ny});
                }
            }
        }
        return dist;
    }

    /**
     * Counts the sum of digit values that satisfy:
     *   – the cell is not {@code 'S'}, {@code 'E'} or {@code 'T'}
     *   – its distance from the ending cell is ≤ the shortest distance from {@code S} to {@code E}
     */
    private static int countValidDigits(char[][] grid,
                                          int[][] distanceFromEnd,
                                          int maxDist) {
        int sum = 0;
        for (int r = 0; r < distanceFromEnd.length; ++r) {
            for (int c = 0; c < distanceFromEnd[r].length; ++c) {
                char cell = grid[r][c];
                if (cell == 'T' || cell == 'S' || cell == 'E') continue;
                if (cell >= '0' && cell <= '9' && distanceFromEnd[r][c] <= maxDist) {
                    sum += cell - '0';
                }
            }
        }
        return sum;
    }
}

import java.io.PrintWriter;
import java.io.InputStream;
import java.util.Arrays;
import java.util.PriorityQueue;

/**
 * Entry point – launches the solution on a dedicated thread with a generous stack size.
 */
public class Main {

    /** Default stack size used for the worker thread (≈64 MiB). */
    private static final int DEFAULT_THREAD_STACK_SIZE = 1 << 26;

    public static void main(String[] args) {
        Thread worker = new Thread(null, new Runnable() {
            @Override
            public void run() {
                solve();
            }
        }, "MainSolver", DEFAULT_THREAD_STACK_SIZE);
        worker.start();
    }

    /** Contains the whole solving process. */
    private void solve() {
        // try‑with‑resources guarantees proper closing of streams
        try (FastScanner scanner = new FastScanner(System.in);
             PrintWriter out = new PrintWriter(System.out)) {

            new PathFinder(scanner).execute();
        }
    }

    /** --------------------------------------------------------------
     *  Core algorithm – reads the grid, runs Dijkstra from the exit,
     *  then sums all reachable digits whose distance does not exceed
     *  the distance from the start cell.
     *  --------------------------------------------------------------
     */
    private static class PathFinder {

        private final FastScanner in;
        private char[][] grid;
        private final int rows;
        private final int cols;
        private final int[][] distance;          // distance from the exit ('E')
        private final int[] start = new int[2];    // row, col of 'S'
        private final int[] exit  = new int[2];    // row, col of 'E'

        PathFinder(FastScanner in) {
            this.in = in;
        }

        /** Reads input data, builds the grid and locates 'S' and 'E'. */
        private void readInput() {
            rows = in.scanInt();
            cols = in.scanInt();
            grid = new char[rows][];
            distance = new int[rows][cols];

            for (int r = 0; r < rows; ++r) {
                grid[r] = in.scanString().toCharArray();
            }
        }

        /** Marks the coordinates of the start and exit cells. */
        private void locateSymbols() {
            for (int r = 0; r < rows; ++r) {
                for (int c = 0; c < cols; ++c) {
                    char cell = grid[r][c];
                    if (cell == 'S') {
                        start[0] = r;
                        start[1] = c;
                    } else if (cell == 'E') {
                        exit[0] = r;
                        exit[1] = c;
                    }
                }
            }
        }

        /** Executes the whole solving pipeline. */
        private void execute() {
            readInput();
            locateSymbols();
            int endDistance = dijkstra(exit[0], exit[1]);
            long answer = collectDigits(endDistance);
            out.println(answer);
        }

        /** Classic Dijkstra (all edges weight = 1) starting from (sr, sc). */
        private int dijkstra(int sr, int sc) {
            int visits = 0;
            PriorityQueue<Node> pq = new PriorityQueue<>();
            pq.add(new Node(sr, sc, 0));

            // initialise distances to “infinite”
            for (int[] row : distance) {
                Arrays.fill(row, Integer.MAX_VALUE);
            }

            boolean[][] visited = new boolean[rows][cols];

            while (!pq.isEmpty()) {
                Node cur = pq.poll();
                ++visits;

                if (visited[cur.r][cur.c]) {
                    continue;
                }
                visited[cur.r][cur.c] = true;
                distance[cur.r][cur.c] = cur.dis;

                for (int[] dir : DIRECTIONS) {
                    int nr = cur.r + dir[0];
                    int nc = cur.c + dir[1];
                    if (isValid(nr, nc) && !visited[nr][nc]) {
                        pq.add(new Node(nr, nc, cur.dis + 1));
                    }
                }
            }
            return visits;
        }

        /** Whether (r,c) lies inside the grid and is not an obstacle ('T'). */
        private boolean isValid(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols && grid[r][c] != 'T';
        }

        /** Sums all digit cells whose distance from the exit does not exceed
         *  the distance from the start cell. */
        private long collectDigits(int maxDist) {
            long sum = 0;
            for (int r = 0; r < rows; ++r) {
                for (int c = 0; c < cols; ++c) {
                    char ch = grid[r][c];
                    if (Character.isDigit(ch) && distance[r][c] <= maxDist) {
                        sum += ch - '0';
                    }
                }
            }
            return sum;
        }

        /** Four orthogonal movement directions. */
        private static final int[][] DIRECTIONS = {
                {1, 0}, {-1, 0}, {0, 1}, {0, -1}
        };

        /** Simple node used in the priority queue – implements Comparable by distance. */
        private static final class Node implements Comparable<Node> {
            final int r;
            final int c;
            final int dis;          // distance from the source of Dijkstra

            Node(int r, int c, int dis) {
                this.r = r;
                this.c = c;
                this.dis = dis;
            }

            @Override
            public int compareTo(Node o) {
                return Integer.compare(this.dis, o.dis);
            }
        }
    }

    /** --------------------------------------------------------------
     *  Very small, fast scanner that works with raw bytes.
     *  --------------------------------------------------------------
     */
    private static final class FastScanner {

        private final byte[] buffer = new byte[1 << 12];
        private int pos = 0, len = 0;
        private final InputStream in;

        FastScanner(InputStream in) {
            this.in = in;
        }

        private int readByte() {
            if (pos >= len) {
                pos = 0;
                len = in.read(buffer);
                if (len <= 0) {
                    return -1;
                }
            }
            return buffer[pos++];
        }

        private boolean isWhite(int b) {
            return b == ' ' || b == '\n' || b == '\r' || b == '\t' || b == -1;
        }

        /** Reads a 32‑bit signed integer. */
        int scanInt() {
            int c;
            do {
                c = readByte();
            } while (isWhite(c));

            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = readByte();
            }

            int value = 0;
            while (!isWhite(c) && c != -1) {
                if (c >= '0' && c <= '9') {
                    value = value * 10 + (c - '0');
                }
                c = readByte();
            }
            return sign * value;
        }

        /** Reads a non‑whitespace token (used for the grid rows). */
        String scanString() {
            int c;
            do {
                c = readByte();
            } while (isWhite(c));

            StringBuilder sb = new StringBuilder();
            while (!isWhite(c) && c != -1) {
                sb.append((char) c);
                c = readByte();
            }
            return sb.toString();
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Refactored solution for the “CF” problem.
 * <p>
 * The program reads a grid, performs a breadth‑first search from the exit cell
 * (‘E’) to compute distances, and then sums the numeric values of cells that are
 * reachable within a distance not greater than the distance from the start cell
 * (‘S’) to the exit.  All variable names, methods and responsibilities have been
 * reorganised to improve readability and maintainability.
 */
public class Solution {

    /* ----------------------------------------------------------- */
    /* ---------------------------  Data  ------------------------ */
    /* ----------------------------------------------------------- */

    /** Simple immutable position holder used throughout the code. */
    private static final class Position {
        final int row;
        final int col;

        Position(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }

    /** Directions used for BFS – up, down, left, right. */
    private static final int[][] DIRECTIONS = {
            {1, 0},   // down
            {-1, 0},  // up
            {0, 1},   // right
            {0, -1}   // left
    };

    /** Constants representing cell types in the grid. */
    private static final char WALL    = 'T';
    private static final char EXIT    = 'E';
    private static final char START   = 'S';

    /* ----------------------------------------------------------- */
    /* ---------------------------  Main  ------------------------ */
    /* ----------------------------------------------------------- */

    public static void main(String[] args) throws IOException {
        /* Try‑with‑resources guarantees proper closure of streams. */
        try (InputReader reader = new InputReader(System.in);
             PrintWriter out = new PrintWriter(System.out)) {

            int rows = reader.nextInt();
            int cols = reader.nextInt();

            char[][] grid = new char[rows][];
            Position door = null;
            Position player = null;

            /* --------------------------------------------------- */
            /*   Read the grid and locate the exit and start cells   */
            /* --------------------------------------------------- */
            for (int r = 0; r < rows; r++) {
                String line = reader.next();
                grid[r] = line.toCharArray();
                for (int c = 0; c < cols; c++) {
                    if (grid[r][c] == EXIT) {
                        door = new Position(r, c);
                    } else if (grid[r][c] == START) {
                        player = new Position(r, c);
                    }
                }
            }

            /* --------------------------------------------------- */
            /*   BFS from the exit to obtain distances to every cell */
            /* --------------------------------------------------- */
            int[][] distanceFromDoor = bfs(grid, door, rows, cols);

            /* --------------------------------------------------- */
            /*   Compute the required sum according to the original  */
            /*   specification (distance‑based condition)          */
            /* --------------------------------------------------- */
            long answer = sumValidNumbers(
                    grid,
                    distanceFromDoor,
                    player,
                    door,
                    rows,
                    cols);

            out.println(answer);
        }
    }

    /* ----------------------------------------------------------- */
    /* ---------------------------  BFS  -------------------------- */
    /* ----------------------------------------------------------- */

    /**
     * Performs a breadth‑first search starting from {@code start}.
     *
     * @param grid    the character grid
     * @param start   starting position (the exit)
     * @param rows    number of rows in the grid
     * @param cols    number of columns in the grid
     * @return a 2‑D array where each entry holds the distance from {@code start}
     *         or -1 if the cell is unreachable or a wall.
     */
    private static int[][] bfs(char[][] grid, Position start, int rows, int cols) {
        int[][] dist = new int[rows][cols];
        for (int[] row : dist) Arrays.fill(row, -1);

        Queue<Position> queue = new ArrayDeque<>();
        queue.add(start);
        dist[start.row][start.col] = 0;

        while (!queue.isEmpty()) {
            Position cur = queue.poll();

            for (int[] dir : DIRECTIONS) {
                int nr = cur.row + dir[0];
                int nc = cur.col + dir[1];
                if (isInBounds(nr, nc, rows, cols)
                        && grid[nr][nc] != WALL
                        && dist[nr][nc] == -1) {
                    dist[nr][nc] = dist[cur.row][cur.col] + 1;
                    queue.add(new Position(nr, nc));
                }
            }
        }
        return dist;
    }

    /** Utility method that checks whether a cell lies inside the grid. */
    private static boolean isInBounds(int r, int c, int rows, int cols) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    /* ----------------------------------------------------------- */
    /* ---------------  Result calculation logic  ---------------- */
    /* ----------------------------------------------------------- */

    /**
     * Calculates the sum of numeric characters in cells that satisfy the
     * problem’s distance condition.
     *
     * @param grid        the input grid
     * @param distanceFromDoor  distances computed by BFS
     * @param player      position of the start cell (‘S’)
     * @param door        position of the exit cell (‘E’)
     * @param rows        grid row count
     * @param cols        grid column count
     * @return the computed sum
     */
    private static long sumValidNumbers(char[][] grid,
                                         int[][] distanceFromDoor,
                                         Position player,
                                         Position door,
                                         int rows,
                                         int cols) {
        long sum = 0;
        int playerDist = distanceFromDoor[player.row][player.col];

        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                /* Skip the player and door cells themselves */
                if ((r == player.row && c == player.col) ||
                        (r == door.row && c == door.col)) {
                    continue;
                }

                /* Only consider reachable (non‑wall) cells */
                if (distanceFromDoor[r][c] == -1) {
                    continue;
                }

                /* Apply the distance condition */
                if (distanceFromDoor[r][c] <= playerDist) {
                    char ch = grid[r][c];
                    if (Character.isDigit(ch)) {
                        sum += ch - '0';
                    }
                }
            }
        }
        return sum;
    }

    /* ----------------------------------------------------------- */
    /* ------------------------  Input  --------------------------- */
    /* ----------------------------------------------------------- */

    /**
     * Simple wrapper around {@link BufferedReader} that tokenises input lines.
     */
    private static class InputReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        InputReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
        }

        /** Reads the next token, expanding the tokenizer as needed. */
        String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Solves the “labyrinth” problem:
 *   • reads a grid containing 'S' (start), 'E' (end), 'T' (blocked) and digits,
 *   • finds the length of the shortest path from start to end,
 *   • sums all digit cells that lie on any shortest path,
 *   • outputs the sum.
 *
 * The implementation is deliberately split into small, reusable pieces
 * to make the code easier to understand, test and maintain.
 */
public class LabyrinthSolver {

    /** Directions used for the breadth‑first search. */
    private static final int[][] DIRS = {
            {-1, 0}, {1, 0}, {0, -1}, {0, 1}
    };

    /** Represents a cell in the grid. */
    private static final class Cell {
        final int row;
        final int col;

        Cell(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }

    /** Simple holder for the input parameters. */
    private static final class ProblemData {
        final char[][] grid;
        final int rows;
        final int cols;
        final int startRow, startCol;
        final int endRow,   endCol;

        ProblemData(char[][] grid, int rows, int cols,
                    int startRow, int startCol,
                    int endRow,   int endCol) {
            this.grid = grid;
            this.rows = rows;
            this.cols = cols;
            this.startRow = startRow;
            this.startCol = startCol;
            this.endRow = endRow;
            this.endCol = endCol;
        }
    }

    /** Entry point. */
    public static void main(String[] args) throws IOException {
        try (BufferedReader reader = new BufferedReader(
                new InputStreamReader(System.in));
             PrintWriter writer = new PrintWriter(System.out)) {

            ProblemData data = readInput(reader);
            int[][] distanceFromEnd = bfsFrom(data.grid, data.endRow, data.endCol);
            int shortestPathLength = data.distanceFromStart[data.endRow][data.endCol];

            int sumOfDigits = collectDigitsOnShortestPaths(
                    data.grid,
                    distanceFromEnd,
                    shortestPathLength);

            writer.println(sumOfDigits);
        }
    }

    /** Reads the whole input and builds a {@link ProblemData} instance. */
    private static ProblemData readInput(BufferedReader reader) throws IOException {
        String[] firstLine = reader.readLine().split("\\s+");
        int rows = Integer.parseInt(firstLine[0]);
        int cols = Integer.parseInt(firstLine[1]);

        char[][] grid = new char[rows][cols];
        int startRow = -1, startCol = -1;
        int endRow = -1,   endCol = -1;

        for (int r = 0; r < rows; ++r) {
            String line = reader.readLine();
            for (int c = 0; c < cols; ++c) {
                char ch = line.charAt(c);
                grid[r][c] = ch;
                if (ch == 'S') {
                    startRow = r;
                    startCol = c;
                } else if (ch == 'E') {
                    endRow = r;
                    endCol = c;
                }
            }
        }

        if (startRow < 0 || endRow < 0) {
            throw new IllegalArgumentException("Start ('S') or End ('E') not found in input.");
        }

        // BFS from the start cell is required only to obtain the length
        // of the shortest path – we store it in a dedicated array.
        int[][] distanceFromStart = new int[rows][cols];
        bfs(data.grid, startRow, startCol, distanceFromStart);

        return new ProblemData(grid, rows, cols,
                startRow, startCol,
                endRow,   endCol);
    }

    /**
     * Executes a breadth‑first search from the given cell.
     *
     * @param grid        the maze representation
     * @param srcRow      starting row
     * @param srcCol      starting column
     * @param dist        matrix that will receive distances (0 = unvisited)
     */
    private static void bfs(char[][] grid, int srcRow, int srcCol, int[][] dist) {
        int rows = grid.length;
        int cols = grid[0].length;

        Queue<Cell> queue = new ArrayDeque<>();
        queue.add(new Cell(srcRow, srcCol));
        dist[srcRow][srcCol] = 1;               // mark as visited with distance 1

        while (!queue.isEmpty()) {
            Cell cur = queue.poll();
            int curDist = dist[cur.row][cur.col];

            for (int[] dir : DIRS) {
                int nr = cur.row + dir[0];
                int nc = cur.col + dir[1];

                if (!inBounds(nr, nc, rows, cols)) continue;
                if (grid[nr][nc] == 'T') continue;               // blocked cell
                if (dist[nr][nc] != 0) continue;                  // already visited

                dist[nr][nc] = curDist + 1;
                queue.add(new Cell(nr, nc));
            }
        }
    }

    /** Convenience wrapper over the generic BFS that also returns the distance matrix. */
    private static int[][] bfsFrom(char[][] grid, int startRow, int startCol) {
        int rows = grid.length;
        int cols = grid[0].length;
        int[][] dist = new int[rows][cols];
        Arrays.fill(dist, 0);
        bfs(grid, startRow, startCol, dist);
        return dist;
    }

    /**
     * Collects all digits that lie on any shortest path from start to end.
     *
     * The original algorithm added a digit if it could be reached from the end
     * within a distance that does not exceed the length of the shortest overall
     * path (i.e., `used[i][j] <= shortcut && used[i][j] > 0`).
     *
     * @param grid        the maze
     * @param distanceFromEnd  distances filled by BFS started at the end cell
     * @param shortestPathLength length of the shortest path from start to end
     * @return sum of the digit values that satisfy the condition
     */
    private static int collectDigitsOnShortestPaths(char[][] grid,
                                                    int[][] distanceFromEnd,
                                                    int shortestPathLength) {
        int sum = 0;
        for (int r = 0; r < grid.length; ++r) {
            for (int c = 0; c < grid[r].length; ++c) {
                char cell = grid[r][c];
                if (Character.isDigit(cell) &&
                        distanceFromEnd[r][c] <= shortestPathLength &&
                        distanceFromEnd[r][c] > 0) {
                    sum += cell - '0';
                }
            }
        }
        return sum;
    }

    /** Checks whether a given cell is inside the grid boundaries. */
    private static boolean inBounds(int row, int col, int rows, int cols) {
        return row >= 0 && row < rows && col >= 0 && col < cols;
    }
}

package com.example;

/*
 * Main entry point.
 * Reads a grid, finds the start cell 'S' and the exit cell 'E',
 * performs a breadth‑first search from 'E' and sums all digit cells
 * that are reachable and whose distance does not exceed the distance
 * of 'S' from 'E'.
 */
public class Main {

    public static void main(String[] args) {
        try (BufferedReader br = new BufferedReader(
                new InputStreamReader(System.in))) {

            String line;
            // read dimensions (the original code expects two tokens on the first line)
            StringTokenizer tok = new StringTokenizer(br.readLine());
            int rows = Integer.parseInt(tok.nextToken());
            int cols = Integer.parseInt(tok.nextToken());

            char[][] grid = new char[rows][];
            int startR = -1, startC = -1;
            int endR = -1, endC = -1;

            // read the grid line by line
            for (int r = 0; r < rows; r++) {
                String gridLine = br.readLine();
                if (gridLine == null) {
                    throw new IllegalStateException("Unexpected end of input");
                }
                grid[r] = gridLine.toCharArray();
                for (int c = 0; c < cols; c++) {
                    switch (grid[r][c]) {
                        case 'S' -> {
                            startR = r;
                            startC = c;
                        }
                        case 'E' -> {
                            endR = r;
                            endC = c;
                        }
                    }
                }
            }

            // run the BFS from the exit cell
            BfsResult result = new BfsResult(grid, endR, endC);
            int[] distances = result.distances();

            // distance of the start cell from the exit
            int startDistance = distances[result.index(startR, startC)];

            // sum of digits that are reachable and not farther than startDistance
            int answer = result.sumDigitsWithinDistance(distances, startDistance);
            System.out.println(answer);
        } catch (IOException | NumberFormatException e) {
            throw new UncheckedIOException(e);
        }
}

/*
 * Simple generic Pair implementation.
 *
 * @param <F> type of the first component
 * @param <S> type of the second component
 */
final class Pair<F, S> {
    public final F first;
    public final S second;

    public Pair(F first, S second) {
        this.first = first;
        this.second = second;
    }

    @Override
    public boolean equals(Object o) {
        if (this == o) return true;
        if (!(o instanceof Pair<?, ?> other)) return false;
        return Objects.equals(first, other.first) && Objects.equals(second, other.second);
    }

    @Override
    public int hashCode() {
        return Objects.hash(first, second);
    }
}

/*
 * Encapsulates the BFS algorithm that starts from the cell containing 'E'.
 *
 * The class:
 *   • Stores the grid,
 *   • Computes distances from 'E' to every walkable cell,
 *   • Provides utilities to query those distances.
 */
final class BfsResult {

    private final char[][] grid;
    private final int rows;
    private final int cols;

    // four possible movement directions
    private final int[] dx = {1, -1, 0, 0};
    private final int[] dy = {0, 0, 1, -1};

    // distance[i][j] holds the distance from 'E' to cell (i,j); -1 means unreachable
    private final int[][] distance;

    public BfsResult(char[][] grid, int startR, int startC) {
        this.grid = grid;
        this.rows = grid.length;
        this.cols = grid[0].length;
        this.distance = new int[rows][cols];
        for (int[] row : distance) {
            Arrays.fill(row, -1);
        }
        performBfs(startR, startC);
    }

    /** Executes BFS starting from (startR,startC). */
    private void performBfs(int startR, int startC) {
        Queue<Pair<Integer, Integer>> queue = new ArrayDeque<>();
        queue.add(new Pair<>(startR, startC));
        distance[startR][startC] = 0;

        while (!queue.isEmpty()) {
            Pair<Integer, Integer> cur = queue.poll();
            int r = cur.first;
            int c = cur.second;

            for (int dir = 0; dir < 4; dir++) {
                int nr = r + dx[dir];
                int nc = c + dy[dir];
                if (isInBounds(nr, nc)
                        && canWalk(nr, nc)
                        && distance[nr][nc] == -1) {
                    distance[nr][nc] = distance[r][c] + 1;
                    queue.add(new Pair<>(nr, nc));
                }
            }
        }
    }

    private boolean isInBounds(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    private boolean canWalk(int r, int c) {
        return grid[r][c] != 'T';
    }

    /**
     * Returns a flattened view of the {@code distance} matrix.
     * The order matches the row‑major traversal of the matrix.
     */
    public int[] distances() {
        int[] flat = new int[rows * cols];
        int idx = 0;
        for (int[] row : distance) {
            for (int d : row) {
                flat[idx++] = d;
            }
        }
        return flat;
    }

    /**
     * Returns the index of a cell in the flattened distance array.
     * Used to retrieve the distance of a particular (r,c) location.
     */
    public int index(int r, int c) {
        return r * cols + c;
    }

    /**
     * Sums all numeric cells that:
     *   • are reachable from 'E' (distance != -1),
     *   • are not farther than {@code maxDist} from 'E',
     *   • and contain a digit character.
     *
     * @param flatDistances   the flattened distance array returned by {@link #distances()}
     * @param maxDist         the maximum allowed distance (typically the distance of 'S')
     * @return sum of those digit values
     */
    public int sumDigitsWithinDistance(int[] flatDistances, int maxDist) {
        int answer = 0;
        int idx = 0;
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                int d = flatDistances[idx++];
                char ch = grid[r][c];
                if (Character.isDigit(ch) && d != -1 && d <= maxDist) {
                    answer += ch - '0';
                }
            }
        }
        return answer;
    }
}

package solution;

import java.io.*;
import java.util.ArrayDeque;
import java.util.Arrays;
import java.util.Queue;

/**
 * Refactored version of the original B‑problem solution.
 * The logic remains identical but the implementation is
 * more readable, maintainable and type‑safe.
 */
public class Main {

    /** Directions: right, left, down, up */
    private static final int[][] DIRS = {{0, 1}, {0, -1}, {1, 0}, {-1, 0}};

    /** Small wrapper for a grid cell coordinate */
    private static final class Node {
        final int row;
        final int col;

        Node(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }

    /** Reads all input; optionally redirects from a file named "b.in". */
    private static BufferedReader openInputReader() throws IOException {
        InputStream source = System.in;
        File file = new File("b.in");
        if (file.exists() && file.canRead()) {
            source = new FileInputStream(file);
        }
        return new BufferedReader(new InputStreamReader(source));
    }

    /** Utility container for simple token handling. */
    private static final class InputReader {
        private final BufferedReader br;
        private StringTokenizer st;

        InputReader(BufferedReader br) {
            this.br = br;
        }

        /** Returns the next token or {@code null} on EOF. */
        private String nextToken() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                String line = br.readLine();
                if (line == null) {
                    return null;
                }
                st = new StringTokenizer(line);
            }
            return st.nextToken();
        }

        /** Convenience wrapper around nextInt(). */
        int nextInt() throws IOException {
            return Integer.parseInt(nextToken());
        }

        /** Reads a whole grid of size {@code rows × cols}. */
        char[][] readGrid(int rows) throws IOException {
            char[][] grid = new char[rows][];
            for (int i = 0; i < rows; i++) {
                String line = br.readLine();
                if (line == null) {
                    throw new IOException("Unexpected end of input while reading grid");
                }
                grid[i] = line.toCharArray();
            }
            return grid;
        }
    }

    /** Finds the coordinates of a given character in a grid. */
    private static int[] locateChar(char[][] grid, char target) {
        for (int r = 0; r < grid.length; r++) {
            for (int c = 0; c < grid[r].length; c++) {
                if (grid[r][c] == target) {
                    return new int[]{r, c};
                }
            }
        }
        return null;
    }

    /** Breadth‑first search from {@code startRow/startCol} filling {@code distance}. */
    private static int bfs(char[][] grid, int startRow, int startCol,
                           int[][] distance) {
        final int rows = grid.length;
        final int cols = grid[0].length;

        Queue<Node> queue = new ArrayDeque<>();
        queue.add(new Node(startRow, startCol));
        distance[startRow][startCol] = 0;

        while (!queue.isEmpty()) {
            Node cur = queue.poll();
            int r = cur.row;
            int c = cur.col;

            for (int[] d : DIRS) {
                int nr = r + d[0];
                int nc = c + d[1];

                if (outOfBounds(nr, nc, rows, cols) || grid[nr][nc] == 'T') {
                    continue;
                }
                if (distance[nr][nc] != -1) {
                    continue;               // already visited
                }

                distance[nr][nc] = distance[r][c] + 1;
                queue.add(new Node(nr, nc));
            }
        }
        // Return the distance of the start cell; -1 would mean unreachable.
        return distance[startRow][startCol];
    }

    /** Simple bounds check. */
    private static boolean outOfBounds(int nr, int nc, int rows, int cols) {
        return nr < 0 || nr >= rows || nc < 0 || nc >= cols;
    }

    /** Core solving routine – mirrors the original algorithm but with clearer flow. */
    private static void solve() throws IOException {
        // -----------------------------------------------------------------
        // 1️⃣  Input handling (file redirection optional)
        // -----------------------------------------------------------------
        try (BufferedReader reader = openInputReader()) {
            InputReader in = new InputReader(reader);
            int rows = in.nextInt();
            int cols = in.nextInt();

            char[][] grid = in.readGrid(rows);

            // -----------------------------------------------------------------
            // 2️⃣  Locate the exit ('E') and compute distances from it.
            // -----------------------------------------------------------------
            int[] exitPos = locateChar(grid, 'E');
            if (exitPos == null) {
                throw new IllegalArgumentException("No 'E' found in the grid");
            }

            int[][] distance = new int[rows][cols];
            for (int[] row : distance) {
                Arrays.fill(row, -1);
            }
            int ourDistance = bfs(grid, exitPos[0], exitPos[1], distance);

            // -----------------------------------------------------------------
            // 3️⃣  Locate the start position ('S') and obtain its distance.
            // -----------------------------------------------------------------
            int startRow = -1, startCol = -1;
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (grid[i][j] == 'S') {
                        startRow = i;
                        startCol = j;
                        break;
                    }
                }
                if (startRow != -1) {
                    break;
                }
            }
            if (startRow == -1) {
                throw new IllegalArgumentException("Start 'S' not found in the grid");
            }
            ourDistance = distance[startRow][startCol];
            // If the start is unreachable we treat its distance as "infinite"
            // (the original code never considered such a case).
            if (ourDistance < 0) {
                ourDistance = Integer.MAX_VALUE;
            }

            // -----------------------------------------------------------------
            // 4️⃣  Sum all digits whose distance is within our reachable radius.
            // -----------------------------------------------------------------
            int fightSum = 0;
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (distance[i][j] >= 0 && distance[i][j] <= ourDistance) {
                        char ch = grid[i][j];
                        if (ch >= '0' && ch <= '9') {
                            fightSum += ch - '0';
                        }
                    }
                }
            }

            // -----------------------------------------------------------------
            // 5️⃣  Output the result.
            // -----------------------------------------------------------------
            System.out.println(fightSum);
        }
    }

    /** Entry point – simply delegates to {@link #solve()}. */
    public static void main(String[] args) throws IOException {
        solve();
    }
}

import java.io.*;
import java.util.*;

/**
 * Main class – entry point for the program.
 *
 * <p>This refactor improves readability, separates concerns and follows common Java naming
 * conventions. The algorithm itself (a BFS that walks the grid from the 'E' cells) is kept
 * unchanged, but the code is now easier to understand and maintain.
 */
public class Solution {

    /** Marker for an unvisited cell in the {@code visited} matrix. */
    private static final int UNVISITED = 0;

    /** Simple queue wrapper used by the BFS. */
    private static final class Node {
        final int row;
        final int col;
        final int distance;

        Node(int row, int col, int distance) {
            this.row = row;
            this.col = col;
            this.distance = distance;
        }
    }

    /** --------------------------------------------------------------------- */
    /** Program entry point. */
    public static void main(String[] args) throws IOException {
        // The original program only processes a single test case (t = 1).
        try (PrintWriter out = new PrintWriter(System.out);
             ScannerLikeReader in = new ScannerLikeReader()) {

            final int TEST_CASES = 1;
            for (int i = 0; i < TEST_CASES; i++) {
                solve(in, out);
            }
            out.flush();
        }
    }

    /** --------------------------------------------------------------------- */
    /** Core BFS routine that solves one test case. */
    private static void solve(ScannerLikeReader in, PrintWriter out) {
        int rows = in.nextInt();   // number of rows
        int cols = in.nextInt();   // number of columns

        char[][] grid = new char[rows][];
        int startRow = -1, startCol = -1;

        Queue<Node> queue = new ArrayDeque<>();

        // Read the grid and locate all 'E' cells (enqueue them) and the start cell.
        for (int i = 0; i < rows; i++) {
            String line = in.nextLine().trim();               // consume the whole line
            grid[i] = line.toCharArray();
            for (int j = 0; j < cols; j++) {
                char cell = grid[i][j];
                if (cell == 'E') {
                    queue.add(new Node(i, j, 0));           // start points for BFS
                } else if (cell == 'S') {
                    startRow = i;
                    startCol = j;
                }
            }
        }

        int[][] visited = new int[rows][cols];
        int answer = 0;
        boolean startReached = false;

        // Direction vectors for the four possible moves.
        final int[] dr = {1, -1, 0, 0};
        final int[] dc = {0, 0, 1, -1};

        while (!queue.isEmpty()) {
            Node cur = queue.poll();
            int r = cur.row;
            int c = cur.col;
            int dist = cur.distance;

            // Skip already processed cells.
            if (visited[r][c] != UNVISITED) {
                continue;
            }
            visited[r][c] = dist;

            // Detect the start cell.
            if (grid[r][c] == 'S') {
                startReached = true;
            }

            // Accumulate numeric cell values.
            char val = grid[r][c];
            if (val >= '0' && val <= '9') {
                answer += val - '0';
            }

            // Termination condition from the original code: once the start cell has been
            // visited and we later encounter a cell whose distance is larger than the start
            // cell's distance, we stop the BFS.
            if (startReached && visited[r][c] > visited[startRow][startCol]) {
                break;
            }

            // Explore neighbours (up, down, left, right) – ignore 'T' and 'E' cells.
            for (int dir = 0; dir < 4; dir++) {
                int nr = r + dr[dir];
                int nc = c + dc[dir];
                if (nr < 0 || nr >= rows || nc < 0 || nc >= cols) {
                    continue;                                   // out of bounds
                }
                if (visited[nr][nc] != UNVISITED) {
                    continue;                                   // already visited
                }
                char neighbour = grid[nr][nc];
                if (neighbour == 'T' || neighbour == 'E') {
                    continue;                                   // forbidden cells
                }
                queue.add(new Node(nr, nc, dist + 1));
            }
        }

        out.println(answer);
    }

    /** --------------------------------------------------------------------- */
    /** Very similar to the original {@code FastReader} – provides quick access to tokens. */
    private static final class ScannerLikeReader {
        private final BufferedReader br;
        private StringTokenizer st;

        ScannerLikeReader() {
            this.br = new BufferedReader(new InputStreamReader(System.in));
        }

        /** Returns the next token, reading a new line if necessary. */
        String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    throw new UncheckedIOException(e);
                }
            }
            return st.nextToken();
        }

        /** Convenience wrappers for primitive types. */
        int nextInt()               { return Integer.parseInt(next()); }
        long nextLong()             { return Long.parseLong(next()); }
        double nextDouble()         { return Double.parseDouble(next()); }
        boolean nextBoolean()       { return Boolean.parseBoolean(next()); }

        /** Returns the next whole line. */
        String nextLine() {
            try {
                return br.readLine();
            } catch (IOException e) {
                throw new UncheckedIOException(e);
            }
        }
    }
}

import java.io.*;
import java.util.*;

public class Solution {

    /* --------------------------------------------------------------------- */
    /*  Constants that describe the labyrinth characters                     */
    /* --------------------------------------------------------------------- */
    private static final char WALL      = 'T'; // blocked cell
    private static final char ENTRY     = 'E'; // starting point(s) for BFS
    private static final char START     = 'S'; // target cell, distance is measured to it
    private static final int INVALID_DIST = -1; // marker for “not visited / unreachable”

    public static void main(String[] args) {
        // try‑with‑resources guarantees that streams are closed even on error
        try (InputStream in = System.in;
             OutputStream out = System.out) {

            InputReader reader   = new InputReader(in);
            PrintWriter   writer = new PrintWriter(out, true); // auto‑flush

            LabyrinthSolver solver = new LabyrinthSolver();
            solver.solve(reader, writer);
        }
    }
}

/* --------------------------------------------------------------------- */
/*  Simple input parser – reads tokens from System.in                     */
/* --------------------------------------------------------------------- */
class InputReader {
    private final BufferedReader reader;
    private StringTokenizer tokenizer;   // reused across calls

    InputReader(InputStream stream) {
        this.reader = new BufferedReader(new InputStreamReader(stream));
    }

    /** Returns the next token from the input stream. */
    String next() {
        while (tokenizer == null || !tokenizer.hasMoreTokens()) {
            try {
                tokenizer = new StringTokenizer(reader.readLine());
            } catch (IOException e) {
                throw new UncheckedIOException(e);
            }
        }
        return tokenizer.nextToken();
    }

    /** Convenience wrapper for reading an int. */
    int nextInt() {
        return Integer.parseInt(next());
    }
}

/* --------------------------------------------------------------------- */
/*  Core algorithm – BFS from all entrances, then aggregate digit sums   */
/* --------------------------------------------------------------------- */
class LabyrinthSolver {

    /**
     * Entry point required by the original `TaskB` contract.
     *
     * @param reader  token stream parser
     * @param out     output stream wrapper that writes the answer
     */
    public void solve(InputReader reader, PrintWriter out) {
        int rows = reader.nextInt();
        int cols = reader.nextInt();

        char[][] grid = readGrid(reader, rows);

        int[][] distances = bfsFromAllEntries(grid, rows, cols);

        int maxDistToStart = locateFirstStartDistance(distances, grid);
        int answer         = sumDigitsWithinReachableDistance(distances, grid, maxDistToStart);

        out.println(answer);
    }

    /** Reads the whole labyrinth into a 2‑D character array. */
    private char[][] readGrid(InputReader reader, int rows) {
        char[][] grid = new char[rows][];
        for (int r = 0; r < rows; r++) {
            grid[r] = reader.next().toCharArray();
        }
        return grid;
    }

    /**
     * Breadth‑first search starting from every cell that contains {@code ENTRY}.
     *
     * @return a distance matrix; {@code INVALID_DIST} marks walls or unreachable cells.
     */
    private int[][] bfsFromAllEntries(char[][] grid, int rows, int cols) {
        int[][] dist = new int[rows][cols];
        for (int[] row : dist) {
            Arrays.fill(row, INVALID_DIST);
        }

        int[] qRows = new int[rows * cols];
        int[] qCols = new int[rows * cols];
        int head = 0, tail = 0;

        // enqueue all entries
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == ENTRY) {
                    qRows[tail] = r;
                    qCols[tail] = c;
                    dist[r][c] = 0;
                    tail++;
                }
            }
        }

        // four orthogonal directions
        int[] dr = {-1, 1, 0, 0};
        int[] dc = {0, 0, -1, 1};

        while (head < tail) {
            int r = qRows[head];
            int c = qCols[head];
            head++;

            for (int dir = 0; dir < 4; dir++) {
                int nr = r + dr[dir];
                int nc = c + dc[dir];
                if (isInside(nr, cols) && isInside(nc, rows)
                        && grid[nr][nc] != WALL
                        && dist[nr][nc] == INVALID_DIST) {
                    dist[nr][nc] = dist[r][c] + 1;
                    qRows[tail] = nr;
                    qCols[tail] = nc;
                    tail++;
                }
            }
        }
        return dist;
    }

    /** Returns the distance of the first {@code START} cell that is reachable. */
    private int locateFirstStartDistance(int[][] distances, char[][] grid) {
        int maxDist = 0;
        for (int r = 0; r < distances.length; r++) {
            for (int c = 0; c < distances[r].length; c++) {
                if (grid[r][c] == START && distances[r][c] != INVALID_DIST) {
                    maxDist = distances[r][c]; // distance of the *first* S found
                }
            }
        }
        return maxDist;
    }

    /** Sums all digit characters whose distance ≤ {@code maxDist}. */
    private int sumDigitsWithinReachableDistance(int[][] distances,
                                                  char[][] grid,
                                                  int maxDist) {
        int sum = 0;
        for (int r = 0; r < distances.length; r++) {
            for (int c = 0; c < distances[r].length; c++) {
                char ch = grid[r][c];
                if (Character.isDigit(ch)
                        && distances[r][c] != INVALID_DIST
                        && distances[r][c] <= maxDist) {
                    sum += ch - '0';
                }
            }
        }
        return sum;
    }

    /** Helper – checks whether an index is inside a dimension of size {@code size}. */
    private boolean isInside(int index, int size) {
        return index >= 0 && index < size;
    }
}

/**
 * BiridianForest – computes the minimal “battles” that must be passed
 * when travelling from the start (S) to the exit (E) while optionally
 * stepping on numeric cells whose distance from the exit does not
 * exceed the shortest‑path distance from start to exit.
 *
 * The refactor focuses on readability, encapsulation and testability:
 *   • All mutable state is confined to a dedicated {@code Forest} class.
 *   • BFS is implemented with a typed {@code Position} wrapper instead of
 *     raw integer queues.
 *   • Magic numbers and field accesses are replaced by expressive names.
 *   • The program follows the standard Java coding conventions.
 */
public class BiridianForest {

    /** Directions used for neighbour exploration (up, left, down, right). */
    private static final int[][] NEIGHBOUR_OFFSETS = {
            {-1, 0}, {0, -1}, {1, 0}, {0, 1}
    };

    /** Represents a grid coordinate. */
    private static final class Position {
        final int row;
        final int col;

        Position(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }

    /** Holds the forest grid and all related logic. */
    private static final class Forest {
        private final char[][] grid;
        private final int rows;
        private final int columns;

        private Position start;
        private Position exit;

        Forest(char[][] grid) {
            this.grid = grid;
            this.rows = grid.length;
            this.columns = grid[0].length;
        }

        /** Finds the coordinates of the start and exit cells. */
        void locateStartAndExit() {
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < columns; c++) {
                    char cell = grid[r][c];
                    if (cell == 'S') {
                        start = new Position(r, c);
                    } else if (cell == 'E') {
                        exit = new Position(r, c);
                    }
                }
            }
        }

        /** Returns the shortest‑path distance from (sr, sc) to every reachable cell. */
        int[][] bfsFrom(int sr, int sc) {
            int[][] distance = new int[rows][columns];
            for (int[] row : distance) {
                Arrays.fill(row, -1);
            }

            Queue<Position> queue = new ArrayDeque<>();
            distance[sr][sc] = 0;
            queue.add(new Position(sr, sc));

            while (!queue.isEmpty()) {
                Position cur = queue.poll();
                for (int[][] offset : NEIGHBOUR_OFFSETS) {
                    int nr = cur.row + offset[0][0];
                    int nc = cur.col + offset[0][1];
                    if (isWithinBounds(nr, nc)
                            && distance[nr][nc] == -1
                            && grid[nr][nc] != 'T') {
                        distance[nr][nc] = distance[cur.row][cur.col] + 1;
                        queue.add(new Position(nr, nc));
                    }
                }
            }
            return distance;
        }

        /** Simple bounds check. */
        private boolean isWithinBounds(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < columns;
        }

        /** Returns the minimal battles value required by the problem statement. */
        int computeMinBattles() {
            // 1️⃣ Shortest distance from start to exit.
            int[] startPos = {start.row, start.col};
            int[][] distFromStart = bfsFrom(startPos[0], startPos[1]);
            int exitDistance = distFromStart[exit.row][exit.col];

            // 2️⃣ Shortest distance from exit to every cell.
            int[][] distFromExit = bfsFrom(exit.row, exit.col);

            // 3️⃣ Accumulate numeric cells whose distance from exit
            //    does not exceed the start‑to‑exit distance.
            int battles = 0;
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < columns; c++) {
                    char cell = grid[r][c];
                    int d = distFromExit[r][c];
                    if (cell >= '1' && cell <= '9' &&   // numeric cell
                        d != -1 && d <= exitDistance) {
                        battles += cell - '0';
                    }
                }
            }
            return battles;
        }
    }

    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            int rows = scanner.nextInt();
            int columns = scanner.nextInt();
            scanner.nextLine(); // consume end‑of‑line

            // Build the grid
            char[][] rawGrid = new char[rows][];
            for (int r = 0; r < rows; r++) {
                rawGrid[r] = scanner.nextLine().toCharArray();
            }

            Forest forest = new Forest(rawGrid);
            forest.locateStartAndExit();

            // Output the result
            System.out.println(forest.computeMinBattles());
        }
    }
}

/*
 *  Biridian Forest – refactored version
 *  ---------------------------------------------------------------
 *  This program reads a grid, performs a breadth‑first search from the
 *  end cell ('E') to the start cell ('S'), finds the shortest distance
 *  between them and then sums all numeric cells whose distance from 'E'
 *  is positive, finite and not greater than that shortest distance.
 *
 *  The code has been refactored to improve:
 *   • naming & constants
 *   • separation of concerns (input handling, BFS, result calculation)
 *   • use of proper collection types (Deque)
 *   • elimination of unnecessary static mutable fields
 *   • clearer flow and documentation
 */
public class BirdInForest {

    // -------------------------------------------------------------------------
    //  Direction vectors (north, east, south, west)
    // -------------------------------------------------------------------------
    private static final int[] DY = { -1, 0, 1, 0 };
    private static final int[] DX = { 0, 1, 0, -1 };

    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            int rows = scanner.nextInt();
            int cols = scanner.nextInt();

            GridParser parser = new GridParser(scanner);
            char[][] grid = parser.readGrid(rows, cols);
            Position end   = parser.findCell(grid, 'E');
            Position start = parser.findCell(grid, 'S');

            int[][] distanceFromEnd = BfsCalculator.computeDistances(grid, end);
            Integer shortestPath = BfsCalculator.findShortestPath(distanceFromEnd, start);

            int total = DigitSumCollector.sumDigits(grid, distanceFromEnd, shortestPath);
            System.out.println(total);
        }
    }
}

/**
 * Utility class that encapsulates all parsing logic.
 */
final class GridParser {

    private final Scanner scanner;

    GridParser(Scanner scanner) {
        this.scanner = scanner;
    }

    /**
     * Reads the whole grid from {@link Scanner} and returns it as a char matrix.
     */
    char[][] readGrid(int rows, int cols) {
        char[][] grid = new char[rows][cols];
        for (int r = 0; r < rows; r++) {
            String line = scanner.next();
            for (int c = 0; c < cols; c++) {
                grid[r][c] = line.charAt(c);
            }
        }
        return grid;
    }

    /**
     * Locates the first occurrence of {@code target} in the grid.
     *
     * @throws IllegalArgumentException if the target is not found.
     */
    Position findCell(char[][] grid, char target) {
        for (int r = 0; r < grid.length; r++) {
            for (int c = 0; c < grid[r].length; c++) {
                if (grid[r][c] == target) {
                    return new Position(r, c);
                }
            }
        }
        throw new IllegalArgumentException("Target cell '" + target + "' not found.");
    }
}

/**
 * Encapsulates all breadth‑first‑search related calculations.
 */
final class BfsCalculator {

    private BfsCalculator() { /* utility class – no instances */ }

    /**
     * Performs a BFS starting from {@code source} and fills the supplied
     * {@code distance} matrix with the number of steps needed to reach each
     * reachable cell (unreachable cells stay {@code -1}).
     *
     * @return the filled distance matrix.
     */
    static int[][] computeDistances(char[][] grid, Position source) {
        int rows = grid.length;
        int cols = grid[0].length;
        int[][] distance = new int[rows][cols];
        for (int[] row : distance) {
            java.util.Arrays.fill(row, -1);
        }
        distance[source.row][source.col] = 0;

        java.util.Deque<Integer> queueY = new java.util.ArrayDeque<>();
        java.util.Deque<Integer> queueX = new java.util.ArrayDeque<>();

        queueX.add(source.row);
        queueY.add(source.col);

        while (!queueX.isEmpty()) {
            int x = queueX.pollFirst();
            int y = queueY.pollFirst();

            for (int dir = 0; dir < DIR_COUNT; dir++) {
                int nx = x + DX[dir];
                int ny = y + DY[dir];

                // Boundary check and obstacle check
                if (!isInBounds(nx, ny, rows, cols) || grid[nx][ny] == 'T') {
                    continue;
                }
                if (distance[nx][ny] != -1) { // already visited
                    continue;
                }

                distance[nx][ny] = distance[x][y] + 1;
                queueX.add(nx);
                queueY.add(ny);
            }
        }
        return distance;
    }

    /**
     * Returns the shortest distance from {@code source} to the start cell.
     * The start cell is identified by the known constant 'S'. If such a cell
     * cannot be reached, {@code null} is returned.
     */
    static Integer findShortestPath(int[][] distance, Position start) {
        return distance[start.row][start.col];
    }

    // -----------------------------------------------------------------------
    //  Constants used internally
    // -----------------------------------------------------------------------
    private static final int DIR_COUNT = 4;
}

/**
 * Represents a 2‑D position (row, column) inside the grid.
 */
final class Position {
    final int row;
    final int col;

    Position(int row, int col) {
        this.row = row;
        this.col = col;
    }
}

/**
 * Utility class that collects digit values from cells whose BFS distance
 * satisfies the problem constraints.
 */
final class DigitSumCollector {

    private DigitSumCollector() { /* utility class – no instances */ }

    /**
     * Sums all numeric characters ('0'–'9') in the grid that satisfy:
     *   • distance from the end cell is ≥ 1,
     *   • distance is not -1,
     *   • distance is ≤ shortest‑path distance (if it exists).
     *
     * @return the computed sum.
     */
    static int sumDigits(char[][] grid, int[][] distance, Integer maxDistance) {
        int sum = 0;
        for (int r = 0; r < grid.length; r++) {
            for (int c = 0; c < grid[r].length; c++) {
                int value = grid[r][c] - '0';
                if (value < 0 || value > 9) {
                    continue;                // not a digit
                }
                int d = distance[r][c];
                if (d <= 0 || d == -1) {
                    continue;                // skip start cell and unreachable cells
                }
                if (maxDistance != null && d > maxDistance) {
                    continue;                // outside allowed range
                }
                sum += value;
            }
        }
        return sum;
    }
}

import java.io.*;
import java.util.*;

public class Main {

    /** Directions: down, right, up, left */
    private static final int[] DX = {1, 0, -1, 0};
    private static final int[] DY = {0, 1, 0, -1};

    private static int rows;
    private static int cols;
    private static char[][] grid;
    private static int[][] distance;
    private static boolean[][] visited;

    private static int startX, startY;
    private static int endX, endY;

    public static void main(String[] args) throws IOException {
        /*try (BufferedReader br = ...) – automatic resource closing*/
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
             PrintWriter out = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)))) {

            initialize(br);
            bfs();
            long answer = computeResult();
            out.println(answer);
        }
    }

    /**
     * Reads the grid and identifies the start (S) and end (E) positions.
     */
    private static void initialize(BufferedReader br) throws IOException {
        StringTokenizer st = new StringTokenizer(br.readLine());
        rows = Integer.parseInt(st.nextToken());
        cols = Integer.parseInt(st.nextToken());

        grid       = new char[rows][cols];
        distance   = new int[rows][cols];
        visited    = new boolean[rows][cols];

        for (int i = 0; i < rows; i++) {
            String line = br.readLine();
            for (int j = 0; j < cols; j++) {
                char ch = line.charAt(j);
                grid[i][j] = ch;
                if (ch == 'S') {
                    startX = i;
                    startY = j;
                } else if (ch == 'E') {
                    endX = i;
                    endY = j;
                }
            }
        }

        // Fill distance matrix with a large value; set the end distance to 0
        for (int[] row : distance) {
            Arrays.fill(row, Integer.MAX_VALUE);
        }
        distance[endX][endY] = 0;
    }

    /**
     * Performs a BFS from the end cell to compute the shortest distance
     * from every reachable cell to the end.
     */
    private static void bfs() {
        Queue<int[]> queue = new ArrayDeque<>();
        queue.add(new int[]{endX, endY});
        visited[endX][endY] = true;

        while (!queue.isEmpty()) {
            int[] cur = queue.remove();
            int x = cur[0];
            int y = cur[1];

            for (int dir = 0; dir < 4; dir++) {
                int nx = x + DX[dir];
                int ny = y + DY[dir];
                if (isValid(nx, ny) && !visited[nx][ny] && grid[nx][ny] != 'T') {
                    distance[nx][ny] = distance[x][y] + 1;
                    visited[nx][ny] = true;
                    queue.add(new int[]{nx, ny});
                }
            }
        }
    }

    /** Checks bounds of a cell inside the grid. */
    private static boolean isValid(int x, int y) {
        return x >= 0 && x < rows && y >= 0 && y < cols;
    }

    /**
     * Calculates the required sum:
     * cells other than start/end whose distance to end is not greater
     * than the distance from start to end.
     */
    private static long computeResult() {
        long sum = 0;
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                char c = grid[i][j];
                if (c != 'S' && c != 'E' && distance[i][j] <= distance[startX][startY]) {
                    sum += c - '0';
                }
            }
        }
        return sum;
    }
}

import java.io.*;
import java.util.*;

/**
 * Solution for problem "B".
 *
 * <p>
 *   Reads a grid containing the characters:
 *   <ul>
 *     <li>'S' – start cell</li>
 *     <li>'E' – end cell</li>
 *     <li>'T' – blocked cell</li>
 *     <li>digits '0'‑'9' – cells that contribute to the result</li>
 *   </ul>
 *   Performs a BFS from the end cell to compute distances,
 *   then sums all digit cells whose distance is not greater than the distance
 *   from the start cell to the end cell.
 * </p>
 */
public class B {

    /** Directions: up, right, left, down */
    private static final int[] DX = {-1, 0, 0, 1};
    private static final int[] DY = {0, 1, -1, 0};

    /** Grid dimensions and data */
    private static int rows;
    private static int cols;
    private static char[][] grid;

    /** Positions of the start and end cells */
    private static int startRow, startCol;
    private static int endRow, endCol;

    /** Distance from the end cell to every other reachable cell */
    private static int[][] distance;

    /** Entry point */
    public static void main(String[] args) throws IOException {
        FastScanner fs = new FastScanner(System.in);
        readInput(fs);
        bfsFromEnd();
        int maxDistance = distance[startRow][startCol];
        int result = sumDigitsWithin(maxDistance);
        System.out.println(result);
    }

    /** Reads the whole input and builds the grid representation. */
    private static void readInput(FastScanner fs) {
        rows = fs.nextInt();
        cols = fs.nextInt();
        grid = new char[rows][cols];

        for (int i = 0; i < rows; i++) {
            String line = fs.next();
            System.arraycopy(line.toCharArray(), 0, grid[i], 0, cols);
            for (int j = 0; j < cols; j++) {
                char c = grid[i][j];
                if (c == 'S') {
                    startRow = i;
                    startCol = j;
                } else if (c == 'E') {
                    endRow = i;
                    endCol = j;
                }
            }
        }
    }

    /** Breadth‑first search starting from the end cell, filling the distance matrix. */
    private static void bfsFromEnd() {
        distance = new int[rows][cols];
        for (int[] row : distance) {
            Arrays.fill(row, -1);
        }

        Queue<int[]> queue = new ArrayDeque<>();
        queue.add(new int[]{endRow, endCol});
        distance[endRow][endCol] = 0;

        while (!queue.isEmpty()) {
            int[] cur = queue.poll();
            int x = cur[0];
            int y = cur[1];
            for (int dir = 0; dir < 4; dir++) {
                int nx = x + DX[dir];
                int ny = y + DY[dir];
                if (isInside(nx, ny) && canTraverse(nx, ny) && distance[nx][ny] == -1) {
                    distance[nx][ny] = distance[x][y] + 1;
                    queue.add(new int[]{nx, ny});
                }
            }
        }
    }

    /** Returns true if a cell can be entered (i.e., it is not a wall 'T'). */
    private static boolean canTraverse(int x, int y) {
        return grid[x][y] != 'T';
    }

    /** Calculates the sum of numeric characters whose distance is ≤ the start‑cell distance. */
    private static int sumDigitsWithin(int maxDist) {
        int sum = 0;
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                int d = distance[i][j];
                if (d != -1 && d <= maxDist &&
                    grid[i][j] >= '0' && grid[i][j] <= '9' &&
                    !(grid[i][j] == 'S' || grid[i][j] == 'E')) {
                    sum += grid[i][j] - '0';
                }
            }
        }
        return sum;
    }

    /** Utility class for fast tokenized input. */
    private static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner(InputStream source) {
            br = new BufferedReader(new InputStreamReader(source));
        }

        /** Returns the next token, reading a new line if necessary. */
        private String next() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                String line = br.readLine();
                if (line == null) {
                    return null;
                }
                st = new StringTokenizer(line);
            }
            return st.nextToken();
        }

        /** Reads the next integer token. */
        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }

    /** Helper method to check array bounds. */
    private static boolean isInside(int x, int y) {
        return x >= 0 && x < rows && y >= 0 && y < cols;
    }
}

import java.io.*;
import java.util.ArrayDeque;
import java.util.Deque;
import java.util.StringTokenizer;

/**
 * Refactored version of the original program.
 *
 * <p>Changes made for readability and maintainability:
 * <ul>
 *   <li>Encapsulated BFS logic in dedicated private methods.</li>
 *   <li>Replaced the generic {@code Node} class with a {@code record} for immutability.</li>
 *   <li>Extracted constants (directions) and utility methods with clear names.</li>
 *   <li>Avoided labeled loops in favor of early returns and simple condition checks.</li>
 *   <li>Improved naming of variables and methods to reflect their purpose.</li>
 *   <li>Kept the fast scanner but isolated its initialization.</li>
 * </ul>
 *
 * The functional behavior of the program is unchanged.
 */
public class Main {

    /* ---------- Constants ---------- */
    private static final int[][] DIRS = {{1, 0}, {0, 1}, {-1, 0}, {0, -1}};
    private static final PrintWriter OUT = new PrintWriter(System.out, true);

    /* ---------- IO utilities ---------- */
    private static BufferedReader BR;
    private static StringTokenizer ST;

    private static void initTokenizer() throws IOException {
        String line = BR.readLine();
        if (line == null) {
            throw new IOException("Unexpected end of input");
        }
        ST = new StringTokenizer(line);
    }

    private static String nextToken() throws IOException {
        while (!ST.hasMoreTokens()) {
            String next = BR.readLine();
            if (next == null) {
                return null;
            }
            ST = new StringTokenizer(next);
        }
        return ST.nextToken();
    }

    private static int nextInt() throws IOException {
        return Integer.parseInt(nextToken());
    }

    /* ---------- Core logic ---------- */
    public static void main(String[] args) throws IOException {
        BR = new BufferedReader(new InputStreamReader(System.in));
        initTokenizer();
        solve();
        OUT.flush();
    }

    private static void solve() throws IOException {
        // ----- read grid dimensions -----
        int rows = nextInt();
        int cols = nextInt();

        // ----- read the grid itself -----
        char[][] grid = new char[rows][];
        for (int r = 0; r < rows; r++) {
            grid[r] = nextToken().toCharArray();
        }

        // ----- locate the exit and run BFS from it -----
        Node exit = findExit(grid);
        int[][] distanceFromExit = new int[rows][cols];
        boolean[][] visited = new boolean[rows][cols];
        bfs(grid, exit, distanceFromExit, visited);

        // ----- find the step count at the start position -----
        int startSteps = findStartSteps(grid, distanceFromExit);

        // ----- count battles (digits reachable within startSteps steps) -----
        int battleCount = countBattles(grid, distanceFromExit, startSteps);
        OUT.println(battleCount);
    }

    /** Returns the coordinates of the cell containing 'E'. */
    private static Node findExit(char[][] grid) {
        for (int i = 0; i < grid.length; i++) {
            for (int j = 0; j < grid[i].length; j++) {
                if (grid[i][j] == 'E') {
                    return new Node(i, j, 0);
                }
            }
        }
        throw new IllegalArgumentException("Exit 'E' not found");
    }

    /** Bread‑first search that fills {@code distance} with step counts from {@code source}. */
    private static void bfs(char[][] grid,
                            Node source,
                            int[][] distance,
                            boolean[][] visited) {
        Deque<Node> queue = new ArrayDeque<>();
        queue.add(source);
        visited[source.i][source.j] = true;

        while (!queue.isEmpty()) {
            Node cur = queue.poll();
            distance[cur.i][cur.j] = cur.steps;

            for (int[] d : DIRS) {
                int ni = cur.i + d[0];
                int nj = cur.j + d[1];
                if (isWithin(ni, nj, grid) && grid[ni][nj] != 'T' && !visited[ni][nj]) {
                    queue.add(new Node(ni, nj, cur.steps + 1));
                    visited[ni][nj] = true;
                }
            }
        }
    }

    /** Returns the distance stored at the cell containing 'S'. */
    private static int findStartSteps(char[][] grid, int[][] distance) {
        for (int i = 0; i < grid.length; i++) {
            for (int j = 0; j < grid[i].length; j++) {
                if (grid[i][j] == 'S') {
                    return distance[i][j];
                }
            }
        }
        throw new IllegalArgumentException("Start 'S' not found");
    }

    /** Counts the sum of all positive digit characters reachable within {@code maxSteps}. */
    private static int countBattles(char[][] grid,
                                    int[][] distance,
                                    int maxSteps) {
        int total = 0;
        for (int i = 0; i < grid.length; i++) {
            char[] row = grid[i];
            for (int j = 0; j < row.length; j++) {
                if (isPositiveDigit(row[j]) && distance[i][j] <= maxSteps && distance[i][j] >= 0) {
                    total += row[j] - '0';
                }
            }
        }
        return total;
    }

    /** Checks whether a character is a digit from '1' through '9'. */
    private static boolean isPositiveDigit(char c) {
        int val = c - '0';
        return val > 0 && val <= 9;
    }

    /** Simple bounds check for a cell inside the grid. */
    private static boolean isWithin(int i, int j, char[][] grid) {
        return i >= 0 && i < grid.length && j >= 0 && j < grid[i].length;
    }

    /** Record representing a cell in the grid with its BFS distance from the source. */
    private record Node(int i, int j, int steps) {}
}

import java.io.IOException;
import java.io.PrintWriter;
import java.util.Arrays;
import java.util.Deque;
import java.util.Scanner;

/**
 * Reads a rectangular grid, performs a reverse breadth‑first search from the goal
 * to the start and returns the total “battle” cost accumulated along the way.
 */
public class ProblemB {

    /** Four possible movement directions: right, down, left, up */
    private static final int[] DX = {1, 0, -1, 0};
    private static final int[] DY = {0, 1, 0, -1};

    /** Maximum number of distinct time steps that can be explored.
     *  In the original problem this is bounded by the number of cells. */
    private static final int MAX_TIME = 10_000;

    /** Entry point of the program. */
    public static void main(String[] args) throws IOException {
        try (Scanner scanner = new Scanner(System.in);
             PrintWriter out = new PrintWriter(System.out)) {

            int rows = scanner.nextInt();
            int cols = scanner.nextInt();

            char[][] rawInput = new char[rows][];
            for (int i = 0; i < rows; i++) {
                rawInput[i] = scanner.next().toCharArray();
            }

            int startX = -1, startY = -1;
            int goalX = -1, goalY = -1;
            int[][] costMap = new int[rows][cols];

            placeSymbols(rawInput, costMap, startX, startY, goalX, goalY);

            int answer = solve(costMap, startX, startY, goalX, goalY);
            out.println(answer);
            out.flush();
        }
    }

    /**
     * Parses the input grid, records the start / goal positions and fills
     * {@code costMap} with the integer values that represent battle costs.
     * Cells containing 'T' are marked with {@code -1} (impassable).
     */
    private static void placeSymbols(char[][] grid,
                                     int[][] costMap,
                                     int[] start,
                                     int[] goal,
                                     int[] goalPlaceholder) {
        int rows = grid.length;
        int cols = grid[0].length;

        for (int y = 0; y < rows; y++) {
            for (int x = 0; x < cols; x++) {
                char ch = grid[y][x];
                if (ch == 'S') {
                    start[0] = x;
                    start[1] = y;
                } else if (ch == 'E') {
                    goal[0] = x;
                    goal[1] = y;
                } else if (ch == 'T') {
                    costMap[y][x] = -1;               // impassable
                } else if (ch >= '1' && ch <= '9') {
                    costMap[y][x] = ch - '0';         // battle cost of the cell
                }
            }
        }
    }

    /**
     * Performs a reverse breadth‑first search from the goal to the start.
     * While exploring, it accumulates the battle cost of each visited cell
     * according to the step (time) at which it is reached.
     *
     * @return the total battle cost incurred until the start cell is reached.
     */
    private static int solve(int[][] map, int startX, int startY,
                             int goalX, int goalY) {
        final int rows = map.length;
        final int cols = map[0].length;

        // battleCost[t] holds the sum of all cell costs that are reached at step t
        int[] battleCost = new int[MAX_TIME + 1];

        // visited[y][x] indicates whether (x,y) has already been enqueued
        boolean[][] visited = new boolean[rows][cols];

        // Queue stores a tuple (x, y, timeStep)
        Deque<Position> queue = new ArrayDeque<>();
        queue.add(new Position(goalX, goalY, 0));
        visited[goalY][goalX] = true;

        int reachedTime = -1;

        while (!queue.isEmpty()) {
            Position cur = queue.poll();

            // If the current position is the start, remember at which step we arrived
            if (cur.x == startX && cur.y == startY) {
                reachedTime = cur.time;
                break; // No need to continue – we have found the start.
            }

            // Accumulate the battle cost of the current cell for its time step
            if (map[cur.y][cur.x] >= 1) {
                battleCost[cur.time] += map[cur.y][cur.x];
            }

            // Explore the four neighbours
            for (int dir = 0; dir < 4; dir++) {
                int nx = cur.x + DX[dir];
                int ny = cur.y + DY[dir];

                // Boundary checks and obstacle check
                if (!insideGrid(nx, ny, rows, cols) ||
                        map[ny][nx] == -1) {
                    continue;
                }

                if (!visited[ny][nx]) {
                    visited[ny][nx] = true;
                    queue.add(new Position(nx, ny, cur.time + 1));
                }
            }
        }

        // If the start was never reached, the problem definition would need to handle it.
        // Assuming a path always exists, compute the total battle cost up to the step we arrived.
        int totalBattle = 0;
        for (int t = 0; t <= reachedTime; t++) {
            totalBattle += battleCost[t];
        }
        return totalBattle;
    }

    /** Helper that checks whether a coordinate lies inside the rectangular grid. */
    private static boolean insideGrid(int x, int y, int rows, int cols) {
        return x >= 0 && x < cols && y >= 0 && y < rows;
    }

    /** Simple immutable container for a grid position together with the time step. */
    private static final class Position {
        final int x;
        final int y;
        final int time;

        Position(int x, int y, int time) {
            this.x = x;
            this.y = y;
            this.time = time;
        }
    }
}

import java.io.*;
import java.util.*;
import java.math.BigInteger;

public class Main {
    static class Pair {
        int a;
        int b;

        public Pair() {}

        public Pair(int x, int y) {
            a = x;
            b = y;
        }
    }

    static class Cell implements Comparable<Cell> {
        int a, b;
        long dis;

        public Cell(int x, int y, long z) {
            a = x;
            b = y;
            dis = z;
        }

        @Override
        public int compareTo(Cell c) {
            return Long.compare(dis, c.dis);
        }
    }

    static class TrieNode {
        TrieNode left;
        TrieNode right;
        int op;
        int data;

        public TrieNode() {}
    }

    private static int gcd(int a, int b) {
        if (a < b) return gcd(b, a);
        if (b == 0) return a;
        return gcd(b, a % b);
    }

    private static long pow(long x, long y) {
        if (y == 0) return 1;
        if (y == 1) return x;
        long half = pow(x, y / 2);
        half = (half * half) % MOD;
        return (y % 2 == 0) ? half : (half * x) % MOD;
    }

    private static final long MOD = (long) 1e9 + 7;
    private static long[] fact;
    private static long[] invFact;
    private static int[][] sd, td;
    private static char[][] grid;
    private static boolean[][] visited;
    private static final int[] DX = {-1, 1, 0, 0};
    private static final int[] DY = {0, 0, -1, 1};
    private static int rows, cols;

    public static void main(String[] args) throws Exception {
        new Thread(null, null, "Anshum Gupta", 99999999).start();
    }

    private static void solve() throws Exception {
        FastScanner scanner = new FastScanner();
        PrintWriter out = new PrintWriter(new BufferedOutputStream(System.out), true);
        int testCases = 1;

        while (testCases-- > 0) {
            rows = scanner.nextInt();
            cols = scanner.nextInt();
            grid = new char[rows][cols];

            for (int i = 0; i < rows; i++) {
                grid[i] = scanner.next().toCharArray();
            }

            sd = new int[rows][cols];
            solveComponent();
            td = new int[rows][cols];
            int result = 0;

            for (int i = 0; i < rows; i++) {
                Arrays.fill(visited[i], false);
                for (int j = 0; j < cols; j++) {
                    if (grid[i][j] == 'E') {
                        result = bfsFromE(i, j, sd[i][j]);
                        break;
                    }
                }
            }

            out.println(result);
        }

        out.flush();
    }

    private static void solveComponent() {
        Arrays.fill(visited[0], false);
        Queue<Pair> queue = new LinkedList<>();

        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == 'S') {
                    bfsFromS(i, j);
                }
            }
        }
    }

    private static void bfsFromS(int startX, int startY) {
        Queue<Pair> queue = new LinkedList<>();
        queue.add(new Pair(startX, startY));
        visited[startX][startY] = true;
        sd[startX][startY] = 0;

        while (!queue.isEmpty()) {
            Pair current = queue.poll();
            for (int i = 0; i < 4; i++) {
                int newX = current.a + DX[i];
                int newY = current.b + DY[i];

                if (!isValidCell(newX, newY) || visited[newX][newY] || grid[newX][newY] == 'T') {
                    continue;
                }

                queue.add(new Pair(newX, newY));
                sd[newX][newY] = sd[current.a][current.b] + 1;
                visited[newX][newY] = true;
            }
        }
    }

    private static boolean isValidCell(int x, int y) {
        return x >= 0 && y >= 0 && x < rows && y < cols;
    }

    private static int bfsFromE(int startX, int startY, int maxDistance) {
        Queue<Pair> queue = new LinkedList<>();
        queue.add(new Pair(startX, startY));
        visited[startX][startY] = true;
        int result = 0;

        while (!queue.isEmpty()) {
            Pair current = queue.poll();
            if (current.dis > maxDistance) break;

            for (int i = 0; i < 4; i++) {
                int newX = current.a + DX[i];
                int newY = current.b + DY[i];

                if (!isValidCell(newX, newY) || visited[newX][newY] || grid[newX][newY] == 'T') {
                    continue;
                }

                visited[newX][newY] = true;
                td[newX][newY] = current.dis + 1;
                queue.add(new Pair(newX, newY));

                if (grid[newX][newY] != 'S' && grid[newX][newY] != 'E') {
                    result += grid[newX][newY] - '0';
                }
            }
        }

        return result;
    }

    private static class FastScanner {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        FastScanner() {
            reader = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.util.ArrayDeque;
import java.util.Deque;
import java.util.Scanner;
import java.util.Arrays;

/**
 * Simulates a forest traversal.
 * <p>
 * The algorithm:
 * <ol>
 *   <li>Read the grid (rows × columns) containing characters
 *       <code>E</code> (exit), <code>S</code> (start), digits 1‑9 (battles)
 *       and <code>T</code> (blocked terrain).</li>
 *   <li>Run a breadth‑first search from the exit to compute the minimum
 *       number of steps needed to reach every walkable cell.</li>
 *   <li>The required step count is the distance from the exit to the start.</li>
 *   <li>Sum the values of all digit cells whose distance is ≤ the required
 *       step count.</li>
 *   <li>Print the sum.</li>
 * </ol>
 */
public class ForestSimulator {

    /** Directions: left, right, up, down */
    private static final int[][] DIRS = {
            {0, -1}, {0, 1}, {-1, 0}, {1, 0}
    };

    /** Character that represents a blocked cell (cannot be entered). */
    private static final char BLOCKED = 'T';

    /** Character that marks the exit point. */
    private static final char EXIT = 'E';

    /** Character that marks the start point. */
    private static final char START = 'S';

    /** Character range for digit cells (1‑9). */
    private static final char DIGIT_MIN = '1';
    private static final char DIGIT_MAX = '9';

    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            int rows = scanner.nextInt();
            int columns = scanner.nextInt();

            char[][] grid = readGrid(scanner, rows, columns);
            int stepsFromExit = computeStepDistances(grid);
            int requiredSteps = findStartStep(grid, stepsFromExit);

            int totalBattles = sumBattlesWithinSteps(grid, stepsFromExit, requiredSteps);
            System.out.print(totalBattles);
        }
    }

    /**
     * Reads the whole grid from {@code scanner}.
     *
     * @param scanner    the scanner positioned after the dimensions
     * @param rows       number of rows
     * @param columns    number of columns
     * @return a 2‑D array representing the forest
     */
    private static char[][] readGrid(Scanner scanner, int rows, int columns) {
        char[][] grid = new char[rows][];
        for (int r = 0; r < rows; r++) {
            String line = scanner.next();
            grid[r] = line.toCharArray();
        }
        return grid;
    }

    /**
     * Performs a BFS from the exit cell and stores the minimum number of steps
     * required to reach each walkable cell in {@code distance}.
     * <p>
     * Cells that are blocked ('T') are ignored.  Unreachable cells keep the
     * value {@link Integer#MAX_VALUE}.
     *
     * @param grid the forest map
     * @return a 2‑D array of step distances from the exit
     */
    private static int[][] computeStepDistances(char[][] grid) {
        int rows = grid.length;
        int columns = grid[0].length;
        int[][] distance = new int[rows][columns];
        for (int[] row : distance) {
            Arrays.fill(row, Integer.MAX_VALUE);
        }

        // Locate the exit cell
        int startX = -1, startY = -1;
        outerLoop:
        for (int y = 0; y < rows; y++) {
            for (int x = 0; x < columns; x++) {
                if (grid[y][x] == EXIT) {
                    startX = x;
                    startY = y;
                    break outerLoop;
                }
            }
        }

        // BFS queue stores coordinates as a single integer (x << 16 | y)
        Deque<Integer> queue = new ArrayDeque<>();
        distance[startY][startX] = 0;
        queue.add(pack(startX, startY));

        while (!queue.isEmpty()) {
            int packed = queue.poll();
            int x = unpackX(packed);
            int y = unpackY(packed);

            for (int[] dir : DIRS) {
                int nx = x + dir[1];
                int ny = y + dir[0];

                if (isInside(nx, ny, rows, columns)
                        && grid[ny][nx] != BLOCKED
                        && distance[ny][nx] > distance[y][x] + 1) {
                    distance[ny][nx] = distance[y][x] + 1;
                    queue.add(pack(nx, ny));
                }
            }
        }
        return distance;
    }

    /**
     * Finds the step distance of the start cell ('S') from the pre‑computed
     * {@code distance} matrix.
     *
     * @param grid       the forest map
     * @param distance   step distance matrix from the exit
     * @return the distance to the start cell
     */
    private static int findStartStep(char[][] grid, int[][] distance) {
        for (int y = 0; y < grid.length; y++) {
            for (int x = 0; x < grid[y].length; x++) {
                if (grid[y][x] == START) {
                    return distance[y][x];
                }
            }
        }
        // If the start is not found we consider it unreachable → 0 battles.
        return 0;
    }

    /**
     * Sums the numeric values of all digit cells whose distance to the exit
     * is less than or equal to {@code limit}.
     *
     * @param grid       the forest map
     * @param distance   step distance matrix from the exit
     * @param limit      maximum allowed distance
     * @return the total battle count
     */
    private static int sumBattlesWithinSteps(char[][] grid,
                                             int[][] distance,
                                             int limit) {
        int total = 0;
        for (int y = 0; y < grid.length; y++) {
            for (int x = 0; x < grid[y].length; x++) {
                if (grid[y][x] >= DIGIT_MIN && grid[y][x] <= DIGIT_MAX
                        && distance[y][x] <= limit) {
                    total += grid[y][x] - '0';
                }
            }
        }
        return total;
    }

    /** Packs (x, y) into a single {@code int} for queue storage. */
    private static int pack(int x, int y) {
        return (x << 16) | (y & 0xFFFF);
    }

    /** Unpacks the X coordinate from a packed integer. */
    private static int unpackX(int packed) {
        return packed >> 16;
    }

    /** Unpacks the Y coordinate from a packed integer. */
    private static int unpackY(int packed) {
        return packed & 0xFFFF;
    }

    /** Checks whether (x, y) lies inside the grid bounds. */
    private static boolean isInside(int x, int y, int rows, int columns) {
        return x >= 0 && x < columns && y >= 0 && y < rows;
    }
}

import java.io.*;
import java.util.*;

public class Main {

    /** Four possible movement directions. */
    private static final int[][] DIRECTIONS = {{1, 0}, {-1, 0}, {0, -1}, {0, 1}};

    /** Simple immutable cell position. */
    private static final class Position {
        final int row;
        final int col;

        Position(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }

    /** Holds a numeric cell together with its digit value. */
    private static final class NumericCell {
        final int row;
        final int col;
        final int value;

        NumericCell(int row, int col, int value) {
            this.row = row;
            this.col = col;
            this.value = value;
        }
    }

    public static void main(String[] args) throws Exception {
        try (Scanner scanner = new Scanner(System.in);
             PrintWriter out = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)))) {

            int rows = scanner.nextInt();
            int cols = scanner.nextInt();
            scanner.nextLine();                     // consume the line‑break

            char[][] grid = new char[rows][cols];
            Position start = null;
            Position end   = null;
            List<NumericCell> numericCells = new ArrayList<>();

            for (int r = 0; r < rows; r++) {
                String line = scanner.nextLine();
                grid[r] = line.toCharArray();
                for (int c = 0; c < cols; c++) {
                    char ch = grid[r][c];
                    if (ch == 'S') {
                        start = new Position(r, c);
                    } else if (ch == 'E') {
                        end = new Position(r, c);
                    } else if (Character.isDigit(ch)) {
                        numericCells.add(new NumericCell(r, c, ch - '0'));
                    }
                }
            }

            int[][] distance = bfs(grid, end);
            int moves = distance[start.row][start.col];
            long answer = 0L;

            for (NumericCell nc : numericCells) {
                int d = distance[nc.row][nc.col];
                if (d != -1 && d <= moves) {
                    answer += nc.value;
                }
            }

            out.println(answer);
        }
    }

    /** Breadth‑first search that records the minimal number of steps from `start` to every reachable cell. */
    private static int[][] bfs(char[][] grid, Position start) {
        int rows = grid.length;
        int cols = grid[0].length;
        int[][] dist = new int[rows][cols];
        for (int[] row : dist) {
            Arrays.fill(row, -1);
        }

        Queue<Position> queue = new ArrayDeque<>();
        queue.add(start);
        dist[start.row][start.col] = 0;

        while (!queue.isEmpty()) {
            Position cur = queue.poll();

            // Do not expand from trap cells marked '*'
            if (grid[cur.row][cur.col] == '*') {
                continue;
            }

            for (int[] dir : DIRECTIONS) {
                int nr = cur.row + dir[0];
                int nc = cur.col + dir[1];
                if (isInBounds(nr, nc, rows, cols)
                        && isValidCell(grid, nr, nc)
                        && dist[nr][nc] == -1) {
                    dist[nr][nc] = dist[cur.row][cur.col] + 1;
                    queue.add(new Position(nr, nc));
                }
            }
        }
        return dist;
    }

    private static boolean isInBounds(int r, int c, int rows, int cols) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    private static boolean isValidCell(char[][] grid, int r, int c) {
        char ch = grid[r][c];
        // The only forbidden cell is 'T' (the rest, including '*' are traversable but '*'
        // does not propagate further, which is handled above).
        return ch != 'T';
    }
}

/**
 * Path‑finding utility that:
 *  1. Computes the shortest path from the start cell 'S' to the end cell 'E'
 *     while avoiding cells marked 'T'.
 *  2. From the end cell, explores all reachable cells within that shortest
 *     distance and adds up the numeric values of those cells (ignoring 'S',
 *     'E' and 'T').
 *
 * The implementation uses a classic breadth‑first search with explicit
 * coordinates instead of the encoding trick used in the original code.
 */
public class Main {

    /** Directions used for neighbour traversal. */
    private static final int[][] DIRS = {
            {-1, 0}, // up
            { 1, 0}, // down
            { 0,-1}, // left
            { 0, 1}  // right
    };

    /** Fast I/O wrapper around {@link InputStream}. */
    private static final class FastIO {
        private final InputStream stream;
        private final byte[] buffer = new byte[8192];
        private int bytePointer = 0, bytesRead = 0;

        FastIO(InputStream stream) {
            this.stream = stream;
        }

        private int readByte() throws IOException {
            if (bytePointer >= bytesRead) {
                bytesRead = stream.read(buffer);
                bytePointer = 0;
                if (bytesRead <= 0) {
                    return -1;
                }
            }
            return buffer[bytePointer++];
        }

        private static boolean isSpaceChar(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        private void skipSpaces() throws IOException {
            int c;
            while ((c = readByte()) != -1 && isSpaceChar(c)) { /* no‑op */ }
            // Move pointer back one step so the next call reads this char again
            if (bytePointer > 0) bytePointer--;
        }

        /** Reads the next token (a non‑space sequence). */
        private String readToken() throws IOException {
            skipSpaces();
            if (bytePointer >= bytesRead) {
                bytesRead = stream.read(buffer);
                bytePointer = 0;
                if (bytesRead <= 0) return null;
            }
            StringBuilder sb = new StringBuilder();
            int c = buffer[bytePointer++];
            while (!isSpaceChar(c)) {
                sb.append((char) c);
                if (bytePointer >= bytesRead) {
                    bytesRead = stream.read(buffer);
                    bytePointer = 0;
                    if (bytesRead <= 0) break;
                }
                c = buffer[bytePointer++];
            }
            return sb.toString();
        }

        /** Convenience method – reads the whole next line. */
        String nextLine() throws IOException {
            StringBuilder sb = new StringBuilder();
            int c;
            while ((c = readByte()) != -1 && !isSpaceChar(c) && c != '\n') {
                sb.append((char) c);
            }
            return sb.toString();
        }

        /** Reads an integer from the input. */
        int nextInt() throws IOException {
            String token = readToken();
            return Integer.parseInt(token);
        }
    }

    /** Performs a BFS to obtain the minimum number of steps from (sx,sy) to (dx,dy). */
    private static int shortestPath(char[][] grid, int sx, int sy, int dx, int dy,
                                    int rows, int cols) {
        boolean[][] visited = new boolean[rows][cols];
        int[][] dist = new int[rows][cols];

        java.util.Queue<int[]> q = new java.util.ArrayDeque<>();
        q.add(new int[]{sx, sy});
        visited[sx][sy] = true;
        dist[sx][sy] = 0;

        while (!q.isEmpty()) {
            int[] cur = q.poll();
            int r = cur[0], c = cur[1];

            if (r == dx && c == dy) {
                break; // target reached – distance already stored
            }

            for (int[] dir : DIRS) {
                int nr = r + dir[0];
                int nc = c + dir[1];

                if (!inBounds(nr, nc, rows, cols) || visited[nr][nc]) continue;
                char ch = grid[nr][nc];
                if (ch == 'T') continue; // wall

                visited[nr][nc] = true;
                dist[nr][nc] = dist[r][c] + 1;
                q.add(new int[]{nr, nc});
            }
        }
        return dist[dx][dy];
    }

    /** Collects the numeric values of all cells reachable from (startR,startC)
     *  within {@code maxDist} steps, excluding 'S', 'E' and 'T'. */
    private static int sumValuesWithinDistance(char[][] grid,
                                               int startR, int startC,
                                               int maxDist,
                                               int rows, int cols) {
        boolean[][] visited = new boolean[rows][cols];
        int[][] curDist = new int[rows][cols];

        java.util.Queue<int[]> q = new java.util.ArrayDeque<>();
        q.add(new int[]{startR, startC});
        visited[startR][startC] = true;
        curDist[startR][startC] = 0;

        int total = 0;

        while (!q.isEmpty()) {
            int[] cur = q.poll();
            int r = cur[0], c = cur[1];

            for (int[] dir : DIRS) {
                int nr = r + dir[0];
                int nc = c + dir[1];

                if (!inBounds(nr, nc, rows, cols) || visited[nr][nc]) continue;
                if (curDist[r][c] + 1 > maxDist) continue; // exceed allowed depth

                visited[nr][nc] = true;
                curDist[nr][nc] = curDist[r][c] + 1;

                char ch = grid[nr][nc];
                if (ch >= '0' && ch <= '9') {
                    total += ch - '0';
                }
                // Continue BFS regardless of whether the cell is numeric or not.
                q.add(new int[]{nr, nc});
            }
        }
        return total;
    }

    private static boolean inBounds(int r, int c, int rows, int cols) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    /** Entry point – reads input, runs the two searches and prints the result. */
    public static void main(String[] args) throws Exception {
        FastIO io = new FastIO(System.in);
        int rows = io.nextInt();
        int cols = io.nextInt();

        char[][] grid = new char[rows][];
        int startR = -1, startC = -1;
        int endR = -1, endC = -1;

        for (int r = 0; r < rows; r++) {
            String line = io.nextLine();
            grid[r] = line.toCharArray();
            for (int c = 0; c < cols; c++) {
                char ch = grid[r][c];
                if (ch == 'S') {
                    startR = r;
                    startC = c;
                } else if (ch == 'E') {
                    endR = r;
                    endC = c;
                }
            }
        }

        // Guard against malformed input
        if (startR < 0 || endR < 0) {
            throw new IllegalArgumentException("Missing 'S' or 'E' in the grid");
        }

        int shortest = shortestPath(grid, startR, startC, endR, endC, rows, cols);
        int answer = sumValuesWithinDistance(grid, endR, endC, shortest, rows, cols);

        System.out.println(answer);
    }
}

/**
 * Refactored solution for the problem.
 *
 * The program reads a grid containing:
 *   - 'E' : the endpoint (distance = 0)
 *   - 'S' : the start point
 *   - 'T' : a blocked cell (treated as wall)
 *   - digits '0'‑'9' : collectible values
 *
 * It computes the shortest Manhattan‑like distance from the endpoint to every
 * reachable cell using BFS. The distance from the endpoint to the start cell
 * is used as a “threshold”. All digit cells whose distance does not exceed this
 * threshold are summed and the result is printed.
 *
 * The refactor focuses on readability, maintainability and separation of concerns.
 */
public class Main {

    /** Size limits – keep them configurable if needed */
    private static final int MAX_N = 1000;   // adjust according to the real limits

    /** Directions: right, down, left, up */
    private static final int[] DX = {0, 1, 0, -1};
    private static final int[] DY = {1, 0, -1, 0};

    /** Value representing "infinity" for unvisited cells */
    private static final int INF = Integer.MAX_VALUE / 2;

    /** Simple container for BFS queue entries */
    private static final class Position {
        final int row;
        final int col;

        Position(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }

    /** Fast input scanner – lightweight wrapper around BufferedReader */
    private static final class FastScanner {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        FastScanner(InputStream input) {
            this.reader = new BufferedReader(new InputStreamReader(input));
            tokenizer = new StringTokenizer(readLineOrSkip());
        }

        /** Reads next non‑empty line and creates a tokenizer */
        private void scanLine() {
            try {
                tokenizer = new StringTokenizer(reader.readLine().trim());
            } catch (IOException e) {
                throw new UncheckedIOException(e);
            }
        }

        /** Returns true if there is still a token left */
        private boolean hasMoreTokens() {
            return tokenizer != null && tokenizer.hasMoreTokens();
        }

        /** Convenience method to read a whole line (ignores blank lines) */
        private String readLineIfExists() throws IOException {
            String line;
            while ((line = reader.readLine()) != null && line.trim().isEmpty()) {
                // skip empty lines
            }
            if (line == null) {
                tokenizer = null; // signal EOF
            } else {
                tokenizer = new StringTokenizer(line.trim());
            }
            return line;
        }

        /** Fetch the next token, expanding the input automatically */
        private String nextToken() {
            if (!hasMoreTokens()) {
                readLineIfExists();
                if (!hasMoreTokens()) {
                    return null; // EOF
                }
            }
            return tokenizer.nextToken();
        }

        /** Convenience wrappers */
        int nextInt() { return Integer.parseInt(nextToken()); }
        long nextLong() { return Long.parseLong(nextToken()); }
    }

    /** Entry point */
    public static void main(String[] args) {
        FastScanner in = new FastScanner(System.in);

        int rows = in.nextInt();
        int cols = in.nextInt();

        char[][] grid = new char[rows][];
        int startRow = -1, startCol = -1;
        int endRow = -1, endCol = -1;

        for (int i = 0; i < rows; i++) {
            String line = in.readLineIfExists();
            if (line == null) {
                throw new IllegalArgumentException("Unexpected end of input");
            }
            grid[i] = line.toCharArray();

            // locate start and end positions while scanning the line
            for (int j = 0; j < cols; j++) {
                char cell = grid[i][j];
                if (cell == 'S') {
                    startRow = i;
                    startCol = j;
                } else if (cell == 'E') {
                    endRow = i;
                    endCol = j;
                }
            }
        }

        if (startRow == -1 || startCol == -1 || endRow == -1 || endCol == -1) {
            throw new IllegalArgumentException("Both 'S' and 'E' must be present in the grid");
        }

        int[][] distance = new int[rows][cols];
        for (int[] row : distance) {
            Arrays.fill(row, INF);
        }
        distance[endRow][endCol] = 0;

        Deque<Position> queue = new ArrayDeque<>();
        queue.add(new Position(endRow, endCol));

        while (!queue.isEmpty()) {
            Position cur = queue.pollFirst();
            int r = cur.row;
            int c = cur.col;

            for (int dir = 0; dir < DX.length; dir++) {
                int nr = r + DX[dir];
                int nc = c + DY[dir];

                // bounds check
                if (nr < 0 || nr >= rows || nc < 0 || nc >= cols) {
                    continue;
                }
                // skip blocked cells ('T')
                if (grid[nr][nc] == 'T') {
                    continue;
                }
                // relax edge
                if (distance[nr][nc] > distance[r][c] + 1) {
                    distance[nr][nc] = distance[r][c] + 1;
                    queue.add(new Position(nr, nc));
                }
            }
        }

        int threshold = distance[startRow][startCol];
        int collectibleSum = 0;

        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] >= '0' && grid[i][j] <= '9') {
                    if (distance[i][j] <= threshold) {
                        collectibleSum += grid[i][j] - '0';
                    }
                }
            }
        }

        System.out.println(collectibleSum);
    }
}

import java.io.*;
import java.util.*;

/**
 * Reads a grid from standard input, performs a breadth‑first search from the
 * endpoint 'E', and prints the sum of numeric cells that are at most the same
 * distance from 'E' as the distance from 'E' to the starting cell 'S'.
 */
public class Main {

    /** Encoding of a cell as a single integer for queue storage. */
    private static int encode(int row, int col, int width) {
        return row * width + col;
    }

    /** Decoding of the integer produced by {@link #encode(int, int, int)}. */
    private static int decodeRow(int code, int width) {
        return code / width;
    }

    /** Decoding of the integer produced by {@link #encode(int, int, int)}. */
    private static int decodeCol(int code, int width) {
        return code % width;
    }

    /** Directions used for neighbour exploration (up, down, left, right). */
    private static final int[] DR = {1, -1, 0, 0};
    private static final int[] DC = {0, 0, 1, -1};

    /** Entry point. */
    public static void main(String[] args) throws IOException {
        new Main().run();
    }

    /** Orchestrates input parsing and solution computation. */
    private void run() throws IOException {
        /* ---------- Input parsing ---------- */
        try (BufferedReader br = new BufferedReader(
                new InputStreamReader(System.in))) {

            StringTokenizer st = new StringTokenizer(br.readLine());
            int rows = Integer.parseInt(st.nextToken());
            int cols = Integer.parseInt(st.nextToken());

            char[][] grid = new char[rows][];
            int[][] values = new int[rows][cols];
            int startRow = -1, startCol = -1;
            int endRow = -1, endCol = -1;

            for (int r = 0; r < rows; r++) {
                String line = br.readLine();
                grid[r] = line.toCharArray();
                for (int c = 0; c < cols; c++) {
                    char ch = line.charAt(c);
                    if (ch == 'T') {
                        /* obstacle – value not used */
                    } else if (ch == 'S') {
                        startRow = r;
                        startCol = c;
                        values[r][c] = 0;
                    } else if (ch == 'E') {
                        endRow = r;
                        endCol = c;
                        values[r][c] = 0;
                    } else {
                        values[r][c] = ch - '0';
                    }
                }
            }

            /* ---------- Core algorithm ---------- */
            long answer = computeSumWithinDistance(
                    grid, values, rows, cols,
                    startRow, startCol, endRow, endCol);

            /* ---------- Output ---------- */
            System.out.println(answer);
        }
    }

    /**
     * Executes a BFS from the endpoint {@code 'E'}, records the distance of every
     * reachable cell, obtains the distance from {@code 'E'} to the start cell
     * {@code 'S'}, and sums the numeric values of all cells whose distance to
     * {@code 'E'} does not exceed that threshold.
     */
    private long computeSumWithinDistance(char[][] grid, int[][] values,
                                          int rows, int cols,
                                          int sr, int sc, int er, int ec) {

        int[][] distance = new int[rows][cols];
        boolean[][] visited = new boolean[rows][cols];

        /* Initialise queue with the endpoint */
        Queue<Integer> queue = new ArrayDeque<>();
        final int WIDTH = rows * cols;
        queue.add(encode(er, ec, WIDTH));
        visited[er][ec] = true;

        /* BFS */
        int depth = 0;
        while (!queue.isEmpty()) {
            int work = queue.size();
            for (int i = 0; i < work; i++) {
                int encoded = queue.poll();
                int r = decodeRow(encoded, WIDTH);
                int c = decodeCol(encoded, WIDTH);
                distance[r][c] = depth;

                exploreNeighbours(r, c, grid, visited, queue, WIDTH);
            }
            depth++;
        }

        int maxAllowedDepth = distance[sr][sc];
        long sum = 0;
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (distance[r][c] <= maxAllowedDepth) {
                    sum += values[r][c];
                }
            }
        }
        return sum;
    }

    /** Adds all unvisited, non‑obstacle neighbours of (r,c) to the BFS queue. */
    private void exploreNeighbours(int r, int c, char[][] grid,
                                   boolean[][] visited,
                                   Queue<Integer> queue, int width) {
        for (int dir = 0; dir < 4; dir++) {
            int nr = r + DR[dir];
            int nc = c + DC[dir];
            if (nr < 0 || nr >= grid.length || nc < 0 || nc >= grid[0].length) {
                continue;                       // outside the grid
            }
            if (grid[nr][nc] == 'T') {
                continue;                       // obstacle – cannot move onto 'T'
            }
            if (!visited[nr][nc]) {
                visited[nr][nc] = true;
                queue.add(encode(nr, nc, width));
            }
        }
    }
}

