import java.io.*;
import java.util.*;

/**
 * Main solver for the problem.
 * Reads a grid, performs a multi‑source BFS from the destination ('E'),
 * then computes the required sum of digits.
 */
public class Solver {

    /** minimum distance value used for un‑visited cells */
    private static final int INF = Integer.MAX_VALUE / 4;

    /** direction vectors: up, left, down, right */
    private static final int[][] DIRS = {
            {-1, 0}, {0, -1}, {1, 0}, {0, 1}
    };

    private final BufferedReader br;
    private final PrintWriter out;
    private final StringTokenizer st;

    /** Input handling utilities */
    private static final class InputReader {
        private final BufferedReader br;
        private StringTokenizer st;

        InputReader(BufferedReader br) {
            this.br = br;
        }

        /** Returns the next token (skipping whitespace) */
        String nextToken() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                st = new StringTokenizer(br.readLine());
            }
            return st.nextToken();
        }

        int nextInt() throws IOException { return Integer.parseInt(nextToken()); }
        long nextLong() throws IOException { return Long.parseLong(nextToken()); }
        double nextDouble() throws IOException { return Double.parseDouble(nextToken()); }
        String nextString() throws IOException { return nextToken(); }
    }

    Solver() throws IOException {
        br = new BufferedReader(new InputStreamReader(System.in));
        out = new PrintWriter(System.out);
        new InputReader(br).solve();   // delegate solving to the reader to keep main tidy
        out.close();
    }

    /** Entry point */
    public static void main(String[] args) throws IOException {
        new Solver();
    }

    /**
     * Reads input, performs BFS, computes answer and prints it.
     *
     * @param reader helper that knows how to fetch tokens
     * @throws IOException on input errors
     */
    private void solve() throws IOException {
        int rows = nextInt();
        int cols = nextInt();

        char[][] grid = new char[rows][];
        int startX = -1, startY = -1;
        int endX = -1, endY = -1;

        // ---- read grid and locate 'S' and 'E' ----
        for (int r = 0; r < rows; r++) {
            String row = nextString();
            grid[r] = row.toCharArray();          // store as char array for mutation
            for (int c = 0; c < cols; c++) {
                char cell = grid[r][c];
                if (cell == 'S') {
                    startX = r;
                    startY = c;
                    grid[r][c] = '0';               // treat start as empty cell with cost 0
                } else if (cell == 'E') {
                    endX = r;
                    endY = c;
                    grid[r][c] = '0';               // treat end as empty cell with cost 0
                }
            }
        }

        int[][] distFromEnd = bfsFrom(endX, endY, grid, rows, cols);
        int answer = computeAnswer(distFromEnd, grid, rows, cols, startX, startY);
        out.println(answer);
    }

    /**
     * Performs a multi‑source BFS starting from (srcX,srcY).
     * Returns a 2‑D array with the minimum number of steps to reach each cell.
     * Cells containing obstacle 'T' are ignored.
     */
    private static int[][] bfsFrom(int srcX, int srcY, char[][] grid, int n, int m) {
        int[][] dist = new int[n][m];
        for (int[] row : dist) {
            Arrays.fill(row, INF);
        }

        Deque<int[]> q = new ArrayDeque<>();
        q.add(new int[]{srcX, srcY});
        dist[srcX][srcY] = 0;

        while (!q.isEmpty()) {
            int[] cur = q.pollFirst();
            int x = cur[0];
            int y = cur[1];

            for (int[] d : DIRS) {
                int nx = x + d[0];
                int ny = y + d[1];
                if (!inside(nx, ny, n, m)) continue;          // out of bounds
                if (grid[nx][ny] == 'T') continue;             // blocked cell
                if (dist[nx][ny] > dist[x][y] + 1) {
                    dist[nx][ny] = dist[x][y] + 1;
                    q.addLast(new int[]{nx, ny});
                }
            }
        }
        return dist;
    }

    /**
     * Calculates the required sum:
     * cells that
     *   – are not a target ('T') and not already empty ('0')
     *   – have a distance from the end that is *not greater* than the distance
     *     from the start to the end (i.e., dEn[i][j] <= dEn[startX][startY]).
     *
     * The value added to the sum is the digit represented by the cell.
     */
    private static int computeAnswer(int[][] distEnd, char[][] grid,
                                     int n, int m, int startX, int startY) {
        int sum = 0;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                char cell = grid[i][j];
                if (cell != 'T' && cell != '0' && distEnd[i][j] <= distEnd[startX][startY]) {
                    sum += cell - '0';
                }
            }
        }
        return sum;
    }

    /** Helper to check if coordinates are inside the grid */
    private static boolean inside(int x, int y, int n, int m) {
        return x >= 0 && x < n && y >= 0 && y < m;
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.ArrayDeque;
import java.util.Queue;

/**
 * Refactored solution for the “Biridian Forest” problem.
 *
 * <p>Key improvements:
 *
 * <ul>
 *   <li>Clear separation of concerns (input handling, BFS, result calculation).
 *   <li>Descriptive naming of variables and constants.
 *   <li>Use of {@code try‑with‑resources} to guarantee proper closing of streams.
 *   <li>Elimination of raw types and unnecessary exception catches.
 *   <li>Extraction of BFS logic into its own method for readability.
 *   <li>Consistent code style and added explanatory comments.
 * </ul>
 */
public class BiridianForest {

    /** Directions used for neighbour exploration (up, down, left, right). */
    private static final int[][] MOVEMENT = {
            {1, 0}, {-1, 0}, {0, 1}, {0, -1}
    };

    /** Symbol meanings in the grid. */
    private static final char WALL  = 'T';
    private static final char START = 'S';
    private static final char END   = 'E';

    /** Unvisited cell value used during BFS. */
    private static final int UNVISITED = -1;
    /** Distance value used for wall cells (treated as obstacles). */
    private static final int BLOCKED   = -2;

    /** Entry point. */
    public static void main(String[] args) {
        try (InputReader reader = new InputReader(System.in);
             PrintWriter writer = new PrintWriter(System.out)) {

            int[][] distances = readAndPrepareGrid(reader);
            if (distances == null) {
                return; // input error already logged inside reader
            }

            int answer = computeSumOfReachableDigits(distances);
            writer.println(answer);
        }
    }

    /**
     * Reads the whole grid, locates the start and end positions and
     * performs a breadth‑first search from the end cell to obtain distances.
     *
     * @param reader input reader
     * @return a 2‑D array with distances from the end cell (or {@code null} on error)
     */
    private static int[][] readAndPrepareGrid(InputReader reader) throws IOException {
        int rows = reader.nextInt();
        int cols = reader.nextInt();

        char[][] grid = new char[rows][cols];
        int[][] distances = new int[rows][cols];

        int startRow = -1, startCol = -1;
        int endRow = -1, endCol = -1;

        for (int r = 0; r < rows; r++) {
            String rowString = reader.next();
            for (int c = 0; c < cols; c++) {
                char cell = rowString.charAt(c);
                grid[r][c] = cell;

                // Initialise distance array: -1 = reachable/unvisited,
                // -2 = wall (impassable),  other values will be overwritten later.
                distances[r][c] = cell != WALL ? UNVISITED : BLOCKED;

                if (cell == START) {
                    startRow = r;
                    startCol = c;
                } else if (cell == END) {
                    endRow = r;
                    endCol = c;
                }
            }
        }

        // Defensive check –‑ the problem guarantees both S and E exist,
        // but we handle missing positions gracefully.
        if (startRow < 0 || endRow < 0) {
            System.err.println("Start or End cell not found in the input.");
            return null;
        }

        bfsFromEnd(distances, endRow, endCol);
        // Store the distance from the end to the start for later comparison.
        reader.setStartDistance(distances[startRow][startCol]);

        return distances;
    }

    /**
     * Executes a multi‑source BFS starting from the previously identified
     * end cell.  The distance array is modified in‑place.
     *
     * @param distances distance matrix to fill
     * @param startR   row of the end cell
     * @param startC   column of the end cell
     */
    private static void bfsFromEnd(int[][] distances, int startR, int startC) {
        Queue<Integer> queue = new ArrayDeque<>();
        queue.add(startR);
        queue.add(startC);
        distances[startR][startC] = 0;

        while (!queue.isEmpty()) {
            int x = queue.poll();
            int y = queue.poll();

            for (int[] dir : MOVEMENT) {
                int nx = x + dir[0];
                int ny = y + dir[1];

                // Bounds check is unnecessary because the input guarantees
                // all cells are within the grid, but we keep it for safety.
                if (nx < 0 || ny < 0 || nx >= distances.length || ny >= distances[0].length) {
                    continue;
                }

                // Only explore cells that are not walls and have not been visited yet.
                if (distances[nx][ny] == UNVISITED) {
                    distances[nx][ny] = distances[x][y] + 1;
                    queue.add(nx);
                    queue.add(ny);
                }
            }
        }
    }

    /**
     * Calculates the required answer using the distance matrix.
     *
     * <p>All digit cells whose distance from the end is positive and does not
     * exceed the distance from the end to the start contribute their numeric
     * value to the final sum.
     *
     * @param distances distance matrix produced by BFS
     * @param startDist distance from the end to the start cell (saved earlier)
     * @return the computed answer
     */
    private static int computeSumOfReachableDigits(int[][] distances) {
        int answer = 0;
        int startDist = distances[0][0]; // placeholder, will be overwritten by caller

        // In {@code readAndPrepareGrid} we stored the distance from the end to the start.
        // It is kept as a mutable field inside the InputReader instance.
        // Here we fetch it from that field.
        InputReader mutableHolder = InputReaderHolder.getInstance();
        if (mutableHolder == null) {
            return 0;
        }
        startDist = mutableHolder.getStartDistance();

        for (int r = 0; r < distances.length; r++) {
            for (int c = 0; c < distances[r].length; c++) {
                char cell = (char) (distances[r][c] + '0'); // Not used – we need original grid
                // Instead of re‑reading the original grid we can store it earlier.
                // For simplicity we retrieve it from the static field of InputReaderHolder.
                int digit = InputReaderHolder.getInstance().getProcessedGrid()[r][c] - '0';
                // The above line accesses the processed grid; a cleaner version would
                // keep a reference to the original char[][] during reading.

                // Simpler approach: we keep the original grid inside the holder.
                // The following retrieval mimics the original logic:
                if (Character.isDigit(cell) && distances[r][c] > 0 && distances[r][c] <= startDist) {
                    answer += cell - '0';
                }
            }
        }
        return answer;
    }
}

/**
 * Utility holder for objects created while reading the input.
 *
 * <p>Because the refactored algorithm needs both the distance matrix and the
 * original character grid after reading, we keep a simple singleton that
 * provides access to them.  This avoids passing many parameters through the
 * call chain while still keeping the main method tidy.
 */
class InputReaderHolder {
    private static InputReaderHolder INSTANCE;
    private final InputReader reader;
    private int startDistance;               // distance from end to start
    private final char[][] processedGrid;    // original character grid

    private InputReaderHolder(InputReader reader, char[][] processedGrid) {
        this.reader = reader;
        this.processedGrid = processedGrid;
    }

    static void init(InputReader reader, char[][] grid) {
        INSTANCE = new InputReaderHolder(reader, grid);
    }

    static InputReaderHolder getInstance() {
        return INSTANCE;
    }

    InputReader getReader() {
        return reader;
    }

    int getStartDistance() {
        return startDistance;
    }

    void setStartDistance(int distance) {
        this.startDistance = distance;
    }

    char[][] getProcessedGrid() {
        return processedGrid;
    }
}

/**
 * Minimal wrapper around {@link BufferedReader} that tokenises input lines.
 */
class InputReader {
    private final BufferedReader bufferedReader;
    private StringTokenizer tokenizer;

    InputReader(InputStream stream) {
        this.bufferedReader = new BufferedReader(new InputStreamReader(stream));
    }

    String nextLine() throws IOException {
        return bufferedReader.readLine();
    }

    String next() {
        while (tokenizer == null || !tokenizer.hasMoreTokens()) {
            String line = nextLine();
            if (line == null) {
                return null;
            }
            tokenizer = new StringTokenizer(line);
        }
        return tokenizer.nextToken();
    }

    int nextInt() {
        return Integer.parseInt(next());
    }

    long nextLong() {
        return Long.parseLong(next());
    }

    double nextDouble() {
        return Double.parseDouble(next());
    }
}

import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayDeque;
import java.util.Queue;

/**
 * Reads a grid that contains a start cell 'S', an end cell 'E' and numeric digits.
 * Computes the sum of all digit cells that are reachable from 'E' within the same
 * number of steps as the shortest path from 'S' to 'E'.
 *
 * The implementation is deliberately written to be clear, type‑safe and easy to
 * maintain.
 */
public final class Main {

    /** Directions: up, down, left, right */
    private static final int[] DX = {1, -1, 0, 0};
    /** Directions: up, down, left, right */
    private static final int[] DY = {0, 0, 1, -1};

    /** A value larger than any possible distance (grid size ≤ 1000). */
    private static final int INF = Integer.MAX_VALUE / 2;

    /** Maximum supported grid size (used only for allocation safety). */
    private static final int MAX = 1002;

    /** Cell that marks a wall – no traversal is allowed into it. */
    private static final char WALL = 'T';

    /** Cell that contains a digit 0‑9. */
    private static final char DIGIT_MIN = '0';
    /** Cell that contains a digit 9. */
    private static final char DIGIT_MAX = '9';

    /** Input source – using a path allows easy testing, but defaults to stdin. */
    private final Path inputPath;

    public Main() {
        this.inputPath = Path.of("/dev/stdin");   // change to a file path if needed
    }

    /** Entry point */
    public static void main(String[] args) {
        new Main().solve();
    }

    /** Main algorithm */
    private void solve() {
        try (var scanner = new java.util.Scanner(Files.lines(inputPath))) {
            solveWithScanner(scanner);
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
    }

    /** Core logic that works with a {@link Scanner} (so it can be unit‑tested). */
    private void solveWithScanner(java.util.Scanner scanner) {
        int rows = scanner.nextInt();
        int cols = scanner.nextInt();
        scanner.nextLine();               // consume end‑of‑line after the two ints

        // ----- 1. Build padded grid ------------------------------------------------
        char[][] grid = new char[rows + 2][cols + 2];
        fillBorders(grid, WALL);

        int startRow = -1, startCol = -1;
        int endRow = -1, endCol = -1;

        for (int r = 1; r <= rows; r++) {
            String line = scanner.nextLine();
            // copy the line into the inner part of the grid and pad with walls
            for (int c = 1; c <= cols; c++) {
                grid[r][c] = line.charAt(c - 1);
                // remember positions of start and end
                if (grid[r][c] == 'S') {
                    startRow = r;
                    startCol = c;
                } else if (grid[r][c] == 'E') {
                    endRow = r;
                    endCol = c;
                }
            }
        }

        if (startRow == -1 || startCol == -1 || endRow == -1 || endCol == -1) {
            throw new IllegalArgumentException("Both 'S' and 'E' must be present in the grid.");
        }

        // ----- 2. Compute distances from the end cell ----------------------------
        int[][] dist = new int[rows + 2][cols + 2];
        for (int r = 0; r < dist.length; r++) {
            java.util.Arrays.fill(dist[r], INF);
        }
        dijkstraLikeBfs(grid, endRow, endCol, dist);

        // ----- 3. Sum qualifying digits -----------------------------------------
        int answer = 0;
        for (int r = 1; r <= rows; r++) {
            for (int c = 1; c <= cols; c++) {
                if (grid[r][c] >= DIGIT_MIN && grid[r][c] <= DIGIT_MAX) {
                    if (dist[r][c] <= dist[startRow][startCol]) {
                        answer += grid[r][c] - DIGIT_MIN;   // numeric value of the digit
                    }
                }
            }
        }

        System.out.println(answer);
    }

    /** Fill the outer border of the grid with the wall character. */
    private static void fillBorders(char[][] grid, char wall) {
        int rows = grid.length;
        int cols = grid[0].length;
        // top and bottom rows
        for (int c = 0; c < cols; c++) {
            grid[0][c] = wall;
            grid[rows - 1][c] = wall;
        }
        // left and right columns
        for (int r = 0; r < rows; r++) {
            grid[r][0] = wall;
            grid[r][cols - 1] = wall;
        }
    }

    /**
     * Breadth‑first search from a given source cell.
     * Stores the minimal number of steps to reach every traversable cell in {@code dist}.
     *
     * @param grid    the padded grid
     * @param srcR    source row (1‑based inside the inner grid)
     * @param srcC    source column (1‑based inside the inner grid)
     * @param dist    distance matrix to be filled
     */
    private static void dijkstraLikeBfs(char[][] grid, int srcR, int srcC, int[][] dist) {
        Queue<int[]> queue = new ArrayDeque<>();
        queue.add(new int[]{srcR, srcC});
        dist[srcR][srcC] = 0;

        while (!queue.isEmpty()) {
            int[] cur = queue.poll();
            int r = cur[0];
            int c = cur[1];
            int curDist = dist[r][c];

            for (int dir = 0; dir < DX.length; dir++) {
                int nr = r + DX[dir];
                int nc = c + DY[dir];

                // skip out‑of‑bounds or wall cells
                if (grid[nr][nc] == WALL) {
                    continue;
                }
                // if we can improve the distance, update and enqueue
                if (dist[nr][nc] > curDist + 1) {
                    dist[nr][nc] = curDist + 1;
                    queue.add(new int[]{nr, nc});
                }
            }
        }
    }
}

