import java.io.DataInputStream;
import java.io.IOException;
import java.io.InputStream;
import java.util.ArrayDeque;
import java.util.Queue;

/**
 * Refactored version of the original solution.
 * - Clear separation of concerns (input, BFS, result calculation)
 * - Meaningful names and modern Java constructs
 * - Encapsulation of positional data
 */
public class Main {

    /** Marker for an unvisited cell */
    private static final int UNVISITED = 0;

    public static void main(String[] args) throws IOException {
        FastScanner fs = new FastScanner(System.in);

        int rows = fs.nextInt();
        int cols = fs.nextInt();

        char[][] grid = new char[rows][];
        Position start = null;
        Position end = null;

        for (int i = 0; i < rows; i++) {
            String line = fs.nextString();
            grid[i] = line.toCharArray();
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == 'S') {
                    start = new Position(i, j);
                } else if (grid[i][j] == 'E') {
                    end = new Position(i, j);
                }
            }
        }

        int[][] distance = bfs(grid, start, end);
        long result = computeResult(grid, distance, start);
        System.out.println(result);
    }

    /**
     * Breadth‑first search starting from the end position.
     *
     * @return 2‑D array where each cell contains the distance from the end,
     *         or {@link #UNVISITED} if unreachable / blocked.
     */
    private static int[][] bfs(char[][] grid, Position start, Position end) {
        int rows = grid.length;
        int cols = grid[0].length;

        int[][] distance = new int[rows][cols];
        // All cells are initially unvisited (distance = 0)
        Queue<PositionWithDist> queue = new ArrayDeque<>();

        queue.add(new PositionWithDist(end.row, end.col, 0));
        distance[end.row][end.col] = 0;

        final int[][] DIRS = {{-1, 0}, {0, 1}, {1, 0}, {0, -1}};

        while (!queue.isEmpty()) {
            PositionWithDist cur = queue.poll();
            int r = cur.row;
            int c = cur.col;
            int d = cur.dist;

            for (int[] dir : DIRS) {
                int nr = r + dir[0];
                int nc = c + dir[1];
                if (nr < 0 || nr >= rows || nc < 0 || nc >= cols) continue;
                if (grid[nr][nc] == 'T') continue;                     // wall
                if (distance[nr][nc] != UNVISITED) continue;           // already visited

                distance[nr][nc] = d + 1;
                queue.add(new PositionWithDist(nr, nc, d + 1));
            }
        }
        return distance;
    }

    /**
     * Calculates the required sum of digits.
     * A digit cell contributes if it is reachable and its distance
     * does not exceed the distance from the start cell to the end cell.
     */
    private static long computeResult(char[][] grid,
                                      int[][] distance,
                                      Position start) {
        long sum = 0;
        int startDist = distance[start.row][start.col];

        for (int i = 0; i < grid.length; i++) {
            for (int j = 0; j < grid[i].length; j++) {
                char ch = grid[i][j];
                if (Character.isDigit(ch)) {
                    int cellDist = distance[i][j];
                    if (cellDist != UNVISITED && cellDist <= startDist) {
                        sum += ch - '0';
                    }
                }
            }
        }
        return sum;
    }

    /** Simple immutable coordinate holder */
    private static final class Position {
        final int row;
        final int col;
        Position(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }

    /** Queue element that also stores the accumulated distance */
    private static final class PositionWithDist {
        final int row;
        final int col;
        final int dist;
        PositionWithDist(int row, int col, int dist) {
            this.row = row;
            this.col = col;
            this.dist = dist;
        }
    }

    /**
     * Fast scanner based on {@link DataInputStream} with a buffered
     * read method. Keeps the original performance characteristics
     * while providing meaningful method names.
     */
    private static final class FastScanner {
        private final DataInputStream ds;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0;
        private int len = 0;

        FastScanner(InputStream in) {
            ds = new DataInputStream(in);
        }

        private int readByte() throws IOException {
            if (ptr >= len) {
                len = ds.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c, sign = 1, val = 0;
            do { c = readByte(); } while (c <= ' ');
            if (c == '-') {
                sign = -1;
                c = readByte();
            }
            do {
                val = val * 10 + (c - '0');
                c = readByte();
            } while (c > ' ');
            return val * sign;
        }

        String nextString() throws IOException {
            int c;
            do { c = readByte(); } while (c <= ' ');
            StringBuilder sb = new StringBuilder();
            do {
                sb.append((char) c);
                c = readByte();
            } while (c > ' ');
            return sb.toString();
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.ArrayDeque;
import java.util.Locale;
import java.util.Queue;

/**
 * Refactored solution that reads a grid, performs a BFS from the start cell,
 * and computes the required sum based on distances from the start.
 *
 * <p>Changes made for readability and maintainability:
 * <ul>
 *   <li>Extracted input handling into a small {@code FastScanner}</li>
 *   <li>Replaced magic numbers and raw array encoding with clear constants
 *       and helper methods.</li>
 *   <li>Used {@code Queue<int[]>} to store coordinates instead of an encoded
 *       {@code int} value.</li>
 *   <li>Named variables and methods descriptively (e.g., {@code directions},
 *       {@codebfs}, {@codeisInside}).</li>
 *   <li>Applied try‑with‑resources for all I/O resources.</li>
 *   <li>Removed unnecessary static imports and duplicated code.</li>
 *   <li>Separated concerns into small, single‑purpose methods.</li>
 * </ul>
 */
public class Main {

    /** Maximum grid dimension (as used in the original code). */
    private static final int MAX_N = 1001;

    /** Four possible movement directions: up, down, left, right. */
    private static final int[][] DIRECTIONS = {
            {0, -1},   // up
            {0, 1},    // down
            {-1, 0},   // left
            {1, 0}     // right
    };

    /** Grid values: -1 for obstacles, 0 for start/end, 1‑9 for numbers. */
    private static final int OBSTACLE = -1;
    private static final int START_VALUE = 0;
    private static final int END_VALUE = 0;

    private BufferedReader reader;
    private PrintWriter writer;

    /** Grid representations. */
    private final int[][] grid = new int[MAX_N][MAX_N];
    private final int[][] distance = new int[MAX_N][MAX_N];

    /** Width and height of the grid. */
    private int cols, rows;

    /** Start (x, y) and end (x, y) coordinates. */
    private int startX, startY;
    private int endX, endY;

    /** --------------------------------------------------------------------- */
    /** Entry point. */
    public static void main(String[] args) throws IOException {
        new Main().run();
    }

    /** --------------------------------------------------------------------- */
    /** Core workflow: read input, solve, output answer. */
    private void run() throws IOException {
        try (FastScanner fs = new FastScanner()) {
            readInput(fs);
            bfs();
            int answer = computeAnswer();
            writer.println(answer);
        }
    }

    /** --------------------------------------------------------------------- */
    /** Reads the grid and identifies start / end positions. */
    private void readInput(FastScanner fs) {
        rows = fs.nextInt();          // n
        cols = fs.nextInt();          // m

        for (int y = 0; y < rows; y++) {
            String line = fs.nextToken();
            for (int x = 0; x < cols; x++) {
                char ch = line.charAt(x);
                switch (ch) {
                    case 'T' -> {
                        grid[y][x] = OBSTACLE;
                    }
                    case 'S' -> {
                        grid[y][x] = START_VALUE;
                        startX = x;
                        startY = y;
                    }
                    case 'E' -> {
                        grid[y][x] = END_VALUE;
                        endX = x;
                        endY = y;
                    }
                    default -> {
                        grid[y][x] = ch - '0';
                    }
                }
            }
        }

        // Initialise distance matrix with a large sentinel value.
        for (int[] row : distance) {
            java.util.Arrays.fill(row, Integer.MAX_VALUE / 4);
        }
    }

    /** --------------------------------------------------------------------- */
    /** Performs a breadth‑first search from the start cell. */
    private void bfs() {
        // Queue holds coordinate pairs [x, y].
        Queue<int[]> queue = new ArrayDeque<>();
        distance[startY][startX] = 0;
        queue.add(new int[]{startX, startY});

        while (!queue.isEmpty()) {
            int[] cur = queue.poll();
            int x = cur[0];
            int y = cur[1];
            int curDist = distance[y][x];

            for (int[] dir : DIRECTIONS) {
                int nx = x + dir[0];
                int ny = y + dir[1];

                if (!isInside(nx, ny)) {
                    continue;
                }
                if (grid[ny][nx] == OBSTACLE) {
                    continue;
                }
                int nextDist = curDist + 1;
                if (nextDist < distance[ny][nx]) {
                    distance[ny][nx] = nextDist;
                    queue.add(new int[]{nx, ny});
                }
            }
        }
    }

    /** --------------------------------------------------------------------- */
    /** Calculates the required sum based on the problem statement. */
    private int computeAnswer() {
        int startDistance = distance[startY][startX];
        int sum = 0;

        for (int y = 0; y < rows; y++) {
            for (int x = 0; x < cols; x++) {
                if (grid[y][x] > 0 && distance[y][x] <= startDistance) {
                    sum += grid[y][x];
                }
            }
        }
        return sum;
    }

    /** --------------------------------------------------------------------- */
    /** Utility to check whether a coordinate lies inside the grid. */
    private boolean isInside(int x, int y) {
        return x >= 0 && y >= 0 && x < cols && y < rows;
    }

    /** --------------------------------------------------------------------- */
    /** Simple fast scanner based on {@link BufferedReader} and {@link StringTokenizer}. */
    private static final class FastScanner implements AutoCloseable {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner(BufferedReader br) {
            this.br = br;
        }

        /** Reads the next token, expanding the tokenizer if needed. */
        String nextToken() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                String line = br.readLine();
                if (line == null) {
                    return null;
                }
                st = new StringTokenizer(line);
            }
            return st.nextToken();
        }

        /** Convenience wrappers for primitive types. */
        int nextInt() throws IOException {
            return Integer.parseInt(nextToken());
        }

        /** @return the next line (used only when a full line is required). */
        String nextLine() throws IOException {
            return br.readLine();
        }

        /** Marks end of input. */
        boolean EOF() throws IOException {
            return nextToken() == null;
        }

        @Override
        public void close() throws IOException {
            br.close();
        }
    }
}

/**
 * Refactored solution for the “forest walk” problem.
 *
 * <p>
 * The program reads a rectangular grid from standard input. Each cell contains:
 * <ul>
 *   <li>‘T’ – an impassable obstacle,
 *   <li>‘S’ – the starting position,
 *   <li>‘E’ – the ending position,
 *   <li>or a digit ‘0’‑‘9’ – the value of the cell.
 * </ul>
 * It performs a breadth‑first search from the ending cell, determines the farthest
 * reachable distance to the start cell, and finally sums the numeric values of all
 * cells whose distance from the end does not exceed that maximum.
 * </p>
 *
 * <p>Refactoring goals:</p>
 * <ul>
 *   <li>Encapsulate I/O in a dedicated {@link InputReader} that uses try‑with‑resources.</li>
 *   <li>Remove the tangled global mutable state of the original code.</li>
 *   <li>Replace manual circular buffers with the standard {@link java.util.Queue}</li>
 *   <li>Extract constants and reusable methods (directions, validation, summation).</li>
 *   <li>Add meaningful naming, javadoc comments and avoid magic numbers.</li>
 *   <li>Make the public API of {@code solve} explicit – it now receives the reader and
 *       an output writer, allowing deterministic testing.</li>
 * </ul>
 */
public final class Solution {

    /** Directions used by the breadth‑first search (up, right, down, left). */
    private static final int[] DIR_X = {-1, 0, 1, 0};
    private static final int[] DIR_Y = {0, 1, 0, -1};

    /** Simple wrapper around a {@link BufferedReader} that tokenises input lines. */
    private static final class InputReader implements AutoCloseable {
        private final BufferedReader bufferedReader;
        private StringTokenizer tokenizer;

        InputReader(BufferedReader bufferedReader) {
            this.bufferedReader = bufferedReader;
        }

        /** Returns the next token from the input stream, blocking if necessary. */
        String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(bufferedReader.readLine());
                } catch (Exception e) {
                    throw new IllegalStateException("Failed to read input", e);
                }
            }
            return tokenizer.nextToken();
        }

        /** Convenience method that returns the next token as an {@code int}. */
        int nextInt() {
            return Integer.parseInt(next());
        }

        @Override
        public void close() {
            // Delegates to the underlying BufferedReader which is closed by the caller.
        }
    }

    /**
     * Entry point.
     *
     * <p>All resources are released via {@code try‑with‑resources} to guarantee proper
     * cleanup even when exceptions occur.</p>
     */
    public static void main(String[] args) {
        try (java.io.InputStream in = System.in;
             java.io.PrintWriter out = new java.io.PrintWriter(System.out)) {
            solve(in, out);
        }
    }

    /**
     * Core solving routine.
     *
     * @param input  an input stream that provides the problem description
     * @param output a writer where the single integer answer is printed
     */
    private static void solve(java.io.InputStream input, java.io.PrintWriter output) {
        // -----------------------------------------------------------------------
        // 1. Parse the whole grid and locate special cells.
        // -----------------------------------------------------------------------
        try (var reader = new InputReader(new java.io.BufferedReader(
                new java.io.InputStreamReader(input)))) {

            int rows = reader.nextInt();
            int cols = reader.nextInt();

            int[][] forest = new int[rows][cols];
            int startX = -1, startY = -1;
            int finishX = -1, finishY = -1;

            for (int i = 0; i < rows; i++) {
                String line = reader.next();
                if (line.length() != cols) {
                    throw new IllegalArgumentException("Row length mismatch");
                }
                for (int j = 0; j < cols; j++) {
                    char cell = line.charAt(j);
                    if (cell == 'T') {
                        forest[i][j] = -1;                 // obstacle
                    } else if (cell == 'S') {
                        startX = i;
                        startY = j;
                        forest[i][j] = 0;                 // walkable, value 0
                    } else if (cell == 'E') {
                        finishX = i;
                        finishY = j;
                        forest[i][j] = 0;                 // walkable, value 0
                    } else {
                        forest[i][j] = cell - '0';        // numeric cell
                    }
                }
            }

            // -------------------------------------------------------------------
            // 2. Breadth‑first search from the finishing cell.
            // -------------------------------------------------------------------
            var distance = bfs(forest, finishX, finishY, rows, cols);
            int maxDist = distance[startX][startY]; // farthest reachable distance

            // -------------------------------------------------------------------
            // 3. Accumulate values of all cells that satisfy the distance bound.
            // -------------------------------------------------------------------
            long answer = sumValuesWithinDistance(forest, distance, maxDist, rows, cols);
            output.println(answer);
        }
    }

    /**
     * Executes a breadth‑first search starting from {@code startX,startY}.
     *
     * @return a 2‑D array where each entry holds the distance from the start cell,
     *         or {@code -1} if the cell is unreachable.
     */
    private static int[][] bfs(int[][] forest, int startX, int startY,
                               int rows, int cols) {
        int[][] distance = new int[rows][cols];
        for (int[] row : distance) {
            Arrays.fill(row, -1);
        }
        boolean[][] visited = new boolean[rows][cols];

        var queue = new java.util.ArrayDeque<int[]>();
        distance[startX][startY] = 0;
        visited[startX][startY] = true;
        queue.add(new int[]{startX, startY});

        while (!queue.isEmpty()) {
            int[] cur = queue.poll();
            int x = cur[0];
            int y = cur[1];

            for (int d = 0; d < 4; d++) {
                int nx = x + DIR_X[d];
                int ny = y + DIR_Y[d];
                if (isValid(nx, ny, rows, cols, forest, visited)) {
                    visited[nx][ny] = true;
                    distance[nx][ny] = distance[x][y] + 1;
                    queue.add(new int[]{nx, ny});
                }
            }
        }
        return distance;
    }

    /**
     * Determines whether a coordinate represents a walkable, not‑yet‑visited cell.
     */
    private static boolean isValid(int x, int y, int rows, int cols,
                                   int[][] forest, boolean[][] visited) {
        return x >= 0 && x < rows && y >= 0 && y < cols &&
               !visited[x][y] && forest[x][y] != -1;
    }

    /**
     * Sums the numeric values of all cells whose distance from the finish cell
     * does not exceed {@code maxDist}. Cells marked as obstacles are ignored.
     */
    private static long sumValuesWithinDistance(int[][] forest,
                                                int[][] distance,
                                                int maxDist,
                                                int rows,
                                                int cols) {
        long sum = 0;
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (distance[i][j] != -1 && distance[i][j] <= maxDist && forest[i][j] != -1) {
                    sum += forest[i][j];
                }
            }
        }
        return sum;
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.LinkedList;
import java.util.Queue;
import java.util.StringTokenizer;

/**
 * Refactored version of the "Biridian Forest" solution.
 *
 * <p>
 * The program reads a rectangular grid where:
 * <ul>
 *   <li>'E' – start cell,
 *   <li>'S' – target cell,
 *   <li>Digits '0'–'9' – collectible cells,
 *   <li>'T' – blocked cells,
 *   <li>'.' – empty cells.
 * </ul>
 * It performs a breadth‑first search from the start cell and adds all digit
 * values that are reachable within the same distance as the shortest path to
 * the target cell.
 * </p>
 */
public final class BiridianForest {

    /** Direction vectors: down, up, right, left */
    private static final int[] DX = {1, -1, 0, 0};
    private static final int[] DY = {0, 0, 1, -1};

    /** Width and height of the forest */
    private static int rows;
    /** Width and height of the forest */
    private static int cols;
    /** The grid itself */
    private static char[][] grid;

    /** Simple immutable position holder */
    private static final class Pos {
        private final int row;
        private final int col;

        private Pos(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }

    /** Entry point of the program. */
    public static void main(String[] args) throws IOException {
        try (Scanner scanner = new Scanner()) {
            rows = scanner.nextInt();
            cols = scanner.nextInt();
            grid = new char[rows][cols];

            for (int i = 0; i < rows; i++) {
                grid[i] = scanner.next().toCharArray();
            }

            int answer = bfs();
            System.out.println(answer);
        }
    }

    /** Breadth‑first search that calculates the required sum. */
    private static int bfs() {
        Pos start = locateStart();
        if (start == null) {
            throw new IllegalStateException("Start cell 'E' not found in the grid.");
        }

        int[][] distances = bfsComputeDistances(start);
        int distanceToTarget = distanceAt(start, 'S');

        int sum = 0;
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (Character.isDigit(grid[i][j])
                        && distances[i][j] <= distanceToTarget) {
                    sum += grid[i][j] - '0';
                }
            }
        }
        return sum;
    }

    /** Locates the cell containing the letter 'E'. */
    private static Pos locateStart() {
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == 'E') {
                    return new Pos(i, j);
                }
            }
        }
        return null; // should never happen if input is valid
    }

    /** Executes BFS from the given start position and returns a distance matrix. */
    private static int[][] bfsComputeDistances(Pos start) {
        final int INF = Integer.MAX_VALUE / 4;
        int[][] distance = new int[rows][cols];
        for (int[] row : distance) {
            java.util.Arrays.fill(row, INF);
        }
        distance[start.row][start.col] = 0;

        Queue<Pos> queue = new LinkedList<>();
        queue.add(start);

        while (!queue.isEmpty()) {
            Pos cur = queue.remove();

            for (int dir = 0; dir < DX.length; dir++) {
                int nextRow = cur.row + DX[dir];
                int nextCol = cur.col + DY[dir];

                if (isValid(nextRow, nextCol) && distance[nextRow][nextCol] == INF) {
                    distance[nextRow][nextCol] = distance[cur.row][cur.col] + 1;
                    queue.add(new Pos(nextRow, nextCol));
                }
            }
        }
        return distance;
    }

    /** Returns the distance of a cell if its character matches {@code target}, otherwise -1. */
    private static int distanceAt(Pos pos, char target) {
        return grid[pos.row][pos.col] == target ? 0 : -1;
    }

    /** Checks bounds and that the cell is not a tree ('T'). */
    private static boolean isValid(int i, int j) {
        return i >= 0 && i < rows && j >= 0 && j < cols && grid[i][j] != 'T';
    }

    /** Simple input wrapper using StringTokenizer. */
    private static final class Scanner {
        private final BufferedReader br;
        private StringTokenizer st;

        Scanner() throws IOException {
            this.br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                st = new StringTokenizer(br.readLine());
            }
            return st.nextToken();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }
}

/*
 * Refactored version of the original program.
 * The functionality is unchanged, but the code is organized,
 * uses meaningful names, Try‑With‑Resources and better encapsulation.
 */
import java.io.*;
import java.util.*;

public class Main {

    /* ----- constants ----------------------------------------------------- */
    private static final int INF = Integer.MAX_VALUE / 4;   // safe upper bound
    private static final int[] DX = {1, 0, -1, 0};
    private static final int[] DY = {0, 1, 0, -1};

    /* ----- mutable state ------------------------------------------------- */
    private static char[][] grid;          // input grid
    private static int[][] dist;           // distances from the exit
    private static int n, m;               // dimensions
    private static int startRow, startCol; // position of 'S'
    private static int exitRow, exitCol;   // position of 'E'

    /* ----- entry point ---------------------------------------------------- */
    public static void main(String[] args) {
        // Try‑With‑Resources guarantees proper closure of I/O streams
        try (Scanner scanner = new Scanner(System.in);
             PrintWriter out = new PrintWriter(System.out)) {

            readInput(scanner);
            bfs();                     // compute distances from the exit
            int limit = dist[startRow][startCol];

            int answer = 0;
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    char cell = grid[i][j];
                    if (Character.isDigit(cell) && dist[i][j] <= limit) {
                        answer += cell - '0';
                    }
                }
            }
            out.println(answer);
        } catch (Exception e) {
            // Unexpected I/O errors are wrapped in an unchecked exception
            throw new UncheckedIOException(e);
        }
    }

    /* ----- input handling ------------------------------------------------- */
    private static void readInput(Scanner scanner) {
        n = scanner.nextInt();
        m = scanner.nextInt();
        grid = new char[n];

        for (int i = 0; i < n; i++) {
            String line = scanner.next();
            grid[i] = line.toCharArray();

            for (int j = 0; j < m; j++) {
                char c = grid[i][j];
                if (c == 'E') {
                    exitRow = i;
                    exitCol = j;
                } else if (c == 'S') {
                    startRow = i;
                    startCol = j;
                }
            }
        }
    }

    /* ----- breadth‑first search ------------------------------------------- */
    private static void bfs() {
        dist = new int[n][m];
        for (int[] row : dist) {
            Arrays.fill(row, INF);
        }
        dist[exitRow][exitCol] = 0;
        Queue<Cell> queue = new ArrayDeque<>();
        queue.add(new Cell(exitRow, exitCol));

        while (!queue.isEmpty()) {
            Cell cur = queue.poll();
            for (int d = 0; d < DX.length; d++) {
                int nr = cur.row + DX[d];
                int nc = cur.col + DY[d];
                if (isValid(nr, nc) && dist[nr][nc] == INF) {
                    dist[nr][nc] = dist[cur.row][cur.col] + 1;
                    queue.add(new Cell(nr, nc));
                }
            }
        }
    }

    /* ----- helper methods ------------------------------------------------- */
    private static boolean isValid(int x, int y) {
        return x >= 0 && x < n && y >= 0 && y < m
                && grid[x][y] != 'T'               // walls are impassable
                && dist[x][y] == INF;              // not visited yet
    }

    /** Simple immutable cell holder used during BFS. */
    private static final class Cell {
        final int row, col;
        Cell(int row, int col) { this.row = row; this.col = col; }
    }
}

package forest;

import java.io.*;
import java.util.*;

/**
 * Reads a grid that contains a start cell 'S', an end cell 'E',
 * walkable cells (digits) and blocked cells 'T'.
 * Using Dijkstra's algorithm it finds the shortest distance from 'E' to 'S'
 * and then sums the digit values of all cells whose distance is not greater
 * than that distance (excluding 'S', 'E' and 'T').
 */
public class ForestPathFinder {

    /* ---------------------------------------------------------------------- */
    /*  Constants & helper structures                                           */
    /* ---------------------------------------------------------------------- */
    private static final int INF = 1_000_000_000;          // “infinite” distance

    /** Simple node used in the priority queue. */
    private static final class Node implements Comparable<Node> {
        final int row;
        final int col;
        final int dist;          // distance from the source ('E')

        Node(int row, int col, int dist) {
            this.row = row;
            this.col = col;
            this.dist = dist;
        }

        @Override
        public int compareTo(Node o) {
            return Integer.compare(this.dist, o.dist);
        }
    }

    /** Directions: down, up, right, left */
    private static final class Directions {
        static final int[] DR = {1, -1, 0, 0};
        static final int[] DC = {0,  0, 1,-1};
    }

    /** Minimal input reader that works with the original token format. */
    private static final class InputReader {
        private final BufferedReader br;

        InputReader(InputStream stream) {
            this.br = new BufferedReader(new InputStreamReader(stream));
        }

        /** Reads the next integer token. */
        int nextInt() throws IOException {
            int c;
            do {
                c = br.read();
            } while (c <= ' ');
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = br.read();
            }
            int value = 0;
            while (c >= '0' && c <= '9') {
                value = value * 10 + (c - '0');
                c = br.read();
            }
            return value * sign;
        }

        /** Reads the next non‑empty line. */
        String nextLine() throws IOException {
            String line;
            do {
                line = br.readLine();
            } while (line == null && line.isBlank());
            return line;
        }
    }

    /* ---------------------------------------------------------------------- */
    /*  Main solving routine                                                    */
    /* ---------------------------------------------------------------------- */
    public static void main(String[] args) throws Exception {
        /* ---------- input & grid preparation ---------- */
        try (InputReader reader = new InputReader(System.in);
             PrintWriter out = new PrintWriter(System.out)) {

            int n = reader.nextInt();          // number of rows
            int m = reader.nextInt();          // number of columns
            char[][] grid = new char[n][];
            int startR = -1, startC = -1;        // coordinates of 'S'
            int endR = -1,   endC = -1;          // coordinates of 'E'

            for (int r = 0; r < n; r++) {
                String line = reader.nextLine();
                grid[r] = line.toCharArray();
                for (int c = 0; c < m; c++) {
                    char ch = grid[r][c];
                    if (ch == 'S') {
                        startR = r;
                        startC = c;
                    } else if (ch == 'E') {
                        endR = r;
                        endC = c;
                    }
                }
            }

            /* ---------- Dijkstra from 'E' ---------- */
            int[][] distance = new int[n][m];
            for (int[] row : distance) {
                Arrays.fill(row, INF);
            }
            distance[endR][endC] = 0;

            PriorityQueue<Node> pq = new PriorityQueue<>();
            pq.add(new Node(endR, endC, 0));

            while (!pq.isEmpty()) {
                Node cur = pq.poll();
                // ignore stale entries
                if (cur.dist != distance[cur.row][cur.col]) {
                    continue;
                }
                for (int d = 0; d < 4; d++) {
                    int nr = cur.row + Directions.DR[d];
                    int nc = cur.col + Directions.DC[d];
                    if (isInBounds(nr, nc) && canWalk(grid, nr, nc)) {
                        int nd = cur.dist + 1;
                        if (nd < distance[nr][nc]) {
                            distance[nr][nc] = nd;
                            pq.add(new Node(nr, nc, nd));
                        }
                    }
                }
            }

            /* ---------- compute answer ---------- */
            int maxAllowed = distance[startR][startC];
            int answer = 0;

            for (int r = 0; r < n; r++) {
                for (int c = 0; c < m; c++) {
                    if (distance[r][c] <= maxAllowed) {
                        char ch = grid[r][c];
                        // keep only digit characters (ignore 'S','E','T')
                        if (ch >= '1' && ch <= '9') {
                            answer += ch - '0';
                        }
                    }
                }
            }

            out.println(answer);
        }
    }

    /* ---------------------------------------------------------------------- */
    /*  Small utility methods                                                   */
    /* ---------------------------------------------------------------------- */
    /** Checks whether a cell lies inside the rectangular grid. */
    private static boolean isInBounds(int r, int c, int n, int m) {
        return r >= 0 && r < n && c >= 0 && c < m;
    }

    /** Current grid dimensions are stored as static fields (set in main). */
    private static int n, m;               // set by the main method

    /** Returns true if the cell is not a blocked ('T') cell. */
    private static boolean canWalk(char[][] grid, int r, int c) {
        return grid[r][c] != 'T';
    }
}

/**
 * Refactored version of the Biridian Forest solution.
 *
 * <p>
 *   The program:
 *   <ul>
 *     <li>reads a grid from standard input,
 *     <li>performs a breadth‑first search from the end cell {@code 'E'} to compute the
 *         minimum distance to every reachable cell,
 *     <li>sums the numeric values of cells that are not obstacles and whose distance
 *         from the end is not larger than the distance from the end to the start cell
 *         {@code 'S'}.
 *   </ul>
 * </p>
 * The refactor focuses on readability, maintainability and testability by:
 * <ul>
 *   <li>extracting concerns into small, well‑named methods,
 *   <li>using expressive types (e.g. {@link Position}, {@link CellType}),
 *   <li>removing raw casts and magic numbers,
 *   <li>adding JavaDoc and inline comments,
 *   <li>preferring collection implementations that support iterator removal.
 * </ul>
 */
public class BiridianForest {

    /** Symbol that marks an obstacle (cannot be traversed). */
    private static final int OBSTACLE = -1;

    /** Symbol that marks the start position (the player). */
    private static final int START = -2;

    /** Fast scanner that works with tokenised input. */
    private static final class InputReader {
        private final BufferedReader br;
        private StringTokenizer st;

        InputReader() {
            this.br = new BufferedReader(new InputStreamReader(System.in));
        }

        /** Reads the next token, expanding the tokenizer when necessary. */
        private String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    throw new UncheckedIOException(e);
                }
            }
            return st.nextToken();
        }

        /** Convenience wrappers for primitive types. */
        int nextInt()               { return Integer.parseInt(next()); }
        long nextLong()             { return Long.parseLong(next()); }
        double nextDouble()         { return Double.parseDouble(next()); }
        String nextLine() {
            try {
                return br.readLine();
            } catch (IOException e) {
                throw new UncheckedIOException(e);
            }
        }
    }

    /** Simple immutable container for a grid coordinate. */
    private static final class Position {
        final int row;
        final int col;

        Position(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }

    /** Symbolic representation of a cell type found in the input grid. */
    private enum CellType {
        EMPTY('0', 0),
        ONE('1', 1),
        TWO('2', 2),
        THREE('3', 3),
        FOUR('4', 4),
        FIVE('5', 5),
        SIX('6', 6),
        SEVEN('7', 7),
        EIGHT('8', 8),
        NINE('9', 9),
        TREE('T', OBSTACLE),
        END('E', 0),
        START('S', START);

        private final char symbol;
        private final int value;

        CellType(char symbol, int value) {
            this.symbol = symbol;
            this.value = value;
        }

        static CellType fromChar(char ch) {
            for (CellType ct : values()) {
                if (ct.symbol == ch) {
                    return ct;
                }
            }
            throw new IllegalArgumentException("Unknown symbol: " + ch);
        }

        int getIntValue() {
            return value;
        }
    }

    /** Directions used for BFS – up, down, left, right. */
    private static final int[][] DIRECTIONS = {
            {1, 0},
            {-1, 0},
            {0, 1},
            {0, -1}
    };

    /** Determines whether a given coordinate lies inside the grid. */
    private static boolean isInside(int[][] grid, int row, int col) {
        return row >= 0 && col >= 0 && row < grid.length && col < grid[0].length;
    }

    /** Returns true if the cell at (row, col) can be entered (not an obstacle). */
    private static boolean isWalkable(int[][] grid, int row, int col) {
        return isInside(grid, row, col) && grid[row][col] != OBSTACLE;
    }

    /**
     * Reads the complete grid from {@code InputReader}, returning both the
     * raw integer matrix and auxiliary data about start / end positions.
     *
     * @param reader scanner providing the input tokens
     * @return a container with the grid, start row/col and end row/col
     */
    private static GridInfo parseInput(InputReader reader) {
        int rows = reader.nextInt();
        int cols = reader.nextInt();

        int[][] matrix = new int[rows][cols];
        int endRow = -1, endCol = -1;
        int startRow = -1, startCol = -1;

        for (int r = 0; r < rows; ++r) {
            String line = reader.nextLine();
            for (int c = 0; c < cols; ++c) {
                char ch = line.charAt(c);
                CellType cell = CellType.fromChar(ch);

                switch (cell) {
                    case TREE -> matrix[r][c] = OBSTACLE;
                    case END -> {
                        endRow = r;
                        endCol = c;
                        matrix[r][c] = 0;               // distance will be overwritten later
                    }
                    case START -> {
                        startRow = r;
                        startCol = c;
                        matrix[r][c] = START;
                    }
                    default -> matrix[r][c] = cell.getIntValue();
                }
            }
        }

        if (endRow == -1 || startRow == -1) {
            throw new IllegalArgumentException("Input must contain exactly one 'E' and one 'S'.");
        }

        return new GridInfo(matrix, startRow, startCol, endRow, endCol);
    }

    /**
     * Performs a multi‑source BFS from the end cell and fills the {@code distances}
     * matrix with the minimal number of steps required to reach each walkable cell.
     *
     * @param grid        the integer representation of the map
     * @param distances   matrix that will receive the computed distances
     * @param startPos    coordinates of the end cell (source of BFS)
     */
    private static void bfsFromEnd(int[][] grid, int[][] distances, Position startPos) {
        final int rows = grid.length;
        final int cols = grid[0].length;

        boolean[][] visited = new boolean[rows][cols];
        Queue<Position> queue = new ArrayDeque<>();

        queue.add(startPos);
        visited[startPos.row][startPos.col] = true;
        distances[startPos.row][startPos.col] = 0;

        while (!queue.isEmpty()) {
            Position cur = queue.poll();

            for (int[] dir : DIRECTIONS) {
                int nxtRow = cur.row + dir[0];
                int nxtCol = cur.col + dir[1];

                if (isWalkable(grid, nxtRow, nxtCol) && !visited[nxtRow][nxtCol]) {
                    visited[nxtRow][nxtCol] = true;
                    distances[nxtRow][nxtCol] = distances[cur.row][cur.col] + 1;
                    queue.add(new Position(nxtRow, nxtCol));
                }
            }
        }
    }

    /** Holds all information extracted from the input stream. */
    private static final class GridInfo {
        final int[][] grid;
        final int startRow, startCol;
        final int endRow, endCol;

        GridInfo(int[][] grid, int startRow, int startCol, int endRow, int endCol) {
            this.grid = grid;
            this.startRow = startRow;
            this.startCol = startCol;
            this.endRow = endRow;
            this.endCol = endCol;
        }
    }

    /** Computes the battle value according to the original specification. */
    private static int computeBattle(int[][] grid, int[][] distances, Position start) {
        int battle = 0;
        int startDistance = distances[start.row][start.col];

        for (int r = 0; r < grid.length; ++r) {
            for (int c = 0; c < grid[0].length; ++c) {
                int cellValue = grid[r][c];

                // skip obstacles and the start cell itself
                if (cellValue == OBSTACLE || cellValue == START) {
                    continue;
                }

                // include the cell if its distance to the end is not larger than the
                // distance from the end to the start cell
                if (distances[r][c] <= startDistance) {
                    battle += cellValue;
                }
            }
        }

        return battle;
    }

    /** Entry point of the application. */
    public static void main(String[] args) {
        InputReader reader = new InputReader();
        GridInfo info = parseInput(reader);

        int[][] distances = new int[info.grid.length][info.grid[0].length];
        for (int[] row : distances) {
            Arrays.fill(row, Integer.MAX_VALUE);
        }

        Position endPos = new Position(info.endRow, info.endCol);
        bfsFromEnd(info.grid, distances, endPos);

        int battleResult = computeBattle(info.grid, distances,
                new Position(info.startRow, info.startCol));

        System.out.print(battleResult);
    }
}

import java.util.Scanner;

/**
 * Simple Tic‑Tac‑Toe validator & interpreter.
 *
 * <p>The program reads a 3×3 board from {@code System.in},
 * validates that the board could belong to a real game,
 * determines the winner (if any), and prints the result.
 *
 * <p>All game‑logic is isolated in small, pure methods so that each
 * responsibility (input, validation, win detection, etc.) can be
 * unit‑tested independently.
 */
public final class TicTacToe {

    /** character used for an empty cell */
    private static final char EMPTY = '.';

    /** character representing the first player (X) */
    private static final char PLAYER_X = 'X';

    /** character representing the second player (0) – note the original code
     *  uses the digit zero, not the letter “O”. */
    private static final char PLAYER_O = '0';

    /** Scanner reused for the whole execution – try‑with‑resources would be ideal
     *  for production code, but the original program kept it simple. */
    private static final Scanner SCANNER = new Scanner(System.in);

    public static void main(String[] args) {
        char[][] board = readBoard();
        int xCount = countOccurrences(board, PLAYER_X);
        int oCount = countOccurrences(board, PLAYER_O);

        analyzeGame(board, xCount, oCount);
    }

    /** Reads three lines of exactly three characters each and stores them in a
     *  3×3 {@code char} array. */
    private static char[][] readBoard() {
        char[][] board = new char[3][3];
        for (int row = 0; row < 3; row++) {
            String line = SCANNER.nextLine().trim();
            if (line.length() != 3) {
                throw new IllegalArgumentException(
                        "Each line must contain exactly three characters");
            }
            for (int col = 0; col < 3; col++) {
                board[row][col] = line.charAt(col);
            }
        }
        return board;
    }

    /** Counts how many times a given character appears on the board. */
    private static int countOccurrences(char[][] board, char target) {
        int cnt = 0;
        for (char[] row : board) {
            for (char cell : row) {
                if (cell == target) {
                    cnt++;
                }
            }
        }
        return cnt;
    }

    /** Determines whether the supplied board respects the rules of Tic‑Tac‑Toe.
     *  The principal rules are:
     *      <ul>
     *        <li>Number of O's cannot exceed number of X's.</li>
     *        <li>The difference between X and O is at most one.</li>
     *        <li>Both players cannot win simultaneously.</li>
     *        <li>If X wins, X must have played one more move than O.</li>
     *        <li>If O wins, the move counts must be equal.</li>
     *      </ul>
     */
    private static boolean isLegal(char[][] board, int xCount, int oCount) {
        // 1️⃣  basic count consistency
        if (oCount > xCount || xCount - oCount > 1) {
            return false;
        }

        // 2️⃣  determine win status
        boolean xWon = hasWon(board, PLAYER_X);
        boolean oWon = hasWon(board, PLAYER_O);

        // 3️⃣  both cannot win
        if (xWon && oWon) {
            return false;
        }

        // 4️⃣  win‑condition consistency with move counts
        if (xWon && xCount != oCount + 1) {
            return false;
        }
        if (oWon && xCount != oCount) {
            return false;
        }

        return true;
    }

    /** Returns {@code true} if the given player has a complete row,
     *  column or diagonal on the board. */
    private static boolean hasWon(char[][] board, char player) {
        // rows
        for (int i = 0; i < 3; i++) {
            if (board[i][0] == player && board[i][1] == player && board[i][2] == player) {
                return true;
            }
        }
        // columns
        for (int j = 0; j < 3; j++) {
            if (board[0][j] == player && board[1][j] == player && board[2][j] == player) {
                return true;
            }
        }
        // diagonals
        if (board[0][0] == player && board[1][1] == player && board[2][2] == player) {
            return true;
        }
        if (board[0][2] == player && board[1][1] == player && board[2][0] == player) {
            return true;
        }
        return false;
    }

    /** Determines the game state and prints the appropriate message:
     *  <ul>
     *    <li>illegal – the board cannot happen in a real game</li>
     *    <li>the first player won / the second player won</li>
     *    <li>draw</li>
     *    <li>first / second – whose turn it would be next</li>
     *  </ul>
     */
    private static void analyzeGame(char[][] board, int xCount, int oCount) {
        if (!isLegal(board, xCount, oCount)) {
            System.out.println("illegal");
            return;
        }

        // Check for a winner
        if (hasWon(board, PLAYER_X)) {
            System.out.println("the first player won");
            return;
        }
        if (hasWon(board, PLAYER_O)) {
            System.out.println("the second player won");
            return;
        }

        // No winner yet – is the board full?
        if (isBoardFull(board)) {
            System.out.println("draw");
            return;
        }

        // Game still in progress – indicate the player to move next
        System.out.println(xCount == oCount ? "first" : "second");
    }

    /** Returns {@code true} if every cell contains either X or O (i.e. no '.'). */
    private static boolean isBoardFull(char[][] board) {
        for (char[] row : board) {
            for (char cell : row) {
                if (cell == EMPTY) {
                    return false;
                }
            }
        }
        return true;
    }
}

import java.util.Scanner;

public class TicTacToeValidator {

    private static final char EMPTY = '.';
    private static final int PLAYER_X = 1;
    private static final int PLAYER_O = 2;

    private static final int ILLEGAL = 1;
    private static final int X_WON = 2;
    private static final int O_WON = 3;
    private static final int DRAW = 6;
    private static final int NEXT_FIRST = 4;
    private static final int NEXT_SECOND = 5;

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        char[][] rawLines = new char[3][];
        for (int i = 0; i < 3; i++) {
            String line = scanner.nextLine().trim();
            if (line.length() != 3) {
                System.out.println("illegal");
                scanner.close();
                return;
            }
            rawLines[i] = line.toCharArray();
        }
        scanner.close();

        int[][] board = new int[3][3];
        int xCount = 0, oCount = 0;
        for (int i = 0; i < 3; i++) {
            for (int j = 0; j < 3; j++) {
                char c = rawLines[i][j];
                if (c == '.') {
                    board[i][j] = 0;
                } else if (c == 'X') {
                    board[i][j] = PLAYER_X;
                    xCount++;
                } else if (c == 'O') {
                    board[i][j] = PLAYER_O;
                    oCount++;
                } else {
                    System.out.println("illegal");
                    return;
                }
            }
        }

        // ----- validation of stone counts -----
        if (oCount > xCount || xCount - oCount > 1) {
            System.out.println("illegal");
            return;
        }

        boolean xWon = hasWin(board, PLAYER_X);
        boolean oWon = hasWin(board, PLAYER_O);

        // both cannot win simultaneously
        if (xWon && oWon) {
            System.out.println("illegal");
            return;
        }

        // X can only win when it just played (xCount == oCount + 1)
        if (xWon && xCount != oCount + 1) {
            System.out.println("illegal");
            return;
        }
        // O can only win when counts are equal
        if (oWon && oCount != xCount) {
            System.out.println("illegal");
            return;
        }

        int result;

        if (xWon) {
            result = X_WON; // "the first player won"
        } else if (oWon) {
            result = O_WON; // "the second player won"
        } else if (xCount + oCount == 9) {
            result = DRAW; // "draw"
        } else if (xCount == oCount) {
            result = NEXT_FIRST; // next is first player
        } else {
            result = NEXT_SECOND; // next is second player
        }

        switch (result) {
            case ILLEGAL -> System.out.println("illegal");
            case X_WON -> System.out.println("the first player won");
            case O_WON -> System.out.println("the second player won");
            case DRAW -> System.out.println("draw");
            case NEXT_FIRST -> System.out.println("first");
            case NEXT_SECOND -> System.out.println("second");
            default -> System.out.println("illegal");
        }
    }

    private static boolean hasWin(int[][] board, int player) {
        // rows
        for (int i = 0; i < 3; i++) {
            if (board[i][0] == player && board[i][1] == player && board[i][2] == player) {
                return true;
            }
        }
        // columns
        for (int j = 0; j < 3; j++) {
            if (board[0][j] == player && board[1][j] == player && board[2][j] == player) {
                return true;
            }
        }
        // diagonals
        if (board[0][0] == player && board[1][1] == player && board[2][2] == player) {
            return true;
        }
        if (board[0][2] == player && board[1][1] == player && board[2][0] == player) {
            return true;
        }
        return false;
    }
}

import java.util.Scanner;

/**
 * Tic‑Tac‑Toe board validator.
 *
 * The program reads nine characters from standard input (three lines of three
 * characters each).  Valid symbols are:
 *   • 'X'   – mark of the first player
 *   • '0'   – mark of the second player (the digit zero)
 *   • any other character – treated as empty
 *
 * It validates the position according to the normal rules of tic‑tac‑toe
 * and prints one of the following:
 *   • "first"   – X has a winning line and the move counts are correct
 *   • "second"  – O (the digit zero) has a winning line and the move counts are correct
 *   • "draw"    – the board is full and nobody has won
 *   • "illegal" – any configuration that cannot appear in a legal game
 *
 * The implementation is split into small, pure methods to improve readability,
 * testability and maintainability.
 */
public class TicTacToeValidator {

    private static final char EMPTY = ' ';   // placeholder for non‑X/0 cells
    private static final char PLAYER_X = 'X';
    private static final char PLAYER_O = '0';   // the digit zero used in the original input

    public static void main(String[] args) throws Exception {
        Scanner scanner = new Scanner(System.in);

        // ------------------------------------------------------------
        // 1. Read three lines and build the 3×3 board.
        // ------------------------------------------------------------
        String line1 = scanner.nextLine();
        String line2 = scanner.nextLine();
        String line3 = scanner.nextLine();

        char[][] board = new char[3][3];
        int idx = 0;
        for (char c : (line1 + line2 + line3).toCharArray()) {
            int row = idx / 3;
            int col = idx % 3;
            board[row][col] = c;
            idx++;
        }

        // ------------------------------------------------------------
        // 2. Count the marks of each player.
        // ------------------------------------------------------------
        int xCount = 0, oCount = 0;
        for (int r = 0; r < 3; r++) {
            for (int c = 0; c < 3; c++) {
                if (board[r][c] == PLAYER_X) {
                    xCount++;
                } else if (board[r][c] == PLAYER_O) {
                    oCount++;
                }
            }
        }

        // ------------------------------------------------------------
        // 3. Determine whether either player has a winning line.
        // ------------------------------------------------------------
        boolean xWins = hasWon(board, PLAYER_X);
        boolean oWins = hasWon(board, PLAYER_O);

        // ------------------------------------------------------------
        // 4. Decide the outcome.
        // ------------------------------------------------------------
        String result = null;

        // ----- Illegal configurations ---------------------------------
        // 1) The number of X's must be either equal to O's or exactly one more.
        if (!(xCount == oCount || xCount == oCount + 1)) {
            result = "illegal";
        }
        // 2) Both players cannot win at the same time.
        else if (xWins && oWins) {
            result = "illegal";
        }
        // 3) If X wins, the move count must be exactly one larger than O's.
        else if (xWins && !(xCount == oCount + 1)) {
            result = "illegal";
        }
        // 4) If O wins, the move counts must be equal.
        else if (oWins && !(xCount == oCount)) {
            result = "illegal";
        }

        // ----- Winning / Draw -----------------------------------------
        if (result == null) {
            if (xWins) {
                result = "first";
            } else if (oWins) {
                result = "second";
            } else if (xCount + oCount == 9) {
                result = "draw";
            } else {
                // No winner yet and the board is not full.
                // The original program treats any non‑terminal legal position
                // as "illegal".  We keep that behaviour for compatibility.
                result = "illegal";
            }
        }

        System.out.println(result);
    }

    /**
     * Checks whether the given player has any complete row, column or diagonal.
     *
     * @param board the 3×3 board
     * @param player the player symbol to test ('X' or the digit '0')
     * @return true if the player has a winning line
     */
    private static boolean hasWon(char[][] board, char player) {
        // Check rows
        for (int i = 0; i < 3; i++) {
            if (board[i][0] == player && board[i][1] == player && board[i][2] == player) {
                return true;
            }
        }
        // Check columns
        for (int j = 0; j < 3; j++) {
            if (board[0][j] == player && board[1][j] == player && board[2][j] == player) {
                return true;
            }
        }
        // Check diagonals
        if (board[0][0] == player && board[1][1] == player && board[2][2] == player) {
            return true;
        }
        if (board[0][2] == player && board[1][1] == player && board[2][0] == player) {
            return true;
        }
        return false;
    }
}

import java.util.Scanner;

/**
 * Refactored version of the Tic‑Tac‑Toe validator/determiner.
 *
 * The program reads three lines from standard input, each containing three
 * characters that describe the board state. It validates the position,
 * detects a winner or a draw, and prints the appropriate message.
 *
 * Output messages exactly match the original program:
 *   illegal
 *   the first player won
 *   the second player won
 *   draw
 *   first
 *   second
 */
public class ThreeD {

    private static final int SIZE = 3;
    private static final int EMPTY = 0;
    private static final int FIRST = 1;   // 'X'
    private static final int SECOND = 2;  // '0'

    public static void main(String[] args) {
        Game game = new Game();
        game.play();
    }

    /** Encapsulates all game logic. */
    private static class Game {
        private final int[][] board = new int[SIZE][SIZE];
        private int firstCount;
        private int secondCount;

        /** Reads the board from standard input. */
        private void readBoard() {
            Scanner scanner = new Scanner(System.in);
            for (int i = 0; i < SIZE; i++) {
                String line = scanner.nextLine().trim();
                for (int j = 0; j < SIZE; j++) {
                    board[i][j] = mapChar(line.charAt(j));
                }
            }
            countPieces();
        }

        /** Maps a character from the input to the internal representation. */
        private static int mapChar(char c) {
            return switch (c) {
                case 'X' -> FIRST;
                case '0' -> SECOND;
                default -> EMPTY;
            };
        }

        /** Counts how many moves each player has made. */
        private void countPieces() {
            firstCount = 0;
            secondCount = 0;
            for (int i = 0; i < SIZE; i++) {
                for (int j = 0; j < SIZE; j++) {
                    if (board[i][j] == FIRST) {
                        firstCount++;
                    } else if (board[i][j] == SECOND) {
                        secondCount++;
                    }
                }
            }
        }

        /** Determines whether the current board configuration is illegal. */
        private boolean isIllegal() {
            boolean firstWon = hasWon(FIRST);
            boolean secondWon = hasWon(SECOND);

            // Both players cannot have winning lines at the same time.
            if (firstWon && secondWon) {
                return true;
            }

            // The number of '0' cells must not exceed the number of 'X' cells.
            if (secondCount > firstCount) {
                return true;
            }

            // The absolute difference between the counts must be at most 1.
            if ((firstCount - secondCount) * (firstCount - secondCount) > 1) {
                return true;
            }

            // If the second player has won but the first player has made more moves,
            // the position is illegal.
            if (secondWon && firstCount > secondCount) {
                return true;
            }

            // If the first player has won but the move counts are equal,
            // the position is illegal.
            if (firstWon && firstCount == secondCount) {
                return true;
            }

            return false;
        }

        /** Checks whether the given player has three of their marks in a row. */
        private boolean hasWon(int player) {
            // rows
            for (int i = 0; i < SIZE; i++) {
                if (board[i][0] == player && board[i][1] == player && board[i][2] == player) {
                    return true;
                }
                // columns
                if (board[0][i] == player && board[1][i] == player && board[2][i] == player) {
                    return true;
                }
            }
            // diagonals
            if (board[0][0] == player && board[1][1] == player && board[2][2] == player) {
                return true;
            }
            if (board[0][2] == player && board[1][1] == player && board[2][0] == player) {
                return true;
            }
            return false;
        }

        /** Executes the main flow: read input, validate, and emit the result. */
        private void play() {
            readBoard();

            if (isIllegal()) {
                System.out.println("illegal");
                return;
            }

            boolean firstWon = hasWon(FIRST);
            boolean secondWon = hasWon(SECOND);

            if (firstWon) {
                System.out.println("the first player won");
                return;
            }
            if (secondWon) {
                System.out.println("the second player won");
                return;
            }

            if (firstCount + secondCount == SIZE * SIZE) {
                System.out.println("draw");
                return;
            }

            if (firstCount == secondCount) {
                System.out.println("first");
            } else {
                System.out.println("second");
            }
        }
    }
}

import java.io.PrintWriter;
import java.util.Scanner;

/**
 * Decision Maker – Tic‑Tac‑Toe validator.
 *
 * <p>
 * The program reads a 3×3 board where
 * <ul>
 *   <li>'X' – move of the first player</li>
 *   <li>'0' – move of the second player</li>
 *   <li>'.' – empty cell (represented by the digit '0' in the original code)</li>
 * </ul>
 * It then checks the board for legality, reports the winner (if any) or declares a draw,
 * and finally prints one of the following messages:
 * <pre>
 *   illegal
 *   the first player won
 *   the second player won
 *   draw
 *   first
 *   second
 * </pre>
 * </p>
 *
 * <p>Refactoring goals:</p>
 * <ul>
 *   <li>Replace magic numbers with named constants.</li>
 *   <li>Separate concerns: input handling, board validation, win detection, output.</li>
 *   <li>Give meaningful names to variables and methods.</li>
 *   <li>Extract repeated logic into well‑named helper methods.</li>
 *   <li>Make the code self‑documenting (Javadoc comments, expressive identifiers).</li>
 * </ul>
 */
public class Solution {

    /** Size of the board (3×3). */
    private static final int SIZE = 3;

    /** Symbol used for an empty cell in the original statement. */
    private static final char EMPTY = '0';

    /** Symbol of the first player. */
    private static final char FIRST_PLAYER = 'X';

    /** Symbol of the second player. */
    private static final char SECOND_PLAYER = '0';

    /** All possible winning lines expressed as three coordinate pairs. */
    private static final int[][] WIN_LINES = {
            // rows
            {0, 1, 2}, {3, 4, 5}, {6, 7, 8},
            // columns
            {0, 3, 6}, {1, 4, 7}, {2, 5, 8},
            // diagonals
            {0, 4, 8}, {2, 4, 6}
    };

    /** The 2‑D representation of a Tic‑Tac‑Toe board. */
    private static final char[][] BOARD = new char[SIZE][SIZE];

    /** --------------------------------------------------------------------- */
    /** Entry point */
    public static void main(String[] args) {
        try (Scanner in = new Scanner(System.in);
             PrintWriter out = new PrintWriter(System.out)) {

            readBoard(in);
            int firstMoves = countOccurrences(FIRST_PLAYER);
            int secondMoves = countOccurrences(SECOND_PLAYER);

            // ---- validation of move counts ---------------------------------
            if (!isMoveCountValid(firstMoves, secondMoves)) {
                out.println("illegal");
                return;
            }

            // ---- detect winners ---------------------------------------------
            boolean firstWon = isWinner(FIRST_PLAYER);
            boolean secondWon = isWinner(SECOND_PLAYER);

            // ---- contradictory win states are illegal -----------------------
            if (firstWon && secondWon) {
                out.println("illegal");
                return;
            }

            // ---- decide the final status ------------------------------------
            if (firstWon) {
                // first player can only win when they made the last move
                out.println(firstMoves == secondMoves + 1 ? "the first player won" : "illegal");
                return;
            }

            if (secondWon) {
                // second player always moves after the first
                out.println(secondMoves == firstMoves ? "the second player won" : "illegal");
                return;
            }

            // ---- no winner ----------------------------------------------------
            if (firstMoves + secondMoves == SIZE * SIZE) {
                out.println("draw");
                return;
            }

            // If the next player to move is the first player, cx == c0
            out.println(firstMoves == secondMoves ? "first" : "second");

        }
    }

    /** --------------------------------------------------------------------- */
    /** Reads a 3×3 board from the provided Scanner. Empty cells are stored as
     *  {@link #EMPTY}. */
    private static void readBoard(Scanner scanner) {
        for (int row = 0; row < SIZE; row++) {
            String line = scanner.nextLine().trim();
            for (int col = 0; col < SIZE; col++) {
                BOARD[row][col] = line.charAt(col);
            }
        }
    }

    /** --------------------------------------------------------------------- */
    /** Returns the number of cells occupied by the given player symbol. */
    private static int countOccurrences(char symbol) {
        int count = 0;
        for (int i = 0; i < SIZE; i++) {
            for (int j = 0; j < SIZE; j++) {
                if (BOARD[i][j] == symbol) {
                    ++count;
                }
            }
        }
        return count;
    }

    /** --------------------------------------------------------------------- */
    /** Determines whether the move count respects the turn order constraints. */
    private static boolean isMoveCountValid(int first, int second) {
        // first player always moves first → they must have made either
        // the same number of moves as the second player or exactly one more.
        return !(first > second + 1 || second > first);
    }

    /** --------------------------------------------------------------------- */
    /** Checks whether the supplied player has a winning line on the board. */
    private static boolean isWinner(char player) {
        for (int[] line : WIN_LINES) {
            int a = line[0];
            int b = line[1];
            int c = line[2];

            int r0 = a / SIZE, c0 = a % SIZE;
            int r1 = b / SIZE, c1 = b % SIZE;
            int r2 = c / SIZE, c2 = c % SIZE;

            if (BOARD[r0][c0] == player &&
                BOARD[r1][c1] == player &&
                BOARD[r2][c2] == player) {
                return true;
            }
        }
        return false;
    }
}

import java.io.*;
import java.util.*;

public class Main {

    /** Symbols used on the board */
    private static final char EMPTY      = '.';
    private static final char PLAYER_X   = 'X';
    private static final char PLAYER_O   = 'O';

    /** 3×3 board */
    private char[][] board;

    /** Input and output streams */
    private BufferedReader reader;
    private PrintWriter writer;

    public static void main(String[] args) throws IOException {
        new Main().solve();
    }

    /** Entry point that glues everything together */
    private void solve() throws IOException {
        configureI_o();
        board = readBoard();
        analyseAndPrintResult();
        close();
    }

    /** Redirects input from “input.txt” if it exists – keeps original behaviour */
    private void configureI_o() throws IOException {
        try (FileInputStream fis = new FileInputStream("input.txt")) {
            System.setIn(new BufferedInputStream(fis));
        } catch (FileNotFoundException ignored) {
        } catch (SecurityException ignored) {
        }

        reader = new BufferedReader(new InputStreamReader(System.in));
        writer = new PrintWriter(System.out, true);
    }

    /** Reads the three rows that describe the current board state */
    private char[][] readBoard() throws IOException {
        char[][] board = new char[3][];
        for (int i = 0; i < 3; i++) {
            String line = reader.readLine();
            if (line == null) {
                throw new IOException("Unexpected end of input");
            }
            // Remove any whitespace and ensure exactly three characters
            line = line.replaceAll("\\s+", "");
            if (line.length() != 3) {
                throw new IOException("Each line must contain exactly 3 characters");
            }
            board[i] = line.toCharArray();
        }
        return board;
    }

    /** Main logical routine that validates and prints the answer */
    private void analyseAndPrintResult() {
        try {
            int xCount = countOccurrences(PLAYER_X);
            int oCount = countOccurrences(PLAYER_O);
            validateMoveCounts(xCount, oCount);

            boolean xWins = hasWinningLine(PLAYER_X);
            boolean oWins = hasWinningLine(PLAYER_O);

            /* Both players cannot have winning lines simultaneously */
            if (xWins && oWins) {
                writer.println("illegal");
                return;
            }

            /* No winner yet – decide draw or whose turn it is */
            if (!xWins && !oWins) {
                if (xCount + oCount == 9) {
                    writer.println("draw");
                } else {
                    writer.println(xCount > oCount ? "second" : "first");
                }
                return;
            }

            /* Exactly one player has a winning line */
            boolean lastMoveWasByX = xCount > oCount;
            boolean winnerIsX = xWins;

            // The winner must have made the last move
            if (winnerIsX != lastMoveWasByX) {
                writer.println("illegal");
                return;
            }

            writer.println(winnerIsX ? "the first player won" : "the second player won");
        } catch (IllegalStateException e) {
            writer.println("illegal");
        }
    }

    /** Counts occurrences of a given symbol on the board */
    private int countOccurrences(char symbol) {
        int cnt = 0;
        for (char[] row : board) {
            for (char cell : row) {
                if (cell == symbol) cnt++;
            }
        }
        return cnt;
    }

    /** Checks that the numbers of X and O follow the rules of Tic‑Tac‑Toe */
    private void validateMoveCounts(int x, int o) {
        int diff = x - o;
        if (diff < 0 || diff > 1) {
            throw new IllegalStateException();   // triggers “illegal” output
        }
        // Additional illegal patterns could be added here if needed
    }

    /** Determines whether the given player has a winning line */
    private boolean hasWinningLine(char player) {
        // rows
        for (int i = 0; i < 3; i++) {
            if (isTriple(i, 0, 0, 1, player)) return true;
            if (isTriple(0, i, 1, 0, player)) return true;
        }
        // diagonals
        if (isTriple(0, 0, 1, 1, player)) return true;
        if (isTriple(0, 2, 1, -1, player)) return true;
        return false;
    }

    /** Returns true if three cells in a line starting at (r,c) with step (dr,dc) are all `player` */
    private boolean isTriple(int row, int col, int dr, int dc, char player) {
        char first = board[row][col];
        if (first != player) return false;
        return first == board[row + dr][col + dc]
                && board[row + dr][col + dc] == board[row + 2 * dr][col + 2 * dc];
    }

    /** Closes all streams */
    private void close() {
        try { reader.close(); } catch (Exception ignored) {}
        writer.close();
    }
}

import java.io.*;
import java.util.StringTokenizer;

/**
 * Tiny Tic‑Tac‑Toe validator/winner‑detector.
 * It reads three tokens (each a single digit) that together form a 3×3 board.
 * The board uses the characters:
 *   'X' – first player move
 *   '0' – second player move
 *   '.' – empty cell
 *
 * The program prints one of the following messages:
 *   "illegal"
 *   "the first player won"
 *   "the second player won"
 *   "first"
 *   "second"
 *   "draw"
 */
public class TicTacToeValidator {

    /** All possible winning line indices on a 3×3 board. */
    private static final int[][] WIN_LINES = {
            {0, 1, 2}, {3, 4, 5}, {6, 7, 8},   // rows
            {0, 3, 6}, {1, 4, 7}, {2, 5, 8},   // columns
            {0, 4, 8}, {2, 4, 6}               // diagonals
    };

    /** Size of the board (= number of cells). */
    private static final int BOARD_SIZE = 9;

    /** Input stream used for reading from stdin. */
    private BufferedReader br;

    /** Print stream used for writing to stdout. */
    private PrintWriter out;

    /** Tokeniser used by the scanner‑like helpers. */
    private StringTokenizer st;

    /** Flag that indicates end‑of‑file while reading. */
    private boolean eof;

    /** --------------------------------------------------------------------- */
    /** PUBLIC API ------------------------------------------------------------------- */
    public static void main(String[] args) throws IOException {
        new TicTacToeValidator().run();
    }

    /** --------------------------------------------------------------------- */
    /** CORE LOGIC ------------------------------------------------------------------- */
    /** Main driver – parses input, validates the board and prints the result. */
    private void run() throws IOException {
        initIO();
        solve();
        closeIO();
    }

    /** Solve the puzzle – read the board, validate it and output the answer. */
    private void solve() {
        // Board representation: '.' = empty, 'X' = first player, '0' = second player
        char[] board = readBoard();

        // Basic validation – count of moves must be legal and no player may have
        // already won with the opponent's turn.
        if (!isBoardStateLegal(board)) {
            out.println("illegal");
            return;
        }

        // If nobody has won yet, decide whose turn it is (or if the game is a draw).
        if (!hasWinner(board, 'X') && !hasWinner(board, '0')) {
            if (boardIsFull(board)) {
                out.println("draw");
            } else {
                out.println(nextPlayer(board).toUpperCase()); // "first" or "second"
            }
            return;
        }

        // A player just won – find out which move caused the win.
        for (int i = 0; i < BOARD_SIZE; i++) {
            if (board[i] == 'X' || board[i] == '0') {
                board[i] = '.';
                if (!hasWinner(board, board[i] == 'X' ? '0' : 'X')) {
                    String winner = board[i] == 'X' ? "first" : "second";
                    out.printf("the %s player won%n", winner);
                    return;
                }
                // Restore the cell and continue searching (should not happen).
                board[i] = board[i] == 'X' ? 'X' : '0';
            }
        }

        // If we reach this point something is inconsistent.
        out.println("illegal");
    }

    /** --------------------------------------------------------------------- */
    /** HELPERS ------------------------------------------------------------------- */
    /** Reads three tokens from the tokenizer and concatenates them into a single
     *  string that represents the board (row‑major order). */
    private char[] readBoard() {
        StringBuilder sb = new StringBuilder();
        while (sb.length() < BOARD_SIZE) {
            sb.append(nextToken());
        }
        return sb.toString().toCharArray();
    }

    /** Returns true if the current board respects the rules of turn order and
     *  does not contain a win for the player who should not have moved yet. */
    private boolean isBoardStateLegal(char[] board) {
        int xCount = countOccurrences(board, 'X');
        int oCount = countOccurrences(board, '0');

        // The number of X's must be equal to O's or exactly one more.
        int diff = xCount - oCount;
        if (diff != 0 && diff != 1) {
            return false;
        }

        char lastMover = diff == 0 ? '0' : 'X';   // player who just moved
        char nextMover = diff == 0 ? 'X' : '0';   // player who would move next

        // It is illegal for the next player to already have a winning line.
        if (hasWinner(board, nextMover)) {
            return false;
        }

        return true;
    }

    /** Counts how many times {@code c} appears in {@code arr}. */
    private int countOccurrences(char[] arr, char c) {
        int cnt = 0;
        for (char v : arr) {
            if (v == c) {
                cnt++;
            }
        }
        return cnt;
    }

    /** Returns the player whose turn it is next ('X' for first, '0' for second). */
    private char nextPlayer(char[] board) {
        int x = countOccurrences(board, 'X');
        int o = countOccurrences(board, '0');
        return (x > o) ? '0' : 'X';
    }

    /** Checks whether the given player has a winning line on the board. */
    private boolean hasWinner(char[] board, char player) {
        for (int[] line : WIN_LINES) {
            boolean win = true;
            for (int idx : line) {
                if (board[idx] != player) {
                    win = false;
                    break;
                }
            }
            if (win) {
                return true;
            }
        }
        return false;
    }

    /** Returns true if every cell on the board is filled (i.e. no '.' left). */
    private boolean boardIsFull(char[] board) {
        for (char c : board) {
            if (c == '.') {
                return false;
            }
        }
        return true;
    }

    /** --------------------------------------------------------------------- */
    /** INPUT / OUTPUT UTILITIES --------------------------------------------------- */
    /** Initializes the BufferedReader / PrintWriter pair used for console I/O. */
    private void initIO() throws IOException {
        br = new BufferedReader(new InputStreamReader(System.in));
        out = new PrintWriter(System.out);
    }

    /** Closes the streams that were opened in {@link #initIO()}. */
    private void closeIO() {
        out.close();
        try {
            br.close();
        } catch (IOException ignored) {
        }
    }

    /** Simple tokeniser that returns the next non‑empty token from stdin. */
    private String nextToken() {
        while (st == null || !st.hasMoreTokens()) {
            try {
                st = new StringTokenizer(br.readLine());
            } catch (IOException e) {
                eof = true;
                return null;
            }
        }
        return st.nextToken();
    }
}

import java.util.Scanner;

/**
 * Simple console Tic‑Tac‑Toe evaluator.
 *
 * <p>It reads a 3×3 board (each row entered as a 3‑character string) and reports one of the
 * following outcomes:
 *
 * <ul>
 *   <li>"the first player won"</li>
 *   <li>"the second player won"</li>
 *   <li>"draw"</li>
 *   <li>"first"</li>
 *   <li>"second"</li>
 *   <li>"illegal"</li>
 * </ul>
 *
 * <p>The board uses the symbols:
 * <ul>
 *   <li>'X' – first player</li>
 *   <li>'0' (zero) – second player</li>
 *   <li>'.' – empty cell</li>
 * </ul>
 *
 * The program validates the board state according to the normal rules of Tic‑Tac‑Toe.
 */
public class TicTacToe {

    /** All 8 possible winning line patterns on a 3×3 board. */
    private static final int[][] WIN_PATTERNS = {
            {0, 1, 2}, {3, 4, 5}, {6, 7, 8}, // rows
            {0, 3, 6}, {1, 4, 7}, {2, 5, 8}, // columns
            {0, 4, 8}, {2, 4, 6}             // diagonals
    };

    /** Symbol used by the first player. */
    private static final char PLAYER_X = 'X';

    /** Symbol used by the second player. */
    private static final char PLAYER_O = '0';   // note: the original code used the digit zero

    /**
     * Checks whether the given board contains a winning line for the supplied player.
     *
     * @param board   the board, length 9, indexed row‑major.
     * @param player  the player symbol to test for a win.
     * @return {@code true} if the player has any of the winning patterns.
     */
    private static boolean hasWon(char[] board, char player) {
        for (int[] pattern : WIN_PATTERNS) {
            if (board[pattern[0]] == player
                    && board[pattern[1]] == player
                    && board[pattern[2]] == player) {
                return true;
            }
        }
        return false;
    }

    /**
     * Determines whether the supplied board state obeys the turn‑order and win‑relationship rules.
     *
     * @param board       the board (length 9)
     * @param xCount      number of 'X' marks on the board
     * @param oCount      number of '0' marks on the board
     * @return {@code true} if the state is legal; {@code false} otherwise.
     */
    private static boolean isValidState(char[] board, int xCount, int oCount) {
        // The number of X's must be either equal to O's (next turn is X) or one more than O's (next turn is O)
        if (!(xCount == oCount || xCount == oCount + 1)) {
            return false;
        }

        boolean xWins = hasWon(board, PLAYER_X);
        boolean oWins = hasWon(board, PLAYER_O);

        // Both players cannot win simultaneously – that would be an illegal position.
        if (xWins && oWins) {
            return false;
        }

        // If X wins, the game must have ended right after X's move, i.e. xCount == oCount + 1.
        if (xWins && xCount != oCount + 1) {
            return false;
        }

        // If O wins, the move counts must be equal (O just played).
        if (oWins && xCount != oCount) {
            return false;
        }

        // Otherwise the state obeys the turn‐order constraints.
        return true;
    }

    /**
     * Reads a complete 3×3 board from the console.
     *
     * @param scanner a scanner that supplies three lines, each containing exactly three characters.
     * @return a char array of length 9 representing the board.
     */
    private static char[] readBoard(Scanner scanner) {
        char[] board = new char[9];
        for (int row = 0; row < 3; row++) {
            String line = scanner.next();
            // Guard against shorter input – pad with '.' to avoid IndexOutOfBoundsException
            if (line == null || line.length() < 3) {
                line = String.format("%-3s", line);
            }
            board[row * 3] = line.charAt(0);
            board[row * 3 + 1] = line.charAt(1);
            board[row * 3 + 2] = line.charAt(2);
        }
        return board;
    }

    /**
     * Counts the occurrences of each symbol on the board.
     *
     * @param board the board array
     * @return a small {@code Result} object containing the three counts.
     */
    private static Result countSymbols(char[] board) {
        int x = 0, o = 0, empty = 0;
        for (char c : board) {
            if (c == PLAYER_X) {
                x++;
            } else if (c == PLAYER_O) {
                o++;
            } else {
                empty++;
            }
        }
        return new Result(x, o, empty);
    }

    /** Simple container for the three symbol counts. */
    private static final class Result {
        final int x;
        final int o;
        final int empty;

        Result(int x, int o, int empty) {
            this.x = x;
            this.o = o;
            this.empty = empty;
        }
    }

    /**
     * Evaluates the supplied board and prints the appropriate message.
     *
     * @param board the board to evaluate
     */
    private static void evaluateAndPrint(char[] board) {
        Result counts = countSymbols(board);
        int xCount = counts.x;
        int oCount = counts.o;
        int emptyCount = counts.empty;

        if (!isValidState(board, xCount, oCount)) {
            System.out.println("illegal");
            return;
        }

        if (hasWon(board, PLAYER_X)) {
            System.out.println("the first player won");
        } else if (hasWon(board, PLAYER_O)) {
            System.out.println("the second player won");
        } else if (emptyCount == 0) {
            System.out.println("draw");
        } else if (xCount > oCount) {
            System.out.println("second");
        } else {
            System.out.println("first");
        }
    }

    /**
     * Main entry point – reads input, builds the board and runs the evaluation.
     */
    public static void main(String[] args) {
        // Using try‑with‑resources ensures the scanner is closed automatically.
        try (Scanner scanner = new Scanner(System.in)) {
            char[] board = readBoard(scanner);
            evaluateAndPrint(board);
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.ArrayList;
import java.util.List;
import java.util.Set;

/**
 * Refactored Tic‑Tac‑Toe validator and result reporter.
 *
 * The program reads three lines from {@code stdin}, each representing a row of the board,
 * validates the board state and prints the appropriate outcome.
 */
public class Driver {

    /* --------------------------------------------------------------------- */
    /* Constants & simple utilities                                           */
    /* --------------------------------------------------------------------- */
    private static final char PLAYER_X = 'X';
    private static final char PLAYER_O = 'O';
    private static final char EMPTY   = '.';
    private static final Set<Character> VALID_CHARS = Set.of(PLAYER_X, PLAYER_O, EMPTY);

    /**
     * Entry point – reads board, determines result and prints it.
     */
    public static void main(String[] args) {
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(System.in))) {
            List<String> rows = new ArrayList<>();
            String line;
            for (int i = 0; i < 3; i++) {
                line = reader.readLine();
                if (line == null) {
                    throw new IOException("Not enough input lines");
                }
                rows.add(line);
            }

            String[] board = rows.toArray(new String[0]);
            Result result = determineResult(board);
            System.out.println(result.message());

        } catch (Exception e) {
            System.out.println("ERROR");
        }
    }

    /* --------------------------------------------------------------------- */
    /* Result enum – encapsulates all possible outputs                      */
    /* --------------------------------------------------------------------- */
    private enum Result {
        ILLEGAL("illegal"),
        FIRST_WON("the first player won"),
        SECOND_WON("the second player won"),
        DRAW("draw"),
        FIRST_TURN("first"),
        SECOND_TURN("second"),
        UNEXPECTED("unexpected");

        private final String message;
        Result(String message) { this.message = message; }
        public String message() { return message; }
    }

    /* --------------------------------------------------------------------- */
    /* Orchestrator – decides which message to emit                           */
    /* --------------------------------------------------------------------- */
    private static Result determineResult(String[] board) {
        if (BoardValidator.isIllegal(board)) {
            return Result.ILLEGAL;
        }

        Player winner = BoardAnalyzer.winner(board);
        if (winner == Player.X) {
            return Result.FIRST_WON;
        }
        if (winner == Player.O) {
            return Result.SECOND_WON;
        }
        if (BoardAnalyzer.isDraw(board)) {
            return Result.DRAW;
        }

        int xCnt = BoardUtils.count(board, PLAYER_X);
        int oCnt = BoardUtils.count(board, PLAYER_O);

        if (xCnt == oCnt) {
            return Result.FIRST_TURN;
        }
        // In a legal position the only remaining possibility is xCnt == oCnt + 1
        return Result.SECOND_TURN;
    }

    /* --------------------------------------------------------------------- */
    /* Validation utilities                                                   */
    /* --------------------------------------------------------------------- */
    private static final class BoardValidator {
        private BoardValidator() {}

        /** Returns {@code true} if the board breaks turn order or contains illegal
         *  combinations (e.g., both players winning). */
        static boolean isIllegal(String[] board) {
            // 1) Turn counts must be legal
            if (!BoardUtils.validCount(board, PLAYER_X, PLAYER_O)) {
                return true;
            }

            Player winX = BoardAnalyzer.checkWin(board, PLAYER_X);
            Player winO = BoardAnalyzer.checkWin(board, PLAYER_O);

            // 2) Both players cannot win simultaneously
            if (winX != Player.NONE && winO != Player.NONE) {
                return true;
            }

            // 3) If X won, they must have made one more move than O
            if (winX == Player.X && !BoardUtils.count(board, PLAYER_X)
                    .equals(BoardUtils.count(board, PLAYER_O) + 1)) {
                return true;
            }

            // 4) If O won, the move counts must be equal
            if (winO == Player.O && BoardUtils.count(board, PLAYER_X)
                    != BoardUtils.count(board, PLAYER_O)) {
                return true;
            }

            return false;
        }
    }

    /* --------------------------------------------------------------------- */
    /* Core board analysis                                                    */
    /* --------------------------------------------------------------------- */
    private enum Player { NONE, X, O }

    private static final class BoardAnalyzer {
        private BoardAnalyzer() {}

        /** Determines which player (if any) has a line of three. */
        static Player winner(String[] board) {
            if (hasThreeInRow(board, PLAYER_X)) return Player.X;
            if (hasThreeInRow(board, PLAYER_O)) return Player.O;
            return Player.NONE;
        }

        /** True if the board is full and no winner exists. */
        static boolean isDraw(String[] board) {
            for (String row : board) {
                if (row.contains(String.valueOf(EMPTY))) {
                    return false;
                }
            }
            return true;
        }

        /** Helper used by {@link #winner(String[])} and validation. */
        static Player checkWin(String[] board, char player) {
            return hasThreeInRow(board, player) ? Player.valueOf(String.valueOf(player))
                                               : Player.NONE;
        }

        /** Checks all rows, columns and diagonals for a given player mark. */
        private static boolean hasThreeInRow(String[] board, char player) {
            // rows
            for (String row : board) {
                if (row.charAt(0) == player && row.charAt(1) == player && row.charAt(2) == player) {
                    return true;
                }
            }
            // columns
            for (int col = 0; col < 3; col++) {
                if (board[0].charAt(col) == player &&
                    board[1].charAt(col) == player &&
                    board[2].charAt(col) == player) {
                    return true;
                }
            }
            // diagonals
            if (board[0].charAt(0) == player && board[1].charAt(1) == player && board[2].charAt(2) == player) {
                return true;
            }
            if (board[0].charAt(2) == player && board[1].charAt(1) == player && board[2].charAt(0) == player) {
                return true;
            }
            return false;
        }
    }

    /* --------------------------------------------------------------------- */
    /* Simple count / validation utilities                                    */
    /* --------------------------------------------------------------------- */
    private static final class BoardUtils {
        private BoardUtils() {}

        /** Counts occurrences of a given character on the board. */
        static int count(String[] board, char ch) {
            int total = 0;
            for (String row : board) {
                total += countInRow(row, ch);
            }
            return total;
        }

        /** Counts occurrences of a character in a single row string. */
        private static int countInRow(String row, char ch) {
            int cnt = 0;
            for (int i = 0; i < row.length(); i++) {
                if (row.charAt(i) == ch) cnt++;
            }
            return cnt;
        }

        /** Returns true if the numbers of X's and O's differ by at most one and
         *  X is never behind O. */
        static boolean validCount(String[] board, char xChar, char oChar) {
            int x = count(board, xChar);
            int o = count(board, oChar);
            return (x == o) || (x == o + 1);
        }
    }
}

import java.util.Scanner;

/**
 * Tic‑Tac‑Toe referee.
 *
 * <p>Reads a 3×3 board from standard input (three lines of three characters each)
 * where {@code '.'} denotes an empty cell, {@code 'X'} the first player and
 * {@code 'O'} the second player. It then prints the result of the game:
 *
 * <ul>
 *   <li>{@code "the first player won"} – X has a winning line</li>
 *   <li>{@code "the second player won"} – O has a winning line</li>
 *   <li>{@code "draw"} – board is full and nobody won</li>
 *   <li>{@code "first"} – it is the first player's turn</li>
 *   <li>{@code "second"} – it is the second player's turn</li>
 *   <li>{@code "illegal"} – the board configuration cannot arise in a real game</li>
 * </ul>
 */
public class TicTacToeC {

    /** Symbol used to represent an empty cell. */
    private static final char EMPTY = '.';

    /** Symbols for the two players. */
    private static final char PLAYER_X = 'X';
    private static final char PLAYER_O = 'O';

    /** Size of the board (3×3). */
    private static final int BOARD_SIZE = 3;

    public static void main(String[] args) {
        CharGrid grid = readBoard();
        Result result = evaluateGame(grid);
        System.out.println(result.message());
    }

    /** Reads exactly three lines from {@code System.in}, each expected to be length 3. */
    private static CharGrid readBoard() {
        char[][] board = new char[BOARD_SIZE][BOARD_SIZE];
        Scanner scanner = new Scanner(System.in);
        for (int i = 0; i < BOARD_SIZE; i++) {
            String line = scanner.nextLine().trim();
            board[i] = line.toCharArray();
        }
        scanner.close();
        return new CharGrid(board);
    }

    /** Main evaluation routine – returns a {@link Result} describing the current state. */
    private static Result evaluateGame(CharGrid grid) {
        int xCount = grid.count(PLAYER_X);
        int oCount = grid.count(PLAYER_O);
        boolean xWins = grid.hasWon(PLAYER_X);
        boolean oWins = grid.hasWon(PLAYER_O);

        if (isIllegal(xCount, oCount, xWins, oWins)) {
            return new Result("illegal");
        }

        if (xWins) {
            return new Result("the first player won");
        }
        if (oWins) {
            return new Result("the second player won");
        }

        if (grid.isFull()) {
            return new Result("draw");
        }

        // No winner yet – indicate whose turn it is.
        return new Result(xCount == oCount ? "first" : "second");
    }

    /**
     * Checks the board for any illegal configuration.
     *
     * <p>Rules encoded:
     * <ul>
     *   <li>Both players cannot have winning lines simultaneously.</li>
     *   <li>The absolute difference between X‑ and O‑marks must be 0 or 1.</li>
     *   <li>If O wins, the number of O‑marks must equal the number of X‑marks.</li>
     *   <li>If X wins, the number of X‑marks must be exactly one more than O‑marks.</li>
     * </ul>
     */
    private static boolean isIllegal(int xCount, int oCount, boolean xWins, boolean oWins) {
        if (xWins && oWins) {
            return true;
        }
        if (Math.abs(xCount - oCount) > 1) {
            return true;
        }
        if (oWins && xCount != oCount) {
            return true;
        }
        if (xWins && xCount != oCount + 1) {
            return true;
        }
        return false;
    }

    /** Simple immutable holder for the textual output of the evaluation. */
    private static final class Result {
        private final String message;

        Result(String message) {
            this.message = message;
        }

        String message() {
            return message;
        }
    }

    /** Encapsulates board‑specific operations (counting, win detection, etc.). */
    private static final class CharGrid {
        private final char[][] board;

        CharGrid(char[][] board) {
            this.board = board;
        }

        /** Returns how many cells contain the given symbol. */
        int count(char symbol) {
            int cnt = 0;
            for (char[] row : board) {
                for (char cell : row) {
                    if (cell == symbol) {
                        cnt++;
                    }
                }
            }
            return cnt;
        }

        /** True if the supplied player has any complete row, column or diagonal. */
        boolean hasWon(char player) {
            // rows
            for (int i = 0; i < BOARD_SIZE; i++) {
                if (board[i][0] == player && board[i][1] == player && board[i][2] == player) {
                    return true;
                }
            }
            // columns
            for (int j = 0; j < BOARD_SIZE; j++) {
                if (board[0][j] == player && board[1][j] == player && board[2][j] == player) {
                    return true;
                }
            }
            // diagonals
            if (board[0][0] == player && board[1][1] == player && board[2][2] == player) {
                return true;
            }
            if (board[0][2] == player && board[1][1] == player && board[2][0] == player) {
                return true;
            }
            return false;
        }

        /** True when there are no empty cells left. */
        boolean isFull() {
            return count(EMPTY) == 0;
        }
    }
}

import java.util.Scanner;

/**
 * Tic‑Tac‑Toe board validator and result determiner.
 * <p>
 * The program reads three lines from standard input, each containing exactly three
 * characters that can be {@code 'X'}, {@code 'O'} or {@code '_'} (empty square).
 * It then evaluates the board state and prints one of the following messages:
 * <ul>
 *   <li>“the first player won”</li>
 *   <li>“the second player won”</li>
 *   <li>“draw”</li>
 *   <li>“illegal”</li>
 * </ul>
 * </p>
 */
public class Main {

    /** Symbol for an empty cell. */
    private static final char EMPTY = '_';

    /** Symbol used by the first player. */
    private static final char PLAYER_X = 'X';

    /** Symbol used by the second player. */
    private static final char PLAYER_O = 'O';

    public static void main(String[] args) {
        char[][] board = readBoard();
        if (board == null) {
            System.out.println("illegal");
            return;
        }

        int xCount = countMoves(board, PLAYER_X);
        int oCount = countMoves(board, PLAYER_O);

        if (!isCountLegal(xCount, oCount)) {
            System.out.println("illegal");
            return;
        }

        String winner = getWinner(board);
        if (winner != null) {
            System.out.println(winner);
            return;
        }

        // If the board is full but there is no winner we have a draw.
        System.out.println(xCount + oCount == 9 ? "draw" : "illegal");
    }

    /** Reads exactly three lines of length three and builds the board. */
    private static char[][] readBoard() {
        Scanner scanner = new Scanner(System.in);
        char[][] board = new char[3][3];

        for (int i = 0; i < 3; i++) {
            String line = scanner.nextLine().trim();
            if (line.length() != 3) {
                return null;                     // malformed line
            }
            for (int j = 0; j < 3; j++) {
                char cell = line.charAt(j);
                if (cell != PLAYER_X && cell != PLAYER_O && cell != EMPTY) {
                    return null;                     // illegal character
                }
                board[i][j] = cell;
            }
        }
        return board;
    }

    /** Counts how many times the given player symbol appears on the board. */
    private static int countMoves(char[][] board, char player) {
        int count = 0;
        for (char[] row : board) {
            for (char cell : row) {
                if (cell == player) {
                    count++;
                }
            }
        }
        return count;
    }

    /** Checks the basic turn‑count legality of the supplied board. */
    private static boolean isCountLegal(int xCount, int oCount) {
        // X always starts, therefore |x - o| must be 0 or 1 and O can never outnumber X.
        return Math.abs(xCount - oCount) <= 1 && oCount <= xCount;
    }

    /** Determines the winner of the game (if any). Returns a descriptive message or {@code null}. */
    private static String getWinner(char[][] board) {
        // Check rows
        for (int i = 0; i < 3; i++) {
            if (hasThreeInARow(board[i][0], board[i][1], board[i][2])) {
                return winnerMessage(board[i][0]);
            }
        }
        // Check columns
        for (int i = 0; i < 3; i++) {
            if (hasThreeInARow(board[0][i], board[1][i], board[2][i])) {
                return winnerMessage(board[0][i]);
            }
        }
        // Check diagonals
        if (hasThreeInARow(board[0][0], board[1][1], board[2][2])
                || hasThreeInARow(board[0][2], board[1][1], board[2][0])) {
            return winnerMessage(board[0][0]); // either diagonal’s symbol is the same
        }
        return null; // no winner
    }

    /** Returns true if the three supplied characters are equal and not an empty cell. */
    private static boolean hasThreeInARow(char a, char b, char c) {
        return a != EMPTY && a == b && b == c;
    }

    /** Translates a winning symbol into the required output message. */
    private static String winnerMessage(char winnerSymbol) {
        return winnerSymbol == PLAYER_X
                ? "the first player won"
                : "the second player won";
    }
}

import java.util.Scanner;

/**
 * Refactored Tic‑Tac‑Toe validator and outcome determiner.
 *
 * <p>
 * The program reads three lines from {@code System.in}, each containing exactly three
 * characters (either 'X', '0' or any other character to represent an empty cell).
 * It then checks whether the board configuration is legal, decides who has won
 * (if anyone), and prints one of the following messages:
 * <ul>
 *   <li>"first" – the board is empty or the next turn belongs to the first player</li>
 *   <li>"second" – the next turn belongs to the second player</li>
 *   <li>"illegal" – the board violates the rules of Tic‑Tac‑Toe</li>
 *   <li>"the first player won"</li>
 *   <li>"the second player won"</li>
 *   <li>"draw"</li>
 * </ul>
 * </p>
 *
 * <p>This refactor improves maintainability by:</p>
 * <ul>
 *   <li>Eliminating dozens of meaningless temporary variables.</li>
 *   <li>Separating concerns into small, focused methods.</li>
 *   <li>Using clear naming and Java‑standard constants.</li>
 *   <li>Adding comments and inline documentation.</li>
 * </ul>
 */
public class TicTacToe {

    /** Symbol used for the first player (X). */
    private static final char PLAYER_X = 'X';

    /** Symbol used for the second player (O). */
    private static final char PLAYER_O = 'O';

    /** Empty cell representation (any character other than X or O). */
    private static final char EMPTY = '\u0000';

    /** Größe des Brettes (3×3). */
    private static final int SIZE = 3;

    public static void main(String[] args) {
        try (Scanner sc = new Scanner(System.in)) {
            char[][] board = readBoard(sc);
            int countX = countMarks(board, PLAYER_X);
            int countO = countMarks(board, PLAYER_O);

            // 1️⃣  Prüfen, ob das Spiel bereits beendet ist oder illegal ist.
            if (!isLegal(countX, countO, board)) {
                System.out.println("illegal");
                return;
            }

            // 2️⃣  Ermitteln, wer gewonnen hat (falls jemand).
            boolean xWon = hasWon(board, PLAYER_X);
            boolean oWon = hasWon(board, PLAYER_O);

            // 3️⃣  Ergebnis bestimmen.
            if (xWon) {
                System.out.println("the first player won");
            } else if (oWon) {
                System.out.println("the second player won");
            } else if (isBoardFull(board)) {
                System.out.println("draw");
            } else {
                // Spiel ist noch nicht beendet – welcher Spieler ist am Zug?
                System.out.println(countX == countO ? "first" : "second");
            }
        }
    }

    /**
     * Liest exakt drei Zeilen von {@code scanner} ein und baut das 3×3‑Brett.
     *
     * @param scanner Scanner, der Eingabe bereitstellt.
     * @return 3×3‑Array mit den eingelesenen Zeichen.
     */
    private static char[][] readBoard(Scanner scanner) {
        char[][] board = new char[SIZE][SIZE];
        for (int row = 0; row < SIZE; row++) {
            String line = scanner.next().trim();
            // Falls weniger als 3 Zeichen vorhanden sind, restliche Felder bleiben leer.
            for (int col = 0; col < SIZE; col++) {
                board[row][col] = (col < line.length()) ? line.charAt(col) : EMPTY;
            }
        }
        return board;
    }

    /**
     * Zählt, wie oft ein bestimmtes Symbol auf dem Brett erscheint.
     *
     * @param board   Das Spielbrett.
     * @param symbol  Das zu zählende Symbol ('X' oder 'O').
     * @return Anzahl der Vorkommen des Symbols.
     */
    private static int countMarks(char[][] board, char symbol) {
        int count = 0;
        for (int i = 0; i < SIZE; i++) {
            for (int j = 0; j < SIZE; j++) {
                if (board[i][j] == symbol) {
                    count++;
                }
            }
        }
        return count;
    }

    /**
     * Prüft, ob ein Spieler ein Gewinnmuster erreicht hat.
     *
     * @param board   Das Spielbrett.
     * @param symbol  Das zu prüfende Symbol.
     * @return {@code true}, falls das Symbol drei Mal in einer Reihe, Spalte oder Diagonal steht.
     */
    private static boolean hasWon(char[][] board, char symbol) {
        // Reihen und Spalten
        for (int i = 0; i < SIZE; i++) {
            if (allEqual(board[i][0], board[i][1], board[i][2], symbol)) return true;
            if (allEqual(board[0][i], board[1][i], board[2][i], symbol)) return true;
        }
        // Diagonalen
        return allEqual(board[0][0], board[1][1], board[2][2], symbol) ||
               allEqual(board[0][2], board[1][1], board[2][0], symbol);
    }

    /** Hilfsmethode, um drei Werte auf Gleichheit mit einem Symbol zu prüfen. */
    private static boolean allEqual(char a, char b, char c, char symbol) {
        return a == symbol && b == symbol && c == symbol;
    }

    /**
     * Prüft, ob die aktuelle Brett-Konfiguration rechtlich möglich ist.
     *
     * <p>Typische Regeln:</p>
     * <ul>
     *   <li>Die Anzahl von 'X' ist entweder gleich der Anzahl von 'O' oder um 1 größer.</li>
     *   <li>Nur ein Spieler kann gewinnen; kann beide gewinnen, ist das Brett illegal.</li>
     *   <li>Hat 'O' gewonnen, muss {@code countO == countX} gelten.</li>
     *   <li>Hat 'X' gewonnen, muss {@code countX == countO + 1} gelten.</li>
     * </ul>
     *
     * @param countX Anzahl der 'X'‑Symbole.
     * @param countO Anzahl der 'O'‑Symbole.
     * @param board  Das Spielbrett.
     * @return {@code true}, falls die Konfiguration den Regeln entspricht.
     */
    private static boolean isLegal(int countX, int countO, char[][] board) {
        // Grundlegende Zähler‑Regel
        if (!(countX == countO || countX == countO + 1)) {
            return false;
        }

        boolean xWon = hasWon(board, PLAYER_X);
        boolean oWon = hasWon(board, PLAYER_O);

        // Beide Spieler können nicht gleichzeitig gewinnen
        if (xWon && oWon) {
            return false;
        }

        // Gewinnbedingungen prüfen
        if (oWon && countX != countO) {
            return false;
        }
        if (xWon && countX != countO + 1) {
            return false;
        }

        return true;
    }

    /** Prüft, ob das Brett vollständig besetzt ist (Unentschieden‑Basis). */
    private static boolean isBoardFull(char[][] board) {
        for (int i = 0; i < SIZE; i++) {
            for (int j = 0; j < SIZE; j++) {
                if (board[i][j] == EMPTY) {
                    return false;
                }
            }
        }
        return true;
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;

/**
 * Tic‑Tac‑Toe board validator.
 *
 * <p>
 * The program reads three lines from standard input, each containing a 3‑character
 * description of a board row (e.g. "X0X"). Empty cells are represented by '.'.
 * It then evaluates the board according to the rules of Tic‑Tac‑Toe and prints:
 * <ul>
 *   <li>"illegal" – when the board configuration cannot appear in a real game.</li>
 *   <li>"the first player won"</li>
 *   <li>"the second player won"</li>
 *   <li>"draw"</li>
 *   <li>"first"</li>  – next move belongs to the first player.</li>
 *   <li>"second"</li> – next move belongs to the second player.</li>
 * </ul>
 * </p>
 *
 * <p>All validation logic is isolated in small, single‑purpose methods to make the
 * code easy to test and maintain.</p>
 */
public class TicTacToeValidator {

    /** Marks an empty cell. */
    private static final char EMPTY = '.';

    /** Player X (the first player). */
    private static final char PLAYER_X = 'X';

    /** Player O (the second player). */
    private static final char PLAYER_O = 'O';

    /** Entry point – reads three rows from stdin and evaluates the board. */
    public static void main(String[] args) throws IOException {
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));

        String row1 = reader.readLine();
        String row2 = reader.readLine();
        String row3 = reader.readLine();

        // Guard against missing input – silently exit if incomplete.
        if (row1 == null || row2 == null || row3 == null) {
            return;
        }

        evaluateBoard(row1, row2, row3);
    }

    /**
     * Main driver that orchestrates the validation steps.
     *
     * @param row1 first row of the board
     * @param row2 second row of the board
     * @param row3 third row of the board
     */
    private static void evaluateBoard(String row1, String row2, String row3) {
        // Convert textual rows into a 3×3 character grid.
        char[][] board = {
                row1.toCharArray(),
                row2.toCharArray(),
                row3.toCharArray()
        };

        // Gather statistics about the board.
        int xCount = countOccurrences(board, PLAYER_X);
        int oCount = countOccurrences(board, PLAYER_O);
        int emptyCount = countOccurrences(board, EMPTY);

        // Determine whether either player has a winning line.
        boolean xWins = hasWon(board, PLAYER_X);
        boolean oWins = hasWon(board, PLAYER_O);

        // Apply the game‑logic rules.
        if (isIllegalConfiguration(xCount, oCount, xWins, oWins)) {
            System.out.println("illegal");
            return;
        }

        if (xWins) {
            System.out.println("the first player won");
            return;
        }

        if (oWins) {
            System.out.println("the second player won");
            return;
        }

        if (emptyCount == 0) {
            System.out.println("draw");
            return;
        }

        // Next move depends on whose turn it is.
        System.out.println((xCount == oCount) ? "first" : "second");
    }

    /**
     * Counts how many cells contain a given character on the board.
     *
     * @param board   3×3 grid
     * @param target  character to count ('X', 'O' or '.')
     * @return number of occurrences
     */
    private static int countOccurrences(char[][] board, char target) {
        int cnt = 0;
        for (int r = 0; r < 3; r++) {
            for (int c = 0; c < 3; c++) {
                if (board[r][c] == target) {
                    cnt++;
                }
            }
        }
        return cnt;
    }

    /**
     * Checks whether a given player has three of their marks in a row,
     * column, or diagonal.
     *
     * @param board   3×3 grid
     * @param player  'X' or 'O'
     * @return true if the player has a winning line
     */
    private static boolean hasWon(char[][] board, char player) {
        // Rows
        for (int r = 0; r < 3; r++) {
            if (board[r][0] == player && board[r][1] == player && board[r][2] == player) {
                return true;
            }
        }
        // Columns
        for (int c = 0; c < 3; c++) {
            if (board[0][c] == player && board[1][c] == player && board[2][c] == player) {
                return true;
            }
        }
        // Diagonals
        if (board[0][0] == player && board[1][1] == player && board[2][2] == player) {
            return true;
        }
        if (board[0][2] == player && board[1][1] == player && board[2][0] == player) {
            return true;
        }
        return false;
    }

    /**
     * Determines whether the supplied board configuration obeys the turn‑order
     * rules and the “win‑only‑when‑legal” restriction.
     *
     * @param xCnt number of 'X' cells
     * @param oCnt number of 'O' cells
     * @param xWon true if 'X' has a winning line
     * @param oWon true if 'O' has a winning line
     * @return true if the board is illegal, false otherwise
     */
    private static boolean isIllegalConfiguration(int xCnt, int oCnt, boolean xWon, boolean oWon) {
        // X always starts, therefore they can never have fewer marks than O.
        if (oCnt > xCnt) {
            return true;
        }
        // X cannot have made more than one move extra compared to O.
        if (xCnt - oCnt > 1) {
            return true;
        }
        // Both players cannot win simultaneously.
        if (xWon && oWon) {
            return true;
        }
        // If 'X' wins, the game must have ended on X's move → xCnt == oCnt + 1.
        if (xWon && xCnt != oCnt + 1) {
            return true;
        }
        // If 'O' wins, the game must have ended on O's move → xCnt == oCnt.
        if (oWon && xCnt != oCnt) {
            return true;
        }
        return false;
    }
}

import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;

/**
 * Tic‑Tac‑Toe game evaluator.
 *
 * <p>Input consists of three lines that describe a 3×3 board.
 * Each line must contain exactly three characters:
 * <ul>
 *   <li>'X' – first player's move</li>
 *   <li>'0' – second player's move</li>
 *   <li>'.' – empty cell</li>
 * </ul>
 * The program evaluates the board and prints one of the following messages:
 * <pre>
 *   illegal
 *   first
 *   second
 *   the first player won
 *   the second player won
 *   draw
 * </pre>
 * The semantics of the messages match the original program.
 */
public class Main {

    /** Cell types used on the board. */
    private enum Cell { EMPTY, FIRST, SECOND }

    /** Winning lines are indexed for quick access. */
    private static final int[][] WIN_LINES = {
            {0, 1, 2}, {3, 4, 5}, {6, 7, 8}, // rows
            {0, 3, 6}, {1, 4, 7}, {2, 5, 8}, // columns
            {0, 4, 8}, {2, 4, 6}             // diagonals
    };

    /** The 3×3 board. */
    private final Cell[][] cells = new Cell[3][3];

    /** Private constructor – use {@link #fromLines(List)}. */
    private BoardGame(String line1, String line2, String line3) {
        cells[0] = parseLine(line1);
        cells[1] = parseLine(line2);
        cells[2] = parseLine(line3);
    }

    /** Convert a single string of three characters into a row of Cells. */
    private static Cell[] parseLine(String line) {
        Cell[] row = new Cell[3];
        for (int i = 0; i < 3; i++) {
            char ch = line.charAt(i);
            row[i] = switch (ch) {
                case 'X' -> Cell.FIRST;
                case '0' -> Cell.SECOND;
                default -> Cell.EMPTY;
            };
        }
        return row;
    }

    /** Build a board from three input lines. */
    private static BoardGame fromLines(List<String> lines, int start) {
        if (start + 3 > lines.size()) {
            throw new IllegalArgumentException("Insufficient lines to form a board");
        }
        String l1 = lines.get(start);
        String l2 = lines.get(start + 1);
        String l3 = lines.get(start + 2);
        return new BoardGame(l1, l2, l3);
    }

    /** Count how many cells belong to each player. */
    private int[] countMarks() {
        int first = 0, second = 0;
        for (Cell[] row : cells) {
            for (Cell c : row) {
                if (c == Cell.FIRST) first++;
                else if (c == Cell.SECOND) second++;
            }
        }
        return new int[]{first, second};
    }

    /** Does the given player have at least one complete winning line? */
    private boolean hasWinningLine(Cell player) {
        char target = player == Cell.FIRST ? 'X' : '0';
        for (int[] indices : WIN_LINES) {
            Cell c1 = cells[indices[0] / 3][indices[0] % 3];
            Cell c2 = cells[indices[1] / 3][indices[1] % 3];
            Cell c3 = cells[indices[2] / 3][indices[2] % 3];
            if (c1 == target && c2 == target && c3 == target) {
                return true;
            }
        }
        return false;
    }

    /** Number of winning lines for the given player (0 or 1 in practice). */
    private int winningLineCount(Cell player) {
        int cnt = 0;
        char target = player == Cell.FIRST ? 'X' : '0';
        for (int[] indices : WIN_LINES) {
            Cell c1 = cells[indices[0] / 3][indices[0] % 3];
            Cell c2 = cells[indices[1] / 3][indices[1] % 3];
            Cell c3 = cells[indices[2] / 3][indices[2] % 3];
            if (c1 == target && c2 == target && c3 == target) {
                cnt++;
            }
        }
        return cnt;
    }

    /** Verify that the current board configuration obeys the rules of Tic‑Tac‑Toe. */
    private boolean isLegal() {
        int[] counts = countMarks();
        int firstCnt = counts[0];
        int secondCnt = counts[1];

        // 1. Turn order must be respected
        if (firstCnt < secondCnt || firstCnt > secondCnt + 1) {
            return false;
        }

        // 2. Both players cannot have a winning line simultaneously
        if (hasWinningLine(Cell.FIRST) && hasWinningLine(Cell.SECOND)) {
            return false;
        }

        // 3. If second player wins, the move counts must be equal
        if (hasWinningLine(Cell.SECOND) && firstCnt != secondCnt) {
            return false;
        }

        // 4. If first player wins, they must have made exactly one more move
        if (hasWinningLine(Cell.FIRST) && firstCnt != secondCnt + 1) {
            return false;
        }

        return true;
    }

    /** Is the board completely filled? */
    private boolean isFull() {
        int[] counts = countMarks();
        return counts[0] + counts[1] == 9;
    }

    /** Evaluate the board and print the appropriate message. */
    private static void evaluateAndPrint(BoardGame board) {
        if (!board.isLegal()) {
            System.out.println("illegal");
            return;
        }

        int firstWins = board.winningLineCount(Cell.FIRST);
        int secondWins = board.winningLineCount(Cell.SECOND);

        if (firstWins > 0) {
            System.out.println("the first player won");
        } else if (secondWins > 0) {
            System.out.println("the second player won");
        } else if (board.isFull()) {
            System.out.println("draw");
        } else {
            // No winner yet – announce whose turn is next
            int[] counts = board.countMarks();
            if (counts[0] == counts[1]) {
                System.out.println("first");
            } else {
                System.out.println("second");
            }
        }
    }

    /** Simple wrapper that holds a board instance. */
    private static final class BoardGame {
        private final Cell[][] grid;

        private BoardGame(Cell[][] grid) {
            this.grid = grid;
        }

        Cell[][] getGrid() {
            return grid;
        }
    }

    /** Entry point – reads boards line‑by‑line until EOF. */
    public static void main(String[] args) {
        List<String> inputLines = new ArrayList<>();
        try (Scanner scanner = new Scanner(System.in)) {
            while (scanner.hasNextLine()) {
                inputLines.add(scanner.nextLine().trim());
            }
        }

        int idx = 0;
        while (idx < inputLines.size()) {
            try {
                BoardGame board = fromLines(inputLines, idx);
                evaluateAndPrint(board);
                idx += 3; // move to the next board
            } catch (IllegalArgumentException ex) {
                // Not enough lines left – stop processing
                break;
            }
        }
    }
}

import java.io.*;
import java.util.Scanner;

/**
 * Entry point of the application. Reads a 3×3 Tic‑Tac‑Toe board,
 * evaluates its state and prints the appropriate result.
 */
public class Main {

    /** Symbol used for an empty cell. */
    private static final char EMPTY = '.';
    /** Symbol used for the first player (X). */
    private static final char CROSS = 'X';
    /** Symbol used for the second player (0). */
    private static final char NOUGHT = '0';

    public static void main(String[] args) {
        // Using try‑with‑resources guarantees that the PrintWriter is closed properly.
        try (PrintWriter out = new PrintWriter(System.out)) {
            Board board = readBoard();                     // Parse input
            Result result = evaluate(board);               // Analyse the board
            printResult(out, result);                      // Emit the answer
        }
    }

    /**
     * Reads three lines from standard input, each containing exactly three
     * characters that are either {@code 'X'}, {@code '0'} or {@code '.'}.
     *
     * @return a {@link Board} representation of the parsed cells
     */
    private static Board readBoard() {
        Scanner scanner = new Scanner(System.in);
        char[][] cells = new char[3][3];
        int idx = 0;

        for (int row = 0; row < 3; row++) {
            String line = scanner.nextLine().trim();
            if (line.length() != 3) {
                throw new IllegalArgumentException(
                    "Each line must contain exactly 3 characters");
            }
            for (int col = 0; col < 3; col++) {
                char ch = line.charAt(col);
                if (ch != CROSS && ch != NOUGHT && ch != EMPTY) {
                    throw new IllegalArgumentException(
                        "Invalid character encountered: '" + ch + "'");
                }
                cells[row][col] = ch;
            }
        }
        return new Board(cells);
    }

    /**
     * Evaluates the supplied board and returns a {@link Result} describing its
     * state.
     *
     * @param board the board to evaluate
     * @return a {@link Result} enum value representing the outcome
     */
    private static Result evaluate(Board board) {
        int crosses = board.count(CROSS);
        int noughts = board.count(NOUGHT);
        boolean firstWon  = board.hasWinningLine(CROSS);
        boolean secondWon = board.hasWinningLine(NOUGHT);

        // ---------- Validation ----------
        if (Math.abs(crosses - noughts) > 1) {
            return Result.INVALID;
        }
        if (noughts > crosses) {
            return Result.INVALID;
        }
        if (firstWon && secondWon) {
            return Result.INVALID;
        }
        if (firstWon && crosses != noughts + 1) {
            return Result.INVALID;
        }
        if (secondWon && crosses != noughts) {
            return Result.INVALID;
        }

        // ---------- Determine the result ----------
        if (firstWon) {
            return Result.FIRST_WON;
        }
        if (secondWon) {
            return Result.SECOND_WON;
        }
        if (crosses + noughts == 9) {
            return Result.DRAW;
        }
        // Game not finished → whose turn is it?
        return (crosses > noughts) ? Result.SECOND_TURN : Result.FIRST_TURN;
    }

    /**
     * Translates the {@link Result} into the required output string and prints it.
     *
     * @param out    the PrintWriter used for output
     * @param result the result to translate
     */
    private static void printResult(PrintWriter out, Result result) {
        switch (result) {
            case INVALID -> out.println("illegal");
            case FIRST_WON -> out.println("the first player won");
            case SECOND_WON -> out.println("the second player won");
            case DRAW -> out.println("draw");
            case FIRST_TURN -> out.println("first");
            case SECOND_TURN -> out.println("second");
        }
    }

    /** Encapsulates a 3×3 Tic‑Tac‑Toe board. */
    private static class Board {
        private final char[][] cells;

        Board(char[][] cells) {
            this.cells = cells;
        }

        /** Returns how many times the given symbol occurs on the board. */
        int count(char symbol) {
            int cnt = 0;
            for (char[] row : cells) {
                for (char cell : row) {
                    if (cell == symbol) {
                        cnt++;
                    }
                }
            }
            return cnt;
        }

        /** Checks whether the given symbol has a complete winning line. */
        boolean hasWinningLine(char symbol) {
            // rows
            for (int i = 0; i < 3; i++) {
                if (cells[i][0] == symbol && cells[i][1] == symbol && cells[i][2] == symbol) {
                    return true;
                }
            }
            // columns
            for (int j = 0; j < 3; j++) {
                if (cells[0][j] == symbol && cells[1][j] == symbol && cells[2][j] == symbol) {
                    return true;
                }
            }
            // diagonals
            if (cells[0][0] == symbol && cells[1][1] == symbol && cells[2][2] == symbol) {
                return true;
            }
            if (cells[0][2] == symbol && cells[1][1] == symbol && cells[2][0] == symbol) {
                return true;
            }
            return false;
        }
    }

    /** Enum that captures all possible outcomes of the evaluation phase. */
    private enum Result {
        INVALID,
        FIRST_WON,
        SECOND_WON,
        DRAW,
        FIRST_TURN,
        SECOND_TURN
    }
}

import java.io.BufferedReader;
import java.io.FileReader;
import java.io.IOException;
import java.util.Optional;

/**
 * Refactored Tic‑Tac‑Toe validator.
 *
 * <p>
 * The program reads three lines of 3 characters each (X, O or .) from the
 * supplied input source and determines the game state:
 * <ul>
 *   <li>draw</li>
 *   <li>first</li>
 *   <li>second</li>
 *   <li>the first player won</li>
 *   <li>the second player won</li>
 *   <li>illegal</li>
 * </ul>
 * </p>
 */
public final class TicTacToe {

    /** Symbol used for an empty cell. */
    private static final char EMPTY = '.';

    /** Symbol for player X. */
    private static final char PLAYER_X = 'X';

    /** Symbol for player O. */
    private static final char PLAYER_O = 'O';

    /** Marker used when two players have winning lines simultaneously. */
    private static final char ILLEGAL_WIN = 'i';

    private TicTacToe() {
        // utility class – no instances
    }

    public static void main(String[] args) throws IOException {
        // The original program allowed an optional filename; we keep the same flexibility.
        String source = System.getProperty("user.input", "System.in");

        try (BufferedReader reader = obtainReader(source)) {
            char[][] board = readBoard(reader);
            if (board == null) {
                // readBoard already printed "illegal" and returned.
                System.exit(0);
            }

            int xCount = count(board, PLAYER_X);
            int oCount = count(board, PLAYER_O);
            boolean isFull = isBoardFull(board);

            // ---------- Validation ----------
            if (!isLegalCount(xCount, oCount)) {
                System.out.println("illegal");
                return;
            }
            if (isFull && !(xCount == 5 && oCount == 4)) {
                System.out.println("illegal");
                return;
            }

            char winnerSymbol = determineWinner(board);
            if (winnerSymbol == ILLEGAL_WIN) {
                System.out.println("illegal");
                return;
            }

            // ---------- Result ----------
            if (winnerSymbol == 'n') {
                // No winner
                if (isFull) {
                    System.out.println("draw");
                } else if (oCount == xCount) {
                    System.out.println("first");
                } else if (xCount == oCount + 1) {
                    System.out.println("second");
                } else {
                    System.out.println("illegal");
                }
            } else if (winnerSymbol == PLAYER_X) {
                // X just won – X must have played one more move than O.
                if (oCount >= xCount) {
                    System.out.println("illegal");
                } else {
                    System.out.println("the first player won");
                }
            } else if (winnerSymbol == PLAYER_O) {
                // O just won – O cannot have more moves than X.
                if (xCount > oCount) {
                    System.out.println("illegal");
                } else {
                    System.out.println("the second player won");
                }
            } else {
                System.out.println("illegal");
            }
        }
    }

    /** Creates a BufferedReader that reads either from a file or from standard input. */
    private static BufferedReader obtainReader(String source) throws IOException {
        if ("System.in".equals(source)) {
            return new BufferedReader(new java.io.InputStreamReader(System.in));
        }
        return new BufferedReader(new FileReader(source));
    }

    /** Reads exactly three lines of length three containing only 'X', '0' or '.'. */
    private static char[][] readBoard(BufferedReader reader) throws IOException {
        char[][] board = new char[3][3];
        int lineNumber = 0;

        for (int i = 0; i < 3; i++) {
            String line = reader.readLine();
            if (line == null) {
                System.out.println("illegal");
                return null;
            }
            if (line.length() != 3) {
                System.out.println("illegal");
                return null;
            }
            for (int j = 0; j < 3; j++) {
                char c = line.charAt(j);
                if (c != PLAYER_X && c != PLAYER_O && c != EMPTY) {
                    System.out.println("illegal");
                    return null;
                }
                board[i][j] = c;
            }
            lineNumber++;
        }
        return board;
    }

    /** Counts occurrences of the given symbol on the board. */
    private static int count(char[][] board, char symbol) {
        int cnt = 0;
        for (char[] row : board) {
            for (char cell : row) {
                if (symbol == cell) {
                    cnt++;
                }
            }
        }
        return cnt;
    }

    /** Returns true if there are no empty cells left. */
    private static boolean isBoardFull(char[][] board) {
        for (char[] row : board) {
            for (char cell : row) {
                if (cell == EMPTY) {
                    return false;
                }
            }
        }
        return true;
    }

    /** Determines whether the move counts are legally consistent. */
    private static boolean isLegalCount(int x, int o) {
        // X always starts, so x must be equal to o or o+1.
        return x == o || x == o + 1;
    }

    /**
     * Analyzes the board for winning lines.
     *
     * @return {@code Optional} containing the winning symbol ('X' or 'O') if exactly one
     *         player has a complete line, otherwise {@link Optional#empty()} when
     *         there is no winner or both players have winning lines (treated as illegal).
     */
    private static Optional<Character> determineWinner(char[][] board) {
        // All possible winning lines (rows, columns, diagonals)
        char[][] winningLines = {
                // rows
                {board[0][0], board[0][1], board[0][2]},
                {board[1][0], board[1][1], board[1][2]},
                {board[2][0], board[2][1], board[2][2]},
                // columns
                {board[0][0], board[1][0], board[2][0]},
                {board[0][1], board[1][1], board[2][1]},
                {board[0][2], board[1][2], board[2][2]},
                // diagonals
                {board[0][0], board[1][1], board[2][2]},
                {board[0][2], board[1][1], board[2][0]}
        };

        int xWins = 0;
        int oWins = 0;
        char xWinner = 'n';
        char oWinner = 'n';

        for (char[] line : winningLines) {
            if (line[0] != EMPTY && line[0] == line[1] && line[1] == line[2]) {
                if (line[0] == PLAYER_X) {
                    xWins++;
                    xWinner = PLAYER_X;
                } else {
                    oWins++;
                    oWinner = PLAYER_O;
                }
            }
        }

        // If both players have at least one winning line, the board is illegal.
        if (xWins > 0 && oWins > 0) {
            return Optional.of(ILLEGAL_WIN);
        }

        // Exactly one player has a winning line → return that symbol.
        if (xWins > 0) {
            return Optional.of(PLAYER_X);
        }
        if (oWins > 0) {
            return Optional.of(PLAYER_O);
        }
        // No winning line.
        return Optional.empty();
    }
}

import java.util.Scanner;

/**
 * Console based Tic‑Tac‑Toe validator and starter game logic.
 *
 * <p>This class reads a partially filled board (three lines of three characters
 * each) and determines the current game state according to the rules of
 * Tic‑Tac‑Toe.</p>
 */
public class TicTacToe {

    /** Empty cell marker used internally. */
    private static final char EMPTY = ' ';

    /** 3×3 board stored as a char array. */
    private final char[][] board;

    public TicTacToe(char[][] board) {
        this.board = board;
    }

    /** Returns the player symbol ('X' or '0') that has won, or {@code EMPTY} if none. */
    private static char winner(char[][] b) {
        // rows
        for (int i = 0; i < 3; i++) {
            if (b[i][0] != EMPTY && b[i][0] == b[i][1] && b[i][1] == b[i][2]) {
                return b[i][0];
            }
        }
        // columns
        for (int j = 0; j < 3; j++) {
            if (b[0][j] != EMPTY && b[0][j] == b[1][j] && b[1][j] == b[2][j]) {
                return b[0][j];
            }
        }
        // diagonals
        if (b[0][0] != EMPTY && b[0][0] == b[1][1] && b[1][1] == b[2][2]) {
            return b[0][0];
        }
        if (b[2][0] != EMPTY && b[2][0] == b[1][1] && b[1][1] == b[0][2]) {
            return b[2][0];
        }
        return EMPTY;
    }

    /** Counts occurrences of a given symbol on the board. */
    private static int count(char[][] b, char symbol) {
        int cnt = 0;
        for (int i = 0; i < 3; i++) {
            for (int j = 0; j < 3; j++) {
                if (b[i][j] == symbol) {
                    cnt++;
                }
            }
        }
        return cnt;
    }

    /** Determines whether the current board configuration obeys turn order rules. */
    private static boolean isValidState(char[][] b, char winnerX, char winnerO) {
        int xCount = count(b, 'X');
        int oCount = count(b, '0');

        // O cannot have more moves than X
        if (oCount > xCount) {
            return false;
        }
        // Both players cannot win
        if (winnerX != EMPTY && winnerO != EMPTY) {
            return false;
        }
        // If X won, they must have made one more move than O
        if (winnerX != EMPTY && xCount != oCount + 1) {
            return false;
        }
        // If O won, the move counts must be equal
        if (winnerO != EMPTY && xCount != oCount) {
            return false;
        }
        return true;
    }

    /** Reads a board from standard input (three lines of three characters each). */
    private static char[][] readBoard(Scanner scanner) {
        char[][] grid = new char[3][3];
        for (int i = 0; i < 3; i++) {
            String line = scanner.nextLine().trim();
            if (line.length() != 3) {
                throw new IllegalArgumentException("Each line must contain exactly 3 characters.");
            }
            grid[i] = line.toCharArray();
        }
        return grid;
    }

    /** Outputs the game state according to the specification. */
    private static void printResult(char winner) {
        switch (winner) {
            case 'X' -> System.out.println("the first player won");
            case '0' -> System.out.println("the second player won");
            default -> {
                int xCount = count(instanceBoard, 'X');
                int oCount = count(instanceBoard, '0');

                if (!isValidState(instanceBoard, instanceBoardWinnerX, instanceBoardWinnerO)) {
                    System.out.println("illegal");
                } else if (xCount + oCount == 9) {
                    System.out.println("draw");
                } else if (xCount == oCount + 1) {
                    System.out.println("second");
                } else {
                    System.out.println("first");
                }
            }
        }
    }

    /* --------------------------------------------------------------------- */
    /*  The following static fields are used only for the final output step   */
    /*  in this simplified example – they hold the board read from input.   */
    /* --------------------------------------------------------------------- */
    private static char[][] instanceBoard;
    private static char instanceBoardWinnerX;
    private static char instanceBoardWinnerO;

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        instanceBoard = readBoard(scanner);
        instanceBoardWinnerX = winner(instanceBoard);
        instanceBoardWinnerO = winner(instanceBoard);

        printResult(instanceBoardWinnerX);
    }
}

/**
 * Refactored Tic‑Tac‑Toe validator.
 *
 * The program reads three whitespace‑separated tokens that each represent a row
 * of a 3×3 board.  Tokens must be exactly three characters long and consist of
 * 'X', '0' (zero) or '.' (empty).  It validates the board state and prints the
 * appropriate result:
 *
 *   illegal      – the board cannot arise from a legal game
 *   first        – X (the first player) has won
 *   second       – O (the second player) has won
 *   draw         – board is full and nobody has won
 *
 * The refactor improves readability, maintainability and testability by:
 *   • Extracting input handling into its own method
 *   • Encapsulating board representation and win detection in a dedicated class
 *   • Using meaningful names, constants and Java‑idiomatic constructs
 *   • Removing duplicated code and magic numbers
 *   • Adding Javadoc comments
 */
public class TicTacToe {

    /** Symbol used for an empty cell. */
    private static final char EMPTY = '.';

    /** Symbol used for the first player (X). */
    private static final char FIRST_PLAYER = 'X';

    /** Symbol used for the second player (O). */
    private static final char SECOND_PLAYER = '0';

    /** Size of the board (3×3). */
    private static final int BOARD_SIZE = 3;

    /** Utility class that parses the input tokens into a 2‑D char array. */
    private static final class Board {
        private final char[][] cells = new char[BOARD_SIZE][BOARD_SIZE];

        /** Constructs a board from three whitespace‑separated tokens. */
        Board(Tokenizer tokenizer) throws IllegalArgumentException {
            for (int r = 0; r < BOARD_SIZE; r++) {
                String token = tokenizer.nextToken();
                if (token == null || token.length() != BOARD_SIZE) {
                    throw new IllegalArgumentException("Invalid token length");
                }
                for (int c = 0; c < BOARD_SIZE; c++) {
                    cells[r][c] = token.charAt(c);
                }
            }
        }

        /** Returns a copy of the internal board (read‑only). */
        char[][] getCells() {
            return cells.clone();
        }
    }

    /** Tokenizer wrapper that hides the original `StringTokenizer` logic. */
    private static final class Tokenizer {
        private final BufferedReader reader = new BufferedReader(
                new InputStreamReader(System.in));
        private StringTokenizer tokenizer;
        private boolean endOfFile;

        /** Returns the next token, or "0" when EOF is reached. */
        String nextToken() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) {
                        endOfFile = true;
                        return "0";
                    }
                    tokenizer = new StringTokenizer(line);
                } catch (Exception e) {
                    throw new UncheckedIOException(e);
                }
            }
            return tokenizer.nextToken();
        }
    }

    /** Holds all validation logic for a board. */
    private static final class Validation {

        private final char[][] board;

        Validation(Board board) {
            this.board = board.getCells();
        }

        /** Counts occurrences of a given symbol on the board. */
        private int count(char symbol) {
            int cnt = 0;
            for (int r = 0; r < BOARD_SIZE; r++) {
                for (int c = 0; c < BOARD_SIZE; c++) {
                    if (board[r][c] == symbol) {
                        cnt++;
                    }
                }
            }
            return cnt;
        }

        /** Determines whether the given player has a winning line. */
        private boolean hasWon(char player) {
            // rows
            for (int r = 0; r < BOARD_SIZE; r++) {
                if (board[r][0] == player && board[r][1] == player && board[r][2] == player) {
                    return true;
                }
            }
            // columns
            for (int c = 0; c < BOARD_SIZE; c++) {
                if (board[0][c] == player && board[1][c] == player && board[2][c] == player) {
                    return true;
                }
            }
            // diagonals
            if (board[0][0] == player && board[1][1] == player && board[2][2] == player) {
                return true;
            }
            if (board[0][2] == player && board[1][1] == player && board[2][0] == player) {
                return true;
            }
            return false;
        }

        /** Performs all checks and returns a description of the result. */
        String validate() {
            int firstCnt = count(FIRST_PLAYER);
            int secondCnt = count(SECOND_PLAYER);

            // ---- illegal state checks -------------------------------------------------
            // O cannot have more moves than X, and the difference cannot exceed 1.
            if (secondCnt > firstCnt || firstCnt - secondCnt > 1) {
                return "illegal";
            }

            boolean firstWon = hasWon(FIRST_PLAYER);
            boolean secondWon = hasWon(SECOND_PLAYER);

            // Both players cannot win simultaneously.
            if (firstWon && secondWon) {
                return "illegal";
            }

            // If X wins, it must have made exactly one more move than O.
            if (firstWon && firstCnt != secondCnt + 1) {
                return "illegal";
            }

            // If O wins, the move counts must be equal.
            if (secondWon && firstCnt != secondCnt) {
                return "illegal";
            }

            // ---- determine the outcome -----------------------------------------------
            if (firstWon) {
                return "first";
            }
            if (secondWon) {
                return "second";
            }

            // Draw when the board is full.
            if (firstCnt + secondCnt == BOARD_SIZE * BOARD_SIZE) {
                return "draw";
            }

            // Ongoing game – the player whose turn it is next.
            return (firstCnt > secondCnt) ? "second" : "first";
        }
    }

    /** Main entry point – reads input, validates and prints the result. */
    public static void main(String[] args) {
        Tokenizer tokenizer = new Tokenizer();
        try {
            Board board = new Board(tokenizer);
            Validation validation = new Validation(board);
            System.out.println(validation.validate());
        } catch (IllegalArgumentException e) {
            System.out.println("illegal");
        }
    }
}

import java.io.PrintWriter;
import java.util.Scanner;

/**
 * Refactored version of the original {@code C} program.
 * <p>
 * The purpose of the program is to analyse a 3×3 Tic‑Tac‑Toe board that
 * contains the symbols
 * <ul>
 *   <li>'X' – first player</li>
 *   <li>'0' – second player</li>
 *   <li>'.' – empty cell</li>
 * </ul>
 * It reports whether the board is illegal, who has won (or will win next),
 * or whether the game is a draw.
 * </p>
 */
public class GameSolver {

    /* --------------------------------------------------------------------- */
    /*                         Symbol constants                               */
    /* --------------------------------------------------------------------- */
    private static final char EMPTY = '.';
    private static final char PLAYER_ONE = 'X';   // first player
    private static final char PLAYER_TWO = '0';   // second player

    /* --------------------------------------------------------------------- */
    /*                         Outcome enum                                   */
    /* --------------------------------------------------------------------- */
    private enum Outcome {
        ILLEGAL,
        ONGOING_FIRST_TURN,
        ONGOING_SECOND_TURN,
        FIRST_WON,
        SECOND_WON,
        DRAW
    }

    /* --------------------------------------------------------------------- */
    /*                     Instance fields / board                           */
    /* --------------------------------------------------------------------- */
    private final char[][] board = new char[3][3];

    /* --------------------------------------------------------------------- */
    /*                           Input handling                               */
    /* --------------------------------------------------------------------- */
    private void readBoard(Scanner scanner) {
        for (int i = 0; i < 3; i++) {
            board[i] = scanner.next().toCharArray();
        }
    }

    /* --------------------------------------------------------------------- */
    /*                     Core analysis logic (private helpers)              */
    /* --------------------------------------------------------------------- */
    /** Wraps all statistics that are needed for the final decision. */
    private static final class Stats {
        final int cntOne, cntTwo;
        final Outcome outcome;

        Stats(int cntOne, int cntTwo, Outcome outcome) {
            this.cntOne = cntOne;
            this.cntTwo = cntTwo;
            this.outcome = outcome;
        }
    }

    /** Analyzes the current board and returns a {@link Stats} object that
     *  contains everything needed to print the final result. */
    private Stats analyze() {
        int cntOne = 0, cntTwo = 0;
        for (char[] row : board) {
            for (char c : row) {
                if (c == PLAYER_ONE) cntOne++;
                else if (c == PLAYER_TWO) cntTwo++;
            }
        }

        Stats stats = new Stats(cntOne, cntTwo, Outcome.ONGOING_FIRST_TURN);

        // 1️⃣ Validate the count difference and determine whose turn it is
        if (!validateSymbolCount(cntOne, cntTwo, stats)) {
            stats.outcome = Outcome.ILLEGAL;
            return stats;
        }

        // 2️⃣ Detect wins
        boolean firstWon = isWinning(PLAYER_ONE);
        boolean secondWon = isWinning(PLAYER_TWO);

        if (firstWon && secondWon) {
            stats.outcome = Outcome.ILLEGAL;
            return stats;
        }

        if (firstWon && !stats.turnIsFirst) {
            stats.outcome = Outcome.ILLEGAL;
            return stats;
        }
        if (secondWon && stats.turnIsFirst) {
            stats.outcome = Outcome.ILLEGAL;
            return stats;
        }

        if (firstWon) {
            stats.outcome = Outcome.FIRST_WON;
            return stats;
        }
        if (secondWon) {
            stats.outcome = Outcome.SECOND_WON;
            return stats;
        }

        if (cntOne + cntTwo == 9) {
            stats.outcome = Outcome.DRAW;
            return stats;
        }

        // 3️⃣ Game still in progress – whose turn is next?
        stats.outcome = stats.turnIsFirst
                ? Outcome.ONGOING_FIRST_TURN
                : Outcome.ONGOING_SECOND_TURN;
        return stats;
    }

    /** Returns {@code true} if the given player has a winning line. */
    private boolean isWinning(char player) {
        // rows
        for (int i = 0; i < 3; i++) {
            if (lineWins(board[i], player)) return true;
        }
        // columns
        for (int i = 0; i < 3; i++) {
            if (columnWins(i, player)) return true;
        }
        // diagonals
        return diagonalWins(player) || antiDiagonalWins(player);
    }

    /** Checks whether the specified line (row or column) consists solely of
     *  the given player's marks. */
    private boolean lineWins(char[] line, char player) {
        return line[0] == player && line[1] == player && line[2] == player;
    }

    private boolean columnWins(int col, char player) {
        return board[0][col] == player && board[1][col] == player && board[2][col] == player;
    }

    private boolean diagonalWins(char player) {
        return board[0][0] == player && board[1][1] == player && board[2][2] == player;
    }

    private boolean antiDiagonalWins(char player) {
        return board[0][2] == player && board[1][1] == player && board[2][0] == player;
    }

    /** Validates that the numbers of 'X' and '0' obey the turn order rules.
     *  If valid, also sets {@code stats.turnIsFirst} to indicate whose move
     *  should follow. */
    private boolean validateSymbolCount(int cntOne, int cntTwo, Stats stats) {
        int diff = cntOne - cntTwo;
        if (diff == 0) {
            stats.turnIsFirst = true;   // next move must be first player
            return true;
        }
        if (diff == 1) {
            stats.turnIsFirst = false;  // next move must be second player
            return true;
        }
        // any other difference makes the board illegal
        return false;
    }

    /* --------------------------------------------------------------------- */
    /*                        Result → output conversion                     */
    /* --------------------------------------------------------------------- */
    private static String outcomeToString(Outcome outcome) {
        switch (outcome) {
            case ILLEGAL          -> "illegal";
            case ONGOING_FIRST_TURN -> "first";
            case ONGOING_SECOND_TURN-> "second";
            case FIRST_WON        -> "the first player won";
            case SECOND_WON       -> "the second player won";
            case DRAW             -> "draw";
            default               -> "illegal";
        }
    }

    /* --------------------------------------------------------------------- */
    /*                              Driver code                               */
    /* --------------------------------------------------------------------- */
    public static void main(String[] args) throws Exception {
        new GameSolver().run();
    }

    private void run() throws Exception {
        Scanner scanner = new Scanner(System.in);
        PrintWriter out = new PrintWriter(System.out);

        readBoard(scanner);
        Stats stats = analyze();
        out.println(outcomeToString(stats.outcome));

        out.flush();
    }
}

import java.util.Scanner;

/**
 * Refactored version of the original Tic‑Tac‑Toe validator.
 * The program reads three lines of three characters each.
 * '.' denotes an empty cell.
 *
 * Output (exactly as the original program):
 *   - "illegal"
 *   - "draw"
 *   - "the first player won"
 *   - "the second player won"
 *   - "first"   – first player's turn
 *   - "second"  – second player's turn
 *
 * The refactor improves readability, separates concerns and uses
 * expressive method names and constants.
 */
public class Driver {

    /** Character used to denote an empty cell ('.'). */
    private static final char EMPTY = '.';

    public static void main(String[] args) {
        new Driver().run();
    }

    /** Entry point that reads input, validates it and prints the result. */
    private void run() {
        try (Scanner scanner = new Scanner(System.in)) {
            // ----- 1. Read three board rows -------------------------------------------------
            String[] rows = new String[3];
            for (int i = 0; i < 3; i++) {
                rows[i] = scanner.next();
            }

            // ----- 2. Build the board -------------------------------------------------------
            char[][] board = parse(rows);
            boolean incomplete = rows[0].indexOf(EMPTY) >= 0 ||
                                 rows[1].indexOf(EMPTY) >= 0 ||
                                 rows[2].indexOf(EMPTY) >= 0;

            // ----- 3. Analyse the board ------------------------------------------------------
            analyse(board, incomplete);
        }
    }

    /** Parses the three input strings into a 3×3 char matrix. */
    private static char[][] parse(String[] input) {
        char[][] board = new char[3][3];
        for (int i = 0; i < 3; i++) {
            board[i] = input[i].toCharArray();
        }
        return board;
    }

    /**
     * Core validation & result determination.
     *
     * @param board       the current board state
     * @param incomplete  true if at least one cell contains '.'
     */
    private void analyse(char[][] board, boolean incomplete) {
        int xCount = count(board, 'X');
        int oCount = count(board, 'O');

        // ----- 1. Basic count validation -------------------------------------------------
        if (!isCountCombinationValid(xCount, oCount)) {
            System.out.println("illegal");
            return;
        }

        boolean xWins = hasWon(board, 'X');
        boolean oWins = hasWon(board, 'O');

        // ----- 2. Conflicting wins -------------------------------------------------------
        if (xWins && oWins) {
            System.out.println("illegal");
            return;
        }

        // ----- 3. Winner validation against turn order -----------------------------------
        if (xWins) {
            if (oCount != xCount - 1) {
                System.out.println("illegal");
                return;
            }
            System.out.println("the first player won");
            return;
        }

        if (oWins) {
            if (xCount != oCount) {
                System.out.println("illegal");
                return;
            }
            System.out.println("the second player won");
            return;
        }

        // ----- 4. Draw --------------------------------------------------------------------
        if (!incomplete) {
            System.out.println("draw");
            return;
        }

        // ----- 5. Determine next player ---------------------------------------------------
        if (xCount == oCount) {
            System.out.println("first");
        } else if (xCount == oCount + 1) {
            System.out.println("second");
        } else {
            // This branch should never be reached because of earlier validation.
            System.out.println("illegal");
        }
    }

    /** Returns true if the supplied count pair obeys the turn order rules. */
    private static boolean isCountCombinationValid(int x, int o) {
        // X may be equal to O or exactly one more; O may never exceed X.
        return !(x - o > 1 || o > x);
    }

    /** Checks whether the given player has any winning line (row, column, diagonal). */
    private static boolean hasWon(char[][] board, char player) {
        // rows
        for (int i = 0; i < 3; i++) {
            if (board[i][0] == player && board[i][1] == player && board[i][2] == player) {
                return true;
            }
        }
        // columns
        for (int i = 0; i < 3; i++) {
            if (board[0][i] == player && board[1][i] == player && board[2][i] == player) {
                return true;
            }
        }
        // diagonals
        return (board[0][0] == player && board[1][1] == player && board[2][2] == player) ||
               (board[2][0] == player && board[1][1] == player && board[0][2] == player);
    }

    /** Counts how many times {@code token} appears on the board. */
    private static int count(char[][] board, char token) {
        int cnt = 0;
        for (int i = 0; i < 3; i++) {
            for (int j = 0; j < 3; j++) {
                if (board[i][j] == token) {
                    cnt++;
                }
            }
        }
        return cnt;
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;

/**
 * Tic‑Tac‑Toe game state evaluator.
 *
 * Reads a 3×3 board from standard input and prints one of the following:
 *   - "illegal"
 *   - "the first player won"
 *   - "the second player won"
 *   - "first"   (first player must move next)
 *   - "second"  (second player must move next)
 *   - "draw"
 */
public class Main {

    private static final char EMPTY = '.';
    private static final char PLAYER_X = 'X'; // first player
    private static final char PLAYER_O = 'O'; // second player

    public static void main(String[] args) throws IOException {
        char[][] board = readBoard();
        int xCount = count(board, PLAYER_X);
        int oCount = count(board, PLAYER_O);
        int emptyCount = count(board, EMPTY);

        boolean xWon = hasWon(board, PLAYER_X);
        boolean oWon = hasWon(board, PLAYER_O);

        String result = evaluate(xCount, oCount, emptyCount, xWon, oWon);
        System.out.println(result);
    }

    /** Reads exactly three lines of length three from {@code System.in}. */
    private static char[][] readBoard() throws IOException {
        char[][] board = new char[3][3];
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in))) {
            for (int i = 0; i < 3; i++) {
                String line = br.readLine();
                if (line == null || line.length() != 3) {
                    throw new IOException("Input must contain three lines of three characters");
                }
                for (int j = 0; j < 3; j++) {
                    board[i][j] = line.charAt(j);
                }
            }
        }
        return board;
    }

    /** Counts occurrences of a given character on the board. */
    private static int count(char[][] board, char ch) {
        int cnt = 0;
        for (int i = 0; i < 3; i++) {
            for (int j = 0; j < 3; j++) {
                if (board[i][j] == ch) {
                    cnt++;
                }
            }
        }
        return cnt;
    }

    /**
     * Determines whether the supplied player has a winning line.
     */
    private static boolean hasWon(char[][] board, char player) {
        // rows
        for (int i = 0; i < 3; i++) {
            if (board[i][0] == player && board[i][1] == player && board[i][2] == player) {
                return true;
            }
        }
        // columns
        for (int j = 0; j < 3; j++) {
            if (board[0][j] == player && board[1][j] == player && board[2][j] == player) {
                return true;
            }
        }
        // diagonals
        if (board[0][0] == player && board[1][1] == player && board[2][2] == player) {
            return true;
        }
        if (board[2][0] == player && board[1][1] == player && board[0][2] == player) {
            return true;
        }
        return false;
    }

    /**
     * Evaluates the current board state and returns the appropriate message.
     *
     * The method encapsulates all legality checks and outcome messages.
     */
    private static String evaluate(int xCount, int oCount, int emptyCount,
                                   boolean xWon, boolean oWon) {
        // ---- illegal board configurations ------------------------------------
        if (xCount < oCount || xCount > oCount + 1) {
            return "illegal";
        }
        if (xWon && oWon) {
            return "illegal";
        }
        if (xWon && xCount != oCount + 1) {
            return "illegal";
        }
        if (oWon && xCount != oCount) {
            return "illegal";
        }
        if (oWon && oCount > xCount + 1) {
            return "illegal";
        }

        // ---- decisive outcomes -------------------------------------------------
        if (xWon) {
            return "the first player won";
        }
        if (oWon) {
            return "the second player won";
        }

        // ---- game still in progress -------------------------------------------
        if (emptyCount > 0) {
            // next move is first player when the board has equal X and O counts
            return (xCount == oCount) ? "first" : "second";
        }

        // ---- draw ---------------------------------------------------------------
        return "draw";
    }
}

/**
 * Simple console implementation of Tic‑Tac‑Toe.
 *
 * <p>It reads a 3×3 board from standard input, validates the board state,
 * and prints the result of the game:
 * <ul>
 *   <li>“illegal” – the board cannot appear in a real game</li>
 *   <li>“the first player won” – player X has a winning line</li>
 *   <li>“the second player won” – player O (the character '0') has a winning line</li>
 *   <li>“first” – the first player must make the next move</li>
 *   <li>“second” – the second player must make the next move</li>
 *   <li>“draw” – the board is full and nobody has won</li>
 * </ul>
 *
 * <p>The program has been refactored for readability, maintainability and
 * proper resource handling.
 */
public class TicTacToe {

    /** Symbol used for an empty cell. */
    private static final char EMPTY = '.';

    /** Symbol used by the first player (X). */
    private static final char PLAYER_X = 'X';

    /** Symbol used by the second player (0). */
    private static final char PLAYER_O = '0';

    public static void main(String[] args) {
        try (var reader = new java.io.BufferedReader(
                new java.io.InputStreamReader(System.in))) {
            new Game(reader).play();
        } catch (Exception e) {
            // Any problem while reading the board is treated as an illegal state.
            System.out.println("illegal");
        }
    }
}

/**
 * Encapsulates the game logic.
 *
 * <p>All methods are intentionally small and focused, making the code easier to
 * test and extend.
 */
class Game {

    private final java.io.BufferedReader reader;

    /** The 3×3 board, stored as characters. */
    private char[][] board;

    Game(java.io.BufferedReader reader) {
        this.reader = reader;
    }

    /** Entry point for the game – loads the board and prints the outcome. */
    void play() throws java.io.IOException {
        loadBoard();
        evaluateAndPrintResult();
    }

    /** Reads three lines from {@code reader} to build the board. */
    private void loadBoard() throws java.io.IOException {
        board = new char[3][3];
        for (int row = 0; row < 3; row++) {
            String line = reader.readLine();
            if (line == null) {
                throw new IllegalArgumentException("Insufficient input lines");
            }
            board[row] = line.toCharArray();
        }
    }

    /** Determines the game state and prints the corresponding message. */
    private void evaluateAndPrintResult() {
        int countX = countOccurrences(PLAYER_X);
        int countO = countOccurrences(PLAYER_O);
        boolean xWon = hasWon(PLAYER_X);
        boolean oWon = hasWon(PLAYER_O);
        boolean boardFull = isBoardFull();

        if (isIllegal(countX, countO, xWon, oWon)) {
            System.out.println("illegal");
            return;
        }

        if (xWon) {
            System.out.println("the first player won");
            return;
        }

        if (oWon) {
            System.out.println("the second player won");
            return;
        }

        if (!boardFull) {
            System.out.println(countX == countO ? "first" : "second");
        } else {
            System.out.println("draw");
        }
    }

    /** Counts how many times {@code symbol} appears on the board. */
    private int countOccurrences(char symbol) {
        int cnt = 0;
        for (char[] row : board) {
            for (char cell : row) {
                if (cell == symbol) {
                    cnt++;
                }
            }
        }
        return cnt;
    }

    /** Returns {@code true} if there is at least one empty cell. */
    private boolean isBoardFull() {
        for (char[] row : board) {
            for (char cell : row) {
                if (cell == EMPTY) {
                    return false;
                }
            }
        }
        return true;
    }

    /**
     * Checks whether the current board configuration obeys the rules of Tic‑Tac‑Toe.
     *
     * @return {@code true} if the board is illegal, {@code false} otherwise.
     */
    private boolean isIllegal(int countX, int countO, boolean xWon, boolean oWon) {
        // X always starts, therefore the move counts must respect the turn order.
        if (oWon && countX > countO) return true;          // O cannot have more moves than X
        if (xWon && countO != countX) return true;         // X cannot win on O's turn
        if (countO > countX) return true;                  // O cannot have more moves than X
        if (countX - countO > 1) return true;              // X cannot have two more moves than O
        if (xWon && oWon) return true;                     // Both players cannot win simultaneously
        return false;
    }

    /**
     * Checks whether the given player has any complete row, column or diagonal.
     *
     * @param player the symbol to test for a win
     * @return {@code true} if the player has a winning line
     */
    private boolean hasWon(char player) {
        // Check rows
        for (int i = 0; i < 3; i++) {
            if (board[i][0] == player && board[i][1] == player && board[i][2] == player) {
                return true;
            }
        }
        // Check columns
        for (int i = 0; i < 3; i++) {
            if (board[0][i] == player && board[1][i] == player && board[2][i] == player) {
                return true;
            }
        }
        // Check the two diagonals
        if (board[0][0] == player && board[1][1] == player && board[2][2] == player) {
            return true;
        }
        if (board[0][2] == player && board[1][1] == player && board[2][0] == player) {
            return true;
        }
        return false;
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;

/**
 * Main class for the Tic‑Tac‑Toe board validator.
 *
 * The program reads three lines from standard input, each line representing a
 * row of a 3×3 board (characters 'X', 'O' or '.' for empty).  It then decides
 * which message to print:
 *   • "illegal"          – the board configuration cannot appear in a legal game
 *   • "first"            – it is the first player's turn
 *   • "second"           – it is the second player's turn
 *   • "the first player won"
 *   • "the second player won"
 *   • "draw"
 */
public class Main {

    /** Characters used on the board */
    private static final char EMPTY = '.';

    /** All 8 possible winning line indices (row‑major order) */
    private static final int[][] WIN_LINES = {
            {0, 1, 2}, {3, 4, 5}, {6, 7, 8}, // rows
            {0, 3, 6}, {1, 4, 7}, {2, 5, 8}, // columns
            {0, 4, 8}, {2, 4, 6}             // diagonals
    };

    public static void main(String[] args) {
        // -----------------------------------------------------------------
        // 1. Input handling
        // -----------------------------------------------------------------
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(System.in))) {
            String line1 = reader.readLine();
            String line2 = reader.readLine();
            String line3 = reader.readLine();

            // Missing lines make the board impossible
            if (line1 == null || line2 == null || line3 == null) {
                System.out.println("illegal");
                return;
            }

            // Build a single 9‑character representation of the board
            StringBuilder sb = new StringBuilder();
            sb.append(line1).append(line2).append(line3);
            String board = sb.toString();

            // The board must contain exactly 9 cells
            if (board.length() != 9) {
                System.out.println("illegal");
                return;
            }

            // -----------------------------------------------------------------
            // 2. Basic statistics
            // -----------------------------------------------------------------
            int xCount = countMark(board, 'X');
            int oCount = countMark(board, 'O');
            int emptyCount = countMark(board, EMPTY);

            // -----------------------------------------------------------------
            // 3. Win detection
            // -----------------------------------------------------------------
            boolean xWins = hasWon(board, 'X');
            boolean oWins = hasWon(board, 'O');

            // -----------------------------------------------------------------
            // 4. Validate board legality
            // -----------------------------------------------------------------
            if (isIllegalBoard(xCount, oCount, xWins, oWins)) {
                System.out.println("illegal");
                return;
            }

            // -----------------------------------------------------------------
            // 5. Determine and print the result
            // -----------------------------------------------------------------
            if (xCount == 0 && oCount == 0) {               // completely empty board
                System.out.println("first");
                return;
            }

            if (xWins) {
                System.out.println("the first player won");
            } else if (oWins) {
                System.out.println("the second player won");
            } else if (emptyCount == 0) {
                System.out.println("draw");
            } else if (xCount > oCount) {
                System.out.println("second");
            } else {
                System.out.println("first");
            }

        } catch (IOException e) {
            // Unexpected I/O error – print a stack trace for debugging
            e.printStackTrace();
        }
    }

    /** Count how many times {@code mark} appears in the board. */
    private static int countMark(String board, char mark) {
        int cnt = 0;
        for (int i = 0; i < board.length(); i++) {
            if (board.charAt(i) == mark) {
                cnt++;
            }
        }
        return cnt;
    }

    /** Check whether the given player has a complete winning line. */
    private static boolean hasWon(String board, char player) {
        for (int[] line : WIN_LINES) {
            if (board.charAt(line[0]) == player &&
                board.charAt(line[1]) == player &&
                board.charAt(line[2]) == player) {
                return true;
            }
        }
        return false;
    }

    /**
     * Returns {@code true} if the supplied board configuration cannot occur
     * during a legitimate game of Tic‑Tac‑Toe.
     *
     * @param xCount number of 'X' marks
     * @param oCount number of 'O' marks
     * @param xWins  {@code true} if 'X' has a winning line
     * @param oWins  {@code true} if 'O' has a winning line
     */
    private static boolean isIllegalBoard(int xCount, int oCount,
                                          boolean xWins, boolean oWins) {
        // 1) Turn‑order violations
        if (oCount > xCount || xCount > oCount + 1) {
            return true;
        }

        // 2) Both players cannot win simultaneously
        if (xWins && oWins) {
            return true;
        }

        // 3) 'X' can only win on its own turn (xCount == oCount + 1)
        if (xWins && xCount != oCount + 1) {
            return true;
        }

        // 4) 'O' can only win on its own turn (xCount == oCount)
        if (oWins && xCount != oCount) {
            return true;
        }

        return false;
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.StringTokenizer;

/**
 * Entry point of the application.
 *
 * The program reads a 3×3 Tic‑Tac‑Toe board (characters 'X', '0' and '.'), validates the
 * board state and prints the appropriate result:
 * <ul>
 *   <li>illegal – the board cannot appear in a real game</li>
 *   <li>draw – board is full and nobody has won</li>
 *   <li>second / first – the game is not finished; the player whose turn it should be</li>
 *   <li>the first player won / the second player won – a player has a winning line</li>
 * </ul>
 */
public class Main {

    /** Symbol used for the first player. */
    private static final char PLAYER_X = 'X';

    /** Symbol used for the second player. */
    private static final char PLAYER_O = '0';          // note: the original code uses '0'

    /** Representation of the 3×3 board. */
    private static final class Board {
        private final char[][] cells = new char[3][3];

        /** Loads the board from the supplied {@link InputReader}. */
        void loadFrom(InputReader reader) throws IOException {
            for (int row = 0; row < 3; ++row) {
                String line = reader.n();
                if (line == null) {
                    throw new IOException("Not enough input lines");
                }
                cells[row] = line.toCharArray();
            }
        }

        /** Returns the character at {@code (r,c)}. */
        char get(int r, int c) {
            return cells[r][c];
        }

        /** Counts how many times {@code symbol} appears on the board. */
        int count(char symbol) {
            int cnt = 0;
            for (int r = 0; r < 3; ++r) {
                for (int c = 0; c < 3; ++c) {
                    if (cells[r][c] == symbol) {
                        ++cnt;
                    }
                }
            }
            return cnt;
        }

        /** Number of empty cells ('.'). */
        int countEmpty() {
            return count('.');
        }

        /** Checks whether the supplied player has a winning line. */
        boolean hasWon(char player) {
            // Check rows and columns
            for (int i = 0; i < 3; ++i) {
                if (cells[i][0] == player && cells[i][1] == player && cells[i][2] == player) {
                    return true;
                }
                if (cells[0][i] == player && cells[1][i] == player && cells[2][i] == player) {
                    return true;
                }
            }
            // Check the two diagonals
            if (cells[0][0] == player && cells[1][1] == player && cells[2][2] == player) {
                return true;
            }
            if (cells[0][2] == player && cells[1][1] == player && cells[2][0] == player) {
                return true;
            }
            return false;
        }

        /** Returns a printable representation of the board (useful for debugging). */
        @Override
        public String toString() {
            StringBuilder sb = new StringBuilder();
            for (int r = 0; r < 3; ++r) {
                sb.append(cells[r]);
                sb.append('\n');
            }
            return sb.toString();
        }
    }

    /** Simple token reader that works like the original `InputReader`. */
    private static final class InputReader {
        private final BufferedReader br;
        private StringTokenizer st;

        InputReader(InputStream in) {
            this.br = new BufferedReader(new InputStreamReader(in));
        }

        /** Returns the next token, reading a new line when necessary. */
        String n() throws IOException {
            while (st == null || !st.hasMoreElements()) {
                String line = br.readLine();
                if (line == null) {
                    return null;                // EOF
                }
                st = new StringTokenizer(line);
            }
            return st.nextToken();
        }
    }

    /** Core logic that validates the board and prints the result. */
    private static final class GameValidator {
        private final Board board = new Board();

        /** Reads the board, validates it, and prints the corresponding message. */
        void process(InputReader reader, PrintWriter out) throws IOException {
            board.loadFrom(reader);

            int xCount = board.count(PLAYER_X);
            int oCount = board.count(PLAYER_O);
            int emptyCount = board.countEmpty();

            boolean xWon = board.hasWon(PLAYER_X);
            boolean oWon = board.hasWon(PLAYER_O);

            // -----------------------------------------------------------------
            // 1️⃣  Invalid board states (illegal)
            // -----------------------------------------------------------------
            if (invalidCounts(xCount, oCount) || bothWon(xWon, oWon)) {
                out.println("illegal");
                return;
            }

            // -----------------------------------------------------------------
            // 2️⃣  No winner yet – decide what to print next
            // -----------------------------------------------------------------
            if (!xWon && !oWon) {
                if (xCount + oCount == 9) {
                    out.println("draw");
                } else if (xCount > oCount) {
                    out.println("second");
                } else {
                    out.println("first");
                }
                return;
            }

            // -----------------------------------------------------------------
            // 3️⃣  There is a winner – verify that the win matches the turn order
            // -----------------------------------------------------------------
            if (xWon) {
                // X (first player) can only win on his turn → xCount must be one more than oCount
                if (xCount == oCount + 1) {
                    out.println("the first player won");
                } else {
                    out.println("illegal");
                }
            } else { // oWon
                // O (second player) can only win on his turn → counts must be equal
                if (xCount == oCount) {
                    out.println("the second player won");
                } else {
                    out.println("illegal");
                }
            }
        }

        /** Returns true if the numbers of X and O are not compatible with the rules. */
        private boolean invalidCounts(int x, int o) {
            int diff = x - o;
            return diff != 0 && diff != 1;
        }

        /** Returns true if both players have winning lines simultaneously. */
        private boolean bothWon(boolean xWon, boolean oWon) {
            return xWon && oWon;
        }
    }

    /** --------------------------------------------------------------------- */
    /** Entry point – wiring everything together.                               */
    /** --------------------------------------------------------------------- */
    public static void main(String[] args) throws Exception {
        InputStream input = System.in;
        PrintWriter out = new PrintWriter(System.out, true);

        InputReader reader = new InputReader(input);
        GameValidator validator = new GameValidator();

        validator.process(reader, out);

        out.flush();      // ensure all output is written before the JVM exits
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;

/**
 * Entry point of the Tic‑Tac‑Toe validator.
 */
public final class TicTacToe {

    /** Texts used in the output – keep them identical to the original version. */
    private static final String ILLEGAL = "illegal";
    private static final String FIRST_WON = "the first player won";
    private static final String SECOND_WON = "the second player won";
    private static final String DRAW = "draw";

    public static void main(String[] args) throws IOException {
        /* -------------------------------------------------------------
         *  1️⃣  Read the 3×3 board from standard input and record the
         *      number of moves made by each player.
         * ------------------------------------------------------------- */
        Board board = new Board();
        int xCount = 0;   // moves of the first player (X)
        int oCount = 0;   // moves of the second player (O)
        boolean draw = true; // will be cleared if any cell is empty

        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in))) {
            for (int row = 0; row < 3; row++) {
                String line = br.readLine();
                for (int col = 0; col < 3; col++) {
                    char cell = line.charAt(col);
                    if (cell == 'X') {
                        xCount++;
                        board.set('X', row, col);
                    } else if (cell == '0') {
                        oCount++;
                        board.set('0', row, col);
                    } else {
                        // any other character means an empty cell
                        board.set('.', row, col);
                        draw = false; // there is at least one empty square
                    }
                }
            }
        }

        /* -------------------------------------------------------------
         *  2️⃣  Validate the move sequence.
         * ------------------------------------------------------------- */
        if (isIllegal(xCount, oCount, board)) {
            System.out.println(ILLEGAL);
            return;
        }

        /* -------------------------------------------------------------
         *  3️⃣  Determine the game result.
         * ------------------------------------------------------------- */
        if (board.hasWin('X')) {
            System.out.println(FIRST_WON);
        } else if (board.hasWin('0')) {
            System.out.println(SECOND_WON);
        } else if (draw) {
            System.out.println(DRAW);
        } else {
            // According to the original program this prints the opposite
            // player name when X has made one move more than O.
            System.out.println(xCount > oCount ? "second" : "first");
        }
    }

    /** Returns true if the move counts break the rules of Tic‑Tac‑Toe. */
    private static boolean isIllegal(int x, int o, Board board) {
        // O can never have more moves than X, and the difference may be at most 1.
        boolean illegalByCount = o > x || Math.abs(x - o) > 1;

        // If a player has won, the move counts must respect the turn order.
        if (!illegalByCount) {
            if (board.hasWin('X') && !(x == o + 1)) {
                illegalByCount = true;
            } else if (board.hasWin('0') && !(x == o)) {
                illegalByCount = true;
            }
        }
        return illegalByCount;
    }
}

/**
 * Simple container that represents a 3×3 Tic‑Tac‑Toe board.
 * It stores the cells in a flat {@code char[9]} array and provides
 * utilities to place a symbol and to test for a winning line.
 */
final class Board {

    private static final int SIZE = 3;                 // board dimension
    private final char[] cells = new char[SIZE * SIZE]; // flattened board

    /** Places a symbol at the given row/column. */
    void set(char symbol, int row, int col) {
        cells[pos(row, col)] = symbol;
    }

    /** Translates (row, col) → linear index. */
    private int pos(int row, int col) {
        return row * SIZE + col;
    }

    /** Returns the symbol stored at the linear position {@code i}. */
    char get(int i) {
        return cells[i];
    }

    /** Checks whether the given player has a complete line (row, column or diagonal). */
    boolean hasWin(char player) {
        // All 8 possible winning lines expressed as lists of linear indices.
        final int[][] WIN_LINES = {
                {0, 1, 2}, {3, 4, 5}, {6, 7, 8}, // rows
                {0, 3, 6}, {1, 4, 7}, {2, 5, 8}, // columns
                {0, 4, 8}, {2, 4, 6}             // diagonals
        };

        for (int[] line : WIN_LINES) {
            if (cells[line[0]] == player &&
                cells[line[1]] == player &&
                cells[line[2]] == player) {
                return true;
            }
        }
        return false;
    }
}

import java.io.BufferedReader;
