 *   <li>Validating input early and clearly.</li>
 *   <li>Using try‑with‑resources for safe resource handling.</li>
 *   <li>Removing duplicated code and consolidating win‑checking logic.</li>
 * </ul>
 */
public class Main {

    private static final char PLAYER_X = 'X';
    private static final char PLAYER_O = 'O';
    private static final int BOARD_SIZE = 3;

    public static void main(String[] args) throws IOException {
        // Read three rows from standard input
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in))) {
            char[][] board = readBoard(br);

            int countX = countOccurrences(board, PLAYER_X);
            int countO = countOccurrences(board, PLAYER_O);
            boolean xWins = isWin(board, PLAYER_X);
            boolean oWins = isWin(board, PLAYER_O);

            handleResult(countX, countO, xWins, oWins);
        }
    }

    /** Reads exactly three lines from the supplied reader and converts them to a 3×3 board. */
    private static char[][] readBoard(BufferedReader br) throws IOException {
        String row1 = br.readLine();
        String row2 = br.readLine();
        String row3 = br.readLine();

        return new char[][] {
                row1.toCharArray(),
                row2.toCharArray(),
                row3.toCharArray()
        };
    }

    /** Counts how many times {@code player} appears on the board. */
    private static int countOccurrences(char[][] board, char player) {
        int count = 0;
        for (int i = 0; i < BOARD_SIZE; i++) {
            for (int j = 0; j < BOARD_SIZE; j++) {
                if (board[i][j] == player) {
                    count++;
                }
            }
        }
        return count;
    }

    /** Determines whether {@code player} has a winning line (row, column or diagonal). */
    private static boolean isWin(char[][] board, char player) {
        // rows
        for (int i = 0; i < BOARD_SIZE; i++) {
            if (board[i][0] == player && board[i][1] == player && board[i][2] == player) {
                return true;
            }
        }
        // columns
        for (int j = 0; j < BOARD_SIZE; j++) {
            if (board[0][j] == player && board[1][j] == player && board[2][j] == player) {
                return true;
            }
        }
        // diagonals
        if (board[0][0] == player && board[1][1] == player && board[2][2] == player) {
            return true;
        }
        if (board[0][2] == player && board[1][1] == player && board[2][0] == player) {
            return true;
        }
        return false;
    }

    /**
     * Validates the game state and prints the appropriate message.
     *
     * <p>The printing rules follow the original specification:
     *
     * <ul>
     *   <li>illegal – state cannot arise from a proper turn order or has contradictory wins.</li>
     *   <li>the first player won / the second player won – when a player has a winning line.</li>
     *   <li>draw – the board is full and there is no winner.</li>
     *   <li>first / second – whose turn it is to move next.</li>
     * </ul>
     */
    private static void handleResult(int countX, int countO, boolean xWins, boolean oWins) {
        if (!isStateLegal(countX, countO, xWins, oWins)) {
            System.out.println("illegal");
            return;
        }

        if (xWins) {
            System.out.println("the first player won");
            return;
        }
        if (oWins) {
            System.out.println("the second player won");
            return;
        }
        if (isBoardFull(countX, countO)) {
            System.out.println("draw");
            return;
        }

        // No winner, board not full – indicate whose turn it is
        System.out.println(countX > countO ? "second" : "first");
    }

    /** Checks whether the move counts and win flags respect the rules of Tic‑Tac‑Toe. */
    private static boolean isStateLegal(int countX, int countO, boolean xWins, boolean oWins) {
        // Basic turn‑order validation
        if (countX < countO || countX > countO + 1) {
            return false;
        }
        // Both players cannot win simultaneously
        if (xWins && oWins) {
            return false;
        }
        // X can only win on its own extra move
        if (xWins && countX != countO + 1) {
            return false;
        }
        // O can only win when the move counts are equal
        if (oWins && countX != countO) {
            return false;
        }
        return true;
    }

    /** Returns true when the board is completely filled (9 moves). */
    private static boolean isBoardFull(int countX, int countO) {
        return countX + countO == BOARD_SIZE * BOARD_SIZE;
    }
}

package tictactoe;

import java.util.Scanner;

/**
 * Entry point for the Tic‑Tac‑Toe validator.
 * Reads a 3×3 board from standard input, validates the position,
 * determines the game outcome and prints the appropriate message.
 */
public class Main {

    /** Symbol for an empty cell. */
    private static final char EMPTY = '.';
    /** Symbol for the first player (X). */
    private static final char PLAYER_X = 'x';
    /** Symbol for the second player (O). */
    private static final char PLAYER_O = '0';

    /** Possible textual results that the program can emit. */
    private enum Result {
        FIRST_PLAYER_WON,
        SECOND_PLAYER_WON,
        DRAW,
        FIRST_TURN,
        SECOND_TURN,
        ILLEGAL
    }

    public static void main(String[] args) {
        char[][] board = readBoard();
        Result result = evaluate(board);
        printResult(result);
    }

    /** Reads three rows of three characters each from {@link Scanner}. */
    private static char[][] readBoard() {
        Scanner scanner = new Scanner(System.in);
        char[][] board = new char[3][3];

        for (int i = 0; i < 3; i++) {
            String line = scanner.next().toLowerCase();
            if (line.length() != 3) {
                throw new IllegalArgumentException("Each row must contain exactly 3 characters");
            }
            for (int j = 0; j < 3; j++) {
                board[i][j] = line.charAt(j);
            }
        }
        return board;
    }

    /**
     * Evaluates the current board state.
     *
     * @return a {@link Result} describing the game outcome.
     */
    private static Result evaluate(char[][] board) {
        int xCount = countOccurrences(board, PLAYER_X);
        int oCount = countOccurrences(board, PLAYER_O);
        int emptyCount = countOccurrences(board, EMPTY);

        // ---- 1. Basic count validation -------------------------------------------------
        if (!isCountCombinationValid(xCount, oCount)) {
            return Result.ILLEGAL;
        }

        // ---- 2. Winner detection --------------------------------------------------------
        boolean xWon = hasWon(board, PLAYER_X);
        boolean oWon = hasWon(board, PLAYER_O);

        if (xWon && oWon) {
            return Result.ILLEGAL; // both cannot win
        }

        // The winning player must have a consistent number of moves.
        if (xWon && !isWinningCountConsistent(xCount, oCount, true)) {
            return Result.ILLEGAL;
        }
        if (oWon && !isWinningCountConsistent(xCount, oCount, false)) {
            return Result.ILLEGAL;
        }

        // ---- 3. Determine final state ---------------------------------------------------
        if (xWon) {
            return Result.FIRST_PLAYER_WON;
        }
        if (oWon) {
            return Result.SECOND_PLAYER_WON;
        }
        if (emptyCount == 0) {
            return Result.DRAW;
        }

        // No winner yet – indicate whose turn it is.
        return (xCount == oCount) ? Result.FIRST_TURN : Result.SECOND_TURN;
    }

    /** Counts how many times {@code symbol} appears on the board. */
    private static int countOccurrences(char[][] board, char symbol) {
        int cnt = 0;
        for (char[] row : board) {
            for (char cell : row) {
                if (cell == symbol) {
                    cnt++;
                }
            }
        }
        return cnt;
    }

    /** Checks whether a particular move count combination obeys the rules of Tic‑Tac‑Toe. */
    private static boolean isCountCombinationValid(int x, int o) {
        return Math.abs(x - o) <= 1 && o <= x;
    }

    /** Verifies that a win is consistent with the move counts (X must have one more move than O, O must have equal moves). */
    private static boolean isWinningCountConsistent(int x, int o, boolean isXWinning) {
        return isXWinning ? (x == o + 1) : (x == o);
    }

    /** Determines if the given player has a complete row, column or diagonal. */
    private static boolean hasWon(char[][] board, char player) {
        // rows & columns
        for (int i = 0; i < 3; i++) {
            if (allEqual(board[i][0], board[i][1], board[i][2], player)) {
                return true;
            }
            if (allEqual(board[0][i], board[1][i], board[2][i], player)) {
                return true;
            }
        }
        // diagonals
        return allEqual(board[0][0], board[1][1], board[2][2], player)
                || allEqual(board[2][0], board[1][1], board[0][2], player);
    }

    /** Helper that checks whether three cells are equal to {@code expected}. */
    private static boolean allEqual(char a, char b, char c, char expected) {
        return a == expected && b == expected && c == expected;
    }

    /** Prints the textual result corresponding to {@link Result}. */
    private static void printResult(Result result) {
        switch (result) {
            case FIRST_PLAYER_WON -> System.out.println("the first player won");
            case SECOND_PLAYER_WON -> System.out.println("the second player won");
            case DRAW -> System.out.println("draw");
            case FIRST_TURN -> System.out.println("first");
            case SECOND_TURN -> System.out.println("second");
            case ILLEGAL -> System.out.println("illegal");
        }
    }
}

import java.util.Scanner;

/**
 * Simple Tic‑Tac‑Toe validator.
 * <p>
 * Reads a 3×3 board from standard input where each line contains exactly three
 * characters: {@code X}, {@code 0} (zero) or {@code .}.  The program then reports
 * the state of the game – e.g. "the first player won", "the second player won",
 * "draw", "first", "second", "not good" or "illegal".
 * </p>
 */
public class Main {

    /** Size of the board – kept as a constant for clarity. */
    private static final int BOARD_SIZE = 3;

    /**
     * Holds the board and the counters for the number of {@code X} and {@code 0}
     * symbols.
     */
    private static final class GameState {
        private final char[][] board = new char[BOARD_SIZE][BOARD_SIZE];
        private int countX;
        private int count0;

        /**
         * Constructs the game state from raw input lines.
         *
         * @param lines three lines, each containing exactly three valid characters
         */
        GameState(String[] lines) {
            if (lines.length != BOARD_SIZE) {
                throw new IllegalArgumentException("Exactly " + BOARD_SIZE + " lines required");
            }

            for (int i = 0; i < BOARD_SIZE; i++) {
                String line = lines[i];
                if (line == null || line.length() != BOARD_SIZE) {
                    throw new IllegalArgumentException(
                            "Each line must contain exactly " + BOARD_SIZE + " characters");
                }
                for (int j = 0; j < BOARD_SIZE; j++) {
                    char c = line.charAt(j);
                    board[i][j] = c;
                    switch (c) {
                        case 'X' -> ++countX;
                        case '0' -> ++count0;
                        case '.' -> /* nothing */;
                        default -> throw new IllegalArgumentException(
                                "Invalid character '" + c + "' at position [" + i + "][" + j + "]");
                    }
                }
            }
        }

        char[][] getBoard() {
            return board;
        }

        int getCountX() {
            return countX;
        }

        int getCount0() {
            return count0;
        }

        /** Returns {@code true} if the board is completely filled. */
        boolean isFull() {
            return countX + count0 == BOARD_SIZE * BOARD_SIZE;
        }
    }

    /** Determines the outcome of the game according to the rules of Tic‑Tac‑Toe. */
    private static String evaluate(GameState state) {
        char[][] b = state.getBoard();
        int xCount = state.getCountX();
        int oCount = state.getCount0();

        // ---------- Illegal position checks ----------
        if (xCount > oCount + 1) {
            return "illegal";
        }
        if (oCount > xCount) {
            return "illegal";
        }
        if (hasWinner(b, 'X') && hasWinner(b, '0')) {
            return "illegal";
        }
        if (hasWinner(b, 'X') && xCount == oCount) {
            return "illegal";
        }
        if (hasWinner(b, '0') && xCount > oCount) {
            return "illegal";
        }

        // ---------- Win / draw detection ----------
        boolean xWon = hasWinner(b, 'X');
        boolean oWon = hasWinner(b, '0');

        if (xWon) {
            return "the first player won";
        }
        if (oWon) {
            return "the second player won";
        }
        if (!xWon && !oWon && !state.isFull()) {
            // game not finished and no winner – not a draw yet
            return "not good";
        }
        if (!xWon && !oWon && state.isFull()) {
            return "draw";
        }
        // No winner but counts decide whose turn it is
        return xCount == oCount ? "first" : "second";
    }

    /** Checks whether the given player has a complete row, column or diagonal. */
    private static boolean hasWinner(char[][] board, char player) {
        // Quick win detection – we only need to verify that a line consists
        // entirely of the player's symbol.
        // Rows
        for (int i = 0; i < BOARD_SIZE; i++) {
            if (board[i][0] == player && board[i][1] == player && board[i][2] == player) {
                return true;
            }
        }
        // Columns
        for (int j = 0; j < BOARD_SIZE; j++) {
            if (board[0][j] == player && board[1][j] == player && board[2][j] == player) {
                return true;
            }
        }
        // Diagonals
        if (board[0][0] == player && board[1][1] == player && board[2][2] == player) {
            return true;
        }
        if (board[0][2] == player && board[1][1] == player && board[2][0] == player) {
            return true;
        }
        return false;
    }

    /** Main entry point – reads from stdin and prints the evaluation. */
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        String[] lines = new String[BOARD_SIZE];
        for (int i = 0; i < BOARD_SIZE; i++) {
            lines[i] = scanner.nextLine().trim();
        }
        try {
            GameState state = new GameState(lines);
            System.out.println(evaluate(state));
        } catch (IllegalArgumentException e) {
            System.out.println("illegal");
        }
    }
}

import java.util.Scanner;

/**
 * Maintainable Tic‑Tac‑Toe validator.
 *
 * The program reads three lines, each representing a row of the board,
 * validates the board state and prints one of the following messages:
 *   "illegal",
 *   "the first player won",
 *   "the second player won",
 *   "first",
 *   "second",
 *   "draw".
 */
public class TicTacToe {

    // -------------------------------------------------------------------------
    // Constants
    // -------------------------------------------------------------------------
    private static final char PLAYER_X = 'X';
    private static final char PLAYER_O = 'O';
    private static final int BOARD_SIZE = 3;

    // -------------------------------------------------------------------------
    // Entry point
    // -------------------------------------------------------------------------
    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            String row1 = scanner.nextLine().trim();
            String row2 = scanner.nextLine().trim();
            String row3 = scanner.nextLine().trim();

            Board board = new Board(row1, row2, row3);
            Result result = board.analyse();

            System.out.println(result.message);
        }
    }

    // -------------------------------------------------------------------------
    // Board representation and analysis logic
    // -------------------------------------------------------------------------
    /**
     * Encapsulates the 3×3 board and all rules required to determine the game
     * outcome or to detect an illegal configuration.
     */
    private static final class Board {
        private final char[][] cells = new char[BOARD_SIZE][BOARD_SIZE];

        Board(String r1, String r2, String r3) {
            // Validate that every row contains exactly three characters.
            if (!isValidRow(r1) || !isValidRow(r2) || !isValidRow(r3)) {
                throw new IllegalArgumentException("illegal");
            }
            cells[0] = r1.toCharArray();
            cells[1] = r2.toCharArray();
            cells[2] = r3.toCharArray();
        }

        /** A row is valid when it consists of exactly three characters. */
        private static boolean isValidRow(String row) {
            return row.length() == BOARD_SIZE;
        }

        /**
         * Performs the complete analysis of the board.
         *
         * @return a {@link Result} object containing the message to print.
         */
        Result analyse() {
            int countX = countOccurrences(PLAYER_X);
            int countO = countOccurrences(PLAYER_O);

            // 1️⃣ Illegal number of moves
            if (isIllegalCount(countX, countO)) {
                return new Result("illegal");
            }
            // 2️⃣ Both players cannot win simultaneously
            if (hasBothWon()) {
                return new Result("illegal");
            }

            boolean xWon = hasWon(PLAYER_X);
            boolean oWon = hasWon(PLAYER_O);

            // 3️⃣ Legal winning states
            if (xWon && countX == countO + 1) {
                return new Result("the first player won");
            }
            if (oWon && countX == countO) {
                return new Result("the second player won");
            }
            if (xWon || oWon) {
                // A win without satisfying turn‑order constraints is illegal
                return new Result("illegal");
            }

            // 4️⃣ Game finished (full board, no winner)
            if (countX + countO == BOARD_SIZE * BOARD_SIZE) {
                return new Result("draw");
            }

            // 5️⃣ Next player to move
            return new Result(countX == countO ? "first" : "second");
        }

        /** Counts how many times {@code symbol} appears on the board. */
        private int countOccurrences(char symbol) {
            int cnt = 0;
            for (char[] row : cells) {
                for (char cell : row) {
                    if (cell == symbol) {
                        cnt++;
                    }
                }
            }
            return cnt;
        }

        /** Checks whether {@code symbol} has a complete row, column or diagonal. */
        private boolean hasWon(char symbol) {
            // rows
            for (int i = 0; i < BOARD_SIZE; i++) {
                if (allEqual(cells[i], symbol)) {
                    return true;
                }
            }
            // columns
            for (int i = 0; i < BOARD_SIZE; i++) {
                if (cells[0][i] == symbol && cells[1][i] == symbol && cells[2][i] == symbol) {
                    return true;
                }
            }
            // diagonals
            if (cells[0][0] == symbol && cells[1][1] == symbol && cells[2][2] == symbol) {
                return true;
            }
            if (cells[0][2] == symbol && cells[1][1] == symbol && cells[2][0] == symbol) {
                return true;
            }
            return false;
        }

        /** Helper: true if every element of the given array equals {@code symbol}. */
        private boolean allEqual(char[] arr, char symbol) {
            return arr[0] == symbol && arr[1] == symbol && arr[2] == symbol;
        }

        /** Returns true if the move counts violate the turn order rules. */
        private boolean isIllegalCount(int x, int o) {
            // X always starts → O can never be ahead and the difference must be ≤ 1
            return o > x || x > o + 1;
        }

        /** Returns true if both players have winning lines. */
        private boolean hasBothWon() {
            return hasWon(PLAYER_X) && hasWon(PLAYER_O);
        }
    }

    /**
     * Simple container that carries the textual output of the analysis.
     */
    private static final class Result {
        final String message;
        Result(String message) {
            this.message = message;
        }
    }
}

import java.util.Scanner;

/**
 * Refactored Tic‑Tac‑Toe validator.
 *
 * <p>The program reads a 3×3 board where each cell contains either 'X',
 * '0' (zero) or any other character.  It then determines whether the
 * board configuration is legal and, if legal, which player has won,
 * whether the game is a draw, or whose turn is next.</p>
 *
 * <p>The output messages are kept identical to the original program:
 *
 * <ul>
 *   <li>"illegal"</li>
 *   <li>"draw"</li>
 *   <li>"the first player won"</li>
 *   <li>"the second player won"</li>
 *   <li>"second"</li>
 *   <li>"first"</li>
 * </ul>
 * </p>
 */
public class TicTacToe {

    /** Return codes used by {@link #analyse(char[][])}. */
    private static final int ILLEGAL = 0;
    private static final int DRAW = 1;
    private static final int FIRST_WON = 2;
    private static final int SECOND_WON = 3;
    private static final int NEXT_SECOND = 4; // prints "second"
    private static final int NEXT_FIRST = 5;  // prints "first"

    public static void main(String[] args) {
        char[][] board = readBoard();
        int outcome = analyse(board);
        printOutcome(outcome);
    }

    /** Reads exactly three lines of three characters each from {@code System.in}. */
    private static char[][] readBoard() {
        Scanner scanner = new Scanner(System.in);
        if (!scanner.hasNextLine()) {
            throw new IllegalStateException("No input provided.");
        }

        char[][] board = new char[3][3];
        for (int i = 0; i < 3; i++) {
            String line = scanner.nextLine().trim();
            if (line.length() != 3) {
                throw new IllegalArgumentException("Each row must contain exactly 3 characters.");
            }
            for (int j = 0; j < 3; j++) {
                board[i][j] = line.charAt(j);
            }
        }
        return board;
    }

    /**
     * Analyses the board and returns a code that determines the printed message.
     *
     * @param board the 3×3 game board
     * @return one of the constants defined in this class
     */
    private static int analyse(char[][] board) {
        // 1️⃣ Count pieces
        int xCount = 0;
        int oCount = 0;
        for (int i = 0; i < 3; i++) {
            for (int j = 0; j < 3; j++) {
                char cell = board[i][j];
                if (cell == 'X') {
                    xCount++;
                } else if (cell == '0') {
                    oCount++;
                }
            }
        }

        // 2️⃣ Determine winning lines for each player
        int winningLinesX = countWinningLines(board, 'X');
        int winningLinesO = countWinningLines(board, '0');

        // 3️⃣ Apply the same decision logic as the original program
        //    (preserving exact output strings).

        // Draw: board full, equal difference of 1, no winning lines
        if (xCount + oCount == 9 && xCount - oCount == 1 && winningLinesX + winningLinesO == 0) {
            return DRAW;
        }

        // First player ("X") has at least one winning line, and the move count difference is 1
        if (xCount - oCount == 1 && winningLinesX > 0 && winningLinesO == 0) {
            return FIRST_WON;
        }

        // Second player ("0") has at least one winning line, and the move count difference is 0
        if (xCount - oCount == 0 && winningLinesX == 0 && winningLinesO > 0) {
            return SECOND_WON;
        }

        // No winner yet, board not full, X has made one more move than O → next move would be "second"
        if (xCount - oCount == 1 && xCount + oCount < 9 && winningLinesX + winningLinesO == 0) {
            return NEXT_SECOND;
        }

        // No winner yet, board not full, equal moves → next move would be "first"
        if (xCount - oCount == 0 && xCount + oCount < 9 && winningLinesX + winningLinesO == 0) {
            return NEXT_FIRST;
        }

        // Anything that falls through is considered illegal
        return ILLEGAL;
    }

    /**
     * Counts how many rows, columns or diagonals consist exclusively of the given player's mark.
     *
     * @param board the game board
     * @param player the character to look for ('X' or '0')
     * @return number of complete lines formed by the player
     */
    private static int countWinningLines(char[][] board, char player) {
        int lines = 0;

        // rows
        for (int i = 0; i < 3; i++) {
            if (board[i][0] == player && board[i][1] == player && board[i][2] == player) {
                lines++;
            }
        }

        // columns
        for (int j = 0; j < 3; j++) {
            if (board[0][j] == player && board[1][j] == player && board[2][j] == player) {
                lines++;
            }
        }

        // main diagonal
        if (board[0][0] == player && board[1][1] == player && board[2][2] == player) {
            lines++;
        }

        // anti‑diagonal
        if (board[0][2] == player && board[1][1] == player && board[2][0] == player) {
            lines++;
        }

        return lines;
    }

    /** Prints the outcome determined by {@link #analyse(char[][])}. */
    private static void printOutcome(int outcome) {
        switch (outcome) {
            case ILLEGAL -> System.out.println("illegal");
            case DRAW -> System.out.println("draw");
            case FIRST_WON -> System.out.println("the first player won");
            case SECOND_WON -> System.out.println("the second player won");
            case NEXT_SECOND -> System.out.println("second");
            case NEXT_FIRST -> System.out.println("first");
            default -> System.out.println("unknown");
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;

/**
 * Refactored Tic‑Tac‑Toe validator.
 *
 * <p>This program reads a 3×3 board from standard input and reports the game state:
 * <ul>
 *   <li>illegal – the board cannot appear in a real game,
 *   <li>the first player won,
 *   <li>the second player won,
 *   <li>draw,
 *   <li>first – it is the first player's turn,
 *   <li>second – it is the second player's turn.
 * </ul>
 *
 * <p>The implementation is split into small, single‑responsibility methods and
 * uses a {@code GameState} enum to make the control flow explicit.
 */
public class Main {

    /** Symbol used for an empty cell. */
    private static final char EMPTY = '.';

    /** Entry point. */
    public static void main(String[] args) throws IOException {
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in))) {
            char[][] board = readBoard(br);
            GameState state = analyzeGame(board);

            switch (state) {
                case ILLEGAL      -> System.out.println("illegal");
                case FIRST_WON    -> System.out.println("the first player won");
                case SECOND_WON   -> System.out.println("the second player won");
                case DRAW         -> System.out.println("draw");
                case NEXT_FIRST   -> System.out.println("first");
                case NEXT_SECOND  -> System.out.println("second");
            }
        }
    }

    /** Reads exactly three lines of 3 characters each and builds the board. */
    private static char[][] readBoard(BufferedReader br) throws IOException {
        char[][] board = new char[3][3];
        for (int i = 0; i < 3; i++) {
            String line = br.readLine();
            if (line == null) {
                throw new IOException("Unexpected end of input");
            }
            String trimmed = line.trim();
            if (trimmed.length() != 3) {
                throw new IOException("Each line must contain exactly 3 characters");
            }
            board[i] = trimmed.toCharArray();
        }
        return board;
    }

    /** Determines the current logical state of the game. */
    private static GameState analyzeGame(char[][] board) {
        int xCount = countSymbols(board, 'X');
        int oCount = countSymbols(board, 'O');

        boolean xWins = hasWon(board, 'X');
        boolean oWins = hasWon(board, 'O');

        // ----- Illegal board configurations -----
        if (xWins && oWins) {
            return GameState.ILLEGAL;
        }
        if (xCount < oCount || xCount > oCount + 1) { // X and O count differ by more than 1
            return GameState.ILLEGAL;
        }
        // X can only win on his turn (when the counts are equal) and O only on hers (when X>O)
        if ((xCount == oCount && xWins) || (xCount > oCount && oWins)) {
            return GameState.ILLEGAL;
        }

        // ----- Terminal states -----
        if (xWins) {
            return GameState.FIRST_WON;
        }
        if (oWins) {
            return GameState.SECOND_WON;
        }
        if (xCount + oCount == 9) {
            return GameState.DRAW;
        }

        // ----- Next player to move -----
        return xCount > oCount ? GameState.NEXT_SECOND : GameState.NEXT_FIRST;
    }

    /** Counts how many times {@code symbol} appears on the board. */
    private static int countSymbols(char[][] board, char symbol) {
        int cnt = 0;
        for (char[] row : board) {
            for (char cell : row) {
                if (cell == symbol) {
                    cnt++;
                }
            }
        }
        return cnt;
    }

    /** Checks whether {@code player} has a winning line (row, column or diagonal). */
    private static boolean hasWon(char[][] board, char player) {
        // rows
        for (int i = 0; i < 3; i++) {
            if (board[i][0] == player && board[i][1] == player && board[i][2] == player) {
                return true;
            }
        }
        // columns
        for (int i = 0; i < 3; i++) {
            if (board[0][i] == player && board[1][i] == player && board[2][i] == player) {
                return true;
            }
        }
        // diagonals
        if (board[0][0] == player && board[1][1] == player && board[2][2] == player) {
            return true;
        }
        if (board[0][2] == player && board[1][1] == player && board[2][0] == player) {
            return true;
        }
        return false;
    }

    /** Encapsulates all possible outcomes after validation. */
    private enum GameState {
        ILLEGAL,      // board cannot occur in a real game
        FIRST_WON,    // 'X' has a winning line
        SECOND_WON,   // 'O' has a winning line
        DRAW,         // board is full and nobody won
        NEXT_FIRST,   // it is the first player's turn next
        NEXT_SECOND   // it is the second player's turn next
    }
}

import java.io.*;
import java.util.StringTokenizer;

/**
 * Reads a 3×3 Tic‑Tac‑Toe board from standard input, validates it and prints the
 * game status. The program follows a clear separation of concerns, uses
 * expressive names and guards against resource leaks.
 */
public class TicTacToeValidator implements Runnable {

    /* --------------------------------------------------------------------- */
    /* Constants – keep the original semantics (the second player uses '0')   */
    /* --------------------------------------------------------------------- */
    private static final char PLAYER_X = 'X';
    private static final char PLAYER_O = '0';

    private static final String MSG_FIRST_WON = "the first player won";
    private static final String MSG_SECOND_WON = "the second player won";
    private static final String MSG_DRAW = "draw";
    private static final String MSG_FIRST = "first";
    private static final String MSG_SECOND = "second";
    private static final String MSG_ILLEGAL = "illegal";

    /* --------------------------------------------------------------------- */
    /* I/O streams – managed through try‑with‑resources                     */
    /* --------------------------------------------------------------------- */
    private BufferedReader reader;
    private PrintWriter writer;

    /* --------------------------------------------------------------------- */
    /* Entry point                                                          */
    /* --------------------------------------------------------------------- */
    public static void main(String[] args) {
        new Thread(new TicTacToeValidator()).start();
    }

    @Override
    public void run() {
        try {
            process();
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        } finally {
            closeSilently(reader);
            closeSilently(writer);
        }
    }

    /* --------------------------------------------------------------------- */
    /* Core workflow                                                        */
    /* --------------------------------------------------------------------- */
    private void process() throws IOException {
        try (reader = new BufferedReader(new InputStreamReader(System.in));
             writer = new PrintWriter(System.out)) {

            char[][] board = readBoard();
            String result = validate(board);
            writer.println(result);
        }
    }

    /* --------------------------------------------------------------------- */
    /* Input handling – returns a 3×3 char array                             */
    /* --------------------------------------------------------------------- */
    private char[][] readBoard() throws IOException {
        char[][] board = new char[3][3];
        for (int row = 0; row < 3; row++) {
            String line = nextToken();                 // whole line is a token here
            for (int col = 0; col < 3; col++) {
                board[row][col] = line.charAt(col);
            }
        }
        return board;
    }

    /* --------------------------------------------------------------------- */
    /* Validation logic – all checks are expressed as small, pure methods   */
    /* --------------------------------------------------------------------- */
    private String validate(char[][] board) {
        int xCount = count(board, PLAYER_X);
        int oCount = count(board, PLAYER_O);

        if (!legalMoveCount(xCount, oCount)) {
            return MSG_ILLEGAL;
        }

        boolean xWins = hasWon(board, PLAYER_X);
        boolean oWins = hasWon(board, PLAYER_O);

        if (xWins && oWins) {
            return MSG_ILLEGAL;
        }
        if (xWins && xCount == oCount) {
            return MSG_ILLEGAL;
        }
        if (xWins) {
            return MSG_FIRST_WON;
        }
        if (oWins && xCount == oCount + 1) {
            return MSG_ILLEGAL;
        }
        if (oWins) {
            return MSG_SECOND_WON;
        }
        if (isBoardFull(board)) {
            return MSG_DRAW;
        }
        return (xCount == oCount) ? MSG_FIRST : MSG_SECOND;
    }

    private boolean legalMoveCount(int x, int o) {
        return x >= o && x <= o + 1;
    }

    private boolean hasWon(char[][] board, char player) {
        return hasWon(board, player, 1, 0)   // row
            || hasWon(board, player, 0, 1)   // column
            || hasWon(board, player, 1, 1)   // main diagonal
            || hasWon(board, player, 1, -1); // anti‑diagonal
    }

    private boolean hasWon(char[][] board, char player, int di, int dj) {
        for (int i = 0; i < 3; i++) {
            for (int j = 0; j < 3; j++) {
                if (hasWonFrom(board, player, i, j, di, dj)) {
                    return true;
                }
            }
        }
        return false;
    }

    private boolean hasWonFrom(char[][] board, char player, int i0, int j0,
                               int di, int dj) {
        int consecutive = 0;
        int i = i0, j = j0;
        while (inBounds(i, j) && board[i][j] == player) {
            consecutive++;
            i += di;
            j += dj;
        }
        return consecutive == 3;
    }

    private boolean inBounds(int i, int j) {
        return i >= 0 && i < 3 && j >= 0 && j < 3;
    }

    private boolean isBoardFull(char[][] board) {
        return count(board, PLAYER_X) + count(board, PLAYER_O) == 9;
    }

    private int count(char[][] board, char ch) {
        int cnt = 0;
        for (int i = 0; i < 3; i++) {
            for (int j = 0; j < 3; j++) {
                if (board[i][j] == ch) {
                    cnt++;
                }
            }
        }
        return cnt;
    }

    /* --------------------------------------------------------------------- */
    /* Token reading – mimics the original behaviour without exposing state   */
    /* --------------------------------------------------------------------- */
    private String nextToken() throws IOException {
        while (true) {
            String line = reader.readLine();
            if (line == null || !line.isBlank()) {
                return line.trim();
            }
        }
    }

    /* --------------------------------------------------------------------- */
    /* Helper to close AutoCloseable instances silently                     */
    /* --------------------------------------------------------------------- */
    private static void closeSilently(AutoCloseable ac) {
        if (ac != null) {
            try {
                ac.close();
            } catch (Exception ignored) {
            }
        }
    }
}

import java.io.*;
import java.util.*;

public class TicTacToe {

    /** Enum representing the three possible cell values. */
    private enum Cell {
        EMPTY,
        FIRST,   // 'X'
        SECOND   // '0'
    }

    private static final PrintWriter OUT = new PrintWriter(System.out);
    private static final BufferedReader IN = new BufferedReader(new InputStreamReader(System.in));
    private static final int SIZE = 3;

    /** Reads the board from standard input. */
    private static Cell[][] readBoard() throws IOException {
        Cell[][] board = new Cell[SIZE][SIZE];
        for (int i = 0; i < SIZE; i++) {
            String token = nextToken();
            if (token == null || token.length() != SIZE) {
                throw new IllegalArgumentException("Invalid input token length.");
            }
            for (int j = 0; j < SIZE; j++) {
                char c = token.charAt(j);
                board[i][j] = switch (c) {
                    case 'X' -> Cell.FIRST;
                    case '0' -> Cell.SECOND;
                    default -> Cell.EMPTY;
                };
            }
        }
        return board;
    }

    /** Reads the next non‑empty whitespace‑separated token from stdin. */
    private static String nextToken() throws IOException {
        String line;
        while ((line = IN.readLine()) == null || line.isBlank()) {
            // skip empty lines
        }
        StringTokenizer st = new StringTokenizer(line);
        return st.hasMoreTokens() ? st.nextToken() : null;
    }

    /** Simple holder for the counts of each player's pieces. */
    private static final class Count {
        final int first;
        final int second;
        Count(int first, int second) { this.first = first; this.second = second; }
    }

    /** Returns how many cells belong to each player. */
    private static Count countPieces(Cell[][] board) {
        int first = 0, second = 0;
        for (Cell[] row : board) {
            for (Cell cell : row) {
                if (cell == Cell.FIRST) first++;
                else if (cell == Cell.SECOND) second++;
            }
        }
        return new Count(first, second);
    }

    /** Determines whether the given player has a winning line. */
    private static boolean hasWon(Cell[][] board, Cell player) {
        // rows
        for (int i = 0; i < SIZE; i++) {
            if (Arrays.stream(board[i]).allMatch(c -> c == player)) {
                return true;
            }
        }
        // columns
        for (int j = 0; j < SIZE; j++) {
            if (board[0][j] == player && board[1][j] == player && board[2][j] == player) {
                return true;
            }
        }
        // diagonals
        if (board[0][0] == player && board[1][1] == player && board[2][2] == player) return true;
        if (board[0][2] == player && board[1][1] == player && board[2][0] == player) return true;
        return false;
    }

    /** Validates the board according to the rules of Tic‑Tac‑Toe. */
    private static boolean isLegal(Cell[][] board) {
        Count cnt = countPieces(board);
        boolean firstWon = hasWon(board, Cell.FIRST);
        boolean secondWon = hasWon(board, Cell.SECOND);

        // Both players cannot win at the same time.
        if (firstWon && secondWon) {
            return false;
        }

        int diff = cnt.first - cnt.second; // must be -1, 0 or 1
        if (diff < -1 || diff > 1) {
            return false;
        }

        // If the first player won, they must have made one more move than the second.
        if (firstWon && diff != 1) {
            return false;
        }

        // If the second player won, the move counts must be equal.
        if (secondWon && diff != 0) {
            return false;
        }

        return true;
    }

    /** Core logic: determines the result and prints it. */
    public static void solve() throws IOException {
        Cell[][] board = readBoard();

        if (!isLegal(board)) {
            OUT.println("illegal");
            return;
        }

        boolean firstWon = hasWon(board, Cell.FIRST);
        boolean secondWon = hasWon(board, Cell.SECOND);

        if (firstWon) {
            OUT.println("the first player won");
        } else if (secondWon) {
            OUT.println("the second player won");
        } else {
            int totalMoves = SIZE * SIZE;
            Count cnt = countPieces(board);
            if (cnt.first + cnt.second == totalMoves) {
                OUT.println("draw");
            } else {
                // The player with fewer pieces moves next.
                OUT.println(cnt.first <= cnt.second ? "first" : "second");
            }
        }
    }

    public static void main(String[] args) throws Exception {
        solve();
        OUT.close();
    }
}

import java.util.Scanner;

/**
 * Represents the result of a Tic‑Tac‑Toe game.
 * The logic is split into small, purpose‑focused methods.
 */
public class Judge {

    /** Scanner used to read the three rows of the board. */
    private static final Scanner SCANNER = new Scanner(System.in);

    /** Enum making the board state self‑documenting. */
    enum Cell {
        EMPTY,   // '.' – empty cell
        FIRST,   // 'X' – first player
        SECOND   // 'O' – second player
    }

    public static void main(String[] args) {
        Cell[][] board = readBoard();
        if (board == null) {
            return; // readBoard already printed an error message
        }

        int xCount = countOccurrences(board, Cell.FIRST);
        int oCount = countOccurrences(board, Cell.SECOND);
        int emptyCount = countOccurrences(board, Cell.EMPTY);

        if (isIllegalState(xCount, oCount)) {
            System.out.println("illegal");
            return;
        }

        boolean firstWon = hasWon(board, Cell.FIRST);
        boolean secondWon = hasWon(board, Cell.SECOND);

        if (firstWon && secondWon) {
            System.out.println("illegal");
        } else if (firstWon) {
            System.out.println("the first player won");
        } else if (secondWon) {
            System.out.println("the second player won");
        } else if (emptyCount == 0) {
            System.out.println("draw");
        } else {
            System.out.println(xCount > oCount ? "second" : "first");
        }
    }

    /** Reads three rows of three characters each and builds a Cell board. */
    private static Cell[][] readBoard() {
        Cell[][] board = new Cell[3][3];
        for (int i = 0; i < 3; i++) {
            String row = SCANNER.next();
            if (row.length() != 3) {
                System.out.println("illegal");
                SCANNER.close();
                return null;
            }
            for (int j = 0; j < 3; j++) {
                char ch = row.charAt(j);
                Cell cell;
                switch (ch) {
                    case '.' -> cell = Cell.EMPTY;
                    case 'X' -> cell = Cell.FIRST;
                    case 'O' -> cell = Cell.SECOND;
                    default -> {
                        System.out.println("illegal");
                        SCANNER.close();
                        return null;
                    }
                }
                board[i][j] = cell;
            }
        }
        SCANNER.close();
        return board;
    }

    /** Counts how many times a given player appears on the board. */
    private static int countOccurrences(Cell[][] board, Cell player) {
        int count = 0;
        for (Cell[] row : board) {
            for (Cell cell : row) {
                if (cell == player) count++;
            }
        }
        return count;
    }

    /** Returns true if the move counts violate the rules of Tic‑Tac‑Toe. */
    private static boolean isIllegalState(int xCount, int oCount) {
        return xCount > oCount + 1 || oCount > xCount;
    }

    /** Checks whether the supplied player has a winning line. */
    private static boolean hasWon(Cell[][] board, Cell player) {
        // rows
        for (int i = 0; i < 3; i++) {
            if (board[i][0] == player && board[i][1] == player && board[i][2] == player) {
                return true;
            }
            if (board[0][i] == player && board[1][i] == player && board[2][i] == player) {
                return true;
            }
        }
        // diagonals
        if (board[0][0] == player && board[1][1] == player && board[2][2] == player) {
            return true;
        }
        if (board[0][2] == player && board[1][1] == player && board[2][0] == player) {
            return true;
        }
        return false;
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.Optional;

/**
 * Refactored Tic‑Tac‑Toe validator.
 *
 * <p>
 *   The program reads a 3×3 board from standard input, counts the marks,
 *   detects a winner (if any) and prints one of the following messages:
 *   <ul>
 *     <li>"illegal" – the board configuration cannot appear during a real game</li>
 *     <li>"the first player won"</li>
 *     <li>"the second player won"</li>
 *     <li>"draw"</li>
 *     <li>"first"</li>   – first player has the next move
 *     <li>"second"</li>  – second player has the next move
 *   </ul>
 * </p>
 */
public class TicTacToe {

    /** size of the board (3×3) */
    private static final int SIZE = 3;

    public static void main(String[] args) throws IOException {
        /* -------------------------------------------------------------
         *  Input handling
         * ------------------------------------------------------------- */
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in))) {
            char[][] board = readBoard(br);
            int xCount = countMarks(board, 'X');   // number of 'X'
            int oCount = countMarks(board, '0');   // '0' represents 'O' in the original spec
            Optional<Character> winner = determineWinner(board);

            /* -------------------------------------------------------------
             *  Evaluation & output
             * ------------------------------------------------------------- */
            System.out.println(evaluateGame(xCount, oCount, winner));
        }
    }

    /** Reads exactly 3 lines of 3 characters each and builds the board. */
    private static char[][] readBoard(BufferedReader br) throws IOException {
        char[][] board = new char[SIZE][SIZE];
        for (int i = 0; i < SIZE; i++) {
            String line = br.readLine().trim();
            if (line == null || line.length() != SIZE) {
                throw new IllegalArgumentException("Invalid input format");
            }
            for (int j = 0; j < SIZE; j++) {
                board[i][j] = line.charAt(j);
            }
        }
        return board;
    }

    /** Counts how many times {@code mark} appears on the board. */
    private static int countMarks(char[][] board, char mark) {
        int count = 0;
        for (char[] row : board) {
            for (char cell : row) {
                if (cell == mark) {
                    count++;
                }
            }
        }
        return count;
    }

    /**
     * Determines whether there is a winning line.
     *
     * @return an {@link Optional} containing the winning character ('X' or '0')
     *         or empty if there is no winner.
     */
    private static Optional<Character> determineWinner(char[][] board) {
        Character winner = null;

        // rows
        for (int i = 0; i < SIZE && winner == null; i++) {
            if (isWinningLine(board, i, 0, 0, 1)) {
                winner = board[i][0];
            }
        }

        // columns
        if (winner == null) {
            for (int i = 0; i < SIZE && winner == null; i++) {
                if (isWinningLine(board, 0, i, 1, 0)) {
                    winner = board[0][i];
                }
            }
        }

        // diagonals
        if (winner == null) {
            if (isWinningLine(board, 0, 0, 1, 1)) {
                winner = board[0][0];
            } else if (isWinningLine(board, 0, SIZE - 1, 1, -1)) {
                winner = board[0][SIZE - 1];
            }
        }

        return winner == null ? Optional.empty() : Optional.of(winner);
    }

    /**
     * Checks whether the three cells starting at {@code startRow,startCol}
     * with the given step increments form a winning line for the same player.
     */
    private static boolean isWinningLine(
            char[][] board,
            int startRow,
            int startCol,
            int rowStep,
            int colStep) {

        char first = board[startRow][startCol];
        return first != '\0'               // empty cell cannot win
                && (first == 'X' || first == '0')   // only player marks can win
                && first == board[startRow + rowStep][startCol + colStep]
                && first == board[startRow + 2 * rowStep][startCol + 2 * colStep];
    }

    /**
     * Evaluates the whole game state and returns the appropriate output string.
     */
    private static String evaluateGame(int xCount, int oCount, Optional<Character> winner) {
        // ---------- illegal board configurations ----------
        if (xCount > oCount + 1 || oCount > xCount) {
            return "illegal";
        }
        if (winner.isPresent()) {
            char w = winner.get();
            if (w == 'X' && xCount != oCount + 1) {
                return "illegal";
            }
            if (w == '0' && xCount != oCount) {
                return "illegal";
            }
        }

        // ---------- game outcomes ----------
        if (winner.isPresent()) {
            return winner.get() == 'X' ? "the first player won" : "the second player won";
        }
        if (xCount + oCount == SIZE * SIZE) {
            return "draw";
        }

        // ---------- next player to move ----------
        return (xCount == oCount) ? "first" : "second";
    }
}

import java.util.*;

public class Main {

    private static final char EMPTY = '.';

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        char[][] board = readBoard(scanner);
        Result result = evaluate(board);
        System.out.println(result.message);
    }

    private static char[][] readBoard(Scanner scanner) {
        char[][] board = new char[3][3];
        for (int i = 0; i < 3; i++) {
            String line = scanner.next();
            for (int j = 0; j < 3; j++) {
                board[i][j] = line.charAt(j);
            }
        }
        return board;
    }

    private static Result evaluate(char[][] board) {
        int zeroCount = count(board, '0');
        int xCount = count(board, 'X');

        // Rule 1 – move counts must be consistent
        if (!validCounts(zeroCount, xCount)) {
            return new Result("illegal");
        }

        char winner = determineWinner(board);

        // Both players cannot have winning lines
        if (winner == '2') {
            return new Result("illegal");
        }

        // No winner yet
        if (winner == EMPTY) {
            if (isBoardFull(board)) {
                return new Result("draw");
            } else {
                // indicate whose turn it is
                return new Result(zeroCount == xCount ? "first" : "second");
            }
        }

        // Winner is either X or 0
        if (winner == 'X') {
            if (xCount == zeroCount + 1) {
                return new Result("the first player won");
            }
            return new Result("illegal");
        }

        // winner == '0'
        if (winner == '0') {
            if (xCount == zeroCount) {
                return new Result("the second player won");
            }
            return new Result("illegal");
        }

        // unreachable
        return new Result("illegal");
    }

    private static boolean validCounts(int zeros, int xes) {
        return xes == zeros || xes == zeros + 1;
    }

    private static int count(char[][] board, char c) {
        int cnt = 0;
        for (char[] row : board) {
            for (char cell : row) {
                if (cell == c) cnt++;
            }
        }
        return cnt;
    }

    private static boolean isBoardFull(char[][] board) {
        for (char[] row : board) {
            for (char cell : row) {
                if (cell == EMPTY) {
                    return false;
                }
            }
        }
        return true;
    }

    private static char determineWinner(char[][] board) {
        StringBuilder lines = new StringBuilder();

        // rows
        for (int i = 0; i < 3; i++) {
            if (board[i][0] != EMPTY && board[i][0] == board[i][1] && board[i][1] == board[i][2]) {
                lines.append(board[i][0]);
            }
        }
        // columns
        for (int i = 0; i < 3; i++) {
            if (board[0][i] != EMPTY && board[0][i] == board[1][i] && board[1][i] == board[2][i]) {
                lines.append(board[0][i]);
            }
        }
        // diagonals
        if (board[0][0] != EMPTY && board[0][0] == board[1][1] && board[1][1] == board[2][2]) {
            lines.append(board[0][0]);
        }
        if (board[1][1] != EMPTY && board[1][1] == board[2][0] && board[2][0] == board[0][2]) {
            lines.append(board[1][1]);
        }

        if (lines.length() == 0) {
            return EMPTY;
        }
        if (lines.length() == 1) {
            return lines.charAt(0);
        }
        // More than one distinct symbol in lines means both players have winning lines
        return '2';
    }

    // -------------------------------------------------------------------------
    // Simple holder for the textual result
    // -------------------------------------------------------------------------
    private static final class Result {
        final String message;
        Result(String message) { this.message = message; }
    }
}

import java.util.Scanner;

/**
 * Simple Tic‑Tac‑Toe validator.
 *
 * Reads a 3×3 board where cells are entered as three strings of three characters each.
 * Outputs:
 *   • "the first player won" / "the second player won"
 *   • "draw"
 *   • "first" / "second"   – whose turn it is next (only reached when the game is not over)
 *   • "illegal"            – when the board state cannot happen in a real game
 */
public class TicTacToe {

    private static final int SIZE = 3;                     // board dimension (3×3)

    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            char[][] board = readBoard(scanner);
            analyseAndPrintResult(board);
        }
    }

    /** Reads exactly three lines, each containing three characters, and builds the board. */
    private static char[][] readBoard(Scanner scanner) {
        char[][] board = new char[SIZE][SIZE];

        for (int row = 0; row < SIZE; row++) {
            String line = scanner.next().trim();
            // Guard against malformed input – required for a robust solution.
            if (line.length() != SIZE) {
                throw new IllegalArgumentException(
                    "Each line must contain exactly " + SIZE + " characters");
            }
            for (int col = 0; col < SIZE; col++) {
                board[row][col] = line.charAt(col);
            }
        }
        return board;
    }

    /**
     * Main driver that validates the board and prints the appropriate message.
     */
    private static void analyseAndPrintResult(char[][] board) {
        int xCount = countOccurrences(board, 'X');
        int oCount = countOccurrences(board, '0');

        // 1️⃣  Illegal board states -------------------------------------------------
        if (!isLegal(board, xCount, oCount)) {
            System.out.println("illegal");
            return;
        }

        // 2️⃣  Victory checks ---------------------------------------------------------
        boolean firstWon  = hasWon(board, 'X');
        boolean secondWon = hasWon(board, '0');

        if (firstWon && secondWon) {                 // both cannot win simultaneously
            System.out.println("illegal");
            return;
        }

        if (firstWon) {
            System.out.println("the first player won");
            return;
        }
        if (secondWon) {
            System.out.println("the second player won");
            return;
        }

        // 3️⃣  End of game (board full) -----------------------------------------------
        if (isFullBoard(board)) {
            System.out.println("draw");
            return;
        }

        // 4️⃣  Next player ------------------------------------------------------------
        System.out.println(xCount == oCount ? "first" : "second");
    }

    /** Counts how many cells contain the given symbol. */
    private static int countOccurrences(char[][] board, char symbol) {
        int cnt = 0;
        for (int i = 0; i < SIZE; i++) {
            for (int j = 0; j < SIZE; j++) {
                if (board[i][j] == symbol) {
                    cnt++;
                }
            }
        }
        return cnt;
    }

    /** True when the board is completely filled (no empty cells). */
    private static boolean isFullBoard(char[][] board) {
        return countOccurrences(board, 'X') + countOccurrences(board, '0') == SIZE * SIZE;
    }

    /**
     * Verifies whether the supplied board configuration obeys the game rules:
     * <ul>
     *   <li>Number of X's must be either equal to O's or one more.</li>
     *   <li>Both players cannot be winning at the same time.</li>
     *   <li>If O has won, X count must equal O count; if X has won, X count must be O+1.</li>
     * </ul>
     */
    private static boolean isLegal(char[][] board, int xCount, int oCount) {
        boolean firstWon  = hasWon(board, 'X');
        boolean secondWon = hasWon(board, '0');

        // Basic count rule
        if (!(xCount == oCount || xCount == oCount + 1)) {
            return false;
        }

        // Cannot have both winners
        if (firstWon && secondWon) {
            return false;
        }

        // Winning conditions impose extra restrictions
        if (firstWon && xCount != oCount + 1) {
            return false;
        }
        if (secondWon && xCount != oCount) {
            return false;
        }

        return true;
    }

   /**
     * Checks whether the given player has a complete row, column or diagonal.
     */
    private static boolean hasWon(char[][] board, char player) {
        // rows and columns
        for (int i = 0; i < SIZE; i++) {
            if (allEqual(board[i][0], board[i][1], board[i][2], player)) {
                return true;
            }
            if (allEqual(board[0][i], board[1][i], board[2][i], player)) {
                return true;
            }
        }
        // diagonals
        return allEqual(board[0][0], board[1][1], board[2][2], player)
            || allEqual(board[0][2], board[1][1], board[2][0], player);
    }

    /** Helper that returns true only if all three cells equal the given player symbol. */
    private static boolean allEqual(char a, char b, char c, char player) {
        return a == player && b == player && c == player;
    }
}

import java.util.Scanner;

/**
 * Utility that validates a Tic‑Tac‑Toe board entered by the user
 * and reports the game state.
 *
 * <p>All logic has been split into small, focused methods, uses
 * meaningful names and constants, and avoids mutable static state.
 * The behaviour is identical to the original program.</p>
 */
public class TicTacToeValidator {

    /** Symbol used for player X */
    private static final char PLAYER_X = 'X';

    /** Symbol used for player O (the original code uses the digit '0') */
    private static final char PLAYER_O = '0';

    /** Symbol used for an empty cell */
    private static final char EMPTY = '.';

    /** Entry point */
    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            // read the 3×3 board – each call reads the next whitespace‑separated token
            String[] board = new String[3];
            for (int row = 0; row < 3; ++row) {
                board[row] = scanner.next();
            }

            Result result = analyse(board);
            System.out.println(result.message);
        }
    }

    /** Holds the analysis outcome and the message that must be printed. */
    private static final class Result {
        final String message;
        Result(String message) {
            this.message = message;
        }
    }

    /** Main dispatcher – returns the appropriate textual result. */
    private static Result analyse(String[] board) {
        CountInfo counts = countSymbols(board);

        if (!validSymbolCounts(counts)) {
            return new Result("illegal");
        }

        if (bothWin(board)) {
            return new Result("illegal");
        }

        if (hasWin(board, PLAYER_X)) {
            if (counts.x != counts.o + 1) {
                return new Result("illegal");
            }
            return new Result("the first player won");
        }

        if (hasWin(board, PLAYER_O)) {
            if (counts.o + 1 != counts.x) {
                return new Result("illegal");
            }
            return new Result("the second player won");
        }

        if (counts.empty == 0) {
            return new Result("draw");
        }

        // Game is still in progress – whose turn is it?
        return new Result(counts.x > counts.o ? "first" : "second");
    }

    /** Checks that the numbers of X and O satisfy the rules of Tic‑Tac‑Toe. */
    private static boolean validSymbolCounts(CountInfo c) {
        // X can be equal to O or exactly one more than O
        return !(c.x > c.o + 1 || c.o > c.x);
    }

    /** Determines whether both players have winning lines simultaneously. */
    private static boolean bothWin(String[] board) {
        return hasWin(board, PLAYER_X) && hasWin(board, PLAYER_O);
    }

    /** Returns true if the given player has any winning line. */
    private static boolean hasWin(String[] board, char player) {
        // rows
        for (int row = 0; row < 3; ++row) {
            if (allEqual(board[row], player)) {
                return true;
            }
        }
        // columns
        for (int col = 0; col < 3; ++col) {
            if (board[0].charAt(col) == player &&
                board[1].charAt(col) == player &&
                board[2].charAt(col) == player) {
                return true;
            }
        }
        // diagonals
        if (board[0].charAt(0) == player && board[1].charAt(1) == player && board[2].charAt(2) == player) {
            return true;
        }
        if (board[0].charAt(2) == player && board[1].charAt(1) == player && board[2].charAt(0) == player) {
            return true;
        }
        return false;
    }

    /** Utility – true if every character in the supplied string equals `ch`. */
    private static boolean allEqual(String s, char ch) {
        return s.charAt(0) == ch && s.charAt(1) == ch && s.charAt(2) == ch;
    }

    /** Counts how many X, O and empty cells are on the board. */
    private static CountInfo countSymbols(String[] board) {
        int xCount = 0, oCount = 0, emptyCount = 0;

        for (String row : board) {
            for (int col = 0; col < 3; ++col) {
                char cell = row.charAt(col);
                if (cell == PLAYER_X) {
                    ++xCount;
                } else if (cell == PLAYER_O) {
                    ++oCount;
                } else {
                    ++emptyCount;   // treats any non‑X/O character as empty
                }
            }
        }
        return new CountInfo(xCount, oCount, emptyCount);
    }

    /** Simple immutable holder for the three counters. */
    private static final class CountInfo {
        final int x;
        final int o;
        final int empty;

        CountInfo(int x, int o, int empty) {
            this.x = x;
            this.o = o;
            this.empty = empty;
        }
    }
}

