/**
 * Encapsulates all game‑specific logic:
 *   • reading the board,
 *   • counting pieces,
 *   • validating legality,
 *   • determining the outcome.
 */
final class GameValidator {

    /** Empty cell placeholder used when parsing input. */
    private static final char EMPTY = '-';

    /** Player symbols. */
    private static final char PLAYER_X = 'X';
    private static final char PLAYER_O = 'O';

    /** 3×3 board representation. */
    private final char[][] board = new char[3][3];

    /** Number of X's and O's on the board. */
    private int countX;
    private int countO;

    /** Entry point for the validator – reads input, validates and prints the result. */
    public void validateAndPrintResult() throws IOException {
        readBoard();
        countPieces();
        evaluate();
    }

    /** Reads a 3×3 board from stdin. Tokens are whitespace‑separated and must be exactly three characters long. */
    private void readBoard() throws IOException {
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer tokeniser = new StringTokenizer(reader.readLine());

        for (int row = 0; row < 3; row++) {
            String token = tokeniser.nextToken();
            if (token == null || token.length() != 3) {
                throw new IOException("Invalid board format – expected three 3‑character tokens per row");
            }
            for (int col = 0; col < 3; col++) {
                board[row][col] = normalizeCell(token.charAt(col));
            }
        }
    }

    /** Validates a single cell character – only 'X', 'O' or '-' are accepted. */
    private static char normalizeCell(char c) {
        if (c == PLAYER_X || c == PLAYER_O || c == EMPTY) {
            return c;
        }
        throw new IOException("Invalid character '" + c + "' found in board");
    }

    /** Counts how many X's and O's are present on the board. */
    private void countPieces() {
        countX = 0;
        countO = 0;
        for (char[] row : board) {
            for (char cell : row) {
                if (cell == PLAYER_X) {
                    countX++;
                } else if (cell == PLAYER_O) {
                    countO++;
                }
            }
        }
    }

    /** Checks whether the given player has a complete winning line (row, column or diagonal). */
    private boolean hasWin(char player) {
        // rows
        for (int i = 0; i < 3; i++) {
            if (board[i][0] == player && board[i][1] == player && board[i][2] == player) {
                return true;
            }
        }
        // columns
        for (int j = 0; j < 3; j++) {
            if (board[0][j] == player && board[1][j] == player && board[2][j] == player) {
                return true;
            }
        }
        // diagonals
        if (board[0][0] == player && board[1][1] == player && board[2][2] == player) {
            return true;
        }
        if (board[0][2] == player && board[1][1] == player && board[2][0] == player) {
            return true;
        }
        return false;
    }

    /** Core validation logic followed by output generation. */
    private void evaluate() {
        boolean xWon = hasWin(PLAYER_X);
        boolean oWon = hasWin(PLAYER_O);

        // ---- Illegal board states -------------------------------------------------
        // X must not be fewer than O and the difference may not exceed 1.
        if ((countX < countO) || (countX - countO > 1) || (xWon && oWon)) {
            System.out.println("illegal");
            return;
        }

        // ---- Victory ---------------------------------------------------------------
        if (xWon) {
            System.out.println("the first player won");
            return;
        }
        if (oWon) {
            System.out.println("the second player won");
            return;
        }

        // ---- Draw or next move ------------------------------------------------------
        if (countX + countO == 9) {
            System.out.println("draw");
        } else if (countX > countO) {
            System.out.println("first");
        } else {
            System.out.println("second");
        }
    }
}

import java.util.Scanner;

/**
 * Simple Tic‑Tac‑Toe validator / game‑state printer.
 *
 * <p>
 * The program reads a 3×3 board from the console where each cell contains
 * either 'X', '0' (zero) or '.' (empty).  It validates the board (illegal
 * configurations are rejected), determines whether somebody has won,
 * and prints the appropriate message.
 * </p>
 *
 * <ul>
 *   <li>Clear naming and small helper methods improve readability.</li>
 *   <li>All magic numbers are expressed as constants.</li>
 *   <li>Input handling uses a try‑with‑resources statement.</li>
 *   <li>The logic is split into small, single‑purpose methods.</li>
 * </ul>
 */
public class C003 {

    /** Board size – always 3 for classic Tic‑Tac‑Toe. */
    private static final int SIZE = 3;

    /** Character representing an empty cell (not used directly but clarifies intent). */
    private static final char EMPTY = '.';

    /** Player symbols. */
    private static final char PLAYER_X = 'X';
    private static final char PLAYER_O = '0';

    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            char[][] board = readBoard(scanner);
            evaluateAndPrint(board);
        }
    }

    /**
     * Reads exactly three lines from {@code scanner}, each containing three
     * characters, and stores them into a {@code SIZE × SIZE} board.
     *
     * @param scanner a scanner that supplies the three board rows
     * @return a 3×3 character matrix representing the board
     * @throws IllegalStateException if fewer than three lines are provided
     */
    private static char[][] readBoard(Scanner scanner) {
        char[][] board = new char[SIZE][SIZE];
        for (int row = 0; row < SIZE; row++) {
            String line = scanner.nextLine();
            if (line == null || line.length() < SIZE) {
                throw new IllegalStateException("Incomplete board input");
            }
            for (int col = 0; col < SIZE; col++) {
                board[row][col] = line.charAt(col);
            }
        }
        return board;
    }

    /**
     * Counts how many X and O marks are present on the board.
     *
     * @param board the game board
     * @return an {@code int[2]} where {@code [0]} = X count, {@code [1]} = O count
     */
    private static int[] countMarks(char[][] board) {
        int x = 0, o = 0;
        for (int row = 0; row < SIZE; row++) {
            for (int col = 0; col < SIZE; col++) {
                char cell = board[row][col];
                if (cell == PLAYER_X) {
                    x++;
                } else if (cell == PLAYER_O) {
                    o++;
                }
            }
        }
        return new int[]{x, o};
    }

    /**
     * Determines whether the given player has a winning line.
     *
     * @param player the symbol to check ('X' or '0')
     * @param board the board
     * @return {@code true} if the player has any row, column or diagonal fully filled with {@code player}
     */
    private static boolean hasWon(char player, char[][] board) {
        // Check rows and columns
        for (int i = 0; i < SIZE; i++) {
            if (allEqual(board, player, i, 0, 0, 1)   // row i
                    || allEqual(board, player, 0, i, 1, 0)) { // column i
                return true;
            }
        }
        // Diagonals
        if (allEqual(board, player, 0, 0, 1, 1) || allEqual(board, player, 0, SIZE - 1, 1, -1)) {
            return true;
        }
        return false;
    }

    /**
     * Helper that checks whether a sequence of cells starting at (startRow, startCol)
     * with the given direction equals {@code player}.  Only used internally by
     * {@link #hasWon(char, char[][])}.
     */
    private static boolean allEqual(char[][] board, char player, int row, int col, int rowStep, int colStep) {
        for (int i = 0; i < SIZE; i++) {
            if (board[row][col] != player) {
                return false;
            }
            row += rowStep;
            col += colStep;
        }
        return true;
    }

    /**
     * Validates the board configuration.
     *
     * <p>An illegal board satisfies any of the following:</p>
     * <ul>
     *   <li>Number of O's exceeds number of X's.</li>
     *   <li>Number of X's exceeds 5 or number of O's exceeds 4.</li>
     *   <li>The difference between X and O counts is larger than 1.</li>
     *   <li>Both players have winning lines.</li>
     * </ul>
     *
     * @param board the board to validate
     * @return {@code true} if the board is illegal, {@code false} otherwise
     */
    private static boolean isIllegal(char[][] board) {
        int[] counts = countMarks(board);
        int x = counts[0];
        int o = counts[1];

        if (o > x || x > SIZE * SIZE - 1 || o > SIZE * SIZE - 2 || Math.abs(x - o) > 1) {
            return true;
        }

        boolean xWon = hasWon(PLAYER_X, board);
        boolean oWon = hasWon(PLAYER_O, board);

        if (xWon && oWon) {
            return true;
        }

        // Additional consistency checks implied by the original code:
        if (xWon && (x != o + 1)) {
            return true;
        }
        if (oWon && (x != o)) {
            return true;
        }

        return false;
    }

    /**
     * Evaluates the board, prints the appropriate message and terminates.
     *
     * @param board the game board
     */
    private static void evaluateAndPrint(char[][] board) {
        if (isIllegal(board)) {
            System.out.println("illegal");
            return;
        }

        boolean xWon = hasWon(PLAYER_X, board);
        boolean oWon = hasWon(PLAYER_O, board);
        int[] counts = countMarks(board);
        int x = counts[0];
        int o = counts[1];

        if (xWon) {
            System.out.println(x == o + 1 ? "the first player won" : "illegal");
        } else if (oWon) {
            System.out.println(x == o ? "the second player won" : "illegal");
        } else if (x + o == SIZE * SIZE) {      // board is full → draw
            System.out.println("draw");
        } else if (x == o) {                     // next turn is first player
            System.out.println("first");
        } else {                                 // next turn is second player
            System.out.println("second");
        }
    }
}

import java.io.*;
import java.util.StringTokenizer;

/**
 * Main class that reads a 3×3 tic‑tac‑toe board, validates the position and
 * prints the appropriate message:
 * <ul>
 *   <li>illegal – the board cannot appear during a real game</li>
 *   <li>the first player won</li>
 *   <li>the second player won</li>
 *   <li>draw</li>
 *   <li>first – it is the first player's turn</li>
 *   <li>second – it is the second player's turn</li>
 * </ul>
 *
 * The implementation is deliberately split into small, single‑purpose
 * methods to improve readability and maintainability.
 */
public class Main {

    /* --------------------------------------------------------------------- */
    /*                     Constant definitions                               */
    /* --------------------------------------------------------------------- */
    private static final char CROSS = 'X';   // first player
    private static final char ZERO  = 'O';   // second player
    private static final char EMPTY = '.';   // empty cell

    /* --------------------------------------------------------------------- */
    /*                           I/O helpers                                   */
    /* --------------------------------------------------------------------- */
    /**
     * Fast scanner that works with a {@link Reader}.  It tokenises whole
     * lines – exactly what the original program expected.
     */
    private static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner(Reader reader) {
            this.br = new BufferedReader(reader);
        }

        /** Returns the next available token, or {@code null} on EOF. */
        String nextToken() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                String line = br.readLine();
                if (line == null) {
                    return null;
                }
                st = new StringTokenizer(line);
            }
            return st.nextToken();
        }

        /** Convenience methods used by the original code. */
        int nextInt() throws IOException               { return Integer.parseInt(nextToken()); }
        long nextLong() throws IOException             { return Long.parseLong(nextToken()); }
        double nextDouble() throws IOException         { return Double.parseDouble(nextToken()); }

        /** Reads an entire line and returns it as a {@code String}. */
        String readLine() throws IOException {
            return br.readLine();
        }
    }

    /** PrintWriter wrapper that can be constructed from any {@link OutputStream}. */
    private static PrintWriter newPrintWriter(OutputStream out) {
        return new PrintWriter(out, true);
    }

    /* --------------------------------------------------------------------- */
    /*                       Game‑logic utilities                               */
    /* --------------------------------------------------------------------- */
    /** Checks whether two 3×3 boards are equal. */
    private static boolean equal(char[][] a, char[][] b) {
        for (int i = 0; i < 3; i++) {
            for (int j = 0; j < 3; j++) {
                if (a[i][j] != b[i][j]) {
                    return false;
                }
            }
        }
        return true;
    }

    /** Returns {@code true} if the given player has a winning row/column/diagonal. */
    private static boolean winner(char[][] board, char player) {
        // rows & columns
        for (int i = 0; i < 3; i++) {
            if (board[i][0] == player && board[i][1] == player && board[i][2] == player) {
                return true;
            }
            if (board[0][i] == player && board[1][i] == player && board[2][i] == player) {
                return true;
            }
        }
        // diagonals
        return (board[0][0] == player && board[1][1] == player && board[2][2] == player) ||
               (board[0][2] == player && board[1][1] == player && board[2][0] == player);
    }

    /** Counts the occurrences of a given character in the board. */
    private static int count(char[][] board, char c) {
        int cnt = 0;
        for (char[] row : board) {
            for (char cell : row) {
                if (cell == c) {
                    cnt++;
                }
            }
        }
        return cnt;
    }

    /* --------------------------------------------------------------------- */
    /*                         Core problem solving                             */
    /* --------------------------------------------------------------------- */
    /**
     * Evaluates the supplied board and writes the appropriate answer to
     * {@code out}.  The method follows the exact semantics of the original
     * program but is written with clear, self‑documenting helpers.
     */
    private static void solve(FastScanner in, PrintWriter out) throws IOException {
        /* ---------- 1. read the board ----------------------------------- */
        char[][] board = new char[3][];
        for (int i = 0; i < 3; i++) {
            String line = in.nextToken();
            if (line == null) {
                throw new IOException("Unexpected end of input");
            }
            board[i] = line.toCharArray();
        }

        /* ---------- 2. basic validation --------------------------------- */
        int xCnt = count(board, CROSS);
        int oCnt = count(board, ZERO);

        // In a legal game the numbers of X and O satisfy one of two relations.
        if (! (xCnt == oCnt || xCnt == oCnt + 1)) {
            out.println("illegal");
            return;
        }

        // Both players cannot have winning lines simultaneously.
        boolean xWins = winner(board, CROSS);
        boolean oWins = winner(board, ZERO);
        if (xWins && oWins) {
            out.println("illegal");
            return;
        }

        // The winner must have played the last move.
        if (xWins && xCnt != oCnt + 1) {
            out.println("illegal");
            return;
        }
        if (oWins && xCnt != oCnt) {
            out.println("illegal");
            return;
        }

        /* ---------- 3. terminal states ----------------------------------- */
        if (xWins) {
            out.println("the first player won");
            return;
        }
        if (oWins) {
            out.println("the second player won");
            return;
        }

        // Check whether the board is full → draw.
        boolean full = true;
        for (char[] row : board) {
            for (char cell : row) {
                if (cell == EMPTY) {
                    full = false;
                    break;
                }
            }
            if (!full) {
                break;
            }
        }
        if (full) {
            out.println("draw");
            return;
        }

        /* ---------- 4. whose turn is it? --------------------------------- */
        out.println(xCnt > oCnt ? "second" : "first");
    }

    /* --------------------------------------------------------------------- */
    /*                               Entry point                               */
    /* --------------------------------------------------------------------- */
    public static void main(String[] args) throws Exception {
        boolean online = System.getProperty("ONLINE_JUDGE") != null;

        // Choose input / output streams based on the execution context.
        InputStream  inStream  = online ? System.in  : new FileInputStream("input.txt");
        OutputStream outStream = online ? System.out : new FileOutputStream("output.txt");

        // try‑with‑resources guarantees proper closure of both streams.
        try (FastScanner scanner = new FastScanner(new InputStreamReader(inStream));
             PrintWriter writer = newPrintWriter(outStream)) {

            solve(scanner, writer);
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Core logic of the Tic‑Tac‑Toe problem solution.
 *
 * <p>This class has been refactored to improve readability, maintainability and
 * separation of concerns.  All magic numbers are replaced with named constants,
 * the board representation is encapsulated, and the search algorithm uses a
 * proper cache instead of a raw array.</p>
 */
public class Main implements Runnable {

    /* ------------------------------------------------------------ *
     *  Constants & Enums                                            *
     * ------------------------------------------------------------ */
    private static final int BOARD_SIZE = 9;          // 3×3 board
    private static final int EMPTY = 0;               // empty cell
    private static final int FIRST = 1;               // first player (X)
    private static final int SECOND = 2;              // second player (0)
    private static final int DRAW = 3;                // draw
    private static final int UNKNOWN = 0;             // game still continues

    /* ------------------------------------------------------------ *
     *  Instance fields                                               *
     * ------------------------------------------------------------ */
    /** Cached evaluation of every reachable board state. */
    private final Map<Integer, Integer> winCache = new HashMap<>();

    /** Current board in internal numeric form (0‑2). */
    private int[] currentBoard;

    /** Player whose turn it is (1 = first, 2 = second). */
    private int currentPlayer;

    /* ------------------------------------------------------------ *
     *  Input / output helpers                                        *
     * ------------------------------------------------------------ */
    private static final class Input {
        private final BufferedReader reader;
        private final BufferedWriter writer;

        Input(InputStream in, OutputStream out) {
            this.reader = new BufferedReader(new InputStreamReader(in));
            this.writer = new BufferedWriter(new OutputStreamWriter(out));
        }

        /** Reads the next non‑whitespace token. */
        String readWord() throws IOException {
            StringBuilder sb = new StringBuilder();
            int c;
            while ((c = reader.read()) >= 0 && c <= ' ');
            if (c < 0) return "";
            while (c > ' ') {
                sb.append((char) c);
                c = reader.read();
            }
            return sb.toString();
        }

        /** Parses the next token as an integer. */
        int readInt() throws IOException {
            return Integer.parseInt(readWord());
        }

        /** Writes text to the underlying output stream. */
        void write(String msg) throws IOException {
            writer.write(msg);
        }

        /** Flushes the writer. */
        void flush() throws IOException {
            writer.flush();
        }
    }

    /* ------------------------------------------------------------ *
     *  Public entry point                                            *
     * ------------------------------------------------------------ */
    @Override
    public void run() {
        try (Input input = new Input(System.in, System.out)) {
            solve(input);
        } catch (Exception e) {
            e.printStackTrace();
            System.exit(1);
        }
    }

    /** Main algorithm entry point – reads board, validates, and prints result. */
    private void solve(Input input) throws IOException {
        initializeGameState();

        // ---- read the 3×3 board description (three lines of 3 chars each) ----
        int[] board = new int[BOARD_SIZE];
        for (int i = 0; i < BOARD_SIZE; i += 3) {
            String line = input.readWord();
            for (int j = 0; j < 3; j++) {
                char ch = line.charAt(j);
                if (ch == 'X') board[i + j] = FIRST;
                else if (ch == '0') board[i + j] = SECOND;
                else board[i + j] = EMPTY;
            }
        }

        int stateCode = encodeBoard(board);
        Integer cachedResult = winCache.get(stateCode);

        if (cachedResult == null) {
            input.write("illegal\n");
            return;
        }

        int evaluation = evaluateBoard(board);
        if (evaluation == FIRST) {
            input.write("the first player won\n");
        } else if (evaluation == SECOND) {
            input.write("the second player won\n");
        } else if (evaluation == DRAW) {
            input.write("draw\n");
        } else {
            // Determine which player made the last move (more moves → that player)
            int firstCount = 0, secondCount = 0;
            for (int v : board) {
                if (v == FIRST) firstCount++;
                else if (v == SECOND) secondCount++;
            }
            input.write(firstCount > secondCount ? "second\n" : "first\n");
        }
    }

    /** Prepares a fresh board and clears the evaluation cache. */
    private void initializeGameState() {
        currentBoard = new int[BOARD_SIZE];
        currentPlayer = FIRST;
        winCache.clear();
        dfs();                     // fill the cache with optimal outcomes
    }

    /** Evaluates a board state: win for first, win for second, draw or unknown. */
    private int evaluateBoard(int[] board) {
        // rows
        for (int row = 0; row < 3; row++) {
            int base = row * 3;
            if (board[base] != EMPTY && board[base] == board[base + 1] && board[base] == board[base + 2]) {
                return board[base];
            }
        }
        // columns
        for (int col = 0; col < 3; col++) {
            if (board[col] != EMPTY && board[col] == board[col + 3] && board[col] == board[col + 6]) {
                return board[col];
            }
        }
        // diagonals
        if (board[0] != EMPTY && board[0] == board[4] && board[0] == board[8]) {
            return board[0];
        }
        if (board[2] != EMPTY && board[2] == board[4] && board[2] == board[6]) {
            return board[2];
        }

        // draw if the board is full, otherwise the game can continue
        for (int cell : board) {
            if (cell == EMPTY) {
                return UNKNOWN;
            }
        }
        return DRAW;
    }

    /** Depth‑first search that fills the winCache with optimal outcomes. */
    private int dfs() {
        int stateCode = encodeBoard(currentBoard);
        if (winCache.containsKey(stateCode)) {
            return winCache.get(stateCode);
        }

        int eval = evaluateBoard(currentBoard);
        if (eval != UNKNOWN) {
            winCache.put(stateCode, eval);
            return eval;
        }

        int bestOutcome = currentPlayer;      // default if no forced win exists
        int opponent = (currentPlayer == FIRST) ? SECOND : FIRST;

        for (int i = 0; i < BOARD_SIZE; i++) {
            if (currentBoard[i] == EMPTY) {
                // make a move
                currentBoard[i] = currentPlayer;
                int nextOutcome = dfs();
                // undo move
                currentBoard[i] = EMPTY;
                currentPlayer = opponent;

                if (nextOutcome == opponent) {
                    // opponent can force a loss → we have a winning move
                    bestOutcome = opponent;
                    break;
                } else if (nextOutcome == DRAW && bestOutcome != opponent) {
                    bestOutcome = DRAW;
                }
            }
        }

        winCache.put(stateCode, bestOutcome);
        return bestOutcome;
    }

    /** Encodes a board as a base‑3 number (unique integer representation). */
    private int encodeBoard(int[] board) {
        int code = 0;
        int factor = 1;
        for (int i = 0; i < BOARD_SIZE; i++) {
            code += factor * board[i];
            factor *= 3;
        }
        return code;
    }

    /** Decodes a base‑3 integer back into a board array (unused in the final logic,
     *  kept for completeness). */
    private int[] decodeBoard(int code, int[] dest) {
        for (int i = 0; i < BOARD_SIZE; i++) {
            dest[i] = code % 3;
            code /= 3;
        }
        return dest;
    }

    /* ------------------------------------------------------------ *
     *  Main method – launches the program on a new thread           *
     * ------------------------------------------------------------ */
    public static void main(String[] args) {
        try {
            Locale.setDefault(Locale.US);
        } catch (Exception ignored) { }
        new Thread(new Main()).start();
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;

public class TicTacToe {

    private static final int SIZE = 3;

    /** Player identifiers – makes the intent of numeric values explicit. */
    private enum Player {
        EMPTY(0), FIRST(1), SECOND(2);
        private final int value;
        Player(int value) { this.value = value; }
        int getValue() { return value; }
    }

    /** The game board – shared across all static methods. */
    private static final int[][] BOARD = new int[SIZE][SIZE];
    /** Number of 'X' (first player) and '0' (second player) marks on the board. */
    private static int countX = 0;
    private static int countO = 0;
    /** Becomes false as soon as an empty cell (anything other than 'X' or '0') is found. */
    private static boolean boardFull = true;

    static {
        for (int i = 0; i < SIZE; i++) {
            for (int j = 0; j < SIZE; j++) {
                BOARD[i][j] = Player.EMPTY.getValue();
            }
        }
    }

    public static void main(String[] args) throws IOException {
        readInput();
        processGame();
    }

    /** Reads three rows from stdin and builds the internal board representation. */
    private static void readInput() throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        for (int i = 0; i < SIZE; i++) {
            String line = br.readLine().trim();
            for (int j = 0; j < SIZE; j++) {
                char c = line.charAt(j);
                if (c == 'X') {
                    BOARD[i][j] = Player.FIRST.getValue();
                    countX++;
                } else if (c == '0') {
                    BOARD[i][j] = Player.SECOND.getValue();
                    countO++;
                } else {
                    BOARD[i][j] = Player.EMPTY.getValue();
                    boardFull = false;
                }
            }
        }
    }

    /** Orchestrates the validation and output phases of the game. */
    private static void processGame() {
        int winner = checkWinner();

        /* -----------------------------------------------------------------
         *  1️⃣  Illegal board states
         * ----------------------------------------------------------------- */
        if (bothPlayersWin()) {
            System.out.println("illegal");
            System.exit(0);
        }
        if (!moveCountsAreValid()) {
            System.out.println("illegal");
            System.exit(0);
        }

        /* -----------------------------------------------------------------
         *  2️⃣  Full board (no empty cells)
         * ----------------------------------------------------------------- */
        if (boardFull) {
            handleFullBoard(winner);
            return;
        }

        /* -----------------------------------------------------------------
         *  3️⃣  Determine whose turn it is next and decide the outcome.
         * ----------------------------------------------------------------- */
        int nextPlayer = (countX == countO) ? Player.FIRST.getValue() : Player.SECOND.getValue();

        if (winner != Player.EMPTY.getValue()) {
            /* The game would have ended on the previous move, therefore the
             * winner must be the player who just moved. */
            if (winner != nextPlayer) {
                System.out.println("illegal");
                System.exit(0);
            }
            announceWinner(winner);
        } else {
            System.out.println(nextPlayer == Player.FIRST.getValue() ? "first" : "second");
        }
    }

    /** Returns true if both players have at least one winning line – an illegal board. */
    private static boolean bothPlayersWin() {
        return hasWin(Player.FIRST) && hasWin(Player.SECOND);
    }

    /** Checks that the numbers of X and O obey the rules of tic‑tac‑toe. */
    private static boolean moveCountsAreValid() {
        // X always starts, therefore countX must be either equal to countO or one larger.
        return countX == countO || countX == countO + 1;
    }

    /** Determines the winner (0 if none) while ensuring the win respects turn order. */
    private static int checkWinner() {
        int winner = Player.EMPTY.getValue();

        // rows
        for (int i = 0; i < SIZE; i++) {
            if (hasThreeInLine(BOARD[i][0], BOARD[i][1], BOARD[i][2])) {
                winner = BOARD[i][0];
            }
            if (hasThreeInLine(BOARD[0][i], BOARD[1][i], BOARD[2][i])) {
                winner = BOARD[0][i];
            }
        }
        // diagonals
        if (hasThreeInLine(BOARD[0][0], BOARD[1][1], BOARD[2][2])) {
            winner = BOARD[0][0];
        }
        if (hasThreeInLine(BOARD[0][2], BOARD[1][1], BOARD[2][0])) {
            winner = BOARD[0][2];
        }

        // If a winner exists, it must be the player whose turn it was just before
        // the board became terminal.
        if (winner != Player.EMPTY.getValue()) {
            int toMove = (countX == countO) ? Player.FIRST.getValue() : Player.SECOND.getValue();
            if (winner != toMove) {
                System.out.println("illegal");
                System.exit(0);
            }
        }
        return winner;
    }

    /** True if the given player occupies any complete row, column, or diagonal. */
    private static boolean hasWin(Player player) {
        int p = player.getValue();
        // rows & columns
        for (int i = 0; i < SIZE; i++) {
            if (BOARD[i][0] == p && BOARD[i][1] == p && BOARD[i][2] == p) return true;
            if (BOARD[0][i] == p && BOARD[1][i] == p && BOARD[2][i] == p) return true;
        }
        // diagonals
        if (BOARD[0][0] == p && BOARD[1][1] == p && BOARD[2][2] == p) return true;
        if (BOARD[0][2] == p && BOARD[1][1] == p && BOARD[2][0] == p) return true;
        return false;
    }

    /** Helper used by `checkWinner` to detect a line of three identical non‑empty values. */
    private static boolean hasThreeInLine(int a, int b, int c) {
        return a != Player.EMPTY.getValue() && a == b && b == c;
    }

    /** Handles the special case where the board is completely filled. */
    private static void handleFullBoard(int winner) {
        // A full board must have been won by X on the very last move.
        if (countX != countO + 1) {
            System.out.println("illegal");
            System.exit(0);
        }

        if (winner == Player.EMPTY.getValue()) {
            System.out.println("draw");
        } else if (winner == Player.FIRST.getValue()) {
            System.out.println("the first player won");
        } else {
            System.out.println("the second player won");
        }
    }

    /** Prints the appropriate message for a winning player. */
    private static void announceWinner(int winner) {
        if (winner == Player.FIRST.getValue()) {
            System.out.println("the first player won");
        } else {
            System.out.println("the second player won");
        }
    }
}

import java.io.*;
import java.util.Objects;

/**
 * Console implementation of a Tic‑Tac‑Toe referee.
 *
 * <p>The program reads a 3×3 board from standard input, validates the board
 * configuration and announces the game result according to the classic rules:
 *
 * <ul>
 *   <li>“illegal” – the board cannot appear during a legal game,
 *   <li>“the first player won” – the player using ‘X’ has a winning line,
 *   <li>“the second player won” – the player using ‘0’ has a winning line,
 *   <li>“draw” – the board is full and nobody won,
 *   <li>“first” – it is the first player's turn to move,
 *   <li>“second” – it is the second player's turn to move.
 * </ul>
 *
 * <p>The implementation is deliberately small and focused on readability:
 * separate helper methods are used for input handling, win detection,
 * counting and legality checks.
 */
public class TicTacToe {

    /** Size of the board – 3×3 */
    private static final int SIZE = 3;

    /** Character used for an empty cell */
    private static final char EMPTY = '.';

    /**
     * Entry point.
     *
     * @param args command line arguments (unused)
     * @throws IOException if reading from {@code System.in} fails
     */
    public static void main(String[] args) throws IOException {
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
             PrintWriter out = new PrintWriter(System.out, true)) {

            char[][] board = readBoard(br);
            int xCount = countSymbols(board, 'X');
            int oCount = countSymbols(board, 'O');

            boolean xWon = hasWon(board, 'X');
            boolean oWon = hasWon(board, 'O');

            System.out.println(evaluateGame(xWon, oWon, xCount, oCount));
        }
    }

    /**
     * Reads exactly three lines from {@code reader} and builds a 3×3 board.
     * Each line should contain at least three non‑newline characters; only the
     * first three characters of each line are used.
     *
     * @param reader source of input
     * @return a 3×3 array representing the board
     */
    private static char[][] readBoard(BufferedReader reader) throws IOException {
        char[][] board = new char[SIZE][SIZE];
        for (int row = 0; row < SIZE; row++) {
            String line = Objects.requireNonNull(reader.readLine(),
                    "Input ended before the board could be read");
            for (int col = 0; col < SIZE; col++) {
                board[row][col] = line.charAt(col);
            }
        }
        return board;
    }

    /**
     * Counts how many cells of the supplied symbol are present on the board.
     *
     * @param board   the board to inspect
     * @param symbol  the symbol to count ('X' or 'O')
     * @return the number of occurrences
     */
    private static int countSymbols(char[][] board, char symbol) {
        int count = 0;
        for (char[] row : board) {
            for (char cell : row) {
                if (cell == symbol) {
                    count++;
                }
            }
        }
        return count;
    }

    /**
     * Determines whether the supplied player has a winning line.
     *
     * @param board   the board to inspect
     * @param player  the player symbol to check ('X' or 'O')
     * @return {@code true} if the player owns at least one complete row,
     * column or diagonal
     */
    private static boolean hasWon(char[][] board, char player) {
        // Check rows
        for (int row = 0; row < SIZE; row++) {
            if (isCompleteLine(board[row], player)) {
                return true;
            }
        }
        // Check columns
        for (int col = 0; col < SIZE; col++) {
            if (isCompleteColumn(board, col, player)) {
                return true;
            }
        }
        // Check diagonals
        if (isCompleteDiagonal(board, player) || isCompleteAntiDiagonal(board, player)) {
            return true;
        }
        return false;
    }

    /** Helper: does a row consist entirely of the given player symbol? */
    private static boolean isCompleteLine(char[] row, char player) {
        return row[0] == player && row[1] == player && row[2] == player;
    }

    /** Helper: does a column consist entirely of the given player symbol? */
    private static boolean isCompleteColumn(char[][] board, int col, char player) {
        return board[0][col] == player && board[1][col] == player && board[2][col] == player;
    }

    /** Helper: does the main diagonal consist entirely of the given player symbol? */
    private static boolean isCompleteDiagonal(char[][] board, char player) {
        return board[0][0] == player && board[1][1] == player && board[2][2] == player;
    }

    /** Helper: does the anti‑diagonal consist entirely of the given player symbol? */
    private static boolean isCompleteAntiDiagonal(char[][] board, char player) {
        return board[0][2] == player && board[1][1] == player && board[2][0] == player;
    }

    /**
     * Evaluates the current board status and returns the appropriate console output.
     *
     * @param xWon     {@code true} if ‘X’ has a winning line
     * @param oWon     {@code true} if ‘O’ has a winning line
     * @param xCount   number of ‘X’ symbols on the board
     * @param oCount   number of ‘O’ symbols on the board
     * @return the textual result according to the specification
     */
    private static String evaluateGame(boolean xWon, boolean oWon,
                                       int xCount, int oCount) {
        // ----- Illegal board configurations ---------------------------------
        if (isIllegalBoard(xWon, oWon, xCount, oCount)) {
            return "illegal";
        }

        // ----- Victory ------------------------------------------------------
        if (xWon) {
            return "the first player won";
        }
        if (oWon) {
            return "the second player won";
        }

        // ----- Draw or next turn --------------------------------------------
        if (xCount + oCount == SIZE * SIZE) {
            return "draw";
        }
        // The player whose turn it is next is the one with fewer symbols,
        // or the first player when the counts are equal (X always starts).
        return (xCount == oCount) ? "first" : "second";
    }

    /**
     * Determines whether the supplied board configuration can appear during a
     * legal game of Tic‑Tac‑Toe.
     *
     * <p>A board is illegal if any of the following holds:
     *
     * <ul>
     *   <li>Both players have winning lines,
     *   <li>Number of ‘O’ symbols exceeds the number of ‘X’ symbols,
     *   <li>Number of ‘X’ symbols exceeds ‘O’ symbols by more than one,
     *   <li>A winning line for ‘X’ exists but the move count does not follow
     *       the rule {@code xCount == oCount + 1},
     *   <li>A winning line for ‘O’ exists but {@code oCount != xCount}.
     * </ul>
     *
     * @param xWon   {@code true} if ‘X’ has a winning line
     * @param oWon   {@code true} if ‘O’ has a winning line
     * @param xCount number of ‘X’ symbols
     * @param oCount number of ‘O’ symbols
     * @return {@code true} if the board is illegal, {@code false} otherwise
     */
    private static boolean isIllegalBoard(boolean xWon, boolean oWon,
                                           int xCount, int oCount) {
        // Both cannot win simultaneously
        if (xWon && oWon) {
            return true;
        }
        // Count invariant: X always moves first, so X count must be >= O count
        if (oCount > xCount) {
            return true;
        }
        // X may have at most one more move than O
        if (xCount - oCount > 1) {
            return true;
        }
        // If X wins, it must have made the last move
        if (xWon && xCount != oCount + 1) {
            return true;
        }
        // If O wins, the move counts must be equal
        if (oWon && oCount != xCount) {
            return true;
        }
        return false;
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;

/**
 * Maintains a Tic‑Tac‑Toe board read from standard input and reports the
 * game state.  Illegal positions are detected and reported as "illegal".
 * Otherwise the program prints the winner, a draw, or which player has
 * the next turn.
 */
public class Main {

    private static final char EMPTY = ' ';
    private static final char PLAYER_X = 'X';
    private static final char PLAYER_O = 'O';

    public static void main(String[] args) {
        // Try‑with‑resources guarantees that the reader is closed automatically.
        try (BufferedReader reader = new BufferedReader(
                new InputStreamReader(System.in))) {

            // -----------------------------------------------------------------
            // 1. Read the 3×3 board and count the number of X's and O's.
            // -----------------------------------------------------------------
            char[][] board = new char[3][3];
            int xCount = 0;
            int oCount = 0;

            for (int row = 0; row < 3; row++) {
                String line = reader.readLine();
                for (int col = 0; col < 3; col++) {
                    char cell = line.charAt(col);
                    board[row][col] = cell;

                    if (cell == PLAYER_X) {
                        xCount++;
                    } else if (cell == PLAYER_O) {
                        oCount++;
                    }
                }
            }

            // -----------------------------------------------------------------
            // 2. Determine whether either player has a winning line.
            // -----------------------------------------------------------------
            boolean xWon = hasWon(board, PLAYER_X);
            boolean oWon = hasWon(board, PLAYER_O);

            // -----------------------------------------------------------------
            // 3. Validate the board state – it must obey the rules of Tic‑Tac‑Toe.
            // -----------------------------------------------------------------
            if (!isLegalState(board, xCount, oCount, xWon, oWon)) {
                System.out.println("illegal");
                return;
            }

            // -----------------------------------------------------------------
            // 4. Announce the result according to the current board.
            // -----------------------------------------------------------------
            if (xWon) {
                System.out.println("the first player won");
            } else if (oWon) {
                System.out.println("the second player won");
            } else if (xCount + oCount == 9) {
                System.out.println("draw");
            } else {
                System.out.println(xCount == oCount ? "first" : "second");
            }

        } catch (IOException e) {
            // In practice this will never happen because we read from System.in.
            // But we keep the catch block to satisfy the compiler.
            throw new RuntimeException("Failed to read input", e);
        }
    }

    /**
     * Checks whether the given player has any winning row, column or diagonal.
     */
    private static boolean hasWon(char[][] board, char player) {
        // Check rows and columns
        for (int i = 0; i < 3; i++) {
            if (allEqual(board[i][0], board[i][1], board[i][2], player)
                    && board[i][0] != EMPTY) {
                return true;
            }
            if (allEqual(board[0][i], board[1][i], board[2][i], player)
                    && board[0][i] != EMPTY) {
                return true;
            }
        }
        // Check the two diagonals
        if (allEqual(board[0][0], board[1][1], board[2][2], player)
                && board[0][0] != EMPTY) {
            return true;
        }
        if (allEqual(board[0][2], board[1][1], board[2][0], player)
                && board[0][2] != EMPTY) {
            return true;
        }
        return false;
    }

    /**
     * Helper that returns true only if all three cells contain the same
     * non‑empty value equal to {@code target}.
     */
    private static boolean allEqual(char a, char b, char c, char target) {
        return a == target && b == target && c == target;
    }

    /**
     * Determines whether the current board configuration obeys the game rules.
     *
     * @return {@code true} if the board is legal, {@code false} otherwise.
     */
    private static boolean isLegalState(char[][] board, int xCount, int oCount,
                                        boolean xWon, boolean oWon) {
        // 1. The number of X's must be equal to or exactly one greater than O's.
        if (Math.abs(xCount - oCount) > 1) {
            return false;
        }

        // 2. Both players cannot win simultaneously.
        if (xWon && oWon) {
            return false;
        }

        // 3. If X wins, it must have made the last move (xCount == oCount + 1).
        if (xWon && xCount != oCount + 1) {
            return false;
        }

        // 4. If O wins, the move counts must be equal.
        if (oWon && xCount != oCount) {
            return false;
        }

        return true;
    }
}

import java.util.Scanner;

/**
 * Refactored version of the original Tic‑Tac‑Toe validator.
 *
 * <p>This class encapsulates the game state, validates the board and
 * prints the appropriate message:
 * <ul>
 *   <li>"illegal" – the board configuration cannot appear during a legal game</li>
 *   <li>"the first player won"</li>
 *   <li>"the second player won"</li>
 *   <li>"draw"</li>
 *   <li>"first"</li>
 *   <li>"second"</li>
 * </ul>
 *
 * <p>The logic follows the same rules as the original program but is
 * organized into small, well‑named methods and free of static mutable
 * fields, making it easier to test and maintain.
 */
public class TicTacToeValidator {

    private static final char EMPTY = '.';
    private static final char FIRST_PLAYER = 'X';
    private static final char SECOND_PLAYER = '0';

    private final char[][] board = new char[3][3];

    /** Reads three lines of 3 characters each from {@link Scanner}. */
    private void readBoard(Scanner scanner) {
        for (int row = 0; row < 3; row++) {
            String line = scanner.next();
            board[row] = line.toCharArray();
        }
    }

    /** Counts how many 'X' and '0' cells are on the board. */
    private CountResult countMoves() {
        int x = 0, o = 0;
        for (int r = 0; r < 3; r++) {
            for (int c = 0; c < 3; c++) {
                if (board[r][c] == FIRST_PLAYER) {
                    x++;
                } else if (board[r][c] == SECOND_PLAYER) {
                    o++;
                }
            }
        }
        return new CountResult(x, o);
    }

    /** Determines whether the given player has a winning line. */
    private boolean hasWon(char player) {
        // rows
        for (int i = 0; i < 3; i++) {
            if (board[i][0] == player && board[i][1] == player && board[i][2] == player) {
                return true;
            }
        }
        // columns
        for (int i = 0; i < 3; i++) {
            if (board[0][i] == player && board[1][i] == player && board[2][i] == player) {
                return true;
            }
        }
        // diagonals
        if (board[0][0] == player && board[1][1] == player && board[2][2] == player) {
            return true;
        }
        if (board[2][0] == player && board[1][1] == player && board[0][2] == player) {
            return true;
        }
        return false;
    }

    /** Returns the player that has won, or {@code EMPTY} if no one has won. */
    private char getWinner() {
        boolean xWins = hasWon(FIRST_PLAYER);
        boolean oWins = hasWon(SECOND_PLAYER);

        if (xWins && oWins) {
            // Both players cannot win simultaneously in a legal game.
            return BOTH_WIN;
        }
        return xWins ? FIRST_PLAYER : (oWins ? SECOND_PLAYER : EMPTY);
    }

    /** Simple holder for move counts. */
    private static final class CountResult {
        final int xCount;
        final int oCount;

        CountResult(int xCount, int oCount) {
            this.xCount = xCount;
            this.oCount = oCount;
        }
    }

    /** Symbol used to indicate that both players have winning lines. */
    private static final char BOTH_WIN = '\0';

    /** Main validation routine – prints the result and exits. */
    private static void validateAndPrint(Scanner scanner) {
        TicTacToeValidator validator = new TicTacToeValidator();
        validator.readBoard(scanner);
        CountResult counts = validator.countMoves();

        // 1. Verify move counts are plausible.
        if (!isMoveCountValid(counts.xCount, counts.oCount)) {
            System.out.println("illegal");
            System.exit(0);
        }

        // 2. Determine if both players have winning lines.
        char winner = validator.getWinner();
        if (winner == BOTH_WIN) {
            System.out.println("illegal");
            System.exit(0);
        }

        // 3. If there is a winner, verify that the winner's move count is consistent.
        if (winner != EMPTY) {
            if (winner == FIRST_PLAYER) {
                // X must have played one more move than O.
                if (counts.xCount != counts.oCount + 1) {
                    System.out.println("illegal");
                    System.exit(0);
                }
                System.out.println("the first player won");
                System.exit(0);
            } else { // SECOND_PLAYER
                // O must have played the same number of moves as X.
                if (counts.oCount != counts.xCount) {
                    System.out.println("illegal");
                    System.exit(0);
                }
                System.out.println("the second player won");
                System.exit(0);
            }
        }

        // 4. No winner yet.
        if (counts.xCount + counts.oCount == 9) {
            System.out.println("draw");
            System.exit(0);
        }

        // 5. Game is still in progress – indicate whose turn it is.
        System.out.println(
                counts.xCount == counts.oCount ? "first" : "second"
        );
        System.exit(0);
    }

    /** Checks whether the numbers of X and O moves follow the game rules. */
    private static boolean isMoveCountValid(int xCount, int oCount) {
        // X always starts, so the only legal patterns are:
        //   x == o      (O's turn)
        //   x == o + 1  (X's turn)
        return (xCount == oCount) || (xCount == oCount + 1);
    }

    /** Entry point – mirrors the original program's behavior. */
    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            validateAndPrint(scanner);
        }
    }
}

import java.util.Scanner;

/**
 * Refactored Tic‑Tac‑Toe implementation.
 * <p>
 * The program reads three lines of three characters each (X, 0 or any other character)
 * that represent the current board state, validates the position and prints one of:
 * <ul>
 *   <li>"the first player won"</li>
 *   <li>"the second player won"</li>
 *   <li>"draw"</li>
 *   <li>"illegal"</li>
 *   <li>"first"</li>  – first player has to move next</li>
 *   <li>"second"</li> – second player has to move next</li>
 * </ul>
 * </p>
 */
public class TicTacToe {

    /** Board size (3×3). */
    private static final int SIZE = 3;

    /** Symbol representations. */
    private static final int EMPTY = 0;
    private static final int PLAYER_X = 1;   // first player
    private static final int PLAYER_O = 2;   // second player

    /** Internal 3×3 board. */
    private final int[][] board = new int[SIZE][SIZE];

    /**
     * Parses the input supplied by the user and stores it in {@link #board}.
     * The input must consist of exactly three lines, each containing three characters.
     *
     * @param scanner a {@link Scanner} that provides the three lines
     * @throws IllegalArgumentException if a line is missing or not of length 3
     */
    public void loadBoard(Scanner scanner) {
        for (int row = 0; row < SIZE; row++) {
            String line = scanner.next();
            if (line == null || line.length() != SIZE) {
                throw new IllegalArgumentException(
                        "Each move line must contain exactly " + SIZE + " characters.");
            }
            for (int col = 0; col < SIZE; col++) {
                char c = line.charAt(col);
                if (c == 'X') {
                    board[row][col] = PLAYER_X;
                } else if (c == '0') {
                    board[row][col] = PLAYER_O;
                } else {
                    board[row][col] = EMPTY;
                }
            }
        }
    }

    /**
     * Checks whether the given player has a winning line on the board.
     *
     * @param player the player to test ({@link #PLAYER_X} or {@link #PLAYER_O})
     * @return {@code true} if the player has won, otherwise {@code false}
     */
    public boolean hasWon(int player) {
        // rows
        for (int i = 0; i < SIZE; i++) {
            if (board[i][0] == player && board[i][1] == player && board[i][2] == player) {
                return true;
            }
            // columns
            if (board[0][i] == player && board[1][i] == player && board[2][i] == player) {
                return true;
            }
        }
        // diagonals
        if (board[0][0] == player && board[1][1] == player && board[2][2] == player) {
            return true;
        }
        if (board[0][2] == player && board[1][1] == player && board[2][0] == player) {
            return true;
        }
        return false;
    }

    /** Counts how many cells contain the given player's mark. */
    private static int count(int player, int[][] b) {
        int cnt = 0;
        for (int[] row : b) {
            for (int cell : row) {
                if (cell == player) {
                    cnt++;
                }
            }
        }
        return cnt;
    }

    /** Determines whether the current board configuration is illegal. */
    private static boolean illegal(int xCount, int oCount, boolean xWon, boolean oWon) {
        return (xCount - oCount > 1) || (xCount < oCount) || (xWon && oWon);
    }

    /**
     * Evaluates the game state and returns the appropriate output string.
     *
     * @param xCount number of 'X' marks on the board
     * @param oCount number of '0' marks on the board
     * @param xWon   {@code true} if the first player has won
     * @param oWon   {@code true} if the second player has won
     * @return a message describing the result
     */
    public static String evaluate(int xCount, int oCount, boolean xWon, boolean oWon) {
        if (illegal(xCount, oCount, xWon, oWon)) {
            return "illegal";
        }
        if (xWon) {
            return "the first player won";
        }
        if (oWon) {
            return "the second player won";
        }
        if (xCount + oCount == SIZE * SIZE) {
            return "draw";
        }
        // Next player to move
        return (xCount == oCount) ? "first" : "second";
    }

    /** Entry point of the program. */
    public static void main(String[] args) {
        // Try‑with‑resources ensures the scanner is closed automatically.
        try (Scanner scan = new Scanner(System.in)) {
            TicTacToe game = new TicTacToe();
            game.loadBoard(scan);

            int xCount = count(PLAYER_X, game.board);
            int oCount = count(PLAYER_O, game.board);
            boolean xWon = game.hasWon(PLAYER_X);
            boolean oWon = game.hasWon(PLAYER_O);

            System.out.println(evaluate(xCount, oCount, xWon, oWon));
        }
    }
}

import java.io.*;
