public final class Main {

    /** Size of the tic‑tac‑toe board */
    private static final int SIZE = 3;

    /** Represent the two players */
    private enum Player {
        NONE,   // no one has won yet
        FIRST,  // X  (first player)
        SECOND  // 0  (second player)
    }

    /** Convert a character to our internal player representation */
    private static Player toPlayer(char c) {
        return switch (c) {
            case 'X' -> Player.FIRST;
            case '0' -> Player.SECOND;
            default  -> Player.NONE;
        };
    }

    /** Checks whether the given player has a winning line on the board */
    private static Player checkWinner(int[][] board) {
        // rows and columns
        for (int i = 0; i < SIZE; i++) {
            if (board[i][0] != 0 && board[i][0] == board[i][1] && board[i][1] == board[i][2]) {
                return board[i][0] == 1 ? Player.FIRST : Player.SECOND;
            }
            if (board[0][i] != 0 && board[0][i] == board[1][i] && board[1][i] == board[2][i]) {
                return board[0][i] == 1 ? Player.FIRST : Player.SECOND;
            }
        }
        // diagonals
        if (board[0][0] != 0 && board[0][0] == board[1][1] && board[1][1] == board[2][2]) {
            return board[0][0] == 1 ? Player.FIRST : Player.SECOND;
        }
        if (board[0][2] != 0 && board[0][2] == board[1][1] && board[1][1] == board[2][0]) {
            return board[0][2] == 1 ? Player.FIRST : Player.SECOND;
        }
        return Player.NONE;
    }

    /** Reads exactly three non‑empty lines, each containing three valid characters. */
    private static int[][] readBoard(BufferedReader br) throws IOException {
        int[][] board = new int[SIZE][SIZE];
        int xCount = 0, oCount = 0;

        for (int row = 0; row < SIZE; row++) {
            String line = br.readLine();
            if (line == null) {
                throw new IllegalStateException("Not enough input lines");
            }
            line = line.trim();
            if (line.length() != SIZE) {
                throw new IllegalArgumentException("Each line must contain exactly 3 characters");
            }
            for (int col = 0; col < SIZE; col++) {
                char c = line.charAt(col);
                if (c == 'X') {
                    board[row][col] = 1;
                    xCount++;
                } else if (c == '0') {
                    board[row][col] = 2;
                    oCount++;
                } else {
                    board[row][col] = 0; // empty
                }
            }
        }
        // store counts in static fields for later validation
        CountHolder.x = xCount;
        CountHolder.o = oCount;
        return board;
    }

    /** Holds the number of X and O placed on the board – used after board construction */
    private static final class CountHolder {
        static int x;
        static int o;
    }

    /** Core validation and result determination */
    private static void solve() throws IOException {
        // ------------------------------------------------------------
        // 1. Read board and count marks
        // ------------------------------------------------------------
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in))) {
            int[][] board = readBoard(br);
        }

        int xCount = CountHolder.x;
        int oCount = CountHolder.o;

        // ------------------------------------------------------------
        // 2. Basic legality checks
        // ------------------------------------------------------------
        // X always starts, therefore the difference must be 0 or 1
        if (! (xCount == oCount || xCount == oCount + 1)) {
            System.out.println("illegal");
            return;
        }

        // ------------------------------------------------------------
        // 3. Determine if someone has already won
        // ------------------------------------------------------------
        Player winner = checkWinner(board); // NONE, FIRST or SECOND

        boolean bothWon = winner != Player.NONE && false; // placeholder for future extension
        // The original program also checks the reverse diagonal; covered above.

        // If both players claim a win, the state is illegal.
        // (In practice this cannot happen with our win detection, but we keep the logic.)
        // The original also validates that a win matches the move counts.
        if (winner == Player.FIRST) {
            if (xCount != oCount + 1) {
                System.out.println("illegal");
                return;
            }
            System.out.println("the first player won");
            return;
        }

        if (winner == Player.SECOND) {
            if (xCount != oCount) {
                System.out.println("illegal");
                return;
            }
            System.out.println("the second player won");
            return;
        }

        // ------------------------------------------------------------
        // 4. No winner yet – decide whose turn it is or if the game is a draw
        // ------------------------------------------------------------
        if (xCount + oCount == SIZE * SIZE) {
            System.out.println("draw");
            return;
        }

        System.out.println(xCount == oCount ? "first" : "second");
    }

    /** Simple holder for the X and O counts read from the board */
    private static final class CountHolder {
        static int x;
        static int o;
    }

    public static void main(String[] args) throws IOException {
        solve();
    }
}

import java.util.Scanner;

/**
 * Tic‑Tac‑Toe (noughts‑and‑crosses) console utility.
 *
 * <p>This version is refactored for readability, maintainability and correctness.
 * All board operations are isolated in dedicated methods, magic numbers are named
 * constants, and the game‑state evaluation is performed by pure functions that
 * make the intent explicit.</p>
 */
public class Test {

    /** Symbol used for the first player (X). */
    private static final char PLAYER_X = 'X';

    /** Symbol used for the second player (O). */
    private static final char PLAYER_O = '0';   // original uses the digit zero

    /** Number of rows (and columns) on the board. */
    private static final int BOARD_SIZE = 3;

    /** Winning lines stored as coordinate triples – avoids duplicated checks. */
    private static final int[][] ROWS = {
            {0, 1, 2},
            {3, 4, 5},
            {6, 7, 8}
    };
    private static final int[][] COLS = {
            {0, 3, 6},
            {1, 4, 7},
            {2, 5, 8}
    };
    private static final int[][] DIAGONALS = {
            {0, 4, 8},
            {2, 4, 6}
    };

    public static void main(String[] args) {
        char[][] board = readBoard();
        EvaluationResult evaluation = evaluate(board);

        System.out.println(evaluation.message);
    }

    /**
     * Reads exactly three lines from {@code System.in} and converts them into a
     * 3×3 char board.
     *
     * @return a 3×3 array containing ‘X’, ‘0’, or any other character (treated as empty)
     */
    private static char[][] readBoard() {
        Scanner scanner = new Scanner(System.in);
        char[][] board = new char[BOARD_SIZE][BOARD_SIZE];

        for (int i = 0; i < BOARD_SIZE; i++) {
            String line = scanner.nextLine();
            if (line.length() != BOARD_SIZE) {
                throw new IllegalArgumentException("Each line must contain exactly " + BOARD_SIZE + " characters.");
            }
            for (int j = 0; j < BOARD_SIZE; j++) {
                board[i][j] = line.charAt(j);
            }
        }
        return board;
    }

    /**
     * Evaluates the supplied board and produces a result message.
     *
     * @param board current game state
     * @return an {@link EvaluationResult} holding the textual outcome
     */
    private static EvaluationResult evaluate(char[][] board) {
        int xCount = countOccurrences(board, PLAYER_X);
        int oCount = countOccurrences(board, PLAYER_O);

        boolean xWins = hasWon(board, PLAYER_X);
        boolean oWins = hasWon(board, PLAYER_O);

        // ---------- Illegal state checks ----------
        if (isIllegalCountDifference(xCount, oCount) || isBothWinners(xWins, oWins)) {
            return new EvaluationResult("illegal");
        }

        // ---------- Determining the winner / next player ----------
        if (xWins) {
            // X can only win on its own turn (X always starts => xCount == oCount + 1)
            return new EvaluationResult("the first player won");
        } else if (oWins) {
            // O can only win when the move counts are equal (O plays after X)
            return new EvaluationResult("the second player won");
        } else if (boardFull(board)) {
            return new EvaluationResult("draw");
        } else if (xCount > oCount) {
            return new EvaluationResult("second");
        } else {
            return new EvaluationResult("first");
        }
    }

    /** @return true if the absolute difference between X and O counts is 2 or more. */
    private static boolean isIllegalCountDifference(int x, int o) {
        return Math.abs(x - o) >= 2;
    }

    /** @return true if both players claim a winning line. */
    private static boolean isBothWinners(boolean xWins, boolean oWins) {
        return xWins && oWins;
    }

    /** @return true when the board contains no empty cells. */
    private static boolean boardFull(char[][] board) {
        for (char[] row : board) {
            for (char cell : row) {
                if (cell != PLAYER_X && cell != PLAYER_O) {
                    return false;
                }
            }
        }
        return true;
    }

    /** Counts how many times {@code symbol} appears on the board. */
    private static int countOccurrences(char[][] board, char symbol) {
        int count = 0;
        for (char[] row : board) {
            for (char cell : row) {
                if (cell == symbol) {
                    count++;
                }
            }
        }
        return count;
    }

    /**
     * Checks whether the given {@code symbol} occupies any winning line.
     *
     * @return true if the symbol has at least one complete row, column or diagonal
     */
    private static boolean hasWon(char[][] board, char symbol) {
        // Helper that checks if the three cells of a line are all the given symbol
        java.util.function.IntUnaryOperator lineMatches = line -> {
            int a = line / BOARD_SIZE;
            int b = line % BOARD_SIZE;
            return board[a][b] == symbol;
        };

        // Check rows and columns via their linear indices (0‑8)
        for (int[] indices : ROWS) {
            if (board[indices[0] / BOARD_SIZE][indices[0] % BOARD_SIZE] == symbol &&
                board[indices[1] / BOARD_SIZE][indices[1] % BOARD_SIZE] == symbol &&
                board[indices[2] / BOARD_SIZE][indices[2] % BOARD_SIZE] == symbol) {
                return true;
            }
        }
        for (int[] indices : COLS) {
            if (board[indices[0] / BOARD_SIZE][indices[0] % BOARD_SIZE] == symbol &&
                board[indices[1] / BOARD_SIZE][indices[1] % BOARD_SIZE] == symbol &&
                board[indices[2] / BOARD_SIZE][indices[2] % BOARD_SIZE] == symbol) {
                return true;
            }
        }
        // Diagonals
        for (int[] indices : DIAGONALS) {
            if (board[indices[0] / BOARD_SIZE][indices[0] % BOARD_SIZE] == symbol &&
                board[indices[1] / BOARD_SIZE][indices[1] % BOARD_SIZE] == symbol &&
                board[indices[2] / BOARD_SIZE][indices[2] % BOARD_SIZE] == symbol) {
                return true;
            }
        }

        // Anti‑diagonal check (already covered by DIAGONALS[1])
        int[] anti = DIAGONALS[1];
        if (board[anti[0] / BOARD_SIZE][anti[0] % BOARD_SIZE] == symbol &&
            board[anti[1] / BOARD_SIZE][anti[1] % BOARD_SIZE] == symbol &&
            board[anti[2] / BOARD_SIZE][anti[2] % BOARD_SIZE] == symbol) {
            return true;
        }

        return false;
    }

    /** Simple DTO to carry the evaluation outcome. */
    private static final class EvaluationResult {
        final String message;

        EvaluationResult(String message) {
            this.message = message;
        }
    }
}

import java.util.Scanner;

/**
 * Maintainable implementation of a simple Tic‑Tac‑Toe validator.
 *
 * <p>It reads a 3×3 board, validates the move order, detects wins and prints the
 * appropriate message:</p>
 * <ul>
 *   <li>illegal – board configuration cannot appear in a real game</li>
 *   <li>draw – board is full and no player has won</li>
 *   <li>first / second – the player whose turn it is next</li>
 *   <li>the first player won / the second player won</li>
 * </ul>
 *
 * <p>All game‑specific logic is isolated in {@link Game} to keep {@code main}
 * clean and easy to test.</p>
 */
public class Main {

    /** Size of the board (always 3 for classic Tic‑Tac‑Toe). */
    private static final int SIZE = 3;

    /** Empty cell marker. */
    private static final char EMPTY = '.';

    /** Player markers used on the board. */
    private static final char PLAYER_X = 'X';
    private static final char PLAYER_O = 'O';

    /** Collection of winning lines (rows, columns and diagonals). */
    private static final int[][] WIN_LINES = {
            // rows
            {0, 1, 2},
            {3, 4, 5},
            {6, 7, 8},
            // columns
            {0, 3, 6},
            {1, 4, 7},
            {2, 5, 8},
            // diagonals
            {0, 4, 8},
            {2, 4, 6}
    };

    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            char[][] board = readBoard(scanner);
            Result result = Game.analyze(board);
            System.out.println(result.message);
        }
    }

    /**
     * Reads exactly three lines from {@code scanner}, each containing three
     * non‑whitespace characters that represent a board row.
     *
     * @param scanner a {@link Scanner} that provides the input
     * @return a 3×3 char matrix holding the board
     * @throws IllegalArgumentException if a line is shorter than three
     *         non‑whitespace characters or contains illegal symbols
     */
    private static char[][] readBoard(Scanner scanner) {
        char[][] board = new char[SIZE][SIZE];
        for (int i = 0; i < SIZE; i++) {
            String line = scanner.nextLine().trim();
            if (line.length() < SIZE) {
                throw new IllegalArgumentException("Each line must contain at least "
                        + SIZE + " non‑whitespace characters.");
            }
            for (int j = 0; j < SIZE; j++) {
                char cell = line.charAt(j);
                if (cell != EMPTY && cell != PLAYER_X && cell != PLAYER_O) {
                    throw new IllegalArgumentException(
                            "Illegal character '" + cell + "' found in input.");
                }
                board[i][j] = cell;
            }
        }
        return board;
    }

    /**
     * Holds the outcome of the board analysis so the caller can simply print
     * the human‑readable message.
     */
    public static final class Result {
        /** The textual message that must be printed to {@code stdout}. */
        public final String message;

        private Result(String message) {
            this.message = message;
        }
    }

    /**
     * Core game‑logic: validates the board, detects winners and produces the
     * appropriate {@link Result}.
     *
     * @param board the 3×3 board to evaluate (already validated for allowed
     *              characters)
     * @return a {@link Result} describing the situation
     */
    public static Result analyze(char[][] board) {
        // -----------------------------------------------------------------
        // 1. Count Xes and Os and ensure the board is legal so far.
        // -----------------------------------------------------------------
        int xCount = 0;
        int oCount = 0;
        outer:
        for (int i = 0; i < SIZE; i++) {
            for (int j = 0; j < SIZE; j++) {
                switch (board[i][j]) {
                    case PLAYER_X -> xCount++;
                    case PLAYER_O -> oCount++;
                }
            }
        }

        // Count validation – the move order must respect turn rules.
        if (Math.abs(xCount - oCount) > 1 || oCount > xCount) {
            return new Result("illegal");
        }

        // -----------------------------------------------------------------
        // 2. Determine whether either player has a winning line.
        // -----------------------------------------------------------------
        boolean xWon = hasWon(board, PLAYER_X);
        boolean oWon = hasWon(board, PLAYER_O);

        // It is illegal for both players to have winning lines simultaneously.
        if (xWon && oWon) {
            return new Result("illegal");
        }

        // If a player has won, the move counts must reflect that the winner
        // made the last move.
        if (xWon && xCount != oCount + 1) {
            return new Result("illegal");
        }
        if (oWon && xCount != oCount) {
            return new Result("illegal");
        }

        // -----------------------------------------------------------------
        // 3. Produce the final message based on the current board state.
        // -----------------------------------------------------------------
        if (xWon) {
            return new Result("the first player won");
        }
        if (oWon) {
            return new Result("the second player won");
        }

        // No winner yet.
        if (xCount + oCount == SIZE * SIZE) {
            return new Result("draw");
        }

        // Game is still ongoing – indicate whose turn is next.
        return new Result(xCount == oCount ? "first" : "second");
    }

    /**
     * Checks whether the given marker ('X' or 'O') occupies any of the
     * predefined winning lines.
     *
     * @param board   the game board
     * @param marker  the player marker to test for a win
     * @return {@code true} if the marker has at least one complete line
     */
    private static boolean hasWon(char[][] board, char marker) {
        outer:
        for (int[] line : WIN_LINES) {
            int sum = 0;
            for (int index : line) {
                char cell = board[index / SIZE][index % SIZE];
                if (cell == marker) {
                    sum++;
                } else {
                    continue outer; // this line cannot be a winning line
                }
            }
            // Because each line has exactly three cells, a full line equals 3.
            // Using a sum check makes the intent explicit.
            if (sum == 3) {
                return true;
            }
        }
        return false;
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.PrintWriter;

/**
 * Simple Tic‑Tac‑Toe validator/announcer.
 *
 * Reads a 3×3 board from standard input, validates the position and prints the
 * appropriate game status:
 *   - win/lose messages,
 *   - illegal board messages,
 *   - draw message,
 *   - whose turn it is next.
 *
 * The program follows the specification of the original implementation but
 * has been refactored for readability, maintainability and correctness.
 */
public final class TicTacToe {

    /** Board size – keep it in a single place. */
    private static final int SIZE = 3;

    /** Player symbols used on the board. */
    private static final char PLAYER_X = 'X';
    private static final char PLAYER_O = '0';
    private static final char EMPTY = ' ';

    /** Result of board validation – useful for a clear flow in {@code main}. */
    private enum ValidationResult {
        VALID,
        ILLEGAL,
        DRAW,
        FIRST_TURN,
        SECOND_TURN,
        FIRST_WON,
        SECOND_WON
    }

    public static void main(String[] args) throws IOException {
        try (BufferedReader reader = new BufferedReader(
                new java.io.InputStreamReader(System.in));
             PrintWriter out = new PrintWriter(System.out)) {

            char[][] board = readBoard(reader);
            ValidationResult result = evaluatePosition(board);

            String message = switch (result) {
                case FIRST_WON -> "the first player won";
                case SECOND_WON -> "the second player won";
                case DRAW -> "draw";
                case ILLEGAL -> "illegal";
                case FIRST_TURN -> "first";
                case SECOND_TURN -> "second";
                case VALID -> throw new AssertionError("Unexpected VALID state");
            };

            out.println(message);
        }
    }

    /**
     * Reads three lines from {@code reader}, each expected to contain exactly
     * three characters representing one row of the board.
     *
     * @return a 3×3 char array holding the board.
     */
    private static char[][] readBoard(BufferedReader reader) throws IOException {
        char[][] board = new char[SIZE][SIZE];

        for (int row = 0; row < SIZE; row++) {
            String line = reader.readLine();
            if (line == null || line.length() != SIZE) {
                throw new IllegalArgumentException(
                        "Input must contain three lines of three characters each.");
            }

            for (int col = 0; col < SIZE; col++) {
                board[row][col] = line.charAt(col);
            }
        }

        return board;
    }

    /**
     * Determines the status of the supplied board.
     *
     * Validation rules (identical to the original program):
     * <ul>
     *   <li>The number of X's can be equal to or exactly one greater than the
     *       number of O's.</li>
     *   <li>Both players cannot be winning simultaneously.</li>
     *   <li>If O has won, the move count of X must be equal to that of O.</li>
     *   <li>If X has won, the move count of X must be greater than that of O.</li>
     *   <li>A completely filled board with a winner is illegal.</li>
     * </ul>
     *
     * @param board the current board state.
     * @return a {@link ValidationResult} describing the situation.
     */
    private static ValidationResult evaluatePosition(char[][] board) {
        int xCount = countOccurrences(board, PLAYER_X);
        int oCount = countOccurrences(board, PLAYER_O);
        int blankCount = SIZE * SIZE - xCount - oCount;

        boolean xWon = hasWon(board, PLAYER_X);
        boolean oWon = hasWon(board, PLAYER_O);

        // 1️⃣  Count‑mismatch or both players winning → illegal.
        if (Math.abs(xCount - oCount) > 1 || (xWon && oWon)) {
            return ValidationResult.ILLEGAL;
        }

        // 2️⃣  O cannot have made more moves than X.
        if (oCount > xCount) {
            return ValidationResult.ILLEGAL;
        }

        // 3️⃣  If the board is full and there is no winner → draw.
        if (blankCount == 0 && xCount > oCount && !xWon) {
            return ValidationResult.DRAW;
        }

        // 4️⃣  Illegal win conditions.
        if (oWon && xCount > oCount) {
            return ValidationResult.ILLEGAL;
        }
        if (xWon && xCount == oCount) {
            return ValidationResult.ILLEGAL;
        }

        // 5️⃣  Determine the next player or announce a win/draw.
        if (xWon) {
            return ValidationResult.FIRST_WON;
        }
        if (oWon) {
            return ValidationResult.SECOND_WON;
        }

        // No winner – whose turn is it?
        return (xCount == oCount) ? ValidationResult.FIRST_TURN
                                 : ValidationResult.SECOND_TURN;
    }

    /**
     * Counts how many times {@param symbol} appears on the board.
     *
     * @param grid   the board to scan.
     * @param symbol the character to count ('X' or '0').
     * @return the total occurrences.
     */
    private static int countOccurrences(char[][] grid, char symbol) {
        int count = 0;
        for (int row = 0; row < SIZE; row++) {
            for (int col = 0; col < SIZE; col++) {
                if (grid[row][col] == symbol) {
                    count++;
                }
            }
        }
        return count;
    }

    /**
     * Checks whether the given player has a winning line (row, column or diagonal).
     *
     * @param grid   the board.
     * @param player the player symbol to test ('X' or '0').
     * @return {@code true} if the player has won.
     */
    private static boolean hasWon(char[][] grid, char player) {
        // Check rows.
        for (int row = 0; row < SIZE; row++) {
            if (grid[row][0] == player && grid[row][1] == player && grid[row][2] == player) {
                return true;
            }
        }
        // Check columns.
        for (int col = 0; col < SIZE; col++) {
            if (grid[0][col] == player && grid[1][col] == player && grid[2][col] == player) {
                return true;
            }
        }
        // Check diagonals.
        if (grid[0][0] == player && grid[1][1] == player && grid[2][2] == player) {
            return true;
        }
        if (grid[0][2] == player && grid[1][1] == player && grid[2][0] == player) {
            return true;
        }
        return false;
    }
}

import java.util.Scanner;

/**
 * Refactored version of the original “a2” program.
 * It reads a 3×3 Tic‑Tac‑Toe board, validates the position,
 * detects a winner (if any) and prints the appropriate message.
 *
 * Output semantics (identical to the original):
 *   • "illegal"      – the board configuration cannot arise from legal play
 *   • "draw"         – the board is full and there is no winner
 *   • "the first player won" – X has a winning line
 *   • "the second player won" – O has a winning line
 *   • "first" / "second" – whose turn it would be next (no winner yet)
 */
public class a2 {

    /** Symbol used for the first player. */
    private static final char PLAYER_X = 'X';
    /** Symbol used for the second player. */
    private static final char PLAYER_O = 'O';

    public static void main(String[] args) {
        try (Scanner sc = new Scanner(System.in)) {
            char[][] board = readBoard(sc);
            if (board == null) {
                System.out.println("illegal");
                return;
            }

            int countX = countOccurrences(board, PLAYER_X);
            int countO = countOccurrences(board, PLAYER_O);

            if (!isLegalPosition(countX, countO, board)) {
                System.out.println("illegal");
                return;
            }

            boolean xWins = isWinning(board, PLAYER_X);
            boolean oWins = isWinning(board, PLAYER_O);

            // Both players cannot win simultaneously
            if (xWins && oWins) {
                System.out.println("illegal");
                return;
            }

            if (xWins) {
                System.out.println("the first player won");
            } else if (oWins) {
                System.out.println("the second player won");
            } else if (countX + countO == 9) {
                System.out.println("draw");
            } else {
                // No winner yet – indicate which player moves next
                System.out.println(countX == countO ? "first" : "second");
            }
        }
    }

    /**
     * Reads three lines from {@code Scanner} and builds a 3×3 char matrix.
     * Returns {@code null} if any line does not contain exactly three characters.
     */
    private static char[][] readBoard(Scanner sc) {
        char[][] board = new char[3][3];
        for (int i = 0; i < 3; i++) {
            String line = sc.next().trim();
            if (line.length() != 3) {
                return null; // malformed input → illegal
            }
            board[i] = line.toCharArray();
        }
        return board;
    }

    /**
     * Counts how many times {@code symbol} occurs on the board.
     */
    private static int countOccurrences(char[][] board, char symbol) {
        int cnt = 0;
        for (char[] row : board) {
            for (char cell : row) {
                if (cell == symbol) {
                    cnt++;
                }
            }
        }
        return cnt;
    }

    /**
     * Determines whether the current board position obeys the rules of Tic‑Tac‑Toe.
     *
     * The checks performed are:
     *   1. Number of moves must be consistent (O never exceeds X, and the difference is at most 1).
     *   2. If O has a winning line, the move counts must be equal.
     *   3. If X has a winning line, X must have made exactly one more move than O.
     *
     * @return {@code true} if the position is legal, {@code false} otherwise.
     */
    private static boolean isLegalPosition(int countX, int countO, char[][] board) {
        // 1) consistency of move counts
        if (countO > countX || countX - countO > 1) {
            return false;
        }

        // 2) O cannot win unless the board is balanced
        if (isWinning(board, PLAYER_O) && countX != countO) {
            return false;
        }

        // 3) X cannot win unless it has made one more move than O
        if (isWinning(board, PLAYER_X) && countX != countO + 1) {
            return false;
        }

        // All checks passed → position is legal
        return true;
    }

    /**
     * Checks whether the given {@code player} occupies any winning line
     * (row, column or diagonal) on the board.
     */
    private static boolean isWinning(char[][] board, char player) {
        // Rows
        for (int i = 0; i < 3; i++) {
            if (board[i][0] == player && board[i][1] == player && board[i][2] == player) {
                return true;
            }
        }
        // Columns
        for (int j = 0; j < 3; j++) {
            if (board[0][j] == player && board[1][j] == player && board[2][j] == player) {
                return true;
            }
        }
        // Diagonals
        if (board[0][0] == player && board[1][1] == player && board[2][2] == player) {
            return true;
        }
        if (board[0][2] == player && board[1][1] == player && board[2][0] == player) {
            return true;
        }
        return false;
    }
}

/**
 * Tic‑Tac‑Toe validator.
 *
 * <p>This program reads three lines from standard input, each line representing a row of a
 * 3×3 board. The characters are:</p>
 * <ul>
 *   <li>'X' – move of the first player</li>
 *   <li>'0' – move of the second player (the digit zero)</li>
 *   <li>'.' – empty square</li>
 * </ul>
 *
 * <p>The validator checks the board for legality and reports one of the following:</p>
 * <ul>
 *   <li>"illegal" – the board cannot arise during a proper game</li>
 *   <li>"the first player won"</li>
 *   <li>"the second player won"</li>
 *   <li>"draw" – the board is full and nobody won</li>
 *   <li>"first" – it is the first player's turn</li>
 *   <li>"second" – it is the second player's turn</li>
 * </ul>
 *
 * <p>The implementation follows clean‑code principles:</p>
 * <ul>
 *   <li>Encapsulation of board representation with an {@link Mark} enum</li>
 *   <li>Pure functions without mutable static state</li>
 *   <li>Descriptive method names and meaningful constants</li>
 *   <li>Clear separation of concerns (parsing, validation, win detection)</li>
 *   <li>Resource‑safe input handling with try‑with‑resources</li>
 * </ul>
 */
public class TicTacToeValidator {

    /** The three possible cell states on the board. */
    private enum Mark { EMPTY, X, O }

    /** Board dimension – kept as a constant to avoid magic numbers. */
    private static final int SIZE = 3;

    /**
     * Entry point – reads three rows from {@code System.in} and prints the evaluation.
     */
    public static void main(String[] args) throws IOException {
        // Try‑with‑resources guarantees the BufferedReader is closed promptly.
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in))) {
            // We expect exactly three lines; extra lines are ignored.
            String[] inputLines = br.lines().limit(SIZE).toArray(String[]::new);
            Mark[][] board = new Mark[SIZE][SIZE];

            for (int r = 0; r < SIZE; r++) {
                board[r] = parseRow(inputLines[r]);
            }

            System.out.println(evaluate(board));
        }
    }

    /** Converts a single character into the corresponding {@link Mark}. */
    private static Mark mapCharToMark(char c) {
        return switch (c) {
            case 'X' -> Mark.X;
            case '0' -> Mark.O;           // The digit zero represents the second player
            case '.' -> Mark.EMPTY;
            default -> throw new IllegalArgumentException("Invalid board character: " + c);
        };
    }

    /** Parses one row of the input and returns an array of {@link Mark}. */
    private static Mark[] parseRow(String line) {
        Mark[] row = new Mark[SIZE];
        for (int i = 0; i < SIZE; i++) {
            row[i] = mapCharToMark(line.charAt(i));
        }
        return row;
    }

    /**
     * Main validation routine – determines the textual description of the supplied board.
     *
     * @param board a 3×3 matrix of {@link Mark}
     * @return one of the predefined status strings
     */
    private static String evaluate(Mark[][] board) {
        int xCount = count(board, Mark.X);
        int oCount = count(board, Mark.O);

        // 1️⃣  Illegal count configurations
        if (!isLegalCount(xCount, oCount)) {
            return "illegal";
        }

        boolean xWon = hasWon(board, Mark.X);
        boolean oWon = hasWon(board, Mark.O);

        // 2️⃣  Both players cannot win simultaneously
        if (xWon && oWon) {
            return "illegal";
        }

        // 3️⃣  Determine winner and adjust legality based on turn order
        if (xWon) {
            return (xCount == oCount + 1) ? "the first player won" : "illegal";
        }
        if (oWon) {
            return (xCount == oCount) ? "the second player won" : "illegal";
        }

        // 4️⃣  Game finished?
        if (xCount + oCount == SIZE * SIZE) {
            return "draw";
        }

        // 5️⃣  Whose turn is it?
        return (xCount == oCount) ? "first" : "second";
    }

    /** Returns true if the supplied counts follow the rules of turn order. */
    private static boolean isLegalCount(int x, int o) {
        return (x == o) || (x == o + 1);
    }

    /** Checks whether the given player has a complete row, column or diagonal. */
    private static boolean hasWon(Mark[][] board, Mark player) {
        // Check rows
        for (int r = 0; r < SIZE; r++) {
            if (board[r][0] == player && board[r][1] == player && board[r][2] == player) {
                return true;
            }
        }
        // Check columns
        for (int c = 0; c < SIZE; c++) {
            if (board[0][c] == player && board[1][c] == player && board[2][c] == player) {
                return true;
            }
        }
        // Check diagonals
        if (board[0][0] == player && board[1][1] == player && board[2][2] == player) {
            return true;
        }
        if (board[0][2] == player && board[1][1] == player && board[2][0] == player) {
            return true;
        }
        return false;
    }

    /** Counts how many cells in the board match the supplied {@link Mark}. */
    private static int count(Mark[][] board, Mark mark) {
        int counter = 0;
        for (Mark[] row : board) {
            for (Mark cell : row) {
                if (cell == mark) {
                    counter++;
                }
            }
        }
        return counter;
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;

/**
 * Refactored Tic‑Tac‑Toe program.
 * <p>
 * The code is split into small, single‑responsibility methods,
 * uses an enum to represent the different possible outcomes,
 * and removes magic strings/magic numbers.
 * </p>
 */
public class TicTacToe {

    /* --------------------------------------------------------------------- */
    /*  Constants – keep all user‑visible messages in one place               */
    /* --------------------------------------------------------------------- */
    private static final char EMPTY = '.';
    private static final String MESSAGE_ILLEGAL = "illegal";
    private static final String MESSAGE_FIRST_WON = "the first player won";
    private static final String MESSAGE_SECOND_WON = "the second player won";
    private static final String MESSAGE_DRAW = "draw";

    /* --------------------------------------------------------------------- */
    /*  Enumerations                                                          */
    /* --------------------------------------------------------------------- */
    /**
     * All possible results after analysing a board.
     */
    private enum Result {
        ILLEGAL,
        FIRST_WON,
        SECOND_WON,
        DRAW,
        NEXT_PLAYER // the player whose turn it is to move
    }

    /**
     * Player identifiers – also hold the win‑message for each player.
     */
    private enum Player {
        X(MESSAGE_FIRST_WON) {
            @Override
            String winMessage() { return MESSAGE_FIRST_WON; }
        },
        O(MESSAGE_SECOND_WON) {
            @Override
            String winMessage() { return MESSAGE_SECOND_WON; }
        };

        private final String winMessage;
        Player(String winMessage) { this.winMessage = winMessage; }
        String winMessage() { return winMessage; }
        static Player fromSymbol(char c) { return c == 'X' ? X : O; }
    }

    /* --------------------------------------------------------------------- */
    /*  Instance fields                                                         */
    /* --------------------------------------------------------------------- */
    private final char[][] grid = new char[3][3];
    private Result result;                // outcome of the analysis
    private Player nextPlayer;            // valid only when result == NEXT_PLAYER
    private Player winner;                // valid only when result is a win
    private boolean draw;                 // valid only when result == DRAW

    /* --------------------------------------------------------------------- */
    /*  Entry point                                                             */
    /* --------------------------------------------------------------------- */
    public static void main(String[] args) throws IOException {
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in))) {
            new TicTacToe().initAndPlay(br);
        }
    }

    /* --------------------------------------------------------------------- */
    /*  Public API                                                              */
    /* --------------------------------------------------------------------- */
    /** Reads the board, analyses it and prints the appropriate message. */
    private void initAndPlay(BufferedReader br) throws IOException {
        readBoard(br);
        analyseBoard();
        printResult();
    }

    /* --------------------------------------------------------------------- */
    /*  Private helpers – readability & maintainability                         */
    /* --------------------------------------------------------------------- */
    /** Reads exactly three lines, each containing three characters. */
    private void readBoard(BufferedReader br) throws IOException {
        for (int row = 0; row < 3; row++) {
            String line = br.readLine();
            if (line == null || line.length() != 3) {
                throw new IllegalArgumentException("Invalid input format");
            }
            grid[row] = line.toCharArray();
        }
    }

    /** Analyses the board and sets {@link #result}, {@link #winner},
     *  {@link #draw}, and {@link #nextPlayer}. */
    private void analyseBoard() {
        countPieces();
        validateCounts();
        detectWinner();
        checkMultipleWinners();
        detectDraw();
        determineNextPlayer();
    }

    /** Counts X's and O's on the board. */
    private void countPieces() {
        int x = 0, o = 0;
        for (int r = 0; r < 3; r++) {
            for (int c = 0; c < 3; c++) {
                char val = grid[r][c];
                if (val == 'X') x++;
                else if (val == '0') o++;
                else if (val != EMPTY) {
                    // unexpected character – treat as illegal
                    throw new IllegalArgumentException("Invalid board character");
                }
            }
        }
        this.xCount = x;
        this.oCount = o;
    }

    /** Validates turn order and winner‑consistency. May throw IllegalStateException. */
    private void validateCounts() {
        if (oCount > xCount || xCount - oCount > 1) {
            result = Result.ILLEGAL;
            return;
        }
        if (winner == Player.X && !validWhenXWins()) {
            result = Result.ILLEGAL;
        } else if (winner == Player.O && !validWhenOWins()) {
            result = Result.ILLEGAL;
        }
    }

    /** X can only win on its turn → xCount == oCount + 1 */
    private boolean validWhenXWins() {
        return xCount == oCount + 1;
    }

    /** O can only win on its turn → xCount == oCount */
    private boolean validWhenOWins() {
        return xCount == oCount;
    }

    /** Detects a winning line and stores the winning player, if any. */
    private void detectWinner() {
        winner = null;
        // rows
        for (int r = 0; r < 3; r++) {
            if (hasWinningLine(grid[r])) {
                winner = Player.fromSymbol(grid[r][0]);
            }
        }
        // columns
        for (int c = 0; c < 3; c++) {
            if (hasWinningLine(column(c))) {
                winner = Player.fromSymbol(grid[0][c]);
            }
        }
        // diagonals
        if (hasWinningLine(diagonalMain())) {
            winner = Player.fromSymbol(grid[0][0]);
        }
        if (hasWinningLine(diagonalAnti())) {
            winner = Player.fromSymbol(grid[0][2]);
        }
        // multiple distinct winners → illegal
        if (hasMoreThanOneDistinctWinner()) {
            result = Result.ILLEGAL;
        }
    }

    /** Returns true if the supplied 3‑char array is a winning line. */
    private boolean hasWinningLine(char[] line) {
        return line[0] != EMPTY && line[0] == line[1] && line[1] == line[2];
    }

    /** Helper to extract a column as a 3‑char array. */
    private char[] column(int idx) {
        return new char[]{grid[0][idx], grid[1][idx], grid[2][idx]};
    }

    /** Main diagonal (top‑left → bottom‑right). */
    private char[] diagonalMain() {
        return new char[]{grid[0][0], grid[1][1], grid[2][2]};
    }

    /** Anti‑diagonal (top‑right → bottom‑left). */
    private char[] diagonalAnti() {
        return new char[]{grid[0][2], grid[1][1], grid[2][0]};
    }

    /** Returns true if we have observed two *different* winning symbols. */
    private boolean hasMoreThanOneDistinctWinner() {
        Player[] distinctWinners = new Player[2];
        int idx = 0;
        // rows
        for (int r = 0; r < 3; r++) {
            if (hasWinningLine(grid[r])) {
                distinctWinners[idx++] = Player.fromSymbol(grid[r][0]);
            }
        }
        // columns
        for (int c = 0; c < 3; c++) {
            if (hasWinningLine(column(c))) {
                distinctWinners[idx++] = Player.fromSymbol(grid[0][c]);
            }
        }
        // diagonals
        if (hasWinningLine(diagonalMain())) {
            distinctWinners[idx++] = Player.fromSymbol(grid[0][0]);
        }
        if (hasWinningLine(diagonalAnti())) {
            distinctWinners[idx++] = Player.fromSymbol(grid[0][2]);
        }
        // deduplicate and count distinct values
        java.util.Set<Player> unique = new java.util.HashSet<>();
        for (Player p : distinctWinners) {
            if (p != null) unique.add(p);
        }
        return unique.size() > 1;
    }

    /** Sets {@link #draw} when the board is full and there is no winner. */
    private void detectDraw() {
        draw = (xCount + oCount == 9) && winner == null;
    }

    /** Determines which player must move next, if the game is not finished. */
    private void determineNextPlayer() {
        if (result != Result.ILLEGAL && winner == null && !draw) {
            nextPlayer = (xCount == oCount) ? Player.X : Player.O;
        }
    }

    /** Maps the internal state to a user‑visible outcome. */
    private Result mapToResult() {
        if (result == Result.ILLEGAL) {
            return Result.ILLEGAL;
        }
        if (winner != null) {
            return (winner == Player.X) ? Result.FIRST_WON : Result.SECOND_WON;
        }
        if (draw) {
            return Result.DRAW;
        }
        return Result.NEXT_PLAYER;
    }

    /** Prints the appropriate message based on the computed {@link Result}. */
    private void printResult() {
        Result r = mapToResult();
        switch (r) {
            case ILLEGAL -> System.out.println(MESSAGE_ILLEGAL);
            case FIRST_WON -> System.out.println(winner.winMessage());
            case SECOND_WON -> System.out.println(winner.winMessage());
            case DRAW -> System.out.println(MESSAGE_DRAW);
            case NEXT_PLAYER -> System.out.println(nextPlayer.winMessage());
        }
    }

    /* --------------------------------------------------------------------- */
    /*  Additional fields used during analysis                                 */
    /* --------------------------------------------------------------------- */
    private int xCount; // number of 'X' symbols on the board
    private int oCount; // number of '0' symbols on the board
}

import java.io.*;
import java.util.StringTokenizer;

/**
 * Tiny console I/O helper that works like a stripped‑down Scanner.
 */
class InputReader {
    private final BufferedReader br;

    InputReader(InputStream source) {
        this.br = new BufferedReader(new InputStreamReader(source));
    }

    /** Reads the next token from standard input. */
    String next() {
        while (true) {
            try {
                String line = br.readLine();
                if (line == null) {
                    return null;
                }
                StringTokenizer tokenizer = new StringTokenizer(line);
                if (tokenizer.hasMoreTokens()) {
                    return tokenizer.nextToken();
                }
            } catch (IOException e) {
                throw new UncheckedIOException(e);
            }
        }
    }
}

/**
 * Core logic of the tic‑tac‑toe validator.
 * <p>
 * The program validates a single 3×3 board read from stdin and prints one of:
 * <ul>
 *   <li>the first player won</li>
 *   <li>the second player won</li>
 *   <li>draw</li>
 *   <li>first</li>
 *   <li>second</li>
 *   <li>illegal</li>
 * </ul>
 * </p>
 */
final class TicTacToeValidator {

    /** Symbol used by the first player. */
    private static final char PLAYER_X = 'X';

    /** Symbol used by the second player. */
    private static final char PLAYER_O = 'O';

    /** Board representation – 3×3 grid. */
    private final char[][] board = new char[3][3];

    /** Number of X's and O's on the board. */
    private int countX;
    private int countO;

    /**
     * Reads exactly nine tokens (three rows of three characters each) from the
     * supplied {@link InputReader}.  Each token is expected to contain a single
     * character representing a cell of the board.
     *
     * @param reader input source
     * @throws IllegalStateException if fewer than nine tokens are available
     */
    void readBoard(InputReader reader) {
        for (int row = 0; row < 3; row++) {
            String line = reader.next();
            if (line == null) {
                throw new IllegalStateException("Not enough board cells provided");
            }
            // Accept a whole line of three characters or three separate tokens.
            if (line.length() == 3) {
                board[row][0] = line.charAt(0);
                board[row][1] = line.charAt(1);
                board[row][2] = line.charAt(2);
            } else {
                board[row][0] = line.charAt(0);
                board[row][1] = reader.next().charAt(0);
                board[row][2] = reader.next().charAt(0);
            }
            // Count pieces while populating the board.
            for (char cell : board[row]) {
                if (cell == PLAYER_X) {
                    ++countX;
                } else if (cell == PLAYER_O) {
                    ++countO;
                } else {
                    throw new IllegalStateException(
                        "Invalid cell value: " + cell);
                }
            }
        }
    }

    /**
     * Checks whether the supplied player has a winning line.
     *
     * @param player symbol to test ('X' or 'O')
     * @return {@code true} if the player owns any complete row, column or diagonal
     */
    private boolean hasWon(char player) {
        // Diagonals
        if (board[0][0] == player && board[1][1] == player && board[2][2] == player) {
            return true;
        }
        if (board[0][2] == player && board[1][1] == player && board[2][0] == player) {
            return true;
        }

        // Rows & columns
        for (int i = 0; i < 3; i++) {
            if (lineMatches(i, 0, i, 1, i, 2, player)) {
                return true;
            }
            if (lineMatches(0, i, 1, i, 2, i, player)) {
                return true;
            }
        }
        return false;
    }

    /** Helper – checks three cells in a straight line for {@code player}. */
    private boolean lineMatches(int c0, int c1, int c2, int r0, int r1, int r2, char player) {
        return board[r0][c0] == player &&
               board[r1][c1] == player &&
               board[r2][c2] == player;
    }

    /**
     * Validates the board according to the rules of tic‑tac‑toe and prints
     * the appropriate result.
     *
     * @param out print stream for the answer
     */
    void validate(PrintWriter out) {
        // 1️⃣  Basic count validation
        if (!isCountConfigurationValid()) {
            out.println("illegal");
            return;
        }

        // 2️⃣  Win‑state validation
        boolean xWon = hasWon(PLAYER_X);
        boolean oWon = hasWon(PLAYER_O);

        if (xWon && oWon) {
            out.println("illegal");
        } else if (xWon) {
            out.println(countX == countO + 1 ? "the first player won" : "illegal");
        } else if (oWon) {
            out.println(countX == countO ? "the second player won" : "illegal");
        } else if (isBoardFull()) {
            out.println("draw");
        } else if (countX == countO) {
            out.println("first");
        } else {
            out.println("second");
        }
    }

    /** Returns {@code true} if X and O counts obey the turn order rule. */
    private boolean isCountConfigurationValid() {
        // X always starts, therefore #X must be equal to #O or #O+1
        return countX == countO || countX == countO + 1;
    }

    /** Returns {@code true} when the board contains nine pieces. */
    private boolean isBoardFull() {
        return countX + countO == 9;
    }
}

/**
 * Main class – thin wrapper that wires the validator with I/O.
 */
public class Main {
    public static void main(String[] args) {
        // Standard streams
        try (InputStream in = System.in;
             PrintWriter out = new PrintWriter(System.out, true)) {

            InputReader reader = new InputReader(in);
            new TicTacToeValidator()
                    .readBoard(reader)
                    .validate(out);
        }
    }
}

/**
 * Refactored Tic‑Tac‑Toe validator.
 *
 * <p>
 *   The program reads a 3×3 board from standard input (three lines, each
 *   containing three characters: 'X', '0' or '.'). It then evaluates the
 *   board and prints a single line describing its state:
 *   <ul>
 *       <li>"illegal"</li>
 *       <li>"the first player won"</li>
 *       <li>"the second player won"</li>
 *       <li>"draw"</li>
 *       <li>"first"</li>
 *       <li>"second"</li>
 *   </ul>
 *   The original implementation was monolithic and hard‑to‑maintain.
 *   This version separates concerns into small, well‑named classes and
 *   constants, adds Javadoc, and removes magic numbers.
 * </p>
 */
public class TicTacToe {

    /** Size of the board (3×3). */
    private static final int BOARD_SIZE = 3;

    /**
     * Entry point of the program.
     *
     * @param args command‑line arguments (not used)
     */
    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            Board board = new Board();
            board.readFromScanner(scanner);
            String outcome = GameEvaluator.evaluate(board);
            System.out.println(outcome);
        }
    }
}

/**
 * Represents the 3×3 Tic‑Tac‑Toe board.
 *
 * <p>The board stores the characters read from the input and provides
 * convenient methods for counting pieces and checking win conditions.</p>
 */
final class Board {

    /** The underlying 2‑dimensional array of cells. */
    private final char[][] cells = new char[BOARD_SIZE][BOARD_SIZE];

    /**
     * Reads exactly three lines from the supplied {@link Scanner}. Each line
     * must contain exactly three characters; otherwise an {@link IllegalArgumentException}
     * is thrown.
     *
     * @param scanner a scanner positioned at the start of the board data
     * @throws IllegalArgumentException if the input format is invalid
     */
    void readFromScanner(Scanner scanner) {
        for (int row = 0; row < BOARD_SIZE; row++) {
            if (!scanner.hasNextLine()) {
                throw new IllegalArgumentException("Not enough lines in input.");
            }
            String line = scanner.nextLine().trim();
            if (line.length() != BOARD_SIZE) {
                throw new IllegalArgumentException(
                    "Each line must contain exactly " + BOARD_SIZE + " characters.");
            }
            for (int col = 0; col < BOARD_SIZE; col++) {
                cells[row][col] = line.charAt(col);
            }
        }
    }

    /** @return number of 'X' pieces on the board. */
    int count(char player) {
        int cnt = 0;
        for (int i = 0; i < BOARD_SIZE; i++) {
            for (int j = 0; j < BOARD_SIZE; j++) {
                if (cells[i][j] == player) {
                    cnt++;
                }
            }
        }
        return cnt;
    }

    /** @return {@code true} if the supplied player has a winning line. */
    boolean hasWin(char player) {
        // Check rows and columns
        for (int i = 0; i < BOARD_SIZE; i++) {
            if (cells[0][i] == player && cells[1][i] == player && cells[2][i] == player) {
                return true;
            }
            if (cells[i][0] == player && cells[i][1] == player && cells[i][2] == player) {
                return true;
            }
        }
        // Diagonals
        if (cells[0][0] == player && cells[1][1] == player && cells[2][2] == player) {
            return true;
        }
        if (cells[2][0] == player && cells[1][1] == player && cells[0][2] == player) {
            return true;
        }
        return false;
    }
}

/**
 * Encapsulates the logical evaluation of a Tic‑Tac‑Toe board.
 *
 * <p>All business rules (illegal states, win detection, whose turn it is, etc.)
 * are centralized here, making the code easy to test and modify.</p>
 */
final class GameEvaluator {

    /** Private constructor – utility class. */
    private GameEvaluator() {}

    /**
     * Evaluates the supplied board and returns the corresponding message.
     *
     * @param board the board to evaluate (must not be {@code null})
     * @return one of the six possible outcome strings
     */
    static String evaluate(Board board) {
        int xCount = board.count('X');
        int oCount = board.count('0');

        // Rule 1 – illegal piece counts
        if (xCount < oCount || xCount > oCount + 1) {
            return "illegal";
        }

        boolean xWon = board.hasWin('X');
        boolean oWon = board.hasWin('0');

        // Rule 2 – both players cannot win simultaneously
        if (xWon && oWon) {
            return "illegal";
        }

        // Rule 3 – if X wins, the game must have exactly one more X than O
        if (xWon) {
            return (xCount == oCount + 1) ? "the first player won" : "illegal";
        }

        // Rule 4 – if O wins, the counts must be equal
        if (oWon) {
            return (xCount == oCount) ? "the second player won" : "illegal";
        }

        // Rule 5 – full board without a winner is a draw
        if (xCount + oCount == BOARD_SIZE * BOARD_SIZE) {
            return "draw";
        }

        // Rule 6 – otherwise indicate whose turn it is
        return (xCount == oCount) ? "first" : "second";
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;

/**
 * Validates a Tic‑Tac‑Toe board supplied on stdin and reports the game result.
 *
 * <p>Original code was heavily duplicated and mixed input handling with game logic.
 * This version separates concerns into small, well‑named methods, uses constants
 * for symbols and board size, and centralises validation rules.</p>
 */
public class TicTacToeValidator {

    /** Symbol used by the first player. */
    private static final char FIRST_PLAYER = 'X';

    /** Symbol used by the second player (represented by the character '0' in the input). */
    private static final char SECOND_PLAYER = '0';

    /** Board dimension – classic 3×3 Tic‑Tac‑Toe. */
    private static final int BOARD_SIZE = 3;

    public static void main(String[] args) throws IOException {
        // --------------------------------------------------------------------
        // 1. Read the board from standard input
        // --------------------------------------------------------------------
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(System.in))) {
            char[][] board = readBoard(reader);
            int countFirst  = countOccurrences(board, FIRST_PLAYER);
            int countSecond = countOccurrences(board, SECOND_PLAYER);

            boolean firstWon  = hasWon(board, FIRST_PLAYER);
            boolean secondWon = hasWon(board, SECOND_PLAYER);

            // --------------------------------------------------------------------
            // 2. Validate board state (illegal positions are rejected early)
            // --------------------------------------------------------------------
            if (!isValidBoard(countFirst, countSecond, firstWon, secondWon)) {
                System.out.println("illegal");
                return;
            }

            // --------------------------------------------------------------------
            // 3. Determine and print the appropriate outcome
            // --------------------------------------------------------------------
            if (firstWon) {
                System.out.println("the first player won");
            } else if (secondWon) {
                System.out.println("the second player won");
            } else if (countFirst + countSecond == BOARD_SIZE * BOARD_SIZE) {
                System.out.println("draw");
            } else {
                System.out.println(countFirst == countSecond ? "first" : "second");
            }
        }
    }

    /** Reads exactly three lines of length three and builds the board array. */
    private static char[][] readBoard(BufferedReader reader) throws IOException {
        char[][] board = new char[BOARD_SIZE][BOARD_SIZE];
        for (int i = 0; i < BOARD_SIZE; i++) {
            String line = reader.readLine();
            if (line == null) {
                throw new IOException("Unexpected end of input");
            }
            for (int j = 0; j < BOARD_SIZE; j++) {
                board[i][j] = line.charAt(j);
            }
        }
        return board;
    }

    /** Counts how many times {@code symbol} appears on the board. */
    private static int countOccurrences(char[][] board, char symbol) {
        int count = 0;
        for (char[] row : board) {
            for (char cell : row) {
                if (cell == symbol) {
                    count++;
                }
            }
        }
        return count;
    }

    /** Checks whether the given player has a winning line (row, column or diagonal). */
    private static boolean hasWon(char[][] board, char player) {
        // rows
        for (int i = 0; i < BOARD_SIZE; i++) {
            if (board[i][0] == player && board[i][1] == player && board[i][2] == player) {
                return true;
            }
        }
        // columns
        for (int j = 0; j < BOARD_SIZE; j++) {
            if (board[0][j] == player && board[1][j] == player && board[2][j] == player) {
                return true;
            }
        }
        // diagonals
        if (board[0][0] == player && board[1][1] == player && board[2][2] == player) {
            return true;
        }
        if (board[0][2] == player && board[1][1] == player && board[2][0] == player) {
            return true;
        }
        return false;
    }

    /**
     * Performs all legality checks required by the problem statement.
     *
     * <ul>
     *   <li>X count must be equal to O count or one greater.</li>
     *   <li>Both players cannot be winning simultaneously.</li>
     *   <li>If the first player wins, X count must be exactly one larger than O count.</li>
     *   <li>If the second player wins, the counts must be equal.</li>
     * </ul>
     */
    private static boolean isValidBoard(int xCount, int oCount, boolean firstWon, boolean secondWon) {
        // basic turn order validation
        if (!(xCount == oCount || xCount == oCount + 1)) {
            return false;
        }

        // both cannot win
        if (firstWon && secondWon) {
            return false;
        }

        // first player's win must respect turn order
        if (firstWon && xCount != oCount + 1) {
            return false;
        }

        // second player's win must respect turn order
        if (secondWon && xCount != oCount) {
            return false;
        }

        return true;
    }
}

