/**
 * Main entry point of the application.
 */
public class Main {

    private static final char EMPTY = '.';   // empty cell marker
    private static final char PLAYER_X = 'X'; // first player
    private static final char PLAYER_O = '0'; // second player

    public static void main(String[] args) {
        Game game = new Game();
        game.readBoard(System.in);
        String result = game.evaluate();
        System.out.println(result);
    }
