/**
 * Encapsulates the logic of reading a Tic‑Tac‑Toe board,
 * validating its state and determining the outcome.
 */
class Game {

    private static final int SIZE = 3;

    private final char[][] board = new char[SIZE][SIZE];
    private int countX;   // number of 'X' placed
    private int countO;   // number of '0' placed

    /**
     * Reads exactly three lines, each containing three characters,
     * from the supplied {@code InputStream}.
     *
     * @param source stream providing the board description
     * @throws IllegalArgumentException if an illegal character is encountered
     */
    void readBoard(InputStream source) {
        try (BufferedReader br = new BufferedReader(new InputStreamReader(source))) {
            int row = 0;
            String line;
            while (row < SIZE && (line = br.readLine()) != null) {
                for (int col = 0; col < SIZE; col++) {
                    char ch = line.charAt(col);
                    board[row][col] = ch;
                    if (ch == PLAYER_X) {
                        countX++;
                    } else if (ch == PLAYER_O) {
                        countO++;
                    } else if (ch != EMPTY) {
                        throw new IllegalArgumentException(
                                "Invalid character '" + ch + "' found in board description");
                    }
                }
                row++;
            }

            if (row != SIZE) {
                throw new IllegalArgumentException("Expected 3 lines of input, got " + row);
            }
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
    }

    /**
     * Evaluates the current board and returns a descriptive outcome.
     *
     * @return one of the predefined outcome strings
     */
    String evaluate() {
        // ---------- basic count validation ----------
        if (countX < countO || countX - countO > 1) {
            return "illegal";
        }

        boolean xWins = hasWon(PLAYER_X);
        boolean oWins = hasWon(PLAYER_O);

        // both players cannot win simultaneously
        if (xWins && oWins) {
            return "illegal";
        }

        // ---------- win checks ----------
        if (xWins) {
            // X can only win when it made the last move (countX == countO + 1)
            return countX == countO ? "illegal" : "the first player won";
        }
        if (oWins) {
            // O can only win when it made the last move (countX == countO)
            return countX != countO ? "illegal" : "the second player won";
        }

        // ---------- draw / next player ----------
        if (countX + countO == SIZE * SIZE) {
            return "draw";
        }
        return countX == countO ? "first" : "second";
    }

    /**
     * Checks whether the supplied player has a winning line
     * (row, column or diagonal) on the board.
     *
     * @param player the character representing the player ('X' or '0')
     * @return {@code true} if the player has a winning line
     */
    private boolean hasWon(char player) {
        // rows
        for (int i = 0; i < SIZE; i++) {
            if (board[0][i] == player && board[1][i] == player && board[2][i] == player) {
                return true;
            }
            if (board[i][0] == player && board[i][1] == player && board[i][2] == player) {
                return true;
            }
        }
        // diagonals
        return (board[0][0] == player && board[1][1] == player && board[2][2] == player) ||
               (board[0][2] == player && board[1][1] == player && board[2][0] == player);
    }
}

