/**
 * Solution for the classic “tic‑tac‑toe” (noughts‑and‑crosses) judge.
 *
 * <p>This version improves readability, maintainability and testability by:
 * <ul>
 *   <li>Extracting logical concerns into small, well‑named methods.</li>
 *   <li>Eliminating magic numbers and cryptic variable names.</li>
 *   <li>Grouping constants together.</li>
 *   <li>Using early returns to avoid deep nesting.</li>
 *   <li>Adding Javadoc comments that explain the intent.</li>
 * </ul>
 *
 * The algorithm follows exactly the same rules as the original code but is now
 * easier to understand and extend.
 */
public class Main implements Runnable {

    /** Input buffer – reused by {@link #next()} helpers. */
    private BufferedReader in;

    /** Output buffer – prints to console or a file depending on {@code fromConsole}. */
    private PrintWriter out;

    /** String tokenizer used to parse input tokens lazily. */
    private StringTokenizer tokenizer;

    /** Fixed name of the input‑output files when they are used. */
    private static final String INPUT_NAME = "A";

    /** When {@code true} the program reads from {@code System.in} and writes to {@code System.out}. */
    private static final boolean READ_FROM_CONSOLE = true;

    /** Board dimensions – kept as a constant for future extensions. */
    private static final int BOARD_SIZE = 3;

    /** Entry point – starts a new thread because the runner expects it. */
    public static void main(String[] args) {
        new Thread(new Main()).start();
    }

    /* --------------------------------------------------------------------- *
     *  Public API (called by Runner)                                          *
     * --------------------------------------------------------------------- */

    /** Reads three rows from the input, validates them and prints the game state. */
    @Override
    public void run() {
        try (closeQuietly(in); closeQuietly(out)) {
            initStreams();
            solve();
        } catch (Exception e) {
            e.printStackTrace();
            System.exit(-1);
        }
    }

    /** Core logic – parses the board, analyses its state and sends the result to the output. */
    private void solve() throws IOException {
        char[][] board = readBoard();
        String result = analyse(board);
        out.println(result);
    }

    /* --------------------------------------------------------------------- *
     *  Helper methods                                                          *
     * --------------------------------------------------------------------- */

    /** Reads exactly three lines of three characters each and returns the board. */
    private static char[][] readBoard() throws IOException {
        // The original code expects three tokens, each token being a 3‑character string.
        // We keep the same semantics but make the intention explicit.
        char[][] board = new char[BOARD_SIZE][];
        for (int r = 0; r < BOARD_SIZE; r++) {
            String line = nextToken();
            if (line == null || line.length() != BOARD_SIZE) {
                throw new IllegalArgumentException("Invalid board row.");
            }
            board[r] = line.toCharArray();
        }
        return board;
    }

    /** Main analysis routine – determines whether the board is illegal, a win,
     *  a draw or whose turn it is next. */
    private static String analyse(char[][] board) {
        // 1️⃣ Count pieces – illegal counts are caught early.
        Count counts = countPieces(board);
        if (!validPieceCount(counts)) {
            return "illegal";
        }

        // 2️⃣ Detect winning lines for both players.
        Outcome outcome = detectOutcome(board);

        // 3️⃣ Rules specific to winners.
        if (outcome.xWins) {
            return counts.x == counts.o + 1 ? "the first player won" : "illegal";
        }
        if (outcome.oWins) {
            return counts.x == counts.o ? "the second player won" : "illegal";
        }

        // 4️⃣ No winner – decide between draw and ongoing game.
        if (counts.total == BOARD_SIZE * BOARD_SIZE) {
            return "draw";
        }
        return counts.x == counts.o ? "first" : "second";
    }

    /** Counts how many 'X' and '0' characters are on the board. */
    private static Count countPieces(char[][] board) {
        int x = 0, o = 0;
        for (int r = 0; r < BOARD_SIZE; r++) {
            for (int c = 0; c < BOARD_SIZE; c++) {
                if (board[r][c] == 'X') {
                    x++;
                } else if (board[r][c] == '0') {
                    o++;
                }
            }
        }
        return new Count(x, o);
    }

    /** Checks if the numbers of X and O are compatible with the rules of tic‑tac‑toe. */
    private static boolean validPieceCount(Count c) {
        return (c.x == c.o || c.x == c.o + 1);
    }

    /** Detects whether X or O have a winning line, or both (illegal). */
    private static Outcome detectOutcome(char[][] board) {
        boolean xWins = hasThreeInLine(board, 'X');
        boolean oWins = hasThreeInLine(board, '0');

        // It is illegal for both players to have winning lines simultaneously.
        if (xWins && oWins) {
            // Force outcome to “illegal” later by setting wins flag.
            return new Outcome(false, true);
        }
        return new Outcome(xWins, oWins);
    }

    /** Scans rows, columns and both diagonals for a line consisting exclusively of
     *  the supplied player token. */
    private static boolean hasThreeInLine(char[][] board, char player) {
        // ---- rows ----
        for (int r = 0; r < BOARD_SIZE; r++) {
            if (allEqual(board[r], player)) {
                return true;
            }
        }
        // ---- columns ----
        for (int c = 0; c < BOARD_SIZE; c++) {
            if (allEqual(column(board, c), player)) {
                return true;
            }
        }
        // ---- main diagonal ----
        if (allEqual(mainDiagonal(board), player)) {
            return true;
        }
        // ---- anti‑diagonal ----
        if (allEqual(antiDiagonal(board), player)) {
            return true;
        }
        return false;
    }

    /** Helper that returns true if every element of {@code arr} equals {@code value}. */
    private static boolean allEqual(char[] arr, char value) {
        for (char ch : arr) {
            if (ch != value) {
                return false;
            }
        }
        return true;
    }

    /** Returns the r‑th column of the board as a freshly allocated array. */
    private static char[] column(char[][] board, int columnIndex) {
        char[] col = new char[BOARD_SIZE];
        for (int r = 0; r < BOARD_SIZE; r++) {
            col[r] = board[r][columnIndex];
        }
        return col;
    }

    /** Returns the main diagonal (top‑left to bottom‑right). */
    private static char[] mainDiagonal(char[][] board) {
        char[] diag = new char[BOARD_SIZE];
        for (int i = 0; i < BOARD_SIZE; i++) {
            diag[i] = board[i][i];
        }
        return diag;
    }

    /** Returns the anti‑diagonal (top‑right to bottom‑left). */
    private static char[] antiDiagonal(char[][] board) {
        char[] diag = new char[BOARD_SIZE];
        for (int i = 0; i < BOARD_SIZE; i++) {
            diag[i] = board[i][BOARD_SIZE - 1 - i];
        }
        return diag;
    }

    /** Simple holder for the result of {@link #detectOutcome(char[][])}. */
    private static final class Outcome {
        final boolean xWins;
        final boolean oWins;

        Outcome(boolean xWins, boolean oWins) {
            this.xWins = xWins;
            this.oWins = oWins;
        }
    }

    /** Simple DTO that stores the piece counts. */
    private static final class Count {
        final int x;
        final int o;
        final int total;

        Count(int x, int o) {
            this.x = x;
            this.o = o;
            this.total = x + o;
        }
    }

    /* --------------------------------------------------------------------- *
     *  I/O utilities (used by the original template)                         *
     * --------------------------------------------------------------------- */

    /** Initializes {@code in}, {@code out} and {@code tokenizer} according
     *  to the {@code READ_FROM_CONSOLE} flag. */
    private static void initStreams() throws IOException {
        if (!READ_FROM_CONSOLE) {
            // Files named "A.in" and "A.out" are used when not reading from console.
            System.setIn(new BufferedInputStream(new FileInputStream(INPUT_NAME + ".in")));
            System.setOut(new PrintStream(new BufferedOutputStream(new FileOutputStream(INPUT_NAME + ".out"))));
        }
        // Tokenizer is created lazily by {@link #hasNext()} and {@link #next()}.
    }

    /** Reads the next non‑empty token from the input stream. */
    private static String nextToken() throws IOException {
        while (true) {
            if (singletonTokenizer.hasMoreTokens()) {
                return singletonTokenizer.nextToken();
            }
            String line = System.in.readLine();
            if (line == null) {
                return null;
            }
            singletonTokenizer = new StringTokenizer(line);
        }
    }

    /** The global singleton used by the static I/O helpers. */
    private static StringTokenizer singletonTokenizer = new StringTokenizer();

    /** Utility to close a {@link Closeable} without throwing checked exceptions. */
    private static void closeQuietly(Closeable c) {
        if (c != null) {
            try {
                c.close();
            } catch (IOException ignored) {
                // ignore – this mimics the behaviour of the original template.
            }
        }
    }

    /* --------------------------------------------------------------------- *
     *  Tokenizer wrappers (replicates original API)                           *
     * --------------------------------------------------------------------- */

    /** Returns true if at least one token is available. */
    private boolean hasNext() throws IOException {
        while (!singletonTokenizer.hasMoreTokens()) {
            String line = nextLine();
            if (line == null) {
                return false;
            }
            singletonTokenizer = new StringTokenizer(line);
        }
        return true;
    }

    /** Reads the next line from {@code System.in}. */
    private static String nextLine() throws IOException {
        return singletonTokenizer.hasMoreTokens() ? null : System.in.readLine();
    }

    /** Returns the next token as a {@link String}. */
    private static String next() throws IOException {
        return singletonTokenizer.nextToken();
    }

    /** Returns the next token as an {@link Integer}. */
    private static int nextInt() throws IOException {
        return Integer.parseInt(next());
    }

    /** Returns the next token as a {@link Long}. */
    private static long nextLong() throws IOException {
        return Long.parseLong(next());
    }

    /** Returns the next token as a {@link Double}. */
    private static double nextDouble() throws IOException {
        return Double.parseDouble(next());
    }

    /** Returns the next token as a {@link BigInteger}. */
    private static BigInteger nextBigInteger() throws IOException {
        return new BigInteger(next());
    }
}

import java.io.*;
import java.util.StringTokenizer;

/**
 * Entry‑point for the tic‑tac‑toe board evaluator.
 * <p>
 * The program reads a 3×3 board from standard input, validates the game state,
 * determines the result and prints it.
 * </p>
 */
public class Solution implements Runnable {

    // -----------------------------------------------------------------------
    // I/O fields
    // -----------------------------------------------------------------------
    private BufferedReader in;
    private PrintWriter out;
    private StringTokenizer st;

    // -----------------------------------------------------------------------
    // Constants
    // -----------------------------------------------------------------------
    private static final char EMPTY = '.';

    /** Starts a new thread that runs the {@link Runnable}. */
    public static void main(String[] args) {
        new Thread(new Solution()).start();
    }

    @Override
    public void run() {
        try {
            in = new BufferedReader(new InputStreamReader(System.in));
            out = new PrintWriter(System.out, true);
            solve();
        } catch (IOException e) {
            e.printStackTrace();
        } finally {
            out.flush();
        }
    }

    /** Main logic: reads the board, validates it and prints the outcome. */
    private void solve() throws IOException {
        char[][] board = new char[3][3];
        readBoard(board);

        int xCount = count(board, 'X');
        int oCount = count(board, '0');

        if (!isValidState(xCount, oCount)) {
            out.println("illegal");
            return;
        }

        char winner = evaluate(board);
        if (winner == EMPTY) {
            if (xCount + oCount == 9) {
                out.println("draw");
            } else {
                out.println(xCount == oCount ? "first" : "second");
            }
        } else {
            if ((winner == 'X' && isXWinValid(xCount, oCount)) ||
                (winner == '0' && !isXWinValid(xCount, oCount))) {
                out.println(winner == 'X' ?
                        "the first player won" : "the second player won");
            } else {
                out.println("illegal");
            }
        }
    }

    /** Counts how many times a given symbol appears on the board. */
    private int count(char[][] board, char symbol) {
        int cnt = 0;
        for (int r = 0; r < 3; ++r) {
            for (int c = 0; c < 3; ++c) {
                if (board[r][c] == symbol) {
                    ++cnt;
                }
            }
        }
        return cnt;
    }

    /** Checks whether the turn order (X starts) is respected. */
    private boolean isValidState(int x, int o) {
        return (x == o) || (x == o + 1);
    }

    /** Determines the winning symbol ('X', '0' or {@code EMPTY} if none). */
    private char evaluate(char[][] board) {
        // rows
        for (int r = 0; r < 3; ++r) {
            if (isThreeInLine(board[r][0], board[r][1], board[r][2])) {
                return board[r][0];
            }
        }
        // columns
        for (int c = 0; c < 3; ++c) {
            if (isThreeInLine(board[0][c], board[1][c], board[2][c])) {
                return board[0][c];
            }
        }
        // diagonals
        if (isThreeInLine(board[0][0], board[1][1], board[2][2]) ||
            isThreeInLine(board[0][2], board[1][1], board[2][0])) {
            return board[0][0];
        }
        return EMPTY;
    }

    /** Helper that verifies three cells contain the same non‑empty symbol. */
    private boolean isThreeInLine(char a, char b, char c) {
        return a != EMPTY && a == b && a == c;
    }

    /** Checks if a win for 'X' is possible with the current move counts. */
    private boolean isXWinValid(int x, int o) {
        return x == o + 1;
    }

    /** Reads three tokens (rows) from the input and fills the board array. */
    private void readBoard(char[][] board) throws IOException {
        for (int row = 0; row < 3; ++row) {
            String token = nextToken();               // each token is a row of three chars
            for (int col = 0; col < 3; ++col) {
                board[row][col] = token.charAt(col);
            }
        }
    }

    /** Lazily creates a new {@link StringTokenizer} when needed and returns the next token. */
    private String nextToken() throws IOException {
        while (st == null || !st.hasMoreTokens()) {
            st = new StringTokenizer(in.readLine());
        }
        return st.nextToken();
    }
}

import java.io.*;
import java.util.*;

public class Main {

    /* Constants match the original input format */
    private static final char EMPTY = '.';
    private static final char PLAYER_X = 'X';
    private static final char PLAYER_O = '0';   // original used '0' instead of 'O'

    public static void main(String[] args) throws Exception {
        // Read exactly three lines from stdin; any deviation is illegal
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in))) {
            String[] rows = br.lines().limit(3).toArray(String[]::new);
            if (rows.length != 3) {
                System.out.println("illegal");
                return;
            }

            // Build a 3×3 char board
            char[][] board = new char[3][3];
            for (int i = 0; i < 3; i++) {
                if (rows[i].length() != 3) {
                    System.out.println("illegal");
                    return;
                }
                for (int j = 0; j < 3; j++) {
                    board[i][j] = rows[i].charAt(j);
                }
            }

            // Analyse the board and print the required message
            GameState state = analyze(board);
            state.print();
        }
    }

    /** Analyses the board and returns the logical outcome of the game. */
    private static GameState analyze(char[][] board) {
        int xCount = 0, oCount = 0, dotCount = 0;

        // Count pieces and validate characters
        for (char[] row : board) {
            for (char c : row) {
                switch (c) {
                    case PLAYER_X -> xCount++;
                    case PLAYER_O -> oCount++;
                    case EMPTY -> dotCount++;
                    default -> {
                        // Illegal character found
                        return GameState.ILLEGAL;
                    }
                }
            }
        }

        boolean xWins = hasWon(board, PLAYER_X);
        boolean oWins = hasWon(board, PLAYER_O);

        // Inconsistent win conditions → illegal
        if (xWins && oWins) {
            return GameState.ILLEGAL;
        }

        // Win‑related illegal counts
        if (xWins && xCount != oCount + 1) {
            return GameState.ILLEGAL;
        }
        if (oWins && xCount != oCount) {
            return GameState.ILLEGAL;
        }

        // Global move‑count rule violations
        if (xCount > oCount + 1 || oCount > xCount) {
            return GameState.ILLEGAL;
        }

        boolean nextIsX   = xCount > oCount;   // whose turn is next
        boolean boardFull = dotCount == 0;     // no empty squares left

        // Determine final outcome
        if (xWins) {
            return GameState.FIRST_PLAYER_WON;
        }
        if (oWins) {
            return GameState.SECOND_PLAYER_WON;
        }
        if (boardFull) {
            return GameState.DRAW;
        }
        return nextIsX ? GameState.FIRST_TURN : GameState.SECOND_TURN;
    }

    /** Checks whether the given player has a winning line on the board. */
    private static boolean hasWon(char[][] board, char player) {
        // rows
        for (int i = 0; i < 3; i++) {
            if (board[i][0] == player && board[i][1] == player && board[i][2] == player) {
                return true;
            }
        }
        // columns
        for (int j = 0; j < 3; j++) {
            if (board[0][j] == player && board[1][j] == player && board[2][j] == player) {
                return true;
            }
        }
        // diagonals
        if (board[0][0] == player && board[1][1] == player && board[2][2] == player) {
            return true;
        }
        if (board[0][2] == player && board[1][1] == player && board[2][0] == player) {
            return true;
        }
        return false;
    }

    /** Enum that encapsulates every possible textual output of the program. */
    private enum GameState {
        ILLEGAL {
            @Override public void print() { System.out.println("illegal"); }
        },
        FIRST_PLAYER_WON {
            @Override public void print() { System.out.println("the first player won"); }
        },
        SECOND_PLAYER_WON {
            @Override public void print() { System.out.println("the second player won"); }
        },
        DRAW {
            @Override public void print() { System.out.println("draw"); }
        },
        FIRST_TURN {
            @Override public void print() { System.out.println("first"); }
        },
        SECOND_TURN {
            @Override public void print() { System.out.println("second"); }
        };

        /** Sub‑classes provide the exact message to print. */
        abstract void print();
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;

/**
 * Refactored Tic‑Tac‑Toe validator and outcome printer.
 *
 * <p>
 * The program reads a 3×3 board from standard input (three lines, each
 * containing exactly three characters: 'X', 'O' or any other character for an
 * empty cell). It then determines the current state of the game and prints
 * one of the following messages:
 * <ul>
 *   <li>"the first player won"</li>
 *   <li>"the second player won"</li>
 *   <li>"draw"</li>
 *   <li>"first"</li>
 *   <li>"second"</li>
 *   <li>"illegal"</li>
 * </ul>
 * The logic follows the same rules as the original program but is now
 * organised into small, single‑purpose methods with expressive names and
 * without duplicated code.
 * </p>
 */
public class TicTacToe {

    private static final int SIZE = 3;

    private static final char EMPTY = ' ';
    private static final char PLAYER_X = 'X';
    private static final char PLAYER_O = 'O';

    /** 2‑D representation of the board. */
    private final char[][] board = new char[SIZE][SIZE];

    /** Counters for how many X and O have been placed. */
    private int countX;
    private int countO;

    /** Entry point – reads the board and prints the result. */
    public static void main(String[] args) throws IOException {
        TicTacToe game = new TicTacToe();
        game.readBoard();
        game.evaluateAndPrint();
    }

    /** Reads three lines from {@code System.in}, each expected to contain three characters. */
    private void readBoard() throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        for (int row = 0; row < SIZE; row++) {
            String line = br.readLine();
            if (line == null) {
                throw new IOException("Unexpected end of input");
            }
            // Use the first three characters of the line; ignore any extras.
            for (int col = 0; col < SIZE; col++) {
                char cell = line.charAt(col);
                board[row][col] = cell;
                handleCell(cell);
            }
        }
    }

    /** Updates the X/O counters when a cell is processed. */
    private void handleCell(char cell) {
        if (cell == PLAYER_X) {
            countX++;
        } else if (cell == PLAYER_O) {
            countO++;
        }
        // All other characters are treated as empty cells and require no counting.
    }

    /** Determines the current game state and prints the corresponding message. */
    private void evaluateAndPrint() {
        if (!isLegalBoard()) {
            System.out.println("illegal");
            return;
        }

        boolean xWon = hasWon(PLAYER_X);
        boolean oWon = hasWon(PLAYER_O);

        // According to the rules both players cannot win simultaneously;
        // this situation is already excluded by {@link #isLegalBoard()}.
        if (xWon) {
            System.out.println("the first player won");
            return;
        }
        if (oWon) {
            System.out.println("the second player won");
            return;
        }

        // Full board without a winner → draw.
        if (countX + countO == SIZE * SIZE) {
            System.out.println("draw");
            return;
        }

        // Next turn: first player moves when X and O counts are equal,
        // otherwise the second player moves.
        System.out.println(countX == countO ? "first" : "second");
    }

    /** Checks whether the current board configuration obeys all game rules. */
    private boolean isLegalBoard() {
        if (!validPieceCount()) {
            return false;
        }

        boolean xWon = hasWon(PLAYER_X);
        boolean oWon = hasWon(PLAYER_O);

        // Both players cannot have winning lines.
        if (xWon && oWon) {
            return false;
        }

        // Winning conditions impose additional constraints on the piece counts.
        if (xWon && countX != countO + 1) {
            return false;
        }
        if (oWon && countX != countO) {
            return false;
        }

        return true;
    }

    /** Validates that the number of X's and O's follows the turn‑taking rules. */
    private boolean validPieceCount() {
        return (countX == countO) || (countX == countO + 1);
    }

    /** Scans rows, columns and diagonals to see if the given player has a winning line. */
    private boolean hasWon(char player) {
        // Check rows.
        for (int i = 0; i < SIZE; i++) {
            if (board[i][0] == player && board[i][1] == player && board[i][2] == player) {
                return true;
            }
        }
        // Check columns.
        for (int j = 0; j < SIZE; j++) {
            if (board[0][j] == player && board[1][j] == player && board[2][j] == player) {
                return true;
            }
        }
        // Check main diagonal.
        if (board[0][0] == player && board[1][1] == player && board[2][2] == player) {
            return true;
        }
        // Check anti‑diagonal.
        if (board[0][2] == player && board[1][1] == player && board[2][0] == player) {
            return true;
        }
        return false;
    }
}

import java.util.Scanner;

/**
 * Reads an endless stream of 3×3 board configurations (each line is a
 * three‑character string) and, for every board, decides which player
 * should move next, or reports an illegal board / win / draw.
 *
 * The logic is the same as the original program but the code is
 * organized into small, dedicated methods and uses meaningful names.
 */
public class Main {

    private static final char EMPTY = '.';
    private static final char X = 'X';
    private static final char O = 'O';

    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            while (scanner.hasNext()) {
                String[] board = readBoard(scanner);
                evaluate(board);
            }
        }
    }

    /** Reads three consecutive tokens from the scanner – each token is a row. */
    private static String[] readBoard(Scanner scanner) {
        String[] rows = new String[3];
        for (int i = 0; i < 3; i++) {
            rows[i] = scanner.next();
        }
        return rows;
    }

    /** Main driver that decides what to print for a single board. */
    private static void evaluate(String[] board) {
        int xCount = countOccurrences(board, X);
        int oCount = countOccurrences(board, O);
        int emptyCount = countOccurrences(board, EMPTY);

        boolean xWins  = hasWon(board, X);
        boolean oWins  = hasWon(board, O);

        printIllegalIfNecessary(xCount, oCount, xWins, oWins);

        if (xWins) {
            System.out.println("the first player won");
            return;
        }
        if (oWins) {
            System.out.println("the second player won");
            return;
        }
        if (emptyCount == 0) {
            System.out.println("draw");
            return;
        }
        System.out.println(xCount > oCount ? "second" : "first");
    }

    /** Prints “illegal” when the board violates the game rules. */
    private static void printIllegalIfNecessary(
            int xCount, int oCount, boolean xWins, boolean oWins) {

        boolean illegal = (xCount < oCount)                     // O cannot have more moves than X
                         || (xCount > oCount + 1)                // X cannot have more than one move ahead
                         || (xWins && oWins)                     // both cannot win
                         || (xWins && xCount != oCount + 1)     // X can only win on its own turn
                         || (oWins && xCount > oCount);          // O can only win on its own turn

        if (illegal) {
            System.out.println("illegal");
        }
    }

    /** Counts how many times a given character appears on the board. */
    private static int countOccurrences(String[] board, char target) {
        int cnt = 0;
        for (String row : board) {
            for (int col = 0; col < 3; col++) {
                if (row.charAt(col) == target) {
                    cnt++;
                }
            }
        }
        return cnt;
    }

    /** Returns true if the supplied player has a winning line on the board. */
    private static boolean hasWon(String[] board, char player) {
        // rows
        for (int i = 0; i < 3; i++) {
            if (rowMatches(board[i], player)) {
                return true;
            }
        }
        // columns
        for (int col = 0; col < 3; col++) {
            if (columnMatches(board, col, player)) {
                return true;
            }
        }
        // diagonals
        if (diagonal1Matches(board, player) || diagonal2Matches(board, player)) {
            return true;
        }
        return false;
    }

    private static boolean rowMatches(String row, char player) {
        return row.charAt(0) == player && row.charAt(1) == player && row.charAt(2) == player;
    }

    private static boolean columnMatches(String[] board, int columnIndex, char player) {
        return board[0].charAt(columnIndex) == player &&
               board[1].charAt(columnIndex) == player &&
               board[2].charAt(columnIndex) == player;
    }

    private static boolean diagonal1Matches(String[] board, char player) {
        return board[0].charAt(0) == player &&
               board[1].charAt(1) == player &&
               board[2].charAt(2) == player;
    }

    private static boolean diagonal2Matches(String[] board, char player) {
        return board[0].charAt(2) == player &&
               board[1].charAt(1) == player &&
               board[2].charAt(0) == player;
    }
}

import java.io.*;
import java.util.StringTokenizer;

/**
 * Entry point of the program.
 * Reads the board from standard input, validates it and prints the result.
 */
public class Main {

    /** Size of the Tic‑Tac‑Toe board */
    private static final int BOARD_SIZE = 3;

    public static void main(String[] args) {
        InputReader reader = new InputReader(System.in);
        PrintWriter writer = new PrintWriter(System.out);

        // The problem guarantees a single test case, but the method name
        // suggests it could handle more – we keep the same contract.
        new GameSolver().solve(1, reader, writer);

        writer.flush();
        writer.close();
    }
}

/**
 * Utility class that contains the core game‑logic.
 * It is separated from I/O handling to make the algorithm easier to test
 * and to keep the `main` method thin.
 */
class GameSolver {

    /** Player symbols used throughout the program */
    private enum Symbol {
        EMPTY('.'), FIRST('X'), SECOND('0');

        private final char representation;

        Symbol(char representation) {
            this.representation = representation;
        }

        char get() {
            return representation;
        }
    }

    /** Number of symbols placed on the board by each player */
    private static int count( char[][] board, Symbol symbol ) {
        int cnt = 0;
        for (int row = 0; row < BOARD_SIZE; ++row) {
            for (int col = 0; col < BOARD_SIZE; ++col) {
                if (board[row][col] == symbol.get()) {
                    cnt++;
                }
            }
        }
        return cnt;
    }

    /** Returns {@code true} if the given symbol has a winning line. */
    private static boolean hasWon( char[][] board, Symbol symbol ) {
        // rows
        for (int r = 0; r < BOARD_SIZE; ++r) {
            if (allEqual(board[r][0], board[r][1], board[r][2], symbol)) {
                return true;
            }
        }
        // columns
        for (int c = 0; c < BOARD_SIZE; ++c) {
            if (allEqual(board[0][c], board[1][c], board[2][c], symbol)) {
                return true;
            }
        }
        // diagonals
        if (allEqual(board[0][0], board[1][1], board[2][2], symbol)) {
            return true;
        }
        if (allEqual(board[0][2], board[1][1], board[2][0], symbol)) {
            return true;
        }
        return false;
    }

    /** Simple helper that checks whether all three values are equal to the expected symbol. */
    private static boolean allEqual( char a, char b, char c, Symbol symbol ) {
        return a == symbol.get() && b == symbol.get() && c == symbol.get();
    }

    /**
     * Validates the board state and prints the result.
     *
     * @param testNumber dummy – kept for compatibility with the original signature
     * @param in         input reader
     * @param out        output writer
     */
    public void solve(int testNumber, InputReader in, PrintWriter out) {
        // ----- read board --------------------------------------------------
        char[][] board = new char[BOARD_SIZE][BOARD_SIZE];
        for (int i = 0; i < BOARD_SIZE; ++i) {
            String line = in.next();
            if (line.length() != BOARD_SIZE) {
                illegal(out);
                return;
            }
            for (int j = 0; j < BOARD_SIZE; ++j) {
                board[i][j] = line.charAt(j);
            }
        }

        // ----- count moves -------------------------------------------------
        int firstMoves  = count(board, Symbol.FIRST);
        int secondMoves = count(board, Symbol.SECOND);

        // ----- basic illegal state checks ----------------------------------
        boolean illegalState = false;

        // X must not be fewer than O and cannot exceed O by more than one
        if (firstMoves < secondMoves || firstMoves > secondMoves + 1) {
            illegalState = true;
        }

        // both players cannot win
        boolean firstWon  = hasWon(board, Symbol.FIRST);
        boolean secondWon = hasWon(board, Symbol.SECOND);
        if (firstWon && secondWon) {
            illegalState = true;
        }

        // if O wins, the move counts must be equal (otherwise X played one extra turn)
        if (secondWon && firstMoves != secondMoves) {
            illegalState = true;
        }

        // if X wins, the move counts must differ by exactly one
        if (firstWon && firstMoves != secondMoves + 1) {
            illegalState = true;
        }

        // ----- produce result -----------------------------------------------
        if (illegalState) {
            out.println("illegal");
            return;
        }

        if (firstWon) {
            out.println("the first player won");
        } else if (secondWon) {
            out.println("the second player won");
        } else if (firstMoves + secondMoves == BOARD_SIZE * BOARD_SIZE) {
            out.println("draw");
        } else {
            // No winner yet – decide which player must move next
            out.println(firstMoves == secondMoves ? "first" : "second");
        }
    }

    /** Helper that prints “illegal” and short‑circuits the current solve call. */
    private void illegal(PrintWriter out) {
        out.println("illegal");
    }
}

