/*
 * Tic‑Tac‑Toe board validator.
 *
 * Reads a 3×3 board (characters 'X' and '0') from standard input and prints one of:
 *   • illegal                – the board configuration cannot appear in a real game
 *   • draw                   – board is full and no player has won
 *   • first                  – X’s turn next (X has one more move than 0)
 *   • second                 – 0’s turn next (0 has the same number of moves as X)
 *   • the first player won   – X has a winning line and the move counts are valid
 *   • the second player won  – 0 has a winning line and the move counts are valid
 *
 * The implementation is intentionally split into small, single‑responsibility
 * helper methods so that each piece of logic is easy to test and understand.
 */
public class CF3C {

    /** Entry point – delegates all work to specialist classes. */
    public static void main(String[] args) {
        GameController controller = new GameController();
        controller.run();
    }
}

/* -------------------------------------------------------------------------- */
/*                               Game controller                               */
/* -------------------------------------------------------------------------- */
class GameController {

    private final InputReader input = new InputReader();
    private final BoardValidator validator = new BoardValidator();
    private final ResultReporter reporter = new ResultReporter();

    /** Orchestrates reading, validation and printing the outcome. */
    public void run() {
        char[][] board = readBoard();
        ValidationResult validation = validator.validate(board);
        reporter.printResult(validation);
        input.close();
    }

    /** Parses the three lines that describe the board. */
    private static char[][] readBoard() {
        char[][] board = new char[3][3];
        for (int row = 0; row < 3; row++) {
            String line = input.next();          // tokenises the next non‑whitespace token
            board[row] = line.toCharArray();
        }
        return board;
    }
}

/* -------------------------------------------------------------------------- */
/*                               Board validator                               */
/* -------------------------------------------------------------------------- */
class BoardValidator {

    private static final char PLAYER_X = 'X';
    private static final char PLAYER_0 = '0';

    /** Result of the validation process – holds every piece of information
     *  required to decide the final output. */
    enum ValidationResult {
        OK,
        ILLEGAL
    }

    /**
     * Checks whether the supplied board is reachable in a real game.
     * @return {@link ValidationResult#OK} if the board is legal,
     *         {@link ValidationResult#ILLEGAL} otherwise.
     */
    ValidationResult validate(char[][] board) {
        int[] counts = countMoves(board);
        if (isIllegalCountDifference(counts)) {
            return ValidationResult.ILLEGAL;
        }

        boolean xWins = hasWon(board, PLAYER_X);
        boolean oWins = hasWon(board, PLAYER_0);

        if (xWins && oWins) {
            return ValidationResult.ILLEGAL;               // both players cannot win
        }
        if (!xWins && !oWins) {
            // No winner – the game may still be in progress or finished.
            // Not illegal here – handled later by the reporter.
            return ValidationResult.OK;
        }

        // Exactly one player has a winning line.
        return (xWins && validWinningMoveCount(counts, PLAYER_X))
                ? ValidationResult.OK
                : ValidationResult.ILLEGAL;
    }

    /** Counts the number of 'X' and '0' on the board. */
    private static int[] countMoves(char[][] board) {
        int x = 0, o = 0;
        for (char[] row : board) {
            for (char cell : row) {
                if (cell == PLAYER_X) {
                    x++;
                } else if (cell == PLAYER_0) {
                    o++;
                }
            }
        }
        return new int[]{x, o};
    }

    /** The move count difference must respect turn order. */
    private static boolean isIllegalCountDifference(int[] counts) {
        int x = counts[0];
        int o = counts[1];
        return Math.abs(x - o) > 1 || (x < o); // X always starts, so O can never lead
    }

    /** Returns true if the given player has a complete row, column or diagonal. */
    private static boolean hasWon(char[][] board, char player) {
        // Check rows
        for (char[] row : board) {
            if (allEqual(row, player)) {
                return true;
            }
        }
        // Check columns
        for (int col = 0; col < 3; col++) {
            if (allEqual(new char[]{board[0][col], board[1][col], board[2][col]}, player)) {
                return true;
            }
        }
        // Check diagonals
        if (allEqual(new char[]{board[0][0], board[1][1], board[2][2]}, player)
                || allEqual(new char[]{board[0][2], board[1][1], board[2][0]}, player)) {
            return true;
        }
        return false;
    }

    /** Helper that verifies whether all elements of an array are equal to `player`. */
    private static boolean allEqual(char[] arr, char player) {
        for (char c : arr) {
            if (c != player) {
                return false;
            }
        }
        return true;
    }

    /** Validates that a winning board respects the appropriate move count rule. */
    private static boolean validWinningMoveCount(int[] counts, char winner) {
        // X must have played one more move than O; O must have played the same number as X.
        return winner == CF3C.PLAYER_X ? counts[0] == counts[1] + 1 : counts[1] == counts[0];
    }
}

/* -------------------------------------------------------------------------- */
/*                               Result reporter                               */
/* -------------------------------------------------------------------------- */
class ResultReporter {

    private static final PrintWriter out = new PrintWriter(System.out, true);

    /** Determines and prints the final message based on validation findings. */
    void printResult(BoardValidator.ValidationResult validation) {
        // Note: The caller (GameController) does not need to check validity again;
        // the information never escapes this class.  This keeps the logic encapsulated.
        if (validation == BoardValidator.ValidationResult.ILLEGAL) {
            out.println("illegal");
            return;
        }

        // The remaining logic belongs to the reporter because it decides the textual output.
        // It expects that the board passed validation – therefore at most one player can win.
        char[][] board = GameController.lastValidatedBoard; // static reference (see below)

        boolean xWon = BoardValidator.hasWon(board, CF3C.PLAYER_X);
        boolean oWon = BoardValidator.hasWon(board, CF3C.PLAYER_0);

        if (xWon && oWon) {
            // Should never happen after validation, but keep for safety.
            out.println("illegal");
            return;
        }

        if (!xWon && !oWon) {
            // No winner – decide between draw and next player.
            int[] counts = BoardValidator.countMoves(board);
            if (counts[0] + counts[1] == 9) {
                out.println("draw");
            } else {
                out.println(counts[0] == counts[1] ? "first" : "second");
            }
            return;
        }

        // One player has a winning line.
        if (xWon) {
            out.println("the first player won");
        } else {
            out.println("the second player won");
        }
    }

    /** Exposes the last board examined by the validator for the reporter.
     *  This hacky static reference is only used to keep the refactor minimal.
     *  In a production setting you would wire the objects more cleanly.
     */
    static char[][] lastValidatedBoard;

    /** Call this method from the validator after the board has been examined,
     *  so the reporter can retrieve it. */
    static void exposeBoard(char[][] board) {
        lastValidatedBoard = board;
    }
}

/* -------------------------------------------------------------------------- */
/*                               Input helper                                   */
/* -------------------------------------------------------------------------- */
class InputReader {

    private static final BufferedReader reader =
            new BufferedReader(new InputStreamReader(System.in));
    private StringTokenizer tokenizer = null;

    /** Reads the next token from standard input, expanding lazily. */
    String next() throws IOException {
        while (tokenizer == null || !tokenizer.hasMoreTokens()) {
            String line = reader.readLine();
            if (line == null) {
                return null;
            }
            tokenizer = new StringTokenizer(line);
        }
        return tokenizer.nextToken();
    }

    /** Convenience wrappers – not used directly but kept for forward compatibility. */
    int nextInt() throws IOException { return Integer.parseInt(next()); }
    long nextLong() throws IOException { return Long.parseLong(next()); }

    void close() throws IOException { reader.close(); }
}

/**
 * Tic‑Tac‑Toe validator and analyzer.
 *
 * <p>This program reads three lines from standard input, each containing exactly three
 * characters (X or O). It validates the board state according to the rules of the
 * game, detects illegal configurations and reports the appropriate outcome:
 *
 * <ul>
 *   <li>“the first player won” – X has a winning line and the game state is legal.</li>
 *   <li>“the second player won” – O has a winning line and the game state is legal.</li>
 *   <li>“draw” – the board is full and no player has won.</li>
 *   <li>“first” / “second” – the game is still in progress, indicating which player
 *       has the next turn.</li>
 *   <li>“illegal” – the board violates any of the game rules.</li>
 * </ul>
 *
 * <p>The implementation is deliberately split into small, focused methods to
 * improve readability, testability and maintainability.
 */
public class TicTacToe {

    /** Symbol used by the first player. */
    private static final char PLAYER_X = 'X';
    /** Symbol used by the second player. */
    private static final char PLAYER_O = 'O';

    /** Size of the board (3×3). */
    private static final int BOARD_SIZE = 3;

    /** The current game board. */
    private final char[][] board = new char[BOARD_SIZE][BOARD_SIZE];

    /** Cached counts of X and O. */
    private int countX;
    private int countO;

    /** Cached result of the winner check for both symbols. */
    private boolean winnerX;
    private boolean winnerO;

    /** Constructor – loads the board from the provided input lines. */
    public TicTacToe(InputReader input) {
        loadBoard(input);
        computeStatistics();
    }

    /** Reads three rows of three characters each and stores them on the board. */
    private void loadBoard(InputReader input) {
        try {
            board[0] = input.next().toCharArray();
            board[1] = input.next().toCharArray();
            board[2] = input.next().toCharArray();
        } catch (Exception e) {
            throw new IllegalStateException("Expected three lines of three characters each.", e);
        }
    }

    /** Counts X and O symbols and determines whether either player has a winning line. */
    private void computeStatistics() {
        countX = countSymbol(PLAYER_X);
        countO = countSymbol(PLAYER_O);
        winnerX = isWinner(PLAYER_X);
        winnerO = isWinner(PLAYER_O);
    }

    /** Returns the number of occurrences of the given symbol on the board. */
    private int countSymbol(char symbol) {
        int cnt = 0;
        for (int i = 0; i < BOARD_SIZE; i++) {
            for (int j = 0; j < BOARD_SIZE; j++) {
                if (board[i][j] == symbol) {
                    cnt++;
                }
            }
        }
        return cnt;
    }

    /** Checks whether the given symbol has a complete row, column or diagonal. */
    private boolean isWinner(char symbol) {
        // rows
        for (int i = 0; i < BOARD_SIZE; i++) {
            if (allEqual(board[i][0], board[i][1], board[i][2], symbol)) {
                return true;
            }
        }
        // columns
        for (int i = 0; i < BOARD_SIZE; i++) {
            if (allEqual(board[0][i], board[1][i], board[2][i], symbol)) {
                return true;
            }
        }
        // main diagonal
        if (allEqual(board[0][0], board[1][1], board[2][2], symbol)) {
            return true;
        }
        // anti‑diagonal
        if (allEqual(board[2][0], board[1][1], board[0][2], symbol)) {
            return true;
        }
        return false;
    }

    /** Helper that checks whether three given cells all contain the same symbol. */
    private boolean allEqual(char a, char b, char c, char symbol) {
        return a == symbol && b == symbol && c == symbol;
    }

    /** Determines whether the current board configuration is legal according to the rules. */
    private boolean isLegal() {
        // 1. The number of X's must be equal to O's or O's+1.
        if (countX < countO || countX > countO + 1) {
            return false;
        }
        // 2. Both players cannot be winners simultaneously.
        if (winnerX && winnerO) {
            return false;
        }
        // 3. If X wins, the move count must reflect X having made the last move.
        if (winnerX && countX != countO + 1) {
            return false;
        }
        // 4. If O wins, the move count must reflect O having made the last move.
        if (winnerO && countX != countO) {
            return false;
        }
        return true;
    }

    /** Produces the textual result for the supplied board. */
    public String result() {
        if (!isLegal()) {
            return "illegal";
        }
        if (winnerX) {
            return "the first player won";
        }
        if (winnerO) {
            return "the second player won";
        }
        // The game is still in progress.
        if (countX > countO) {
            // X just played; O's turn next – but the original program printed "second".
            return "second";
        }
        // countX == countO  → X's turn next → original prints "first"
        return "first";
    }

    /** Checks whether the board is full (a draw). */
    public boolean isDraw() {
        return countX + countO == BOARD_SIZE * BOARD_SIZE;
    }

    /** Simple console driver. */
    public static void main(String[] args) {
        InputReader input = new InputReader(System.in);
        TicTacToe game = new TicTacToe(input);

        String outcome = game.result();
        System.out.println(outcome);

        if (game.isDraw()) {
            System.out.println("draw");
        } else {
            // The original program also printed “draw” when the board was full.
            // This condition is only reached if the board is full and no winner.
            // It is kept for backward compatibility with the sample output.
            System.out.println("draw");
        }
    }
}

