import java.io.BufferedReader;
import java.io.BufferedWriter;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.OutputStreamWriter;

/**
 * Maintainable Tic‑Tac‑Toe validator.
 *
 * <p>The program reads a 3×3 board from <code>stdin</code>. The board is described by
 * nine characters, one per move, separated by blank lines between rows
 * (exactly the same format the original program expected). Characters are
 * {@code 'X'}, {@code '0'} (the digit zero) or any other character which is
 * treated as an empty cell.</p>
 *
 * <p>After validation the program prints one of the following messages:</p>
 * <ul>
 *   <li><code>first</code> – the first player (X) can make the next legal move,
 *       i.e. the game is not finished and the move counts are correct.</li>
 *   <li><code>second</code> – analogous for the second player (0).</li>
 *   <li><code>draw</code> – board is full and nobody has won.</li>
 *   <li><code>the first player won</code> – X has a winning line and the
 *       move counts are consistent with the winner.</li>
 *   <li><code>the second player won</code> – 0 has a winning line and the
 *       move counts are consistent with the winner.</li>
 *   <li><code>illegal</code> – any rule violation (illegal board state,
 *       both players winning, wrong turn, etc.).</li>
 * </ul>
 *
 * <p>All resources are closed with try‑with‑resources, and the logic is split
 * into small, well‑named methods to make the code easy to test and maintain.</p>
 */
public final class TicTacToe {

    /** Player symbols used by the game. */
    private enum Symbol {
        X('X'), O('0'), EMPTY('.');

        private final char value;

        Symbol(char value) {
            this.value = value;
        }

        static Symbol fromChar(char c) {
            switch (c) {
                case 'X': return X;
                case '0': return O;
                default:  return EMPTY;
            }
        }

        char getChar() {
            return value;
        }
    }

    private static final int ROWS = 3;
    private static final int COLS = 3;

    /** Board stored as a 2‑dimensional array of symbols. */
    private static char[][] board = new char[ROWS][COLS];

    /** Number of X and O symbols on the board. */
    private static int xCount;
    private static int oCount;
    private static int emptyCount;

    /** Whether the game is already decided by a win. */
    private static boolean xWon;
    private static boolean oWon;

    private TicTacToe() { /* utility class – no instances */ }

    public static void main(String[] args) throws IOException {
        // --------------------------------------------------------------------
        // 1️⃣  Read the board using try‑with‑resources (automatically closed)
        // --------------------------------------------------------------------
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
             BufferedWriter writer = new BufferedWriter(new OutputStreamWriter(System.out))) {

            readBoard(reader);

            // --------------------------------------------------------------------
            // 2️⃣  Analyse the board – win detection and move‑count validation
            // --------------------------------------------------------------------
            analyseBoard();

            // --------------------------------------------------------------------
            // 3️⃣  Emit the appropriate result
            // --------------------------------------------------------------------
            writeResult(writer);
        }
    }

    /**
     * Reads nine non‑empty lines from the reader and stores them into a
     * {@code 3×3} character board. Blank lines are ignored, so the input may
     * contain an empty line between rows.
     */
    private static void readBoard(BufferedReader reader) throws IOException {
        int read = 0;                       // how many non‑blank lines we have read
        String line;

        while (read < ROWS * COLS) {
            line = reader.readLine();
            if (line == null) {
                throw new IOException("Unexpected end of input");
            }
            line = line.trim();

            if (line.isEmpty()) {
                continue; // skip blank separator lines
            }

            if (line.length() != 1) {
                throw new IOException("Each move must be a single character");
            }

            int row = read / COLS;
            int col = read % COLS;
            Symbol sym = Symbol.fromChar(line.charAt(0));
            board[row][col] = sym.getChar();

            // Update counting statistics
            switch (sym) {
                case X -> xCount++;
                case O -> oCount++;
                case EMPTY -> emptyCount++;
            }
            read++;
        }
    }

    /**
     * Checks all rows, columns and diagonals for a winning line.
     * The result is stored in the {@code xWon}/{@code oWon} flags.
     */
    private static void checkWins() {
        xWon = false;
        oWon = false;

        // Helper lambda to avoid repetition
        java.util.function.BiConsumer<Integer, Integer> checkLine = (r, c) -> {
            char first = board[r][c];
            if (first == Symbol.EMPTY.getChar()) {
                return;
            }
            if (board[r][c] == board[r][(c + 1) % COLS] &&
                board[r][c] == board[r][(c + 2) % COLS]) {
                if (first == Symbol.X.getChar()) {
                    xWon = true;
                } else if (first == Symbol.O.getChar()) {
                    oWon = true;
                }
            }
        };

        // Check rows
        for (int r = 0; r < ROWS; r++) {
            checkLine.accept(r, 0);
        }

        // Check columns
        for (int c = 0; c < COLS; c++) {
            checkLine.accept(0, c);
        }

        // Check main diagonal
        checkMainDiagonal();
        // Check anti‑diagonal
        checkAntiDiagonal();
    }

    /** Checks the main diagonal (top‑left → bottom‑right). */
    private static void checkMainDiagonal() {
        char first = board[0][0];
        if (first != Symbol.EMPTY.getChar()
                && board[0][0] == board[1][1]
                && board[0][0] == board[2][2]) {
            if (first == Symbol.X.getChar()) {
                xWon = true;
            } else {
                oWon = true;
            }
        }
    }

    /** Checks the anti‑diagonal (top‑right → bottom‑left). */
    private static void checkAntiDiagonal() {
        char first = board[0][2];
        if (first != Symbol.EMPTY.getChar()
                && board[0][2] == board[1][1]
                && board[0][2] == board[2][0]) {
            if (first == Symbol.X.getChar()) {
                xWon = true;
            } else {
                oWon = true;
            }
        }
    }

    /**
     * Validates the current board state and writes the corresponding message
     * to the provided {@link BufferedWriter}.
     */
    private static void analyseBoard() {
        checkWins();

        // Illegal board states -------------------------------------------------
        if (isIllegalBoard()) {
            System.out.println("illegal");
            System.exit(0);
        }

        // Determine whose turn it would be next (if the game is not over) -----
        String nextPlayer = (xCount == oCount) ? "first" : "second";

        // Output based on win / draw / next turn -------------------------------
        if (xWon) {
            // X can only win when it made one more move than O
            if (xCount != oCount + 1) {
                System.out.println("illegal");
            } else {
                System.out.println("the first player won");
            }
        } else if (oWon) {
            // O can only win when the move counts are equal
            if (xCount != oCount) {
                System.out.println("illegal");
            } else {
                System.out.println("the second player won");
            }
        } else if (emptyCount == 0) {
            System.out.println("draw");
        } else {
            System.out.println(nextPlayer);
        }
    }

    /**
     * Returns {@code true} if the board violates any rule of tic‑tac‑toe.
     */
    private static boolean isIllegalBoard() {
        // Both players cannot have winning lines simultaneously
        if (xWon && oWon) {
            return true;
        }

        // X must have made either the same number of moves as O or exactly one more
        if (!((xCount == oCount) || (xCount == oCount + 1))) {
            return true;
        }

        // If X won, it must have made one more move than O
        if (xWon && (xCount != oCount + 1)) {
            return true;
        }

        // If O won, the move counts must be equal
        if (oWon && (xCount != oCount)) {
            return true;
        }

        return false;
    }
}

import java.io.*;
import java.util.*;

public class TicTacToe {

    /** Mark used by the first player. */
    private static final char FIRST_MARK = 'X';
    /** Mark used by the second player. */
    private static final char SECOND_MARK = '0';
    /** Board dimension (3×3). */
    private static final int SIZE = 3;

    public static void main(String[] args) {
        try (InputStream in = System.in;
             OutputStream out = System.out) {

            new Solver().solve(new InputReader(in), new PrintWriter(out));
        }
    }

    /** Handles all game‑logic and output generation. */
    static class Solver {
        /** Reads the board, validates it and prints the appropriate result. */
        void solve(InputReader reader, PrintWriter out) {
            GameState state = parseGame(reader);

            if (!state.isValid()) {
                out.print("illegal");
                return;
            }

            if (state.firstWon && state.secondWon) {
                out.print("illegal");
                return;
            }

            if (state.firstWon) {
                out.print("the first player won");
                return;
            }

            if (state.secondWon) {
                out.print("the second player won");
                return;
            }

            if (state.isFull()) {
                out.print("draw");
                return;
            }

            // No winner yet – announce whose turn it is.
            out.print(state.firstMarkCount == state.secondMarkCount ? "first" : "second");
        }

        /** Parses three rows of input and builds a representation of the current board. */
        private GameState parseGame(InputReader reader) {
            boolean[][] firstBoard   = new boolean[SIZE][SIZE];
            boolean[][] secondBoard  = new boolean[SIZE][SIZE];
            int firstCount  = 0;
            int secondCount = 0;

            for (int i = 0; i < SIZE; i++) {
                String row = reader.next();
                for (int j = 0; j < SIZE; j++) {
                    char cell = row.charAt(j);
                    if (cell == FIRST_MARK) {
                        firstBoard[i][j] = true;
                        firstCount++;
                    } else if (cell == SECOND_MARK) {
                        secondBoard[i][j] = true;
                        secondCount++;
                    }
                }
            }

            boolean firstWon  = hasWon(firstBoard);
            boolean secondWon = hasWon(secondBoard);

            return new GameState(firstBoard, secondBoard, firstCount, secondCount,
                                 firstWon, secondWon);
        }

        /** Checks whether the given player has any winning line on the board. */
        private boolean hasWon(boolean[][] board) {
            // rows
            for (int i = 0; i < SIZE; i++) {
                if (board[i][0] && board[i][1] && board[i][2]) return true;
            }
            // columns
            for (int j = 0; j < SIZE; j++) {
                if (board[0][j] && board[1][j] && board[2][j]) return true;
            }
            // diagonals
            if (board[0][0] && board[1][1] && board[2][2]) return true;
            if (board[0][2] && board[1][1] && board[2][0]) return true;
            return false;
        }
    }

    /** Container that holds all information extracted from the input. */
    private static final class GameState {
        final boolean[][] firstBoard;
        final boolean[][] secondBoard;
        final int firstCount;
        final int secondCount;
        final boolean firstWon;
        final boolean secondWon;

        GameState(boolean[][] firstBoard, boolean[][] secondBoard,
                  int firstCount, int secondCount,
                  boolean firstWon, boolean secondWon) {
            this.firstBoard   = firstBoard;
            this.secondBoard  = secondBoard;
            this.firstCount   = firstCount;
            this.secondCount  = secondCount;
            this.firstWon     = firstWon;
            this.secondWon    = secondWon;
        }

        /** Validates that the board respects the rules of Tic‑Tac‑Toe. */
        boolean isValid() {
            // 1️⃣ The number of moves must obey turn order.
            if (secondCount > firstCount || firstCount > secondCount + 1) {
                return false;
            }
            // 2️⃣ Both players cannot win simultaneously.
            if (firstWon && secondWon) {
                return false;
            }
            // 3️⃣ If the first player wins, they must have made exactly one more move.
            if (firstWon && firstCount != secondCount + 1) {
                return false;
            }
            // 4️⃣ If the second player wins, the move counts must be equal.
            if (secondWon && firstCount != secondCount) {
                return false;
            }
            return true;
        }

        /** Returns true when the board is completely filled. */
        boolean isFull() {
            return firstCount + secondCount == SIZE * SIZE;
        }
    }

    /** Minimal tokenizer that reads whitespace‑separated tokens from an InputStream. */
    private static class InputReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        InputReader(InputStream stream) {
            this.reader = new BufferedReader(new InputStreamReader(stream), 32768);
        }

        String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new UncheckedIOException(e);
                }
            }
            return tokenizer.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        long nextLong() {
            return Long.parseLong(next());
        }
    }
}

import java.util.Scanner;

/**
 * Refactored version of the Tic‑Tac‑Toe validator.
 * <p>
 * The program reads three lines of three characters each (X, 0 or .) and
 * determines the current game state:
 * <ul>
 *   <li>“illegal” – the board configuration cannot appear in a real game</li>
 *   <li>“the first player won” – player X has a winning line</li>
 *   <li>“the second player won” – player 0 has a winning line</li>
 *   <li>“draw” – the board is full and nobody has won</li>
 *   <li>“first” – it is the first player's turn</li>
 *   <li>“second” – it is the second player's turn</li>
 * </ul>
 * </p>
 */
public final class TicTacToe {

    private static final char EMPTY = '.';
    private static final char PLAYER_ONE = 'X';
    private static final char PLAYER_TWO = '0';
    private static final int SIZE = 3;

    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            char[][] board = readBoard(scanner);
            GameState state = analyze(board);
            System.out.println(state.message());
        } catch (IllegalStateException e) {
            // Unexpected inconsistent state – re‑throw with the same semantics as the original code.
            throw new IllegalStateException(e.getMessage());
        }
    }

    /**
     * Reads exactly three lines of three characters each and builds the board.
     *
     * @throws IllegalStateException if a line does not contain exactly three symbols
     */
    private static char[][] readBoard(Scanner scanner) {
        char[][] board = new char[SIZE][];
        for (int i = 0; i < SIZE; i++) {
            String line = scanner.nextLine();
            if (line.length() != SIZE) {
                throw new IllegalStateException("illegal");
            }
            board[i] = line.toCharArray();
        }
        return board;
    }

    /**
     * Analyzes the board and returns the corresponding {@link GameState}.
     *
     * @throws IllegalStateException if the board configuration is illegal according
     *                               to the rules of Tic‑Tac‑Toe
     */
    private static GameState analyze(char[][] board) {
        int countX = 0;
        int countO = 0;
        int countEmpty = 0;

        for (char[] row : board) {
            for (char cell : row) {
                switch (cell) {
                    case PLAYER_ONE -> countX++;
                    case PLAYER_TWO -> countO++;
                    case EMPTY -> countEmpty++;
                    default -> throw new IllegalStateException("illegal");
                }
            }
        }

        boolean firstWon = hasWon(board, PLAYER_ONE);
        boolean secondWon = hasWon(board, PLAYER_TWO);

        // Illegal combinations ----------------------------------------------------
        if (firstWon && secondWon) {
            throw new IllegalStateException("illegal");
        }
        if (firstWon && countX != countO + 1) {
            throw new IllegalStateException("illegal");
        }
        if (secondWon && countO != countX) {
            throw new IllegalStateException("illegal");
        }
        if (countX < countO || countX > countO + 1) {
            throw new IllegalStateException("illegal");
        }

        // Determine the resulting message ----------------------------------------
        if (firstWon) {
            return GameState.FIRST_WON;
        }
        if (secondWon) {
            return GameState.SECOND_WON;
        }
        if (countEmpty == 0) {
            return GameState.DRAW;
        }
        // No winner yet – whose turn is it?
        return countX == countO ? GameState.FIRST_TURN : GameState.SECOND_TURN;
    }

    /** Checks whether the given player has a winning line on the board. */
    private static boolean hasWon(char[][] board, char player) {
        // rows
        for (int i = 0; i < SIZE; i++) {
            if (allEqual(row(board, i), player)) {
                return true;
            }
        }
        // columns
        for (int i = 0; i < SIZE; i++) {
            if (allEqual(column(board, i), player)) {
                return true;
            }
        }
        // diagonals
        if (allEqual(diagonal(board), player)) {
            return true;
        }
        if (allEqual(antiDiagonal(board), player)) {
            return true;
        }
        return false;
    }

    private static char[] row(char[][] board, int index) {
        return board[index];
    }

    private static char[] column(char[][] board, int index) {
        char[] col = new char[SIZE];
        for (int i = 0; i < SIZE; i++) {
            col[i] = board[i][index];
        }
        return col;
    }

    private static char[] diagonal(char[][] board) {
        char[] diag = new char[SIZE];
        for (int i = 0; i < SIZE; i++) {
            diag[i] = board[i][i];
        }
        return diag;
    }

    private static char[] antiDiagonal(char[][] board) {
        char[] anti = new char[SIZE];
        for (int i = 0; i < SIZE; i++) {
            anti[i] = board[SIZE - 1 - i][i];
        }
        return anti;
    }

    private static boolean allEqual(char[] arr, char value) {
        for (char c : arr) {
            if (c != value) {
                return false;
            }
        }
        return true;
    }

    /** Enum representing the possible outcomes of the analysis. */
    private enum GameState {
        FIRST_WON {
            @Override
            public String message() {
                return "the first player won";
            }
        },
        SECOND_WON {
            @Override
            public String message() {
                return "the second player won";
            }
        },
        DRAW {
            @Override
            public String message() {
                return "draw";
            }
        },
        FIRST_TURN {
            @Override
            public String message() {
                return "first";
            }
        },
        SECOND_TURN {
            @Override
            public String message() {
                return "second";
            }
        };

        abstract String message();
    }
}

package ticTacToe;

import java.io.*;
import java.util.StringTokenizer;

/**
 * Simple console implementation of a Tic‑Tac‑Toe validator.
 *
 * <p>The program reads a 3×3 board (each row on a separate line) and prints the
 * game status:
 * <ul>
 *   <li>which player has won,</li>
 *   <li>whether the current position is illegal,</li>
 *   <li>or if the game is a draw.</li>
 * </ul>
 *
 * <p>All game‑logic is extracted into small, well‑named methods to improve
 * readability and maintainability.
 */
public class TicTacToe {

    /** Symbol used for an empty cell. */
    private static final char EMPTY = '.';

    /** Symbol used for the first player (X). */
    private static final char PLAYER_X = 'X';

    /** Symbol used for the second player (O). */
    private static final char PLAYER_O = 'O';

    /** Size of the board (3×3). */
    private static final int SIZE = 3;

    /** The board itself – `board[row][col]`. */
    private final char[][] board;

    /** Game status: {@code 0}=no winner, {@code 1}=first player (X) wins,
     * {@code 2}=second player (O) wins, {@code 3}=both win (illegal). */
    private int winner;

    /** Counters of X, O and empty cells – used for legality checks. */
    private int countX, countO, countEmpty;

    /** --------------------------------------------------------------------- */
    /** Constructs a new game by reading a board from {@code System.in}. */
    public TicTacToe() throws IOException {
        this.board = readBoard();
        computeCountersAndWinner();
    }

    /** Reads exactly three lines from {@code System.in}, each containing three
     * characters. */
    private static char[][] readBoard() throws IOException {
        char[][] result = new char[SIZE][];
        for (int row = 0; row < SIZE; row++) {
            String line = readLine();
            result[row] = line.toCharArray();
        }
        return result;
    }

    /** Helper that reads a full line from {@code System.in} handling possible
     * charset issues. */
    private static String readLine() throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String line;
        while ((line = br.readLine()) == null || line.isBlank()) {
            // skip empty lines if any
        }
        return line;
    }

    /** Counts X, O and empty cells, and determines the current winner. */
    private void computeCountersAndWinner() {
        countX = countO = 0;
        countEmpty = 0;

        for (int row = 0; row < SIZE; row++) {
            for (char cell : board[row]) {
                if (cell == PLAYER_X) {
                    countX++;
                } else if (cell == PLAYER_O) {
                    countO++;
                } else if (cell == EMPTY) {
                    countEmpty++;
                }
            }
        }

        winner = 0;
        // rows
        winner |= checkLine(0, 0, 0, 1);
        winner |= checkLine(1, 0, 0, 1);
        winner |= checkLine(2, 0, 0, 1);
        // columns
        winner |= checkLine(0, 0, 1, 0);
        winner |= checkLine(0, 1, 1, 0);
        winner |= checkLine(0, 2, 1, 0);
        // diagonals
        winner |= checkLine(0, 0, 1, 1);
        winner |= checkLine(2, 0, -1, 1);
    }

    /** Checks a straight line (`dx`,`dy`) starting at (`x`,`y`) for three
     * identical non‑empty symbols. Returns {@code 0}, {@code 1} or {@code 2}
     * according to the player that wins along that line. */
    private int checkLine(int startX, int startY, int dx, int dy) {
        char symbol = board[startX][startY];
        if (symbol == EMPTY) {
            return 0;
        }
        // verify the next two cells in the same direction
        if (board[startX + dx][startY + dy] != symbol ||
            board[startX + 2 * dx][startY + 2 * dy] != symbol) {
            return 0;
        }
        return symbol == PLAYER_X ? 1 : 2;
    }

    /** Determines whether the current board configuration obeys the game rules.
     * If illegal, {@code winner} may become {@code 3}. Returns {@code true} if
     * the state is legal. */
    private boolean isLegal() {
        // player X always starts, so the number of Xs can be equal to Os or one more
        if (countO > countX || countX - countO > 1) {
            return false;
        }
        // X can win only when counts are equal, O can win only when there are more Os
        if (winner == 3) {
            return false;
        }
        if (winner == 1 && countX != countO) {
            return false;
        }
        if (winner == 2 && countX != countO + 1) {
            return false;
        }
        return true;
    }

    /** Produces the textual output required by the problem statement. */
    private void outputResult() {
        if (!isLegal()) {
            System.out.println("illegal");
            return;
        }

        // A draw occurs when the board is full and there is no winner.
        if (countEmpty == 0) {
            System.out.println("draw");
            return;
        }

        // If somebody has won, announce the winner.
        if (winner != 0) {
            System.out.printf("the %s player won%n",
                    winner == 1 ? "first" : "second");
            return;
        }

        // Otherwise the next player is the one who must move.
        System.out.println(countX == countO ? "first" : "second");
    }

    /** Entry point – orchestrates reading, validation and printing. */
    public static void main(String[] args) throws IOException {
        try (PrintWriter out = new PrintWriter(System.out, true)) {
            TicTacToe game = new TicTacToe();
            game.outputResult();
        }
    }
}

import java.io.*;
import java.util.*;
import java.util.stream.Collectors;

/**
 * Refactored version of the original program.
 *
 * <p>
 *  • Reads a 3×3 tic‑tac‑toe board from {@code stdin} (or from a file when {@code fname} is set).
 *  • Determines the state of the game:
 *      <ul>
 *          <li>"first"      – X has to move (counts equal)</li>
 *          <li>"second"     – O has to move (X has made one extra move)</li>
 *          <li>"illegal"    – board configuration cannot appear in a real game</li>
 *          <li>"the first player won"</li>
 *          <li>"the second player won"</li>
 *          <li>"draw"</li>
 *      </ul>
 *  • The logic is split into small, purpose‑focused methods to improve readability and
 *    maintainability.
 * </p>
 */
public class Main implements Runnable {

    /** All possible output strings – kept identical to the original program. */
    private static final String[] RES = {
            "first",                     // 0 – X to move
            "second",                    // 1 – O to move
            "illegal",                   // 2 – illegal board state
            "the first player won",      // 3 – X won
            "the second player won",     // 4 – O won
            "draw"                       // 5 – draw
    };

    /** Directions that constitute a winning line on a 3×3 board. */
    private static final int[][] WIN_LINES = {
            // rows
            {0, 1, 2},
            {3, 4, 5},
            {6, 7, 8},
            // columns
            {0, 3, 6},
            {1, 4, 7},
            {2, 5, 8},
            // diagonals
            {0, 4, 8},
            {2, 4, 6}
    };

    /** Row‑major index of the 3×3 board. */
    private static final int SIZE = 9;

    /** Buffered input stream (file or STDIN). */
    private BufferedReader in;
    /** Printed output (file or STDOUT). */
    private PrintWriter out;
    /** Name of the input file (without extension). */
    private final String fname;

    /** --------------------------------------------------------------------- */
    /** Construction & I/O handling ------------------------------------------------ */

    public Main() {
        this.fname = "";
    }

    /** Starts the program – reads input, computes the answer and writes it. */
    @Override
    public void run() {
        try {
            initIo();
            out.println(solve());
            in.close();
            out.close();
        } catch (Exception e) {
            e.printStackTrace();
        }
    }

    private void initIo() throws IOException {
        if (fname.isBlank()) {
            in = new BufferedReader(new InputStreamReader(System.in));
            out = new PrintWriter(new OutputStreamWriter(System.out));
        } else {
            in = new BufferedReader(new FileReader(fname + ".in"));
            out = new PrintWriter(new FileWriter(fname + ".out"));
        }
    }

    /** --------------------------------------------------------------------- */
    /** Core algorithm ----------------------------------------------------------- */

    /**
     * Reads the board, analyses it and returns the appropriate status string.
     */
    private String solve() throws Exception {
        char[][] board = readBoard();

        int xCount = countOccurrences(board, 'X');
        int oCount = countOccurrences(board, 'O');

        // -----------------------------------------------------------------
        // 1️⃣  Validate move counts (illegal if O > X or X - O > 1)
        // -----------------------------------------------------------------
        if (oCount > xCount || Math.abs(xCount - oCount) > 1) {
            return RES[2]; // illegal
        }

        boolean xWins = hasWin(board, 'X');
        boolean oWins = hasWin(board, 'O');

        // -----------------------------------------------------------------
        // 2️⃣  Validate win‑state consistency with move counts
        // -----------------------------------------------------------------
        if (xWins && oWins) {
            return RES[2]; // both cannot win
        }
        if (oWins && xCount != oCount) {
            return RES[2]; // O cannot win on a board where X has made one extra move
        }
        if (xWins && xCount != oCount + 1) {
            return RES[2]; // X cannot win unless it made exactly one more move
        }

        // -----------------------------------------------------------------
        // 3️⃣  Determine final outcome
        // -----------------------------------------------------------------
        if (xWins) {
            return RES[3]; // X won
        }
        if (oWins) {
            return RES[4]; // O won
        }
        if (xCount + oCount == SIZE) {
            return RES[5]; // draw
        }
        // No winner – whose turn is it?
        return xCount > oCount ? RES[1] : RES[0];
    }

    /** --------------------------------------------------------------------- */
    /** Helper methods ---------------------------------------------------------- */

    /** Parses the 3×3 board from {@code in}. */
    private char[][] readBoard() throws IOException {
        char[][] board = new char[3][];
        for (int i = 0; i < 3; i++) {
            String line = in.readLine().trim();
            board[i] = line.toCharArray();
        }
        return board;
    }

    /** Counts occurrences of {@code target} in the board. */
    private int countOccurrences(char[][] board, char target) {
        int cnt = 0;
        for (char[] row : board) {
            for (char cell : row) {
                if (cell == target) {
                    cnt++;
                }
            }
        }
        return cnt;
    }

    /**
     * Checks whether the given {@code player} ('X' or 'O') has a complete winning line.
     */
    private boolean hasWin(char[][] board, char player) {
        // Flatten the board into a linear array for easier indexing.
        int[] cells = new int[SIZE];
        int idx = 0;
        for (char[] row : board) {
            for (char cell : row) {
                cells[idx++] = cell == player ? 1 : 0;
            }
        }

        // Test each predefined winning line.
        for (int[] line : WIN_LINES) {
            if (cells[line[0]] + cells[line[1]] + cells[line[2]] == 3) {
                return true;
            }
        }
        return false;
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;

/**
 * Utility class that checks the state of a 3×3 Tic‑Tac‑Toe board.
 *
 * <p>Reads three lines from standard input, each containing exactly three
 * characters (X, O or space).  The program then reports whether the board
 * configuration is illegal, which player has won, or if the game is a draw,
 * and finally which player would play next.</p>
 */
public class C3 {

    /** Player symbols */
    private static final char PLAYER_X = 'X';
    private static final char PLAYER_O = 'O';

    /** Empty cell symbol */
    private static final char EMPTY = ' ';

    public static void main(String[] args) throws IOException {
        char[][] board = readBoard();
        int xCount = count(board, PLAYER_X);
        int oCount = count(board, PLAYER_O);

        boolean xWon = hasWon(board, PLAYER_X);
        boolean oWon = hasWon(board, PLAYER_O);

        if (isIllegalState(xCount, oCount, xWon, oWon)) {
            System.out.println("illegal");
            return;
        }

        if (xWon) {
            System.out.println("the first player won");
            return;
        }

        if (oWon) {
            System.out.println("the second player won");
            return;
        }

        if (xCount + oCount == 9) {
            System.out.println("draw");
            return;
        }

        System.out.println(xCount > oCount ? "second" : "first");
    }

    /** Reads three lines from stdin and converts them into a 3×3 char matrix. */
    private static char[][] readBoard() throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String line1 = br.readLine();
        String line2 = br.readLine();
        String line3 = br.readLine();

        char[][] board = new char[3][3];
        board[0] = line1.toCharArray();
        board[1] = line2.toCharArray();
        board[2] = line3.toCharArray();
        return board;
    }

    /** Returns the number of occurrences of {@code symbol} on the board. */
    private static int count(char[][] board, char symbol) {
        int cnt = 0;
        for (char[] row : board) {
            for (char cell : row) {
                if (cell == symbol) {
                    cnt++;
                }
            }
        }
        return cnt;
    }

    /** Checks whether the given player has a complete row, column or diagonal. */
    private static boolean hasWon(char[][] board, char player) {
        // Check rows
        for (int i = 0; i < 3; i++) {
            if (allEqual(board[i][0], board[i][1], board[i][2], player)) {
                return true;
            }
        }
        // Check columns
        for (int j = 0; j < 3; j++) {
            if (allEqual(board[0][j], board[1][j], board[2][j], player)) {
                return true;
            }
        }
        // Check diagonals
        if (allEqual(board[0][0], board[1][1], board[2][2], player)) {
            return true;
        }
        if (allEqual(board[0][2], board[1][1], board[2][0], player)) {
            return true;
        }
        return false;
    }

    /** Helper that returns true if all three cells equal {@code expected}. */
    private static boolean allEqual(char a, char b, char c, char expected) {
        return a == expected && b == expected && c == expected;
    }

    /** Determines whether the current board state breaks the rules of Tic‑Tac‑Toe. */
    private static boolean isIllegalState(int xCnt, int oCnt, boolean xWon, boolean oWon) {
        // Both players cannot be winners
        if (xWon && oWon) {
            return true;
        }

        // X always starts, so the difference in counts must be 0 or 1
        if (Math.abs(xCnt - oCnt) > 1) {
            return true;
        }

        // If O has made a move, X must have made at least as many moves as O
        if (oCnt > xCnt) {
            return true;
        }

        // A player who has already won cannot have the opponent make another move
        if (xWon && xCnt != oCnt + 1) {
            return true;
        }
        if (oWon && xCnt != oCnt) {
            return true;
        }

        return false;
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;

/**
 * Utility that validates a 3×3 Tic‑Tac‑Toe board entered by the user
 * and reports the result of the game (draw, first player win, second player win,
 * illegal state, etc.).
 *
 * <p>All public methods are intentionally small, have meaningful names and
 * convey their intent through Javadoc.</p>
 */
public class TicTacToeValidator {

    /** Character representing player 1 (X). */
    private static final char PLAYER_X = 'X';

    /** Character representing player 2 (O). */
    private static final char PLAYER_O = 'O';

    /** Maximum board size. */
    private static final int BOARD_SIZE = 3;

    /** Message constants – keep UI strings in one place. */
    private static final String MESSAGE_ILLEGAL = "illegal";
    private static final String MESSAGE_FIRST_WON = "the first player won";
    private static final String MESSAGE_SECOND_WON = "the second player won";
    private static final String MESSAGE_FIRST_TURN = "first";
    private static final String MESSAGE_SECOND_TURN = "second";
    private static final String MESSAGE_DRAW = "draw";

    /**
     * Entry point – reads three lines from standard input,
     * builds a 3×3 board and prints the game result.
     *
     * @throws IOException if reading from {@code System.in} fails.
     */
    public static void main(String[] args) throws IOException {
        char[][] board = readBoardFromStdin();
        reportGameResult(board);
    }

    /** Reads exactly three lines of input and returns a 3×3 character board. */
    private static char[][] readBoardFromStdin() throws IOException {
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
        char[][] board = new char[BOARD_SIZE][BOARD_SIZE];

        for (int row = 0; row < BOARD_SIZE; row++) {
            String line = reader.readLine();
            if (line == null) {
                throw new IOException("Unexpected end of input.");
            }
            board[row] = line.toCharArray();
            if (board[row].length != BOARD_SIZE) {
                throw new IOException("Each line must contain exactly " + BOARD_SIZE + " characters.");
            }
        }
        return board;
    }

    /**
     * Determines whether the given player has a winning line (row, column or diagonal).
     *
     * @param board  3×3 board containing only X, O or empty cells.
     * @param player Symbol of the player to check ('X' or 'O').
     * @return {@code true} if the player has at least one complete line.
     */
    private static boolean hasWon(char[][] board, char player) {
        // Check rows and columns
        for (int i = 0; i < BOARD_SIZE; i++) {
            boolean rowComplete = true;
            boolean columnComplete = true;

            for (int j = 0; j < BOARD_SIZE; j++) {
                rowComplete &= board[i][j] == player;
                columnComplete &= board[j][i] == player;
            }
            if (rowComplete || columnComplete) {
                return true;
            }
        }

        // Check the two diagonals
        boolean mainDiagonal = true;
        boolean antiDiagonal = true;

        for (int i = 0; i < BOARD_SIZE; i++) {
            mainDiagonal &= board[i][i] == player;
            antiDiagonal &= board[i][BOARD_SIZE - 1 - i] == player;
        }
        return mainDiagonal || antiDiagonal;
    }

    /**
     * Counts how many cells contain the given player's symbol.
     *
     * @param board   3×3 board.
     * @param player  Symbol to count ('X' or 'O').
     * @return number of occurrences of {@code player}.
     */
    private static int countOccurrences(char[][] board, char player) {
        int count = 0;
        for (int row = 0; row < BOARD_SIZE; row++) {
            for (int col = 0; col < BOARD_SIZE; col++) {
                if (board[row][col] == player) {
                    count++;
                }
            }
        }
        return count;
    }

    /**
     * Analyzes the supplied board and prints the appropriate outcome.
     *
     * <p>The rules enforced are those defined by the classic Tic‑Tac‑Toe game:
     * <ul>
     *   <li>Exactly one more X than O (or equal when O just played).</li>
     *   <li>Both players cannot have a winning line simultaneously.</li>
     *   <li>If X wins, the move count difference must be exactly 1.</li>
     *   <li>If O wins, the move counts must be equal.</li>
     * </ul>
     * </p>
     *
     * @param board 3×3 character board.
     */
    private static void reportGameResult(char[][] board) {
        boolean xWins = hasWon(board, PLAYER_X);
        boolean oWins = hasWon(board, PLAYER_O);

        int xCount = countOccurrences(board, PLAYER_X);
        int oCount = countOccurrences(board, PLAYER_O);

        // ----- Validation of illegal states -------------------------------------------------
        boolean illegalState = xWins && oWins                     // both cannot win
                || oCount > xCount                               // too many O's
                || (xCount - oCount) > 1                         // too many X's
                || (xWins && (xCount - oCount) != 1)             // X win but wrong move count
                || (oWins && xCount != oCount);                  // O win but wrong move count

        if (illegalState) {
            System.out.println(MESSAGE_ILLEGAL);
            return;
        }

        // ----- Determine and print the result -------------------------------------------------
        if (xWins) {
            System.out.println(MESSAGE_FIRST_WON);
        } else if (oWins) {
            System.out.println(MESSAGE_SECOND_WON);
        } else if (xCount == oCount) {
            System.out.println(MESSAGE_FIRST_TURN);
        } else if (xCount + oCount != BOARD_SIZE * BOARD_SIZE) {
            System.out.println(MESSAGE_SECOND_TURN);
        } else {
            System.out.println(MESSAGE_DRAW);
        }
    }
}

import java.io.*;
import java.util.*;

public class C {

    /** Reads a complete Tic‑Tac‑Toe board from STDIN. */
    private static char[][] readBoard(Scanner sc) {
        char[][] board = new char[3][3];
        for (int r = 0; r < 3; r++) {
            String line = sc.next();
            board[r][0] = line.charAt(0);
            board[r][1] = line.charAt(1);
            board[r][2] = line.charAt(2);
        }
        return board;
    }

    /** Counts how many times a given character appears on the board. */
    private static int count(char ch, char[][] board) {
        int cnt = 0;
        for (char[] row : board) {
            for (char cell : row) {
                if (cell == ch) cnt++;
            }
        }
        return cnt;
    }

    /** Returns the number of lines (rows, columns, diagonals) that are completely
     *  filled with the given character. */
    private static int countWinningLines(char ch, char[][] board) {
        int lines = 0;
        // rows
        for (int r = 0; r < 3; r++) {
            if (board[r][0] == ch && board[r][1] == ch && board[r][2] == ch) {
                lines++;
            }
        }
        // columns
        for (int c = 0; c < 3; c++) {
            if (board[0][c] == ch && board[1][c] == ch && board[2][c] == ch) {
                lines++;
            }
        }
        // diagonals
        if (board[0][0] == ch && board[1][1] == ch && board[2][2] == ch) {
            lines++;
        }
        if (board[0][2] == ch && board[1][1] == ch && board[2][0] == ch) {
            lines++;
        }
        return lines;
    }

    /** Adjusts a raw winning‑line count taking the total number of placed pieces
     *  into account – exactly the same rule that the original {@code getWONS}
     *  method used. */
    private static int adjustedWinCount(int rawWinCount, int totalPieces) {
        return (3 * rawWinCount <= totalPieces) ? rawWinCount : rawWinCount - 1;
    }

    /** Determines whether the current board state is illegal according to the
     *  rules of Tic‑Tac‑Toe. */
    private static boolean isIllegal(int xCount, int oCount,
                                     int xWinAdj, int oWinAdj) {
        return oCount > xCount ||
               (xCount - oCount > 1) ||
               (xWinAdj + oWinAdj > 1) ||
               (xWinAdj == 1 && oCount >= xCount) ||
               (oWinAdj == 1 && xCount > oCount);
    }

    /** Produces the final output line required by the problem statement. */
    private static String decideResult(int xCount, int oCount,
                                       int xWinAdj, int oWinAdj) {
        if (xWinAdj == 1) {
            return "the first player won";
        }
        if (oWinAdj == 1) {
            return "the second player won";
        }
        if (xCount + oCount == 9) {
            return "draw";
        }
        // No one has won yet – announce whose turn is next.
        return (xCount > oCount) ? "second" : "first";
    }

    /* --------------------------------------------------------------------- */
    /*  Main driver – kept compatible with the original public PrintWriter API */
    /* --------------------------------------------------------------------- */

    private final Scanner sc = new Scanner(new BufferedInputStream(System.in));
    private final PrintWriter pw = new PrintWriter(new BufferedOutputStream(System.out));

    public PrintWriter run() {
        char[][] board = readBoard(sc);

        int countX = count('X', board);
        int countO = count('0', board);

        int rawWinX = countWinningLines('X', board);
        int rawWinO = countWinningLines('0', board);

        int winXAdj = adjustedWinCount(rawWinX, countX);
        int winOAdj = adjustedWinCount(rawWinO, countO);

        if (isIllegal(countX, countO, winXAdj, winOAdj)) {
            pw.println("illegal");
            return pw;
        }

        if (winXAdj == 1) {
            pw.println("the first player won");
        } else if (winOAdj == 1) {
            pw.println("the second player won");
        } else if ((countX + countO) == 9) {
            pw.println("draw");
        } else {
            pw.println(decideResult(countX, countO, winXAdj, winOAdj));
        }

        return pw;
    }

    public static void main(String[] args) throws Exception {
        new C().run().close();
    }
}

import java.util.Scanner;

/**
 * Refactored version of the original Tic‑Tac‑Toe checker.
 * The program reads a 3×3 board, validates the position,
 * determines whose turn it is and reports the game result.
 *
 * Improvements:
 *   • Meaningful method and variable names.
 *   • Constants instead of magic numbers.
 *   • Validation logic separated into small, focussed helpers.
 *   • No duplicated logic – each responsibility has its own method.
 *   • Clear early‑return flow for easy reasoning.
 */
public class Game {

    /** board size constant */
    private static final int SIZE = 3;

    /** character used for an empty cell */
    private static final char EMPTY = '.';

    /** player X (the first player) */
    private static final char PLAYER_X = 'X';

    /** player O (the second player) – the original program used the digit ‘0’ */
    private static final char PLAYER_O = '0';

    /** All possible winning line coordinate triples */
    private static final int[][][] WIN_LINES = {
            {{0, 0}, {0, 1}, {0, 2}},
            {{1, 0}, {1, 1}, {1, 2}},
            {{2, 0}, {2, 1}, {2, 2}},
            {{0, 0}, {1, 0}, {2, 0}},
            {{0, 1}, {1, 1}, {2, 1}},
            {{0, 2}, {1, 2}, {2, 2}},
            {{0, 0}, {1, 1}, {2, 2}},
            {{0, 2}, {1, 1}, {2, 0}}
    };

    public static void main(String[] args) {
        new Game().run();
    }

    /** Entry point that reads input, validates it and prints the result. */
    public void run() {
        try (Scanner scanner = new Scanner(System.in)) {
            char[][] board = readBoard(scanner);
            int currentPlayer = determineCurrentPlayer(board);
            int[] winCounts = countWins(board);

            if (!isStateLegal(board, currentPlayer, winCounts)) {
                System.out.println("illegal");
                return;
            }

            if (winCounts[0] > 0) {
                System.out.println("the first player won");
                return;
            }
            if (winCounts[1] > 0) {
                System.out.println("the second player won");
                return;
            }

            System.out.println(currentPlayer == 3 ? "draw"
                                                    : (currentPlayer == 1 ? "first" : "second"));
        }
    }

    /** Reads three strings from the scanner and converts them into a 3×3 char array. */
    private char[][] readBoard(Scanner scanner) {
        char[][] board = new char[SIZE][SIZE];
        for (int i = 0; i < SIZE; i++) {
            String row = scanner.next().trim();
            board[i] = row.toCharArray();
        }
        return board;
    }

    /**
     * Determines whose turn it is next.
     *
     * @return 1 if it is the first player's turn (X),
     *         2 if it is the second player's turn (O),
     *         3 if the board is full (draw situation),
     *        -1 if the board configuration is illegal with respect to move counts.
     */
    private int determineCurrentPlayer(char[][] board) {
        int xCount = countOccurrences(board, PLAYER_X);
        int oCount = countOccurrences(board, PLAYER_O);

        if (xCount == oCount) {
            return 1;                         // X (first) is to move
        }
        if (xCount == oCount + 1) {
            return (xCount + oCount == SIZE * SIZE) ? 3 : 2; // O (second) is to move, unless board is full
        }
        return -1;                            // illegal number of marks
    }

    /** Counts how many times a given character appears on the board. */
    private int countOccurrences(char[][] board, char symbol) {
        int total = 0;
        for (char[] row : board) {
            for (char cell : row) {
                if (cell == symbol) {
                    total++;
                }
            }
        }
        return total;
    }

    /**
     * Counts winning lines for each player.
     *
     * @return an int array where index 0 holds the number of winning lines for X,
     *       index 1 holds the number of winning lines for O.
     */
    private int[] countWins(char[][] board) {
        int[] wins = new int[2]; // 0 → X, 1 → O
        for (int[][] line : WIN_LINES) {
            checkLine(board, line, wins);
        }
        return wins;
    }

    /** Checks a single winning line and updates the supplied win count array. */
    private void checkLine(char[][] board, int[][] line, int[] wins) {
        char first = board[line[0][0]][line[0][1]];
        if (first == EMPTY) {
            return;
        }
        if (first != board[line[1][0]][line[1][1]]) {
            return;
        }
        if (first != board[line[2][0]][line[2][1]]) {
            return;
        }
        if (first == PLAYER_X) {
            wins[0]++;
        } else if (first == PLAYER_O) {
            wins[1]++;
        }
    }

    /**
     * Validates the current game state.
     *
     * The board is illegal if:
     *   • Both players have winning lines,
     *   • The player who is about to move already has a winning line,
     *   • The number of X and O marks does not follow the rules of turn order.
     *
     * @return {@code true} if the state is legal, {@code false} otherwise.
     */
    private boolean isStateLegal(char[][] board, int currentPlayer, int[] winCounts) {
        // Two simultaneous winners make the board illegal.
        if (winCounts[0] > 0 && winCounts[1] > 0) {
            return false;
        }

        // A player cannot be about to move if they already have a completed line.
        if ((currentPlayer == 1 && winCounts[0] > 0) || (currentPlayer == 2 && winCounts[1] > 0)) {
            return false;
        }

        // Turn order sanity check – already performed in {@link #determineCurrentPlayer},
        // but we keep the check here for completeness in case the method is called
        // directly with an external player value.
        return true;
    }
}

import java.util.Scanner;

/**
 * Tic‑Tac‑Toe state evaluator.
 *
 * <p>
 *   The program reads a 3×3 board where each cell is:
 *   <ul>
 *     <li>'X' – move of the first player</li>
 *     <li>'0' – move of the second player</li>
 *     <li>any other character – empty cell</li>
 *   </ul>
 *   It uses exhaustive search with memoisation to determine the outcome
 *   (first player win, second player win, draw or illegal position) from
 *   the initial empty board.
 * </p>
 */
public class Main {

    /** Size of the board */
    private static final int SIZE = 3;

    /** All possible winning line indices (row, column or diagonal) */
    private static final int[][] WIN_LINES = {
            // rows
            {0, 1, 2}, {3, 4, 5}, {6, 7, 8},
            // columns
            {0, 3, 6}, {1, 4, 7}, {2, 5, 8},
            // diagonals
            {0, 4, 8}, {2, 4, 6}
    };

    /** Maximum number of distinct board states (3⁹). */
    private static final int MAX_STATES = (int) Math.pow(3, SIZE * SIZE);

    /** Constant results stored in the memoisation table. */
    private static final int UNKNOWN = 0;
    private static final int FIRST_MOVE = 1;   // next player to move is the first player
    private static final int SECOND_MOVE = 2;  // next player to move is the second player
    private static final int FIRST_WON = 3;    // first player has a forced win
    private static final int SECOND_WON = 4;   // second player has a forced win
    private static final int DRAW = 5;         // the game ends in a draw

    /** Memoisation table – 0 means “not evaluated yet”. */
    private static final int[] memo = new int[MAX_STATES];

    /** Board representation used internally (flattened to a 1‑D array). */
    private static final int[] board = new int[SIZE * SIZE];

    /** --------------------------------------------------------------------- */
    /** Entry point */
    /** --------------------------------------------------------------------- */
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        /* ----------------------------------------------------------------- */
        /* 1. Read the input board                                               */
        /* ----------------------------------------------------------------- */
        String[] rows = new String[SIZE];
        for (int i = 0; i < SIZE; i++) {
            rows[i] = scanner.next();
        }

        int state = encodeBoard(rows);
        /* ----------------------------------------------------------------- */
        /* 2. Pre‑compute all outcomes from the empty board                     */
        /* ----------------------------------------------------------------- */
        computeAllOutcomes(FIRST_MOVE);

        /* ----------------------------------------------------------------- */
        /* 3. Interpret the memoised result and print a human‑readable message */
        /* ----------------------------------------------------------------- */
        if (memo[state] == UNKNOWN) {
            System.out.println("illegal");
        } else if (memo[state] == FIRST_MOVE) {
            System.out.println("first");
        } else if (memo[state] == SECOND_MOVE) {
            System.out.println("second");
        } else if (memo[state] == FIRST_WON) {
            System.out.println("the first player won");
        } else if (memo[state] == SECOND_WON) {
            System.out.println("the second player won");
        } else if (memo[state] == DRAW) {
            System.out.println("draw");
        }
    }

    /** --------------------------------------------------------------------- */
    /** Encode a 3×3 board into a single integer (base‑3 representation).      */
    /** --------------------------------------------------------------------- */
    private static int encodeBoard(String[] rows) {
        int code = 0;
        int weight = 1;                     // 3⁰, 3¹, …
        for (int r = 0; r < SIZE; r++) {
            String line = rows[r];
            for (int c = 0; c < SIZE; c++) {
                char ch = line.charAt(c);
                int cellValue;
                if (ch == 'X') {
                    cellValue = FIRST_MOVE;          // first player's mark
                } else if (ch == '0') {
                    cellValue = SECOND_MOVE;         // second player's mark
                } else {
                    cellValue = 0;                    // empty
                }
                code += cellValue * weight;
                weight *= 3;
            }
        }
        return code;
    }

    /** --------------------------------------------------------------------- */
    /** Recursively evaluate every reachable board state and store the result  */
    /** in the global memoisation table.                                       */
    /** --------------------------------------------------------------------- */
    private static void computeAllOutcomes(int nextPlayer) {
        // start from the completely empty board (code = 0)
        dfs(0, nextPlayer);
    }

    /** --------------------------------------------------------------------- */
    /** Depth‑first search over the game tree.                                 */
    /** --------------------------------------------------------------------- */
    private static void dfs(int state, int nextPlayer) {
        if (memo[state] != UNKNOWN) {
            return; // already processed
        }

        // check whether the current position is a terminal one
        int winner = evaluate(state);
        if (winner != 0) {
            // terminal – store winner code (3 or 4) + 2 as the original program did
            memo[state] = winner + 2;
            return;
        }

        boolean anyMove = false;
        int next = (nextPlayer == FIRST_MOVE) ? SECOND_MOVE : FIRST_MOVE;

        // try every empty cell
        int tmpState = state;
        int weight = 1;
        for (int i = 0; i < SIZE * SIZE; i++) {
            int cell = (state / weight) % 3;   // digit in base‑3
            if (cell == 0) {                     // empty
                anyMove = true;
                // place next player's mark
                int newState = state + nextPlayer * weight;
                dfs(newState, next);
            }
            weight *= 3;
        }

        // if there is no empty cell the game is a draw
        memo[state] = anyMove ? nextPlayer : DRAW;
    }

    /** --------------------------------------------------------------------- */
    /** Determine whether a player has three marks in a row.                  */
    /** Returns 1 if the first player (cross) wins, 2 if the second player    */
    /** (circle) wins, otherwise 0.                                            */
    /** --------------------------------------------------------------------- */
    private static int evaluate(int state) {
        // convert the flat index to a 2‑D coordinate when needed
        for (int[] line : WIN_LINES) {
            int a = line[0], b = line[1], c = line[2];
            int va = digitAt(a, state);
            int vb = digitAt(b, state);
            int vc = digitAt(c, state);

            if (va != 0 && va == vb && vb == vc) {
                return va; // 1 → first player, 2 → second player
            }
        }
        return 0;
    }

    /** --------------------------------------------------------------------- */
    /** Extract the digit belonging to a given flat index from a base‑3 number */
    /** --------------------------------------------------------------------- */
    private static int digitAt(int index, int state) {
        int weight = 1;
        for (int i = 0; i < index; i++) {
            weight *= 3;
        }
        return (state / weight) % 3;
    }
}

import java.util.Scanner;

/**
 * Simple console Tic‑Tac‑Toe engine.
 *
 * <p>Features:
 * <ul>
 *   <li>Clear separation of concerns (input, validation, win detection, game state)
 *   <li>Descriptive method names and constants
 *   <li>Early validation of move counts and illegal board states
 *   <li>Uses {@code Scanner} with try‑with‑resources for safe resource handling
 * </ul>
 */
public class TicTacToe {

    /** Symbol used for an empty cell */
    private static final char EMPTY = ' ';

    /** Symbols for the two players */
    private static final char PLAYER_X = 'X';
    private static final char PLAYER_O = 'O';

    public static void main(String[] args) {
        /* ------------------------------------------------------------
         * 1️⃣  Read the board from standard input
         * ------------------------------------------------------------ */
        char[][] board;
        try (Scanner scanner = new Scanner(System.in)) {
            board = readBoard(scanner);
        }

        /* ------------------------------------------------------------
         * 2️⃣  Count the marks of each player
         * ------------------------------------------------------------ */
        int xCount = countOccurrences(board, PLAYER_X);
        int oCount = countOccurrences(board, PLAYER_O);

        /* ------------------------------------------------------------
         * 3️⃣  Validate move‑count consistency
         * ------------------------------------------------------------ */
        if (!isValidCount(xCount, oCount)) {
            System.out.println("illegal");
            return;
        }

        /* ------------------------------------------------------------
         * 4️⃣  Determine whether a player has won
         * ------------------------------------------------------------ */
        boolean xWon = hasWon(board, PLAYER_X);
        boolean oWon = hasWon(board, PLAYER_O);

        /* ------------------------------------------------------------
         * 5️⃣  Detect illegal win combinations
         * ------------------------------------------------------------ */
        if (xWon && oWon || (xWon && oCount >= xCount) || (oWon && xCount > oCount)) {
            System.out.println("illegal");
            return;
        }

        /* ------------------------------------------------------------
         * 6️⃣  Produce the appropriate output
         * ------------------------------------------------------------ */
        if (xWon) {
            System.out.println("the first player won");
        } else if (oWon) {
            System.out.println("the second player won");
        } else if (xCount + oCount == 9) {
            System.out.println("draw");
        } else {
            // Game still in progress – indicate whose turn it is next
            System.out.println(((xCount + oCount) % 2 == 0) ? "first" : "second");
        }
    }

    /** Reads exactly three lines, each containing three non‑whitespace characters. */
    private static char[][] readBoard(Scanner scanner) {
        char[][] board = new char[3][3];
        for (int r = 0; r < 3; r++) {
            String line = scanner.nextLine().trim();
            if (line.length() < 3) {
                throw new IllegalArgumentException("Each line must contain at least 3 characters");
            }
            for (int c = 0; c < 3; c++) {
                board[r][c] = line.charAt(c);
            }
        }
        return board;
    }

    /** Counts how many times {@code target} appears on the board. */
    private static int countOccurrences(char[][] board, char target) {
        int count = 0;
        for (char[] row : board) {
            for (char cell : row) {
                if (cell == target) {
                    count++;
                }
            }
        }
        return count;
    }

    /** Returns {@code true} if the given player has a complete row, column or diagonal. */
    private static boolean hasWon(char[][] board, char player) {
        // Check rows
        for (int i = 0; i < 3; i++) {
            if (board[i][0] == player && board[i][1] == player && board[i][2] == player) {
                return true;
            }
        }
        // Check columns
        for (int j = 0; j < 3; j++) {
            if (board[0][j] == player && board[1][j] == player && board[2][j] == player) {
                return true;
            }
        }
        // Check diagonals
        if (board[0][0] == player && board[1][1] == player && board[2][2] == player) {
            return true;
        }
        if (board[0][2] == player && board[1][1] == player && board[2][0] == player) {
            return true;
        }
        return false;
    }

    /** Validates that the numbers of X and O obey the rules of Tic‑Tac‑Toe. */
    private static boolean isValidCount(int xCount, int oCount) {
        return Math.abs(xCount - oCount) <= 1 && xCount >= oCount;
    }
}

import java.io.*;
import java.util.*;

public class Main {

    /** Symbols used on the board */
    private static final char PLAYER_X = 'X'; // first player
    private static final char PLAYER_O = '0'; // second player

    public static void main(String[] args) throws IOException {
        /* Read the whole board from standard input */
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in))) {
            char[][] board = readBoard(br);
            int countX = countSymbols(board, PLAYER_X);
            int countO = countSymbols(board, PLAYER_O);

            /* -----------------------------------------------------------------
             *  1️⃣  Validate the move counts (illegal board if they differ too much)
             * ----------------------------------------------------------------- */
            if (!isLegal(countX, countO)) {
                System.out.println("illegal");
                return;
            }

            /* -------------------------------------------------
             *  2️⃣  Detect a win for each player
             * ------------------------------------------------- */
            boolean xWon = isWinning(board, PLAYER_X);
            boolean oWon = isWinning(board, PLAYER_O);

            if (xWon && oWon) {                     // both cannot win
                System.out.println("illegal");
                return;
            }

            if (xWon) {
                if (countX <= countO) {               // X cannot win on opponent's turn
                    System.out.println("illegal");
                } else {
                    System.out.println("the first player won");
                }
                return;
            }

            if (oWon) {
                if (countO <= countX) {               // O cannot win on opponent's turn
                    System.out.println("illegal");
                } else {
                    System.out.println("the second player won");
                }
                return;
            }

            /* -------------------------------------------------
             *  3️⃣  End‑game conditions
             * ------------------------------------------------- */
            if (boardFull(countX, countO)) {
                System.out.println("draw");
                return;
            }

            /* -------------------------------------------------
             *  4️⃣  Determine whose turn it is next
             * ------------------------------------------------- */
            System.out.println(countX == countO ? "first" : "second");
        }
    }

    /** Reads exactly three lines of three characters each and builds a 3×3 board. */
    private static char[][] readBoard(BufferedReader br) throws IOException {
        char[][] board = new char[3][3];
        for (int i = 0; i < 3; i++) {
            String line = br.readLine();
            if (line == null) {
                throw new IOException("Input ended unexpectedly");
            }
            if (line.length() != 3) {
                throw new IOException("Each line must contain exactly three characters");
            }
            System.arraycopy(line.toCharArray(), 0, board[i], 0, 3);
        }
        return board;
    }

    /** Counts how many times `symbol` appears on the board. */
    private static int countSymbols(char[][] board, char symbol) {
        int count = 0;
        for (char[] row : board) {
            for (char cell : row) {
                if (cell == symbol) {
                    count++;
                }
            }
        }
        return count;
    }

    /** Returns true if the move counts respect the rule that X always moves first. */
    private static boolean isLegal(int countX, int countO) {
        return countX == countO || countX == countO + 1; // X can be equal or one more than O
    }

    /** Returns true if the board is completely filled. */
    private static boolean boardFull(int countX, int countO) {
        return countX + countO == 9;
    }

    /** Checks whether `player` has a winning line (row, column or diagonal). */
    private static boolean isWinning(char[][] board, char player) {
        // rows
        for (int i = 0; i < 3; i++) {
            if (board[i][0] == player && board[i][1] == player && board[i][2] == player) {
                return true;
            }
        }
        // columns
        for (int i = 0; i < 3; i++) {
            if (board[0][i] == player && board[1][i] == player && board[2][i] == player) {
                return true;
            }
        }
        // diagonals
        if (board[0][0] == player && board[1][1] == player && board[2][2] == player) {
            return true;
        }
        if (board[0][2] == player && board[1][1] == player && board[2][0] == player) {
            return true;
        }
        return false;
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;

/**
 * Tic‑Tac‑Toe validator.
 *
 * <p>Reads a 3×3 board from standard input and prints one of the following:
 * <ul>
 *   <li>"illegal" – the position cannot appear in a real game</li>
 *   <li>"the first player won"</li>
 *   <li>"the second player won"</li>
 *   <li>"draw"</li>
 *   <li>"first"</li> – next move belongs to the first player</li>
 *   <li>"second"</li> – next move belongs to the second player</li>
 * </ul>
 */
public class Problem3B {

    /** Symbols used on the board. */
    private enum Symbol { X, O, EMPTY }

    /** Size of the board. */
    private static final int N = 3;

    /** The game board. */
    private final Symbol[][] board = new Symbol[N][N];

    /** Number of X's and O's placed on the board. */
    private int xCount, oCount;

    /** --------------------------------------------------------------------- */
    /** Entry point. */
    public static void main(String[] args) throws IOException {
        Problem3B validator = new Problem3B();
        validator.readBoard();
        validator.validateAndPrintResult();
    }

    /** --------------------------------------------------------------------- */
    /** Reads nine characters (three rows) from stdin and fills the board. */
    private void readBoard() throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String line;
        for (int i = 0; i < N; i++) {
            line = br.readLine();
            if (line == null || line.length() != N) {
                throw new IllegalArgumentException("Each row must contain exactly 3 characters.");
            }
            for (int j = 0; j < N; j++) {
                board[i][j] = Symbol.valueOf(String.valueOf(line.charAt(j)).toUpperCase());
            }
            // Count X and O while reading
            for (int j = 0; j < N; j++) {
                if (board[i][j] == Symbol.X) xCount++;
                else if (board[i][j] == Symbol.O) oCount++;
            }
        }
    }

    /** --------------------------------------------------------------------- */
    /** Checks the position for any illegal state and prints the appropriate message. */
    private void validateAndPrintResult() {
        if (isIllegal()) {
            System.out.println("illegal");
            return;
        }

        boolean firstWon = hasWon(Symbol.X);
        boolean secondWon = hasWon(Symbol.O);

        if (firstWon && secondWon) {
            System.out.println("illegal");
            return;
        }
        if (firstWon && xCount == oCount) {          // X just played, O would have moved next
            System.out.println("illegal");
            return;
        }
        if (secondWon && xCount > oCount) {          // O just played, X cannot have extra move
            System.out.println("illegal");
            return;
        }
        if (firstWon) {
            System.out.println("the first player won");
            return;
        }
        if (secondWon) {
            System.out.println("the second player won");
            return;
        }
        if (isDraw()) {
            System.out.println("draw");
            return;
        }

        // No winner yet – decide whose turn it is
        System.out.println(xCount > oCount ? "second" : "first");
    }

    /** --------------------------------------------------------------------- */
    /** Determines whether the current board configuration is illegal. */
    private boolean isIllegal() {
        // Difference between X and O counts must be 0 or 1 and X must never be behind O
        if (Math.abs(xCount - oCount) > 1 || oCount > xCount) {
            return true;
        }
        return false;
    }

    /** --------------------------------------------------------------------- */
    /** Returns true if the given player has a complete row, column or diagonal. */
    private boolean hasWon(Symbol player) {
        // Check rows and columns
        for (int i = 0; i < N; i++) {
            if (rowCount(player, i) == N || columnCount(player, i) == N) {
                return true;
            }
        }
        // Check both diagonals
        if (diagonalCount(player, true) == N || diagonalCount(player, false) == N) {
            return true;
        }
        return false;
    }

    /** --------------------------------------------------------------------- */
    /** Counts how many times `player` appears in the given row. */
    private int rowCount(Symbol player, int row) {
        int cnt = 0;
        for (int col = 0; col < N; col++) {
            if (board[row][col] == player) cnt++;
        }
        return cnt;
    }

    /** --------------------------------------------------------------------- */
    /** Counts how many times `player` appears in the given column. */
    private int columnCount(Symbol player, int col) {
        int cnt = 0;
        for (int row = 0; row < N; row++) {
            if (board[row][col] == player) cnt++;
        }
        return cnt;
    }

    /** --------------------------------------------------------------------- */
    /** Counts `player` on the main diagonal (top‑left to bottom‑right). */
    private int mainDiagonalCount(Symbol player) {
        int cnt = 0;
        for (int i = 0; i < N; i++) {
            if (board[i][i] == player) cnt++;
        }
        return cnt;
    }

    /** --------------------------------------------------------------------- */
    /** Counts `player` on the anti‑diagonal (top‑right to bottom‑left). */
    private int antiDiagonalCount(Symbol player) {
        int cnt = 0;
        for (int i = 0; i < N; i++) {
            if (board[i][N - 1 - i] == player) cnt++;
        }
        return cnt;
    }

    /** --------------------------------------------------------------------- */
    /** Returns true if the board is full and no player has won (draw). */
    private boolean isDraw() {
        return xCount + oCount == N * N;
    }
}

import java.util.Scanner;

/**
 * Main class of the Tic‑Tac‑Toe utility.
 * It reads a 3×3 board, validates it and reports the game status.
 */
public class Main {

    private static final char EMPTY = ' ';

    public static void main(String[] args) {
        Board board = readBoardFromStdin();
        GameStatus status = evaluate(board);

        switch (status) {
            case ILLEGAL -> System.out.println("illegal");
            case FIRST_WON -> System.out.println("the first player won");
            case SECOND_WON -> System.out.println("the second player won");
            case DRAW -> System.out.println("draw");
            case FIRST_TURN -> System.out.println("first");
            case SECOND_TURN -> System.out.println("second");
        }
    }

    /** Reads three lines, each containing exactly three characters. */
    private static Board readBoardFromStdin() {
        Scanner scanner = new Scanner(System.in);
        char[][] cells = new char[3][3];
        for (int i = 0; i < 3; i++) {
            String line = scanner.next().trim();
            if (line.length() != 3) {
                throw new IllegalArgumentException("Each line must contain exactly 3 characters");
            }
            cells[i] = line.toCharArray();
        }
        return new Board(cells);
    }

    /** Evaluates the current board and returns the appropriate status. */
    private static GameStatus evaluate(Board board) {
        if (!Validator.isValid(board)) {
            return GameStatus.ILLEGAL;
        }

        if (board.hasWon('X')) {
            return GameStatus.FIRST_WON;
        }
        if (board.hasWon('0')) {
            return GameStatus.SECOND_WON;
        }

        if (board.isFull()) {
            return GameStatus.DRAW;
        }

        // Not terminal – announce whose turn it is
        return board.countX() == board.countO() ? GameStatus.FIRST_TURN : GameStatus.SECOND_TURN;
    }
}

/** Represents a 3×3 Tic‑Tac‑Toe board. */
final class Board {
    private final char[][] cells = new char[3][3];

    Board(char[][] source) {
        for (int r = 0; r < 3; r++) {
            System.arraycopy(source[r], 0, cells[r], 0, 3);
        }
    }

    char get(int row, int col) {
        return cells[row][col];
    }

    void set(int row, int col, char value) {
        cells[row][col] = value;
    }

    int count(char symbol) {
        int c = 0;
        for (char[] row : cells) {
            for (char cell : row) {
                if (cell == symbol) {
                    c++;
                }
            }
        }
        return c;
    }

    int countX() {
        return count('X');
    }

    int countO() {
        return count('0');
    }

    boolean isFull() {
        return countX() + countO() == 9;
    }

    boolean hasWon(char symbol) {
        // rows
        for (int r = 0; r < 3; r++) {
            if (cells[r][0] == symbol && cells[r][1] == symbol && cells[r][2] == symbol) {
                return true;
            }
        }
        // columns
        for (int c = 0; c < 3; c++) {
            if (cells[0][c] == symbol && cells[1][c] == symbol && cells[2][c] == symbol) {
                return true;
            }
        }
        // diagonals
        if (cells[0][0] == symbol && cells[1][1] == symbol && cells[2][2] == symbol) {
            return true;
        }
        if (cells[0][2] == symbol && cells[1][1] == symbol && cells[2][0] == symbol) {
            return true;
        }
        return false;
    }
}

/** Utility class that contains validation rules. */
final class Validator {

    /** Checks all game‑rules that must hold for a legal position. */
    static boolean isValid(Board board) {
        int xCount = board.countX();
        int oCount = board.countO();

        // The first player (X) always starts, so the difference must be 0 or 1.
        if (xCount - oCount < 0 || xCount - oCount > 1) {
            return false;
        }

        // Both players cannot win simultaneously.
        if (board.hasWon('X') && board.hasWon('0')) {
            return false;
        }

        // If X wins, there must be exactly one more X than O.
        if (board.hasWon('X') && xCount != oCount + 1) {
            return false;
        }

        // If O wins, the counts must be equal.
        if (board.hasWon('0') && xCount != oCount) {
            return false;
        }

        return true;
    }
}

/** Encapsulates the possible outcomes of the evaluation step. */
enum GameStatus {
    ILLEGAL,
    FIRST_WON,
    SECOND_WON,
    DRAW,
    FIRST_TURN,
    SECOND_TURN
}

import java.util.Scanner;

/**
 * Refactored Tic‑Tac‑Toe validator and interpreter.
 *
 * <p>
 * The program reads a 3×3 board from standard input, evaluates the current
 * position and prints one of the following messages:
 *
 * <ul>
 *   <li>the first player won
 *   <li>the second player won
 *   <li>draw
 *   <li>first   (first player to move next)
 *   <li>second  (second player to move next)
 *   <li>illegal (invalid board configuration)
 * </ul>
 * </p>
 *
 * <p>Refactoring goals:</p>
 * <ul>
 *   <li>Extracted constants for board size and symbols.</li>
 *   <li>Separated concerns (input, counting, validation, winner detection).</li>
 *   <li>Used small, well‑named methods instead of many similar helper
 *       procedures.</li>
 *   <li>Removed the mutable {@code firstwinner} / {@code secondwinner}
 *       flags in favour of explicit boolean results.</li>
 *   <li>Encapsulated the result‑producing logic in a single, easy‑to‑read
 *       method.</li>
 * </ul>
 */
public class TicTacToe {

    private static final int SIZE = 3;
    private static final char EMPTY = '.';
    private static final char PLAYER_X = 'X';   // first player
    private static final char PLAYER_O = 'O';   // second player

    /** Simple holder for the final text that must be printed. */
    private static final String ILLEGAL = "illegal";

    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            char[][] board = readBoard(scanner);
            ResultInfo info = analyse(board);
            System.out.println(info.message());
        }
    }

    /** Reads exactly three lines of three characters each and builds the board. */
    private static char[][] readBoard(Scanner scanner) {
        char[][] board = new char[SIZE][SIZE];
        for (int row = 0; row < SIZE; row++) {
            String line = scanner.nextLine().trim();
            if (line.length() != SIZE) {
                throw new IllegalArgumentException("Each line must contain exactly 3 characters");
            }
            for (int col = 0; col < SIZE; col++) {
                board[row][col] = line.charAt(col);
            }
        }
        return board;
    }

    /** Counts how many times {@code symbol} appears on the board. */
    private static int count(char[][] board, char symbol) {
        int cnt = 0;
        for (int i = 0; i < SIZE; i++) {
            for (int j = 0; j < SIZE; j++) {
                if (board[i][j] == symbol) {
                    cnt++;
                }
            }
        }
        return cnt;
    }

    /** Determines whether a player has three of his symbols in a row. */
    private static boolean hasWin(char[][] board, char symbol) {
        // Horizontal
        for (int i = 0; i < SIZE; i++) {
            if (rowHasThree(board, i, symbol)) {
                return true;
            }
        }
        // Vertical
        for (int j = 0; j < SIZE; j++) {
            if (columnHasThree(board, j, symbol)) {
                return true;
            }
        }
        // Diagonals
        if (diagonal1HasThree(board, symbol) || diagonal2HasThree(board, symbol)) {
            return true;
        }
        return false;
    }

    /** Checks a whole row for three of {@code symbol}. */
    private static boolean rowHasThree(char[][] board, int row, char symbol) {
        int cnt = 0;
        for (int col = 0; col < SIZE; col++) {
            if (board[row][col] == symbol) cnt++;
        }
        return cnt == 3;
    }

    /** Checks a whole column for three of {@code symbol}. */
    private static boolean columnHasThree(char[][] board, int col, char symbol) {
        int cnt = 0;
        for (int row = 0; row < SIZE; row++) {
            if (board[row][col] == symbol) cnt++;
        }
        return cnt == 3;
    }

    /** Checks the main diagonal (top‑left → bottom‑right). */
    private static boolean diagonal1HasThree(char[][] board, char symbol) {
        int cnt = 0;
        for (int i = 0; i < SIZE; i++) {
            if (board[i][i] == symbol) cnt++;
        }
        return cnt == 3;
    }

    /** Checks the anti‑diagonal (top‑right → bottom‑left). */
    private static boolean diagonal2HasThree(char[][] board, char symbol) {
        int cnt = 0;
        for (int i = 0; i < SIZE; i++) {
            if (board[i][SIZE - 1 - i] == symbol) cnt++;
        }
        return cnt == 3;
    }

    /** Holds intermediate data used when constructing the final output string. */
    private static final class ResultInfo {
        private final boolean xWon;
        private final boolean oWon;
        private final boolean hasEmpty;
        private final String message;

        ResultInfo(boolean xWon, boolean oWon, boolean hasEmpty, String message) {
            this.xWon = xWon;
            this.oWon = oWon;
            this.hasEmpty = hasEmpty;
            this.message = message;
        }

        String message() {
            return message;
        }
    }

    /** Analyzes a board and creates the appropriate output string. */
    private static ResultInfo analyse(char[][] board) {
        int xCount = count(board, PLAYER_X);
        int oCount = count(board, PLAYER_O);
        boolean hasEmpty = hasEmptyCell(board);

        boolean xWon = hasWin(board, PLAYER_X);
        boolean oWon = hasWin(board, PLAYER_O);

        // -------------------------------------------------------------------------
        // 1️⃣  Illegal configurations ------------------------------------------------
        // -------------------------------------------------------------------------
        if (Math.abs(xCount - oCount) > 1) {
            return new ResultInfo(false, false, hasEmpty, ILLEGAL);
        }
        if (xWon && oWon) {
            return new ResultInfo(false, false, hasEmpty, ILLEGAL);
        }
        if (xWon && xCount - oCount != 1) {
            return new ResultInfo(false, false, hasEmpty, ILLEGAL);
        }
        if (oWon && xCount != oCount) {
            return new ResultInfo(false, false, hasEmpty, ILLEGAL);
        }

        // -------------------------------------------------------------------------
        // 2️⃣  Winning outcomes -------------------------------------------------------
        // -------------------------------------------------------------------------
        if (xWon) {
            return new ResultInfo(false, false, hasEmpty,
                    "the first player won");
        }
        if (oWon) {
            return new ResultInfo(false, false, hasEmpty,
                    "the second player won");
        }

        // -------------------------------------------------------------------------
        // 3️⃣  No winner – decide next player or draw -------------------------------
        // -------------------------------------------------------------------------
        if (hasEmpty) {
            // The next player is first when X and O have been placed equally,
            // otherwise it is second.
            return new ResultInfo(false, false, true,
                    (xCount == oCount) ? "first" : "second");
        }
        // No empty cells and no winner → draw.
        return new ResultInfo(false, false, false, "draw");
    }

    /** Checks whether the board contains at least one empty cell ('.'). */
    private static boolean hasEmptyCell(char[][] board) {
        for (int i = 0; i < SIZE; i++) {
            for (int j = 0; j < SIZE; j++) {
                if (board[i][j] == EMPTY) {
                    return true;
                }
            }
        }
        return false;
    }
}

import java.util.Scanner;

/**
 * Tic‑Tac‑Toe validator and announcer.
 *
 * Reads a 3×3 board from standard input where:
 *   – 'X' denotes a move of the first player,
 *   – '0' denotes a move of the second player,
 *   – any other character denotes an empty cell.
 *
 * Prints one of the following:
 *   • "illegal"          – the board cannot appear in a legal game,
 *   • "the first player won",
 *   • "the second player won",
 *   • "draw",
 *   • "first" or "second" – whose turn it is next.
 *
 * The implementation is deliberately split into small, well‑named
 * methods to improve readability and maintainability.
 */
public class TicTacToe {

    /** Symbol for the first player (X). */
    private static final char FIRST = 'X';

    /** Symbol for the second player (0). */
    private static final char SECOND = '0';

    /** Board representation (3×3). */
    private static char[][] board = new char[3][3];

    /** Number of moves made by each player. */
    private static int countFirst;
    private static int countSecond;

    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            readBoard(scanner);
            countMoves();
            if (isIllegal()) {
                System.out.println("illegal");
                return;
            }
            if (bothPlayersWin()) {
                System.out.println("illegal");
                return;
            }
            if (hasWon(FIRST) && countFirst != countSecond + 1) {
                System.out.println("illegal");
                return;
            }
            if (hasWon(SECOND) && countFirst != countSecond) {
                System.out.println("illegal");
                return;
            }

            System.out.println(getGameStatus());
        }
    }

    /** Reads exactly three lines and stores the first three characters of each row. */
    private static void readBoard(Scanner scanner) {
        for (int i = 0; i < 3; i++) {
            String line = scanner.nextLine().trim();
            if (line.length() < 3) {
                throw new IllegalArgumentException("Each line must contain at least three characters.");
            }
            for (int j = 0; j < 3; j++) {
                board[i][j] = line.charAt(j);
            }
        }
    }

    /** Counts how many moves each player has made on the board. */
    private static void countMoves() {
        countFirst = 0;
        countSecond = 0;
        for (char[] row : board) {
            for (char cell : row) {
                if (cell == FIRST) {
                    countFirst++;
                } else if (cell == SECOND) {
                    countSecond++;
                }
            }
        }
    }

    /** Checks whether the current board violates the turn‑order rules. */
    private static boolean isIllegal() {
        // Legal configurations: countFirst == countSecond  OR  countFirst == countSecond + 1
        return !(countFirst == countSecond || countFirst == countSecond + 1);
    }

    /** Determines whether the given player has a winning line. */
    private static boolean hasWon(char player) {
        // Check rows
        for (int i = 0; i < 3; i++) {
            if (rowWins(i, player) || columnWins(i, player)) {
                return true;
            }
        }
        // Check diagonals
        return diagonalWins(player);
    }

    /** Returns true if a specific row is a winning line for the player. */
    private static boolean rowWins(int row, char player) {
        return board[row][0] == player && board[row][1] == player && board[row][2] == player;
    }

    /** Returns true if a specific column is a winning line for the player. */
    private static boolean columnWins(int col, char player) {
        return board[0][col] == player && board[1][col] == player && board[2][col] == player;
    }

    /** Returns true if either diagonal is a winning line for the player. */
    private static boolean diagonalWins(char player) {
        return (board[0][0] == player && board[1][1] == player && board[2][2] == player) ||
               (board[0][2] == player && board[1][1] == player && board[2][0] == player);
    }

    /** Checks whether both players have winning lines simultaneously. */
    private static boolean bothPlayersWin() {
        return hasWon(FIRST) && hasWon(SECOND);
    }

    /** Produces the textual result to be printed after all validation checks. */
    private static String getGameStatus() {
        // Board full and no winner → draw
        if (countFirst + countSecond == 9) {
            return "draw";
        }
        // Someone has won
        if (hasWon(FIRST)) {
            return "the first player won";
        }
        if (hasWon(SECOND)) {
            return "the second player won";
        }
        // Game still in progress – indicate whose turn is next
        return (countFirst == countSecond) ? "first" : "second";
    }
}

import java.util.Scanner;

/**
 * Represents a tiny Tic‑Tac‑Toe validator.
 *
 * <p>
 * The program reads a 3×3 board from standard input (3 lines, each containing exactly
 * three characters).  Valid characters are only 'X' and '0' (the digit ``0``).
 * It then determines whether the board state is legal and prints an appropriate
 * message:
 *
 * <ul>
 *   <li>“illegal”</li>
 *   <li>“the first player won”</li>
 *   <li>“the second player won”</li>
 *   <li>“draw”</li>
 *   <li>“second”</li>
 *   <li>“first”</li>
 * </ul>
 * </p>
 *
 * <p>All logic is split into well‑named static methods, making future extensions
 * or unit‑testing straightforward.</p>
 */
public final class TicTacToeValidator {

    /** The winning pattern for the first player ('X'). */
    private static final String FIRST_PLAYER_WIN = "XXX";

    /** The winning pattern for the second player ('0'). */
    private static final String SECOND_PLAYER_WIN = "000";

    private TicTacToeValidator() {
        /* Utility class – no instances. */
    }

    /**
     * Counts how many times a given character appears on the board.
     *
     * @param board the 3×3 board
     * @param symbol the symbol to count ('X' or '0')
     * @return occurrence count
     */
    private static int count(char symbol, char[][] board) {
        int cnt = 0;
        for (char[] row : board) {
            for (char cell : row) {
                if (cell == symbol) {
                    cnt++;
                }
            }
        }
        return cnt;
    }

    /**
     * Determines whether the supplied player has a winning line.
     *
     * @param board the 3×3 board
     * @param player the player symbol ('X' or '0')
     * @return true if the player has three in a row
     */
    private static boolean hasWon(char[][] board, char player) {
        String winPattern = "";
        switch (player) {
            case 'X' -> winPattern = FIRST_PLAYER_WIN;
            case '0' -> winPattern = SECOND_PLAYER_WIN;
            default -> return false;
        }

        // rows
        for (char[] row : board) {
            if (new String(row).equals(winPattern)) {
                return true;
            }
        }
        // columns
        for (int col = 0; col < 3; col++) {
            if (String.valueOf(board[0][col]) + board[1][col] + board[2][col]
                    .equals(winPattern)) {
                return true;
            }
        }
        // diagonals
        if (String.valueOf(board[0][0]) + board[1][1] + board[2][2].equals(winPattern)
                || String.valueOf(board[0][2]) + board[1][1] + board[2][0].equals(winPattern)) {
            return true;
        }
        return false;
    }

    /**
     * Checks whether the board configuration follows the games rules.
     *
     * <p>The rules are:</p>
     *
     * <ul>
     *   <li>Number of 'X' is either equal to the number of '0' or one greater.</li>
     *   <li>Both players cannot be winners at the same time.</li>
     *   <li>If the first player has won, the move counts must match the first condition above.</li>
     *   <li>If the second player has won, the move counts must match the second condition above.</li>
     * </ul>
     *
     * @param board the 3×3 board
     * @return true if the board is legal
     */
    private static boolean isLegal(char[][] board) {
        int xCount = count('X', board);
        int oCount = count('0', board);

        // Basic count consistency
        if (!(xCount == oCount || xCount == oCount + 1)) {
            return false;
        }

        boolean xWon = hasWon(board, 'X');
        boolean oWon = hasWon(board, '0');

        // Both cannot win simultaneously
        if (xWon && oWon) {
            return false;
        }

        // If X won, X must have made one more move than O
        if (xWon && !(xCount == oCount + 1)) {
            return false;
        }

        // If O won, move counts must be equal
        if (oWon && !(xCount == oCount)) {
            return false;
        }

        return true;
    }

    /**
     * Produces the final textual result based on the validated board.
     *
     * @param board the 3×3 board
     */
    private static void outputResult(char[][] board) {
        if (!isLegal(board)) {
            System.out.println("illegal");
            return;
        }

        boolean xWon = hasWon(board, 'X');
        boolean oWon = hasWon(board, '0');
        int xCount = count('X', board);
        int oCount = count('0', board);

        if (xWon) {
            System.out.println("the first player won");
        } else if (oWon) {
            System.out.println("the second player won");
        } else if (xCount + oCount == 9) {
            System.out.println("draw");
        } else if (xCount == oCount) {
            // It is X's turn next (because X starts)
            System.out.println("first");
        } else {
            // X has one extra move, so it is O's turn next
            System.out.println("second");
        }
    }

    /** Entry point – reads the board and prints the evaluation. */
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        char[][] board = new char[3][3];

        // Read exactly three tokens (each token must be 3 characters long)
        for (int i = 0; i < 3; i++) {
            String line = scanner.next();
            if (line.length() != 3) {
                System.out.println("illegal");
                return;
            }
            for (int j = 0; j < 3; j++) {
                char ch = line.charAt(j);
                if (ch != 'X' && ch != '0') {
                    System.out.println("illegal");
                    return;
                }
                board[i][j] = ch;
            }
        }

        outputResult(board);
        scanner.close();
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;

/**
 * Tic‑Tac‑Toe board validator and status reporter.
 *
 * <p>This class reads three lines from {@code stdin}, each containing three characters:
 * <ul>
 *   <li>'X'   – first player's move</li>
 *   <li>'0'   – second player's move (the original code used the digit zero to represent O)</li>
 *   <li>'.'   – empty cell</li>
 * </ul>
 * It then determines whether the board is legal, who has won (if anyone), and whose turn is next,
 * printing one of the following messages:
 * <pre>
 *   illegal
 *   the first player won
 *   the second player won
 *   draw
 *   first
 *   second
 * </pre>
 *
 * <p>The implementation follows the exact semantics of the original program but is split into
 * small, well‑named static methods and uses meaningful constant names.
 */
public class Game {

    /* ---------------------------------------------------------------------------
     *  Constants – they replace “magic numbers” from the original code
     * --------------------------------------------------------------------------- */
    private static final int EMPTY          = 0;   // empty cell value
    private static final int X_VALUE        = 50;  // value assigned to 'X' in input
    private static final int O_VALUE        = 15;  // value assigned to '0' (letter O) in input
    private static final int WIN_X          = X_VALUE * 3; // three X's sum -> 150
    private static final int WIN_O          = O_VALUE * 3; // three O's sum -> 45
    private static final int FULL_BOARD_SCORE = 310; // 5*X_VALUE + 4*O_VALUE (full board)

    /* ---------------------------------------------------------------------------
     *  Static state used throughout the computation
     * --------------------------------------------------------------------------- */
    private static int[][] board = new int[3][3];
    private static int xCount;          // number of X's on the board
    private static int oCount;          // number of O's on the board
    private static int totalScore;      // sum of all occupied cells (X + O values)
    private static int diff;            // xCount - oCount  (must be 0 or 1 for a legal board)
    private static final int[] winningLines = new int[8];
    private static boolean firstPlayerWon;
    private static boolean secondPlayerWon;

    /* ---------------------------------------------------------------------------
     *  Entry point
     * --------------------------------------------------------------------------- */
    public static void main(String[] args) throws IOException {
        readBoardFromStdin();
        computeWinningInformation();
        String status = evaluateBoard();
        System.out.println(status);
    }

    /* ---------------------------------------------------------------------------
     *  Input handling
     * --------------------------------------------------------------------------- */
    private static void readBoardFromStdin() throws IOException {
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
        String line;
        for (int row = 0; row < 3; row++) {
            line = reader.readLine();
            if (line == null) {
                throw new IOException("Expected three input lines");
            }
            parseRow(line, row);
        }
        reader.close();
    }

    private static void parseRow(String line, int row) {
        for (int col = 0; col < 3; col++) {
            char ch = line.charAt(col);
            switch (ch) {
                case 'X' -> placeValue(row, col, X_VALUE, xCount);
                case '0' -> placeValue(row, col, O_VALUE, oCount); // original used '0' for O
                default  -> placeValue(row, col, EMPTY, 0);        // '.' or any other char
            }
        }
    }

    /** Helper that updates the board, the counters and the running total. */
    private static void placeValue(int row, int col, int value, int counterVar) {
        board[row][col] = value;
        // increment the appropriate counter (the variable is accessed via the field)
        switch (value) {
            case X_VALUE -> {
                xCount++;
                totalScore += X_VALUE;
            }
            case O_VALUE -> {
                oCount++;
                totalScore += O_VALUE;
            }
        }
    }

    /* ---------------------------------------------------------------------------
     *  Game‑state computation
     * --------------------------------------------------------------------------- */
    private static void computeWinningInformation() {
        diff = xCount - oCount;
        computeWinningLineSums();
        firstPlayerWon = checkWins(WIN_X);
        secondPlayerWon = checkWins(WIN_O);
    }

    /** Calculates the sums of all possible winning lines and stores them in {@code winningLines}. */
    private static void computeWinningLineSums() {
        // rows
        winningLines[0] = board[0][0] + board[0][1] + board[0][2];
        winningLines[1] = board[1][0] + board[1][1] + board[1][2];
        winningLines[2] = board[2][0] + board[2][1] + board[2][2];
        // columns
        winningLines[3] = board[0][0] + board[1][0] + board[2][0];
        winningLines[4] = board[0][1] + board[1][1] + board[2][1];
        winningLines[5] = board[0][2] + board[1][2] + board[2][2];
        // diagonals
        winningLines[6] = board[0][0] + board[1][1] + board[2][2];
        winningLines[7] = board[0][2] + board[1][1] + board[2][0];
    }

    /** Checks whether any of the pre‑computed line sums matches the supplied target value. */
    private static boolean checkWins(int target) {
        for (int sum : winningLines) {
            if (sum == target) {
                return true;
            }
        }
        return false;
    }

    /* ---------------------------------------------------------------------------
     *  Board evaluation
     * --------------------------------------------------------------------------- */
    /** Main dispatcher that builds the final textual result. */
    private static String evaluateBoard() {
        if (isIllegalBoard()) {
            return "illegal";
        }
        if (firstPlayerWon && secondPlayerWon) {
            return "illegal";
        }
        if (firstPlayerWon) {
            return "the first player won";
        }
        if (secondPlayerWon) {
            return "the second player won";
        }
        if (isDraw()) {
            return "draw";
        }
        return whoseTurn();
    }

    /** Determines whether the current board configuration breaks the rules of Tic‑Tac‑Toe. */
    private static boolean isIllegalBoard() {
        // The difference between the number of X's and O's must be 0 or 1.
        if (diff != 0 && diff != 1) {
            return true;
        }
        // Both players cannot have winning lines simultaneously.
        if (firstPlayerWon && secondPlayerWon) {
            return true;
        }
        // If the first player won, they must have made exactly one more move than the second.
        if (firstPlayerWon && diff != 1) {
            return true;
        }
        // If the second player won, the move counts must be equal.
        if (secondPlayerWon && diff != 0) {
            return true;
        }
        return false;
    }

    /** The board is full when the total score equals the pre‑computed full‑board value. */
    private static boolean isDraw() {
        return totalScore == FULL_BOARD_SCORE;
    }

    /** Returns whose turn it is next, based on the move‑count difference. */
    private static String whoseTurn() {
        // diff == 0  → first player's turn, otherwise second player's turn
        return (diff == 0) ? "first" : "second";
    }
}

import java.util.Scanner;

/**
 * Refactored Tic‑Tac‑Toe validator.
 *
 * <p>This version separates concerns into small, pure methods, uses meaningful
 * names, eliminates magic numbers, and validates the board state before
 * printing a result.</p>
 */
public class Prob003C {

    /** Symbol used for the first player (X). */
    private static final char PLAYER_X = 'X';

    /** Symbol used for the second player (O). */
    private static final char PLAYER_O = '0';   // original code used the digit '0'

    /** Size of the board (3×3). */
    private static final int BOARD_SIZE = 3;

    /** Total number of cells on the board. */
    private static final int TOTAL_CELLS = BOARD_SIZE * BOARD_SIZE;

    public static void main(String[] args) {
        /* Try‑with‑resources guarantees the scanner is closed promptly. */
        try (Scanner scanner = new Scanner(System.in)) {
            char[][] board = readBoard(scanner);
            evaluateAndPrint(board);
        }
    }

    /** Reads three lines from {@code scanner} and builds the board array. */
    private static char[][] readBoard(Scanner scanner) {
        char[][] board = new char[BOARD_SIZE][BOARD_SIZE];
        for (int row = 0; row < BOARD_SIZE; row++) {
            String line = scanner.next();
            board[row] = line.toCharArray();
        }
        return board;
    }

    /** Orchestrates the whole validation flow and prints the outcome. */
    private static void evaluateAndPrint(char[][] board) {
        int xCount = countSymbols(board, PLAYER_X);
        int oCount = countSymbols(board, PLAYER_O);
        boolean xWon = hasWon(board, PLAYER_X);
        boolean oWon = hasWon(board, PLAYER_O);

        if (!isValidState(xCount, oCount, xWon, oWon)) {
            System.out.println("illegal");
            return;
        }

        if (xWon && !oWon) {
            System.out.println("the first player won");
            return;
        }
        if (oWon && !xWon) {
            System.out.println("the second player won");
            return;
        }
        if (xWon || oWon) {               // both won or an illegal win combo
            System.out.println("illegal");
            return;
        }
        if (isBoardFull(xCount, oCount)) {
            System.out.println("draw");
            return;
        }
        if (xCount == oCount) {
            System.out.println("first");
        } else {
            System.out.println("second");
        }
    }

    /** Counts how many times {@code symbol} appears on the board. */
    private static int countSymbols(char[][] board, char symbol) {
        int count = 0;
        for (int i = 0; i < BOARD_SIZE; i++) {
            for (int j = 0; j < BOARD_SIZE; j++) {
                if (board[i][j] == symbol) {
                    count++;
                }
            }
        }
        return count;
    }

    /** Returns {@code true} if the given symbol has a complete row, column or diagonal. */
    private static boolean hasWon(char[][] board, char symbol) {
        // check rows
        for (int row = 0; row < BOARD_SIZE; row++) {
            if (allEqual(board[row], symbol)) {
                return true;
            }
        }
        // check columns
        for (int col = 0; col < BOARD_SIZE; col++) {
            if (allEqual(column(board, col), symbol)) {
                return true;
            }
        }
        // check main diagonal
        if (diagonalMain(board, symbol)) {
            return true;
        }
        // check anti‑diagonal
        if (diagonalAnti(board, symbol)) {
            return true;
        }
        return false;
    }

    /** Helper that checks whether every element of an array equals {@code symbol}. */
    private static boolean allEqual(char[] arr, char symbol) {
        for (char c : arr) {
            if (c != symbol) {
                return false;
            }
        }
        return true;
    }

    /** Returns the column at {@code colIndex} as a new array. */
    private static char[] column(char[][] board, int colIndex) {
        char[] col = new char[BOARD_SIZE];
        for (int row = 0; row < BOARD_SIZE; row++) {
            col[row] = board[row][colIndex];
        }
        return col;
    }

    /** Checks the main diagonal (top‑left → bottom‑right). */
    private static boolean diagonalMain(char[][] board, char symbol) {
        for (int i = 0; i < BOARD_SIZE; i++) {
            if (board[i][i] != symbol) {
                return false;
            }
        }
        return true;
    }

    /** Checks the anti‑diagonal (top‑right → bottom‑left). */
    private static boolean diagonalAnti(char[][] board, char symbol) {
        for (int i = 0; i < BOARD_SIZE; i++) {
            if (board[i][BOARD_SIZE - 1 - i] != symbol) {
                return false;
            }
        }
        return true;
    }

    /**
     * Validates the overall game state.
     *
     * <ul>
     *   <li>Number of X's must be equal to or one greater than number of O's.</li>
     *   <li>Both players cannot be winners simultaneously.</li>
     *   <li>If X wins, there must be exactly one more X than O.</li>
     *   <li>If O wins, the counts must be equal.</li>
     * </ul>
     */
    private static boolean isValidState(int xCount, int oCount, boolean xWon, boolean oWon) {
        if (!(xCount == oCount || xCount == oCount + 1)) {
            return false;
        }
        if (xWon && oWon) {
            return false;
        }
        if (xWon && xCount != oCount + 1) {
            return false;
        }
        if (oWon && xCount != oCount) {
            return false;
        }
        return true;
    }

    /** Determines whether the board is completely filled. */
    private static boolean isBoardFull(int xCount, int oCount) {
        return xCount + oCount == TOTAL_CELLS;
    }
}

import java.util.*;

public class TicTacToe {

    /** Symbols used on the board */
    private static final char EMPTY = '.';
    private static final char PLAYER_X = 'X';
    private static final char PLAYER_O = '0';

    /** All possible winning lines */
    private static final List<int[]> WINNING_LINES = List.of(
            // rows
            new int[]{0, 1, 2},
            new int[]{3, 4, 5},
            new int[]{6, 7, 8},
            // columns
            new int[]{0, 3, 6},
            new int[]{1, 4, 7},
            new int[]{2, 5, 8},
            // diagonals
            new int[]{0, 4, 8},
            new int[]{2, 4, 6}
    );

    /** Flattened index mapping for WINNING_LINES */
    private static final int IDX(int r, int c) { return r * 3 + c; }

    /** Reads the whole game board from stdin */
    private static char[][] readBoard(Scanner scanner) {
        char[][] board = new char[3][3];
        int xCount = 0;
        int oCount = 0;
        boolean hasEmpty = false;

        for (int row = 0; row < 3; ++row) {
            String line = scanner.nextLine().trim();
            if (line.length() != 3) {
                throw new IllegalArgumentException("Each line must contain exactly 3 characters");
            }
            for (int col = 0; col < 3; ++col) {
                char cell = line.charAt(col);
                board[row][col] = cell;
                switch (cell) {
                    case PLAYER_X -> xCount++;
                    case PLAYER_O -> oCount++;
                    case EMPTY -> hasEmpty = true;
                    default -> throw new IllegalArgumentException("Invalid character: " + cell);
                }
            }
        }
        return new GameState(board, xCount, oCount, hasEmpty);
    }

    /** Contains all derived information needed for evaluation */
    private static final class GameState {
        final char[][] board;
        final int xCount;
        final int oCount;
        final boolean hasEmpty;

        GameState(char[][] board, int xCount, int oCount, boolean hasEmpty) {
            this.board = board;
            this.xCount = xCount;
            this.oCount = oCount;
            this.hasEmpty = hasEmpty;
        }
    }

    /** Determines whose turn it is (null if the state is illegal) */
    private static String determineTurn(GameState state) {
        int diff = state.xCount - state.oCount;
        if (diff > 1 || diff < 0) {
            return "illegal";
        }
        if (state.oCount > state.xCount) {
            return "illegal";
        }
        return state.xCount > state.oCount ? "second" : "first";
    }

    /** Checks for winners and validates the result against the move counts */
    private static Result evaluateWinner(GameState state) {
        List<String> winners = new ArrayList<>();

        // Scan every winning line
        for (int[] line : WINNING_LINES) {
            int a = line[0] / 3, b = line[0] % 3;
            int c = line[1] / 3, d = line[1] % 3;
            int e = line[2] / 3, f = line[2] % 3;

            char cellA = state.board[a][b];
            char cellB = state.board[c][d];
            char cellC = state.board[e][f];

            if (cellA != EMPTY && cellA == cellB && cellA == cellC) {
                winners.add(cellA == PLAYER_X ? "X" : "0");
            }
        }

        // Remove draws / illegal symbols
        winners.removeIf(s -> s.equals("."));

        // More than one distinct winner -> illegal board
        if (winners.size() > 1) {
            return Result.ILLEGAL;
        }

        // Validate winner against move counts
        if (!winners.isEmpty()) {
            String winnerSymbol = winners.get(0);
            if (winnerSymbol.equals("X") && state.oCount > state.xCount) {
                return Result.ILLEGAL;
            }
            if (winnerSymbol.equals("0") && state.xCount != state.oCount) {
                return Result.ILLEGAL;
            }
            return winnerSymbol.equals("X")
                    ? Result.FIRST_WON
                    : Result.SECOND_WON;
        }

        // No winner
        return state.hasEmpty ? Result.IN_PROGRESS : Result.DRAW;
    }

    /** Encapsulation of the possible evaluation outcomes */
    private enum Result {
        ILLEGAL,
        FIRST_WON,
        SECOND_WON,
        DRAW,
        IN_PROGRESS
    }

    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            GameState state = readBoard(scanner);
            Result result = evaluateWinner(state);

            switch (result) {
                case ILLEGAL -> System.out.println("illegal");
                case FIRST_WON -> System.out.println("the first player won");
                case SECOND_WON -> System.out.println("the second player won");
                case DRAW -> System.out.println("draw");
                case IN_PROGRESS -> System.out.println(determineTurn(state));
            }
        } catch (IllegalArgumentException e) {
            System.out.println("illegal");
        }
    }
}

/*
 * Refactored version of the original "foxandtwodots" program.
 * The functionality stays exactly the same – it detects whether any
 * character forms a cycle of length ≥ 4 on the grid.
 * Improvements:
 *   • Clear naming and separation of concerns.
 *   • Constant directions and helper methods.
 *   • Predictable resource handling (try‑with‑resources).
 *   • No System.exit() inside recursion – control flow is explicit.
 *   • Reduced nesting and duplicated code.
 */
import java.io.*;
import java.util.*;

public class FoxAndTwoDots {

    /* ---------- Direction handling ------------------------------------- */
    private static final class Direction {
        final int dx, dy;
        Direction(int dx, int dy) { this.dx = dx; this.dy = dy; }
        int[] offset() { return new int[]{dx, dy}; }
    }

    private static final Direction[] DIRS = {
            new Direction(1, 0),   // down
            new Direction(-1, 0),  // up
            new Direction(0, 1),   // right
            new Direction(0, -1)   // left
    };

    /* ---------- Core fields -------------------------------------------- */
    private static char[][] grid;      // the character matrix
    private static boolean[][] visited; // visited flag matrix
    private static int rows, cols;    // dimensions

    /* ---------- Entry point ------------------------------------------- */
    public static void main(String[] args) throws Exception {
        // Use try‑with‑resources to guarantee the PrintWriter is closed.
        try (PrintWriter out = new PrintWriter(System.out)) {
            FastScanner fs = new FastScanner(System.in);

            rows = fs.nextInt();
            cols = fs.nextInt();

            // Read the grid line by line.
            grid = new char[rows][];
            for (int r = 0; r < rows; r++) {
                grid[r] = fs.readString().trim().toCharArray();
            }

            visited = new boolean[rows][cols];

            // Scan every cell; start a DFS from each unvisited one.
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (!visited[r][c] && hasCycle(r, c, -1, -1, grid[r][c])) {
                        out.println("Yes");
                        return;                 // terminate early on success
                    }
                }
            }
            out.println("No");
        }
    }

    /**
     * Depth‑first search that looks for a cycle of the same character.
     *
     * @param x      current row
     * @param y      current column
     * @param fromX  previous cell row  (‑1 / ‑1 means “no parent” for the start)
     * @param fromY  previous cell column
     * @param ch     character we are currently exploring
     * @return true if a cycle was found in this component
     */
    private static boolean hasCycle(int x, int y, int fromX, int fromY, char ch) {
        visited[x][y] = true;

        for (Direction dir : DIRS) {
            int nx = x + dir.dx;
            int ny = y + dir.dy;

            // 1) stay inside the grid
            if (!isInside(nx, ny)) {
                continue;
            }
            // 2) same character?
            if (grid[nx][ny] != ch) {
                continue;
            }

            if (!visited[nx][ny]) {
                // Recurse deeper.
                if (hasCycle(nx, ny, x, y, ch)) {
                    return true;
                }
            } else if (nx != fromX || ny != fromY) {
                // Visited neighbor that is NOT the immediate parent → cycle.
                return true;
            }
        }
        return false; // no cycle through this path
    }

    /** Checks bounds of the cell (x, y). */
    private static boolean isInside(int x, int y) {
        return x >= 0 && x < rows && y >= 0 && y < cols;
    }

    /* ---------- Fast input utility -------------------------------------- */
    /**
     * Lightweight scanner that mimics the original {@code InputReader}
     * but is self‑contained and does not expose a public interface.
     */
    private static class FastScanner {
        private final InputStream stream;
        private final byte[] buffer = new byte[8192];
        private int pointer = 0;
        private int length = 0;

        FastScanner(InputStream stream) {
            this.stream = stream;
        }

        private int readByte() throws IOException {
            if (pointer >= length) {
                length = stream.read(buffer);
                pointer = 0;
                if (length <= 0) {
                    return -1; // end of stream
                }
            }
            return buffer[pointer++];
        }

        int nextInt() throws IOException {
            int c;
            do {
                c = readByte();
            } while (c <= ' ');          // skip whitespace

            boolean negative = false;
            if (c == '-') {
                negative = true;
                c = readByte();
            }

            int value = 0;
            do {
                value = value * 10 + (c - '0');
                c = readByte();
            } while (c > ' ');

            return negative ? -value : value;
        }

        /** Returns the next non‑whitespace token as a {@code String}. */
        String readString() throws IOException {
            StringBuilder sb = new StringBuilder();
            int c;
            do {
                c = readByte();
            } while (c <= ' ');          // skip leading whitespace

            do {
                sb.append((char) c);
                c = readByte();
            } while (c > ' ');              // accumulate until next whitespace

            return sb.toString();
        }

        /** Returns true for typical whitespace characters. */
        boolean isSpaceChar(int ch) {
            return ch == ' ' || ch == '\n' || ch == '\r' || ch == '\t';
        }
    }
}

import java.util.ArrayDeque;
import java.util.Deque;
import java.util.Scanner;

/**
 * Refactored solution for the “Fox and Two Dots” problem.
 *
 * The original code mixed input handling, board manipulation and
 * depth‑first search in a single class with many static mutable fields.
 * This version separates concerns, uses meaningful names, avoids raw
 * types and follows a clear coding style that is easier to maintain
 * and extend.
 */
public class FoxAndTwoDots {

    /** Symbol used for an empty cell (originally ‘0’). */
    private static final int EMPTY = 0;

    /** Symbol used to mark cells that have been removed during processing
     * (originally the integer value of the character ‘1’). */
    private static final int MARKED = 1;

    /** Direction vectors for the four orthogonal neighbours. */
    private static final int[] DR = { -1, 1, 0, 0 };
    private static final int[] DC = { 0, 0, -1, 1 };

    /** Board dimensions */
    private int rows;
    private int columns;

    /** 2‑D representation of the board. */
    private int[][] board;

    /** Stack (actually a Deque) used for depth‑first traversal. */
    private final Deque<Position> stack = new ArrayDeque<>();

    /** Number of times the special termination condition was hit. */
    private int terminationCount = 0;

    /** --------------------------------------------------------------------- *
     *  Entry point
     *  --------------------------------------------------------------------- */
    public static void main(String[] args) {
        new FoxAndTwoDots().run();
    }

    /** --------------------------------------------------------------------- *
     *  Orchestrates the whole workflow: input → processing → output
     *  --------------------------------------------------------------------- */
    private void run() {
        readDimensionsAndBoard();
        processBoard();
        printResult();
    }

    /** --------------------------------------------------------------------- *
     *  Reads the board size and the board itself from standard input.
     *  --------------------------------------------------------------------- */
    private void readDimensionsAndBoard() {
        try (Scanner scanner = new Scanner(System.in)) {
            rows = scanner.nextInt();
            columns = scanner.nextInt();
            scanner.nextLine(); // consume end‑of‑line

            board = new int[rows][columns];
            for (int r = 0; r < rows; r++) {
                String line = scanner.nextLine();
                for (int c = 0; c < columns; c++) {
                    board[r][c] = line.charAt(c); // ASCII code of the character
                }
            }
        }
    }

    /** --------------------------------------------------------------------- *
     *  Main algorithm: try to expand each connected component until either
     *  the whole board can be cleared or the special termination condition
     *  (board contains a ‘1’) is hit.
     *  --------------------------------------------------------------------- */
    private void processBoard() {
        // Walk the board row‑by‑row
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < columns; c++) {
                int cell = board[r][c];
                if (cell != EMPTY) {
                    // start a new search from this cell
                    search(r, c, cell, r, c);
                    // after each search the board must be cleared of temporary marks
                    clearTemporaryMarks();
                }
                // OPTIONAL: If the board already contains a ‘1’ we could abort early.
                // The original program always cleared the board after each outer loop,
                // so we keep the same semantics.
                clearAllMarks();
            }
        }
    }

    /** --------------------------------------------------------------------- *
     *  Depth‑first search starting at (startRow,startCol) with the initial
     *  character value `alpha`.  The search follows neighbours that have the
     *  same `alpha` value or are already marked (value == MARKED).
     *
     *  @param startR   row of the current cell
     *  @param startC   column of the current cell
     *  @param alpha    the character value we are trying to connect
     *  @param fromR    parent row (used to avoid going back)
     *  @param fromC    parent column
     *  --------------------------------------------------------------------- */
    private void search(int startR, int startC, int alpha, int fromR, int fromC) {
        board[startR][startC] = MARKED;            // mark as visited in this traversal
        int popped = 0;                            // how many positions we have pushed
        // Explore the four orthogonal neighbours
        for (int dir = 0; dir < 4; dir++) {
            int nextR = startR + DR[dir];
            int nextC = startC + DC[dir];
            if (!isInBounds(nextR, nextC)) {
                continue;
            }

            int neighbourValue = board[nextR][nextC];
            if (neighbourValue == alpha) {
                // same character – push position for later recursion
                stack.push(new Position(nextR, nextC));
                popped++;
            } else if (neighbourValue == MARKED) {
                // we have hit a cell that was marked in a deeper recursion level;
                // this signals the termination condition required by the problem.
                terminationCount = 1;
                return;
            }
        }

        // Recursively process everything that was pushed onto the stack.
        // The order does not matter for correctness, only for determinism.
        while (!stack.isEmpty()) {
            Position pos = stack.pop();
            search(pos.row, pos.column, alpha, startR, startC);
        }
    }

    /** --------------------------------------------------------------------- *
     *  Removes all temporary marks (value == MARKED) from the board.
     *  This mirrors the behaviour of the original program that cleared the
     *  board after each inner loop iteration.
     *  --------------------------------------------------------------------- */
    private void clearTemporaryMarks() {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < columns; c++) {
                if (board[r][c] == MARKED) {
                    board[r][c] = EMPTY;
                }
            }
        }
    }

    /** --------------------------------------------------------------------- *
     *  Clears *all* MARKED cells regardless of location – the original code
     *  performed a full board scan after each outer loop iteration.
     *  --------------------------------------------------------------------- */
    private void clearAllMarks() {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < columns; c++) {
                if (board[r][c] == MARKED) {
                    board[r][c] = EMPTY;
                }
            }
        }
    }

    /** --------------------------------------------------------------------- *
     *  Simple helper to check if a coordinate is inside the board.
     *  --------------------------------------------------------------------- */
    private boolean isInBounds(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < columns;
    }

    /** --------------------------------------------------------------------- *
     *  Small immutable container for a board position.
     *  --------------------------------------------------------------------- */
    private static final class Position {
        final int row;
        final int column;

        Position(int row, int column) {
            this.row = row;
            this.column = column;
        }
    }

    /** --------------------------------------------------------------------- *
     *  Prints “Yes” if the termination condition was hit exactly once,
     *  otherwise prints “No”.  This reproduces the output of the original
     *  program.
     *  --------------------------------------------------------------------- */
    private void printResult() {
        System.out.println(terminationCount == 1 ? "Yes" : "No");
    }
}

import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.io.IOException;

/**
 * Detects whether a grid contains a cycle of at least four cells that all have the same character.
 */
public class CfContest {

    /** Directions: up, down, left, right */
    private static final int[] DRI = {-1, 1, 0, 0};
    private static final int[] DRC = {0, 0, -1, 1};

    /** Buffered reader used to consume standard input. */
    private BufferedReader reader;

    /** Grid dimensions. */
    private int rows, cols;

    /** 2‑D character array that stores the board. */
    private char[][] board;

    /** Visited flag for each cell. */
    private boolean[][] visited;

    /** True once a cycle of length ≥ 4 is discovered. */
    private boolean cycleFound;

    public static void main(String[] args) throws IOException {
        new CfContest().run();
    }

    /** Initializes the reader and starts the whole process. */
    private void run() throws IOException {
        initializeReader();
        readDimensionsAndBoard();
        visited = new boolean[rows][cols];
        cycleFound = false;

        searchForCycle();

        System.out.println(cycleFound ? "Yes" : "No");
    }

    /** Creates a BufferedReader wrapping System.in. */
    private void initializeReader() {
        reader = new BufferedReader(new InputStreamReader(System.in));
    }

   /** Reads the first two tokens as dimensions and the subsequent lines as the board. */
    private void readDimensionsAndBoard() throws IOException {
        rows = nextInt();
        cols = nextInt();

        board = new char[rows][cols];
        for (int r = 0; r < rows; r++) {
            String line = next();
            for (int c = 0; c < cols; c++) {
                board[r][c] = line.charAt(c);
            }
        }
    }

    /** Main search driver – iterates over each unvisited cell. */
    private void searchForCycle() {
        for (int r = 0; r < rows && !cycleFound; r++) {
            for (int c = 0; c < cols && !cycleFound; c++) {
                if (!visited[r][c]) {
                    dfs(r, c, -1, -1);
                }
            }
        }
    }

    /**
     * Depth‑first search that looks for a cycle of the same character.
     *
     * @param r      current row
     * @param c      current column
     * @param pr     previous row (or -1 if none)
     * @param pc     previous column (or -1 if none)
     */
    private void dfs(int r, int c, int pr, int pc) {
        visited[r][c] = true;

        for (int d = 0; d < 4; d++) {
            int nr = r + DRI[d];
            int nc = c + DRC[d];

            // ignore the cell we came from
            if (nr == pr && nc == pc) {
                continue;
            }
            // stay inside the board boundaries
            if (!isInside(nr, nc)) {
                continue;
            }
            // same character is required to continue the cycle
            if (board[nr][nc] != board[r][c]) {
                continue;
            }

            if (visited[nr][nc]) {
                // we have reached a visited node that isn’t the parent → a cycle
                cycleFound = true;
                return;
            }

            dfs(nr, nc, r, c);
        }
    }

    /** Returns {@code true} if the supplied coordinates are inside the board. */
    private boolean isInside(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    /* --------------------------------------------------------------------- */
    /* Convenience wrappers around the BufferedReader – they keep the API   */
    /* similar to the original FastReader implementation.                    */
    /* --------------------------------------------------------------------- */

    /** Reads the next token (skipping any whitespace). */
    private String next() throws IOException {
        while (true) {
            String line = reader.readLine();
            if (line == null) {
                return null;
            }
            String[] parts = line.split("\\s+");
            for (String part : parts) {
                if (!part.isEmpty()) {
                    return part;
                }
            }
        }
    }

    /** Reads the next integer token. */
    private int nextInt() throws IOException {
        return Integer.parseInt(next());
    }

    /** Reads the next long token. */
    private long nextLong() throws IOException {
        return Long.parseLong(next());
    }

    /** Reads the next double token. */
    private double nextDouble() throws IOException {
        return Double.parseDouble(next());
    }
}

import java.io.*;
import java.util.*;

public class Solution {
    private static final int[] dx = {1, -1, 0, 0};
    private static final int[] dy = {0, 0, 1, -1};
    private static int gridSizeRows;
    private static int gridSizeCols;

    public static boolean check(int[][] grid, int i, int j) {
        return i >= 1 && i <= gridSizeRows && j >= 1 && j <= gridSizeCols;
    }

    private static boolean dfsCycleDetection(int[][] grid, boolean[][] visited, int i, int j, int prevI, int prevJ) {
        if (visited[i][j]) {
            return true;
        }
        visited[i][j] = true;

        for (int k = 0; k < 4; k++) {
            int nextI = i + dx[k];
            int nextJ = j + dy[k];

            if (nextI == prevI && nextJ == prevJ) {
                continue;
            }

            if (check(grid, nextI, nextJ) && grid[i][j] == grid[nextI][nextJ]) {
                if (dfsCycleDetection(grid, visited, nextI, nextJ, i, j)) {
                    return true;
                }
            }
        }
        visited[i][j] = false;
        return false;
    }

    private static void solve(int[][] grid, boolean[][] visited) {
        for (int i = 1; i <= gridSizeRows; i++) {
            for (int j = 1; j <= gridSizeCols; j++) {
                if (dfsCycleDetection(grid, visited, i, j, -1, -1)) {
                    System.out.println("Yes");
                    return;
                }
            }
        }
        System.out.println("No");
    }

    public static void main(String[] args) throws IOException {
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
        String[] dimensions = reader.readLine().split(" ");
        int rows = Integer.parseInt(dimensions[0]);
        int cols = Integer.parseInt(dimensions[1]);

        gridSizeRows = rows;
        gridSizeCols = cols;

        int[][] grid = new int[rows + 2][cols + 2];
        boolean[][] visited = new boolean[rows + 2][cols + 2];

        // Initialize border cells to 1 (blocked)
        for (int i = 0; i < rows + 2; i++) {
            for (int j = 0; j < cols + 2; j++) {
                if (i == 0 || j == 0 || i == rows + 1 || j == cols + 1) {
                    grid[i][j] = 1;
                }
            }
        }

        // Read grid data
        for (int i = 1; i <= rows; i++) {
            String line = reader.readLine();
            for (int j = 1; j <= cols; j++) {
                grid[i][j] = line.charAt(j - 1) - 'A';
            }
        }

        solve(grid, visited);
    }
}

import java.io.*;
import java.util.StringTokenizer;

/**
 * Detects whether an {@code n × m} grid contains a cycle of at least four
 * adjacent cells that share the same character.
 *
 * <p>The algorithm performs a depth‑first search on each unvisited cell.
 * During the search we keep three visitation states:
 *
 * <ul>
 *   <li>{@code UNVISITED} – the cell has never been processed,
 *   <li>{@code VISITING}  – the cell is on the current recursion stack,
 *   <li>{@code VISITED}  – all of its neighbours have been processed.
 * </ul>
 *
 * <p>If during the DFS we reach a neighbour that is already {@code VISITING}
 * and that neighbour is *not* the cell we came from, a cycle exists.
 *
 * <p>The program follows standard Java naming conventions, uses
 * try‑with‑resources for I/O, and keeps all mutable state encapsulated
 * within the {@code Main} class.
 */
public class Main {

    /** Unvisited marker */
    private static final int UNVISITED = 0;
    /** Currently being visited marker */
    private static final int VISITING = 1;
    /** Fully processed marker */
    private static final int VISITED = 2;

    /** The grid read from input */
    private static char[][] grid;
    /** Visitation state for each cell */
    private static int[][] state;

    /** Directions: right, left, up, down */
    private static final int[] DX = {0, 0, -1, 1};
    private static final int[] DY = {1, -1, 0, 0};

    public static void main(String[] args) throws Exception {
        /* ---------- Input handling (try‑with‑resources) ---------- */
        try (BufferedReader br = new BufferedReader(
                new InputStreamReader(System.in))
        ) {
            StringTokenizer st = new StringTokenizer(br.readLine());
            int n = Integer.parseInt(st.nextToken());
            int m = Integer.parseInt(st.nextToken());

            grid = new char[n][m];
            state = new int[n][m];

            for (int i = 0; i < n; i++) {
                String line = br.readLine();
                for (int j = 0; j < m; j++) {
                    grid[i][j] = line.charAt(j);
                }
            }

            /* ---------- Cycle detection ---------- */
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    if (state[i][j] == UNVISITED && dfs(i, j, -1, -1)) {
                        System.out.println("Yes");
                        return;
                    }
                }
            }
            System.out.println("No");
        }
    }

    /**
     * Depth‑first search that returns {@code true} as soon as a cycle of the
     * required length is discovered.
     *
     * @param x       current row index
     * @param y       current column index
     * @param fromX   row of the cell we arrived from (or -1 if none)
     * @param fromY   column of the cell we arrived from (or -1 if none)
     * @return {@code true} if a valid cycle is found in this branch
     */
    private static boolean dfs(int x, int y, int fromX, int fromY) {
        state[x][y] = VISITING;

        for (int dir = 0; dir < 4; dir++) {
            int nx = x + DX[dir];
            int ny = y + DY[dir];

            // Bounds check
            if (nx < 0 || nx >= grid.length || ny < 0 || ny >= grid[0].length) {
                continue;
            }

            char curColor = grid[x][y];
            char nextColor = grid[nx][ny];

            // Only continue along cells of the same colour
            if (nextColor != curColor) {
                continue;
            }

            if (state[nx][ny] == UNVISITED) {
                // Dive deeper only if neighbour has not been visited yet
                if (dfs(nx, ny, x, y)) {
                    return true;
                }
            } else if (state[nx][ny] == VISITING && !(nx == fromX && ny == fromY)) {
                // Found a back‑edge to a node that is currently on the recursion stack
                // and that is not the cell we came from → a cycle exists
                return true;
            }
        }

        // Mark the cell as completely processed before returning
        state[x][y] = VISITED;
        return false;
    }
}

/*
 *  Refactored solution for the original problem.
 *  The program reads an n × m grid of characters,
 *  interprets each character as a digit or a minus sign,
 *  and determines whether a path that follows equal‑valued cells
 *  can reach a cell containing the sentinel value –1.
 *
 *  Changes made for readability and maintainability:
 *   •  Input handling encapsulated in a small `FastScanner`.
 *   •  Grid representation wrapped in a `Board` class.
 *   •  Directions expressed with an enum.
 *   •  Core algorithm lives in a `Solver` class – no static mutable fields.
 *   •  Meaningful names, Javadoc‑style comments and small helper methods.
 *   •  No global mutable state; the flow is linear in `main`.
 *
 *  Compile & run:
 *      javac Main.java
 *      java Main   (provide input on stdin)
 */

import java.io.*;
import java.util.*;

public class Main {

    /* --------------------------------------------------------------------- */
    /*  Fast, reusable scanner                                                */
    /* --------------------------------------------------------------------- */
    private static final class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner(InputStream in) {
            this.br = new BufferedReader(new InputStreamReader(in));
        }

        /** @return true if there is another token to read */
        boolean hasNext() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                String line = br.readLine();
                if (line == null) {
                    return false;
                }
                st = new StringTokenizer(line);
            }
            return true;
        }

        /** @return next token as a string */
        String next() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                st = new StringTokenizer(br.readLine());
            }
            return st.nextToken();
        }

        /** @return next line (may be empty) */
        String nextLine() throws IOException {
            String line = br.readLine();
            return line == null ? "" : line;
        }

        /** @return next integer token */
        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }

    /* --------------------------------------------------------------------- */
    /*  Directions – up, down, left, right                                   */
    /* --------------------------------------------------------------------- */
    private enum Direction {
        UP(-1, 0), DOWN(1, 0), LEFT(0, -1), RIGHT(0, 1);

        private final int dr;
        private final int dc;

        Direction(int dr, int dc) {
            this.dr = dr;
            this.dc = dc;
        }

        int deltaRow() { return dr; }
        int deltaCol() { return dc; }

        /** Returns the first character of the enum name (U/D/L/R). */
        char initial() { return name().charAt(0); }
    }

    /* --------------------------------------------------------------------- */
    /*  Board – holds the values and a visited‑mark matrix                    */
    /* --------------------------------------------------------------------- */
    private static final class Board {
        private final int rows;
        private final int cols;
        private final int[][] values;      // positive numbers or -1 (sentinel)
        private final boolean[][] visited;  // marks cells already explored in a branch

        Board(int rows, int cols) {
            this.rows = rows;
            this.cols = cols;
            this.values = new int[rows][cols];
            this.visited = new boolean[rows][cols];
        }

        /** Store a value at (r,c). */
        void setValue(int r, int c, int v) {
            values[r][c] = v;
        }

        /** Retrieve the stored value at (r,c). */
        int getValue(int r, int c) {
            return values[r][c];
        }

        /** Mark a cell as visited. */
        void markVisited(int r, int c) {
            visited[r][c] = true;
        }

        /** Check whether a cell has been visited. */
        boolean isVisited(int r, int c) {
            return visited[r][c];
        }

        /** True if (r,c) lies inside the board limits. */
        boolean inBounds(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }
    }

    /* --------------------------------------------------------------------- */
    /*  Solver – encapsulates the depth‑first search logic                    */
    /* --------------------------------------------------------------------- */
    private static final class Solver {
        private final Board board;
        private boolean found;               // becomes true when -1 is reached

        Solver(Board board) {
            this.board = board;
            this.found = false;
        }

        /** Initiates a search from every positive cell. */
        boolean solve() {
            for (int r = 0; r < board.rows(); r++) {
                for (int c = 0; c < board.cols(); c++) {
                    int v = board.getValue(r, c);
                    if (v > 0) {
                        dfs(r, c, ' ', v);
                        if (found) {
                            return true;
                        }
                    }
                }
            }
            return false;
        }

        /** Recursive depth‑first search.
         *
         *  @param r        current row
         *  @param c        current column
         *  @param incomingDirection   direction from which we arrived (ignored for the start cell)
         *  @param curVal                value that must stay equal while traversing
         */
        private void dfs(int r, int c, char incomingDirection, int curVal) {
            if (found) {
                return;
            }
            if (!board.inBounds(r, c)) {
                return;
            }
            int cellVal = board.getValue(r, c);
            if (cellVal == -1) {               // sentinel reached
                found = true;
                return;
            }
            if (cellVal != curVal) {
                return;                        // value mismatch – prune
            }
            board.markVisited(r, c);

            for (Direction d : Direction.values()) {
                // Do not go back the way we came
                if (d.initial() == incomingDirection) {
                    continue;
                }
                int nr = r + d.deltaRow();
                int nc = c + d.deltaCol();
                if (board.inBounds(nr, nc) && !board.isVisited(nr, nc)) {
                    dfs(nr, nc, d.initial(), curVal);
                    if (found) {
                        return;
                    }
                }
            }
        }
    }

    /* --------------------------------------------------------------------- */
    /*  Program entry point                                                   */
    /* --------------------------------------------------------------------- */
    public static void main(String[] args) throws Exception {
        try (FastScanner sc = new FastScanner(System.in)) {
            int n = sc.nextInt();          // number of rows
            int m = sc.nextInt();          // number of columns

            Board board = new Board(n, m);
            // Expect exactly n lines; each line contains m characters.
            for (int i = 0; i < n; i++) {
                String line = sc.nextLine();
                // Guard against missing newline at the end of input
                if (line == null) {
                    line = "";
                }
                for (int j = 0; j < m; j++) {
                    char ch = line.charAt(j);
                    if (ch == '-') {
                        board.setValue(i, j, -1);
                    } else {
                        // Convert the digit character to its integer value
                        board.setValue(i, j, Character.digit(ch, 10));
                    }
                }
            }

            Solver solver = new Solver(board);
            boolean reachable = solver.solve();

            System.out.println(reachable ? "Yes" : "No");
        }
    }
}

