/**
 * Core logic for Problem B.
 * Encapsulates the board and cycle‑detection algorithm.
 */
class Solver {

    // -----------------------------------------------------------------------
    // Direction vectors – right, left, down, up
    // -----------------------------------------------------------------------
    private static final int[] DX = {0, 0, 1, -1};
    private static final int[] DY = {1, -1, 0, 0};

    // Board state
    private char[][] field;          // input characters with a safe border
    private boolean[][] visited;     // marks cells already processed
    private int rows;                  // number of rows (excluding border)
    private int cols;                  // number of columns (excluding border)

    /**
     * Reads the input, searches for a cycle and writes the result.
     *
     * @param scanner source of tokens
     * @param out     destination for the answer
     */
    public void solve(FastScanner scanner, PrintWriter out) {
        rows = scanner.nextInt();
        cols = scanner.nextInt();

        // Allocate board with a one‑cell border to simplify neighbour checks
        field = new char[rows + 2][cols + 2];
        visited = new boolean[rows + 2][cols + 2];

        // Fill the inner rectangle (1‑based coordinates)
        for (int i = 1; i <= rows; i++) {
            char[] line = scanner.nextWord().toCharArray();
            System.arraycopy(line, 0, field[i], 1, cols);
        }

        boolean hasCycle = false;
        for (int i = 1; i <= rows; i++) {
            for (int j = 1; j <= cols; j++) {
                if (!visited[i][j]) {
                    if (hasCycle(i, j, -1, -1)) {
                        hasCycle = true;
                        break;
                    }
                }
            }
            if (hasCycle) {
                break;
            }
        }

        out.print(hasCycle ? "Yes" : "No");
    }

    /**
     * Depth‑first search that looks for a cycle of equal characters.
     *
     * @param i      current row index (1‑based)
     * @param j      current column index (1‑based)
     * @param pi     previous row (to avoid immediate back‑track)
     * @param pj     previous column
     * @return true if a cycle was found from this cell
     */
    private boolean hasCycle(int i, int j, int pi, int pj) {
        if (visited[i][j]) {
            // Returning to an already visited cell means we completed a cycle.
            return true;
        }

        visited[i][j] = true;

        for (int d = 0; d < DX.length; d++) {
            int ni = i + DX[d];
            int nj = j + DY[d];

            // Skip the cell we came from
            if (ni == pi && nj == pj) {
                continue;
            }

            // Continue only when neighbour shares the same character
            if (field[i][j] == field[ni][nj] && hasCycle(ni, nj, i, j)) {
                return true;
            }
        }
        return false;
    }
}

/**
 * Minimal fast scanner that tokenises the supplied {@link InputStream}.
 * It hides the raw {@code BufferedReader} behind a simple token API.
 */
class FastScanner {

    private final BufferedReader reader;
    private StringTokenizer tokenizer;

    /** Creates a scanner that reads from the given stream. */
    public FastScanner(InputStream stream) {
        reader = new BufferedReader(new InputStreamReader(stream));
    }

    /** Returns the next integer token. */
    public int nextInt() {
        return Integer.parseInt(next());
    }

    /** Returns the next token as a character array. */
    public char[] nextWord() {
        return next().toCharArray();
    }

    /** Returns the next token as a {@code String}. */
    public String next() {
        while (tokenizer == null || !tokenizer.hasMoreTokens()) {
            try {
                String line = reader.readLine();
                if (line == null) {
                    return null;                     // EOF reached
                }
                tokenizer = new StringTokenizer(line);
            } catch (IOException e) {
                throw new UncheckedIOException(e);
            }
        }
        return tokenizer.nextToken();
    }

    /** Returns the next complete line, or {@code null} on EOF. */
    public String nextLine() {
        try {
            return reader.readLine();
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
    }
}

import java.io.IOException;
import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;

/**
 * Program reads a grid of characters and determines whether the cells
 * that share the same colour and are orthogonally adjacent form a
 * cycle when considered as an undirected graph.
 */
public class Main {

    /** Entry point */
    public static void main(String[] args) throws IOException {
        // Use try‑with‑resources to guarantee the scanner is closed
        try (Scanner scanner = new Scanner(System.in)) {
            int rows = scanner.nextInt();   // n
            int cols = scanner.nextInt();   // m

            // Read the grid
            char[][] grid = new char[rows][];
            for (int i = 0; i < rows; i++) {
                grid[i] = scanner.next().toCharArray();
            }

            // Build the adjacency graph
            Graph graph = buildGraph(grid, rows, cols);

            // Cycle detection
            boolean hasCycle = graph.hasCycle();

            System.out.println(hasCycle ? "Yes" : "No");
        }
    }

    /**
     * Creates an undirected graph where each vertex corresponds to a cell in the grid.
     * Vertices are connected when neighbouring cells have the same character.
     *
     * @param grid   2‑D character grid
     * @param rows   number of rows
     * @param cols   number of columns
     * @return       Graph representing adjacency of equal‑coloured neighbours
     */
    private static Graph buildGraph(char[][] grid, int rows, int cols) {
        int vertexCount = rows * cols;
        Graph graph = new Graph(vertexCount);

        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                int current = i * cols + j;

                // Right neighbour
                if (j + 1 < cols && grid[i][j] == grid[i][j + 1]) {
                    int neighbour = i * cols + (j + 1);
                    graph.addUndirectedEdge(current, neighbour);
                }

                // Down neighbour
                if (i + 1 < rows && grid[i][j] == grid[i + 1][j]) {
                    int neighbour = (i + 1) * cols + j;
                    graph.addUndirectedEdge(current, neighbour);
                }
            }
        }
        return graph;
    }

    /**
     * Simple undirected graph implementation using adjacency lists.
     * Vertices are identified by the indices {@code 0,…,size-1}.
     */
    public static final class Graph {
        private final List<Integer>[] adjacency;
        private final int vertexCount;

        /**
         * Constructs a graph with the given number of vertices.
         *
         * @param vertexCount number of vertices
         */
        public Graph(int vertexCount) {
            this.vertexCount = vertexCount;
            @SuppressWarnings("unchecked")
            List<Integer>[] list = new List[vertexCount];
            for (int i = 0; i < vertexCount; i++) {
                list[i] = new ArrayList<>();
            }
            this.adjacency = list;
        }

        /**
         * Adds an undirected edge between {@code u} and {@code v}.
         *
         * @param u first vertex index
         * @param v second vertex index
         * @throws IllegalArgumentException if either index is out of range
         */
        public void addUndirectedEdge(int u, int v) {
            if (u < 0 || u >= vertexCount || v < 0 || v >= vertexCount) {
                throw new IllegalArgumentException("Vertex index out of range");
            }
            adjacency[u].add(v);
            adjacency[v].add(u);
        }

        /**
         * Detects whether the graph contains any cycle (undirected).
         *
         * @return {@code true} if a cycle exists, otherwise {@code false}
         */
        public boolean hasCycle() {
            boolean[] visited = new boolean[vertexCount];
            for (int v = 0; v < vertexCount; v++) {
                if (!visited[v]) {
                    if (dfsCycle(v, -1, visited)) {
                        return true;
                    }
                }
            }
            return false;
        }

        /**
         * Depth‑first search that searches for a back‑edge to an already visited node
         * that is not the parent node – the hallmark of a cycle in an undirected graph.
         *
         * @param current vertex currently being explored
         * @param parent  previous vertex in the traversal, or {@code -1} for the root
         * @param visited array indicating which vertices have been visited
         * @return {@code true} if a cycle is found in this branch, otherwise {@code false}
         */
        private boolean dfsCycle(int current, int parent, boolean[] visited) {
            visited[current] = true;

            for (int neighbour : adjacency[current]) {
                if (!visited[neighbour]) {
                    if (dfsCycle(neighbour, current, visited)) {
                        return true;
                    }
                } else if (neighbour != parent) {
                    // Back edge to a visited node that isn't the parent → cycle
                    return true;
                }
            }
            return false;
        }
    }
}

import java.io.*;
