import java.util.StringTokenizer;

/**
 * Entry point of the program.
 * <p>
 * Reads a grid of characters, builds an undirected graph where vertices are cells
 * that contain the same character and are adjacent horizontally or vertically,
 * then determines whether the graph contains a cycle.
 * </p>
 */
public class Round290B {

    /** Global output writer used for printing results. */
    private static PrintWriter out;

    /** Fast scanner for reading input data. */
    private static InputReader scanner;

    /** --------------------------------------------------------------------- */
    /**                         MAIN LOGIC                                   */
    /** --------------------------------------------------------------------- */

    public static void main(String[] args) {
        scanner = new InputReader();
        out = new PrintWriter(new BufferedOutputStream(System.out));
        solve();
        out.close();
    }

    /**
     * Core workflow:
     * <ul>
     *   <li>Read grid dimensions and the grid itself.</li>
     *   <li>Transform each cell into a vertex id.</li>
     *   <li>Connect equal‑valued adjacent cells.</li>
     *   <li>Detect whether the resulting graph contains a cycle.</li>
     *   <li>Output "Yes" if a cycle exists, otherwise "No".</li>
     * </ul>
     */
    private static void solve() {
        int n = scanner.nextInt();
        int m = scanner.nextInt();
        char[][] grid = new char[n][];
        for (int i = 0; i < n; i++) {
            String line = scanner.next();
            grid[i] = line.toCharArray();
        }

        Graph graph = buildGraph(grid, n, m);
        boolean hasCycle = graph.hasCycle();
        out.println(hasCycle ? "Yes" : "No");
    }

    /**
     * Constructs the undirected graph.
     *
     * @param grid   character matrix representing the board
     * @param rows   number of rows of the grid
     * @param cols   number of columns of the grid
     * @return an instance of {@link Graph} that contains edges between equal,
     *         horizontally or vertically adjacent cells.
     */
    private static Graph buildGraph(char[][] grid, int rows, int cols) {
        int vertexCount = rows * cols;
        Graph graph = new Graph(vertexCount);

        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                int curId = i * cols + j;

                // Horizontal edge – look only to the right to avoid double work
                if (j + 1 < cols && grid[i][j] == grid[i][j + 1]) {
                    int neighbourId = i * cols + (j + 1);
                    graph.addEdge(curId, neighbourId);
                }

                // Vertical edge – look only downwards
                if (i + 1 < rows && grid[i][j] == grid[i + 1][j]) {
                    int neighbourId = (i + 1) * cols + j;
                    graph.addEdge(curId, neighbourId);
                }
            }
        }

        return graph;
    }

    /** --------------------------------------------------------------------- */
    /**                     GRAPH IMPLEMENTATION                               */
    /** --------------------------------------------------------------------- */

    /**
     * Simple undirected graph based on adjacency lists.
     */
    static class Graph {
        private final int vertexCount;
        /** Array of adjacency lists, one per vertex. */
        private final List<Integer>[] adjacency;

        Graph(int vertexCount) {
            this.vertexCount = vertexCount;
            adjacency = new ArrayList[vertexCount];
            for (int i = 0; i < vertexCount; i++) {
                adjacency[i] = new ArrayList<>();
            }
        }

        /** Adds an undirected edge {@code src} – {@code dest}. */
        void addEdge(int src, int dest) {
            adjacency[src].add(dest);
            adjacency[dest].add(src);
        }

        /**
         * Checks whether the graph contains any cycle.
         * The method uses a depth‑first search with parent tracking,
         * which correctly identifies cycles in an undirected graph.
         *
         * @return {@code true} if a cycle exists, {@code false} otherwise.
         */
        boolean hasCycle() {
            boolean[] visited = new boolean[vertexCount];
            for (int v = 0; v < vertexCount; v++) {
                if (!visited[v] && dfsDetectCycle(v, -1, visited)) {
                    return true;
                }
            }
            return false;
        }

        /**
         * Recursive DFS that looks for a cycle.
         *
         * @param current   vertex currently being explored
         * @param parent    identifier of the calling vertex (or -1 for the root)
         * @param visited   marks vertices that have already been processed
         * @return {@code true} if a cycle is found in the explored branch
         */
        private boolean dfsDetectCycle(int current, int parent, boolean[] visited) {
            visited[current] = true;
            for (int neighbour : adjacency[current]) {
                if (!visited[neighbour]) {
                    if (dfsDetectCycle(neighbour, current, visited)) {
                        return true;
                    }
                } else if (neighbour != parent) {
                    // Back‑edge to an already visited vertex that is not the parent
                    return true;
                }
            }
            return false;
        }
    }

    /** --------------------------------------------------------------------- */
    /**                     FAST INPUT READER                                 */
    /** --------------------------------------------------------------------- */

    /**
     * Minimal fast scanner based on {@link BufferedReader} and {@link StringTokenizer}.
     */
    private static class InputReader {
        private final BufferedReader br;
        private StringTokenizer st;

        InputReader() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        /**
         * Returns the next token from {@link #st}. If the tokenizer is exhausted,
         * it reads a new line and re‑initialises the tokenizer.
         */
        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    throw new UncheckedIOException(e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        // Additional parsing methods can be added here if needed.
    }
}

import java.util.Scanner;

/**
 * Detects whether a 2‑dimensional grid contains a cycle of at least four
 * connected cells that share the same character.
 *
 * <p>This implementation is a refactor of the original program with the
 * following improvements:</p>
 * <ul>
 *   <li>Clear separation of concerns (input handling, grid representation,
 *       cycle detection).</li>
 *   <li>Descriptive naming for variables and methods.</li>
 *   <li>Constants for direction vectors and grid dimensions.</li>
 *   <li>Javadoc documentation for public types.</li>
 *   <li>Reduced duplicate code by looping over the four neighbours.</li>
 *   <li>Early exit as soon as a cycle is found.</li>
 * </ul>
 */
public class Cycle {

    /** Grid containing the characters. */
    private static char[][] grid;

    /** Marks cells that have already been processed. */
    private static boolean[][] visited;

    /** Number of rows and columns in the grid. */
    private static int rows, cols;

    /** All possible movement directions (up, down, left, right). */
    private static final int[][] DIRECTIONS = {
            {-1, 0},   // up
            {1, 0},    // down
            {0, -1},   // left
            {0, 1}     // right
    };

    public static void main(String[] args) {
        /* ---------- Input handling ---------- */
        try (Scanner scanner = new Scanner(System.in)) {
            rows = scanner.nextInt();
            cols = scanner.nextInt();
            scanner.nextLine(); // consume the newline after the dimensions

            grid = new char[rows][cols];
            visited = new boolean[rows][cols];

            for (int r = 0; r < rows; r++) {
                String line = scanner.nextLine();
                grid[r] = line.toCharArray();
            }

            /* ---------- Cycle detection ---------- */
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (!visited[r][c]) {
                        // start a DFS from an unvisited cell
                        if (hasCycleFrom(r, c, -1, -1)) {
                            System.out.println("Yes");
                            return; // terminate immediately
                        }
                    }
                }
            }

            // No cycle found after scanning the whole grid
            System.out.println("No");
        }
    }

    /**
     * Depth‑first search that looks for a cycle beginning at {@code (x, y)}.
     *
     * @param x       current row index
     * @param y       current column index
     * @param px      previous row index (or -1 if none)
     * @param py      previous column index (or -1 if none)
     * @return {@code true} if a cycle was detected from this cell,
     *         otherwise {@code false}
     */
    private static boolean hasCycleFrom(int x, int y, int px, int py) {
        visited[x][y] = true;

        for (int[] dir : DIRECTIONS) {
            int nx = x + dir[0];
            int ny = y + dir[1];

            // 1. Stay inside the grid
            if (!inBounds(nx, ny)) {
                continue;
            }

            // 2. Same character is required to continue a potential cycle
            if (grid[nx][ny] != grid[x][y]) {
                continue;
            }

            // 3. Do not go back to the immediate parent (avoids trivial back‑edge)
            if (nx == px && ny == py) {
                continue;
            }

            // 4. If the neighbour has already been visited we have found a cycle
            if (visited[nx][ny]) {
                System.out.println("Yes");
                System.exit(0);
            }

            // 5. Recurse deeper
            if (hasCycleFrom(nx, ny, x, y)) {
                return true;
            }
        }

        return false;
    }

    /** Checks whether a given cell lies inside the grid boundaries. */
    private static boolean inBounds(int x, int y) {
        return x >= 0 && x < rows && y >= 0 && y < cols;
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.ArrayList;
import java.util.List;

/**
 * Detects whether the graph built from equal‑adjacent cells contains a component
 * with more edges than vertices‑1 (i.e. a cycle) and prints "Yes" or "No".
 */
public class Solution {

    /** Simple immutable container for DFS component statistics. */
    private static final class ComponentInfo {
        final int vertexCount;
        final int degreeSum;

        ComponentInfo(int vertexCount, int degreeSum) {
            this.vertexCount = vertexCount;
            this.degreeSum = degreeSum;
        }
    }

    public static void main(String[] args) throws IOException {
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(System.in))) {
            // -----------------------------------------------------------------
            // 1️⃣  Read matrix dimensions and data
            // -----------------------------------------------------------------
            String[] header = reader.readLine().trim().split("\\s+");
            int rows = Integer.parseInt(header[0]);
            int cols = Integer.parseInt(header[1]);

            char[][] grid = new char[rows][cols];
            for (int r = 0; r < rows; r++) {
                String line = reader.readLine();
                for (int c = 0; c < cols; c++) {
                    grid[r][c] = line.charAt(c);
                }
            }

            // -----------------------------------------------------------------
            // 2️⃣  Build adjacency list of the implicit undirected graph
            // -----------------------------------------------------------------
            List<List<Integer>> graph = buildAdjacencyList(grid, rows, cols);
            boolean[] visited = new boolean[rows * cols];

            // -----------------------------------------------------------------
            // 3️⃣  Explore each connected component
            // -----------------------------------------------------------------
            for (int v = 0; v < rows * cols; v++) {
                if (!visited[v]) {
                    ComponentInfo info = dfs(graph, v, visited);
                    int edgeCount = info.degreeSum / 2;   // each edge counted twice
                    int vertexCount = info.vertexCount;
                    if (edgeCount > vertexCount - 1) {
                        System.out.println("Yes");
                        return;
                    }
                }
            }

            System.out.println("No");
        }
    }

    /**
     * Constructs an undirected adjacency list where each vertex corresponds to a
     * cell and edges connect side‑adjacent cells with identical characters.
     */
    private static List<List<Integer>> buildAdjacencyList(char[][] grid, int rows, int cols) {
        int totalVertices = rows * cols;
        List<List<Integer>> adjacency = new ArrayList<>(totalVertices);
        for (int i = 0; i < totalVertices; i++) {
            adjacency.add(new ArrayList<>());
        }

        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                int curIdx = index(r, c, cols);
                // Up neighbour
                if (r > 0 && grid[r][c] == grid[r - 1][c]) {
                    int neighbourIdx = index(r - 1, c, cols);
                    addUndirectedEdge(adjacency, curIdx, neighbourIdx);
                }
                // Left neighbour
                if (c > 0 && grid[r][c] == grid[r][c - 1]) {
                    int neighbourIdx = index(r, c - 1, cols);
                    addUndirectedEdge(adjacency, curIdx, neighbourIdx);
                }
            }
        }
        return adjacency;
    }

    /** Linear index calculation: row * cols + col */
    private static int index(int row, int col, int cols) {
        return row * cols + col;
    }

    /** Adds an undirected edge (a ↔ b) to the adjacency list. */
    private static void addUndirectedEdge(List<List<Integer>> adjacency, int a, int b) {
        adjacency.get(a).add(b);
        adjacency.get(b).add(a);
    }

    /**
     * Depth‑first search that gathers the number of vertices and the sum of
     * degrees in the connected component containing {@code start}.
     */
    private static ComponentInfo dfs(List<List<Integer>> graph, int start, boolean[] visited) {
        visited[start] = true;
        int vertices = 1;
        int degreeSum = graph.get(start).size();

        for (int neighbour : graph.get(start)) {
            if (!visited[neighbour]) {
                ComponentInfo sub = dfs(graph, neighbour, visited);
                vertices += sub.vertexCount;
                degreeSum += sub.degreeSum;
            }
        }
        return new ComponentInfo(vertices, degreeSum);
    }
}

import java.io.*;
import java.util.*;

public class MazeCycleDetector {

    /* Directions: down, up, right, left */
    private static final int[] DX = {1, -1, 0, 0};
    private static final int[] DY = {0, 0, 1, -1};

    /** The character grid read from input. */
    private char[][] grid;

    /** Tracks visited cells during DFS. */
    private boolean[][] visited;

    /** Set to true as soon as any cycle is detected. */
    private boolean hasCycle;

    /** Entry point. */
    public static void main(String[] args) throws IOException {
        // Use try‑with‑resources to guarantee the BufferedReader is closed.
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in))) {
            MazeCycleDetector detector = new MazeCycleDetector();
            detector.readInput(br);
            detector.detectCycle();
            System.out.println(detector.hasCycle ? "Yes" : "No");
        }
    }

    /** Reads dimensions and exactly `rows * cols` characters that form the grid. */
    private void readInput(BufferedReader br) throws IOException {
        // First line contains the dimensions.
        String[] dims = br.readLine().trim().split("\\s+");
        if (dims.length < 2) {
            throw new IllegalArgumentException("Expected at least two integers for rows and columns.");
        }
        int rows = Integer.parseInt(dims[0]);
        int cols = Integer.parseInt(dims[1]);

        // Collect exactly `rows * cols` characters (they may be split across several lines).
        StringBuilder chars = new StringBuilder();
        while (chars.length() < rows * cols) {
            String line = br.readLine();
            if (line == null) {
                throw new EOFException("Unexpected end of input while reading grid characters.");
            }
            chars.append(line.trim());
        }

        // Build the 2‑D char array.
        grid = new char[rows][cols];
        int idx = 0;
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                grid[r][c] = chars.charAt(idx++);
            }
        }

        // Reset auxiliary structures.
        visited = new boolean[rows][cols];
        hasCycle = false;
    }

    /** Initiates a DFS from each unvisited cell looking for cycles of equal characters. */
    private void detectCycle() {
        for (int r = 0; r < grid.length && !hasCycle; r++) {
            for (int c = 0; c < grid[0].length && !hasCycle; c++) {
                if (!visited[r][c]) {
                    dfs(r, c, -1, -1, '\0');
                }
            }
        }
    }

    /** Depth‑first search that marks visited cells and detects back‑edges forming a cycle. */
    private void dfs(int r, int c, int pr, int pc, char fromChar) {
        visited[r][c] = true;

        for (int dir = 0; dir < DX.length; dir++) {
            int nr = r + DX[dir];
            int nc = c + DY[dir];

            if (!inBounds(nr, nc)) {
                continue;
            }

            char currentChar = grid[r][c];

            // Only consider edges that connect cells with the same character.
            if (grid[nr][nc] != currentChar) {
                continue;
            }

            if (!visited[nr][nc]) {
                dfs(nr, nc, r, c, currentChar);
                if (hasCycle) {
                    return;
                }
            } else if (nr != pr || nc != pc) {
                // A visited neighbour that is not the immediate parent indicates a cycle.
                hasCycle = true;
                return;
            }
        }
    }

    /** Utility to check whether a coordinate lies inside the grid. */
    private boolean inBounds(int x, int y) {
        return x >= 0 && x < grid.length && y >= 0 && y < grid[0].length;
    }
}

import java.io.*;
import java.util.*;

/**
 * Refactored solution for detecting a cycle of adjacent equal characters
 * in a grid.  The program reads an {@code n × m} grid from standard input,
 * adds a one‑cell border for simpler bounds checking, and prints {@code "Yes"}
 * if a cycle exists, otherwise {@code "No"}.
 *
 * The refactor focuses on:
 *   • Separation of concerns (input handling, border setup, cycle detection)
 *   • Meaningful names and constants
 *   • Use of {@link AutoCloseable} for resource safety
 *   • Immutable direction vectors
 *   • Clear method contracts and Javadoc comments
 */
public class Main {

    /** Fast scanner that implements {@link AutoCloseable}. */
    private static final class FastScanner implements AutoCloseable {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        FastScanner(Reader reader) {
            this.reader = new BufferedReader(reader);
            this.tokenizer = new StringTokenizer("");
        }

        /** Returns the next lexical token, reading a new line if necessary. */
        private String prepareTokenizer() throws IOException {
            while (!tokenizer.hasMoreTokens()) {
                String line = reader.readLine();
                if (line == null) {
                    return null;
                }
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        String next() {
            return prepareTokenizer();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        long nextLong() {
            return Long.parseLong(next());
        }

        double nextDouble() {
            return Double.parseDouble(next());
        }

        /** Returns the whole next line (including possible leading/trailing spaces). */
        String nextLine() {
            try {
                return reader.readLine();
            } catch (IOException e) {
                throw new UncheckedIOException(e);
            }
        }

        @Override
        public void close() throws IOException {
            reader.close();
        }
    }

    /** Detects whether the grid contains a cycle of equal characters. */
    private static final class CycleDetector {
        /** Directions: up, left, right, down */
        private static final int[] DX = {-1, 0, 0, 1};
        private static final int[] DY = {0, -1, 1, 0};

        private final char[][] grid;
        private final boolean[][] visited;
        private final int effectiveRows;
        private final int effectiveCols;

        CycleDetector(char[][] grid, boolean[][] visited) {
            this.grid = grid;
            this.visited = visited;
            // Inner part of the grid (excluding the added border)
            this.effectiveRows = grid.length - 2;
            this.effectiveCols = grid[0].length - 2;
        }

        /** Entry point – returns {@code true} if any cycle exists. */
        boolean hasCycle() {
            for (int r = 1; r <= effectiveRows; r++) {
                for (int c = 1; c <= effectiveCols; c++) {
                    if (!visited[r][c] && dfs(r, c, r, c)) {
                        return true;
                    }
                }
            }
            return false;
        }

        /** Depth‑first search that looks for a previously visited cell of the same
         *  character that is not the immediate parent. */
        private boolean dfs(int curX, int curY, int prevX, int prevY) {
            if (visited[curX][curY]) {
                return true;                    // Cycle detected
            }
            visited[curX][curY] = true;

            char current = grid[curX][curY];
            for (int d = 0; d < 4; d++) {
                int nx = curX + DX[d];
                int ny = curY + DY[d];

                if (!isInside(nx, ny)) {
                    continue;
                }
                if (grid[nx][ny] != current) {
                    continue;
                }
                if (nx == prevX && ny == prevY) {
                    continue;                     // Do not go back to parent
                }
                if (dfs(nx, ny, curX, curY)) {
                    return true;                  // Propagate cycle detection upward
                }
            }
            return false;
        }

        /** Checks bounds of the effective grid (excluding the outer border). */
        private boolean isInside(int x, int y) {
            return x >= 1 && x <= effectiveRows && y >= 1 && y <= effectiveCols;
        }
    }

    /** Program entry point. */
    public static void main(String[] args) {
        // Try‑with‑resources guarantees that the scanner (and underlying reader)
        // is closed as soon as we leave the block.
        try (FastScanner scanner = new FastScanner(new InputStreamReader(System.in))) {
            int n = scanner.nextInt();   // number of rows
            int m = scanner.nextInt();   // number of columns

            // Create a grid with a one‑cell padding on all sides.
            char[][] grid = new char[n + 2][m + 2];
            boolean[][] visited = new boolean[n + 2][m + 2];

            // Fill the interior of the grid (the padded border stays at its default value).
            for (int i = 1; i <= n; i++) {
                String line = scanner.nextLine().trim(); // consume the rest of the current line
                // The next token after n and m is the first row of the grid.
                line = scanner.nextLine().trim();        // actual row content
                for (int j = 1; j <= m; j++) {
                    grid[i][j] = line.charAt(j - 1);
                }
            }

            CycleDetector detector = new CycleDetector(grid, visited);
            System.out.println(detector.hasCycle() ? "Yes" : "No");
        } catch (IOException e) {
            // In competitive‑programming contexts we generally do not need a stack trace.
            // For production code this would be logged or handled more gracefully.
            throw new UncheckedIOException(e);
        }
    }
}

import java.util.Scanner;

/**
 * Detects whether a cycle of identical characters exists in a grid.
 * A cycle is defined as a closed path of length ≥ 2 where you can move
 * up, down, left or right to adjacent cells that share the same character
 * and return to a previously visited cell that is not the immediate parent.
 */
public class Main {

    /* ---------- constants for traversal ---------- */
    private static final int UNVISITED = 0;
    private static final int VISITING  = 1;
    private static final int VISITED   = 2;

    // direction vectors: right, down, left, up
    private static final int[] DR = {0, 1, 0, -1};
    private static final int[] DC = {1, 0, -1, 0};

    public static void main(String[] args) {
        try (Scanner sc = new Scanner(System.in)) {
            int rows = sc.nextInt();
            int cols = sc.nextInt();
            char[][] grid = new char[rows][cols];

            // read one line per row (no spaces between characters)
            for (int r = 0; r < rows; r++) {
                String line = sc.next();
                System.arraycopy(line.toCharArray(), 0, grid[r], 0, cols);
            }

            boolean hasCycle = false;
            int[][] state = new int[rows][cols];   // tracks UNVISITED / VISITING / VISITED

            // start a DFS from every still‑unvisited cell
            for (int r = 0; r < rows && !hasCycle; r++) {
                for (int c = 0; c < cols && !hasCycle; c++) {
                    if (state[r][c] == UNVISITED) {
                        hasCycle = dfs(grid, state, r, c, -1, -1);
                    }
                }
            }

            System.out.println(hasCycle ? "Yes" : "No");
        }
    }

    /**
     * Depth‑first search that searches for a cycle beginning at (r,c).
     *
     * @return true if a cycle is discovered in this component
     */
    private static boolean dfs(char[][] grid, int[][] state, int r, int c, int pr, int pc) {
        state[r][c] = VISITING;   // mark as currently on the recursion stack

        for (int dir = 0; dir < 4; dir++) {
            int nr = r + DR[dir];
            int nc = c + DC[dir];

            // 1️⃣ out‑of‑bounds check
            if (!isInBounds(nr, grid.length, grid[0].length)) {
                continue;
            }

            // 2️⃣ stay on the same character
            if (grid[nr][nc] != grid[r][c]) {
                continue;
            }

            // 3️⃣ do not go back to the parent cell
            if (nr == pr && nc == pc) {
                continue;
            }

            if (state[nr][nc] == UNVISITED) {
                // explore deeper
                if (dfs(grid, state, nr, nc, r, c)) {
                    return true;
                }
            } else if (state[nr][nc] == VISITING) {
                // visited cell that is still on the stack → a cycle exists
                return true;
            }
            // else (VISITED) we just ignore – no new information
        }

        state[r][c] = VISITED;   // finished processing this cell
        return false;
    }

    /** Helper that checks if an index is inside the given bounds. */
    private static boolean isInBounds(int v, int max, int exclusiveMax) {
        return v >= 0 && v < exclusiveMax;
    }
}

import java.io.*;
import java.util.*;

public class B510 implements Runnable {

    // -----------------------------------------------------------------------
    // Constants
    // -----------------------------------------------------------------------
    /** Four possible moves: up, down, right, left */
    private static final int[][] DIRS = {
            {1, 0},   // down
            {-1, 0},  // up
            {0, 1},   // right
            {0, -1}   // left
    };
    // -----------------------------------------------------------------------

    /** Grid characters */
    private final char[][] grid;
    /** 0 = unvisited, 1 = visiting, 2 = processed */
    private final int[][] visited;
    /** Dimensions of the board */
    private int rows, cols;
    /** True when a cycle is found */
    private boolean foundCycle;

    /** Program entry point */
    public static void main(String[] args) throws IOException {
        try (PrintWriter out = new PrintWriter(System.out)) {
            new B510().run(out);
        }
    }

    /** Runs the whole solution using a supplied output stream */
    @Override
    public void run(PrintWriter out) {
        try (Input in = new StandardInput()) {
            solve(in, out);
        } catch (Exception e) {
            e.printStackTrace();
        }
    }

    /** Reads input, runs DFS detection and writes the answer */
    private void solve(Input in, PrintWriter out) throws IOException {
        rows = in.nextInt();
        cols = in.nextInt();
        grid = new char[rows][];
        for (int r = 0; r < rows; r++) {
            grid[r] = in.next().toCharArray();
        }

        visited = new int[rows][cols];
        foundCycle = false;

        for (int r = 0; r < rows && !foundCycle; r++) {
            for (int c = 0; c < cols && !foundCycle; c++) {
                if (visited[r][c] == 0) {
                    dfs(r, c, -1, -1);
                }
            }
        }

        out.print(foundCycle ? "Yes" : "No");
    }

    /** Depth‑first search that detects cycles of equal characters */
    private void dfs(int r, int c, int pr, int pc) {
        if (visited[r][c] == 1) {          // cycle found
            foundCycle = true;
            return;
        }
        if (visited[r][c] == 2) {          // already processed – nothing to do
            return;
        }

        visited[r][c] = 1;                 // mark as visiting
        for (int[] d : DIRS) {
            int nr = r + d[0];
            int nc = c + d[1];
            if (nr == pr && nc == pc) {    // ignore the parent cell
                continue;
            }
            if (inBounds(nr, nc) && grid[nr][nc] == grid[r][c]) {
                dfs(nr, nc, r, c);
            }
        }
        visited[r][c] = 2;                 // mark as processed
    }

    /** Helper to check whether (r, c) lies inside the grid */
    private boolean inBounds(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    /* -----------------------------------------------------------------------
       Input utilities – kept minimal and encapsulated for clarity
       ----------------------------------------------------------------------- */
    /** Simple contract for reading tokens from a source */
    interface Input extends AutoCloseable {
        String next() throws IOException;

        default int nextInt() throws IOException {
            return Integer.parseInt(next());
        }

        default int[] readIntArray() throws IOException {
            // Example utility – not used in this solution but kept for completeness
            throw new UnsupportedOperationException();
        }

        default int[] readIntArray(int size) throws IOException {
            int[] a = new int[size];
            for (int i = 0; i < size; i++) {
                a[i] = nextInt();
            }
            return a;
        }
    }

    /** Reads from standard input using a BufferedReader */
    private static class StandardInput implements Input {
        private final BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        private StringTokenizer st;

        @Override
        public void close() throws IOException {
            br.close();
        }

        @Override
        public String next() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                st = new StringTokenizer(br.readLine());
            }
            return st.nextToken();
        }
    }
}

import java.util.Scanner;

/**
 * Utility that detects whether a character grid contains a cycle made of
 * orthogonally‑connected cells of the same character.
 *
 * <p>Algorithm: depth‑first search on every un‑visited cell. The recursion
 * carries the coordinates of the current cell, the cell we came from
 * (the parent), and the direction array describing possible moves.
 *
 * <p>This refactor improves readability, separates concerns, and replaces
 * string‑based visited tracking with a proper boolean matrix for better
 * performance and clarity.
 */
public final class CodeForces {

    /** The start‑point of the search. */
    private static final class Point {
        final int row;
        final int col;

        Point(int row, int col) {
            this.row = row;
            this.col = col;
        }

        @Override public boolean equals(Object o) {
            if (this == o) return true;
            if (!(o instanceof Point)) return false;
            Point p = (Point) o;
            return row == p.row && col == p.col;
        }

        @Override public int hashCode() {
            return 31 * row + col;
        }

        @Override public String toString() {
            return row + "," + col;
        }
    }

    /** Directions used for orthogonal moves (up, down, left, right). */
    private static final int[][] DIRS = {
            {-1, 0},   // up
            {1, 0},    // down
            {0, -1},   // left
            {0, 1}     // right
    };

    /**
     * Entry point used by the original solution – kept for compatibility with
     * the provided test harness.
     *
     * @param grid character matrix to examine
     * @return {@code true} if a cycle exists, otherwise {@code false}
     */
    public static boolean hasCycle(char[][] grid) {
        if (grid == null || grid.length == 0) {
            return false;
        }

        boolean[][] visited = new boolean[grid.length][grid[0].length];

        for (int r = 0; r < grid.length; r++) {
            for (int c = 0; c < grid[0].length; c++) {
                if (!visited[r][c]) {
                    if (search(grid, r, c, visited, -1, -1, grid[r][c])) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    /**
     * Depth‑first search that explores all reachable cells of the same colour.
     *
     * @param grid      the character grid
     * @param r         current row
     * @param c         current column
     * @param visited   matrix tracking visited cells
     * @param fromR     row of the parent cell (or -1 for the root)
     * @param fromC     column of the parent cell (or -1 for the root)
     * @param colour    colour that must be matched throughout the DFS
     * @return {@code true} if a cycle is detected during this traversal
     */
    private static boolean search(char[][] grid,
                                  int r,
                                  int c,
                                  boolean[][] visited,
                                  int fromR,
                                  int fromC,
                                  char colour) {
        visited[r][c] = true;

        for (int[] dir : DIRS) {
            int nr = r + dir[0];
            int nc = c + dir[1];

            if (!inBounds(grid, nr, nc)) {
                continue;
            }

            if (grid[nr][nc] != colour) {
                continue;
            }

            if (!visited[nr][nc]) {
                if (search(grid, nr, nc, visited, r, c, colour)) {
                    return true;      // a cycle was found deeper in the recursion
                }
            } else if (nr != fromR || nc != fromC) {
                // visited neighbour that is **not** the cell we came from
                return true;          // a cycle exists
            }
        }
        return false;
    }

    /** Checks that a coordinate lies inside the grid limits. */
    private static boolean inBounds(char[][] grid, int row, int col) {
        return row >= 0 && row < grid.length
                && col >= 0 && col < grid[0].length;
    }

    /** Main method – reproduces the original I/O behaviour. */
    public static void main(String[] args) {
        try (Scanner sc = new Scanner(System.in)) {
            int rows = sc.nextInt();
            int cols = sc.nextInt();

            char[][] matrix = new char[rows][];
            for (int i = 0; i < rows; i++) {
                matrix[i] = sc.next().toCharArray();
            }

            boolean has = hasCycle(matrix);
            System.out.println(has ? "Yes" : "No");
        }
    }
}

