        int nextInt() throws IOException {
            return Integer.parseInt(nextToken());
        }

        /** Reads the next non‑empty line (used as a token for strings). */
        String next() throws IOException {
            while (true) {
                String line = br.readLine();
                if (line == null) {
                    return null;
                }
                String trimmed = line.trim();
                if (!trimmed.isEmpty()) {
                    return trimmed;
                }
            }
        }

        @Override
        public void close() throws IOException {
            br.close();
        }
    }

    /** Finds a cycle of cells that share the same character. */
    private static final class CycleFinder {
        private final int rows;
        private final int cols;
        private final char[][] grid;
        private final boolean[][] visited;

        CycleFinder(int rows, int cols, char[][] grid) {
            this.rows = rows;
            this.cols = cols;
            this.grid = grid;
            this.visited = new boolean[rows][cols];
        }

        /** Public API – returns true as soon as any cycle is discovered. */
        boolean hasCycle() {
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (!visited[r][c] && searchForCycle(r, c, -1, -1)) {
                        return true;
                    }
                }
            }
            return false;
        }

        /** Depth‑first search that avoids revisiting the immediate parent. */
        private boolean searchForCycle(int r, int c, int pr, int pc) {
            if (visited[r][c]) {
                // A previously visited cell of the same colour => cycle found.
                return true;
            }

            visited[r][c] = true;
            char current = grid[r][c];

            // Four orthogonal directions: up, down, left, right.
            int[][] directions = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};
            for (int[] dir : directions) {
                int nr = r + dir[0];
                int nc = c + dir[1];

                if (isOutOfBounds(nr, nc)) {
                    continue;                       // outside the grid
                }
                if (nr == pr && nc == pc) {
                    continue;                       // back to the parent cell
                }
                if (grid[nr][nc] != current) {
                    continue;                       // different character
                }
                // Recurse; any true bubbling up means a cycle exists.
                if (searchForCycle(nr, nc, r, c)) {
                    return true;
                }
            }
            return false;
        }

        /** Helper – checks whether a coordinate lies outside the grid. */
        private boolean isOutOfBounds(int r, int c) {
            return r < 0 || r >= rows || c < 0 || c >= cols;
        }
    }
}

import java.util.Scanner;

/**
 * Reads a grid of characters and determines whether there exists a
 * reachable neighbour cell of the same character that can be reached
 * via a depth‑first search which does not immediately step back to the
 * start position.
 *
 * <p>Refactored for readability, maintainability and adherence to Java
 * coding conventions.</p>
 */
public class Main {

    /** Directions: up, right, down, left */
    private static final int[] DR = { -1, 0, 1, 0 };
    private static final int[] DC = { 0, 1, 0, -1 };

    public static void main(String[] args) {
        try (Scanner sc = new Scanner(System.in)) {
            int rows = sc.nextInt();
            int cols = sc.nextInt();

            char[][] grid = readGrid(sc, rows, cols);
            boolean found = hasConnectingNeighbour(grid);
            System.out.println(found ? "Yes" : "No");
        }
    }

    /** Reads a rows × cols grid from the scanner. */
    private static char[][] readGrid(Scanner sc, int rows, int cols) {
        char[][] grid = new char[rows][cols];
        for (int r = 0; r < rows; r++) {
            String line = sc.next();
            for (int c = 0; c < cols; c++) {
                grid[r][c] = line.charAt(c);
            }
        }
        return grid;
    }

    /**
     * Determines whether any cell has a neighbouring cell of the same
     * character that can be reached via a DFS that does not immediately
     * return to the start cell.
     */
    private static boolean hasConnectingNeighbour(char[][] grid) {
        final int rows = grid.length;
        final int cols = grid[0].length;
        boolean[][] visited = new boolean[rows][cols];

        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                for (int d = 0; d < DR.length; d++) {
                    int nr = r + DR[d];
                    int nc = c + DC[d];

                    if (isInside(grid, nr, nc) &&
                        grid[nr][nc] == grid[r][c] &&
                        canReach(grid, visited, r, c, nr, nc, r, c)) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    /**
     * Depth‑first search that checks whether the target cell (tr, tc) can be
     * reached from (br, bc) without immediately stepping back to the start.
     *
     * @return {@code true} if the target can be reached under the
     *         constraints, otherwise {@code false}.
     */
    private static boolean canReach(char[][] grid,
                                    boolean[][] visited,
                                    int br, int bc,
                                    int tr, int tc,
                                    int r, int c) {
        visited[r][c] = true;

        if (r == tr && c == tc) {
            return true;
        }

        for (int d = 0; d < DR.length; d++) {
            int nr = r + DR[d];
            int nc = c + DC[d];

            if (isInside(grid, nr, nc) &&
                grid[nr][nc] == grid[r][c] &&
                !visited[nr][nc] &&
                !(r == br && c == bc && nr == tr && nc == tc) &&   // avoid immediate back‑track
                canReach(grid, visited, br, bc, tr, tc, nr, nc)) {
                return true;
            }
        }

        visited[r][c] = false;
        return false;
    }

    /** Checks whether the given coordinates are inside the grid bounds. */
    private static boolean isInside(char[][] grid, int r, int c) {
        return r >= 0 && r < grid.length && c >= 0 && c < grid[0].length;
    }
}

import java.io.*;
import java.util.*;

/**
 * Detects whether an undirected graph built from a 2‑D grid contains a cycle
 * of length at least 4 where adjacent vertices correspond to cells that
 * share the same character.
 */
public class CycleFinder {

    /** Directions used to connect neighboring cells (down, right, up, left). */
    private static final int[] DX = {1, 0, -1, 0};
    private static final int[] DY = {0, 1, 0, -1};

    /** Fast scanner used to read integer input. */
    private static final class FastScanner {
        private final int BUFFER_SIZE = 1 << 16;
        private final DataInputStream din;
        private final byte[] buffer;
        private int bufferPointer = 0, bytesRead = 0;

        FastScanner() {
            din = new DataInputStream(System.in);
            buffer = new byte[BUFFER_SIZE];
        }

        private void fillBuffer() throws IOException {
            bytesRead = din.read(buffer, bufferPointer, BUFFER_SIZE);
            if (bytesRead == -1) {
                buffer[0] = -1; // sentinel
            }
        }

        private byte read() throws IOException {
            if (bufferPointer == bytesRead) {
                fillBuffer();
            }
            return buffer[bufferPointer++];
        }

        /** Reads next token (skipping whitespace). */
        private String nextToken() throws IOException {
            char c;
            do {
                c = (char) read();
            } while (Character.isWhitespace(c));
            StringBuilder sb = new StringBuilder();
            sb.append(c);
            c = (char) read();
            while (!Character.isWhitespace(c) && c != -1) {
                sb.append(c);
                c = (char) read();
            }
            return sb.toString();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(nextToken());
        }

        /** Constructs a 2‑D char matrix from the given number of rows. */
        static char[][] readGrid(int rows) throws IOException {
            char[][] grid = new char[rows][];
            for (int r = 0; r < rows; ++r) {
                String line = new FastScanner().nextToken();
                grid[r] = line.toCharArray();
            }
            return grid;
        }
    }

    /**
     * Builds an adjacency list for the grid where vertices are cells
     * and edges connect orthogonal neighbours that share the same character.
     */
    private static List<Set<Integer>> buildAdjacency(char[][] grid) {
        final int rows = grid.length;
        final int cols = grid[0].length;
        final int vertexCount = rows * cols;
        List<Set<Integer>> adjacency = new ArrayList<>(vertexCount);
        for (int i = 0; i < vertexCount; ++i) {
            adjacency.add(new HashSet<>());
        }

        for (int r = 0; r < rows; ++r) {
            for (int c = 0; c < cols; ++c) {
                for (int d = 0; d < 4; ++d) {
                    int nr = r + DX[d];
                    int nc = c + DY[d];
                    if (nr < 0 || nr >= rows || nc < 0 || nc >= cols) {
                        continue;
                    }
                    if (grid[r][c] != grid[nr][nc]) {
                        continue;
                    }
                    int src = r * cols + c;
                    int dst = nr * cols + nc;
                    adjacency.get(src).add(dst);
                    adjacency.get(dst).add(src);
                }
            }
        }
        return adjacency;
    }

    /**
     * Depth‑first search that looks for a cycle starting from {@code u}
     * and using {@code parent} as the previous vertex.
     *
     * @return {@code true} if a cycle of length at least four is found.
     */
    private static boolean hasCycleFrom(
            int u,
            int parent,
            boolean[][] visited,
            char[][] grid,
            List<Set<Integer>> adjacency,
            int rows,
            int cols,
            int depth) {

        int r = u / cols;
        int c = u % cols;

        if (visited[r][c] && depth >= 4) {
            return true;
        }
        visited[r][c] = true;

        for (int v : adjacency.get(u)) {
            if (v == parent) {
                continue;
            }
            if (hasCycleFrom(v, u, visited, grid, adjacency, rows, cols, depth + 1)) {
                return true;
            }
        }
        return false;
    }

    /** Entry point – reads input, builds the graph and reports the result. */
    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();
        int rows = fs.nextInt();
        int cols = fs.nextInt();

        char[][] grid = new char[rows][];
        for (int r = 0; r < rows; ++r) {
            // Using a dedicated scanner simplifies reading whole lines.
            String line = new FastScanner().nextToken();
            grid[r] = line.toCharArray();
        }

        List<Set<Integer>> adjacency = buildAdjacency(grid);

        boolean[][] visited = new boolean[rows][cols];
        boolean hasCycle = false;

        for (int r = 0; r < rows && !hasCycle; ++r) {
            for (int c = 0; c < cols && !hasCycle; ++c) {
                if (!visited[r][c]) {
                    int startIdx = r * cols + c;
                    hasCycle = hasCycleFrom(startIdx, -1, visited, grid,
                                            adjacency, rows, cols, 1);
                }
            }
        }

        System.out.println(hasCycle ? "Yes" : "No");
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

/**
 * Detects whether a grid contains a cycle of length {@code >= 4}
 * formed by equal characters connected orthogonally.
 *
 * The program reads a rectangular grid from standard input:
 *
 *   n m            – number of rows and columns
 *   row_1          – string of length {@code m}
 *   row_2
 *   …
 *
 * If such a cycle exists the word {@code Yes} is printed,
 * otherwise {@code No}.
 *
 * The implementation is deliberately split into small, well‑named
 * methods and uses constant‑time direction handling to improve
 * readability and maintainability.
 */
public class Main {

    /** Directions: down, up, right, left */
    private static final int[] DX = {1, -1, 0, 0};
    private static final int[] DY = {0, 0, 1, -1};

    /** Fast scanner used for competitive‑style input */
    private static final class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner() {
            this.br = new BufferedReader(new InputStreamReader(System.in));
        }

        /** Returns next non‑empty token */
        private String nextToken() throws IOException {
            while (st == null || !st.hasMoreElements()) {
                String line = br.readLine();
                if (line == null) {
                    return null;
                }
                st = new StringTokenizer(line);
            }
            return st.nextToken();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(nextToken());
        }

        /** Reads the grid and returns it as a char matrix */
        char[][] readGrid(int rows, int cols) throws IOException {
            char[][] grid = new char[rows][cols];
            for (int r = 0; r < rows; ++r) {
                String token = nextToken();
                // token length must be {@code cols}; repeat if necessary (unlikely in contest data)
                for (int c = 0; c < cols; ++c) {
                    grid[r][c] = token.charAt(c);
                }
            }
            return grid;
        }
    }

    /** Entry point */
    public static void main(String[] args) throws IOException {
        FastScanner fs = new FastScanner();

        int rows = fs.nextInt();
        int cols = fs.nextInt();

        char[][] grid = fs.readGrid(rows, cols);

        boolean found = hasCycle(grid);

        System.out.println(found ? "Yes" : "No");
    }

    /**
     * Determines whether the grid contains a cycle of at least four
     * equal‑character cells connected orthogonally.
     *
     * @param grid input character matrix
     * @return {@code true} if a qualifying cycle exists
     */
    private static boolean hasCycle(char[][] grid) {
        final int rows = grid.length;
        final int cols = grid[0].length;

        for (int r = 0; r < rows; ++r) {
            for (int c = 0; c < cols; ++c) {
                boolean[][] visited = new boolean[rows][cols];
                if (!visited[r][c] && dfs(r, c, r, c, grid[r][c], visited, 1, grid)) {
                    return true;
                }
            }
        }
        return false;
    }

    /**
     * Depth‑first search that looks for a cycle starting from {@code startR,startC}.
     *
     * @param curR       current row
     * @param curC       current column
     * @param startR     row of the cycle's starting cell
     * @param startC     column of the cycle's starting cell
     * @param ch         character that must be matched throughout the cycle
     * @param visited    matrix tracking visited cells
     * @param lengthSoFar number of cells visited on the current path (including current)
     * @param grid       the original grid
     * @return {@code true} if a cycle with the required properties is found
     */
    private static boolean dfs(int curR, int curC,
                               int startR, int startC,
                               char ch,
                               boolean[][] visited,
                               int lengthSoFar,
                               char[][] grid) {
        visited[curR][curC] = true;

        // Cycle found if we have enough length and are orthogonally adjacent to the start
        if (lengthSoFar >= 4 && areAdjacent(curR, curC, startR, startC)) {
            return true;
        }

        for (int dir = 0; dir < 4; ++dir) {
            int nextR = curR + DX[dir];
            int nextC = curC + DY[dir];

            if (!inBounds(nextR, grid.length, nextC, grid[0].length)) {
                continue;
            }
            if (grid[nextR][nextC] != ch) {
                continue;
            }
            if (visited[nextR][nextC]) {
                continue;
            }

            if (dfs(nextR, nextC, startR, startC, ch, visited, lengthSoFar + 1, grid)) {
                return true;
            }
        }
        return false;
    }

    /** Checks whether two cells are orthogonal neighbours. */
    private static boolean areAdjacent(int r1, int c1, int r2, int c2) {
        return (r1 == r2 && Math.abs(c1 - c2) == 1) ||
               (c1 == c2 && Math.abs(r1 - r2) == 1);
    }

    /** Utility to test array bounds. */
    private static boolean inBounds(int x, int maxRow, int y, int maxCol) {
        return x >= 0 && x < maxRow && y >= 0 && y < maxCol;
    }
}

import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.io.IOException;
import java.util.StringTokenizer;

public class FoxAndCeil2 {

    public static void main(String[] args) {
        FastScanner scanner = new FastScanner();
        int rows = scanner.nextInt();
        int cols = scanner.nextInt();
        char[][] grid = new char[rows][cols];

        for (int i = 0; i < rows; i++) {
            grid[i] = scanner.nextCharArray();
        }

        boolean[][] visited = new boolean[rows][cols];

        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (!visited[i][j] && hasCycle(i, j, grid, visited)) {
                    System.out.println("Yes");
                    return;
                }
            }
        }
        System.out.println("No");
    }

    private static boolean hasCycle(int i, int j, char[][] grid, boolean[][] visited) {
        visited[i][j] = true;
        int sameCharNeighbors = countSameCharNeighbors(i, j, grid, visited);

        if (sameCharNeighbors >= 2) {
            return true;
        }

        if (hasCycleNeighbor(i, j, grid, visited, -1, 0)) return true;
        if (hasCycleNeighbor(i, j, grid, visited, 1, 0)) return true;
        if (hasCycleNeighbor(i, j, grid, visited, 0, -1)) return true;
        if (hasCycleNeighbor(i, j, grid, visited, 0, 1)) return true;

        return false;
    }

    private static int countSameCharNeighbors(int i, int j, char[][] grid, boolean[][] visited) {
        int count = 0;
        int rows = grid.length;
        int cols = grid[0].length;

        if (i > 0 && visited[i-1][j] && grid[i-1][j] == grid[i][j]) count++;
        if (i < rows-1 && visited[i+1][j] && grid[i+1][j] == grid[i][j]) count++;
        if (j > 0 && visited[i][j-1] && grid[i][j-1] == grid[i][j]) count++;
        if (j < cols-1 && visited[i][j+1] && grid[i][j+1] == grid[i][j]) count++;

        return count;
    }

    private static boolean hasCycleNeighbor(int i, int j, char[][] grid, boolean[][] visited, int di, int dj) {
        int ni = i + di;
        int nj = j + dj;
        int rows = grid.length;
        int cols = grid[0].length;

        if (ni >= 0 && ni < rows && nj >= 0 && nj < cols && 
            !visited[ni][nj] && grid[ni][nj] == grid[i][j]) {
            return hasCycle(ni, nj, grid, visited);
        }
        return false;
    }

    static class FastScanner {
        private BufferedReader br;
        private StringTokenizer st;

        FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    e.printStackTrace();
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        char[] nextCharArray() {
            return next().toCharArray();
        }
    }
}

import java.util.Scanner;

/**
 * Entry point of the application.
 * It reads the input, delegates the cycle detection to {@link Solver},
 * and prints the result.
 */
public class Main {

    public static void main(String[] args) {
        // Using try‑with‑resources guarantees that the Scanner (which wraps System.in)
        // is closed as soon as we are done.
        try (Scanner scanner = new Scanner(System.in)) {
            Solver solver = new Solver();
            boolean cycleExists = solver.hasCycle(scanner);
            System.out.println(cycleExists ? "Yes" : "No");
        }
    }

    /**
     * Core class that implements the algorithm for detecting a cycle of at least
     * four cells with the same character.
     *
     * <p>All public methods are deliberately small and have a single responsibility,
     * making the code easier to test and maintain.</p>
     */
    static final class Solver {

        /** Four possible movement directions (down, right, up, left). */
        private static final int[][] DIRS = {
                {1, 0},   // down
                {0, 1},   // right
                {-1, 0},  // up
                {0, -1}   // left
        };

        /**
         * Reads the matrix dimensions and the grid, then checks for a qualifying cycle.
         *
         * @param scanner a {@link Scanner} that supplies the input data
         * @return {@code true} if a cycle of length ≥ 4 exists, {@code false} otherwise
         */
        boolean hasCycle(Scanner scanner) {
            int rows = scanner.nextInt();
            int cols = scanner.nextInt();

            // Read the whole grid in one pass
            char[][] grid = new char[rows][cols];
            for (int r = 0; r < rows; r++) {
                String line = scanner.next();
                for (int c = 0; c < cols; c++) {
                    grid[r][c] = line.charAt(c);
                }
            }

            boolean[][] visited = new boolean[rows][cols];

            // Explore each cell; stop early if a cycle is already found
            for (int r = 0; r < rows && !visitedAllCells(rows, cols, visited); r++) {
                for (int c = 0; c < cols && !visitedAllCells(rows, cols, visited); c++) {
                    if (!visited[r][c]) {
                        if (dfs(grid, visited, r, c, grid[r][c], -1, -1)) {
                            return true; // Cycle detected
                        }
                    }
                }
            }
            return false; // No cycle found
        }

        /**
         * Depth‑first search that looks for a cycle starting at (row, col).
         *
         * @return {@code true} if a cycle meeting the problem’s constraints is found
         */
        private boolean dfs(char[][] grid, boolean[][] visited, int r, int c,
                            char currentChar, int parentR, int parentC) {
            visited[r][c] = true;
            for (int[] dir : DIRS) {
                int nr = r + dir[0];
                int nc = c + dir[1];

                // Skip cells outside the matrix
                if (outOfBounds(nr, nc, grid.length, grid[0].length)) {
                    continue;
                }

                // Only continue on cells with the same character
                if (grid[nr][nc] != currentChar) {
                    continue;
                }

                if (visited[nr][nc]) {
                    // A visited neighbour that is not the immediate parent indicates a cycle
                    if (nr != parentR || nc != parentC) {
                        return true;
                    }
                    continue;
                }

                // Recurse deeper; early‑exit if a cycle is found downstream
                if (dfs(grid, visited, nr, nc, currentChar, r, c)) {
                    return true;
                }
            }
            return false;
        }

        /**
         * Utility method that checks whether a coordinate lies outside the matrix.
         */
        private boolean outOfBounds(int x, int y, int rows, int cols) {
            return x < 0 || x >= rows || y < 0 || y >= cols;
        }

        /** Helper used to stop early when every cell has been visited. */
        private boolean visitedAllCells(int rows, int cols, boolean[][] visited) {
            // The outer loops already respect this condition via the early‑exit checks,
            // but the method is kept for readability of the calling loop.
            return false;
        }
    }
}

package b510;

import java.io.PrintWriter;
import java.util.InputMismatchException;

/**
 * Detects whether a grid contains a cycle formed by adjacent cells
 * that have the same character.
 *
 * <p>Refactorings performed:
 * <ul>
 *   <li>Renamed variables and methods for clearer intent.
 *   <li>Extracted helper methods and removed duplicated code.
 *   <li>Encapsulated the DFS logic in a dedicated method.
 *   <li>Separated input handling from the algorithm.
 *   <li>Eliminated unused imports and static imports.
 *   <li>Made the class `final` and all its fields `private static` where appropriate.
 *   <li>Added JavaDoc comments and descriptive line breaks.
 * </ul>
 *
 * <p>The algorithm works as follows:
 * <ol>
 *   <li>Read the size of the grid and the grid itself.</li>
 *   <li>For each unvisited cell start a DFS that moves only to orthogonal neighbours
 *       with the same character.</li>
 *   <li>When a neighbour that has already been visited is reached,
 *       and it is not the cell we came from (the “parent”), a cycle exists.</li>
 * </ol>
 *
 * <p>The program prints "Yes" if such a cycle is found, otherwise "No".
 */
public final class B510 {

    /** Size of the grid – filled after reading the input. */
    private static int rows;
    /** Size of the grid – filled after reading the input. */
    private static int columns;

    /** Grid stored as characters (lower‑case English letters). */
    private static char[][] grid;

    /** Visited flag for each cell. */
    private static boolean[][] visited;

    /** Global flag – becomes true as soon as a cycle is detected. */
    private static boolean cycleFound;

    /** The scanner used for fast input reading. */
    private static final FasterScanner FINPUT = new FasterScanner();

    /** Output writer – uses the supplied `System.out`. */
    private static final PrintWriter POUT = new PrintWriter(System.out, true);

    /** Private constructor – utility class. */
    private B510() { }

    /**
     * Entry point of the program.
     */
    public static void main(String[] args) {
        readInput();
        for (int r = 1; r <= rows; r++) {
            for (int c = 1; c <= columns; c++) {
                if (!visited[r][c]) {
                    dfs(r, c, -1, -1);
                }
            }
        }
        POUT.println(cycleFound ? "Yes" : "No");
        POUT.flush();
    }

    /**
     * Depth‑first search that looks for cycles.
     *
     * @param r      current row (1‑based)
     * @param c      current column (1‑based)
     * @param pr     row of the parent cell, {@code -1} if none
     * @param pc     column of the parent cell, {@code -1} if none
     */
    private static void dfs(int r, int c, int pr, int pc) {
        visited[r][c] = true;
        exploreNeighbour(r, c, pr, pc, 0, -1); // right
        exploreNeighbour(r, c, pr, pc, 0, 1);  // left
        exploreNeighbour(r, c, pr, pc, -1, 0); // up
        exploreNeighbour(r, c, pr, pc, 1, 0);  // down
    }

    /**
     * Checks a single direction for a neighbour that may continue the DFS.
     *
     * @param r      current row
     * @param c      current column
     * @param pr     parent row
     * @param pc     parent column
     * @param dr     row delta
     * @param dc     column delta
     */
    private static void exploreNeighbour(int r, int c, int pr, int pc, int dr, int dc) {
        int nr = r + dr;
        int nc = c + dc;
        if (!isInBounds(nr, nc)) {
            return;
        }
        char cur = grid[r][c];
        char next = grid[nr][nc];

        // Continue DFS only when the characters are equal.
        if (cur == next) {
            if (!visited[nr][nc]) {
                dfs(nr, nc, r, c);
                if (cycleFound) {
                    return;
                }
            } else if ((nr != pr) || (nc != pc)) {
                // Visited neighbour that is not the direct parent → cycle found.
                cycleFound = true;
            }
        }
    }

    /** @return {@code true} if the coordinates are inside the grid. */
    private static boolean isInBounds(int r, int c) {
        return r >= 1 && r <= rows && c >= 1 && c <= columns;
    }

    /** Reads the grid dimensions and the grid itself from standard input. */
    private static void readInput() {
        rows = FINPUT.nextInt();
        columns = FINPUT.nextInt();
        grid = new char[rows + 1][columns + 1];
        visited = new boolean[rows + 1][columns + 1];

        // The input consists of `rows` lines, each containing exactly `columns` characters.
        for (int r = 1; r <= rows; r++) {
            String line = FINPUT.nextLine().trim();
            if (line.length() < columns) {
                throw new InputMismatchException("Insufficient characters on line " + r);
            }
            for (int c = 1; c <= columns; c++) {
                grid[r][c] = line.charAt(c - 1);
            }
        }
    }

    /**
     * Very small, fast scanner that skips whitespace.
     * (Original implementation kept unchanged, only the class name was adjusted.)
     */
    private static final class FasterScanner {
        private final byte[] buffer = new byte[1024];
        private int bytePointer = 0;
        private int bytesRead = 0;

        private int readByte() {
            if (bytePointer >= bytesRead) {
                bytePointer = 0;
                bytesRead = System.in.read(buffer);
                if (bytesRead <= 0) {
                    return -1;
                }
            }
            return buffer[bytePointer++];
        }

        /** Reads a full line (up to line‑break). */
        private String readLine() {
            StringBuilder sb = new StringBuilder();
            int b;
            // skip leading whitespace
            do {
                b = readByte();
            } while (isSpace(b));

            while (!isEndOfLine(b)) {
                sb.append((char) b);
                b = readByte();
            }
            return sb.toString();
        }

        /** Reads the next token (non‑whitespace characters). */
        private String nextToken() {
            int b;
            // skip whitespace
            do {
                b = readByte();
            } while (isSpace(b));

            StringBuilder sb = new StringBuilder();
            while (!isSpace(b)) {
                sb.append((char) b);
                b = readByte();
            }
            return sb.toString();
        }

        /** @return {@code true} for spaces, newlines, carriage returns and tabs. */
        private static boolean isSpace(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t';
        }

        /** @return {@code true} for newline or carriage return. */
        private static boolean isEndOfLine(int c) {
            return c == '\n' || c == '\r';
        }

        // Convenience wrappers used by the refactored code
        private int nextInt() {
            String token = nextToken();
            try {
                return Integer.parseInt(token);
            } catch (NumberFormatException e) {
                throw new InputMismatchException();
            }
        }

        private String nextLine() {
            return readLine();
        }
    }
}

import java.util.Scanner;

/**
 * Detects whether a grid contains a cycle of at least 4 cells that are
 * connected by the same character. The program reads the grid dimensions
 * and the grid itself from standard input and prints {@code Yes} if such a
 * cycle exists, otherwise {@code No}.
 *
 * The implementation is deliberately kept simple, type‑safe and
 * easy to maintain.
 */
public class Main {

    /** Four possible movement directions (right, down, left, up). */
    private static final int[][] DIRS = {
            {0, 1},   // right
            {1, 0},   // down
            {0, -1},  // left
            {-1, 0}   // up
    };

    /** Grid characters (1‑based indexing is used for convenience). */
    private static char[][] grid;

    /** Marks cells that have already been visited during DFS. */
    private static boolean[][] visited;

    /** Current grid dimensions. */
    private static int rows, cols;

    /** Flag that indicates a valid cycle has been found. */
    private static boolean cycleFound;

    /** Entry point of the program. */
    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            if (!readInput(scanner)) {
                // Invalid dimensions – nothing to do.
                return;
            }

            initializeVisitedArray();
            scanGrid(scanner);

            // Start a DFS from every unvisited cell.
            for (int r = 1; r <= rows; r++) {
                for (int c = 1; c <= cols; c++) {
                    if (!visited[r][c]) {
                        dfs(r, c, -1, -1);
                        if (cycleFound) {
                            System.out.println("Yes");
                            return;
                        }
                    }
                }
            }
            System.out.println("No");
        } catch (Exception ignored) {
            // Input format errors are ignored – the program simply ends.
        }
    }

    /** Reads the matrix dimensions and validates them. */
    private static boolean readInput(Scanner sc) {
        if (!sc.hasNextInt()) {
            return false;
        }
        rows = sc.nextInt();
        cols = sc.nextInt();

        if (rows < 2 || rows > 50 || cols < 2 || cols > 50) {
            // According to the original specification we simply abort.
            return false;
        }
        return true;
    }

    /** Fills the padding area of the grid with spaces. */
    private static void scanGrid(Scanner sc) {
        grid = new char[rows + 2][cols + 2]; // extra border for simpler bounds check
        for (int r = 1; r <= rows; r++) {
            String line = sc.next();
            for (int c = 1; c <= cols; c++) {
                grid[r][c] = line.charAt(c - 1);
            }
        }
    }

    /** Initializes the visited matrix (padding included). */
    private static void initializeVisitedArray() {
        visited = new boolean[rows + 2][cols + 2];
    }

    /**
     * Depth‑first search that looks for cycles.
     *
     * @param r       current row (1‑based)
     * @param c       current column (1‑based)
     * @param pr      previous row (or -1 if none)
     * @param pc      previous column (or -1 if none)
     */
    private static void dfs(int r, int c, int pr, int pc) {
        visited[r][c] = true;
        char currentChar = grid[r][c];

        for (int[][] dir : DIRS) {
            int nr = r + dir[0];
            int nc = c + dir[1];

            // Skip the cell we just came from (the parent).
            if (nr == pr && nc == pc) {
                continue;
            }

            // Out of bounds check (the surrounding padding is always present).
            if (!isInside(nr, nc)) {
                continue;
            }

            char neighbourChar = grid[nr][nc];
            if (neighbourChar != currentChar) {
                continue; // different character – not part of the same component
            }

            if (!visited[nr][nc]) {
                // First time we see this neighbour – explore it.
                dfs(nr, nc, r, c);
                if (cycleFound) {
                    return;
                }
            } else {
                // Visited neighbour that is not the parent => cycle detected.
                // In a grid of size ≥2 the detected cycle is guaranteed to have
                // length ≥ 4, matching the problem constraints.
                cycleFound = true;
                return;
            }
        }
    }

    /** Checks whether a coordinate lies inside the padded grid area. */
    private static boolean isInside(int r, int c) {
        return r >= 1 && r <= rows && c >= 1 && c <= cols;
    }
}

import java.io.*;
import java.util.*;

public class FoxAndTwoDots {
    private static final int UP = -1;
    private static final int DOWN = 1;
    private static final int LEFT = -1;
    private static final int RIGHT = 1;

    public static void main(String[] args) throws IOException {
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
        String[] dimensions = reader.readLine().split("\\s+");
        int rows = Integer.parseInt(dimensions[0]);
        int columns = Integer.parseInt(dimensions[1]);

        char[][] grid = new char[rows][];
        for (int i = 0; i < rows; i++) {
            grid[i] = reader.readLine().toCharArray();
        }

        boolean[][] visited = new boolean[rows][columns];
        int[] dx = {UP, LEFT, DOWN, RIGHT};
        int[] dy = {LEFT, DOWN, RIGHT, UP};

        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < columns; j++) {
                if (!visited[i][j]) {
                    if (hasCycle(i, j, -1, -1, grid[i][j], grid, visited, dx, dy)) {
                        System.out.println("Yes");
                        return;
                    }
                }
            }
        }
        System.out.println("No");
    }

    private static boolean hasCycle(int i, int j, int parentI, int parentJ, 
                                   char currentChar, char[][] grid, 
                                   boolean[][] visited, int[] dx, int[] dy) {
        visited[i][j] = true;
        for (int k = 0; k < 4; k++) {
            int ni = i + dx[k];
            int nj = j + dy[k];

            if (!isInBounds(ni, grid.length, nj, grid[0].length)) {
                continue;
            }
            if (grid[ni][nj] != currentChar) {
                continue;
            }
            if (ni == parentI && nj == parentJ) {
                continue;
            }
            if (visited[ni][nj]) {
                return true;
            }
            if (hasCycle(ni, nj, i, j, currentChar, grid, visited, dx, dy)) {
                return true;
            }
        }
        visited[i][j] = false;
        return false;
    }

    private static boolean isInBounds(int row, int maxRow, int col, int maxCol) {
        return row >= 0 && row < maxRow && col >= 0 && col < maxCol;
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.PrintWriter;
import java.util.*;

public class B {

    /** Helper class that encapsulates the grid and cycle‑detection logic. */
    private static final class CycleInfo {
        private final char[][] grid;
        private final boolean[][] visited;
        private final int rows;
        private final int cols;

        CycleInfo(char[][] grid) {
            this.grid = grid;
            this.rows = grid.length;
            this.cols = grid[0].length;
            this.visited = new boolean[rows][cols];
        }

        /** Returns true if any cycle of length ≥ 4 exists in the grid. */
        boolean hasCycle() {
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (!visited[r][c] && dfs(r, c, -1, -1)) {
                        return true;
                    }
                }
            }
            return false;
        }

        /** Depth‑first search that looks for a visited neighbour which is not the parent. */
        private boolean dfs(int i, int j, int fromI, int fromJ) {
            visited[i][j] = true;

            for (Direction dir : Direction.values()) {
                int ni = i + dir.di;
                int nj = j + dir.dj;

                if (!inBounds(ni, nj)) {
                    continue;
                }
                if (grid[ni][nj] != grid[i][j]) {
                    continue;
                }
                if (!visited[ni][nj]) {
                    if (dfs(ni, nj, i, j)) {
                        return true;          // cycle discovered downstream
                    }
                } else if (ni != fromI || nj != fromJ) {
                    // A visited cell that is not the immediate parent forms a cycle.
                    return true;
                }
            }
            return false;
        }

        private boolean inBounds(int i, int j) {
            return i >= 0 && i < rows && j >= 0 && j < cols;
        }

        /** Directions: up, down, left, right. */
        private enum Direction {
            UP(-1, 0), DOWN(1, 0), LEFT(0, -1), RIGHT(0, 1);
            final int di;
            final int dj;

            Direction(int di, int dj) {
                this.di = di;
                this.dj = dj;
            }
        }
    }

    public static void main(String[] args) throws IOException {
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
        PrintWriter out = new PrintWriter(System.out);

        // Read dimensions
        String[] sizeTokens = reader.readLine().split("\\s+");
        int n = Integer.parseInt(sizeTokens[0]);
        int m = Integer.parseInt(sizeTokens[1]);

        // Read grid
        char[][] grid = new char[n][m];
        for (int i = 0; i < n; i++) {
            grid[i] = reader.readLine().toCharArray();
        }

        // Determine if a qualifying cycle exists
        CycleInfo info = new CycleInfo(grid);
        out.println(info.hasCycle() ? "Yes" : "No");
        out.flush();
    }
}

import java.io.PrintWriter;
import java.util.Scanner;

/**
 * Entry point of the application.
 * Reads a grid written with 'B', 'F', 'O', 'X', or '.' and prints
 * "Yes" if at least one cycle of at least length 4 exists,
 * otherwise prints "No".
 */
public class Main {

    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in);
             PrintWriter out = new PrintWriter(System.out)) {

            Solver solver = new Solver();
            solver.solve(scanner, out);
        }
    }

    /**
     * Core logic that detects a cycle of length ≥ 4.
     * The grid contains characters; a cycle is a closed walk that
     * visits at least 4 distinct cells and moves only up/down/left/right
     * while staying on cells with the same character.
     */
    private static class Solver {

        /** Cell visited flag (0 = unvisited, 1 = currently in recursion stack). */
        private final int[][] visited;

        /** Grid of characters read from input. */
        private final char[][] grid;

        /** true if a qualifying cycle has been found. */
        private boolean hasCycle;

        /** Number of rows and columns. */
        private int rows, cols;

        /** List of movement directions (up, down, left, right). */
        private static final int[][] DIRECTIONS = {
                { -1, 0 },   // up
                { 1, 0 },    // down
                { 0, -1 },   // left
                { 0, 1 }     // right
        };

        /** Detects a cycle starting from the given cell. */
        private void dfs(int row, int col, int prevRow, int prevCol) {
            visited[row][col] = 1;

            for (int[] dir : DIRECTIONS) {
                int newRow = row + dir[0];
                int newCol = col + dir[1];

                // Check bounds.
                if (!isInside(newRow, newCol)) {
                    continue;
                }

                // Ignore the cell from which we came.
                if (newRow == prevRow && newCol == prevCol) {
                    continue;
                }

                // Same character required for continuation.
                if (grid[newRow][newCol] != grid[row][col]) {
                    continue;
                }

                if (visited[newRow][newCol] == 0) {
                    // Unvisited – keep exploring.
                    dfs(newRow, newCol, row, col);
                    if (hasCycle) {
                        return; // early exit, cycle already found.
                    }
                } else {
                    // Visited and not the immediate parent → a cycle.
                    hasCycle = true;
                    return;
                }
            }
        }

        /** Returns true if the given coordinates are within the grid. */
        private boolean isInside(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }

        /** Public entry point used by {@code Main}. */
        void solve(Scanner scanner, PrintWriter out) {
            readInput(scanner);
            searchCycles();
            out.println(hasCycle ? "Yes" : "No");
        }

        /** Parses the grid dimensions and the grid itself. */
        private void readInput(Scanner scanner) {
            rows = scanner.nextInt();
            cols = scanner.nextInt();
            grid = new char[rows][cols];

            for (int r = 0; r < rows; r++) {
                String line = scanner.next();
                for (int c = 0; c < cols; c++) {
                    grid[r][c] = line.charAt(c);
                }
            }

            visited = new int[rows][cols];
            hasCycle = false;
        }

        /** Initiates DFS from every unvisited cell. */
        private void searchCycles() {
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (visited[r][c] == 0) {
                        dfs(r, c, -1, -1);
                        if (hasCycle) {
                            return; // No need to continue searching.
                        }
                    }
                }
            }
        }
    }
}

import java.util.Scanner;

/**
 * Detects whether a grid contains a cycle formed by adjacent cells of the same character.
 *
 * <p>This implementation replaces the original “hacky” approach with a clean,
 * object‑oriented design:
 * <ul>
 *   <li>Input handling and board representation are isolated in {@code main}.</li>
 *   <li>Cycle detection is performed by a dedicated DFS routine.</li>
 *   <li>Only local variables are used – no static mutable fields.</li>
 *   <li>Naming, constants and comments improve readability and maintainability.</li>
 * </ul>
 */
public class CycleDetector {

    /** Symbol used for an empty board cell (originally “0”). */
    private static final char EMPTY = '0';

    /** Symbol used for a wall cell (originally “-1”). */
    private static final char WALL = '-';

    public static void main(String[] args) {
        try (Scanner sc = new Scanner(System.in)) {
            /* ---- 1. Read dimensions ------------------------------------------------ */
            int rows = sc.nextInt();
            int cols = sc.nextInt();
            sc.nextLine();                     // consume the line‑break

            /* ---- 2. Read the board ------------------------------------------------- */
            char[][] grid = new char[rows][cols];
            for (int r = 0; r < rows; r++) {
                String line = sc.nextLine();
                // The original program split on "" (each character) – we do the same.
                String[] tokens = line.split("");
                for (int c = 0; c < cols; c++) {
                    grid[r][c] = tokens[c].charAt(0);
                }
            }

            /* ---- 3. Determine if a cycle exists ------------------------------------ */
            boolean hasCycle = findCycle(grid);
            System.out.println(hasCycle ? "Yes" : "No");
        } catch (NoSuchElementException e) {
            System.err.println("Invalid or incomplete input.");
        }
    }

    /**
     * Scans the board for any cycle made of cells that share the same character.
     *
     * @param grid the board to analyse
     * @return {@code true} if a cycle is found, {@code false} otherwise
     */
    private static boolean findCycle(char[][] grid) {
        boolean[][] visited = new boolean[grid.length][grid[0].length];

        for (int r = 0; r < grid.length; r++) {
            for (int c = 0; c < grid[r].length; c++) {
                if (!visited[r][c]) {
                    if (dfsDetectCycle(grid, visited, r, c, -1, -1)) {
                        return true;                     // early‑exit on first cycle
                    }
                }
            }
        }
        return false;
    }

    /**
     * Depth‑first search that looks for a cycle starting at (r,c).
     *
     * @param grid      the board
     * @param visited   marks cells that have been visited globally
     * @param r,c       current cell coordinates
     * @param pr,pc     parent cell coordinates (or –1,‑1 for the root)
     * @return {@code true} if a cycle is discovered in this branch
     */
    private static boolean dfsDetectCycle(char[][] grid,
                                          boolean[][] visited,
                                          int r,
                                          int c,
                                          int pr,
                                          int pc) {
        visited[r][c] = true;

        // Four orthogonal neighbours: up, down, left, right
        int[] dr = {-1, 1, 0, 0};
        int[] dc = {0, 0, -1, 1};

        for (int dir = 0; dir < 4; dir++) {
            int nr = r + dr[dir];
            int nc = c + dc[dir];

            if (outOfBounds(nr, grid) || grid[nr][nc] != grid[r][c]) {
                continue;                                 // ignore walls or different chars
            }
            if (nr == pr && nc == pc) {
                continue;                                 // do not go back to the parent
            }
            if (visited[nr][nc]) {
                return true;                              // visited neighbour → cycle!
            }
            if (dfsDetectCycle(grid, visited, nr, nc, r, c)) {
                return true;
            }
        }
        return false;
    }

    /** Helper: checks whether a coordinate lies outside the board limits. */
    private static boolean outOfBounds(int idx, int[] bounds) {
        return idx < 0 || idx >= bounds.length;
    }
}

import java.io.*;
import java.util.*;

public class Main {

    /** -------------------------------------------------------------
     *  Fast input helper – wraps a BufferedReader and a StringTokenizer.
     *  ------------------------------------------------------------- */
    private static final class FastScanner {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        FastScanner(BufferedReader reader) {
            this.reader = reader;
        }

        private void ensureTokenizer() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                tokenizer = new StringTokenizer(reader.readLine());
            }
        }

        String nextToken() throws IOException {
            ensureTokenizer();
            return tokenizer.nextToken();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(nextToken());
        }

        long nextLong() throws IOException {
            return Long.parseLong(nextToken());
        }

        double nextDouble() throws IOException {
            return Double.parseDouble(nextToken());
        }
    }

    /** -------------------------------------------------------------
     *  Core algorithm – searches for a closed walk of length ≥ 3 that
     *  moves only on cells having the same letter.
     *  ------------------------------------------------------------- */
    private static final class CycleDetector {
        private final int[][] grid;      // encoded letters (1 … 26)
        private final int rows;
        private final int cols;
        private final int[][] visited;   // 0 = not visited, 1 = currently in recursion stack
        private final int[] startX;       // single‑element arrays used to keep the origin
        private final int[] startY;
        private boolean terminated;       // becomes true when a valid cycle is found

        CycleDetector(int[][] grid) {
            this.grid = grid;
            this.rows = grid.length;
            this.cols = grid[0].length;
            this.visited = new int[rows][cols];
            this.startX = new int[1];
            this.startY = new int[1];
            this.terminated = false;
        }

        /** Entry point – iterates over every cell as a possible start. */
        void searchAndPrintResult() throws IOException {
            for (int i = 0; i < rows && !terminated; i++) {
                for (int j = 0; j < cols && !terminated; j++) {
                    if (visited[i][j] == 0) {
                        startX[0] = i;
                        startY[0] = j;
                        dfs(i, j, 0);
                    }
                }
            }
            if (!terminated) {
                System.out.println("No");
            }
        }

        /** Depth‑first search that respects the original program's semantics. */
        private void dfs(int x, int y, int step) {
            visited[x][y] = 1;

            explore(x + 1, y);
            explore(x - 1, y);
            explore(x, y + 1);
            explore(x, y - 1);

            visited[x][y] = 0; // backtrack for next start points
        }

        /** Checks a neighbour; if it is the start cell and the walk is long enough,
         *  prints "Yes" and terminates the JVM exactly like the original code. */
        private void explore(int nx, int ny) {
            if (!inside(nx, ny)) {
                return;
            }
            if (grid[nx][ny] != grid[startX[0]][startY[0]]) {
                return;
            }
            if (visited[nx][ny] == 1) {               // already in the current path
                if (nx == startX[0] && ny == startY[0] && step + 1 >= 3) {
                    System.out.println("Yes");
                    System.exit(0);
                }
                return;
            }

            visited[nx][ny] = 1;
            dfs(nx, ny, step + 1);
            visited[nx][ny] = 0; // backtrack
        }

        /** Utility – verifies that coordinates are inside the matrix. */
        private boolean inside(int x, int y) {
            return x >= 0 && x < rows && y >= 0 && y < cols;
        }
    }

    /** -------------------------------------------------------------
     *  Program entry point.
     *  ------------------------------------------------------------- */
    public static void main(String[] args) throws IOException {
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in))) {
            FastScanner fs = new FastScanner(br);
            int[][] board = new int[fs.nextInt()][fs.nextInt()];

            for (int i = 0; i < board.length; i++) {
                String line = fs.nextToken();
                for (int j = 0; j < line.length(); j++) {
                    // Encode letters as 1‑based numbers: A → 1, B → 2, …, Z → 26
                    board[i][j] = line.charAt(j) - 'A' + 1;
                }
            }

            new CycleDetector(board).searchAndPrintResult();
        }
        System.out.flush();
    }
}

import java.util.Scanner;

/**
 * Represents a single cell of the grid.
 * <p>
 * Each cell knows its value and its four possible neighbours
 * (up, down, left, right).  Adjacent cells that contain the same
 * character are linked together during the initialization phase.
 */
final class Cell {

    char value;                     // stored character (e.g. 'A', 'B', …)
    boolean visited = false;        // used by the DFS
    boolean isStart = false;        // marks the cell from which DFS is launched
    Cell up, down, left, right;     // neighbours with identical value

    Cell(char value) {
        this.value = value;
    }

    /**
     * Connects this cell with adjacent cells that have the same character.
     *
     * @param grid  the whole board
     * @param row   current row index
     * @param col   current column index
     */
    void connectAdjacent(Cell[][] grid, int row, int col) {
        if (row > 0 && grid[row][col].value == grid[row - 1][col].value) {
            up = grid[row - 1][col];
        }
        if (row < grid.length - 1 && grid[row][col].value == grid[row + 1][col].value) {
            down = grid[row + 1][col];
        }
        if (col > 0 && grid[row][col].value == grid[row][col - 1].value) {
            left = grid[row][col - 1];
        }
        if (col < grid[0].length - 1 && grid[row][col].value == grid[row][col + 1].value) {
            right = grid[row][col + 1];
        }
    }

    /**
     * Returns {@code true} if the cell has **at least three** neighbours.
     * The original program performed an implicit check that a cell must not
     * have a single missing direction – this method captures the same intent
     * more clearly.
     */
    boolean isBranchingNode() {
        int neighbourCount = 0;
        if (up != null) neighbourCount++;
        if (down != null) neighbourCount++;
        if (left != null) neighbourCount++;
        if (right != null) neighbourCount++;
        return neighbourCount >= 3;
    }
}

/**
 * Core algorithm that processes the board and decides whether a solution exists.
 * The public interface is tiny (the {@code main} method) – all heavy lifting
 * happens in well‑named private helpers.
 */
public class Main {

    /** Directions used by the depth‑first search. */
    private enum Direction { UP, RIGHT, DOWN, LEFT }

    /**
     * Depth‑first search that starts from a given {@code start} cell.
     * As soon as a successful path is found the program prints {@code "Yes"}
     * and terminates.
     *
     * @param board   the complete grid
     * @param start   cell from which the search begins
     * @param used    array used to remember which letters have already been
     *                processed (mirrors the original hashtable behaviour)
     */
    private static void dfs(Cell[][] board, Cell start, boolean[] used) {
        start.visited = true;

        // The original code treated a branching node that carries the
        // “starting” flag as a successful termination condition.
        if (start.isBranchingNode() && start.isStart) {
            System.out.print("Yes");
            System.exit(0);
        }

        for (Direction dir : Direction.values()) {
            Cell neighbour = switch (dir) {
                case UP -> start.up;
                case RIGHT -> start.right;
                case DOWN -> start.down;
                case LEFT -> start.left;
            };
            if (neighbour != null && !neighbour.visited) {
                if (start.isStart) {
                    neighbour.isStart = true;               // propagate the flag
                }
                dfs(board, neighbour, used);
            }
        }
    }

    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {

            /* ---------- read dimensions and board ---------- */
            int rows = scanner.nextInt();
            int cols = scanner.nextInt();

            Cell[][] grid = new Cell[rows][cols];
            for (int r = 0; r < rows; ++r) {
                String line = scanner.next();
                for (int c = 0; c < cols; ++c) {
                    grid[r][c] = new Cell(line.charAt(c));
                }
            }

            /* ---------- build adjacency links ---------- */
            for (int r = 0; r < rows; ++r) {
                for (int c = 0; c < cols; ++c) {
                    grid[r][c].connectAdjacent(grid, r, c);
                }
            }

            /* ---------- main search loop ---------- */
            boolean[] alphabetUsed = new boolean[26];   // mirrors original hashtable
            boolean solutionFound = false;

            for (int r = 0; r < rows && !solutionFound; ++r) {
                for (int c = 0; c < cols && !solutionFound; ++c) {
                    Cell cur = grid[r][c];

                    // Skip cells that have already been visited,
                    // letters that have been processed, or cells that are not branching.
                    if (cur.visited
                            || alphabetUsed[cur.value - 'A']
                            || !cur.isBranchingNode()) {
                        continue;
                    }

                    cur.isStart = true;                 // mark as the DFS starting point
                    dfs(grid, cur, alphabetUsed);
                    // If the DFS printed "Yes" it already terminated the JVM,
                    // therefore reaching this point means “No” is the correct output.
                }
            }

            /* ---------- final output ---------- */
            if (!solutionFound) {
                System.out.print("No");
            }
        }
    }
}

import java.io.IOException;
import java.util.ArrayDeque;
import java.util.Arrays;
import java.util.Scanner;

/**
 * Refactored version of the original {@code DifferentStrings} program.
 *
 * <p>This class contains:
 * <ul>
 *   <li>Utility data structures (e.g., {@link UnionFind}).
 *   <li>A simple {@link Point} helper.
 *   <li>Algorithms for breadth‑first search (used only for illustration)
 *       and depth‑first search for cycle detection in a grid.
 *   <li>A {@code main} method that reads a matrix of characters and reports
 *       whether any cycle of equal characters exists.
 * </ul>
 *
 * <p>The implementation follows modern Java coding conventions:
 * clear naming, encapsulation of mutable state, use of try‑with‑resources,
 * immutable helpers where possible, and extensive inline documentation.
 */
public class DifferentStrings {

    /* --------------------------------------------------------------------- */
    /* 1.  Utility data structures                                            */
    /* --------------------------------------------------------------------- */

    /**
     * Simple Union‑Find (Disjoint Set) implementation that was present in the
     * original source.  It is kept here as a reusable component but is not
     * used by the current algorithm – the code merely demonstrates good
     * encapsulation.
     */
    private static final class UnionFind {
        private final int[] parent;

        UnionFind(int size) {
            parent = new int[size];
            for (int i = 0; i < size; i++) {
                parent[i] = i;
            }
        }

        /** Finds the representative of the set that contains {@code x}. */
        int find(int x) {
            if (parent[x] != x) {
                parent[x] = find(parent[x]);
            }
            return parent[x];
        }

        /** Merges the sets that contain {@code x} and {@code y}. */
        void union(int x, int y) {
            int rx = find(x);
            int ry = find(y);
            if (rx != ry) {
                parent[rx] = ry;
            }
        }

        /** Checks whether {@code x} and {@code y} belong to the same set. */
        boolean same(int x, int y) {
            return find(x) == find(y);
        }
    }

    /**
     * Minimal point class used by the BFS routine.  The {@code depth} field
     * is retained only for backward compatibility with the legacy code.
     */
    private static final class Point {
        final int x;
        final int y;
        final int depth; // kept only to mirror the original field

        Point(int x, int y) {
            this.x = x;
            this.y = y;
            this.depth = 0;
        }
    }

    /* --------------------------------------------------------------------- */
    /* 2.  Global (relevant) state used by the algorithms                    */
    /* --------------------------------------------------------------------- */

    /** The character matrix that represents the maze / grid. */
    private static char[][] grid;

    /** Global visited flag matrix used by the BFS routine. */
    private static boolean[][] visited;

    /** Destination coordinates for the BFS search (not used by the final
     *  cycle‑detection logic but kept for completeness). */
    private static int goalX, goalY;

    /** Distance found during BFS (unused in the final program). */
    private static int distance;

    /** Helper direction vectors (horizontal / vertical). */
    private static final int[] DX = {1, -1, 0, 0};
    private static final int[] DY = {0, 0, 1, -1};

    /* --------------------------------------------------------------------- */
    /* 3.  Algorithm implementations                                          */
    /* --------------------------------------------------------------------- */

    /**
     * Breadth‑first search that attempts to reach {@code goalX, goalY}
     * moving only on cells that contain {@code letter}.  The method
     * resets the global {@code visited} matrix before returning.
     *
     * @return {@code true} if a path to the goal was found.
     */
    private static boolean bfs(int startX, int startY, char letter) {
        Queue<Point> queue = new ArrayDeque<>();
        Point start = new Point(startX, startY);
        queue.add(start);
        visited[startX][startY] = true;

        while (!queue.isEmpty()) {
            Point cur = queue.poll();

            for (int dir = 0; dir < 4; dir++) {
                int nx = cur.x + DX[dir];
                int ny = cur.y + DY[dir];

                // Destination cells are not required to match the letter.
                if (nx == goalX && ny == goalY) {
                    continue;
                }

                if (isInside(nx, ny) && !visited[nx][ny] && grid[nx][ny] == letter) {
                    Point child = new Point(nx, ny);
                    queue.add(child);
                    visited[nx][ny] = true;

                    if (nx == goalX && ny == goalY) {
                        // Stop early – the original code stored some state here.
                        distance = child.depth;
                        return true;
                    }
                }
            }
        }

        // Clean up for the next search.
        resetVisited();
        return false;
    }

    /** Clears the global {@code visited} array (all zeros). */
    private static void resetVisited() {
        for (boolean[] row : visited) {
            Arrays.fill(row, false);
        }
    }

    /** Returns {@code true} if (x, y) lies inside the current grid bounds. */
    private static boolean isInside(int x, int y) {
        return x >= 0 && x < grid.length && y >= 0 && y < grid[0].length;
    }

    /**
     * Detects whether the supplied grid contains a cycle made of equal
     * characters.  The method performs a depth‑first search on each
     * unvisited component and returns as soon as a cycle is found.
     *
     * @param matrix the character matrix to examine.
     * @return {@code true} if any cycle exists; otherwise {@code false}.
     */
    private static boolean hasCycle(char[][] matrix) {
        boolean[][] visited = new boolean[matrix.length][matrix[0].length];

        for (int i = 0; i < matrix.length; i++) {
            for (int j = 0; j < matrix[0].length; j++) {
                if (!visited[i][j]) {
                    if (dfs(i, j, -1, -1, matrix[i][j], matrix, visited)) {
                        return true; // Cycle detected – exit early.
                    }
                }
            }
        }
        return false; // No cycles found.
    }

    /**
     * Recursive helper for {@link #hasCycle(char[][])}.
     *
     * @param x      current row.
     * @param y      current column.
     * @param fromX  parent row (or -1 if this is the root cell).
     * @param fromY  parent column (or -1 if this is the root cell).
     * @param ch     character that must be matched.
     * @param grid   the whole matrix.
     * @param visited global visitation matrix.
     * @return {@code true} if a cycle was discovered in this component.
     */
    private static boolean dfs(int x, int y, int fromX, int fromY,
                               char ch, char[][] grid, boolean[][] visited) {
        visited[x][y] = true;

        int[][] directions = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};
        for (int[] d : directions) {
            int nx = x + d[0];
            int ny = y + d[1];

            // Do not revisit the cell we came from.
            if (nx == fromX && ny == fromY) {
                continue;
            }

            if (isInsideGrid(nx, ny, grid) && grid[nx][ny] == ch) {
                if (visited[nx][ny]) {
                    // Already visited neighbour that is not the parent => cycle.
                    return true;
                }
                if (dfs(nx, ny, x, y, ch, grid, visited)) {
                    return true;
                }
            }
        }
        return false;
    }

    /** Checks whether (x, y) is within the bounds of {@code grid}. */
    private static boolean isInsideGrid(int x, int y, char[][] grid) {
        return x >= 0 && x < grid.length && y >= 0 && y < grid[0].length;
    }

    /* --------------------------------------------------------------------- */
    /* 4.  Program entry point                                                */
    /* --------------------------------------------------------------------- */

    /**
     * Reads dimensions and rows of a character matrix from standard input,
     * then determines whether the matrix contains a cycle of equal characters.
     * Prints {@code Yes} if such a cycle exists, otherwise {@code No}.
     */
    public static void main(String[] args) throws IOException {
        // Try‑with‑resources guarantees that the Scanner is closed promptly.
        try (Scanner scanner = new Scanner(System.in)) {
            int rows = scanner.nextInt();
            int cols = scanner.nextInt();

            // Allocate structures.
            grid = new char[rows][cols];
            visited = new boolean[rows][cols];

            // Load each line from input and transform it into a char array.
            for (int i = 0; i < rows; i++) {
                String line = scanner.next();
                grid[i] = line.toCharArray();
            }

            // Cycle detection.
            if (hasCycle(grid)) {
                System.out.println("Yes");
                System.exit(0); // Match original early termination behaviour.
            }

            System.out.println("No");
        }
    }
}

/**
 * Detects whether a grid contains a cycle of at least four cells
 * that share the same letter (connected orthogonally).
 *
 * The program follows the original algorithm but is reorganised
 * into clearer, more maintainable pieces.
 */
public final class Main {

    /** Entry point */
    public static void main(String[] args) {
        // Use the (single‑thread) shared {@link InputReader} instance
        try (var in = new InputReader(System.in);
             var out = new PrintWriter(System.out)) {

            new CycleDetector().doWork(in, out);
        }
    }
}

/**
 * Handles all input, processes the grid and writes the result.
 * All mutable state is confined to this class, making the flow easier
 * to follow and test.
 */
final class CycleDetector {

    /** Public method required by the original `Main` signature */
    public void doWork(InputReader in, PrintWriter out) {
        int rows = in.nextInt();
        int cols = in.nextInt();

        char[][] grid = readGrid(in, rows);
        boolean hasCycle = findCycle(grid);

        out.println(hasCycle ? "Yes" : "No");
    }

    /** Reads {@code rows} lines each containing {@code cols} characters */
    private static char[][] readGrid(InputReader in, int rows) {
        char[][] grid = new char[rows][];
        for (int r = 0; r < rows; r++) {
            String line = in.next();               // next token is the whole line
            grid[r] = line.toCharArray();
        }
        return grid;
    }

    /** Main detection routine – mirrors the behaviour of the original code */
    private boolean findCycle(char[][] grid) {
        final int rows = grid.length;
        final int cols = grid[0].length;

        boolean[][] visited = new boolean[rows][cols];
        int[] frequency = new int[26]; // how many times each letter appears

        // Count total occurrences of each letter
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                char ch = grid[r][c];
                frequency[ch - 'A']++;
            }
        }

        // Try to start a DFS from every cell whose letter appears at least 4 times
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                char ch = grid[r][c];
                if (frequency[ch - 'A'] >= 4 && !visited[r][c]) {
                    if (dfs(grid, visited, r, c, -1, -1, ch)) {
                        return true; // a cycle has been found
                    }
                }
            }
        }
        return false; // no cycle detected
    }

    /**
     * Depth‑first search that looks for a cycle of the same character.
     *
     * @param grid      the board
     * @param visited   marks cells already examined globally
     * @param row, col  current cell coordinates
     * @param fromRow, fromCol  coordinates of the parent cell (or -1,-1 for the start)
     * @param currentChar  the character we are matching
     * @return true if a cycle of length ≥ 4 is discovered
     */
    private boolean dfs(char[][] grid, boolean[][] visited,
                        int row, int col, int fromRow, int fromCol, char currentChar) {

        visited[row][col] = true;

        // Explore the four orthogonal neighbours
        int[][] directions = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};
        for (int[] dir : directions) {
            int nr = row + dir[0];
            int nc = col + dir[1];

            if (!isInBounds(nr, grid.length, nc, grid[0].length)) {
                continue;
            }
            if (grid[nr][nc] != currentChar) {
                continue; // different letter – not part of this component
            }
            if (nr == fromRow && nc == fromCol) {
                continue; // go back to the parent is not allowed
            }
            if (visited[nr][nc]) {
                // Visiting a previously visited cell means we have closed a loop.
                // Because we only start DFS from cells that appear at least four times,
                // the loop must contain at least four distinct positions.
                return true;
            }

            // Recurse deeper
            if (dfs(grid, visited, nr, nc, row, col, currentChar)) {
                return true;
            }
        }
        return false;
    }

    /** Helper – checks that a coordinate lies inside the grid */
    private static boolean isInBounds(int r, int maxR, int c, int maxC) {
        return r >= 0 && r < maxR && c >= 0 && c < maxC;
    }
}

/**
 * Very small wrapper around {@link BufferedReader} that supplies
 * convenient tokenised reading methods used by the original code.
 * It is kept deliberately simple – no extra state is stored beyond
 * what the original implementation needed.
 */
final class InputReader implements AutoCloseable {

    private final BufferedReader reader;
    private StringTokenizer tokenizer;

    InputReader(InputStream stream) {
        this.reader = new BufferedReader(new InputStreamReader(stream));
    }

    /** Returns the next token, loading a new line when the current one is exhausted */
    String next() {
        while (tokenizer == null || !tokenizer.hasMoreTokens()) {
            try {
                tokenizer = new StringTokenizer(reader.readLine());
            } catch (Exception e) {
                throw new RuntimeException(e);
            }
        }
        return tokenizer.nextToken();
    }

    /** Convenience wrappers for primitive types */
    int nextInt() { return Integer.parseInt(next()); }
    long nextLong() { return Long.parseLong(next()); }
    double nextDouble() { return Double.parseDouble(next()); }
    float nextFloat() { return Float.parseFloat(next()); }
    String nextLine() { try { return reader.readLine(); } catch (Exception e) { throw new RuntimeException(e); } }

    /** @param n number of elements to read */
    int[] nextIntegerArray(int n) {
        int[] a = new int[n];
        for (int i = 0; i < n; i++) a[i] = nextInt();
        return a;
    }

    /** @param n number of elements to read */
    long[] nextLongArray(int n) {
        long[] a = new long[n];
        for (int i = 0; i < n; i++) a[i] = nextLong();
        return a;
    }

    /** Close the underlying {@link BufferedReader} – also closes System.in when called from {@code main} */
    @Override
    public void close() throws Exception {
        reader.close();
    }
}

import java.io.*;
import java.util.*;

public class Main {

    /** Number of rows in the grid */
    private static int rows;
    /** Number of columns in the grid */
    private static int cols;

    /** Movement directions: up, left, down, right */
    private static final int[][] DIRECTIONS = {
        { -1, 0 },   // up
        { 0, -1 },   // left
        { 1, 0 },    // down
        { 0, 1 }     // right
    };

    public static void main(String[] args) throws IOException {
        try (BufferedReader br = new BufferedReader(
                new InputStreamReader(System.in))) {

            String[] firstLine = br.readLine().split("\\s+");
            rows = Integer.parseInt(firstLine[0]);
            cols = Integer.parseInt(firstLine[1]);

            char[][] grid = new char[rows][];
            for (int r = 0; r < rows; r++) {
                grid[r] = br.readLine().trim().toCharArray();
            }

            boolean[][] visited = new boolean[rows][cols];
            int[] parentIndex = new int[rows * cols + 2];

            boolean answerFound = false;
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (!visited[r][c]) {
                        // Reset state for a fresh component search
                        for (boolean[] row : visited) {
                            Arrays.fill(row, false);
                        }
                        Arrays.fill(parentIndex, 0);

                        if (searchPath(grid, visited, parentIndex, r, c, r, c)) {
                            answerFound = true;
                            break;
                        }
                    }
                }
                if (answerFound) {
                    break;
                }
            }

            System.out.println(answerFound ? "Yes" : "No");
        }
    }

    /**
     * Searches for a path that satisfies the original problem's condition.
     *
     * @return true if such a path exists, false otherwise
     */
    private static boolean searchPath(char[][] grid,
                                      boolean[][] visited,
                                      int[] parentIndex,
                                      int x,
                                      int y,
                                      int startX,
                                      int startY) {
        visited[x][y] = true;

        // Detect the special condition described in the original code:
        // when we are back at the start cell and the first neighbour of the start
        // has been assigned a parent.
        if (x == startX && y == startY && parentIndex[startX * cols + (startY + 1)] != 0) {
            return true;
        }

        for (int[] dir : DIRECTIONS) {
            int nx = x + dir[0];
            int ny = y + dir[1];

            if (!isInside(grid, nx, ny) || grid[nx][ny] != grid[startX][startY]) {
                continue;
            }

            int neighbourIdx = nx * cols + (ny + 1);   // mirrors original indexing
            int curIdx        = x * cols + (y + 1);

            // Prevent re‑using the same parent edge
            if (parentIndex[neighbourIdx] == curIdx) {
                continue;
            }

            parentIndex[neighbourIdx] = curIdx;

            if (visited[nx][ny]) {
                // If we have already visited this neighbour in the current search,
                // a valid cycle has been found.
                if (nx == startX && ny == startY) {
                    return true;
                }
            } else {
                if (searchPath(grid, visited, parentIndex, nx, ny, startX, startY)) {
                    return true;
                }
            }
        }

        return false;
    }

    /** Utility to verify that coordinates are within the grid bounds. */
    private static boolean isInside(char[][] grid, int x, int y) {
        return x >= 0 && x < grid.length && y >= 0 && y < grid[0].length;
    }
}

import java.io.*;
import java.util.*;

/**
 * Detects whether a grid contains a cycle formed by cells of the same character.
 *
 * The program reads:
 *      n m                     – dimensions of the grid
 *      n lines of m characters   – the grid itself
 *
 * For each connected component (using 4‑directional adjacency) that shares the same
 * character it performs a BFS. If during the BFS we encounter an already‑visited
 * neighbour that is **not** the node we arrived from, a cycle exists.
 *
 * Output:
 *      "Yes" – a cycle was found
 *      "No"  – no cycle was found
 */
public class FoxDots {

    /* ------------------------------------------------------------           */
    /*  Constants & small helper classes                                   */
    /* ------------------------------------------------------------           */

    /** Directions: up, left, down, right */
    private static final int[][] DIRECTIONS = {
            {-1, 0},   // up
            { 0,-1},   // left
            { 1, 0},   // down
            { 0, 1}    // right
    };

    /** Simple immutable point used as a key in maps/sets. */
    private static final class Point {
        final int row;
        final int col;

        Point(int row, int col) {
            this.row = row;
            this.col = col;
        }

        /** Returns a compact string representation, e.g. "3_5". */
        @Override
        public String toString() {
            return row + "_" + col;
        }

        @Override
        public boolean equals(Object o) {
            if (this == o) return true;
            if (!(o instanceof Point)) return false;
            Point p = (Point) o;
            return row == p.row && col == p.col;
        }

        @Override
        public int hashCode() {
            return Objects.hash(row, col);
        }
    }

    /* ------------------------------------------------------------           */
    /*  Main entry point                                                   */
    /* ------------------------------------------------------------           */

    public static void main(String[] args) throws IOException {
        /* ----- read input (try‑with‑resources guarantees the stream is closed) ----- */
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in))) {
            String[] sizeTokens = br.readLine().split("\\s+");
            int rows = Integer.parseInt(sizeTokens[0]);
            int cols = Integer.parseInt(sizeTokens[1]);

            char[][] grid = new char[rows][cols];
            for (int r = 0; r < rows; r++) {
                grid[r] = br.readLine().toCharArray();
            }

            boolean[][] visited = new boolean[rows][cols];
            Map<Point, Point> parent = new HashMap<>();

            /* ----- explore every component -------------------------------------- */
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (!visited[r][c]) {
                        if (containsCycle(grid, visited, parent, r, c)) {
                            System.out.println("Yes");
                            return;               // early exit – we already know the answer
                        }
                    }
                }
            }

            System.out.println("No");
        }
    }

    /* ------------------------------------------------------------           */
    /*  Cycle detection for a single component                               */
    /* ------------------------------------------------------------           */

    /**
     * Breadth‑first searches the component that starts at (startRow,startCol).
     * If a visited neighbour that is **not** the immediate parent is found,
     * a cycle exists.
     *
     * @return {@code true} if a cycle was discovered.
     */
    private static boolean containsCycle(char[][] grid,
                                         boolean[][] visited,
                                         Map<Point, Point> parent,
                                         int startRow,
                                         int startCol) {
        Queue<Point> queue = new LinkedList<>();
        Point start = new Point(startRow, startCol);
        queue.add(start);
        visited[startRow][startCol] = true;
        parent.put(start, null);                     // start has no parent

        while (!queue.isEmpty()) {
            Point cur = queue.poll();
            char curChar = grid[cur.row][cur.col];

            for (int[] dir : DIRECTIONS) {
                int nxtRow = cur.row + dir[0];
                int nxtCol = cur.col + dir[1];
                if (!inBounds(grid, nxtRow, nxtCol)) {
                    continue;
                }
                if (grid[nxtRow][nxtCol] != curChar) {
                    continue;                         // different character → ignore
                }

                Point neighbour = new Point(nxtRow, nxtCol);

                if (visited[nxtRow][nxtCol]) {
                    /*  If the neighbour has been visited before,
                        it can only indicate a cycle when it is NOT
                        the node we came from (the parent).            */
                    if (!parent.get(cur).equals(neighbour)) {
                        return true;                  // cycle found
                    }
                } else {
                    visited[nxtRow][nxtCol] = true;
                    parent.put(neighbour, cur);
                    queue.add(neighbour);
                }
            }
        }
        return false;                                 // no cycle in this component
    }

    /** Checks whether (r,c) lies inside the grid. */
    private static boolean inBounds(char[][] grid, int r, int c) {
        return r >= 0 && r < grid.length && c >= 0 && c < grid[0].length;
    }
}

/**
 * Detects whether a grid contains a cycle of adjacent cells with the same character.
 *
 * <p>Refactored for readability, testability and maintainability.
 */
public class GridCycleChecker {

    /** Directions: right, left, down, up */
    private static final int[] DX = {0, 0, 1, -1};
    /** Directions: right, left, down, up */
    private static final int[] DY = {1, -1, 0, 0};

    /** Grid dimensions */
    private final int rows;
    /** Grid dimensions */
    private final int cols;
    /** Characters of the grid */
    private final char[][] grid;
    /** Whether a cell has been visited during the search */
    private final boolean[][] visited;
    /** Parent of each cell in the DFS tree */
    private final Parent[][] parent;
    /** Input source */
    private final FastScanner scanner;
    /** Output destination */
    private final PrintWriter writer;

    /**
     * Creates a new cycle checker.
     *
     * @param scanner input scanner
     * @param writer  output printer
     * @param rows    number of rows
     * @param cols    number of columns
     * @param grid    grid of characters
     */
    private GridCycleChecker(FastScanner scanner, PrintWriter writer,
                             int rows, int cols, char[][] grid) {
        this.scanner = scanner;
        this.writer = writer;
        this.rows = rows;
        this.cols = cols;
        this.grid = grid;
        this.visited = new boolean[rows][cols];
        this.parent = new Parent[rows][cols];
    }

    /**
     * Entry point of the program.
     *
     * @param args command line arguments (unused)
     */
    public static void main(String[] args) throws Exception {
        try (FastScanner scanner = new FastScanner(System.in);
             PrintWriter writer = new PrintWriter(System.out)) {

            int rows = scanner.nextInt();
            int cols = scanner.nextInt();

            char[][] grid = new char[rows][];
            for (int i = 0; i < rows; i++) {
                grid[i] = scanner.nextString().toCharArray();
            }

            new GridCycleChecker(scanner, writer, rows, cols, grid)
                    .process();
        }
    }

    /**
            * Executes the cycle detection algorithm.
            *
            * Prints "Yes" if a cycle exists, otherwise prints "No".
            */
    private void process() {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (!visited[r][c] && dfs(r, c)) {
                    writer.println("Yes");
                    return;
                }
            }
        }
        writer.println("No");
    }

    /**
     * Depth‑first search that detects a cycle.
     *
     * @param r current row index
     * @param c current column index
     * @return {@code true} if a cycle is found from this cell
     */
    private boolean dfs(int r, int c) {
        visited[r][c] = true;
        Parent currentParent = parent[r][c];

        for (int dir = 0; dir < 4; dir++) {
            int nr = r + DX[dir];
            int nc = c + DY[dir];

            if (!isInBounds(nr, nc)) {
                continue;
            }

            char currentChar = grid[r][c];
            char nextChar = grid[nr][nc];

            if (currentChar != nextChar) {
                continue;
            }

            if (visited[nr][nc]) {
                // Cycle detected when the neighboring cell is visited
                // and it is not the parent of the current cell.
                if (currentParent == null || !currentParent.equals(new Parent(nr, nc))) {
                    return true;
                }
            } else {
                // First time we see the neighbor – record its parent and recurse.
                parent[nr][nc] = new Parent(r, c);
                if (dfs(nr, nc)) {
                    return true;
                }
            }
        }
        return false;
    }

    /** Simple bounds check. */
    private boolean isInBounds(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    /** Utility class that stores a cell coordinate. */
    private static final class Parent {
        final int row;
        final int col;

        Parent(int row, int col) {
            this.row = row;
            this.col = col;
        }

        /** Equality based on both coordinates. */
        @Override
        public boolean equals(Object o) {
            if (this == o) return true;
            if (!(o instanceof Parent)) return false;
            Parent that = (Parent) o;
            return row == that.row && col == that.col;
        }
    }

    /**
     * Fast scanner that reads tokens from an {@link InputStream}.
     * Identical in behaviour to the original {@code InputReader} but renamed
     * for clarity.
     */
    private static final class FastScanner {
        private final InputStream stream;
        private final byte[] buffer = new byte[1024];
        private int currentChar;
        private int numChars;

        FastScanner(InputStream stream) {
            this.stream = stream;
        }

        private int read() {
            if (numChars == -1) {
                throw new IllegalStateException();
            }
            if (currentChar >= numChars) {
                currentChar = 0;
                numChars = stream.read(buffer);
                if (numChars <= 0) {
                    return -1;
                }
            }
            return buffer[currentChar++];
        }

        private boolean isSpaceChar(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        /** Returns the next token (a non‑space sequence). */
        private String nextString() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }
            StringBuilder sb = new StringBuilder();
            do {
                sb.appendCodePoint(c);
                c = read();
            } while (!isSpaceChar(c));
            return sb.toString();
        }

        /** Convenience wrapper around {@link #nextString()} for integers. */
        int nextInt() {
            return Integer.parseInt(nextString());
        }

        /** Checks whether another token is available. */
        boolean hasNext() {
            int c;
            while ((c = peek()) != -1 && isSpaceChar(c)) {
                read();
            }
            return c != -1;
        }

        /** Peeks at the next character without consuming it. */
        private int peek() {
            if (numChars == -1) {
                return -1;
            }
            if (currentChar >= numChars) {
                currentChar = 0;
                try {
                    numChars = stream.read(buffer);
                } catch (IOException e) {
                    throw new UncheckedIOException(e);
                }
                if (numChars <= 0) {
                    return -1;
                }
            }
            return buffer[currentChar];
        }

        /** Skips exactly {@code x} characters. */
        void skip(int x) {
            while (x-- > 0) {
                read();
            }
        }
    }
}

