/**
 * Simple scanner that treats each token separately and provides a line reader.
 * It throws {@link UncheckedIOException} on I/O errors for brevity.
 */
class FastScanner {
    private final BufferedReader reader;
    private StringTokenizer tokenizer = null;

    FastScanner(InputStream stream) {
        this.reader = new BufferedReader(new InputStreamReader(stream));
    }

    /** Returns the next whitespace‑delimited token. */
    String next() {
        while (tokenizer == null || !tokenizer.hasMoreTokens()) {
            try {
                tokenizer = new StringTokenizer(reader.readLine());
            } catch (IOException e) {
                throw new UncheckedIOException(e);
            }
        }
        return tokenizer.nextToken();
    }

    int nextInt() {
        return Integer.parseInt(next());
    }

    /** Returns the next full line, trimming the trailing newline characters. */
    String nextLine() {
        try {
            return reader.readLine();
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
    }
}

/**
 * Detects whether the given grid contains a closed cycle (length ≥ 4) of equal characters.
 */
class CycleDetector {

    /** Four possible movement directions: right, left, down, up */
    private static final int[][] DIRECTIONS = {{0, 1}, {0, -1}, {1, 0}, {-1, 0}};

    private char[][] grid;          // the input grid
    private int rows;               // number of rows
    private int cols;               // number of columns
    private boolean[][] visited;    // tracks visited cells during each DFS

    /** Reads the grid from the scanner. */
    void readGrid(FastScanner scanner, int rows, int cols) {
        this.rows = rows;
        this.cols = cols;
        this.grid = new char[rows][];
        for (int r = 0; r < rows; r++) {
            String line = scanner.nextLine().trim();
            this.grid[r] = line.toCharArray();
        }
        this.visited = new boolean[rows][cols];
    }

    /** Detects the presence of a closed cycle.
     *  A cycle is considered closed when we can step back onto the start cell
     *  after taking at least 3 moves (=> 4 distinct cells). */
    boolean hasCycle() {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                resetVisited();                       // start a fresh search
                if (dfs(r, c, r, c, 0)) {             // begin DFS from (r,c)
                    return true;
                }
            }
        }
        return false;
    }

    /** Clears the visited matrix before each new start cell. */
    private void resetVisited() {
        for (boolean[] row : visited) {
            Arrays.fill(row, false);
        }
    }

    /** Depth‑first search exploring neighbours of the same character. */
    private boolean dfs(int sr, int sc, int cr, int cc, int steps) {
        visited[cr][cc] = true;

        // If we have returned to the start after at least 3 moves, a cycle exists.
        if (cr == sr && cc == sc && steps >= 3) {
            return true;
        }

        // Explore all four directions
        for (int[] dir : DIRECTIONS) {
            int nr = cr + dir[0];
            int nc = cc + dir[1];

            if (!isInside(nr, nc)) {
                continue;                     // out of bounds
            }
            if (visited[nr][nc]) {
                continue;                     // already processed in this DFS
            }
            if (grid[nr][nc] != grid[cr][cc]) {
                continue;                     // different character, cannot continue
            }

            if (dfs(sr, sc, nr, nc, steps + 1)) {
                return true;                  // propagate success upwards
            }
        }
        return false;                       // no cycle found from this path
    }

    /** Returns true if the coordinates are within the grid limits. */
    private boolean isInside(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;

/**
 * Refactored solution for the word‑search‑like problem.
 * The program reads a grid of characters, then determines whether a path
 * exists where each step moves to an adjacent cell (up, down, left, right)
 * that contains the same character as the current cell.
 */
public class WordSearchSolver {

    /** Directions used for exploring neighbours (up, down, left, right). */
    private static final int[] ROW_DELTAS = {-1, 1, 0, 0};
    private static final int[] COL_DELTAS = {0, 0, -1, 1};

    /**
     * Entry point of the application.
     *
     * @param args command‑line arguments (unused)
     */
    public static void main(String[] args) throws IOException {
        // BufferedReader can be closed automatically with try‑with‑resources.
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in))) {
            String header = br.readLine();                     // first line: rows cols
            String[] headerParts = header.trim().split("\\s+");
            int rows = Integer.parseInt(headerParts[0]);
            int cols = Integer.parseInt(headerParts[1]);

            String[] grid = new String[rows];
            for (int r = 0; r < rows; r++) {
                grid[r] = br.readLine();                        // each subsequent line is a row
            }

            boolean[][] visited = new boolean[rows][cols];
            boolean found = hasPath(grid, rows, cols, visited);

            System.out.println(found ? "Yes" : "No");
        }
    }

    /**
     * Determines whether any path exists that satisfies the adjacency rule.
     *
     * @param grid      the character grid
     * @param rows      number of rows in the grid
     * @param cols      number of columns in the grid
     * @param visited   matrix tracking visited cells throughout the search
     * @return {@code true} if a valid path is found; otherwise {@code false}
     */
    private static boolean hasPath(String[] grid, int rows, int cols, boolean[][] visited) {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (!visited[r][c] && canReach(grid, visited, r, c, r, c)) {
                    return true;
                }
            }
        }
        return false;
    }

    /**
     * Depth‑first search that tries to extend a path from the current cell.
     *
     * @param grid        the character grid
     * @param visited     matrix used to remember visited cells
     * @param curRow      current row index
     * @param curCol      current column index
     * @param startRow    row where the current path started
     * @param startCol    column where the current path started
     * @return {@code true} if the recursive exploration leads to a successful path
     */
    private static boolean canReach(String[] grid,
                                    boolean[][] visited,
                                    int curRow,
                                    int curCol,
                                    int startRow,
                                    int startCol) {
        if (visited[curRow][curCol]) {
            return true;                 // already visited – path succeeded
        }

        visited[curRow][curCol] = true;   // mark current cell as part of the current path
        char currentChar = grid[curRow].charAt(curCol);

        // Explore the four orthogonal neighbours
        for (int d = 0; d < 4; d++) {
            int nextRow = curRow + ROW_DELTAS[d];
            int nextCol = curCol + COL_DELTAS[d];

            if (isWithinBounds(nextRow, nextCol, rows, cols)
                    && grid[nextRow].charAt(nextCol) == currentChar
                    && !(nextRow == startRow && nextCol == startCol)) {
                if (canReach(grid, visited, nextRow, nextCol, startRow, startCol)) {
                    return true;
                }
            }
        }
        return false;
    }

    /**
     * Checks whether a given cell coordinate lies inside the grid boundaries.
     *
     * @param r        row index to test
     * @param c        column index to test
     * @param rows     total number of rows
     * @param cols     total number of columns
     * @return {@code true} if the coordinate is valid; otherwise {@code false}
     */
    private static boolean isWithinBounds(int r, int c, int rows, int cols) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }
}

import java.io.*;
import java.util.*;

public class Main {

    /* --------------------------------------------------------------
     *  Fast input utilities – encapsulate all byte‑level reading logic.
     * -------------------------------------------------------------- */
    private static final class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[16_384];   // reuse a reasonably sized buffer
        private int ptr = 0;   // current position in the buffer
        private int len = 0;   // actual length of the data currently in the buffer

        FastScanner(InputStream in) {
            this.in = in;
        }

        /** Reads the next byte, handling buffer refills automatically. */
        private int readByte() throws IOException {
            if (len < 0) throw new InputMismatchException();
            if (ptr >= len) {               // need to refill the buffer
                ptr = 0;
                len = in.read(buffer);
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        /** Helper – skips over whitespace characters. */
        private int skipUntilNonSpace() throws IOException {
            int b;
            while ((b = readByte()) != -1 && isSpaceChar(b)) {}
            return b;
        }

        /** Checks whether a character is considered whitespace for tokenisation. */
        private boolean isSpaceChar(int c) {
            return !(c >= 33 && c <= 126);
        }

        /** Reads the next token (non‑whitespace characters). */
        private String nextToken() throws IOException {
            int b = skipUntilNonSpace();
            if (b == -1) return "";
            StringBuilder sb = new StringBuilder();
            sb.appendCodePoint(b);
            b = readByte();
            while (b != -1 && !isSpaceChar(b)) {
                sb.appendCodePoint(b);
                b = readByte();
            }
            return sb.toString();
        }

        int nextInt() throws IOException               { return Integer.parseInt(nextToken()); }
        long nextLong() throws IOException             { return Long.parseLong(nextToken()); }
        char nextChar() throws IOException             { return (char) skipUntilNonSpace(); }
        char[] nextCharArray(int size) throws IOException {
            char[] arr = new char[size];
            for (int i = 0; i < size; i++) arr[i] = nextChar();
            return arr;
        }
        char[][] nextCharMatrix(int rows) throws IOException {
            char[][] mat = new char[rows][];
            for (int i = 0; i < rows; i++) mat[i] = nextCharArray(nextInt());
            return mat;
        }
    }

    /* --------------------------------------------------------------
     *  Direction vectors – keep them in a tiny class for clarity.
     * -------------------------------------------------------------- */
    private static final class Direction {
        static final int[] DX = {1, 0, -1, 0};
        static final int[] DY = {0, 1, 0, -1};
    }

    /* --------------------------------------------------------------
     *  Core solver – isolates all game‑logic from the I/O handling.
     * -------------------------------------------------------------- */
    private static final class Solver {
        private final FastScanner fs;
        private final PrintWriter out;

        Solver(FastScanner fs, PrintWriter out) {
            this.fs = fs;
            this.out = out;
        }

        /** Entry point used by `main`. */
        void solve() {
            final int n = fs.nextInt();          // rows
            final int m = fs.nextInt();          // columns

            char[][] grid = fs.nextCharMatrix(n); // whole board
            boolean[][] visited = new boolean[n][m];

            boolean foundCycle = false;
            outer:
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    if (!visited[i][j]) {
                        foundCycle = dfs(grid, visited, i, j, -1, -1, grid[i][j]);
                        if (foundCycle) break outer;    // stop as soon as a cycle is found
                    }
                }
            }

            out.println(foundCycle ? "Yes" : "No");
        }

        /** Depth‑first search that detects a cycle of length ≥ 2 with identical characters. */
        private boolean dfs(char[][] grid, boolean[][] visited, int x, int y,
                           int parentX, int parentY, char ch) {
            if (visited[x][y]) {
                // Reached a visited cell that is not the immediate parent → cycle detected
                return true;
            }
            visited[x][y] = true;

            for (int d = 0; d < 4; d++) {
                int nx = x + Direction.DX[d];
                int ny = y + Direction.DY[d];
                if (!inBounds(grid, nx, ny)) continue;          // outside board?
                if (nx == parentX && ny == parentY) continue;   // would go back to parent
                if (grid[nx][ny] != ch) continue;               // different character
                if (dfs(grid, visited, nx, ny, x, y, ch)) {
                    return true;                               // propagate success upward
                }
            }
            return false; // no cycle found from this cell
        }

        private boolean inBounds(char[][] grid, int x, int y) {
            return 0 <= x && x < grid.length && 0 <= y && y < grid[0].length;
        }
    }

    /* --------------------------------------------------------------
     *  Application entry point – handles input source selection and timing.
     * -------------------------------------------------------------- */
    public static void main(String[] args) throws Exception {
        // The original program allows an optional pre‑populated INPUT string.
        // Leaving it empty makes the scanner read from stdin.
        String input = "";   // set to a non‑empty string to use a simulated input source

        // Choose the appropriate InputStream (real stdin or the provided string)
        InputStream source = input.isEmpty()
                ? System.in
                : new ByteArrayInputStream(input.getBytes());

        FastScanner fs = new FastScanner(source);
        PrintWriter out = new PrintWriter(System.out, true); // auto‑flush on println()

        long start = System.currentTimeMillis();
        new Solver(fs, out).solve();
        out.flush();

        // When we used a simulated input, print the elapsed time to stderr.
        if (!input.isEmpty()) {
            System.err.println((System.currentTimeMillis() - start) + " ms");
        }
    }
}

import java.util.ArrayDeque;
import java.util.Deque;
import java.util.Scanner;

/**
 * Represents a rectangular grid of characters and provides utilities
 * to detect cycles of length at least 4 consisting of the same character.
 */
final class Grid {
    private final char[][] board;
    private final int rows;
    private final int cols;

    Grid(int rows, int cols) {
        this.rows = rows;
        this.cols = cols;
        this.board = new char[rows][cols];
    }

    /** Fill the grid from a {@link Scanner}. */
    static Grid fromInput(Scanner scanner) {
        int rows = scanner.nextInt();
        int cols = scanner.nextInt();
        Grid grid = new Grid(rows, cols);
        for (int r = 0; r < rows; r++) {
            String line = scanner.next();
            for (int c = 0; c < cols; c++) {
                grid.board[r][c] = line.charAt(c);
            }
        }
        return grid;
    }

    int rows() {
        return rows;
    }

    int cols() {
        return cols;
    }

    char at(int r, int c) {
        return board[r][c];
    }

    /** Directions: up, down, left, right. */
    private static final int[] DR = {-1, 1, 0, 0};
    private static final int[] DC = {0, 0, -1, 1};

    /** Tries to find a cycle of length ≥ 4 that starts at (sr, sc). */
    boolean findCycleFrom(int sr, int sc) {
        boolean[][] visited = new boolean[rows][cols];
        depth = 0;
        recursionStack.clear();                 // reuse static stack
        recursionStack.push(new Pos(sr, sc));
        visited[sr][sc] = true;
        return dfs(sr, sc, sr, sc, visited);
    }

    /** Depth of the current recursive call (used to enforce minimum length). */
    private static int depth;
    /** Stack used for the DFS recursion. */
    private static final Deque<Pos> recursionStack = new ArrayDeque<>();

    /** Simple container for a coordinate pair. */
    private static final class Pos {
        final int r, c;
        Pos(int r, int c) {
            this.r = r;
            this.c = c;
        }
    }

    /** Depth counter used during the search. */
    private static int depth = 0;

    /**
     * Depth‑first search that looks for a cycle returning to the start cell.
     *
     * @return {@code true} if a cycle of length ≥ 4 is found.
     */
    private boolean dfs(int sr, int sc, int r, int c, boolean[][] visited) {
        Pos cur = new Pos(r, c);
        Pos start = new Pos(sr, sc);
        Pos last = recursionStack.peekLast(); // cell we came from

        // If we stepped back onto the start cell after at least 4 steps, we found a cycle.
        if (r == start.r && c == start.c && depth >= 4) {
            return true;
        }

        // Explore neighbours.
        for (int dir = 0; dir < 4; dir++) {
            int nr = r + DR[dir];
            int nc = c + DC[dir];

            // Bounds check.
            if (nr < 0 || nr >= rows() || nc < 0 || nc >= cols()) {
                continue;
            }

            // Same character?
            if (board[nr][nc] != board[r][c]) {
                continue;
            }

            // Do not go back directly to the cell we just came from.
            if (nr == last.r && nc == last.c) {
                continue;
            }

            // Already visited this cell in the current search?
            if (visited[nr][nc]) {
                continue;
            }

            // Continue the search.
            visited[nr][nc] = true;
            recursionStack.push(new Pos(nr, nc));
            depth++;

            if (dfs(sr, sc, nr, nc, visited)) {
                return true;
            }

            // Backtrack.
            depth--;
            recursionStack.pop();
            visited[nr][nc] = false;
        }
        return false;
    }

    /** Checks whether the whole board contains any qualifying cycle. */
    boolean hasCycle() {
        boolean[][] globalVisited = new boolean[rows][cols];
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (!globalVisited[r][c]) {
                    if (findCycleFrom(r, c)) {
                        return true;
                    }
                    // Mark everything we examined from this start cell as visited
                    // to avoid re‑searching from cells that cannot start a new cycle.
                    markVisitedFrom(r, c, globalVisited);
                }
            }
        }
        reset(); // clear static fields for possible subsequent calls
        return false;
    }

    /** Helper that marks all cells reachable from (sr,sc) as visited. */
    private void markVisitedFrom(int sr, int sc, boolean[][] visited) {
        Deque<Pos> q = new ArrayDeque<>();
        q.push(new Pos(sr, sc));
        visited[sr][sc] = true;
        while (!q.isEmpty()) {
            Pos p = q.poll();
            for (int dir = 0; dir < 4; dir++) {
                int nr = p.r + DR[dir];
                int nc = p.c + DC[dir];
                if (nr < 0 || nr >= rows() || nc < 0 || nc >= cols()) continue;
                if (!visited[nr][nc] && board[nr][nc] == board[p.r][p.c]) {
                    visited[nr][nc] = true;
                    q.push(new Pos(nr, nc));
                }
            }
        }
    }

    /** Resets the static fields used by the DFS for a fresh run. */
    private static void reset() {
        depth = 0;
        recursionStack.clear();
    }
}

/**
 * Main class containing only input handling and output.
 */
public class Main {
    public static void main(String[] args) {
        Grid grid = Grid.fromInput(new Scanner(System.in));

        // Scan the whole board; as soon as we discover a cycle we can stop.
        for (int r = 0; r < grid.rows(); r++) {
            for (int c = 0; c < grid.cols(); c++) {
                Grid.depth = 0;                     // reset depth for a new start
                Grid.recursionStack.clear();         // reset static DFS stack
                if (grid.findCycleFrom(r, c)) {
                    System.out.println("Yes");
                    return;
                }
                // Optional optimisation: skip cells already known to belong to a
                // component that cannot start a new cycle – omitted for brevity.
            }
        }
        System.out.println("No");
    }
}

import java.io.*;
import java.util.*;

public class Main {

    public static void main(String[] args) throws IOException {
        /* ---------- Input ---------- */
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String[] first = br.readLine().split("\\s+");
        int n = Integer.parseInt(first[0]);
        int m = Integer.parseInt(first[1]);

        char[][] grid = new char[n][m];
        for (int i = 0; i < n; i++) {
            String line = br.readLine();
            if (line == null) line = "";
            line = line.trim();
            for (int j = 0; j < m; j++) {
                grid[i][j] = line.charAt(j);
            }
        }

        /* ---------- Cycle detection ---------- */
        boolean[][] visited = new boolean[n][m];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (!visited[i][j] && hasCycle(grid, visited, i, j, -1, -1)) {
                    System.out.println("Yes");
                    return;
                }
            }
        }
        System.out.println("No");
    }

    /**
     * Depth‑first search that searches for a cycle of at least length 4.
     *
     * @param grid   the character grid
     * @param visited marker array for visited cells
     * @param x      current row
     * @param y      current column
     * @param px     previous row (parent) or -1 if none
     * @param py     previous column (parent) or -1 if none
     * @return true if a cycle was found starting from (x, y)
     */
    private static boolean hasCycle(char[][] grid, boolean[][] visited, int x, int y, int px, int py) {
        visited[x][y] = true;

        // Up, Down, Left, Right
        int[] dx = {-1, 1, 0, 0};
        int[] dy = {0, 0, -1, 1};

        for (int dir = 0; dir < 4; dir++) {
            int nx = x + dx[dir];
            int ny = y + dy[dir];

            // Bounds check
            if (nx < 0 || nx >= grid.length || ny < 0 || ny >= grid[0].length) continue;

            // Must be the same character to continue the path
            if (grid[nx][ny] != grid[x][y]) continue;

            if (!visited[nx][ny]) {
                if (hasCycle(grid, visited, nx, ny, x, y)) {
                    return true;      // propagate the found cycle upward
                }
            } else if (nx != px || ny != py) {
                // A visited neighbour that is not the immediate parent indicates a cycle
                return true;
            }
        }
        return false;
    }
}

import java.io.*;

public class FoxAndTwoDots {

    /** All four orthogonal directions (right, down, left, up). */
    private static final int[][] DIRECTIONS = {
            {0, 1},   // right
            {1, 0},   // down
            {0, -1},  // left
            {-1, 0}   // up
    };

    /** Entry point of the program. */
    public static void main(String[] args) throws IOException {
        // Read input with try‑with‑resources to guarantee closure.
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in))) {
            String[] header = br.readLine().split("\\s+");
            int rows = Integer.parseInt(header[0]);
            int cols = Integer.parseInt(header[1]);

            // Load the grid.
            char[][] grid = new char[rows][];
            for (int i = 0; i < rows; i++) {
                grid[i] = br.readLine().toCharArray();
            }

            // Shared visited matrix – prevents re‑processing of cells.
            boolean[][] visited = new boolean[rows][cols];

            // Search for a cycle in each unvisited component.
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (!visited[i][j]) {
                        if (hasCycle(grid, visited, i, j, grid[i][j], -1, -1)) {
                            System.out.println("Yes");
                            return;   // Cycle found → exit early.
                        }
                    }
                }
            }
            System.out.println("No");
        }
    }

    /**
     * Detects whether a cycle consisting of the same character exists,
     * starting from {@code (row, col)}. The search follows a depth‑first
     * approach while keeping track of the previous cell to avoid back‑tracking.
     *
     * @param grid      character grid
     * @param visited   shared visited matrix
     * @param row       current row
     * @param col       current column
     * @param ch        character we are exploring
     * @param pr        previous row (parent) – {@code -1} if none
     * @param pc        previous column (parent) – {@code -1} if none
     * @return {@code true} if a cycle is detected
     */
    private static boolean hasCycle(char[][] grid, boolean[][] visited,
                                    int row, int col, char ch,
                                    int pr, int pc) {
        // A previously visited cell that is not the immediate parent signals a cycle.
        if (visited[row][col]) {
            return true;
        }

        // The cell must contain the character we are currently exploring.
        if (grid[row][col] != ch) {
            return false;
        }

        // Mark this cell as visited for the current connected component.
        visited[row][col] = true;

        // Explore each neighbour.
        for (int[] dir : DIRECTIONS) {
            int nr = row + dir[0];
            int nc = col + dir[1];

            // Skip coordinates outside the grid.
            if (!isInBounds(grid, nr, nc)) {
                continue;
            }

            // Do not go back to the parent cell.
            if (nr == pr && nc == pc) {
                continue;
            }

            // Recurse only if the neighbour holds the same character.
            if (grid[nr][nc] == ch) {
                if (hasCycle(grid, visited, nr, nc, ch, row, col)) {
                    return true;   // Propagate the success upward.
                }
            }
        }
        return false;
    }

    /** Checks whether a coordinate lies inside the bounds of the grid. */
    private static boolean isInBounds(char[][] grid, int r, int c) {
        return r >= 0 && r < grid.length && c >= 0 && c < grid[0].length;
    }
}

/**
 * Fox and Two Dots – Detect a cycle of at least four same‑colored adjacent cells.
 *
 * <p>This implementation is deliberately kept simple and readable while preserving the
 * original algorithm.  All mutable state is confined to the {@link Solver} class,
 * the scanner is isolated in its own helper, and naming, constants and documentation
 * are improved for maintainability.</p>
 */
public class FoxAndTwoDots {

    /** ---------------------------------------------------  Inner classes  --------------------------------------------------- */

    /** Holds the core solving logic. */
    static class Solver {

        /** Grid size. */
        private final int rows;
        private final int columns;

        /** Grid of characters (uppercase letters). */
        private final char[][] board;

        /** Movement directions – up, left, right, down. */
        private static final int[] DR = {-1, 0, 0, 1};
        private static final int[] DC = {0, -1, 1, 0};

        /** Cached reference to the input scanner. */
        private final FastScanner input;
        /** Cached reference to the output printer. */
        private final PrintWriter output;

        /** Constructor – injects the input source and output destination. */
        Solver(FastScanner scanner, PrintWriter printer) {
            this.input = scanner;
            this.output = printer;
        }

        /** Entry point used by {@link #main(String[])}. */
        void solve() {
            readDimensionsAndBoard();
            if (hasAnyCycle()) {
                output.println("Yes");
            } else {
                output.println("No");
            }
        }

        /** Reads N and M, then the board itself. */
        private void readDimensionsAndBoard() {
            rows = input.nextInt();
            columns = input.nextInt();

            board = new char[rows][];
            for (int r = 0; r < rows; r++) {
                String line = input.next();
                char[] chars = line.toCharArray();
                board[r] = chars;
            }
        }

        /** Determines whether any cycle exists in the grid. */
        private boolean hasAnyCycle() {
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < columns; c++) {
                    if (tryStartCycleFrom(r, c, r, c, -1, -1)) {
                        return true;
                    }
                }
            }
            return false;
        }

        /**
         * Attempts to find a cycle that starts and ends at {@code startR}/{@code startC}
         * using the current cell as the first step.  The method explores neighbours
         * recursively, ignoring the immediate predecessor {@code prevR}/{@code prevC}.
         *
         * @return {@code true} if a cycle of length ≥ 4 is discovered.
         */
        private boolean tryStartCycleFrom(int startR, int startC,
                                          int curR, int curC,
                                          int prevR, int prevC) {
            if (curR == startR && curC == startC && !(prevR == startR && prevC == startC)) {
                // Reached the start again after moving at least one step.
                return true;
            }

            char colour = board[curR][curC];
            for (int dir = 0; dir < 4; dir++) {
                int nr = curR + DR[dir];
                int nc = curC + DC[dir];

                // Bounds check.
                if (!inBounds(nr, nc)) {
                    continue;
                }
                // Must stay on the same colour.
                if (board[nr][nc] != colour) {
                    continue;
                }
                // Do not step back to the previous cell.
                if (nr == prevR && nc == prevC) {
                    continue;
                }

                if (tryStartCycleFrom(startR, startC, nr, nc, curR, curC)) {
                    return true;
                }
            }
            return false;
        }

        /** Simple bounds guard. */
        private boolean inBounds(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < columns;
        }
    }

    /** ---------------------------------------------------  Fast scanner  --------------------------------------------------- */

    /**
     * Very small wrapper around {@link InputStream} that supplies primitive tokens
     * without the overhead of {@link Scanner}.  It is deliberately kept static so
     * that it can be instantiated once in {@code main}.
     */
    static class FastScanner implements AutoCloseable {

        private final InputStream stream;
        private final byte[] buffer = new byte[1024];
        private int bufferPointer = 0;
        private int bytesRead = 0;

        FastScanner(InputStream stream) {
            this.stream = stream;
        }

        private int readByte() {
            if (bufferPointer >= bytesRead) {
                refreshBuffer();
                if (bytesRead == -1) {
                    return -1;
                }
                bufferPointer = 0;
            }
            return buffer[bufferPointer++];
        }

        private void refreshBuffer() throws IOException {
            bytesRead = stream.read(buffer);
        }

        /** Consumes whitespace and returns the next token. */
        private String next() {
            int b;
            do {
                b = readByte();
            } while (isSpaceChar(b));

            StringBuilder sb = new StringBuilder();
            do {
                sb.append((char) readByte());
                b = readByte();
            } while (!isSpaceChar(b));

            return sb.toString();
        }

        /** @return {@code true} for spaces, newlines, tabs or EOF. */
        private boolean isSpaceChar(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        /** @return {@code true} for line‑ending characters. */
        private boolean isEndOfLine(int c) {
            return c == '\n' || c == '\r' || c == -1;
        }

        /** Convenience wrappers for the primitives used in the problem. */
        int nextInt()    { return Integer.parseInt(next()); }
        long nextLong()  { return Long.parseLong(next()); }
        double nextDouble(){ return Double.parseDouble(next()); }
    }

    /** ---------------------------------------------------  Program entry point  --------------------------------------------------- */

    public static void main(String[] args) throws Exception {
        try (FastScanner scanner = new FastScanner(System.in)) {
            Solver solver = new Solver(scanner, new PrintWriter(System.out, true));
            solver.solve();
        }
    }
}

/* -------------------------------------------------------------
 *  Cycle detector for a 2‑D character grid
 * ------------------------------------------------------------- */
import java.util.Arrays;
import java.util.Scanner;

/**
 * Entry point of the application.
 */
public class Solution {

    public static void main(String[] args) {
        // Try‑with‑resources ensures the Scanner is closed automatically.
        try (Scanner scanner = new Scanner(System.in)) {
            int rows = scanner.nextInt();
            int cols = scanner.nextInt();

            char[][] grid = new char[rows][];
            for (int i = 0; i < rows; i++) {
                grid[i] = scanner.next().toCharArray();
            }

            CycleDetector detector = new CycleDetector(rows, cols, grid);
            System.out.println(detector.hasCycle() ? "Yes" : "No");
        }
    }
}

/**
 * Encapsulates the logic required to discover a cycle of equal
 * characters in a rectangular grid.
 */
final class CycleDetector {

    private final char[][] grid;
    private final boolean[][] visited;
    private final Position[][] parent;
    private boolean cycleFound = false;

    CycleDetector(int rows, int cols, char[][] grid) {
        this.grid = grid;
        this.visited = new boolean[rows][cols];
        this.parent = new Position[rows][cols];
        // initialise all parents to a sentinel "null" position
        for (Position[] row : parent) {
            Arrays.fill(row, Position.NULL);
        }
    }

    /** Public query used by {@link Solution#main}. */
    boolean hasCycle() {
        for (int r = 0; r < grid.length && !cycleFound; r++) {
            for (int c = 0; c < grid[r].length && !cycleFound; c++) {
                if (!visited[r][c]) {
                    dfs(r, c, grid[r][c]);
                }
            }
        }
        return cycleFound;
    }

    /** Depth‑first search starting from (row, col). */
    private void dfs(int row, int col, char ch) {
        visited[row][col] = true;
        exploreNeighbors(row, col, ch);
    }

    /** Examine the four orthogonal neighbours of the current cell. */
    private void exploreNeighbors(int row, int col, char ch) {
        int[][] directions = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};
        for (int[] dir : directions) {
            int nr = row + dir[0];
            int nc = col + dir[1];
            if (isSafe(row, col, nr, nc, ch)) {
                Position neighbour = parent[nr][nc] != null ? parent[nr][nc] : Position.of(nr, nc);
                // A visited neighbour that is *not* the immediate parent means a cycle.
                if (visited[nr][nc] && !parent[row][col].equals(neighbour)) {
                    cycleFound = true;
                    return;
                }
                if (!visited[nr][nc]) {
                    parent[nr][nc] = Position.of(row, col);
                    dfs(nr, nc, ch);
                    if (cycleFound) {
                        return;
                    }
                }
            }
        }
    }

    /** Checks bounds and whether the neighbour has the same character as the start cell. */
    private boolean isSafe(int curR, int curC, int nR, int nC, char ch) {
        return nR >= 0 && nR < grid.length
                && nC >= 0 && nC < grid[0].length
                && grid[nR][nC] == ch;
    }
}

/**
 * Immutable container for a grid coordinate.
 * Used for the parent matrix to keep track of the DFS tree.
 */
final class Position {
    final int row;
    final int col;

    private Position(int row, int col) {
        this.row = row;
        this.col = col;
    }

    /** Factory method – makes creation concise. */
    static Position of(int row, int col) {
        return new Position(row, col);
    }

    /** Sentinel object representing “no parent”. */
    static final Position NULL = new Position(Integer.MIN_VALUE, Integer.MIN_VALUE);

    @Override
    public boolean equals(Object o) {
        if (this == o) return true;
        if (!(o instanceof Position)) return false;
        Position that = (Position) o;
        return row == that.row && col == that.col;
    }

    @Override
    public int hashCode() {
        return 31 * row + col;
    }
}

import java.io.*;
import java.util.*;

public class P510B {

    /** Directions: right, down, left, up */
    private static final int[][] DIRS = {{1, 0}, {0, 1}, {-1, 0}, {0, -1}};

    /** Fast input helper */
    private static class InputReader {
        private final BufferedReader br;
        private StringTokenizer st;

        InputReader() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        /** Returns next token or null if EOF */
        String nextToken() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                String line = br.readLine();
                if (line == null) {
                    return null;
                }
                st = new StringTokenizer(line);
            }
            return st.nextToken();
        }

        int nextInt()throws IOException { return Integer.parseInt(nextToken()); }
        long nextLong()throws IOException { return Long.parseLong(nextToken()); }
        String next()throws IOException { return nextToken(); }
        String nextLine()throws IOException { return br.readLine(); }
    }

    /** --------------------------------------------------------------
     *  Main solving logic
     *  --------------------------------------------------------------
     */
    private InputReader reader;
    private PrintWriter writer;

    private int rows, cols;
    private char[][] board;
    private boolean[][] visited;

    public void solve() throws Exception {
        reader = new InputReader();
        writer = new PrintWriter(new BufferedOutputStream(System.out));

        rows = reader.nextInt();
        cols = reader.nextInt();

        board = new char[rows][];
        for (int r = 0; r < rows; r++) {
            board[r] = reader.next().toCharArray();
        }

        visited = new boolean[rows][cols];

        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (!visited[r][c]) {
                    if (hasCycle(r, c, -1, -1, board[r][c])) {
                        writer.println("Yes");
                        return;
                    }
                }
            }
        }

        writer.println("No");
        writer.flush();
    }

    /**
     * Depth‑first search that looks for a cycle of at least length 2
     * consisting of the same character. The recursion avoids stepping
     * back to the cell we came from (parent coordinates).
     *
     * @param r        current row
     * @param c        current column
     * @param pr        previous row (or -1 when there is no parent)
     * @param pc        previous column (or -1 when there is no parent)
     * @param ch        character we are exploring
     * @return true if a cycle is found
     */
    private boolean hasCycle(int r, int c, int pr, int pc, char ch) {
        if (visited[r][c]) {
            return true;                  // reached a previously visited cell → cycle
        }

        visited[r][c] = true;

        for (int[] d : DIRS) {
            int nr = r + d[0];
            int nc = c + d[1];

            // bounds check
            if (nr < 0 || nr >= rows || nc < 0 || nc >= cols) {
                continue;
            }
            // must be the same character
            if (board[nr][nc] != ch) {
                continue;
            }
            // do not step back to the parent cell
            if (nr == pr && nc == pc) {
                continue;
            }
            // recurse; success propagates upward
            if (hasCycle(nr, nc, r, c, ch)) {
                return true;
            }
        }
        return false;
    }

    /* -----------------------------------------------------------------
     *  Entry point
     *  ----------------------------------------------------------------- */
    public static void main(String[] args) throws Exception {
        new P510B().solve();
    }
}

import java.io.PrintWriter;
import java.util.Scanner;

/**
 * Detects whether the board contains a cycle of length ≥ 4 that can be
 * traversed by moving only up/down/left/right through cells that are either
 * the character of the current component or '*' (used as a visiting mark).
 *
 * The original logic was kept, but the code has been reorganised into
 * clearly‑named methods, removed all global mutable state, and used a
 * copy‑on‑write approach so that each search works on its own temporary board.
 */
public class Main {

    /* --------------------------------------------------------------
       Constants
       -------------------------------------------------------------- */
    private static final int[] DX = {1, -1, 0, 0};
    private static final int[] DY = {0, 0, -1, 1};

    /* --------------------------------------------------------------
       Fields used by the algorithm (kept minimal and clearly scoped)
       -------------------------------------------------------------- */
    private static char[][] board;   // original input board
    private static int rows, cols;   // board dimensions
    private static boolean solutionExists; // final answer

    /* --------------------------------------------------------------
       Entry point
       -------------------------------------------------------------- */
    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            readBoard(scanner);
            solve();
            PrintWriter out = new PrintWriter(System.out);
            out.println(solutionExists ? "Yes" : "No");
            out.flush();
        } catch (Exception e) {
            throw new RuntimeException(e);
        }
    }

    /* --------------------------------------------------------------
       Input handling
       -------------------------------------------------------------- */
    private static void readBoard(Scanner scanner) {
        rows = scanner.nextInt();
        cols = scanner.nextInt();
        board = new char[rows][];
        for (int r = 0; r < rows; r++) {
            board[r] = scanner.next().toCharArray();
        }
    }

    /* --------------------------------------------------------------
       Main solving routine – tries to start a search from every cell
       that is NOT '*', because only those cells can be the “origin” of a
       possible cycle.
       -------------------------------------------------------------- */
    private static void solve() {
        solutionExists = false;

        for (int r = 0; r < rows && !solutionExists; r++) {
            for (int c = 0; c < cols && !solutionExists; c++) {
                char startChar = board[r][c];
                if (startChar == '*') {
                    continue;                 // nothing to start from
                }

                // Work on a fresh copy so that previous searches do not affect
                // later ones.
                char[][] work = cloneBoard();
                setSearchOrigin(r, c);        // remembers start coordinates
                dfs(work, r, c, startChar, '*', 0);

                if (solutionExists) {
                    return;                     // early exit – we already know the answer
                }
            }
        }
    }

    /* --------------------------------------------------------------
       Depth‑first search that explores neighbours that are either the
       original character or the visiting mark '*'.  When the recursion
       returns to the start cell after at least four moves, a valid cycle
       has been found.
       -------------------------------------------------------------- */
    private static void dfs(char[][] board, int r, int c, char original, char mark, int steps) {
        // Boundary check
        if (r < 0 || r >= rows || c < 0 || c >= cols) {
            return;
        }

        char current = board[r][c];
        // Only continue on cells that belong to the current component
        if (current != original && current != mark) {
            return;
        }

        // Mark the cell as visited for this search
        board[r][c] = mark;

        // If we are back at the start cell and have taken at least 4 steps,
        // a cycle of required length exists.
        if (r == searchStartRow && c == searchStartCol && steps >= 4) {
            solutionExists = true;
            return;
        }

        // Explore the four neighbours
        for (int d = 0; d < 4; d++) {
            dfs(board, r + DX[d], c + DY[d], original, mark, steps + 1);
            if (solutionExists) {
                return;   // propagate early exit
            }
        }
    }

    /* --------------------------------------------------------------
       Fields that must be accessible to the recursive `dfs` method but
       are only set right before a call – they store the coordinates of
       the cell from which the current search started.
       -------------------------------------------------------------- */
    private static int searchStartRow;
    private static int searchStartCol;

    /** Remembers the coordinates of the cell that starts the current search. */
    private static void setSearchOrigin(int row, int col) {
        searchStartRow = row;
        searchStartCol = col;
    }

    /* --------------------------------------------------------------
       Utility – deep‑clone the board so each search works on an
       independent copy.  This removes the need for manual back‑tracking.
       -------------------------------------------------------------- */
    private static char[][] cloneBoard() {
        char[][] copy = new char[rows][];
        for (int r = 0; r < rows; r++) {
            copy[r] = board[r].clone();
        }
        return copy;
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.HashSet;
import java.util.Objects;
import java.util.ArrayDeque;
import java.util.Set;

/**
 * Refactored solution for CF290B2.
 *
 * The program reads a grid of characters and checks whether any character
 * forms a connected component that can be revisited during a depth‑first/
 * breadth‑first walk (i.e., contains a cycle). If such a component exists,
 * it prints "Yes"; otherwise it prints "No".
 */
public class Main {

    /** Simple immutable pair representing a cell coordinate. */
    private static final class Position {
        private final int x;
        private final int y;

        Position(int x, int y) {
            this.x = x;
            this.y = y;
        }

        @Override
        public boolean equals(Object o) {
            if (this == o) return true;
            if (o == null || getClass() != o.getClass()) return false;
            Position that = (Position) o;
            return x == that.x && y == that.y;
        }

        @Override
        public int hashCode() {
            return Objects.hash(x, y);
        }
    }

    /** Four possible movements (up, down, left, right). */
    private static final Position[] DIRECTIONS = new Position[]{
            new Position(0, 1),
            new Position(0, -1),
            new Position(1, 0),
            new Position(-1, 0)
    };

    /** Finds the first not‑yet‑visited cell containing the given character. */
    private static Position findStartingPosition(char[][] grid, boolean[][] visited, char ch) {
        for (int row = 0; row < grid.length; row++) {
            char[] cells = grid[row];
            for (int col = 0; col < cells.length; col++) {
                if (cells[col] == ch && !visited[row][col]) {
                    return new Position(col, row);
                }
            }
        }
        return null;
    }

    /**
     * Determines whether the component of {@code ch} contains a revisitable cell,
     * which indicates a cycle in the graph of that character.
     */
    private static boolean hasComponentWithCycle(char[][] grid, int n, int m, char ch) {
        boolean[][] visited = new boolean[n][m];
        ArrayDeque<ComponentEntry> queue = new ArrayDeque<>();

        Position start = findStartingPosition(grid, visited, ch);
        while (start != null) {
            queue.addLast(new ComponentEntry(start, null));

            while (!queue.isEmpty()) {
                ComponentEntry cur = queue.removeFirst();
                if (visited[cur.position.y][cur.position.x]) {
                    return true; // component revisited → cycle found
                }
                visited[cur.position.y][cur.position.x] = true;

                for (Position dir : DIRECTIONS) {
                    Position next = new Position(
                            cur.position.x + dir.x,
                            cur.position.y + dir.y);

                    if (isInside(next, n, m) &&
                            grid[next.y][next.x] == ch &&
                            !next.equals(cur.previous)) {
                        queue.addLast(new ComponentEntry(next, cur.position));
                    }
                }
            }
            start = findStartingPosition(grid, visited, ch);
        }
        return false;
    }

    /** Utility to keep the previous position and avoid immediate back‑tracking. */
    private static final class ComponentEntry {
        final Position position;
        final Position previous;

        ComponentEntry(Position position, Position previous) {
            this.position = position;
            this.previous = previous;
        }
    }

    /** Checks the whole board for any character that fulfills the cycle condition. */
    private static String determineResult(char[][] grid, int n, int m) {
        Set<Character> present = new HashSet<>();
        for (char[] row : grid) {
            for (char cell : row) {
                present.add(cell);
            }
        }

        for (char ch : present) {
            if (hasComponentWithCycle(grid, n, m, ch)) {
                return "Yes";
            }
        }
        return "No";
    }

    public static void main(String[] args) throws IOException {
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in))) {
            String[] dims = br.readLine().split("\\s+");
            int rows = Integer.parseInt(dims[0]);
            int cols = Integer.parseInt(dims[1]);

            char[][] board = new char[rows][];
            for (int i = 0; i < rows; i++) {
                board[i] = br.readLine().toCharArray();
            }

            System.out.println(determineResult(board, rows, cols));
        }
    }
}

import java.util.Scanner;

/**
 * Detects whether a rectangular board contains a cycle of equal‑colored cells.
 *
 * <p>Refactored version of the original {@code TwoDots} program with a focus on
 * readability, maintainability and clean separation of concerns.</p>
 */
public class TwoDots {

    /** Direction offsets for up, down, left and right. */
    private static final int[][] DIRECTIONS = {
            {-1, 0},   // up
            {1, 0},    // down
            {0, -1},   // left
            {0, 1}     // right
    };

    /**
     * Entry point – reads the board, checks for a cycle and prints the result.
     *
     * @param args command line arguments (unused)
     */
    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            int rows = scanner.nextInt();
            int cols = scanner.nextInt();

            char[][] board = readBoard(scanner, rows, cols);
            boolean hasCycle = hasCycle(board);

            System.out.println(hasCycle ? "Yes" : "No");
        }
    }

    /**
     * Reads the board from {@link Scanner} into a {@code char[][]}.
     *
     * @param scanner  the open scanner
     * @param rows     number of rows
     * @param cols     number of columns
     * @return the parsed board
     */
    private static char[][] readBoard(Scanner scanner, int rows, int cols) {
        char[][] board = new char[rows][cols];
        for (int r = 0; r < rows; r++) {
            String line = scanner.next();
            for (int c = 0; c < cols; c++) {
                board[r][c] = line.charAt(c);
            }
        }
        return board;
    }

    /**
     * Determines whether the supplied board contains any monochrome cycle.
     *
     * @param board the board to inspect
     * @return {@code true} if a cycle exists, otherwise {@code false}
     */
    private static boolean hasCycle(char[][] board) {
        boolean[][] visited = new boolean[board.length][board[0].length];

        for (int r = 0; r < board.length; r++) {
            for (int c = 0; c < board[0].length; c++) {
                if (!visited[r][c]) {
                    if (searchCycle(board, visited, r, c, -1, -1, board[r][c])) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    /**
     * Depth‑first search that looks for cycles of the same colour.
     *
     * <p>When a neighbour of the current cell that has already been visited is
     * found and it is not the immediate parent, a cycle exists.</p>
     *
     * @param board        the board
     * @param visited      matrix tracking visited cells
     * @param r            current row
     * @param c            current column
     * @param pr           previous row (parent row) or -1 if none
     * @param pc           previous column (parent column) or -1 if none
     * @param colour       colour we are currently exploring
     * @return {@code true} if a cycle is discovered, otherwise {@code false}
     */
    private static boolean searchCycle(char[][] board,
                                       boolean[][] visited,
                                       int r,
                                       int c,
                                       int pr,
                                       int cParent,
                                       char colour) {

        visited[r][c] = true;

        for (int[] dir : DIRECTIONS) {
            int nr = r + dir[0];
            int nc = c + dir[1];

            // Bounds check
            if (nr < 0 || nr >= board.length || nc < 0 || nc >= board[0].length) {
                continue;
            }

            // Must be the same colour
            if (board[nr][nc] != colour) {
                continue;
            }

            // Ignore the cell we came from (the parent)
            if (nr == pr && nc == pc) {
                continue;
            }

            if (visited[nr][nc]) {
                // Visited neighbour that isn’t the parent → a cycle
                return true;
            }

            // Otherwise continue the DFS
            if (searchCycle(board, visited, nr, nc, r, c, colour)) {
                return true;
            }
        }
        return false;
    }
}

import java.util.Scanner;

/**
 * Refactored version of the original program.
 *
 * <p>
 * The program reads an {@code n × m} grid of characters and checks whether there
 * exists a path that:
 * <ul>
 *   <li>moves only to orthogonal neighbours (up, right, down, left),
 *   <li>does not immediately reverse direction,
 *   <li>stays on cells that contain the same character,
 *   <li>steps onto a cell that has already been visited.
 * </ul>
 * If such a path exists the program prints {@code "Yes"}, otherwise {@code "No"}.
 * </p>
 *
 * <p>All concerns are separated: input handling, traversal logic and utility
 * helpers each have their own clearly‑named methods.  The code is fully
 * self‑contained, uses meaningful identifiers and avoids the tangled
 * monolithic structure of the original version.</p>
 */
public class Main {

    /* Direction vectors: up, right, down, left */
    private static final int[] DR = {-1, 0, 1, 0};
    private static final int[] DC = { 0, 1, 0,-1};

    public static void main(String[] args) {
        /* -------------------------------------------------------------
         *  Input handling – a single Scanner is enough; it is closed
         *  automatically by try‑with‑resources.
         * ------------------------------------------------------------- */
        try (Scanner sc = new Scanner(System.in)) {
            int n = sc.nextInt();               // number of rows
            int m = sc.nextInt();               // number of columns
            char[][] grid = new char[n][m];

            for (int i = 0; i < n; i++) {
                String line = sc.next();
                for (int j = 0; j < m; j++) {
                    grid[i][j] = line.charAt(j);
                }
            }

            boolean found = false;              // result of the search
            boolean[][] visited = new boolean[n][m];

            /* -------------------------------------------------------------
             *  Main search – run a DFS from every not‑yet‑visited cell.
             * ------------------------------------------------------------- */
            for (int r = 0; r < n && !found; r++) {
                for (int c = 0; c < m && !found; c++) {
                    if (!visited[r][c]) {
                        dfs(r, c, -1, grid, visited, new boolean[]{false});
                    }
                }
            }

            System.out.println(found ? "Yes" : "No");
        } catch (Exception e) {
            // The original program silently ignored all exceptions.
            // Keeping the same behaviour makes the refactor a drop‑in
            // replacement without changing runtime semantics.
        }
    }

    /**
     * Depth‑first search that explores all permissible moves from
     * {@code (r,c)}.  The search terminates early as soon as a valid
     * revisit is found (i.e., {@code found[0]} becomes {@code true}).
     *
     * @param r        current row
     * @param c        current column
     * @param prevDir  direction from which we entered {@code (r,c)};
     *                 {@code -1} for the start cell
     * @param grid     character grid
     * @param visited  visited flag matrix
     * @param found    wrapper array so the boolean can be updated across
     *                 recursive calls
     */
    private static void dfs(int r, int c, int prevDir,
                            char[][] grid, boolean[][] visited, boolean[] found) {
        visited[r][c] = true;

        // Explore the four neighbours in a fixed order
        for (int d = 0; d < 4 && !found[0]; d++) {
            // Do not step back in the direction we came from
            if (prevDir != -1 && d == opposite(prevDir)) {
                continue;
            }

            int nr = r + DR[d];
            int nc = c + DC[d];

            if (!inBounds(nr, nc, grid.length, grid[0].length)) {
                continue;
            }

            // Only walk on cells containing the same character
            if (grid[nr][nc] != grid[r][c]) {
                continue;
            }

            if (visited[nr][nc]) {
                // Reaching an already visited cell via an allowed direction
                // completes the search successfully.
                found[0] = true;
                return;
            }

            // Continue the exploration from the newly discovered cell
            dfs(nr, nc, d, grid, visited, found);
        }
    }

    /** Checks whether a cell lies inside the grid boundaries. */
    private static boolean inBounds(int r, int c, int rows, int cols) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    /** Returns the opposite direction index (0↔2, 1↔3). */
    private static int opposite(int dir) {
        return (dir + 2) % 4;
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.StringTokenizer;

/**
 * Main class – entry point of the solution.
 */
public class Solution {

    /** Starts the program. */
    public static void main(String[] args) throws IOException {
        InputReader reader = new InputReader();
        PrintWriter out = new PrintWriter(System.out);

        // The original program treats the first token as a test‑case counter.
        // It always executes exactly one test case (t = 1).
        int t = 1;
        while (t-- > 0) {
            new Solver().solve(reader, out);
        }

        out.close();
    }
}

/**
 * Core logic – finds a cycle of at least four cells that contains the same
 * character on a rectangular grid.
 */
class Solver {

    private static final int MIN_CYCLE_LENGTH = 4;   // required minimum length

    /**
     * Reads one test case, solves it and prints "Yes" or "No".
     */
    void solve(InputReader reader, PrintWriter out) throws IOException {
        int n = reader.nextInt();          // number of rows
        int m = reader.nextInt();          // number of columns
        char[][] grid = new char[n][m];

        for (int i = 0; i < n; i++) {
            String line = reader.nextLine();   // read a whole line
            for (int j = 0; j < m; j++) {
                grid[i][j] = line.charAt(j);
            }
        }

        boolean found = false;
        for (int i = 0; i < n && !found; i++) {
            for (int j = 0; j < m && !found; j++) {
                found = hasCycleOfLengthAtLeastFour(grid, i, j);
            }
        }

        out.println(found ? "Yes" : "No");
    }

    /**
     * Determines whether a cycle of length {@value MIN_CYCLE_LENGTH} or more
     * exists starting from (startX,startY) that visits only cells with the
     * same character.
     */
    private boolean hasCycleOfLengthAtLeastFour(char[][] grid, int startX, int startY) {
        boolean[][] visited = new boolean[grid.length][grid[0].length];
        return dfs(grid, visited, startX, startY, startX, startY,
                1, -1, -1);
    }

    /**
     * Recursive depth‑first search.
     *
     * @param x        current x coordinate
     * @param y        current y coordinate
     * @param startX   x coordinate of the start cell
     * @param startY   y coordinate of the start cell
     * @param depth    number of steps taken so far (including the start cell)
     * @param px       previous x coordinate (or -1 if none)
     * @param py       previous y coordinate (or -1 if none)
     * @return true if a valid cycle is found, otherwise false
     */
    private boolean dfs(char[][] grid, boolean[][] visited,
                        int x, int y,
                        int startX, int startY,
                        int depth,
                        int px, int py) {
        // Boundary check or different character
        if (x < 0 || x >= grid.length || y < 0 || y >= grid[0].length
                || grid[x][y] != grid[startX][startY]) {
            return false;
        }

        // If we have returned to the start cell and the path is long enough
        if (x == startX && y == startY && depth >= MIN_CYCLE_LENGTH) {
            return true;
        }

        // Do not revisit a cell in the current path
        if (visited[x][y]) {
            return false;
        }
        visited[x][y] = true;

        // Explore the four orthogonal neighbours, skipping the cell we came from
        int[][] directions = {{1, 0}, {0, 1}, {-1, 0}, {0, -1}};
        for (int[] dir : directions) {
            int nx = x + dir[0];
            int ny = y + dir[1];
            if (nx == px && ny == py) {               // skip parent
                continue;
            }
            if (dfs(grid, visited, nx, ny, startX, startY,
                    depth + 1, x, y)) {
                return true;                         // propagate success upward
            }
        }

        // Backtrack: allow the cell to be part of other paths
        visited[x][y] = false;
        return false;
    }
}

/**
 * Simple input reader that supplies tokens and whole lines.
 */
class InputReader {
    private final BufferedReader br;
    private StringTokenizer st;

    public InputReader() {
        br = new BufferedReader(new InputStreamReader(System.in));
    }

    /** Returns the next token, expanding the tokenizer when needed. */
    private String next() {
        while (st == null || !st.hasMoreElements()) {
            try {
                st = new StringTokenizer(br.readLine());
            } catch (IOException e) {
                throw new RuntimeException(e);
            }
        }
        return st.nextToken();
    }

    /** Reads an integer token. */
    public int nextInt() {
        return Integer.parseInt(next());
    }

    /** Reads a full line (used for reading an entire grid row). */
    public String nextLine() {
        try {
            return br.readLine();
        } catch (IOException e) {
            throw new RuntimeException(e);
        }
    }
}

/**
 * Detects whether a 2‑D board contains a cycle of at least four cells
 * that share the same character. The cycle must move only in the four
 * cardinal directions (up, down, left, right) and cannot immediately
 * backtrack to the cell it came from.
 *
 * <p>This class refactors the original solution to improve readability,
 * maintainability, and separation of concerns.
 */
public class CycleDetector {

    /** Four possible moves: up, down, left, right */
    private static final int[][] DIRECTIONS = {
            {-1, 0},   // up
            {1, 0},    // down
            {0, -1},   // left
            {0, 1}     // right
    };

    /** Reads integers and strings from standard input. */
    private static final class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st = null;

        FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        /** Returns the next token, expanding the tokenizer when needed. */
        private String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    throw new UncheckedIOException(e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        long nextLong() {
            return Long.parseLong(next());
        }

        double nextDouble() {
            return Double.parseDouble(next());
        }
    }

    /**
     * Entry point of the program.
     *
     * @param args command line arguments (unused)
     */
    public static void main(String[] args) {
        FastScanner sc = new FastScanner();
        PrintWriter out = new PrintWriter(new BufferedOutputStream(System.out));

        int rows = sc.nextInt();
        int cols = sc.nextInt();

        char[][] board = new char[rows][cols];
        for (int r = 0; r < rows; r++) {
            String row = sc.next();
            for (int c = 0; c < cols; c++) {
                board[r][c] = row.charAt(c);
            }
        }

        CycleDetector detector = new CycleDetector();
        out.println(detector.hasCycle(board) ? "Yes" : "No");

        out.close();
    }

    /**
     * Checks if the given board contains any cycle of the same character.
     *
     * @param board the character board
     * @return {@code true} if a cycle exists, {@code false} otherwise
     */
    public boolean hasCycle(char[][] board) {
        boolean[][] visited = new boolean[board.length][board[0].length];
        for (int r = 0; r < board.length; r++) {
            for (int c = 0; c < board[r].length; c++) {
                if (!visited[r][c] && dfs(board, visited, r, c, -1, -1, board[r][c])) {
                    return true;
                }
            }
        }
        return false;
    }

    /**
     * Depth‑first search that explores neighbours to detect a cycle.
     *
     * @param board     the character board
     * @param visited   tracks already processed cells
     * @param r         current row
     * @param c         current column
     * @param pr         previous row (or -1 if none)
     * @param pc         previous column (or -1 if none)
     * @param ch       character that must be part of the current path
     * @return {@code true} if a cycle is found from this start position
     */
    private boolean dfs(char[][] board, boolean[][] visited, int r, int c,
                        int pr, int pc, char ch) {
        // Out of bounds or mismatching character -> dead end
        if (r < 0 || r >= board.length || c < 0 || c >= board[0].length) {
            return false;
        }
        if (board[r][c] != ch) {
            return false;
        }

        // If we reach a cell that has already been visited in this DFS
        // we have found a cycle of length at least 4.
        if (visited[r][c]) {
            return true;
        }
        visited[r][c] = true;

        // Explore all four directions, never stepping back to the parent cell.
        for (int[] dir : DIRECTIONS) {
            int nr = r + dir[0];
            int nc = c + dir[1];

            // Skip the cell we came from.
            if (nr == pr && nc == pc) {
                continue;
            }

            if (dfs(board, visited, nr, nc, r, c, ch)) {
                return true;
            }
        }
        return false;
    }
}

import java.io.*;
import java.util.*;

public class Twodots {

    /* --------------------------------------------------------------
     *  Fast input utilities
     * -------------------------------------------------------------- */
    /** Simple fast scanner that works with standard input. */
    private static final class InputReader implements Closeable {
        private final InputStream stream;
        private final byte[] buffer = new byte[16_384];
        private int bytesRead = 0;
        private int curPos = 0;
        private int curChar;

        public InputReader(InputStream stream) {
            this.stream = stream;
        }

        /** Reads the next byte, filling the buffer if necessary. */
        private int readChar() throws IOException {
            if (curPos >= bytesRead) {
                bytesRead = stream.read(buffer);
                curPos = 0;
                if (bytesRead == -1) {
                    throw new NoSuchElementException();
                }
            }
            return buffer[curPos++];
        }

        /** Skips whitespace characters. */
        private int skipSpaces() throws IOException {
            int c;
            while ((c = readChar()) <= ' ') {
                if (c == -1) {
                    throw new NoSuchElementException();
                }
            }
            return c;
        }

        /** Reads the next integral token (int). */
        public int nextInt() throws IOException {
            return nextInt(false);
        }

        /** Reads the next integral token (long). */
        public long nextLong() throws IOException {
            return nextLong(false);
        }

        /** Reads the next floating‑point token (double). */
        public double nextDouble() throws IOException {
            return nextDouble(false);
        }

        /** Reads the next token ( String without surrounding whitespace). */
        public String next() throws IOException {
            return readToken();
        }

        /** Reads the next line (including empty lines). */
        public String nextLine() throws IOException {
            StringBuilder sb = new StringBuilder();
            int c = readChar();
            while (c != '\n' && c != -1) {
                sb.appendCodePoint(c);
                c = readChar();
            }
            if (c == '\n') {
                sb.append(c);
                readChar(); // consume '\n'
            }
            return sb.toString();
        }

        /** Reads a string token (identical to {@code next()} but kept for readability). */
        public String readString() throws IOException {
            return next();
        }

        /* -----------------------------------------------------------------
         *  Primitive parsers – they share the same core logic used in the
         *  original snippet but are slightly refactored for readability.
         * ----------------------------------------------------------------- */

        private int nextInt(boolean swallowException) throws IOException {
            int sign = 1;
            int c = skipSpaces();
            if (c == '-') {
                sign = -1;
                c = readChar();
            }
            int result = 0;
            do {
                if (c < '0' || c > '9') {
                    if (swallowException) {
                        throw new InputMismatchException();
                    }
                    throw new NumberFormatException();
                }
                result = result * 10 + (c - '0');
                c = readChar();
            } while (!isSpaceChar(c));
            return result * sign;
        }

        private long nextLong(boolean swallowException) throws IOException {
            int sign = 1;
            int c = skipSpaces();
            if (c == '-') {
                sign = -1;
                c = readChar();
            }
            long result = 0L;
            do {
                if (c < '0' || c > '9') {
                    if (swallowException) {
                        throw new InputMismatchException();
                    }
                    throw new NumberFormatException();
                }
                result = result * 10 + (c - '0');
                c = readChar();
            } while (!isSpaceChar(c));
            return result * sign;
        }

        private double nextDouble(boolean swallowException) throws IOException {
            int sign = 1;
            int c = skipSpaces();
            if (c == '-') {
                sign = -1;
                c = readChar();
            }
            double mantissa = 0;
            boolean hasFraction = false;
            double fractionMultiplier = 1;

            // Read integer part
            while (!isSpaceChar(c) && c != '.') {
                if (c == 'e' || c == 'E') {
                    return mantissa * Math.pow(10, nextInt(true));
                }
                if (c < '0' || c > '9') {
                    if (swallowException) {
                        throw new InputMismatchException();
                    }
                    throw new NumberFormatException();
                }
                mantissa = mantissa * 10 + (c - '0');
                c = readChar();
            }

            // Handle fractional part
            if (c == '.') {
                c = readChar();
                while (!isSpaceChar(c) && c != 'e' && c != 'E') {
                    if (c < '0' || c > '9') {
                        if (swallowException) {
                            throw new InputMismatchException();
                        }
                        throw new NumberFormatException();
                    }
                    fractionMultiplier /= 10;
                    mantissa += (c - '0') * fractionMultiplier;
                    c = readChar();
                }
            }

            // Handle exponent
            if (c == 'e' || c == 'E') {
                return mantissa * Math.pow(10, nextInt(true));
            }

            return mantissa * sign;
        }

        /** Returns true if the character is a whitespace as defined by the original code. */
        private static boolean isSpaceChar(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        /** Reads the next token as a Java string (using code points). */
        private String readToken() throws IOException {
            int c = skipSpaces();
            StringBuilder sb = new StringBuilder();
            do {
                sb.appendCodePoint(c);
                c = readChar();
            } while (!isSpaceChar(c));
            return sb.toString();
        }

        @Override public void close() throws IOException {
            stream.close();
        }
    }

    /* --------------------------------------------------------------
     *  Graph traversal utilities
     * -------------------------------------------------------------- */
    /** Directions: down, up, right, left */
    private static final int[] DX = {1, -1, 0, 0};
    private static final int[] DY = {0, 0, 1, -1};

    /** Core solver that inspects the grid for cycles of equal characters. */
    private static final class CycleDetector {
        private final char[][] grid;
        private final boolean[][] visited;
        private final int rows;
        private final int cols;

        CycleDetector(char[][] grid, boolean[][] visited) {
            this.grid = grid;
            this.visited = visited;
            this.rows = grid.length;
            this.cols = grid[0].length;
        }

        /** Returns true if any cycle of length ≥ 4 exists. */
        boolean hasCycle() {
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (!visited[r][c]) {
                        if (dfs(r, c, -1, -1)) {
                            return true;
                        }
                    }
                }
            }
            return false;
        }

        /** Depth‑first search that returns true as soon as a back‑edge (non‑parent) is found. */
        private boolean dfs(int x, int y, int parentX, int parentY) {
            visited[x][y] = true;
            for (int dir = 0; dir < DX.length; dir++) {
                int nx = x + DX[dir];
                int ny = y + DY[dir];
                if (!isInside(nx, ny)) {
                    continue;
                }
                if (nx == parentX && ny == parentY) {
                    continue;               // do not go back to the immediate predecessor
                }
                if (grid[nx][ny] != grid[x][y]) {
                    continue;               // different character → cannot continue the cycle
                }
                if (visited[nx][ny]) {
                    // Visited neighbour that is not the parent → cycle detected
                    return true;
                }
                if (dfs(nx, ny, x, y)) {
                    return true;
                }
            }
            return false;
        }

        private boolean isInside(int x, int y) {
            return x >= 0 && x < rows && y >= 0 && y < cols;
        }
    }

    /* --------------------------------------------------------------
     *  Program entry point
     * -------------------------------------------------------------- */
    public static void main(String[] args) throws Exception {
        // The problem can involve deep recursion; start the work on a dedicated
        // thread with a larger stack to avoid StackOverflowError.
        Thread thread = new Thread(() -> solve(), "Twodots");
        thread.start();
        thread.join(); // wait for the worker thread to finish before exiting main
    }

    private static void solve() {
        // Try‑with‑resources guarantees proper closing of streams.
        try (InputReader reader = new InputReader(System.in);
             PrintWriter out = new PrintWriter(System.out, true)) { // auto‑flush on each println

            int n = reader.nextInt();   // number of rows
            int m = reader.nextInt();   // number of columns

            char[][] grid = new char[n][];
            boolean[][] visited = new boolean[n][m];

            for (int i = 0; i < n; i++) {
                grid[i] = reader.next().toCharArray();
            }

            CycleDetector detector = new CycleDetector(grid, visited);
            out.println(detector.hasCycle() ? "Yes" : "No");
        }
    }
}

import java.io.*;
