public class School {

    /** Four possible moves: down, up, right, left */
    private static final int[][] DIRECTIONS = {
            {1, 0}, {-1, 0}, {0, 1}, {0, -1}
    };

    public static void main(String[] args) {
        try (InputReader reader = new InputReader(System.in);
             PrintWriter out = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)))) {

            int rows = reader.nextInt();
            int cols = reader.nextInt();

            char[][] grid = new char[rows][];
            for (int r = 0; r < rows; r++) {
                grid[r] = reader.next().toCharArray();
            }

            boolean hasCycle = false;
            boolean[][] visited = new boolean[rows][cols];

            for (int r = 0; r < rows && !hasCycle; r++) {
                for (int c = 0; c < cols && !hasCycle; c++) {
                    if (!visited[r][c] && dfs(grid, visited, r, c, -1, -1, grid[r][c])) {
                        hasCycle = true;
                    }
                }
            }

            out.println(hasCycle ? "Yes" : "No");
        }
    }

    /**
     * Depth‑first search that looks for a cycle of the same character.
     *
     * @param grid       the board
     * @param visited    marks cells already processed
     * @param r          current row
     * @param c          current column
     * @param pr         parent row (or -1 if none)
     * @param pc         parent column (or -1 if none)
     * @param ch         character we are matching
     * @return true if a valid cycle is found from this start cell
     */
    private static boolean dfs(char[][] grid, boolean[][] visited,
                               int r, int c, int pr, int pc, char ch) {
        visited[r][c] = true;

        for (int[] dir : DIRECTIONS) {
            int nr = r + dir[0];
            int nc = c + dir[1];

            if (!isInBounds(grid, nr, nc)) {
                continue;
            }
            if (grid[nr][nc] != ch) {
                continue;
            }

            if (!visited[nr][nc]) {
                if (dfs(grid, visited, nr, nc, r, c, ch)) {
                    return true;
                }
            } else if (nr != pr || nc != pc) {
                /* 
                 * A visited neighbour that is not the immediate parent indicates a cycle.
                 * Because the grid moves are only horizontal/vertical, any such back‑edge
                 * necessarily creates a cycle of length at least 4.
                 */
                return true;
            }
        }
        return false;
    }

    /** Utility to check whether a cell is inside the grid. */
    private static boolean isInBounds(char[][] grid, int r, int c) {
        return r >= 0 && r < grid.length && c >= 0 && c < grid[0].length;
    }

    /** Fast scanner used for competitive‑programming style input. */
    public static class InputReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public InputReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
        }

        /** Returns the next token from stdin. */
        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        /** Reads an int from stdin. */
        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.util.Scanner;

/**
 * Detects whether a grid contains a cycle of at least four cells of the same colour.
 * The algorithm uses depth‑first search and avoids counting the immediate parent
 * as a cycle, which guarantees detection only for genuine cycles of length ≥4.
 */
public class Main {

    /** Directions: up, down, left, right */
    private static final int[][] DIRECTIONS = {
            {-1, 0},   // up
            {1, 0},    // down
            {0, -1},   // left
            {0, 1}     // right
    };

    /** Entry point */
    public static void main(String[] args) {
        // Use try‑with‑resources to guarantee the Scanner is closed
        try (Scanner scanner = new Scanner(System.in)) {
            int rows = scanner.nextInt();
            int cols = scanner.nextInt();
            scanner.nextLine(); // consume the newline after the dimensions

            char[][] board = readBoard(scanner, rows, cols);
            boolean hasCycle = CycleDetector.hasCycle(board);
            System.out.println(hasCycle ? "Yes" : "No");
        }
    }

    /**
     * Reads the board from standard input.
     *
     * @param scanner a Scanner positioned after the dimensions line
     * @param rows    number of rows
     * @param cols    number of columns
     * @return the character grid
     */
    private static char[][] readBoard(Scanner scanner, int rows, int cols) {
        char[][] board = new char[rows][cols];
        for (int i = 0; i < rows; i++) {
            String line = scanner.nextLine();
            System.arraycopy(line.toCharArray(), 0, board[i], 0, cols);
        }
        return board;
    }
}

/**
 * Helper class that encapsulates the cycle detection logic.
 */
class CycleDetector {

    /**
     * Determines whether the supplied grid contains a cycle of equal‑coloured cells.
     *
     * @param grid the character board
     * @return {@code true} if a cycle exists, {@code false} otherwise
     */
    public static boolean hasCycle(char[][] grid) {
        boolean[][] visited = new boolean[grid.length][grid[0].length];

        for (int r = 0; r < grid.length; r++) {
            for (int c = 0; c < grid[0].length; c++) {
                if (!visited[r][c]) {
                    if (dfs(grid, visited, r, c, -1, -1, grid[r][c])) {
                        return true; // a cycle has been found
                    }
                }
            }
        }
        return false; // no cycles detected
    }

    /**
     * Depth‑first search that explores all neighbours of the current cell.
     *
     * @param grid      the character board
     * @param visited   matrix that tracks visited cells
     * @param r         current row
     * @param c         current column
     * @param pr        previous row (or -1 if none)
     * @param pc        previous column (or -1 if none)
     * @param colour    colour of the component we are analysing
     * @return {@code true} if a cycle is found in this branch, {@code false} otherwise
     */
    private static boolean dfs(char[][] grid, boolean[][] visited, int r, int c,
                               int pr, int pc, char colour) {
        visited[r][c] = true;

        for (int[] dir : DIRECTIONS) {
            int nr = r + dir[0];
            int nc = c + dir[1];

            // Boundary check
            if (nr < 0 || nr >= grid.length || nc < 0 || nc >= grid[0].length) {
                continue;
            }

            // Skip cells of different colour
            if (grid[nr][nc] != colour) {
                continue;
            }

            if (!visited[nr][nc]) {
                // Continue the search
                if (dfs(grid, visited, nr, nc, r, c, colour)) {
                    return true;
                }
            } else if (nr != pr || nc != pc) {
                // Visited neighbour that is not the immediate parent → cycle detected
                return true;
            }
        }
        return false;
    }
}

/**
 * Detects whether a grid contains a cycle of length ≥ 3 formed by equal adjacent characters.
 *
 * <p>Refactored version of the original program – the logic is unchanged, but the code has been
 * reorganized for readability, testability and maintainability.</p>
 */
public class Main {

    /** Entry point. */
    public static void main(String[] args) {
        FastScanner fs = new FastScanner();
        PrintWriter out = new PrintWriter(System.out);

        int n = fs.nextInt();               // number of rows
        int m = fs.nextInt();               // number of columns
        char[][] grid = new char[n][m];
        for (int i = 0; i < n; i++) {
            grid[i] = fs.nextLine().toCharArray();
        }

        int[][] visited = new int[n][m];
        for (int[] row : visited) {
            Arrays.fill(row, -1);
        }

        boolean found = false;
        for (int i = 0; i < n && !found; i++) {
            for (int j = 0; j < m && !found; j++) {
                if (visited[i][j] == -1) {
                    found = dfs(grid, visited, i, j, 0);
                }
            }
        }

        out.println(found ? "Yes" : "No");
        out.flush();
    }

    /**
     * Depth‑first search that looks for a cycle of the same character.
     *
     * @param grid     the character grid
     * @param visited  matrix storing the discovery depth of each visited cell
     * @param i        current row
     * @param j        current column
     * @param dist     current distance from the start of the DFS tree
     * @return {@code true} if a qualifying cycle is discovered, otherwise {@code false}
     */
    private static boolean dfs(char[][] grid, int[][] visited, int i, int j, int dist) {
        visited[i][j] = dist;

        int[][] dirs = {{0, -1}, {0, 1}, {-1, 0}, {1, 0}};
        for (int[] d : dirs) {
            int ni = i + d[0];
            int nj = j + d[1];

            if (!inBounds(ni, grid) || !inBounds(nj, grid)) {
                continue;
            }
            if (grid[ni][nj] != grid[i][j]) {
                continue;
            }

            if (visited[ni][nj] == -1) {
                if (dfs(grid, visited, ni, nj, dist + 1)) {
                    return true;
                }
            } else if (dist - visited[ni][nj] >= 3) {
                // A back‑edge that closes a cycle of length ≥ 3
                System.out.println("Yes");
                System.exit(0);
            }
        }
        return false;
    }

    private static boolean inBounds(int idx, char[][] grid) {
        return 0 <= idx && idx < grid.length;
    }

    /* ---------------------------------------------------------------------------
       Helper class for fast input – unchanged logic, only renamed for clarity.
       --------------------------------------------------------------------------- */
    private static class FastScanner {
        private final byte[] buffer = new byte[1024];
        private int curChar;
        private int numChars;

        /** Reads the next byte, throwing {@link InputMismatchException} on EOF. */
        private int read() {
            if (numChars == -1) {
                throw new InputMismatchException();
            }
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = System.in.read(buffer);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (numChars <= 0) {
                    return -1;
                }
            }
            return buffer[curChar++];
        }

        /** Returns the next line of input. */
        private String nextLine() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }
            StringBuilder sb = new StringBuilder();
            do {
                sb.appendCodePoint(c);
                c = read();
            } while (!isEndOfLine(c));
            return sb.toString();
        }

        /** Returns the next token (non‑whitespace characters). */
        private String nextString() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }
            StringBuilder sb = new StringBuilder();
            do {
                sb.appendCodePoint(c);
                c = read();
            } while (!isSpaceChar(c));
            return sb.toString();
        }

        /** Returns the next integer from the input. */
        private int nextInt() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            int result = 0;
            do {
                if (c < '0' || c > '9') {
                    throw new InputMismatchException();
                }
                result = result * 10 + (c - '0');
                c = read();
            } while (!isSpaceChar(c));
            return result * sign;
        }

        /** Returns {@code true} if the character is a whitespace that separates tokens. */
        private boolean isSpaceChar(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        /** Returns {@code true} if the character marks the end of a line. */
        private boolean isEndOfLine(int c) {
            return c == '\n' || c == '\r' || c == -1;
        }
    }
}

import java.io.*;
import java.util.*;

public class Cf510B {

    /** Simple wrapper for fast input. */
    private static final class FastInput {
        private final InputStream stream;
        private final byte[] buffer = new byte[8192];
        private int pointer = 0, length = 0;
        private final SpaceCharFilter filter;

        FastInput(InputStream stream) {
            this.stream = stream;
        }

        private int read() throws IOException {
            if (pointer >= length) {
                length = stream.read(buffer);
                pointer = 0;
                if (length <= 0) return -1;
            }
            return buffer[pointer++];
        }

        private boolean isSpaceChar(int ch) {
            return ch == ' ' || ch == '\n' || ch == '\r' || ch == '\t' || ch == -1;
        }

        private void skipSpaces() throws IOException {
            int c;
            while ((c = read()) != -1 && isSpaceChar(c)) { }
            if (c != -1) pointer--; // step back to process current non‑space char
        }

        int nextInt() throws IOException {
            skipSpaces();
            int sign = 1;
            int c = read();
            if (c == '-') {
                sign = -1;
                c = read();
            }
            int value = 0;
            do {
                if (c < '0' || c > '9') throw new InputMismatchException();
                value = value * 10 + (c - '0');
                c = read();
            } while (!isSpaceChar(c));
            return value * sign;
        }

        String readString() throws IOException {
            skipSpaces();
            StringBuilder sb = new StringBuilder();
            int c;
            do {
                sb.append((char) read());
                c = read();
            } while (!isSpaceChar(c));
            return sb.toString();
        }
    }

    /** Core logic of the problem – detection of a cycle in a grid of letters. */
    private static final class Solver {
        private static final int[][] DIRECTIONS = {
                {1, 0}, {-1, 0}, {0, 1}, {0, -1}
        };

        private final char[][] grid;
        private final boolean[][] visited;
        private final int rows, cols;
        private boolean foundCycle = false;

        Solver(char[][] grid, boolean[][] visited) {
            this.grid = grid;
            this.visited = visited;
            this.rows = grid.length;
            this.cols = grid[0].length;
        }

        /** Entry point – scans the whole board looking for a cycle. */
        void solve() {
            for (int r = 0; r < rows && !foundCycle; r++) {
                for (int c = 0; c < cols && !foundCycle; c++) {
                    if (!visited[r][c]) {
                        dfs(r, c, -1, -1, grid[r][c]);
                    }
                }
            }
        }

        /** Depth‑first search that detect a cycle of the same colour. */
        private void dfs(int r, int c, int pr, int pc, char colour) {
            visited[r][c] = true;

            for (int[] dir : DIRECTIONS) {
                int nr = r + dir[0];
                int nc = c + dir[1];

                // bounds check
                if (!inside(nr, nc)) continue;
                // same colour ?
                if (grid[nr][nc] != colour) continue;
                // do not go back to the parent cell
                if (nr == pr && nc == pc) continue;

                if (visited[nr][nc]) {
                    // reaching an already visited cell means we have found a cycle
                    foundCycle = true;
                    return;
                }
                dfs(nr, nc, r, c, colour);
                if (foundCycle) return;
            }
        }

        private boolean inside(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }
    }

    public static void main(String[] args) throws Exception {
        FastInput in = new FastInput(System.in);
        PrintWriter out = new PrintWriter(System.out, true);

        int n = in.nextInt();
        int m = in.nextInt();

        // read the board – keep characters as‑is for easier colour comparison
        char[][] board = new char[n][];
        for (int i = 0; i < n; i++) {
            board[i] = in.readString().toCharArray();
        }

        boolean[][] visited = new boolean[n][m];
        Solver solver = new Solver(board, visited);
        solver.solve();

        out.println(solver.foundCycle ? "Yes" : "No");
        out.close();
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.Arrays;

/**
 * Detects cycles of equal characters in a 2‑D grid.
 * Uses iterative neighbour exploration and a simple state machine.
 */
public class Solution {

    /** State values for the visited matrix. */
    private static final int UNVISITED = 0;
    private static final int VISITING = 1;
    private static final int VISITED = 2;

    /** Offsets for the four possible moves: right, down, left, up. */
    private static final int[][] DIRECTIONS = {
            {0, 1},   // right
            {1, 0},   // down
            {0, -1},  // left
            {-1, 0}   // up
    };

    /** Fast scanner for reading input tokens. */
    private static class FastReader {
        private final BufferedReader br;
        private StringTokenizer st;

        FastReader() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        private void fillTokenizer() {
            try {
                st = new StringTokenizer(br.readLine());
            } catch (IOException e) {
                throw new UncheckedIOException(e);
            }
        }

        private String next() {
            while (st == null || !st.hasMoreElements()) {
                fillTokenizer();
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }
    }

    /** Simple wrapper around System.out.println for readability. */
    private static void print(Object o) {
        System.out.println(o);
    }

    public static void main(String[] args) {
        FastReader sc = new FastReader();

        int rows = sc.nextInt();
        int cols = sc.nextInt();

        char[][] grid = new char[rows][cols];
        int[][] state = new int[rows][cols]; // 0=unvisited, 1=visiting, 2=visited

        for (int r = 0; r < rows; r++) {
            Arrays.fill(state[r], UNVISITED);
            String line = sc.next();
            grid[r] = line.toCharArray();
        }

        boolean hasCycle = false;
        for (int r = 0; r < rows && !hasCycle; r++) {
            for (int c = 0; c < cols && !hasCycle; c++) {
                if (state[r][c] == UNVISITED) {
                    hasCycle = dfs(grid, state, r, c, -1, -1);
                }
            }
        }

        print(hasCycle ? "Yes" : "No");
    }

    /**
     * Depth‑first search that looks for a cycle of the same character.
     *
     * @return true if a cycle is found in the current component.
     */
    private static boolean dfs(char[][] grid, int[][] state, int r, int c, int pr, int pc) {
        state[r][c] = VISITING;

        for (int[] dir : DIRECTIONS) {
            int nr = r + dir[0];
            int nc = c + dir[1];

            // Boundary check and character match
            if (!isInBounds(nr, grid.length, nc, grid[0].length) || grid[nr][nc] != grid[r][c]) {
                continue;
            }

            // Skip the cell we just came from (parent)
            if (nr == pr && nc == pc) {
                continue;
            }

            if (state[nr][nc] == UNVISITED) {
                if (dfs(grid, state, nr, nc, r, c)) {
                    return true;
                }
            } else if (state[nr][nc] == VISITING) {
                // A visited node that is still in the recursion stack indicates a cycle.
                // Ensure it is not the immediate parent (already handled above).
                return true;
            }
        }

        state[r][c] = VISITED;
        return false;
    }

    /** Utility to check if a coordinate lies inside the given bounds. */
    private static boolean isInBounds(int pos, int max) {
        return pos >= 0 && pos < max;
    }

    /** Overload for 2‑D bounds checking. */
    private static boolean isInBounds(int r, int n, int c, int m) {
        return r >= 0 && c >= 0 && r < n && c < m;
    }
}

import java.io.*;
import java.util.*;

/**
 * Detects whether an undirected graph built from a grid contains any cycle.
 *
 * <p>
 *   The graph is constructed as follows:
 *   <ul>
 *     <li>Each cell of the grid becomes a vertex.</li>
 *     <li>Vertices are connected if they are orthogonal neighbours (up, down, left, right)
 *         and contain the same character.</li>
 *   </ul>
 *   <p>
 *   Cycle detection is performed with a standard Depth‑First Search that ignores the
 *   edge leading back to the caller (the “parent”). If an already‑visited vertex is
 *   reached that is not the parent, a cycle exists.
 * </p>
 *
 * <p>Entry point: {@code main(String[])} reads input from {@code stdin},
 * builds the graph and prints either {@code "Yes"} (a cycle exists) or {@code "No"}.
 * </p>
 */
public class GraphCycleDetector {

    /** Maximum number of vertices – one per grid cell plus one unused slot (0). */
    private static final int MAX_VERTICES = 1_000_001;   // safe upper bound for typical constraints

    /** Adjacency list where index corresponds to the vertex id. */
    private final List<Integer>[] adjacency = new List[MAX_VERTICES];

    /** Tracks whether a vertex has been visited during DFS. */
    private final boolean[] visited = new boolean[MAX_VERTICES];

    /** Mapping from grid coordinates to a unique vertex id. */
    private final int[][] idMap;

    /** Number of rows and columns of the grid. */
    private final int rows, cols;

    /** The character grid itself. */
    private final char[][] grid;

    /**
     * Constructs the detector with the supplied dimensions and grid.
     *
     * @param rows    number of rows
     * @param cols    number of columns
     * @param grid    character grid
     */
    public GraphCycleDetector(int rows, int cols, char[][] grid) {
        this.rows = rows;
        this.cols = cols;
        this.grid = grid;
        this.idMap = new int[rows][cols];
        initializeAdjacency();
    }

    /** Populates the adjacency list with edges for equal‑character neighbours. */
    private void initializeAdjacency() {
        int vertexId = 1; // 0 is left unused to keep the id space 1‑based
        for (int r = 0; r < rows; r++) {
            Arrays.fill(idMap[r], 0);
        }

        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                idMap[r][c] = vertexId++;
            }
        }

        // Ensure every adjacency list is non‑null
        for (int i = 0; i < adjacency.length; i++) {
            adjacency[i] = new ArrayList<>();
        }

        // Build undirected edges between equal‑character neighbours
        int[] dr = {-1, 1, 0, 0};
        int[] dc = {0, 0, -1, 1};

        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                int curId = idMap[r][c];
                char curChar = grid[r][c];
                for (int d = 0; d < 4; d++) {
                    int nr = r + dr[d];
                    int nc = c + dc[d];
                    if (nr < 0 || nr >= rows || nc < 0 || nc >= cols) {
                        continue;
                    }
                    if (grid[nr][nc] != curChar) {
                        continue;
                    }
                    int neighId = idMap[nr][nc];
                    // Avoid adding duplicate edges (both directions will be added naturally)
                    adjacency[curId].add(neighId);
                    adjacency[neighId].add(curId);
                }
            }
        }
    }

    /**
     * Returns {@code true} if the graph contains at least one cycle.
     *
     * @return {@code true} if a cycle is found, otherwise {@code false}
     */
    public boolean hasCycle() {
        // Reset visited flags for a fresh run (in case the method is called repeatedly)
        Arrays.fill(visited, false);

        // Scan all vertices; start a DFS from each unvisited one
        for (int v = 1; v < adjacency.length; v++) {
            if (!visited[v]) {
                if (dfsCycleDetection(v, -1)) {
                    return true; // Cycle found – no need to continue
                }
            }
        }
        return false; // No cycles detected
    }

    /**
     * Depth‑first search that detects a back‑edge to an already visited vertex
     * that is not the immediate parent.
     *
     * @param current   current vertex
     * @param parent    vertex we arrived from (or -1 if root)
     * @return {@code true} if a cycle is discovered in this component
     */
    private boolean dfsCycleDetection(int current, int parent) {
        visited[current] = true;
        for (int neighbour : adjacency[current]) {
            if (!visited[neighbour]) {
                if (dfsCycleDetection(neighbour, current)) {
                    return true;
                }
            } else if (neighbour != parent) {
                // Found a visited vertex that is not the parent → cycle
                return true;
            }
        }
        return false;
    }

    /** --------------------------------------------------------------------- */
    /** I/O utilities – keep the main method tidy and self‑contained.        */
    /** --------------------------------------------------------------------- */

    /**
     * Reads the input, builds the graph and prints the answer.
     *
     * Expected input format:
     * <pre>
     * n m
     * row_0
     * row_1
     * …
     * row_{n‑1}
     * </pre>
     *
     * Output is either {@code "Yes"} or {@code "No"}.
     */
    public static void main(String[] args) throws Exception {
        // Using Scanner is sufficient for the problem constraints and avoids
        // the custom fast‑reader implementation that was hard to maintain.
        try (Scanner scanner = new Scanner(new BufferedReader(new InputStreamReader(System.in)))) {
            int n = scanner.nextInt();   // number of rows
            int m = scanner.nextInt();   // number of columns
            char[][] grid = new char[n][m];

            // Read the grid rows
            for (int i = 0; i < n; i++) {
                String line = scanner.next();
                for (int j = 0; j < m; j++) {
                    grid[i][j] = line.charAt(j);
                }
            }

            // Construct detector and answer the problem
            GraphCycleDetector detector = new GraphCycleDetector(n, m, grid);
            System.out.println(detector.hasCycle() ? "Yes" : "No");
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.ArrayDeque;
import java.util.Deque;
import java.util.StringTokenizer;

/**
 * Reflection of static typing in Java.
 *
 * Problem: Detect if there exists a cycle of length ≥ 4 formed by adjacent '#'
 * cells in a 2‑D grid.
 */
public class CF290B {

    /* Directions: down, up, right, left */
    private static final int[][] DIRECTIONS = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};

    private InputReader scanner;
    private PrintWriter writer;

    /* ---------------------- Entry point ---------------------- */
    public static void main(String[] args) {
        new CF290B().run();
    }

    /* ---------------------- Execution flow ------------------- */
    private void run() {
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in))) {
            scanner = new InputReader(br);
            writer = new PrintWriter(System.out, true);
            solve();
        } catch (IOException e) {
            e.printStackTrace();
        } finally {
            writer.close();
        }
    }

    private void solve() {
        int rows = scanner.nextInt();
        int cols = scanner.nextInt();
        char[][] board = readBoard(rows);

        boolean hasCycle = hasCycle(board);
        writer.println(hasCycle ? "Yes" : "No");
    }

    private char[][] readBoard(int rows) {
        char[][] board = new char[rows][];
        for (int i = 0; i < rows; i++) {
            String line = scanner.next();
            board[i] = line.toCharArray();
        }
        return board;
    }

    /* ---------------------- Cycle detection ----------------- */
    private boolean hasCycle(char[][] board) {
        int rows = board.length;
        int cols = board[0].length;
        boolean[][] visited = new boolean[rows][cols];

        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (!visited[i][j] && board[i][j] == '#') {
                    if (bfsDetectCycle(board, visited, i, j)) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    /** Breadth‑first search that returns true if any cycle is found in the component. */
    private boolean bfsDetectCycle(char[][] board, boolean[][] visited, int startX, int startY) {
        char targetColor = board[startX][startY];
        Deque<Point> queue = new ArrayDeque<>();
        queue.add(new Point(startX, startY));
        visited[startX][startY] = true;

        while (!queue.isEmpty()) {
            Point cur = queue.pollFirst();
            for (int[] dir : DIRECTIONS) {
                int nx = cur.x + dir[0];
                int ny = cur.y + dir[1];

                if (isOutOfBounds(nx, ny, board)) {
                    continue;
                }
                if (board[nx][ny] != targetColor) {
                    continue;
                }
                if (!visited[nx][ny]) {
                    visited[nx][ny] = true;
                    queue.addLast(new Point(nx, ny));
                } else {
                    // Visited neighbour that is not the immediate parent → cycle.
                    return true;
                }
            }
        }
        return false;
    }

    private boolean isOutOfBounds(int x, int y, char[][] board) {
        return x < 0 || y < 0 || x >= board.length || y >= board[0].length;
    }

    /** Simple holder for a grid coordinate. */
    private static final class Point {
        final int x, y;
        Point(int x, int y) { this.x = x; this.y = y; }
    }

    /* ---------------------- Fast input reader --------------- */
    /** Minimal scanner suitable for competitive programming. */
    private static class InputReader {
        private final BufferedReader br;
        private StringTokenizer st;

        InputReader(BufferedReader br) {
            this.br = br;
        }

        String next() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                st = new StringTokenizer(br.readLine());
            }
            return st.nextToken();
        }

        int nextInt() throws IOException { return Integer.parseInt(next()); }

        long nextLong() throws IOException { return Long.parseLong(next()); }

        double nextDouble() throws IOException { return Double.parseDouble(next()); }
    }
}

/**
 * Detects whether a grid contains a cycle of length ≥ 4 consisting of the same
 * character. The algorithm performs a depth‑first search and reports “Yes”
 * if any such cycle exists, otherwise “No”.
 *
 * The implementation is deliberately kept simple and readable while still
 * offering good performance and testability.
 */
public class Main {

    /** Directions used for neighbour exploration (up, right, down, left). */
    private enum Direction {
        UP(-1, 0), RIGHT(0, 1), DOWN(1, 0), LEFT(0, -1);

        private final int dr;
        private final int dc;

        Direction(int dr, int dc) {
            this.dr = dr;
            this.dc = dc;
        }

        int[] delta() {
            return new int[]{dr, dc};
        }
    }

    /** Simple container that stores the parent coordinates of a DFS node. */
    private static final class Parent {
        final int row;
        final int col;

        Parent(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }

    public static void main(String[] args) throws Exception {
        // -----------------------------------------------------------------------
        // Input handling – using try‑with‑resources to guarantee proper closure.
        // -----------------------------------------------------------------------
        try (var reader = new BufferedReader(
                new InputStreamReader(System.in));
             var writer = new BufferedWriter(
                new java.io.PrintWriter(System.out))) {

            String[] header = reader.readLine().split("\\s+");
            int rows = Integer.parseInt(header[0]);
            int cols = Integer.parseInt(header[1]);

            // Convert each character to its 1‑based alphabet index (e.g. 'A' → 1)
            char[][] grid = new char[rows][cols];
            for (int r = 0; r < rows; r++) {
                String line = reader.readLine();
                for (int c = 0; c < cols; c++) {
                    grid[r][c] = line.charAt(c);
                }
            }

            // Execute the detection and write the result.
            writer.write(determineResult(grid));
            writer.flush();
        }
    }

    /**
     * Determines whether the given grid contains a cycle of at least four cells
     * with identical characters. Returns the string "Yes" or "No".
     *
     * @param grid matrix of uppercase letters
     * @return "Yes" if a qualifying cycle exists, otherwise "No"
     */
    private static String determineResult(char[][] grid) {
        final int rows = grid.length;
        final int cols = grid[0].length;

        // visited[r][c] == 0  → not visited yet
        // visited[r][c] == 1  → currently exploring (stack frame)
        // visited[r][c] == 2  → finished exploring
        int[][] visited = new int[rows][cols];
        boolean[][] hasCycle = new boolean[rows][cols];

        // Exploration flag – once a cycle is found we can stop the whole search.
        final boolean[] found = {false};

        // Parent information for each cell (null if the cell has no parent yet).
        Parent[][] parent = new Parent[rows][cols];
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                parent[r][c] = null;
            }
        }

        // -----------------------------------------------------------------------
        // DFS from every unvisited cell until a cycle is discovered.
        // -----------------------------------------------------------------------
        for (int r = 0; r < rows && !found[0]; r++) {
            for (int c = 0; c < cols && !found[0]; c++) {
                if (visited[r][c] == 0) {
                    explore(r, c, grid, visited, hasCycle, parent, found);
                }
            }
        }

        // Collect the answer – any true entry in hasCycle triggers "Yes".
        for (boolean[] row : hasCycle) {
            for (boolean cell : row) {
                if (cell) {
                    return "Yes";
                }
            }
        }
        return "No";
    }

    /**
     * Depth‑first search that marks visited cells and detects cycles.
     *
     * @param r        current row
     * @param c        current column
     * @param grid     character grid
     * @param visited  visitation state matrix
     * @param hasCycle detection result matrix
     * @param parent   map of parent coordinates for each cell
     * @param found    wrapper flag to stop early when a cycle is found
     */
    private static void explore(int r, int c,
                                char[][] grid,
                                int[][] visited,
                                boolean[][] hasCycle,
                                Parent[][] parent,
                                boolean[] found) {
        visited[r][c] = 1; // entering the node

        for (Direction dir : Direction.values()) {
            int nr = r + dir.delta()[0];
            int nc = c + dir.delta()[1];

            // Skip out‑of‑bounds neighbours.
            if (!isInBounds(nr, grid.length, grid[0].length)) {
                continue;
            }

            // Only follow neighbours with the *same* character.
            if (grid[nr][nc] != grid[r][c]) {
                continue;
            }

            // If neighbour hasn't been visited yet, recurse.
            if (visited[nr][nc] == 0) {
                parent[nr][nc] = new Parent(r, c);
                explore(nr, nc, grid, visited, hasCycle, parent, found);
                if (found[0]) {
                    return; // early exit – a cycle was already detected upstream
                }
                continue;
            }

            // If the neighbour is already being explored and it is not the direct
            // parent, we have discovered a cycle of length ≥ 4.
            if (visited[nr][nc] == 1 && !isParent(parent, r, c, nr, nc)) {
                hasCycle[r][c] = true;
                found[0] = true;
                return;
            }
        }

        visited[r][c] = 2; // leaving the node
    }

    /** Checks whether (pr, pc) is the immediate parent of (r, c). */
    private static boolean isParent(Parent[][] parent, int r, int c, int pr, int pc) {
        Parent candidate = parent[r][c];
        return candidate != null && candidate.row == pr && candidate.col == pc;
    }

    /** Utility to test array bounds. */
    private static boolean isInBounds(int index, int min, int max) {
        return index >= min && index < max;
    }
}

/**
 * Detects whether a rectangular grid of characters contains a cycle of the
 * same character whose length is at least 4. The cycle must move only up,
 * down, left or right and may not immediately go back on the edge it came
 * from.
 *
 * <p>Refactor goals
 *
 * <ul>
 *   <li>All mutable state is contained inside objects – no class‑level globals.</li>
 *   <li>Distinct responsibilities are separated into small, focused classes.</li>
 *   <li>Naming and constants make the intent self‑documenting.</li>
 *   <li>Input handling, processing and output are clearly separated.</li>
 *   <li>The code follows modern Java style (try‑with‑resources, final where possible,
 *       appropriate access modifiers, etc.).</li>
 * </ul>
 */
public class CircularCharChecker {

    /** Directions in which we can move. */
    private enum Direction {
        UP(0, -1), DOWN(0, 1), LEFT(-1, 0), RIGHT(1, 0);

        final int di;
        final int dj;

        Direction(int di, int dj) {
            this.di = di;
            this.dj = dj;
        }

        int[] offset() {
            return new int[]{di, dj};
        }
    }

    /** Small holder that represents a single cell visited during DFS. */
    private static final class VisitedCell {
        final int row;
        final int col;

        VisitedCell(int row, int col) {
            this.row = row;
            this.col = col;
        }

        @Override
        public boolean equals(Object o) {
            if (this == o) return true;
            if (!(o instanceof VisitedCell that)) return false;
            return row == that.row && col == that.col;
        }

        @Override
        public int hashCode() {
            return 31 * row + col;
        }
    }

    /** Core logic for finding a circular path of equal characters. */
    private static final class CircularDetector {

        private final char[][] grid;
        private final boolean[][] visited;
        private final char targetChar;
        private final VisitedCell parent;               // the cell we entered the current cell from
        private boolean found;                           // signal that a cycle was discovered

        CircularDetector(char[][] grid) {
            this.grid = grid;
            this.visited = new boolean[grid.length][grid[0].length];
            this.targetChar = '\0';   // will be set by the caller for each DFS start
            this.parent = new VisitedCell(-1, -1);
            this.found = false;
        }

        /**
         * Starts a depth‑first search from the given cell if it has not been visited yet.
         * Returns {@code true} when a suitable cycle has been found.
         */
        boolean hasCycleStartingAt(int startRow, int startCol) {
            targetChar = grid[startRow][startCol];
            resetVisited();                // only the current DFS needs a fresh visited mask
            dfs(startRow, startCol, parent);
            return found;
        }

        /** Depth‑first search that looks for a cycle of length >= 4. */
        private void dfs(int row, int col, VisitedCell from) {
            visited[row][col] = true;
            for (Direction dir : Direction.values()) {
                int nextRow = row + dir.di;
                int nextCol = col + dir.dj;

                if (!isInBounds(nextRow, nextCol)) {
                    continue;
                }
                if (grid[nextRow][nextCol] != targetChar) {
                    continue;
                }
                if (visited[nextRow][nextCol]) {
                    // Found a previously visited cell – must be the start of a cycle.
                    // Ensure we didn't just go back on the edge we came from.
                    if (nextRow == from.row && nextCol == from.col) {
                        continue;
                    }
                    // Cycle length is guaranteed to be at least 4 because we only
                    // start DFS from cells that have a neighbour of the same character,
                    // and we explore only cells that are reachable via that neighbour.
                    found = true;
                    return;
                }
                // Continue exploring deeper.
                dfs(nextRow, nextCol, new VisitedCell(row, col));
                if (found) {
                    return;
                }
            }
        }

        private boolean isInBounds(int r, int c) {
            return r >= 0 && r < grid.length && c >= 0 && c < grid[0].length;
        }

        private void resetVisited() {
            for (int i = 0; i < visited.length; i++) {
                java.util.Arrays.fill(visited[i], false);
            }
        }
    }

    /** ---------------------------------------------------------------
     *  Program entry point.
     *  ---------------------------------------------------------------
     */
    public static void main(String[] args) {
        try (java.util.Scanner sc = new java.util.Scanner(System.in)) {
            int rows = sc.nextInt();
            int cols = sc.nextInt();
            char[][] grid = new char[rows][cols];

            for (int i = 0; i < rows; i++) {
                String line = sc.next();
                for (int j = 0; j < cols; j++) {
                    grid[i][j] = line.charAt(j);
                }
            }

            CircularDetector detector = new CircularDetector(grid);
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (hasPotentialStart(grid, i, j) && detector.hasCycleStartingAt(i, j)) {
                        System.out.println("Yes");
                        return;
                    }
                }
            }
            System.out.println("No");
        }
    }

    /** Determines whether a cell can possibly be the *second* cell of a
     *  candidate cycle of length ≥ 4.  This mirrors the original program’s
     *  cheap preliminary check: the cell to the right and the cell below
     *  must share the same character as the current one. */
    private static boolean hasPotentialStart(char[][] grid, int r, int c) {
        char cur = grid[r][c];
        // Need a right neighbour *and* a bottom neighbour (both must exist)
        if (c + 1 >= grid[0].length || r + 1 >= grid.length) {
            return false;
        }
        char right = grid[r][c + 1];
        char down = grid[r + 1][c];
        return right == cur && down == cur;
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.Deque;
import java.util.LinkedList;
import java.util.StringTokenizer;

public class GraphProblemB {

    /** Directions: up, down, left, right */
    private static final int[][] DIRS = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};

    private final int rows, cols;
    private final char[][] board;
    private final int[][] visited;           // component identifier for each cell
    private final int[][][] parent;          // parent coordinates of each visited cell
    private int componentId;                  // monotonically increasing identifier of current component

    /* --------------------------------------------------- */
    /* Entry point                                           */
    /* --------------------------------------------------- */
    public static void main(String[] args) throws IOException {
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in))) {
            new GraphProblemB(br).solve();
        }
    }

    /* --------------------------------------------------- */
    /* Constructor – stores the input buffer                 */
    /* --------------------------------------------------- */
    private final BufferedReader rd;
    private GraphProblemB(BufferedReader rd) {
        this.rd = rd;
    }

    /* --------------------------------------------------- */
    /* Main solving routine                                   */
    /* --------------------------------------------------- */
    private void solve() throws IOException {
        readBoard();
        initDataStructures();

        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (visited[r][c] == -1) {
                    if (bfsCycleDetection(r, c)) {
                        System.out.println("Yes");
                        return;
                    }
                }
            }
        }
        System.out.println("No");
    }

    /* --------------------------------------------------- */
    /* Reads the board from stdin                              */
    /* --------------------------------------------------- */
    private void readBoard() throws IOException {
        String first = rd.readLine();
        if (first == null) throw new IOException("Empty input");
        String[] dims = split(first);
        rows = Integer.parseInt(dims[0]);
        cols = Integer.parseInt(dims[1]);

        board = new char[rows][];
        for (int r = 0; r < rows; r++) {
            board[r] = split(rd.readLine())[0].toCharArray();
        }
    }

    /* --------------------------------------------------- */
    /* Initializes visited flags and parent storage           */
    /* --------------------------------------------------- */
    private void initDataStructures() {
        visited = new int[rows][cols];
        parent = new int[rows][cols][2];
        for (int[] row : visited) {
            java.util.Arrays.fill(row, -1);
        }
        componentId = 0;
    }

    /* --------------------------------------------------- */
    /* Breadth‑first search that detects a non‑trivial cycle */
    /* --------------------------------------------------- */
    private boolean bfsCycleDetection(int startR, int startC) {
        componentId++;                     // a new component identifier
        Deque<int[]> queue = new LinkedList<>();
        queue.addLast(new int[]{startR, startC, 0});   // row, col, dummy depth
        visited[startR][startC] = componentId;

        while (!queue.isEmpty()) {
            int[] cur = queue.removeFirst();
            int r = cur[0], c = cur[1];

            for (int[] dir : DIRS) {
                int nr = r + dir[0];
                int nc = c + dir[1];
                if (!inBounds(nr, nc)) continue;
                if (board[nr][nc] != board[r][c]) continue;

                if (visited[nr][nc] != componentId) {
                    // first time we see this neighbour
                    visited[nr][nc] = componentId;
                    parent[nr][nc][0] = r;
                    parent[nr][nc][1] = c;
                    queue.addLast(new int[]{nr, nc, 0});
                } else if (visited[nr][nc] == componentId) {
                    // neighbour already visited in the same BFS layer
                    // ignore the edge that goes back to the immediate parent
                    if (parent[r][c][0] != nr || parent[r][c][1] != nc) {
                        return true;      // a non‑trivial cycle was found
                    }
                }
            }
        }
        return false;
    }

    /* --------------------------------------------------- */
    /* Helper – check board limits                           */
    /* --------------------------------------------------- */
    private boolean inBounds(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    /* --------------------------------------------------- */
    /* Utility – split a line into tokens                     */
    /* --------------------------------------------------- */
    private static String[] split(String line) {
        if (line == null || line.isEmpty()) return new String[0];
        StringTokenizer st = new StringTokenizer(line);
        int tokenCount = st.countTokens();
        String[] tokens = new String[tokenCount];
        for (int i = 0; i < tokenCount; i++) {
            tokens[i] = st.nextToken();
        }
        return tokens;
    }
}

import java.io.*;
import java.util.*;

public class Main {

    /** Direction vectors: up, down, left, right */
    private static final int[][] DIRS = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};

    public static void main(String[] args) throws IOException {
        /* ---------- Input handling ---------- */
        try (BufferedReader br = new BufferedReader(
                new InputStreamReader(System.in));
             PrintWriter pw = new PrintWriter(System.out)) {

            String[] header = br.readLine().split("\\s+");
            int rows = Integer.parseInt(header[0]);
            int cols = Integer.parseInt(header[1]);

            char[][] grid = new char[rows][];
            for (int r = 0; r < rows; r++) {
                String line = br.readLine();
                grid[r] = line.toCharArray();               // store each row directly
            }

            /* ---------- Cycle detection ---------- */
            boolean[][] visited = new boolean[rows][cols];
            boolean hasCycle = false;

            for (int r = 0; r < rows && !hasCycle; r++) {
                for (int c = 0; c < cols && !hasCycle; c++) {
                    if (!visited[r][c]) {
                        hasCycle = dfs(grid, visited, r, c, -1, -1);
                    }
                }
            }

            /* ---------- Output ---------- */
            pw.println(hasCycle ? "Yes" : "No");
        }
    }

    /**
     * Depth‑first search that returns {@code true} as soon as a cycle of length ≥ 4
     * is discovered in the component containing (r,c).
     *
     * @param grid     the character grid
     * @param visited  matrix that tracks already processed cells
     * @param r        current row
     * @param c        current column
     * @param pr       previous row (parent), or –1 if none
     * @param pc       previous column (parent), or –1 if none
     * @return {@code true} if a cycle was found downstream
     */
    private static boolean dfs(char[][] grid, boolean[][] visited, int r, int c, int pr, int pc) {
        visited[r][c] = true;

        for (int[] dir : DIRS) {
            int nr = r + dir[0];
            int nc = c + dir[1];

            // 1️⃣ stay inside the grid
            if (!isInBounds(grid, nr, nc)) {
                continue;
            }

            // 2️⃣ only consider neighbours of the same character
            if (grid[nr][nc] != grid[r][c]) {
                continue;
            }

            // 3️⃣ if neighbour is unvisited → recurse
            if (!visited[nr][nc]) {
                if (dfs(grid, visited, nr, nc, r, c)) {
                    return true;      // propagate upward the detection of a cycle
                }
            }
            // 4️⃣ visited neighbour that is *not* the parent → a cycle (≥ 4) exists
            else if (nr != pr || nc != pc) {
                return true;
            }
        }
        return false;   // no cycle found in this branch
    }

    /** Helper to check array bounds. */
    private static boolean isInBounds(char[][] grid, int r, int c) {
        return r >= 0 && r < grid.length && c >= 0 && c < grid[0].length;
    }
}

import java.util.Scanner;

/**
 * Detects whether a grid contains a cycle formed by identical characters.
 * <p>
 * A cycle is a closed path of length ≥ 2 that moves only to orthogonal
 * neighbours (up, down, left, right) and whose cells all contain the same
 * character.
 * </p>
 */
public class CycleDetector {

    /** Four orthogonal directions used for neighbour exploration. */
    private static final int[][] DIRECTIONS = {
            {-1, 0},   // up
            {1, 0},    // down
            {0, -1},   // left
            {0, 1}     // right
    };

    /**
     * Determines if the supplied grid contains any cycle.
     *
     * @param grid character grid to examine
     * @return {@code true} if a cycle exists, {@code false} otherwise
     */
    public static boolean hasCycle(char[][] grid) {
        final int rows = grid.length;
        final int cols = grid[0].length;
        boolean[][] visited = new boolean[rows][cols];

        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (!visited[r][c] && dfs(r, c, grid, visited, -1, -1)) {
                    return true;          // cycle discovered
                }
            }
        }
        return false;                     // no cycles found
    }

    /**
     * Depth‑first search that checks for cycles starting at {@code (row, col)}.
     *
     * @param row        current row index
     * @param col        current column index
     * @param grid       the character grid
     * @param visited    matrix tracking visited cells
     * @param pr         parent row (or -1 if none)
     * @param pc         parent column (or -1 if none)
     * @return {@code true} if a cycle is found in this component
     */
    private static boolean dfs(int row, int col, char[][] grid,
                               boolean[][] visited, int pr, int pc) {
        visited[row][col] = true;

        for (int[] dir : DIRECTIONS) {
            int nxtRow = row + dir[0];
            int nxtCol = col + dir[1];

            // Boundary check
            if (nxtRow < 0 || nxtRow >= grid.length ||
                nxtCol < 0 || nxtCol >= grid[0].length) {
                continue;
            }

            // Do not go back to the cell we arrived from
            if (nxtRow == pr && nxtCol == pc) {
                continue;
            }

            // Characters must match to stay on the same component
            if (grid[nxtRow][nxtCol] != grid[row][col]) {
                continue;
            }

            if (visited[nxtRow][nxtCol]) {
                // Re‑visiting a node that isn’t the immediate parent means a cycle
                return true;
            }

            if (dfs(nxtRow, nxtCol, grid, visited, row, col)) {
                return true;
            }
        }
        return false;
    }

    /** Simple driver that reads input, runs the detector, and prints the result. */
    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            int rows = scanner.nextInt();
            int cols = scanner.nextInt();

            char[][] grid = new char[rows][cols];
            for (int i = 0; i < rows; i++) {
                String line = scanner.next();
                for (int j = 0; j < cols; j++) {
                    grid[i][j] = line.charAt(j);
                }
            }

            System.out.println(hasCycle(grid) ? "Yes" : "No");
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;

/**
 * Detects whether the given grid contains a cycle of adjacent equal characters.
 *
 * <p>Input format:
 *
 * <pre>
 * n m
 * row‑1
 * row‑2
 * …
 * row‑n
 * </pre>
 *
 * <p>Each row contains exactly {@code m} characters.
 *
 * <p>If a cycle is found the program prints {@code Yes}, otherwise {@code No}.
 *
 * <p>The implementation has been refactored for readability, maintainability and
 * proper resource handling.
 */
public class Main {

    /** Sentinel value used for “unvisited” cells in the {@code visited} matrix. */
    private static final int UNVISITED = Integer.MIN_VALUE;

    /** Number of rows in the grid. */
    private int rows;

    /** Number of columns in the grid. */
    private int cols;

    /** Grid of characters to be examined. */
    private char[][] grid;

    /** Timestamp of the DFS step when a cell was last visited. */
    private int[][] visited;

    /** Offsets for the four possible moves (left, right, up, down). */
    private static final int[][] DIRECTIONS = {
            {0, -1},   // left
            {0, 1},    // right
            {-1, 0},   // up
            {1, 0}     // down
    };

    /**
     * Entry point of the program.
     *
     * @param args command‑line arguments (unused)
     * @throws IOException if an I/O error occurs while reading from {@code System.in}
     */
    public static void main(String[] args) throws IOException {
        try (BufferedReader reader = new BufferedReader(
                new InputStreamReader(System.in))) {

            String[] firstLine = reader.readLine().split("\\s+");
            int rows = Integer.parseInt(firstLine[0]);
            int cols = Integer.parseInt(firstLine[1]);

            char[][] grid = new char[rows][];
            for (int i = 0; i < rows; i++) {
                grid[i] = reader.readLine().toCharArray();
            }

            int[][] visited = new int[rows][cols];
            for (int[] row : visited) {
                java.util.Arrays.fill(row, UNVISITED);
            }

            Main solver = new Main(rows, cols, grid, visited);
            if (solver.hasCycle()) {
                System.out.println("Yes");
            } else {
                System.out.println("No");
            }
        }
    }

    /**
     * Constructs a new solver for the supplied grid.
     *
     * @param rows    number of rows of the grid
     * @param cols    number of columns of the grid
     * @param grid    the character grid
     * @param visited matrix used to store DFS timestamps
     */
    private Main(int rows, int cols, char[][] grid, int[][] visited) {
        this.rows = rows;
        this.cols = cols;
        this.grid = grid;
        this.visited = visited;
    }

    /**
     * Determines whether any cycle exists in the grid.
     *
     * @return {@code true} if a cycle is found, {@code false} otherwise
     */
    private boolean hasCycle() {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (visited[r][c] == UNVISITED) {
                    char current = grid[r][c];
                    if (dfs(r, c, current, 0)) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    /**
     * Depth‑first search that looks for a cycle starting at {@code (r, c)}.
     *
     * @param r        current row
     * @param c        current column
     * @param current  character that must be matched to continue the path
     * @param depth    current depth stamp (used solely for distinguishing visits)
     * @return {@code true} if a cycle is detected from this start cell
     */
    private boolean dfs(int r, int c, char current, int depth) {
        visited[r][c] = depth;

        for (int[] dir : DIRECTIONS) {
            int nr = r + dir[0];
            int nc = c + dir[1];

            // Bounds check
            if (nr < 0 || nr >= rows || nc < 0 || nc >= cols) {
                continue;
            }

            // Must stay on the same character
            if (grid[nr][nc] != current) {
                continue;
            }

            // Do not immediately go back to the cell we came from
            if (visited[nr][nc] == depth - 1) {
                continue;
            }

            // If the neighbour has already been visited in this DFS tree,
            // we have found a cycle.
            if (visited[nr][nc] != UNVISITED) {
                return true;
            }

            // Otherwise, explore the neighbour recursively.
            if (dfs(nr, nc, current, depth + 1)) {
                return true;
            }
        }

        return false;
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.ArrayDeque;
import java.util.Deque;

/**
 * Detects a cycle of at least 4 cells that contains the same character
 * on a rectangular board.
 *
 * <p>Refactored version of the original {@code FoxAndTwoDots} program.
 * The algorithm:
 * <ul>
 *   <li>Iterates over every cell that has not been visited.</li>
 *   <li>Starts a depth‑first search that remembers the previous cell
 *       (the cell we came from) to avoid considering it a cycle.</li>
 *   <li>When a visited neighbour is found that is not the predecessor,
 *       a back‑edge exists. The length of the resulting cycle is
 *       {@code currentDepth - depth[neighbour] + 1}. If this length is
 *       {@code >= 4} we have found a valid cycle.</li>
 * </ul>
 * The solution prints {@code Yes} if any such cycle exists, otherwise
 * {@code No}.
 */
public class FoxAndTwoDots {

    /** Directions: up, right, down, left */
    private static final int[][] DIRS = {{-1, 0}, {0, 1}, {1, 0}, {0, -1}};

    /** Maximum board size that we support. */
    private static final int MAX_N = 50;   // generous upper bound

    /** Depth of each cell during DFS; 0 means “unvisited”. */
    private static final int[][] DEPTH = new int[MAX_N][MAX_N];

    /** Overall visited flag – used to skip cells already processed in a previous DFS. */
    private static final boolean[][] GLOBAL_VISITED = new boolean[MAX_N][MAX_N];

    /** The board itself. */
    private static char[][] grid;

    /** Board dimensions. */
    private static int rows, cols;

    /** --------------------------------------------------------------------- */
    /** Entry point. */
    public static void main(String[] args) throws IOException {
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in))) {
            String[] first = br.readLine().split("\\s+");
            rows = Integer.parseInt(first[0]);
            cols = Integer.parseInt(first[1]);

            grid = new char[rows][cols];
            for (int r = 0; r < rows; r++) {
                String line = br.readLine();
                for (int c = 0; c < cols; c++) {
                    grid[r][c] = line.charAt(c);
                }
            }

            boolean found = false;
            for (int r = 0 !found && r < rows; r++) {
                for (int c = 0; c < cols && !found; c++) {
                    if (!GLOBAL_VISITED[r][c]) {
                        if (dfs(r, c, -1, -1, 1)) {
                            found = true;
                        }
                    }
                }
            }

            System.out.println(found ? "Yes" : "No");
        }
    }

    /** --------------------------------------------------------------------- */
    /**
     * Depth‑first search for a cycle.
     *
     * @param r          current row
     * @param c          current column
     * @param prRow      previous row (or -1 for the start cell)
     * @param prCol      previous column (or -1 for the start cell)
     * @param depthSoFar current depth in the search tree
     * @return {@code true} if a cycle of length ≥4 is detected from this start cell
     */
    private static boolean dfs(int r, int c, int prRow, int prCol, int depthSoFar) {
        GLOBAL_VISITED[r][c] = true;            // mark as processed globally
        DEPTH[r][c] = depthSoFar;               // store depth for back‑edge length calculation

        for (int[] dir : DIRS) {
            int nr = r + dir[0];
            int nc = c + dir[1];

            // bounds check
            if (nr < 0 || nr >= rows || nc < 0 || nc >= cols) {
                continue;
            }

            // we can only move to cells with the same character
            if (grid[nr][nc] != grid[r][c]) {
                continue;
            }

            // ignore the cell we just came from (prevents trivial back‑track)
            if (nr == prRow && nc == prCol) {
                continue;
            }

            if (!GLOBAL_VISITED[nr][nc]) {
                // explore unvisited neighbours recursively
                if (dfs(nr, nc, r, c, depthSoFar + 1)) {
                    return true;                // propagate success upward
                }
            } else {
                // neighbour has been visited earlier → a cycle.
                // Cycle length = current depth - stored depth of neighbour + 1
                int cycleLength = depthSoFar - DEPTH[nr][nc] + 1;
                if (cycleLength >= 4) {
                    return true;                // found a valid cycle
                }
            }
        }
        return false;   // no cycle found from this branch
    }
}

import java.util.ArrayDeque;
import java.util.Deque;
import java.util.Scanner;

/**
 * Detects a cycle of equal‑valued cells in a rectangular grid.
 *
 * <p>If such a cycle exists the program prints {@code Yes} and terminates,
 * otherwise it prints {@code No}.</p>
 */
public class Code2Feb02 {

    /** Maximum supported dimensions (used only for static allocation). */
    private static final int MAX = 55;

    /** Grid storing the characters */
    private static char[][] grid = new char[MAX][MAX];

    /** Visited flag for each cell */
    private static boolean[][] visited = new boolean[MAX][MAX];

    /** Parent of each visited cell – used to avoid treating the edge back
     *  to the parent as a cycle. */
    private static int[][] parentRow = new int[MAX][MAX];
    private static int[][] parentCol = new int[MAX][MAX];

    /** Entry point */
    public static void main(String[] args) {
        solve();
    }

    /** Reads input, runs the search and prints the result. */
    private static void solve() {
        try (Scanner scanner = new Scanner(System.in)) {
            readDimensions(scanner);
            readGrid(scanner);
        }

        // Explore each component of the grid
        for (int row = 0; row < n; row++) {
            for (int col = 0; col < m; col++) {
                if (!visited[row][col]) {
                    boolean foundCycle = bfs(row, col);
                    if (foundCycle) {
                        return; // Cycle already printed inside BFS
                    }
                }
            }
        }

        System.out.println("No");
    }

    /** Reads the two dimensions of the grid. */
    private static void readDimensions(Scanner scanner) {
        n = scanner.nextInt();
        m = scanner.nextInt();
        // Consume the line separator after the two integers
        scanner.nextLine();
    }

    /** Reads the grid itself. */
    private static void readGrid(Scanner scanner) {
        for (int i = 0; i < n; i++) {
            String line = scanner.nextLine().trim();
            grid[i] = line.toCharArray();
        }
    }

    /** Breadth‑first search that reports a cycle of equal characters. */
    private static boolean bfs(int startRow, int startCol) {
        Deque<int[]> queue = new ArrayDeque<>();
        queue.addLast(new int[]{startRow, startCol});

        visited[startRow][startCol] = true;
        parentRow[startRow][startCol] = -1;
        parentCol[startRow][startCol] = -1;

        while (!queue.isEmpty()) {
            int[] cur = queue.removeFirst();
            int r = cur[0];
            int c = cur[1];
            char currentChar = grid[r][c];

            // Explore the four orthogonal neighbours
            for (int[] dir : List.of(
                    new int[]{1, 0},   // down
                    new int[]{-1, 0},  // up
                    new int[]{0, 1},   // right
                    new int[]{0, -1}   // left
            )) {
                int nr = r + dir[0];
                int nc = c + dir[1];

                // Bounds check and same‑value requirement
                if (outOfBounds(nr, nc) || grid[nr][nc] != currentChar) {
                    continue;
                }

                if (!visited[nr][nc]) {
                    // First time we see this neighbour → enqueue it
                    visited[nr][nc] = true;
                    parentRow[nr][nc] = r;
                    parentCol[nr][nc] = c;
                    queue.addLast(new int[]{nr, nc});
                } else {
                    // Already visited neighbour – a cycle is found unless it
                    // is the cell we came from (the parent)
                    if (nr != parentRow[r][c] || nc != parentCol[r][c]) {
                        System.out.println("Yes");
                        System.exit(0);
                    }
                }
            }
        }

        return false; // No cycle discovered in this component
    }

    /** Returns {@code true} if the given coordinates are outside the grid. */
    private static boolean outOfBounds(int row, int col) {
        return row < 0 || row >= n || col < 0 || col >= m;
    }

    /** Grid dimensions */
    private static int n;
    private static int m;
}

import java.io.*;
import java.util.*;

public class Main {

    /** Entry point of the program. */
    public static void main(String[] args) throws IOException {
        /* ----- Input ----- */
        try (BufferedReader br = new BufferedReader(
                new InputStreamReader(System.in))
        ) {
            String[] dim = br.readLine().split("\\s+");
            if (dim == null || dim.length != 2) {
                return;
            }
            int rows = Integer.parseInt(dim[0]);
            int cols = Integer.parseInt(dim[1]);

            char[][] board = new char[rows][cols];
            for (int r = 0; r < rows; r++) {
                String line = br.readLine();
                if (line == null || line.length() != cols) {
                    continue;                // tolerate malformed input
                }
                for (int c = 0; c < cols; c++) {
                    board[r][c] = line.charAt(c);
                }
            }

            /* ----- Cycle detection ----- */
            boolean hasCycle = hasCycle(board);
            System.out.println(hasCycle ? "Yes" : "No");
        }
    }

    /**
     * Detects whether the board contains a cycle of cells sharing the same colour.
     * <p>
     * The algorithm performs a depth‑first search (DFS) on each not‑yet‑visited
     * cell. While traversing we keep track of the parent cell to avoid reporting
     * the trivial “edge back to parent” as a cycle.
     *
     * @param board the grid of characters
     * @return true if any cycle exists, false otherwise
     */
    private static boolean hasCycle(char[][] board) {
        final int rows = board.length;
        final int cols = board[0].length;
        boolean[][] visited = new boolean[rows][cols];

        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (!visited[r][c]) {
                    if (dfsCycleDetection(board, visited, r, c, -1, -1)) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    /**
     * Depth‑first search used by {@link #hasCycle(char[][])}.
     *
     * @param board    the grid
     * @param visited  marker of already processed cells
     * @param r        current row
     * @param c        current column
     * @param pr       previous row (‑1 for the start)
     * @param pc       previous column (‑1 for the start)
     * @return true if a cycle is found downstream
     */
    private static boolean dfsCycleDetection(
            char[][] board,
            boolean[][] visited,
            int r,
            int c,
            int pr,
            int pc) {

        visited[r][c] = true;
        // Explore the four orthogonal neighbours
        int[][] dirs = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};
        for (int[] d : dirs) {
            int nr = r + d[0];
            int nc = c + d[1];

            // Boundary check
            if (nr < 0 || nr >= board.length || nc < 0 || nc >= board[0].length) {
                continue;
            }
            // Skip cells of different colour
            if (board[nr][nc] != board[r][c]) {
                continue;
            }
            // Prevent going back to the immediate parent
            if (nr == pr && nc == pc) {
                continue;
            }
            if (visited[nr][nc]) {
                // A visited neighbour that is not the parent forms a cycle
                return true;
            }
            // Continue DFS from the neighbour
            if (dfsCycleDetection(board, visited, nr, nc, r, c)) {
                return true;
            }
        }
        return false;
    }
}

import java.util.Arrays;
import java.util.LinkedList;
import java.util.Queue;
import java.util.Scanner;

/**
 * Fox and Two Dots – cycle detection in a grid of characters.
 * <p>
 * The algorithm performs a BFS on each unvisited component, refusing to
 * immediately return to the cell we came from. If during the traversal we
 * encounter a cell that has already been visited (and it isn’t the cell we
 * just came from) a cycle exists.
 * </p>
 */
public class FoxAndTwoDots {

    /** Marks a cell that has not been visited yet. */
    private static final int UNVISITED = -1;

    /** Step count for the first visit (kept constant for readability). */
    private static final int FIRST_VISIT = 0;

    /** Four possible movement directions. */
    private static final int[] DX = {1, -1, 0, 0};
    private static final int[] DY = {0, 0, 1, -1};

    /** Simple wrapper for BFS queue elements. */
    private static final class State {
        final int x;
        final int y;
        final int prevDirection; // –1 for the start cell

        State(int x, int y, int prevDirection) {
            this.x = x;
            this.y = y;
            this.prevDirection = prevDirection;
        }
    }

    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            int rows = scanner.nextInt();
            int cols = scanner.nextInt();

            char[][] board = readBoard(scanner, rows, cols);
            boolean hasCycle = hasCycle(board);
            System.out.println(hasCycle ? "Yes" : "No");
        }
    }

    /** Reads the board from {@code scanner}. */
    private static char[][] readBoard(Scanner scanner, int n, int m) {
        char[][] board = new char[n][m];
        for (int i = 0; i < n; i++) {
            String line = scanner.next();
            for (int j = 0; j < m; j++) {
                board[i][j] = line.charAt(j);
            }
        }
        return board;
    }

    /** Main cycle detection routine. */
    private static boolean hasCycle(char[][] board) {
        int n = board.length;
        int m = board[0].length;
        int[][] visited = new int[n][m];
        for (int[] row : visited) {
            Arrays.fill(row, UNVISITED);
        }

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (visited[i][j] == UNVISITED) {
                    if (bfs(board, visited, i, j)) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    /** Breadth‑first search that looks for a cycle starting from (sx, sy). */
    private static boolean bfs(char[][] board, int[][] visited, int sx, int sy) {
        Queue<State> queue = new LinkedList<>();
        visited[sx][sy] = FIRST_VISIT;
        queue.add(new State(sx, sy, -1));

        while (!queue.isEmpty()) {
            State cur = queue.poll();
            for (int dir = 0; dir < 4; dir++) {
                // Do not step back to the cell we just came from.
                if (dir == cur.prevDirection) {
                    continue;
                }
                int nx = cur.x + DX[dir];
                int ny = cur.y + DY[dir];

                // Boundary check.
                if (nx < 0 || nx >= board.length || ny < 0 || ny >= board[0].length) {
                    continue;
                }
                // Same colour must be preserved.
                if (board[nx][ny] != board[cur.x][cur.y]) {
                    continue;
                }
                // If we reach a cell that was visited earlier (and it isn’t the parent),
                // a cycle has been found.
                if (visited[nx][ny] != UNVISITED) {
                    return true;
                }
                visited[nx][ny] = visited[cur.x][cur.y] + 1;
                queue.add(new State(nx, ny, dir));
            }
        }
        return false;
    }
}

