/**
 * Detects a cycle of identical characters in a grid.
 *
 * <p>The algorithm performs a depth‑first search from each unvisited cell.
 * When a neighbour that has already been discovered in the current traversal
 * (and is not the immediate predecessor) is found, a cycle exists.</p>
 */
class CycleDetector {

    /** Relative moves in the four cardinal directions. */
    private static final int[] DX = {-1, 0, 0, 1};
    /** Relative moves in the four cardinal directions. */
    private static final int[] DY = {0, 1, -1, 0};

    private final char[][] grid;
    /** Marks cells that have been visited at least once. */
    private final boolean[][] visited;

    public CycleDetector(char[][] grid) {
        this.grid = grid;
        this.visited = new boolean[grid.length][grid[0].length];
    }

    /**
     * Returns {@code true} if the grid contains any cycle of equal characters.
     */
    public boolean hasCycle() {
        for (int r = 0; r < grid.length; r++) {
            for (int c = 0; c < grid[r].length; c++) {
                if (!visited[r][c]) {
                    if (dfs(r, c, -1, -1)) {
                        return true;   // Cycle found – terminate early.
                    }
                }
            }
        }
        return false; // No cycle discovered.
    }

    /**
     * Depth‑first search starting from (x, y).
     *
     * @param x        current row
     * @param y        current column
     * @param prevX    previous row (or -1 if none)
     * @param prevY    previous column (or -1 if none)
     * @return {@code true} if a cycle is found in this branch
     */
    private boolean dfs(int x, int y, int prevX, int prevY) {
        visited[x][y] = true;
        for (int d = 0; d < DX.length; d++) {
            int nx = x + DX[d];
            int ny = y + DY[d];

            // Boundary check
            if (nx < 0 || nx >= grid.length || ny < 0 || ny >= grid[0].length) {
                continue;
            }

            // Skip back to the immediate predecessor
            if (nx == prevX && ny == prevY) {
                continue;
            }

            // Same character required to continue the path
            if (grid[nx][ny] != grid[x][y]) {
                continue;
            }

            // If the neighbour has already been visited within this DFS tree,
            // we have found a cycle.
            if (visited[nx][ny]) {
                return true;
            }

            // Continue exploring
            if (dfs(nx, ny, x, y)) {
                return true;
            }
        }
        return false;
    }
}

import java.io.PrintWriter;
import java.io.InputStream;
import java.io.OutputStreamWriter;
import java.util.Scanner;

/**
 * Detects whether a grid contains a cycle of at least four cells with the same character.
 * The implementation is deliberately kept simple while improving readability,
 * naming, and structure.
 */
public class TaskB {

    /** Four possible movement directions: right, down, left, up */
    private static final int[][] DIRECTIONS = {
            {0, 1},   // right
            {1, 0},   // down
            {0, -1},  // left
            {-1, 0}   // up
    };

    public static void main(String[] args) {
        new TaskB().run();
    }

    /* --------------------------------------------------------------------- */
    /*  I/O handling                                                         */
    /* --------------------------------------------------------------------- */
    private Scanner scanner;
    private PrintWriter writer;

    private void initIO() {
        scanner = new Scanner(System.in);
        writer = new PrintWriter(new OutputStreamWriter(System.out));
    }

    private void readInput() {
        int rows = scanner.nextInt();
        int cols = scanner.nextInt();
        scanner.nextLine();                     // consume end‑of‑line

        char[][] grid = new char[rows][];
        for (int r = 0; r < rows; r++) {
            String line = scanner.nextLine().trim();
            grid[r] = line.toCharArray();
        }

        explore(grid);
    }

    private void explore(char[][] grid) {
        boolean[][] visited = new boolean[grid.length][grid[0].length];
        boolean cycleFound = false;

        for (int r = 0; r < grid.length && !cycleFound; r++) {
            for (int c = 0; c < grid[0].length && !cycleFound; c++) {
                if (!visited[r][c]) {
                    dfs(grid, visited, r, c, -1, -1, false);
                }
            }
        }

        writeAnswer(cycleFound);
    }

    /* --------------------------------------------------------------------- */
    /*  Cycle detection via depth‑first search                               */
    /* --------------------------------------------------------------------- */
    /**
     * Recursive DFS that looks for a cycle containing ≥ 4 cells of the same character.
     *
     * @param grid       the character grid
     * @param visited    matrix that marks already processed cells
     * @param r          current row
     * @param c          current column
     * @param pr         row of the previous cell (‑1 if none)
     * @param pc         column of the previous cell (‑1 if none)
     * @param firstCall  true only for the very first invocation of the recursion
     */
    private void dfs(char[][] grid,
                     boolean[][] visited,
                     int r, int c,
                     int pr, int pc,
                     boolean firstCall) {

        visited[r][c] = true;

        for (int[] dir : DIRECTIONS) {
            int nr = r + dir[0];
            int nc = c + dir[1];

            if (!isInside(nr, nc, grid)) {
                continue;
            }

            if (grid[nr][nc] != grid[r][c]) {
                continue;                           // different character → ignore
            }

            // Do not go back to the cell we just came from
            if (pr != -1 && nr == pr && nc == pc) {
                continue;
            }

            if (visited[nr][nc]) {
                // A visited neighbour that is not the immediate predecessor forms a cycle
                if (!firstCall) {
                    this.cycleFound = true;
                }
                return;
            }

            // Continue the search deeper
            dfs(grid, visited, nr, nc, r, c, false);
            if (cycleFound) {
                return;                             // early exit once a cycle is found
            }
        }
    }

    private boolean isInside(int r, int c, char[][] grid) {
        return r >= 0 && r < grid.length && c >= 0 && c < grid[0].length;
    }

    /* --------------------------------------------------------------------- */
    /*  Output                                                            */
    /* --------------------------------------------------------------------- */
    private void writeAnswer(boolean hasCycle) {
        writer.println(hasCycle ? "Yes" : "No");
        writer.flush();
    }

    private void closeIO() {
        scanner.close();
        writer.close();
    }

    /* --------------------------------------------------------------------- */
    /*  Run orchestrator                                                      */
    /* --------------------------------------------------------------------- */
    private void run() {
        initIO();
        readInput();
        closeIO();
    }
}

/**
 * Refactored solution – cycle detection in a character matrix.
 *
 * The program reads an n×m grid of characters and reports whether any
 * cycle consisting of the same character with a length of at least 4 exists.
 *
 * Refactoring goals:
 *   • Separate concerns into dedicated classes.
 *   • Replace cryptic static globals with encapsulated fields.
 *   • Use expressive method names and constants.
 *   • Manage resources with try‑with‑resources.
 *   • Keep side‑effects (e.g., `System.out.flush()`) to an absolute minimum.
 */
public class Solution {

    /* --------------------------------------------------------------------- */
    /*  Input handling                                                       */
    /* --------------------------------------------------------------------- */
    private static final class InputReader {
        private final BufferedReader br;
        private StringTokenizer st;

        InputReader(InputStream in) {
            this.br = new BufferedReader(new InputStreamReader(in));
        }

        /** Reads the next token, blocking until one is available. */
        private String nextToken() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                st = new StringTokenizer(br.readLine());
            }
            return st.nextToken();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(nextToken());
        }

        char[][] readCharMatrix(int rows, int cols) throws IOException {
            char[][] matrix = new char[rows][cols];
            for (int r = 0; r < rows; r++) {
                String line = nextToken();
                for (int c = 0; c < cols; c++) {
                    matrix[r][c] = line.charAt(c);
                }
            }
            return matrix;
        }
    }

    /* --------------------------------------------------------------------- */
    /*  Cycle detection logic                                                 */
    /* --------------------------------------------------------------------- */
    private static final class CycleDetector {
        /** Four orthogonal directions: up, right, down, left */
        private static final int[][] DIRS = {
                {-1, 0},
                {0, 1},
                {1, 0},
                {0, -1}
        };

        private final char[][] grid;
        private final boolean[][] visited;
        private final int[][] depth;
        private final int rows;
        private final int cols;

        CycleDetector(int rows, int cols, char[][] grid) {
            this.rows = rows;
            this.cols = cols;
            this.grid = grid;
            this.visited = new boolean[rows][cols];
            this.depth = new int[rows][cols];
        }

        /**
         * Returns {@code true} if a cycle of length ≥ 4 (i.e. a revisit distance
         * of at least 2) with the same character exists anywhere in the grid.
         */
        boolean hasCycle() {
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (!visited[r][c] && dfs(r, c, -1, -1, 1)) {
                        return true;
                    }
                }
            }
            return false;
        }

        /**
         * Depth‑first search that explores neighbours with the same character.
         *
         * @param r        current row
         * @param c        current column
         * @param pr       parent row (or -1 if none)
         * @param pc       parent column (or -1 if none)
         * @param count    current depth in the DFS tree
         * @return {@code true} if a qualifying cycle is found downstream
         */
        private boolean dfs(int r, int c, int pr, int pc, int count) {
            // Boundary check
            if (r < 0 || r >= rows || c < 0 || c >= cols) {
                return false;
            }

            // Character mismatch – not part of the current component
            if (pr != -1 && grid[r][c] != grid[pr][pc]) {
                return false;
            }

            // Already visited – only count as a cycle if we jump back at least
            // two steps in depth to avoid trivial length‑1 cycles.
            if (visited[r][c]) {
                if (Math.abs(depth[r][c] - count) >= 2) {
                    return true;
                }
                return false;
            }

            visited[r][c] = true;
            depth[r][c] = count;

            // Explore all four neighbours
            for (int[] dir : DIRS) {
                int nr = r + dir[0];
                int nc = c + dir[1];
                if (dfs(nr, nc, r, c, count + 1)) {
                    return true;
                }
            }
            return false;
        }

        /** Resets internal state – kept for a clean API, not used in main flow. */
        void reset() {
            for (int r = 0; r < rows; r++) {
                Arrays.fill(visited[r], false);
                Arrays.fill(depth[r], 0);
            }
        }
    }

    /* --------------------------------------------------------------------- */
    /*  Entry point                                                            */
    /* --------------------------------------------------------------------- */
    public static void main(String[] args) throws Exception {
        // try‑with‑resources guarantees the underlying stream is closed.
        try (InputReader reader = new InputReader(System.in)) {
            int n = reader.nextInt();
            int m = reader.nextInt();
            char[][] matrix = reader.readCharMatrix(n, m);

            CycleDetector detector = new CycleDetector(n, m, matrix);
            System.out.println(detector.hasCycle() ? "Yes" : "No");
        }

        // Flush remains a no‑op in most modern JVMs but is kept for backward
        // compatibility with the original snippet.
        System.out.flush();
    }

    /* --------------------------------------------------------------------- */
    /*  Unused utility code from the original file (kept for completeness)   */
    /* --------------------------------------------------------------------- */
    private static long gcd(long a, long b) {
        return (b == 0) ? a : gcd(b, a % b);
    }

    private static int gcd(int a, int b) {
        return (b == 0) ? a : gcd(b, a % b);
    }

    private static final Random random = new Random();

    private static <T> void ruffleSort(T[] array) {
        int n = array.length;
        for (int i = 0; i < n; i++) {
            int oi = random.nextInt(n);
            T tmp = array[oi];
            array[oi] = array[i];
            array[i] = tmp;
        }
        Arrays.sort(array);
    }
}

/*
 * CycleDetector – Detects a cycle made of orthogonally adjacent cells
 * of the same character in a grid.
 *
 * The original program read the grid from standard input, performed a
 * depth‑first search on each unvisited cell, and printed "Yes" if a cycle
 * was found, otherwise "No".  This version preserves exact behaviour while
 * improving readability, maintainability and type‑safety.
 */

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.ArrayDeque;
import java.util.Deque;
import java.util.Objects;

public final class CycleDetector {

    /** Directions used for neighbour traversal (down, up, right, left). */
    private static final int[][] DIRECTIONS = {
            {1, 0},   // down
            {-1, 0},  // up
            {0, 1},   // right
            {0, -1}   // left
    };

    /** Private constructor – utility class. */
    private CycleDetector() {
    }

    /**
     * Entry point used by the original program.
     *
     * @param reader a BufferedReader that supplies the input data.
     * @throws IOException if an I/O error occurs.
     */
    public static void main(String[] args) throws IOException {
        // The original program closed the reader after use.
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(System.in))) {
            int rows = readInt(reader);
            int cols = readInt(reader);
            char[][] grid = readRows(reader, rows);

            String result = solve(rows, cols, grid);
            System.out.println(result);
        }
    }

    /** Reads the next integer token from the input stream. */
    private static int readInt(BufferedReader br) throws IOException {
        String trimmed = br.readLine().trim();
        Objects.requireNonNull(trimmed);
        String[] parts = trimmed.split("\\s+");
        return Integer.parseInt(parts[0]);
    }

    /** Reads {@code rows} lines, returning them as a char matrix. */
    private static char[][] readRows(BufferedReader br, int rows) throws IOException {
        char[][] grid = new char[rows][];
        for (int r = 0; r < rows; r++) {
            String line = br.readLine().trim();
            grid[r] = line.toCharArray();
        }
        return grid;
    }

    /**
     * Determines whether the supplied grid contains a cycle formed by
     * cells that share the same character.
     *
     * @param rows    number of rows.
     * @param cols    number of columns.
     * @param grid    character grid.
     * @return "Yes" if a cycle exists, otherwise "No".
     */
    private static String solve(int rows, int cols, char[][] grid) {
        boolean[][] visited = new boolean[rows][cols];

        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (!visited[r][c]) {
                    if (hasCycle(grid, visited, r, c, -1, -1, 0)) {
                        return "Yes";
                    }
                }
            }
        }
        return "No";
    }

    /**
     * Detects a cycle reachable from the starting cell (r, c).  The algorithm
     * uses an explicit stack to avoid recursion depth limits.
     *
     * @return {@code true} if a cycle is found.
     */
    private static boolean hasCycle(char[][] grid,
                                    boolean[][] visited,
                                    int startRow,
                                    int startCol,
                                    int parentRow,
                                    int parentCol,
                                    int unusedDirectionIdx) {

        Deque<State> stack = new ArrayDeque<>();
        stack.push(new State(startRow, startCol, parentRow, parentCol));
        visited[startRow][startCol] = true;

        while (!stack.isEmpty()) {
            State current = stack.pop();
            int cr = current.row;
            int cc = current.column;
            int pr = current.parentRow;
            int pc = current.parentColumn;

            for (int i = 0; i < DIRECTIONS.length; i++) {
                int nr = cr + DIRECTIONS[i][0];
                int nc = cc + DIRECTIONS[i][1];

                if (outOfBounds(nr, nc, grid.length, grid[0].length)) {
                    continue;
                }

                if (grid[nr][nc] != grid[cr][cc]) {
                    continue; // different character – not part of the same component
                }

                // Do not go back to the immediate parent cell.
                if (nr == pr && nc == pc) {
                    continue;
                }

                if (visited[nr][nc]) {
                    // Visiting a previously visited cell that is not the parent means a cycle.
                    return true;
                }

                visited[nr][nc] = true;
                stack.push(new State(nr, nc, cr, cc));
            }
        }
        return false;
    }

    /** Simple data holder representing a cell together with its parent cell. */
    private static final class State {
        final int row;
        final int column;
        final int parentRow;
        final int parentColumn;

        State(int row, int column, int parentRow, int parentColumn) {
            this.row = row;
            this.column = column;
            this.parentRow = parentRow;
            this.parentColumn = parentColumn;
        }
    }

    /** Helper for bounds checking of neighbour coordinates. */
    private static boolean outOfBounds(int row, int col, int maxRows, int maxCols) {
        return row < 0 || row >= maxRows || col < 0 || col >= maxCols;
    }
}

