    }

    /** Reads each row of the maze, validating the length of each line. */
    private void readMaze(Scanner sc) {
        for (int r = 0; r < rows; r++) {
            String line = sc.next();
            if (line.length() != cols) {
                throw new IllegalArgumentException(
                        "Row " + (r + 1) + " length differs from declared column count");
            }
            for (int c = 0; c < cols; c++) {
                maze[r][c] = line.charAt(c);
            }
        }
    }

