    private boolean containsSameCharCycle() {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (!visited[r][c] && hasCycleFrom(r, c, -1, -1, maze[r][c])) {
                    return true;  // early exit on first found cycle
                }
            }
        }
        return false;
    }

    /** Depth‑first search that checks for a cycle starting at (r,c). */
    private boolean hasCycleFrom(int r, int c, int prevR, int prevC, char currentChar) {
        visited[r][c] = true;

        for (int[] dir : DIRECTIONS) {
            int nr = r + dir[0];
            int nc = c + dir[1];

            // Do not go back to the cell we just came from.
            if (nr == prevR && nc == prevC) {
                continue;
            }

            if (isInside(nr, nc) && maze[nr][nc] == currentChar) {
                if (visited[nr][nc]) {
                    // Reaching a previously visited cell that isn’t the parent → cycle
                    return true;
                }
                if (hasCycleFrom(nr, nc, r, c, currentChar)) {
                    return true;
                }
            }
        }
        return false;
    }

    /** Helper that checks bounds of a coordinate. */
    private boolean isInside(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }
}

