            for (int c = 0; c < cols; c++) {
                grid[r][c] = line.charAt(c);
                uniqueChars.add(grid[r][c]);
            }
        }
    }

    /**
     * Main processing routine – iterates over each distinct character,
     * builds the corresponding sub‑graph and determines whether a cycle exists.
     *
     * @param out writer for the final answer
     * @throws IOException if an I/O error occurs
     */
    private void process(PrintWriter out) throws IOException {
        boolean cycleFound = false;

        for (Character ch : uniqueChars) {
            buildSubgraph(ch);
            if (adjacency != null && hasCycle()) {
                out.println("Yes");
                return; // answer determined
            }
        }

        out.println("No");
    }

    /**
     * Creates an adjacency list for all cells that contain {@code ch}.
     * Each cell receives a unique id starting from 1.
     */
    private void buildSubgraph(char ch) {
        List<Integer> positions = new ArrayList<>();

        // Assign sequential ids to every occurrence of the character.
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == ch) {
                    int id = positions.size() + 1; // 1‑based ids
                    positions.add(id);
                    charToIds.computeIfAbsent(ch, k -> new ArrayList<>()).add(id);
                }
            }
        }

        int maxId = positions.size();
        @SuppressWarnings("unchecked")
        List<Integer>[] list = new LinkedList[maxId + 1];
        for (int i = 0; i <= maxId; i++) {
            list[i] = new LinkedList<>();
        }
        adjacency = list;

        // Build undirected edges between orthogonal neighbours that also
        // belong to the same character.
        for (int nodeId : positions) {
            int r = ((nodeId - 1) / cols);
            int c = ((nodeId - 1) % cols);
            addNeighbourEdges(r, c, nodeId);
        }
    }

    /**
     * Adds edges to the adjacency list for the cell that holds {@code id}
     * at coordinates {@code (r,c)} if a neighbour also contains the same
     * character.
     */
    private void addNeighbourEdges(int r, int c, int id) {
        for (int dir = 0; dir < DR.length; dir++) {
            int nr = r + DR[dir];
            int nc = c + DC[dir];
            if (!isInBounds(nr, nc)) {
                continue;
            }
            if (grid[nr][nc] != grid[r][c]) {
                continue; // neighbour belongs to a different character
            }
            // Find the linear id of the neighbour (if any)
            for (int neighbourId : charToIds.get(grid[r][c])) {
                // The neighbour lies exactly at (nr,nc)
                if (nr == ((neighbourId - 1) / cols) &&
                    nc == ((neighbourId - 1) % cols)) {
                    adjacency[id].add(neighbourId);
                    adjacency[neighbourId].add(id);
                    break;
                }
            }
        }
    }

    /** @return true if the current adjacency list contains a cycle. */
    private boolean hasCycle() {
        boolean[] visited = new boolean[adjacency.length];
        // START a DFS from every component – the graph may be disconnected.
        for (int v = 1; v < adjacency.length; v++) {
            if (!visited[v]) {
                if (dfs(v, visited, -1)) {
                    return true; // found a cycle in at least one component
                }
            }
        }
        return false;
    }

    /**
     * Depth‑first search that detects a back‑edge (cycle) while ignoring the
     * edge that leads back to the parent node.
     *
     * @param current   node being explored
     * @param visited   flags indicating already processed nodes
     * @param parent    id of the node we arrived from (or -1 for the root)
     * @return true if a cycle is found in the explored subtree
     */
    private boolean dfs(int current, boolean[] visited, int parent) {
        visited[current] = true;
        for (int neighbour : adjacency[current]) {
            if (!visited[neighbour]) {
                if (dfs(neighbour, visited, current)) {
                    return true;
                }
            } else if (neighbour != parent) {
                // Edge to an already visited node that is not the parent -> cycle
                return true;
            }
        }
        return false;
    }

    /** @return true if coordinates are inside the grid. */
    private boolean isInBounds(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }
}

import java.io.*;
import java.util.Arrays;

/**
 * Entry point of the application.
 * The program checks whether the grid contains a cycle of equal characters.
 */
public class Main {

    /* --------------------------------------------------------------------- */
    /*  Fast input utilities – keep original behaviour but with clearer code   */
    /* --------------------------------------------------------------------- */
    private static class FastScanner {
        private final InputStream stream;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        public FastScanner(InputStream stream) {
            this.stream = stream;
        }

        /** Reads the next byte, filling the buffer when necessary. */
        private int readByte() throws IOException {
            if (ptr >= len) {
                len = stream.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        /** Reads the next non‑whitespace token as an {@code int}. */
        int nextInt() throws IOException {
            int c, sign = 1, val = 0;
            do { c = readByte(); } while (c <= ' ');
            if (c == '-') { sign = -1; c = readByte(); }
            do {
                val = val * 10 + (c - '0');
                c = readByte();
            } while (c > ' ');
            return val * sign;
        }

        /** Reads the next token (a word) as {@code String}. */
        String next() throws IOException {
            int c;
            do { c = readByte(); } while (c <= ' ');
            StringBuilder sb = new StringBuilder();
            do {
                sb.append((char) c);
                c = readByte();
            } while (c > ' ');
            return sb.toString();
        }
    }

    /* --------------------------------------------------------------------- */
    /*  Cycle detector – encapsulates all DFS related logic                  */
    /* --------------------------------------------------------------------- */
    private static class CycleDetector {
        private final char[][] grid;
        private final boolean[][] visited;
        private final int rows, cols;
        /** Four orthogonal directions. */
        private static final int[][] DIR = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};

        public CycleDetector(char[][] grid) {
            this.grid = grid;
            this.rows = grid.length;
            this.cols = grid[0].length;
            this.visited = new boolean[rows][cols];
        }

        /** Clears the visited matrix and starts a DFS from (sr, sc). */
        public boolean hasCycleFrom(int sr, int sc) {
            clearVisited();
            visited[sr][sc] = true;
            return dfs(sr, sc, -1, -1, grid[sr][sc]);
        }

        /** Depth‑first search that returns true as soon as a cycle is found. */
        private boolean dfs(int r, int c, int pr, int pc, char ch) {
            for (int[] d : DIR) {
                int nr = r + d[0];
                int nc = c + d[1];
                if (!inside(nr, nc)) continue;
                if (grid[nr][nc] != ch) continue;
                if (nr == pr && nc == pc) continue;          // do not go back to parent
                if (visited[nr][nc]) return true;            // cycle detected
                visited[nr][nc] = true;
                if (dfs(nr, nc, r, c, ch)) return true;
            }
            return false;
        }

        /** Marks the whole visited matrix as false. */
        private void clearVisited() {
            for (boolean[] row : visited) Arrays.fill(row, false);
        }

        /** Checks whether a cell lies inside the grid borders. */
        private boolean inside(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }
    }

    /* --------------------------------------------------------------------- */
    /*  Solver – orchestrates input reading and orchestration of components   */
    /* --------------------------------------------------------------------- */
    private static class Solver {
        private final FastScanner in;
        private final PrintWriter out;

        Solver(FastScanner in, PrintWriter out) {
            this.in = in;
            this.out = out;
        }

        /** Core algorithm entry point. */
        void solve() throws IOException {
            int n = in.nextInt();          // rows
            int m = in.nextInt();          // columns
            char[][] grid = new char[n][];
            for (int i = 0; i < n; i++) {
                grid[i] = in.next().toCharArray();
            }

            CycleDetector detector = new CycleDetector(grid);
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    if (detector.hasCycleFrom(i, j)) {
                        out.println("Yes");
                        return;
                    }
                }
            }
            out.println("No");
        }
    }

    /* --------------------------------------------------------------------- */
    /*  Program entry point – runs the solver on a separate thread          */
    /* --------------------------------------------------------------------- */
    public static void main(String[] args) throws Exception {
        FastScanner scanner = new FastScanner(System.in);
        PrintWriter writer = new PrintWriter(System.out, true);

        // Run the solution in its own thread with a generous stack size.
        new Thread(() -> {
            try {
                new Solver(scanner, writer).solve();
            } catch (Exception e) {
                e.printStackTrace();
            } finally {
                writer.flush();
                writer.close();
            }
        }, "Solution").start();
    }
}

/**
 * Refactored solution for Codeforces 290B – Cycle detection in a grid.
 *
 * The original program performed a depth‑first search (DFS) that tried to find a
 * cycle of length at least four consisting of the same characters.  The
 * refactored version improves readability, separates concerns, uses expressive
 * naming and constants, and implements a clearer cycle‑detection algorithm.
 *
 * Author:  (your name)
 * Created: 2025‑11‑03
 */
public class CF290B {

    /* ------------------------------------------------------------------ */
    /*  Constants – movement directions                                    */
    /* ------------------------------------------------------------------ */
    private static final int[] DX = {-1, 1, 0, 0};
    private static final int[] DY = {0, 0, -1, 1};

    /* ------------------------------------------------------------------ */
    /*  Fields used during the computation                                  */
    /* ------------------------------------------------------------------ */
    private final char[][] grid;          // input character matrix
    private final boolean[][] visited;    // permanently visited cells
    private final int rows, cols;         // grid dimensions

    /* ------------------------------------------------------------------ */
    /*  Constructor                                                         */
    /* ------------------------------------------------------------------ */
    public CF290B(char[][] grid) {
        this.grid = grid;
        this.rows = grid.length;
        this.cols = grid[0].length;
        this.visited = new boolean[rows][cols];
    }

    /* ------------------------------------------------------------------ */
    /*  Public entry point – does a cycle exist?                           */
    /* ------------------------------------------------------------------ */
    public boolean hasCycle() {
        for (int r = 0; r < rows; ++r) {
            for (int c = 0; c < cols; ++c) {
                if (!visited[r][c]) {
                    if (dfs(r, c, -1, -1, 0)) {
                        return true;                 // a qualifying cycle found
                    }
                }
            }
        }
        return false;                               // no cycle discovered
    }

    /**
     * Depth‑first search that looks for a cycle.
     *
     * @param sr        current row
     * @param sc        current column
     * @param pr        previous row (or –1 if none)
     * @param pc        previous column (or –1 if none)
     * @param length    length of the current path (including the start cell)
     * @return true if a cycle of length ≥ 4 is discovered
     */
    private boolean dfs(int sr, int sc, int pr, int pc, int length) {
        visited[sr][sc] = true;                     // mark this cell as visited

        for (int dir = 0; dir < 4; ++dir) {
            int nr = sr + DX[dir];
            int nc = sc + DY[dir];

            if (!inside(nr, nc)) {                  // out of bounds?
                continue;
            }
            if (grid[nr][nc] != grid[sr][sc]) {     // different character?
                continue;
            }
            if (nr == pr && nc == pc) {             // step back to the parent?
                continue;                         // ignore the edge we came from
            }

            if (visited[nr][nc]) {                  // we reached a previously visited node → cycle!
                // By construction we only start a DFS once length >= 1,
                // therefore a back‑edge necessarily forms a cycle of at least 4 cells.
                return true;
            }

            if (dfs(nr, nc, sr, sc, length + 1)) { // recurse
                return true;
            }
        }
        return false;                               // no cycle found from this branch
    }

    /** Helper – checks whether a cell is inside the grid. */
    private boolean inside(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    /* ------------------------------------------------------------------ */
    /*  I/O utilities – fast scanner and writer                             */
    /* ------------------------------------------------------------------ */
    private static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner(InputStream stream) {
            this.br = new BufferedReader(new InputStreamReader(stream));
        }

        /** Returns the next non‑empty token. */
        private String token() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                String line = br.readLine();
                if (line == null) {
                    return null;
                }
                st = new StringTokenizer(line);
            }
            return st.nextToken();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(token());
        }

        /** Reads a grid of characters with the given number of rows. */
        char[][] nextGrid(int rows) throws IOException {
            char[][] grid = new char[rows][];
            for (int i = 0; i < rows; ++i) {
                String line = token();
                grid[i] = line.toCharArray();
            }
            return grid;
        }
    }

    /* ------------------------------------------------------------------ */
    /*  Main method – orchestrates input, processing and output            */
    /* ------------------------------------------------------------------ */
    public static void main(String[] args) throws Exception {
        try (FastScanner fs = new FastScanner(System.in)) {
            int n = fs.nextInt();          // number of rows
            int m = fs.nextInt();          // number of columns

            char[][] board = fs.nextGrid(n);
            CF290B solver = new CF290B(board);

            System.out.println(solver.hasCycle() ? "Yes" : "No");
        }
    }
}

import java.io.*;
import java.util.StringTokenizer;

/**
 * Detects whether a grid contains a cycle formed by at least four
 * connected cells having the same character.
 *
 * The original competitive‑programming template has been refactored
 * to improve readability, naming, constants and separation of concerns.
 */
public class CF510B {

    /* ---------- constants ---------- */
    private static final long MOD = 1_000_000_007L;   // not used in this solution but kept for compatibility
    private static final int[] DX = {-1, 1, 0, 0};
    private static final int[] DY = {0, 0, -1, 1};

    /* ---------- fields ---------- */
    private final FastScanner fs;   // fast scanner wrapper
    private final PrintWriter out;  // output writer

    /* ---------- constructor ---------- */
    public CF510B() throws IOException {
        this.fs = new FastScanner(System.in);
        this.out = new PrintWriter(System.out);
        solve();
        out.close();
    }

    /* ---------- entry point ---------- */
    public static void main(String[] args) throws IOException {
        new CF510B();
    }

    /* ---------- core algorithm ---------- */
    private void solve() {
        int n = fs.nextInt();
        int m = fs.nextInt();
        char[][] grid = readGrid(n);
        boolean[][] visited = new boolean[n][m];

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (!visited[i][j]) {
                    if (hasCycle(i, j, -1, -1, grid[i][j], grid, visited)) {
                        out.println("Yes");
                        return;
                    }
                }
            }
        }
        out.println("No");
    }

    /**
     * Depth‑first search that looks for a cycle of cells sharing the same
     * character.  The method returns {@code true} as soon as a cycle is found.
     *
     * @param x            current row
     * @param y            current column
     * @param fromX        row of the cell we came from, or {@code -1}
     * @param fromY        column of the cell we came from, or {@code -1}
     * @param colour       character we are exploring
     * @param grid         the whole grid
     * @param visited      visited flag matrix
     * @return {@code true} if a cycle exists in the current component
     */
    private boolean hasCycle(int x, int y, int fromX, int fromY,
                             char colour, char[][] grid, boolean[][] visited) {
        visited[x][y] = true;

        for (int dir = 0; dir < DX.length; dir++) {
            int nx = x + DX[dir];
            int ny = y + DY[dir];

            // 1️⃣ bounds
            if (outOfBounds(nx, grid.length, ny, grid[0].length)) {
                continue;
            }
            // 2️⃣ colour mismatch
            if (grid[nx][ny] != colour) {
                continue;
            }
            // 3️⃣ don't step back to the parent cell
            if (nx == fromX && ny == fromY) {
                continue;
            }
            // 4️⃣ visited cell → cycle detected
            if (visited[nx][ny]) {
                return true;
            }
            // 5️⃣ recurse deeper
            if (hasCycle(nx, ny, x, y, colour, grid, visited)) {
                return true;
            }
        }
        return false; // no cycle found in this branch
    }

    /* ---------- utility methods ---------- */
    private static boolean outOfBounds(int x, int maxX, int y, int maxY) {
        return x < 0 || x >= maxX || y < 0 || y >= maxY;
    }

    /** Reads the whole grid from the scanner. */
    private static char[][] readGrid(int n) throws IOException {
        char[][] grid = new char[n][];
        for (int i = 0; i < n; i++) {
            grid[i] = fs.nextString().toCharArray();
        }
        return grid;
    }

    /* ---------- fast scanner ----------
     * A compact replacement for the original hand‑rolled tokenizer.
     */
    private static final class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner(InputStream stream) {
            this.br = new BufferedReader(new InputStreamReader(stream));
        }

        /** Returns the next non‑empty token. */
        private String nextToken() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    throw new UncheckedIOException(e);
                }
            }
            return st.nextToken();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(nextToken());
        }

        long nextLong() throws IOException {
            return Long.parseLong(nextToken());
        }

        /** Reads a whole line (used for grid rows). */
        String nextString() throws IOException {
            return br.readLine();
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.Arrays;

/**
 * Detects whether a grid contains a cycle of at least 4 cells that all have the same
 * character.  The implementation is deliberately kept small, readable and
 * maintainable – all “static‑sprawl” has been removed, method responsibilities are
 * clearly separated and meaningful names are used throughout.
 */
public class WordSearchCycleDetector {

    /* --------------------------------------------------------------
     *  Constants & direction helpers
     * -------------------------------------------------------------- */
    private static final int[] DX = {0, 0, -1, 1};
    private static final int[] DY = {-1, 1, 0, 0};

    /** Checks whether a coordinate lies inside the board. */
    private boolean isInBounds(int x, int y, char[][] board) {
        return x >= 0 && x < board.length && y >= 0 && y < board[0].length;
    }

    /** Validates that a neighbour cell contains the same character we are exploring. */
    private boolean isSameChar(char neighbourChar, char targetChar) {
        return neighbourChar == targetChar;
    }

    /* --------------------------------------------------------------
     *  Core data holder for a DFS node
     * -------------------------------------------------------------- */
    /**
     * Simple immutable container that stores a cell’s coordinates and the
     * distance (number of steps) taken to reach it from the start of the current
     * search chain.
     */
    private static final class Cell {
        final int x;
        final int y;
        final int distance;

        Cell(int x, int y, int distance) {
            this.x = x;
            this.y = y;
            this.distance = distance;
        }
    }

    /* --------------------------------------------------------------
     *  Public API
     * -------------------------------------------------------------- */
    /**
     * Entry point used by {@code main}.  Returns {@code true} if a cycle of
     * length ≥ 4 exists anywhere on the board.
     */
    public boolean hasCycleOfLengthAtLeastFour(char[][] board) {
        this.board = board;
        this.visited = new boolean[board.length][board[0].length];
        this.found = false;

        for (int i = 0; !found && i < board.length; i++) {
            for (int j = 0; !found && j < board[i].length; j++) {
                if (!visited[i][j]) {
                    dfs(i, j, board[i][j], new Cell(i, j, 0), -1, -1);
                }
            }
        }
        return found;
    }

    /* --------------------------------------------------------------
     *  Depth‑first search implementation
     * -------------------------------------------------------------- */
    /**
     * Recursively explores all reachable cells that share the same character.
     *
     * @param x          current row index
     * @param y          current column index
     * @param ch         character currently being explored
     * @param cur        cell representing the node we are visiting now
     * @param fromX      row of the caller (or –1 for the root)
     * @param fromY      column of the caller (or –1 for the root)
     */
    private void dfs(int x, int y, char ch, Cell cur, int fromX, int fromY) {
        visited[x][y] = true;

        for (int dir = 0; dir < DX.length && !found; dir++) {
            int nx = x + DX[dir];
            int ny = y + DY[dir];

            // 1️⃣  Bounds & character check
            if (!isInBounds(nx, ny, board) || !isSameChar(board[nx][ny], ch)) {
                continue;
            }

            // 2️⃣  Not visited yet → continue recursion
            if (!visited[nx][ny]) {
                dfs(nx, ny, ch, new Cell(nx, ny, cur.distance + 1), x, y);
                if (found) {
                    return;               // early exit – we already have a valid cycle
                }
                continue;
            }

            // 3️⃣  Already visited – this forms a cycle.
            //    The cycle length is guaranteed to be at least (cur.distance + 1).
            //    We only accept cycles of length ≥ 4.
            if (cur.distance >= 3) {
                found = true;
            }
        }
    }

    /* --------------------------------------------------------------
     *  Program entry point – handles I/O cleanly
     * -------------------------------------------------------------- */
    public static void main(String[] args) throws IOException {
        /* Use BufferedReader + try‑with‑resources to guarantee proper closure. */
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in))) {
            /* First line contains the board dimensions. */
            String[] dims = br.readLine().trim().split("\\s+");
            int n = Integer.parseInt(dims[0]);
            int m = Integer.parseInt(dims[1]);

            /* Remaining lines hold the board itself. */
            char[][] board = new char[n][m];
            for (int i = 0; i < n; i++) {
                String line = br.readLine().trim();
                // Defensive copy – makes the intent explicit.
                Arrays.fill(board[i], ' ');
                for (int j = 0; j < m; j++) {
                    board[i][j] = line.charAt(j);
                }
            }

            /* Instantiate the solver and print the result. */
            WordSearchCycleDetector solver = new WordSearchCycleDetector(board);
            System.out.println(solver.hasCycleOfLengthAtLeastFour() ? "Yes" : "No");
        }
    }
}

