                solve(scanner, out);
            }
        }
    }

    /** Core algorithm: scan the grid and launch DFS from each unvisited cell. */
    private static void solve(FastScanner sc, PrintWriter out) {
        int rows = sc.nextInt();
        int cols = sc.nextInt();

        char[][] grid = new char[rows][];
        boolean[][] visited = new boolean[rows][cols];

        for (int r = 0; r < rows; ++r) {
            grid[r] = sc.readLine().trim().toCharArray();
        }

        // Check every cell; stop as soon as a cycle is discovered.
        for (int r = 0; r < rows; ++r) {
            for (int c = 0; c < cols; ++c) {
                if (!visited[r][c]) {
                    if (hasCycle(r, c, -1, -1, grid, visited)) {
                        out.println("Yes");
                        return;
                    }
                }
            }
        }
        out.println("No");
    }

    /**
     * Depth‑first search that returns {@code true} if a cycle of the same
     * character is found starting from (x, y).  {@code prevX, prevY} denotes the
     * cell we came from (or {@code -1,-1} for the root).
     */
    private static boolean hasCycle(int x, int y, int prevX, int prevY,
                                    char[][] grid, boolean[][] visited) {
        visited[x][y] = true;
        char curChar = grid[x][y];

        for (int[] dir : DIRS) {
            int nx = x + dir[0];
            int ny = y + dir[1];

            // Bounds check.
            if (!inBounds(nx, ny, grid)) {
                continue;
            }

            char nextChar = grid[nx][ny];
            if (nextChar != curChar) {
                continue; // different characters cannot belong to the same cycle
            }

            // Do not immediately return to the previous cell.
            if (nx == prevX && ny == prevY) {
                continue;
            }

            if (visited[nx][ny]) {
                // Visited neighbour that is not the immediate parent → cycle detected.
                return true;
            }

            if (hasCycle(nx, ny, x, y, grid, visited)) {
                return true;
            }
        }
        return false;
    }

    /** Helper that checks whether a coordinate lies inside the grid. */
    private static boolean inBounds(int x, int y, char[][] grid) {
        return x >= 0 && x < grid.length && y >= 0 && y < grid[0].length;
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.Arrays;

/**
 * Reads a grid of characters and determines whether a cycle appears
 * among vertices that share the same label.  Vertices are connected
 * according to the original specification (right and down neighbours)
 * but the logic has been clarified and expressed with meaningful names.
 */
public class Foxdots {

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));

        // -----------------------------------------------------------------
        // 1️⃣  Parse dimensions and the grid itself
        // -----------------------------------------------------------------
        String[] dim = br.readLine().split("\\s+");
        int rows = Integer.parseInt(dim[0]);
        int cols = Integer.parseInt(dim[1]);

        char[][] grid = new char[rows][cols];
        for (int r = 0; r < rows; r++) {
            String line = br.readLine();
            // the original code assumes exactly `cols` characters per line
            for (int c = 0; c < cols; c++) {
                grid[r][c] = line.charAt(c);
            }
        }

        // -----------------------------------------------------------------
        // 2️⃣  Build a Union‑Find structure for the whole grid
        // -----------------------------------------------------------------
        int totalVertices = rows * cols;
        UnionFind uf = new UnionFind(totalVertices);

        boolean cycleDetected = false;

        // -----------------------------------------------------------------
        // 3️⃣  Create edges (right‑ and down‑neighbour) and try to union
        // -----------------------------------------------------------------
        for (int idx = 0; idx < totalVertices; idx++) {
            int row = idx / cols;      // logical row in the grid
            int col = idx % cols;      // logical column in the grid

            // ── edge to the right (idx + 1) ───────────────────────────────────
            if (col + 1 < cols) {
                int neighbourIdx = idx + 1;
                if (sameLabel(grid, idx, neighbourIdx)) {
                    if (uf.union(idx, neighbourIdx)) {
                        cycleDetected = true;          // a cycle was found
                        break;
                    }
                }
            }

            // ── edge downward (idx + cols) ─────────────────────────────────────
            int downIdx = idx + cols;
            if (downIdx < totalVertices) {
                if (sameLabel(grid, idx, downIdx)) {
                    if (uf.union(idx, downIdx)) {
                        cycleDetected = true;
                        break;
                    }
                }
            }
        }

        // -----------------------------------------------------------------
        // 4️⃣  Output the result
        // -----------------------------------------------------------------
        System.out.println(cycleDetected ? "Yes" : "No");
    }

    /** Utility that checks whether two linear indices refer to vertices
     *  that carry the same character label. */
    private static boolean sameLabel(char[][] grid, int idx1, int idx2) {
        int r1 = idx1 / grid.length;
        int c1 = idx1 % grid.length;
        int r2 = idx2 / grid.length;
        int c2 = idx2 % grid.length;
        return grid[r1][c1] == grid[r2][c2];
    }
}

/**
 * Simple Union‑Find (Disjoint Set Union) implementation that can tell
 * whether a {@code union} operation closes a cycle.
 *
 * <p>Design goals:
 * <ul>
 *   <li>Path compression and union‑by‑rank for near‑constant amortised time.</li>
 *   <li>Method {@code union} returns {@code true} when the two
 *       arguments already belong to the same set – i.e. a cycle was formed.</li>
 * </ul>
 */
class UnionFind {
    private final int[] parent;   // parent[i] points to the representative of i
    private final int[] rank;     // tree height approximation

    public UnionFind(int size) {
        parent = new int[size];
        rank   = new int[size];
        // each element starts as its own root
        Arrays.fill(parent, -1);   // negative value = root with size = 1
        // rank left untouched (starts at 0)
    }

    /** Find the representative of {@code x} with path compression. */
    private int find(int x) {
        int root = x;
        // locate the root (negative = root)
        while (parent[root] >= 0) {
            root = parent[root];
        }

        // Path compression – make every visited node point directly to the root
        int cur = x;
        while (cur != root) {
            int next = parent[cur];
            parent[cur] = root;
            cur = next;
        }
        return root;
    }

    /**
     * Attempts to merge the sets of {@code x} and {@code y}.
     *
     * @return {@code true} if {@code x} and {@code y} were already in the same set
     *         (i.e. a cycle would be created); otherwise {@code false} and the
     *         merge is performed.
     */
    public boolean union(int x, int y) {
        int rx = find(x);
        int ry = find(y);
        if (rx == ry) {
            // Already connected → a cycle is discovered
            return true;
        }

        // Union by rank
        if (rank[rx] < rank[ry]) {
            parent[rx] = ry;
        } else if (rank[rx] > rank[ry]) {
            parent[ry] = rx;
        } else {
            parent[ry] = rx;
            rank[rx]++;
        }
        return false;
    }
}

import java.io.*;
import java.util.*;

public class Main {

    private static final int[] DX = {1, -1, 0, 0};
    private static final int[] DY = {0, 0, 1, -1};

    /**
     * Entry point – reads the grid, searches for a cycle of length ≥ 4
     * composed of the same character, and prints "Yes" or "No".
     */
    public static void main(String[] args) throws IOException {
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in))) {
            String[] header = br.readLine().split("\\s+");
            int rows = Integer.parseInt(header[0]);
            int cols = Integer.parseInt(header[1]);

            char[][] grid = new char[rows][cols];
            for (int i = 0; i < rows; i++) {
                String line = br.readLine();
                if (line == null) break;
                for (int j = 0; j < cols; j++) {
                    grid[i][j] = line.charAt(j);
                }
            }

            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    boolean[][] visited = new boolean[rows][cols];
                    if (hasCycle(grid, visited, i, j, i, j, 1, grid[i][j])) {
                        System.out.print("Yes");
                        return;
                    }
                }
            }
            System.out.print("No");
        }
    }

    /**
     * Depth‑first search that looks for a cycle starting and ending at
     * (startX,startY) using the same character as grid[startX][startY].
     *
     * @return true if such a cycle exists, false otherwise.
     */
    private static boolean hasCycle(char[][] grid,
                                    boolean[][] visited,
                                    int x,
                                    int y,
                                    int startX,
                                    int startY,
                                    int count,
                                    char targetChar) {
        // A valid cycle is found when we return to the start cell after
        // at least four steps (count ≥ 4).
        if (count >= 4 && x == startX && y == startY) {
            return true;
        }

        visited[x][y] = true;

        for (int dir = 0; dir < DX.length; dir++) {
            int nx = x + DX[dir];
            int ny = y + DY[dir];
            if (isInside(grid, nx, ny) && !visited[nx][ny] && grid[nx][ny] == targetChar) {
                if (hasCycle(grid, visited, nx, ny, startX, startY, count + 1, targetChar)) {
                    return true;
                }
            }
        }
        return false;
    }

    /** Utility to check whether (x, y) lies inside the grid boundaries. */
    private static boolean isInside(char[][] grid, int x, int y) {
        return x >= 0 && x < grid.length && y >= 0 && y < grid[0].length;
    }
}

import java.io.*;
import java.util.*;

public class B {

    // -----------------------------------------------------------------------
    // Constants
    // -----------------------------------------------------------------------
    private static final int MIN_CYCLE_LENGTH = 4;   // required minimum cycle size

    // -----------------------------------------------------------------------
    // Simple token‑based input helper (mirrors the original `In` class)
    // -----------------------------------------------------------------------
    private static final class In {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;   // current token source

        In(BufferedReader reader) {
            this.reader = reader;
        }

        /** Fill the tokenizer with the next line of input. */
        private void fill() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                String line = reader.readLine();
                if (line == null) {
                    tokenizer = null;
                    return;
                }
                tokenizer = new StringTokenizer(line);
            }
        }

        /** Returns the next lexical token. */
        String nextString() throws IOException {
            if (!tokenizer.hasMoreTokens()) {
                fill();
            }
            return tokenizer.nextToken();
        }

        /** Convenience wrappers for primitive types. */
        int nextInt() throws IOException {
            return Integer.parseInt(nextString());
        }

        long nextLong() throws IOException {
            return Long.parseLong(nextString());
        }

        double nextDouble() throws IOException {
            return Double.parseDouble(nextString());
        }
    }

    // -----------------------------------------------------------------------
    // Core algorithm
    // -----------------------------------------------------------------------
    public static void solution(BufferedReader reader, PrintWriter out) throws IOException {
        try (In in = new In(reader)) {
            int rows = in.nextInt();
            int cols = in.nextInt();

            char[][] grid = new char[rows][];
            for (int r = 0; r < rows; ++r) {
                grid[r] = in.nextString().toCharArray();
            }

            boolean[][] processed = new boolean[rows][cols];   // globally visited cells
            int[][] discovery = new int[rows][cols];           // DFS entry depth
            final int[][] DIRS = {{0, 1}, {1, 0}, {0, -1}, {-1, 0}};

            for (int r = 0; r < rows; ++r) {
                for (int c = 0; c < cols; ++c) {
                    if (!processed[r][c]) {
                        if (hasCycle(grid, processed, discovery, DIRS, r, c, -1, -1, 1, grid[r][c])) {
                            out.println("Yes");
                            return;
                        }
                    }
                }
            }
            out.println("No");
        }
    }

    /**
     * Depth‑first search that searches for a cycle of at least {@value MIN_CYCLE_LENGTH}
     * edges made of the same character.
     *
     * @return {@code true} if such a cycle is discovered starting from (r,c)
     */
    private static boolean hasCycle(char[][] grid,
                                    boolean[][] processed,
                                    int[][] discovery,
                                    int[][] dirs,
                                    int r, int c,
                                    int pr, int pc,
                                    int depth,
                                    char targetChar) {
        processed[r][c] = true;

        // Record the depth of the first visit of this cell in the current DFS tree.
        if (discovery[r][c] == 0) {
            discovery[r][c] = depth;
        }

        for (int[] d : dirs) {
            int nr = r + d[0];
            int nc = c + d[1];

            // Do not go back to the parent cell.
            if (nr == pr && nc == pc) {
                continue;
            }
            // Stay inside the grid.
            if (nr < 0 || nr >= grid.length || nc < 0 || nc >= grid[0].length) {
                continue;
            }
            // Continue only along cells that share the same character.
            if (grid[nr][nc] != targetChar) {
                continue;
            }

            // If the neighbour has already been discovered in this DFS tree,
            // a cycle exists.  The length of the cycle is the difference of depths.
            if (discovery[nr][nc] != 0) {
                if (depth - discovery[nr][nc] >= MIN_CYCLE_LENGTH) {
                    return true;
                }
                continue;
            }

            // Recurse deeper.
            if (hasCycle(grid, processed, discovery, dirs,
                    nr, nc, r, c, depth + 1, targetChar)) {
                return true;
            }
        }

        // Backtrack: allow the cell to be reused for other components.
        discovery[r][c] = 0;
        return false;
    }

    // -----------------------------------------------------------------------
    // Application entry point
    // -----------------------------------------------------------------------
    public static void main(String[] args) throws Exception {
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in))) {
            PrintWriter pw = new PrintWriter(new BufferedWriter(
                    new OutputStreamWriter(System.out)));
            solution(br, pw);
            pw.close();
        }
    }
}

import java.io.*;
import java.util.*;

public class Main {

    /** Entry point – uses try‑with‑resources to guarantee stream closure */
    public static void main(String[] args) {
        try (InputStream in = System.in;
             OutputStream out = System.out) {

            InputReader reader = new InputReader(in);
            PrintWriter writer = new PrintWriter(out);
            new TaskC().solve(reader, writer);
            writer.flush();
        }
    }

    /** TaskC implements the algorithm that checks for cycles on the grid */
    static class TaskC {

        /** Four movement directions: down, up, right, left */
        private static final int[] DX = {1, -1, 0, 0};
        private static final int[] DY = {0, 0, 1, -1};

        /** Main driver – reads input, runs the search and prints the result */
        public void solve(InputReader reader, PrintWriter writer) {
            int rows = reader.nextInt();
            int cols = reader.nextInt();
            char[][] grid = new char[rows][cols];

            /* ----- read the grid ----- */
            for (int i = 0; i < rows; i++) {
                String line = reader.next();
                for (int j = 0; j < cols; j++) {
                    grid[i][j] = line.charAt(j);
                }
            }

            boolean[][] visited = new boolean[rows][cols];

            /* ----- search for any cycle ----- */
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (!visited[i][j] && hasCycle(grid, visited, i, j, -1, -1)) {
                        writer.println("Yes");
                        return;
                    }
                }
            }
            writer.println("No");
        }

        /**
         * Recursive depth‑first search that looks for a cycle.
         *
         * @param grid     the character grid
         * @param visited  permanently visited cells
         * @param x        current row
         * @param y        current column
         * @param fromX    row of the cell we arrived from (or -1,-1 for the start)
         * @param fromY    column of the cell we arrived from
         * @return true if a cycle exists, false otherwise
         */
        private boolean hasCycle(char[][] grid, boolean[][] visited, int x, int y,
                                 int fromX, int fromY) {
            // out‑of‑bounds guard
            if (x < 0 || y < 0 || x >= grid.length || y >= grid[0].length) {
                return false;
            }

            // Already visited → a cycle is found unless it is the parent cell
            if (visited[x][y]) {
                return !(fromX == x && fromY == y);
            }

            visited[x][y] = true;
            char current = grid[x][y];

            /* ----- explore neighbours ----- */
            for (int d = 0; d < 4; d++) {
                int nx = x + DX[d];
                int ny = y + DY[d];

                // Skip the cell we came from
                if (nx == fromX && ny == fromY) {
                    continue;
                }

                // Boundary check before accessing the array
                if (nx < 0 || ny < 0 || nx >= grid.length || ny >= grid[0].length) {
                    continue;
                }

                // Continue only along cells with the same character
                if (grid[nx][ny] != current) {
                    continue;
                }

                // Recurse; if any recursive call reports a cycle, propagate true
                if (hasCycle(grid, visited, nx, ny, x, y)) {
                    return true;
                }
            }
            return false;
        }
    }

    /** Fast input scanner */
    static class InputReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        InputReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream, 32768));
        }

        /** Returns the next token from the input stream */
        String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        /** Convenience wrapper for reading an int */
        int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.io.*;
import java.util.*;

public class Main {

    /** Wrapper around BufferedReader that supplies simple tokenised input. */
    private static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner(InputStream source) {
            br = new BufferedReader(new InputStreamReader(source));
        }

        /** Returns the next non‑empty token or {@code null} if EOF is reached. */
        private String nextToken() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                String line = br.readLine();
                if (line == null || line.isEmpty()) {
                    return null;
                }
                st = new StringTokenizer(line);
            }
            return st.nextToken();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(nextToken());
        }

        String next() throws IOException {
            return nextToken();
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);

        int rows = fs.nextInt();
        int cols = fs.nextInt();

        char[][] grid = new char[rows][cols];
        for (int i = 0; i < rows; i++) {
            String line = fs.next();
            for (int j = 0; j < cols; j++) {
                grid[i][j] = line.charAt(j);
            }
        }

        /* Try every cell as a possible start of a cycle */
        for (int startR = 0; startR < rows; startR++) {
            for (int startC = 0; startC < cols; startC++) {
                char targetChar = grid[startR][startC];
                boolean[][] visited = new boolean[rows][cols];

                if (depthFirstSearch(grid, targetChar, startR, startC,
                                     targetChar, 1, startR, startC, visited)) {
                    System.out.println("Yes");
                    return;
                }

                /* Reset visited for the next start cell */
                for (boolean[] row : visited) {
                    Arrays.fill(row, false);
                }
            }
        }

        System.out.println("No");
    }

    /**
     * Depth‑first search that looks for a closed walk returning to the start
     * cell after at least four steps.  The method follows the same logic as
     * the original program but with clearer parameter passing and naming.
     *
     * @return {@code true} if such a walk exists starting from the given cell.
     */
    private static boolean depthFirstSearch(char[][] grid, char target,
                                            int curR, int curC,
                                            char startChar, int step,
                                            int startR, int startC,
                                            boolean[][] visited) {
        /* Out of bounds or wrong character – dead end */
        if (curR < 0 || curR >= grid.length || curC < 0 || curC >= grid[0].length) {
            return false;
        }
        if (grid[curR][curC] != target) {
            return false;
        }

        /* If we have returned to the start cell and have taken enough steps,
         * a valid cycle has been found.  The visited flag must already be set
         * (meaning we arrived here from a deeper recursion level). */
        if (curR == startR && curC == startC) {
            return step >= 4 && visited[curR][curC];
        }

        /* Already visited cells cannot be reused on the current path */
        if (visited[curR][curC]) {
            return false;
        }

        visited[curR][curC] = true;

        /* Explore the four orthogonal neighbours */
        int[][] directions = {{0, 1}, {0, -1}, {1, 0}, {-1, 0}};
        for (int[] d : directions) {
            int nextR = curR + d[0];
            int nextC = curC + d[1];
            if (depthFirstSearch(grid, target, nextR, nextC,
                                 startChar, step + 1, startR, startC, visited)) {
                return true;
            }
        }

        return false;
    }
}

import java.io.*;
import java.util.*;

/**
 * Solution for the “Fox and Two Dots” problem – detects a cycle of at least
 * four same‑colored cells in a grid.
 *
 * The implementation is deliberately split into small, focused methods
 * and uses sensible naming throughout to improve readability and maintainability.
 */
public class FoxAndTwoDots {

    /** Simple scanner that works with BufferedReader and StringTokenizer. */
    private static final class FastScanner {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        FastScanner(BufferedReader reader) {
            this.reader = reader;
        }

        /** Guarantees that a tokenizer is ready; reads a new line when empty. */
        private void ensureTokenizer() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                String line = reader.readLine();
                if (line == null) {
                    return;                     // EOF
                }
                tokenizer = new StringTokenizer(line);
            }
        }

        String nextToken() throws IOException {
            ensureTokenizer();
            return tokenizer.nextToken();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(nextToken());
        }

        long nextLong() throws IOException {
            return Long.parseLong(nextToken());
        }

        double nextDouble() throws IOException {
            return Double.parseDouble(nextToken());
        }
    }

    /** Holds the state needed for the algorithm. */
    private char[][] board;
    private List<Integer>[] adjacency;      // adjacency list for the virtual graph
    private boolean[] visited;               // discovery flag
    private boolean[] finished;              // processing‑complete flag
    private final FastScanner scanner;
    private final PrintWriter printer;

    /** Constructs the solver with the given I/O streams. */
    FoxAndTwoDots(FastScanner scanner, PrintWriter printer) {
        this.scanner = scanner;
        this.printer = printer;
    }

    /** Entry point – reads input, builds the graph and reports the answer. */
    void solve() {
        readBoard();
        buildAdjacencyGraph();
        printer.println(containsCycle() ? "Yes" : "No");
    }

    /** Parses the dimensions and the board from the scanner. */
    private void readBoard() {
        int rows = scanner.nextInt();
        int cols = scanner.nextInt();
        board = new char[rows][];
        for (int r = 0; r < rows; r++) {
            String line = scanner.nextToken();
            board[r] = line.toCharArray();
            if (board[r].length != cols) {
                throw new IllegalArgumentException("Row length does not match declared column count.");
            }
        }
    }

    /** Constructs an undirected adjacency list where neighbours share the same colour. */
    private void buildAdjacencyGraph() {
        final int vertices = board.length * board[0].length;
        adjacency = new ArrayList[vertices];
        for (int i = 0; i < vertices; i++) {
            adjacency[i] = new ArrayList<>();
        }

        // Traverse the board and connect same‑colored neighbours (up & left only)
        for (int r = 0; r < board.length; r++) {
            for (int c = 0; c < board[r].length; c++) {
                int u = toIndex(r, c);
                // upward neighbour
                if (r > 0 && board[r][c] == board[r - 1][c]) {
                    int v = toIndex(r - 1, c);
                    addUndirectedEdge(u, v);
                }
                // left neighbour
                if (c > 0 && board[r][c] == board[r][c - 1]) {
                    int v = toIndex(r, c - 1);
                    addUndirectedEdge(u, v);
                }
            }
        }
    }

    /** Adds a bidirectional edge to the virtual graph. */
    private void addUndirectedEdge(int a, int b) {
        adjacency[a].add(b);
        adjacency[b].add(a);
    }

    /** Linear index conversion (row‑major). */
    private int toIndex(int row, int col) {
        return row * board[0].length + col;
    }

    /** Detects whether any cycle of length ≥ 4 composed of equal colours exists. */
    private boolean containsCycle() {
        final int size = board.length * board[0].length;
        visited = new boolean[size];
        finished = new boolean[size];

        for (int r = 0; r < board.length; r++) {
            for (int c = 0; c < board[r].length; c++) {
                int node = toIndex(r, c);
                if (!visited[node] && dfs(node, -1)) {
                    return true;               // a qualifying cycle was found
                }
            }
        }
        return false;
    }

    /**
     * Depth‑first search that returns {@code true} if a cycle is discovered
     * reachable from {@code current} (excluding the {@code parent} edge).
     *
     * @param current vertex being explored
     * @param parent  identifier of the vertex we came from (or -1 for the root)
     * @return {@code true} if a suitable cycle exists in this component
     */
    private boolean dfs(int current, int parent) {
        visited[current] = true;

        for (int neighbour : adjacency[current]) {
            if (neighbour == parent) {
                continue;                     // ignore the edge we just traversed
            }
            if (!visited[neighbour]) {
                if (dfs(neighbour, current)) {
                    return true;               // propagate cycle detection upwards
                }
            } else if (!finished[neighbour]) {
                // Back‑edge to a visited but not yet finished vertex → cycle
                return true;
            }
        }
        finished[current] = true;
        return false;
    }

    /** Launches the solution using standard input/output streams. */
    public static void main(String[] args) throws Exception {
        try (FastScanner scanner = new FastScanner(
                new BufferedReader(new InputStreamReader(System.in))) {
            // The outer try‑with‑resources ensures the PrintWriter is closed properly.
            try (PrintWriter out = new PrintWriter(System.out)) {
                new FoxAndTwoDots(scanner, out).solve();
            }
        }
    }
}

/**
 * cf510B – Detect a cycle of equal adjacent characters.
 *
 * The program reads a grid of characters, assigns a unique index to each cell,
 * and performs a breadth‑first search from every unvisited cell. While walking
 * through the grid it never steps back to the cell we just came from.
 * Encountering a cell that has already been visited during such a walk means a
 * cycle exists and the program prints “Yes”. If no cycle is found the program
 * prints “No”.
 *
 * The original source was hard to follow.  The refactor improves readability,
 * separates concerns, uses expressive names, and follows common Java conventions.
 */
public class cf510B {

    /** Simple container that stores a cell index together with the index we arrived from. */
    private static final class Pair {
        /** Index of the current cell (row * cols + col). */
        final int current;
        /** Index of the previous cell; -1 when we are at the start. */
        final int previous;

        Pair(int current, int previous) {
            this.current = current;
            this.previous = previous;
        }
    }

    /** Directions used when exploring neighbours (up, down, left, right). */
    private enum Direction {
        UP(-1, 0),
        DOWN(1, 0),
        LEFT(0, -1),
        RIGHT(0, 1);

        private final int rowDelta;
        private final int colDelta;

        Direction(int rowDelta, int colDelta) {
            this.rowDelta = rowDelta;
            this.colDelta = colDelta;
        }

        /** Returns the neighbour coordinates of the given cell. */
        void offset(int row, int col, int[] out) {
            out[0] = row + rowDelta;
            out[1] = col + colDelta;
        }
    }

    /** Fast scanner that works with the original InputStream‑based implementation. */
    private static final class InputReader {
        private final byte[] buf = new byte[1024];
        private int curChar;
        private int numChars;
        private final InputStream stream;
        private final BufferedReader br;

        InputReader(InputStream stream) {
            this.stream = stream;
            this.br = new BufferedReader(new InputStreamReader(stream));
        }

        /** Reads the next character or throws InputMismatchException if EOF. */
        private int read() {
            if (numChars == -1) {
                throw new InputMismatchException();
            }
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (numChars <= 0) {
                    return -1;
                }
            }
            return buf[curChar++];
        }

        /** Skips whitespace characters. */
        private int skipSpaces(int c) {
            while (isSpaceChar(c)) {
                c = read();
            }
            return c;
        }

        /** Reads a line (used only for the first line that contains *s* and *c*). */
        String readLine() {
            try {
                return br.readLine();
            } catch (IOException e) {
                throw new UncheckedIOException(e);
            }
        }

        /** Reads the next integer token. */
        int nextInt() {
            int c = skipSpaces(read());
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            int result = 0;
            do {
                if (c < '0' || c > '9') {
                    throw new InputMismatchException();
                }
                result = result * 10 + (c - '0');
                c = read();
            } while (!isSpaceChar(c));
            return result * sign;
        }

        /** Utility – tells whether a character is a whitespace. */
        private static boolean isSpaceChar(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }
    }

    public static void main(String[] args) {
        InputReader scanner = new InputReader(System.in);

        int rows = scanner.nextInt();      // *s*
        int cols = scanner.nextInt();      // *c*

        char[][] board = new char[rows][cols];
        int[][] indexMap = new int[rows][cols]; // map[row][col] -> linear index
        int cellCount = 0;

        // -----------------------------------------------------------------
        // Read the grid and assign a unique linear index to each cell.
        // -----------------------------------------------------------------
        for (int r = 0; r < rows; r++) {
            String line = scanner.readLine();
            for (int c = 0; c < cols; c++) {
                board[r][c] = line.charAt(c);
                indexMap[r][c] = cellCount++;
            }
        }

        boolean[] visited = new boolean[cellCount];
        Arrays.fill(visited, false);

        // -----------------------------------------------------------------
        // BFS exploration from every still‑unvisited cell.
        // -----------------------------------------------------------------
        for (int startIdx = 0; startIdx < cellCount; startIdx++) {
            if (visited[startIdx]) {
                continue;
            }

            // Start a new BFS component.
            Queue<Pair> queue = new LinkedList<>();
            queue.add(new Pair(startIdx, -1));   // -1 = coming from nowhere
            visited[startIdx] = true;

            outer:
            while (!queue.isEmpty()) {
                Pair cur = queue.poll();
                int curIdx = cur.current;
                int prevIdx = cur.previous;

                int curRow = curIdx / cols;
                int curCol = curIdx % cols;
                char curChar = board[curRow][curCol];

                // Examine the four neighbours.
                for (Direction dir : Direction.values()) {
                    int[] neighbourCoords = new int[2];
                    dir.offset(curRow, curCol, neighbourCoords);
                    int nr = neighbourCoords[0];
                    int nc = neighbourCoords[1];

                    // Bounds check.
                    if (nr < 0 || nr >= rows || nc < 0 || nc >= cols) {
                        continue;
                    }

                    // Only walk on cells that have the same character.
                    if (board[nr][nc] != curChar) {
                        continue;
                    }

                    int neighbourIdx = indexMap[nr][nc];

                    // Do not step back to the cell we just came from.
                    if (neighbourIdx == prevIdx) {
                        continue;
                    }

                    // If we have already visited this neighbour, a cycle exists.
                    if (visited[neighbourIdx]) {
                        System.out.println("Yes");
                        System.exit(0);
                    }

                    // Otherwise enqueue it and mark visited.
                    visited[neighbourIdx] = true;
                    queue.add(new Pair(neighbourIdx, curIdx));
                }
            }
        }

        // No cycle was found.
        System.out.println("No");
    }
}

import java.io.*;
import java.util.*;

/**
 * Fast input scanner that works with {@link System#in}.
 * It tokenises the input line‑by‑line to avoid the overhead of the
 * default {@code StringTokenizer} creation on every call.
 */
final class FastScanner {
    private final BufferedReader br;

    FastScanner(InputStream stream) {
        this.br = new BufferedReader(new InputStreamReader(stream), 32768);
    }

    /** Returns the next token from the input stream. */
    private String nextToken() throws IOException {
        while (true) {
            String line = br.readLine();
            if (line == null) {
                return null;
            }
            StringTokenizer st = new StringTokenizer(line);
            if (st.hasMoreTokens()) {
                return st.nextToken();
            }
        }
    }

    String next() {
        return nextToken();
    }

    int nextInt() {
        return Integer.parseInt(nextToken());
    }

    /** Returns the next full line (without removing the trailing newline). */
    String nextLine() throws IOException {
        return br.readLine();
    }
}

/**
 * Solution for the “Fox and Two Dots” problem.
 *
 * <p>Given a rectangular grid of uppercase letters, the task is to decide
 * whether any letter appears at least four times and forms a cycle of
 * length ≥ 4 when moving orthogonally between equal letters.</p>
 */
public class Main {

    public static void main(String[] args) throws Exception {
        FastScanner scanner = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(System.out, true);

        // The original template used a dummy test number; we keep it for compatibility.
        new FoxAndTwoDotsSolver().solve(1, scanner, out);
        out.close();
    }

    /**
     * Core logic that encapsulates all problem‑specific operations.
     * Keeping the algorithm in a dedicated class makes the `main` method
     * trivial and improves testability.
     */
    static final class FoxAndTwoDotsSolver {

        /** Directions: Up, Right, Down, Left */
        private static final char[] DIRECTIONS = {'U', 'R', 'D', 'L'};

        /**
         * Entry point used by {@code Main}.
         *
         * @param testNumber dummy test index (the original code only supports one test)
         * @param in         fast input scanner
         * @param out        output writer
         */
        void solve(int testNumber, FastScanner in, PrintWriter out) {
            int n = in.nextInt();
            int m = in.nextInt();
            char[][] grid = new char[n][];
            int[] letterCount = new int[26];               // count of each uppercase letter

            // ---- read grid and count letters ---------------------------------
            for (int i = 0; i < n; i++) {
                String row = in.next();
                grid[i] = row.toCharArray();
                for (char ch : grid[i]) {
                    letterCount[ch - 'A']++;
                }
            }

            // ---- examine every letter that occurs at least four times ----------
            for (int idx = 0; idx < 26; idx++) {
                if (letterCount[idx] < 4) {
                    continue;    // not enough occurrences to form a cycle
                }
                char target = (char) ('A' + idx);
                List<Integer>[] adjacency = buildAdjacency(grid, target);
                if (hasCycle(adjacency)) {
                    out.println("Yes");
                    return;
                }
            }
            out.println("No");
        }

        /**
         * Constructs an undirected adjacency list for all cells that contain
         * {@code target}. The list is indexed by a linear hash
         * {@code row * m + col}.
         *
         * @param grid   the character grid
         * @param target the letter we are currently analysing
         * @return adjacency list indexed by cell hash
         */
        private List<Integer>[] buildAdjacency(char[][] grid, char target) {
            int n = grid.length;
            int m = grid[0].length;
            int total = n * m;
            @SuppressWarnings("unchecked")
            List<Integer>[] graph = new List[total];
            for (int i = 0; i < total; i++) {
                graph[i] = new ArrayList<>();
            }

            for (int r = 0; r < n; r++) {
                for (int c = 0; c < m; c++) {
                    if (grid[r][c] != target) {
                        continue;
                    }
                    int curIdx = linearHash(r, c, m);
                    for (char dir : DIRECTIONS) {
                        int nr = r + dY(dir);
                        int nc = c + dX(dir);
                        if (isInside(nr, nc, n, m) && grid[nr][nc] == target) {
                            int nbIdx = linearHash(nr, nc, m);
                            graph[curIdx].add(nbIdx);
                        }
                    }
                }
            }
            return graph;
        }

        /**
         * Detects whether the undirected graph represented by {@code adjacency}
         * contains a cycle whose length is at least four edges.
         *
         * @param adjacency adjacency list indexed by linear cell hash
         * @return {@code true} if such a cycle exists
         */
        private boolean hasCycle(List<Integer>[] adjacency) {
            boolean[] visited = new boolean[adjacency.length];
            int[] depth   = new int[adjacency.length];

            for (int start = 0; start < adjacency.length; start++) {
                if (!visited[start]) {
                    if (dfsCycle(start, start, visited, depth, adjacency)) {
                        return true;
                    }
                }
            }
            return false;
        }

        /**
         * Depth‑first search that looks for a back‑edge to an already visited
         * vertex whose depth differs by at least three (implying a cycle of
         * length ≥ 4). The {@code parent} concept is encoded by ignoring the
         * edge that leads back to the start node itself.
         */
        private boolean dfsCycle(int start, int current,
                                 boolean[] visited, int[] depth,
                                 List<Integer>[] adjacency) {
            visited[current] = true;
            depth[current] = depth[start];          // depth relative to the start node

            for (int neighbour : adjacency[current]) {
                if (!visited[neighbour]) {
                    if (dfsCycle(start, neighbour, visited, depth, adjacency)) {
                        return true;
                    }
                } else if (neighbour != start) {    // ignore the edge back to the start node
                    int cycleDepthDiff = Math.abs(depth[current] - depth[neighbour]);
                    if (cycleDepthDiff >= 3) {
                        return true;
                    }
                }
            }
            return false;
        }

        // -----------------------------------------------------------------
        // Helper utilities (static for simplicity)
        // -----------------------------------------------------------------
        private static int dY(char dir) {
            switch (dir) {
                case 'U': return -1;
                case 'D': return  1;
                default:  return 0;
            }
        }

        private static int dX(char dir) {
            switch (dir) {
                case 'R': return  1;
                case 'L': return -1;
                default:  return 0;
            }
        }

        private static boolean isInside(int r, int c, int n, int m) {
            return r >= 0 && c >= 0 && r < n && c < m;
        }

        private static int linearHash(int row, int col, int m) {
            return row * m + col;
        }
    }
}

import java.io.IOException;
import java.util.Scanner;

/**
 * Main program – reads a grid, unions adjacent cells that contain the same character,
 * and prints "Yes" if two adjacent equal‑character cells already belong to the same
 * component, otherwise prints "No".
 */
public class Main {

    public static void main(String[] args) throws IOException {
        try (Scanner sc = new Scanner(System.in)) {
            int rows = sc.nextInt();
            int cols = sc.nextInt();

            // DSU can handle every cell in the grid (rows * cols possible elements)
            DSU dsu = new DSU(rows * cols);

            // Read the grid
            char[][] grid = new char[rows][cols];
            for (int i = 0; i < rows; i++) {
                String line = sc.next();
                for (int j = 0; j < cols; j++) {
                    grid[i][j] = line.charAt(j);
                }
            }

            // Scan neighbours (right and down) and union when characters match
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    processRight(i, j, grid, dsu);
                    processBottom(i, j, grid, dsu);
                }
            }

            // No adjacent equal‑character cells were already in the same component
            System.out.println("No");
        }
    }

    /** Union‑find helper that checks the right neighbour of (i, j). */
    private static void processRight(int i, int j, char[][] grid, DSU dsu) {
        if (j + 1 >= grid[0].length) {
            return;                       // no right neighbour
        }
        if (grid[i][j] != grid[i][j + 1]) {
            return;                       // characters differ – nothing to do
        }

        int idA = i * grid[0].length + j;
        int idB = i * grid[0].length + (j + 1);

        if (dsu.isSame(idA, idB)) {
            System.out.println("Yes");
            System.exit(0);               // already in the same component
        } else {
            dsu.union(idA, idB);
        }
    }

    /** Union‑find helper that checks the bottom neighbour of (i, j). */
    private static void processBottom(int i, int j, char[][] grid, DSU dsu) {
        if (i + 1 >= grid.length) {
            return;                       // no bottom neighbour
        }
        if (grid[i][j] != grid[i + 1][j]) {
            return;                       // characters differ – nothing to do
        }

        int idA = i * grid[0].length + j;
        int idB = (i + 1) * grid[0].length + j;

        if (dsu.isSame(idA, idB)) {
            System.out.println("Yes");
            System.exit(0);
        } else {
            dsu.union(idA, idB);
        }
    }
}

/**
 * Simple Disjoint Set Union (Union‑Find) implementation with path compression
 * and union by rank.
 */
final class DSU {
    private final int[] parent;
    private final int[] rank;

    /**
     * Constructs a DSU that can handle {@code size} distinct elements.
     *
     * @param size number of elements (typically {@code rows * cols})
     */
    DSU(int size) {
        parent = new int[size];
        rank = new int[size];
        for (int i = 0; i < size; i++) {
            parent[i] = i;               // each element is its own root initially
        }
    }

    /** Finds the representative of {@code x} with path compression. */
    int find(int x) {
        if (parent[x] != x) {
            parent[x] = find(parent[x]);
        }
        return parent[x];
    }

    /** Returns {@code true} if {@code x} and {@code y} belong to the same set. */
    boolean isSame(int x, int y) {
        return find(x) == find(y);
    }

    /** Merges the sets containing {@code x} and {@code y} using union‑by‑rank. */
    void union(int x, int y) {
        int rootX = find(x);
        int rootY = find(y);
        if (rootX == rootY) {
            return;
        }

        // Attach the lower‑rank tree under the higher‑rank tree
        if (rank[rootX] < rank[rootY]) {
            parent[rootX] = rootY;
        } else if (rank[rootX] > rank[rootY]) {
            parent[rootY] = rootX;
        } else {
            parent[rootY] = rootX;
            rank[rootX]++;
        }
    }
}

/**
 * Detects whether a grid contains a cycle of at least five cells made of the same character.
 *
 * <p>Refactored version of the original {@code Dots} program to improve readability,
 * maintainability and modern Java practices.
 */
public class Dots {

    /** Minimum depth (inclusive) required for a valid cycle. */
    private static final int MIN_SEQUENCE_LENGTH = 5; // 5 steps → difference of 4 edges

    /** Directions used for DFS traversal (down, up, right, left). */
    private static final int[][] DIRS = {
            {1, 0},
            {-1, 0},
            {0, 1},
            {0, -1}
    };

    /** The 2‑D character board read from the input. */
    private final char[][] board;
    /** Number of rows of the board. */
    private final int rows;
    /** Number of columns of the board. */
    private final int cols;

    /**
     * Entry point of the program.
     * Parses the input, builds the board and starts the search.
     */
    public static void main(String[] args) {
        new Dots().solve();
    }

    /**
     * Orchestrates the whole process: reading the board, performing the DFS,
     * and printing the result.
     */
    private void solve() {
        // ---------- 1️⃣ Read input ----------
        int rows, cols;
        char[][] matrix;

        try (Scanner scanner = new Scanner(System.in)) {
            rows = scanner.nextInt();
            cols = scanner.nextInt();
            matrix = readBoard(scanner, rows, cols);
        }

        this.board = matrix;
        this.rows = rows;
        this.cols = cols;

        // ---------- 2️⃣ Search for a cycle ----------
        int[][] depthVisited = new int[rows][cols];
        found = false;

        for (int i = 0; i < rows && !found; i++) {
            for (int j = 0; j < cols && !found; j++) {
                if (depthVisited[i][j] == 0) {
                    dfs(i, j, 1, depthVisited);
                }
            }
        }

        // ---------- 3️⃣ Output ----------
        System.out.println(found ? "Yes" : "No");
    }

    /*
     * -----------------------------------------------------------------------
     * Private helper methods
     * -----------------------------------------------------------------------
     */

    /**
     * Parses multiple lines of input to fill a {@code char[][]} board.
     *
     * @param scanner   Scanner positioned after the board dimensions.
     * @param rows      Number of rows to read.
     * @param cols      Number of columns per row.
     * @return          Populated board.
     */
    private static char[][] readBoard(Scanner scanner, int rows, int cols) {
        char[][] mat = new char[rows][cols];
        for (int i = 0; i < rows; i++) {
            String line = scanner.next();
            for (int j = 0; j < cols; j++) {
                mat[i][j] = line.charAt(j);
            }
        }
        return mat;
    }

    /**
     * Depth‑first search that looks for cycles of length {@link #MIN_SEQUENCE_LENGTH}
     * consisting of the same character.
     *
     * @param i           Current row index.
     * @param j           Current column index.
     * @param currentDepth Depth value at entry of this cell (1‑based).
     * @param depthVisited Grid storing the depth of the first visit for each cell.
     */
    private void dfs(int i, int j, int currentDepth, int[][] depthVisited) {
        // If the cell has been visited before, we might have found a cycle.
        if (depthVisited[i][j] != 0) {
            // Cycle length = current depth - previously stored depth
            if (currentDepth - depthVisited[i][j] + 1 >= MIN_SEQUENCE_LENGTH) {
                found = true;               // found a valid cycle
            }
            return;                         // nothing more to explore from here
        }

        // Mark the cell with the depth at which we first entered it.
        depthVisited[i][j] = currentDepth;

        // Explore all four neighbours that share the same character.
        char currentChar = board[i][j];
        for (int[] dir : DIRS) {
            int ni = i + dir[0];
            int nj = j + dir[1];

            if (isWithinBounds(ni, nj) && board[ni][nj] == currentChar) {
                dfs(ni, nj, currentDepth + 1, depthVisited);
                if (found) {
                    return;                 // early exit – no need to continue searching
                }
            }
        }

        // Backtrack: clear the mark so that other unrelated paths can reuse this cell.
        depthVisited[i][j] = 0;
    }

    /**
     * Checks whether a given cell lies inside the grid boundaries.
     *
     * @param i Row index.
     * @param j Column index.
     * @return {@code true} if the cell is inside the board.
     */
    private boolean isWithinBounds(int i, int j) {
        return i >= 0 && i < rows && j >= 0 && j < cols;
    }

    // -----------------------------------------------------------------------
    // State used during the search (kept minimal and package‑private)
    // -----------------------------------------------------------------------
    private boolean found;   // becomes true as soon as a qualifying cycle is discovered
}

