/**
 * Core logic for detecting a cycle of at least four cells that share the same character.
 */
class TaskB {
    /** Directions: down, left, up, right */
    private static final int[] DX = {1, 0, -1, 0};
    private static final int[] DY = {0, -1, 0, 1};

    /**
     * Reads one test case from the supplied {@link InputReader},
     * performs the detection and prints {@code Yes} or {@code No}.
     *
     * @param in  input reader
     * @param out output writer
     */
    public void solve(InputReader in, OutputWriter out) {
        int rows = in.readInt();
        int cols = in.readInt();
        char[][] grid = IOUtils.readTable(in, rows, cols);

        boolean hasCycle = hasCycle(grid);
        out.printLine(hasCycle ? "Yes" : "No");
    }

    /**
     * Checks whether the grid contains a cycle of length ≥ 4 formed by equal characters.
     *
     * @param grid the character grid to examine
     * @return {@code true} if such a cycle exists
     */
    private boolean hasCycle(char[][] grid) {
        int rows = grid.length;
        int cols = grid[0].length;
        boolean[][] visited = new boolean[rows][cols];

        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (!visited[r][c] && dfs(r, c, -1, -1, grid[r][c], 0, grid, visited)) {
                    return true;               // early exit on first found cycle
                }
            }
        }
        return false;
    }

    /**
     * Depth‑first search that traverses cells of the same character.
     *
     * @param curX      current row index
     * @param curY      current column index
     * @param fromX     row of the previous cell in the current path
     * @param fromY     column of the previous cell in the current path
     * @param ch        character we are looking for
     * @param depth     number of cells visited so far in the current branch
     * @param grid      mutable grid – marks cells visited in the current DFS
     * @param visited   global visitation matrix to avoid re‑processing cells
     * @return {@code true} if a valid cycle has been detected
     */
    private boolean dfs(int curX, int curY,
                        int fromX, int fromY,
                        char ch,
                        int depth,
                        char[][] grid,
                        boolean[][] visited) {

        visited[curX][curY] = true;
        grid[curX][curY] = '*';                     // mark as part of current search

        for (int dir = 0; dir < DX.length; dir++) {
            int nx = curX + DX[dir];
            int ny = curY + DY[dir];

            // Do not go back to the cell we came from
            if (nx == fromX && ny == fromY) {
                continue;
            }

            if (!MiscUtils.isInBounds(nx, ny, grid.length, grid[0].length)) {
                continue;
            }

            if (grid[nx][ny] != ch) {
                // Visited a cell that belongs to the current search and we have
                // enough depth → a cycle of length ≥ 4 exists.
                if (grid[nx][ny] == '*' && depth >= 3) {
                    return true;
                }
                continue;
            }

            if (dfs(nx, ny, curX, curY, ch, depth + 1, grid, visited)) {
                return true;
            }
        }

        // Backtrack – restore the cell so it can be used in other searches
        grid[curX][curY] = ch;
        return false;
    }
}

/**
 * Miscellaneous utility methods that do not belong to any particular domain.
