class MiscUtils {
    /** Returns {@code true} if the coordinates are inside the grid. */
    public static boolean isInBounds(int row, int col, int rows, int cols) {
        return row >= 0 && row < rows && col >= 0 && col < cols;
    }
}

/**
 * Simple token reader based on a buffered {@link InputStream}.
 */
class InputReader {
    private final InputStream stream;
    private final byte[] buffer = new byte[16_384];
    private int ptr = 0, length = 0;

    /** Constructs a reader for the given {@link InputStream}. */
    public InputReader(InputStream stream) {
        this.stream = stream;
    }

    /** Reads the next raw byte, -1 if EOF. */
    private int read() {
        if (length == -1) return -1;
        if (ptr >= length) {
            ptr = 0;
            length = stream.read(buffer);
            if (length <= 0) length = -1;
        }
        return buffer[ptr++];
    }

    /** Reads the next integer from the input. */
    public int readInt() {
        int c = read();
        while (isSpaceChar(c)) c = read();

        int sign = 1;
        if (c == '-') {
            sign = -1;
            c = read();
        }

        int value = 0;
        do {
            if (c < '0' || c > '9') throw new InputMismatchException();
            value = value * 10 + (c - '0');
            c = read();
        } while (!isSpaceChar(c));

        return value * sign;
    }

    /** Checks whether the character is considered whitespace. */
    public boolean isSpaceChar(int ch) {
        return ch == ' ' || ch == '\n' || ch == '\r' || ch == '\t';
    }

    /** Reads the next non‑whitespace character. */
    public char readChar() {
        int c;
        do {
            c = read();
        } while (isSpaceChar(c));
        return (char) c;
    }
}

