import java.io.PrintStream;
import java.util.Scanner;

/**
 * Utility that reads a grid of characters and checks whether any connected component
 * of the same character contains a cycle (i.e. it is *not* a tree).
 *
 * <p>If at least one component is not a tree the program prints {@code Yes},
 * otherwise it prints {@code No}.</p>
 *
 * <p>This version focuses on readability, separation of concerns and proper resource
 * handling.</p>
 */
public class B {

    /** Directions: up, right, down, left */
    private static final int[] DX = {-1, 0, 1, 0};
    private static final int[] DY = {0, 1, 0, -1};

    /** Information gathered during a DFS traversal of one component. */
    private static final class ComponentInfo {
        int nodeCount = 0;   // number of vertices visited
        int edgeCount = 0;   // edges counted twice (once per endpoint)

        void incrementEdgeCount() {
            edgeCount++;
        }

        int getUndirectedEdgeCount() {
            // each undirected edge was counted from both ends
            return edgeCount / 2;
        }
    }

    /**
     * Depth‑first search that populates {@code info} with the size of the
     * connected component consisting of {@code colour}.
     *
     * @param board      the grid
     * @param colour     character we are currently exploring
     * @param i          start row index
     * @param j          start column index
     * @param visited    matrix that records visited cells
     * @param info       container that will be filled with component statistics
     * @param rows       number of rows in the board
     * @param cols       number of columns in the board
     */
    private static void dfs(String[] board,
                            char colour,
                            int i,
                            int j,
                            boolean[][] visited,
                            ComponentInfo info,
                            int rows,
                            int cols) {

        if (visited[i][j]) {
            return;
        }

        visited[i][j] = true;
        info.nodeCount++;

        // Count every adjacent cell that has the same colour.
        // This counts each undirected edge twice (once from each side).
        for (int dir = 0; dir < 4; dir++) {
            int ni = i + DX[dir];
            int nj = j + DY[dir];

            if (ni < 0 || ni >= rows || nj < 0 || nj >= cols) {
                continue;
            }

            if (board[ni].charAt(nj) == colour) {
                info.incrementEdgeCount();

                if (!visited[ni][nj]) {
                    dfs(board, colour, ni, nj, visited, info, rows, cols);
                }
            }
        }
    }

    /**
     * Determines whether the supplied component behaves like a tree.
     *
     * @param info component statistics
     * @return {@code true} if {@code nodes - 1 == edges / 2} (i.e. a tree)
     */
    private static boolean isTree(ComponentInfo info) {
        return info.nodeCount - 1 == info.getUndirectedEdgeCount();
    }

    /**
     * Reads input, processes the board and prints the result.
     *
     * @param out Print stream used for output (normally {@code System.out})
     */
    private static void solve(PrintStream out) {
        try (Scanner scanner = new Scanner(System.in)) {
            int rows = scanner.nextInt();
            int cols = scanner.nextInt();

            // Read the board line by line
            String[] board = new String[rows];
            for (int r = 0; r < rows; r++) {
                board[r] = scanner.next();
            }

            boolean[][] visited = new boolean[rows][cols];

            // Explore every not‑yet‑visited cell
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (visited[r][c]) {
                        continue;
                    }

                    ComponentInfo comp = new ComponentInfo();
                    dfs(board,
                          board[r].charAt(c),
                          r,
                          c,
                          visited,
                          comp,
                          rows,
                          cols);

                    // As soon as we find a component that is NOT a tree,
                    // we can terminate early with "Yes".
                    if (!isTree(comp)) {
                        out.println("Yes");
                        return;
                    }
                }
            }

            // No non‑tree component was found
            out.println("No");
        }
    }

    /** Entry point – delegates to {@link #solve(PrintStream)}. */
    public static void main(String[] args) {
        solve(System.out);
    }
}

import java.io.BufferedReader;
import java.io.IOException;
