import java.util.Objects;

/**
 * Reads a grid of characters from standard input and determines whether there exists
 * a pair of adjacent equal characters that belong to the same connected component
 * when the components are built using the DSU (Disjoint Set Union) data structure.
 *
 * <p>If such a pair is found the program prints {@code Yes} and exits; otherwise it
 * prints {@code No}.</p>
 */
public final class Solution {

    /** Size of the DSU – one element per cell of the grid. */
    private static final int DSU_SIZE = 1;

    private Solution() {
        // Utility class – prevent instantiation.
    }

    public static void main(String[] args) throws IOException {
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(System.in))) {
            String[] dims = parseFirstLine(reader);
            int rows = Integer.parseInt(dims[0]);
            int cols = Integer.parseInt(dims[1]);

            char[][] grid = readGrid(reader, rows, cols);
            DSU dsu = new DSU(rows, cols);

            detectAndPrintResult(grid, rows, cols, dsu);
        }
    }

    /**
     * Parses the first line of input which contains the number of rows and columns.
     *
     * @param reader a {@link BufferedReader} positioned at the first line.
     * @return an array {@code [rows, cols]}.
     * @throws IOException if an I/O error occurs.
     */
    private static String[] parseFirstLine(BufferedReader reader) throws IOException {
        String line = readNonEmptyLine(reader);
        String[] parts = line.trim().split("\\s+");
        return new String[] { parts[0], parts[1] };
    }

    /**
     * Reads exactly {@code rows} lines, each representing a row of the grid.
     *
     * @param reader a {@link BufferedReader}.
     * @param rows   number of rows.
     * @param cols   number of columns.
     * @return a 2‑dimensional {@code char[][]`grid`.
     */
    private static char[][] readGrid(BufferedReader reader, int rows, int cols) throws IOException {
        char[][] grid = new char[rows][cols];
        for (int i = 0; i < rows; i++) {
            String line = readNonEmptyLine(reader);
            Objects.requireNonNull(line);
            // Ensure the line length matches the declared column count.
            if (line.length() < cols) {
                throw new IllegalArgumentException(
                    String.format("Row %d does not contain enough characters (expected %d, got %d)",
                                  i + 1, cols, line.length()));
            }
            // Store only the first {@code cols} characters – extra characters are ignored.
            for (int j = 0; j < cols; j++) {
                grid[i][j] = line.charAt(j);
            }
        }
        return grid;
    }

    /**
     * Reads a non‑empty line from the supplied {@link BufferedReader}.
     *
     * @param reader a {@link BufferedReader}.
     * @return the next non‑empty line.
     * @throws IOException if an I/O error occurs.
     */
    private static String readNonEmptyLine(BufferedReader reader) throws IOException {
        String line;
        while ((line = reader.readLine()) != null && line.trim().isEmpty()) {
            // Skip blank lines.
        }
        return line;
    }

    /**
     * Executes the DSU‑based detection logic and prints the result.
     *
     * @param grid     the character grid.
     * @param rows     number of rows.
     * @param cols     number of columns.
     * @param dsu      the DSU structure used for connectivity.
     */
    private static void detectAndPrintResult(char[][] grid, int rows, int cols, DSU dsu) {
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                int currentIdx = toLinearIndex(i, j, cols);
                // Check upper neighbour.
                if (i > 0 && grid[i][j] == grid[i - 1][j]) {
                    int neighbourIdx = toLinearIndex(i - 1, j, cols);
                    if (dsu.isSameSet(currentIdx + 1, neighbourIdx + 1)) {
                        System.out.println("Yes");
                        return;
                    }
                    dsu.union(currentIdx + 1, neighbourIdx + 1);
                }
                // Check left neighbour.
                if (j > 0 && grid[i][j] == grid[i][j - 1]) {
                    int neighbourIdx = toLinearIndex(i, j - 1, cols);
                    if (dsu.isSameSet(currentIdx + 1, neighbourIdx + 1)) {
                        System.out.println("Yes");
                        return;
                    }
                    dsu.union(currentIdx + 1, neighbourIdx + 1);
                }
            }
        }
        System.out.println("No");
    }

    /**
     * Converts a (row, column) pair into a 1‑based linear index used by the DSU.
     *
     * @param row    zero‑based row index.
     * @param col    zero‑based column index.
     * @param cols   number of columns in the grid.
     * @return the 1‑based index.
     */
    private static int toLinearIndex(int row, int col, int cols) {
        return row * cols + col + 1; // +1 because DSU internally uses 1‑based indexing.
    }
}

/**
 * Simple Disjoint Set Union (DSU) implementation with path compression and union by size.
 *
 * <p>The internal arrays are 1‑based to match the index calculation used in {@link Solution}.</p>
 */
final class DSU {
    private final int[] parent;
    private final int[] size;

    /**
     * Constructs a DSU capable of handling {@code elements} items (1‑based indexing).
     *
     * @param rows    number of rows in the grid.
     * @param cols    number of columns in the grid.
     */
    DSU(int rows, int cols) {
        int elementCount = rows * cols;
        parent = new int[elementCount + 1];
        size   = new int[elementCount + 1];

        for (int i = 1; i <= elementCount; i++) {
            parent[i] = i;
            size[i]   = 1;
        }
    }

    /**
     * Returns the representative (root) of the set that contains {@code vertex}.
     * Path compression is applied while traversing.
     *
     * @param vertex a 1‑based element index.
     * @return the root of the set.
     */
    int find(int vertex) {
        int root = vertex;
        // Find root.
        while (parent[root] != root) {
            root = parent[root];
        }
        // Path compression – point every visited node directly to the root.
        while (parent[vertex] != root) {
            int next = parent[vertex];
            parent[vertex] = root;
            vertex = next;
        }
        return root;
    }

    /**
     * Checks whether {@code a} and {@code b} belong to the same set.
     *
     * @param a first element (1‑based).
     * @param b second element (1‑based).
     * @return {@code true} if both elements are in the same set.
     */
    boolean isSameSet(int a, int b) {
        return find(a) == find(b);
    }

    /**
     * Merges the sets that contain {@code u} and {@code v}.
     * Uses union‑by‑size: the smaller tree is attached under the larger one.
     *
     * @param u first element (1‑based).
     * @param v second element (1‑based).
     */
    void union(int u, int v) {
        int rootU = find(u);
        int rootV = find(v);
        if (rootU == rootV) {
            return; // Already in the same set.
        }

        // Attach smaller tree under the larger one.
        if (size[rootU] < size[rootV]) {
            parent[rootU] = rootV;
            size[rootV] += size[rootU];
        } else {
            parent[rootV] = rootU;
            size[rootU] += size[rootV];
        }
    }
}

import java.io.BufferedReader;
import java.io.BufferedWriter;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.OutputStreamWriter;
import java.util.ArrayDeque;
import java.util.Deque;

/**
 * Detects whether a grid of letters contains a cycle of at least 4 cells
 * consisting of the same letter.
 *
 * <p>This refactor separates concerns, uses clearer naming, avoids unnecessary
 * static fields, and employs try‑with‑resources for proper resource handling.</p>
 */
public final class FoxAndTwoDots {

    /** Directions in which we can move on the grid. */
    private enum Direction {
        UP(-1, 0), RIGHT(0, 1), DOWN(1, 0), LEFT(0, -1);

        private final int dr;
        private final int dc;

        Direction(int dr, int dc) {
            this.dr = dr;
            this.dc = dc;
        }

        int[] delta() {
            return new int[]{dr, dc};
        }
    }

    /** Utility class that encapsulates the cycle‑detection algorithm. */
    private static final class CycleDetector {

        private final char[][] grid;
        private final boolean[][] visited;
        private boolean hasCycle = false;

        CycleDetector(char[][] grid, boolean[][] visited) {
            this.grid = grid;
            this.visited = visited;
        }

        /**
         * Starts the DFS from the supplied start cell if it was not visited yet.
         *
         * @param startR start row index
         * @param startC start column index
         */
        void explore(int startR, int startC) {
            if (visited[startR][startC]) {
                return;
            }
            dfs(startR, startC, -1, -1, new ArrayDeque<>());
        }

        /** Depth‑first search that checks for cycles. */
        private void dfs(int r, int c, int parentR, int parentC, Deque<Direction> stack) {
            visited[r][c] = true;

            for (Direction dir : Direction.values()) {
                int nr = r + dir.delta()[0];
                int nc = c + dir.delta()[1];

                // Bounds check
                if (!isInside(nr, nc)) {
                    continue;
                }

                // Must stay on the same letter
                if (grid[nr][nc] != grid[r][c]) {
                    continue;
                }

                // If we revisit a cell that is not the immediate parent, we found a cycle.
                if ((nr != parentR || nc != parentC) && visited[nr][nc]) {
                    hasCycle = true;
                    return;
                }

                if (!visited[nr][nc]) {
                    stack.push(dir);
                    dfs(nr, nc, r, c, stack);
                    if (hasCycle) {
                        return;
                    }
                    stack.pop();
                }
            }
        }

        private boolean isInside(int r, int c) {
            return r >= 0 && r < grid.length && c >= 0 && c < grid[0].length;
        }

        boolean hasCycle() {
            return hasCycle;
        }
    }

    /** Entry point. */
    public static void main(String[] args) throws IOException {
        // Advisory: try‑with‑resources automatically closes the reader.
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
             BufferedWriter bw = new BufferedWriter(new OutputStreamWriter(System.out))) {

            // ----- read dimensions -------------------------------------------------
            String[] dimLine = br.readLine().split("\\s+");
            final int n = Integer.parseInt(dimLine[0]);
            final int m = Integer.parseInt(dimLine[1]);

            // ----- read grid -------------------------------------------------------
            char[][] grid = new char[n][m];
            for (int i = 0; i < n; i++) {
                String line = br.readLine();
                for (int j = 0; j < m; j++) {
                    grid[i][j] = line.charAt(j);
                }
            }

            // ----- visited matrix ---------------------------------------------------
            boolean[][] visited = new boolean[n][m];

            // ----- run detection ---------------------------------------------------
            CycleDetector detector = new CycleDetector(grid, visited);
            for (int i = 0; i < n && !detector.hasCycle(); i++) {
                for (int j = 0; j < m && !detector.hasCycle(); j++) {
                    if (!visited[i][j]) {
                        detector.explore(i, j);
                    }
                }
            }

            // ----- output -----------------------------------------------------------
            bw.write(detector.hasCycle() ? "Yes" : "No");
            bw.flush();
        }
    }
}

/*
 *  Solution – Detect a cycle of length ≥ 4 formed by the same character
 *  in a 2‑D grid.
 *
 *  The program is deliberately split into small, single‑purpose classes
 *  (FastScanner, FastPrinter) and the core algorithm lives in the
 *  `GridAnalyzer` helper class.  All dead code, unused imports and
 *  duplicated logic have been removed.
 *
 *  Author:  (your name)
 *  Created: 2025‑11‑03
 */

import java.io.*;
import java.util.*;

/**
 * Fast input reader that works with {@code System.in}, a {@code File}
 * or an arbitrary {@code InputStream}.  It supplies the same methods
 * as the original hand‑rolled scanner but with a clearer API and
 * better documentation.
 */
final class FastScanner {
    private final BufferedReader reader;
    private StringTokenizer tokenizer;

    /** Creates a scanner that reads from the given stream. */
    FastScanner(InputStream stream) {
        this.reader = new BufferedReader(new InputStreamReader(stream));
        this.tokenizer = new StringTokenizer("");
    }

    /** Creates a scanner that reads from the supplied file. */
    FastScanner(File file) throws FileNotFoundException {
        this(new FileInputStream(file));
    }

    /** @return next integral token as {@code int}. */
    int nextInt() throws IOException {
        return Integer.parseInt(nextToken());
    }

    /** @return next token as {@code long}. */
    long nextLong() throws IOException {
        return Long.parseLong(nextToken());
    }

    /** @return next token as {@code double}. */
    double nextDouble() throws IOException {
        return Double.parseDouble(nextToken());
    }

    /** @return next token as {@code String}. */
    String nextString() throws IOException {
        return nextToken();
    }

    /** @return next complete line (including empty lines). */
    String nextLine() throws IOException {
        return reader.readLine();
    }

    /** @return {@code true} if there is another token available. */
    boolean hasMoreTokens() throws IOException {
        return tokenizer.hasMoreTokens() || peekToken() != null;
    }

    /** Reads the next non‑null token without consuming it (‑‑internal helper). */
    private String peekToken() throws IOException {
        while (!tokenizer.hasMoreTokens()) {
            String line = reader.readLine();
            if (line == null) {
                return null;
            }
            tokenizer = new StringTokenizer(line);
        }
        return tokenizer.nextToken();
    }

    /** Consumes the current token and returns it. */
    private String nextToken() throws IOException {
        while (!tokenizer.hasMoreTokens()) {
            String line = reader.readLine();
            if (line == null) {
                return null;
            }
            tokenizer = new StringTokenizer(line);
        }
        return tokenizer.nextToken();
    }

    /** Closes the underlying reader. */
    void close() throws IOException {
        reader.close();
    }
}

/**
 * Simple wrapper around {@code PrintWriter} that writes to the given
