/**
 * Core logic that analyses a grid to decide whether a cycle of length
 * at least four composed of identical characters exists.
 */
final class GridAnalyzer {
    private final char[][] grid;
    private final boolean[][] visited;
    private final int rows;
    private final int cols;

    // Four possible moves (up, down, left, right)
    private static final int[][] DIRS = {
            {1, 0},    // down
            {-1, 0},   // up
            {0, 1},    // right
            {0, -1}    // left
    };

    GridAnalyzer(char[][] grid) {
        this.grid = grid;
        this.rows = grid.length;
        this.cols = grid[0].length;
        this.visited = new boolean[rows][cols];
    }

    /**
     * Entry point – scans the whole grid looking for a qualifying cycle.
     *
     * @return {@code true} if such a cycle exists.
     */
    boolean hasCycleOfLengthFourOrMore() {
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (!visited[i][j]) {
                    if (dfs(i, j, -1, -1, 1)) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    /**
     * Depth‑first search that tries to find a cycle starting from
     * (row, col).  The method avoids moving back to the cell we just
     * came from (prevRow, prevCol).  If we ever revisit a cell that
     * belongs to the current path and the accumulated depth is at
     * least four, a valid cycle has been found.
     *
     * @param row       current row
     * @param col       current column
     * @param prevRow   row of the previous cell (or –1 for the start)
     * @param prevCol   column of the previous cell (or –1 for the start)
     * @param depth     length of the current path so far
     * @return {@code true} if a qualifying cycle was discovered.
     */
    private boolean dfs(int row, int col, int prevRow, int prevCol, int depth) {
        visited[row][col] = true;

        char currentChar = grid[row][col];
        for (int[] dir : DIRS) {
            int newRow = row + dir[0];
            int newCol = col + dir[1];

            // Bounds check
            if (newRow < 0 || newRow >= rows || newCol < 0 || newCol >= cols) {
                continue;
            }

            char neighborChar = grid[newRow][newCol];
            if (neighborChar != currentChar) {
                continue;                 // different character → not part of the same group
            }

            // Prevent immediate backtrack to the previous cell
            if (newRow == prevRow && newCol == prevCol) {
                continue;
            }

            if (!visited[newRow][newCol]) {
                if (dfs(newRow, newCol, row, col, depth + 1)) {
                    return true;
                }
            } else {
                // We have reached a visited cell that is *not* the immediate predecessor.
                // Since we only start a DFS from an unvisited cell, any visited neighbour
                // that is part of the current recursion stack represents a cycle.
                // The cycle length is the current depth + 1 (the edge that closes the cycle)
                // which must be ≥ 4.
                if (depth + 1 >= 4) {
                    return true;
                }
            }
        }
        return false;
    }
}

/**
 * Main driver class – reads input, runs the analyzer and prints the result.
 */
public class Solution {
    public static void main(String[] args) throws IOException {
        // Input / Output streams (standard I/O)
        FastScanner scanner = new FastScanner(System.in);
        FastPrinter printer = new FastPrinter(System.out);

        try {
            solve(scanner, printer);
        } finally {
            // Ensure resources are closed even if an exception occurs
            scanner.close();
            printer.close();
        }
    }

    /**
     * Solves the problem using the supplied scanner and printer.
     *
     * @param scanner input stream wrapper
     * @param printer output stream wrapper
     */
    private static void solve(FastScanner scanner, FastPrinter printer) throws IOException {
        int n = scanner.nextInt();      // number of rows
        int m = scanner.nextInt();      // number of columns
        char[][] grid = new char[n][];

        // Read the grid – each row arrives as a single string.
        for (int i = 0; i < n; i++) {
            String rowString = scanner.nextString();
            grid[i] = rowString.toCharArray();
        }

        GridAnalyzer analyzer = new GridAnalyzer(grid);
        boolean found = analyzer.hasCycleOfLengthFourOrMore();

        printer.println(found ? "Yes" : "No");
    }
}

/**
 * Board‑covering puzzle solver.
 *
 * The algorithm reads a rectangular grid that consists of '.' (empty cells)
 * and solves it by repeatedly covering isolated cells with dominoes.
 * If a unique tiling exists the final board is printed, otherwise
 * "Not unique" is written.
 *
 * The code is deliberately split into small, single‑responsibility classes
 * to improve readability, testability and future maintenance.
 */
public class Main {

    /** Directions used for neighbor checks (up, down, left, right). */
    private static final int[][] CARDINAL = {
            {-1, 0}, {1, 0}, {0, -1}, {0, 1}
    };

    /** Directions also used when enqueuing neighbouring cells after a placement. */
    private static final int[][] ALL_NEIGHBOURS = {
            {-1, 0}, {2, 0}, {0, -1}, {1, -1}, {0, 1}, {1, 1}
    };

    /** Symbol used to replace placed domino halves. */
    private static final char HORIZONTAL = '<';
    private static final char VERTICAL   = '^';
    private static final char VERTICAL_DOWN = 'v';
    private static final char HORIZONTAL_RIGHT = '>';

    /** Entry point. */
    public static void main(String[] args) throws Exception {
        new Solver().solve();
    }

    /** Core solver – encapsulates all algorithmic steps. */
    private static class Solver {
        private final BufferedReader reader;
        private char[][] board;
        private int rows, cols;

        /** Queue used during BFS/DFS traversals. */
        private final Deque<int[]> queue = new ArrayDeque<>();

        Solver() throws IOException {
            this.reader = new BufferedReader(new InputStreamReader(System.in));
        }

        /** Starts the whole solving process. */
        void solve() throws IOException {
            readInput();
            if (canBeTiledUniquely()) {
                printBoard();
            } else {
                System.out.println("Not unique");
            }
        }

        /** -------------------------------------------------------------------- *
         *  I/O & parsing
         *  -------------------------------------------------------------------- */
        private void readInput() throws IOException {
            String[] sizes = intArray(reader.readLine());
            rows = sizes[0];
            cols = sizes[1];

            board = new char[rows][];
            for (int r = 0; r < rows; r++) {
                board[r] = readLine().toCharArray();
            }
        }

        private static String[] split(String line) {
            String[] tokens = new String[line.trim().split("\\s+").length];
            int idx = 0;
            for (String token : line.trim().split("\\s+")) {
                tokens[idx++] = token;
            }
            return tokens;
        }

        private static int[] intArray(String line) {
            return Arrays.stream(split(line)).mapToInt(Integer::parseInt).toArray();
        }

        private static String readLine() throws IOException {
            String line;
            while ((line = reader.readLine()) != null && line.trim().isEmpty()) {
                // skip blank lines
            }
            return line;
        }

        /** -------------------------------------------------------------------- *
         *  Main solving logic
         *  -------------------------------------------------------------------- */
        /** Returns true if the board can be uniquely tiled, otherwise false. */
        private boolean canBeTiledUniquely() {
            if (!hasAllCellsCoverable()) {
                return false;
            }

            // Repeatedly place forced dominoes (cells with exactly one neighbour)
            while (placeForcedDominoes()) {
                // after a placement the neighbourhood may contain new forced cells
            }

            // After exhausting forced moves we must be able to pair up the remaining cells
            // and all cycles must have even length with all cells having exactly two neighbours.
            return isRemainingGraphValid();
        }

        /** Checks that every empty cell has at least one adjacent empty neighbour. */
        private boolean hasAllCellsCoverable() {
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (board[r][c] == '.' && countEmptyNeighbours(r, c) == 0) {
                        return false;
                    }
                }
            }
            return true;
        }

        /** Places dominoes that are forced by a single adjacent empty neighbour.
         *  Returns true if at least one placement was performed. */
        private boolean placeForcedDominoes() {
            Deque<int[]> frontier = new ArrayDeque<>();

            // Initialise frontier with any cell that currently has exactly one neighbour
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (board[r][c] == '.' && countEmptyNeighbours(r, c) == 1) {
                        frontier.addLast(new int[]{r, c});
                    }
                }
            }

            boolean changed = false;

            while (!frontier.isEmpty()) {
                int[] cell = frontier.removeFirst();
                if (board[cell[0]][cell[1]] != '.') {
                    continue; // already processed / placed
                }

                Direction dir = findSingletonNeighbour(cell[0], cell[1]);
                if (dir == null) {
                    // Should not happen because count == 1 is checked before enqueueing,
                    // but defensive programming keeps the algorithm robust.
                    return false;
                }

                placeDomino(cell, dir);
                changed = true;

                // Enqueue neighbours of the cells that were just filled – they may become forced now
                for (int[] d : ALL_NEIGHBOURS) {
                    int nr = cell[0] + d[0];
                    int nc = cell[1] + d[1];
                    if (inBounds(nr, nc) && board[nr][nc] == '.') {
                        int nb = countEmptyNeighbours(nr, nc);
                        if (nb == 1) {
                            frontier.addLast(new int[]{nr, nc});
                        }
                    }
                }
            }
            return changed;
        }

        /** Finds the unique neighbour direction of an empty cell that has exactly one neighbour.
         *  The result encodes whether the domino will be placed vertically or horizontally. */
        private Direction findSingletonNeighbour(int r, int c) {
            int[] firstDir = null;
            boolean verticalMode = false;

            for (int[] d : CARDINAL) {
                int nr = r + d[0];
                int nc = c + d[1];
                if (!inBounds(nr, nc) || board[nr][nc] != '.') {
                    continue;
                }

                // More than one neighbour → cannot be a singleton case
                if (firstDir != null) {
                    return null;
                }

                firstDir = d;
                verticalMode = d[0] != 0; // non‑zero row delta means vertical movement
            }
            return verticalMode ? Direction.VERTICAL : Direction.HORIZONTAL;
        }

        /** Places a domino according to the given direction.
         *  Updates the board in‑place and enqueues newly created cells for further processing. */
        private void placeDomino(int[] root, Direction dir) {
            switch (dir) {
                case VERTICAL -> placeVerticalDomino(root);
                case HORIZONTAL -> placeHorizontalDomino(root);
            }
        }

        /** Places a vertical domino covering (r,c) and the cell below it. */
        private void placeVerticalDomino(int[] pos) {
            int r = pos[0];
            int c = pos[1];

            // Determine which of the two cells is the upper half
            int topRow = (r > 0 && board[r - 1][c] == '.') ? r - 1 : r + 1;
            replaceWithVerticalMarks(topRow, c);
        }

        /** Places a horizontal domino covering (r,c) and the cell to its right. */
        private void placeHorizontalDomino(int[] pos) {
            int r = pos[0];
            int c = pos[1];

            // Determine which of the two cells is the left half
            int leftCol = (c > 0 && board[r][c - 1] == '.') ? c - 1 : c + 1;
            replaceWithHorizontalMarks(r, leftCol);
        }

        /** Writes the appropriate characters for a vertical domino.
         *  The queue is updated with neighbours that may become forced afterwards. */
        private void replaceWithVerticalMarks(int r, int c) {
            char upper = VERTICAL;
            char lower = VERTICAL_DOWN;

            // Upper half (^) or lower half (v) can be placed either way – we only need distinct symbols.
            // Here we arbitrarily assign '^' to the first row and 'v' to the second.
            board[r][c] = upper;
            board[r + 1][c] = lower;

            // Enqueue neighbours of the newly placed cells
            for (int[] d : ALL_NEIGHBOURS) {
                int nr = r + d[0];
                int nc = c + d[1];
                if (inBounds(nr, nc) && board[nr][nc] == '.') {
                    queue.addLast(new int[]{nr, nc});
                }
            }
        }

        /** Writes the appropriate characters for a horizontal domino. */
        private void replaceWithHorizontalMarks(int r, int c) {
            char left = HORIZONTAL;
            char right = HORIZONTAL_RIGHT;

            board[r][c] = left;
            board[r][c + 1] = right;

            // Enqueue neighbours of the newly placed cells
            for (int[] d : ALL_NEIGHBOURS) {
                int nr = r + d[1];   // note: d[1] is delta‑x, we keep consistent order
                int nc = c + d[0];   // delta‑y
                if (inBounds(nr, nc) && board[nr][nc] == '.') {
                    queue.addLast(new int[]{nr, nc});
                }
            }
        }

        /** Returns true if the board can be fully tiled while respecting uniqueness constraints. */
        private boolean isRemainingGraphValid() {
            boolean[][] visited = new boolean[rows][cols];

            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (board[r][c] == '.' && !visited[r][c]) {
                        // BFS to explore the connected component of empty cells
                        if (!processComponent(r, c, visited)) {
                            return false;
                        }
                    }
                }
            }
            return true;
        }

        /** Processes a single connected component of empty cells.
         *  Returns false if the component violates any uniqueness rule. */
        private boolean processComponent(int startR, int startC, boolean[][] visited) {
            // Collect all cells belonging to this component
            List<int[]> component = new ArrayList<>();
            queue.clear();
            queue.addLast(new int[]{startR, startC});
            visited[startR][startC] = true;

            while (!queue.isEmpty()) {
                int[] cur = queue.removeFirst();
                component.add(cur);
                for (int[] d : CARDINAL) {
                    int nr = cur[0] + d[0];
                    int nc = cur[1] + d[1];
                    if (inBounds(nr, nc) && board[nr][nc] == '.' && !visited[nr][nc]) {
                        visited[nr][nc] = true;
                        queue.addLast(new int[]{nr, nc});
                    }
                }
            }

            // 1️⃣ All cells must have exactly two neighbours inside the component
            //    (otherwise forced placements would have already removed them)
            for (int[] cell : component) {
                int neighbourCount = countEmptyNeighbourCount(cell[0], cell[1]);
                if (neighbourCount != 2) {
                    return false;
                }
            }

            // 2️⃣ The number of cells must be even – a component with odd size can never be tiled.
            if (component.size() % 2 != 0) {
                return false;
            }

            // 3️⃣ Find a cell that has exactly two neighbours in a distinct direction –
            //    this defines the (unique) domino orientation for the component.
            int[] start = null;
            boolean verticalMode = false;

            for (int[] cell : component) {
                int nb = countEmptyNeighbourCount(cell[0], cell[1]);
                if (nb == 2) {
                    // Determine the direction pair of the two neighbours
                    DirectionPair pair = analyseNeighbourPair(cell[0], cell[1]);
                    if (pair == null) {
                        return false;
                    }
                    if (start == null) {
                        start = cell;
                        verticalMode = pair.isVertical;
                    } else if (start != cell) {
                        // More than one candidate → non‑unique component
                        return false;
                    }
                }
            }

            if (start == null) {
                return false; // no cell with exactly two neighbours → malformed component
            }

            // 4️⃣ Finally, place all dominoes for this component following the discovered orientation.
            //    The placement algorithm is identical to the one used for forced moves,
            //    but we now know the exact orientation for the whole component.
            //    (Implementation detail – simply walk the component like a path.)
            placeComponent(start, verticalMode);
            return true;
        }

        /** Analyses the two adjacent empty neighbours of a cell that has exactly two of them.
         *  Returns a {@link DirectionPair} describing the orientation of those neighbours,
         *  or {@code null} if the pattern cannot be interpreted. */
        private DirectionPair analyseNeighbourPair(int r, int c) {
            List<int[]> neighbours = new ArrayList<>();
            for (int[] d : CARDINAL) {
                int nr = r + d[0];
                int nc = c + d[1];
                if (inBounds(nr, nc) && board[nr][nc] == '.') {
                    neighbours.add(new int[]{nr, nc});
                }
            }
            if (neighbours.size() != 2) {
                return null;
            }

            int[] n1 = neighbours.get(0);
            int[] n2 = neighbours.get(1);
            boolean vertical1 = n1[0] != r; // true if neighbour differs in row
            boolean vertical2 = n2[0] != r;
            // Both neighbours must lie on the same line (both vertical or both horizontal)
            if (vertical1 != vertical2) {
                return null;
            }

            // Determine which direction (up/down/left/right) each neighbour represents
            // We simply return a wrapper that indicates overall vertical/horizontal nature.
            return new DirectionPair(vertical1);
        }

        /** Places dominoes throughout a component whose orientation has already been decided.
         *  This method walks the component like a path, always taking the unique pair of
         *  neighbours that matches the expected orientation. */
        private void placeComponent(int root, boolean verticalMode) {
            // Simple DFS that always moves to the yet‑unvisited neighbour that respects
            // the required orientation (vertical vs horizontal). The algorithm is deterministic.
            boolean[][] visited = new boolean[rows][cols];
            queue.addLast(root);
            visited[root[0]][root[1]] = true;

            while (!queue.isEmpty()) {
                int[] cur = queue.removeFirst();
                if (board[cur[0]][cur[1]] != '.') {
                    continue;
                }

                // Determine the unique adjacent empty cell that continues the path
                Direction dir = findSingletonNeighbour(cur[0], cur[1]); // will return HORIZONTAL or VERTICAL
                // The above is a simplification – in practice we know the component's shape,
                // so we just walk to the neighbour that has not been visited yet.
                for (int[] d : CARDINAL) {
                    int nr = cur[0] + d[0];
                    int nc = cur[1] + d[1];
                    if (inBounds(nr, nc) && board[nr][nc] == '.' && !visited[nr][nc]) {
                        // place a domino between cur and (nr,nc)
                        placeDomino(cur, dirFromDelta(d));
                        visited[nr][nc] = true;
                        queue.addLast(new int[]{nr, nc});
                        break;
                    }
                }
            }
        }

        /** Converts a delta array into a {@link Direction} suitable for {@link #placeDomino}. */
        private Direction dirFromDelta(int[] delta) {
            if (delta[0] != 0) {
                return Direction.VERTICAL;
            } else {
                return Direction.HORIZONTAL;
            }
        }

        /** Returns the number of empty neighbours of a given empty cell. */
        private int countEmptyNeighbourCount(int r, int c) {
            int cnt = 0;
            for (int[] d : CARDINAL) {
                int nr = r + d[0];
                int nc = c + d[1];
                if (inBounds(nr, nc) && board[nr][nc] == '.') {
                    cnt++;
                }
            }
            return cnt;
        }

        private boolean inBounds(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }

        /** Enum describing the orientation of a domino. */
        private enum Direction {
            VERTICAL,
            HORIZONTAL
        }

        /** Simple wrapper that carries the orientation information extracted from a neighbour pair. */
        private static final class DirectionPair {
            final boolean isVertical;

            DirectionPair(boolean isVertical) {
                this.isVertical = isVertical;
            }
        }
    }
}

import java.io.PrintWriter;
import java.util.ArrayList;
import java.util.LinkedList;
import java.util.List;
import java.util.Queue;
import java.util.Scanner;

/**
 * Main class that solves the “unique tiling” puzzle.
 *
 * The program reads an {@code n × m} board consisting of '.' (empty) and
 * other characters (which are never modified).  Whenever an empty cell has
 * exactly one empty neighbour, the two cells must be linked by an arrow.
 * Arrows are written using the symbols '>', '<', '^' and 'v'.
 *
 * After all forced placements are performed, the board must be completely
 * filled; otherwise the solution is not unique and the program prints
 * {@code "Not unique"}.
 */
public class Main {

    /* Directions: down, left, up, right */
    private static final int[] DR = {1, 0, -1, 0};
    private static final int[] DC = {0, -1, 0, 1};

    private final char[][] grid;          // board representation
    private final boolean[][] visited;    // not used in final version but kept for compatibility
    private final int rows;               // number of rows
    private final int cols;               // number of columns
    private final PrintWriter out;        // output stream

    /** Constructor – reads the board from {@code Scanner}. */
    public Main(Scanner sc) {
        this.rows = sc.nextInt();
        this.cols = sc.nextInt();
        sc.nextLine();                     // consume end‑of‑line

        this.grid = new char[rows][cols];
        this.visited = new boolean[rows][cols];
        for (int r = 0; r < rows; r++) {
            Arrays.fill(grid[r], '.');
        }
        for (int r = 0; r < rows; r++) {
            String line = sc.nextLine();
            for (int c = 0; c < cols; c++) {
                grid[r][c] = line.charAt(c);
            }
        }
        this.out = new PrintWriter(System.out);
    }

    /** Number of adjacent '.' cells for a given position. */
    private int countAdjEmpty(int r, int c) {
        int cnt = 0;
        for (int d = 0; d < 4; d++) {
            int nr = r + DR[d];
            int nc = c + DC[d];
            if (inside(nr, nc) && grid[nr][nc] == '.') {
                cnt++;
            }
        }
        return cnt;
    }

    /** Returns {@code true} if {@code (r,c)} lies inside the board. */
    private boolean inside(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    /** Places an arrow from (r,c) to its unique empty neighbour (nr,nc). */
    private void placeArrow(int r, int c, int nr, int nc) {
        // write the two cells that form the directed edge
        if (r == nr) {                       // horizontal edge
            int left = Math.min(c, nc);
            int right = Math.max(c, nc);
            grid[r][left] = '>';
            grid[r][right] = '<';
        } else {                             // vertical edge
            int top = Math.min(r, nr);
            int bottom = Math.max(r, nr);
            grid[top][c] = 'v';
            grid[bottom][c] = '^';
        }

        // The newly created cell may now have become forced (exactly one free neighbour).
        for (int d = 0; d < 4; d++) {
            int nnr = nr + DR[d];
            int nnc = nc + DC[d];
            if (inside(nnr, nnc) && grid[nnr][nnc] == '.' &&
                countAdjEmpty(nnr, nnc) == 1) {
                queue.add(new int[]{nnr, nnc});
            }
        }
    }

    /** Finds the unique empty neighbour of (r,c) or returns {@code null}. */
    private int[] findUniqueEmptyNeighbour(int r, int c) {
        List<int[]> candidates = new ArrayList<>();
        for (int d = 0; d < 4; d++) {
            int nr = r + DR[d];
            int nc = c + DC[d];
            if (inside(nr, nc) && grid[nr][nc] == '.') {
                candidates.add(new int[]{nr, nc});
            }
        }
        return candidates.isEmpty() ? null : candidates.get(0);
    }

    /** Solves the puzzle and prints the result. */
    private void solve() {
        Queue<int[]> queue = new LinkedList<>();

        /* 1️⃣  Initialize the queue with all empty cells that have exactly one empty neighbour */
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '.' && countAdjEmpty(r, c) == 1) {
                    queue.add(new int[]{r, c});
                }
            }
        }

        /* 2️⃣  Propagate forced placements */
        while (!queue.isEmpty()) {
            int[] cur = queue.poll();
            int r = cur[0];
            int c = cur[1];

            // The cell might already have been filled by a previous step
            if (grid[r][c] != '.') {
                continue;
            }

            // The number of empty neighbours may have changed – nothing to do if it is not exactly one
            if (countAdjEmpty(r, c) != 1) {
                continue;
            }

            int[] neighbour = findUniqueEmptyNeighbour(r, c);
            if (neighbour == null) {
                continue;
            }
            int nr = neighbour[0];
            int nc = neighbour[1];
            placeArrow(r, c, nr, nc);
        }

        /* 3️⃣  If any empty cell remains, the solution is not unique */
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '.') {
                    out.println("Not unique");
                    out.flush();
                    return;
                }
            }
        }

        /* 4️⃣  Print the fully‑filled board */
        printSolution();
        out.flush();
    }

    /** Writes the solved board to standard output. */
    private void printSolution() {
        StringBuilder sb = new StringBuilder();
        for (char[] row : grid) {
            for (char ch : row) {
                sb.append(ch);
            }
            sb.append('\n');
        }
        out.print(sb.toString());
    }

    /** Entry point – reads input, solves, and prints the answer. */
    public static void main(String[] args) throws Exception {
        try (Scanner sc = new Scanner(System.in)) {
            new Main(sc).solve();
        }
    }
}

import java.util.ArrayDeque;
import java.util.Deque;
import java.util.Scanner;

/**
 * Solves a tiling problem on a rectangular board where each empty cell ('.')
 * must be paired with one of its orthogonal neighbours. The algorithm:
 * <ol>
 *   <li>Detects forced placements by counting how many viable neighbours a cell has.</li>
 *   <li>Whenever a cell has exactly three viable neighbours, its unique partner
 *       is enqueued for later processing.</li>
 *   <li>When a pair is finally placed, the board is updated with the appropriate
 *       directional symbols ('>', '<', 'v', '^') and neighbouring cells are re‑checked.</li>
 *   <li>If after exhausting the queue the board is completely filled the solution is
 *       unique; otherwise the result is "Not unique".</li>
 * </ol>
 *
 * The implementation is deliberately split into small, focussed methods and
 * uses expressive naming to improve readability and maintainability.
 */
public class DominoTilingSolver {

    /** Direction vectors: right, left, down, up */
    private static final int[] DX = {0, 0, 1, -1};
    private static final int[] DY = {1, -1, 0, 0};

    private final int rows;
    private final int cols;
    private final char[][] board;

    /** Queue that stores cells involved in forced placements (four ints per entry). */
    private final Deque<Integer> queue = new ArrayDeque<>();

    /**
     * Constructs a solver, reads the board from {@code System.in} and starts the solving process.
     */
    public DominoTilingSolver() {
        try (Scanner scanner = new Scanner(System.in)) {
            readDimensionsAndBoard(scanner);
            discoverForcedMoves();
            resolveQueue();
            printResult();
        }
    }

    /** Reads the board size and its contents from the scanner. */
    private void readDimensionsAndBoard(Scanner scanner) {
        rows = scanner.nextInt();
        cols = scanner.nextInt();
        board = new char[rows][cols];
        for (int r = 0; r < rows; r++) {
            board[r] = scanner.next().toCharArray();
        }
    }

    /** Initiates the search for forced moves (cells with exactly three possibilities). */
    private void discoverForcedMoves() {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                handleCell(r, c);
            }
        }
    }

    /**
     * Handles a single cell by counting its valid neighbours.
     * If exactly three are valid, the unique neighbour pair is enqueued.
     *
     * @param r row index
     * @param c column index
     */
    private void handleCell(int r, int c) {
        if (!isInside(r, c) || board[r][c] != '.') {
            return;
        }

        int viableNeighbourCount = 0;
        int neighbourRow = -1, neighbourCol = -1;

        for (int dir = 0; dir < 4; dir++) {
            int nr = r + DX[dir];
            int nc = c + DY[dir];
            if (isInside(nr, nc) && board[nr][nc] == '.') {
                viableNeighbourCount++;
                neighbourRow = nr;
                neighbourCol = nc;
            }
        }

        if (viableNeighbourCount == 3) {
            // Queue layout: [r, c, neighbourRow, neighbourCol]
            queue.add(r);
            queue.add(c);
            queue.add(neighbourRow);
            queue.add(neighbourCol);
        }
    }

    /** Main solving loop – processes forced placements until the queue empties. */
    private void resolveQueue() {
        while (!queue.isEmpty()) {
            int r1 = queue.remove();
            int c1 = queue.remove();
            int r2 = queue.remove();
            int c2 = queue.remove();

            // Skip if either cell is no longer empty (might have been resolved earlier)
            if (!isEmpty(r1, c1) || !isEmpty(r2, c2)) {
                continue;
            }

            // Determine the relative direction to decide the proper symbols
            if (r1 == r2) { // Horizontal pair
                placeHorizontal(r1, c1, r2, c2);
            } else {        // Vertical pair
                placeVertical(r1, c1, r2, c2);
            }

            // Re‑evaluate neighbours of both cells – they may now become forced
            for (int dir = 0; dir < 4; dir++) {
                enqueueIfForced(r1 + DX[dir], c1 + DY[dir]);
                enqueueIfForced(r2 + DX[dir], c2 + DY[dir]);
            }
        }
    }

    /** Places a horizontal domino (pair in the same row). */
    private void placeHorizontal(int r, int c1, int r2, int c2) {
        board[r][c1] = (c2 > c1) ? '<' : '>';
        board[r2][c2] = (c2 > c1) ? '>' : '<';
    }

    /** Places a vertical domino (pair in the same column). */
    private void placeVertical(int r1, int c, int r2, int c2) {
        board[r1][c] = (r2 > r1) ? '^' : 'v';
        board[r2][c2] = (r2 > r1) ? 'v' : '^';
    }

    /** Enqueues a cell if it has exactly three viable empty neighbours. */
    private void enqueueIfForced(int nr, int nc) {
        if (isInside(nr, nc) && isEmpty(nr, nc)) {
            handleCell(nr, nc);
        }
    }

    /** Checks whether the entire board is filled (i.e., a complete tiling exists). */
    private boolean isComplete() {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (isEmpty(r, c)) {
                    return false;
                }
            }
        }
        return true;
    }

    /** Returns true if the given coordinate is inside the board bounds. */
    private boolean isInside(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    /** Returns true if the cell at (r,c) is still empty ('.'). */
    private boolean isEmpty(int r, int c) {
        return isInside(r, c) && board[r][c] == '.';
    }

    /** Outputs the solution board if it is unique; otherwise prints "Not unique". */
    private void printResult() {
        if (isComplete()) {
            for (char[] row : board) {
                System.out.println(new String(row));
            }
        } else {
            System.out.println("Not unique");
        }
    }

    /** Entry point – simply instantiates the solver. */
    public static void main(String[] args) {
        new DominoTilingSolver();
    }
}

import java.io.*;
import java.util.*;

/**
 * Solves the “unique domino tiling” problem.
 * <p>
 * The algorithm works in three steps:
 * <ol>
 *   <li>Count for each empty cell how many adjacent empty cells it has.</li>
 *   <li>Repeatedly place forced dominoes (cells with exactly one free neighbour)
 *       and update the neighbour counts.</li>
 *   <li>If any empty cell remains the tiling is not unique; otherwise we output the
 *       board filled with the characters '&lt;', '&gt;', '^', 'v'.</li>
 * </ol>
 * </p>
 */
public class Solver implements Runnable {

    /* ------------------------------------------------------------ */
    /*                     CONSTANTS & STATE                       */
    /* ------------------------------------------------------------ */

    // Directions: down, up, right, left
    private static final int[] DX = {1, -1, 0, 0};
    private static final int[] DY = {0, 0, 1, -1};

    /** Number of rows and columns of the board. */
    private int rows, cols;

    /** The board; '.' denotes an empty cell, the other chars are the final tiles. */
    private char[][] grid;

    /** How many free neighbours each empty cell currently has. */
    private int[][] neighbourCount;

    /** Queue that holds cells which currently have exactly one free neighbour
     *  (they are “forced” and must be paired next). */
    private Deque<int[]> forcedQueue;

    /** Input / output streams used by the original template. */
    private BufferedReader reader;
    private PrintWriter writer;
    private StringTokenizer tokenizer;

    /* ------------------------------------------------------------ */
    /*                       CONSTRUCTION / PARSING                */
    /* ------------------------------------------------------------ */

    /** Reads the next whitespace‑separated token from {@link #reader}. */
    private String nextToken() throws IOException {
        while (!tokenizer.hasMoreTokens()) {
            tokenizer = new StringTokenizer(reader.readLine());
        }
        return tokenizer.nextToken();
    }

    /** Reads the next {@code int} from the input. */
    private int nextInt() throws IOException {
        return Integer.parseInt(nextToken());
    }

    /** Checks that a coordinate lies inside the board and represents an empty cell. */
    private boolean inBounds(int x, int y) {
        return x >= 0 && x < rows && y >= 0 && y < cols && grid[x][y] == '.';
    }

    /* ------------------------------------------------------------ */
    /*                     CORE ALGORITHM                           */
    /* ------------------------------------------------------------ */

    /**
     * Counts the number of adjacent empty cells for every empty cell.
     * The result is stored in {@code neighbourCount}.
     */
    private void computeNeighbourCounts() {
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] != '.') {
                    continue;
                }
                int cnt = 0;
                for (int d = 0; d < DX.length; d++) {
                    int nx = i + DX[d];
                    int ny = j + DY[d];
                    if (inBounds(nx, ny)) {
                        cnt++;
                    }
                }
                neighbourCount[i][j] = cnt;
            }
        }
    }

    /**
     * Places a forced domino that connects {@code (x,y)} with one of its neighbours.
     * The orientation characters are chosen so that the smaller coordinate
     * (lexicographically) gets the “start” symbol.
     */
    private void placeTile(int x, int y, int nx, int ny) {
        // Normalise order – (x,y) will be the “first” cell.
        int firstX = Math.min(x, nx);
        int firstY = Math.min(y, ny);
        int secondX = Math.max(x, nx);
        int secondY = Math.max(y, ny);

        if (firstX == x && firstY == y) {
            // Horizontal adjacency: '<' on the left, '>' on the right.
            grid[x][y] = '<';
            grid[nx][ny] = '>';
        } else {
            // Vertical adjacency: '^' on the top, 'v' on the bottom.
            grid[x][y] = '^';
            grid[nx][ny] = 'v';
        }
    }

    /**
     * Decrements the neighbour count of each adjacent empty cell.
     * If a neighbour’s count becomes exactly 1 it is added to the forced queue.
     */
    private void propagate(int x, int y) {
        for (int d = 0; d < DX.length; d++) {
            int nx = x + DX[d];
            int ny = y + DY[d];
            if (!inBounds(nx, ny)) {
                continue;
            }
            if (--neighbourCount[nx][ny] == 1) {
                forcedQueue.addLast(new int[]{nx, ny});
            }
        }
    }

    /** Executes the whole solving procedure and writes the result to {@code writer}. */
    private void solve() throws IOException {
        rows = nextInt();
        cols = nextInt();

        // ----- read the board -------------------------------------------------
        grid = new char[rows][];
        for (int i = 0; i < rows; i++) {
            String line = nextToken();
            grid[i] = line.toCharArray();
        }

        // ----- initialise neighbour counts ------------------------------------
        neighbourCount = new int[rows][cols];
        computeNeighbourCounts();

        // ----- queue all currently forced cells -------------------------------
        forcedQueue = new ArrayDeque<>();
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == '.' && neighbourCount[i][j] == 1) {
                    forcedQueue.addLast(new int[]{i, j});
                }
            }
        }

        // ----- repeatedly place forced dominoes ---------------------------------
        while (!forcedQueue.isEmpty()) {
            int[] cur = forcedQueue.pollFirst();
            int x = cur[0];
            int y = cur[1];

            // Cell may already have been paired – ignore stale entries.
            if (grid[x][y] != '.') {
                continue;
            }

            // Find the unique free neighbour.
            int partnerX = -1, partnerY = -1;
            for (int d = 0; d < DX.length; d++) {
                int nx = x + DX[d];
                int ny = y + DY[d];
                if (inBounds(nx, ny) && grid[nx][ny] == '.') {
                    partnerX = nx;
                    partnerY = ny;
                    break;
                }
            }
            if (partnerX == -1) {
                // This situation should never happen for a valid test case.
                continue;
            }

            // Place the domino.
            placeTile(x, y, partnerX, partnerY);

            // Update neighbour counts for both cells.
            propagate(x, y);
            propagate(partnerX, partnerY);
        }

        // ----- check whether every cell has been covered -----------------------
        boolean allCovered = true;
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == '.') {
                    allCovered = false;
                    break;
                }
            }
            if (!allCovered) {
                break;
            }
        }

        // ----- output -----------------------------------------------------------
        if (!allCovered) {
            writer.println("Not unique");
        } else {
            for (char[] row : grid) {
                writer.println(new String(row));
            }
        }
    }

    /* ------------------------------------------------------------ */
    /*                         RUNTIME ENTRY                        */
    /* ------------------------------------------------------------ */

    @Override
    public void run() {
        try {
            reader = new BufferedReader(new InputStreamReader(System.in));
            writer = new PrintWriter(System.out);
            tokenizer = null;               // will be created lazily by nextToken()
            solve();
            reader.close();
            writer.close();
        } catch (IOException e) {
            // In a competitive‑programming setting we simply exit on error.
            System.exit(0);
        }
    }

    /* ------------------------------------------------------------ */
    /*                     OPTIONAL DEBUG HELPERS                  */
    /* ------------------------------------------------------------ */

    /** Prints the given objects using {@code Arrays.deepToString}. */
    private void debug(Object... arr) {
        System.out.println(Arrays.deepToString(arr));
    }

    /** Utility to print a 1‑D int array. */
    private void print1Int(int[] a) {
        for (int v : a) {
            System.out.print(v + " ");
        }
        System.out.println();
    }

    /** Utility to print a 2‑D int array. */
    private void print2Int(int[][] a) {
        for (int[] row : a) {
            for (int v : row) {
                System.out.print(v + " ");
            }
            System.out.println();
        }
    }

    /** Classic entry point required by the original template. */
    public static void main(String[] args) {
        new Solver().run();
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.ArrayDeque;
import java.util.Arrays;
import java.util.Queue;

/**
 * Refactored version of the original solution.
 *
 * <p>This program reads a grid that consists of cells marked with '*' (border),
 * '.' (empty) or one of the arrow symbols.  The task is to fill every '.' so
 * that each empty cell points to exactly one neighbouring '.' cell and all
 * paths eventually lead to a cycle.  If more than one filling satisfies the
 * constraints the program prints “Not unique”, otherwise it prints the unique
 * final grid.
 *
 * <p>All public methods are kept small and focused, making the code easier to
 * maintain and test.
 */
public class Main {

    /* --------------------------------------------------------------------- */
    /*  Constants – character symbols used throughout the algorithm           */
    /* --------------------------------------------------------------------- */
    private static final char BORDER = '*';   // border character
    private static final char EMPTY = '.';    // empty cell
    private static final char UP = '^';
    private static final char DOWN = 'v';
    private static final char LEFT = '<';
    private static final char RIGHT = '>';

    /** Arrow that points from a cell to its neighbour when the neighbour is forced */
    private static final char[] ARROW_FROM = {DOWN, UP, RIGHT, LEFT};
    /** Opposite arrow that points back from the neighbour to the original cell */
    private static final char[] ARROW_TO = {UP, DOWN, LEFT, RIGHT};

    /** Direction vectors – up, down, left, right */
    private static final int[][] DIRECTIONS = {
            {-1, 0},   // up
            {1, 0},    // down
            {0, -1},   // left
            {0, 1}     // right
    };

    /* --------------------------------------------------------------------- */
    /*  I/O helpers                                                         */
    /* --------------------------------------------------------------------- */
    private static BufferedReader reader;
    private static StringTokenizer tokenizer;

    private static void initTokenizer() throws IOException {
        while (!tokenizer.hasMoreTokens()) {
            tokenizer = new StringTokenizer(reader.readLine());
        }
    }

    private static int readInt() throws IOException {
        initTokenizer();
        return Integer.parseInt(tokenizer.nextToken());
    }

    private static long readLong() throws IOException {
        initTokenizer();
        return Long.parseLong(tokenizer.nextToken());
    }

    /* --------------------------------------------------------------------- */
    /*  Core data structures                                                 */
    /* --------------------------------------------------------------------- */
    private static char[][] grid;          // the board with border
    private static int[][] neighborCount; // how many adjacent '.' cells each cell has
    private static Queue<Cell> forcedQueue; // cells that have exactly one empty neighbour

    /* --------------------------------------------------------------------- */
    /*  Entry point                                                          */
    /* --------------------------------------------------------------------- */
    public static void main(String[] args) throws IOException {
        reader = new BufferedReader(new InputStreamReader(System.in));

        int n = readInt();
        int m = readInt();

        initialiseBoard(n, m);
        fillBorder();

        readGrid();
        computeNeighborCounts();

        // Queue cells that are forced (exactly one possible neighbour)
        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= m; j++) {
                if (grid[i][j] == EMPTY) {
                    updateNeighborCount(i, j);
                    if (neighborCount[i][j] == 0) {
                        // No possible placement → impossible puzzle
                        System.out.println("Not unique");
                        return;
                    }
                    if (neighborCount[i][j] == 1) {
                        forcedQueue.add(new Cell(i, j));
                    }
                }
            }
        }

        solve();

        // After propagation there must be no '.' left
        if (!hasNoEmptyCells()) {
            System.out.println("Not unique");
            return;
        }

        printSolution();
    }

    /* --------------------------------------------------------------------- */
    /*  Board initialisation                                                  */
    /* --------------------------------------------------------------------- */
    private static void initialiseBoard(int n, int m) {
        // extra 1‑cell margin for simple border handling
        grid = new char[n + 2][m + 2];
        neighborCount = new int[n + 2][m + 2];

        // Fill the four borders with the block character
        Arrays.fill(grid[0], BORDER);
        Arrays.fill(grid[n + 1], BORDER);
        for (int i = 1; i <= n; i++) {
            grid[i][0] = BORDER;
            grid[i][m + 1] = BORDER;
        }
    }

    private static void fillBorder() {
        // corners already contain BORDER; nothing else required
    }

    private static void readGrid() throws IOException {
        for (int i = 1; i <= grid.length - 2; i++) {
            String line = reader.readLine();
            if (line == null) {
                break;
            }
            // left and right borders stay unchanged
            grid[i][0] = BORDER;
            grid[i][grid[i].length - 1] = BORDER;
            // copy the interior cells
            for (int j = 1; j < grid[i].length - 1; j++) {
                grid[i][j] = line.charAt(j - 1);
            }
        }
    }

    /** Re‑calculate how many adjacent '.' cells a given position has. */
    private static void updateNeighborCount(int r, int c) {
        if (grid[r][c] != EMPTY) {
            neighborCount[r][c] = 0;
            return;
        }
        int cnt = 0;
        for (int[] d : DIRECTIONS) {
            int nr = r + d[0];
            int nc = c + d[1];
            if (grid[nr][nc] == EMPTY) {
                cnt++;
            }
        }
        neighborCount[r][c] = cnt;
    }

    /** Main propagation loop – repeatedly forces placements where possible. */
    private static void solve() {
        boolean solved = true;
        while (!forcedQueue.isEmpty() && solved) {
            Cell cur = forcedQueue.poll();
            // Skip cells that have already been filled by a previous step
            if (grid[cur.r][cur.c] != EMPTY) {
                continue;
            }

            // Find the *only* neighbouring empty cell
            int dirFound = -1;
            for (int i = 0; i < 4; i++) {
                int nr = cur.r + DIRECTIONS[i][0];
                int nc = cur.c + DIRECTIONS[i][1];
                if (grid[nr][nc] == EMPTY) {
                    if (dirFound != -1) {          // more than one neighbour → impossible
                        solved = false;
                        break;
                    }
                    dirFound = i;
                }
            }
            if (!solved) {
                break;
            }

            // Place the arrows that encode the forced move
            grid[cur.r][cur.c] = ARROW_FROM[dirFound];
            grid[cur.r + DIRECTIONS[dirFound][0]][cur.c + DIRECTIONS[dirFound][1]]
                    = ARROW_TO[dirFound];

            // Update counts for the newly placed cells and re‑queue newly forced ones
            updateNeighborCount(cur.r, cur.c);
            for (int[] d : DIRECTIONS) {
                int ar = cur.r + d[0];
                int ac = cur.c + d[1];
                updateNeighborCount(ar, ac);
                if (grid[ar][ac] == EMPTY) {
                    if (neighborCount[ar][ac] == 1) {
                        forcedQueue.add(new Cell(ar, ac));
                    }
                    if (neighborCount[ar][ac] == 0) {
                        solved = false;          // dead end → impossible
                        break;
                    }
                }
            }
        }
    }

    /** Returns true if there is no '.' left in the interior of the board. */
    private static boolean hasNoEmptyCells() {
        for (int i = 1; i < grid.length - 1; i++) {
            for (int j = 1; j < grid[i].length - 1; j++) {
                if (grid[i][j] == EMPTY) {
                    return false;
                }
            }
        }
        return true;
    }

    /** Print the solved board (without the surrounding border). */
    private static void printSolution() {
        StringBuilder out = new StringBuilder();
        for (int i = 1; i < grid.length - 1; i++) {
            out.append(grid[i], 1, grid[i].length - 2);
            out.append('\n');
        }
        System.out.print(out.toString());
    }

    /* --------------------------------------------------------------------- */
    /*  Simple container for a coordinate                                    */
    /* --------------------------------------------------------------------- */
    private static final class Cell {
        final int r, c;

        Cell(int r, int c) {
            this.r = r;
            this.c = c;
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Solves the “Drazil And Tiles” puzzle.
 *
 * The algorithm works with a square grid that contains three kinds of cells:
 *   * '*' – already occupied (cannot be used)
 *   * '.' – empty and must be covered by a tile
 *   * a directional character – part of a placed tile
 *
 * The solution tries to place tiles greedily on cells that have exactly one
 * remaining neighbour. If at any point an empty cell cannot be matched, the
 * puzzle is declared *not unique*.
 *
 * The implementation is deliberately split into small, well‑named methods
 * to improve maintainability.
 */
public class DrazilAndTiles {

    /* ------------------------------------------------------------ */
    /*                         Constants                               */
    /* ------------------------------------------------------------ */
    private static final int[] DR = {1, 0, -1, 0};
    private static final int[] DC = {0, -1, 0, 1};

    /* ------------------------------------------------------------ */
    /*                         Data structures                         */
    /* ------------------------------------------------------------ */
    /** Simple container for a grid coordinate. */
    private static final class Cell {
        final int row;
        final int col;

        Cell(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }

    /** Holds the whole board as mutable characters. */
    private final char[][] board;

    /** Degree of each empty cell – number of adjacent empty neighbours. */
    private final int[][] degree;

    /** Queue used for the BFS‑like propagation of forced moves. */
    private final Queue<Cell> forcedMoves = new LinkedList<>();

    /* ------------------------------------------------------------ */
    /*                         Constructor                             */
    /* ------------------------------------------------------------ */
    public DrazilAndTiles(char[][] board) {
        this.board = board;
        int rows = board.length;
        int cols = board[0].length;
        this.degree = new int[rows][cols];
        computeDegrees();
    }

    /* ------------------------------------------------------------ */
    /*                        Private helpers                         */
    /* ------------------------------------------------------------ */

    /** Checks whether a given coordinate is inside the board. */
    private boolean isInside(int r, int c) {
        return r >= 0 && r < board.length && c >= 0 && c < board[0].length;
    }

    /** Calculates the degree (number of empty neighbours) for every cell. */
    private void computeDegrees() {
        for (int r = 0; r < board.length; r++) {
            for (int c = 0; c < board[0].length; c++) {
                if (board[r][c] == '*') {
                    continue;
                }
                int cnt = 0;
                for (int d = 0; d < 4; d++) {
                    int nr = r + DR[d];
                    int nc = c + DC[d];
                    if (isInside(nr, nc) && board[nr][nc] == '.') {
                        cnt++;
                    }
                }
                degree[r][c] = cnt;
                if (cnt == 1) {
                    forcedMoves.add(new Cell(r, c));
                }
            }
        }
    }

    /** Places a domino covering two adjacent empty cells.
     *  The direction is determined by the first applicable neighbour.
     */
    private void placeDomino(Cell start) {
        // The neighbour with degree 1 that we are expanding to
        Cell neighbour = null;
        for (int d = 0; d < 4; d++) {
            int nr = start.row + DR[d];
            int nc = start.col + DC[d];
            if (isInside(nr, nc) && board[nr][nc] == '.') {
                neighbour = new Cell(nr, nc);
                break;
            }
        }
        if (neighbour == null) {
            return; // safety – should not happen for a valid forced move
        }

        // Zero out the degrees of the two cells – they are now occupied
        degree[start.row][start.col] = 0;
        degree[neighbour.row][neighbour.col] = 0;

        // Reduce the degree of all still‑empty neighbours of the new tile
        for (int d = 0; d < 4; d++) {
            int er = neighbour.row + DR[d];
            int ec = neighbour.col + DC[d];
            if (!isInside(er, ec) || board[er][ec] != '.') {
                continue;
            }
            degree[er][ec]--;
            if (degree[er][ec] == 1) {
                forcedMoves.add(new Cell(er, ec));
            }
        }

        // Determine which direction the domino represents
        int dir = getDirection(start.row, start.col, neighbour.row, neighbour.col);
        placeDirectionalSymbols(start, neighbour, dir);
    }

    /** Returns an integer encoding the relative direction between two cells. */
    private int getDirection(int r1, int c1, int r2, int c2) {
        for (int d = 0; d < 4; d++) {
            if (r1 + DR[d] == r2 && c1 + DC[d] == c2) {
                return d;
            }
        }
        return -1; // unreachable for adjacent cells
    }

    /** Writes the appropriate characters (^, v, <, >) for the two cells of a domino. */
    private void placeDirectionalSymbols(Cell a, Cell b, int dir) {
        switch (dir) {
            case 0 -> { // a -> b is down, so a is '^' and b is 'v'
                board[a.row][a.col] = '^';
                board[b.row][b.col] = 'v';
            }
            case 1 -> { // a -> b is left
                board[a.row][a.col] = '>';
                board[b.row][b.col] = '<';
            }
            case 2 -> { // a -> b is up
                board[a.row][a.col] = 'v';
                board[b.row][b.col] = '^';
            }
            case 3 -> { // a -> b is right
                board[a.row][a.col] = '<';
                board[b.row][b.col] = '>';
            }
            default -> {
                // Should never happen – we only get valid adjacent cells.
                board[a.row][a.col] = '?';
                board[b.row][b.col] = '?';
            }
        }
    }

    /** Checks whether any empty cell remains after all forced moves have been processed. */
    private boolean isBoardComplete() {
        for (int r = 0; r < board.length; r++) {
            for (int c = 0; c < board[0].length; c++) {
                if (board[r][c] == '.') {
                    return false;
                }
            }
        }
        return true;
    }

    /* ------------------------------------------------------------ */
    /*                        Public processing                        */
    /* ------------------------------------------------------------ */

    /**
     * Executes the whole solution and writes the result to the provided PrintWriter.
     *
     * @param out where the output should be written
     */
    public void solve(PrintWriter out) {
        while (!forcedMoves.isEmpty()) {
            Cell current = forcedMoves.poll();
            // A cell can become invalid (degree 0) after we processed some of its neighbours.
            if (degree[current.row][current.col] != 1) {
                continue;
            }
            placeDomino(current);
        }

        if (isBoardComplete()) {
            for (char[] row : board) {
                out.println(new String(row));
            }
        } else {
            out.println("Not unique");
        }
    }

    /* ------------------------------------------------------------ */
    /*                          Main entry point                        */
    /* ------------------------------------------------------------ */
    public static void main(String[] args) throws IOException {
        try (MyScanner scanner = new MyScanner(System.in);
             PrintWriter writer = new PrintWriter(System.out)) {

            int rows = scanner.nextInt();
            int cols = scanner.nextInt();

            char[][] grid = new char[rows][];
            for (int r = 0; r < rows; r++) {
                grid[r] = scanner.next().toCharArray();
            }

            DrazilAndTiles solver = new DrazilAndTiles(grid);
            solver.solve(writer);
        }
    }

    /* ------------------------------------------------------------ */
    /*                       Simple I/O wrapper                       */
    /* ------------------------------------------------------------ */
    /** Minimal scanner that can read tokens from either stdin or a file. */
    private static final class MyScanner {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        MyScanner(InputStream source) {
            reader = new BufferedReader(new InputStreamReader(source));
        }

        private void fillTokenizer() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                tokenizer = new StringTokenizer(reader.readLine());
            }
        }

        String next() throws IOException {
            if (tokenizer == null || !tokenizer.hasMoreTokens()) {
                fillTokenizer();
            }
            return tokenizer.nextToken();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }

        String nextLine() throws IOException {
            return reader.readLine();
        }
    }
}

/*  --------------------------------------------------------------
 *  Tile‑placement uniqueness checker
 *  --------------------------------------------------------------
 *  The original program has been refactored to improve readability,
 *  modularity and maintainability:
 *    • Input handling is isolated in a small FastScanner class.
 *    • Board state and algorithm live in the non‑static Board class.
 *    • Directions are expressed with an enum and a small lookup table,
 *      eliminating magic numbers.
 *    • Variable names describe their purpose (row, col, obstacle, …).
 *    • The algorithm is split into small, self‑documenting methods.
 *    • All public APIs are kept tiny – only `solve()` is exposed.
 *  --------------------------------------------------------------
 */

import java.io.*;
import java.util.*;
import java.util.stream.Collectors;

/**
 * Main entry point – reads the whole input, runs the solver and prints the answer.
 */
public final class Main {
    public static void main(String[] args) throws IOException {
        new Solver().run();
    }
}

/**
 * Fast scanner that mimics the original hand‑rolled {@code BufferedReader}
 * implementation but is a bit more expressive.
 */
final class FastScanner {
    private final BufferedReader reader;
    private StringTokenizer tokenizer;

    FastScanner(InputStream in) {
        this.reader = new BufferedReader(new InputStreamReader(in));
    }

    /** Returns the next integral token, waiting for input if necessary. */
    int nextInt() throws IOException {
        return Integer.parseInt(nextToken());
    }

    /** Returns the next token (String). */
    String nextToken() throws IOException {
        while (tokenizer == null || !tokenizer.hasMoreTokens()) {
            tokenizer = new StringTokenizer(reader.readLine());
        }
        return tokenizer.nextToken();
    }

    /** Closes the underlying stream. */
    void close() throws IOException {
        reader.close();
    }
}

/**
 * Immutable representation of a board cell coordinate.
 */
final class Coord implements Comparable<Coord> {
    final int row;
    final int col;

    Coord(int row, int col) {
        this.row = row;
        this.col = col;
    }

    /** Natural order – row first, then column (mirrors the original logic). */
    @Override
    public int compareTo(Coord o) {
        int cmp = Integer.compare(this.row, o.row);
        return (cmp != 0) ? cmp : Integer.compare(this.col, o.col);
    }
}

/**
 * All possible move directions – each entry knows how to update the two
 * cells that become part of a domino.
 * <p>
 * The four directions are stored in the order used by the original
 * {@code dx}/{@code dy} arrays: up, down, left, right.
 */
enum Move {
    UP(-1, 0, '^', 'v'),   // neighbour gets '^', current gets 'v'
    DOWN(1, 0, 'v', '^'),  // neighbour gets 'v', current gets '^'
    LEFT(0, -1, '<', '>'), // neighbour gets '<', current gets '>'
    RIGHT(0, 1, '>', '<'); // neighbour gets '>', current gets '<'

    final int deltaRow;
    final int deltaCol;
    final char toNeighbour;
    final char toCurrent;

    Move(int deltaRow, int deltaCol, char toNeighbour, char toCurrent) {
        this.deltaRow = deltaRow;
        this.deltaCol = deltaCol;
        this.toNeighbour = toNeighbour;
        this.toCurrent = toCurrent;
    }
}

/**
 * Encapsulates the whole board, the tiling algorithm and the uniqueness check.
 * <p>
 * The class is deliberately small – it owns the grid, the priority queue
 * of “extendable” cells and the public {@code solve()} method that drives the
 * whole process.
 */
final class Board {
    /** Empty cell value (still to be filled). */
    private static final int EMPTY = 0;
    /** Obstacle cell value. */
    private static final int OBSTACLE = -1;
    /** Cells that have already been assigned a direction symbol. */
    private static final int FILLED = 1;

    private final int rows;
    private final int cols;
    /** Grid with an extra border of obstacles around it (simplifies checks). */
    private final int[][] grid;
    /** Queue of cells that can be extended in exactly one way. */
    private final PriorityQueue<Coord> queue;
    /** Output stream used for printing the final board. */
    private final PrintWriter out;
    /** Mapping from the numeric marker (1‑4) to the character that must be printed. */
    private static final char[] CHAR_MAP = {'<', '>', '^', 'v'};

    Board(int rows, int cols, FastScanner fs, PrintWriter out) {
        this.rows = rows;
        this.cols = cols;
        this.grid = new int[rows + 2][cols + 2];
        this.out = out;
        this.queue = new PriorityQueue<>();

        // ----- read input -------------------------------------------------
        // Surround the board with obstacles.
        for (int r = 0; r <= rows + 1; r++) {
            grid[r][0] = grid[r][cols + 1] = OBSTACLE;
        }
        for (int c = 0; c <= cols + 1; c++) {
            grid[0][c] = grid[rows + 1][c] = OBSTACLE;
        }

        // Fill obstacles from the input.
        for (int r = 1; r <= rows; r++) {
            String line = fs.nextToken();
            for (int c = 1; c <= cols; c++) {
                if (line.charAt(c - 1) == '*') {
                    grid[r][c] = OBSTACLE;
                }
            }
        }

        // Initialise queue with “extendable” empty cells.
        for (int r = 1; r <= rows; r++) {
            for (int c = 1; c <= cols; c++) {
                if (grid[r][c] == EMPTY && isExtendable(r, c)) {
                    queue.add(new Coord(r, c));
                }
            }
        }
    }

    /** Determines whether a cell currently has exactly three filled neighbours. */
    private boolean isExtendable(int r, int c) {
        int filledNeighbours = 0;
        for (int d = 0; d < Move.values().length; d++) {
            int nr = r + Move.values()[d].deltaRow;
            int nc = c + Move.values()[d].deltaCol;
            if (grid[nr][nc] == FILLED) {
                filledNeighbours++;
            }
        }
        return filledNeighbours == 3;
    }

    /** Core tiling step – finds the unique neighbour to extend and assigns symbols. */
    private void tryToPlace(Coord cur) {
        if (grid[cur.row][cur.col] != EMPTY) {
            return; // already placed earlier
        }

        // Scan the four directions in the same order the original code used.
        for (Move move : Move.values()) {
            int nr = cur.row + move.deltaRow;
            int nc = cur.col + move.deltaCol;

            if (grid[nr][nc] == EMPTY) {
                // Place the domino piece connecting (cur) and (nr,nc).
                grid[nr][nc] = FILLED;      // neighbour becomes part of the tile
                grid[cur.row][cur.col] = FILLED; // current becomes part of the tile

                // Write the direction symbols.
                outChar(nr, nc, move.toNeighbour);
                outChar(cur.row, cur.col, move.toCurrent);

                // The two cells that just changed may now become extendable.
                maybeAddToQueue(nr, nc);
                maybeAddToQueue(cur);
                return; // exactly one placement is possible per step
            }
        }
    }

    /** Writes a character into the output buffer (used while building the board). */
    private void outChar(int r, int c, char ch) {
        // We temporarily store characters in a separate 2‑D char array to avoid
        // mixing integer markers with final output. The array is created lazily.
        if (charBoard == null) {
            charBoard = new char[rows + 2][cols + 2];
            // Fill the border with sentinel values that will never be printed.
            for (int r = 0; r < charBoard.length; r++) {
                Arrays.fill(charBoard[r], 0);
            }
        }
        charBoard[r][c] = ch;
    }

    /** Lazily creates the char board and copies its contents to the final output. */
    private char[][] charBoard; // created on first use

    /** Ensures the given coordinate is added to the queue only if it is empty and extendable. */
    private void maybeAddToQueue(int r, int c) {
        if (grid[r][c] == EMPTY && isExtendable(r, c)) {
            queue.add(new Coord(r, c));
        }
    }

    /** Finishes the algorithm – either prints “Not unique” or the solved board. */
    void solve() {
        // Main placement loop – mimics the original while‑loop semantics.
        while (!queue.isEmpty()) {
            Coord cur = queue.poll();
            tryToPlace(cur);
        }

        // Verify that the whole board has been filled.
        boolean fullyFilled = true;
        for (int r = 1; r <= rows; r++) {
            for (int c = 1; c <= cols; c++) {
                if (grid[r][c] == EMPTY) {
                    fullyFilled = false;
                    break;
                }
            }
            if (!fullyFilled) {
                break;
            }
        }

        if (!fullyFilled) {
            out.println("Not unique");
        } else {
            // Produce the final printed board.
            printSolution();
        }
    }

    /** Renders the solved board to the provided PrintWriter. */
    private void printSolution() {
        // First, copy any direction characters that were written during the
        // placement steps into the final char board (if it exists).
        if (charBoard != null) {
            for (int r = 1; r <= rows; r++) {
                for (int c = 1; c <= cols; c++) {
                    if (grid[r][c] == OBSTACLE) {
                        out.print('*');
                    } else {
                        // The marker stored in charBoard is one of '<','>','^','v'.
                        out.print(charBoard[r][c]);
                    }
                }
                out.println();
            }
        } else {
            // Fallback – should never be used with the current logic,
            // but keeps the behaviour identical to the original program.
            for (int r = 1; r <= rows; r++) {
                for (int c = 1; c <= cols; c++) {
                    if (grid[r][c] == OBSTACLE) {
                        out.print('*');
                    } else {
                        // All cells are marked as “filled”; we need to infer the
                        // original direction marker from the numeric value used.
                        // The numeric marker (1‑4) corresponds to CHAR_MAP index.
                        // Since we never stored that numeric value, we reconstruct it
                        // from the position of the cell in the board – this mirrors
                        // the original “a[i][j]‑1” lookup.
                        // For simplicity we just print a placeholder space;
                        // the earlier branch (charBoard) will always be taken.
                        out.print(' ');
                    }
                }
                out.println();
            }
        }
    }
}

/**
 * The object that glues everything together – reading, solving and printing.
 */
final class Solver {
    private final FastScanner fs;
    private final PrintWriter out;

    Solver() throws IOException {
        this.fs = new FastScanner(System.in);
        this.out = new PrintWriter(new OutputStreamWriter(System.out));
    }

    /** Runs the whole solve‑pipeline and finally closes streams. */
    void run() throws IOException {
        try {
            int rows = fs.nextInt();
            int cols = fs.nextInt();
            Board board = new Board(rows, cols, fs, out);
            board.solve();
        } finally {
            fs.close();
            out.flush();
        }
    }
}

import java.io.IOException;
import java.util.ArrayDeque;
import java.util.Queue;

/**
 * Reads a grid of '.' characters and converts it into a unique tiling
 * where every '.' is paired with exactly one neighboring '.' using arrows.
 * If a unique tiling cannot be produced, the program prints "Not unique".
 */
public class DrazilTilesSolver {

    /* ------------------------------------------------------------------- */
    /*                           CONSTANTS & ENUMS                        */
    /* ------------------------------------------------------------------- */

    /** Direction offsets used for neighbour checks. */
    private static final int[][] DIR_OFFSETS = {
            {-1, 0}, // UP
            { 1, 0}, // DOWN
            { 0,-1}, // LEFT
            { 0, 1}  // RIGHT
    };

    /** Arrow symbols used in the final board. */
    private static final char UP      = '^';
    private static final char DOWN    = 'v';
    private static final char LEFT    = '<';
    private static final char RIGHT   = '>';

    /** Enum representing the four possible directions for easier readability. */
    private enum Direction { UP, DOWN, LEFT, RIGHT }

    /* ------------------------------------------------------------------- */
    /*                         INTERNAL DATA STRUCTURES                  */
    /* ------------------------------------------------------------------- */

    /** Simple immutable point holder for row/column coordinates. */
    private static final class Point {
        final int row;
        final int col;
        Point(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }

    /* ------------------------------------------------------------------- */
    /*                               API METHODS                           */
    /* ------------------------------------------------------------------- */

    /**
     * Entry point used by `main`. All I/O is performed here.
     */
    public void solve() throws IOException {
        // Use try‑with‑resources to guarantee proper closing of the Scanner.
        try (Scanner scanner = new Scanner(System.in)) {
            int rows = scanner.nextInt();
            int cols = scanner.nextInt();
            char[][] board = readBoard(scanner, rows);
            placeArrows(board);
            printResult(board);
        }
    }

    /* ------------------------------------------------------------------- */
    /*                                HELPERS                              */
    /* ------------------------------------------------------------------- */

    /** Reads the grid from the scanner. */
    private char[][] readBoard(Scanner scanner, int rows) {
        char[][] board = new char[rows][];
        for (int i = 0; i < rows; i++) {
            board[i] = scanner.next().toCharArray();
        }
        return board;
    }

    /** Main algorithm that fills the board with arrows. */
    private void placeArrows(char[][] board) {
        Queue<Point> terminals = collectTerminals(board);

        while (!terminals.isEmpty()) {
            Point cur = terminals.poll();
            Point neighbour = findOpenNeighbour(board, cur);
            if (neighbour == null) {
                System.out.println("Not unique");
                return;
            }
            placeArrow(board, cur, neighbour);
            // Newly created tiles may become new terminals.
            terminals.addAll(collectTerminalsAround(board, neighbour));
        }

        // If any '.' remains, the tiling is not unique.
        for (char[] row : board) {
            for (char cell : row) {
                if (cell == '.') {
                    System.out.println("Not unique");
                    return;
                }
            }
        }
    }

    /** Returns a queue containing the coordinates of all *terminal* cells ('.' with exactly one open neighbour). */
    private Queue<Point> collectTerminals(char[][] board) {
        Queue<Point> q = new ArrayDeque<>();
        for (int i = 0; i < board.length; i++) {
            for (int j = 0; j < board[i].length; j++) {
                if (isTerminal(board, i, j)) {
                    q.add(new Point(i, j));
                }
            }
        }
        return q;
    }

    /** Returns true if the cell at (i,j) is a terminal (open and has exactly one open neighbour). */
    private boolean isTerminal(char[][] board, int i, int j) {
        if (!isInBounds(board, i, j) || board[i][j] != '.') {
            return false;
        }
        return countOpenNeighbours(board, i, j) == 1;
    }

    /** Counts how many adjacent cells are open ('.'). */
    private int countOpenNeighbours(char[][] board, int i, int j) {
        int count = 0;
        for (int[] off : DIR_OFFSETS) {
            int ni = i + off[0];
            int nj = j + off[1];
            if (isInBounds(board, ni, nj) && board[ni][nj] == '.') {
                count++;
            }
        }
        return count;
    }

    /** Finds the single adjacent open cell of `p`. Returns null if none or more than one exist. */
    private Point findOpenNeighbour(char[][] board, Point p) {
        for (int[] off : DIR_OFFSETS) {
            int ni = p.row + off[0];
            int nj = p.col + off[1];
            if (isInBounds(board, ni, nj) && board[ni][nj] == '.') {
                return new Point(ni, nj);
            }
        }
        return null;
    }

    /** Places the appropriate arrow at `from` and its opposite at `to`. */
    private void placeArrow(char[][] board, Point from, Point to) {
        Direction dir = determineDirection(from, to);
        char arrow = switch (dir) {
            case UP    -> UP;
            case DOWN  -> DOWN;
            case LEFT  -> LEFT;
            case RIGHT -> RIGHT;
        };
        board[from.row][from.col] = arrow;
        board[to.row][to.col]      = opposite(arrow);
    }

    /** Determines the direction from `src` to `dst`. */
    private Direction determineDirection(Point src, Point dst) {
        int dr = dst.row - src.row;
        int dc = dst.col - src.col;
        return switch (dr) {
            case -1 -> Direction.UP;
            case  1 -> Direction.DOWN;
            case  0 -> {
                if (dc == -1) yield Direction.LEFT;
                else if (dc == 1) yield Direction.RIGHT;
            }
        };
        // The caller guarantees that a neighbour exists, so this is unreachable.
        yield null;
    }

    /** Returns the opposite arrow symbol for a given arrow. */
    private char opposite(char arrow) {
        return switch (arrow) {
            case UP    -> DOWN;
            case DOWN  -> UP;
            case LEFT  -> RIGHT;
            case RIGHT -> LEFT;
            default    -> '.';
        };
    }

    /** Collects all terminals that neighbour the given point (used to extend the queue). */
    private Queue<Point> collectTerminalsAround(char[][] board, Point p) {
        Queue<Point> neighbours = new ArrayDeque<>();
        for (int[] off : DIR_OFFSETS) {
            int r = p.row + off[0];
            int c = p.col + off[1];
            if (isTerminal(board, r, c)) {
                neighbours.add(new Point(r, c));
            }
        }
        return neighbours;
    }

    /** Returns true if (i,j) lies inside the board limits. */
    private boolean isInBounds(char[][] board, int i, int j) {
        return i >= 0 && i < board.length && j >= 0 && j < board[i].length;
    }

    /** Outputs the final board to stdout. */
    private void printResult(char[][] board) {
        for (char[] row : board) {
            System.out.println(new String(row));
        }
    }

    /* ------------------------------------------------------------------- */
    /*                               MAIN ENTRY                           */
    /* ------------------------------------------------------------------- */

    public static void main(String[] args) throws IOException {
        new DrazilTilesSolver().solve();
    }
}

import java.io.*;
import java.util.*;
import java.util.stream.Collectors;

/**
 * Entry point of the application.
 */
public class Main {
    public static void main(String[] args) {
        FastScanner scanner = new FastScanner(System.in);
        FastPrinter printer = new FastPrinter(System.out);
        new DominoSolver().solve(scanner, printer);
        printer.close();
    }
}

/**
 * Solves the “Domino” problem – determines whether the tile placement on the board is unique,
 * and prints either “Not unique” or the uniquely completed board.
 */
final class DominoSolver {

    /** Directions used for neighbours (right, up, left, down). */
    private enum Direction {
        RIGHT(0, 1), UP(-1, 0), LEFT(0, -1), DOWN(1, 0);

        final int dr;
        final int dc;

        Direction(int dr, int dc) {
            this.dr = dr;
            this.dc = dc;
        }
    }

    /** Simple pair of row/column indices. */
    private record Cell(int row, int col) implements Comparable<Cell> {
        @Override
        public int compareTo(Cell o) {
            int cmp = Integer.compare(this.row, o.row);
            return (cmp != 0) ? cmp : Integer.compare(this.col, o.col);
        }
    }

    /** How a domino is represented on the board after it is placed. */
    private enum Tile {
        HORIZONTAL('<', '>'),   // left cell gets '<', right cell gets '>'
        VERTICAL('^', 'v');     // upper cell gets '^', lower cell gets 'v';

        final char start, end;

        Tile(char start, char end) {
            this.start = start;
            this.end = end;
        }

        /** Place this tile on the board using the two cells that form the domino. */
        void place(char[][] board, Cell start, Cell end) {
            board[start.row][start.col] = switch (this) {
                case HORIZONTAL -> start.col < end.col ? '<' : '>';
                case VERTICAL -> start.row < end.row ? '^' : 'v';
            };
            board[end.row][end.col] = switch (this) {
                case HORIZONTAL -> end.col < start.col ? '<' : '>';
                case VERTICAL -> end.row < start.row ? '^' : 'v';
            };
        }
    }

    /** Utility class that reads input efficiently. */
    private static final class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[16_384];
        private int ptr = 0, len = 0;

        FastScanner(InputStream in) {
            this.in = in;
        }

        private int readByte() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int readInt() {
            int c;
            do {
                c = readByte();
                if (c == -1) throw new EOFException();
            } while (Character.isWhitespace((char) c));
            boolean negative = false;
            if (c == '-') {
                negative = true;
                c = readByte();
            }
            int value = 0;
            while (Character.isDigit((char) c)) {
                value = value * 10 + (c - '0');
                c = readByte();
            }
            return negative ? -value : value;
        }

        char readCharacter() {
            int c;
            do {
                c = readByte();
                if (c == -1) throw new EOFException();
            } while (Character.isWhitespace((char) c));
            return (char) c;
        }
    }

    /** Utility class that writes output efficiently. */
    private static final class FastPrinter {
        private final PrintWriter writer;

        FastPrinter(OutputStream out) {
            this.writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(out)));
        }

        void println(Object... vals) {
            for (int i = 0; i < vals.length; ++i) {
                if (i > 0) writer.print(' ');
                writer.print(vals[i]);
            }
            writer.println();
        }

        void print(Object... vals) {
            for (int i = 0; i < vals.length; ++i) {
                if (i > 0) writer.print(' ');
                writer.print(vals[i]);
            }
        }

        void close() {
            writer.close();
        }
    }

    /** Reads the board from the scanner. */
    private static char[][] readBoard(FastScanner scanner, int rows, int cols) {
        char[][] board = new char[rows][];
        for (int r = 0; r < rows; ++r) {
            board[r] = scanner.readCharacter().repeat(cols);
        }
        return board;
    }

    /** Counts empty neighbours ('.') of a cell. */
    private static int countEmptyNeighbours(char[][] board, Cell cell) {
        int count = 0;
        for (Direction d : Direction.values()) {
            Cell neighbour = new Cell(cell.row + d.dr, cell.col + d.dc);
            if (isInside(board, neighbour) && board[neighbour.row][neighbour.col] == '.') {
                ++count;
            }
        }
        return count;
    }

    /** Checks whether a cell is inside the board borders. */
    private static boolean isInside(char[][] board, Cell cell) {
        return cell.row >= 0 && cell.row < board.length &&
               cell.col >= 0 && cell.col < board[0].length;
    }

    /** Places a domino on the board if the two cells form a forced placement. */
    private static boolean tryPlaceDomino(char[][] board, Cell forced, List<Cell> queue) {
        Cell other = findPairedCell(board, forced);
        if (other == null) return false; // should never happen for a valid forced cell

        Tile tile;
        if (forced.row == other.row) {           // horizontal domino
            tile = (forced.col < other.col) ? Tile.HORIZONTAL : Tile.HORIZONTAL;
        } else {                                 // vertical domino
            tile = (forced.row < other.row) ? Tile.VERTICAL : Tile.VERTICAL;
        }

        tile.place(board, forced, other);

        // Propagation: neighbours that become forced (exactly one empty neighbour)
        for (int dir = 0; dir < 4; ++dir) {
            Cell nbr = new Cell(other.row + Direction.values()[dir].dr,
                                other.col + Direction.values()[dir].dc);
            if (isInside(board, nbr) && board[nbr.row][nbr.col] == '.') {
                int emptyCnt = countEmptyNeighbours(board, nbr);
                if (emptyCnt == 0) return false; // dead end – placement not unique
                if (emptyCnt == 1) queue.add(nbr);
            }
        }
        return true;
    }

    /** Finds the unique empty neighbour of a forced cell (used when exactly one exists). */
    private static Cell findPairedCell(char[][] board, Cell cell) {
        Cell paired = null;
        for (Direction d : Direction.values()) {
            Cell neighbour = new Cell(cell.row + d.dr, cell.col + d.dc);
            if (isInside(board, neighbour) && board[neighbour.row][neighbour.col] == '.') {
                if (paired != null) return null; // more than one neighbour – not forced
                paired = neighbour;
            }
        }
        return paired;
    }

    /** Core solving routine. */
    public void solve(FastScanner in, FastPrinter out) {
        int rows = in.readInt();
        int cols = in.readInt();
        char[][] board = readBoard(in, rows, cols);

        List<Cell> forcedQueue = new ArrayDeque<>();

        // First step – locate cells that currently have exactly one empty neighbour.
        for (int r = 0; r < rows; ++r) {
            for (int c = 0; c < cols; ++c) {
                if (board[r][c] == '.') {
                    int emptyCnt = countEmptyNeighbours(board, new Cell(r, c));
                    if (emptyCnt == 0) {
                        out.println("Not unique");
                        return;
                    }
                    if (emptyCnt == 1) {
                        forcedQueue.add(new Cell(r, c));
                    }
                }
            }
        }

        // Process forced placements iteratively.
        while (!forcedQueue.isEmpty()) {
            Cell cell = forcedQueue.remove(0);
            if (board[cell.row][cell.col] != '.') continue; // already filled

            if (!tryPlaceDomino(board, cell, forcedQueue)) {
                out.println("Not unique");
                return;
            }
        }

        // After propagation, any remaining '.' means the solution is not unique.
        if (boardHasEmpty(board)) {
            out.println("Not unique");
            return;
        }

        // Output the uniquely solved board.
        for (char[] row : board) {
            out.println(new String(row));
        }
    }

    /** Checks whether the board still contains any empty cells ('.'). */
    private static boolean boardHasEmpty(char[][] board) {
        for (char[] row : board) {
            for (char cell : row) {
                if (cell == '.') return true;
            }
        }
        return false;
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.StringTokenizer;

/**
 * Reads the whole input, solves the tiling puzzle and prints the result.
 */
public class D515 {

    public static void main(String[] args) {
        InputStream inStream = System.in;
        PrintWriter out = new PrintWriter(System.out);
        Solver solver = new Solver();

        solver.solve(1, new FastInput(reader(inStream)), out);
        out.close();
    }

    private static FastInput reader(InputStream stream) {
        return new FastInput(new BufferedReader(new InputStreamReader(stream)));
    }

    /** Core logic of the algorithm. */
    static class Solver {

        /** Grid representation – after the algorithm it contains the tiling. */
        private char[][] board;

        /** Number of rows. */
        private int rows;
        /** Number of columns. */
        private int cols;

        /** Offsets for the four directions: up, right, down, left. */
        private static final int[] DY = {-1, 0, 1, 0};
        /** Offsets for the four directions: up, right, down, left. */
        private static final int[] DX = {0, 1, 0, -1};

        /** Arrow characters that correspond to the four directions. */
        private static final char[] ARROWS = {'<', 'v', '>', '^'};

        /** Places the tiles on the board respecting the uniqueness condition. */
        public void solve(int testNumber, FastInput in, PrintWriter out) {
            readInput(in);
            fillAllEmptyCells();

            // If any empty cell remains the tiling is not unique.
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (board[i][j] == '.') {
                        out.println("Not unique");
                        return;
                    }
                }
            }

            // Output the completed board.
            for (int i = 0; i < rows; i++) {
                out.println(new String(board[i]));
            }
        }

        /** Reads the original matrix from the input. */
        private void readInput(FastInput in) {
            rows = in.nextInt();
            cols = in.nextInt();

            board = new char[rows][cols];
            for (int r = 0; r < rows; r++) {
                board[r] = in.next().toCharArray();
            }
        }

        /** Recursively tries to resolve empty cells one by one. */
        private void fillAllEmptyCells() {
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (board[r][c] == '.') {
                        dfs(r, c);
                    }
                }
            }
        }

        /** Picks a '.' cell and attempts to extend the tiling from it. */
        private void dfs(int startR, int startC) {
            int emptyNeighbours = countEmptyNeighbours(startR, startC);

            // The puzzle is only unique if there is exactly one free neighbour.
            if (emptyNeighbours != 1) {
                return;
            }

            // Find that unique neighbour.
            int dir = findDirection(startR, startC);
            int nr = startR + DY[dir];
            int nc = startC + DX[dir];

            // Place the tile with the appropriate arrows.
            board[nr][nc] = ARROWS[dir];
            board[startR][startC] = ARROWS[(dir + 2) % 4]; // opposite direction

            // Continue exploring from the newly placed tile.
            exploreNeighbour(nr, nc);
        }

        /** Counts how many orthogonal neighbours of (r,c) are still empty. */
        private int countEmptyNeighbours(int r, int c) {
            int count = 0;
            for (int d = 0; d < 4; d++) {
                int nr = r + DY[d];
                int nc = c + DX[d];
                if (isInside(nr, nc) && board[nr][nc] == '.') {
                    count++;
                }
            }
            return count;
        }

        /** Returns the index of the only empty neighbour; undefined if none or >1. */
        private int findDirection(int r, int c) {
            for (int d = 0; d < 4; d++) {
                int nr = r + DY[d];
                int nc = c + DX[d];
                if (isInside(nr, nc) && board[nr][nc] == '.') {
                    return d;
                }
            }
            // Should never reach here because caller checked count == 1.
            throw new IllegalStateException("No empty neighbour found");
        }

        /** Recursively explores neighbours of (r,c) after a tile has been placed. */
        private void exploreNeighbour(int r, int c) {
            for (int d = 0; d < 4; d++) {
                int nr = r + DY[d];
                int nc = c + DX[d];
                if (isInside(nr, nc) && board[nr][nc] == '.') {
                    dfs(nr, nc);
                }
            }
        }

        /** Checks whether coordinate (r,c) is inside the board limits. */
        private boolean isInside(int r, int c) {
            return 0 <= r && r < rows && 0 <= c && c < cols;
        }
    }

    /** Very small, fast input parser used only by D515. */
    private static final class FastInput {
        private final BufferedReader br;
        private StringTokenizer st;

        FastInput(BufferedReader br) {
            this.br = br;
        }

        /** Reads the next token, expanding the StringTokenizer lazily. */
        private void ensureTokenizer() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                String line = br.readLine();
                if (line == null) {
                    return;
                }
                st = new StringTokenizer(line);
            }
        }

        /** Returns the next token as a {@code String}. */
        String next() throws IOException {
            ensureTokenizer();
            return st.nextToken();
        }

        /** Convenience wrappers for primitive types. */
        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }
}

import java.io.IOException;
import java.util.ArrayList;
import java.util.ArrayDeque;
import java.util.List;
import java.util.Scanner;

/**
 * Refactored solver for Drazil's tiling problem.
 *
 * <p>Key improvements:
 *
 * <ul>
 *   <li>Encapsulated constants and mutable state in a dedicated class.
 *   <li>Clear method names and small, focused helper methods.
 *   <li>Removed redundant variables and magic numbers.
 *   <li>Used proper resource handling with try‑with‑resources.
 *   <li>Employed a simple queue to propagate cells with a single free neighbour.
 *   <li>Added thorough comments explaining the algorithm steps.
 * </ul>
 */
public class DrazilTiles {

    /** Directions used to explore neighbours (up, down, left, right). */
    private static final int[][] DIRECTIONS = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};

    /** The board read from input. */
    private static char[][] board;

    /** Number of rows and columns of the board. */
    private static int rows, cols;

    /** Entry point. */
    public static void main(String[] args) throws IOException {
        /*
         * Read input size and board layout, then attempt to tile the board.
         * If tiling is not uniquely determined, print "Not unique".
         * Otherwise output the fully tiled board.
         */
        try (Scanner scanner = new Scanner(System.in)) {
            readDimensionsAndBoard(scanner);
            Queue<int[]> queue = new ArrayDeque<>();

            /*
             * Repeatedly process cells that have exactly one adjacent empty cell,
             * because such cells force a deterministic placement.
             */
            boolean propagated;
            do {
                propagated = false;
                propagated = propagate(queue);
            } while (propagated);

            if (!isBoardCompletelyTiled()) {
                System.out.println("Not unique");
                return;
            }

            printBoard();
        }
    }

    /** Reads the board dimensions and the board itself from the scanner. */
    private static void readDimensionsAndBoard(Scanner scanner) {
        rows = scanner.nextInt();
        cols = scanner.nextInt();
        board = new char[rows][cols];

        for (int r = 0; r < rows; r++) {
            String line = scanner.next();
            board[r] = line.toCharArray();
        }
    }

    /** Main propagation step – tries to resolve forced tiles and enqueue neighbours. */
    private static boolean propagate(Queue<int[]> queue) {
        boolean somethingPropagated = false;

        while (!queue.isEmpty()) {
            int[] cell = queue.poll();
            int r = cell[0];
            int c = cell[1];

            if (!isFree(r, c)) {
                continue; // already processed or not free
            }

            int[] uniqueNeighbour = findOnlyFreeNeighbour(r, c);
            if (uniqueNeighbour == null) {
                continue; // No deterministic placement possible here
            }

            placeTile(r, c, uniqueNeighbour[0], uniqueNeighbour[1]);
            somethingPropagated = true;

            // The newly placed tile may enable further propagations.
            enqueueIfFree(uniqueNeighbour[0], uniqueNeighbour[1], queue);
            enqueueNeighbourhood(uniqueNeighbour[0], uniqueNeighbour[1], queue);
        }

        return somethingPropagated;
    }

    /** Returns true if the given cell is still marked as empty ('.'). */
    private static boolean isFree(int r, int c) {
        return board[r][c] == '.';
    }

    /**
     * Finds the unique adjacent empty cell, or {@code null} if there is
     * zero or more than one.
     */
    private static int[] findOnlyFreeNeighbour(int r, int c) {
        List<int[]> neighbours = new ArrayList<>(4);
        for (int[] dir : DIRECTIONS) {
            int nr = r + dir[0];
            int nc = c + dir[1];
            if (isInside(nr, nc) && isFree(nr, nc)) {
                neighbours.add(new int[]{nr, nc});
            }
        }
        return neighbours.size() == 1 ? neighbours.get(0) : null;
    }

    /** Determines whether the coordinates are within board bounds. */
    private static boolean isInside(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    /** Places a domino covering two adjacent empty cells using the appropriate symbols. */
    private static void placeTile(int r1, int c1, int r2, int c2) {
        if (c2 == c1 + 1) {               // horizontal, left → right
            board[r1][c1] = '<';
            board[r2][c2] = '>';
        } else if (c1 == c2 + 1) {        // horizontal, right → left
            board[r1][c1] = '>';
            board[r2][c2] = '<';
        } else if (r2 == r1 + 1) {        // vertical, top → bottom
            board[r1][c1] = 'v';
            board[r2][c2] = '^';
        } else {                           // vertical, bottom → top
            board[r1][c1] = '^';
            board[r2][c2] = 'v';
        }
    }

    /** Enqueues the given cell if it is still empty. */
    private static void enqueueIfFree(int r, int c, Queue<int[]> queue) {
        if (isFree(r, c)) {
            queue.add(new int[]{r, c});
        }
    }

    /** Enqueues all empty neighbours of the given cell. */
    private static void enqueueNeighbourhood(int r, int c, Queue<int[]> queue) {
        for (int[] dir : DIRECTIONS) {
            int nr = r + dir[0];
            int nc = c + dir[1];
            enqueueIfFree(nr, nc, queue);
        }
    }

    /** Checks whether every cell on the board has been filled (i.e., no '.' remain). */
    private static boolean isBoardCompletelyTiled() {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (board[r][c] == '.') {
                    return false;
                }
            }
        }
        return true;
    }

    /** Prints the solved board to standard output. */
    private static void printBoard() {
        for (char[] row : board) {
            System.out.println(new String(row));
        }
    }
}

import java.awt.Point;
import java.io.IOException;
import java.util.LinkedList;
import java.util.Queue;
import java.util.Scanner;

public class DrazilAndTiles {

    private static int n;
    private static int m;
    private static char[][] grid;
    private static final int[] DR = {1, -1, 0, 0};
    private static final int[] DC = {0, 0, 1, -1};

    private static boolean isValid(int r, int c) {
        return r >= 0 && r < n && c >= 0 && c < m;
    }

    private static void placeDomino(int i, int j, int direction) {
        int ni = i + DR[direction];
        int nj = j + DC[direction];
        if (direction == 0) {
            grid[i][j] = '^';
            grid[ni][nj] = 'v';
        } else if (direction == 1) {
            grid[i][j] = 'v';
            grid[ni][nj] = '^';
        } else if (direction == 2) {
            grid[i][j] = '<';
            grid[ni][nj] = '>';
        } else {
            grid[i][j] = '>';
            grid[ni][nj] = '<';
        }
    }

    public static void main(String[] args) throws IOException {
        Scanner scanner = new Scanner(System.in);
        n = scanner.nextInt();
        m = scanner.nextInt();
        grid = new char[n][m];

        for (int i = 0; i < n; i++) {
            String row = scanner.next();
            for (int j = 0; j < m; j++) {
                grid[i][j] = row.charAt(j);
            }
        }

        Queue<Point> queue = new LinkedList<>();
        int[][] degree = new int[n][m];

        // Initialize degree counts for all non-obstacle cells
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i][j] == '*') continue;

                for (int d = 0; d < 4; d++) {
                    int ni = i + DR[d];
                    int nj = j + DC[d];
                    if (isValid(ni, nj) && grid[ni][nj] == '.') {
                        degree[i][j]++;
                    }
                }

                if (degree[i][j] == 1) {
                    queue.add(new Point(i, j));
                }
            }
        }

        // Process tiles with only one possible connection
        while (!queue.isEmpty()) {
            Point current = queue.poll();

            for (int d = 0; d < 4; d++) {
                int ni = current.x + DR[d];
                int nj = current.y + DC[d];

                if (isValid(ni, nj) && grid[ni][nj] == '.') {
                    placeDomino(current.x, current.y, d);

                    // Update degrees for adjacent cells
                    for (int adjDir = 0; adjDir < 4; adjDir++) {
                        int ani = ni + DR[adjDir];
                        int anj = nj + DC[adjDir];

                        if (isValid(ani, anj) && grid[ani][anj] == '.') {
                            degree[ani][anj]--;
                            if (degree[ani][anj] == 1) {
                                queue.add(new Point(ani, anj));
                            }
                        }
                    }
                }
            }
        }

        // Verify complete tiling (no remaining uncovered cells)
        StringBuilder result = new StringBuilder();
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i][j] == '.') {
                    System.out.println("Not unique");
                    return;
                }
            }
            result.append(new String(grid[i])).append('\n');
        }
        System.out.print(result.toString());
    }
}

import java.io.*;
import java.util.*;

/**
 * Refactored solution for problem “B”.
 * <p>
 * The program reads a grid that contains walls (‘*’) and empty cells ('.').
 * It tries to build a unique domino tiling of the empty cells.
 * If a unique tiling exists, the grid is printed with arrows that describe the
 * tiling; otherwise the string “Not unique” is printed.
 * </p>
 */
public class B {

    /* --------------------------------------------------------------------- */
    /* Constants                                                             */
    /* --------------------------------------------------------------------- */
    private static final char WALL      = '*';
    private static final char EMPTY     = '.';
    private static final int  MOD       = 1_000_000_007;   // kept from original code

    /** Symbol used for the current cell of each direction (up, right, down, left). */
    private static final char[] CURRENT_SYMBOLS = {'v', '<', '^', '>'};
    /** Symbol used for the neighbour cell of each direction. */
    private static final char[] NEIGHBOR_SYMBOLS = {'^', '>', 'v', '<'};

    /** Direction vectors: up, right, down, left. */
    private static final int[] DR = {-1, 0, 1, 0};
    private static final int[] DC = {0, 1, 0, -1};

    /* --------------------------------------------------------------------- */
    /* I/O helpers                                                             */
    /* --------------------------------------------------------------------- */
    private final InputReader reader;
    private final OutputWriter writer;

    public B(InputReader reader, OutputWriter writer) {
        this.reader = reader;
        this.writer = writer;
    }

    /* --------------------------------------------------------------------- */
    /* Grid utilities                                                          */
    /* --------------------------------------------------------------------- */

    /** Counts empty neighbours of (r,c). */
    private int countEmptyNeighbours(char[][] grid, int r, int c) {
        int cnt = 0;
        for (int k = 0; k < 4; k++) {
            int nr = r + DR[k];
            int nc = c + DC[k];
            if (grid[nr][nc] == EMPTY) {
                cnt++;
            }
        }
        return cnt;
    }

    /** Returns true if (r,c) lies inside the inner part of the grid (excluding the border). */
    private boolean isInside(char[][] grid, int r, int c) {
        return r >= 0 && r < grid.length && c >= 0 && c < grid[0].length;
    }

    /** Fills the whole grid with wall characters (used for the outer border). */
    private void fillWithWall(char[][] grid) {
        Arrays.fill(grid, WALL);
    }

    /** Places all cells that have at most one empty neighbour into the queue. */
    private void collectForcedCells(char[][] grid, Queue<int[]> queue) {
        int n = grid.length - 2;   // inner height
        int m = grid[0].length - 2; // inner width
        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= m; j++) {
                if (grid[i][j] != EMPTY) continue;
                if (countEmptyNeighbours(grid, i, j) <= 1) {
                    queue.add(new int[]{i, j});
                }
            }
        }
    }

    /** Attempts to build the unique tiling; returns false when uniqueness is impossible. */
    private boolean buildUniqueTiling(char[][] grid) {
        Queue<int[]> q = new ArrayDeque<>();
        collectForcedCells(grid, q);
        boolean unique = true;

        while (!q.isEmpty() && unique) {
            int[] cur = q.poll();
            int r = cur[0];
            int c = cur[1];

            // already processed?
            if (grid[r][c] != EMPTY) continue;

            // locate the only empty neighbour
            int nr = -1, nc = -1, dirIdx = -1;
            for (int k = 0; k < 4; k++) {
                int rr = r + DR[k];
                int cc = c + DC[k];
                if (grid[rr][cc] == EMPTY) {
                    nr = rr;
                    nc = cc;
                    dirIdx = k;
                    break;
                }
            }

            if (nr == -1) { // no neighbour → impossible tiling
                unique = false;
                break;
            }

            // assign the arrows according to the direction index
            grid[r][c]      = CURRENT_SYMBOLS[dirIdx];
            grid[nr][nc]    = NEIGHBOR_SYMBOLS[dirIdx];

            // newly forced cells might appear around the just‑filled domino
            for (int k = 0; k < 4; k++) {
                int rr = nr + DR[k];
                int cc = nc + DC[k];
                if (isInside(grid, rr, cc) && grid[rr][cc] == EMPTY
                        && countEmptyNeighbours(grid, rr, cc) <= 1) {
                    q.add(new int[]{rr, cc});
                }
            }
        }

        // Verify that no empty cell is left unmatched.
        for (int i = 1; i < grid.length && unique; i++) {
            for (int j = 1; j < grid[i].length && unique; j++) {
                if (grid[i][j] == EMPTY) {
                    unique = false;
                }
            }
        }
        return unique;
    }

    /* --------------------------------------------------------------------- */
    /* Core solving routine                                                    */
    /* --------------------------------------------------------------------- */
    private void solve() throws IOException {
        int n = reader.nextInt();
        int m = reader.nextInt();

        // grid with a one‑cell wide border of walls to simplify bounds handling
        char[][] grid = new char[n + 2][m + 2];
        fillWithWall(grid);

        // copy the input rows
        for (int i = 1; i <= n; i++) {
            String line = reader.next();
            System.arraycopy(line.toCharArray(), 0, grid[i], 1, m);
        }

        if (buildUniqueTiling(grid)) {
            for (int i = 1; i <= n; i++) {
                for (int j = 1; j <= m; j++) {
                    writer.print(grid[i][j]);
                }
                writer.println();
            }
        } else {
            writer.println("Not unique");
        }
        writer.flush();
    }

    /* --------------------------------------------------------------------- */
    /* I/O infrastructure                                                      */
    /* --------------------------------------------------------------------- */
    public static void main(String[] args) throws IOException {
        FastScanner scanner = new FastScanner();
        PrintWriter out = new PrintWriter(System.out);
        B solver = new B(scanner, new OutputWriter(out));
        solver.solve();
        out.close();
    }

    /** Simple scanner based on StringTokenizer. */
    private static class FastScanner implements InputReader {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner() throws IOException {
            this.br = new BufferedReader(new InputStreamReader(System.in));
        }

        @Override public String next() throws IOException {
            while (st == null || !st.hasMoreTokens()) st = new StringTokenizer(br.readLine());
            return st.nextToken();
        }

        @Override public int nextInt() throws IOException { return Integer.parseInt(next()); }
        @Override public long nextLong() throws IOException { return Long.parseLong(next()); }
        @Override public double nextDouble() throws IOException { return Double.parseDouble(next()); }
    }

    /** Minimal wrapper around PrintWriter that implements Closeable. */
    private static class OutputWriter implements Closeable {
        private final PrintWriter out;
        OutputWriter(PrintWriter out) { this.out = out; }
        public void println(String s) { out.println(s); }
        public void print(Object o) { out.print(o); }
        @Override public void close() { out.close(); }
    }

    /** Minimal interface that the refactored code expects from an input source. */
    private interface InputReader {
        String next() throws IOException;
        int    nextInt() throws IOException;
        long   nextLong() throws IOException;
        double nextDouble() throws IOException;
    }
}

import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;

/**
 * Refactored Minesweeper solver.
 *
 * <p>Key improvements:
 * <ul>
 *   <li>Self‑documenting naming and constants replace magic numbers.
 *   <li>Core logic split into small, single‑purpose methods.
 *   <li>Encapsulation of grid handling and input parsing.
 *   <li>Use of {@code enum}‑style constants for cell states.
 *   <li>Clear separation between algorithmic steps and I/O.
 * </ul>
 */
public class Main {

    /* --------------------------------------------------------------------- */
    /*                           Constants                                    */
    /* --------------------------------------------------------------------- */

    /** Empty cell value (originally 0). */
    private static final byte EMPTY = 0;

    /** Border cell value used to mark the surrounding fence (originally 1). */
    private static final byte BOUND = 1;

    /** Direction markers used by the original algorithm. */
    private static final byte UP    = 9;
    private static final byte DOWN  = 8;
    private static final byte LEFT  = 7;
    private static final byte RIGHT = 6;

    /* --------------------------------------------------------------------- */
    /*                           Instance fields                               */
    /* --------------------------------------------------------------------- */

    /** Number of rows of the logical field (without the surrounding border). */
    private int rows;

    /** Number of columns of the logical field (without the surrounding border). */
    private int cols;

    /** Grid including a one‑cell border on every side. */
    private byte[][] grid;

    /** Temporary storage for cells that have to be processed later. */
    private final int[] xQueue = new int[10000];
    private final int[] yQueue = new int[10000];
    private int queueSize = 0;

    /* --------------------------------------------------------------------- */
    /*                               Entry point                               */
    /* --------------------------------------------------------------------- */

    public static void main(String[] args) {
        new Main().solve();
    }

    /* --------------------------------------------------------------------- */
    /*                               Public API                                */
    /* --------------------------------------------------------------------- */

    /** Solves the puzzle read from standard input and prints the result. */
    public void solve() {
        Scanner scanner = new Scanner(System.in);
        Parser parser = new Parser(scanner);

        readDimensions(parser);
        allocateGrid();
        fillBorderWithBoundValues();
        readInputMines(parser);
        processAllForcedMoves();

        // If after exhaustive processing any interior cell is still EMPTY,
        // the solution is not unique.
        if (anyInteriorEmptyCell()) {
            System.out.print("Not unique");
            return;
        }

        printResult();
    }

    /* --------------------------------------------------------------------- */
    /*                         Private Helpers (I/O)                         */
    /* --------------------------------------------------------------------- */

    /** Reads the size of the field. */
    private void readDimensions(Parser parser) {
        rows = parser.nextInteger();
        cols = parser.nextInteger();
        parser.nextLine(); // consume end‑of‑line
    }

    /** Allocates the internal grid (border + logical area). */
    private void allocateGrid() {
        grid = new byte[rows + 2][cols + 2];
        // allocate temporary queue storage
        int capacity = rows * cols;
        xQueue = new int[capacity];
        yQueue = new int[capacity];
        queueSize = 0;
    }

    /** Fills the outer border with the BOUND constant (originally "one"). */
    private void fillBorderWithBoundValues() {
        for (int r = 0; r < grid.length; r++) {
            grid[r][0] = BOUND;
            grid[r][grid[0].length - 1] = BOUND;
        }
        for (int c = 0; c < grid[0].length; c++) {
            grid[0][c] = BOUND;
            grid[grid.length - 1][c] = BOUND;
        }
    }

    /** Reads the actual field lines and sets mines (BOUND) where '*' appears. */
    private void readInputMines(Parser parser) {
        for (int r = 1; r <= rows; r++) {
            String line = parser.nextLine();
            for (int c = 1; c <= cols; c++) {
                if (line.charAt(c - 1) == '*') {
                    set(r, c, BOUND);
                }
            }
        }
    }

    /* --------------------------------------------------------------------- */
    /*                         Core Algorithm (Queuing)                        */
    /* --------------------------------------------------------------------- */

    /** Main driver – scans the whole interior and propagates forced moves. */
    private void processAllForcedMoves() {
        // First pass: try every interior cell.
        for (int r = 1; r <= rows; r++) {
            for (int c = 1; c <= cols; c++) {
                if (grid[r][c] == EMPTY) {
                    tryResolve(r, c);
                }
            }
        }

        // Second pass: handle cells that were queued during resolution.
        while (queueSize > 0) {
            int r = xQueue[--queueSize];
            int c = yQueue[queueSize];
            tryResolve(r, c);
        }
    }

    /** Attempts to resolve a single EMPTY cell.
     * @throws IllegalStateException if the pre‑conditions for a forced move are not met.
     */
    private void tryResolve(int r, int c) throws IllegalStateException {
        if (grid[r][c] != EMPTY) {
            return; // already processed
        }

        int emptyNeighbourCount = countEmptyNeighbours(r, c, EMPTY);
        if (emptyNeighbourCount != 1) {
            throw new IllegalStateException(); // cannot decide now
        }

        Point neighbour = findSingleEmptyNeighbour(r, c);
        if (neighbour == null) {
            throw new IllegalStateException();
        }

        // Determine direction from (r,c) to the neighbour.
        byte direction = directionFromOffset(neighbour.x - r, neighbour.y - c);

        // Store the direction on the neighbour cell.
        set(neighbour.x, neighbour.y, direction);
        // Store the opposite direction on the current cell (mirrors original behaviour).
        set(r, c, opposite(direction));

        // Enqueue surrounding cells so that the propagation continues.
        enqueue(neighbour.x - 1, neighbour.y);          // original offsets: i‑2, j
        enqueue(neighbour.x,     neighbour.y - 1);    // original offsets: i‑1, j‑1
        enqueue(neighbour.x,     neighbour.y + 1);    // original offsets: i‑1, j+1
    }

    /** Counts how many neighbours of (r,c) contain the supplied value. */
    private int countEmptyNeighbours(int r, int c, byte value) {
        int cnt = 0;
        if (grid[r - 1][c] == value) cnt++;
        if (grid[r + 1][c] == value) cnt++;
        if (grid[r][c - 1] == value) cnt++;
        if (grid[r][c + 1] == value) cnt++;
        return cnt;
    }

    /** Returns the unique adjacent empty neighbour, or {@code null} if there are none or many. */
    private Point findSingleEmptyNeighbour(int r, int c) {
        Point result = null;
        int[] dr = {-1, 1, 0, 0};
        int[] dc = {0, 0, -1, 1};
        for (int i = 0; i < 4; i++) {
            int nr = r + dr[i];
            int nc = c + dc[i];
            if (grid[nr][nc] == EMPTY) {
                if (result != null) {
                    return null; // more than one empty neighbour
                }
                result = new Point(nr, nc);
            }
        }
        return result;
    }

    /** Determines the direction byte that corresponds to the given offset. */
    private byte directionFromOffset(int dr, int dc) {
        return switch (dr) {
            case -1 -> UP;
            case 1 -> DOWN;
            case 0 -> {
                if (dc == -1) yield LEFT;
                else if (dc == 1) yield RIGHT;
                else continue;
            }
            default -> {
                if (dc == -1) yield LEFT;
                else if (dc == 1) yield RIGHT;
                else continue;
            }
        };
    }

    /** Returns the opposite direction of the supplied one. */
    private byte opposite(byte dir) {
        return switch (dir) {
            case UP -> DOWN;
            case DOWN -> UP;
            case LEFT -> RIGHT;
            case RIGHT -> LEFT;
            default -> BOUND;
        };
    }

    /** Stores a coordinate pair in the internal queue (used by the original algorithm). */
    private void enqueue(int x, int y) {
        if (grid[x][y] != EMPTY) {
            return;
        }
        xQueue[queueSize] = x;
        yQueue[queueSize++] = y;
    }

    /* --------------------------------------------------------------------- */
    /*                         Utility Checks & Output                        */
    /* --------------------------------------------------------------------- */

    /** Checks whether any interior cell is still EMPTY after processing. */
    private boolean anyInteriorEmptyCell() {
        for (int r = 1; r <= rows; r++) {
            for (int c = 1; c <= cols; c++) {
                if (grid[r][c] == EMPTY) {
                    return true;
                }
            }
        }
        return false;
    }

    /** Prints the solved board using the same characters as the original program. */
    private void printResult() {
        StringBuilder out = new StringBuilder();
        for (int r = 1; r <= rows; r++) {
            for (int c = 1; c <= cols; c++) {
                byte cell = grid[r][c];
                switch (cell) {
                    case BOUND -> out.append('*');          // mine cells
                    case UP -> out.append('^');
                    case DOWN -> out.append('v');
                    case LEFT -> out.append('<');
                    case RIGHT -> out.append('>');
                    default -> out.append('?'); // should never happen
                }
            }
            out.append('\n');
        }
        System.out.print(out.toString());
    }

    /* --------------------------------------------------------------------- */
    /*                               Cell State                               */
    /* --------------------------------------------------------------------- */

    /** Simple holder for a coordinate pair used during processing. */
    private static final class Point {
        final int x, y;
        Point(int x, int y) { this.x = x; this.y = y; }
    }

    /* --------------------------------------------------------------------- */
    /*                               Input Parser                              */
    /* --------------------------------------------------------------------- */

    /** Minimalist scanner wrapper used by {@link #solve()}. */
    private static final class Parser {
        private final Scanner scanner;

        Parser(Scanner scanner) { this.scanner = scanner; }

        int nextInteger() { return scanner.nextInt(); }

        String nextLine() { return scanner.nextLine(); }
    }
}

/*  TilePlacementSolver
 *
 *  Reads a rectangular board ('.' denotes an empty cell) and attempts to tile it
 *  with 2×1 dominoes. If the tiling is unique the program prints the board with
 *  characters '<', '>', '^' and 'v' representing the orientation of each domino.
 *  Otherwise it prints "Not unique".
 *
 *  The algorithm works by repeatedly selecting a cell with exactly one free
 *  neighbour (degree == 1) and fixing the domino that must cover it.  The
 *  degrees of affected neighbours are updated and the process continues
 *  until no empty cells remain (successful unique tiling) or the algorithm
 *  gets stuck (multiple tilings or impossibility).
 *
 *  The implementation follows the original logic but is organized into
 *  clearly named methods, uses proper Java naming conventions and removes
 *  unused or confusing code.
 */
import java.io.IOException;
import java.io.InputStream;
import java.io.PrintWriter;
import java.util.Stack;

public class TilePlacementSolver {

    /** Simple container for a cell position on the board. */
    private static final class Cell {
        final int row;
        final int col;

        Cell(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }

    /** Wrapper around a fast byte‑based input reader. */
    private static final class InputReader {
        private final InputStream stream;
        private final byte[] buffer = new byte[1024];
        private int currentByte;
        private int bytesRead;

        InputReader(InputStream stream) {
            this.stream = stream;
        }

        /** Reads the next byte, returning -1 when the stream ends. */
        private int readByte() {
            if (currentByte >= bytesRead) {
                currentByte = 0;
                bytesRead = stream.read(buffer);
                if (bytesRead <= 0) {
                    return -1;
                }
            }
            return buffer[currentByte++];
        }

        /** Skips whitespace characters. */
        private int skipWhitespace(int c) {
            while (!Character.isWhitespace(c) && c != -1) {
                c = readByte();
            }
            return c;
        }

        /** Reads the next token as a string. */
        String nextString() {
            int c = skipWhitespace(readByte());
            if (c == -1) {
                throw new InputMismatchException();
            }
            StringBuilder sb = new StringBuilder();
            do {
                sb.append((char) c);
                c = readByte();
            } while (!Character.isWhitespace(c) && c != -1);
            return sb.toString();
        }

        /** Reads the next token as a long (handles optional leading '-'). */
        long nextLong() {
            int c = skipWhitespace(readByte());
            if (c == -1) {
                throw new InputMismatchException();
            }
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = readByte();
            }
            long value = 0;
            do {
                if (c < '0' || c > '9') {
                    throw new InputMismatchException();
                }
                value = value * 10 + (c - '0');
                c = readByte();
            } while (!Character.isWhitespace(c) && c != -1);
            return value * sign;
        }

        /** Convenience method for reading the next integer. */
        int nextInt() {
            return (int) nextLong();
        }
    }

    /** Fast output wrapper around a PrintWriter. */
    private static final class OutputWriter extends PrintWriter {
        OutputWriter(InputStream out) {
            super(new PrintWriter(new java.io.OutputStreamWriter(out)));
        }

        /** Prints the result and closes the writer. */
        void closeAndFlush() {
            flush();
            super.close();
        }
    }

    /** Solves a single test case. */
    private static void solve(InputReader reader, OutputWriter out) {
        /* ---- read dimensions ------------------------------------------------ */
        final int rows = reader.nextInt();
        final int cols = reader.nextInt();

        /* ---- build the board with a border of non‑empty cells ----------------- */
        char[][] board = new char[rows + 2][cols + 2];
        for (int r = 1; r <= rows; r++) {
            // copy the input line, adjusting indices to keep the border
            reader.nextString().toCharArray().copyOfRange(0, cols, 0, board[r + 1]);
            // place the line inside the bordered array
            System.arraycopy(
                    reader.nextString().toCharArray(),
                    0,
                    board[r + 1],
                    1,
                    cols);
        }

        /* ---- compute degree (number of adjacent empty cells) for each cell ---- */
        final int[][] degree = new int[rows + 2][cols + 2];
        final Stack<Cell> frontier = new Stack<>();

        final int emptyCellCount = countEmptyCells(board, degree, frontier);

        /* ---- main tiling loop ------------------------------------------------- */
        while (!frontier.isEmpty()) {
            Cell current = frontier.pop();

            // If cell was already filled or its degree changed, skip it.
            if (board[current.row][current.col] != '.' || degree[current.row][current.col] != 1) {
                continue;
            }

            // Determine which neighbouring cell is empty and place the domino.
            if (board[current.row][current.col - 1] == '.') {
                placeHorizontal(left: current.row, leftCol: current.col - 1, rightCol: current.col, out);
                decrementDegrees(degree, current.row, current.col - 1, frontier);
            } else if (board[current.row][current.col + 1] == '.') {
                placeHorizontal(left: current.row, leftCol: current.col, rightCol: current.col + 1, out);
                decrementDegrees(degree, current.row, current.col + 1, frontier);
            } else if (board[current.row + 1][current.col] == '.') {
                placeVertical(topRow: current.row, bottomRow: current.row + 1, col: current.col, out);
                decrementDegrees(degree, current.row + 1, current.col, frontier);
            } else if (board[current.row - 1][current.col] == '.') {
                placeVertical(topRow: current.row - 1, bottomRow: current.row, col: current.col, out);
                decrementDegrees(degree, current.row - 1, current.col, frontier);
            } else {
                // No free neighbour -> impossibility (should not happen in a valid case)
                break;
            }

            emptyCellCount -= 2; // two cells are now occupied
        }

        /* ---- output the result ------------------------------------------------ */
        if (emptyCellCount != 0) {
            out.println("Not unique");
        } else {
            for (int r = 1; r <= rows; r++) {
                for (int c = 1; c <= cols; c++) {
                    out.print(board[r][c]);
                }
                out.println();
            }
        }
    }

    /** Counts empty cells, fills the degree matrix and pushes cells with degree 1
     *  onto the supplied stack. */
    private static int countEmptyCells(char[][] board, int[][] degree, Stack<Cell> stack) {
        int count = 0;
        for (int r = 1; r <= board.length - 2; r++) {
            for (int c = 1; c <= board[r].length - 2; c++) {
                if (board[r][c] != '.') {
                    continue;
                }
                count++;
                // horizontal neighbour
                if (board[r][c + 1] == '.') {
                    degree[r][c]++;
                    degree[r][c + 1]++;
                }
                // vertical neighbour
                if (board[r + 1][c] == '.') {
                    degree[r][c]++;
                    degree[r + 1][c]++;
                }
                if (degree[r][c] == 1) {
                    stack.push(new Cell(r, c));
                }
            }
        }
        return count;
    }

    /** Places a horizontal domino (left -> right) on the board. */
    private static void placeHorizontal(char[][] board, int row, int leftCol, int rightCol, OutputWriter out) {
        board[row][leftCol] = '<';
        board[row][rightCol] = '>';
    }

    /** Places a vertical domino (top -> bottom) on the board. */
    private static void placeVertical(char[][] board, int topRow, int bottomRow, int col, OutputWriter out) {
        board[topRow][col] = '^';
        board[bottomRow][col] = 'v';
    }

    /** Decrements degrees of the given cell and its four orthogonal neighbours,
     *  pushing any neighbour whose degree becomes exactly 1 onto the stack. */
    private static void decrementDegrees(int[][] degree, int row, int col, Stack<Cell> stack) {
        degree[row][col] = 0; // current cell is now fixed

        int[][] dirs = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};
        for (int[] d : dirs) {
            int nr = row + d[0];
            int nc = col + d[1];
            degree[nr][nc]--;
            if (degree[nr][nc] == 1) {
                stack.push(new Cell(nr, nc));
            }
        }
    }

    /** Entry point. */
    public static void main(String[] args) {
        final InputReader in = new InputReader(System.in);
        final OutputWriter out = new OutputWriter(System.out);
        try {
            solve(in, out);
        } finally {
            out.closeAndFlush();
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Reads a grid that contains '.' characters and tries to fill every '.' with
 * an arrow that points to a neighbouring '.' in a uniquely deterministic way.
 * If a unique assignment is impossible the program prints "Not unique".
 *
 * The algorithm:
 *   1. Count how many empty neighbours each '.' cell has (its "degree").
 *   2. Put every '.' cell with degree 1 into a queue.
 *   3. Repeatedly take a queued cell, match it with its only empty neighbour,
 *      write the appropriate arrows, and reduce degrees of affected neighbours.
 *   4. If after the process any '.' cells remain, the solution is not unique.
 *
 * The refactor focuses on readability, naming, encapsulation and proper resource
 * handling while preserving exact functionality.
 */
public class Main {

    /* -------------------------------------------------------------
     *  Direction handling
     * ------------------------------------------------------------- */
    /** The four orthogonal directions. */
    private enum Direction {
        UP(-1, 0, '^', 'v'),
        DOWN(1, 0, 'v', '^'),
        LEFT(0, -1, '<', '>'),
        RIGHT(0, 1, '>', '<');

        private final int dx;
        private final int dy;
        private final char source;   // symbol written in the current cell
        private final char target;   // symbol written in the neighbour cell

        Direction(int dx, int dy, char source, char target) {
            this.dx = dx;
            this.dy = dy;
            this.source = source;
            this.target = target;
        }

        /** Row offset. */
        int deltaX() { return dx; }

        /** Column offset. */
        int deltaY() { return dy; }

        /** Symbol for the current cell (points toward the neighbour). */
        char sourceChar() { return source; }

        /** Symbol for the neighbour cell (points back toward the current cell). */
        char targetChar() { return target; }
    }

    /** All directions in a stable order for iteration. */
    private static final Direction[] ALL_DIRECTIONS = Direction.values();

    /* -------------------------------------------------------------
     *  Helper utilities
     * ------------------------------------------------------------- */
    /** Returns true if the coordinates are inside the grid and the cell is empty ('.'). */
    private static boolean isInside(int x, int y, char[][] grid) {
        return x >= 0 && y >= 0 && x < grid.length && y < grid[0].length && grid[x][y] == '.';
    }

    /** Formats the solved grid as a single string (each row terminated by '\n'). */
    private static String formatSolution(char[][] grid) {
        StringBuilder sb = new StringBuilder();
        for (char[] row : grid) {
            sb.append(row).append('\n');
        }
        return sb.toString();
    }

    /* -------------------------------------------------------------
     *  Core algorithm
     * ------------------------------------------------------------- */
    /**
     * Executes the unique‑matching algorithm.
     *
     * @param grid the mutable grid to process
     * @return either the solved grid (with arrows) or the literal string "Not unique"
     */
    private static String solve(char[][] grid) {
        final int rows = grid.length;
        final int cols = grid[0].length;
        final int cellCount = rows * cols;

        int[] degree = new int[cellCount];   // number of adjacent empty cells for each cell
        boolean[] inQueue = new boolean[cellCount];
        Queue<Integer> queue = new ArrayDeque<>();

        // 1️⃣  Compute initial degree for each empty cell and fill the queue
        int emptyCellCount = 0;
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == '.') {
                    ++emptyCellCount;
                    for (Direction dir : ALL_DIRECTIONS) {
                        int ni = i + dir.deltaX();
                        int nj = j + dir.deltaY();
                        if (isInside(ni, nj, grid)) {
                            ++degree[i * cols + j];
                        }
                    }
                    if (degree[i * cols + j] == 1) {
                        inQueue[i * cols + j] = true;
                        queue.add(i * cols + j);
                    }
                }
            }
        }

        // 2️⃣  Process the queue
        while (!queue.isEmpty()) {
            int curId = queue.poll();
            --emptyCellCount;            // we are about to “consume” this empty cell

            int x = curId / cols;
            int y = curId % cols;

            boolean matched = grid[x][y] != '.';   // becomes true once we assign an arrow here

            for (Direction dir : ALL_DIRECTIONS) {
                int nx = x + dir.deltaX();
                int ny = y + dir.deltaY();

                if (!isInside(nx, ny, grid)) {
                    continue;
                }

                int neighId = nx * cols + ny;
                // Reduce neighbour's degree because one adjacent empty cell is no longer empty
                if (--degree[neighId] == 1) {
                    if (!inQueue[neighId]) {
                        inQueue[neighId] = true;
                        queue.add(neighId);
                    }
                }

                // If we haven't written an arrow yet, try to match with this neighbour
                if (!matched) {
                    matched = true;
                    grid[x][y] = dir.sourceChar();
                    grid[nx][ny] = dir.targetChar();

                    if (!inQueue[neighId]) {
                        inQueue[neighId] = true;
                        queue.add(neighId);
                    }
                }
            }

            // If a match could not be made, this cell stays empty → non‑unique solution
            if (!matched) {
                ++emptyCellCount;
            }
        }

        // 3️⃣  Determine final outcome
        return emptyCellCount == 0 ? formatSolution(grid) : "Not unique";
    }

    /* -------------------------------------------------------------
     *  Scanner utilities (compatible with InputStream, Reader, etc.)
     * ------------------------------------------------------------- */
    /** Simple scanner that works with any BufferedReader source. */
    private static class Scanner {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public Scanner(InputStream in) {
            this.reader = new BufferedReader(new InputStreamReader(in));
        }

        public Scanner(FileReader fileReader) {
            this.reader = new BufferedReader(fileReader);
        }

        /** Skips whitespace and prepares the next token. */
        private void ensureTokenizer() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                String line = reader.readLine();
                if (line == null) {
                    return; // EOF
                }
                tokenizer = new StringTokenizer(line);
            }
        }

        public String next() throws IOException {
            ensureTokenizer();
            return tokenizer.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }

    /* -------------------------------------------------------------
     *  Entry point
     * ------------------------------------------------------------- */
    public static void main(String[] args) throws IOException {
        // The original code read from stdin; we keep that behaviour.
        Scanner scanner = new Scanner(System.in);
        int n = scanner.nextInt();
        int m = scanner.nextInt();

        char[][] grid = new char[n][];
        for (int i = 0; i < n; i++) {
            grid[i] = scanner.next().toCharArray();
        }

        String result = solve(grid);
        System.out.print(result);
        System.out.flush();   // mimic the original PrintWriter behaviour
    }
}

import java.io.PrintWriter;
import java.util.ArrayDeque;
import java.util.Queue;
import java.util.Scanner;

/**
 * Entry point of the application.
 * Reads input, runs the solver and prints the result.
 */
public final class Main {

    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in);
             PrintWriter out = new PrintWriter(System.out, true)) {

            Solver solver = new Solver();
            solver.solve(scanner, out);
        }
    }

    /**
     * Core logic that determines whether the puzzle has a unique solution
     * and fills the grid accordingly.
     */
    private static final class Solver {

        /** Four possible movement directions (up, down, left, right). */
        private enum Direction {
            UP(-1, 0), DOWN(1, 0), LEFT(0, -1), RIGHT(0, 1);

            final int deltaRow;
            final int deltaCol;

            Direction(int dr, int dc) {
                this.deltaRow = dr;
                this.deltaCol = dc;
            }
        }

        /** Characters used to fill a pair of adjacent empty cells. */
        private static final char[][] ARROW_FROM_DIRECTION = new char[][]{
                {'>', '<', 'v', '^'},   // arrow placed on the current cell
                {'<', '>', '^', 'v'}    // arrow placed on the neighbour cell
        };

        private int rows;
        private int columns;
        private char[][] grid;
        private int[] degree;          // degree of each cell (number of adjacent empty cells)
        private boolean[] inQueue;     // whether a cell is already enqueued
        private final Queue<Integer> queue = new ArrayDeque<>();

        /** Number of empty cells that remain unresolved – used to detect non‑unique solutions. */
        private int unresolvedEmptyCells;

        public void solve(Scanner scanner, PrintWriter out) {
            readInput(scanner);
            propagate();
            printResult(out);
        }

        /** Parses the input data and initialises auxiliary structures. */
        private void readInput(Scanner scanner) {
            rows = scanner.nextInt();
            columns = scanner.nextInt();
            grid = new char[rows][];

            for (int r = 0; r < rows; r++) {
                grid[r] = scanner.next().toCharArray();
            }

            degree = new int[rows * columns];
            inQueue = new boolean[rows * columns];

            initializeDegrees();
            enqueueAllDegreeOneCells();
        }

        /** Computes for each empty cell how many adjacent empty cells it has. */
        private void initializeDegrees() {
            int temporaryEmptyCount = 0;

            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < columns; c++) {
                    if (grid[r][c] == '.') {
                        temporaryEmptyCount++;
                        for (Direction dir : Direction.values()) {
                            int nr = r + dir.deltaRow;
                            int nc = c + dir.deltaCol;
                            if (isInside(nr, nc) && grid[nr][nc] == '.') {
                                degree[r * columns + c]++;
                            }
                        }
                        if (degree[r * columns + c] == 1) {
                            enqueueCell(r, c);
                        }
                    }
                }
            }
            unresolvedEmptyCells = temporaryEmptyCount;
        }

        /** Enqueues every empty cell whose degree is exactly one. */
        private void enqueueAllDegreeOneCells() {
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < columns; c++) {
                    if (grid[r][c] == '.' && degree[r * columns + c] == 1) {
                        enqueueCell(r, c);
                    }
                }
            }
        }

        /** Main BFS‑like propagation that resolves the puzzle step by step. */
        private void propagate() {
            while (!queue.isEmpty()) {
                int idx = queue.poll();
                int r = idx / columns;
                int c = idx % columns;
                boolean matched = grid[r][c] != '.';

                for (Direction dir : Direction.values()) {
                    int nr = r + dir.deltaRow;
                    int nc = c + dir.deltaCol;

                    if (!isInside(nr, nc)) {
                        continue;
                    }

                    int neighborIdx = nr * columns + nc;
                    degree[neighborIdx]--;

                    if (degree[neighborIdx] == 1) {
                        enqueueCell(nr, nc);
                    }

                    if (!matched) {
                        matched = true;
                        grid[r][c] = ARROW_FROM_DIRECTION[0][dir.ordinal()];
                        grid[nr][nc] = ARROW_FROM_DIRECTION[1][dir.ordinal()];
                        if (!inQueue[neighborIdx]) {
                            enqueueCell(nr, nc);
                        }
                    }
                }

                if (!matched) {
                    // The cell could not be paired → puzzle does not have a unique solution.
                    unresolvedEmptyCells++;
                }
            }

            if (unresolvedEmptyCells != 0) {
                System.out.println("Not unique");
            } else {
                for (char[] row : grid) {
                    System.out.println(row);
                }
            }
        }

        /** Utility to push a grid coordinate into the processing queue. */
        private void enqueueCell(int r, int c) {
            int pos = r * columns + c;
            inQueue[pos] = true;
            queue.add(pos);
        }

        /** Checks whether a coordinate is inside the grid and still empty. */
        private boolean isInside(int r, int c) {
            return r >= 0 && c >= 0 && r < rows && c < columns && grid[r][c] == '.';
        }
    }
}

import java.io.*;
import java.util.*;

public class DominoSolver {

    /** Simple coordinate class used throughout the algorithm. */
    private static final class Coord implements Comparable<Coord> {
        final int row;
        final int col;

        Coord(int row, int col) {
            this.row = row;
            this.col = col;
        }

        @Override
        public int compareTo(Coord other) {
            if (row != other.row) {
                return Integer.compare(row, other.row);
            }
            return Integer.compare(col, other.col);
        }

        @Override
        public boolean equals(Object o) {
            if (this == o) return true;
            if (!(o instanceof Coord)) return false;
            Coord other = (Coord) o;
            return row == other.row && col == other.col;
        }

        @Override
        public int hashCode() {
            return Objects.hash(row, col);
        }
    }

    /** Entry point – reads input, solves the puzzle and prints the result. */
    public static void main(String[] args) throws IOException {
        // BufferedReader + PrintWriter mimic the original I/O handling.
        try (BufferedReader br = new BufferedReader(
                new InputStreamReader(System.in))) {

            String[] dimensions = br.readLine().split("\\s+");
            int rows = Integer.parseInt(dimensions[0]);
            int cols = Integer.parseInt(dimensions[1]);

            char[][] grid = new char[rows][];
            for (int r = 0; r < rows; r++) {
                grid[r] = br.readLine().toCharArray();
            }

            solveAndPrint(grid);
        }
    }

    /** Orchestrates solving and output. */
    private static void solveAndPrint(char[][] grid) {
        if (!hasUniqueDominoTiling(grid)) {
            System.out.println("Not unique");
            return;
        }
        printSolution(grid);
    }

    /** Checks whether the grid admits a *unique* domino tiling.
     *  Returns true only if every '.' cell can be forced into a single
     *  placement sequence and the whole board becomes filled. */
    private static boolean hasUniqueDominoTiling(char[][] grid) {
        int rows = grid.length;
        int cols = grid[0].length;
        Deque<Coord> queue = new ArrayDeque<>();

        // Seed the queue with all cells that currently have exactly one empty neighbour.
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '.') {
                    List<Coord> neighbours = getEmptyNeighbours(grid, r, c, rows, cols);
                    if (neighbours.size() == 1) {
                        queue.addLast(new Coord(r, c));
                    }
                }
            }
        }

        // Process forced placements iteratively.
        while (!queue.isEmpty()) {
            Coord cur = queue.pollFirst();
            if (grid[cur.row][cur.col] != '.') {
                continue; // already handled
            }

            List<Coord> neighbours = getEmptyNeighbours(grid, cur.row, cur.col, rows, cols);
            if (neighbours.size() != 1) {
                continue; // situation changed – skip for now
            }

            Coord partner = neighbours.get(0);
            placeDomino(grid, cur.row, cur.col, partner.row, partner.col);

            // After placing a domino, re‑evaluate the neighbour that now belongs to a pair.
            for (Coord p : neighbours) {
                if (grid[p.row][p.col] == '.') {
                    List<Coord> pNeighbours = getEmptyNeighbours(grid, p.row, p.col, rows, cols);
                    if (pNeighbours.size() == 1) {
                        queue.addLast(p);
                    }
                }
            }
        }

        // If any '.' remains, the tiling is not unique (or unsolvable).
        for (char[] row : grid) {
            for (char cell : row) {
                if (cell == '.') {
                    return false;
                }
            }
        }
        return true;
    }

    /** Returns all orthogonal neighbours of (r,c) that are still '.' */
    private static List<Coord> getEmptyNeighbours(char[][] grid,
                                                  int r, int c,
                                                  int rows, int cols) {
        List<Coord> neighbours = new ArrayList<>(4);
        int[][] dirs = {{-1, 0}, {0, -1}, {1, 0}, {0, 1}};
        for (int[] d : dirs) {
            int nr = r + d[0];
            int nc = c + d[1];
            if (inside(nr, nc, rows, cols) && grid[nr][nc] == '.') {
                neighbours.add(new Coord(nr, nc));
            }
        }
        return neighbours;
    }

    /** Helper to check array bounds. */
    private static boolean inside(int r, int c, int rows, int cols) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    /** Marks a pair of adjacent '.' cells with the appropriate domino symbols. */
    private static void placeDomino(char[][] grid,
                                    int r1, int c1,
                                    int r2, int c2) {
        if (r1 == r2) {                     // horizontal domino
            int min = Math.min(c1, c2);
            int max = Math.max(c1, c2);
            grid[r1][min] = '<';
            grid[r1][max] = '>';
        } else {                            // vertical domino
            int min = Math.min(r1, r2);
            int max = Math.max(r1, r2);
            grid[min][c1] = '^';
            grid[max][c1] = 'v';
        }
    }

    /** Prints the solved grid row‑by‑row. */
    private static void printSolution(char[][] grid) {
        StringBuilder out = new StringBuilder();
        for (char[] row : grid) {
            for (char cell : row) {
                out.append(cell);
            }
            out.append('\n');
        }
        System.out.print(out.toString());
    }
}

import java.io.*;
import java.util.*;

/**
 * Entry point of the program.
 *
 * <p>It creates an {@link InputReader} and an {@link OutputWriter}, builds a {@link Solver}
 * instance and runs it. All heavy‑lifting is delegated to {@link Solver}.</p>
 */
public class Main {

    /** If {@code true} the execution time is printed on standard error (debug mode). */
    private static final boolean DEBUG = false;

    /** Name of the input file without the extension – also used for the output file. */
    private static final String INPUT_BASENAME = "";

    /** When {@code true} the program reads from {@code *.in}/{@code *.out} files. */
    private static final boolean USE_FILES = false;

    public static void main(String[] args) throws IOException {
        long startNs = DEBUG ? System.nanoTime() : 0L;

        // Resolve the underlying streams (file or stdio)
        InputStream inStream = System.in;
        OutputStream outStream = System.out;
        if (USE_FILES) {
            inStream = new FileInputStream(INPUT_BASENAME + ".in");
            outStream = new FileOutputStream(INPUT_BASENAME + ".out");
        }

        // Build I/O helpers
        InputReader reader = new InputReader(inStream);
        OutputWriter writer = new OutputWriter(outStream);

        // Solve the problem
        new Solver(reader, writer).solve();

        // Close output (closing System.out is safe only when it was redirected)
        writer.close();

        if (DEBUG) {
            System.err.println((System.nanoTime() - startNs) / 1e9);
        }
    }
}

/**
 * Simple enum that represents the four cardinal directions.
 *
 * <p>Each direction knows its opposite, its relative coordinate offset and the
 * character used in the input / output.</p>
 */
enum Direction {
    LEFT (0, -1, '<', '>'),   // from cell to neighbor: left neighbor has '>'
    RIGHT(0,  1, '>', '<'),   // the opposite token is written on the neighbor
    UP   (-1, 0, '^', 'v'),
    DOWN ( 1, 0, 'v', '^');

    /** Row offset when moving one step in this direction. */
    final int rowDelta;

    /** Column offset when moving one step in this direction. */
    final int colDelta;

    /** Character read from the board representing a tile that points to the neighbour. */
    final char inputSymbol;

    /** Character written on the neighbour that completes the domino. */
    final char outputSymbol;

    Direction(int rowDelta, int colDelta, char inputSymbol, char outputSymbol) {
        this.rowDelta = rowDelta;
        this.colDelta = colDelta;
        this.inputSymbol = inputSymbol;
        this.outputSymbol = outputSymbol;
    }

    /** Helper returning the opposite direction. */
    Direction opposite() {
        for (Direction d : values()) {
            if (d.inputSymbol == this.outputSymbol && d.outputSymbol == this.inputSymbol) {
                return d;
            }
        }
        throw new IllegalStateException("No opposite direction defined");
    }

    /** Move one cell in this direction. */
    void offset(Position p) {
        p.row += rowDelta;
        p.col += colDelta;
    }
}

/**
 * Simple container for a cell coordinate on the grid.
 */
final class Position {
    int row;
    int col;

    Position(int row, int col) {
        this.row = row;
        this.col = col;
    }
}

/**
 * Core logic that decides whether the board can be tiled uniquely and prints the result.
 *
 * <p>The algorithm follows the original solution:
 * <ol>
 *   <li>Find cells that have exactly one free neighbour – they must be paired.</li>
 *   <li>Place the corresponding tile (domino) immediately.</li>
 *   <li>Propagate newly created forced moves.</li>
 *   <li>If at any point a cell has no or more than one possible continuation,
 *       the tiling is not unique.</li>
 *   <li>If after exhaustive processing any empty cell remains, the board cannot be tiled.</li>
 * </ol>
 * </p>
 */
final class Solver {

    /** Directions used for neighbour search. */
    private static final int[][] OFFSET = {
            {0, 1},   // right
            {0, -1},  // left
            {1, 0},   // down
            {-1, 0}   // up
    };

    /** Character patterns for the four directions – match the {@link Direction} enum order. */
    private static final char[] BEGIN_TOKEN = {'>', '<', '^', 'v'};
    private static final char[] END_TOKEN   = {'<', '>', 'v', '^'};

    private final InputReader reader;
    private final OutputWriter writer;

    /** Board representation (mutable). */
    private char[][] board;

    /** Grid dimension. */
    private int rows, cols;

    /** Queue of cells that currently have exactly one free neighbour and therefore can be processed. */
    private final Queue<Position> pending = new ArrayDeque<>();

    Solver(InputReader reader, OutputWriter writer) {
        this.reader = reader;
        this.writer = writer;
    }

    /** Orchestrates input, processing and output. */
    void solve() {
        readInput();
        propagate();
        validateCompleteCoverage();
        printSolution();
    }

    /** Reads the dimension and the board from {@link #reader}. */
    private void readInput() throws IOException {
        rows = reader.nextInt();
        cols = reader.nextInt();
        board = new char[rows][cols];

        for (int i = 0; i < rows; i++) {
            String line = reader.next();
            System.arraycopy(line.toCharArray(), 0, board[i], 0, cols);
        }
    }

    /**
     * Main propagation loop – repeatedly extracts cells that have a single
     * free neighbour, decides the unique way to place a tile and adds newly
     * created cells back to the queue if they become forced.
     */
    private void propagate() {
        initialiseQueue();

        while (!pending.isEmpty()) {
            Position cur = pending.poll();
            if (board[cur.row][cur.col] != '.') {
                continue; // already resolved
            }

            Pair<Direction, Position> decision = decideUniqueDirection(cur);
            if (decision == null) {
                writer.println("Not unique");
                System.exit(0);
            }

            // Write both halves of the domino
            Direction dir = decision.first;
            board[cur.row][cur.col] = dir.inputSymbol;
            Position neighbour = new Position(cur.row, cur.col);
            dir.offset(neighbour);
            board[neighbour.row][neighbour.col] = dir.outputSymbol;

            // Queue newly created forced cells
            for (int d = 0; d < OFFSET.length; d++) {
                Position p = new Position(neighbour.row, neighbour.col);
                Direction.next(d).offset(p);
                if (inside(p) && board[p.row][p.col] == '.' && hasExactlyOneFreeNeighbour(p)) {
                    pending.add(p);
                }
            }
        }
    }

    /** Fills {@link #pending} with all cells that currently have exactly one free neighbour. */
    private void initialiseQueue() {
        pending.clear();
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                Position p = new Position(r, c);
                if (board[p.row][p.col] == '.' && hasExactlyOneFreeNeighbour(p)) {
                    pending.add(p);
                }
            }
        }
    }

    /**
     * Determines the only possible direction to continue from {@code start}
     * if it exists, otherwise returns {@code null}.
     */
    private Pair<Direction, Position> decideUniqueDirection(Position start) {
        Direction dir = null;
        Position neighbour = null;

        for (int d = 0; d < OFFSET.length; d++) {
            Position p = new Position(start.row, start.col);
            Direction.next(d).offset(p);
            if (inside(p) && board[p.row][p.col] == '.') {
                if (dir != null) { // more than one possibility => fail early
                    return null;
                }
                dir = Direction.values()[d];
                neighbour = p;
            }
        }

        // No free neighbour → unsolvable board (but this should not happen
        // when the queue invariant is maintained).
        return (dir == null) ? null : new Pair<>(dir, neighbour);
    }

    /** Returns {@code true} if the cell has exactly one adjacent '.' cell. */
    private boolean hasExactlyOneFreeNeighbour(Position p) {
        int count = 0;
        for (int d = 0; d < OFFSET.length; d++) {
            Position q = new Position(p.row, p.col);
            Direction.next(d).offset(q);
            if (inside(q) && board[q.row][q.col] == '.') {
                count++;
            }
        }
        return count == 1;
    }

    /** Writes the solved board to {@link #writer} or reports failure cases. */
    private void validateCompleteCoverage() {
        for (char[] row : board) {
            for (char cell : row) {
                if (cell == '.') {
                    writer.println("Not unique");
                    System.exit(0);
                }
            }
        }
    }

    /** Prints the solved board line by line. */
    private void printSolution() {
        for (char[] row : board) {
            writer.print(new String(row));
            writer.println();
        }
    }

    /** Simple utility to test array bounds. */
    private boolean inside(Position p) {
        return 0 <= p.row && p.row < rows && 0 <= p.col && p.col < cols;
    }
}

/**
 * Tiny helper that bundles the two characters written on a domino.
 */
final class Pair<A, B> {
    final A first;
    final B second;

    private Pair(A first, B second) {
        this.first = first;
        this.second = second;
    }

    static <A, B> Pair<A, B> of(A a, B b) {
        return new Pair<>(a, b);
    }
}

/**
 * Fast buffered input reader that works with tokens separated by whitespace.
 */
final class InputReader {
    private final BufferedReader reader;
    private StringTokenizer tokenizer;

    InputReader(InputStream stream) {
        this.reader = new BufferedReader(new InputStreamReader(stream), 32768);
    }

    /** Returns the next token, expanding the stream lazily. */
    String next() {
        while (tokenizer == null || !tokenizer.hasMoreTokens()) {
            try {
                tokenizer = new StringTokenizer(reader.readLine());
            } catch (IOException e) {
                throw new RuntimeException(e);
            }
        }
        return tokenizer.nextToken();
    }

    // Convenience methods omitted for brevity – they simply forward to {@code next()}.
    int nextInt()            { return Integer.parseInt(next()); }
    long nextLong()          { return Long.parseLong(next()); }
    double nextDouble()      { return Double.parseDouble(next()); }
    // …
}

/**
 * Minimal output writer that writes to a given {@link OutputStream}.
 * It also provides a {@code println()} convenience.
 */
final class OutputWriter {
    private final PrintWriter printWriter;

    OutputWriter(OutputStream stream) {
        this.printWriter = new PrintWriter(stream);
    }

    void print(String s)               { printWriter.print(s); }
    void println()                       { printWriter.println(); }
    void close()                         { printWriter.close(); }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Deque;
import java.util.List;
import java.util.StringTokenizer;

/**
 * CF292B – Tiling with dominoes.
 *
 * The program reads a grid consisting of '.' (empty) and other characters.
 * It tries to uniquely tile all empty cells with 1×2 or 2×1 dominoes.
 * If the tiling is not unique the program prints "Not unique",
 * otherwise it prints the grid where each placed domino is represented by
 * the appropriate arrow characters.
 *
 * The implementation is deliberately split into small, pure methods,
 * uses meaningful names, avoids raw types where possible and isolates the
 * algorithmic steps from I/O.
 */
public class CF292B {

    /** Entry point – reads input, solves the problem and prints the result. */
    public static void main(String[] args) throws IOException {
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in))) {
            StringTokenizer st = new StringTokenizer(br.readLine());
            int rows = Integer.parseInt(st.nextToken());
            int cols = Integer.parseInt(st.nextToken());

            char[][] grid = new char[rows][];
            for (int i = 0; i < rows; i++) {
                grid[i] = br.readLine().toCharArray();
            }

            solve(rows, cols, grid);
        }
    }

    /**
     * Core algorithm – attempts to tile the grid uniquely.
     *
     * @param rows number of rows in the grid
     * @param cols number of columns in the grid
     * @param grid mutable char matrix representing the board
     */
    private static void solve(int rows, int cols, char[][] grid) {
        final int[] dr = {0, 0, 1, -1};
        final int[] dc = {1, -1, 0, 0};

        // 1️⃣  Find all cells that currently have exactly one free neighbour.
        List<Cell> forced = discoverForcedCells(rows, cols, grid, dr, dc);
        Deque<Cell> queue = new ArrayDeque<>(forced);

        // 2️⃣  Process forced cells iteratively.
        while (!queue.isEmpty()) {
            Cell cur = queue.poll();
            if (!isStillFree(cur.row(), cur.col(), grid)) {
                continue; // already paired
            }

            List<Cell> neighbours = getEmptyNeighbours(cur.row(), cur.col(), rows, cols, grid, dr, dc);
            if (neighbours.size() != 1) {
                continue; // no longer forced
            }

            Cell next = neighbours.get(0);
            pairCells(cur, next, grid); // mark the domino with arrows
            markUsed(cur);
            markUsed(next);

            // After pairing, re‑evaluate neighbours for new forced cells.
            for (Cell neighbour : neighbours) {
                if (neighbour.equals(cur) || neighbour.equals(next)) {
                    continue;
                }
                int free = countFreeNeighbours(neighbour.row(), neighbour.col(), rows, cols, grid, dr, dc);
                if (free == 1) {
                    queue.add(new Cell(neighbour.row(), neighbour.col()));
                }
            }
        }

        // 3️⃣  Verify that every empty cell was paired.
        if (containsRemainingEmptyCell(grid)) {
            System.out.println("Not unique");
            return;
        }

        // 4️⃣  Output the solved board.
        printGrid(grid);
    }

    /** Helper class to hold a board coordinate. */
    private static final class Cell {
        final int row, col;
        Cell(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }

    /** Checks whether a cell is still an empty ('.') position. */
    private static boolean isStillFree(int r, int c, char[][] grid) {
        return grid[r][c] == '.';
    }

    /** Marks a cell as used (no longer considered for tiling). */
    private static void markUsed(Cell cell) {
        // '#' is used as a sentinel; any non‑'.' value means “already placed”.
        // Keeping the character unchanged would also work, but '#' makes the intent clear.
        // The caller is expected to have verified that the cell is free.
        // This method is only called on cells we know are '.'.
        // Hence we simply leave the character untouched – the surrounding logic
        // treats any non‑'.' as “not free”.
    }

    /** Returns all orthogonal neighbours that are currently empty ('.').

     * @return list of neighbour cells
     */
    private static List<Cell> getEmptyNeighbours(
            int r, int c, int rows, int cols, char[][] grid,
            int[] dr, int[] dc) {

        List<Cell> neighbours = new ArrayList<>();
        for (int d = 0; d < 4; d++) {
            int nr = r + dr[d];
            int nc = c + dc[d];
            if (!inBounds(nr, nc, rows, cols)) continue;
            if (grid[nr][nc] != '.') continue;
            neighbours.add(new Cell(nr, nc));
        }
        return neighbours;
    }

    /** Counts how many orthogonal neighbours of (r,c) are still empty. */
    private static int countFreeNeighbours(
            int r, int c, int rows, int cols, char[][] grid,
            int[] dr, int[] dc) {

        int free = 0;
        for (int d = 0; d < 4; d++) {
            int nr = r + dr[d];
            int nc = c + dc[d];
            if (!inBounds(nr, nc, rows, cols)) continue;
            if (grid[nr][nc] == '.') free++;
        }
        return free;
    }

    /** Simple bounds check. */
    private static boolean inBounds(int r, int c, int rows, int cols) {
        return r >= 0 && c >= 0 && r < rows && c < cols;
    }

    /** Pairs two adjacent free cells with the appropriate arrow symbols. */
    private static void pairCells(Cell a, Cell b, char[][] grid) {
        if (a.row() != b.row()) { // vertical domino
            int top = Math.min(a.row(), b.row());
            int bottom = Math.max(a.row(), b.row());
            grid[top][a.col()] = '^';
            grid[bottom][a.col()] = 'v';
        } else { // horizontal domino
            int left = Math.min(a.col(), b.col());
            int right = Math.max(a.col(), b.col());
            grid[a.row()][left] = '<';
            grid[a.row()][right] = '>';
        }
    }

    /** Determines whether any '.' remains in the grid. */
    private static boolean containsRemainingEmptyCell(char[][] grid) {
        for (char[] row : grid) {
            for (char ch : row) {
                if (ch == '.') {
                    return true;
                }
            }
        }
        return false;
    }

    /** Prints the final grid to standard output. */
    private static void printGrid(char[][] grid) {
        for (char[] row : grid) {
            System.out.println(new String(row));
        }
    }
}

import java.util.ArrayDeque;
import java.util.Deque;
import java.util.Scanner;

/**
 * TileCover – refactored version of the original CF515D solution.
 *
 * The program reads an {@code n × m} grid containing '.' (free cells) and
 * other characters. It tries to cover all free cells with 2‑cell dominoes
 * and prints the resulting tiling if it is unique; otherwise it prints
 * “Not unique”.
 *
 * The refactor focuses on:
 *   • Removing unnecessary fields and mutable global state.
 *   • Using clearly named constants and methods.
 *   • Encapsulating logic into small, reusable helpers.
 *   • Improving readability with modern Java constructs.
 */
public class CF515D {

    /** Direction vectors: east, west, south, north */
    private static final int[] DX = {0, 0, 1, -1};
    /** Direction vectors: east, west, south, north */
    private static final int[] DY = {1, -1, 0, 0};

    /** Arrow pairs for the two cells of a domino.
     *  Index matches the direction index (0‑3). */
    private static final char[][] ARROW = {
            {'<', '>', '^', 'v'},   // first cell of the domino
            {'>', '<', 'v', '^'}    // second cell of the domino
    };

    /** Entry stored in the work queue – three integers: row, column, direction. */
    private static final class QueueEntry {
        final int row;
        final int col;
        final int dir; // direction index (0‑3)

        QueueEntry(int row, int col, int dir) {
            this.row = row;
            this.col = col;
            this.dir = dir;
        }
    }

    /** Solves the problem using the supplied input stream. */
    public static void main(String[] args) {
        new CF515D().solve();
    }

    /** Core solving routine – reads input, processes the grid and prints the answer. */
    private void solve() {
        try (Scanner sc = new Scanner(System.in)) {
            int n = sc.nextInt();
            int m = sc.nextInt();
            char[][] grid = new char[n][];
            for (int i = 0; i < n; i++) {
                grid[i] = sc.next().toCharArray();
            }

            int remainingFree = countFreeCells(grid);
            Deque<QueueEntry> queue = new ArrayDeque<>();

            // Initialise the queue with every free cell that has exactly one free neighbour.
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    if (grid[i][j] == '.') {
                        remainingFree++;
                        int dir = firstFreeDirection(grid, i, j);
                        if (dir != -1) {
                            queue.add(new QueueEntry(i, j, dir));
                        }
                    }
                }
            }

            // Greedily place dominoes while possible.
            while (!queue.isEmpty() && remainingFree > 0) {
                QueueEntry entry = queue.poll();
                placeDomino(grid, entry);
                if (remainingFree > 0) {
                    // Enqueue neighbours of both cells that now have a single free neighbour.
                    for (int d = 0; d < 4; d++) {
                        tryAddIfSingleNeighbour(grid, queue, entry.row, entry.col);
                        tryAddIfSingleNeighbour(grid, queue,
                                entry.row + DX[entry.dir],
                                entry.col + DY[entry.dir]);
                    }
                }
            }

            if (remainingFree != 0) {
                System.out.println("Not unique");
            } else {
                printSolution(grid);
            }
        }
    }

    /** Counts how many cells in the grid are still free ('.'). */
    private static int countFreeCells(char[][] grid) {
        int cnt = 0;
        for (char[] row : grid) {
            for (char cell : row) {
                if (cell == '.') cnt++;
            }
        }
        return cnt;
    }

    /** Returns the direction index of the unique free neighbour of (r,c),
     *  or -1 if the cell does not have exactly one free neighbour. */
    private static int firstFreeDirection(char[][] grid, int r, int c) {
        int cnt = 0;
        int dir = -1;
        for (int d = 0; d < 4; d++) {
            int nr = r + DX[d];
            int nc = c + DY[d];
            if (isFree(grid, nr, nc)) {
                cnt++;
                dir = d;
            }
        }
        return cnt == 1 ? dir : -1;
    }

    /** Places a domino covering (r,c) and its neighbour in direction {@code dir}
     *  if both cells are still free. Updates {@code remainingFree} accordingly. */
    private static void placeDomino(char[][] grid, QueueEntry entry) {
        int r = entry.row;
        int c = entry.col;
        int dir = entry.dir;

        int nr = r + DX[dir];
        int nc = c + DY[dir];

        if (isFree(grid, r, c) && isFree(grid, nr, nc)) {
            grid[r][c] = ARROW[0][dir];
            grid[nr][nc] = ARROW[1][dir];
            // Two cells are now occupied
            // (the outer method keeps track of the remaining count)
        }
    }

    /** Returns true iff the cell (r,c) is inside the grid and still free ('.'). */
    private static boolean isFree(char[][] grid, int r, int c) {
        return r >= 0 && r < grid.length && c >= 0 && c < grid[0].length && grid[r][c] == '.';
    }

    /** Enqueues (r,c) together with its unique free direction if exactly one exists. */
    private static void tryAddIfSingleNeighbour(char[][] grid, Deque<QueueEntry> q,
                                                int r, int c) {
        int cnt = 0;
        int dir = -1;
        for (int d = 0; d < 4; d++) {
            int nr = r + DX[d];
            int nc = c + DY[d];
            if (isFree(grid, nr, nc)) {
                cnt++;
                dir = d;
            }
        }
        if (cnt == 1) {
            q.add(new QueueEntry(r, c, dir));
        }
    }

    /** Prints the solved grid to standard output. */
    private static void printSolution(char[][] grid) {
        for (char[] row : grid) {
            System.out.println(new String(row));
        }
    }
}

import java.awt.Point;
import java.io.*;
import java.util.ArrayDeque;
import java.util.Queue;
import java.util.StringTokenizer;

/**
 * Solves a labyrinth‑domino tiling problem.
 * <p>
 * The algorithm:
 * <ul>
 *   <li>Computes for every empty cell how many neighbouring empty cells it has
 *       (the “age”).</li>
 *   <li>Tiles are forced when a cell has exactly one free neighbour.</li>
 *   <li>After placing a domino the ages of the involved cells and their
 *       neighbours are recomputed, possibly creating new forced tiles.</li>
 *   <li>If at any point a free cell has age 0 the solution is not unique;
 *       otherwise, when no empty cells remain the tiling is printed.</li>
 * </ul>
 * </p>
 */
public class LabyrinthSolver {

    /* ------------------------------------------------------------------ *
     *  Constant direction vectors (down, up, right, left)                *
     * ------------------------------------------------------------------ */
    private static final int[][] DIRS = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};

    /* ------------------------------------------------------------------ *
     *  Input / output streams                                              *
     * ------------------------------------------------------------------ */
    private BufferedReader reader;
    private PrintWriter writer;
    private StringTokenizer tokenizer;

    /* ------------------------------------------------------------------ *
     *  Problem parameters                                                  *
     * ------------------------------------------------------------------ */
    private int n, m;                     // board dimensions
    private char[][] grid;                // original board (1‑based)
    private int[][] age;                  // age of each cell (0 = isolated)

    /* ------------------------------------------------------------------ *
     *  Entry point                                                       *
     * ------------------------------------------------------------------ */
    public static void main(String[] args) throws IOException {
        new LabyrinthSolver().run();
    }

    /* ------------------------------------------------------------------ *
     *  Main workflow                                                     *
     * ------------------------------------------------------------------ */
    private void run() throws IOException {
        initIO();
        readBoard();
        computeAges();

        Queue<Point> queue = locateForcedTiles();
        solve(queue);

        if (hasRemainingEmptyCells()) {
            printer("Not unique");
        } else {
            printSolution();
        }
        cleanup();
    }

    /* ------------------------------------------------------------------ *
     *  I/O initialisation                                                 *
     * ------------------------------------------------------------------ */
    private void initIO() {
        reader = new BufferedReader(new InputStreamReader(System.in));
        writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)));
    }

    private void cleanup() {
        try { if (reader != null) reader.close(); } catch (Exception ignored) {}
        writer.close();
    }

    /* ------------------------------------------------------------------ *
     *  Input reading                                                     *
     * ------------------------------------------------------------------ */
    private void readBoard() throws IOException {
        n = nextInt();
        m = nextInt();
        grid = new char[n + 2][m + 2];   // extra border of '.' simplifies checks
        for (int i = 0; i < n + 2; i++) {
            Arrays.fill(grid[i], '.');
        }
        for (int i = 1; i <= n; i++) {
            String line = nextLine().trim();
            System.arraycopy(line.toCharArray(), 0, grid[i], 1, m);
        }
    }

    /* ------------------------------------------------------------------ *
     *  Age computation – number of adjacent empty cells                    *
     * ------------------------------------------------------------------ */
    private void computeAges() {
        age = new int[n + 2][m + 2];
        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= m; j++) {
                if (grid[i][j] != '.') continue;
                int cnt = 0;
                for (int[] d : DIRS) {
                    int ni = i + d[0], nj = j + d[1];
                    if (grid[ni][nj] == '.') cnt++;
                }
                age[i][j] = cnt;
            }
        }
    }

    /* ------------------------------------------------------------------ *
     *  Locate cells that are forced to be part of a domino (age == 1)      *
     * ------------------------------------------------------------------ */
    private Queue<Point> locateForcedTiles() {
        Queue<Point> forced = new ArrayDeque<>();
        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= m; j++) {
                if (grid[i][j] == '.' && age[i][j] == 1) {
                    forced.add(new Point(i, j));
                }
            }
        }
        return forced;
    }

    /* ------------------------------------------------------------------ *
     *  Main solving loop                                                  *
     * ------------------------------------------------------------------ */
    private void solve(Queue<Point> q) {
        while (!q.isEmpty()) {
            Point cur = q.poll();
            int x = cur.x, y = cur.y;

            // Already processed or no longer empty
            if (grid[x][y] != '.') continue;

            // If the cell has become isolated → not unique
            if (age[x][y] == 0) {
                printer("Not unique");
                return;
            }

            // Find the unique neighbouring empty cell to pair with
            int nx = -1, ny = -1;
            for (int[] d : DIRS) {
                int tx = x + d[0], ty = y + d[1];
                if (inside(tx, ty) && grid[tx][ty] == '.') {
                    nx = tx; ny = ty;
                    break;
                }
            }
            if (nx == -1) {                     // should not happen
                printer("Not unique");
                return;
            }

            // Place the domino
            placeDomino(x, y, nx, ny);
            recomputeAge(x, y);
            recomputeAge(nx, ny);
            propagateToNeighbours(nx, ny);

            // After placing, possible new forced tiles appear
            for (int[] d : DIRS) {
                int ax = x + d[0], ay = y + d[1];
                if (inside(ax, ay) && grid[ax][ay] == '.' && age[ax][ay] == 1) {
                    q.add(new Point(ax, ay));
                }
                ax = nx + d[0];
                ay = ny + d[1];
                if (inside(ax, ay) && grid[ax][ay] == '.' && age[ax][ay] == 1) {
                    q.add(new Point(ax, ay));
                }
            }
        }
    }

    /* ------------------------------------------------------------------ *
     *  Helper: put the two cells of a domino with proper characters       *
     * ------------------------------------------------------------------ */
    private void placeDomino(int i, int j, int pi, int pj) {
        if (i == pi) {                       // horizontal domino
            grid[i][j] = (j < pj) ? '<' : '>';
            grid[pi][pj] = (j < pj) ? '>' : '<';
        } else {                             // vertical domino
            grid[i][j] = (i < pi) ? '^' : 'v';
            grid[pi][pj] = (i < pi) ? 'v' : '^';
        }
    }

    /* ------------------------------------------------------------------ *
     *  Re‑compute the age of a single cell                               *
     * ------------------------------------------------------------------ */
    private void recomputeAge(int i, int j) {
        age[i][j] = 0;
        for (int[] d : DIRS) {
            int ni = i + d[0], nj = j + d[1];
            if (grid[ni][nj] == '.') age[i][j]++;
        }
    }

    /* ------------------------------------------------------------------ *
     *  Add neighbours that might have become forced (age == 1)             *
     * ------------------------------------------------------------------ */
    private void propagateToNeighbours(int i, int j) {
        for (int[] d : DIRS) {
            int x = i + d[0], y = j + d[1];
            if (inside(x, y) && grid[x][y] == '.' && age[x][y] == 1) {
                // age will be recomputed automatically when the cell is processed
            }
        }
    }

    /* ------------------------------------------------------------------ *
     *  Utility: board bounds check                                        *
     * ------------------------------------------------------------------ */
    private boolean inside(int x, int y) {
        return x >= 1 && x <= n && y >= 1 && y <= m;
    }

    /* ------------------------------------------------------------------ *
     *  Check whether any empty cell remains after solving                    *
     * ------------------------------------------------------------------ */
    private boolean hasRemainingEmptyCells() {
        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= m; j++) {
                if (grid[i][j] == '.') return true;
            }
        }
        return false;
    }

    /* ------------------------------------------------------------------ *
     *  Output the solved board                                             *
     * ------------------------------------------------------------------ */
    private void printSolution() {
        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= m; j++) {
                writer.print(grid[i][j]);
            }
            writer.println();
        }
    }

    /* ------------------------------------------------------------------ *
     *  Small wrapper to print messages and continue execution              *
     * ------------------------------------------------------------------ */
    private void printer(String msg) {
        writer.println(msg);
    }

    /* ------------------------------------------------------------------ *
     *  Fast scanner utilities                                            *
     * ------------------------------------------------------------------ */
    private String nextToken() throws IOException {
        while (tokenizer == null || !tokenizer.hasMoreTokens()) {
            tokenizer = new StringTokenizer(nextLine());
        }
        return tokenizer.nextToken();
    }

    private String nextLine() throws IOException {
        return reader.readLine();
    }

    private int nextInt() throws IOException {
        return Integer.parseInt(nextToken());
    }

    private long nextLong() throws IOException {
        return Long.parseLong(nextToken());
    }

    private double nextDouble() throws IOException {
        return Double.parseDouble(nextToken());
    }
}

import java.util.ArrayDeque;
import java.util.Deque;
import java.util.Scanner;

/**
 * Refactored version of the original domino‑tiling solver.
 *
 * <p>
 * The program reads a rectangular grid composed of '.' (empty), '*' (obstacle) and
 * possibly other characters.  It tries to cover every empty cell with a domino,
 * marking each domino with directional characters ('^', 'v', '<', '>').
 * If the covering is unique the final board is printed; otherwise "Not unique"
 * is printed.
 * </p>
 *
 * <p>Key improvements over the original code:</p>
 * <ul>
 *   <li>Encapsulation of mutable state in dedicated fields.</li>
 *   <li>Descriptive identifiers and method extraction.</li>
 *   <li>Constant definitions for direction vectors.</li>
 *   <li>Clear separation of input handling, processing, and output.</li>
 *   <li>Early‑exit on errors via {@code System.exit} replaced by normal flow.</li>
 * </ul>
 */
public final class DominoSolver {

    /** Direction vectors: right, left, down, up */
    private static final int[] DX = {0, 0, 1, -1};
    private static final int[] DY = {1, -1, 0, 0};

    /** The game board */
    private static char[][] grid;

    /** Board dimensions */
    private static int rows;
    private static int cols;

    /** Queue used during the discovery/forced‑placement phase */
    private static Deque<Integer> processingQueue;

    private DominoSolver() {
        // Prevent instantiation – this is a utility class.
    }

    /** Entry point */
    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            readInput(scanner);
            initialiseQueue();
            resolveTiles();
            printResult();
        }
    }

    /** Reads board dimensions and the grid itself. */
    private static void readInput(Scanner scanner) {
        rows = scanner.nextInt();
        cols = scanner.nextInt();
        grid = new char[rows][cols];
        for (int r = 0; r < rows; r++) {
            grid[r] = scanner.next().toCharArray();
        }
    }

    /** Populates the processing queue with all cells that may trigger a forced move. */
    private static void initialiseQueue() {
        processingQueue = new ArrayDeque<>();
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] != '*') {
                    enqueueForProcessing(r, c);
                }
            }
        }
    }

    /**
     * Enqueues a cell together with its only free neighbour when exactly one such neighbour exists.
     * This mimics the original {@code check} routine where {@code sc == 3}.
     */
    private static void enqueueForProcessing(int x, int y) {
        if (isBlocked(x, y)) {
            return;
        }

        int freeX = -1, freeY = -1;
        int freeNeighbourCount = 0;

        for (int d = 0; d < 4; d++) {
            int nx = x + DX[d];
            int ny = y + DY[d];
            if (!isBlocked(nx, ny)) {
                freeX = nx;
                freeY = ny;
                freeNeighbourCount++;
            }
        }

        if (freeNeighbourCount == 1) {
            // Store the current cell and the unique free neighbour
            processingQueue.add(x);
            processingQueue.add(y);
            processingQueue.add(freeX);
            processingQueue.add(freeY);
        }
    }

    /** Returns {@code true} if the cell lies outside the board or is not an empty '.' cell. */
    private static boolean isBlocked(int x, int y) {
        return x < 0 || y < 0 || x >= rows || y >= cols || grid[x][y] != '.';
    }

    /** Main solving loop – repeatedly places forced dominoes until no more can be placed. */
    private static void resolveTiles() {
        while (!processingQueue.isEmpty()) {
            // Retrieve two cells that form a domino pair
            int x1 = processingQueue.remove(); // ux
            int y1 = processingQueue.remove(); // uy
            int x2 = processingQueue.remove(); // vx
            int y2 = processingQueue.remove(); // vy

            // Skip stale entries
            if (grid[x1][y1] != '.' || grid[x2][y2] != '.') {
                continue;
            }

            // Place the domino, choosing the appropriate visual marker
            if (x1 != x2) { // vertical orientation
                if (x1 > x2) {
                    grid[x2][y2] = '^';
                    grid[x1][y1] = 'v';
                } else {
                    grid[x2][y2] = 'v';
                    grid[x1][y1] = '^';
                }
            } else { // horizontal orientation
                if (y1 > y2) {
                    grid[x2][y2] = '<';
                    grid[x1][y1] = '>';
                } else {
                    grid[x2][y2] = '>';
                    grid[x1][y1] = '<';
                }
            }

            // Enqueue neighbours that may now have a forced placement
            for (int d = 0; d < 4; d++) {
                enqueueForProcessing(x1 + DX[d], y1 + DY[d]);
                enqueueForProcessing(x2 + DX[d], y2 + DY[d]);
            }
        }
    }

    /** Determines whether every empty cell has been covered by a domino. */
    private static boolean isCompleteCoverage() {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '.') {
                    return false;
                }
            }
        }
        return true;
    }

    /** Outputs the solved board or reports that the solution is not unique. */
    private static void printResult() {
        if (isCompleteCoverage()) {
            for (char[] row : grid) {
                System.out.println(new String(row));
            }
        } else {
            System.out.println("Not unique");
        }
    }
}

import java.util.*;

/**
 * Refactored version of the original tile‑placement solver.
 * The code focuses on readability, maintainability and clear separation
 * of concerns.
 */
public class TilePlacementSolver {

    // -----------------------------------------------------------------------
    // Constants and enums
    // -----------------------------------------------------------------------
    private static final char BORDER_CHAR = '#';
    private static final char EMPTY_CELL = '.';

    /** Directions in order: up, right, down, left */
    private enum Direction {
        UP(-1, 0, 'v'),    // current cell gets 'v' when neighbor is below
        RIGHT(0, 1, '<'),  // current cell gets '<' when neighbor is to the right
        DOWN(1, 0, '^'),   // current cell gets '^' when neighbor is above
        LEFT(0, -1, '>');  // current cell gets '>' when neighbor is to the left

        private final int dRow;
        private final int dCol;
        private final char symbol;

        Direction(int dRow, int dCol, char symbol) {
            this.dRow = dRow;
            this.dCol = dCol;
            this.symbol = symbol;
        }

        public int getDRow()   { return dRow; }
        public int getDCol()   { return dCol; }
        public char getSymbol(){ return symbol; }

        /** Returns the opposite direction in the enum. */
        public Direction opposite() {
            return switch (this) {
                case UP -> Direction.DOWN;
                case RIGHT -> Direction.LEFT;
                case DOWN -> Direction.UP;
                case LEFT -> Direction.RIGHT;
            };
        }
    }

    // -----------------------------------------------------------------------
    // Fields representing the playing field
    // -----------------------------------------------------------------------
    private final char[][] grid;
    private final int rows;
    private final int cols;

    public TilePlacementSolver(char[][] input) {
        this.rows = input.length;
        this.cols = input[0].length;
        this.grid = new char[rows + 2][cols + 2];
        initGrid();
        copyInput(input);
    }

    /** Creates the border‑surrounded grid. */
    private void initGrid() {
        for (int r = 1; r <= rows; r++) {
            grid[r][0] = BORDER_CHAR;
            grid[r][cols + 1] = BORDER_CHAR;
        }
        for (int c = 1; c <= cols; c++) {
            grid[0][c] = BORDER_CHAR;
            grid[rows + 1][c] = BORDER_CHAR;
        }
    }

    /** Copies the user supplied board into the internal grid (offset by one). */
    private void copyInput(char[][] input) {
        for (int r = 0; r < rows; r++) {
            String line = input[r];
            for (int c = 0; c < cols; c++) {
                grid[r + 1][c + 1] = line.charAt(c);
            }
        }
    }

    // -----------------------------------------------------------------------
    // Helper methods
    // -----------------------------------------------------------------------
    /** Returns true if coordinates are inside the playable area (excluding borders). */
    private boolean inside(int r, int c) {
        return r > 0 && r < grid.length && c > 0 && c < grid[0].length;
    }

    /**
     * Counts how many orthogonal neighbours of the given cell are still empty.
     */
    public int countEmptyNeighbours(int r, int c) {
        int count = 0;
        for (Direction dir : Direction.values()) {
            int nr = r + dir.getDRow();
            int nc = c + dir.getDCol();
            if (grid[nr][nc] == EMPTY_CELL) {
                count++;
            }
        }
        return count;
    }

    /**
     * Attempts to place a pair of tiles covering an empty cell and one of its empty neighbours.
     * The method throws an exception if no such placement can be made at the given cell.
     *
     * @return the direction that was used to place the tiles
     */
    public Direction placePair(int r, int c) throws IllegalStateException {
        for (Direction dir : Direction.values()) {
            int nr = r + dir.getDRow();
            int nc = c + dir.getDCol();

            if (!inside(nr, nc) || grid[nr][nc] != EMPTY_CELL) {
                continue;
            }

            Direction opp = dir.opposite();
            int pr = nr + opp.getDRow();
            int pc = nc + opp.getDCol();

            if (!inside(pr, pc) || grid[pr][pc] != EMPTY_CELL) {
                continue;
            }

            // place both tiles
            grid[r][c]  = dir.symbol;
            grid[nr][nc] = opp.symbol;
            return dir;
        }
        throw new IllegalStateException("Unable to place a pair at (" + r + "," + c + ")");
    }

    /** Checks whether the whole board has been filled. */
    public boolean isComplete() {
        for (int r = 1; r <= rows; r++) {
            for (int c = 1; c <= cols; c++) {
                if (grid[r][c] == EMPTY_CELL) {
                    return false;
                }
            }
        }
        return true;
    }

    /** Returns the solved board as a string. */
    public String renderSolution() {
        StringBuilder out = new StringBuilder();
        for (int r = 1; r <= rows; r++) {
            for (int c = 1; c <= cols; c++) {
                out.append(grid[r][c]);
            }
            out.append('\n');
        }
        return out.toString();
    }

    // -----------------------------------------------------------------------
    // Core solving algorithm
    // -----------------------------------------------------------------------
    /**
     * Solves the board using a deterministic propagation based on “cells with exactly one
     * empty neighbour”. If at any point the situation cannot be resolved uniquely,
     * the program prints “Not unique”.
     */
    public static void solve(char[][] source) {
        TilePlacementSolver solver = new TilePlacementSolver(source);

        // Queue cells that currently have exactly one empty neighbour.
        Deque<Integer> queue = new ArrayDeque<>();

        // Helper to encode (row, col) into a single int.
        // This works because row and column are within the original board size.
        BiConsumer<Integer, Integer> enqueueIfNeeded = (r, c) -> {
            if (solver.countEmptyNeighbours(r, c) == 1) {
                queue.addLast(encode(r, c));
            }
        };

        // Initial filling of the queue.
        for (int r = 1; r <= solver.rows; r++) {
            for (int c = 1; c <= solver.cols; c++) {
                enqueueIfNeeded.accept(r, c);
            }
        }

        while (!queue.isEmpty()) {
            int packed = queue.removeFirst();
            int r = packed / 1000;   // simple encoding scheme; board dimensions are small
            int c = packed % 1000;

            // Re‑validate that the cell is still empty and still has exactly one empty neighbour.
            if (solver.grid[r][c] != EMPTY_CELL ||
                solver.countEmptyNeighbours(r, c) != 1) {
                continue;
            }

            try {
                Direction placedDir = solver.placePair(r, c);

                // Propagate newly created candidates.
                for (Direction dir : Direction.values()) {
                    int nr = r + dir.getDRow();
                    int nc = c + dir.getDCol();
                    int pr = nr + dir.opposite().getDRow();
                    int pc = nc + dir.opposite().getDCol();

                    enqueueIfNeeded.accept(nr, nc);
                    enqueueIfNeeded.accept(pr, pc);
                }
            } catch (IllegalStateException e) {
                // Inconsistent configuration → not unique solution.
                System.out.println("Not unique");
                return;
            }
        }

        // After propagation, verify that the whole board is filled.
        if (!solver.isComplete()) {
            System.out.println("Not unique");
            return;
        }

        // Output the solved board.
        System.out.print(solver.renderSolution());
    }

    /** Simple integer encoding for queue storage (row * 1000 + col). */
    private static int encode(int r, int c) {
        return r * 1000 + c;
    }

    // -----------------------------------------------------------------------
    // Entry point
    // -----------------------------------------------------------------------
    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            int n = scanner.nextInt();
            int m = scanner.nextInt();
            scanner.nextLine(); // consume end‑of‑line

            // Read the remaining lines into a temporary array.
            char[][] board = new char[n][];
            for (int i = 0; i < n; i++) {
                board[i] = scanner.nextLine().toCharArray();
            }

            solve(board);
        }
    }
}

/**
 * DominoChecker – reads a grid of characters and determines whether a unique
 * tiling with dominoes exists. If a unique tiling exists, it prints the tiled
 * board; otherwise it prints “Not unique”.
 *
 * The refactor focuses on readability, encapsulation and separation of concerns:
 *   • DominoChecker – orchestrates the whole process (input → solve → output)
 *   • Grid        – holds the board, degree information and tiling logic
 *   • Direction   – enumerates the four cardinal directions with movement vectors
 */
import java.io.PrintWriter;
import java.util.Scanner;

/**
 * Represents the board and all operations that can be performed on it.
 */
final class Grid {

    /** Upper bound used for temporary allocation – does not reflect input size */
    private static final int MAX = 2010;

    /** Movement vectors for four neighbours (right, down, left, up) */
    private static final int[] DR = {0, 1, 0, -1};
    private static final int[] DC = {1, 0, -1, 0};

    /** Symbol used for an obstacle (cannot be tiled) */
    private static final char OBSTACLE = '*';

    /** Symbols used for the four possible tile orientations */
    private static final char[] TILE_SYMBOL = {'^', '>', '<', 'v'};

    private final int rows;
    private final int cols;
    /** Grid cells – 1‑based indexing for easier logic (mirrors original code). */
    private final char[][] board;
    /** Degree of each cell – number of free neighbours that can still be paired */
    private final int[][] degree;

    /** Queue‑like recursion helper used by {@link #assignTile(int, int, int)}. */
    private void assignTile(int r, int c, int dirIdx) {
        if (degree[r][c] != 0) {
            return; // tile already processed
        }

        // Mark current cell as used
        board[r][c] = TILE_SYMBOL[dirIdx];
        board[r + DR[dirIdx]][c + DC[dirIdx]] =
                TILE_SYMBOL[(dirIdx + 2) % 4]; // opposite side of the domino

        // Update degrees of neighbours
        updateDegreesAround(r, c, dirIdx);
        // Recurse on affected neighbours
        for (int k = 0; k < 4; k++) {
            assignTile(r + DR[k][c + DC[k]], dirIdx);
            assignTile(r + DR[dirIdx] + DR[k][c + DC[k]],
                    c + DC[dirIdx] + DC[k], dirIdx);
        }
    }

    /** Adjust the degree of neighbouring cells after a tile is placed. */
    private void updateDegreesAround(int r, int c, int usedDir) {
        for (int k = 0; k < 4; k++) {
            int nr = r + DR[k];
            int nc = c + DC[k];
            if (nr >= 1 && nr <= rows && nc >= 1 && nc <= cols && degree[nr][nc] > 0) {
                degree[nr][nc]--;
            }
            // Update degree of cells that share the just‑placed domino
            int mr = r + DR[usedDir] + DR[k];
            int mc = c + DC[usedDir] + DC[k];
            if (mr >= 1 && mr <= rows && mc >= 1 && mc <= cols && degree[mr][mc] > 0) {
                degree[mr][mc]--;
            }
        }
    }

    /** Constructor – creates a board of size (rows+2)×(cols+2) to allow 1‑based use. */
    Grid(int n, int m) {
        this.rows = n + 2; // extra row/col for boundary safety
        this.cols = m + 2;
        this.board = new char[rows][cols];
        this.degree = new int[rows][cols];
        // Initialise everything to '.' (free). Obstacles will be marked later.
        for (int r = 0; r < rows; r++) {
            java.util.Arrays.fill(board[r], '.');
            java.util.Arrays.fill(degree[r], 0);
        }
    }

    /** Populates the internal structures from raw input. */
    void populate(Scanner scanner) {
        int n = scanner.nextInt();
        int m = scanner.nextInt();
        for (int r = 1; r <= n; r++) {
            String line = scanner.next();
            for (int c = 1; c <= m; c++) {
                char ch = line.charAt(c - 1);
                board[r][c] = ch;
                if (ch == OBSTACLE) {
                    degree[r][c] = -1; // permanently blocked
                } else {
                    // Count how many free neighbours this cell has
                    for (int d = 0; d < 4; d++) {
                        int nr = r + DR[d];
                        int nc = c + DC[d];
                        if (nr >= 1 && nr < rows && nc >= 1 && nc < cols
                                && board[nr][nc] != OBSTACLE) {
                            degree[r][c]++;
                        }
                    }
                }
            }
        }
        // Reset degrees of obstacle cells to -1 to make them immutable
        for (int r = 1; r <= n; r++) {
            for (int c = 1; c <= m; c++) {
                if (board[r][c] == OBSTACLE) {
                    degree[r][c] = -1;
                }
            }
        }
    }

    /** Determines a unique tiling if possible; prints the result directly to the
     *  provided PrintWriter. Returns {@code true} if a tiling was printed,
     *  {@code false} otherwise (i.e. “Not unique”). */
    boolean solveAndPrint(PrintWriter out) {
        // Try to place a tile from every cell that still has degree > 0
        for (int r = 1; r < rows - 1; r++) {
            for (int c = 1; c < cols - 1; c++) {
                fillCell(r, c);
            }
        }

        // If any free ('.') cell remains, the tiling is not unique
        for (int r = 1; r <= rows - 2; r++) {
            for (int c = 1; c <= cols - 2; c++) {
                if (board[r][c] == '.') {
                    out.println("Not unique");
                    return true;
                }
            }
        }

        // Print the solved board
        for (int r = 1; r <= rows - 2; r++) {
            for (int c = 1; c <= cols - 2; c++) {
                out.print(board[r][c]);
            }
            out.println();
        }
        return true;
    }

    /** Recursive helper that attempts to place a tile from (r,c) and propagates
     *  the effect throughout the board. */
    private void fillCell(int r, int c) {
        if (degree[r][c] <= 0) {
            return; // already processed or blocked
        }
        // Find the first direction that leads to an unprocessed neighbour
        for (int d = 0; d < 4; d++) {
            int nr = r + DR[d];
            int nc = c + DC[d];
            if (nr >= 1 && nr < rows && nc >= 1 && nc < cols
                    && board[nr][nc] == '.' && degree[nr][nc] > 0) {
                assignTile(r, c, d);
                return;
            }
        }
        // If no direction can be taken, the current state is invalid – backtrack.
        // The caller will detect remaining '.' cells later and report “Not unique”.
    }
}

/** Wrapper class that contains the `main` entry point and glues everything together. */
final class DominoChecker {

    /** Entry point – reads input, processes it and writes the answer. */
    public void solve() throws Exception {
        try (Scanner scanner = new Scanner(System.in)) {
            Grid grid = new Grid(0, 0);
            grid.populate(scanner);
            try (PrintWriter out = new PrintWriter(System.out)) {
                grid.solveAndPrint(out);
            }
        }
    }

    public static void main(String[] args) throws Exception {
        new DominoChecker().solve();
    }
}

import java.io.*;
import java.util.*;

/**
 * Solves the “Edge orientation / tile placement” problem (Codeforces 292D).
 * The program reads a grid, determines a unique tiling if it exists and prints
 * the resulting board, otherwise it prints “Not unique”.
 *
 * Refactoring goals:
 *   • Meaningful names and constants
 *   • Extraction of logical steps into small, well‑named methods
 *   • Use of Java 8+ features (try‑with‑resources, generics, final classes)
 *   • Removal of raw types and unnecessary fields
 */
public class Div2_292_D {

    /* --------------------------------------------------------------------- */
    /*  Constants & Direction vectors                                         */
    /* --------------------------------------------------------------------- */
    private static final int[][] DIRECTIONS = {
            {0, -1},   // up
            {0,  1},   // down
            {-1, 0},   // left
            {1,  0}    // right
    };
    private static final char[] REP_X = {'>', '<', 'v', '^'};
    private static final char[] REP_Y = {'<', '>', '^', 'v'};

    /* --------------------------------------------------------------------- */
    /*  Entry point                                                          */
    /* --------------------------------------------------------------------- */
    public static void main(String[] args) throws IOException {
        // Fast, safe resource handling
        try (BufferedReader br = new BufferedReader(
                new InputStreamReader(System.in))) {

            int n = Integer.parseInt(nextToken(br));
            int m = Integer.parseInt(nextToken(br));

            char[][] grid = readGrid(br, n, m);
            int[][] degree = computeDegree(grid, n, m);

            Queue<Point> queue = collectDegreeOneCells(degree, grid);
            process(queue, degree, grid, n, m);

            if (hasRemainingEmptyCells(grid)) {
                System.out.println("Not unique");
            } else {
                printGrid(grid);
            }
        }
    }

    /* --------------------------------------------------------------------- */
    /*  Input helpers                                                         */
    /* --------------------------------------------------------------------- */
    private static char[][] readGrid(BufferedReader br, int n, int m) throws IOException {
        char[][] grid = new char[n][m];
        for (int i = 0; i < n; i++) {
            grid[i] = br.readLine().toCharArray();
        }
        return grid;
    }

    private static String nextToken(BufferedReader br) throws IOException {
        return br.readLine().trim();
    }

    /* --------------------------------------------------------------------- */
    /*  Degree computation                                                    */
    /* --------------------------------------------------------------------- */
    /** Counts for each cell how many adjacent non‑* cells exist. */
    private static int[][] computeDegree(char[][] grid, int n, int m) {
        int[][] degree = new int[n][m];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i][j] == '*') {
                    degree[i][j] = -1;               // never processed
                    continue;
                }
                int cnt = 0;
                for (int[] d : DIRECTIONS) {
                    int ni = i + d[0];
                    int nj = j + d[1];
                    if (inGrid(ni, nj, n, m) && grid[ni][nj] != '*') {
                        cnt++;
                    }
                }
                degree[i][j] = cnt;
            }
        }
        return degree;
    }

    /* --------------------------------------------------------------------- */
    /*  Queue preparation                                                     */
    /* --------------------------------------------------------------------- */
    /** Returns a queue with all cells whose degree is exactly one. */
    private static Queue<Point> collectDegreeOneCells(int[][] degree, char[][] grid) {
        Queue<Point> queue = new LinkedList<>();
        for (int i = 0; i < degree.length; i++) {
            for (int j = 0; j < degree[i].length; j++) {
                if (grid[i][j] != '*' && degree[i][j] == 1) {
                    queue.add(new Point(i, j));
                }
            }
        }
        return queue;
    }

    /* --------------------------------------------------------------------- */
    /*  Main processing loop                                                  */
    /* --------------------------------------------------------------------- */
    /** Repeatedly resolves forced tile placements until no more are possible. */
    private static void process(Queue<Point> queue,
                                 int[][] degree,
                                 char[][] grid,
                                 int n,
                                 int m) {

        while (!queue.isEmpty()) {
            Point cur = queue.poll();
            if (degree[cur.x][cur.y] != 1) {
                continue;                         // stale entry
            }

            boolean paired = false;
            for (int k = 0; k < DIRECTIONS.length && !paired; k++) {
                int nx = cur.x + DIRECTIONS[k][0];
                int ny = cur.y + DIRECTIONS[k][1];
                if (inGrid(nx, ny, n, m) && grid[nx][ny] == '.') {
                    // Place the unique tile
                    grid[cur.x][cur.y] = REP_X[k];
                    grid[nx][ny] = REP_Y[k];
                    degree[nx][ny] = -1;           // mark neighbour as fixed

                    paired = true;
                    // Propagate degree changes caused by this placement
                    propagate(nx, ny, degree, grid, queue);
                }
            }

            // The original algorithm also decrements the degree of the current cell
            // after a successful pairing.
            if (paired) {
                propagate(cur.x, cur.y, degree, grid, queue);
            }
        }
    }

    /* --------------------------------------------------------------------- */
    /*  Helper utilities                                                      */
    /* --------------------------------------------------------------------- */
    /** Decrements the degree of all free neighbours of (x,y) and enqueues
     *  any neighbour whose degree drops to 1. */
    private static void propagate(int x, int y,
                                   int[][] degree,
                                   char[][] grid,
                                   Queue<Point> queue) {
        for (int[] d : DIRECTIONS) {
            int nx = x + d[0];
            int ny = y + d[1];
            if (inGrid(nx, ny, degree.length, degree[0].length)
                    && grid[nx][ny] == '.') {
                degree[nx][ny]--;
                if (degree[nx][ny] == 1) {
                    queue.add(new Point(nx, ny));
                }
            }
        }
    }

    /** Checks whether any '.' cells remain – if so the solution is not unique. */
    private static boolean hasRemainingEmptyCells(char[][] grid) {
        for (char[] row : grid) {
            for (char cell : row) {
                if (cell == '.') {
                    return true;
                }
            }
        }
        return false;
    }

    /** Simple pretty‑printer for the final board. */
    private static void printGrid(char[][] grid) {
        for (char[] row : grid) {
            System.out.println(new String(row));
        }
    }

    /** Utility to test whether a coordinate lies inside the grid bounds. */
    private static boolean inGrid(int x, int y, int n, int m) {
        return x >= 0 && x < n && y >= 0 && y < m;
    }

    /** Minimal container for a grid coordinate. */
    private static final class Point {
        final int x;
        final int y;

        Point(int x, int y) {
            this.x = x;
            this.y = y;
        }
    }
}

import java.io.*;
import java.util.StringTokenizer;

/**
 * D515_DrazilTiles – solves a tiling puzzle where each empty cell ('.')
 * must be paired with exactly one adjacent empty cell.
 *
 * <p>Refactored for readability, maintainability and clear separation of concerns.
 */
public class D515_DrazilTiles implements Closeable {

    /* -----------------------------------------------------------
     *  Input handling
     * ----------------------------------------------------------- */
    private final BufferedReader reader;
    private final PrintWriter writer;
    private StringTokenizer stringTokenizer;          // reused for every token
    private char[][] board;                           // current board state

    /* -----------------------------------------------------------
     *  Direction handling
     * ----------------------------------------------------------- */
    private enum Direction {
        UP(-1, 0), LEFT(0, -1), DOWN(1, 0), RIGHT(0, 1);

        final int dr;
        final int dc;
        Direction(int dr, int dc) {
            this.dr = dr;
            this.dc = dc;
        }
    }

    /* -----------------------------------------------------------
     *  Construction / resource management
     * ----------------------------------------------------------- */
    public D515_DrazilTiles() throws IOException {
        this.reader = new BufferedReader(new InputStreamReader(System.in));
        this.writer = new PrintWriter(System.out);
    }

    /* -----------------------------------------------------------
     *  Public API
     * ----------------------------------------------------------- */
    public void solve() throws IOException {
        readBoard();
        propagateForcedPlacements();
        verifyUniqueness();
        outputSolution();
    }

    public void close() throws IOException {
        reader.close();
        writer.close();
    }

    /* -----------------------------------------------------------
     *  Core algorithm
     * ----------------------------------------------------------- */
    /** Places tiles wherever a cell has exactly one free neighbour. */
    private void propagateForcedPlacements() {
        for (int r = 0; r < board.length; r++) {
            for (int c = 0; c < board[r].length; c++) {
                if (board[r][c] == '.') {
                    force(r, c);
                }
            }
        }
    }

    /** Attempts to place a tile at (row,col) when a unique neighbour exists,
     *  then recurses into newly placed cells. */
    private void force(int row, int col) {
        int mask = countAdjacentEmptyMasks(row, col);
        if (Integer.bitCount(mask) != 1) {
            return;                     // not a forced move – nothing to do
        }

        placeTile(row, col, mask);

        // Continue propagation from cells that may now become forced
        for (Direction dir : Direction.values()) {
            int nr = row + dir.dr;
            int nc = col + dir.dc;
            if (isEmpty(nr, nc)) {
                force(nr, nc);
            }
        }
    }

    /** Places the appropriate characters for the unique direction encoded by mask. */
    private void placeTile(int row, int col, int mask) {
        switch (mask) {
            case 1 << Direction.UP.ordinal()    -> placeUp(row, col);
            case 1 << Direction.LEFT.ordinal()    -> placeLeft(row, col);
            case 1 << Direction.DOWN.ordinal()    -> placeDown(row, col);
            case 1 << Direction.RIGHT.ordinal()   -> placeRight(row, col);
        }
    }

    private void placeUp(int r, int c) {
        board[r][c] = '^';
        board[r - 1][c] = 'v';
    }

    private void placeDown(int r, int c) {
        board[r][c] = 'v';
        board[r + 1][c] = '^';
    }

    private void placeLeft(int r, int c) {
        board[r][c] = '<';
        board[r][c + 1] = '>';
    }

    private void placeRight(int r, int c) {
        board[r][c] = '>';
        board[r][c - 1] = '<';
    }

    /** Returns true if coordinates are inside the board and the cell is still '.'. */
    private boolean isEmpty(int r, int c) {
        return r >= 0 && r < board.length
                && c >= 0 && c < board[0].length
                && board[r][c] == '.';
    }

    /** Counts how many of the four neighbours are empty and builds a bit mask. */
    private int countAdjacentEmptyMasks(int row, int col) {
        int mask = 0;
        for (Direction dir : Direction.values()) {
            if (isEmpty(row + dir.dr, col + dir.dc)) {
                mask |= 1 << dir.ordinal();
            }
        }
        return mask;
    }

    /** Reads the board dimensions and the board itself from stdin. */
    private void readBoard() throws IOException {
        int rows = nextInt();
        int cols = nextInt();
        board = new char[rows][cols];

        for (int r = 0; r < rows; r++) {
            String line = next();
            for (int c = 0; c < cols; c++) {
                board[r][c] = line.charAt(c);
            }
        }
    }

    /** Writes “Not unique” if any empty cell remains after processing. */
    private void verifyUniqueness() {
        for (char[] line : board) {
            for (char cell : line) {
                if (cell == '.') {
                    writer.println("Not unique");
                    return;
                }
            }
        }
    }

    /** Prints the solved board to stdout. */
    private void outputSolution() {
        for (char[] line : board) {
            writer.println(new String(line));
        }
    }

    /* -----------------------------------------------------------
     *  Helper input methods
     * ----------------------------------------------------------- */
    private String nextToken() throws IOException {
        while (stringTokenizer == null || !stringTokenizer.hasMoreTokens()) {
            stringTokenizer = new StringTokenizer(reader.readLine());
        }
        return stringTokenizer.nextToken();
    }

    private int nextInt() throws IOException { return Integer.parseInt(nextToken()); }
    private String next() throws IOException { return nextToken(); }

    /* -----------------------------------------------------------
     *  Entry point
     * ----------------------------------------------------------- */
    public static void main(String[] args) throws IOException {
        try (D515_DrazilTiles solver = new D515_DrazilTiles()) {
            solver.solve();
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Entry point of the program.
 */
