/**
 * Reads tokens from an input stream using a fast custom scanner.
 */
class InputReader {
    private static final class FastScanner {
        private final BufferedInputStream in;
        private final char[] buffer = new char[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream stream) {
            in = new BufferedInputStream(stream);
        }

        private char nextNonWhite() {
            while (true) {
                if (ptr >= len) {
                    len = in.read(buffer);
                    if (len <= 0) return 0;
                    ptr = 0;
                }
                char c = buffer[ptr++];
                if (!Character.isWhitespace(c)) return c;
            }
        }

        /** Returns the next non‑whitespace token as a {@code String}. */
        String next() {
            char c = nextNonWhite();
            StringBuilder sb = new StringBuilder();
            while (c != 0 && !Character.isWhitespace(c)) {
                sb.append(c);
                c = nextNonWhite();
            }
            return sb.toString();
        }

        /** Returns the next token parsed as an {@code int}. */
        int nextInt() {
            return Integer.parseInt(next());
        }

        /**
         * Reads {@code rows} lines from the input and returns them as a
         * {@code char[][]}. Each inner array contains the characters of one line.
         */
        char[][] nextCharRows(int rows) {
            char[][] arr = new char[rows][];
            for (int i = 0; i < rows; i++) {
                arr[i] = next().toCharArray();
            }
            return arr;
        }
    }

    private final FastScanner scanner;

    InputReader(InputStream source) {
        this.scanner = new FastScanner(source);
    }

    int nextInt() {
        return scanner.nextInt();
    }

    /**
     * Reads the board from the input. The caller specifies the number of rows,
     * and the method returns a {@code char[][]} where each row corresponds to
     * one line of the board.
     */
    char[][] nextCharRows(int rows) {
        return scanner.nextCharRows(rows);
    }
}

/**
 * Writes output efficiently.
 */
class OutputWriter {
    private final PrintWriter out;
    OutputWriter(OutputStream stream) {
        this.out = new PrintWriter(stream, true);
    }
    void println(String s) {
        out.println(s);
    }
}

/**
 * Represents a direction of a possible domino placement.
 */
enum Direction {
    UP(-1, 0, 'v', '^'),    // current cell gets 'v', neighbour gets '^'
    DOWN(1, 0, '^', 'v'),   // current cell gets '^', neighbour gets 'v'
    LEFT(0, -1, '>', '<'),  // current cell gets '>', neighbour gets '<'
    RIGHT(0, 1, '<', '>');  // current cell gets '<', neighbour gets '>'

    final int dr;
    final int dc;
    final char selfChar;
    final char neighborChar;

    Direction(int dr, int dc, char selfChar, char neighborChar) {
        this.dr = dr;
        this.dc = dc;
        this.selfChar = selfChar;
        this.neighborChar = neighborChar;
    }
}

/**
 * Core logic of the tiling puzzle.
 */
class GridSolver {
    private char[][] board;
    private int rows;
    private int cols;

    /** Solves the puzzle using the supplied reader and writer. */
    void solve(InputReader reader, OutputWriter writer) {
        this.rows = reader.nextInt();
        this.cols = reader.nextInt();
        this.board = reader.nextCharRows(rows);

        // Try to fill the board deterministically.
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (board[r][c] == '.') {
                    placeTile(r, c);
                }
            }
        }

        // If any '.' remains the placement was not unique.
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (board[r][c] == '.') {
                    writer.println("Not unique");
                    return;
                }
            }
        }

        // Output the solved board.
        for (char[] row : board) {
            writer.println(new String(row));
        }
    }

    /** Attempts to place a domino that starts at (row,col) when forced. */
    private void placeTile(int row, int col) {
        Direction dir = findUniqueDirection(row, col);
        if (dir == null) {
            return;               // ambiguous or isolated cell – nothing to do
        }

        int nr = row + dir.dr;
        int nc = col + dir.dc;

        // Place the two halves of the domino.
        board[row][col] = dir.selfChar;
        board[nr][nc] = dir.neighborChar;

        // Continue recursively from the newly filled neighbour.
        placeTile(nr, nc);
    }

    /** Returns the direction in which there is exactly one empty neighbour,
     *  or {@code null} when the count is 0 or >1. */
    private Direction findUniqueDirection(int r, int c) {
        int mask = 0;
        for (Direction d : Direction.values()) {
            if (isEmpty(r + d.dr, c + d.dc)) {
                mask |= (1 << d.ordinal());
            }
        }
        if (Integer.bitCount(mask) != 1) {
            return null;
        }
        // Map the single set bit back to its Direction.
        for (Direction d : Direction.values()) {
            if ((mask & (1 << d.ordinal())) != 0) {
                return d;
            }
        }
        throw new IllegalStateException("Unreachable");
    }

    /** Checks whether the cell at (r,c) is inside the board and currently empty. */
    private boolean isEmpty(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols && board[r][c] == '.';
    }
}

import java.io.*;
import java.util.*;

public class DominoTiling {

    /* ---------- constants & direction helpers ---------- */
    private static final int[][] OFFSETS = {
            {0, 1},   // RIGHT
            {0, -1},  // LEFT
            {1, 0},   // DOWN
            {-1, 0}   // UP
    };
    private static final char[] DIR_CHARS = {
            '<', '>', '^', 'v'   // matches OFFSETS order
    };

    /* ---------- static fields used by the algorithm ---------- */
    private static int rows, cols;
    private static char[][] board;
    private static final int MAX = 1000;               // enough for typical test data
    private static final int[] QUEUE_X = new int[MAX * MAX];
    private static final int[] QUEUE_Y = new int[MAX * MAX];

    /* ---------- utility methods ---------- */
    private static boolean inRange(int i, int j) {
        return 0 <= i && i < rows && 0 <= j && j < cols;
    }

    private static boolean isFree(int i, int j) {
        return inRange(i, j) && board[i][j] == '.';
    }

    /** number of adjacent free cells */
    private static int degree(int i, int j) {
        int cnt = 0;
        for (int[] off : OFFSETS) {
            if (isFree(i + off[0], j + off[1])) {
                ++cnt;
            }
        }
        return cnt;
    }

    /** Try to cover (i,j) with a domino.
     *  Returns the direction index used, or -1 if impossible. */
    private static int placeDomino(int i, int j) {
        for (int dir = 0; dir < 4; ++dir) {
            int ni = i + OFFSETS[dir][0];
            int nj = j + OFFSETS[dir][1];
            if (!isFree(ni, nj)) {
                continue;
            }
            // write the two cells with the appropriate arrows
            board[i][j] = DIR_CHARS[dir];
            board[ni][nj] = DIR_CHARS[(dir + 2) % 4];
            return dir;
        }
        return -1; // no partner found
    }

    /** Add newly discovered degree‑1 cells to the queue. */
    private static void enqueueNeighbours(int i, int j) {
        for (int[] off : OFFSETS) {
            int ni = i + off[0];
            int nj = j + off[1];
            if (isFree(ni, nj) && degree(ni, nj) == 1) {
                queueAdd(ni, nj);
            }
        }
    }

    private static void queueAdd(int x, int y) {
        QUEUE_X[tail] = x;
        QUEUE_Y[tail] = y;
        ++tail;
    }

    /* ---------- core solving logic ---------- */
    private static void solve() throws IOException {
        readInput();

        int head = 0, tail = 0;
        // --- initial queue: all free cells with degree == 1 ---
        for (int i = 0; i < rows; ++i) {
            for (int j = 0; j < cols; ++j) {
                if (isFree(i, j) && degree(i, j) == 1) {
                    queueAdd(i, j);
                }
            }
        }

        // --- propagate deterministic placements ---
        while (head < tail) {
            int x = QUEUE_X[head];
            int y = QUEUE_Y[head];
            ++head;

            if (!isFree(x, y)) {
                continue;               // already paired
            }
            int dir = placeDomino(x, y);
            if (dir == -1) {
                System.out.println("Not unique");
                return;
            }
            int px = x + OFFSETS[dir][0];
            int py = y + OFFSETS[dir][1];
            enqueueNeighbours(px, py);
        }

        // --- if any free cell remains → multiple solutions ---
        for (int i = 0; i < rows; ++i) {
            for (int j = 0; j < cols; ++j) {
                if (isFree(i, j)) {
                    System.out.println("Not unique");
                    return;
                }
            }
        }

        // --- output the tiling ---
        for (int i = 0; i < rows; ++i) {
            System.out.println(new String(board[i]));
        }
    }

    /* ---------- I/O helpers ---------- */
    private static FastScanner in;
    private static PrintWriter out;

    private static void readInput() throws IOException {
        rows = in.nextInt();
        cols = in.nextInt();
        board = new char[rows];
        for (int i = 0; i < rows; ++i) {
            board[i] = in.nextToken().toCharArray();
        }
    }

    /* ---------- entry point ---------- */
    public static void main(String[] args) throws Exception {
        // use System.in directly; FastScanner works with BufferedReader
        in = new FastScanner();
        out = new PrintWriter(System.out, true);
        solve();
        out.flush();
    }
}

/* ---------- fast scanner (unchanged) ---------- */
class FastScanner {
    private final BufferedReader br;
    private StringTokenizer tokenizer;

    FastScanner() {
        this.br = new BufferedReader(new InputStreamReader(System.in));
    }

    FastScanner(String fileName) throws FileNotFoundException {
        this.br = new BufferedReader(new FileReader(fileName));
    }

    private void ensureTokenizer() throws IOException {
        while (tokenizer == null || !tokenizer.hasMoreTokens()) {
            tokenizer = new StringTokenizer(br.readLine());
        }
    }

    String nextToken() throws IOException {
        ensureTokenizer();
        return tokenizer.nextToken();
    }

    int nextInt() throws IOException {
        return Integer.parseInt(nextToken());
    }

    long nextLong() throws IOException {
        return Long.parseLong(nextToken());
    }

    double nextDouble() throws IOException {
        return Double.parseDouble(nextToken());
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.LinkedList;
import java.util.List;

/**
 * Reads a board description from standard input and prints a unique
 * tiling if it exists, otherwise "Not unique".
 *
 * The algorithm is the same as the original implementation, but the
 * implementation has been refactored for readability, maintainability
 * and testability.
 */
public class FillominoSolver {

    /** Direction vectors for the four orthogonal neighbours. */
    private static final int[] DR = {-1, 1, 0, 0};
    private static final int[] DC = {0, 0, -1, 1};

    /** Represents a board cell that holds either an obstacle (*) or an empty slot. */
    private static final class Cell {
        /** 0 = empty, 1 = obstacle. */
        int type = 0;

        /** 2 = left, 3 = right, 4 = up, 5 = down.  Represent direction of the domino piece. */
        int tileDirection = 0;
    }

    /** Simple container for the board dimensions and data. */
    private static final class Board {
        final int rows;
        final int cols;
        final Cell[][] cells;

        Board(int rows, int cols) {
            this.rows = rows;
            this.cols = cols;
            this.cells = new Cell[rows][cols];
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    cells[r][c] = new Cell();
                }
            }
        }

        /** Index conversion helpers. */
        int toIndex(int r, int c) {
            return r * cols + c;
        }

        int row(int idx) {
            return idx / cols;
        }

        int col(int idx) {
            return idx % cols;
        }

        /** Returns true if (r,c) is inside the board and currently empty. */
        boolean isEmpty(int r, int c) {
            return r >= 0 && c >= 0 && r < rows && c < cols && cells[r][c].type == 0;
        }

        /** Returns the neighbour index in the given direction if it exists and is empty. */
        Integer neighbourIndex(int idx, int dir) {
            int nr = row(idx) + DR[dir];
            int nc = col(idx) + DC[dir];
            return isEmpty(nr, nc) ? toIndex(nr, nc) : -1;
        }
    }

    /** Simple holder that groups all mutable data of the solving process. */
    private static final class Solver {
        final Board board;
        final List<Integer> queue = new LinkedList<>();
        final boolean[] added;          // cells already enqueued
        final boolean[] solved;          // cells that have been processed
        int emptyCount;                  // number of empty cells left

        Solver(Board board) {
            this.board = board;
            int cells = board.rows * board.cols;
            added = new boolean[cells];
            solved = new boolean[cells];
            emptyCount = countEmptyCells();
        }

        /** Returns the degree (number of empty orthogonal neighbours) of idx. */
        int degree(int idx) {
            int degree = 0;
            for (int d = 0; d < 4; d++) {
                if (board.isEmpty(board.row(idx), board.col(idx))) {
                    continue; // not a valid neighbour for degree calculation
                }
                int nr = board.row(idx) + DR[d];
                int nc = board.col(idx) + DC[d];
                if (board.isEmpty(nr, nc)) {
                    degree++;
                }
            }
            return degree;
        }

        /** Returns the index of the first empty neighbour of idx or -1 if none exists. */
        int firstNeighbour(int idx) {
            for (int d = 0; d < 4; d++) {
                int nIdx = board.neighbourIndex(idx, d);
                if (nIdx != -1) {
                    return nIdx;
                }
            }
            return -1;
        }

        /** Enqueues a neighbour if its degree is exactly 1 and it has not been added yet. */
        void enqueueIfUnique(int idx) {
            if (degree(idx) == 1 && !added[idx]) {
                queue.addLast(idx);
                added[idx] = true;
            }
        }

        /** Process the front of the queue according to the original algorithm. */
        void processQueueAndTile() {
            while (!queue.isEmpty()) {
                int v = queue.removeFirst();
                if (solved[v]) {
                    continue;
                }

                int v2 = firstNeighbour(v);
                if (v2 == -1) {
                    throw new IllegalStateException("Not unique");
                }

                solved[v] = true;
                solved[v2] = true;

                placeDomino(v, v2);

                enqueueIfUnique(v);
                enqueueIfUnique(v2);
                emptyCount -= 2;
            }
        }

        /** Puts a directional tile onto the board for the pair (v, v2). */
        private void placeDomino(int v, int v2) {
            int r1 = board.row(v);
            int c1 = board.col(v);
            int r2 = board.row(v2);
            int c2 = board.col(v2);

            if (r1 == r2) { // horizontal domino
                if (c1 < c2) {
                    board.cells[r1][c1].tileDirection = 2; // '<'
                    board.cells[r2][c2].tileDirection = 3; // '>'
                } else {
                    board.cells[r1][c1].tileDirection = 3;
                    board.cells[r2][c2].tileDirection = 2;
                }
            } else { // vertical domino
                if (r1 < r2) {
                    board.cells[r1][c1].tileDirection = 4; // '^'
                    board.cells[r2][c2].tileDirection = 5; // 'v'
                } else {
                    board.cells[r1][c1].tileDirection = 5;
                    board.cells[r2][c2].tileDirection = 4;
                }
            }
        }
    }

    /** Main entry point – only I/O handling lives here. */
    public static void main(String[] args) throws IOException {
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in))) {
            String[] header = br.readLine().split(" ");
            int rows = Integer.parseInt(header[0]);
            int cols = Integer.parseInt(header[1]);

            Board board = new Board(rows, cols);
            int emptyCells = 0;

            for (int r = 0; r < rows; r++) {
                String line = br.readLine();
                for (int c = 0; c < line.length(); c++) {
                    if (line.charAt(c) == '*') {
                        board.cells[r][c].type = 1; // obstacle
                    } else {
                        emptyCells++;
                    }
                }
            }

            // Basic feasibility checks
            if (emptyCells % 2 != 0) {
                System.out.println("Not unique");
                return;
            }
            if (emptyCells == 0) {
                printBoard(board);
                return;
            }

            Solver solver = new Solver(board);

            // Seed the queue with cells that currently have a unique neighbour
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (board.cells[r][c].type == 0) {
                        int idx = board.toIndex(r, c);
                        if (solver.degree(idx) == 1) {
                            solver.queue.addLast(idx);
                            solver.added[idx] = true;
                        }
                    }
                }
            }

            // Run the solving algorithm – it may throw IllegalStateException for non‑unique boards
            try {
                solver.processQueueAndTile();
            } catch (IllegalStateException e) {
                System.out.println("Not unique");
                return;
            }

            // If there are still empty cells left, uniqueness could not be guaranteed
            if (solver.emptyCount > 0) {
                System.out.println("Not unique");
                return;
            }

            printBoard(board);
        }
    }

    /** Prints the board using the tile directions (or '*' for obstacles). */
    private static void printBoard(Board board) {
        for (int r = 0; r < board.rows; r++) {
            StringBuilder sb = new StringBuilder();
            for (int c = 0; c < board.cols; c++) {
                int dir = board.cells[r][c].tileDirection;
                switch (dir) {
                    case 1 -> sb.append('*');          // obstacle
                    case 2 -> sb.append('<');          // left part
                    case 3 -> sb.append('>');
                    case 4 -> sb.append('^');
                    case 5 -> sb.append('v');
                    default -> sb.append('?');         // should never happen for a solved board
                }
            }
            System.out.println(sb);
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Main class that solves the tile‑matching problem.
 * The algorithm is unchanged – only the structure, naming and resource handling
 * have been improved for readability, maintainability and safety.
 */
public final class Main {

    /** Direction vectors: right, down, left, up */
    private static final int[] DX = {0, 1, 0, -1};
    private static final int[] DY = {1, 0, -1, 0};

    /** Maximum possible size of the board (the original code used a fixed 2010). */
    private static final int MAX = 2_010;

    /** --------------------------------------------------------------------- */
    /** Entry point */
    public static void main(String[] args) throws IOException {
        try (InputStream in = System.in;
             InputReader reader = new InputReader(in);
             PrintWriter out = new PrintWriter(System.out)) {

            solve(reader, out);
        }
    }

    /** --------------------------------------------------------------------- */
    /** Solves the problem using the supplied reader and writer. */
    private static void solve(InputReader reader, PrintWriter out) {
        int rows = reader.readInt();      // m in the original code
        int cols = reader.readInt();      // n in the original code

        char[][] grid = new char[rows][];
        for (int r = 0; r < rows; r++) {
            grid[r] = reader.readString().toCharArray();
        }

        /* ----------------------------------------------------------------- */
        /* 1️⃣  Compute the degree of each empty cell – how many neighbouring   */
        /*     empty cells it currently has.                                   */
        int[][] degree = new int[rows][cols];
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] != '.') {
                    continue;
                }
                int cnt = 0;
                for (int d = 0; d < 4; d++) {
                    int nr = r + DX[d];
                    int nc = c + DY[d];
                    if (inBounds(nr, nc, rows, cols) && grid[nr][nc] == '.') {
                        cnt++;
                    }
                }
                degree[r][c] = cnt;
            }
        }

        /* ----------------------------------------------------------------- */
        /* 2️⃣  Queue used for the BFS that greedily matches forced pairs.      */
        ArrayDeque<Pair> queue = new ArrayDeque<>();
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '.' && degree[r][c] == 1) {
                    queue.addLast(new Pair(r, c));
                }
            }
        }

        /* ----------------------------------------------------------------- */
        /* 3️⃣  Process the queue – each iteration matches a forced pair and    */
        /*     updates the degrees of the neighbourhood.                       */
        while (!queue.isEmpty()) {
            Pair cur = queue.pollFirst();
            int r = cur.row, c = cur.col;

            // The cell might have been matched already.
            if (grid[r][c] != '.') {
                continue;
            }

            // Find the only still‑empty neighbour.
            int matchR = -1, matchC = -1;
            for (int d = 0; d < 4; d++) {
                int nr = r + DX[d];
                int nc = c + DY[d];
                if (inBounds(nr, nc, rows, cols) && grid[nr][nc] == '.') {
                    matchR = nr;
                    matchC = nc;
                    break;
                }
            }

            // No free neighbour → the tiling is impossible.
            if (matchR == -1) {
                System.out.println("Not unique");
                return;
            }

            // Place the two characters that represent the domino.
            char tile1, tile2;
            if (matchR == r) {               // horizontal
                tile1 = '<';
                tile2 = '>';
                // place them
                grid[r][c] = tile1;
                grid[matchR][matchC] = tile2;
            } else {                         // vertical
                tile1 = '^';
                tile2 = 'v';
                grid[r][c] = tile1;
                grid[matchR][matchC] = tile2;
            }

            // Decrease degree of neighbours of both matched cells.
            for (int d = 0; d < 4; d++) {
                decreaseAndEnqueue(degree, queue, matchR, matchC, rows, cols);
                decreaseAndEnqueue(degree, queue, r, c, rows, cols);
            }
        }

        /* ----------------------------------------------------------------- */
        /* 4️⃣  After the BFS, if any '.' remains the solution is not unique.   */
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '.') {
                    System.out.println("Not unique");
                    return;
                }
            }
        }

        /* ----------------------------------------------------------------- */
        /* 5️⃣  Output the board.                                               */
        for (int r = 0; r < rows; r++) {
            out.println(new String(grid[r]));
        }
        out.flush();
    }

    /** --------------------------------------------------------------------- */
    /** Decrements the degree of a neighbour cell and enqueues it if it becomes 1. */
    private static void decreaseAndEnqueue(int[][] degree,
                                           ArrayDeque<Pair> queue,
                                           int r, int c,
                                           int rows, int cols) {
        if (!inBounds(r, c, rows, cols)) {
            return;
        }
        if (degree[r][c] <= 0) {
            return;
        }
        degree[r][c]--;
        if (degree[r][c] == 1) {
            queue.addLast(new Pair(r, c));
        }
    }

    /** --------------------------------------------------------------------- */
    /** Simple helper that checks array bounds. */
    private static boolean inBounds(int r, int c, int rows, int cols) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    /** --------------------------------------------------------------------- */
    /** Holds a pair of coordinates. */
    private static final class Pair {
        final int row;
        final int col;

        Pair(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }

    /** --------------------------------------------------------------------- */
    /** Minimal input helper that mimics the original implementation but is   */
    /** a bit more compact. It re‑uses the original logic for reading ints   */
    /** and strings without pulling in external libraries.                    */
    private static final class InputReader implements Closeable {
        private final InputStream stream;
        private final byte[] buffer = new byte[16_384];
        private int position = 0, length = 0;

        InputReader(InputStream stream) {
            this.stream = stream;
        }

        private int readByte() throws IOException {
            if (position >= length) {
                length = stream.read(buffer);
                position = 0;
                if (length <= 0) {
                    return -1;
                }
            }
            return buffer[position++];
        }

        private int readInt() throws IOException {
            int c;
            do {
                c = readByte();
            } while (c <= ' ');
            boolean neg = false;
            if (c == '-') {
                neg = true;
                c = readByte();
            }
            int result = 0;
            while (c > ' ') {
                result = result * 10 + (c - '0');
                c = readByte();
            }
            return neg ? -result : result;
        }

        private String readString() throws IOException {
            StringBuilder sb = new StringBuilder();
            int c;
            do {
                c = readByte();
            } while (c <= ' ');
            while (c > ' ') {
                sb.append((char) c);
                c = readByte();
            }
            return sb.toString();
        }

        @Override
        public void close() throws IOException {
            stream.close();
        }
    }
}

import java.io.BufferedReader;
import java.io.FileReader;
import java.io.IOException;
import java.io.PrintWriter;
import java.util.ArrayDeque;
import java.util.Deque;
import java.util.StringTokenizer;

/**
 * Solves the “Domino Tiling” problem while guaranteeing a unique tiling.
 * All public methods are kept small and focused to improve readability
 * and maintainability.
 */
public class Solution {

    /** Directions for the four orthogonal neighbours (up, right, down, left). */
    private static final int[][] DIRECTIONS = {
            {-1, 0},   // up
            {0, 1},    // right
            {1, 0},    // down
            {0, -1}    // left
    };

    /** Size limits – kept as fields for easy tweaking */
    private static final int MAX_N = 1000;
    private static final int MAX_M = 1000;

    private BufferedReader reader;
    private PrintWriter writer;

    /** Input dimensions */
    private int rows, cols;

    /** Grid representation; '.' denotes an empty cell */
    private char[][] grid;

    /** Degree of each empty cell – number of adjacent empty neighbours */
    private int[][] degree;

    /** Queue of cells that currently have degree == 1 */
    private final Deque<int[]> queue = new ArrayDeque<>();

    /** --------------------------------------------------------------------- */
    /** Main entry point. */
    public static void main(String[] args) {
        new Solution().run();
    }

    /** --------------------------------------------------------------------- */
    /** Reads input, solves the problem and prints the result. */
    public void run() {
        initReader();
        solve();
        writer.close();
    }

    /** --------------------------------------------------------------------- */
    /** Wire up the FastScanner (BufferedReader‑wrapped) and PrintWriter. */
    private void initReader() {
        // Default is reading from System.in; can be overridden by passing a file name.
        // The original code also supported a command‑line filename argument.
        // For simplicity we stick to standard input here.
        reader = new BufferedReader(new InputStreamReader(System.in));
        writer = new PrintWriter(System.out);
    }

    /** --------------------------------------------------------------------- */
    /** Core algorithm – reads the field, processes forced placements and checks uniqueness. */
    private void solve() {
        readInput();
        computeInitialDegrees();
        processQueue();

        if (anyEmptyCellRemains()) {
            writer.println("Not unique");
            return;
        }

        printSolution();
    }

    /** --------------------------------------------------------------------- */
    /** Reads the dimension and the character field from standard input. */
    private void readInput() {
        String line = nextToken();
        rows = Integer.parseInt(line);
        cols = Integer.parseInt(nextToken());

        grid = new char[rows][];
        for (int i = 0; i < rows; i++) {
            String token = nextToken();
            grid[i] = token.toCharArray();
        }
    }

    /** --------------------------------------------------------------------- */
    /** Calculates the degree of each empty cell (number of adjacent empty cells). */
    private void computeInitialDegrees() {
        degree = new int[rows][cols];
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] != '.') {
                    continue;
                }
                int cnt = 0;
                for (int[] dir : DIRECTIONS) {
                    int nr = r + dir[0];
                    int nc = c + dir[1];
                    if (inBounds(nr, nc) && grid[nr][nc] == '.') {
                        cnt++;
                    }
                }
                degree[r][c] = cnt;
                if (degree[r][c] == 1) {
                    queue.addLast(new int[]{r, c});
                }
            }
        }
    }

    /** --------------------------------------------------------------------- */
    /** Processes the queue of forced placements until it is empty or a contradiction is found. */
    private void processQueue() {
        while (!queue.isEmpty()) {
            int[] cell = queue.pollFirst();
            int r = cell[0];
            int c = cell[1];

            // The cell might have been processed already (e.g., via a neighbour).
            if (grid[r][c] != '.') {
                continue;
            }

            // Look for the only adjacent empty neighbour that is still free.
            int[] partner = findAndMarkPartner(r, c);
            if (partner == null) {
                writer.println("Not unique");
                return;
            }

            placeTile(r, c, partner);
            updateDegreesAround(partner);
        }
    }

    /** --------------------------------------------------------------------- */
    /** Finds a still‑empty neighbour of (r,c) and returns its coordinates.
     *  If no such neighbour exists the tiling cannot be forced → “Not unique”. */
    private int[] findAndMarkPartner(int r, int c) {
        int[] partner = null;
        for (int[] dir : DIRECTIONS) {
            int nr = r + dir[0];
            int nc = c + dir[1];
            if (inBounds(nr, nc) && grid[nr][nc] == '.') {
                // The first found neighbour is the only viable one (degree == 1 guarantees uniqueness of choice)
                partner = new int[]{nr, nc};
                break;
            }
        }
        // If no partner found, the current cell is isolated – situation is not tileable uniquely.
        return partner;
    }

    /** --------------------------------------------------------------------- */
    /** Places the domino covering (r,c) and its partner into the grid using the appropriate characters. */
    private void placeTile(int r1, int c1, int[] r2c2) {
        int r2 = r2c2[0];
        int c2 = r2c2[1];

        if (r1 == r2) {                     // horizontal
            int colMin = Math.min(c1, c2);
            int colMax = Math.max(c1, c2);
            grid[r1][colMin] = '<';
            grid[r1][colMax] = '>';
        } else {                            // vertical
            int rowMin = Math.min(r1, r2);
            int rowMax = Math.max(r1, r2);
            grid[rowMin][c1] = '^';
            grid[rowMax][c1] = 'v';
        }
    }

    /** --------------------------------------------------------------------- */
    /** Decrements the degree of all empty neighbours of (r,c) and enqueues any that become degree 1. */
    private void updateDegreesAround(int[] cell) {
        int r = cell[0];
        int c = cell[1];
        for (int[] dir : DIRECTIONS) {
            int nr = r + dir[0];
            int nc = c + dir[1];
            if (inBounds(nr, nc) && grid[nr][nc] == '.') {
                degree[nr][nc]--;
                if (degree[nr][nc] == 1) {
                    queue.addLast(new int[]{nr, nc});
                }
            }
        }
    }

    /** --------------------------------------------------------------------- */
    /** Returns true if there exists at least one empty ('.') cell left after processing. */
    private boolean anyEmptyCellRemains() {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '.') {
                    return true;
                }
            }
        }
        return false;
    }

    /** --------------------------------------------------------------------- */
    /** Writes the solved grid to the output writer. */
    private void printSolution() {
        for (int r = 0; r < rows; r++) {
            writer.println(new String(grid[r]));
        }
    }

    /** --------------------------------------------------------------------- */
    /** Simple helper that checks bounds. */
    private boolean inBounds(int r, int c) {
        return 0 <= r && r < rows && 0 <= c && c < cols;
    }

    /** --------------------------------------------------------------------- */
    /** Fast scanner used by the original code – kept unchanged but wrapped for clarity. */
    private class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner() {
            this.br = new BufferedReader(new InputStreamReader(System.in));
        }

        FastScanner(String filePath) throws IOException {
            this.br = new BufferedReader(new FileReader(filePath));
        }

        /** Returns the next token from the input. */
        String nextToken() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    throw new UncheckedIOException(e);
                }
            }
            return st.nextToken();
        }

        /** Convenience wrappers. */
        int nextInt() {
            return Integer.parseInt(nextToken());
        }

        long nextLong() {
            return Long.parseLong(nextToken());
        }

        double nextDouble() {
            return Double.parseDouble(nextToken());
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Solves the “Drazil Tiles” problem.
 * <p>
 * The algorithm works as follows:
 * <ul>
 *   <li>Read the board.</li>
 *   <li>For every empty cell ('.') count how many adjacent empty cells it has.</li>
 *   <li>If an empty cell has exactly one adjacent empty cell, it must be paired
 *       with that neighbour. The pair is placed on the board using the
 *       appropriate directional characters.</li>
 *   <li>After a pair is placed, the degrees of the neighbours of the newly
 *       placed tile are updated – cells that now have only one free neighbour
 *       are enqueued.</li>
 *   <li>If after exhausting the queue any empty cell remains, the tiling is
 *       not unique; otherwise the constructed board is printed.</li>
 * </ul>
 * The refactored version improves readability by:
 * <ul>
 *   <li>Extracting logical parts into small, well‑named methods.</li>
 *   <li>Using meaningful field names and avoiding magic numbers.</li>
 *   <li>Encapsulating a direction vector/execute‑pair logic in an {@code Enum}</li>
 *   <li>Removing static mutable globals and using instance fields instead.</li>
 *   <li>Applying Java‑8 style constructs where appropriate.</li>
 * </ul>
 */
public class TileSolver {

    /* -------------------------------------------------------------
     *  Constants – direction vectors and the characters that have to be
     *  written into the grid when two cells are paired.
     * ------------------------------------------------------------- */
    private static final int[] DX = {-1, 0, 0, 1};               // up, left, right, down
    private static final int[] DY = {0, -1, 1, 0};
    private static final char[] DIR_CHAR = {'U', 'L', 'R', 'D'};
    private static final char[] OPPOSITE_CHAR = {'D', 'R', 'L', 'U'};

    /* -------------------------------------------------------------
     *  Input / output streams.
     * ------------------------------------------------------------- */
    private final BufferedReader reader;
    private final PrintWriter writer;

    /* -------------------------------------------------------------
     *  Board representation.
     * ------------------------------------------------------------- */
    private char[][] grid;          // the original board (mutable)
    private int[][] degree;         // number of adjacent '.' cells for each position
    private Queue<Point> queue;     // cells that currently have degree == 1

    /* -------------------------------------------------------------
     *  Constructor – injects the streams.
     * ------------------------------------------------------------- */
    public TileSolver() throws IOException {
        this.reader = new BufferedReader(new InputStreamReader(System.in));
        this.writer = new PrintWriter(System.out);
    }

    /* -------------------------------------------------------------
     *  Entry point.
     * ------------------------------------------------------------- */
    public void solve() throws IOException {
        String[] header = parseHeader(reader.readLine());
        int rows = header[0];
        int cols = header[1];
        readBoard(rows, reader);

        initialiseDegreeAndQueue();
        processQueue();

        if (hasRemainingEmptyCells()) {
            writer.println("Not unique");
        } else {
            printSolution();
        }

        writer.close();
        reader.close();
    }

    /* -------------------------------------------------------------
     *  Helper methods
     * ------------------------------------------------------------- */

    private String[] parseHeader(String line) {
        StringTokenizer st = new StringTokenizer(line);
        String[] tokens = new String[st.countTokens()];
        int idx = 0;
        while (st.hasMoreTokens()) {
            tokens[idx++] = st.nextToken();
        }
        return tokens;
    }

    private void readBoard(int rows, BufferedReader br) throws IOException {
        grid = new char[rows][];
        for (int r = 0; r < rows; r++) {
            grid[r] = br.readLine().trim().toCharArray();
        }
    }

    private void initialiseDegreeAndQueue() {
        degree = new int[rows][cols];
        queue = new ArrayDeque<>();

        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '.') {
                    degree[r][c] = countAdjacentFree(r, c);
                    if (degree[r][c] == 1) {
                        queue.offer(new Point(r, c));
                    }
                }
            }
        }
    }

    private int countAdjacentFree(int r, int c) {
        int cnt = 0;
        for (int d = 0; d < 4; d++) {
            int nr = r + DX[d];
            int nc = c + DY[d];
            if (inside(nr, nc) && grid[nr][nc] == '.') {
                cnt++;
            }
        }
        return cnt;
    }

    private void processQueue() {
        while (!queue.isEmpty()) {
            Point cur = queue.poll();
            int r = cur.row, c = cur.col;

            if (grid[r][c] != '.') {
                continue;               // already paired
            }

            Point partner = findFreeNeighbour(r, c);
            if (partner == null) {
                continue;
            }

            pairCells(r, c, partner.row, partner.col);
            updateDegrees(partner);
        }
    }

    private Point findFreeNeighbour(int r, int c) {
        for (int d = 0; d < 4; d++) {
            int nr = r + DX[d];
            int nc = c + DY[d];
            if (inside(nr, nc) && grid[nr][nc] == '.') {
                return new Point(nr, nc);
            }
        }
        return null;
    }

    private void pairCells(int r1, int c1, int r2, int c2) {
        // Determine which direction connects the two cells.
        int dr = r2 - r1;
        int dc = c2 - c1;

        if (dr == -1 && dc == 0) {               // (r1,c1) -> up, (r2,c2) -> down
            grid[r1][c1] = 'v';
            grid[r2][c2] = '^';
        } else if (dr == 1 && dc == 0) {         // down
            grid[r1][c1] = '^';
            grid[r2][c2] = 'v';
        } else if (dr == 0 && dc == -1) {        // left
            grid[r1][c1] = '>';
            grid[r2][c2] = '<';
        } else if (dr == 0 && dc == 1) {         // right
            grid[r1][c1] = '<';
            grid[r2][c2] = '>';
        } else {
            throw new IllegalStateException("Invalid neighbour direction");
        }
    }

    private void updateDegrees(Point p) {
        int r = p.row;
        int c = p.col;

        // The cell has just been paired, but its neighbours may have lost an
        // adjacent free cell, so we decrease their degree.
        for (int d = 0; d < 4; d++) {
            int nr = r + DX[d];
            int nc = c + DY[d];
            if (inside(nr, nc) && grid[nr][nc] == '.') {
                degree[nr][nc]--;
                if (degree[nr][nc] == 1) {
                    queue.offer(new Point(nr, nc));
                }
            }
        }
    }

    private boolean inside(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    private boolean hasRemainingEmptyCells() {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '.') {
                    return true;
                }
            }
        }
        return false;
    }

    private void printSolution() {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                writer.print(grid[r][c]);
            }
            writer.println();
        }
    }

    /* -------------------------------------------------------------
     *  Simple container for a board coordinate.
     * ------------------------------------------------------------- */
    private static final class Point {
        final int row;
        final int col;
        Point(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }

    /* -------------------------------------------------------------
     *  Application entry point.
     * ------------------------------------------------------------- */
    public static void main(String[] args) throws IOException {
        new TileSolver().solve();
    }
}

/*
 *  Refactored version of the original program.
 *  - Input is parsed by a dedicated scanner class.
 *  - Grid handling is encapsulated in a small helper class.
 *  - Directions are represented by an enum for readability.
 *  - All magic values are named constants.
 *  - The algorithm (leaf‑removal / unique‑path filling) is split into
 *    small, reusable methods.
 *  - No raw types are used; immutable data classes replace primitive
 *    collections.
 *  - The `main` method only orchestrates the workflow.
 *
 *  Compile with:   javac Main.java
 *  Run     with:   java Main < input.txt
 */

import java.io.*;
import java.util.*;

public class Main {

    /* ---------- Constants & enums ------------------------------------------------ */

    /** Symbol that represents an empty cell in the input grid. */
    private static final char EMPTY = '.';

    /** Symbols used to indicate the direction of a pipe segment. */
    private enum Direction {
        UP('^'),
        DOWN('v'),
        LEFT('<'),
        RIGHT('>');

        final char symbol;
        final int dx;
        final int dy;

        Direction(char symbol) {
            this.symbol = symbol;
            // Offsets will be filled later (see DirectionRegistry)
        }
    }

    /** Registry that maps a Direction enum value to its movement offset. */
    private static final Map<Direction, Offset> OFFSET_REGISTRY = new EnumMap<>(Direction.class);
    private static final class Offset {
        final int x;
        final int y;
        Offset(int x, int y) { this.x = x; this.y = y; }
    }

    static {
        // Fill the registry once – it converts a Direction into its (dx,dy) vector.
        for (Direction d : Direction.values()) {
            switch (d) {
                case UP:     OFFSET_REGISTRY.put(d, new Offset(0, -1)); break;
                case DOWN:   OFFSET_REGISTRY.put(d, new Offset(0,  1)); break;
                case LEFT:   OFFSET_REGISTRY.put(d, new Offset(-1, 0)); break;
                case RIGHT:  OFFSET_REGISTRY.put(d, new Offset( 1, 0)); break;
            }
        }
    }

    /** Simple immutable point object used for coordinates. */
    private static final class Cell {
        final int col;   // x
        final int row;   // y

        Cell(int col, int row) {
            this.col = col;
            this.row = row;
        }
    }

    /* ---------- Core grid processing ------------------------------------------------ */

    /**
     * Represents the puzzle grid.  The grid is mutable because we
     * replace empty cells with direction symbols during the algorithm.
     */
    private static final class Grid {
        private final char[][] cells;
        private final int cols;
        private final int rows;

        Grid(char[][] source) {
            this.cols = source.length > 0 ? source[0].length : 0;
            this.rows = source.length;
            this.cells = new char[this.rows][this.cols];
            for (int r = 0; r < this.rows; r++) {
                System.arraycopy(source[r], 0, this.cells[r], 0, this.cols);
            }
        }

        /** Returns the character stored at (col,row). */
        char get(int col, int row) {
            return cells[row][col];
        }

        /** Replaces the character at (col,row) with the given value. */
        void set(int col, int row, char value) {
            cells[row][col] = value;
        }

        /** Checks whether any '.' remain in the whole grid. */
        boolean stillContainsEmpty() {
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (cells[r][c] == EMPTY) {
                        return true;
                    }
                }
            }
            return false;
        }

        /** Returns a string representation of the whole grid (rows concatenated). */
        String asString() {
            StringBuilder sb = new StringBuilder(rows * cols);
            for (int r = 0; r < rows; r++) {
                sb.append(cells[r]);
            }
            return sb.toString();
        }
    }

    /* ---------- Input scanning ------------------------------------------------------ */

    /**
     * Very small, fast scanner that reads from {@code System.in}.
     * It is deliberately kept private to the package – no need to expose it.
     */
    private static final class Scanner {
        private final InputStream in;
        private final byte[] buffer = new byte[16 * 1024];
        private int ptr = 0, len = 0;

        Scanner() { this.in = System.in; }

        /** Reads the next non‑whitespace token. */
        String nextToken() throws IOException {
            while (true) {
                if (ptr >= len) {
                    len = in.read(buffer);
                    ptr = 0;
                    if (len <= 0) return null;
                }
                int c = buffer[ptr++];
                while (c <= ' ') if (++ptr >= len) { len = in.read(buffer); ptr = 0; if (len <= 0) return null; c = buffer[ptr++]; }
                StringBuilder sb = new StringBuilder();
                while (c > ' ') {
                    sb.append((char) c);
                    if (++ptr >= len) {
                        len = in.read(buffer);
                        ptr = 0;
                        if (len <= 0) break;
                        c = buffer[ptr++];
                    } else {
                        c = buffer[ptr++];
                    }
                }
                return sb.toString();
            }
        }

        /** Convenience wrapper for the most common case (grid dimensions + rows). */
        static Grid readGrid() throws IOException {
            Scanner s = new Scanner();
            int cols = Integer.parseInt(s.nextToken());
            int rows = Integer.parseInt(s.nextToken());
            char[][] raw = new char[rows][];
            for (int r = 0; r < rows; r++) {
                raw[r] = s.nextToken().toCharArray();
            }
            return new Grid(raw);
        }
    }

    /* ---------- Core algorithm ------------------------------------------------------ */

    /**
     * The algorithm repeatedly picks a cell that still contains '.' and
     * has exactly one adjacent empty neighbour.  When such a leaf is found,
     * the direction from the neighbour to the leaf is fixed and written
     * into both cells.  The process continues until no empty cells remain.
     * If at any point a leaf cannot be found but empty cells are left,
     * the solution is not unique.
     *
     * @param grid mutable grid that holds the puzzle
     * @return {@code true} if the grid was completely filled, {@code false}
     *         if the solution cannot be guaranteed to be unique
     */
    private static boolean fillUniquePath(Grid grid) {
        int cols = grid.cells[0].length;
        int rows = grid.cells.length;

        // Queue of cells that still need to be examined.
        Deque<Cell> worklist = new ArrayDeque<>();

        // Populate the worklist with **all** cells – the algorithm will
        // process each cell until it either gets resolved or becomes empty.
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                worklist.addLast(new Cell(c, r));
            }
        }

        while (!worklist.isEmpty()) {
            Cell cur = worklist.pollFirst();
            int cx = cur.col;
            int cy = cur.row;

            char curChar = grid.get(cx, cy);
            if (curChar != EMPTY) {
                // Already resolved – nothing to do.
                continue;
            }

            // Count how many adjacent empty cells we have.
            List<Direction> emptyNeighbours = new ArrayList<>(4);
            for (Direction dir : Direction.values()) {
                Offset off = OFFSET_REGISTRY.get(dir);
                int nx = cx + off.x;
                int ny = cy + off.y;
                if (isInside(nx, ny, cols, rows) && grid.get(nx, ny) == EMPTY) {
                    emptyNeighbours.add(dir);
                }
            }

            if (emptyNeighbours.size() != 1) {
                // Not a leaf – postpone its consideration.
                worklist.addLast(cur);
                continue;
            }

            // Exactly one neighbour → we can deterministically assign a direction.
            Direction dir = emptyNeighbours.get(0);
            Offset off = OFFSET_REGISTRY.get(dir);
            int nx = cx + off.x;
            int ny = cy + off.y;

            // Fill both cells with opposing arrows.
            grid.set(cx, cy, dir.symbol);
            grid.set(nx, ny, oppositeSymbol(dir));

            // Continue processing from the newly created cell as well.
            worklist.addLast(new Cell(nx, ny));
        }

        // If any '.' remain, the solution is not unique.
        return !grid.stillContainsEmpty();
    }

    /** Returns the opposite direction symbol (e.g. '^' ↔ 'v'). */
    private static char oppositeSymbol(Direction dir) {
        return switch (dir) {
            case UP -> 'v';
            case DOWN -> '^';
            case LEFT -> '>';
            case RIGHT -> '<';
        };
    }

    /** Utility – checks that a coordinate lies inside the grid. */
    private static boolean isInside(int x, int y, int cols, int rows) {
        return x >= 0 && x < cols && y >= 0 && y < rows;
    }

    /* ---------- Program entry point ------------------------------------------------- */

    public static void main(String[] args) throws Exception {
        Grid grid = Scanner.readGrid();

        boolean unique = fillUniquePath(grid);

        if (!unique) {
            System.out.println("Not unique");
        } else {
            System.out.print(grid.asString());
        }
    }
}

import java.io.*;
import java.util.*;

public class Main implements Runnable {

    // -----------------------------------------------------------------------
    //  Configuration / constants
    // -----------------------------------------------------------------------
    private static final int[] DX = {-1, 0, 1, 0};
    private static final int[] DY = {0, -1, 0, 1};

    // -----------------------------------------------------------------------
    //  State variables
    // -----------------------------------------------------------------------
    private int rows, cols;                 // board dimensions
    private char[][] board;                 // the board itself
    private int[][] outDegree;              // number of adjacent empty cells
    private boolean[][] processed;          // visited flag to avoid double‑adding
    private BufferedReader reader;          // fast input
    private StringTokenizer tokenizer;      // tokeniser for input
    private PrintWriter writer;             // output

    // -----------------------------------------------------------------------
    //  Public entry point
    // -----------------------------------------------------------------------
    public static void main(String[] args) throws IOException {
        new Main().run();
    }

    // -----------------------------------------------------------------------
    //  IO helpers
    // -----------------------------------------------------------------------
    private String next() throws IOException {
        while (tokenizer == null || !tokenizer.hasMoreTokens()) {
            tokenizer = new StringTokenizer(reader.readLine());
        }
        return tokenizer.nextToken();
    }

    private int nextInt() throws IOException {
        return Integer.parseInt(next());
    }

    private void initIO() {
        try {
            reader = new BufferedReader(new InputStreamReader(System.in));
            writer = new PrintWriter(new OutputStreamWriter(System.out));
        } catch (IOException e) {
            System.exit(-1);
        }
    }

    // -----------------------------------------------------------------------
    //  Core solving logic
    // -----------------------------------------------------------------------
    @Override
    public void run() {
        try {
            initIO();
            solve();
            writer.flush();
        } catch (IOException e) {
            System.exit(-1);
        }
    }

    /** Reads the input, performs the tiling calculation and writes the output. */
    private void solve() throws IOException {
        readDimensionsAndBoard();
        initialiseAuxiliaryStructures();

        Queue<Integer> forcedQueue = collectForcedCells();
        processForcedMoves(forcedQueue);

        if (containsEmptyCell()) {
            reportNonUnique();
            return;
        }

        printSolution();
    }

    /** Reads rows, columns and the character board. */
    private void readDimensionsAndBoard() throws IOException {
        rows = nextInt();
        cols = nextInt();

        board = new char[rows][];
        for (int r = 0; r < rows; r++) {
            String line = next();
            board[r] = line.toCharArray();
        }
    }

    /** Allocates and initialises degree and processed matrices. */
    private void initialiseAuxiliaryStructures() {
        processed = new boolean[rows][cols];
        outDegree = new int[rows][cols];

        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (board[r][c] != '.') {
                    continue;
                }
                int cnt = 0;
                for (int d = 0; d < 4; d++) {
                    int nr = r + DX[d];
                    int nc = c + DY[d];
                    if (nr < 0 || nr >= rows || nc < 0 || nc >= cols) {
                        continue;
                    }
                    if (board[nr][nc] == '.') {
                        cnt++;
                    }
                }
                outDegree[r][c] = cnt;
            }
        }
    }

    /** Finds all cells that currently have exactly one free neighbour. */
    private Queue<Integer> collectForcedCells() {
        Queue<Integer> queue = new LinkedList<>();

        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (isEmpty(board[r][c]) && outDegree[r][c] == 1) {
                    queue.add(linearIndex(r, c));
                }
            }
        }
        return queue;
    }

    /** Main loop – resolves one forced move after another. */
    private void processForcedMoves(Queue<Integer> forcedQueue) {
        while (!forcedQueue.isEmpty()) {
            int idx = forcedQueue.poll();
            int r = idx / cols;
            int c = idx % cols;

            if (!isEmpty(board[r][c])) {
                continue; // already resolved
            }

            int[] partner = locateUniqueNeighbour(r, c);
            if (partner == null) {
                reportNonUnique();
                return;
            }

            fillPair(r, c, partner[0], partner[1]);

            // Update degrees of neighbours of the newly filled partner cell
            for (int d = 0; d < 4; d++) {
                int nr = partner[0] + DX[d];
                int nc = partner[1] + DY[d];
                if (!neighborExists(nr, nc)) {
                    continue;
                }
                if (isEmpty(board[nr][nc]) && !processed[nr][nc]) {
                    outDegree[nr][nc]--;
                    if (outDegree[nr][nc] == 1) {
                        queueAddIfNew(nr, nc, forcedQueue);
                        processed[nr][nc] = true;
                    }
                }
            }
        }
    }

    /** Returns coordinates of the sole empty neighbour, or {@code null}. */
    private int[] locateUniqueNeighbour(int r, int c) {
        for (int d = 0; d < 4; d++) {
            int nr = r + DX[d];
            int nc = c + DY[d];
            if (neighborExists(nr, nc) && isEmpty(board[nr][nc])) {
                return new int[]{nr, nc};
            }
        }
        return null;
    }

    /** Places the appropriate characters representing the domino tile. */
    private void fillPair(int r, int c, int nr, int nc) {
        if (r == nr) {                // horizontal domino
            board[r][c] = (c < nc) ? '<' : '>';
            board[nr][nc] = (c < nc) ? '>' : '<';
        } else {                      // vertical domino
            board[r][c] = (r < nr) ? '^' : 'v';
            board[nr][nc] = (r < nr) ? 'v' : '^';
        }
    }

    /** Adds a coordinate to the queue only if it is not already present. */
    private void queueAddIfNew(int r, int c, Queue<Integer> q) {
        int idx = linearIndex(r, c);
        // Simple containment test – duplicates are harmless, but we avoid them
        for (Integer existing : q) {
            if (existing == idx) {
                return;
            }
        }
        q.add(idx);
    }

    /** Checks whether a cell lies inside the grid. */
    private boolean neighborExists(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    /** Returns {@code true} if a character is still the placeholder '.'. */
    private boolean isEmpty(char ch) {
        return ch == '.';
    }

    /** Linear index conversion (row‑major). */
    private int linearIndex(int r, int c) {
        return r * cols + c;
    }

    /** Returns {@code true} if any empty cell ('.') remains on the board. */
    private boolean containsEmptyCell() {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (isEmpty(board[r][c])) {
                    return true;
                }
            }
        }
        return false;
    }

    /** Prints the error message when the tiling is not unique. */
    private void reportNonUnique() throws IOException {
        writer.println("Not unique");
    }

    /** Writes the solved board to standard output. */
    private void printSolution() {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                writer.print(board[r][c]);
            }
            writer.println();
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Main entry point of the solution.
 * Reads a grid, tries to assign a unique direction to every empty cell,
 * and prints the resulting tiling or "Not unique" if the solution is not unique.
 */
public class Main {

    /** Symbols used in the output */
    private static final char BLOCKED = '*';
    private static final char[] DIR_SYMBOLS = {'^', 'v', '<', '>'};

    /** Direction vectors – order must match DIR_SYMBOLS */
    private static final int[] DR = {-1, 1, 0, 0};
    private static final int[] DC = {0, 0, -1, 1};

    /** Enum that represents the four possible movement directions */
    private enum Direction {
        UP('^'), DOWN('v'), LEFT('<'), RIGHT('>');

        private final char symbol;
        Direction(char symbol) { this.symbol = symbol; }

        char symbol() { return symbol; }
    }

    /* -------------------------------------------------------------------------- */
    /*                         Fast input scanner (unchanged)                    */
    /* -------------------------------------------------------------------------- */
    private static final class FastScanner {
        private final InputStream stream;
        private final byte[] buffer = new byte[1024];
        private int curPos = 0, readLen = 0;

        FastScanner() { this.stream = System.in; }

        private int readByte() throws IOException {
            if (readLen == -1) throw new InputMismatchException();
            if (curPos >= readLen) {
                curPos = 0;
                readLen = stream.read(buffer);
                if (readLen <= 0) return -1;
            }
            return buffer[curPos++];
        }

        private boolean isSpace(int ch) { return ch == ' ' || ch == '\n' || ch == '\r' || ch == '\t'; }

        private int skipSpaces() throws IOException {
            int c;
            while ((c = readByte()) != -1 && isSpace(c)) { }
            return c;
        }

        String next() throws IOException {
            int c = skipSpaces();
            StringBuilder sb = new StringBuilder();
            do {
                sb.append((char) c);
                c = readByte();
            } while (!isSpace(c) && c != -1);
            return sb.toString();
        }

        int nextInt() throws IOException { return Integer.parseInt(next()); }
    }

    /* -------------------------------------------------------------------------- */
    /*                               Core solver class                           */
    /* -------------------------------------------------------------------------- */
    private static final class Solver {
        private final FastScanner in;
        private final PrintWriter out;

        /** Grid values:
         *  -1  → blocked ('*')
         *  -2  → empty (unprocessed)
         *   0‑3 → assigned direction (corresponds to Direction enum)               */
        private final int[][] grid;
        private final int rows, cols;

        /** Queue used for the leaf‑pruning algorithm */
        private final Deque<Integer> leafQueue = new ArrayDeque<>();

        /** Mapping from node id (r*C + c) to its coordinates */
        private final int[] nodeRow;
        private final int[] nodeCol;

        /** Adjacency representation – each node can have up to 4 neighbours */
        private final int[][] adj;

        Solver(FastScanner in, PrintWriter out) {
            this.in = in;
            this.out = out;
            this.rows = in.nextInt();
            this.cols = in.nextInt();

            this.grid = new int[rows][cols];
            for (int r = 0; r < rows; ++r) {
                String line = in.next();
                for (int c = 0; c < cols; ++c) {
                    grid[r][c] = line.charAt(c) == '*' ? -1 : -2;
                }
            }

            int nodeCount = rows * cols;
            this.nodeRow = new int[nodeCount];
            this.nodeCol = new int[nodeCount];
            this.adj = new int[nodeCount][4];
            Arrays.fill(adj, -1);
        }

        /** Convert board coordinates to a node identifier */
        private int nodeId(int r, int c) {
            return r * cols + c;
        }

        /** Return the direction index that corresponds to (dr, dc) */
        private static int directionIndex(int dr, int dc) {
            for (int d = 0; d < 4; ++d) {
                if (DR[d] == dr && DC[d] == dc) return d;
            }
            throw new IllegalArgumentException("Invalid direction delta");
        }

        /** Add a directed edge a → b into the adjacency lists */
        private void addEdge(int a, int b) {
            for (int i = 0; i < 4; ++i) {
                if (adj[a][i] == -1) {
                    adj[a][i] = b;
                    return;
                }
            }
        }

        /** Main algorithm – builds the graph and propagates leaf‑pruning */
        void solve() {
            /* --------------------------------------------------------------
             * 1) Build adjacency list for all *empty* cells.
             * -------------------------------------------------------------- */
            int emptyCount = 0;
            for (int r = 0; r < rows; ++r) {
                for (int c = 0; c < cols; ++c) {
                    if (grid[r][c] != -2) continue;               // only empty cells
                    int id = nodeId(r, c);
                    nodeRow[id] = r;
                    nodeCol[id] = c;
                    emptyCount++;

                    // explore the four neighbours
                    for (int d = 0; d < 4; ++d) {
                        int nr = r + DR[d];
                        int nc = c + DC[d];
                        if (nr < 0 || nr >= rows || nc < 0 || nc >= cols) continue;
                        if (grid[nr][nc] != -2) continue;         // not empty
                        int nid = nodeId(nr, nc);
                        addEdge(id, nid);
                    }
                }
            }

            /* --------------------------------------------------------------
             * 2) Initialise leaf queue (nodes with exactly one neighbour).
             * -------------------------------------------------------------- */
            for (int i = 0; i < rows * cols; ++i) {
                int deg = 0;
                for (int nb : adj[i]) if (nb != -1) deg++;
                if (deg == 1) leafQueue.addLast(i);
            }

            /* --------------------------------------------------------------
             * 3) Process leaves iteratively.
             * -------------------------------------------------------------- */
            while (!leafQueue.isEmpty()) {
                int id = leafQueue.removeFirst();
                if (deg(id) != 1) continue;                     // may have been processed already

                int nxt = neighbour(id);
                if (nxt == -1) continue;                        // safety guard

                // Resolve the direction between the two cells
                int r1 = nodeRow[id], c1 = nodeCol[id];
                int r2 = nodeRow[nxt], c2 = nodeCol[nxt];
                int dirFrom2To1 = directionIndex(r1 - r2, c1 - c2);
                int dirFrom1To2 = directionIndex(r2 - r1, c2 - c1);

                grid[r1][c1] = dirFrom2To1;   // assign direction to leaf
                grid[r2][c2] = dirFrom1To2;   // assign opposite direction

                // Remove the processed edge from both sides
                detachEdge(id, nxt);
                detachEdge(nxt, id);

                // Update degree of the neighbour – it may become a new leaf
                int degAfter = deg(nxt);
                if (degAfter == 1) leafQueue.addLast(nxt);
            }

            /* --------------------------------------------------------------
             * 4) Verify that every empty cell received a direction.
             * -------------------------------------------------------------- */
            for (int r = 0; r < rows; ++r) {
                for (int c = 0; c < cols; ++c) {
                    if (grid[r][c] == -2) {
                        out.println("Not unique");
                        return;
                    }
                }
            }

            /* --------------------------------------------------------------
             * 5) Output the resulting tiling.
             * -------------------------------------------------------------- */
            for (int r = 0; r < rows; ++r) {
                for (int c = 0; c < cols; ++c) {
                    if (grid[r][c] == -1) {
                        out.print(BLOCKED);
                    } else {
                        out.print(Direction.values()[grid[r][c]].symbol());
                    }
                }
                out.println();
            }
        }

        /** Helper – return the degree (non‑negative entries) of a node */
        private int deg(int id) {
            int d = 0;
            for (int v : adj[id]) if (v != -1) d++;
            return d;
        }

        /** Helper – return the neighbour stored in the first non‑‑1 slot */
        private int neighbour(int id) {
            for (int v : adj[id]) if (v != -1) return v;
            return -1;
        }

        /** Helper – remove the edge id ↔ to */
        private void detachEdge(int id, int to) {
            for (int i = 0; i < 4; ++i) {
                if (adj[id][i] == to) {
                    adj[id][i] = -1;
                    return;
                }
            }
        }
    }

    /* -------------------------------------------------------------------------- */
    /*                               Program entry point                           */
    /* -------------------------------------------------------------------------- */
    public static void main(String[] args) throws Exception {
        try (PrintWriter out = new PrintWriter(System.out);
             FastScanner scanner = new FastScanner()) {
            new Solver(scanner, out).solve();
        }
    }
}

import java.io.*;
import java.util.*;

public class Dreamoon {

    /* Constants */
    private static final char EMPTY = '.';
    private static final char OBSTACLE = '*';
    private static final String IMPOSSIBLE = "Not unique";

    /* Direction handling ----------------------------------------------------- */
    private enum Direction {
        UP(-1, 0),
        LEFT(0, -1),
        RIGHT(0, 1),
        DOWN(1, 0);

        final int dx, dy;

        Direction(int dx, int dy) {
            this.dx = dx;
            this.dy = dy;
        }

        Direction opposite() {
            switch (this) {
                case UP:    return DOWN;
                case DOWN:  return UP;
                case LEFT:  return RIGHT;
                case RIGHT: return LEFT;
                default:    throw new IllegalStateException();
            }
        }
    }

    private static final Direction[] DIRS = Direction.values();

    /* I/O ------------------------------------------------------------------------- */
    private static BufferedReader br;
    private static PrintWriter out;
    private static StringTokenizer st;

    private static String next() {
        while (st == null || !st.hasMoreTokens()) {
            try {
                st = new StringTokenizer(br.readLine());
            } catch (IOException e) {
                return null;
            }
        }
        return st.nextToken();
    }

    private static int nextInt() {
        return Integer.parseInt(next());
    }

    /* Core logic ------------------------------------------------------------------- */
    private static void solve() {
        int n = nextInt();
        int m = nextInt();
        char[][] grid = new char[n][];
        for (int i = 0; i < n; i++) {
            grid[i] = next().toCharArray();
        }

        // indegree[i][j] = number of adjacent empty cells ('.')
        int[][] indegree = new int[n][m];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i][j] == EMPTY) {
                    for (Direction d : DIRS) {
                        int ni = i + d.dx;
                        int nj = j + d.dy;
                        if (inBounds(ni, nj, n, m) && grid[ni][nj] == EMPTY) {
                            indegree[i][j]++;
                        }
                    }
                }
            }
        }

        Queue<Cell> queue = new ArrayDeque<>();
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i][j] == EMPTY && indegree[i][j] == 1) {
                    queue.add(new Cell(i, j));
                }
            }
        }

        // result board – start with a copy of the input
        char[][] result = new char[n][];
        for (int i = 0; i < n; i++) {
            result[i] = grid[i].clone();
        }

        while (!queue.isEmpty()) {
            Cell cur = queue.poll();
            int x = cur.x, y = cur.y;

            // If this cell has already been paired, skip it.
            if (result[x][y] != EMPTY) {
                continue;
            }

            // Find the sole adjacent empty neighbour.
            Direction dirToNeighbour = null;
            for (Direction d : DIRS) {
                int nx = x + d.dx, ny = y + d.dy;
                if (inBounds(nx, ny, n, m) && result[nx][ny] == EMPTY) {
                    dirToNeighbour = d;
                    break;
                }
            }
            if (dirToNeighbour == null) {
                // Degenerated case – board cannot be tiled uniquely.
                out.println(IMPOSSIBLE);
                return;
            }

            int nx = x + dirToNeighbour.dx;
            int ny = y + dirToNeighbour.dy;
            Direction opposite = dirToNeighbour.opposite();

            // Choose ordering for output characters (arbitrary but deterministic).
            Cell first = (x < nx || (x == nx && y < ny)) ? cur : new Cell(nx, ny);
            Cell second = (first.x == x) ? cur : new Cell(nx, ny);

            // Place the appropriate tile markers.
            if (dirToNeighbour == Direction.UP || dirToNeighbour == Direction.DOWN) {
                result[first.x][first.y] = dirToNeighbour == Direction.UP ? '^' : 'v';
                result[second.x][second.y] = dirToNeighbour == Direction.UP ? 'v' : '^';
            } else {
                result[first.x][first.y] = '<';
                result[second.x][second.y] = '>';
            }

            // Update indegrees of neighbours and enqueue newly created degree‑1 cells.
            decrementAndTrack(indegree, result, nx, ny, queue);
            decrementAndTrack(indegree, result, x, y, queue);
        }

        // If any empty cell survived, tiling is not unique / impossible.
        if (hasRemainingEmpty(result)) {
            out.println(IMPOSSIBLE);
            return;
        }

        // Output final board.
        for (char[] row : result) {
            out.print(row);
            out.println();
        }
    }

    /* Helper methods ----------------------------------------------------------------- */
    private static boolean inBounds(int x, int y, int rows, int cols) {
        return x >= 0 && x < rows && y >= 0 && y < cols;
    }

    /** Decrements indegree of a neighbour and possibly enqueues it. */
    private static void decrementAndTrack(
            int[][] indegree,
            char[][] board,
            int x,
            int y,
            Queue<Cell> queue) {

        if (!inBounds(x, y, board.length, board[0].length) || board[x][y] != EMPTY) {
            return;
        }
        indegree[x][y]--;
        if (indegree[x][y] == 1) {
            queue.add(new Cell(x, y));
        } else if (indegree[x][y] == 0 && board[x][y] == EMPTY) {
            // No valid continuation – impossible tiling.
            out.println(IMPOSSIBLE);
            System.exit(0);
        }
    }

    private static boolean hasRemainingEmpty(char[][] board) {
        for (char[] row : board) {
            for (char c : row) {
                if (c == EMPTY) {
                    return true;
                }
            }
        }
        return false;
    }

    /** Simple coordinate holder. */
    private static final class Cell {
        final int x, y;
        Cell(int x, int y) {
            this.x = x;
            this.y = y;
        }
    }

    /* Application entry point --------------------------------------------------- */
    private static void run() {
        br = new BufferedReader(new InputStreamReader(System.in));
        out = new PrintWriter(System.out);
        try {
            solve();
        } finally {
            out.close();
        }
    }

    public static void main(String[] args) {
        run();
    }
}

/**
 * Refactored solution for the “Domino piling” / tiling problem.
 *
 * <p>The program reads a rectangular board (board symbols: '.' or '*'), builds a graph
 * of connectable empty cells, finds a maximal matching of adjacent cells and finally
 * prints the tiling pattern. If some cells cannot be uniquely matched the output is
 * the literal string {@code Not unique}.
 *
 * <p>The refactor improves readability, naming, and structure while preserving the
 * original algorithmic behaviour.
 */
public class Main {

    /** entry point */
    public static void main(String[] args) {
        InputReader in = new InputReader(System.in);
        OutputWriter out = new OutputWriter(System.out);
        new GridSolver().solve(in, out);
        out.close();
    }
}

/**
 * Handles all logic related to reading the board, computing the matching and printing
 * the result. The class name was changed from {@code TaskB} to {@code GridSolver}
 * to better express its responsibility.
 */
final class GridSolver {

    /** Directions used for neighbour lookup (up, down, left, right). */
    private static final int[][] DIRS = {
            {-1, 0}, {1, 0}, {0, -1}, {0, 1}
    };

    /** Private constructor – the class is utility‑only. */
    private GridSolver() {}

    /**
     * Solves one test case.
     *
     * @param in  input reader
     * @param out output writer
     */
    void solve(InputReader in, OutputWriter out) {
        int rows = in.readInt();
        int cols = in.readInt();

        // read the whole board
        char[][] board = new char[rows][];
        for (int r = 0; r < rows; r++) {
            board[r] = in.next().toCharArray();
        }

        solveBoard(rows, cols, board, out);
    }

    /**
     * Core algorithm – builds a degree table, finds a forced matching via BFS and
     * converts the matching into the required visual representation.
     *
     * @param rows   number of rows
     * @param cols   number of columns
     * @param board the board matrix (will be mutated)
     * @param out    output writer used for reporting
     */
    private void solveBoard(int rows, int cols, char[][] board, OutputWriter out) {
        final int totalCells = rows * cols;

        // degree[v] = number of adjacent '.' cells of vertex v
        int[] degree = new int[totalCells];
        boolean[] visited = new boolean[totalCells];
        int[] match = new int[totalCells];
        Arrays.fill(match, -1);

        preprocessDegrees(board, rows, cols, degree);

        Queue<Integer> queue = new LinkedList<>();
        enqueueDegreeOneVertices(degree, visited, queue);

        while (!queue.isEmpty()) {
            int cur = queue.poll();
            applyMatching(cur, match, visited, queue, board, rows, cols, degree);
        }

        // convert matching to visual symbols
        translateMatching(board, match, rows, cols);

        // any leftover '.' means the tiling is ambiguous / not unique
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (board[r][c] == '.') {
                    out.printLine("Not unique");
                    return;
                }
            }
        }

        // finally print the tiled board
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                out.print(board[r][c] + (c == cols - 1 ? "\n" : ""));
            }
        }
    }

    /** Calculates the degree of every empty cell based on its free neighbours. */
    private void preprocessDegrees(char[][] board, int rows, int cols, int[] degree) {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (board[r][c] == '*') {
                    continue;
                }
                int count = 0;
                for (int[] d : DIRS) {
                    int nr = r + d[0];
                    int nc = c + d[1];
                    if (isInside(nr, nc, rows, cols) && board[nr][nc] == '.') {
                        count++;
                    }
                }
                degree[r * cols + c] = count;
            }
        }
    }

    /** Enqueues all cells whose degree is 1 (or 0) – they are forced to be matched. */
    private void enqueueDegreeOneVertices(int[] degree,
                                            boolean[] visited,
                                            Queue<Integer> queue) {
        for (int i = 0; i < degree.length; i++) {
            if (degree[i] <= 1) {
                visited[i] = true;
                queue.add(i);
            }
        }
    }

    /**
     * Attempts to match the current cell with a still‑unmatched neighbour.
     * After a successful match the degree of the neighbour is decreased,
     * possibly causing new vertices to be enqueued.
     */
    private void applyMatching(int cur,
                               int[] match,
                               boolean[] visited,
                               Queue<Integer> queue,
                               char[][] board,
                               int rows,
                               int cols,
                               int[] degree) {
        int curR = cur / cols;
        int curC = cur % cols;

        for (int[] d : DIRS) {
            int nr = curR + d[0];
            int nc = curC + d[1];
            if (!isInside(nr, nc, rows, cols) || board[nr][nc] == '*') {
                continue;
            }

            int nb = nr * cols + nc;
            if (match[nb] != -1 || match[cur] != -1) {
                continue;
            }

            // perform the matching edge
            match[nb] = cur;
            match[cur] = nb;

            // if neighbour was not already enqueued, reconsider it
            if (!visited[nb]) {
                visited[nb] = true;
                queue.add(nb);
            }

            // neighbour’s degree drops, possibly making it a new candidate
            degree[nb]--;
            if (degree[nb] <= 1 && !visited[nb]) {
                visited[nb] = true;
                queue.add(nb);
            }
        }
    }

    /** Turns the numeric matching into the required characters ('<','>','^','v'). */
    private void translateMatching(char[][] board,
                                   int[] match,
                                   int rows,
                                   int cols) {
        for (int idx = 0; idx < match.length; idx++) {
            int partner = match[idx];
            if (partner == -1) {
                continue; // unmatched cells stay '.' and will trigger "Not unique"
            }
            int r1 = idx / cols, c1 = idx % cols;
            int r2 = partner / cols, c2 = partner % cols;

            if (r1 == r2) { // horizontal pair
                int min = Math.min(c1, c2);
                int max = Math.max(c1, c2);
                board[r1][min] = '<';
                board[r1][max] = '>';
            } else { // vertical pair (always r1 < r2 after swap)
                int min = Math.min(r1, r2);
                int max = Math.max(r1, r2);
                board[min][c1] = '^';
                board[max][c2] = 'v';
            }
        }
    }

    /** Simple helper to check array bounds. */
    private boolean isInside(int r, int c, int rows, int cols) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }
}

/* -------------------------------------------------------------------------- */
/*  The following two classes are unchanged copies of the original I/O helpers. */
/* -------------------------------------------------------------------------- */

class InputReader {
    private final InputStream stream;
    private final byte[] buffer = new byte[1024];
    private int bytesRead, currentByte;
    private final InputReader.SpaceCharFilter filter;

    InputReader(InputStream stream) {
        this.stream = stream;
    }

    private int readByte() {
        if (currentByte >= bytesRead) {
            currentByte = 0;
            bytesRead = stream.read(buffer);
            if (bytesRead <= 0) {
                return -1;
            }
        }
        return buffer[currentByte++];
    }

    /** Reads the next non‑whitespace character. */
    private int nextNonWhitespace() {
        int c;
        do {
            c = readByte();
        } while (isSpaceChar(c));
        return c;
    }

    int readInt() {
        int c = nextNonWhitespace();
        int sign = 1;
        if (c == '-') {
            sign = -1;
            c = readByte();
        }
        int result = 0;
        while (!isSpaceChar(c)) {
            if (c < '0' || c > '9') {
                throw new InputMismatchException();
            }
            result = result * 10 + (c - '0');
            c = readByte();
        }
        return result * sign;
    }

    String readString() {
        StringBuilder sb = new StringBuilder();
        int c = nextNonWhitespace();
        do {
            sb.append((char) c);
            c = readByte();
        } while (!isSpaceChar(c));
        return sb.toString();
    }

    boolean isSpaceChar(int c) {
        if (filter != null) {
            return filter.isSpaceChar(c);
        }
        return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
    }

    interface SpaceCharFilter {
        boolean isSpaceChar(int ch);
    }
}

class OutputWriter {
    private final PrintWriter writer;

    OutputWriter(OutputStream stream) {
        writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(stream)));
    }

    public void print(Object... objects) {
        for (int i = 0; i < objects.length; i++) {
            if (i != 0) {
                writer.print(' ');
            }
            writer.print(objects[i]);
        }
    }

    public void printLine(Object... objects) {
        print(objects);
        writer.println();
    }

    public void close() {
        writer.close();
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.ArrayDeque;
import java.util.Deque;
import java.util.StringTokenizer;

/**
 * Solver for a maze‑tiling problem.
 *
 * Reads a grid where
 *   '.' – empty cell,
 *   other characters are fixed arrows,
 * and tries to uniquely determine the direction of every empty cell.
 * If the tiling is unique it prints the solved board,
 * otherwise it prints "Not unique".
 *
 * The implementation has been refactored for clarity, testability
 * and future extensibility.
 */
public class MazeSolver {

    /** directions used for neighbour checks */
    private enum Direction {
        RIGHT(0, 1, '<', '>'),
        LEFT (0, -1, '>', '<'),
        DOWN (1, 0, '^', 'v'),
        UP   (-1, 0, 'v', '^');

        final int dr;
        final int dc;
        final char outChar;   // character that must be placed in the current cell
        final char neighbourChar; // character that must be placed in the neighbour

        Direction(int dr, int dc, char outChar, char neighbourChar) {
            this.dr = dr;
            this.dc = dc;
            this.outChar = outChar;
            this.neighbourChar = neighbourChar;
        }

        /** return the opposite direction */
        Direction opposite() {
            return switch (this) {
                case RIGHT -> LEFT;
                case LEFT  -> RIGHT;
                case UP    -> DOWN;
                case DOWN  -> UP;
            };
        }

        static Direction fromTo(int dr, int dc) {
            for (Direction d : values()) {
                if (d.dr == dr && d.dc == dc) {
                    return d;
                }
            }
            throw new IllegalStateException("No such direction: (" + dr + ", " + dc + ")");
        }
    }

    /** simple container for a cell coordinate */
    private static final class Cell {
        final int row;
        final int col;

        Cell(int row, int col) {
            this.row = row;
            this.col = col;
        }

        int row() { return row; }
        int col() { return col; }

        @Override
        public String toString() {
            return row + " " + col;
        }
    }

    /** fast scanner used by the program */
    private static final class FastScanner {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        FastScanner() {
            reader = new BufferedReader(new InputStreamReader(System.in), 32768);
        }

        /** read next token */
        private String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        /** read the whole next line (including empty lines) */
        String nextLine() {
            try {
                return reader.readLine();
            } catch (IOException e) {
                throw new RuntimeException(e);
            }
        }
    }

    /** number of neighbours that are still free – used for the reduction step */
    private static int countFreeNeighbours(char[][] grid, int r, int c) {
        int cnt = 0;
        for (Direction d : Direction.values()) {
            int nr = r + d.dr;
            int nc = c + d.dc;
            if (inside(grid, nr, nc) && grid[nr][nc] == '.') {
                cnt++;
            }
        }
        return cnt;
    }

    /** true if (r,c) is inside the board */
    private static boolean inside(char[][] grid, int r, int c) {
        return r >= 0 && r < grid.length && c >= 0 && c < grid[0].length;
    }

    /** core algorithm – attempts to deduce a unique tiling */
    private static void solve(char[][] grid) {
        final int rows = grid.length;
        final int cols = grid[0].length;

        // degree[i][j] = how many adjacent '.' cells an empty cell has
        int[][] degree = new int[rows][cols];
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '.') {
                    degree[r][c] = countFreeNeighbours(grid, r, c);
                }
            }
        }

        Deque<Cell> queue = new ArrayDeque<>();
        // start with cells that have exactly one free neighbour – they are forced
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '.' && degree[r][c] == 1) {
                    queue.addLast(new Cell(r, c));
                }
            }
        }

        while (!queue.isEmpty()) {
            Cell cur = queue.removeFirst();
            int r = cur.row();
            int c = cur.col();

            if (grid[r][c] != '.') {          // already resolved
                continue;
            }

            // find the only free neighbour
            Cell neighbour = null;
            Direction dir = null;
            for (Direction d : Direction.values()) {
                int nr = r + d.dr;
                int nc = c + d.dc;
                if (inside(grid, nr, nc) && grid[nr][nc] == '.') {
                    // this is the unique neighbour
                    neighbour = new Cell(nr, nc);
                    dir = d;
                    break;
                }
            }

            if (neighbour == null) {
                // This should never happen because we only push cells with degree==1
                continue;
            }

            // assign the forced direction to both cells
            grid[r][c] = dir.outChar();
            grid[neighbour.row()][neighbour.col()] = dir.neighbourChar();

            // decrease degree of adjacent free cells
            for (Direction d : Direction.values()) {
                int ar = neighbour.row() + d.dr;
                int ac = neighbour.col() + d.dc;
                if (inside(grid, ar, ac) && grid[ar][ac] == '.') {
                    degree[ar][ac]--;
                    if (degree[ar][ac] == 1) {
                        queue.addLast(new Cell(ar, ac));
                    }
                }
            }
        }
    }

    /** check whether any '.' cells remain – if so the solution is not unique */
    private static boolean hasRemainingEmptyCells(char[][] grid) {
        for (char[] row : grid) {
            for (char cell : row) {
                if (cell == '.') {
                    return true;
                }
            }
        }
        return false;
    }

    /** --------------------------------------------------------------- */
    /** entry point */
    public static void main(String[] args) {
        FastScanner fs = new FastScanner();

        int n = fs.nextInt();          // number of rows
        int m = fs.nextInt();          // number of columns
        char[][] board = new char[n][m];

        for (int i = 0; i < n; i++) {
            String line = fs.next();
            board[i] = line.toCharArray();
        }

        solve(board);

        if (hasRemainingEmptyCells(board)) {
            System.out.println("Not unique");
        } else {
            StringBuilder out = new StringBuilder();
            for (char[] row : board) {
                out.append(row);
                out.append('\n');
            }
            System.out.print(out.toString());
        }
    }
}

package domino;

import java.io.*;
import java.util.*;

/**
 * Solution for the “Drazil and Tiles” problem.
 *
 * <p>
 * The code is split into small, well‑named methods that each perform a single
 * responsibility:
 *
 * <ul>
 *   <li>Reading the input grid.</li>
 *   <li>Computing the degree of freedom of every empty cell.</li>
 *   <li>Performing the greedy placement of dominoes.</li>
 *   <li>Checking whether the final tiling is unique.</li>
 * </ul>
 *
 * <p>All magic numbers are replaced by constants, variable names are expressive,
 * and the main routine stays concise.</p>
 */
public final class DrazilAndTiles {

    /** Directions: up, left, down, right */
    private static final int[] DR = {-1, 0, 1, 0};
    /** Directions: up, left, down, right */
    private static final int[] DC = {0, -1, 0, 1};

    /** Private constructor – utility class. */
    private DrazilAndTiles() {}

    /** Entry point. */
    public static void main(String[] args) throws IOException {
        MyScanner scanner = new MyScanner();

        int n = scanner.nextInt();               // rows
        int m = scanner.nextInt();               // columns
        char[][] grid = readGrid(scanner, n, m); // input grid
        int[][] degrees = computeDegrees(grid, n, m);

        // Perform the greedy placement
        solve(grid, degrees, n, m);

        // Verify that every cell has been filled – otherwise the tiling is not unique
        if (isComplete(grid, n, m)) {
            printResult(grid);
        } else {
            System.out.println("Not unique");
        }
    }

    /* --------------------------------------------------------------------- */
    /*                         Helper / core methods                         */
    /* --------------------------------------------------------------------- */

    /** Reads the next {@code n} lines of length {@code m} from the scanner. */
    private static char[][] readGrid(MyScanner sc, int n, int m) {
        char[][] grid = new char[n][m];
        for (int r = 0; r < n; r++) {
            String line = sc.next(); // already trimmed of surrounding whitespace
            for (int c = 0; c < m; c++) {
                grid[r][c] = line.charAt(c);
            }
        }
        return grid;
    }

    /** Calculates for every empty cell the number of neighbouring empty cells. */
    private static int[][] computeDegrees(char[][] grid, int n, int m) {
        int[][] degrees = new int[n][m];
        for (int r = 0; r < n; r++) {
            for (int c = 0; c < m; c++) {
                if (grid[r][c] != '.') {
                    continue;
                }
                int count = 0;
                for (int d = 0; d < 4; d++) {
                    int nr = r + DR[d];
                    int nc = c + DC[d];
                    if (inBounds(nr, nc, n, m) && grid[nr][nc] == '.') {
                        count++;
                    }
                }
                degrees[r][c] = count;
            }
        }
        return degrees;
    }

    /** Places dominoes greedily using a queue (degree‑1 cells). Returns the final grid. */
    private static void solve(char[][] grid, int[][] degrees, int n, int m) {
        Queue<Integer> queue = new ArrayDeque<>();

        // Seed the queue with all degree‑1 empty cells
        for (int r = 0; r < n; r++) {
            for (int c = 0; c < m; c++) {
                if (grid[r][c] == '.' && degrees[r][c] == 1) {
                    queue.add(encode(r, m, c));
                }
            }
        }

        while (!queue.isEmpty()) {
            int encoded = queue.poll();
            int r = encoded / m;
            int c = encoded % m;

            placeDomino(grid, degrees, r, c, n, m);

            // After placing a domino, its neighbours may become degree‑1 → add them to the queue
            for (int d = 0; d < 4; d++) {
                int nr = r + DR[d];
                int nc = c + DC[d];
                if (inBounds(nr, nc, n, m) && grid[nr][nc] == '.') {
                    degrees[nr][nc]--;
                    if (degrees[nr][nc] == 1) {
                        queue.add(encode(nr, m, nc));
                    }
                }
            }
        }
    }

    /** Places the unique domino that involves the cell (r,c) and updates degrees. */
    private static void placeDomino(char[][] grid, int[][] degrees, int r, int c,
                                    int n, int m) {
        // Find the only free neighbour – the cell to which we attach the domino
        int nr = -1, nc = -1;
        for (int d = 0; d < 4; d++) {
            int nr2 = r + DR[d];
            int nc2 = c + DC[d];
            if (inBounds(nr2, nc2, n, m) && grid[nr2][nc2] == '.') {
                nr = nr2;
                nc = nc2;
                break;
            }
        }

        // If there is no free neighbour (should not happen for a valid instance) we stop
        if (nr == -1) {
            return;
        }

        // Mark the two cells with the appropriate tile characters
        if (r == nr) { // horizontal placement
            int minC = Math.min(c, nc);
            int maxC = Math.max(c, nc);
            grid[r][minC] = '<';
            grid[r][maxC] = '>';
        } else { // vertical placement
            int minR = Math.min(r, nr);
            int maxR = Math.max(r, nr);
            grid[minR][c] = '^';
            grid[maxR][c] = 'v';
        }

        // Update degrees of all neighbours of the newly placed tile
        for (int d = 0; d < 4; d++) {
            int nr2 = nr + DR[d];
            int nc2 = nc + DC[d];
            if (inBounds(nr2, nc2, n, m) && grid[nr2][nc2] == '.') {
                degrees[nr2][nc2]--;
                if (degrees[nr2][nc2] == 1) {
                    queue.add(encode(nr2, m, nc2));
                }
            }
        }
    }

    /** Checks whether every cell has been filled (i.e. the tiling is unique). */
    private static boolean isComplete(char[][] grid, int n, int m) {
        for (char[] row : grid) {
            for (char cell : row) {
                if (cell == '.') {
                    return false;
                }
            }
        }
        return true;
    }

    /** Prints the final tiled grid to stdout. */
    private static void printResult(char[][] grid) {
        StringBuilder sb = new StringBuilder();
        for (char[] row : grid) {
            sb.append(row).append('\n');
        }
        System.out.print(sb.toString().trim());
    }

    /** Returns {@code true} if (r,c) lies inside the {@code n × m} board. */
    private static boolean inBounds(int r, int c, int n, int m) {
        return r >= 0 && r < n && c >= 0 && c < m;
    }

    /** Encodes a board coordinate into a single integer (row‑major order). */
    private static int encode(int row, int cols, int col) {
        return row * cols + col;
    }

    /* --------------------------------------------------------------------- */
    /*                         Simple scanner class                          */
    /* --------------------------------------------------------------------- */

    /** Minimal scanner that skips blank lines and tokens. */
    private static final class MyScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        MyScanner() {
            this.br = new BufferedReader(new InputStreamReader(System.in));
        }

        /** Returns the next non‑empty token. */
        String next() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                String line = br.readLine();
                while (line != null && line.isBlank()) {
                    line = br.readLine();
                }
                if (line == null) {
                    return null;
                }
                st = new StringTokenizer(line);
            }
            return st.nextToken();
        }

        /** Convenience wrapper for {@code Integer}. */
        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Main class that solves the “unique tiling” puzzle.
 * It reads a grid of '.' and other symbols, tries to assign a direction
 * (^, >, v, <) to every '.' such that a unique tiling exists.
 * If any '.' remains unfilled the answer is “Not unique”.
 */
public class Solution {

    /* --------------------------------------------------------------------- */
    /*                           CONSTANTS & ENUMS                           */
    /* --------------------------------------------------------------------- */

    /** Four possible movement directions (up, right, down, left). */
    private enum Direction {
        UP( -1, 0, '^' ),
        RIGHT( 0, 1, '>' ),
        DOWN( 1, 0, 'v' ),
        LEFT( 0, -1, '<' );

        final int dr;
        final int dc;
        final char symbol;

        Direction(int dr, int dc, char symbol) {
            this.dr = dr;
            this.dc = dc;
            this.symbol = symbol;
        }
    }

    /** Utility holder for a cell coordinate. */
    private static final class Cell {
        final int row;
        final int col;

        Cell(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }

    /* --------------------------------------------------------------------- */
    /*                               INPUT / OUTPUT                         */
    /* --------------------------------------------------------------------- */

    /** Simple fast scanner used throughout the program. */
    private static final class FastScanner {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        FastScanner(InputStream source) {
            reader = new BufferedReader(new InputStreamReader(source));
        }

        /** Initializes the internal tokenizer with the first line. */
        void init(InputStream source) throws IOException {
            tokenizer = new StringTokenizer(reader.readLine());
        }

        /** Returns the next token (blocking if necessary). */
        private String nextToken() throws IOException {
            while (!tokenizer.hasMoreTokens()) {
                tokenizer = new StringTokenizer(reader.readLine());
            }
            return tokenizer.nextToken();
        }

        /** Convenience methods. */
        int nextInt() throws IOException { return Integer.parseInt(nextToken()); }
        char nextChar() throws IOException { return nextToken().charAt(0); }
    }

    /** Simple wrapper around PrintWriter that automatically flushes on close. */
    private static final class FastOutput {
        private final PrintWriter writer;

        FastOutput(OutputStream out) {
            this.writer = new PrintWriter(out);
        }

        void printGrid(char[][] grid) {
            for (char[] row : grid) {
                for (char cell : row) {
                    writer.print(cell);
                }
                writer.println();
            }
        }

        void println(String message) {
            writer.println(message);
        }

        void close() {
            writer.flush();
            writer.close();
        }
    }

    /* --------------------------------------------------------------------- */
    /*                         CORE ALGORITHM LOGIC                          */
    /* --------------------------------------------------------------------- */

    /** Directions used for neighbour traversal – mirrors {@link Direction}. */
    private static final int[] DR = {-1, 0, 1, 0};
    private static final int[] DC = {0, 1, 0, -1};

    /** Symbols that correspond to the four directions (same order as DR/DC). */
    private static final char[] SYMBOLS = {'^', '>', 'v', '<'};

    /** Computes the degree (number of adjacent empty cells) for each '.' in the grid. */
    private static int[][] computeDegrees(char[][] grid) {
        int n = grid.length;
        int m = grid[0].length;
        int[][] degree = new int[n][m];
        for (int r = 0; r < n; ++r) {
            for (int c = 0; c < m; ++c) {
                if (grid[r][c] != '.') {
                    continue;
                }
                int cnt = 0;
                for (int d = 0; d < 4; ++d) {
                    int nr = r + DR[d];
                    int nc = c + DC[d];
                    if (inBounds(nr, nc, n, m) && grid[nr][nc] == '.') {
                        ++cnt;
                    }
                }
                degree[r][c] = cnt;
            }
        }
        return degree;
    }

    /** Populates a queue with all cells that have degree == 1 (and are '.'). */
    private static void enqueueDegreeOneCells(int[][] degree, char[][] grid,
                                                Queue<Cell> q) {
        for (int r = 0; r < degree.length; ++r) {
            for (int c = 0; c < degree[0].length; ++c) {
                if (grid[r][c] == '.' && degree[r][c] == 1) {
                    q.add(new Cell(r, c));
                    degree[r][c] = -1; // mark as already enqueued
                }
            }
        }
    }

    /** Main propagation step – assigns arrows to cells that have degree 1. */
    private static void propagate(int[][] degree,
                                  char[][] grid,
                                  Queue<Cell> active) {
        while (!active.isEmpty()) {
            Cell cur = active.poll();
            int r = cur.row;
            int c = cur.col;

            // The cell must still be empty; otherwise it was processed twice.
            if (grid[r][c] != '.') {
                continue;
            }

            boolean propagated = false;
            for (int d = 0; d < 4; ++d) {
                int nr = r + DR[d];
                int nc = c + DC[d];
                if (!inBounds(nr, nc, grid.length, grid[0].length) ||
                        grid[nr][nc] != '.') {
                    continue;
                }

                // Assign direction to the neighbour and the opposite direction
                // to the current cell.
                grid[nr][nc] = SYMBOLS[d];
                grid[r][c]   = SYMBOLS[(d + 2) % 4];

                // Decrease degree of all neighbours of the newly filled cell.
                for (int nd = 0; nd < 4; ++nd) {
                    int nnr = nr + DR[nd];
                    int nnc = nc + DC[nd];
                    if (!inBounds(nnr, nnc, grid.length, grid[0].length) ||
                            grid[nnr][nnc] != '.') {
                        continue;
                    }
                    if (--degree[nnr][nnc] == 1) {
                        active.add(new Cell(nnr, nnc));
                    }
                }
                propagated = true;
                break; // only one neighbour can be used (degree == 1 guarantees uniqueness)
            }

            // If we could not find a free neighbour, the puzzle is unsolvable.
            if (!propagated) {
                throw new IllegalStateException("Puzzle inconsistency detected.");
            }
        }
    }

    /** Checks whether any '.' remain in the grid. */
    private static boolean hasEmptyCells(char[][] grid) {
        for (char[] row : grid) {
            for (char cell : row) {
                if (cell == '.') {
                    return true;
                }
            }
        }
        return false;
    }

    /** Utility – true if (r, c) lies inside an N×M grid. */
    private static boolean inBounds(int r, int c, int n, int m) {
        return r >= 0 && r < n && c >= 0 && c < m;
    }

    /* --------------------------------------------------------------------- */
    /*                               MAIN ENTRY                               */
    /* --------------------------------------------------------------------- */

    public static void main(String[] args) throws IOException {
        FastScanner in = new FastScanner(System.in);
        in.init(System.in);
        FastOutput out = new FastOutput(System.out);

        // -----------------------------------------------------------------
        // 1. Read dimensions and grid
        // -----------------------------------------------------------------
        int rows = in.nextInt();
        int cols = in.nextInt();
        char[][] board = new char[rows][cols];
        for (int r = 0; r < rows; ++r) {
            String line = in.next();
            for (int c = 0; c < cols; ++c) {
                board[r][c] = line.charAt(c);
            }
        }

        // -----------------------------------------------------------------
        // 2. Compute adjacency degree for every empty cell ('.')
        // -----------------------------------------------------------------
        int[][] degree = computeDegrees(board);
        Queue<Cell> queue = new ArrayDeque<>();

        // Enqueue all degree‑1 cells to start the propagation.
        enqueueDegreeOneCells(degree, board, queue);

        // -----------------------------------------------------------------
        // 3. Propagate assignments until queue empties
        // -----------------------------------------------------------------
        propagate(degree, board, queue);

        // -----------------------------------------------------------------
        // 4. Determine final answer
        // -----------------------------------------------------------------
        if (hasEmptyCells(board)) {
            out.println("Not unique");
        } else {
            out.printGrid(board);
        }

        out.close();
    }
}

import java.io.*;
import java.util.*;

/**
 * Solver for the “unique domino tiling” problem.
 *
 * <p>Reads a grid consisting of '.' (free) and other characters.
 * Tries to pair each free cell with exactly one adjacent free cell.
 * If every free cell can be paired uniquely, the result is printed using
 * '^', 'v', '<', '>' to indicate the orientation of each domino.
 * Otherwise the literal {@code Not unique} is printed.
 */
public class Solver {

    /** Relative directions: down, left, up, right */
    private static final int[][] DIRECTIONS = {
            {1, 0},    // down
            {0, -1},   // left
            {-1, 0},   // up
            {0, 1}     // right
    };

    /** Fast scanner used to read the input */
    private static final class FastScanner {
        private final InputStream stream;
        private final byte[] buffer = new byte[1024];
        private int curChar;
        private int numChars;
        private final StringBuilder sb = new StringBuilder();

        FastScanner(InputStream stream) {
            this.stream = stream;
        }

        private int read() {
            if (numChars == -1) throw new InputMismatchException();
            if (curChar >= numChars) {
                curChar = 0;
                numChars = stream.read(buffer);
                if (numChars <= 0) return -1;
            }
            return buffer[curChar++];
        }

        private boolean isWhitespace(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        /** Reads the next token (non‑whitespace sequence). */
        String next() {
            int c = read();
            while (isWhitespace(c)) c = read();
            sb.setLength(0);
            do {
                sb.appendCodePoint(c);
                c = read();
            } while (!isWhitespace(c));
            return sb.toString();
        }

        /** Reads the next integer. */
        int nextInt() {
            return (int) nextLong();
        }

        /** Reads the next long. */
        long nextLong() {
            int c = read();
            while (isWhitespace(c)) c = read();
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            long value = 0;
            do {
                if (c < '0' || c > '9') throw new InputMismatchException();
                value = value * 10 + (c - '0');
                c = read();
            } while (!isWhitespace(c));
            return value * sign;
        }
    }

    /** Simple container for a grid cell (row, column). */
    private static final class Cell {
        final int row;
        final int col;

        Cell(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }

    /** The main solving routine – called from {@code main}. */
    public void solve() throws Exception {
        FastScanner in = new FastScanner(System.in);

        final String NOT_UNIQUE = "Not unique";

        int rows = in.nextInt();
        int cols = in.nextInt();
        String[] gridLines = new String[rows];
        for (int r = 0; r < rows; r++) {
            gridLines[r] = in.next();
        }

        // Count for each free cell how many adjacent free cells exist.
        int[][] adjacentCount = new int[rows][cols];
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (gridLines[r].charAt(c) != '.') continue;
                int cnt = 0;
                for (int[] d : DIRECTIONS) {
                    int nr = r + d[0];
                    int nc = c + d[1];
                    if (isInside(nr, nc) && gridLines[nr].charAt(nc) == '.') {
                        cnt++;
                    }
                }
                adjacentCount[r][c] = cnt;
            }
        }

        // Queue of cells that currently have exactly one possible partner.
        Queue<Cell> queue = new ArrayDeque<>();
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (gridLines[r].charAt(c) == '.' && adjacentCount[r][c] == 1) {
                    queue.add(new Cell(r, c));
                }
            }
        }

        char[][] result = new char[rows][];
        for (int r = 0; r < rows; r++) {
            result[r] = gridLines[r].toCharArray();
        }

        boolean[][] done = new boolean[rows][cols];
        while (!queue.isEmpty()) {
            Cell cur = queue.poll();
            if (done[cur.row][cur.col] || adjacentCount[cur.row][cur.col] != 1) {
                continue;
            }

            // Find the only free neighbour that is not yet used.
            Cell partner = findUniquePartner(cur, done, gridLines);
            if (partner == null) {
                // Should never happen if the queue logic is correct.
                System.out.println(NOT_UNIQUE);
                return;
            }

            placeDomino(result, cur.row, cur.col, partner.row, partner.col);
            done[cur.row][cur.col] = done[partner.row][partner.col] = true;

            // Update degrees of neighbours of the partner.
            for (int[] d : DIRECTIONS) {
                int nr = partner.row + d[0];
                int nc = partner.col + d[1];
                if (!isInside(nr, nc) || done[nr][nc] || gridLines[nr].charAt(nc) != '.') {
                    continue;
                }
                adjacentCount[nr][nc]--;
                if (adjacentCount[nr][nc] == 1) {
                    queue.add(new Cell(nr, nc));
                }
            }
        }

        // If any free cell remains unmatched, the tiling is not unique.
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (!done[r][c] && gridLines[r].charAt(c) == '.') {
                    System.out.println(NOT_UNIQUE);
                    return;
                }
            }
        }

        // Output the resulting tiling.
        StringBuilder sb = new StringBuilder();
        for (char[] row : result) {
            sb.append(row).append('\n');
        }
        System.out.print(sb);
    }

    /** Checks whether a grid coordinate lies inside the board. */
    private boolean isInside(int r, int c) {
        return r >= 0 && r < resultLength && c >= 0 && c < resultWidth;
    }

    /** Retrieves the dimensions of the grid (used for bounds checking). */
    private int resultLength;
    private int resultWidth;

    /** Finds the unique free neighbour of {@code cell} that is not yet used. */
    private Cell findUniquePartner(Cell cell, boolean[][] done, String[] grid) {
        int r = cell.row;
        int c = cell.col;
        for (int[] d : DIRECTIONS) {
            int nr = r + d[0];
            int nc = c + d[1];
            if (isInside(nr, nc) && !done[nr][nc] && grid[nr].charAt(nc) == '.') {
                return new Cell(nr, nc);
            }
        }
        return null; // no partner found
    }

    /** Marks the two cells forming a domino with the appropriate directional symbols.
     *  The orientation is deduced from the relative position of the cells.
     */
    private void placeDomino(char[][] board, int r0, int c0, int r1, int c1) {
        int dr = r1 - r0;
        int dc = c1 - c0;

        // Resolve cases where the partner is above or to the left by swapping.
        if (dr < 0 || (dr == 0 && dc < 0)) {
            placeDomino(board, r1, c1, r0, c0);
            return;
        }

        switch (dr) {
            case 1 -> { // partner is below
                board[r0][c0] = '^';
                board[r1][c1] = 'v';
            }
            case 0, -1 -> { // horizontal
                if (dc > 0) { // partner is to the right
                    board[r0][c0] = '<';
                    board[r1][c1] = '>';
                } else { // partner is to the left – should have been handled by recursion
                    board[r0][c0] = '<';
                    board[r1][c1] = '>';
                }
            }
        }
    }

    /** Entry point – keeps the original signature expected by the judge. */
    public static void main(String[] args) throws Exception {
        new Solver().solve();
    }
}

import java.io.BufferedInputStream;
import java.io.PrintWriter;
import java.util.ArrayDeque;
import java.util.Arrays;

/**
 * Reads a grid, fills it with arrows that describe a unique tiling,
 * and prints the result. If the tiling is not unique or impossible,
 * prints "Not unique".
 *
 * The code is deliberately split into small, well‑named methods,
 * uses self‑describing variable names and isolates input handling
 * from the algorithmic part, making it easier to understand,
 * maintain and extend.
 */
public class D292 {

    /* --------------------------------------------------------------------- */
    /*  Constants                                                          */
    /* --------------------------------------------------------------------- */
    private static final int[] DR = {-1, 0, 1, 0};
    private static final int[] DC = {0, -1, 0, 1};
    private static final char[] DIR_CHAR = {'v', '>', '^', '<'};

    /* --------------------------------------------------------------------- */
    /*  Fast scanner – a tiny, high‑performance wrapper around InputStream   */
    /* --------------------------------------------------------------------- */
    private static final class FastScanner {
        private final BufferedInputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int bufferIdx = 0, size = 0;
        private char curChar = 0;

        FastScanner(InputStream input) {
            this.in = new BufferedInputStream(input, 1 << 16);
        }

        private int readByte() throws java.io.IOException {
            if (bufferIdx == size) {
                size = in.read(buffer);
                bufferIdx = 0;
                if (size == -1) size = 0;
            }
            return bufferIdx < size ? buffer[bufferIdx++] : -1;
        }

        private char nextChar() throws java.io.IOException {
            while (true) {
                int code = readByte();
                if (code == -1) return 0;
                char ch = (char) code;
                if (!Character.isWhitespace(ch)) return ch;
            }
        }

        public int nextInt() {
            return (int) nextLong();
        }

        public long nextLong() {
            long negative = 0, result = 0;
            char ch = nextChar();
            while (ch != '-' && (ch < '0' || ch > '9')) ch = nextChar();
            if (ch == '-') {
                negative = 1;
                ch = nextChar();
            }
            while (ch >= '0' && ch <= '9') {
                result = result * 10 + (ch - '0');
                ch = nextChar();
            }
            return negative == 1 ? -result : result;
        }
    }

    /* --------------------------------------------------------------------- */
    /*  Core solving logic                                                  */
    /* --------------------------------------------------------------------- */
    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        final int rows = fs.nextInt();
        final int cols = fs.nextInt();

        char[][] board = new char[rows][];
        for (int r = 0; r < rows; r++) {
            board[r] = fs.next().toCharArray();
        }

        /* --------------------------------------------------------------- */
        /*  1. Colouring cells to start propagation (mirrors original code) */
        /* --------------------------------------------------------------- */
        int[][] colour = new int[rows][cols];
        for (int r = 0; r < rows; r++) {
            Arrays.fill(colour[r], -1);
        }
        colour[0][0] = 0;
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (r == 0 && c == 0) continue;
                if (c > 0) {
                    colour[r][c] = colour[r][c - 1] ^ 1;
                } else {
                    colour[r][c] = colour[r - 1][c] ^ 1;
                }
            }
        }

        /* --------------------------------------------------------------- */
        /*  2. Queue of cells that have exactly one empty neighbour            */
        /* --------------------------------------------------------------- */
        ArrayDeque<int[]> pending = new ArrayDeque<>();
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (board[r][c] != '.' ) continue;
                if (hasExactlyOneEmptyNeighbour(board, r, c)) {
                    pending.add(new int[]{r, c});
                }
            }
        }

        /* --------------------------------------------------------------- */
        /*  3. Repeatedly place forced dominoes while queue not empty        */
        /* --------------------------------------------------------------- */
        placeForcedPairs(board, pending, rows, cols);

        /* --------------------------------------------------------------- */
        /*  4. Verify whether the whole board was filled                     */
        /* --------------------------------------------------------------- */
        boolean allFilled = true;
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (board[r][c] == '.') {
                    allFilled = false;
                    break;
                }
            }
            if (!allFilled) break;
        }

        /* --------------------------------------------------------------- */
        /*  5. Output result                                                   */
        /* --------------------------------------------------------------- */
        PrintWriter out = new PrintWriter(System.out);
        if (!allFilled) {
            out.println("Not unique");
        } else {
            for (char[] line : board) {
                out.print(line);
            }
            out.println();
        }
        out.flush();
    }

    /* --------------------------------------------------------------------- */
    /*  Helper: does a given cell have exactly one free neighbour?           */
    /* --------------------------------------------------------------------- */
    private static boolean hasExactlyOneEmptyNeighbour(char[][] board,
                                                        int r, int c) {
        int count = 0;
        for (int d = 0; d < 4; d++) {
            int nr = r + DR[d];
            int nc = c + DC[d];
            if (inside(nr, nc, board.length, board[0]) && board[nr][nc] == '.') {
                count++;
            }
        }
        return count == 1;
    }

    /* --------------------------------------------------------------------- */
    /*  Helper: place the domino for a forced placement and enqueue newly    */
    /*          placed cells that become forced themselves                    */
    /* --------------------------------------------------------------------- */
    private static void placeForcedPairs(char[][] board,
                                         ArrayDeque<int[]> queue,
                                         int rows, int cols) {
        while (!queue.isEmpty()) {
            int[] cur = queue.poll();
            int r = cur[0];
            int c = cur[1];

            if (board[r][c] != '.') continue;          // already resolved

            for (int d = 0; d < 4; d++) {
                int nr = r + DR[d];
                int nc = c + DC[d];
                if (!inside(nr, nc, rows, cols) || board[nr][nc] != '.') continue;

                // fill the domino
                board[r][c] = DIR_CHAR[d];
                board[nr][nc] = DIR_CHAR[(d + 2) % 4];

                // enqueue any neighbour that now has a unique empty neighbour
                for (int nd = 0; nd < 4; nd++) {
                    int rr = nr + DR[nd];
                    int rc = nc + DC[nd];
                    if (inside(rr, rc, rows, cols) && board[rr][rc] == '.') {
                        if (hasExactlyOneEmptyNeighbour(board, rr, rc)) {
                            queue.add(new int[]{rr, rc});
                        }
                    }
                }
            }
        }
    }

    /* --------------------------------------------------------------------- */
    /*  Utility: check bounds                                                */
    /* --------------------------------------------------------------------- */
    private static boolean inside(int r, int c, int rows, int cols) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }
}

/*  Refactored solution for the “unique tiling” problem.
 *  The program reads a grid of '.' and '#', tries to fill every '.' with a
 *  directed arrow that connects it to exactly one adjacent '.', and must do
 *  this in a unique way.  If any '.' remains unmatched the output is
 *  “Not unique”, otherwise the resulting grid of arrows is printed.
 *
 *  The refactor focuses on readability, maintainability and separation of
 *  concerns while preserving the original algorithmic behaviour.
 */

import java.io.IOException;
import java.io.InputStream;
import java.io.PrintWriter;
import java.util.ArrayDeque;
import java.util.Arrays;
import java.util.Queue;

public class Solver {

    /** Fast scanner that works with BufferedInputStream for speed. */
    private static final class FastScanner {
        private final InputStream stream;
        private final byte[] buffer = new byte[1024];
        private int curPos;
        private int curLen;

        FastScanner(InputStream stream) {
            this.stream = stream;
        }

        private int readByte() {
            if (curLen == -1) {
                throw new IOException();
            }
            if (curPos >= curLen) {
                curPos = 0;
                curLen = stream.read(buffer);
                if (curLen <= 0) {
                    return -1;
                }
            }
            return buffer[curPos++];
        }

        /** Skip whitespace characters. */
        private int skipWhite() {
            int b;
            do {
                b = readByte();
            } while (isSpace(b));
            return b;
        }

        private static boolean isSpace(int b) {
            return b == ' ' || b == '\n' || b == '\r' || b == '\t';
        }

        /** Return next non‑whitespace token as a string. */
        String next() {
            int c = skipWhite();
            StringBuilder sb = new StringBuilder();
            do {
                sb.appendCodePoint(c);
                c = readByte();
            } while (!isSpace(c));
            return sb.toString();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        char[] nextCharArray(int length) {
            char[] arr = new char[length];
            for (int i = 0; i < length; i++) {
                arr[i] = (char) next().charAt(0);
            }
            return arr;
        }
    }

    /** Pair of adjacent cells that were forced to match each other. */
    private static final class Pair {
        final int x, y;          // coordinates of the first cell
        final int nx, ny;        // coordinates of the neighbor

        Pair(int x, int y, int nx, int ny) {
            this.x = x;
            this.y = y;
            this.nx = nx;
            this.ny = ny;
        }
    }

    /** Direction vectors for the four orthogonal neighbours. */
    private static final int[][] DIR = {
            {0, -1}, // up
            {-1, 0}, // left
            {1, 0},  // right
            {0, 1}   // down
    };

    /** The main solving routine. */
    private final FastScanner in;
    private final PrintWriter out;

    Solver(FastScanner in, PrintWriter out) {
        this.in = in;
        this.out = out;
    }

    /** Entry point used by the original starter code. */
    public static void main(String[] args) {
        new Solver(new FastScanner(System.in), new PrintWriter(System.out)).run();
    }

    /** Runs the whole algorithm. */
    public void run() {
        int rows = in.nextInt();
        int cols = in.nextInt();
        char[][] grid = readGrid(rows);

        Queue<Pair> queue = findForcedPairs(grid);
        process(queue, grid);

        if (containsFreeCell(grid)) {
            out.println("Not unique");
        } else {
            for (char[] line : grid) {
                out.println(new String(line));
            }
        }
        out.close();
    }

    /** Reads the grid from the scanner. */
    private char[][] readGrid(int n) {
        char[][] map = new char[n][];
        for (int i = 0; i < n; i++) {
            map[i] = in.nextCharArray(cols);
        }
        return map;
    }

    /** Locate all cells that have exactly one adjacent free neighbour – they must be paired immediately. */
    private Queue<Pair> findForcedPairs(char[][] grid) {
        Queue<Pair> q = new ArrayDeque<>();
        for (int y = 0; y < grid.length; y++) {
            for (int x = 0; x < grid[y].length; x++) {
                if (grid[y][x] != '.') {
                    continue;
                }
                int freeNeighbours = countFreeNeighbours(grid, x, y);
                if (freeNeighbours == 1) {
                    Pair forced = findUniqueNeighbour(grid, x, y);
                    q.add(forced);
                }
            }
        }
        return q;
    }

    /** Count how many orthogonal neighbours of (x,y) are '.' and remember the single one if it exists. */
    private int countFreeNeighbours(char[][] grid, int x, int y) {
        int count = 0;
        int nx = -1, ny = -1;
        for (int[] d : DIR) {
            int nx2 = x + d[0];
            int ny2 = y + d[1];
            if (inside(nx2, ny2, grid) && grid[ny2][nx2] == '.') {
                count++;
                nx = nx2;
                ny = ny2;
            }
        }
        return count;
    }

    /** Return the unique neighbour that is '.' for a cell that is known to have exactly one such neighbour. */
    private Pair findUniqueNeighbour(char[][] grid, int x, int y) {
        for (int[] d : DIR) {
            int nx = x + d[0];
            int ny = y + d[1];
            if (inside(nx, ny, grid) && grid[ny][nx] == '.') {
                return new Pair(nx, ny, x, y); // store in (neighbor → current) order for later processing
            }
        }
        throw new IllegalStateException("Expected exactly one free neighbour");
    }

    /** Main loop – repeatedly take a forced pair, place the arrows and propagate newly created forced pairs. */
    private void process(Queue<Pair> queue, char[][] grid) {
        while (!queue.isEmpty()) {
            Pair cur = queue.poll();
            if (!bothFree(grid, cur)) {
                continue; // this pair was already consumed by a previous step
            }
            placeArrow(cur, grid);

            // neighbours of the newly placed pair might become forced now
            inspectNeighbourhood(cur, grid, queue);
        }
    }

    /** Place the proper arrow characters for a matched pair. */
    private void placeArrow(Pair p, char[][] grid) {
        int dx = p.nx - p.x; // neighbour relative to current
        int dy = p.ny - p.y;

        if (dy == -1) {            // neighbour is above
            grid[p.y][p.x] = 'v';
            grid[p.ny][p.nx] = '^';
        } else if (dy == 1) {      // neighbour is below
            grid[p.y][p.x] = '^';
            grid[p.ny][p.nx] = 'v';
        } else if (dx == -1) {     // neighbour is to the left
            grid[p.y][p.x] = '<';
            grid[p.ny][p.nx] = '>';
        } else {                   // dx == 1, neighbour is to the right
            grid[p.y][p.x] = '>';
            grid[p.ny][p.nx] = '<';
        }
    }

    /** Examine the eight neighbours (the four around each of the two cells) for newly formed forced pairs. */
    private void inspectNeighbourhood(Pair p, char[][] grid, Queue<Pair> queue) {
        for (int[] dir : DIR) {
            // first cell
            int nx = p.x + dir[0];
            int ny = p.y + dir[1];
            handlePotentialForced(grid, nx, ny, queue);

            // second cell
            nx = p.nx + dir[0];
            ny = p.ny + dir[1];
            handlePotentialForced(grid, nx, ny, queue);
        }
    }

    /** If a '.' cell has exactly one free neighbour, add that forced pair to the queue. */
    private void handlePotentialForced(char[][] grid, int x, int y, Queue<Pair> queue) {
        if (!inside(x, y, grid) || grid[y][x] != '.') {
            return;
        }
        int freeNeighbours = countFreeNeighbours(grid, x, y);
        if (freeNeighbours == 1) {
            Pair forced = findUniqueNeighbour(grid, x, y);
            queue.add(forced);
        }
    }

    /** Return true if all cells are filled (i.e. no '.' remains). */
    private boolean containsFreeCell(char[][] grid) {
        for (char[] row : grid) {
            for (char cell : row) {
                if (cell == '.') {
                    return true;
                }
            }
        }
        return false;
    }

    /** Verify that both cells of a Pair are still '.' – required because a pair may be processed twice. */
    private boolean bothFree(char[][] grid, Pair p) {
        return grid[p.y][p.x] == '.' && grid[p.ny][p.nx] == '.';
    }

    /** Simple bounds check. */
    private boolean inside(int x, int y, char[][] grid) {
        return x >= 0 && x < grid[0].length && y >= 0 && y < grid.length;
    }
}

/*
 *  Domino Tilings – unique‑tiling checker
 *  --------------------------------------------------------------
 *  The program reads a rectangular grid of characters ('.' denotes an empty
 *  cell).  It tries to cover every empty cell with 2×1 dominoes in a
 *  deterministic way.  If at any point the placement is ambiguous or
 *  impossible, the output is “Not unique”.  Otherwise the board is printed
 *  with the characters ‘^’, ‘v’, ‘<’, ‘>’ indicating the orientation of each
 *  domino.
 *
 *  The refactoring focuses on:
 *   • Clear separation of concerns (scanner, solver, helper classes)
 *   • Meaningful naming and encapsulation
 *   • Removal of unnecessary static mutable fields
 *   • Use of try‑with‑resources for I/O
 *   • Small, single‑responsibility methods
 *   • Java‑8+ stream usage for concise counting
 *
 *  The algorithm is identical to the original one but expressed in a
 *  cleaner, easier‑to‑maintain style.
 */

import java.io.*;
import java.util.*;
import java.util.stream.*;

public class Main {

    // --------------------------------------------------------------------
    // Fast input – works with stdin or with a file supplied on the command line
    // --------------------------------------------------------------------
    private static final class FastScanner implements Closeable {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        FastScanner() {
            this.reader = new BufferedReader(new InputStreamReader(System.in));
            this.tokenizer = new StringTokenizer("");
        }

        FastScanner(File file) throws FileNotFoundException {
            this.reader = new BufferedReader(new FileReader(file));
            this.tokenizer = new StringTokenizer("");
        }

        private void ensureTokens() throws IOException {
            while (!tokenizer.hasMoreTokens()) {
                String line = reader.readLine();
                if (line == null) {
                    throw new EOFException();
                }
                tokenizer = new StringTokenizer(line);
            }
        }

        int nextInt() throws IOException {
            ensureTokens();
            return Integer.parseInt(tokenizer.nextToken());
        }

        long nextLong() throws IOException {
            ensureTokens();
            return Long.parseLong(tokenizer.nextToken());
        }

        double nextDouble() throws IOException {
            ensureTokens();
            return Double.parseDouble(tokenizer.nextToken());
        }

        String nextString() throws IOException {
            ensureTokens();
            return tokenizer.nextToken();
        }

        String readLine() throws IOException {
            return reader.readLine();
        }

        @Override
        public void close() throws IOException {
            reader.close();
        }
    }

    // --------------------------------------------------------------------
    // Constants for neighbour movement and the characters that represent
    // each orientation of a domino.
    // --------------------------------------------------------------------
    private static final int[] DR = { -1, 0, 1, 0 };
    private static final int[] DC = { 0, -1, 0, 1 };
    private static final char[] DIR_CHAR = { '^', '<', 'v', '>' };

    // --------------------------------------------------------------------
    // Entry point – delegates all work to the Solver class.
    // --------------------------------------------------------------------
    public static void main(String[] args) throws Exception {
        try (FastScanner fs = new FastScanner()) {
            PrintWriter out = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)));
            new Solver().solve(fs, out);
            out.close();
        }
    }

    // --------------------------------------------------------------------
    // Core solving logic – self‑contained and easy to unit‑test.
    // --------------------------------------------------------------------
    private static final class Solver {

        private char[][] board;          // the grid read from input
        private final int rows, cols;    // dimensions
        private final List<Cell> workList = new ArrayList<>(); // all empty cells

        /** Simple immutable container for a cell coordinate. */
        private static final class Cell {
            final int r, c;
            Cell(int r, int c) { this.r = r; this.c = c; }
        }

        /** Starts the whole solving process. */
        void solve(FastScanner fs, PrintWriter out) throws IOException {
            readInput(fs, out);
            if (!canBeTiled(out)) {
                return; // error message already printed
            }
            tileBoard(out);
            printResult(out);
        }

        /** Reads the grid and performs quick sanity checks. */
        private void readInput(FastScanner fs, PrintWriter out) throws IOException {
            rows = fs.nextInt();
            cols = fs.nextInt();
            board = new char[rows][cols];
            for (int r = 0; r < rows; r++) {
                board[r] = fs.readLine().toCharArray();
            }

            // Odd number of empty cells → impossible to tile uniquely.
            long emptyCount = Arrays.stream(board)
                    .flatMap(Arrays::stream)
                    .filter(ch -> ch == '.')
                    .count();
            if (emptyCount % 2 != 0) {
                out.println("Not unique");
                throw new IOException(); // signal early exit
            }

            // Keep a mutable list of all initially empty cells.
            workList.clear();
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (board[r][c] == '.') {
                        workList.add(new Cell(r, c));
                    }
                }
            }
        }

        /** Determines whether a unique tiling exists using a deterministic greedy propagation. */
        private boolean canBeTiled(PrintWriter out) {
            while (true) {
                // All cells that are still empty and have exactly one free neighbour must be processed now.
                List<Cell> forced = findForcedCells();

                if (forced.isEmpty()) {
                    // No forced move left – ambiguity or impossibility.
                    out.println("Not unique");
                    return false;
                }

                for (Cell cell : forced) {
                    // The cell might already have been covered by a previous placement.
                    if (board[cell.r][cell.c] != '.') {
                        continue;
                    }
                    placeDomino(cell);
                }
            }
        }

        /** Returns the sub‑list of empty cells that have exactly one free orthogonal neighbour. */
        private List<Cell> findForcedCells() {
            List<Cell> forced = new ArrayList<>();
            for (Cell cell : workList) {
                if (board[cell.r][cell.c] != '.') {
                    continue; // already covered
                }
                int freeNeighbours = countFreeNeighbours(cell.r, cell.c);
                if (freeNeighbours == 0) {
                    // Dead end – cannot tile.
                    System.out.println("Not unique");
                    throw new IllegalStateException();
                }
                if (freeNeighbours == 1) {
                    forced.add(cell);
                }
            }
            return forced;
        }

        /** Places a domino that starts at (r,c) and extends to its only free neighbour. */
        private void placeDomino(Cell start) {
            int r = start.r;
            int c = start.c;

            // Determine the unique free neighbour.
            int dir = -1;
            for (int d = 0; d < 4; d++) {
                int nr = r + DR[d];
                int nc = c + DC[d];
                if (nr < 0 || nr >= rows || nc < 0 || nc >= cols) {
                    continue;
                }
                if (board[nr][nc] == '.') {
                    dir = d;
                    break;
                }
            }
            if (dir == -1) {
                // Should never happen because we only call this when exactly one neighbour is free.
                return;
            }

            int nr = r + DR[dir];
            int nc = c + DC[dir];

            // Write the two halves of the domino.
            board[r][c] = DIR_CHAR[(dir + 2) % 4]; // opposite direction character for the start cell
            board[nr][nc] = DIR_CHAR[dir];         // direction character for the neighbour

            // Cells are now considered covered; subsequent iterations will simply skip them.
        }

        /** Counts orthogonal neighbours of (r,c) that are still empty ('.'). */
        private int countFreeNeighbours(int r, int c) {
            int cnt = 0;
            for (int d = 0; d < 4; d++) {
                int nr = r + DR[d];
                int nc = c + DC[d];
                if (nr < 0 || nr >= rows || nc < 0 || nc >= cols) {
                    continue;
                }
                if (board[nr][nc] == '.') {
                    cnt++;
                }
            }
            return cnt;
        }

        /** Prints the final tiling (or returns early if tiling is impossible). */
        private void printResult(PrintWriter out) {
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (board[r][c] == '.') {
                        // This situation should never arise because we would have exited earlier.
                        out.println("Not unique");
                        return;
                    }
                    out.print(board[r][c]);
                }
                out.println();
            }
        }
    }
}

import java.io.*;
import java.util.LinkedList;
import java.util.Queue;

/**
 * Entry point of the application.
 * Reads a rectangular grid of '.' and '#' characters,
 * attempts to tile the empty cells uniquely with dominoes,
 * and prints the tiled board or the message "Not unique".
 */
public class Main {

    /** Symbol used for a horizontal domino piece. */
    private static final char HORIZONTAL = '<';
    /** Symbol used for the opposite half of a horizontal domino. */
    private static final char HORIZONTAL_END = '>';

    /** Symbol used for a vertical domino piece. */
    private static final char VERTICAL_TOP = '^';
    /** Symbol used for the opposite half of a vertical domino. */
    private static final char VERTICAL_BOTTOM = 'v';

    /** Fast scanner implementation. */
    private static final class FastScanner {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        FastScanner(InputStream stream) {
            this.reader = new BufferedReader(
                    new InputStreamReader(stream, StandardCharsets.UTF_8), 32768);
        }

        /** Returns the next token or loads a new line if needed. */
        private void ensureTokenizer() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new UncheckedIOException(e);
                }
            }
        }

        String next() {
            ensureTokenizer();
            return tokenizer.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }
    }

    /** Core logic for solving the tiling problem. */
    static final class Solver {

        /** Grid containing '.' for free cells and any other character for blocked cells. */
        private char[][] grid;
        /** Number of rows in the grid. */
        private int rows;
        /** Number of columns in the grid. */
        private int cols;

        /** Queue used for processing cells with degree 1 during the greedy reduction. */
        private final Queue<Integer> degreeOneQueue = new LinkedList<>();

        /** Solves the problem for a single test case. */
        void solve(int testNumber, FastScanner in, PrintWriter out) {
            readInput(in);
            if (!canBeTiled()) {
                out.println("Not unique");
                return;
            }
            outputSolution(out);
        }

        /** Reads the dimensions and the grid from the scanner. */
        private void readInput(FastScanner in) {
            rows = in.nextInt();
            cols = in.nextInt();
            grid = new char[rows][];
            for (int r = 0; r < rows; r++) {
                grid[r] = in.next().toCharArray();
            }
        }

        /** Determines whether a unique tiling exists and performs the tiling if possible. */
        private boolean canBeTiled() {
            int uncoveredCells = countUncoveredCells();
            if (uncoveredCells % 2 != 0) {                     // odd number of cells → impossible
                return false;
            }

            // Initialise queue with all degree‑1 cells
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (grid[r][c] == '.' && degree(r, c) == 1) {
                        degreeOneQueue.add(index(r, c));
                    }
                }
            }

            while (!degreeOneQueue.isEmpty()) {
                int idx = degreeOneQueue.remove();
                int r = coordsFromIndex(idx)[0];
                int c = coordsFromIndex(idx)[1];

                // Skip if the cell has already been covered
                if (grid[r][c] != '.') {
                    continue;
                }

                // Find the only adjacent uncovered neighbour
                int[] neighbour = locateUniqueNeighbour(r, c);
                if (neighbour == null) {
                    continue; // no neighbour – should not happen in a valid degree‑1 cell
                }

                // Mark the pair as covered with appropriate symbols
                coverPair(r, c, neighbour[0], neighbour[1]);

                // Update the degree information of the surrounding cells
                spreadChanges(r, c, neighbour[0], neighbour[1]);

                uncoveredCells -= 2; // two cells have been covered
            }

            // If any uncovered cells remain, the tiling is not unique
            return uncoveredCells == 0;
        }

        /** Counts the number of '.' cells in the grid. */
        private int countUncoveredCells() {
            int count = 0;
            for (char[] row : grid) {
                for (char cell : row) {
                    if (cell == '.') {
                        count++;
                    }
                }
            }
            return count;
        }

        /** Returns the coordinates of the only adjacent '.' cell to (row, col) or {@code null}. */
        private int[] locateUniqueNeighbour(int row, int col) {
            int[] neighbours = new int[4];
            int count = 0;
            int targetRow = -1, targetCol = -1;

            // Check the four possible directions
            int[][] dirs = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};
            for (int[] d : dirs) {
                int r = row + d[0];
                int c = col + d[1];
                if (inBounds(r, c) && grid[r][c] == '.') {
                    neighbours[count++] = r * cols + c;
                    targetRow = r;
                    targetCol = c;
                }
            }
            return (count == 1) ? new int[]{targetRow, targetCol} : null;
        }

        /** Marks a matched pair of cells with the appropriate directional symbols. */
        private void coverPair(int r1, int c1, int r2, int c2) {
            if (r1 == r2) { // horizontal domino
                int min = Math.min(c1, c2);
                int max = Math.max(c1, c2);
                grid[r1][min] = HORIZONTAL;
                grid[r2][max] = HORIZONTAL_END;
            } else { // vertical domino
                int min = Math.min(r1, r2);
                int max = Math.max(r1, r2);
                grid[min][c1] = VERTICAL_TOP;
                grid[max][c2] = VERTICAL_BOTTOM;
            }
        }

        /** Propagates degree changes to neighbour cells after a covering operation. */
        private void spreadChanges(int r1, int c1, int r2, int c2) {
            for (int dr = -1; dr <= 1; dr++) {
                for (int dc = -1; dc <= 1; dc++) {
                    if (!isNeighbour(r1 + dr, c1 + dc)) continue;
                    pushIfDegreeOne(r1 + dr, c1 + dc);
                    if (!isNeighbour(r2 + dr, c2 + dc)) continue;
                    pushIfDegreeOne(r2 + dr, c2 + dc);
                }
            }
        }

        /** Adds a cell to the queue if it is free and its degree equals 1. */
        private void pushIfDegreeOne(int r, int c) {
            if (inBounds(r, c) && grid[r][c] == '.' && degree(r, c) == 1) {
                degreeOneQueue.add(index(r, c));
            }
        }

        /** Determines whether coordinates are inside the grid bounds. */
        private boolean inBounds(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }

        /** Computes the index of a cell in the flattened grid representation. */
        private int index(int row, int col) {
            return row * cols + col;
        }

        /** Extracts row and column from a flattened index. */
        private int[] coordsFromIndex(int index) {
            return new int[]{index / cols, index % cols};
        }

        /** Computes the degree (number of adjacent free cells) of a given position. */
        private int degree(int row, int col) {
            if (!inBounds(row, col) || grid[row][col] != '.') {
                return 0;
            }
            int deg = 0;
            int[][] dirs = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};
            for (int[] d : dirs) {
                if (inBounds(row + d[0], col + d[1]) && grid[row + d[0]][col + d[1]] == '.') {
                    deg++;
                }
            }
            return deg;
        }
    }

    /** Main method – orchestrates input, solving, and output. */
    public static void main(String[] args) throws Exception {
        try (InputStream inStream = System.in;
             OutputStream outStream = System.out;
             FastScanner scanner = new FastScanner(inStream);
             PrintWriter printer = new PrintWriter(outStream, true)) {

            new Solver().solve(/* test number */ 1, scanner, printer);
        }
    }
}

import java.io.*;
import java.util.*;

public class Main {

    // -----------------------------------------------------------------------
    // Constants and small helper utilities
    // -----------------------------------------------------------------------
    private static final int[][] DIRS = {
            {-1, 0}, // up
            {0, 1},  // right
            {1, 0},  // down
            {0, -1}  // left
    };

    private static final String NOT_UNIQUE = "Not unique";

    /** Simple container for a grid cell */
    private static final class Cell {
        final int r, c;
        Cell(int r, int c) { this.r = r; this.c = c; }
    }

    /** Places a domino covering (r,c) and (nr,nc) and writes the arrows */
    private static void placeDomino(char[][] board, int r, int c,
                                    int nr, int nc) {
        // (r,c) is above its partner → partner gets 'v', (r,c) gets '^'
        if (nr == r - 1 && nc == c) {
            board[r][c] = '^';
            board[nr][nc] = 'v';
        }
        // (r,c) is below its partner
        else if (nr == r + 1 && nc == c) {
            board[r][c] = 'v';
            board[nr][nc] = '^';
        }
        // (r,c) is left of its partner
        else if (nr == r && nc == c - 1) {
            board[r][c] = '<';
            board[nr][nc] = '>';
        }
        // (r,c) is right of its partner
        else {
            board[r][c] = '>';
            board[nr][nc] = '<';
        }
    }

    /** Counts how many adjacent cells are still empty ('.') */
    private static int countFreeNeighbours(char[][] board, int r, int c) {
        int cnt = 0;
        for (int[] d : DIRS) {
            int nr = r + d[0];
            int nc = c + d[1];
            if (inside(board, nr, nc) && board[nr][nc] == '.') {
                cnt++;
            }
        }
        return cnt;
    }

    /** true if (r,c) lies inside the grid */
    private static boolean inside(char[][] board, int r, int c) {
        return r >= 0 && c >= 0 && r < board.length && c < board[0].length;
    }

    // -----------------------------------------------------------------------
    // Core solving algorithm
    // -----------------------------------------------------------------------
    public static void main(String[] args) throws IOException {
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
             PrintWriter pw = new PrintWriter(new OutputStreamWriter(System.out))) {

            // ----- read dimensions and board ---------------------------------
            StringTokenizer st = new StringTokenizer(br.readLine());
            int n = Integer.parseInt(st.nextToken());
            int m = Integer.parseInt(st.nextToken());

            char[][] board = new char[n][m];
            for (int i = 0; i < n; i++) {
                board[i] = br.readLine().toCharArray();
            }

            boolean[][] visited = new boolean[n][m];
            Queue<Cell> queue = new ArrayDeque<>();

            // ----- find cells that have exactly one free neighbour -----------
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    if (board[i][j] == '.' && countFreeNeighbours(board, i, j) == 1) {
                        visited[i][j] = true;
                        queue.add(new Cell(i, j));
                    }
                }
            }

            // ----- propagate forced placements -------------------------------
            while (!queue.isEmpty()) {
                Cell cur = queue.poll();
                int r = cur.r;
                int c = cur.c;

                for (int[] d : DIRS) {
                    int nr = r + d[0];
                    int nc = c + d[1];

                    // partner must be empty and inside the grid
                    if (!inside(board, nr, nc) || board[nr][nc] != '.') {
                        continue;
                    }

                    // place the domino (arrows)
                    placeDomino(board, r, c, nr, nc);

                    // after placing, any neighbour that now has a single free
                    // neighbour becomes forced as well
                    for (int[] nd : DIRS) {
                        for (int[] pair : new int[][]{{r, c}, {nr, nc}}) {
                            int ar = pair[0] + nd[0];
                            int ac = pair[1] + nd[1];
                            if (inside(board, ar, ac) && board[ar][ac] == '.' && !visited[ar][ac]) {
                                if (countFreeNeighbours(board, ar, ac) == 1) {
                                    visited[ar][ac] = true;
                                    queue.add(new Cell(ar, ac));
                                }
                            }
                        }
                    }
                }
            }

            // ----- check whether every empty cell has been covered -----------
            boolean allCovered = true;
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    if (board[i][j] == '.') {
                        allCovered = false;
                        break;
                    }
                }
                if (!allCovered) {
                    break;
                }
            }

            if (!allCovered) {
                pw.println(NOT_UNIQUE);
            } else {
                for (char[] row : board) {
                    pw.println(new String(row));
                }
            }
        }
    }
}

/* -------------------------------------------------------------
 * Refactored version of the original program.
 * - Improves naming, extracts constants, separates concerns.
 * - Keeps the same functionality while making the code easier
 *   to read, test and maintain.
 * ------------------------------------------------------------- */
import java.io.PrintWriter;
import java.io.IOException;

/* ---------- entry point ------------------------------------------------- */
public class Main {
    public static void main(String[] args) {
        // Use try‑with‑resources to guarantee the PrintWriter is closed.
        try (PrintWriter out = new PrintWriter(System.out)) {
            InputReader reader = new InputReader(System.in);
            new Solution().solve(reader, out);
        }
    }
}

/* ---------- core algorithm ------------------------------------------------ */
final class Solution {

    /* ---- constants -------------------------------------------------------- */
    private static final int[] DX = {-1, 0, 0, 1};          // up, left, right, down
    private static final int[] DY = {0, -1, 1, 0};
    private static final char[] DIR_TO_C1 = {'v', '>', '<', '^'};
    private static final char[] DIR_TO_C2 = {'^', '<', '>', 'v'};

    private char[][] grid;      // input grid
    private int[][] degree;     // number of neighbouring '.' cells
    private int rows, cols;     // dimensions

    /* ---- public entry point ------------------------------------------------ */
    void solve(InputReader reader, PrintWriter out) {
        readInput(reader);
        if (solve()) {
            printSolution(out);
        } else {
            out.println("Not unique");
        }
    }

    /* ---- input ------------------------------------------------------------- */
    private void readInput(InputReader reader) {
        rows = reader.readInt();
        cols = reader.readInt();
        grid = new char[rows][];
        degree = new int[rows][cols];

        for (int r = 0; r < rows; r++) {
            String line = reader.readString();
            grid[r] = line.toCharArray();
        }
    }

    /* ---- solving ----------------------------------------------------------- */
    private boolean solve() {
        java.util.Queue<Position> queue = new java.util.ArrayDeque<>();

        // 1️⃣ Initialise degree values and seed the queue with cells that have ≤1 free neighbour.
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '.') {
                    degree[r][c] = countFreeNeighbours(r, c);
                    if (degree[r][c] <= 1) {
                        queue.add(new Position(r, c));
                    }
                }
            }
        }

        // 2️⃣ Process cells from the queue.
        while (!queue.isEmpty()) {
            Position cur = queue.poll();

            // Cell may already be matched – skip it.
            if (grid[cur.row][cur.col] != '.') {
                continue;
            }

            // Find the *only* neighbouring free cell.
            int nextRow = -1, nextCol = -1, dirIdx = -1;
            for (int d = 0; d < 4; d++) {
                int nr = cur.row + DX[d];
                int nc = cur.col + DY[d];
                if (isInBounds(nr, nc) && grid[nr][nc] == '.') {
                    nextRow = nr;
                    nextCol = nc;
                    dirIdx = d;
                    break;
                }
            }
            if (dirIdx == -1) {                // dead‑end → tiling impossible
                return false;
            }

            // Place the domino according to the found direction.
            grid[cur.row][cur.col] = DIR_TO_C1[dirIdx];
            grid[nextRow][nextCol] = DIR_TO_C2[dirIdx];

            // Update degree information for neighbours of both cells.
            updateNeighbourDegrees(nextRow, nextCol);
            updateNeighbourDegrees(cur.row, cur.col);
        }

        // 3️⃣ Verify that every cell was covered.
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '.') {
                    return false;
                }
            }
        }
        return true;
    }

    /** Returns the number of orthogonal neighbours of (r,c) that are still '.' */
    private int countFreeNeighbours(int r, int c) {
        int cnt = 0;
        for (int d = 0; d < 4; d++) {
            int nr = r + DX[d];
            int nc = c + DY[d];
            if (isInBounds(nr, nc) && grid[nr][nc] == '.') {
                cnt++;
            }
        }
        return cnt;
    }

    /** Adjusts degree values after a new domino is placed at (r,c) */
    private void updateNeighbourDegrees(int r, int c) {
        for (int d = 0; d < 4; d++) {
            int nr = r + DX[d];
            int nc = c + DY[d];
            if (isInBounds(nr, nc) && grid[nr][nc] == '.') {
                degree[nr][nc]--;
                if (degree[nr][nc] <= 1) {
                    queueIfNeeded(nr, nc);
                }
            }
        }
    }

    /** Helper that adds a position to the queue only when it is still free and degree ≤ 1 */
    private void queueIfNeeded(int r, int c) {
        if (grid[r][c] == '.' && degree[r][c] <= 1) {
            queue.add(new Position(r, c));
        }
    }

    /** Simple bounds check */
    private boolean isInBounds(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    /* ---- output ------------------------------------------------------------ */
    private void printSolution(PrintWriter out) {
        for (char[] row : grid) {
            out.println(new String(row));
        }
    }

    /* ---- tiny data holder --------------------------------------------------- */
    private static final class Position {
        final int row;
        final int col;

        Position(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }
}

/* ---------- input reader (unchanged from the original) --------------------- */
class InputReader {
    private final InputStream stream;
    private final byte[] buffer = new byte[1024];
    private int curChar;
    private int numChars;
    private final SpaceCharFilter filter;

    InputReader(InputStream stream) {
        this.stream = stream;
    }

    private int read() {
        if (numChars == -1) {
            throw new java.util.InputMismatchException();
        }
        if (curChar >= numChars) {
            curChar = 0;
            try {
                numChars = stream.read(buffer);
            } catch (IOException e) {
                throw new java.util.InputMismatchException();
            }
            if (numChars <= 0) {
                return -1;
            }
        }
        return buffer[curChar++];
    }

    int readInt() {
        int c = read();
        while (isSpaceChar(c)) {
            c = read();
        }
        int sign = 1;
        if (c == '-') {
            sign = -1;
            c = read();
        }
        int result = 0;
        do {
            if (c < '0' || c > '9') {
                throw new java.util.InputMismatchException();
            }
            result *= 10;
            result += c - '0';
            c = read();
        } while (!isSpaceChar(c));
        return result * sign;
    }

    String readString() {
        int c = read();
        while (isSpaceChar(c)) {
            c = read();
        }
        StringBuilder sb = new StringBuilder();
        do {
            if (Character.isValidCodePoint(c)) {
                sb.appendCodePoint(c);
            }
            c = read();
        } while (!isSpaceChar(c));
        return sb.toString();
    }

    boolean isSpaceChar(int c) {
        if (filter != null) {
            return filter.isSpaceChar(c);
        }
        return isWhitespace(c);
    }

    private static boolean isWhitespace(int c) {
        return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
    }

    // The rest of the original InputReader implementation (readLong,
    // readDouble, readLine, etc.) has been omitted here for brevity,
    // but it is exactly the same as in the original snippet and can be
    // copied verbatim if needed.
}

import java.io.*;
import java.util.*;

/**
 * Entry point that reads the input, solves the tiling problem and prints the result.
 */
public class Main {

    public static void main(String[] args) {
        solve();
    }

    /** Runs the whole solving procedure. */
    private static void solve() {
        InputScanner scanner = new InputScanner(System.in);
        PrintWriter out = new PrintWriter(System.out);

        int n = scanner.nextInt();
        int m = scanner.nextInt();

        char[][] board = new char[n][m];
        for (int i = 0; i < n; i++) {
            String line = scanner.nextLine().trim();
            board[i] = line.toCharArray();
        }

        TileSolver solver = new TileSolver(board);
        solver.solve(out);
        out.flush();
    }
}

/**
 * Encapsulates the domino‑tiling algorithm.
 */
class TileSolver {

    /** Arrow patterns used for the four possible orientations. */
    static final String[] TILE_PATTERNS = {"^", "v", "<", ">"};

    private final char[][] board;
    private final int rows;
    private final int cols;
    /** Number of adjacent free cells for each position – used as a degree counter. */
    private final int[][] degree;
    /** Queue of cells whose degree is currently 1. */
    private final Queue<Point> queue = new ArrayDeque<>();

    TileSolver(char[][] board) {
        this.board = board;
        this.rows = board.length;
        this.cols = board[0].length;
        this.degree = new int[rows][cols];
    }

    /** Starts the solving process and prints the outcome. */
    void solve(PrintWriter out) {
        initDegree();
        collectDegreeOnePoints();

        int[][] dirs = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};

        while (!queue.isEmpty()) {
            Point cur = queue.poll();
            int x = cur.row, y = cur.col;

            if (board[x][y] != '.') {
                continue;                     // already matched
            }

            Point match = findFreeNeighbor(x, y, dirs);
            if (match == null) {
                out.println("Not unique");
                return;
            }

            placeTile(x, y, match);
            decreaseDegreeAround(match);
            enqueueNeighborsWithDegreeOne(match);
        }

        // If any '.' remains the tiling is not unique
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (board[i][j] == '.') {
                    out.println("Not unique");
                    return;
                }
            }
        }

        // Successful unique tiling – output the board
        for (char[] row : board) {
            out.println(new String(row));
        }
    }

    /** Initialise the degree matrix based on right and down adjacency only. */
    private void initDegree() {
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (board[i][j] == '.') {
                    if (i + 1 < rows && board[i + 1][j] == '.') {
                        degree[i][j]++;
                        degree[i + 1][j]++;
                    }
                    if (j + 1 < cols && board[i][j + 1] == '.') {
                        degree[i][j]++;
                        degree[i][j + 1]++;
                    }
                }
                if (degree[i][j] == 1) {
                    queue.add(new Point(i, j));
                }
            }
        }
    }

    /** Locate the unique adjacent empty neighbour of (x, y). */
    private Point findFreeNeighbor(int x, int y, int[][] dirs) {
        for (int[] d : dirs) {
            int nx = x + d[0];
            int ny = y + d[1];
            if (inBounds(nx, ny) && board[nx][ny] == '.') {
                return new Point(nx, ny);
            }
        }
        return null;    // should not happen when degree == 1
    }

    /** Write the appropriate arrows for the newly placed domino. */
    private void placeTile(int x, int y, Point match) {
        int dx = match.row - x;
        int dy = match.col - y;

        int dirIdx = -1;
        if (dx == 1 && dy == 0) dirIdx = 0;            // down
        else if (dx == -1 && dy == 0) dirIdx = 1;      // up
        else if (dx == 0 && dy == 1) dirIdx = 2;       // right
        else if (dx == 0 && dy == -1) dirIdx = 3;      // left

        board[x][y] = TILE_PATTERNS[dirIdx].charAt(0);
        board[match.row][match.col] = TILE_PATTERNS[(dirIdx + 2) % 4].charAt(0);
    }

    /** Decrease degree counters of cells surrounding the placed tile. */
    private void decreaseDegreeAround(Point p) {
        int[][] dirs = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};
        for (int[] d : dirs) {
            int nx = p.row + d[0];
            int ny = p.col + d[1];
            if (inBounds(nx, ny) && board[nx][ny] == '.') {
                degree[nx][ny]--;
                if (degree[nx][ny] == 1) {
                    queue.add(new Point(nx, ny));
                }
            }
        }
    }

    /** Enqueue neighbours of a cell that now have degree 1. */
    private void enqueueNeighborsWithDegreeOne(Point p) {
        int[][] dirs = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};
        for (int[] d : dirs) {
            int nx = p.row + d[0];
            int ny = p.col + d[1];
            if (inBounds(nx, ny) && board[nx][ny] == '.' && degree[nx][ny] == 1) {
                queue.add(new Point(nx, ny));
            }
        }
    }

    /** Simple bounds checking. */
    private boolean inBounds(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    /** Small container for a coordinate pair. */
    private static final class Point {
        final int row;
        final int col;

        Point(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }
}

/**
 * Fast byte‑buffer based scanner suitable for competitive programming style input.
 */
class InputScanner {

    private final InputStream stream;
    private final byte[] buffer;
    private int curPos;
    private int byteCount;
    private final InputReader.SpaceCharFilter filter;

    InputScanner(InputStream stream) {
        this.stream = stream;
        this.buffer = new byte[1024];
        this.curPos = 0;
        this.byteCount = 0;
        this.filter = new InputReader.SpaceCharFilter() {
            @Override public boolean isSpaceChar(int ch) {
                return ch == ' ' || ch == '\n' || ch == '\r' || ch == '\t' || ch == -1;
            }
        };
    }

    /** Read the next non‑space character. */
    private int peek() {
        int c;
        while ((c = readByte()) != -1 && filter.isSpaceChar(c)) {}
        return c;
    }

    /** Read next integer from the input. */
    int nextInt() {
        int sign = 1, c = peek();
        if (c == '-') {
            sign = -1;
            c = readByte();
        }
        int value = 0;
        while (c >= '0' && c <= '9') {
            value = value * 10 + (c - '0');
            c = readByte();
        }
        return value * sign;
    }

    /** Read next complete line (including spaces). */
    String nextLine() {
        StringBuilder sb = new StringBuilder();
        int c;
        while ((c = readByte()) != -1 && c != '\n') {
            sb.append((char) c);
        }
        return sb.toString();
    }

    /** Read a single byte from the underlying stream using the buffer. */
    private int readByte() {
        if (byteCount <= curPos) {
            curPos = 0;
            byteCount = stream.read(buffer);
            if (byteCount == -1) {
                return -1;
            }
        }
        return buffer[curPos++];
    }
}

import java.io.*;
import java.util.*;

/**
 * Solver for a domino‑tiling problem.
 *
 * The algorithm:
 *   1. Read the board ('.' – empty, '*' – occupied).
 *   2. Count how many free neighbours each empty cell still has.
 *   3. Repeatedly take a cell that has exactly one free neighbour,
 *      place the corresponding domino and update the neighbour counts.
 *   4. If every empty cell becomes part of a domino, print the filled board,
 *      otherwise the tiling is not unique.
 */
public class DominoTilingSolver {

    /* --------------------------------------------------------------------- */
    /*  Directions (right, down, left, up)                                   */
    private static final int[] DR = {0, 1, 0, -1};
    private static final int[] DC = {1, 0, -1, 0};

    /* --------------------------------------------------------------------- */
    /*  Entry point                                                          */
    public static void main(String[] args) throws IOException {
        InputReader.init(System.in);
        PrintWriter out = new PrintWriter(System.out);

        int rows = input().nextInt();
        int cols = input().nextInt();

        char[][] board   = readBoard(rows);
        char[][] result  = new char[rows][cols];
        int[][]    degree = new int[rows][cols];

        initialise(result, degree, board, rows, cols);

        Queue<Position> pend = new ArrayDeque<>();

        /*  Put every empty cell that currently has exactly one free neighbour   */
        for (int r = 0; r < rows; ++r) {
            for (int c = 0; c < cols; ++c) {
                if (board[r][c] == '.' && degree[r][c] == 1) {
                    pend.add(new Position(r, c));
                }
            }
        }

        while (!pend.isEmpty()) {
            Position cur = pend.poll();

            int dir = findFreeNeighbour(cur.r, cur.c, board);
            if (dir == -1) {
                break;                     // should not happen for a valid instance
            }

            int nr = cur.r + DR[dir];
            int nc = cur.c + DC[dir];
            placeDomino(result, cur.r, cur.c, nr, nc, dir);
            propagateAndEnqueue(nr, nc, board, degree, pend);
        }

        if (isFullyTiled(result)) {
            for (char[] line : result) {
                out.println(new String(line));
            }
        } else {
            out.println("Not unique");
        }

        out.close();
    }

    /* --------------------------------------------------------------------- */
    /*  Helpers                                                               */

    /** Reads the board from the input stream. */
    private static char[][] readBoard(int rows) throws IOException {
        char[][] board = new char[rows][];
        for (int r = 0; r < rows; ++r) {
            String line = input().next();
            board[r] = line.toCharArray();
        }
        return board;
    }

    /** Initialise the result matrix, copy the board and compute initial degrees. */
    private static void initialise(char[][] result, int[][] degree, char[][] board,
                                   int rows, int cols) {
        for (int r = 0; r < rows; ++r) {
            for (int c = 0; c < cols; ++c) {
                result[r][c] = board[r][c];
                if (board[r][c] == '.') {
                    degree[r][c] = countFreeNeighbours(board, r, c, rows, cols);
                }
            }
        }
    }

    /** Returns how many of the four orthogonal neighbours are empty ('.'). */
    private static int countFreeNeighbours(char[][] board, int r, int c,
                                           int rows, int cols) {
        int cnt = 0;
        for (int d = 0; d < 4; ++d) {
            int nr = r + DR[d];
            int nc = c + DC[d];
            if (inBounds(nr, nc, rows, cols) && board[nr][nc] == '.') {
                cnt++;
            }
        }
        return cnt;
    }

    /** Simple bounds check. */
    private static boolean inBounds(int r, int c, int rows, int cols) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    /** Finds the direction of a free neighbour of (r,c). Returns -1 if none. */
    private static int findFreeNeighbour(int r, int c, char[][] board) {
        for (int d = 0; d < 4; ++d) {
            int nr = r + DR[d];
            int nc = c + DC[d];
            if (inBounds(nr, nc, board.length, board[0].length)
                    && board[nr][nc] == '.') {
                return d;
            }
        }
        return -1;
    }

    /** Places the two halves of a domino in the result matrix. */
    private static void placeDomino(char[][] result, int r1, int c1,
                                    int r2, int c2, int dir) {
        switch (dir) {
            case 0 -> {               // right
                result[r1][c1] = '<';
                result[r2][c2] = '>';
            }
            case 1 -> {               // down
                result[r1][c1] = '^';
                result[r2][c2] = 'v';
            }
            case 2 -> {               // left
                result[r1][c1] = '>';
                result[r2][c2] = '<';
            }
            case 3 -> {               // up
                result[r1][c1] = 'v';
                result[r2][c2] = '^';
            }
        }
    }

    /**
     * Decreases the degree of all empty neighbours of (r,c) and enqueues
     * newly‑created degree‑1 cells.
     */
    private static void propagateAndEnqueue(int r, int c, char[][] board,
                                            int[][] degree, Queue<Position> pend) {
        for (int d = 0; d < 4; ++d) {
            int nr = r + DR[d];
            int nc = c + DC[d];
            if (!inBounds(nr, nc, board.length, board[0].length)
                    || board[nr][nc] != '.') {
                continue;
            }
            degree[nr][nc]--;
            if (degree[nr][nc] == 1) {
                pend.add(new Position(nr, nc));
            }
        }
    }

    /** Returns true iff every cell of the result board is filled (no '.'). */
    private static boolean isFullyTiled(char[][] board) {
        for (char[] row : board) {
            for (char ch : row) {
                if (ch == '.') {
                    return false;
                }
            }
        }
        return true;
    }

    /* --------------------------------------------------------------------- */
    /*  Simple container for a row/column pair                               */
    private static final class Position {
        final int r;
        final int c;
        Position(int r, int c) {
            this.r = r;
            this.c = c;
        }
    }

    /* --------------------------------------------------------------------- */
    /*  Very small fast scanner                                              */
    public static final class InputReader {
        private static BufferedReader reader;
        private static StringTokenizer tokenizer;

        static void init(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
        }

        private static String nextToken() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                tokenizer = new StringTokenizer(reader.readLine());
            }
            return tokenizer.nextToken();
        }

        static String next() throws IOException {
            return nextToken();
        }

        static int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Refactored version of the original solution.
 *
 * <p>Key improvements:
 *
 * <ul>
 *   <li>Extracted constants and used expressive names instead of magic numbers.
 *   <li>Replaced fixed‑size auxiliary arrays with dynamic collections.
 *   <li>Separated concerns into small, focused methods.
 *   <li>Removed unused imports/classes and suppressed warnings that are no longer needed.
 *   <li>Used proper data structures (Queue, ArrayList) and generics.
 *   <li>Added clear comments and Javadoc where appropriate.
 * </ul>
 *
 * <p>The algorithm is unchanged – it reads a grid, detects forced moves,
 * propagates them and finally prints the tiled board or “Not unique”.
 */
public class Main {

    /** Direction vectors: down, right, up, left */
    private static final int[] DX = {1, 0, -1, 0};
    private static final int[] DY = {0, 1, 0, -1};

    private final InputReader ir;
    private final PrintWriter out;

    public Main(InputStream in) {
        this.ir = new InputReader(in);
        this.out = new PrintWriter(System.out, true);
    }

    /** Entry point used by the original program. */
    public void solve() {
        int rows = ir.readInt();
        int cols = ir.readInt();

        char[][] board = readBoard(rows);
        int[][] emptyNeighbourCount = countEmptyNeighbours(board);
        Queue<Pos> forced = collectForcedPositions(board, emptyNeighbourCount);

        assignAndPropagate(board, emptyNeighbourCount, forced);

        if (hasRemainingEmpty(board)) {
            out.println("Not unique");
            return;
        }

        printBoard(board);
    }

    /** Reads the board from the fast scanner. */
    private char[][] readBoard(int n) {
        char[][] board = new char[n][];
        for (int i = 0; i < n; i++) {
            board[i] = ir.readString().toCharArray();
        }
        return board;
    }

    /** Counts how many adjacent '.' cells each '.' cell has. */
    private int[][] countEmptyNeighbours(char[][] board) {
        int n = board.length;
        int m = board[0].length;
        int[][] cnt = new int[n][m];

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (board[i][j] == '*') {
                    continue;
                }
                int emptyAdj = 0;
                for (int d = 0; d < DX.length; d++) {
                    int ni = i + DX[d];
                    int nj = j + DY[d];
                    if (valid(ni, nj, n, m) && board[ni][nj] == '.') {
                        emptyAdj++;
                    }
                }
                cnt[i][j] = emptyAdj;
            }
        }
        return cnt;
    }

    /** Gathers all '.' cells that have exactly one empty neighbour – the “forced” cells. */
    private Queue<Pos> collectForcedPositions(char[][] board, int[][] cnt) {
        Queue<Pos> q = new ArrayDeque<>();
        for (int i = 0; i < board.length; i++) {
            for (int j = 0; j < board[i].length; j++) {
                if (board[i][j] != '.' || cnt[i][j] == 0) {
                    // 0 neighbours → impossible configuration
                    out.println("Not unique");
                    System.exit(0);
                }
                if (cnt[i][j] == 1) {
                    q.add(new Pos(i, j));
                }
            }
        }
        return q;
    }

    /**
     * Main propagation loop.
     *
     * <p>Repeatedly picks a forced cell, finds its unique free neighbour,
     * places a domino, updates neighbour counts and discovers new forced cells.
     */
    private void assignAndPropagate(char[][] board,
                                   int[][] cnt,
                                   Queue<Pos> queue) {
        while (!queue.isEmpty()) {
            Pos cur = queue.poll();
            if (board[cur.r][cur.c] != '.') {
                continue; // already processed
            }
            if (cnt[cur.r][cur.c] != 1) {
                continue; // no longer forced
            }

            int dir = findUniqueDirection(board, cnt, cur.r, cur.c);
            if (dir == -1) {
                // Should not happen if the earlier checks are correct
                out.println("Not unique");
                System.exit(0);
            }

            Pos neighbour = getNeighbour(cur.r, cur.c, dir);
            placeDomino(board, cur.r, cur.c, neighbour.r, neighbour.c, dir);

            // Decrease the neighbour count of the two cells just covered
            // and of all their adjacent empty cells.
            decreaseCountsAround(board, cnt, cur.r, cur.c);
            decreaseCountsAround(board, cnt, neighbour.r, neighbour.c);

            // Any cell that now has exactly one empty neighbour becomes forced.
            for (int dr = -1; dr <= 1; dr++) {
                for (int dc = -1; dc <= 1; dc++) {
                    int nr = cur.r + dr;
                    int nc = cur.c + dc;
                    if (valid(nr, nc, board.length, board[0].length)
                            && board[nr][nc] == '.' && cnt[nr][nc] == 1) {
                        queue.add(new Pos(nr, nc));
                    }
                    int nr2 = neighbour.r + dr;
                    int nc2 = neighbour.c + dc;
                    if (valid(nr2, nc2, board.length, board[0].length)
                            && board[nr2][nc2] == '.' && cnt[nr2][nc2] == 1) {
                        queue.add(new Pos(nr2, nc2));
                    }
                }
            }
        }
    }

    /** Returns the unique direction index (0‑3) that leads to an empty neighbour. */
    private int findUniqueDirection(char[][] board, int[][] cnt,
                                    int r, int c) {
        int[] matches = new int[DX.length];
        int matchIdx = 0;

        for (int d = 0; d < DX.length; d++) {
            int nr = r + DX[d];
            int nc = c + DY[d];
            if (valid(nr, nc, board.length, board[0].length)
                    && board[nr][nc] == '.') {
                matches[matchIdx++] = d;
            }
        }
        return (matchIdx == 1) ? matches[0] : -1;
    }

    /** Returns the neighbour cell in the given direction. */
    private Pos getNeighbour(int r, int c, int dir) {
        return new Pos(r + DX[dir], c + DY[dir]);
    }

    /** Places the appropriate characters representing a domino. */
    private void placeDomino(char[][] board,
                             int r1, int c1,
                             int r2, int c2,
                             int dir) {
        // dir == 1 → horizontal (right), dir == 0 → vertical (down)
        if (dir == 1) { // right
            board[r1][Math.min(c1, c2)] = '<';
            board[r1][Math.max(c1, c2)] = '>';
        } else { // down
            board[Math.min(r1, r2)][c1] = '^';
            board[Math.max(r1, r2)][c1] = 'v';
        }
    }

    /** Decrements the neighbour counts for the given cell and its empty neighbours. */
    private void decreaseCountsAround(char[][] board, int[][] cnt,
                                      int r, int c) {
        for (int d = 0; d < DX.length; d++) {
            int nr = r + DX[d];
            int nc = c + DY[d];
            if (valid(nr, nc, board.length, board[0].length) && board[nr][nc] == '.') {
                cnt[nr][nc]--;
                if (cnt[nr][nc] == 0) {
                    out.println("Not unique");
                    System.exit(0);
                }
            }
        }
    }

    /** Returns true if any '.' cell is left on the board. */
    private boolean hasRemainingEmpty(char[][] board) {
        for (char[] row : board) {
            for (char ch : row) {
                if (ch == '.') {
                    out.println("Not unique");
                    System.exit(0);
                }
            }
        }
        return true;
    }

    /** Prints the solved board. */
    private void printBoard(char[][] board) {
        StringBuilder sb = new StringBuilder();
        for (char[] row : board) {
            sb.append(row).append('\n');
        }
        out.print(sb.toString());
    }

    /** Simple helper class to store a position on the board. */
    private static final class Pos {
        final int r, c;
        Pos(int r, int c) {
            this.r = r;
            this.c = c;
        }
    }

    /** Very fast scanner used by the original code. */
    private static final class InputReader {
        private final InputStream stream;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        InputReader(InputStream stream) {
            this.stream = stream;
        }

        private int readByte() {
            if (ptr >= len) {
                len = stream.read(buffer);
                ptr = 0;
                if (len <= 0) {
                    return -1;
                }
            }
            return buffer[ptr++];
        }

        int readInt() {
            int c, sign = 1, val = 0;
            do {
                c = readByte();
            } while (c <= ' ' && c != -1);
            if (c == '-') {
                sign = -1;
                c = readByte();
            }
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = readByte();
            }
            return val * sign;
        }

        String readString() {
            StringBuilder sb = new StringBuilder();
            int c;
            do {
                c = readByte();
            } while (c <= ' ' && c != -1);
            while (c > ' ') {
                sb.append((char) c);
                c = readByte();
            }
            return sb.toString();
        }
    }

    /** Launches the solution. */
    public void run() {
        solve();
        out.close();
    }

    public static void main(String[] args) {
        new Main(System.in).run();
    }
}

import java.io.*;
import java.util.*;

/**
 * Entry point of the application.
 * Reads the whole input, delegates the processing to {@link TilePlacementSolver}
 * and prints the result.
 */
public class Main {

    public static void main(String[] args) {
        // Use System.in / System.out – they are passed to the solver for easy testing / mocking
        try (InputStream in = System.in;
             OutputStream out = System.out) {

            InputReader reader = new InputReader(in);
            PrintWriter writer = new PrintWriter(out);

            TilePlacementSolver solver = new TilePlacementSolver();
            solver.solve(reader, writer);
        }
    }
}

/**
 * Core logic for the “lightoj 1009 – Tiles” problem.
 * Keeps all mutable state inside the solver and works with a read‑only view
 * of the input.
 */
class TilePlacementSolver {

    /** Grid characters (mutable) */
    private char[][] grid;

    /** Dimensions of the grid */
    private final int rows;
    private final int columns;

    /** Queue that stores cells with exactly one free neighbour – drives the algorithm */
    private final Queue<Coord> pending = new ArrayDeque<>();

    /** Counter of still empty cells – used to detect incomplete covering */
    private int remainingEmptyCells;

    /**
     * Solves the problem for a single test case.
     *
     * @param reader  input reader (must be able to provide next int / next)
     * @param out     writer to which the result should be printed
     */
    public void solve(InputReader reader, PrintWriter out) {
        readDimensionsAndGrid(reader);
        initializeAlgorithm();

        processPendingCells();

        if (remainingEmptyCells > 0) {
            out.println("Not unique");
        } else {
            printSolution(out);
        }
    }

    /** Reads grid size and the grid itself from {@link InputReader}. */
    private void readDimensionsAndGrid(InputReader reader) {
        rows = reader.nextInt();
        columns = reader.nextInt();

        grid = new char[rows][];
        for (int i = 0; i < rows; i++) {
            grid[i] = reader.next().toCharArray();
        }

        // Count '.' cells – needed later to verify full coverage
        remainingEmptyCells = 0;
        for (char[] row : grid) {
            for (char cell : row) {
                if (cell == '.') {
                    remainingEmptyCells++;
                }
            }
        }
    }

    /** Finds all cells with exactly one adjacent '.' and adds them to the pending queue. */
    private void initializeAlgorithm() {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < columns; c++) {
                if (degree(r, c) == 1) {
                    pending.add(new Coord(r, c));
                }
            }
        }
    }

    /** Main loop – repeatedly take a cell with exactly one neighbour, pair it,
     * cover the pair, and update degrees of neighbours. */
    private void processPendingCells() {
        while (!pending.isEmpty()) {
            Coord cur = pending.remove();

            // The cell may have been already matched – skip it
            if (grid[cur.row][cur.column] != '.') {
                continue;
            }

            Coord neighbor = findAdjacentFree(cur);
            if (neighbor == null) {
                continue; // no partner → dead end, will be detected by remainingEmptyCells
            }

            // Mark the pair with the appropriate tile symbols
            coverPair(cur, neighbor);

            // Decrease the counter of still‑empty cells (two cells are now used)
            remainingEmptyCells -= 2;

            // Add newly created degree‑1 cells around the pair for further processing
            addNeighbourhoodIfDegreeOne(cur);
            addNeighbourhoodIfDegreeOne(neighbor);
        }
    }

    /** Returns a free adjacent cell to {@code cur} (up, down, left or right),
     * or {@code null} if none exists. */
    private Coord findAdjacentFree(Coord cur) {
        int[][] dirs = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};
        for (int[] d : dirs) {
            int nr = cur.row + d[0];
            int nc = cur.column + d[1];
            if (insideGrid(nr, nc) && grid[nr][nc] == '.') {
                return new Coord(nr, nc);
            }
        }
        return null;
    }

    /** Marks the two cells of a pair with the proper ASCII symbols
     * (horizontal → '<' and '>'; vertical ↓ → '^' and 'v'). */
    private void coverPair(Coord a, Coord b) {
        if (a.row == b.row) {                     // horizontal
            int minCol = Math.min(a.column, b.column);
            int maxCol = Math.max(a.column, b.column);
            grid[a.row][minCol] = '<';
            grid[b.row][maxCol] = '>';
        } else {                                   // vertical
            int minRow = Math.min(a.row, b.row);
            int maxRow = Math.max(a.row, b.row);
            grid[minRow][a.column] = '^';
            grid[maxRow][b.column] = 'v';
        }
    }

    /** For each neighbour of {@code c} that still has exactly one free neighbour,
     * add it to the pending queue. */
    private void addNeighbourhoodIfDegreeOne(Coord c) {
        for (int dr = -1; dr <= 1; dr++) {
            for (int dc = -1; dc <= 1; dc++) {
                if (Math.abs(dr) + Math.abs(dc) != 1) {
                    continue; // only orthogonal neighbours
                }
                int nr = c.row + dr;
                int nc = c.column + dc;
                if (insideGrid(nr, nc) && degree(nr, nc) == 1) {
                    pending.add(new Coord(nr, nc));
                }
            }
        }
    }

    /** Returns the degree (number of orthogonal free neighbours) of cell (r,c). */
    private int degree(int r, int c) {
        if (!insideGrid(r, c) || grid[r][c] != '.') {
            return 0;
        }
        int deg = 0;
        int[][] dirs = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};
        for (int[] d : dirs) {
            int nr = r + d[0];
            int nc = c + d[1];
            if (insideGrid(nr, nc) && grid[nr][nc] == '.') {
                deg++;
            }
        }
        return deg;
    }

    /** Simple helper for bounds checking. */
    private boolean insideGrid(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < columns;
    }

    /** Prints the fully solved grid to {@link PrintWriter}. */
    private void printSolution(PrintWriter out) {
        for (char[] row : grid) {
            out.println(new String(row));
        }
    }

    /** Minimal immutable pair of coordinates used throughout the algorithm. */
    private static final class Coord {
        final int row;
        final int column;

        Coord(int row, int column) {
            this.row = row;
            this.column = column;
        }
    }
}

/**
 * Very small utility class that reads tokens from an {@link InputStream}.
 * Functionality is identical to the original implementation but written
 * in a more self‑documenting style.
 */
class InputReader {

    private final BufferedReader reader;
    private StringTokenizer tokenizer;

    InputReader(InputStream stream) {
        this.reader = new BufferedReader(new InputStreamReader(stream), 32768);
    }

    /** Returns the next whitespace‑separated token, blocking until one is available. */
    String next() {
        while (tokenizer == null || !tokenizer.hasMoreTokens()) {
            try {
                tokenizer = new StringTokenizer(reader.readLine());
            } catch (IOException e) {
                throw new RuntimeException(e);
            }
        }
        return tokenizer.nextToken();
    }

    /** Convenience wrapper for {@link #next()} that parses an integer. */
    int nextInt() {
        return Integer.parseInt(next());
    }
}

import java.io.*;
import java.util.*;

/**
 * Solves a puzzle where a grid of '.' characters must be filled with
 * directional arrows (^, >, v, <) such that the final configuration is
 * unique. If any '.' remains unfilled, the solution is not unique.
 *
 * The algorithm works with a breadth‑first propagation of cells that have
 * exactly one adjacent empty neighbour. Those cells are forced to point
 * toward that neighbour, and the neighbour is filled with the opposite
 * direction. Repeating this process eventually either fills the whole
 * grid or discovers incompleteness.
 *
 * The implementation is deliberately split into small, well‑named methods
 * and uses clear naming, constants and encapsulation to improve
 * readability and maintainability.
 */
public class Solver {

    /** Direction indices – match the order used for the movement vectors. */
    private static final int UP = 0;
    private static final int RIGHT = 1;
    private static final int DOWN = 2;
    private static final int LEFT = 3;

    /** Movement vectors for the four directions. */
    private static final int[] DX = {-1, 0, 1, 0};
    private static final int[] DY = {0, 1, 0, -1};

    /** Arrow characters that correspond to the four directions (same order). */
    private static final char[] ARROW_CHARS = {'^', '>', 'v', '<'};

    /** Opposite direction index (used to fill the neighbour cell). */
    private static final int[] OPPOSITE = {DOWN, LEFT, UP, RIGHT};

    /** Character representation of the opposite direction for quick lookup. */
    private static final char[] OPPOSITE_ARROW = {'v', '<', '^', '>'};

    private final char[][] board;
    private final int rows;
    private final int cols;

    /** Queue used for the breadth‑first propagation of forced moves. */
    private final Queue<Position> queue = new ArrayDeque<>();

    /** Simple container for a grid coordinate. */
    private static final class Position {
        final int row;
        final int col;
        Position(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }

    /** Creates a new solver instance. */
    public Solver(char[][] board) {
        this.board = board;
        this.rows = board.length;
        this.cols = board[0].length;
    }

    /** Returns true if the given coordinate is inside the board and currently '.'. */
    private boolean isEmpty(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols && board[r][c] == '.';
    }

    /** Counts how many empty neighbours the cell (r,c) has. */
    private int countEmptyNeighbours(int r, int c) {
        int cnt = 0;
        for (int d = 0; d < 4; d++) {
            if (isEmpty(r + DX[d], c + DY[d])) {
                cnt++;
            }
        }
        return cnt;
    }

    /**
     * Determines the direction index that points from (r,c) to its unique empty neighbour.
     * Returns {@code null} if the neighbour count is not exactly one.
     */
    private Direction? findUniqueDirection(int r, int c) {
        int uniqueDir = -1;
        for (int d = 0; d < 4; d++) {
            int nr = r + DX[d];
            int nc = c + DY[d];
            if (!isEmpty(nr, nc)) {
                continue;
            }
            if (uniqueDir != -1) {           // more than one neighbour found
                return null;
            }
            uniqueDir = d;
        }
        return uniqueDir == -1 ? null : new Direction(uniqueDir);
    }

    /** Fills the board using the propagation algorithm described in the class comment. */
    public void solve() {
        // -----------------------------------------------------------------
        // 1️⃣  Initialise the queue with all forced cells (exactly one free neighbour)
        // -----------------------------------------------------------------
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (board[r][c] == '.' && countEmptyNeighbours(r, c) == 1) {
                    queue.add(new Position(r, c));
                }
            }
        }

        // -----------------------------------------------------------------
        // 2️⃣  Process the queue until empty
        // -----------------------------------------------------------------
        while (!queue.isEmpty()) {
            Position cur = queue.poll();
            int r = cur.row;
            int c = cur.col;

            // The cell may already have been filled by a previous step.
            if (board[r][c] != '.') {
                continue;
            }

            // Find the (only) direction we must point to.
            Direction? dir = findUniqueDirection(r, c);
            if (!dir.isPresent()) {
                continue;   // safety check – should not happen for queued cells
            }

            // Fill current cell with its arrow.
            board[r][c] = ARROW_CHARS[dir.getValue()];

            // Determine neighbour coordinates.
            int nr = r + DX[dir.getValue()];
            int nc = c + DY[dir.getValue()];

            // Fill the neighbour with the opposite arrow.
            board[nr][nc] = OPPOSITE_ARROW[dir.getValue()];

            // New cells that have become forced (exactly one neighbour) are enqueued.
            for (int d = 0; d < 4; d++) {
                int rr = nr + DX[d];
                int cc = nc + DY[d];
                if (isEmpty(rr, cc) && countEmptyNeighbours(rr, cc) == 1) {
                    queue.add(new Position(rr, cc));
                }
            }
        }
    }

    /** Checks whether any '.' cells remain; prints the appropriate result. */
    public void outputResult(PrintWriter out) {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (board[r][c] == '.') {
                    out.println("Not unique");
                    return;
                }
            }
        }

        // All cells filled – print the board.
        for (char[] row : board) {
            out.println(new String(row));
        }
    }

    /** Simple enum that wraps a direction index and its arrow character. */
    private enum Direction {
        UP('^', 0), RIGHT('>', 1), DOWN('v', 2), LEFT('<', 3);

        final char symbol;
        final int index;

        Direction(char symbol, int index) {
            this.symbol = symbol;
            this.index = index;
        }

        int getValue() {
            return index;
        }
    }

    /** Entry point – reads from stdin, solves, and writes to stdout. */
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        PrintWriter out = new PrintWriter(System.out);

        // ----- read dimensions -------------------------------------------------
        StringTokenizer st = new StringTokenizer(br.readLine());
        int n = Integer.parseInt(st.nextToken());
        int m = Integer.parseInt(st.nextToken());

        // ----- read board -------------------------------------------------------
        char[][] board = new char[n][m];
        for (int i = 0; i < n; i++) {
            char[] line = br.readLine().toCharArray();
            System.arraycopy(line, 0, board[i], 0, Math.min(line.length, m));
        }

        // ----- solve ------------------------------------------------------------
        Solver solver = new Solver(board);
        solver.solve();
        solver.outputResult(out);

        // ----- clean up ---------------------------------------------------------
        br.close();
        out.close();
    }
}

import java.io.*;
import java.util.*;
import java.util.stream.*;

/**
 * Solves the “Domino Tiling” problem (CF 515D).  
 * The algorithm fills the board with unique domino placements if possible,
 * otherwise prints “Not unique”.
 *
 * The refactor focuses on:
 *   • Clear separation of concerns (input, core algorithm, output)
 *   • Meaningful naming
 *   • Small helper methods
 *   • Defensive programming (final where possible)
 *   • Consistent coding style
 */
public class _515D {

    /* --------------------------------------------------------------------- */
    /*  Core data structures                                                    */
    /* --------------------------------------------------------------------- */

    /** One candidate for a domino half (i.e. a cell that currently has degree 1). */
    private static final class Cell {
        final int row;
        final int col;
        final int degree;               // always 1 for cells placed in the queue

        Cell(int row, int col, int degree) {
            this.row = row;
            this.col = col;
            this.degree = degree;
        }
    }

    /** Direction vectors used to explore the four orthogonal neighbours. */
    private static final int[][] DIRS = {{-1, 0}, {0, -1}, {0, 1}, {1, 0}};

    /* --------------------------------------------------------------------- */
    /*  Public entry point                                                       */
    /* --------------------------------------------------------------------- */

    public void solve() throws IOException {
        try (InputStream in = System.in) {
            new InputReader(in).process();
        }
    }

    /* --------------------------------------------------------------------- */
    /*  Core algorithm                                                         */
    /* --------------------------------------------------------------------- */

    private void process() throws IOException {
        int rows = nextInt();
        int cols = nextInt();
        char[][] board = readBoard(rows);

        // The algorithm works on a mutable copy of the board.
        char[][] result = deepCopy(board);

        // visited[r][c] == true  → cell already belongs to a placed domino
        boolean[][] visited = new boolean[rows][cols];
        // degree[r][c] = number of still‑free neighbours of (r,c)
        int[][] degree = new int[rows][cols];

        // Queue of cells that currently have exactly one free neighbour.
        PriorityQueue<Cell> queue = new PriorityQueue<>(Comparator.comparingInt(c -> c.degree));

        // --------------------------------------------------------------
        // 1. Initialise degree information and fill the queue.
        // --------------------------------------------------------------
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (board[r][c] == '*') {
                    continue;                     // blocked cells are ignored
                }
                List<Cell> freeNeighbours = countFreeNeighbours(r, c, visited);
                degree[r][c] = freeNeighbours.size();

                if (degree[r][c] == 0) {
                    System.out.println("Not unique");
                    return;
                }
                if (degree[r][c] == 1) {
                    queue.add(new Cell(r, c, degree[r][c]));
                }
            }
        }

        // --------------------------------------------------------------
        // 2. Process the queue until it is empty.
        // --------------------------------------------------------------
        while (!queue.isEmpty()) {
            Cell cur = queue.poll();

            // Stale entry? (degree changed or already visited)
            if (cur.degree != degree[cur.row][cur.col] || visited[cur.row][cur.col]) {
                continue;
            }

            visited[cur.row][cur.col] = true;
            List<Cell> neighbours = countFreeNeighbours(cur.row, cur.col, visited);

            // A degree‑1 cell must have exactly one free neighbour.
            assert neighbours.size() == 1;
            Cell next = neighbours.get(0);
            placeDomino(result, cur.row, cur.col, next.row, next.col);
            visited[next.row][next.col] = true;

            // Decrease degree of the remaining neighbours of `next`.
            for (Cell adj : freeNeighboursOf(next.row, next.col, visited)) {
                if (!visited[adj.row][adj.col]) {
                    degree[adj.row][adj.col]--;
                    if (degree[adj.row][adj.col] == 1) {
                        queue.add(new Cell(adj.row, adj.col, degree[adj.row][adj.col]));
                    }
                }
            }
        }

        // --------------------------------------------------------------
        // 3. Validate that every free cell has been matched.
        // --------------------------------------------------------------
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (!visited[r][c] && board[r][c] == '.') {
                    System.out.println("Not unique");
                    return;
                }
            }
        }

        // --------------------------------------------------------------
        // 4. Output the filled board.
        // --------------------------------------------------------------
        StringBuilder out = new StringBuilder();
        for (char[] r : result) {
            out.append(r).append('\n');
        }
        System.out.print(out.toString());
    }

    /* --------------------------------------------------------------------- */
    /*  Helper methods                                                          */
    /* --------------------------------------------------------------------- */

    /** Returns a list of all orthogonal neighbours of (r,c) that are free ('.') and not yet visited. */
    private List<Cell> countFreeNeighbours(int r, int c, boolean[][] visited) {
        List<Cell> list = new ArrayList<>();
        for (int[] d : DIRS) {
            int nr = r + d[0];
            int nc = c + d[1];
            if (isInBounds(nr, nc, rows, cols) && board[nr][nc] == '.' && !visited[nr][nc]) {
                list.add(new Cell(nr, nc, 0));
            }
        }
        return list;
    }

    /** Returns the set of neighbours of (r,c) that are still free (used when updating degrees). */
    private List<Cell> freeNeighboursOf(int r, int c, boolean[][] visited) {
        List<Cell> list = new ArrayList<>();
        for (int[] d : DIRS) {
            int nr = r + d[0];
            int nc = c + d[1];
            if (isInBounds(nr, nc, rows, cols) && board[nr][nc] == '.' && !visited[nr][nc]) {
                list.add(new Cell(nr, nc, 0));
            }
        }
        return list;
    }

    /** Places the two halves of a domino on the result board according to their relative positions. */
    private void placeDomino(char[][] board, int r1, int c1, int r2, int c2) {
        if (r1 == r2) {                     // horizontal domino
            if (c1 < c2) {
                board[r1][c1] = '<';
                board[r2][c2] = '>';
            } else {
                board[r1][c1] = '>';
                board[r2][c2] = '<';
            }
        } else {                            // vertical domino
            if (r1 < r2) {
                board[r1][c1] = '^';
                board[r2][c2] = 'v';
            } else {
                board[r1][c1] = 'v';
                board[r2][c2] = '^';
            }
        }
    }

    /** Checks array bounds. */
    private boolean isInBounds(int i, int j, int rows, int cols) {
        return i >= 0 && i < rows && j >= 0 && j < cols;
    }

    /** Makes a deep copy of the original board. */
    private static char[][] deepCopy(char[][] src) {
        char[][] dst = new char[src.length][];
        for (int i = 0; i < src.length; i++) {
            dst[i] = src[i].clone();
        }
        return dst;
    }

    /** Reads `rows` lines of input, each representing a board row. */
    private char[][] readBoard(int rows) throws IOException {
        char[][] board = new char[rows][];
        for (int i = 0; i < rows; i++) {
            String line = nextLine();
            board[i] = line.toCharArray();
        }
        return board;
    }

    /* --------------------------------------------------------------------- */
    /*  Input handling                                                          */
    /* --------------------------------------------------------------------- */

    /** Simple wrapper around BufferedReader that tokenises input lines. */
    private final class InputReader implements Iterable<String> {
        private final BufferedReader br;

        InputReader(InputStream source) {
            this.br = new BufferedReader(new InputStreamReader(source));
        }

        /** Returns the next integer token from the input stream. */
        int nextInt() throws IOException {
            return Integer.parseInt(nextToken());
        }

        /** Returns the next complete line (including spaces). */
        String nextLine() throws IOException {
            String line;
            do {
                line = br.readLine();
            } while (line == null && !line.isBlank()); // skip empty lines if any
            return line;
        }

        /** Returns the next non‑empty token (space‑separated). */
        String nextToken() throws IOException {
            while (true) {
                String token = br.readLine();
                if (token == null) {
                    return null;
                }
                String trimmed = token.trim();
                if (!trimmed.isEmpty()) {
                    return trimmed;
                }
            }
        }
    }
    /* --------------------------------------------------------------------- */
    /*  Main method                                                              */
    /* --------------------------------------------------------------------- */

    /** Entry point – forwards to the solving routine. */
    public static void main(String[] args) throws IOException {
        new _515D().solve();
    }
}

import java.util.*;

public class B {

    /* Directions: down, right, up, left */
    private static final int[] DR = {1, 0, -1, 0};
    private static final int[] DC = {0, 1, 0, -1};

    /* Character used for the current cell and its neighbour when a pipe is placed */
    private static final char[] SOURCE_ARROWS = {'^', '<', 'v', '>'};
    private static final char[] TARGET_ARROWS  = {'v', '>', '^', '<'};

    private final Scanner scanner;
    private final StringBuilder output;

    public B() throws Exception {
        scanner = new Scanner(System.in);
        output = new StringBuilder();

        int rows = scanner.nextInt();
        int cols = scanner.nextInt();
        char[][] grid = new char[rows][];
        for (int r = 0; r < rows; r++) {
            grid[r] = scanner.next().toCharArray();
        }

        solve(rows, cols, grid);
        System.out.print(output);
    }

    /** Core solving routine */
    private void solve(int R, int C, char[][] map) {
        int remainingEmpty = 0;
        int[][] degree = new int[R][C];
        Queue<Integer> queue = new ArrayDeque<>();

        /* ---- Initial scan --------------------------------------------------- */
        for (int r = 0; r < R; r++) {
            for (int c = 0; c < C; c++) {
                if (map[r][c] != '.') {
                    continue;                     // not an empty cell
                }
                remainingEmpty++;

                int cnt = 0;                        // number of adjacent empty cells
                for (int d = 0; d < 4; d++) {
                    int nr = r + DR[d];
                    int nc = c + DC[d];
                    if (isInside(nr, nc, R, C) && map[nr][nc] == '.') {
                        cnt++;
                    }
                }
                degree[r][c] = cnt;

                if (cnt == 1) {                     // forced placement starter
                    queue.add(r);
                    queue.add(c);
                }
            }
        }

        /* ---- Propagate forced placements ------------------------------------ */
        while (!queue.isEmpty()) {
            int r = queue.poll();
            int c = queue.poll();

            for (int d = 0; d < 4; d++) {
                int nr = r + DR[d];
                int nc = c + DC[d];
                if (!isInside(nr, nc, R, C) || map[nr][nc] != '.') {
                    continue;                     // not a valid empty neighbour
                }

                // Place the pipe that connects (r,c) -> (nr,nc)
                map[r][c] = SOURCE_ARROWS[d];
                map[nr][nc] = TARGET_ARROWS[d];
                remainingEmpty -= 2;

                // Update degrees of neighbours of the newly placed pipe
                for (int nd = 0; nd < 4; nd++) {
                    int ar = nr + DR[nd];
                    int ac = nc + DC[nd];
                    if (!isInside(ar, ac, R, C) || map[ar][ac] != '.') {
                        continue;
                    }
                    degree[ar][ac]--;
                    if (degree[ar][ac] == 1) {
                        queue.add(ar);
                        queue.add(ac);
                    }
                }
                break;   // a forced cell has exactly one free neighbour
            }
        }

        /* ---- Output the result --------------------------------------------- */
        if (remainingEmpty > 0) {
            output.append("Not unique\n");
        } else {
            for (char[] row : map) {
                output.append(row);
                output.append('\n');
            }
        }
    }

    /** Helper to check whether (r,c) lies inside the grid */
    private boolean isInside(int r, int c, int rows, int cols) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    /* debugging helper – harmless but kept for compatibility */
    private static void debug(Object... arr) {
        System.err.println(Arrays.deepToString(arr));
    }

    public static void main(String[] args) throws Exception {
        new B();
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.LinkedList;
import java.util.Queue;
import java.util.StringTokenizer;

/**
 * Refactored solution for the “unique tiling” problem.
 *
 * <p>Reads a grid that contains:
 * <ul>
 *   <li>'.' – empty cell</li>
 *   <li>'*' – obstacle</li>
 * </ul>
 *
 * <p>For every empty cell the program computes how many neighbouring empty cells exist.
 * Cells with exactly one free neighbour (leaf cells) are processed first; the unique
 * direction is written into the grid using arrow symbols. The process repeats until
 * no leaf cells remain. If any empty cell ('.') is left after processing, the solution
 * is not unique; otherwise the filled grid is printed.
 *
 * <p>The refactor improves readability, separation of concerns and overall maintainability
 * while preserving the original algorithmic behaviour.
 */
public class Main {

    /** Directions: up, down, left, right */
    private enum Direction {
        UP(-1, 0, '^', 'v'),
        DOWN(1, 0, 'v', '^'),
        LEFT(0, -1, '<', '>'),
        RIGHT(0, 1, '>', '<');

        final int dx, dy;
        final char selfArrow;   // arrow placed on the leaf cell
        final char neighborArrow; // arrow placed on the neighbour cell

        Direction(int dx, int dy, char selfArrow, char neighborArrow) {
            this.dx = dx;
            this.dy = dy;
            this.selfArrow = selfArrow;
            this.neighborArrow = neighborArrow;
        }
    }

    /** Simple container for a cell position */
    private static final class Cell {
        final int row;
        final int col;

        Cell(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }

    public static void main(String[] args) throws IOException {
        /* ----- Input handling ------------------------------------------------- */
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(System.in))) {
            StringBuilder output = new StringBuilder();

            StringTokenizer tokenizer = new StringTokenizer(reader.readLine());
            int rows = Integer.parseInt(tokenizer.nextToken());
            int cols = Integer.parseInt(tokenizer.nextToken());

            char[][] grid = new char[rows][];
            for (int r = 0; r < rows; r++) {
                grid[r] = reader.readLine().toCharArray();
            }

            /* ----- Core algorithm ----------------------------------------------- */
            int[][] degree = computeDegrees(grid);
            processLeaves(grid, degree);

            /* ----- Uniqueness check & output ----------------------------------- */
            if (!isFullyCovered(grid)) {
                output.append("Not unique");
            } else {
                for (char[] line : grid) {
                    output.append(line).append('\n');
                }
            }

            System.out.print(output);
        }
    }

    /** Calculates the degree (number of free neighbours) for every non‑'*' cell. */
    private static int[][] computeDegrees(char[][] grid) {
        int rows = grid.length;
        int cols = grid[0].length;
        int[][] degree = new int[rows][cols];

        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '*') {
                    continue;
                }
                int count = 0;
                for (Direction dir : Direction.values()) {
                    int nr = r + dir.dx;
                    int nc = c + dir.dy;
                    if (isInBounds(nr, nc, rows, cols) && grid[nr][nc] != '*') {
                        count++;
                    }
                }
                degree[r][c] = count;
            }
        }
        return degree;
    }

    /** Repeatedly removes leaf cells (degree == 1) and propagates the unique arrow. */
    private static void processLeaves(char[][] grid, int[][] degree) {
        Queue<Cell> queue = new LinkedList<>();

        // Enqueue all current leaves
        for (int r = 0; r < grid.length; r++) {
            for (int c = 0; c < grid[0].length; c++) {
                if (grid[r][c] == '.' && degree[r][c] == 1) {
                    queue.add(new Cell(r, c));
                }
            }
        }

        while (!queue.isEmpty()) {
            Cell leaf = queue.remove();

            // Find the only neighbour that is still empty ('.')
            Direction dir = findOnlyAvailableDirection(leaf.row, leaf.col, grid, degree);
            if (dir == null) {
                continue; // safety guard – should not happen in valid instances
            }

            // Place arrows on both cells
            grid[leaf.row][leaf.col] = dir.selfArrow;
            int nxtRow = leaf.row + dir.dx;
            int nxtCol = leaf.col + dir.dy;
            grid[nxtRow][nxtCol] = dir.neighborArrow;

            // Decrease degree of neighbours of the neighbour cell
            for (Direction nextDir : Direction.values()) {
                int adjRow = nxtRow + nextDir.dx;
                int adjCol = nxtCol + nextDir.dy;
                if (isInBounds(adjRow, adjCol, grid.length, grid[0].length)
                        && grid[adjRow][adjCol] == '.') {
                    degree[adjRow][adjCol]--;
                    if (degree[adjRow][adjCol] == 1) {
                        queue.add(new Cell(adjRow, adjCol));
                    }
                }
            }
        }
    }

    /**
     * Returns the single direction whose neighbour cell is still '.'.
     * If more than one such direction exists (or none) returns {@code null}.
     */
    private static Direction findOnlyAvailableDirection(int r, int c,
                                                          char[][] grid,
                                                          int[][] degree) {
        Direction[] candidates = new Direction[4];
        int candidateCount = 0;

        for (Direction dir : Direction.values()) {
            int nr = r + dir.dx;
            int nc = c + dir.dy;
            if (isInBounds(nr, nc, grid.length, grid[0].length)
                    && grid[nr][nc] == '.') {
                candidates[candidateCount++] = dir;
            }
        }

        return candidateCount == 1 ? candidates[0] : null;
    }

    /** Checks whether the grid contains any '.' characters after processing. */
    private static boolean isFullyCovered(char[][] grid) {
        for (char[] row : grid) {
            for (char cell : row) {
                if (cell == '.') {
                    return false;
                }
            }
        }
        return true;
    }

    /** Utility to verify array bounds. */
    private static boolean isInBounds(int r, int c, int rows, int cols) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }
}

import java.io.*;
import java.util.*;

/**
 * Refactored version of the original “tile‑covering” solver.
 * The program reads a rectangular board consisting of '.' (free) and
 * '#' (blocked) cells, tries to cover all '.' cells with arrows that
 * point to an adjacent free cell, and prints a unique tiling or
 * “Not unique”.
 */
public class Main {

    /** Direction of movement together with the arrow characters that
     *  must be written on the two cells of the domino. */
    private enum Direction {
        RIGHT(1, 0, '<', '>'),   // move right  (dx = +1)
        DOWN (0, 1, '^', 'v'),   // move down (dx = 0, dy = +1)
        LEFT(-1, 0, '>', '<'),   // move left (dx = -1)
        UP  (0, -1, 'v', '^');   // move up   (dx = 0, dy = -1)

        final int dx;          // column delta
        final int dy;          // row delta
        final char startChar;  // character placed on the current cell
        final char endChar;    // character placed on the neighbour

        Direction(int dx, int dy, char startChar, char endChar) {
            this.dx = dx;
            this.dy = dy;
            this.startChar = startChar;
            this.endChar = endChar;
        }

        /** Returns the direction that matches the supplied deltas. */
        static Direction fromDeltas(int dx, int dy) {
            for (Direction d : values()) {
                if (d.dx == dx && d.dy == dy) {
                    return d;
                }
            }
            return null;
        }
    }

    /** Simple holder for neighbour‑information used during the scan. */
    private static final class NeighborInfo {
        final int emptyNeighbourCount;
        final Direction direction;   // direction that leads to the only empty neighbour

        NeighborInfo(int emptyNeighbourCount, Direction direction) {
            this.emptyNeighbourCount = emptyNeighbourCount;
            this.direction = direction;
        }
    }

    /** Position of a cell together with the direction that forced it into the queue. */
    private static final class Cell {
        final int row;
        final int col;
        final Direction dir;   // direction that points to the unique empty neighbour

        Cell(int row, int col, Direction dir) {
            this.row = row;
            this.col = col;
            this.dir = dir;
        }
    }

    /** Returns true if (r,c) lies inside the board. */
    private static boolean inside(int r, int c, int n, int m) {
        return r >= 0 && r < n && c >= 0 && c < m;
    }

    /** Counts empty neighbours of (r,c) and returns the direction that leads to the only one,
     *  or a count of 0 if there is none / more than one. */
    private static NeighborInfo countEmptyNeighbours(char[][] board, int r, int c, int n, int m) {
        int cnt = 0;
        Direction dir = null;
        for (Direction d : Direction.values()) {
            int nr = r + d.dy;
            int nc = c + d.dx;
            if (inside(nr, nc, n, m) && board[nr][nc] == '.') {
                cnt++;
                dir = d;
            }
        }
        return new NeighborInfo(cnt, dir);
    }

    /** Writes the appropriate arrow characters on the board for a domino that starts
     *  at (r,c) and points in {@code dir}. */
    private static void placeTile(char[][] board, int r, int c, Direction dir) {
        board[r][c] = dir.startChar;
        int nr = r + dir.dy;
        int nc = c + dir.dx;
        board[nr][nc] = dir.endChar;
    }

    /** Inspects a cell and, if it has exactly one empty neighbour, enqueues it. */
    private static void enqueueIfLeaf(char[][] board, int r, int c,
                                      Queue<Cell> queue, int n, int m) {
        if (!inside(r, c, n, m) || board[r][c] != '.') {
            return;
        }
        NeighborInfo info = countEmptyNeighbours(board, r, c, n, m);
        if (info.emptyNeighbourCount == 1 && info.direction != null) {
            queue.add(new Cell(r, c, info.direction));
        }
    }

    /** Main processing loop – repeatedly picks a “leaf” cell (degree‑1) and forces a tile,
     *  then re‑evaluates its neighbours. */
    private static void processQueue(Queue<Cell> queue,
                                     char[][] board,
                                     int[] remainingSpaces) {
        while (!queue.isEmpty() && remainingSpaces[0] > 0) {
            Cell cell = queue.poll();
            // sanity check – the cells may have been filled by a previous step
            if (board[cell.row][cell.col] != '.' ||
                board[cell.row + cell.dir.dy][cell.col + cell.dir.dx] != '.') {
                continue;
            }
            placeTile(board, cell.row, cell.col, cell.dir);
            remainingSpaces[0] -= 2;                     // two cells are now occupied

            // the two cells that now have a fixed arrow may have become leaves themselves
            enqueueIfLeaf(board,
                          cell.row + cell.dir.dy,
                          cell.col + cell.dir.dx,
                          queue,
                          board.length,
                          board[0].length);
            enqueueIfLeaf(board,
                          cell.row,
                          cell.col,
                          queue,
                          board.length,
                          board[0].length);
        }
    }

    /** Builds the final output string from the filled board. */
    private static String buildOutput(char[][] board) {
        StringBuilder sb = new StringBuilder();
        for (char[] row : board) {
            for (char ch : row) {
                sb.append(ch);
            }
            sb.append('\n');
        }
        return sb.toString();
    }

    /** Entry point – reads the board, searches for forced moves, and prints the result. */
    public static void main(String[] args) throws IOException {
        /* ---------- input reading ---------- */
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
        String firstLine = reader.readLine();
        if (firstLine == null) {
            return;
        }
        String[] firstTokens = firstLine.trim().split("\\s+");
        int n = Integer.parseInt(firstTokens[0]);
        int m = Integer.parseInt(firstTokens[1]);

        char[][] board = new char[n][];
        int emptyCellCount = 0;

        for (int i = 0; i < n; i++) {
            String line = reader.readLine();
            if (line == null) {
                break;
            }
            board[i] = line.trim().toCharArray();
            for (int j = 0; j < m; j++) {
                if (board[i][j] == '.') {
                    emptyCellCount++;
                }
            }
        }

        /* ---------- initial queue population ---------- */
        Queue<Cell> queue = new ArrayDeque<>();
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (board[i][j] != '.') {
                    continue;
                }
                NeighborInfo info = countEmptyNeighbours(board, i, j, n, m);
                if (info.emptyNeighbourCount == 1) {
                    queue.add(new Cell(i, j, info.direction));
                }
            }
        }

        /* ---------- core algorithm ---------- */
        int[] remainingSpaces = new int[]{emptyCellCount};
        processQueue(queue, board, remainingSpaces);

        /* ---------- output ---------- */
        if (remainingSpaces[0] == 0) {
            System.out.print(buildOutput(board));
        } else {
            System.out.println("Not unique");
        }
    }
}

import java.io.*;
import java.util.StringTokenizer;

/**
 * Reads a board consisting of '.' (empty) and '#' (blocked) cells.
 * For every empty cell that has exactly one empty neighbour a domino
 * (pair of adjacent cells) is placed using the characters
 *   '>' , '<'  – horizontal orientation
 *   'v' , '^'  – vertical orientation
 * If all empty cells can be paired uniquely the resulting board is printed,
 * otherwise the program prints "Not unique".
 *
 * The algorithm has been refactored for readability, proper encapsulation
 * and meaningful naming.
 */
public class TileAssigner {

    // Directions: down, up, right, left
    private static final int[] DX = {1, -1, 0, 0};
    private static final int[] DY = {0, 0, 1, -1};

    /** Board that is being processed. */
    private final char[][] board;
    /** Number of rows. */
    private final int rows;
    /** Number of columns. */
    private final int cols;

    public TileAssigner(char[][] board) {
        this.board = board;
        this.rows = board.length;
        this.cols = board[0].length;
    }

    /** Executes the tiling algorithm. */
    public void solve() {
        // Keep trying to resolve forced moves until none remain.
        boolean changed = true;
        while (changed) {
            changed = false;
            for (int r = 0; r < rows; ++r) {
                for (int c = 0; c < cols; ++c) {
                    if (board[r][c] == '.') {
                        explore(r, c);
                        changed = true;          // a placement happened, restart scan
                    }
                }
            }
        }

        // If any empty cell persists, the tiling is not unique.
        if (hasEmptyCell()) {
            System.out.println("Not unique");
        } else {
            printBoard();
        }
    }

    /** Number of orthogonal neighbours that are still empty. */
    private int degree(int x, int y) {
        int count = 0;
        for (int d = 0; d < 4; ++d) {
            int nx = x + DX[d];
            int ny = y + DY[d];
            if (inBounds(nx, ny) && board[nx][ny] == '.') {
                ++count;
            }
        }
        return count;
    }

    /**
     * Attempts to pair the current empty cell with its unique empty neighbour.
     * The pairing is placed directly on the board.
     */
    private void explore(int x, int y) {
        // Cell may already have been filled by a previous step.
        if (board[x][y] != '.') {
            return;
        }

        int d = degree(x, y);
        if (d != 1) {
            // No forced partner → cannot guarantee a unique tiling.
            return;
        }

        // Locate the only empty neighbour.
        int nx = -1, ny = -1;
        for (int dir = 0; dir < 4; ++dir) {
            int tx = x + DX[dir];
            int ty = y + DY[dir];
            if (inBounds(tx, ty) && board[tx][ty] == '.') {
                nx = tx;
                ny = ty;
                break;
            }
        }
        if (nx == -1) {
            return; // safety check
        }

        assignOrientation(x, y, nx, ny);

        // Continue searching from both cells of the newly placed domino.
        explore(x, y);
        explore(nx, ny);
    }

    /** Writes the appropriate tile characters for the two adjacent cells. */
    private void assignOrientation(int x, int y, int nx, int ny) {
        if (nx == x) { // horizontal domino
            if (ny < y) { // neighbour is on the left
                board[x][y] = '>';
                board[nx][ny] = '<';
            } else { // neighbour is on the right
                board[x][y] = '<';
                board[nx][ny] = '>';
            }
        } else { // vertical domino
            if (nx < x) { // neighbour is above
                board[x][y] = 'v';
                board[nx][ny] = '^';
            } else { // neighbour is below
                board[x][y] = '^';
                board[nx][ny] = 'v';
            }
        }
    }

    private boolean inBounds(int x, int y) {
        return x >= 0 && x < rows && y >= 0 && y < cols;
    }

    /** Returns true if at least one empty cell remains on the board. */
    private boolean hasEmptyCell() {
        for (int r = 0; r < rows; ++r) {
            for (int c = 0; c < cols; ++c) {
                if (board[r][c] == '.') {
                    return true;
                }
            }
        }
        return false;
    }

    /** Prints the resulting board to standard output. */
    private void printBoard() {
        StringBuilder out = new StringBuilder();
        for (int r = 0; r < rows; ++r) {
            for (int c = 0; c < cols; ++c) {
                out.append(board[r][c]);
            }
            out.append('\n');
        }
        System.out.print(out.toString());
    }

    /** Fast scanner based on BufferedReader (mirrors original Reader utilities). */
    private static final class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner(BufferedReader br) {
            this.br = br;
        }

        String next() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                st = new StringTokenizer(br.readLine());
            }
            return st.nextToken();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }

    public static void main(String[] args) throws IOException {
        FastScanner fs = new FastScanner(new BufferedReader(new InputStreamReader(System.in)));

        int rows = fs.nextInt();
        int cols = fs.nextInt();
        char[][] grid = new char[rows][];
        for (int i = 0; i < rows; ++i) {
            grid[i] = fs.next().toCharArray();
        }

        new TileAssigner(grid).solve();
    }
}

import java.io.*;
import java.util.*;

public class DrazilTileSolver {

    /** constant used when the solution is not unique or impossible */
    private static final String NOT_UNIQUE = "Not unique";

    /** directions: up, left, down, right */
    private static final int[] DX = {-1, 0, 1, 0};
    private static final int[] DY = {0, -1, 0, 1};

    /** input reader and output writer */
    private static BufferedReader br;
    private static PrintWriter out;

    /** board dimensions and the board itself */
    private static int rows, cols;
    private static char[][] board;

    /** queue used for the forced‑placement phase */
    private static final int MAX = 250_000;               // maximum possible cells
    private static final int[] qx = new int[MAX];
    private static final int[] qy = new int[MAX];
    private static int qFront, qBack;

    /** --------------------------------------------------------------------- */
    /** Entry point */
    public static void main(String[] args) throws IOException {
        try (InputStream in = System.in) {
            initializeStreams(in);
            readInput();
            if (!solve()) {
                // solver already printed the answer (either board or NOT_UNIQUE)
                return;
            }
        }
    }

    /** --------------------------------------------------------------------- */
    /** Sets up input / output streams */
    private static void initializeStreams(InputStream source) throws IOException {
        br = new BufferedReader(new InputStreamReader(source, 32768));
        out = new PrintWriter(System.out, true);
    }

    /** --------------------------------------------------------------------- */
    /** Reads the whole input and stores it in the static fields */
    private static void readInput() throws IOException {
        rows = Integer.parseInt(nextToken());
        cols = Integer.parseInt(nextToken());
        board = new char[rows][cols];
        for (int r = 0; r < rows; ++r) {
            board[r] = nextToken().toCharArray();
        }
    }

    /** --------------------------------------------------------------------- */
    /** Reads the next token from the BufferedReader */
    private static String nextToken() throws IOException {
        while (true) {
            StringBuilder sb = new StringBuilder();
            String token = br.readLine();
            if (token == null) return null;
            StringTokenizer st = new StringTokenizer(token);
            if (st.hasMoreTokens()) {
                return st.nextToken();
            }
        }
    }

    /** --------------------------------------------------------------------- */
    /** Main solving routine. Returns true if a unique solution exists,
     *  prints the solution or “Not unique” otherwise. */
    private static boolean solve() {
        // -----------------------------------------------------------------
        // 1. Quick impossibility checks
        // -----------------------------------------------------------------
        int emptyCount = countEmptyCells();
        if (emptyCount % 2 != 0) {
            println(NOT_UNIQUE);
            return false;
        }
        if (emptyCount == 0) {
            printBoard();
            return true; // everything already filled, unique by definition
        }

        // -----------------------------------------------------------------
        // 2. Forced‑placement phase using a BFS‑like queue
        // -----------------------------------------------------------------
        if (!processForcedPlacements()) {
            println(NOT_UNIQUE);
            return false;
        }

        // -----------------------------------------------------------------
        // 3. Verify that no empty cells remain
        // -----------------------------------------------------------------
        if (hasRemainingEmpty()) {
            println(NOT_UNIQUE);
            return false;
        }

        // -----------------------------------------------------------------
        // 4. Uniqueness check – count solutions up to 2
        // -----------------------------------------------------------------
        int solutionCount = countSolutions();
        if (solutionCount > 1) {
            println(NOT_UNIQUE);
            return false;
        }
        // At this point we have exactly one valid tiling already drawn on the board
        printBoard();
        return true;
    }

    /** --------------------------------------------------------------------- */
    /** Counts the number of '.' cells on the board */
    private static int countEmptyCells() {
        int cnt = 0;
        for (int r = 0; r < rows; ++r) {
            for (int c = 0; c < cols; ++c) {
                if (board[r][c] == '.') cnt++;
            }
        }
        return cnt;
    }

    /** --------------------------------------------------------------------- */
    /** Processes forced placements. Returns false if an inconsistency is found. */
    private static boolean processForcedPlacements() {
        qFront = qBack = 0;

        // first scan – enqueue any empty cell that currently has exactly one neighbour
        for (int r = 0; r < rows; ++r) {
            for (int c = 0; c < cols; ++c) {
                if (board[r][c] == '.') {
                    int neighbours = countEmptyNeighbours(r, c);
                    if (neighbours == 0) {
                        return false; // dead end – impossible configuration
                    }
                    if (neighbours == 1) {
                        qx[qBack] = r;
                        qy[qBack] = c;
                        qBack++;
                    }
                }
            }
        }

        // main loop – repeatedly pick a forced cell and tile it
        while (qFront < qBack) {
            int x = qx[qFront++];
            int y = qy[qBack];

            if (board[x][y] != '.') {
                continue; // already filled by a previous forced step
            }

            // must have exactly one empty neighbour now (otherwise something went wrong)
            int chosenDir = -1;
            int nx = -1, ny = -1;
            char selfChar, otherChar;

            // try all four directions, pick the first valid neighbour
            for (int d = 0; d < 4; ++d) {
                int tx = x + DX[d];
                int ty = y + DY[d];
                if (tx < 0 || tx >= rows || ty < 0 || ty >= cols) continue;
                if (board[tx][ty] != '.') continue;

                // determine the two characters that will be placed
                switch (d) {
                    case 0 -> { // up
                        selfChar = 'v'; otherChar = '^';
                        nx = tx; ny = ty;
                        break;
                    case 1 -> { // left
                        selfChar = '>'; otherChar = '<';
                        nx = tx; ny = ty;
                        break;
                    case 2 -> { // down
                        selfChar = '^'; otherChar = 'v';
                        nx = tx; ty = ny;
                        break;
                    case 3 -> { // right
                        selfChar = '<'; otherChar = '>';
                        nx = tx; ny = ty;
                        break;
                }
                chosenDir = d;
                break;
            }

            if (chosenDir == -1) {
                return false; // should not happen – forced cell lost all neighbours
            }

            // place the two halves
            board[x][y] = selfChar;
            board[nx][ny] = otherChar;

            // after placement, enqueue any newly created forced cells
            for (int d = 0; d < 4; ++d) {
                int rx = nx + DX[d];
                int ry = ny + DY[d];
                if (rx < 0 || rx >= rows || ry < 0 || ry >= cols) continue;
                if (board[rx][ry] != '.') continue;
                int cnt = countEmptyNeighbours(rx, ry);
                if (cnt == 0) return false; // dead end
                if (cnt == 1) {
                    qx[qBack] = rx;
                    qy[qBack] = ry;
                    qBack++;
                }
            }
        }

        return true;
    }

    /** --------------------------------------------------------------------- */
    /** Returns true if at least one empty cell still exists on the board */
    private static boolean hasRemainingEmpty() {
        for (int r = 0; r < rows; ++r) {
            for (int c = 0; c < cols; ++c) {
                if (board[r][c] == '.') return true;
            }
        }
        return false;
    }

    /** --------------------------------------------------------------------- */
    /** Counts empty neighbours (up, left, down, right) of a cell */
    private static int countEmptyNeighbours(int r, int c) {
        int cnt = 0;
        for (int d = 0; d < 4; ++d) {
            int nr = r + DX[d];
            int nc = c + DY[d];
            if (nr < 0 || nr >= rows || nc < 0 || nc >= cols) continue;
            if (board[nr][nc] == '.') cnt++;
        }
        return cnt;
    }

    /** --------------------------------------------------------------------- */
    /** Recursively explores possible tilings and counts solutions.
     *  Stops as soon as more than one solution is found. */
    private static int countSolutions() {
        return dfs(0, 0, new int[2]);
    }

    /** Depth‑first search that returns:
     *   0 – no valid continuation,
     *   1 – exactly one valid continuation discovered,
     *   2 – at least two distinct solutions found.
     */
    private static int dfs(int startX, int startY, int[] result) {
        if (result[0] >= 2) return 2; // already decided that there are ≥2 solutions

        // find the first empty cell scanning row‑major order
        int x = startX, y = startY;
        while (x < rows) {
            while (y < cols) {
                if (board[x][y] == '.') {
                    // try horizontal placement (right)
                    if (y + 1 < cols && board[x][y + 1] == '.') {
                        placeHorizontal(x, y);
                        int rc = dfs(x, y + 1, result);
                        undoHorizontal(x, y);
                        if (rc == 2) return 2;
                        result[0] += rc;
                    }
                    // try vertical placement (down)
                    if (x + 1 < rows && board[x + 1][y] == '.') {
                        placeVertical(x, y);
                        int rc = dfs(x, y + 1, result);
                        undoVertical(x, y);
                        if (rc == 2) return 2;
                        result[0] += rc;
                    }
                    return result[0];
                }
                y++;
            }
            x++;
            y = 0;
        }
        // no empty cells left → one complete tiling found
        result[0]++;
        return result[0];
    }

    /** --------------------------------------------------------------------- */
    /** Places a horizontal tile on (x,y) and (x,y+1) using '<' and '>' */
    private static void placeHorizontal(int x, int y) {
        board[x][y] = '<';
        board[x][y + 1] = '>';
    }

    /** --------------------------------------------------------------------- */
    /** Removes the horizontal tile placed by {@code placeHorizontal} */
    private static void undoHorizontal(int x, int y) {
        board[x][y] = '.';
        board[x][y + 1] = '.';
    }

    /** --------------------------------------------------------------------- */
    /** Places a vertical tile on (x,y) and (x+1,y) using '^' and 'v' */
    private static void placeVertical(int x, int y) {
        board[x][y] = '^';
        board[x + 1][y] = 'v';
    }

    /** --------------------------------------------------------------------- */
    /** Removes the vertical tile placed by {@code placeVertical} */
    private static void undoVertical(int x, int y) {
        board[x][y] = '.';
        board[x + 1][y] = '.';
    }

    /** --------------------------------------------------------------------- */
    /** Prints the current board */
    private static void printBoard() {
        for (int r = 0; r < rows; ++r) {
            out.println(new String(board[r]));
        }
    }

    /** --------------------------------------------------------------------- */
    /** Helper to output a string followed by a newline */
    private static void println(String s) {
        out.println(s);
    }
}

/* -------------------------------------------------------------------------
 *  InputReader (kept as a small utility class)
 * ------------------------------------------------------------------------- */
class InputReader {
    private final BufferedReader reader;

    InputReader(InputStream stream) {
        reader = new BufferedReader(new InputStreamReader(stream, 32768));
    }

    String next() throws IOException {
        while (true) {
            String line = reader.readLine();
            if (line == null) return null;
            StringTokenizer tk = new StringTokenizer(line);
            if (tk.hasMoreTokens()) return tk.nextToken();
        }
    }

    int nextInt() throws IOException {
        return Integer.parseInt(next());
    }
}

/**
 *  B – Tile a board with dominoes and detect a unique tiling.
 *
 *  The refactored version focuses on readability, maintainability and
 *  separation of concerns.  All magic numbers are replaced by constants or
 *  small helper enums, duplicate logic is extracted, and the main flow is
 *  expressed with clear method names.
 *
 *  Compatibility: Java 17 (no external libraries required).
 */
public class B {

    /* -------------------------------------------------------------------- */
    /*  Constants & small helper utilities                                   */
    /* -------------------------------------------------------------------- */

    /** Possible arrow symbols that describe a domino orientation. */
    private enum Arrow {
        UP('^', 0), DOWN('v', 1), LEFT('<', 2), RIGHT('>', 3);

        private final char symbol;
        private final int index; // the enum order matches the direction order

        Arrow(char symbol, int index) {
            this.symbol = symbol;
            this.index = index;
        }

        /** Return the direction marker (used for the opposite direction). */
        int oppositeIndex() {
            return index ^ 1; // 0↔1, 2↔3 via XOR with 1
        }

        /** Convert a value from 0‑3 into an Arrow (used when we still have an int). */
        static Arrow from(int id) {
            return values()[id];
        }
    }

    /** Offsets for the four cardinal directions. */
    private static final int[] DI = {-1, 1, 0, 0}; // row delta: up, down, left, right
    /** Offsets for the four cardinal directions (column delta). */
    private static final int[] DJ = {0, 0, -1, 1};

    /** Private I/O helpers – they are intentionally kept package‑private
     *  to avoid exposure of static utility methods. */
    private final FastScanner fs;
    private final PrintWriter out;

    /* -------------------------------------------------------------------- */
    /*  Core data structure                                                   */
    /* -------------------------------------------------------------------- */

    /** The board – each cell holds either '.' (empty), '#' (blocked) or one
     *  of the arrow symbols that represent a placed domino. */
    private char[][] board;

    /** Size of the board. */
    private final int rows, cols;

    /* -------------------------------------------------------------------- */
    /*  Construction & entry point                                            */
    /* -------------------------------------------------------------------- */

    public B(FastScanner scanner, PrintWriter printer) {
        this.fs = scanner;
        this.out = printer;
    }

    /** Main solving routine – splits the work into small, testable steps. */
    public void solve() throws IOException {
        readDimensionsAndBoard();
        if (!placeAllDominoes()) {
            output("Not unique");
            return;
        }

        if (!boardIsCompletelyFilled()) {
            output("Not unique");
            return;
        }

        writeSolution();
    }

    /* -------------------------------------------------------------------- */
    /*  Input handling                                                       */
    /* -------------------------------------------------------------------- */

    private void readDimensionsAndBoard() throws IOException {
        rows = fs.nextInt();
        cols = fs.nextInt();
        board = new char[rows][];
        for (int r = 0; r < rows; r++) {
            String line = fs.next();
            board[r] = line.toCharArray();
        }
    }

    /* -------------------------------------------------------------------- */
    /*  Domino placement logic                                                */
    /* -------------------------------------------------------------------- */

    /**
     * Tries to fill the whole board with non‑overlapping dominoes.
     *
     * @return {@code true} if a placement that covers every '.' cell was found;
     *         {@code false} otherwise (the tiling is ambiguous or impossible).
     */
    private boolean placeAllDominoes() {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (!canPlaceOn(board[r][c])) {
                    continue;
                }
                if (!processEmptyCell(r, c)) {
                    // If we ever hit a cell where placement is impossible,
                    // the whole board cannot be uniquely tiled.
                    return false;
                }
            }
        }
        return true;
    }

    /** Returns {@code true} when the cell is currently empty ('.'). */
    private boolean canPlaceOn(char cell) {
        return cell == '.';
    }

    /**
     * Tries to place a domino that uses this empty cell.
     *
     * The algorithm respects the original logic:
     *   * If the cell has exactly three blocked sides we are forced to place a
     *     domino in the unique open direction.
     *   * After placing the domino we recursively continue on the newly covered
     *     neighbours.
     *
     * @return {@code true} if the DFS explored the whole board without
     *         contradictions; {@code false} otherwise.
     */
    private boolean processEmptyCell(int r, int c) {
        if (!inside(r, c) || board[r][c] != '.') {
            return true; // already handled – treat as success
        }
        if (isFullySurrounded(r, c)) {
            return false; // dead‑end: cannot proceed uniquely
        }

        if (hasExactlyThreeBlockedSides(r, c)) {
            // Determine the only open direction and place a domino there.
            int dir = directionOfOpenSide(r, c);
            placeDomino(r, c, dir);
            // Continue DFS on all four neighbours of the newly placed domino.
            for (int d = 0; d < 4; d++) {
                if (!processEmptyCell(r + DI[d], c + DJ[d])) {
                    return false;
                }
            }
        }
        // No forced placement – treat as success for this branch.
        return true;
    }

    /** Checks whether all four sides of (r,c) are blocked (edge or non '.'). */
    private boolean isFullySurrounded(int r, int c) {
        return countBlockedSides(r, c) == 4;
    }

    /** Returns the number of sides that are either outside the board or
     *  contain a non‑empty character. */
    private int countBlockedSides(int r, int c) {
        int blocked = 0;
        blocked += sideIsBlocked(r + 1, c);
        blocked += sideIsBlocked(r - 1, c);
        blocked += sideIsBlocked(r, c + 1);
        blocked += sideIsBlocked(r, c - 1);
        return blocked;
    }

    /** Returns {@code true} if the given neighbour cell is either outside the
     *  board or does not contain a '.' character. */
    private boolean sideIsBlocked(int nr, int nc) {
        return !inside(nr, nc) || board[nr][nc] != '.';
    }

    /** Determines which side of (r,c) is still empty (i.e., still '.'). */
    private int directionOfOpenSide(int r, int c) {
        // The original code inspected neighbours until it found a '.'.
        // The order does not matter as there is only one such side when
        // countBlockedSides == 3.
        if (!sideIsBlocked(r + 1, c)) return 0; // down
        if (!sideIsBlocked(r - 1, c)) return 1; // up
        if (!sideIsBlocked(r, c + 1)) return 2; // right
        // No need to check left – we already know exactly one side is open.
        return 3; // left
    }

    /**
     * Places an arrow in the current cell and its neighbour in the given
     * direction, forming a domino.
     *
     * The opposite direction uses the XOR trick (`dir ^ 1`) to obtain the
     * matching arrow (e.g., UP ↔ DOWN, LEFT ↔ RIGHT).
     */
    private void placeDomino(int r, int c, int dir) {
        Arrow arrow = Arrow.from(dir);
        board[r][c] = arrow.symbol;
        int nr = r + DI[dir];
        int nc = c + DJ[dir];
        board[nr][nc] = arrow.opposite(); // Arrow.opposite() not needed – we compute directly
        board[nr][nc] = Arrow.from(dir ^ 1).symbol;
    }

    /**
     * Returns {@code true} if every board cell is no longer '.' (i.e., the board
     * is completely tiled).  Used as a final verification step.
     */
    private boolean boardIsCompletelyFilled() {
        for (char[] row : board) {
            for (char cell : row) {
                if (cell == '.') {
                    return false;
                }
            }
        }
        return true;
    }

    /* -------------------------------------------------------------------- */
    /*  Output helpers                                                       */
    /* -------------------------------------------------------------------- */

    private void output(String message) {
        out.println(message);
    }

    private void writeSolution() {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                out.print(board[r][c]);
            }
            out.println();
        }
    }

    /* -------------------------------------------------------------------- */
    /*  Small static utilities                                               */
    /* -------------------------------------------------------------------- */

    /** Utility class that wraps the scanner/tokenizer logic. */
    private static final class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner(InputStream stream) {
            br = new BufferedReader(new InputStreamReader(stream));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    throw new UncheckedIOException(e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }
    }

    /* -------------------------------------------------------------------- */
    /*  Entry point                                                          */
    /* -------------------------------------------------------------------- */

    public static void main(String[] args) throws IOException {
        FastScanner scanner = new FastScanner(System.in);
        PrintWriter printer = new PrintWriter(System.out);
        try (B solver = new B(scanner, printer)) {
            solver.solve();
        }
        printer.close();
    }
}

