/** Fast scanner that works with a buffered byte array. */
final class StreamScanner {
    private final InputStream input;
    private final byte[] buffer = new byte[1 << 16];
    private int ptr = 0;
    private int length = 0;

    StreamScanner(InputStream input) {
        this.input = input;
    }

    private int readByte() {
        if (ptr >= length) {
            length = input.read(buffer);
            ptr = 0;
            if (length <= 0) return -1;
        }
        return buffer[ptr++];
    }

    private boolean isSpace(int c) {
        return c <= ' ';
    }

    /** Reads the next token (delimited by whitespace). */
    String next() {
        int c;
        do {
            c = readByte();
        } while (!isSpace(c) && c != -1);

        if (c == -1) return null;

        StringBuilder sb = new StringBuilder();
        do {
            sb.append((char) c);
            c = readByte();
        } while (!isSpace(c) && c != -1);
        return sb.toString();
    }

    /** Reads the next integer. */
    int nextInt() {
        return Integer.parseInt(next());
    }

    /** Closes the underlying stream. */
    void close() {
        readByte(); // forces a final read to flush buffers
    }
}

/** Solves the tiling problem and prints the result. */
class Solver {
    /** Directions: right, up, left, down */
    private static final int[][] DIRS = {
            {0, 1}, {-1, 0}, {0, -1}, {1, 0}
    };
    /** Symbols used for domino halves. */
    private static final char HORIZ_LEFT  = '<';
    private static final char HORIZ_RIGHT = '>';
    private static final char VERT_TOP    = '^';
    private static final char VERT_BOTTOM = 'v';

    /** Current board (mutable). */
    private char[][] board;
    /** Number of rows and columns. */
    private int rows, cols;
    /** Queue of cells that currently have exactly one free neighbour. */
    private final Queue<Cell> queue = new ArrayDeque<>();

    /** Simple container for row and column indices. */
    private static final class Cell {
        final int r, c;
        Cell(int r, int c) { this.r = r; this.c = c; }
    }

    /** Entry point called by Main. */
    void solve(StreamScanner scanner, PrintWriter out) {
        rows = scanner.nextInt();
        cols = scanner.nextInt();
        board = new char[rows][];

        // Read the board
        for (int r = 0; r < rows; r++) {
            board[r] = scanner.next().toCharArray();
        }

        // Initialise degree (number of free neighbours) for each '.' cell
        int[][] degree = new int[rows][cols];
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (board[r][c] == '.') {
                    degree[r][c] = countFreeNeighbours(r, c);
                    if (degree[r][c] == 1) {
                        queue.add(new Cell(r, c));
                    }
                }
            }
        }

        // Process degree‑1 cells until the queue empties
        while (!queue.isEmpty()) {
            Cell cur = queue.poll();
            int r = cur.r, c = cur.c;

            // Cell may already be paired
            if (board[r][c] != '.') continue;

            // Locate the only remaining free neighbour (its partner)
            Cell partner = findFreeNeighbour(r, c, degree);
            if (partner == null) continue; // no partner -> later detection of non‑uniqueness

            // Mark the domino
            placeDomino(r, c, partner.r, partner.c);

            // Update neighbours of the partner
            for (int[] d : DIRS) {
                int nr = partner.r + d[0];
                int nc = partner.c + d[1];
                if (inBounds(nr, nc) && board[nr][nc] == '.') {
                    decreaseDegree(nr, nc, degree, queue);
                }
            }
        }

        // If any '.' remains, the tiling is not unique
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (board[r][c] == '.') {
                    out.println("Not unique");
                    return;
                }
            }
        }

        // Output the fully tiled board
        for (char[] row : board) {
            out.println(row);
        }
    }

    /** Counts adjacent '.' cells for (r,c). */
    private int countFreeNeighbours(int r, int c) {
        int cnt = 0;
        for (int[] d : DIRS) {
            int nr = r + d[0];
            int nc = c + d[1];
            if (inBounds(nr, nc) && board[nr][nc] == '.') cnt++;
        }
        return cnt;
    }

    /** Returns the unique free neighbour of (r,c) or null if none exist. */
    private Cell findFreeNeighbour(int r, int c, int[][] degree) {
        for (int[] d : DIRS) {
            int nr = r + d[0];
            int nc = c + d[1];
            if (inBounds(nr, nc) && board[nr][nc] == '.') {
                return new Cell(nr, nc);
            }
        }
        return null;
    }

    /** Decrements neighbour degree; if it becomes 1, enqueues the neighbour. */
    private void decreaseDegree(int nr, int nc, int[][] degree, Queue<Cell> q) {
        degree[nr][nc]--;
        if (degree[nr][nc] == 1) {
            q.add(new Cell(nr, nc));
        }
    }

    /** Places the appropriate characters for a horizontal or vertical domino. */
    private void placeDomino(int r1, int c1, int r2, int c2) {
        if (r1 == r2) { // horizontal
            int left  = Math.min(c1, c2);
            int right = Math.max(c1, c2);
            board[r1][left]  = HORIZ_LEFT;
            board[r1][right] = HORIZ_RIGHT;
        } else {        // vertical
            int top    = Math.min(r1, r2);
            int bottom = Math.max(r1, r2);
            board[top][c1]   = VERT_TOP;
            board[bottom][c1]= VERT_BOTTOM;
        }
    }

    /** Checks whether the given coordinates are inside the board. */
    private boolean inBounds(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }
}

import java.io.*;
import java.util.*;
import java.util.stream.*;

/**
 * Solution for CF292_B – Tiling with Dominoes.
 *
 * <p>Reads a rectangular board where {@code '*'} denotes an obstacle and {@code '.'}
 * denotes an empty cell. Empty cells must be covered by non‑overlapping dominoes.
 * The program prints the board with arrows showing the direction of each domino
 * (e.g. '<', '>', '^', 'v'), or {@code "Not unique"} if the tiling is ambiguous
 * or impossible. The refactored version focuses on readability, modularisation,
 * and proper use of Java idioms.</p>
 */
public class Main {

    /** Symbol used for obstacles. */
    private static final char OBSTACLE = '*';

    /** Symbol used for empty cells before tiling. */
    private static final char EMPTY = '.';

    /** Direction enum – each constant knows its opposite and offset. */
    private enum Direction {
        UP(0, -1, '^', 'v'),
        DOWN(0, 1, 'v', '^'),
        LEFT(-1, 0, '<', '>'),
        RIGHT(1, 0, '>', '<');

        private final int di, dj;
        private final char selfChar, partnerChar;

        Direction(int di, int dj, char selfChar, char partnerChar) {
            this.di = di;
            this.dj = dj;
            this.selfChar = selfChar;
            this.partnerChar = partnerChar;
        }

        /** Returns the opposite direction. */
        Direction opposite() {
            return switch (this) {
                case UP -> DOWN;
                case DOWN -> UP;
                case LEFT -> RIGHT;
                case RIGHT -> LEFT;
            };
        }

        /** Returns the movement offset for this direction. */
        int[] offset() {
            return new int[]{di, dj};
        }
    }

    /** Small holder for a cell together with the direction that forces its pairing. */
    private static final class Placement {
        final int i, j;
        final Direction dir;

        Placement(int i, int j, Direction dir) {
            this.i = i;
            this.j = j;
            this.dir = dir;
        }
    }

    /** Simple scanner that reads tokens from stdin. */
    private static final class MyScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        MyScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        /** Returns the next token, reading a new line if necessary. */
        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    throw new UncheckedIOException(e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        char[] nextCharArray() {
            return next().toCharArray();
        }
    }

    public static void main(String[] args) {
        MyScanner in = new MyScanner();

        int rows = in.nextInt();
        int cols = in.nextInt();

        /* -----------------------------------------------------------
         * Build the board surrounded by an obstacle border.
         * ----------------------------------------------------------- */
        char[][] board = new char[rows + 2][cols + 2];
        fillBorders(board, OBSTACLE);

        for (int r = 1; r <= rows; r++) {
            char[] input = in.nextCharArray();
            board[r][0] = OBSTACLE;
            board[r][cols + 1] = OBSTACLE;
            System.arraycopy(input, 0, board[r], 1, cols);
        }

        /* -----------------------------------------------------------
         * Basic feasibility tests.
         * ----------------------------------------------------------- */
        int emptyCount = countEmpties(board);
        if ((emptyCount & 1) == 1) {
            System.out.println("Not unique");
            return;
        }

        int remainingEmpty = emptyCount;
        Queue<Placement> workQueue = new ArrayDeque<>();

        /* -----------------------------------------------------------
         * Initial scan – cells that have exactly one free neighbour are
         * forced to be paired in the given direction.
         * ----------------------------------------------------------- */
        for (int r = 0; r < board.length; r++) {
            for (int c = 0; c < board[r].length; c++) {
                if (board[r][c] != EMPTY) continue;

                int neighbourCount = countAdjacentEmpties(board, r, c);
                if (neighbourCount != 1) continue;

                Direction dir = discoverDirection(board, r, c);
                workQueue.add(new Placement(r, c, dir));
            }
        }

        /* -----------------------------------------------------------
         * Propagation – each forced placement may create new cells
         * with a single free neighbour, which are then processed.
         * ----------------------------------------------------------- */
        while (!workQueue.isEmpty()) {
            Placement p = workQueue.remove();
            int i0 = p.i, j0 = p.j;
            Direction dir = p.dir;

            // The board may have been altered already; skip stale entries.
            if (board[i0][j0] != EMPTY) continue;

            int toI = i0 + dir.offset()[0];
            int toJ = j0 + dir.offset()[1];

            if (board[toI][toJ] != EMPTY) continue; // another thread already filled it

            // Mark the pair.
            board[i0][j0] = dir.selfChar;
            board[toI][toJ] = dir.partnerChar;
            remainingEmpty -= 2;

            // Enqueue newly created forced cells.
            for (int d = 0; d < 4; d++) {
                Direction neighbourDir = Direction.values()[d];
                int ni = toI + neighbourDir.offset()[0];
                int nj = toJ + neighbourDir.offset()[1];

                if (board[ni][nj] != EMPTY) continue;

                int cnt = countAdjacentEmpties(board, ni, nj);
                if (cnt == 1) {
                    workQueue.add(new Placement(ni, nj, discoverDirection(board, ni, nj)));
                }
            }
        }

        if (remainingEmpty != 0) {
            System.out.println("Not unique");
            return;
        }

        /* -----------------------------------------------------------
         * Output the solved board.
         * ----------------------------------------------------------- */
        StringBuilder out = new StringBuilder();
        for (int r = 1; r < board.length - 1; r++) {
            for (int c = 1; c < board[r].length - 1; c++) {
                out.append(board[r][c]);
            }
            out.append('\n');
        }
        System.out.print(out);
    }

    /** Fill the outermost rows and columns with the given character. */
    private static void fillBorders(char[][] board, char ch) {
        Arrays.fill(board[0], ch);
        Arrays.fill(board[board.length - 1], ch);
        for (int r = 0; r < board.length; r++) {
            board[r][0] = ch;
            board[r][board[r].length - 1] = ch;
        }
    }

    /** Count 'EMPTY' cells on the whole board. */
    private static int countEmpties(char[][] board) {
        return (int) Arrays.stream(board)
                .flatMapToInt(Arrays::stream)
                .filter(ch -> ch == EMPTY)
                .count();
    }

    /** Count adjacent EMPTY cells for a given coordinate. */
    private static int countAdjacentEmpties(char[][] board, int i, int j) {
        int cnt = 0;
        for (Direction d : Direction.values()) {
            int ni = i + d.offset()[0];
            int nj = j + d.offset()[1];
            if (board[ni][nj] == EMPTY) cnt++;
        }
        return cnt;
    }

    /** Determine the unique direction that leads to an adjacent EMPTY cell. */
    private static Direction discoverDirection(char[][] board, int i, int j) {
        for (Direction d : Direction.values()) {
            int ni = i + d.offset()[0];
            int nj = j + d.offset()[1];
            if (board[ni][nj] == EMPTY) {
                return d;
            }
        }
        throw new IllegalStateException("Cell (" + i + "," + j + ") has no empty neighbour");
    }
}

/**
 * Refactored Domino Tiling solution.
 *
 * <p>This version improves readability, separates concerns and uses modern Java constructs
 * while preserving the exact algorithmic behaviour of the original code.</p>
 */
import java.io.IOException;
import java.io.PrintWriter;
import java.util.ArrayDeque;
import java.util.Deque;
import java.util.StringTokenizer;

public class DominoTiling {

    /** Fast scanner for competitive‑style input. */
    private static final class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner(BufferedReader br) {
            this.br = br;
        }

        /** Returns next token, or {@code null} if EOF. */
        String nextToken() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    return null;
                }
            }
            return st.nextToken();
        }

        /** Reads a whole line (or {@code null} on EOF). */
        String nextString() {
            try {
                return br.readLine();
            } catch (IOException e) {
                return null;
            }
        }

        /** Reads an {@code int}. */
        int nextInt() {
            return Integer.parseInt(nextToken());
        }
    }

    /** Directions used for neighbour probing. */
    private static final int[] DX = {1, -1, 0, 0};
    private static final int[] DY = {0, 0, 1, -1};

    /** Maximum grid size assumed by the original solution. */
    private static final int MAX = 2222;

    /** Graphic representation of the board after tiling. */
    private char[][] board;
    /** Degree of each free cell – number of adjacent free cells. */
    private int[][] degree;
    /** Queue used for the BFS‑like propagation. */
    private final Deque<Integer> queue = new ArrayDeque<>();

    /** Input reader, output writer. */
    private FastScanner in;
    private PrintWriter out;

    /** Entry point. */
    public static void main(String[] args) throws IOException {
        new DominoTiling().run();
    }

    /** Runs the whole program – read, solve, output. */
    private void run() throws IOException {
        in = new FastScanner(new BufferedReader(new InputStreamReader(System.in)));
        out = new PrintWriter(System.out);
        solve();
        out.close();
    }

    /** Core solving routine. */
    private void solve() {
        final int rows = in.nextInt();
        final int cols = in.nextInt();

        board = new char[rows][cols];
        degree = new int[rows][cols];

        for (int r = 0; r < rows; r++) {
            String line = in.nextString();
            board[r] = line.toCharArray();               // read input board
        }

        initDegrees(rows, cols);
        fillQueueWithDegreeOne(rows, cols);

        while (!queue.isEmpty()) {
            int id = queue.pollFirst();
            int x = id / cols;
            int y = id % cols;

            // Skip already processed cells
            if (board[x][y] != '.') {
                continue;
            }

            // Try to match the current cell with a neighbour that is still free
            for (int d = 0; d < 4; d++) {
                int nx = x + DX[d];
                int ny = y + DY[d];
                if (!isInBounds(nx, ny, rows, cols) || board[nx][ny] != '.') {
                    continue;
                }

                // Place a domino covering (x,y) and (nx,ny)
                assignTile(x, y, nx, ny);

                // Update degrees of neighbours of (nx,ny) – they lost a free neighbour
                for (int nd = 0; nd < 4; nd++) {
                    int ax = nx + DX[nd];
                    int ay = ny + DY[nd];
                    if (isInBounds(ax, ay, rows, cols) && board[ax][ay] == '.') {
                        degree[ax][ay]--;
                        if (degree[ax][ay] == 1) {
                            queue.addLast(ax * cols + ay);
                        }
                    }
                }
            }
        }

        // If any '.' remains the tiling is not unique (or impossible)
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (board[r][c] == '.') {
                    out.println("Not unique");
                    return;
                }
            }
        }

        // Otherwise print the unique tiling
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                out.print(board[r][c]);
            }
            out.println();
        }
    }

    /** Computes the initial degree for each free cell. */
    private void initDegrees(int rows, int cols) {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (board[r][c] == '*') {
                    continue;
                }
                int cnt = 0;
                for (int d = 0; d < 4; d++) {
                    int nr = r + DX[d];
                    int nc = c + DY[d];
                    if (isInBounds(nr, nc, rows, cols) && board[nr][nc] == '.') {
                        cnt++;
                    }
                }
                degree[r][c] = cnt;
            }
        }
    }

    /** Populates the queue with all cells that currently have degree == 1. */
    private void fillQueueWithDegreeOne(int rows, int cols) {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (board[r][c] == '.' && degree[r][c] == 1) {
                    queue.addLast(r * cols + c);
                }
            }
        }
    }

    /** Checks whether (x, y) lies inside the grid. */
    private boolean isInBounds(int x, int y, int rows, int cols) {
        return x >= 0 && x < rows && y >= 0 && y < cols;
    }

    /**
     * Places a domino covering two adjacent free cells.
     *
     * <p>The original code used a small helper {@code mark} that wrote the
     * appropriate arrow/backslash character into the board.  The logic is
     * reproduced here with clearer variable names and without any mutable
     * temporary arrays.</p>
     *
     * @param x1 row of the first cell (must be free)
     * @param y1 col of the first cell (must be free)
     * @param x2 row of the second cell (must be free)
     * @param y2 col of the second cell (must be free)
     */
    private void assignTile(int x1, int y1, int x2, int y2) {
        if (x1 == x2) {                     // horizontal domino
            if (y1 > y2) {
                int tmp = y2; y2 = y1; y1 = tmp;
            }
            board[x1][y1] = '<';
            board[x2][y2] = '>';
        } else {                            // vertical domino
            if (x1 > x2) {
                int tmp = x1; x1 = x2; x2 = tmp;
            }
            board[x1][y1] = '^';
            board[x2][y2] = 'v';
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.Arrays;

/**
 * Reads a grid, determines whether it can be tiled in exactly one way
 * and prints the tiling if it is unique.
 *
 * <p>
 *   Empty cells ('.') are represented by {@code 0},
 *   obstacles ('*') by {@code 1},
 *   and placed tiles by {@code 2}, {@code 3}, {@code 4}, {@code 5}
 *   (down, up, right, left respectively).
 * </p>
 *
 * <p>If the board cannot be tiled uniquely the program prints
 * {@code "Not unique"}.</p>
 */
public class B {

    /* --------------------------------------------------------------------- */
    /*                          Constants & Types                            */
    /* --------------------------------------------------------------------- */
    private static final int EMPTY   = 0;   // '.'  – free cell
    private static final int OBSTACLE = 1;   // '*'  – blocked cell
    private static final int TILE_DOWN = 2;  // placed tile pointing down
    private static final int TILE_UP   = 3;  // placed tile pointing up
    private static final int TILE_RIGHT= 4;  // placed tile pointing right
    private static final int TILE_LEFT = 5;  // placed tile pointing left

    private static final char CHAR_OBSTACLE = '*';
    private static final char CHAR_EMPTY    = '.';   // not used in output
    private static final char CHAR_UP      = '^';
    private static final char CHAR_DOWN    = 'v';
    private static final char CHAR_RIGHT   = '>';
    private static final char CHAR_LEFT    = '<';

    /* --------------------------------------------------------------------- */
    /*                            Entry Point                                 */
    /* --------------------------------------------------------------------- */
    public static void main(String[] args) throws IOException {
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(System.in))) {
            String line = reader.readLine();
            if (line == null) {
                return;
            }

            String[] dims = line.trim().split("\\s+");
            int rows = Integer.parseInt(dims[0]);
            int cols = Integer.parseInt(dims[1]);

            // map[0][*] and map[rows+1][*] are outer borders filled with OBSTACLE
            int[][] map = createEmptyBoard(rows, cols);
            fillBoard(reader, rows, cols, map);

            boolean unique = solveUniqueTiling(rows, cols, map);
            if (!unique) {
                System.out.println("Not unique");
            }
        }
    }

    /* --------------------------------------------------------------------- */
    /*                              Helpers                                    */
    /* --------------------------------------------------------------------- */
    private static int[][] createEmptyBoard(int rows, int cols) {
        int[][] board = new int[rows + 2][cols + 2];
        for (int[] row : board) {
            Arrays.fill(row, OBSTRUCT);
        }
        return board;
    }

    private static void fillBoard(BufferedReader reader,
                                  int rows, int cols,
                                  int[][] map) throws IOException {
        for (int r = 1; r <= rows; r++) {
            String line = reader.readLine();
            if (line == null) {
                return;
            }
            String trimmed = line.trim();
            for (int c = 1; c <= cols; c++) {
                map[r][c] = (trimmed.charAt(c - 1) == '.') ? EMPTY : OBSTACLE;
            }
        }
    }

    /** Entry point for the algorithm – returns {@code true} iff the tiling is unique. */
    private static boolean solveUniqueTiling(int rows, int cols, int[][] map) {
        int[][] degree = computeDegrees(map, rows, cols);
        boolean changed;
        do {
            changed = tryAssignTiles(map, degree, rows, cols);
        } while (changed);

        // If any empty cell remains the board cannot be uniquely tiled.
        for (int r = 1; r <= rows; r++) {
            for (int c = 1; c <= cols; c++) {
                if (map[r][c] == EMPTY) {
                    return false;
                }
            }
        }
        printSolution(map, rows, cols);
        return true;
    }

    /** Calculates for every free cell the number of adjacent free cells. */
    private static int[][] computeDegrees(int[][] map, int rows, int cols) {
        int[][] degree = new int[rows + 2][cols + 2];
        for (int r = 1; r <= rows; r++) {
            for (int c = 1; c <= cols; c++) {
                if (map[r][c] != EMPTY) {
                    continue;
                }
                int cnt = 0;
                if (map[r - 1][c] == EMPTY) cnt++;
                if (map[r + 1][c] == EMPTY) cnt++;
                if (map[r][c - 1] == EMPTY) cnt++;
                if (map[r][c + 1] == EMPTY) cnt++;
                degree[r][c] = cnt;
            }
        }
        return degree;
    }

    /**
     * Scans the board for a free cell with {@code degree == 1} and makes the
     * forced placement. Returns {@code true} if a placement was performed.
     */
    private static boolean tryAssignTiles(int[][] map,
                                          int[][] degree,
                                          int rows, int cols) {
        for (int r = 1; r <= rows; r++) {
            for (int c = 1; c <= cols; c++) {
                if (map[r][c] != EMPTY) {
                    continue;
                }
                if (degree[r][c] == 1) {
                    makeForcedPlacement(map, degree, r, c);
                    return true;               // placement performed – restart scan
                }
                if (degree[r][c] == 0) {
                    // isolated cell – tiling impossible
                    return false;
                }
            }
        }
        return false; // no degree‑1 cells left
    }

    /**
     * Starting from a cell that is guaranteed to have exactly one free neighbour,
     * follows that neighbour along the unique possible line and tiles the whole
     * line, updating the board and the degree matrix.
     */
    private static void makeForcedPlacement(int[][] map,
                                            int[][] degree,
                                            int startR, int startC) {
        int r = startR;
        int c = startC;

        // Determine the direction of the forced segment by inspecting the first free neighbour
        int nextR = -1, nextC = -1;
        if (map[r - 1][c] == EMPTY) {
            nextR = r - 1; nextC = c;
        } else if (map[r + 1][c] == EMPTY) {
            nextR = r + 1; nextC = c;
        } else if (map[r][c - 1] == EMPTY) {
            nextR = r; nextC = c - 1;
        } else if (map[r][c + 1] == EMPTY) {
            nextR = r; nextC = c + 1;
        }
        // If none found something is wrong – but the caller guarantees degree == 1.

        // Walk until we hit a non‑empty cell
        while (map[r][c] == EMPTY && degree[r][c] == 1) {
            // Choose the only free neighbour
            int bestR = -1, bestC = -1;
            int bestDir = -1;
            if (map[r - 1][c] == EMPTY) { bestR = r - 1; bestC = c; bestDir = 0; }
            if (map[r + 1][c] == EMPTY) { bestR = r + 1; bestC = c; bestDir = 1; }
            if (map[r][c - 1] == EMPTY) { bestR = r;    bestC = c - 1; bestDir = 2; }
            if (map[r][c + 1] == EMPTY) { bestR = r;    bestC = c + 1; bestDir = 3; }

            if (bestR == -1) {
                // should never happen because degree == 1 guarantees exactly one free neighbour
                break;
            }

            // Place the two ends of the domino
            placeTileEnds(map, r, c, bestR, bestC);

            // Move to the next cell
            r = bestR;
            c = bestC;
        }

        // After the whole line is tiled we must relax degrees at both ends
        // (the caller will restart scanning, so we just continue)
    }

    /** Marks the two cells of a domino with the appropriate directional symbols. */
    private static void placeTileEnds(int[][] map,
                                      int aR, int aC,
                                      int bR, int bC) {
        // The first cell always gets the “start” marker (2‑5)
        // The second cell gets the opposite direction (3‑4‑2‑5)
        if (bR == aR - 1) {               // a points down, b points up
            map[aR][aC] = TILE_DOWN;
            map[bR][bC] = TILE_UP;
        } else if (bR == aR + 1) {        // a points up, b points down
            map[aR][aC] = TILE_UP;
            map[bR][bC] = TILE_DOWN;
        } else if (bC == aC - 1) {        // a points right, b points left
            map[aR][aC] = TILE_RIGHT;
            map[bR][bC] = TILE_LEFT;
        } else if (bC == aC + 1) {        // a points left, b points right
            map[aR][aC] = TILE_LEFT;
            map[bR][bC] = TILE_RIGHT;
        }
    }

    /** Decrements the degree counters of the four neighbours of (r,c) if they are positive. */
    private static void relaxDegrees(int[][] degree, int r, int c) {
        if (degree[r - 1][c] > 0) degree[r - 1][c]--;
        if (degree[r + 1][c] > 0) degree[r + 1][c]--;
        if (degree[r][c - 1] > 0) degree[r][c - 1]--;
        if (degree[r][c + 1] > 0) degree[r][c + 1]--;
    }

    /** Renders the solved board and prints it line by line. */
    private static void printSolution(int[][] map, int rows, int cols) {
        for (int r = 1; r <= rows; r++) {
            StringBuilder out = new StringBuilder(cols);
            for (int c = 1; c <= cols; c++) {
                switch (map[r][c]) {
                    case OBSTACLE   -> out.append(CHAR_OBSTACLE);
                    case TILE_DOWN  -> out.append(CHAR_DOWN);
                    case TILE_UP    -> out.append(CHAR_UP);
                    case TILE_RIGHT -> out.append(CHAR_RIGHT);
                    case TILE_LEFT  -> out.append(CHAR_LEFT);
                    default         -> out.append('?');   // should never happen
                }
            }
            System.out.println(out);
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Refactored version of the original program.
 * The logic is unchanged, but the code is organized into small, well‑named methods,
 * uses clear constants, and removes obscure tricks (e.g. bit‑shifts for encoding).
 *
 * <p>Input:</p>
 * <ul>
 *   <li>n m – grid dimensions.</li>
 *   <li>n lines each containing m characters ('.' or one of '<','>','^','v').</li>
 * </ul>
 *
 * <p>Output:</p>
 * <ul>
 *   <li>"Not unique" if any empty cell ('.') remains after processing.</li>
 *   <li>Otherwise the filled grid, where each empty cell becomes a direction
 *   character that points to its unique matched neighbour.</li>
 * </ul>
 */
public class Main {

    /* -----------------------------------------------------------
     *  Constants
     * ----------------------------------------------------------- */
    /** Direction characters that will be written into the board. */
    private static final char[] DIR_CHARS = {'<', '>', '^', 'v'};

    /** Offsets for the four neighbour directions (down, up, right, left). */
    private static final int[] DX = {1, -1, 0, 0};
    private static final int[] DY = {0, 0, 1, -1};

    /** Bit‑shift used for packing row/column into a single int (large enough for typical limits). */
    private static final int ENCODING_SHIFT = 32;

    /* -----------------------------------------------------------
     *  Entry point
     * ----------------------------------------------------------- */
    public static void main(String[] args) throws Exception {
        Reader sc = new Reader(System.in);
        int rows = sc.nextInt();
        int cols = sc.nextInt();

        char[][] board = new char[rows][cols];
        int[][] degree = new int[rows][cols];   // number of adjacent '.' cells

        // ----- read the board -------------------------------------------------
        for (int i = 0; i < rows; i++) {
            String line = sc.nextString();
            board[i] = line.toCharArray();
        }

        // ----- initialise degree matrix ---------------------------------------
        initialiseDegree(board, degree, rows, cols);

        // ----- find cells with exactly one free neighbour ----------------------
        Queue<Integer> queue = new ArrayDeque<>();
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (hasExactlyOneEmptyNeighbour(board, degree, i, j)) {
                    queue.add(encode(i, j));
                }
            }
        }

        // ----- process the queue ------------------------------------------------
        while (!queue.isEmpty()) {
            int packed = queue.poll();
            int r = decodeRow(packed);
            int c = decodeCol(packed);

            if (!isProcessable(board, degree, r, c)) {
                continue;    // cell may have become non‑empty by now
            }

            placeTile(board, r, c);                     // fill current and its partner
            propagateNeighbourUpdates(board, degree, r, c, queue);
        }

        // ----- produce the answer ------------------------------------------------
        if (stillHasEmptyCell(board)) {
            System.out.println("Not unique");
        } else {
            printBoard(board);
        }
    }

    /* -----------------------------------------------------------
     *  Helper methods
     * ----------------------------------------------------------- */

    /** Initialise the `degree` matrix – count of empty neighbours for each '.' cell. */
    private static void initialiseDegree(char[][] board, int[][] degree, int n, int m) {
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (board[i][j] == '.') {
                    degree[i][j] = countEmptyNeighbours(board, i, j);
                } else {
                    degree[i][j] = -1; // non‑empty cells are ignored
                }
            }
        }
    }

    /** Does the cell (i,j) contain exactly one adjacent empty neighbour? */
    private static boolean hasExactlyOneEmptyNeighbour(char[][] board,
                                                       int[][] degree,
                                                       int i,
                                                       int j) {
        return board[i][j] == '.' && degree[i][j] == 1;
    }

    /** Count '.' neighbours around (i,j). */
    private static int countEmptyNeighbours(char[][] board, int i, int j) {
        int cnt = 0;
        for (int d = 0; d < 4; d++) {
            int ni = i + DX[d];
            int nj = j + DY[d];
            if (isInBounds(ni, nj, board.length, board[0].length) && board[ni][nj] == '.') {
                cnt++;
            }
        }
        return cnt;
    }

    /** True if (x,y) lies inside the board. */
    private static boolean isInBounds(int x, int y, int rows, int cols) {
        return x >= 0 && x < rows && y >= 0 && y < cols;
    }

    /** Encode row and column into a single int for queue storage. */
    private static int encode(int row, int col) {
        return (row << ENCODING_SHIFT) | col;
    }

    /** Decode the packed int back to its row index. */
    private static int decodeRow(int packed) {
        return packed >>> ENCODING_SHIFT;
    }

    /** Decode the packed int back to its column index. */
    private static int decodeCol(int packed) {
        return packed & ((1 << ENCODING_SHIFT) - 1);
    }

    /** Is the cell eligible for processing (still empty and has degree 1)? */
    private static boolean isProcessable(char[][] board, int[][] degree, int i, int j) {
        return board[i][j] == '.' && degree[i][j] == 1;
    }

    /** Fill the current cell and its unique neighbour with appropriate direction chars. */
    private static void placeTile(char[][] board, int i, int j) {
        for (int d = 0; d < 4; d++) {
            int ni = i + DX[d];
            int nj = j + DY[d];
            if (isInBounds(ni, nj, board.length, board[0].length) && board[ni][nj] == '.') {
                board[i][j] = DIR_CHARS[d];
                board[ni][nj] = DIR_CHARS[(d + 2) % 4]; // opposite direction
                return;
            }
        }
    }

    /** After placing a tile, decrease the degree of its neighbours and enqueue newly‑unique cells. */
    private static void propagateNeighbourUpdates(char[][] board,
                                                  int[][] degree,
                                                  int i,
                                                  int j,
                                                  Queue<Integer> queue) {
        for (int d = 0; d < 4; d++) {
            int ni = i + DX[d];
            int nj = j + DY[d];
            if (!isInBounds(ni, nj, board.length, board[0].length) || board[ni][nj] != '.') {
                continue;
            }

            degree[ni][nj]--;
            if (degree[ni][nj] == 1) {
                queue.add(encode(ni, nj));
            }
        }
    }

    /** Scan the whole board – return true if any '.' remains. */
    private static boolean stillHasEmptyCell(char[][] board) {
        for (char[] row : board) {
            for (char cell : row) {
                if (cell == '.') {
                    return true;
                }
            }
        }
        return false;
    }

    /** Print the final board line by line. */
    private static void printBoard(char[][] board) {
        for (char[] row : board) {
            System.out.println(new String(row));
        }
    }
}

/* -----------------------------------------------------------
 *  Fast input reader (unchanged from the original, but isolated)
 * ----------------------------------------------------------- */
class Reader {
    private final BufferedReader reader;
    private StringTokenizer tokenizer;

    Reader(InputStream source) {
        reader = new BufferedReader(new InputStreamReader(source));
    }

    /** Return next token, reading a new line if necessary. */
    String nextString() throws IOException {
        while (tokenizer == null || !tokenizer.hasMoreTokens()) {
            tokenizer = new StringTokenizer(reader.readLine());
        }
        return tokenizer.nextToken();
    }

    int nextInt() throws IOException {
        return Integer.parseInt(nextString());
    }
}

import java.io.PrintWriter;
import java.util.ArrayDeque;
import java.util.Deque;
import java.util.Scanner;

/**
 * Entry point of the program.
 * Reads a grid from standard input, determines whether the tiling is unique,
 * and prints either "Not unique" or the solved board.
 */
public class Main {

    /** Sentinel value used to mark cells that are known to have zero neighbours. */
    private static final int ZERO_NEIGHBOURS = Integer.MIN_VALUE;

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        PrintWriter writer = new PrintWriter(System.out, true);

        Solver solver = new Solver();
        solver.solve(1, scanner, writer);

        writer.close();
        scanner.close();
    }
}

/**
 * Core logic that checks for a unique tiling of a rectangular board.
 * The board consists of '.' (available cell) and '*' (blocked cell).
 * If a unique tiling exists, the result is printed; otherwise the program
 * outputs "Not unique".
 */
class Solver {

    /**
     * Solves the problem for a single test case.
     *
     * @param testNumber dummy parameter kept for compatibility with original code
     * @param sc         scanner for reading input
     * @param out        writer for output
     */
    void solve(int testNumber, Scanner sc, PrintWriter out) {
        int rows = sc.nextInt();
        int cols = sc.nextInt();

        char[][] board = readBoard(sc, rows, cols);
        int[][] freeNeighbourCount = computeFreeNeighbourCount(board);
        int[][] assignments = new int[rows][cols];
        Deque<int[]> queue = new ArrayDeque<>();

        // Initialise the queue with cells that have exactly one free neighbour.
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (board[r][c] == '.') {
                    int degree = freeNeighbourCount[r][c];
                    if (degree == 0) {
                        out.println("Not unique");
                        return;
                    }
                    if (degree == 1) {
                        queue.add(new int[]{r, c});
                    }
                    assignments[r][c] = degree;                 // positive -> free cell
                } else {
                    assignments[r][c] = ZERO_NEIGHBOURS;       // blocked cell
                }
            }
        }

        // Process forced placements.
        while (!queue.isEmpty()) {
            int[] cur = queue.pollFirst();
            int r = cur[0];
            int c = cur[1];

            // The cell might have become invalid while waiting in the queue.
            if (assignments[r][c] != 1) {
                continue;
            }

            // Find a partner cell that is still free.
            int partnerR = findPartner(r, c, board, assignments);
            if (partnerR < 0) {
                out.println("Not unique");
                return;
            }

            // Record the pairing in a reversible way.
            assignments[r][c] = -(partnerR * 3000 + c);
            assignments[partnerR][c] = -(r * 3000 + partnerR);
            board[r][c] = 'X';      // mark as used
            board[partnerR][c] = 'X';

            // Update neighbour degrees of the affected area.
            for (int dr = -1; dr <= 1; dr++) {
                for (int dc = -1; dc <= 1; dc++) {
                    if (Math.abs(dr) + Math.abs(dc) != 1) {
                        continue;
                    }
                    int nr = partnerR + dr;
                    int nc = c + dc;
                    if (isValid(nr, nc, rows, cols) && board[nr][nc] == '.') {
                        decrementDegree(freeNeighbourCount, nr, nc);
                        if (freeNeighbourCount[nr][nc] == 1) {
                            queue.add(new int[]{nr, nc});
                        }
                    }
                }
            }
        }

        // After processing, any remaining free cell indicates non‑uniqueness.
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (assignments[r][c] > 0) {
                    out.println("Not unique");
                    return;
                }
            }
        }

        // Print the solved board.
        printSolution(board, assignments, out);
    }

    /** Reads the board from the scanner and maps '.' → 1 (free) and '*' → 0 (blocked). */
    private static char[][] readBoard(Scanner sc, int rows, int cols) {
        char[][] board = new char[rows][];
        for (int r = 0; r < rows; r++) {
            String line = sc.next();
            board[r] = line.toCharArray();
        }
        return board;
    }

    /** Counts how many orthogonal neighbours of (r,c) are free cells. */
    private static int countFreeNeighbour(int r, int c, char[][] board) {
        int count = 0;
        for (int dr : new int[]{-1, 1}) {
            int nr = r + dr;
            if (isValidRow(nr, board.length)) {
                if (board[nr][c] == '.') count++;
            }
        }
        for (int dc : new int[]{-1, 1}) {
            int nc = c + dc;
            if (isValidCol(c, board[0].length)) {
                if (board[r][nc] == '.') count++;
            }
        }
        return count;
    }

    /** Computes a matrix where each free cell holds the number of its free neighbours. */
    private static int[][] computeFreeNeighbourCount(char[][] board) {
        int rows = board.length;
        int cols = board[0].length;
        int[][] count = new int[rows][cols];
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (board[r][c] == '.') {
                    count[r][c] = countFreeNeighbour(r, c, board);
                }
            }
        }
        return count;
    }

    /** Returns the (row, col) of the unique free neighbour of (r,c), or -1 if none exists. */
    private static int findPartner(int r, int c, char[][] board, int[][] assignments) {
        // The order matches the original implementation (up, down, left, right).
        int[] dr = {-1, 1, 0, 0};
        int[] dc = {0, 0, -1, 1};

        for (int k = 0; k < 4; k++) {
            int nr = r + dr[k];
            int nc = c + dc[k];
            if (isValid(nr, nc, board.length, board[0].length) && board[nr][nc] == '.') {
                return nr; // column is always c in this problem (vertical dominoes only)
            }
        }
        return -1;
    }

    /** Decrements the neighbour count of a cell and returns the new value. */
    private static void decrementDegree(int[][] count, int r, int c) {
        count[r][c]--;
    }

    /** Checks whether (r,c) lies inside the board dimensions. */
    private static boolean isValid(int r, int c, int rows, int cols) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    /** Helper that checks only the row index. */
    private static boolean isValidRow(int r, int max) {
        return r >= 0 && r < max;
    }

    /** Helper that checks only the column index. */
    private static boolean isValidCol(int c, int max) {
        return c >= 0 && c < max;
    }

    /** Prints the solved board according to the encoded assignments. */
    private static void printSolution(char[][] board, int[][] assignments, PrintWriter out) {
        for (int r = 0; r < board.length; r++) {
            for (int c = 0; c < board[0].length; c++) {
                if (assignments[r][c] == Integer.MIN_VALUE) {
                    out.print('*');                     // originally blocked cell
                } else {
                    int code = -assignments[r][c];
                    int nr = code / 3000;
                    int nc = code % 3000;

                    // Horizontal adjacency (different row)
                    if (nr != r) {
                        out.print(nr < r ? 'v' : '^');
                    }
                    // Vertical adjacency (different column)
                    else {
                        out.print(nc < c ? '>' : '<');
                    }
                }
            }
            out.println();
        }
    }
}

package solution;

import java.io.*;
import java.util.StringTokenizer;

/**
 * Entry point – reads input, delegates to {@link TileSolver} and prints the result.
 */
public class Main {
    public static void main(String[] args) {
        solve(System.in, System.out);
    }

    private static void solve(InputStream in, OutputStream out) {
        FastScanner fs = new FastScanner(in);
        PrintWriter pw = new PrintWriter(new BufferedWriter(new OutputStreamWriter(out)));

        int rows = fs.nextInt();
        int cols = fs.nextInt();
        char[][] grid = new char[rows][];
        for (int i = 0; i < rows; ++i) {
            grid[i] = fs.next().toCharArray();
        }

        TileSolver solver = new TileSolver();
        solver.process(rows, cols, grid, pw);
        pw.flush();
    }
}

/**
 * Fast scanner that works with whitespace‑separated tokens.
 */
final class FastScanner {
    private final BufferedReader br;
    private StringTokenizer st;

    FastScanner(InputStream in) {
        br = new BufferedReader(new InputStreamReader(in));
    }

    private String readLine() {
        try {
            return br.readLine();
        } catch (IOException e) {
            throw new RuntimeException(e);
        }
    }

    private String readToken() {
        while (st == null || !st.hasMoreTokens()) {
            String line = readLine();
            if (line == null) return null;
            st = new StringTokenizer(line);
        }
        return st.nextToken();
    }

    String next() {
        return readToken();
    }

    int nextInt() {
        return Integer.parseInt(next());
    }
}

/**
 * Core logic for determining whether the empty cells of a grid admit a unique tiling
 * by 2×1 dominoes.  If a unique tiling exists, the tiled board is printed;
 * otherwise the string {@code "Not unique"} is printed.
 */
final class TileSolver {
    private static final String NOT_UNIQUE = "Not unique";

    /** The board being processed. */
    private char[][] grid;
    /** Number of rows and columns. */
    private final int rows, cols;
    /** Queue used for breadth‑first processing of cells that have exactly three free neighbours. */
    private final int[][] queue = new int[100_000][2];
    /** Head/tail indices for the queue. */
    private int queueHead, queueTail;
    /** Marks cells that have already been enqueued. */
    private final boolean[][] visited;
    /** Direction vectors (down, up, right, left). */
    private final int[] dx = {1, -1, 0, 0};
    private final int[] dy = {0, 0, 1, -1};

    /** Public entry point. */
    void process(int rows, int cols, char[][] grid, PrintWriter out) {
        this.rows = rows;
        this.cols = cols;
        this.grid = grid;
        this.visited = new boolean[rows][cols];
        queueHead = 0;
        queueTail = 0;

        // 1️⃣  Collect all cells that have exactly three adjacent empty cells.
        for (int r = 0; r < rows; ++r) {
            for (int c = 0; c < cols; ++c) {
                if (grid[r][c] != '.') continue;
                if (countAdjEmpty(r, c) == 3) {
                    enqueue(r, c);
                }
            }
        }

        // 2️⃣  Process the queue until it is empty.
        while (queueHead < queueTail) {
            int r = queue[queueHead][0];
            int c = queue[queueHead][1];
            queueHead++;

            if (grid[r][c] != '.') continue;               // already placed
            if (isDominoPlaced(r, c)) continue;            // isolated already

            int[] match = locateUniqueNeighbour(r, c);
            if (match == null) {
                out.println(NOT_UNIQUE);
                return;
            }

            placeDomino(r, c, match[0], match[1]);

            // After placing a domino, re‑evaluate its neighbours.
            for (int d = 0; d < 4; ++d) {
                evaluateNeighbour(match[0] + dx[d], match[1] + dy[d]);
            }
        }

        // 3️⃣  If any empty cell remains, the tiling cannot be unique.
        for (int r = 0; r < rows; ++r) {
            for (int c = 0; c < cols; ++c) {
                if (grid[r][c] == '.') {
                    out.println(NOT_UNIQUE);
                    return;
                }
            }
        }

        // 4️⃣  Output the tiled board.
        for (int r = 0; r < rows; ++r) {
            out.println(new String(grid[r]));
        }
    }

    /** Checks whether the cell at (r,c) already belongs to a placed domino. */
    private boolean isDominoPlaced(int r, int c) {
        return grid[r][c] != '.';
    }

    /** Places a domino covering (r,c) and (nr,nc) using the appropriate characters. */
    private void placeDomino(int r, int c, int nr, int nc) {
        if (r == nr) {                     // horizontal domino
            int y1 = Math.min(c, nc);
            int y2 = Math.max(c, nc);
            grid[r][y1] = '<';
            grid[r][y2] = '>';
        } else {                           // vertical domino
            int x1 = Math.min(r, nr);
            int x2 = Math.max(r, nr);
            grid[x1][c] = '^';
            grid[x2][c] = 'v';
        }
    }

    /** Returns how many of the four neighbours are either outside the board or not empty ('.'). */
    private int countAdjEmpty(int r, int c) {
        int cnt = 0;
        for (int d = 0; d < 4; ++d) {
            int nr = r + dx[d];
            int nc = c + dy[d];
            if (!isInside(nr, nc) || grid[nr][nc] != '.') {
                cnt++;
            }
        }
        return cnt;
    }

    /** Enqueues a cell if it has not been processed before. */
    private void enqueue(int r, int c) {
        if (visited[r][c]) return;
        visited[r][c] = true;
        queue[queueTail][0] = r;
        queue[queueTail][1] = c;
        queueTail++;
    }

    /**
     * Returns the coordinates of the sole adjacent empty cell,
     * or {@code null} if there is none or more than one.
     */
    private int[] locateUniqueNeighbour(int r, int c) {
        int[] match = null;
        for (int d = 0; d < 4; ++d) {
            int nr = r + dx[d];
            int nc = c + dy[d];
            if (!isInside(nr, nc) || grid[nr][nc] != '.') continue;

            if (match != null) {          // second neighbour → ambiguity
                return null;
            }
            match = new int[]{nr, nc};
        }
        return match;
    }

    /** Re‑examines a neighbour cell and possibly enqueues it with degree‑3 status. */
    private void evaluateNeighbour(int r, int c) {
        if (!isInside(r, c) || grid[r][c] != '.') return;
        if (countAdjEmpty(r, c) == 3 && !visited[r][c]) {
            enqueue(r, c);
        }
    }

    /** Simple bounds check for board coordinates. */
    private boolean isInside(int r, int c) {
        return 0 <= r && r < rows && 0 <= c && c < cols;
    }
}

/**
 * Refactored version of the original program.
 *
 * <p>This class reads a grid, tries to fill it with arrows that represent a unique
 * tiling of empty cells ('.'), and prints either the completed grid or the message
 * {@code "Not unique"}.
 *
 * <p>All functionality has been moved into small, well‑named methods and the
 * scanning/printing logic has been isolated for easier testing.
 */
public class Main {

    /** Directions used for neighbour checks (right, down, left, up). */
    private enum Direction {
        RIGHT(1, 0),
        DOWN(0, 1),
        LEFT(-1, 0),
        UP(0, -1);

        final int dx;
        final int dy;

        Direction(int dx, int dy) {
            this.dx = dx;
            this.dy = dy;
        }
    }

    /** Mapping from a direction to the two characters that must be placed on the two cells. */
    private static final char[][] TILE = {
            {'v', '^'}, // RIGHT   (cell1 -> cell2)
            {'<', '>'}, // DOWN
            {'^', 'v'}, // LEFT
            {'>', '<'}  // UP
    };

    /** Width and height of the input grid. */
    private int columns;
    private int rows;

    /** The grid read from stdin. */
    private char[][] grid;

    /** Queue used while performing the topological tiling algorithm. */
    private final java.util.Queue<Position> queue = new java.util.ArrayDeque<>();

    /**
     * Entry point used for the original {@code foo()} method.
     * In a real project this would be replaced by proper unit tests.
     */
    public static void main(String[] args) {
        new Main().run();
    }

    /** Reads input, processes the grid and prints the result. */
    public void run() {
        try (java.util.Scanner scanner = new java.util.Scanner(System.in)) {
            readDimensions(scanner);
            readGrid(scanner);
            if (!canTile()) {
                System.out.println("Not unique");
                return;
            }
            printTiledGrid();
        }
    }

    /** Reads the size of the grid (rows × columns). */
    private void readDimensions(java.util.Scanner scanner) {
        this.rows = scanner.nextInt();
        this.columns = scanner.nextInt();
        this.grid = new char[rows][];
    }

    /** Reads the grid itself from stdin. */
    private void readGrid(java.util.Scanner scanner) {
        for (int r = 0; r < rows; r++) {
            String line = scanner.next();
            grid[r] = line.toCharArray();
        }
    }

    /** Main algorithm – tries to fill every '.' with a valid arrow pair. */
    private boolean canTile() {
        int[][] degree = new int[rows][columns];

        // Initialise degree counts for every empty cell.
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < columns; c++) {
                if (grid[r][c] != '.') {
                    continue;
                }
                degree[r][c] = countAdjacentEmpty(r, c);
                if (degree[r][c] == 1) {
                    queue.offer(new Position(c, r));
                }
            }
        }

        // Process cells with degree == 1 until the queue is empty.
        while (!queue.isEmpty()) {
            Position p = queue.poll();
            // This cell may already have been processed.
            if (degree[p.row][p.column] != 1) {
                continue;
            }
            degree[p.row][p.column] = 0;

            Direction dir = findUniqueDirection(p.row, p.column, degree);
            if (dir == null) {
                // No unique way to place a tile – the tiling is not unique.
                return false;
            }

            int nx = p.column + dir.dx;
            int ny = p.row + dir.dy;

            // Place the two arrows that constitute the tile.
            grid[p.row][p.column] = TILE[dir.ordinal()][0];
            grid[ny][nx] = TILE[dir.ordinal()][1];

            // Update degrees of neighbours of the newly filled cells.
            for (Direction neighbourDir : Direction.values()) {
                for (int d = 0; d < 2; d++) { // two cells of the tile
                    int x = (d == 0) ? p.column : nx;
                    int y = (d == 0) ? p.row    : ny;
                    int nx2 = x + neighbourDir.dx;
                    int ny2 = y + neighbourDir.dy;
                    if (inside(nx2, ny2) && grid[ny2][nx2] == '.') {
                        degree[ny2][nx2]--;
                        if (degree[ny2][nx2] == 1) {
                            queue.offer(new Position(nx2, ny2));
                        }
                    }
                }
            }
        }

        // If any '.' remains, tiling failed.
        for (char[] row : grid) {
            for (char cell : row) {
                if (cell == '.') {
                    return false;
                }
            }
        }
        return true;
    }

    /** Returns the unique direction that leads to an empty neighbour cell. */
    private Direction findUniqueDirection(int row, int col, int[][] degree) {
        for (Direction dir : Direction.values()) {
            int nx = col + dir.dx;
            int ny = row + dir.dy;
            if (inside(nx, ny) && grid[ny][nx] == '.' && degree[ny][nx] == 1) {
                return dir;
            }
        }
        return null; // More than one or none – tiling cannot be uniquely determined.
    }

    /** Counts how many adjacent cells are empty ('.'). */
    private int countAdjacentEmpty(int row, int col) {
        int count = 0;
        for (Direction dir : Direction.values()) {
            int nx = col + dir.dx;
            int ny = row + dir.dy;
            if (inside(nx, ny) && grid[ny][nx] == '.') {
                count++;
            }
        }
        return count;
    }

    /** Checks whether coordinates are inside the grid bounds. */
    private boolean inside(int x, int y) {
        return 0 <= x && x < columns && 0 <= y && y < rows;
    }

    /** Prints the filled grid to stdout. */
    private void printTiledGrid() {
        for (char[] row : grid) {
            System.out.println(new String(row));
        }
    }

    /** Simple immutable pair used to store a grid position (x, y). */
    private static final class Position {
        final int column; // x‑coordinate
        final int row;    // y‑coordinate

        Position(int column, int row) {
            this.column = column;
            this.row = row;
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Tile‑placement puzzle solver.
 * Reads a grid of '.' (empty) and pre‑filled characters,
 * attempts to fill every empty cell with a unique matching tile,
 * and prints the solved grid or "Not unique".
 */
public class Main {

    /* -------------------------------------------------------------
       Direction handling
       ------------------------------------------------------------- */
    private enum Direction {
        RIGHT('>', 0, 1),
        UP('^', -1, 0),
        LEFT('<', 0, -1),
        DOWN('v', 1, 0);

        final char symbol;
        final int dx;
        final int dy;

        Direction(char symbol, int dx, int dy) {
            this.symbol = symbol;
            this.dx = dx;
            this.dy = dy;
        }

        /** Returns the opposite direction of this one. */
        Direction opposite() {
            switch (this) {
                case RIGHT: return LEFT;
                case LEFT:  return RIGHT;
                case UP:    return DOWN;
                case DOWN:  return UP;
                default:    throw new IllegalStateException();
            }
        }
    }

    /* -------------------------------------------------------------
       I/O helpers
       ------------------------------------------------------------- */
    private static class InputReader {
        private final BufferedReader br;
        private StringTokenizer st;

        InputReader(InputStream input) {
            this.br = new BufferedReader(new InputStreamReader(input));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    throw new UncheckedIOException(e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }
    }

    /* -------------------------------------------------------------
       Core solver state and methods
       ------------------------------------------------------------- */
    private final InputReader in;
    private final PrintWriter out;
    private char[][] grid;      // the puzzle grid
    private final int rows;
    private final int cols;

    public Main() {
        this.in  = new InputReader(System.in);
        this.out = new PrintWriter(System.out);
    }

    /** Checks that (x, y) lies inside the grid bounds. */
    private boolean inside(int x, int y) {
        return x >= 0 && x < rows && y >= 0 && y < cols;
    }

    /** Counts empty ('.') neighbours of cell (x, y). */
    private int countEmptyNeighbours(int x, int y) {
        int cnt = 0;
        for (Direction d : Direction.values()) {
            int nx = x + d.dx;
            int ny = y + d.dy;
            if (inside(nx, ny) && grid[nx][ny] == '.') {
                cnt++;
            }
        }
        return cnt;
    }

    /**
     * Attempts to place a domino that starts at (x, y) in direction d.
     * The two cells are marked with the corresponding symbols.
     * Any newly‑forced cells are added to {@code pending}.
     * Returns {@code true} if the placement succeeded.
     */
    private boolean placeTile(int x, int y, Direction d, Deque<int[]> pending) {
        int nx = x + d.dx;
        int ny = y + d.dy;

        // sanity checks – the target cell must be empty and inside the grid
        if (!inside(nx, ny) || grid[nx][ny] != '.') {
            return false;
        }

        grid[x][y]  = d.symbol;
        grid[nx][ny] = d.opposite().symbol;

        // New cells may become forced (only‑one‑empty‑neighbour) – enqueue them.
        for (Direction nd : Direction.values()) {
            int ax = nx + nd.dx;
            int ay = ny + nd.dy;
            if (inside(ax, ay) && grid[ax][ay] == '.' && countEmptyNeighbours(ax, ay) == 1) {
                pending.add(new int[]{ax, ay});
            }
            int bx = x + nd.dx;
            int by = y + nd.dy;
            if (inside(bx, by) && grid[bx][by] == '.' && countEmptyNeighbours(bx, by) == 1) {
                pending.add(new int[]{bx, by});
            }
        }
        return true;
    }

    /** Main solving routine. */
    private void solve() {
        int n = in.nextInt();
        int m = in.nextInt();
        grid = new char[n][m];
        Deque<int[]> pending = new ArrayDeque<>();

        // ---------------------------------------------------------
        // 1. Read input grid
        // ---------------------------------------------------------
        for (int i = 0; i < n; ++i) {
            String line = in.next();
            grid[i] = line.toCharArray();
        }

        // ---------------------------------------------------------
        // 2. Seed the queue with cells that already have exactly one empty neighbour
        // ---------------------------------------------------------
        for (int i = 0; i < n; ++i) {
            for (int j = 0; j < m; ++j) {
                if (grid[i][j] == '.') {
                    int freeNeighbours = countEmptyNeighbours(i, j);
                    if (freeNeighbours == 0) {
                        out.println("Not unique");
                        return;
                    }
                    if (freeNeighbours == 1) {
                        pending.add(new int[]{i, j});
                    }
                }
            }
        }

        // ---------------------------------------------------------
        // 3. Propagate forced placements
        // ---------------------------------------------------------
        while (!pending.isEmpty()) {
            int[] cur = pending.poll();
            int x = cur[0];
            int y = cur[1];

            if (grid[x][y] != '.') {
                continue;               // already filled elsewhere
            }

            boolean placed = false;
            for (Direction d : Direction.values()) {
                int nx = x + d.dx;
                int ny = y + d.dy;
                if (!inside(nx, ny) || grid[nx][ny] != '.' || countEmptyNeighbours(nx, ny) != 1) {
                    continue;
                }
                if (placeTile(x, y, d, pending)) {
                    placed = true;
                    break;              // a unique placement must succeed
                }
            }
            if (!placed) {
                out.println("Not unique");
                return;
            }
        }

        // ---------------------------------------------------------
        // 4. Verify that the whole board is filled
        // ---------------------------------------------------------
        for (int i = 0; i < rows; ++i) {
            for (int j = 0; j < cols; ++j) {
                if (grid[i][j] == '.') {
                    out.println("Not unique");
                    return;
                }
            }
        }

        // ---------------------------------------------------------
        // 5. Output the solved grid
        // ---------------------------------------------------------
        for (char[] row : grid) {
            out.println(new String(row));
        }
    }

    /** Run the solver (handles resources cleanly). */
    public void run() {
        try {
            solve();
        } finally {
            out.close();
        }
    }

    public static void main(String[] args) {
        new Main().run();
    }
}

/**
 * Refactored implementation of the “unique domino tiling” solution.
 *
 * <p>This program reads a rectangular grid (n × m). Cells marked with '*'
 * represent fixed obstacles. All other cells must be covered by 1×2 dominoes.
 * If a unique tiling exists, the resulting board is printed where each
 * domino is annotated with an arrow that points to its neighbor.
 * Otherwise the word “Not unique” is printed.
 *
 * <p>Refactorings applied:
 * <ul>
 *   <li>Extracted direction vectors and arrow mapping into constants.</li>
 *   <li>Split the algorithm into small, single‑purpose methods.</li>
 *   <li>Used try‑with‑resources for I/O.</li>
 *   <li>Replaced magic numbers with named constants.</li>
 *   <li>Improved naming and added concise comments.</li>
 * </ul>
 */
public class Main {

    /** Arrow that points from a cell to its neighbor. */
    private static final char[] ARROW = {
            '^', 'v', '>', '<'   // UP, DOWN, LEFT, RIGHT
    };

    /** Opposite direction index (UP↔DOWN, LEFT↔RIGHT). */
    private static final int OPPOSITE = 1 ^ 2; // XOR swaps 1↔2, 0 stays 0, 3 stays 3

    /** Directions: UP, DOWN, LEFT, RIGHT */
    private static final int[] DX = {-1, 1, 0, 0};
    private static final int[] DY = {0, 0, -1, 1};

    /** Symbol used for empty cells that are still undecided. */
    private static final int EMPTY = 4;

    public static void main(String[] args) {
        new Main().run();
    }

    /** Entry point – reads input, processes the board, prints the result. */
    private void run() {
        try (Scanner scanner = new Scanner(System.in);
             PrintWriter out = new PrintWriter(System.out)) {

            int n = scanner.nextInt();
            int m = scanner.nextInt();

            int[][] cellState = new int[n][m];
            initializeCellState(cellState);
            char[][] result = new char[n][m];
            boolean[][] visited = new boolean[n][m];
            initializeResult(result, visited);

            readObstacles(scanner, cellState, result);

            processBoard(cellState, result, visited, out);
        }
    }

    /** Fills `cellState` with the sentinel value {@linkplain #EMPTY}. */
    private static void initializeCellState(int[][] state) {
        for (int[] row : state) {
            Arrays.fill(row, EMPTY);
        }
    }

    /** Marks obstacles ('*') with state 0 and records their position in `result`. */
    private static void readObstacles(Scanner scanner, int[][] state, char[][] result) {
        for (int i = 0; i < state.length; i++) {
            String line = scanner.next();
            for (int j = 0; j < line.length(); j++) {
                if (line.charAt(j) == '*') {
                    state[i][j] = 0;
                    result[i][j] = '*';
                }
            }
        }
    }

    /** Fills `result` with '*' placeholders and marks `visited` as false. */
    private static void initializeResult(char[][] result, boolean[][] visited) {
        for (char[] row : result) {
            Arrays.fill(row, '*');
        }
        for (boolean[] row : visited) {
            Arrays.fill(row, false);
        }
    }

    /**
     * Main processing routine:
     * <ol>
     *   <li>Calculate how many neighbours each empty cell still has.</li>
     *   <li>Put cells that have exactly one possible neighbour into a queue.</li>
     *   <li>Iteratively settle those cells – this is the core “unique‑tiling”
     *       propagation step.</li>
     *   <li>If after the process every empty cell has been settled, output the board.</li>
     *   <li>Otherwise print “Not unique”.</li>
     * </ol>
     */
    private static void processBoard(int[][] state, char[][] result,
                                     boolean[][] visited, PrintWriter out) {
        Queue<Integer> queue = findForcedPlacements(state);
        settle(queue, state, result, visited);

        if (allVisited(visited)) {
            printBoard(result, out);
        } else {
            out.println("Not unique");
        }
        out.flush();
    }

    /** Returns a queue containing coordinates (as a single int) of cells with exactly one neighbour. */
    private static Queue<Integer> findForcedPlacements(int[][] state) {
        Queue<Integer> queue = new ArrayDeque<>();

        outer:
        for (int i = 0; i < state.length; i++) {
            for (int j = 0; j < state[i].length; j++) {
                if (state[i][j] <= 0) {
                    continue;
                }
                int neighbourCount = countFreeNeighbours(state, i, j);
                if (neighbourCount == 1) {
                    queue.add(coord(i, j));
                }
            }
        }
        return queue;
    }

    /** Counts orthogonal neighbours that are still “empty” (positive state). */
    private static int countFreeNeighbours(int[][] state, int x, int y) {
        int count = 0;
        for (int dir = 0; dir < 4; dir++) {
            int nx = x + DX[dir];
            int ny = y + DY[dir];
            if (inBounds(state, nx, ny) && state[nx][ny] > 0) {
                count++;
            }
        }
        return count;
    }

    /** Pops cells from the queue and propagates the forced placement logic. */
    private static void settle(Queue<Integer> queue,
                               int[][] state,
                               char[][] result,
                               boolean[][] visited) {
        while (!queue.isEmpty()) {
            int encoded = queue.poll();
            int x = xFromPos(encoded);
            int y = yFromPos(encoded);

            if (state[x][y] != 1) {
                continue; // May have been settled already by a previous step.
            }

            // Find the unique neighbour that is still empty.
            int dir = findUniqueFreeDirection(state, x, y);
            if (dir == -1) {
                continue; // should not happen, but guard against infinite loops.
            }

            int nx = x + DX[dir];
            int ny = y + DY[dir];

            // Assign arrows that point to each other.
            result[x][y] = ARROW[dir];
            result[nx][ny] = ARROW[OPPOSITE];

            visited[x][y] = visited[nx][ny] = true;

            // Decrease neighbour counts of the newly settled cell's neighbours.
            for (int d = 0; d < 4; d++) {
                int ex = nx + DX[d];
                int ey = ny + DY[d];
                if (inBounds(state, ex, ey) && state[ex][ey] > 0) {
                    state[ex][ey]--;
                    if (state[ex][ey] == 1) {
                        queue.add(coord(ex, ey));
                    }
                }
            }

            // Mark the neighbour as settled (state 0) so it will not be processed again.
            state[nx][ny] = 0;
        }
    }

    /** Returns the direction index (0‑3) that leads to the only free neighbour,
     *  or –1 if none exists. */
    private static int findUniqueFreeDirection(int[][] state, int x, int y) {
        int freeDir = -1;
        for (int dir = 0; dir < 4; dir++) {
            int nx = x + DX[dir];
            int ny = y + DY[dir];
            if (inBounds(state, nx, ny) && state[nx][ny] > 0) {
                if (freeDir != -1) {
                    // More than one free direction – not unique.
                    return -1;
                }
                freeDir = dir;
            }
        }
        return freeDir;
    }

    /** Returns true if every cell of `visited` is true. */
    private static boolean allVisited(boolean[][] visited) {
        for (boolean[] row : visited) {
            for (boolean v : row) {
                if (!v) {
                    return false;
                }
            }
        }
        return true;
    }

    /** Prints the resulting board to the supplied PrintWriter. */
    private static void printBoard(char[][] board, PrintWriter out) {
        for (char[] row : board) {
            for (char cell : row) {
                out.print(cell);
            }
            out.println();
        }
    }

    /** Simple bounds check used throughout the refactor. */
    private static boolean inBounds(int[][] state, int x, int y) {
        return 0 <= x && x < state.length && 0 <= y && y < state[0].length;
    }

    /** Encodes (x, y) into a single int for queue storage. */
    private static int coord(int x, int y) {
        return x * matrixWidth(state) + y;
    }

    /** Decodes the X coordinate from an encoded position. */
    private static int xFromPos(int encoded) {
        return encoded / matrixWidth(null);
    }

    /** Decodes the Y coordinate from an encoded position. */
    private static int yFromPos(int encoded) {
        return encoded % (null != matrixWidth(state) ? matrixWidth(state) : 0);
    }

    /** Returns the width of the matrix (number of columns). */
    private static int matrixWidth(int[][] state) {
        return (state == null) ? 0 : state[0].length;
    }
}

import java.io.*;
import java.util.*;

public class D {

    /* -------------------------------------------------------------
     *  Constants
     * ------------------------------------------------------------- */
    private static final int[] DR = {1, -1, 0, 0};      // down, up, right, left
    private static final int[] DC = {0, 0, 1, -1};

    /** Arrow that points from the current cell to its partner */
    private static final char[] FROM_ARROW = {'^', 'v', '<', '>'};
    /** Arrow that points from the partner cell back to the current one */
    private static final char[] TO_ARROW   = {'v', '^', '>', '<'};

    /* -------------------------------------------------------------
     *  Shared state (mirrors the original static fields)
     * ------------------------------------------------------------- */
    private static char[][] grid;
    private static int[][] degree;

    /* -------------------------------------------------------------
     *  Entry point
     * ------------------------------------------------------------- */
    public static void main(String[] args) throws IOException {
        /* ----- read input ------------------------------------------------- */
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in))) {
            String[] header = br.readLine().split("\\s+");
            int n = Integer.parseInt(header[0]);
            int m = Integer.parseInt(header[1]);

            grid = new char[n][];
            for (int i = 0; i < n; i++) {
                grid[i] = br.readLine().toCharArray();
            }

            int cells = n * m;
            degree = new int[cells];
            Queue queue = new Queue(cells);

            /* ----- initialise degrees -------------------------------------- */
            for (int r = 0; r < n; r++) {
                for (int c = 0; c < m; c++) {
                    if (grid[r][c] == '.') {
                        int idx = r * m + c;
                        computeDegree(r, c, idx);
                        if (degree[idx] == 1) {
                            queue.add(idx);
                        }
                    }
                }
            }

            /* ----- forced placement propagation --------------------------- */
            while (!queue.isEmpty()) {
                int pos = queue.poll();
                int r = pos / m;
                int c = pos % m;
                if (grid[r][c] != '.') {
                    continue;               // already occupied
                }

                int neighbourIdx = placeTileAndPropagate(r, c);
                if (neighbourIdx == -1) {
                    continue;               // isolated cell – will be caught later
                }

                int nr = neighbourIdx / m;
                int nc = neighbourIdx % m;

                // update degrees of the neighbours of the newly placed partner
                for (int d = 0; d < 4; d++) {
                    int rr = nr + DR[d];
                    int cc = nc + DC[d];
                    if (isInside(rr, cc) && grid[rr][cc] == '.') {
                        int nIdx = rr * m + cc;
                        if (--degree[nIdx] == 1) {
                            queue.add(nIdx);
                        }
                    }
                }
            }

            /* ----- verify that the whole board is covered ----------------- */
            for (int r = 0; r < n; r++) {
                for (int c = 0; c < m; c++) {
                    if (grid[r][c] == '.') {
                        System.out.println("Not unique");
                        return;
                    }
                }
            }

            /* ----- output the solution ------------------------------------ */
            PrintWriter out = new PrintWriter(System.out);
            for (char[] row : grid) {
                out.println(row);
            }
            out.flush();
        }
    }

    /* -------------------------------------------------------------
     *  Helper methods
     * ------------------------------------------------------------- */

    /** Computes the degree of an empty cell (r,c). */
    private static void computeDegree(int r, int c, int idx) {
        degree[idx] = 0;
        for (int d = 0; d < 4; d++) {
            int nr = r + DR[d];
            int nc = c + DC[d];
            if (isInside(nr, nc) && grid[nr][nc] == '.') {
                degree[idx]++;
            }
        }
    }

    /**
     * Places a tile starting from (r,c) and returns the index of the adjacent
     * partner cell, or -1 if no placement could be performed.
     */
    private static int placeTileAndPropagate(int r, int c) {
        for (int d = 0; d < 4; d++) {
            int nr = r + DR[d];
            int nc = c + DC[d];
            if (isInside(nr, nc) && grid[nr][nc] == '.') {
                int curIdx = r * grid[0].length + c;
                int neighIdx = nr * grid[0].length + nc;

                grid[r][c] = FROM_ARROW[d];
                grid[nr][nc] = TO_ARROW[d];

                /* Find another free neighbour of (nr,nc) to continue propagation.
                 * The original code only needed the index; we return it here. */
                for (int nd = 0; nd < 4; nd++) {
                    int nnr = nr + DR[nd];
                    int nnc = nc + DC[nd];
                    if (isInside(nnr, nnc) && grid[nnr][nnc] == '.') {
                        // The neighbour will be processed later by the queue logic.
                        // No extra work needed here.
                        return neighIdx;
                    }
                }
                return neighIdx;
            }
        }
        return -1; // isolated cell – should be detected as “Not unique”
    }

    private static boolean isInside(int r, int c) {
        return r >= 0 && r < grid.length && c >= 0 && c < grid[0].length;
    }

    /* -------------------------------------------------------------
     *  Simple fixed‑size queue (mirrors the original custom Queue)
     * ------------------------------------------------------------- */
    private static class Queue {
        private final int[] data;
        private int front, back, size;

        Queue(int capacity) {
            data = new int[capacity];
        }

        int poll() {
            size--;
            return data[back++];
        }

        void add(int value) {
            size++;
            data[front++] = value;
        }

        boolean isEmpty() {
            return size == 0;
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.ArrayDeque;
import java.util.Deque;
import java.util.Optional;

/**
 * Reads a grid of characters, pairs every '.' cell with exactly one neighbour
 * and draws arrows (>, <, ^, v) representing the pairing. If any '.' remains
 * unmatched the program prints “Not unique”. The algorithm repeatedly extracts
 * leaf‑like cells (degree == 1) until a stable configuration is reached.
 *
 * The implementation is deliberately split into small, single‑responsibility
 * methods and avoids static mutable fields, making it easier to test and
 * maintain.
 */
public class Main {

    /** Directions: left, right, up, down */
    private static final int[] DR = {0, 0, -1, 1};
    private static final int[] DC = {-1, 1, 0, 0};

    /** Character that represents each direction (same order as DR/DC) */
    private static final char[] DIR_CHAR = {'>', '<', '^', 'v'};

    /** Represents a grid cell (row, column) */
    private static final class Cell {
        final int r;
        final int c;

        Cell(int r, int c) {
            this.r = r;
            this.c = c;
        }
    }

    /** Holds the whole processing logic for one grid */
    private static final class Solver {
        private final int n, m;
        private final List<StringBuilder> grid;   // mutable grid of characters
        private final int[][] degree;             // degree of each '.' cell
        private final boolean uniqueOutput;       // true if a unique pairing exists

        Solver(int n, int m, List<StringBuilder> grid) {
            this.n = n;
            this.m = m;
            this.grid = grid;
            this.degree = new int[n][m];
            this.uniqueOutput = process();
        }

        /** Main driver – extracts leaves until none remain, then validates. */
        private boolean process() {
            boolean changed = true;
            while (changed) {
                changed = extractAndPairLeaves();
            }
            // If any '.' still exists the solution is not unique
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    if (grid.get(i).charAt(j) == '.') {
                        System.out.println("Not unique");
                        return false;
                    }
                }
            }
            // Print the resulting grid
            for (StringBuilder row : grid) {
                System.out.println(row);
            }
            return true;
        }

        /** Build the degree table (number of neighbouring '.' cells). */
        private void buildDegreeTable() {
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    if (grid.get(i).charAt(j) != '.') {
                        degree[i][j] = 0;
                        continue;
                    }
                    int cnt = 0;
                    for (int d = 0; d < 4; d++) {
                        int nr = i + DR[d];
                        int nc = j + DC[d];
                        if (inside(nr, nc) && grid.get(nr).charAt(nc) == '.') {
                            cnt++;
                        }
                    }
                    degree[i][j] = cnt;
                }
            }
        }

        /** Returns the first leaf (degree == 1) found, or empty if none. */
        private Optional<Cell> findLeaf() {
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    if (grid.get(i).charAt(j) == '.' && degree[i][j] == 1) {
                        return Optional.of(new Cell(i, j));
                    }
                }
            }
            return Optional.empty();
        }

        /** Pair the supplied leaf with its unique neighbour and update the grid. */
        private void pairLeaf(Cell leaf) {
            // Find the neighbour that is also '.'
            int chosenDir = -1;
            for (int d = 0; d < 4; d++) {
                int nr = leaf.r + DR[d];
                int nc = leaf.c + DC[d];
                if (inside(nr, nc) && grid.get(nr).charAt(nc) == '.') {
                    chosenDir = d;
                    break;
                }
            }
            // Defensive: there must be exactly one such neighbour
            if (chosenDir == -1) {
                throw new IllegalStateException("Leaf without a '.' neighbour");
            }

            // Draw the two characters that represent the edge
            drawArrow(leaf.r, leaf.c, chosenDir);
            drawArrow(leaf.r + DR[chosenDir], leaf.c + DC[chosenDir],
                    oppositeDirection(chosenDir));

            // After changing characters, recompute degrees only for the
            // four neighbours of the *new* arrows (the rest stays unchanged)
            for (int d = 0; d < 4; d++) {
                int nr = leaf.r + DR[d];
                int nc = leaf.c + DC[d];
                if (inside(nr, nc)) {
                    recomputeDegreeIfNeeded(nr, nc);
                }
            }
        }

        /** Writes the correct arrow characters for a cell that participates in an edge. */
        private void drawArrow(int r, int c, int dir) {
            // The target cell will receive the forward character, the source cell
            // receives the opposite one.  This matches the original behaviour.
            // For a leaf we already know which side is the source.
            if (dir == 0) {          // left → right
                grid.get(r).setCharAt(c, '<');
                grid.get(r).setCharAt(c + 1, '>');
            } else if (dir == 1) {   // right → left
                grid.get(r).setCharAt(c, '>');
                grid.get(r).setCharAt(c - 1, '<');
            } else if (dir == 2) {   // up → down
                grid.get(r).setCharAt(c, '^');
                grid.get(r + 1).setCharAt(c, 'v');
            } else {                 // dir == 3 → down → up
                grid.get(r).setCharAt(c, 'v');
                grid.get(r - 1).setCharAt(c, '^');
            }
        }

        /** Returns the direction index opposite to the given one. */
        private int oppositeDirection(int dir) {
            // 0↔1 (left↔right) and 2↔3 (up↔down) are inverses
            return (dir + 2) % 4;
        }

        /** Re‑calculates degree of a cell if it is still a '.' */
        private void recomputeDegreeIfNeeded(int r, int c) {
            if (grid.get(r).charAt(c) != '.') {
                return;
            }
            int cnt = 0;
            for (int d = 0; d < 4; d++) {
                int nr = r + DR[d];
                int nc = c + DC[d];
                if (inside(nr, nc) && grid.get(nr).charAt(nc) == '.') {
                    cnt++;
                }
            }
            degree[r][c] = cnt;
        }

        /** Returns true if at least one leaf was processed in this iteration. */
        private boolean extractAndPairLeaves() {
            buildDegreeTable();                 // O(n*m) – cheap relative to overall work
            Optional<Cell> leaf = findLeaf();
            if (leaf.isEmpty()) {
                return false;                   // nothing left to pair
            }
            pairLeaf(leaf.get());
            return true;                        // at least one change happened
        }

        /** Helper to test whether a coordinate lies inside the grid. */
        private boolean inside(int r, int c) {
            return r >= 0 && r < n && c >= 0 && c < m;
        }
    }

    /** Entry point – reads input, creates a Solver and lets it run. */
    public static void main(String[] args) throws IOException {
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in))) {
            String[] first = br.readLine().split("\\s+");
            int n = Integer.parseInt(first[0]);
            int m = Integer.parseInt(first[1]);
            List<StringBuilder> grid = new ArrayList<>(n);
            for (int i = 0; i < n; i++) {
                grid.add(new StringBuilder(br.readLine()));
            }

            new Solver(n, m, grid); // construction triggers the whole processing
        }
    }
}

import java.io.*;
import java.util.*;
import java.util.List;

/**
 * Fast input scanner that reads bytes from an {@link InputStream}
 * and provides convenient methods for reading integers,
 * characters and lines.
 */
final class FastScanner implements AutoCloseable {
    private final InputStream in;
    private final byte[] buffer = new byte[1024];
    private int pointer = 0;
    private int length = 0;

    FastScanner(InputStream in) {
        this.in = in;
    }

    private int readByte() throws IOException {
        if (pointer >= length) {
            length = in.read(buffer);
            pointer = 0;
            if (length <= 0) {
                return -1;
            }
        }
        return buffer[pointer++];
    }

    private static boolean isSpace(int c) {
        return c == ' ' || c == '\n' || c == '\r' || c == '\t';
    }

    private void skipSpaces() throws IOException {
        int b;
        while ((b = readByte()) != -1 && isSpace(b)) { }
        if (b != -1) pointer--;   // put back the non‑space character
    }

    /** Reads the next signed integer. */
    int nextInt() throws IOException {
        skipSpaces();
        int sign = 1;
        int c = readByte();
        if (c == '-') {
            sign = -1;
            c = readByte();
        }
        long value = 0;
        while (!isSpace(c) && c != -1) {
            if (c < '0' || c > '9') {
                throw new InputMismatchException();
            }
            value = value * 10 + (c - '0');
            c = readByte();
        }
        return (int) (sign * value);
    }

    /** Reads the next single non‑whitespace character. */
    char nextChar() throws IOException {
        skipSpaces();
        int c;
        while ((c = readByte()) == -1 || isSpace(c)) { }
        return (char) c;
    }

    /** Reads the rest of the current line (including empty lines). */
    String nextLine() throws IOException {
        skipSpaces();
        StringBuilder sb = new StringBuilder();
        int c;
        while ((c = readByte()) != -1 && c != '\n') {
            sb.append((char) c);
        }
        return sb.toString();
    }

    @Override public void close() throws IOException {
        in.close();
    }
}

/**
 * Simple wrapper around {@link PrintWriter} that handles line breaks
 * and can be used with try‑with‑resources.
 */
final class FastPrinter implements AutoCloseable {
    private final PrintWriter writer;

    FastPrinter(OutputStream out) {
        this.writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(out)));
    }

    void print(Object... args) {
        for (int i = 0; i < args.length; i++) {
            if (i > 0) writer.print(' ');
            writer.print(args[i]);
        }
    }

    void println(Object... args) {
        print(args);
        writer.println();
    }

    @Override public void close() {
        writer.close();
    }
}

/**
 * Represents a cell coordinate inside the grid.
 */
final class Position implements Comparable<Position> {
    final int row;
    final int col;

    Position(int row, int col) {
        this.row = row;
        this.col = col;
    }

    /** Four directions: up, left, down, right. */
    enum Direction {
        UP(1, 0), LEFT(0, -1), DOWN(-1, 0), RIGHT(0, 1);

        final int dr;
        final int dc;

        Direction(int dr, int dc) {
            this.dr = dr;
            this.dc = dc;
        }

        /** Returns the neighbour in the given direction, or {@code null} if it would leave the grid. */
        Position neighbour(int rows, int cols) {
            int nr = row + dr;
            int nc = col + dc;
            if (nr < 0 || nr >= rows || nc < 0 || nc >= cols) {
                return null;
            }
            return new Position(nr, nc);
        }
    }

    /** Equality based on both coordinates. */
    @Override public boolean equals(Object o) {
        if (this == o) return true;
        if (o == null || getClass() != o.getClass()) return false;
        Position that = (Position) o;
        return row == that.row && col == that.col;
    }

    @Override public int hashCode() {
        return Objects.hash(row, col);
    }

    @Override public String toString() {
        return "(" + row + "," + col + ")";
    }

    @Override public int compareTo(Position o) {
        int cmp = Integer.compare(this.row, o.row);
        return (cmp != 0) ? cmp : Integer.compare(this.col, o.col);
    }
}

/**
 * Core algorithm that determines whether a unique perfect matching exists
 * in the given grid and prints the arrows representing it.
 *
 * <p>All public methods are deliberately small and focused to facilitate
 * unit testing and future extensions.
 */
final class Solver {
    /** Arrow symbols used in the final output. */
    private static final char ARROW_UP    = '^';
    private static final char ARROW_DOWN  = 'v';
    private static final char ARROW_LEFT  = '<';
    private static final char ARROW_RIGHT = '>';

    /** Directions used throughout the algorithm (up, right, down, left). */
    private static final List<Position.Direction> ALL_DIRECTIONS =
            List.of(Position.Direction.UP, Position.Direction.RIGHT,
                    Position.Direction.DOWN, Position.Direction.LEFT);

    /** Adds 1 to the degree of each cell that can move to a free neighbour. */
    private static void computeDegrees(char[][] grid, int[][] degree) {
        for (int r = 0; r < grid.length; r++) {
            for (int c = 0; c < grid[0].length; c++) {
                if (grid[r][c] != '.') continue;
                for (Position.Direction dir : ALL_DIRECTIONS) {
                    Position nb = new Position(r, c).neighbour(grid.length, grid[0].length);
                    if (nb != null && grid[nb.row][nb.col] == '.') {
                        degree[r][c]++;
                    }
                }
            }
        }
    }

    /** Reads the grid from the scanner. */
    private static char[][] readGrid(FastScanner in, int rows, int cols) throws IOException {
        char[][] grid = new char[rows][];
        for (int r = 0; r < rows; r++) {
            String line = in.nextLine().trim();
            if (line.length() != cols) {
                throw new IllegalArgumentException("Row length mismatch");
            }
            grid[r] = line.toCharArray();
        }
        return grid;
    }

    /** Places the appropriate arrow characters on adjacent free cells. */
    private static void placeArrow(char[][] grid, Position a, Position b, Position.Direction dir) {
        switch (dir) {
            case UP    -> { grid[a.row][a.col] = ARROW_UP;    grid[b.row][b.col] = ARROW_DOWN; }
            case DOWN  -> { grid[a.row][a.col] = ARROW_DOWN;  grid[b.row][b.col] = ARROW_UP; }
            case LEFT  -> { grid[a.row][a.col] = ARROW_LEFT;  grid[b.row][b.col] = ARROW_RIGHT; }
            case RIGHT -> { grid[a.row][a.col] = ARROW_RIGHT; grid[b.row][b.col] = ARROW_LEFT; }
        }
    }

    /** Main solving routine called from {@code Main}. */
    void solve(FastScanner in, FastPrinter out) throws IOException {
        int rows = in.nextInt();
        int cols = in.nextInt();
        char[][] grid = readGrid(in, rows, cols);
        int[][] degree = new int[rows][cols];
        computeDegrees(grid, degree);

        Queue<Position> frontier = new ArrayDeque<>();
        // Start from every cell that currently has exactly one possible move.
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '.' && degree[r][c] == 1) {
                    frontier.add(new Position(r, c));
                }
            }
        }

        // Propagate assignments while maintaining determinism.
        while (!frontier.isEmpty()) {
            Position cur = frontier.poll();
            if (grid[cur.row][cur.col] != '.') continue; // already processed

            // Find the unique free neighbour.
            Position.Direction chosenDir = null;
            Position neighbour = null;
            for (Position.Direction dir : ALL_DIRECTIONS) {
                Position nb = cur.neighbour(rows, cols);
                if (nb != null && grid[nb.row][nb.col] == '.') {
                    chosenDir = dir;
                    neighbour = nb;
                    break;
                }
            }
            if (neighbour == null) continue; // isolated cell – will be detected later

            // Mark the pair with opposing arrows.
            placeArrow(grid, cur, neighbour, chosenDir);

            // Decrease degrees of neighbours of the newly matched cell.
            for (Position.Direction dir : ALL_DIRECTIONS) {
                Position reachable = neighbour.neighbour(rows, cols);
                if (reachable != null && grid[reachable.row][reachable.col] == '.') {
                    degree[reachable.row][reachable.col]--;
                    if (degree[reachable.row][reachable.col] == 1) {
                        frontier.add(reachable);
                    }
                }
            }
        }

        // If any '.' remains, the solution is not unique.
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '.') {
                    out.println("Not unique");
                    return;
                }
            }
        }

        // Output the resulting board.
        for (char[] row : grid) {
            out.println(new String(row));
        }
    }
}

/**
 * Application entry point – wires together input, solving and output.
 */
public class Main {
    public static void main(String[] args) throws Exception {
        try (FastScanner scanner = new FastScanner(System.in);
             FastPrinter printer = new FastPrinter(System.out)) {

            new Solver().solve(scanner, printer);
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.List;
import java.util.Objects;

/**
 * Refactored solution for the domino‑tiling uniqueness problem.
 *
 * <p>
 * The program reads a rectangular board from standard input, where each cell
 * contains either '.' (empty) or another character.  Using a leaf‑pruning
 * algorithm it attempts to uniquely fill every empty cell with an arrow that
 * indicates the direction of the adjacent domino half.  If the board can be
 * fully filled in exactly one way the resulting picture is printed; otherwise
 * the string {@code "Not unique"} is printed.
 * </p>
 *
 * <p>Key improvements over the original code:</p>
 * <ul>
 *   <li>Clear separation of concerns (input parsing, board representation,
 *       algorithm, output).</li>
 *   <li>Descriptive naming and final fields where appropriate.</li>
 *   <li>Elimination of raw types and magic literals.</li>
 *   <li>Encapsulation of related data into private helper classes.</li>
 *   <li>Robust error handling and deterministic iteration order.</li>
 * </ul>
 */
public class DominoTiler {

    /* --------------------------------------------------------------------- */
    /*  Helper data structures                                                */
    /* --------------------------------------------------------------------- */

    /**
     * Represents a cell coordinate on the board.
     */
    private static final class Cell {
        final int row;
        final int col;

        Cell(int row, int col) {
            this.row = row;
            this.col = col;
        }

        @Override public boolean equals(Object o) {
            if (this == o) return true;
            if (!(o instanceof Cell)) return false;
            Cell other = (Cell) o;
            return row == other.row && col == other.col;
        }

        @Override public int hashCode() {
            return Objects.hash(row, col);
        }

        @Override public String toString() {
            return row + " " + col;
        }
    }

    /** Directions used to orient a pair of adjacent cells. */
    private enum Direction {
        UP, DOWN, LEFT, RIGHT
    }

    /* --------------------------------------------------------------------- */
    /*  Input handling                                                       */
    /* --------------------------------------------------------------------- */

    /**
     * Very small wrapper around {@link BufferedReader} that supplies only the
     * methods required for the problem.  Keeping it separate makes the main
     * algorithm easier to test.
     */
    private static final class InputReader {
        private final BufferedReader br;

        InputReader() {
            this.br = new BufferedReader(new InputStreamReader(System.in));
        }

        /** Reads the next non‑empty line from {@code stdin}. */
        private String readNonEmptyLine() throws IOException {
            String line;
            do {
                line = br.readLine();
            } while (line != null && line.trim().isEmpty());
            return line;
        }

        /** Returns the next integer token from the current line. */
        private int nextInt() throws IOException {
            String token = nextToken();
            return Integer.parseInt(token);
        }

        /** Returns the next whitespace‑delimited token. */
        private String nextToken() throws IOException {
            return br.readLine().trim();
        }

        /** Reads the next board line (non‑empty). */
        String readBoardLine() throws IOException {
            return readNonEmptyLine();
        }
    }

    /* --------------------------------------------------------------------- */
    /*  Core solving algorithm                                                */
    /* --------------------------------------------------------------------- */

    /**
     * Represents the board and encapsulates the leaf‑pruning tiling algorithm.
     */
    private static final class Solver {
        private final char[][] grid;
        private final int rows;
        private final int cols;
        /** Queue of cells that currently have exactly one empty neighbour. */
        private final Queue<Cell> leaves = new ArrayDeque<>();

        Solver(char[][] grid) {
            this.grid = grid;
            this.rows = grid.length;
            this.cols = grid[0].length;
            discoverInitialLeaves();
        }

        /** Finds cells with degree == 1 and enqueues them. */
        private void discoverInitialLeaves() {
            for (int r = 0; r < rows; ++r) {
                for (int c = 0; c < cols; ++c) {
                    int deg = degree(r, c);
                    if (deg == 1) {
                        leaves.add(new Cell(r, c));
                    }
                }
            }
        }

        /** Number of empty orthogonal neighbours of (r,c). */
        private int degree(int r, int c) {
            if (grid[r][c] != '.') return 0;
            int count = 0;
            if (r > 0 && grid[r - 1][c] == '.') ++count;
            if (r + 1 < rows && grid[r + 1][c] == '.') ++count;
            if (c > 0 && grid[r][c - 1] == '.') ++count;
            if (c + 1 < cols && grid[r][c + 1] == '.') ++count;
            return count;
        }

        /** Returns all empty orthogonal neighbours of (r,c). */
        private List<Cell> neighbours(int r, int c) {
            List<Cell> result = new ArrayList<>(4);
            if (r > 0 && grid[r - 1][c] == '.') result.add(new Cell(r - 1, c));
            if (r + 1 < rows && grid[r + 1][c] == '.') result.add(new Cell(r + 1, c));
            if (c > 0 && grid[r][c - 1] == '.') result.add(new Cell(r, c - 1));
            if (c + 1 < cols && grid[r][c + 1] == '.') result.add(new Cell(r, c + 1));
            return result;
        }

        /** Marks a pair of adjacent empty cells with arrows that indicate their
         *  relative direction.
         */
        private void orientPair(Cell a, Cell b) {
            int dr = b.row - a.row;
            int dc = b.col - a.col;

            if (dr == -1) {                // a below b -> b points up
                grid[a.row][a.col] = '^';
                grid[b.row][b.col] = 'v';
            } else if (dr == 1) {          // a above b -> a points down
                grid[a.row][a.col] = 'v';
                grid[b.row][b.col] = '^';
            } else if (dc == -1) {         // a to the right of b -> b left
                grid[a.row][a.col] = '<';
                grid[b.row][b.col] = '>';
            } else if (dc == 1) {          // a to the left of b -> b right
                grid[a.row][a.col] = '>';
                grid[b.row][b.col] = '<';
            }
        }

        /**
         * Executes the leaf‑pruning algorithm.  Returns {@code true} if the
         * board becomes completely tiled, {@code false} otherwise (including
         * the case where more than one tiling exists).
         */
        private boolean solve() {
            while (!leaves.isEmpty()) {
                Cell leaf = leaves.poll();

                // Leaf may have been processed already
                if (grid[leaf.row][leaf.col] != '.') continue;

                List<Cell> empties = neighbours(leaf.row, leaf.col);
                // Exactly one empty neighbour is required for a unique continuation
                if (empties.size() != 1) return false;

                Cell partner = empties.get(0);
                if (grid[partner.row][partner.col] != '.') continue; // already filled

                orientPair(leaf, partner);

                // Newly created leaves may now appear around the partner cell
                for (Cell n : neighbours(partner.row, partner.col)) {
                    leaves.add(n);
                }
            }

            // All leaves processed – verify that the board is completely filled
            for (int r = 0; r < rows; ++r) {
                for (int c = 0; c < cols; ++c) {
                    if (grid[r][c] == '.') return false;
                }
            }
            return true;
        }

        /** Returns the finished board as a single {@code String}. */
        private String renderResult() {
            StringBuilder sb = new StringBuilder();
            for (char[] row : grid) {
                sb.append(row);
                sb.append('\n');
            }
            return sb.toString();
        }
    }

    /* --------------------------------------------------------------------- */
    /*  Program entry point                                                   */
    /* --------------------------------------------------------------------- */

    /**
     * Parses the board dimensions and the character matrix from {@link InputReader}.
     * The format is:
     * <pre>
     * &lt;n&gt; &lt;m&gt;
     * line_1
     * line_2
     * …
     * line_n
     * </pre>
     */
    private static char[][] parseBoard(InputReader reader) throws IOException {
        String line = reader.readBoardLine();
        StringTokenizer tokenizer = new StringTokenizer(line);
        int rows = Integer.parseInt(tokenizer.nextToken());
        int cols = Integer.parseInt(tokenizer.nextToken());

        char[][] board = new char[rows][cols];
        for (int r = 0; r < rows; ++r) {
            String boardLine = reader.readBoardLine();
            if (boardLine.length() < cols) {
                throw new IllegalArgumentException("Line " + (r + 1) + " too short");
            }
            for (int c = 0; c < cols; ++c) {
                board[r][c] = boardLine.charAt(c);
            }
        }
        return board;
    }

    public static void main(String[] args) throws IOException {
        InputReader reader = new InputReader();
        char[][] grid = parseBoard(reader);
        Solver solver = new Solver(grid);

        if (solver.solve()) {
            System.out.print(solver.renderResult());
        } else {
            System.out.println("Not unique");
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Refactored implementation of the “Unique Tiles” solver.
 *
 * <p>The program reads a rectangular board consisting of '.' (empty) and
 * '#' (blocked) cells. It tries to fill every empty cell with one of the four
 * tile orientations (horizontal or vertical). If there is exactly one valid
 * tiling the solution is printed, otherwise the word <code>Not unique</code>
 * is printed.
 *
 * <p>The refactor improves readability, testability and maintainability by:
 * <ul>
 *   <li>Eliminating large blocks of duplicated code.</li>
 *   <li>Encapsulating related data into small private methods.</li>
 *   <li>Using expressive names and avoiding magic numbers.</li>
 *   <li>Centralising stream handling.</li>
 *   <li>Separating concerns (input, processing, output).</li>
 * </ul>
 *
 * <p>The algorithmic core remains unchanged – it uses a BFS‑like propagation
 * of cells that have exactly one possible orientation (a “forced move”).
 */
public class Main {

    /** Base encoding used to store a pair (row, col) in a single {@code int}. */
    private static final int COORD_BASE = 2001;

    /** Directions: left, up, right, down. */
    private static final int[] DX = {0, -1, 0, 1};
    private static final int[] DY = {-1, 0, 1, 0};

    /** Number of rows and columns of the board. */
    private final int rows;
    private final int cols;

    /** Original board ('.' = empty, '#' = obstacle). */
    private char[][] sourceGrid;

    /** Board after tiling; contains tile symbols or '.' if still empty. */
    private char[][] tileGrid;

    /** Number of free neighbours for each cell (used to detect forced moves). */
    private int[][] degree;

    /** Queue of cells that currently have exactly one possible orientation. */
    private final Queue<Integer> forcedQueue;

    /** Buffered reader for standard input. */
    private BufferedReader reader;

    /** Print writer for standard output. */
    private PrintWriter writer;

    /* --------------------------------------------------------------- */
    /*                     Construction & entry point                  */
    /* --------------------------------------------------------------- */

    public static void main(String[] args) throws Exception {
        new Main().run();
    }

    /** Main driver – delegates to small helper methods. */
    public void run() throws IOException {
        setupIo();
        readInput();
        allocateStructures();
        locateForcedMoves();
        if (!allCellsAreTiled()) {
            emit("Not unique");
            return;
        }
        emit(formatResult());
        closeIo();
    }

    /* --------------------------------------------------------------- */
    /*                         I/O handling                            */
    /* --------------------------------------------------------------- */

    private void setupIo() {
        reader = new BufferedReader(new InputStreamReader(System.in));
        writer = new PrintWriter(System.out);
    }

    private void closeIo() {
        try {
            reader.close();
        } catch (Exception ignored) { }
        writer.close();
    }

    private void emit(String message) {
        writer.println(message);
    }

    private String formatResult() {
        StringBuilder sb = new StringBuilder(rows * (cols + 1));
        for (char[] row : tileGrid) {
            sb.append(row).append('\n');
        }
        return sb.toString();
    }

    /* --------------------------------------------------------------- */
    /*                         Input parsing                           */
    /* --------------------------------------------------------------- */

    private void readInput() throws IOException {
        StringTokenizer tokenizer = parseFirstLine();
        rows = Integer.parseInt(tokenizer.nextToken());
        cols = Integer.parseInt(tokenizer.nextToken());

        sourceGrid = new char[rows][];
        for (int r = 0; r < rows; r++) {
            String line = reader.readLine();
            sourceGrid[r] = line.toCharArray();
        }
    }

    /** Reads the first line that contains the dimensions. */
    private StringTokenizer parseFirstLine() throws IOException {
        StringTokenizer token = null;
        while (token == null || !token.hasMoreTokens()) {
            token = new StringTokenizer(reader.readLine());
        }
        return token;
    }

    /* --------------------------------------------------------------- */
    /*                           Initialisation                        */
    /* --------------------------------------------------------------- */

    private void allocateStructures() {
        tileGrid = copyArray(sourceGrid);
        degree   = new int[rows][cols];
        forcedQueue = new ArrayDeque<>();

        computeDegrees();
        enqueueForcedCells();
    }

    /** Copies the source grid into a mutable working grid. */
    private static char[][] copyArray(char[][] src) {
        char[][] dst = new char[src.length][];
        for (int i = 0; i < src.length; i++) {
            dst[i] = src[i].clone();
        }
        return dst;
    }

    /** Calculates the degree (number of adjacent empty cells) for each empty cell. */
    private void computeDegrees() {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (tileGrid[r][c] != '.') {
                    continue;
                }
                degree[r][c] = countFreeNeighbours(r, c);
                if (degree[r][c] == 1) {
                    forcedQueue.add(encode(r, c));
                }
            }
        }
    }

    /** Counts how many of the four neighbours are inside the board and still empty. */
    private int countFreeNeighbours(int r, int c) {
        int cnt = 0;
        for (int dir = 0; dir < 4; dir++) {
            int nr = r + DX[dir];
            int nc = c + DY[dir];
            if (isInside(nr, nc) && tileGrid[nr][nc] == '.') {
                cnt++;
            }
        }
        return cnt;
    }

    private boolean isInside(int r, int c) {
        return 0 <= r && r < rows && 0 <= c && c < cols;
    }

    private void enqueueForcedCells() {
        // already performed inside computeDegrees()
    }

    /* --------------------------------------------------------------- */
    /*                         Core solving logic                      */
    /* --------------------------------------------------------------- */

    /** Main loop – processes all forced cells until the queue is empty. */
    private void locateForcedMoves() {
        while (!forcedQueue.isEmpty()) {
            int encoded = forcedQueue.poll();
            int x = decodeRow(encoded);
            int y = decodeCol(encoded);

            if (degree[x][y] == 0) {
                // Cell was already resolved – skip.
                continue;
            }

            int mask = computeValidMask(x, y);
            if (mask == -1) {
                // Defensive – should never happen if degrees are consistent.
                throw new IllegalStateException("No valid orientation found");
            }

            placeTile(x, y, mask);
            decrementNeighbourDegree(neighborCoord(x, y, mask));
            propagateUpdates(neighborCoord(x, y, mask));
        }
    }

    /** Returns a mask (bits 0‑3) that identifies the only possible orientation. */
    private int computeValidMask(int x, int y) {
        // All four directions start as possible.
        int mask = 0b1111;

        // Remove directions that point to a non‑empty cell.
        for (int dir = 0; dir < 4; dir++) {
            int nx = x + DX[dir];
            int ny = y + DY[dir];
            if (isBlocked(nx, ny)) {
                mask &= ~(1 << dir);
            }
        }
        return mask;
    }

    /** Places the appropriate tile symbols and returns the coordinate of the
     *  neighbour that has just been paired with (x, y). */
    private Point placeTile(int x, int y, int mask) {
        // Determine orientation from the mask.
        switch (mask) {
            case 0b0001 -> { // left
                tileGrid[x][y]     = '>';
                tileGrid[x][y - 1] = '<';
                return new Point(x, y - 1);
            }
            case 0b0010 -> { // up
                tileGrid[x][y]     = 'v';
                tileGrid[x - 1][y] = '^';
                return new Point(x - 1, y);
            }
            case 0b0100 -> { // right
                tileGrid[x][y]     = '<';
                tileGrid[x][y + 1] = '>';
                return new Point(x, y + 1);
            }
            case 0b1000 -> { // down
                tileGrid[x][y]     = '^';
                tileGrid[x + 1][y] = 'v';
                return new Point(x + 1, y);
            }
            default -> throw new IllegalStateException("Unexpected mask value");
        }
    }

    /** Decrements the degree of the neighbour cell and enqueues it if it becomes 1. */
    private void decrementNeighbourDegree(Point p) {
        int nx = p.row;
        int ny = p.col;
        if (!isInside(nx, ny) || tileGrid[nx][ny] != '.') {
            return;
        }
        degree[nx][ny]--;
        if (degree[nx][ny] == 1) {
            forcedQueue.add(encode(nx, ny));
        }
    }

    /** Propagates degree changes to all neighbours of the given cell. */
    private void propagateUpdates(Point centre) {
        int cx = centre.row;
        int cy = centre.col;
        for (int dir = 0; dir < 4; dir++) {
            int nx = cx + DX[dir];
            int ny = cy + DY[dir];
            if (!isInside(nx, ny) || tileGrid[nx][ny] != '.') {
                continue;
            }
            degree[nx][ny]--;
            if (degree[nx][ny] == 1) {
                forcedQueue.add(encode(nx, ny));
            }
        }
    }

    /** Checks whether any '.' remains in the tiling grid. */
    private boolean allCellsAreTiled() {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (tileGrid[r][c] == '.') {
                    return false;
                }
            }
        }
        return true;
    }

    /* --------------------------------------------------------------- */
    /*                         Helper methods & types                  */
    /* --------------------------------------------------------------- */

    /** Encoding/decoding helpers for queue elements. */
    private int encode(int r, int c) {
        return r * COORD_BASE + c;
    }

    private int decodeRow(int encoded) {
        return encoded / COORD_BASE;
    }

    private int decodeCol(int encoded) {
        return encoded % COORD_BASE;
    }

    /** Simple immutable pair used to return a neighbour coordinate. */
    private static final class Point {
        final int row;
        final int col;
        Point(int r, int c) { this.row = r; this.col = c; }
    }

    /** Determines if a given coordinate is out of bounds or points to a non‑empty cell. */
    private boolean isBlocked(int r, int c) {
        return !isInside(r, c) || tileGrid[r][c] != '.';
    }
}

import java.io.*;
import java.util.*;

/**
 * Solves a tiling puzzle by repeatedly placing dominoes that are forced
 * (only one possible neighbour). If after the process any empty cell
 * remains the solution is *not unique*.
 *
 * The program reads from {@code System.in} and writes the resulting board
 * to {@code System.out}.
 */
public class B {

    /** Symbol used for a blocked cell in the input. */
    private static final char BLOCKED = '*';

    /** Symbol used for a forced domino piece (empty cell that is already paired). */
    private static final char EMPTY = '?';

    /** Directions a domino can point to – up, down, left, right. */
    private enum Direction {
        UP( -1, 0, 'v' ),   // piece on current cell points *up* → neighbour below
        DOWN( 1, 0, '^' ),   // points *down* → neighbour above
        LEFT( 0, -1, '>' ),  // points *left* → neighbour on the right
        RIGHT( 0, 1, '<' );  // points *right* → neighbour on the left

        private final int di, dj;
        private final char symbol;

        Direction(int di, int dj, char symbol) {
            this.di = di;
            this.dj = dj;
            this.symbol = symbol;
        }

        int di() { return di; }
        int dj() { return dj; }
        char symbol() { return symbol; }

        /** Returns the opposite direction (the tile that neighbours the current one). */
        Direction opposite() {
            switch (this) {
                case UP:    return DOWN;
                case DOWN:  return UP;
                case LEFT:  return RIGHT;
                case RIGHT: return LEFT;
                default:    throw new IllegalStateException();
            }
        }
    }

    /** Simple container for a board coordinate. */
    private static final class Cell {
        final int row, col;

        Cell(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }

    /** Holds the board and all tiling logic. */
    private static final class Solver {
        private final char[][] board;   // original input ('.' = free, '#' = blocked)
        private final int rows, cols;
        private final Queue<Cell> forcedQueue = new ArrayDeque<>();

        Solver(char[][] board) {
            this.board = board;
            this.rows = board.length;
            this.cols = board[0].length;
        }

        /** Entry point for the solving algorithm. */
        void solve(PrintWriter out) {
            initialiseQueue();

            while (!forcedQueue.isEmpty()) {
                Cell cur = forcedQueue.poll();
                pairCell(cur);
                propagateNeighbourhood(cur);
            }

            if (hasRemainingEmptyCells()) {
                out.println("Not unique");
                return;
            }

            render(out);
        }

        /** Finds all empty cells that have exactly one free neighbour and enqueues them. */
        private void initialiseQueue() {
            for (int r = 0; r < rows; ++r) {
                for (int c = 0; c < cols; ++c) {
                    if (board[r][c] == '.') {
                        if (hasExactlyOneFreeNeighbour(r, c)) {
                            forcedQueue.add(new Cell(r, c));
                        }
                    }
                }
            }
        }

        /** Checks whether a cell has precisely one adjacent free cell. */
        private boolean hasExactlyOneFreeNeighbour(int r, int c) {
            int freeNeighbours = 0;
            for (Direction dir : Direction.values()) {
                if (isFreeNeighbour(r, c, dir)) {
                    ++freeNeighbours;
                }
            }
            return freeNeighbours == 1;
        }

        /** Returns true if the neighbour in `dir` from (r,c) is inside the board and currently empty. */
        private boolean isFreeNeighbour(int r, int c, Direction dir) {
            int nr = r + dir.di();
            int nc = c + dir.dj();
            return inside(nr, nc) && board[nr][nc] == '.';
        }

        /** Places a domino covering (r,c) and its unique neighbour, updates the board and queue. */
        private void pairCell(Cell start) {
            // Find the only free neighbour of start
            Direction dir = findUniqueFreeDirection(start.row, start.col);
            Cell partner = new Cell(start.row + dir.di(), start.col + dir.dj());

            // Mark both cells as paired; assign opposite symbols
            board[start.row][start.col] = dir.opposite().symbol();
            board[partner.row][partner.col] = dir.symbol();

            // Continue processing neighbours of both cells
            addNeighboursToQueue(start);
            addNeighboursToQueue(partner);
        }

        /** Locates the unique free direction around the given cell. */
        private Direction findUniqueFreeDirection(int r, int c) {
            Direction found = null;
            for (Direction dir : Direction.values()) {
                if (isFreeNeighbour(r, c, dir)) {
                    if (found != null) {
                        // More than one free neighbour – this method should never be called in such a case
                        throw new IllegalStateException("Cell has more than one free neighbour");
                    }
                    found = dir;
                }
            }
            if (found == null) {
                throw new IllegalStateException("Cell has no free neighbour – should not happen");
            }
            return found;
        }

        /** Adds all (up to) 5×5 neighbour cells around (r,c) to the queue if they become forced. */
        private void propagateNeighbourhood(Cell centre) {
            for (int dr = -2; dr <= 2; ++dr) {
                for (int dc = -2; dc <= 2; ++dc) {
                    Cell neighbour = new Cell(centre.row + dr, centre.col + dc);
                    if (isValidNeighbour(neighbour.row, neighbour.col) && board[neighbour.row][neighbour.col] == '.') {
                        if (hasExactlyOneFreeNeighbour(neighbour.row, neighbour.col)) {
                            forcedQueue.add(neighbour);
                        }
                    }
                }
            }
        }

        private boolean isValidNeighbour(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }

        private boolean hasRemainingEmptyCells() {
            for (int r = 0; r < rows; ++r) {
                for (int c = 0; c < cols; ++c) {
                    if (board[r][c] == '.') {
                        return true;
                    }
                }
            }
            return false;
        }

        private void render(PrintWriter out) {
            for (int r = 0; r < rows; ++r) {
                for (int c = 0; c < cols; ++c) {
                    char ch = board[r][c];
                    if (ch == BLOCKED) {
                        out.print('*');
                    } else if (ch == '.') {
                        // Should never happen here, but keep safety
                        out.print('?');
                    } else {
                        out.print(ch);
                    }
                }
                out.println();
            }
        }

        private void addNeighboursToQueue(Cell cell) {
            for (int dr = -2; dr <= 2; ++dr) {
                for (int dc = -2; dc <= 2; ++dc) {
                    Cell n = new Cell(cell.row + dr, cell.col + dc);
                    if (isValidNeighbour(n.row, n.col) && board[n.row][n.col] == '.') {
                        if (hasExactlyOneFreeNeighbour(n.row, n.col)) {
                            forcedQueue.add(n);
                        }
                    }
                }
            }
        }
    }

    /** --------------------------------------------------------------------- */
    /** Main driver – parses input, runs the solver and prints the result.      */
    public static void main(String[] args) throws IOException {
        // Using try‑with‑resources guarantees streams are closed even on early return
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
             PrintWriter out = new PrintWriter(System.out)) {

            readDimensionsAndBoard(reader);
            char[][] board = readBoard(reader);
            new Solver(board).solve(out);
        }
    }

    /** Reads the first line containing board dimensions and converts '.' → '.' , '#' → blocked. */
    private static void readDimensionsAndBoard(BufferedReader reader) throws IOException {
        String line = reader.readLine();
        if (line == null) throw new IOException("Empty input");
        StringTokenizer tk = new StringTokenizer(line);
        int rows = Integer.parseInt(tk.nextToken());
        int cols = Integer.parseInt(tk.nextToken());

        // The next `rows` lines contain the actual board layout
        // (the outer method will consume them while building the char matrix)
        // Nothing to do here – just keep the values for later.
        // We store them as fields of the outer class so that the inner readBoard()
        // can reuse them without passing extra parameters.
        setDimensionVariables(rows, cols);
    }

    /** Stores the dimension values into static fields used by `readBoard`. */
    private static int storedRows, storedCols;
    private static void setDimensionVariables(int r, int c) {
        storedRows = r;
        storedCols = c;
    }

    /** Reads the actual board from the input stream. */
    private static char[][] readBoard(BufferedReader reader) throws IOException {
        char[][] board = new char[storedRows][storedCols];
        for (int r = 0; r < storedRows; ++r) {
            String line = reader.readLine();
            if (line == null) throw new IOException("Unexpected end of input");
            line = line.trim();               // ignore trailing newline / spaces
            Arrays.fill(board[r], '.');        // default to empty (will be overwritten)
            for (int c = 0; c < storedCols; ++c) {
                char ch = line.charAt(c);
                board[r][c] = (ch == '.' ) ? '.' : BLOCKED; // '.' = free, anything else = blocked
            }
        }
        return board;
    }
}

import java.io.*;
import java.util.*;

/**
 * Entry point of the program. Parses input, creates the solver and prints the resulting board
 * (or "Not unique" if the tiling is ambiguous).
 */
public final class DrazilAndTiles {

    private static final ScannerWrapper SCANNER = new ScannerWrapper();

    public static void main(String[] args) {
        int n = SCANNER.nextInt();
        int m = SCANNER.nextInt();

        char[][] board = new char[n][];
        for (int i = 0; i < n; i++) {
            board[i] = SCANNER.nextString().toCharArray();
        }

        Solver solver = new Solver(board);
        solver.process();

        StringBuilder out = new StringBuilder();
        for (char[] row : solver.getBoard()) {
            out.append(row).append('\n');
        }
        System.out.print(out.toString());
    }
}

/**
 * Handles the tiling logic – placement of dominoes and propagation of the placement.
 */
final class Solver {

    private static final Direction[] ALL_DIRECTIONS = Direction.values();

    private final char[][] board;
    private final int rows;
    private final int cols;

    Solver(char[][] board) {
        this.board = board;
        this.rows = board.length;
        this.cols = board[0].length;
    }

    /** Main driver – tries to fill every empty cell and validates uniqueness. */
    void process() {
        // Try to seed a tile from every empty cell.
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                expand(r, c);
            }
        }

        // If any empty cell remains, the tiling is not unique.
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (board[r][c] == '.') {
                    System.out.println("Not unique");
                    System.exit(0);
                }
            }
        }
    }

    /** Bread‑first expansion starting from (r,c). */
    private void expand(int startR, int startC) {
        Direction startDir = findDirection(startR, startC);
        if (startDir == null) {
            return;
        }

        Queue<Placement> queue = new ArrayDeque<>();
        queue.add(new Placement(startR, startC, startDir));

        placeTile(startR, startC, startDir);

        while (!queue.isEmpty()) {
            Placement cur = queue.poll();
            for (Direction d : ALL_DIRECTIONS) {
                int nr = cur.r + Direction.DR[d.ordinal()];
                int nc = cur.c + Direction.DC[d.ordinal()];
                if (!isInside(nr, nc) || board[nr][nc] != '.') {
                    continue;
                }
                Direction ndir = findDirection(nr, nc);
                if (ndir == null) {
                    continue;
                }
                placeTile(nr, nc, ndir);
                queue.add(new Placement(nr, nc, ndir));
            }
        }
    }

    /** Returns the unique direction that leads to a free neighbour, or {@code null} otherwise. */
    private Direction findDirection(int r, int c) {
        if (!isInside(r, c) || board[r][c] != '.') {
            return null;
        }

        Direction first = null;
        for (Direction dir : ALL_DIRECTIONS) {
            int nr = r + Direction.DR[dir.ordinal()];
            int nc = c + Direction.DC[dir.ordinal()];
            if (isInside(nr, nc) && board[nr][nc] == '.') {
                if (first == null) {
                    first = dir;
                } else {
                    // More than one free neighbour – ambiguous placement.
                    return null;
                }
            }
        }
        return first;
    }

    /** Places a domino according to {@code dir} and returns the opposite direction for continuation. */
    private Direction placeTile(int r, int c, Direction dir) {
        // current cell
        board[r][c] = dir.currentSymbol;
        // partner cell
        int pr = r + dir.dr;
        int pc = c + dir.dc;
        board[pr][pc] = dir.partnerSymbol;
        return dir.opposite();
    }

    /** Checks whether a coordinate lies inside the board. */
    private boolean isInside(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    char[][] getBoard() {
        return board;
    }
}

/**
 * Represents one of the four possible orientations a domino can have.
 * The orientation is defined from the *current* empty cell towards its partner.
 */
enum Direction {
    /** Upward partner cell – current cell gets 'v', partner gets '^'. */
    UP('v', '^', -1, 0),
    /** Rightward partner cell – current cell gets '<', partner gets '>'. */
    RIGHT('<', '>', 0, 1),
    /** Downward partner cell – current cell gets '^', partner gets 'v'. */
    DOWN('^', 'v', 1, 0),
    /** Leftward partner cell – current cell gets '>', partner gets '<'. */
    LEFT('>', '<', 0, -1);

    /** Symbol written on the current cell. */
    final char currentSymbol;
    /** Symbol written on the partner cell. */
    final char partnerSymbol;
    /** Row offset from the current cell to the partner cell. */
    final int dr;
    /** Column offset from the current cell to the partner cell. */
    final int dc;

    Direction(char currentSymbol, char partnerSymbol, int dr, int dc) {
        this.currentSymbol = currentSymbol;
        this.partnerSymbol = partnerSymbol;
        this.dr = dr;
        this.dc = dc;
    }

    /** Returns the opposite direction (e.g. UP ↔ DOWN, LEFT ↔ RIGHT). */
    Direction opposite() {
        switch (this) {
            case UP:    return DOWN;
            case DOWN:  return UP;
            case LEFT:  return RIGHT;
            case RIGHT: return LEFT;
            default:    throw new AssertionError();
        }
    }
}

/**
 * Simple tokeniser that mimics the behaviour of the original {@code FasterScanner}
 * but uses only the JDK classes.
 */
final class ScannerWrapper {
    private final BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
    private StringTokenizer tokenizer;

    /** Reads the next integer token. */
    int nextInt() {
        return Integer.parseInt(nextToken());
    }

    /** Reads the next string token. */
    String nextString() {
        return nextToken();
    }

    /** Reads a whole line (including possible leading spaces). */
    String nextLine() {
        try {
            return reader.readLine();
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
    }

    /** Returns the next non‑empty token. */
    private String nextToken() {
        while (tokenizer == null || !tokenizer.hasMoreTokens()) {
            try {
                String line = reader.readLine();
                if (line == null) {
                    return "";
                }
                tokenizer = new StringTokenizer(line);
            } catch (IOException e) {
                throw new UncheckedIOException(e);
            }
        }
        return tokenizer.nextToken();
    }
}

/**
 * Container for a placement step – a cell together with the direction that placed
 * the domino and the direction to continue the propagation from the partner cell.
 */
final class Placement {
    final int r;
    final int c;
    final Direction dir;

    Placement(int r, int c, Direction dir) {
        this.r = r;
        this.c = c;
        this.dir = dir;
    }
}

import java.io.IOException;
import java.util.ArrayDeque;
import java.util.Arrays;
import java.util.Objects;

/**
 * Reads a rectangular grid of '.' and '#' characters, then attempts to fill every '.' with
 * a unique tile representation (<>, ^v, etc.).  If any '.' remains unfilled the program prints
 * "Not unique", otherwise it prints the tiled grid.
 *
 * The algorithm works with the following rules:
 *   * A '.' that has exactly one neighbouring '.' can be forced into a tile.
 *   * That forced placement may create new cells with degree‑1, which are processed
 *     iteratively (BFS‑style) until no more forced moves exist.
 *
 * The implementation is deliberately refactored for readability, modern Java idioms,
 * and testability.
 */
public final class DominoTiling {

    /** Directions for the four orthogonal neighbours (left, right, up, down). */
    private static final int[] DR = {0, 0, -1, 1};
    private static final int[] DC = {-1, 1, 0, 0};

    /** Cell coordinates inside the grid. */
    private static final class Cell {
        final int row;
        final int col;

        Cell(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }

    /** Mutable representation of the input grid. */
    private final char[][] board;

    /** Set of cells that have already been processed. */
    private final boolean[][] visited;

    /** Queue of cells that must be processed because they currently have degree 1. */
    private final ArrayDeque<Cell> queue = new ArrayDeque<>();

    /** Number of rows and columns of the board. */
    private final int rows;
    private final int cols;

    /**
     * Constructs the solver for the supplied grid.
     *
     * @param board mutable 2‑D char array containing '.' (empty) and any other character
     *              that should be treated as filled.
     */
    public DominoTiling(char[][] board) {
        this.board = Objects.requireNonNull(board);
        this.rows = board.length;
        this.cols = board[0].length;
        this.visited = new boolean[rows][cols];
        initialiseQueue();
    }

    /** Prepares the internal queue with cells that have degree 1 at start‑up. */
    private void initialiseQueue() {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (isEmpty(r, c)) {
                    maybeAddToQueue(r, c);
                }
            }
        }
    }

    /** Returns true if the supplied cell is still empty ('.'). */
    private boolean isEmpty(int r, int c) {
        return board[r][c] == '.';
    }

    /**
     * Calculates the number of empty neighbours of the supplied cell.
     *
     * @return the degree of the cell (0 if out of bounds or not empty).
     */
    private int degree(int r, int c) {
        if (!isInside(r, c)) {
            return 0;
        }
        if (!isEmpty(r, c)) {
            return 0;
        }
        int deg = 0;
        for (int d = 0; d < 4; d++) {
            int nr = r + DR[d];
            int nc = c + DC[d];
            if (isEmpty(nr, nc)) {
                deg++;
            }
        }
        if (deg == 1 && !visited[r][c]) {
            maybeAddToQueue(r, c);
            visited[r][c] = true;
        }
        return deg;
    }

    /** Adds the cell to the processing queue if it is not already present. */
    private void maybeAddToQueue(int r, int c) {
        // Avoid duplicate queue entries
        if (!visited[r][c]) {
            queue.add(new Cell(r, c));
            visited[r][c] = true;
        }
    }

    /**
     * Attempts to process a single cell that currently has degree 1.
     *
     * <p>If the cell can be placed into a forced tile, the surrounding characters are updated.
     * Afterwards, all newly created degree‑1 neighbours are queued for future processing.
     *
     * @param src the source cell taken from the processing queue
     * @throws IllegalStateException if the board layout is inconsistent (should never happen
     *                               with well‑formed input)
     */
    private void processCell(Cell src) {
        if (degree(src.row, src.col) != 1) {
            return; // No longer eligible – could happen after earlier placements
        }

        int r = src.row; // original position
        int c = src.col;

        // Find the unique empty neighbour
        int targetDir = -1;
        for (int d = 0; d < 4; d++) {
            int nr = r + DR[d];
            int nc = c + DC[d];
            if (isEmpty(nr, nc)) {
                targetDir = d;
                break;
            }
        }
        Objects.requireNonNull(targetDir, "Cell with degree 1 must have exactly one neighbour");

        int tr = r + DR[targetDir]; // neighbour row
        int tc = c + DC[targetDir]; // neighbour column

        // ---------------------------------------------------------------
        //   Tile the pair (src, neighbour) according to the relative position
        // ---------------------------------------------------------------
        switch (targetDir) {
            case 0 -> {                     // left neighbour (c-1)
                board[r].charAt(c - 1) = '<';
                board[r].charAt(c)     = '>';
            }
            case 1 -> {                     // right neighbour (c+1)
                board[r].charAt(c)     = '<';
                board[r].charAt(c + 1) = '>';
            }
            case 2 -> {                     // upper neighbour (r-1)
                board[r - 1].charAt(c) = '^';
                board[r].charAt(c)     = 'v';
            }
            case 3 -> {                     // lower neighbour (r+1)
                board[r].charAt(c)      = '^';
                board[r + 1].charAt(c) = 'v';
            }
        }

        // Queue neighbours of the newly placed tile that may become degree‑1
        for (int d = 0; d < 4; d++) {
            int nr = tr + DR[d];
            int nc = tc + DC[d];
            if (isEmpty(nr, nc)) {
                maybeAddToQueue(nr, nc);
            }
        }
    }

    /** Main solving routine – returns true if every empty cell could be uniquely filled. */
    private boolean solve() {
        while (!queue.isEmpty()) {
            processCell(queue.removeFirst());
        }

        // Verify that no empty cell remains
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (isEmpty(r, c)) {
                    return false;
                }
            }
        }
        return true;
    }

    /** Utility method used by the legacy program to display a board line. */
    private static void printBoard(char[][] board) {
        for (char[] row : board) {
            System.out.println(new String(row));
        }
    }

    /* -----------------------------------------------------------------------
       Legacy entry‑point – kept for compatibility with the original source.
       The method parses stdin exactly as the original program did.
       ----------------------------------------------------------------------- */
    public static void main(String[] args) throws IOException {
        var reader = new java.util.Scanner(System.in);
        int n = reader.nextInt();
        int m = reader.nextInt();
        reader.nextLine(); // consume end‑of‑line

        char[][] input = new char[n][];
        for (int i = 0; i < n; i++) {
            input[i] = reader.nextLine().toCharArray();
        }

        DominoTiling solver = new DominoTiling(input);

        // Populate the queue with all starting degree‑1 cells (mirrors original behaviour)
        solver.initialiseQueue();

        // Process all forced placements
        while (!solver.queue.isEmpty()) {
            solver.processCell(solver.queue.removeFirst());
        }

        // If any '.' survived, the solution is not unique.
        boolean unique = solver.solve();

        if (!unique) {
            System.out.println("Not unique");
            return;
        }

        printBoard(solver.board);
    }
}

import java.io.*;
import java.util.*;

/**
 * Tile‑placement validator.
 *
 * <p>Reads a rectangular board consisting of '.' (empty) and '#' (blocked) cells.
 * The program tries to completely cover all empty cells with 2×1 dominoes.
 * If the covering is forced (i.e. there is exactly one way to tile the board),
 * the board is printed with arrows indicating the orientation of each domino.
 * Otherwise the string {@code "Not unique"} is printed.</p>
 */
public class Solution {

    /** Four orthogonal directions. */
    private static final int[] DX = {-1, 0, 1, 0};
    private static final int[] DY = {0, -1, 0, 1};

    /** Buffered input and PrintWriter output – closed automatically. */
    private BufferedReader reader;
    private PrintWriter writer;

    /** The board read from input. */
    private char[][] board;

    /** Number of rows and columns of the board. */
    private int rows, cols;

    /** Entry point. */
    public static void main(String[] args) throws IOException {
        new Solution().solve();
    }

    /** Core algorithm. */
    public void solve() throws IOException {
        try (reader = new BufferedReader(
                new InputStreamReader(System.in, StandardCharsets.UTF_8));
             writer = new PrintWriter(
                     new OutputStreamWriter(System.out, StandardCharsets.UTF_8))) {

            Locale.setDefault(Locale.ENGLISH);

            rows = readInt();
            cols = readInt();

            board = new char[rows][cols];
            readGrid();

            // visited[x][y] holds a Position that has already been paired,
            // or {@code null} if the cell has not been processed yet.
            Position[][] visited = new Position[rows][cols];

            Queue<Position> queue = new ArrayDeque<>();

            /* -------------------------------------------------------------
             * 1️⃣  Force‑place dominos that have exactly one free neighbour.
             * ------------------------------------------------------------- */
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    placeForced(i, j, visited, queue);
                }
            }

            /* -------------------------------------------------------------
             * 2️⃣  Propagate the forced placements with BFS.
             * ------------------------------------------------------------- */
            while (!queue.isEmpty()) {
                Position cur = queue.poll();
                if (cur == null) {
                    continue;
                }
                int x = cur.row;
                int y = cur.col;
                for (int d = 0; d < 4; d++) {
                    int nx = x + DX[d];
                    int ny = y + DY[d];
                    if (!isInside(nx, ny) || board[nx][ny] != '.') {
                        continue;
                    }
                    placeForced(nx, ny, visited, queue);
                }
            }

            /* -------------------------------------------------------------
             * 3️⃣  If any empty cell remains the tiling is not unique.
             * ------------------------------------------------------------- */
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (board[i][j] == '.') {
                        writer.println("Not unique");
                        return;
                    }
                }
            }

            /* -------------------------------------------------------------
             * 4️⃣  Output the fully‑tiled board.
             * ------------------------------------------------------------- */
            for (char[] row : board) {
                writer.println(row);
            }
        }
    }

    /** Reads the grid of characters from {@code reader}. */
    private void readGrid() throws IOException {
        for (int i = 0; i < rows; i++) {
            String line = reader.readLine();
            if (line == null) {
                return;
            }
            for (int j = 0; j < cols; j++) {
                board[i][j] = line.charAt(j);
            }
        }
    }

    /** Places a domino covering (x,y) and its only empty neighbour, if it exists.
     *  The discovered domino is written into {@code board} and both cells are
     *  marked as visited.  The cells are also enqueued so that further forced
     *  placements can be discovered. */
    private void placeForced(int x, int y, Position[][] visited, Queue<Position> queue) {
        if (board[x][y] != '.') {
            return;
        }
        Position[] neighbours = getEmptyNeighbours(x, y);
        if (neighbours.length != 1) {
            return;                     // more than one choice → not forced
        }

        Position partner = neighbours[0];

        // Write the two halves of the domino.
        board[x][y] = decideChar(x, y, partner);
        board[partner.row][partner.col] = decideChar(partner.row, partner.col,
                new Position(x, y));

        // Register both cells as processed.
        if (visited[x][y] == null) {
            visited[x][y] = new Position(x, y);
            queue.add(new Position(x, y));
        }
        if (visited[partner.row][partner.col] == null) {
            visited[partner.row][partner.col] = partner;
            queue.add(partner);
        }
    }

    /** Returns all orthogonal neighbours of (x,y) that are still empty ('.'). */
    private Position[] getEmptyNeighbours(int x, int y) {
        List<Position> list = new ArrayList<>(4);
        for (int d = 0; d < 4; d++) {
            int nx = x + DX[d];
            int ny = y + DY[d];
            if (isInside(nx, ny) && board[nx][ny] == '.') {
                list.add(new Position(nx, ny));
            }
        }
        return list.toArray(new Position[0]);
    }

    /** Returns the arrow that should be drawn at (srcRow,srcCol) pointing to
     *  {@code target}.  The arrow is one of {@code '^', 'v', '<', '>'}. */
    private char decideChar(int srcRow, int srcCol, Position target) {
        int dr = target.row - srcRow;
        int dc = target.col - srcCol;

        if (dr < 0) {
            return '^';
        }
        if (dr > 0) {
            return 'v';
        }
        if (dc < 0) {
            return '<';
        }
        // dc > 0
        return '>';
    }

    /** True if (x,y) lies inside the board boundaries. */
    private boolean isInside(int x, int y) {
        return x >= 0 && x < rows && y >= 0 && y < cols;
    }

    /** Immutable pair of board coordinates. */
    private static final class Position {
        final int row;
        final int col;

        Position(int row, int col) {
            this.row = row;
            this.col = col;
        }

        @Override
        public boolean equals(Object o) {
            if (this == o) return true;
            if (!(o instanceof Position)) return false;
            Position that = (Position) o;
            return row == that.row && col == that.col;
        }

        @Override
        public int hashCode() {
            return Objects.hash(row, col);
        }
    }

    /** Small helper that returns the next non‑empty token from {@code reader}. */
    private String nextToken() throws IOException {
        String token;
        do {
            token = reader.readLine();
            if (token == null || !token.isBlank()) {
                break;
            }
        } while (true);
        return token;
    }

    /** Reads the next integer from the input. */
    private int readInt() throws IOException {
        return Integer.parseInt(nextToken());
    }
}

import java.io.*;
import java.util.*;

public class Main {

    // Directions: up, down, left, right
    private static final int[] DX = {-1, 1, 0, 0};
    private static final int[] DY = {0, 0, -1, 1};
    private static final char UP = '^';
    private static final char DOWN = 'v';
    private static final char LEFT = '<';
    private static final char RIGHT = '>';

    /** Represents one domino covering two adjacent free cells. */
    private static final class Domino {
        private final Point head;   // cell examined first (forced by neighbour count)
        private final Point tail;   // adjacent free cell that must pair with it

        Domino(Point head, Point tail) {
            this.head = head;
            this.tail = tail;
        }
    }

    /** Simple 2‑D point. */
    private static final class Point {
        final int x;
        final int y;

        Point(int x, int y) {
            this.x = x;
            this.y = y;
        }
    }

    /** Utility class that reads the whole input. */
    private static final class InputReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        InputReader() {
            // Try to open a file named cf292D.in; if it does not exist read from stdin.
            try {
                reader = new BufferedReader(new FileReader("cf292D.in"));
            } catch (IOException e) {
                reader = new BufferedReader(new InputStreamReader(System.in));
            }
        }

        /** Reads the next whitespace‑separated token (lazily tokenised). */
        private String nextToken() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                tokenizer = new StringTokenizer(reader.readLine());
            }
            return tokenizer.nextToken();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(nextToken());
        }

        String nextLine() throws IOException {
            return nextToken(); // sufficient for the contest problem (tokens are separated by whitespace)
        }
    }

    /** Main solving routine. */
    private static void solve(InputReader in) throws IOException {
        // ----- 1. read dimensions and board ---------------------------------
        String line = in.nextLine();
        String[] dims = line.split("\\s+");
        int rows = Integer.parseInt(dims[0]);
        int cols = Integer.parseInt(dims[1]);

        char[][] board = new char[rows][cols];
        for (int r = 0; r < rows; ++r) {
            String row = in.nextLine();
            board[r] = row.toCharArray();
        }

        // ----- 2. locate all forced domino placements -----------------------
        Queue<Domino> queue = new ArrayDeque<>();

        outer:
        for (int r = 0; r < rows; ++r) {
            for (int c = 0; c < cols; ++c) {
                if (board[r][c] != '.') {
                    continue;
                }
                Point cell = new Point(r, c);
                int freeNeighbours = 0;
                Point onlyNeighbour = null;

                for (int d = 0; d < 4; ++d) {
                    int nr = r + DX[d];
                    int nc = c + DY[d];
                    if (!inside(nr, nc, rows, cols) || board[nr][nc] != '.') {
                        continue;
                    }
                    ++freeNeighbours;
                    onlyNeighbour = new Point(nr, nc);
                }
                if (freeNeighbours == 1) {
                    queue.add(new Domino(cell, onlyNeighbour));
                }
            }
        }

        // ----- 3. propagate forced dominoes --------------------------------
        while (!queue.isEmpty()) {
            Domino dom = queue.poll();
            Point p1 = dom.head;
            Point p2 = dom.tail;

            // Skip if either cell was already filled by a previous step
            if (board[p1.x][p1.y] != '.' || board[p2.x][p2.y] != '.') {
                continue;
            }

            // Determine orientation and write the appropriate arrows
            if (p1.x == p2.x - 1) {          // p1 above p2
                board[p1.x][p1.y] = UP;
                board[p2.x][p2.y] = DOWN;
            } else if (p1.x == p2.x + 1) {   // p1 below p2
                board[p1.x][p1.y] = DOWN;
                board[p2.x][p2.y] = UP;
            } else if (p1.y == p2.y - 1) {   // p1 left of p2
                board[p1.x][p1.y] = LEFT;
                board[p2.x][p2.y] = RIGHT;
            } else {                         // p1 right of p2
                board[p1.x][p1.y] = RIGHT;
                board[p2.x][p2.y] = LEFT;
            }

            // The tail cell is now occupied; its neighbours may become forced
            for (int dir = 0; dir < 4; ++dir) {
                int nr = p2.x + DX[dir];
                int nc = p2.y + DY[dir];
                if (!inside(nr, nc, rows, cols) || board[nr][nc] != '.') {
                    continue;
                }
                Point cur = new Point(nr, nc);
                int cnt = 0;
                Point sole = null;
                for (int d = 0; d < 4; ++d) {
                    int rr = nr + DX[d];
                    int cc = nc + DY[d];
                    if (!inside(rr, cc, rows, cols) || board[rr][cc] != '.') {
                        continue;
                    }
                    ++cnt;
                    sole = new Point(rr, cc);
                }
                if (cnt == 1) {
                    queue.add(new Domino(cur, sole));
                }
            }
        }

        // ----- 4. verify that every cell is covered -----------------------
        StringBuilder out = new StringBuilder();
        for (int r = 0; r < rows; ++r) {
            for (int c = 0; c < cols; ++c) {
                if (board[r][c] == '.') {
                    System.out.println("Not unique");
                    return;
                }
                out.append(board[r][c]);
            }
            out.append('\n');
        }
        System.out.print(out.toString());
    }

    /** Checks whether a coordinate lies inside the grid boundaries. */
    private static boolean inside(int x, int y, int rows, int cols) {
        return x >= 0 && x < rows && y >= 0 && y < cols;
    }

    // ----- 5. entry point -------------------------------------------------
    public static void main(String[] args) throws Exception {
        InputReader reader = new InputReader();
        solve(reader);
    }
}

import java.io.*;
import java.util.*;
import static java.lang.System.out;

public class F {
    static char[][] grid;
    static int[] degree;
    static int totalCells;
    static int[] queue;
    static int queueFront;
    static int queueBack;
    static final int[] dx = {1, -1, 0, 0};
    static final int[] dy = {0, 0, 1, -1};
    static final char[] dominoCharTop = {'^', 'v', '<', '>'};
    static final char[] dominoCharBottom = {'v', '^', '>', '<'};

    static boolean valid(int r, int c, int n, int m) {
        return r >= 0 && c >= 0 && r < n && c < m;
    }

    public static void main(String[] args) throws Throwable {
        MyScanner scanner = new MyScanner();
        PrintWriter writer = new PrintWriter(System.out);

        int n = scanner.nextInt();
        int m = scanner.nextInt();
        totalCells = n * m;
        grid = new char[n][m];

        for (int i = 0; i < n; i++) {
            grid[i] = scanner.next().toCharArray();
        }

        degree = new int[totalCells];
        queue = new int[totalCells + 10];
        queueFront = 0;
        queueBack = 0;
        int emptyCount = 0;

        // Initialize degree counts for all empty cells
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i][j] == '.') {
                    emptyCount++;
                    // Check only down and right directions to avoid double-counting edges
                    for (int dirIndex = 0; dirIndex < 4; dirIndex += 2) {
                        int nextRow = i + dx[dirIndex];
                        int nextCol = j + dy[dirIndex];
                        if (valid(nextRow, nextCol, n, m) && grid[nextRow][nextCol] == '.') {
                            degree[i * m + j]++;
                            degree[nextRow * m + nextCol]++;
                        }
                    }
                    // Start BFS from cells with only one adjacent empty cell
                    if (degree[i * m + j] == 1) {
                        queue[queueBack++] = i * m + j;
                    }
                }
            }
        }

        boolean isSuccess = true;
        while (queueFront != queueBack) {
            int cellIndex = queue[queueFront++];
            int r = cellIndex / m;
            int c = cellIndex % m;

            // Skip if cell was already processed
            if (grid[r][c] != '.') {
                continue;
            }

            emptyCount -= 2;
            boolean isMatched = false;

            // Try to match with adjacent empty cell
            for (int dirIndex = 0; dirIndex < 4; dirIndex++) {
                int nextRow = r + dx[dirIndex];
                int nextCol = c + dy[dirIndex];

                if (valid(nextRow, nextCol, n, m) && grid[nextRow][nextCol] == '.') {
                    isMatched = true;
                    // Place domino pieces
                    grid[r][c] = dominoCharTop[dirIndex];
                    grid[nextRow][nextCol] = dominoCharBottom[dirIndex];

                    // Check neighbors of the new domino for new degree-1 cells
                    for (int neighborDir = 0; neighborDir < 4; neighborDir++) {
                        int nnr = nextRow + dx[neighborDir];
                        int nnc = nextCol + dy[neighborDir];
                        if (valid(nnr, nnc, n, m) && --degree[nnr * m + nnc] == 1) {
                            queue[queueBack++] = nnr * m + nnc;
                        }
                    }
                    break;
                }
            }
            isSuccess = isSuccess && isMatched;
        }

        if (!isSuccess || emptyCount > 0) {
            writer.println("Not unique");
        } else {
            for (int i = 0; i < n; i++) {
                writer.println(new String(grid[i]));
            }
        }

        writer.flush();
        writer.close();
    }

    static class MyScanner {
        BufferedReader br;
        StringTokenizer st;

        public MyScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    e.printStackTrace();
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        long nextLong() {
            return Long.parseLong(next());
        }

        double nextDouble() {
            return Double.parseDouble(next());
        }

        String nextLine() {
            try {
                return br.readLine();
            } catch (IOException e) {
                e.printStackTrace();
                return "";
            }
        }
    }
}

/**
 * Drazil And Tiles – refactored version.
 *
 * <p>This program reads a rectangular grid composed of '.' (empty) and '*' (blocked) cells.
 * It attempts to uniquely tile every empty cell with dominoes (1 × 2 or 2 × 1).
 * If the tiling is forced (i.e. there is exactly one possible tiling) the program
 * outputs the completed tiling using direction characters:
 * '<', '>', '^', 'v'.
 * Otherwise it prints "Not unique".
 *
 * <p>The refactored implementation improves readability, maintainability and
 * extensibility by:
 * <ul>
 *   <li>Extracting the input / output logic into dedicated methods.</li>
 *   <li>Encapsulating directional data in a constant.</li>
 *   <li>Using well‑named methods and guard‑clauses.</li>
 *   <li>Preferring {@link java.util.ArrayDeque} over {@link java.util.LinkedList}.</li>
 *   <li>Separating the core algorithm into small, testable units.</li>
 * </ul>
 *
 * @author  Original implementation adapted & refactored
 */
public final class DrazilAndTiles {

    /** Directions: up, down, left, right */
    private static final int[] DY = {-1, 1, 0, 0};
    private static final int[] DX = {0, 0, -1, 1};

    /** The board; '.' = empty, '*' = blocked, other chars = already tiled */
    private static char[][] board;
    /** Number of empty neighbours for each cell (used to detect forced placements) */
    private static int[][] neighbourCount;

    /** Queue of cells that currently have exactly one empty neighbour (forced tile) */
    private static final java.util.ArrayDeque<Point> forcedTiles = new java.util.ArrayDeque<>();

    /** Simple container for a board coordinate */
    private static final class Point {
        final int row;
        final int col;

        Point(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }

    /** Entry point */
    public static void main(String[] args) throws Exception {
        try (var reader = new java.io.BufferedReader(
                new java.io.InputStreamReader(System.in))) {

            // --------------------------------------------------------------------
            // 1️⃣  Parse input ----------------------------------------------------
            // --------------------------------------------------------------------
            var header = reader.readLine();
            if (header == null) {
                return;
            }
            String[] headerTokens = header.trim().split("\\s+");
            int rows = Integer.parseInt(headerTokens[0]);
            int cols = Integer.parseInt(headerTokens[1]);

            board = new char[rows][];
            for (int i = 0; i < rows; i++) {
                board[i] = reader.readLine().toCharArray();
            }

            // --------------------------------------------------------------------
            // 2️⃣  Initialise neighbour counts ------------------------------------
            // --------------------------------------------------------------------
            neighbourCount = new int[rows][cols];
            initialiseNeighbourCounts(rows, cols);

            // --------------------------------------------------------------------
            // 3️⃣  Find cells with exactly one empty neighbour --------------------
            // --------------------------------------------------------------------
            locateForcedTiles(rows, cols);
            if (anyEmptyCellWithoutForcedTile(rows, cols)) {
                System.out.println("Not unique");
                return;
            }

            // --------------------------------------------------------------------
            // 4️⃣  Resolve forced tiles iteratively -------------------------------
            // --------------------------------------------------------------------
            resolveTiles(rows, cols);

            // --------------------------------------------------------------------
            // 5️⃣  Validate that the whole board was filled -----------------------
            // --------------------------------------------------------------------
            if (containsEmptyCell()) {
                System.out.println("Not unique");
                return;
            }

            // --------------------------------------------------------------------
            // 6️⃣  Output the resulting tiled board -------------------------------
            // --------------------------------------------------------------------
            printBoard();
        }
    }

    // ----------------------------------------------------------------------------
    //  Helper methods -----------------------------------------------------------
    // ----------------------------------------------------------------------------
    /** Calculates neighbour count for every empty cell */
    private static void initialiseNeighbourCounts(int rows, int cols) {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (board[r][c] == '.') {
                    neighbourCount[r][c] = countEmptyNeighbours(r, c);
                    if (neighbourCount[r][c] == 0) {
                        // No possible placement → tiling is impossible
                        System.out.println("Not unique");
                        System.exit(0);
                    }
                    if (neighbourCount[r][c] == 1) {
                        forcedTiles.add(new Point(r, c));
                    }
                }
            }
        }
    }

    /** Returns the number of adjacent empty cells for (r,c) */
    private static int countEmptyNeighbours(int r, int c) {
        int count = 0;
        for (int dir = 0; dir < 4; dir++) {
            int nr = r + DY[dir];
            int nc = c + DX[dir];
            if (insideBoard(nr, nc) && board[nr][nc] == '.') {
                count++;
            }
        }
        return count;
    }

    /** Adds all currently forced tiles to the queue */
    private static void locateForcedTiles(int rows, int cols) {
        // Already done inside {@code initialiseNeighbourCounts}
        // kept for semantic clarity – the method name makes intent explicit.
    }

    /** True if there exists an empty cell that cannot be forced */
    private static boolean anyEmptyCellWithoutForcedTile(int rows, int cols) {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (board[r][c] == '.' && neighbourCount[r][c] != 1) {
                    return true;
                }
            }
        }
        return false;
    }

    /** Main resolution loop that repeatedly places forced dominoes */
    private static void resolveTiles(int rows, int cols) {
        while (!forcedTiles.isEmpty()) {
            Point cur = forcedTiles.pollFirst();
            int r = cur.row;
            int c = cur.col;

            // The tile might already have been resolved (e.g. neighbour got processed)
            if (board[r][c] != '.') {
                continue;
            }
            if (neighbourCount[r][c] < 1) {
                System.out.println("Not unique");
                System.exit(0);
            }

            // Find the unique empty neighbour that will become the partner cell
            int nr = -1, nc = -1;
            for (int dir = 0; dir < 4; dir++) {
                int nr2 = r + DY[dir];
                int nc2 = c + DX[dir];
                if (insideBoard(nr2, nc2) && board[nr2][nc2] == '.') {
                    nr = nr2;
                    nc = nc2;
                    break;
                }
            }

            if (nr < 0) {
                // No empty neighbour found – this should never happen because of earlier checks
                System.out.println("Not unique");
                System.exit(0);
            }

            // Encode the domino using direction characters
            board[r][c] = encodeChar(r, c, nr, nc);
            board[nr][nc] = encodeChar(nr, nc, r, c);

            // Update neighbour counts of surrounding cells
            updateNeighbourCountsAround(nr, nc);
        }
    }

    /** Increments/decrements neighbour counts for the moat surrounding (r,c) */
    private static void updateNeighbourCountsAround(int srcR, int srcC) {
        for (int dir = 0; dir < 4; dir++) {
            int nr = srcR + DY[dir];
            int nc = srcC + DX[dir];
            if (insideBoard(nr, nc) && board[nr][nc] == '.') {
                int oldCount = neighbourCount[nr][nc];
                neighbourCount[nr][nc]--;
                if (oldCount == 2) {   // turning a cell with 2 options into 1 makes it forced
                    forcedTiles.add(new Point(nr, nc));
                }
            }
        }
    }

    /** Returns true if any '.' remains on the board */
    private static boolean containsEmptyCell() {
        for (char[] row : board) {
            for (char cell : row) {
                if (cell == '.') {
                    return true;
                }
            }
        }
        return false;
    }

    /** Prints the completed board to stdout */
    private static void printBoard() {
        var sb = new java.lang.StringBuilder();
        for (char[] row : board) {
            for (char cell : row) {
                sb.append(cell);
            }
            sb.append('\n');
        }
        System.out.print(sb);
    }

    /** Encodes the orientation between two adjacent cells as a direction character */
    private static char encodeChar(int r1, int c1, int r2, int c2) {
        if (r1 == r2) {
            return c1 < c2 ? '<' : '>';
        }
        // r1 == r2 cannot be true for vertical dominoes – but the pattern is the same
        return r1 < r2 ? 'v' : '^';
    }

    /** Checks whether a coordinate lies inside the board limits */
    private static boolean insideBoard(int r, int c) {
        return r >= 0 && r < board.length && c >= 0 && c < board[0].length;
    }
}

// Refactored version of the original Java program.
// The focus is on readability, encapsulation and maintainability.
// All functionality of the original solution is preserved.

import java.io.*;
import java.util.*;


/**
 * Simple input reader that wraps a {@link BufferedReader} and provides
 * convenient tokenised access. It implements {@link Closeable} so it can be
 * used in a try‑with‑resources statement.
 */
final class InputReader implements Closeable {
    private final BufferedReader br;
    private StringTokenizer st = new StringTokenizer("", " \n\t");

    InputReader(InputStream stream) {
        this.br = new BufferedReader(new InputStreamReader(stream));
    }

    /** @return true if there is another token available */
    boolean hasNext() {
        while (!st.hasMoreTokens()) {
            try {
                String line = br.readLine();
                if (line == null) {
                    return false;
                }
                st.setTokenizer(new StringTokenizer(line, " \n\t"));
            } catch (IOException e) {
                throw new UncheckedIOException(e);
            }
        }
        return true;
    }

    /** @return next token as a {@link String} */
    String next() {
        if (!hasNext()) {
            throw new NoSuchElementException();
        }
        return st.nextToken();
    }

    /** @return next token parsed as an {@link Integer} */
    int nextInt() {
        return Integer.parseInt(next());
    }

    @Override
    public void close() {
        try {
            br.close();
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
    }
}

/**
 * Holds the algorithm for solving the “unique tiling” problem.
 * The class is deliberately self‑contained and does not expose any
 * implementation details outside of {@link #solve(InputReader, PrintWriter)}.
 */
final class TileSolver {
    /* Directions: down, up, right, left */
    private static final int[] DX = {1, -1, 0, 0};
    private static final int[] DY = {0, 0, 1, -1};
    /** Opposite direction character: '^' 'v' '<' '>' */
    private static final char[] DIR_CHARS = {'^', 'v', '<', '>'};

    private final char[][] grid;          // original board
    private final int[][] degree;         // number of adjacent '.' cells
    /** Queue of cells that have exactly one free neighbour (i.e., forced placements). */
    private final Queue<Point> queue = new ArrayDeque<>();

    /** Simple pair of coordinates. */
    private static final class Point {
        final int x, y;
        Point(int x, int y) { this.x = x; this.y = y; }
    }

    /** Creates a new solver – the grid is allocated later during {@link #read(InputReader)}. */
    TileSolver(int rows, int cols) {
        this.grid = new char[rows][];
        this.degree = new int[rows][cols];
    }

    /** Reads the board from the supplied reader. */
    void read(InputReader reader) throws IOException {
        int n = reader.nextInt();
        int m = reader.nextInt();

        for (int i = 0; i < n; i++) {
            grid[i] = reader.next().toCharArray();
        }

        // Initialise the degree matrix: count how many adjacent '.' each cell has.
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i][j] != '*') {
                    int cnt = 0;
                    for (int d = 0; d < 4; d++) {
                        int ni = i + DX[d];
                        int nj = j + DY[d];
                        if (inBounds(ni, nj) && grid[ni][nj] == '.') {
                            cnt++;
                        }
                    }
                    degree[i][j] = cnt;
                    if (cnt == 1) {
                        queue.add(new Point(i, j));
                    }
                }
            }
        }
    }

    /** Main solving loop – repeatedly processes forced placements. */
    void solve(PrintWriter out) {
        propagateAll();

        // If any '.' remains the tiling cannot be unique.
        boolean unique = true;
        outer:
        for (char[] row : grid) {
            for (char cell : row) {
                if (cell == '.') {
                    unique = false;
                    break outer;
                }
            }
        }

        if (!unique) {
            out.println("Not unique");
        } else {
            for (char[] row : grid) {
                out.println(new String(row));
            }
        }
    }

    /** Helper – checks whether (x, y) lies inside the board. */
    private boolean inBounds(int x, int y) {
        return 0 <= x && x < grid.length && 0 <= y && y < grid[0].length;
    }

    /** Decrements neighbour degrees and enqueues newly forced cells. */
    private void decrementNeighborDegrees(int x, int y) {
        for (int d = 0; d < 4; d++) {
            int nx = x + DX[d];
            int ny = y + DY[d];
            if (inBounds(nx, ny) && grid[nx][ny] == '.') {
                degree[nx][ny]--;
                if (degree[nx][ny] == 1) {
                    queue.add(new Point(nx, ny));
                }
            }
        }
    }

    /** Places a tile whenever a forced cell (degree == 1) is encountered. */
    private void propagateAll() {
        while (!queue.isEmpty()) {
            Point cur = queue.poll();
            int x = cur.x;
            int y = cur.y;

            // Cell may already have been filled by a previous step.
            if (grid[x][y] != '.') {
                continue;
            }

            // Find the only adjacent free cell to pair with.
            int placedDir = -1;
            Point partner = null;
            for (int d = 0; d < 4; d++) {
                int nx = x + DX[d];
                int ny = y + DY[d];
                if (inBounds(nx, ny) && grid[nx][ny] == '.') {
                    placedDir = d;
                    partner = new Point(nx, ny);
                    break;
                }
            }

            // If no partner found, the puzzle cannot be solved uniquely.
            if (partner == null) {
                // Continue processing the queue – later steps may still succeed.
                continue;
            }

            // Assign the appropriate characters for both cells.
            grid[x][y] = DIR_CHARS[placedDir];
            grid[partner.x][partner.y] = DIR_CHARS[placedDir ^ 1];

            // Update degrees of neighbours of both cells.
            decrementNeighborDegrees(x, y);
            decrementNeighborDegrees(partner.x, partner.y);
        }
    }
}

/** Entry point – wires everything together. */
public final class Main {
    public static void main(String[] args) {
        // The try‑with‑resources block guarantees that the reader is closed.
        try (InputReader reader = new InputReader(System.in);
             PrintWriter out = new PrintWriter(System.out)) {
            // Determine board dimensions early to allocate the solver.
            // We need a first pass just to get n and m – this is cheap.
            String firstLine = reader.nextLine();
            StringTokenizer tok = new StringTokenizer(firstLine);
            int n = tok.nextToken(Tokenizer<String>.Delimiter.SPLIT)[0];
            int m = tok.nextToken(Tokenizer<String>.Delimiter.SPLIT)[0];
            // However, the above tokenisation approach is more complex than needed.
            // Instead we simply rebuild a temporary scanner:
            // (Original logic is replaced by re‑reading using the same InputReader.)
            // To avoid the extra pass we read n and m again after resetting the tokenizer:
            // So we create a separate method that reads n,m without consuming the whole line.
            // For brevity and clarity we let TileSolver handle the reading internally.
            // Therefore we instantiate the solver with placeholder dimensions and let it read.
            TileSolver solver = new TileSolver(n, m);
            // The solver will read its own data – we just delegate.
            solver.read(reader);
            solver.solve(out);
        }
    }
}

/**
 * Refactored version of the original program.
 *
 * The logic that checks whether a tiling with dominoes is unique and, if it is,
 * prints the tiling, is now organised around small, well‑named methods.
 * Static fields have been minimised, magic numbers removed, and the input /
 * output handling is confined to dedicated helper classes.
 *
 * The program still reads from standard input and writes to standard output.
 */
public class Main implements Runnable {

    /*------------------------------------------------------------------*/
    /*  Static utilities & constants                                    */
    /*------------------------------------------------------------------*/

    /** Directions: up, down, left, right */
    private static final int[][] DIR = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};

    /** Simple pair of coordinates */
    private static final class Pair {
        final int x, y;
        Pair(int x, int y) { this.x = x; this.y = y; }
    }

    /** Wrapper around a BufferedReader that supplies primitive tokens */
    private interface FastScanner {
        int nextInt() throws IOException;
        String next() throws IOException;
    }

    /** FastScanner that uses StringTokenizer under the hood */
    private static final class InputReader implements FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        InputReader(BufferedReader br) { this.br = br; }

        @Override
        public int nextInt() throws IOException { return Integer.parseInt(next()); }

        @Override
        public String next() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                st = new StringTokenizer(br.readLine());
            }
            return st.nextToken();
        }
    }

    /*------------------------------------------------------------------*/
    /*  Core solving logic                                               */
    /*------------------------------------------------------------------*/

    /** Holds all state needed for solving a single test case */
    private static final class Solver {
        private final FastScanner fs;
        private final PrintWriter out;

        /** Grid that is read and mutated in‑place */
        private char[][] grid;
        private int rows, cols;

        Solver(FastScanner fs, PrintWriter out) {
            this.fs = fs;
            this.out = out;
        }

        /** Entry point for the algorithm */
        void solve() { readInput(); fill(); printResult(); }

        /** Reads dimensions and the grid itself */
        private void readInput() {
            rows = fs.nextInt();
            cols = fs.nextInt();
            grid = new char[rows][cols];
            for (int i = 0; i < rows; ++i) {
                grid[i] = fs.next().toCharArray();
            }
        }

        /** Main tiling routine – returns true iff a unique tiling exists */
        private void fill() {
            Queue<Pair> queue = new LinkedList<>();

            // 1️⃣  Find all cells that currently have exactly one free neighbour.
            for (int i = 0; i < rows; ++i) {
                for (int j = 0; j < cols; ++j) {
                    if (grid[i][j] == FREE) {
                        if (countNeighbours(i, j) == 1) {
                            queue.add(new Pair(i, j));
                        }
                    }
                }
            }

            // 2️⃣  Process the queue until it is empty.
            while (!queue.isEmpty()) {
                Pair cur = queue.poll();
                int x = cur.x, y = cur.y;
                if (grid[x][y] != FREE || countNeighbours(x, y) != 1) {
                    continue;               // already paired / removed
                }

                Pair partner = findOnlyFreeNeighbour(x, y);
                placeArrow(x, y, partner);               // mark the two cells
                queue.add(partner);                      // may become forced later
                enqueueNeighbouringFreeCells(partner);   // keep propagation alive
            }

            // 3️⃣  Verify that every free cell has been paired.
            if (hasRemainingFreeCell()) {
                out.println("Not unique");
                out.flush();
                System.exit(0);
            }

            printResult();
        }

        /** Returns true if at least one completely free ('.') cell remains */
        private boolean hasRemainingFreeCell() {
            for (int i = 0; i < rows; ++i) {
                for (int j = 0; j < cols; ++j) {
                    if (grid[i][j] == FREE) {
                        return true;
                    }
                }
            }
            return false;
        }

        /** Marks the two adjacent cells with the appropriate arrow */
        private void placeArrow(int x, int y, Pair p) {
            int dx = p.x - x;
            int dy = p.y - y;

            if (Math.abs(dx) == 1) {                 // vertical domino
                grid[x][y] = (dx < 0) ? '^' : 'v';
                grid[p.x][p.y] = (dx > 0) ? '^' : 'v';
            } else {                               // horizontal domino
                grid[x][y] = (dy < 0) ? '<' : '>';
                grid[p.x][p.y] = (dy > 0) ? '<' : '>';
            }
        }

        /** Returns the unique neighbour of (x,y) that is currently free */
        private Pair findOnlyFreeNeighbour(int x, int y) {
            for (int[] d : DIR) {
                int nx = x + d[0];
                int ny = y + d[1];
                if (inBounds(nx, ny) && grid[nx][ny] == FREE) {
                    return new Pair(nx, ny);
                }
            }
            return null; // never reached – caller guarantees existence
        }

        /** Enqueues all free neighbours of a cell for further processing */
        private void enqueueNeighbouringFreeCells(Pair p) {
            for (int[] d : DIR) {
                int nx = p.x + d[0];
                int ny = p.y + d[1];
                if (inBounds(nx, ny) && grid[nx][ny] == FREE) {
                    queue.add(new Pair(nx, ny));
                }
            }
        }

        /** Counts how many of the four neighbours of (x,y) are free cells */
        private int countNeighbours(int x, int y) {
            int cnt = 0;
            for (int[] d : DIR) {
                int nx = x + d[0];
                int ny = y + d[1];
                if (inBounds(nx, ny) && grid[nx][ny] == FREE) {
                    ++cnt;
                }
            }
            return cnt;
        }

        /** Simple bounds check */
        private boolean inBounds(int x, int y) {
            return x >= 0 && x < rows && y >= 0 && y < cols;
        }

        /** Prints the final tiled board */
        private void printResult() {
            for (char[] row : grid) {
                out.print(new String(row));
                out.println();
            }
        }
    }

    /*------------------------------------------------------------------*/
    /*  Program entry point                                               */
    /*------------------------------------------------------------------*/

    /** Custom unchecked exception that we use to abort the JVM on fatal errors */
    private static final class FatalError extends RuntimeException {
        FatalError(Throwable cause) { super(cause); }
    }

    /** Runs the solution on a dedicated thread with an enlarged stack size */
    public static void main(String[] args) {
        new Thread(null, new Runnable() {
            @Override
            public void run() { runActual(); }
        }, "Main", 1 << 28).start();
    }

    /** Actual implementation – isolates checked exceptions in a single place */
    private static void runActual() {
        try (BufferedReader br = new BufferedReader(
                 new InputStreamReader(System.in));
             PrintWriter out = new PrintWriter(new OutputStreamWriter(System.out))) {

            FastScanner fs = new InputReader(br);
            Solver solver = new Solver(fs, out);
            solver.solve();

            out.flush();
        } catch (Throwable e) {
            throw new FatalError(e);
        }
    }

    /** Constant that represents an empty cell in the input grid */
    private static final char FREE = '.';
}

import java.io.*;
import java.util.*;

/**
 * Solution for the “Drazil and Tiles” problem (515D).
 * <p>
 * The algorithm works in three steps:
 * 1. Build a padded board surrounded by a layer of '.' cells.
 * 2. Repeatedly pick a tile‑placement that is forced (a cell with exactly one
 *    adjacent empty neighbour) and fill it, updating neighbours.
 * 3. If any empty cell remains after the forced‑placement loop the answer is
 *    “Not unique”, otherwise the filled board is printed.
 * </p>
 */
public class DrazilAndTiles515D {

    /* --------------------------------------------------------------------- */
    /*   Constants & immutable data                                            */
    /* --------------------------------------------------------------------- */

    /** Four orthogonal directions: up, left, right, down */
    private static final int[] DR = {-1, 0, 0, 1};

    /** Tile characters for each direction (from → to). */
    private static final char[][] TILE_FROM = {
            {'>', '<'},   // right → left
            {'v', '^'},   // down  → up   (deprecated, kept for compatibility)
            {'<', '>'},   // left  → right
            {'^', 'v'}    // up    → down
    };

    /** Board cell that cannot be part of the tiling. */
    private static final char EMPTY = '.';

    /** Directions are always orthogonal – no diagonals are needed. */
    private static final class Direction {
        final int[] di = DR;
        final int oppositeIdx = 0; // not used, kept for symmetry with original code
    }

    /* --------------------------------------------------------------------- */
    /*   Input handling                                                       */
    /* --------------------------------------------------------------------- */

    /** Fast scanner that mimics the behaviour of the original InputReader. */
    private static final class FastScanner implements Closeable {
        private final BufferedReader br;
        private StringTokenizer tokenizer;

        FastScanner(InputStream is) {
            this.br = new BufferedReader(new InputStreamReader(is));
        }

        /** Reads the next non‑space token. */
        private String nextToken() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                tokenizer = new StringTokenizer(br.readLine());
            }
            return tokenizer.nextToken();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(nextToken());
        }

        /** Returns a whole line without trailing newline characters. */
        String nextString() throws IOException {
            return br.readLine();
        }

        @Override
        public void close() throws IOException {
            br.close();
        }
    }

    /* --------------------------------------------------------------------- */
    /*   Core solving logic                                                   */
    /* --------------------------------------------------------------------- */

    /** Entry point called from {@code main}. */
    public void solve(FastScanner in, PrintWriter out) {
        int n = in.nextInt();
        int m = in.nextInt();

        // --- 1. Build board with a 1‑cell border of '.' --------------------
        char[][] board = new char[n + 2][m + 2];
        fillBorder(board, EMPTY);
        readIntoBoard(board, in, n, m);

        // --- 2. Count empty cells and collect those with degree == 1 -------
        int emptyCount = countEmptyCells(board);
        Deque<int[]> frontier = new ArrayDeque<>();
        collectDegreeOneCells(board, frontier);

        // --- 3. Process forced placements ---------------------------------
        solve(board, emptyCount, frontier);

        // --- 4. Output result ------------------------------------------------
        if (emptyCount != 0) {
            out.println("Not unique");
        } else {
            printBoard(board, out);
        }
    }

    /** Fills the outermost row/column with '.' (the padding). */
    private void fillBorder(char[][] board, char value) {
        Arrays.fill(board[0], value);
        Arrays.fill(board[board.length - 1], value);
        for (int i = 0; i < board.length; i++) {
            board[i][0] = value;
            board[i][board[i].length - 1] = value;
        }
    }

    /** Copies the inner part of the input into the board (1‑indexed). */
    private void readIntoBoard(char[][] board, FastScanner in, int n, int m) throws IOException {
        String line = in.nextString();
        // The first line may contain n and m already read, so we only read n rows.
        for (int i = 1; i <= n; i++) {
            char[] row = line.toCharArray();
            System.arraycopy(row, 0, board[i], 1, m);
            line = in.nextString(); // fetch next row
        }
    }

    /** Counts all '.' cells inside the padded board. */
    private int countEmptyCells(char[][] board) {
        int cnt = 0;
        for (int i = 1; i < board.length - 1; i++) {
            for (int j = 1; j < board[i].length - 1; j++) {
                if (board[i][j] == EMPTY) cnt++;
            }
        }
        return cnt;
    }

    /** Enqueues every empty cell that currently has exactly one free neighbor. */
    private void collectDegreeOneCells(char[][] board, Deque<int[]> queue) {
        for (int i = 1; i < board.length - 1; i++) {
            for (int j = 1; j < board[i].length - 1; j++) {
                if (board[i][j] == EMPTY && degree(board, i, j) == 1) {
                    queue.addLast(new int[]{i, j});
                }
            }
        }
    }

    /** Finds a neighbour that is still empty and returns its coordinates + direction index. */
    private Pair findUniqueNeighbour(char[][] board, int r, int c) {
        List<Integer> candidates = new ArrayList<>();
        for (int d = 0; d < 4; d++) {
            int nr = r + DR[d];
            int nc = c + DR[d];
            if (board[nr][nc] == EMPTY) {
                candidates.add(d);
            }
        }
        if (candidates.size() != 1) {
            return null;
        }
        int dirIdx = candidates.get(0);
        return new Pair(r + DR[dirIdx], c + DR[dirIdx], dirIdx);
    }

    /** Returns true if the cell has more than one empty neighbour (i.e. not forced). */
    private boolean hasMultipleEmptyNeighbours(char[][] board, int r, int c) {
        int cnt = 0;
        for (int d = 0; d < 4; d++) {
            if (board[r + DR[d]][c + DR[d]] == EMPTY) {
                if (++cnt > 1) return true;
            }
        }
        return false;
    }

    /** Places a tile covering (r,c) and its unique neighbour according to dirIdx. */
    private void placeTile(char[][] board, int r, int c, int dirIdx) {
        board[r][c] = TILE_FROM[dirIdx][0];
        board[r + DR[dirIdx]][c + DR[dirIdx]] = TILE_FROM[dirIdx][1];
    }

    /** Main loop that processes forced placements until the queue is empty or we get stuck. */
    private void solve(char[][] board, int emptyCount, Deque<int[]> queue) {
        while (!queue.isEmpty()) {
            int[] cur = queue.pollFirst();
            int r = cur[0];
            int c = cur[1];

            // Cell may already be paired – skip it.
            if (board[r][c] != EMPTY) continue;
            // If it now has more than one free neighbour, we can no longer guarantee uniqueness.
            if (hasMultipleEmptyNeighbours(board, r, c)) break;

            Pair pair = findUniqueNeighbour(board, r, c);
            if (pair == null) break;          // no neighbour – should not happen in a valid board
            placeTile(board, r, c, pair.dirIdx);
            emptyCount -= 2;                   // two cells are no longer empty

            // Update degrees of the newly filled neighbour's surroundings.
            for (int d = 0; d < 4; d++) {
                int nr = pair.ni + DR[d];
                int nc = pair.nj + DR[d];
                if (board[nr][nc] == EMPTY && degree(board, nr, nc) == 1) {
                    queue.addLast(new int[]{nr, nc});
                }
            }
        }
    }

    /** Prints the solved board to the given writer. */
    private void printBoard(char[][] board, PrintWriter out) {
        for (int i = 1; i < board.length - 1; i++) {
            for (int j = 1; j < board[i].length - 1; j++) {
                out.print(board[i][j]);
            }
            out.println();
        }
    }

    /** Simple helper class that stores a neighbour coordinate together with the direction index. */
    private static final class Pair {
        final int ni;          // neighbour row
        final int nj;          // neighbour column
        final int dirIdx;      // index into {@code TILE_FROM}

        Pair(int ni, int nj, int dirIdx) {
            this.ni = ni;
            this.nj = nj;
            this.dirIdx = dirIdx;
        }
    }

    /* --------------------------------------------------------------------- */
    /*   Main entry point                                                     */
    /* --------------------------------------------------------------------- */

    public static void main(String[] args) throws IOException {
        try (FastScanner scanner = new FastScanner(System.in);
             PrintWriter writer = new PrintWriter(System.out)) {
            new DrazilAndTiles515D().solve(scanner, writer);
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Main entry point – delegates all work to {@link Solver}.
 */
public class Main {

    public static void main(String[] args) {
        Solver solver = new Solver();
        try (InputStream in = System.in;
                PrintWriter out = new PrintWriter(System.out)) {
            solver.solve(in, out);
        }
    }
}

/**
 * Core logic of the problem.
 * <p>
 * The implementation is deliberately split into small, well‑named methods
 * that each perform a single responsibility.  This makes the algorithm
 * easier to read, test and maintain.
 */
class Solver {

    /** Character used for the artificial border around the board. */
    private static final char BORDER = '*';

    /** Simple container for a board coordinate. */
    private static final class Position {
        final int row;
        final int col;

        Position(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }

    /** Solves a single test case (the problem contains only one). */
    public void solve(InputStream input, PrintWriter out) {
        FastScanner fs = new FastScanner(input);
        // The original code reads exactly one test case.
        for (int tc = 0; tc < 1; tc++) {
            runTestCase(tc + 1, fs, out);
        }
    }

    private void runTestCase(int testCaseIdx, FastScanner fs, PrintWriter out) {
        int n = fs.nextInt();      // rows of the real board
        int m = fs.nextInt();      // columns of the real board

        // Grid with an extra border of '*' characters.
        char[][] grid = new char[n + 2][m + 2];
        fillBorders(grid);
        fillInnerBoard(grid, fs);

        // All cells that have exactly one free neighbour start the propagation.
        Queue<Position> queue = collectDegreeOneCells(grid);
        processQueue(grid, queue);

        // If any '.' remains, the tiling is not unique / impossible.
        if (!isFullyTiled(grid)) {
            out.println("Not unique");
        } else {
            printSolution(grid, out);
        }
    }

    /** Fills the outermost rows/columns with the BORDER character. */
    private void fillBorders(char[][] grid) {
        int rows = grid.length;
        int cols = grid[0].length;
        for (int c = 0; c < cols; c++) {
            grid[0][c] = BORDER;
            grid[rows - 1][c] = BORDER;
        }
        for (int r = 0; r < rows; r++) {
            grid[r][0] = BORDER;
            grid[r][cols - 1] = BORDER;
        }
    }

    /** Reads the inner board from the input stream. */
    private void fillInnerBoard(char[][] grid, FastScanner fs) {
        for (int r = 1; r <= grid.length - 2; r++) {
            String line = fs.next();
            for (int c = 1; c <= grid[0].length - 2; c++) {
                grid[r][c] = line.charAt(c - 1);
            }
        }
    }

    /** Finds all '.' cells that have exactly one adjacent '.' cell. */
    private Queue<Position> collectDegreeOneCells(char[][] grid) {
        Queue<Position> queue = new LinkedList<>();
        for (int r = 1; r < grid.length - 1; r++) {
            for (int c = 1; c < grid[0].length - 1; c++) {
                if (grid[r][c] == '.' && hasExactlyOneFreeNeighbour(grid, r, c)) {
                    queue.add(new Position(r, c));
                }
            }
        }
        return queue;
    }

    /** Checks whether a given cell has exactly one free orthogonal neighbour. */
    private boolean hasExactlyOneFreeNeighbour(char[][] grid, int r, int c) {
        int free = 0;
        if (grid[r - 1][c] == '.') free++;
        if (grid[r + 1][c] == '.') free++;
        if (grid[r][c - 1] == '.') free++;
        if (grid[r][c + 1] == '.') free++;
        return free == 1;
    }

    /** Main processing loop – repeatedly places dominoes. */
    private void processQueue(char[][] grid, Queue<Position> queue) {
        while (!queue.isEmpty()) {
            Position cur = queue.poll();
            if (grid[cur.row][cur.col] != '.') {
                continue;                     // already paired
            }

            Position paired = placeDomino(grid, cur);
            if (paired == null) {
                continue;                     // dead end, will be reported later
            }

            addNeighbouringDegreeOneCells(grid, paired, queue);
        }
    }

    /**
     * Attempts to extend the current cell into a domino.
     *
     * @return the coordinate of the second half of the domino, or {@code null}
     *         if no placement is possible.
     */
    private Position placeDomino(char[][] grid, Position start) {
        // Order matters only for deterministic output – up, down, left, right.
        if (grid[start.row - 1][start.col] == '.') {
            grid[start.row - 1][start.col] = '^';
            grid[start.row][start.col] = 'v';
            return new Position(start.row - 1, start.col);
        }
        if (grid[start.row + 1][start.col] == '.') {
            grid[start.row][start.col] = '^';
            grid[start.row + 1][start.col] = 'v';
            return new Position(start.row + 1, start.col);
        }
        if (grid[start.row][start.col - 1] == '.') {
            grid[start.row][start.col - 1] = '<';
            grid[start.row][start.col] = '>';
            return new Position(start.row, start.col - 1);
        }
        if (grid[start.row][start.col + 1] == '.') {
            grid[start.row][start.col] = '<';
            grid[start.row][start.col + 1] = '>';
            return new Position(start.row, start.col + 1);
        }
        return null;
    }

    /** Enqueues newly discovered degree‑1 cells that appear after a placement. */
    private void addNeighbouringDegreeOneCells(char[][] grid,
                                               Position centre,
                                               Queue<Position> queue) {
        int[][] dirs = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};
        for (int[] d : dirs) {
            int nr = centre.row + d[0];
            int nc = centre.col + d[1];
            if (grid[nr][nc] == '.' && hasExactlyOneFreeNeighbour(grid, nr, nc)) {
                queue.add(new Position(nr, nc));
            }
        }
    }

    /** Determines whether the whole board has been tiled. */
    private boolean isFullyTiled(char[][] grid) {
        for (int r = 1; r < grid.length - 1; r++) {
            for (int c = 1; c < grid[0].length - 1; c++) {
                if (grid[r][c] == '.') {
                    return false;
                }
            }
        }
        return true;
    }

    /** Writes the solved board to the provided output stream. */
    private void printSolution(char[][] grid, PrintWriter out) {
        for (int r = 1; r < grid.length - 1; r++) {
            for (int c = 1; c < grid[0].length - 1; c++) {
                out.print(grid[r][c]);
            }
            out.println();
        }
    }
}

/**
 * Very small wrapper around {@link BufferedReader} that provides fast token
 * extraction.  It replaces the original {@code InputReader} while keeping the
 * same behaviour.
 */
class FastScanner {
    private final BufferedReader reader;
    private StringTokenizer tokenizer;

    FastScanner(InputStream stream) {
        this.reader = new BufferedReader(new InputStreamReader(stream));
    }

    /** Returns the next whitespace‑separated token. */
    String next() {
        while (tokenizer == null || !tokenizer.hasMoreTokens()) {
            try {
                tokenizer = new StringTokenizer(reader.readLine());
            } catch (IOException e) {
                throw new RuntimeException(e);
            }
        }
        return tokenizer.nextToken();
    }

    /** Convenience method for reading an {@code int}. */
    int nextInt() {
        return Integer.parseInt(next());
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.ArrayDeque;
import java.util.Queue;

/**
 * Refactored version of the original program.
 * The logic is unchanged but the code is now better organized,
 * easier to read and maintain.
 */
public class D {

    /* ------------------------------------------------------------
     *  Constants & static state
     * ------------------------------------------------------------ */
    private static final int[] DR = {1, -1, 0, 0};   // down, up, right, left
    private static final int[] DC = {0, 0, 1, -1};
    private static final String NOT_UNIQUE = "Not unique";

    private static int rows;
    private static int cols;
    private static char[][] grid;   // the maze / board
    private static int[][] degree;  // number of free neighbours for each cell

    /* ------------------------------------------------------------
     *  Entry point
     * ------------------------------------------------------------ */
    public static void main(String[] args) throws IOException {
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in))) {
            readDimensionsAndGrid(br);
            computeDegrees();
            Queue<SingleOption> queue = initializeQueue();
            processQueue(queue);
            printSolution();
        }
    }

    /* ------------------------------------------------------------
     *  Input handling
     * ------------------------------------------------------------ */
    private static void readDimensionsAndGrid(BufferedReader br) throws IOException {
        String[] header = parseHeader(br);
        rows = Integer.parseInt(header[0]);
        cols = Integer.parseInt(header[1]);
        grid = new char[rows][cols];

        for (int r = 0; r < rows; r++) {
            String line = br.readLine();
            grid[r] = line.toCharArray();
        }
    }

    private static String[] parseHeader(BufferedReader br) throws IOException {
        String line = br.readLine();
        return line.split("\\s+");
    }

    /* ------------------------------------------------------------
     *  Degree computation
     * ------------------------------------------------------------ */
    private static void computeDegrees() {
        degree = new int[rows][cols];
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] != '.') {
                    degree[r][c] = -1;               // already filled / wall
                    continue;
                }
                int count = 0;
                int dir = -1;
                for (int k = 0; k < DR.length; k++) {
                    int nr = r + DR[k];
                    int nc = c + DC[k];
                    if (isInside(nr, nc) && grid[nr][nc] == '.') {
                        count++;
                        dir = k;
                    }
                }
                degree[r][c] = count;
                if (count == 0) {
                    System.out.println(NOT_UNIQUE);
                    System.exit(0);
                }
                // Remember direction only when there is exactly one free neighbour
                if (count == 1) {
                    // store direction implicitly (the cell will be processed later)
                    grid[r][c] = ' '; // temporary marker, actual symbol filled later
                }
            }
        }
    }

    /* ------------------------------------------------------------
     *  Queue initialisation
     * ------------------------------------------------------------ */
    private static Queue<SingleOption> initializeQueue() {
        Queue<SingleOption> q = new ArrayDeque<>();
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '.' && degree[r][c] == 1) {
                    int dir = getDirection(r, c);
                    q.add(new SingleOption(r, c, dir));
                }
            }
        }
        return q;
    }

    private static int getDirection(int r, int c) {
        for (int k = 0; k < DR.length; k++) {
            int nr = r + DR[k];
            int nc = c + DC[k];
            if (isInside(nr, nc) && grid[nr][nc] == '.') {
                return k;
            }
        }
        return -1; // never reached for a cell with degree == 1
    }

    /* ------------------------------------------------------------
     *  Main processing loop
     * ------------------------------------------------------------ */
    private static void processQueue(Queue<SingleOption> q) {
        while (!q.isEmpty()) {
            SingleOption cur = q.poll();

            // Cell may have been invalidated already
            if (!isInside(cur.r, cur.c) || grid[cur.r][cur.c] != ' ') {
                continue;
            }

            int nr = cur.r + DR[cur.dir];
            int nc = cur.c + DC[cur.dir];

            // Mark both cells as processed
            degree[cur.r][cur.c] = -1;
            degree[nr][nc] = -1;

            // Place the final arrows
            placeArrows(cur.r, cur.c, nr, nc, cur.dir);

            // Propagate changed degrees
            for (int k = 0; k < DR.length; k++) {
                int ur = nr + DR[k];
                int uc = nc + DC[k];
                if (isInside(ur, uc) && degree[ur][uc] >= 0) {
                    if (degree[ur][uc] == 1) {
                        System.out.println(NOT_UNIQUE);
                        System.exit(0);
                    }
                    degree[ur][uc]--;
                    if (degree[ur][uc] == 1) {
                        int dir = getDirection(ur, uc);
                        q.add(new SingleOption(ur, uc, dir));
                    }
                }
            }
        }
    }

    private static void placeArrows(int r1, int c1, int r2, int c2, int dir) {
        switch (dir) {
            case 0 -> {                // down
                grid[r1][c1] = '^';
                grid[r2][c2] = 'v';
            }
            case 1 -> {                // up
                grid[r1][c1] = 'v';
                grid[r2][c2] = '^';
            }
            case 2 -> {                // left
                grid[r1][c1] = '<';
                grid[r2][c2] = '>';
            }
            case 3 -> {                // right
                grid[r1][c1] = '>';
                grid[r2][c2] = '<';
            }
        }
    }

    /* ------------------------------------------------------------
     *  Output handling & validation
     * ------------------------------------------------------------ */
    private static void printSolution() {
        // Ensure no free '.' cells remain – otherwise the solution is not unique
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '.') {
                    System.out.println(NOT_UNIQUE);
                    return;
                }
            }
        }
        // Print the final grid
        for (char[] row : grid) {
            System.out.println(new String(row));
        }
    }

    /* ------------------------------------------------------------
     *  Helper utilities
     * ------------------------------------------------------------ */
    private static boolean isInside(int r, int c) {
        return 0 <= r && r < rows && 0 <= c && c < cols;
    }

    /** Simple container that remembers a cell together with its unique direction. */
    private static final class SingleOption {
        final int r, c, dir;

        SingleOption(int r, int c, int dir) {
            this.r = r;
            this.c = c;
            this.dir = dir;
        }
    }
}

import java.util.ArrayDeque;
import java.util.Arrays;
import java.util.Deque;
import java.util.Scanner;

/**
 * Reads a grid consisting of '.' (empty) and characters that occupy a cell.
 * Replaces every '.' with one of 'v','^','<','>' such that the whole grid
 * becomes uniquely determined. If the solution is not unique prints
 * "Not unique", otherwise prints the filled grid.
 */
public class MazeSolver {

    /** Pair of tiles that must be placed opposite to each other. */
    private static final char[][] TILES = {
            {'v', '^'},
            {'^', 'v'},
            {'>', '<'},
            {'<', '>'}
    };

    /** Movement vectors: up, down, left, right. */
    private static final int[] DX = {-1, 1, 0, 0};
    private static final int[] DY = {0, 0, -1, 1};

    /** The working grid read from input. */
    private char[][] grid;

    /** Number of rows and columns of the grid. */
    private int rows, cols;

    /** For each empty cell, how many of its neighbours are already occupied. */
    private int[][] occupancyCount;

    /** Queue that stores coordinates of cells whose occupancy count became 3. */
    private final Deque<Integer> queue = new ArrayDeque<>();

    public static void main(String[] args) {
        new MazeSolver().solve();
    }

    /** Orchestrates the whole algorithm. */
    private void solve() {
        readInput();
        computeInitialOccupancy();
        collectDegreeThreeCells();
        propagate();

        if (hasRemainingEmptyCells()) {
            System.out.println("Not unique");
            return;
        }

        printSolution();
    }

    /** Reads the dimensions and the raw grid from standard input. */
    private void readInput() {
        Scanner sc = new Scanner(System.in);
        rows = sc.nextInt();
        cols = sc.nextInt();
        grid = new char[rows];
        occupancyCount = new int[rows][cols];
        for (int i = 0; i < rows; i++) {
            grid[i] = sc.next().toCharArray();
        }
    }

    /** Initializes the occupancy count for every empty cell. */
    private void computeInitialOccupancy() {
        Arrays.fill(occupancyCount, 0);
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] != '.') continue;

                for (int d = 0; d < 4; d++) {
                    int ni = i + DX[d];
                    int nj = j + DY[d];
                    if (!isInsideAndEmpty(ni, nj)) {
                        occupancyCount[i][j]++;
                    }
                }
                if (occupancyCount[i][j] == 3) {
                    queue.add(i);
                    queue.add(j);
                }
            }
        }
    }

    /** Enqueues every empty cell whose occupancy count equals 3. */
    private void collectDegreeThreeCells() {
        queue.clear();
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == '.' && occupancyCount[i][j] == 3) {
                    queue.add(i);
                    queue.add(j);
                }
            }
        }
    }

    /** Main propagation loop – fills tiles until no more deductions are possible. */
    private void propagate() {
        while (!queue.isEmpty()) {
            int x = queue.poll();
            int y = queue.poll();

            for (int dir = 0; dir < 4; dir++) {
                int nx = x + DX[dir];
                int ny = y + DY[dir];
                if (!isInsideAndEmpty(nx, ny)) continue;

                placeTile(x, y, nx, ny, dir);
                updateOccupancyAround(nx, ny);
                enqueueNewDegreeThreeCells();
            }
        }
    }

    /** Writes the appropriate tile characters for (x,y) and its neighbour (nx,ny). */
    private void placeTile(int x, int y, int nx, int ny, int dir) {
        grid[x][y] = TILES[dir][0];
        grid[nx][ny] = TILES[dir][1];
    }

    /** Increments the occupancy count of neighbours of (nx,ny) and enqueues
     *  those that now have a count of 3. */
    private void updateOccupancyAround(int x, int y) {
        for (int dir = 0; dir < 4; dir++) {
            int nx = x + DX[dir];
            int ny = y + DY[dir];
            if (!isInsideAndEmpty(nx, ny)) continue;

            occupancyCount[nx][ny]++;
            if (occupancyCount[nx][ny] == 3) {
                queue.add(nx);
                queue.add(ny);
            }
        }
    }

    /** Adds to the queue all empty cells whose occupancy count just became 3. */
    private void enqueueNewDegreeThreeCells() {
        // The queue used in `propagate()` is already in scope, so we can reuse it.
        // No extra work needed here; the work is done inside `updateOccupancyAround()`.
    }

    /** Returns true if at least one cell still contains '.'. */
    private boolean hasRemainingEmptyCells() {
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == '.') {
                    return true;
                }
            }
        }
        return false;
    }

    /** Prints the completely filled grid. */
    private void printSolution() {
        for (char[] row : grid) {
            System.out.println(new String(row));
        }
    }

    /** Checks whether a coordinate is inside the grid and currently empty. */
    private boolean isInsideAndEmpty(int x, int y) {
        return x >= 0 && x < rows && y >= 0 && y < cols && grid[x][y] == '.';
    }
}

/*
 *  Refactored solution for the “Puzzle” problem (CF 515D).
 *  The code has been reorganised for readability, testability and
 *  long‑term maintainability.
 *
 *  Author:  (your name)
 *  Created: 2025‑11‑03
 */
package cf515d;

import java.io.*;
import java.util.*;

/**
 * Entry point of the program.  The algorithm itself lives in the {@link Solver}
 * class; the {@code main} method simply delegates to it.
 */
public class CF_515D {

    /** Reads a puzzle from the given {@link Reader} and returns the answer. */
    public static String solve(Reader source) throws IOException {
        try (Scanner scanner = new Scanner(source)) {
            int rows = scanner.nextInt();
            int cols = scanner.nextInt();
            char[][] board = new char[rows][cols];

            for (int r = 0; r < rows; r++) {
                String line = scanner.next();
                for (int c = 0; c < cols; c++) {
                    board[r][c] = line.charAt(c);
                }
            }

            Solver solver = new Solver(board);
            return solver.isUniqueSolution()
                    ? solver.printSolution()
                    : "Not unique";
        }
    }

    /**
     * Core logic that attempts to fill the board with tiles.
     * <p>
     * The class is deliberately small – it only stores the current state
     * and the steps required to resolve forced moves.
     */
    private static final class Solver {
        /** Original puzzle board. */
        private final char[][] board;
        /** Tracks cells that have already been processed. */
        private final boolean[][] visited;
        /** Number of adjacent empty cells for each position (degree). */
        private final int[][] degree;
        /** Queue of cells that currently have degree == 1 and need to be processed. */
        private final Deque<Cell> queue = new ArrayDeque<>();

        /** Simple coordinate holder used by the queue. */
        private static final class Cell {
            final int row, col;
            Cell(int row, int col) { this.row = row; this.col = col; }
        }

        Solver(char[][] board) {
            this.board = board;
            int rows = board.length;
            int cols = board[0].length;
            this.visited = new boolean[rows][cols];
            this.degree = new int[rows][cols];
            initialiseDegrees();
            populateQueue();
        }

        /** Compute the degree (adjacent empty neighbours) for every empty cell. */
        private void initialiseDegrees() {
            for (int r = 0; r < board.length; r++) {
                for (int c = 0; c < board[0].length; c++) {
                    degree[r][c] = countAdjacentEmpties(r, c);
                }
            }
        }

        /** Return how many of the four neighbours are empty ('.'). */
        private int countAdjacentEmpties(int r, int c) {
            if (board[r][c] != '.') return 0;
            int cnt = 0;
            for (Direction d : Direction.values()) {
                int nr = r + d.dr;
                int nc = c + d.dc;
                if (isInside(nr, nc) && board[nr][nc] == '.') cnt++;
            }
            return cnt;
        }

        /** Fill the processing queue with all empty cells that have degree == 1. */
        private void populateQueue() {
            for (int r = 0; r < board.length; r++) {
                for (int c = 0; c < board[0].length; c++) {
                    if (board[r][c] == '.' && degree[r][c] == 1 && !visited[r][c]) {
                        queue.add(new Cell(r, c));
                        visited[r][c] = true;
                    }
                }
            }
        }

        /** Main loop – repeatedly resolve forced moves until the queue empties. */
        private void solve() {
            while (!queue.isEmpty()) {
                Cell cur = queue.poll();
                resolveCell(cur.row, cur.col);
            }
        }

        /** Attempt to place a tile starting from a forced cell (degree == 1). */
        private void resolveCell(int r, int c) {
            // Guard against stale entries (cell already filled or degree changed)
            if (board[r][c] != '.' || degree[r][c] != 1) return;

            Cell neighbour = findUniqueNeighbour(r, c);
            if (neighbour == null) return;               // safety check – should not happen

            // Determine which direction we are pairing in
            Direction dir = Direction.fromDelta(neighbour.row - r, neighbour.col - c);
            placeTile(r, c, neighbour, dir);

            // After placing a tile, the involved cells have degree 0.
            degree[r][c] = degree[neighbour.row][neighbour.col] = 0;

            // Propagate the change to the neighbour’s neighbours – new forced moves may appear
            updateNeighbourhood(neighbour);
        }

        /** Locate the *only* adjacent empty cell of (r,c). Returns {@code null} if none or many. */
        private Cell findUniqueNeighbour(int r, int c) {
            List<Cell> candidates = new ArrayList<>();
            for (Direction d : Direction.values()) {
                int nr = r + d.dr;
                int nc = c + d.dc;
                if (isInside(nr, nc) && board[nr][nc] == '.') {
                    candidates.add(new Cell(nr, nc));
                }
            }
            return candidates.size() == 1 ? candidates.get(0) : null;
        }

        /** Write the appropriate characters to fill a pair of cells. */
        private void placeTile(int r1, int c1, Cell nb, Direction dir) {
            switch (dir) {
                case RIGHT -> {
                    board[r1][c1] = '<';
                    board[nb.row][nb.col] = '>';
                }
                case LEFT -> {
                    board[r1][c1] = '>';
                    board[nb.row][nb.col] = '<';
                }
                case UP -> {
                    board[r1][c1] = '^';
                    board[nb.row][nb.col] = 'v';
                }
                case DOWN -> {
                    board[r1][c1] = 'v';
                    board[nb.row][nb.col] = '^';
                }
            }
        }

        /** Re‑calculate degrees around the given neighbour and enqueue newly forced cells. */
        private void updateNeighbourhood(Cell centre) {
            for (Direction d : Direction.values()) {
                int nr = centre.row + d.dr;
                int nc = centre.col + d.dc;
                if (isInside(nr, nc) && board[nr][nc] == '.' && !visited[nr][nc]) {
                    int newDegree = countAdjacentEmpties(nr, nc);
                    degree[nr][nc] = newDegree;
                    if (newDegree == 1) {
                        queue.add(new Cell(nr, nc));
                        visited[nr][nc] = true;
                    }
                }
            }
        }

        /** Verify that every cell has been filled – this is our simple uniqueness test. */
        private boolean isComplete() {
            for (char[] row : board) {
                for (char cell : row) {
                    if (cell == '.') return false;
                }
            }
            return true;
        }

        /** Produce the solved board as a single string with line breaks. */
        private String printSolution() {
            StringBuilder sb = new StringBuilder();
            for (char[] row : board) {
                sb.append(row).append('\n');
            }
            return sb.toString().trim(); // remove trailing newline
        }

        /** Public query used by {@code solve()} to decide the final output. */
        private boolean isUniqueSolution() {
            return isComplete();
        }

        /** Helper – checks whether a coordinate lies inside the board limits. */
        private boolean isInside(int r, int c) {
            return r >= 0 && r < board.length && c >= 0 && c < board[0].length;
        }
    }

    /**
     * Program entry point.  Mirrors the original `main` signature but delegates
     * all heavy lifting to the {@link Solver} class.
     */
    public static void main(String[] args) throws Exception {
        // Direct use of System.in / System.out as required by the original source.
        String answer = solve(System.in);
        System.out.print(answer);
    }
}

/**
 * Refactored version of the “SolveContest” program.
 *
 * <p>This version focuses on readability, maintainability and robustness:
 * <ul>
 *   <li>Uses meaningful names and generics.</li>
 *   <li>Encapsulates input / output handling with try‑with‑resources.</li>
 *   <li>Replaces magic numbers, strings and raw arrays with constants / enums.</li>
 *   <li>Separates concerns – parsing, core algorithm and I/O are distinct.</li>
 *   <li>Provides javadoc comments for public members.</li>
 * </ul>
 *
 * <p>The algorithm itself remains the same (domino‑tiling via forced moves), but the
 * surrounding code is now cleaner and easier to extend or test.
 */
public final class SolveContest {

    /** Input file name (fallback to {@code System.in} when not found). */
    private static final String INPUT_FILE = "input.txt";

    /** Output file name (fallback to {@code System.out}). */
    private static final String OUTPUT_FILE = "output.txt";

    /** Directions in the order: up, down, left, right. */
    private enum Direction {
        UP(0, -1, '^', 'v'),
        DOWN(1, 0, 'v', '^'),
        LEFT(0, -1, '<', '>'),   // NOTE: dx/dy are reused later – values are swapped accordingly
        RIGHT(0, 1, '>', '<');

        private final int dx;
        private final int dy;
        private final char tileStart; // character that will be placed on the current cell
        private final char tileEnd;   // character that will be placed on the neighbour cell

        Direction(int dx, int dy, char tileStart, char tileEnd) {
            this.dx = dx;
            this.dy = dy;
            this.tileStart = tileStart;
            this.tileEnd = tileEnd;
        }

        int deltaX() { return dx; }
        int deltaY() { return dy; }
        char startChar() { return tileStart; }
        char endChar() { return tileEnd; }
    }

    /** Simple container for a cell coordinate. */
    private static final class Coord {
        final int row;
        final int col;

        Coord(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }

    /** Core solver class – contains the tiling algorithm. */
    private static final class Solver {

        /** Grid stored as char matrix; '.' denotes an empty cell. */
        private char[][] grid;

        /** Current number of rows and columns. */
        private int rows, cols;

        /** Queue of cells that currently have exactly one free neighbour. */
        private final java.util.Queue<Coord> forcedQueue = new java.util.ArrayDeque<>();

        /** Directions used for neighbour checks. */
        private static final int[][] NEIGHBOUR_DELTAS = {
                {1, 0}, {-1, 0}, {0, 1}, {0, -1}
        };

        /** Returns the number of free neighbours of cell (r,c). */
        private int countFreeNeighbours(int r, int c) {
            int cnt = 0;
            for (int[] d : NEIGHBOUR_DELTAS) {
                int nr = r + d[0];
                int nc = c + d[1];
                if (inBounds(nr, nc) && grid[nr][nc] == '.') {
                    cnt++;
                }
            }
            return cnt;
        }

        /** Checks whether (r,c) is a valid coordinate. */
        private boolean inBounds(int r, int c) {
            return 0 <= r && r < rows && 0 <= c && c < cols;
        }

        /**
         * Starts the solving process.
         * Reads input, performs tiling and writes the result.
         */
        void solve(BufferedReader reader, PrintWriter out) throws IOException {
            // ----- 1️⃣  Read dimensions and grid -------------------------------------------------
            String line = reader.readLine();
            String[] dim = line.trim().split("\\s+");
            rows = Integer.parseInt(dim[0]);
            cols = Integer.parseInt(dim[1]);

            grid = new char[rows][cols];
            for (int r = 0; r < rows; r++) {
                String rowString = reader.readLine();
                for (int c = 0; c < cols; c++) {
                    grid[r][c] = rowString.charAt(c);
                }
            }

            // ----- 2️⃣  Find all cells that currently have exactly one free neighbour --------------
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (grid[r][c] == '.' && countFreeNeighbours(r, c) == 1) {
                        forcedQueue.add(new Coord(r, c));
                    }
                }
            }

            // ----- 3️⃣  Process forced moves ---------------------------------------------------
            while (!forcedQueue.isEmpty()) {
                Coord cur = forcedQueue.poll();
                int r = cur.row;
                int c = cur.col;

                // Cell may already have been filled by a previous step.
                if (grid[r][c] != '.') {
                    continue;
                }

                // Determine the unique free neighbour.
                Direction dir = findUniqueDirection(r, c);
                if (dir == null) {
                    // Zero or more than one free neighbour – tiling is not unique.
                    out.println("Not unique");
                    return;
                }

                // Place the two halves of the domino.
                grid[r][c] = dir.startChar();
                Coord neighbour = new Coord(r + dir.deltaX(), c + dir.deltaY());
                grid[neighbour.row][neighbour.col] = dir.endChar();

                // Update neighbour counts for cells adjacent to the newly placed domino.
                for (int i = 0; i < NEIGHBOUR_DELTAS.length; i++) {
                    int nr = neighbour.row + NEIGHBOUR_DELTAS[i][0];
                    int nc = neighbour.col + NEIGHBOUR_DELTAS[i][1];
                    if (inBounds(nr, nc) && grid[nr][nc] == '.') {
                        int freeCnt = countFreeNeighbours(nr, nc);
                        if (freeCnt == 1) {
                            forcedQueue.add(new Coord(nr, nc));
                        }
                    }
                }
            }

            // ----- 4️⃣  Verify that the whole board is filled ---------------------------------
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (grid[r][c] == '.') {
                        out.println("Not unique");
                        return;
                    }
                }
            }

            // ----- 5️⃣  Output the solved board ------------------------------------------------
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    out.print(grid[r][c]);
                }
                out.println();
            }
        }

        /**
         * Returns the unique {@link Direction} that corresponds to the sole empty neighbour of
         * cell (r,c). If there isn’t exactly one, {@code null} is returned.
         */
        private Direction findUniqueDirection(int r, int c) {
            Direction dir = null;
            for (Direction d : Direction.values()) {
                int nr = r + d.deltaX();
                int nc = c + d.deltaY();
                if (inBounds(nr, nc) && grid[nr][nc] == '.') {
                    if (dir != null) {
                        // more than one free neighbour – not uniquely deterministic
                        return null;
                    }
                    dir = d;
                }
            }
            return dir;
        }
    }

    /** Program entry‑point. */
    public static void main(String[] args) {
        SolveContest solver = new SolveContest();
        solver.run();
    }

    /** Orchestrates input handling, solving and graceful fallback to console I/O. */
    private void run() {
        BufferedReader reader;
        PrintWriter out;

        // Try to open the designated input file; fall back to stdin on any problem.
        try {
            reader = new BufferedReader(new FileReader(INPUT_FILE));
            out = new PrintWriter(new FileWriter(OUTPUT_FILE, false), true);
        } catch (Exception e) {
            // Close any partially‑opened streams to avoid resource leaks.
            try { if (reader != null) reader.close(); } catch (Exception ignored) {}
            try { if (out != null) out.close(); } catch (Exception ignored) {}

            reader = new BufferedReader(new InputStreamReader(System.in));
            out = new PrintWriter(System.out, true);
        }

        try {
            new Solver().solve(reader, out);
        } finally {
            // Ensure resources are closed even if an exception occurs.
            try { if (reader != null) reader.close(); } catch (Exception ignored) {}
            if (out != null) out.close();
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Domino tiling uniqueness checker.
 *
 * The program reads a rectangular grid that consists of '.' (free cells) and
 * any other characters (blocked cells).  Using a forced‑move algorithm it
 * determines whether there is a **unique** way to cover all free cells with
 * 2×1 dominoes.  If a unique tiling exists, the board is printed using the
 * symbols '<', '>', '^', 'v' to indicate the orientation of each domino.
 * Otherwise the program prints "Not unique".
 *
 * The implementation has been refactored to improve readability,
 * maintainability and separation of concerns while preserving the original
 * behaviour.
 */
public class Main {

    /* ---------------------------------------------------------------------- */
    /*  Constants & tiny helper classes                                         */
    /* ---------------------------------------------------------------------- */
    /** Simple 2‑direction representation used for neighbour walks. */
    private static final class Directions {
        private static final int[] DR = {0, -1, 0, 1};
        private static final int[] DC = {-1, 0, 1, 0};

        static boolean valid(int r, int c, int rows, int cols) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }
    }

    /** One coordinate pair. */
    private static final class Cell {
        final int row;
        final int col;
        Cell(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }

    /** One domino – two adjacent cells that have been paired. */
    private static final class Domino {
        final Cell first;
        final Cell second;
        Domino(Cell first, Cell second) {
            this.first = first;
            this.second = second;
        }
    }

    /* ---------------------------------------------------------------------- */
    /*  Input / output handling                                                   */
    /* ---------------------------------------------------------------------- */
    private final boolean useFileIo;
    private BufferedReader bufferedIn;
    private PrintWriter bufferedOut;
    private StringTokenizer tokenizer;

    /** Entry point – creates a solver and runs it. */
    public static void main(String[] args) throws Exception {
        new Main(false).run();
    }

    /** Lifecycle method – initialise streams, solve, and shut down cleanly. */
    private void run() throws Exception {
        initIo();
        solve();
        closeResources();
    }

    /** Sets up the appropriate {@link BufferedReader}/{@link PrintWriter}
     * based on the {@code useFileIo} flag. */
    private void initIo() throws IOException {
        if (!useFileIo) {
            bufferedIn = new BufferedReader(new InputStreamReader(System.in));
            bufferedOut = new PrintWriter(System.out);
            tokenizer = new StringTokenizer("");
        } else {
            bufferedIn = new BufferedReader(new FileReader("input.txt"));
            bufferedOut = new PrintWriter("output.txt");
            tokenizer = new StringTokenizer("");
        }
    }

    /** Closes all opened streams. */
    private void closeResources() {
        try { bufferedIn.close(); } catch (Exception ignored) {}
        try { tokenizer.close(); } catch (Exception ignored) {}
        try { bufferedOut.close(); } catch (Exception ignored) {}
    }

    /** Small token utilities used throughout the solver. */
    private String nextToken(String delimiter) throws IOException {
        if (!tokenizer.hasMoreTokens()) {
            tokenizer = new StringTokenizer(bufferedIn.readLine());
        }
        return tokenizer.nextToken(delimiter);
    }

    private String readLine() throws IOException {
        return bufferedIn.readLine();
    }

    private int nextInt() throws IOException {
        return Integer.parseInt(nextToken());
    }

    /** Reads the whole grid after the size header. */
    private char[][] readGrid(int rows) throws IOException {
        char[][] grid = new char[rows];
        for (int i = 0; i < rows; i++) {
            grid[i] = readLine().toCharArray();
        }
        return grid;
    }

    /* ---------------------------------------------------------------------- */
    /*  Solving logic                                                          */
    /* ---------------------------------------------------------------------- */
    /** Orchestrates the whole solving procedure. */
    private void solve() throws IOException {
        int n = nextInt();                     // rows
        int m = nextInt();                     // columns

        char[][] rawGrid = readGrid(n);
        Board board = new Board(rawGrid);

        List<Domino> dominoes = board.findUniqueTiling();

        if (dominoes == null) {
            bufferedOut.println("Not unique");
            return;
        }

        board.applyDominoes(dominoes);
        board.printTo(bufferedOut);
    }

    /* ---------------------------------------------------------------------- */
    /*  Core board implementation                                                */
    /* ---------------------------------------------------------------------- */
    /**
     * Encapsulates all board‑specific logic:
     * <ul>
     *   <li>computes degrees of freedom (how many free neighbours a cell has)</li>
     *   <li>searches for forced moves (degree == 1)</li>
     *   <li>collects a matching if it is unique</li>
     *   <li>applies the matching to the visual representation</li>
     * </ul>
     */
    private static final class Board {
        private char[][] grid;                 // mutable view of the board
        private final int rows;
        private final int cols;
        private final boolean[][] used;        // has the cell already been matched?
        private final boolean[][] inQueue;     // is the cell currently queued?
        private final Queue<Cell> queue = new ArrayDeque<>();

        /** Directions used for neighbour checks – kept as an array for simplicity. */
        private final int[][] dirs = {
                {0, -1}, { -1, 0 }, {0, 1 }, { 1, 0}
        };

        Board(char[][] grid) {
            this.grid = grid;
            this.rows = grid.length;
            this.cols = grid[0].length;
            this.used = new boolean[rows][cols];
            this.inQueue = new boolean[rows][cols];
        }

        /** Helper – reset the mutable reference after the board has been created. */
        void setGrid(char[][] grid) {
            this.grid = grid;
        }

        /**
         * Tries to build a *unique* tiling of all '.' cells with dominoes.
         *
         * @return a list of {@link Domino} objects if a unique tiling exists,
         *         otherwise {@code null}.
         */
        List<Domino> findUniqueTiling() {
            List<Domino> result = new ArrayList<>();

            /* --------------------------------------------------------------
             *  1️⃣  Initialise the queue with every cell that has exactly one
             *      free neighbour (degree == 1). Those are the only cells that
             *      can be placed unambiguously at this point.
             * -------------------------------------------------------------- */
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (grid[r][c] == '.' && degree(r, c) == 1 && !used[r][c]) {
                        queue.add(new Cell(r, c));
                        inQueue[r][c] = true;
                    }
                }
            }

            /* --------------------------------------------------------------
             *  2️⃣  Process the queue until it is empty or a contradiction is
             *      discovered.  Each iteration handles a forced placement.
             * -------------------------------------------------------------- */
            while (!queue.isEmpty()) {
                Cell cur = queue.poll();
                if (used[cur.row][cur.col]) {
                    continue;                       // already consumed by a previous step
                }
                used[cur.row][cur.col] = true;      // mark as taken

                Cell partner = findOnlyFreeNeighbour(cur.row, cur.col);
                if (partner == null) {
                    return null;                    // dead end → not unique
                }
                used[partner.row][partner.col] = true;
                result.add(new Domino(cur, partner));

                /* ----------------------------------------------------------
                 *  3️⃣  Re‑evaluate neighbours of both cells – a neighbour may
                 *      have become degree‑1 because one of its free neighbours
                 *      just got matched, so it now belongs to the queue.
                 * ---------------------------------------------------------- */
                for (Cell cell : List.of(cur, partner)) {
                    for (int d = 0; d < 4; d++) {
                        int nr = cell.row + dirs[d][0];
                        int nc = cell.col + dirs[d][1];
                        if (Directions.valid(nr, nc, rows, cols)
                                && grid[nr][nc] == '.'
                                && !used[nr][nc]
                                && !inQueue[nr][nc]) {
                            if (degree(nr, nc) == 1) {
                                queue.add(new Cell(nr, nc));
                                inQueue[nr][nc] = true;
                            }
                        }
                    }
                }
            }

            /* --------------------------------------------------------------
             *  4️⃣  After processing everything we must have matched *every*
             *      free cell.  If any '.' remains uncovered the tiling is not
             *      unique (or impossible).
             * -------------------------------------------------------------- */
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (grid[r][c] == '.' && !used[r][c]) {
                        return null;
                    }
                }
            }
            return result;
        }

        /** Returns how many adjacent '.' cells are still free (degree). */
        private int degree(int r, int c) {
            int cnt = 0;
            for (int[] d : dirs) {
                int nr = r + d[0];
                int nc = c + d[1];
                if (Directions.valid(nr, nc, rows, cols)
                        && grid[nr][nc] == '.'
                        && !used[nr][nc]) {
                    cnt++;
                }
            }
            return cnt;
        }

        /**
         * Finds the *unique* free neighbour of (r,c).  Returns {@code null}
         * if there is zero or more than one such neighbour.
         */
        private Cell findOnlyFreeNeighbour(int r, int c) {
            Cell partner = null;
            for (int[] d : dirs) {
                int nr = r + d[0];
                int nc = c + d[1];
                if (Directions.valid(nr, nc, rows, cols)
                        && grid[nr][nc] == '.'
                        && !used[nr][nc]) {
                    if (partner != null) {          // more than one → not forced
                        return null;
                    }
                    partner = new Cell(nr, nc);
                }
            }
            return partner;
        }

        /** Places the appropriate arrow symbols on the board for each domino. */
        void applyDominoes(List<Domino> dominoes) {
            for (Domino d : dominoes) {
                Cell a = d.first;
                Cell b = d.second;
                if (a.row == b.row) {                 // horizontal domino
                    if (a.col < b.col) {
                        grid[a.row][a.col] = '<';
                        grid[b.row][b.col] = '>';
                    } else {
                        grid[a.row][a.col] = '>';
                        grid[b.row][b.col] = '<';
                    }
                } else {                               // vertical domino
                    if (a.row < b.row) {
                        grid[a.row][a.col] = '^';
                        grid[b.row][b.col] = 'v';
                    } else {
                        grid[a.row][a.col] = 'v';
                        grid[b.row][b.col] = '^';
                    }
                }
            }
        }

        /** Serialises the solved board to the supplied {@link PrintWriter}. */
        void printTo(PrintWriter out) {
            for (char[] row : grid) {
                for (char ch : row) {
                    out.print(ch);
                }
                out.println();
            }
        }
    }
}

import java.io.PrintWriter;
import java.util.ArrayDeque;
import java.util.Deque;
import java.util.Scanner;

/**
 * Entry point of the application.
 * Reads the board, solves the tiling problem and prints the result.
 */
public class Main {

    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in);
             PrintWriter out = new PrintWriter(System.out)) {
            new GridSolver().solve(scanner, out);
        }
    }
}

/**
 * Represents a coordinate in the grid.
 */
final class Coord {
    final int row;
    final int col;

    Coord(int row, int col) {
        this.row = row;
        this.col = col;
    }
}

/**
 * Core logic that attempts to uniquely tile the board with dominoes.
 * If the tiling is unique the solved board is printed, otherwise
 * the string "Not unique" is printed.
 */
final class GridSolver {

    // Directions: right, left, up, down
    private static final int[] DR = {0, 0, -1, 1};
    private static final int[] DC = {1, -1, 0, 0};

    private char[][] board;   // original board read from input
    private int rows, cols;    // board dimensions
    private int[][] degree;    // number of adjacent empty cells for each cell
    private final Deque<Coord> queue = new ArrayDeque<>();

    /** Reads the board, initialises auxiliary structures and starts the solving process. */
    void solve(Scanner in, PrintWriter out) {
        readInput(in);
        if (!initQueue()) {
            out.print("Not unique");
            return;
        }

        if (!processQueue(out)) {
            return; // "Not unique" already printed inside processQueue
        }

        outputSolution(out);
    }

    /** Reads dimensions and the board from the scanner. */
    private void readInput(Scanner in) {
        rows = in.nextInt();
        cols = in.nextInt();
        board = new char[rows][];
        for (int r = 0; r < rows; r++) {
            board[r] = in.next().toCharArray();
        }
    }

    /** Calculates the degree of each empty cell and fills the initial queue. */
    private boolean initQueue() {
        degree = new int[rows][cols];
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (board[r][c] == '.') {
                    int cnt = 0;
                    for (int d = 0; d < 4; d++) {
                        int nr = r + DR[d];
                        int nc = c + DC[d];
                        if (isInside(nr, nc) && board[nr][nc] == '.') {
                            cnt++;
                        }
                    }
                    degree[r][c] = cnt;
                    if (cnt == 1) {
                        queue.addLast(new Coord(r, c));
                    }
                }
            }
        }
        return !queue.isEmpty(); // if no forced start exists the solution cannot be unique
    }

    /** Executes the propagation algorithm using the queue of forced cells. */
    private boolean processQueue(PrintWriter out) {
        while (!queue.isEmpty()) {
            Coord cur = queue.removeFirst();

            // If a cell that was forced to be placed lost its only neighbour – not unique
            if (degree[cur.row][cur.col] == 0) {
                out.print("Not unique");
                return false;
            }

            // Find the only adjacent empty cell that is still free
            Coord neighbour = null;
            int direction = -1;
            outer:
            for (int d = 0; d < 4; d++) {
                int nr = cur.row + DR[d];
                int nc = cur.col + DC[d];
                if (isInside(nr, nc) && board[nr][nc] == '.') {
                    neighbour = new Coord(nr, nc);
                    direction = d;
                    break outer;
                }
            }
            if (neighbour == null) {
                out.print("Not unique");
                return false;
            }

            // Place the domino according to the discovered direction
            char left, right;
            switch (direction) {
                case 0 -> { left = '<'; right = '>'; } // cur -> right neighbour
                case 1 -> { left = '>'; right = '<'; } // cur -> left neighbour
                case 2 -> { left = 'v'; right = '^'; } // cur -> upper neighbour
                case 3 -> { left = '^'; right = 'v'; } // cur -> lower neighbour
                default -> throw new IllegalStateException();
            }
            board[cur.row][cur.col] = left;
            board[neighbour.row][neighbour.col] = right;

            // Decrease degree of the newly placed cells and propagate changes
            reduceDegree(neighbour.row, neighbour.col);
        }
        return true;
    }

    /** Decrements the degree of a cell and enqueues it when it becomes forced (degree == 1). */
    private void reduceDegree(int r, int c) {
        if (--degree[r][c] == 1) {
            queue.addLast(new Coord(r, c));
        }
        // Update neighbours of the processed cell – their degrees may drop as well
        for (int d = 0; d < 4; d++) {
            int nr = r + DR[d];
            int nc = c + DC[d];
            if (isInside(nr, nc) && board[nr][nc] == '.') {
                reduceDegree(nr, nc);
            }
        }
    }

    /** Prints the solved board if it is completely tiled, otherwise prints "Not unique". */
    private void outputSolution(PrintWriter out) {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (board[r][c] == '.') {
                    out.print("Not unique");
                    return;
                }
            }
        }
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                out.print(board[r][c]);
            }
            out.println();
        }
    }

    /** Helper that checks whether a coordinate lies inside the board. */
    private boolean isInside(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }
}

/**
 * Domino Solver – refactored for readability, maintainability and extensibility.
 *
 * The original program reads an N×M board made of '.' , '*', and attempts to fill every
 * empty cell with a domino orientation marker ('<', '>', '^', 'v').  It uses an
 * iterative “forced‑move” algorithm: whenever a free cell has exactly three free
 * neighbours, the fourth neighbour must be its partner and the two cells are
 * paired immediately.  After processing all forced moves the solver checks
 * whether the whole board became filled; if any '.' remains the solution is not
 * unique and the program prints “Not unique”.
 *
 * The refactored version separates concerns into small, well‑named methods,
 * uses constants instead of magic numbers, employs a tiny `Pair` helper for
 * queue elements, and follows Java naming conventions.
 */
public class DominoSolver {

    /** Directions: right, left, down, up */
    private static final int[] DX = {0, 0, 1, -1};
    private static final int[] DY = {1, -1, 0, 0};

    /** Grid contains the board characters. */
    private char[][] board;

    /** Queue of cells that need to be examined (stored as i‑j pairs). */
    private final java.util.ArrayDeque<Pair> queue = new java.util.ArrayDeque<>();

    /** Number of rows and columns of the board. */
    private int rows, cols;

    /** Simple container for a coordinate pair. */
    private static final class Pair {
        final int i;
        final int j;

        Pair(int i, int j) {
            this.i = i;
            this.j = j;
        }
    }

    /** --------------------------------------------------------------------- *
     *  Entry point
     *  --------------------------------------------------------------------- */
    public static void main(String[] args) {
        new DominoSolver().solve();
    }

    /** --------------------------------------------------------------------- *
     *  Main solver routine
     *  --------------------------------------------------------------------- */
    private void solve() {
        readInput();
        initialiseQueueWithEmptyCells();
        processQueue();
        outputResult();
    }

    /** --------------------------------------------------------------------- *
     *  Read board dimensions and the board itself.
     *  --------------------------------------------------------------------- */
    private void readInput() {
        try (java.util.Scanner scanner = new java.util.Scanner(System.in)) {
            rows = scanner.nextInt();
            cols = scanner.nextInt();
            board = new char[rows][cols];
            for (int i = 0; i < rows; i++) {
                board[i] = scanner.next().toCharArray();
            }
        }
    }

    /** --------------------------------------------------------------------- *
     *  Put every empty ('.') cell into the queue for later processing.
     *  --------------------------------------------------------------------- */
    private void initialiseQueueWithEmptyCells() {
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (board[i][j] == '.') {
                    checkCell(i, j);
                }
            }
        }
    }

    /** --------------------------------------------------------------------- *
     *  Examine a cell; if it has exactly three free neighbours, add the forced
     *  pair to the queue.
     *  --------------------------------------------------------------------- */
    private void checkCell(int i, int j) {
        int freeNeighbours = 0;
        int partnerI = -1, partnerJ = -1;

        for (int d = 0; d < 4; d++) {
            int ni = i + DX[d];
            int nj = j + DY[d];
            if (!isSolid(ni, nj)) {
                freeNeighbours++;
                partnerI = ni;
                partnerJ = nj;
            }
        }

        if (freeNeighbours == 3) {
            queue.add(new Pair(i, j));
            queue.add(new Pair(partnerI, partnerJ));
        }
    }

    /** --------------------------------------------------------------------- *
     *  Pop a pair from the queue and, if both cells are still empty, lock them
     *  into a domino and re‑evaluate their neighbours.
     *  --------------------------------------------------------------------- */
    private void processQueue() {
        while (!queue.isEmpty()) {
            int i = queue.removeFirst().i;
            int j = queue.removeFirst().j;
            int ni = queue.removeFirst().i;
            int nj = queue.removeFirst().j;

            if (board[i][j] != '.' || board[ni][nj] != '.') {
                continue; // already processed or blocked
            }

            placeDomino(i, j, ni, nj);
            enqueueNeighbourChecks(i, j);
            enqueueNeighbourChecks(ni, nj);
        }
    }

    /** --------------------------------------------------------------------- *
     *  Mark a pair of cells with the appropriate orientation symbols.
     *  --------------------------------------------------------------------- */
    private void placeDomino(int i1, int j1, int i2, int j2) {
        if (i1 == i2) {                     // horizontal
            board[i1][j1] = (j2 > j1) ? '<' : '>';
            board[i2][j2] = (j2 > j1) ? '>' : '<';
        } else {                            // vertical
            board[i1][j1] = (i2 > i1) ? '^' : 'v';
            board[i2][j2] = (i2 > i1) ? 'v' : '^';
        }
    }

    /** --------------------------------------------------------------------- *
     *  Re‑evaluate the four neighbours of (i, j); if any becomes forced,
     *  enqueue the necessary pair.
     *  --------------------------------------------------------------------- */
    private void enqueueNeighbourChecks(int i, int j) {
        for (int d = 0; d < 4; d++) {
            int ni = i + DX[d];
            int nj = j + DY[d];
            if (!isSolid(ni, nj)) {
                checkCell(ni, nj);
            }
        }
    }

    /** --------------------------------------------------------------------- *
     *  Helper: a cell is solid if it is outside the board or not an empty '.'.
     *  --------------------------------------------------------------------- */
    private boolean isSolid(int i, int j) {
        return i < 0 || j < 0 || i >= rows || j >= cols || board[i][j] != '.';
    }

    /** --------------------------------------------------------------------- *
     *  After the forced‑move phase, verify whether the whole board is covered.
     *  Print the solved board or “Not unique”.
     *  --------------------------------------------------------------------- */
    private void outputResult() {
        boolean fullyCovered = true;
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (board[i][j] == '.') {
                    fullyCovered = false;
                    break;
                }
            }
            if (!fullyCovered) {
                break;
            }
        }

        if (fullyCovered) {
            for (char[] row : board) {
                System.out.println(new String(row));
            }
        } else {
            System.out.println("Not unique");
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Solution for the “Domino” problem (Task D).
 *
 * The program reads a rectangular board that contains:
 *   '.' – empty cell
 *   '*' – blocked cell
 *
 * It has to place dominoes so that every empty cell belongs to exactly one domino.
 * The solution must be unique; otherwise the answer is printed as “Not unique”.
 *
 * The implementation is deliberately split into small, well‑named pieces to
 * maximise readability and maintainability.
 */
public class Main {

    /** Entry point – delegates work to {@link Solver}. */
    public static void main(String[] args) {
        InputStream input = System.in;
        OutputStream output = System.out;

        InputReader in = new InputReader(input);
        OutputWriter out = new OutputWriter(output);

        Solver solver = new Solver();
        solver.solve(in, out);
        out.close();
    }
}

