/* -------------------------------------------------------------------------- */

/**
 * Core algorithm that places dominoes on the board.
 *
 * <p>It works by repeatedly finding cells that have exactly one free neighbour,
 * fixing the corresponding domino, and propagating the consequences.
 *
 * <p>All public methods are deliberately small and focused, making unit‑testing
 * straightforward.
 */
final class Solver {

    /** Directions used while scanning neighbours. */
    private enum Direction {
        UP(-1, 0),
        DOWN(1, 0),
        LEFT(0, -1),
        RIGHT(0, 1);

        private final int dr;
        private final int dc;

        Direction(int dr, int dc) {
            this.dr = dr;
            this.dc = dc;
        }

        int[] delta() {
            return new int[]{dr, dc};
        }
    }

    /** Simple immutable pair of coordinates. */
    private static final class Coord {
        final int row;
        final int col;

        Coord(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }

    /** ---------------------------------------------------------------------- */
    /** Public entry point used by {@code Main}. */
    public void solve(InputReader in, OutputWriter out) {
        int rows = in.nextInt();
        int cols = in.nextInt();

        char[][] board = readBoard(in, rows, cols);
        List<Coord> pending = collectInitiallyDetermined(board, rows, cols);

        while (!pending.isEmpty()) {
            Coord cur = pending.remove(pending.size() - 1);
            // The cell might already have been filled by a previous placement.
            if (board[cur.row][cur.col] != '.') {
                continue;
            }

            Coord partner = findFreeNeighbour(board, rows, cols, cur);
            if (partner == null) {
                // No partner → the board cannot be completely tiled.
                out.printLine("Not unique");
                return;
            }

            placeDomino(board, cur, partner);
            pending.addAll(discoverNextCandidates(board, rows, cols, partner));
        }

        if (isBoardComplete(board, rows, cols)) {
            out.printBoard(board);
        } else {
            out.printLine("Not unique");
        }
    }

    /* ---------------------------------------------------------------------- */
    /** Reads the board from {@link InputReader}. */
    private static char[][] readBoard(InputReader in, int n, int m) {
        char[][] board = new char[n][];
        for (int i = 0; i < n; ++i) {
            board[i] = in.next().toCharArray();
        }
        return board;
    }

    /** Returns a list of cells that initially have exactly one free neighbour. */
    private static List<Coord> collectInitiallyDetermined(char[][] board, int n, int m) {
        List<Coord> result = new ArrayList<>();
        for (int r = 0; r < n; ++r) {
            for (int c = 0; c < m; ++c) {
                if (board[r][c] == '.' && hasExactlyOneFreeNeighbour(board, n, m, r, c)) {
                    result.add(new Coord(r, c));
                }
            }
        }
        return result;
    }

    /** Places a domino covering {@code a} and {@code b} on the board. */
    private static void placeDomino(char[][] board, Coord a, Coord b) {
        char first, second;
        if (a.row == b.row) {                     // horizontal
            first = a.col < b.col ? '<' : '>';
            second = first == '<' ? '>' : '<';
        } else {                                   // vertical
            first = a.row < b.row ? '^' : 'v';
            second = first == '^' ? 'v' : '^';
        }

        board[a.row][a.col] = first;
        board[b.row][b.col] = second;
    }

    /** Returns a neighbour of {@code cell} that is still empty ('.'). */
    private static Coord findFreeNeighbour(char[][] board, int n, int m, Coord cell) {
        for (Direction dir : Direction.values()) {
            int nr = cell.row + dir.delta()[0];
            int nc = cell.col + dir.delta()[1];
            if (inside(nr, nc, n, m) && board[nr][nc] == '.') {
                return new Coord(nr, nc);
            }
        }
        return null;
    }

    /** Returns all cells that become “forced” after placing the domino around {@code start}. */
    private static List<Coord> discoverNextCandidates(char[][] board, int n, int m, Coord start) {
        List<Coord> next = new ArrayList<>();
        for (Direction dir : Direction.values()) {
            int nr = start.row + dir.delta()[0];
            int nc = start.col + dir.delta()[1];
            if (inside(nr, nc, n, m) && board[nr][nc] == '.' && hasExactlyOneFreeNeighbour(board, n, m, nr, nc)) {
                next.add(new Coord(nr, nc));
            }
        }
        return next;
    }

    /** Checks whether every empty cell has been filled. */
    private static boolean isBoardComplete(char[][] board, int n, int m) {
        for (char[] row : board) {
            for (char cell : row) {
                if (cell == '.') {
                    return false;
                }
            }
        }
        return true;
    }

    /* ---------------------------------------------------------------------- */
    /** Returns true if the cell at (r,c) has exactly one adjacent free neighbour. */
    private static boolean hasExactlyOneFreeNeighbour(char[][] board, int n, int m, int r, int c) {
        if (!inside(r, c, n, m) || board[r][c] != '.') {
            return false;
        }
        int freeCount = 0;
        Coord nearest = null;
        for (Direction dir : Direction.values()) {
            int nr = r + dir.delta()[0];
            int nc = c + dir.delta()[1];
            if (inside(nr, nc, n, m) && board[nr][nc] == '.') {
                ++freeCount;
                nearest = new Coord(nr, nc);
            }
        }
        // The neighbour itself must also have exactly one free neighbour – this is only
        // needed for the propagation step; for the initial collection we just need the count.
        return freeCount == 1;
    }

    /** Simple bounds check. */
    private static boolean inside(int r, int c, int n, int m) {
        return r >= 0 && r < n && c >= 0 && c < m;
    }
}

