/** Minimal buffered input reader. */
final class InputReader {
    private final BufferedReader reader;
    private StringTokenizer tokenizer;

    InputReader(InputStream stream) {
        reader = new BufferedReader(new InputStreamReader(stream), 32768);
        tokenizer = null;
    }

    String next() {
        while (tokenizer == null || !tokenizer.hasMoreTokens()) {
            try {
                tokenizer = new StringTokenizer(reader.readLine());
            } catch (IOException e) {
                throw new RuntimeException(e);
            }
        }
        return tokenizer.nextToken();
    }

    boolean hasNext() {
        while (tokenizer == null || !tokenizer.hasMoreTokens()) {
            try {
                String line = reader.readLine();
                if (line == null) {
                    return false;
                }
                tokenizer = new StringTokenizer(line);
            } catch (IOException e) {
                throw new RuntimeException(e);
            }
        }
        return true;
    }

    int nextInt() {
        return Integer.parseInt(next());
    }
}

/** Minimal buffered output writer. */
final class OutputWriter {
    private final PrintWriter writer;

    OutputWriter(OutputStream outputStream) {
        writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(outputStream)));
    }

    /** Prints the supplied objects separated by a single space. */
    void print(Object... objects) {
        for (int i = 0; i < objects.length; ++i) {
            if (i != 0) {
                writer.print(' ');
            }
            writer.print(objects[i]);
        }
    }

    /** Prints the supplied objects followed by a line break. */
    void printLine(Object... objects) {
        print(objects);
        writer.println();
    }

    /** Flushes and closes the underlying stream. */
    void close() {
        writer.close();
    }

    /** Writes the whole board to the output stream. */
    void printBoard(char[][] board) {
        for (char[] row : board) {
            for (char cell : row) {
                writer.print(cell);
            }
            writer.println();
        }
    }
}

/*
 *  Domino tiling solver – refactored for maintainability and readability.
 *
 *  The algorithm is identical to the original implementation:
 *   • read the grid,
 *   • repeatedly pick a free cell with exactly one free neighbour,
 *   • place a domino (using the four predefined patterns),
 *   • propagate newly created degree‑1 cells,
 *   • finally verify that the whole board is filled.
 *   • if any cell remains empty → output "Not unique",
 *   • otherwise output the tiled board.
 *
 *  Refactoring highlights:
 *   – Separate concerns (input, output, algorithm).
 *   – Meaningful class / method names.
 *   – Eliminate duplicated imports and unused fields.
 *   – Use final where appropriate and reduce mutable state.
 *   – Extract small helper methods to keep `solve()` concise.
 *   – Add brief Javadoc comments.
 */

import java.io.*;
