/**
 * Reads integers, characters and whole lines from an {@link InputStream}
 * using a fast byte‑buffer technique.
 */
final class InputReader {

    private final InputStream stream;
    private final byte[] buffer = new byte[16_384];
    private int bytesInBuffer = 0;
    private int currentByteOffset = 0;

    InputReader(InputStream stream) {
        this.stream = stream;
    }

    /** Reads the next unsigned byte, -1 on EOF. */
    private int readByte() {
        if (bytesInBuffer == -1) {
            return -1;
        }
        if (currentByteOffset >= bytesInBuffer) {
            currentByteOffset = 0;
            bytesInBuffer = stream.read(buffer);
        }
        return bytesInBuffer <= 0 ? -1 : buffer[currentByteOffset++];
    }

    /** Skips whitespace according to the current {@link #filter}. */
    private int skipWhite() {
        int c;
        do {
            c = readByte();
        } while (c != -1 && isWhitespace(c));
        return c;
    }

    /** Reads the next integer (supports negative numbers). */
    int readInt() {
        int c = skipWhite();
        int sign = 1;
        if (c == '-') {
            sign = -1;
            c = readByte();
        }
        long result = 0;
        while (c >= '0' && c <= '9') {
            result = result * 10 + (c - '0');
            c = readByte();
        }
        return (int) (result * sign);
    }

    /** Reads the next non‑whitespace character. */
    char readChar() {
        int c = skipWhite();
        return (char) c;
    }

    /** Checks whether a character is whitespace according to the current filter. */
    boolean isWhitespace(int c) {
        return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
    }
}

/**
 * Writes formatted output to a {@link Writer} (wrapped {@link OutputStream}).
