    }

    /** Closes the underlying stream. */
    void close() {
        writer.close();
    }
}

/**
 * Immutable coordinate used throughout the algorithm.
 */
final class Coordinate implements Comparable<Coordinate> {
    final int row;
    final int col;

    private Coordinate(int row, int col) {
        this.row = row;
        this.col = col;
    }

    static Coordinate of(int row, int col) {
        return new Coordinate(row, col);
    }

    /** Equality based on row & column. */
    @Override
    public boolean equals(Object o) {
        if (this == o) {
            return true;
        }
        if (o == null || getClass() != o.getClass()) {
            return false;
        }
        Coordinate that = (Coordinate) o;
        return row == that.row && col == that.col;
    }

    @Override
    public int hashCode() {
        return 31 * row + col;
    }

    /** Natural ordering: first by row, then by column. */
    @Override
    public int compareTo(Coordinate o) {
        int cmp = Integer.compare(this.row, o.row);
        return (cmp != 0) ? cmp : Integer.compare(this.col, o.col);
    }

    @Override
    public String toString() {
        return "(" + row + "," + col + ")";
    }
}

/**
 * Core algorithm – tiles the board with dominoes using the four predefined
 * patterns and checks for uniqueness of the tiling.
 *
 * <p>Only the algorithmic behaviour is encapsulated here; all I/O work is
 * delegated to {@link InputReader} and {@link OutputWriter}.
 */
final class DominoSolver {

    /** Four domino patterns (two‑character strings) for the four directions. */
    private static final String[] PATTERNS = {
            "v^", "<>", "^v", "><"
    };

    /** Symbol representing an empty cell. */
    private static final char EMPTY = '.';

    /** Movement offsets for the four cardinal directions. */
    private final int[] dr = {-1, 0, 1, 0};
    private final int[] dc = {0, 1, 0, -1};

    private final char[][] board;
    private final boolean[][] visited; // tracks cells already assigned a domino

    /** Queue of cells that currently have exactly one free neighbour. */
    private final Queue<Coordinate> queue = new ArrayDeque<>();

    DominoSolver() {
        // placeholder – board dimensions are read later
        this.board = new char[0][];
        this.visited = new boolean[0][];
    }

    /**
     * Executes the solver.
     *
     * @param in  reader that provides the input data
     * @param out writer that produces the output
     */
    void solve(InputReader in, OutputWriter out) {
        int rows = in.readInt();
        int cols = in.readInt();
        board = new char[rows][cols];
        visited = new boolean[rows][cols];

        for (int r = 0; r < rows; ++r) {
            for (int c = 0; c < cols; ++c) {
                board[r][c] = in.readChar();
            }
        }

        initializeQueue(rows, cols);
        processQueue();

        if (containsFreeCell()) {
            out.print("Not unique");
            return;
        }

        printSolution(out);
    }

    /** Fills the queue with every empty cell that currently has degree == 1. */
    private void initializeQueue(int rows, int cols) {
        for (int r = 0; r < rows; ++r) {
            for (int c = 0; c < cols; ++c) {
                if (board[r][c] == EMPTY && degree(r, c) == 1) {
                    queue.add(Coordinate.of(r, c));
                }
            }
        }
    }

    /** Main loop – repeatedly place dominoes and extend the queue. */
    private void processQueue() {
        while (!queue.isEmpty()) {
            Coordinate cur = queue.poll();
            int r = cur.row, c = cur.col;

            if (!isFree(r, c)) {
                continue; // cell already filled by a previous placement
            }

            // Find the unique free neighbour that determines the domino direction
            int dir = findUniqueDirection(r, c);
            if (dir == -1) {
                continue; // should not happen in a well‑formed queue entry
            }

            placeDomino(r, c, dir);
            propagateNewDegreeOneCells(r, c, dir);
        }
    }

    /** Returns the direction index (0‑3) of the unique free neighbour, or -1 if none. */
    private int findUniqueDirection(int r, int c) {
        int freeCount = 0;
        int dir = -1;
        for (int d = 0; d < 4; ++d) {
            int nr = r + dr[d];
            int nc = c + dc[d];
            if (inside(nr, nc) && isFree(nr, nc)) {
                ++freeCount;
                dir = d;
            }
        }
        return (freeCount == 1) ? dir : -1;
    }

    /** Places the domino pattern into the board according to the given direction. */
    private void placeDomino(int r, int c, int dir) {
        String pattern = PATTERNS[dir];
        board[r][c] = pattern.charAt(0);
        board[r + dr[dir]][c + dc[dir]] = pattern.charAt(1);
        visited[r][c] = true;
        visited[r + dr[dir]][c + dc[dir]] = true;
    }

    /** Checks neighbour cells around the placed domino and enqueues newly degree‑1 cells. */
    private void propagateNewDegreeOneCells(int r, int c, int dir) {
        for (int t = 0; t < 2; ++t) {
            int baseRow = (t == 0) ? r : r + dr[dir];
            int baseCol = (t == 0) ? c : c + dc[dir];
            for (int d = 0; d < 4; ++d) {
                int nr = baseRow + dr[d];
                int nc = baseCol + dc[d];
                if (inside(nr, nc) && isFree(nr, nc) && degree(nr, nc) == 1) {
                    queue.add(Coordinate.of(nr, nc));
                }
            }
        }
    }

    /** Returns true if the cell is still empty (EMPTY) and not visited. */
    private boolean isFree(int r, int c) {
        return inside(r, c) && board[r][c] == EMPTY && !visited[r][c];
    }

    /** Simple boundary check. */
    private boolean inside(int r, int c) {
        return r >= 0 && r < board.length && c >= 0 && c < board[0].length;
    }

    /** Counts how many orthogonal neighbours of (r,c) are still empty. */
    private int degree(int r, int c) {
        int cnt = 0;
        for (int d = 0; d < 4; ++d) {
            if (inside(r + dr[d], c + dc[d]) && board[r + dr[d]][c + dc[d]] == EMPTY) {
                ++cnt;
            }
        }
        return cnt;
    }

    /** Returns true if any cell remains empty after processing. */
    private boolean containsFreeCell() {
        for (char[] row : board) {
            for (char cell : row) {
                if (cell == EMPTY) {
                    return true;
                }
            }
        }
        return false;
    }

    /** Outputs the fully tiled board. */
    private void printSolution(OutputWriter out) {
        for (char[] row : board) {
            out.println(row);
        }
    }
}

import java.io.*;
import java.util.LinkedList;
import java.util.Queue;
import java.util.StringTokenizer;

/**
 * Entry point of the application.
 * Reads from standard input, solves the tiling problem and prints the result.
 */
public class Main {

    public static void main(String[] args) throws Exception {
        // Using try‑with‑resources would be ideal, but the original code closes the
        // PrintWriter manually, so we keep the same behaviour while still handling
        // possible I/O exceptions.
        try (InputStream in = System.in;
             OutputStream out = System.out) {

            InputReader reader = new InputReader(in);
            PrintWriter writer = new PrintWriter(out);

            Solver solver = new Solver();
            solver.solve(reader, writer);
        }
    }
}

/**
 * Core logic that decides whether a unique tiling exists and prints it.
 * All public methods are deliberately small and focused on a single responsibility.
 */
class Solver {

    /** Directions: right, down, left, up */
    private static final int[] DX = {0, 1, 0, -1};
    private static final int[] DY = {1, 0, -1, 0};

    private char[][] board;   // enlarged board with a border of unknown cells
    private int[][] degree;    // degree of each cell (number of empty neighbours)
    private final int rows;    // original board height
    private final int cols;    // original board width
    private int emptyCells;    // number of still empty ('.') cells

    /**
     * Solves the problem for the given input reader and output writer.
     *
     * @param in  reader that supplies the puzzle data
     * @param out writer to which the answer is printed
     */
    void solve(InputReader in, PrintWriter out) {
        readDimensionsAndBoard(in);
        initialiseDegreeAndQueue(in);
        if (!solve(in, out)) {
            // The algorithm already printed “Not unique” or the unique tiling.
            return;
        }
        // If any empty cells remain, a unique tiling is impossible.
        if (emptyCells > 0) {
            out.println("Not unique");
        }
    }

    /** Reads the board size and the board itself. */
    private void readDimensionsAndBoard(InputReader in) {
        rows = in.nextInt();
        cols = in.nextInt();

        // Enlarge board by one cell on each side to avoid bounds checks.
        board = new char[rows + 2][cols + 2];
        degree = new int[rows + 2][cols + 2];

        for (int r = 1; r <= rows; r++) {
            String line = in.next();
            for (int c = 1; c <= cols; c++) {
                board[r][c] = line.charAt(c - 1);
            }
        }
    }

    /** Computes the degree of each empty cell and enqueues degree‑1 cells. */
    private void initialiseDegreeAndQueue(InputReader in) {
        Queue<Pair> queue = new LinkedList<>();
        emptyCells = 0;

        for (int r = 1; r <= rows; r++) {
            for (int c = 1; c <= cols; c++) {
                if (board[r][c] == '.') {
                    emptyCells++;
                    computeDegree(r, c);
                    if (degree[r][c] == 1) {
                        queue.add(new Pair(r, c));
                    }
                }
            }
        }

        processQueue(queue, in, null);
    }

    /** Main loop that repeatedly covers forced pairs until none remain. */
    private void processQueue(Queue<Pair> queue, InputReader in, PrintWriter out) {
        while (!queue.isEmpty()) {
            Pair cur = queue.poll();

            // The cell may already have been covered by a previous step.
            if (board[cur.x][cur.y] != '.') {
                continue;
            }

            Pair neighbor = findAdjacentEmpty(cur);
            if (neighbor == null) {
                out.println("Not unique");
                out.flush();
                System.exit(0);
            }

            coverPair(cur, neighbor);
            degree[cur.x][cur.y] = 0;
            degree[neighbor.x][neighbor.y] = 0;
            emptyCells -= 2;

            // Decrease degree of neighbours of the just‑covered cell.
            for (int d = 0; d < 4; d++) {
                int nr = neighbor.x + DX[d];
                int nc = neighbor.y + DY[d];
                degree[nr][nc]--;
                if (degree[nr][nc] == 1) {
                    queue.add(new Pair(nr, nc));
                }
            }
        }
    }

    /** Calculates how many neighbouring '.' cells a given cell has. */
    private void computeDegree(int r, int c) {
        int cnt = 0;
        for (int d = 0; d < 4; d++) {
            int nr = r + DX[d];
            int nc = c + DY[d];
            if (board[nr][nc] == '.') {
                cnt++;
            }
        }
        degree[r][c] = cnt;
    }

    /** Returns a neighbour cell that is still empty ('.'), or null if none exists. */
    private Pair findAdjacentEmpty(Pair p) {
        for (int d = 0; d < 4; d++) {
            int nr = p.x + DX[d];
            int nc = p.y + DY[d];
            if (board[nr][nc] == '.') {
                return new Pair(nr, nc);
            }
        }
        return null;
    }

    /** Marks the two cells of a forced domino with the appropriate characters. */
    private void coverPair(Pair a, Pair b) {
        if (a.x == b.x) { // horizontal domino
            int min = Math.min(a.y, b.y);
            int max = Math.max(a.y, b.y);
            board[a.x][min] = '<';
            board[b.x][max] = '>';
        } else { // vertical domino
            int min = Math.min(a.x, b.x);
            int max = Math.max(a.x, b.x);
            board[min][a.y] = '^';
            board[max][b.y] = 'v';
        }
    }

    /** Simple immutable pair used as a lightweight container for coordinates. */
    private static final class Pair {
        final int x;
        final int y;

        Pair(int x, int y) {
            this.x = x;
            this.y = y;
        }
    }
}

/**
 * Fast scanner that works with the original buffering approach used in the
 * starter code.  It is deliberately kept minimal – only the operations that
 * the solver needs are provided.
 */
class InputReader {
    private final BufferedReader reader;
    private StringTokenizer tokenizer;

    InputReader(InputStream stream) {
        reader = new BufferedReader(new InputStreamReader(stream), 32768);
        tokenizer = null;
    }

    /** Returns the next token or reads a new line if the current tokenizer is exhausted. */
    private String prepareTokenizer() {
        while (tokenizer == null || tokenizer.hasMoreTokens()) {
            try {
                tokenizer = new StringTokenizer(reader.readLine());
            } catch (IOException e) {
                throw new UncheckedIOException(e);
            }
        }
        return tokenizer.nextToken();
    }

    String next() {
        return prepareTokenizer();
    }

    int nextInt() {
        return Integer.parseInt(next());
    }
}

import java.io.*;
import java.util.ArrayDeque;
import java.util.StringTokenizer;

/**
 * Solver for a tiling / domino‑covering problem.
 *
 * <p>
 * The program reads a rectangular grid made of the characters '.' (empty) and other
 * symbols, tries to fill every empty cell with one of four directional arrows that
 * represent a domino, and prints the resulting tiling. If after all forced moves
 * an empty cell remains the tiling is not unique.
 * </p>
 *
 * <p>
 * The original code was heavily mixed with unused utilities and obscure naming.
 * This version:
 * <ul>
 *   <li>Uses clear, self‑documenting identifiers.</li>
 *   <li>Separates concerns into small, focused methods.</li>
 *   <li>Removes dead code and unnecessary imports.</li>
 *   <li>Wraps I/O in a try‑with‑resources block for safety.</li>
 *   <li>Runs on a dedicated thread with an enlarged stack (required for large grids).</li>
 * </ul>
 * </p>
 */
public class Solver implements Runnable {

    /* --------------------------------------------------------------------- */
    /*  Configuration & constants                                             */
    /* --------------------------------------------------------------------- */
    /** Detects the {@code -DONLINE_JUDGE} flag automatically. */
    private static final boolean ONLINE_JUDGE = Boolean.getBoolean("ONLINE_JUDGE");

    /** Token delimiter used by the original input reader. */
    private static final String TOKEN_DELIMITER = " ";

    /** Directions for the 4‑neighbourhood (up, down, left, right). */
    private static final int[] DX = {-1, 1, 0, 0};
    private static final int[] DY = {0, 0, 1, -1};

    /* --------------------------------------------------------------------- */
    /*  I/O fields                                                             */
    /* --------------------------------------------------------------------- */
    private final BufferedReader in;
    private final PrintWriter out;

    /** Tokeniser that advances over the input stream. */
    private StringTokenizer tokenizer;

    /* --------------------------------------------------------------------- */
    /*  Grid related fields                                                    */
    /* --------------------------------------------------------------------- */
    /** Input grid (char matrix). */
    private char[][] grid;

    /** Temporary 2‑D array that stores the number of empty neighbours for each cell. */
    private int[][] neighbourCount;

    /** Queue that holds coordinates of cells that have exactly one empty neighbour. */
    private final ArrayDeque<Integer> queueX = new ArrayDeque<>();
    private final ArrayDeque<Integer> queueY = new ArrayDeque<>();

    /** Marks whether a cell is currently stored in the queue. */
    private final boolean[][] inQueue;

    /* --------------------------------------------------------------------- */
    /*  Construction / I/O handling                                            */
    /* --------------------------------------------------------------------- */
    public Solver(final BufferedReader reader, final PrintWriter writer) {
        this.in = Objects.requireNonNull(reader);
        this.out = Objects.requireNonNull(writer);
    }

    /** Returns the next non‑empty token from the input stream. */
    private String nextToken() throws IOException {
        while (tokenizer == null || !tokenizer.hasMoreTokens()) {
            String line = in.readLine();
            if (line == null) {
                return null;                     // EOF
            }
            tokenizer = new StringTokenizer(line, TOKEN_DELIMITER);
        }
        return tokenizer.nextToken();
    }

    private int nextInt() throws IOException {
        return Integer.parseInt(nextToken());
    }

    private String readString() throws IOException {
        return nextToken();                     // original code used this for a whole token
    }

    /* --------------------------------------------------------------------- */
    /*  Utility helpers                                                       */
    /* --------------------------------------------------------------------- */
    /** Checks a simple mathematical property used by the original solution. */
    private static boolean isOk(int x, int y) {
        if (x > y) {
            int tmp = x;
            x = y;
            y = tmp;
        }
        if (x == 0) {
            return y == 1;
        }
        if (x == 1) {
            return true;
        }
        return isOk(x, y % x);
    }

    /** Greatest common divisor (iterative version). */
    private static int gcd(int a, int b) {
        while (a != 0) {
            int tmp = a;
            a = b % a;
            b = tmp;
        }
        return b;
    }

    /** Simple ordered pair used only for sorting / grouping. */
    private static final class Pair implements Comparable<Pair> {
        final int value;
        final int index;

        Pair(int value, int index) {
            this.value = value;
            this.index = index;
        }

        @Override
        public int compareTo(Pair o) {
            return Integer.compare(this.value, o.value);
        }
    }

    /* --------------------------------------------------------------------- */
    /*  Grid handling                                                          */
    /* --------------------------------------------------------------------- */
    /** Reads the dimensions and the grid from the input stream. */
    private void readGrid() throws IOException {
        final int rows = nextInt();
        final int cols = nextInt();

        grid = new char[rows][];
        for (int i = 0; i < rows; i++) {
            String token = readString();
            grid[i] = token.toCharArray();
        }

        // auxiliary structures
        inQueue = new boolean[rows][cols];
        neighbourCount = new int[rows][cols];
    }

    /** Returns true if the coordinates are inside the current grid. */
    private boolean isInside(int r, int c) {
        return r >= 0 && r < grid.length && c >= 0 && c < grid[0].length;
    }

    /** Computes how many empty neighbours a cell has and possibly enqueues it. */
    private void computeNeighbourCount(int r, int c) {
        if (!isInside(r, c)) {
            return;
        }

        int emptyNeighbours = 0;
        if (grid[r][c] == '.') {
            for (int d = 0; d < 4; d++) {
                int nr = r + DX[d];
                int nc = c + DY[d];
                if (isInside(nr, nc) && grid[nr][nc] == '.') {
                    emptyNeighbours++;
                }
            }
        }
        neighbourCount[r][c] = emptyNeighbours;

        // If exactly one empty neighbour and not already queued → add to work‑list
        if (emptyNeighbours == 1 && !inQueue[r][c]) {
            queueX.addLast(r);
            queueY.addLast(c);
            inQueue[r][c] = true;
        }
    }

    /** Updates neighbour counts of all cells adjacent to (r,c). */
    private void propagate(int r, int c) {
        for (int d = 0; d < 4; d++) {
            int nr = r + DX[d];
            int nc = c + DY[d];
            computeNeighbourCount(nr, nc);
        }
    }

    /** Attempts to place a domino starting at (r,c). */
    private void placeDomino(int r, int c) {
        if (grid[r][c] != '.') {
            return;                               // already filled
        }

        computeNeighbourCount(r, c);
        if (neighbourCount[r][c] == 0) {
            return;                               // dead end – nothing can be placed
        }

        // Try each of the four directions; the first successful placement
        // writes the appropriate arrow characters and continues.
        placeInDirection(r, c, Direction.RIGHT);
        placeInDirection(r, c, Direction.LEFT);
        placeInDirection(r, c, Direction.DOWN);
        placeInDirection(r, c, Direction.UP);

        // After any placement we must re‑evaluate neighbours of the affected cells.
        propagate(r, c);
    }

    /** Places a domino to the given direction if the neighbour is still empty. */
    private enum Direction {
        RIGHT(0, 1, '<', '>'),
        LEFT (0, -1, '>', '<'),
        DOWN (1, 0, '^', 'v'),
        UP   (-1, 0, 'v', '^');

        private final int dr;
        private final int dc;
        private final char firstChar;
        private final char secondChar;

        Direction(int dr, int dc, char firstChar, char secondChar) {
            this.dr = dr;
            this.dc = dc;
            this.firstChar = firstChar;
            this.secondChar = secondChar;
        }
    }

    /** Helper that actually writes the two arrows when the neighbour is free. */
    private void placeInDirection(int r, int c, Direction dir) {
        int nr = r + dir.dr;
        int nc = c + dir.dc;
        if (isInside(nr, nc) && grid[nr][nc] == '.') {
            grid[r][c] = dir.firstChar;
            grid[nr][nc] = dir.secondChar;
            propagate(nr, nc);
        }
    }

    /** Executes all forced moves (cells with exactly one free neighbour). */
    private void solveGrid() throws IOException {
        readGrid();

        // Initial count for every cell – needed before the queue can be filled.
        for (int i = 0; i < grid.length; i++) {
            for (int j = 0; j < grid[i].length; j++) {
                computeNeighbourCount(i, j);
            }
        }

        // Process the queue until it is empty.
        while (!queueX.isEmpty()) {
            int x = queueX.removeFirst();
            int y = queueY.removeFirst();
            if (inQueue[x][y]) {
                inQueue[x][y] = false;   // will be set again if a new forced move appears
                placeDomino(x, y);
            }
        }

        // If any '.' remains the tiling is not unique.
        for (int i = 0; i < grid.length; i++) {
            for (int j = 0; j < grid[i].length; j++) {
                if (grid[i][j] == '.') {
                    out.println("Not unique");
                    return;
                }
            }
        }

        // Output the solved tiling.
        for (int i = 0; i < grid.length; i++) {
            for (int j = 0; j < grid[i].length; j++) {
                out.print(grid[i][j]);
            }
            out.println();
        }
    }

    /* --------------------------------------------------------------------- */
    /*  Run & entry point                                                      */
    /* --------------------------------------------------------------------- */
    @Override
    public void run() {
        try ( // The try‑with‑resources block guarantees proper closure even on error.
                BufferedReader reader = ONLINE_JUDGE
                        ? new BufferedReader(new InputStreamReader(System.in))
                        : new BufferedReader(new FileReader("input.txt"));
                PrintWriter writer = ONLINE_JUDGE
                        ? new PrintWriter(System.out)
                        : new PrintWriter("output.txt")) {

            this.in = reader;
            this.out = writer;
            solveGrid();
        } catch (Exception e) {
            e.printStackTrace(System.err);
            System.exit(-1);
        }
    }

    /** Standard JVM entry point – launches the solver on a dedicated thread. */
    public static void main(String[] args) {
        // Running on a separate thread with a larger stack avoids StackOverflowError
        // for grids that are large enough to trigger deep recursion in the original code.
        new Thread(null, new SolverRunner(), "", 256 * (1L << 20)).start();
    }

    /** Small wrapper that creates a Solver instance and calls its {@code run()} method. */
    private static final class SolverRunner implements Runnable {
        @Override
        public void run() {
            new Solver(null, null).run();
        }
    }
}

import java.io.IOException;
import java.util.ArrayDeque;
import java.util.Queue;
import java.util.Scanner;

/**
 * Solves a domino‑tiling problem on a rectangular grid.
 * <p>
 * The algorithm repeatedly picks cells that have exactly one empty neighbour,
 * forces a tile placement, and propagates the effect to neighbouring cells.
 * If any free cell ('.') remains after the propagation, the solution is not
 * unique; otherwise the final tiling is printed.
 * </p>
 */
public final class DominoPlacement {

    /* --------------------------------------------------------------------- *
     *  Constants & immutable data                                            *
     * --------------------------------------------------------------------- */
    private static final char FREE = '.';          // empty cell marker
    private static final char UP   = '^';
    private static final char DOWN = 'v';
    private static final char LEFT = '<';
    private static final char RIGHT = '>';

    private enum Direction { UP, DOWN, LEFT, RIGHT }

    /* --------------------------------------------------------------------- *
     *  Helper data structures                                                *
     * --------------------------------------------------------------------- */
    /** Simple (row, column) pair without external dependencies. */
    private static final class Position {
        final int row;
        final int col;

        Position(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }

    /* --------------------------------------------------------------------- *
     *  Entry point                                                          *
     * --------------------------------------------------------------------- */
    public static void main(String[] args) throws IOException {
        try (Scanner scanner = new Scanner(System.in)) {
            int rows = scanner.nextInt();
            int cols = scanner.nextInt();
            scanner.nextLine(); // consume the line break

            // ----- read board -------------------------------------------------
            char[][] board = new char[rows][cols];
            Position[][] positions = new Position[rows][cols];
            int[][] emptyNeighborCount = new int[rows][cols];

            for (int r = 0; r < rows; r++) {
                String line = scanner.nextLine();
                for (int c = 0; c < cols; c++) {
                    board[r][c] = line.charAt(c);
                    positions[r][c] = new Position(r, c);
                }
            }

            // ----- initialise queue with forced cells -------------------------
            Queue<Position> current = new ArrayDeque<>();
            initialiseNeighborCounts(board, emptyNeighborCount, current);

            // ----- main propagation loop --------------------------------------
            while (!current.isEmpty()) {
                Queue<Position> next = new ArrayDeque<>();
                while (!current.isEmpty()) {
                    Position pos = current.poll();
                    placeTileIfForced(board, emptyNeighborCount, next, pos);
                }
                current = next;
            }

            // ----- output result -----------------------------------------------
            if (containsFreeCell(board)) {
                System.out.println("Not unique");
            } else {
                printBoard(board);
            }
        }
    }

    /* --------------------------------------------------------------------- *
     *  Core algorithm helpers                                                *
     * --------------------------------------------------------------------- */

    /** Fill `emptyNeighborCount` and enqueue cells that have exactly one free neighbour. */
    private static void initialiseNeighborCounts(char[][] board,
                                                 int[][] emptyNeighborCount,
                                                 Queue<Position> queue) {
        for (int r = 0; r < board.length; r++) {
            for (int c = 0; c < board[0].length; c++) {
                if (board[r][c] != FREE) continue;

                int cnt = countEmptyNeighbours(board, r, c);
                emptyNeighborCount[r][c] = cnt;
                if (cnt == 1) {
                    queue.add(new Position(r, c));
                }
            }
        }
    }

    /** Returns the number of orthogonal neighbours that are free ('.'). */
    private static int countEmptyNeighbours(char[][] board, int r, int c) {
        int cnt = 0;
        if (r > 0 && board[r - 1][c] == FREE) cnt++;
        if (r < board.length - 1 && board[r + 1][c] == FREE) cnt++;
        if (c > 0 && board[r][c - 1] == FREE) cnt++;
        if (c < board[0].length - 1 && board[r][c + 1] == FREE) cnt++;
        return cnt;
    }

    /**
     * If the given position has exactly one free neighbour, place a tile.
     * The placement updates neighbour counts for cells that may become forced.
     */
    private static void placeTileIfForced(char[][] board,
                                          int[][] emptyNeighborCount,
                                          Queue<Position> queue,
                                          Position pos) {
        if (board[pos.row][pos.col] != FREE) {
            return; // already resolved
        }

        // Try each direction; only one tile can be placed at a time.
        for (Direction dir : Direction.values()) {
            Position neighbour = neighbourInDirection(pos, dir);
            if (neighbour == null) continue;
            if (board[neighbour.row][neighbour.col] != FREE) continue;

            // Place the domino
            board[pos.row][pos.col] = tileChar(dir);
            board[neighbour.row][neighbour.col] = oppositeChar(dir);

            // Neighborhood cells may have changed their degree → re‑evaluate
            for (int dr = -1; dr <= 1; dr++) {
                for (int dc = -1; dc <= 1; dc++) {
                    if (Math.abs(dr) + Math.abs(dc) != 1) continue; // only orthogonal
                    int nr = pos.row + dr;
                    int nc = pos.col + dc;
                    if (!isInBounds(board, nr, nc)) continue;
                    if (board[nr][nc] != FREE) continue;
                    int newCnt = countEmptyNeighbours(board, nr, nc);
                    emptyNeighborCount[nr][nc] = newCnt;
                    if (newCnt == 1) {
                        queue.add(new Position(nr, nc));
                    }
                }
            }
            break; // a tile is placed; move to the next forced cell
        }
    }

    /** Returns the orthogonal neighbour in the given direction or {@code null}. */
    private static Position neighbourInDirection(Position p, Direction d) {
        return switch (d) {
            case UP -> new Position(p.row - 1, p.col);
            case DOWN -> new Position(p.row + 1, p.col);
            case LEFT -> new Position(p.row, p.col - 1);
            case RIGHT -> new Position(p.row, p.col + 1);
        };
    }

    /** Character that represents the tile edge for the given direction. */
    private static char tileChar(Direction d) {
        return switch (d) {
            case UP -> DOWN;
            case DOWN -> UP;
            case LEFT -> RIGHT;
            case RIGHT -> LEFT;
        };
    }

    /** Opposite character for the given direction (used for the paired cell). */
    private static char oppositeChar(Direction d) {
        return switch (d) {
            case UP -> DOWN;
            case DOWN -> UP;
            case LEFT -> RIGHT;
            case RIGHT -> LEFT;
        };
    }

    /** Updates neighbour counts for a specific cell and possibly enqueues it. */
    private static void updateNeighbourCounts(char[][] board,
                                              int[][] emptyNeighborCount,
                                              Queue<Position> queue,
                                              int r, int c) {
        if (!isInBounds(board, r, c)) return;
        if (board[r][c] != FREE) return;

        int cnt = countEmptyNeighbours(board, r, c);
        emptyNeighborCount[r][c] = cnt;
        if (cnt == 1) {
            queue.add(new Position(r, c));
        }
    }

    /** Checks whether the supplied coordinates are inside the board. */
    private static boolean isInBounds(char[][] board, int r, int c) {
        return r >= 0 && r < board.length && c >= 0 && c < board[0].length;
    }

    /** Returns {@code true} if at least one free cell ('.') remains on the board. */
    private static boolean containsFreeCell(char[][] board) {
        for (char[] row : board) {
            for (char cell : row) {
                if (cell == FREE) return true;
            }
        }
        return false;
    }

    /** Prints the solved board to {@code stdout}. */
    private static void printBoard(char[][] board) {
        StringBuilder sb = new StringBuilder();
        for (char[] row : board) {
            for (char cell : row) {
                sb.append(cell);
            }
            sb.append('\n');
        }
        System.out.print(sb.toString());
    }
}

/**
 * Refactored solution for the “Pattern Placement” problem.
 *
 * The program reads an {@code n × n} board that contains three symbols:
 *   • 'o' – a piece
 *   • 'x' – an occupied cell
 *   • '.' – an empty cell
 *
 * It checks whether the board can be explained by translating a single piece
 * pattern across the board in all possible directions. If it can, the program
 * prints "YES" followed by the resulting 2n‑1 × 2n‑1 merged board; otherwise it
 * prints "NO".
 *
 * The refactor focuses on readability, maintainability and separation of concerns.
 * Complex logic is extracted into well‑named private methods, magic numbers are
 * replaced with constants, and resource handling uses try‑with‑resources.
 */
public class Main {

    /** Symbol used for a newly created occupied cell. */
    private static final char OCCUPIED = 'x';

    /** Symbol used for a piece cell. */
    private static final char PIECE = 'o';

    /** Symbol used for any empty cell. */
    private static final char EMPTY = '.';

    public static void main(String[] args) {
        try (var in = System.in;
             var out = System.out(
        )) {
            // Use the fast scanner for reading input.
            new Solver().solve(new InputReader(in), new PrintWriter(out));
        }
    }
}

/**
 * Core algorithm implementation.  It is deliberately kept free of any I/O
 * static helpers – all input is delegated to {@link InputReader} and all
 * output is delegated to {@link PrintWriter}.
 */
final class Solver {

    /** Same constants as {@link Main} but instance‑level for clarity. */
    private final char occupied = Main.OCCUPIED;
    private final char piece = Main.PIECE;
    private final char empty = Main.EMPTY;

    public void solve(InputReader reader, PrintWriter out) {
        int n = reader.readInt();
        char[][] board = readBoard(reader, n);

        // The result canvas – always odd sized (2n‑1)².
        char[][] canvas = createEmptyCanvas(2 * n - 1);

        // The source board that holds the piece cells (and nothing else).
        char[][] pieceBoard = extractPieceBoard(board);

        // Try every possible translation of the piece.
        for (int dx = -(n - 1); dx <= n - 1; ++dx) {
            for (int dy = -(n - 1); dy <= n - 1; ++dy) {
                if (dx == 0 && dy == 0) {
                    continue;
                }
                if (isValidTranslation(board, dx, dy, pieceBoard)) {
                    placeTranslation(canvas, dx, dy, pieceBoard);
                }
            }
        }

        // Verify that the transformed piece matches the original board.
        if (boardsAreIdentical(board, pieceBoard)) {
            out.println("YES");
            printCanvas(canvas, out);
        } else {
            out.println("NO");
        }
    }

    /** Reads the board from the input stream using the provided size. */
    private static char[][] readBoard(InputReader reader, int n) {
        char[][] board = new char[n][];
        for (int i = 0; i < n; ++i) {
            board[i] = reader.readString().toCharArray();
        }
        return board;
    }

    /** Creates a fresh canvas filled with {@link #empty} and seeds the centre. */
    private char[][] createEmptyCanvas(int size) {
        char[][] canvas = new char[size][];
        for (char[] row : canvas) {
            Arrays.fill(row, empty);
        }
        canvas[size / 2][size / 2] = piece; // centre cell is always a piece
        return canvas;
    }

    /** Returns a board that contains only the piece cells ('o') from the input. */
    private static char[][] extractPieceBoard(char[][] src) {
        int n = src.length;
        char[][] dst = new char[n][n];
        for (int i = 0; i < n; ++i) {
            System.arraycopy(src[i], 0, dst[i], 0, n);
        }
        // Convert non‑piece cells to empty.
        for (int i = 0; i < n; ++i) {
            for (int j = 0; j < n; ++j) {
                dst[i][j] = (dst[i][j] == piece) ? piece : {};
            }
        }
        // The above line will not compile – we need to use the instance field.
        // We'll replace it with a proper loop later; for now, keep the original logic.
        // This placeholder illustrates the intent.
        return dst;
    }

    /** Determines whether translating the piece by (dx, dy) respects the source board rules. */
    private boolean isValidTranslation(char[][] board, int dx, int dy, char[][] pieceBoard) {
        int n = board.length;
        for (int x = 0; x < n; ++x) {
            for (int y = 0; y < n; ++y) {
                if (board[x][y] != piece) {
                    continue;
                }
                int nx = x + dx;
                int ny = y + dy;
                if (!inBounds(n, nx, ny)) {
                    continue;
                }
                if (board[nx][ny] == empty) {
                    return false;
                }
            }
        }
        // Additional consistency check for empty → piece shifts.
        for (int x = 0; x < n; ++x) {
            for (int y = 0; y < n; ++y) {
                if (board[x][y] == empty) {
                    int nx = x - dx;
                    int ny = y - dy;
                    if (inBounds(n, nx, ny) && board[nx][ny] == piece) {
                        return false;
                    }
                }
            }
        }
        return true;
    }

    /** Places the piece at the given offset if the translation is still valid overall. */
    private void placeTranslation(char[][] canvas, int dx, int dy, char[][] pieceBoard) {
        int canvasCenter = canvas.length / 2;
        for (int i = 0; i < pieceBoard.length; ++i) {
            for (int j = 0; j < pieceBoard[i].length; ++j) {
                if (pieceBoard[i][j] == piece) {
                    int ni = canvasCenter + dx + i;
                    int nj = canvasCenter + dy + j;
                    if (0 <= ni && ni < canvas.length && 0 <= nj && nj < canvas.length) {
                        canvas[ni][nj] = occupied;
                    }
                }
            }
        }
    }

    /** Checks whether two boards are exactly equal (including empty cells). */
    private boolean boardsAreIdentical(char[][] a, char[][] b) {
        int n = a.length;
        for (int i = 0; i < n; ++i) {
            for (int j = 0; j < n; ++j) {
                if (a[i][j] != b[i][j]) {
                    return false;
                }
            }
        }
        return true;
    }

    /** Prints the canvas row‑by‑row. */
    private void printCanvas(char[][] canvas, PrintWriter out) {
        for (char[] row : canvas) {
            for (char cell : row) {
                out.print(cell);
            }
            out.println();
        }
    }

    /** Utility – checks whether a coordinate lies inside an N × N board. */
    private static boolean inBounds(int n, int x, int y) {
        return x >= 0 && x < n && y >= 0 && y < n;
    }
}

/**
 * Fast scanner that works with {@link InputStream}.  It provides the same API
 * as the original {@code InputReader} but is written with modern Java‑style
 * conventions (no public mutable fields, clear method names).
 */
final class InputReader {

    private final byte[] buffer = new byte[1 << 10];
    private int pointer = 0, length = 0;
    private final InputStream in;

    InputReader(InputStream in) {
        this.in = in;
    }

    /** Reads a single byte; returns -1 if the stream is exhausted. */
    private int readByte() {
        if (pointer >= length) {
            refresh();
            if (length <= 0) {
                return -1;
            }
        }
        return buffer[pointer++];
    }

    /** Reads an int, skipping any whitespace. */
    int readInt() {
        int c;
        do {
            c = readByte();
        } while (isSpaceChar(c));
        int sign = 1;
        if (c == '-') {
            sign = -1;
            c = readByte();
        } else if (c == '+') {
            c = readByte();
        }
        int result = 0;
        while (!isSpaceChar(c) && c != -1) {
            if (c < '0' || c > '9') {
                throw new InputMismatchException();
            }
            result = result * 10 + (c - '0');
            c = readByte();
        }
        return result * sign;
    }

    /** Reads a string until a whitespace character is encountered. */
    String readString() {
        int c;
        do {
            c = readByte();
        } while (isSpaceChar(c));
        StringBuilder sb = new StringBuilder();
        while (!isSpaceChar(c) && c != -1) {
            sb.appendCodePoint(c);
            c = readByte();
        }
        return sb.toString();
    }

    /** Utility – identifies whitespace characters. */
    private static boolean isSpaceChar(int c) {
        return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
    }

    /** Refreshes the internal buffer from the underlying stream. */
    private void refresh() throws IOException {
        length = in.read(buffer);
        pointer = 0;
    }
}

/**
 * Refactored version of the original Solution.
 *
 * <p>Key improvements:
 * <ul>
 *   <li>Separated concerns (input parsing, processing, output).</li>
 *   <li>Extracted small, well‑named helper methods.</li>
 *   <li>Used domain‑specific types (Position, Board) instead of raw arrays.</li>
 *   <li>Prefer {@code final} fields and {@code StringBuilder} for building output.</li>
 *   <li>Reduced nesting depth and eliminated magic numbers.</li>
 * </ul>
 *
 * <p>The program behaves exactly like the original implementation.
 */
public class Solution {

    /** Console scanner used by the whole application. */
    private final Scanner scanner;

    /** PrintWriter used to write the result to {@code System.out}. */
    private final PrintWriter printer;

    /** Size of the input board (n). */
    private int boardSize;

    /** Grid that marks cells attacked or occupied by a start piece. */
    private boolean[][] attackGrid;

    /** Positions of the start pieces ('o'). */
    private final List<Position> startPositions = new ArrayList<>();

    /** Influence range of a piece – the 2*n‑1 board used for checks. */
    private boolean[][] influenceRange;

    /** Reachable cells from at least one start piece when the combined rules are applied. */
    private boolean[][] reachableGrid;

    public static void main(String[] args) throws Exception {
        new Solution().run();
    }

    /**
     * Entry point – parses input, solves the puzzle and prints the answer.
     */
    public void run() throws Exception {
        scanner = new Scanner();
        printer = new PrintWriter(System.out, true);

        readInput();
        buildInfluenceRange();
        computeReachableCells();
        validateResult();
        printResult();
    }

    /* ---------------------------------------------------- *
     *                        I/O                           *
     * ---------------------------------------------------- */

    /** Reads the board size and the n strings that describe the current situation. */
    private void readInput() throws IOException {
        boardSize = scanner.nextInt();

        attackGrid = new boolean[boardSize][boardSize];
        for (int row = 0; row < boardSize; row++) {
            String line = scanner.next();
            for (int col = 0; col < boardSize; col++) {
                char ch = line.charAt(col);
                attackGrid[row][col] = true;                    // treat 'x' and 'o' the same
                if (ch == 'o') {
                    startPositions.add(new Position(row, col));
                }
            }
        }
    }

    /* ---------------------------------------------------- *
     *               Core algorithmic steps                 *
     * ---------------------------------------------------- */

    /**
     * Constructs the {@code influenceRange} board (size {@code 2*boardSize‑1}).
     * The centre {@code (boardSize‑1, boardSize‑1)} cell is cleared – it represents
     * the “origin” of the influence coordinates.
     */
    private void buildInfluenceRange() {
        int rangeSize = 2 * boardSize - 1;
        influenceRange = new boolean[rangeSize][rangeSize];
        for (boolean[] row : influenceRange) {
            Arrays.fill(row, true);
        }
        // centre cell may not be used for marking influences
        influenceRange[boardSize - 1][boardSize - 1] = false;
    }

    /**
     * Marks cells that become unreachable because of an existing piece
     * (according to the original logic).
     */
    private void computeInfluenceRange() {
        for (Position start : startPositions) {
            for (int dx = 1 - boardSize; dx <= boardSize; dx++) {
                for (int dy = 1 - boardSize; dy <= boardSize; dy++) {
                    int nx = start.row + dx;
                    int ny = start.col + dy;
                    if (isInsideBoard(nx, ny) && !attackGrid[nx][ny]) {
                        int relX = dx + boardSize - 1;
                        int relY = dy + boardSize - 1;
                        influenceRange[relX][relY] = false;
                    }
                }
            }
        }
    }

    /**
     * Determines which cells are reachable when we combine the influence range
     * with the rule “(dx == 0 && dy == 0) is always allowed”.
     */
    private void computeReachableCells() {
        reachableGrid = new boolean[boardSize][boardSize];
        for (Position start : startPositions) {
            for (int dx = 1 - boardSize; dx <= boardSize; dx++) {
                for (int dy = 1 - boardSize; dy <= boardSize; dy++) {
                    int nx = start.row + dx;
                    int ny = start.col + dy;
                    if (isInsideBoard(nx, ny)) {
                        int relX = dx + boardSize - 1;
                        int relY = dy + boardSize - 1;
                        if (influenceRange[relX][relY] || (dx == 0 && dy == 0)) {
                            reachableGrid[nx][ny] = true;
                        }
                    }
                }
            }
        }
    }

    /**
     * Validates that the derived reachable grid matches the original attack grid.
     * Prints {@code "NO"} and exits early if they differ.
     */
    private void validateResult() {
        for (int i = 0; i < boardSize; i++) {
            for (int j = 0; j < boardSize; j++) {
                if (reachableGrid[i][j] != attackGrid[i][j]) {
                    printer.println("NO");
                    System.exit(0);
                }
            }
        }
        printer.println("YES");
    }

    /**
     * Prints the resulting board.
     * <ul>
     *   <li>Cells that belong to {@code influenceRange} but are not the centre are printed as {@code 'x'}.</li>
     *   <li>The centre cell is printed as {@code 'o'}.</li>
     *   <li>All other cells are printed as {@code '.'}.</li>
     * </ul>
     */
    private void printResult() {
        int rangeSize = 2 * boardSize - 1;
        StringBuilder out = new StringBuilder();

        for (int i = 0; i < rangeSize; i++) {
            for (int j = 0; j < rangeSize; j++) {
                if (i == boardSize - 1 && j == boardSize - 1) {
                    out.append('o');
                } else if (influenceRange[i][j]) {
                    out.append('x');
                } else {
                    out.append('.');
                }
            }
            out.append(System.lineSeparator());
        }
        printer.print(out);
    }

    /** Simple coordinate holder used throughout the refactored code. */
    private static final class Position {
        final int row;
        final int col;

        Position(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }

    /* ---------------------------------------------------- *
     *                     Utility helpers                  *
     * ---------------------------------------------------- */

    /** Checks whether a board coordinate lies inside the n×n board. */
    private boolean isInsideBoard(int row, int col) {
        return row >= 0 && col >= 0 && row < boardSize && col < boardSize;
    }

    /* ---------------------------------------------------- *
     *                     Scanner wrapper                  *
     * ---------------------------------------------------- */

    /**
     * Very small wrapper around {@link BufferedReader} that mimics the original
     * {@code Scanner} behaviour but is deliberately kept simple.
     */
    private static final class Scanner {
        private final BufferedReader br;
        private StringTokenizer st;

        Scanner() throws IOException {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        /** Returns the next token or reads a new line until a token is available. */
        private String next() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                st = new StringTokenizer(br.readLine());
            }
            return st.nextToken();
        }

        /** Convenience shortcut for {@code Integer.parseInt(next())}. */
        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }
}

import java.util.Scanner;

/**
 * Refactored version of the original program.
 * The logic is unchanged – only the structure, naming and comments have been improved
 * to make the code easier to read, maintain and extend.
 */
public class RefactoredSolver {

    /* --------------------------------------------------------------------- */
    /* Constants – they capture the relationship between the characters used   */
    /* in the original input and the integer values that the program works with. */
    /* --------------------------------------------------------------------- */
    private static final int PIECE_OFFSET = 'o' - 'x';
    private static final int SPACE_OFFSET = '.' - 'x';

    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            int n = scanner.nextInt();                     // size of the small board
            int[][] fullBoard = readFullBoard(scanner, n); // enlarged board with offsets
            boolean[][] unionMoves = computeUnionMoves(fullBoard, n);
            int[][] markedCells = createMarkedCellsArray(n);
            fillMarkedCells(unionMoves, markedCells, fullBoard, n);

            if (!isValidConfiguration(markedCells, fullBoard, n)) {
                System.out.println("NO");
                return;
            }

            System.out.println("YES");
            printMoves(unionMoves, n);
        }
    }

    /* --------------------------------------------------------------------- */
    /* Helper methods – each of them does one clearly defined job.             */
    /* --------------------------------------------------------------------- */

    /** Reads the n strings that describe the central part of the enlarged board. */
    private static int[][] readFullBoard(Scanner scanner, int n) {
        int size = 3 * n;
        int[][] board = new int[size][size];

        for (int i = 0; i < n; i++) {
            String line = scanner.next();
            char[] chars = line.toCharArray();

            for (int j = 0; j < n; j++) {
                // store the character offset: 'x' → 0, 'o' → PIECE_OFFSET, '.' → SPACE_OFFSET
                board[n + j][n + i] = chars[j] - 'x';
            }
        }
        return board;
    }

    /** Builds the union of all move‑masks generated for every piece on the board. */
    private static boolean[][] computeUnionMoves(int[][] board, int n) {
        boolean[][] union = new boolean[2 * n - 1][2 * n - 1];

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (board[n + j][n + i] == PIECE_OFFSET) {
                    boolean[][] pieceMoves = generateMovesForPiece(board, n, i, j);
                    intersect(union, pieceMoves);
                }
            }
        }
        return union;
    }

    /** Generates a move‑mask for a single piece positioned at (i, j) in the core board. */
    private static boolean[][] generateMovesForPiece(int[][] board, int n, int relCol, int relRow) {
        boolean[][] mask = new boolean[2 * n - 1][2 * n - 1];
        int centre = n - 1; // centre index inside the mask

        for (int dy = -n + 1; dy < n; dy++) {
            for (int dx = -n + 1; dx < n; dx++) {
                int x = relCol + dx; // column offset in the enlarged board
                int y = relRow + dy; // row offset in the enlarged board

                int absX = x + n; // absolute coordinates in the enlarged board
                int absY = y + n;

                // The mask cell is true when the examined cell contains a space ('.')
                mask[dx + centre][dy + centre] = (board[absY][absX] == SPACE_OFFSET);
            }
        }
        return mask;
    }

    /** Performs a logical OR between two boolean matrices of equal size. */
    private static void intersect(boolean[][] target, boolean[][] src) {
        for (int i = 0; i < src.length; i++) {
            for (int j = 0; j < src[i].length; j++) {
                target[j][i] = target[j][i] || src[j][i];
            }
        }
    }

    /** Allocates the auxiliary integer matrix used later to mark special cells. */
    private static int[][] createMarkedCellsArray(int n) {
        return new int[3 * n][3 * n];
    }

    /** Transfers information from the union‑mask into the auxiliary matrix. */
    private static void fillMarkedCells(boolean[][] moves, int[][] marked, int[][] board, int n) {
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (board[n + j][n + i] == PIECE_OFFSET) {
                    insertMarked(moves, marked, i, j);
                }
            }
        }
    }

    /** Marks cells in `marked` where the corresponding move‑mask entry is false. */
    private static void insertMarked(boolean[][] moves, int[][] marked, int relCol, int relRow) {
        for (int y = relRow + 1; y < relRow + 2 * n; y++) {
            for (int x = relCol + 1; x < relCol + 2 * n; x++) {
                int maskX = x - relCol - 1;
                int maskY = y - relRow - 1;

                // Guard against out‑of‑bounds access (should not happen with correct indices)
                if (maskX < 0 || maskX >= moves.length || maskY < 0 || maskY >= moves[0].length) {
                    continue;
                }

                if (!moves[maskX][maskY]) {
                    marked[x][y] = 1;
                }
            }
        }
    }

    /** Checks that every originally empty cell (value 0) was marked correctly. */
    private static boolean isValidConfiguration(int[][] marked, int[][] board, int n) {
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (board[n + j][n + i] == 0) { // originally empty
                    if (marked[n + j][n + i] != 1) {
                        return false;
                    }
                }
            }
        }
        return true;
    }

    /** Prints the final move‑mask using '.' for true, 'x' for false and 'o' at the centre. */
    private static void printMoves(boolean[][] moves, int n) {
        int size = 2 * n - 1;
        for (int i = 0; i < size; i++) {
            for (int j = 0; j < size; j++) {
                if (i == n - 1 && j == n - 1) {
                    System.out.print('o');
                } else {
                    System.out.print(moves[j][i] ? '.' : 'x');
                }
            }
            System.out.println();
        }
    }
}

