import java.util.List;

/**
 * Main entry point – delegates work to {@link Solver}.
 */
public class Main {
    public static void main(String[] args) throws IOException {
        // try‑with‑resources guarantees proper closing of streams
        try (InputReader in = new InputReader(System.in);
             PrintWriter out = new PrintWriter(System.out)) {
            new Solver().solve(in, out);
        }
    }
}

/**
 * Core logic of the problem.
 * <p>
 * The class is deliberately small, uses only pure Java types and
 * contains self‑documenting methods that each perform a single responsibility.
 */
final class Solver {

    /** Symbols used on the board */
    private static final char EMPTY   = '.';
    private static final char OBSTACLE = 'x';
    private static final char KING     = 'o';

    /** Size of the original n × n board */
    private int n;

    /** Original board */
    private char[][] board;

    /** Positions of all kings ('o') on the board */
    private final List<Point> occupiedSquares = new ArrayList<>();

    /** Simple 2‑D point – immutable and lightweight */
    private static final class Point {
        final int x, y;
        Point(int x, int y) { this.x = x; this.y = y; }
    }

    /** Reads the whole input and fills the internal state. */
    private void read(InputReader in) {
        n = in.nextInt();
        board = new char[n][];
        for (int i = 0; i < n; i++) {
            board[i] = in.next().toCharArray();
        }

        occupiedSquares.clear();
        for (int y = 0; y < n; y++) {
            for (int x = 0; x < n; x++) {
                if (board[y][x] == KING) {
                    occupiedSquares.add(new Point(x, y));
                }
            }
        }
    }

    /** Utility – checks whether (x, y) lies inside the board. */
    private boolean isInside(int x, int y) {
        return 0 <= x && x < n && 0 <= y && y < n;
    }

    /** Executes the whole solving process. */
    private void solve(InputReader in, PrintWriter out) {
        read(in);

        int boardSize = 2 * n - 1;                // size of the result matrix
        char[][] result = new char[boardSize][boardSize];
        List<Point> kingMoves = new ArrayList<>(); // moves that reach an empty square

        // -----------------------------------------------------------------
        // 1. Build the 2n‑1 × 2n‑1 result matrix.
        // -----------------------------------------------------------------
        Point centre = new Point(n - 1, n - 1);
        for (int y = 0; y < boardSize; y++) {
            for (int x = 0; x < boardSize; x++) {
                if (x == centre.x && y == centre.y) {
                    result[y][x] = KING;               // centre cell always contains a king
                    continue;
                }

                int dx = x - centre.x;                 // displacement from centre
                int dy = y - centre.y;

                // Check whether any king can move to (dx, dy) without leaving the board
                boolean canStep = false;
                for (Point king : occupiedSquares) {
                    int nx = king.x + dx;
                    int ny = king.y + dy;
                    if (isInside(nx, ny) && board[ny][nx] == EMPTY) {
                        canStep = true;
                        break;
                    }
                }

                result[y][x] = canStep ? EMPTY : OBSTACLE;
                if (!canStep) {
                    kingMoves.add(new Point(dx, dy));
                }
            }
        }

        // -----------------------------------------------------------------
        // 2. Validate that every obstacle ('x') on the original board can be captured.
        // -----------------------------------------------------------------
        for (int y = 0; y < n; y++) {
            for (int x = 0; x < n; x++) {
                if (board[y][x] == OBSTACLE) {
                    boolean capturable = false;
                    for (Point move : kingMoves) {
                        int targetX = x - move.x;
                        int targetY = y - move.y;
                        if (isInside(targetX, targetY) && board[targetY][targetX] == KING) {
                            capturable = true;
                            break;
                        }
                    }
                    if (!capturable) {
                        out.println("NO");
                        return;
                    }
                }
            }
        }

        // -----------------------------------------------------------------
        // 3. Output the answer.
        // -----------------------------------------------------------------
        out.println("YES");
        for (char[] row : result) {
            out.println(new String(row));
        }
    }
}

/**
 * Very small buffered input helper.
 * It skips empty lines and trims whitespace – sufficient for typical competitive‑programming problems.
 */
class InputReader {
    private final BufferedReader reader;

    InputReader(InputStream stream) {
        reader = new BufferedReader(new InputStreamReader(stream), 32768);
    }

    /** Returns the next non‑empty token (whitespace‑separated). */
    private String nextToken() throws IOException {
        while (true) {
            String line = reader.readLine();
            if (line == null) return null;                // EOF
            line = line.trim();
            if (!line.isEmpty()) return line;
        }
    }

    String next() { return nextToken(); }

    int nextInt() { return Integer.parseInt(next()); }
}

