/**
 * Simple scanner that supplies tokens (strings and integers) from the input.
 */
class FastScanner {
    private final BufferedReader br;

    FastScanner(Reader reader) {
        this.br = new BufferedReader(reader);
    }

    /** Returns the next token, or {@code null} if EOF is reached. */
    String next() throws IOException {
        while (true) {
            String line = br.readLine();
            if (line == null) {
                return null;
            }
            String trimmed = line.trim();
            if (!trimmed.isEmpty()) {
                return readToken(trimmed);
            }
        }
    }

    /** Parses the next token as an {@code int}. */
    int nextInt() throws IOException {
        return Integer.parseInt(next());
    }

    /** Reads a whitespace‑delimited token from the supplied line. */
    private String readToken(String line) {
        int end = line.length() - 1;
        while (end >= 0 && Character.isWhitespace(line.charAt(end))) {
            end--;
        }
        String trimmed = line.substring(0, end + 1);
        int start = 0, i = 0;
        while (i <= end && Character.isWhitespace(trimmed.charAt(i))) {
            i++;
        }
        int tokenStart = i;
        while (i <= end && !Character.isWhitespace(trimmed.charAt(i))) {
            i++;
        }
        return trimmed.substring(tokenStart, i);
    }
}

/**
 * Contains the core logic for solving the board‑placement problem.
 */
class Solver {
    private final FastScanner in;
    private final PrintWriter out;

    Solver(FastScanner in, PrintWriter out) {
        this.in = in;
        this.out = out;
    }

    /** Runs the whole solution. */
    void solve() throws IOException {
        int n = in.nextInt();
        String[] board = readBoard(n);
        Position[] pieces = collectPieces(board);
        char[][] template = buildEmptyTemplate(n);
        markForbiddenMoves(board, pieces, template);
        if (hasUncoveredBlockedCell(board, pieces, template)) {
            out.println("NO");
            return;
        }
        out.println("YES");
        printTemplate(template);
    }

    /** Reads the n × n board from the scanner. */
    private String[] readBoard(int n) throws IOException {
        String[] board = new String[n];
        for (int i = 0; i < n; i++) {
            board[i] = in.next();
        }
        return board;
    }

    /** Gathers the coordinates of all 'o' pieces on the board. */
    private Position[] collectPieces(String[] board) {
        List<Position> list = new ArrayList<>();
        for (int r = 0; r < board.length; r++) {
            String row = board[r];
            for (int c = 0; c < row.length(); c++) {
                if (row.charAt(c) == 'o') {
                    list.add(new Position(r, c));
                }
            }
        }
        return list.toArray(new Position[0]);
    }

    /** Creates an empty (all 'x') template of size (2n‑1) × (2n‑1) with a single 'o' in the centre. */
    private char[][] buildEmptyTemplate(int n) {
        char[][] moves = new char[2 * n - 1][2 * n - 1];
        for (char[] row : moves) {
            Arrays.fill(row, 'x');
        }
        moves[n - 1][n - 1] = 'o';
        return moves;
    }

    /**
     * Marks cells that become impossible because they would require moving onto a blocked empty cell.
     * The method mutates {@code grid} in‑place.
     */
    private void markForbiddenMoves(String[] board, Position[] pieces, char[][] grid) {
        int boardSize = board.length;
        for (int r = 0; r < boardSize; r++) {
            String row = board[r];
            for (int c = 0; c < boardSize; c++) {
                if (row.charAt(c) == '.') {
                    for (Position p : pieces) {
                        int dx = r - p.row;
                        int dy = c - p.col;
                        int targetX = (boardSize - 1) + dx;
                        int targetY = (boardSize - 1) + dy;
                        if (inside(grid) && grid[targetX][targetY] == 'x') {
                            grid[targetX][targetY] = '.';
                        }
                    }
                }
            }
        }
    }

    /** Returns {@code true} if the supplied coordinates are inside the grid. */
    private boolean inside(char[][] grid) {
        return grid != null && grid.length > 0 && grid[0].length > 0;
    }

    /**
     * Determines whether there exists a blocked cell ('x') that cannot be reached by any placement.
     * If such a cell is found we must output “NO”.
     */
    private boolean hasUncoveredBlockedCell(String[] board, Position[] pieces, char[][] grid) {
        for (int r = 0; r < board.length; r++) {
            String row = board[r];
            for (int c = 0; c < row.length(); c++) {
                if (row.charAt(c) == 'x') {
                    boolean reachable = false;
                    for (Position p : pieces) {
                        int dx = r - p.row;
                        int dy = c - p.col;
                        int targetX = (grid.length / 2) + dx; // centre index = n‑1 for odd size
                        int targetY = (grid.length / 2) + dy;
                        if (inside(grid) && grid[targetX][targetY] == 'x') {
                            reachable = true;
                            break;
                        }
                    }
                    if (!reachable) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    /** Prints the resulting template to the output writer. */
    private void printTemplate(char[][] grid) {
        for (char[] row : grid) {
            out.println(new String(row));
        }
    }

    /** Immutable container for a board coordinate. */
    private static final class Position {
        final int row;
        final int col;

        Position(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }
}

