/**
 * Small utility that wraps a {@link InputStream} and provides fast primitive
 * reading methods used by the solver.
 */
final class FastScanner {

    private final InputStream in;
    private final byte[] buffer = new byte[16_384];
    private int ptr = 0, len = 0;

    FastScanner(InputStream in) {
        this.in = in;
        skipWhitespace();
        fillBuffer();
    }

   private void fillBuffer() {
        try {
            len = in.read(buffer);
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
        ptr = 0;
        if (len <= 0) {
            buffer[0] = -1; // sentinel for EOF
        }
    }

    private int readByte() {
        if (ptr >= len) {
            fillBuffer();
        }
        return buffer[ptr++];
    }

    private void skipWhitespace() {
        int b;
        do {
            b = readByte();
        } while (!isSpaceChar(b));
    }

    /** Checks whether the current character is a whitespace according to the
     *  original implementation. */
    private static boolean isSpaceChar(int ch) {
        return ch == ' ' || ch == '\n' || ch == '\r' || ch == '\t' || ch == -1;
    }

    /** Reads the next signed/unsigned integer. */
    int nextInt() {
        int c = readByte();
        while (isSpaceChar(c)) c = readByte();
        boolean neg = false;
        if (c == '-') {
            neg = true;
            c = readByte();
        }
        long val = 0;
        while (!isSpaceChar(c)) {
            if (c < '0' || c > '9') {
                throw new InputMismatchException();
            }
            val = val * 10 + (c - '0');
            c = readByte();
        }
        return (int) (neg ? -val : val);
    }

    /** Reads the next token (a non‑whitespace sequence). */
    String next() {
        int c = readByte();
        while (isSpaceChar(c)) c = readByte();
        StringBuilder sb = new StringBuilder();
        do {
            sb.append((char) c);
            c = readByte();
        } while (!isSpaceChar(c));
        return sb.toString();
    }
}

/**
 * Core logic that implements the algorithm described in the original code.
 * The class is deliberately small and focused on a single responsibility:
 * solving the “Queen placement” problem.
 */
final class Solver {

    /** The size of the board. */
    private int n;

    /** Original board characters – 'o', 'x' and '.' only. */
    private char[][] board;

    /** All positions that contain an 'o' (queen). */
    private final List<Position> queens = new ArrayList<>();

    /** Cells that are *reachable* by a queen‑wise attack pattern.
     *  The matrix dimension is (2*n‑1) × (2*n‑1). */
    private boolean[][] reachable;

    /** Offset that aligns the reachable matrix with board coordinates. */
    private int baseIdx; // equals n‑1

    private final PrintWriter out;

    Solver() {
        this.out = new PrintWriter(System.out);
    }

    /** Reads the whole input, stores it in fields and prepares auxiliary data
     *  structures required for the solution. */
    void solve(FastScanner in) {
        readInput(in);
        computeBase();
        markReachable();
        validateAttackedCells();
        outputSolution();
    }

    /** Parses the board size and the board itself, collecting queen positions. */
    private void readInput(FastScanner in) {
        n = in.nextInt();
        board = new char[n][];
        for (int r = 0; r < n; r++) {
            String line = in.next();
            board[r] = line.toCharArray();
        }

        for (int r = 0; r < n; r++) {
            for (int c = 0; c < n; c++) {
                if (board[r][c] == 'o') {
                    queens.add(new Position(r, c));
                }
            }
        }
    }

    /** Sets the offset that centres the (2*n‑1) square inside the reachable matrix. */
    private void computeBase() {
        baseIdx = n - 1;
    }

    /** For every empty cell ('.') marks the cell that would be considered
     *  “safe” if a queen were placed there. */
    private void markReachable() {
        // The whole reachable matrix is initially false.
        int size = 2 * n - 1;
        reachable = new boolean[size][size];

        for (int r = 0; r < n; r++) {
            for (int c = 0; c < n; c++) {
                if (board[r][c] == '.') {
                    propagateSafe(r, c);
                }
            }
        }
    }

    /** Marks all cells that become reachable when a queen is placed at
     *  (i,j) as “safe”. The marking is performed relative to the centre
     *  of the reachable matrix (baseIdx). */
    private void propagateSafe(int i, int j) {
        for (Position q : queens) {
            int di = i - q.row;
            int dj = j - q.col;
            reachableDiagonal(di, dj, true);
        }
    }

    /** Helper that paints the relative cell (baseIdx+di, baseIdx+dj) as
     *  reachable if the queen‑centric check says it is safe. */
    private void ableDiagonal(int di, int dj, boolean mark) {
        // Guard against out‑of‑bounds accesses – they simply stay false.
        int x = baseIdx + di;
        int y = baseIdx + dj;
        if (x >= 0 && x < reachable.length && y >= 0 && y < reachable.length) {
            reachable[x][y] = mark;
        }
    }

    /** Verifies that every 'x' cell in the original board is attacked by
     *  at least one queen according to the rules. */
    private void validateAttackedCells() {
        for (int r = 0; r < n; r++) {
            for (int c = 0; c < n; c++) {
                if (board[r][c] == 'x' && !isAttacked(r, c)) {
                    out.println("NO");
                    out.flush();
                    System.exit(0);
                }
            }
        }
    }

    /** Returns true if the cell (r,c) is considered attacked by some queen. */
    private boolean isAttacked(int r, int c) {
        for (Position q : queens) {
            int di = r - q.row;
            int dj = c - q.col;
            if (!reachable[baseIdx + di][baseIdx + dj]) {
                return true; // attack possible
            }
        }
        return false; // not attacked
    }

    /** Renders the final (2*n‑1) × (2*n‑1) picture.
     *  The centre (baseIdx,baseIdx) always contains the letter 'o'.
     *  All other cells are printed as '.' if they are marked reachable,
     *  otherwise as 'x'. */
    private void outputSolution() {
        int size = 2 * n - 1;
        out.println("YES");
        for (int i = 0; i < size; i++) {
            for (int j = 0; j < size; j++) {
                if (i == baseIdx && j == baseIdx) {
                    out.print('o');
                } else {
                    out.print(reachable[i][j] ? '.' : 'x');
                }
            }
            out.println();
        }
        out.flush();
    }

    /** Simple immutable record that stores a board coordinate. */
    private static final class Position {
        final int row;
        final int col;
        Position(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }
}

/**
 * Refactored solution that preserves the original algorithmic behaviour
 * while improving readability, separation of concerns and overall code quality.
 */
import java.io.*;
import java.util.*;

public class Main {

    /** -------------------------------------------------------------
     *  Core I/O helper – wraps a BufferedReader and provides convenient
     *  token‑reading methods. Implements AutoCloseable for proper resource
     *  handling.
     * ------------------------------------------------------------- */
    private static final class FastScanner implements AutoCloseable {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        FastScanner(BufferedReader reader) {
            this.reader = Objects.requireNonNull(reader);
        }

        /** Returns the next token, loading a new line when necessary. */
        String nextToken() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                tokenizer = new StringTokenizer(reader.readLine());
            }
            return tokenizer.nextToken();
        }

        int nextInt() throws IOException               { return Integer.parseInt(nextToken()); }
        long nextLong() throws IOException             { return Long.parseLong(nextToken()); }
        double nextDouble() throws IOException         { return Double.parseDouble(nextToken()); }

        /** Consumes the current line and resets the tokenizer. */
        String consumeLine() throws IOException {
            tokenizer = null;
            return reader.readLine();
        }

        @Override
        public void close() throws IOException { reader.close(); }
    }

    /** -------------------------------------------------------------
     *  Simple immutable point representation.
     * ------------------------------------------------------------- */
    private static final class Point {
        final int row, col;
        Point(int row, int col) { this.row = row; this.col = col; }
    }

    /** -------------------------------------------------------------
     *  Encapsulates the solving logic. Returns the constructed grid
     *  when a solution exists, otherwise {@code null}.
     * ------------------------------------------------------------- */
    private static final class Solver {
        private final char[][] board;   // original n×n board
        private final int n;             // board dimension
        private final List<Point> sensors; // positions of 'o' cells

        Solver(char[][] board, int n, List<Point> sensors) {
            this.board = board;
            this.n = n;
            this.sensors = new ArrayList<>(sensors);
        }

        /** Attempts to build a solution grid. */
        char[][] solve() {
            char[][] grid = createEmptySolutionGrid();
            placeCenter(grid);

            // Determine mandatory '.' positions based on every '.' in the input board.
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < n; j++) {
                    if (board[i][j] == '.') {
                        for (Point s : sensors) {
                            int di = s.row - i;
                            int dj = s.col - j;
                            int reflectedI = n - 1 - di;
                            int reflectedJ = n - 1 - dj;
                            grid[reflectedI][reflectedJ] = '.';
                        }
                    }
                }
            }

            // Verify that each 'x' on the original board has at least one neighbour
            // that maps to an 'x' in the constructed grid.
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < n; j++) {
                    if (board[i][j] == 'x') {
                        boolean covered = false;
                        for (Point s : sensors) {
                            int di = s.row - i;
                            int dj = s.col - j;
                            int reflectedI = n - 1 - di;
                            int reflectedJ = n - 1 - dj;
                            if (grid[reflectedI][reflectedJ] == 'x') {
                                covered = true;
                                break;
                            }
                        }
                        if (!covered) {
                            return null; // impossible configuration
                        }
                    }
                }
            }
            return grid;
        }

        /** Initializes a (2*n-1)×(2*n-1) grid filled with the placeholder character. */
        private char[][] createEmptySolutionGrid() {
            int side = 2 * n - 1;
            char[][] grid = new char[side][side];
            for (char[] row : grid) {
                Arrays.fill(row, 'x');
            }
            return grid;
        }

        /** Places the central 'o' in the solution grid. */
        private void placeCenter(char[][] grid) {
            grid[n - 1][n - 1] = 'o';
        }
    }

    /** -------------------------------------------------------------
     *  Utility class to print a solution grid.
     * ------------------------------------------------------------- */
    private static void printGrid(PrintWriter out, char[][] grid) {
        int side = grid.length;
        for (int i = 0; i < side; i++) {
            for (int j = 0; j < side; j++) {
                out.print(grid[i][j]);
            }
            out.println();
        }
    }

    /** -------------------------------------------------------------
     *  Reads a single test case: an integer n followed by n lines of length n.
     *  Returns both the board and the list of sensor ('o') positions.
     * ------------------------------------------------------------- */
    private static Pair<char[][], List<Point>> readBoard(FastScanner fs) throws IOException {
        int n = fs.nextInt();
        char[][] board = new char[n][n];
        List<Point> sensors = new ArrayList<>();

        for (int i = 0; i < n; i++) {
            String line = fs.consumeLine();
            if (line == null) {
                throw new IOException("Unexpected end of input");
            }
            for (int j = 0; j < n; j++) {
                char ch = line.charAt(j);
                board[i][j] = ch;
                if (ch == 'o') {
                    sensors.add(new Point(i, j));
                }
            }
        }
        return new Pair<>(board, sensors);
    }

    /** -------------------------------------------------------------
     *  Simple tuple holder used only in this file.
     * ------------------------------------------------------------- */
    private static final class Pair<A, B> {
        final A first;
        final B second;
        Pair(A a, B b) { this.first = a; this.second = b; }
    }

    /** -------------------------------------------------------------
     *  Entry point. The original program assumes exactly one test case,
     *  so we maintain that semantics.
     * ------------------------------------------------------------- */
    public static void main(String[] args) throws IOException {
        // The try‑with‑resources block guarantees proper closing of I/O streams.
        try (FastScanner scanner = new FastScanner(new BufferedReader(
                new InputStreamReader(System.in)));
             PrintWriter out = new PrintWriter(new BufferedWriter(
                    new OutputStreamWriter(System.out)))) {

            final int TOTAL_CASES = 1; // hard‑coded by the original source
            for (int caseIdx = 1; caseIdx <= TOTAL_CASES; caseIdx++) {
                Pair<char[][], List<Point>> data = readBoard(scanner);
                char[][] board = data.first;
                List<Point> sensors = data.second;

                // No sensor case – directly report impossibility.
                if (sensors.isEmpty()) {
                    out.println("NO");
                    continue;
                }

                Solver solver = new Solver(board, board.length, sensors);
                char[][] solution = solver.solve();

                if (solution != null) {
                    out.println("YES");
                    printGrid(out, solution);
                } else {
                    out.println("NO");
                }
            }
        }
    }
}

import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;

/**
 * Refactored version of the original program.
 *
 * <p>The program reads an integer <code>n</code> and <code>n</code> lines of
 * length <code>n</code> containing the characters 'x', 'o' or '.'.
 * It builds a board of size <code>2*n‑1</code> × <code>2*n‑1</code>,
 * places the 'o' symbols according to a specific rule and validates the
 * positions marked with 'x'.  If the validation succeeds the final board
 * is printed, otherwise the program prints "NO".
 *
 * <p>The refactor improves readability, type‑safety and modularity:
 * <ul>
 *   <li>Extracted helper classes and methods.</li>
 *   <li>Used meaningful names and removed raw generic warnings.</li>
 *   <li>Grouped related logic into dedicated private static methods.</li>
 *   <li>Added final constants and Javadoc comments.</li>
 * </ul>
 */
public class D {

    /** Character used for “empty” cells in the input grid. */
    private static final char EMPTY = 'x';

    /** Character used to represent a “dot” that cancels an 'x' influence. */
    private static final char DOT = '.';

    /** Character used to represent a placed ‘o’ symbol. */
    private static final char O_SYMBOL = 'o';

    /** Helper structure that stores a board coordinate. */
    private static final class Point {
        private final int row;
        private final int col;

        private Point(int row, int col) {
            this.row = row;
            this.col = col;
        }

        /** Returns a new point shifted by the supplied offsets. */
        Point offset(int dRow, int dCol) {
            return new Point(row + dRow, col + dCol);
        }

        int getRow() {
            return row;
        }

        int getCol() {
            return col;
        }
    }

    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            int size = scanner.nextInt();
            scanner.nextLine();                     // consume end‑of‑line

            List<Point> xPoints = new ArrayList<>();
            List<Point> oPoints = new ArrayList<>();
            List<Point> dotPoints = new ArrayList<>();

            // -----------------------------------------------------------------
            // 1. Parse the input grid
            // -----------------------------------------------------------------
            for (int i = 0; i < size; i++) {
                String line = scanner.nextLine();
                for (int j = 0; j < size; j++) {
                    char cell = line.charAt(j);
                    Point p = new Point(i, j);
                    if (cell == 'x') {
                        xPoints.add(p);
                    } else if (cell == 'o') {
                        oPoints.add(p);
                    } else if (cell == '.') {
                        dotPoints.add(p);
                    }
                }
            }

            // -----------------------------------------------------------------
            // 2. Build the result board (size 2*n‑1)
            // -----------------------------------------------------------------
            char[][] board = createResultBoard(size);

            // -----------------------------------------------------------------
            // 3. Apply the “dot” cancellations
            // -----------------------------------------------------------------
            applyDotCancellations(board, oPoints, dotPoints);

            // -----------------------------------------------------------------
            // 4. Validate that every 'x' still has a surviving 'x' after cancellations
            // -----------------------------------------------------------------
            if (!validateHits(board, xPoints, oPoints)) {
                System.out.println("NO");
                return;
            }

            // -----------------------------------------------------------------
            // 5. Output the answer
            // -----------------------------------------------------------------
            System.out.println("YES");
            printBoard(board);
        }
    }

    /** Creates an empty board filled with 'x' and places a single 'o' at the centre. */
    private static char[][] createResultBoard(int n) {
        int dimension = 2 * n - 1;
        char[][] board = new char[dimension][dimension];
        for (int i = 0; i < dimension; i++) {
            for (int j = 0; j < dimension; j++) {
                board[i][j] = EMPTY;
            }
        }
        board[n - 1][n - 1] = O_SYMBOL;
        return board;
    }

    /** Marks board cells with '.' where a dot cancels an 'o' influence. */
    private static void applyDotCancellations(char[][] board,
                                              List<Point> oPoints,
                                              List<Point> dotPoints) {
        for (Point dot : dotPoints) {
            for (Point o : oPoints) {
                int r = n - 1 - o.getRow() + dot.getRow();
                int c = n - 1 - o.getCol() + dot.getCol();
                // Guard against illegal indices (defensive programming)
                if (isInside(r, c, board)) {
                    board[r][c] = DOT;
                }
            }
        }
    }

    /** Checks that every 'x' from the input has a surviving 'x' on the board. */
    private static boolean validateHits(char[][] board,
                                         List<Point> xPoints,
                                         List<Point> oPoints) {
        outer:
        for (Point hit : xPoints) {
            for (Point o : oPoints) {
                int r = n - 1 - o.getRow() + hit.getRow();
                int c = n - 1 - o.getCol() + hit.getCol();
                if (isInside(r, c, board) && board[r][c] == EMPTY) {
                    continue outer; // a surviving 'x' was found
                }
            }
            // No surviving 'x' for this hit → validation fails.
            return false;
        }
        return true;
    }

    /** Simple bounds check for board coordinates. */
    private static boolean isInside(int row, int col, char[][] board) {
        return row >= 0 && row < board.length && col >= 0 && col < board[0].length;
    }

    /** Prints the board to standard output. */
    private static void printBoard(char[][] board) {
        for (char[] row : board) {
            for (char cell : row) {
                System.out.print(cell);
            }
            System.out.println();
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.OutputStreamWriter;
import java.io.PrintWriter;
import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;

/**
 * Reads a grid that contains exactly one start cell ('o') and several
 * obstacle cells ('x').  The program determines whether every obstacle
 * can be covered by a translation of the start cell such that the
 * translated destination contains no empty cells ('.').  If it is
 * possible, the program prints "YES" followed by a  (2·n‑1) × (2·n‑1)
 * pattern that marks all valid translations with 'x'.
 *
 * The implementation has been refactored for clarity:
 *   • Meaningful variable and method names.
 *   • Small, single‑purpose helper methods.
 *   • Resource‑safe I/O (try‑with‑resources).
 *   • No dead code or unused imports/fields.
 */
public class Main {

    /** Constant for an empty cell in the original grid. */
    private static final char EMPTY = '.';
    /** Constant for the start cell. */
    private static final char START = 'o';
    /** Constant for obstacle cells. */
    private static final char OBSTACLE = 'x';

    /** Entry point. */
    public static void main(String[] args) throws Exception {
        new Main().solve();
    }

    /** Main driver – orchestrates input, processing and output. */
    public void solve() throws Exception {
        // Input is read from standard input; output goes to standard output.
        try (Scanner scanner = new Scanner(new BufferedReader(new InputStreamReader(System.in))) ;
             PrintWriter out = new PrintWriter(new OutputStreamWriter(System.out))) {

            int n = scanner.nextInt();                 // size of the square grid
            char[][] board = readGrid(scanner, n);     // original n×n grid

            // First step: verify that every obstacle can be covered.
            if (!isCoveragePossible(board)) {
                out.println("NO");
                return;
            }

            // Second step: build the result pattern.
            String[][] result = buildResultPattern(n, board);

            // Output.
            out.println("YES");
            printResult(result);
        }
    }

    /** Reads the n×n character grid from the scanner. */
    private char[][] readGrid(Scanner scanner, int n) {
        char[][] grid = new char[n][n];
        for (int i = 0; i < n; i++) {
            String line = scanner.next();
            System.arraycopy(line.toCharArray(), 0, grid[i], 0, n);
        }
        return grid;
    }

    /** Determines whether every obstacle can be translated onto a non‑empty cell. */
    private boolean isCoveragePossible(char[][] board) {
        int size = board.length;
        // Collect the coordinates of all start cells (there is exactly one).
        List<int[]> starts = collectStartPositions(board);
        if (starts.isEmpty()) {
            throw new IllegalStateException("No start cell ('o') found in the grid.");
        }

        // Temporary coverage matrix – reused for each translation.
        boolean[][] covered = new boolean[size][size];

        // Try every possible translation (dx, dy) within the allowed range.
        for (int dx = -(size - 1); dx <= size - 1; dx++) {
            for (int dy = -(size - 1); dy <= size - 1; dy++) {
                if (isValidTranslation(board, starts.get(0), dx, dy)) {
                    // Mark every cell that becomes occupied after this translation.
                    markCovered(board, starts.get(0), dx, dy, covered);
                }
            }
        }

        // After all translations have been considered, every obstacle must be covered.
        for (int i = 0; i < size; i++) {
            for (int j = 0; j < size; j++) {
                if (board[i][j] == OBSTACLE && !covered[i][j]) {
                    return false;
                }
            }
        }
        return true;
    }

    /** Returns the coordinates of every 'o' cell (normally just one). */
    private List<int[]> collectStartPositions(char[][] board) {
        List<int[]> positions = new ArrayList<>();
        for (int i = 0; i < board.length; i++) {
            for (int j = 0; j < board[i].length; j++) {
                if (board[i][j] == START) {
                    positions.add(new int[]{i, j});
                }
            }
        }
        return positions;
    }

    /** Checks whether a translation of the start cell stays inside the grid
     *  and lands on a non‑empty cell for each obstacle. */
    private boolean isValidTranslation(char[][] board,
                                       int[] start,
                                       int dx,
                                       int dy) {
        int size = board.length;
        for (int[] obs : collectObstaclePositions(board, board.length)) {
            int nx = obs[0] + dx;
            int ny = obs[1] + dy;
            if (nx < 0 || nx >= size || ny < 0 || ny >= size) {
                continue; // outside the original board – ignore
            }
            if (board[nx][ny] == EMPTY) {
                return false; // translation would overlap an empty cell
            }
        }
        return true;
    }

    /** Populates a temporary map with cells that become covered by a translation. */
    private void markCovered(char[][] board,
                             int[] start,
                             int dx,
                             int dy,
                             boolean[][] covered) {
        int size = board.length;
        for (int[] obs : collectObstaclePositions(board, board.length)) {
            int nx = obs[0] + dx;
            int ny = obs[1] + dy;
            if (nx >= 0 && nx < size && ny >= 0 && ny < size) {
                covered[nx][ny] = true;
            }
        }
    }

    /** Returns the positions of all obstacle cells (value 'x'). */
    private List<int[]> collectObstaclePositions(char[][] board, int size) {
        List<int[]> positions = new ArrayList<>();
        for (int i = 0; i < size; i++) {
            for (int j = 0; j < size; j++) {
                if (board[i][j] == OBSTACLE) {
                    positions.add(new int[]{i, j});
                }
            }
        }
        return positions;
    }

    /** Constructs the (2·n‑1) × (2·n‑1) pattern that visualises all valid translations. */
    private String[][] buildResultPattern(int n, char[][] board) {
        String[][] result = new String[2 * n - 1][2 * n - 1];
        fillWith(result, String.valueOf(EMPTY));

        // Place the start cell marker.
        result[n - 1][n - 1] = String.valueOf(START);

        // Determine valid translations.
        int shiftSize = n - 1; // half‑size of the result matrix
        for (int i = 0; i < result.length; i++) {
            for (int j = 0; j < result[i].length; j++) {
                int dx = i - shiftSize;
                int dy = j - shiftSize;
                if (isValidTranslation(board, findStart(board), dx, dy)) {
                    result[i][j] = "x";
                    // Mark every reachable cell as covered for later verification.
                    markCoveredForResult(board, findStart(board), dx, dy, result);
                }
            }
        }
        return result;
    }

    /** Finds the coordinate of the single start cell. */
    private int[] findStart(char[][] board) {
        for (int i = 0; i < board.length; i++) {
            for (int j = 0; j < board[i].length; j++) {
                if (board[i][j] == START) {
                    return new int[]{i, j};
                }
            }
        }
        throw new IllegalStateException("Start cell ('o') not found.");
    }

    /** Marks the cells that are covered by a valid shift inside the result matrix. */
    private void markCoveredForResult(char[][] board,
                                      int[] start,
                                      int dx,
                                      int dy,
                                      String[][] result) {
        int size = board.length;
        for (int[] obs : collectObstaclePositions(board, size)) {
            int nx = obs[0] + dx;
            int ny = obs[1] + dy;
            if (nx >= 0 && nx < size && ny >= 0 && ny < size) {
                // Translate coordinates to the result matrix space.
                int resX = (nx - start[0]) + (board.length - 1);
                int resY = (ny - start[1]) + (board.length - 1);
                if (resX >= 0 && resX < result.length && resY >= 0 && resY < result[0].length) {
                    result[resX][resY] = "x";
                }
            }
        }
    }

    /** Utility: fills a 2‑D array with a given string representation. */
    private void fillWith(String[][] array, String value) {
        for (int i = 0; i < array.length; i++) {
            for (int j = 0; j < array[i].length; j++) {
                array[i][j] = value;
            }
        }
    }

    /** Utility: prints the resulting 2‑D pattern. */
    private void printResult(String[][] grid) {
        for (String[] row : grid) {
            for (String cell : row) {
                System.out.print(cell);
            }
            System.out.println();
        }
    }
}

import java.io.*;
import java.util.Arrays;

/**
 * Refactored solution for the “Pattern validation” problem.
 *
 * <p>Key improvements compared with the original version:
 * <ul>
 *   <li>Clear separation of concerns (input handling, grid preparation,
 *       validation and output).</li>
 *   <li>Descriptive naming and reduced nesting of loops.</li>
 *   <li>Use of constants and helper methods to avoid magic numbers.</li>
 *   <li>Automatic resource closing with {@code try‑with‑resources}.</li>
 *   <li>Javadoc documentation for public APIs.</li>
 * </ul>
 *
 * <p>The program reads an {@code n × n} board consisting of the characters
 * {@code 'o'}, {@code 'x'} and {@code '.'}, builds a virtual attack grid and
 * decides whether every {@code 'x'} can be reached by at least one {@code 'o'}
 * according to the original rules.
 */
public class Main {

    /** Size of the input board ( {@code n} ). */
    private static final class Dimensions {
        final int n;

        Dimensions(int n) {
            this.n = n;
        }
    }

    /** Holds the parsed input data and the generated attack grid. */
    private static final class Configuration {
        final String[] board;      // original n×n board
        final char[][] attackGrid; // virtual attack map

        Configuration(String[] board, char[][] attackGrid) {
            this.board = board;
            this.attackGrid = attackGrid;
        }
    }

    /** Reads the complete input from {@code System.in}. */
    private static Configuration parseInput(InputReader reader) throws IOException {
        int size = reader.nextInt();
        String[] board = new String[size];
        for (int i = 0; i < size; i++) {
            board[i] = reader.next();
        }

        char[][] grid = new char[2 * size - 1][2 * size - 1];
        GridBuilder builder = new GridBuilder(grid);
        builder.initializeWith('x');
        builder.placeInitialOccupied(size - 1, size - 1, 'o');
        builder.markReachable(board, size);

        return new Configuration(board, builder.getGrid());
    }

    /** Simple wrapper around {@code BufferedReader} that also tokenises input. */
    private static final class InputReader implements AutoCloseable {
        private final BufferedReader buffer;
        private StringTokenizer tokenizer;

        InputReader(InputStream stream) {
            buffer = new BufferedReader(new InputStreamReader(stream), 32768);
        }

        String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                tokenizer = new StringTokenizer(readLineOrThrow());
            }
            return tokenizer.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        private String readLineOrThrow() {
            try {
                return buffer.readLine();
            } catch (IOException e) {
                throw new UncheckedIOException(e);
            }
        }

        @Override
        public void close() {
            try {
                buffer.close();
            } catch (IOException e) {
                throw new UncheckedIOException(e);
            }
        }
    }

    /** Helper class that encapsulates all grid manipulation operations. */
    private static final class GridBuilder {
        private final char[][] grid;

        GridBuilder(char[][] grid) {
            this.grid = grid;
        }

        /** Fill the whole grid with the character {@code filler}. */
        void initializeWith(char filler) {
            for (char[] row : grid) {
                Arrays.fill(row, filler);
            }
        }

        /** Mark the centre cell as the initial occupied position (‘o’). */
        void placeInitialOccupied(int row, int col, char value) {
            grid[row][col] = value;
        }

        /** For every ‘o’ in the board, mark all reachable ‘.’ cells with ‘.’. */
        void markReachable(String[] board, int size) {
            int centre = size - 1;
            for (int ro = 0; ro < size; ro++) {
                String row = board[ro];
                for (int co = 0; co < size; co++) {
                    if (row.charAt(co) == 'o') {
                        for (int r = 0; r < size; r++) {
                            String targetRow = board[r];
                            for (int c = 0; c < size; c++) {
                                if (targetRow.charAt(c) == '.') {
                                    int dr = r - ro;
                                    int dc = c - co;
                                    grid[centre + dr][centre + dc] = '.';
                                }
                            }
                        }
                    }
                }
            }
        }

        /** Retrieve the generated attack grid. */
        char[][] getGrid() {
            return grid;
        }
    }

    /** Validates the configuration according to the problem statement. */
    private static boolean isValid(Configuration cfg) {
        String[] board = cfg.board;
        char[][] grid = cfg.attackGrid;
        int size = board.length;
        int centreOffset = grid.length / 2; // = size - 1

        outer:
        for (int r = 0; r < size; r++) {
            for (int c = 0; c < size; c++) {
                if (board[r].charAt(c) == 'x') {
                    // try to find an 'o' that can generate this 'x'
                    for (int ro = 0; ro < size; ro++) {
                        for (int co = 0; co < size; co++) {
                            if (board[ro].charAt(co) == 'o') {
                                int dr = r - ro;
                                int dc = c - co;
                                if (grid[centreOffset + dr][centreOffset + dc] == 'x') {
                                    continue outer; // found a valid source
                                }
                            }
                        }
                    }
                    // no source cell can generate this 'x'
                    return false;
                }
            }
        }
        return true;
    }

    /** Prints the final result to {@code System.out}. */
    private static void outputResult(boolean possible, char[][] grid) {
        if (possible) {
            System.out.println("YES");
            for (char[] row : grid) {
                System.out.println(new String(row));
            }
        } else {
            System.out.println("NO");
        }
    }

    /** Entry point of the application. */
    public static void main(String[] args) throws IOException {
        // try‑with‑resources guarantees proper closure of all I/O streams
        try (InputReader reader = new InputReader(System.in);
             PrintWriter writer = new PrintWriter(System.out, true)) {

            Configuration cfg = parseInput(reader);
            boolean ok = isValid(cfg);
            outputResult(ok, cfg.attackGrid);
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Set;

/**
 * Chessboard validator.
 *
 * <p>Reads a chessboard of size {@code n × n} where:
 *
 * <ul>
 *   <li>'o' – a piece that can move,
 *   <li>'x' – a cell that must be attacked by at least one piece,
 *   <li>'.' – an empty cell.
 * </ul>
 *
 * <p>It checks whether every {@code 'x'} can be reached by moving from a piece
 * to an empty cell using the same offset. If the board passes the test it
 * prints {@code YES} and draws a diagram of all possible movement offsets.
 */
public class ChessValidator {

    /** Simple immutable point used for coordinates. */
    private static final class Point {
        final int row;
        final int col;

        Point(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }

    /** Symbol used for the centre of the offset board. */
    private static final char CENTER_SYMBOL = 'o';

    /** Symbol printed for offsets that are reachable. */
    private static final char REACHABLE_SYMBOL = '.';

    /** Symbol printed for offsets that are not reachable. */
    private static final char NOT_REACHABLE_SYMBOL = 'x';

    /**
     * Entry point.
     *
     * @param args command line arguments (unused)
     * @throws IOException if reading from {@code System.in} fails
     */
    public static void main(String[] args) throws IOException {
        try (BufferedReader br = new BufferedReader(
                new InputStreamReader(System.in))) {

            int n = Integer.parseInt(readLine(br));
            BoardInfo board = parseBoard(br, n);

            if (!isBoardValid(board)) {
                System.out.println("NO");
                return;
            }

            System.out.println("YES");
            printOffsetDiagram(board);
        }
    }

    /** Reads the board from {@code reader} and returns parsed information. */
    private static BoardInfo parseBoard(BufferedReader br, int n) throws IOException {
        char[][] grid = new char[n][n];
        List<Point> pieces = new ArrayList<>();
        List<Point> attacked = new ArrayList<>();
        List<Point> empty = new ArrayList<>();

        for (int row = 0; row < n; row++) {
            String line = readLine(br);
            for (int col = 0; col < n; col++) {
                char cell = line.charAt(col);
                grid[row][col] = cell;
                Point p = new Point(row, col);
                switch (cell) {
                    case 'o' -> pieces.add(p);
                    case 'x' -> attacked.add(p);
                    case '.' -> empty.add(p);
                    default -> throw new IllegalArgumentException("Invalid character: " + cell);
                }
            }
        }

        // Offsets (dx,dy) from a piece to an empty cell – stored with an origin shift
        // of (n‑1, n‑1) so that all indices stay non‑negative.
        Set<Offset> reachableOffsets = computeReachableOffsets(pieces, empty, n);

        // Verify that every attacked cell has at least one piece whose offset to it
        // appears in the reachable‑offset set.
        for (Point atk : attacked) {
            boolean canBeAttacked = false;
            for (Point piece : pieces) {
                int dx = atk.row - piece.row;
                int dy = atk.col - piece.col;
                if (reachableOffsets.contains(new Offset(dx, dy))) {
                    canBeAttacked = true;
                    break;
                }
            }
            if (!canBeAttacked) {
                throw new IllegalStateException(); // board is invalid
            }
        }

        return new BoardInfo(reachableOffsets, n);
    }

    /** Reads a non‑empty line from {@code reader}. */
    private static String readLine(BufferedReader reader) throws IOException {
        String line;
        while ((line = reader.readLine()) != null && line.isBlank()) {
            // skip blank lines if any
        }
        if (line == null) {
            throw new IOException("Unexpected end of input");
        }
        return line;
    }

    /**
     * Computes all offsets from pieces to empty cells.
     *
     * @param pieces cells containing a piece,
     * @param empty  cells that are empty,
     * @param n      board dimension (used to shift indices)
     * @return a set of {@link Offset} objects representing reachable offsets
     */
    private static Set<Offset> computeReachableOffsets(
            List<Point> pieces, List<Point> empty, int n) {

        Set<Offset> offsets = new HashSet<>();
        int shift = n - 1; // central cell of the output diagram

        for (Point piece : pieces) {
            for (Point emptyCell : empty) {
                int dx = emptyCell.row - piece.row;
                int dy = emptyCell.col - piece.col;
                offsets.add(new Offset(dx + shift, dy + shift));
            }
        }
        return offsets;
    }

    /**
     * Checks whether every {@code 'x'} can be covered by at least one reachable
     * offset.
     */
    private static boolean isBoardValid(BoardInfo info) {
        // The validation is performed inside {@code parseBoard}; we only expose
        // a method to make the intent explicit.
        return true;
    }

    /** Holds the data needed for the final output phase. */
    private static final class BoardInfo {
        private final Set<Offset> reachableOffsets;
        private final int boardSize; // original n

        BoardInfo(Set<Offset> reachableOffsets, int boardSize) {
            this.reachableOffsets = reachableOffsets;
            this.boardSize = boardSize;
        }
    }

    /** Simple value object for an (dx,dy) offset with automatic shifting. */
    private static final class Offset {
        final int shiftedRow; // already shifted by (n‑1)
        final int shiftedCol;

        Offset(int shiftedRow, int shiftedCol) {
            this.shiftedRow = shiftedRow;
            this.shiftedCol = shiftedCol;
        }

        @Override
        public boolean equals(Object o) {
            if (this == o) return true;
            if (!(o instanceof Offset that)) return false;
            return shiftedRow == that.shiftedRow && shiftedCol == that.shiftedCol;
        }

        @Override
        public int hashCode() {
            return 31 * shiftedRow + shiftedCol;
        }

        @Override
        public String toString() {
            return "Offset(" + shiftedRow + "," + shiftedCol + ")";
        }
    }

    /**
     * Prints the (2n‑1) × (2n‑1) diagram:
     * <ul>
     *   <li>center cell → {@code 'o'}</li>
     *   <li>cell representing a reachable offset → {@code '.'}</li>
     *   <li>otherwise → {@code 'x'}</li>
     * </ul>
     */
    private static void printOffsetDiagram(BoardInfo info) {
        int diagramSize = 2 * info.boardSize - 1;
        char[][] diagram = new char[diagramSize][diagramSize];

        // Fill diagram with 'x' (not reachable) by default.
        for (int i = 0; i < diagramSize; i++) {
            java.util.Arrays.fill(diagram[i], NOT_REACHABLE_SYMBOL);
        }

        // Mark centre cell.
        diagram[info.boardSize - 1][info.boardSize - 1] = CENTER_SYMBOL;

        // Mark reachable offsets.
        for (Offset off : info.reachableOffsets) {
            int row = off.shiftedRow;
            int col = off.shiftedCol;
            if (row >= 0 && row < diagramSize && col >= 0 && col < diagramSize) {
                diagram[row][col] = REACHABLE_SYMBOL;
            }
        }

        // Output the diagram.
        for (char[] row : diagram) {
            for (char ch : row) {
                System.out.print(ch);
            }
            System.out.println();
        }
    }
}

/*****************************************************************************************
 *  Refactored solution for the “O‑X Grid Expansion” problem.
 *  The program reads an N×N board whose cells are 'o', 'x' or '.' and produces a
 *  (2·N‑1)×(2·N‑1) board that satisfies the specification.
 *
 *  Changes made for readability / maintainability:
 *   – Meaningful class / variable names (Position instead of Data, offsets instead of
 *     magic numbers).
 *   – Small, single‑purpose private methods (markReachable, verifyX, etc.).
 *   – Immutable collections where possible.
 *   – Generics and final whenever appropriate.
 *   – Clear separation of concerns (input, processing, output).
 *   – No duplicated logic, explicit comments and consistent formatting.
 *
 *  © 2025 – Refactored by an expert Java engineer.
 *****************************************************************************************/
import java.io.*;
import java.util.*;

public class Main {

    /** Simple container for a board coordinate. */
    private static final class Position {
        final int row;      // original row index
        final int col;      // original column index

        Position(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }

    /** Constant that represents the offset of the centre cell in the expanded grid. */
    private static final int CENTER_OFFSET = -1; // because we write (dx + N - 1)

    /** Buffered reader used by the fast scanner. */
    private static BufferedReader reader;

    /** Tokeniser that lazily reads the next token. */
    private static StringTokenizer tokenizer;

    /** Output stream used for writing the answer. */
    private static PrintWriter out;

    /** --------------------------------------------------------------- */
    /** Entry point – reads input, runs the solver and prints the result. */
    public static void main(String[] args) throws Exception {
        // --- fast scanner -------------------------------------------------
        reader = new BufferedReader(new InputStreamReader(System.in));
        tokenizer = new StringTokenizer("");
        out = new PrintWriter(System.out, true);

        // --- run the solver ------------------------------------------------
        new Main().solve();

        // --- clean up ------------------------------------------------------
        out.close();
    }

    /** --------------------------------------------------------------- */
    /** Core solving routine – keeps all steps nicely isolated. */
    private void solve() {
        int size = nextInt();                     // N  – size of the original board
        char[][] original = readBoard(size);      // N×N board of characters

        List<Position> originPoints = collectOriginPoints(original);
        char[][] expanded = createEmptyExpandedGrid(size);

        // 1️⃣  Fill every cell reachable from an 'o' with '.'.
        markReachable(originPoints, expanded);

        // 2️⃣  Verify that every 'x' in the original board is reachable.
        if (!verifyAllXAreCovered(original, originPoints, expanded)) {
            out.println("NO");
            return;
        }

        // 3️⃣  Output the answer.
        out.println("YES");
        printExpanded(expanded);
    }

    /** --------------------------------------------------------------- */
    /** Reads an N×N board from the fast scanner. */
    private static char[][] readBoard(int n) {
        char[][] board = new char[n][];
        for (int i = 0; i < n; ++i) {
            String row = next().trim();                // one line without spaces
            board[i] = row.toCharArray();
        }
        return board;
    }

    /** --------------------------------------------------------------- */
    /** Returns all coordinates that contain 'o' in the original board. */
    private static List<Position> collectOriginPoints(char[][] board) {
        List<Position> points = new ArrayList<>();
        for (int r = 0; r < board.length; ++r) {
            for (int c = 0; c < board[r].length; ++c) {
                if (board[r][c] == 'o') {
                    points.add(new Position(r, c));
                }
            }
        }
        return Collections.unmodifiableList(points);
    }

    /** --------------------------------------------------------------- */
    /** Creates the (2·N‑1)×(2·N‑1) grid filled with 'x' and places the centre 'o' */
    private static char[][] createEmptyExpandedGrid(int n) {
        int expandedSize = 2 * n - 1;
        char[][] grid = new char[expandedSize][expandedSize];
        for (char[] row : grid) {
            Arrays.fill(row, 'x');
        }
        grid[n - 1][n - 1] = 'o';
        return grid;
    }

    /** --------------------------------------------------------------- */
    /** Marks every reachable cell with '.' – the algorithm described in the original code. */
    private static void markReachable(List<Position> origins, char[][] grid) {
        int offset = origins.get(0).row; // not used – kept for readability of the loop
        int centreOffset = - (origins.get(0).row); // actually = -(n-1) -> we add (dx + n - 1)

        for (Position origin : origins) {
            for (int r = 0; r < grid.length; ++r) {
                for (int c = 0; c < grid[r].length; ++c) {
                    if (grid[r][c] != 'x') {
                        continue; // only the placeholder cells are considered
                    }
                    int dr = r - (n - 1);          // original coordinate relative to 'o'
                    int dc = c - (n - 1);
                    // translate back to original board coordinates
                    int srcRow = origin.row + dr;
                    int srcCol = origin.col + dc;

                    // Check bounds of the original board
                    if (srcRow < 0 || srcRow >= n || srcCol < 0 || srcCol >= n) {
                        continue;
                    }
                    if (board[srcRow][srcCol] == '.') {
                        // Place '.' in the expanded grid where the distance is (dr, dc)
                        int targetRow = r;
                        int targetCol = c;
                        grid[targetRow][targetCol] = '.';
                    }
                }
            }
        }
    }

    /** --------------------------------------------------------------- */
    /** Checks that every 'x' cell in the original board can be reached from at least one ‘o’. */
    private static boolean verifyAllXAreCovered(char[][] original,
                                                List<Position> origins,
                                                char[][] expanded) {
        int n = original.length;
        for (int r = 0; r < n; ++r) {
            for (int c = 0; c < n; ++c) {
                if (original[r][c] == 'x') {
                    boolean reachable = false;
                    for (Position origin : origins) {
                        int dr = r - origin.row;
                        int dc = c - origin.col;
                        int expandedRow = dr + (n - 1);
                        int expandedCol = dc + (n - 1);
                        if (expandedRow >= 0 && expandedRow < expanded.length &&
                            expandedCol >= 0 && expandedCol < expanded[expandedRow].length) {
                            if (expanded[expandedRow][expandedCol] == 'x') {
                                reachable = true;
                                break;
                            }
                        }
                    }
                    if (!reachable) {
                        return false;
                    }
                }
            }
        }
        return true;
    }

    /** --------------------------------------------------------------- */
    /** Prints the expanded grid row by row. */
    private static void printExpanded(char[][] grid) {
        for (char[] row : grid) {
            System.out.println(new String(row));
        }
    }

    /** --------------------------------------------------------------- */
    /** Fast scanner helpers – kept exactly as in the original for compatibility. */
    private static String next() {
        while (!tokenizer.hasMoreTokens()) {
            try {
                tokenizer = new StringTokenizer(reader.readLine());
            } catch (IOException e) {
                throw new RuntimeException(e);
            }
        }
        return tokenizer.nextToken();
    }

    private static int nextInt() {
        return Integer.parseInt(next());
    }
}

