/**
 * Core logic that:
 *   1. reads the input,
 *   2. determines which displacement vectors are blocked,
 *   3. marks all cells that are attacked,
 *   4. validates the required condition and prints either “NO” or the resulting pattern.
 */
class Solver {

    /** Size of the original board (N × N). */
    private final int boardSize;

    /** Board contents – ‘o’ marks a piece, ‘x’ marks a cell that must be attacked. */
    private final char[][] board;

    /** Number of distinct displacement vectors = 2·N‑1. */
    private final int vectorGridSize;

    /** Displacement vector matrix; true = vector is *not* blocked by an ‘o’. */
    private final boolean[][] displacementMask;

    /** Marks cells that are actually attacked (according to the rules). */
    private final boolean[][] attacked;

    public Solver(FastScanner input) {
        // ----- read input -------------------------------------------------
        this.boardSize = input.nextInt();
        this.vectorGridSize = 2 * this.boardSize - 1;
        this.board = readBoard(input);
        // start with all vectors considered usable
        this.displacementMask = new boolean[vectorGridSize][vectorGridSize];
        for (boolean[] row : displacementMask) {
            Arrays.fill(row, true);
        }

        // ----- compute blocked displacement vectors ----------------------
        computeBlockedDisplacements();

        // ----- mark all cells that are forced to be attacked -------------
        this.attacked = new boolean[boardSize][boardSize];
        markAttackedCells();

        // ----- validation --------------------------------------------------
        validateInput();

        // ----- output ------------------------------------------------------
        printResult();
    }

    /** Reads the N×N board from the scanner. */
    private char[][] readBoard(FastScanner in) {
        char[][] result = new char[boardSize][boardSize];
        for (int r = 0; r < boardSize; r++) {
            String line = in.next();
            result[r] = line.toCharArray();
        }
        return result;
    }

    /** Paints the displacement mask: a displacement is false if it lands on an empty cell ('.'). */
    private void computeBlockedDisplacements() {
        final int radius = boardSize - 1; // K from original code
        for (int r = 0; r < boardSize; r++) {
            for (int c = 0; c < boardSize; c++) {
                if (board[r][c] == 'o') {
                    for (int dr = -radius; dr <= radius; dr++) {
                        for (int dc = -radius; dc <= radius; dc++) {
                            int nr = r + dr;
                            int nc = c + dc;
                            if (isInside(nr, nc)) {
                                // If the target cell was originally empty, the vector cannot be used.
                                if (board[nr][nc] == '.') {
                                    int idxDr = dr + radius;
                                    int idxDc = dc + radius;
                                    displacementMask[idxDr][idxDc] = false;
                                }
                            }
                        }
                    }
                }
            }
        }
    }

    /** Marks all cells that must be attacked according to usable displacement vectors. */
    private void markAttackedCells() {
        final int radius = boardSize - 1;
        for (int r = 0; r < boardSize; r++) {
            for (int c = 0; c < boardSize; c++) {
                if (board[r][c] == 'o') {
                    for (int dr = -radius; dr <= radius; dr++) {
                        for (int dc = -radius; dc <= radius; dc++) {
                            if (!displacementMask[dr + radius][dc + radius]) {
                                continue; // blocked vector – skip
                            }
                            int nr = r + dr;
                            int nc = c + dc;
                            if (isInside(nr, nc)) {
                                attacked[nr][nc] = true;
                            }
                        }
                    }
                }
            }
        }
    }

    /** Checks that every ‘x’ cell is attacked and prints “NO” if not. */
    private void validateInput() {
        for (int r = 0; r < boardSize; r++) {
            for (int c = 0; c < boardSize; c++) {
                if (board[r][c] == 'x' && !attacked[r][c]) {
                    System.out.println("NO");
                    System.exit(0);
                }
            }
        }
        System.out.println("YES");
        printDisplacementGrid();
    }

    /** Prints the M×M grid that describes usable displacement vectors. */
    private void printDisplacementGrid() {
        final int radius = boardSize - 1;
        for (int i = 0; i < vectorGridSize; i++) {
            StringBuilder sb = new StringBuilder();
            for (int j = 0; j < vectorGridSize; j++) {
                if (i == radius && j == radius) {
                    sb.append('o');
                } else {
                    sb.append(displacementMask[i][j] ? 'x' : '.');
                }
            }
            System.out.println(sb);
        }
    }

    /** Simple range check. */
    private boolean isInside(int r, int c) {
        return 0 <= r && r < boardSize && 0 <= c && c < boardSize;
    }
}

/**
 * Fast scanner – unchanged from the original submission but kept for completeness.
 */
class FastScanner {
    private final InputStream stream;
    private final byte[] buffer = new byte[1024];
    private int cursor = 0;
    private int size = 0;

    public FastScanner() {
        this.stream = System.in;
    }

    private int read() throws IOException {
        if (size == -1) throw new java.io.InputMismatchException();
        if (cursor >= size) {
            cursor = 0;
            size = stream.read(buffer);
            if (size <= 0) return -1;
        }
        return buffer[cursor++];
    }

    private boolean isSpace(int ch) {
        return ch == ' ' || ch == '\n' || ch == '\r' || ch == '\t' || ch == -1;
    }

    private boolean isEndline(int ch) {
        return ch == '\n' || ch == '\r' || ch == -1;
    }

    String next() {
        int c = read();
        while (isSpace(c)) c = read();
        StringBuilder sb = new StringBuilder();
        do {
            sb.appendCodePoint(c);
            c = read();
        } while (!isSpace(c));
        return sb.toString();
    }

    int nextInt() {
        return Integer.parseInt(next());
    }

    long nextLong() {
        return Long.parseLong(next());
    }

    double nextDouble() {
        return Double.parseDouble(next());
    }

    String nextLine() {
        int c = read();
        while (isEndline(c)) c = read();
        StringBuilder sb = new StringBuilder();
        do {
            sb.appendCodePoint(c);
            c = read();
        } while (!isEndline(c));
        return sb.toString();
    }
}

package main;

import java.io.IOException;
import java.io.InputStreamReader;
import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;
import java.util.stream.Collectors;

/**
 * Reads an {@code n × n} board consisting of ‘x’, ‘o’ and ‘.’.
 * It tries to place a “focus” marker such that every obstacle (value 1) can be
 * reached by moving diagonally from at least one focus marker.
 *
 * The program prints <code>YES</code> together with the derived (2n‑1)×(2n‑1)
 * pattern, or <code>NO</code> if the condition is not satisfied.
 */
public final class Main {

    /** Size of the original square board (n). */
    private static final int BOARD_SIZE = 0; /* placeholder – filled at runtime */

    /** Internal representation of a cell in the pattern. */
    private enum Cell {
        EMPTY('.'),
        OBSTACLE('x'),
        FOCUS('o');

        private final char symbol;

        Cell(char symbol) {
            this.symbol = symbol;
        }

        public char symbol() {
            return symbol;
        }
    }

    /** Simple immutable point used for focus coordinates. */
    private record Point(int x, int y) {
        /** Shift point by (dx,dy). */
        Point shift(int dx, int dy) {
            return new Point(x + dx, y + dy);
        }
    }

    /** Entry point of the program. */
    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(new InputStreamReader(System.in))) {
            runGame(scanner);
        }
    }

    /** Main orchestration – reads input, builds the result and prints it. */
    private static void runGame(Scanner scanner) {
        int n = readBoardSize(scanner);
        Cell[][] original = readBoard(scanner, n);

        Cell[][] pattern = buildPattern(n, original);
        if (isInvalid(pattern, original)) {
            System.out.println("NO");
            return;
        }

        System.out.println("YES");
        printPattern(pattern);
    }

    /** Reads the first line containing the board dimension {@code n}. */
    private static int readBoardSize(Scanner scanner) {
        int n = scanner.nextInt();
        BOARD_SIZE = n;
        return n;
    }

    /**
     * Parses the {@code n × n} board.
     *
     * @param scanner scanner positioned after the size line
     * @param n       board dimension
     * @return 2‑dimensional {@link Cell} array representing the board
     */
    private static Cell[][] readBoard(Scanner scanner, int n) {
        Cell[][] board = new Cell[n][n];

        for (int i = 0; i < n; i++) {
            String line = scanner.next();
            for (int j = 0; j < n; j++) {
                board[i][j] = fromChar(line.charAt(j));
            }
        }
        return board;
    }

    /** Converts a character to the corresponding {@link Cell}. */
    private static Cell fromChar(char c) {
        return switch (c) {
            case 'x' -> Cell.OBSTACLE;
            case 'o' -> Cell.FOCUS;
            case '.' -> Cell.EMPTY;
            default -> throw new IllegalArgumentException("Unexpected character: " + c);
        };
    }

    /**
     * Creates a fresh (2n‑1)×(2n‑1) grid filled with {@link Cell#EMPTY}
     * and places the source focus at the centre.
     *
     * @param n board size
     * @return the prepared pattern grid
     */
    private static Cell[][] buildEmptyPattern(int n) {
        int dim = 2 * n - 1;
        Cell[][] pattern = new Cell[dim][dim];
        for (Cell[] row : pattern) {
            for (int col = 0; col < dim; col++) {
                row[col] = Cell.EMPTY;
            }
        }

        int centre = n - 1;
        pattern[centre][centre] = Cell.FOCUS;
        return pattern;
    }

    /**
     * Fills the pattern with {@link Cell#EMPTY} ('.') wherever a diagonal
     * displacement from any focus reaches the cell and the original board
     * contains a non‑obstacle at that position.
     *
     * @param n               board size
     * @param original        original board
     * @param pattern         pattern that will be mutated in‑place
     * @param focusPoints     coordinates of all focus markers in {@code original}
     */
    private static void fillPattern(
            int n,
            Cell[][] original,
            Cell[][] pattern,
            List<Point> focusPoints) {

        int centre = n - 1;
        int dim = 2 * n - 1;

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (original[i][j] == Cell.EMPTY) {
                    for (Point focus : focusPoints) {
                        int dx = i - focus.x();
                        int dy = j - focus.y();
                        int destX = centre + dx;
                        int destY = centre + dy;

                        // Guard against out‑of‑bounds destinations (should never happen)
                        if (destX >= 0 && destX < dim && destY >= 0 && destY < dim) {
                            pattern[destX][destY] = Cell.EMPTY;
                        }
                    }
                }
            }
        }
    }

    /**
     * Validates that every {@link Cell#OBSTACLE} is reachable from at least one
     * focus marker by a diagonal move. If any obstacle cannot be reached, the
     * method prints {@code NO} and the program terminates.
     *
     * @param pattern   pattern used to test reachability
     * @param original  original board
     * @param focusPoints list of focus positions
     */
    private static void validateObstacles(
            Cell[][] pattern,
            Cell[][] original,
            List<Point> focusPoints) {

        int centre = Main.BOARD_SIZE - 1;

        for (int i = 0; i < Main.BOARD_SIZE; i++) {
            for (int j = 0; j < Main.BOARD_SIZE; j++) {
                if (original[i][j] == Cell.OBSTACLE) {
                    boolean reachable = false;

                    for (Point focus : focusPoints) {
                        int dx = i - focus.x();
                        int dy = j - focus.y();

                        // Destination cell in the pattern for this diagonal move
                        int destX = centre + dx;
                        int destY = centre + dy;

                        // If the pattern cell is still the default obstacle ('x')
                        // we mark it as reachable.
                        if (pattern[destX][destY] == Cell.OBSTACLE) {
                            reachable = true;
                            break;
                        }
                    }

                    if (!reachable) {
                        System.out.println("NO");
                        System.exit(0);
                    }
                }
            }
        }
    }

    /** Prints the resulting pattern to standard output. */
    private static void printPattern(Cell[][] pattern) {
        StringBuilder sb = new StringBuilder();

        for (Cell[] row : pattern) {
            for (Cell cell : row) {
                sb.append(cell.symbol());
            }
            sb.append('\n');
        }
        System.out.print(sb.toString());
    }

    /**
     * Helper that converts the user’s board representation into a list of focus
     * points. The method also returns the parsed board so the caller can work
     * with proper {@link Cell} objects.
     */
    private static List<Point> collectFocusPoints(Cell[][] original) {
        List<Point> foci = new ArrayList<>();

        for (int i = 0; i < original.length; i++) {
            for (int j = 0; j < original[i].length; j++) {
                if (original[i][j] == Cell.FOCUS) {
                    foci.add(new Point(i, j));
                }
            }
        }
        return foci;
    }
}

import java.io.*;
import java.util.StringTokenizer;

/**
 * Refactored solution for problem D.
 *
 * The program reads an N×N board consisting of characters 'x', 'o' and '.'.
 * It determines whether each 'x' can be reached by moving from an 'o' using a
 * set of allowed displacement vectors. If such a set exists, the program prints
 * "YES" followed by a visualisation of the allowed vectors; otherwise it prints
 * "NO".
 *
 * The code has been split into small, purpose‑focused methods, uses expressive
 * naming, and groups related constants. This improves readability and makes
 * future modifications easier.
 */
public final class Main {

    /** Program entry point. */
    public static void main(String[] args) {
        try (PrintWriter writer = new PrintWriter(System.out)) {
            new Solver().run(writer);
        }
    }

    /** Encapsulates the solving logic. */
    static final class Solver {

        /** Small scanner that mimics the original FastScanner behaviour. */
        private static final FastScanner fastInput = new FastScanner(System.in);

        /** Orchestrates input reading, solving and output generation. */
        void run(PrintWriter out) {
            int n = fastInput.nextInt();
            char[][] board = readBoard(n);
            solveAndPrint(board, out);
        }

        /** Reads N lines of equal length from the scanner. */
        private static char[][] readBoard(int n) {
            char[][] board = new char[n][];
            for (int i = 0; i < n; i++) {
                String line = fastInput.next();
                board[i] = line.toCharArray();
            }
            return board;
        }

        /** Core solving routine – validates coverage and prints the result. */
        private void solveAndPrint(char[][] board, PrintWriter out) {
            final int offsetBase = board.length;               // maps (-n … n) → (0 … 2n)
            boolean[][] allowedOffsets = initAllowedOffsets(2 * board.length + 1);
            boolean[][] covered = new boolean[board.length][board.length];

            pruneInvalidOffsets(board, allowedOffsets);
            markCovered(board, allowedOffsets, covered);

            if (!everyXIsCovered(board, covered)) {
                out.println("NO");
                return;
            }

            out.println("YES");
            printOffsetVisualisation(allowedOffsets, out);
        }

        /** Constructs a matrix where all offsets except (0,0) are initially legal. */
        private static boolean[][] initAllowedOffsets(int dimension) {
            boolean[][] table = new boolean[dimension][dimension];
            final int centre = dimension / 2;
            for (int dx = -centre; dx <= centre; dx++) {
                for (int dy = -centre; dy <= centre; dy++) {
                    if (dx != 0 || dy != 0) {
                        table[dx + centre][dy + centre] = true;
                    }
                }
            }
            return table;
        }

        /** Removes offsets that point from an 'o' to a '.' cell – such offsets can never be used. */
        private static void pruneInvalidOffsets(char[][] board, boolean[][] allowed) {
            final int n = board.length;
            for (int ox = 0; ox < n; ox++) {
                for (int oy = 0; oy < n; oy++) {
                    if (board[ox][oy] != 'o') {
                        continue;
                    }
                    // Every empty cell eliminates the corresponding offset.
                    for (int tx = 0; tx < n; tx++) {
                        for (int ty = 0; ty < n; ty++) {
                            if (board[tx][ty] == '.') {
                                int dx = tx - ox;
                                int dy = ty - oy;
                                allowed[dx + n][dy + n] = false;
                            }
                        }
                    }
                }
            }
        }

        /** Marks all cells that can be reached using a legal offset from any 'o'. */
        private static void markCovered(char[][] board,
                                        boolean[][] allowed,
                                        boolean[][] covered) {
            final int n = board.length;
            for (int ox = 0; ox < n; ox++) {
                for (int oy = 0; oy < n; oy++) {
                    if (board[ox][oy] != 'o') {
                        continue;
                    }
                    for (int dx = -n; dx <= n; dx++) {
                        for (int dy = -n; dy <= n; dy++) {
                            if (dx == 0 && dy == 0) {
                                continue;
                            }
                            if (!allowed[dx + n][dy + n]) {
                                continue;
                            }
                            int nx = ox + dx;
                            int ny = oy + dy;
                            if (nx >= 0 && nx < n && ny >= 0 && ny < n) {
                                covered[nx][ny] = true;
                            }
                        }
                    }
                }
            }
        }

        /** Returns true iff every cell containing 'x' is marked as covered. */
        private static boolean everyXIsCovered(char[][] board, boolean[][] covered) {
            final int n = board.length;
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < n; j++) {
                    if (board[i][j] == 'x' && !covered[i][j]) {
                        return false;
                    }
                }
            }
            return true;
        }

        /** Prints the (2n‑1)×(2n‑1) visualisation of allowed offsets. */
        private static void printOffsetVisualisation(boolean[][] allowed, PrintWriter out) {
            final int size = allowed.length; // should be 2n+1
            for (int i = 0; i < size; i++) {
                for (int j = 0; j < size; j++) {
                    if (i == size / 2 && j == size / 2) {
                        out.print('o');
                    } else {
                        out.print(allowed[i][j] ? 'x' : '.');
                    }
                }
                out.println();
            }
        }
    }

    /** Minimal scanner that returns tokens from {@code System.in}. */
    private static final class FastScanner {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        FastScanner(InputStream source) {
            this.reader = new BufferedReader(new InputStreamReader(source));
        }

        /** Returns the next token, blocking until input is available or EOF is reached. */
        String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) {
                        return null;
                    }
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new UncheckedIOException(e);
                }
            }
            return tokenizer.nextToken();
        }

        /** Convenience wrapper for reading an integer token. */
        int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Solves the problem described in the original source.
 * The implementation has been refactored for readability,
 * maintainability and correctness while keeping the original behaviour.
 */
public class Main {

    /* --------------------------------------------------------------
     *  Entry point
     * -------------------------------------------------------------- */
    public static void main(String[] args) throws IOException {
        new Main().solve();
    }

    /* --------------------------------------------------------------
     *  Core solving routine
     * -------------------------------------------------------------- */
    private void solve() throws IOException {
        Reader reader = new Reader();
        Writer writer = new Writer();

        int n = reader.readInt();                     // board size
        char[][] board = new char[n][];
        for (int i = 0; i < n; ++i) {
            board[i] = reader.readToken().toCharArray();
        }

        int size = 2 * n - 1;                           // dimensions of the result grid
        char[][] result = new char[size][size];
        fillWithDots(result);

        boolean[][] mask = new boolean[n][n];           // cells covered by a valid displacement

        // Scan all possible displacement vectors
        for (int di = 1 - n; di < n; ++di) {
            for (int dj = 1 - n; dj < n; ++dj) {
                if (isValidDisplacement(di, dj, board)) {
                    placeDisplacement(di, dj, result, mask, board);
                }
            }
        }

        // Verify that every 'x' cell of the original board is covered by the mask
        boolean allXCovered = allXCellsAreMasked(board, mask);

        if (allXCovered) {
            result[n - 1][n - 1] = 'o';                 // mark the centre with 'o'
            writer.println("YES");
            for (char[] row : result) {
                writer.println(new String(row));
            }
        } else {
            writer.println("NO");
        }

        // Clean up
        writer.close();
    }

    /* --------------------------------------------------------------
     *  Helper methods
     * -------------------------------------------------------------- */

    /** Checks whether a given displacement vector (di,dj) is valid.
     *  The vector is valid if no 'o' of the board is shifted onto a '.' cell
     *  that stays inside the board. Out‑of‑bounds shifts are ignored. */
    private boolean isValidDisplacement(int di, int dj, char[][] board) {
        int n = board.length;
        for (int i = 0; i < n && valid; ++i) {
            for (int j = 0; j < n && valid; ++j) {
                if (board[i][j] == 'o') {
                    int ni = i + di;
                    int nj = j + dj;
                    if (inside(ni, nj, n)) {
                        if (board[ni][nj] == '.') {
                            valid = false;
                        }
                    }
                }
            }
        }
        return valid;
    }

    /** Places the marker 'x' for a valid displacement and updates the mask. */
    private void placeDisplacement(int di, int dj,
                                     char[][] result,
                                     boolean[][] mask,
                                     char[][] board) {
        int offset = board.length - 1;                 // centre offset in the result grid
        result[di + offset][dj + offset] = 'x';

        for (int i = 0; i < board.length; ++i) {
            for (int j = 0; j < board.length; ++j) {
                if (board[i][j] == 'o') {
                    int ni = i + di;
                    int nj = j + dj;
                    if (inside(ni, nj, board.length)) {
                        mask[ni][nj] = true;
                    }
                }
            }
        }
    }

    /** Returns true iff every cell containing 'x' in the original board
     *  is marked by the mask (i.e. can be reached by a valid displacement). */
    private boolean allXCellsAreMasked(char[][] board, boolean[][] mask) {
        for (int i = 0; i < board.length && covered; ++i) {
            for (int j = 0; j < board.length && covered; ++j) {
                if (board[i][j] == 'x') {
                    covered = mask[i][j];
                }
            }
        }
        return covered;
    }

    /** Simple bounds check. */
    private static boolean inside(int r, int c, int limit) {
        return r >= 0 && r < limit && c >= 0 && c < limit;
    }

    /** Fills a square char array with '.' characters. */
    private static void fillWithDots(char[][] arr) {
        Arrays.fill(arr, '.');
    }

    /* --------------------------------------------------------------
     *  I/O utilities (minimal but functional)
     * -------------------------------------------------------------- */
    private static class Reader {
        private final InputStream stream;
        private final byte[] buffer = new byte[1024];
        private int pos = 0, len = 0;
        private int cur = 0;
        private final StringBuilder sb = new StringBuilder(32);

        Reader() throws IOException {
            stream = System.in;
            cur = read();
        }

        private int read() throws IOException {
            if (len == -1) throw new EOFException();
            if (pos >= len) {
                pos = 0;
                len = stream.read(buffer);
                if (len == -1) throw new EOFException();
            }
            return buffer[pos++];
        }

        private boolean isWhitespace(int c) {
            return c == ' ' || c == '\t' || c == '\r' || c == '\n' || c == -1;
        }

        String readToken() throws IOException {
            while (isWhitespace(cur)) cur = read();
            if (cur == -1) throw new EOFException();
            sb.setLength(0);
            while (!isWhitespace(cur)) {
                sb.append((char) cur);
                cur = read();
            }
            return sb.toString();
        }

        int readInt() throws IOException {
            String token = readToken();
            return Integer.parseInt(token);
        }
    }

    private static class Writer {
        private final PrintWriter out;

        Writer() throws IOException {
            out = new PrintWriter(System.out, true);
        }

        void println(String s) {
            out.println(s);
        }

        void close() {
            out.close();
        }
    }
}

package solution;

import java.io.*;
import java.util.*;

/**
 * Entry point of the program.
 * Reads the test case, delegates the solving process and forwards the output.
 */
public class Main {
    public static void main(String[] args) {
        var scanner = new FastScanner(System.in);
        var printer = new FastPrintWriter(System.out);
        new Solver().solve(scanner, printer);
        printer.close();
    }
}

/**
 * Core logic of the problem.
 * The class is deliberately self‑contained and focuses on a single responsibility:
 * solving one test case.
 */
final class Solver {

    /** Symbols used on the board. */
    private static final char SOURCE = 'o';   // original piece
    private static final char TARGET   = 'x';   // required target cells
    private static final char EMPTY    = '.';   // empty cells in the source board
    private static final char MARKER   = 'o';   // centre marker in the result grid

    /** Solves a single test case. */
    public void solve(FastScanner in, FastPrintWriter out) {
        int n = in.nextInt();                     // board dimension
        char[][] board = readBoard(in, n);          // source board
        boolean[][] covered = new boolean[n][n];    // coverage tracker

        List<Coordinate> validMoves = findValidTranslations(board, n);
        char[][] resultGrid = buildResultGrid(n);

        // Apply each valid translation (except the zero vector) to the result grid
        // and mark every newly reached target cell as covered.
        for (Coordinate mv : validMoves) {
            if (mv.isOrigin()) continue;               // skip the trivial (0,0) move
            markCovered(covered, board, n, mv.dx, mv.dy);
            placeTranslation(resultGrid, mv.dx, mv.dy);
        }

        // Every 'x' must be covered by at least one translation.
        if (!allXTargetsAreCovered(board, covered)) {
            out.println("NO");
            return;
        }

        // Output the answer.
        out.println("YES");
        printResultGrid(resultGrid, out);
    }

    /** Reads an N×N board from the scanner. */
    private static char[][] readBoard(FastScanner in, int n) {
        char[][] board = new char[n][];
        for (int i = 0; i < n; i++) {
            board[i] = in.nextString().toCharArray();
        }
        return board;
    }

    /** Collects all translation vectors (dx,dy) that keep every 'o' inside the board
     *  and land only on '.' cells. */
    private static List<Coordinate> findValidTranslations(char[][] board, int n) {
        List<Coordinate> moves = new ArrayList<>();
        for (int dx = -n + 1; dx < n; dx++) {
            for (int dy = -n + 1; dy < n; dy++) {
                if (isTranslationValid(board, n, dx, dy)) {
                    moves.add(new Coordinate(dx, dy));
                }
            }
        }
        return moves;
    }

    /** Checks whether a given translation leaves the board in a legal state. */
    private static boolean isTranslationValid(char[][] board, int n, int dx, int dy) {
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (board[i][j] != SOURCE) continue;
                int ni = i + dx;
                int nj = j + dy;
                if (ni >= 0 && ni < n && nj >= 0 && nj < n && board[ni][nj] == EMPTY) {
                    return false;          // overlap with an empty cell → illegal move
                }
            }
        }
        return true;                       // no illegal overlap → valid
    }

    /** Marks all target ('x') cells that become reachable by the given translation. */
    private static void markCovered(boolean[][] covered,
                                    char[][] board,
                                    int n,
                                    int dx,
                                    int dy) {
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (board[i][j] != SOURCE) continue;
                int ni = i + dx;
                int nj = j + dy;
                if (ni >= 0 && ni < n && nj >= 0 && nj < n && board[ni][nj] == TARGET) {
                    covered[ni][nj] = true;
                }
            }
        }
    }

    /** Inserts an 'x' marker into the result grid for the supplied translation. */
    private static void placeTranslation(char[][] grid, int dx, int dy) {
        int centre = grid.length / 2;          // centre position offset
        grid[dx + centre][dy + centre] = 'x';
    }

    /** Builds the (2N‑1)×(2N‑1) result grid with a central 'o'. */
    private static char[][] buildResultGrid(int n) {
        int size = 2 * n - 1;
        char[][] grid = new char[size][];
        for (int i = 0; i < size; i++) {
            grid[i] = new char[size];
            Arrays.fill(grid[i], EMPTY);
        }
        int mid = n - 1;
        grid[mid][mid] = MARKER;
        return grid;
    }

    /** Verifies that every 'x' cell on the original board is covered by at least one translation. */
    private static boolean allXTargetsAreCovered(char[][] board, boolean[][] covered) {
        for (int i = 0; i < board.length; i++) {
            for (int j = 0; j < board[i].length; j++) {
                if (board[i][j] == TARGET && !covered[i][j]) {
                    return false;
                }
            }
        }
        return true;
    }

    /** Writes the result grid line‑by‑line to the provided printer. */
    private static void printResultGrid(char[][] grid, FastPrintWriter out) {
        for (char[] row : grid) {
            out.println(new String(row));
        }
    }
}

/**
 * Simple immutable pair representing a translation vector (dx,dy).
 */
final class Coordinate {
    final int dx;
    final int dy;

    Coordinate(int dx, int dy) {
        this.dx = dx;
        this.dy = dy;
    }

    /** Checks whether the vector is the trivial (0,0) move. */
    boolean isOrigin() {
        return dx == 0 && dy == 0;
    }
}

/**
 * Fast scanner that works with the default Java I/O streams.
 */
final class FastScanner {
    private final InputStream stream;
    private final byte[] buffer = new byte[16_384];
    private int bytesRead = 0;
    private int offset = 0;

    FastScanner(InputStream stream) {
        this.stream = stream;
    }

    private int readByte() {
        if (offset >= bytesRead) {
            offset = 0;
            bytesRead = stream.read(buffer);
            if (bytesRead == -1) {
                return -1;
            }
        }
        return buffer[offset++];
    }

    /** Returns the next non‑whitespace token as a {@code String}. */
    String nextString() {
        int c;
        do {
            c = readByte();
        } while (c <= ' ' && c != -1);
        StringBuilder sb = new StringBuilder();
        do {
            sb.append((char) c);
            c = readByte();
        } while (c > ' ' && c != -1);
        return sb.toString();
    }

    /** Returns the next integer token. */
    int nextInt() {
        return Integer.parseInt(nextString());
    }
}

/**
 * Fast printer that flushes automatically on {@code close()}.
 */
final class FastPrintWriter extends PrintWriter {
    FastPrintWriter(OutputStream out) {
        super(out, true);
    }
}

/* -------------------------------------------------------------
 *  Rock‑Paper‑Scissors (RPS) solver – refactored for readability
 *  -------------------------------------------------------------
 *
 *  What the program does:
 *   • Reads an N × N board containing '.', 'x', 'o'.
 *   • Finds all “off‑board” offsets (dx, dy) such that moving every
 *     'o' by (dx, dy) lands exclusively on empty cells ('.').
 *   • If any 'x' cannot be covered by at least one of those offsets,
 *     the answer is “NO”.
 *   • Otherwise prints “YES” and a visualisation that combines the
 *     original board with the chosen offset.
 *
 *  The refactor focuses on:
 *   • Meaningful names (constants, classes, methods).
 *   • Separating concerns (input, processing, output).
 *   • Reducing duplicated code.
 *   • Using small helper types (Point, Board) to improve clarity.
 * ------------------------------------------------------------- */

import java.io.*;
import java.util.*;

public class RockPaperScissorsSolver {

    /* ---------- constants ------------------------------------------------- */
    private static final int EMPTY   = 0;
    private static final int ROCK    = 1;
    private static final int PAPER   = 2;

    /* ---------- entry point ------------------------------------------------ */
    public static void main(String[] args) {
        new RockPaperScissorsSolver().run();
    }

    /* ---------- fields ------------------------------------------------------ */
    private final FastScanner scanner;
    private final PrintWriter out;
    private boolean useSystemIo = true;               // keep original behaviour

    /* ---------- constructor ------------------------------------------------ */
    public RockPaperScissorsSolver() {
        // will be initialised in run() according to the IO mode
        this.scanner = null;
        this.out     = null;
    }

    /* ---------- public API -------------------------------------------------- */
    public void solve() throws IOException {
        Board board = readBoard();
        OffsetSet offsets = findFreeOffsets(board);
        validateRockPositions(board, offsets);
        printResult(board, offsets);
    }

    public void run() {
        try {
            if (useSystemIO) {
                scanner = new FastScanner(System.in);
                out     = new PrintWriter(System.out);
            } else {
                scanner = new FastScanner(new File("rps.in"));
                out     = new PrintWriter(new File("rps.out"));
            }
            solve();
            out.close();
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    /* ---------- input ------------------------------------------------------- */
    private Board readBoard() throws IOException {
        int n = scanner.nextInt();
        char[][] cells = new char[n][n];
        List<Point> papers = new ArrayList<>();

        for (int r = 0; r < n; r++) {
            String row = scanner.next();
            if (row.length() != n) {
                throw new IllegalArgumentException("Row length mismatch");
            }
            for (int c = 0; c < n; c++) {
                cells[r][c] = row.charAt(c);
                if (cells[r][c] == 'o') {
                    papers.add(new Point(r, c));
                }
            }
        }
        return new Board(n, cells, papers);
    }

    /* ---------- core logic --------------------------------------------------- */

    /**
     * Determines all translation offsets (dx, dy) such that moving every
     * ‘o’ (paper) by that offset lands only on empty cells.
     */
    private OffsetSet findFreeOffsets(Board board) {
        int limit = board.size();
        OffsetSet free = new OffsetSet(2 * limit - 1);   // matrix to store results

        for (int dx = -(limit - 1); dx < limit; dx++) {
            for (int dy = -(limit - 1); dy < limit; dy++) {
                if (isOffsetFree(dx, dy, board)) {
                    free.enable(dx + limit - 1, dy + limit - 1);
                }
            }
        }
        return free;
    }

    /** @return true if the offset does not hit any rocky cell */
    private boolean isOffsetFree(int dx, int dy, Board board) {
        for (Point p : board.papers) {
            int nx = p.row + dx;
            int ny = p.col + dy;
            if (!board.isInside(nx, ny)) {
                continue;                // completely outside the board → ignore
            }
            if (board.cell(nx, ny) == EMPTY) {
                // keep checking; only when **all** papers land on empty we accept
                continue;
            }
            return false;                // at least one paper would land on a non‑empty cell
        }
        return true;                     // every paper landed on an empty cell
    }

    /**
     * Checks that every ‘x’ (rock) can be covered by at least one free offset.
     * If not, prints “NO” and aborts.
     */
    private void validateRockPositions(Board board, OffsetSet offsets) {
        for (int r = 0; r < board.size(); r++) {
            for (int c = 0; c < board.size(); c++) {
                if (board.cell(r, c) == ROCK && !offsets.canCover(r, c)) {
                    out.println("NO");
                    out.flush();
                    System.exit(0);
                }
            }
        }
        out.println("YES");
    }

    /** Prints the visualisation that merges the board with the chosen offset. */
    private void printResult(Board board, OffsetSet offsets) {
        // The problem expects exactly one offset to be marked ‘2’ (the “chosen” one)
        // – we take the first enabled cell in the matrix.
        int chosenDx = -1, chosenDy = -1;
        outer:
        for (int i = 0; i < offsets.matrix.length; i++) {
            for (int j = 0; j < offsets.matrix[i].length; j++) {
                if (offsets.isEnabled(i, j)) {
                    chosenDx = i - (board.size() - 1);
                    chosenDy = j - (board.size() - 1);
                    break outer;
                }
            }
        }

        // Build the output matrix (2n‑1 × 2n‑1)
        int outSize = 2 * board.size() - 1;
        char[][] outMatrix = new char[outSize][outSize];

        // Fill with '.' first
        for (char[] row : outMatrix) {
            Arrays.fill(row, '.');
        }

        // Mark the chosen offset as 'o'
        if (chosenDx >= 0) {
            outMatrix[chosenDx + board.size() - 1][chosenDy + board.size() - 1] = 'o';
        }

        // Place the original ‘x’ and ‘o’ cells that survive the shift
        for (int r = 0; r < board.size(); r++) {
            for (int c = 0; c < board.size(); c++) {
                if (board.cell(r, c) != EMPTY) {
                    int nx = r + chosenDx;
                    int ny = c + chosenDy;
                    if (board.isInside(nx, ny)) {
                        outMatrix[nx + board.size() - 1][ny + board.size() - 1] =
                                board.cell(r, c) == ROCK ? 'x' : 'o';
                    }
                }
            }
        }

        // Print the resulting pattern
        for (char[] row : outMatrix) {
            for (char ch : row) {
                out.print(ch);
            }
            out.println();
        }
    }

    /* ---------- helper classes -------------------------------------------- */

    /** Simple immutable point used to store the positions of ‘o’. */
    private static final class Point {
        final int row;
        final int col;

        Point(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }

    /** Container for the N×N board information. */
    private static final class Board {
        final int size;
        final char[][] cells;
        final List<Point> papers;         // positions of ‘o’

        Board(int size, char[][] cells, List<Point> papers) {
            this.size = size;
            this.cells = cells;
            this.papers = papers;
        }

        int cell(int r, int c) {
            return cells[r][c] == '.' ? EMPTY :
                   cells[r][c] == 'x' ? ROCK : PAPER;
        }

        boolean isInside(int r, int c) {
            return r >= 0 && c >= 0 && r < size && c < size;
        }
    }

    /** Matrix that stores which offsets are “free”. */
    private static final class OffsetSet {
        final boolean[][] matrix;           // (2n‑1) × (2n‑1)

        OffsetSet(int dimension) {
            this.matrix = new boolean[dimension][dimension];
        }

        void enable(int i, int j) {
            matrix[i][j] = true;
        }

        boolean isEnabled(int i, int j) {
            return matrix[i][j];
        }

        /** Checks whether a rock at (r,c) can be covered by any enabled offset. */
        boolean canCover(int r, int c, Board board) {
            for (int i = 0; i < matrix.length; i++) {
                for (int j = 0; j < matrix[i].length; j++) {
                    if (!isEnabled(i, j)) {
                        continue;
                    }
                    int dx = i - (board.size() - 1);
                    int dy = j - (board.size() - 1);
                    int nr = r - dx;
                    int nc = c - dy;
                    if (board.isInside(nr, nc) && board.cell(nr, nc) == PAPER) {
                        // there exists a paper that can be shifted onto (r,c)
                        return true;
                    }
                }
            }
            return false;
        }
    }

    /* ---------- fast scanner ------------------------------------------------- */
    private static final class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner(InputStream stream) {
            this.br = new BufferedReader(new InputStreamReader(stream));
        }

        FastScanner(File file) throws FileNotFoundException {
            this.br = new BufferedReader(new FileReader(file));
        }

        private String nextToken() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) {
                        return null;
                    }
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new UncheckedIOException(e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(nextToken());
        }
    }
}

package solution;

import java.io.*;
import java.util.StringTokenizer;

/**
 * Reads one or more chess‑board configurations from standard input,
 * decides whether every ‘x’ cell can be attacked by moving a piece
 * from an ‘o’ cell by a constant offset, and prints the set of
 * admissible offsets in a (2·n‑1)×(2·n‑1) board.
 *
 * The implementation is deliberately split into small, well‑named
 * methods so that each piece of logic can be unit‑tested and
 * understood in isolation.
 */
public class Solver {

    /** Input helper – provides convenient tokenised reading. */
    private static final class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner(InputStream in) {
            this.br = new BufferedReader(new InputStreamReader(in));
        }

        /** Returns the next available token (or waits for more input). */
        private String nextToken() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                String line = br.readLine();
                if (line == null) {
                    throw new EOFException();
                }
                st = new StringTokenizer(line.trim());
            }
            return st.nextToken();
        }

        /** Reads an int from the next token. */
        int nextInt() throws IOException {
            return Integer.parseInt(nextToken());
        }

        /** Reads a double from the next token. */
        double nextDouble() throws IOException {
            return Double.parseDouble(nextToken());
        }

        /** Reads a long from the next token. */
        long nextLong() throws IOException {
            return Long.parseLong(nextToken());
        }

        /** Closes the underlying reader. */
        void close() throws IOException {
            br.close();
        }
    }

    /** Entry point – processes all test cases until EOF. */
    public static void main(String[] args) {
        try (FastScanner fs = new FastScanner(System.in)) {
            solveAll(fs);
        } catch (EOFException eof) {
            // Normal termination when input ends.
        } catch (Exception ex) {
            // Unexpected error – print stack trace and exit.
            ex.printStackTrace();
        }
    }

    /** Orchestrates the processing of every board found in the input. */
    private static void solveAll(FastScanner fs) throws IOException {
        while (true) {
            try {
                int n = fs.nextInt();               // board dimension
                char[][] board = readBoard(fs, n);    // the n×n grid
                Result result = analyseBoard(board);
                outputResult(result);
            } catch (EOFException ignored) {
                break; // no more boards to process
            }
        }
    }

    /** Reads the next n lines and builds a char matrix representing the board. */
    private static char[][] readBoard(FastScanner fs, int n) {
        char[][] board = new char[n][n];
        for (int i = 0; i < n; i++) {
            String line = fs.nextToken();
            for (int j = 0; j < n; j++) {
                board[i][j] = line.charAt(j);
            }
        }
        return board;
    }

    /** Analyzes the board and returns a {@link Result} object containing
     *  the answer and the visual representation of valid offsets. */
    private static Result analyseBoard(char[][] board) {
        int n = board.length;

        // Step 1 – locate every 'o' cell.
        java.util.List<Point> originPoints = findOriginPoints(board);

        // Step 2 – iterate over all possible offsets (dx, dy) that keep
        //          the moved piece inside the board.
        boolean[][] offsetMark = new boolean[2 * n - 1][2 * n - 1];
        boolean[][] attacked = new boolean[n][n];

        for (int dx = -(n - 1); dx <= n - 1; dx++) {
            for (int dy = -(n - 1); dy <= n - 1; dy++) {
                if (isValidOffset(board, originPoints, dx, dy)) {
                    offsetMark[dx + n - 1][dy + n - 1] = true;
                    markAttackedCells(board, originPoints, dx, dy, attacked);
                }
            }
        }

        // Step 3 – verify that every 'x' cell is attacked.
        boolean allXAreAttacked = allXCellsAttacked(board, attacked);

        return new Result(allXAreAttacked, offsetMark);
    }

    /** Returns the list of coordinates that contain an 'o'. */
    private static java.util.List<Point> findOriginPoints(char[][] board) {
        java.util.List<Point> list = new java.util.ArrayList<>();
        int n = board.length;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (board[i][j] == 'o') {
                    list.add(new Point(i, j));
                }
            }
        }
        return list;
    }

    /** Checks whether the offset (dx, dy) satisfies the problem’s rule:
     *  for every 'o' the landing cell must stay inside the board
     *  and must NOT be a '.' cell.
     */
    private static boolean isValidOffset(char[][] board,
                                           java.util.List<Point> origins,
                                           int dx, int dy) {
        for (Point p : origins) {
            int nx = p.x + dx;
            int ny = p.y + dy;
            if (inside(board, nx, ny)) {
                if (board[nx][ny] == '.') {
                    return false;
                }
            }
        }
        return true;
    }

    /** Marks all cells that become attacked by moving an 'o' by (dx, dy). */
    private static void markAttackedCells(char[][] board,
                                            java.util.List<Point> origins,
                                            int dx, int dy,
                                            boolean[][] attacked) {
        for (Point p : origins) {
            int nx = p.x + dx;
            int ny = p.y + dy;
            if (inside(board, nx, ny)) {
                attacked[nx][ny] = true;
            }
        }
    }

    /** Simple bounds check for board coordinates. */
    private static boolean inside(char[][] board, int x, int y) {
        return x >= 0 && x < board.length && y >= 0 && y < board[0].length;
    }

    /** Determines whether every 'x' cell in the original board is marked
     *  as attacked by at least one valid offset. */
    private static boolean allXCellsAttacked(char[][] board,
                                               boolean[][] attacked) {
        for (int i = 0; i < board.length; i++) {
            for (int j = 0; j < board[i].length; j++) {
                if (board[i][j] == 'x' && !attacked[i][j]) {
                    return false;
                }
            }
        }
        return true;
    }

    /** Prints the answer for the current board:
     *   – "NO" if not all 'x' cells are reachable,
     *   – "YES" followed by the (2·n‑1)×(2·n‑1) visualisation of offsets
     *     if a solution exists.
     */
    private static void outputResult(Result result) {
        if (!result.isSolutionExists()) {
            System.out.println("NO");
            return;
        }

        System.out.println("YES");
        int size = result.offsetMark.length; // = 2·n‑1
        for (int i = 0; i < size; i++) {
            StringBuilder sb = new StringBuilder();
            for (int j = 0; j < size; j++) {
                if (i == result.centerRow && j == result.centerCol) {
                    sb.append('o');
                } else if (result.offsetMark[i][j]) {
                    sb.append('x');
                } else {
                    sb.append('.');
                }
            }
            System.out.println(sb);
        }
    }

    /** Holds the outcome of a board analysis. */
    private static final class Result {
        private final boolean solutionExists;
        private final boolean[][] offsetMark;
        private final int centerRow;
        private final int centerCol;

        Result(boolean solutionExists, boolean[][] offsetMark) {
            this.solutionExists = solutionExists;
            this.offsetMark = offsetMark;
            int dimension = offsetMark.length;
            this.centerRow = dimension / 2;
            this.centerCol = dimension / 2;
        }

        boolean isSolutionExists() {
            return solutionExists;
        }

        boolean[][] getOffsetMark() {
            return offsetMark;
        }

        int getCenterRow() {
            return centerRow;
        }

        int getCenterCol() {
            return centerCol;
        }
    }

    /** Simple point holder used during the search. */
    private static final class Point {
        final int x, y;
        Point(int x, int y) {
            this.x = x;
            this.y = y;
        }
    }
}

import java.io.*;
import java.util.*;
import java.util.stream.*;

/**
 * WeirdChess – determines whether every ‘x’ on the board can be reached
 * by moving all ‘o’ pieces by the same (dx,dy) translation and prints the
 * resulting (2·n‑1)×(2·n‑1) pattern.
 */
public class WeirdChess {

    /** Helper that stores a board position. */
    private static final class Position {
        final int row;
        final int col;
        Position(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }

    /** Helper that records which board translations are possible. */
    private static final class TranslationMap {
        private final boolean[][] marked;
        private final int centre;               // index of (0,0) translation

        TranslationMap(int n) {
            int size = 2 * n - 1;
            marked = new boolean[size][size];
            centre = n - 1;
        }

        /** Mark that translation (dx,dy) works. */
        void mark(int dx, int dy) {
            marked[centre + dx][centre + dy] = true;
        }

        /** Check whether a given translation was marked. */
        boolean isMarked(int dx, int dy) {
            return marked[centre + dx][centre + dy];
        }
    }

    /** Fast scanner that wraps a {@link BufferedReader}. */
    private static final class InputScanner implements AutoCloseable {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        InputScanner(InputStream stream) {
            this.reader = new BufferedReader(new InputStreamReader(stream));
        }

        /** Return the next token, filling the tokenizer lazily. */
        private String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                tokenizer = new StringTokenizer(readLine());
            }
            return tokenizer.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        /** Read a full line (used only internally). */
        private String readLine() throws IOException {
            return reader.readLine();
        }

        @Override
        public void close() throws IOException {
            reader.close();
        }
    }

    /** Reads the chess board from the scanner. */
    private static char[][] readBoard(InputScanner scanner, int n) throws IOException {
        char[][] board = new char[n][n];
        for (int r = 0; r < n; ++r) {
            board[r] = scanner.next().toCharArray();
        }
        return board;
    }

    /** Collects all coordinates that contain the character 'o'. */
    private static List<Position> collectPieces(char[][] board) {
        List<Position> pieces = new ArrayList<>();
        for (int r = 0; r < board.length; ++r) {
            for (int c = 0; c < board[r].length; ++c) {
                if (board[r][c] == 'o') {
                    pieces.add(new Position(r, c));
                }
            }
        }
        return pieces;
    }

    /** Determine whether the translation (dx,dy) can be applied to every piece.
     *  If it can, mark the target cells as reachable.
     */
    private static boolean applicableTranslation(char[][] board,
                                                 List<Position> pieces,
                                                 int dx, int dy,
                                                 boolean[][] reachable) {
        for (Position p : pieces) {
            int nx = p.row + dx;
            int ny = p.col + dy;
            if (nx < 0 || nx >= board.length || ny < 0 || ny >= board.length) {
                return false;
            }
            if (board[nx][ny] != 'x') {
                return false;
            }
            reachable[nx][ny] = true;   // the cell can be reached
        }
        return true;
    }

    /** Verify that every ‘x’ on the original board has been marked reachable. */
    private static boolean allXCellsCovered(char[][] board, boolean[][] reachable) {
        return Arrays.stream(board)
                .flatMap(Arrays::stream)
                .anyMatch(cell -> cell == 'x' && !reachable[cell - board[0].length * 0][0]); // placeholder – will be replaced by real check below
    }

    /** Actually checks that each ‘x’ has a corresponding reachable cell. */
    private static boolean allXCellsCovered(char[][] board, boolean[][] reachable) {
        for (int r = 0; r < board.length; ++r) {
            for (int c = 0; c < board[r].length; ++c) {
                if (board[r][c] == 'x' && !reachable[r][c]) {
                    return false;
                }
            }
        }
        return true;
    }

    /** Prints the final (2*n‑1)×(2*n‑1) board according to the marked translations. */
    private static void printResult(TranslationMap map, int n) {
        int size = 2 * n - 1;
        char[][] out = new char[size][size];
        for (char[] row : out) {
            Arrays.fill(row, '.');
        }
        out[map.centre][map.centre] = 'o';   // centre cell represents the (0,0) translation

        for (int dx = -n + 1; dx < n; ++dx) {
            for (int dy = -n + 1; dy < n; ++dy) {
                if (map.isMarked(dx, dy)) {
                    out[map.centre + dx][map.centre + dy] = 'x';
                }
            }
        }

        for (char[] row : out) {
            System.out.println(new String(row));
        }
    }

    /** Entry point. */
    public static void main(String[] args) throws IOException {
        try (InputScanner scanner = new InputScanner(System.in)) {
            int n = scanner.nextInt();
            char[][] board = readBoard(scanner, n);
            List<Position> pieces = collectPieces(board);

            boolean[][] reachable = new boolean[n][n];
            TranslationMap map = new TranslationMap(n);

            // Examine every possible translation
            for (int dx = -n + 1; dx < n; ++dx) {
                for (int dy = -n + 1; dy < n; ++dy) {
                    if (applicableTranslation(board, pieces, dx, dy, reachable)) {
                        map.mark(dx, dy);
                    }
                }
            }

            if (!allXCellsCovered(board, reachable)) {
                System.out.println("NO");
                return;
            }

            System.out.println("YES");
            printResult(map, n);
        }
    }
}

import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;

/**
 * Refactored version of the original program.
 * 
 * <p>
 * The program reads an N×N board containing the characters:
 * <ul>
 *   <li>{@code 'o'} – the origin piece</li>
 *   <li>{@code 'x'} – pieces to be transformed</li>
 *   <li>{@code '.'} – empty cells</li>
 * </ul>
 * It tries to place an {@code 'x'} on every cell of an enlarged board (size
 * 2·N‑1) that is reachable by translating the origin piece by a constant offset.
 * The translation must not cause an {@code 'o'} to land on an empty cell.
 * Then it propagates the change, replacing any {@code 'x'} that would be hit
 * by the translation with a {@code 'y'}. If after propagation there is no {@code 'x'}
 * left on the original board the answer is {@code "YES"} and the transformed
 * enlarged board is printed, otherwise {@code "NO"} is printed.
 * </p>
 */
public final class Main {

    /** Character used for empty cells in the resulting board. */
    private static final char EMPTY = '.';

    /** Character representing the original piece. */
    private static final char ORIGIN = 'o';

    /** Character used to mark a successfully placed translation. */
    private static final char TRANSLATED = 'x';

    /** Character used to mark a target that gets transformed. */
    private static final char TRANSFORMED = 'y';

    /** Size of the input square board. */
    private final int size;

    /** The input board. */
    private final char[][] board;

    /** The output board (enlarged to 2·size‑1). */
    private final char[][] result;

    /**
     * Entry point.
     *
     * @param args command line arguments (unused)
     */
    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            new Main(scanner).run();
        }
    }

    /** Constructor that reads the input and performs the computation. */
    private Main(Scanner scanner) {
        this.size = scanner.nextInt();
        this.board = readBoard(scanner);
        this.result = createEmptyResultBoard();
    }

    /** Reads the N×N board from the scanner. */
    private char[][] readBoard(Scanner scanner) {
        char[][] b = new char[size][size];
        for (int r = 0; r < size; r++) {
            String line = scanner.next();
            b[r] = line.toCharArray();
        }
        return b;
    }

    /** Creates an empty result board and puts the origin piece in its centre. */
    private char[][] createEmptyResultBoard() {
        char[][] r = new char[2 * size - 1][2 * size - 1];
        for (char[] row : r) {
            java.util.Arrays.fill(row, EMPTY);
        }
        int centre = size - 1;
        r[centre][centre] = ORIGIN;
        return r;
    }

    /** Finds all safe translation offsets that do not land on an empty cell. */
    private List<Offset> findSafeOffsets() {
        List<Offset> safe = new ArrayList<>();
        int centre = size - 1;

        // iterate over possible offsets in the enlarged board
        for (int y = 0; y < result.length; y++) {
            for (int x = 0; x < result[0].length; x++) {
                if (y == centre && x == centre) {
                    continue; // centre cell already contains 'o'
                }

                int dr = y - centre;
                int dc = x - centre;

                if (isSafeOffset(dr, dc)) {
                    safe.add(new Offset(dr, dc));
                }
            }
        }
        return safe;
    }

    /** Returns true if translating every 'o' by (dr,dc) never lands on '.'. */
    private boolean isSafeOffset(int dr, int dc) {
        for (int r = 0; r < size; r++) {
            for (int c = 0; c < size; c++) {
                if (board[r][c] != ORIGIN) {
                    continue;
                }
                int nr = r + dr;
                int nc = c + dc;
                if (isInside(nr, nc) && board[nr][nc] == EMPTY) {
                    return false;
                }
            }
        }
        return true;
    }

    /** Simple container for an offset (row, column). */
    private static final class Offset {
        final int dr;
        final int dc;
        Offset(int dr, int dc) {
            this.dr = dr;
            this.dc = dc;
        }
    }

    /** Propagates transformations on the original board for each safe offset. */
    private void propagateTransformations(List<Offset> offsets) {
        for (Offset off : offsets) {
            int dr = off.dr;
            int dc = off.dc;
            for (int r = 0; r < size; r++) {
                for (int c = 0; c < size; c++) {
                    if (board[r][c] != ORIGIN) {
                        continue;
                    }
                    int nr = r + dr;
                    int nc = c + dc;
                    if (isInside(nr, nc) && board[nr][nc] == TRANSLATED) {
                        board[nr][nc] = TRANSFORMED;
                    }
                }
            }
        }
    }

    /** Checks whether any 'x' remains on the original board. */
    private boolean hasRemainingX() {
        for (char[] row : board) {
            for (char cell : row) {
                if (cell == TRANSLATED) {
                    return true;
                }
            }
        }
        return false;
    }

    /** Executes the full algorithm and prints the result. */
    private void run() {
        List<Offset> safeOffsets = findSafeOffsets();

        // Mark the safe positions with 'x' in the result board
        int centre = size - 1;
        for (Offset off : safeOffsets) {
            int y = centre + off.dr;
            int x = centre + off.dc;
            result[y][x] = TRANSLATED;
        }

        // Apply the propagation logic
        propagateTransformations(safeOffsets);

        // Decide which output to produce
        if (hasRemainingX()) {
            System.out.println("NO");
        } else {
            System.out.println("YES");
            printResultBoard();
        }
    }

    /** Prints the enlarged board line by line. */
    private void printResultBoard() {
        for (char[] row : result) {
            System.out.println(new String(row));
        }
    }

    /** Utility method to test array bounds. */
    private boolean isInside(int r, int c) {
        return r >= 0 && r < board.length && c >= 0 && c < board[0].length;
    }
}

import java.io.*;
import java.util.*;
import java.util.stream.*;

public class Main {

    /* -------------------------------------------------
       Simple container for a board coordinate
       ------------------------------------------------- */
    private static final class Point {
        final int row;
        final int col;

        Point(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }

    /* -------------------------------------------------
       Minimal input helper (wraps System.in)
       ------------------------------------------------- */
    private static final class InputReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        InputReader(InputStream stream) {
            this.reader = new BufferedReader(new InputStreamReader(stream), 32768);
        }

        String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new UncheckedIOException(e);
                }
            }
            return tokenizer.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }
    }

    /* -------------------------------------------------
       Core solver – separates reading, solving and output
       ------------------------------------------------- */
    private static final class Solver {

        private char[][] board;          // original N×N board (1‑based)
        private char[][] result;         // (2N‑1)×(2N‑1) answer grid
        private final List<Point> pieces = new ArrayList<>();

        void solve(InputReader in, PrintWriter out) {
            int n = in.nextInt();
            readBoard(in, n);
            int outSize = 2 * n - 1;
            buildResultGrid(outSize);

            // centre cell always holds the original ‘o’
            result[n - 1][n - 1] = 'o';

            // fill the answer grid according to the problem rules
            fillResultGrid(n);

            // verify that every ‘x’ in the original board is reachable
            if (isValidSolution(n)) {
                out.println("YES");
                printResult(out);
            } else {
                out.println("NO");
            }
        }

        /* -------------------------------------------------
           Reads the board and stores positions of ‘o’
           ------------------------------------------------- */
        private void readBoard(InputReader in, int n) {
            board = new char[n + 2][n + 2];   // 1‑based with a safety margin
            for (int i = 1; i <= n; i++) {
                char[] row = in.next().toCharArray();
                for (int j = 1; j <= n; j++) {
                    board[i][j] = row[j - 1];
                    if (board[i][j] == 'o') {
                        pieces.add(new Point(i, j));
                    }
                }
            }
        }

        /* -------------------------------------------------
           Creates the (2N‑1)×(2N‑1) grid filled with ‘x’
           ------------------------------------------------- */
        private void buildResultGrid(int size) {
            result = new char[size][size];
            for (char[] row : result) {
                Arrays.fill(row, 'x');
            }
        }

        /* -------------------------------------------------
           Implements the rule that a '.' on the board
           makes the corresponding output cell become '.'
           ------------------------------------------------- */
        private void fillResultGrid(int n) {
            int outSize = result.length;

            for (int outRow = 0; outRow < outSize; outRow++) {
                for (int outCol = 0; outCol < outSize; outCol++) {
                    // skip the already‑filled centre cell
                    if (outRow == n - 1 && outCol == n - 1) {
                        continue;
                    }

                    // translate output coordinates to an offset
                    int deltaRow = (outRow + 1) - n;
                    int deltaCol = (outCol + 1) - n;

                    // any original piece that maps to a '.' cell makes this
                    // output cell become '.'
                    for (Point p : pieces) {
                        int newRow = p.row + deltaRow;
                        int newCol = p.col + deltaCol;
                        if (isInsideBoard(newRow, newCol) && board[newRow][newCol] == '.') {
                            result[outRow][outCol] = '.';
                            break;
                        }
                    }
                }
            }
        }

        /* -------------------------------------------------
           Helper – checks whether a board coordinate lies
           inside the original N×N area (margin excluded)
           ------------------------------------------------- */
        private boolean isInsideBoard(int r, int c) {
            return r >= 1 && r < board.length - 1 &&
                   c >= 1 && c < board[0].length - 1;
        }

        /* -------------------------------------------------
           Validation – every ‘x’ on the original board must
           be reachable by at least one offset whose output cell
           is still ‘x’ (i.e. not overwritten by '.')
           ------------------------------------------------- */
        private boolean isValidSolution(int n) {
            for (int i = 1; i <= n; i++) {
                for (int j = 1; j <= n; j++) {
                    if (board[i][j] == 'x') {
                        boolean reachable = false;
                        for (Point p : pieces) {
                            int deltaRow = i - p.row;
                            int deltaCol = j - p.col;
                            int outRow = n - 1 + deltaRow;
                            int outCol = n - 1 + deltaCol;

                            if (outRow >= 0 && outRow < result.length &&
                                outCol >= 0 && outCol < result[0].length &&
                                result[outRow][outCol] == 'x') {
                                reachable = true;
                                break;
                            }
                        }
                        if (!reachable) {
                            return false;
                        }
                    }
                }
            }
            return true;
        }

        /* -------------------------------------------------
           Prints the resulting grid line‑by‑line
           ------------------------------------------------- */
        private void printResult(PrintWriter out) {
            StringBuilder sb = new StringBuilder();
            for (char[] row : result) {
                for (char cell : row) {
                    sb.append(cell);
                }
                sb.append('\n');
            }
            out.print(sb);
        }
    }

    /* -------------------------------------------------
       Entry point – uses try‑with‑resources for safe stream
       management and delegates all work to Solver
       ------------------------------------------------- */
    public static void main(String[] args) {
        try (InputStream in = System.in;
             OutputStream out = System.out) {
            new Solver().solve(new InputReader(in), new PrintWriter(out));
        }
    }
}

/**
 * Refactored version of the original program.
 * The logic is unchanged, but the code is now more readable,
 * maintainable and better organized.
 */
import java.io.*;
import java.util.*;

public class Solution {

    /* --------------------------------------------------------------------- */
    /*  Helper data structures                                                 */
    /* --------------------------------------------------------------------- */

    /** Simple container for a cell coordinate. */
    private static final class Cell {
        final int row;
        final int col;

        Cell(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }

    /** Markers used in the result grid. */
    private static final char MARK_ORIGIN = 'o';
    private static final char MARK_EMPTY   = '.';
    private static final char MARK_FILL    = 'x';

    /* --------------------------------------------------------------------- */
    /*  Core solver                                                          */
    /* --------------------------------------------------------------------- */

    private final FastScanner scanner;
    private final PrintWriter printer;

    /** Size of the input square grid. */
    private int n;

    /** The original input grid (n × n). */
    private char[][] inputGrid;

    /** A parallel grid that records which cells must be marked as 'x' or '.' */
    private char[][] checkGrid;

    /** Relative offsets that will be applied to every 'o' position. */
    private final List<Cell> offsets = new ArrayList<>();

    /** All positions that contain an 'o' in the input. */
    private final List<Cell> originPoints = new ArrayList<>();

    /** Constructors ----------------------------------------------------------------- */

    public Solution(FastScanner scanner, PrintWriter printer) {
        this.scanner = scanner;
        this.printer = printer;
    }

    /** Entry point ----------------------------------------------------------- */

    public static void main(String[] args) {
        new Solution(new FastScanner(System.in), new PrintWriter(System.out)).run();
    }

    /** Main solving routine --------------------------------------------------- */

    public void run() {
        try {
            readInput();
            solve();
            printResult();
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    /** Reads and validates the whole input ----------------------------------- */

    private void readInput() throws IOException {
        n = scanner.nextInt();

        // read the n × n board
        inputGrid = new char[n][n];
        for (int i = 0; i < n; i++) {
            String token = scanner.next();
            if (token.length() != n) {
                throw new IllegalArgumentException("Token length mismatch");
            }
            inputGrid[i] = token.toCharArray();
        }

        // initialise auxiliary structures
        checkGrid = new char[n][n];
        for (int i = 0; i < n; i++) {
            Arrays.fill(checkGrid[i], MARK_EMPTY);
        }
    }

    /** Core algorithm – builds the answer grid -------------------------------- */

    private void solve() {
        int size = 2 * n - 1;                     // size of the output grid
        char[][] answer = new char[size][size];

        // fill answer with the fill‑character
        Arrays.fill(answer, MARK_FILL);

        // origin of the answer grid (the centre where the original board starts)
        int originRow = n - 1;
        int originCol = n - 1;
        answer[originRow][originCol] = MARK_ORIGIN;

        // -----------------------------------------------------------------
        // 1) Remember all positions that contain an 'o' in the input board
        // -----------------------------------------------------------------
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (inputGrid[i][j] == MARK_ORIGIN) {
                    originPoints.add(new Cell(i, j));
                }
            }
        }

        // -----------------------------------------------------------------
        // 2) Compute all relative offsets between an 'o' cell and a '.' cell
        // -----------------------------------------------------------------
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (inputGrid[i][j] == MARK_ORIGIN) {
                    continue; // we only need '.' cells here
                }
                if (inputGrid[i][j] == '.') {
                    // every such cell defines an offset that must be marked with '.'
                    Cell offset = new Cell(i, j);
                    offsets.add(offset);
                }
            }
        }

        // -----------------------------------------------------------------
        // 3) Apply the offsets to each origin point and fill the answer grid
        // -----------------------------------------------------------------
        for (Cell origin : originPoints) {
            for (Cell off : offsets) {
                int newRow = originRow + off.row - origin.row;
                int newCol = originCol + off.col - origin.col;
                if (inside(newRow, newCol, size)) {
                    answer[newRow][newCol] = MARK_EMPTY;
                }
            }
        }

        // -----------------------------------------------------------------
        // 4) Allocate an array that stores the same offsets but in a more
        //    convenient primitive form (row‑delta, col‑delta)
        // -----------------------------------------------------------------
        int capacity = size * size; // safe upper bound
        int[] deltaRows = new int[capacity];
        int[] deltaCols = new int[capacity];
        int used = 0;
        for (int i = 0; i < size; i++) {
            for (int j = 0; j < size; j++) {
                if (answer[i][j] == MARK_FILL) {
                    deltaRows[used] = i - originRow;
                    deltaCols[used] = j - originCol;
                    used++;
                }
            }
        }

        // -----------------------------------------------------------------
        // 5) Propagate the '.' marks from every origin point using the stored
        //    primitive offsets
        // -----------------------------------------------------------------
        for (Cell origin : originPoints) {
            for (int k = 0; k < used; k++) {
                int newR = origin.row + deltaRows[k];
                int newC = origin.col + deltaCols[k];
                if (insideGrid(newR, newC, n) && checkGrid[newR][newC] != MARK_ORIGIN) {
                    checkGrid[newR][newC] = MATH_EMPTY; // we will use MARK_EMPTY later
                }
            }
        }

        // -----------------------------------------------------------------
        // 6) Verify that the constructed `checkGrid` matches the original
        //    input board. If not, the answer is impossible.
        // -----------------------------------------------------------------
        if (!boardsMatch()) {
            printer.println("NO");
            return;
        }

        // -----------------------------------------------------------------
        // 7) All checks passed – output the answer.
        // -----------------------------------------------------------------
        printer.println("YES");
        for (int i = 0; i < size; i++) {
            for (int j = 0; j < size; j++) {
                printer.print(answer[i][j]);
            }
            printer.println();
        }
    }

    /** Helper: does the constructed check grid equal the input board? ---- */

    private boolean boardsMatch() {
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (checkGrid[i][j] != inputGrid[i][j]) {
                    return false;
                }
            }
        }
        return true;
    }

    /** Simple range check for a given coordinate. ------------------------ */

    private boolean inside(int r, int c, int limit) {
        return 0 <= r && r < limit && 0 <= c && c < limit;
    }

    /** Simple range check for the original n × n grid. ------------------- */

    private boolean insideGrid(int r, int c, int limit) {
        return 0 <= r && r < limit && 0 <= c && c < limit;
    }

    /* --------------------------------------------------------------------- */
    /*  FastScanner – unchanged from the original solution                     */
    /* --------------------------------------------------------------------- */

    /**
     * A tiny wrapper around {@link BufferedReader} that returns tokens.
     */
    private static final class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner(InputStream stream) {
            br = new BufferedReader(new InputStreamReader(stream));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                String line = readLine();
                if (line == null) {
                    return null;
                }
                st = new StringTokenizer(line);
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        private String readLine() throws IOException {
            return br.readLine();
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.PrintWriter;
import java.util.ArrayList;
import java.util.List;

/**
 * Entry point of the application.
 * Reads the input, runs the solver and prints the result.
 */
public class Main {

    public static void main(String[] args) throws IOException {
        try (BufferedReader br = new BufferedReader(new java.io.InputStreamReader(System.in))) {
            PrintWriter out = new PrintWriter(System.out);
            solve(br, out);
            out.close();
        }
    }

    /**
     * Orchestrates the whole solution.
     *
     * @param reader a source of tokenised input
     * @param out    where the answer is written
     */
    private static void solve(BufferedReader reader, PrintWriter out) throws IOException {
        int boardSize = parseBoardSize(reader);
        List<String> initialPatterns = parseInitialPatterns(reader, boardSize);

        // 1️⃣ Determine all legal offsets that can be placed around the central 'o'
        List<OffsetInfo> legalOffsets = computeLegalOffsets(boardSize, initialPatterns);

        // 2️⃣ Build the resulting (2n‑1) × (2n‑1) board
        char[][] resultBoard = buildResultBoard(boardSize, initialPatterns, legalOffsets);

        // 3️⃣ Verify that every 'x' in the original pattern is covered by at least one legal beat
        if (!validateAllBeatsAreCovered(boardSize, initialPatterns, legalOffsets)) {
            out.println("NO");
            return;
        }

        // 4️⃣ Output the answer
        out.println("YES");
        printResultBoard(resultBoard, out);
    }

    /* --------------------------------------------------------------------- */
    /*  Parsing helpers                                                       */
    /* --------------------------------------------------------------------- */

    /** Reads the first integer – the size of the board (n). */
    private static int parseBoardSize(BufferedReader reader) throws IOException {
        String token = reader.readLine();
        return Integer.parseInt(token.trim());
    }

    /** Reads exactly {@code n} lines, each containing a row of the pattern. */
    private static List<String> parseInitialPatterns(BufferedReader reader, int n) throws IOException {
        List<String> patterns = new ArrayList<>(n);
        for (int i = 0; i < n; i++) {
            String line = reader.readLine();
            if (line == null) {
                throw new IOException("Unexpected end of input while reading pattern rows.");
            }
            patterns.add(line.trim());
        }
        return patterns;
    }

    /* --------------------------------------------------------------------- */
    /*  Core algorithmic stages                                               */
    /* --------------------------------------------------------------------- */

    /** Information about a candidate offset (dx, dy) for the board. */
    private static final class OffsetInfo {
        final int dx, dy; // relative shift from centre

        OffsetInfo(int dx, int dy) {
            this.dx = dx;
            this.dy = dy;
        }
    }

    /**
     * Finds every offset (dx, dy) such that translating every 'o' in the original
     * pattern does not land on an empty cell ('.') of the pattern.
     *
     * @return list of all legal offsets
     */
    private static List<OffsetInfo> computeLegalOffsets(int n, List<String> pattern) {
        int boardDim = 2 * n - 1;
        List<OffsetInfo> offsets = new ArrayList<>();

        for (int i = 0; i < boardDim; i++) {
            for (int j = 0; j < boardDim; j++) {
                if (i == n - 1 && j == n - 1) {               // centre cell – already occupied
                    continue;
                }
                int dx = i - (n - 1);
                int dy = j - (n - 1);

                if (isPlacementValid(dx, dy, n, pattern)) {
                    offsets.add(new OffsetInfo(dx, dy));
                }
            }
        }
        return offsets;
    }

    /** Checks if translating every 'o' by (dx,dy) avoids empty cells. */
    private static boolean isPlacementValid(int dx, int dy, int n, List<String> pattern) {
        for (int r = 0; r < n; r++) {
            String row = pattern.get(r);
            for (int c = 0; c < n; c++) {
                if (row.charAt(c) != 'o') {
                    continue;
                }
                int nr = r + dx;
                int nc = c + dy;
                if (!isInside(n, nr, nc) || pattern.get(nr).charAt(nc) == '.') {
                    return false;
                }
            }
        }
        return true;
    }

    /** Helper that checks whether a coordinate lies inside an n×n grid. */
    private static boolean isInside(int n, int x, int y) {
        return x >= 0 && x < n && y >= 0 && y < n;
    }

    /**
     * Creates the (2n‑1)×(2n‑1) board.
     *
     * * Places the central 'o'.
     * * For each legal offset marks the corresponding cell with 'x' if it
     *   satisfies the “beat” condition.
     */
    private static char[][] buildResultBoard(int n,
                                             List<String> pattern,
                                             List<OffsetInfo> offsets) {
        int boardDim = 2 * n - 1;
        char[][] board = new char[boardDim][boardDim];

        // initialise with '.'
        for (char[] row : board) {
            java.util.Arrays.fill(row, '.');
        }

        // central cell
        board[n - 1][n - 1] = 'o';

        // mark all beats
        boolean[][] beat = new boolean[n][n];
        for (OffsetInfo off : offsets) {
            for (int r = 0; r < n; r++) {
                String row = pattern.get(r);
                for (int c = 0; c < n; c++) {
                    if (row.charAt(c) == 'o') {
                        int tr = r + off.dx;
                        int tc = c + off.dy;
                        if (isInside(n, tr, tc) && row.charAt(tr).charAt(tc) == 'x') {
                            beat[tr][tc] = true;
                        }
                    }
                }
            }
            // fill the board cell for this offset with 'x'
            int boardX = off.dx + (n - 1);
            int boardY = off.dy + (n - 1);
            board[boardX][boardY] = 'x';
        }

        // store beat information for the later validation step
        // (kept as a field of the class – here we just return it implicitly)
        // For simplicity we embed it in the next step.
        return board;
    }

    /**
     * Checks that every 'x' in the original pattern is covered by at least
     * one beat derived from a legal offset.
     */
    private static boolean validateAllBeatsAreCovered(int n,
                                                      List<String> pattern,
                                                      List<OffsetInfo> offsets) {
        boolean[][] beat = new boolean[n][n];

        // recompute beats (same logic as in buildResultBoard, but we need the array)
        for (OffsetInfo off : offsets) {
            for (int r = 0; r < n; r++) {
                String row = pattern.get(r);
                for (int c = 0; c < n; c++) {
                    if (row.charAt(c) == 'o') {
                        int tr = r + off.dx;
                        int tc = c + off.dy;
                        if (isInside(n, tr, tc) && row.charAt(tr).charAt(tc) == 'x') {
                            beat[tr][tc] = true;
                        }
                    }
                }
            }
        }

        // verify coverage
        for (int r = 0; r < n; r++) {
            String row = pattern.get(r);
            for (int c = 0; c < n; c++) {
                if (row.charAt(c) == 'x' && !beat[r][c]) {
                    return false;
                }
            }
        }
        return true;
    }

    /** Writes the resulting board to the provided PrintWriter. */
    private static void printResultBoard(char[][] board, PrintWriter out) {
        for (char[] row : board) {
            for (char cell : row) {
                out.print(cell);
            }
            out.println();
        }
    }
}

/**
 * Refactored solution for the “Puzzle” problem.
 *
 * <p>Key improvements:
 *
 * <ul>
 *   <li>Extracted responsibilities into small, focused methods.</li>
 *   <li>Replaced parallel {@code dx}/{@code dy} lists with a list of {@link Offset} objects.</li>
 *   <li>Used meaningful names instead of single‑letter variables.</li>
 *   <li>Removed magic numbers and grouped related constants.</li>
 *   <li>Prefer try‑with‑resources for I/O to guarantee proper closing.</li>
 *   <li>Added javadoc comments and inline documentation.</li>
 * </ul>
 *
 * <p>The functional behaviour is unchanged – the program still reads an {@code n × n}
 * grid of characters {@code 'x'}/{'o'}/{'.'}, finds all translation offsets that keep every
 * {@code 'o'} on the board, verifies that each {@code 'x'} can be attacked by at least one
 * {@code 'o'} after applying one of those offsets, and finally prints a visual board of
 * size {@code 2*n‑1}.
 */
public class Solution {

    /* -------------------------------------------------------------------------- */
    /*                           Configuration constants                        */
    /* -------------------------------------------------------------------------- */
    private static final String DEFAULT_INPUT_FILE = "input.txt";
    private static final String DEFAULT_OUTPUT_FILE = "output.txt";

    /** Selects the source of input (0 → file, 1 → stdin). */
    private static final int INPUT_SOURCE_FILE = 0;
    /** Selects the destination of output (0 → file, 1 → stdout). */
    private static final int OUTPUT_SINK_FILE = 0;

    /* -------------------------------------------------------------------------- */
    /*                               Entry point                                   */
    /* -------------------------------------------------------------------------- */
    public static void main(String[] args) throws IOException {
        try (InputReader in = openInputReader();
             PrintWriter out = openOutputWriter()) {

            new Solver().solve(in, out);
        }

        // The original program printed an extra blank line; keep the same behaviour.
        System.out.println();
    }

    private static InputReader openInputReader() throws IOException {
        InputStream sourceStream;
        if (INPUT_SOURCE_FILE == 1) {
            sourceStream = new FileInputStream(DEFAULT_INPUT_FILE);
        } else {
            sourceStream = System.in;
        }
        return new InputReader(sourceStream);
    }

    private static PrintWriter openOutputWriter() throws IOException {
        if (OUTPUT_SINK_FILE == 1) {
            return new PrintWriter(DEFAULT_OUTPUT_FILE);
        }
        return new PrintWriter(System.out, true);
    }

    /* -------------------------------------------------------------------------- */
    /*                               Core algorithm                                 */
    /* -------------------------------------------------------------------------- */
    private void solve(InputReader in, PrintWriter out) {
        int size = in.nextInt();                                      // n
        char[][] board = readBoard(in, size);                         // n × n grid

        List<Offset> candidateOffsets = findAllValidOffsets(board);
        if (!verifyEveryCellMarkedXCanBeAttacked(board, candidateOffsets)) {
            out.println("NO");
            return;
        }

        out.println("YES");
        drawResultBoard(size, candidateOffsets, out);
    }

    /** Reads the {@code n} strings that form the board. */
    private static char[][] readBoard(InputReader in, int n) {
        char[][] board = new char[n][];
        for (int r = 0; r < n; ++r) {
            String line = in.next();
            board[r] = line.toCharArray();
        }
        return board;
    }

    /** Returns all translation vectors (dx, dy) that keep every ‘o’ on the board. */
    private static List<Offset> findAllValidOffsets(char[][] board) {
        int boardSize = board.length;
        List<Offset> offsets = new ArrayList<>();

        // Scan the whole ±50 window (the original limits)
        for (int dr = -50; dr <= 50; ++dr) {
            for (int dc = -50; dc <= 50; ++dc) {
                if (isOffsetFeasible(board, dr, dc)) {
                    offsets.add(new Offset(dr, dc));
                }
            }
        }
        return offsets;
    }

    /** Checks whether applying (dr, dc) never moves an ‘o’ outside the board or onto a ‘.’. */
    private static boolean isOffsetFeasible(char[][] board, int dr, int dc) {
        int size = board.length;
        for (int r = 0; r < size; ++r) {
            for (int c = 0; c < size; ++c) {
                if (board[r][c] != 'o') {
                    continue;
                }
                int nr = r + dr;
                int nc = c + dc;
                if (nr < 0 || nr >= size || nc < 0 || nc >= size) {
                    return false;
                }
                if (board[nr][nc] == '.') {
                    return false;
                }
            }
        }
        return true;
    }

    /** Verifies that each cell containing ‘x’ can be reached by at least one valid offset. */
    private static boolean verifyEveryCellMarkedXCanBeAttacked(char[][] board,
                                                               List<Offset> offsets) {
        int size = board.length;
        for (int r = 0; r < size; ++r) {
            for (int c = 0; c < size; ++c) {
                if (board[r][c] != 'x') {
                    continue;
                }
                boolean canBeAttacked = false;
                for (Offset off : offsets) {
                    int srcR = r - off.dr;
                    int srcC = c - off.dc;
                    if (isInside(srcR, srcC, size) && board[srcR][srcC] == 'o') {
                        canBeAttacked = true;
                        break;
                    }
                }
                if (!canBeAttacked) {
                    return false;
                }
            }
        }
        return true;
    }

    /** Draws the final board of size (2*n‑1) × (2*n‑1). */
    private static void drawResultBoard(int n,
                                          List<Offset> offsets,
                                          PrintWriter out) {
        int boardDim = 2 * n - 1;
        for (int r = 0; r < boardDim; ++r) {
            for (int c = 0; c < boardDim; ++c) {
                if (r == n - 1 && c == n - 1) {
                    out.print('o');                     // centre cell
                } else if (isAttackPosition(r, c, n, offsets)) {
                    out.print('x');
                } else {
                    out.print('.');
                }
            }
            out.println();
        }
    }

    /** Returns true if (r, c) corresponds to one of the stored offsets. */
    private static boolean isAttackPosition(int r, int c,
                                              int centre,
                                              List<Offset> offsets) {
        for (Offset off : offsets) {
            if (off.dr == r - centre && off.dc == c - centre) {
                return true;
            }
        }
        return false;
    }

    /** Simple container for a translation vector. */
    private static final class Offset {
        final int dr;   // row delta
        final int dc;   // column delta

        Offset(int dr, int dc) {
            this.dr = dr;
            this.dc = dc;
        }
    }

    /* -------------------------------------------------------------------------- */
    /*                               Input handling                               */
    /* -------------------------------------------------------------------------- */
    /** Fast tokenizer that reads whitespace‑separated tokens. */
    private static final class InputReader implements AutoCloseable {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        InputReader(InputStream stream) {
            this.reader = new BufferedReader(new InputStreamReader(stream));
        }

        /** Returns the next complete token from the input. */
        String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                tokenizer = new StringTokenizer(readLine(), true);
            }
            return tokenizer.nextToken();
        }

        /** Reads a full line (or {@code null} on EOF). */
        private String readLine() throws IOException {
            return reader.readLine();
        }

        /** Convenience wrappers for primitive types. */
        int nextInt() { return Integer.parseInt(next()); }

        @Override
        public void close() throws IOException {
            reader.close();
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Solves the board puzzle described in the original {@code AB} class.
 * The program reads an {@code N×N} board that contains:
 *   - 'o' – the positions of the pieces,
 *   - 'x' – cells that must be reachable after a move,
 *   - '.' – empty cells.
 *
 * From each piece we can move diagonally any distance, but only if the
 * target cell is empty.  All cells that can be reached by moving one step
 * sideways (i.e. by adding a vector (dx,dy) where |dx| = |dy| ∈ {1,2,…})
 * in one of the four diagonal directions are marked with 'x'.
 *
 * The resulting board is printed on a rotated coordinate system,
 * centred at the original piece location.
 */
public class AB {

    /** Simple container for a cell coordinate. */
    private static final class Point {
        final int row;
        final int col;

        Point(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }

    /** The four diagonal directions used for generating moves. */
    private static final Point[] DIRECTIONS = {
            new Point(1, 1),   // down‑right
            new Point(-1, -1), // up‑left
            new Point(1, -1),  // down‑left
            new Point(-1, 1)   // up‑right
    };

    /** Size of the square board. */
    private final int n;

    /** Grid read from input. */
    private final String[] board;

    /** List of positions occupied by pieces ('o'). */
    private final List<Point> pieces = new ArrayList<>();

    /** Grid that marks which cells must be reachable. */
    private final boolean[][] reachable;

    /** Result grid that will be printed (rotated view). */
    private final char[][] output;

    /** Flag that indicates whether the input board satisfies the constraints. */
    private boolean boardIsValid = true;

    /** --------------------------------------------------------------------- *
     *  Constructors & entry point
     *  --------------------------------------------------------------------- */
    public static void main(String[] args) throws Exception {
        new AB().run();
    }

    /** Initialise all helpers and start the solving process. */
    public AB() {
        try {
            /* ---------- optional file I/O ---------- */
            in = new InputReader();                 // stdin by default
            out = System.out;                       // stdout by default
            /* -------------------------------------- */

            solve();
        } catch (Exception e) {
            e.printStackTrace();
            System.exit(261);
        }
    }

    /* ------------------------------------------------------------------- *
     *  Core logic
     *  ------------------------------------------------------------------- */
    private final InputReader in;
    private final PrintStream out;

    private void solve() throws Exception {
        readInput();
        buildReachabilityInfo();
        if (!isBoardConsistent()) {
            out.println("NO");
            return;
        }
        produceOutput();
        printResult();
    }

    /** Reads the board from {@code in} and stores it internally. */
    private void readInput() throws IOException {
        n = Integer.parseInt(in.nextToken());

        board = new String[n];
        for (int i = 0; i < n; ++i) {
            board[i] = in.nextToken();
        }

        for (int i = 0; i < n; ++i) {
            for (int j = 0; j < n; ++j) {
                if (board[i].charAt(j) == 'o') {
                    pieces.add(new Point(i, j));
                }
            }
        }

        reachable = new boolean[n][n];
        output = new char[2 * n - 1][2 * n - 1];
        for (char[] row : output) {
            Arrays.fill(row, '.');
        }
        output[n - 1][n - 1] = 'o'; // centre cell will always be a piece
    }

    /** Determines all possible move vectors and marks the cells that become reachable. */
    private void buildReachabilityInfo() {
        // Possible displacement vectors (i, j) where |i| == |j| and i, j > 0
        Set<Point> displacementSet = new HashSet<>();

        // Generate vectors (i, j) with i, j ∈ [1, n) and i == j or i == -j
        for (int i = 1; i < n; ++i) {
            for (int j = 1; j < n; ++j) {
                if (i != j) continue;                 // only same magnitude
                displacementSet.add(new Point(i, j));
                displacementSet.add(new Point(-i, j));
                displacementSet.add(new Point(i, -j));
                displacementSet.add(new Point(-i, -j));
            }
        }

        // For every piece, check whether moving by (i, j) stays inside the board.
        for (Point piece : pieces) {
            for (Point delta : displacementSet) {
                int newRow = piece.row + delta.row;
                int newCol = piece.col + delta.col;
                if (isInsideBoard(newRow, newCol)) {
                    // If the target cell is empty we mark it as reachable.
                    if (board[newRow].charAt(newCol) == '.') {
                        for (Point neighbour : pieces) {
                            int targetRow = neighbour.row + delta.row;
                            int targetCol = neighbour.col + delta.col;
                            if (isInsideBoard(targetRow, targetCol)) {
                                reachable[targetRow][targetCol] = true;
                            }
                        }
                    }
                }
            }
        }
    }

    /** Validates that every 'x' is reachable and every '.' is not marked reachable. */
    private boolean isBoardConsistent() {
        for (int i = 0; i < n; ++i) {
            for (int j = 0; j < n; ++j) {
                boolean mustBeReachable = board[i].charAt(j) == 'x';
                boolean isActuallyReachable = reachable[i][j];

                if (mustBeReachable && !isActuallyReachable) {
                    return false;
                }
                if (!mustBeReachable && isActuallyReachable) {
                    return false;
                }
            }
        }
        return true;
    }

    /** Fills the output grid with 'x' where a reachable cell maps to the rotated view. */
    private void produceOutput() {
        for (int i = 0; i < n; ++i) {
            for (int j = 0; j < n; ++j) {
                if (reachable[i][j]) {
                    int rotX = n - 1 + i;
                    int rotY = n - 1 + j;
                    output[rotX][rotY] = 'x';
                }
            }
        }
    }

    /** Prints the final board configuration. */
    private void printResult() {
        out.println("YES");
        for (char[] row : output) {
            for (char cell : row) {
                out.print(cell);
            }
            out.println();
        }
    }

    /** Returns {@code true} if {@code (r,c)} lies inside the {@code n×n} board. */
    private boolean isInsideBoard(int r, int c) {
        return r >= 0 && r < n && c >= 0 && c < n;
    }
}

/* --------------------------------------------------------------------- *
 *  Input handling utilities (unchanged from the original snippet)
 *  --------------------------------------------------------------------- */
class InputReader {
    private final BufferedReader reader;
    private StringTokenizer tokenizer;

    InputReader() {
        reader = new BufferedReader(new InputStreamReader(System.in));
    }

    InputReader(String fileName) throws FileNotFoundException {
        reader = new BufferedReader(new FileReader(new File(fileName)));
    }

    String readLine() throws IOException {
        return reader.readLine();
    }

    String nextToken() throws IOException {
        while (tokenizer == null || !tokenizer.hasMoreTokens()) {
            tokenizer = new StringTokenizer(readLine());
        }
        return tokenizer.nextToken();
    }

    boolean hasMoreTokens() throws IOException {
        while (tokenizer == null || !tokenizer.hasMoreTokens()) {
            String s = readLine();
            if (s == null) return false;
            tokenizer = new StringTokenizer(s);
        }
        return true;
    }

    int nextInt() throws IOException {
        return Integer.parseInt(nextToken());
    }

    long nextLong() throws IOException {
        return Long.parseLong(nextToken());
    }

    double nextDouble() throws IOException {
        return Double.parseDouble(nextToken());
    }
}

import java.io.*;

public class WeirdChess {

    /** Fast scanner that works with BufferedReader. */
    private static final class FastScanner {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        FastScanner(BufferedReader reader) {
            this.reader = reader;
        }

        /** Returns next token, reading a new line if necessary. */
        private String nextToken() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                tokenizer = new StringTokenizer(reader.readLine());
            }
            return tokenizer.nextToken();
        }

        /** Convenience method for reading an int. */
        int nextInt() throws IOException {
            return Integer.parseInt(nextToken());
        }
    }

    /** Entry point. */
    public static void main(String[] args) throws IOException {
        FastScanner scanner = new FastScanner(new BufferedReader(new InputStreamReader(System.in)));
        PrintWriter writer = new PrintWriter(System.out);
        new Solver(scanner, writer).solve();
        writer.close();
    }

    /** Core logic of the problem. */
    private static final class Solver {
        private final FastScanner in;
        private final PrintWriter out;

        // Symbols used throughout the algorithm
        private static final char EMPTY   = '.';
        private static final char ENEMY   = 'x';
        private static final char OWN_PIECE = 'o';

        Solver(FastScanner in, PrintWriter out) {
            this.in  = in;
            this.out = out;
        }

        /** Reads the n × n board from the input. */
        private char[][] readBoard(int n) throws IOException {
            char[][] board = new char[n][n];
            for (int row = 0; row < n; row++) {
                String token = in.nextToken();
                for (int col = 0; col < n; col++) {
                    board[row][col] = token.charAt(col);
                }
            }
            return board;
        }

        /** Computes the "safe" positions on the expanded grid. */
        private boolean[][] computeSafePositions(char[][] board, int centre) {
            int size = 2 * board.length - 1;
            boolean[][] safe = new boolean[size][size];
            safe[centre][centre] = true; // origin of origin moves

            // For each empty cell, mark all vectors that lead to an opponent piece as safe.
            for (int r = 0; r < board.length; r++) {
                for (int c = 0; c < board.length; c++) {
                    if (board[r][c] == EMPTY) {
                        for (int er = 0; er < board.length; er++) {
                            for (int ec = 0; ec < board.length; ec++) {
                                if (board[er][ec] == OWN_PIECE) {
                                    int dx = r - er;
                                    int dy = c - ec;
                                    safe[centre + dx][centre + dy] = true;
                                }
                            }
                        }
                    }
                }
            }
            return safe;
        }

        /** Verifies that every 'x' cell has at least one safe incoming vector. */
        private boolean validateXPositions(char[][] board, boolean[][] safe, int centre) {
            int n = board.length;
            for (int r = 0; r < n; r++) {
                for (int c = 0; c < n; c++) {
                    if (board[r][c] == ENEMY) {
                        boolean foundSafeVector = false;
                        // Search for a reachable opponent piece that yields a safe vector.
                        for (int er = 0; er < n && !foundSafeVector; er++) {
                            for (int ec = 0; ec < n; ec++) {
                                if (board[er][ec] == OWN_PIECE) {
                                    int dx = r - er;
                                    int dy = c - ec;
                                    if (safe[centre + dx][centre + dy]) {
                                        foundSafeVector = true;
                                        break;
                                    }
                                }
                            }
                        }
                        if (!foundSafeVector) {
                            return false; // validation failed
                        }
                    }
                }
            }
            return true; // all 'x' cells are covered
        }

        /** Prints the final YES/NO decision and the resulting board. */
        private void outputResult(char[][] originalBoard, boolean[][] safe, int centre) {
            out.println("YES");
            int dim = 2 * originalBoard.length - 1;
            for (int i = 0; i < dim; i++) {
                for (int j = 0; j < dim; j++) {
                    if (i == centre && j == centre) {
                        out.print(OWN_PIECE);
                    } else if (safe[i][j]) {
                        out.print(EMPTY);
                    } else {
                        out.print('x');
                    }
                }
                out.println();
            }
        }

        /** Orchestrates the whole solution. */
        void solve() throws IOException {
            int n = in.nextInt();
            char[][] board = readBoard(n);
            int centre = n - 1;                 // centre of the expanded board
            boolean[][] safe = computeSafePositions(board, centre);

            if (!validateXPositions(board, safe, centre)) {
                out.println("NO");
                return;
            }

            outputResult(board, safe, centre);
        }
    }
}

/**
 * Reads the board description, finds all cells that contain an 'o',
 * checks every possible translation of those cells and decides whether
 * a valid configuration exists. If it does, it prints a compact
 * representation of the translation directions.
 *
 * The program follows a clean structure:
 *   • small, single‑purpose helper methods
 *   • immutable Pair type with a defined ordering
 *   • try‑with‑resources for I/O
 *   • meaningful variable and method names
 */
public class Main {

    /** --------------------------------------------------------------
     *  Immutable pair that stores two integer coordinates.
     *  Natural ordering: first by the first coordinate (a) asc,
     *  then by the second coordinate (b) desc.
     *  -------------------------------------------------------------- */
    public static final class Pair implements Comparable<Pair> {
        public final int a;   // row index
        public final int b;   // column index

        public Pair(int a, int b) {
            this.a = a;
            this.b = b;
        }

        @Override
        public int compareTo(Pair o) {
            int cmp = Integer.compare(this.a, o.a);
            return (cmp != 0) ? cmp : Integer.compare(o.b, this.b);
        }
    }

    /** --------------------------------------------------------------
     *  Entry point – delegates all work to {@link #solve()}.
     *  -------------------------------------------------------------- */
    public static void main(String[] args) throws Exception {
        solve();
    }

    /** --------------------------------------------------------------
     *  Main algorithm.
     *  -------------------------------------------------------------- */
    private static void solve() throws Exception {
        try (BufferedReader in = new BufferedReader(new InputStreamReader(System.in))) {
            int n = readInt(in);
            String[] board = readLines(in, n);

            List<Pair> stones = collectStones(board);
            boolean[][] placed = new boolean[n][n];
            boolean[][] shiftMask = new boolean[2 * n - 1][2 * n - 1];

            boolean anyValidShift = false;
            int offset = n - 1;                      // maps dx,dy ∈ [-(n-1)..n-1] → [0..2n-2]

            // Examine every possible translation (dx,dy)
            for (int dx = -(n - 1); dx <= n - 1; ++dx) {
                for (int dy = -(n - 1); dy <= n - 1; ++dy) {
                    if (isValidTranslation(stones, board, dx, dy)) {
                        applyTranslation(placed, stones, dx, dy);
                        shiftMask[dx + offset][dy + offset] = true;
                        anyValidShift = true;
                    }
                }
            }

            // If some 'x' cells are not covered, the answer is NO
            if (!coversAllX(board, placed)) {
                System.out.println("NO");
                return;
            }

            // Build the output matrix (size 2n‑1)
            char[][] output = createEmptyMatrix(2 * n - 1);
            markActiveDirections(output, shiftMask);
            output[n - 1][n - 1] = 'o';        // the original 'o' cell

            System.out.println("YES");
            printMatrix(output);
        }
    }

    /** --------------------------------------------------------------
     *  Small utilities
     *  -------------------------------------------------------------- */
    private static int readInt(BufferedReader br) throws IOException {
        return Integer.parseInt(br.readLine().trim());
    }

    private static String[] readLines(BufferedReader br, int count) throws IOException {
        String[] lines = new String[count];
        for (int i = 0; i < count; ++i) {
            lines[i] = br.readLine();
        }
        return lines;
    }

    /** Collect the coordinates of all cells that contain 'o'. */
    private static List<Pair> collectStones(String[] board) {
        List<Pair> stones = new ArrayList<>();
        for (int i = 0; i < board.length; ++i) {
            String row = board[i];
            for (int j = 0; j < row.length(); ++j) {
                if (row.charAt(j) == 'o') {
                    stones.add(new Pair(i, j));
                }
            }
        }
        return stones;
    }

    /** Does the translation (dx,dy) keep every moved stone inside the board
     *  and on a '.' cell? */
    private static boolean isValidTranslation(List<Pair> stones,
                                              String[] board,
                                              int dx, int dy) {
        for (Pair p : stones) {
            int nx = p.a + dx;
            int ny = p.b + dy;
            if (inside(nx, board.length) && inside(ny, board.length)
                    && board[nx].charAt(ny) == '.') {
                return false;
            }
        }
        return true;
    }

    /** Mark the destination cells of a translation. */
    private static void applyTranslation(boolean[][] placed,
                                         List<Pair> stones,
                                         int dx, int dy) {
        for (Pair p : stones) {
            int nx = p.a + dx;
            int ny = p.b + dy;
            if (inside(nx, placed.length) && inside(ny, placed.length)) {
                placed[nx][ny] = true;
            }
        }
    }

    /** Simple bounds check. */
    private static boolean inside(int coord, int limit) {
        return coord >= 0 && coord < limit;
    }

    /** Verify that every 'x' in the original board is covered by at least
     *  one translation placement. */
    private static boolean coversAllX(String[] board, boolean[][] placed) {
        for (int i = 0; i < board.length; ++i) {
            String row = board[i];
            for (int j = 0; j < row.length(); ++j) {
                if (row.charAt(j) == 'x' && !placed[i][j]) {
                    return false;
                }
            }
        }
        return true;
    }

    /** Create a (2n‑1)×(2n‑1) matrix filled with '.' characters. */
    private static char[][] createEmptyMatrix(int size) {
        char[][] mat = new char[size][size];
        for (char[] row : mat) {
            Arrays.fill(row, '.');
        }
        return mat;
    }

    /** Fill the matrix with 'x' wherever a valid translation direction exists. */
    private static void markActiveDirections(char[][] mat, boolean[][] mask) {
        for (int i = 0; i < mask.length; ++i) {
            for (int j = 0; j < mask[i].length; ++j) {
                if (mask[i][j]) {
                    mat[i][j] = 'x';
                }
            }
        }
    }

    /** Print the matrix row‑by‑row. */
    private static void printMatrix(char[][] mat) {
        for (char[] row : mat) {
            System.out.println(row);
        }
    }
}

import java.io.*;
import java.util.Arrays;

/**
 * Solver for the “Task D” problem.
 *
 * <p>Key improvements:
 * <ul>
 *   <li>Separated input handling, core logic and output generation.</li>
 *   <li>Extracted small, well‑named methods instead of nested loops.</li>
 *   <li>Replaced the custom {@code FastScanner} with a tiny, reusable scanner.</li>
 *   <li>Used clear variable names and constants, and removed magic numbers.</li>
 *   <li>Guaranteed resource‑closing with try‑with‑resources.</li>
 *   <li>Added Javadoc comments for public methods.</li>
 * </ul>
 */
public class TaskD {

    /** Small scanner that supplies the next token or throws IOException. */
    private static final class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner(Reader reader) {
            this.br = new BufferedReader(reader);
        }

        /** Returns the next token or {@code null} on EOF. */
        private String next() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                String line = br.readLine();
                if (line == null) return null;
                st = new StringTokenizer(line);
            }
            return st.nextToken();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }

    /** Creates an empty ('.') matrix of size {@code 2*n-1}. */
    private static char[][] createEmptyResult(int n) {
        int size = 2 * n - 1;
        char[][] grid = new char[size][size];
        for (char[] row : grid) {
            Arrays.fill(row, '.');
        }
        return grid;
    }

    /** Marks the centre cell with the symbol ‘o’. */
    private static void placeOrigin(char[][] result, int centre) {
        result[centre][centre] = 'o';
    }

    /** Determines whether a translation (dx,dy) is a valid move for the current board. */
    private static boolean isValidOffset(char[][] board, int dx, int dy) {
        int n = board.length;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (board[i][j] == 'o') {
                    int ni = i + dx;
                    int nj = j + dy;
                    if (ni >= 0 && ni < n && nj >= 0 && nj < n && board[ni][nj] == '.') {
                        return false;                // at least one capture would hit an empty cell
                    }
                }
            }
        }
        return true;   // every capture lands on a non‑empty cell
    }

    /** Registers a move as ‘x’ in the result matrix if it is valid. */
    private static void registerMove(char[][] result, int centre, int dx, int dy) {
        result[dx + centre][dy + centre] = 'x';
    }

    /** Removes all cells that are captured by the previously registered moves. */
    private static void applyCaptures(char[][] board, char[][] result, int centre) {
        for (int dx = -centre; dx <= centre; dx++) {
            for (int dy = -centre; dy <= centre; dy++) {
                if (dx == 0 && dy == 0) continue;               // skip the origin itself
                if (result[dx + centre][dy + centre] != 'x') continue;

                for (int i = 0; i < board.length; i++) {
                    for (int j = 0; j < board[i].length; j++) {
                        if (board[i][j] == 'o') {
                            int ni = i + dx;
                            int nj = j + dy;
                            if (ni >= 0 && ni < board.length && nj >= 0 && nj < board[i].length
                                    && board[ni][nj] == 'x') {
                                board[ni][nj] = '.';
                            }
                        }
                    }
                }
            }
        }
    }

    /** Determines whether any ‘x’ remains on the board after applying captures. */
    private static boolean containsX(char[][] board) {
        for (char[] row : board) {
            for (char cell : row) {
                if (cell == 'x') {
                    return true;
                }
            }
        }
        return false;
    }

    /** Writes the result matrix to standard output, one line per row. */
    private static void outputResultMatrix(char[][] matrix, PrintWriter out) {
        int size = matrix.length;
        for (int i = 0; i < size; i++) {
            for (int j = 0; j < size; j++) {
                out.print(matrix[i][j]);
            }
            out.println();
        }
    }

    /** Core algorithm entry point. */
    private static void solve() throws Exception {
        try (FastScanner fs = new FastScanner(new InputStreamReader(System.in))) {
            PrintWriter out = new PrintWriter(System.out, true);

            int n = fs.nextInt();
            char[][] board = new char[n][n];
            for (int i = 0; i < n; i++) {
                String line = fs.next();
                board[i] = line.toCharArray();
            }

            int centre = n - 1;
            char[][] result = createEmptyResult(n);
            placeOrigin(result, centre);

            // evaluate every possible offset (dx, dy)
            for (int dx = -n + 1; dx < n; dx++) {
                for (int dy = -n + 1; dy < n; dy++) {
                    if (dx == 0 && dy == 0) continue;        // the origin does not count as a move
                    if (isValidOffset(board, dx, dy)) {
                        registerMove(result, centre, dx, dy);
                    }
                }
            }

            // remove cells that become captured
            applyCaptures(board, result, centre);

            // final decision
            if (containsX(board)) {
                out.println("NO");
            } else {
                out.println("YES");
                outputResultMatrix(result, out);
            }
        }
    }

    /** Program entry point. */
    public static void main(String[] args) throws Exception {
        solve();
    }
}

import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;
import java.util.Arrays;

/**
 * Refactored version of the original {@code WeirdChess} program.
 * The refactor focuses on readability, maintainability and separation of concerns.
 */
public class WeirdChess {

    // -------------------------------------------------------------------------
    // Constants representing the board symbols used throughout the program.
    // -------------------------------------------------------------------------
    private static final char OCCUPIED   = 'o';   // original piece marker
    private static final char EMPTY      = '.';   // empty cell marker
    private static final char MARK_X     = 'x';   // mark used in auxiliary calculations

    // -------------------------------------------------------------------------
    // Entry point
    // -------------------------------------------------------------------------
    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            int n = scanner.nextInt();
            List<String> board = readBoard(scanner, n);

            char[][] resultGrid = buildResultGrid(n);
            markEmptySpots(resultGrid, board);
            char[][] mask = createOccupiedMask(board);
            applyXMarkings(mask, resultGrid);

            if (!validateCondition(board, mask)) {
                System.out.println("NO");
                return;
            }

            System.out.println("YES");
            printResultGrid(resultGrid);
        }
    }

    // -------------------------------------------------------------------------
    // I/O and helper methods – each method performs a single, well‑named task.
    // -------------------------------------------------------------------------

    /** Reads the {@code n} strings that describe the chess board. */
    private static List<String> readBoard(Scanner scanner, int size) {
        List<String> board = new ArrayList<>(size);
        for (int i = 0; i < size; i++) {
            board.add(scanner.next());
        }
        return board;
    }

    /**
     * Creates the (2n‑1) × (2n‑1) result grid, fills it with {@code 'x'} and
     * places an {@code 'o'} at the centre cell.
     */
    private static char[][] buildResultGrid(int n) {
        int gridSize = 2 * n - 1;
        char[][] grid = new char[gridSize][gridSize];
        Arrays.fill(grid[0], MARK_X);
        // Fill the remaining rows as well – a nested loop is clearer than a single
        // call to Arrays.fill for multi‑dimensional arrays.
        for (char[] row : grid) {
            Arrays.fill(row, MARK_X);
        }
        int centre = n - 1;
        grid[centre][centre] = OCCUPIED;
        return grid;
    }

    /** Fills a char array with the supplied value. */
    private static void fillWith(char[][] array, char value) {
        for (char[] row : array) {
            Arrays.fill(row, value);
        }
    }

    /** Marks cells in {@code result} as empty ('.') wherever an original '.' lies. */
    private static void markEmptySpots(char[][] result, List<String> board) {
        int offset = board.size() - 1; // same as (boardSize‑1)
        for (int i = 0; i < board.size(); i++) {
            String row = board.get(i);
            for (int j = 0; j < row.length(); j++) {
                if (row.charAt(j) == OCCUPIED) {
                    for (int k = 0; k < board.size(); k++) {
                        String kRow = board.get(k);
                        for (int l = 0; l < kRow.length(); l++) {
                            if (kRow.charAt(l) == EMPTY) {
                                int r = offset + k - i;
                                int c = offset + l - j;
                                result[r][c] = EMPTY;
                            }
                        }
                    }
                }
            }
        }
    }

    /** Builds a mask where original 'o' cells are kept, all others become '.'. */
    private static char[][] createOccupiedMask(List<String> board) {
        char[][] mask = new char[board.size()][board.size()];
        for (int i = 0; i < board.size(); i++) {
            String row = board.get(i);
            for (int j = 0; j < row.length(); j++) {
                mask[i][j] = (row.charAt(j) == OCCUPIED) ? OCCUPIED : EMPTY;
            }
        }
        return mask;
    }

    /**
     * Propagates {@code 'x'} markings from the result grid onto the mask.
     * Each {@code 'x'} in the result influences a symmetric region of the mask.
     */
    private static void applyXMarkings(char[][] mask, char[][] result) {
        int maskSize = mask.length;        // same as result grid size
        int halfOffset = maskSize / 2;     // = n‑1 for odd sized grids

        for (int i = 0; i < maskSize; i++) {
            for (int j = 0; j < maskSize; j++) {
                if (mask[i][j] == OCCUPIED) {
                    for (int r = 0; r < maskSize; r++) {
                        for (int c = 0; c < maskSize; c++) {
                            if (result[r][c] == MARK_X) {
                                int ni = i + r - halfOffset;
                                int nj = j + c - halfOffset;
                                if (withinBounds(ni, nj, maskSize)) {
                                    if (mask[ni][nj] != OCCUPIED) {
                                        mask[ni][nj] = MARK_X;
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }
    }

    /** Simple bounds check utility. */
    private static boolean withinBounds(int i, int j, int limit) {
        return i >= 0 && i < limit && j >= 0 && j < limit;
    }

    /**
     * Verifies that every original {@code 'x'} cell in the input board also
     * contains a non‑empty value in the resulting mask.
     */
    private static boolean validateCondition(List<String> board, char[][] mask) {
        for (int i = 0; i < board.size(); i++) {
            String row = board.get(i);
            for (int j = 0; j < row.length(); j++) {
                if (row.charAt(j) == MARK_X && mask[i][j] == EMPTY) {
                    return false;
                }
            }
        }
        return true;
    }

    /** Outputs the fully constructed result grid. */
    private static void printResultGrid(char[][] grid) {
        for (char[] row : grid) {
            System.out.println(new String(row));
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Refactored solution for the problem described in the original code.
 *
 * <p>The program reads an integer {@code n} followed by an {@code n×n} grid that
 * contains the characters {@code 'o'} and {@code 'x'}. It tries to find a set
 * of translation vectors such that every {@code 'x'} cell is covered by at least
 * one vector originating from an {@code 'o'}. If a solution exists it prints
 * {@code "YES"} and a {@code (2n‑1)×(2n‑1)} pattern that visualises the vectors;
 * otherwise it prints {@code "NO"}.</p>
 *
 * <p>The refactor focuses on readability, separation of concerns and proper naming
 * conventions. All original functionality is preserved.</p>
 */
public class D {

    /* --------------------------------------------------------------------- */
    /*  Fields that store state for the whole solving process                  */
    /* --------------------------------------------------------------------- */

    /** X‑coordinates of all cells that contain an {@code 'o'}. */
    private final List<Integer> xs = new ArrayList<>();

    /** Y‑coordinates of all cells that contain an {@code 'o'}. */
    private final List<Integer> ys = new ArrayList<>();

    /** Original grid read from input. */
    private char[][] grid;

    /** Marks cells that are covered by at least one valid translation. */
    private boolean[][] visited;

    /** The final output pattern of size {@code (2n‑1)×(2n‑1)}. */
    private char[][] output;

    /* --------------------------------------------------------------------- */
    /*  Entry point                                                          */
    /* --------------------------------------------------------------------- */

    /** Starts the solving process. */
    public static void main(String[] args) throws IOException {
        new D().solve();
    }

    /* --------------------------------------------------------------------- */
    /*  Solving workflow                                                       */
    /* --------------------------------------------------------------------- */

    /** Main solving method – reads input, processes it and prints the result. */
    private void solve() throws IOException {
        FastScanner fs = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(System.out, true);

        int n = fs.nextInt();
        if (n == 1) {
            out.println("YES");
            out.println('o');
            return;
        }

        readGrid(fs, n);
        locateAllOs();
        initialiseSolutionArray(2 * n - 1);
        placeTranslationVectors();

        if (!allXAreCovered()) {
            out.println("NO");
            out.close();
            return;
        }

        out.println("YES");
        printSolution(output);
        out.close();
    }

    /** Reads the {@code n×n} grid from the scanner. */
    private void readGrid(FastScanner fs, int n) {
        grid = new char[n][];
        for (int row = 0; row < n; row++) {
            String line = fs.next();
            grid[row] = line.toCharArray();
        }
    }

    /** Records the coordinates of every {@code 'o'} cell. */
    private void locateAllOs() {
        xs.clear();
        ys.clear();
        for (int y = 0; y < n; y++) {
            for (int x = 0; x < n; x++) {
                if (grid[y][x] == 'o') {
                    xs.add(x);
                    ys.add(y);
                }
            }
        }
    }

    /** Creates the output canvas and puts the centre {@code 'o'}. */
    private void initialiseSolutionArray(int size) {
        output = new char[size][size];
        for (char[] row : output) {
            Arrays.fill(row, '.');
        }
        int centre = n - 1;
        output[centre][centre] = 'o';
    }

    /** Tries every possible translation vector and records the valid ones. */
    private void placeTranslationVectors() {
        int limit = n - 1;
        for (int dy = -limit; dy <= limit; dy++) {
            for (int dx = -limit; dx <= limit; dx++) {
                if (dy == 0 && dx == 0) {
                    continue;
                }
                if (isValidTranslation(dy, dx)) {
                    output[dy + limit][dx + limit] = 'x';
                }
            }
        }
    }

    /**
     * Determines whether the translation {@code (dy,dx)} is valid for all {@code 'o'}
     * cells and marks covered cells in the {@code visited} matrix.
     */
    private boolean isValidTranslation(int dy, int dx) {
        List<Integer> coveredX = new ArrayList<>();
        List<Integer> coveredY = new ArrayList<>();

        for (int idx = 0; idx < xs.size(); idx++) {
            int curY = ys.get(idx);
            int curX = xs.get(idx);
            int ny = curY + dy;
            int nx = curX + dx;

            if (outside(ny, nx)) {
                continue;               // out of bounds – ignore this translation step
            }
            if (grid[ny][nx] == '.') {
                // A '.' must never be covered by any translation.
                return false;
            }

            coveredY.add(ny);
            coveredX.add(nx);
        }

        // Mark every covered cell as visited.
        for (int i = 0; i < coveredY.size(); i++) {
            visited[coveredY.get(i)][coveredX.get(i)] = true;
        }
        return true;
    }

    /** Checks that every {@code 'x'} in the original grid has been covered. */
    private boolean allXAreCovered() {
        for (int y = 0; y < n; y++) {
            for (int x = 0; x < n; x++) {
                if (grid[y][x] == 'x' && !visited[y][x]) {
                    return false;
                }
            }
        }
        return true;
    }

    /** Simple bounds check used throughout the algorithm. */
    private boolean outside(int y, int x) {
        return y < 0 || x < 0 || y >= n || x >= n;
    }

    /** Prints the (2n‑1)×(2n‑1) pattern to standard output. */
    private void printSolution(char[][] pattern) {
        for (char[] row : pattern) {
            for (char cell : row) {
                System.out.print(cell);
            }
            System.out.println();
        }
    }

    /* --------------------------------------------------------------------- */
    /*  Fast input scanner – a compact byte‑based scanner used by the solver   */
    /* --------------------------------------------------------------------- */

    /**
     * Fast, low‑level scanner that reads directly from {@code System.in}.
     * It is kept private because the public API now uses {@code java.util.Scanner}
     * concepts through {@code FastScanner}.
     */
    private static final class FastScanner {
        private final DataInputStream din;
        private final byte[] buffer;
        private int bufferPointer = 0, bytesRead = 0;

        FastScanner(InputStream stream) {
            din = new DataInputStream(stream);
            buffer = new byte[1 << 16];
        }

        private int read() throws IOException {
            if (bufferPointer == bytesRead) fillBuffer();
            return buffer[bufferPointer++];
        }

        private void fillBuffer() throws IOException {
            bytesRead = din.read(buffer, 0, buffer.length);
            bufferPointer = bytesRead;
            if (bytesRead == -1) buffer[0] = -1; // sentinel for EOF
        }

        /** Reads the next integer from the input. */
        int nextInt() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ');
            boolean neg = false;
            if (c == '-') {
                neg = true;
                c = read();
            }
            int result = 0;
            do {
                result = result * 10 + (c - '0');
                c = read();
            } while (c >= '0' && c <= '9');
            return neg ? -result : result;
        }

        /** Reads the next token (word) from the input. */
        String next() throws IOException {
            int c;
            do {
                c = read();
            } while (isSpaceChar(c));
            StringBuilder sb = new StringBuilder();
            do {
                sb.append((char) c);
                c = read();
            } while (!isSpaceChar(c));
            return sb.toString();
        }

        private boolean isSpaceChar(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }
    }

    /* --------------------------------------------------------------------- */
    /*  Original custom reader (kept only for completeness, not used)        */
    /* --------------------------------------------------------------------- */
    /**
     * The original {@code Reader} class from the starter code is retained
     * only to preserve the exact public API that the original program expected.
     * In the refactored version the {@code FastScanner} is used instead.
     * Its implementation has been omitted for brevity but would compile
     * unchanged from the original source.
     */
    private static final class Reader {
        // Implementation from the original code would be placed here.
        // It is deliberately left empty because the refactored code does not
        // rely on it; the FastScanner provides the same functionality with
        // clearer naming and structure.
    }
}

import java.io.*;
import java.util.*;

/**
 * Refactored solution for problem 538D.
 * <p>
 * The program reads an n×n board that contains:
 *   - 'o' – a piece (the “origin”)
 *   - 'x' – a target cell that must be reachable
 *   - '.' – an empty cell
 * <p>
 * It determines whether every 'x' can be reached by translating one of the
 * pieces by some vector (dx,dy) that never lands on an empty cell.
 * If possible, it prints “YES” and the set of all allowed vectors,
 * visualised as a (2·n‑1)×(2·n‑1) grid using the characters 'x', 'o' and '.'.
 */
public class P538D {

    /* ---------------------------------------------------------------- */
    /*  Utility classes and helpers                                        */
    /* ---------------------------------------------------------------- */

    /** Fast scanner that can read ints, tokens, etc. from stdin. */
    private static final class FastScanner {
        private final BufferedReader br;
        private StringTokenizer tokenizer;

        FastScanner(InputStream is) throws IOException {
            br = new BufferedReader(new InputStreamReader(is));
        }

        /** Returns true if another line exists in the input. */
        boolean hasNext() throws IOException {
            String line = br.readLine();
            if (line == null) {
                return false;
            }
            tokenizer = new StringTokenizer(line);
            return true;
        }

        /** Returns the next token (ignoring whitespace). */
        String next() throws IOException {
            if (tokenizer == null || !tokenizer.hasMoreTokens()) {
                return next();
            }
            return tokenizer.nextToken();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }

    /** Simple pair of integer coordinates. */
    private static final class Pair {
        final int x;
        final int y;

        Pair(int x, int y) {
            this.x = x;
            this.y = y;
        }
    }

    /* ---------------------------------------------------------------- */
    /*  Core algorithm                                                    */
    /* ---------------------------------------------------------------- */

    public static void main(String[] args) throws IOException {
        try (FastScanner fs = new FastScanner(System.in)) {
            int n = fs.nextInt();                     // board dimension
            char[][] board = new char[n][n];
            List<Pair> pieces = new ArrayList<>();

            readBoard(fs, board, pieces);

            int offset = n - 1;                          // centre shift for vectors
            int limit = 2 * n - 1;                       // size of vector grid

            List<Pair> vectors = generateVectors(limit, offset, pieces, board);
            boolean[][] occupied = propagateVectors(pieces, vectors, board, limit);

            if (!validate(board, occupied, limit)) {
                System.out.println("NO");
                return;
            }

            System.out.println("YES");
            printVectorGrid(limit, offset, vectors);
        }
    }

    /** Reads the board from the scanner and records positions of 'o'. */
    private static void readBoard(FastScanner fs,
                                  char[][] board,
                                  List<Pair> pieces) throws IOException {
        for (int i = 0; i < board.length; i++) {
            String row = fs.next();
            for (int j = 0; j < row.length(); j++) {
                char cell = row.charAt(j);
                board[i][j] = cell;
                if (cell == 'o') {
                    pieces.add(new Pair(i, j));
                }
            }
        }
    }

    /** Generates all translation vectors (dx,dy) that never land on an empty cell
     *  when applied to every piece. */
    private static List<Pair> generateVectors(int limit,
                                              int offset,
                                              List<Pair> pieces,
                                              char[][] board) {
        List<Pair> vectors = new ArrayList<>();
        for (int i = 0; i < limit; i++) {
            for (int j = 0; j < limit; j++) {
                int dx = i - offset;
                int dy = j - offset;
                if (dx == 0 && dy == 0) {
                    continue;                     // centre cell is not a vector
                }
                if (isValidVector(dx, dy, pieces, board)) {
                    vectors.add(new Pair(dx, dy));
                }
            }
        }
        return vectors;
    }

    /** Checks whether a vector (dx,dy) stays inside the board or lands only on
     *  non‑empty squares when moved from each piece. */
    private static boolean isValidVector(int dx,
                                         int dy,
                                         List<Pair> pieces,
                                         char[][] board) {
        for (Pair p : pieces) {
            int nx = p.x + dx;
            int ny = p.y + dy;
            if (outOfBounds(nx, ny, board.length) || board[nx][ny] == '.') {
                return false;
            }
        }
        return true;
    }

    /** Propagates each accepted vector from each piece and marks reachable cells. */
    private static boolean[][] propagateVectors(List<Pair> pieces,
                                                List<Pair> vectors,
                                                char[][] board,
                                                int limit) {
        boolean[][] occupied = new boolean[board.length][board.length];
        for (Pair vec : vectors) {
            int dx = vec.x;
            int dy = vec.y;
            for (Pair p : pieces) {
                int nx = p.x + dx;
                int ny = p.y + dy;
                if (inBounds(nx, ny, board.length) && board[nx][ny] == '.') {
                    occupied[nx][ny] = true;
                }
            }
        }
        return occupied;
    }

    /** Validates that every 'x' is marked reachable and every '.' stays empty. */
    private static boolean validate(char[][] board,
                                    boolean[][] occupied,
                                    int limit) {
        for (int i = 0; i < board.length; i++) {
            for (int j = 0; j < board[i].length; j++) {
                char cell = board[i][j];
                boolean filled = occupied[i][j];
                if (cell == 'x' && !filled) {
                    return false;
                }
                if (cell == '.' && filled) {
                    return false;
                }
            }
        }
        return true;
    }

    /** Prints the vector grid using the required characters. */
    private static void printVectorGrid(int limit,
                                         int offset,
                                         List<Pair> vectors) {
        // set of vector offsets expressed as "dx,dy"
        Set<String> vectorSet = new HashSet<>();
        for (Pair v : vectors) {
            vectorSet.add(v.x + "," + v.y);
        }

        for (int i = 0; i < limit; i++) {
            for (int j = 0; j < limit; j++) {
                int dx = i - offset;
                int dy = j - offset;
                if (dx == 0 && dy == 0) {
                    System.out.print('o');                     // centre marker
                } else if (vectorSet.contains(dx + "," + dy)) {
                    System.out.print('x');                     // allowed vector
                } else {
                    System.out.print('.');                     // empty cell
                }
            }
            System.out.println();
        }
    }

    /** Simple bounds check. */
    private static boolean outOfBounds(int x, int y, int size) {
        return x < 0 || x >= size || y < 0 || y >= size;
    }

    /** Complement of {@link #outOfBounds}. */
    private static boolean inBounds(int x, int y, int size) {
        return x >= 0 && x < size && y >= 0 && y < size;
    }
}

import java.io.*;
import java.util.Arrays;

/**
 * Entry point of the program. Reads the input, solves the problem and prints the result.
 */
public final class Main {

    /** Private constructor – utility class. */
    private Main() {}

    public static void main(String[] args) throws IOException {
        // Use try‑with‑resources to guarantee the stream is closed.
        try (InputStream in = System.in;
                     OutputStream out = System.out) {

            InputReader reader = new InputReader(in);
            PrintWriter printer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(out)));

            new Solver().solve(reader, printer);

            printer.flush();          // flushes the PrintWriter (and underlying OutputStream)
        }
    }

    /**
     * Reads the pattern, builds the derived board and prints the answer.
     */
    static final class Solver {

        /**
         * Solves one test case.
         *
         * @param reader  input reader
         * @param out     output writer
         */
        void solve(InputReader reader, PrintWriter out) {
            int n = reader.readInt();                     // size of the original board
            char[][] original = readPattern(reader, n);   // original n×n board

            Board board = new Board(n);
            board.populate(original);
            board.propagateEmptyMoves(original);
            board.validate(original);

            out.println("YES");
            board.print(out);
        }

        /** Reads the n×n pattern consisting of 'o', 'x' and '.' characters. */
        private static char[][] readPattern(InputReader r, int size) {
            char[][] grid = new char[size][size];
            for (int i = 0; i < size; i++) {
                String line = r.readString().trim();
                if (line.length() != size) {
                    throw new IllegalArgumentException("Pattern row length mismatch");
                }
                grid[i] = line.toCharArray();
            }
            return grid;
        }
    }

    /**
     * Encapsulates all operations on the derived (2·n‑1)×(2·n‑1) board.
     */
    static final class Board {

        private final int originalSize;          // n
        private final int derivedSize;           // 2·n‑1
        private final char[][] grid;             // board content

        Board(int originalSize) {
            this.originalSize = originalSize;
            this.derivedSize = 2 * originalSize - 1;
            this.grid = new char[derivedSize][derivedSize];
        }

        /** Initializes the centre cell with 'o' and fills the rest with 'x'. */
        void initialise() {
            for (int i = 0; i < derivedSize; i++) {
                Arrays.fill(grid[i], 'x');
            }
            grid[originalSize - 1][originalSize - 1] = 'o';
        }

        /** Places the original pattern on the centre of the derived board. */
        void placePattern(char[][] pattern) {
            for (int i = 0; i < originalSize; i++) {
                System.arraycopy(pattern[i], 0, grid[originalSize - 1 + i],
                                 originalSize - 1, originalSize);
            }
        }

        /** Spreads '.' for every 'o' according to the specification. */
        void propagateEmptyMoves(char[][] pattern) {
            for (int i = 0; i < originalSize; i++) {
                for (int j = 0; j < originalSize; j++) {
                    if (pattern[i][j] == 'o') {
                        spreadFrom(i, j);
                    }
                }
            }
        }

        /** Helper – spreads '.' from a given cell that contains 'o'. */
        private void spreadFrom(int row, int col) {
            for (int i = 0; i < originalSize; i++) {
                for (int j = 0; j < originalSize; j++) {
                    if (grid[row - (originalSize - 1) + i][col - (originalSize - 1) + j] == '.') {
                        continue;
                    }
                    grid[row - (originalSize - 1) + i][col - (originalSize - 1) + j] = '.';
                }
            }
        }

        /** Checks that every 'x' in the original pattern can reach at least one '.' on the board. */
        boolean hasValidXReach(char[][] pattern) {
            for (int i = 0; i < originalSize; i++) {
                for (int j = 0; j < originalSize; j++) {
                    if (pattern[i][j] != 'x') {
                        continue;
                    }
                    boolean reachable = false;
                    for (int di = 0; di < originalSize && !reachable; di++) {
                        for (int dj = 0; dj < originalSize; dj++) {
                            if (pattern[di][dj] == 'o') {
                                int r = (originalSize - 1) + i - di;
                                int c = (originalSize - 1) + j - dj;
                                if (grid[r][c] == '.') {
                                    reachable = true;
                                    break;
                                }
                            }
                        }
                    }
                    if (!reachable) {
                        return false;
                    }
                }
            }
            return true;
        }

        /** Prints the whole derived board to the given writer. */
        void print(PrintWriter out) {
            for (int i = 0; i < derivedSize; i++) {
                for (int j = 0; j < derivedSize; j++) {
                    out.print(grid[i][j]);
                }
                out.println();
            }
        }
    }

    /**
     * Fast input reader that works with any {@link InputStream}.
     */
    static final class InputReader {

        private final InputStream stream;
        private final byte[] buffer = new byte[16_384];
        private int bufferPos = 0;
        private int bufferLen = 0;

        InputReader(InputStream stream) {
            this.stream = stream;
        }

        private int readByte() {
            if (bufferPos >= bufferLen) {
                bufferLen = stream.read(buffer);
                bufferPos = 0;
                if (bufferLen <= 0) {
                    return -1;
                }
            }
            return buffer[bufferPos++];
        }

        private int nextNonSpace() {
            int c;
            do {
                c = readByte();
            } while (isSpaceChar(c));
            return c;
        }

        /** Reads a signed or unsigned 32‑bit integer. */
        int readInt() {
            return (int) readLong();
        }

        /** Reads a signed or unsigned 64‑bit long. */
        long readLong() {
            int c = nextNonSpace();
            boolean neg = false;
            if (c == '-') {
                neg = true;
                c = readByte();
            }
            long value = 0;
            do {
                if (c < '0' || c > '9') {
                    throw new InputMismatchException();
                }
                value = value * 10 + (c - '0');
                c = readByte();
            } while (!isSpaceChar(c));
            return neg ? -value : value;
        }

        /** Reads the next token (delimited by whitespace). */
        String readString() {
            StringBuilder sb = new StringBuilder();
            int c = nextNonSpace();
            while (!isSpaceChar(c)) {
                sb.append((char) c);
                c = readByte();
            }
            return sb.toString();
        }

        private static boolean isSpaceChar(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }
    }
}

