/**
 * Reads the board, analyses the situation and prints the result.
 */
class Solver {

    /** Size of the board. */
    private int n;

    /** Original characters read from the input. */
    private char[][] board;

    /** All cells that contain an 'o' piece. */
    private final List<Position> pieces = new ArrayList<>();

    /** Cells that are considered “under attack” (i.e. non‑empty squares). */
    private boolean[][] isAttacked;

    /** Marks the displacements that would hit every attacked cell. */
    private boolean[][] rookHit;

    /** Tracks which cells become shielded when a rook is placed at a given
        displacement – used for validation. */
    private boolean[][] shielded;

    /** All valid displacements that satisfy the problem constraints. */
    private final Set<Position> validMoves = new HashSet<>();

    /** Solves the problem for the supplied scanner and writer. */
    public void solve(FastScanner scanner, PrintWriter out) {
        readInput(scanner);
        computeAttacks();
        findPotentialRookMoves();
        if (!verifyCoverage()) {
            out.println("NO");
            return;
        }
        printAnswer(out);
    }

    /** Parses the board description from the scanner. */
    private void readInput(FastScanner scanner) {
        n = scanner.nextInt();
        board = new char[n][];
        isAttacked = new boolean[n][n];
        int pieceCount = 0;

        for (int r = 0; r < n; r++) {
            board[r] = scanner.next().toCharArray();
            for (int c = 0; c < n; c++) {
                char cell = board[r][c];
                if (cell != '.') {
                    isAttacked[r][c] = true;
                }
                if (cell == 'o') {
                    pieces.add(new Position(r, c));
                }
            }
        }
        // pieceCount is no longer needed; we keep the list of positions.
    }

    /** Determines which cells are under attack – already prepared during input. */
    private void computeAttacks() {
        // The board parsing step already filled isAttacked.
    }

    /** Finds every rook displacement that would also attack all currently
        attacked cells and records it. */
    private void findPotentialRookMoves() {
        rookHit = new boolean[2 * n - 1][2 * n - 1];
        shielded = new boolean[n][n];

        // Cells occupied by existing pieces are considered already shielded.
        for (Position p : pieces) {
            shielded[p.row][p.col] = true;
        }

        // Scan every possible rook displacement.
        for (int dr = -(n - 1); dr <= n - 1; dr++) {
            for (int dc = -(n - 1); dc <= n - 1; dc++) {
                if (isMoveConsistent(dr, dc)) {
                    int shiftedRow = n - 1 + dr;
                    int shiftedCol = n - 1 + dc;
                    rookHit[shiftedRow][shiftedCol] = true;
                    applyShieldEffect(dr, dc);
                }
            }
        }
    }

    /** Returns true iff a rook placed with displacement (dr, dc) would attack
        every cell that is currently under attack. */
    private boolean isMoveConsistent(int dr, int dc) {
        for (Position p : pieces) {
            int nr = p.row + dr;
            int nc = p.col + dc;
            if (!isInsideBoard(nr, nc)) {
                continue;
            }
            if (!isAttacked[nr][nc]) {
                return false;
            }
        }
        return true;
    }

    /** Marks the cells that become protected when a rook is placed at
        (dr, dc). */
    private void applyShieldEffect(int dr, int dc) {
        for (Position p : pieces) {
            int nr = p.row + dr;
            int nc = p.col + dc;
            if (isInsideBoard(nr, nc)) {
                shielded[nr][nc] = true;
            }
        }
    }

    /** Verifies that the shielding matrix exactly matches the attack matrix.
        If it does, all valid moves are collected for later printing. */
    private boolean verifyCoverage() {
        for (int r = 0; r < n; r++) {
            for (int c = 0; c < n; c++) {
                if (shielded[r][c] != isAttacked[r][c]) {
                    return false;
                }
            }
        }

        // Convert the boolean hit‑matrix into a set of Position objects.
        for (int i = 0; i < rookHit.length; i++) {
            for (int j = 0; j < rookHit[i].length; j++) {
                if (rookHit[i][j]) {
                    int dr = i - (n - 1);
                    int dc = j - (n - 1);
                    validMoves.add(new Position(dr, dc));
                }
            }
        }
        return true;
    }

    /** Writes the required YES/NO answer and the resulting board layout. */
    private void printAnswer(PrintWriter out) {
        out.println("YES");
        for (int r = 0; r < rookHit.length; r++) {
            for (int c = 0; c < rookHit[r].length; c++) {
                if (r == n - 1 && c == n - 1) {
                    out.print('o');
                } else if (rookHit[r][c]) {
                    out.print('x');
                } else {
                    out.print('.');
                }
            }
            out.println();
        }
    }

    /** Simple immutable coordinate holder. */
    private static final class Position {
        final int row;
        final int col;

        Position(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }

    /** Helper to test whether a board index is inside the n×n board. */
    private boolean isInsideBoard(int r, int c) {
        return r >= 0 && r < n && c >= 0 && c < n;
    }
}

/**
 * Fast scanner that works with any {@link InputStream}.
 */
class FastScanner {

    private final BufferedReader br;
    private StringTokenizer st;

    FastScanner(InputStream stream) {
        this.br = new BufferedReader(new InputStreamReader(stream));
    }

    /** Returns the next token from the input stream. */
    public String next() {
        while (st == null || !st.hasMoreTokens()) {
            try {
                st = new StringTokenizer(br.readLine());
            } catch (IOException e) {
                throw new UncheckedIOException(e);
            }
        }
        return st.nextToken();
    }

    /** Convenience method for reading an integer. */
    public int nextInt() {
        return Integer.parseInt(next());
    }
}

