/**
 * Simple wrapper around {@link BufferedReader} that returns the next token
 * and parses integers.
 */
final class InputReader {
    private final BufferedReader reader;
    private StringTokenizer tokenizer;

    InputReader(InputStream stream) {
        this.reader = new BufferedReader(new InputStreamReader(stream), 32768);
    }

    /** Returns the next token or reads a new line if the current tokenizer is exhausted. */
    private String nextToken() {
        while (tokenizer == null || !tokenizer.hasMoreTokens()) {
            try {
                tokenizer = new StringTokenizer(reader.readLine());
            } catch (IOException e) {
                throw new UncheckedIOException(e);
            }
        }
        return tokenizer.nextToken();
    }

    /** Convenience method used by the solver – reads exactly {@code count} tokens. */
    String[] nextLines(int count) {
        String[] lines = new String[count];
        for (int i = 0; i < count; i++) {
            lines[i] = nextToken();
        }
        return lines;
    }

    /** Reads the next token as an {@code int}. */
    int nextInt() {
        return Integer.parseInt(nextToken());
    }
}

/**
 * Core logic of the problem – computes whether a set of allowed shifts can
 * explain every 'x' on the board and, if so, prints one possible layout of the
 * shifts.
 */
final class Solver {

    /** Point used for representing coordinates; immutable and overrides {@code equals} / {@code hashCode}. */
    private static final class Point {
        final int x;
        final int y;

        Point(int x, int y) {
            this.x = x;
            this.y = y;
        }

        @Override
        public boolean equals(Object o) {
            if (this == o) return true;
            if (o == null || getClass() != o.getClass()) return false;
            Point point = (Point) o;
            return x == point.x && y == point.y;
        }

        @Override
        public int hashCode() {
            return Objects.hash(x, y);
        }
    }

    /** Size of the square board. */
    private int size;

    /** The board itself, stored row‑by‑row. */
    private String[] board;

    /** All positions that contain an 'o'. */
    private final Set<Point> os = new HashSet<>();

    /** All positions that contain an 'x'. */
    private final Set<Point> xs = new HashSet<>();

    /** All shifts (dx, dy) that keep every 'o' onto another occupied cell or an 'x'. */
    private final Set<Point> allowedShifts = new HashSet<>();

    /** --------------------------------------------------------------
     *  Public entry point.
     * -------------------------------------------------------------- */
    void solve(InputReader reader, PrintWriter out) {
        size = reader.nextInt();
        board = reader.nextLines(size);

        parseBoard();

        computeAllowedShifts();

        if (!allXsAreExplained()) {
            out.println("NO");
            return;
        }

        out.println("YES");
        printShiftBoard(out);
    }

    /** --------------------------------------------------------------
     *  Parsing helpers.
     * -------------------------------------------------------------- */
    private void parseBoard() {
        for (int i = 0; i < size; i++) {
            for (int j = 0; j < size; j++) {
                char c = board[i].charAt(j);
                if (c == 'o') {
                    os.add(new Point(i, j));
                } else if (c == 'x') {
                    xs.add(new Point(i, j));
                }
            }
        }
    }

    /** --------------------------------------------------------------
     *  Compute the set of allowed translation vectors (dx, dy).
     * -------------------------------------------------------------- */
    private void computeAllowedShifts() {
        allowedShifts.clear();

        for (int dx = -(size - 1); dx < size; dx++) {
            for (int dy = -(size - 1); dy < size; dy++) {
                if (isShiftAllowed(dx, dy)) {
                    allowedShifts.add(new Point(dx, dy));
                }
            }
        }
    }

    /** Checks whether a particular shift keeps every 'o' on a valid target. */
    private boolean isShiftAllowed(int dx, int dy) {
        for (Point p : os) {
            Point shifted = new Point(p.x + dx, p.y + dy);
            if (outside(shifted.x, shifted.y)) {
                continue; // outside board – automatically considered covered
            }
            if (!os.contains(shifted) && !hasX(shifted.x, shifted.y)) {
                return false;
            }
        }
        return true;
    }

    /** Returns true if the given coordinate lies inside the board. */
    private boolean outside(int x, int y) {
        return x < 0 || x >= size || y < 0 || y >= size;
    }

    /** Convenience – does the board have an 'x' at (x, y)? */
    private boolean hasX(int x, int y) {
        return board[x].charAt(y) == 'x';
    }

    /** --------------------------------------------------------------
     *  Validation – each 'x' must be reachable by at least one allowed shift.
     * -------------------------------------------------------------- */
    private boolean allXsAreExplained() {
        for (Point x : xs) {
            long explained = 0;
            for (Point o : os) {
                int dx = x.x - o.x;
                int dy = x.y - o.y;
                if (allowedShifts.contains(new Point(dx, dy))) {
                    explained++;
                }
            }
            if (explained == 0) {
                return false;
            }
        }
        return true;
    }

    /** --------------------------------------------------------------
     *  Output generation.
     * -------------------------------------------------------------- */
    private void printShiftBoard(PrintWriter out) {
        int boardLines = 2 * size - 1;
        char[][] grid = new char[boardLines][boardLines];
        for (char[] row : grid) {
            Arrays.fill(row, '.');
        }

        // mark each allowed shift with 'x'
        for (Point shift : allowedShifts) {
            int i = shift.x + size - 1;
            int j = shift.y + size - 1;
            if (inside(i, j)) {
                grid[i][j] = 'x';
            }
        }

        // central cell must contain the original 'o' marker
        grid[size - 1][size - 1] = 'o';

        // print result
        for (char[] row : grid) {
            out.println(new String(row));
        }
    }

    private boolean inside(int i, int j) {
        return i >= 0 && i < 2 * size - 1 && j >= 0 && j < 2 * size - 1;
    }
}

