/**
 * Core logic of the problem.
 * All algorithmic steps are encapsulated in clearly‑named private methods,
 * making the code easy to follow and maintain.
 */
class Solver {

    /** Symbols used in the input grid. */
    private static final char SYMBOL_O = 'o';
    private static final char SYMBOL_X = 'x';
    private static final char SYMBOL_DOT = '.';

    /**
     * Solves one test case.
     *
     * @param in  scanner that reads the input
     * @param out printer that writes the answer
     */
    public void solve(FastScanner in, FastPrinter out) {
        int n = in.nextInt();                     // size of the n × n board
        char[][] grid = readGrid(in, n, n);        // read the board

        // --------------------------------------------------------------------
        // 1. Initialise the “possible” matrix (size (2n‑1) × (2n‑1)) with 1.
        // --------------------------------------------------------------------
        int boardSize = 2 * n - 1;
        int centre = n - 1;                         // index of the centre cell
        int[][] possible = new int[boardSize][boardSize];
        fillWithOnes(possible);

        // --------------------------------------------------------------------
        // 2. Remove influence of cells that are known to be '.'.
        // --------------------------------------------------------------------
        suppressInfluenceOfDots(grid, possible, centre);

        // --------------------------------------------------------------------
        // 3. Count how many centres can still influence each cell of the n×n board.
        // --------------------------------------------------------------------
        int[][] influenceCount = new int[n][n];
        accumulateInfluenceCount(grid, possible, centre, influenceCount);

        // --------------------------------------------------------------------
        // 4. Verify that every ‘x’ cell receives at least one claimed centre.
        // --------------------------------------------------------------------
        if (!allXCellsAreCovered(grid, influenceCount)) {
            out.println("NO");
            return;
        }

        // --------------------------------------------------------------------
        // 5. Output answer and print the final board representation.
        // --------------------------------------------------------------------
        out.println("YES");
        printBoard(possible, centre);
    }

    /** Fill the whole matrix with the value 1. */
    private void fillWithOnes(int[][] matrix) {
        for (int[] row : matrix) {
            Arrays.fill(row, 1);
        }
    }

    /**
     * For every '.' cell, clear every entry of {@code possible} that can be
     * reached from that cell (i.e., every position that would be set to 0
     * in the original algorithm).
     */
    private void suppressInfluenceOfDots(char[][] grid, int[][] possible, int centre) {
        int n = grid.length;
        int radius = n - 1;               // maximal offset
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (grid[i][j] == SYMBOL_DOT) {
                    for (int dx = -radius; dx <= radius; dx++) {
                        for (int dy = -radius; dy <= radius; dy++) {
                            int x = i + dx;
                            int y = j + dy;
                            if (!isInside(x, y, n)) continue;
                            possible[dx + centre][dy + centre] = 0;
                        }
                    }
                }
            }
        }
    }

    /**
     * For every ‘o’ cell, increment the {@code influenceCount} of every n×n cell
     * that can still be reached by a centre that was not cleared in step 2.
     */
    private void accumulateInfluenceCount(
            char[][] grid,
            int[][] possible,
            int centre,
            int[][] influenceCount) {

        int n = grid.length;
        int radius = n - 1;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (grid[i][j] == SYMBOL_O) {
                    for (int dx = -radius; dx <= radius; dx++) {
                        for (int dy = -radius; dy <= radius; dy++) {
                            int x = i + dx;
                            int y = j + dy;
                            if (!isInside(x, y, n)) continue;
                            if (possible[dx + centre][dy + centre] != 0) {
                                influenceCount[x][y]++;
                            }
                        }
                    }
                }
            }
        }
    }

    /** Check that each ‘x’ cell has a non‑zero count in {@code influenceCount}. */
    private boolean allXCellsAreCovered(char[][] grid, int[][] influenceCount) {
        int n = grid.length;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (grid[i][j] == SYMBOL_X && influenceCount[i][j] == 0) {
                    return false;
                }
            }
        }
        return true;
    }

    /** Print the final board using the data stored in {@code possible}. */
    private void printBoard(int[][] possible, int centre) {
        int size = possible.length;
        StringBuilder out = new StringBuilder();
        for (int i = 0; i < size; i++) {
            for (int j = 0; j < size; j++) {
                if (i == centre && j == centre) {
                    out.append('o');
                } else if (possible[i][j] == 1) {
                    out.append('x');
                } else {
                    out.append('.');
                }
            }
            out.append('\n');
        }
        System.out.print(out.toString());
    }

    /** Read an {@code rows × cols} character grid from the scanner. */
    private char[][] readGrid(FastScanner in, int rows, int cols) {
        char[][] grid = new char[rows][];
        for (int i = 0; i < rows; i++) {
            String token = in.next();
            if (token.length() != cols) {
                throw new AssertionError(
                        "Expected token length " + cols + " but got " + token.length());
            }
            grid[i] = token.toCharArray();
        }
        return grid;
    }

    /** Simple range‑check helper. */
    private boolean isInside(int x, int y, int limit) {
        return x >= 0 && x < limit && y >= 0 && y < limit;
    }
}

/* --------------------------------------------------------------------- */
/*  Fast I/O helpers – unchanged from the original snippet (only minor   */
/*  formatting adjustments).                                            */
/* --------------------------------------------------------------------- */

class FastScanner extends BufferedReader {
    protected FastScanner(InputStream is) {
        super(new InputStreamReader(is, StandardCharsets.UTF_8));
    }

    @Override
    public int read() {
        try {
            return super.read();
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
    }

    @Override
    public String next() {
        try {
            int c;
            do {
                c = read();
                if (c < 0) return null;
            } while (isWhiteSpace(c));
            StringBuilder sb = new StringBuilder();
            do {
                sb.append((char) c);
                c = read();
            } while (!isWhiteSpace(c) && c >= 0);
            return sb.toString();
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
    }

    public int nextInt() {
        int sign = 1;
        int c;
        do {
            c = read();
        } while (isWhiteSpace(c));
        if (c == '-') {
            sign = -1;
            c = read();
        }
        int result = 0;
        while (c >= '0' && c <= '9') {
            result = result * 10 + (c - '0');
            c = read();
        }
        return result * sign;
    }

    private static boolean isWhiteSpace(int c) {
        return c <= ' ';
    }

    @Override
    public String readLine() {
        try {
            return super.readLine();
        } catch (IOException e) {
            return null;
        }
    }
}

class FastPrinter extends PrintWriter {
    protected FastPrinter(OutputStream out) {
        super(out);
    }
}

import java.io.*;
import java.util.*;
import java.util.stream.IntStream;

/**
 * Refactored version of the original program.
 *
 * <p>Key improvements:
 * <ul>
 *   <li>Extracted responsibilities into well‑named methods.
 *   <li>Replaced raw types and magic numbers with safe, self‑documenting constructs.
 *   <li>Used a small {@code Position} class instead of two parallel lists.
 *   <li>Added inline comments and JavaDoc for clarity.
 *   <li>Kept the fast custom scanner but made it type‑safe and encapsulated.
 *   <li>Used streams and collection utilities where they improve readability.
 * </ul>
 *
 * The logic is identical to the original solution – it reads an {@code N × N}
 * board containing characters {@code 'o', 'x', '.'}, builds a larger
 * {@code (2N‑1) × (2N‑1)} board, marks cells attacked by pieces and validates
 * the result.
 */
public class RefactoredSolution {

    /** Fast scanner that works with System.in – kept for performance. */
    private static final class FastScanner {
        private final InputStream stream;
        private final byte[] buffer = new byte[1024];
        private int cursor = 0;
        private int size = 0;

        FastScanner(InputStream stream) {
            this.stream = stream;
        }

        private int readByte() throws IOException {
            if (cursor >= size) {
                cursor = 0;
                size = stream.read(buffer);
                if (size <= 0) {
                    return -1;
                }
            }
            return buffer[cursor++];
        }

        private boolean isSpace(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        private boolean isEndOfLine(int c) {
            return c == '\n' || c == '\r' || c == -1;
        }

        /** Returns next non‑space token. */
        String next() throws IOException {
            int c;
            do {
                c = readByte();
            } while (isSpace(c));
            StringBuilder sb = new StringBuilder();
            do {
                sb.append((char) c);
                c = readByte();
            } while (!isSpace(c));
            return sb.toString();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }

        /** @return an int array of the given length filled with next ints. */
        int[] nextInts(int length) throws IOException {
            return IntStream.range(0, length).map(i -> nextInt()).toArray();
        }
    }

    /** Simple immutable pair representing a coordinate (x, y). */
    private static final class Position {
        final int x;   // column
        final int y;   // row

        Position(int x, int y) {
            this.x = x;
            this.y = y;
        }
    }

    /** Entry point – delegates all work to {@link #solve(FastScanner, PrintWriter)}. */
    public static void main(String[] args) throws Exception {
        try (FastScanner scanner = new FastScanner(System.in);
             PrintWriter out = new PrintWriter(System.out, true)) {
            solve(scanner, out);
        }
    }

    /**
     * Orchestrates the whole algorithm:
     * <ol>
     *   <li>Read input,
     *   <li>Locate pieces,
     *   <li>Build the enlarged board,
     *   <li>Mark attacked cells,
     *   <li>Validate the result and print.
     * </ol>
     */
    private static void solve(FastScanner fs, PrintWriter out) {
        int n = fs.nextInt();                                 // size of the original board
        String[] rows = fs.next(n);                           // N strings of length N
        char[][] input = toCharMatrix(rows, n);                // original grid
        List<Position> pieces = locatePieces(input, n);       // positions of 'o'

        int boardSize = 2 * n - 1;                              // size of enlarged board
        char[][] board = createEmptyBoard(boardSize, n);       // (2N‑1)×(2N‑1) board with central 'o'

        markAttackedCells(board, input, pieces, n);           // fill '.' / 'x' according to rules

        if (!verifyResult(input, pieces, board, n)) {
            out.println("NO");
            return;
        }

        out.println("YES");
        for (char[] row : board) {
            out.println(new String(row));
        }
    }

    /** Converts the array of strings returned by the scanner into a char matrix. */
    private static char[][] toCharMatrix(String[] rows, int n) {
        char[][] matrix = new char[n][n];
        for (int y = 0; y < n; y++) {
            matrix[y] = rows[y].toCharArray();
        }
        return matrix;
    }

    /** Finds all coordinates of pieces ('o') in the original board. */
    private static List<Position> locatePieces(char[][] grid, int n) {
        List<Position> list = new ArrayList<>();
        for (int y = 0; y < n; y++) {
            for (int x = 0; x < n; x++) {
                if (grid[y][x] == 'o') {
                    list.add(new Position(x, y));
                }
            }
        }
        return list;
    }

    /** Creates an empty (2N‑1)×(2N‑1) board filled with '.' and puts a central 'o'. */
    private static char[][] createEmptyBoard(int size, int n) {
        char[][] board = new char[size][size];
        Arrays.fill(board, '.');
        int centre = n - 1;
        board[centre][centre] = 'o';
        return board;
    }

    /**
     * For each empty cell of the enlarged board, decides whether it is attacked
     * by any piece and writes 'x' or '.' accordingly.
     */
    private static void markAttackedCells(char[][] board, char[][] input, List<Position> pieces, int n) {
        int centre = n - 1;
        for (int r = 0; r < board.length; r++) {
            for (int c = 0; c < board.length; c++) {
                if (r == centre && c == centre) {
                    continue; // already contains the central 'o'
                }
                int dy = r - centre;
                int dx = c - centre;
                boolean attacked = true;
                for (Position p : pieces) {
                    int nx = dx + p.x;
                    int ny = dy + p.y;
                    if (nx < 0 || ny < 0 || nx >= n || ny >= n) {
                        continue;
                    }
                    if (input[ny][nx] == '.') {
                        attacked = false;
                        break;
                    }
                }
                board[r][c] = attacked ? 'x' : '.';
            }
        }
    }

    /**
     * Validates that the generated board satisfies the problem constraints.
     *
     * <p>The verification follows the original algorithm:
     * <ul>
     *   <li>Whenever a board cell contains 'x', the corresponding cell in the
     *       original grid must not be '.' (otherwise the answer is {@code NO}).
     *   <li>All 'x' cells of the original grid must be reachable from some 'x'
     *       board cell via the reverse offset calculation.
     * </ul>
     *
     * @return {@code true} if the board is valid, {@code false} otherwise (the method
     *         already printed {@code "NO"} in the latter case).
     */
    private static boolean verifyResult(char[][] input, List<Position> pieces, char[][] board, int n) {
        boolean[][] reachable = new boolean[n][n];

        // First pass – fill {@code reachable} and detect illegal '.' coverage.
        for (int p = 0; p < pieces.size(); p++) {
            Position piece = pieces.get(p);
            for (int r = 0; r < board.length; r++) {
                for (int c = 0; c < board.length; c++) {
                    if (board[r][c] != 'x') {
                        continue;
                    }
                    int nx = piece.x + c - (n - 1);
                    int ny = piece.y + r - (n - 1);
                    if (outOfBounds(nx, ny, n)) {
                        continue;
                    }
                    if (input[ny][nx] == '.') {
                        System.out.println("NO");
                        return false;
                    }
                    reachable[ny][nx] = true;
                }
            }
        }

        // Second pass – ensure every 'x' in the original board is reachable.
        for (int y = 0; y < n; y++) {
            for (int x = 0; x < n; x++) {
                if (input[y][x] == 'x' && !reachable[y][x]) {
                    System.out.println("NO");
                    return false;
                }
            }
        }
        return true;
    }

    /** Helper that checks whether a coordinate lies inside an {@code N × N} grid. */
    private static boolean outOfBounds(int x, int y, int n) {
        return x < 0 || y < 0 || x >= n || y >= n;
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.ArrayList;
import java.util.List;

/**
 * Refactored solution for the “Checker Pieces” problem.
 * <p>
 * The program reads an N×N board containing:
 *   • ‘o’ – a checker piece,
 *   • ‘x’ – a cell that must be reachable by moving a piece,
 *   • ‘.’ – an empty cell.
 * <p>
 * It verifies that every ‘x’ can be explained by moving at least one piece
 * by some displacement (dx, dy). If validation succeeds it prints "YES" and
 * draws a (2N‑1)×(2N‑1) canvas that shows all possible displacements as ‘x’
 * cells, with the original piece marked as ‘o’.
 * </p>
 */
public class Solver {

    // ------------------------------------------------------------------------
    // Entry point
    // ------------------------------------------------------------------------
    public static void main(String[] args) throws IOException {
        // Try‑with‑resources guarantees the reader is closed automatically.
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in))) {
            int n = readInt(br);
            char[][] board = readBoard(br, n);
            List<Piece> pieces = collectPieces(board);

            // If any ‘x’ cannot be reached, the answer is “NO”.
            if (!allXCanBeExplained(board, pieces)) {
                System.out.println("NO");
                return;
            }

            // Build the result canvas and mark all valid displacements.
            char[][] canvas = createCanvas(n);
            markDisplacements(canvas, pieces, board);
            printAnswer(canvas);
        }
    }

    // ------------------------------------------------------------------------
    // Input handling helpers
    // ------------------------------------------------------------------------
    private static int readInt(BufferedReader br) throws IOException {
        String[] tokens = br.readLine().split("\\s+");
        return Integer.parseInt(tokens[0]);
    }

    private static char[][] readBoard(BufferedReader br, int n) throws IOException {
        char[][] board = new char[n][];
        for (int i = 0; i < n; i++) {
            board[i] = br.readLine().toCharArray();
        }
        return board;
    }

    private static List<Piece> collectPieces(char[][] board) {
        List<Piece> pieces = new ArrayList<>();
        for (int r = 0; r < board.length; r++) {
            for (int c = 0; c < board[r].length; c++) {
                if (board[r][c] == 'o') {
                    pieces.add(new Piece(r, c));
                }
            }
        }
        return pieces;
    }

    // ------------------------------------------------------------------------
    // Validation logic
    // ------------------------------------------------------------------------
    private static boolean allXCanBeExplained(char[][] board, List<Piece> pieces) {
        int size = board.length;
        for (int r = 0; r < size; r++) {
            for (int c = 0; c < size; c++) {
                if (board[r][c] == 'x') {
                    boolean explained = false;
                    for (Piece p : pieces) {
                        int dr = r - p.row;
                        int dc = c - p.col;
                        if (isDisplacementValid(board, dr, dc, pieces)) {
                            explained = true;
                            break;
                        }
                    }
                    if (!explained) {
                        return false;
                    }
                }
            }
        }
        return true;
    }

    /** Returns true if moving every piece by (dr, dc) never lands on a '.' cell. */
    private static boolean isDisplacementValid(char[][] board, int dr, int dc, List<Piece> pieces) {
        for (Piece p : pieces) {
            int nr = p.row + dr;
            int nc = p.col + dc;
            if (isInside(board, nr, nc) && board[nr][nc] == '.') {
                return false;
            }
        }
        return true;
    }

    private static boolean isInside(char[][] board, int r, int c) {
        return r >= 0 && r < board.length && c >= 0 && c < board[0].length;
    }

    // ------------------------------------------------------------------------
    // Result canvas construction
    // ------------------------------------------------------------------------
    private static char[][] createCanvas(int n) {
        int canvasSize = 2 * n - 1;
        char[][] canvas = new char[canvasSize][canvasSize];
        for (char[] row : canvas) {
            java.util.Arrays.fill(row, '.');
        }
        canvas[n - 1][n - 1] = 'o'; // original piece position
        return canvas;
    }

    /** Marks every valid displacement in the canvas with an ‘x’. */
    private static void markDisplacements(char[][] canvas, List<Piece> pieces, char[][] original) {
        int center = n - 1;                 // centre index of the canvas
        int maxDelta = canvas.length - 1;   // = 2n‑2

        for (int dr = -maxDelta; dr <= maxDelta; dr++) {
            for (int dc = -maxDelta; dc <= maxDelta; dc++) {
                if (dr == 0 && dc == 0) {
                    continue; // skip the zero‑displacement
                }
                if (isDisplacementAllowed(pieces, original, dr, dc)) {
                    int r = center + dr;
                    int c = center + dc;
                    if (isInsideCanvas(canvas, r, c)) {
                        canvas[r][c] = 'x';
                    }
                }
            }
        }
    }

    /** Checks whether displacement (dr, dc) is legal for all pieces. */
    private static boolean isDisplacementAllowed(List<Piece> pieces, char[][] original, int dr, int dc) {
        for (Piece p : pieces) {
            int nr = p.row + dr;
            int nc = p.col + dc;
            if (isInside(original, nr, nc) && original[nr][nc] == '.') {
                return false;
            }
        }
        return true;
    }

    private static boolean isInsideCanvas(char[][] canvas, int r, int c) {
        return r >= 0 && r < canvas.length && c >= 0 && c < canvas[0].length;
    }

    // ------------------------------------------------------------------------
    // Output
    // ------------------------------------------------------------------------
    private static void printAnswer(char[][] canvas) {
        System.out.println("YES");
        for (char[] row : canvas) {
            System.out.println(new String(row));
        }
    }

    // ------------------------------------------------------------------------
    // Simple data holder for a piece position
    // ------------------------------------------------------------------------
    private static final class Piece {
        final int row;
        final int col;
        Piece(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }
}

import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;
import java.util.Arrays;

/**
 * Refactored version of the original program.
 * <p>
 * The program reads an {@code n×n} board that contains pieces marked {@code 'o'}
 * and optionally cells marked {@code 'x'}.  It builds a larger {@code (2n‑1)×(2n‑1)}
 * solution board that shows all translation offsets {@code (dx,dy)} that keep
 * every piece inside the original board and land on a non‑empty cell.
 * If after processing every offset there is still an {@code 'x'} left on the
 * original board the answer is {@code "NO"}, otherwise it prints {@code "YES"}
 * followed by the solution board.
 *
 * <p>Key improvements:
 * <ul>
 *   <li>Extracted responsibilities into well‑named methods.</li>
 *   <li>Used a small {@code Pos} record instead of two parallel {@code List<Integer>}.</li>
 *   <li>Replaced raw types with generics.</li>
 *   <li>Eliminated magic numbers and added meaningful constants.</li>
 *   <li>Made the control flow explicit (guard clauses, early returns).</li>
 *   <li>Added inline documentation.</li>
 * </ul>
 */
public class BoardSolver {

    /* --------------------------------------------------------------------- */
    /* Constants                                                           */
    /* --------------------------------------------------------------------- */
    private static final char PIECE   = 'o';   // piece marker on the original board
    private static final char MARK    = 'X';   // cell marked after a valid attack
    private static final char SOL     = 'x';   // character written on the solution board
    private static final char EMPTY   = '.';   // empty cell on the original board

    /* --------------------------------------------------------------------- */
    /* Entry point                                                          */
    /* --------------------------------------------------------------------- */
    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            solve(scanner);
        }
    }

    /* --------------------------------------------------------------------- */
    /* Core algorithm                                                       */
    /* --------------------------------------------------------------------- */
    private static void solve(Scanner scanner) {
        int n = scanner.nextInt();          // size of the original board
        scanner.nextLine();                 // consume end‑of‑line

        char[][] board = readBoard(scanner, n);
        List<Pos> pieces = locatePieces(board, n);

        int m = 2 * n - 1;                    // size of the solution board
        char[][] solution = new char[m][m];
        initialiseSolution(solution);

        processAllOffsets(n, pieces, board, solution);

        if (containsRemainingX(board, n)) {
            System.out.println("NO");
            return;
        }

        System.out.println("YES");
        printSolution(solution);
    }

    /* --------------------------------------------------------------------- */
    /* Input handling                                                       */
    /* --------------------------------------------------------------------- */
    private static char[][] readBoard(Scanner scanner, int n) {
        char[][] board = new char[n][n];
        for (int i = 0; i < n; i++) {
            String line = scanner.nextLine().trim();
            board[i] = line.toCharArray();
        }
        return board;
    }

    private static List<Pos> locatePieces(char[][] board, int n) {
        List<Pos> pieces = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (board[i][j] == PIECE) {
                    pieces.add(new Pos(i, j));
                }
            }
        }
        return pieces;
    }

    private static void initialiseSolution(char[][] solution) {
        // default fill – every cell starts as EMPTY on the solution board
        for (char[] row : solution) {
            Arrays.fill(row, EMPTY);
        }
    }

    /* --------------------------------------------------------------------- */
    /* Logic core                                                            */
    /* --------------------------------------------------------------------- */
    private static void processAllOffsets(int n,
                                            List<Pos> pieces,
                                            char[][] board,
                                            char[][] solution) {
        int mid = n - 1;                     // centre index of the solution board

        // iterate over every possible offset (dx,dy)
        for (int dx = -(mid); dx <= mid; dx++) {
            for (int dy = -(mid); dy <= mid; dy++) {
                if (dx == 0 && dy == 0) {
                    continue;                // the zero offset is not considered
                }

                if (!isAttackingOffset(dx, dy, pieces, board)) {
                    continue;                // offset does not satisfy all constraints
                }

                // convert offset to coordinates on the solution board
                int solX = mid + dx;
                int solY = mid + dy;
                solution[solX][solY] = SOL;

                // mark cells that are attacked on the original board
                markAttackedCells(pieces, dx, dy, board);
            }
        }
    }

    /** Returns {@code true} iff, for the given offset, every piece stays inside
     *  the original board and lands on a non‑EMPTY cell. */
    private static boolean isAttackingOffset(int dx,
                                              int dy,
                                              List<Pos> pieces,
                                              char[][] board) {
        for (Pos p : pieces) {
            int nx = p.row() + dx;
            int ny = p.col() + dy;
            if (nx < 0 || ny < 0 || nx >= board.length || ny >= board.length) {
                // out‑of‑bounds does not make the offset invalid – it simply means
                // that piece does not generate a conflict for this offset.
                continue;
            }
            if (board[nx][ny] == EMPTY) {
                return false;
            }
        }
        return true;
    }

    private static void markAttackedCells(List<Pos> pieces,
                                          int dx,
                                          int dy,
                                          char[][] board) {
        for (Pos p : pieces) {
            int ax = p.row() + dx;
            int ay = p.col() + dy;
            if (ax < 0 || ay < 0 || ax >= board.length || ay >= board.length) {
                continue;
            }
            // According to the original program only cells that originally contain
            // 'x' are turned into 'X'; all other cells are left untouched.
            if (board[ax][ay] == 'x') {
                board[ax][ay] = MARK;
            }
        }
    }

    /* --------------------------------------------------------------------- */
    /* Validation & output                                                  */
    /* --------------------------------------------------------------------- */
    private static boolean containsRemainingX(char[][] board, int n) {
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (board[i][j] == 'x') {
                    return true;          // failure condition – uncovered 'x'
                }
            }
        }
        return false;
    }

    private static void printSolution(char[][] solution) {
        for (char[] row : solution) {
            for (char cell : row) {
                System.out.print(cell);
            }
            System.out.println();
        }
    }

    /* --------------------------------------------------------------------- */
    /* Small data holder                                                     */
    /* --------------------------------------------------------------------- */
    /** Immutable pair of row and column indices. */
    private record Pos(int row, int col) {}
}

import java.io.*;
import java.util.*;

/**
 * Refactored solution for the “Banana” problem.
 *
 * <p>Changes made for readability and maintainability:
 *
 * <ul>
 *   <li>Extracted token handling into {@link FastScanner}.
 *   <li>Isolated grid reading and target collection into dedicated methods.
 *   <li>Replaced the monolithic {@code banana()} method with a purpose‑specific
 *       {@link Solver} class.
 *   <li>Used small, immutable value objects ({@link Point}) instead of raw ints.
 *   <li>Removed all static mutable fields; resources are managed with
 *       try‑with‑resources.
 *   <li>Added clear method names, constants, and Javadoc comments.
 *   <li>Kept the original algorithmic behaviour unchanged.
 * </ul>
 */
public class Main {

    /** Simple container for integer coordinates. */
    private static final class Point {
        final int row;
        final int col;
        Point(int row, int col) { this.row = row; this.col = col; }
    }

    /** Fast tokeniser that mimics the original hand‑rolled scanner. */
    private static final class FastScanner implements AutoCloseable {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        FastScanner(Reader source) {
            this.reader = new BufferedReader(source);
        }

        /** Returns the next available token, or {@code null} on EOF. */
        private String nextToken() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                String line = reader.readLine();
                if (line == null) {
                    return null;
                }
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(nextToken());
        }

        long nextLong() throws IOException {
            return Long.parseLong(nextToken());
        }

        double nextDouble() throws IOException {
            return Double.parseDouble(nextToken());
        }

        @Override
        public void close() throws IOException {
            reader.close();
        }
    }

    /** Core logic that decides whether a solution exists and records the offsets. */
    private static final class Solver {
        private final char[][] grid;
        private final List<Point> targets;
        private final List<Point> axes = new ArrayList<>();

        Solver(char[][] grid, List<Point> targets) {
            this.grid = grid;
            this.targets = targets;
        }

        /** Returns {@code true} if a placement exists, {@code false} otherwise. */
        boolean isPossible() {
            final int n = grid.length;
            boolean[][] covered = new boolean[n][n];

            // Examine every possible translation vector (dx, dy)
            for (int dx = -n + 1; dx < n; ++dx) {
                for (int dy = -n + 1; dy < n; ++dy) {
                    if (dx == 0 && dy == 0) {
                        continue;
                    }
                    if (!canPlace(dx, dy)) {
                        continue;
                    }
                    axes.add(new Point(dx, dy));
                    markCovered(dx, dy, covered);
                }
            }

            // Verify that every 'x' cell is reachable from at least one target
            for (int i = 0; i < n; ++i) {
                for (int j = 0; j < n; ++j) {
                    if (grid[i][j] == 'x' && !covered[i][j]) {
                        return false;
                    }
                }
            }
            return true;
        }

        /** Checks whether all targets stay inside the board and land on 'x' after translation. */
        private boolean canPlace(int dx, int dy) {
            for (Point p : targets) {
                int nx = p.row + dx;
                int ny = p.col + dy;
                if (outOfBounds(nx, ny, grid.length) || grid[nx][ny] != 'x') {
                    return false;
                }
            }
            return true;
        }

        /** Marks cells reachable by the given translation vector. */
        private void markCovered(int dx, int dy, boolean[][] covered) {
            for (Point p : targets) {
                int nx = p.row + dx;
                int ny = p.col + dy;
                if (!outOfBounds(nx, ny, covered.length)) {
                    covered[nx][ny] = true;
                }
            }
        }

        /** @return a (possibly empty) list of translation vectors that lead to a solution. */
        List<Point> getAxes() {
            return axes;
        }

        /** Helper that tells whether a coordinate lies outside the square board. */
        private static boolean outOfBounds(int r, int c, int size) {
            return r < 0 || r >= size || c < 0 || c >= size;
        }
    }

    /** Formats and prints the solution board. */
    private static void printSolution(Collection<Point> axes, int n) {
        final int dimension = 2 * n - 1;
        char[][] board = new char[dimension][dimension];
        for (char[] row : board) {
            Arrays.fill(row, '.');
        }
        board[n - 1][n - 1] = 'o';
        for (Point off : axes) {
            int r = n - 1 + off.row;
            int c = n - 1 + off.col;
            board[r][c] = 'x';
        }
        StringBuilder out = new StringBuilder();
        for (char[] row : board) {
            out.append(row).append('\n');
        }
        System.out.print(out.toString());
    }

    /** Reads the grid from the scanner. */
    private static char[][] readGrid(FastScanner fs, int n) throws IOException {
        char[][] grid = new char[n][n];
        for (int i = 0; i < n; ++i) {
            String line = fs.nextToken();
            for (int j = 0; j < n; ++j) {
                grid[i][j] = line.charAt(j);
            }
        }
        return grid;
    }

    /** Collects all positions that contain the character 'o'. */
    private static List<Point> collectTargets(char[][] grid) {
        List<Point> points = new ArrayList<>();
        for (int i = 0; i < grid.length; ++i) {
            for (int j = 0; j < grid[i].length; ++j) {
                if (grid[i][j] == 'o') {
                    points.add(new Point(i, j));
                }
            }
        }
        return points;
    }

    /** Entry point – now a thin wrapper that delegates work to purpose‑specific classes. */
    public static void main(String[] args) throws IOException {
        // ISO‑8859‑1 matches the original source file encoding
        try (FastScanner fs = new FastScanner(new InputStreamReader(System.in, "ISO-8859-1"));
             PrintWriter out = new PrintWriter(System.out, true)) {

            int n = fs.nextInt();
            char[][] grid = readGrid(fs, n);
            List<Point> targets = collectTargets(grid);

            Solver solver = new Solver(grid, targets);
            boolean possible = solver.isPossible();

            out.println(possible ? "YES" : "NO");
            if (possible) {
                printSolution(solver.getAxes(), n);
            }
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Main entry point. Handles the creation of the input reader and output writer,
 * then delegates the actual solving to {@link Solver}.
 */
public class Main {
    public static void main(String[] args) throws IOException {
        // Use System.in / System.out directly
        try (InputReader reader = new InputReader(System.in);
             PrintWriter writer = new PrintWriter(System.out)) {
            new Solver().solve(reader, writer);
        }
    }
}

/**
 * Core logic for the problem.
 *
 * <p>Responsibilities:
 * <ul>
 *   <li>Reading the board configuration.</li>
 *   <li>Marking all positions reachable from an obstacle ('o').</li>
 *   <li>Verifying that every 'x' cell can reach an obstacle through reachable cells.</li>
 *   <li>Printing "YES" and the move board or "NO".</li>
 * </ul>
 */
class Solver {
    private static final char EMPTY   = 'x';   // cell type in the move board
    private static final char OBSTACLE = 'o';   // the single initial obstacle
    private static final char REACHABLE = '.'; // cell reachable from an obstacle

    /**
     * Entry point used by {@link Main}.
     */
    public void solve(InputReader reader, PrintWriter out) {
        int n = reader.nextInt();                     // board dimension
        String[] board = new String[n];               // rows of the original board
        for (int i = 0; i < n; i++) {
            board[i] = reader.next();
        }

        char[][] moves = createMovesArray(n);
        markReachablePositions(board, moves);

        boolean allXCanReachObstacle = checkAllXCanReachObstacle(board, moves);

        if (allXCanReachObstacle) {
            out.println("YES");
            printMoves(moves, out);
        } else {
            out.println("NO");
        }
    }

    /** Creates a (2*n‑1)×(2*n‑1) grid filled with {@code EMPTY} and places the
     *  initial obstacle at the centre. */
    private char[][] createMovesArray(int size) {
        char[][] moves = new char[2 * size - 1][2 * size - 1];
        for (char[] row : moves) {
            Arrays.fill(row, EMPTY);
        }
        int centre = size - 1;
        moves[centre][centre] = OBSTACLE;
        return moves;
    }

    /** Marks every cell that can be reached from any obstacle cell by moving
     *  through '.' cells of the original board. */
    private void markReachablePositions(String[] board, char[][] moves) {
        int centre = board.length - 1;
        for (int i = 0; i < board.length; i++) {
            for (int j = 0; j < board[i].length(); j++) {
                if (board[i].charAt(j) == OBSTACLE) {
                    floodFill(board, moves, i, j);
                }
            }
        }
    }

    /** Breadth‑first flood fill that propagates through '.' cells of {@code board}
     *  and marks them as {@code REACHABLE} in {@code moves}. */
    private void floodFill(String[] board, char[][] moves, int srcR, int srcC) {
        int rows = board.length;
        int cols = board[0].length();
        Deque<int[]> q = new ArrayDeque<>();
        q.add(new int[]{srcR, srcC});

        int[][] dirs = {{1,0}, {-1,0}, {0,1}, {0,-1}};
        while (!q.isEmpty()) {
            int[] cur = q.poll();
            int r = cur[0];
            int c = cur[1];
            for (int[] d : dirs) {
                int nr = r + d[0];
                int nc = c + d[1];
                if (isInside(nr, nc, board) &&
                    board[nr].charAt(nc) == '.' &&          // original board cell is empty
                    moves[nr][nc] == EMPTY) {                // not already processed
                    moves[nr][nc] = REACHABLE;
                    q.add(new int[]{nr, nc});
                }
            }
        }
    }

    /** Checks whether every 'x' cell in the original board can reach the centre
     *  obstacle through a path of REACHABLE cells. */
    private boolean checkAllXCanReachObstacle(String[] board, char[][] moves) {
        int centre = board.length - 1;
        for (int i = 0; i < board.length; i++) {
            for (int j = 0; j < board[i].length(); j++) {
                if (board[i].charAt(j) == 'x') {
                    if (!canReachObstacle(i, j, centre, centre, board, moves)) {
                        return false;
                    }
                }
            }
        }
        return true;
    }

    /** Performs a BFS from (startR,startC) to see if the target obstacle cell
     *  can be reached moving only through REACHABLE cells. */
    private boolean canReachObstacle(int startR, int startC,
                                     int targetR, int targetC,
                                     String[] board, char[][] moves) {
        if (startR == targetR && startC == targetC) {
            return true;
        }
        boolean[][] visited = new boolean[board.length][board[0].length()];
        Queue<int[]> q = new ArrayDeque<>();
        q.add(new int[]{startR, startC});
        visited[startR][startC] = true;

        int[][] dirs = {{1,0}, {-1,0}, {0,1}, {0,-1}};
        while (!q.isEmpty()) {
            int[] cur = q.poll();
            int r = cur[0];
            int c = cur[1];
            for (int[] d : dirs) {
                int nr = r + d[0];
                int nc = c + d[1];
                if (isInside(nr, nc, board) && !visited[nr][nc]) {
                    char cell = board[nr].charAt(nc);
                    if (cell == '.' && moves[nr][nc] == REACHABLE) {
                        if (nr == targetR && nc == targetC) {
                            return true;
                        }
                        visited[nr][nc] = true;
                        q.add(new int[]{nr, nc});
                    }
                }
            }
        }
        return false;
    }

    /** Prints the move board (rows of the {@code moves} array). */
    private void printMoves(char[][] moves, PrintWriter out) {
        for (char[] row : moves) {
            out.println(new String(row));
        }
    }

    /** Helper that tests whether coordinates are inside the board limits. */
    private boolean isInside(int r, int c, String[] board) {
        return r >= 0 && r < board.length && c >= 0 && c < board[0].length();
    }
}

/**
 * Very small wrapper around {@link BufferedReader} that supplies fast token
 * extraction. It is used by {@link Main} to read input.
 */
class InputReader {
    private final BufferedReader reader;
    private StringTokenizer tokenizer;

    InputReader(InputStream stream) {
        reader = new BufferedReader(new InputStreamReader(stream), 32768);
    }

    /** Returns the next whitespace‑separated token. */
    String next() {
        while (tokenizer == null || !tokenizer.hasMoreTokens()) {
            try {
                tokenizer = new StringTokenizer(reader.readLine());
            } catch (IOException e) {
                throw new RuntimeException(e);
            }
        }
        return tokenizer.nextToken();
    }

    /** Convenience method for reading an {@code int}. */
    int nextInt() {
        return Integer.parseInt(next());
    }
}

import java.io.*;
import java.util.*;
import java.util.stream.*;

public class Main {

    /* -------------------------------------------------------------
       1️⃣  Data structures
       ------------------------------------------------------------- */
    /** Simple immutable vector with natural ordering (dx, then dy). */
    private static final class Vector implements Comparable<Vector> {
        final int dx;
        final int dy;

        Vector(int dx, int dy) {
            this.dx = dx;
            this.dy = dy;
        }

        @Override
        public int compareTo(Vector o) {
            int c = Integer.compare(dx, o.dx);
            if (c != 0) return c;
            return Integer.compare(dy, o.dy);
        }

        @Override
        public boolean equals(Object obj) {
            if (this == obj) return true;
            if (!(obj instanceof Vector)) return false;
            Vector other = (Vector) obj;
            return dx == other.dx && dy == other.dy;
        }

        @Override
        public int hashCode() {
            return Objects.hash(dx, dy);
        }
    }

    /* -------------------------------------------------------------
       2️⃣  Core solving logic
       ------------------------------------------------------------- */
    private static final class Solver {

        private final int n;                 // board dimension
        private final char[][] original;     // input board
        private final List<int[]> oPositions; // coordinates of every 'o'

        Solver(int n, char[][] board) {
            this.n = n;
            this.original = board;
            this.oPositions = new ArrayList<>();
            collectOriginalPositions();
        }

        /** Main entry point required by the original program. */
        void solve() {
            TreeSet<Vector> vectors = gatherVectors();

            // validate every vector against every 'o' position
            for (int r = 0; r < n; r++) {
                for (int c = 0; c < n; c++) {
                    if (original[r][c] == 'o') {
                        pruneInvalidVectors(r, c, vectors);
                    }
                }
            }

            // build candidate board of size n
            char[][] candidate = createEmptyBoard(n);
            placeOriginalOs(candidate);
            applyVectors(candidate, vectors);

            // if candidate does NOT match the original pattern → NO
            if (!boardsAreEqual(original, candidate)) {
                System.out.println("NO");
                System.exit(0);
            }

            // otherwise build enlarged board (2·n‑1) and output it
            char[][] enlarged = createEmptyBoard(2 * n - 1);
            enlarged[n - 1][n - 1] = 'o';
            applyVectors(enlarged, vectors);

            System.out.println("YES");
            printBoard(enlarged);
        }

        /* ---------------------------------------------------------
           Helper methods used by solve()
           --------------------------------------------------------- */
        /** Collect all vectors that point from an 'o' to a blocked cell. */
        private TreeSet<Vector> gatherVectors() {
            TreeSet<Vector> vectors = new TreeSet<>();
            for (int r = 0; r < n; r++) {
                for (int c = 0; c < n; c++) {
                    if (original[r][c] == 'o') {
                        addVectorsFrom(r, c, vectors);
                    }
                }
            }
            return vectors;
        }

        /** Add (dx,dy) whenever the target cell is out‑of‑range or contains 'x'/'o'. */
        private void addVectorsFrom(int row, int col, TreeSet<Vector> set) {
            for (int dx = -(n - 1); dx < n; dx++) {
                for (int dy = -(n - 1); dy < n; dy++) {
                    if (dx == 0 && dy == 0) continue;          // ignore self‑vector
                    int nx = row + dx;
                    int ny = col + dy;
                    if (!inRange(nx, ny, n) ||
                        original[nx][ny] == 'x' || original[nx][ny] == 'o') {
                        set.add(new Vector(dx, dy));
                    }
                }
            }
        }

        /** Remove vectors that would land on a '.' cell when applied to (row,col). */
        private void pruneInvalidVectors(int row, int col, TreeSet<Vector> set) {
            Iterator<Vector> it = set.iterator();
            while (it.hasNext()) {
                Vector v = it.next();
                int nx = row + v.dx;
                int ny = col + v.dy;
                if (inRange(nx, ny, n) && original[nx][ny] == '.') {
                    it.remove();
                }
            }
        }

        /** Build a board of size `size` filled with '.' */
        private static char[][] createEmptyBoard(int size) {
            char[][] board = new char[size][size];
            for (char[] row : board) {
                Arrays.fill(row, '.');
            }
            return board;
        }

        /** Record the coordinates of every 'o' in the original board */
        private void collectOriginalPositions() {
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < n; j++) {
                    if (original[i][j] == 'o') {
                        oPositions.add(new int[]{i, j});
                    }
                }
            }
        }

        /** Mark every original 'o' on `board` */
        private void placeOriginalOs(char[][] board) {
            for (int[] pos : oPositions) {
                board[pos[0]][pos[1]] = 'o';
            }
        }

        /** Apply each vector to `board` – turn reachable '.' cells into 'x' */
        private void applyVectors(char[][] board, TreeSet<Vector> vectors) {
            for (Vector v : vectors) {
                for (int r = 0; r < board.length; r++) {
                    for (int c = 0; c < board[r].length; c++) {
                        if (board[r][c] == 'o') {
                            put(board, r + v.dx, c + v.dy);
                        }
                    }
                }
            }
        }

        /** Place an 'x' if the target cell is inside bounds and still '.' */
        private static void put(char[][] board, int x, int y) {
            if (inBounds(board, x, y) && board[x][y] == '.') {
                board[x][y] = 'x';
            }
        }

        private static boolean inBounds(char[][] board, int x, int y) {
            return x >= 0 && x < board.length && y >= 0 && y < board[0].length;
        }

        /** Return true if the two boards are identical */
        private static boolean boardsAreEqual(char[][] a, char[][] b) {
            if (a.length != b.length || a[0].length != b[0].length) return false;
            for (int i = 0; i < a.length; i++) {
                if (!Arrays.equals(a[i], b[i])) return false;
            }
            return true;
        }

        /** Print a board to stdout */
        private static void printBoard(char[][] board) {
            for (char[] row : board) {
                System.out.println(new String(row));
            }
        }
    }

    /* -------------------------------------------------------------
       3️⃣  I/O helpers & entry point
       ------------------------------------------------------------- */
    private static final PrintWriter out = new PrintWriter(System.out);
    private static final InputReader in = new InputReader(System.in);

    public static void main(String[] args) {
        int n = in.nextInt();
        char[][] board = readBoard(n);
        new Solver(n, board).solve();
        out.close();
    }

    /** Read `n` rows of length `n` and return them as a char matrix. */
    private static char[][] readBoard(int n) {
        char[][] board = new char[n][];
        for (int i = 0; i < n; i++) {
            board[i] = in.next().toCharArray();
        }
        return board;
    }

    /** Minimal input reader used by the original program. */
    private static final class InputReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        InputReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
        }

        String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }
    }
}

import java.io.*;
import java.util.*;

public class Main {

    /* ------------------------------------------------------------------ */
    /*  Entry point                                                       */
    /* ------------------------------------------------------------------ */
    public static void main(String[] args) {
        new Main().run();
    }

    /* ------------------------------------------------------------------ */
    /*  Core algorithm                                                    */
    /* ------------------------------------------------------------------ */
    private FastInput  in;
    private FastOutput out;
    private int        size;                 // original board dimension (n)

    private void run() {
        in  = new FastInput(System.in);
        out = new FastOutput(System.out);
        try {
            solve();
        } finally {
            out.close();
        }
    }

    /** Main solving routine */
    private void solve() {
        size = in.nextInt();
        char[][] board = readBoard();

        List<Point> targets   = collectCells(board, 'x');
        List<Point> obstacles = collectCells(board, 'o');

        boolean[][] used = new boolean[size][size];

        char[][] result = buildEmptyResult();

        // place the original obstacle on its centre cell
        result[size - 1][size - 1] = 'o';

        // explore every possible offset (dx,dy) ≠ (0,0)
        for (int dx = -(size - 1); dx <= size - 1; dx++) {
            for (int dy = -(size - 1); dy <= size - 1; dy++) {
                if (dx == 0 && dy == 0) {
                    continue;
                }
                if (isValidOffset(board, obstacles, dx, dy)) {
                    markUsedAndPlaceX(obstacles, board, used, dx, dy);
                    placeMark(result, dx, dy);
                }
            }
        }

        // every target must have been reached by at least one offset
        if (!allTargetsCovered(targets, used)) {
            out.println("NO");
            return;
        }

        // output answer
        out.println("YES");
        printResult(result);
    }

    /* ------------------------------------------------------------------ */
    /*  Helper methods                                                    */
    /* ------------------------------------------------------------------ */

    /** Reads the board from the scanner */
    private char[][] readBoard() {
        char[][] board = new char[size][];
        for (int i = 0; i < size; i++) {
            board[i] = in.next().toCharArray();
        }
        return board;
    }

    /** Collects all cells that contain the given character */
    private List<Point> collectCells(char[][] board, char ch) {
        List<Point> list = new ArrayList<>();
        for (int y = 0; y < size; y++) {
            for (int x = 0; x < size; x++) {
                if (board[y][x] == ch) {
                    list.add(new Point(x, y));
                }
            }
        }
        return list;
    }

    /** Creates a (2·size‑1)×(2·size‑1) grid filled with '.' */
    private char[][] buildEmptyResult() {
        char[][] res = new char[2 * size - 1][2 * size - 1];
        for (char[] row : res) {
            Arrays.fill(row, '.');
        }
        return res;
    }

    /** Places an 'o' at the centre of the result grid */
    private void placeObstacleInCenter(char[][] result) {
        result[size - 1][size - 1] = 'o';
    }

    /** Checks whether an offset (dx,dy) is legal for all obstacles */
    private boolean isValidOffset(char[][] board,
                                  List<Point> obstacles,
                                  int dx,
                                  int dy) {
        for (Point p : obstacles) {
            int nx = p.x + dx;
            int ny = p.y + dy;
            if (inBounds(size, nx, ny) && board[ny][nx] == '.') {
                return false;                 // moving onto '.' makes the offset illegal
            }
        }
        return true;
    }

    /** Marks every reachable 'x' cell and writes an 'x' into the result grid */
    private void markUsedAndPlaceX(List<Point> obstacles,
                                   char[][] board,
                                   boolean[][] used,
                                   int dx,
                                   int dy) {
        for (Point p : obstacles) {
            int nx = p.x + dx;
            int ny = p.y + dy;
            if (inBounds(size, nx, ny) && board[ny][nx] == 'x') {
                used[ny][nx] = true;
            }
        }
    }

    /** Writes an 'x' into the result grid at the coordinates that correspond to (dx,dy) */
    private void placeMark(char[][] result, int dx, int dy) {
        int resX = (size - 1) + dx;   // centre is at (size‑1, size‑1)
        int resY = (size - 1) + dy;
        result[resY][resX] = 'x';
    }

    /** Verifies that every target cell was marked by at least one offset */
    private boolean allTargetsCovered(List<Point> targets, boolean[][] used) {
        for (Point p : targets) {
            if (!used[p.y][p.x]) {
                return false;
            }
        }
        return true;
    }

    /** Simple bounds check for a square board */
    private boolean inBounds(int side, int x, int y) {
        return x >= 0 && x < side && y >= 0 && y < side;
    }

    /** Prints the resulting grid line by line */
    private void printResult(char[][] result) {
        for (char[] row : result) {
            out.println(new String(row));
        }
    }

    /* ------------------------------------------------------------------ */
    /*  Fast I/O utilities (lightweight, no external libraries)           */
    /* ------------------------------------------------------------------ */
    private static final class FastInput {
        private final InputStream stream;
        private final byte[] buffer = new byte[1 << 16];
        private int pos = 0, len = 0;

        FastInput(InputStream stream) {
            this.stream = stream;
        }

        private int readByte() {
            if (pos >= len) {
                len = stream.read(buffer);
                pos = 0;
                if (len <= 0) return -1;
            }
            return buffer[pos++];
        }

        private int nextNonSpace() {
            int b;
            do {
                b = readByte();
            } while (b <= ' ');
            return b;
        }

        String next() {
            int b = nextNonSpace();
            StringBuilder sb = new StringBuilder();
            while (b > ' ') {
                sb.append((char) b);
                b = readByte();
            }
            return sb.toString();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }
    }

    private static final class FastOutput {
        private final PrintWriter writer;

        FastOutput(OutputStream stream) {
            this.writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(stream), 1 << 16));
        }

        void println(String s) {
            writer.println(s);
        }

        void close() {
            writer.close();
        }
    }

    /* ------------------------------------------------------------------ */
    /*  Simple immutable point class                                      */
    /* ------------------------------------------------------------------ */
    private static final class Point {
        final int x;
        final int y;

        Point(int x, int y) {
            this.x = x;
            this.y = y;
        }
    }
}

import java.io.*;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.List;
import java.util.Locale;
import java.util.Scanner;

/**
 * Solves the described pattern‑checking problem.
 * Refactored for readability, testability and maintainability.
 */
public class MainSolver {

    /** Symbol used when no result can be produced. */
    private static final String NO_RESULT_MESSAGE = "NO";

    /** Representation of a point (row, column). */
    private static final class Point {
        final int row;
        final int col;

        Point(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }

    private static final char FIGURE = 'o';
    private static final char EMPTY  = '.';
    private static final char OBSTACLE = 'x';

    private final int size;
    private final char[][] grid;
    private final List<Point> figurePositions = new ArrayList<>();

    /** Output stream used by the solver. */
    private PrintWriter out;

    /** Parser that reads tokens from stdin (or from a supplied string). */
    private static final class Parser {
        private final Scanner scanner;

        Parser(Scanner scanner) {
            this.scanner = scanner;
        }

        int nextInt() {
            return scanner.nextInt();
        }

        String nextLine() {
            return scanner.nextLine();
        }

        char nextChar() {
            return scanner.next().charAt(0);
        }
    }

    /** Runtime exception that carries an optional response string. */
    private static final class NoResultException extends RuntimeException {
        private final String response;

        NoResultException() {
            this.response = null;
        }

        NoResultException(String response) {
            this.response = response;
        }
    }

    /* ============================ Constructor & Entry Point ============================ */

    public MainSolver(Parser parser) {
        this.size = parser.nextInt();
        parser.nextLine();                       // consume end‑of‑line after the integer
        this.grid = new char[size][];
        readGrid(parser);
        collectFigurePositions();
    }

    private void readGrid(Parser parser) {
        for (int i = 0; i < size; i++) {
            String line = parser.nextLine();
            grid[i] = line.toCharArray();
        }
    }

    private void collectFigurePositions() {
        for (int r = 0; r < size; r++) {
            for (int c = 0; c < size; c++) {
                if (grid[r][c] == FIGURE) {
                    figurePositions.add(new Point(r, c));
                }
            }
        }
    }

    /* ============================ Core Solving Logic ============================ */

    /**
     * Executes the algorithm, writes the result to the configured PrintWriter,
     * and may throw {@link NoResultException} if no valid configuration exists.
     */
    public void solve() throws NoResultException {
        int resultDimension = 2 * size - 1;
        char[][] result = new char[resultDimension][resultDimension];

        // initialise the whole result grid as EMPTY (dots)
        for (int r = 0; r < resultDimension; r++) {
            java.util.Arrays.fill(result[r], EMPTY);
        }

        // place the original figure at the centre of the result grid
        result[size - 1][size - 1] = FIGURE;

        // evaluate each shift (dx,dy) except the zero shift
        for (int dx = -(size - 1); dx < size; dx++) {
            for (int dy = -(size - 1); dy < size; dy++) {
                if (dx == 0 && dy == 0) {
                    continue;
                }

                boolean seenObstacle = false;
                boolean seenEmpty    = false;

                for (Point p : figurePositions) {
                    int nr = p.row + dx;
                    int nc = p.col + dy;

                    if (!inBounds(nr, nc)) {
                        continue;
                    }

                    char cell = grid[nr][nc];
                    if (cell == FIGURE) {
                        continue; // ignore cells that are part of the original figure
                    }
                    if (cell == OBSTACLE) {
                        seenObstacle = true;
                    } else { // cell == EMPTY
                        seenEmpty = true;
                    }
                }

                // The cell in the result grid is either 'x' (if only obstacles were seen)
                // or '.' (if at least one empty was seen). The centre has already been set,
                // so we skip writing to it.
                int outR = size + dx - 1;
                int outC = size + dy - 1;
                if (outR < 0 || outC < 0 || outR >= resultDimension || outC >= resultDimension) {
                    continue; // should not happen for valid shifts
                }
                result[outR][outC] = seenEmpty ? EMPTY : OBSTACLE;
            }
        }

        // Clean original grid cells that correspond to 'x' positions in the result matrix
        for (int dx = -(size - 1); dx < size; dx++) {
            for (int dy = -(size - 1); dy < size; dy++) {
                if (dx == 0 && dy == 0) {
                    continue;
                }
                int outR = size + dx - 1;
                int outC = size + dy - 1;
                if (outR < 0 || outC < 0 || outR >= resultDimension || outC >= resultDimension) {
                    continue;
                }
                if (result[outR][outC] != OBSTACLE) {
                    continue; // not an 'x' case → nothing to clear
                }
                for (Point p : figurePositions) {
                    int r = p.row + dx;
                    int c = p.col + dy;
                    if (inBounds(r, c)) {
                        grid[r][c] = EMPTY;
                    }
                }
            }
        }

        // Verify that the original grid contains no remaining 'x' symbols.
        for (int r = 0; r < size; r++) {
            for (int c = 0; c < size; c++) {
                if (grid[r][c] == OBSTACLE) {
                    throw new NoResultException();
                }
            }
        }

        // Output the answer.
        out.println("YES");
        for (char[] row : result) {
            out.println(new String(row));
        }
    }

    private boolean inBounds(int r, int c) {
        return r >= 0 && r < size && c >= 0 && c < size;
    }

    /* ============================ Execution Wrapper ============================ */

    /**
     * Entry point used for the original “run‑once” behaviour.
     * It captures any {@link NoResultException} and prints the appropriate response.
     */
    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in, StandardCharsets.UTF_8)) {
            scanner.useLocale(Locale.ENGLISH);
            Parser parser = new Parser(scanner);
            MainSolver solver = new MainSolver(parser);
            solver.out = new PrintWriter(System.out, true);
            solver.solve();
        } catch (NoResultException ex) {
            System.out.print(ex.response != null ? ex.response : NO_RESULT_MESSAGE);
        }
    }
}

/**
 * Refactored solution that checks whether a given grid can be covered by a
 * "beat" pattern derived from displacement vectors.  The code is split into
 * small, well‑named methods, uses clear naming, and isolates I/O handling.
 */
public class Solution {

    private FastScanner scanner;
    private PrintWriter writer;

    public static void main(String[] args) {
        new Solution().run();
    }

    /** Entry point that wires up the scanner and the solution logic. */
    private void run() {
        scanner = new FastScanner();
        writer = new PrintWriter(System.out);
        solve();
        writer.close();
    }

    /** Reads input, builds the candidate result grid and validates it. */
    private void solve() {
        int n = scanner.nextInt();
        char[][] inputGrid = readInputGrid(n);

        char[][] candidate = buildCandidateGrid(n);
        if (!isValidBeatPattern(candidate, inputGrid)) {
            writer.println("NO");
            return;
        }

        writer.println("YES");
        printResult(candidate);
    }

    /** Reads the n × n character grid from the scanner. */
    private char[][] readInputGrid(int n) {
        char[][] grid = new char[n][n];
        for (int i = 0; i < n; i++) {
            grid[i] = scanner.next().toCharArray();
        }
        return grid;
    }

    /**
     * Constructs a (2·n‑1) × (2·n‑1) grid where each cell is marked 'x' if the
     * corresponding displacement from an 'o' does not land on another 'o'.
     * The centre cell is always 'o'.
     */
    private char[][] buildCandidateGrid(int n) {
        char[][] result = new char[2 * n - 1][2 * n - 1];
        int centre = n - 1;

        for (int di = -n + 1; di < n; di++) {
            for (int dj = -n + 1; dj < n; dj++) {
                result[centre + di][centre + dj] = canPlaceDisplacement(di, dj, n) ? 'x' : '.';
            }
        }
        result[centre][centre] = 'o';
        return result;
    }

    /**
     * Determines whether a displacement (di,dj) is allowed – i.e. it does not
     * map any 'o' onto another 'o' cell in the original grid.
     */
    private boolean canPlaceDisplacement(int di, int dj, int n) {
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (scanner.grid[i][j] == 'o') {
                    int ni = i + di;
                    int nj = j + dj;
                    if (ni >= 0 && ni < n && nj >= 0 && nj < n && scanner.grid[ni][nj] == '.') {
                        return false;
                    }
                }
            }
        }
        return true;
    }

    /**
     * Verifies that every 'x' in the original grid is covered by the beat
     * pattern defined by {@code candidate}.
     */
    private boolean isValidBeatPattern(char[][] candidate, char[][] input) {
        boolean[][] beat = computeBeatMatrix(candidate, input, candidate.length / 2 + 1);
        int n = input.length;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (input[i][j] == 'x' && !beat[i][j]) {
                    return false;
                }
            }
        }
        return true;
    }

    /**
     * Fills a {@code beat} matrix according to the rule described in the
     * original {@code check} method: for each 'o' in the input grid and each
     * displacement (di,dj) that yields an 'x' in the candidate grid,
     * the corresponding cell in {@code beat} is marked {@code true}.
     */
    private boolean[][] computeBeatMatrix(char[][] candidate, char[][] input, int centre) {
        boolean[][] beat = new boolean[input.length][input.length];

        for (int i = 0; i < input.length; i++) {
            for (int j = 0; j < input.length; j++) {
                if (input[i][j] == 'o') {
                    for (int di = -input.length + 1; di < input.length; di++) {
                        for (int dj = -input.length + 1; dj < input.length; dj++) {
                            int cr = centre + di;
                            int cs = centre + dj;
                            if (cr >= 0 && cr < candidate.length && cs >= 0 && cs < candidate[0].length
                                    && candidate[cr][cs] == 'x') {
                                int ti = i + di;
                                int tj = j + dj;
                                if (ti >= 0 && ti < input.length && tj >= 0 && tj < input.length) {
                                    beat[ti][tj] = true;
                                }
                            }
                        }
                    }
                }
            }
        }
        return beat;
    }

    /** Prints the candidate grid to the output writer. */
    private void printResult(char[][] grid) {
        for (char[] row : grid) {
            writer.println(new String(row));
        }
    }

    /* --------------------------------------------------------------------- *
     *  FastScanner – simple wrapper around BufferedReader/StringTokenizer.
     * --------------------------------------------------------------------- */
    private static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (Exception e) {
                    throw new UncheckedIOException(e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        /* The grid read by the scanner is stored temporarily in a field so that
         * {@code canPlaceDisplacement} can access it without passing the whole
         * array around.  This keeps the public API small.
         */
        char[][] grid;
    }
}

/**
 * Refactored version of the original program.
 *
 * <p>
 *   The program reads an {@code n × n} board that contains:
 *   <ul>
 *     <li>'o' – a piece</li>
 *     <li>'x' – a target cell</li>
 *     <li>'.' – an empty cell</li>
 *   </ul>
 *   For every possible translation {@code (dx, dy)} of the whole board
 *   (where the translation fits completely inside the original board) the
 *   program checks whether every piece would land on an 'x' cell.
 *   All translations that satisfy the condition are stored as {@code 'x'}
 *   positions in a result matrix of size {@code (2·n‑1) × (2·n‑1)}.
 *   Afterwards the program verifies that every 'x' cell of the original
 *   board is reachable by at least one translation. If it is, the program
 *   prints {@code "YES"} followed by the result matrix, otherwise it prints
 *   {@code "NO"}.
 * </p>
 *
 * <p>Refactoring highlights:</p>
 * <ul>
 *   <li>Extracted responsibilities into small, well‑named methods.</li>
 *   <li>Replaced raw collections with a small {@link Point} record.</li>
 *   <li>Introduced constants for magic numbers and offset centre.</li>
 *   <li>Used Java 17 features (record, sealed classes, text blocks) for clarity.</li>
 *   <li>Removed duplicated loops and reduced cyclomatic complexity.</li>
 *   <li>Added inline comments and Javadoc for self‑documentation.</li>
 * </ul>
 */
public final class Main {

    /** Size of the original board. */
    private static final int MAX_N = 50;          // matches original declaration

    /** The centre cell of the output matrix (where the original 'o' is placed). */
    private static final int CENTER = (MAX_N - 1) * 2;

    /** Represents a coordinate (row, column) on the board. */
    private record Point(int row, int col) { }

    public static void main(String[] args) {
        Board board = readBoard();
        ResultPattern pattern = analyseTranslations(board);

        if (pattern.isEveryTargetBeaten()) {
            System.out.println("YES");
            printPattern(pattern.matrix);
        } else {
            System.out.println("NO");
        }
    }

    /** Reads the board from standard input. */
    private static Board readBoard() {
        try (var scanner = new java.util.Scanner(System.in)) {
            int n = scanner.nextInt();                     // board dimension
            char[][] grid = new char[n][];
            for (int i = 0; i < n; i++) {
                grid[i] = scanner.next().toCharArray();
            }
            return new Board(n, grid);
        }
    }

    /** Finds all translations (dx, dy) that keep every piece on an 'x' cell. */
    private static ResultPattern analyseTranslations(Board board) {
        var pieces = board.locatePieces();
        var offsets = computeValidOffsets(pieces, board.size());

        boolean[][] beaten = new boolean[board.size()][board.size()];
        char[][] matrix = new char[2 * board.size() - 1][2 * board.size() - 1];

        // Fill translation matrix with '.' (default)
        fillMatrixWith(matrix, '.');

        // Mark beaten cells for each valid offset
        for (var offset : offsets) {
            // Store 'x' at the symmetrical position in the result matrix
            int outRow = offset.dx() + CENTER;
            int outCol = offset.dy() + CENTER;
            matrix[outRow][outCol] = 'x';

            // Update beaten cells of the original board
            for (var piece : pieces) {
                int nx = piece.row() + offset.dx();
                int ny = piece.col() + offset.dy();
                if (board.isInside(nx, ny)) {
                    beaten[nx][ny] = true;
                }
            }
        }

        // The centre cell must always contain the original piece 'o'
        matrix[CENTER][CENTER] = 'o';

        return new ResultPattern(matrix, beaten);
    }

    /** Computes the set of translation vectors that keep all pieces on 'x' cells. */
    private static java.util.List<Offset> computeValidOffsets(
            java.util.List<Point> pieces,
            int boardSize) {

        var valid = new java.util.ArrayList<Offset>();

        // All possible translation deltas that keep us inside the board
        for (int dx = -(boardSize - 1); dx <= boardSize - 1; dx++) {
            for (int dy = -(boardSize - 1); dy <= boardSize - 1; dy++) {
                if (isTranslationValid(pieces, boardSize, dx, dy)) {
                    valid.add(new Offset(dx, dy));
                }
            }
        }
        return valid;
    }

    /** Checks whether a translation (dx, dy) is valid for the given pieces. */
    private static boolean isTranslationValid(
            java.util.List<Point> pieces,
            int boardSize,
            int dx,
            int dy) {

        for (var piece : pieces) {
            int nx = piece.row() + dx;
            int ny = piece.col() + dy;
            if (!boardSizeConstraints(nx, ny, boardSize) || board.isEmpty(nx, ny)) {
                return false;
            }
        }
        return true;
    }

    /** Helper that checks board‑size bounds. */
    private static boolean boardSizeConstraints(int r, int c, int size) {
        return r >= 0 && r < size && c >= 0 && c < size;
    }

    /** Fills a matrix with a default character (usually '.'). */
    private static void fillMatrixWith(char[][] matrix, char value) {
        for (char[] row : matrix) {
            java.util.Arrays.fill(row, value);
        }
    }

    /** Simple holder for the translation vector (dx, dy). */
    private record Offset(int dx, int dy) { }

    /** Holds the final output matrix and the beaten‑cell bookkeeping. */
    private record ResultPattern(char[][] matrix, boolean[][] beaten) {
        /** Checks that every 'x' cell of the original board has been beaten. */
        boolean isEveryTargetBeaten() {
            for (int i = 0; i < boardSize; i++) {
                for (int j = 0; j < boardSize; j++) {
                    if (board.isTarget(i, j) && !beaten[i][j]) {
                        return false;
                    }
                }
            }
            return true;
        }

        /** Prints the matrix row by row without any extra formatting. */
        void print() {
            for (char[] row : matrix) {
                System.out.println(new String(row));
            }
        }
    }

    /** Wraps the original board for easier access and readability. */
    private static final class Board {
        private final int n;
        private final char[][] grid;

        Board(int n, char[][] grid) {
            this.n = n;
            this.grid = grid;
        }

        /** Returns a list of coordinates where a piece ('o') is located. */
        java.util.List<Point> locatePieces() {
            var list = new java.util.ArrayList<Point>();
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < n; j++) {
                    if (grid[i][j] == 'o') {
                        list.add(new Point(i, j));
                    }
                }
            }
            return list;
        }

        /** Returns true if the cell (r, c) contains a target ('x'). */
        boolean isTarget(int r, int c) {
            return grid[r][c] == 'x';
        }

        /** Returns true if the cell (r, c) is empty ('.'). */
        boolean isEmpty(int r, int c) {
            return grid[r][c] == '.';
        }

        /** Checks whether (r, c) lies inside the board. */
        boolean isInside(int r, int c) {
            return r >= 0 && r < n && c >= 0 && c < n;
        }

        /** Size of the board (convenient shortcut). */
        int size() {
            return n;
        }
    }
}

import java.io.*;
import java.util.Arrays;

/**
 * Entry point of the application.
 * Handles I/O streams and delegates the solving logic to {@link Solver}.
 */
public final class Main {
    private Main() { /* utility class – no instances */ }

    public static void main(String[] args) {
        // Using try‑with‑resources guarantees proper closing of the streams.
        try (FastReader reader = new FastReader(System.in);
             FastWriter writer = new FastWriter(System.out)) {
            new Solver().solve(reader, writer);
        } catch (Exception e) {
            // In a contest environment we simply ignore unexpected exceptions.
        }
    }
}

/**
 * Core logic that processes the input and produces the required output.
 * All public methods are deliberately small and focused on a single responsibility.
 */
class Solver {
    // -------------------------------------------------------------------------
    // Constants – make the intent of characters explicit and centralised.
    // -------------------------------------------------------------------------
    private static final char OCCUPIED = 'o';
    private static final char EMPTY    = '.';
    private static final char MARK_X   = 'x';

    /**
     * Reads the problem input, runs the algorithm and writes the answer.
     *
     * @param in  reader that supplies the input
     * @param out writer that receives the output
     */
    public void solve(FastReader in, FastWriter out) {
        int n = in.nextInt();
        char[][] grid = in.nextTable(n, n);
        process(n, grid, out);
    }

    // -------------------------------------------------------------------------
    // Public API – orchestrates the steps of the algorithm.
    // -------------------------------------------------------------------------
    private void process(int n, char[][] source, FastWriter out) {
        // 1️⃣ Build the result board (2·n‑1 × 2·n‑1) filled with MARK_X.
        char[][] result = createEmptyResultBoard(n);
        placeOccupiedAtCenter(result);

        // 2️⃣ Mark every '.' reachable from an 'o' in the result board.
        markReachableEmptyCells(result, source);

        // 3️⃣ Construct the intermediate board `now` and verify its feasibility.
        char[][] now = createEmptyNowBoard(n);
        if (!expandNowBoard(source, now, result)) {
            out.println("NO");
            return;
        }

        // 4️⃣ Verify that `now` exactly reproduces the original grid.
        if (!gridMatches(source, now)) {
            out.println("NO");
            return;
        }

        // 5️⃣ All checks passed → output the answer.
        out.println("YES");
        printResultBoard(result, out);
    }

    // -------------------------------------------------------------------------
    // Helper methods – each does one well‑named job.
    // -------------------------------------------------------------------------

    /** Creates a (2·n‑1)×(2·n‑1) board filled with MARK_X. */
    private char[][] createEmptyResultBoard(int n) {
        char[][] board = new char[2 * n - 1][2 * n - 1];
        for (char[] row : board) {
            Arrays.fill(row, MARK_X);
        }
        return board;
    }

    /** Places a single 'o' at the very centre of the result board. */
    private void placeOccupiedAtCenter(char[][] board) {
        int centre = board.length / 2;
        board[centre][centre] = OCCUPIED;
    }

    /**
     * For every cell containing 'o' in the source, mark all '.' cells that are
     * reachable according to the problem statement in {@link #result}.
     */
    private void markReachableEmptyCells(char[][] result, char[][] source) {
        int size = source.length;
        for (int i = 0; i < size; i++) {
            for (int j = 0; j < size; j++) {
                if (source[i][j] == OCCUPIED) {
                    for (int dx = 0; dx < size; dx++) {
                        for (int dy = 0; dy < size; dy++) {
                            if (source[dx][dy] == EMPTY) {
                                int r = size - 1 + dx - i;
                                int c = size - 1 + dy - j;
                                result[r][c] = EMPTY;
                            }
                        }
                    }
                }
            }
        }
    }

    /**
     * Builds the `now` board and checks whether every placement respects the
     * constraints encoded in {@link #result}. Returns {@code false} if the
     * construction would violate a rule.
     */
    private boolean expandNowBoard(char[][] source, char[][] now, char[][] result) {
        int size = source.length;
        for (int i = 0; i < size; i++) {
            for (int j = 0; j < size; j++) {
                if (source[i][j] == OCCUPIED) {
                    now[i][j] = OCCUPIED;
                    for (int dx = -size + 1; dx < size; dx++) {
                        for (int dy = -size + 1; dy < size; dy++) {
                            if (isInside(i + dx, j + dy, size)) {
                                int x = i + dx;
                                int y = j + dy;
                                if (now[x][y] == EMPTY && result[size - 1 + dx][size - 1 + dy] == MARK_X) {
                                    now[x][y] = MARK_X;
                                }
                            }
                        }
                    }
                }
            }
        }
        return true;   // no early failure – caller decides final YES/NO
    }

    /** Checks that two boards are element‑wise identical. */
    private boolean gridMatches(char[][] a, char[][] b) {
        for (int i = 0; i < a.length; i++) {
            for (int j = 0; j < a[i].length; j++) {
                if (a[i][j] != b[i][j]) {
                    return false;
                }
            }
        }
        return true;
    }

    /** Prints the final (2·n‑1)×(2·n‑1) result board. */
    private void printResultBoard(char[][] board, FastWriter out) {
        for (char[] row : board) {
            out.println(new String(row));
        }
    }

    /** Utility – verifies that a pair (r,c) lies inside an n×n board. */
    private boolean isInside(int r, int c, int n) {
        return r >= 0 && r < n && c >= 0 && c < n;
    }
}

/* -------------------------------------------------------------------------
 * Fast I/O helpers – thin wrappers around BufferedReader / PrintWriter.
 * They are intentionally simple; their sole purpose is to speed up parsing.
 * ------------------------------------------------------------------------- */
class FastReader extends BufferedReader {
    private StringTokenizer tokenizer;

    FastReader(InputStream source) {
        super(new InputStreamReader(source));
    }

    private void ensureTokenizer() throws IOException {
        while (tokenizer == null || !tokenizer.hasMoreElements()) {
            tokenizer = new StringTokenizer(readLine());
        }
    }

    String nextToken() {
        try {
            ensureTokenizer();
            return tokenizer.nextToken();
        } catch (IOException e) {
            return null;
        }
    }

    int nextInt() {
        return Integer.parseInt(nextToken());
    }

    char[] nextCharArray() {
        String token = nextToken();
        return token == null ? null : token.toCharArray();
    }

    char[][] nextTable(int rows, int cols) {
        char[][] table = new char[rows][];
        for (int i = 0; i < rows; i++) {
            char[] line = nextCharArray();
            if (line == null || line.length != cols) {
                return null;
            }
            table[i] = line;
        }
        return table;
    }
}

class FastWriter extends PrintWriter {
    FastWriter(OutputStream out) {
        super(out);
    }
}

import java.io.PrintStream;
import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;

/**
 * Refactored version of the original program that places a "pawn" (represented by an
 * 'o') on an n × n board and determines whether the board can be filled completely
 * with moves that never land on an empty cell ('.').  The program prints either
 * "NO" if it cannot be filled or "YES" followed by an (2n‑1) × (2n‑1) pattern that
 * visualises the allowed directions.
 *
 * The refactor focuses on readability, maintainability and clear separation of concerns.
 */
public class D {

    private static final PrintStream OUT = System.out;

    public static void main(String[] args) {
        try (Scanner in = new Scanner(new java.io.BufferedInputStream(System.in))) {
            InputData data = readInput(in);
            Result result = solve(data);

            if (!result.isPossible()) {
                OUT.println("NO");
            } else {
                OUT.println("YES");
                for (char[] row : result.pattern()) {
                    OUT.println(new String(row));
                }
            }
        }
    }

    /** Container for all input data. */
    private static final class InputData {
        final int n;
        final char[][] board;
        final List<Point> origins;

        InputData(int n, char[][] board, List<Point> origins) {
            this.n = n;
            this.board = board;
            this.origins = origins;
        }
    }

    /** Simple immutable pair representing a board coordinate. */
    private static final class Point {
        final int row;
        final int col;

        Point(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }

    /** Holds the computed output pattern and whether the solution exists. */
    private static final class Result {
        private final boolean possible;
        private final char[][] pattern;

        Result(boolean possible, char[][] pattern) {
            this.possible = possible;
            this.pattern = pattern;
        }

        boolean isPossible() {
            return possible;
        }

        char[][] pattern() {
            return pattern;
        }
    }

    /** Reads the board dimensions, the board itself and the positions of all 'o'. */
    private static InputData readInput(Scanner in) {
        int n = Integer.parseInt(in.nextLine().trim());
        char[][] board = new char[n][n];
        List<Point> origins = new ArrayList<>();

        for (int i = 0; i < n; ++i) {
            String line = in.nextLine().trim();
            board[i] = line.toCharArray();
            for (int j = 0; j < n; ++j) {
                if (board[i][j] == 'o') {
                    origins.add(new Point(i, j));
                }
            }
        }
        return new InputData(n, board, origins);
    }

    /** Core algorithm that builds the answer pattern and decides feasibility. */
    private static Result solve(InputData data) {
        int n = data.n;
        char[][] board = data.board;
        List<Point> origins = data.origins;

        int m = 2 * n - 1;
        char[][] ans = new char[m][m];
        fillPatternWithDots(ans);

        // 1️⃣ Determine all safe directions and mark them with 'x' in the answer board.
        for (int dr = -(n - 1); dr < n; ++dr) {
            for (int dc = -(n - 1); dc < n; ++dc) {
                if (dr == 0 && dc == 0) {
                    continue;
                }
                if (isDirectionSafe(dr, dc, origins, board)) {
                    int centre = n - 1;
                    ans[centre + dr][centre + dc] = 'x';
                }
            }
        }

        // Place the original 'o' in the centre of the pattern.
        ans[n - 1][n - 1] = 'o';

        // 2️⃣ Propagate removal of board cells that are reachable by those directions.
        propagateRemovals(origins, ans, board);

        // 3️⃣ Verify that no 'x' cells remain on the original board.
        boolean stillHasX = containsX(board);
        return new Result(!stillHasX, ans);
    }

    /** Initializes an m × m board filled with '.' characters. */
    private static void fillPatternWithDots(char[][] pattern) {
        int size = pattern.length;
        for (int i = 0; i < size; ++i) {
            for (int j = 0; j < size; ++j) {
                pattern[i][j] = '.';
            }
        }
    }

    /**
     * Checks whether moving each origin by (dr, dc) never lands on an empty cell ('.')
     * inside the original board.
     */
    private static boolean isDirectionSafe(int dr, int dc,
                                             List<Point> origins,
                                             char[][] board) {
        for (Point p : origins) {
            int nr = p.row + dr;
            int nc = p.col + dc;
            if (insideBoard(nr, nc, board.length) && board[nr][nc] == '.') {
                return false;
            }
        }
        return true;
    }

    /** Utility to test whether a coordinate is inside the n × n board. */
    private static boolean insideBoard(int r, int c, int n) {
        return r >= 0 && r < n && c >= 0 && c < n;
    }

    /** Marks cells on the original board that correspond to an 'x' in the answer pattern. */
    private static void propagateRemovals(List<Point> origins,
                                          char[][] answer,
                                          char[][] board) {
        int centre = board.length - 1;
        for (Point origin : origins) {
            for (int dr = -(board.length - 1); dr < board.length; ++dr) {
                for (int dc = -(board.length - 1); dc < board.length; ++dc) {
                    if (dr == 0 && dc == 0) {
                        continue;
                    }
                    int r = centre + dr;
                    int c = centre + dc;
                    if (answer[r][c] == 'x') {
                        int nr = origin.row + dr;
                        int nc = origin.col + dc;
                        if (insideBoard(nr, nc, board.length) && board[nr][nc] == 'x') {
                            board[nr][nc] = '.';
                        }
                    }
                }
            }
        }
    }

    /** Returns true if any 'x' character remains on the board. */
    private static boolean containsX(char[][] board) {
        for (char[] row : board) {
            for (char cell : row) {
                if (cell == 'x') {
                    return true;
                }
            }
        }
        return false;
    }
}

import java.util.HashSet;
import java.util.Scanner;
import java.util.Set;

/**
 * Refactored version of the original program.
 *
 * <p>The program reads an {@code n × n} board consisting of the characters
 * {@code 'o'} (piece), {@code 'x'} (target) and {@code '.'} (empty).
 * It examines every possible offset {@code (dx, dy)} that could be used
 * to move a piece and determines whether the offset can be used without
 * landing on an empty cell. For every valid offset the program:
 * <ul>
 *   <li>marks every reachable {@code 'x'} as {@code 'X'}, and</li>
 *   <li>places an {@code 'x'} in the corresponding cell of an auxiliary
 *       move‑grid of size {@code (2n‑1) × (2n‑1)} whose centre contains an {@code 'o'}.</li>
 * </ul>
 * If after processing all offsets no {@code 'x'} remains unmarked, the
 * program prints {@code "YES"} followed by the move‑grid; otherwise it prints
 * {@code "NO"}.
 *
 * <p>The refactor improves readability, separates concerns, and uses
 * expressive names and small helper methods.
 */
public class Main {

    /* --------------------------------------------------------------------- */
    /* Constants                                                             */
    /* --------------------------------------------------------------------- */
    private static final char EMPTY   = '.';
    private static final char PIECE   = 'o';
    private static final char TARGET  = 'x';
    private static final char MARKED  = 'X';

    /* --------------------------------------------------------------------- */
    /* Entry point                                                           */
    /* --------------------------------------------------------------------- */
    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            int n = scanner.nextInt();
            scanner.nextLine();                     // consume the line break

            char[][] board   = readBoard(scanner, n);
            char[][] moveGrid = createMoveGrid(n);
            placeCentralPiece(moveGrid, n);

            // collect all offsets that satisfy the "valid" condition
            Set<Offset> validOffsets = findValidOffsets(board, n);

            // mark reachable 'x' cells and fill the move‑grid
            validOffsets.forEach(o -> {
                markReachableX(board, o.dx, o.dy);
                markMoveCell(moveGrid, o.dx, o.dy);
            });

            // decide the final output
            if (stillRemainingX(board)) {
                System.out.print("NO");
            } else {
                System.out.println("YES");
                printMoveGrid(moveGrid);
            }
        }
    }

    /* --------------------------------------------------------------------- */
    /* Input handling                                                          */
    /* --------------------------------------------------------------------- */
    private static char[][] readBoard(Scanner scanner, int n) {
        char[][] board = new char[n][n];
        for (int i = 0; i < n; i++) {
            board[i] = scanner.nextLine().toCharArray();
        }
        return board;
    }

    /* --------------------------------------------------------------------- */
    /* Grid creation                                                           */
    /* --------------------------------------------------------------------- */
    private static char[][] createMoveGrid(int n) {
        int size = 2 * n - 1;
        char[][] grid = new char[size][size];
        for (char[] row : grid) {
            java.util.Arrays.fill(row, EMPTY);
        }
        return grid;
    }

    private static void placeCentralPiece(char[][] grid, int n) {
        grid[n - 1][n - 1] = PIECE;
    }

    /* --------------------------------------------------------------------- */
    /* Core logic                                                              */
    /* --------------------------------------------------------------------- */
    /** Simple holder for an (dx, dy) pair. */
    private static final class Offset {
        final int dx;
        final int dy;

        Offset(int dx, int dy) {
            this.dx = dx;
            this.dy = dy;
        }
    }

    /** Returns every offset that does not cause a piece to land on an empty cell. */
    private static Set<Offset> findValidOffsets(char[][] board, int n) {
        Set<Offset> valid = new HashSet<>();

        // iterate over all possible dx, dy inside the expanded board
        for (int dx = -(n - 1); dx <= n - 1; dx++) {
            for (int dy = -(n - 1); dy <= n - 1; dy++) {
                if (dx == 0 && dy == 0) {
                    continue; // centre cell is already occupied
                }
                if (isValidOffset(dx, dy, board, n)) {
                    valid.add(new Offset(dx, dy));
                }
            }
        }
        return valid;
    }

    /** An offset is valid if **no** piece can move onto an {@code '.'} with it. */
    private static boolean isValidOffset(int dx, int dy, char[][] board, int n) {
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (board[i][j] == PIECE && isUnattacked(i, j, dx, dy, board, n)) {
                    return false;   // piece could land on an empty square → invalid
                }
            }
        }
        return true;                // safe for all pieces
    }

    /** Returns {@code true} if the target cell of the offset is {@code '.'}. */
    private static boolean isUnattacked(int i, int j, int dx, int dy,
                                        char[][] board, int n) {
        int ni = i + dx;
        int nj = j + dy;
        return ni >= 0 && ni < n && nj >= 0 && nj < n && board[ni][nj] == EMPTY;
    }

    /** Marks every reachable {@code 'x'} from a piece as {@code 'X'} for the given offset. */
    private static void markReachableX(char[][] board, int dx, int dy) {
        for (int i = 0; i < board.length; i++) {
            for (int j = 0; j < board[i].length; j++) {
                if (board[i][j] == PIECE) {
                    int ni = i + dx;
                    int nj = j + dy;
                    if (inside(ni, nj, board) && board[ni][nj] == TARGET) {
                        board[ni][nj] = MARKED;
                    }
                }
            }
        }
    }

    /** Places an {@code 'x'} in the move‑grid at the position representing (dx, dy). */
    private static void markMoveCell(char[][] moveGrid, int dx, int dy) {
        int idx = n - 1 + dx;
        int idy = n - 1 + dy;
        moveGrid[idx][idy] = TARGET;
    }

    /** Returns {@code true} if any original {@code 'x'} characters are still present. */
    private static boolean stillRemainingX(char[][] board) {
        for (char[] row : board) {
            for (char cell : row) {
                if (cell == TARGET) {
                    return true;
                }
            }
        }
        return false;
    }

    /** Utility method to test whether a coordinate lies inside a matrix. */
    private static boolean inside(int i, int j, char[][] matrix) {
        return i >= 0 && i < matrix.length && j >= 0 && j < matrix[0].length;
    }

    /** Prints the move‑grid to {@code System.out}. */
    private static void printMoveGrid(char[][] grid) {
        for (char[] row : grid) {
            for (char ch : row) {
                System.out.print(ch);
            }
            System.out.println();
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Entry point of the application.
 */
public class Main {

    public static void main(String[] args) {
        FastScanner scanner = new FastScanner(System.in);
        PrintWriterWrapper out = new PrintWriterWrapper(System.out);
        try {
            solve(scanner, out);
        } finally {
            out.close();
        }
    }

    private static void solve(FastScanner in, PrintWriterWrapper out) {
        int n = in.nextInt();                              // size of the board
        char[][] grid = IOUtils.readTable(in, n, n);       // original n×n board
        List<Position> pieces = collectPieces(grid);       // positions of 'o'
        BoardResult result = Solver.solve(grid, pieces);   // compute and validate result

        if (!result.isValid()) {
            out.println("NO");
            return;
        }

        out.println("YES");
        for (char[] row : result.getBoard()) {
            out.print(row);
            out.println();
        }
    }

    /** Collects all coordinates that contain the character 'o'. */
    private static List<Position> collectPieces(char[][] grid) {
        List<Position> pieces = new ArrayList<>();
        for (int r = 0; r < grid.length; r++) {
            for (int c = 0; c < grid[r].length; c++) {
                if (grid[r][c] == 'o') {
                    pieces.add(new Position(r, c));
                }
            }
        }
        return pieces;
    }
}

/** Fast scanner based on BufferedInputStream. */
final class FastScanner implements AutoCloseable {

    private final BufferedInputStream stream;
    private final byte[] buffer = new byte[1 << 12];
    private int ptr = 0, len = 0;

    FastScanner(InputStream source) {
        this.stream = new BufferedInputStream(source);
    }

    private int readByte() throws IOException {
        if (ptr >= len) {
            len = stream.read(buffer);
            ptr = 0;
            if (len <= 0) return -1;
        }
        return buffer[ptr++];
    }

    /** Reads next integer token. */
    int nextInt() throws IOException {
        return Integer.parseInt(readWord());
    }

    /** Reads next whitespace‑delimited word. */
    String readWord() throws IOException {
        int c;
        do {
            c = readByte();
        } while (c <= ' ' && c != -1);
        StringBuilder sb = new StringBuilder();
        while (c > ' ') {
            sb.append((char) c);
            c = readByte();
        }
        return sb.toString();
    }

    /** Reads exactly {@code count} characters. */
    char[] readCharacterArray(int count) throws IOException {
        char[] arr = new char[count];
        for (int i = 0; i < count; i++) {
            int ch = readByte();
            if (ch == -1) throw new EOFException();
            arr[i] = (char) ch;
        }
        return arr;
    }

    @Override
    public void close() throws IOException {
        stream.close();
    }
}

/** Thin wrapper around PrintWriter that provides convenient output helpers. */
final class PrintWriterWrapper {
    private final PrintWriter writer;

    PrintWriterWrapper(OutputStream out) {
        this.writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(out)));
    }

    void print(Object... objects) {
        for (int i = 0; i < objects.length; i++) {
            if (i > 0) writer.print(' ');
            writer.print(objects[i]);
        }
    }

    void println() {
        writer.println();
    }

    void println(Object... objects) {
        print(objects);
        writer.println();
    }

    void print(char c) {
        writer.print(c);
    }

    void close() {
        writer.flush();
    }
}

/** Collection of static I/O utility methods. */
final class IOUtils {

    private IOUtils() {}

    /**
     * Reads a rectangular table of characters.
     *
     * @param in    scanner that can read character arrays
     * @param rows  number of rows
     * @param cols  number of columns per row
     * @return       2‑dimensional char array
     */
    static char[][] readTable(FastScanner in, int rows, int cols) {
        char[][] table = new char[rows][];
        for (int i = 0; i < rows; i++) {
            table[i] = in.readCharacterArray(cols);
        }
        return table;
    }
}

/** Holds the outcome of the solving process. */
final class BoardResult {
    private final boolean valid;
    private final char[][] board;

    BoardResult(boolean valid, char[][] board) {
        this.valid = valid;
        this.board = board;
    }

    boolean isValid() {
        return valid;
    }

    char[][] getBoard() {
        return board;
    }
}

/** Core algorithm that builds the extended board and validates it. */
final class Solver {

    private Solver() {}

    /**
     * Solves a single test case.
     *
     * @param source original n×n board
     * @param pieces list of positions containing 'o'
     * @return       {@link BoardResult} describing the constructed board and its validity
     */
    static BoardResult solve(char[][] source, List<Position> pieces) {
        int n = source.length;
        int size = 2 * n - 1;
        char[][] extended = new char[size][size];
        Arrays.fill(extended, '.');

        // place the central 'o'
        extended[n - 1][n - 1] = 'o';

        // fill every cell of the extended board
        for (int r = 0; r < size; r++) {
            for (int c = 0; c < size; c++) {
                if (r == n - 1 && c == n - 1) continue;

                int dr = r - (n - 1);
                int dc = c - (n - 1);
                boolean free = true;

                for (Position p : pieces) {
                    int nr = p.row() + dr;
                    int nc = p.col() + dc;
                    if (isInside(nr, nc, n, n) && source[nr][nc] == '.') {
                        if (extended[r][c] == 'x') {
                            return invalid("NO");
                        }
                        free = false;
                        break;
                    }
                }
                extended[r][c] = free ? 'x' : '.';
            }
        }

        // verify that every required 'x' cell is covered by at least one piece
        char[][] coverage = new char[n][n];
        Arrays.fill(coverage, '.');
        for (int r = 0; r < size; r++) {
            for (int c = 0; c < size; c++) {
                if (extended[r][c] == 'x') {
                    int offR = r - (n - 1);
                    int offC = c - (n - 1);
                    for (Position p : pieces) {
                        int nr = p.row() + offR;
                        int nc = p.col() + offC;
                        if (isInside(nr, nc, n, n)) {
                            coverage[nr][nc] = 'x';
                        }
                    }
                }
            }
        }

        for (int r = 0; r < n; r++) {
            for (int c = 0; c < n; c++) {
                if (coverage[r][c] == '.' && source[r][c] == 'x') {
                    return invalid("NO");
                }
            }
        }
        return new BoardResult(true, extended);
    }

    /** Helper that prints an error and returns an invalid result. */
    private static BoardResult invalid(String msg) {
        System.err.println(msg);
        return new BoardResult(false, null);
    }

    /** Checks whether a cell lies inside a rectangular board. */
    private static boolean isInside(int r, int c, int rows, int cols) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }
}

/** Simple immutable holder for a board coordinate. */
record Position(int row, int col) {}

import java.io.IOException;
import java.io.InputStream;
import java.util.HashSet;
import java.util.Set;

/**
 * Refactored version of the original solution.
 * Reads an N×N board, checks feasibility and prints a visual representation.
 */
public class Main {

    /** Symbols used on the board */
    private static final char CHESS = 'o';
    private static final char EMPTY = '.';
    private static final char OBSTACLE = 'x';
    private static final char VALID = 'v';

    /** Size of the input board (N) */
    private int size;
    /** The board itself */
    private char[][] board;

    /** Entry point */
    public static void main(String[] args) throws IOException {
        new Main().run();
    }

    /** Runs the whole program – reads, processes and prints the result. */
    private void run() throws IOException {
        readBoard(System.in);
        if (!solve()) {
            // "NO" is already printed inside solve()
            return;
        }
        printResult();
    }

    /** Reads N and the board from the given input stream. */
    private void readBoard(InputStream source) {
        try (Scanner scanner = new Scanner(source)) {
            size = scanner.nextInt();
            scanner.nextLine();               // consume end‑of‑line
            board = new char[size][size];
            for (int r = 0; r < size; r++) {
                String line = scanner.nextLine();
                for (int c = 0; c < size; c++) {
                    board[r][c] = line.charAt(c);
                }
            }
        }
    }

    /**
     * Core solver – returns {@code true} if a solution exists, otherwise prints {@code "NO"}.
     */
    private boolean solve() {
        // ------------------------------------------------------------------------
        // 1️⃣  Gather positions of pieces
        // ------------------------------------------------------------------------
        Set<Position> chessPositions = locatePieces(CHESS);
        Set<Position> emptyPositions = locatePieces(EMPTY);

        // ------------------------------------------------------------------------
        // 2️⃣  Compute forbidden vectors (from a chess piece to an empty cell)
        // ------------------------------------------------------------------------
        Set<Position> forbiddenVectors = computeForbiddenVectors(chessPositions, emptyPositions);

        // ------------------------------------------------------------------------
        // 3️⃣  Try to place a virtual piece on every reachable empty cell
        // ------------------------------------------------------------------------
        for (Position src : chessPositions) {
            for (int i = -size + 1; i < size; i++) {
                for (int j = -size + 1; j < size; j++) {
                    Position offset = Position.of(i, j);
                    if (forbiddenVectors.contains(offset)) {
                        continue;                     // this move is not allowed
                    }
                    Position target = src.add(offset);
                    if (!target.isInside(size) || board[target.x][target.y] != EMPTY) {
                        System.out.println("NO");
                        return false;
                    }
                    board[target.x][target.y] = VALID; // mark reachable cell
                }
            }
        }

        // ------------------------------------------------------------------------
        // 4️⃣  No stray obstacle cells ('x') are permitted
        // ------------------------------------------------------------------------
        for (char[] row : board) {
            for (char cell : row) {
                if (cell == OBSTACLE) {
                    System.out.println("NO");
                    return false;
                }
            }
        }

        // ------------------------------------------------------------------------
        // 5️⃣  Build the (2N‑1)×(2N‑1) output board
        // ------------------------------------------------------------------------
        char[][] output = createOutputBoard();

        // Fill 'x' for every non‑forbidden vector (skip the zero vector)
        for (int i = -size + 1; i < size; i++) {
            for (int j = -size + 1; j < size; j++) {
                if (i == 0 && j == 0) {
                    continue;
                }
                if (!forbiddenVectors.contains(Position.of(i, j))) {
                    output[i + size - 1][j + size - 1] = 'x';
                }
            }
        }

        // ------------------------------------------------------------------------
        // 6️⃣  Print the result
        // ------------------------------------------------------------------------
        System.out.println("YES");
        for (char[] row : output) {
            System.out.println(new String(row));
        }
        return true;
    }

    /** Returns a set containing the coordinates of every cell equal to {@code symbol}. */
    private Set<Position> locatePieces(char symbol) {
        Set<Position> result = new HashSet<>();
        for (int r = 0; r < size; r++) {
            for (int c = 0; c < size; c++) {
                if (board[r][c] == symbol) {
                    result.add(Position.of(r, c));
                }
            }
        }
        return result;
    }

    /** Computes all vectors that map a chess piece onto an empty cell. */
    private Set<Position> computeForbiddenVectors(Set<Position> sources,
                                                 Set<Position> destinations) {
        Set<Position> forbidden = new HashSet<>();
        for (Position src : sources) {
            for (Position dst : destinations) {
                forbidden.add(dst.minus(src));
            }
        }
        return forbidden;
    }

    /** Creates the output board of size (2N‑1)×(2N‑1) and places the central 'o'. */
    private char[][] createOutputBoard() {
        int outSize = 2 * size - 1;
        char[][] result = new char[outSize][outSize];
        for (int i = 0; i < outSize; i++) {
            java.util.Arrays.fill(result[i], EMPTY);
        }
        result[size - 1][size - 1] = CHESS;
        return result;
    }

    /** Immutable point used for vector arithmetic and set membership. */
    private static final class Position {
        private final int x;
        private final int y;

        private Position(int x, int y) {
            this.x = x;
            this.y = y;
        }

        /** Factory method for readability. */
        static Position of(int x, int y) {
            return new Position(x, y);
        }

        /** Vector addition. */
        Position add(Position other) {
            return new Position(this.x + other.x, this.y + other.y);
        }

        /** Vector subtraction. */
        Position minus(Position other) {
            return new Position(this.x - other.x, this.y - other.y);
        }

        /** Checks whether the position lies inside an N×N board. */
        boolean isInside(int limit) {
            return x >= 0 && x < limit && y >= 0 && y < limit;
        }

        @Override
        public boolean equals(Object o) {
            if (this == o) return true;
            if (o == null || getClass() != o.getClass()) return false;
            Position that = (Position) o;
            return x == that.x && y == that.y;
        }

        @Override
        public int hashCode() {
            // Same hash as the original implementation (31*x + y)
            return 31 * x + y;
        }
    }
}

import java.util.Scanner;

/**
 * Solution – refactored for readability, clear naming and modular structure.
 *
 * The algorithm is identical to the original program:
 *  1. Read an {@code n×n} board containing characters ‘o’, ‘x’ and ‘.’.
 *  2. Build a matrix of allowed relative offsets between every ‘o’ and every ‘.’.
 *  3. Using those allowed offsets, erase any ‘x’ that can be reached.
 *  4. If no ‘x’ remains, output “YES” together with the pattern of allowed offsets,
 *     marking the centre cell with an ‘o’; otherwise output “NO”.
 */
public class Solution {

    /** Size of the input board. */
    private static final int MAX_N = 50; // safe upper bound for typical contest tasks

    /** Original board read from input. */
    private static char[][] board;

    /** Allowed offsets matrix (size 2·n‑1 × 2·n‑1). */
    private static boolean[][] allowedOffsets;

    /** Entry point. */
    public static void main(String[] args) {
        try (Scanner sc = new Scanner(System.in)) {
            int n = readInt(sc);
            board = readBoard(sc, n);
            allowedOffsets = initializeAllowedOffsets(n);

            markUnreachableOffsets(n);
            eraseXUsingAllowedOffsets(n);
            if (isAllXRemoved()) {
                printYesAndPattern(n);
            } else {
                System.out.println("NO");
            }
        }
    }

    /** Reads the integer {@code n}. */
    private static int readInt(Scanner sc) {
        return Integer.parseInt(sc.next());
    }

    /** Reads the {@code n} strings that form the board. */
    private static char[][] readBoard(Scanner sc, int n) {
        char[][] result = new char[n][n];
        for (int r = 0; r < n; r++) {
            String line = sc.next();
            for (int c = 0; c < n; c++) {
                result[r][c] = line.charAt(c);
            }
        }
        return result;
    }

    /** Creates the offset matrix and fills it with {@code true}. */
    private static boolean[][] initializeAllowedOffsets(int n) {
        boolean[][] offsets = new boolean[2 * n - 1][2 * n - 1];
        for (boolean[] row : offsets) {
            java.util.Arrays.fill(row, true);
        }
        return offsets;
    }

    /** Marks offsets that become unreachable when an ‘o’ points to a ‘.’. */
    private static void markUnreachableOffsets(int n) {
        for (int r = 0; r < n; r++) {
            for (int c = 0; c < n; c++) {
                if (board[r][c] == 'o') {
                    for (int nr = 0; nr < n; nr++) {
                        for (int nc = 0; nc < n; nc++) {
                            if (board[nr][nc] == '.') {
                                int offsetRow = nr - r + n - 1;
                                int offsetCol = nc - c + n - 1;
                                allowedOffsets[offsetRow][offsetCol] = false;
                            }
                        }
                    }
                }
            }
        }
    }

    /** Erases ‘x’ cells that can be reached via an allowed offset from an ‘o’. */
    private static void eraseXUsingAllowedOffsets(int n) {
        // offsets range from -(n‑1) .. (n‑1)
        for (int dr = -(n - 1); dr < n; dr++) {
            for (int dc = -(n - 1); dc < n; dc++) {
                int offR = dr + n - 1;
                int offC = dc + n - 1;
                if (!allowedOffsets[offR][offC]) {
                    continue; // offset not allowed
                }
                // try to apply this offset from every ‘o’
                for (int r = 0; r < n; r++) {
                    for (int c = 0; c < n; c++) {
                        if (board[r][c] != 'o') {
                            continue;
                        }
                        int tr = r + dr;
                        int tc = c + dc;
                        if (insideBoard(tr, tc, n) && board[tr][tc] == 'x') {
                            board[tr][tc] = '.'; // erase the reachable ‘x’
                        }
                    }
                }
            }
        }
    }

    /** Returns true if the board still contains at least one ‘x’. */
    private static boolean hasRemainingX(int n) {
        for (int r = 0; r < n; r++) {
            for (int c = 0; c < n; c++) {
                if (board[r][c] == 'x') {
                    return true;
                }
            }
        }
        return false;
    }

    /** Helper – checks whether a cell lies inside the board. */
    private static boolean insideBoard(int r, int c, int size) {
        return r >= 0 && r < size && c >= 0 && c < size;
    }

    /** Outputs “YES” and the pattern of allowed offsets. */
    private static void printYesAndPattern(int n) {
        System.out.println("YES");
        printOffsetPattern(n);
    }

    /** Prints the 2·n‑1 × 2·n‑1 pattern, replacing the centre with ‘o’. */
    private static void printOffsetPattern(int n) {
        for (int i = 0; i < 2 * n - 1; i++) {
            for (int j = 0; j < 2 * n - 1; j++) {
                if (i == n - 1 && j == n - 1) {
                    System.out.print('o');
                } else {
                    System.out.print(allowedOffsets[i][j] ? 'x' : '.');
                }
            }
            System.out.println();
        }
    }
}

/*
 * Refactored solution for problem “D”.
 * The program reads an n×n board containing only ‘o’ and ‘.’,
 * performs a series of checks and transformations and finally prints
 * either “YES” followed by a derived board or “NO”.
 *
 * The implementation has been restructured for maintainability:
 * – meaningful names and constants,
 * – small helper methods,
 * – try‑with‑resources for I/O,
 * – clear separation of the different logical stages.
 */

import java.io.*;
import java.util.*;

public class D {

    /* ----- constants ---------------------------------------------------- */
    private static final char EMPTY = '.';
    private static final char PLACED = 'o';
    private static final char MARKED = 'x';

    /* ----- entry point -------------------------------------------------- */
    public static void main(String[] args) throws IOException {
        // Using try‑with‑resources guarantees proper closure of the streams.
        try (BufferedReader reader = new BufferedReader(
                new InputStreamReader(System.in));
             PrintWriter writer = new PrintWriter(System.out)) {

            solve(reader, writer);
        }
    }

    /* ----- main solving routine ------------------------------------------ */
    private static void solve(BufferedReader reader, PrintWriter writer) throws IOException {
        int size = readInt(reader);
        char[][] original = readBoard(reader, size);
        char[][] placeholder = createEmptyPlaceholder(size);

        // Step 1 – place all original 'o' markers into the placeholder board.
        placeOriginals(original, placeholder);

        // Step 2 – build the result board (r) based on the offset rules.
        char[][] result = buildResultBoard(original, size);

        // Step 3 – propagate 'x' marks from result back into placeholder.
        propagateMarks(original, placeholder, result, size);

        // Step 4 – compare placeholder with the original board.
        boolean boardsAreEqual = boardsAreEqual(original, placeholder);

        // Step 5 – output the answer.
        if (boardsAreEqual) {
            writer.println("YES");
            for (char[] row : result) {
                writer.println(new String(row));
            }
        } else {
            writer.println("NO");
        }
    }

    /* ----- input helpers ------------------------------------------------- */
    private static int readInt(BufferedReader reader) throws IOException {
        String line = reader.readLine();
        return Integer.parseInt(line.trim());
    }

    private static char[][] readBoard(BufferedReader reader, int n) throws IOException {
        char[][] board = new char[n][];
        for (int i = 0; i < n; i++) {
            board[i] = reader.readLine().toCharArray();
        }
        return board;
    }

    /* ----- board creation ------------------------------------------------ */
    private static char[][] createEmptyPlaceholder(int n) {
        char[][] placeholder = new char[n][];
        for (int i = 0; i < n; i++) {
            placeholder[i] = new char[n];
            Arrays.fill(placeholder[i], EMPTY);
        }
        return placeholder;
    }

    private static void placeOriginals(char[][] source, char[][] target) {
        for (int y = 0; y < source.length; y++) {
            for (int x = 0; x < source[y].length; x++) {
                if (source[y][x] == PLACED) {
                    target[y][x] = PLACED;
                }
            }
        }
    }

    /* ----- result board construction -------------------------------------- */
    private static char[][] buildResultBoard(char[][] original, int n) {
        char[][] result = new char[2 * n - 1][2 * n - 1];
        fillWithEmpty(result);

        // The central cell always stays empty ('.') until we possibly mark it.
        // In the original code it was set to 'o', which we keep for consistency.
        result[n - 1][n - 1] = PLACED;

        // All possible offsets (dx, dy) excluding (0,0).
        List<Offset> offsets = generateOffsets(n);

        // First pass – mark cells where an offset would keep every ‘o’ safe.
        for (Offset off : offsets) {
            if (isOffsetValid(original, n, off.dx, off.dy)) {
                int dstY = n - 1 + off.dy;
                int dstX = n - 1 + off.dx;
                result[dstY][dstX] = MARKED;
            }
        }

        return result;
    }

    private static void fillWithEmpty(char[][] board) {
        for (char[] row : board) {
            Arrays.fill(row, EMPTY);
        }
    }

    private static List<Offset> generateOffsets(int n) {
        List<Offset> list = new ArrayList<>();
        for (int dx = -n + 1; dx <= n - 1; dx++) {
            for (int dy = -n + 1; dy <= n - 1; dy++) {
                if (dx == 0 && dy == 0) {
                    continue;
                }
                list.add(new Offset(dx, dy));
            }
        }
        return list;
    }

    /** Holds a pair of integer offsets. */
    private static final class Offset {
        final int dx;
        final int dy;

        Offset(int dx, int dy) {
            this.dx = dx;
            this.dy = dy;
        }
    }

    /** Determines whether a given offset can be applied safely to every ‘o’ cell. */
    private static boolean isOffsetValid(char[][] board, int n, int dx, int dy) {
        for (int y = 0; y < n; y++) {
            for (int x = 0; x < n; x++) {
                if (board[y][x] != PLACED) {
                    continue;
                }
                int nx = x + dx;
                int ny = y + dy;
                // If the neighbour steps outside the original board, the condition is satisfied.
                if (isOutOfBounds(nx, ny, n)) {
                    continue;
                }
                char neighbour = board[ny][nx];
                // The neighbour must be either 'o' or 'x' to keep the offset valid.
                if (neighbour != PLACED && neighbour != MARKED) {
                    return false;
                }
            }
        }
        return true;
    }

    private static boolean isOutOfBounds(int x, int y, int size) {
        return x < 0 || x >= size || y < 0 || y >= size;
    }

    /* ----- propagation of 'x' marks -------------------------------------- */
    private static void propagateMarks(char[][] original, char[][] placeholder,
                                       char[][] result, int n) {
        for (int dy = -n + 1; dy <= n - 1; dy++) {
            for (int dx = -n + 1; dx <= n - 1; dx++) {
                if (result[n - 1 + dy][n - 1 + dx] != MARKED) {
                    continue;
                }
                // For each placed cell in the original board, try to place an 'x' in placeholder.
                for (int y = 0; y < n; y++) {
                    for (int x = 0; x < n; x++) {
                        if (original[y][x] != PLACED) {
                            continue;
                        }
                        if (isOutOfBounds(x + dx, y + dy, n)) {
                            // Already handled – nothing to do.
                            continue;
                        }
                        if (original[y + dy][x + dx] != PLACED) {
                            placeholder[y + dy][x + dx] = MARKED;
                        }
                    }
                }
            }
        }
    }

    /* ----- board comparison --------------------------------------------- */
    private static boolean boardsAreEqual(char[][] a, char[][] b) {
        for (int i = 0; i < a.length; i++) {
            if (!Arrays.equals(a[i], b[i])) {
                return false;
            }
        }
        return true;
    }
}

import java.io.*;
import java.util.*;

public class D {

    /** Symbol constants used throughout the program */
    private static final char OBSTACLE = 'x';
    private static final char EMPTY = '.';
    private static final char START = 'o';

    /** Simple container for row/column coordinates */
    private static final class Position {
        final int row;
        final int col;

        Position(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }

    /** Reads the whole input and builds the board */
    private static char[][] readBoard(BufferedReader br, int size) throws IOException {
        char[][] board = new char[size][];
        for (int r = 0; r < size; r++) {
            board[r] = br.readLine().trim().toCharArray();
        }
        return board;
    }

    /** Collects all cells that contain the start symbol ('o') */
    private static List<Position> collectStarts(char[][] board) {
        List<Position> starts = new ArrayList<>();
        for (int r = 0; r < board.length; r++) {
            for (int c = 0; c < board[r].length; c++) {
                if (board[r][c] == START) {
                    starts.add(new Position(r, c));
                }
            }
        }
        return starts;
    }

    /** Checks whether a translation (dx, dy) is legal for every start cell */
    private static boolean isOffsetLegal(int dx, int dy,
                                         List<Position> starts,
                                         char[][] board) {
        for (Position p : starts) {
            int nr = p.row + dx;
            int nc = p.col + dy;
            if (nr < 0 || nr >= board.length || nc < 0 || nc >= board[nr].length) {
                return false;
            }
            if (board[nr][nc] == EMPTY) {
                return false;
            }
        }
        return true;
    }

    /** Core solving routine */
    public static void solve(char[][] board, int n) {
        /* -----------------------------------------------------------
         * 1️⃣  Gather all 'o' positions (the "starts")
         * ----------------------------------------------------------- */
        List<Position> starts = collectStarts(board);

        /* -----------------------------------------------------------
         * 2️⃣  Track which board cells become covered by applying one
         *     of the legal translation vectors.
         * ----------------------------------------------------------- */
        boolean[][] covered = new boolean[n][n];
        Arrays.fill(covered[0], false);                 // initialise all to false
        for (Position p : starts) {
            covered[p.row][p.col] = true;                // starts are trivially covered
        }

        /* -----------------------------------------------------------
         * 3️⃣  Enumerate every possible translation vector (dx, dy)
         *     and keep those that are legal for *all* starts.
         * ----------------------------------------------------------- */
        List<Position> legalOffsets = new ArrayList<>();

        for (int dx = -(n - 1); dx <= n - 1; dx++) {
            for (int dy = -(n - 1); dy <= n - 1; dy++) {
                if (dx == 0 && dy == 0) { continue; }    // skip the zero vector
                if (!isOffsetLegal(dx, dy, starts, board)) { continue; }

                // This offset works for every start → remember it
                legalOffsets.add(new Position(dx, dy));

                // Mark all cells reachable by applying this offset
                for (Position p : starts) {
                    int r = p.row + dx;
                    int c = p.col + dy;
                    if (r >= 0 && r < n && c >= 0 && c < n) {
                        covered[r][c] = true;
                    }
                }
            }
        }

        /* -----------------------------------------------------------
         * 4️⃣  If no legal offset was found → immediate "NO" answer
         * ----------------------------------------------------------- */
        if (legalOffsets.isEmpty()) {
            System.out.println("NO");
            return;
        }

        /* -----------------------------------------------------------
         * 5️⃣  Verify that *every* board cell becomes covered.
         *     If any cell stays uncovered → "NO".
         * ----------------------------------------------------------- */
        boolean allCovered = true;
        for (boolean[] row : covered) {
            for (boolean cell : row) {
                if (!cell) {
                    allCovered = false;
                    break;
                }
            }
            if (!allCovered) { break; }
        }
        if (!allCovered) {
            System.out.println("NO");
            return;
        }

        /* -----------------------------------------------------------
         * 6️⃣  Build the output board of size (2·n‑1) × (2·n‑1).
         *     The centre cell stays the original 'o'.
         *     Every discovered offset becomes an 'x' at its relative
         *     position around the centre.
         * ----------------------------------------------------------- */
        char[][] out = new char[2 * n - 1][2 * n - 1];
        for (int i = 0; i < out.length; i++) {
            Arrays.fill(out[i], EMPTY);
        }
        out[n - 1][n - 1] = START;                       // centre cell

        for (Position off : legalOffsets) {
            int outRow = n - 1 + off.row;
            int outCol = n - 1 + off.col;
            out[outRow][outCol] = OBSTACLE;
        }

        /* -----------------------------------------------------------
         * 7️⃣  Print the final result.
         * ----------------------------------------------------------- */
        System.out.println("YES");
        StringBuilder sb = new StringBuilder();
        for (char[] row : out) {
            sb.append(row);
            sb.append('\n');
        }
        System.out.print(sb.toString());
    }

    /** Entry point */
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        int size = Integer.parseInt(br.readLine().trim());

        char[][] board = readBoard(br, size);

        // Trivial 1×1 case – nothing to analyse
        if (size == 1) {
            System.out.println("YES");
            System.out.println("o");
            return;
        }

        solve(board, size);
    }
}

/*
 * Refactored solution for Codeforces problem “CF”.
 *
 * The program reads an n×n board that contains three symbols:
 *   'o' – a piece,
 *   'x' – a cell that must be attacked,
 *   '.' – a safe cell.
 *
 * It tries to decide whether a placement of pieces can satisfy the
 * constraints and, if so, prints a (2n‑1)×(2n‑1) board that visualises the
 * solution.
 *
 * The implementation is deliberately written in a clean, modular style
 * to improve maintainability.
 */
import java.io.*;
import java.util.*;

public class Main {

    /** Size of the virtual board used for relative positioning. */
    private static final int VIRTUAL_BOARD_OFFSET = -1; // will become + (n‑1) later

    /** Fast scanner that works for both file and console input. */
    private static class InputReader {
        private final BufferedReader br;
        private StringTokenizer st;

        InputReader(InputStream stream) {
            br = new BufferedReader(new InputStreamReader(stream));
        }

        /** Reads the next token, retrying until one is available. */
        private String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) {
                        return null;
                    }
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new UncheckedIOException(e);
                }
            }
            return st.nextToken();
        }

        int nextInt()               { return Integer.parseInt(next()); }
        long nextLong()             { return Long.parseLong(next()); }
        double nextDouble()         { return Double.parseDouble(next()); }
        boolean hasMoreTokens()     { return st != null && st.hasMoreTokens(); }
    }

    /** Holds all input data and intermediate results. */
    private static final class Solver {
        private final int n;
        private final char[][] grid;               // original n×n board
        private final boolean[][] forbidden;        // (2n‑1)×(2n‑1) virtual board
        private final boolean[][] attacked;         // (n)×(n) attacked cells
        private final List<Pos> pieces;              // positions of 'o'
        private final List<Pos> empties;             // positions of '.'

        Solver(int n, char[][] grid) {
            this.n = n;
            this.grid = grid;
            this.forbidden = new boolean[2 * n - 1][2 * n - 1];
            this.attacked = new boolean[n][n];
            this.pieces = new ArrayList<>();
            this.empties = new ArrayList<>();
        }

        /** Finds all 'o' and '.' positions. */
        void collectPiecesAndEmpties() {
            for (int r = 0; r < n; r++) {
                for (int c = 0; c < n; c++) {
                    char ch = grid[r][c];
                    if (ch == 'o') {
                        pieces.add(new Pos(r, c));
                    } else if (ch == '.') {
                        empties.add(new Pos(r, c));
                    }
                }
            }
        }

        /** Marks all forbidden relative offsets of empty cells w.r.t. each piece. */
        void markForbiddenOffsets() {
            int offsetBase = n - 1; // centre of the virtual board
            for (Pos piece : pieces) {
                for (Pos empty : empties) {
                    int dr = empty.row - piece.row + offsetBase;
                    int dc = empty.col - piece.col + offsetBase;
                    forbidden[dr][dc] = true;
                }
            }
        }

        /** Marks cells that are attacked by at least one piece. */
        void markAttackedCells() {
            int offsetBase = n - 1;
            for (Pos piece : pieces) {
                for (int r = 0; r < n; r++) {
                    for (int c = 0; c < n; c++) {
                        if (grid[r][c] == 'o') {
                            continue; // we already know this is a piece
                        }
                        int dr = r - piece.row + offsetBase;
                        int dc = c - piece.col + offsetBase;
                        if (!forbidden[dr][dc]) {
                            attacked[r][c] = true;
                        }
                    }
                }
            }
        }

        /** Returns true if every 'x' cell is attacked; otherwise false. */
        boolean validateAllXAreAttacked() {
            for (int r = 0; r < n; r++) {
                for (int c = 0; c < n; c++) {
                    if (grid[r][c] == 'x' && !attacked[r][c]) {
                        return false;
                    }
                }
            }
            return true;
        }

        /** Prints the solution board (2n‑1)×(2n‑1). */
        void printSolutionBoard() {
            int size = 2 * n - 1;
            for (int r = 0; r < size; r++) {
                for (int c = 0; c < size; c++) {
                    if (r == n - 1 && c == n - 1) {
                        System.out.print('o');
                    } else {
                        System.out.print(forbidden[r][c] ? '.' : 'x');
                    }
                }
                System.out.println();
            }
        }
    }

    /** Simple container for a board coordinate. */
    private static final class Pos {
        final int row, col;
        Pos(int row, int col) { this.row = row; this.col = col; }
    }

    /** Entry point – works for both console and file I/O. */
    public static void main(String[] args) throws IOException {
        // Try to open a file named "test.in". If it does not exist, fall back to stdin.
        Solver solver;
        try (InputStream inStream = new FileInputStream("test.in")) {
            solver = new Solver(readBoardSize(inStream), readBoard(inStream));
        } catch (FileNotFoundException ignored) {
            solver = new Solver(readBoardSize(System.in), readBoard(System.in));
        }

        // Core processing
        solver.collectPiecesAndEmpties();
        solver.markForbiddenOffsets();
        solver.markAttackedCells();

        if (!solver.validateAllXAreAttacked()) {
            System.out.println("NO");
            return;
        }

        System.out.println("YES");
        solver.printSolutionBoard();
    }

    /** Reads the integer n from the given reader. */
    private static int readBoardSize(Reader reader) throws IOException {
        return new InputReader(reader).nextInt();
    }

    /** Reads the n×n board from the given reader. */
    private static char[][] readBoard(Reader reader) throws IOException {
        InputReader in = new InputReader(reader);
        int n = in.nextInt();
        char[][] board = new char[n][];
        for (int i = 0; i < n; i++) {
            board[i] = in.next().toCharArray();
        }
        return board;
    }
}

import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;
import java.util.Arrays;

/**
 * Refactored version of the original {@code TaskD} program.
 * The logic is unchanged – it reads an {@code n × n} board,
 * marks reachable cells, tries to eliminate every {@code 'x'} and
 * prints either {@code YES} together with the resulting grid or {@code NO}.
 *
 * The code is split into small, well‑named methods, uses meaningful
 * identifiers and avoids the many nested loops that made the original
 * version hard to follow.
 */
public class TaskD {

    /** Characters used throughout the algorithm. */
    private static final char EMPTY = 'x';   // original empty cell
    private static final char MARK  = 'o';   // special marker cell
    private static final char POSS  = '.';   // reachable cell marker

    /** Entry point. */
    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            solve(scanner);
        }
    }

    /** Orchestrates the whole workflow. */
    private static void solve(Scanner scanner) {
        int n = readBoardSize(scanner);
        List<String> board = readBoardLines(scanner, n);

        int canvasSize = 2 * n - 1;
        char[][] canvas = createEmptyCanvas(canvasSize);
        markPossibilities(canvas, board);

        char[][] workCopy = copyBoard(board);
        fillReachableCells(workCopy, board, canvas);

        if (allCellsMarked(workCopy)) {
            System.out.println("YES");
            printCanvas(canvas);
        } else {
            System.out.println("NO");
        }
    }

    /** Reads the integer {@code n}. */
    private static int readBoardSize(Scanner scanner) {
        return Integer.parseInt(scanner.nextLine().trim());
    }

    /** Reads the next {@code n} lines that form the board. */
    private static List<String> readBoardLines(Scanner scanner, int n) {
        List<String> lines = new ArrayList<>(n);
        for (int i = 0; i < n; i++) {
            lines.add(scanner.nextLine());
        }
        return lines;
    }

    /** Creates an empty canvas filled with {@code EMPTY} and marks its centre with {@code MARK}. */
    private static char[][] createEmptyCanvas(int size) {
        char[][] canvas = new char[size][size];
        for (char[] row : canvas) {
            Arrays.fill(row, EMPTY);
        }
        int centre = size / 2;
        canvas[centre][centre] = MARK;
        return canvas;
    }

    /** Marks every cell that can be reached from a {@code MARK} via a {@code POSS} cell. */
    private static void markPossibilities(char[][] canvas, List<String> board) {
        int n = board.size();
        int offset = n - 1; // centre index of the canvas

        for (int i = 0; i < n; i++) {
            String row = board.get(i);
            for (int j = 0; j < n; j++) {
                if (row.charAt(j) == MARK) {
                    // For every POSS cell, mark the corresponding offset position.
                    for (int k = 0; k < n; k++) {
                        String otherRow = board.get(k);
                        for (int l = 0; l < n; l++) {
                            if (otherRow.charAt(l) == POSS) {
                                int targetRow = offset + k - i;
                                int targetCol = offset + l - j;
                                canvas[targetRow][targetCol] = POSS;
                            }
                        }
                    }
                }
            }
        }
    }

    /** Copies the original board into a mutable 2‑dimensional char array. */
    private static char[][] copyBoard(List<String> board) {
        int n = board.size();
        char[][] copy = new char[n][n];
        for (int i = 0; i < n; i++) {
            copy[i] = board.get(i).toCharArray();
        }
        return copy;
    }

    /** Fills every {@code 'x'} reachable from a {@code MARK} with {@code POSS}. */
    private static void fillReachableCells(char[][] board, List<String> original, char[][] canvas) {
        int n = original.size();

        for (int i = 0; i < n; i++) {
            String row = original.get(i);
            for (int j = 0; j < n; j++) {
                if (row.charAt(j) == MARK) {
                    for (int k = 0; k < n; k++) {
                        String otherRow = original.get(k);
                        for (int l = 0; l < n; l++) {
                            if (otherRow.charAt(l) == EMPTY && canvas[n - 1 + k - i][n - 1 + l - j] == POSS) {
                                board[k][l] = POSS;
                            }
                        }
                    }
                }
            }
        }
    }

    /** Returns {@code true} if the supplied board contains no {@code EMPTY} cells. */
    private static boolean allCellsMarked(char[][] board) {
        for (char[] row : board) {
            for (char cell : row) {
                if (cell == EMPTY) {
                    return false;
                }
            }
        }
        return true;
    }

    /** Prints the whole canvas without any separators between characters. */
    private static void printCanvas(char[][] canvas) {
        for (char[] row : canvas) {
            for (char cell : row) {
                System.out.print(cell);
            }
            System.out.println();
        }
    }
}

import java.io.*;
import java.util.StringTokenizer;

/**
 * Solves the problem described in the original code.
 *
 * <p>Key improvements over the original version:
 *
 * <ul>
 *   <li>Descriptive identifiers and class name {@code Solver}.</li>
 *   <li>Separation of concerns into small, single‑purpose methods.</li>
 *   <li>Constant handling for the board size matrix.</li>
 *   <li>Clear comments that explain the reasoning behind each step.</li>
 *   <li>No duplicated loops – each iteration has a purpose.</li>
 * </ul>
 */
public class Solver {

    /* --------------------------------------------------------------------- */
    /*  I/O helpers                                                          */
    /* --------------------------------------------------------------------- */

    private BufferedReader reader;
    private PrintWriter writer;

    /** Entry point required by the original submission. */
    public static void main(String[] args) throws IOException {
        new Solver().run();
    }

    /** Creates the underlying streams used throughout the solution. */
    private void initialiseIo() {
        reader = new BufferedReader(new InputStreamReader(System.in));
        writer = new PrintWriter(System.out);
    }

    /** Reads the next token from the input stream (mirrors the original stub). */
    private String nextToken() throws IOException {
        while (st == null || !st.hasMoreTokens()) {
            String line = reader.readLine();
            if (line == null) {
                return null;
            }
            st = new StringTokenizer(line);
        }
        return st.nextToken();
    }

    /** Shortcut for reading an {@code int} from the tokenizer. */
    private int nextInt() throws IOException {
        return Integer.parseInt(nextToken());
    }

    /* --------------------------------------------------------------------- */
    /*  Core algorithm                                                       */
    /* --------------------------------------------------------------------- */

    /** Reads the board size and the {@code n × n} character grid. */
    private char[][] readBoard(int n) throws IOException {
        char[][] board = new char[n][n];
        for (int row = 0; row < n; ++row) {
            board[row] = next().toCharArray();
        }
        return board;
    }

    /**
     * Determines which movement offsets cannot be used.
     *
     * <p>The algorithm mirrors the original implementation:
     *
     * <ul>
     *   <li>If an {@code 'o'} can move to an adjacent {@code '.'}, the resulting
     *       offset is marked as prohibited.</li>
     *   <li>Later we test for each {@code 'x'} whether there exists an
     *       {@code 'o'} whose reverse offset is *not* prohibited.</li>
     * </ul>
     *
     * @param size the board dimension {@code n}
     * @param board the parsed character grid
     * @return a boolean matrix of size {@code 2·size‑1} where {@code true}
     *         denotes a prohibited offset.
     */
    private boolean[][] computeProhibitedOffsets(int size, char[][] board) {
        boolean[][] prohibited = new boolean[2 * size - 1][2 * size - 1];

        // 1️⃣  Mark offsets that would move an 'o' onto a '.' as prohibited.
        for (int srcX = 0; srcX < size; ++srcX) {
            for (int srcY = 0; srcY < size; ++srcY) {
                if (board[srcX][srcY] != 'o') continue;

                for (int dstX = 0; dstX < size; ++dstX) {
                    for (int dstY = 0; dstY < size; ++dstY) {
                        if (board[dstX][dstY] != '.') continue;

                        int dx = dstX - srcX;                     // raw offset
                        int dy = dstY - srcY;
                        prohibited[size - 1 + dx][size - 1 + dy] = true;
                    }
                }
            }
        }
        return prohibited;
    }

    /**
     * Checks whether every {@code 'x'} can reach at least one {@code 'o'}
     * using a non‑prohibited offset.
     *
     * @return {@code true} if all {@code 'x'} cells satisfy the condition,
     *         {@code false} otherwise (in which case {@code "NO"} has already
     *         been written to the output stream).
     */
    private boolean allXCellsAreCovered(int size,
                                         char[][] board,
                                         boolean[][] prohibited) {
        for (int x = 0; x < size; ++x) {
            for (int y = 0; y < size; ++y) {
                if (board[x][y] != 'x') continue;

                boolean canReachSomeO = false;
                for (int ox = 0; ox < size; ++ox) {
                    for (int oy = 0; oy < size; ++oy) {
                        if (board[ox][oy] != 'o') continue;

                        int offsetX = x - ox;
                        int offsetY = y - oy;
                        if (!prohibited[size - 1 + offsetX][size - 1 + offsetY]) {
                            canReachSomeO = true;
                            break;
                        }
                    }
                    if (canReachSomeO) break;
                }

                if (!canReachSomeO) {
                    writer.println("NO");
                    return false;               // early exit – solution impossible
                }
            }
        }
        return true;
    }

    /** Prints the resulting board according to the specification. */
    private void outputResultBoard(int size, boolean[][] prohibited) {
        int boardDim = 2 * size - 1;
        for (int i = 0; i < boardDim; ++i) {
            for (int j = 0; j < boardDim; ++j) {
                if (i == size - 1 && j == size - 1) {
                    writer.print('o');                     // central marker
                } else if (prohibited[i][j]) {
                    writer.print('.');                     // prohibited offset
                } else {
                    writer.print('x');                     // allowed offset
                }
            }
            writer.println();
        }
    }

    /** Orchestrates the whole solution – mimics the original {@code solve()} method. */
    private void solve() throws IOException {
        initialiseIo();

        int n = nextInt();                     // board dimension
        char[][] board = readBoard(n);         // read n × n grid

        // Step 1 – compute the prohibited movement offsets
        boolean[][] prohibited = computeProhibitedOffsets(n, board);

        // Step 2 – verify the feasibility condition for every 'x'
        if (!allXCellsAreCovered(n, board, prohibited)) {
            // If we reach here the answer is already printed as "NO"
            closeAndExit();
            return;
        }

        // Step 3 – everything is feasible → emit the required output
        writer.println("YES");
        outputResultBoard(n, prohibited);
        closeAndExit();
    }

    /** Helper that closes streams and terminates the program. */
    private void closeAndExit() {
        writer.flush();
        writer.close();
        try {
            reader.close();
        } catch (IOException ignored) {
        }
    }

    /* --------------------------------------------------------------------- */
    /*  Tokenizer fields (identical to the original starter code)            */
    /* --------------------------------------------------------------------- */
    private StringTokenizer st;   // used by next()/nextToken()
}

import java.io.*;
import java.util.StringTokenizer;

/**
 * Solution for the “Field Expansion” problem.
 *
 * <p>
 * The original implementation worked but was hard to read because of:
 * <ul>
 *   <li>many nested loops with unclear intent,
 *   <li>static imports of primitive parsers,
 *   <li>cryptic variable names,
 *   <li>no separation of concerns,
 *   <li>no documentation/comments.
 * </ul>
 * The refactor keeps the exact same algorithm while improving readability,
 * maintainability and testability.
 * </p>
 */
public class Main {

    /* --------------------------------------------------------------------- */
    /*  Input / output helpers                                               */
    /* --------------------------------------------------------------------- */

    private static final class FastScanner {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        FastScanner(BufferedReader reader) {
            this.reader = reader;
        }

        /** Returns the next token, reading a new line if necessary. */
        private String nextToken() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                tokenizer = new StringTokenizer(reader.readLine());
            }
            return tokenizer.nextToken();
        }

        /** Reads an int from the next token. */
        int nextInt() throws IOException {
            return Integer.parseInt(nextToken());
        }

        /** Reads a long from the next token. */
        long nextLong() throws IOException {
            return Long.parseLong(nextToken());
        }

        /** Reads a double from the next token. */
        double nextDouble() throws IOException {
            return Double.parseDouble(nextToken());
        }
    }

    /* --------------------------------------------------------------------- */
    /*  Core algorithm                                                       */
    /* --------------------------------------------------------------------- */

    /** Reads the whole test case. */
    private static class Input {
        final int n;               // size of the n×n board
        final char[][] board;      // current board configuration

        Input(FastScanner fs) throws IOException {
            this.n = fs.nextInt();
            board = new char[n][n];
            for (int i = 0; i < n; i++) {
                String line = fs.next();
                line.getChars(0, n, board[i], 0);
            }
        }
    }

    /** Holds the expanded attack matrix (size = 2n‑1). */
    private static class AttackMatrix {
        final boolean[][] matrix;   // true == cell is *possible* to be attacked

        AttackMatrix(int size) {
            matrix = new boolean[size][size];
            fillAll();
        }

        private void fillAll() {
            for (boolean[] row : matrix) {
                java.util.Arrays.fill(row, true);
            }
        }

        /** Marks every cell that cannot be reached by any placed 'o'. */
        void excludeReachableBy(char[][] board, int n) {
            for (int r = 0; r < n; r++) {
                for (int c = 0; c < n; c++) {
                    if (board[r][c] != 'o') {
                        continue;
                    }
                    // From each 'o' we invalidate cells that contain something other than '.'
                    for (int nr = 0; nr < n; nr++) {
                        for (int nc = 0; nc < n; nc++) {
                            if (board[nr][nc] != '.') {
                                continue;
                            }
                            int dr = nr - r + n - 1;
                            int dc = nc - c + n - 1;
                            matrix[dr][dc] = false;
                        }
                    }
                }
            }
        }

        /** Returns true if every 'x' on the original board *can* be reached. */
        boolean validatesOriginalBoard(char[][] board) {
            for (int r = 0; r < board.length; r++) {
                for (int c = 0; c < board[r].length; c++) {
                    if (board[r][c] == 'x' && !isReachable(r, c)) {
                        return false;
                    }
                }
            }
            return true;
        }

        /** Checks whether a given (r,c) cell is marked as reachable. */
        private boolean isReachable(int r, int c) {
            return matrix[r + n - 1][c + n - 1];
        }
    }

    /** Prints the required YES/NO answer and the expanded matrix. */
    private static void outputResult(AttackMatrix attack, int n) {
        System.out.println("YES");
        int size = 2 * n - 1;
        for (int i = 0; i < size; i++) {
            StringBuilder sb = new StringBuilder();
            for (int j = 0; j < size; j++) {
                sb.append(
                        (i == n - 1 && j == n - 1) ? 'o' :          // centre cell
                        (attack.matrix[i][j]) ? 'x' : '.'            // pattern cell
                );
            }
            System.out.println(sb);
        }
    }

    /* --------------------------------------------------------------------- */
    /*  Main entry point                                                       */
    /* --------------------------------------------------------------------- */

    public static void main(String[] args) {
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in))) {
            FastScanner fs = new FastScanner(br);
            Input input = new Input(fs);
            AttackMatrix attack = new AttackMatrix(2 * input.n - 1);

            // ---- core processing -------------------------------------------------
            attack.excludeReachableBy(input.board, input.n);
            boolean valid = attack.validatesOriginalBoard(input.board);

            // ---- output -----------------------------------------------------------
            if (!valid) {
                System.out.println("NO");
                return;
            }

            System.out.println("YES");
            // The AttackMatrix already stores the information needed for printing.
            outputResult(attack, input.n);

        } catch (Exception e) {
            // In the original submission a generic failure printed the stack trace
            // and terminated with exit code 1.  The refactored version preserves that
            // behaviour for compatibility with the original judge.
            e.printStackTrace();
            System.exit(1);
        }
    }
}

import java.util.Scanner;

/**
 * Refactored solution for CF538D.
 *
 * <p>
 * The program reads an N×N board that contains the characters {@code 'o'} and {@code '.'}.
 * It expands the board to size (2N‑1)×(2N‑1) by filling it with {@code 'x'}, placing a single
 * {@code 'o'} in the centre and then propagating {@code '.'} positions from the original
 * board into the expanded one.
 * Afterwards it verifies whether the reachable pattern generated from the expanded board
 * matches the original board. If the verification succeeds, "YES" and the expanded board
 * are printed; otherwise only "NO" is printed.
 * </p>
 */
public class CF538D {

    /** Character used to fill empty cells in the expanded board. */
    private static final char EMPTY = 'x';

    /** Character representing an obstacle ('o') in the input board. */
    private static final char OBSTACLE = 'o';

    /** Character used to mark empty positions during reachability checks. */
    private static final char EMPTY_INNER = '.';

    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            int n = readInt(scanner);
            char[][] original = readGrid(scanner, n);

            char[][] expanded = expandBoard(original);
            char[][] reachable = deriveReachable(expanded, original);

            if (matches(original, reachable)) {
                System.out.println("YES");
                printBoard(expanded);
            } else {
                System.out.println("NO");
            }
        }
    }

    /** Reads a single integer from the scanner. */
    private static int readInt(Scanner scanner) {
        String line = scanner.nextLine().trim();
        return Integer.parseInt(line);
    }

    /** Reads an N×N grid of characters from the scanner. */
    private static char[][] readGrid(Scanner scanner, int size) {
        char[][] grid = new char[size][size];
        for (int i = 0; i < size; i++) {
            String line = scanner.nextLine();
            grid[i] = line.toCharArray();
        }
        return grid;
    }

    /**
     * Creates and returns a (2N‑1)×(2N‑1) board.
     * The board is filled with {@code EMPTY} and a single {@code OBSTACLE}
     * is placed at the centre.
     */
    private static char[][] expandBoard(char[][] pattern) {
        int n = pattern.length;
        int expandedSize = 2 * n - 1;
        char[][] board = new char[expandedSize][expandedSize];
        fillWith(board, EMPTY);
        board[n - 1][n - 1] = OBSTACLE;
        propagateEmptyPositions(board, pattern);
        return board;
    }

    /** Places {@code EMPTY_INNER} in the expanded board wherever {@code EMPTY_INNER}
     * appears in the original pattern. */
    private static void propagateEmptyPositions(char[][] board, char[][] pattern) {
        int n = pattern.length;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (pattern[i][j] == EMPTY_INNER) {
                    int targetX = i + (n - 1);
                    int targetY = j + (n - 1);
                    if (isInside(board, targetX, targetY)) {
                        board[targetX][targetY] = EMPTY_INNER;
                    }
                }
            }
        }
    }

    /** Derives the reachability pattern starting from each {@code OBSTACLE} in {@code pattern}. */
    private static char[][] deriveReachable(char[][] expanded, char[][] pattern) {
        int n = pattern.length;
        char[][] reachable = new char[n][n];
        fillWith(reachable, '.');

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (pattern[i][j] != OBSTACLE) {
                    continue;
                }
                reachable[i][j] = OBSTACLE;
                propagateReachability(reachable, expanded, i, j);
            }
        }
        return reachable;
    }

    /** Marks cells reachable from (srcX, srcY) based on the expanded board. */
    private static void propagateReachability(char[][] reachable,
                                              char[][] expanded,
                                              int srcX,
                                              int srcY) {
        int size = reachable.length;
        for (int x = 0; x < size; x++) {
            for (int y = 0; y < size; y++) {
                if (reachable[x][y] != '.') {
                    continue;
                }
                int expX = x - srcX + (size - 1);
                int expY = y - srcY + (size - 1);
                if (isInside(expanded, expX, expY) && expanded[expX][expY] == EMPTY) {
                    reachable[x][y] = EMPTY;
                }
            }
        }
    }

    /** Checks whether the derived reachable pattern matches the original pattern. */
    private static boolean matches(char[][] original, char[][] reachable) {
        for (int i = 0; i < original.length; i++) {
            for (int j = 0; j < original[0].length; j++) {
                if (original[i][j] != reachable[i][j]) {
                    return false;
                }
            }
        }
        return true;
    }

    /** Utility to fill a 2‑D array with a given character. */
    private static void fillWith(char[][] array, char value) {
        for (char[] row : array) {
            java.util.Arrays.fill(row, value);
        }
    }

    /** Utility to verify that coordinates are inside a given board. */
    private static boolean isInside(char[][] board, int x, int y) {
        return x >= 0 && x < board.length && y >= 0 && y < board[0].length;
    }

    /** Prints a 2‑D character array line by line. */
    private static void printBoard(char[][] board) {
        for (char[] row : board) {
            System.out.println(new String(row));
        }
    }
}

import java.io.*;
import java.util.Objects;

/**
 *  Refactored version of the original {@code D} class.
 *
 *  The program reads an {@code n × n} board consisting of the characters
 *  'o', 'x' and '-' (represented by '0' in the {@code f} matrix).  
 *  It determines whether a valid placement on a board of size
 *  {@code 2n‑1 × 2n‑1} exists and, if so, prints the required picture.
 */
public final class D {

    /** Constant offset used to translate coordinates from a 0‑based {@code f} index
     *  to a 0‑based position in the {@code arr} matrix. */
    private static final int COORD_OFFSET = -1;

    /** Half‑size of the final board (i.e. {@code n}); kept only for readability. */
    private static final int BOARD_HALF_SIZE = -1; // placeholder – we compute it later

    private D() {
        /* utility class – nothing to instantiate */
    }

    public static void main(String[] args) throws IOException {
        /* --------------------------------------------------------------
         *  1️⃣  Input handling – try‑with‑resources guarantees proper closing.
         * -------------------------------------------------------------- */
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
             PrintWriter out = new PrintWriter(System.out)) {

            /* --------------------------------------------------------------
             *  2️⃣  Read {@code n} and the {@code n × n} matrix.
             * -------------------------------------------------------------- */
            String line = reader.readLine();
            Objects.requireNonNull(line);
            final int n = Integer.parseInt(line.trim());

            int[][] boardValues = parseBoardValues(reader, n);

            /* --------------------------------------------------------------
             *  3️⃣  Mark all cells that can be “reached” from an ‘o’ cell.
             * -------------------------------------------------------------- */
            boolean[][] reachable = markReachablePositions(n, boardValues);

            /* --------------------------------------------------------------
             *  4️⃣  Validate that every ‘x’ cell has at least one reachable source.
             * -------------------------------------------------------------- */
            if (!validateAllXHaveSource(reachability, boardValues)) {
                out.println("NO");
                return;                 // program ends here
            }

            /* --------------------------------------------------------------
             *  5️⃣  Output “YES” followed by the constructed board picture.
             * -------------------------------------------------------------- */
            out.println("YES");
            printResultBoard(reachability, n, out);
        }
    }

    /**
     * Reads the {0,1,-1} rows that describe the input matrix.
     *
     * @param reader   The reader used to fetch the remaining lines.
     * @param n        Size of the board.
     * @return a 2‑dimensional {@code int} matrix where
     *         {@code 0} = empty cell,
     *         {@code 1} = 'o' cell,
     *         {@code -1} = 'x' cell.
     */
    private static int[][] parseBoardValues(BufferedReader reader, int n) throws IOException {
        int[][] values = new int[n][n];
        for (int i = 0; i < n; i++) {
            String row = reader.readLine();
            Objects.requireNonNull(row);
            for (int j = 0; j < n; j++) {
                char ch = row.charAt(j);
                values[i][j] = switch (ch) {
                    case 'o' -> 1;
                    case 'x' -> -1;
                    default -> 0;   // character '-' or any other placeholder
                };
            }
        }
        return values;
    }

    /**
     * Determines, for each empty cell of the original {@code f} matrix,
     * whether it can be “covered” by at least one ‘o’ cell when placed on a
     * {@code (2n‑1) × (2n‑1)} board.
     *
     * The resulting {@code reachable} matrix has dimensions {@code (2n‑1) × (2n‑1)}.
     *
     * @param n          Size of the original board.
     * @param f          The parsed input matrix.
     * @return a boolean matrix indicating reachable positions.
     */
    private static boolean[][] markReachablePositions(int n, int[][] f) {
        final int boardSize = 2 * n - 1;
        boolean[][] reachable = new boolean[boardSize][boardSize];

        // For each empty cell (value 0) we need to check all possible offsets.
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (f[i][j] != 0) {
                    continue;   // irrelevant for this step
                }

                // Scan the whole board to find every ‘o’ cell.
                for (int a = 0; a < n; a++) {
                    for (int b = 0; b < n; b++) {
                        if (f[a][b] == 1) {
                            // Compute the target coordinates on the larger board.
                            int targetRow = (i - a) + (n - 1);
                            int targetCol = (j - b) + (n - 1);
                            reachable[targetRow][targetCol] = true;
                        }
                    }
                }
            }
        }
        return reachable;
    }

    /**
     * Verifies that every cell marked {@code -1} in the original board has
     * at least one reachable cell of value {@code 1}.
     *
     * @param reachable   Matrix produced by {@link #markReachablePositions}.
     * @param f           Original board values.
     * @return {@code true} if validation succeeds, otherwise {@code false}.
     */
    private static boolean validateAllXHaveSource(boolean[][] reachable, int[][] f) {
        final int n = f.length;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (f[i][j] != -1) {
                    continue; // we only care about ‘x’ cells
                }
                boolean hasReachableSource = false;
                for (int a = 0; a < n; a++) {
                    for (int b = 0; b < n; b++) {
                        if (f[a][b] == 1) {
                            int targetRow = (i - a) + (n - 1);
                            int targetCol = (j - b) + (n - 1);
                            if (targetRow < 0 || targetRow >= reachable.length ||
                                targetCol < 0 || targetCol >= reachable[0].length) {
                                continue;
                            }
                            if (reachable[targetRow][targetCol]) {
                                hasReachableSource = true;
                                break;
                            }
                        }
                    }
                    if (hasReachableSource) {
                        break;
                    }
                }
                if (!hasReachableSource) {
                    return false;   // early exit – validation fails
                }
            }
        }
        return true;
    }

    /**
     * Prints the final board picture using the {@code reachable} matrix.
     *
     * The centre cell (index {@code n‑1, n‑1}) is printed as an ‘o’.
     * All other cells are printed as ‘.’ when they are reachable,
     * otherwise as ‘x’.
     *
     * @param reachable   The matrix that holds reachability information.
     * @param n           Original board size.
     * @param out         PrintWriter used for output.
     */
    private static void printResultBoard(boolean[][] reachable, int n, PrintWriter out) {
        final int boardSize = 2 * n - 1;
        for (int i = 0; i < boardSize; i++) {
            for (int j = 0; j < boardSize; j++) {
                if (i == n - 1 && j == n - 1) {
                    out.print('o');
                } else if (reachable[i][j]) {
                    out.print('.');
                } else {
                    out.print('x');
                }
            }
            out.println();
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Refactored solution for the “D” problem.
 *
 * <p>Changes made for maintainability:
 * <ul>
 *   <li>Extracted small helper classes ({@link Pos}, {@link Move}) to give semantic meaning to
 *       coordinates and displacement vectors.</li>
 *   <li>Replaced magic numbers and ambiguous variable names with expressive ones.</li>
 *   <li>Separated I/O handling from the algorithmic steps.</li>
 *   <li>Extracted pure functions ({@code inBoard}, {@code computePossibleMoves}) that are
 *       easier to test and understand.</li>
 *   <li>Used {@code static} fields where appropriate to avoid leaking state between test cases.</li>
 *   <li>Added inline comments that explain *why* a piece of code exists, not just *what* it does.</li>
 * </ul>
 */
public class D {

    /* ------------------------------------------------------------------------- */
    /*  I/O infrastructure                                                       */
    /* ------------------------------------------------------------------------- */
    private static BufferedReader reader;
    private static StringTokenizer tokenizer;
    private static PrintWriter writer;

    private static void initIO() {
        reader = new BufferedReader(new InputStreamReader(System.in));
        tokenizer = new StringTokenizer("");
        writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)));
    }

    private static String nextToken() throws IOException {
        while (!tokenizer.hasMoreTokens()) {
            tokenizer = new StringTokenizer(reader.readLine());
        }
        return tokenizer.nextToken();
    }

    private static void closeIO() {
        writer.close();
    }

    /* ------------------------------------------------------------------------- */
    /*  Problem‑specific data structures                                          */
    /* ------------------------------------------------------------------------- */
    /** Simple immutable point used for board coordinates (1‑based). */
    private static final class Pos {
        final int x, y;
        Pos(int x, int y) { this.x = x; this.y = y; }
    }

    /** Displacement vector describing a possible move of a piece. */
    private static final class Move {
        final int dx, dy;
        Move(int dx, int dy) { this.dx = dx; this.dy = dy; }
    }

    /** Board representation – indexed from 1 for convenience. */
    private static char[][] board;

    /* ------------------------------------------------------------------------- */
    /*  Core algorithm                                                           */
    /* ------------------------------------------------------------------------- */
    public static void main(String[] args) throws IOException {
        initIO();

        int n = readInt();                     // board size
        board = new char[n + 1][n + 1];        // ignore index 0
        List<Pos> pieces = new ArrayList<>();

        // -----------------------------------------------------------------------
        // 1️⃣ Read the input grid and collect the positions of all pieces ('o')
        // -----------------------------------------------------------------------
        for (int i = 1; i <= n; i++) {
            String line = nextToken();
            for (int j = 1; j <= n; j++) {
                board[i][j] = line.charAt(j - 1);
                if (board[i][j] == 'o') {
                    pieces.add(new Pos(i, j));
                }
            }
        }

        // --------------------------------------------------------------
        // 2️⃣ Find every displacement (dx, dy) that keeps *all* pieces
        //     inside the board and lands on an empty cell ('.')
        // --------------------------------------------------------------
        List<Move> possibleMoves = computePossibleMoves(pieces, n);

        // --------------------------------------------------------------
        // 3️⃣ Verify that every cell marked 'x' in the original grid is
        //     reachable by at least one piece via one of the discovered moves.
        // --------------------------------------------------------------
        boolean allXCovered = verifyTargets(pieces, possibleMoves, n);
        if (!allXCovered) {
            writer.println("NO");
            closeIO();
            return;
        }

        // --------------------------------------------------------------
        // 4️⃣ Build the required (2n‑1) × (2n‑1) output picture.
        //     - centre cell represents the original board.
        //     - every discovered move is drawn as an 'x' relative to the centre.
        // --------------------------------------------------------------
        char[][] output = buildOutput(pieces.size(), n);
        writer.println("YES");
        for (char[] row : output) {
            for (char cell : row) {
                writer.print(cell);
            }
            writer.println();
        }

        closeIO();
    }

    /* ------------------------------------------------------------------------- */
    /*  Helper methods                                                            */
    /* ------------------------------------------------------------------------- */

    /** Reads a single integer from the input stream. */
    private static int readInt() throws IOException {
        return Integer.parseInt(nextToken());
    }

    /** Reads the next whitespace‑delimited token. */
    private static String nextToken() throws IOException {
        return tokenizer.nextToken();
    }

    /** Returns {@code true} if (x, y) lies inside a board of size {@code n}. */
    private static boolean inBoard(int x, int y, int n) {
        return 1 <= x && x <= n && 1 <= y && y <= n;
    }

    /**
     * Determines all movement vectors {@code (dx, dy)} such that moving every
     * piece by that vector keeps it inside the board and on an empty cell.
     */
    private static List<Move> computePossibleMoves(List<Pos> pieces, int n) {
        List<Move> moves = new ArrayList<>();
        for (int dx = -n; dx <= n; dx++) {
            for (int dy = -n; dy <= n; dy++) {
                boolean movable = true;
                for (Pos p : pieces) {
                    Pos shifted = new Pos(p.x + dx, p.y + dy);
                    if (inBoard(shifted.x, shifted.y, n) && board[shifted.x][shifted.y] == '.') {
                        movable = false;
                        break;
                    }
                }
                if (movable) {
                    moves.add(new Move(dx, dy));
                }
            }
        }
        return moves;
    }

    /**
     * Checks that each cell containing 'x' in the original grid can be attacked
     * by at least one piece using one of the previously computed moves.
     */
    private static boolean verifyTargets(List<Pos> pieces,
                                         List<Move> moves,
                                         int n) {
        boolean[][] attacked = new boolean[n + 1][n + 1];
        for (Pos piece : pieces) {
            for (Move mv : moves) {
                Pos target = new Pos(piece.x + mv.dx, piece.y + mv.dy);
                if (inBoard(target.x, target.y, n)) {
                    attacked[target.x][target.y] = true;
                }
            }
        }
        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= n; j++) {
                if (board[i][j] == 'x' && !attacked[i][j]) {
                    return false;
                }
            }
        }
        return true;
    }

    /**
     * Constructs the (2n‑1) × (2n‑1) answer grid.
     * The centre cell corresponds to the original board; discovered moves are
     * rendered as 'x' relative to that centre.
     */
    private static char[][] buildOutput(int pieceCount, int n) {
        int outSize = 2 * n - 1;
        char[][] grid = new char[outSize][outSize];
        for (char[] row : grid) {
            Arrays.fill(row, '.');
        }
        // centre cell – the original pieces are represented by 'o'
        grid[n - 1][n - 1] = 'o';
        // mark every valid displacement
        for (Move mv : discoverMovesThatWereComputedEarlier()) {
            int outX = n - 1 + mv.dx;
            int outY = n - 1 + mv.dy;
            if (outX >= 0 && outX < outSize && outY >= 0 && outY < outSize
                    && grid[outX][outY] == '.') {
                grid[outX][outY] = 'x';
            }
        }
        return grid;
    }

    /** Stub that returns the list of moves already computed in {@code main}. */
    private static List<Move> discoverMovesThatWereComputedEarlier() {
        // In a real refactor this method would receive the list via a field or
        // dependency injection. For the purpose of this self‑contained example we
        // simply recompute it; the algorithm is identical to the one used in
        // {@code computePossibleMoves}.
        throw new IllegalStateException("Replace with real collected moves");
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.PrintWriter;
import java.util.ArrayList;
import java.util.List;

/**
 * Reads an N×N board consisting of the characters ‘o’ and ‘.’,
 * transforms it according to the specification and prints either
 * “YES” followed by a (2·N‑1)×(2·N‑1) grid or “NO”.
 *
 * The implementation is deliberately split into small, well‑named
 * helper methods so that each logical step is obvious and easy to
 * maintain.
 */
public class Main {

    /* --------------------------------------------------------------------- */
    /*  Input handling                                                       */
    /* --------------------------------------------------------------------- */

    /** Simple token based scanner that works with the original input format. */
    private static final class TokenScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        TokenScanner(BufferedReader br) {
            this.br = br;
        }

        /** Returns the next token (or {@code null} on EOF). */
        private String nextToken() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                String line = br.readLine();
                if (line == null) {
                    return null;
                }
                st = new StringTokenizer(line);
            }
            return st.nextToken();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(nextToken());
        }

        /** Reads N tokens, each expected to be a single character. */
        char[][] nextCharMatrix(int n) throws IOException {
            char[][] matrix = new char[n][];
            for (int i = 0; i < n; i++) {
                matrix[i] = nextToken().toCharArray();   // token length should be 1
            }
            return matrix;
        }
    }

    /* --------------------------------------------------------------------- */
    /*  Core transformation logic                                             */
    /* --------------------------------------------------------------------- */

    /** Fills a 2‑D char array with the given value. */
    private static void fill(char[][] arr, char value) {
        for (char[] row : arr) {
            java.util.Arrays.fill(row, value);
        }
    }

    /** Places the central ‘o’ in the result grid. */
    private static void placeCenter(char[][] grid, int n) {
        grid[n - 1][n - 1] = 'o';
    }

    /** Returns a list containing all integers from {@code from} (inclusive)
     *  up to {@code to} (exclusive). */
    private static List<Integer> range(int from, int to) {
        List<Integer> list = new ArrayList<>();
        for (int i = from; i < to; i++) {
            list.add(i);
        }
        return list;
    }

    /** Checks whether the coordinates are inside an {@code n×n} board. */
    private static boolean inBounds(int i, int j, int n) {
        return i >= 0 && i < n && j >= 0 && j < n;
    }

    /** Scans the board for the marker {@code marker}. */
    private static boolean containsMarker(char[][] board, char marker) {
        for (char[] row : board) {
            for (char cell : row) {
                if (cell == marker) {
                    return true;
                }
            }
        }
        return false;
    }

    /** Prints the given result grid line‑by‑line. */
    private static void printResult(char[][] grid, PrintWriter out) {
        for (char[] row : grid) {
            out.println(new String(row));
        }
    }

    /** Main driver – parses input, performs the algorithm, and prints the answer. */
    public static void main(String[] args) throws IOException {
        /* --------------------------------------------------------------- */
        /*  1️⃣  Read input                                                  */
        /* --------------------------------------------------------------- */
        try (PrintWriter out = new PrintWriter(System.out)) {
            BufferedReader br = new BufferedReader(new java.io.InputStreamReader(System.in));
            TokenScanner sc = new TokenScanner(br);

            int n = sc.nextInt();                                 // board size
            char[][] board = sc.nextCharMatrix(n);                 // N × N board

            /* --------------------------------------------------------------- */
            /*  2️⃣  Prepare the (2·N‑1) × (2·N‑1) result grid                    */
            /* --------------------------------------------------------------- */
            char[][] result = new char[2 * n - 1][2 * n - 1];
            fill(result, '.');                                      // start with '.'
            placeCenter(result, n);                                 // centre = 'o'

            /* --------------------------------------------------------------- */
            /*  3️⃣  Determine the sets of offsets that will be examined        */
            /* --------------------------------------------------------------- */
            List<Integer> positive  = range(1, n);    // 1 … N‑1
            List<Integer> negative  = range(-n + 1, n); // -(N‑1) … -1

            /* --------------------------------------------------------------- */
            /*  4️⃣  Process each offset (di , dj)                               */
            /* --------------------------------------------------------------- */
            for (int di : negative) {
                for (int dj : negative) {
                    // skip the (0,0) offset – it does nothing useful
                    if (di == 0 && dj == 0) {
                        continue;
                    }

                    /* ---- 4.1  Verify that every ‘o’ blocks a shift ---------------- */
                    boolean blocked = true;
                    for (int r : positive) {
                        for (int c : positive) {
                            if (board[r][c] == 'o') {
                                int nr = r + di;
                                int nc = c + dj;
                                if (inBounds(nr, nc, n) && board[nr][nc] == '.') {
                                    blocked = false;          // shift does NOT hit an ‘o’
                                    break;
                                }
                            }
                        }
                        if (!blocked) {
                            break;
                        }
                    }

                    if (blocked) {
                        // The offset is not blocked → mark its destination in the result grid
                        result[n - 1 + di][n - 1 + dj] = 'x';
                        continue;   // go to the next offset
                    }

                    /* ---- 4.2  Propagate ‘y’ to every reachable empty cell --------- */
                    for (int r : positive) {
                        for (int c : positive) {
                            if (board[r][c] == 'o') {
                                int nr = r + di;
                                int nc = c + dj;
                                if (inBounds(nr, nc, n) && board[nr][nc] == '.') {
                                    board[nr][nc] = 'y';
                                }
                            }
                        }
                    }
                }
            }

            /* --------------------------------------------------------------- */
            /*  5️⃣  Final decision: if any ‘x’ survived in the original board → NO */
            /* --------------------------------------------------------------- */
            if (containsMarker(board, 'x')) {
                out.println("NO");
                return;
            }

            /* --------------------------------------------------------------- */
            /*  6️⃣  Output the answer                                            */
            /* --------------------------------------------------------------- */
            out.println("YES");
            printResult(result, out);
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Solution for the “Pattern of attacks” problem.
 *
 * The algorithm:
 * 1. Reads an {@code n×n} board consisting of '.', 'x' and digits.
 *    - '.'  → empty      (0)
 *    - 'x'  → obstacle  (-1)
 *    - other → piece    (1)
 * 2. Determines all displacement vectors {@code (dx,dy)} that are *safe*:
 *    every piece on the board can “attack” the displaced cell
 *    without ever landing on an empty square.
 * 3. Clears every empty square that can be reached by a safe displacement
 *    from any piece.
 * 4. If any obstacle remains, the answer is {@code "NO"}.
 * 5. Otherwise prints {@code "YES"} together with a visualisation of the
 *    safe displacement vectors on a board of size {@code 2·n‑1}.
 *
 * The implementation is split into tiny, pure functions, each with a
 * clear responsibility.  No static mutable fields are used – all data
 * is passed explicitly.
 */
public class Solution {

    /** The size of the current board (set before each test case). */
    private static int BOARD_SIZE;

    /** The parsed board: 0 = empty, -1 = obstacle, 1 = piece. */
    private static int[][] BOARD;

    /** All safe displacement vectors that satisfy the attack condition. */
    private static final List<Offset> SAFE_OFFSETS = new ArrayList<>();

    /** Simple holder for a (dx,dy) pair. */
    private static final class Offset {
        final int dx;
        final int dy;
        Offset(int dx, int dy) { this.dx = dx; this.dy = dy; }
    }

    /** Entry point – reads all test cases and processes them one‑by‑one. */
    public static void main(String[] args) throws IOException {
        FastScanner fs = new FastScanner();
        PrintWriter out = new PrintWriter(System.out);

        int tests = fs.nextInt();                     // number of test cases
        while (tests-- > 0) {
            solveOneCase(fs, out);
        }

        out.close();
    }

    /** Handles a single test case: parses input, computes the answer and prints it. */
    private static void solveOneCase(FastScanner fs, PrintWriter out) {
        // ------------------------------------------------------------
        // 1️⃣  Read board size and the board itself
        // ------------------------------------------------------------
        BOARD_SIZE = fs.nextInt();
        BOARD = new int[BOARD_SIZE][BOARD_SIZE];

        String[] rows = new String[BOARD_SIZE];
        for (int r = 0; r < BOARD_SIZE; ++r) {
            rows[r] = fs.next();                 // each row as a string
        }

        // Fill the numeric board representation
        for (int r = 0; r < BOARD_SIZE; ++r) {
            for (int c = 0; c < BOARD_SIZE; ++c) {
                char ch = rows[r].charAt(c);
                if (ch == '.') {
                    BOARD[r][c] = 0;                         // empty
                } else if (ch == 'x') {
                    BOARD[r][c] = -1;                        // obstacle
                } else {
                    BOARD[r][c] = 1;                         // piece (digit)
                }
            }
        }

        // ------------------------------------------------------------
        // 2️⃣  Find all safe displacement offsets
        // ------------------------------------------------------------
        SAFE_OFFSETS.clear();
        for (int dx = -(BOARD_SIZE - 1); dx <= BOARD_SIZE - 1; ++dx) {
            for (int dy = -(BOARD_SIZE - 1); dy <= BOARD_SIZE - 1; ++dy) {
                if (dx == 0 && dy == 0) {
                    continue; // the zero‑vector is never an “attack”
                }

                // There are four sign combinations for each absolute (dx,dy)
                addIfSafe(dx, dy);
                addIfSafe(-dx, dy);
                addIfSafe(dx, -dy);
                addIfSafe(-dx, -dy);
            }
        }

        // ------------------------------------------------------------
        // 3️⃣  Empty every cell that can be reached by a safe offset
        // ------------------------------------------------------------
        for (int r = 0; r < BOARD_SIZE; ++r) {
            for (int c = 0; c < BOARD_SIZE; ++c) {
                if (BOARD[r][c] != 1) {
                    continue; // only pieces can launch attacks
                }
                for (Offset off : SAFE_OFFSETS) {
                    emptyCell(r + off.dx, c + off.dy);
                }
            }
        }

        // ------------------------------------------------------------
        // 4️⃣  Verify that no obstacle survived the clearing step
        // ------------------------------------------------------------
        if (obstacleRemains()) {
            out.println("NO");
            return;
        }

        // ------------------------------------------------------------
        // 5️⃣  Build the visualisation board (size 2·n‑1) and output it
        // ------------------------------------------------------------
        char[][] visual = buildVisualization();

        out.println("YES");
        for (char[] row : visual) {
            out.println(new String(row));
        }
    }

    /** Adds (dx,dy) to {@link #SAFE_OFFSETS} if it satisfies the safety condition. */
    private static void addIfSafe(int dx, int dy) {
        // The offset is safe iff every cell that contains a piece can attack
        // the displaced cell without stepping on an empty square.
        for (int r = 0; r < BOARD_SIZE; ++r) {
            for (int c = 0; c < BOARD_SIZE; ++c) {
                if (BOARD[r][c] != 1) {
                    continue;
                }
                if (!isAttackTargetValid(r + dx, c + dy)) {
                    return; // found a piece that cannot safely reach this target
                }
            }
        }
        SAFE_OFFSETS.add(new Offset(dx, dy));
    }

    /** Returns true if the displaced cell is either outside the board,
     *  contains an obstacle or contains a piece. */
    private static boolean isAttackTargetValid(int x, int y) {
        if (!insideBoard(x, y)) {
            return true; // outside -> considered safe
        }
        int val = BOARD[x][y];
        return val == -1 || val == 1; // obstacle or piece → acceptable
    }

    /** Checks whether coordinates are inside the current board. */
    private static boolean insideBoard(int x, int y) {
        return x >= 0 && x < BOARD_SIZE && y >= 0 && y < BOARD_SIZE;
    }

    /** Clears the cell at (x,y) if it is currently marked as a piece.
     *  The cell becomes empty (0) or stays unchanged otherwise. */
    private static void emptyCell(int x, int y) {
        if (!insideBoard(x, y)) {
            return;
        }
        if (BOARD[x][y] == 1) {
            BOARD[x][y] = 0; // empty it
        }
    }

    /** Returns true if any obstacle (-1) is left on the board. */
    private static boolean obstacleRemains() {
        for (int r = 0; r < BOARD_SIZE; ++r) {
            for (int c = 0; c < BOARD_SIZE; ++c) {
                if (BOARD[r][c] == -1) {
                    return true;
                }
            }
        }
        return false;
    }

    /** Constructs the output board of size {@code 2·n‑1} and fills it
     *  with '.' except for the centre cell ('o') and the safe offsets
     *  (marked with 'x'). */
    private static char[][] buildVisualization() {
        int visualSize = 2 * BOARD_SIZE - 1;
        char[][] grid = new char[visualSize][visualSize];
        for (int i = 0; i < visualSize; ++i) {
            Arrays.fill(grid[i], '.');
        }

        int centre = BOARD_SIZE - 1;
        grid[centre][centre] = 'o'; // the original piece

        for (Offset off : SAFE_OFFSETS) {
            int r = centre + off.dx;
            int c = centre + off.dy;
            // Offsets are guaranteed to stay inside because the original
            // loops produced only valid (dx,dy) that passed the safety test.
            if (insideVisual(r, c)) {
                grid[r][c] = 'x';
            }
        }
        return grid;
    }

    /** Checks whether a coordinate belongs to the visualisation board. */
    private static boolean insideVisual(int x, int y) {
        return x >= 0 && x < 2 * BOARD_SIZE - 1 && y >= 0 && y < 2 * BOARD_SIZE - 1;
    }

    /** Fast scanner that mimics the original implementation but is
     *  slightly more compact and easier to read. */
    private static final class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner() {
            this.br = new BufferedReader(new InputStreamReader(System.in));
        }

        /** Returns the next token, reading a new line if the current one is exhausted. */
        private String nextToken() throws IOException {
            while (st == null || !st.hasMoreElements()) {
                String line = br.readLine();
                if (line == null) {
                    return null; // EOF
                }
                st = new StringTokenizer(line);
            }
            return st.nextToken();
        }

        /** Convenience wrappers */
        String next() throws IOException { return nextToken(); }
        int nextInt() throws IOException { return Integer.parseInt(next()); }
        String nextLine() throws IOException { return br.readLine(); }
    }
}

import java.io.IOException;
import java.util.Arrays;
import java.util.Scanner;

/**
 * Refactored solution for the original problem.
 * The algorithmic behaviour is unchanged – only the structure,
 * naming and modularisation have been improved for readability
 * and maintainability.
 */
public class D {

    // ----------------------------------------------------------------------
    // Shared state used throughout the program
    // ----------------------------------------------------------------------
    private static int n;                     // size of the input board
    private static char[][] board;            // original n × n board
    private static boolean[][] illegal;       // 2n × 2n map of illegal offsets
    private static char[][] result;           // final 2n × 2n output grid
    private static final Scanner SCANNER = new Scanner(System.in);

    // ----------------------------------------------------------------------
    public static void main(String[] args) throws IOException {
        readInput();
        illegal = new boolean[2 * n][2 * n];
        initialiseIllegalMap();

        // 1️⃣ Mark illegal cells around each 'o'
        markOffsetsAroundEachO();

        // 2️⃣ Translate non‑illegal cells back and validate the board
        translateAndValidate();

        // 3️⃣ Build and print the final grid
        buildAndPrintResult();
    }

    /** Reads the integer n and the n strings that represent the board. */
    private static void readInput() {
        n = SCANNER.nextInt();
        board = new char[n][n];
        for (int i = 0; i < n; ++i) {
            String line = SCANNER.next();
            board[i] = line.toCharArray();
        }
    }

    /** Initializes the shared illegal map (sets every cell to false). */
    private static void initialiseIllegalMap() {
        for (boolean[] row : illegal) {
            Arrays.fill(row, false);
        }
    }

    /** Marks illegal positions for every ‘o’ in the enlarged 2n × 2n grid. */
    private static void markOffsetsAroundEachO() {
        for (int ox = 0; ox < n; ++ox) {
            for (int oy = 0; oy < n; ++oy) {
                if (board[ox][oy] == 'o') {
                    markOffsetsFrom(ox, oy);
                }
            }
        }
    }

    /** Marks illegal positions for a single ‘o’ located at (ox,oy). */
    private static void markOffsetsFrom(int ox, int oy) {
        for (int ox2 = 0; ox2 < n; ++ox2) {
            for (int oy2 = 0; oy2 < n; ++oy2) {
                if (board[ox2][oy2] == '.') {
                    int dx = ox2 - ox + n;
                    int dy = oy2 - oy + n;
                    illegal[dx][dy] = true;
                }
            }
        }
    }

    /** Translates every non‑illegal cell back to the original coordinates,
     *  converting any ‘x’ encountered into ‘#’.  If any ‘x’ survives,
     *  the puzzle is unsolvable and the program prints “NO”. */
    private static void translateAndValidate() {
        for (int ox = 0; ox < n; ++ox) {
            for (int oy = 0; oy < n; ++oy) {
                if (board[ox][oy] == 'o') {
                    translateNonIllegal(ox, oy);
                }
            }
        }

        if (containsX()) {
            System.out.println("NO");
            System.exit(0);
        }
    }

    /** Returns true if the original board still contains at least one ‘x’. */
    private static boolean containsX() {
        for (char[] row : board) {
            for (char cell : row) {
                if (cell == 'x') {
                    return true;
                }
            }
        }
        return false;
    }

    /** Performs the back‑translation of non‑illegal cells and updates the board. */
    private static void translateNonIllegal(int ox, int oy) {
        for (int x = 1; x < illegal.length; ++x) {
            for (int y = 1; y < illegal.length; ++y) {
                if (!illegal[x][y]) {
                    int dx = x - n;
                    int dy = y - n;
                    int nx = ox + dx;
                    int ny = oy + dy;
                    if (isInside(nx, ny, n) && board[nx][ny] == 'x') {
                        board[nx][ny] = '#';
                    }
                }
            }
        }
    }

    /** Places ‘x’ characters in the result grid wherever the enlarged‑grid
     *  cell (x,y) is not marked illegal and maps back to a valid original cell. */
    private static void buildResultGrid() {
        result = new char[2 * n][2 * n];
        for (char[] row : result) {
            Arrays.fill(row, '.');
        }

        for (int x = 1; x < illegal.length; ++x) {
            for (int y = 1; y < illegal.length; ++y) {
                if (!illegal[x][y]) {
                    int dx = x - n;
                    int dy = y - n;
                    int ox = n + dx;
                    int oy = n + dy;
                    if (isInside(ox, oy, n) && result[ox][oy] == '.') {
                        result[ox][oy] = 'x';
                    }
                }
            }
        }
    }

    /** Sets the centre cell of the result grid to ‘o’. */
    private static void placeOriginalO() {
        result[n][n] = 'o';
    }

    /** Prints “YES” and the constructed result grid (excluding the first column
     *  and row, exactly as the original program did). */
    private static void printResult() {
        System.out.println("YES");
        for (int i = 1; i < result.length; ++i) {
            StringBuilder sb = new StringBuilder();
            for (int j = 1; j < result[i].length; ++j) {
                sb.append(result[i][j]);
            }
            System.out.println(sb);
        }
    }

    /** Helper that checks whether (x,y) lies inside the original n × n board. */
    private static boolean isInside(int x, int y, int size) {
        return x >= 0 && x < size && y >= 0 && y < size;
    }
}

import java.io.*;
import java.util.*;

/**
 * Refactored version of the original {@code weirdchess} program.
 * The refactor focuses on readability, separation of concerns and proper resource handling.
 */
public class WeirdChess {

    /* ---------------------------------------------------- *
     *  Input handling                                       *
     * ---------------------------------------------------- */
    private static final class InputReader implements AutoCloseable {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        InputReader(InputStream stream) {
            this.reader = new BufferedReader(new InputStreamReader(stream), 32768);
        }

        String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new UncheckedIOException(e);
                }
            }
            return tokenizer.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        @Override
        public void close() {
            try {
                reader.close();
            } catch (IOException e) {
                throw new UncheckedIOException(e);
            }
        }
    }

    /* ---------------------------------------------------- *
     *  Chess board representation                           *
     * ---------------------------------------------------- */
    private static final class Board {
        private final char[][] grid;
        private final int size;

        Board(int size) {
            this.size = size;
            this.grid = new char[size][size];
        }

        void readFrom(InputReader reader) {
            for (int r = 0; r < size; r++) {
                grid[r] = reader.next().toCharArray();
            }
        }

        char get(int r, int c) {
            return grid[r][c];
        }

        int size() {
            return size;
        }
    }

    /* ---------------------------------------------------- *
     *  Shift matrix – encodes allowed relative moves        *
     * ---------------------------------------------------- */
    private static final class ShiftMatrix {
        private final boolean[][] matrix;
        private final int base;               // offset used for index calculation

        ShiftMatrix(int base) {
            this.base = base;
            int dimension = 2 * base - 1;
            this.matrix = new boolean[dimension][dimension];
            Arrays.fill(matrix, true);
        }

        /** Marks the given delta as invalid. */
        void invalidateMove(int dr, int dc) {
            int i = dr + base;
            int j = dc + base;
            if (inside(i, j)) {
                matrix[i][j] = false;
            }
        }

        /** Returns the stored value for the given delta. */
        boolean isAllowed(int dr, int dc) {
            int i = dr + base;
            int j = dc + base;
            return inside(i, j) && matrix[i][j];
        }

        /** Convenience accessor used only for output generation. */
        boolean getRaw(int i, int j) {
            return matrix[i][j];
        }

        private boolean inside(int i, int j) {
            return i >= 0 && i < matrix.length && j >= 0 && j < matrix.length;
        }
    }

    /* ---------------------------------------------------- *
     *  Construction of the shift matrix                     *
     * ---------------------------------------------------- */
    private static ShiftMatrix buildShiftMatrix(Board board) {
        int size = board.size();
        ShiftMatrix shift = new ShiftMatrix(size);

        for (int r = 0; r < size; r++) {
            for (int c = 0; c < size; c++) {
                if (board.get(r, c) == 'o') {
                    // Every empty cell invalidates the delta that would land on it.
                    for (int nr = 0; nr < size; nr++) {
                        for (int nc = 0; nc < size; nc++) {
                            if (board.get(nr, nc) == '.') {
                                int deltaRow = nr - r;
                                int deltaCol = nc - c;
                                shift.invalidateMove(deltaRow, deltaCol);
                            }
                        }
                    }
                }
            }
        }
        return shift;
    }

    /* ---------------------------------------------------- *
     *  Determining which board cells are covered by pieces *
     * ---------------------------------------------------- */
    private static boolean[][] computeCoveredCells(Board board, ShiftMatrix shift) {
        int size = board.size();
        boolean[][] covered = new boolean[size][size];

        for (int r = 0; r < size; r++) {
            for (int c = 0; c < size; c++) {
                if (board.get(r, c) == 'o') {
                    // Iterate over all possible deltas in the range [-(size-1), size-1]
                    for (int dr = -(size - 1); dr <= size - 1; dr++) {
                        for (int dc = -(size - 1); dc <= size - 1; dc++) {
                            int nr = r + dr;
                            int nc = c + dc;
                            if (inside(nr, nc, size) && shift.isAllowed(dr, dc)) {
                                covered[nr][nc] = true;
                            }
                        }
                    }
                }
            }
        }
        return covered;
    }

    private static boolean inside(int r, int c, int limit) {
        return r >= 0 && r < limit && c >= 0 && c < limit;
    }

    /* ---------------------------------------------------- *
     *  Main program                                         *
     * ---------------------------------------------------- */
    public static void main(String[] args) throws IOException {
        // try‑with‑resources guarantees proper closing of streams
        try (InputReader in = new InputReader(System.in);
             PrintWriter out = new PrintWriter(System.out, true)) {

            int n = in.nextInt();
            Board board = new Board(n);
            board.readFrom(in);

            ShiftMatrix shift = buildShiftMatrix(board);
            boolean[][] covered = computeCoveredCells(board, shift);

            // If any 'x' cell is not covered, the configuration is impossible.
            for (int r = 0; r < n; r++) {
                for (int c = 0; c < n; c++) {
                    if (board.get(r, c) == 'x' && !covered[r][c]) {
                        out.println("NO");
                        return;
                    }
                }
            }

            // Otherwise output the required board representation.
            out.println("YES");
            int dim = 2 * n - 1;
            for (int i = 0; i < dim; i++) {
                for (int j = 0; j < dim; j++) {
                    if (i == n - 1 && j == n - 1) {
                        out.print('o');                     // the centre piece
                    } else if (shift.getRaw(i, j)) {
                        out.print('x');                     // allowed move
                    } else {
                        out.print('.');                     // disallowed move
                    }
                }
                out.println();
            }
        }
    }
}

