/**
 * Utility class that encapsulates the logic for solving the problem.
 * The algorithm is a direct translation of the original implementation,
 * but organized into clearly named methods and constants.
 */
final class Solver {

    // Symbol constants – makes the intent explicit.
    private static final char EMPTY = '.';
    private static final char OCCUPIED = 'o';
    private static final char TARGET = 'x';

    /** Entry point required by the original `Main` class. */
    public static void solve(int testNumber, InputReader in, PrintWriter out) {
        // ----- 1. Read board size and the board itself -----
        String line = in.readLine();
        if (line == null) {
            return; // no input
        }
        int n = Integer.parseInt(line.trim());
        char[][] board = readBoard(in, n);

        // ----- 2. Build the result grid (size 2*n-1) -----
        char[][] result = buildResultGrid(board, n);

        // ----- 3. Validate that every 'x' in the original board
        //          can be reached from at least one 'o' through the mapping -----
        if (!allXHaveReachableO(board, result, n)) {
            out.println("NO");
            return;
        }

        // ----- 4. Output the answer -----
        out.println("YES");
        printResult(result, out);
    }

    /** Reads exactly `size` lines and returns a 2‑D char array representing the board. */
    private static char[][] readBoard(InputReader in, int size) {
        char[][] board = new char[size][size];
        for (int i = 0; i < size; i++) {
            String row = in.readLine();
            if (row == null) {
                throw new IllegalStateException("Unexpected end of input while reading board.");
            }
            for (int j = 0; j < size; j++) {
                board[i][j] = row.charAt(j);
            }
        }
        return board;
    }

    /**
     * Constructs the intermediate grid of size {@code 2*n-1}.
     * The centre cell contains the character {@code 'o'}.
     * For every empty cell in the original board the algorithm marks
     * the reflected position for each 'o' with '.'.
     */
    private static char[][] buildResultGrid(char[][] board, int n) {
        final int expanded = 2 * n - 1;
        final int offset = n - 1; // centre coordinate
        char[][] result = new char[expanded][expanded];

        // Initialise every cell with the null character (the default value for char[]).
        // The original code later replaces those with 'x' when printing.
        // To keep the same behaviour we leave them untouched.

        // Place a single 'o' at the centre of the expanded grid.
        result[offset][offset] = OCCUPIED;

        // For each '.' in the original board, reflect it for every 'o'.
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (board[i][j] != EMPTY) {
                    continue;
                }
                for (int k = 0; k < n; k++) {
                    for (int l = 0; l < n; l++) {
                        if (board[k][l] == OCCUPIED) {
                            int r = offset + i - k;
                            int c = offset + j - l;
                            if (isInside(r, c, expanded)) {
                                result[r][c] = EMPTY;
                            }
                        }
                    }
                }
            }
        }
        return result;
    }

    /** Simple boundary check for the expanded grid. */
    private static boolean isInside(int row, int col, int limit) {
        return row >= 0 && row < limit && col >= 0 && col < limit;
    }

    /**
     * Verifies that for every position containing 'x' in the original board
     * there exists at least one 'o' such that the reflected cell in the
     * result grid is **not** '.'.
     *
     * @return {@code true} if validation succeeds, otherwise {@code false}.
     */
    private static boolean allXHaveReachableO(char[][] board, char[][] result, int n) {
        final int offset = n - 1;
        final int limit = 2 * n - 1;

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (board[i][j] != 'x') {
                    continue;
                }
                boolean reachable = false;
                for (int k = 0; k < n; k++) {
                    for (int l = 0; l < n; l++) {
                        if (board[k][l] == OCCUPIED) {
                            int r = offset + i - k;
                            int c = offset + j - l;
                            if (isInside(r, c, limit) && result[r][c] != EMPTY) {
                                reachable = true;
                                break;
                            }
                        }
                    }
                    if (reachable) {
                        break;
                    }
                }
                if (!reachable) {
                    return false; // found an isolated 'x'
                }
            }
        }
        return true;
    }

    /** Prints the expanded grid replacing any '\0' (default) with 'x'. */
    private static void printResult(char[][] result, PrintWriter out) {
        int size = result.length;
        for (int i = 0; i < size; i++) {
            StringBuilder sb = new StringBuilder(size);
            for (int j = 0; j < size; j++) {
                char ch = result[i][j];
                if (ch == '\0') {
                    ch = TARGET;
                }
                sb.append(ch);
            }
            out.println(sb);
        }
    }
}

