/* -------------------------------------------------------------------------- */
/* --------------------------- Core Solver ----------------------------------- */
/* -------------------------------------------------------------------------- */
final class Solver {

    private Solver() { /* utility class – no instances */ }

    /**
     * Entry point used by {@link Main}.
     *
     * @param dummyTestNumber unused (kept for compatibility with the original code)
     * @param in   input reader
     * @param out  output writer
     */
    public void solve(int dummyTestNumber, InputReader in, OutputWriter out) {
        int size = in.readInt();                           // board dimension
        char[][] board = IOUtils.readTable(in, size, size); // read the whole board

        List<Pos> pieces = collectPieces(board);
        List<Pos> moves  = generateWinningMoves(board, size, pieces);

        if (!isCompleteCoverage(board, size, moves)) {
            out.printLine("NO");
            return;
        }

        out.printLine("YES");
        printResult(board, size, moves, out);
    }

    /** Returns all cells that contain an 'o'. */
    private static List<Pos> collectPieces(char[][] board) {
        List<Pos> pieces = new ArrayList<>();
        for (int r = 0; r < board.length; r++) {
            for (int c = 0; c < board[r].length; c++) {
                if (board[r][c] == 'o') {
                    pieces.add(new Pos(r, c));
                }
            }
        }
        return Collections.unmodifiableList(pieces);
    }

    /**
     * Determines all translation vectors (dr, dc) such that moving every piece
     * by that vector would land exactly on a free cell ('.'). Those vectors are
     * the only legitimate moves for the solution.
     */
    private static List<Pos> generateWinningMoves(char[][] board, int size,
                                                  List<Pos> pieces) {
        List<Pos> moves = new ArrayList<>();
        for (int dr = -size + 1; dr < size; dr++) {
            for (int dc = -size + 1; dc < size; dc++) {
                if (dr == 0 && dc == 0) {
                    continue; // self‑move is not allowed
                }
                if (isDisplacementValid(dr, dc, board, size, pieces)) {
                    moves.add(new Pos(dr, dc));
                }
            }
        }
        return Collections.unmodifiableList(moves);
    }

    /** Checks whether a displacement (dr, dc) reaches only empty cells for all pieces. */
    private static boolean isDisplacementValid(int dr, int dc, char[][] board,
                                               int size, List<Pos> pieces) {
        for (Pos p : pieces) {
            int nr = p.row + dr;
            int nc = p.col + dc;
            if (inBounds(nr, nc, size, size) && board[nr][nc] == '.') {
                return false; // at least one empty cell would be filled → invalid
            }
        }
        return true; // no reachable empty cells → valid displacement
    }

    /**
     * Verifies that for every cell containing 'x' there exists at least one
     * winning move that would bring a piece onto that 'x' when moved backwards.
     */
    private static boolean isCompleteCoverage(char[][] board, int size,
                                              List<Pos> moves) {
        for (int r = 0; r < size; r++) {
            for (int c = 0; c < size; c++) {
                if (board[r][c] == 'x') {
                    boolean found = false;
                    for (Pos m : moves) {
                        int sr = r - m.row;
                        int sc = c - m.col;
                        if (inBounds(sr, sc, size, size) && board[sr][sc] == 'o') {
                            found = true;
                            break;
                        }
                    }
                    if (!found) {
                        return false; // uncovered 'x' → impossible solution
                    }
                }
            }
        }
        return true;
    }

    /** Builds the final 2·size‑1 × 2·size‑1 grid and prints it. */
    private static void printResult(char[][] original, int size,
                                    List<Pos> moves, OutputWriter out) {
        char[][] result = new char[2 * size - 1][2 * size - 1];
        Arrays.fill(result, '.');
        result[size - 1][size - 1] = 'o'; // centre always stays an 'o'

        for (Pos m : moves) {
            int r = size + m.row - 1;
            int c = size + m.col - 1;
            result[r][c] = 'x'; // mark valid moves
        }

        for (char[] row : result) {
            out.printLine(row);
        }
    }

    /** Simple bounds check used throughout the algorithm. */
    private static boolean inBounds(int r, int c, int rows, int cols) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }
}

/* -------------------------------------------------------------------------- */
/* -------------------------- Input utilities ------------------------------- */
/* -------------------------------------------------------------------------- */
class InputReader {
    private final InputStream stream;
    private final byte[] buffer = new byte[1 << 10];
    private int bytesInBuffer = 0;
    private int bytePointer = 0;

    InputReader(InputStream stream) {
        this.stream = stream;
    }

    private int readByte() throws IOException {
        if (bytesInBuffer == bytePointer) {
            bytesInBuffer = stream.read(buffer);
            bytePointer = 0;
            if (bytesInBuffer == -1) {
                return -1;
            }
        }
        return buffer[bytePointer++];
    }

    /** Reads a signed 32‑bit integer. */
    int readInt() {
        int c;
        do {
            c = readByte();
        } while (c <= ' ');
        int sign = 1;
        if (c == '-') {
            sign = -1;
            c = readByte();
        }
        int value = 0;
        while (c >= '0' && c <= '9') {
            value = value * 10 + (c - '0');
            c = readByte();
        }
        return value * sign;
    }
}

/* -------------------------------------------------------------------------- */
/* --------------------------- Output utilities ----------------------------- */
class OutputWriter {
    private final PrintWriter writer;

    OutputWriter(OutputStream out) {
        this.writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(out)));
    }

    /** Prints the supplied objects separated by a single space (no trailing space). */
    void print(Object... objects) {
        for (int i = 0; i < objects.length; i++) {
            if (i != 0) {
                writer.print(' ');
            }
            writer.print(objects[i]);
        }
    }

    /** Prints the supplied objects followed by a line‑break. */
    void printLine(Object... objects) {
        print(objects);
        writer.println();
    }

    /** Prints a character array as a line. */
    void printLine(char[] array) {
        writer.println(array);
    }

    /** Closes the underlying writer. */
    void close() {
        writer.close();
    }
}

/* -------------------------------------------------------------------------- */
/* ------------------------------ IO helpers --------------------------------- */
/* -------------------------------------------------------------------------- */
final class IOUtils {
    private IOUtils() { /* static utility class */ }

    /** Reads a char[] of the given length from the input reader. */
    static char[] readCharArray(InputReader in, int length) {
        char[] arr = new char[length];
        for (int i = 0; i < length; i++) {
            arr[i] = in.readCharacter();
        }
        return arr;
    }

    /** Reads a rectangular char matrix of size rows × cols. */
    static char[][] readTable(InputReader in, int rows, int cols) {
        char[][] table = new char[rows][];
        for (int i = 0; i < rows; i++) {
            table[i] = readCharArray(in, cols);
        }
        return table;
    }
}

/* -------------------------------------------------------------------------- */
/* ---------------------------- Miscellaneous utilities ---------------------- */
/* -------------------------------------------------------------------------- */
final class MiscUtils {
    private MiscUtils() { /* static utils – no instances */ }

    /** Checks whether (r, c) lies inside a matrix of the given dimensions. */
    static boolean inBounds(int r, int c, int rows, int cols) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }
}

/* -------------------------------------------------------------------------- */
/* ------------------------------ Core record --------------------------------- */
record Pos(int row, int col) implements Comparable<Pos> {
    @Override
    public int compareTo(Pos o) {
        int cmp = Integer.compare(this.row, o.row);
        return cmp != 0 ? cmp : Integer.compare(this.col, o.col);
    }
}

import java.io.*;
import java.util.*;

public class Main {

    /* Constants that describe the symbols used in the puzzle */
    private static final char EMPTY = '.';
    private static final char OCCUPIED = 'o';
    private static final char MARK_X = 'x';
    private static final char RESULT_OCCUPIED = 'o';
    private static final char RESULT_CANDIDATE = 'x';

    public static void main(String[] args) throws IOException {
        /* Read input, solve the puzzle and output the answer */
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in))) {
            int n = Integer.parseInt(br.readLine().trim());
            char[][] board = readBoard(br, n);
            char[][] result = buildResult(board, n);

            if (result == null) {
                System.out.println("NO");
            } else {
                System.out.println("YES");
                printResult(result);
            }
        }
    }

    /** Reads an n×n board from the supplied BufferedReader. */
    private static char[][] readBoard(BufferedReader br, int n) throws IOException {
        char[][] board = new char[n][n];
        for (int i = 0; i < n; i++) {
            String line = br.readLine();
            if (line == null) {
                throw new IOException("Unexpected end of input");
            }
            board[i] = line.toCharArray();
        }
        return board;
    }

    /**
     * Constructs the result board of size (2·n‑1)×(2·n‑1) according to the
     * algorithm described in the original program.
     *
     * @return the constructed board, or {@code null} if the puzzle has no solution.
     */
    private static char[][] buildResult(char[][] board, int n) {
        int dim = 2 * n - 1;
        char[][] result = new char[dim][dim];
        fill(result, RESULT_OCCUPIED);
        placeCenterOccupied(result, n);

        boolean[][] reachable = new boolean[n][n];

        /* Examine every possible displacement (dx, dy) */
        for (int dx = -n + 1; dx < n; dx++) {
            for (int dy = -n + 1; dy < n; dy++) {
                if (dx == 0 && dy == 0) continue;
                if (!isDisplacementAllowed(board, dx, dy)) continue;

                markReachable(board, dx, dy, reachable);
                placeCandidate(result, dx, dy, n);
            }
        }

        /* All 'x' marks in the original board must be reachable, otherwise unsolvable */
        if (!allXMarksReachable(board, reachable)) {
            return null;
        }
        return result;
    }

    /** Fills a 2‑D array with the given character. */
    private static void fill(char[][] arr, char value) {
        for (char[] row : arr) {
            Arrays.fill(row, value);
        }
    }

    /** Places the central 'o' in the result board. */
    private static void placeCenterOccupied(char[][] board, int n) {
        board[n - 1][n - 1] = RESULT_OCCUPIED;
    }

    /**
     * Determines whether a displacement (dx,dy) is legally allowed.
     * A displacement is illegal if moving every 'o' by (dx,dy) lands on an EMPTY cell
     * that lies inside the original board.
     */
    private static boolean isDisplacementAllowed(char[][] board, int dx, int dy) {
        for (int i = 0; i < board.length; i++) {
            for (int j = 0; j < board[i].length; j++) {
                if (board[i][j] == OCCUPIED) {
                    int ni = i + dx;
                    int nj = j + dy;
                    if (inside(ni, nj, board.length) && board[ni][nj] == EMPTY) {
                        return false;
                    }
                }
            }
        }
        return true;
    }

    /** Marks all cells reachable by a valid displacement. */
    private static void markReachable(char[][] board, int dx, int dy, boolean[][] reachable) {
        for (int i = 0; i < board.length; i++) {
            for (int j = 0; j < board[i].length; j++) {
                if (board[i][j] == OCCUPIED) {
                    int ni = i + dx;
                    int nj = j + dy;
                    if (inside(ni, nj, board.length)) {
                        reachable[ni][nj] = true;
                    }
                }
            }
        }
    }

    /** Places a candidate 'x' in the result board at the appropriate offset. */
    private static void placeCandidate(char[][] result, int dx, int dy, int n) {
        int centre = n - 1;
        result[centre + dx][centre + dy] = RESULT_CANDIDATE;
    }

    /** Checks that every 'x' in the original board is marked reachable. */
    private static boolean allXMarksReachable(char[][] board, boolean[][] reachable) {
        for (int i = 0; i < board.length; i++) {
            for (int j = 0; j < board[i].length; j++) {
                if (board[i][j] == MARK_X && !reachable[i][j]) {
                    return false;
                }
            }
        }
        return true;
    }

    /** Helper that tells whether a coordinate lies inside a square of given side. */
    private static boolean inside(int x, int y, int limit) {
        return x >= 0 && x < limit && y >= 0 && y < limit;
    }

    /** Prints the resulting board line by line. */
    private static void printResult(char[][] board) {
        for (char[] row : board) {
            System.out.println(new String(row));
        }
    }
}

import java.util.Scanner;

/**
 * Refactored version of the original program.
 *
 * <p>
 *   The program reads an {@code n×n} board, builds an auxiliary {@code (2n‑1)×(2n‑1)} mask,
 *   populates the mask according to the movement rules of the pieces and finally checks
 *   that every {@code 'x'} on the board can be attacked by at least one {@code 'o'}.
 *   If all pieces can be hit the word {@code YES} is printed together with the mask,
 *   otherwise {@code NO} is printed.</p>
 *
 * <p>Key improvements over the original version:</p>
 * <ul>
 *   <li>Meaningful identifiers and constants.</li>
 *   <li>Extraction of logic into small, reusable methods.</li>
 *   <li>Guard clauses and early returns for clearer flow.</li>
 *   <li>Resource handling with a single {@code Scanner} instance.</li>
 *   <li>Added validation and explanatory comments.</li>
 * </ul>
 */
public class D {

    /** Scanner used for all input – automatically closed at program exit. */
    private static final Scanner SCANNER = new Scanner(System.in);

    /** Entry point. */
    public static void main(String[] args) {
        run();
    }

    /** Orchestrates the whole workflow. */
    private static void run() {
        int boardSize = readBoardSize();
        SCANNER.nextLine(); // consume residual line‑breaker

        char[][] board = readBoard(boardSize);
        char[][] mask = createEmptyMask(boardSize);

        placeObviousMoves(board, mask, boardSize);
        fillUnmarkedMask(mask, boardSize);

        if (!verifyAllPiecesCanAttack(board, mask, boardSize)) {
            System.out.println("NO");
            return;
        }

        System.out.println("YES");
        printMask(mask, boardSize);
    }

    /** Reads and validates the integer {@code n}. */
    private static int readBoardSize() {
        String line = SCANNER.nextLine().trim();
        return Integer.parseInt(line);
    }

    /** Reads the {@code n} rows that constitute the board. */
    private static char[][] readBoard(int size) {
        char[][] board = new char[size][];
        for (int i = 0; i < size; i++) {
            String row = SCANNER.nextLine();
            if (row.length() != size) {
                throw new IllegalArgumentException(
                        "Row " + i + " must contain exactly " + size + " characters");
            }
            board[i] = row.toCharArray();
        }
        return board;
    }

    /** Creates an empty mask of size {@code (2*n‑1)×(2*n‑1)}. */
    private static char[][] createEmptyMask(int size) {
        int maskSize = 2 * size - 1;
        return new char[maskSize][maskSize];
    }

    /** Marks cells reachable from empty squares ('.') with '.'. */
    private static void placeObviousMoves(char[][] board, char[][] mask, int size) {
        for (int freeX = 0; freeX < size; freeX++) {
            for (int freeY = 0; freeY < size; freeY++) {
                if (board[freeX][freeY] == '.') {
                    markReachable(board, mask, size, freeX, freeY);
                }
            }
        }
    }

    /** Marks every mask cell that corresponds to a reachable offset from (freeX,freeY). */
    private static void markReachable(char[][] board, char[][] mask, int size, int freeX, int freeY) {
        for (int pieceX = 0; pieceX < size; pieceX++) {
            for (int pieceY = 0; pieceY < size; pieceY++) {
                if (board[pieceX][pieceY] == 'o') {
                    int offsetX = freeX - pieceX;
                    int offsetY = freeY - pieceY;
                    int maskX = size - 1 + offsetX;
                    int maskY = size - 1 + offsetY;
                    if (isInsideMask(maskX, maskY, mask)) {
                        mask[maskX][maskY] = '.';
                    }
                }
            }
        }
    }

    /** Returns {@code true} if the given coordinates are inside the mask. */
    private static boolean isInsideMask(int x, int y, char[][] mask) {
        return x >= 0 && x < mask.length && y >= 0 && y < mask[0].length;
    }

    /** Fills every still‑zero cell of the mask with 'x'. */
    private static void fillUnmarkedMask(char[][] mask, int size) {
        for (int i = 0; i < mask.length; i++) {
            for (int j = 0; j < mask[i].length; j++) {
                if (mask[i][j] == 0) {
                    mask[i][j] = 'x';
                }
            }
        }
    }

    /** Checks that each 'x' on the board can be hit by at least one piece. */
    private static boolean verifyAllPiecesCanAttack(char[][] board, char[][] mask, int size) {
        for (int pieceX = 0; pieceX < size; pieceX++) {
            for (int pieceY = 0; pieceY < size; pieceY++) {
                if (board[pieceX][pieceY] == 'x' && !hasAttackPath(board, mask, size, pieceX, pieceY)) {
                    return false;
                }
            }
        }
        return true;
    }

    /** Determines whether a given 'x' can be attacked from any 'o'. */
    private static boolean hasAttackPath(char[][] board, char[][] mask, int size, int attackX, int attackY) {
        for (int pieceX = 0; pieceX < size; pieceX++) {
            for (int pieceY = 0; pieceY < size; pieceY++) {
                if (board[pieceX][pieceY] == 'o') {
                    int offsetX = attackX - pieceX;
                    int offsetY = attackY - pieceY;
                    int maskX = size - 1 + offsetX;
                    int maskY = size - 1 + offsetY;
                    if (isInsideMask(maskX, maskY, mask) && mask[maskX][maskY] == '.') {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    /** Prints the resulting mask to standard output. */
    private static void printMask(char[][] mask, int size) {
        for (char[] row : mask) {
            System.out.println(new String(row));
        }
    }
}

import java.io.*;
import java.util.*;

public class Main implements Runnable {
    private BufferedReader in;
    private PrintWriter out;
    private StringTokenizer tok;

    public static void main(String[] args) {
        new Main().run();
    }

    public void solve() throws IOException {
        int N = Integer.parseInt(nextToken());
        char[][] map = readGrid(N);
        char[][] res = createResultGrid(N);
        markValidDisplacements(map, res);
        if (validateAllMarkedX(map, res)) {
            outputResult(res);
        } else {
            out.println("NO");
        }
    }

    private char[][] readGrid(int N) throws IOException {
        char[][] grid = new char[N][N];
        for (int i = 0; i < N; i++) {
            grid[i] = nextToken().toCharArray();
        }
        return grid;
    }

    private char[][] createResultGrid(int N) {
        char[][] res = new char[2 * N - 1][2 * N - 1];
        for (char[] row : res) {
            Arrays.fill(row, 'x');
        }
        res[N - 1][N - 1] = 'o';
        return res;
    }

    private void markValidDisplacements(char[][] map, char[][] res) {
        int center = N - 1;
        for (int i = 0; i < N; i++) {
            for (int j = 0; j < N; j++) {
                if (map[i][j] == 'o') {
                    for (int ii = 0; ii < N; ii++) {
                        for (int jj = 0; jj < N; jj++) {
                            if (map[ii][jj] == '.') {
                                int dx = ii - i;
                                int dy = jj - j;
                                int r = center + dx;
                                int c = center + dy;
                                if (isInBounds(r, c, res)) {
                                    res[r][c] = '.';
                                }
                            }
                        }
                    }
                }
            }
        }
    }

    private boolean isInBounds(int r, int c, char[][] res) {
        return r >= 0 && r < res.length && c >= 0 && c < res[0].length;
    }

    private boolean validateAllMarkedX(char[][] map, char[][] res) {
        int center = map.length - 1;
        for (int i = 0; i < map.length; i++) {
            for (int j = 0; j < map.length; j++) {
                if (map[i][j] == 'x') {
                    if (!hasValidDisplacement(map, res, i, j)) {
                        return false;
                    }
                }
            }
        }
        return true;
    }

    private boolean hasValidDisplacement(char[][] map, char[][] res, int xRow, int xCol) {
        for (int i = 0; i < map.length; i++) {
            for (int j = 0; j < map.length; j++) {
                if (map[i][j] == 'o') {
                    int dx = xRow - i;
                    int dy = xCol - j;
                    int r = (map.length - 1) + dx;
                    int c = (map.length - 1) + dy;
                    if (isInBounds(r, c, res) && res[r][c] == '.') {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    private void outputResult(char[][] res) {
        out.println("YES");
        for (char[] row : res) {
            out.println(new String(row));
        }
    }

    public void run() {
        try {
            in = new BufferedReader(new InputStreamReader(System.in));
            out = new PrintWriter(System.out);
            solve();
            in.close();
            out.close();
        } catch (IOException e) {
            System.exit(0);
        }
    }

    public String nextToken() throws IOException {
        while (tok == null || !tok.hasMoreTokens()) {
            tok = new StringTokenizer(in.readLine());
        }
        return tok.nextToken();
    }

    public int nextInt() throws IOException {
        return Integer.parseInt(nextToken());
    }
    PrintWriter out;
    BufferedReader in;
    StringTokenizer tok;
}

import java.util.*;
import java.util.stream.Collectors;

public class D {

    /** immutable point used as a key in sets */
    private record Pos(int r, int c) {
        Pos translate(int dr, int dc) {
            return new Pos(r + dr, c + dc);
        }
    }

    private static final char EMPTY = '.';

    /** read the board and collect positions of 'o' and 'x' */
    private static void readBoard(Scanner sc, int n,
                                   Set<Pos> oSet, Set<Pos> xSet) {
        for (int i = 0; i < n; i++) {
            String line = sc.next().trim();
            for (int j = 0; j < n; j++) {
                char ch = line.charAt(j);
                if (ch == 'o') {
                    oSet.add(new Pos(i, j));
                } else if (ch == 'x') {
                    xSet.add(new Pos(i, j));
                }
            }
        }
    }

    /** create the (2n‑1)×(2n‑1) result board */
    private static char[][] buildResult(int n, Set<Pos> oSet) {
        char[][] result = new char[2 * n - 1][2 * n - 1];

        // fill with '.' and place the centre 'o'
        for (int i = 0; i < result.length; i++) {
            Arrays.fill(result[i], EMPTY);
        }
        result[n - 1][n - 1] = 'o';

        // for each possible translation (dx,dy) of the whole pattern
        for (int i = 0; i < result.length; i++) {
            for (int j = 0; j < result.length; j++) {
                if (i == n - 1 && j == n - 1) continue;          // centre already done
                int dx = j - (n - 1);
                int dy = i - (n - 1);

                // check that translating every 'o' by (dx,dy) does NOT land on an empty cell of the original board
                boolean valid = true;
                for (Pos o : oSet) {
                    Pos translated = o.translate(dx, dy);
                    if (isInside(translated.r, translated.c, n) &&
                        originalBoard.get(translated) == EMPTY) {
                        valid = false;
                        break;
                    }
                }

                if (valid) {
                    result[i][j] = 'x';
                    // mark every original 'x' cell that this translation covers
                    for (Pos o : oSet) {
                        Pos translated = o.translate(dx, dy);
                        if (isInside(translated.r, translated.c, n)) {
                            covered[translated.r][translated.c] = true;
                        }
                    }
                }
            }
        }
        return result;
    }

    /** verify that every original 'x' position was covered by some translation */
    private static boolean allXCovered(Set<Pos> xSet) {
        return xSet.stream().allMatch(p -> covered[p.r][p.c]);
    }

    /** helper – is (r,c) a valid index inside an n×n board? */
    private static boolean isInside(int r, int c, int n) {
        return 0 <= r && r < n && 0 <= c && c < n;
    }

    /** the original board is needed for validation; filled after reading */
    private static List<String> originalBoard;

    /** temporary coverage map used while building the result */
    private static boolean[][] covered;

    /** --------------------------------------------------------------- */
    private void run() {
        try (Scanner sc = new Scanner(System.in)) {
            int n = sc.nextInt();
            originalBoard = new ArrayList<>(n);
            for (int i = 0; i < n; i++) {
                originalBoard.add(sc.next().trim());
            }

            Set<Pos> o = new HashSet<>();
            Set<Pos> x = new HashSet<>();
            readBoard(sc, n, o, x);

            covered = new boolean[n][n];

            char[][] out = buildResult(n, o);
            boolean allCovered = allXCovered(x);

            System.out.println(allCovered ? "YES" : "NO");
            if (allCovered) {
                for (char[] row : out) {
                    System.out.println(new String(row));
                }
            }
        }
    }

    public static void main(String[] args) {
        new D().run();
    }
}

import java.io.*;
import java.util.Arrays;

/**
 * Validates a chess‑like board configuration and produces the required
 * auxiliary board. The logic is split into small, well‑named methods
 * to improve readability and future maintenance.
 */
public class ChessboardValidator {

    /* --------------------------------------------------------------------- */
    /*  Constant symbols used throughout the program                         */
    /* --------------------------------------------------------------------- */
    private static final char EMPTY   = '.';   // empty cell
    private static final char ORIGIN  = 'o';   // a piece on the original board
    private static final char MARK    = 'x';   // reachable cell marker

    /* --------------------------------------------------------------------- */
    /*  Instance fields (input & intermediate results)                      */
    /* --------------------------------------------------------------------- */
    private int n;                     // board dimension
    private char[][] source;           // original n × n board
    private char[][] answer;           // (2n‑1) × (2n‑1) answer board

    /* --------------------------------------------------------------------- */
    /*  Entry point                                                          */
    /* --------------------------------------------------------------------- */
    public static void main(String[] args) {
        new ChessboardValidator().run();
    }

    /* --------------------------------------------------------------------- */
    /*  Orchestrates the whole workflow                                      */
    /* --------------------------------------------------------------------- */
    private void run() {
        try (FastScanner fs = new FastScanner()) {
            solve(fs);
        }
    }

    /* --------------------------------------------------------------------- */
    /*  Reads the board from the scanner                                      */
    /* --------------------------------------------------------------------- */
    private void solve(FastScanner fs) {
        readBoard(fs);
        buildAnswer();
        if (isConsistent()) {
            printResult();
        } else {
            System.out.println("NO");
        }
    }

    /* --------------------------------------------------------------------- */
    /*  Populates the source board                                            */
    /* --------------------------------------------------------------------- */
    private void readBoard(FastScanner fs) {
        n = fs.nextInt();
        source = new char[n][n];
        for (int row = 0; row < n; row++) {
            source[row] = fs.nextToken().toCharArray();
        }
    }

    /* --------------------------------------------------------------------- */
    /*  Constructs the (2n‑1) × (2n‑1) auxiliary board                         */
    /* --------------------------------------------------------------------- */
    private void buildAnswer() {
        int size = 2 * n - 1;
        answer = new char[size][size];
        fill(answer, EMPTY);

        // place the origin cell at the centre of the answer board
        answer[n - 1][n - 1] = ORIGIN;

        // decide which offsets are safe and mark them
        for (int dx = -n + 1; dx <= n - 1; dx++) {
            for (int dy = -n + 1; dy <= n - 1; dy++) {
                if (dx == 0 && dy == 0) {
                    continue; // already handled
                }
                if (isOffsetSafe(dx, dy)) {
                    answer[n - 1 + dx][n - 1 + dy] = MARK;
                }
            }
        }
    }

    /* --------------------------------------------------------------------- */
    /*  Determines whether a given (dx, dy) offset can be used safely        */
    /* --------------------------------------------------------------------- */
    private boolean isOffsetSafe(int dx, int dy) {
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (source[i][j] != ORIGIN) {
                    continue;
                }
                int ni = i + dx;
                int nj = j + dy;
                if (0 <= ni && ni < n && 0 <= nj && nj < n) {
                    if (source[ni][nj] == EMPTY) {
                        return false;               // unsafe move
                    }
                }
            }
        }
        return true;                               // safe move
    }

    /* --------------------------------------------------------------------- */
    /*  Utility to fill a 2‑D array with a given character                     */
    /* --------------------------------------------------------------------- */
    private void fill(char[][] array, char value) {
        for (char[] row : array) {
            Arrays.fill(row, value);
        }
    }

    /* --------------------------------------------------------------------- */
    /*  Verifies whether the constructed answer reproduces the original board */
    /* --------------------------------------------------------------------- */
    private boolean isConsistent() {
        char[][] result = new char[n][n];
        fill(result, EMPTY);

        // copy all original pieces
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (source[i][j] == ORIGIN) {
                    result[i][j] = ORIGIN;
                }
            }
        }

        // propagate 'x' marks from each origin according to the answer board
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (source[i][j] != ORIGIN) {
                    continue;
                }
                for (int dx = -n + 1; dx <= n - 1; dx++) {
                    for (int dy = -n + 1; dy <= n - 1; dy++) {
                        if (answer[n - 1 + dx][n - 1 + dy] != MARK) {
                            continue;
                        }
                        int ni = i + dx;
                        int nj = j + dy;
                        if (0 <= ni && ni < n && 0 <= nj && nj < n) {
                            if (result[ni][nj] == EMPTY) {
                                result[ni][nj] = MARK;
                            }
                        }
                    }
                }
            }
        }

        // final comparison
        return Arrays.deepEquals(source, result);
    }

    /* --------------------------------------------------------------------- */
    /*  Prints the required output                                            */
    /* --------------------------------------------------------------------- */
    private void printResult() {
        System.out.println("YES");
        for (char[] row : answer) {
            System.out.println(new String(row));
        }
    }

    /* --------------------------------------------------------------------- */
    /*  Simple fast scanner used for competitive‑programming‑style input      */
    /* --------------------------------------------------------------------- */
    private static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner() {
            this(System.in);
        }

        FastScanner(InputStream stream) {
            br = new BufferedReader(new InputStreamReader(stream));
        }

        String nextToken() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    throw new UncheckedIOException(e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(nextToken());
        }
    }
}

import java.io.*;
import java.util.Arrays;

/**
 * Refactored solution that improves readability, naming and structure
 * while preserving the original behaviour.
 */
public class Main {

    // -------------------------------------------------------------------------
    // Constants
    // -------------------------------------------------------------------------
    private static final char ORIGINAL_MARKER = 'o';
    private static final char TARGET_EMPTY   = '.';   // '.' in the source grid
    private static final char RESULT_EMPTY   = 'x';   // 'x' in the result board
    private static final char RESULT_MARKER  = 'o';   // the extra marker placed in the centre

    // -------------------------------------------------------------------------
    // Entry point
    // -------------------------------------------------------------------------
    public static void main(String[] args) throws IOException {
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(System.in))) {
            solve(reader);
        }
    }

    // -------------------------------------------------------------------------
    // Core logic
    // -------------------------------------------------------------------------
    private static void solve(BufferedReader reader) throws IOException {
        int n = parseInt(readLine(reader));
        char[][] original = readGrid(reader, n);

        int boardSize = 2 * n - 1;
        int centre = n - 1;                     // boardSize / 2 == n‑1

        char[][] result = new char[boardSize][boardSize];
        fillWith(result, RESULT_EMPTY);

        placeMarkers(original, result, centre);
        int totalMarkers = countMarkers(original);

        if (!isConfigurationPossible(original, result, centre, totalMarkers)) {
            System.out.println("NO");
            return;
        }

        // place the central marker and output the board
        result[centre][centre] = RESULT_MARKER;
        printResult(result);
    }

    // -------------------------------------------------------------------------
    // Helper methods
    // -------------------------------------------------------------------------
    private static int parseInt(String value) {
        return Integer.parseInt(value.trim());
    }

    private static char[][] readGrid(BufferedReader reader, int size) throws IOException {
        char[][] grid = new char[size][];
        for (int i = 0; i < size; i++) {
            grid[i] = readLine(reader).toCharArray();
        }
        return grid;
    }

    private static String readLine(BufferedReader reader) throws IOException {
        String line;
        while ((line = reader.readLine()) != null && line.isBlank()) { /* skip empty lines */ }
        return line;
    }

    private static char[][] newBoard(int size) {
        return new char[size][size];
    }

    private static void fillWith(char[][] board, char value) {
        for (char[] row : board) {
            Arrays.fill(row, value);
        }
    }

    /**
     * For every {@code ORIGINAL_MARKER} in the source grid, mark the
     * corresponding offset in the result board with {@code TARGET_EMPTY}.
     */
    private static void placeMarkers(char[][] original, char[][] result, int centre) {
        int n = original.length;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (original[i][j] == ORIGINAL_MARKER) {
                    for (int x = 0; x < n; x++) {
                        for (int y = 0; y < n; y++) {
                            if (original[x][y] == TARGET_EMPTY) {
                                int dx = x - i;
                                int dy = y - j;
                                result[centre + dx][centre + dy] = TARGET_EMPTY;
                            }
                        }
                    }
                }
            }
        }
    }

    private static int countMarkers(char[][] grid) {
        int count = 0;
        for (char[] row : grid) {
            for (char cell : row) {
                if (cell == ORIGINAL_MARKER) {
                    count++;
                }
            }
        }
        return count;
    }

    /**
     * Determines whether the generated result board can satisfy all
     * constraints imposed by the original markers.
     *
     * @return {@code true} if at least one placement is valid; {@code false}
     *         otherwise.
     */
    private static boolean isConfigurationPossible(char[][] original,
                                                   char[][] result,
                                                   int centre,
                                                   int totalMarkers) {
        int n = original.length;
        int[] conflictCounts = new int[n * n]; // linear index for brevity

        // Scan every source marker and compare its surrounding cells
        // with the expectations encoded in the result board.
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (original[i][j] != ORIGINAL_MARKER) {
                    continue;
                }
                for (int x = 0; x < n; x++) {
                    for (int y = 0; y < n; y++) {
                        int dx = x - i;
                        int dy = y - j;
                        char expected = result[centre + dx][centre + dy];
                        char actual   = original[x][y];

                        // Conflict occurs when the expected symbol is the opposite
                        // of the actual one (i.e. 'x' vs '.' or vice‑versa).
                        if ((actual == 'x' && expected == TARGET_EMPTY) ||
                            (actual == TARGET_EMPTY && expected == RESULT_EMPTY)) {
                            int idx = x * n + y;
                            conflictCounts[idx]++;
                        }
                    }
                }
            }
        }

        // If any cell was conflicting with *all* markers, the configuration
        // is impossible.
        for (int cnt : conflictCounts) {
            if (cnt == totalMarkers) {
                return false;
            }
        }
        return true;
    }

    private static void printResult(char[][] board) {
        StringBuilder out = new StringBuilder();
        out.append("YES\n");
        int size = board.length;
        for (int i = 0; i < size; i++) {
            for (int j = 0; j < size; j++) {
                out.append(board[i][j]);
            }
            out.append('\n');
        }
        System.out.print(out.toString());
    }
}

import java.io.*;
import java.util.*;

/**
 * Solves the problem described in the original source code.
 * The program reads an n×n board, analyses possible moves,
 * checks a feasibility condition and finally prints a pattern
 * of reachable cells.
 */
public class Solver {

    /** Simple container for a board position. */
    private static final class Pos {
        final int row;
        final int col;

        Pos(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }

    /** Offset used for move generation. The original code swapped
     *  dx / dy – we keep the same semantics (row offset = dy, column offset = dx). */
    private static final class Offset {
        final int rowOffset; // corresponds to original "dy"
        final int colOffset; // corresponds to original "dx"

        Offset(int rowOffset, int colOffset) {
            this.rowOffset = rowOffset;
            this.colOffset = colOffset;
        }
    }

    /** Input helper – automatically closes the underlying stream. */
    private static final class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner(BufferedReader br) {
            this.br = br;
        }

        /** Returns the next token, or {@code null} on EOF. */
        String nextToken() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) {
                        return null;                 // EOF
                    }
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new UncheckedIOException(e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(nextToken());
        }
    }

    /** Utility method – checks whether a cell is inside an n×n board. */
    private static boolean inBounds(int r, int c, int n) {
        return r >= 0 && r < n && c >= 0 && c < n;
    }

    /** Generates the full list of candidate offsets used by the algorithm. */
    private static List<Offset> generateOffsets(int n) {
        List<Offset> offs = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                // four symmetric variants required by the original specification
                addIfNew(offs, new Offset(i, j));
                addIfNew(offs, new Offset(-i, -j));
                addIfNew(offs, new Offset(-i, j));
                addIfNew(offs, new Offset(i, -j));
            }
        }
        return offs;
    }

    /** Helper that avoids storing identical offsets twice. */
    private static void addIfNew(List<Offset> list, Offset off) {
        // Duplicates are harmless here, but keeping the list a bit cleaner looks nicer.
        for (Offset e : list) {
            if (e.rowOffset == off.rowOffset && e.colOffset == off.colOffset) {
                return;
            }
        }
        list.add(off);
    }

    /** Entry point – delegates all work to {@link Solver#solve()}. */
    public static void main(String[] args) throws IOException {
        new Solver().solve();
    }

    /** Core logic – reads input, processes the board and prints the answer. */
    private void solve() throws IOException {
        // -----------------------------------------------------------------
        // 1. Read input
        // -----------------------------------------------------------------
        try (FastScanner fs = new FastScanner(new BufferedReader(new InputStreamReader(System.in))) {
            int n = fs.nextInt();
            String[] board = new String[n];
            for (int i = 0; i < n; i++) {
                board[i] = fs.nextToken();
            }

            // -----------------------------------------------------------------
            // 2. Collect positions of the 'o' pieces
            // -----------------------------------------------------------------
            List<Pos> pieces = new ArrayList<>();
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < n; j++) {
                    if (board[i].charAt(j) == 'o') {
                        pieces.add(new Pos(i, j));
                    }
                }
            }

            // -----------------------------------------------------------------
            // 3. Build the set of candidate offsets
            // -----------------------------------------------------------------
            List<Offset> candidates = generateOffsets(n);

            // -----------------------------------------------------------------
            // 4. Mark all cells that are reachable from any 'o' piece
            // -----------------------------------------------------------------
            boolean[][] reachable = new boolean[n][n];
            for (Pos p : pieces) {
                reachable[p.row][p.col] = true;
                for (Offset off : candidates) {
                    int nr = p.row + off.rowOffset;
                    int nc = p.col + off.colOffset;
                    if (inBounds(nr, nc, n)) {
                        reachable[nr][nc] = true;
                    }
                }
            }

            // -----------------------------------------------------------------
            // 5. Verify the “x” condition – every 'x' must be reachable
            // -----------------------------------------------------------------
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < n; j++) {
                    if (board[i].charAt(j) == 'x' && !reachable[i][j]) {
                        System.out.println("NO");
                        return;
                    }
                }
            }
            System.out.println("YES");

            // -----------------------------------------------------------------
            // 6. Build and print the final N×N pattern (N = 2n‑1)
            // -----------------------------------------------------------------
            int size = 2 * n - 1;
            int centerRow = (size - 1) / 2;
            int centerCol = (size - 1) / 2;

            StringBuilder out = new StringBuilder();
            for (int r = 0; r < size; r++) {
                for (int c = 0; c < size; c++) {
                    if (r == centerRow && c == centerCol) {
                        out.append('o');
                    } else {
                        char ch = '.';
                        for (Offset off : candidates) {
                            if (centerRow + off.rowOffset == r && centerCol + off.colOffset == c) {
                                ch = 'x';
                                break;
                            }
                        }
                        out.append(ch);
                    }
                }
                out.append('\n');
            }
            System.out.print(out.toString());
        }
    }
}

