/**
 * Handles all input parsing. The implementation is deliberately tiny –
 * it only wraps a BufferedReader/InputStreamReader pair and provides
 * convenient typed getters used by the solver.
 */
final class FastScanner {

    private final BufferedReader reader;
    private StringTokenizer tokenizer;

    FastScanner(InputStream stream) {
        this.reader = new BufferedReader(new InputStreamReader(stream));
    }

    /** Returns the next token as an {@code int}. */
    int nextInt() {
        return Integer.parseInt(next());
    }

    /** Returns the next token as a {@code char[]} (the word without whitespace). */
    char[] nextWord() {
        return next().toCharArray();
    }

    /** Returns the next token as a {@code String}. */
    private String next() {
        while (tokenizer == null || !tokenizer.hasMoreTokens()) {
            tokenizer = new StringTokenizer(readLine());
        }
        return tokenizer.nextToken();
    }

    /** Returns the next full line (or {@code null} on EOF). */
    private String readLine() {
        try {
            return reader.readLine();
        } catch (IOException e) {
            throw new RuntimeException(e);
        }
    }
}

/**
 * Core logic of the problem – separates all steps into small, well‑named
 * methods.  Each method does one thing and returns early on errors,
 * which makes the flow easy to follow.
 */
final class Solver {

    /** Symbols used in the input. */
    private static final char OCCUPIED = 'o';
    private static final char EMPTY    = '.';
    private static final char ATTACKED  = 'x';

    /** Size of the board (n × n). */
    private final int size;

    /** Raw board read from the scanner. */
    private final char[][] board;

    /** 2·n‑1 × 2·n‑1 pattern that describes valid moves. */
    private final boolean[][] movePattern;

    /** Cells that are covered by at least one legal move. */
    private final boolean[][] covered;

    /** Constructor – stores the size and the raw board. */
    Solver(int size, char[][] board) {
        this.size = size;
        this.board = board;
        this.movePattern = new boolean[2 * size - 1][2 * size - 1];
        this.covered    = new boolean[size][size];
    }

    /** Public entry point called from {@code Main}. */
    void solve(FastScanner in, PrintWriter out) {
        readBoard(in);
        buildMovePattern();
        if (!verifyAllAttackedCellsAreCovered()) {
            out.println("NO");
            return;
        }
        printPositiveAnswer(out);
    }

    /** Reads the integer n and the n rows of the board. */
    private void readBoard(FastScanner in) {
        int n = in.nextInt();
        this.size = n;                       // store size for later use
        char[][] tmp = new char[n][];
        for (int i = 0; i < n; i++) {
            tmp[i] = in.nextWord();
        }
        this.board = tmp;
    }

    /** Constructs the move‑pattern matrix (`movePattern`). */
    private void buildMovePattern() {
        int limit = 2 * size - 1;
        // start assuming every vector is possible
        for (boolean[] row : movePattern) {
            Arrays.fill(row, true);
        }

        int centre = size - 1;   // the centre of the enlarged matrix
        movePattern[centre][centre] = false;   // the "stay‑still" vector is illegal

        // For every occupied cell (o) and every empty cell (.) we forbid
        // the vector that would land on the empty cell from the occupied one.
        for (int i = 0; i < size; i++) {
            for (int j = 0; j < size; j++) {
                if (board[i][j] != OCCUPIED) {
                    continue;
                }
                for (int ni = 0; ni < size; ni++) {
                    for (int nj = 0; nj < size; nj++) {
                        if (board[ni][nj] == EMPTY) {
                            int vecX = ni - i + centre;
                            int vecY = nj - j + centre;
                            movePattern[vecX][vecY] = false;
                        }
                    }
                }
            }
        }
    }

    /** Fills the `covered` matrix – a cell is covered if a legal vector exists
     *  that moves an 'o' directly onto it.  Afterwards we verify that every
     *  'x' in the original board is covered. */
    private void computeCovered() {
        Arrays.stream(covered).forEach(row -> Arrays.fill(row, false));

        int centre = size - 1;
        for (int i = 0; i < size; i++) {
            for (int j = 0; j < size; j++) {
                if (board[i][j] != OCCUPIED) {
                    continue;
                }
                for (int vi = 0; vi < movePattern.length; vi++) {
                    for (int vj = 0; vj < movePattern.length; vj++) {
                        if (!movePattern[vi][vj]) {
                            continue;               // illegal vector
                        }
                        int targetX = i + vi - centre;
                        int targetY = j + vj - centre;
                        if (insideBoard(targetX, targetY)) {
                            covered[targetX][targetY] = true;
                        }
                    }
                }
            }
        }
    }

    /** Returns {@code true} if every cell marked 'x' in the original board is
     *  covered by at least one legal move. */
    private boolean verifyAllAttackedCellsAreCovered() {
        computeCovered();

        for (int i = 0; i < size; i++) {
            for (int j = 0; j < size; j++) {
                if (board[i][j] == ATTACKED && !covered[i][j]) {
                    return false;
                }
            }
        }
        return true;
    }

    /** Prints the final “YES” + the pattern matrix. The centre cell (size‑1,
     * size‑1) is rendered as the character 'o'; all other cells are rendered
     * as 'x' for a possible vector or '.' for an impossible one. */
    private void printPositiveAnswer(PrintWriter out) {
        out.println("YES");
        int centre = size - 1;

        for (int i = 0; i < movePattern.length; i++) {
            for (int j = 0; j < movePattern.length; j++) {
                char ch = (i == centre && j == centre) ? 'o' : movePattern[i][j] ? 'x' : '.';
                out.print(ch);
            }
            out.println();
        }
    }

    /** Simple bounds check for the enlarged matrix. */
    private boolean insideBoard(int x, int y) {
        return x >= 0 && x < movePattern.length && y >= 0 && y < movePattern.length;
    }
}

import java.io.PrintWriter;
import java.io.InputStream;
import java.util.Scanner;
import java.util.Arrays;

/**
 * Refactored solution that maintains the original algorithmic behaviour
 * while improving readability, modularity and resource handling.
 */
public class Main {

    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            PrintWriter out = new PrintWriter(System.out);
            new Solver().solve(scanner, out);
            out.flush();
        }
    }

    /**
     * Core logic of the problem.
     */
    static class Solver {

        void solve(Scanner in, PrintWriter out) {
            int n = in.nextInt();
            String[] lines = readBoard(in, n);

            char[][] board = toCharMatrix(lines);
            boolean[][] can = buildCanMatrix(board, n);
            boolean[][] reachable = markReachable(board, can, n);
            validateX(board, reachable);
            printResult(can, n);
        }

        /** Reads the n board lines from the scanner. */
        private String[] readBoard(Scanner in, int n) {
            String[] board = new String[n];
            for (int i = 0; i < n; i++) {
                board[i] = in.next();
            }
            return board;
        }

        /** Convert String[][] to a primitive `char[][]` for easier handling. */
        private char[][] toCharMatrix(String[] lines) {
            char[][] matrix = new char[lines.length][];
            for (int i = 0; i < lines.length; i++) {
                matrix[i] = lines[i].toCharArray();
            }
            return matrix;
        }

        /**
         * Builds the {@code can} matrix (size (2n‑1)×(2n‑1)).  Initially all
         * positions are {@code true}, and positions that must be false are
         * cleared according to the rules described in the original algorithm.
         */
        private boolean[][] buildCanMatrix(char[][] board, int n) {
            boolean[][] can = new boolean[2 * n - 1][2 * n - 1];
            fillWithTrue(can);
            // Mark positions that become false when a piece 'o' blocks a '.' cell.
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < n; j++) {
                    if (board[i][j] == 'o') {
                        clearReachableFrom(board, i, j, n, can);
                    }
                }
            }
            return can;
        }

        /** Helper to fill a matrix with {@code true}. */
        private void fillWithTrue(boolean[][] matrix) {
            for (boolean[] row : matrix) {
                Arrays.fill(row, true);
            }
        }

        /**
         * For a given piece at (x0, y0), clear entries in {@code can} that
         * correspond to positions reachable from any '.' cell in the original board.
         */
        private void clearReachableFrom(char[][] board, int x0, int y0,
                                        int n, boolean[][] can) {
            for (int x = 0; x < n; x++) {
                for (int y = 0; y < n; y++) {
                    if (board[x][y] == '.') {
                        int relX = x - x0;
                        int relY = y - y0;
                        int idxX = relX + n - 1;
                        int idxY = relY + n - 1;
                        if (isInside(can, idxX, idxY)) {
                            can[idxX][idxY] = false;
                        }
                    }
                }
            }
        }

        /** Checks whether a coordinate lies inside a matrix. */
        private boolean isInside(boolean[][] matrix, int r, int c) {
            return r >= 0 && r < matrix.length && c >= 0 && c < matrix[0].length;
        }

        /**
         * Determines which cells are reachable by a piece when moving through
         * positions marked {@code true} in {@code can}.  The result is stored in
         * a {@code reachable} matrix of size n×n.
         */
        private boolean[][] markReachable(char[][] board, boolean[][] can, int n) {
            boolean[][] reachable = new boolean[n][n];
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < n; j++) {
                    if (board[i][j] == 'o') {
                        propagateReach(i, j, n, can, reachable);
                    }
                }
            }
            return reachable;
        }

        /** Populates {@code reachable} for a piece located at (originX, originY). */
        private void propagateReach(int originX, int originY,
                                    int n, boolean[][] can, boolean[][] reachable) {
            for (int x = 0; x < n; x++) {
                for (int y = 0; y < n; y++) {
                    int relX = x - originX;
                    int relY = y - originY;
                    int idxX = relX + n - 1;
                    int idxY = relY + n - 1;
                    if (isInside(can, idxX, idxY) && can[idxX][idxY]) {
                        reachable[x][y] = true;
                    }
                }
            }
        }

        /** Validates that every 'x' cell is reachable; otherwise prints "NO" and exits. */
        private void validateX(char[][] board, boolean[][] reachable) {
            for (int i = 0; i < board.length; i++) {
                for (int j = 0; j < board[i].length; j++) {
                    if (board[i][j] == 'x' && !reachable[i][j]) {
                        System.out.println("NO");
                        System.exit(0);
                    }
                }
            }
        }

        /** Prints the final (2n‑1)×(2n‑1) visual representation. */
        private void printResult(boolean[][] can, int n) {
            int size = can.length;
            StringBuilder out = new StringBuilder();
            for (int i = 0; i < size; i++) {
                for (int j = 0; j < size; j++) {
                    if (i == n - 1 && j == n - 1) {
                        out.append('o');
                    } else if (can[i][j]) {
                        out.append('x');
                    } else {
                        out.append('.');
                    }
                }
                out.append('\n');
            }
            System.out.print(out.toString());
        }
    }
}

import java.io.*;
import java.util.*;
import java.util.Locale;

/**
 * Refactored solution for the original competitive‑programming problem.
 * The algorithm is unchanged – only the code layout, naming and safety have been improved.
 */
public class Main {

    /* ------------------------------------------------------------ */
    /*  Entry point & I/O handling                                    */
    /* ------------------------------------------------------------ */
    public static void main(String[] args) throws IOException {
        // The original program forces US locale for numeric parsing.
        Locale.setDefault(Locale.US);

        // Try‑with‑resources guarantees proper closing of streams.
        try (BufferedReader br = new BufferedReader(
                new InputStreamReader(System.in));
             PrintWriter pw = new PrintWriter(
                     new OutputStreamWriter(System.out))) {

            new Main().solve(br, pw);
        }
    }

    /* ------------------------------------------------------------ */
    /*  Core solving routine                                            */
    /* ------------------------------------------------------------ */
    private void solve(BufferedReader reader,
                      PrintWriter printer) throws IOException {

        this.reader = reader;
        this.printer = printer;
        this.tok = new StringTokenizer("");

        int boardSize = nextInt();                 // n
        char[][] board = new char[boardSize][boardSize];

        // Collect start ( 'o' ) and end ( '.' ) positions
        List<Position> starts = new ArrayList<>();
        List<Position> ends   = new ArrayList<>();

        for (int r = 0; r < boardSize; r++) {
            String line = nextToken();
            for (int c = 0; c < boardSize; c++) {
                char cell = line.charAt(c);
                board[r][c] = cell;
                if (cell == 'o') {
                    starts.add(new Position(r, c));
                } else if (cell == '.') {
                    ends.add(new Position(r, c));
                }
            }
        }

        // -----------------------------------------------------------------
        // 1) Build the "forbidden" offset map from every start → every end
        // -----------------------------------------------------------------
        boolean[][] forbidden = new boolean[2 * boardSize - 1][2 * boardSize - 1];
        for (Position s : starts) {
            for (Position e : ends) {
                markForbidden(forbidden, s, e, boardSize);
            }
        }

        // -----------------------------------------------------------------
        // 2) Starting from each 'o', spread outwards while the offset is not forbidden
        // -----------------------------------------------------------------
        boolean[][] reachable = new boolean[boardSize][boardSize];
        spreadFromStarts(reachable, forbidden, boardSize);

        // -----------------------------------------------------------------
        // 3) Validation – any 'x' cell that remains unreachable makes the answer NO
        // -----------------------------------------------------------------
        for (int r = 0; r < boardSize; r++) {
            for (int c = 0; c < boardSize; c++) {
                if (!reachable[r][c] && board[r][c] == 'x') {
                    printer.println("NO");
                    return;
                }
            }
        }
        printer.println("YES");

        // -----------------------------------------------------------------
        // 4) Print the transformed board
        // -----------------------------------------------------------------
        printTransformedBoard(forbidden, boardSize);
    }

    /* ------------------------------------------------------------ */
    /*  Helper data structures                                        */
    /* ------------------------------------------------------------ */
    /** Simple coordinate holder. */
    private static final class Position {
        final int row;
        final int col;

        Position(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }

    /* ------------------------------------------------------------ */
    /*  Input token utilities                                         */
    /* ------------------------------------------------------------ */
    private BufferedReader reader;
    private PrintWriter printer;
    private StringTokenizer tok;

    /** Returns the next token from the input stream. */
    private String nextToken() throws IOException {
        while (tok == null || !tok.hasMoreTokens()) {
            tok = new StringTokenizer(reader.readLine());
        }
        return tok.nextToken();
    }

    /** Convenience wrappers for primitive types. */
    private int nextInt() throws IOException {
        return Integer.parseInt(nextToken());
    }

    /* ------------------------------------------------------------ */
    /*  Forbidden‑offset handling                                     */
    /* ------------------------------------------------------------ */
    /** Marks the offset (dx,dy) from a start to an end position as forbidden. */
    private static void markForbidden(
            boolean[][] forbidden,
            Position start,
            Position end,
            int boardSize) {

        int dx = end.row - start.row;
        int dy = end.col - start.col;
        int idx = dx + boardSize - 1;   // map to 0‑based index inside the enlarged grid
        int idy = dy + boardSize - 1;

        if (0 <= idx && idx < forbidden.length &&
            0 <= idy && idy < forbidden.length) {
            forbidden[idx][idy] = true;
        }
    }

    /** Populates `reachable` according to the original spreading algorithm. */
    private void spreadFromStarts(
            boolean[][] reachable,
            boolean[][] forbidden,
            int boardSize) {

        int offset = boardSize - 1;               // used for accessing `forbidden`

        for (int r = 0; r < boardSize; r++) {
            for (int c = 0; c < boardSize; c++) {
                // Only start positions need to be processed (they are known to be reachable)
                // The loops reproduce the exact bounds used in the original code.
                // (dx runs from -r to boardSize‑1‑r, inclusive)
                for (int dx = -r; dx + r < boardSize; dx++) {
                    for (int dy = -c; dy + c < boardSize; dy++) {
                        if (!forbidden[dx + offset][dy + offset]) {
                            reachable[r + dx][c + dy] = true;
                        }
                    }
                }
            }
        }
    }

    /** Prints the transformed board representation. */
    private void printTransformedBoard(boolean[][] forbidden, int boardSize) {
        int gridSize = 2 * boardSize - 1;
        for (int i = 0; i < gridSize; i++) {
            for (int j = 0; j < gridSize; j++) {
                if (i == boardSize - 1 && j == boardSize - 1) {
                    printer.print('o');
                } else {
                    printer.print(forbidden[i][j] ? '.' : 'x');
                }
            }
            printer.println();
        }
    }
}

import java.io.*;
import java.util.StringTokenizer;

/**
 * Refactored version of the original solution.
 * <p>
 * The program reads an {@code n × n} board consisting of 'o' (stone) and '.' (empty)
 * cells, builds an enlarged {@code (2n‑1) × (2n‑1)} board (`moves`) that shows where
 * the original stones would be placed after reflecting them across every empty cell,
 * and finally checks whether the original board can be reproduced from that pattern.
 * The result ("YES"/"NO") and the `moves` board are printed to standard output.
 * </p>
 *
 * @author  (refactored by AI)
 */
public class Main implements Closeable {

    /** Input buffer */
    private final BufferedReader reader;

    /** Output stream wrapper */
    private final PrintWriter writer;

    /** Modulo constant used by helper arithmetic methods */
    private static final int MOD = 1_000_000_007;

    /**
     * Constructs the helper that reads from {@code System.in} and writes to
     * {@code System.out}. The constructor is called with a try‑with‑resources block
     * from {@link #main(String)} so that resources are automatically closed.
     *
     * @throws IOException if an I/O error occurs while opening the streams
     */
    public Main() throws IOException {
        this.reader = new BufferedReader(new InputStreamReader(System.in));
        this.writer = new PrintWriter(
                new BufferedWriter(new OutputStreamWriter(System.out))
        );
    }

    /* --------------------------------------------------------------------- */
    /*                         Input helpers                                 */
    /* --------------------------------------------------------------------- */

    /** Tokeniser used to read the next token from the input source. */
    private StringTokenizer tokenizer;

    /**
     * Returns the next token from {@code reader}. If the current tokeniser is
     * {@code null} or exhausted, a new one is created from the next line.
     *
     * @return next token as a {@code String}
     * @throws IOException if an I/O error occurs while reading
     */
    private String nextToken() throws IOException {
        while (tokenizer == null || !tokenizer.hasMoreTokens()) {
            tokenizer = new StringTokenizer(reader.readLine());
        }
        return tokenizer.nextToken();
    }

    /** @return next integer from the input */
    private int nextInt() throws IOException {
        return Integer.parseInt(nextToken());
    }

    /** @return next long from the input */
    private long nextLong() throws IOException {
        return Long.parseLong(nextToken());
    }

    /** @return next double from the input */
    private double nextDouble() throws IOException {
        return Double.parseDouble(nextToken());
    }

    /* --------------------------------------------------------------------- */
    /*                         Arithmetic helpers                             */
    /* --------------------------------------------------------------------- */

    /** Adds two integers under {@code MOD} and returns the result. */
    private static int sum(int a, int b) {
        a += b;
        return a >= MOD ? a - MOD : a;
    }

    /** Returns {@code (a * b) % MOD} as an {@code int}. */
    private static int product(int a, int b) {
        return (int) (1L * a * b % MOD);
    }

    /** Fast exponentiation modulo {@code MOD}. */
    private static int pow(int x, int k) {
        int result = 1;
        while (k > 0) {
            if ((k & 1) == 1) {
                result = product(result, x);
            }
            x = product(x, x);
            k >>>= 1;
        }
        return result;
    }

    /** Returns the modular inverse of {@code x} under {@code MOD}. */
    private static int inv(int x) {
        return pow(x, MOD - 2);
    }

    /* --------------------------------------------------------------------- */
    /*                         Core logic methods                              */
    /* --------------------------------------------------------------------- */

    /**
     * Reads the board size {@code n} and the board itself.
     *
     * @return a 2‑D {@code char} array representing the board
     * @throws IOException if an I/O error occurs
     */
    private char[][] readBoard(int n) throws IOException {
        char[][] board = new char[n][n];
        String line;
        for (int i = 0; i < n; i++) {
            line = reader.readLine();
            if (line == null) {
                throw new EOFException();
            }
            System.arraycopy(line.toCharArray(), 0, board[i], 0, n);
        }
        return board;
    }

    /**
     * Constructs the {@code moves} board – an enlarged grid that marks where
     * each '.' of the original board would be placed relative to every 'o'.
     *
     * @param board the original board
     * @return the constructed moves board
     */
    private char[][] buildMoves(char[][] board) {
        int n = board.length;
        int size = 2 * n - 1;
        char[][] moves = new char[size][size];
        for (char[] row : moves) {
            Arrays.fill(row, 'x');
        }

        int centre = n - 1;               // centre coordinate in the enlarged grid
        moves[centre][centre] = 'o';      // fixed central stone

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (board[i][j] == 'o') {
                    // Propagate '.' to all positions reachable from (i,j)
                    for (int r = 0; r < n; r++) {
                        for (int c = 0; c < n; c++) {
                            if (board[r][c] == '.') {
                                int targetRow = centre + r - i;
                                int targetCol = centre + c - j;
                                // Defensive check – the target must stay inside the grid
                                if (0 <= targetRow && targetRow < size &&
                                    0 <= targetCol && targetCol < size) {
                                    moves[targetRow][targetCol] = '.';
                                }
                            }
                        }
                    }
                }
            }
        }
        return moves;
    }

    /**
     * Builds a pattern (named {@code check} in the original code) that mirrors the
     * original board based on the positions of 'o' and the 'x' cells of {@code moves}.
     *
     * @param board the original board
     * @param moves the moves board produced by {@link #buildMoves(char[][], int)}
     * @return a 2‑D {@code char} array representing the derived pattern
     */
    private char[][] buildCheck(char[][] board, char[][] moves) {
        int n = board.length;
        char[][] check = new char[n][n];
        for (char[] row : check) {
            Arrays.fill(row, '.');
        }

        int centre = n - 1;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (board[i][j] == 'o') {
                    check[i][j] = 'o';
                    // Treat every '.' of the original board as a reference point
                    for (int r = 0; r < n; r++) {
                        for (int c = 0; c < n; c++) {
                            if (board[r][c] == '.') {
                                int relRow = centre + r - i;
                                int relCol = centre + c - j;
                                if (0 <= relRow && relRow < moves.length &&
                                    0 <= relCol && relCol < moves[0].length &&
                                    moves[relRow][relCol] == 'x') {
                                    check[r][c] = 'x';
                                }
                            }
                        }
                    }
                }
            }
        }
        return check;
    }

    /**
     * Executes the solution: reads input, builds the auxiliary boards,
     * compares them and prints the result.
     *
     * @throws IOException if an I/O error occurs during processing
     */
    public void solve() throws IOException {
        int n = nextInt();
        char[][] board = readBoard(n);

        char[][] moves = buildMoves(board);
        char[][] check = buildCheck(board, moves);

        // Verify that the reconstructed board matches the original one.
        for (int i = 0; i < n; i++) {
            if (!new String(board[i]).equals(new String(check[i]))) {
                writer.println("NO");
                return;
            }
        }
        writer.println("YES");
        for (char[] row : moves) {
            writer.println(new String(row));
        }
    }

    /* --------------------------------------------------------------------- */
    /*                         Entry point                                     */
    /* --------------------------------------------------------------------- */

    /**
     * Main entry point. Uses try‑with‑resources to guarantee that the
     * {@link BufferedReader} and {@link PrintWriter} are closed even when an
     * exception is thrown.
     */
    public static void main(String[] args) throws IOException {
        try (Main main = new Main()) {
            main.solve();
        }
    }

    @Override
    public void close() throws IOException {
        reader.close();
        writer.close();
    }
}

import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.Scanner;

/**
 * Refactored version of Prob04.
 * <p>
 * The program reads an {@code n×n} board, builds a {@code (2n‑1)×(2n‑1)} result canvas,
 * places an 'o' at the centre and uses the positions of 'o' in the input to spread
 * '.' symbols.  Afterwards it checks whether every 'x' in the original board can be
 * “covered’’ by at least one such spread.  If all 'x' are covered the program prints
 * {@code YES} followed by the result canvas; otherwise it prints {@code NO}.
 * </p>
 */
public class Prob04 {

    /** Constant characters used throughout the program. */
    private static final char CHAR_X      = 'x';
    private static final char CHAR_O      = 'o';
    private static final char CHAR_DOT    = '.';
    private static final char CHAR_Y      = 'y';   // legacy marker kept for compatibility

    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            int size = Integer.parseInt(scanner.nextLine().trim());
            char[][] board   = readBoard(scanner, size);
            char[][] canvas  = createResultCanvas(size);
            boolean allXCovered = process(board, canvas);

            if (!allXCovered) {
                System.out.println("NO");
                return;
            }

            System.out.println("YES");
            printCanvas(canvas);
        }
    }

    /** Reads the {@code n} rows of the board from {@code scanner}. */
    private static char[][] readBoard(Scanner scanner, int n) {
        char[][] board = new char[n][n];
        for (int i = 0; i < n; i++) {
            board[i] = scanner.nextLine().toCharArray();
        }
        return board;
    }

    /** Creates the result canvas filled with 'x' and puts an 'o' at its centre. */
    private static char[][] createResultCanvas(int n) {
        char[][] canvas = new char[2 * n - 1][2 * n - 1];
        fillWith(canvas, CHAR_X);
        canvas[n - 1][n - 1] = CHAR_O;
        return canvas;
    }

    /**
     * Main processing routine.
     *
     * @return {@code true} if every 'x' in {@code board} gets covered,
     *         {@code false} otherwise.
     */
    private static boolean process(char[][] board, char[][] canvas) {
        // Positions of all 'o' cells in the input board
        List<int[]> oPositions = collectPositions(board, CHAR_O);

        // Tracks whether each 'x' has been covered by at least one spread
        boolean[][] xCovered = new boolean[board.length][board[0].length];

        for (int[] o : oPositions) {
            int oi = o[0];
            int oj = o[1];

            /* Step 1 – spread '.' symbols.
               For each '.' in the original board we write a '.' into the canvas
               at the offset {@code (n‑1 + p‑i, n‑1 + q‑j)}. */
            for (int p = 0; p < board.length; p++) {
                for (int q = 0; q < board[p].length; q++) {
                    if (board[p][q] == CHAR_DOT) {
                        int targetRow = (board.length - 1) + p - oi;
                        int targetCol = (board.length - 1) + q - oj;
                        if (inBounds(canvas, targetRow, targetCol)) {
                            canvas[targetRow][targetCol] = CHAR_DOT;
                        }
                    }
                }
            }

            /* Step 2 – mark x‑cells that become covered.
               An 'x' cell is considered covered if, after the spread,
               the corresponding canvas cell is still the original 'x'. */
            for (int p = 0; p < board.length; p++) {
                for (int q = 0; q < board[p].length; q++) {
                    if (board[p][q] == CHAR_X) {
                        int targetRow = (board.length - 1) + p - oi;
                        int targetCol = (board.length - 1) + q - oj;
                        if (inBounds(canvas, targetRow, targetCol)
                                && canvas[targetRow][targetCol] == CHAR_X) {
                            xCovered[p][q] = true;
                        }
                    }
                }
            }
        }

        /* Verify that every 'x' was covered.
           The original program also replaced covered x's with 'y' for its
           internal state; we keep that side‑effect for completeness. */
        boolean anyUncoveredX = false;
        for (int i = 0; i < board.length; i++) {
            for (int j = 0; j < board[i].length; j++) {
                if (board[i][j] == CHAR_X && !xCovered[i][j]) {
                    anyUncoveredX = true;
                }
                if (board[i][j] == CHAR_X && xCovered[i][j]) {
                    board[i][j] = CHAR_Y;   // legacy marker, not used for output
                }
            }
        }
        return !anyUncoveredX;
    }

    /** Collects the coordinates of all cells equal to {@code target}. */
    private static List<int[]> collectPositions(char[][] board, char target) {
        List<int[]> positions = new ArrayList<>();
        int n = board.length;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (board[i][j] == target) {
                    positions.add(new int[]{i, j});
                }
            }
        }
        return positions;
    }

    /** Checks whether a row/column index lies inside the given canvas. */
    private static boolean inBounds(char[][] canvas, int row, int col) {
        return row >= 0 && row < canvas.length
                && col >= 0 && col < canvas[row].length;
    }

    /** Fills a 2‑dimensional array with the supplied value. */
    private static void fillWith(char[][] array, char value) {
        Arrays.fill(array, value);
    }

    /** Prints the content of the canvas line by line. */
    private static void printCanvas(char[][] canvas) {
        for (char[] row : canvas) {
            System.out.println(new String(row));
        }
    }
}

import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.util.ArrayDeque;
import java.util.Arrays;
import java.util.Deque;

/**
 * Reads a grid together with start / end coordinates,
 * then determines whether a path exists that satisfies the
 * problem’s special condition.
 *
 * The algorithm uses an explicit stack (DFS) and a small
 * helper that counts “relevant” sides of a cell.
 */
public class Solution {

    /** Grid size */
    private int rows;
    private int cols;

    /** Grid content */
    private char[][] grid;

    /** Start and target positions (0‑based) */
    private int startRow, startCol;
    private int targetRow, targetCol;

    /** Directions: down, up, right, left */
    private static final int[][] DIRS = {
            {1, 0},   // down
            {-1, 0},  // up
            {0, 1},   // right
            {0, -1}   // left
    };

    /** Simple container for row/col coordinates */
    private static final class Position {
        final int row;
        final int col;

        Position(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }

    /**
     * Main entry point – reads input, runs the search and prints the result.
     *
     * @throws Exception if an I/O error occurs
     */
    public void calc() throws Exception {
        // Try‑with‑resources guarantees the reader is closed.
        try (BufferedReader br = new BufferedReader(
                new InputStreamReader(System.in))) {

            // ----- read dimensions -------------------------------------------------
            String[] dims = br.readLine().split("\\s+");
            rows = Integer.parseInt(dims[0]);
            cols = Integer.parseInt(dims[1]);

            // ----- read grid -------------------------------------------------------
            grid = new char[rows][];
            for (int r = 0; r < rows; r++) {
                String line = br.readLine();
                grid[r] = line.toCharArray();
            }

            // ----- read start / target ---------------------------------------------
            startRow = parseInt(br.readLine().split("\\s+")[0]) - 1;
            startCol = parseInt(br.readLine().split("\\s+")[0]) - 1;
            targetRow = parseInt(br.readLine().split("\\s+")[0]) - 1;
            targetCol = parseInt(br.readLine().split("\\s+")[0]) - 1;

            // ----- run search -------------------------------------------------------
            boolean reachable = findPath();

            // ----- output -----------------------------------------------------------
            System.out.println(reachable ? "YES" : "NO");
        }
    }

    /**
     * Parses a single integer from a token array (used for convenience).
     */
    private static int parseInt(String s) {
        return Integer.parseInt(s);
    }

    /**
     * Depth‑first search using an explicit stack.  The search obeys the
     * original movement rules:
     * <ul>
     *   <li> '.' cells are always traversable,
     *   <li> an 'X' cell is only traversable when it is the target cell.
     * </ul>
     *
     * @return {@code true} if a path satisfying the special condition exists
     */
    private boolean findPath() {
        boolean[][] visited = new boolean[rows][];
        for (int r = 0; r < rows; r++) {
            visited[r] = new boolean[cols];
            Arrays.fill(visited[r], false);
        }

        Deque<Position> stack = new ArrayDeque<>();
        Position start = new Position(startRow, startCol);
        stack.push(start);
        visited[start.row][start.col] = true;

        while (!stack.isEmpty()) {
            Position cur = stack.pop();

            // If we reached the target, check the special condition.
            if (cur.row == targetRow && cur.col == targetCol) {
                if (countRelevantNeighbors(startRow, startCol, cur.row, cur.col) > 1) {
                    return true;
                }
            }

            // Explore neighbours.
            for (int[] dir : DIRS) {
                int nr = cur.row + dir[0];
                int nc = cur.col + dir[1];

                if (!isInside(nr, nc)) {
                    continue;
                }
                if (visited[nr][nc]) {
                    continue;
                }
                char cell = grid[nr][nc];
                boolean isTarget = (nr == targetRow && nc == targetCol);
                boolean canEnter = (cell == '.' || (cell == 'X' && isTarget));

                if (canEnter) {
                    visited[nr][nc] = true;
                    stack.push(new Position(nr, nc));
                }
            }
        }
        return false;
    }

    /**
     * Counts the number of “relevant” sides of the target cell.
     * The counting logic mirrors the original {@code res(...)} method:
     * <ul>
     *   <li>the target cell itself contributes 1 if it contains 'X',
     *   <li>each of the four orthogonal neighbours contributes 1
     *       when it is either '.' or it is the start cell.
     * </ul>
     *
     * @return the computed count
     */
    private int countRelevantNeighbors(int startY, int startX,
                                       int targetY, int targetX) {
        int count = 0;

        // The cell itself
        if (grid[targetY][targetX] == 'X') {
            count++;
        }

        // Helper to test a neighbour position
        for (int[] dir : DIRS) {
            int nr = targetY + dir[0];
            int nc = targetX + dir[1];
            if (!isInside(nr, nc)) {
                continue;
            }
            char neighbour = grid[nr][nc];
            boolean isStartNeighbour = (nr == startY && nc == startX);
            if (neighbour == '.' || isStartNeighbour) {
                count++;
            }
        }
        return count;
    }

    /** Checks whether a coordinate lies inside the grid. */
    private boolean isInside(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    /** ------------------------------------------------------------------------- */

    public static void main(String[] args) throws Exception {
        new Solution().calc();
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

/**
 * Refactored solution for the original {@code TaskA} problem.
 * The program reads a grid, a start cell and a target cell,
 * then determines whether the target can be reached under the
 * problem's special “cracking” rules.
 */
public class TaskA {

    /** Character that represents a free (unblocked) cell. */
    private static final char FREE = '.';

    /** Character that represents a blocked cell. */
    private static final char BLOCKED = '#';

    /** Grid of characters read from input. */
    private static char[][] grid;

    /** Marks cells that have already been visited during DFS. */
    private static boolean[][] visited;

    /** Number of rows and columns in the grid. */
    private static int rows, cols;

    /** Directions: right, down, up, left. */
    private static final int[][] DIRECTIONS = {
            {0, 1},   // right
            {1, 0},   // down
            {-1, 0},  // up
            {0, -1}   // left
    };

    /** Row and column of the start cell (0‑based). */
    private static int startRow, startCol;

    /** Row and column of the target cell (0‑based). */
    private static int targetRow, targetCol;

    /** Flag set when the target cell is discovered during DFS. */
    private static boolean targetReached = false;

    /** --------------------------------------------------------------------- */
    /** Core DFS that explores reachable free cells. */
    private static void dfs(int r, int c) {
        visited[r][c] = true;

        for (int[] dir : DIRECTIONS) {
            if (targetReached) {
                return;
            }

            int nr = r + dir[0];
            int nc = c + dir[1];

            // If the neighbour is the target, we are done.
            if (nr == targetRow && nc == targetCol) {
                targetReached = true;
                return;
            }

            // Continue exploring if the cell is inside the grid,
            // not yet visited and is a free cell.
            if (isInBounds(nr, nc)
                    && !visited[nr][nc]
                    && grid[nr][nc] == FREE) {
                dfs(nr, nc);
            }
        }
    }

    /** Checks whether a coordinate lies inside the grid. */
    private static boolean isInBounds(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    /** Determines whether two cells are orthogonally adjacent. */
    private static boolean areAdjacent(int r1, int c1, int r2, int c2) {
        int dr = Math.abs(r1 - r2);
        int dc = Math.abs(c1 - c2);
        return (dr == 1 && dc == 0) || (dr == 0 && dc == 1);
    }

    /** Counts how many orthogonal neighbours of (r,c) are free cells. */
    private static int countFreeNeighbours(int r, int c) {
        int count = 0;
        for (int[] dir : DIRECTIONS) {
            int nr = r + dir[0];
            int nc = c + dir[1];
            if (isInBounds(nr, nc) && grid[nr][nc] == FREE) {
                count++;
            }
        }
        return count;
    }

    /** --------------------------------------------------------------------- */
    /** Reads the whole input and solves the problem. */
    public static void main(String[] args) throws IOException {
        // ----- Input ---------------------------------------------------------
        try (BufferedReader br = new BufferedReader(
                new InputStreamReader(System.in))) {

            StringTokenizer st = new StringTokenizer(br.readLine());
            rows = Integer.parseInt(st.nextToken());
            cols = Integer.parseInt(st.nextToken());

            grid = new char[rows][cols];
            visited = new boolean[rows][cols];

            // Read the grid itself
            for (int i = 0; i < rows; i++) {
                String line = br.readLine();
                for (int j = 0; j < cols; j++) {
                    grid[i][j] = line.charAt(j);
                }
            }

            // Read the start and target coordinates (1‑based in the input)
            startRow = Integer.parseInt(st.nextToken()) - 1;
            startCol = Integer.parseInt(st.nextToken()) - 1;
            targetRow = Integer.parseInt(st.nextToken()) - 1;
            targetCol = Integer.parseInt(st.nextToken()) - 1;

            // ----- Pre‑computations -------------------------------------------
            boolean originallyBlocked = grid[targetRow][targetCol] == BLOCKED;
            int freeNeighboursAtTarget = countFreeNeighbours(targetRow, targetCol);

            // ----- Depth‑first search -----------------------------------------
            dfs(startRow, startCol);

            // ----- Decision making --------------------------------------------
            if (!targetReached) {
                System.out.println("NO");
                return;
            }

            boolean condition = originallyBlocked
                    || (areAdjacent(startRow, startCol, targetRow, targetCol)
                        && freeNeighboursAtTarget >= 1)
                    || freeNeighboursAtTarget >= 2;

            System.out.println(condition ? "YES" : "NO");
        }
    }
}

import java.io.IOException;
import java.util.Scanner;

/**
 * Refactored solution for the “reachability” problem.
 * <p>
 * The program reads a rectangular board, a start cell and a target cell,
 * then decides whether the target can be reached from the start respecting
 * the original algorithm’s rules.
 */
public final class Solver {

    /** 4‑directional movement vectors (right, down, left, up). */
    private enum Direction {
        RIGHT(0, 1),
        DOWN(1, 0),
        LEFT(0, -1),
        UP(-1, 0);

        final int dr;
        final int dc;

        Direction(int dr, int dc) {
            this.dr = dr;
            this.dc = dc;
        }
    }

    /** Symbols used on the board. */
    private static final char EMPTY = '.';
    private static final char BLOCKED = 'X';

    /** Simple immutable coordinate holder. */
    private static final class Coordinate {
        final int row;
        final int col;

        Coordinate(int row, int col) {
            this.row = row;
            this.col = col;
        }

        /** Equality check – useful when start == target. */
        boolean equals(Coordinate other) {
            return row == other.row && col == other.col;
        }
    }

    /** Board dimensions and the board itself. */
    private int rows;
    private int cols;
    private char[][] board;

    /** Entry point. */
    public static void main(String[] args) {
        new Solver().solve();
    }

    /** Orchestrates the whole workflow. */
    private void solve() {
        try (Scanner in = new Scanner(System.in)) {
            readBoard(in);
            Coordinate start = readCoordinate(in, true);
            Coordinate target = readCoordinate(in, true);

            if (start.equals(target)) {
                handleStartEqualsTarget(in, start);
                return;
            }

            boolean[][] visited = initializeVisited();
            floodFill(start.row, start.col, visited);

            if (!visited[target.row][target.col]) {
                System.out.println("NO");
                return;
            }

            boolean targetIsEmpty = board[target.row][target.col] == EMPTY;
            int adjacentFree = countAdjacentFree(target);

            if (targetIsEmpty && adjacentFree <= 1) {
                System.out.println("NO");
            } else {
                System.out.println("YES");
            }
        }
    }

    /** Reads the board dimensions and the board rows. */
    private void readBoard(Scanner in) {
        String[] dims = in.nextLine().split("\\s+");
        rows = Integer.parseInt(dims[0]);
        cols = Integer.parseInt(dims[1]);

        board = new char[rows][];
        for (int r = 0; r < rows; r++) {
            board[r] = in.nextLine().toCharArray();
        }
    }

    /** Reads a 1‑based coordinate and converts it to 0‑based. */
    private Coordinate readCoordinate(Scanner in, boolean zeroBasedExpected) {
        int r = in.nextInt() - 1;
        int c = in.nextInt() - 1;
        if (!zeroBasedExpected) {
            throw new IllegalStateException("Coordinates are expected to be 0‑based after decrement");
        }
        return new Coordinate(r, c);
    }

    /** Handles the special case where start and target are the same cell. */
    private void handleStartEqualsTarget(Scanner in, Coordinate coord) {
        int adjacentFree = countAdjacentFree(coord);
        System.out.println(adjacentFree > 0 ? "YES" : "NO");
    }

    /** Marks all blocked cells as visited so they are ignored during flood‑fill. */
    private boolean[][] initializeVisited() {
        boolean[][] visited = new boolean[rows][cols];
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (board[r][c] == BLOCKED) {
                    visited[r][c] = true;
                }
            }
        }
        // The target cell is *not* considered blocked for traversal.
        // It will be set to false later in the caller.
        return visited;
    }

    /** Depth‑first flood‑fill from (sr, sc). */
    private void floodFill(int sr, int sc, boolean[][] visited) {
        visited[sr][sc] = true;
        for (Direction d : Direction.values()) {
            int nr = sr + d.dr;
            int nc = sc + d.dc;
            if (isInside(nr, nc) && !visited[nr][nc]) {
                floodFill(nr, nc, visited);
            }
        }
    }

    /** Simple bounds check. */
    private boolean isInside(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    /**
     * Counts the neighbours of {@code p} that are either empty ('.')
     * or equal to the start cell (used only when start == target).
     */
    private int countAdjacentFree(Coordinate p) {
        int count = 0;
        for (Direction d : Direction.values()) {
            int nr = p.row + d.dr;
            int nc = p.col + d.dc;
            if (isInside(nr, nc)) {
                char ch = board[nr][nc];
                if (ch == EMPTY || (nr == startRow && nc == startCol)) {
                    count++;
                }
            }
        }
        return count;
    }

    /** Row/column of the start cell – needed only for the legacy neighbour test. */
    private int startRow;
    private int startCol;

    /** Called from {@code handleStartEqualsTarget} to capture the start coordinates. */
    void captureStartCoordinate(Coordinate coord) {
        this.startRow = coord.row;
        this.startCol = coord.col;
    }
}

import java.util.ArrayDeque;
import java.util.Deque;
import java.util.Scanner;

/**
 * Main class that reads a grid, performs a breadth‑first search from a start
 * cell to a target cell and prints whether the target is reachable.
 *
 * The algorithm and output exactly match the original version, but the
 * implementation has been refactored for readability, maintainability and
 * adherence to Java best practices.
 */
public class C2 {

    /* --------------------------------------------------------------------- */
    /*  Constants & helper data structures                                      */
    /* --------------------------------------------------------------------- */

    /** Movement offsets: right, down, up, left */
    private static final int[] DX = {1, 0, 0, -1};
    private static final int[] DY = {0, 1, -1, 0};

    /** Cells with value 0 are considered blocked; any positive value is walkable */
    private static final class Position {
        final int row;
        final int col;

        Position(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }

    /* --------------------------------------------------------------------- */
    /*  Instance fields (all are immutable after construction)                */
    /* --------------------------------------------------------------------- */
    private final int rows;
    private final int cols;
    private final char[][] grid;          // original character map
    private final int[][] visited;        // integer visitation map
    private final int startRow, startCol;
    private final int targetRow, targetCol;

    /* --------------------------------------------------------------------- */
    /*  Construction & entry point                                              */
    /* --------------------------------------------------------------------- */

    public static void main(String[] args) {
        new C2().run();
    }

    /** Orchestrates input reading, processing and output. */
    private void run() {
        readInput();
        boolean reachable = solve();
        printAnswer(reachable);
    }

    /* --------------------------------------------------------------------- */
    /*  Input handling                                                         */
    /* --------------------------------------------------------------------- */

    /** Reads everything from {@code System.in} and prepares internal structures. */
    private void readInput() {
        Scanner sc = new Scanner(System.in);

        // 1️⃣ grid dimensions
        rows = sc.nextInt();
        cols = sc.nextInt();

        // 2️⃣ the grid itself (characters)
        grid = new char[rows][cols];
        for (int r = 0; r < rows; r++) {
            String line = sc.next();
            for (int c = 0; c < cols; c++) {
                grid[r][c] = line.charAt(c);
            }
        }

        // 3️⃣ visited matrix (2 = original '.' , 1 = original '#')
        visited = new int[rows][cols];
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                visited[r][c] = (grid[r][c] == '.') ? 2 : 1;
            }
        }

        // 4️⃣ start and target coordinates (1‑based in input → 0‑based internally)
        startRow = sc.nextInt() - 1;
        startCol = sc.nextInt() - 1;
        targetRow = sc.nextInt() - 1;
        targetCol = sc.nextInt() - 1;
    }

    /* --------------------------------------------------------------------- */
    /*  Core algorithm – BFS                                                    */
    /* --------------------------------------------------------------------- */

    /**
     * Executes a breadth‑first search from {@code startRow,startCol} to the
     * target cell. Returns {@code true} iff the target is reachable and its
     * visitation value equals {@code 1} (mirroring the original condition).
     */
    private boolean solve() {
        Deque<Position> queue = new ArrayDeque<>();
        queue.add(new Position(startRow, startCol));
        visited[startRow][startCol] = 2;          // mark as visited (same as original)

        while (!queue.isEmpty()) {
            Position cur = queue.poll();

            // Success condition: we are at the target and it is of type 1
            if (cur.row == targetRow && cur.col == targetCol && visited[cur.row][cur.col] == 1) {
                return true;
            }

            // Original code skips processing if the cell's value is 1 (treated as wall)
            if (visited[cur.row][cur.col] == 1) {
                continue;
            }

            // Decrement the cell's counter (mirrors original behaviour)
            visited[cur.row][cur.col]--;

            // Explore the four neighbours
            for (int dir = 0; dir < 4; dir++) {
                int nr = cur.row + DY[dir];
                int nc = cur.col + DX[dir];

                if (isInside(nr, nc)) {
                    queue.add(new Position(nr, nc));
                }
            }
        }
        return false;
    }

    /* --------------------------------------------------------------------- */
    /*  Helper utilities                                                       */
    /* --------------------------------------------------------------------- */

    /** Checks whether a given cell lies inside the grid bounds. */
    private boolean isInside(int r, int c) {
        return 0 <= r && r < rows && 0 <= c && c < cols;
    }

    /** Prints "YES" if the target is reachable, otherwise "NO". */
    private void printAnswer(boolean reachable) {
        System.out.println(reachable ? "YES" : "NO");
    }
}

import java.io.*;
import java.util.*;

public class CF540C {

    /** Directions used for neighbour exploration. */
    private static final int[][] NEIGHBOURS = {
            { -1, 0 }, { 1, 0 }, { 0, -1 }, { 0, 1 }
    };

    /** Fast input scanner. */
    private static final class FastScanner {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        FastScanner() {
            this.reader = new BufferedReader(new InputStreamReader(System.in));
        }

        /** Returns the next token or reads a new line if needed. */
        private String nextToken() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                tokenizer = new StringTokenizer(reader.readLine());
            }
            return tokenizer.nextToken();
        }

        /** Convenience method for reading an int. */
        int nextInt() throws IOException {
            return Integer.parseInt(nextToken());
        }

        /** Close the underlying stream. */
        void close() throws IOException {
            reader.close();
        }
    }

    /** Entry point of the program. */
    public static void main(String[] args) throws Exception {
        try (FastScanner fs = new FastScanner()) {
            int rows = fs.nextInt();
            int cols = fs.nextInt();

            boolean[][] grid = readGrid(fs, rows, cols);

            // read source and destination positions (1‑based input)
            int srcRow = fs.nextInt() - 1;
            int srcCol = fs.nextInt() - 1;
            int dstRow = fs.nextInt() - 1;
            int dstCol = fs.nextInt() - 1;

            boolean reachable = findPath(grid, srcRow, srcCol, dstRow, dstCol);
            int adjacentBlankCount = countAdjacentBlanks(dstRow, dstCol, grid);

            boolean answer = reachable && (
                    !grid[dstRow][dstCol] ||
                    adjacentBlankCount >= 2 ||
                    (srcRow == dstRow && srcCol == dstCol && adjacentBlankCount >= 1)
            );

            System.out.println(answer ? "YES" : "NO");
        }
    }

    /** Reads the matrix of '.' / '#' characters and converts it to a boolean grid. */
    private static boolean[][] readGrid(FastScanner fs, int rows, int cols) throws IOException {
        boolean[][] grid = new boolean[rows][cols];
        String[] lineTokens = fs.nextToken().split("");
        for (int i = 0; i < rows; i++) {
            String[] chars = lineTokens[i].split("");
            for (int j = 0; j < cols; j++) {
                grid[i][j] = chars[j].equals(".");
            }
        }
        // consume the remaining lines containing the coordinates
        fs.nextInt(); // source row
        fs.nextInt(); // source col
        fs.nextInt(); // destination row
        fs.nextInt(); // destination col
        return grid;
    }

    /** Determines whether a path exists from (sr, sc) to (dr, dc). */
    private static boolean findPath(boolean[][] grid,
                                    int sr, int sc,
                                    int dr, int dc) {
        boolean[][] visited = new boolean[grid.length][grid[0].length];
        // Use an explicit stack to avoid deep recursion.
        Deque<int[]> stack = new ArrayDeque<>();
        stack.push(new int[]{sr, sc});
        visited[sr][sc] = true;

        while (!stack.isEmpty()) {
            int[] cur = stack.pop();
            int r = cur[0];
            int c = cur[1];

            if (r == dr && c == dc) {
                return true;
            }

            for (int[] dir : NEIGHBOURS) {
                int nr = r + dir[0];
                int nc = c + dir[1];
                if (isWithinBounds(nr, nc, grid) && !visited[nr][nc] && grid[nr][nc]) {
                    visited[nr][nc] = true;
                    stack.push(new int[]{nr, nc});
                }
            }
        }
        return false;
    }

    /** Helper that checks whether a cell coordinate is inside the grid. */
    private static boolean isWithinBounds(int row, int col, boolean[][] grid) {
        return row >= 0 && row < grid.length &&
               col >= 0 && col < grid[0].length;
    }

    /** Counts how many of the four orthogonal neighbours of (r,c) are blank ('.'). */
    private static int countAdjacentBlanks(int r, int c, boolean[][] grid) {
        int count = 0;
        for (int[] dir : NEIGHBOURS) {
            int nr = r + dir[0];
            int nc = c + dir[1];
            if (isWithinBounds(nr, nc, grid) && grid[nr][nc]) {
                count++;
            }
        }
        return count;
    }
}

import java.io.*;
import java.util.ArrayDeque;
import java.util.Deque;

/**
 * Solution for the “marked cells” problem.
 * Reads a grid, performs a BFS from a start cell and checks whether the
 * finish cell can be reached under certain conditions.
 */
public class Main {

    /** Fast scanner that buffers input for better performance. */
    private static final class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner(InputStream source) {
            br = new BufferedReader(new InputStreamReader(source), 32768);
        }

        /** Ensure a non‑empty tokeniser; throws IOException if the stream ends. */
        private void ensureReady() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                st = new StringTokenizer(br.readLine());
            }
        }

        /** Return next token as a {@code String}. */
        String nextString() {
            ensureReady();
            return st.nextToken();
        }

        /** Convenience wrappers for primitive types. */
        int nextInt() { return Integer.parseInt(nextString()); }
        long nextLong() { return Long.parseLong(nextString()); }
        double nextDouble() { return Double.parseDouble(nextString()); }
    }

    /** Directions used during the breadth‑first search. */
    private static final int[] DX = {-1, 1, 0, 0};
    private static final int[] DY = {0, 0, -1, 1};

    /** Simple container for a grid coordinate. */
    private static final class Cell {
        final int row, col;
        Cell(int row, int col) { this.row = row; this.col = col; }
    }

    /** Entry point – delegates all work to {@link #solve(FastScanner, PrintWriter)}. */
    public static void main(String[] args) throws IOException {
        // Using try‑with‑resources guarantees that streams are closed.
        try (InputStream in = System.in;
             OutputStream out = System.out) {

            FastScanner scanner = new FastScanner(in);
            PrintWriter writer = new PrintWriter(out);

            solve(scanner, writer);
            writer.flush();               // ensure all output is flushed
        }
    }

    /** Core algorithm: read input, BFS, evaluate answer, write result. */
    private static void solve(FastScanner in, PrintWriter out) {
        int n = in.nextInt();          // number of rows
        int m = in.nextInt();          // number of columns

        // Grid with a 1‑cell border of walls (value = false) simplifies neighbour checks.
        boolean[][] grid = new boolean[n + 2][m + 2];
        for (int i = 1; i <= n; i++) {
            String line = in.next();
            for (int j = 1; j <= m; j++) {
                grid[i][j] = line.charAt(j - 1) == '.';
            }
        }

        // Coordinates are 1‑based according to the original specification.
        int startX = in.nextInt();
        int startY = in.nextInt();
        int finishX = in.nextInt();
        int finishY = in.nextInt();

        boolean[][] visited = new boolean[n + 2][m + 2];
        bfs(grid, startX, startY, visited);

        // If the finish cell is a wall, success is possible only via an adjacent visited cell.
        if (!grid[finishX][finishY]) {
            if (visited[finishX - 1][finishY] ||
                visited[finishX + 1][finishY] ||
                visited[finishX][finishY - 1] ||
                visited[finishX][finishY + 1]) {
                out.println("YES");
            } else {
                out.println("NO");
            }
            return;
        }

        // Otherwise count how many neighbours of the finish cell were visited.
        int adjacentVisited = 0;
        for (int d = 0; d < 4; d++) {
            int nx = finishX + DX[d];
            int ny = finishY + DY[d];
            if (visited[nx][ny]) {
                adjacentVisited++;
            }
        }
        out.println(adjacentVisited >= 2 ? "YES" : "NO");
    }

    /**
     * Breadth‑first search that marks all reachable cells starting from (srcX, srcY).
     *
     * @param grid   the traversable map (true = free cell)
     * @param srcX   starting row (1‑based)
     * @param srcY   starting column (1‑based)
     * @param visited output matrix that will be filled with {@code true} for visited cells
     */
    private static void bfs(boolean[][] grid, int srcX, int srcY, boolean[][] visited) {
        Deque<Cell> queue = new ArrayDeque<>();
        queue.addLast(new Cell(srcX, srcY));

        while (!queue.isEmpty()) {
            Cell cur = queue.pollFirst();
            int x = cur.row;
            int y = cur.col;

            if (visited[x][y]) {
                continue;               // already processed
            }
            visited[x][y] = true;

            // Explore the four orthogonal neighbours.
            for (int dir = 0; dir < 4; dir++) {
                int nx = x + DX[dir];
                int ny = y + DY[dir];
                if (grid[nx][ny]) {       // neighbour is walkable
                    queue.addLast(new Cell(nx, ny));
                }
            }
        }
    }
}

import java.util.ArrayDeque;
import java.util.Arrays;
import java.util.Deque;
import java.util.Scanner;

/**
 * Main class that solves a maze‑reachability problem.
 * <p>
 * The program reads a grid, start and goal coordinates, and determines
 * whether the goal can be reached from the start using a breadth‑first
 * search.  Special‑case handling for isolated goal cells has been kept
 * but moved into dedicated helper methods to improve readability.
 */
public class Main {

    /** Directions: right, down, left, up */
    private static final int[][] DIRECTIONS = {
            {0, 1}, {1, 0}, {0, -1}, {-1, 0}
    };

    /** Size of the padded grid (outer layer of walls) */
    private static final char WALL = 'X';
    private static final char EMPTY = '.';

    /** Input data */
    private static char[][] board;   // padded board
    private static int rows;        // actual height (excluding padding)
    private static int cols;        // actual width  (excluding padding)
    private static int[] start;     // {row, col} of start
    private static int[] goal;      // {row, col} of goal

    public static void main(String[] args) {
        parseInput();
        if (goalIsUnreachableTrivially()) {
            return;
        }
        if (bfsCanReachGoal()) {
            System.out.println("YES");
        } else {
            System.out.println("NO");
        }
    }

    /** --------------------------------------------------------------
     *  Input handling – keeps the {@code main} method tidy.
     *  -------------------------------------------------------------- */
    private static void parseInput() {
        try (Scanner sc = new Scanner(System.in)) {
            int H = sc.nextInt();      // number of rows inside the board
            int W = sc.nextInt();      // number of columns inside the board

            rows = H;
            cols = W;

            // Build a board surrounded by a wall of ‘X’
            board = new char[H + 2][];
            board[0] = new char[W + 2];
            board[H + 1] = new char[W + 2];
            Arrays.fill(board[0], WALL);
            Arrays.fill(board[H + 1], WALL);
            for (int r = 1; r <= H; r++) {
                String line = "X" + sc.next() + "X";
                board[r] = line.toCharArray();
            }

            // Read start and goal coordinates (1‑based indexing in input)
            start = readTwoCoordinates(sc);
            goal = readTwoCoordinates(sc);
        }
    }

    /** Reads two integer pairs from the given scanner. */
    private static int[] readTwoCoordinates(Scanner sc) {
        int[] coord = new int[2];
        for (int i = 0; i < 2; i++) {
            coord[i] = sc.nextInt();
        }
        return coord;
    }

    /** --------------------------------------------------------------
     *  Special‑case handling that mirrors the original code's early exits.
     *  -------------------------------------------------------------- */
    private static void maybePrintAndReturn(String message) {
        System.out.println(message);
        System.exit(0);
    }

    /** Replicates the original early‑exit logic surrounding a blocked goal. */
    private static boolean goalIsUnreachableTrivially() {
        if (board[goal[0]][goal[1]] == WALL) {
            // If start and goal are adjacent, the answer is immediately YES.
            if (areAdjacent(start, goal)) {
                maybePrintAndReturn("YES");
            }

            // Goal must have at least one empty neighbour to be reachable.
            for (int[] d : DIRECTIONS) {
                int nr = goal[0] + d[0];
                int nc = goal[1] + d[1];
                if (board[nr][nc] == EMPTY) {
                    maybePrintAndReturn("YES");
                }
            }
            // No empty neighbour → unreachable.
            maybePrintAndReturn("NO");
        }

        // Goal is currently empty – count how many empty neighbours it has.
        int emptyNeighbourCount = countEmptyNeighbours(goal);
        if (areAdjacent(start, goal) && emptyNeighbourCount >= 1) {
            maybePrintAndReturn("YES");
        }
        if (emptyNeighbourCount < 2) {
            maybePrintAndReturn("NO");
        }
        return false; // continue normal BFS
    }

    /** Returns true if two points are neighbours (Manhattan distance == 1). */
    private static boolean areAdjacent(int[] a, int[] b) {
        return Math.abs(a[0] - b[0]) + Math.abs(a[1] - b[1]) == 1;
    }

    /** Counts empty ('.') cells among the four neighbours of a point. */
    private static int countEmptyNeighbours(int[] point) {
        int count = 0;
        for (int[] d : DIRECTIONS) {
            int nr = point[0] + d[0];
            int nc = point[1] + d[1];
            if (board[nr][nc] == EMPTY) {
                count++;
            }
        }
        return count;
    }

    /** --------------------------------------------------------------
     *  Breadth‑first search – returns true as soon as the goal is reached.
     *  -------------------------------------------------------------- */
    private static boolean bfsCanReachGoal() {
        boolean[][] visited = new boolean[rows + 2][cols + 2];
        Deque<int[]> queue = new ArrayDeque<>();
        queue.add(new int[]{start[0], start[1]});
        visited[start[0]][start[1]] = true;

        while (!queue.isEmpty()) {
            int[] cur = queue.poll();

            for (int[] d : DIRECTIONS) {
                int nr = cur[0] + d[0];
                int nc = cur[1] + d[1];

                // Goal reached?
                if (nr == goal[0] && nc == goal[1]) {
                    maybePrintAndReturn("YES");
                }

                // Skip walls and already visited cells.
                if (board[nr][nc] == WALL || visited[nr][nc]) {
                    continue;
                }

                queue.add(new int[]{nr, nc});
                visited[nr][nc] = true;
            }
        }
        // Exhausted search without finding the goal.
        maybePrintAndReturn("NO");
    }
}

import java.io.*;
import java.util.*;

public class Main {

    /* --------------------------------------------------------------------- */
    /*  Constants and direction vectors                                      */
    /* --------------------------------------------------------------------- */
    private static final char FREE = '.';
    private static final char WALL = '#';

    private static final int[] DX = {0, 0, 1, -1};
    private static final int[] DY = {1, -1, 0, 0};

    /* --------------------------------------------------------------------- */
    /*  Instance fields                                                        */
    /* --------------------------------------------------------------------- */
    private int rows;
    private int cols;
    private boolean[][] free;          // cell is traversable?
    private boolean[][] visited;       // used by DFS (re‑uses `free` as marker)
    private int startX, startY;        // source cell
    private int targetX, targetY;      // destination cell

    /* --------------------------------------------------------------------- */
    /*  Entry point                                                            */
    /* --------------------------------------------------------------------- */
    public static void main(String[] args) throws IOException {
        // The original program used a custom FastScanner; we keep the same behaviour.
        try (FastScanner scanner = new FastScanner(System.in);
             PrintWriter out = new PrintWriter(System.out)) {

            new Main().solve(scanner, out);
        }
    }

    /* --------------------------------------------------------------------- */
    /*  Solving routine                                                        */
    /* --------------------------------------------------------------------- */
    private void solve(FastScanner in, PrintWriter out) {
        readInput(in);
        locateStartAndTarget();

        // remember whether the target cell was originally traversable
        boolean targetWasOriginallyFree = free[targetX][targetY];

        // The algorithm always marks the start and target as traversable.
        // (The original code set them to `true` even if they already were.)
        free[startX][startY] = true;
        free[targetX][targetY] = true;

        // Number of free neighbours of the target cell after it has been marked.
        int freeAdjacentToTarget = countFreeAdjacent(targetX, targetY);

        // -----------------------------------------------------------------
        //  Special case: start == target – we only need at least one free neighbour.
        // -----------------------------------------------------------------
        if (startX == targetX && startY == targetY) {
            out.println(freeAdjacentToTarget >= 1 ? "YES" : "NO");
            return;
        }

        // -----------------------------------------------------------------
        //  Normal case – does a path from the start exist?
        // -----------------------------------------------------------------
        boolean reachable = dfs(startX, startY);

        // Decision logic reproduced from the original source:
        //   (reachable && targetWasOriginallyFree) || (reachable && freeAdjacentToTarget > 1)
        boolean answer = reachable && (targetWasOriginallyFree || freeAdjacentToTarget > 1);
        out.println(answer ? "YES" : "NO");
    }

    /* --------------------------------------------------------------------- */
    /*  Input handling                                                         */
    /* --------------------------------------------------------------------- */
    private void readInput(FastScanner in) {
        rows = in.nextInt();
        cols = in.nextInt();

        free = new boolean[rows][];
        for (int i = 0; i < rows; i++) {
            String line = in.next();
            char[] chars = line.toCharArray();
            free[i] = new boolean[cols];
            for (int j = 0; j < cols; j++) {
                free[i][j] = (chars[j] == FREE);
            }
        }
    }

    private void locateStartAndTarget() {
        startX = in.nextInt() - 1;
        startY = in.nextInt() - 1;
        targetX = in.nextInt() - 1;
        targetY = in.nextInt() - 1;
    }

    /* --------------------------------------------------------------------- */
    /*  Depth‑First Search – returns true iff the target can be reached       */
    /* --------------------------------------------------------------------- */
    private boolean dfs(int x, int y) {
        if (!inBounds(x, y) || !free[x][y]) {
            return false;
        }
        // Mark the cell as visited by clearing the boolean (re‑using `free`).
        free[x][y] = false;
        if (x == targetX && y == targetY) {
            return true;
        }
        for (int d = 0; d < 4; d++) {
            if (dfs(x + DX[d], y + DY[d])) {
                return true;
            }
        }
        return false;
    }

    /* --------------------------------------------------------------------- */
    /*  Helper utilities                                                       */
    /* --------------------------------------------------------------------- */
    private boolean inBounds(int x, int y) {
        return x >= 0 && y >= 0 && x < rows && y < cols;
    }

    /** Counts how many orthogonal neighbours of (x, y) are currently free. */
    private int countFreeAdjacent(int x, int y) {
        int cnt = 0;
        for (int d = 0; d < 4; d++) {
            int nx = x + DX[d];
            int ny = y + DY[d];
            if (inBounds(nx, ny) && free[nx][ny]) {
                cnt++;
            }
        }
        return cnt;
    }

    /* --------------------------------------------------------------------- */
    /*  Simple fast scanner – mirrors the original FastScanner implementation */
    /* --------------------------------------------------------------------- */
    static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner(InputStream source) {
            br = new BufferedReader(new InputStreamReader(source));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    throw new UncheckedIOException(e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.io.*;
import java.util.*;

public class IceCave {

    /** Directions: up, down, left, right */
    private static final int[][] DIRS = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};

    /* --------------------------  Core fields  -------------------------- */
    private static char[][] grid;
    private static boolean[][] visited;
    private static int rows, cols;
    private static int startR, startC, endR, endC;

    /* --------------------------  IO wrapper  -------------------------- */
    /** Simple fast scanner/printer that implements AutoCloseable */
    private static class FastScanner extends PrintWriter implements AutoCloseable {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner() {
            super(System.out);
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        private String nextToken() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                st = new StringTokenizer(br.readLine());
            }
            return st.nextToken();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(nextToken());
        }

        void close() throws IOException {
            br.close();
            super.close();
        }
    }

    /* --------------------------  BFS/DFS logic  -------------------------- */
    /** Marks all cells reachable from (r,c) using an explicit stack (iterative DFS). */
    private static void floodFill(int startR, int startC) {
        Deque<int[]> stack = new ArrayDeque<>();
        stack.push(new int[]{startR, startC});
        visited[startR][startC] = true;

        while (!stack.isEmpty()) {
            int[] cur = stack.pop();
            int r = cur[0];
            int c = cur[1];

            // Destination cell is always allowed, even if it is an 'X' block
            if (r == endR && c == endC) {
                continue;
            }

            if (!inBounds(r, c) || visited[r][c] || grid[r][c] == 'X') {
                continue;
            }

            visited[r][c] = true;
            for (int[] dir : DIRS) {
                stack.push(new int[]{r + dir[0], c + dir[1]});
            }
        }
    }

    private static boolean inBounds(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    /** Counts how many of the four neighbours of (r,c) have been visited. */
    private static int countVisitedNeighbors(int r, int c) {
        int count = 0;
        for (int[] dir : DIRS) {
            int nr = r + dir[0];
            int nc = c + dir[1];
            if (inBounds(nr, nc) && visited[nr][nc]) {
                count++;
            }
        }
        return count;
    }

    /* --------------------------  Main algorithm  -------------------------- */
    public static void main(String[] args) throws Exception {
        try (FastScanner io = new FastScanner()) {
            rows = io.nextInt();
            cols = io.nextInt();

            grid = new char[rows][cols];
            for (int i = 0; i < rows; i++) {
                String line = io.next();
                System.arraycopy(line.toCharArray(), 0, grid[i], 0, cols);
            }

            // Convert to 0‑based coordinates
            startR = io.nextInt() - 1;
            startC = io.nextInt() - 1;
            endR   = io.nextInt() - 1;
            endC   = io.nextInt() - 1;

            visited = new boolean[rows][cols];

            // Start cell is always traversable
            grid[startR][startC] = '.';
            floodFill(startR, startC);

            String answer = "NO";

            if (visited[endR][endC]) {
                if (startR == endR && startC == endC) {
                    // Need at least one adjacent visited cell to leave and re‑enter
                    if (countVisitedNeighbors(endR, endC) >= 1) {
                        answer = "YES";
                    }
                } else if (grid[endR][endC] == 'X') {
                    // Destination is an ice block that can be broken
                    answer = "YES";
                } else {
                    // Need at least two distinct ways to reach the destination
                    if (countVisitedNeighbors(endR, endC) >= 2) {
                        answer = "YES";
                    }
                }
            }

            System.out.println(answer);
        }
    }
}

import java.io.*;
import java.util.*;

public class Main {

    /** Directions: up, down, left, right */
    private static final int[][] DIRS = { { -1, 0 }, { 1, 0 }, { 0, -1 }, { 0, 1 } };

    /** Simple immutable position holder */
    private static final class Position {
        final int row, col;

        Position(int row, int col) {
            this.row = row;
            this.col = col;
        }

        @Override public boolean equals(Object o) {
            if (this == o) return true;
            if (!(o instanceof Position)) return false;
            Position p = (Position) o;
            return row == p.row && col == p.col;
        }

        @Override public int hashCode() {
            return Objects.hash(row, col);
        }

        @Override public String toString() {
            return "(" + row + "," + col + ")";
        }
    }

    /** Entry point */
    public static void main(String[] args) throws IOException {
        new Main().solve();
    }

    /** Solves the problem */
    private void solve() throws IOException {
        // read dimensions
        int[] dims = readInts();
        int n = dims[0];
        int m = dims[1];

        // read grid
        char[][] grid = new char[n][];
        for (int i = 0; i < n; i++) {
            grid[i] = readLine().toCharArray();
        }

        // read source and destination coordinates (1‑based)
        int[] srcArr = readInts();
        int[] dstArr = readInts();

        Position src = new Position(srcArr[0] - 1, srcArr[1] - 1);
        Position dst = new Position(dstArr[0] - 1, dstArr[1] - 1);

        // count empty ('.') neighbours of the destination
        int emptyNeighbours = 0;
        for (int[] d : DIRS) {
            int nr = dst.row + d[0];
            int nc = dst.col + d[1];
            if (inBounds(nr, nc) && grid[nr][nc] == '.') {
                emptyNeighbours++;
            }
        }

        // are src and dst orthogonally adjacent?
        boolean adjacent = (Math.abs(src.row - dst.row) == 1 && src.col == dst.col) ||
                           (Math.abs(src.col - dst.col) == 1 && src.row == dst.row);

        boolean answer;

        // same cell
        if (src.equals(dst)) {
            answer = emptyNeighbours > 0;
        }
        // destination is an empty cell
        else if (grid[dst.row][dst.col] == '.') {
            if (emptyNeighbours == 0) {
                answer = false;
            } else {
                // exactly one empty neighbour, it must be src, and src must be blocked ('X')
                answer = emptyNeighbours == 1 && adjacent && grid[src.row][src.col] == 'X';
            }
        }
        // destination is blocked ('X')
        else {
            answer = bfsCanReach(src, dst, grid);
        }

        out(answer ? "YES" : "NO");
    }

    /** Returns true if `dst` can be reached from `src` moving only on '.' cells
     *  (the destination cell itself is allowed regardless of its content). */
    private boolean bfsCanReach(Position src, Position dst, char[][] grid) {
        int n = grid.length;
        int m = grid[0].length;
        boolean[][] visited = new boolean[n][m];
        Queue<Position> q = new ArrayDeque<>();

        q.add(src);
        visited[src.row][src.col] = true;

        while (!q.isEmpty()) {
            Position cur = q.poll();
            if (cur.equals(dst)) {
                return true;
            }

            for (int[] d : DIRS) {
                int nr = cur.row + d[0];
                int nc = cur.col + d[1];
                if (!inBounds(nr, nc)) continue;
                if (visited[nr][nc]) continue;

                // we may step on '.' cells or directly onto the destination cell
                if (grid[nr][nc] == '.' || (nr == dst.row && nc == dst.col)) {
                    visited[nr][nc] = true;
                    q.add(new Position(nr, nc));
                }
            }
        }
        return false;
    }

    /** Checks board bounds. */
    private boolean inBounds(int r, int c) {
        return r >= 0 && r < grid.length && c >= 0 && c < grid[0].length;
    }

    /** Reads a line of whitespace‑separated integers. */
    private static int[] readInts() throws IOException {
        String line = IN.readLine();
        String[] parts = line.trim().split("\\s+");
        int[] arr = new int[parts.length];
        for (int i = 0; i < parts.length; i++) {
            arr[i] = Integer.parseInt(parts[i]);
        }
        return arr;
    }

    /** Reads the next line (used for grid rows). */
    private static String readLine() throws IOException {
        return IN.readLine();
    }

    /** Shortcut for printing a line. */
    private static void out(Object o) {
        System.out.println(o);
    }
}

import java.util.Scanner;

/**
 * Ice Cave – refactored for readability, maintainability and correctness.
 *
 * <p>
 *   The program reads an {@code n × m} grid where {@code 'X'} denotes a cracked cell.
 *   Starting from a given cell {@code (r1,c1)} it determines whether the
 *   destination cell {@code (r2,c2)} can be reached.
 *   If the destination itself is cracked, it is reachable only when it has at
 *   least one orthogonal neighbour that is not cracked.
 * </p>
 */
public class IceCave {

    /* --------------------------  Fields  -------------------------- */

    private static int rows, cols;                     // grid dimensions
    private static boolean[][] grid;                    // true → cracked ('X')
    private static boolean[][] visited;                 // tracks visited cells
    private static int startRow, startCol;              // start coordinates
    private static int targetRow, targetCol;            // target coordinates

    /** Four orthogonal directions used for neighbour checks. */
    private static final int[][] DIRECTIONS = {
            {-1, 0}, {1, 0}, {0, -1}, {0, 1}
    };

    /* ---------------------------  Main  --------------------------- */

    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            readDimensions(scanner);
            readGrid(scanner);
            readStartAndTarget(scanner);

            // The start cell is treated as “uncracked” for the search.
            grid[startRow][startCol] = false;

            boolean reachable = dfs(startRow, startCol);
            System.out.println(reachable ? "YES" : "NO");
        }
    }

    /* ---------------------------  Input  -------------------------- */

    private static void readDimensions(Scanner sc) {
        rows = sc.nextInt();
        cols = sc.nextInt();
    }

    private static void readGrid(Scanner sc) {
        grid = new boolean[rows][cols];
        visited = new boolean[rows][cols];

        for (int r = 0; r < rows; r++) {
            String line = sc.next();
            for (int c = 0; c < cols; c++) {
                grid[r][c] = line.charAt(c) == 'X';   // true = cracked
            }
        }
    }

    private static void readStartAndTarget(Scanner sc) {
        startRow = sc.nextInt() - 1;
        startCol = sc.nextInt() - 1;
        targetRow = sc.nextInt() - 1;
        targetCol = sc.nextInt() - 1;
    }

    /* ---------------------------  DFS  ---------------------------- */

    /**
     * Depth‑first search that returns {@code true} if the target can be reached
     * from the current position.
     */
    private static boolean dfs(int r, int c) {
        // Boundary checks, cracked cells and already visited cells are impassable.
        if (!isInside(r, c) || grid[r][c] || visited[r][c]) {
            return false;
        }

        // Destination reached.
        if (r == targetRow && c == targetCol) {
            // If the destination itself is cracked, it can only be stepped on
            // when it has at least one adjacent non‑cracked neighbour.
            if (grid[r][c]) {
                return hasAdjacentlyUncracked(r, c);
            }
            return true;
        }

        visited[r][c] = true;

        // Explore neighbours in a deterministic order.
        for (int[] dir : DIRECTIONS) {
            int nr = r + dir[0];
            int nc = c + dir[1];
            if (dfs(nr, nc)) {
                return true;
            }
        }

        // Backtrack – this path did not lead to the target.
        visited[r][c] = false;
        return false;
    }

    /**
     * Checks whether the cell {@code (r,c)} has at least one orthogonal neighbour
     * that is not cracked. Used when the target cell itself is cracked.
     */
    private static boolean hasAdjacentlyUncracked(int r, int c) {
        for (int[] dir : DIRECTIONS) {
            int nr = r + dir[0];
            int nc = c + dir[1];
            if (isInside(nr, nc) && !grid[nr][nc]) {
                return true;
            }
        }
        return false;
    }

    /** Utility method to test whether a coordinate lies inside the grid. */
    private static boolean isInside(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }
}

import java.io.FileNotFoundException;
import java.util.Scanner;

/**
 * Finds whether there is a path from a starting cell to an exit cell
 * in a rectangular maze that consists of open cells ('.') and walls ('#').
 *
 * <p>This implementation is deliberately kept simple and highly readable,
 * while avoiding global mutable state and respecting Java naming conventions.
 */
public class IceCaveSolver {

    /** Directions: right, down, left, up */
    private static final int[][] DIRECTIONS = {
            {0, 1},
            {1, 0},
            {0, -1},
            {-1, 0}
    };

    /** The internal representation of the maze. */
    private final char[][] grid;

    /** Marks visited cells during the depth‑first search. */
    private final boolean[][] visited;

    /** Entry point of the program. */
    public static void main(String[] args) throws FileNotFoundException {
        try (Scanner scanner = new Scanner(System.in)) {
            solve(scanner);
        }
    }

    /**
     * Reads the maze description from {@code scanner}, performs the search,
     * and prints {@code YES} if the exit can be reached, otherwise {@code NO}.
     */
    private static void solve(Scanner scanner) {
        int rows = scanner.nextInt();
        int cols = scanner.nextInt();

        // Allocate the grid with a border of walls to simplify edge handling.
        char[][] grid = new char[rows + 2][cols + 2];
        boolean[][] visited = new boolean[rows + 2][cols + 2];

        // Fill the inner area with the characters from the input.
        scanner.nextLine(); // consume end‑of‑line after reading rows/cols
        for (int r = 1; r <= rows; r++) {
            String line = scanner.nextLine();
            for (int c = 1; c <= cols; c++) {
                grid[r][c] = line.charAt(c - 1);
            }
        }

        int startR = scanner.nextInt();
        int startC = scanner.nextInt();
        int exitR = scanner.nextInt();
        int exitC = scanner.nextInt();

        IceCaveSolver solver = new IceCaveSolver(grid, visited);
        boolean reachable = solver.canReachExit(startR, startC, exitR, exitC);

        System.out.println(reachable ? "YES" : "NO");
    }

    /** Constructor – stores the maze and the visited array. */
    IceCaveSolver(char[][] grid, boolean[][] visited) {
        this.grid = grid;
        this.visited = visited;
    }

    /**
     * Depth‑first search that returns {@code true} when a path from the
     * starting cell to the exit cell exists.
     *
     * @param sr start row (1‑based as read from input)
     * @param sc start column (1‑based as read from input)
     * @param er exit row (1‑based as read from input)
     * @param ec exit column (1‑based as read from input)
     * @return {@code true} if the exit can be reached, {@code false} otherwise
     */
    boolean canReachExit(int sr, int sc, int er, int ec) {
        // The cell is considered visited as soon as we step into it.
        visited[sr][sc] = true;
        grid[sr][sc] = 'X'; // legacy marker used by the original code

        for (int[] dir : DIRECTIONS) {
            int nr = sr + dir[0];
            int nc = sc + dir[1];

            // Direct success when we step onto the exit cell.
            if (nr == er && nc == ec && visited[er][ec]) {
                return true;
            }

            // Continue only through open, unvisited cells.
            if (grid[nr][nc] == '.' && !visited[nr][nc]) {
                if (canReachExit(nr, nc, er, ec)) {
                    return true;
                }
            }
        }
        return false;
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.ArrayDeque;
import java.util.Queue;

/**
 * Main class of the program.
 * <p>
 * The program reads a grid, a start cell and a target cell.
 * It decides whether the target can be reached from the start under
 * the following rules:
 * <ul>
 *   <li>The target cell is either an obstacle ('X') or is “surrounded”
 *       (has at least two empty neighbouring cells, where an extra
 *       count is added if the start cell is adjacent and contains an
 *       obstacle).</li>
 *   <li>There exists a path from the start to the target moving only
 *       through empty cells ('.') or directly stepping on the target.</li>
 * </ul>
 */
public class Main {

    /** Direction vectors: right, left, down, up */
    private static final int[][] DIRS = {{0, 1}, {0, -1}, {1, 0}, {-1, 0}};

    private static int rows, cols;
    private static char[][] grid;
    private static boolean[][] visited;
    private static final int START_R = -1, START_C = -1, END_R = -1, END_C = -1;

    /** Reads the whole input and solves the problem. */
    public static void main(String[] args) throws Exception {
        try (PrintWriter out = new PrintWriter(System.out)) {
            readInput();
            solveAndPrintResult();
        }
    }

    /** --------------------------------------------------------------------- */
    /**  Input handling                                                       */
    /** --------------------------------------------------------------------- */
    private static void readInput() throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));

        String[] firstLine = br.readLine().split("\\s+");
        rows = Integer.parseInt(firstLine[0]);
        cols = Integer.parseInt(firstLine[1]);

        grid = new char[rows][];
        for (int r = 0; r < rows; r++) {
            grid[r] = br.readLine().trim().toCharArray();
        }

        // start and target are given 1‑based in the original statement
        int sR = Integer.parseInt(br.readLine()) - 1;
        int sC = Integer.parseInt(br.readLine()) - 1;
        int tR = Integer.parseInt(br.readLine()) - 1;
        int tC = Integer.parseInt(br.readLine()) - 1;

        START_R = sR;
        START_C = sC;
        // store target coordinates locally for the rest of the algorithm
        int endR = tR;
        int endC = tC;

        solve(sR, sC, endR, endC);
    }

    /** --------------------------------------------------------------------- */
    /**  Core solving logic                                                   */
    /** --------------------------------------------------------------------- */
    private static void solve(int sr, int sc, int tr, int tc) {
        // same start and target cell – special case
        if (sr == tr && sc == tc) {
            out.println(hasAtLeastOneEmptyNeighbour(sr, sc) ? "YES" : "NO");
            return;
        }

        boolean targetIsObstacleOrSurrounded = isTargetObstacleOrSurrounded(tr, tc);
        boolean reachable = canReach(sr, sc, tr, tc);

        out.println((targetIsObstacleOrSurrounded && reachable) ? "YES" : "NO");
    }

    /** --------------------------------------------------------------------- */
    /**  Helper methods                                                         */
    /** --------------------------------------------------------------------- */

    /** Checks whether a cell (r,c) lies inside the grid. */
    private static boolean inside(int r, int c) {
        return r >= 0 && c >= 0 && r < rows && c < cols;
    }

    /** Counts empty ('.') neighbours of (r,c). */
    private static int countEmptyNeighbours(int r, int c) {
        int emptyCnt = 0;
        for (int[] d : DIRS) {
            int nr = r + d[0];
            int nc = c + d[1];
            if (inside(nr, nc) && grid[nr][nc] == '.') {
                emptyCnt++;
            }
        }
        return emptyCnt;
    }

    /**
     * Returns true if the cell contains an obstacle ('X') or is “surrounded”.
     * The definition of “surrounded” used here matches the original code:
     * <ul>
     *   <li>At least two neighbouring cells are empty,</li>
     *   <li>If the neighbour coincides with the start cell and that start cell
     *       holds an 'X', it contributes one extra count.</li>
     * </ul>
     */
    private static boolean isTargetObstacleOrSurrounded(int r, int c) {
        if (grid[r][c] == 'X') {
            return true;
        }

        int emptyNeighbours = countEmptyNeighbours(r, c);
        // original code adds one extra count when the adjacent neighbour is the start cell
        for (int[] d : DIRS) {
            int nr = r + d[0];
            int nc = c + d[1];
            if (nr == START_R && nc == START_C && grid[nr][nc] == 'X') {
                emptyNeighbours++;          // counts the start cell as an extra empty neighbour
            }
        }
        return emptyNeighbours >= 2;
    }

    /**
     * Returns true if the cell has at least one empty neighbour.
     * Used only for the “same start‑target” case of the original program.
     */
    private static boolean hasAtLeastOneEmptyNeighbour(int r, int c) {
        return countEmptyNeighbours(r, c) >= 1;
    }

    /**
     * Breadth‑first search from (sr,sc) to (tr,tc).
     * The search may step on the target even if it is an obstacle,
     * exactly as the original recursive implementation allowed.
     */
    private static boolean canReach(int sr, int sc, int tr, int tc) {
        if (!inside(sr, sc)) {
            return false;
        }

        visited = new boolean[rows][cols];
        Queue<int[]> queue = new ArrayDeque<>();
        queue.add(new int[]{sr, sc});
        visited[sr][sc] = true;

        while (!queue.isEmpty()) {
            int[] cur = queue.poll();
            int r = cur[0];
            int c = cur[1];

            if (r == tr && c == tc) {
                return true;
            }

            for (int[] d : DIRS) {
                int nr = r + d[0];
                int nc = c + d[1];
                if (!inside(nr, nc) || visited[nr][nc]) {
                    continue;
                }

                // we can move to an empty cell or directly onto the target cell
                if ((nr == tr && nc == tc) || grid[nr][nc] != 'X') {
                    visited[nr][nc] = true;
                    queue.add(new int[]{nr, nc});
                }
            }
        }
        return false;
    }
}

import java.io.PrintWriter;
import java.util.Scanner;
import java.util.EnumSet;

/**
 * Refactored solution for the Ice Cave problem.
 *
 * <p>Reads a grid where '.' denotes a safe cell and '#' an obstacle.
 * Determines whether the destination can be reached from the start cell
 * according to the problem rules and prints "YES" or "NO".
 */
public class IceCave {

    /** Four possible movement directions. */
    private enum Direction {
        UP(0, -1),
        DOWN(0, 1),
        LEFT(-1, 0),
        RIGHT(1, 0);

        final int dr;
        final int dc;

        Direction(int dr, int dc) {
            this.dr = dr;
            this.dc = dc;
        }
    }

    /** Simple wrapper around {@link Scanner} that can be closed. */
    private static final class InputReader implements AutoCloseable {
        private final Scanner scanner;

        InputReader(Scanner scanner) {
            this.scanner = scanner;
        }

        /** Reads the next token (grid row string). */
        String nextToken() {
            return scanner.next();
        }

        /** Reads the next integer. */
        int nextInt() {
            return scanner.nextInt();
        }

        /** Consumes the rest of the current line. */
        void nextLine() {
            scanner.nextLine();
        }

        @Override
        public void close() {
            scanner.close();
        }
    }

    /** Print writer used for output. */
    private final PrintWriter out;

    /** Grid where 1 = safe ('.'), 0 = obstacle ('#'). */
    private int[][] grid;

    /** Grid dimensions. */
    private int rows, cols;

    /** Start and target coordinates (zero‑based). */
    private int startRow, startCol, endRow, endCol;

    /** Constructor that receives the output stream. */
    public IceCave(PrintWriter out) {
        this.out = out;
    }

    /** Program entry point. */
    public static void main(String[] args) {
        try (PrintWriter writer = new PrintWriter(System.out);
             InputReader reader = new InputReader(new Scanner(System.in))) {
            new IceCave(writer).solve(reader);
        } catch (Exception e) {
            e.printStackTrace();
        }
    }

    /** Main solving routine. */
    public void solve(InputReader in) {
        readInput(in);
        if (areCoordinatesEqual(startRow, startCol, endRow, endCol)) {
            handleStartEqualsTarget();
            return;
        }

        boolean[][] visited = new boolean[rows][cols];
        if (depthFirstSearch(startRow, startCol, visited)) {
            // If the target cell was originally safe we can finish directly.
            if (grid[endRow][endCol] == 0) {
                out.println("YES");
                return;
            }
            // Count distinct safe neighbours that lead into the target.
            int entryCount = 0;
            for (Direction d : Direction.values()) {
                int nr = endRow + d.dr;
                int nc = endCol + d.dc;
                if (inBounds(nr, nc) && (visited[nr][nc] || grid[nr][nc] == 1)) {
                    entryCount++;
                }
            }
            if (entryCount >= 2) {
                out.println("YES");
                return;
            }
        }
        out.println("NO");
    }

    /** Reads and parses the input data. */
    private void readInput(InputReader in) {
        rows = in.nextInt();
        cols = in.nextInt();
        grid = new int[rows][cols];

        // The token after the dimensions is the first row string.
        in.nextLine(); // consume remaining newline

        for (int r = 0; r < rows; r++) {
            String line = in.nextToken();
            for (int c = 0; c < cols; c++) {
                grid[r][c] = (line.charAt(c) == '.') ? 1 : 0;
            }
        }

        startRow = in.nextInt() - 1;
        startCol = in.nextInt() - 1;
        endRow   = in.nextInt() - 1;
        endCol   = in.nextInt() - 1;
    }

    /** Returns true when start and target cells are the same. */
    private boolean areCoordinatesEqual(int r1, int c1, int r2, int c2) {
        return r1 == r2 && c1 == c2;
    }

    /** Handles the special case where start == target. */
    private void handleStartEqualsTarget() {
        boolean reachable = false;
        for (Direction d : Direction.values()) {
            int nr = endRow + d.dr;
            int nc = endCol + d.dc;
            if (inBounds(nr, nc) && isSafe(nr, nc)) {
                reachable = true;
                break;
            }
        }
        out.println(reachable ? "YES" : "NO");
    }

    /** Recursive depth‑first search that attempts to reach the target. */
    private boolean depthFirstSearch(int r, int c, boolean[][] visited) {
        if (!inBounds(r, c) || !isSafe(r, c) || visited[r][c]) {
            return false;
        }
        visited[r][c] = true;
        grid[r][c] = 0; // mark visited

        for (Direction d : Direction.values()) {
            int nr = r + d.dr;
            int nc = c + d.dc;
            if (nr == endRow && nc == endCol) {
                return true;
            }
            if (depthFirstSearch(nr, nc, visited)) {
                return true;
            }
        }
        return false;
    }

    /** Checks if a coordinate lies inside the grid. */
    private boolean inBounds(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    /** Returns true if the cell at (r, c) is marked as safe. */
    private boolean isSafe(int r, int c) {
        return grid[r][c] == 1;
    }
}

import java.io.*;
import java.util.*;

/**
 * Solves problem "C – Checkpoints" (contest style).
 *
 * <p>Refactored for readability, maintainability and proper resource handling.
 */
public class Main {

    /** Entry point of the program. */
    public static void main(String[] args) throws IOException {
        try (InputStream input = System.in;
             OutputStream output = System.out) {

            InputReader reader = new InputReader(input);
            PrintWriter writer = new PrintWriter(output);

            // Test case index is unused – keep argument for compatibility with original signature.
            new Solver().solve(1, reader, writer);

            writer.flush();
        }
    }

    /** Core logic for a single test case. */
    private static class Solver {

        /** Directions used for movement (up, down, left, right). */
        private static final int[][] DIRECTIONS = {
                {0, -1},   // up
                {0, 1},    // down
                {-1, 0},   // left
                {1, 0}     // right
        };

        /** 505×505 board – size matches original constraints. */
        private char[][] board;
        private int rows, cols;

        /** Marks visited cells during BFS. */
        private boolean[][] visited;

        /** Determines if the target checkpoint is reachable under the problem rules. */
        public void solve(int testId, InputReader reader, PrintWriter out) {
            readInput(reader);
            int startRow = reader.nextInt() - 1;
            int startCol = reader.nextInt() - 1;
            int targetRow = reader.nextInt() - 1;
            int targetCol = reader.nextInt() - 1;

            boolean reachable = bfs(startRow, startCol, targetRow, targetCol);
            out.println(reachable ? "YES" : "NO");
        }

        /** Reads the board and checkpoint coordinates from the input stream. */
        private void readInput(InputReader reader) {
            rows = reader.nextInt();
            cols = reader.nextInt();

            board = new char[rows][];
            visited = new boolean[rows][cols];

            for (int i = 0; i < rows; i++) {
                String line = reader.nextLine();
                board[i] = line.toCharArray();
            }
        }

        /** Breadth‑first search that respects the movement rules. */
        private boolean bfs(int sr, int sc, int tr, int tc) {
            Deque<int[]> queue = new ArrayDeque<>();
            queue.addLast(new int[]{sr, sc});
            visited[sr][sc] = true;

            while (!queue.isEmpty()) {
                int[] cur = queue.removeFirst();
                int r = cur[0];
                int c = cur[1];

                // Goal reached?
                if (r == tr && c == tc) {
                    return board[r][c] == 'X';
                }

                for (int[][] dir : DIRECTIONS) {
                    int nr = r + dir[0];
                    int nc = c + dir[1];

                    if (!inBounds(nr, nc) || visited[nr][nc]) {
                        continue;
                    }

                    char cell = board[nr][nc];
                    if (cell == '.') {
                        queue.addLast(new int[]{nr, nc});
                        visited[nr][nc] = true;
                    } else if (cell == 'X') {
                        // Direct step onto the target when it is blocked.
                        if (nr == tr && nc == tc) {
                            return true;
                        }
                        // Treat other blocked cells as impassable.
                    } else if (cell == 'S') {
                        // Count adjacent free cells (or special cells) to decide if we may step onto it.
                        int adjacentFree = countAdjacentFreeOrSpecial(nr, nc);
                        if (adjacentFree >= 1) {
                            queue.addLast(new int[]{nr, nc});
                            visited[nr][nc] = true;
                        }
                    }
                }
            }
            return false;
        }

        /** Returns true if the cell at (r, c) is within the board limits. */
        private boolean inBounds(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }

        /**
         * Counts how many neighbours of (r, c) are either free ('.') or the start cell ('S').
         * This mimics the original heuristic that required at least one free neighbour
         * or two neighbours that are 'S'.
         */
        private int countAdjacentFreeOrSpecial(int r, int c) {
            int count = 0;
            for (int[][] dir : DIRECTIONS) {
                int nr = r + dir[0];
                int nc = c + dir[1];
                if (!inBounds(nr, nc)) {
                    continue;
                }
                char neighbor = board[nr][nc];
                if (neighbor == '.' || neighbor == 'S') {
                    count++;
                }
            }
            return count;
        }
    }

    /** Simple line‑oriented input reader compatible with the original API. */
    private static class InputReader {
        private final BufferedReader bufferedReader;

        InputReader(InputStream inputStream) {
            this.bufferedReader = new BufferedReader(
                    new InputStreamReader(inputStream));
        }

        /** Returns the next token separated by whitespace. */
        String next() {
            try {
                while (!tokenizer.hasMoreTokens()) {
                    String line = bufferedReader.readLine();
                    if (line == null) {
                        return null;
                    }
                    tokenizer = new StringTokenizer(line);
                }
            } catch (IOException e) {
                throw new RuntimeException(e);
            }
            return tokenizer.nextToken();
        }

        /** Returns the next line of input (or null on EOF). */
        String nextLine() {
            try {
                return bufferedReader.readLine();
            } catch (IOException e) {
                throw new RuntimeException(e);
            }
        }

        /** Convenience wrapper around {@code Integer.parseInt}. */
        int nextInt() {
            return Integer.parseInt(next());
        }

        /** Tokenizer reused across calls; lazily created when needed. */
        private StringTokenizer tokenizer = new StringTokenizer("");
    }
}

import java.util.Scanner;
import java.util.Stack;

/**
 * Utility class that checks whether a path exists between two points in a grid
 * and determines if the target cell has more than one adjacent walkable area.
 *
 * The main logic is split into small, self‑documenting methods to improve
 * readability, testability and maintainability.
 */
public class PathChecker {

    // Direction vectors: left, right, up, down
    private static final int[] DX = {0, 0, -1, 1};
    private static final int[] DY = {-1, 1, 0, 0};

    public static void main(String[] args) {
        // Try‑with‑resources ensures the scanner is closed automatically
        try (Scanner scanner = new Scanner(System.in)) {
            int rows = scanner.nextInt();
            int cols = scanner.nextInt();
            scanner.nextLine(); // consume the rest of the line

            char[][] grid = readGrid(scanner, rows, cols);

            int startRow = scanner.nextInt() - 1;
            int startCol = scanner.nextInt() - 1;
            int endRow   = scanner.nextInt() - 1;
            int endCol   = scanner.nextInt() - 1;

            if (!hasPath(grid, startRow, startCol, endRow, endCol)) {
                System.out.println("NO");
                return;
            }

            // If the destination cell itself is blocked, the answer is trivially YES
            if (grid[endRow][endCol] == 'X') {
                System.out.println("YES");
                return;
            }

            int adjacentWalkable = countAdjacentWalkable(grid, endRow, endCol,
                                                          startRow, startCol);
            System.out.println(adjacentWalkable > 1 ? "YES" : "NO");
        }
    }

    /** Reads `rows × cols` characters from the input and builds the grid. */
    private static char[][] readGrid(Scanner scanner, int rows, int cols) {
        char[][] grid = new char[rows][cols];
        for (int r = 0; r < rows; r++) {
            String line = scanner.nextLine().trim();
            for (int c = 0; c < cols; c++) {
                grid[r][c] = line.charAt(c);
            }
        }
        return grid;
    }

    /** Determines whether a path exists from (sr, sc) to (er, ec). */
    private static boolean hasPath(char[][] grid, int sr, int sc, int er, int ec) {
        boolean[][] visited = new boolean[grid.length][grid[0].length];
        Stack<int[]> stack = new Stack<>();
        stack.push(new int[]{sr, sc});
        visited[sr][sc] = true;

        while (!stack.isEmpty()) {
            int[] cur = stack.pop();
            if (cur[0] == er && cur[1] == ec) {
                return true; // Destination reached
            }

            for (int d = 0; d < DX.length; d++) {
                int nr = cur[0] + DX[d];
                int nc = cur[1] + DY[d];

                if (isInside(grid, nr, nc) && !visited[nr][nc] && grid[nr][nc] != 'X') {
                    visited[nr][nc] = true;
                    stack.push(new int[]{nr, nc});
                }
            }
        }
        return false;
    }

    /** Counts neighboring cells that are walkable ('.') or equal to the start cell. */
    private static int countAdjacentWalkable(char[][] grid,
                                            int row, int col,
                                            int startRow, int startCol) {
        int count = 0;
        for (int d = 0; d < DX.length; d++) {
            int nr = row + DX[d];
            int nc = col + DY[d];

            if (!isInside(grid, nr, nc)) {
                continue;
            }
            // Allow stepping back to the cell we came from
            if (nr == startRow && nc == startCol) {
                count++;
                continue;
            }
            if (grid[nr][nc] == '.') {
                count++;
            }
        }
        return count;
    }

    /** Helper that checks whether (r, c) lies inside the grid bounds. */
    private static boolean isInside(char[][] grid, int r, int c) {
        return r >= 0 && r < grid.length && c >= 0 && c < grid[0].length;
    }
}

import java.util.Arrays;
import java.util.Scanner;

/**
 * Refactored solution for the “rnd301_C” problem.
 *
 * <p>Key improvements:
 * <ul>
 *   <li>Clear separation of concerns: input handling, DFS traversal, bounds checking,
 *   and the main decision logic are isolated in dedicated methods.</li>
 *   <li>Descriptive variable and method names replace cryptic one‑letter identifiers.</li>
 *   <li>Magic numbers and manual neighbour checks are replaced by constant arrays.</li>
 *   <li>Visited cells are stored in a {@code boolean[][]} rather than an {@code int[][]}.</li>
 *   <li>Input reading is performed in a dedicated method that hides the 1‑based indexing
 *   details from the core algorithm.</li>
 * </ul>
 */
public class Main {

    // Directions: up, left, down, right
    private static final int[] DR = {-1, 0, 1, 0};
    private static final int[] DC = {0, -1, 0, 1};

    private static Scanner scanner;
    private static char[][] grid;          // maze representation (1‑based)
    private static boolean[][] visited;    // visited cells during DFS
    private static int rows, cols;         // dimensions of the maze

    public static void main(String[] args) {
        scanner = new Scanner(System.in);
        readInput();

        int startRow = scanner.nextInt();   // 1‑based coordinates of the start cell
        int startCol = scanner.nextInt();
        int endRow   = scanner.nextInt();   // 1‑based coordinates of the destination cell
        int endCol   = scanner.nextInt();

        if (grid[endRow][endCol] == 'X') {
            // Destination is a wall that must be broken – check adjacency to a reachable cell
            boolean adjacentVisited = reachableAdjacentTo(endRow, endCol);
            System.out.println(adjacentVisited ? "YES" : "NO");
        } else {
            // Destination is an empty cell; we may need to temporarily block a neighbour
            boolean reachableAfterBlocking = tryToReachByBlockingNeighbour(endRow, endCol);
            System.out.println(reachableAfterBlocking ? "YES" : "NO");
        }
    }

    /** Reads the maze dimensions and the maze itself from standard input. */
    private static void readInput() {
        rows = scanner.nextInt();
        cols = scanner.nextInt();
        scanner.nextLine(); // consume the line‑break after the two integers

        grid = new char[rows + 1][cols + 1];
        for (int r = 1; r <= rows; r++) {
            String line = scanner.nextLine();
            // Guard against malformed input – expect exactly 'cols' characters
            for (int c = 1; c <= cols; c++) {
                grid[r][c] = line.charAt(c - 1);
            }
        }
    }

    /** Determines whether any of the four neighbours of (r, c) have been visited. */
    private static boolean reachableAdjacentTo(int r, int c) {
        visited = new boolean[rows + 1][cols + 1];
        dfs(1, 1); // start DFS from the (original) start cell (treated as (1,1) in the problem)

        for (int dir = 0; dir < 4; dir++) {
            int nr = r + DR[dir];
            int nc = c + DC[dir];
            if (inBounds(nr, nc) && visited[nr][nc]) {
                return true; // at least one adjacent cell is reachable
            }
        }
        return false;
    }

    /** Tries each neighbour of (r, c) as a temporary wall and checks if (r, c) becomes reachable. */
    private static boolean tryToReachByBlockingNeighbour(int r, int c) {
        for (int dir = 0; dir < 4; dir++) {
            int nr = r + DR[dir];
            int nc = c + DC[dir];
            if (!inBounds(nr, nc) || grid[nr][nc] != '.') {
                continue; // only '.' cells can be turned into a temporary wall
            }

            char original = grid[nr][nc];
            grid[nr][nc] = 'X';                // block the neighbour

            visited = new boolean[rows + 1][cols + 1];
            dfs(1, 1);                         // explore again from the start

            grid[nr][nc] = original;           // restore the cell
            if (visited[r][c]) {
                return true;   // success – destination became reachable after blocking
            }
        }
        return false; // no suitable neighbour was found
    }

    /** Depth‑first search that marks all cells reachable from (startR, startC) via '.' cells. */
    private static void dfs(int startR, int startC) {
        if (!inBounds(startR, startC) || visited[startR][startC] || grid[startR][startC] == 'X') {
            return;
        }
        visited[startR][startC] = true;
        for (int i = 0; i < 4; i++) {
            dfs(startR + DR[i], startC + DC[i]);
        }
    }

    /** Helper that checks whether a coordinate lies inside the grid. */
    private static boolean inBounds(int r, int c) {
        return r >= 1 && r <= rows && c >= 1 && c <= cols;
    }
}

/**
 * Refactored version of the original program.
 *
 * <p>Key improvements:
 * <ul>
 *   <li>Extracted all I/O into a dedicated {@link InputReader}} class.
 *   <li>Used immutable {@link Point}} objects with proper {@code equals}/{@code hashCode}.
 *   <li>Replaced recursion and static mutable fields with an iterative BFS that returns a
 *       {@code boolean} result.
 *   <li>Removed magic numbers, added meaningful constant interfaces and Javadoc comments.
 *   <li>All variables are scoped locally, making the flow easier to follow.
 * </ul>
 *
 * The functional behaviour is unchanged – the program prints {@code YES} if the
 * required condition is satisfied, otherwise {@code NO}.
 */
public class Main {

    /** Directions used for neighbour exploration (up, down, left, right). */
    private static final int[][] DIRECTIONS = {
            {-1, 0}, {1, 0}, {0, -1}, {0, 1}
    };

    /** Simple immutable point used as a key for visited cells. */
    private static final class Point {
        final int row;
        final int col;

        Point(int row, int col) {
            this.row = row;
            this.col = col;
        }

        @Override
        public boolean equals(Object o) {
            if (this == o) return true;
            if (!(o instanceof Point)) return false;
            Point p = (Point) o;
            return row == p.row && col == p.col;
        }

        @Override
        public int hashCode() {
            return 31 * row + col;
        }
    }

    /** Holds the result of the BFS – whether the required condition was met. */
    private static final class BfsResult {
        final boolean satisfied;

        BfsResult(boolean satisfied) {
            this.satisfied = satisfied;
        }
    }

    /** Reads input from {@code System.in} and provides convenient token methods. */
    private static final class InputReader {
        private final BufferedReader br;
        private StringTokenizer st;

        InputReader() {
            this.br = new BufferedReader(new java.io.InputStreamReader(System.in));
        }

        /** Returns the next token, reading a new line if necessary. */
        private String nextToken() throws java.io.IOException {
            while (st == null || !st.hasMoreElements()) {
                st = new StringTokenizer(br.readLine());
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(nextToken());
        }

        /** Returns the whole current line (used for reading the grid rows). */
        String nextLine() throws java.io.IOException {
            String line = "";
            while (line.isEmpty()) {
                line = br.readLine();
            }
            return line;
        }
    }

    /** Executes a BFS from the start cell to the target cell and evaluates the condition. */
    private static BfsResult bfs(
            int startRow, int startCol,
            int targetRow, int targetCol,
            int n, int m, int[][] grid) {

        int manhattan = Math.abs(targetRow - startRow) + Math.abs(targetCol - startCol);
        boolean[][] visited = new boolean[n][m];
        java.util.Queue<Point> queue = new java.util.ArrayDeque<>();

        queue.add(new Point(startRow, startCol));
        visited[startRow][startCol] = true;

        while (!queue.isEmpty()) {
            Point cur = queue.poll();

            // -------------------------------------------------------------
            // Target reached – evaluate the special condition.
            // -------------------------------------------------------------
            if (cur.row == targetRow && cur.col == targetCol) {
                int emptyNeighbourCount = 0;
                for (int[] dir : DIRECTIONS) {
                    int nr = cur.row + dir[0];
                    int nc = cur.col + dir[1];
                    if (nr < 0 || nr >= n || nc < 0 || nc >= m) continue;
                    if (grid[nr][nc] == 0) emptyNeighbourCount++;
                }

                boolean satisfied;
                if (grid[cur.row][cur.col] == 1 && emptyNeighbourCount > 0) {
                    satisfied = true;
                } else if (grid[cur.row][cur.col] == 0 && emptyNeighbourCount > 1) {
                    satisfied = true;
                } else if (grid[cur.row][cur.col] == 1 && manhattan == 1) {
                    satisfied = true;
                } else if (manhattan == 1 && emptyNeighbourCount >= 1) {
                    satisfied = true;
                } else {
                    satisfied = false;
                }
                return new BfsResult(satisfied);
            }

            // -------------------------------------------------------------
            // Explore neighbours – we may step onto the target even if it
            // contains a value of 1, otherwise only onto empty cells (0).
            // -------------------------------------------------------------
            for (int[] dir : DIRECTIONS) {
                int nr = cur.row + dir[0];
                int nc = cur.col + dir[1];
                if (nr < 0 || nr >= n || nc < 0 || nc >= m) continue;

                if (nr == targetRow && nc == targetCol) {
                    // Target cell is reachable – no need to mark visited.
                    queue.add(new Point(nr, nc));
                    visited[nr][nc] = true; // prevents revisiting it later
                } else if (!visited[nr][nc] && grid[nr][nc] == 0) {
                    visited[nr][nc] = true;
                    queue.add(new Point(nr, nc));
                }
            }
        }
        // Should never reach here because the target is guaranteed to be reachable
        // in the original problem constraints.
        return new BfsResult(false);
    }

    /** Entry point – reads input, invokes the solver and prints the answer. */
    public static void main(String[] args) throws java.io.IOException {
        InputReader reader = new InputReader();
        java.io.PrintWriter out = new java.io.PrintWriter(
                new java.io.BufferedOutputStream(System.out));

        // ----- read dimensions -------------------------------------------------
        int n = reader.nextInt();
        int m = reader.nextInt();

        // ----- read the grid ---------------------------------------------------
        int[][] grid = new int[n][m];
        for (int i = 0; i < n; ++i) {
            String line = reader.nextLine();
            for (int j = 0; j < m; ++j) {
                char ch = line.charAt(j);
                grid[i][j] = ch == '.' ? 0 : 1;   // '.' → empty (0), anything else → filled (1)
            }
        }

        // ----- read start and target coordinates (1‑based in the original) -----
        int startRow = reader.nextInt() - 1;
        int startCol = reader.nextInt() - 1;
        int targetRow = reader.nextInt() - 1;
        int targetCol = reader.nextInt() - 1;

        // ----- run the solver -------------------------------------------------
        BfsResult result = bfs(
                startRow, startCol,
                targetRow, targetCol,
                n, m, grid);

        // ----- output -----------------------------------------------------------
        out.println(result.satisfied ? "YES" : "NO");
        out.close();
    }
}

import java.io.*;
import java.util.*;

/**
 * Refactored solution for Codeforces problem 301C.
 * The program determines whether a target cell can be reached under specific
 * movement rules on a grid.
 */
public class cf_301_c {

    /** Four possible movement directions: down, up, right, left. */
    private static final int[][] DIRECTIONS = {
            {1, 0}, {-1, 0}, {0, 1}, {0, -1}
    };

    private FastScanner scanner;
    private PrintWriter writer;

    public static void main(String[] args) {
        new cf_301_c().run();
    }

    /** Executes the whole program: reads input, processes it, prints the answer. */
    public void run() {
        try {
            scanner = new FastScanner();
            writer = new PrintWriter(System.out);
            solve();
            writer.flush();
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    /** Core logic that reads the grid and decides the answer. */
    public void solve() throws IOException {
        final int n = scanner.nextInt();
        final int m = scanner.nextInt();

        char[][] grid = readGrid(n, m);

        final int startR = scanner.nextInt() - 1;
        final int startC = scanner.nextInt() - 1;
        final int targetR = scanner.nextInt() - 1;
        final int targetC = scanner.nextInt() - 1;

        /* ------------------------------------------------------------------ */
        /* 1.  Start cell equals target cell                                   */
        /* ------------------------------------------------------------------ */
        if (startR == targetR && startC == targetC) {
            writer.println(hasIntactNeighbor(grid, targetR, targetC) ? "YES" : "NO");
            return;
        }

        /* ------------------------------------------------------------------ */
        /* 2.  Check adjacency and target state                               */
        /* ------------------------------------------------------------------ */
        boolean adjacent = isAdjacent(startR, startC, targetR, targetC);
        boolean targetIntact = grid[targetR][targetC] == '.';

        if (adjacent) {
            writer.println(targetIntact ? "YES" : "NO");
            return;
        }

        /* ------------------------------------------------------------------ */
        /* 3.  Attempt to reach the target via BFS                             */
        /* ------------------------------------------------------------------ */
        boolean reachable = bfsCanReachTarget(grid, startR, startC, targetR, targetC);
        if (!reachable) {
            writer.println("NO");
            return;
        }

        /* ------------------------------------------------------------------ */
        /* 4.  Final decision based on target cell state and intact neighbours */
        /* ------------------------------------------------------------------ */
        int intactNeighbors = countIntactNeighbors(grid, targetR, targetC);
        if (grid[targetR][targetC] == 'X') {
            writer.println("YES");
        } else {
            writer.println(intactNeighbors >= 2 ? "YES" : "NO");
        }
    }

    /** Reads an n × m grid from the scanner. */
    private char[][] readGrid(int n, int m) {
        char[][] grid = new char[n][m];
        for (int i = 0; i < n; i++) {
            String line = scanner.next();
            System.arraycopy(line.toCharArray(), 0, grid[i], 0, m);
        }
        return grid;
    }

    /** Returns true if the given cell has at least one intact ('.') neighbour. */
    private boolean hasIntactNeighbor(char[][] grid, int r, int c) {
        for (int[] d : DIRECTIONS) {
            int nr = r + d[0];
            int nc = c + d[1];
            if (isInRange(nr, nc, grid.length, grid[0].length) && grid[nr][nc] == '.') {
                return true;
            }
        }
        return false;
    }

    /** Determines whether two cells are directly adjacent. */
    private boolean isAdjacent(int r1, int c1, int r2, int c2) {
        for (int[] d : DIRECTIONS) {
            if (r1 + d[0] == r2 && c1 + d[1] == c2) {
                return true;
            }
        }
        return false;
    }

    /** Counts intact ('.') neighbours of a given cell. */
    private int countIntactNeighbors(char[][] grid, int r, int c) {
        int cnt = 0;
        for (int[] d : DIRECTIONS) {
            int nr = r + d[0];
            int nc = c + d[1];
            if (isInRange(nr, nc, grid.length, grid[0].length) && grid[nr][nc] == '.') {
                cnt++;
            }
        }
        return cnt;
    }

    /** Breadth‑first search that checks whether the target can be reached. */
    private boolean bfsCanReachTarget(char[][] grid,
                                      int sr, int sc,
                                      int tr, int tc) {
        final int rows = grid.length;
        final int cols = grid[0].length;
        boolean[][] visited = new boolean[rows][cols];
        Queue<int[]> queue = new ArrayDeque<>();
        queue.add(new int[]{sr, sc});
        visited[sr][sc] = true;

        while (!queue.isEmpty()) {
            int[] cur = queue.poll();
            int r = cur[0];
            int c = cur[1];

            for (int[] d : DIRECTIONS) {
                int nr = r + d[0];
                int nc = c + d[1];

                /* If stepping onto the target cell, a path exists. */
                if (nr == tr && nc == tc) {
                    return true;
                }

                if (isInRange(nr, nc, rows, cols)
                        && !visited[nr][nc]
                        && grid[nr][nc] == '.') {
                    visited[nr][nc] = true;
                    grid[nr][nc] = 'X';          // mark as visited
                    queue.add(new int[]{nr, nc});
                }
            }
        }
        return false;
    }

    /** Simple range check for grid coordinates. */
    private static boolean isInRange(int r, int c, int rows, int cols) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    /** Fast scanner that supplies primitive tokens from standard input. */
    private class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                st = new StringTokenizer(br.readLine());
            }
            return st.nextToken();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }

        long nextLong() throws IOException {
            return Long.parseLong(next());
        }

        double nextDouble() throws IOException {
            return Double.parseDouble(next());
        }

        BigInteger nextBigInteger() throws IOException {
            return new BigInteger(next());
        }
    }
}

