/**
 * Fast scanner that reads tokens from an {@link InputStream} quickly.
 */
class FastScanner {

    private final BufferedReader br;

    FastScanner(InputStream stream) {
        this.br = new BufferedReader(new InputStreamReader(stream));
    }

    /** Reads the next character, throwing {@link InputMismatchException} on I/O errors. */
    private int readChar() {
        try {
            int value = br.read();
            if (value < 0) {
                throw new InputMismatchException();
            }
            return value;
        } catch (IOException e) {
            throw new InputMismatchException();
        }
    }

    /** Skips whitespace characters. */
    private static boolean isWhitespace(int c) {
        return c <= ' ';
    }

    /** Returns the next non‑whitespace token (or {@code null} at EOF). */
    String next() {
        int ch;
        do {
            ch = readChar();
        } while (isWhitespace(ch));
        StringBuilder sb = new StringBuilder();
        while (ch >= 0 && !isWhitespace(ch)) {
            sb.appendCodePoint(ch);
            ch = readChar();
        }
        return sb.toString();
    }

    /** Reads the next integer from the input. */
    int nextInt() {
        int sign = 1;
        int c;
        do {
            c = readChar();
        } while (isWhitespace(c));

        if (c == '-') {
            sign = -1;
            c = readChar();
        }

        int result = 0;
        while (c >= 0 && !isWhitespace(c)) {
            if (c < '0' || c > '9') {
                throw new NumberFormatException();
            }
            result = result * 10 + (c - '0');
            c = readChar();
        }
        return result * sign;
    }

    /**
     * Reads a rectangular grid of characters.
     *
     * @param rows number of rows
     * @param cols number of columns
     * @return a 2‑D array where each inner array has length {@code cols}
     */
    char[][] readCharacterField(int rows, int cols) {
        char[][] grid = new char[rows][];
        for (int r = 0; r < rows; r++) {
            String token = next();
            if (token.length() != cols) {
                throw new AssertionError("Expected " + cols + " chars per row, got " + token.length());
            }
            grid[r] = token.toCharArray();
        }
        return grid;
    }

    /**
     * Reads the next complete line (or {@code null} if EOF).
     */
    String readLine() {
        try {
            return br.readLine();
        } catch (IOException e) {
            return null;
        }
    }
}

