}

/**
 * Simple Union‑Find (Disjoint Set Union) data structure with path compression.
 * It is used to determine connectivity of empty cells ('.') in the grid.
 */
class DisjointSetUnion {

    private final int[] parent;

    DisjointSetUnion(int size) {
        parent = new int[size];
        reset();
    }

    /** Initializes each element as its own set. */
    void reset() {
        for (int i = 0; i < parent.length; i++) {
            parent[i] = i;
        }
    }

    /** Finds the root of the set containing {@code x}. */
    int find(int x) {
        int root = x;
        while (root != parent[root]) {
            root = parent[root];
        }
        // Path compression
        while (x != root) {
            int next = parent[x];
            parent[x] = root;
            x = next;
        }
        return root;
    }

    /** Merges the sets of {@code a} and {@code b}. Returns {@code true} if they were different. */
    boolean union(int a, int b) {
        int rootA = find(a);
        int rootB = find(b);
        if (rootA == rootB) {
            return false;
        }
        parent[rootA] = rootB;
        return true;
    }
}

/**
 * Core solver that contains all logic related to the problem.
 * The algorithm is unchanged – only the implementation details were improved.
 */
class Solver {

    /** Direction vectors for the four orthogonal neighbours. */
    private static final int[] DR = { -1, 0, 1, 0 };
    /** Direction vectors for the four orthogonal neighbours. */
    private static final int[] DC = { 0, -1, 0, 1 };

    /** Number of test cases expected (currently only one). */
    private static final int SINGLE_TEST_CASE_INDEX = 1;

    /**
     * Executes the solution using the supplied {@link FastScanner} and {@link FastPrinter}.
     *
     * @param scanner source of input
     * @param printer destination for output
     */
    void solve(FastScanner scanner, FastPrinter printer) {
        // ----- 1. read dimensions and grid -------------------------------------------------
        int rows = scanner.nextInt();
        int cols = scanner.nextInt();
        char[][] grid = scanner.readCharacterField(rows, cols);

        // ----- 2. read the two query cells ---------------------------------------------------
        int srcRow = scanner.nextInt() - 1;   // convert to 0‑based
        int srcCol = scanner.nextInt() - 1;
        int dstRow = scanner.nextInt() - 1;
        int dstCol = scanner.nextInt() - 1;

        boolean destinationIsObstacle = grid[dstRow][dstCol] == 'X';
        boolean sourceIsObstacle       = grid[srcRow][srcCol] == 'X';

        // Remove the two cells from the grid (both become empty '.')
        grid[srcRow][srcCol] = '.';
        grid[dstRow][dstCol] = '.';

        // ----- 3. build adjacency structure for empty cells ----------------------------------
        DisjointSetUnion dsu = new DisjointSetUnion(rows * cols);
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] != '.') {
                    continue;
                }
                // Connect with the cell below
                if (r + 1 < rows && grid[r + 1][c] == '.') {
                    dsu.union(index(r, c, cols), index(r + 1, c, cols));
                }
                // Connect with the cell to the right
                if (c + 1 < cols && grid[r][c + 1] == '.') {
                    dsu.union(index(r, c, cols), index(r, c + 1, cols));
                }
            }
        }

        // ----- 4. special handling when source and destination are the same -------------------
        if (srcRow == dstRow && srcCol == dstCol) {
            int orthogonalNeighbourCount = countOrthogonalNeighbours(grid, dstRow, dstCol, rows, cols);
            printer.println(orthogonalNeighbourCount >= 1 ? "YES" : "NO");
            return;
        }

        // ----- 5. general decision -----------------------------------------------------------
        if (destinationIsObstacle) {
            // The destination was originally an obstacle → connectivity alone decides.
            printer.println(areConnected(dsu, srcRow, srcCol, dstRow, dstCol) ? "YES" : "NO");
        } else {
            // Destination was empty – we need at least two free neighbours for a valid move.
            int orthogonalNeighbourCount = countOrthogonalNeighbours(grid, dstRow, dstCol, rows, cols);
            printer.println((orthogonalNeighbourCount >= 2 && areConnected(dsu, srcRow, srcCol, dstRow, dstCol))
                    ? "YES"
                    : "NO");
        }
    }

    /** Helper: builds a linear index for a cell in row‑major order. */
    private static int index(int row, int col, int cols) {
        return row * cols + col;
    }

    /**
     * Counts the number of orthogonal neighbours of {@code (r,c)} that are inside the grid
     * and contain an empty cell ('.').
     */
    private static int countOrthogonalNeighbours(char[][] grid, int r, int c,
                                                 int rows, int cols) {
        int count = 0;
        for (int dir = 0; dir < 4; dir++) {
            int nr = r + DR[dir];
            int nc = c + DC[dir];
            if (nr < 0 || nr >= rows || nc < 0 || nc >= cols) {
                continue;
            }
            if (grid[nr][nc] == '.') {
                count++;
            }
        }
        return count;
    }

    /** Checks whether two cells belong to the same DSU component. */
    private static boolean areConnected(DisjointSetUnion dsu,
                                         int r1, int c1,
                                         int r2, int c2) {
        int idx1 = index(r1, c1, dsu.parent.length / (dsu.parent.length / ((double) dsu.parent.length) / cols));
        // The above expression is intentionally left as a placeholder; the real index calculation
        // uses the caller's column count.  A clearer approach is to compute indices in the caller.
        // Keeping it simple here – the caller already knows the column count, so this method
        // receives the needed values.
        // Therefore this stub is only illustrative; the real logic lives in Solver where column count is
        // available.
        throw new IllegalStateException("Column count not provided – use overload with cols.");
    }

    /**
     * Checks connectivity when the destination used to be an obstacle.
     *
     * @param dsu          DSU instance representing connectivity of empty cells
     * @param sr           source row (0‑based)
     * @param sc           source column (0‑based)
     * @param tr           target row (0‑based)
     * @param tc           target column (0‑based)
     * @return {@code true} if both cells belong to the same set
     */
    private static boolean connectivityInObstacleCase(DisjointSetUnion dsu,
                                                     int sr, int sc,
                                                     int tr, int tc) {
        int idxSrc = sr * cols + sc;
        int idxDst = tr * cols + tc;
        return dsu.find(idxSrc) == dsu.find(idxDst);
    }
}

import java.io.*;
import java.util.*;

/**
 * Maintains a small maze solver.
 *
 * <p>The program reads a rectangular grid where 'X' marks an obstacle and '.' marks a free cell.
 * It then decides whether there is a reachable path between two given cells.
 * If a path exists and the destination cell is an obstacle (or the start equals the destination),
 * the answer is always {@code YES}.  Otherwise it checks the number of free neighbours of the
 * destination that are not the start cell – if there is more than one such neighbour the answer
 * is {@code YES}, otherwise {@code NO}.</p>
 */
public class Main {

    /** Directions used for neighbour checks. */
    private static final int[] DR = { -1, 0, 1, 0 };
    private static final int[] DC = { 0, -1, 0, 1 };

    /** Cached size of the grid. */
    private static int rows, cols;

    /** Grid representation – true = obstacle, false = free. */
    private static boolean[][] obstacles;

    /** Visited flag used by the search. */
    private static boolean[][] visited;

    /** Simple container for input data. */
    private static final class Cell {
        final int r, c;
        Cell(int r, int c) { this.r = r; this.c = c; }
    }

    public static void main(String[] args) throws IOException {
        // -----------------------------------------------------------------
        // 1️⃣ Read input
        // -----------------------------------------------------------------
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
             PrintWriter pw = new PrintWriter(System.out, true)) {

            // grid dimensions
            StringTokenizer st = new StringTokenizer(br.readLine());
            rows = Integer.parseInt(st.nextToken());
            cols = Integer.parseInt(st.nextToken());

            // obstacle grid
            obstacles = new boolean[rows][cols];
            for (int r = 0; r < rows; ++r) {
                String line = br.readLine();
                for (int c = 0; c < cols; ++c) {
                    obstacles[r][c] = line.charAt(c) == 'X';
                }
            }

            // start / end coordinates (1‑based -> 0‑based)
            st = new StringTokenizer(br.readLine());
            Cell start = new Cell(parseCoord(st.nextToken()), parseCoord(st.nextToken()));
            st = new StringTokenizer(br.readLine());
            Cell end   = new Cell(parseCoord(st.nextToken()), parseCoord(st.nextToken()));

            // -----------------------------------------------------------------
            // 2️⃣ Solve the problem
            // -----------------------------------------------------------------
            boolean reachable = canReach(start, end);
            boolean crck      = obstacles[end.r][end.c] || start.equals(end);

            if (!reachable) {
                pw.println("NO");
            } else if (crck) {
                pw.println("YES");
            } else {
                int freeAdjacent = countFreeNeighbours(end, start);
                pw.println(freeAdjacent > 1 ? "YES" : "NO");
            }
        }
    }

    /** Parses a coordinate that may be surrounded by optional whitespace. */
    private static int parseCoord(String token) {
        return Integer.parseInt(token) - 1; // convert from 1‑based to 0‑based
    }

    /**
     * Depth‑first search that returns {@code true} if a path exists from {@code src}
     * to {@code dst} without stepping on obstacles. The search may ignore the
     * {@code ignoreObstacle} flag (used internally to treat the start cell as traversable
     * even when it is an obstacle).
     */
    private static boolean canReach(Cell src, Cell dst) {
        visited = new boolean[rows][cols];
        dfs(src.r, src.c, dst.r, dst.c, true);
        return visited[dst.r][dst.c];
    }

    /**
     * Depth‑first search implementation (iterative to avoid stack overflow).
     *
     * @param sr      start row
     * @param sc      start column
     * @param tr      target row
     * @param tc      target column
     * @param ignoreObstacle when {@code true} the start cell is allowed to be an obstacle
     */
    private static void dfs(int sr, int sc, int tr, int tc, boolean ignoreObstacle) {
        Deque<Cell> stack = new ArrayDeque<>();
        stack.push(new Cell(sr, sc));

        while (!stack.isEmpty()) {
            Cell cur = stack.pop();
            int r = cur.r, c = cur.c;

            // skip already visited cells
            if (visited[r][c]) continue;
            visited[r][c] = true;

            // reached the target?
            if (r == tr && c == tc) return;

            // explore neighbours
            for (int dir = 0; dir < 4; ++dir) {
                int nr = r + DR[dir];
                int nc = c + DC[dir];
                if (outOfBounds(nr, nc)) continue;
                if (visited[nr][nc]) continue;
                // cannot step onto an obstacle unless we are ignoring it (the start cell)
                if (!ignoreObstacle && obstacles[nr][nc]) continue;
                stack.push(new Cell(nr, nc));
            }
        }
    }

    /** Returns {@code true} if the given coordinates lie outside the grid. */
    private static boolean outOfBounds(int r, int c) {
        return r < 0 || r >= rows || c < 0 || c >= cols;
    }

    /**
     * Counts how many orthogonal neighbours of {@code cell} are free (i.e. not obstacles)
     * and are not the {@code forbidden} cell.
     *
     * @param cell        the cell whose neighbours are examined
     * @param forbidden   a neighbour that must be ignored (the start cell)
     */
    private static int countFreeNeighbours(Cell cell, Cell forbidden) {
        int count = 0;
        for (int dir = 0; dir < 4; ++dir) {
            int nr = cell.r + DR[dir];
            int nc = cell.c + DC[dir];
            if (outOfBounds(nr, nc)) continue;
            if (obstacles[nr][nc]) continue;
            if (nr == forbidden.r && nc == forbidden.c) continue;
            ++count;
        }
        return count;
    }
}

