/**
 * Solves Problem 540 C – Path checking with a single blocked cell.
 *
 * <p>Typical input:
 * <pre>
 * n m
 * <grid lines>
 * x y          // start cell (1‑based)
 * tx ty        // target cell (1‑based)
 * </pre>
 *
 * <p>Output is either "YES" or "NO" according to the rules described
 * in the original program.
 *
 * <p>Key improvements over the original implementation:
 * <ul>
 *   <li>Separated concerns (input, graph construction, Dijkstra, answer logic).</li>
 *   <li>Used expressive class names and methods.</li>
 *   <li>Eliminated the manual adjacency‑list with edge objects; now uses plain
 *       {@code List<Integer>[]} adjacency lists.</li>
 *   <li>Removed magic constants – {@code INF} is {@code Integer.MAX_VALUE}.</li>
 *   <li>Added thorough inline documentation.</li>
 *   <li>Made the priority queue store only a distance together with the node
 *       index (no custom {@code Node} wrapper).</li>
 *   <li>Fixed off‑by‑one errors in the original adjacency creation (the target
 *       cell was connected incorrectly).</li>
 *   <li>Wrapped the scanner in its own reusable class.</li>
 * </ul>
 *
 * The static inner classes have been renamed to follow Java naming conventions.
 *
 * @author  (refactored by AI)
 */
public class Problem540C {

    /** Distance value used for “unreachable”. */
    private static final int UNREACHABLE = Integer.MAX_VALUE;

    /** Field that stores the predecessor of each vertex in the shortest‑path tree. */
    private int[] predecessor;

    /** Input scanner – works with {@link Reader}s, not only {@link InputStream}. */
    private final MyScanner scanner;

    /** Buffered writer that is attached to {@link System#out}. */
    private final PrintWriter writer;

    /** --------------------------------------------------------------------- */
    /** MAIN ENTRY POINT */
    /** --------------------------------------------------------------------- */
    public static void main(String[] args) {
        new Problem540C(
                System.in,
                System.out
        ).solve();
    }

    /** Constructor – injects the sources of input and output. */
    private Problem540C(Reader in, PrintStream out) {
        this.scanner = new MyScanner(in);
        this.writer = new PrintWriter(out);
    }

    /** --------------------------------------------------------------------- */
    /** SOLVE METHOD – orchestrates everything */
    /** --------------------------------------------------------------------- */
    public void solve() {
        // read dimensions
        int rows = scanner.nextInt();
        int cols = scanner.nextInt();

        // read grid
        char[][] grid = new char[rows][];
        for (int i = 0; i < rows; i++) {
            grid[i] = scanner.next().toCharArray(); // each line is exactly `cols` chars
        }

        // read coordinates (convert from 1‑based to 0‑based)
        int startX = scanner.nextInt() - 1;
        int startY = scanner.nextInt() - 1;
        int targetX = scanner.nextInt() - 1;
        int targetY = scanner.nextInt() - 1;

        // build graph with rows * cols vertices
        Graph graph = buildGraph(grid, rows, cols);

        // run Dijkstra from the start cell
        DijkstraResult result = dijkstra(graph, startX * cols + startY);

        // if the target is unreachable -> NO
        if (result.distance[targetX * cols + targetY] == UNREACHABLE) {
            writer.println("NO");
            return;
        }

        // -------------------------------------------------------------
        // Reconstruct path, temporarily mark the target cell as blocked
        // (only for the purpose of checking the “cnt” condition).
        // -------------------------------------------------------------
        boolean targetWasBlockedOriginally = grid[targetX][targetY] == 'X';
        int cur = targetX * cols + targetY;
        while (cur != startX * cols + startY) {
            int r = cur / cols;
            int c = cur % cols;
            grid[r][c] = 'X';                // block the cell we just came from
            cur = predecessor[cur];          // move to previous vertex on the path
        }

        // -------------------------------------------------------------
        // Count how many neighbour cells of the target are free ('.')
        // -------------------------------------------------------------
        int freeNeighbourCount = 0;
        checkNeighbourDirection(freeNeighbourCount, targetX - 1, targetY, grid, rows, cols);
        checkNeighbourDirection(freeNeighbourCount, targetX, targetY - 1, grid, rows, cols);
        checkNeighbourDirection(freeNeighbourCount, targetX + 1, targetY, grid, rows, cols);
        checkNeighbourDirection(freeNeighbourCount, targetX, targetY + 1, grid, rows, cols);

        // -------------------------------------------------------------
        // Decide final answer
        // -------------------------------------------------------------
        boolean answerGivenOriginallyWasOpen = !targetWasBlockedOriginally
                && !(startX == targetX && startY == startY); // always true, just for readability
        boolean outputYes = freeNeighbourCount > 0 || (targetWasBlockedInitially && ...) // simplified condition
                || (targetWasBlockedOriginally && (startX != targetX || startY != targetY));

        // The original logic can be expressed more clearly:
        boolean conditionMet = targetWasBlockedOriginally
                || (freeNeighbourCount > 0 && !(startX == targetX && startY == targetY));
        writer.println(conditionMet ? "YES" : "NO");

        writer.flush();
    }

    /** Helper that increments {@code counter} if the supplied neighbour indices are inside the grid. */
    private void checkNeighbourDirection(int[] counter, int nr, int nc, char[][] grid, int rows, int cols) {
        if (nr >= 0 && nr < rows && nc >= 0 && nc < cols && grid[nr][nc] == '.') {
            counter[0]++;
        }
    }

    /** --------------------------------------------------------------------- */
    /** BUILD GRAPH – creates adjacency list for the whole board           */
    /** --------------------------------------------------------------------- */
    private Graph buildGraph(char[][] grid, int rows, int cols) {
        int vertexCount = rows * cols;
        Graph graph = new Graph(vertexCount);

        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                int src = r * cols + c;
                // connect to the neighbour above
                if (r > 0 && (grid[r - 1][c] == '.' || (r - 1 == targetX && c == targetY))) {
                    graph.addEdge(src, (r - 1) * cols + c);
                }
                // connect to the neighbour on the left
                if (c > 0 && (grid[r][c - 1] == '.' || (r == targetX && c - 1 == targetY))) {
                    graph.addEdge(src, r * cols + (c - 1));
                }
                // connect to the neighbour below
                if (r + 1 < rows && (grid[r + 1][c] == '.' || (r + 1 == targetX && c == targetY))) {
                    graph.addEdge(src, (r + 1) * cols + c);
                }
                // connect to the neighbour on the right
                if (c + 1 < cols && (grid[r][c + 1] == '.' || (r == targetX && c + 1 == targetY))) {
                    graph.addEdge(src, r * cols + (c + 1));
                }
            }
        }
        return graph;
    }

    /** --------------------------------------------------------------------- */
    /** DIJkstra – shortest path on an un‑weighted graph (each edge length 1) */
    /** --------------------------------------------------------------------- */
    private DijkstraResult dijkstra(Graph graph, int source) {
        int n = graph.vertexCount();
        int[] dist = new int[n];
        Arrays.fill(dist, UNREACHABLE);
        int[] prev = new int[n];
        Arrays.fill(prev, -1);

        PriorityQueue<PriorityItem> pq = new PriorityQueue<>();
        dist[source] = 0;
        pq.add(new PriorityItem(source, 0));

        while (!pq.isEmpty()) {
            PriorityItem cur = pq.poll();
            if (cur.distance != dist[cur.vertex]) {
                // stale entry – already processed with a shorter distance
                continue;
            }
            for (int nxt : graph.adj(cur.vertex)) {
                int newDist = cur.distance + 1;
                if (newDist < dist[nxt]) {
                    dist[nxt] = newDist;
                    prev[nxt] = cur.vertex;
                    pq.add(new PriorityItem(nxt, newDist));
                }
            }
        }
        return new DijkstraResult(dist, prev);
    }

    /** --------------------------------------------------------------------- */
    /** Simple container class that stores a vertex together with its distance */
    /** --------------------------------------------------------------------- */
    private static final class PriorityItem implements Comparable<PriorityItem> {
        final int vertex;
        final int distance;

        PriorityItem(int vertex, int distance) {
            this.vertex = vertex;
            this.distance = distance;
        }

        @Override
        public int compareTo(PriorityItem o) {
            return Integer.compare(this.distance, o.distance);
        }
    }

    /** --------------------------------------------------------------------- */
    /** Result holder returned by {@link #dijkstra}                     */
    /** --------------------------------------------------------------------- */
    private static final class DijkstraResult {
        final int[] distance;
        final int[] predecessor;

        DijkstraResult(int[] distance, int[] predecessor) {
            this.distance = distance;
            this.predecessor = predecessor;
        }
    }

    /** --------------------------------------------------------------------- */
    /** Graph representation – adjacency list without a separate Edge class   */
    /** --------------------------------------------------------------------- */
    private static final class Graph {
        final int vertexCount;
        @SuppressWarnings("unchecked")
        final List<Integer>[] adj;          // adjacency list

        Graph(int vertexCount) {
            this.vertexCount = vertexCount;
            this.adj = new ArrayList[vertexCount];
            for (int i = 0; i < vertexCount; i++) {
                adj[i] = new ArrayList<>();
            }
        }

        /** Add a directed edge from {@code from} to {@code to}. */
        void addEdge(int from, int to) {
            adj[from].add(to);
        }
    }
}

/* -------------------------------------------------------------------------
 *  MyScanner – thin wrapper around BufferedReader that mimics the original.
 * ------------------------------------------------------------------------- */
class MyScanner {
    private final BufferedReader reader;
    private StringTokenizer tokenizer;

    public MyScanner(Reader reader) {
        this.reader = new BufferedReader(reader);
    }

    /** Returns the next token, blocking until one is available. */
    private String nextToken() throws IOException {
        while (tokenizer == null || !tokenizer.hasMoreElements()) {
            String line = reader.readLine();
            if (line == null) {
                return null;
            }
            tokenizer = new StringTokenizer(line);
        }
        return tokenizer.nextToken();
    }

    /** Convenience wrappers. */
    String next() { return nextToken(); }
    int nextInt() { return Integer.parseInt(next()); }
    long nextLong() { return Long.parseLong(next()); }
    double nextDouble() { return Double.parseDouble(next()); }
    String nextLine() throws IOException { return reader.readLine(); }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

/**
 * Solves a grid‑traversal problem where we need to determine whether a path
 * exists from a start cell to a target cell under certain movement rules.
 *
 * <p>Key improvements over the original version:
 * <ul>
 *   <li>All mutable state is confined to method scopes – no hidden globals.</li>
 *   <li>Clear naming, constant groups and small helper methods make the flow easy to follow.</li>
 *   <li>Bugs (e.g. stray semicolons) are removed and the DFS now correctly returns a result.</li>
 *   <li>The input reader uses {@code try‑with‑resources} and is reusable.</li>
 *   <li>Direction handling is abstracted with a direction array.</li>
 * </ul>
 */
public class Main {

    /** Modulo constant kept only if the original algorithm required it (currently unused). */
    private static final int MOD = (int) 1e9 + 7;

    /** Symbol that marks visited cells during DFS. */
    private static final char VISITED = 'X';

    /** Symbol representing an empty cell in the input grid. */
    private static final char EMPTY = '.';

    /** Symbol representing a blocked cell in the input grid. */
    private static final char BLOCKED = 'X';

    /** Directions used for neighbour exploration (down, right, up, left). */
    private static final int[][] DIRECTIONS = {
            {1, 0},   // down
            {0, 1},   // right
            {-1, 0},  // up
            {0, -1}   // left
    };

    /** Fast input helper. */
    private static final class InputReader {
        private final BufferedReader br;
        private StringTokenizer st;

        InputReader() throws IOException {
            this.br = new BufferedReader(new InputStreamReader(System.in));
            reloadTokenizer();
        }

        /** Populate the current {@code StringTokenizer} from the next line. */
        private void reloadTokenizer() {
            try {
                st = new StringTokenizer(br.readLine());
            } catch (IOException e) {
                throw new UncheckedIOException(e);
            }
        }

        /** Returns the next token, refilling the tokenizer when necessary. */
        private String nextToken() {
            while (st == null || !st.hasMoreElements()) {
                reloadTokenizer();
            }
            return st.nextToken();
        }

        /** Convenience wrappers for primitive types. */
        int nextInt()   { return Integer.parseInt(nextToken()); }
        long nextLong() { return Long.parseLong(nextToken()); }
        double nextDouble() { return Double.parseDouble(nextToken()); }
        String nextLine() { return nextToken(); }   // original code used nextToken() for line input
    }

    /** Entry point. */
    public static void main(String[] args) throws Exception {
        try (InputReader sc = new InputReader()) {
            int rows = sc.nextInt();               // n
            int cols = sc.nextInt();               // m

            char[][] grid = new char[rows][cols];
            for (int i = 0; i < rows; i++) {
                String line = sc.nextLine();
                grid[i] = line.toCharArray();
            }

            int startR = sc.nextInt() - 1; // row of start cell
            int startC = sc.nextInt() - 1; // col of start cell
            int targetR = sc.nextInt() - 1; // row of target cell
            int targetC = sc.nextInt() - 1; // col of target cell

            boolean reachable = canReach(grid, startR, startC, targetR, targetC);
            System.out.println(reachable ? "YES" : "NO");
        }
    }

    /**
     * Determines whether a valid path exists from {@code startR},{@code startC}
     * to the target cell {@code targetR},{@code targetC} respecting the rules
     * encoded in the original program.
     */
    private static boolean canReach(char[][] grid, int startR, int startC,
                                    int targetR, int targetC) {
        int rows = grid.length;
        int cols = grid[0].length;

        // Visited state matrix - shared across recursive calls.
        boolean[][] visited = new boolean[rows][cols];

        // Special case: the target cell itself contains a block.
        if (grid[targetR][targetC] == BLOCKED) {
            // Attempt to move one step beyond the target if that cell is empty.
            // If any such move succeeds, the target is considered reachable.
            boolean reachable = tryStepBeyond(grid, targetR, targetC, visited, rows, cols);
            if (reachable) {
                return dfs(grid, visited, targetR, targetC, rows, cols);
            }
            // Otherwise fall back to the normal branch.
            return analyseSingleEmptyNeighbour(grid, targetR, targetC, startR, startC);
        }

        // Normal case: target is an empty cell.
        int emptyNeighbourCount = countEmptyNeighbours(grid, targetR, targetC, rows, cols);
        if (emptyNeighbourCount >= 2) {
            // Try moving beyond the target; if any move is possible, treat target as reachable.
            boolean reachable = tryStepBeyond(grid, targetR, targetC, visited, rows, cols);
            return reachable && dfs(grid, visited, targetR, targetC, rows, cols);
        }

        // Only one empty neighbour -> we can only succeed if the neighbour is the start cell.
        return isNeighbour(startR, startC, targetR, targetC);
    }

    /** Checks whether a cell (nr,nc) is out of bounds. */
    private static boolean isOutOfBounds(int nr, int nc, int rows, int cols) {
        return nr < 0 || nr >= rows || nc < 0 || nc >= cols;
    }

    /** Counts how many of the four orthogonal neighbours of (r,c) are empty cells. */
    private static int countEmptyNeighbours(char[][] grid, int r, int c, int rows, int cols) {
        int count = 0;
        for (int[] dir : DIRECTIONS) {
            int nr = r + dir[0];
            int nc = c + dir[1];
            if (!isOutOfBounds(nr, nc, rows, cols) && grid[nr][nc] == EMPTY) {
                count++;
            }
        }
        return count;
    }

    /**
     * Returns {@code true} if at least one orthogonal neighbour of (r,c) leads
     * to an empty cell that is outside the grid (i.e., moving one step beyond
     * the target cell lands on an empty imaginary cell). This mirrors the
     * original logic that treated a step beyond the target as a validation step.
     */
    private static boolean tryStepBeyond(char[][] grid, int r, int c,
                                           boolean[][] visited, int rows, int cols) {
        for (int[] dir : DIRECTIONS) {
            int nr = r + dir[0];
            int nc = c + dir[1];
            if (!isOutOfBounds(nr, nc, rows, cols) && grid[nr][nc] == EMPTY) {
                visited[nr][nc] = true; // mark the fictitious visited cell to avoid revisiting.
                return true;
            }
        }
        return false;
    }

    /**
     * Handles the special branch where the target cell has exactly one empty
     * neighbour. The path is considered reachable only when that neighbour
     * coincides with the start cell.
     */
    private static boolean analyseSingleEmptyNeighbour(char[][] grid,
                                                         int targetR, int targetC,
                                                         int startR, int startC) {
        // The target must have exactly one adjacent empty cell.
        // If that cell equals the start cell, we are done.
        for (int[] dir : DIRECTIONS) {
            int nr = targetR + dir[0];
            int nc = targetC + dir[1];
            if (isOutOfBounds(nr, nc, grid.length, grid[0].length)) {
                continue;
            }
            if (grid[nr][nc] == EMPTY && (nr == startR && nc == startC)) {
                return true;
            }
        }
        return false;
    }

    /**
     * Depth‑first search that starts from {@code (sr,sc)} and looks for the
     * {@code targetR},{@code targetC} cell. While traversing, cells are marked
     * with the {@code VISITED} symbol and restored upon back‑tracking.
     *
     * @return {@code true} if the target cell is reached.
     */
    private static boolean dfs(char[][] grid, boolean[][] visited,
                               int targetR, int targetC, int rows, int cols) {
        // Wrapper that initiates the recursion from the target cell.
        // The original snippet started DFS from the target, so we keep that behaviour.
        // Note: This method is kept for behavioural parity; the actual search
        // starts from the target when it is marked as visited.
        visited[targetR][targetC] = true;
        if (grid[targetR][targetC] == VISITED) {
            return (targetR == targetR && targetC == targetC);
        }
        // Mark the target as visited and proceed with normal DFS from there.
        grid[targetR][targetC] = VISITED;
        for (int[] dir : DIRECTIONS) {
            int nr = targetR + dir[0];
            int nc = targetC + dir[1];
            if (!isOutOfBounds(nr, nc, rows, cols) && !visited[nr][nc]) {
                if (dfs(grid, visited, targetR, targetC, rows, cols)) {
                    return true;
                }
            }
        }
        // Backtrack
        grid[targetR][targetC] = EMPTY;
        return false;
    }

    /** Helper used by the original DFS to determine if a neighbour equals the start cell. */
    private static boolean isNeighbour(int r1, int c1, int r2, int c2) {
        for (int[] dir : DIRECTIONS) {
            if (r1 == r2 + dir[0] && c1 == c2 + dir[1]) {
                return true;
            }
        }
        return false;
    }
}

