/**
 * Encapsulates the core algorithm for problem C.
 * Keeps the {@code main} method untouched and focuses on readability,
 * single‑responsibility methods and proper naming.
 */
class Solver {

    /** Four cardinal directions: up, left, right, down. */
    private static final int[][] DIRECTIONS = {
            {-1, 0}, {0, -1}, {0, 1}, {1, 0}
    };

    /**
     * Reads the whole test case from {@link InputReader} and prints the answer.
     *
     * @param testNumber ignored (kept for API compatibility)
     * @param reader     input source
     * @param out        output destination
     */
    public void solve(int testNumber, InputReader reader, PrintWriter out) {
        int rows = reader.nextInt();
        int cols = reader.nextInt();

        char[][] grid = readGrid(reader, rows);
        int[] start = readPosition(reader);
        int[] end   = readPosition(reader);

        if (!bfsReachable(grid, rows, cols, start, end)) {
            out.println("NO");
            return;
        }

        // Original problem specific rule
        if (grid[end[0]][end[1]] == 'X') {
            out.println("YES");
        } else {
            int goodNeighbours = countValidNeighbours(grid, end, start);
            out.println(goodNeighbours >= 2 ? "YES" : "NO");
        }
    }

    /** Reads the matrix of characters that describes the board. */
    private char[][] readGrid(InputReader reader, int rows) {
        char[][] grid = new char[rows][];
        for (int r = 0; r < rows; r++) {
            grid[r] = reader.next().toCharArray();
        }
        return grid;
    }

    /** Reads a 1‑based coordinate pair and converts it to 0‑based indices. */
    private int[] readPosition(InputReader reader) {
        return new int[]{reader.nextInt() - 1, reader.nextInt() - 1};
    }

    /** Breadth‑first search that determines if {@code target} can be reached from {@code source}. */
    private boolean bfsReachable(char[][] grid, int rows, int cols, int[] source, int[] target) {
        boolean[][] visited = new boolean[rows][cols];
        Queue<int[]> queue = new ArrayDeque<>();

        queue.add(source);
        visited[source[0]][source[1]] = true;

        while (!queue.isEmpty()) {
            int[] cur = queue.poll();
            int r = cur[0];
            int c = cur[1];

            if (r == target[0] && c == target[1]) {
                return true;
            }

            for (int[] dir : DIRECTIONS) {
                int nr = r + dir[0];
                int nc = c + dir[1];
                if (isInside(nr, nc, rows, cols) && !visited[nr][nc] && grid[nr][nc] != 'X') {
                    visited[nr][nc] = true;
                    queue.add(new int[]{nr, nc});
                }
            }
        }
        return false;
    }

    /** Utility to test if a cell lies inside the board. */
    private boolean isInside(int r, int c, int rows, int cols) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    /** Counts orthogonal neighbours of {@code pos} that are either the start cell or an empty cell ('.'). */
    private int countValidNeighbours(char[][] grid, int[] pos, int[] start) {
        int count = 0;
        for (int[] dir : DIRECTIONS) {
            int nr = pos[0] + dir[0];
            int nc = pos[1] + dir[1];
            if ((nr == start[0] && nc == start[1])
                    || (isInside(nr, nc, grid.length, grid[0].length) && grid[nr][nc] == '.')) {
                count++;
            }
        }
        return count;
    }
}

/**
 * Fast tokenised input reader.
 * Works with any {@link InputStream} supplied by the caller.
 */
class InputReader {
    private final BufferedReader reader;
    private StringTokenizer tokenizer;

    /** Constructs a reader that wraps the given {@link InputStream}. */
    InputReader(InputStream stream) {
        reader = new BufferedReader(new InputStreamReader(stream));
    }

    /** Returns the next token or blocks waiting for more input. */
    String next() {
        while (tokenizer == null || !tokenizer.hasMoreTokens()) {
            try {
                tokenizer = new StringTokenizer(reader.readLine());
            } catch (IOException e) {
                throw new UncheckedIOException(e);
            }
        }
        return tokenizer.nextToken();
    }

    /** Convenience wrapper around {@code next()} that parses an int. */
    int nextInt() {
        return Integer.parseInt(next());
    }
}

/**
 * Refactored version of the original program.
 *
 * <p>
 * The program reads a rectangular grid, builds a binary map where 'X' cells are obstacles,
 * and then determines whether the goal cell can be reached from the start cell.
 * The result printed by the original code was a mixture of several disconnected checks.
 * The refactor reorganises the logic into well‑named methods, removes magic numbers,
 * and uses proper data‑structures for clarity and maintainability.
 * </p>
 *
 * <p>Behaviour is kept identical to the original program, but the code is now:</p>
 * <ul>
 *   <li>type‑safe (no raw {@code Scanner} misuse, fixed‑size arrays → dynamic allocation)</li>
 *   <li>self‑documenting (meaningful names, constants, Javadoc)</li>
 *   <li>structured (encapsulation, single‑responsibility methods)</li>
 *   <li>easier to test and extend</li>
 * </ul>
 */
public class PathFinder {

    /* --------------------------------------------------------------------- */
    /*  Constants & direction vectors                                         */
    /* --------------------------------------------------------------------- */
    private static final int UNVISITED = 0;
    private static final int VISITED   = 1;

    /** Four orthogonal moves: up, down, left, right */
    private static final int[][] DIRS = {
            {-1, 0}, {1, 0}, {0, -1}, {0, 1}
    };

    /* --------------------------------------------------------------------- */
    /*  Core data holder                                                       */
    /* --------------------------------------------------------------------- */
    private final int rows;
    private final int cols;
    private final int[][] grid;        // 0 = free cell, 1 = obstacle
    private final int[] start;           // {row, col}
    private final int[] goal;            // {row, col}
    private final boolean[][] visited;   // tracks visited cells during DFS
    private final List<int[]> path;      // optional – stores one valid path

    /* --------------------------------------------------------------------- */
    /*  Constructor                                                            */
    /* --------------------------------------------------------------------- */
    /**
     * @param rows   number of rows in the grid
     * @param cols   number of columns in the grid
     * @param grid   binary map (0/1) where 1 denotes an obstacle
     * @param start  start coordinates {@code [row, col]}
     * @param goal   goal coordinates {@code [row, col]}
     */
    public PathFinder(int rows, int cols, int[][] grid,
                      int[] start, int[] goal) {
        this.rows = rows;
        this.cols = cols;
        this.grid = grid;
        this.start = start;
        this.goal = goal;
        this.visited = new boolean[rows][cols];
        this.path = new java.util.ArrayList<>();
    }

    /* --------------------------------------------------------------------- */
    /*  Public API                                                             */
    /* --------------------------------------------------------------------- */
    /**
     * Executes a depth‑first search from the start cell.
     * The search respects obstacle cells and records one successful path if the goal
     * is reachable.  The method returns {@code true} if the goal was visited.
     */
    public boolean dfs() {
        return dfsRecursive(start[0], start[1]);
    }

    /**
     * Evaluates the conditions that decide whether the answer is {@code YES}
     * or {@code NO}.  The algorithm mimics the original program’s branching
     * logic but is expressed in a cleaner way.
     *
     * @return the textual answer for the problem
     */
    public String evaluate() {
        if (!visited[goal[0]][goal[1]]) {
            return "NO";
        }

        // Goal was visited – now analyse localisation relative to the start.
        boolean adjacentToStart = areAdjacent(start[0], start[1], goal[0], goal[1]);
        boolean alreadyAtGoal   = start[0] == goal[0] && start[1] == goal[1];

        if (adjacentToStart || alreadyAtGoal) {
            // count neighbouring free cells of the goal
            int freeNeighbourCount = countFreeNeighbours(goal[0], goal[1]);
            return (freeNeighbourCount >= 1 || grid[goal[0]][goal[1]] == 1) ? "YES" : "NO";
        }

        // General case – need at least two free neighbours of the goal,
        // or the goal itself being an obstacle.
        int freeNeighbourCount = countFreeNeighbours(goal[0], goal[1]);
        return (freeNeighbourCount >= 2 || grid[goal[0]][goal[1]] == 1) ? "YES" : "NO";
    }

    /* --------------------------------------------------------------------- */
    /*  Private helpers                                                         */
    /* --------------------------------------------------------------------- */
    /** Recursive DFS that marks visited cells and stores one path. */
    private boolean dfsRecursive(int r, int c) {
        if (!inBounds(r, c)) {
            return false;
        }
        if (visited[r][c] || grid[r][c] == 1) {
            return false;
        }

        visited[r][c] = true;
        path.add(new int[]{r, c});

        if (isGoal(r, c)) {
            return true;                // goal reached – stop recursion early
        }

        for (int[] d : DIRS) {
            int nr = r + d[0];
            int nc = c + d[1];
            if (dfsRecursive(nr, nc)) {
                return true;              // propagate success upward
            }
        }

        path.remove(path.size() - 1);     // backtrack
        return false;
    }

    /** Checks whether two coordinates are orthogonal neighbours. */
    private boolean areAdjacent(int r1, int c1, int r2, int c2) {
        return (Math.abs(r1 - r2) == 1 && c1 == c2) ||
               (Math.abs(c1 - c2) == 1 && r1 == r2);
    }

    /** Counts how many orthogonal neighbours of (r,c) are inside the grid and not obstacles. */
    private int countFreeNeighbours(int r, int c) {
        int count = 0;
        for (int[] d : DIRS) {
            int nr = r + d[0];
            int nc = c + d[1];
            if (inBounds(nr, nc) && grid[nr][nc] == 0) {
                count++;
            }
        }
        return count;
    }

    /** Returns {@code true} if (r,c) coordinates are inside the grid limits. */
    private boolean inBounds(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    /** Determines whether the current cell is the goal. */
    private boolean isGoal(int r, int c) {
        return r == goal[0] && c == goal[1];
    }

    /* --------------------------------------------------------------------- */
    /*  Utility method for printing the result                               */
    /* --------------------------------------------------------------------- */
    private static void printResult(String answer) {
        System.out.println(answer);
    }

    /* --------------------------------------------------------------------- */
    /*  Main entry point                                                       */
    /* --------------------------------------------------------------------- */
    public static void main(String[] args) {
        /* ------------ read input ---------------------------------------- */
        try (java.util.Scanner scanner = new java.util.Scanner(System.in)) {
            int rows = scanner.nextInt();
            int cols = scanner.nextInt();

            // read the textual representation of the grid (size up to 500 cells)
            String[] rowsStr = new String[rows];
            for (int i = 0; i < rows; i++) {
                rowsStr[i] = scanner.next();
            }

            // allocate binary map
            int[][] binaryGrid = new int[rows][cols];
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    binaryGrid[r][c] = rowsStr[r].charAt(c) == 'X' ? 1 : 0;
                }
            }

            // start and goal coordinates (the original code uses 1‑based input)
            int startRow = scanner.nextInt() - 1;
            int startCol = scanner.nextInt() - 1;
            int goalRow  = scanner.nextInt() - 1;
            int goalCol  = scanner.nextInt() - 1;

            /* ------------ build PathFinder instance ----------------------- */
            int[] startCoord = {startRow, startCol};
            int[] goalCoord  = {goalRow, goalCol};

            PathFinder pf = new PathFinder(rows, cols, binaryGrid, startCoord, goalCoord);

            /* ------------ run DFS ----------------------------------------- */
            pf.dfs();

            /* ------------ evaluate and output the answer ------------------ */
            printResult(pf.evaluate());

        } catch (java.util.InputMismatchException e) {
            System.err.println("Invalid input format.");
        }
    }
}

import java.io.*;
import java.util.*;

public class IceCave {

    /* ------------------------------------------------------------
     *  Input handling
     * ------------------------------------------------------------ */
    private static class FastInput {
        private final InputStream stream;
        private final byte[] buffer = new byte[16_384];
        private int ptr = 0, len = 0;

        FastInput(InputStream stream) { this.stream = stream; }

        private int readByte() {
            if (len == -1) throw new EOFException();
            if (ptr >= len) {
                ptr = 0;
                len = stream.read(buffer);
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        private boolean isSpace(int c) { return !(c >= 33 && c <= 126); }

        private int skippingWhitespace() {
            int b;
            while ((b = readByte()) != -1 && isSpace(b)) { }
            return b;
        }

        private char readChar() { return (char) skippingWhitespace(); }

        private String nextString() {
            StringBuilder sb = new StringBuilder();
            int b = skippingWhitespace();
            while (!isSpace(b)) {
                sb.appendCodePoint(b);
                b = readByte();
            }
            return sb.toString();
        }

        private int nextInt() {
            long val = 0;
            boolean neg = false;
            int b = skippingWhitespace();
            if (b == '-') { neg = true; b = readByte(); }

            while (b >= '0' && b <= '9') {
                val = val * 10 + (b - '0');
                b = readByte();
            }
            return (int) (neg ? -val : val);
        }

        private long nextLong() {
            long val = 0;
            boolean neg = false;
            int b = skippingWhitespace();
            if (b == '-') { neg = true; b = readByte(); }

            while (b >= '0' && b <= '9') {
                val = val * 10 + (b - '0');
                b = readByte();
            }
            return neg ? -val : val;
        }

        // Convenience wrappers -------------------------------------------------
        int nextInt(int n) { return nextInt(); }               // overload for readability
        long nextLong() { return nextLong(); }
        char[] nextCharArray(int size) {
            char[] arr = new char[size];
            for (int i = 0; i < size; i++) arr[i] = readChar();
            return arr;
        }

        char[][] nextCharGrid(int rows, int cols) {
            char[][] grid = new char[rows][cols];
            for (int r = 0; r < rows; r++) {
                String line = nextString();
                grid[r] = line.toCharArray();
            }
            return grid;
        }
    }

    /* ------------------------------------------------------------
     *  Core solving logic
     * ------------------------------------------------------------ */
    private static final int[][] DIRECTIONS = {{-1, 0}, {0, -1}, {0, 1}, {1, 0}};

    private static class Solver {
        private final FastInput in;
        private final PrintWriter out;

        // Grids / state
        private char[][] maze;
        private boolean[][] visited;
        private int startR, startC, targetR, targetC;
        private boolean solved;

        Solver(FastInput in, PrintWriter out) {
            this.in = in;
            this.out = out;
        }

        /** Entry point used by {@code run()}. */
        void solve() {
            int rows = in.nextInt();
            int cols = in.nextInt();

            maze      = new char[rows][cols];
            visited   = new boolean[rows][cols];

            // read the map
            for (int r = 0; r < rows; r++) {
                String line = in.nextString();
                System.arraycopy(line.toCharArray(), 0, maze[r], 0, cols);
            }

            // read start & target (1‑based indices in the original code)
            startR = in.nextInt() - 1;
            startC = in.nextInt() - 1;
            targetR = in.nextInt() - 1;
            targetC = in.nextInt() - 1;

            // the starting cell is always free – we explicitly mark it as visited
            visited[startR][startC] = true;
            dfs(startR, startC);
            out.println(solved ? "YES" : "NO");
        }

        /** Depth‑first search that respects the original game rules. */
        private void dfs(int r, int c) {
            if (r < 0 || r >= maze.length || c < 0 || c >= maze[0].length) return;

            // Destination reached?
            if (r == targetR && c == targetC && maze[r][c] == 'X') {
                solved = true;
                return;
            }

            // Only walk on free cells ('.') or the destination ('X')
            if (maze[r][c] != '.' && !(r == targetR && c == targetC)) return;

            // Mark current cell as visited – we reuse the visited array instead of
            // mutating the maze itself, which makes the intent clearer.
            for (int[] dir : DIRECTIONS) {
                int nr = r + dir[0];
                int nc = c + dir[1];
                // Allow moving to the target even if it hasn't been visited yet.
                if (nr >= 0 && nr < maze.length && nc >= 0 && nc < maze[0].length &&
                    (visited[nr][nc] || (nr == targetR && nc == targetC))) {
                    visited[nr][nc] = true;
                    dfs(nr, nc);
                    if (solved) return; // early exit once a solution is found
                }
            }
        }
    }

    /* ------------------------------------------------------------
     *  Program entry point
     * ------------------------------------------------------------ */
    private static void solveAll() throws Exception {
        // Read all input at once (mirrors the original behavior)
        String fullInput = (System.in instanceof java.io.FileInputStream is && is.available() > 0)
                ? readFileToString(is)
                : null;                                      // fallback to stdin later

        FastInput in = new FastInput(
                fullInput != null ? new ByteArrayInputStream(fullInput.getBytes())
                                 : System.in
        );
        PrintWriter out = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)));

        long start = System.currentTimeMillis();
        Solver solver = new Solver(in, out);
        solver.solve();
        out.flush();

        if (fullInput != null) {
            long elapsed = System.currentTimeMillis() - start;
            System.err.println(elapsed + "ms");
        }
    }

    /** Helper that reads an entire file into a String – only used for the sample‑input trick. */
    private static String readFileToString(FileInputStream fis) throws IOException {
        StringBuilder sb = new StringBuilder();
        byte[] buf = new byte[8192];
        int len;
        while ((len = fis.read(buf)) != -1) sb.append(new String(buf, 0, len));
        return sb.toString();
    }

    public static void main(String[] args) throws Exception {
        solveAll();
    }
}

import java.io.*;
import java.util.ArrayDeque;
import java.util.Objects;
import java.util.Queue;

/**
 * Entry point of the program.
 * Reads the input, solves the problem and prints {@code YES} or {@code NO}.
 */
public final class Main {

    /** Directions used by the BFS search. */
    private static final int[] DX = {0, 0, -1, 1};
    /** Directions used by the BFS search. */
    private static final int[] DY = {-1, 1, 0, 0};

    /** Fast scanner that reads raw bytes – much faster than {@link Scanner}. */
    private static final class FastScanner {
        private static final int BUFFER_SIZE = 1 << 16;
        private final InputStream in;
        private final byte[] buffer = new byte[BUFFER_SIZE];
        private int bufferIdx = 0;
        private int size = 0;
        private long cur = -1;          // holds the current character as a signed value

        FastScanner(InputStream in) {
            this.in = in;
        }

        /** Reads the next non‑whitespace character. */
        private int nextChar() throws IOException {
            if (cur != -1) {
                return (int) cur;
            }
            while (true) {
                if (bufferIdx == size) {
                    size = in.read(buffer);
                    if (size == -1) {
                        return -1; // EOF
                    }
                    bufferIdx = 0;
                }
                cur = buffer[bufferIdx++];
                if (!isWhitespace(cur)) {
                    break;
                }
            }
            return cur;
        }

        /** Checks whether a character code represents whitespace. */
        private static boolean isWhitespace(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        /** Returns {@code true} if the end of the stream has been reached. */
        private boolean isEOF() throws IOException {
            return nextChar() == -1;
        }

        /** Reads the next signed 32‑bit integer. */
        int nextInt() throws IOException {
            long v = nextLong();
            if (v > Integer.MAX_VALUE || v < Integer.MIN_VALUE) {
                throw new ArithmeticException("Scanned value overflows integer");
            }
            return (int) v;
        }

        /** Reads the next signed 64‑bit integer. */
        long nextLong() throws IOException {
            boolean negative = false;
            if (cur == -1) {
                cur = nextChar();
            }
            while (!isEOF() && (cur < '0' || cur > '9') && cur != '-') {
                cur = nextChar();
            }
            if (!isEOF() && cur == '-') {
                negative = true;
                cur = nextChar();
            }
            long result = 0L;
            while (!isEOF() && cur >= '0' && cur <= '9') {
                result = result * 10 + (cur - '0');
                cur = nextChar();
            }
            return negative ? -result : result;
        }

        /** Reads the next token as a {@link String}. */
        String nextToken() throws IOException {
            int c;
            do {
                c = nextChar();
            } while (c != -1 && isWhitespace(c));
            if (c == -1) {
                return null;
            }
            StringBuilder sb = new StringBuilder();
            do {
                sb.append((char) c);
                c = nextChar();
            } while (!isWhitespace(c) && c != -1);
            return sb.toString();
        }
    }

    /** Simple immutable pair of integer coordinates. */
    private static final class Pair {
        final int row;
        final int col;

        Pair(int row, int col) {
            this.row = row;
            this.col = col;
        }

        /** Equality based on both coordinates. */
        boolean equalsTo(Pair o) {
            return this.row == o.row && this.col == o.col;
        }

        /** Manhattan distance to another pair determines adjacency. */
        boolean isAdjacent(Pair o) {
            return Math.abs(row - o.row) + Math.abs(col - o.col) == 1;
        }

        /** Checks that the coordinates stay inside the grid limits. */
        boolean isInBounds(char[][] grid) {
            return row >= 0 && row < grid.length
                    && col >= 0 && col < grid[row].length;
        }

        /** Convenient toString for debugging. */
        @Override
        public String toString() {
            return "(" + row + ',' + col + ')';
        }
    }

    /** Solves a single test case. */
    private static void solve(FastScanner in, PrintWriter out) throws IOException {
        int rows = in.nextInt();
        int cols = in.nextInt();

        // Read grid
        char[][] grid = new char[rows][];
        for (int r = 0; r < rows; ++r) {
            grid[r] = in.nextToken().toCharArray();
        }

        // Source and sink positions (they are 1‑based in the original input)
        Pair source = new Pair(in.nextInt() - 1, in.nextInt() - 1);
        Pair sink   = new Pair(in.nextInt() - 1, in.nextInt() - 1);

        boolean answer = isPathPossible(source, sink, grid, rows, cols);
        out.println(answer ? "YES" : "NO");
    }

    /**
     * Determines whether a path exists from {@code start} to {@code end}
     * while obeying the movement rules described by the original code.
     */
    private static boolean isPathPossible(Pair start, Pair end,
                                          char[][] grid,
                                          int maxRow, int maxCol) {
        // Trivial case – source already equals sink
        if (start.equalsTo(end)) {
            return hasAtLeastOneEmptyNeighbour(sink, grid, maxRow, maxCol);
        }

        // Directly adjacent case
        if (start.isAdjacent(end)) {
            if (grid[end.row][end.col] == 'X') {
                return true;
            }
            // Need at least two empty neighbours OR (one empty neighbour and start cell is empty)
            return hasAtLeastTwoEmptyNeighbours(sink, grid, maxRow, maxCol)
                    || (hasAtLeastOneEmptyNeighbour(sink, grid, maxRow, maxCol)
                        && grid[start.row][start.col] == '.');
        }

        // General case – BFS for a walkable path
        return bfs(start, end, grid);
    }

    /** Counts how many of the four orthogonal neighbours of {@code cell} are empty ('.'). */
    private static boolean hasAtLeastOneEmptyNeighbour(Pair cell,
                                                       char[][] grid,
                                                       int maxRow, int maxCol) {
        int count = 0;
        for (int i = 0; i < 4; ++i) {
            int nr = cell.row + DX[i];
            int nc = cell.col + DY[i];
            if (nr < 0 || nr >= maxRow || nc < 0 || nc >= maxCol) {
                continue;
            }
            if (grid[nr][nc] == '.') {
                ++count;
            }
        }
        return count >= 1;
    }

    /** Counts how many of the four orthogonal neighbours of {@code cell} are empty ('.'). */
    private static boolean hasAtLeastTwoEmptyNeighbours(Pair cell,
                                                        char[][] grid,
                                                        int maxRow, int maxCol) {
        int count = 0;
        for (int i = 0; i < 4; ++i) {
            int nr = cell.row + DX[i];
            int nc = cell.col + DY[i];
            if (nr < 0 || nr >= maxRow || nc < 0 || nc >= maxCol) {
                continue;
            }
            if (grid[nr][nc] == '.') {
                ++count;
            }
        }
        return count >= 2;
    }

    /**
     * Breadth‑first search that respects the rule “cannot step onto an {@code X} cell,
     * except possibly the destination”.  The algorithm uses a visited boolean matrix
     * to keep the original grid unchanged.
     */
    private static boolean bfs(Pair start, Pair end,
                               char[][] grid) {
        final int rows = grid.length;
        final int cols = grid[0].length;
        boolean[][] visited = new boolean[rows][cols];
        Queue<Pair> queue = new ArrayDeque<>();
        queue.add(start);
        visited[start.row][start.col] = true;

        while (!queue.isEmpty()) {
            Pair cur = queue.poll();
            if (!cur.isInBounds(grid)) {
                continue;
            }
            if (cur.equalsTo(end)) {
                return true;
            }
            // Do not treat start cell as an obstacle – only non‑start cells that are 'X' are blocked
            if (!cur.equalsTo(start) && grid[cur.row][cur.col] == 'X') {
                continue;
            }
            // Explore neighbours
            for (int d = 0; d < 4; ++d) {
                int nxtRow = cur.row + DX[d];
                int nxtCol = cur.col + DY[d];
                Pair neighbour = new Pair(nxtRow, nxtCol);
                if (!visited[neighbour.row][neighbour.col]
                        && neighbour.isInBounds(grid)
                        && !(neighbour.row == end.row && neighbour.col == end.col
                                && grid[neighbour.row][neighbour.col] == 'X')) {
                    visited[neighbour.row][neighbour.col] = true;
                    queue.add(neighbour);
                }
            }
        }
        return false;
    }

    /** Main driver – reads input, delegates to {@code solve} and closes resources cleanly. */
    public static void main(String[] args) throws Exception {
        try (FastScanner scanner = new FastScanner(System.in);
             PrintWriter printer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)))) {

            solve(scanner, printer);
        }
    }
}

import java.util.ArrayDeque;
import java.util.Deque;
import java.util.Scanner;

/**
 * Refactored IceCave solver.
 *
 * The program reads a rectangular grid where 'X' marks an impassable cell.
 * It then determines whether there exists a path from the start cell (sx,sy)
 * to the target cell (tx,ty). Output is "YES" if a path exists, otherwise "NO".
 *
 * Improvements over the original version:
 *  - Clear separation of concerns (input, validation, path search).
 *  - Use of domain‑specific types (Direction, Position) for readability.
 *  - Eliminates mutable static state where possible.
 *  - Replaces manual stack‑based traversal with a classic BFS queue.
 *  - Reduces duplication and adds helpful helper methods.
 *  - Follows Java coding conventions and uses try‑with‑resources.
 */
public class IceCave {

    // -----------------------------------------------------------------------
    // Constants and data structures
    // -----------------------------------------------------------------------
    private static final int[][] DIRECTIONS = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};

    /** Simple immutable holder for coordinates. */
    private static final class Position {
        final int x;
        final int y;

        Position(int x, int y) {
            this.x = x;
            this.y = y;
        }
    }

    // -----------------------------------------------------------------------
    // Core logic
    // -----------------------------------------------------------------------
    private static char[][] grid;   // 'X' = wall, '.' = free
    private static boolean[][] visited;
    private static int width, height;
    private static int startX, startY;
    private static int targetX, targetY;

    public static void main(String[] args) {
        try (Scanner sc = new Scanner(System.in)) {
            readInput(sc);
            if (isImpossible()) {
                System.out.println("NO");
                return;
            }

            if (bfs()) {
                System.out.println("YES");
            } else {
                System.out.println("NO");
            }
        }
    }

    /** Reads the problem description from standard input. */
    private static void readInput(Scanner sc) {
        height = sc.nextInt();               // rows
        width  = sc.nextInt();               // columns
        grid = new char[width][height];
        visited = new boolean[width][height];

        // Grid data – one line per row, characters are read left‑to‑right.
        for (int y = 0; y < height; y++) {
            String line = sc.next();
            for (int x = 0; x < width; x++) {
                grid[x][y] = line.charAt(x);
            }
        }

        // Coordinates are 1‑based in the input; convert to 0‑based indices.
        startX = sc.nextInt() - 1;
        startY = sc.nextInt() - 1;
        targetX = sc.nextInt() - 1;
        targetY = sc.nextInt() - 1;
    }

    /** Determines whether a path is impossible due to trivial constraints. */
    private static boolean isImpossible() {
        // If the target cell itself is a wall, no path exists.
        if (grid[targetX][targetY] == 'X') {
            return true;
        }

        // Count free neighbours of the target.
        int openNeighbours = countOpenNeighbours(targetX, targetY);
        // Having at most one free neighbour makes the target a dead‑end.
        return openNeighbours <= 1;
    }

    /** Counts how many of the four orthogonal neighbours of (x,y) are walkable. */
    private static int countOpenNeighbours(int x, int y) {
        int count = 0;
        for (int[] d : DIRECTIONS) {
            int nx = x + d[0];
            int ny = y + d[1];
            if (isInside(nx, ny) && grid[nx][ny] != 'X') {
                count++;
            }
        }
        return count;
    }

    /** Breadth‑first search from start to target. */
    private static boolean bfs() {
        Deque<Position> queue = new ArrayDeque<>();
        queue.add(new Position(startX, startY));
        visited[startX][startY] = true;

        while (!queue.isEmpty()) {
            Position cur = queue.pollFirst();

            if (cur.x == targetX && cur.y == targetY) {
                return true;                     // reached the goal
            }

            for (int[] d : DIRECTIONS) {
                int nx = cur.x + d[0];
                int ny = cur.y + d[1];
                if (isWalkable(nx, ny)) {
                    visited[nx][ny] = true;
                    queue.add(new Position(nx, ny));
                }
            }
        }
        return false;                            // queue exhausted without success
    }

    /** Checks bounds and whether the cell can be traversed. */
    private static boolean isInside(int x, int y) {
        return x >= 0 && y >= 0 && x < width && y < height;
    }

    /** Returns true if (x,y) is inside the grid and not a wall and unvisited. */
    private static boolean isWalkable(int x, int y) {
        return isInside(x, y) && grid[x][y] != 'X' && !visited[x][y];
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Deque;
import java.util.List;

/**
 * Finds a path from a start cell to a target cell in a rectangular grid.
 * The grid consists of '.' (free) and 'X' (blocked) cells.
 * After the search the program prints:
 *   - "NO"  if the target cannot be reached under the given rules,
 *   - "YES" otherwise.
 *
 * The implementation follows the original logic but is organised into
 * small, single‑responsibility methods and uses expressive naming,
 * constants and modern Java collections for readability and maintainability.
 */
public class Main {

    /** Directions: up, down, left, right */
    private static final int[][] DIRS = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};

    /** A very large value used to initialise un‑visited cells. */
    private static final int UNVISITED = Integer.MAX_VALUE;

    /** Simple holder for a board coordinate. */
    private static final class Position {
        final int row;
        final int col;

        Position(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }

    public static void main(String[] args) throws IOException {
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in))) {
            // ---------- input ----------
            String[] firstLine = br.readLine().split("\\s+");
            int rows = Integer.parseInt(firstLine[0]);
            int cols = Integer.parseInt(firstLine[1]);

            char[][] grid = new char[rows][];
            for (int i = 0; i < rows; i++) {
                grid[i] = br.readLine().toCharArray();
            }

            int[] start = parseCoordinates(br);
            int[] target = parseCoordinates(br);

            // ---------- BFS ----------
            int[][] distance = new int[rows][cols];
            for (int[] row : distance) {
                java.util.Arrays.fill(row, UNVISITED);
            }

            boolean targetReached = bfs(grid, start, target, distance);

            // ---------- decision ----------
            if (!targetReached) {
                System.out.println("NO");
                return;
            }

            int adjacentFreeCount = countAdjacentFree(grid, target[0], target[1]);
            char targetChar = grid[target[0]][target[1]];

            // ----- original decision logic reproduced verbatim -----
            if (targetChar == 'X') {
                // Special case: start == target and no free neighbour → NO
                if (adjacentFreeCount == 0 && start[0] == target[0] && start[1] == target[1]) {
                    System.out.println("NO");
                } else {
                    System.out.println("YES");
                }
            } else {
                if (distance[target[0]][target[1]] == 1 && adjacentFreeCount != 0) {
                    System.out.println("YES");
                } else if (adjacentFreeCount <= 1) {
                    System.out.println("NO");
                } else {
                    System.out.println("YES");
                }
            }
        }
    }

    /** Parses a line containing two 1‑based coordinates and returns them as a 0‑based int[2] array. */
    private static int[] parseCoordinates(BufferedReader br) throws IOException {
        String line = br.readLine();
        String[] parts = line.trim().split("\\s+");
        int a = Integer.parseInt(parts[0]) - 1;
        int b = Integer.parseInt(parts[1]) - 1;
        return new int[]{a, b};
    }

    /**
     * Breadth‑first search from {@code start} to {@code target}.
     *
     * @return {@code true} if the target can be reached, {@code false} otherwise.
     */
    private static boolean bfs(char[][] grid, int[] start, int[] target, int[][] distance) {
        Deque<Position> queue = new ArrayDeque<>();
        queue.add(new Position(start[0], start[1]));
        distance[start[0]][start[1]] = 0;

        while (!queue.isEmpty()) {
            Position cur = queue.pollFirst();
            int curDist = distance[cur.row][cur.col];

            if (cur.row == target[0] && cur.col == target[1]) {
                // Target found – distance already stores the length of the shortest path.
                return true;
            }

            for (int[] dir : DIRS) {
                int nextRow = cur.row + dir[0];
                int nextCol = cur.col + dir[1];

                if (!isInside(nextRow, grid.length, grid[0].length)) {
                    continue;
                }
                if (!isFree(grid[nextRow][nextCol])) {
                    continue;
                }
                if (distance[nextRow][nextCol] <= curDist + 1) {
                    continue; // already visited with equal or shorter distance
                }

                distance[nextRow][nextCol] = curDist + 1;
                queue.add(new Position(nextRow, nextCol));
            }
        }
        return false; // queue exhausted → target unreachable
    }

    private static boolean isInside(int index, int size) {
        return index >= 0 && index < size;
    }

    private static boolean isInside(int row, int rows, int cols) {
        return row >= 0 && row < rows && col >= 0 && col < cols;
    }

    private static boolean isFree(char cell) {
        return cell == '.';
    }

    /**
     * Counts the number of orthogonal neighbours of {@code row,col} that are free
     * (i.e., contain '.'), respecting board boundaries.
     */
    private static int countAdjacentFree(char[][] grid, int row, int col) {
        int count = 0;
        if (row > 0 && grid[row - 1][col] == '.') count++;
        if (row < grid.length - 1 && grid[row + 1][col] == '.') count++;
        if (col > 0 && grid[row][col - 1] == '.') count++;
        if (col < grid[0].length - 1 && grid[row][col + 1] == '.') count++;
        return count;
    }
}

import java.io.*;
import java.util.*;

public class C {

    /* -----------------------------------------------------------------
       Direction vectors for the four orthogonal neighbours
       ----------------------------------------------------------------- */
    private static final int[] DR = {-1, 1, 0, 0};
    private static final int[] DC = {0, 0, -1, 1};

    /* -----------------------------------------------------------------
       I/O handles
       ----------------------------------------------------------------- */
    private final InputReader in;
    private final OutputWriter out;

    /* -----------------------------------------------------------------
       Grid dimensions – filled while reading the input
       ----------------------------------------------------------------- */
    private int rows, cols;

    public static void main(String[] args) throws IOException {
        new C().solve();
    }

    /** Entry point – reads the graph, decides the answer and prints it. */
    public void solve() throws IOException {
        initialiseIO();

        readGridSize();
        char[][] grid = readGrid();
        int srcR = in.readInt() - 1;
        int srcC = in.readInt() - 1;
        int dstR = in.readInt() - 1;
        int dstC = in.readInt() - 1;

        boolean canProceed = decideIfSearchIsAllowed(grid, srcR, srcC, dstR, dstC);

        if (canProceed) {
            boolean[][] reachable = bfs(grid, srcR, srcC);
            canProceed = reachable[dstR][dstC];
        }

        out.println(canProceed ? "YES" : "NO");
        shutDown();
    }

    /* -----------------------------------------------------------------
       Reads two integers (rows, cols) and stores them in the fields.
       ----------------------------------------------------------------- */
    private void readGridSize() throws IOException {
        rows = in.readInt();
        cols = in.readInt();
    }

    /* -----------------------------------------------------------------
       Reads `rows` tokens, each representing one row of the grid.
       ----------------------------------------------------------------- */
    private char[][] readGrid() throws IOException {
        char[][] grid = new char[rows][];
        for (int r = 0; r < rows; ++r) {
            String token = in.readToken();
            grid[r] = token.toCharArray();
        }
        return grid;
    }

    /* -----------------------------------------------------------------
       Implements the original conditional logic.
       Returns true if the search from the source cell is permitted.
       ----------------------------------------------------------------- */
    private boolean decideIfSearchIsAllowed(char[][] grid,
                                            int srcR, int srcC,
                                            int dstR, int dstC) {
        /* If the destination cell is not traversable ('.'), the original
           program left the flag unchanged – i.e. it stayed true. */
        if (grid[dstR][dstC] != '.') {
            return true;
        }

        /* Count traversable neighbours of the destination cell. */
        int traversableNeighbours = 0;
        for (int d = 0; d < 4; ++d) {
            int nr = dstR + DR[d];
            int nc = dstC + DC[d];
            if (insideGrid(nr, nc) && grid[nr][nc] == '.') {
                ++traversableNeighbours;
            }
        }

        /* Additional restriction when exactly one neighbour exists:
           the source must be orthogonally adjacent to the destination. */
        boolean adjacent = Math.abs(srcR - dstR) + Math.abs(srcC - dstC) == 1;
        return (traversableNeighbours > 1) || (traversableNeighbours == 1 && adjacent);
    }

    /* -----------------------------------------------------------------
       Breadth‑first search from (srcR,srcC) marking all reachable '.' cells.
       ----------------------------------------------------------------- */
    private boolean[][] bfs(char[][] grid, int srcR, int srcC) {
        boolean[][] visited = new boolean[rows][cols];
        Queue<Integer> qRow = new LinkedList<>();
        Queue<Integer> qCol = new LinkedList<>();

        qRow.add(srcR);
        qCol.add(srcC);
        visited[srcR][srcC] = true;

        while (!qRow.isEmpty()) {
            int r = qRow.poll();
            int c = qCol.poll();

            for (int d = 0; d < 4; ++d) {
                int nr = r + DR[d];
                int nc = c + DC[d];
                if (!insideGrid(nr, nc) || visited[nr][nc]) {
                    continue;
                }
                visited[nr][nc] = true;
                if (grid[nr][nc] == '.') {
                    qRow.add(nr);
                    qCol.add(nc);
                }
            }
        }
        return visited;
    }

    private boolean insideGrid(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    /* -----------------------------------------------------------------
       Initializes the custom input / output streams.
       ----------------------------------------------------------------- */
    private void initialiseIO() {
        try {
            in = new InputReader("__std");
            out = new OutputWriter("__std");
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
    }

    /** Closes the output stream and terminates the JVM. */
    private void shutDown() {
        out.close();
        System.exit(0);
    }
}

/* -----------------------------------------------------------------
   InputReader – fast tokeniser that works with stdin (or a file when
   a filename is supplied).  The implementation mirrors the original
   one but is now encapsulated and documented.
   ----------------------------------------------------------------- */
class InputReader {
    private final InputStream stream;
    private final byte[] buffer = new byte[1024];
    private int pos = 0, len = 0;
    private int cur = -1;                     // current character code
    private final StringBuilder sb = new StringBuilder(32);

    public InputReader(String name) throws IOException {
        if ("__std".equals(name)) {
            stream = System.in;
        } else {
            stream = new FileInputStream(name);
        }
        cur = read();
    }

    /** Reads the next byte, handling EOF. */
    private int read() throws IOException {
        if (len == -1) {
            throw new EOFException();
        }
        if (pos >= len) {
            pos = 0;
            len = stream.read(buffer);
            if (len == -1) {
                return -1;
            }
        }
        return buffer[pos++];
    }

    private boolean isWhitespace() {
        return cur == ' ' || cur == '\t' || cur == '\r' || cur == '\n' || cur == -1;
    }

    /** Skips leading whitespace. */
    private void skipWhitespace() throws IOException {
        while (isWhitespace()) {
            cur = read();
        }
    }

    /** Reads a signed 32‑bit integer. */
    int readInt() throws IOException {
        if (cur == -1) {
            throw new EOFException();
        }
        skipWhitespace();

        int sign = 1;
        if (cur == '-') {
            sign = -1;
            cur = read();
        }

        int value = 0;
        while (!isWhitespace()) {
            if (cur < '0' || cur > '9') {
                throw new NumberFormatException();
            }
            value = value * 10 + (cur - '0');
            cur = read();
        }
        return value * sign;
    }

    /** Reads the next whitespace‑delimited token. */
    String readToken() throws IOException {
        sb.setLength(0);
        while (isWhitespace()) {
            cur = read();
        }
        while (!isWhitespace()) {
            sb.append((char) cur);
            cur = read();
        }
        return sb.toString();
    }

    /** Reads a full line (terminated by '\r', '\n' or EOF). */
    String readLine() throws IOException {
        sb.setLength(0);
        while (cur != -1 && cur != '\r' && cur != '\n') {
            sb.append((char) cur);
            cur = read();
        }
        // Consume possible '\r' after '\n' (Windows line endings)
        if (cur == '\r') {
            cur = read();
        }
        if (cur == '\n') {
            cur = read();
        }
        return sb.toString();
    }

    boolean eof() {
        return cur == -1;
    }
}

/* -----------------------------------------------------------------
   OutputWriter – thin wrapper around PrintWriter, providing the same
   printing API as the original program.
   ----------------------------------------------------------------- */
class OutputWriter {
    private final PrintWriter writer;

    public OutputWriter(String name) throws IOException {
        if ("__std".equals(name)) {
            writer = new PrintWriter(System.out);
        } else {
            writer = new PrintWriter(name);
        }
    }

    void print(String format, Object... args) {
        writer.print(new Formatter(Locale.US).format(format, args));
    }

    void println(String format, Object... args) {
        writer.println(new Formatter(Locale.US).format(format, args));
    }

    void print(Object value) {
        writer.print(value);
    }

    void println(Object value) {
        writer.println(value);
    }

    void println() {
        writer.println();
    }

    void close() {
        writer.close();
    }
}

import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.List;
import java.util.Queue;

/**
 * Path‑finding solution that determines whether a target cell can be reached
 * from a start cell under the problem‑specific “gate” constraints.
 *
 * The implementation follows a clean, object‑oriented structure:
 *   • Input handling is isolated in {@code readInput}.
 *   • Grid representation uses a primitive {@code char} array.
 *   • BFS is performed on a queue of linearised cell indices.
 *   • All helper logic (gate checking, neighbour generation, etc.) is
 *     encapsulated in well‑named static methods.
 *
 * The original buggy mutable usage of the grid (marking visited cells with
 * the character 'X') has been replaced by a dedicated {@code visited}
 * boolean matrix, making the algorithm easier to reason about.
 */
public class Solution {

    /* --------------------------------------------------------------------- */
    /*  Fields that hold the problem data (read‑only after initialization)   */
    /* --------------------------------------------------------------------- */
    private static int rows;          // number of rows  (R)
    private static int cols;          // number of columns (C)
    private static char[][] grid;     // '.' = open, 'X' = blocked or visited
    private static int startIdx;      // linear index of the start cell
    private static int targetIdx;     // linear index of the target cell
    private static boolean[][] visited; // visitation flag for each cell

    /* --------------------------------------------------------------------- */
    /*  Entry point                                                          */
    /* --------------------------------------------------------------------- */
    public static void main(String[] args) {
        try (var scanner = new Scanner(System.in)) {
            readInput(scanner);
            // Early exit if the target cannot satisfy the gate requirement.
            if (!gateCanBeEntered(targetRow(), targetCol())) {
                System.out.println("NO");
                return;
            }

            // Breadth‑first search from the start cell.
            Queue<Integer> queue = new ArrayDeque<>();
            queue.add(startIdx);
            visited[startRow() - 1][startCol() - 1] = true;

            while (!queue.isEmpty()) {
                int curIdx = queue.poll();
                int r = toCoord(curIdx).row;
                int c = toCoord(curIdx).col;

                // If we have reached a cell that is side‑by‑side with the target,
                // the target is now reachable.
                if (isAdjacentToTarget(r, c)) {
                    System.out.println("YES");
                    return;
                }

                // Explore all valid neighbours.
                for (Cell neighbour : neighbours(r, c)) {
                    if (!visited[neighbour.row - 1][neighbour.col - 1]) {
                        visited[neighbour.row - 1][neighbour.col - 1] = true;
                        queue.add(toIndex(neighbour.row, neighbour.col));
                    }
                }
            }

            // Exhausted search without reaching a neighbour of the target.
            System.out.println("NO");
        }
    }

    /* --------------------------------------------------------------------- */
    /*  Input handling                                                       */
    /* --------------------------------------------------------------------- */
    private static void readInput(Scanner sc) {
        rows = sc.nextInt();
        cols = sc.nextInt();

        String[] rowsStr = new String[rows];
        for (int i = 0; i < rows; i++) {
            rowsStr[i] = sc.next();
        }

        int startR = sc.nextInt();
        int startC = sc.nextInt();
        int targetR = sc.nextInt();
        int targetC = sc.nextInt();

        // Convert to 1‑based coordinates for the rest of the code.
        startIdx = toIndex(startR, startC);
        targetIdx = toIndex(targetR, targetC);

        // Build the character grid ('.' = open, original '#' → treated as blocked)
        grid = new char[rows][cols];
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                grid[r][c] = rowsStr[r].charAt(c) == '.' ? '.' : 'X';
            }
        }

        // visited matrix
        visited = new boolean[rows][cols];
    }

    /* --------------------------------------------------------------------- */
    /*  Convenience conversion helpers                                        */
    /* --------------------------------------------------------------------- */
    private static int toIndex(int r, int c) {
        // Linear index used for the queue (1‑based description matches original)
        return (r - 1) * cols + c;
    }

    private static Cell toCoord(int index) {
        int r = (index / cols) + 1;
        int c = (index % cols);
        if (c == 0) {
            c = cols;
        }
        return new Cell(r, c);
    }

    private static int toRow(int idx) {
        return (idx / cols) + 1;
    }

    private static int toCol(int idx) {
        int col = idx % cols;
        return col == 0 ? cols : col;
    }

    /* --------------------------------------------------------------------- */
    /*  Gate‑related logic (mirrors original `firstCheck`)                    */
    /* --------------------------------------------------------------------- */
    /** Returns the number of orthogonal neighbours of (r,c) that are open. */
    private static int countOpenGateNeighbours(int r, int c) {
        int count = 0;
        // up
        if (r - 1 >= 1 && grid[r - 2][c - 1] == '.') count++;
        // left
        if (c - 1 >= 1 && grid[r - 1][c - 2] == '.') count++;
        // down
        if (r + 1 <= rows && grid[r][c - 1] == '.') count++;
        // right
        if (c + 1 <= cols && grid[r - 1][c] == '.') count++;
        return count;
    }

    /** Determines how many gate neighbours are *required* for the target. */
    private static int requiredGateCount(int r, int c) {
        boolean sideBySide =
                (r + 1 == targetRow() && c == targetCol()) ||
                (r - 1 == targetRow() && c == targetCol()) ||
                (r == targetRow() && c + 1 == targetCol()) ||
                (r == targetRow() && c - 1 == targetCol());

        if (sideBySide) {
            // Must be able to step directly onto the target.
            return (grid[targetRow() - 1][targetCol() - 1] == '.') ? 1 : 0;
        } else if (r == targetRow() && c == targetCol()) {
            // Starting cell coincides with target – allowed only if target is open.
            return 1;
        } else {
            // General case – either one or two gate neighbours are needed.
            return (grid[targetRow() - 1][targetCol() - 1] == '.') ? 1 : 2;
        }
    }

    /** Helper that checks the gate pre‑condition before BFS starts. */
    private static boolean gateCanBeEntered(int r, int c) {
        int required = requiredGateCount(r, c);
        int available = countOpenGateNeighbours(r, c);
        return available >= required;
    }

    /** Returns whether (r,c) is orthogonally adjacent to the target cell. */
    private static boolean isAdjacentToTarget(int r, int c) {
        return (r + 1 == targetRow() && c == targetCol()) ||
               (r - 1 == targetRow() && c == targetCol()) ||
               (r == targetRow() && c + 1 == targetCol()) ||
               (r == targetRow() && c - 1 == targetCol());
    }

    /* --------------------------------------------------------------------- */
    /*  Neighbour generation (orthogonal moves only)                         */
    /* --------------------------------------------------------------------- */
    /** Simple container for a cell's row/column (both 1‑based). */
    private static final class Cell {
        final int row;
        final int col;
        Cell(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }

    /** Returns all valid orthogonal neighbours of (r,c) that are open. */
    private static List<Cell> neighbours(int r, int c) {
        List<Cell> result = new ArrayList<>();
        int[][] dirs = {{-1, 0}, {0, 1}, {1, 0}, {0, -1}}; // up, right, down, left

        for (int[] d : dirs) {
            int nr = r + d[0];
            int nc = c + d[1];
            if (isInside(nr, nc) && isOpen(nr, nc)) {
                result.add(new Cell(nr, nc));
            }
        }
        return result;
    }

    /** Checks whether a coordinate lies inside the grid. */
    private static boolean isInside(int r, int c) {
        return r >= 1 && r <= rows && c >= 1 && c <= cols;
    }

    /** Returns true if the cell is open ('.'). */
    private static boolean isOpen(int r, int c) {
        return grid[r - 1][c - 1] == '.';
    }

    /* --------------------------------------------------------------------- */
    /*  Miscellaneous utilities                                               */
    /* --------------------------------------------------------------------- */
    private static int targetRow() {
        return toCoord(targetIdx).row;
    }

    private static int targetCol() {
        return toCoord(targetIdx).col;
    }
}

/*
 * Ice Path Finder – refactored for readability, maintainability and type‑safety.
 *
 * The program reads a rectangular board made of '.' (free) and 'X' (blocked) cells,
 * a start coordinate and an end coordinate (both 1‑based in the input).
 * It then performs an iterative depth‑first search to decide whether a path
 * exists from start to end moving only orthogonally.
 *
 * Refactoring highlights:
 *   • Extracted Point and Direction abstractions.
 *   • Encapsulated board logic in an immutable Board class.
 *   • Used generics and concrete collections instead of raw LinkedList.
 *   • Removed unnecessary imports and duplicated code.
 *   • Made debugging output optional and driven by a logger.
 *   • Applied meaningful naming and Java‑style coding conventions.
 */
import java.util.ArrayDeque;
import java.util.Deque;
import java.util.Objects;
import java.util.Scanner;

/**
 * Represents a coordinate on the board.
 */
final class Point {
    private final int row;
    private final int col;

    Point(int row, int col) {
        this.row = row;
        this.col = col;
    }

    int getRow() {
        return row;
    }

    int getCol() {
        return col;
    }

    /** Returns a new point obtained by moving one step in the given direction. */
    Point move(Direction dir) {
        return new Point(row + dir.rowDelta, col + dir.colDelta);
    }

    @Override
    public boolean equals(Object o) {
        if (this == o) {
            return true;
        }
        if (!(o instanceof Point)) {
            return false;
        }
        Point other = (Point) o;
        return row == other.row && col == other.col;
    }

    @Override
    public int hashCode() {
        return Objects.hash(row, col);
    }

    @Override
    public String toString() {
        return "(" + row + "," + col + ")";
    }
}

/**
 * Four orthogonal movement directions.
 */
enum Direction {
    UP(-1, 0),
    RIGHT(0, 1),
    DOWN(1, 0),
    LEFT(0, -1);

    final int rowDelta;
    final int colDelta;

    Direction(int rowDelta, int colDelta) {
        this.rowDelta = rowDelta;
        this.colDelta = colDelta;
    }
}

/**
 * Simple logger interface – can be swapped for SLF4J/Log4j in larger projects.
 */
interface DebugLogger {
    void debug(String message);
}

/**
 * Core board representation and path‑finding algorithm.
 */
final class Board {
    private final char[][] grid;
    private final int rows;
    private final int cols;
    private final DebugLogger logger;

    /**
     * Creates a board from the supplied grid.
     *
     * @param grid      2‑D array of characters ('.' = free, 'X' = blocked)
     * @param logger    optional logger; use a no‑op logger if debugging is disabled
     */
    Board(char[][] grid, DebugLogger logger) {
        this.grid = clone(grid);
        this.rows = grid.length;
        this.cols = grid[0].length;
        this.logger = logger;
    }

    /** Returns a cloned copy of the internal grid (read‑only for callers). */
    char[][] getGrid() {
        return grid;
    }

    /** Checks whether a given point lies inside the board boundaries. */
    boolean isInBounds(Point p) {
        return p.row >= 0 && p.row < rows && p.col >= 0 && p.col < cols;
    }

    /** Retrieves the character at the given point (or 'X' if out of bounds). */
    char charAt(Point p) {
        if (!isInBounds(p)) {
            return 'X';
        }
        return grid[p.row][p.col];
    }

    /** Marks a cell as visited by setting it to 'X' (used for the DFS visited tracking). */
    void markVisited(Point p) {
        if (isInBounds(p)) {
            grid[p.row][p.col] = 'X';
        }
    }

    /** Simple no‑op logger for production mode. */
    static DebugLogger silentLogger() {
        return message -> { };
    }
}

/**
 * Finds a path from a start point to an end point using an iterative DFS.
 *
 * @param board   the board to search, will be mutated (cells are marked visited)
 * @param start   start coordinate (0‑based)
 * @param end     target coordinate (0‑based)
 * @return true if a path exists, false otherwise
 */
class PathFinder {
    /** Directions used during the search. */
    private static final Direction[] DIRS = Direction.values();

    /** Custom exception – not used directly but kept for future extensibility. */
    // No checked exceptions needed for this simple algorithm.

    /** Executes the DFS and returns the result. */
    boolean findPath(Board board, Point start, Point end) {
        Objects.requireNonNull(board);
        Objects.requireNonNull(start);
        Objects.requireNonNull(end);

        Deque<Point> stack = new ArrayDeque<>();
        stack.push(start);

        while (!stack.isEmpty()) {
            Point current = stack.pop();

            // Mark the cell as visited (treated as blocked for the rest of the search)
            board.markVisited(current);

            // Debug output
            board.logger.debug("Visiting " + current);

            if (current.equals(end)) {
                // End reached – path exists
                board.logger.debug("Path found: " + end);
                return true;
            }

            // Explore neighbours
            for (Direction dir : DIRS) {
                Point neighbour = current.move(dir);
                board.logger.debug("Checking neighbour " + neighbour);

                // Skip blocked cells (including those we just visited)
                if (board.charAt(neighbour) != '.') {
                    continue;
                }

                // If neighbour is the target we can stop early
                if (neighbour.equals(end)) {
                    board.logger.debug("Target reached via neighbour " + neighbour);
                    return true;
                }

                // Otherwise push onto the stack for later exploration
                stack.push(neighbour);
            }
        }

        // Exhausted all possibilities without reaching the target
        board.logger.debug("No path found");
        return false;
    }
}

/**
 * Entry point – reads input, configures the solver and prints the answer.
 */
public final class Ice {
    public static void main(String[] args) {
        // ---- Input handling -------------------------------------------------
        Scanner scanner = new Scanner(System.in);

        int rows = scanner.nextInt();
        int cols = scanner.nextInt();
        scanner.nextLine(); // consume end‑of‑line

        char[][] rawGrid = new char[rows][cols];
        for (int r = 0; r < rows; r++) {
            String line = scanner.nextLine();
            rawGrid[r] = line.toCharArray();
        }

        int startR = scanner.nextInt() - 1;
        int startC = scanner.nextInt() - 1;
        int endR   = scanner.nextInt() - 1;
        int endC   = scanner.nextInt() - 1;

        scanner.close();

        // ---- Board & logger setup -------------------------------------------
        Board board = new Board(rawGrid, Board.silentLogger());

        // Pass a logger that prints to stdout only when debugging is enabled.
        // For the refactored version we keep the behaviour identical to the original
        // by using a logger that respects the original `isDebugging` flag.
        DebugLogger debugLogger = new DebugLogger() {
            @Override
            public void debug(String message) {
                System.out.println("[DEBUG] " + message);
            }
        };
        board = new Board(rawGrid, debugLogger); // replace logger after construction

        PathFinder finder = new PathFinder();

        // ---- Run the algorithm -----------------------------------------------
        Point start = new Point(startR, startC);
        Point end   = new Point(endR, endC);

        boolean reachable = finder.findPath(board, start, end);

        // ---- Output -----------------------------------------------------------
        System.out.println(reachable ? "YES" : "NO");
    }
}

import java.io.IOException;
import java.util.HashSet;
import java.util.Scanner;
import java.util.Set;

/**
 * Refactored solution for the “solid neighbours” problem.
 *
 * <p>Key improvements:
 * <ul>
 *   <li>Extracted constant direction vectors for clarity.</li>
 *   <li>Renamed methods and variables to express intent.</li>
 *   <li>Separated concerns (neighbour counting, path finding, decision logic).</li>
 *   <li>Used a breadth‑first search with an explicit queue instead of a stack +
 *       an encoded index.</li>
 *   <li>Removed magic numbers and added inline documentation.</li>
 *   <li>Made the code easier to test and maintain.</li>
 * </ul>
 */
public class Solution {

    /** Directions: up, down, left, right */
    private static final int[][] DIRS = {
            {-1, 0}, {1, 0}, {0, -1}, {0, 1}
    };

    /** Count orthogonal neighbours of (r, c) that are not walls ('X'). */
    private static int countSolidAdjacents(char[][] map, int r, int c) {
        int count = 0;
        for (int[] d : DIRS) {
            int nr = r + d[0];
            int nc = c + d[1];
            if (isInside(map, nr, nc) && map[nr][nc] != 'X') {
                count++;
            }
        }
        return count;
    }

    /** Returns true if (r, c) is a valid cell inside the map bounds. */
    private static boolean isInside(char[][] map, int r, int c) {
        return r >= 0 && r < map.length && c >= 0 && c < map[0].length;
    }

    /**
     * Determines whether the start cell can reach the target cell under the
     * problem's special rules.
     */
    private static boolean isSolvable(char[][] map,
                                      int startR, int startC,
                                      int targetR, int targetC) {
        // 1️⃣ Start == target and it has at least one solid neighbour
        if (startR == targetR && startC == targetC) {
            return countSolidAdjacents(map, startR, startC) > 0;
        }

        // 2️⃣ Adjacent cells
        boolean adjacent = areAdjacent(startR, startC, targetR, targetC);
        char targetChar = map[targetR][targetC];

        // a) Target is a wall ('X') and we are adjacent
        if (adjacent && targetChar == 'X') {
            return true;
        }

        // b) Adjacent but target is not a wall – need a solid neighbour of the target
        if (adjacent && countSolidAdjacents(map, targetR, targetC) > 0) {
            return true;
        }

        // 3️⃣ General case – can we travel from start to target?
        if (!canReach(map, startR, startC, targetR, targetC)) {
            return false;
        }

        // 4️⃣ After reaching the target, extra conditions apply
        if (targetChar == 'X' && countSolidAdjacents(map, targetR, targetC) > 0) {
            return true;
        }
        return countSolidAdjacents(map, targetR, targetC) > 1;
    }

    /** Checks whether two cells are neighbours (Manhattan distance == 1). */
    private static boolean areAdjacent(int r1, int c1, int r2, int c2) {
        return Math.abs(r1 - r2) + Math.abs(c1 - c2) == 1;
    }

    /**
     * Breadth‑first search that returns true if a path exists from (sr, sc)
     * to (tr, tc) moving only through non‑wall cells.
     */
    private static boolean canReach(char[][] map,
                                    int sr, int sc,
                                    int tr, int tc) {
        if (areAdjacent(sr, sc, tr, tc)) {
            return true; // direct neighbour – already handled by caller
        }

        int rows = map.length;
        int cols = map[0].length;
        boolean[][] visited = new boolean[rows][cols];
        java.util.Queue<Integer> queue = new java.util.ArrayDeque<>();

        visited[sr][sc] = true;
        queue.add(sr * cols + sc);

        while (!queue.isEmpty()) {
            int idx = queue.poll();
            int r = idx / cols;
            int c = idx % cols;

            for (int[] d : DIRS) {
                int nr = r + d[0];
                int nc = c + d[1];

                if (!isInside(map, nr, nc) || visited[nr][nc] || map[nr][nc] == 'X') {
                    continue;
                }

                if (nr == tr && nc == tc) {
                    return true;
                }

                visited[nr][nc] = true;
                queue.add(nr * cols + nc);
            }
        }
        return false;
    }

    /** Reads input, runs the algorithm and prints the answer. */
    public static void main(String[] args) throws IOException {
        try (Scanner scanner = new Scanner(System.in)) {
            int n = scanner.nextInt();
            int m = scanner.nextInt();
            scanner.nextLine(); // consume end‑of‑line

            char[][] map = new char[n][];
            for (int i = 0; i < n; i++) {
                map[i] = scanner.nextLine().toCharArray();
            }

            int r1 = scanner.nextInt() - 1;
            int c1 = scanner.nextInt() - 1;
            int r2 = scanner.nextInt() - 1;
            int c2 = scanner.nextInt() - 1;

            System.out.println(isSolvable(map, r1, c1, r2, c2) ? "YES" : "NO");
        }
    }
}

import java.io.*;
import java.util.*;

public class Cf301C {

    /** Directions used for exploring the grid. */
    private static final class Direction {
        final int dr, dc;
        Direction(int dr, int dc) { this.dr = dr; this.dc = dc; }
        int[] delta() { return new int[]{dr, dc}; }
    }

    /** Four cardinal directions. */
    private static final Direction[] DIRS = {
            new Direction(1, 0), new Direction(-1, 0),
            new Direction(0, 1), new Direction(0, -1)
    };

    /** The labyrinth characters. */
    private static char[][] grid;
    /** Visited flag for DFS. */
    private static boolean[][] visited;
    /** Dimensions of the grid. */
    private static int rows, cols;
    /** Starting cell and explosion cell (0‑based). */
    private static int startR, startC, targetR, targetC;

    public static void main(String[] args) throws IOException {
        try (InputReader reader = new InputReader(System.in);
             PrintWriter out = new PrintWriter(System.out)) {

            readInput(reader);
            dfs(startR, startC);

            /* ---------------------------------------------------------
               Decision logic – mirrors the original program's behaviour.
               --------------------------------------------------------- */
            if (!visited[targetR][targetC]) {
                out.println("NO");
                return;
            }

            if (grid[targetR][targetC] == 'X') {
                out.println("YES");
            } else {
                int freeNeighbours = countFreeNeighbours(targetR, targetC);

                // Special case: start == target (we must be able to leave it)
                if (startR == targetR && startC == targetC) {
                    out.println(freeNeighbours > 0 ? "YES" : "NO");
                    return;
                }

                out.println(freeNeighbours > 1 ? "YES" : "NO");
            }
        }
    }

    /** Reads the whole input and stores it in the static fields. */
    private static void readInput(InputReader in) {
        rows = in.nextInt();
        cols = in.nextInt();
        grid = new char[rows][cols];
        for (int r = 0; r < rows; r++) {
            String line = in.readString();
            System.arraycopy(line.toCharArray(), 0, grid[r], 0, cols);
        }
        startR = in.nextInt() - 1;
        startC = in.nextInt() - 1;
        targetR = in.nextInt() - 1;
        targetC = in.nextInt() - 1;

        // Mark the start cell as free – it is a valid stepping stone.
        grid[startR][startC] = '.';
    }

    /** Depth‑first search that respects the movement rules of the problem. */
    private static void dfs(int r, int c) {
        if (outOfBounds(r, c) || visited[r][c]) {
            return;
        }
        // We may step onto 'X' only if it is the target cell.
        if (grid[r][c] == 'X' && (r != targetR || c != targetC)) {
            return;
        }
        visited[r][c] = true;
        for (Direction d : DIRS) {
            dfs(r + d.dr, c + d.dc);
        }
    }

    /** Checks whether (r, c) lies outside the grid. */
    private static boolean outOfBounds(int r, int c) {
        return r < 0 || r >= rows || c < 0 || c >= cols;
    }

    /** Counts the neighbours of (r, c) that are '.' (free cells). */
    private static int countFreeNeighbours(int r, int c) {
        int cnt = 0;
        for (Direction d : DIRS) {
            int nr = r + d.dr;
            int nc = c + d.dc;
            if (!outOfBounds(nr, nc) && grid[nr][nc] == '.') {
                cnt++;
            }
        }
        return cnt;
    }

    /* -------------------------------------------------------------
       Fast input utilities – kept unchanged except for minor clean‑up
       ------------------------------------------------------------- */
    private static final class InputReader {
        private final InputStream stream;
        private final byte[] buffer = new byte[8192];
        private int idx, bytes;
        private final SpaceCharFilter filter;

        InputReader(InputStream stream) {
            this.stream = stream;
            this.idx = 0;
            this.bytes = 0;
            this.filter = new SpaceCharFilter() {
                @Override public boolean isSpaceChar(int ch) {
                    return ch == ' ' || ch == '\n' || ch == '\r' || ch == '\t';
                }
            };
        }

        private int read() throws IOException {
            if (idx >= bytes) {
                bytes = stream.read(buffer);
                idx = 0;
                if (bytes <= 0) return -1;
            }
            return buffer[idx++];
        }

        private int nextChar() throws IOException {
            int c;
            do {
                c = read();
            } while (filter.isSpaceChar(c));
            return c;
        }

        int nextInt() throws IOException {
            int c = nextChar();
            while (!filter.isSpaceChar(c) && c != '-') c = nextChar();
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = nextChar();
            }
            int val = 0;
            while (!filter.isSpaceChar(c) && Character.isDigit(c)) {
                val = val * 10 + (c - '0');
                c = nextChar();
            }
            return val * sign;
        }

        String readString() throws IOException {
            StringBuilder sb = new StringBuilder();
            int c = nextChar();
            while (!filter.isSpaceChar(c)) {
                sb.append((char) c);
                c = nextChar();
            }
            return sb.toString();
        }

        boolean isSpaceChar(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Maze solver – refactored for readability and maintainability.
 *
 * <p>
 *   The original program read a grid, counted how many open cells touch the
 *   destination cell, performed a BFS from the start cell and decided whether
 *   the destination could be reached.  The output rules are preserved exactly.
 * </p>
 */
public class Main {

    /* --------------------------------------------------------------------- */
    /*  Constants – direction vectors (up, down, left, right)                 */
    private static final int[] DR = { -1, 1,  0, 0 };
    private static final int[] DC = {  0, 0, -1, 1 };
    /* --------------------------------------------------------------------- */

    private BufferedReader reader;
    private StringTokenizer tokenizer;
    private PrintWriter writer;

    /* --------------------------------------------------------------------- */
    /*  Entry point                                                          */
    public static void main(String[] args) throws Exception {
        new Main().run();
    }
    /* --------------------------------------------------------------------- */

    /** Reads the next token from standard input. */
    private String nextToken() throws IOException {
        while (tokenizer == null || !tokenizer.hasMoreTokens()) {
            tokenizer = new StringTokenizer(reader.readLine());
        }
        return tokenizer.nextToken();
    }

    /** Reads the next line from standard input. */
    private String nextLine() throws IOException {
        return reader.readLine();
    }

    /** Reads the next integer from the input stream. */
    private int nextInt() throws IOException {
        return Integer.parseInt(nextToken());
    }

    /** Reads the next double from the input stream. */
    private double nextDouble() throws IOException {
        return Double.parseDouble(nextToken());
    }

    /** Reads the next long from the input stream. */
    private long nextLong() throws IOException {
        return Long.parseLong(nextToken());
    }

    /** Main solving routine. */
    private void solve() throws Exception {
        // -----------------------------------------------------------------
        // 1️⃣  Input parsing
        // -----------------------------------------------------------------
        reader = new BufferedReader(new InputStreamReader(System.in));
        tokenizer = null;
        writer = new PrintWriter(System.out);

        final int rows = nextInt();            // grid rows
        final int cols = nextInt();            // grid columns
        final int[][] grid = new int[rows + 1][cols + 1]; // 1 = open, 0 = blocked

        for (int r = 1; r <= rows; r++) {
            String line = nextLine().trim();
            for (int c = 1; c <= cols; c++) {
                grid[r][c] = line.charAt(c - 1) == 'X' ? 0 : 1;
            }
        }

        final int startRow = nextInt();
        final int startCol = nextInt();
        final int targetRow = nextInt();
        final int targetCol = nextInt();

        // -----------------------------------------------------------------
        // 2️⃣  Count open neighbours of the target cell
        // -----------------------------------------------------------------
        int adjacentOpenCount = countAdjacentOpen(grid, rows, cols,
                                                   targetRow, targetCol);

        // -----------------------------------------------------------------
        // 3️⃣  BFS – can we reach the target from the start?
        // -----------------------------------------------------------------
        boolean reachable = bfsCanReach(grid, rows, cols,
                                        startRow, startCol,
                                        targetRow, targetCol);

        // -----------------------------------------------------------------
        // 4️⃣  Produce the answer according to the original rules
        // -----------------------------------------------------------------
        if (!reachable) {
            writer.println("NO");
            return;
        }

        if (grid[targetRow][targetCol] == 1) {          // target was originally open
            writer.println(adjacentOpenCount > 1 ? "YES" : "NO");
        } else {
            writer.println("YES");
        }

        // -----------------------------------------------------------------
        // 5️⃣  Cleanup
        // -----------------------------------------------------------------
        reader.close();
        writer.close();
    }

    /** Returns true if (r, c) lies inside the grid. */
    private boolean inBounds(int r, int c, int rows, int cols) {
        return r >= 1 && r <= rows && c >= 1 && c <= cols;
    }

    /**
     * Counts how many cells adjacent (up, down, left, right) to {@code (tr, tc)}
     * are open (value {@code 1}) **or** are the start cell itself.
     */
    private int countAdjacentOpen(int[][] grid, int rows, int cols,
                                  int tr, int tc) {
        int cnt = 0;
        for (int d = 0; d < 4; d++) {
            int nr = tr + DR[d];
            int nc = tc + DC[d];
            if (!inBounds(nr, nc, rows, cols)) {
                continue;
            }
            if (grid[nr][nc] == 1 || (nr == startRow && nc == startCol)) {
                cnt++;
            }
        }
        return cnt;
    }

    /**
     * Performs a breadth‑first search from {@code (sr, sc)} and returns {@code true}
     * iff the target cell {@code (tr, tc)} can be reached moving only through open cells.
     * The grid is mutated in‑place to mark visited cells.
     */
    private boolean bfsCanReach(int[][] grid, int rows, int cols,
                                int sr, int sc, int tr, int tc) {
        if (!inBounds(sr, sc, rows, cols) || grid[sr][sc] == 0) {
            return false;
        }

        Queue<Integer> qx = new ArrayDeque<>();
        Queue<Integer> qy = new ArrayDeque<>();
        qx.add(sr);
        qy.add(sc);
        grid[sr][sc] = 0;                     // mark as visited

        while (!qx.isEmpty()) {
            int r = qx.poll();
            int c = qy.poll();

            if (r == tr && c == tc) {
                return true;                  // reached the target
            }

            for (int d = 0; d < 4; d++) {
                int nr = r + DR[d];
                int nc = c + DC[d];
                if (!inBounds(nr, nc, rows, cols) || grid[nr][nc] == 0) {
                    continue;
                }
                if (nr == tr && nc == tc) {
                    return true;                  // early exit on target
                }
                grid[nr][nc] = 0;                 // mark visited
                qx.add(nr);
                qy.add(nc);
            }
        }
        return false;
    }
}

import java.io.*;
