/* --------------------------------------------------------------
 *  Solver – contains all problem‑specific logic
 * -------------------------------------------------------------- */
class Solver {

    /** Direction vectors: up, left, down, right */
    private static final int[][] DIRS = {{-1, 0}, {0, -1}, {1, 0}, {0, 1}};

    /** Grid dimensions and data */
    private int rows, cols;
    private char[][] grid;

    /** Visited marker */
    private boolean[][] visited;

    /** Start and target cell (0‑based indexes) */
    private int startR, startC, targetR, targetC;

    /** Wrapper around the custom Reader class */
    private final Reader input;

    /** PrintWriter used for output */
    private final PrintWriter out;

    /** Small container for a cell position */
    private static final class Pair {
        final int x, y;
        Pair(int x, int y) { this.x = x; this.y = y; }
    }

    /** Constructor that receives the external Reader and PrintWriter */
    public Solver(Reader input, PrintWriter out) {
        this.input = input;
        this.out = out;
    }

    /** Main solving routine – kept compatible with the original signature */
    public void solve(int testCaseNumber, Reader in, PrintWriter out) {
        try {
            readInput();
            if (!hasPath()) {
                out.println("NO");
            } else {
                out.println("YES");
            }
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
    }

    /** Reads the whole input and stores it in the internal fields */
    private void readInput() throws IOException {
        StringTokenizer tok = new StringTokenizer(input.rl());

        rows = Integer.parseInt(tok.nextToken());
        cols = Integer.parseInt(tok.nextToken());

        grid = new char[rows][];
        visited = new boolean[rows][cols];

        for (int i = 0; i < rows; i++) {
            grid[i] = input.rl().toCharArray();
        }

        startR = Integer.parseInt(input.rl()) - 1;
        startC = Integer.parseInt(input.rl()) - 1;
        targetR = Integer.parseInt(input.rl()) - 1;
        targetC = Integer.parseInt(input.rl()) - 1;
    }

    /** Determines whether a valid path from start to target exists */
    private boolean hasPath() {
        // ----- start equals target -------------------------------------------------
        if (startR == targetR && startC == targetC) {
            // Need at least one adjacent empty cell to step onto
            for (int[] d : DIRS) {
                int nr = startR + d[0];
                int nc = startC + d[1];
                if (isInside(nr, nc) && grid[nr][nc] == '.') {
                    return true;
                }
            }
            return false;
        }

        // ----- target is blocked ---------------------------------------------------
        if (grid[targetR][targetC] == 'X') {
            return false; // cannot finish on a blocked cell
        }

        // ----- need at least two ways to enter the target -------------------------
        int enteringNeighbours = 0;
        for (int[] d : DIRS) {
            int nr = targetR + d[0];
            int nc = targetC + d[1];
            if (isInside(nr, nc) && (grid[nr][nc] == '.' || (nr == startR && nc == startC))) {
                enteringNeighbours++;
            }
        }
        if (enteringNeighbours < 2) {
            return false;
        }

        // ----- breadth‑first search from the start ---------------------------------
        ArrayDeque<Pair> queue = new ArrayDeque<>();
        queue.add(new Pair(startR, startC));
        visited[startR][startC] = true;

        while (!queue.isEmpty()) {
            Pair cur = queue.pollFirst();
            for (int[] d : DIRS) {
                int nr = cur.x + d[0];
                int nc = cur.y + d[1];
                if (isInside(nr, nc) && !visited[nr][nc] && grid[nr][nc] != 'X') {
                    visited[nr][nc] = true;
                    queue.add(new Pair(nr, nc));
                }
            }
        }

        // ----- destination must be adjacent to any visited cell --------------------
        for (int[] d : DIRS) {
            int nr = targetR + d[0];
            int nc = targetC + d[1];
            if (isInside(nr, nc) && visited[nr][nc]) {
                return true;
            }
        }
        return false;
    }

    /** Simple bounds check */
    private boolean isInside(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }
}

