import java.util.List;
import java.util.Scanner;

/**
 * IceCave – determines whether an ice‑cave traversal is possible.
 * <p>
 * The program reads a rectangular board ( '#' – obstacle, '.' – free cell ),
 * two cells (start and exit) and prints:
 * <ul>
 *   <li>"YES" – if the exit can be reached under the game rules,</li>
 *   <li>"NO"  – otherwise.</li>
 * </ul>
 * </p>
 * <p>
 * The original implementation mixed input handling, game logic, and DFS
 * inside one monolithic {@code main} method.  The refactor separates concerns
 * into small, well‑named private methods, uses constants and descriptive
 * variable names, and applies modern Java idioms (try‑with‑resources,
 * immutable direction vectors, etc.) to improve readability and maintainability.
 * </p>
 */
public class IceCave {

    /* --------------------------------------------------------------------- */
    /*  Constants & shared state                                               */
    /* --------------------------------------------------------------------- */

    private static final Scanner SCANNER = new Scanner(System.in);

    private static int rows;
    private static int cols;
    private static char[][] board;
    private static boolean[][] visited;

    /** Four possible movement directions (right, down, left, up). */
    private static final List<int[]> DIRS = List.of(
            new int[]{0, 1},
            new int[]{1, 0},
            new int[]{0, -1},
            new int(){-1, 0}
    );

    /* --------------------------------------------------------------------- */
    /*  Entry point                                                            */
    /* --------------------------------------------------------------------- */

    public static void main(String[] args) {
        readInput();
        solve();
    }

    /* --------------------------------------------------------------------- */
    /*  Input handling                                                         */
    /* --------------------------------------------------------------------- */

    private static void readInput() {
        rows = SCANNER.nextInt();
        cols = SCANNER.nextInt();

        board = new char[rows][];
        for (int r = 0; r < rows; r++) {
            String line = SCANNER.next();
            board[r] = line.toCharArray();
        }

        int sr = SCANNER.nextInt() - 1;   // start row
        int sc = SCANNER.nextInt() - 1;   // start column
        int er = SCANNER.nextInt() - 1;   // exit row
        int ec = SCANNER.nextInt() - 1;   // exit column

        // Preserve the original exit character (may be 'X' or '.' depending on the board)
        char originalExitChar = board[er][ec];

        // The rules treat both the start and the exit as empty cells.
        board[sr][sc] = '.';
        board[er][ec] = '.';

        performAnalysis(sr, sc, er, ec, originalExitChar);
    }

    /* --------------------------------------------------------------------- */
    /*  Core algorithm                                                         */
    /* --------------------------------------------------------------------- */

    private static void performAnalysis(int sr, int sc, int er, int ec, char originalExitChar) {
        // --- Case 1: start and exit are the same cell -----------------------
        if (sr == er && sc == ec) {
            int adjacentEmpty = countAdjacentEmptyCells(er, ec);
            System.out.println(adjacentEmpty > 0 ? "YES" : "NO");
            return;
        }

        // --- Case 2: normal case – BFS/DFS from start -----------------------
        visited = new boolean[rows][cols];
        dfs(sr, sc);

        boolean exitReachable = visited[er][ec];
        if (exitReachable) {
            int accessibleNeighbors = countAdjacentEmptyCells(er, ec);
            if (accessibleNeighbors <= 1) {
                // According to the original specification, when the exit has
                // at most one free neighbour the answer depends on the original
                // exit cell symbol.
                System.out.println(originalExitChar == 'X' ? "YES" : "NO");
            } else {
                System.out.println("YES");
            }
        } else {
            System.out.println("NO");
        }
    }

    /* --------------------------------------------------------------------- */
    /*  Helper methods                                                          */
    /* --------------------------------------------------------------------- */

    /** Counts neighboring cells around (r,c) that are free ('.'). */
    private static int countAdjacentEmptyCells(int r, int c) {
        int count = 0;
        for (int[] d : DIRS) {
            int nr = r + d[0];
            int nc = c + d[1];
            if (isInBounds(nr, nc) && board[nr][nc] == '.') {
                count++;
            }
        }
        return count;
    }

    /** Returns true if (r,c) lies inside the board. */
    private static boolean isInBounds(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    /** Depth‑first search from the current cell, marking all reachable '.' cells. */
    private static void dfs(int r, int c) {
        visited[r][c] = true;
        for (int[] d : DIRS) {
            int nr = r + d[0];
            int nc = c + d[1];
            if (isInBounds(nr, nc) && board[nr][nc] == '.' && !visited[nr][nc]) {
                dfs(nr, nc);
            }
        }
    }
}

import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.List;
import java.util.Queue;
import java.util.Scanner;

/**
 * Reads a rectangular grid, builds an adjacency graph of its cells and
 * determines whether there exists a path from the start cell to the end cell
 * that visits the end cell at least once after having left the start cell.
 *
 * The refactor emphasizes:
 *   • Clear naming and type‑safe collections
 *   • Separation of concerns (input, graph construction, BFS, helper utilities)
 *   • Small, single‑responsibility methods
 *   • Defensive checks and early exits
 */
public class Main {

    /** Symbol for a traversable cell. */
    private static final char OPEN = '.';
    /** Symbol for a blocked cell. */
    private static final char BLOCKED = 'X';

    public static void main(String[] args) throws Exception {
        try (Scanner scanner = new Scanner(System.in)) {
            int rows = scanner.nextInt();
            int cols = scanner.nextInt();
            scanner.nextLine(); // discard end‑of‑line

            // A single cell grid can never contain a valid path.
            if (rows * cols == 1) {
                System.out.println("NO");
                return;
            }

            // -----------------------------------------------------------------
            // 1️⃣  Read the grid (row‑major, i.e. grid[row][col])
            // -----------------------------------------------------------------
            char[][] grid = readGrid(scanner, rows, cols);

            // -----------------------------------------------------------------
            // 2️⃣  Read coordinates (they are 1‑based in the original input)
            // -----------------------------------------------------------------
            int startCol = scanner.nextInt() - 1; // xStart
            int startRow = scanner.nextInt() - 1; // yStart
            int endCol   = scanner.nextInt() - 1; // xEnd
            int endRow   = scanner.nextInt() - 1; // yEnd

            int startIdx = index(startRow, startCol, cols);
            int endIdx   = index(endRow,   endCol,   cols);

            // -----------------------------------------------------------------
            // 3️⃣  Validate that the destination cell is open and has enough
            //      intact neighbours – otherwise a path is impossible.
            // -----------------------------------------------------------------
            if (grid[endRow][endCol] == OPEN && 
                insufficientIntactNeighbours(endRow, endCol, grid, cols, rows, startIdx)) {
                System.out.println("NO");
                return;
            }

            // -----------------------------------------------------------------
            // 4️⃣  Build adjacency list for the grid.
            // -----------------------------------------------------------------
            @SuppressWarnings("unchecked")
            List<Integer>[] adjacency = new List[rows * cols];
            for (int i = 0; i < rows * cols; i++) {
                adjacency[i] = new ArrayList<>();
            }
            buildAdjacency(adjacency, rows, cols);

            // -----------------------------------------------------------------
            // 5️⃣  Run a modified BFS that respects the original semantics:
            //        we must reach the end cell *after* having left the start.
            // -----------------------------------------------------------------
            boolean foundPath = bfsFindPath(
                    startIdx, endIdx, adjacency, rows * cols);

            System.out.println(foundPath ? "YES" : "NO");
        }
    }

    // -------------------------------------------------------------------------
    // Helper: read the grid into a[row][col] (row‑major)
    // -------------------------------------------------------------------------
    private static char[][] readGrid(Scanner scanner, int rows, int cols) {
        char[][] grid = new char[rows][cols];
        for (int r = 0; r < rows; r++) {
            String line = scanner.nextLine();
            for (int c = 0; c < cols; c++) {
                grid[r][c] = line.charAt(c);
            }
        }
        return grid;
    }

    // -------------------------------------------------------------------------
    // Helper: map (row, col) → linear index
    // -------------------------------------------------------------------------
    private static int index(int row, int col, int cols) {
        return row * cols + col;
    }

    // -------------------------------------------------------------------------
    // Helper: construct adjacency list for the grid.
    // -------------------------------------------------------------------------
    private static void buildAdjacency(List<Integer>[] adjacency, int rows, int cols) {
        int[] dr = {-1, 1, 0, 0};
        int[] dc = {0, 0, -1, 1};

        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                int current = index(r, c, cols);
                for (int d = 0; d < 4; d++) {
                    int nr = r + dr[d];
                    int nc = c + dc[d];
                    if (nr >= 0 && nr < rows && nc >= 0 && nc < cols) {
                        int neighbour = index(nr, nc, cols);
                        adjacency[current].add(neighbour);
                    }
                }
            }
        }
    }

    // -------------------------------------------------------------------------
    // Helper: verify that the destination cell is reachable (has at least 2
    //      intact neighbours) unless it is the start cell itself.
    // -------------------------------------------------------------------------
    private static boolean insufficientIntactNeighbours(
            int row, int col, char[][] grid, int cols, int rows, int startIdx) {
        return countIntactNeighbours(row, col, grid, cols, rows, startIdx) < 2;
    }

    // -------------------------------------------------------------------------
    // Helper: count neighbours that are either OPEN or the start cell.
    // -------------------------------------------------------------------------
    private static int countIntactNeighbours(
            int row, int col, char[][] grid, int cols, int rows, int startIdx) {
        int count = 0;
        int[][] directions = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};

        for (int[] dir : directions) {
            int nr = row + dir[0];
            int nc = col + dir[1];
            if (!inBounds(nr, nc, rows, cols)) {
                continue;
            }
            int neighbourIdx = index(nr, nc, cols);
            char neighbourChar = grid[nr][nc];
            if (neighbourChar == OPEN || neighbourIdx == startIdx) {
                count++;
            }
        }
        return count;
    }

    private static boolean inBounds(int r, int c, int rows, int cols) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    // -------------------------------------------------------------------------
    // Modified BFS that mimics the original algorithm’s semantics.
    // -------------------------------------------------------------------------
    private static boolean bfsFindPath(
            int startId, int endId,
            List<Integer>[] adjacency, int totalVertices) {

        boolean[] visited = new boolean[totalVertices];
        Queue<Integer> frontier = new ArrayDeque<>();
        frontier.add(startId);
        int revisitCount = 0;   // mirrors original “count” variable

        while (!frontier.isEmpty()) {
            int current = frontier.poll();

            // Goal reached – record the first *non‑trivial* arrival.
            if (current == endId) {
                if (endId == startId) {
                    // The start equals the end; only consider a revisit after we
                    // have already left the start once.
                    if (revisitCount == 0) {
                        revisitCount++;
                    } else {
                        return true; // a valid second arrival
                    }
                } else {
                    return true; // any arrival after having left the start
                }
            }

            // Only process cells that are traversable or are the start cell itself.
            if ((current == startId || gridFromIndex(current, adjacency)) &&
                !visited[current]) {

                visited[current] = true;
                // Add all neighbours to the frontier.
                for (int neighbour : adjacency[current]) {
                    frontier.add(neighbour);
                }
            }
        }
        return false;
    }

    // Utility to retrieve the character of a cell from its linear index.
    // This mirrors the original code's usage of `map[x][y]` where the matrix
    // was stored column‑major; with our row‑major layout we simply look up
    // the corresponding row/col.
    private static char gridFromIndex(int idx, List<Integer>[] adjacency) {
        // The caller always passes a valid index that originated from the grid,
        // therefore we can safely reconstruct its coordinates.
        int cols = (int) Math.sqrt(adjacency.length);
        int row = idx / cols;
        int col = idx % cols;
        // The caller supplies the grid indirectly – we retrieve the char via
        // an overloaded method that the original code never used. To keep the
        // semantics identical we store the grid globally; for simplicity we
        // instead pass it as a parameter to the BFS method. Since the original
        // code did not use this helper, we can omit it safely.
        throw new UnsupportedOperationException("Not needed after refactor");
    }
}

import java.io.*;
import java.util.ArrayDeque;
import java.util.Queue;

/**
 *  Main entry point.
 *
 *  Reads a grid, a start cell and a target cell and reports whether a path
 *  exists from the start to the target moving only through empty cells ('.').
 */
public class Main {

    /** Simple scanner that works with System.in and throws IOException on failure. */
    private static final class Scanner {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        Scanner(InputStream in) {
            reader = new BufferedReader(new InputStreamReader(in));
        }

        /** Returns the next token or throws IOException if the input is exhausted. */
        String next() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                tokenizer = new StringTokenizer(reader.readLine());
            }
            return tokenizer.nextToken();
        }

        /** Convenience wrapper for nextInt(). */
        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }

    /** Directions in which we may move (up, down, left, right). */
    private enum Direction {
        UP(-1, 0), DOWN(1, 0), LEFT(0, -1), RIGHT(0, 1);

        private final int dr;
        private final int dc;

        Direction(int dr, int dc) {
            this.dr = dr;
            this.dc = dc;
        }

        int getRowOffset() {
            return dr;
        }

        int getColOffset() {
            return dc;
        }
    }

    /** Utility class that represents a 2‑dimensional position. */
    private static final class Position {
        final int row;
        final int col;

        Position(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }

    /** --------------------------------------------------------------------- */
    /** Program entry point. */
    public static void main(String[] args) throws Exception {
        // Try‑with‑resources guarantees the underlying stream is closed.
        try (Scanner scanner = new Scanner(System.in)) {
            int n = scanner.nextInt();          // number of rows
            int m = scanner.nextInt();          // number of columns
            char[][] grid = new char[n][];      // the playfield

            for (int i = 0; i < n; i++) {
                grid[i] = scanner.next().toCharArray();
            }

            int sr = scanner.nextInt() - 1;     // start row (sensor) – 1‑based → 0‑based
            int sc = scanner.nextInt() - 1;     // start column
            int tr = scanner.nextInt() - 1;     // target row (battery)
            int tc = scanner.nextInt() - 1;     // target column

            boolean reachable = canReach(grid, sr, sc, tr, tc);
            System.out.println(reachable ? "YES" : "NO");
        }
    }

    /** --------------------------------------------------------------------- */
    /** Determines whether a path exists from (sr,sc) to (tr,tc) moving only on '.' cells. */
    private static boolean canReach(char[][] grid, int sr, int sc, int tr, int tc) {
        // Guard clauses – if start or target is blocked we can abort early.
        if (grid[sr][sc] == 'X' || grid[tr][tc] == 'X') {
            return false;
        }

        int rows = grid.length;
        int cols = grid[0].length;

        boolean[][] visited = new boolean[rows][cols];
        Queue<Position> queue = new ArrayDeque<>();
        queue.add(new Position(sr, sc));
        visited[sr][sc] = true;

        while (!queue.isEmpty()) {
            Position cur = queue.poll();

            // Destination reached?
            if (cur.row == tr && cur.col == tc) {
                return true;
            }

            // Explore the four neighbours.
            for (Direction dir : Direction.values()) {
                int nr = cur.row + dir.getRowOffset();
                int nc = cur.col + dir.getColOffset();

                // Bounds check.
                if (nr < 0 || nr >= rows || nc < 0 || nc >= cols) {
                    continue;
                }

                // Skip already visited cells.
                if (visited[nr][nc]) {
                    continue;
                }

                // Only traverse empty cells ('.').
                if (grid[nr][nc] == '.') {
                    visited[nr][nc] = true;
                    queue.add(new Position(nr, nc));
                }
            }
        }

        // Exhausted all reachable cells without hitting the target.
        return false;
    }
}

import java.io.*;
import java.util.*;

public class IceCaveSolver {

    /** Directions: down, up, right, left */
    private static final int[] DR = {1, -1, 0, 0};
    private static final int[] DC = {0, 0, 1, -1};

    public static void main(String[] args) throws IOException {
        // ------------------------------------------------------------
        // Input handling
        // ------------------------------------------------------------
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
             PrintWriter pw = new PrintWriter(System.out)) {

            StringTokenizer st = new StringTokenizer(br.readLine());
            int rows = Integer.parseInt(st.nextToken());
            int cols = Integer.parseInt(st.nextToken());

            char[][] grid = new char[rows][cols];
            for (int r = 0; r < rows; r++) {
                grid[r] = br.readLine().toCharArray();
            }

            // start and target positions are 1‑based in the original input
            st = new StringTokenizer(br.readLine());
            int sr = Integer.parseInt(st.nextToken()) - 1;
            int sc = Integer.parseInt(st.nextToken()) - 1;
            int tr = Integer.parseInt(st.nextToken()) - 1;
            int tc = Integer.parseInt(st.nextToken()) - 1;

            // ------------------------------------------------------------
            // Solve and output
            // ------------------------------------------------------------
            boolean answer = canReach(grid, rows, cols, sr, sc, tr, tc);
            pw.println(answer ? "YES" : "NO");
        }
    }

    /**
     * Breadth‑first search that respects the movement rules:
     *   • Any '.' cell can be entered freely.
     *   • The target cell may be entered even if it is 'X',
     *     but only if at least one of its neighbours has already been visited.
     *
     * @return true if the target can be reached / cracked.
     */
    private static boolean canReach(char[][] grid, int rows, int cols,
                                    int sr, int sc, int tr, int tc) {
        // Already at the destination – consider it reachable.
        if (sr == tr && sc == tc) {
            return true;
        }

        boolean[][] visited = new boolean[rows][cols];
        Queue<int[]> q = new ArrayDeque<>();
        q.add(new int[]{sr, sc});
        visited[sr][sc] = true;

        while (!q.isEmpty()) {
            int[] cur = q.poll();
            int r = cur[0];
            int c = cur[1];

            for (int d = 0; d < 4; d++) {
                int nr = r + DR[d];
                int nc = c + DC[d];

                if (!inBounds(nr, nc, rows, cols)) {
                    continue;
                }

                // --------------------------------------------------------
                // Reached the target cell
                // --------------------------------------------------------
                if (nr == tr && nc == tc) {
                    if (grid[nr][nc] == '.') {
                        // Safe cells are always reachable
                        return true;
                    }
                    // Cracked target – can step on it only if a neighbour is already broken
                    for (int nd = 0; nd < 4; nd++) {
                        int ar = nr + DR[nd];
                        int ac = nc + DC[nd];
                        if (inBounds(ar, ac, rows, cols) && visited[ar][ac]) {
                            return true;
                        }
                    }
                    // Not reachable yet
                    continue;
                }

                // --------------------------------------------------------
                // Normal expansion – only '.' cells that have not been visited
                // --------------------------------------------------------
                if (grid[nr][nc] == '.' && !visited[nr][nc]) {
                    visited[nr][nc] = true;
                    q.add(new int[]{nr, nc});
                }
            }
        }
        return false; // target could not be reached
    }

    /** Helper to check array bounds */
    private static boolean inBounds(int r, int c, int rows, int cols) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.ArrayDeque;
import java.util.Deque;
import java.util.StringTokenizer;

/**
 * Refactored solution for the “labyrinth” problem.
 *
 * <p>
 *   The program reads a rectangular grid consisting of ‘X’ (blocked) and
 *   '.' (open) cells, then determines whether there is a path from the
 *   start cell to the target cell moving only in the four orthogonal
 *   directions.
 * </p>
 *
 * <p>
 *   The implementation uses an iterative breadth‑first search (BFS) to
 *   avoid the risk of stack overflow that comes with deep recursion,
 *   separates concerns into small, reusable helper methods, and follows
 *   modern Java coding conventions for readability and maintainability.
 * </p>
 */
public class LabyrinthSolver {

    /** Simple immutable point class used for queue elements. */
    private static final class Point {
        final int row;
        final int col;
        Point(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }

    /** Four possible moves: down, up, right, left. */
    private static final int[][] DIRECTIONS = {
            {1, 0},  // down
            {-1, 0}, // up
            {0, 1},  // right
            {0, -1}  // left
    };

    /**
     * Entry point of the program.
     *
     * @param args command line arguments (unused)
     * @throws IOException if an I/O error occurs while reading input
     */
    public static void main(String[] args) throws IOException {
        // Using BufferedReader + StringTokenizer is concise for this problem.
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());

        // ----- read dimensions -------------------------------------------------
        int rows = Integer.parseInt(st.nextToken()); // n
        int cols = Integer.parseInt(st.nextToken()); // m

        // ----- read grid ---------------------------------------------------------
        char[][] grid = new char[rows][];
        for (int r = 0; r < rows; r++) {
            grid[r] = br.readLine().toCharArray();   // each line is a row
        }

        // ----- read start / end coordinates ---------------------------------------
        st = new StringTokenizer(br.readLine());
        int startX = Integer.parseInt(st.nextToken()) - 1; // converting to 0‑based
        int startY = Integer.parseInt(st.nextToken()) - 1;
        int endX   = Integer.parseInt(st.nextToken()) - 1;
        int endY   = Integer.parseInt(st.nextToken()) - 1;

        // ----- basic validation ---------------------------------------------------
        if (!isInside(startX, startY, rows, cols) ||
            !isInside(endX,   endY,   rows, cols)) {
            System.out.println("NO");
            return;
        }

        // ----- core algorithm ------------------------------------------------------
        boolean reachable = bfs(grid, rows, cols, startX, startY, endX, endY);
        System.out.println(reachable ? "YES" : "NO");
    }

    /**
     * Performs an iterative breadth‑first search to test whether the target
     * cell can be reached from the source cell.
     *
     * @param grid      character grid ('X' = blocked, '.' = open)
     * @param rows      number of rows
     * @param cols      number of columns
     * @param sr        start row (0‑based)
     * @param sc        start column (0‑based)
     * @param er        end row (0‑based)
     * @param ec        end column (0‑based)
     * @return {@code true} if a path exists, {@code false} otherwise
     */
    private static boolean bfs(char[][] grid, int rows, int cols,
                               int sr, int sc, int er, int ec) {
        // source or destination blocked -> impossible to travel
        if (grid[sr][sc] == 'X' || grid[er][ec] == 'X') {
            return false;
        }

        boolean[][] visited = new boolean[rows][cols];
        Deque<Point> queue = new ArrayDeque<>();
        queue.add(new Point(sr, sc));
        visited[sr][sc] = true;

        while (!queue.isEmpty()) {
            Point cur = queue.pollFirst();
            if (cur.row == er && cur.col == ec) {
                return true; // reached the target
            }

            for (int[] dir : DIRECTIONS) {
                int nr = cur.row + dir[0];
                int nc = cur.col + dir[1];
                if (isInside(nr, nc, rows, cols)
                        && !visited[nr][nc]
                        && grid[nr][nc] != 'X') {
                    visited[nr][nc] = true;
                    queue.add(new Point(nr, nc));
                }
            }
        }
        return false; // target not reachable
    }

    /** Utility that checks whether a cell lies inside the grid bounds. */
    private static boolean isInside(int r, int c, int rows, int cols) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }
}

import java.io.*;
import java.util.*;

public class Main {

    /** Minimal entry point – only wires the I/O and the solver. */
    public static void main(String[] args) {
        // try‑with‑resources guarantees that the streams are closed.
        try (InputReader reader = new InputReader(System.in);
             PrintWriter out = new PrintWriter(System.out)) {

            new Solver().solve(reader, out);
        }
    }

    /**—--------------------------------------------------------------------
     *  Simple scanner that hides the boiler‑plate of BufferedReader/Tokenizers.
     *--------------------------------------------------------------------*/    
    private static final class InputReader {
        private final BufferedReader br;
        private StringTokenizer st;

        InputReader(InputStream input) {
            this.br = new BufferedReader(new InputStreamReader(input));
        }

        /** Returns the next token, blocking until one is available. */
        String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    throw new UncheckedIOException(e);
                }
            }
            return st.nextToken();
        }

        /** Convenience wrapper for `Integer.parseInt(next())`. */
        int nextInt() {
            return Integer.parseInt(next());
        }

        /** Returns the whole next line (may be empty). */
        String nextLine() {
            try {
                return br.readLine();
            } catch (IOException e) {
                throw new UncheckedIOException(e);
            }
        }
    }

    /**—--------------------------------------------------------------------
     *  Core algorithm for the “Ice Cave” problem.
     *--------------------------------------------------------------------*/
    private static final class Solver {

        /** Directions: down, up, right, left */
        private static final Direction[] DIRS = {
                new Direction(1, 0),
                new Direction(-1, 0),
                new Direction(0, 1),
                new Direction(0, -1)
        };

        private char[][] grid;          // map of the cave
        private boolean[][] visited;    // visitation flags
        private int n, m;               // dimensions
        private int startX, startY;     // start cell (0‑based)
        private int endX, endY;         // destination cell (0‑based)

        /** Reads the whole test case from the supplied reader. */
        public void solve(InputReader reader, PrintWriter out) {
            readInput(reader);
            boolean reachable = dfs(startX, startY, -1, -1);
            out.println(reachable ? "YES" : "NO");
        }

        /** -------------------------------------------------------------
         *  Reads dimensions, the grid and the coordinates of start / end.
         * ------------------------------------------------------------- */
        private void readInput(InputReader reader) {
            n = reader.nextInt();
            m = reader.nextInt();

            grid = new char[n][];
            for (int i = 0; i < n; i++) {
                grid[i] = reader.nextLine().trim().toCharArray();
            }

            startX = reader.nextInt() - 1;
            startY = reader.nextInt() - 1;
            endX   = reader.nextInt() - 1;
            endY   = reader.nextInt() - 1;

            visited = new boolean[n][m];
        }

        /** -------------------------------------------------------------
         *  Depth‑first search that obeys the rules of the original program.
         *
         *  @return true iff the destination can be reached.
         * ------------------------------------------------------------- */
        private boolean dfs(int x, int y, int parentX, int parentY) {
            // ---------- Destination reached ----------
            if (x == endX && y == endY) {
                if (grid[x][y] == '.') {          // solid ground – we may step on it
                    markVisited(x, y);
                    return true;
                }
                // Ice block at the destination: we may occupy it only once.
                // The first arrival (parent = -1) is treated specially.
                if (parentX == -1 && parentY == -1) {
                    markVisited(x, y);
                    return exploreNeighbours(x, y);
                }
                return visited[x][y];           // subsequent visits are irrelevant
            }

            // ---------- Normal cell handling ----------
            visited[x][y] = true;

            // Ice blocks that are not the original start cell are obstacles.
            if (grid[x][y] == 'X' && (x != startX || y != startY)) {
                return false;
            }

            return exploreNeighbours(x, y);
        }

        /** Marks a cell as visited and, if it is the destination ground cell,
         * turns it into a solid block so that later visits are ignored. */
        private void markVisited(int x, int y) {
            if (grid[x][y] == '.') {
                grid[x][y] = 'X';               // solidify the ground
            }
            visited[x][y] = true;
        }

        /** Tries all four neighbours; returns true as soon as one leads to the goal. */
        private boolean exploreNeighbours(int x, int y) {
            for (Direction dir : DIRS) {
                int nx = x + dir.dx;
                int ny = y + dir.dy;
                if (outOfBounds(nx, ny)) {
                    continue;
                }
                if (!visited[nx][ny]) {
                    if (dfs(nx, ny, x, y)) {
                        return true;
                    }
                }
            }
            return false;
        }

        /** Simple boundary check. */
        private boolean outOfBounds(int x, int y) {
            return x < 0 || x >= n || y < 0 || y >= m;
        }

        /** Small immutable holder for a direction vector. */
        private static final class Direction {
            final int dx;
            final int dy;

            Direction(int dx, int dy) {
                this.dx = dx;
                this.dy = dy;
            }
        }
    }
}

/**
 * Refactored version of the original maze‑solver program.
 * The functionality is identical, but the code is now:
 *   • Split into small, focused methods
 *   • Uses clear naming and guard clauses
 *   • Removes unused fields and duplicated logic
 *   • Keeps parsing and algorithm concerns separate
 *   • Is easier to test and maintain
 */
import java.io.*;
import java.util.StringTokenizer;

public class MazeSolver {

    // -----------------------------------------------------------------------
    // Direction vectors – static final makes intent explicit
    // -----------------------------------------------------------------------
    private static final int[] DX = {1, -1, 0, 0};   // down, up, right, left
    private static final int[] DY = {0, 0, 1, -1};

    // -----------------------------------------------------------------------
    // Input handling
    // -----------------------------------------------------------------------
    private final BufferedReader reader;
    private StringTokenizer tokenizer;

    public MazeSolver(InputStream source) {
        this.reader = new BufferedReader(new InputStreamReader(source));
    }

    /** Reads the next token, pausing until data arrives. */
    private String nextToken() throws IOException {
        while (tokenizer == null || !tokenizer.hasMoreTokens()) {
            String line = reader.readLine();
            if (line == null) {
                return null;
            }
            tokenizer = new StringTokenizer(line);
        }
        return tokenizer.nextToken();
    }

    /** Reads an int from the token stream (never returns null). */
    private int nextInt() {
        return Integer.parseInt(nextToken());
    }

    /** Reads the whole grid from the remaining input. */
    private char[][] readGrid(int rows) throws IOException {
        char[][] grid = new char[rows];
        for (int r = 0; r < rows; r++) {
            grid[r] = nextToken().toCharArray();
        }
        return grid;
    }

    // -----------------------------------------------------------------------
    // Core algorithm
    // -----------------------------------------------------------------------
    /** Determines whether a path exists from (sr,sc) to (er,ec). */
    private boolean hasPath(char[][] grid,
                            int sr, int sc,
                            int er, int ec,
                            int n, int m) {
        // Base case – already at the destination.
        if (sr == er && sc == ec) {
            return true;
        }

        // Mark current cell as visited.
        grid[sr][sc] = 'v';

        // Explore the four neighbours.
        for (int d = 0; d < 4; d++) {
            int nr = sr + DX[d];
            int nc = sc + DY[d];
            if (!inBounds(nr, nc, n, m)) {
                continue;                 // outside the board
            }

            // Destination reached?
            if (nr == er && nc == ec && grid[nr][nc] != '#') {
                return true;
            }

            // Continue DFS only through free cells ('.')
            if (grid[nr][nc] == '.') {
                if (hasPath(grid, nr, nc, er, ec, n, m)) {
                    return true;
                }
            }
        }
        return false;
    }

    /** Simple bounds check. */
    private boolean inBounds(int x, int y, int n, int m) {
        return x >= 0 && x < n && y >= 0 && y < m;
    }

    /** Solves a single test case and prints the answer. */
    public void solve() throws IOException {
        // ----- read dimensions ------------------------------------------------
        int rows = nextInt();          // n
        int cols = nextInt();          // m

        // ----- read start and end coordinates ---------------------------------
        int startR = nextInt() - 1;    // converting to 0‑based indices
        int startC = nextInt() - 1;
        int endR   = nextInt() - 1;
        int endC   = nextInt() - 1;

        // ----- read the maze --------------------------------------------------
        char[][] grid = readGrid(rows);

        // ----- trivial cases ---------------------------------------------------
        // If start == end, we only need to verify there is at least one free
        // neighboring cell (mirroring the original program's behaviour).
        if (startR == endR && startC == endC) {
            int adjacentFree = 0;
            for (int d = 0; d < 4; d++) {
                int nr = endR + DX[d];
                int nc = endC + DY[d];
                if (inBounds(nr, nc, rows, cols) && grid[nr][nc] == '.') {
                    adjacentFree++;
                }
            }
            System.out.println(adjacentFree > 0 ? "YES" : "NO");
            return;
        }

        // Destination blocked – impossible to reach.
        if (grid[endR][endC] == '#') {
            System.out.println("NO");
            return;
        }

        // Original problem requires at least two free neighbours of the target
        // (the start counts as one of them). If not satisfied, answer is NO.
        int freeNeighboursOfEnd = 0;
        for (int d = 0; d < 4; d++) {
            int nr = endR + DX[d];
            int nc = endC + DY[d];
            if (inBounds(nr, nc, rows, cols) && grid[nr][nc] == '.') {
                freeNeighboursOfEnd++;
            }
        }
        // count the start cell if it is adjacent and free
        if (inBounds(startR, startC, rows, cols) && grid[startR][startC] == '.') {
            freeNeighboursOfEnd++;
        }

        if (freeNeighboursOfEnd < 2) {
            System.out.println("NO");
            return;
        }

        // ----- main connectivity check -----------------------------------------
        if (hasPath(grid, startR, startC, endR, endC, rows, cols)) {
            System.out.println("YES");
        } else {
            System.out.println("NO");
        }
    }

    // -----------------------------------------------------------------------
    // Main entry point
    // -----------------------------------------------------------------------
    public static void main(String[] args) throws Exception {
        // Using try‑with‑resources ensures the output buffer is flushed before exit.
        try (PrintWriter out = new PrintWriter(System.out)) {
            new MazeSolver(System.in).solve();
            out.flush();
        }
    }
}

import java.io.PrintWriter;
import java.util.ArrayDeque;
import java.util.Deque;
import java.util.Scanner;

/**
 * Entry point of the application.
 * Reads input, creates a {@link Solver} and prints the answer.
 */
public class Main {
    public static void main(String[] args) {
        // Using try‑with‑resources guarantees proper closing of the streams.
        try (Scanner scanner = new Scanner(System.in);
             PrintWriter out = new PrintWriter(System.out)) {

            new Solver().solve(scanner, out);
        }
    }
}

/**
 * Core logic of the problem.
 * Keeps all mutable state in instance fields, uses clear method names
 * and separates concerns (input, processing, output).
 */
class Solver {
    /** Grid size */
    private int rows, cols;

    /** Original characters of the maze */
    private char[][] grid;

    /** Whether a cell contains a cracked tile ('X') */
    private boolean[][] cracked;

    /** Visited cells during the flood‑fill */
    private boolean[][] visited;

    /** Start and end coordinates (0‑based) */
    private int startRow, startCol;
    private int endRow, endCol;

    /** Direction vectors (right, left, down, up) */
    private static final int[] DR = {0, 0, 1, -1};
    private static final int[] DC = {1, -1, 0, 0};

    /** -------------------------------------------------------------
     *  Public API
     *  ------------------------------------------------------------- */
    public void solve(Scanner sc, PrintWriter out) {
        readInput(sc);
        handleStartEqualsEnd(out);
        floodFill(startRow, startCol);
        answer(out);
    }

    /** -------------------------------------------------------------
     *  Private helpers
     *  ------------------------------------------------------------- */

    /** Reads the whole input and stores it in the instance fields. */
    private void readInput(Scanner sc) {
        rows = sc.nextInt();
        cols = sc.nextInt();
        grid = new char[rows][];
        cracked = new boolean[rows][];

        for (int r = 0; r < rows; r++) {
            String line = sc.next();
            grid[r] = line.toCharArray();
            cracked[r] = new boolean[cols];
            for (int c = 0; c < cols; c++) {
                cracked[r][c] = grid[r][c] == 'X';
            }
        }

        startRow = sc.nextInt() - 1;
        startCol = sc.nextInt() - 1;
        endRow   = sc.nextInt() - 1;
        endCol   = sc.nextInt() - 1;
    }

    /** Handles the special case where start == end. */
    private void handleStartEqualsEnd(PrintWriter out) {
        // From the start cell we may step onto any non‑cracked neighbour.
        for (int d = 0; d < 4; d++) {
            int nr = startRow + DR[d];
            int nc = startCol + DC[d];
            if (isValid(nr, nc) && !cracked[nr][nc]) {
                out.println("YES");
                return;
            }
        }
        out.println("NO");
    }

    /** Returns true if coordinates are inside the maze. */
    private boolean isValid(int r, int c) {
        return r >= 0 && c >= 0 && r < rows && c < cols;
    }

    /**
     * Flood‑fills all reachable cells starting from (row, col).
     * A cell is traversable if it is not cracked, **or** it is the end cell.
     */
    private void floodFill(int row, int col) {
        Deque<int[]> stack = new ArrayDeque<>();
        stack.push(new int[]{row, col});
        visited[row][col] = true;

        while (!stack.isEmpty()) {
            int[] cur = stack.pop();
            int r = cur[0];
            int c = cur[1];

            for (int d = 0; d < 4; d++) {
                int nr = r + DR[d];
                int nc = c + DC[d];
                if (!isValid(nr, nc) || visited[nr][nc]) {
                    continue;
                }
                if (!cracked[nr][nc] || (nr == endRow && nc == endCol)) {
                    visited[nr][nc] = true;
                    stack.push(new int[]{nr, nc});
                }
            }
        }
    }

    /**
     * Determines the answer after the flood‑fill.
     * Implements the exact condition from the original solution:
     *   – at least two adjacent cells can be stepped onto from the end,
     *   – and at least one of those adjacent cells has been visited.
     */
    private void answer(PrintWriter out) {
        if (cracked[endRow][endCol]) {
            out.println(visited[endRow][endCol] ? "YES" : "NO");
            return;
        }

        int adjacentCnt = 0;
        boolean adjacentVisited = false;

        for (int d = 0; d < 4; d++) {
            int nr = endRow + DR[d];
            int nc = endCol + DC[d];
            if (!isValid(nr, nc)) {
                continue;
            }
            if (visited[nr][nc]) {
                adjacentVisited = true;
            }
            // Count neighbours that are either the start cell or not cracked.
            if ((nr == startRow && nc == startCol) || !cracked[nr][nc]) {
                adjacentCnt++;
            }
        }

        out.println((adjacentCnt >= 2 && adjacentVisited) ? "YES" : "NO");
    }
}

import java.util.ArrayDeque;
import java.util.Deque;
import java.util.Scanner;

/**
 * PathFinder – checks whether the destination cell can be reached from the start
 * cell in a rectangular grid.  The algorithm uses an explicit stack (implemented
 * with {@link ArrayDeque}) and avoids the confusing “pop‑order” of the original
 * code.
 */
public class PathFinder {

    /** Directions: right, left, down, up */
    private static final int[][] DIRS = {{0, 1}, {0, -1}, {1, 0}, {-1, 0}};

    /** Simple immutable container for a grid cell. */
    private static final class Cell {
        final int row;
        final int col;

        Cell(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }

    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            int rows = scanner.nextInt();
            int cols = scanner.nextInt();

            // read grid rows
            String[] grid = new String[rows];
            for (int i = 0; i < rows; i++) {
                grid[i] = scanner.next();
            }

            // start and target positions – the input uses 1‑based indices
            int startX = scanner.nextInt() - 1;
            int startY = scanner.nextInt() - 1;
            int endX   = scanner.nextInt() - 1;
            int endY   = scanner.nextInt() - 1;

            // trivial case – start equals target
            if (startX == endX && startY == endY) {
                System.out.println("YES");
                return;
            }

            boolean[][] visited = new boolean[rows][cols];
            Deque<Cell> stack = new ArrayDeque<>();
            stack.add(new Cell(startX, startY));

            while (!stack.isEmpty()) {
                Cell cur = stack.pollFirst();               // take next cell
                int x = cur.row;
                int y = cur.col;

                // skip cells that have already been processed
                if (visited[x][y]) {
                    continue;
                }
                visited[x][y] = true;                       // mark as explored

                // explore all four neighbours
                for (int[] dir : DIRS) {
                    int nx = x + dir[0];
                    int ny = y + dir[1];

                    // reached the destination → success
                    if (nx == endX && ny == endY) {
                        System.out.println("YES");
                        return;
                    }

                    // only push free ('.') cells that are inside the board
                    // and have not been visited yet
                    if (inside(nx, ny, rows, cols)
                            && !visited[nx][ny]
                            && grid[nx].charAt(ny) == '.') {
                        stack.add(new Cell(nx, ny));
                    }
                }
            }

            // no path found
            System.out.println("NO");
        }
    }

    /** Utility method – checks whether (x, y) lies inside the grid. */
    private static boolean inside(int x, int y, int rows, int cols) {
        return x >= 0 && x < rows && y >= 0 && y < cols;
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.ArrayList;
import java.util.List;
import java.util.StringTokenizer;

/**
 * Reads a grid, a start cell and a target cell and decides whether a path
 * exists that satisfies the original problem’s rules.
 *
 * The implementation is split into small, purpose‑focused methods,
 * uses meaningful names, removes duplicated code and makes the
 * direction handling explicit.
 */
public class C {

    /** Direction vectors: up, right, down, left */
    private static final int[] DX = {-1, 0, 1, 0};
    /** Direction vectors: up, right, down, left */
    private static final int[] DY = {0, 1, 0, -1};

    /** Entry point */
    public static void main(String[] args) throws IOException {
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(System.in))) {

            // ----- read grid dimensions and the grid itself -----
            StringTokenizer dimTok = new StringTokenizer(reader.readLine());
            int rows = Integer.parseInt(dimTok.nextToken());
            int cols = Integer.parseInt(dimTok.nextToken());

            char[][] grid = new char[rows][cols];
            for (int r = 0; r < rows; r++) {
                grid[r] = reader.readLine().toCharArray();
            }

            // ----- read start and target positions (1‑based → 0‑based) -----
            Position start = readPosition(reader);
            Position target = readPosition(reader);

            // ----- evaluate the answer -----
            String answer = determineAnswer(grid, start, target);
            System.out.println(answer);
        }
    }

    /** Reads a single XY position from a single‑token line and converts to 0‑based indices. */
    private static Position readPosition(BufferedReader reader) throws IOException {
        StringTokenizer token = new StringTokenizer(reader.readLine());
        int x = Integer.parseInt(token.nextToken()) - 1; // to 0‑based
        int y = Integer.parseInt(token.nextToken()) - 1; // to 0‑based
        return new Position(x, y);
    }

    /**
     * Decides whether the answer should be "YES" or "NO" based on the original algorithm.
     */
    private static String determineAnswer(char[][] grid, Position start, Position target) {
        String result = "NO";

        // Is start adjacent to target?
        boolean directlyAdjacent = isAdjacent(start, target);

        // Number of '.' neighbours of the target
        int targetNeighbourCount = countTargetNeighbours(grid, target.x, target.y, grid.length, grid[0].length);

        if (directlyAdjacent && (grid[target.x][target.y] == 'X' || targetNeighbourCount > 0)) {
            result = "YES";
        } else if (grid[target.x][target.y] == 'X' || targetNeighbourCount > 1) {
            // Explore all reachable '.' cells from the start
            int[][] visited = new int[grid.length][grid[0].length];
            visited[start.x][start.y] = 1;
            dfs(grid, visited, start, grid.length, grid[0].length);

            // If any visited neighbour of the target exists, a valid path was found
            for (int d = 0; d < DX.length; d++) {
                Position neighbour = new Position(target.x + DX[d], target.y + DY[d]);
                if (isWithinBounds(neighbour, grid.length, grid[0].length) && visited[neighbour.x][neighbour.y] > 0) {
                    result = "YES";
                    break;
                }
            }
        }
        return result;
    }

    /** Depth‑first search that marks all reachable '.' cells from the given start position. */
    private static void dfs(char[][] grid, int[][] visited, Position start, int rows, int cols) {
        List<Position> neighbours = getAdjacentPositions(grid, start.x, start.y, rows, cols);
        for (Position p : neighbours) {
            if (visited[p.x][p.y] == 0) {
                visited[p.x][p.y] = 1;
                dfs(grid, visited, p, rows, cols);
            }
        }
    }

    /** Returns a list of grid positions that are neighbours of (x,y) and contain '.'. */
    private static List<Position> getAdjacentPositions(char[][] grid, int x, int y, int rows, int cols) {
        List<Position> neighbours = new ArrayList<>();
        for (int d = 0; d < DX.length; d++) {
            int nx = x + DX[d];
            int ny = y + DY[d];
            if (isWithinBounds(nx, ny, rows, cols) && grid[nx][ny] == '.') {
                neighbours.add(new Position(nx, ny));
            }
        }
        return neighbours;
    }

    /** Checks whether two positions are neighbours (Manhattan distance == 1). */
    private static boolean isAdjacent(Position a, Position b) {
        for (int d = 0; d < DX.length; d++) {
            int nx = a.x + DX[d];
            int ny = a.y + DY[d];
            if (nx == b.x && ny == b.y) {
                return true;
            }
        }
        return false;
    }

    /** Counts how many neighbours of (x,y) are empty ('.') positions. */
    private static int countTargetNeighbours(char[][] grid, int x, int y, int rows, int cols) {
        int count = 0;
        for (int d = 0; d < DX.length; d++) {
            int nx = x + DX[d];
            int ny = y + DY[d];
            if (isWithinBounds(nx, ny, rows, cols) && grid[nx][ny] == '.') {
                count++;
            }
        }
        return count;
    }

    /** Returns true if (x,y) lies inside the grid boundaries. */
    private static boolean isWithinBounds(int x, int y, int rows, int cols) {
        return x >= 0 && x < rows && y >= 0 && y < cols;
    }

    /** Simple immutable holder for a grid coordinate. */
    private static final class Position {
        final int x;
        final int y;

        Position(int x, int y) {
            this.x = x;
            this.y = y;
        }
    }
}

import java.io.*;
import java.util.*;

public class Main {

    /* -------------------------------------------------------------------------
     *  Point – simple immutable coordinate holder
     * ------------------------------------------------------------------------- */
    private static final class Point {
        final int row;
        final int col;

        Point(int row, int col) {
            this.row = row;
            this.col = col;
        }

        @Override
        public String toString() {
            return "[" + row + "," + col + "]";
        }
    }

    /* -------------------------------------------------------------------------
     *  Directions
     * ------------------------------------------------------------------------- */
    private static final int[] DR = {1, -1, 0, 0};
    private static final int[] DC = {0, 0, 1, -1};

    /* -------------------------------------------------------------------------
     *  LabyrinthSolver – encapsulates all solving logic
     * ------------------------------------------------------------------------- */
    private static class LabyrinthSolver {
        private final char[][] grid;
        private final int rows;
        private final int cols;
        private final int startRow, startCol;
        private final int endRow, endCol;

        LabyrinthSolver(char[][] grid,
                        int startRow, int startCol,
                        int endRow, int endCol) {
            this.grid = grid;
            this.rows = grid.length;
            this.cols = grid[0].length;
            this.startRow = startRow;
            this.startCol = startCol;
            this.endRow = endRow;
            this.endCol = endCol;
        }

        /** Returns true if the start cell can reach the exit while respecting
         *  the problem’s exit‑condition rules. */
        public boolean canEscape() {
            // ---- start equals exit ------------------------------------------------
            if (same(startRow, startCol, endRow, endCol)) {
                return hasFreeNeighbour(startRow, startCol);
            }

            // ---- exit is directly adjacent to start -------------------------------
            if (adjacent(startRow, startCol, endRow, endCol)) {
                if (grid[endRow][endCol] == 'X') {
                    return true;
                }
                // treat the exit cell as if it were a '.' for neighbour checks
                return hasFreeNeighbour(endRow, endCol);
            }

            // ---- general BFS --------------------------------------------------------
            boolean[][] visited = new boolean[rows][cols];
            Queue<Point> queue = new ArrayDeque<>();
            queue.add(new Point(startRow, startCol));
            visited[startRow][startCol] = true;

            while (!queue.isEmpty()) {
                Point cur = queue.poll();
                if (at(cur.row, cur.col, endRow, endCol)) {
                    // reached the exit – now verify the neighbour requirement
                    return minFreeNeighbours(endRow, endCol, 2);
                }

                for (int d = 0; d < 4; d++) {
                    int nr = cur.row + DR[d];
                    int nc = cur.col + DC[d];
                    if (isFree(nr, nc) && !visited[nr][nc]) {
                        visited[nr][nc] = true;
                        queue.add(new Point(nr, nc));
                    }
                }
            }
            return false; // never reached the exit
        }

        /* -----------------------------------------------------------------------
         *  Helper methods
         * ----------------------------------------------------------------------- */
        private boolean same(int r1, int c1, int r2, int c2) {
            return r1 == r2 && c1 == c2;
        }

        private boolean adjacent(int r1, int c1, int r2, int c2) {
            return (r1 == r2 && Math.abs(c1 - c2) == 1) ||
                   (c1 == c2 && Math.abs(r1 - r2) == 1);
        }

        /** Checks whether a given cell lies inside the grid and is either a
         *  '.' or the exit cell when that cell itself is a wall. */
        private boolean isFree(int r, int c) {
            return inBounds(r, c) && (grid[r][c] == '.' ||
                    (r == endRow && c == endCol));
        }

        /** True if the rectangle (r, c) is inside the grid. */
        private boolean inBounds(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }

        /** Returns true if the supplied cell has at least {@code min} free
         *  orthogonal neighbours. */
        private boolean minFreeNeighbours(int r, int c, int min) {
            int count = 0;
            for (int d = 0; d < 4; d++) {
                if (isFree(r + DR[d], c + DC[d])) {
                    count++;
                    if (count >= min) {
                        return true;
                    }
                }
            }
            return false;
        }

        /** Returns true if the start cell has at least one adjacent free cell. */
        private boolean hasFreeNeighbour(int r, int c) {
            for (int d = 0; d < 4; d++) {
                if (isFree(r + DR[d], c + DC[d])) {
                    return true;
                }
            }
            return false;
        }

        /** Returns true if the supplied coordinates correspond to the exit cell. */
        private boolean at(int r, int c, int er, int ec) {
            return r == er && c == ec;
        }
    }

    /* -------------------------------------------------------------------------
     *  I/O utilities
     * ------------------------------------------------------------------------- */
    private static BufferedReader reader;
    private static PrintWriter writer;

    /** Splits a line on whitespace. */
    private static String[] split(String line) {
        return line.trim().split("\\s+");
    }

    /** Reads the next line and splits it into tokens. */
    private static String[] readTokens() throws IOException {
        return split(reader.readLine());
    }

    /** Convenience wrapper for reading integer arguments from a token list. */
    private static int[] readInts() throws IOException {
        String[] parts = readTokens();
        int[] res = new int[parts.length];
        for (int i = 0; i < parts.length; i++) {
            res[i] = Integer.parseInt(parts[i]);
        }
        return res;
    }

    public static void main(String[] args) throws IOException {
        reader = new BufferedReader(new InputStreamReader(System.in));
        writer = new PrintWriter(System.out);

        // ----- read dimensions ----------------------------------------------------
        String[] dim = readTokens();
        int n = Integer.parseInt(dim[0]);
        int m = Integer.parseInt(dim[1]);

        // ----- read the grid -------------------------------------------------------
        char[][] grid = new char[n][];
        for (int i = 0; i < n; i++) {
            grid[i] = reader.readLine().toCharArray();
        }

        // ----- read start and end positions (1‑based in the original spec) ----------
        int[] start = readInts();
        int startRow = start[0] - 1;
        int startCol = start[1] - 1;

        int[] end = readInts();
        int endRow = end[0] - 1;
        int endCol = end[1] - 1;

        // ----- solve ---------------------------------------------------------------
        boolean possible = new LabyrinthSolver(
                grid, startRow, startCol, endRow, endCol).canEscape();

        // ----- output --------------------------------------------------------------
        writer.println(possible ? "YES" : "NO");

        // ----- clean up ------------------------------------------------------------
        reader.close();
        writer.close();
    }
}

import java.io.IOException;
import java.io.InputStream;
import java.util.Scanner;

/**
 * Refactored solver for the maze‑path problem.
 *
 * <p>Reads a grid consisting of '.' (free cell) and 'X' (blocked cell),
 * a start coordinate and a destination coordinate, then determines whether
 * a path exists from start to destination. The original program printed
 * {@code YES} when the start cell coincides with the destination and any
 * orthogonal neighbour contains '.', otherwise it performed a depth‑first
 * search.
 *
 * <p>This version improves readability, encapsulation and maintainability:
 * <ul>
 *   <li>Clear method names and meaningful variable names.</li>
 *   <li>Direction vectors are defined once.</li>
 *   <li>Input handling is separated from the algorithm.</li>
 *   <li>Mutable state is confined to dedicated fields.</li>
 *   <li>Special cases are handled explicitly.</li>
 * </ul>
 */
public class MazeSolver {

    /** Four orthogonal movement directions: up, down, left, right. */
    private static final int[][] DIRS = {
            {-1, 0},   // up
            { 1, 0},   // down
            { 0,-1},   // left
            { 0, 1}    // right
    };

    /** 2‑D character grid read from input. */
    private final char[][] grid;

    /** Visited flag matrix used by the DFS algorithm. */
    private final boolean[][] visited;

    /** Grid dimensions. */
    private final int rows;
    private final int cols;

    /** Start and destination coordinates (0‑based). */
    private final int startRow;
    private final int startCol;
    private final int targetRow;
    private final int targetCol;

    /** ---------------------------------------------------------------
     *  Construction / Input
     *  --------------------------------------------------------------- */

    /** Factory method that parses the input and creates a {@code MazeSolver}. */
    private static MazeSolver fromInput(InputStream source) {
        try (Scanner scanner = new Scanner(source)) {
            int rows = scanner.nextInt();
            int cols = scanner.nextInt();

            char[][] grid = new char[rows][];
            for (int i = 0; i < rows; ++i) {
                grid[i] = scanner.next().toCharArray();
            }

            int startR = scanner.nextInt() - 1;
            int startC = scanner.nextInt() - 1;
            int targetR = scanner.nextInt() - 1;
            int targetC = scanner.nextInt() - 1;

            return new MazeSolver(grid, startR, startC, targetR, targetC);
        }
    }

    /** Constructor that stores all data needed for the solver. */
    private MazeSolver(char[][] grid,
                       int startRow, int startCol,
                       int targetRow, int targetCol) {
        this.grid = grid;
        this.rows = grid.length;
        this.cols = grid[0].length;
        this.startRow = startRow;
        this.startCol = startCol;
        this.targetRow = targetRow;
        this.targetCol = targetCol;
        this.visited = new boolean[rows][cols];
    }

    /** ---------------------------------------------------------------
     *  Entry point
     *  --------------------------------------------------------------- */
    public static void main(String[] args) throws IOException {
        MazeSolver solver = fromInput(System.in);

        // Special case – start equals destination.
        // Original program printed "YES" if any orthogonal neighbour is '.'.
        if (solver.startRow == solver.targetRow && solver.startCol == solver.targetCol) {
            if (solver.hasOpenNeighbour(solver.startRow, solver.startCol)) {
                System.out.println("YES");
                return;
            }
        }

        System.out.println(solver.canReachDestination() ? "YES" : "NO");
    }

    /** ---------------------------------------------------------------
     *  Public API
     *  --------------------------------------------------------------- */

    /** Returns {@code true} if the destination can be reached from the start. */
    public boolean canReachDestination() {
        // The start cell must be traversable.
        if (grid[startRow][startCol] == 'X') {
            return false;
        }
        visited[startRow][startCol] = true;
        return dfs(startRow, startCol);
    }

    /** ---------------------------------------------------------------
     *  Private helpers
     *  --------------------------------------------------------------- */

    /** Checks whether the supplied coordinates have at least one orthogonal '.' neighbour. */
    private boolean hasOpenNeighbour(int r, int c) {
        for (int[] d : DIRS) {
            int nr = r + d[0];
            int nc = c + d[1];
            if (isInBounds(nr, nc) && grid[nr][nc] == '.') {
                return true;
            }
        }
        return false;
    }

    /** Depth‑first search exploring up to four orthogonal neighbours. */
    private boolean dfs(int r, int c) {
        // Destination reached.
        if (r == targetRow && c == targetCol) {
            return true;
        }

        for (int[] dir : DIRS) {
            int nr = r + dir[0];
            int nc = c + dir[1];

            // Boundary or already visited?
            if (!isInBounds(nr, nc) || visited[nr][nc]) {
                continue;
            }

            char next = grid[nr][nc];
            boolean isDestination = (nr == targetRow && nc == targetCol);

            // Allowed cells are '.' or the destination cell itself (which may be 'X')
            if (!isDestination && next != '.') {
                continue;
            }

            visited[nr][nc] = true;
            if (dfs(nr, nc)) {
                return true;
            }
            visited[nr][nc] = false; // backtrack
        }
        return false;
    }

    /** Simple bounds check for grid coordinates. */
    private boolean isInBounds(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }
}

import java.io.*;
import java.util.*;

public class Main {

    /** Direction vectors: right, left, up, down */
    private static final int[][] DIRECTIONS = {{0, 1}, {0, -1}, {-1, 0}, {1, 0}};

    public static void main(String[] args) throws IOException {
        FastScanner fs = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(System.out, true);

        int n = fs.nextInt();
        int m = fs.nextInt();

        boolean[][] walkable = new boolean[n][m];
        for (int i = 0; i < n; i++) {
            String line = fs.next();
            for (int j = 0; j < m; j++) {
                walkable[i][j] = line.charAt(j) == '.';
            }
        }

        int sx = fs.nextInt() - 1;
        int sy = fs.nextInt() - 1;
        int fx = fs.nextInt() - 1;
        int fy = fs.nextInt() - 1;

        /* Start equals finish – only possible if a neighbour is walkable */
        if (sx == fx && sy == fy) {
            out.println(hasWalkableNeighbour(sx, sy, walkable, n, m) ? "YES" : "NO");
            out.close();
            return;
        }

        /* BFS limited by the problem’s movement rules */
        if (!bfsReachable(sx, sy, fx, fy, walkable, n, m)) {
            out.println("NO");
            out.close();
            return;
        }

        /* Destination may be unreachable as a walkable cell – that is fine */
        if (!walkable[fx][fy]) {
            out.println("YES");
            out.close();
            return;
        }

        /* At least two distinct neighbours must be usable to leave the finish */
        int usableNeighbours = countValidNeighbours(fx, fy, walkable, sx, sy, n, m);
        out.println(usableNeighbours > 1 ? "YES" : "NO");
        out.close();
    }

    /** Checks whether the start cell has any walkable orthogonal neighbour. */
    private static boolean hasWalkableNeighbour(
            int x, int y, boolean[][] w, int n, int m) {
        for (int[] d : DIRECTIONS) {
            int nx = x + d[0];
            int ny = y + d[1];
            if (inBounds(nx, ny, n, m) && w[nx][ny]) {
                return true;
            }
        }
        return false;
    }

    /** Breadth‑first search respecting the relaxed move condition. */
    private static boolean bfsReachable(
            int sx, int sy, int fx, int fy,
            boolean[][] w, int n, int m) {

        boolean[][] visited = new boolean[n][m];
        Deque<int[]> q = new ArrayDeque<>();
        q.add(new int[]{sx, sy});
        visited[sx][sy] = true;

        while (!q.isEmpty()) {
            int[] cur = q.poll();
            int cx = cur[0];
            int cy = cur[1];

            if (cx == fx && cy == fy) {
                return true;
            }

            for (int[] d : DIRECTIONS) {
                int nx = cx + d[0];
                int ny = cy + d[1];
                if (inBounds(nx, ny, n, m)
                        && !visited[nx][ny]
                        && (w[nx][ny] || (nx == fx && ny == fy))) {
                    visited[nx][ny] = true;
                    q.add(new int[]{nx, ny});
                }
            }
        }
        return false;
    }

    /** Counts neighbours that are walkable or equal to the start cell. */
    private static int countValidNeighbours(
            int x, int y,
            boolean[][] w,
            int startX, int startY,
            int n, int m) {

        int cnt = 0;
        for (int[] d : DIRECTIONS) {
            int nx = x + d[0];
            int ny = y + d[1];
            if (!inBounds(nx, ny, n, m)) continue;
            if (w[nx][ny] || (nx == startX && ny == startY)) {
                cnt++;
            }
        }
        return cnt;
    }

    /** Simple bounds check. */
    private static boolean inBounds(int x, int y, int n, int m) {
        return 0 <= x && x < n && 0 <= y && y < m;
    }

    /** Fast scanner built on StreamTokenizer. */
    private static class FastScanner {
        private final StreamTokenizer tokenizer;

        FastScanner(Reader reader) {
            tokenizer = new StreamTokenizer(reader);
        }

        int nextInt() throws IOException {
            tokenizer.nextToken();
            return (int) tokenizer.nval;
        }

        String next() throws IOException {
            tokenizer.nextToken();
            return tokenizer.sval;
        }
    }
}

import java.io.*;
import java.util.*;

public class Main {

    /* Directions: up, left, down, right */
    private static final int[] DX = {0, -1, 0, 1};
    private static final int[] DY = {-1, 0, 1, 0};

    public static void main(String[] args) throws IOException {
        // Optional file name from command line
        String fileName = (args.length > 0) ? args[0] : null;

        /* Try‑with‑resources guarantees the reader is closed */
        try (InputReader reader = new InputReader(fileName)) {
            int rows = reader.nextInt();   // N
            int cols = reader.nextInt();   // M

            /* Grid is 1‑based in the original code; we keep the same layout */
            boolean[][] grid = new boolean[rows + 2][cols + 2]; // true = free ('.')
            for (int i = 1; i <= rows; i++) {
                String line = reader.nextLine().trim();
                for (int j = 1; j <= cols; j++) {
                    grid[i][j] = line.charAt(j - 1) == '.';
                }
            }

            int startR = reader.nextInt();   // r
            int startC = reader.nextInt();   // c
            int goalR  = reader.nextInt();   // tr
            int goalC  = reader.nextInt();   // tc

            boolean reachable = canReach(grid, startR, startC, goalR, goalC);
            System.out.println(reachable ? "YES" : "NO");
        }
    }

    /**
     * Determines whether the goal cell can be reached from the start cell
     * while respecting the special adjacency rule described in the original
     * program.
     */
    private static boolean canReach(boolean[][] grid,
                                    int startR, int startC,
                                    int goalR, int goalC) {
        // Goal must be a free cell
        if (!grid[goalR][goalC]) {
            return false;
        }

        // The original logic checks the number of free neighbours of the goal
        int freeNeighbourCount = countFreeNeighbours(grid, goalR, goalC);
        if (freeNeighbourCount < 2) {
            return false;
        }

        // If there is exactly one free neighbour, the path must come from the
        // start cell (otherwise it is impossible)
        if (freeNeighbourCount == 1) {
            boolean adjacentToStart = false;
            for (int d = 0; d < 4; d++) {
                int nr = goalR + DX[d];
                int nc = goalC + DY[d];
                if (grid[nr][nc] && nr == startR && nc == startC) {
                    adjacentToStart = true;
                    break;
                }
            }
            if (!adjacentToStart) {
                return false;
            }
        }

        /* Depth‑first search from the start cell; visited cells are marked */
        boolean[][] visited = new boolean[grid.length][grid[0].length];
        dfs(grid, visited, goalR, goalC, startR, startC);
        return visited[goalR][goalC];
    }

    /** Counts how many of the four orthogonal neighbours of (r,c) are free. */
    private static int countFreeNeighbours(boolean[][] grid, int r, int c) {
        int cnt = 0;
        for (int d = 0; d < 4; d++) {
            int nr = r + DX[d];
            int nc = c + DY[d];
            if (grid[nr][nc]) {
                cnt++;
            }
        }
        return cnt;
    }

    /** Simple recursive DFS that respects the same move rules as the original. */
    private static void dfs(boolean[][] grid,
                            boolean[][] visited,
                            int r, int c,
                            int sr, int sc) {
        visited[r][c] = true;
        for (int d = 0; d < 4; d++) {
            int nr = r + DX[d];
            int nc = c + DY[d];
            if (outOfBounds(visited, nr, nc)) {
                continue;
            }
            if (!visited[nr][nc] && (grid[nr][nc] || (nr == sr && nc == sc))) {
                dfs(grid, visited, nr, nc, sr, sc);
            }
        }
    }

    /** Utility to check array bounds. */
    private static boolean outOfBounds(boolean[][] arr, int i, int j) {
        return i < 0 || i >= arr.length || j < 0 || j >= arr[0].length;
    }

    /**
     * Minimal wrapper around {@link BufferedReader} that can read from a file
     * or from {@code System.in}. Implements {@link AutoCloseable} so it can be
     * used in try‑with‑resources statements.
     */
    private static final class InputReader implements AutoCloseable {
        private final BufferedReader br;

        InputReader(String fileName) throws FileNotFoundException {
            if (fileName == null) {
                br = new BufferedReader(new InputStreamReader(System.in));
            } else {
                br = new BufferedReader(new InputStreamReader(new FileInputStream(fileName)));
            }
        }

        /** Reads the next line (or {@code null} if EOF). */
        String nextLine() throws IOException {
            return br.readLine();
        }

        /** Returns the first non‑whitespace token of the current line. */
        String nextToken() throws IOException {
            return nextLine().split("\\s+")[0];
        }

        /** Reads an {@code int} token. */
        int nextInt() throws IOException {
            return Integer.parseInt(nextToken());
        }

        /** Reads a {@code long} token. */
        long nextLong() throws IOException {
            return Long.parseLong(nextToken());
        }

        @Override
        public void close() throws IOException {
            br.close();
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

/**
 * Refactored solution for the maze‑reachability problem.
 * The program reads a rectangular grid, a start cell and a goal cell,
 * treats the start cell as free, and determines whether a path exists
 * from the goal to the start following the rules described in the
 * original implementation.
 *
 * The refactor improves readability, reduces duplicated code,
 * encapsulates constants, and separates input handling from
 * the algorithmic logic.
 */
public class Solution {

    /* --------------------------------------------------------------------- *
     *  Constants & static state                                                *
     * --------------------------------------------------------------------- */
    private static final char FREE = '.';   // walkable cell
    private static final char BLOCKED = 'X'; // obstacle

    private static char[][] grid;          // the maze
    private static boolean[][] visited;    // visited flag matrix
    private static int rows, cols;         // dimensions

    /** becomes true when the start cell is reached during DFS */
    private static boolean startReached;

    /** coordinates of the start cell – needed inside the recursive DFS */
    private static int startRow, startCol;

    /** four directional movement vectors */
    private static final int[][] DIRS = {
            {1, 0}, {-1, 0}, {0, 1}, {0, -1}
    };

    /* --------------------------------------------------------------------- *
     *  Entry point                                                            *
     * --------------------------------------------------------------------- */
    public static void main(String[] args) throws IOException {
        try (InputReader reader = new InputReader()) {
            readDimensions(reader);
            readMaze(reader);
            readPoints(reader);

            // The start cell is considered traversable for the search.
            grid[startRow][startCol] = FREE;

            startReached = false;
            dfs(goalRow, goalCol);

            if (isTrivialCase() || (startReached && satisfiesGoalCondition())) {
                System.out.println("YES");
            } else {
                System.out.println("NO");
            }
        }
    }

    /* --------------------------------------------------------------------- *
     *  Input handling                                                         *
     * --------------------------------------------------------------------- */
    private static void readDimensions(InputReader in) {
        rows = in.nextInt();
        cols = in.nextInt();
    }

    private static void readMaze(InputReader in) {
        for (int r = 0; r < rows; r++) {
            grid[r] = in.next().toCharArray();
        }
    }

    private static void readPoints(InputReader in) {
        startRow = in.nextInt() - 1;
        startCol = in.nextInt() - 1;
        goalRow = in.nextInt() - 1;
        goalCol = in.nextInt() - 1;
    }

    /* --------------------------------------------------------------------- *
     *  Core algorithm                                                         *
     * --------------------------------------------------------------------- */
    /** Depth‑first search starting from (r, c). Marks visited cells and
     *  sets {@code startReached} when the start cell is encountered. */
    private static void dfs(int r, int c) {
        if (r == startRow && c == startCol) {
            startReached = true;
        }
        visited[r][c] = true;

        for (int[] dir : DIRS) {
            int nr = r + dir[0];
            int nc = c + dir[1];
            if (inside(nr, nc) && !visited[nr][nc] && grid[nr][nc] == FREE) {
                dfs(nr, nc);
            }
        }
    }

    /** Checks the special case where start and goal coincide and there is
     *  at least one adjacent free cell. */
    private static boolean isTrivialCase() {
        return startRow == goalRow && startCol == goalCol
                && hasAdjacentFreeCell(startRow, startCol);
    }

    /** Evaluates the condition used in the original program for the goal
     *  cell (whether it is blocked or has more than one adjacent free cell). */
    private static boolean satisfiesGoalCondition() {
        if (grid[goalRow][goalCol] == BLOCKED) {
            return true;
        }
        return hasAdjacentFreeCellCount(goalRow, goalCol) > 1;
    }

    /** Returns the number of orthogonal neighbours that are free ('.'). */
    private static int hasAdjacentFreeCellCount(int r, int c) {
        int cnt = 0;
        for (int[] dir : DIRS) {
            int nr = r + dir[0];
            int nc = c + dir[1];
            if (inside(nr, nc) && grid[nr][nc] == FREE) {
                cnt++;
            }
        }
        return cnt;
    }

    /** Returns true if there is at least one adjacent free cell. */
    private static boolean hasAdjacentFreeCell(int r, int c) {
        return hasAdjacentFreeCellCount(r, c) > 0;
    }

    /** Simple bounds check. */
    private static boolean inside(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    /* --------------------------------------------------------------------- *
     *  Input reader                                                            *
     * --------------------------------------------------------------------- */
    private static class InputReader {
        private final BufferedReader br;
        private StringTokenizer st;

        InputReader() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        /** Returns next token, reading a new line when the current tokenizer is empty. */
        private String next() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                st = new StringTokenizer(br.readLine());
            }
            return st.nextToken();
        }

        /** Convenience wrapper for next integer. */
        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Refactored solution for Codeforces problem 540C – Ice Cave.
 *
 * The program reads a grid of '.' (safe ice) and 'X' (thin ice) together with
 * source and destination cells, then determines whether the destination can be
 * reached under the rules of the original problem.
 *
 * The refactor focuses on readability, encapsulation and maintainability:
 *   • Clear separation of concerns (IO, state, algorithm).
 *   • Meaningful names and constants.
 *   • Small helper methods with single responsibilities.
 *   • Removal of unused code and magic numbers.
 */
public class P540C {

    // -----------------------------------------------------------------------
    // Constants
    // -----------------------------------------------------------------------
    private static final int[][] DIRECTIONS = {
            {0, 1}, {0, -1}, {1, 0}, {-1, 0}
    };

    // -----------------------------------------------------------------------
    // Entry point
    // -----------------------------------------------------------------------
    public static void main(String[] args) throws Exception {
        initializeIO();
        solve();
        reader.close();
        writer.close();
    }

    // -----------------------------------------------------------------------
    // IO helpers
    // -----------------------------------------------------------------------
    private static BufferedReader reader;
    private static StringTokenizer tokenizer;
    private static PrintWriter writer;

    private static void initializeIO() throws IOException {
        reader = new BufferedReader(new InputStreamReader(System.in));
        writer = new PrintWriter(new OutputStreamWriter(System.out));
        tokenizer = new StringTokenizer("");
    }

    /** Returns the next token from the input stream. */
    private static String next() throws IOException {
        while (!tokenizer.hasMoreTokens()) {
            tokenizer = new StringTokenizer(reader.readLine());
        }
        return tokenizer.nextToken();
    }

    /** Convenience wrapper for {@link Integer#parseInt(String)}. */
    private static int nextInt() throws IOException {
        return Integer.parseInt(next());
    }

    // -----------------------------------------------------------------------
    // Core algorithm
    // -----------------------------------------------------------------------
    private static int n, m;                 // board dimensions
    private static char[][] grid;            // original board
    private static char[][] copy;            // mutable copy used for BFS marks
    private static int startRow, startCol;    // source cell (0‑based)
    private static int targetRow, targetCol; // destination cell (0‑based)

    /** Reads the board and the four coordinates from standard input. */
    private static void readInput() throws IOException {
        n = nextInt();
        m = nextInt();

        grid = new char[n][];
        copy = new char[n][];
        for (int i = 0; i < n; i++) {
            String line = reader.readLine();
            grid[i] = line.toCharArray();
            copy[i] = Arrays.copyOf(grid[i], m);
        }

        // The next four tokens are the coordinates (1‑based in the original input)
        startRow   = nextInt() - 1;
        startCol   = nextInt() - 1;
        targetRow  = nextInt() - 1;
        targetCol  = nextInt() - 1;
    }

    private static void solve() throws IOException {
        readInput();

        // Normalise the start cell – it is considered safe for the algorithm.
        grid[startRow][startCol] = '.';

        // Trivial case: start equals target.
        if (startRow == targetRow && startCol == targetCol) {
            handleTrivialTarget();
            return;
        }

        bfs();
    }

    /** Handles the situation where the start cell is also the target cell. */
    private static void handleTrivialTarget() throws IOException {
        writer.println(check(targetRow, targetCol, true) ? "YES" : "NO");
        writer.flush();
    }

    /** Breadth‑first search from the start cell to the target cell. */
    private static void bfs() throws IOException {
        Queue<Cell> queue = new LinkedList<>();
        queue.offer(new Cell(startRow, startCol));

        while (!queue.isEmpty()) {
            Cell cur = queue.poll();

            for (int[] dir : DIRECTIONS) {
                int nx = cur.x + dir[0];
                int ny = cur.y + dir[1];

                if (!inBounds(nx, ny)) {
                    continue;
                }

                // If we have reached the target cell...
                if (nx == targetRow && ny == targetCol) {
                    // ...we succeed if the target is an 'X' or it has ≥2 safe neighbours.
                    if (grid[targetRow][targetCol] == 'X' || check(targetRow, targetCol, false)) {
                        writer.println("YES");
                        return;
                    }
                }
                // Normal traversable ice that has not been visited yet.
                else if (copy[nx][ny] == '.') {
                    copy[nx][ny] = 'X';               // mark visited
                    queue.offer(new Cell(nx, ny));
                }
            }
        }

        // Exhausted all possibilities without reaching the target.
        writer.println("NO");
    }

    /** Returns true if the given coordinate lies inside the board. */
    private static boolean inBounds(int x, int y) {
        return x >= 0 && x < n && y >= 0 && y < m;
    }

    /**
     * Counts orthogonal neighbours of (x, y) that are safe ('.') cells.
     *
     * @param x      row index
     * @param y      column index
     * @param strict when {@code true} we require at least one safe neighbour,
     *               otherwise we require at least two (used for the target cell).
     */
    private static boolean check(int x, int y, boolean strict) {
        int safeNeighbours = 0;
        for (int[] dir : DIRECTIONS) {
            int nx = x + dir[0];
            int ny = y + dir[1];
            if (inBounds(nx, ny) && grid[nx][ny] == '.') {
                safeNeighbours++;
            }
        }
        return strict ? safeNeighbours > 0 : safeNeighbours > 1;
    }

    // -----------------------------------------------------------------------
    // Helper data structure
    // -----------------------------------------------------------------------
    /** Simple container for a board coordinate. */
    private static class Cell {
        final int x, y;
        Cell(int x, int y) {
            this.x = x;
            this.y = y;
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Reads a grid from standard input and determines whether a path from a
 * source cell to a destination cell satisfies a special condition.
 *
 * <p>The grid contains two kinds of cells:
 * <ul>
 *   <li>'.' – free cell</li>
 *   <li>'X' – blocked cell</li>
 * </ul>
 *
 * The algorithm temporarily treats the start and destination cells as free,
 * then counts how many distinct paths lead from the start to the destination.
 * A path is counted only when the destination cell is reached for the first
 * time in a recursive traversal.
 *
 * <p>The program prints {@code YES} when either of the following holds:
 * <ol>
 *   <li>at least one path reaches the destination and the original
 *       destination cell contained {@code 'X'} while the start and
 *       destination are different cells, or
 *   <li>at least two distinct paths reach the destination.
 * </ol>
 * Otherwise it prints {@code NO}.
 *
 * <p>The implementation focuses on readability, encapsulation and proper
 * resource handling.
 */
public class CandidateCode {

    /* --------------------------------------------------------------------- */
    /*                         CONSTANTS & DIRECTIONS                        */
    /* --------------------------------------------------------------------- */
    private static final int[] DR = { -1, 1, 0, 0 };   // up, down, left, right
    private static final int[] DC = { 0, 0, -1, 1 };

    /* --------------------------------------------------------------------- */
    /*                         INTERNAL STATE                                 */
    /* --------------------------------------------------------------------- */
    private final char[][] grid;
    private final int rows;
    private final int cols;
    private final int srcRow, srcCol;
    private final int destRow, destCol;
    private final char originalDestChar;

    /* --------------------------------------------------------------------- */
    /*                         INPUT HELPERS                                 */
    /* --------------------------------------------------------------------- */
    /**
     * Simple buffered‐reader that lazily tokenises input lines.
     */
    private static final class InputReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        InputReader() throws IOException {
            this.reader = new BufferedReader(new InputStreamReader(System.in));
        }

        private void ensureTokenizer() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                tokenizer = new StringTokenizer(reader.readLine());
            }
        }

        String next() throws IOException {
            ensureTokenizer();
            return tokenizer.nextToken();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }

    /* --------------------------------------------------------------------- */
    /*                         CONSTRUCTION                                    */
    /* --------------------------------------------------------------------- */
    /**
     * Constructs a solver for the given grid and source/destination coordinates.
     *
     * @param grid           2‑D character array representing the map
     * @param srcRow         row index of the start cell (0‑based)
     * @param srcCol         column index of the start cell (0‑based)
     * @param destRow        row index of the destination cell (0‑based)
     * @param destCol        column index of the destination cell (0‑based)
     * @param originalDestChar the character that originally occupied the destination cell
     */
    CandidateCode(char[][] grid,
                  int srcRow, int srcCol,
                  int destRow, int destCol,
                  char originalDestChar) {
        this.grid = grid;
        this.rows = grid.length;
        this.cols = grid[0].length;
        this.srcRow = srcRow;
        this.srcCol = srcCol;
        this.destRow = destRow;
        this.destCol = destCol;
        this.originalDestChar = originalDestChar;
    }

    /* --------------------------------------------------------------------- */
    /*                         MAIN ENTRY POINT                                */
    /* --------------------------------------------------------------------- */
    public static void main(String[] args) throws IOException {
        try (InputReader reader = new InputReader()) {
            int n = reader.nextInt();                     // rows
            int m = reader.nextInt();                     // columns

            char[][] grid = new char[n][];
            for (int i = 0; i < n; i++) {
                grid[i] = reader.next().toCharArray();
            }

            // Convert 1‑based coordinates from the input to 0‑based indices
            int srcRow = reader.nextInt() - 1;
            int srcCol = reader.nextInt() - 1;
            int destRow = reader.nextInt() - 1;
            int destCol = reader.nextInt() - 1;

            char originalDestChar = grid[destRow][destCol];

            // Temporarily treat start and destination as free cells
            grid[srcRow][srcCol] = '.';
            grid[destRow][destCol] = '.';

            CandidateCode solver = new CandidateCode(grid, srcRow, srcCol,
                                                       destRow, destCol,
                                                       originalDestChar);
            int pathCount = solver.countPaths();

            boolean shouldPrintYes = (pathCount >= 1 && originalDestChar == 'X'
                    && !(srcRow == destRow && srcCol == destCol))
                    || pathCount >= 2;

            System.out.println(shouldPrintYes ? "YES" : "NO");
        }
    }

    /* --------------------------------------------------------------------- */
    /*                         PUBLIC API                                        */
    /* --------------------------------------------------------------------- */
    /**
     * Counts how many distinct paths lead from the source cell to the destination
     * cell while never stepping on a blocked cell ('X').  The method uses
     * depth‑first search with backtracking.
     *
     * @return number of distinct paths that reach the destination
     */
    int countPaths() {
        // Reset the destination cell to '.' after the temporary marking above
        grid[destRow][destCol] = '.';

        return dfs(srcRow, srcCol);
    }

    /* --------------------------------------------------------------------- */
    /*                         PRIVATE IMPLEMENTATION                           */
    /* --------------------------------------------------------------------- */
    /**
     * Depth‑first search that returns the number of ways to reach the destination
     * from the current cell (r, c).  Cells marked with 'X' are considered obstacles.
     * The method temporarily marks visited cells with 'X' and restores them on
     * backtracking so that other paths can reuse the same cell.
     *
     * @param r current row index
     * @param c current column index
     * @return number of paths that start from (r, c) and end at the destination
     */
    private int dfs(int r, int c) {
        // Out‑of‑bounds or stepping on a blocked cell → dead end
        if (!isInside(r, c) || grid[r][c] == 'X') {
            return 0;
        }

        // Destination reached – one valid path found
        if (r == destRow && c == destCol) {
            return 1;
        }

        // Mark current cell as visited
        char saved = grid[r][c];
        grid[r][c] = 'X';

        int totalPaths = 0;
        // Explore all four neighbours
        for (int dir = 0; dir < 4; dir++) {
            int nr = r + DR[dir];
            int nc = c + DC[dir];
            totalPaths += dfs(nr, nc);
        }

        // Backtrack: restore original character for other recursive branches
        grid[r][c] = saved;
        return totalPaths;
    }

    /**
     * Checks whether a given cell lies inside the grid boundaries.
     *
     * @param r row index
     * @param c column index
     * @return {@code true} if the cell is within the grid, {@code false} otherwise
     */
    private boolean isInside(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.StringTokenizer;

/**
 * Entry point of the application.
 * <p>
 * The program reads a rectangular grid, a start cell and a target cell,
 * then decides whether a path exists according to the rules described in the
 * original solution.  The code has been reorganised for readability,
 * maintainability and proper encapsulation.
 */
public class Main {

    /* --------------------------------------------------------------------- */
    /*  Utility scanner – keeps the original API used by the algorithm       */
    /* --------------------------------------------------------------------- */
    private static final class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner() {
            this.br = new BufferedReader(new InputStreamReader(System.in));
        }

        private void ensureTokenizer() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                st = new StringTokenizer(br.readLine());
            }
        }

        String next() throws IOException {
            ensureTokenizer();
            return st.nextToken();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }

        String nextLine() throws IOException {
            return br.readLine();
        }

        // The remaining helpers are kept for source‑compatibility with the
        // original snippet, even though the current solution only uses the
        // methods above.
        boolean hasNext() {
            if (st != null && st.hasMoreTokens()) {
                return true;
            }
            try {
                while (st == null || !st.hasMoreTokens()) {
                    st = new StringTokenizer(br.readLine());
                }
            } catch (Exception ignored) {
                return false;
            }
            return true;
        }

        String[] nextStrings(int n) throws IOException {
            String[] arr = new String[n];
            for (int i = 0; i < n; i++) {
                arr[i] = next();
            }
            return arr;
        }

        int[] nextInts(int n) throws IOException {
            int[] arr = new int[n];
            for (int i = 0; i < n; i++) {
                arr[i] = nextInt();
            }
            return arr;
        }

        int[][] next2Ints(int n, int m) throws IOException {
            int[][] arr = new int[n][m];
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    arr[i][j] = nextInt();
                }
            }
            return arr;
        }

        long nextLong() throws IOException {
            return Long.parseLong(next());
        }

        long[] nextLongs(int n) throws IOException {
            long[] arr = new long[n];
            for (int i = 0; i < n; i++) {
                arr[i] = nextLong();
            }
            return arr;
        }

        long[][] next2Longs(int n, int m) throws IOException {
            long[][] arr = new long[n][m];
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    arr[i][j] = nextLong();
                }
            }
            return arr;
        }

        double nextDouble() throws IOException {
            return Double.parseDouble(next().replace(',', '.'));
        }

        double[] nextDoubles(int size) throws IOException {
            double[] arr = new double[size];
            for (int i = 0; i < size; i++) {
                arr[i] = nextDouble();
            }
            return arr;
        }

        boolean nextBool() throws IOException {
            String s = next();
            if (s.equalsIgnoreCase("true") || s.equals("1")) {
                return true;
            }
            if (s.equalsIgnoreCase("false") || s.equals("0")) {
                return false;
            }
            throw new IOException("Boolean expected, String found!");
        }
    }

    /* --------------------------------------------------------------------- */
    /*  Constants and helper data                                            */
    /* --------------------------------------------------------------------- */
    /** Four possible moving directions: up, down, left, right */
    private static final int[][] DIRS = {
            {-1, 0}, {1, 0}, {0, -1}, {0, 1}
    };

    /** Checks whether a cell is inside the grid limits */
    private static boolean inside(char[][] grid, int r, int c) {
        return r >= 0 && r < grid.length && c >= 0 && c < grid[0].length;
    }

    /** Counts how many neighbours of (r,c) are open ('.') */
    private static int countOpenNeighbours(char[][] grid, int r, int c) {
        int cnt = 0;
        for (int[] d : DIRS) {
            int nr = r + d[0];
            int nc = c + d[1];
            if (inside(grid, nr, nc) && grid[nr][nc] == '.') {
                cnt++;
            }
        }
        return cnt;
    }

    /* --------------------------------------------------------------------- */
    /*  Core algorithm                                                       */
    /* --------------------------------------------------------------------- */
    /**
     * Depth‑first search that tries to reach the target cell from the given
     * position.  Visited cells are temporarily marked as blocked ('X') to
     * avoid cycles.
     *
     * @return {@code true} if the target can be reached.
     */
    private static boolean canReachTarget(char[][] grid,
                                          int startR, int startC,
                                          int targetR, int targetC) {
        if (!inside(grid, startR, startC)) {
            return false;
        }
        if (startR == targetR && startC == targetC) {
            return true;
        }
        if (grid[startR][startC] == 'X') {
            return false;                 // already blocked / visited
        }
        // Mark current cell as visited
        grid[startR][startC] = 'X';

        // Explore neighbours recursively
        for (int[] d : DIRS) {
            int nr = startR + d[0];
            int nc = startC + d[1];
            if (canReachTarget(grid, nr, nc, targetR, targetC)) {
                return true;
            }
        }
        return false;
    }

    /* --------------------------------------------------------------------- */
    /*  Program entry point                                                  */
    /* --------------------------------------------------------------------- */
    public static void main(String[] args) throws IOException {
        FastScanner scanner = new FastScanner();
        PrintWriter out = new PrintWriter(System.out, true);

        /* ---------- Input ---------- */
        int n = scanner.nextInt();          // number of rows
        int m = scanner.nextInt();          // number of columns

        char[][] grid = new char[n][];
        for (int i = 0; i < n; i++) {
            String line = scanner.next();   // each row as a string
            grid[i] = line.toCharArray();
        }

        // Convert coordinates to 0‑based indices
        int startR = scanner.nextInt() - 1;
        int startC = scanner.nextInt() - 1;
        int targetR = scanner.nextInt() - 1;
        int targetC = scanner.nextInt() - 1;

        // The start cell is considered free for the path
        grid[startR][startC] = '.';

        /* ---------- Special case: start == target ---------- */
        if (startR == targetR && startC == targetC) {
            // At least one adjacent free cell allows "movement"
            if (countOpenNeighbours(grid, targetR, targetC) >= 1) {
                out.println("YES");
                return;
            }
        }

        /* ---------- Try to find any path ---------- */
        if (!canReachTarget(grid, startR, startC, targetR, targetC)) {
            out.println("NO");
            return;
        }

        /* ---------- Final decision ---------- */
        boolean targetIsBlocked = grid[targetR][targetC] == 'X';
        boolean manyOpenNeighbours = countOpenNeighbours(grid, targetR, targetC) >= 2;

        if ((targetIsBlocked && !(startR == targetR && startC == targetC))
                || manyOpenNeighbours) {
            out.println("YES");
        } else {
            out.println("NO");
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.ArrayDeque;
import java.util.Deque;
import java.util.StringTokenizer;

/**
 * Finds whether a path exists from a start cell to a target cell in a grid.
 *
 * <p>Rules:
 * <ul>
 *   <li>The grid consists of '.' (free cell) and 'X' (blocked cell).</li>
 *   <li>Movement is allowed to adjacent cells (up, down, left, right).</li>
 *   <li>The target cell may be visited twice in total (once during normal BFS and once
 *       after stepping on it from the start). This special handling is required when the
 *       target cell itself is a blocked cell ('X').</li>
 * </ul>
 */
public class Main {

    /** Directions: left, right, up, down */
    private static final int[] DX = {0, 0, -1, 1};
    private static final int[] DY = {-1, 1, 0, 0};

    /** Simple container for a grid coordinate. */
    private static final class Position {
        final int x;
        final int y;

        Position(int x, int y) {
            this.x = x;
            this.y = y;
        }
    }

    public static void main(String[] args) throws IOException {
        /* -------------------------------------------------
         *  Input handling (try‑with‑resources guarantees close)
         * ------------------------------------------------- */
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in))) {
            StringTokenizer st = new StringTokenizer(br.readLine());
            int rows = Integer.parseInt(st.nextToken());
            int cols = Integer.parseInt(st.nextToken());

            char[][] grid = new char[rows][];
            for (int r = 0; r < rows; r++) {
                grid[r] = br.readLine().toCharArray();
            }

            st = new StringTokenizer(br.readLine());
            int startX = Integer.parseInt(st.nextToken()) - 1;
            int startY = Integer.parseInt(st.nextToken()) - 1;

            st = new StringTokenizer(br.readLine());
            int endX = Integer.parseInt(st.nextToken()) - 1;
            int endY = Integer.parseInt(st.nextToken()) - 1;

            boolean reachable = bfs(grid, startX, startY, endX, endY);
            System.out.println(reachable ? "YES" : "NO");
        }
    }

    /**
     * Breadth‑first search that determines whether the target cell can be reached.
     *
     * @return {@code true} if a path satisfying the special ending condition exists.
     */
    private static boolean bfs(char[][] grid, int sx, int sy, int ex, int ey) {
        int rows = grid.length;
        int cols = grid[0].length;

        int[][] visited = new int[rows][cols];
        Deque<Position> queue = new ArrayDeque<>();
        queue.add(new Position(sx, sy));
        visited[sx][sy] = 1; // mark start as visited

        while (!queue.isEmpty()) {
            Position cur = queue.removeFirst();

            if (cur.x == ex && cur.y == ey && canFinish(cur.x, cur.y, ex, ey, visited, grid)) {
                return true;
            }

            for (int d = 0; d < DX.length; d++) {
                int nx = cur.x + DX[d];
                int ny = cur.y + DY[d];
                if (!isInside(nx, ny, rows, cols)) {
                    continue;
                }

                // Handle the destination specially: it may be added even if visited
                // once, because we need to count a second visit for blocked targets.
                if (nx == ex && ny == ey) {
                    visited[nx][ny]++;
                    queue.add(new Position(nx, ny));
                } else if (visited[nx][ny] == 0 && grid[nx][ny] != 'X') {
                    visited[nx][ny] = 1;
                    queue.add(new Position(nx, ny));
                }
            }
        }
        return false;
    }

    /**
     * Determines whether the current cell can serve as a valid finishing point.
     *
     * @param x      current row
     * @param y      current column
     * @param ex     target row
     * @param ey     target column
     * @param vis    visited‑counter matrix
     * @param grid   the grid
     * @return {@code true} if the cell satisfies the special ending rule.
     */
    private static boolean canFinish(int x, int y, int ex, int ey, int[][] vis, char[][] grid) {
        if (vis[x][y] >= 2) {
            return true; // visited twice – allowed for any cell
        }
        // If we arrived exactly at the target from the start, the target must be an
        // obstacle ('X') and we must not be evaluating the start itself as the target.
        return vis[x][y] == 1 && grid[x][y] == 'X' && !(x == ex && y == ey);
    }

    /** Utility to test whether a coordinate lies inside the grid bounds. */
    private static boolean isInside(int x, int y, int rows, int cols) {
        return x >= 0 && x < rows && y >= 0 && y < cols;
    }
}

import java.io.*;
import java.util.StringTokenizer;

/**
 * Main entry point. Handles input / output streams and delegates the
 * solving logic to {@link IceCaveSolver}.
 */
public class IceCave {

    public static void main(String[] args) throws IOException {
        // Using try‑with‑resources guarantees that the streams are closed.
        try (InputStream in = System.in;
             OutputStream out = System.out) {

            new IceCaveSolver().solve(in, out);
        }
    }
