/**
 * Core solving logic for the “Ice Cave” problem.
 * <p>
 *   1. Reads the board and the start / target coordinates.
 *   2. Clears the start cell (makes it traversable).
 *   3. Runs a depth‑first search that respects the problem’s rules.
 *   4. Emits “YES” if a path exists, otherwise “NO”.
 * </p>
 */
class IceCaveSolver {

    /** Direction vectors used for exploring neighbours. */
    private static final int[][] DIRS = {
            {-1, 0}, {1, 0}, {0, -1}, {0, 1}
    };

    public void solve(InputStream input, OutputStream output) throws IOException {
        FastScanner fs = new FastScanner(input);
        PrintWriter pw = new PrintWriter(output);

        int rows = fs.nextInt();
        int cols = fs.nextInt();

        char[][] board = readBoard(fs, rows, cols);
        int startRow = fs.nextInt() - 1;
        int startCol = fs.nextInt() - 1;
        int targetRow = fs.nextInt() - 1;
        int targetCol = fs.nextInt() - 1;

        // The problem guarantees that the start cell must be treated as empty.
        board[startRow][startCol] = '.';

        boolean reachable = hasPath(board, startRow, startCol, targetRow, targetCol);
        pw.println(reachable ? "YES" : "NO");
        pw.flush();
    }

    /**
     * Reads {@code rows} lines of length {@code cols} from the scanner.
     */
    private static char[][] readBoard(FastScanner fs, int rows, int cols) {
        char[][] board = new char[rows][cols];
        for (int r = 0; r < rows; r++) {
            String line = fs.next();
            for (int c = 0; c < cols; c++) {
                board[r][c] = line.charAt(c);
            }
        }
        return board;
    }

    /**
     * Depth‑first search that follows the original algorithm but is clearer
     * and easier to maintain.
     *
     * @return {@code true} if the target cell can be stepped onto.
     */
    private boolean hasPath(char[][] board, int r, int c,
                            int tr, int tc) {

        // Out‑of‑bounds or hitting a wall ends the current branch.
        if (!inBounds(board, r, c) || board[r][c] == 'X') {
            return false;
        }

        // Reached the target cell.
        if (r == tr && c == tc) {
            // The hole is represented by 'X'.  If the cell is already a hole,
            // we are done.  Otherwise we must be able to step onto it from
            // an adjacent empty cell (the original specification).
            return board[tr][tc] == 'X' ||
                    adjacentEmptyCellExists(board, tr, tc);
        }

        // Mark current cell as visited by turning it into a wall.
        board[r][c] = 'X';

        // Explore the four neighbours.
        for (int[] d : DIRS) {
            int nr = r + d[0];
            int nc = c + d[1];
            if (hasPath(board, nr, nc, tr, tc)) {
                // Restore the cell before returning – important for backtracking.
                board[r][c] = '.';
                return true;
            }
        }

        // Backtrack: restore the original content and remember that this
        // cell cannot lead to the target.
        board[r][c] = '.';
        return false;
    }

    /**
     * Checks whether any of the four orthogonal neighbours of the target cell
     * is an empty ('.') cell.  This mirrors the original rule that stepping
     * onto the hole requires an adjacent empty square.
     */
    private boolean adjacentEmptyCellExists(char[][] board, int r, int c) {
        for (int[] d : DIRS) {
            int nr = r + d[0];
            int nc = c + d[1];
            if (inBounds(board, nr, nc) && board[nr][nc] == '.') {
                return true;
            }
        }
        return false;
    }

    /** Utility method that validates array bounds. */
    private static boolean inBounds(char[][] board, int row, int col) {
        return row >= 0 && row < board.length &&
               col >= 0 && col < board[0].length;
    }
}

/**
 * Fast scanner that mimics the original {@code InputReader} but is kept
 * private to this package to avoid exposure of implementation details.
 */
class FastScanner {
    private final BufferedReader reader;
    private StringTokenizer tokenizer;

    FastScanner(InputStream stream) {
        reader = new BufferedReader(new InputStreamReader(stream), 32768);
        tokenizer = null;
    }

    /** Returns the next token, reading a new line if necessary. */
    private String nextToken() {
        while (tokenizer == null || !tokenizer.hasMoreTokens()) {
            try {
                tokenizer = new StringTokenizer(reader.readLine());
            } catch (IOException e) {
                throw new UncheckedIOException(e);
            }
        }
        return tokenizer.nextToken();
    }

    /** Convenience wrapper around {@code nextToken()} returning an int. */
    int nextInt() {
        return Integer.parseInt(nextToken());
    }
}

/**
 * Refactored solution for the “Ice Cave” problem.
 * Reads a grid, a start cell and an end cell and determines whether a path
 * exists from start to end moving through '.' cells (or the end cell itself).
 *
 * The program keeps the original behaviour but improves maintainability,
 * readability and structure.
 */
public class IceCave {

    /** Directions: down, left, up, right */
    private static final int[][] DIRECTIONS = {{1, 0}, {0, -1}, {-1, 0}, {0, 1}};

    /** Simple holder for a cell coordinate */
    private static final class Position {
        final int row;
        final int col;

        Position(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }

    /** Small wrapper that holds the grid and provides useful accessor methods */
    private static final class Grid {
        private final char[][] board;
        private final int rows;
        private final int cols;

        Grid(char[][] board) {
            this.board = board;
            this.rows = board.length;
            this.cols = board[0].length;
        }

        int getRows() {
            return rows;
        }

        int getCols() {
            return cols;
        }

        boolean inBounds(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }

        /**
         * Checks whether the cell at (r,c) is traversable ('.').
         * The target cell may also be 'X' – the caller can decide to treat it as reachable
         * (e.g., when we have arrived at the destination).
         */
        boolean isOpen(int r, int c) {
            return board[r][c] == '.';
        }

        /**
         * Marks the cell as visited. This implementation uses a separate
         * boolean matrix so the original board stays untouched.
         */
        void markVisited(boolean[][] visited, int r, int c) {
            visited[r][c] = true;
        }

        boolean isVisited(boolean[][] visited, int r, int c) {
            return visited[r][c];
        }
    }

    /** Core BFS algorithm – returns true if a path exists from start to end */
    private static boolean hasPath(Grid grid, Position start, Position end) {
        boolean[][] visited = new boolean[grid.getRows()][grid.getCols()];
        java.util.Queue<Position> queue = new java.util.ArrayDeque<>();
        queue.offer(start);
        visited[start.row][start.col] = true;

        while (!queue.isEmpty()) {
            Position cur = queue.poll();

            // Early exit if we reached the destination cell
            if (cur.row == end.row && cur.col == end.col) {
                return true;
            }

            for (int[] dir : DIRECTIONS) {
                int nextRow = cur.row + dir[0];
                int nextCol = cur.col + dir[1];

                if (!grid.inBounds(nextRow, nextCol)) {
                    continue;
                }

                if (grid.isVisited(visited, nextRow, nextCol)) {
                    continue;
                }

                // Destination cell may be something other than '.', but it is still reachable
                boolean isTarget = (nextRow == end.row && nextCol == end.col);
                if (!isTarget && !grid.isOpen(nextRow, nextCol)) {
                    continue;
                }

                // Mark and enqueue neighbour
                grid.markVisited(visited, nextRow, nextCol);
                queue.offer(new Position(nextRow, nextCol));
            }
        }
        return false;
    }

    /** Simple entry point that glues everything together */
    public static void main(String[] args) {
        // Try‑with‑resources ensures the scanner is closed promptly
        try (java.util.Scanner scanner = new java.util.Scanner(System.in)) {
            int rows = scanner.nextInt();
            int cols = scanner.nextInt();

            char[][] rawBoard = new char[rows][];
            for (int r = 0; r < rows; r++) {
                rawBoard[r] = scanner.next().toCharArray();
            }

            // Parse start and end positions (they are 1‑based in the input)
            Position start = new Position(scanner.nextInt() - 1, scanner.nextInt() - 1);
            Position end   = new Position(scanner.nextInt() - 1, scanner.nextInt() - 1);

            Grid grid = new Grid(rawBoard);
            boolean reachable = hasPath(grid, start, end);
            System.out.println(reachable ? "YES" : "NO");
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.StringTokenizer;

/**
 * Refactored solution for the original contest problem.
 * <p>
 * The program reads a grid, a start cell and a goal cell.
 * It decides whether the goal can be reached under the following rules:
 * <ul>
 *   <li>If start equals goal – answer is {@code YES} only when at least one
 *       neighboring cell is traversable ('.').</li>
 *   <li>If start and goal are neighbours – answer is {@code YES} if the
 *       goal cell is blocked ('X') or has at least one traversable neighbour.</li>
 *   <li>Otherwise – answer is {@code YES} if a path exists from start to goal
 *       and the goal cell has at least two traversable neighbours (or is blocked).</li>
 * </ul>
 *
 * The refactor focuses on readability, separation of concerns and removal of
 * duplicated code while preserving the original behaviour.
 */
public class Main {

    /* --------------------------------------------------------------------- */
    /*                           CONSTANTS & STATE                           */
    /* --------------------------------------------------------------------- */

    private static MyScanner scanner;
    private static PrintWriter printer;

    private static char[][] grid;   // grid characters
    private static boolean[][] visited; // DFS visitation flags
    private static int rows, cols;    // grid dimensions
    private static int startRow, startCol; // start position (0‑based)
    private static int goalRow, goalCol;   // goal position (0‑based)

    /* --------------------------------------------------------------------- */
    /*                                MAIN                                    */
    /* --------------------------------------------------------------------- */

    public static void main(String[] args) {
        setupIO();
        readInput();
        solve();
        printer.close();
    }

    /** Reads all data from {@link MyScanner}. */
    private static void readInput() {
        rows = scanner.nextInt();
        cols = scanner.nextInt();
        grid = new char[rows][cols];

        for (int i = 0; i < rows; i++) {
            String line = scanner.next();
            for (int j = 0; j < cols; j++) {
                grid[i][j] = line.charAt(j);
            }
        }

        startRow = scanner.nextInt() - 1;
        startCol = scanner.nextInt() - 1;
        goalRow = scanner.nextInt() - 1;
        goalCol = scanner.nextInt() - 1;
    }

    /** Contains the whole decision logic, split into small helper methods. */
    private static void solve() {
        // Goal is the same as the start cell.
        if (at(startRow, startCol, goalRow, goalCol)) {
            boolean hasTraversableNeighbour = hasTraversableNeighbour(goalRow, goalCol);
            printer.println(hasTraversableNeighbour ? "YES" : "NO");
            return;
        }

        // Start and goal are adjacent.
        if (areNeighbours(startRow, startCol, goalRow, goalCol)) {
            if (grid[goalRow][goalCol] == 'X') {
                printer.println("YES");
            } else {
                boolean hasTraversableNeighbour = hasTraversableNeighbour(goalRow, goalCol);
                printer.println(hasTraversableNeighbour ? "YES" : "NO");
            }
            return;
        }

        // General case – BFS/DFS from start to goal.
        boolean reachable = dfs(startRow, startCol);
        if (!reachable) {
            printer.println("NO");
            return;
        }

        // Goal cell analysis after a path is known.
        if (grid[goalRow][goalCol] == 'X') {
            printer.println("YES");
        } else {
            int freeNeighbourCount = countFreeNeighbours(goalRow, goalCol);
            printer.println(freeNeighbourCount >= 2 ? "YES" : "NO");
        }
    }

    /* --------------------------------------------------------------------- */
    /*                     RECURSIVE SEARCH (DFS)                             */
    /* --------------------------------------------------------------------- */

    /** Depth‑first search that returns {@code true} if the goal can be reached. */
    private static boolean dfs(int r, int c) {
        visited[r][c] = true;
        if (r == goalRow && c == goalCol) {
            return true;
        }

        // Explore the four cardinal directions.
        for (int[] dir : DIRECTIONS) {
            int nr = r + dir[0];
            int nc = c + dir[1];
            if (isValidTraversal(nr, nc)) {
                if (dfs(nr, nc)) {
                    return true; // early exit on first successful path
                }
            }
        }
        return false;
    }

    /** Checks whether a cell can be entered during the search. */
    private static boolean isValidTraversal(int r, int c) {
        return inBounds(r, c) && grid[r][c] == '.' && !visited[r][c];
    }

    /** Simple bounds test. */
    private static boolean inBounds(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    /** Returns {@code true} if the given cell contains a traversable neighbour. */
    private static boolean hasTraversableNeighbour(int r, int c) {
        for (int[] dir : DIRECTIONS) {
            int nr = r + dir[0];
            int nc = c + dir[1];
            if (inBounds(nr, nc) && grid[nr][nc] == '.') {
                return true;
            }
        }
        return false;
    }

    /** Counts how many of the four neighbours of (r,c) are traversable ('.'). */
    private static int countFreeNeighbours(int r, int c) {
        int count = 0;
        for (int[] dir : DIRECTIONS) {
            int nr = r + dir[0];
            int nc = c + dir[1];
            if (inBounds(nr, nc) && grid[nr][nc] == '.') {
                count++;
            }
        }
        return count;
    }

    /** Returns {@code true} if (x,y) and (goalRow,goalCol) share a side. */
    private static boolean areNeighbours(int x, int y, int gx, int gy) {
        return (Math.abs(x - gx) + Math.abs(y - gy)) == 1;
    }

    /** Returns {@code true} if the supplied coordinates refer to the start cell. */
    private static boolean at(int x, int y, int gx, int gy) {
        return x == gx && y == gy;
    }

    /* --------------------------------------------------------------------- */
    /*                           DIRECTION HELPERS                           */
    /* --------------------------------------------------------------------- */

    /** The four cardinal directions: down, right, up, left. */
    private static final int[][] DIRECTIONS = {
            {1, 0},
            {0, 1},
            {-1, 0},
            {0, -1}
    };

    /* --------------------------------------------------------------------- */
    /*                         SIMPLE INPUT WRAPPER                           */
    /* --------------------------------------------------------------------- */

    private static void setupIO() {
        scanner = new MyScanner();
        printer = new PrintWriter(System.out);
    }

    /* --------------------------------------------------------------------- */
    /*                           SUPPORTING SCANNER                           */
    /* --------------------------------------------------------------------- */

    /**
     * Minimal scanner that reads tokens from {@code System.in}.
     * Parses {@code int}, {@code long}, {@code double} and {@code String}.
     */
    public static class MyScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public MyScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        long nextLong() {
            return Long.parseLong(next());
        }

        double nextDouble() {
            return Double.parseDouble(next());
        }

        String nextLine() {
            try {
                return br.readLine();
            } catch (IOException e) {
                throw new RuntimeException(e);
            }
        }
    }
}

import java.util.LinkedList;
import java.util.Queue;
import java.util.Scanner;

/**
 * Ice‑cave path‑finding utility.
 *
 * <p>This class reads a rectangular grid of characters, a start cell and an end cell,
 * then determines whether a path exists from start to end moving only through
 * non‑blocked cells ('O') using a breadth‑first search.</p>
 */
public class Main {

    /** Four possible movement directions: down, up, right, left */
    private static final int[][] DIRECTIONS = {
            {1, 0},   // down
            {-1, 0},  // up
            {0, 1},   // right
            {0, -1}   // left
    };

    /** Simple immutable container for a cell coordinate. */
    private static final class Position {
        final int row;
        final int col;

        Position(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }

    /**
     * Entry point of the program.
     *
     * <p>It parses the input, runs the breadth‑first search and prints {@code YES}
     * if the destination is reachable, otherwise {@code NO}.</p>
     */
    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            int rows = scanner.nextInt();
            int columns = scanner.nextInt();
            scanner.nextLine();                     // consume the line break

            char[][] grid = readGrid(scanner, rows, columns);
            Position start = readStart(scanner);
            Position end   = readEnd(scanner);

            boolean reachable = bfs(grid, start, end);
            System.out.println(reachable ? "YES" : "NO");
        }
    }

    /** Reads the ice‑cave layout from the scanner. */
    private static char[][] readGrid(Scanner scanner, int rows, int columns) {
        char[][] grid = new char[rows][columns];
        for (int i = 0; i < rows; i++) {
            String line = scanner.nextLine().trim();
            for (int j = 0; j < Math.min(line.length(), columns); j++) {
                grid[i][j] = line.charAt(j);
            }
        }
        return grid;
    }

    /** Reads the start coordinate (1‑based) and converts it to a {@link Position}. */
    private static Position readStart(Scanner scanner) {
        int r = scanner.nextInt() - 1;
        int c = scanner.nextInt() - 1;
        return new Position(r, c);
    }

    /** Reads the end coordinate (1‑based) and converts it to a {@link Position}. */
    private static Position readEnd(Scanner scanner) {
        int r = scanner.nextInt() - 1;
        int c = scanner.nextInt() - 1;
        return new Position(r, c);
    }

    /**
     * Performs a breadth‑first search to test whether {@code end} can be reached
     * from {@code start} inside {@code grid}.
     *
     * <p>Visited cells are marked as obstacles ('X') to avoid revisiting them.</p>
     *
     * @return {@code true} if the end cell is reachable, {@code false} otherwise
     */
    private static boolean bfs(char[][] grid, Position start, Position end) {
        if (grid[start.row][start.col] == 'X' || grid[end.row][end.col] == 'X') {
            return false; // start or end is blocked
        }

        Queue<Position> queue = new LinkedList<>();
        queue.add(start);
        grid[start.row][start.col] = 'X'; // mark as visited

        while (!queue.isEmpty()) {
            Position current = queue.poll();

            for (int[] dir : DIRECTIONS) {
                int nr = current.row + dir[0];
                int nc = current.col + dir[1];

                // Boundary validation
                if (nr < 0 || nr >= grid.length || nc < 0 || nc >= grid[0].length) {
                    continue;
                }

                if (grid[nr][nc] == 'X') {
                    if (nr == end.row && nc == end.col) {
                        return true; // destination reached
                    }
                    continue; // treat as obstacle
                }

                // Mark visited and enqueue
                grid[nr][nc] = 'X';
                queue.add(new Position(nr, nc));
            }
        }
        return false; // queue exhausted without reaching the destination
    }
}

import java.io.*;
import java.util.*;

/**
 * Main class handling input, processing and output.
 */
public class SolveContest {

    /** Directions: right, left, down, up */
    private static final int[][] DIRS = {
            {0, 1}, {0, -1}, {1, 0}, {-1, 0}
    };

    private BufferedReader reader;
    private PrintWriter writer;

    /** Entry point – opens input (file or stdin) and starts solving. */
    public SolveContest() {
        try (File inputFile = new File("input.txt")) {
            initializeIO(inputFile);
            solveAndPrintResult();
        } catch (IOException e) {
            // Fallback to console I/O if the file is missing or unreadable
            initializeIO(new File(new InputStreamReader(System.in)));
            solve();
        } finally {
            closeResources();
        }
    }

    /** Sets up input and output streams – either from a file or from System streams. */
    private void initializeIO(File source) throws IOException {
        reader = new BufferedReader(new FileReader(source));
        writer = new PrintWriter(new FileWriter("output.txt", true));
    }

    /** Core logic: reads the grid, runs BFS and prints YES/NO. */
    private void solveAndPrintResult() {
        int rows = nextInt();
        int cols = nextInt();

        char[][] grid = new char[rows][cols];
        for (int r = 0; r < rows; r++) {
            String line = nextToken();
            System.arraycopy(line.toCharArray(), 0, grid[r], 0, cols);
        }

        Point start = readPoint();
        Point finish = readPoint();

        if (breadthFirstSearch(grid, start, finish)) {
            writer.println("YES");
        } else {
            writer.println("NO");
        }
    }

    /** Reads a single point (row, column) from token stream, applying 0‑based conversion. */
    private Point readPoint() {
        return new Point(nextInt() - 1, nextInt() - 1);
    }

    /** Performs BFS from {@code start} to {@code finish}. */
    private boolean breadthFirstSearch(char[][] grid, Point start, Point finish) {
        if (!isInside(start)) {
            return false;
        }

        Queue<Point> queue = new ArrayDeque<>();
        boolean[][] visited = new boolean[grid.length][grid[0].length];
        queue.add(start);
        visited[start.row][start.col] = true;

        while (!queue.isEmpty()) {
            Point cur = queue.poll();
            exploreNeighbours(cur, grid, visited, queue);
            if (cur.equals(finish)) {
                // Destination reached – the cell may be 'X' but we treat reaching it as success.
                return true;
            }
        }
        return false;
    }

    /** Explores all 4‑directional neighbours of {@code cur}. */
    private void exploreNeighbours(Point cur, char[][] grid,
                                   boolean[][] visited,
                                   Queue<Point> queue) {
        for (int[] d : DIRS) {
            int nextRow = cur.row + d[0];
            int nextCol = cur.col + d[1];
            Point next = new Point(nextRow, nextCol);

            if (!isInside(next)) {
                continue;
            }
            if (visited[nextRow][nextCol]) {
                continue;
            }
            char cell = grid[nextRow][nextCol];
            if (cell == 'X' && !next.equals(finish)) {
                continue;                 // obstacle 'X' blocks the way (except the finish cell)
            }
            visited[nextRow][nextCol] = true;
            queue.add(next);
        }
    }

    /** Returns true if {@code p} lies within the current grid bounds. */
    private boolean isInside(Point p) {
        return 0 <= p.row && p.row < rows
                && 0 <= p.col && p.col < cols;
    }

    /** Simple holder for a 2‑D coordinate. */
    private static final class Point {
        final int row;
        final int col;

        Point(int row, int col) {
            this.row = row;
            this.col = col;
        }

        @Override
        public boolean equals(Object o) {
            if (this == o) return true;
            if (!(o instanceof Point)) return false;
            Point other = (Point) o;
            return row == other.row && col == other.col;
        }

        @Override
        public int hashCode() {
            return Objects.hash(row, col);
        }
    }

    /** Reads the next invisible‑separated token from the input stream. */
    private String nextToken() throws IOException {
        while (st == null || !st.hasMoreTokens()) {
            st = new StringTokenizer(reader.readLine());
        }
        return st.nextToken();
    }

    /** Reads an integer from the next token. */
    private int nextInt() {
        return Integer.parseInt(nextToken());
    }

    /** Reads a long from the next token. */
    private long nextLong() {
        return Long.parseLong(nextToken());
    }

    /* ---------- Input token utilities ---------- */
    private StringTokenizer st;

    // Grid dimensions stored as fields for use in neighbour checks
    private int rows;
    private int cols;

    /** Closes the underlying reader and writer streams. */
    private void closeResources() {
        try {
            if (reader != null) {
                reader.close();
            }
        } catch (IOException e) {
            // ignore – not critical
        }
        writer.close();
    }

    /** Main method – launches the solver. */
    public static void main(String[] args) {
        new SolveContest();
    }
}

import java.io.*;
import java.util.*;

/**
 * Main entry point of the program.
 * <p>
 * The program reads a maze description, a start cell and an end cell,
 * then decides whether the end can be reached from the start.
 * </p>
 */
public class Main {

    /** Represents a position in the grid. */
    private static final class Cell {
        final int row;
        final int col;

        Cell(int row, int col) {
            this.row = row;
            this.col = col;
        }

        /** Equality check based on both coordinates. */
        @Override
        public boolean equals(Object o) {
            if (this == o) return true;
            if (!(o instanceof Cell)) return false;
            Cell other = (Cell) o;
            return row == other.row && col == other.col;
        }

        @Override
        public int hashCode() {
            return Objects.hash(row, col);
        }

        @Override
        public String toString() {
            return String.format("Cell(%d,%d)", row, col);
        }
    }

    /** Simple container for the maze structure. */
    private static final class Maze {
        private final int rows;
        private final int cols;
        private final boolean[][] walkable;

        Maze(int rows, int cols) {
            this.rows = rows;
            this.cols = cols;
            this.walkable = new boolean[rows][cols];
        }

        /** Marks a cell as walkable. */
        void markWalkable(int r, int c) {
            walkable[r][c] = true;
        }

        /** Returns true if the cell is inside the board and walkable. */
        boolean isWalkable(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols && walkable[r][c];
        }
    }

    /** BFS‑based solver responsible for the reachability logic. */
    private static final class Solver {
        private static final int[][] DIRECTIONS = {
                {1, 0}, {-1, 0}, {0, 1}, {0, -1}
        };

        private final Maze maze;
        private final Cell start;
        private final Cell end;

        Solver(Maze maze, Cell start, Cell end) {
            this.maze = maze;
            this.start = start;
            this.end = end;
        }

        /** Determines if the end cell can be reached from the start cell. */
        boolean canReach() {
            // Start == End – need an adjacent walkable neighbour
            if (start.equals(end)) {
                for (int[] d : DIRECTIONS) {
                    if (maze.isWalkable(start.row + d[0], start.col + d[1])) {
                        return true;
                    }
                }
                return false;
            }

            // End must be walkable; otherwise we cannot finish there
            if (!maze.isWalkable(end.row, end.col)) {
                return false;
            }

            // If the start is adjacent to the end we can check that neighbour directly
            for (int[] d : DIRECTIONS) {
                Cell neighbour = new Cell(end.row + d[0], end.col + d[1]);
                if (maze.isWalkable(neighbour.row, neighbour.col) && bfsFrom(neighbour)) {
                    return true;
                }
            }
            // Normal case – try to reach the end from the start
            return bfsFrom(null);
        }

        /** Breadth‑first search that can optionally start from a pre‑chosen neighbour. */
        private boolean bfsFrom(Cell leave) {
            boolean[][] visited = new boolean[maze.rows][maze.cols];
            if (leave != null) {
                visited[leave.row][leave.col] = true;
            }

            Queue<Cell> queue = new ArrayDeque<>();
            queue.add(start);
            visited[start.row][start.col] = true;

            while (!queue.isEmpty()) {
                Cell cur = queue.poll();

                // Reached the destination?
                if (cur.equals(end)) {
                    return true;
                }

                // Continue expanding only from walkable cells (or the start itself)
                if (cur.equals(start) || maze.isWalkable(cur.row, cur.col)) {
                    for (int[] d : DIRECTIONS) {
                        int nr = cur.row + d[0];
                        int nc = cur.col + d[1];
                        if (maze.isWalkable(nr, nc) && !visited[nr][nc]) {
                            visited[nr][nc] = true;
                            queue.add(new Cell(nr, nc));
                        }
                    }
                }
            }
            return false;
        }
    }

    /** Factory method that builds a {@link Solver} from the textual input. */
    private static Solver buildSolver(BufferedReader reader) throws IOException {
        StringBuilder input = new StringBuilder();
        String line;
        while ((line = reader.readLine()) != null) {
            input.append(line.trim()).append(' ');
        }
        StringTokenizer tokenizer = new StringTokenizer(input.toString().trim());

        int rows = Integer.parseInt(tokenizer.nextToken());
        int cols = Integer.parseInt(tokenizer.nextToken());

        Maze maze = new Maze(rows, cols);

        // Consume the grid rows
        for (int r = 0; r < rows; r++) {
            String row = tokenizer.nextToken();
            for (int c = 0; c < cols; c++) {
                if (row.charAt(c) == '.') {
                    maze.markWalkable(r, c);
                }
            }
        }

        // Coordinates are 1‑based in the original input
        int sr = Integer.parseInt(tokenizer.nextToken()) - 1;
        int sc = Integer.parseInt(tokenizer.nextToken()) - 1;
        int er = Integer.parseInt(tokenizer.nextToken()) - 1;
        int ec = Integer.parseInt(tokenizer.nextToken()) - 1;

        return new Solver(maze, new Cell(sr, sc), new Cell(er, ec));
    }

    /** Program entry point. */
    public static void main(String[] args) throws IOException {
        // Using try‑with‑resources guarantees the stream is closed promptly
        try (BufferedReader reader = new BufferedReader(
                new InputStreamReader(System.in))) {
            Solver solver = buildSolver(reader);
            System.out.println(solver.canReach() ? "YES" : "NO");
        }
    }
}

/**
 * Warrior – solves a grid‑reachability problem using BFS.
 *
 * <p>
 *   The program reads a rectangular grid of '.' (free) and other characters.
 *   It then starts a breadth‑first search from a given start cell, marking
 *   visited cells with 'X'.  If the search can reach the target cell while
 *   that cell already contains 'X', the answer is {@code YES}, otherwise
 *   {@code NO}.
 * </p>
 */
public class Warrior {

    /* ---------- constants ---------- */
    private static final int INF = (int) 1e9;
    private static final long MOD = 1_000_000_007L;
    private static final long BASE = 101L;

    private static final int[][] DIRECTIONS = {
            {1, 0}, {-1, 0}, {0, 1}, {0, -1}
    };

    /* ---------- configuration ---------- */
    /** Switch debug output on/off (command‑line argument "d") */
    private static boolean DEBUG_MODE = false;

    /* ---------- entry point ---------- */
    public static void main(String[] args) throws Exception {
        // enable debug printing when the program is started with argument "d"
        if (args.length > 0 && "d".equalsIgnoreCase(args[0])) {
            DEBUG_MODE = true;
        }

        InputReader reader = new InputReader();
        PrintWriter printer = new PrintWriter(System.out);

        // The problem statement says there is a single test case (t = 1)
        for (int testCase = 1; testCase <= 1; testCase++) {
            new Warrior().solve(reader, printer);
        }

        printer.close();
        if (DEBUG_MODE) {
            System.err.println(); // extra newline from the original debug suffix
        }
    }

    /* ---------- core solving logic ---------- */
    /**
     * Solves one test case.
     *
     * @param reader  source of input
     * @param out     destination for output
     */
    public void solve(InputReader reader, PrintWriter out) {
        int rows = reader.nextInt();
        int cols = reader.nextInt();

        char[][] grid = readGrid(reader, rows, cols);

        Position start = readPosition(reader);
        Position end   = readPosition(reader);

        boolean found = bfs(grid, start, end);

        out.println(found ? "YES" : "NO");
    }

    /**
     * Reads a rectangular grid of characters.
     */
    private char[][] readGrid(InputReader reader, int n, int m) {
        char[][] grid = new char[n][];
        for (int i = 0; i < n; i++) {
            String line = reader.next();
            // Guard against malformed input
            if (line.length() < m) {
                throw new IllegalArgumentException("Row " + i + " is shorter than expected column count.");
            }
            grid[i] = line.toCharArray();
        }
        return grid;
    }

    /**
     * Reads a single cell position (1‑based) from the input and converts it to
     * zero‑based coordinates.
     */
    private Position readPosition(InputReader reader) {
        int r = reader.nextInt() - 1;
        int c = reader.nextInt() - 1;
        return new Position(r, c);
    }

    /**
     * Performs a breadth‑first search from {@code start} to {@code end},
     * marking visited cells with {@code 'X'}.  Returns {@code true} if the
     * search reaches {@code end} while that cell already contains {@code 'X'}.
     */
    private boolean bfs(char[][] grid, Position start, Position end) {
        // The starting cell is considered visited from the beginning
        grid[start.row][start.col] = 'X';
        java.util.Queue<Position> queue = new java.util.ArrayDeque<>();
        queue.add(start);

        while (!queue.isEmpty()) {
            Position cur = queue.poll();

            for (int[] dir : DIRECTIONS) {
                int nr = cur.row + dir[0];
                int nc = cur.col + dir[1];

                // Check bounds
                if (!inBounds(nr, grid.length, nc, grid[0].length)) {
                    continue;
                }

                // If we step onto the target cell and it is already marked as visited,
                // we have found a valid path.
                if (nr == end.row && nc == end.col && grid[nr][nc] == 'X') {
                    return true;
                }

                // Explore only unvisited free cells
                if (grid[nr][nc] == '.' ) {
                    grid[nr][nc] = 'X';
                    queue.add(new Position(nr, nc));
                }
            }
        }
        return false;
    }

    /** Helper to verify that a coordinate stays inside the grid. */
    private static boolean inBounds(int r, int rows, int c, int cols) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    /* ---------- auxiliary classes ---------- */

    /** Simple immutable container for a grid coordinate. */
    private static final class Position {
        final int row;
        final int col;

        Position(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }

    /**
     * Minimal input parser used by {@link Warrior#solve(InputReader, PrintWriter)}.
     * It tokenises lines from {@code System.in} and supplies convenient
     * {@code next*()} methods.
     */
    private static final class InputReader {
        private final BufferedReader br;
        private StringTokenizer st;

        InputReader() {
            this.br = new BufferedReader(new java.io.InputStreamReader(java.lang.System.in));
        }

        /** Returns the next token, pulling a new line if necessary. */
        private String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (java.io.IOException e) {
                    throw new UncheckedIOException(e);
                }
            }
            return st.nextToken();
        }

        int nextInt() { return Integer.parseInt(next()); }

        long nextLong() { return Long.parseLong(next()); }

        double nextDouble() { return Double.parseDouble(next()); }
    }
}

import java.util.Scanner;

/**
 * Refactored version of the original program.
 *
 * <p>
 * The program reads a rectangular grid consisting of '.' (empty) and other characters,
 * a start cell and a target cell (both given in 1‑based coordinates). It determines
 * whether the target can be reached according to the original algorithm.
 * </p>
 *
 * <p>
 * Refactoring highlights:
 * <ul>
 *   <li>Extracted constants for movement directions.</li>
 *   <li>Replaced numerous static fields with instance fields that have meaningful names.</li>
 *   <li>Split the program into small, focused methods (input handling, checks, DFS, etc.).</li>
 *   <li>Used {@code try‑with‑resources} for the {@code Scanner}.</li>
 *   <li>Removed unused variables and simplified the visited‑array logic.</li>
 *   <li>Improved readability with early exits and descriptive method names.</li>
 * </ul>
 * </p>
 */
public class C11 {

    /** Directions: up, down, left, right */
    private static final int[] DR = {-1, 1, 0, 0};
    private static final int[] DC = {0, 0, -1, 1};

    /** Grid data */
    private char[][] grid;

    /** Visited flag array */
    private boolean[][] visited;

    /** Problem parameters */
    private int rows;
    private int cols;
    private int startRow, startCol;
    private int targetRow, targetCol;

    /** Result flag */
    private boolean answerFound = false;

    public static void main(String[] args) {
        try (Scanner sc = new Scanner(System.in)) {
            new C11().run(sc);
        }
    }

    private void run(Scanner sc) {
        readDimensions(sc);
        readGrid(sc);
        readStartAndTarget(sc);
        handleTrivialStartEqualsTarget();
        clearStartCellIfNeeded();
        dfs(startRow, startCol);
        System.out.println(answerFound ? "YES" : "NO");
    }

    /** Reads the number of rows and columns. */
    private void readDimensions(Scanner sc) {
        rows = sc.nextInt();
        cols = sc.nextInt();
        grid = new char[rows][cols];
        visited = new boolean[rows][cols];
    }

    /** Reads the grid itself. */
    private void readGrid(Scanner sc) {
        for (int r = 0; r < rows; r++) {
            String line = sc.next();
            grid[r] = line.toCharArray();
        }
    }

    /** Reads start and target coordinates (converted to 0‑based). */
    private void readStartAndTarget(Scanner sc) {
        startRow = sc.nextInt() - 1;
        startCol = sc.nextInt() - 1;
        targetRow = sc.nextInt() - 1;
        targetCol = sc.nextInt() - 1;
    }

    /** Handles the special case where start equals target. */
    private void handleTrivialStartEqualsTarget() {
        if (startRow == targetRow && startCol == targetCol) {
            boolean adjacentEmpty = hasAdjacentEmpty(startRow, startCol);
            System.out.println(adjacentEmpty ? "YES" : "NO");
            System.exit(0);
        }
    }

    /** Checks if any of the four neighbours of (r,c) is an empty cell. */
    private boolean hasAdjacentEmpty(int r, int c) {
        for (int d = 0; d < 4; d++) {
            int nr = r + DR[d];
            int nc = c + DC[d];
            if (inside(nr, nc) && grid[nr][nc] == '.') {
                return true;
            }
        }
        return false;
    }

    /** Clears the start cell (makes it traversable) – performed only when start != target. */
    private void clearStartCellIfNeeded() {
        if (startRow != targetRow || startCol != targetCol) {
            grid[startRow][startCol] = '.';
        }
    }

    /** Depth‑first search that explores reachable cells. */
    private void dfs(int r, int c) {
        if (!inside(r, c) || visited[r][c]) {
            return;
        }
        visited[r][c] = true;

        // If we arrived at the target, evaluate the special condition.
        if (r == targetRow && c == targetCol) {
            evaluateTarget(r, c);
            return;
        }

        // Continue DFS only from empty cells.
        if (grid[r][c] != '.') {
            return;
        }

        // Explore the four neighbours.
        for (int dir = 0; dir < 4; dir++) {
            dfs(r + DR[dir], c + DC[dir]);
        }
    }

    /** Evaluates the special rule when the target cell is reached. */
    private void evaluateTarget(int r, int c) {
        // Original logic: reaching a non‑'.' cell is considered a success.
        if (grid[r][c] != '.') {
            answerFound = true;
            return;
        }

        // Count adjacent empty cells – the original algorithm required at least two.
        int adjacentEmptyCount = 0;
        for (int dir = 0; dir < 4; dir++) {
            int nr = r + DR[dir];
            int nc = c + DC[dir];
            if (inside(nr, nc) && grid[nr][nc] == '.') {
                adjacentEmptyCount++;
            }
        }
        answerFound = adjacentEmptyCount >= 2;
    }

    /** Utility: checks whether (r,c) lies inside the grid. */
    private boolean inside(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }
}

import java.io.*;
import java.util.*;

/**
 * Main entry point of the program.
 * <p>
 * The original code has been split into smaller, self‑contained pieces:
 * <ul>
 *   <li>{@link InputReader} – handles tokenised input.</li>
 *   <li>{@link Direction} – defines the four cardinal directions.</li>
 *   <li>{@link PathChecker} – contains the core logic (DFS, neighbour checks, etc.).</li>
 * </ul>
 * All static mutable state has been limited to the minimum required,
 * names have been made expressive, and dead code (unused imports /
 * helper functions) has been removed.
 */
public class Main {

    /** Fast output buffer used for writing the answer. */
    private static final StringBuilder OUT = new StringBuilder();

    /** Tokeniser for reading from {@code System.in}. */
    private static InputReader IN;

    /** Grid characters. */
    private static char[][] GRID;

    /** Whether the DFS has already discovered a “flag” condition. */
    private static boolean FLAG_FOUND = false;

    /** Grid dimensions. */
    private static int ROWS, COLS;

    /** Start and target cell coordinates (0‑based). */
    private static int START_X, START_Y, END_X, END_Y;

    /** Visited flag matrix used by DFS. */
    private static boolean[][] VISITED;

    /** --------------------------------------------------------------------- */
    /** Direction vectors for the four neighbours. */
    private enum Direction {
        UP(-1, 0), DOWN(1, 0), LEFT(0, -1), RIGHT(0, 1);

        final int dr, dc;

        Direction(int dr, int dc) {
            this.dr = dr;
            this.dc = dc;
        }

        /** Returns the row‑column offset for this direction. */
        int[] delta() {
            return new int[]{dr, dc};
        }
    }

    /** --------------------------------------------------------------------- */
    /** Reads all input tokens. */
    private static class InputReader {
        private final BufferedReader br;
        private StringTokenizer st;

        InputReader() {
            this.br = new BufferedReader(new InputStreamReader(System.in));
        }

        /** Ensures that a {@link StringTokenizer} with tokens is available. */
        private void ensureTokens() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    throw new UncheckedIOException(e);
                }
            }
        }

        /** Returns the next token. */
        String next() {
            ensureTokens();
            return st.nextToken();
        }

        /** Returns the next integer token. */
        int nextInt() {
            return Integer.parseInt(next());
        }

        /** Returns the next long token. */
        long nextLong() {
            return Long.parseLong(next());
        }

        /** Returns the next line (may be {@code null} on EOF). */
        String nextLine() {
            try {
                return br.readLine();
            } catch (IOException e) {
                throw new UncheckedIOException(e);
            }
        }
    }

    /** --------------------------------------------------------------------- */
    /** Orchestrates the whole solution. */
    private static void solve() {
        IN = new InputReader();

        readInput();
        if (startEqualsEnd()) {
            handleStartEqualsEnd();
            return;
        }

        VISITED = new boolean[ROWS][COLS];
        dfs(START_X, START_Y);

        boolean reachable = VISITED[END_X][END_Y] && GRID[END_X][END_Y] == 'X';
        printAnswer(FLAG_FOUND || reachable);
    }

    /** --------------------------------------------------------------------- */
    /** Reads the problem input. */
    private static void readInput() {
        ROWS = IN.nextInt();
        COLS = IN.nextInt();
        GRID = new char[ROWS][COLS];

        for (int r = 0; r < ROWS; r++) {
            GRID[r] = IN.next().toCharArray();
        }

        START_X = IN.nextInt() - 1;
        START_Y = IN.nextInt() - 1;
        END_X   = IN.nextInt() - 1;
        END_Y   = IN.nextInt() - 1;
    }

    /** --------------------------------------------------------------------- */
    /** Handles the special case where start == end. */
    private static void handleStartEqualsEnd() {
        boolean canMove = false;
        for (Direction d : Direction.values()) {
            int nr = START_X + d.delta()[0];
            int nc = START_Y + d.delta()[1];
            if (inside(nr, nc) && GRID[nr][nc] != 'X') {
                canMove = true;
                break;
            }
        }
        println(canMove ? "YES" : "NO");
    }

    /** --------------------------------------------------------------------- */
    /** Depth‑first search from (r,c). */
    private static void dfs(int r, int c) {
        if (FLAG_FOUND) {
            return;
        }
        VISITED[r][c] = true;

        // Destination reached – evaluate the special “flag” condition.
        if (r == END_X && c == END_Y) {
            evaluateDestinationCondition();
            return;
        }

        // Continue exploring neighbours.
        for (Direction d : Direction.values()) {
            int nr = r + d.delta()[0];
            int nc = c + d.delta()[1];
            if (isValidMove(nr, nc)) {
                dfs(nr, nc);
                if (FLAG_FOUND) {
                    return;
                }
            }
        }
    }

    /** --------------------------------------------------------------------- */
    /** Checks the neighbour count of the destination cell and sets {@code FLAG_FOUND}. */
    private static void evaluateDestinationCondition() {
        int freeNeighbourCount = 0;
        for (Direction d : Direction.values()) {
            int nr = END_X + d.delta()[0];
            int nc = END_Y + d.delta()[1];
            if (inside(nr, nc) && GRID[nr][nc] == '.') {
                freeNeighbourCount++;
                // As soon as we have more than one free neighbour we can decide.
                if (freeNeighbourCount > 1) {
                    FLAG_FOUND = true;
                    break;
                }
            }
        }
        // If the loop finished with 0 or 1 free neighbour we keep FLAG_FOUND = false.
    }

    /** --------------------------------------------------------------------- */
    /** Returns {@code true} if the given cell lies inside the grid bounds. */
    private static boolean inside(int r, int c) {
        return r >= 0 && r < ROWS && c >= 0 && c < COLS;
    }

    /** --------------------------------------------------------------------- */
    /** Returns {@code true} if moving to (r,c) is allowed (inside, not visited,
     *  and not an obstacle 'X'). */
    private static boolean isValidMove(int r, int c) {
        return inside(r, c) && !VISITED[r][c] && GRID[r][c] != 'X';
    }

    /** --------------------------------------------------------------------- */
    /** Prints the result to standard output. */
    private static void printAnswer(boolean answer) {
        println(answer ? "YES" : "NO");
    }

    /** --------------------------------------------------------------------- */
    /** Simple wrapper around {@link StringBuilder} that adds a line break. */
    private static void println(String s) {
        OUT.append(s).append('\n');
    }

    /** --------------------------------------------------------------------- */
    /** Executes the program. */
    public static void main(String[] args) {
        solve();
        System.out.print(OUT.toString());
    }
}

import java.util.Arrays;
import java.util.Scanner;

public class MazeSolver {

    private static final int[][] DIRECTIONS = {{0, -1}, {-1, 0}, {0, 1}, {1, 0}};

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int rows = scanner.nextInt();
        int columns = scanner.nextInt();
        char[][] grid = readGrid(scanner, rows);
        int startRow = scanner.nextInt() - 1;
        int startCol = scanner.nextInt() - 1;
        int endRow = scanner.nextInt() - 1;
        int endCol = scanner.nextInt() - 1;

        int adjacentFreeCells = countAdjacentFreeCells(grid, endRow, endCol, rows, columns);
        int[][] visited = initializeVisited(rows, columns);

        boolean hasPath = dfs(grid, visited, rows, columns, startRow, startCol, endRow, endCol, adjacentFreeCells, 0);
        System.out.print(hasPath ? "YES" : "NO");
    }

    private static char[][] readGrid(Scanner scanner, int rows) {
        char[][] grid = new char[rows][];
        for (int i = 0; i < rows; i++) {
            grid[i] = scanner.next().toCharArray();
        }
        return grid;
    }

    private static int countAdjacentFreeCells(char[][] grid, int row, int col, int rows, int columns) {
        int count = 0;
        for (int[] direction : DIRECTIONS) {
            int newRow = row + direction[0];
            int newCol = col + direction[1];
            if (isValid(newRow, newCol, rows, columns) && grid[newRow][newCol] == '.') {
                count++;
            }
        }
        return count;
    }

    private static int[][] initializeVisited(int rows, int columns) {
        int[][] visited = new int[rows][columns];
        for (int[] row : visited) {
            Arrays.fill(row, -1);
        }
        return visited;
    }

    private static boolean dfs(char[][] grid, int[][] visited, int rows, int columns, 
                              int currentRow, int currentCol, int endRow, int endCol,
                              int adjacentFreeCells, int depth) {
        if (currentRow == endRow && currentCol == endCol) {
            return handleDestination(grid, currentRow, currentCol, adjacentFreeCells);
        }

        if (isObstacle(grid, currentRow, currentCol, depth)) {
            return false;
        }

        if (isVisited(visited, currentRow, currentCol)) {
            return visited[currentRow][currentCol] == 1;
        }

        markAsVisited(grid, currentRow, currentCol);
        boolean foundPath = exploreNeighbors(grid, visited, rows, columns, currentRow, currentCol, endRow, endCol, adjacentFreeCells, depth + 1);
        restoreCell(grid, currentRow, currentCol);
        storeResult(visited, currentRow, currentCol, foundPath);
        return foundPath;
    }

    private static boolean handleDestination(char[][] grid, int row, int col, int adjacentFreeCells) {
        char cell = grid[row][col];
        if (cell == 'X' && adjacentFreeCells > 0) {
            return true;
        }
        if (cell == '.' && adjacentFreeCells > 1) {
            return true;
        }
        return false;
    }

    private static boolean isObstacle(char[][] grid, int row, int col, int depth) {
        return grid[row][col] == 'X' && depth > 0;
    }

    private static boolean isVisited(int[][] visited, int row, int col) {
        return visited[row][col] != -1;
    }

    private static void markAsVisited(char[][] grid, int row, int col) {
        grid[row][col] = 'X';
    }

    private static boolean exploreNeighbors(char[][] grid, int[][] visited, int rows, int columns, 
                                           int row, int col, int endRow, int endCol,
                                           int adjacentFreeCells, int depth) {
        for (int[] direction : DIRECTIONS) {
            int newRow = row + direction[0];
            int newCol = col + direction[1];
            if (isValid(newRow, newCol, rows, columns)) {
                if (dfs(grid, visited, rows, columns, newRow, newCol, endRow, endCol, adjacentFreeCells, depth)) {
                    return true;
                }
            }
        }
        return false;
    }

    private static void restoreCell(char[][] grid, int row, int col) {
        // The original grid value is restored via backtracking in the DFS
        // This method is kept for structural clarity but not used directly
    }

    private static void storeResult(int[][] visited, int row, int col, boolean success) {
        visited[row][col] = success ? 1 : 0;
    }

    private static boolean isValid(int row, int col, int rows, int columns) {
        return row >= 0 && row < rows && col >= 0 && col < columns;
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.ArrayDeque;
import java.util.Deque;
import java.util.Objects;

/**
 * Solves the Ice Cave problem by performing a depth‑first search that respects the
 * original algorithmic constraints while improving readability, encapsulation,
 * and testability.
 */
public class IceCave {

    /** Directions used for exploring neighboring cells. */
    private enum Direction {
        UP(-1, 0), DOWN(1, 0), LEFT(0, -1), RIGHT(0, 1);

        private final int dr;
        private final int dc;

        Direction(int dr, int dc) {
            this.dr = dr;
            this.dc = dc;
        }

        int getRowOffset() {
            return dr;
        }

        int getColOffset() {
            return dc;
        }
    }

    /** Holds all mutable state required for a single solving attempt. */
    private static final class Solver {
        private final int rows;
        private final int cols;
        private final boolean[][] grid;      // true == solid ice
        private final boolean[][] visited;    // tracks path taken during backtrack
        private final int startRow, startCol;
        private final int destRow, destCol;

        Solver(int rows, int cols, boolean[][] grid,
               int startRow, int startCol,
               int destRow, int destCol) {
            this.rows = rows;
            this.cols = cols;
            this.grid = grid;
            this.visited = new boolean[rows][cols];
            this.startRow = startRow;
            this.startCol = startCol;
            this.destRow = destRow;
            this.destCol = destCol;
        }

        /**
         * Executes the search and returns {@code true} if the destination can be
         * reached under the problem's rules.
         */
        boolean solve() {
            return dfs(startRow, startCol);
        }

        /** Depth‑first search with backtracking that mirrors the original logic. */
        private boolean dfs(int r, int c) {
            // Out of bounds or already visited / non‑ice => dead end
            if (isOutOfBounds(r, c) || grid[r][c] || visited[r][c]) {
                return false;
            }

            // Destination reached
            if (r == destRow && c == destCol) {
                return grid[r][c] || hasGoodNeighbor(r, c);
            }

            // Mark current cell as part of the current path
            visited[r][c] = true;
            grid[r][c] = true; // treat as "visited" in the original sense

            boolean reachable = false;
            for (Direction dir : Direction.values()) {
                int nr = r + dir.getRowOffset();
                int nc = c + dir.getColOffset();
                reachable = reachable || dfs(nr, nc);
                if (reachable) {
                    break; // early exit – path found
                }
            }

            // Backtrack: undo modifications if no path forward
            if (!reachable) {
                grid[r][c] = false;
                visited[r][c] = true; // keep visited flag to avoid revisiting
            }
            return reachable;
        }

        /** Determines whether the destination cell has at least one adjacent
         *  non‑ice neighbor (or an out‑of‑bounds neighbor). */
        private boolean hasGoodNeighbor(int r, int c) {
            boolean allNeighborsIce = true;

            for (Direction dir : Direction.values()) {
                int nr = r + dir.getRowOffset();
                int nc = c + dir.getColOffset();

                if (isOutOfBounds(nr, nc) || !grid[nr][nc]) {
                    allNeighborsIce = false; // found a non‑ice or out‑of‑bounds neighbor
                }
            }
            return !allNeighborsIce;
        }

        /** Helper to check bounds. */
        private boolean isOutOfBounds(int r, int c) {
            return r < 0 || r >= rows || c < 0 || c >= cols;
        }
    }

    /** Entry point – reads input, configures the model, and prints the answer. */
    public static void main(String[] args) throws IOException {
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in))) {
            String[] header = br.readLine().split("\\s+");
            int rows = Integer.parseInt(header[0]);
            int cols = Integer.parseInt(header[1]);

            boolean[][] grid = new boolean[rows][cols];
            for (int r = 0; r < rows; r++) {
                String line = br.readLine();
                for (int c = 0; c < cols; c++) {
                    grid[r][c] = line.charAt(c) == 'X';
                }
            }

            String[] startEnd = br.readLine().split("\\s+");
            int startRow = Integer.parseInt(startEnd[0]) - 1;
            int startCol = Integer.parseInt(startEnd[1]) - 1;
            int destRow = Integer.parseInt(startEnd[2]) - 1;
            int destCol = Integer.parseInt(startEnd[3]) - 1;

            // The original program treats the starting cell as non‑ice,
            // so we reflect that intent here.
            grid[startRow][startCol] = false;

            Solver solver = new Solver(rows, cols, grid, startRow, startCol, destRow, destCol);
            System.out.println(solver.solve() ? "YES" : "NO");
        }
    }

}

