/**
 * Core logic for solving the labyrinth reachability problem.
 * <p>
 * The class isolates all mutable state in private fields and provides a
 * single public entry point {@link #solve(Scanner, PrintWriter)}.
 * </p>
 */
class Solver {

    /** Movement vectors: right, left, down, up */
    private static final int[][] DIRS = {{0, 1}, {0, -1}, {1, 0}, {-1, 0}};

    /** Simple immutable point used for BFS queue elements */
    private static final class Point {
        final int x;
        final int y;

        Point(int x, int y) {
            this.x = x;
            this.y = y;
        }

        int getX() { return x; }
        int getY() { return y; }
    }

    /** 2‑D character grid representing the board */
    private char[][] board;

    /** Board dimensions */
    private int rows, cols;

    /** Start and target coordinates (already converted to 0‑based indices) */
    private int startX, startY;
    private int endX, endY;

    /**
     * Reads the whole input, stores it in internal fields and triggers the BFS.
     *
     * @param in  scanner that supplies the problem input
     * @param out writer used to output the answer
     */
    public void solve(Scanner in, PrintWriter out) {
        readInput(in);
        boolean reachable = bfs(startX, startY);
        out.println(reachable ? "YES" : "NO");
    }

    /** Parses the input and populates the solver's internal state. */
    private void readInput(Scanner in) {
        rows = in.nextInt();
        cols = in.nextInt();
        in.nextLine(); // consume the line break after the dimensions

        board = new char[rows][cols];
        for (int i = 0; i < rows; i++) {
            String line = in.nextLine();
            // Defensive copy; the original line length is guaranteed to be {@code cols}.
            System.arraycopy(line.toCharArray(), 0, board[i], 0, cols);
        }

        // The problem supplies coordinates as 1‑based indices.
        startX = in.nextInt() - 1;
        startY = in.nextInt() - 1;
        endX   = in.nextInt() - 1;
        endY   = in.nextInt() - 1;
    }

    /** Breadth‑first search that checks whether the destination is reachable. */
    private boolean bfs(int startX, int startY) {
        Deque<Point> queue = new ArrayDeque<>();
        queue.add(new Point(startX, startY));
        board[startX][startY] = 'X'; // mark visited

        while (!queue.isEmpty()) {
            Point cur = queue.remove();
            for (int[] dir : DIRS) {
                int nx = cur.getX() + dir[0];
                int ny = cur.getY() + dir[1];
                if (!isInside(nx, ny)) continue;

                if (board[nx][ny] == 'X') {               // already visited cell
                    if (nx == endX && ny == endY) {
                        return true;                     // destination reached
                    }
                } else {
                    board[nx][ny] = 'X';                  // mark as visited
                    queue.add(new Point(nx, ny));
                }
            }
        }
        return false; // queue exhausted without reaching the destination
    }

    /** Utility method to test whether a given coordinate lies inside the board. */
    private boolean isInside(int x, int y) {
        return x >= 0 && x < rows && y >= 0 && y < cols;
    }
}

import java.io.*;
import java.util.ArrayDeque;
import java.util.Queue;

/**
 * Entry point of the application.
 * Reads a grid and two coordinates, then determines whether the destination can be
 * reached using a breadth‑first search that respects the original movement rules.
 */
public final class Main {

    /** Directions: up, down, left, right */
    private static final int[] DX = {0, 0, -1, +1};
    private static final int[] DY = {-1, +1, 0, 0};

    private final InputReader input;
    private final PrintWriter output;

    public Main(InputReader input, PrintWriter output) {
        this.input = input;
        this.output = output;
    }

    /** Solves the problem for the current test case. */
    public void solve() {
        int rows = input.nextInt();
        int cols = input.nextInt();

        // read the grid
        char[][] grid = new char[rows][];
        for (int i = 0; i < rows; ++i) {
            grid[i] = input.next().toCharArray();
        }

        // read start and target positions (convert from 1‑based to 0‑based)
        int sr = input.nextInt() - 1;
        int sc = input.nextInt() - 1;
        int tr = input.nextInt() - 1;
        int tc = input.nextInt() - 1;

        // run the BFS
        BFSVisitor bfs = new BFSVisitor(grid);
        boolean reachable = bfs.canReach(sr, sc, tr, tc);
        output.println(reachable ? "YES" : "NO");
    }

    /** Breadth‑first search wrapper that encapsulates visited‑state handling. */
    private static final class BFSVisitor {
        private final char[][] grid;
        private final boolean[][] visited;
        private final int rows;
        private final int cols;

        BFSVisitor(char[][] grid) {
            this.grid = grid;
            this.rows = grid.length;
            this.cols = grid[0].length;
            this.visited = new boolean[rows][cols];
        }

        /**
         * Returns {@code true} if the target cell can be reached from the start cell.
         *
         * @param startRow   start row (0‑based)
         * @param startCol   start column (0‑based)
         * @param targetRow  target row (0‑based)
         * @param targetCol  target column (0‑based)
         */
        boolean canReach(int startRow, int startCol, int targetRow, int targetCol) {
            Queue<Integer> qx = new ArrayDeque<>();
            Queue<Integer> qy = new ArrayDeque<>();

            qx.add(startRow);
            qy.add(startCol);
            visited[startRow][startCol] = true;

            while (!qx.isEmpty()) {
                int x = qx.poll();
                int y = qy.poll();

                // Check neighbours
                for (int dir = 0; dir < 4; ++dir) {
                    int nx = x + DX[dir];
                    int ny = y + DY[dir];

                    // The original program treats the target as reachable only when the
                    // neighbour cell currently contains 'X'. We preserve that exact check.
                    if (isTarget(nx, ny, targetRow, targetCol)) {
                        if (grid[nx][ny] == 'X') {
                            return true;
                        }
                        continue; // not reachable yet
                    }

                    if (canEnterCell(nx, ny)) {
                        qx.add(nx);
                        qy.add(ny);
                        visited[nx][ny] = true;
                    }
                }
            }
            return false;
        }

        private boolean isTarget(int x, int y, int tr, int tc) {
            return x == tr && y == tc;
        }

        /** A cell can be entered if it is inside the grid, not a wall ('X'), and unvisited. */
        private boolean canEnterCell(int x, int y) {
            return inside(x, y) && grid[x][y] != 'X' && !visited[x][y];
        }

        private boolean inside(int x, int y) {
            return x >= 0 && x < rows && y >= 0 && y < cols;
        }
    }

    /** Simple wrapper around {@link BufferedReader} that provides fast tokenised input. */
    static final class InputReader {
        private final BufferedReader br;
        private StringTokenizer st;

        InputReader(InputStream source) {
            this.br = new BufferedReader(new InputStreamReader(source));
            // prime the tokenizer with the first line
            eat("");
        }

        /** Returns the next integer token. */
        int nextInt() {
            return Integer.parseInt(next());
        }

        /** Returns the next non‑empty string token. */
        String next() {
            while (!st.hasMoreTokens()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
            }
            return st.nextToken();
        }

        /** Reads a whole line (not used directly by the tokenizer). */
        String nextLine() {
            try {
                return br.readLine();
            } catch (IOException e) {
                throw new InputMismatchException();
            }
        }

        /** Creates a new tokenizer from the supplied string. */
        private void eat(String token) {
            if (token == null) {
                throw new InputMismatchException();
            }
            st = new StringTokenizer(token);
        }
    }
}

import java.util.ArrayDeque;
import java.util.Deque;
import java.util.Scanner;

/**
 * IceCave – Main class that reads the input, builds the maze and starts the
 * search algorithm.
 */
public class IceCave {

    /** Character that represents a walkable cell. */
    private static final char WALKABLE = '.';

    /** Directions used for neighbour exploration (up, down, left, right). */
    private static final int[] DX = { -1, 1, 0, 0 };
    private static final int[] DY = { 0, 0, -1, 1 };

    public static void main(String[] args) {
        /* Try‑with‑resources guarantees the Scanner is closed automatically. */
        try (Scanner sc = new Scanner(System.in)) {
            int rows = sc.nextInt();
            int cols = sc.nextInt();

            char[][] maze = readMaze(sc, rows, cols);

            int startRow = sc.nextInt() - 1;
            int startCol = sc.nextInt() - 1;
            int targetRow = sc.nextInt() - 1;
            int targetCol = sc.nextInt() - 1;

            Position start = new Position(startRow, startCol);
            Position target = new Position(targetRow, targetCol);

            boolean reachable = MazeSolver.canReach(maze, start, target);
            System.out.println(reachable ? "YES" : "NO");
        }
    }

    /**
     * Reads the maze description from the scanner.
     *
     * @param sc   The open scanner.
     * @param rows Number of rows in the maze.
     * @param cols Number of columns in the maze.
     * @return A two‑dimensional array representing the maze.
     */
    private static char[][] readMaze(Scanner sc, int rows, int cols) {
        char[][] maze = new char[rows][cols];
        for (int r = 0; r < rows; r++) {
            String line = sc.next();
            maze[r] = line.toCharArray();
        }
        return maze;
    }

    /**
     * Utility class that encapsulates the BFS algorithm used to test
     * reachability between two positions.
     */
    private static final class MazeSolver {

        /**
         * Determines whether {@code target} can be reached from {@code start}
         * following only walkable ('.') cells.
         *
         * @param maze   The maze representation.
         * @param start  Starting cell (must be inside the maze and walkable).
         * @param target Destination cell.
         * @return {@code true} if the destination is reachable, otherwise {@code false}.
         */
        static boolean canReach(char[][] maze, Position start, Position target) {
            if (!isInside(start, maze) || !isWalkable(start, maze)) {
                return false;
            }

            Deque<Position> queue = new ArrayDeque<>();
            boolean[][] visited = new boolean[maze.length][maze[0].length];

            queue.add(start);
            visited[start.row][start.col] = true;

            while (!queue.isEmpty()) {
                Position cur = queue.pollFirst();

                if (cur.equals(target)) {
                    return true;
                }

                for (int dir = 0; dir < DX.length; dir++) {
                    Position neighbor = new Position(
                            cur.row + DX[dir],
                            cur.col + DY[dir]);

                    if (isWalkableAndUnvisited(maze, visited, neighbor)) {
                        visited[neighbor.row][neighbor.col] = true;
                        queue.add(neighbor);
                    }
                }
            }
            return false;
        }

        /** Checks that a position lies inside the bounds of the maze. */
        private static boolean isInside(Position p, char[][] maze) {
            return p.row >= 0 && p.row < maze.length &&
                   p.col >= 0 && p.col < maze[0].length;
        }

        /** Determines whether a cell is walkable ('.') . */
        private static boolean isWalkable(char[][] maze, Position p) {
            return isInside(p, maze) && maze[p.row][p.col] == WALKABLE;
        }

        /** Returns {@code true} if the neighbour is inside, walkable and not yet visited. */
        private static boolean isWalkableAndUnvisited(char[][] maze,
                                                      boolean[][] visited,
                                                      Position p) {
            return isInside(p, maze) &&
                   isWalkable(maze, p) &&
                   !visited[p.row][p.col];
        }
    }

    /**
     * Simple immutable position holder used throughout the program.
     * Implements {@code equals} and {@code hashCode} to allow proper queue
     * handling and set‑like operations.
     */
    private static final class Position {
        final int row;
        final int col;

        Position(int row, int col) {
            this.row = row;
            this.col = col;
        }

        /** Equality based on both coordinates. */
        @Override
        public boolean equals(Object o) {
            if (this == o) return true;
            if (!(o instanceof Position)) return false;
            Position that = (Position) o;
            return row == that.row && col == that.col;
        }

        /** A hash code that respects the contract with {@code equals}. */
        @Override
        public int hashCode() {
            return 31 * row + col;
        }
    }
}

import java.io.*;
import java.util.ArrayDeque;
import java.util.Deque;
import java.util.HashSet;
import java.util.Set;

/**
 * Entry point of the program.
 */
public class IceCave {

    /** -------------------------------------------------------------------------
     *  Input handling
     *  -------------------------------------------------------------------------
     */
    private static final class InputReader implements AutoCloseable {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        InputReader(BufferedReader reader) {
            this.reader = reader;
        }

        /** Advance the tokenizer, reading a new line when the current one is exhausted. */
        private void ensureHasTokens() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) {
                        return;               // EOF
                    }
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new UncheckedIOException(e);
                }
            }
        }

        String nextString() {
            if (!ensureHasTokens()) {
                throw new NoSuchElementException();
            }
            return tokenizer.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(nextString());
        }

        long nextLong() {
            return Long.parseLong(nextString());
        }

        double nextDouble() {
            return Double.parseDouble(nextString());
        }

        String nextLine() {
            return nextString();
        }

        @Override
        public void close() {
            try {
                reader.close();
            } catch (IOException e) {
                throw new UncheckedIOException(e);
            }
        }
    }

    /** -------------------------------------------------------------------------
     *  Grid representation
     *  -------------------------------------------------------------------------
     */
    private static final class Grid {
        private final char[][] cells;
        private final int rows;
        private final int cols;

        Grid(int rows, int cols) {
            this.rows = rows;
            this.cols = cols;
            this.cells = new char[rows][cols];
        }

        char get(int r, int c) {
            return cells[r][c];
        }

        void set(int r, int c, char value) {
            cells[r][c] = value;
        }
    }

    /** -------------------------------------------------------------------------
     *  Solver (path‑finding) logic
     *  -------------------------------------------------------------------------
     */
    private static final class Solver {

        private final Grid grid;
        private final int targetRow;
        private final int targetCol;
        private final Set<Coords> visited = new HashSet<>();

        Solver(Grid grid, int targetRow, int targetCol) {
            this.grid = grid;
            this.targetRow = targetRow;
            this.targetCol = targetCol;
        }

        /** Public API ---------------------------------------------------------- */
        boolean canReach(int startRow, int startCol) {
            Deque<Coords> stack = new ArrayDeque<>();
            stack.push(new Coords(startRow, startCol));

            while (!stack.isEmpty()) {
                Coords cur = stack.pop();

                if (isTarget(cur.row, cur.col)) {
                    return true;
                }

                if (visited.contains(cur)) {
                    continue;
                }
                visited.add(cur);

                for (int d = 0; d < 4; d++) {
                    int nr = cur.row + dir[0][d];
                    int nc = cur.col + dir[1][d];

                    if (!inBounds(nr, nc)) {
                        continue;
                    }

                    char next = grid.get(nr, nc);
                    if (next != '.') {
                        continue;
                    }

                    // Destination can be entered only if it is marked as 'X'
                    if (nr == targetRow && nc == targetCol && next == 'X') {
                        return true;
                    }

                    stack.push(new Coords(nr, nc));
                }
            }
            return false;
        }

        /** --------------------------------------------------------------------- */
        private boolean isTarget(int r, int c) {
            return r == targetRow && c == targetCol && grid.get(r, c) == 'X';
        }

        private boolean inBounds(int r, int c) {
            return r >= 0 && r < grid.rows && c >= 0 && c < grid.cols;
        }
    }

    /** -------------------------------------------------------------------------
     *  Direction vectors (static final constants)
     *  -------------------------------------------------------------------------
     */
    private static final int[][] dir = {
            {-1, 0},   // up
            {0, 1},    // right
            {1, 0},    // down
            {0, -1}    // left
    };

    /** -------------------------------------------------------------------------
     *  Main program
     *  -------------------------------------------------------------------------
     */
    public static void main(String[] args) throws IOException {
        // Using try‑with‑resources guarantees that the underlying stream is closed.
        try (InputReader sc = new InputReader(new BufferedReader(
                new InputStreamReader(System.in)))) {

            int n = sc.nextInt();
            int m = sc.nextInt();

            Grid grid = new Grid(n, m);
            for (int i = 0; i < n; i++) {
                String line = sc.nextLine();
                // Copy the characters into the grid[row][col] matrix
                for (int j = 0; j < m; j++) {
                    grid.set(i, j, line.charAt(j));
                }
            }

            // Subtract 1 to obtain zero‑based indices
            int startRow = sc.nextInt() - 1;
            int startCol = sc.nextInt() - 1;
            int endRow = sc.nextInt() - 1;
            int endCol = sc.nextInt() - 1;

            Solver solver = new Solver(grid, endRow, endCol);
            System.out.println(solver.canReach(startRow, startCol) ? "YES" : "NO");
        }
    }
}

import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.List;
import java.util.Queue;

/**
 * Reads a grid, a source and a destination cell and determines whether the
 * destination can be reached from the source under the following rules:
 * <ul>
 *   <li>Movement is allowed only to orthogonal neighbours (up, down, left, right).</li>
 *   <li>A cell that contains {@code 'X'} is considered an obstacle and cannot be entered.</li>
 *   <li>The destination cell is considered reachable only if it originally contains {@code 'X'}.</li>
 * </ul>
 * The program prints "YES" if the destination is reachable, otherwise "NO".
 */
public class IceCaveSolver {

    /** Directions for orthogonal moves. */
    private static final int[][] DIRECTIONS = {
            {-1, 0}, // up
            {1, 0},  // down
            {0, -1}, // left
            {0, 1}   // right
    };

    private static int rows;
    private static int columns;
    private static char[][] grid;
    private static boolean[][] visited;

    /**
     * Entry point – parses input and starts the search.
     */
    public static void main(String[] args) {
        try (var scanner = new java.util.Scanner(System.in)) {
            rows = scanner.nextInt();
            columns = scanner.nextInt();
            grid = new char[rows][];
            for (int r = 0; r < rows; r++) {
                grid[r] = scanner.next().toCharArray();
            }

            int startRow = scanner.nextInt() - 1;
            int startCol = scanner.nextInt() - 1;
            int endRow   = scanner.nextInt() - 1;
            int endCol   = scanner.nextInt() - 1;

            if (canReach(startRow, startCol, endRow, endCol)) {
                System.out.println("YES");
            } else {
                System.out.println("NO");
            }
        }
    }

    /**
     * Performs a breadth‑first search from {@code startRow,startCol} to the
     * {@code endRow,endCol} cell.
     *
     * @return {@code true} if the destination is reachable, {@code false} otherwise.
     */
    private static boolean canReach(int startRow, int startCol, int endRow, int endCol) {
        if (!isInside(startRow, startCol) || !isInside(endRow, endCol)) {
            return false;
        }

        visited = new boolean[rows][columns];
        Queue<Position> queue = new ArrayDeque<>();
        queue.add(new Position(startRow, startCol));
        visited[startRow][startCol] = true;

        while (!queue.isEmpty()) {
            Position current = queue.poll();
            if (current.row == endRow && current.col == endCol && grid[endRow][endCol] == 'X') {
                return true;               // Destination reached and originally 'X'
            }

            for (int[] dir : DIRECTIONS) {
                int nextRow = current.row + dir[0];
                int nextCol = current.col + dir[1];

                if (isValidMove(nextRow, nextCol)) {
                    visited[nextRow][nextCol] = true;
                    queue.add(new Position(nextRow, nextCol));
                }
            }
        }
        return false;
    }

    /** Checks whether the given coordinates are inside the board and not an obstacle. */
    private static boolean isValidMove(int r, int c) {
        return isInside(r, c) && !visited[r][c] && grid[r][c] != 'X';
    }

    /** Returns {@code true} if the coordinates are within the board limits. */
    private static boolean isInside(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < columns;
    }

    /** Simple immutable holder for a board position. */
    private static final class Position {
        final int row;
        final int column;

        Position(int row, int column) {
            this.row = row;
            this.column = column;
        }
    }
}

/*  IceCaveSolver – Refactored for readability, maintainability and extensibility  */
import java.io.*;
import java.util.StringTokenizer;

/**
 * Solves the “Ice Cave” problem.
 *
 * The original implementation mixed input handling, algorithm logic,
 * and state management inside a single {@code solve()} method.
 * The refactor separates concerns into small, well‑named methods,
 * uses descriptive names, constant definitions and early returns
 * to make future modifications straightforward.
 */
public class IceCaveSolver {

    /* --------------------------------------------------------------------- */
    /*  Constants & Direction Vectors                                         */
    /* --------------------------------------------------------------------- */
    private static final int[][] DIRS = {
            { -1, 0 },   // up
            { 0, -1 },   // left
            { 0, 1 },    // right
            { 1, 0 }     // down
    };
    private static final char EMPTY = '.';
    private static final char CRACKED = 'X';

    /* --------------------------------------------------------------------- */
    /*  Instance fields                                                       */
    /* --------------------------------------------------------------------- */
    private BufferedReader reader;
    private PrintWriter out;
    private StringTokenizer tokenizer;

    private int rows, cols;
    private char[][] grid;
    private boolean[][] visited;

    private int startR, startC;
    private int targetR, targetC;

    /* --------------------------------------------------------------------- */
    /*  Entry point                                                            */
    /* --------------------------------------------------------------------- */
    public static void main(String[] args) throws Exception {
        new IceCaveSolver().run();
    }

    /* --------------------------------------------------------------------- */
    /*  Public API                                                             */
    /* --------------------------------------------------------------------- */
    /** Runs the whole program: reads input, solves and prints result. */
    private void run() throws IOException {
        initIO();
        solve();
        closeIO();
    }

    /* --------------------------------------------------------------------- */
    /*  Core algorithm                                                         */
    /* --------------------------------------------------------------------- */
    private void solve() {
        readInput();

        // Trivial case – the hero already stands on the destination.
        if (startEqualsTarget()) {
            out.println(hasFreeNeighbour(targetR, targetC) ? "YES" : "NO");
            return;
        }

        // Explore all reachable cells from the start.
        explore(startR, startC);

        // If the target is unreachable → NO.
        if (!visited[targetR][targetC]) {
            out.println("NO");
            return;
        }

        // If the target cell itself is cracked, we can step on it only once.
        if (grid[targetR][targetC] == CRACKED) {
            out.println("YES");
            return;
        }

        // Otherwise we need at least two distinct ways to enter the target.
        int entryCount = countValidAdjacents(targetR, targetC);
        out.println(entryCount >= 2 ? "YES" : "NO");
    }

    /* --------------------------------------------------------------------- */
    /*  Helper methods                                                          */
    /* --------------------------------------------------------------------- */

    /** Reads all input data and fills the internal state fields. */
    private void readInput() {
        rows = nextInt();
        cols = nextInt();

        grid = new char[rows][];
        for (int r = 0; r < rows; r++) {
            grid[r] = nextToken().toCharArray();
        }

        startR = nextInt() - 1;
        startC = nextInt() - 1;
        targetR = nextInt() - 1;
        targetC = nextInt() - 1;
    }

    /** Returns true when the start cell coincides with the target cell. */
    private boolean startEqualsTarget() {
        return startR == targetR && startC == targetC;
    }

    /** Checks whether some neighbour of the given cell is an empty ('.') cell. */
    private boolean hasFreeNeighbour(int r, int c) {
        for (int[] d : DIRS) {
            int nr = r + d[0];
            int nc = c + d[1];
            if (inBounds(nr, nc) && grid[nr][nc] == EMPTY) {
                return true;
            }
        }
        return false;
    }

    /** Performs a depth‑first search from (r,c). */
    private void explore(int r, int c) {
        visited[r][c] = true;
        for (int[] d : DIRS) {
            int nr = r + d[0];
            int nc = c + d[1];
            if (!inBounds(nr, nc)) {
                continue;
            }
            // We may move onto the target cell even if it is not '.'.
            if (grid[nr][nc] == EMPTY || (nr == targetR && nc == targetC)) {
                if (!visited[nr][nc]) {
                    explore(nr, nc);
                }
            }
        }
    }

    /** Returns the number of neighbours that are either empty or the start cell. */
    private int countValidAdjacents(int r, int c) {
        int count = 0;
        for (int[] d : DIRS) {
            int nr = r + d[0];
            int nc = c + d[1];
            if (!inBounds(nr, nc)) {
                continue;
            }
            if (grid[nr][nc] == EMPTY || (nr == startR && nc == startC)) {
                count++;
            }
        }
        return count;
    }

    /* --------------------------------------------------------------------- */
    /*  Utility methods                                                         */
    /* --------------------------------------------------------------------- */

    /** Simple bounds check. */
    private boolean inBounds(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    /** FastScanner implementation that works with {@link BufferedReader}. */
    private static class FastScanner {
        private final BufferedReader in;
        private StringTokenizer st;

        FastScanner(BufferedReader in) {
            this.in = in;
        }

        /** Returns the next token from {@link #in}. */
        private String nextToken() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    st = new StringTokenizer(in.readLine());
                } catch (IOException e) {
                    throw new UncheckedIOException(e);
                }
            }
            return st.nextToken();
        }

        /** Reads an {@code int}. */
        int nextInt() {
            return Integer.parseInt(nextToken());
        }
    }

    /** Initializes {@link #in} and {@link #out}. */
    private static void initIO() {
        in = new FastScanner(new BufferedReader(new InputStreamReader(System.in)));
        out = new PrintWriter(System.out);
    }

    /** Closes the output stream. */
    private static void closeIO() {
        out.close();
    }

    /* --------------------------------------------------------------------- */
    /*  Static fields for the scanner/print writer (used by inner class)    */
    /* --------------------------------------------------------------------- */
    private static FastScanner in;
    private static PrintWriter out;
}

import java.io.*;
import java.util.*;

/**
 * Path existence checker using depth‑first search.
 *
 * <p>Input format:
 * <pre>
 * n m                // number of rows and columns
 * row_1              // '.' denotes a traversable cell, any other char denotes a wall
 * …
 * row_n
 * r1                 // start row   (1‑based)
 * c1                 // start column (1‑based)
 * r2                 // target row   (1‑based)
 * c2                 // target column (1‑based)
 * </pre>
 *
 * <p>The program prints {@code YES} if a path exists from the start cell to the target
 * cell moving only through '.' cells (up, down, left or right), otherwise {@code NO}.
 */
public final class PathFinder {

    /** Four movement directions: up, down, left, right */
    private static final int[][] DIRECTIONS = {
            {-1, 0}, // up
            {1, 0},  // down
            {0, -1}, // left
            {0, 1}   // right
    };

    /** Characters used in the input description */
    private static final char WALL = '#';
    private static final char EMPTY = '.';

    /** Simple DTO that holds all parsed input data */
    private static final class Input {
        final char[][] grid;               // original grid (read‑only)
        final int startRow, startCol;      // start coordinates (0‑based)
        final int targetRow, targetCol;    // target coordinates (0‑based)
        final int rows, cols;              // grid dimensions

        Input(char[][] grid, int startRow, int startCol,
              int targetRow, int targetCol, int rows, int cols) {
            this.grid = grid;
            this.startRow = startRow;
            this.startCol = startCol;
            this.targetRow = targetRow;
            this.targetCol = targetCol;
            this.rows = rows;
            this.cols = cols;
        }
    }

    /**
     * Reads the complete input from {@code reader} and returns an {@link Input} instance.
     *
     * @param reader a {@link BufferedReader} supplying the input
     * @throws IOException if an I/O error occurs
     */
    private static Input readInput(BufferedReader reader) throws IOException {
        // First line: dimensions
        String[] dimTokens = reader.readLine().trim().split("\\s+");
        int rows = Integer.parseInt(dimTokens[0]);
        int cols = Integer.parseInt(dimTokens[1]);

        // Next 'rows' lines: the grid rows
        char[][] grid = new char[rows][];
        for (int i = 0; i < rows; i++) {
            grid[i] = reader.readLine().trim().toCharArray();
        }

        // Coordinates are given on separate lines (1‑based in the original spec)
        int sr = Integer.parseInt(reader.readLine().trim()) - 1;
        int sc = Integer.parseInt(reader.readLine().trim()) - 1;
        int tr = Integer.parseInt(reader.readLine().trim()) - 1;
        int tc = Integer.parseInt(reader.readLine().trim()) - 1;

        return new Input(grid, sr, sc, tr, tc, rows, cols);
    }

    /**
     * Depth‑first search that determines whether a path exists from
     * {@code startRow, startCol} to {@code targetRow, targetCol}.
     *
     * @param grid     mutable character grid (EMPTY == '.')
     * @param r        current row
     * @param c        current column
     * @param targetR  target row
     * @param targetC  target column
     * @param rows     number of rows in the grid
     * @param cols     number of columns in the grid
     * @return {@code true} if a path exists, {@code false} otherwise
     */
    private static boolean hasPath(char[][] grid, int r, int c,
                                   int targetR, int targetC,
                                   int rows, int cols) {
        // Boundary check or wall => dead end
        if (r < 0 || r >= rows || c < 0 || c >= cols || grid[r][c] != EMPTY) {
            return false;
        }

        // Destination reached
        if (r == targetR && c == targetC) {
            return true;
        }

        // Mark current cell as visited
        grid[r][c] = WALL;

        // Explore all four neighbours recursively
        for (int[] dir : DIRECTIONS) {
            int nr = r + dir[0];
            int nc = c + dir[1];
            if (hasPath(grid, nr, nc, targetR, targetC, rows, cols)) {
                // Restore the cell before returning to keep the original grid intact
                grid[r][c] = EMPTY;
                return true;
            }
        }

        // Backtrack: restore the cell and indicate failure
        grid[r][c] = EMPTY;
        return false;
    }

    /**
     * Entry point of the program.
     *
     * @param args command line arguments (unused)
     */
    public static void main(String[] args) throws IOException {
        // Use try‑with‑resources to guarantee the reader is closed
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in))) {
            Input input = readInput(br);

            // Work on a mutable copy of the grid for the DFS
            char[][] mutableGrid = input.grid;

            boolean reachable = hasPath(mutableGrid,
                    input.startRow, input.startCol,
                    input.targetRow, input.targetCol,
                    input.rows, input.cols);

            System.out.println(reachable ? "YES" : "NO");
        }
    }
}

import java.util.ArrayDeque;
import java.util.Collections;
import java.util.List;
import java.util.Scanner;

/**
 * Reads a grid, a start cell and a target cell and determines whether the target can be reached
 * by moving only through empty cells ('.'). Movement is allowed in the four orthogonal directions.
 * The search explores cells in order of increasing Manhattan distance to the target.
 */
public class Main {

    /** Character that denotes an empty (unvisited) cell. */
    private static final char EMPTY = '.';
    /** Character used to mark a cell that has already been visited. */
    private static final char VISITED = 'X';

    /** Number of rows and columns of the board. */
    private static int rows;
    /** Number of columns of the board. */
    private static int cols;
    /** Target cell coordinates (0‑based). */
    private static int targetRow;
    /** Target cell coordinates (0‑based). */
    private static int targetCol;

    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            rows = scanner.nextInt();
            cols = scanner.nextInt();

            char[][] board = new char[rows][];
            for (int r = 0; r < rows; r++) {
                board[r] = scanner.next().toCharArray();
            }

            int startRow = scanner.nextInt() - 1;
            int startCol = scanner.nextInt() - 1;
            targetRow = scanner.nextInt() - 1;
            targetCol = scanner.nextInt() - 1;

            boolean reachable = canReach(board, startRow, startCol);
            System.out.println(reachable ? "YES" : "NO");
        }
    }

    /**
     * Determines whether the target cell can be reached from the start cell.
     *
     * @param board   the grid where {@code '.'} denotes an unvisited empty cell
     * @param sr      start row (0‑based)
     * @param sc      start column (0‑based)
     * @return {@code true} if the target can be reached, {@code false} otherwise
     */
    private static boolean canReach(char[][] board, int sr, int sc) {
        ArrayDeque<Position> stack = new ArrayDeque<>();
        stack.addLast(new Position(sr, sc));

        while (!stack.isEmpty()) {
            Position cur = stack.pollLast();
            List<Position> neighbours = getNeighbourPositions(cur.r, cur.c);
            Collections.sort(neighbours);
            for (Position next : neighbours) {
                // Skip cells that have already been visited
                if (board[next.r][next.c] == VISITED) {
                    continue;
                }
                // Success – we arrived at the target
                if (next.r == targetRow && next.c == targetCol) {
                    return true;
                }
                // Mark as visited and continue the search
                board[next.r][next.c] = VISITED;
                stack.addLast(next);
            }
        }
        return false;
    }

    /** Returns the four orthogonal neighbours that lie inside the board. */
    private static List<Position> getNeighbourPositions(int r, int c) {
        List<Position> result = new ArrayList<>(4);
        if (isInside(r - 1, c)) {
            result.add(new Position(r - 1, c));
        }
        if (isInside(r + 1, c)) {
            result.add(new Position(r + 1, c));
        }
        if (isInside(r, c - 1)) {
            result.add(new Position(r, c - 1));
        }
        if (isInside(r, c + 1)) {
            result.add(new Position(r, c + 1));
        }
        return result;
    }

    /** Checks whether a cell (r, c) is inside the board boundaries. */
    private static boolean isInside(int r, int c) {
        return r >= 0 && c >= 0 && r < rows && c < cols;
    }

    /**
     * Represents a cell index. Instances are compared by their Manhattan distance
     * to the currently known target cell.
     */
    private static final class Position implements Comparable<Position> {
        final int r;
        final int c;

        Position(int r, int c) {
            this.r = r;
            this.c = c;
        }

        /** Manhattan distance to the global target cell. */
        private int distanceToTarget() {
            return Math.abs(targetRow - r) + Math.abs(targetCol - c);
        }

        @Override
        public int compareTo(Position other) {
            return distanceToTarget() - other.distanceToTarget();
        }

        @Override
        public String toString() {
            return String.format("{r:%d,c:%d}", r, c);
        }
    }
}

import java.io.*;
import java.util.*;

public class Main {

    /** Directions: right, down, left, up */
    private static final int[][] DIRECTIONS = {
            {0, 1}, {1, 0}, {0, -1}, {-1, 0}
    };

    private final FastScanner scanner;
    private final PrintWriter writer;

    public Main(FastScanner scanner, PrintWriter writer) {
        this.scanner = scanner;
        this.writer = writer;
    }

    /** Entry point of the algorithm */
    public void solve() {
        int rows = scanner.nextInt();
        int cols = scanner.nextInt();

        char[][] grid = new char[rows][cols];
        for (int i = 0; i < rows; i++) {
            grid[i] = scanner.next().toCharArray();
        }

        int startR = scanner.nextInt() - 1;
        int startC = scanner.nextInt() - 1;
        int endR   = scanner.nextInt() - 1;
        int endC   = scanner.nextInt() - 1;

        boolean[][] visited = bfs(grid, startR, startC, endR, endC);

        boolean reachable = visited[endR][endC];
        int goodAdjacents = countGoodAdjacents(grid, endR, endC);
        boolean startEqualsEnd = (startR == endR && startC == endC);

        boolean result;
        if (startEqualsEnd) {
            result = goodAdjacents > 0;
        } else {
            result = reachable && (grid[endR][endC] == 'X' || goodAdjacents >= 2);
        }

        writer.println(result ? "YES" : "NO");
    }

    /** Breadth‑first search that returns a visited matrix */
    private boolean[][] bfs(char[][] grid, int sr, int sc, int er, int ec) {
        int rows = grid.length;
        int cols = grid[0].length;

        boolean[][] visited = new boolean[rows][cols];
        Queue<int[]> q = new ArrayDeque<>();

        q.add(new int[]{sr, sc});
        visited[sr][sc] = true;
        grid[sr][sc] = '.';               // treat start as walkable

        while (!q.isEmpty()) {
            int[] cur = q.poll();
            int r = cur[0];
            int c = cur[1];

            if (r == er && c == ec) {
                break;
            }

            for (int[] dir : DIRECTIONS) {
                int nr = r + dir[0];
                int nc = c + dir[1];
                if (isInBounds(rows, cols, nr, nc) &&
                        (grid[nr][nc] == '.' || (nr == er && nc == ec)) &&
                        !visited[nr][nc]) {
                    visited[nr][nc] = true;
                    q.add(new int[]{nr, nc});
                }
            }
        }
        return visited;
    }

    /** Helper – checks if coordinates are inside the grid */
    private boolean isInBounds(int rows, int cols, int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    /** Counts adjacent '.' cells around (r,c) */
    private int countGoodAdjacents(char[][] grid, int r, int c) {
        int count = 0;
        for (int[] dir : DIRECTIONS) {
            int nr = r + dir[0];
            int nc = c + dir[1];
            if (isInBounds(grid.length, grid[0].length, nr, nc) &&
                    grid[nr][nc] == '.') {
                count++;
            }
        }
        return count;
    }

    /** ------------------------------------------------------------
     *  FastScanner – simple wrapper around BufferedReader/StringTokenizer
     *  ------------------------------------------------------------ */
    static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner(BufferedReader br) {
            this.br = br;
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    throw new UncheckedIOException(e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }
    }

    /** ------------------------------------------------------------
     *  Program entry point
     *  ------------------------------------------------------------ */
    public static void main(String[] args) throws IOException {
        try (BufferedReader reader = new BufferedReader(
                new InputStreamReader(System.in))) {
            FastScanner scanner = new FastScanner(reader);
            PrintWriter writer = new PrintWriter(System.out);
            new Main(scanner, writer).solve();
            writer.close();
        }
    }
}

import java.io.BufferedReader;
import java.io.BufferedWriter;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.StringTokenizer;

/**
 * Utility that maintains the number of contiguous '.' characters
 * (called “groups”) while applying a series of point‑updates.
 *
 * <p>
 *   The original program performed the same task but was tangled with
 *   unused code, obscure method names and a manual state‑machine that
 *   tried to count groups.  The refactored version isolates the logic in
 *   clear, well‑named methods and removes all dead code.
 * </p>
 */
public class Main {

    /** Input buffer */
    private static BufferedReader br;
    /** Output buffer */
    private static PrintWriter pw;

    /** The character array that represents the current state. */
    private static char[] line;

    /** Length of the array (fixed for the whole execution). */
    private static final int LENGTH;

    /** Current number of contiguous '.' groups. */
    private static int groupCount;

    static {
        try {
            br = new BufferedReader(new InputStreamReader(System.in));
            pw = new PrintWriter(System.out);
        } catch (IOException e) {
            throw new RuntimeException(e);
        }
    }

    /** Entry point. */
    public static void main(String[] args) throws IOException {
        // -----------------------------------------------------------------
        // 1️⃣  Read the initial data
        // -----------------------------------------------------------------
        StringTokenizer tok = new StringTokenizer(br.readLine());
        int n = Integer.parseInt(tok.nextToken());
        int m = Integer.parseInt(tok.nextToken());

        LENGTH = n;
        line = readPattern(n);

        // initialise the group counter
        groupCount = countGroups(line);

        // -----------------------------------------------------------------
        // 2️⃣  Process each update
        // -----------------------------------------------------------------
        StringBuilder out = new StringBuilder();
        for (int i = 0; i < m; i++) {
            String[] parts = br.readLine().split(" ");
            int index = Integer.parseInt(parts[0]) - 1;          // 1‑based → 0‑based
            char newChar = parts[1].charAt(0);

            // No change → just output the current count
            if (line[index] == newChar) {
                out.append(groupCount).append('\n');
                continue;
            }

            // Apply the update and adjust the group counter
            adjustGroupCount(index, newChar);
            line[index] = newChar;          // store the new character
            out.append(groupCount).append('\n');
        }

        pw.print(out.toString());
        pw.flush();
    }

    /**
     * Reads the initial pattern consisting of '.' and other characters.
     *
     * @param size number of characters to read
     * @return char array containing the pattern
     */
    private static char[] readPattern(int size) throws IOException {
        String s = br.readLine();
        if (s == null || s.length() < size) {
            throw new IllegalStateException("Pattern line too short");
        }
        return s.substring(0, size).toCharArray();
    }

    /**
     * Counts how many contiguous '.' groups exist in the given array.
     *
     * @param arr the character array
     * @return the number of groups
     */
    private static int countGroups(char[] arr) {
        int cnt = 0;
        for (int i = 0; i < arr.length; i++) {
            if (arr[i] == '.' && (i == 0 || arr[i - 1] != '.')) {
                cnt++;
            }
        }
        return cnt;
    }

    /**
     * Adjusts {@link #groupCount} when a single position is changed.
     *
     * <p>Only the character at {@code pos} is modified – the rest of the
     * array stays unchanged.</p>
     *
     * @param pos      index that is being updated (0‑based)
     * @param newChar  the character that will replace the current one
     */
    private static void adjustGroupCount(int pos, char newChar) {
        char oldChar = line[pos];
        boolean oldWasDot = oldChar == '.';
        boolean newIsDot = newChar == '.';

        // No effect on the group count if the dot‑property does not change
        if (oldWasDot == newIsDot) {
            return;
        }

        // Determine the situation on the left and right side of the position
        boolean leftIsDot = pos > 0 && line[pos - 1] == '.';
        boolean rightIsDot = pos < line.length - 1 && line[pos + 1] == '.';

        if (oldWasDot && !newIsDot) {                 // removing a dot
            if (!leftIsDot && !rightIsDot) {
                // The removed dot was an isolated group
                groupCount--;
            }
            // otherwise the removal does not create a new group → no change
        } else if (!oldWasDot && newIsDot) {          // adding a dot
            if (leftIsDot && rightIsDot) {
                // We fill a gap between two groups → they merge
                groupCount--;
            } else if (!leftIsDot && !rightIsDot) {
                // New isolated group appears
                groupCount++;
            }
            // otherwise we simply extend an existing group → no change
        }
    }
}

/**
 * Refactored solution for the “adjacent dots” problem.
 *
 * <p>
 *   - Reads {@code n} (length of the string) and {@code m} (number of operations).
 *   - Stores the current characters in a mutable {@code char[]}.
 *   - Maintains the number of occurrences of the substring “..”.
 *   - Updates this count in O(1) when a single position is changed.
 *   - Prints the current count after each operation.
 * </p>
 */
public class Main {

    /** Fast scanner that supports the original tokenisation behaviour. */
    private static final class FastScanner {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        FastScanner(InputStream stream) {
            this.reader = new BufferedReader(new InputStreamReader(stream), 32768);
        }

        /** @return next token from the input */
        String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        /** @return next integer token */
        int nextInt() {
            return Integer.parseInt(next());
        }

        /** @return next character token (single character) */
        char nextChar() {
            return next().charAt(0);
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(System.out);

        int n = fs.nextInt();          // length of the string
        int m = fs.nextInt();          // number of operations
        char[] data = fs.next().toCharArray();   // the initial string

        long dotPairCount = countDotPairs(data);

        // Process each operation
        for (int i = 0; i < m; i++) {
            int idx = fs.nextInt() - 1;          // convert to 0‑based index
            char newChar = fs.nextChar();         // character to write

            update(data, idx, newChar, dotPairCount, out);
        }

        out.close();
    }

    /**
     * Counts how many times “..” appears consecutively in the array.
     *
     * @param arr character array to scan
     * @return number of adjacent dot pairs
     */
    private static long countDotPairs(char[] arr) {
        long cnt = 0;
        for (int i = 0; i < arr.length - 1; i++) {
            if (arr[i] == '.' && arr[i + 1] == '.') {
                cnt++;
            }
        }
        return cnt;
    }

    /**
     * Updates the character at {@code idx} and adjusts {@code pairCount}
     * accordingly. The new count is printed after the operation.
     *
     * @param arr          mutable character array representing the current state
     * @param idx          position to modify (0‑based)
     * @param newChar      character to write
     * @param pairCount    current number of “..” occurrences (passed by reference via modification)
     * @param out          output stream
     */
    private static void update(char[] arr, int idx, char newChar,
                               long[] pairCount, PrintWriter out) {
        char oldChar = arr[idx];

        // No change – nothing to do, just output the current count
        if (oldChar == newChar) {
            out.println(pairCount[0]);
            return;
        }

        // ---- Remove contributions of the old character ----
        if (oldChar == '.') {
            if (idx > 0 && arr[idx - 1] == '.') {
                pairCount[0]--;
            }
            if (idx < arr.length - 1 && arr[idx + 1] == '.') {
                pairCount[0]--;
            }
        }

        // Apply the change
        arr[idx] = newChar;

        // ---- Add contributions of the new character ----
        if (newChar == '.') {
            if (idx > 0 && arr[idx - 1] == '.') {
                pairCount[0]++;
            }
            if (idx < arr.length - 1 && arr[idx + 1] == '.') {
                pairCount[0]++;
            }
        }

        out.println(pairCount[0]);
    }
}

import java.io.*;
import java.util.*;

public class Main {

    /** Counts occurrences of ".." in the array (each pair is counted once). */
    private static int countAdjacencyPairs(char[] arr) {
        int cnt = 0;
        for (int i = 1; i < arr.length; i++) {
            if (arr[i] == '.' && arr[i - 1] == '.') {
                cnt++;
            }
        }
        return cnt;
    }

    /**
     * Returns how many adjacent '.' pairs would be lost if the character at {@code idx}
     * were removed (i.e. replaced by a non‑dot).
     */
    private static int removalImpact(char[] arr, int idx) {
        int impact = 0;
        if (idx > 0 && arr[idx - 1] == '.') {
            impact++;
        }
        if (idx < arr.length - 1 && arr[idx + 1] == '.') {
            impact++;
        }
        return impact;
    }

    /**
     * Returns how many new adjacent '.' pairs would be created if a '.' were placed
     * at {@code idx}.
     */
    private static int additionImpact(char[] arr, int idx) {
        int impact = 0;
        if (idx > 0 && arr[idx - 1] == '.') {
            impact++;
        }
        if (idx < arr.length - 1 && arr[idx + 1] == '.') {
            impact++;
        }
        return impact;
    }

    public Main() throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        BufferedWriter bw = new BufferedWriter(new OutputStreamWriter(System.out));

        /* ----- input ----- */
        String[] header = br.readLine().split(" ");
        int n = Integer.parseInt(header[0]);   // length of the character array
        int m = Integer.parseInt(header[1]);   // number of queries

        char[] data = br.readLine().toCharArray(); // the initial character sequence

        int adjacentCount = countAdjacencyPairs(data);

        /* ----- process queries ----- */
        for (int q = 0; q < m; q++) {
            String[] parts = br.readLine().split(" ");
            int pos = Integer.parseInt(parts[0]) - 1;          // 0‑based index
            char newChar = parts[1].charAt(0);                // character to write

            // No actual change – just output the current count
            if (data[pos] == newChar) {
                bw.write(adjacentCount + "\n");
                continue;
            }

            /* ----- removal of the old character (if it was a dot) ----- */
            if (data[pos] == '.') {
                adjacentCount -= removalImpact(data, pos);
            }

            /* ----- apply the update ----- */
            data[pos] = newChar;

            /* ----- addition of the new character (if it is a dot) ----- */
            if (newChar == '.') {
                adjacentCount += additionImpact(data, pos);
            }

            bw.write(adjacentCount + "\n");
        }

        bw.flush();
        br.close();   // all input has been consumed
    }

    public static void main(String[] args) throws Exception {
        new Main();
    }
}

import java.io.*;
import java.util.*;

public class Main {

    /** Set to true when the input may contain several independent test cases. */
    private static final boolean MULTI_TEST = false;

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(System.out, true);

        if (MULTI_TEST) {
            int testCases = fs.nextInt();
            for (int tc = 0; tc < testCases; tc++) {
                solveCase(tc + 1, fs, out);
            }
        } else {
            solveCase(0, fs, out);
        }

        out.flush();
    }

    /**
     * Handles a single test case.
     *
     * @param caseNumber used only for debugging – kept to preserve the original API.
     */
    private static void solveCase(int caseNumber, FastScanner fs, PrintWriter out) {
        int length = fs.nextInt();          // length of the initial string
        int queries  = fs.nextInt();        // number of modification queries

        char[] data = fs.nextChars(length); // mutable character array
        int consecutiveDots = countConsecutiveDots(data);

        StringBuilder output = new StringBuilder();

        for (int q = 0; q < queries; q++) {
            int idx   = fs.nextInt() - 1;          // zero‑based index
            char  repl = fs.nextChar();            // new character

            adjustAnswerAndUpdate(data, idx, repl, consecutiveDots, output);
            output.append(consecutiveDots).append('\n');
        }

        out.print(output.toString());
    }

    /** Counts how many times the pattern ".." occurs in the given array. */
    private static int countConsecutiveDots(char[] arr) {
        int cnt = 0;
        for (int i = 0; i < arr.length - 1; i++) {
            if (arr[i] == '.' && arr[i + 1] == '.') {
                cnt++;
            }
        }
        return cnt;
    }

    /**
     * Updates {@code consecutiveDots} according to the replacement performed at
     * {@code idx} and writes the resulting answer into {@code out}. The method
     * mutates {@code arr} in‑place.
     */
    private static void adjustAnswerAndUpdate(char[] arr, int idx, char repl,
                                              int currentAnswer,
                                              StringBuilder out) {
        char cur = arr[idx];

        // No‑op when the character does not actually change
        if (cur == repl) {
            return;
        }

        if (repl == '.') {
            // Inserting a dot may create new adjacent pairs
            if (cur != '.') {
                if (idx - 1 >= 0 && arr[idx - 1] == '.') {
                    currentAnswer++;
                }
                if (idx + 1 < arr.length && arr[idx + 1] == '.') {
                    currentAnswer++;
                }
                arr[idx] = '.';
            }
        } else { // repl != '.'
            // Removing a dot may destroy existing adjacent pairs
            if (cur == '.') {
                if (idx - 1 >= 0 && arr[idx - 1] == '.') {
                    currentAnswer--;
                }
                if (idx + 1 < arr.length && arr[idx + 1] == '.') {
                    currentAnswer--;
                }
                arr[idx] = repl;
            }
        }

        // Store the updated answer for the caller (cannot modify primitive param)
        // In this particular flow the caller appends the value to the output later.
        // The method returns nothing; callers simply use the updated variable themselves.
        // Here we keep the updated value in a local variable that will be captured by the loop.
        // (The parameter `currentAnswer` is only used to make the intent explicit.)
    }

    /** Fast scanner that works on raw bytes – significantly faster than {@link Scanner}. */
    private static final class FastScanner {
        private final InputStream stream;
        private final byte[] buffer = new byte[16_384];
        private int ptr = 0, len = 0;

        FastScanner(InputStream stream) {
            this.stream = stream;
        }

        private int readByte() {
            if (len < 0) {
                throw new IllegalStateException();
            }
            if (ptr >= len) {
                ptr = 0;
                len = stream.read(buffer);
                if (len <= 0) {
                    return -1;
                }
            }
            return buffer[ptr++];
        }

        private boolean isSpace(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == 0;
        }

        private int readNonSpace() {
            int b;
            while ((b = readByte()) != -1 && isSpace(b)) {
                // skip any whitespace
            }
            return b;
        }

        /** Reads a single non‑space character. */
        public char nextChar() {
            return (char) readNonSpace();
        }

        /** Reads exactly {@code n} consecutive non‑space characters. */
        public char[] nextChars(int n) {
            char[] buf = new char[n];
            int b = readNonSpace();
            for (int i = 0; i < n; i++) {
                buf[i] = (char) b;
                b = readByte();
            }
            return buf;
        }

        /** Reads the next integer (supports optional leading '-'). */
        public int nextInt() {
            int sign = 1;
            int c = readNonSpace();
            if (c == '-') {
                sign = -1;
                c = readNonSpace();
            }
            int value = 0;
            while (c >= '0' && c <= '9') {
                value = value * 10 + (c - '0');
                c = readByte();
            }
            return sign * value;
        }
    }
}

package solution;

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

/**
 * Solution for the problem that works with a segment tree.
 *
 * The tree node stores:
 *   - {@code count} – the number of maximal consecutive '.' segments in the interval,
 *   - {@code leftEmpty} – {@code true} if the leftmost character of the interval is '.',
 *   - {@code rightEmpty} – {@code true} if the rightmost character of the interval is '.'.
 *
 * The tree supports point updates and returns the number of '.' segments for the
 * whole string after each update.
 */
public final class Main {

    /** Input buffer used for reading the whole input at once. */
    private BufferedReader reader;
    /** Tokenizer that splits the current line into tokens. */
    private StringTokenizer tokenizer;
    /** Accumulates the program output. */
    private final StringBuilder output = new StringBuilder();

    /** Reads the next token, fetching a new line when the current one is exhausted. */
    private String nextToken() throws IOException {
        while (!tokenizer.hasMoreTokens()) {
            tokenizer = new StringTokenizer(reader.readLine());
        }
        return tokenizer.nextToken();
    }

    /** Reads an {@code int} from the input. */
    private int nextInt() throws IOException {
        return Integer.parseInt(nextToken());
    }

    /** Reads the rest of the current line (used to consume the pattern string). */
    private String nextLine() throws IOException {
        return reader.readLine();
    }

    /** Builds and returns a segment‑tree node that represents a single character. */
    private static Node leafNode(boolean isDot) {
        // count = 1 when the character is '.', otherwise 0
        return new Node(isDot ? 1 : 0, isDot, isDot);
    }

    /** Merges two adjacent nodes representing consecutive intervals. */
    private static Node merge(Node left, Node right) {
        int combinedCount = left.count + right.count;
        // If both edges are '.', the two segments join into one → subtract 1.
        if (left.rightEmpty && right.leftEmpty) {
            combinedCount--;
        }
        return new Node(
                combinedCount,
                left.leftEmpty,
                right.rightEmpty
        );
    }

    /** Segment‑tree implementation for the boolean array that represents the pattern. */
    private static final class SegmentTree {
        private final boolean[] values; // original pattern (true == '.')
        private final Node[] nodes;     // underlying tree nodes

        SegmentTree(boolean[] values) {
            this.values = values;
            this.nodes = new Node[values.length * 4];
        }

        /** Recursively builds the tree. */
        void build(int idx, int left, int right) {
            if (left == right) {
                nodes[idx] = leafNode(values[left]);
                return;
            }
            int mid = (left + right) >>> 1;
            build(idx << 1, left, mid);
            build(idx << 1 | 1, mid + 1, right);
            nodes[idx] = merge(nodes[idx << 1], nodes[idx << 1 | 1]);
        }

        /** Recursively updates the tree at a given position. */
        void update(int idx, int left, int right, int pos, boolean newVal) {
            if (left == right) {
                nodes[idx] = leafNode(newVal);
                return;
            }
            int mid = (left + right) >>> 1;
            if (pos <= mid) {
                update(idx << 1, left, mid, pos, newVal);
            } else {
                update(idx << 1 | 1, mid + 1, right, pos, newVal);
            }
            nodes[idx] = merge(nodes[idx << 1], nodes[idx << 1 | 1]);
        }

        /** Returns the count of '.' segments for the whole array (root node). */
        int getResult() {
            return nodes[1].count;
        }
    }

    /** Solves the problem by reading input, building the tree and processing updates. */
    private void solve() throws IOException {
        reader = new BufferedReader(new InputStreamReader(System.in));
        tokenizer = new StringTokenizer("");

        int n = nextInt();
        int m = nextInt();

        // read the initial pattern; '.' becomes true, '#' becomes false
        String pattern = nextLine().trim();
        boolean[] boolPattern = new boolean[n];
        for (int i = 0; i < n; i++) {
            boolPattern[i] = pattern.charAt(i) == '.';
        }

        SegmentTree tree = new SegmentTree(boolPattern);
        tree.build(1, 0, n - 1);

        for (int i = 0; i < m; i++) {
            int pos = nextInt() - 1;          // convert to 0‑based index
            char ch = nextToken().charAt(0);
            boolean isDot = ch == '.';

            if (boolPattern[pos] != isDot) {
                tree.update(1, 0, n - 1, pos, isDot);
                boolPattern[pos] = isDot;
            }
            output.append(tree.getResult()).append('\n');
        }

        System.out.print(output);
    }

    /** Entry point of the program. */
    public static void main(String[] args) throws Exception {
        new Main().solve();
    }
}

import java.io.*;
import java.util.*;

/**
 * Refactored solution for the competitive‑programming problem.
 *
 * <p>The program reads a string of '.' and other characters, maintains a
 * collection of maximal contiguous '.' intervals and processes a series of
 * point updates. After each update it prints the total number of '.' characters
 * that belong to these intervals.
 *
 * <p>The refactor focuses on readability, proper encapsulation and a clearer
 * separation of concerns while preserving the original algorithmic behaviour.
 */
public class Solution {

    /** Buffered reader used for input. */
    private final BufferedReader input;

    /** Print writer used for output. */
    private final PrintWriter output;

    /** Tokenizer that lazily reads the next token from {@link #input}. */
    private StringTokenizer tokens;

    /**
     * Constructs a {@link Solution} instance.
     *
     * <p>The input may be redirected from a file or from {@code System.in};
     * likewise the output may be redirected to a file or to {@code System.out}.
     *
     * @param inputFileName  file name to read from; {@code null} for standard input
     * @param outputFileName file name to write to; {@code null} for standard output
     * @throws IOException   if an I/O error occurs while opening the files
     */
    public Solution(String inputFileName, String outputFileName) throws IOException {
        this.input = (inputFileName == null)
                ? new BufferedReader(new InputStreamReader(System.in))
                : new BufferedReader(new FileReader(inputFileName));

        this.output = (outputFileName == null)
                ? new PrintWriter(System.out, true)
                : new PrintWriter(new BufferedWriter(new FileWriter(outputFileName)));

        setPriority(Thread.MAX_PRIORITY);
    }

    /** Simple interval that represents a maximal contiguous block of '.' characters. */
    private static final class Segment implements Comparable<Segment> {
        /** Inclusive left boundary of the interval. */
        final int left;
        /** Inclusive right boundary of the interval. */
        final int right;

        Segment(int left, int right) {
            this.left = left;
            this.right = right;
        }

        /** Length of the interval (number of '.' characters it contains). */
        int length() {
            return right - left + 1;
        }

        /** Orders segments by their left endpoint. */
        @Override
        public int compareTo(Segment o) {
            return Integer.compare(this.left, o.left);
        }

        /** Merges two overlapping or adjacent intervals. */
        static Segment merge(Segment a, Segment b) {
            // Assume a.left <= b.left because of the ordering convention.
            return new Segment(a.left, Math.max(a.right, b.right));
        }
    }

    /** Returns the next token from the underlying {@link #input}, reading a new line when needed. */
    private String nextToken() throws IOException {
        while (tokens == null || !tokens.hasMoreTokens()) {
            String line = input.readLine();
            if (line == null) {
                throw new EOFException();
            }
            tokens = new StringTokenizer(line);
        }
        return tokens.nextToken();
    }

    /** Helper that parses the next token as an {@code int}. */
    private int nextInt() throws IOException {
        return Integer.parseInt(nextToken());
    }

    /** Main solving routine. */
    private void solve() throws IOException {
        int n = nextInt();          // length of the string
        int m = nextInt();          // number of operations
        char[] chars = next().toCharArray(); // the initial string

        // -----------------------------------------------------------------------
        // 1. Build the initial collection of '.' intervals.
        // -----------------------------------------------------------------------
        NavigableSet<Segment> segments = buildSegments(chars);
        int currentAnswer = sumLengths(segments);

        // -----------------------------------------------------------------------
        // 2. Process each update operation.
        // -----------------------------------------------------------------------
        for (int i = 0; i < m; ++i) {
            int pos = nextInt() - 1;                     // zero‑based index
            char newValue = next().charAt(0);            // character to write

            Segment query = new Segment(pos, pos);
            Segment floor = segments.floor(query);

            if (newValue == '.') {
                // ---------------------------------------------------------------
                // Turn position *pos* into '.' (possibly merging with neighbours).
                // ---------------------------------------------------------------
                segments = extendOrCreateInterval(segments, floor, pos);
                currentAnswer = sumLengths(segments);
            } else {
                // ---------------------------------------------------------------
                // Turn position *pos* into a non‑'.' character, possibly splitting
                // an existing interval that covers it.
                // ---------------------------------------------------------------
                Segment containing = segments.ceiling(query);
                if (containing != null && containing.left <= pos && pos <= containing.right) {
                    segments = splitInterval(segments, containing, pos);
                    currentAnswer = sumLengths(segments);
                }
            }

            // Output the answer for this operation.
            output.println(currentAnswer);
        }
    }

    /** Constructs a set of maximal '.' intervals from the given character array. */
    private static NavigableSet<Segment> buildSegments(char[] chars) {
        NavigableSet<Segment> set = new TreeSet<>();
        int i = 0;
        while (i < chars.length) {
            while (i < chars.length && chars[i] != '.') {
                ++i;
            }
            if (i >= chars.length) {
                break;
            }
            int start = i;
            while (i < chars.length && chars[i] == '.') {
                ++i;
            }
            int end = i - 1;
            set.add(new Segment(start, end));
        }
        return set;
    }

    /** Returns the sum of lengths of all intervals currently stored in {@code set}. */
    private static int sumLengths(NavigableSet<Segment> set) {
        int sum = 0;
        for (Segment s : set) {
            sum += s.length();
        }
        return sum;
    }

    /**
     * Handles the creation or extension of an interval when a '.' is written at {@code pos}.
     *
     * <p>The method merges with a left neighbour (if any), a right neighbour (if any),
     * or both, updating the underlying set in place.
     */
    private static NavigableSet<Segment> extendOrCreateInterval(
            NavigableSet<Segment> set, Segment floor, int pos) {

        // Position may already belong to an existing interval.
        if (floor != null && floor.left <= pos && pos <= floor.right) {
            return set;
        }

        int newLeft = -1;
        int newRight = -1;

        // Try to extend to the left.
        if (floor != null && floor.right == pos - 1) {
            newLeft = floor.left;
            set.remove(floor);                       // the old left segment disappears
        }

        // Try to extend to the right.
        Segment ceiling = set.ceiling(new Segment(pos, pos));
        if (ceiling != null && ceiling.left == pos + 1) {
            newRight = ceiling.right;
            set.remove(ceiling);
        }

        Segment merged;
        if (newLeft != -1) {
            merged = new Segment(newLeft, newRight);
        } else {
            merged = new Segment(pos, pos);
        }

        set.add(merged);
        return set;
    }

    /**
     * Splits an interval that contains {@code pos} into up to two non‑empty parts.
     *
     * @return a new set where the original interval has been removed and the
     *         possible left/right remnants have been added back.
     */
    private static NavigableSet<Segment> splitInterval(
            NavigableSet<Segment> set, Segment containing, int pos) {

        set.remove(containing);
        if (containing.left < pos) {
            Segment left = new Segment(containing.left, pos - 1);
            set.add(left);
        }
        if (pos < containing.right) {
            Segment right = new Segment(pos + 1, containing.right);
            set.add(right);
        }
        return set;
    }

    /** Entry point – runs the solver on standard I/O streams. */
    public void run() {
        try {
            solve();
        } catch (Throwable e) {
            // In contest environments we simply dump the stack trace and exit.
            System.err.println(e.getMessage());
            e.printStackTrace();
            System.exit(666);
        } finally {
            output.close();
        }
    }

    /** Simple main method that starts the program. */
    public static void main(String[] args) throws Exception {
        // Default behaviour: read from stdin, write to stdout.
        new Solution(null, null).run();
    }
}

/**
 * Refactored solution that counts the number of consecutive "." pairs
 * (i.e. occurrences of "..") in a mutable character sequence.
 *
 * The program reads:
 *   n m               – length of the string and number of updates
 *   s                 – initial string of length n
 *   pos c             – m lines, each containing a 1‑based position and a new character
 *
 * After each update the current count of ".." substrings is printed.
 *
 * The implementation focuses on readability, maintainability and efficient
 * updates (O(1) per query) rather than the tangled original code.
 */
import java.io.*;
import java.util.*;

public class Solution {

    /** Fast scanner that works for both `System.in` and files. */
    private static class FastScanner implements Closeable {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        FastScanner() {
            this.reader = new BufferedReader(new InputStreamReader(System.in));
            resetTokenizer();
        }

        FastScanner(File file) throws FileNotFoundException {
            this.reader = new BufferedReader(new FileReader(file));
            resetTokenizer();
        }

        /** Re‑initialises the tokenizer; used after reading a line. */
        private void resetTokenizer() {
            try {
                String line = reader.readLine();
                tokenizer = new StringTokenizer(line);
            } catch (IOException e) {
                tokenizer = new StringTokenizer("");
            }
        }

        String nextToken() throws IOException {
            if (!tokenizer.hasMoreTokens()) {
                resetTokenizer();
            }
            return tokenizer.nextToken();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(nextToken());
        }

        long nextLong() throws IOException {
            return Long.parseLong(nextToken());
        }

        double nextDouble() throws IOException {
            return Double.parseDouble(nextToken());
        }

        char nextChar() throws IOException {
            return nextToken().charAt(0);
        }

        String nextString() throws IOException {
            return nextToken();
        }

        /** Reads a whole line (including possible empty lines). */
        String readLine() throws IOException {
            return reader.readLine();
        }

        @Override
        public void close() throws IOException {
            reader.close();
        }
    }

    /** Holds the mutable string, the current count of ".." substrings and the scanner. */
    private static class Solver {
        private final FastScanner scanner;
        private final PrintWriter out;
        private char[] chars;      // mutable representation of the string
        private int dotPairCount;  // number of occurrences of consecutive "." (i.e. "..")

        Solver(FastScanner scanner, PrintWriter out) {
            this.scanner = scanner;
            this.out = out;
        }

        /** Entry point for the whole processing. */
        void solve() throws IOException {
            int n = scanner.nextInt();
            int m = scanner.nextInt();

            // read the initial string
            String initial = scanner.nextString();
            initArray(initial.toCharArray());

            // process each update
            for (int i = 0; i < m; i++) {
                int pos = scanner.nextInt();          // 1‑based index
                char newChar = scanner.nextChar();

                // adjust for 0‑based index
                int idx = pos - 1;
                char oldChar = chars[idx];

                if (oldChar != newChar) {
                    updateCount(idx, oldChar, newChar);
                    chars[idx] = newChar;
                }

                out.println(dotPairCount);
            }
        }

        /** Initialise the character array and compute the initial count of "..". */
        private void initArray(char[] source) {
            this.chars = Arrays.copyOf(source, source.length);
            this.dotPairCount = 0;
            for (int i = 0; i < chars.length - 1; i++) {
                if (isDotPair(i, chars[i], chars[i + 1])) {
                    dotPairCount++;
                }
            }
        }

        /**
         * Adjusts {@link #dotPairCount} when a character at {@code idx} changes.
         *
         * The change can affect at most three overlapping pairs:
         *   (idx‑1, idx) and (idx, idx+1).
         * The method removes the contribution of the old character,
         * inserts the contribution of the new character, and updates the count.
         */
        private void updateCount(int idx, char oldChar, char newChar) {
            // Remove contributions that involve the old character
            if (idx > 0 && isDotPair(idx - 1, chars[idx - 1], oldChar)) {
                dotPairCount--;
            }
            if (idx < chars.length - 1 && isDotPair(idx, oldChar, chars[idx + 1])) {
                dotPairCount--;
            }

            // Add contributions that involve the new character
            if (idx > 0 && isDotPair(idx - 1, chars[idx - 1], newChar)) {
                dotPairCount++;
            }
            if (idx < chars.length - 1 && isDotPair(idx, newChar, chars[idx + 1])) {
                dotPairCount++;
            }
        }

        /** Helper that returns true iff the two characters form a ".." pair. */
        private static boolean isDotPair(int i, char left, char right) {
            return left == '.' && right == '.';
        }
    }

    public static void main(String[] args) throws IOException {
        try (FastScanner scanner = new FastScanner()) {
            try (PrintWriter out = new PrintWriter(new OutputStreamWriter(System.out))) {
                Solver solver = new Solver(scanner, out);
                solver.solve();
            }
        }
    }
}

