/**
 * Solves the problem that was originally encoded in {@code TaskC}.
 */
final class Solver {

    /**
     * Reads the board size, the initial board and all operations,
     * updates the board and prints the required value after each step.
     */
    void solve(FastScanner in, FastPrinter out) {
        int n = in.readInt();                 // length of the board
        int m = in.readInt();                 // number of operations
        String init = in.readLine();          // initial board string

        Board board = new Board(init);
        board.processOperations(in, m, out); // handle each operation
    }
}

/**
 * Encapsulates the mutable board and the derived statistics:
 * <ul>
 *   <li>{@code dotCount} – total number of '.' characters.</li>
 *   <li>{@code blockCount} – number of contiguous '.' blocks.</li>
 * </ul>
 * It updates those counters incrementally on each cell change.
 */
final class Board {

    /** Current characters of the board. */
    private final char[] data;

    /** Total number of '.' characters in {@code data}. */
    private int dotCount;

    /** Number of contiguous blocks of '.' characters. */
    private int blockCount;

    Board(String initial) {
        this.data = initial.toCharArray();
        this.dotCount = countDots();
        this.blockCount = countBlocks();
    }

    /** Public method used by {@link Solver} to process a sequence of operations. */
    void processOperations(FastScanner in, int operationsCount, FastPrinter out) {
        for (int i = 0; i < operationsCount; i++) {
            int pos = in.readInt() - 1;                // convert to 0‑based index
            char newChar = in.readCharacter();

            applyChange(pos, newChar);                // update internal counters
            data[pos] = newChar;                       // physically store the change
            out.printLine(result());                  // print dotCount - blockCount
        }
    }

    /** Adjusts {@code dotCount} and {@code blockCount} when a single cell changes. */
    private void applyChange(int index, char newChar) {
        char oldChar = data[index];
        if (oldChar == newChar) {
            return;                                   // nothing changes
        }

        boolean wasDot = oldChar == '.';
        boolean nowDot = newChar == '.';

        // ----- update dot count -------------------------------------------------
        if (wasDot) dotCount--;
        if (nowDot) dotCount++;

        // ----- update block count -----------------------------------------------
        updateBlockCountAround(index, wasDot, nowDot);
    }

    /** Re‑calculates the block count in the neighbourhood of the changed index. */
    private void updateBlockCountAround(int index, boolean wasDot, boolean nowDot) {
        // Determine left/right neighbour characters (use a sentinel if out of bounds).
        char left  = (index - 1 >= 0) ? data[index - 1] : '\0';
        char right = (index + 1 < data.length) ? data[index + 1] : '\0';

        // Transition from non‑dot → dot
        if (!wasDot && nowDot) {
            boolean leftIsDot  = left == '.';
            boolean rightIsDot = right == '.';

            if (leftIsDot && rightIsDot) {
                // Two neighbouring blocks merge into one.
                this.blockCount--;
            } else if (!leftIsDot && !rightIsDot) {
                // Isolated new block.
                this.blockCount++;
            }
            // If exactly one neighbour is a dot we simply extend an existing block –
            // block count stays unchanged.
        }
        // Transition from dot → non‑dot
        else if (wasDot && !nowDot) {
            boolean leftIsDot  = left == '.';
            boolean rightIsDot = right == '.';

            if (leftIsDot && rightIsDot) {
                // Removing a dot that separates two blocks splits one block into two.
                this.blockCount++;
            } else if (!leftIsDot && !rightIsDot) {
                // Removing an isolated block reduces the total number of blocks.
                this.blockCount--;
            }
            // Otherwise we just shorten a block – block count unchanged.
        }
    }

    /** Returns the required output value: {@code dotCount - blockCount}. */
    private int result() {
        return dotCount - blockCount;
    }

    /** Counts total '.' characters in the current board. */
    private static int countDots(char[] arr) {
        int cnt = 0;
        for (char c : arr) {
            if (c == '.') cnt++;
        }
        return cnt;
    }

    /** Counts contiguous blocks of '.' characters. */
    private static int countBlocks(char[] arr) {
        int blocks = 0;
        boolean inside = false;
        for (char c : arr) {
            if (c == '.') {
                if (!inside) {
                    blocks++;
                    inside = true;
                }
            } else {
                inside = false;
            }
        }
        return blocks;
    }
}

/* ---------------------------------------------------------------------------
 *  Fast I/O helpers – they hide the boilerplate of raw {@code InputStream}
 *  and {@code OutputStream} handling and make the main algorithm easier to
 *  read.
 * --------------------------------------------------------------------------- */

/**
 * Simple buffered scanner that works with {@code System.in}.
 */
final class FastScanner {
    private final InputStream stream;
    private final byte[] buffer = new byte[16_384];
    private int pointer = 0, length = 0;

    FastScanner(InputStream stream) {
        this.stream = stream;
    }

    private int readByte() throws IOException {
        if (pointer >= length) {
            length = stream.read(buffer);
            pointer = 0;
            if (length <= 0) return -1;
        }
        return buffer[pointer++];
    }

    /** Reads a signed 32‑bit integer. */
    int readInt() throws IOException {
        int c, sign = 1, val = 0;
        do { c = readByte(); } while (c <= ' ' && c != -1);
        if (c == '-') { sign = -1; c = readByte(); }
        while (c > ' ') {
            val = val * 10 + (c - '0');
            c = readByte();
        }
        return val * sign;
    }

    /** Reads the next non‑whitespace character. */
    char readCharacter() throws IOException {
        int c;
        do { c = readByte(); } while (c <= ' ' && c != -1);
        return (char) c;
    }

    /** Reads a full line (terminated by '\n' or EOF). */
    String readLine() throws IOException {
        StringBuilder sb = new StringBuilder();
        int c;
        while ((c = readByte()) != '\n' && c != -1) {
            sb.append((char) c);
        }
        return sb.toString();
    }
}

/**
 * Minimal printer that writes to {@code System.out}.
 */
final class FastPrinter {
    private final PrintWriter writer;

    FastPrinter(OutputStream out) {
        this.writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(out)));
    }

    /** Prints an integer followed by a line break. */
    void printLine(int value) {
        writer.println(value);
    }

    /** Flushes and closes the underlying writer. */
    void close() {
        writer.close();
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;

public class Replacement {

    public static void main(String[] args) throws IOException {
        // BufferedReader with try‑with‑resources guarantees proper closure
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in))) {

            // -----------------------------------------------------------
            // 1️⃣ Read header: length of the character sequence and #ops
            // -----------------------------------------------------------
            String[] header = br.readLine().split("\\s+");
            int length = Integer.parseInt(header[0]);   // size of the array
            int operations = Integer.parseInt(header[1]); // number of updates

            // -----------------------------------------------------------
            // 2️⃣ Read the initial character sequence
            // -----------------------------------------------------------
            char[] chars = br.readLine().toCharArray();

            // -----------------------------------------------------------
            // 3️⃣ Initialise the count of adjacent '.' pairs
            // -----------------------------------------------------------
            int adjacentDotCount = countAdjacentDots(chars);

            // -----------------------------------------------------------
            // 4️⃣ Process each update, adjust the count and collect output
            // -----------------------------------------------------------
            StringBuilder output = new StringBuilder();

            for (int i = 0; i < operations; i++) {
                String[] parts = br.readLine().split("\\s+");
                int idx = Integer.parseInt(parts[0]) - 1;           // convert to 0‑based index
                char newChar = parts[1].charAt(0);

                int delta = computeDelta(chars, idx, newChar);
                adjacentDotCount += delta;
                chars[idx] = newChar;                               // mutate in‑place

                output.append(adjacentDotCount).append('\n');
            }

            // -----------------------------------------------------------
            // 5️⃣ Output all answers (one per line)
            // -----------------------------------------------------------
            System.out.print(output.toString());
        }
    }

    /** Counts how many positions *i* (1 ≤ i < length) satisfy
     *  {@code chars[i] == '.' && chars[i‑1] == '.'}. */
    private static int countAdjacentDots(char[] chars) {
        int cnt = 0;
        for (int i = 1; i < chars.length; i++) {
            if (chars[i] == '.' && chars[i - 1] == '.') {
                cnt++;
            }
        }
        return cnt;
    }

    /**
     * Determines how the adjacent‑dot count changes when the character at
     * {@code idx} is replaced by {@code newChar}.
     *
     * @return delta – a positive value to add to the current count,
     *         or a negative value to subtract.
     */
    private static int computeDelta(char[] chars, int idx, char newChar) {
        char oldChar = chars[idx];
        if (oldChar == newChar) {
            return 0; // No change, return 0
        }

        int delta = 0;

        // ---- Remove contributions of the old character ----
        // Pair (idx‑1, idx)
        if (idx > 0 && chars[idx - 1] == '.' && oldChar == '.') {
            delta--;
        }
        // Pair (idx, idx+1)
        if (idx < chars.length - 1 && oldChar == '.' && chars[idx + 1] == '.') {
            delta--;
        }

        // ---- Add contributions of the new character ----
        // Pair (idx‑1, idx)
        if (idx > 0 && chars[idx - 1] == '.' && newChar == '.') {
            delta++;
        }
        // Pair (idx, idx+1)
        if (idx < chars.length - 1 && newChar == '.' && chars[idx + 1] == '.') {
            delta++;
        }

        return delta;
    }
}

import java.io.*;
import java.util.*;

 /*** Fast scanner that reads tokens from standard input ***/
class FastScanner {
    private final BufferedReader br;
    private StringTokenizer st;

    FastScanner(BufferedReader br) {
        this.br = br;
    }

    /** Returns the next token, reading a new line if needed. */
    private String nextToken() {
        while (st == null || !st.hasMoreTokens()) {
            try {
                st = new StringTokenizer(br.readLine());
            } catch (IOException e) {
                throw new UncheckedIOException(e);
            }
        }
        return st.nextToken();
    }

    int nextInt() {
        return Integer.parseInt(nextToken());
    }

    char nextChar() {
        return nextToken().charAt(0);
    }
}

/** Encapsulates all logic related to counting '.' characters and their blocks. */
class PeriodProcessor {
    private final char[] data;          // mutable representation of the string
    private final int length;            // length of the string
    private long totalPeriods;           // total number of '.' characters
    private long totalSegments;          // number of contiguous '.' blocks

    PeriodProcessor(char[] arr) {
        this.data = arr;
        this.length = arr.length;
        initCounters();
    }

    /** Scans the initial array and populates the counters. */
    private void initCounters() {
        totalPeriods = 0;
        totalSegments = 0;
        for (int i = 0; i < length; i++) {
            if (data[i] == '.') {
                totalPeriods++;
                maybeStartNewSegment(i);
            }
        }
    }

    /** A new '.' block starts when the current index is '.' and the previous one is not. */
    private void maybeStartNewSegment(int idx) {
        if (idx == 0 || data[idx - 1] != '.') {
            totalSegments++;
        }
    }

    /** Called when a non‑'.' position becomes '.' . */
    void addPeriod(int pos) {
        // neighbours may or may not be inside the array
        boolean leftIsPeriod  = isPeriod(pos - 1);
        boolean rightIsPeriod = isPeriod(pos + 1);

        // Turning '.' creates a new block or merges existing ones
        if (leftIsPeriod && rightIsPeriod) {
            // two separate blocks become connected → lose one segment
            totalSegments--;
        } else if (!leftIsPeriod && !rightIsPeriod) {
            // isolated '.' → a new block appears
            totalSegments++;
        }
        // otherwise the number of blocks stays the same

        data[pos] = '.';
        totalPeriods++;
    }

    /** Called when a '.' position becomes a non‑'.' character. */
    void removePeriod(int pos) {
        boolean leftIsPeriod  = isPeriod(pos - 1);
        boolean rightIsPeriod = isPeriod(pos + 1);

        if (leftIsPeriod && rightIsPeriod) {
            // removing a '.' splits a block into two → gain one segment
            totalSegments++;
        } else if (!leftIsPeriod && !rightIsPeriod) {
            // removing the only '.' of an isolated block → lose one segment
            totalSegments--;
        }
        // otherwise the number of blocks does not change

        totalPeriods--;
        // the actual character will be overwritten by the caller
    }

    /** Helper that safely checks whether an index holds '.'. */
    private boolean isPeriod(int idx) {
        return idx >= 0 && idx < length && data[idx] == '.';
    }

    /** Returns the required answer: periods – segments . */
    long answer() {
        return totalPeriods - totalSegments;
    }
}

/** Entry point of the program. */
public class Main {
    public static void main(String[] args) {
        FastScanner fs = new FastScanner(new BufferedReader(new InputStreamReader(System.in)));
        PrintWriter out = new PrintWriter(System.out);

        int n = fs.nextInt();          // length of the string
        int m = fs.nextInt();          // number of operations
        String s = fs.nextToken();     // initial string
        char[] chars = s.toCharArray();

        PeriodProcessor processor = new PeriodProcessor(chars);

        for (int i = 0; i < m; i++) {
            int idx = fs.nextInt() - 1; // problem uses 1‑based indices
            char newChar = fs.nextChar();

            if (newChar == '.' && chars[idx] != '.') {
                processor.addPeriod(idx);
            } else if (newChar != '.' && chars[idx] == '.') {
                processor.removePeriod(idx);
            }
            // if the character does not change, nothing needs to be updated

            chars[idx] = newChar;       // keep the underlying array in sync
            out.println(processor.answer());
        }

        out.close();
    }
}

import java.io.*;
import java.util.*;

/**
 * Main entry point. Delegates all work to {@link TaskC}.
 */
public class Main {

    public static void main(String[] args) {
        solve(System.in, System.out);
    }

    /**
     * Core driver that reads input, creates the solver and prints results.
     *
     * @param in  input stream
     * @param out output stream
     */
    private static void solve(InputStream in, PrintStream out) {
        FastScanner fs = new FastScanner(in);
        TaskC solver = new TaskC();
        solver.process(1, fs, new PrintWriter(out));
    }

    /** Solver class that contains all the problem‑specific logic. */
    private static class TaskC {

        /** A maximal contiguous segment of '.' characters. */
        private static final class Segment implements Comparable<Segment> {
            final int start; // inclusive
            final int end;   // exclusive

            Segment(int start, int end) {
                this.start = start;
                this.end = end;
            }

            @Override
            public int compareTo(Segment o) {
                int c = Integer.compare(this.start, o.start);
                if (c != 0) {
                    return c;
                }
                // deterministic ordering for equal starts
                return Integer.compare(this.end, o.end);
            }
        }

        /**
         * Reads a single test case (the problem contains only one) and processes
         * the {@code m} update queries.
         */
        void process(int testNumber, FastScanner fs, PrintWriter out) {
            int n = fs.nextInt();          // length of the string
            int m = fs.nextInt();          // number of queries
            char[] chars = fs.next().toCharArray();

            TreeSet<Segment> segments = new TreeSet<>();
            long score = computeInitialScore(chars, segments);

            for (int i = 0; i < m; i++) {
                int pos = fs.nextInt() - 1;                     // 0‑based
                char newChar = fs.next().charAt(0);

                // No change – nothing to do
                if (chars[pos] == '.' && newChar == '.') {
                    out.println(score);
                    continue;
                }

                char oldChar = chars[pos];
                chars[pos] = newChar;
                handleUpdate(pos, oldChar, newChar, chars, segments, score, out);
            }
        }

        /**
         * Analyzes the initial character array, builds the segment set and
         * returns the initial score (sum of (length‑1) for each '.' run).
         */
        private long computeInitialScore(char[] s, TreeSet<Segment> segments) {
            long score = 0;
            int start = -1;

            for (int i = 0; i <= s.length; i++) {
                if (i < s.length && s[i] == '.') {
                    if (start == -1) {
                        start = i;
                    }
                } else if (start != -1) {
                    int runLength = i - start; // number of '.' characters
                    if (runLength > 1) {
                        Segment seg = new Segment(start, i);
                        segments.add(seg);
                        score += runLength - 1;
                    }
                    start = -1;
                }
            }
            return score;
        }

        /** Dispatches the appropriate update based on the character change. */
        private void handleUpdate(int pos,
                                  char oldChar,
                                  char newChar,
                                  char[] s,
                                  TreeSet<Segment> segments,
                                  long score,
                                  PrintWriter out) {
            // Turning '.' into something else
            if (oldChar == '.' && newChar != '.') {
                removeSegmentContaining(pos, segments, score);
                out.println(score);
                return;
            }

            // Turning a non‑'.' into '.'
            if (oldChar != '.' && newChar == '.') {
                addSegmentAt(pos, s, segments, score);
                out.println(score);
                return;
            }

            // Old and new are both '.' – handled earlier (no‑op)
            out.println(score);
        }

        /** Removes the segment that covers {@code pos} and adjusts {@code score}. */
        private void removeSegmentContaining(int pos,
                                             TreeSet<Segment> segments,
                                             long score) {
            // Find a segment that starts ≤ pos and ends > pos
            Segment toRemove = segments.floor(new Segment(pos, Integer.MAX_VALUE));
            if (toRemove == null || toRemove.start > pos) {
                // No such segment – nothing to adjust
                return;
            }

            segments.remove(toRemove);
            long removedContribution = toRemove.end - toRemove.start - 1;
            score -= removedContribution;

            // Possibly split the removed segment into up to two new parts
            splitSegmentIfNeeded(toRemove.start, pos, segments, score, s);
            splitSegmentIfNeeded(pos + 1, toRemove.end, segments, score, s);
        }

        /** Inserts a '.' at {@code index} and updates {@code segments} & {@code score}. */
        private void addSegmentAt(int index,
                                  char[] s,
                                  TreeSet<Segment> segments,
                                  long score) {
            // Determine the eventual merged segment boundaries
            int newStart = index;
            int newEnd   = index + 1;

            // Check left side
            Segment left = findSegmentEndingAt(index - 1, segments);
            if (left != null) {
                newStart = left.start;
                segments.remove(left);
                score -= left.end - left.start - 1;
            }

            // Check right side
            Segment right = findSegmentStartingAt(index + 1, segments);
            if (right != null) {
                newEnd = right.end;
                segments.remove(right);
                score -= right.end - right.start - 1;
            }

            Segment merged = new Segment(newStart, newEnd);
            segments.add(merged);
            score += newEnd - newStart - 1;
        }

        /** Returns the segment whose {@code end} equals {@code pos}. */
        private Segment findSegmentEndingAt(int pos, TreeSet<Segment> segments) {
            Segment probe = new Segment(pos + 1, Integer.MAX_VALUE);
            Segment candidate = segments.floor(probe);
            return (candidate != null && candidate.end == pos + 1) ? candidate : null;
        }

        /** Returns the segment whose {@code start} equals {@code pos}. */
        private Segment findSegmentStartingAt(int pos, TreeSet<Segment> segments) {
            Segment probe = new Segment(pos, Integer.MAX_VALUE);
            Segment candidate = segments.floor(probe);
            return (candidate != null && candidate.start == pos) ? candidate : null;
        }

        /** If a segment spans over {@code splitPos} it is divided into two parts. */
        private void splitSegmentIfNeeded(int splitPos,
                                          int segmentEnd,
                                          TreeSet<Segment> segments,
                                          long score,
                                          char[] s) {
            Segment seg = segments.floor(new Segment(splitPos, Integer.MAX_VALUE));
            if (seg != null && seg.end == splitPos) {
                // Remove the whole segment (its contribution already subtracted)
                segments.remove(seg);

                // Left part (if any characters remain)
                if (seg.start < splitPos) {
                    Segment left = new Segment(seg.start, splitPos);
                    segments.add(left);
                    score += left.end - left.start - 1;
                }

                // Right part (if any characters remain)
                if (splitPos < seg.end) {
                    Segment right = new Segment(splitPos, seg.end);
                    segments.add(right);
                    score += right.end - right.start - 1;
                }
            }
        }
    }

    /** Fast scanner based on {@link BufferedReader} and {@link StringTokenizer}. */
    private static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner(InputStream stream) {
            this.br = new BufferedReader(new InputStreamReader(stream), 32768);
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    throw new UncheckedIOException(e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.io.*;
import java.util.StringTokenizer;

/**
 * Refactored solution for the problem.
 *
 * The program reads a string consisting of '.' and other characters and
 * maintains the number of adjacent dot pairs (i.e. substrings "..").
 * After each update it prints the current number of such pairs.
 */
public class Main {

    /** Fast scanner that works with BufferedReader and StringTokenizer. */
    private static class FastScanner {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        FastScanner(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
        }

        /** Returns next token, reading a new line if necessary. */
        private String nextToken() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        /** Convenience method for reading an int. */
        int nextInt() {
            return Integer.parseInt(nextToken());
        }

        /** Convenience method for reading a single character. */
        char nextChar() {
            return nextToken().charAt(0);
        }

        /** Convenience method for reading the whole next token as a String. */
        String next() {
            return nextToken();
        }
    }

    /**
     * Helper class that maintains an array of characters and the number of
     * adjacent dot pairs ("..") in the current array.
     *
     * All modifications to the array go through {@link #set(int, char)},
     * which updates the pair count in O(1) time.
     */
    private static class DotCounter {
        private final char[] data;
        private int adjacentDotPairs; // the value we need to output

        /** Constructs a DotCounter from the given character array. */
        DotCounter(char[] array) {
            this.data = array.clone();
            this.adjacentDotPairs = countAdjacentDots();
        }

        /** Returns the current number of adjacent dot pairs. */
        int getPairCount() {
            return adjacentDotPairs;
        }

        /**
         * Updates the character at the given position with the new value.
         * The method correctly adjusts {@link #adjacentDotPairs} by looking
         * only at the affected neighboring positions.
         *
         * @param index position to change (0‑based)
         * @param newChar new character to place at {@code index}
         */
        void set(int index, char newChar) {
            char oldChar = data[index];
            if (oldChar == newChar) {
                return; // nothing changes
            }

            // Remove contributions of pairs that involve the index
            subtractPair(index - 1, index);
            subtractPair(index, index + 1);

            // Apply the change
            data[index] = newChar;

            // Add contributions of pairs that involve the index again
            addPair(index - 1, index);
            addPair(index, index + 1);
        }

        /** Increments pair count if positions i and j form a ".." pair. */
        private void addPair(int i, int j) {
            if (i >= 0 && j < data.length && data[i] == '.' && data[j] == '.') {
                adjacentDotPairs++;
            }
        }

        /** Decrements pair count if positions i and j form a ".." pair. */
        private void subtractPair(int i, int j) {
            if (i >= 0 && j < data.length && data[i] == '.' && data[j] == '.') {
                adjacentDotPairs--;
            }
        }

        /** Counts ".." occurrences in the whole array (used only at construction). */
        private int countAdjacentDots() {
            int cnt = 0;
            for (int i = 0; i < data.length - 1; i++) {
                if (data[i] == '.' && data[i + 1] == '.') {
                    cnt++;
                }
            }
            return cnt;
        }
    }

    /** Entry point of the program. */
    public static void main(String[] args) {
        FastScanner scanner = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(System.out);

        int n = scanner.nextInt();
        int m = scanner.nextInt();
        String original = scanner.next();

        char[] charArray = original.toCharArray();
        DotCounter counter = new DotCounter(charArray);

        StringBuilder outputLines = new StringBuilder();

        for (int q = 0; q < m; q++) {
            int idx = scanner.nextInt() - 1; // converting to 0‑based index
            char newChar = scanner.nextChar();

            if (charArray[idx] != newChar) {
                counter.set(idx, newChar);
                charArray[idx] = newChar; // keep the underlying array in sync
            }

            outputLines.append(counter.getPairCount()).append('\n');
        }

        out.print(outputLines.toString());
        out.flush();
    }
}

package main;

import java.io.PrintWriter;
import java.util.Scanner;

/**
 * Entry point of the application.
 * <p>
 * The program reads a string of length {@code n} and a series of {@code m}
 * update operations. After each update it prints the number of “extra”
 * '.' characters, i.e. the sum of {@code (runLength‑1)} for every maximal
 * consecutive run of '.' in the current array.
 * </p>
 */
public class Main {

    /** Number of test cases – the original code used a single case. */
    private static final int TEST_CASE_COUNT = 1;

    public static void main(String[] args) {
        // try‑with‑resources guarantees that streams are closed properly
        try (Scanner scanner = new Scanner(System.in);
             PrintWriter out = new PrintWriter(System.out)) {

            for (int t = 0; t < TEST_CASE_COUNT; t++) {
                processSingleTestCase(scanner, out);
            }
        }
    }

    /**
     * Reads the input for one test case, performs all updates and prints the
     * resulting value after each update.
     */
    private static void processSingleTestCase(Scanner in, PrintWriter out) {
        // Read dimensions
        int n = in.nextInt();          // length of the character array (unused directly)
        int m = in.nextInt();          // number of update operations

        // Consume the line break left by the previous nextInt()
        in.nextLine();
        // Read the initial character array
        String line = in.nextLine();
        char[] chars = line.toCharArray();

        // Initial total of "extra" dots
        int total = computeDotContribution(chars);

        // Process each update operation
        for (int i = 0; i < m; i++) {
            int idx = in.nextInt() - 1;          // convert to zero‑based index
            char replacement = in.next().charAt(0);
            chars[idx] = replacement;            // apply the change

            // Re‑compute the contribution from scratch – easier to understand
            total = computeDotContribution(chars);
            out.println(total);
        }
    }

    /**
     * Calculates the sum of {@code (runLength‑1)} for all maximal consecutive
     * sequences of '.' characters in the given array.
     *
     * @param arr array of characters to examine
     * @return the computed contribution
     */
    private static int computeDotContribution(char[] arr) {
        int contribution = 0;
        int consecutiveDots = 0;

        for (char c : arr) {
            if (c == '.') {
                consecutiveDots++;
            } else {
                // End of a '.' run – add (length‑1) if the run was non‑empty
                if (consecutiveDots > 0) {
                    contribution += consecutiveDots - 1;
                }
                consecutiveDots = 0; // reset for the next run
            }
        }

        // Handle a possible trailing run of '.' characters
        if (consecutiveDots > 0) {
            contribution += consecutiveDots - 1;
        }

        return contribution;
    }
}

/**
 * Refactored solution for the contest problem.
 *
 * <p>This version improves readability, maintainability and resource handling
 * while preserving the original algorithmic behaviour.
 */
public class Solution {

    /** Fast scanner that works with both {@code System.in} and files. */
    private static final class FastScanner implements AutoCloseable {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        /** Creates a scanner that reads from standard input. */
        FastScanner() {
            this.reader = new BufferedReader(new InputStreamReader(System.in));
            this.tokenizer = new StringTokenizer("");
        }

        /** Creates a scanner that reads from the given file. */
        FastScanner(File file) throws FileNotFoundException {
            this.reader = new BufferedReader(new FileReader(file));
            this.tokenizer = new StringTokenizer("");
        }

        /** Reads the next token as an {@code int}. */
        int nextInt() throws IOException {
            return Integer.parseInt(nextToken());
        }

        /** Reads the next token as a {@code long}. */
        long nextLong() throws IOException {
            return Long.parseLong(nextToken());
        }

        /** Reads the next token as a {@code double}. */
        double nextDouble() throws IOException {
            return Double.parseDouble(nextToken());
        }

        /** Reads the next token as a {@code String}. */
        String nextString() throws IOException {
            return nextToken();
        }

        /** Reads the next line. */
        String readLine() throws IOException {
            return reader.readLine();
        }

        /** Returns the next available token (or loads a new line if needed). */
        private String nextToken() throws IOException {
            if (!tokenizer.hasMoreTokens()) {
                tokenizer = new StringTokenizer(reader.readLine());
            }
            return tokenizer.nextToken();
        }

        /** Closes the underlying reader. */
        @Override
        public void close() throws IOException {
            reader.close();
        }
    }

    /** The main entry point of the program. */
    public static void main(String[] args) throws Exception {
        // -----------------------------------------------------------------
        // 1. Input handling
        // -----------------------------------------------------------------
        try (FastScanner fs = new FastScanner()) {
            int n = fs.nextInt();                 // number of characters (unused later)
            int testCases = fs.nextInt();           // number of modification queries
            StringBuilder sb = new StringBuilder(fs.nextString());

            // Initialise the extra‑period counter (originally named `anss`)
            int extraPeriods = computeExtraPeriods(sb);

            // Prepare output buffer
            StringBuilder output = new StringBuilder();

            // -----------------------------------------------------------------
            // 2. Process each query
            // -----------------------------------------------------------------
            for (int t = 0; t < testCases; t++) {
                int index = fs.nextInt() - 1;       // zero‑based position
                char newChar = fs.nextString().charAt(0);

                // Apply the modification and update the counter
                extraPeriods = applyModification(sb, index, newChar, extraPeriods);

                // Append the current counter value to the output
                output.append(extraPeriods).append('\n');
            }

            // -----------------------------------------------------------------
            // 3. Output the results
            // -----------------------------------------------------------------
            System.out.print(output.toString());
        }
    }

    /**
     * Computes the initial value of the extra‑period counter.
     *
     * <p>The counter equals the sum of {@code (runLength - 1)} for every maximal
     * sequence of consecutive '.' characters in the supplied {@link StringBuilder}.
     *
     * @param sb the mutable sequence to analyse
     * @return the computed extra‑period count
     */
    private static int computeExtraPeriods(StringBuilder sb) {
        int extra = 0;
        int consecutive = 0;

        for (int i = 0; i < sb.length(); i++) {
            char c = sb.charAt(i);
            if (c == '.') {
                consecutive++;
            } else if (consecutive > 0) {
                extra += consecutive - 1;
                consecutive = 0;
            }
        }
        if (consecutive > 0) {
            extra += consecutive - 1;
        }
        return extra;
    }

    /**
     * Applies a single modification to {@code sb} at {@code index} and updates
     * {@code extraPeriods} accordingly.
     *
     * <p>The method mirrors the original logic but isolates the delta‑computation
     * into a clear, self‑documenting block.
     *
     * @param sb            the mutable character sequence
     * @param index         position to modify (zero‑based)
     * @param newChar       character to set at {@code index}
     * @param currentCount  the counter value before the modification
     * @return the updated counter value
     */
    private static int applyModification(StringBuilder sb,
                                          int index,
                                          char newChar,
                                          int currentCount) {
        char oldChar = sb.charAt(index);

        // No change – nothing to adjust.
        if (oldChar == newChar) {
            return currentCount;
        }

        int delta = 0;                     // change to {@code currentCount}
        int len = sb.length();

        // -------------------------------------------------------------
        // 1. Removing a '.' -> possibly decrease the counter
        // -------------------------------------------------------------
        if (oldChar == '.' && newChar != '.') {
            if (index == 0) {
                // Removing '.' at the very start
                if (index + 1 < len && sb.charAt(index + 1) == '.') {
                    delta = -1;
                }
            } else if (index == len - 1) {
                // Removing '.' at the very end
                if (sb.charAt(index - 1) == '.') {
                    delta = -1;
                }
            } else {
                boolean prevIsDot = sb.charAt(index - 1) == '.';
                boolean nextIsDot = sb.charAt(index + 1) == '.';

                if (prevIsDot && nextIsDot) {
                    delta = -2;
                } else if (prevIsDot || nextIsDot) {
                    delta = -1;
                }
            }
            sb.setCharAt(index, newChar);
        }
        // -------------------------------------------------------------
        // 2. Adding a '.' -> possibly increase the counter
        // -------------------------------------------------------------
        else if (oldChar != '.' && newChar == '.') {
            if (index == 0) {
                // Adding '.' at the start
                if (index + 1 < len && sb.charAt(index + 1) == '.') {
                    delta = 1;
                }
            } else if (index == len - 1) {
                // Adding '.' at the end
                if (sb.charAt(index - 1) == '.') {
                    delta = 1;
                }
            } else {
                boolean prevIsDot = sb.charAt(index - 1) == '.';
                boolean nextIsDot = sb.charAt(index + 1) == '.';

                if (prevIsDot && nextIsDot) {
                    delta = 2;
                } else if (prevIsDot || nextIsDot) {
                    delta = 1;
                }
            }
            sb.setCharAt(index, newChar);
        }
        // -------------------------------------------------------------
        // 3. Change between two non‑'.' characters – no effect on counter
        // -------------------------------------------------------------
        else {
            sb.setCharAt(index, newChar);
        }

        return currentCount + delta;
    }
}

import java.io.*;
import java.util.StringTokenizer;

/**
 * Refactored solution for the “adjacent periods” problem.
 *
 * <p>Changes made for maintainability and readability:
 *
 * <ul>
 *   <li>Extracted the tracking logic into {@link PeriodTracker} for a single
 *       responsibility class.</li>
 *   <li>Renamed variables to expressive names (e.g., {@code length},
 *       {@code operations}, {@code pos}).</li>
 *   <li>Used try‑with‑resources to guarantee proper closure of {@code BufferedReader}
 *       and {@code PrintWriter}.</li>
 *   <li>Encapsulated the “adjacent period” count update in a dedicated method
 *       {@code update(int, char)}.</li>
 *   <li>Removed duplicated tokenizers and added inline comments.</li>
 *   <li>Added Javadoc‑style documentation and kept the original functional
 *       contract.</li>
 * </ul>
 *
 * The algorithmic core remains unchanged; only the structure and naming have
 * been improved.
 */
public class SolveC {

    /**
     * Helper class that stores the character array and maintains the count of
     * adjacent period ('.') characters.
     */
    private static final class PeriodTracker {
        private final char[] chars;
        private int adjacentPeriodCount;

        /**
         * Constructs a tracker with the given character array and initializes
         * the adjacent‑period counter.
         *
         * @param chars initial character sequence
         */
        PeriodTracker(char[] chars) {
            this.chars = chars;
            computeAdjacentPeriodCount();
        }

        /** Re‑calculates the counter based on the current {@code chars} array. */
        private void computeAdjacentPeriodCount() {
            adjacentPeriodCount = 0;
            for (int i = 1; i < chars.length; i++) {
                if (chars[i - 1] == '.' && chars[i] == '.') {
                    adjacentPeriodCount++;
                }
            }
        }

        /**
         * Updates the character at the specified position and returns the new
         * adjacent‑period count.
         *
         * @param index position to modify (0‑based)
         * @param newChar the new character to place at {@code index}
         * @return the updated adjacent‑period count
         */
        int update(int index, char newChar) {
            char oldChar = chars[index];
            if (oldChar == newChar) {
                return adjacentPeriodCount; // No change needed
            }

            // 1️⃣ Remove contributions of the old character
            if (oldChar == '.' && index > 0 && chars[index - 1] == '.') {
                adjacentPeriodCount--;
            }
            if (oldChar == '.' && index + 1 < chars.length && chars[index + 1] == '.') {
                adjacentPeriodCount--;
            }

            // 2️⃣ Apply the new character
            chars[index] = newChar;

            // 3️⃣ Add contributions of the new character
            if (newChar == '.' && index > 0 && chars[index - 1] == '.') {
                adjacentPeriodCount++;
            }
            if (newChar == '.' && index + 1 < chars.length && chars[index + 1] == '.') {
                adjacentPeriodCount++;
            }

            return adjacentPeriodCount;
        }
    }

    public static void main(String[] args) throws IOException {
        // ------------------------------------------------------------
        // Input handling (try‑with‑resources guarantees closure)
        // ------------------------------------------------------------
        try (BufferedReader reader = new BufferedReader(
                new InputStreamReader(System.in));
             PrintWriter writer = new PrintWriter(System.out)) {

            // First line: length of the sequence and number of operations
            StringTokenizer tokenizer = new StringTokenizer(reader.readLine());
            int length = Integer.parseInt(tokenizer.nextToken());
            int operations = Integer.parseInt(tokenizer.nextToken());

            // Initial string of characters
            String initial = reader.readLine();
            char[] chars = initial.toCharArray();
            PeriodTracker tracker = new PeriodTracker(chars);

            // Process each operation
            for (int i = 0; i < operations; i++) {
                tokenizer = new StringTokenizer(reader.readLine());
                int pos = Integer.parseInt(tokenizer.nextToken()) - 1; // convert to 0‑based
                char newChar = tokenizer.nextToken().charAt(0);

                int result = tracker.update(pos, newChar);
                writer.println(result);
            }
        }
    }
}

import java.io.BufferedWriter;
import java.io.IOException;
import java.io.InputStream;
import java.io.OutputStream;
import java.io.PrintWriter;
import java.io.Writer;

// Refactored Java program with improved maintainability and readability.

public class Puzzle570C {

    public static void main(String[] args) {
        ProcessInputAndSolve();
    }

    private static void ProcessInputAndSolve() {
        InputStream input = System.in;
        OutputStream output = System.out;

        try (InputReader reader = new InputReader(input);
             OutputWriter writer = new OutputWriter(output)) {
            Puzzle570C_Solver solver = new Puzzle570C_Solver();
            solver.solve(reader);
            writer.flush();
        }
    }

    static class Puzzle570C_Solver {
        public void solve(InputReader reader) {
            int length = reader.nextInt();
            int numQueries = reader.nextInt();
            char[] chars = reader.next().toCharArray();
            int totalDots = 0;
            int groupCount = 0;
            int index = 0;

            // Initial scan to count total dots and groups of consecutive dots.
            while (index < length) {
                if (chars[index] == '.') {
                    groupCount++;
                    while (index < length && chars[index] == '.') {
                        totalDots++;
                        index++;
                    }
                } else {
                    index++;
                }
            }

            // Process each query.
            while (numQueries-- > 0) {
                int pos = reader.nextInt() - 1;
                char repl = reader.nextCharacter();
                char current = chars[pos];

                // Handle replacement logic.
                if (repl != '.') {
                    if (current == '.') {
                        totalDots--;
                        boolean prevIsDot = (pos > 0 && chars[pos - 1] == '.');
                        boolean nextIsDot = (pos < length - 1 && chars[pos + 1] == '.');

                        if (prevIsDot && nextIsDot) {
                            groupCount++;
                        } else if (!prevIsDot && !nextIsDot) {
                            groupCount--;
                        }
                    }
                } else {
                    if (current != '.') {
                        totalDots++;
                        boolean prevIsDot = (pos > 0 && chars[pos - 1] == '.');
                        boolean nextIsDot = (pos < length - 1 && chars[pos + 1] == '.');

                        if (prevIsDot && nextIsDot) {
                            groupCount--;
                        } else if (!prevIsDot && !nextIsDot) {
                            groupCount++;
                        }
                    }
                }

                chars[pos] = repl;
                writer.println(totalDots - groupCount);
            }
        }
    }

    static class InputReader {
        private final InputStream stream;
        private final byte[] buffer = new byte[1024];
        private int currentIndex;
        private int bytesRead;

        public InputReader(InputStream stream) {
            this.stream = stream;
        }

        private int readByte() {
            if (bytesRead == -1) {
                throw new RuntimeException();
            }
            if (currentIndex >= bytesRead) {
                currentIndex = 0;
                bytesRead = stream.read(buffer);
                if (bytesRead <= 0) {
                    return -1;
                }
            }
            return buffer[currentIndex++];
        }

        public int nextInt() {
            int c = readByte();
            while (isWhitespace(c)) {
                c = readByte();
            }
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = readByte();
            }
            int value = 0;
            while (!isWhitespace(c)) {
                value *= 10;
                value += (c - '0');
                c = readByte();
            }
            return value * sign;
        }

        public char nextCharacter() {
            int c;
            do {
                c = readByte();
            } while (isWhitespace(c));
            return (char) c;
        }

        private boolean isWhitespace(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }
    }

    static class OutputWriter {
        private final PrintWriter printWriter;

        public OutputWriter(OutputStream output) {
            this.printWriter = new PrintWriter(new BufferedWriter(
                new OutputStreamWriter(output)));
        }

        public void println(int value) {
            printWriter.println(value);
        }

        public void flush() {
            printWriter.flush();
        }

        public void close() {
            printWriter.close();
        }
    }
}

import java.io.*;
import java.util.StringTokenizer;

/**
 * Fast scanner that reads tokens from standard input.
 */
final class FastScanner {
    private final BufferedReader reader;
    private StringTokenizer tokenizer;

    FastScanner() {
        this.reader = new BufferedReader(new InputStreamReader(System.in));
    }

    /** Returns next token (blocking until one is available). */
    private String nextToken() throws IOException {
        while (tokenizer == null || !tokenizer.hasMoreTokens()) {
            tokenizer = new StringTokenizer(reader.readLine());
        }
        return tokenizer.nextToken();
    }

    /** Convenience wrapper for {@code nextToken()} */
    String next() throws IOException { return nextToken(); }

    int nextInt() throws IOException { return Integer.parseInt(next()); }

    /** Main entry point */
    static void mainPlaceholder() {}
}

/**
 * Encapsulates the mutable character buffer together with the
 * auxiliary statistics (number of '.' characters and number of
 * contiguous '.' groups).  All state changes are performed through
 * well‑named methods, making the logic easy to read and verify.
 */
final class GridState {
    private final char[] cells;
    private int dotCount;      // total number of '.' characters
    private int segmentCount;  // number of maximal contiguous '.' groups

    GridState(char[] source) {
        this.cells = source.clone();
        recomputeStatistics();
    }

    /** Updates internal statistics after a single cell change. */
    void apply(int index, char newChar) {
        char oldChar = cells[index];
        if (oldChar == newChar) {
            return; // nothing to do
        }

        if (oldChar == '.' && newChar != '.') {
            removeDot(index);
        } else if (oldChar != '.' && newChar == '.') {
            addDot(index);
        } else {
            // transition between non‑'.' characters – statistics unchanged
            cells[index] = newChar;
        }
    }

    /** Returns the current value of {@code dotCount - segmentCount}. */
    int answer() {
        return dotCount - segmentCount;
    }

    /** Debug‑friendly representation of the current buffer. */
    @Override
    public String toString() {
        return new String(cells);
    }

    /* --------------------------- private helper methods --------------------------- */

    /** Re‑computes dotCount and segmentCount from scratch (used only on construction). */
    private void recomputeStatistics() {
        dotCount = 0;
        segmentCount = 0;
        for (int i = 0; i < cells.length; i++) {
            if (cells[i] == '.') {
                dotCount++;
                if (i == 0 || cells[i - 1] != '.') {
                    segmentCount++;
                }
            }
        }
    }

    /** Called when a '.' appears at {@code index}. */
    private void addDot(int index) {
        cells[index] = '.';
        dotCount++;

        boolean leftDot = index > 0 && cells[index - 1] == '.';
        boolean rightDot = index + 1 < cells.length && cells[index + 1] == '.';

        // Three possible patterns:
        // 1) both neighbours are dots  -> two groups merge into one  => segmentCount--
        // 2) neither neighbour is dot  -> new isolated group           => segmentCount++
        // 3) exactly one neighbour is dot-> group is simply extended    => segmentCount unchanged
        if (leftDot && rightDot) {
            segmentCount--;
        } else if (!leftDot && !rightDot) {
            segmentCount++;
        }
        // else: change is neutral – nothing to do
    }

    /** Called when a '.' disappears at {@code index}. */
    private void removeDot(int index) {
        boolean leftDot = index > 0 && cells[index - 1] == '.';
        boolean rightDot = index + 1 < cells.length && cells[index + 1] == '.';

        // Before removal we know cells[index] == '.'
        cells[index] = ' '; // placeholder; actual value no longer matters
        dotCount--;

        // After removal the patterns invert:
        // 1) both neighbours are dots  -> one group splits into two      => segmentCount++
        // 2) neither neighbour is dot  -> isolated group disappears       => segmentCount--
        // 3) exactly one neighbour is dot-> group simply shrinks          => segmentCount unchanged
        if (leftDot && rightDot) {
            segmentCount++;
        } else if (!leftDot && !rightDot) {
            segmentCount--;
        }
        // else: change is neutral – nothing to do
    }
}

/**
 * Main driver class – reads input, processes operations and prints results.
 */
public class Main {
    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();

        // ----- input -----------------------------------------------------------
        final int n = fs.nextInt();          // (unused – kept for API compatibility)
        final int m = fs.nextInt();          // number of operations
        char[] buffer = fs.next().toCharArray(); // initial string of length n

        GridState grid = new GridState(buffer);
        StringBuilder output = new StringBuilder();

        // ----- process each operation -----------------------------------------
        for (int i = 0; i < m; i++) {
            int idx = fs.nextInt() - 1;        // convert to 0‑based index
            char newChar = fs.next().charAt(0);

            grid.apply(idx, newChar);
            output.append(grid.answer()).append('\n');
        }

        System.out.print(output);
    }
}

