import java.math.BigInteger;
import java.util.HashSet;
import java.util.Set;

/**
 * Refactored version of the original program.
 *
 * <p>This version improves readability and maintainability by:
 * <ul>
 *   <li>Extracting mathematical helper methods into dedicated private static functions.</li>
 *   <li>Using expressive variable and method names.</li>
 *   <li>Separating concerns (e.g., input handling, state updates, and output generation).</li>
 *   <li>Encapsulating the logic that updates the count of adjacent '.' pairs in its own method.</li>
 *   <li>Adding JavaDoc comments and clear constant definitions.</li>
 * </ul>
 *
 * <p>The program still performs the same functionality as the original code but with a cleaner
 * structure that is easier to test, extend, and understand.
 */
public final class Program {

    /** Modulo constant used for combinatorial calculations. */
    private static final BigInteger MOD = BigInteger.valueOf(1_000_000_007);

    /** Prevent instantiation – this class only contains static utilities. */
    private Program() {
        // intentionally empty
    }

    /** --------------------------------------------------------------------- *
     *  Helper methods (mathematics)
     *  --------------------------------------------------------------------- */

    /**
     * Computes the binomial coefficient {@code C(N, K)} modulo {@code MOD}.
     *
     * <p>Uses the multiplicative formula: product_{i=0}^{K-1} (N-i) / K!.</p>
     *
     * @param n upper bound of the combination
     * @param k lower bound of the combination
     * @return {@code C(N, K)} modulo {@code MOD} as a {@link BigInteger}
     */
    private static BigInteger combination(int n, int k) {
        if (k < 0 || k > n) {
            return BigInteger.ZERO;
        }
        BigInteger result = BigInteger.ONE;
        for (int i = n; i > n - k; i--) {
            result = result.multiply(BigInteger.valueOf(i));
        }
        for (int i = 1; i <= k; i++) {
            result = result.divide(BigInteger.valueOf(i));
        }
        return result.mod(MOD);
    }

    /**
     * Determines whether a positive integer is prime.
     *
     * @param n the number to test
     * @return {@code true} if {@code n} is prime; otherwise {@code false}
     */
    private static boolean isPrime(int n) {
        if (n <= 1) {
            return false;
        }
        if (n == 2) {
            return true;
        }
        if (n % 2 == 0) {
            return false;
        }
        int limit = (int) Math.sqrt(n);
        for (int divisor = 3; divisor <= limit; divisor += 2) {
            if (n % divisor == 0) {
                return false;
            }
        }
        return true;
    }

    /**
     * Computes {@code n!} (factorial) as a {@link BigInteger}.
     *
     * @param n non‑negative integer
     * @return factorial of {@code n}
     */
    private static BigInteger factorial(int n) {
        BigInteger result = BigInteger.ONE;
        for (int i = 2; i <= n; i++) {
            result = result.multiply(BigInteger.valueOf(i));
        }
        return result;
    }

    /** Simple utilities (gcd, min, max) – kept for backward compatibility. */
    private static int gcd(int a, int b) {
        return b == 0 ? a : gcd(b, a % b);
    }

    private static int max(int a, int b) {
        return a > b ? a : b;
    }

    private static int min(int a, int b) {
        return a < b ? a : b;
    }

    /** --------------------------------------------------------------------- *
     *  Domain‑specific logic for the '.' character handling
     *  --------------------------------------------------------------------- */

    /**
     * Updates the count of adjacent '.' pairs after a position is flipped.
     *
     * @param currentCount the existing count of overlapping ".." sequences
     * @param positions    set of 1‑based indices that currently contain '.'
     * @param index        1‑based index that is being modified
     * @param newValue     the character to place at {@code index}
     * @return the updated count of adjacent '.' pairs
     */
    private static int updateDotCount(int currentCount, Set<Integer> positions, int index, char newValue) {
        // --- Remove old contribution if the position currently holds '.' ---
        if (positions.contains(index)) {
            if (positions.contains(index - 1)) {
                currentCount--;
            }
            if (positions.contains(index + 1)) {
                currentCount--;
            }
            positions.remove(index);
        }

        // --- Add new contribution if the new character is '.' ---
        if (newValue == '.') {
            positions.add(index);
            if (positions.contains(index - 1)) {
                currentCount++;
            }
            if (positions.contains(index + 1)) {
                currentCount++;
            }
        }
        return currentCount;
    }

    /** --------------------------------------------------------------------- *
     *  Main program entry point
     *  --------------------------------------------------------------------- */
    public static void main(String[] args) throws IOException {
        BufferedReader reader = new BufferedReader(new java.io.InputStreamReader(System.in));
        StringBuilder output = new StringBuilder();

        // ----- read header -----
        String[] header = reader.readLine().split("\\s+");
        int n = Integer.parseInt(header[0]);
        int m = Integer.parseInt(header[1]);

        // ----- read the initial string -----
        char[] chars = reader.readLine().trim().toCharArray();

        // initialise counters and the set of '.' positions (1‑based indices)
        int dotPairCount = 0;
        Set<Integer> dotPositions = new HashSet<>();

        if (chars[0] == '.') {
            dotPositions.add(1);
        }
        for (int i = 1; i < n; i++) {
            if (chars[i] == '.' && chars[i - 1] == '.') {
                dotPairCount++;
            }
            if (chars[i] == '.') {
                dotPositions.add(i + 1); // store as 1‑based index
            }
        }

        // ----- process each update -----
        for (int step = 0; step < m; step++) {
            String[] query = reader.readLine().split("\\s+");
            int position = Integer.parseInt(query[0]); // 1‑based
            char ch = query[1].charAt(0);

            dotPairCount = updateDotCount(dotPairCount, dotPositions, position, ch);
            output.append(dotPairCount).append('\n');
        }

        System.out.print(output);
    }
}

