/**
 * Refactored version of the original program.
 * <p>
 *   • Responsibilities are split into small, well‑named methods.
 *   • Meaningful variable and class names improve readability.
 *   • Complex logic (the calculation of the answer) is isolated in its own method.
 *   • Try‑with‑resources ensures the input stream is closed cleanly.
 *   • The answer is recomputed in a straightforward way, removing duplicated
 *     branching code from the original version.
 * </p>
 */
public class Major {

    /**
     * Holds the mutable character buffer and the current answer value.
     * <p>
     *   The answer is defined as the sum of {@code (runLength‑1)} for every
     *   maximal consecutive '.' sequence in the buffer.
     * </p>
     */
    private static final class State {
        private final StringBuilder buffer;

        /** Current answer value for the buffer. */
        int answer;

        State(StringBuilder buffer) {
            this.buffer = buffer;
            this.answer = computeAnswer(buffer);
        }

        /**
         * Re‑computes the answer based on the current contents of {@code buffer}.
         *
         * @return the new answer value
         */
        private static int computeAnswer(StringBuilder sb) {
            int ans = 0;
            int runLen = 0;

            for (int i = 0; i < sb.length(); i++) {
                if (sb.charAt(i) == '.') {
                    runLen++;
                } else {
                    if (runLen > 0) {
                        ans += runLen - 1;
                        runLen = 0;
                    }
                }
            }
            if (runLen > 0) {
                ans += runLen - 1;
            }
            return ans;
        }

        /**
         * Updates the character at {@code index} to {@code newChar} and refreshes
         * the stored answer.
         *
         * @param index   zero‑based position to modify
         * @param newChar the character to write
         */
        void update(int index, char newChar) {
            char oldChar = buffer.charAt(index);
            if (oldChar == newChar) {
                // No change → answer stays the same.
                return;
            }

            buffer.setCharAt(index, newChar);
            // Simpler than trying to adjust the answer incrementally.
            this.answer = computeAnswer(buffer);
        }
    }

    public static void main(String[] args) throws IOException {
        /* --------------------------------------------------------------
         *  Input handling
         * -------------------------------------------------------------- */
        try (BufferedReader reader = new BufferedReader(
                new InputStreamReader(System.in))) {

            // First line: n (length of the string) and m (number of queries)
            String firstLine = reader.readLine();
            StringTokenizer tokenizer = new StringTokenizer(firstLine);
            int length = Integer.parseInt(tokenizer.nextToken());
            int queries = Integer.parseInt(tokenizer.nextToken());

            // Initial string
            StringBuilder initial = new StringBuilder(reader.readLine());

            State state = new State(initial);
            StringBuilder output = new StringBuilder();

            // Process each query
            for (int q = 0; q < queries; q++) {
                String queryLine = reader.readLine();
                if (queryLine == null || queryLine.isBlank()) {
                    continue;   // skip empty lines (protective)
                }

                tokenizer = new StringTokenizer(queryLine);
                int pos = Integer.parseInt(tokenizer.nextToken()) - 1; // convert to 0‑based
                char newChar = tokenizer.nextToken().charAt(0);

                state.update(pos, newChar);
                output.append(state.answer).append('\n');
            }

            /* --------------------------------------------------------------
             *  Output
             * -------------------------------------------------------------- */
            System.out.print(output);
        }
    }
}

