/**
 * Replacement – reads a string of length {@code n} and a series of {@code m}
 * update queries. After each query the program prints the current value of
 * {@code sum}, which represents the total number of “extra” dots in all maximal
 * sequences of consecutive dots.
 *
 * <p>Refactoring goals:
 * <ul>
 *   <li>Separate concerns – input handling, state management and output formatting
 *       are split into dedicated methods.</li>
 *   <li>Use meaningful names and avoid duplicated code.</li>
 *   <li>Encapsulate the state (the character array and the running {@code sum})
 *       in a small helper class.</li>
 *   <li>Handle the special cases {@code n == 1} and {@code n == 2} exactly as
 *       the original program did, but with clearer intent.</li>
 * </ul>
 */
public class Replacement {

    /** Helper that stores the mutable character sequence and the current {@code sum}. */
    private static final class State {
        /** The character buffer (initially contains the first input line). */
        final char[] buf;
        /** The current value of {@code sum}. */
        int sum;

        State(char[] buf) {
            this.buf = buf;
        }

        /** Re‑calculate the whole {@code sum} from scratch – used only for {@code n <= 2}. */
        void recomputeSum() {
            sum = 0;
            int run = 0;
            for (char c : buf) {
                if (c == '.') {
                    run++;
                } else {
                    if (run > 0) {
                        sum += Math.max(0, run - 1);
                    }
                    run = 0;
                }
            }
            if (run > 0) {
                sum += Math.max(0, run - 1);
            }
        }

        /** Adjust {@code sum} when the character at {@code pos} is updated to {@code newC}. */
        void update(int pos, char newC) {
            char old = buf[pos];
            if (old == newC) {
                return; // nothing to do
            }

            // Remove the contribution of the old value
            if (old == '.') {
                subtractOldContribution(pos);
            }

            // Apply the new value
            buf[pos] = newC;
            if (newC == '.') {
                addNewContribution(pos);
            } else {
                // old was '.' – we already subtracted its contribution
                // nothing extra to add
            }
        }

        /** Subtract the contribution of a '.' at position {@code pos}. */
        private void subtractOldContribution(int pos) {
            // Removing a '.' may split a run or shorten it.
            int left = pos - 1 >= 0 ? buf[pos - 1] : ' ';
            int right = pos + 1 < buf.length ? buf[pos + 1] : ' ';
            if (left == '.' && right == '.') {
                sum -= 2;
            } else if (left == '.' || right == '.') {
                sum -= 1;
            }
        }

        /** Add the contribution of a newly placed '.' at position {@code pos}. */
        private void addNewContribution(int pos) {
            int left = pos - 1 >= 0 ? buf[pos - 1] : ' ';
            int right = pos + 1 < buf.length ? buf[pos + 1] : ' ';
            if (left == '.' && right == '.') {
                sum += 2;
            } else if (left == '.' || right == '.') {
                sum += 1;
            }
        }
    }

    /** Simple container for the tokens read from a line. */
    private static final class Tokenizer {
        private final StringTokenizer tokenizer;

        Tokenizer(String line) {
            this.tokenizer = new StringTokenizer(line);
        }

        /** Returns true if another token exists. */
        boolean hasMoreTokens() {
            return tokenizer.hasMoreTokens();
        }

        /** Returns the next token as an integer. */
        int nextInt() {
            return Integer.parseInt(tokenizer.nextToken());
        }

        /** Returns the next token as a single character string and consumes it. */
        char nextChar() {
            return tokenizer.nextToken().charAt(0);
        }
    }

    public static void main(String[] args) throws IOException {
        /* ---------- 1. INPUT --------------------------------------------------- */
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));

        // first line: n m
        Tokenizer firstLine = new Tokenizer(reader.readLine());
        int n = firstLine.nextInt();               // length of the string
        int m = firstLine.nextInt();               // number of queries

        // second line: the initial string
        char[] initial = reader.readLine().toCharArray();

        /* ---------- 2. STATE INITIALISATION ----------------------------------- */
        State state = new State(initial);
        state.recomputeSum();                     // initial value of sum

        /* ---------- 3. OUTPUT BUFFER ------------------------------------------- */
        StringBuilder output = new StringBuilder();

        /* ---------- 4. PROCESS QUERIES ---------------------------------------- */
        for (int q = 0; q < m; q++) {
            // each query: index j (1‑based) and a new character c
            Tokenizer queryTokens = new Tokenizer(reader.readLine());
            int index = queryTokens.nextInt() - 1; // convert to 0‑based
            char newChar = queryTokens.nextChar();

            // Special handling required only when n == 1 or n == 2
            if (n == 1) {
                output.append(state.sum).append('\n');
                continue;
            }
            if (n == 2) {
                // The original program printed "1" only when both characters are '.'
                output.append((initial[0] == '.' && initial[1] == '.') ? "1\n" : "0\n");
                continue;
            }

            // General case (n >= 3)
            State before = new State(state.buf.clone()); // keep a snapshot for debugging if needed
            state.update(index, newChar);

            // Print the sum after the update
            output.append(state.sum).append('\n');

            // Debugging aid – uncomment to see the buffer after each change
            // System.out.println("After query " + q + ": " + new String(state.buf));
        }

        /* ---------- 5. FINAL OUTPUT -------------------------------------------- */
        System.out.print(output.toString());
    }
}

