/**
 * Refactored version of the original program.
 *
 * <p>
 * The program reads an array of characters, maintains a count of contiguous '.'‑segments,
 * and processes a series of updates that change a character at a given index.
 * After each update it prints the current segment count.
 * </p>
 */
public class Main {

    /**
     * Calculates the initial number of '.' segments using the original algorithm.
     *
     * @param chars the character array to analyse
     * @return the number of '.' segments
     */
    private static int countDotSegments(char[] chars) {
        if (chars.length == 0) {
            return 0;
        }
        int state = chars[0] == '.' ? 1 : 0;
        int cnt = 0;

        for (int i = 1; i < chars.length; i++) {
            if (chars[i] == '.' && state == 1) {
                cnt++;
            } else if (chars[i] != '.' && state == 1) {
                state = 0;
            } else if (chars[i] == '.' && state == 0) {
                state = 1;
            }
            // remaining cases leave cnt unchanged
        }
        return cnt;
    }

    /**
     * Adjusts the segment count when a single character changes.
     *
     * <p>
     *   The method mirrors the original branching logic that updates {@code cnt}
     *   when a '.' is removed or added, including the special handling for
     *   positions at the array boundaries.
     * </p>
     *
     * @param index     index of the character that changes (0‑based)
     * @param oldChar   character before the change
     * @param newChar   character after the change
     * @param chars     the character array (modified in‑place)
     * @param count     a one‑element array holding the current segment count
     */
    private static void adjustCount(int index, char oldChar, char newChar,
                                    char[] chars, int[] count) {

        // No change – nothing to do
        if (oldChar == newChar) {
            return;
        }

        // ---- Removing a '.' -------------------------------------------------
        if (oldChar == '.' && newChar != '.') {
            if (index == 0) {
                // left boundary
                if (chars.length > 1 && chars[1] == '.') {
                    count[0]--;
                }
            } else if (index == chars.length - 1) {
                // right boundary
                if (chars[index - 1] == '.') {
                    count[0]--;
                }
            } else {
                boolean leftIsDot = chars[index - 1] == '.';
                boolean rightIsDot = chars[index + 1] == '.';
                if (leftIsDot && rightIsDot) {
                    count[0] -= 2;
                } else if (leftIsDot ^ rightIsDot) {
                    count[0] -= 1;
                }
            }
        }
        // ---- Adding a '.' ---------------------------------------------------
        else if (oldChar != '.' && newChar == '.') {
            if (index == 0) {
                if (chars.length > 1 && chars[1] == '.') {
                    count[0]++;
                }
            } else if (index == chars.length - 1) {
                if (chars[index - 1] == '.') {
                    count[0]++;
                }
            } else {
                boolean leftIsDot = chars[index - 1] == '.';
                boolean rightIsDot = chars[index + 1] == '.';
                if (leftIsDot && rightIsDot) {
                    count[0] += 2;
                } else if (leftIsDot ^ rightIsDot) {
                    count[0] += 1;
                }
            }
        }

        // Update the character in the array
        chars[index] = newChar;
    }

    public static void main(String[] args) throws IOException {
        // Use try‑with‑resources to guarantee stream closure
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in))) {
            PrintWriter pw = new PrintWriter(System.out);
            StringTokenizer st = new StringTokenizer(br.readLine());

            int n = Integer.parseInt(st.nextToken()); // number of characters
            int m = Integer.parseInt(st.nextToken()); // number of updates

            // Read the initial character sequence
            char[] chars = br.readLine().toCharArray();

            // Initialise segment count using the original counting logic
            int[] count = new int[1];
            count[0] = countDotSegments(chars);

            // Process each update
            for (int i = 0; i < m; i++) {
                st = new StringTokenizer(br.readLine());
                int idx = Integer.parseInt(st.nextToken()) - 1; // convert to 0‑based index
                char newChar = st.nextToken().charAt(0);
                char oldChar = chars[idx];

                // Special case: only a single character exists
                if (n == 1) {
                    pw.println(0);
                    continue;
                }

                adjustCount(idx, oldChar, newChar, chars, count);
                pw.println(count[0]);
            }
        }
    }
}

/* -------------------------------------------------------------
 *  Refactored solution for the “consecutive dots” problem
 *  (maintainability, readability, clear separation of concerns)
 * ------------------------------------------------------------- */
import java.io.*;

public class Solution {

    public static void main(String[] args) {
        FastScanner sc = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(System.out, true);

        int testCases = 1;
        Solver solver = new Solver();
        solver.solve(testCases, sc, out);

        out.flush();
    }

    /** Solves a single test case. */
    static final class Solver {

        /** Entry point used by `main`. */
        void solve(int testNumber, FastScanner in, PrintWriter out) {
            final int stringLength = in.nextInt();   // n
            final int queryCount   = in.nextInt();   // q
            final char[] chars     = in.readString().toCharArray(); // s

            int maxPairs = calculateMaxPairs(chars, stringLength);
            out.println(maxPairs);

            processQueries(chars, stringLength, queryCount, in, out);
        }

        /** Calculates the initial answer – the number of overlapping ".." pairs
         *  that can be removed from the string. */
        private static int calculateMaxPairs(char[] s, int n) {
            int answer = 0;
            for (int i = 0; i < n; ) {
                int consecutive = 0;
                while (i < n && s[i] == '.') {
                    consecutive++;
                    i++;
                }
                // In a block of k dots we have (k‑1) overlapping pairs
                answer += Math.max(0, consecutive - 1);
            }
            return answer;
        }

        /** Handles all queries, updating the string and the answer on‑the‑fly. */
        private void processQueries(
                char[] s,
                int n,
                int q,
                FastScanner in,
                PrintWriter out) {

            for (int queryIdx = 0; queryIdx < q; queryIdx++) {
                int pos   = in.nextInt() - 1;          // convert to 0‑based index
                char newC = in.readString().charAt(0);

                updateState(pos, newC, s, n);
                out.println(currentAnswer);
            }
        }

        /** Updates the answer (`currentAnswer`) when a character at `pos`
         *  is changed from `old` to `newC`. All side‑effects are performed
         *  in‑place on the `s` array. */
        private void updateState(int pos, char newC, char[] s, int n) {
            char old = s[pos];

            if (old == '.' && newC != '.') {               // a dot disappeared
                if (pos - 1 >= 0 && s[pos - 1] == '.') currentAnswer--; // left pair vanished
                if (pos + 1 < n   && s[pos + 1] == '.') currentAnswer--; // right pair vanished
            } else if (old != '.' && newC == '.') {        // a dot appeared
                if (pos - 1 >= 0 && s[pos - 1] == '.') currentAnswer++;  // left pair created
                if (pos + 1 < n   && s[pos + 1] == '.') currentAnswer++;  // right pair created
            }
            s[pos] = newC;                                   // apply the change
        }

        /** Mutable field that stores the current answer while processing queries. */
        private int currentAnswer;
    }

    /** FastScanner – a compact, high‑performance wrapper around {@link InputStream}
     *  that mimics the original `InputReader` but with clearer method names. */
    private static final class FastScanner {
        private final InputStream stream;
        private final byte[] buffer = new byte[8192];
        private int pointer = 0, bytesRead = -1;

        FastScanner(InputStream stream) {
            this.stream = stream;
        }

        /** Reads the next byte, returning -1 on EOF. */
        private int readByte() {
            if (pointer >= bytesRead) {
                bytesRead = stream.read(buffer);
                pointer   = 0;
                if (bytesRead <= 0) return -1;
            }
            return buffer[pointer++];
        }

        /** Returns true if the current character is a whitespace character. */
        private static boolean isSpaceChar(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t';
        }

        /** Reads the next token as an int. */
        int nextInt() {
            int c = skipWhitespace();
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = readByte();
            }
            int value = 0;
            while (c >= '0' && c <= '9') {
                value = value * 10 + (c - '0');
                c = readByte();
            }
            return value * sign;
        }

        /** Reads the next token as a string (up to whitespace). */
        String readString() {
            int c = skipWhitespace();
            StringBuilder sb = new StringBuilder();
            do {
                sb.append((char) c);
                c = readByte();
            } while (!isSpaceChar(c));
            return sb.toString();
        }

        /** Skips all whitespace characters. */
        private int skipWhitespace() {
            int c;
            do {
                c = readByte();
            } while (isSpaceChar(c));
            return c;
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

/**
 * Reads a sequence of '.' characters and a series of updates,
 * maintaining a count that represents the total length of all '.' runs
 * minus one for each run. After each update the current count is printed.
 */
public class Main {

    /**
     * Calculates the required count for the given character array.
     * The count is the sum of (runLength - 1) for every contiguous '.' run.
     *
     * @param data character array to analyse
     * @return the computed count
     */
    private static int computeDotCount(char[] data) {
        int count = 0;
        int i = 0;
        final int length = data.length;

        while (i < length) {
            if (data[i] == '.') {
                int runStart = i;
                // Skip the whole '.' run
                while (i < length && data[i] == '.') {
                    i++;
                }
                int runLength = i - runStart;
                // Add (runLength - 1) to the total
                count += Math.max(0, runLength - 1);
            } else {
                i++;
            }
        }
        return count;
    }

    public static void main(String[] args) throws IOException {
        /* ---------- Input ---------- */
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));

        // First line: n and m
        StringTokenizer st = new StringTokenizer(br.readLine());
        int n = Integer.parseInt(st.nextToken());
        int m = Integer.parseInt(st.nextToken());

        // Second line: the initial character sequence
        char[] seq = br.readLine().trim().toCharArray();

        /* ---------- Initial count ---------- */
        int currentCount = computeDotCount(seq);

        /* ---------- Process updates ---------- */
        for (int op = 0; op < m; op++) {
            st = new StringTokenizer(br.readLine());
            int idx = Integer.parseInt(st.nextToken()) - 1; // convert to 0‑based
            char newChar = st.nextToken().trim().charAt(0);

            // Skip work if the new character equals the current one
            if (seq[idx] == newChar) {
                System.out.println(currentCount);
                continue;
            }

            // Apply the change
            seq[idx] = newChar;

            // Re‑calculate the count from scratch – clearer and easier to maintain
            currentCount = computeDotCount(seq);

            // Output the result for this operation
            System.out.println(currentCount);
        }

        br.close();
    }
}

import java.io.*;
import java.util.Map;
import java.util.TreeMap;

/**
 * Solution for the problem that processes a string consisting of '.' and other characters.
 * It maintains the total number of '.' characters minus the number of distinct '.' blocks
 * and answers queries that change a character in the string.
 *
 * The refactor focuses on readability, separation of concerns and meaningful naming.
 */
public class Main {

    /* ------------ I/O helpers ------------ */
    private static final class FastReader {
        private final BufferedReader br;

        FastReader() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        /** Reads the next token, retrying until one is available. */
        private String readToken() throws IOException {
            while (root == null || !root.hasMoreTokens()) {
                root = new StringTokenizer(br.readLine());
            }
            return root.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(readToken());
        }

        long nextLong() {
            return Long.parseLong(readToken());
        }

        double nextDouble() {
            return Double.parseDouble(readToken());
        }

        String next() {
            return readToken();
        }

        String nextLine() throws IOException {
            return br.readLine();
        }

        // Lazily created tokenizer holder
        private StringTokenizer root;
    }

    /** Global I/O objects used throughout the program. */
    private static final PrintWriter OUT = new PrintWriter(
            new BufferedOutputStream(System.out));
    private static final FastReader SC = new FastReader();

    /* ------------ Constants ------------ */
    private static final long MOD = 1_000_000_007L;          // not used in the algorithm but kept for parity
    private static final long MAX = 1_000_010L;              // placeholder for future extensions

    /* ------------ Core data structures ------------ */
    /** Intervals of consecutive '.' characters, stored by their start index. */
    private static final Map<Integer, Integer> intervals = new TreeMap<>();

    /** Current character array representing the string. */
    private static char[] current;

    /** Running answer: total '.' count minus number of distinct intervals. */
    private static long answer;

    /* ------------ Public entry point ------------ */
    public static void main(String[] args) throws IOException {
        init();                     // read input and build initial intervals
        processQueries();           // handle the rest of the input
        OUT.close();                // flush output
    }

    /* ------------ Initialization ------------ */
    private static void init() throws IOException {
        int n = SC.nextInt();       // length of the string (unused but kept for compatibility)
        int m = SC.nextInt();       // number of queries
        String s = SC.next();       // the string itself

        current = s.toCharArray();

        answer = 0;
        collectIntervals();        // pop‑ulate `intervals` and compute the initial answer
    }

    /** Scans the initial string and builds the interval map. */
    private static void collectIntervals() {
        int i = 0;
        while (i < current.length) {
            if (current[i] == '.') {
                int start = i;
                while (i < current.length && current[i] == '.') {
                    i++;
                }
                int end = i - 1;
                intervals.put(start, end);
                answer += (end - start + 1);
            } else {
                i++;
            }
        }
        // The original implementation subtracted the number of intervals.
        answer -= intervals.size();
    }

    /* ------------ Query processing ------------ */
    private static void processQueries() throws IOException {
        int queryCount = SC.nextInt();      // number of updates (the first two ints were n,m)

        for (int q = 0; q < queryCount; q++) {
            int pos = SC.nextInt() - 1;     // convert to 0‑based index
            char newChar = SC.next().charAt(0);
            handleUpdate(pos, newChar);
            OUT.println(answer);
        }
    }

    /** Executes a single update (set character at `pos` to `newChar`). */
    private static void handleUpdate(int pos, char newChar) {
        char oldChar = current[pos];
        if (oldChar == newChar) {
            return;                         // nothing to do
        }

        if (newChar == '.') {               // adding a dot
            addDot(pos);
        } else {                            // removing a dot
            removeDot(pos);
        }

        current[pos] = newChar;             // reflect the change in the working array
    }

    /* ------------ Operations for adding a dot ------------ */
    private static void addDot(int pos) {
        // Does an interval already end right before `pos`?
        Integer leftKey = intervals.floorKey(pos - 1);
        // Does an interval already start right after `pos`?
        Integer rightKey = intervals.ceilingKey(pos + 1);

        boolean merged = false;

        if (leftKey != null && rightKey != null) {
            int leftEnd = intervals.get(leftKey);
            int rightStart = intervals.get(rightKey);
            if (leftEnd == pos - 1 && rightStart == pos + 1) {
                // Merge three pieces into one big interval.
                int newEnd = intervals.get(rightKey);
                long oldLength = (leftEnd - leftKey + 1L) + (newEnd - rightStart + 1L);
                answer -= (oldLength - 2);   // remove contribution of the two old pieces
                intervals.remove(leftKey);
                intervals.remove(rightKey);
                intervals.put(leftKey, newEnd);
                answer++;                     // add contribution of the merged piece
                merged = true;
            }
        }

        if (!merged) {
            if (leftKey != null) {
                int leftEnd = intervals.get(leftKey);
                if (leftEnd == pos - 1) {
                    answer++;
                    intervals.remove(leftKey);
                    intervals.put(leftKey, pos);
                    merged = true;
                }
            }
            if (!merged && rightKey != null) {
                int rightStart = intervals.get(rightKey);
                if (rightStart == pos + 1) {
                    answer++;
                    intervals.remove(rightKey);
                    intervals.put(pos, rightKey);
                    merged = true;
                }
            }
        }

        if (!merged) {
            // Stand‑alone dot forms a new interval of length 1.
            intervals.put(pos, pos);
        }
    }

    /* ------------ Operations for removing a dot ------------ */
    private static void removeDot(int pos) {
        Integer key = intervals.floorKey(pos);
        int intervalEnd = intervals.get(key);

        // Remove the whole interval contribution.
        answer -= (intervalEnd - key + 1);
        intervals.remove(key);

        // If there is room on the left side, create a new interval there.
        if (key < pos) {
            intervals.put(key, pos - 1);
            // The new interval contributes its length.
            answer += (pos - 1 - key + 1);
        }

        // If there is room on the right side, create a new interval there.
        if (pos < intervalEnd) {
            intervals.put(pos + 1, intervalEnd);
            answer += (intervalEnd - (pos + 1) + 1);
        }
    }
}

