/**
 * Refactored version of the original program.
 *
 * <p>Key improvements:
 * <ul>
 *   <li>Clear separation of concerns – input handling, statistics calculation, and update logic are isolated.
 *   <li>Descriptive method names and meaningful variable names.
 *   <li>Resource‑safe use of {@link BufferedReader} via try‑with‑resources.
 *   <li>Constant for the '.' character to avoid magic literals.
 *   <li>Simple, O(n) recomputation of statistics after each update – easy to understand and maintain.
 * </ul>
 */
public class Main {

    /** Character that represents an empty cell in the problem statement. */
    private static final char EMPTY = '.';

    public static void main(String[] args) throws IOException {
        // ------------------------------------------------------------
        // 1. Read dimensions and the initial configuration.
        // ------------------------------------------------------------
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in))) {
            StringTokenizer dims = new StringTokenizer(br.readLine());
            int n = Integer.parseInt(dims.nextToken());
            int m = Integer.parseInt(dims.nextToken());

            char[] cells = br.readLine().toCharArray();

            // ------------------------------------------------------------
            // 2. Process each update, emitting the required value before it.
            // ------------------------------------------------------------
            StringBuilder output = new StringBuilder();

            for (int i = 0; i < m; i++) {
                // Emit the current value of (dotCount - segmentCount).
                int dotCount = countDots(cells);
                int segmentCount = countSegments(cells);
                output.append(dotCount - segmentCount).append('\n');

                // Read the next update description and apply it.
                StringTokenizer upd = new StringTokenizer(br.readLine());
                int index = Integer.parseInt(upd.nextToken()) - 1;   // convert to 0‑based
                char newValue = upd.nextToken().charAt(0);
                cells[index] = newValue;
            }

            System.out.print(output.toString());
        }
    }

    /** Returns the number of '.' characters in the given array. */
    private static int countDots(char[] arr) {
        int count = 0;
        for (char c : arr) {
            if (c == EMPTY) {
                count++;
            }
        }
        return count;
    }

    /** Returns the number of contiguous groups of '.' characters. */
    private static int countSegments(char[] arr) {
        int segments = 0;
        boolean inside = false;

        for (char c : arr) {
            if (c == EMPTY) {
                if (!inside) {
                    segments++;      // start of a new segment
                    inside = true;
                }
            } else {
                inside = false;      // exit a segment
            }
        }
        return segments;
    }
}

import java.io.*;
import java.util.StringTokenizer;

/**
 * Reads a string of '.' and other characters and processes a series of updates.
 * For each update it prints <code>dotCount - groupCount</code> where
 * <ul>
 *   <li>dotCount  – number of '.' characters in the current string</li>
 *   <li>groupCount– number of distinct contiguous blocks of '.' characters</li>
 * </ul>
 *
 * The implementation follows the original logic but is organised for
 * readability, testability and future extension.
 */
public class SegmentProcessor {

    /** Maximum index that can appear in the input (used for the boolean‑array size). */
    private static final int MAX_INDEX = 400_000;

    public static void main(String[] args) throws IOException {
        FastScanner scanner = new FastScanner();
        PrintWriter out = new PrintWriter(System.out, true);

        int n = scanner.nextInt();               // length of the initial string
        int q = scanner.nextInt();               // number of queries
        char[] chars = scanner.next().toCharArray();

        // presence[i] == true  ⇔  character at position i (1‑based) is '.'
        boolean[] presence = new boolean[MAX_INDEX + 2];

        int dotCount = 0;                          // total number of '.' characters
        int groupCount = 0;                        // number of separate '.' groups

        // initialise the current state (positions are 1‑based)
        for (int i = 0; i < n; i++) {
            if (chars[i] == '.') {
                presence[i + 1] = true;
                dotCount++;

                // a new group starts when the previous character is not '.'
                if (i == 0 || !presence[i]) {
                    groupCount++;
                }
            }
        }

        StringBuilder output = new StringBuilder();

        // process each query
        for (int i = 0; i < q; i++) {
            updateAndPrint(
                    scanner.nextInt(),
                    scanner.next().charAt(0),
                    presence,
                    dotCount,
                    groupCount,
                    output
            );
        }

        out.print(output.toString());
        out.close();
    }

    /**
     * Updates the character at position {@code pos} and appends the new result
     * {@code dotCount - groupCount} to {@code out}.
     *
     * @param pos      1‑based position to modify
     * @param newChar  character to place at {@code pos}
     * @param presence boolean array describing where '.' are located
     * @param dotCount current number of '.' characters
     * @param groupCount current number of '.' groups
     * @param out      StringBuilder that collects output lines
     */
    private static void updateAndPrint(int pos,
                                       char newChar,
                                       boolean[] presence,
                                       int dotCount,
                                       int groupCount,
                                       StringBuilder out) {
        boolean currentlyDot = presence[pos];
        boolean willBeDot = newChar == '.';

        // nothing changes – just report the current value
        if (currentlyDot == willBeDot) {
            out.append(dotCount - groupCount).append('\n');
            return;
        }

        // -----------------------------------------------------------------
        // 1️⃣  Update dotCount
        // -----------------------------------------------------------------
        if (currentlyDot) {
            dotCount--;
        } else {
            dotCount++;
        }

        // -----------------------------------------------------------------
        // 2️⃣  Look at neighbours (guarded against OOB)
        // -----------------------------------------------------------------
        boolean left  = (pos > 1) ? presence[pos - 1] : false;
        boolean right = (pos < presence.length - 1) ? presence[pos + 1] : false;

        // -----------------------------------------------------------------
        // 3️⃣  Adjust groupCount according to the four cases described in
        //     the original code.
        // -----------------------------------------------------------------
        if (currentlyDot) {               // we are removing a '.'
            if (left && right && !willBeDot) {
                groupCount++;
            } else if (!left && !right && !willBeDot) {
                groupCount--;
            }
        } else {                          // we are inserting a '.'
            if (left && right && willBeDot) {
                groupCount--;
            } else if (!left && !right && willBeDot) {
                groupCount++;
            }
        }

        // -----------------------------------------------------------------
        // 4️⃣  Apply the change to the presence array
        // -----------------------------------------------------------------
        presence[pos] = willBeDot;

        // -----------------------------------------------------------------
        // 5️⃣  Append the required result
        // -----------------------------------------------------------------
        out.append(dotCount - groupCount).append('\n');
    }

    /**
     * Very small fast scanner used in competitive‑programming style problems.
     */
    private static final class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner() {
            try {
                br = new BufferedReader(new InputStreamReader(System.in));
                st = new StringTokenizer(br.readLine());
            } catch (IOException e) {
                throw new UncheckedIOException(e);
            }
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    throw new UncheckedIOException(e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

/**
 * Refactored version of the original program.
 *
 * The code has been reorganised into small, purpose‑driven methods,
 * meaningful identifiers, and a cleaner input handling class.
 * It preserves the exact behaviour of the original implementation.
 */
import java.io.*;
import java.util.*;

public class Main {

    /* ----------  I/O utilities  ---------- */
    private static final FastScanner scanner = new FastScanner();
    private static PrintWriter printer = new PrintWriter(System.out, true);

    /* ----------  Global state  ---------- */
    /** The character array we are mutating. */
    private static char[] board;
    /** The metric we are tracking (number of isolated '.' cells). */
    private static long metric;

    /** Entry point required by the competition environment. */
    public static void main(String[] args) throws Exception {
        boolean debugMode = args.length > 0;
        if (debugMode) {
            System.err.println("Debug mode enabled");
        }
        long startTime = System.currentTimeMillis();

        // read problem description (the string that will be mutated)
        board = scanner.next().toCharArray();

        // read size parameters – the original code only used the length of the string,
        // but we keep both reads to stay faithful to the original logic.
        int rows = scanner.nextInt();      // not used further, kept for compatibility
        int cols = scanner.nextInt();      // not used further, kept for compatibility

        computeInitialMetric(board);

        int q = scanner.nextInt();         // number of updates
        for (int i = 0; i < q; ++i) {
            int pos = scanner.nextInt() - 1;
            char newVal = scanner.nextChar();
            applyChange(pos, newVal);
            printer.println(metric);
        }

        long elapsed = System.currentTimeMillis() - startTime;
        if (debugMode) {
            System.err.println(elapsed + " ms");
        }

        scanner.close();
        printer.close();
    }

    /** Pre‑process the original string to obtain the initial value of the metric. */
    private static void computeInitialMetric(char[] data) {
        metric = 0;
        int length = data.length;
        for (int i = 0; i < length; ++i) {
            if (data[i] != '.') continue;
            int start = i;
            while (i + 1 < length && data[i + 1] == '.') {
                ++i;
            }
            metric += (i - start);               // length of this '.' block
        }
    }

    /**
     * Updates the metric when a single cell changes.
     *
     * @param idx  index of the cell (0‑based)
     * @param newValue character to place at {@code idx}
     */
    private static void applyChange(int idx, char newValue) {
        char oldValue = board[idx];
        if (oldValue == newValue) {
            return;                                 // nothing to do
        }

        // If we are removing a '.' from the board we may destroy up to two isolated runs
        if (oldValue == '.') {
            int neighbourRuns = 0;
            if (idx + 1 < board.length && board[idx + 1] == '.') neighbourRuns++;
            if (idx - 1 >= 0 && board[idx - 1] == '.') neighbourRuns++;
            metric += neighbourRuns;
        } else {
            // If we are inserting a '.' it can merge adjacent isolated runs
            int neighbourRuns = 0;
            if (idx + 1 < board.length && board[idx + 1] == '.') neighbourRuns++;
            if (idx - 1 >= 0 && board[idx - 1] == '.') neighbourRuns++;
            metric -= neighbourRuns;
        }

        board[idx] = newValue;
    }
}

/**
 * Very small, fast scanner that mimics the behaviour of the original hand‑rolled
 * {@code Reader} class but uses fewer lines of code and is easier to understand.
 * It is deliberately kept private to the {@code Main} class.
 */
class FastScanner {

    private final InputStream in;
    private final byte[] buffer = new byte[16_384];
    private int ptr = 0;
    private int len = 0;

    FastScanner() { this(System.in); }
    FastScanner(InputStream source) { this.in = source; }

    /** Reads the next byte, returning {@code -1} on EOF. */
    private int readByte() throws IOException {
        if (ptr >= len) {
            len = in.read(buffer);
            ptr = 0;
            if (len <= 0) return -1;
        }
        return buffer[ptr++];
    }

    /** Skips over any non‑printable characters. */
    private void skipNonPrintable() throws IOException {
        while (true) {
            int c = readByte();
            if (c == -1) return;
            if (c >= 33 && c <= 126) {
                ptr--;               // put back the good character
                break;
            }
        }
    }

    /** Returns {@code true} if there is another token available. */
    public boolean hasNext() {
        skipNonPrintable();
        return true;
    }

    /** Reads the next contiguous printable token. */
    public String next() {
        skipNonPrintable();
        StringBuilder sb = new StringBuilder();
        int c;
        while ((c = readByte()) != -1 && c >= 33 && c <= 126) {
            sb.append((char) c);
        }
        return sb.toString();
    }

    /** Reads the next integer. */
    public int nextInt() {
        return (int) nextLong();
    }

    /** Reads the next long integer. */
    public long nextLong() {
        boolean negative = false;
        long value = 0;
        int c = readByte();
        if (c == '-') {
            negative = true;
            c = readByte();
        }
        while (c >= '0' && c <= '9') {
            value = value * 10 + (c - '0');
            c = readByte();
        }
        return negative ? -value : value;
    }

    /** Reads the next character. */
    public char nextChar() {
        skipNonPrintable();
        return (char) readByte();
    }

    /** Closes the underlying input stream. */
    public void close() throws IOException {
        in.close();
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;

/**
 * Replacement – maintains a count of adjacent “..” pairs while processing
 * updates to a character array.
 *
 * <p>The original logic was embedded directly in {@code main} and used many
 * ad‑hoc conditionals.  The refactor extracts the counting logic into
 * dedicated methods, uses 1‑based indexing for clarity, and replaces the
 * duplicated if‑blocks with a small, well‑named helper.</p>
 */
public class Replacement {

    /** Entry point – reads input, processes queries and prints results. */
    public static void main(String[] args) throws IOException {
        // -----------------------------------------------------------------
        // 1️⃣  Input handling
        // -----------------------------------------------------------------
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in))) {
            String[] firstLine = br.readLine().split("\\s+");
            int n = Integer.parseInt(firstLine[0]); // length of the string
            int m = Integer.parseInt(firstLine[1]); // number of queries

            String initial = br.readLine();          // the initial string (no spaces)
            char[] chars = new char[n + 2];          // 1‑based indexing; index 0 unused
            System.arraycopy(initial.toCharArray(), 0, chars, 1, n);

            long adjacentPairs = countAdjacentPairs(chars, n);
            StringBuilder out = new StringBuilder();

            // -----------------------------------------------------------------
            // 2️⃣  Process each query
            // -----------------------------------------------------------------
            for (int query = 0; query < m; query++) {
                String[] parts = br.readLine().split("\\s+");
                if (parts.length < 2) {
                    continue; // ignore malformed lines
                }

                int idx = Integer.parseInt(parts[0]);
                char newChar = parts[1].charAt(0);

                // No change – just output the current count
                if (chars[idx] == newChar) {
                    out.append(adjacentPairs).append('\n');
                    continue;
                }

                // Update the count based on the neighbourhood of the changed position
                adjacentPairs = updateAdjacentPairs(chars, idx, newChar, n);
                chars[idx] = newChar;                 // apply the modification
                out.append(adjacentPairs).append('\n');
            }

            System.out.print(out.toString());
        }
    }

    /** Counts how many adjacent ".." pairs exist in the range 1 … n. */
    private static long countAdjacentPairs(char[] chars, int n) {
        long cnt = 0;
        for (int i = 1; i < n; i++) {
            if (chars[i] == '.' && chars[i + 1] == '.') {
                cnt++;
            }
        }
        return cnt;
    }

    /**
     * Adjusts the {@code adjacentPairs} counter when the character at {@code idx}
     * is replaced by {@code newChar}.
     *
     * <p>Only the pairs that involve {@code idx} can change:
     * {@code (idx‑1, idx)} and {@code (idx, idx+1)}.  The method returns the
     * updated total.</p>
     *
     * @return the new value of {@code adjacentPairs}
     */
    private static long updateAdjacentPairs(char[] chars, int idx, char newChar, int n) {
        char oldChar = chars[idx];
        if (oldChar == newChar) {
            return 0; // should never happen – caller already checked
        }

        long delta = 0;

        // Adding a '.' can create at most two new adjacent pairs
        if (newChar == '.') {
            if (idx - 1 >= 1 && chars[idx - 1] == '.') delta++;
            if (idx + 1 <= n && chars[idx + 1] == '.') delta++;
        }
        // Removing a '.' can destroy at most two adjacent pairs
        else {
            if (idx - 1 >= 1 && chars[idx - 1] == '.') delta--;
            if (idx + 1 <= n && chars[idx + 1] == '.') delta--;
        }

        return delta;
    }
}

