/**
 * Refactored solution that maintains the number of adjacent '.' pairs
 * (i.e. occurrences of "..") while processing updates.
 *
 * The program follows the same input‑output contract as the original
 * version but is organized into small, reusable methods and uses
 * clearer naming and modern Java practices.
 */
public class Solution {

    /** Fast scanner that reads whitespace‑separated tokens. */
    private static final class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner(BufferedReader br) {
            this.br = br;
        }

        /** Returns the next token, waiting for more input if necessary. */
        String next() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                st = new StringTokenizer(br.readLine());
            }
            return st.nextToken();
        }

        /** Convenience method for reading an integer. */
        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }

    /**
     * Calculates how many indices i satisfy a[i] == '.' && a[i+1] == '.'.
     */
    private static int countAdjacentDots(char[] arr) {
        int cnt = 0;
        for (int i = 0; i < arr.length - 1; i++) {
            if (arr[i] == '.' && arr[i + 1] == '.') {
                cnt++;
            }
        }
        return cnt;
    }

    /**
     * Determines the change in the number of adjacent '.' pairs caused
     * by writing {@code newChar} at position {@code idx}.
     *
     * @return delta – the amount to add to the current answer.
     */
    private static int deltaForChange(char[] arr, int idx, char newChar) {
        int before = 0;

        // contributions that involve the current character before the change
        if (idx > 0 && arr[idx - 1] == '.' && arr[idx] == '.') {
            before++;
        }
        if (idx + 1 < arr.length && arr[idx] == '.' && arr[idx + 1] == '.') {
            before++;
        }

        // contributions after the character has been replaced
        int after = 0;
        if (idx > 0 && arr[idx - 1] == '.' && newChar == '.') {
            after++;
        }
        if (idx + 1 < arr.length && newChar == '.' && arr[idx + 1] == '.') {
            after++;
        }

        return after - before;
    }

    public static void main(String[] args) throws IOException {
        // Use a BufferedReader wrapped in a FastScanner for efficient token reading
        FastScanner fs = new FastScanner(new BufferedReader(new InputStreamReader(System.in)));
        PrintWriter out = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)));

        int n = fs.nextInt();          // length of the character array
        int m = fs.nextInt();          // number of operations
        String s = fs.next();          // initial string of length n
        char[] a = s.toCharArray();    // mutable representation

        // Initial count of ".." occurrences
        int ans = countAdjacentDots(a);

        // Special case: a single character has no adjacent pairs.
        if (n == 1) {
            for (int i = 0; i < m; i++) {
                out.println(0);
            }
            out.close();
            return;
        }

        // Process each operation
        for (int i = 0; i < m; i++) {
            int index = fs.nextInt();          // 1‑based position to modify
            String token = fs.next();          // new character (first char only)
            char newChar = token.charAt(0);
            int pos = index - 1;               // convert to 0‑based index

            // Compute how the answer changes and update it
            int delta = deltaForChange(a, pos, newChar);
            ans += delta;
            a[pos] = newChar;                  // perform the actual update

            out.println(ans);
        }

        out.close();
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;

/**
 * Refactored solution that reads an initial character array,
 * computes a derived value {@code f}, and processes a series of updates.
 *
 * <p>Key improvements over the original version:
 *
 * <ul>
 *   <li>Clear separation of concerns – each logical step lives in its own
 *       well‑named method.</li>
 *   <li>Use of {@code try‑with‑resources} ensures the input stream is closed
 *       automatically.</li>
 *   <li>Descriptive variable and method names improve readability.</li>
 *   <li>Mutable static fields have been eliminated; state is encapsulated in
 *       local variables.</li>
 *   <li>The computation of {@code f} is isolated in {@code computeF}.</li>
 *   <li>Update handling is delegated to {@code handleUpdate}.</li>
 * </ul>
 */
public class Main {

    /** Splits a line on whitespace. */
    private static String[] tokenize(String line) {
        return line.trim().split("\\s+");
    }

    /** Parses a line consisting of integers into an {@code int} array. */
    private static int[] parseInts(String line) {
        String[] parts = tokenize(line);
        int[] numbers = new int[parts.length];
        for (int i = 0; i < parts.length; i++) {
            numbers[i] = Integer.parseInt(parts[i]);
        }
        return numbers;
    }

    /**
     * Computes the function {@code f} on the character array.
     * For each maximal block of {@code '.'} of length {@code L},
     * the contribution to {@code f} is {@code L‑1}.
     */
    private static int computeF(char[] data, int length) {
        int consecutive = 0;
        int result = 0;
        for (int i = 0; i < length; i++) {
            if (data[i] == '.') {
                consecutive++;
            } else {
                if (consecutive > 0) {
                    result += consecutive - 1;
                    consecutive = 0;
                }
            }
        }
        if (consecutive > 0) {
            result += consecutive - 1;
        }
        return result;
    }

    /**
     * Processes a single update request.
     *
     * @param index  zero‑based position to modify
     * @param token  the token containing the new character
     * @param data   mutable character array that stores the current state
     * @param fValue array holding the current {@code f} value (used as mutable container)
     * @param reader buffered reader for further input lines
     * @throws IOException if an I/O error occurs
     */
    private static void handleUpdate(int index, String token, char[] data,
                                     int[] fValue, BufferedReader reader)
            throws IOException {
        char newChar = token.charAt(0);
        char oldChar = data[index];
        data[index] = newChar;                      // apply the change

        // Adjust the current f value according to how the change affects
        // neighboring dot groups. The logic mirrors the original algorithm
        // but is expressed more clearly.
        if (newChar == '.') {
            if (oldChar != '.') {
                if (index > 0 && data[index - 1] == '.') {
                    fValue[0]++;
                }
                if (index < data.length - 1 && data[index + 1] == '.') {
                    fValue[0]++;
                }
            }
        } else { // newChar is a letter, turning a dot into a letter may split a group
            if (oldChar == '.') {
                if (index > 0 && data[index - 1] == '.') {
                    fValue[0]--;
                }
                if (index < data.length - 1 && data[index + 1] == '.') {
                    fValue[0]--;
                }
            }
        }

        System.out.println(fValue[0]);
    }

    public static void main(String[] args) throws IOException {
        // The try‑with‑resources block guarantees that the BufferedReader is closed.
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in))) {
            // ----- read problem description -----
            int[] header = parseInts(br.readLine());   // first line: n m
            int n = header[0];
            int m = header[1];

            // ----- read initial string -----
            char[] chars = br.readLine().toCharArray();

            // initial value of f
            int[] fValue = new int[]{ computeF(chars, n) };

            // ----- process each update operation -----
            for (int i = 0; i < m; i++) {
                String[] request = tokenize(br.readLine());
                int idx = Integer.parseInt(request[0]) - 1; // convert to zero‑based index
                handleUpdate(idx, request[1], chars, fValue, br);
            }
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;

/**
 * Reads an initial binary mask of length {@code n} ( '.' represents {@code true},
 * any other character represents {@code false} ).
 * Afterwards {@code m} updates are performed; each update changes the value at a
 * given index. After each update the number of maximal contiguous '.'‑segments
 * is printed.
 *
 * The program has been refactored to improve readability, maintainability and
 * resource handling.
 */
public class CFTest54 {

    /** Queue used to lazily split incoming lines into tokens. */
    private static final java.util.Queue<String> tokenQueue = new java.util.ArrayDeque<>();

    public static void main(String[] args) throws IOException {
        // try‑with‑resources guarantees the BufferedReader is closed automatically
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in))) {
            // read header (n and number of queries)
            int[] header = parseIntArray(readLine());
            int maskLength = header[0];
            int queryCount = header[1];

            // read the initial mask string
            String maskString = readLine();

            // convert the mask into a boolean array (true == '.')
            boolean[] mask = parseMask(maskString, maskLength);

            // initial count of contiguous '.'‑segments
            int segmentCount = countSegments(mask);

            // process every query
            for (int i = 0; i < queryCount; i++) {
                String[] parts = readLine().split(" ");
                int index = Integer.parseInt(parts[0]) - 1; // problem uses 1‑based indices
                boolean newValue = parts[1].equals(".");

                if (mask[index] != newValue) {
                    updateMaskAndPrint(mask, segmentCount, index, newValue);
                } else {
                    // nothing changed – still output the current count
                    System.out.println(segmentCount);
                }
            }
        }
    }

    /** Parses a line containing space‑separated integers into an {@code int[]}. */
    private static int[] parseIntArray(String line) {
        String[] tokens = line.split(" ");
        int[] result = new int[tokens.length];
        for (int i = 0; i < tokens.length; i++) {
            result[i] = Integer.parseInt(tokens[i]);
        }
        return result;
    }

    /** Parses the binary mask line into a boolean array. */
    private static boolean[] parseMask(String line, int length) {
        boolean[] arr = new boolean[length];
        for (int i = 0; i < length; i++) {
            arr[i] = line.charAt(i) == '.';
        }
        return arr;
    }

    /** Counts how many maximal contiguous groups of {@code true} values exist. */
    private static int countSegments(boolean[] arr) {
        int count = 0;
        for (int i = 0; i < arr.length; i++) {
            if (arr[i] && (i == 0 || !arr[i - 1])) {
                count++;
            }
        }
        return count;
    }

    /**
     * Adjusts {@code segmentCount} according to the toggle at {@code index}
     * and prints the new count.
     *
     * @param mask       the current mask array
     * @param segmentCount mutable holder for the segment count (used as int[1])
     * @param index      position to toggle (0‑based)
     * @param newValue   the value to set at {@code index}
     */
    private static void updateMaskAndPrint(boolean[] mask,
                                            int[] segmentCount,
                                            int index,
                                            boolean newValue) {
        boolean oldValue = mask[index];
        mask[index] = newValue;

        if (oldValue && !newValue) { // '.' -> '_' (removing a dot)
            if (index > 0 && mask[index - 1]) segmentCount[0]--;
            if (index < mask.length - 1 && mask[index + 1]) segmentCount[0]--;
        } else if (!oldValue && newValue) { // '_' -> '.' (adding a dot)
            if (index > 0 && mask[index - 1]) segmentCount[0]++;
            if (index < mask.length - 1 && mask[index + 1]) segmentCount[0]++;
        }

        System.out.println(segmentCount[0]);
    }
}

/**
 * Refactored solution for the problem “C”.
 *
 * Improvements over the original code
 * --------------------------------
 * • Meaningful class and method names (Gap, GapSet, FastScanner …).
 * • No raw types – all collections are parameterised.
 * • The algorithm is split into small, self‑contained helpers.
 * • The scanner/reader is encapsulated in a dedicated {@code FastScanner}
 *   class that hides the boiler‑plate of {@code BufferedReader} and
 *   {@code StringTokenizer}.
 * • All mutable state is confined to the solving class, making the flow
 *   easier to follow.
 * • The code follows modern Java conventions (final where possible,
 *   try‑with‑resources, proper {@code equals}/{\@code hashCode} overrides,
 *   Javadoc comments).
 *
 * The functional behaviour (reading the input, handling the updates,
 * printing the total length of '.'‑segments after each query) is unchanged.
 */

import java.io.*;
import java.util.*;


/** Entry point – thin wrapper that creates the scanner and the solver. */
public final class Main {
    public static void main(String[] args) throws Exception {
        // System.in / System.out are passed to the fast scanner / print‑writer.
        try (Reader ignored = new FastScanner(System.in);
             PrintWriter out = new PrintWriter(System.out)) {
            new TaskC().solve(1, new FastScanner(System.in), out);
        }
    }
}

/** Fast scanner that mimics the behaviour of the original handcrafted
 *  {@code Reader} class but uses only standard JDK types. */
final class FastScanner {
    private final BufferedReader br;
    private StringTokenizer st;

    FastScanner(InputStream source) {
        this.br = new BufferedReader(new InputStreamReader(source));
    }

    /** Returns the next token (delimited by whitespace). */
    private String nextToken() {
        if (st == null || !st.hasMoreTokens()) {
            try {
                String line = br.readLine();
                if (line == null) {
                    return null;
                }
                st = new StringTokenizer(line);
            } catch (IOException e) {
                throw new UncheckedIOException(e);
            }
        }
        return st.nextToken();
    }

    /** Reads the next line completely. */
    String readLine() {
        try {
            return br.readLine();
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
    }

    /** Reads an {@code int}. */
    int nextInt() {
        return Integer.parseInt(nextToken());
    }

    /** Reads a {@code char[]} (the original code expects a whole line of chars). */
    char[] nextCharArray() {
        return readLine().toCharArray();
    }
}

/** Solver for the problem – all logic lives inside this class. */
final class TaskC {

    /** Handles a single test case (the original program only has one). */
    void solve(int testIdx, FastScanner in, PrintWriter out) {
        final int n = in.nextInt();          // length of the string
        final int m = in.nextInt();          // number of queries
        char[] line = in.readLine().toCharArray(); // the initial string

        GapSet gaps = new GapSet();          // all '.'‑segments, sorted by start
        long totalLength = initialiseGaps(line, gaps);

        // Process the queries
        for (int q = 0; q < m; ++q) {
            int pos = in.nextInt() - 1;               // 0‑based index
            char newChar = in.nextToken().charAt(0);
            char oldChar = line[pos];
            line[pos] = newChar;

            if (newChar == '.' && oldChar != '.') {
                // Fill an empty cell – possibly merge adjacent gaps.
                Gap merged = gaps.mergeAround(pos, totalLength);
                totalLength += merged.length();
                out.println(totalLength);
            } else if (newChar != '.' && oldChar == '.') {
                // Turn a '.' into a non‑'.' – possibly split a gap.
                gaps.splitAt(pos, totalLength);
                out.println(totalLength);
            } else {
                // No change to the set of gaps (e.g. '.' → '.' or non‑'.' → non‑'.')
                out.println(totalLength);
            }
        }
    }

    /** Scans the initial string and records all maximal '.'‑segments.
     *  Returns the sum of their lengths. */
    private static long initialiseGaps(char[] s, GapSet gaps) {
        long total = 0;
        for (int i = 0; i < s.length; ) {
            if (s[i] != '.') {
                ++i;
                continue;
            }
            int start = i;
            while (i < s.length && s[i] == '.') {
                ++i;
            }
            Gap g = new Gap(start, i - 1);
            gaps.add(g);
            total += g.length();
        }
        return total;
    }
}

/** Simple immutable container that represents a closed interval
 *  `[start, end]` of consecutive '.' characters. */
final class Gap implements Comparable<Gap> {
    final int start;   // inclusive
    final int end;     // inclusive

    Gap(int start, int end) {
        this.start = start;
        this.end = end;
    }

    /** Length of the gap (number of '.' characters). */
    int length() {
        return end - start;
    }

    /** Returns a comparable instance that can be used with {@code TreeSet}
     *  ordering by the start coordinate. */
    @Override
    public int compareTo(Gap o) {
        int c = Integer.compare(this.start, o.start);
        return (c != 0) ? c : Integer.compare(this.end, o.end);
    }

    @Override
    public boolean equals(Object obj) {
        if (this == obj) return true;
        if (!(obj instanceof Gap)) return false;
        Gap other = (Gap) obj;
        return start == other.start && end == other.end;
    }

    @Override
    public int hashCode() {
        return Objects.hash(start, end);
    }

    @Override
    public String toString() {
        return start + ".." + end;
    }
}

/** A sorted set of {@link Gap} objects that supplies convenient helpers
 *  for merging and splitting gaps. */
final class GapSet extends TreeSet<Gap> {

    GapSet() {
        super(Comparator.comparingInt(g -> g.start));
    }

    /** Finds the gap that ends just before {@code pos} (if any). */
    private Gap floorGapEndingAt(int pos) {
        // A gap that could end at pos‑1 must have start ≤ pos‑1 and end ≥ pos‑1.
        // The natural ordering (by start) guarantees that the greatest gap
        // with start ≤ pos‑1 is the correct candidate.
        Gap probe = new Gap(0, pos - 1);
        Gap candidate = lower(probe);
        return (candidate != null && candidate.end == pos - 1) ? candidate : null;
    }

    /** Finds the gap that starts just after {@code pos} (if any). */
    private Gap ceilingGapStartingAt(int pos) {
        Gap probe = new Gap(pos + 1, Integer.MAX_VALUE);
        Gap candidate = higher(probe);
        return (candidate != null && candidate.start == pos + 1) ? candidate : null;
    }

    /** Merges the gap(s) adjacent to {@code pos} and returns the newly created gap.
     *  The length of the merged interval is added to {@code totalLength}. */
    Gap mergeAround(int pos, long[] totalLength) {
        Gap left = floorGapEndingAt(pos);
        Gap right = ceilingGapStartingAt(pos);

        int newStart = (left != null) ? left.start : pos;
        int newEnd   = (right != null) ? right.end   : pos;

        // Remove absorbed gaps and adjust the total length.
        if (left != null) {
            remove(left);
            totalLength[0] -= left.length();
        }
        if (right != null) {
            remove(right);
            totalLength[0] -= right.length();
        }

        Gap merged = new Gap(newStart, newEnd);
        add(merged);
        totalLength[0] += merged.length();
        return merged;
    }

    /** Splits the gap that contains {@code pos} into two (or one) sub‑gaps.
     *  The length of the removed gap is subtracted from {@code totalLength}. */
    void splitAt(int pos, long[] totalLength) {
        // The gap that contains pos is the floor gap when we query with (pos,pos).
        Gap containing = floor(new Gap(pos, pos));
        if (containing == null || containing.start > pos || containing.end < pos) {
            throw new IllegalStateException("Position " + pos + " is not inside any gap");
        }

        remove(containing);
        totalLength[0] -= containing.length();

        // Add the left piece, if any.
        if (containing.start < pos) {
            Gap left = new Gap(containing.start, pos - 1);
            add(left);
            totalLength[0] += left.length();
        }
        // Add the right piece, if any.
        if (pos < containing.end) {
            Gap right = new Gap(pos + 1, containing.end);
            add(right);
            totalLength[0] += right.length();
        }
    }
}

import java.io.*;
import java.util.StringTokenizer;

/**
 * Solves the problem of counting pairs of consecutive '.' characters after a series of updates.
 *
 * <p>Refactor goals:
 * <ul>
 *   <li>Clear, expressive naming.</li>
 *   <li>Separation of concerns – I/O, validation and the core algorithm are isolated.</li>
 *   <li>Small helper methods that each do one thing.</li>
 *   <li>No use of {@code StringTokenizer} abuse – we read tokens once and reuse them.</li>
 *   <li>Self‑documenting code and minimal magic numbers.</li>
 * </ul>
 */
public class Main implements Runnable {

    /** Buffered reader for fast input. */
    private BufferedReader reader;

    /** Print writer for fast output. */
    private PrintWriter writer;

    /** Tokenizer used for token extraction. */
    private StringTokenizer tokenizer;

    /** Character buffer that stores the current state of the string. */
    private char[] cells;

    /** Number of cells in the string. */
    private int length;

    /** Count of consecutive '.' pairs in the current state. */
    private int consecutiveDotPairs;

    /* --------------------------------------------------------------- */
    /*                     PUBLIC ENTRY POINT                         */
    /* --------------------------------------------------------------- */
    public static void main(String[] args) throws Exception {
        new Thread(new Main()).start();
    }

    @Override
    public void run() {
        try {
            init();
            solve();
            writer.close();
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
    }

    /* --------------------------------------------------------------- */
    /*                     INITIALISATION                              */
    /* --------------------------------------------------------------- */
    /** Sets up the reader, writer and the character buffer. */
    private void init() throws IOException {
        reader = new BufferedReader(new InputStreamReader(System.in));
        writer = new PrintWriter(System.out, true);      // auto‑flush

        // First line: n and m
        String line = reader.readLine();
        assert line != null; // non‑empty input guaranteed
        StringTokenizer firstTokens = new StringTokenizer(line);
        length = Integer.parseInt(firstTokens.nextToken());
        int updates = Integer.parseInt(firstTokens.nextToken());

        // Second line: the initial character sequence
        cells = reader.readLine().toCharArray();
        if (cells.length != length) {
            throw new IllegalArgumentException("Length mismatch of the sequence.");
        }
        tokeniserForSingleToken(); // consume trailing EOF newline / spaces

        // Compute the initial number of consecutive '.' pairs
        consecutiveDotPairs = countConsecutiveDotPairs(cells);
    }

    /* --------------------------------------------------------------- */
    /*                     CORE LOGIC                                   */
    /* --------------------------------------------------------------- */
    /** Reads the next token from the input and advances the tokenizer. */
    private String nextToken() throws IOException {
        while (!tokenizer.hasMoreTokens()) {
            String nextLine = reader.readLine();
            if (nextLine == null) {
                throw new EOFException();
            }
            tokenizer = new StringTokenizer(nextLine);
        }
        return tokenizer.nextToken();
    }

    /** Reads an integer token from the input. */
    private int nextInt() throws IOException {
        return Integer.parseInt(nextToken());
    }

    /** Reads a long token from the input. */
    private long nextLong() throws IOException {
        return Long.parseLong(nextToken());
    }

    /** Reads the next character (the first token is a single character). */
    private char nextChar() throws IOException {
        return nextToken().charAt(0);
    }

    /**
     * Returns the number of indices i such that cells[i] == '.' &&
     * cells[i+1] == '.' for the current buffer.
     */
    private static int countConsecutiveDotPairs(char[] arr) {
        int count = 0;
        for (int i = 0; i < arr.length - 1; i++) {
            if (arr[i] == '.' && arr[i + 1] == '.') {
                count++;
            }
        }
        return count;
    }

    /**
     * Adjusts {@link #consecutiveDotPairs} based on the change from
     * {@code oldChar} to {@code newChar} at {@code index}.
     *
     * <p>The algorithm checks the left neighbour (index‑1) and the right neighbour
     * (index+1) of the updated position, because only those pairs can be affected.
     *
     * @param index   position that changes (0‑based)
     * @param oldChar character that is being replaced
     * @param newChar character that will replace it
     */
    private void adjustCountForUpdate(int index, char oldChar, char newChar) {
        // Helper lambda to update based on presence of '.' on the left/right side
        java.util.function.BiConsumer<Character, Boolean> influence = (c, isRight) -> {
            int neighbourIdx = isRight ? index + 1 : index - 1;
            if (neighbourIdx < 0 || neighbourIdx >= length) {
                return;
            }
            boolean hasDot = c == '.';
            // If we are turning a '.' into something else we may lose a pair
            // If we are turning into '.' we may gain a pair
            if (hasDot) {
                if (newChar == '.' && cells[neighbourIdx] == '.') {
                    consecutiveDotPairs++;
                }
                if (oldChar == '.' && cells[neighbourIdx] == '.') {
                    consecutiveDotPairs--;
                }
            } else {
                if (oldChar == '.' && cells[neighbourIdx] == '.') {
                    consecutiveDotPairs--;
                }
                if (newChar != '.' && cells[neighbourIdx] == '.') {
                    consecutiveDotPairs++;
                }
            }
        };

        // Evaluate left neighbour impact
        boolean leftValid = index - 1 >= 0;
        boolean rightValid = index + 1 < length;

        // Left side (index-1, index)
        if (leftValid) {
            influence.accept(oldChar, false);
            influence.accept(newChar, false);
        }

        // Right side (index, index+1)
        if (rightValid) {
            influence.accept(oldChar, true);
            influence.accept(newChar, true);
        }
    }

    /**
     * Processes all updates.
     *
     * <p>For each update we read an index (1‑based) and a new character.
     * If the new character differs from the current one we update the
     * state and print the new count of consecutive '.' pairs.
     */
    private void solve() throws IOException {
        int updates = nextInt();

        for (int i = 0; i < updates; i++) {
            int idx = nextInt() - 1;               // convert to 0‑based
            char newChar = nextChar();

            char oldChar = cells[idx];
            if (oldChar == newChar) {
                // No change – just output the existing count
                writer.println(consecutiveDotPairs);
                continue;
            }

            // Update the count based on the transition
            adjustCountForUpdate(idx, oldChar, newChar);

            // Apply the change to the buffer
            cells[idx] = newChar;

            // Output the new count
            writer.println(consecutiveDotPairs);
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;

public class Main {

    /** Holds the mutable state of the string and the operations that can change it. */
    private static final class State {
        private final int size;                 // length of the original string
        private final boolean[] isDot;           // true if that position contains '.'
        private int dotCount;                     // number of '.' characters
        private int groups;                       // number of isolated dot‑groups

        /** Build the initial state from the given string. */
        State(int size, String initial) {
            this.size = size;
            this.isDot = new boolean[size + 1];    // 1‑based indexing for convenience
            this.dotCount = 0;
            this.groups = 0;
            buildFrom(initial);
        }

        /** Interpret the initial string and fill `isDot`, `dotCount` and `groups`. */
        private void buildFrom(String src) {
            for (int i = 0; i < src.length(); i++) {
                if (src.charAt(i) == '.') {
                    isDot[i + 1] = true;
                    dotCount++;
                    // start of a new group: either at position 0 or previous char is not '.'
                    if (i == 0 || src.charAt(i - 1) != '.') {
                        groups++;
                    }
                }
            }
        }

        /** Toggle the character at position `pos` (1‑based) to the desired value. */
        void toggle(int pos, boolean wantDot) {
            boolean currently = isDot[pos];
            if (currently == wantDot) {
                return;                     // nothing to change
            }

            isDot[pos] = wantDot;

            if (wantDot) {
                dotCount++;
                adjustGroupsWhenAddingDot(pos);
            } else {
                dotCount--;
                adjustGroupsWhenRemovingDot(pos);
            }
        }

        /** Update `groups` after a '.' is turned into '.' at `pos`. */
        private void adjustGroupsWhenAddingDot(int pos) {
            // If both neighbours are dots we merge two groups into one → groups--
            if (pos < size && isDot[pos - 1] && isDot[pos + 1]) {
                groups--;
            }
            // If neither neighbour is a dot we create a new isolated group → groups++
            else if (pos < size && !isDot[pos - 1] && !isDot[pos + 1]) {
                groups++;
            }
            // If we are at the last position and its left neighbour is not a dot,
            // we also create a new isolated group.
            else if (pos == size && !isDot[pos - 1]) {
                groups++;
            }
            // Otherwise we simply extend an existing group → groups unchanged
        }

        /** Update `groups` after a '.' is turned into a non‑dot at `pos`. */
        private void adjustGroupsWhenRemovingDot(int pos) {
            if (pos < size && isDot[pos - 1] && isDot[pos + 1]) {
                groups++;        // we split a group into two
            } else if (pos < size && !isDot[pos - 1] && !isDot[pos + 1]) {
                groups--;        // we destroy an isolated group
            } else if (pos == size && !isDot[pos - 1]) {
                groups--;        // we remove a trailing isolated group
            }
        }

        /** The value required by the problem: `dotCount - groups`. */
        int result() {
            return dotCount - groups;
        }
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));

        /* ----- read first line: n (string length) and m (number of operations) ----- */
        String[] firstTokens = br.readLine().split("\\s+");
        int n = Integer.parseInt(firstTokens[0]);
        int m = Integer.parseInt(firstTokens[1]);

        /* ----- read the initial string ----- */
        String initial = br.readLine();

        /* ----- build the mutable state ----- */
        State state = new State(n, initial);

        /* ----- process each of the m operations ----- */
        StringBuilder output = new StringBuilder();
        for (int i = 0; i < m; i++) {
            String[] parts = br.readLine().split("\\s+");
            int index = Integer.parseInt(parts[0]);                 // 1‑based position
            char ch = parts[1].charAt(0);                             // '.' or another char
            boolean wantDot = ch == '.';
            state.toggle(index, wantDot);
            output.append(state.result()).append('\n');
        }

        System.out.print(output.toString());
    }
}

import java.io.*;
import java.util.*;

public class Replacement {

    public static void main(String[] args) throws IOException {
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));

        // ----- read dimensions and initial characters -----
        String[] firstLine = reader.readLine().split(" ");
        int n = Integer.parseInt(firstLine[0]);
        int m = Integer.parseInt(firstLine[1]);

        char[] chars = reader.readLine().toCharArray();
        boolean[] isPeriod = new boolean[n];
        for (int i = 0; i < n; i++) {
            isPeriod[i] = chars[i] == '.';
        }

        // ----- compute initial count of “extra” periods (periods beyond the first in each run) -----
        int extraPeriodCount = computeInitialExtraPeriodCount(isPeriod);
        System.out.println(extraPeriodCount);

        // ----- process the M updates -----
        processUpdates(reader, n, m, isPeriod, extraPeriodCount);
    }

    /** Counts how many periods belong to runs longer than one.
        For each maximal consecutive run of periods of length L
        we add L‑1 to the total. */
    private static int computeInitialExtraPeriodCount(boolean[] periodMask) {
        int total = 0;
        int currentRun = 0;

        for (boolean isPeriodic : periodMask) {
            if (isPeriodic) {
                currentRun++;
            } else {
                total += Math.max(0, currentRun - 1);
                currentRun = 0;
            }
        }
        total += Math.max(0, currentRun - 1); // trailing run
        return total;
    }

    private static void processUpdates(BufferedReader reader,
                                       int n,
                                       int m,
                                       boolean[] periodMask,
                                       int total) throws IOException {
        for (int i = 0; i < m; i++) {
            String[] parts = reader.readLine().split(" ");
            int index = Integer.parseInt(parts[0]) - 1;
            char newChar = parts[1].charAt(0);
            boolean newIsPeriod = newChar == '.';

            // No change → just output current total
            if (newIsPeriod == periodMask[index]) {
                System.out.println(total);
                continue;
            }

            total = adjustTotal(periodMask, index, newIsPeriod, total);
            periodMask[index] = newIsPeriod;
            System.out.println(total);
        }
    }

    /** Central routine that decides how the total must be updated
        when the period status of a single position changes. */
    private static int adjustTotal(boolean[] periodMask,
                                   int index,
                                   boolean addingPeriod,
                                   int currentTotal) {
        boolean leftIsPeriod = index > 0 && periodMask[index - 1];
        boolean rightIsPeriod = index < periodMask.length - 1 && periodMask[index + 1];

        if (index == 0) {
            return adjustBoundaryCase(currentTotal, addingPeriod, rightIsPeriod);
        }
        if (index == periodMask.length - 1) {
            return adjustBoundaryCase(currentTotal, addingPeriod, leftIsPeriod);
        }

        // interior cell
        if (leftIsPeriod && rightIsPeriod) {
            return adjustMerge(currentTotal, addingPeriod);
        }
        if (leftIsPeriod ^ rightIsPeriod) {
            return adjustAdd(currentTotal, addingPeriod);
        }
        // neighbours have the same status (both false)
        return adjustSplit(currentTotal, addingPeriod);
    }

    /** Handles updates when the changed position is at one of the ends. */
    private static int adjustBoundaryCase(int total, boolean addingPeriod, boolean neighbourIsPeriod) {
        // Adding a period at the boundary creates a new pair only when the neighbour is also a period.
        if (addingPeriod && neighbourIsPeriod) {
            return total + 1;
        }
        return addingPeriod ? total : total - 1;
    }

    /** When both neighbours are periods, inserting a period merges three runs
        into one and therefore adds two “extra” periods. Removing such a period
        does not affect the count of extra periods. */
    private static int adjustMerge(int total, boolean addingPeriod) {
        return addingPeriod ? total + 2 : total;
    }

    /** When exactly one neighbour is a period, adding a period extends an existing run,
        which adds exactly one extra period; removing it removes that extra period. */
    private static int adjustAdd(int total, boolean addingPeriod) {
        return addingPeriod ? total + 1 : total - 1;
    }

    /** When neither neighbour is a period, the change either creates an isolated period
        (which does not affect the count) or removes the only isolated period.
        The original implementation subtracted 2 only on removal, which we preserve. */
    private static int adjustSplit(int total, boolean addingPeriod) {
        return addingPeriod ? total : total - 2;
    }
}

import java.io.*;
import java.util.*;

/**
 * Refactored version of the original {@code Substituicao} program.
 * <p>
 * The code has been split into small, cohesive methods, uses descriptive
 * names, avoids mutable global state, and relies on try‑with‑resources for
 * I/O handling.  The algorithmic behaviour is unchanged – it reads an
 * initial configuration, then processes a series of character substitutions
 * while maintaining a count of leading double‑dot patterns.
 * </p>
 */
public class Substituicao {

    /** Tiny holder for the values read from the first input line. */
    private static final class Config {
        final int baseIndex;               // first integer (1‑based)
        final int substitutionCount;       // second integer
        final char[] initialChars;         // character array to be mutated

        Config(int baseIndex, int substitutionCount, char[] initialChars) {
            this.baseIndex = baseIndex;
            this.substitutionCount = substitutionCount;
            this.initialChars = initialChars;
        }
    }

    /** Entry point – reads input, processes substitutions and prints results. */
    public static void main(String[] args) {
        /* Try‑with‑resources guarantees proper closing of I/O streams. */
        try (BufferedReader reader = new BufferedReader(
                new InputStreamReader(System.in));
             PrintWriter out = new PrintWriter(
                     new BufferedWriter(new OutputStreamWriter(System.out))) ) {

            Config cfg = readInitialConfiguration(reader);
            processSubstitutions(cfg, reader, out);

        } catch (IOException e) {
            /* In a production setting we would log the error. */
            e.printStackTrace();
        }
    }

    /** Parses the first two lines of input into a {@link Config} instance. */
    private static Config readInitialConfiguration(BufferedReader reader) throws IOException {
        String line = reader.readLine();
        if (line == null) {
            throw new IllegalArgumentException("Missing initial configuration line");
        }

        String[] parts = line.trim().split("\\s+");
        if (parts.length != 2) {
            throw new IllegalArgumentException("First line must contain exactly two integers");
        }

        int baseIndex = Integer.parseInt(parts[0]);
        int substitutionCount = Integer.parseInt(parts[1]);

        // The next line holds the character sequence (dots and other symbols)
        char[] chars = reader.readLine()
                .replaceAll("\\s+", "")
                .toCharArray();

        if (chars.length < baseIndex - 1) {
            throw new IllegalArgumentException("Not enough characters for the given base index");
        }

        return new Config(baseIndex, substitutionCount, chars);
    }

    /** Reads each substitution line, updates the character array and prints the count. */
    private static void processSubstitutions(Config cfg,
                                               BufferedReader reader,
                                               PrintWriter out) throws IOException {
        int doubleDotCount = countLeadingDoubleDots(cfg.initialChars, cfg.baseIndex);

        for (int processed = 0; processed < cfg.substitutionCount; processed++) {
            String[] fields = reader.readLine().trim().split("\\s+");
            if (fields.length < 2) {
                throw new IllegalArgumentException("Substitution line must contain at least two tokens");
            }

            int index = Integer.parseInt(fields[0]);   // 1‑based position
            char replacement = fields[1].charAt(0);

            if (updateCharAt(cfg.initialChars, index - 1, replacement)) {
                // Adjust the double‑dot counter based on the changed character
                adjustCount(index, replacement, cfg.initialChars, doubleDotCount);
            }

            out.println(doubleDotCount);
        }
    }

    /** Counts occurrences of ".." within the first {@code limit} characters. */
    private static int countLeadingDoubleDots(char[] arr, int limit) {
        int count = 0;
        for (int i = 0; i < limit - 1; i++) {
            if (arr[i] == '.' && arr[i + 1] == '.') {
                count++;
            }
        }
        return count;
    }

    /** Updates the character at {@code pos} if it differs from {@code newChar}.
     *  Returns {@code true} if a change was performed. */
    private static boolean updateCharAt(char[] arr, int pos, char newChar) {
        if (arr[pos] == newChar) {
            return false;                     // no mutation needed
        }
        arr[pos] = newChar;
        return true;
    }

    /**
     * Recalculates the double‑dot counter after a character change.
     * <p>
     * The adjustment uses a mutable {@code int[]} wrapper to avoid passing
     * a separate mutable object throughout the code base.
     * </p>
     */
    private static void adjustCount(int changedIndex,
                                        char newChar,
                                        char[] arr,
                                        int[] counter) {
        // Influence of the right neighbour (if it exists)
        if (changedIndex < arr.length - 1 && arr[changedIndex + 1] == '.') {
            counter[0] += (newChar == '.') ? 1 : -1;
        }

        // Influence of the left neighbour (if it exists)
        if (changedIndex > 0 && arr[changedIndex - 1] == '.') {
            counter[0] += (newChar == '.') ? 1 : -1;
        }
    }
}

import java.io.*;
import java.util.Scanner;

/**
 * Entry point of the application.
 * Reads input, creates the solver and prints the answers.
 */
public class Main {

    public static void main(String[] args) {
        // Fast I/O using the system streams
        try (InputStream inStream = System.in;
             OutputStream outStream = System.out) {

            Scanner scanner = new Scanner(inStream);
            PrintWriter printer = new PrintWriter(outStream);

            // The solver works for a single test case (the original code used the same signature)
            new TaskC().solve(1, scanner, printer);
            // PrintWriter is closed automatically by the try‑with‑resources block
        }
    }
}

/**
 * Core logic of the problem.
 * <p>
 * The original implementation mixed I/O with the algorithm and used
 * cryptic variable names.  The refactor separates concerns, introduces
 * expressive names and extracts helper methods.
 */
class TaskC {

    /** Number of characters that the input string contains. */
    private static final int STRING_LENGTH = 100_000;   // not used directly – kept as a hint

    /**
     * Solves the problem for the supplied input reader and output printer.
     *
     * @param testNumber dummy parameter kept to preserve the original API
     * @param in         reader that provides the problem data
     * @param out        printer for the results
     */
    public void solve(int testNumber, Scanner in, PrintWriter out) {
        // -----------------------------------------------------------------
        // 1️⃣  Read the immutable part of the input
        // -----------------------------------------------------------------
        int n = in.nextInt();          // length of the string (not used later)
        int m = in.nextInt();          // number of queries
        in.nextLine();                 // consume end‑of‑line after the two ints

        String rawString = in.nextLine();   // the string itself
        char[] chars = rawString.toCharArray();

        // -----------------------------------------------------------------
        // 2️⃣  Pre‑compute the initial total value (the original algorithm
        //      stored it in the variable `total`)
        // -----------------------------------------------------------------
        long total = computeInitialTotal(chars);

        // -----------------------------------------------------------------
        // 3️⃣  Process each query and output the updated total
        // -----------------------------------------------------------------
        for (int queryIndex = 0; queryIndex < m; queryIndex++) {
            int position = in.nextInt() - 1;   // convert to 0‑based index
            String token = in.next();          // the new character (single char)
            char newChar = token.charAt(0);

            updateTotalAndPrint(position, newChar, chars, total, out);
        }
    }

    // -----------------------------------------------------------------
    // Helper methods – each one does ONE well‑named thing
    // -----------------------------------------------------------------

    /**
     * Calculates the initial value of `total` using the algorithm from the
     * original source code.
     *
     * @param chars the mutable character array representing the string
     * @return the computed total
     */
    private static long computeInitialTotal(char[] chars) {
        long total = 0;
        int from = -1;                     // start index of a '.' run

        for (int i = 0; i < chars.length; i++) {
            if (from < 0 && chars[i] == '.') {
                from = i;
                continue;
            }
            if (from >= 0 && chars[i] != '.') {
                // length of the gap that ends just before i
                total += Math.max(i - 1 - from, 0);
                from = -1;
            }
        }
        // If the string ends with a '.' run, count that gap as well
        if (from >= 0) {
            total += Math.max(chars.length - 1 - from, 0);
        }
        return total;
    }

    /**
     * Updates the running `total` according to the character change at
     * `position` and prints the new value.
     *
     * @param position   index to update
     * @param newChar    the character that will replace the old one
     * @param chars      mutable character array
     * @param total      current total – will be mutated
     * @param out        printer for the answer
     */
    private static void updateTotalAndPrint(int position,
                                            char newChar,
                                            char[] chars,
                                            long[] total,   // mutable wrapper
                                            PrintWriter out) {

        char oldChar = chars[position];

        // -------------------------------------------------------------
        // 1️⃣  If we are setting a non‑'.' character on a '.' position
        // -------------------------------------------------------------
        if (newChar != '.' && oldChar == '.') {
            // Leaving a '.' unpainted – may reduce the number of gaps
            handleSetNonDot(position, chars, total);
        }
        // -------------------------------------------------------------
        // 2️⃣  If we are restoring a '.' on a previously non‑'.' cell
        // -------------------------------------------------------------
        else if (newChar == '.' && oldChar != '.') {
            // Filling a '.' may increase the number of gaps
            handleRestoreDot(position, chars, total);
        }
        // -------------------------------------------------------------
        // 3️⃣  No change that affects the total (both chars are equal)
        // -------------------------------------------------------------
        else {
            // Keep the current total unchanged
        }

        // Update the internal state and print the result
        chars[position] = newChar;
        out.println(total[0]);
    }

    /**
     * Adjusts `total` when a '.' cell is replaced by a non‑'.' character.
     * The logic mirrors the original fragment but is now isolated and
     * documented.
     */
    private static void handleSetNonDot(int idx, char[] chars, long[] total) {
        boolean leftHasDot = idx > 0 && chars[idx - 1] == '.';
        boolean rightHasDot = idx < chars.length - 1 && chars[idx + 1] == '.';

        if (leftHasDot && rightHasDot) {
            total[0] -= 2;               // two gaps disappear
        } else if (leftHasDot || rightHasDot) {
            total[0] -= 1;               // one gap disappears
        }
        // If neither neighbour is a dot, nothing changes – the original
        // code omitted the adjustment in this situation.
    }

    /**
     * Adjusts `total` when a non‑'.' cell is restored to '.'.
     * The method follows the same branching as the original code but
     * uses clearer variable names and avoids deeply nested `if`s.
     */
    private static void handleRestoreDot(int idx, char[] chars, long[] total) {
        char leftLeft = (idx - 1 >= 0) ? chars[idx - 1] : 0;
        char rightRight = (idx + 1 < chars.length) ? chars[idx + 1] : 0;

        boolean leftNeighbourIsDot = idx > 0 && chars[idx - 1] == '.';
        boolean rightNeighbourIsDot = idx < chars.length - 1 && chars[idx + 1] == '.';

        // After setting the cell to '.', check the situation of the
        // *next* neighbours (idx‑1 and idx+1) because they may form new
        // gaps together with the newly created dot.
        boolean leftNeighbourNextIsDot = idx - 1 > 0 && chars[idx - 2] == '.';
        boolean rightNeighbourNextIsDot = idx + 1 < chars.length - 1 && chars[idx + 2] == '.';

        if (leftNeighbourIsDot && rightNeighbourIsDot) {
            // Both sides become part of a new longer gap – could be 2 new units
            if (!leftNeighbourNextIsDot && !rightNeighbourNextIsDot) {
                total[0] += 2;
            } else {
                total[0] += 2; // the original code added 2 regardless;
                               // kept the same behaviour for compatibility
            }
        } else if (leftNeighbourIsDot || rightNeighbourIsDot) {
            total[0] += 2; // same reasoning as above
        } else {
            total[0] += 1; // isolated dot creates a single new gap
        }
    }
}

import java.io.*;
import java.util.StringTokenizer;

/**
 * Refactored solution for the “Replacement” problem (CF 570C).
 *
 * <p>
 * The program maintains a character array of length {@code n} and keeps track of the
 * number of adjacent “..” pairs (i.e., occurrences of two consecutive dots). After each
 * update it prints the current number of such pairs.
 * </p>
 *
 * <p>Key improvements over the original code:</p>
 * <ul>
 *   <li>Clear separation of concerns (input handling, data model, updates).</li>
 *   <li>Descriptive naming and Javadoc comments.</li>
 *   <li>Encapsulation of the tracking logic inside {@code DotTracker}.</li>
 *   <li>O(1) update cost by examining only the neighbours of the modified position.</li>
 *   <li>Fast scanner that avoids unnecessaryStringBuilder churn.</li>
 * </ul>
 */
public class Replacement_CF570C {

    /** Simple, fast scanner for competitive‑programming input. */
    private static final class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner(InputStream in) {
            this.br = new BufferedReader(new InputStreamReader(in));
        }

        /** Reads the next token, loading more tokens when necessary. */
        private String readNext() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                String line = br.readLine();
                if (line == null) {
                    return null;
                }
                st = new StringTokenizer(line);
            }
            return st.nextToken();
        }

        /** Returns the next integer token. */
        int nextInt() throws IOException {
            return Integer.parseInt(readNext());
        }

        /** Returns the next line (including empty lines). */
        String nextLine() throws IOException {
            return br.readLine();
        }
    }

    /**
     * Maintains a character array and the count of adjacent '.' pairs.
     * All operations run in constant time.
     */
    private static final class DotTracker {
        private final char[] data;          // the underlying character array
        private final int length;           // length of the array
        private long adjacentPairs;         // current number of ".." pairs

        /**
         * Constructs a tracker from an existing character array.
         *
         * @param src the source array (will be copied)
         * @param n   length of the logical string
         */
        DotTracker(char[] src, int n) {
            this.data = src.clone();          // work on a copy
            this.length = n;
            this.adjacentPairs = computeInitialPairs();
        }

        /** Calculates the initial number of adjacent '.' pairs. */
        private long computeInitialPairs() {
            long pairs = 0;
            for (int i = 1; i < length; i++) {
                if (data[i] == '.' && data[i - 1] == '.') {
                    pairs++;
                }
            }
            return pairs;
        }

        /**
         * Updates the character at {@code index} to {@code newChar} and returns the
         * new number of adjacent '.' pairs.
         *
         * @param index   position to modify (0‑based)
         * @param newChar the replacement character
         * @return the updated count of adjacent '.' pairs
         */
        long update(int index, char newChar) {
            char oldChar = data[index];
            if (oldChar == newChar) {
                return adjacentPairs; // nothing to do
            }

            // ----- removal of a '.' -------------------------------------------------
            if (oldChar == '.') {
                int dec = 0;
                if (index > 0 && data[index - 1] == '.') dec++;
                if (index + 1 < length && data[index + 1] == '.') dec++;
                adjacentPairs -= dec;
            }

            // ----- insertion of a '.' -----------------------------------------------
            if (newChar == '.') {
                int inc = 0;
                if (index > 0 && data[index - 1] == '.') inc++;
                if (index + 1 < length && data[index + 1] == '.') inc++;
                adjacentPairs += inc;
            }

            // Apply the change
            data[index] = newChar;
            return adjacentPairs;
        }

        /** Returns the current count of adjacent '.' pairs. */
        long getCount() {
            return adjacentPairs;
        }
    }

    /** Entry point of the program. */
    public static void main(String[] args) throws IOException {
        FastScanner fs = new FastScanner(System.in);

        int n = fs.nextInt();          // length of the initial string
        int m = fs.nextInt();          // number of queries

        // Consume the rest of the line after n and m, then read the actual string.
        fs.nextLine();                 // discard newline left by nextInt()
        String line = fs.nextLine();   // the string of length n
        char[] chars = line.toCharArray();

        DotTracker tracker = new DotTracker(chars, n);

        StringBuilder output = new StringBuilder();
        for (int i = 0; i < m; i++) {
            int pos = fs.nextInt() - 1;                 // problem uses 1‑based indexing
            char newChar = fs.next().charAt(0);         // replacement character

            tracker.update(pos, newChar);
            output.append(tracker.getCount()).append('\n');
        }

        System.out.print(output.toString());
    }
}

import java.io.*;
import java.util.*;

public class Replacement {

    /** Sentinel characters used to bound the input string. */
    private static final char SENTINEL = '#';

    public static void main(String[] args) throws IOException {
        try (FasterScanner sc = new FasterScanner()) {
            runWorkflow(sc);
        }
    }

    /** Coordinates reading input, performing the initial calculation, and processing updates. */
    private static void runWorkflow(FasterScanner sc) {
        // ----- read problem parameters -------------------------------------------------
        int N = sc.nextInt();               // length of the original string
        int M = sc.nextInt();               // number of updates

        // ----- read the string surrounded by sentinels -------------------------------
        String raw = sc.nextLine();         // consumes the rest of the line after N and M
        char[] buffer = (SENTINEL + raw + SENTINEL).toCharArray();

        // ----- compute the initial value of `sum` as defined in the original code -----
        int currentSum = calculateInitialSum(buffer);

        // ----- process each update and collect results ---------------------------------
        StringBuilder output = new StringBuilder();

        for (int i = 0; i < M; i++) {
            int position = sc.nextInt();
            String token = sc.nextString();
            char newChar = token.charAt(0);

            updateBufferAndSum(buffer, position, newChar, currentSum);
            output.append(currentSum).append('\n');
        }

        System.out.print(output.toString());
    }

    /** Calculates the initial `sum` based on blocks of consecutive '.' characters. */
    private static int calculateInitialSum(char[] arr) {
        int sum = 0;
        int consecutiveDots = 0;

        for (char c : arr) {
            if (c != '.') {
                // block of dots ends – contribute max(0, length‑1)
                sum += Math.max(0, consecutiveDots - 1);
                consecutiveDots = 0;
            } else {
                consecutiveDots++;
            }
        }
        return sum;
    }

    /**
     * Updates the character at {@code index} and adjusts {@code currentSum}
     * according to the change.
     */
    private static void updateBufferAndSum(char[] arr, int index, char newChar, int currentSum) {
        char oldChar = arr[index];

        // No effective change – nothing to do
        if (oldChar == newChar) {
            return;
        }

        // How many neighboring '.' characters existed before the change?
        int neighboursBefore = countAdjacentDots(arr, index);

        // Apply the modification
        arr[index] = newChar;

        // How many neighboring '.' characters exist now?
        int neighboursAfter = countAdjacentDots(arr, index);

        // Adjust the global sum based on the transition
        if (oldChar == '.' && newChar != '.') {
            // Turning a '.' into a non‑'.' removes its isolated‑dot contribution
            currentSum -= neighboursBefore;
        } else if (oldChar != '.' && newChar == '.') {
            // Turning a non‑'.' into a '.' may create isolated‑dot contributions
            currentSum += neighboursAfter;
        }
        // Otherwise the contribution stays unchanged
    }

    /** Returns the number of neighbours (left and right) of {@code pos} that are '.'. */
    private static int countAdjacentDots(char[] arr, int pos) {
        int count = 0;
        if (arr[pos - 1] == '.') count++;
        if (arr[pos + 1] == '.') count++;
        return count;
    }

    /** Fast scanner implementation that mimics the behaviour of the original one. */
    public static final class FasterScanner {
        private final byte[] buffer = new byte[1 << 16];
        private int pointer = 0;
        private int length = 0;

        private int readByte() throws IOException {
            if (pointer >= length) {
                length = System.in.read(buffer);
                pointer = 0;
                if (length <= 0) return -1;
            }
            return buffer[pointer++];
        }

        private boolean isSpace(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        private int skipNonSpace() throws IOException {
            int c;
            do {
                c = readByte();
            } while (isSpace(c));
            return c;
        }

        public String nextLine() throws IOException {
            StringBuilder sb = new StringBuilder();
            int c = skipNonSpace();
            while (!isEndOfLine(c)) {
                sb.append((char) c);
                c = readByte();
            }
            return sb.toString();
        }

        public String nextString() throws IOException {
            StringBuilder sb = new StringBuilder();
            int c = skipNonSpace();
            while (!isSpace(c) && c != -1) {
                sb.append((char) c);
                c = readByte();
            }
            return sb.toString();
        }

        public long nextLong() throws IOException {
            int c = skipNonSpace();
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = readByte();
            }
            long value = 0;
            while (!isSpace(c) && c != -1) {
                if (c < '0' || c > '9') throw new InputMismatchException();
                value = value * 10 + (c - '0');
                c = readByte();
            }
            return value * sign;
        }

        public int nextInt() throws IOException {
            int c = skipNonSpace();
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = readByte();
            }
            int value = 0;
            while (!isSpace(c) && c != -1) {
                if (c < '0' || c > '9') throw new InputMismatchException();
                value = value * 10 + (c - '0');
                c = readByte();
            }
            return value * sign;
        }

        private boolean isEndOfLine(int c) {
            return c == '\n' || c == '\r' || c == -1;
        }
    }
}

import java.io.*;
import java.util.StringTokenizer;

/**
 * Entry point of the program.
 * Reads from {@code System.in} and writes the answers to {@code System.out}.
 */
public class Solution {

    /** Number of queries to process. */
    private static final int NUMBER_OF_TESTS = 1;

    public static void main(String[] args) throws IOException {
        InputReader reader = new InputReader(System.in);
        PrintWriter writer = new PrintWriter(System.out);

        Solver solver = new Solver();
        solver.solve(NUMBER_OF_TESTS, reader, writer);

        writer.flush();
    }

    /**
     * Solves {@code TaskC} – the “Replace '.'” problem.
     *
     * @param testCount number of test cases (currently always 1)
     * @param reader    input helper
     * @param out       output printer
     */
    static class Solver {

        /** Holds the current string in mutable {@code char[]} form. */
        private char[] chars;

        /** Current value of the answer (number of required moves). */
        private int moves;

        /** Reads the data for a single test case and processes all queries. */
        void solve(int testCount, InputReader reader, PrintWriter out) {
            int n = reader.nextInt();
            int q = reader.nextInt();

            // Store the initial string as a mutable character array.
            chars = reader.next().toCharArray();
            computeInitialMoves();

            // Process each query.
            for (int i = 0; i < q; i++) {
                int idx = reader.nextInt() - 1;          // 0‑based index
                char newChar = reader.next().charAt(0);
                updateMovesOnChange(idx, newChar);
                out.println(moves);
            }
        }

        /** Calculates the initial number of moves based on the starting character array. */
        private void computeInitialMoves() {
            moves = 0;
            int consecutiveDots = 0;

            for (char ch : chars) {
                if (ch == '.') {
                    consecutiveDots++;
                } else {
                    if (consecutiveDots > 0) {
                        moves += consecutiveDots - 1;
                        consecutiveDots = 0;
                    }
                }
            }
            if (consecutiveDots > 0) {
                moves += consecutiveDots - 1;
            }
        }

        /**
         * Adjusts {@code moves} when a character at {@code index} is replaced by {@code newChar}.
         *
         * @param index    position to modify (0‑based)
         * @param newChar  character to place at {@code index}
         */
        private void updateMovesOnChange(int index, char newChar) {
            char oldChar = chars[index];

            // No change → nothing to do.
            if (oldChar == newChar) {
                return;
            }

            boolean wasDot = oldChar == '.';
            boolean isDot   = newChar == '.';

            // Transition: '.' → non‑'.'
            if (isDot && !wasDot) {
                addMovesForCreatingDot(index);
            }
            // Transition: non‑'.' → '.'
            else if (!isDot && wasDot) {
                subtractMovesForRemovingDot(index);
            }

            // Perform the substitution.
            chars[index] = newChar;
        }

        /** Updates {@code moves} when a '.' is inserted between existing '.' characters. */
        private void addMovesForCreatingDot(int idx) {
            boolean leftDot  = idx > 0 && chars[idx - 1] == '.';
            boolean rightDot = idx < chars.length - 1 && chars[idx + 1] == '.';

            if (leftDot && rightDot) {
                moves += 2;
            } else if (leftDot || rightDot) {
                moves += 1;
            }
        }

        /** Updates {@code moves} when a '.' is removed (converted to a non‑'.' character). */
        private void subtractMovesForRemovingDot(int idx) {
            boolean leftDot  = idx > 0 && chars[idx - 1] == '.';
            boolean rightDot = idx < chars.length - 1 && chars[idx + 1] == '.';

            if (leftDot && rightDot) {
                moves -= 2;
            } else if (leftDot || rightDot) {
                moves -= 1;
            }
        }
    }

    /**
     * Fast tokenized input reader. Handles {@code String}, {@code int},
     * and other primitive token types needed by the solver.
     */
    private static class InputReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        InputReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
        }

        private void ensureTokenizer() {
            if (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
        }

        String next() {
            ensureTokenizer();
            return tokenizer.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

/**
 * Solves the problem described in the original source file.
 * The program reads two integers (n, m) and a string of length n,
 * then processes m updates. After each update it prints the
 * number of “fragment” occurrences that remain in the string.
 */
public class Main {

    /** Symbol that represents a “dot” in the input string. */
    private static final char DOT = '.';

    private final StringBuilder output = new StringBuilder();

    /**
     * Entry point of the program.
     */
    public static void main(String[] args) throws IOException {
        new Main().run();
        System.out.print(instance.output);
    }

    /**
     * Contains all the logic required to read the input, process the updates
     * and generate the required output.
     */
    private void run() throws IOException {
        try (InputReader reader = new InputReader(System.in)) {
            solve(reader);
        }
    }

    /**
     * Core algorithm – parses the initial string, registers the number of
     * continuous '.' fragments and updates that count while processing
     * each modification.
     */
    private void solve(InputReader reader) {
        int n = reader.nextInt();          // length of the string (unused directly)
        int operations = reader.nextInt(); // number of modifications
        String initial = reader.next();    // the original string

        char[] chars = initial.toCharArray();
        int fragments = countFragments(chars);

        for (int i = 0; i < operations; i++) {
            int index = reader.nextInt() - 1; // 0‑based index
            char newChar = reader.next().charAt(0);

            fragments = updateFragmentCount(chars, index, newChar, fragments);
            output.append(fragments).append('\n');
        }
    }

    /**
     * Counts how many continuous '.' sequences exist in the given array.
     *
     * @param chars the character array to scan
     * @return the number of dot‑fragments
     */
    private static int countFragments(char[] chars) {
        int fragmentCount = 0;
        int idx = 0;

        while (idx < chars.length) {
            if (chars[idx] == DOT) {
                fragmentCount++;
                // skip the whole block of consecutive dots
                while (idx < chars.length && chars[idx] == DOT) {
                    idx++;
                }
            } else {
                idx++;
            }
        }
        return fragmentCount;
    }

    /**
     * Adjusts the fragment count after a single character change.
     *
     * @param chars          mutable character array
     * @param index          position that is being modified
     * @param newChar        the character to write at {@code index}
     * @param currentFragments current number of dot‑fragments
     * @return the updated fragment count
     */
    private static int updateFragmentCount(char[] chars,
                                           int index,
                                           char newChar,
                                           int currentFragments) {
        boolean wasDot = chars[index] == DOT;
        boolean willBeDot = newChar == DOT;

        // No change? nothing to adjust.
        if (wasDot == willBeDot) {
            return currentFragments;
        }

        // Transition dot → non‑dot
        if (wasDot && !willBeDot) {
            // Remove the fragment that included this position.
            // The surrounding characters may have been part of a larger block,
            // therefore we decrement by the size of that block minus one.
            int decrement = calculateFragmentDecrement(chars, index);
            return currentFragments - decrement;
        }

        // Transition non‑dot → dot
        // Insert a new fragment or merge adjacent fragments.
        return currentFragments + calculateFragmentIncrement(chars, index);
    }

    /**
     * Calculates how many dot‑fragments disappear when the character at
     * {@code index} changes from '.' to something else.
     * The decrement equals the length of the block that contained the index,
     * minus one (because the block disappears completely).
     *
     * @return number of fragments to subtract
     */
    private static int calculateFragmentDecrement(char[] chars, int index) {
        // Determine the size of the contiguous block that includes index.
        int left = stepBackUntilNonDot(chars, index);
        int right = stepForwardUntilNonDot(chars, index);
        int blockSize = right - left - 1; // block length
        // Each block contributes exactly one fragment, so decrement is 1.
        // However, when a block is split by previous modifications,
        // the formula below correctly reflects the remaining fragments.
        return Math.max(0, blockSize - 1);
    }

    /**
     * Calculates how many dot‑fragments appear when a non‑dot is changed to '.'.
     * The increment can be 1 (new isolated fragment) or 0/‑1 when merging.
     *
     * @return number of fragments to add
     */
    private static int calculateFragmentIncrement(char[] chars, int index) {
        // Is there a dot immediately to the left or right?
        boolean leftIsDot = index > 0 && chars[index - 1] == DOT;
        boolean rightIsDot = index < chars.length - 1 && chars[index + 1] == DOT;

        // If both sides are dots, we merge two existing fragments -> net change 0.
        // If only one side is a dot, we extend that fragment -> net change 0 as well.
        // If neither side is a dot, we create a new isolated fragment -> +1.
        return leftIsDot && rightIsDot ? 0 : (leftIsDot || rightIsDot ? 0 : 1);
    }

    /**
     * Moves backward from {@code start} until a character different from '.'
     * is encountered.
     */
    private static int stepBackUntilNonDot(char[] chars, int start) {
        int pos = start;
        while (pos >= 0 && chars[pos] == DOT) {
            pos--;
        }
        return pos;
    }

    /**
     * Moves forward from {@code start} until a character different from '.'
     * is encountered.
     */
    private static int stepForwardUntilNonDot(char[] chars, int start) {
        int pos = start;
        while (pos < chars.length && chars[pos] == DOT) {
            pos++;
        }
        return pos;
    }
}

/**
 * Simple wrapper around {@link BufferedReader} that supplies tokenised input.
 */
class InputReader {
    private final BufferedReader br;
    private StringTokenizer st;

    public InputReader(InputStream stream) {
        this.br = new BufferedReader(new InputStreamReader(stream));
    }

    /** Returns the next token, reading a new line if necessary. */
    String next() throws IOException {
        while (st == null || !st.hasMoreTokens()) {
            String line = br.readLine();
            if (line == null) {
                return null;
            }
            st = new StringTokenizer(line);
        }
        return st.nextToken();
    }

    /** Convenience method for reading an integer. */
    int nextInt() throws IOException {
        return Integer.parseInt(next());
    }

    /** Returns the rest of the current line. */
    String nextLine() throws IOException {
        return br.readLine();
    }

    /** Checks whether there is unread data ready. */
    boolean ready() throws IOException {
        return br.ready();
    }
}

import java.io.BufferedReader;
import java.io.IOException;

/**
 * Refactored version of the original program.
 * Reads a string, counts overlapping ".." substrings and processes a series of
 * updates, printing the current count after each update.
 */
public class Main {

    public static void main(String[] args) throws IOException {
        // Use try‑with‑resources to guarantee the reader is closed.
        try (BufferedReader br = new BufferedReader(
                new java.io.InputStreamReader(System.in))) {

            // ----- read header -----
            String[] header = br.readLine().split("\\s+");
            int length = Integer.parseInt(header[0]);   // size of the sequence
            int updates = Integer.parseInt(header[1]);  // number of modifications

            // ----- read initial state -----
            char[] state = br.readLine().toCharArray();

            // ----- initial count of ".." patterns -----
            int doubleDotCount = countDoubleDots(state, length);

            // ----- process each update -----
            for (int i = 0; i < updates; i++) {
                String[] parts = br.readLine().split("\\s+");
                int index = Integer.parseInt(parts[0]) - 1; // convert to 0‑based index
                char newChar = parts[1].charAt(0);
                char oldChar = state[index];

                if (oldChar != newChar) {
                    // ---- remove contributions of the old character ----
                    if (oldChar == '.') {
                        if (index > 0 && state[index - 1] == '.') {
                            doubleDotCount--;
                        }
                        if (index < length - 1 && state[index + 1] == '.') {
                            doubleDotCount--;
                        }
                    }

                    // ---- add contributions of the new character ----
                    if (newChar == '.') {
                        if (index > 0 && state[index - 1] == '.') {
                            doubleDotCount++;
                        }
                        if (index < length - 1 && state[index + 1] == '.') {
                            doubleDotCount++;
                        }
                    }

                    // ---- apply the modification ----
                    state[index] = newChar;
                }

                // ---- output the current count ----
                System.out.println(doubleDotCount);
            }
        }
    }

    /**
     * Counts the number of overlapping ".." substrings in the given array.
     *
     * @param arr  character array to scan
     * @param size length of the relevant prefix of {@code arr}
     * @return     number of occurrences of two consecutive dots
     */
    private static int countDoubleDots(char[] arr, int size) {
        int count = 0;
        for (int i = 0; i < size - 1; i++) {
            if (arr[i] == '.' && arr[i + 1] == '.') {
                count++;
            }
        }
        return count;
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
