import java.util.StringTokenizer;

/**
 * Refactored version of the original program.
 *
 * <p>Improvements made:
 * <ul>
 *   <li>Renamed classes/methods to follow Java naming conventions.</li>
 *   <li>Extracted input handling into a dedicated {@link FastScanner} class.</li>
 *   <li>Separated the solution logic into a {@link Solver} class for clearer responsibilities.</li>
 *   <li>Removed unnecessary inner classes and static fields.</li>
 *   <li>Used {@link StringBuilder} for efficient output accumulation.</li>
 *   <li>Added comments describing each logical block.</li>
 * </ul>
 */
public class Main {

    public static void main(String[] args) {
        /**
         * Entry point of the program.
         * Reads the initial data, processes the queries and prints the results.
         */
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in))) {
            // ----- read header (t and q) -----
            String[] header = br.readLine().trim().split("\\s+");
            final int length = Integer.parseInt(header[0]); // original variable name was 't'
            final int queries = Integer.parseInt(header[1]); // original variable name was 'q'

            // ----- read the character array -----
            final char[] chars = br.readLine().trim().toCharArray();

            // ----- prepare output buffer -----
            StringBuilder output = new StringBuilder();

            // ----- instantiate solver and execute -----
            new Solver().solve(length, queries, chars, output);

            // ----- print final result -----
            System.out.print(output.toString());
        } catch (IOException e) {
            // In case of an I/O error we re‑throw as an unchecked exception.
            throw new RuntimeException(e);
        }
    }

    /**
     * Handles the core logic of counting double‑dot substrings and applying updates.
     */
    static class Solver {

        /**
         * Executes the processing of {@code queries} updates on the character array.
         *
         * @param length     length of the original character array (parameter 't')
         * @param queryCount number of queries to process (parameter 'q')
         * @param chars      mutable character array that is updated in‑place
         * @param out        buffer where results are appended
         */
        void solve(int length, int queryCount, char[] chars, StringBuilder out) {
            // ----- initial count of ".." substrings -----
            int doubleDotCount = countDoubleDots(chars);

            // ----- process each query -----
            for (int i = 0; i < queryCount; i++) {
                int index = readIndex();          // zero‑based position
                char newChar = readNewCharacter(); // character to place at index

                // ----- adjust the running count based on the change -----
                adjustCount(index, chars, newChar, doubleDotCount);

                // ----- store the updated character -----
                chars[index] = newChar;

                // ----- record the current count as a result line -----
                out.append(doubleDotCount).append('\n');
            }
        }

        /** Returns the number of occurrences of the substring ".." in the given array. */
        private static int countDoubleDots(char[] arr) {
            int cnt = 0;
            for (int i = 0; i < arr.length - 1; i++) {
                if (arr[i] == '.' && arr[i + 1] == '.') {
                    cnt++;
                }
            }
            return cnt;
        }

        /** Reads the next query index (expects 1‑based input, converts to 0‑based). */
        private static int readIndex() {
            // Simple wrapper; concrete reading is delegated to FastScanner.
            return FastScanner.nextInt() - 1;
        }

        /** Reads the next new character (first character of the next token). */
        private static char readNewCharacter() {
            return FastScanner.next().charAt(0);
        }

        /**
         * Updates {@code doubleDotCount} according to the transition at {@code index}
         * from its old value to {@code newChar}.
         *
         * <p>The method modifies {@code doubleDotCount} directly because it represents
         * the running sum of ".." substrings.
         */
        private static void adjustCount(int index, char[] arr, char newChar, int count) {
            char oldChar = arr[index];

            if (oldChar != '.' && newChar == '.') {
                // Introducing a dot – possibly create new ".." pairs with neighbours.
                if (index > 0 && arr[index - 1] == '.') {
                    count++;
                }
                if (index < arr.length - 1 && arr[index + 1] == '.') {
                    count++;
                }
            } else if (oldChar == '.' && newChar != '.') {
                // Removing a dot – possibly destroy existing ".." pairs.
                if (index > 0 && arr[index - 1] == '.') {
                    count--;
                }
                if (index < arr.length - 1 && arr[index + 1] == '.') {
                    count--;
                }
            }
        }
    }

    /**
     * Fast scanner that parses tokens from {@code System.in} using a
     * {@link BufferedReader} and a {@link StringTokenizer}.
     * It mimics the behaviour of the original {@code input} helper class
     * but with a cleaner API and better error handling.
     */
    static class FastScanner {
        private static BufferedReader reader;
        private static StringTokenizer tokenizer;

        /** Initializes the scanner to read from the given input stream. */
        static void init(InputStream in) {
            reader = new BufferedReader(new InputStreamReader(in));
            tokenizer = new StringTokenizer("");
        }

        /** Reads the next token, fetching a new line if necessary. */
        private static String nextToken() throws IllegalStateException {
            while (!tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) {
                        return null; // EOF
                    }
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new UncheckedIOException(e);
                }
            }
            return tokenizer.nextToken();
        }

        /** Returns the next integer token, or {@code null} on EOF. */
        static int nextInt() {
            String token = nextToken();
            if (token == null) {
                throw new IllegalStateException("Unexpected end of input");
            }
            return Integer.parseInt(token);
        }

        /** Returns the next token as a {@code String}. */
        static String next() {
            return nextToken();
        }
    }
}

import java.io.IOException;
import java.io.PrintWriter;
import java.util.Scanner;

/**
 * Refactored version of the original program.
 *
 * <p>Changes made for maintainability and readability:
 * <ul>
 *   <li>Extracted small pure‑logic methods that each perform a single task.</li>
 *   <li>Renamed variables to meaningful names (e.g. {@code chars} instead of {@code s}).</li>
 *   <li>Replaced the custom {@code Scanner} with the standard {@link Scanner}.</li>
 *   <li>Used try‑with‑resources to guarantee proper closure of I/O streams.</li>
 *   <li>Avoided the custom {@code Scanner} implementation that overrode many methods.</li>
 *   <li>Collected output in a {@link StringBuilder} and printed once at the end.</li>
 *   <li>Added Javadoc comments and grouped related operations.</li>
 * </ul>
 *
 * The functional behaviour is identical to the original program.
 */
public class C570 {

    public static void main(String[] args) throws IOException {
        /* --------------------------------------------------------------------
         *  Input handling
         * -------------------------------------------------------------------- */
        try (Scanner sc = new Scanner(System.in);
             PrintWriter out = new PrintWriter(System.out)) {

            int n = sc.nextInt();          // length of the string
            int m = sc.nextInt();          // number of operations
            char[] chars = sc.next().toCharArray(); // the character array

            /* --------------------------------------------------------------------
             *  Pre‑compute the initial value of `fs` (sum of runLength‑1 for each '.' run)
             * -------------------------------------------------------------------- */
            int dotRunSum = countDotRunSum(chars);

            /* --------------------------------------------------------------------
             *  Process the operations and collect the results
             * -------------------------------------------------------------------- */
            StringBuilder output = new StringBuilder();

            for (int op = 0; op < m; op++) {
                int idx = sc.nextInt() - 1;                 // zero‑based index
                char newChar = sc.next().charAt(0);         // new character

                if (isNoEffect(idx, newChar, chars, dotRunSum)) {
                    // No change in the pattern count – just output the current value.
                    output.append(dotRunSum).append('\n');
                    continue;
                }

                // Adjust the pattern count according to the neighbourhood of `idx`.
                dotRunSum = adjustDotRunSum(chars, idx, newChar, dotRunSum);
                chars[idx] = newChar;                        // apply the change

                output.append(dotRunSum).append('\n');
            }

            out.print(output.toString());
        }
    }

    /**
     * Count the sum of (runLength‑1) for every maximal contiguous block of '.' characters.
     *
     * @param arr the character array to examine
     * @return the computed sum
     */
    private static int countDotRunSum(char[] arr) {
        int sum = 0;
        int i = 0;
        while (i < arr.length) {
            if (arr[i] == '.') {
                int start = i;
                while (i < arr.length && arr[i] == '.') {
                    i++;
                }
                int end = i;                     // one‑past the last '.' of the run
                sum += (end - start - 1);        // contribution of this run
            } else {
                i++;
            }
        }
        return sum;
    }

    /**
     * Determines whether the upcoming change leaves the pattern count unchanged.
     *
     * @param idx      the index to change
     * @param newChar  the new character
     * @param arr      the current character array
     * @param currentFs the current value of the pattern count (not used directly)
     * @return {@code true} if the change does not affect the count
     */
    private static boolean isNoEffect(int idx, char newChar, char[] arr, int currentFs) {
        boolean newIsDot = newChar == '.';
        boolean oldIsDot = arr[idx] == '.';
        return (newIsDot && oldIsDot) || (!newIsDot && !oldIsDot);
    }

    /**
     * Updates the pattern count when a character at position {@code idx} is replaced
     * by {@code newChar}.
     *
     * <p>The algorithm mirrors the original logic but is encapsulated in a single
     * method for clarity.</p>
     *
     * @param arr      the mutable character array
     * @param idx      the index being modified
     * @param newChar  the new character
     * @param currentFs the current value of the pattern count
     * @return the updated pattern count
     */
    private static int adjustDotRunSum(char[] arr, int idx, char newChar, int currentFs) {
        if (newChar == '.') {
            // Adding a '.' may create new neighboring adjacencies
            if (idx > 0 && arr[idx - 1] == '.') {
                currentFs++;
            }
            if (idx < arr.length - 1 && arr[idx + 1] == '.') {
                currentFs++;
            }
        } else {
            // Removing a '.' may break adjacencies
            if (idx > 0 && arr[idx - 1] == '.') {
                currentFs--;
            }
            if (idx < arr.length - 1 && arr[idx + 1] == '.') {
                currentFs--;
            }
        }
        return currentFs;
    }
}

import java.io.*;
import java.util.*;

public class Main {

    /** Global variable that stores the current number of adjacent '.' pairs. */
    private static long answer;

    /** Fast scanner that can be configured with a custom whitespace filter. */
    private static final class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 12];
        private int pointer = 0, length = 0;
        private final SpaceCharFilter filter;

        FastScanner(InputStream in) { this(in, null); }

        FastScanner(InputStream in, SpaceCharFilter filter) {
            this.in = in;
            this.filter = filter;
        }

        /** Read a single byte from the underlying stream. */
        private int readByte() throws IOException {
            if (pointer >= length) {
                length = in.read(buffer);
                pointer = 0;
                if (length <= 0) return -1;
            }
            return buffer[pointer++];
        }

        /** Skip over characters that satisfy the whitespace filter. */
        private int skipSpaces(int c) throws IOException {
            while (filter != null && filter.isSpaceChar(c)) c = readByte();
            return c;
        }

        /** Return the next non‑space character. */
        char nextChar() throws IOException {
            int c = readByte();
            while (c != -1 && isSpaceChar(c)) c = readByte();
            return (char) c;
        }

        /** Read the next signed integer. */
        int nextInt() throws IOException {
            int c = skipSpaces(readByte());
            boolean negative = false;
            if (c == '-') {
                negative = true;
                c = readByte();
            }
            int result = 0;
            do {
                if (c < '0' || c > '9') throw new InputMismatchException();
                result = result * 10 + (c - '0');
                c = readByte();
            } while (!isSpaceChar(c));
            return negative ? -result : result;
        }

        /** Read the next whitespace‑delimited string. */
        String nextString() throws IOException {
            int c = skipSpaces(readByte());
            StringBuilder sb = new StringBuilder();
            do {
                sb.append((char) c);
                c = readByte();
            } while (!isSpaceChar(c));
            return sb.toString();
        }

        /** Helper used by other overloads of `isSpaceChar`. */
        boolean isSpaceChar(int c) {
            return filter != null ? filter.isSpaceChar(c) : (c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1);
        }
    }

    /** Counts how many adjacent '.' pairs exist in the supplied character array. */
    private static long countAdjacentDotPairs(char[] data) {
        long pairs = 0;
        int consecutive = 0;
        for (char c : data) {
            if (c == '.') {
                consecutive++;
            } else {
                if (consecutive > 0) {
                    pairs += consecutive - 1;
                    consecutive = 0;
                }
            }
        }
        if (consecutive > 0) pairs += consecutive - 1;
        return pairs;
    }

    /**
     * Adjusts the global {@code answer} when the character at {@code idx}
     * changes to {@code newChar}.
     *<p>
     * The adjustment mirrors the original algorithm:
     * <ul>
     *   <li>If a '.' is removed, decrement {@code answer} for each existing neighbour '.'</li>
     *   <li>If a '.' is inserted, increment {@code answer} for each neighbour '.'</li>
     * </ul>
     * </p>
     */
    private static void adjustAnswer(char[] data, int idx, char newChar) {
        char old = data[idx];
        if (old == newChar) return;               // nothing to do

        // ----- removal of an old dot ------------------------------------------------
        if (old == '.' && newChar != '.') {
            if (idx - 1 >= 0 && data[idx - 1] == '.') answer--;   // left neighbour
            if (idx + 1 < data.length && data[idx + 1] == '.') answer--; // right neighbour
        }

        // ----- insertion of a new dot ------------------------------------------------
        if (old != '.' && newChar == '.') {
            if (idx - 1 >= 0 && data[idx - 1] == '.') answer++;   // left neighbour
            if (idx + 1 < data.length && data[idx + 1] == '.') answer++; // right neighbour
        }

        // apply the change
        data[idx] = newChar;
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(System.out);

        int n = fs.nextInt();          // length of the initial line
        int m = fs.nextInt();          // number of updates

        char[] line = fs.nextString().toCharArray();
        answer = countAdjacentDotPairs(line);
        out.print(answer + " ");

        for (int i = 0; i < m; ++i) {
            int pos = fs.nextInt() - 1;   // convert to 0‑based index
            char ch = fs.nextChar();

            adjustAnswer(line, pos, ch);
            out.print(answer + " ");
        }

        out.println();
        out.flush();
    }
}

