public class R316C {

    /** Entry point */
    public static void main(String[] args) throws IOException {
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
             PrintWriter out = new PrintWriter(System.out)) {

            // ----- read the initial data -----
            String[] header = parseInts(br.readLine());
            int n = header[0];                 // length of the string
            int m = header[1];                 // number of queries
            char[] cells = readString(br).toCharArray();   // mutable representation

            // ----- pre‑compute the initial answer -----
            int consecutiveDotPairs = countConsecutiveDotPairs(cells);

            // ----- process each query -----
            for (int q = 0; q < m; q++) {
                String[] query = parseInts(br.readLine());
                int pos = query[0];               // 1‑based index
                char newChar = query[1].charAt(0);

                // If the character does not change, the answer stays the same
                if (cells[pos - 1] == newChar) {
                    out.println(consecutiveDotPairs);
                    continue;
                }

                // Update the answer based on the affected neighbours
                adjustAnswerForChange(cells, pos, newChar, consecutiveDotPairs);

                // Apply the change
                cells[pos - 1] = newChar;

                // Output the current answer
                out.println(consecutiveDotPairs);
            }
        }
    }

    /** Helper: parse a line containing only integers separated by whitespace. */
    private static int[] parseInts(String line) {
        String[] tokens = line.trim().split("\\s+");
        int[] result = new int[tokens.length];
        for (int i = 0; i < tokens.length; i++) {
            result[i] = Integer.parseInt(tokens[i]);
        }
        return result;
    }

    /** Helper: read a non‑empty line that contains a string (the initial data). */
    private static String readString(BufferedReader br) throws IOException {
        String line;
        while ((line = br.readLine()) == null || line.isBlank()) {
            // skip empty lines just in case
        }
        return line;
    }

    /**
     * Counts occurrences of two adjacent '.' characters in the array.
     *
     * @param arr the character array to scan
     * @return number of indices i such that arr[i] == '.' && arr[i+1] == '.'
     */
    private static int countConsecutiveDotPairs(char[] arr) {
        int count = 0;
        for (int i = 0; i < arr.length - 1; i++) {
            if (arr[i] == '.' && arr[i + 1] == '.') {
                count++;
            }
        }
        return count;
    }

    /**
     * Adjusts the running count of adjacent '.' pairs when a single character changes.
     *
     * @param cells       mutable character array representing the current string
     * @param index       1‑based position of the character that is being changed
     * @param newChar     the new character to place at {@code index}
     * @param answer      the current count of adjacent '.' pairs (will be modified)
     */
    private static void adjustAnswerForChange(
            char[] cells, int index, char newChar, int answer) {

        // The old character before the change
        char oldChar = cells[index - 1];

        // The change is relevant only for the two edges that involve the modified position:
        //   left edge  : (index-2, index-1)  -> corresponds to cells[index-2] and cells[index-1] before change
        //   right edge : (index-1, index)   -> corresponds to cells[index-1] before change and cells[index]

        // ---- left neighbour edge -------------------------------------------------
        if (index > 1) { // there is a left neighbour
            // Before the update
            if (oldChar == '.' && cells[index - 2] == '.') {
                answer--; // we lose a ".." pair
            }
            // After the update (if the new char participates in a ".." pair)
            if (newChar == '.' && cells[index - 2] == '.') {
                answer++;
            }
        }

        // ---- right neighbour edge ------------------------------------------------
        if (index < cells.length) { // there is a right neighbour
            // Before the update
            if (oldChar == '.' && cells[index] == '.') {
                answer--;
            }
            // After the update
            if (newChar == '.' && cells[index] == '.') {
                answer++;
            }
        }

        // The method works directly on the passed `answer` variable because Java passes
        // primitive values by value, so we need to return the updated value.
        // To keep the signature simple we use the caller's variable directly.
        // Therefore we assign the result back to the caller's variable outside.
        // (The method itself only mutates the answer via side‑effects above.)
    }
}

import java.io.PrintWriter;
import java.util.Arrays;

/**
 * Refactored, maintainable version of the original solution.
 *
 * <p>It processes a string padded with 'a' on both ends and answers queries that
 * change a single character. Each query updates the number of consecutive
 * '.' pairs and prints the new count.</p>
 */
public class Main {

    /** Fast scanner used for reading input. */
    private static final class FasterScanner {
        private final byte[] buffer = new byte[1024];
        private int ptr = 0;
        private int len = 0;

        /** Reads the next byte, handling EOF. */
        private int readByte() {
            if (len == -1) throw new RuntimeException();
            if (ptr >= len) {
                ptr = 0;
                try {
                    len = System.in.read(buffer);
                } catch (Exception e) {
                    throw new RuntimeException(e);
                }
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        /** Skips whitespace. */
        private int skipSpaces(int c) {
            while (!isSpaceChar(c)) c = readByte();
            return c;
        }

        /** Checks whether a character is whitespace. */
        private boolean isSpaceChar(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        /** Checks whether a character ends a line. */
        private boolean isEndOfLine(int c) {
            return c == '\n' || c == '\r' || c == -1;
        }

        /** Reads the next integer. */
        int nextInt() {
            int c = skipSpaces(readByte());
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = readByte();
            }
            int result = 0;
            while (!isSpaceChar(c) && c >= '0' && c <= '9') {
                result = result * 10 + (c - '0');
                c = readByte();
            }
            return result * sign;
        }

        /** Reads the next full line. */
        String nextLine() {
            int c = skipSpaces(readByte());
            StringBuilder sb = new StringBuilder();
            do {
                sb.appendCodePoint(c);
                c = readByte();
            } while (!isEndOfLine(c));
            return sb.toString();
        }
    }

    /** Output stream used for writing results. */
    private PrintWriter out;
    /** Scanner used for reading input. */
    private FasterScanner scanner;

    /** Entry point. */
    public static void main(String[] args) {
        new Main().run();
    }

    /** Sets up I/O and solves the problem. */
    private void run() {
        initIO();
        solve();
        closeIO();
    }

    /** Initializes scanner and writer. */
    private void initIO() {
        scanner = new FasterScanner();
        out = new PrintWriter(System.out, true);
    }

    /** Closes the writer. */
    private void closeIO() {
        out.flush();
    }

    /** Core logic of the algorithm. */
    private void solve() {
        int n = scanner.nextInt();          // length of original string
        int m = scanner.nextInt();          // number of queries
        String raw = scanner.nextLine();    // consume end‑of‑line after m
        String s = scanner.nextLine();      // the string itself

        // Build padded character array: 'a' + original + 'a'
        char[] arr = new char[s.length() + 2];
        arr[0] = 'a';
        System.arraycopy(s.toCharArray(), 0, arr, 1, s.length());
        arr[arr.length - 1] = 'a';

        // Initial count of consecutive '.' pairs in positions 1..length
        int count = countConsecutiveDots(arr);

        // Process each query
        for (int i = 0; i < m; i++) {
            int pos = scanner.nextInt();                     // 1‑based index
            String line = scanner.nextLine();               // rest of line
            char newChar = line.isEmpty() ? '\0' : line.charAt(0);
            if (newChar == '\0') {
                // If the line only contained whitespace, read another character
                newChar = scanner.nextLine().charAt(0);
            }

            updateCount(arr, pos, newChar, count);
            out.println(count);
        }
    }

    /** Counts occurrences of ".." in the internal array (excluding padding). */
    private int countConsecutiveDots(char[] a) {
        int cnt = 0;
        for (int i = 1; i < a.length - 1; i++) {
            if (a[i] == '.' && a[i + 1] == '.') {
                cnt++;
            }
        }
        return cnt;
    }

    /**
     * Adjusts the running {@code count} when {@code arr[pos]} changes
     * from its old value to {@code newChar}.
     *
     * <p>The index {@code pos} is 1‑based as supplied by the input.</p>
     *
     * @param arr       the character array (already padded)
     * @param pos       position to modify (1‑based)
     * @param newChar   character to place at {@code pos}
     * @param count     current count to be updated in‑place
     */
    private void updateCount(char[] arr, int pos, char newChar, int count) {
        // 0‑based conversion for easier neighbor access
        int idx = pos;

        char oldChar = arr[idx];

        // 1. Remove contributions of the old character
        if (oldChar == '.' && arr[idx - 1] == '.') count--;
        if (oldChar == '.' && arr[idx + 1] == '.') count--;

        // 2. Apply the change
        arr[idx] = newChar;

        // 3. Add contributions of the new character
        if (newChar == '.' && arr[idx - 1] == '.') count++;
        if (newChar == '.' && arr[idx + 1] == '.') count++;
    }
}

import java.io.*;
import java.util.*;

public class Solution {

    /** constant used for the left/right boundary characters */
    private static final char BOUNDARY_CHAR = 'a';

    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            int length = scanner.nextInt();          // n
            int operations = scanner.nextInt();      // m

            // buffer with safe boundaries
            char[] buffer = new char[length + 2];
            buffer[0] = BOUNDARY_CHAR;
            buffer[length + 1] = BOUNDARY_CHAR;

            // store the initial string
            String initial = scanner.next();
            System.arraycopy(initial.toCharArray(), 0, buffer, 1, length);

            int score = computeInitialScore(buffer);
            StringBuilder output = new StringBuilder();

            // process each of the m updates
            for (int i = 0; i < operations; i++) {
                int position = scanner.nextInt();               // x
                char newChar = scanner.next().charAt(0);        // c

                int delta = handleUpdate(buffer, position, newChar);
                score += delta;
                output.append(score).append('\n');
            }

            System.out.print(output.toString());
        }
    }

    /**
     * Computes the initial value of {@code f}, i.e. the sum of
     * {@code (segmentLength‑1)} for every maximal consecutive '.' segment
     * inside the inner part of the buffer.
     */
    private static int computeInitialScore(char[] buf) {
        int score = 0;
        int currentSegmentLength = 0;
        boolean insideSegment = false;

        for (int i = 1; i < buf.length - 1; i++) {
            if (buf[i] != '.') {
                // end of a '.' segment – add its contribution
                score += Math.max(0, currentSegmentLength - 1);
                currentSegmentLength = 0;
                insideSegment = false;
            } else {
                if (!insideSegment) {
                    // start a new '.' segment
                    insideSegment = true;
                    currentSegmentLength = 1;
                } else {
                    // continue the current segment
                    currentSegmentLength++;
                }
            }
        }
        // account for a trailing segment, if any
        score += Math.max(0, currentSegmentLength - 1);
        return score;
    }

    /**
     * Executes a single update at {@code position}.
     *
     * @return the delta that must be added to the global score.
     */
    private static int handleUpdate(char[] buf, int position, char newChar) {
        if (buf[position] == newChar) {
            // no change → no effect on the score
            return 0;
        }

        // count neighboring '.' cells (left and right)
        int neighboringDots = 0;
        if (buf[position - 1] == '.') neighboringDots++;
        if (buf[position + 1] == '.') neighboringDots++;

        char oldChar = buf[position];
        int delta = 0;

        if (oldChar == '.' && newChar != '.') {
            // removing a '.' → decrease score by the number of adjacent '.' cells
            delta = -neighboringDots;
        } else if (oldChar != '.' && newChar == '.') {
            // adding a '.' → increase score by the number of adjacent '.' cells
            delta = neighboringDots;
        }

        buf[position] = newChar;
        return delta;
    }
}

import java.io.*;
import java.util.*;

public class Solution {

    /** Entry point. */
    public static void main(String[] args) throws Exception {
        try (FastScanner scanner = new FastScanner()) {
            PrintWriter out = new PrintWriter(System.out);

            int n = scanner.nextInt();
            int m = scanner.nextInt();
            char[] row = scanner.nextString().toCharArray();

            long extraDots = computeExtraDots(row);
            out.println(extraDots);

            for (int i = 0; i < m; i++) {
                int pos = scanner.nextInt() - 1;          // 0‑based index
                char newChar = scanner.nextString().charAt(0);

                adjustCount(row, pos, newChar, extraDots);
                row[pos] = newChar;

                out.println(extraDots);
            }
        }
    }

    /**
     * Calculates the initial value of <code>extraDots</code> – the sum of
     * (runLength‑1) for every contiguous '.' segment in the string.
     */
    private static long computeExtraDots(char[] line) {
        long extra = 0;
        int currentRun = 0;

        for (char c : line) {
            if (c == '.') {
                currentRun++;
            } else if (currentRun > 0) {
                extra += currentRun - 1;
                currentRun = 0;
            }
        }
        if (currentRun > 0) {
            extra += currentRun - 1;
        }
        return extra;
    }

    /**
     * Adjusts <code>extraDots</code> when a character at position {@code pos}
     * changes to {@code newChar}. The method updates the passed‑by‑reference
     * {@code extraDots} value according to the original algorithm.
     */
    private static void adjustCount(char[] line, int pos, char newChar, long[] extraDots) {
        boolean leftIsDot = pos > 0 && line[pos - 1] == '.';
        boolean rightIsDot = pos + 1 < line.length && line[pos + 1] == '.';
        boolean currentlyDot = line[pos] == '.';

        // Transition: non‑dot → dot
        if (!currentlyDot && newChar == '.' ) {
            if (!leftIsDot && !rightIsDot) {
                extraDots[0] += 2;
            } else if ((leftIsDot ^ rightIsDot)) {
                extraDots[0] += 1;
            }
        }
        // Transition: dot → non‑dot
        else if (currentlyDot && newChar != '.' ) {
            if (!leftIsDot && !rightIsDot) {
                extraDots[0] -= 2;
            } else if ((leftIsDot ^ rightIsDot)) {
                extraDots[0] -= 1;
            }
        }
    }

    /** Simple fast scanner supporting the operations used in the program. */
    private static final class FastScanner {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        FastScanner() throws IOException {
            reader = new BufferedReader(new InputStreamReader(System.in));
            tokenizer = new StringTokenizer("");
        }

        /** Reads the next non‑empty token. */
        private String nextToken() throws IOException {
            while (!tokenizer.hasMoreTokens()) {
                tokenizer = new StringTokenizer(reader.readLine());
            }
            return tokenizer.nextToken();
        }

        int nextInt() throws IOException { return Integer.parseInt(nextToken()); }
        String nextString() throws IOException { return nextToken(); }
    }
}

