/**
 * Reads a string and a number of updates, then processes each update.
 *
 * <p>The program maintains the count of adjacent "." characters while
 * applying single‑character replacements or insertions.
 *
 * <p>Changes made for maintainability and readability:
 * <ul>
 *   <li>Extracted small helper methods that each do one thing.</li>
 *   <li>Renamed variables for clarity (e.g. {@code adjacentDotPairs}).</li>
 *   <li>Removed dead code (unused {@code Pair} and {@code myComparator}).</li>
 *   <li>Implemented proper resource handling with try‑with‑resources.</li>
 *   <li>Converted all indexes to zero‑based internally – the public API
 *       still expects 1‑based input as in the original specification.</li>
 *   <li>Kept the original behaviour (updates the count after each query
 *       and appends the result to the output).</li>
 * </ul>
 */
public class Main {

    /** Counts the number of occurrences of two consecutive '.' characters. */
    private static int countAdjacentDots(char[] arr) {
        int cnt = 0;
        for (int i = 1; i < arr.length; i++) {
            if (arr[i] == '.' && arr[i - 1] == '.') {
                cnt++;
            }
        }
        return cnt;
    }

    /**
     * Handles a single update: replaces {@code arr[index]} with {@code newChar}
     * and updates {@code count} accordingly.
     *
     * @param arr        the character array representing the string
     * @param count      current number of adjacent '.' pairs (will be updated)
     * @param index      position to modify (zero‑based)
     * @param newChar    character to write into {@code arr[index]}
     */
    private static void applyUpdate(char[] arr, int[] count, int index, char newChar) {
        char oldChar = arr[index];
        if (oldChar == newChar) {
            // nothing changes – keep the count as is
            return;
        }

        /* ---- Remove contributions of the old character ---- */
        if (oldChar == '.') {
            if (index > 0 && arr[index - 1] == '.') count[0]--;
            if (index < arr.length - 1 && arr[index + 1] == '.') count[0]--;
        }

        /* ---- Apply the new character ---- */
        arr[index] = newChar;

        /* ---- Add contributions of the new character ---- */
        if (newChar == '.') {
            if (index > 0 && arr[index - 1] == '.') count[0]++;
            if (index < arr.length - 1 && arr[index + 1] == '.') count[0]++;
        }
    }

    public static void main(String[] args) throws IOException {
        // Language‑specific fast I/O pattern
        try (Scanner scanner = new Scanner(System.in)) {
            int n = scanner.nextInt();           // length of the initial string
            int k = scanner.nextInt();           // number of updates
            String initial = scanner.next();     // the string itself

            char[] data = initial.toCharArray();
            int[] count = { countAdjacentDots(data) };   // wrap in array for mutability

            StringBuilder output = new StringBuilder();

            for (int i = 0; i < k; i++) {
                int pos = scanner.nextInt() - 1;   // convert to zero‑based index
                char ch = scanner.next().charAt(0);

                applyUpdate(data, count, pos, ch);
                output.append(count[0]).append('\n');
            }

            System.out.print(output);
        }
    }
}

import java.io.*;
import java.util.StringJoiner;

/**
 * Refactored version of the original {@code Replacement} program.
 *
 * <p>It reads an initial character array, computes an initial score,
 * then updates that score while processing a series of operations.
 *
 * <p>The program prints the score after each operation.
 */
public final class Replacement {

    private Replacement() { /* utility class – no instances */ }

    /** Simple holder for a single operation. */
    private static final class Operation {
        final int index;   // zero‑based position in the array
        final char value;  // new character to place

        Operation(int index, char value) {
            this.index = index;
            this.value = value;
        }
    }

    /** Parses a line like “3 .” into an {@link Operation}. */
    private static Operation parseOperation(String line) {
        String[] tokens = line.split("\\s+");
        int idx = Integer.parseInt(tokens[0]) - 1; // convert to 0‑based index
        char val = tokens[1].charAt(0);
        return new Operation(idx, val);
    }

    /** Returns how many '.' characters are directly adjacent to {@code pos}. */
    private static int adjacentDotCount(char[] arr, int pos) {
        int count = 0;
        if (pos - 1 >= 0 && arr[pos - 1] == '.') {
            count++;
        }
        if (pos + 1 < arr.length && arr[pos + 1] == '.') {
            count++;
        }
        return count;
    }

    /**
     * Computes the initial answer.
     * For every maximal run of '.' characters of length {@code L},
     * adds {@code L‑1} to the total.
     */
    private static int computeInitialAnswer(char[] arr) {
        int answer = 0;
        for (int i = 0; i < arr.length; ) {
            int runLength = 0;
            while (i < arr.length && arr[i] == '.') {
                runLength++;
                i++;
            }
            if (runLength > 0) {
                answer += runLength - 1;
            }
        }
        return answer;
    }

    /**
     * Processes all remaining operation lines from {@code reader}.
     * The intermediate answer after each operation is appended to {@code output}.
     */
    private static void processOperations(
            BufferedReader reader,
            char[] arr,
            int answer,
            StringBuilder output,
            int operationCount) throws IOException {

        for (int i = 0; i < operationCount; i++) {
            String line = reader.readLine();
            if (line == null || line.isEmpty()) {
                continue;
            }

            Operation op = parseOperation(line);
            char current = arr[op.index];

            if (op.value == '.') {                 // placing a dot
                if (current == '.') {
                    // No change – just output the current answer.
                    output.append(answer).append('\n');
                    continue;
                }
                int adjacent = adjacentDotCount(arr, op.index);
                answer += adjacent;                // increase score
                arr[op.index] = '.';
                output.append(answer).append('\n');
            } else {                               // removing a dot
                if (current != '.') {
                    // Already not a dot – output unchanged answer.
                    output.append(answer).append('\n');
                    continue;
                }
                int adjacent = adjacentDotCount(arr, op.index);
                answer -= adjacent;                // decrease score
                arr[op.index] = op.value;
                output.append(answer).append('\n');
            }
        }
    }

    /** Entry point of the program. */
    public static void main(String[] args) throws IOException {
        // ---------- Read input ----------
        try (BufferedReader br = new BufferedReader(
                new InputStreamReader(System.in))) {

            String[] header = br.readLine().split("\\s+");
            int n = Integer.parseInt(header[0]); // array length
            int m = Integer.parseInt(header[1]); // number of operations

            char[] chars = br.readLine().toCharArray();

            // ---------- Initial answer ----------
            int answer = computeInitialAnswer(chars);

            // ---------- Process operations and collect output ----------
            StringBuilder output = new StringBuilder();
            processOperations(br, chars, answer, output, m);

            // ---------- Print result ----------
            PrintWriter pw = new PrintWriter(System.out);
            pw.print(output);
            pw.flush();
        }
    }
}

