/**
 * Refactored version of the original program.
 *
 * <p>This implementation focuses on readability, modularisation and proper resource handling
 * while preserving the original behaviour.</p>
 */
public class Main {

    /* --------------------------------------------------------------------- */
    /*  Fields                                                               */
    /* --------------------------------------------------------------------- */
    private BufferedReader reader;
    private PrintWriter writer;
    private StringTokenizer tokenizer;

    /** Length of the character sequence */
    private int n;

    /** Number of update queries */
    private int m;

    /** Mutable character array */
    private char[] chars;

    /** Current number of adjacent '.' pairs */
    private int dotPairs;

    /* --------------------------------------------------------------------- */
    /*  Entry point                                                          */
    /* --------------------------------------------------------------------- */
    public static void main(String[] args) throws Exception {
        new Main().run();
    }

    /* --------------------------------------------------------------------- */
    /*  Public API                                                           */
    /* --------------------------------------------------------------------- */
    /** Starts the program flow. */
    public void run() throws IOException {
        initialiseStreams();
        readInitialData();
        processQueries();
        closeStreams();
    }

    /** Initialise input / output streams. */
    private void initialiseStreams() {
        reader = new BufferedReader(new InputStreamReader(System.in));
        writer = new PrintWriter(System.out, true); // auto‑flush
    }

    /** Close streams cleanly. */
    private void closeStreams() {
        try {
            if (reader != null) {
                reader.close();
            }
        } catch (IOException ignored) {
        }
        writer.flush();
    }

    /* --------------------------------------------------------------------- */
    /*  Input handling                                                       */
    /* --------------------------------------------------------------------- */
    /** Returns the next token from the input stream. */
    private String nextToken() throws IOException {
        while (tokenizer == null || !tokenizer.hasMoreTokens()) {
            String line = reader.readLine();
            if (line == null) {
                return null;
            }
            tokenizer = new StringTokenizer(line);
        }
        return tokenizer.nextToken();
    }

    /** Reads the first line of input (n, m and the initial character string). */
    private void readInitialData() throws IOException {
        n = Integer.parseInt(nextToken());
        m = Integer.parseInt(nextToken());

        char[] initial = nextToken().toCharArray();
        chars = new char[n];
        System.arraycopy(initial, 0, chars, 0, n);

        recomputeDotPairCount();
    }

    /** Re‑calculates {@code dotPairs} from scratch – used only at start‑up. */
    private void recomputeDotPairCount() {
        int count = 0;
        for (int i = 1; i < n; i++) {
            if (chars[i] == '.' && chars[i - 1] == '.') {
                count++;
            }
        }
        dotPairs = count;
    }

    /* --------------------------------------------------------------------- */
    /*  Query processing                                                     */
    /* --------------------------------------------------------------------- */
    /** Reads and handles all {@code m} update queries. */
    private void processQueries() throws IOException {
        for (int queryIdx = 0; queryIdx < m; queryIdx++) {
            int pos = Integer.parseInt(nextToken()) - 1; // convert to zero‑based
            String token = nextToken();
            if (token.isEmpty()) {
                continue;
            }
            char newChar = token.charAt(0);

            // No change – nothing to adjust.
            if (chars[pos] == newChar) {
                writer.println(dotPairs);
                continue;
            }

            int delta = adjustDotPairCount(pos, chars[pos], newChar);
            chars[pos] = newChar;        // perform the substitution
            dotPairs += delta;           // update running total

            writer.println(dotPairs);
        }
    }

    /**
     * Calculates how {@code dotPairs} must change when the character at {@code pos}
     * is replaced from {@code oldChar} to {@code newChar}.
     *
     * @return the delta to be added to {@code dotPairs}
     */
    private int adjustDotPairCount(int pos, char oldChar, char newChar) {
        int delta = 0;

        // Remove contributions of the current (old) character
        if (oldChar == '.') {
            if (pos > 0 && chars[pos - 1] == '.') {
                delta--;
            }
            if (pos < n - 1 && chars[pos + 1] == '.') {
                delta--;
            }
        }

        // Add contributions of the new character
        if (newChar == '.') {
            if (pos > 0 && chars[pos - 1] == '.') {
                delta++;
            }
            if (pos < n - 1 && chars[pos + 1] == '.') {
                delta++;
            }
        }

        return delta;
    }
}

import java.io.*;
import java.util.*;

public class Main {

    /** Character used to mark empty cells */
    private static final char DOT = '.';

    public static void main(String[] args) throws IOException {
        try (PrintWriter out = new PrintWriter(System.out)) {
            InputReader reader = new InputReader(System.in);

            int n = reader.nextInt();          // number of cells
            int m = reader.nextInt();          // number of operations
            String initial = reader.readString();

            char[] cells = initial.toCharArray();
            int total = computeInitialTotal(cells);

            for (int i = 0; i < m; i++) {
                int idx = reader.nextInt() - 1;  // 0‑based position
                char newChar = reader.readString().charAt(0);

                total += updateTotal(cells, idx, newChar);
                out.println(total);
            }
        }
    }

    /** Calculates the initial value of `total` for the given cell array. */
    private static int computeInitialTotal(char[] cells) {
        int total = 0;
        int consecutiveDots = 0;

        for (char c : cells) {
            if (c == DOT) {
                consecutiveDots++;
            } else {
                total += consecutiveDots;
                if (consecutiveDots > 0) {
                    total -= 1;
                }
                consecutiveDots = 0;
            }
        }
        total += consecutiveDots;
        if (consecutiveDots > 0) {
            total -= 1;
        }
        return total;
    }

    /**
     * Determines the change in {@code total} when the cell at {@code index}
     * is replaced by {@code newChar}.
     *
     * @return delta to be added to the current total
     */
    private static int updateTotal(char[] cells, int index, char newChar) {
        char oldChar = cells[index];
        if (oldChar == newChar) {
            return 0;
        }

        // Transition from '.' → non‑'.'
        if (oldChar == DOT && newChar != DOT) {
            return computeRemovalDelta(cells, index);
        }
        // Transition from non‑'.' → '.'
        if (oldChar != DOT && newChar == DOT) {
            return computeAdditionDelta(cells, index);
        }
        return 0; // should never happen
    }

    /** Delta when a '.' is removed at the given position. */
    private static int computeRemovalDelta(char[] cells, int idx) {
        int delta = 0;

        // interior cell
        if (idx > 0 && idx < cells.length - 1) {
            if (cells[idx - 1] == DOT && cells[idx + 1] == DOT) {
                delta -= 2;
            } else if (cells[idx - 1] == DOT || cells[idx + 1] == DOT) {
                delta -= 1;
            }
        }
        // first cell (has only a right neighbour)
        else if (idx == 0 && cells.length > 1) {
            if (cells[idx + 1] == DOT) {
                delta -= 1;
            }
        }
        // last cell (has only a left neighbour)
        else if (idx == cells.length - 1) {
            if (cells[idx - 1] == DOT) {
                delta -= 1;
            }
        }
        return delta;
    }

    /** Delta when a '.' is added at the given position. */
    private static int computeAdditionDelta(char[] cells, int idx) {
        int delta = 0;

        // interior cell
        if (idx > 0 && idx < cells.length - 1) {
            if (cells[idx - 1] == DOT && cells[idx + 1] == DOT) {
                delta += 2;
            } else if (cells[idx - 1] == DOT || cells[idx + 1] == DOT) {
                delta += 1;
            }
        }
        // first cell (has only a right neighbour)
        else if (idx == 0 && cells.length > 1) {
            if (cells[idx + 1] == DOT) {
                delta += 1;
            }
        }
        // last cell (has only a left neighbour)
        else if (idx == cells.length - 1) {
            if (cells[idx - 1] == DOT) {
                delta += 1;
            }
        }
        return delta;
    }
}

/* --------------------------------------------------------------
   Input utilities (unchanged from the original submission)
   -------------------------------------------------------------- */
class InputReader {
    private final InputStream stream;
    private final byte[] buffer = new byte[8192];
    private int pointer = 0, length = 0;
    private SpaceCharFilter filter;

    public InputReader(InputStream stream) {
        this.stream = stream;
    }

    private int read() throws IOException {
        if (pointer >= length) {
            length = stream.read(buffer);
            pointer = 0;
            if (length <= 0) {
                return -1;
            }
        }
        return buffer[pointer++];
    }

    private int nextChar() throws IOException {
        int c;
        do {
            c = read();
        } while (isSpaceChar(c));
        return c;
    }

    public int nextInt() throws IOException {
        int c = nextChar();
        int sign = 1;
        if (c == '-') {
            sign = -1;
            c = nextChar();
        }
        int result = 0;
        while (!isSpaceChar(c)) {
            result = result * 10 + (c - '0');
            c = nextChar();
        }
        return result * sign;
    }

    public long nextLong() throws IOException {
        int c = nextChar();
        long sign = 1;
        if (c == '-') {
            sign = -1;
            c = nextChar();
        }

        long result = 0;
        while (!isSpaceChar(c)) {
            result = result * 10 + (c - '0');
            c = nextChar();
        }
        return result * sign;
    }

    public String readString() throws IOException {
        int c = nextChar();
        StringBuilder sb = new StringBuilder();
        while (!isSpaceChar(c)) {
            sb.append((char) c);
            c = nextChar();
        }
        return sb.toString();
    }

    public boolean isSpaceChar(int c) {
        if (filter != null) {
            return filter.isSpaceChar(c);
        }
        return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
    }

    public interface SpaceCharFilter {
        boolean isSpaceChar(int ch);
    }
}

import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int n = scanner.nextInt();
        int m = scanner.nextInt();
        scanner.nextLine(); // Consume newline after reading m
        String s = scanner.nextLine();

        char[] arr = s.toCharArray();
        int pairs = countAdjacentDots(arr);

        StringBuilder output = new StringBuilder();

        for (int i = 0; i < m; i++) {
            int pos = scanner.nextInt();
            char newChar = scanner.next().charAt(0);
            int idx = pos - 1; // Convert to 0-indexed

            // Update adjacent dot count based on transition
            if (arr[idx] == '.' && newChar != '.') {
                updatePairs(arr, pairs, idx, true);
            } else if (arr[idx] != '.' && newChar == '.') {
                updatePairs(arr, pairs, idx, false);
            }

            arr[idx] = newChar;
            output.append(pairs).append('\n');
        }

        System.out.print(output.toString());
    }

    private static int countAdjacentDots(char[] arr) {
        int count = 0;
        for (int i = 0; i < arr.length - 1; i++) {
            if (arr[i] == '.' && arr[i + 1] == '.') {
                count++;
            }
        }
        return count;
    }

    private static void updatePairs(char[] arr, int pairs, int idx, boolean isRemoving) {
        if (isRemoving) {
            if (idx > 0 && arr[idx - 1] == '.') pairs--;
            if (idx < arr.length - 1 && arr[idx + 1] == '.') pairs--;
        } else {
            if (idx > 0 && arr[idx - 1] == '.') pairs++;
            if (idx < arr.length - 1 && arr[idx + 1] == '.') pairs++;
        }
    }
}

