import java.util.*;

/**
 * Refactored solution for Codeforces problem 570C.
 *
 * The program reads a string of length {@code n} and performs {@code m}
 * updates. After each update it prints the current number of
 * substrings “...’’ (three consecutive dots) in the string.
 *
 * The refactor focuses on readability, maintainability and proper
 * encapsulation while preserving the original algorithmic behaviour.
 */
public class Main {

    /** Sentinel character placed at both ends of the mutable buffer. */
    private static final char BOUNDARY = '!';

    /** Simple fast scanner used in competitive programming. */
    private static final class FastScanner {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        FastScanner(InputStream in) {
            reader = new BufferedReader(new InputStreamReader(in));
        }

        /** Return the next token, re‑initialising the tokenizer when needed. */
        private String nextToken() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                String line = reader.readLine();
                if (line == null) {
                    return null;
                }
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(nextToken());
        }

        char nextChar() throws IOException {
            return nextToken().charAt(0);
        }
    }

    public static void main(String[] args) throws IOException {
        FastScanner fs = new FastScanner(System.in);

        int n = fs.nextInt();          // length of the original string
        int m = fs.nextInt();          // number of updates

        // Buffer that holds the string with sentinel characters at both ends.
        char[] buf = new char[n + 2];
        buf[0] = BOUNDARY;
        buf[n + 1] = BOUNDARY;

        // Populate the interior of the buffer with the supplied characters.
        String input = fs.next();
        System.arraycopy(input.toCharArray(), 0, buf, 1, n);

        long answer = computeInitialAnswer(buf);
        StringBuilder output = new StringBuilder();

        for (int i = 0; i < m; i++) {
            int pos = fs.nextInt();          // 1‑based position to modify
            char newChar = fs.nextChar();    // new character

            adjustAnswer(buf, pos, newChar, answer);
            output.append(answer).append('\n');
        }

        System.out.print(output.toString());
    }

    /**
     * Computes the initial answer by scanning the buffer.
     *
     * The algorithm mirrors the original implementation:
     * for each maximal segment of consecutive '.' characters it adds
     * {@code max(segmentLength - 1, 0)} to the answer.
     *
     * @param buf mutable character buffer with sentinel ends
     * @return the initial answer value
     */
    private static long computeInitialAnswer(char[] buf) {
        long answer = 0;
        long currentSegment = 0;

        // Scan the buffer, ignoring the sentinel characters at both ends.
        for (int i = 1; i < buf.length - 1; i++) {
            if (buf[i] == '.') {
                currentSegment++;
            } else {
                answer += Math.max(currentSegment - 1, 0);
                currentSegment = 0;
            }
        }
        // Account for a trailing segment that reaches the right sentinel.
        answer += Math.max(currentSegment - 1, 0);
        return answer;
    }

    /**
     * Adjusts the current answer when a character at {@code index} changes.
     *
     * <p>Follows the same rules as the original program:
     * <ul>
     *   <li>If the new character is '.' and the previous character was not,
     *       increment {@code answer} for each neighboring '.'.</li>
     *   <li>If the old character was '.' and the new one is not,
     *       decrement {@code answer} for each neighboring '.'.</li>
     * </ul>
     *
     * @param buf          mutable buffer with sentinel ends
     * @param index        position to modify (1‑based)
     * @param newChar      character to write
     * @param answer       mutable container (single‑element array) holding the current answer
     */
    private static void adjustAnswer(char[] buf, int index, char newChar, long[] answer) {
        char oldChar = buf[index];

        // Old character was '.' and becomes non‑'.'
        if (oldChar == '.' && newChar != '.') {
            if (buf[index - 1] == '.') {
                answer[0]--;
            }
            if (buf[index + 1] == '.') {
                answer[0]--;
            }
        }
        // Old character was non‑'.' and becomes '.'
        else if (oldChar != '.' && newChar == '.') {
            if (buf[index - 1] == '.') {
                answer[0]++;
            }
            if (buf[index + 1] == '.') {
                answer[0]++;
            }
        }

        // Apply the update.
        buf[index] = newChar;
    }
}

