/**
 * Refactored solution that maintains the count of adjacent empty cells ('.')
 * while processing a series of updates. The code is split into small,
 * well‑named methods, uses meaningful constants, and avoids duplicated logic.
 */
public final class Solution {

    /** Character that represents an empty cell. */
    private static final char EMPTY = '.';

    /** Prevent instantiation of this utility class. */
    private Solution() {
        // intentionally empty
    }

    /**
     * Entry point of the program.
     *
     * @param args command‑line arguments (unused)
     * @throws IOException if an I/O error occurs while reading input or writing output
     */
    public static void main(String[] args) throws IOException {
        // Scanner automatically closes the underlying input stream via try‑with‑resources
        try (Scanner scanner = new Scanner(System.in)) {
            int n = scanner.nextInt();   // length of the character sequence
            int m = scanner.nextInt();   // number of modification queries

            char[] cells = scanner.next().toCharArray();

            // initial count of adjacent empty pairs (positions i and i+1 both equal '.')
            int adjacentPairs = countAdjacentEmptyPairs(cells);

            // Buffer output to minimise I/O operations
            StringBuilder output = new StringBuilder();

            for (int query = 0; query < m; query++) {
                int index = scanner.nextInt() - 1; // convert to 0‑based index
                char newValue = scanner.next().charAt(0);

                adjustPairsForChange(cells, index, newValue, adjacentPairs);
                cells[index] = newValue;

                output.append(adjacentPairs).append('\n');
            }

            // Single write to stdout
            System.out.print(output.toString());
        }
    }

    /**
     * Counts how many times two consecutive positions both contain an {@code EMPTY} character.
     *
     * @param arr the character array to inspect
     * @return the number of adjacent empty‑cell pairs
     */
    private static int countAdjacentEmptyPairs(char[] arr) {
        int count = 0;
        for (int i = 0; i < arr.length - 1; i++) {
            if (arr[i] == EMPTY && arr[i + 1] == EMPTY) {
                count++;
            }
        }
        return count;
    }

    /**
     * Adjusts the pair count when a single cell changes its value.
     * The method inspects the left and right neighbours of {@code index}
     * and updates {@code pairsCount} accordingly.
     *
     * @param cells       the current character array representing the grid
     * @param index       position of the cell being modified (0‑based)
     * @param newChar     the new character to place at {@code index}
     * @param pairsCount  current number of adjacent empty pairs (modified in place)
     */
    private static void adjustPairsForChange(char[] cells, int index, char newChar, int pairsCount) {
        int neighbourPairs = 0;

        // Count how many neighbouring cells are currently empty
        if (index - 1 >= 0 && cells[index - 1] == EMPTY) {
            neighbourPairs++;
        }
        if (index + 1 < cells.length && cells[index + 1] == EMPTY) {
            neighbourPairs++;
        }

        char oldChar = cells[index];

        // Adding a new empty cell can create new adjacent pairs
        if (oldChar != EMPTY && newChar == EMPTY) {
            pairsCount += neighbourPairs;
        }
        // Removing an empty cell can destroy existing adjacent pairs
        else if (oldChar == EMPTY && newChar != EMPTY) {
            pairsCount -= neighbourPairs;
        }
        // If the change does not affect adjacency (e.g., '.' -> '.' or non‑'.' -> non‑'.'),
        // the pair count remains unchanged.
    }
}

import java.io.*;
import java.util.StringTokenizer;

/**
 * Main class that reads input, processes a string with dot‑consecutive counting,
 * and answers a series of update queries.
 */
public class Main {

    public static void main(String[] args) {
        try (InputStream in = System.in;
             PrintWriter out = new PrintWriter(System.out)) {
            solve(in, out);
        }
    }

    /**
     * Orchestrates the whole program flow:
     * <ol>
     *   <li>Reads the initial size {@code n}, number of queries {@code m},
     *       and the initial string.</li>
     *   <li>Computes the initial dot‑consecutive count.</li>
     *   <li>Processes each query, updates the count and prints it.</li>
     * </ol>
     *
     * @param reader low‑level input stream reader
     * @param out    output stream writer
     */
    private static void solve(InputReader reader, PrintWriter out) {
        int n = reader.nextInt();
        int m = reader.nextInt();
        StringBuilder sb = new StringBuilder(reader.next());

        int answer = countConsecutiveDots(sb.toString());

        for (int i = 0; i < m; i++) {
            int pos = reader.nextInt() - 1; // convert to zero‑based index
            char ch = reader.nextChar();
            answer += updateDotCount(sb, pos, ch);
            out.println(answer);
        }
    }

    /**
     * Counts the number of '.' characters that are **not** the first in a
     * consecutive sequence of dots.
     *
     * <p>For example, the string {@code "..x."} yields {@code 1} because only the
     * second dot follows another dot.</p>
     *
     * @param s the string to examine
     * @return the computed count
     */
    private static int countConsecutiveDots(String s) {
        int result = 0;
        boolean previousWasDot = false;

        for (int i = 0; i < s.length(); i++) {
            if (s.charAt(i) == '.') {
                if (previousWasDot) {
                    result++;
                } else {
                    previousWasDot = true;
                }
            } else {
                previousWasDot = false;
            }
        }
        return result;
    }

    /**
     * Updates the character at {@code pos} of {@code sb} with {@code ch} and
     * returns the delta to the consecutive‑dot count.
     *
     * @param sb   mutable sequence representing the current string
     * @param pos  zero‑based position to modify
     * @param ch   new character
     * @return change in the consecutive‑dot count
     */
    private static int updateDotCount(StringBuilder sb, int pos, char ch) {
        int delta = 0;
        char old = sb.charAt(pos);

        // No change – nothing to adjust.
        if (old == ch) {
            return 0;
        }

        // --- 1. Remove the contribution of the old character -----------------
        if (old == '.') {
            // If the old '.' had a dot immediately before it, it contributed.
            if (pos - 1 >= 0 && sb.charAt(pos - 1) == '.') {
                delta--;
            }
            // If the old '.' had a dot immediately after it, it contributed.
            if (pos + 1 < sb.length() && sb.charAt(pos + 1) == '.') {
                delta--;
            }
        }

        // --- 2. Apply the change ------------------------------------------------
        sb.setCharAt(pos, ch);

        // --- 3. Add the contribution of the new character ----------------------
        if (ch == '.') {
            // New '.' may contribute if the preceding character is '.'.
            if (pos - 1 >= 0 && sb.charAt(pos - 1) == '.') {
                delta++;
            }
            // New '.' may contribute if the following character is '.'.
            if (pos + 1 < sb.length() && sb.charAt(pos + 1) == '.') {
                delta++;
            }
        }
        // When turning a '.' into a non‑dot, the removal step already subtracted
        // the possible contributions, so no extra addition is required here.

        return delta;
    }

    /**
     * Simple fast scanner for competitive‑programming style input.
     */
    private static class InputReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        InputReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream), 32768);
        }

        String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new UncheckedIOException(e);
                }
            }
            return tokenizer.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        char nextChar() {
            return next().charAt(0);
        }
    }
}

// Refactored version of the original program with improved naming,
// separation of concerns, proper resource handling and extensive comments.

import java.io.*;
import java.util.*;

public class Main {

    /** Entry point – uses try‑with‑resources to guarantee stream closure. */
    public static void main(String[] args) throws IOException {
        try (FastScanner scanner = new FastScanner(System.in);
             PrintWriter out = new PrintWriter(System.out)) {
            solve(scanner, out);
        }
    }

    /** Core logic: reads input, processes updates and prints results. */
    private static void solve(FastScanner in, PrintWriter out) {
        int n = in.nextInt();          // size of the character array
        int m = in.nextInt();          // number of updates
        String initial = in.nextLine().trim(); // the initial pattern line
        char[] pattern = initial.toCharArray();

        PatternState state = new PatternState(pattern);

        for (int i = 0; i < m; i++) {
            int pos = in.nextInt();                     // 1‑based position
            char newChar = in.nextToken().charAt(0);    // new character
            state.update(pos, newChar);
            out.println(state.getResult());             // required output
        }
    }

    /** Encapsulates the mutable character array and the derived metrics. */
    private static final class PatternState {
        private final char[] data;   // underlying character buffer (never null)
        private int dotCount;         // number of '.' characters (originally "punct")
        private int gapCount;          // derived metric (originally "di")

        /** Constructs the state from an initial character array. */
        PatternState(char[] source) {
            this.data = source.clone();
            recomputeMetrics();
        }

        /** Updates the character at the given 1‑based index and adjusts internal counters. */
        void update(int index1Based, char newChar) {
            int idx = index1Based - 1;
            char oldChar = data[idx];
            if (oldChar == newChar) {
                return;               // no change → nothing to do
            }
            data[idx] = newChar;
            adjustMetrics(idx, oldChar, newChar);
        }

        /** Re‑computes both metrics from scratch (simple, easy‑to‑understand). */
        private void recomputeMetrics() {
            dotCount = 0;
            gapCount = 0;
            boolean inGap = false;

            for (char c : data) {
                if (c == '.') {
                    dotCount++;
                    inGap = true;
                } else if (inGap) {
                    gapCount++;
                    inGap = false;
                }
            }

            // If the string ends with a dot, it counts as an additional gap.
            if (data.length > 0 && data[data.length - 1] == '.') {
                gapCount++;
            }
        }

        /** Adjusts the metrics after a single position change.
         *
         *  The original code performed a lengthy case analysis.  Here we
         *  keep the intent but present it in a clear, step‑by‑step fashion.
         *  Where a local update is non‑trivial we fall back to a full recompute,
         *  which is still acceptable for typical contest constraints.
         */
        private void adjustMetrics(int changedIdx, char oldChar, char newChar) {
            // 1. Directly update the dot counter if the changed character itself is a dot.
            if (oldChar == '.') {
                dotCount--;
            }
            if (newChar == '.') {
                dotCount++;
            }

            // 2. Re‑evaluate the gap counter.  The definition of a “gap” matches
            //    the original algorithm (maximal block of '.' followed by a non‑'.').
            //    Re‑computing the whole metric keeps the logic transparent.
            recomputeMetrics();
        }

        /** Returns the value that must be printed after each update. */
        int getResult() {
            // Original output = punctuation - di.
            return dotCount - gapCount;
        }
    }

    /** Fast scanner that supports the operations used by the solution. */
    private static final class FastScanner {
        private final BufferedReader br;
        private StringTokenizer tokenizer;

        FastScanner(InputStreamReader isr) {
            this.br = new BufferedReader(isr);
        }

        /** Ensures a non‑empty tokenizer; reads the next line when necessary. */
        private void ensureTokenizer() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                String line = br.readLine();
                if (line == null) {
                    return; // end of file
                }
                tokenizer = new StringTokenizer(line);
            }
        }

        int nextInt() throws IOException {
            ensureTokenizer();
            return Integer.parseInt(tokenizer.nextToken());
        }

        char nextChar() throws IOException {
            ensureTokenizer();
            // The original program read a single character, possibly whitespace.
            // Here we treat the first character of the next token as the required one.
            String token = tokenizer.nextToken();
            return token.charAt(0);
        }

        /** Returns the next complete line (including possible empty lines). */
        String nextLine() throws IOException {
            return br.readLine();
        }
    }
}

import java.io.IOException;
import java.io.PrintWriter;
import java.util.Scanner;

/**
 * Main entry point of the program.
 *
 * <p>This class reads input from {@code System.in}, processes it using {@link Solver},
 * and writes the results to {@code System.out}.</p>
 */
public class Main {

    /**
     * Program entry point.
     *
     * <p>The method uses try‑with‑resources to ensure that the {@link Scanner} and
     * {@link PrintWriter} are closed automatically.</p>
     */
    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in);
             PrintWriter out = new PrintWriter(System.out)) {

            new Solver().execute(scanner, out);
        } catch (IOException e) {
            // In a contest setting this should never happen, but we keep the guard.
            throw new RuntimeException(e);
        }
    }

    /**
     * Encapsulates the logic required to solve a single test case.
     *
     * <p>All mutable state (counters, the character buffer, etc.) is kept inside this
     * class, making the code easier to understand and maintain.</p>
     */
    private static class Solver {

        /**
         * Executes the solution using the supplied {@link Scanner} and {@link PrintWriter}.
         *
         * @param in  a scanner that reads from standard input
         * @param out a printer that writes to standard output
         */
        public void execute(Scanner in, PrintWriter out) {
            final int n = in.nextInt();   // length of the initial string
            final int m = in.nextInt();   // number of queries

            // Buffer with two extra cells to simplify boundary handling.
            char[] buffer = new char[n + 2]; // indices 1..n are used.

            // Load the initial string into the buffer.
            String initial = in.next();
            System.arraycopy(initial.toCharArray(), 0, buffer, 1, n);

            // Counters that are updated throughout the queries.
            int dotCount = 0;      // total number of '.' characters.
            int blockStarts = 0;   // corresponds to the original variable `cc`.

            // ------------------------------------------------------------
            // Initial scan: fill the counters based on the starting buffer.
            // ------------------------------------------------------------
            for (int i = 1; i <= n; i++) {
                if (buffer[i] == '.') {
                    dotCount++;
                    // A "block start" occurs when the current '.' is either at position 1
                    // or its left neighbour is not '.'.
                    if (i == 1 || buffer[i - 1] != '.') {
                        blockStarts++;
                    }
                } else {
                    // Non‑'.' characters are treated as the null character (0) in the original code.
                    buffer[i] = 0;
                }
            }

            // ------------------------------------------------------------
            // Process each query.
            // ------------------------------------------------------------
            for (int q = 0; q < m; q++) {
                int pos = in.nextInt();                 // 1‑based index to modify
                char ch = in.next().charAt(0);          // character to write

                // Normalise: only '.' is considered a dot; everything else becomes 0.
                if (ch != '.') {
                    ch = 0;
                }

                char oldChar = buffer[pos];
                if (oldChar != ch) {
                    applyUpdate(pos, ch, buffer, dotCount, blockStarts);
                }

                // Output the required value for this query.
                out.println(dotCount - blockStarts);
            }
        }

        /**
         * Updates the buffer at {@code idx} with {@code newChar} and adjusts
         * {@code dotCount} and {@code blockStarts} exactly as the original program does.
         *
         * <p>The neighbour checks are performed after the buffer has been modified,
         * i.e. they reflect the *new* content of the buffer.</p>
         *
         * @param idx         1‑based index that is being modified.
         * @param newChar     The character to write (either '.' or {@code 0}).
         * @param buffer      The mutable character buffer representing the current state.
         * @param dotCount    Mutable holder for the total number of '.' characters.
         * @param blockStarts Mutable holder for the {@code cc} variable.
         */
        private static void applyUpdate(int idx,
                                        char newChar,
                                        char[] buffer,
                                        int[] dotCount,
                                        int[] blockStarts) {
            // Write the new character into the buffer.
            buffer[idx] = newChar;

            if (newChar == '.') {
                // ----- Adding a dot -----
                dotCount[0]++;

                // If both neighbours are non‑dot (i.e., 0), we create a new block start.
                if (buffer[idx - 1] == 0 && buffer[idx + 1] == 0) {
                    blockStarts[0]++;
                }
                // If both neighbours are already dots, we merge two blocks, decreasing the start count.
                if (buffer[idx - 1] == '.' && buffer[idx + 1] == '.') {
                    blockStarts[0]--;
                }
            } else {
                // ----- Removing a dot (or overwriting a dot with a non‑dot) -----
                dotCount[0]--;

                // If both neighbours are non‑dot, we lose a block start.
                if (buffer[idx - 1] == 0 && buffer[idx + 1] == 0) {
                    blockStarts[0]--;
                }
                // If both neighbours are dots, splitting a block creates a new start.
                if (buffer[idx - 1] == '.' && buffer[idx + 1] == '.') {
                    blockStarts[0]++;
                }
            }
        }
    }
}

import java.io.IOException;
import java.io.InputStreamReader;
import java.util.Scanner;

/**
 * Refactored version of the “good_string” utility.
 *
 * <p>It reads a string and a series of updates, maintains a running total that
 * counts the number of “extra” consecutive dots (i.e. for each maximal run of
 * k dots the contribution is max(0, k‑1)), and prints the total after each
 * update.</p>
 *
 * <p>The code is deliberately split into small, single‑purpose methods to aid
 * maintainability and to make future extensions straightforward.</p>
 */
public class Main {

    /** Buffers the output so we only perform a single write to {@code System.out}. */
    private static final StringBuilder OUTPUT = new StringBuilder();

    public static void main(String[] args) throws IOException {
        // --------------------------------------------------------------------
        // 1️⃣  Input handling
        // --------------------------------------------------------------------
        try (Scanner scanner = new Scanner(new InputStreamReader(System.in))) {

            int /*strLength*/ ignoredLength = scanner.nextInt();   // not used later
            int queryCount = scanner.nextInt();                     // number of updates
            String initialString = scanner.next();                  // the original string

            char[] chars = initialString.toCharArray();
            long total = computeTotal(chars);                       // initial total

            // --------------------------------------------------------------------
            // 2️⃣  Process each query
            // --------------------------------------------------------------------
            for (int i = 0; i < queryCount; i++) {
                int pos = scanner.nextInt() - 1;                      // 1‑based → 0‑based
                char newChar = scanner.next().charAt(0);

                // No change → nothing to do
                if (chars[pos] == newChar) {
                    OUTPUT.append(total).append('\n');
                    continue;
                }

                char oldChar = chars[pos];
                chars[pos] = newChar;                               // apply the update

                // Re‑calculate the total after the mutation
                total = computeTotal(chars);
                OUTPUT.append(total).append('\n');
            }

            // --------------------------------------------------------------------
            // 3️⃣  Output all results at once
            // --------------------------------------------------------------------
            System.out.print(OUTPUT.toString());
        }
    }

    /**
     * Calculates the “total” value for the current character array.
     * <p>
     * The total is the sum of {@code (runLength - 1)} for every maximal
     * contiguous segment of '.' characters.
     * </p>
     *
     * @param chars the character array to analyse
     * @return the computed total
     */
    private static long computeTotal(char[] chars) {
        long total = 0;
        int i = 0;
        final int length = chars.length;

        while (i < length) {
            if (chars[i] == '.') {
                int runStart = i;
                // Extend the run while we keep seeing '.'
                while (i < length && chars[i] == '.') {
                    i++;
                }
                int runLength = i - runStart;
                if (runLength > 1) {
                    total += (runLength - 1);
                }
            } else {
                i++; // move past non‑dot characters
            }
        }
        return total;
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;

/**
 * Reads a string, counts occurrences of adjacent '.' characters,
 * and processes a series of updates, printing the current count after each update.
 */
public class Main {

    /** Character that marks a “filled” cell in the problem statement. */
    private static final char DOT = '.';

    /** Mutable holder for the current number of adjacent '.' pairs. */
    private static final class PairCounter {
        long count;

        PairCounter(long initial) {
            this.count = initial;
        }

        void increment() {
            ++count;
        }

        void decrement() {
            --count;
        }
    }

    public static void main(String[] args) throws IOException {
        /* --------------------------------------------------------------
         *  Input handling – try‑with‑resources guarantees proper closure.
         * -------------------------------------------------------------- */
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
             PrintWriter out = new PrintWriter(System.out)) {

            /* -------- read dimensions -------- */
            String[] dimTokens = br.readLine().split("\\s+");
            int length = Integer.parseInt(dimTokens[0]);
            int queryCount = Integer.parseInt(dimTokens[1]);

            /* -------- read the initial string -------- */
            char[] chars = br.readLine().toCharArray();

            /* -------- initialise pair counter -------- */
            PairCounter counter = new PairCounter(countAdjacentDots(chars));

            /* -------- process each query -------- */
            for (int i = 0; i < queryCount; i++) {
                String[] queryTokens = br.readLine().split("\\s+");
                int index = Integer.parseInt(queryTokens[0]) - 1;   // problem uses 1‑based index
                char newChar = queryTokens[1].charAt(0);

                adjustCounter(index, newChar, chars, counter);
                chars[index] = newChar;          // update the array for future adjustments

                out.println(counter.count);
            }
        }
    }

    /** Counts how many times two consecutive '.' characters occur in the array. */
    private static long countAdjacentDots(char[] chars) {
        long pairs = 0;
        for (int i = 0; i < chars.length - 1; i++) {
            if (chars[i] == DOT && chars[i + 1] == DOT) {
                pairs++;
            }
        }
        return pairs;
    }

    /**
     * Adjusts {@code counter} when the character at {@code index} is changed
     * to {@code newChar}. The method examines only the neighbour positions
     * because only those pairs can be affected.
     *
     * @param index      position that is modified (0‑based)
     * @param newChar    the character that will replace the existing one
     * @param chars      the current character array
     * @param counter    mutable holder for the current pair count
     */
    private static void adjustCounter(int index,
                                      char newChar,
                                      char[] chars,
                                      PairCounter counter) {
        boolean wasDot = chars[index] == DOT;
        boolean willBeDot = newChar == DOT;

        // If the dot‑ness changes, revisit the two adjacent edges
        if (wasDot != willBeDot) {
            // Removing a '.' can destroy up to two existing pairs
            if (!willBeDot) {
                if (index > 0 && chars[index - 1] == DOT) {
                    counter.decrement();
                }
                if (index < chars.length - 1 && chars[index + 1] == DOT) {
                    counter.decrement();
                }
            } else { // Adding a '.'
                if (index > 0 && chars[index - 1] == DOT) {
                    counter.increment();
                }
                if (index < chars.length - 1 && chars[index + 1] == DOT) {
                    counter.increment();
                }
            }
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

/**
 * Reads a trail description and a series of updates, then prints the
 * intermediate “result” after each update.
 *
 * The original program counted how many redundant '.' characters appear
 * between non‑'.' symbols and updated the count incrementally.
 * The refactor improves readability, separates concerns and uses
 * meaningful names while preserving the exact behaviour.
 */
public class TrailCalculator {

    /** Character used for an empty (unfilled) cell. */
    private static final char EMPTY = '.';

    /** StringBuilder used to collect output lines. */
    private static final StringBuilder OUTPUT = new StringBuilder();

    /** Mutable representation of the current trail. */
    private static char[] trail;

    /** Length of the trail (cached for convenience). */
    private static int trailLength;

    /** Current value of the computed result. */
    private static int result;

    public static void main(String[] args) throws IOException {
        /* --------------------------------------------------------------
         *  1.  Read input
         * -------------------------------------------------------------- */
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in))) {
            StringTokenizer tokenizer = new StringTokenizer(br.readLine());
            // n and m are read only to consume the input; n is not used later.
            int unusedN = Integer.parseInt(tokenizer.nextToken());
            int updates = Integer.parseInt(tokenizer.nextToken());

            // read the initial trail
            trail = br.readLine().toCharArray();
            trailLength = trail.length;

            /* --------------------------------------------------------------
             *  2.  Compute the initial result based on the '.'‑segments
             * -------------------------------------------------------------- */
            computeInitialResult();

            /* --------------------------------------------------------------
             *  3.  Process each update
             * -------------------------------------------------------------- */
            for (int i = 0; i < updates; i++) {
                tokenizer = new StringTokenizer(br.readLine());
                int idx = Integer.parseInt(tokenizer.nextToken()) - 1; // 0‑based index
                char newChar = tokenizer.nextToken().charAt(0);

                if (trail[idx] != newChar) {
                    adjustResult(idx, newChar);
                    trail[idx] = newChar;          // mutate the trail
                }

                OUTPUT.append(result).append('\n');
            }

            System.out.print(OUTPUT);
        }
    }

    /** Calculates the result for the current trail configuration. */
    private static void computeInitialResult() {
        result = 0;
        int dotSegmentStart = -1; // start index of the currently observed '.' segment

        for (int i = 0; i < trailLength; i++) {
            if (trail[i] != EMPTY && dotSegmentStart != -1) {
                // we just left a '.' segment – add (segmentLength‑1) to the result
                int segmentLength = i - dotSegmentStart;
                result += segmentLength - 1;
                dotSegmentStart = -1; // reset
            } else if (trail[i] == EMPTY && dotSegmentStart == -1) {
                // start of a new '.' segment
                dotSegmentStart = i;
            }
        }

        // If the trail ends with a '.' segment, account for it as well.
        if (dotSegmentStart != -1) {
            result += (trailLength - 1) - dotSegmentStart;
        }
    }

    /**
     * Adjusts {@code result} when a single position of the trail is changed.
     *
     * @param index   position that will be modified
     * @param newChar character that will be placed at {@code index}
     */
    private static void adjustResult(int index, char newChar) {
        char oldChar = trail[index];
        if (oldChar == newChar) {
            return; // nothing to do
        }

        // Neighbourhood information *before* the change
        boolean beforeIsDot = index > 0 && trail[index - 1] == EMPTY;
        boolean afterIsDot  = index < trailLength - 1 && trail[index + 1] == EMPTY;

        // Information about the old character's neighbourhood (used only
        // when it was a '.')
        boolean oldBeforeIsDot = index > 0 && oldChar == EMPTY;
        boolean oldAfterIsDot  = index < trailLength - 1 && oldChar == EMPTY;

        int delta = 0; // how the result must change

        // -----------------------------------------------------------------
        // 1) Turning a '.' into a filler ('.' → non‑'.')
        //    This *adds* to the result, exactly as the original program did.
        // -----------------------------------------------------------------
        if (oldChar == EMPTY && newChar != EMPTY) {
            if (oldBeforeIsDot && oldAfterIsDot) {
                delta = 2;      // isolated '.' surrounded by other '.' on both sides
            } else if (oldBeforeIsDot || oldAfterIsDot) {
                delta = 1;      // '.' at the edge of a '.' segment
            }
            result += delta;
        }
        // -----------------------------------------------------------------
        // 2) Turning a filler into a '.' (non‑'.' → '.')
        //    This *subtracts* from the result.
        // -----------------------------------------------------------------
        else if (oldChar != EMPTY && newChar == EMPTY) {
            if (beforeIsDot && afterIsDot) {
                delta = -2;      // creates a new isolated '.' segment
            } else if (beforeIsDot || afterIsDot) {
                delta = -1;      // extends an existing segment
            }
            result += delta;
        }
    }
}

import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.io.IOException;

/**
 * Main class that reads input, maintains a segment tree of characters and
 * prints the score after each update operation.
 */
public final class Main {

    /** Simple wrapper around {@link BufferedReader} for convenient token reading. */
    private static final class InputReader {
        private final BufferedReader reader;

        InputReader() {
            this.reader = new BufferedReader(new InputStreamReader(System.in));
        }

        /** Reads a line, trims it and splits it on whitespace. */
        String[] readTokens() throws IOException {
            return reader.readLine().trim().split("\\s+");
        }

        /** Reads the next token as an {@code int}. */
        int nextInt() throws IOException {
            return Integer.parseInt(readTokens()[0]);
        }
    }

    public static void main(String[] args) throws IOException {
        InputReader input = new InputReader();

        // First line: n m
        int n = input.nextInt();
        int m = input.nextInt();

        // Second line: the initial character sequence
        String initial = input.readTokens()[0];

        SegmentTree tree = new SegmentTree(initial.toCharArray());

        StringBuilder output = new StringBuilder();

        // Process m update operations
        for (int i = 0; i < m; ++i) {
            int index = input.nextInt() - 1;          // 0‑based index
            char newChar = input.readTokens()[1].charAt(0);

            tree.update(index, newChar);
            output.append(tree.getScore()).append('\n');
        }

        System.out.print(output);
    }
}

/**
 * Segment tree that stores characters and maintains a score that counts
 * the number of adjacent '.' matches that can be merged across segment
 * boundaries.  The tree is built on a power‑of‑two size to simplify index
 * calculations.
 */
final class SegmentTree {

    /** Node used inside the tree. */
    private static final class Node {
        final char left;   // first character of the segment
        final char right;  // last character of the segment
        int score;         // score contributed by this segment

        Node(char left, char right, int score) {
            this.left = left;
            this.right = right;
            this.score = score;
        }
    }

    private static final char FILLER = 'c'; // character used for padded leaves

    private final int capacity;   // smallest power of two >= input length
    private final Node[] tree;    // 1‑based indexing, tree[0] unused

    SegmentTree(char[] data) {
        int length = data.length;
        capacity = 1 << (32 - Integer.numberOfLeadingZeros(length - 1));
        tree = new Node[2 * capacity];

        // Fill leaves
        for (int i = 0; i < length; ++i) {
            tree[capacity + i] = new Node(data[i], data[i], 0);
        }
        // Pad the remaining leaves
        for (int i = length; i < capacity; ++i) {
            tree[capacity + i] = new Node(FILLER, FILLER, 0);
        }

        // Build internal nodes bottom‑up
        for (int i = capacity - 1; i > 0; --i) {
            merge(i);
        }
    }

    /** Combine the two children of {@code index} and store the result. */
    private void merge(int index) {
        Node left = tree[index << 1];
        Node right = tree[(index << 1) | 1];

        char newLeft = left.left;
        char newRight = right.right;
        int extra = (left.right == '.' && right.left == '.') ? 1 : 0;
        int newScore = left.score + right.score + extra;

        tree[index] = new Node(newLeft, newRight, newScore);
    }

    /** Updates the character at {@code position} (0‑based). */
    void update(int position, char value) {
        int leafIdx = capacity + position;
        if (shouldSkipUpdate(tree[leafIdx], value)) {
            return; // no change needed
        }

        tree[leafIdx] = new Node(value, value, 0);
        int i = leafIdx;
        while (i > 1) {
            i >>= 1;
            merge(i);
        }
    }

    /** Returns the score stored at the root of the tree (node 1). */
    int getScore() {
        return tree[1].score;
    }

    /** Checks whether an update would actually change the leaf's character. */
    private static boolean shouldSkipUpdate(Node node, char value) {
        char current = node.left; // left == right for a leaf
        return (current == '.' && value == '.') || (current != '.' && value != '.');
    }
}

import java.io.*;
import java.util.StringTokenizer;

/**
 * Refactored solution for the problem.
 * The logic is unchanged, but the code is now more maintainable and follows Java best‑practices.
 */
public class Main {

    public static void main(String[] args) {
        // Using try‑with‑resources ensures every stream/reader is closed properly.
        try (InputStream inStream = System.in;
             PrintWriter out = new PrintWriter(
                     new BufferedWriter(
                             new OutputStreamWriter(System.out)
                     )
             )
        ) {
            FastScanner scanner = new FastScanner(inStream);
            solve(scanner, out);
            // PrintWriter is auto‑flushed, no explicit close needed here.
        }
    }

    /**
     * Reads the input and processes each query.
     *
     * @param scanner a fast input scanner
     * @param out     output writer
     */
    private static void solve(FastScanner scanner, PrintWriter out) {
        int n = scanner.nextInt(); // length of the initial string
        int q = scanner.nextInt(); // number of queries
        StringBuilder sb = new StringBuilder(scanner.next());

        int consecutiveDots = countConsecutiveDots(sb, n);

        for (int i = 0; i < q; ++i) {
            int idx = scanner.nextInt() - 1;          // convert to 0‑based index
            char newChar = scanner.next().charAt(0);  // target character

            // No change required if the new character equals the current one
            if (sb.charAt(idx) == newChar) {
                out.println(consecutiveDots);
                continue;
            }

            adjustCountForChange(sb, idx, newChar, consecutiveDots, n, out);
            sb.setCharAt(idx, newChar);               // apply the modification
        }
    }

    /** Counts how many times ".." appears in the current buffer. */
    private static int countConsecutiveDots(StringBuilder sb, int length) {
        int count = 0;
        for (int i = 1; i < length; ++i) {
            if (sb.charAt(i) == '.' && sb.charAt(i - 1) == '.') {
                ++count;
            }
        }
        return count;
    }

    /**
     * Updates {@code consecutiveDots} based on changing the character at {@code index}
     * to {@code newChar} and prints the resulting count.
     *
     * @param sb           mutable character buffer
     * @param index        position that is being changed (0‑based)
     * @param newChar      character we are writing
     * @param currentCount count of ".." occurrences before the change
     * @param length       length of the buffer
     * @param out          writer for the updated count
     */
    private static void adjustCountForChange(StringBuilder sb,
                                             int index,
                                             char newChar,
                                             int currentCount,
                                             int length,
                                             PrintWriter out) {
        char oldChar = sb.charAt(index);

        // The old character may have contributed to existing ".." pairs.
        if (oldChar == '.') {
            if (index > 0 && sb.charAt(index - 1) == '.') {
                currentCount--;
            }
            if (index < length - 1 && sb.charAt(index + 1) == '.') {
                currentCount--;
            }
        }

        // The new character can create new ".." pairs.
        if (newChar == '.') {
            if (index > 0 && sb.charAt(index - 1) == '.') {
                currentCount++;
            }
            if (index < length - 1 && sb.charAt(index + 1) == '.') {
                currentCount++;
            }
        }

        out.println(currentCount);
    }

    /**
     * Simple scanner that returns tokens from {@link BufferedReader}
     * without throwing checked exceptions.
     */
    private static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner(InputStream inputStream) {
            this.br = new BufferedReader(new InputStreamReader(inputStream));
        }

        /** Returns the next token, reading a new line when necessary. */
        String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return st.nextToken();
        }

        /** Convenience method for reading an {@code int}. */
        int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

