/**
 * Solution for the problem that counts occurrences of two consecutive '.' characters
 * after each update operation.
 *
 * <p>The program reads:
 * <ul>
 *   <li>the length of the string {@code n} and the number of queries {@code m}</li>
 *   <li>the initial string {@code s}</li>
 *   <li>each query consists of a 1‑based index and a single character</li>
 * </ul>
 * It maintains the number of adjacent '.' pairs and prints the value after every query.
 *
 * <p>Refactoring focuses on:
 * <ul>
 *   <li>Clearer naming and documentation</li>
 *   <li>Extraction of small, well‑named methods</li>
 *   <li>Encapsulation of input handling</li>
 *   <li>Immutability of public fields where possible</li>
 *   <li>Separation of concerns (I/O, state, logic)</li>
 * </ul>
 */
public class Main {

    /** Fast input reader used throughout the solution. */
    private final FastScanner input = new FastScanner(System.in);

    /** Output writer for the answers. */
    private final PrintWriter output = new PrintWriter(System.out, true);

    /** The current string represented as a mutable character array. */
    private char[] current;

    /** Number of adjacent '.' pairs in {@link #current}. */
    private int adjacentDotCount;

    /**
     * Entry point of the program.
     */
    public static void main(String[] args) {
        new Main().run();
    }

    /** Executes the solution: reads input, processes queries, and writes results. */
    public void run() {
        readInitialData();
        processQueries();
        output.close();
    }

    /** Reads {@code n}, {@code m} and the initial string {@code s}. */
    private void readInitialData() {
        int n = input.nextInt();
        int m = input.nextInt();
        current = input.next().toCharArray();
        computeAdjacencyCount();
        // The loop below processes each of the {@code m} queries.
        for (int i = 0; i < m; i++) {
            int position = input.nextInt() - 1;          // convert to 0‑based index
            String token = input.next();                // the replacement character (as a string)
            updateAtPosition(position, token.charAt(0));
            output.println(adjacentDotCount);
        }
    }

    /** Computes the initial number of adjacent '.' pairs. */
    private void computeAdjacencyCount() {
        adjacentDotCount = 0;
        for (int i = 1; i < current.length; i++) {
            if (isDot(i - 1) && isDot(i)) {
                adjacentDotCount++;
            }
        }
    }

    /**
     * Updates the character at {@code index} with {@code newChar}.
     * Adjusts {@link #adjacentDotCount} accordingly and stores the new character.
     */
    private void updateAtPosition(int index, char newChar) {
        char oldChar = current[index];
        if (oldChar == newChar) {
            return; // no change → nothing to do
        }

        // -----------------------------------------------------------------
        // 1️⃣  If we are turning a '.' into something else, we must possibly
        //     decrement the adjacency counter for the neighbour cells.
        // 2️⃣  If we are turning a non‑'.' into '.', we must possibly
        //     increment the adjacency counter for the neighbour cells.
        // -----------------------------------------------------------------
        if (isDot(oldChar) && !isDot(newChar)) {
            // outgoing '.' → decrement neighbours that previously formed a pair
            if (index > 0 && isDot(index - 1)) {
                adjacentDotCount--;
            }
            if (index + 1 < current.length && isDot(index + 1)) {
                adjacentDotCount--;
            }
        } else if (!isDot(oldChar) && isDot(newChar)) {
            // incoming '.' → increment neighbours that now form a pair
            if (index > 0 && isDot(index - 1)) {
                adjacentDotCount++;
            }
            if (index + 1 < current.length && isDot(index + 1)) {
                adjacentDotCount++;
            }
        }

        // Store the new character for future updates.
        current[index] = newChar;
    }

    /** Tiny helper that returns {@code true} when {@code c} equals '.'. */
    private static boolean isDot(char c) {
        return c == '.';
    }

    /**
     * Simple fast scanner that works with {@link BufferedReader} and
     * {@link StringTokenizer}.  It hides the boiler‑plate from the main logic.
     */
    private static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner(InputStream stream) {
            br = new BufferedReader(new InputStreamReader(stream));
        }

        /** Returns the next token or {@code null} if no more tokens are available. */
        String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    String line = br.readLine();
                    if (line == null) {
                        return null;
                    }
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        long nextLong() {
            return Long.parseLong(next());
        }

        double nextDouble() {
            return Double.parseDouble(next());
        }
    }
}

import java.io.*;
import java.util.StringTokenizer;

/**
 * Refactored solution for the problem.
 *
 * The program reads a string and a series of updates.
 * For each update it changes a character at a given position
 * and reports how many adjacent ".." patterns exist in the
 * current string.
 *
 * The implementation focuses on readability, modularisation
 * and maintainability.
 */
public class C {

    /** Fast scanner that works with BufferedReader. */
    private static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner(Reader reader) {
            this.br = new BufferedReader(reader);
        }

        /** Returns the next integer from the input. */
        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }

        /** Returns the next token (non‑whitespace sequence). */
        String next() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                String line = br.readLine();
                if (line == null) {
                    return null;
                }
                st = new StringTokenizer(line);
            }
            return st.nextToken();
        }
    }

    /** Counts the number of adjacent ".." occurrences in the array. */
    private static int countAdjacentDotPairs(char[] arr) {
        int cnt = 0;
        for (int i = 1; i < arr.length; i++) {
            if (arr[i - 1] == '.' && arr[i] == '.') {
                cnt++;
            }
        }
        return cnt;
    }

    /**
     * Returns how many new adjacent dot‑pairs are created (or removed)
     * when the character at {@code idx} changes to {@code newChar}.
     * The method looks only at the neighbours of {@code idx}.
     */
    private static int adjacentDotPairImpact(char[] arr, int idx, char newChar) {
        // When we set the character to '.', each neighbouring '.' creates a pair.
        // When we clear a '.', each neighbouring '.' removes a pair.
        int impact = 0;

        if (newChar == '.') {
            // left neighbour creates a pair with idx
            if (idx > 0 && arr[idx - 1] == '.') {
                impact++;
            }
            // right neighbour creates a pair with idx
            if (idx < arr.length - 1 && arr[idx + 1] == '.') {
                impact++;
            }
        } else {
            // Removing a '.' – the same neighbours lose a pair.
            if (idx > 0 && arr[idx - 1] == '.') {
                impact--;
            }
            if (idx < arr.length - 1 && arr[idx + 1] == '.') {
                impact--;
            }
        }
        return impact;
    }

    /** Core solving routine. */
    private static void solve() throws IOException {
        FastScanner fs = new FastScanner(new InputStreamReader(System.in));
        int n = fs.nextInt();          // length of the string (not used directly)
        int m = fs.nextInt();          // number of updates
        String initial = fs.next();    // the initial string
        char[] data = initial.toCharArray();

        int consecutiveDotPairs = countAdjacentDotPairs(data);
        StringBuilder output = new StringBuilder();

        for (int i = 0; i < m; i++) {
            int pos = fs.nextInt() - 1;          // 0‑based position
            char newChar = fs.next().charAt(0);  // character to write

            char oldChar = data[pos];
            if (oldChar == newChar) {
                // No change – just output the current count
                output.append(consecutiveDotPairs).append('\n');
                continue;
            }

            // ---- removal of the old character ----
            if (oldChar == '.') {
                consecutiveDotPairs += adjacentDotPairImpact(data, pos, '.');
            }

            // ---- set the new character ----
            data[pos] = newChar;

            // ---- addition of the new character ----
            if (newChar == '.') {
                consecutiveDotPairs += adjacentDotPairImpact(data, pos, '.');
            }

            output.append(consecutiveDotPairs).append('\n');
        }

        System.out.print(output.toString());
    }

    /** Entry point. */
    public static void main(String[] args) throws Exception {
        solve();
    }
}

import java.io.*;
import java.util.*;

/**
 * Main entry point. Handles I/O and orchestrates the solution.
 */
public class Main {

    /** Symbol that denotes an empty cell in the input grid. */
    private static final char EMPTY = '.';

    /** Directions used for neighbour checks (down, up, right, left). */
    private static final int[][] DIRS = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};

    /** Fast scanner that mimics the original BufferedReader‑based utilities. */
    private static final class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner(Reader in) {
            this.br = new BufferedReader(new InputStreamReader(in));
        }

        /** Returns the next token or {@code null} when input is exhausted. */
        private String nextToken() throws IOException {
            while (st == null || !st.hasMoreElements()) {
                String line = br.readLine();
                if (line == null) return null;
                st = new StringTokenizer(line);
            }
            return st.nextToken();
        }

        /** Reads an {@code int}. */
        int nextInt() throws IOException {
            return Integer.parseInt(nextToken());
        }

        /** Reads a {@code char} array (the whole line). */
        char[] nextCharArray() throws IOException {
            String line = br.readLine();
            return (line == null) ? new char[0] : line.toCharArray();
        }
    }

    /** ----------  Fields used by the algorithm  ---------- */
    private final FastScanner fs;
    private final PrintWriter out;

    /** Component identifier for each cell (0 = not processed). */
    private int[][] componentId;

    /** Physical sizes of components; index 0 is a dummy entry. */
    private final List<Integer> componentSize = new ArrayList<>();

    /** Human‑readable answer grid. */
    private char[][] answer;

    /** Constructor – wires the scanners. */
    public Main(Reader input, Writer output) {
        this.fs = new FastScanner(input);
        this.out = new PrintWriter(output);
    }

    /** Executes the full pipeline: read → solve → output. */
    public void solve() throws IOException {
        final int rows = fs.nextInt();
        final int cols = fs.nextInt();

        // ----- 1️⃣ read the grid -------------------------------------------------
        char[][] grid = readGrid(rows);

        // ----- 2️⃣ discover empty components ------------------------------------
        componentId = new int[rows][cols];
        componentSize.clear();
        componentSize.add(0);                // dummy entry, real ids start at 1
        int nextId = 1;

        boolean[][] visited = new boolean[rows][cols];

        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == EMPTY && !visited[r][c]) {
                    int size = bfs(grid, visited, r, c, nextId);
                    componentSize.add(size);
                    nextId++;
                }
            }
        }

        // ----- 3️⃣ build the answer ------------------------------------------------
        answer = new char[rows][];
        for (int r = 0; r < rows; r++) {
            answer[r] = new char[cols];
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == EMPTY) {
                    answer[r][c] = EMPTY;
                } else {
                    long sum = 1L;                     // the wall cell itself
                    Set<Integer> neighbourIds = new HashSet<>();

                    for (int[] d : DIRS) {
                        int nr = r + d[0];
                        int nc = c + d[1];
                        if (valid(nr, nc, rows, cols) && grid[nr][nc] == EMPTY) {
                            neighbourIds.add(componentId[nr][nc]);
                        }
                    }
                    for (int id : neighbourIds) {
                        sum += componentSize.get(id);
                    }
                    answer[r][c] = (char) ('0' + (int) (sum % 10));
                }
            }
            out.println(new String(answer[r]));
        }
    }

    /** Reads `rows` lines of length `cols` from the scanner. */
    private char[][] readGrid(int rows) throws IOException {
        char[][] grid = new char[rows][];
        for (int i = 0; i < rows; i++) {
            grid[i] = fs.nextCharArray();
        }
        return grid;
    }

    /** Breadth‑first search that fills `componentId` and returns the component size. */
    private int bfs(char[][] grid, boolean[][] visited, int sr, int sc, int id) {
        final int rows = grid.length;
        final int cols = grid[0].length;
        int size = 1;
        Deque<int[]> q = new ArrayDeque<>();
        q.addLast(new int[]{sr, sc});
        visited[sr][sc] = true;
        componentId[sr][sc] = id;

        while (!q.isEmpty()) {
            int[] cur = q.removeFirst();
            for (int[] d : DIRS) {
                int nr = cur[0] + d[0];
                int nc = cur[1] + d[1];
                if (valid(nr, nc, rows, cols) && !visited[nr][nc] && grid[nr][nc] == EMPTY) {
                    visited[nr][nc] = true;
                    size++;
                    componentId[nr][nc] = id;
                    q.addLast(new int[]{nr, nc});
                }
            }
        }
        return size;
    }

    /** Helper that checks array bounds. */
    private boolean valid(int r, int c, int rows, int cols) {
        return r >= 0 && c >= 0 && r < rows && c < cols;
    }

    /** Closes all streams used by this instance. */
    public void close() throws IOException {
        out.flush();
        out.close();
        fs.br.close();
    }

    // -----------------------------------------------------------------------
    // Entry point – mirrors the original program’s signature
    // -----------------------------------------------------------------------
    public static void main(String[] args) throws IOException {
        try (Main solver = new Main(
                new BufferedReader(new InputStreamReader(System.in)),
                new PrintWriter(System.out))) {
            solver.solve();
        }
    }
}

// Refactored Java program
// The refactor focuses on readability, encapsulation, naming, and removal of dead code.
// Functionality remains unchanged.

import java.io.*;
import java.util.*;
import java.util.stream.IntStream;

public class Main {

    public static void main(String[] args) {
        Solver solver = new Solver();
        solver.execute();
    }
}

/** Core logic of the problem. */
class Solver {

    private final SolverConfig config = new SolverConfig();

    /** Number of rows and columns of the grid. */
    private int rows;
    /** 2‑D boolean array marking cells that are free ('.') */
    private boolean[][] free;
    /** DSU structure that groups orthogonal adjacent free cells. */
    private DSU dsu;

    /** Input and output streams. */
    private InputReader reader;
    private OutputWriter writer;

    /** Executes the whole workflow: configuration → reading → processing → writing. */
    public void execute() {
        configure();
        readInput(reader);
        compute();
        writeOutput(writer);
    }

    /** Hook for future configuration parameters. Currently empty. */
    private void configure() { }

    /** Reads grid dimensions, the grid itself and stores them in the solver fields. */
    private void readInput(InputReader in) {
        rows = in.readInt();
        cols = in.readInt();
        free = new boolean[rows][cols];
        dsu = new DSU(rows, cols);
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                free[i][j] = in.readCharacter() == '.';
            }
        }
    }

    /** Connects orthogonal adjacent free cells using DSU. */
    private void compute() {
        uniteAdjacentFreeCells();
    }

    /** Generates the required output based on component sizes. */
    private void writeOutput(OutputWriter out) {
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (free[i][j]) {
                    out.print('.');
                } else {
                    Set<Integer> neighbourParents = new HashSet<>(4);
                    collectNeighbourComponentParents(i, j, neighbourParents);
                    int neighbourCount = neighbourParents.stream()
                            .mapToInt(dsu::getSize)
                            .sum()
                            + 1;
                    out.print(neighbourCount % 10);
                }
            }
            out.printLine();
        }
        out.close();
    }

    /** Adds the root of each orthogonal neighbour component to the supplied set. */
    private void collectNeighbourComponentParents(int i, int j, Set<Integer> set) {
        set.clear();
        for (Direction dir : Direction.values()) {
            int ni = i + dir.dx;
            int nj = j + dir.dy;
            if (isInRange(ni, nj) && free[ni][nj]) {
                set.add(dsu.findParent(ni, nj));
            }
        }
    }

    /** Returns true if the supplied coordinates lie inside the grid. */
    private boolean isInRange(int i, int j) {
        return 0 <= i && i < rows && 0 <= j && j < cols;
    }

    /** Connects each free cell with its orthogonal free neighbours. */
    private void uniteAdjacentFreeCells() {
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (free[i][j]) {
                    for (Direction dir : Direction.values()) {
                        int ni = i + dir.dx;
                        int nj = j + dir.dy;
                        if (isInRange(ni, nj) && free[ni][nj]) {
                            dsu.unite(i, j, ni, nj);
                        }
                    }
                }
            }
        }
    }
}

/** Simple wrapper for problem configuration (kept for extensibility). */
final class SolverConfig { }

/** Directions used on the grid: up, left, down, right. */
enum Direction {
    UP(1, 0),
    LEFT(0, -1),
    DOWN(-1, 0),
    RIGHT(0, 1);

    final int dx;
    final int dy;

    Direction(int dx, int dy) {
        this.dx = dx;
        this.dy = dy;
    }
}

/** Utility class for fast input reading. */
final class InputReader {
    private final InputStream stream;
    private final byte[] buffer = new byte[1 << 10];
    private int bufferPointer = 0, bytesRead = 0;
    private final InputReader.SpaceCharFilter filter;

    InputReader(InputStream stream) {
        this.stream = stream;
    }

    private int read() {
        if (bytesRead == -1) {
            throw new EOFException();
        }
        if (bufferPointer >= bytesRead) {
            bytesRead = stream.read(buffer);
            bufferPointer = 0;
            if (bytesRead <= 0) {
                return -1;
            }
        }
        return buffer[bufferPointer++];
    }

    /** Reads a signed integer from the input. */
    int readInt() {
        int c = read();
        while (isSpaceChar(c)) {
            c = read();
        }
        int sign = 1;
        if (c == '-') {
            sign = -1;
            c = read();
        }
        int value = 0;
        do {
            if (!Character.isDigit((char) c)) {
                throw new IllegalArgumentException("Invalid digit: " + (char) c);
            }
            value = value * 10 + (c - '0');
            c = read();
        } while (!isSpaceChar(c));
        return value * sign;
    }

    /** Checks whether the given character type should be treated as whitespace. */
    boolean isSpaceChar(int c) {
        return filter != null ? filter.isSpaceChar(c) : isWhitespace(c);
    }

    private static boolean isWhitespace(int c) {
        return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
    }

    /** Reads the next non‑whitespace character. */
    char readCharacter() {
        int c;
        do {
            c = read();
        } while (isSpaceChar(c));
        return (char) c;
    }

    /** Functional interface for custom whitespace filters. */
    interface SpaceCharFilter {
        boolean isSpaceChar(int ch);
    }
}

/** Union‑Find (Disjoint Set Union) structure for a rectangular grid. */
final class DSU {
    private final int rows;
    private final int cols;
    private final int[] parent;
    private final int[] size;

    DSU(int rows, int cols) {
        this.rows = rows;
        this.cols = cols;
        int gridSize = rows * cols;
        parent = IntStream.range(0, gridSize).toArray();
        size = ArrayUtils.createArray(gridSize, 1);
    }

    /** Finds the root of an element with path compression. */
    int findParent(int v) {
        if (parent[v] == v) {
            return v;
        }
        return parent[v] = findParent(parent[v]);
    }

    /** Merges the sets containing the two supplied grid indices. */
    void unite(int i1, int j1, int i2, int j2) {
        uniteIndices(toIndex(i1, j1), toIndex(i2, j2));
    }

    private void uniteIndices(int a, int b) {
        int pa = findParent(a);
        int pb = findParent(b);
        if (pa != pb) {
            parent[pa] = pb;
            size[pb] += size[pa];
        }
    }

    /** Returns the root index of the cell (i, j). */
    int findParent(int i, int j) {
        return findParent(toIndex(i, j));
    }

    /** Returns the size of the set containing the supplied index. */
    int getSize(int index) {
        return size[findParent(index)];
    }

    /** Helper converting 2‑D coordinates into a linear index. */
    private int toIndex(int i, int j) {
        return i * cols + j;
    }
}

