/**
 * Reads a grid of characters, builds a union‑find structure over the empty cells,
 * and writes a symbol on every non‑empty cell that reflects the number of distinct
 * empty regions adjacent to it.
 *
 * The refactored version improves readability, naming, and modularity while
 * preserving the original algorithmic behaviour.
 */
public class FloodFillProcessor {

    /** Directions used for scanning neighbours (down, right, up, left). */
    private static final int[][] DIRECTIONS = {
            {1, 0},   // down
            {0, 1},   // right
            {-1, 0},  // up
            {0, -1}   // left
    };

    private final InputReader input;
    private final PrintWriter output;
    private char[][] board;
    private int rows, cols;

    public static void main(String[] args) {
        new FloodFillProcessor().run();
    }

    /** Entry point that wires I/O, processing and output together. */
    private void run() {
        input = new InputReader(System.in);
        output = new PrintWriter(System.out);
        readBoard();
        process();
        printBoard();
        output.close();
    }

    /** Reads the dimensions and the board from the input stream. */
    private void readBoard() {
        rows = input.nextInt();
        cols = input.nextInt();

        board = new char[rows][cols];
        for (int r = 0; r < rows; r++) {
            String line = input.next();
            for (int c = 0; c < cols; c++) {
                board[r][c] = line.charAt(c);
            }
        }
    }

    /** Core processing: builds union‑find, computes replacement symbols and writes them. */
    private void process() {
        UnionFind union = new UnionFind(rows * cols);

        // 1️⃣ Build unions among adjacent empty cells ('.')
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (board[r][c] != '.') {
                    continue;
                }
                if (r + 1 < rows && board[r + 1][c] == '.') {
                    union.link(r * cols + c, (r + 1) * cols + c);
                }
                if (c + 1 < cols && board[r][c + 1] == '.') {
                    union.link(r * cols + c, r * cols + c + 1);
                }
            }
        }

        // 2️⃣ For each non‑empty cell, count distinct neighbouring empty components
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (board[r][c] == '.') {
                    continue;
                }
                board[r][c] = symbolForCell(r, c, union);
            }
        }
    }

    /** Returns the symbol that should be written at (row, col). */
    private char symbolForCell(int row, int col, UnionFind uf) {
        int[] neighbourRoots = new int[4];
        int rootCount = 0;
        int sum = 0;

        for (int[] dir : DIRECTIONS) {
            int nr = row + dir[0];
            int nc = col + dir[1];
            if (isInside(nr, nc) && board[nr][nc] == '.') {
                int root = uf.root(nr * cols + nc);
                // Skip duplicates – keep only distinct component roots
                boolean duplicate = false;
                for (int i = 0; i < rootCount; i++) {
                    if (root == neighbourRoots[i]) {
                        duplicate = true;
                        break;
                    }
                }
                if (duplicate) {
                    continue;
                }
                neighbourRoots[rootCount++] = root;
                sum -= uf.upper[root];          // upper stores negative size of component
            }
        }

        int value = (sum + 1) % 10;           // map to a digit 0‑9
        return (char) ('0' + value);
    }

    /** Helper that checks whether a cell coordinate is inside the board. */
    private boolean isInside(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    /** Prints the resulting board to the output stream. */
    private void printBoard() {
        for (int r = 0; r < rows; r++) {
            out.println(new String(board[r]));
        }
    }

    /* --------------------------------------------------------------------- */
    /*                         UNION‑FIND IMPLEMENTATION                     */
    /* --------------------------------------------------------------------- */

    /** Simple Union‑Find (Disjoint Set Union) that works on integer indices. */
    private static final class UnionFind {
        /** Negative sizes are stored as negative values; the absolute value + 1 is the component size. */
        private final int[] parent;

        public UnionFind(int size) {
            parent = new int[size];
            Arrays.fill(parent, -1);
        }

        /** Returns the representative (root) of the set containing {@code x}. */
        public int root(int x) {
            if (parent[x] < 0) {
                return x;
            }
            return parent[x] = root(parent[x]);   // path compression
        }

        /**
         * Merges the sets of {@code a} and {@code b}.
         * @return {@code true} if a merge happened, {@code false} if they were already united.
         */
        public boolean link(int a, int b) {
            int rootA = root(a);
            int rootB = root(b);
            if (rootA == rootB) {
                return false;
            }
            // Union by size – attach smaller tree under larger one
            if (parent[rootB] < parent[rootA]) {
                int tmp = rootA;
                rootA = rootB;
                rootB = tmp;
            }
            parent[rootA] += parent[rootB];
            parent[rootB] = rootA;
            return true;
        }
    }

    /* --------------------------------------------------------------------- */
    /*                         INPUT / OUTPUT HELPERS                        */
    /* --------------------------------------------------------------------- */

    /** Minimal input reader that tokenises lines on demand. */
    private static final class InputReader {
        private final BufferedReader br;
        private StringTokenizer st;

        public InputReader(InputStream source) {
            br = new BufferedReader(new InputStreamReader(source));
        }

        /** Returns the next token, read lazily from {@code BufferedReader}. */
        private String readToken() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                String line = br.readLine();
                if (line == null) {
                    return null;
                }
                st = new StringTokenizer(line);
            }
            return st.nextToken();
        }

        public String next() {
            try {
                return readToken();
            } catch (IOException e) {
                throw new UncheckedIOException(e);
            }
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public long nextLong() {
            return Long.parseLong(next());
        }

        public double nextDouble() {
            return Double.parseDouble(next());
        }
    }
}

