/**
 * Solves the grid transformation problem:
 *   - Reads a grid of '.' and '*' characters.
 *   - Converts each '*' into a digit (0‑9) that represents the sum of the sizes of
 *     adjacent empty components (connected via '.'), taken modulo 10.
 *
 * The implementation is split into small, focused methods and uses proper
 * encapsulation, constants, and Java best practices.
 */
public class GridProcessor {

    /** Modulo used for the final digit calculation (the original code used Long.MAX_VALUE). */
    private static final long MOD = Long.MAX_VALUE;

    /**
     * Fast scanner that reads tokens from {@code System.in}. It implements
     * {@link AutoCloseable} so it can be used in a try‑with‑resources block.
     */
    private static class FastScanner implements AutoCloseable {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner(InputStream source) {
            br = new BufferedReader(new InputStreamReader(source));
            st = null;
        }

        private String nextToken() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                String line = br.readLine();
                if (line == null) {
                    return null;
                }
                st = new StringTokenizer(line);
            }
            return st.nextToken();
        }

        int nextInt() throws IOException { return Integer.parseInt(nextToken()); }
        long nextLong() throws IOException { return Long.parseLong(nextToken()); }
        double nextDouble() throws IOException { return Double.parseDouble(nextToken()); }
        char nextChar() throws IOException { return (char) br.read(); }
        /** Returns the remaining part of the current line. */
        String nextString() throws IOException { return br.readLine(); }
    }

    /** Directions used for neighbour traversal. */
    private enum Direction {
        UP(-1, 0), DOWN(1, 0), LEFT(0, -1), RIGHT(0, 1);
        final int di, dj;
        Direction(int di, int dj) { this.di = di; this.dj = dj; }

        int[] offset() { return new int[]{di, dj}; }
    }

    public static void main(String[] args) throws Exception {
        // Try‑with‑resources automatically closes the scanner.
        try (FastScanner scanner = new FastScanner(System.in)) {
            int n = scanner.nextInt();
            int m = scanner.nextInt();

            int[][] grid = readGrid(scanner, n, m);
            int[][] componentId = new int[n][m];          // component identifier for each cell
            int[] componentSize = new int[n * m + 1];      // size of each component (1‑based)
            boolean[][] visited = new boolean[n][m];      // visited flag for DFS

            int componentCount = 0;
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    if (!visited[i][j] && grid[i][j] == 0) {
                        componentCount++;
                        dfs(i, j, componentCount, visited, grid,
                            componentId, componentSize);
                    }
                }
            }

            StringBuilder out = new StringBuilder();
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    if (grid[i][j] == 0) {
                        out.append('.');                         // original empty cell
                    } else {
                        Set<Integer> neighbourComponents = collectNeighbourComponents(i, j, grid);
                        long sum = 1;                               // count the current '*' cell
                        for (int id : neighbourComponents) {
                            sum += componentSize[id];
                        }
                        out.append((int) (sum % 10));               // digit after modulo
                    }
                }
                out.append('\n');
            }
            System.out.print(out.toString());
        }
    }

    /** Reads the raw grid and converts it to an int matrix: 0 = '.', 1 = '*'. */
    private static int[][] readGrid(FastScanner scanner, int n, int m) throws IOException {
        int[][] matrix = new int[n][m];
        for (int i = 0; i < n; i++) {
            String line = scanner.nextString();
            for (int j = 0; j < m; j++) {
                matrix[i][j] = line.charAt(j) == '*' ? 1 : 0;
            }
        }
        return matrix;
    }

    /** Depth‑first search that marks a component and records its size. */
    private static void dfs(int i, int j, int compId,
                            boolean[][] visited, int[][] grid,
                            int[][] componentId, int[] componentSize) {
        visited[i][j] = true;
        componentId[i][j] = compId;
        componentSize[compId]++;               // increase size of this component

        for (Direction dir : Direction.values()) {
            int ni = i + dir.di;
            int nj = j + dir.dj;
            if (inBounds(ni, nj, grid.length, grid[0].length)
                && grid[ni][nj] == 0 && !visited[ni][nj]) {
                dfs(ni, nj, compId, visited, grid, componentId, componentSize);
            }
        }
    }

    /** Returns the set of component ids that are orthogonally adjacent to (i,j). */
    private static Set<Integer> collectNeighbourComponents(int i, int j, int[][] grid) {
        Set<Integer> neighbours = new HashSet<>();
        for (Direction dir : Direction.values()) {
            int ni = i + dir.di;
            int nj = j + dir.dj;
            if (inBounds(ni, nj, grid.length, grid[0].length) && grid[ni][nj] == 0) {
                neighbours.add(gridComponentId[ni][nj]);   // placeholder – filled later
            }
        }
        return neighbours;
    }

    /** Utility: checks bounds of a 2‑D coordinate. */
    private static boolean inBounds(int row, int col, int rows, int cols) {
        return row >= 0 && row < rows && col >= 0 && col < cols;
    }
}

