/**
 * Refactored version of the original program.
 * <p>
 * The program reads a grid consisting of '.' (empty) and '*' (obstacle) cells,
 * computes connected components of empty cells, and then builds an output grid
 * where each obstacle cell shows a digit that represents the size of the
 * surrounding empty region (+1) modulo 10.
 * </p>
 */
public class Main {

    // Direction vectors for the four neighbours (up, down, left, right)
    private static final int[] DIR_R = {-1, 1, 0, 0};
    private static final int[] DIR_C = {0, 0, -1, 1};

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());

        int n = nextInt(st);
        int m = nextInt(st);

        // Read the grid
        char[][] grid = new char[n][];
        for (int i = 0; i < n; i++) {
            grid[i] = br.readLine().toCharArray();
        }

        // componentId[i][j] holds the id of the component that cell (i,j) belongs to
        int[][] componentId = new int[n][m];
        // componentSize[k] holds the size of component k (index = component number)
        int[] componentSize = new int[n * m + 1];
        int componentCount = 0;

        // -----------------------------------------------------------------------
        // First pass – label each '.' cell with its component number and count size
        // -----------------------------------------------------------------------
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i][j] == '.' && componentId[i][j] == 0) {
                    componentCount++;
                    int size = dfs(grid, componentId, componentSize, componentCount, i, j);
                    componentSize[componentCount] = size;
                }
            }
        }

        // -----------------------------------------------------------------------
        // Second pass – build the output board
        // -----------------------------------------------------------------------
        StringBuilder out = new StringBuilder();
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i][j] == '*') {
                    out.append(computeDigit(i, j, grid, componentId, componentSize));
                } else {
                    out.append('.');
                }
            }
            out.append('\n');
        }
        System.out.print(out.toString());
    }

    /**
     * Depth‑first search that assigns a component id to each reachable '.' cell
     * and returns the size of that component.
     */
    private static int dfs(char[][] grid,
                           int[][] componentId,
                           int[] componentSize,
                           int compNumber,
                           int r,
                           int c) {
        if (componentId[r][c] != 0) {
            return 0;
        }
        componentId[r][c] = compNumber;
        int size = 1;

        for (int d = 0; d < 4; d++) {
            int nr = r + DIR_R[d];
            int nc = c + DIR_C[d];
            if (nr < 0 || nr >= grid.length || nc < 0 || nc >= grid[0].length) {
                continue;
            }
            if (grid[nr][nc] != '.') {
                continue;
            }
            size += dfs(grid, componentId, componentSize, compNumber, nr, nc);
        }
        return size;
    }

    /**
     * For a cell that originally contained '*', compute the digit that should
     * appear at that position in the output grid.
     */
    private static char computeDigit(int r, int c,
                                     char[][] grid,
                                     int[][] componentId,
                                     int[] componentSize) {
        HashSet<Integer> neighboringComponents = new HashSet<>();

        for (int d = 0; d < 4; d++) {
            int nr = r + DIR_R[d];
            int nc = c + DIR_C[d];
            if (nr < 0 || nr >= grid.length || nc < 0 || nc >= grid[0].length) {
                continue;
            }
            if (grid[nr][nc] != '.') {
                continue;
            }
            int comp = componentId[nr][nc];
            if (comp != 0) {
                neighboringComponents.add(comp);
            }
        }

        int totalEmptyCells = 0;
        for (int comp : neighboringComponents) {
            totalEmptyCells += componentSize[comp];
        }

        int digit = (totalEmptyCells + 1) % 10;
        return Character.forDigit(digit, 10);
    }

    // ---------------------------------------------------------------------------
    // Helper methods for token based input reading (mirroring the original code)
    // ---------------------------------------------------------------------------
    private static int nextInt(StringTokenizer tok) {
        return Integer.parseInt(tok.nextToken());
    }

    private static long nextLong(StringTokenizer tok) {
        return Long.parseLong(tok.nextToken());
    }

    private static double nextDouble(StringTokenizer tok) {
        return Double.parseDouble(tok.nextToken());
    }
}

/*
 * Labyrinth – a refactored solution for the original “TheLabyrinth” program.
 *
 * What was improved?
 *  • Meaningful class & method names.
 *  • Removed static mutable global state – component sizes are kept in an
 *    instance map inside the Labyrinth object.
 *  • Encapsulated the grid and its processing logic in a dedicated
 *    `LabyrinthModel` class.
 *  • Used Java 8+ features where they improve readability (try‑with‑resources,
 *    streams, local‑type inference).
 *  • Added Javadoc comments and inline documentation.
 *  • Fixed bugs in the original code (e.g. typo in counter name) and made
 *    the behaviour deterministic.
 *  • Made the program easily testable by isolating I/O from core logic.
 */

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Objects;

/**
 * Entry point – reads the matrix from standard input and prints the result.
 */
public final class TheLabyrinth {

    private TheLabyrinth() { /* utility class – no instances */ }

    public static void main(String[] args) throws IOException {
        // --- Input -------------------------------------------------------------
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in))) {
            String[] dimensions = br.readLine().trim().split("\\s+");
            if (dimensions.length != 2) {
                throw new IllegalArgumentException("First line must contain exactly two integers");
            }
            int rows = Integer.parseInt(dimensions[0]);
            int columns = Integer.parseInt(dimensions[1]);

            String[] matrixLines = new String[rows];
            for (int i = 0; i < rows; i++) {
                matrixLines[i] = br.readLine();
                if (matrixLines[i] == null || matrixLines[i].length() != columns) {
                    throw new IllegalArgumentException(
                        "Each of the next " + rows + " lines must contain exactly " + columns + " characters");
                }
            }

            // --- Core logic ------------------------------------------------------
            LabyrinthModel model = new LabyrinthModel(rows, columns);
            model.loadMatrix(matrixLines);
            String[] output = model.render();

            // --- Output -----------------------------------------------------------
            for (int i = 0; i < output.length; i++) {
                System.out.print(output[i]);
                if (i != output.length - 1) {
                    System.out.println();
                }
            }
        }
    }
}

/**
 * Holds the mutable state of the labyrinth (grid, component information) and
 * performs all required transformations.
 */
final class LabyrinthModel {

    /** The raw adjacency matrix where 0 = open cell ('.'), -1 = wall ('x'). */
    private final int[][] grid;

    /** Mapping from component identifier to its size. */
    private final Map<Integer, Integer> componentSizeMap = new HashMap<>();

    /** Counter used to assign unique identifiers to discovered components. */
    private int nextComponentId = 1;

    /**
     * Creates a new model with the given dimensions.
     *
     * @param rows    number of rows in the matrix
     * @param columns number of columns in the matrix
     */
    LabyrinthModel(int rows, int columns) {
        this.grid = new int[rows][columns];
    }

    /** Loads the textual representation of the matrix into the internal grid. */
    void loadMatrix(String[] lines) {
        for (int r = 0; r < lines.length; r++) {
            String line = lines[r];
            for (int c = 0; c < line.length(); c++) {
                char ch = line.charAt(c);
                grid[r][c] = (ch == '.') ? 0 : -1;
            }
        }
    }

    /**
     * Computes the transformed matrix where every wall cell displays the size
     * (mod 10) of the set of adjacent distinct components.
     *
     * @return an array of strings ready for printing
     */
    String[] render() {
        computeComponentSizes();
        StringBuilder[] results = new StringBuilder[grid.length];

        for (int r = 0; r < grid.length; r++) {
            results[r] = new StringBuilder(grid[r].length);
            for (int c = 0; c < grid[r].length; c++) {
                if (grid[r][c] == -1) {
                    results[r].append(calculateWallSymbol(r, c));
                } else {
                    results[r].append('.');
                }
            }
        }

        // Convert StringBuilder[] to String[]
        return java.util.Arrays.stream(results).map(StringBuilder::toString).toArray(String[]::new);
    }

    /** Finds all open components with DFS and records their sizes. */
    private void computeComponentSizes() {
        for (int r = 0; r < grid.length; r++) {
            for (int c = 0; c < grid[0].length; c++) {
                if (grid[r][c] == 0) {
                    int componentId = nextComponentId++;
                    exploreComponent(r, c, componentId);
                }
            }
        }
    }

    /** Depth‑first search that marks cells of a component with {@code componentId}. */
    private void exploreComponent(int startR, int startC, int componentId) {
        exploreNeighbour(startR, startC, componentId, new DFSState(startR, startC, componentId));
    }

    /** Helper that wraps the DFS recursion state. */
    private void exploreNeighbour(int r, int c, int componentId, DFSState state) {
        if (!state.isInBounds(r, c) || grid[r][c] != 0) {
            return;
        }
        grid[r][c] = componentId;
        state.incrementSize();
        // Explore four neighbours
        exploreNeighbour(r, c + 1, componentId, state);
        exploreNeighbour(r, c - 1, componentId, state);
        exploreNeighbour(r + 1, c, componentId, state);
        exploreNeighbour(r - 1, c, componentId, state);
    }

    /** Returns the size of the component that contains the given cell (or 0 for walls). */
    private int sizeAt(int r, int c) {
        if (!isInBounds(r, c) || grid[r][c] == -1) {
            return 0;
        }
        return componentSizeMap.get(grid[r][c]);
    }

    /** Determines whether a coordinate lies inside the grid. */
    private boolean isInBounds(int r, int c) {
        return r >= 0 && r < grid.length && c >= 0 && c < grid[0].length;
    }

    /** Computes the visual symbol for a wall cell based on its adjacent component sizes. */
    private char calculateWallSymbol(int r, int c) {
        // Use a Set to guarantee uniqueness of neighboring component identifiers.
        var neighbourComponents = new HashSet<Integer>();

        // Check the four orthogonal neighbours.
        for (Direction dir : Direction.values()) {
            int nr = r + dir.rowOffset();
            int nc = c + dir.columnOffset();
            neighbourComponents.add(sizeAt(nr, nc));
        }

        // Sum the distinct sizes, take modulo 10 and convert to a printable character.
        int summed = neighbourComponents.stream()
                .mapToInt(Integer::intValue)
                .sum() % 10;
        return Character.forDigit(summed, 10);
    }

    /** Simple enum describing the four orthogonal directions. */
    private enum Direction {
        UP(-1, 0),
        DOWN(1, 0),
        LEFT(0, -1),
        RIGHT(0, 1);

        private final int rowOffset;
        private final int columnOffset;

        Direction(int rowOffset, int columnOffset) {
            this.rowOffset = rowOffset;
            this.columnOffset = columnOffset;
        }

        int rowOffset()   { return rowOffset; }
        int columnOffset() { return columnOffset; }
    }

    /** Holds the mutable state of a DFS exploration. */
    private static final class DFSState {
        private final int startRow;
        private final int startColumn;
        private final int componentId;
        private int size = 0;

        DFSState(int startRow, int startColumn, int componentId) {
            this.startRow = startRow;
            this.startColumn = startColumn;
            this.componentId = componentId;
        }

        boolean isInBounds(int r, int c) {
            return r >= 0 && r < LabyrinthModel.this.grid.length &&
                   c >= 0 && c < LabyrinthModel.this.grid[0].length;
        }

        void incrementSize() {
            size++;
        }

        int getSize() {
            return size;
        }
    }
}

