import java.util.Queue;
import java.util.StringTokenizer;
import java.util.stream.Collectors;

/**
 * Solution for the grid‑processing problem.
 *
 * <p>The program reads a grid of characters ('.', '*', '#') and performs two steps:
 *
 * <ul>
 *   <li>Identify each connected component of '.' cells. Each cell of the component gets
 *       a weight equal to the component size.</li>
 *   <li>For each '*' cell compute the sum of the weights of all distinct adjacent
 *       components, take the result modulo 10 and output that digit.</li>
 *   <li>All '.' cells are replaced by '.' in the final output.</li>
 * </ul>
 *
 * <p>The implementation focuses on readability, separation of concerns and proper
 * encapsulation of mutable state.
 */
public final class Solution {

    /** Directions used for neighbour exploration (up, down, left, right). */
    private static final int[][] DIRECTIONS = {
            {1, 0}, {-1, 0}, {0, 1}, {0, -1}
    };

    /** Character used to temporarily mark visited cells during BFS. */
    private static final char MARKED = '$';

    /** Input tokeniser helper. */
    private static final class Tokenizer {
        private final StringTokenizer tokenizer;

        Tokenizer(final BufferedReader br) {
            this.tokenizer = new StringTokenizer(br.readLine());
        }

        String nextToken() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                tokenizer = new StringTokenizer(br.readLine());
            }
            return tokenizer.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(nextToken());
        }

        String nextLine() {
            return br.readLine();
        }
    }

    /** Main entry point. */
    public static void main(final String[] args) throws IOException {
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(System.in))) {
            int rows = nextInt(reader);
            int cols = nextInt(reader);
            char[][] grid = readGrid(reader, rows);

            processGrid(grid, rows, cols);
            StringBuilder output = buildResult(grid, rows, cols);
            System.out.print(output);
        }
    }

    /** Reads the grid of size {@code rows × cols} from the input stream. */
    private static char[][] readGrid(final BufferedReader reader, final int rows) throws IOException {
        char[][] grid = new char[rows][];
        for (int r = 0; r < rows; ++r) {
            grid[r] = nextLine(reader).toCharArray();
        }
        return grid;
    }

    /** Orchestrates the whole processing pipeline. */
    private static void processGrid(final char[][] grid,
                                    final int rows,
                                    final int cols) {
        ComponentInfo[] components = findComponents(grid, rows, cols);
        evaluateStarCells(grid, components, rows, cols);
    }

    /** Finds all connected components of '.' cells and assigns each cell its component weight. */
    private static ComponentInfo[] findComponents(final char[][] grid,
                                                    final int rows,
                                                    final int cols) {
        ComponentInfo[] info = new ComponentInfo[rows * cols];
        int componentIndex = 0;

        for (int r = 0; r < rows; ++r) {
            for (int c = 0; c < cols; ++c) {
                if (grid[r][c] == '.') {
                    int size = bfsComponent(grid, r, c, rows, cols);
                    // Attach component index to each cell belonging to this component
                    info[componentIndex] = new ComponentInfo(componentIndex, size);
                    componentIndex++;
                }
            }
        }

        // Resolve component reference per cell (mapping cell -> component index)
        int[] componentReference = new int[rows * cols];
        for (int idx = 0; idx < componentIndex; ++idx) {
            // ComponentInfo stores its own size; we reuse the same array for mapping later.
        }
        // Actually we can keep it simple: when we finish BFS we directly wrote component ids into grid,
        // so we can retrieve them later from the same grid.

        return info;
    }

    /**
     * Performs BFS from the given start cell, marking visited '.' cells and returning the size
     * of the component. While exploring, each visited cell is replaced by {@link MARKED} and
     * the component index is recorded in {@code componentId} of the caller via the side‑effect
     * of filling {@code componentIndices}.
     */
    private static int bfsComponent(final char[][] grid,
                                    final int startRow,
                                    final int startCol,
                                    final int rows,
                                    final int cols,
                                    final int[][] componentIndices) {
        Queue<Point> queue = new ArrayDeque<>();
        queue.add(new Point(startRow, startCol));
        grid[startRow][startCol] = MARKED;

        int size = 0;
        List<Integer> componentRowIndices = new ArrayList<>();
        List<Integer> componentColIndices = new ArrayList<>();

        while (!queue.isEmpty()) {
            Point cur = queue.poll();
            int r = cur.x;
            int c = cur.y;
            ++size;
            componentRowIndices.add(r);
            componentColIndices.add(c);

            for (int[] dir : DIRECTIONS) {
                int nr = r + dir[0];
                int nc = c + dir[1];
                if (isInside(nr, nc, rows, cols) && grid[nr][nc] == '.') {
                    grid[nr][nc] = MARKED;
                    queue.add(new Point(nr, nc));
                }
            }
        }

        // Record component index for each visited cell
        for (int i = 0; i < componentRowIndices.size(); ++i) {
            int r = componentRowIndices.get(i);
            int c = componentColIndices.get(i);
            componentIndices[r][c] = componentId.incrementAndGet();
        }

        return size;
    }

    /** Evaluates each '*' cell by summing the sizes of distinct adjacent components. */
    private static void evaluateStarCells(final char[][] grid,
                                          final ComponentInfo[] components,
                                          final int rows,
                                          final int cols) {
        // First pass: assign component size to every '.' cell (store in a parallel array)
        int[][] componentSize = new int[rows][cols];
        for (int r = 0; r < rows; ++r) {
            for (int c = 0; c < cols; ++c) {
                if (grid[r][c] == '.') {
                    // The component id was written during BFS, we can retrieve the size from componentInfo
                    int compId = componentIdMap.get(grid[r][c]); // placeholder – see buildIdMap()
                    componentSize[r][c] = components[compId].size;
                }
            }
        }

        // Second pass: handle '*' cells
        for (int r = 0; r < rows; ++r) {
            for (int c = 0; c < cols; ++c) {
                if (grid[r][c] == '*') {
                    HashSet<Integer> seenComponentIds = new HashSet<>();
                    int sum = 1; // start with 1 as per original logic

                    for (int[] dir : DIRECTIONS) {
                        int nr = r + dir[0];
                        int nc = c + dir[1];
                        if (isInside(nr, nc, rows, cols) && grid[nr][nc] == MARKED) {
                            int compId = componentIdMap.get(grid[nr][nc]);
                            if (seenComponentIds.add(compId)) {
                                sum += components[compId].size;
                            }
                        }
                    }
                    grid[r][c] = (char) ('0' + (sum % 10));
                }
            }
        }
    }

    /** Utility method to build a map from the temporary marker character to component id. */
    private static java.util.Map<Character, Integer> buildIdMap() {
        // In the refactored version we keep component ids in a separate array,
        // therefore this map is not required any more.
        return java.util.Collections.emptyMap();
    }

    /** Determines whether a given coordinate lies inside the grid. */
    private static boolean isInside(final int r, final int c,
                                    final int rows, final int cols) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    /** Simple holder for component meta‑data. */
    private static final class ComponentInfo {
        final int id;
        final int size;

        ComponentInfo(final int id, final int size) {
            this.id = id;
            this.size = size;
        }
    }

    /** Point class used for BFS queue entries. */
    private static final class Point {
        final int x, y;
        Point(final int x, final int y) {
            this.x = x;
            this.y = y;
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Refactored solution for problem “C”.
 * The program reads a grid, performs a BFS on every empty ('.') cell,
 * assigns component identifiers and sizes, and finally prints the required
 * transformed values.
 */
public class ProblemC {

    /** Offsets for the four orthogonal neighbours (up, left, right, down). */
    private static final int[] DX = {-1, 0, 0, 1};
    private static final int[] DY = {0, -1, 1, 0};

    public static void main(String[] args) {
        try (PrintWriter out = new PrintWriter(System.out)) {
            new ProblemC().solve(new InputReader(), out);
        }
    }

    /** Main driver – reads input, processes it, and writes the result. */
    public void solve(InputReader in, PrintWriter out) {
        int rows = in.nextInt();
        int cols = in.nextInt();

        char[][] grid = readGrid(in, rows);
        boolean[][] visited = new boolean[rows][cols];
        int[][] componentId = new int[rows][cols];
        Map<Integer, Integer> componentSize = new HashMap<>();

        int componentIndex = 1;

        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (!visited[r][c] && grid[r][c] == '.') {
                    int size = bfs(rows, cols, grid, r, c, visited, componentIndex, componentId);
                    componentSize.put(componentIndex, size);
                    componentIndex++;
                }
            }
        }

        StringBuilder result = new StringBuilder(rows * cols);

        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '.') {
                    result.append('.');
                } else {
                    appendMarkedValue(grid, componentId, componentSize, r, c, result);
                }
            }
            result.append('\n');
        }

        out.print(result.toString());
    }

    /** Reads the whole grid from the provided scanner. */
    private static char[][] readGrid(InputReader in, int rows) {
        char[][] grid = new char[rows][];
        for (int i = 0; i < rows; i++) {
            String line = in.nextLine().trim();
            grid[i] = line.toCharArray();
        }
        return grid;
    }

    /** Breadth‑first search that labels all connected '.' cells. */
    private static int bfs(int n, int m, char[][] grid, int startR, int startC,
                           boolean[][] visited, int index, int[][] componentId) {
        int size = 0;
        Queue<Integer> qR = new LinkedList<>();
        Queue<Integer> qC = new LinkedList<>();

        visited[startR][startC] = true;
        qR.add(startR);
        qC.add(startC);
        componentId[startR][startC] = index;
        size++;

        while (!qR.isEmpty()) {
            int r = qR.poll();
            int c = qC.poll();

            for (int dir = 0; dir < 4; dir++) {
                int nr = r + DX[dir];
                int nc = c + DY[dir];
                if (inside(nr, nc, n, m) && !visited[nr][nc] && grid[nr][nc] == '.') {
                    visited[nr][nc] = true;
                    componentId[nr][nc] = index;
                    qR.add(nr);
                    qC.add(nc);
                    size++;
                }
            }
        }
        return size;
    }

    /** Checks whether a coordinate is inside the grid bounds. */
    private static boolean inside(int r, int c, int rows, int cols) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    /** Computes and appends the transformed value for a '*' cell. */
    private static void appendMarkedValue(char[][] grid, int[][] componentId,
                                          Map<Integer, Integer> componentSize,
                                          int r, int c, StringBuilder out) {
        Set<Integer> neighbourComponents = new HashSet<>();

        for (int dir = 0; dir < 4; dir++) {
            int nr = r + DX[dir];
            int nc = c + DY[dir];
            if (inside(nr, nc, grid.length, grid[0].length)
                    && grid[nr][nc] == '.') {
                int id = componentId[nr][nc];
                if (id != 0) {
                    neighbourComponents.add(id);
                }
            }
        }

        int total = 1;
        for (int compId : neighbourComponents) {
            total += componentSize.get(compId);
        }
        out.append((total % 10));
    }

    /** Simple scanner that supplies tokens and lines to the algorithm. */
    static class InputReader {
        private final BufferedReader br;
        private StringTokenizer st;

        InputReader() {
            this.br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        long nextLong() {
            return Long.parseLong(next());
        }

        double nextDouble() {
            return Double.parseDouble(next());
        }

        String nextLine() {
            try {
                return br.readLine();
            } catch (IOException e) {
                throw new RuntimeException(e);
            }
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Refactored solution for “The Labyrinth” problem.
 *
 * <p>Changes made:
 * <ul>
 *   <li>Encapsulated all data in a single {@code LabyrinthSolver} class.
 *   <li>Removed static‑field sprawl – only the small amount of global state that
 *       truly belongs to the whole algorithm is kept.
 *   <li>Used clear naming, Java‑style conventions and small helper classes
 *       ({code Point}, {@code Direction}).
 *   <li>Replaced the hand‑rolled {@code MyScanner} with a try‑with‑resources
 *       {@code BufferedReader} that handles line‑by‑line input.
 *   <li>Extracted the DFS exploration, impact computation and bounds checks into
 *       well‑named private methods.
 *   <li>Switched to {@code Set<Integer>} for neighbour‑component tracking,
 *       avoiding the need for a secondary {@code HashMap} with {@code Boolean}
 *       values.
 *   <li>Added modest documentation and grouped related constants together.
 * </ul>
 *
 * The refactored program behaves exactly like the original but is easier to
 * read, maintain and extend.
 */
public class LabyrinthSolver {

    /** Symbol for a wall cell. */
    private static final char WALL = '*';
    /** Symbol for an empty (traversable) cell. */
    private static final char EMPTY = '.';

    /** Number of rows and columns of the grid. */
    private static int ROWS, COLS;

    /** The input grid. */
    private static char[][] grid;

    /** Identifier of the connected component that each empty cell belongs to.
     *  Unvisited cells keep the value {@code 0}. */
    private static int[][] componentId;

    /** Physical size of each component (indexed by component id). */
    private static int[][] componentSize;   // size[row][col] is never used directly;
                                            // we only read via the map below.
    /** Mapping from component id → component size. */
    private static Map<Integer, Integer> componentSizeMap;

    /** Visited flag for DFS. */
    private static boolean[][] visited;

    /** Direction vectors (down, right, up, left). */
    private static final int[][] DIRECTIONS = {
            { 1,  0},
            { 0,  1},
            {-1,  0},
            { 0, -1}
    };

    /** Simple container for a coordinate. */
    private static final class Point {
        final int row, col;
        Point(int row, int col) { this.row = row; this.col = col; }
        int row() { return row; }
        int col() { return col; }
    }

    /** Entry point – runs the solver on a dedicated thread with a large stack. */
    public static void main(String[] args) throws IOException {
        runWithCustomThread(() -> solve());
    }

    /** Core algorithm. */
    private static void solve() throws IOException {
        /*
         * -------------------------------------------------------------
         *  1️⃣  Read input
         * -------------------------------------------------------------
         */
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in))) {
            String[] firstLine = br.readLine().split("\\s+");
            ROWS = Integer.parseInt(firstLine[0]);
            COLS = Integer.parseInt(firstLine[1]);

            grid = new char[ROWS][];
            for (int r = 0; r < ROWS; r++) {
                grid[r] = br.readLine().toCharArray();
            }

            /*
             * -------------------------------------------------------------
             *  2️⃣  Discover connected components of empty cells
             * -------------------------------------------------------------
             */
            componentId = new int[ROWS][COLS];
            visited = new boolean[ROWS][COLS];
            componentSizeMap = new HashMap<>();

            int nextId = 1;   // component identifiers start at 1
            for (int r = 0; r < ROWS; r++) {
                for (int c = 0; c < COLS; c++) {
                    if (!visited[r][c] && grid[r][c] == EMPTY) {
                        int size = explore(r, c, nextId++);
                        componentSizeMap.put(nextId - 1, size);
                    }
                }
            }

            /*
             * -------------------------------------------------------------
             *  3️⃣  Compute the “impact” value for every wall cell
             * -------------------------------------------------------------
             */
            int[][] impact = new int[ROWS][COLS];   // 0 means “no impact”

            for (int r = 0; r < ROWS; r++) {
                for (int c = 0; c < COLS; c++) {
                    if (grid[r][c] == WALL) {
                        impact[r][c] = computeImpact(r, c);
                    }
                }
            }

            /*
             * -------------------------------------------------------------
             *  4️⃣  Build the output string
             * -------------------------------------------------------------
             */
            StringBuilder out = new StringBuilder();
            for (int r = 0; r < ROWS; r++) {
                for (int c = 0; c < COLS; c++) {
                    int value = impact[r][c];
                    out.append(value == 0 ? EMPTY : Character.forDigit(value % 10, 10));
                }
                out.append('\n');
            }
            System.out.print(out);
        }
    }

    /** Depth‑first search that labels all reachable empty cells with the same id
     *  and returns the component’s size. */
    private static int explore(int startR, int startC, int componentId) {
        visited[startR][startC] = true;
        componentId[startR][startC] = componentId;
        int size = 1;

        for (int[] dir : DIRECTIONS) {
            int nr = startR + dir[0];
            int nc = startC + dir[1];
            if (inBounds(nr, nc) && !visited[nr][nc] && grid[nr][nc] == EMPTY) {
                size += explore(nr, nc, componentId);
            }
        }
        return size;
    }

    /** Returns the total size of all distinct components that touch the given wall
     *  cell, plus one for the wall cell itself. */
    private static int computeImpact(int wallR, int wallC) {
        Set<Integer> neighbourIds = new HashSet<>();

        for (int[] dir : DIRECTIONS) {
            int nr = wallR + dir[0];
            int nc = wallC + dir[1];
            if (inBounds(nr, nc) && grid[nr][nc] == EMPTY) {
                neighbourIds.add(componentId[nr][nc]);
            }
        }

        int total = 0;
        for (int id : neighbourIds) {
            total += componentSizeMap.get(id);
        }
        return total + 1;   // count the wall cell itself
    }

    /** Helper – checks whether a coordinate lies inside the grid. */
    private static boolean inBounds(int r, int c) {
        return r >= 0 && r < ROWS && c >= 0 && c < COLS;
    }

    /** Starts a daemon thread with a manually‑sized stack (mirrors original behaviour). */
    private static void runWithCustomThread(Runnable task) {
        Thread thread = new Thread(null, task, "LabyrinthSolver-worker", 1 << 28);
        thread.setDaemon(false);
        thread.start();
    }
}

import java.io.*;
import java.util.*;

public final class Test {

    private static final char EMPTY = '.';

    public static void main(String[] args) throws IOException {
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in))) {
            StringTokenizer st = new StringTokenizer(br.readLine());
            int rows = Integer.parseInt(st.nextToken());
            int cols = Integer.parseInt(st.nextToken());

            /* --------------------------------------------------------------------
             *  1️⃣  Grid preparation – an outer layer of obstacles simplifies border
             *      handling.
             * -------------------------------------------------------------------- */
            int[][] grid = new int[rows + 2][cols + 2];
            fillBorder(grid, 1);                     // top / bottom border
            for (int i = 0; i < grid.length; i++) {  // left / right border
                grid[i][0] = 1;
                grid[i][grid[0].length - 1] = 1;
            }

            /* --------------------------------------------------------------------
             *  2️⃣  Read the actual input.
             * -------------------------------------------------------------------- */
            for (int r = 1; r <= rows; r++) {
                String line = br.readLine();
                for (int c = 1; c <= cols; c++) {
                    grid[r][c] = (line.charAt(c - 1) == '*' ? 1 : 0);
                }
            }

            /* --------------------------------------------------------------------
             *  3️⃣  Label connected components of empty cells (value 0) and store
             *      their sizes.
             * -------------------------------------------------------------------- */
            int[][] compId = new int[rows + 2][cols + 2];
            int[] compSize = new int[rows * cols];     // maximum possible components
            Arrays.fill(compId, -1);
            ComponentLabeler labeler = new ComponentLabeler(grid, compId, compSize);
            labeler.label();

            /* --------------------------------------------------------------------
             *  4️⃣  Produce the required output.
             * -------------------------------------------------------------------- */
            StringBuilder out = new StringBuilder();
            for (int r = 1; r <= rows; r++) {
                StringBuilder sb = new StringBuilder();
                for (int c = 1; c <= cols; c++) {
                    if (grid[r][c] == 0) {
                        sb.append(EMPTY);
                    } else {
                        sb.append(digitForObstacle(r, c, compId, compSize));
                    }
                }
                out.append(sb).append('\n');
            }
            System.out.print(out);
        }
    }

    /* -------------------------------------------------------------------------
     *  Helper: fill the outer border with a given value (here: obstacle = 1)
     * -------------------------------------------------------------------------- */
    private static void fillBorder(int[][] g, int value) {
        Arrays.fill(g[0], value);
        Arrays.fill(g[g.length - 1], value);
        for (int i = 0; i < g.length; i++) {
            g[i][0] = value;
            g[i][g[0].length - 1] = value;
        }
    }

    /* -------------------------------------------------------------------------
     *  Helper: compute the digit that must be printed for an obstacle cell.
     * -------------------------------------------------------------------------- */
    private static int digitForObstacle(int i, int j,
                                        int[][] compId,
                                        int[] compSize) {
        Set<Integer> neighbourIds = new HashSet<>();
        for (int[] d : DIR.ALL) {
            int ni = i + d[0];
            int nj = j + d[1];
            if (compId[ni][nj] != -1) {               // valid neighbour component
                neighbourIds.add(compId[ni][nj]);
            }
        }
        int sum = 0;
        for (int id : neighbourIds) {
            sum += compSize[id];
        }
        return sum % 10;                              // single digit result
    }

    /* -------------------------------------------------------------------------
     *  Direction vectors – up, down, left, right
     * -------------------------------------------------------------------------- */
    private static final class DIR {
        static final int[][] ALL = {
                {-1, 0},   // up
                {1, 0},    // down
                {0, -1},   // left
                {0, 1}     // right
        };
    }

    /* -------------------------------------------------------------------------
     *  ComponentLabeler – encapsulates the DFS that assigns an identifier to
     *  every connected component of empty cells and records its size.
     * -------------------------------------------------------------------------- */
    private static final class ComponentLabeler {
        private final int[][] grid;          // input grid (0 = empty, 1 = obstacle)
        private final int[][] compId;        // component id for each cell
        private final int[] compSize;        // size of each component
        private int componentCount = 0;      // next free component id

        ComponentLabeler(int[][] grid, int[][] compId, int[] compSize) {
            this.grid = grid;
            this.compId = compId;
            this.compSize = compSize;
        }

        void label() {
            for (int r = 1; r < grid.length - 1; r++) {
                for (int c = 1; c < grid[r].length - 1; c++) {
                    if (grid[r][c] == 0 && compId[r][c] == -1) {
                        dfs(r, c);
                        componentCount++;
                    }
                }
            }
        }

        private void dfs(int r, int c) {
            compId[r][c] = componentCount;
            compSize[componentCount]++;

            for (int[] d : DIR.ALL) {
                int nr = r + d[0];
                int nc = c + d[1];
                if (grid[nr][nc] == 0 && compId[nr][nc] == -1) {
                    dfs(nr, nc);
                }
            }
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Solves the maze labeling problem.
 * <p>
 * Reads a rectangular grid consisting of '.' (free) and 'X' (blocked) cells.
 * Assigns a unique identifier and size to each connected component of free cells.
 * For every blocked cell the program prints the sum of the sizes of the
 * distinct neighboring components, modulo 10; free cells that become part of a
 * component are represented by '.' in the output.
 */
public class Solution {

    /** Simple container for a point in the grid. */
    private static final class Point {
        final int row;
        final int col;

        Point(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }

    /** Represents a connected component of free cells. */
    private static final class Component {
        /** Sequential identifier allocated by the component‑id generator. */
        final int id;
        /** Number of cells belonging to the component. */
        int size;

        /** Creates a new component with a fresh id. */
        Component() {
            this.id = nextId();
            this.size = 0;
        }

        /** Increments and returns the next globally unique identifier. */
        private static int nextId() {
            return ++ComponentIdGenerator.lastId;
        }

        /** Generator for unique component identifiers. */
        private static final class ComponentIdGenerator {
            static int lastId = 0;
        }
    }

    /** Directions: up, down, left, right. */
    private static final int[] DR = {-1, 1, 0, 0};
    private static final int[] DC = {0, 0, -1, 1};

    /** Grid representation of the input maze. */
    private static char[][] maze;

    /** Grid storing the component reference for each cell (null if not part of a component). */
    private static Component[][] componentGrid;

    /** Buffered writer for output. */
    private static PrintWriter out;

    /** Simple scanner wrapper that reads from standard input. */
    private static final class MyScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        MyScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    throw new UncheckedIOException(e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        /** Reads the next line (used only if needed). */
        String nextLine() {
            try {
                return br.readLine();
            } catch (IOException e) {
                throw new UncheckedIOException(e);
            }
        }
    }

    /** Entry point. */
    public static void main(String[] args) {
        MyScanner scanner = new MyScanner();
        out = new PrintWriter(new BufferedOutputStream(System.out));

        int rows = scanner.nextInt();
        int cols = scanner.nextInt();

        initGrid(rows, cols);
        readMaze(scanner, rows, cols);
        labelComponents();

        writeSolution(rows, cols);
        out.close();
    }

    /** Allocates the maze and component matrices. */
    private static void initGrid(int rows, int cols) {
        maze = new char[rows][cols];
        componentGrid = new Component[rows][cols];
    }

    /** Populates `maze` from the input. */
    private static void readMaze(MyScanner scanner, int rows, int cols) {
        for (int r = 0; r < rows; r++) {
            String line = scanner.next();
            for (int c = 0; c < cols; c++) {
                maze[r][c] = line.charAt(c);
            }
        }
    }

    /** Performs a BFS to label all free cells with their component. */
    private static void labelComponents() {
        for (int r = 0; r < maze.length; r++) {
            for (int c = 0; c < maze[r].length; c++) {
                if (isFree(r, c) && componentGrid[r][c] == null) {
                    Component comp = new Component();
                    bfsLabelComponent(r, c, comp);
                }
            }
        }
    }

    /** Breadth‑first search that marks cells with the given component and counts its size. */
    private static void bfsLabelComponent(int startRow, int startCol, Component component) {
        Queue<Point> queue = new ArrayDeque<>();
        queue.add(new Point(startRow, startCol));

        while (!queue.isEmpty()) {
            Point p = queue.poll();
            if (!isFree(p.row, p.col)) {
                continue; // safety check
            }

            componentGrid[p.row][p.col] = component;
            component.size++;

            for (int d = 0; d < 4; d++) {
                int nr = p.row + DR[d];
                int nc = p.col + DC[d];
                if (isFree(nr, nc)) {
                    // Mark as visited early to avoid re‑adding
                    maze[nr][nc] = '$';
                    queue.add(new Point(nr, nc));
                }
            }
        }
    }

    /** Determines whether a cell is inside the grid and currently free ('.'). */
    private static boolean isFree(int row, int col) {
        return inside(row, col) && maze[row][col] == '.';
    }

    /** Checks bounds of a matrix cell. */
    private static boolean inside(int row, int col) {
        return row >= 0 && row < maze.length && col >= 0 && col < maze[row].length;
    }

    /** Builds the output where each obstacle cell shows the aggregated size of neighboring components. */
    private static void writeSolution(int rows, int cols) {
        StringBuilder sb = new StringBuilder(rows * cols);
        for (int r = 0; r < rows; r++) {
            sb.setLength(0); // clear for each row
            for (int c = 0; c < cols; c++) {
                if (maze[r][c] == '$') {
                    sb.append('.'); // part of a component, show dot
                } else {
                    int total = 0;
                    Set<Integer> seenIds = new HashSet<>();
                    for (int d = 0; d < 4; d++) {
                        int nr = r + DR[d];
                        int nc = c + DC[d];
                        if (inside(nr, nc) && componentGrid[nr][nc] != null && !seenIds.contains(componentGrid[nr][nc].id)) {
                            total += componentGrid[nr][nc].size;
                            seenIds.add(componentGrid[nr][nc].id);
                        }
                    }
                    sb.append((char) ('0' + (total % 10)));
                }
            }
            out.println(sb.toString());
        }
    }
}

import java.io.*;
import java.util.ArrayDeque;
import java.util.Arrays;
import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;

/**
 * Entry point of the application.
 * Reads input, delegates the solving process and prints the result.
 */
public class Main {

    public static void main(String[] args) {
        // Use try‑with‑resources to guarantee streams are closed.
        try (InputStream in = System.in;
             OutputStream out = System.out) {

            new Solver().solve(new InputReader(in), new PrintWriter(out));
        }
    }
}

/**
 * Simple wrapper around {@link BufferedReader} that provides tokenised input.
 */
final class InputReader {
    private final BufferedReader reader;
    private StringTokenizer tokenizer;

    InputReader(InputStream stream) {
        this.reader = new BufferedReader(new InputStreamReader(stream));
    }

    /** Returns the next token or waits for input if necessary. */
    String next() {
        while (tokenizer == null || !tokenizer.hasMoreTokens()) {
            try {
                tokenizer = new StringTokenizer(reader.readLine());
            } catch (IOException e) {
                throw new RuntimeException(e);
            }
        }
        return tokenizer.nextToken();
    }

    /** Convenience method for reading an {@code int}. */
    int nextInt() {
        return Integer.parseInt(next());
    }
}

/**
 * Core algorithm – everything that works on the grid.
 * All public methods are deliberately small and well documented.
 */
final class Solver {

    // Four orthogonal directions: up, right, down, left
    private static final int[] DR = {-1, 0, 1, 0};
    private static final int[] DC = {0, 1, 0, -1};

    /**
     * Solves the problem for the given {@code InputReader} and writes the
     * answer to the supplied {@code PrintWriter}.
     */
    void solve(InputReader reader, PrintWriter out) {
        final int rows = reader.nextInt();
        final int cols = reader.nextInt();
        final char[][] grid = readGrid(reader, rows, cols);

        // -----------------------------------------------------------------
        // 1️⃣  Identify all connected components of '.' cells.
        // -----------------------------------------------------------------
        final int[][] componentId = new int[rows][cols];
        Arrays.fill(componentId, -1);               // -1 = not visited yet
        final Map<Integer, Integer> componentSize = new HashMap<>();

        int componentIndex = 0;
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '.') {
                    int size = bfsIdentifyComponent(grid, componentId,
                                                    componentIndex, r, c);
                    componentSize.put(componentIndex, size);
                    componentIndex++;
                }
            }
        }

        // -----------------------------------------------------------------
        // 2️⃣  Build the output line by line.
        // -----------------------------------------------------------------
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                char original = grid[r][c];
                if (original == '.') {
                    out.print('.');
                } else {
                    // Gather distinct component ids that touch this cell.
                    Set<Integer> neighbourComponents = new HashSet<>();
                    int sum = 0;
                    for (int d = 0; d < 4; d++) {
                        int nr = r + DR[d];
                        int nc = c + DC[d];
                        if (isInBounds(nr, nc, rows, cols)
                                && (grid[nr][nc] == '.' || grid[nr][nc] == '#')) {

                            int nid = componentId[nr][nc];
                            if (nid != -1 && neighbourComponents.add(nid)) {
                                sum += componentSize.get(nid);
                            }
                        }
                    }
                    out.print((sum + 1) % 10);
                }
            }
            out.println();
        }
        out.flush();
    }

    /** Reads the whole grid from the input stream. */
    private static char[][] readGrid(InputReader reader, int rows, int cols) {
        char[][] grid = new char[rows][cols];
        for (int r = 0; r < rows; r++) {
            String line = reader.next();
            for (int c = 0; c < cols; c++) {
                grid[r][c] = line.charAt(c);
            }
        }
        return grid;
    }

    /**
     * Performs a BFS starting at {@code (startR,startC)}.
     * All reachable '.' cells are marked with {@code componentId}
     * and the method returns the size of the component.
     */
    private int bfsIdentifyComponent(char[][] grid,
                                     int[][] componentId,
                                     int componentId,
                                     int startR,
                                     int startC) {

        final int rows = grid.length;
        final int cols = grid[0].length;

        final ArrayDeque<Point> queue = new ArrayDeque<>();
        queue.addLast(new Point(startR, startC));

        int size = 0;
        while (!queue.isEmpty()) {
            Point p = queue.pollFirst();
            int r = p.row;
            int c = p.col;

            // Skip cells that have already been processed.
            if (grid[r][c] != '.') {
                continue;
            }
            if (componentId[r][c] != -1) {
                continue;
            }

            componentId[r][c] = componentId;
            size++;
            grid[r][c] = '#'; // mark as visited

            // Explore the four neighbours.
            for (int d = 0; d < 4; d++) {
                int nr = r + DR[d];
                int nc = c + DC[d];
                if (isInBounds(nr, nc, rows, cols) && grid[nr][nc] == '.') {
                    queue.addLast(new Point(nr, nc));
                }
            }
        }
        return size;
    }

    /** Helper that checks whether a coordinate lies inside the grid. */
    private static boolean isInBounds(int r, int c, int rows, int cols) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    /** Simple immutable container for a grid coordinate. */
    private static final class Point {
        final int row;
        final int col;

        Point(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }
}

import java.io.*;
import java.util.*;

public class Main {

    /* ---------- configuration ---------- */
    private static final String INPUT_FILE = "";   // leave empty for stdin/stdout

    /* ---------- I/O ---------- */
    private FastScanner in;
    private PrintWriter out;

    /* ---------- problem data ---------- */
    private int rows, cols;
    private String[] grid;
    private boolean[][] visited;
    private int[][] compOriginX, compOriginY;
    private int[][] componentSize;

    /** Four possible movement directions */
    private static final int[] DX = {-1, 1, 0, 0};
    private static final int[] DY = {0, 0, -1, 1};

    /** Main entry point */
    public static void main(String[] args) {
        new Main().run();
    }

    /** Reads input, processes it and writes output */
    private void solve() {
        readInput();
        preprocess();
        writeOutput();
    }

    /** Reads the whole input (file or System.in) */
    private void readInput() {
        if (INPUT_FILE.equals("")) {
            in = new FastScanner(System.in);
            out = new PrintWriter(System.out);
        } else {
            try {
                in = new FastScanner(new FileInputStream(INPUT_FILE + ".in"));
                out = new PrintWriter(new FileOutputStream(INPUT_FILE + ".out"));
            } catch (FileNotFoundException e) {
                throw new IllegalStateException(e);
            }
        }
    }

    /** Pre‑processes the grid: DFS labeling of all '.'‑components */
    private void preprocess() {
        rows = in.nextInt();
        cols = in.nextInt();
        grid = new String[rows];
        for (int i = 0; i < rows; i++) {
            grid[i] = in.next();
        }

        visited = new boolean[rows][cols];
        compOriginX = new int[rows][cols];
        compOriginY = new int[rows][cols];
        componentSize = new int[rows][cols];

        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r].charAt(c) == '*') {
                    continue;
                }
                int size = dfsExplore(r, c);
                componentSize[r][c] = size;
            }
        }
    }

    /** Iterative DFS that labels every cell of the same component */
    private int dfsExplore(int startX, int startY) {
        Deque<int[]> stack = new ArrayDeque<>();
        stack.push(new int[]{startX, startY});
        int count = 0;
        compOriginX[startX][startY] = startX;
        compOriginY[startX][startY] = startY;

        while (!stack.isEmpty()) {
            int[] cur = stack.pop();
            int x = cur[0];
            int y = cur[1];
            if (visited[x][y]) {
                continue;
            }
            visited[x][y] = true;
            count++;

            for (int dir = 0; dir < DX.length; dir++) {
                int nx = x + DX[dir];
                int ny = y + DY[dir];
                if (!inBounds(nx, ny) || grid[nx].charAt(ny) == '*') {
                    continue;
                }
                if (!visited[nx][ny]) {
                    compOriginX[nx][ny] = startX;
                    compOriginY[nx][ny] = startY;
                    stack.push(new int[]{nx, ny});
                }
            }
        }
        return count;
    }

    /** Evaluates a cell: returns component size visible from it or -1 if it is a wall */
    private int evaluateCell(int x, int y) {
        if (grid[x].charAt(y) == '.') {
            return -1;                     // original wall / empty cell
        }
        Set<PairInt> neighborOrigins = new TreeSet<>();
        for (int dir = 0; dir < DX.length; dir++) {
            int nx = x + DX[dir];
            int ny = y + DY[dir];
            neighborOrigins.add(getComponentOrigin(nx, ny));
        }
        int total = 1;
        for (PairInt origin : neighborOrigins) {
            total += componentSize[origin.x][origin.y];
        }
        return total;
    }

    /** Retrieves the stored origin of the component that contains (x,y) */
    private PairInt getComponentOrigin(int x, int y) {
        if (!inBounds(x, y) || grid[x].charAt(y) == '*') {
            return new PairInt(-1, -1);
        }
        return new PairInt(compOriginX[x][y], compOriginY[x][y]);
    }

    /** Simple bounds check */
    private boolean inBounds(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    /** Writes the resulting grid of digits */
    private void writeOutput() {
        for (int r = 0; r < rows; r++) {
            StringBuilder sb = new StringBuilder(cols);
            for (int c = 0; c < cols; c++) {
                int val = evaluateCell(r, c);
                if (val == -1) {
                    sb.append('.');
                } else {
                    sb.append((char) ('0' + (val % 10)));
                }
            }
            out.println(sb.toString());
        }
    }

    /** Fast scanner that works with any InputStream */
    private static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner(InputStream is) {
            br = new BufferedReader(new InputStreamReader(is));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    throw new UncheckedIOException(e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }
    }

    /** Minimal pair class used as a key inside a TreeSet */
    private static final class PairInt implements Comparable<PairInt> {
        final int x;
        final int y;

        PairInt(int x, int y) {
            this.x = x;
            this.y = y;
        }

        @Override
        public int compareTo(PairInt o) {
            int cmp = Integer.compare(this.x, o.x);
            if (cmp != 0) {
                return cmp;
            }
            return Integer.compare(this.y, o.y);
        }

        @Override
        public boolean equals(Object obj) {
            if (this == obj) {
                return true;
            }
            if (obj == null || getClass() != obj.getClass()) {
                return false;
            }
            PairInt other = (PairInt) obj;
            return x == other.x && y == other.y;
        }

        @Override
        public int hashCode() {
            return Objects.hash(x, y);
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Entry point that handles I/O and delegates the actual solving to {@link Solver}.
 */
public class Main {

    public static void main(String[] args) throws IOException {
        // Using try‑with‑resources guarantees proper closing of streams.
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
             PrintWriter pw = new PrintWriter(System.out)) {
            new Solver().solve(br, pw);
        }
    }
}

/**
 * Core logic of the problem.  All mutable state is encapsulated inside this class,
 * making it easier to test and to reuse.
 */
final class Solver {

    /** Directions used for neighbour traversal (up, left, right, down). */
    private enum Direction {
        UP(-1, 0), LEFT(0, -1), RIGHT(0, 1), DOWN(1, 0);
        private final int dr;
        private final int dc;

        Direction(int dr, int dc) {
            this.dr = dr;
            this.dc = dc;
        }

        int[] delta() {
            return new int[]{dr, dc};
        }
    }

    /** The input grid (filled with '.' or '*'). */
    private char[][] grid;
    /** Identifier of the component each '.' cell belongs to (0 = unvisited). */
    private int[][] componentId;
    /** Size of each component, index = component identifier. */
    private int[] componentSize;
    /** Number of distinct components discovered. */
    private int componentCount;

    /** Number of rows and columns of the grid. */
    private int rows, cols;

    /** Resolved output grid (same dimensions as the input). */
    private char[][] output;

    /** Solve the problem using the supplied {@code reader} and {@code out} streams. */
    public void solve(BufferedReader reader, PrintWriter out) throws IOException {
        readInput(reader);
        discoverComponents();
        buildResultGrid();
        printResult(out);
    }

    /** --------------------------------------------------------------------- */
    /** Input parsing                                                    */
    /** --------------------------------------------------------------------- */
    private void readInput(BufferedReader reader) throws IOException {
        String line = reader.readLine();
        StringTokenizer tokenizer = new StringTokenizer(line);
        rows = Integer.parseInt(tokenizer.nextToken());
        cols = Integer.parseInt(tokenizer.nextToken());

        grid = new char[rows][];
        for (int r = 0; r < rows; r++) {
            grid[r] = reader.readLine().toCharArray();
        }
        initAuxiliaryArrays();
    }

    /** Allocate and initialise the data structures that are reused throughout the algorithm. */
    private void initAuxiliaryArrays() {
        componentId = new int[rows][cols];
        // The maximum possible number of components is rows * cols (worst case: isolated cells).
        componentSize = new int[rows * cols + 1]; // index 0 is unused
        output = new char[rows][];
    }

    /** --------------------------------------------------------------------- */
    /** Component discovery (DFS)                                           */
    /** --------------------------------------------------------------------- */
    private void discoverComponents() {
        componentCount = 1; // start identifiers from 1
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '.' && componentId[r][c] == 0) {
                    exploreComponent(r, c, componentCount);
                    componentCount++;
                }
            }
        }
    }

    /** Depth‑first search that marks all cells of one connected component. */
    private void exploreComponent(int startR, int startC, int id) {
        Deque<int[]> stack = new ArrayDeque<>();
        stack.push(new int[]{startR, startC});

        while (!stack.isEmpty()) {
            int[] cur = stack.pop();
            int r = cur[0];
            int c = cur[1];
            if (!isValid(r, c) || grid[r][c] != '.' || componentId[r][c] != 0) {
                continue;
            }
            componentId[r][c] = id;
            componentSize[id]++;

            for (Direction dir : Direction.values()) {
                int nr = r + dir.delta()[0];
                int nc = c + dir.delta()[1];
                if (isValid(nr, nc)) {
                    stack.push(new int[]{nr, nc});
                }
            }
        }
    }

    /** Simple bounds check. */
    private boolean isValid(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    /** --------------------------------------------------------------------- */
    /** Result construction                                                   */
    /** --------------------------------------------------------------------- */
    private void buildResultGrid() {
        output = new char[rows][];
        for (int r = 0; r < rows; r++) {
            output[r] = new char[cols];
            for (int c = 0; c < cols; c++) {
                char cell = grid[r][c];
                if (cell == '.') {
                    output[r][c] = '.';
                } else { // cell == '*'
                    int adjacentComponentSize = aggregatedAdjacentComponentSize(r, c);
                    output[r][c] = Character.forDigit(adjacentComponentSize % 10, 10);
                }
            }
        }
    }

    /** Compute the total size of distinct neighbouring components of '.' cells. */
    private int aggregatedAdjacentComponentSize(int r, int c) {
        Set<Integer> seenIds = new HashSet<>();
        int total = 1; // count the current '*' cell itself

        for (Direction dir : Direction.values()) {
            int nr = r + dir.delta()[0];
            int nc = c + dir.delta()[1];
            if (!isValid(nr, nc) || grid[nr][nc] != '.' || componentId[nr][nc] == 0) {
                continue;
            }
            int compId = componentId[nr][nc];
            if (seenIds.add(compId)) { // add only once per distinct component
                total += componentSize[compId];
            }
        }
        return total;
    }

    /** --------------------------------------------------------------------- */
    /** Output                                                               */
    /** --------------------------------------------------------------------- */
    private void printResult(PrintWriter out) {
        for (char[] row : output) {
            out.println(new String(row));
        }
    }
}

/**
 * Simple tokenizer that works with any {@link InputStream}.  It is deliberately kept
 * small – the problem only needs {@code next()} and {@code nextInt()}.
 */
final class InputReader {

    private final BufferedReader reader;
    private StringTokenizer tokenizer;

    InputReader(InputStream stream) {
        this.reader = new BufferedReader(new InputStreamReader(stream));
    }

    /** Return the next token or attempt to read a new line. */
    private String nextToken() throws IOException {
        while (tokenizer == null || !tokenizer.hasMoreTokens()) {
            tokenizer = new StringTokenizer(reader.readLine());
        }
        return tokenizer.nextToken();
    }

    /** Convenience wrapper around {@link #nextToken()} for integer reading. */
    int nextInt() throws IOException {
        return Integer.parseInt(nextToken());
    }
}

import java.io.*;
import java.util.ArrayDeque;
import java.util.Arrays;
import java.util.Deque;

/**
 * Refactored version of the original program.
 *
 * <p>What the program does:
 *
 * <ul>
 *   <li>Reads a rectangular grid (m × n) of characters. The input is padded with a
 *       surrounding layer of '*'.</li>
 *   <li>All connected components of '.' are labelled and their sizes are stored.</li>
 *   <li>For every position that originally contained '*', the program prints a digit
 *       that equals <code>(1 + sum of sizes of distinct neighbouring components) % 10</code>.
 *       Cells that contain '.' stay '.' in the output.</li>
 * </ul>
 *
 * <p>The implementation has been reorganised for readability and maintainability:
 *
 * <ul>
 *   <li> constants and magic numbers are named;</li>
 *   <li> direction vectors are encapsulated;</li>
 *   <li> input handling uses try‑with‑resources;</li>
 *   <li> the BFS labelling is extracted into its own method;</li>
 *   <li> variable names describe their purpose;</li>
 *   <li> all mutable state is confined to the {@code main} method.</li>
 * </ul>
 */
public class Main {

    /** character used for the surrounding wall */
    private static final char WALL = '*';
    /** character that represents an empty cell */
    private static final char EMPTY = '.';

    /** four orthogonal directions */
    private static final int[][] DIR = {
            { -1, 0 },   // up
            { 1, 0 },    // down
            { 0, -1 },   // left
            { 0, 1 }     // right
    };

    /**
     * Breadth‑first search that labels one component.
     *
     * @param startX   row of the starting cell (1‑based, interior)
     * @param startY   column of the starting cell (1‑based, interior)
     * @param compId   matrix that stores component identifiers
     * @param grid     padded grid containing the whole picture
     * @param compSize array that stores the size of each component (index = component id)
     * @param id       current component identifier
     * @return the size of the component that has just been labelled
     */
    private static int bfsLabelComponent(int startX, int startY,
                                         int[][] compId,
                                         char[][] grid,
                                         int[] compSize,
                                         int id) {
        Deque<int[]> queue = new ArrayDeque<>();
        queue.add(new int[]{startX, startY});
        compId[startX][startY] = id;
        int size = 0;

        while (!queue.isEmpty()) {
            int[] cur = queue.poll();
            int x = cur[0];
            int y = cur[1];
            size++;

            for (int[] d : DIR) {
                int nx = x + d[0];
                int ny = y + d[1];
                if (grid[nx][ny] == EMPTY && compId[nx][ny] == 0) {
                    compId[nx][ny] = id;
                    queue.add(new int[]{nx, ny});
                }
            }
        }
        compSize[id] = size;
        return size;
    }

    public static void main(String[] args) throws IOException {
        /* --------------------------------------------------------------
         * 1. READ INPUT
         * -------------------------------------------------------------- */
        try (BufferedReader reader = new BufferedReader(
                new InputStreamReader(System.in))) {

            String[] header = reader.readLine().split("\\s+");
            int m = Integer.parseInt(header[0]);
            int n = Integer.parseInt(header[1]);

            // padded grid: rows = m + 2, columns = n + 2
            char[][] grid = new char[m + 2][n + 2];
            // top border
            Arrays.fill(grid[0], WALL);
            // bottom border
            Arrays.fill(grid[m + 1], WALL);
            // interior rows
            for (int i = 1; i <= m; i++) {
                String line = reader.readLine();
                // keep the surrounding '*' characters
                grid[i] = ("*" + line + "*").toCharArray();
            }

            /* --------------------------------------------------------------
             * 2. LABEL COMPONENTS OF EMPTY CELLS
             * -------------------------------------------------------------- */
            int maxComponents = m * n + 1;               // enough space for all possible ids
            int[][] compId = new int[m + 2][n + 2];       // 0 means "unvisited"
            int[] compSize = new int[maxComponents + 1];  // index = component id
            int componentCounter = 0;

            for (int i = 1; i <= m; i++) {
                for (int j = 1; j <= n; j++) {
                    if (grid[i][j] == EMPTY && compId[i][j] == 0) {
                        componentCounter++;
                        bfsLabelComponent(i, j, compId, grid, compSize, componentCounter);
                    }
                }
            }

            /* --------------------------------------------------------------
             * 3. BUILD THE RESULT GRID
             * -------------------------------------------------------------- */
            char[][] result = new char[m][n];

            for (int i = 0; i < m; i++) {
                for (int j = 0; j < n; j++) {
                    int gi = i + 1;      // interior row index in the padded grid
                    int gj = j + 1;      // interior column index in the padded grid

                    if (grid[gi][gj] == EMPTY) {
                        result[i][j] = EMPTY;
                        continue;
                    }

                    // collect distinct component identifiers of the four neighbours
                    int[] neighbourIds = new int[5];   // neighbourIds[0] is unused
                    int used = 1;                       // next free slot in neighbourIds
                    for (int[] d : DIR) {
                        int ni = gi + d[0];
                        int nj = gj + d[1];
                        if (ni < 1 || ni >= grid.length || nj < 1 || nj >= grid[0].length) {
                            continue; // outside the padded grid → ignore
                        }
                        int nid = compId[ni][nj];
                        if (nid == 0) {
                            continue; // neighbour is a wall, not part of any component
                        }
                        neighbourIds[used++] = nid;
                    }

                    // sort and collapse duplicates
                    Arrays.sort(neighbourIds, 1, used);
                    int sum = 1; // the constant “1” that the original code adds
                    for (int k = 1; k < used; k++) {
                        if (neighbourIds[k] != neighbourIds[k - 1]) {
                            sum += compSize[neighbourIds[k]];
                        }
                    }
                    result[i][j] = (char) ('0' + (sum % 10));
                }
            }

            /* --------------------------------------------------------------
             * 4. OUTPUT
             * -------------------------------------------------------------- */
            StringBuilder sb = new StringBuilder();
            for (char[] row : result) {
                sb.append(row).append('\n');
            }
            System.out.print(sb.toString());

        } // BufferedReader is closed automatically
    }
}

import java.io.*;
import java.util.*;

public class TheLabyrinth {

    /* -------------------------------------------------------------
     *  Constants & helpers
     * ------------------------------------------------------------- */
    private static final int[][] DIRECTIONS = {
            {-1, 0}, {0, -1}, {1, 0}, {0, 1}      // up, left, down, right
    };

    /** Simple immutable tuple used to store a coordinate pair. */
    private static final class Pair<A, B> {
        final A first;
        final B second;

        private Pair(A first, B second) {
            this.first = first;
            this.second = second;
        }

        static Pair<Integer, Integer> of(int a, int b) {
            return new Pair<>(a, b);
        }
    }

    /** Information about a discovered component. */
    private static final class ComponentInfo {
        final int size;                                 // number of '.' cells in the component
        final List<Pair<Integer, Integer>> boundary;    // adjacent '*' cells (the component boundary)

        ComponentInfo(int size, List<Pair<Integer, Integer>> boundary) {
            this.size = size;
            this.boundary = boundary;
        }
    }

    /* -------------------------------------------------------------
     *  Main entry point
     * ------------------------------------------------------------- */
    public static void main(String[] args) throws IOException {
        try (BufferedReader br = new BufferedReader(
                new InputStreamReader(System.in));
             PrintWriter out = new PrintWriter(System.out)) {

            // ----- read dimensions -------------------------------------------------
            String[] rcs = br.readLine().split("\\s+");
            int rows = Integer.parseInt(rcs[0]);
            int cols = Integer.parseInt(rcs[1]);

            // ----- read grid -------------------------------------------------------
            char[][] grid = new char[rows][cols];
            boolean[][] visited = new boolean[rows][cols];          // tracks visited '.' cells

            for (int i = 0; i < rows; i++) {
                grid[i] = br.readLine().toCharArray();
            }

            // ----- ans[i][j] will hold the required count for wall cells ----------
            int[][] ans = new int[rows][cols];

            // ----- explore every '.' region ---------------------------------------
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (grid[i][j] == '.' && !visited[i][j]) {
                        ComponentInfo info = bfsComponent(grid, visited, i, j);
                        // Add the component size to each adjacent wall cell (mod 10)
                        for (Pair<Integer, Integer> cell : info.boundary) {
                            int br = cell.first;
                            int bc = cell.second;
                            if (grid[br][bc] == '*') {
                                ans[br][bc] = (ans[br][bc] + info.size) % 10;
                            }
                        }
                    }
                }
            }

            // ----- produce output --------------------------------------------------
            for (int i = 0; i < rows; i++) {
                StringBuilder sb = new StringBuilder();
                for (int j = 0; j < cols; j++) {
                    if (grid[i][j] == '*') {
                        sb.append(String.valueOf(ans[i][j]));
                    } else {
                        sb.append('.');
                    }
                }
                out.println(sb);
            }
        }
    }

    /* -------------------------------------------------------------
     *  BFS/DFS over a '.' component
     * ------------------------------------------------------------- */
    /**
     * Explores the connected region of '.' cells starting at (sr, sc).
     *
     * @return a {@link ComponentInfo} containing the region size and all
     *         border cells that are walls ('*').
     */
    private static ComponentInfo bfsComponent(char[][] grid,
                                              boolean[][] visited,
                                              int sr,
                                              int sc) {
        Queue<Pair<Integer, Integer>> queue = new ArrayDeque<>();
        Set<Pair<Integer, Integer>> boundarySet = new HashSet<>();

        queue.add(Pair.of(sr, sc));
        visited[sr][sc] = true;

        int size = 0;

        while (!queue.isEmpty()) {
            Pair<Integer, Integer> cur = queue.poll();
            size++;

            for (int[] dir : DIRECTIONS) {
                int nr = cur.first + dir[0];
                int nc = cur.second + dir[1];

                if (!inBounds(nr, nc, grid.length, grid[0].length)) {
                    continue;
                }

                if (grid[nr][nc] == '.') {
                    if (!visited[nr][nc]) {
                        visited[nr][nc] = true;
                        queue.add(Pair.of(nr, nc));
                    }
                } else if (grid[nr][nc] == '*') {
                    // remember this wall as part of the boundary of the current component
                    boundarySet.add(Pair.of(nr, nc));
                }
            }
        }

        return new ComponentInfo(size, new ArrayList<>(boundarySet));
    }

    /** Utility method to test array bounds. */
    private static boolean inBounds(int r, int c, int rows, int cols) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }
}

import java.io.PrintWriter;
import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;

/**
 * Refactored solution for the “connected‑components + obstacle expansion” problem.
 *
 * <p>The program reads a rectangular grid consisting of '.' (empty) and '#' (obstacle) cells.
 * It first labels every connected empty component with a unique id and stores the size of
 * each component. Then, for every obstacle cell, it counts how many distinct empty
 * components would become adjacent to that cell if the obstacle were removed, adds one
 * for the cell itself and writes the last digit of that total back to the output grid.
 *
 * <p>Refactoring goals:
 * <ul>
 *   <li>Extract domain concepts into clearly named types and methods.</li>
 *   <li>Replace the hand‑rolled scanner with the standard {@link Scanner}.</li>
 *   <li>Eliminate static sprawl – only immutable data is kept in static fields.</li>
 *   <li>Use proper Java collections and language features (e.g. {@code Deque}, {@code charDigit}).</li>
 *   <li>Keep the public entry point small and focused.</li>
 * </ul>
 */
public class Main {

    /** Direction vectors for the four neighbours. */
    private static final int[] DX = {0, 0, 1, -1};
    private static final int[] DY = {1, -1, 0, 0};

    /** The input grid – filled by the caller.</ */
    private static char[][] grid;

    /** Identifier of each connected component of empty cells (0 = not visited). */
    private static int[][] componentId;

    /** Size of each component; index corresponds to componentId‑1. */
    private static List<Integer> componentSizes;

    /** Simple immutable position holder. */
    private static final class Position {
        final int x, y;
        Position(int x, int y) { this.x = x; this.y = y; }
    }

    /** --------------------------------------------------------------------- */
    /** Entry point */
    /** --------------------------------------------------------------------- */
    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in);
             PrintWriter writer = new PrintWriter(System.out)) {

            int rows = scanner.nextInt();
            int cols = scanner.nextInt();
            grid = new char[rows][];
            for (int i = 0; i < rows; i++) {
                grid[i] = scanner.next().toCharArray();
            }

            labelComponents(rows, cols);
            writer.write(buildResult(rows, cols));
        }
    }

    /** --------------------------------------------------------------------- */
    /** Discover all empty components and fill {@code componentId} & {@code componentSizes}. */
    /** --------------------------------------------------------------------- */
    private static void labelComponents(int rows, int cols) {
        componentId = new int[rows][cols];
        componentSizes = new ArrayList<>();

        int currentId = 0;
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == '.' && componentId[i][j] == 0) {
                    int size = exploreComponent(i, j, ++currentId);
                    componentSizes.add(size);
                }
            }
        }
    }

    /** --------------------------------------------------------------------- */
    /** Breadth‑first search that marks all cells of one component with {@code id}. */
    /** --------------------------------------------------------------------- */
    private static int exploreComponent(int startX, int startY, int id) {
        Deque<Position> queue = new ArrayDeque<>();
        queue.add(new Position(startX, startY));
        componentId[startX][startY] = id;
        int size = 1;

        while (!queue.isEmpty()) {
            Position cur = queue.poll();
            for (int d = 0; d < 4; d++) {
                int nx = cur.x + DX[d];
                int ny = cur.y + DY[d];
                if (isInBounds(nx, ny) && grid[nx][ny] == '.' && componentId[nx][ny] == 0) {
                    componentId[nx][ny] = id;
                    size++;
                    queue.add(new Position(nx, ny));
                }
            }
        }
        return size;
    }

    /** --------------------------------------------------------------------- */
    /** Helper – bounds checking */
    /** --------------------------------------------------------------------- */
    private static boolean isInBounds(int x, int y) {
        return x >= 0 && y >= 0 && x < grid.length && y < grid[0].length;
    }

    /** --------------------------------------------------------------------- */
    /** Build the output string according to the problem specification */
    /** --------------------------------------------------------------------- */
    private static String buildResult(int rows, int cols) {
        StringBuilder sb = new StringBuilder(rows * (cols + 1));

        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                char cell = grid[i][j];
                if (cell == '.') {
                    sb.append('.');
                } else {
                    sb.append(computeExpandedDigit(i, j));
                }
            }
            sb.append('\n');
        }
        return sb.toString();
    }

    /** --------------------------------------------------------------------- */
    /** For an obstacle cell, count adjacent distinct components and return the
     *  last digit of (sum_of_sizes + 1). */
    /** --------------------------------------------------------------------- */
    private static char computeExpandedDigit(int i, int j) {
        boolean[] seen = new boolean[componentSizes.size() + 1];
        int sum = 0;

        for (int d = 0; d < 4; d++) {
            int ni = i + DX[d];
            int nj = j + DY[d];
            if (isInBounds(ni, nj)) {
                int cid = componentId[ni][nj];
                if (cid != 0 && !seen[cid]) {
                    seen[cid] = true;
                    sum += componentSizes.get(cid - 1);
                }
            }
        }
        // (sum + 1) % 10 yields a digit 0‑9; Character.forDigit is the idiomatic way.
        return Character.forDigit((sum + 1) % 10, 10);
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

/**
 * Reads a grid of characters, assigns identifiers to empty ('.') cells,
 * then transforms each non‑empty cell based on the frequencies of its
 * neighboring identifiers. The result is printed to standard output.
 *
 * The implementation is deliberately split into small, self‑contained
 * methods and uses only locally scoped mutable state, which makes the
 * logic easier to follow, test and maintain.
 */
public final class Main {

    /** Directions used for neighbour traversal (down, right, up, left). */
    private static final int[][] DIRS = {
            {1, 0}, {0, 1}, {-1, 0}, {0, -1}
    };

    /** Entry point. */
    public static void main(String[] args) throws Exception {
        // Try‑with‑resources guarantees that the reader is closed promptly.
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in))) {
            new Main().solve(br);
        }
    }

    /** Core algorithm – kept in a separate method for readability. */
    private void solve(BufferedReader br) throws IOException {
        // -----------------------------------------------------------------
        // 1️⃣  Parse input
        // -----------------------------------------------------------------
        StringTokenizer st = new StringTokenizer(br.readLine());
        int rows = Integer.parseInt(st.nextToken());
        int cols = Integer.parseInt(st.nextToken());

        char[][] grid = new char[rows][];
        for (int r = 0; r < rows; r++) {
            grid[r] = readNextToken(br).toCharArray();
        }

        // -----------------------------------------------------------------
        // 2️⃣  Assign distinct identifiers to each connected '.' region
        // -----------------------------------------------------------------
        int[][] componentId = new int[rows][cols];
        int nextComponent = 1;

        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '.' && componentId[r][c] == 0) {
                    dfsAssignComponent(grid, componentId, nextComponent++, r, c);
                }
            }
        }

        // -----------------------------------------------------------------
        // 3️⃣  Count how many '.' cells each component occupies
        // -----------------------------------------------------------------
        int[] componentSize = new int[nextComponent + 1];
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '.') {
                    componentSize[componentId[r][c]]++;
                }
            }
        }

        // -----------------------------------------------------------------
        // 4️⃣  Transform every non‑'.' cell based on its neighbours
        // -----------------------------------------------------------------
        StringBuilder output = new StringBuilder(rows * (cols + 1));
        boolean[] used = new boolean[nextComponent + 1];

        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                char cell = grid[r][c];
                if (cell != '.') {
                    // Gather neighbour component ids
                    int[] neighbourIds = new int[4];
                    for (int d = 0; d < 4; d++) {
                        int nr = r + DIRS[d][0];
                        int nc = c + DIRS[d][1];
                        if (inside(nr, nc, rows, cols)) {
                            neighbourIds[d] = componentId[nr][nc];
                        }
                    }

                    // Sum the sizes of *unique* neighbour components
                    int sum = 0;
                    for (int id : neighbourIds) {
                        if (id == 0 || used[id]) {
                            continue;
                        }
                        sum += componentSize[id];
                        used[id] = true;
                    }
                    // Reset flags for the next cell
                    for (int id : neighbourIds) {
                        used[id] = false;
                    }

                    // Take the last digit and replace the character
                    cell = (char) ('0' + (sum % 10));
                    grid[r][c] = cell;
                }
                output.append(cell);
            }
            output.append('\n');
        }

        // -----------------------------------------------------------------
        // 5️⃣  Emit the final grid
        // -----------------------------------------------------------------
        System.out.print(output.toString());
    }

    /** Depth‑first search that labels a connected '.' region with a given id. */
    private void dfsAssignComponent(char[][] grid, int[][] ids, int id, int r, int c) {
        ids[r][c] = id;
        for (int[] d : DIRS) {
            int nr = r + d[0];
            int nc = c + d[1];
            if (outside(nr, nc, grid)) {
                continue;
            }
            if (ids[nr][nc] != 0 || grid[nr][nc] == '*') {
                continue;
            }
            dfsAssignComponent(grid, ids, id, nr, nc);
        }
    }

    /** Utility to read the next whitespace‑separated token from the stream. */
    private String nextToken(BufferedReader br) throws IOException {
        while (true) {
            String line = br.readLine();
            if (line == null) {
                return null;
            }
            StringTokenizer tokenizer = new StringTokenizer(line);
            if (tokenizer.hasMoreTokens()) {
                return tokenizer.nextToken();
            }
        }
    }

    /** Reads the next token as a character array (used for reading a whole line of chars). */
    private char[] readNextToken(BufferedReader br) throws IOException {
        String token = nextToken(br);
        return token == null ? new char[0] : token.toCharArray();
    }

    /** Checks whether a coordinate lies inside the given rectangular bounds. */
    private boolean inside(int r, int c, int rows, int cols) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    /** Returns true if the coordinate is outside the grid or points to a '*' cell. */
    private boolean outside(int r, int c, char[][] grid) {
        return r < 0 || r >= grid.length
                || c < 0 || c >= grid[0].length
                || grid[r][c] == '*'
                || grid[r][c] == '.';
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.PrintWriter;
import java.util.ArrayDeque;
import java.util.Deque;
import java.util.StringTokenizer;

/**
 * Main class that reads a grid, computes how many empty cells can reach each obstacle
 * and prints the result.  Empty cells ('.') stay unchanged, obstacles ('*') become a
 * digit equal to (count+1) % 10 where {@code count} is the size of the connected empty
 * region that can reach the obstacle.
 */
public class C3 {

    /** Direction vectors for up, down, left and right. */
    private static final int[] DX = {-1, 1, 0, 0};
    /** Direction vectors for up, down, left and right. */
    private static final int[] DY = {0, 0, -1, 1};

    /** Holds the input grid. */
    private char[][] grid;
    /** Holds the temporary counting matrix. */
    private int[][] result;
    /** Visited flag matrix used during BFS. */
    private boolean[][] visited;

    /** Queue used for BFS – re‑used for every component. */
    private final Deque<Pos> queue = new ArrayDeque<>();

    /** Counter for the size of the current empty component. */
    private int componentSize;

    /** Marker for cells that belong to the temporary BFS frontier (adjacent '*'). */
    private final boolean[][] inFrontier;

    /** Reads the whole input and returns a 2‑D array of characters. */
    private static char[][] readGrid(BufferedReader br, int rows, int cols) throws IOException {
        char[][] g = new char[rows][cols];
        for (int r = 0; r < rows; r++) {
            String line = br.readLine();
            if (line == null) {
                throw new IOException("Unexpected end of input");
            }
            Arrays.fill(g[r], ' ');
            for (int c = 0; c < cols; c++) {
                g[r][c] = line.charAt(c);
            }
        }
        return g;
    }

    /** Simple immutable pair representing a cell position. */
    private static final class Pos {
        final int x, y;

        Pos(int x, int y) {
            this.x = x;
            this.y = y;
        }

        /** Returns a neighbour at the given direction offsets. */
        Pos neighbour(int dx, int dy) {
            return new Pos(x + dx, y + dy);
        }
    }

    /**
     * Breadth‑first search that explores a connected empty region.
     *
     * @param startX row index of the starting cell
     * @param startY column index of the starting cell
     * @return cells that are reachable obstacles ('*') belonging to this component
     */
    private Deque<Pos> bfsEmptyComponent(int startX, int startY) {
        componentSize = 0;
        queue.clear();
        queue.add(new Pos(startX, startY));
        visited[startX][startY] = true;

        Deque<Pos> frontier = new ArrayDeque<>();

        while (!queue.isEmpty()) {
            Pos p = queue.poll();
            int x = p.x;
            int y = p.y;
            componentSize++;

            // Check all four neighbours
            for (int dir = 0; dir < 4; dir++) {
                int nx = x + DX[dir];
                int ny = y + DY[dir];
                if (!inBounds(nx, ny) || visited[nx][ny]) {
                    continue;
                }
                visited[nx][ny] = true;
                char ch = grid[nx][ny];
                if (ch == '*') {
                    // Record obstacle cells that can be reached from this empty component
                    frontier.add(new Pos(nx, ny));
                } else if (ch == '.') {
                    queue.add(new Pos(nx, ny));
                }
            }
        }
        return frontier;
    }

    /** Checks if a coordinate lies inside the grid. */
    private boolean inBounds(int x, int y) {
        return x >= 0 && x < grid.length && y >= 0 && y < grid[0].length;
    }

    /** Increments the counter for every obstacle cell belonging to the supplied frontier. */
    private void registerFrontier(Deque<Pos> frontier) {
        while (!frontier.isEmpty()) {
            Pos p = frontier.pollFirst();
            int x = p.x;
            int y = p.y;
            // Each obstacle gets counted once per component
            result[x][y] += componentSize;
            visited[x][y] = false; // allow it to be processed by later components
        }
    }

    /** Formats the output according to the specification. */
    private String buildResultString() {
        StringBuilder sb = new StringBuilder();
        for (int r = 0; r < grid.length; r++) {
            for (int c = 0; c < grid[0].length; c++) {
                char cell = grid[r][c];
                if (cell == '.') {
                    sb.append('.');
                } else { // '*'
                    int digit = (result[r][c] + 1) % 10;
                    sb.append(digit);
                }
            }
            sb.append('\n');
        }
        return sb.toString();
    }

    /** --------------------------------------------------------------- */
    /** Entry point – parses input, runs the algorithm and prints the result. */
    public static void main(String[] args) throws IOException {
        // ----- read dimensions and grid -------------------------------------------------
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in))) {
            StringTokenizer st = new StringTokenizer(br.readLine());
            int rows = Integer.parseInt(st.nextToken());
            int cols = Integer.parseInt(st.nextToken());

            char[][] grid = readGrid(br, rows, cols);

            // ----- initialise auxiliary data structures -----------------------------------
            int[][] result = new int[rows][cols];
            boolean[][] visited = new boolean[rows][cols];
            boolean[][] inFrontier = new boolean[rows][cols]; // not used directly, kept for API compatibility

            // ----- process each empty component -------------------------------------------
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (!visited[r][c] && grid[r][c] == '.') {
                        // Only an instance method can reuse the shared fields, so we delegate:
                        C3 solver = new C3();
                        solver.grid = grid;
                        solver.result = result;
                        solver.visited = visited;
                        solver.inFrontier = inFrontier; // not strictly needed, kept for completeness
                        solver.queue.clear();

                        // bfsEmptyComponent returns the obstacle cells reachable from this component
                        Deque<Pos> reachableObstacles = solver.bfsEmptyComponent(r, c);
                        solver.registerFrontier(reachableObstacles);
                    }
                }
            }

            // ----- build and print the final board ---------------------------------------
            PrintWriter out = new PrintWriter(System.out);
            out.print(solver.buildResultString());
            out.flush();
            out.close();
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.PrintWriter;
import java.util.Random;

/**
 * Reads a grid containing '.' (empty), '*' (blocked) and optionally other symbols,
 * discovers all connected empty regions, and for every blocked cell writes the
 * sum of the sizes of the adjacent empty regions (mod 10). The result is printed
 * as a grid where blocked cells are replaced by that digit and empty cells stay
 * as '.'.
 *
 * The program is deliberately written with a clean, object‑oriented structure,
 * avoiding the use of many scattered static mutable fields.
 */
public class GridProcessor {

    /** Directions for 4‑neighbourhood traversal */
    private static final int[] DX = {1, -1, 0, 0};
    private static final int[] DY = {0, 0, -1, 1};

    /** Symbols used in the input */
    private static final char EMPTY = '.';
    private static final char BLOCKED = '*';

    private final int rows;
    private final int cols;
    private final char[][] grid;          // original input grid
    private final int[][] componentSize;   // size of each discovered component
    private final int[][] starSum;         // accumulated sizes for blocked cells
    private final boolean[][] visited;     // visited flag for DFS
    private int componentId;                // current component identifier

    /**
     * Constructs the processor by reading the grid from the supplied reader.
     *
     * @param reader a {@link BufferedReader} that provides the input
     * @throws IOException if an I/O error occurs
     */
    public GridProcessor(BufferedReader reader) throws IOException {
        String[] firstLine = reader.readLine().split("\\s+");
        rows = Integer.parseInt(firstLine[0]);
        cols = Integer.parseInt(firstLine[1]);

        grid = new char[rows][cols];
        starSum = new int[rows][cols];
        visited = new boolean[rows][cols];

        for (int i = 0; i < rows; i++) {
            grid[i] = reader.readLine().toCharArray();
        }
        componentSize = new int[rows][cols];
    }

    /** Starts the whole processing pipeline and returns the output string. */
    public String process() {
        componentId = 1; // start identifiers from 1

        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == EMPTY && !visited[i][j]) {
                    int size = discoverComponent(i, j);
                    propagateComponentSize(i, j, size);
                }
            }
        }

        StringBuilder out = new StringBuilder();
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == BLOCKED) {
                    out.append((starSum[i][j] % 10));
                } else {
                    out.append(EMPTY);
                }
            }
            out.append('\n');
        }
        return out.toString();
    }

    /**
     * Performs a depth‑first search starting at {@code (i, j)} to determine the
     * size of the connected empty region. While exploring, cells are marked as
     * visited and stored in {@link #componentSize} (the same cell is used as
     * a representative for later reference).
     *
     * @param startI row index of the start cell
     * @param startJ column index of the start cell
     * @return the number of cells in the component
     */
    private int discoverComponent(int startI, int startJ) {
        int size = 0;

        dfsExplore(startI, startJ, (x, y) -> {
            visited[x][y] = true;
            size++;
        });

        // Store the size at a representative cell (any cell of the component)
        componentSize[startI][startJ] = size;
        return size;
    }

    /**
     * Propagates the previously discovered component size to all blocked cells
     * that are directly adjacent to any cell of the component.
     *
     * @param rootI row index of the component's root cell
     * @param rootJ column index of the component's root cell
     * @param componentSize size of the component (already computed)
     */
    private void propagateComponentSize(int rootI, int rootJ, int componentSize) {
        dfsPropagate(rootI, rootJ, () -> {
            // Explore neighbours of the current cell
            for (int dir = 0; dir < 4; dir++) {
                int ni = rootI + DX[dir];
                int nj = rootJ + DY[dir];
                if (isInBounds(ni, nj) && grid[ni][nj] == BLOCKED && !visited[ni][nj]) {
                    visited[ni][nj] = true; // mark to avoid double‑counting
                    starSum[ni][nj] += componentSize;
                }
            }
        });
    }

    /** Simple DFS helper that executes {@code action} on every reachable cell. */
    private void dfsExplore(int i, int j, java.util.function.BiConsumer<Integer, Integer> action) {
        // Use recursion with an explicit stack to avoid deep recursion limits.
        // The recursion style matches the original algorithm but isolates side‑effects.
        dfsVisit(i, j, action);
        for (int k = 0; k < 4; k++) {
            int ni = i + DX[k];
            int nj = j + DY[k];
            if (isInBounds(ni, nj) && grid[ni][nj] == EMPTY && !visited[ni][nj]) {
                dfsVisit(ni, nj, action);
            }
        }
    }

    /** Recursive helper that marks the cell as visited and executes {@code action}. */
    private void dfsVisit(int i, int j, java.util.function.BiConsumer<Integer, Integer> action) {
        visited[i][j] = true;
        action.accept(i, j);
    }

    /** DFS used during the propagation phase. */
    private void dfsPropagate(int i, int j, java.util.function.BiConsumer<Integer, Integer> action) {
        // The original code used a marker (currDfs) to avoid revisiting the same
        // component while propagating. We achieve the same effect with the global
        // visited flag: after a component is processed we mark all its cells as
        // visited, preventing later propagation from touching them again.
        // Here we simply explore neighbours that are blocked.
        for (int k = 0; k < 4; k++) {
            int ni = i + DX[k];
            int nj = j + DY[k];
            if (isInBounds(ni, nj) && grid[ni][nj] == BLOCKED) {
                action.accept(ni, nj);
            }
        }
    }

    /** Checks whether the given coordinates lie inside the grid. */
    private boolean isInBounds(int i, int j) {
        return i >= 0 && i < rows && j >= 0 && j < cols;
    }

    /** Entry point – mirrors the original `main` signature but uses try‑with‑resources. */
    public static void main(String[] args) throws Exception {
        // Using try‑with‑resources guarantees the reader is closed promptly.
        try (BufferedReader br = new BufferedReader(new java.io.InputStreamReader(System.in));
             PrintWriter out = new PrintWriter(System.out)) {

            GridProcessor processor = new GridProcessor(br);
            String result = processor.process();
            out.print(result);
        }
    }
}

/*  --------------------------------------------------------------
 *   Competitive‑programming style entry point
 *  --------------------------------------------------------------
 *  The original program performed:
 *   1. Connected‑component identification on a '.'‑grid.
 *   2. For each '*' cell it summed the sizes of the adjacent
 *      components (mod 10) and printed the resulting digit.
 *  The refactor splits the logic into small, well‑named methods,
 *  uses a stack‑based DFS (to avoid recursion depth limits),
 *  and isolates input/output handling.
 *  --------------------------------------------------------------
 */
import java.io.*;
import java.util.*;

public class Main {

    /* ---------- constants & static state ---------- */
    private static final char EMPTY = '.';          // walkable cell
    private static final char BLOCK = '*';          // explosive cell

    private static int rows, cols;                  // board dimensions
    private static char[][] board;                  // raw input
    private static int[][] componentId;             // component number for each empty cell
    private static int[] componentSize;             // size of each component (1‑based index)
    private static boolean[][] visited;             // visited flag for DFS
    private static final int[][] DIRECTIONS =
            {{0, 1}, {0, -1}, {1, 0}, {-1, 0}};      // 4‑neighbourhood offsets

    /* ---------- entry point ---------- */
    public static void main(String[] args) throws IOException {
        // Input is read via a tiny wrapper that mimics the original Scanner
        try (Scanner scanner = new Scanner(System.in)) {
            readBoard(scanner);
            analyseComponents();
            printResult(scanner);
        }
    }

    /* ---------- input handling ---------- */
    private static void readBoard(Scanner sc) {
        rows = sc.nextInt();
        cols = sc.nextInt();
        board = new char[rows][];

        for (int r = 0; r < rows; ++r) {
            board[r] = sc.next().toCharArray();
        }
    }

    /* ---------- component discovery ---------- */
    private static void analyseComponents() {
        componentId = new int[rows][cols];
        componentSize = new int[rows * cols + 1];   // over‑allocate, 1‑based indexing
        visited = new boolean[rows][cols];

        List<Integer> componentSizes = new ArrayList<>();
        componentSizes.add(0);                       // dummy entry to keep 1‑based indexing
        int nextComponentId = 1;

        for (int r = 0; r < rows; ++r) {
            for (int c = 0; c < cols; ++c) {
                if (!visited[r][c] && isEmpty(r, c)) {
                    int size = exploreComponent(r, c, nextComponentId);
                    visited[r][c] = true;
                    componentSize[nextComponentId] = size;
                    componentSizes.add(size);
                    ++nextComponentId;
                }
            }
        }

        // Resize the size array to the exact number of discovered components
        int[] trimmed = new int[nextComponentId];
        System.arraycopy(componentSize, 0, trimmed, 0, nextComponentId);
        componentSize = trimmed;
    }

    /** Depth‑first search (stack based) that labels a component and returns its size. */
    private static int exploreComponent(int startR, int startC, int componentIdx) {
        Deque<int[]> stack = new ArrayDeque<>();
        stack.push(new int[]{startR, startC});
        visited[startR][startC] = true;
        componentId[startR][startC] = componentIdx;

        int count = 0;
        while (!stack.isEmpty()) {
            int[] cell = stack.pop();
            ++count;

            for (int[] dir : DIRECTIONS) {
                int nr = cell[0] + dir[0];
                int nc = cell[1] + dir[1];
                if (isInBounds(nr, nc) && !visited[nr][nc] && isEmpty(nr, nc)) {
                    visited[nr][nc] = true;
                    componentId[nr][nc] = componentIdx;
                    stack.push(new int[]{nr, nc});
                }
            }
        }
        return count;
    }

    /* ---------- explosion calculation ---------- */
    /** Returns the modulo‑10 result of exploding a '*' cell. */
    private static int explosionValue(int r, int c) {
        Set<Integer> neighbourComponents = new HashSet<>();

        for (int[] dir : DIRECTIONS) {
            int nr = r + dir[0];
            int nc = c + dir[1];
            if (isInBounds(nr, nc) && isEmpty(nr, nc)) {
                neighbourComponents.add(componentId[nr][nc]);
            }
        }

        int total = 1; // the cell itself
        for (int compId : neighbourComponents) {
            total += componentSize[compId];
        }
        return total % 10;
    }

    /* ---------- output generation ---------- */
    private static void printResult(Scanner scanner) {
        StringBuilder out = new StringBuilder();

        for (int r = 0; r < rows; ++r) {
            for (int c = 0; c < cols; ++c) {
                if (board[r][c] == EMPTY) {
                    out.append('.');
                } else {
                    out.append(explosionValue(r, c));
                }
            }
            out.append('\n');
        }

        System.out.print(out.toString());
    }

    /* ---------- auxiliary helpers ---------- */
    private static boolean isEmpty(int r, int c) {
        return board[r][c] == EMPTY;
    }

    private static boolean isInBounds(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    /* ---------- tiny Scanner façade (mirrors original) ---------- */
    private static class Scanner {
        private final BufferedReader br;
        private StringTokenizer st;

        Scanner(InputStream source) throws IOException {
            br = new BufferedReader(new InputStreamReader(source));
        }

        String next() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                st = new StringTokenizer(br.readLine());
            }
            return st.nextToken();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Refactored Labyrinth solution.
 *
 * <p>Reads a rectangular grid of '.' (free) and '#' (wall) cells.
 * Adjacent free cells are unioned into components.
 * For each wall cell the program prints a digit that represents the
 * size (mod 10) of the component that would be formed if the wall were
 * turned into a free cell, plus one, also taken modulo 10.
 *
 * <p>Changes made for readability and maintainability:
 * <ul>
 *   <li>Extracted direction vectors as constants.</li>
 *   <li>Replaced the ad‑hoc pair class with simple row/col calculations.</li>
 *   <li>Implemented a clean Union‑Find (Disjoint Set) class.</li>
 *   <li>Used generically‑named helper methods instead of cryptic arithmetic.</li>
 *   <li>Moved all I/O handling into a try‑with‑resources block.</li>
 *   <li>Added JavaDoc comments and descriptive method names.</li>
 *   <li>Removed duplicated code and magic numbers.</li>
 * </ul>
 */
public class Labyrinth {

    /* --------------------------------------------------------------------- */
    /*                         Configuration constants                     */
    /* --------------------------------------------------------------------- */
    /** Up, down, left, right */
    private static final int[] DR = { -1, 1, 0, 0 };
    private static final int[] DC = { 0, 0, -1, 1 };

    /**
     * Computes a linear index for a cell: {@code row * cols + col}.
     */
    private static int linearIndex(int row, int col, int cols) {
        return row * cols + col;
    }

    /** Bounds checking helper. */
    private static boolean inBounds(int r, int c, int rows, int cols) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    /* --------------------------------------------------------------------- */
    /*                           Union‑Find implementation                  */
    /* --------------------------------------------------------------------- */
    /**
     * Simple Disjoint‑Set (Union‑Find) data structure.
     *
     * <p>Each cell is identified by its linear index {@code row*cols+col}.
     * The structure stores parent pointers and component sizes.
     */
    private static class UnionFind {
        private final int[] parent; // negative value = root, magnitude = size
        private final int[] size;    // only valid for roots (kept for compatibility)

        UnionFind(int cells) {
            parent = new int[cells];
            size = new int[cells];
            Arrays.fill(parent, -1);
            Arrays.fill(size, 1);
        }

        /** Finds the root of {@code x} with path compression. */
        int find(int x) {
            if (parent[x] < 0) return x;
            return parent[x] = find(parent[x]);
        }

        /** Unites the sets containing {@code a} and {@code b}. */
        void union(int a, int b) {
            int ra = find(a);
            int rb = find(b);
            if (ra == rb) return;

            // ensure ra is the smaller tree
            if (size[ra] > size[rb]) {
                int tmp = ra; ra = rb; rb = tmp;
            }
            parent[ra] = rb;
            size[rb] += size[ra];
        }

        /** Returns the size of the component that contains {@code x}. */
        int getSize(int x) {
            return size[find(x)];
        }
    }

    /* --------------------------------------------------------------------- */
    /*                               Main entry point                        */
    /* --------------------------------------------------------------------- */
    public static void main(String[] args) throws IOException {
        /* ---------- Input ---------- */
        try (BufferedReader br = new BufferedReader(
                new InputStreamReader(System.in))) {

            // first line: rows and columns
            String[] header = br.readLine().trim().split("\\s+");
            int rows = Integer.parseInt(header[0]);
            int cols = Integer.parseInt(header[1]);

            char[][] grid = new char[rows][];
            for (int i = 0; i < rows; i++) {
                grid[i] = br.readLine().toCharArray();
            }

            /* ---------- Build Union‑Find for '.' cells ---------- */
            int totalCells = rows * cols;
            UnionFind uf = new UnionFind(totalCells);

            // Connect adjacent free cells (only down & right to avoid double work)
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (grid[r][c] != '.') continue;

                    // down neighbor
                    if (r + 1 < rows && grid[r + 1][c] == '.') {
                        uf.union(linearIndex(r, c, cols),
                                linearIndex(r + 1, c, cols));
                    }
                    // right neighbor
                    if (c + 1 < cols && grid[r][c + 1] == '.') {
                        uf.union(linearIndex(r, c, cols),
                                linearIndex(r, c + 1, cols));
                    }
                }
            }

            /* ---------- Produce Output ---------- */
            StringBuilder out = new StringBuilder();
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (grid[r][c] == '.') {
                        out.append('.');
                    } else {
                        out.append(connectComponent(grid, uf, r, c, rows, cols));
                    }
                }
                out.append('\n');
            }
            System.out.print(out);
        }
    }

    /**
     * Computes the digit to print for a wall cell {@code (r,c)}.
     *
     * <p>The value is the sum of the modulo‑10 sizes of distinct neighboring
     * free components, plus one, finally reduced modulo 10.
     */
    private static int connectComponent(char[][] grid, UnionFind uf,
                                          int r, int c, int rows, int cols) {
        boolean[] seenRoot = new boolean[grid.length * grid[0].length];
        int total = 0;

        for (int d = 0; d < 4; d++) {
            int nr = r + DR[d];
            int nc = c + DC[d];
            if (!inBounds(nr, nc, rows, cols) || grid[nr][nc] != '.') continue;

            int rootIdx = uf.find(linearIndex(nr, nc, cols));
            if (!seenRoot[rootIdx]) {
                seenRoot[rootIdx] = true;
                total += uf.getSize(rootIdx) % 10;
            }
        }
        return (total + 1) % 10;
    }
}

import java.io.*;
import java.util.*;

/**
 * Refactored solution that counts the size of each connected component of '.' cells
 * and, for every non‑'.' cell, prints the sum of the sizes of the neighboring
 * components modulo 10.
 *
 * The implementation is deliberately kept simple and self‑contained:
 *   • exploration is performed with a straightforward DFS,
 *   • component identifiers and sizes are stored in dedicated arrays,
 *   • neighbour groups are collected in a {@link Set} to avoid double‑counting.
 */
public class Main {

    /** Directions: down, up, right, left */
    private static final int[][] DIR = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};

    /** Grid read from input */
    private static char[][] grid;

    /** groupId[row][col] – identifier of the component the cell belongs to (0 = not processed) */
    private static int[][] groupId;

    /** componentSize[id] – size of the component with identifier {@code id} (1‑based) */
    private static int[] componentSize;

    /** Fast scanner that wraps a {@link BufferedReader} */
    private static final class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner(InputStream is) {
            br = new BufferedReader(new InputStreamReader(is));
        }

        /** Returns the next token, reading a new line when the current token is exhausted */
        private String nextToken() throws IOException {
            while (st == null || !st.hasMoreElements()) {
                String line = br.readLine();
                if (line == null) return null;
                st = new StringTokenizer(line);
            }
            return st.nextToken();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(nextToken());
        }

        String next() throws IOException {
            return nextToken();
        }
    }

    /** Depth‑first search that labels all '.' cells of one component and returns its size */
    private static int exploreComponent(int r, int c, int componentId) {
        groupId[r][c] = componentId;
        int size = 1;

        for (int[] d : DIR) {
            int nr = r + d[0];
            int nc = c + d[1];
            if (isInside(nr, nc) && grid[nr][nc] == '.' && groupId[nr][nc] == 0) {
                size += exploreComponent(nr, nc, componentId);
            }
        }
        return size;
    }

    /** Helper that checks whether a cell coordinate is within the grid bounds */
    private static boolean isInside(int r, int c) {
        return r >= 0 && r < grid.length && c >= 0 && c < grid[0].length;
    }

    public static void main(String[] args) throws IOException {
        FastScanner fs = new FastScanner(System.in);

        int n = fs.nextInt();                 // number of rows
        int m = fs.nextInt();                 // number of columns
        grid = new char[n][m];

        // -----------------------------------------------------------------
        // Read the whole grid as strings and copy characters into the 2‑D array
        // -----------------------------------------------------------------
        for (int i = 0; i < n; i++) {
            String line = fs.next();
            System.arraycopy(line.toCharArray(), 0, grid[i], 0, m);
        }

        int rows = grid.length;
        int cols = grid[0].length;

        // -----------------------------------------------------------------
        // Initialise data structures
        // -----------------------------------------------------------------
        groupId = new int[rows][cols];
        // Maximum possible number of components is rows * cols, so allocate +1 for 1‑based indexing
        componentSize = new int[rows * cols + 1];
        int currentComponentId = 1;

        // -----------------------------------------------------------------
        // Identify every '.' component, store its identifier and size
        // -----------------------------------------------------------------
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == '.' && groupId[i][j] == 0) {
                    int componentSizeValue = exploreComponent(i, j, currentComponentId);
                    componentSize[currentComponentId] = componentSizeValue;
                    currentComponentId++;
                }
            }
        }

        // -----------------------------------------------------------------
        // Build the output: '.' stays '.', every other cell gets the digit
        // representing (sum of neighboring component sizes) % 10
        // -----------------------------------------------------------------
        StringBuilder output = new StringBuilder();
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == '.') {
                    output.append('.');
                } else {
                    Set<Integer> neighbourComponentIds = new HashSet<>();

                    for (int[] d : DIR) {
                        int nr = i + d[0];
                        int nc = j + d[1];
                        if (isInside(nr, nc) && grid[nr][nc] == '.' && groupId[nr][nc] != 0) {
                            neighbourComponentIds.add(groupId[nr][nc]);
                        }
                    }

                    int totalSize = 0;
                    for (int id : neighbourComponentIds) {
                        totalSize += componentSize[id];
                    }
                    output.append((char) ('0' + (totalSize % 10)));
                }
            }
            output.append('\n');
        }

        System.out.print(output.toString());
    }
}

