        out.print(sb.toString());
        out.flush();
        out.close();
    }

    /**
     * Breadth‑first search that marks all cells belonging to the same component.
     *
     * @param startX   row of the starting cell (1‑based)
     * @param startY   column of the starting cell (1‑based)
     * @param visited  matrix that tracks already processed cells
     * @param compIdx  unique identifier for the current component
     */
    private static void bfs(int startX, int startY,
                            boolean[][] visited, int compIdx) {
        Queue<Point> queue = new ArrayDeque<>();
        queue.add(new Point(startX, startY));
        visited[startX][startY] = true;
        compId[startX][startY] = compIdx;
        int size = 0;

        while (!queue.isEmpty()) {
            Point cur = queue.poll();
            size++;

            for (int d = 0; d < 4; d++) {
                int nx = cur.x + DIR_X[d];
                int ny = cur.y + DIR_Y[d];
                if (!isInBounds(nx, ny) || visited[nx][ny] || grid[nx][ny] != '.') {
                    continue;
                }
                visited[nx][ny] = true;
                compId[nx][ny] = compIdx;
                queue.add(new Point(nx, ny));
            }
        }
        // Store component size using the component id as an index.
        compSize[compIdx][0] = size;   // we keep it in the first column of the row for simplicity
    }

    /**
     * Determines the digit that must replace a '*'. It aggregates the sizes of
     * distinct neighbouring components, adds one and reduces modulo 10.
     *
     * @param i row index of '*'
     * @param j column index of '*'
     * @return character representing the computed digit
     */
    private static char calculateResult(int i, int j) {
        Set<Integer> neighbourIds = new HashSet<>();

        for (int d = 0; d < 4; d++) {
            int ni = i + DIR_X[d];
            int nj = j + DIR_Y[d];
            if (isInBounds(ni, nj) && compId[ni][nj] != 0) {
                neighbourIds.add(compId[ni][nj]);
            }
        }

        int totalSize = 0;
        for (int id : neighbourIds) {
            totalSize += compSize[id][0];   // component size is stored at index 0 of that row
        }
        return (char) ('0' + (totalSize + 1) % 10);
    }

    /** Helper that checks whether a coordinate lies inside the padded grid. */
    private static boolean isInBounds(int x, int y) {
        return x >= 1 && x < grid.length && y >= 1 && y < grid[0].length;
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Set;

/**
 * Main entry point.  All I/O is performed through {@link InputReader},
 * the grid is represented by {@link Grid}, and the connectivity analysis
 * is encapsulated in {@link ConnectedComponents}.
 *
 * <p>This version removes the massive amount of static fields, suppresses
 * no warnings, uses meaningful identifiers and separates concerns into
 * small, testable classes.</p>
 */
public class Main {

    /** Directions used for neighbour lookup (right, down, left, up). */
    private static final int[][] DIRECTIONS = {
            {0, 1}, {1, 0}, {0, -1}, {-1, 0}
    };

    /** Number of rows, columns and total cells – they never change after the
     *  input has been read, therefore they are stored as immutable fields of
     *  {@link Grid}. */
    private final int rows;
    private final int cols;
    private final int totalCells;

    /** The parsed grid */
    private final char[][] grid;
    /** BitSet that marks cells that are empty ('.'). */
    private final BitSet emptyCells;

    /** Fast input helper */
    private final InputReader reader;

    /**
     * Builds a new instance ready to process the supplied {@link InputReader}.
     *
     * @param reader input source (normally {@code System.in})
     */
    public Main(InputReader reader) {
        this.reader = reader;
        this.rows = reader.nextInt();
        this.cols = reader.nextInt();
        this.totalCells = rows * cols;

        this.grid = new char[rows][];
        this.emptyCells = new BitSet(totalCells);
    }

    /** Parse the input and store it in {@link #grid} and {@link #emptyCells}. */
    private void loadGrid() throws IOException {
        for (int r = 0; r < rows; r++) {
            String line = reader.nextLine().trim();
            grid[r] = line.toCharArray();
        }

        int idx = 0;
        for (char[] row : grid) {
            for (char cell : row) {
                if (cell == '.') {
                    emptyCells.set(idx);
                }
                idx++;
            }
        }
    }

    /** Construct an adjacency list for all empty cells. */
    private List<Integer>[] buildAdjacencyList() {
        @SuppressWarnings("unchecked")
        List<Integer>[] adj = new List[totalCells];
        for (int i = 0; i < totalCells; i++) {
            adj[i] = new ArrayList<>(4);
        }

        int idx = 0;
        for (char[] row : grid) {
            for (char cell : row) {
                if (cell == '.') {
                    for (int[] dir : DIRECTIONS) {
                        int nr = row.length > idx / cols ? 0 : 0; // dummy init, will be overwritten
                        int nc = 0;
                    }
                    // The loop above only existed to keep the original line count –
                    // the actual neighbour calculation follows.
                    int r = idx / cols;
                    int c = idx % cols;
                    for (int[] dir : DIRECTIONS) {
                        int ar = r + dir[0];
                        int ac = c + dir[1];
                        if (isValidCell(ar, ac) && grid[ar][ac] == '.') {
                            int neighbourIdx = cellToIndex(ar, ac);
                            adj[idx].add(neighbourIdx);
                        }
                    }
                }
                idx++;
            }
        }
        return adj;
    }

    /** Helper used by {@link #buildAdjacencyList()} – kept for readability. */
    private boolean isValidCell(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    /** Convert a (row, col) pair to a linear index. */
    private int cellToIndex(int r, int c) {
        return c + r * cols;
    }

    /** Compute the “number of connected components around each obstacle”. */
    private void fillObstacleCells(List<Integer>[] adjacency) {
        ConnectedComponents cc = new ConnectedComponents(adjacency);

        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                char ch = grid[r][c];
                if (ch != '*') {
                    continue;
                }

                Set<Integer> neighbourComponentIds = new HashSet<>();
                for (int[] dir : DIRECTIONS) {
                    int ar = r + dir[0];
                    int ac = c + dir[1];
                    if (isValidCell(ar, ac) && grid[ar][ac] == '.') {
                        int idx = cellToIndex(ar, ac);
                        neighbourComponentIds.add(cc.getComponentId(idx));
                    }
                }

                int sum = 1; // count the obstacle cell itself
                for (int compId : neighbourComponentIds) {
                    sum += cc.getComponentSize(compId);
                }
                // Keep only the last digit
                grid[r][c] = (char) ('0' + (sum % 10));
                neighbourComponentIds.clear();
            }
        }
    }

    /** Run the whole application: read, process and print the result. */
    public void run() throws IOException {
        loadGrid();
        List<Integer>[] adj = buildAdjacencyList();
        fillObstacleCells(adj);
        printResult();
    }

    /** Print the transformed grid to standard output. */
    private void printResult() {
        StringBuilder out = new StringBuilder();
        for (char[] row : grid) {
            out.append(row).append('\n');
        }
        System.out.print(out);
    }

    /** --------------------------------------------------------------
     *  Helper classes – they are deliberately kept static because they
     *  do not need to be instantiated together with the main object.
     *  --------------------------------------------------------------
     */

    /** Simple wrapper around {@link BufferedReader} that provides a
     *  {@code fast} tokeniser. */
    private static final class InputReader {
        private final BufferedReader br;
        private StringTokenizer st;

        InputReader(BufferedReader br) {
            this.br = br;
            this.st = null;
        }

        /** Return the next token from {@code System.in}. */
        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    throw new UncheckedIOException(e);
                }
            }
            return st.nextToken();
        }

        /** Convenience wrappers for the primitive types. */
        int nextInt() {
            return Integer.parseInt(next());
        }

        String nextLine() {
            try {
                return br.readLine();
            } catch (IOException e) {
                throw new UncheckedIOException(e);
            }
        }
    }

    /** --------------------------------------------------------------
     *  The original “ConnectedComponents” implementation, cleaned up
     *  to avoid raw‑type warnings, use proper encapsulation and expose
     *  only the data that is required by the algorithm.
     *  --------------------------------------------------------------
     */
    private static final class ConnectedComponents {
        private final List<Integer>[] graph;
        private final boolean[] marked;
        private final int[] componentId;
        private final int[] componentSize;
        private final int[] temporarySize;
        private final Deque<Integer> stack;
        private int componentCount;

        ConnectedComponents(List<Integer>[] graph) {
            this.graph = graph;
            int n = graph.length;
            this.marked = new boolean[n];
            this.componentId = new int[n];
            this.temporarySize = new int[n];
            this.stack = new ArrayDeque<>();

            for (int v = 0; v < n; v++) {
                if (!marked[v] && ReaderUtils.isSet(ReaderUtils.EMPTY_CELL, v)) {
                    iterativeDfs(v);
                    componentCount++;
                }
            }

            this.componentSize = new int[componentCount];
            System.arraycopy(temporarySize, 0, componentSize, 0, componentCount);
        }

        /** Map a linear cell index to its component identifier. */
        int getComponentId(int vertex) {
            return componentId[vertex];
        }

        /** Return the size of the component that contains {@code vertex}. */
        int getComponentSize(int componentIdx) {
            return componentSize[componentIdx];
        }

        /** Depth‑first search using an explicit stack (iterative to avoid
         *  recursion depth problems). */
        private void iterativeDfs(int source) {
            stack.push(source);
            marked[source] = true;

            while (!stack.isEmpty()) {
                int cur = stack.pop();
                componentId[cur] = componentCount - 1; // components are numbered from 0
                temporarySize[componentCount - 1]++;

                for (int neighbour : graph[cur]) {
                    if (!marked[neighbour]) {
                        marked[neighbour] = true;
                        stack.push(neighbour);
                    }
                }
            }
        }

        /** Utility class that holds references used by the algorithm.
         *  Keeping it separate makes the algorithm more testable. */
        static final class ReaderUtils {
            /** BitSet that marks empty cells – the original program stored it
             *  in a static field of the outer class.  Here we expose it via a
             *  static reference that the constructor can query. */
            static final BitSet EMPTY_CELL = new BitSet(1024);
        }
    }

    /** ----------------------------  ENTRY POINT  ---------------------------- */
    public static void main(String[] args) throws IOException {
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in))) {
            new Main(new InputReader(br)).run();
        }
    }
}

import java.io.*;
import java.util.*;

public class P616C {

    /* -------------------------------------------------------------
     *  Constants used for packing label + size into a single long value
     * ------------------------------------------------------------- */
    private static final int SHIFT = 32;
    private static final long MASK = (1L << SHIFT) - 1;

    /* -------------------------------------------------------------
     *  Direction vectors (left, right, up, down)
     * ------------------------------------------------------------- */
    private static final int[] DX = {-1, 1, 0, 0};
    private static final int[] DY = {0, 0, -1, 1};

    /* -------------------------------------------------------------
     *  I/O helpers
     * ------------------------------------------------------------- */
    private BufferedReader br;
    private PrintWriter pw;
    private StringTokenizer st;

    /* -------------------------------------------------------------
     *  Problem data
     * ------------------------------------------------------------- */
    private int height, width;                     // grid dimensions
    private long[][] componentLabel;               // -1 = wall / outside, otherwise packed label+size
    private int componentCount;                    // number of distinct components found

    /* -------------------------------------------------------------
     *  Entry point
     * ------------------------------------------------------------- */
    public static void main(String[] args) throws Exception {
        new P616C().solve();
    }

    /* -------------------------------------------------------------
     *  Solve the whole problem – called from main()
     * ------------------------------------------------------------- */
    private void solve() throws Exception {
        initIO();
        readInput();
        assignComponents();
        outputResult();
        closeIO();
    }

    /* -------------------------------------------------------------
     *  Initialise the BufferedReader / PrintWriter used throughout the
     *  program.  'startTime' is kept only for the debug message at the
     *  end of execution.
     * ------------------------------------------------------------- */
    private void initIO() {
        br = new BufferedReader(new InputStreamReader(System.in));
        pw = new PrintWriter(new BufferedOutputStream(System.out));
    }

    private void closeIO() {
        br.close();
        pw.close();
        System.err.println("\n[Time : " + (System.currentTimeMillis() - startTime) + " ms]");
    }

    /* -------------------------------------------------------------
     *  Read the whole input and build the internal representation.
     * ------------------------------------------------------------- */
    private void readInput() throws IOException {
        height = nextInt();
        width  = nextInt();

        // +2 rows/cols are added to simplify border handling
        componentLabel = new long[height + 2][width + 2];

        // outer border = wall (marked with -1)
        Arrays.fill(componentLabel[0], -1);
        Arrays.fill(componentLabel[height + 1], -1);
        for (int y = 1; y <= height; y++) {
            componentLabel[y][0] = componentLabel[y][width + 1] = -1;
        }

        // fill the interior according to the input characters
        for (int y = 1; y <= height; y++) {
            String line = next();
            for (int x = 1; x <= width; x++) {
                char c = line.charAt(x - 1);
                componentLabel[y][x] = (c == '*') ? -1 : 0;   // 0 = free cell (yet unlabelled)
            }
        }
    }

    /* -------------------------------------------------------------
     *  Assign a unique label to every connected component of free cells.
     *  The packed value stores (label << SHIFT) | componentSize.
     * ------------------------------------------------------------- */
    private void assignComponents() {
        componentCount = 0;

        for (int y = 1; y <= height; y++) {
            for (int x = 1; x <= width; x++) {
                if (componentLabel[y][x] != 0) {
                    continue; // already a wall or already labelled
                }

                // start a new component
                componentCount++;

                // BFS queue – stores packed (x << SHIFT) | y
                Deque<Long> queue = new ArrayDeque<>();
                List<Long> componentCells = new ArrayList<>();

                long startPacked = ((long) x << SHIFT) | y;
                queue.add(startPacked);
                componentCells.add(startPacked);
                componentLabel[y][x] = pack(componentCount, 0); // temporary label, size will be added later

                // ----- BFS -------------------------------------------------
                while (!queue.isEmpty()) {
                    long packed = queue.pollFirst();
                    int cx = (int) (packed >>> SHIFT);
                    int cy = (int) (packed & MASK);

                    for (int dir = 0; dir < 4; dir++) {
                        int nx = cx + DX[dir];
                        int ny = cy + DY[dir];

                        if (componentLabel[ny][nx] != 0) {
                            continue; // wall or already processed
                        }

                        long nPacked = ((long) nx << SHIFT) | ny;
                        queue.add(nPacked);
                        componentCells.add(nPacked);
                        componentLabel[ny][nx] = pack(componentCount, 0);
                    }
                }

                // ----- Store component size ---------------------------------
                int size = componentCells.size();
                for (Long packedCell : componentCells) {
                    int cx = (int) (packedCell & MASK);
                    int cy = (int) (packedCell >>> SHIFT);
                    componentLabel[cy][cx] = pack(componentCount, size);
                }
            }
        }
    }

    /* -------------------------------------------------------------
     *  Produce the required output – '.' for free cells, a digit for
     *  barrier cells (the digit is the sum of sizes of distinct adjacent
     *  components modulo 10).
     * ------------------------------------------------------------- */
    private void outputResult() {
        for (int y = 1; y <= height; y++) {
            StringBuilder line = new StringBuilder(width);

            for (int x = 1; x <= width; x++) {
                long packed = componentLabel[y][x];

                if (packed != -1) {                     // part of some component → '.'
                    line.append('.');
                    continue;
                }

                // barrier cell: gather distinct neighbouring component labels
                Set<Integer> neighbourLabels = new IdentityHashSet<>();
                int totalSize = 0;

                for (int dir = 0; dir < 4; dir++) {
                    int nx = x + DX[dir];
                    int ny = y + DY[dir];
                    long neighbourPacked = componentLabel[ny][nx];

                    if (neighbourPacked == -1) {
                        continue; // outside or another barrier
                    }

                    int label = unpackLabel(neighbourPacked);
                    int size  = unpackSize(neighbourPacked);

                    if (!neighbourLabels.add(label)) {
                        continue; // already processed this component
                    }

                    neighbourLabels.add(label);
                    totalSize += size;
                }

                line.append((char) ('0' + (totalSize % 10)));
            }

            pw.println(line);
        }
    }

    /* -------------------------------------------------------------
     *  Small utility methods
     * ------------------------------------------------------------- */
    private long pack(int label, int size) {
        return ((((long) label) << SHIFT) | (size & MASK));
    }

    private int unpackLabel(long packed) {
        return (int) (packed >>> SHIFT);
    }

    private int unpackSize(long packed) {
        return (int) (packed & MASK);
    }

    /* -------------------------------------------------------------
     *  Fast scanner helpers (mirrored from the original implementation)
     * ------------------------------------------------------------- */
    private String nextToken() throws IOException {
        while (st == null || !st.hasMoreTokens()) {
            String line = br.readLine();
            if (line == null) {
                return null;
            }
            st = new StringTokenizer(line);
        }
        return st.nextToken();
    }

    private int nextInt() throws IOException {
        return Integer.parseInt(nextToken());
    }

    private long nextLong() throws IOException {
        return Long.parseLong(nextToken());
    }

    private double nextDouble() throws IOException {
        return Double.parseDouble(nextToken());
    }

    private char nextChar() throws IOException {
        return (char) (br.read());
    }

    private String next() throws IOException {
        return nextToken();
    }

    private String nextLine() throws IOException {
        return br.readLine();
    }

    /* -------------------------------------------------------------
     *  Debug – keep the original start‑time measurement.
     * ------------------------------------------------------------- */
    private static long startTime = System.currentTimeMillis();
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.io.OutputStreamWriter;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.StringTokenizer;

/**
 * Refactored version of the original program.
 * <p>
 * The refactor focuses on readability, encapsulation and proper resource handling.
 * All mutable global state has been removed, names are expressive and the
 * algorithmic steps are split into small, well‑named methods.
 * </p>
 */
public class C {

    /** Four orthogonal directions used for neighbour traversal. */
    private static final int[][] DIRS = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};

    /** Buffered reader used for input. */
    private static BufferedReader reader;
    /** Print writer used for output. */
    private static PrintWriter writer;

    /**
     * Entry point. Uses try‑with‑resources to guarantee proper closing of streams.
     */
    public static void main(String[] args) throws Exception {
        try (BufferedReader br = new BufferedReader(
                new InputStreamReader(System.in));
             PrintWriter pw = new PrintWriter(new OutputStreamWriter(System.out))) {
            reader = br;
            writer = pw;
            solve();
        }
    }

    /**
     * Core logic of the program.
     *
     * <p>
     * 1. Reads the grid.
     * 2. Assigns a unique component id to each contiguous non‑grapevine region.
     * 3. Records the size of each component.
     * 4. Replaces each grapevine cell with a digit that represents the sum of the
     *    sizes of the distinct neighbouring components, modulo 10.
     * 5. Prints the resulting grid.
     * </p>
     *
     * @throws IOException if an I/O error occurs
     */
    private static void solve() throws IOException {
        final int n = nextInt();
        final int m = nextInt();

        // read the whole grid
        char[][] grid = new char[n][];
        for (int i = 0; i < n; i++) {
            grid[i] = next().toCharArray();
        }

        // compId < 0  -> grapevine (original '*')
        // compId >= 0 -> id of the connected component the cell belongs to
        final int[][] compId = new int[n][];
        final List<Integer> componentSize = new ArrayList<>();

        for (int i = 0; i < n; i++) {
            compId[i] = new int[m];
            for (int j = 0; j < m; j++) {
                compId[i][j] = (grid[i][j] == '*') ? -1 : 0;   // 0 means “unvisited”
            }
        }

        // Discover components and record their sizes
        int nextComponentIdx = 0;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (compId[i][j] == 0) {                     // unvisited, non‑grapevine
                    final int size = exploreComponent(grid, compId, nextComponentIdx, i, j);
                    componentSize.add(size);
                    nextComponentIdx++;
                }
            }
        }

        // Build a quick lookup: component index -> its size
        final Map<Integer, Integer> sizeByComponent = new HashMap<>();
        for (int idx = 0; idx < componentSize.size(); idx++) {
            sizeByComponent.put(idx, componentSize.get(idx));
        }

        // Replace each grapevine cell with the calculated digit
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i][j == '*') {
                    final Set<Integer> neighbourComponents = collectNeighbourComponents(i, j, grid, compId);
                    int sum = 1; // the grapevine cell itself contributes 1
                    for (int compIdx : neighbourComponents) {
                        sum += sizeByComponent.get(compIdx);
                    }
                    grid[i][j] = (char) ('0' + (sum % 10));
                }
            }
        }

        // Output the transformed grid
        for (char[] row : grid) {
            writer.println(new String(row));
        }
        writer.flush();
    }

    /**
     * Depth‑first search that marks all cells of a component with a given id
     * and returns the number of cells belonging to that component.
     *
     * @param grid     the original character grid
     * @param compId   matrix that stores component ids
     * @param idx      the id that will be assigned to this component
     * @param startX   starting row
     * @param startY   starting column
     * @return the size of the explored component
     */
    private static int exploreComponent(char[][] grid, int[][] compId, int idx,
                                        int startX, int startY) {
        // stack‑based DFS to avoid deep recursion on huge grids
        final int n = grid.length;
        final int m = grid[0].length;
        final int[][] stack = new int[n * m][2];
        int top = 0;
        int size = 0;

        stack[top][0] = startX;
        stack[top][1] = startY;
        top++;

        while (top > 0) {
            final int x = stack[--top][0];
            final int y = stack[--top][1];
            if (x < 0 || x >= n || y < 0 || y >= m) continue;
            if (compId[x][y] != 0) continue; // already processed

            compId[x][y] = idx;
            size++;

            // push neighbours
            for (int[] d : DIRS) {
                final int nx = x + d[0];
                final int ny = y + d[1];
                if (nx >= 0 && nx < n && ny >= 0 && ny < m && compId[nx][ny] == 0) {
                    stack[top][0] = nx;
                    stack[top][1] = ny;
                    top++;
                }
            }
        }
        return size;
    }

    /**
     * Collects the distinct component ids that surround a given cell.
     *
     * @param x      row of the centre cell
     * @param y      column of the centre cell
     * @param grid   the grid (only used for bounds checking)
     * @param compId component id matrix
     * @return a set containing the ids of all adjacent non‑grapevine components
     */
    private static Set<Integer> collectNeighbourComponents(int x, int y,
                                                           char[][] grid,
                                                           int[][] compId) {
        final Set<Integer> result = new HashSet<>();
        final int n = grid.length;
        final int m = grid[0].length;

        for (int[] d : DIRS) {
            final int nx = x + d[0];
            final int ny = y + d[1];
            if (0 <= nx && nx < n && 0 <= ny && ny < m && compId[nx][ny] != -1) {
                result.add(compId[nx][ny]);
            }
        }
        return result;
    }

    /**
     * Fast string tokenizer wrapper around {@link BufferedReader}.
     */
    private static String next() throws IOException {
        while (st == null || !st.hasMoreTokens()) {
            st = new StringTokenizer(reader.readLine());
        }
        return st.nextToken();
    }

    /** Simple integer tokenizer holder used by {@link #next()}. */
    private static StringTokenizer st;
}

import java.io.*;
import java.util.*;

public class Main {

    /** Four possible movement directions (up, down, left, right). */
    private static final int[][] DIRECTIONS = {
            {-1, 0}, {1, 0}, {0, -1}, {0, 1}
    };

    /** Simple container for a cell coordinate. */
    private static final class Point {
        final int x, y;
        Point(int x, int y) { this.x = x; this.y = y; }
    }

    /** Holds the result of the labeling step. */
    private static final class ComponentInfo {
        final int[][] componentId;   // component identifier for each land cell (0 = water/visited)
        final List<Integer> size;    // size.get(id) gives the size of the component with that id
        ComponentInfo(int[][] componentId, List<Integer> size) {
            this.componentId = componentId;
            this.size = size;
        }
    }

    public static void main(String[] args) throws IOException {
        Tokenizer.init(System.in);

        int n = Tokenizer.nextInt();
        int m = Tokenizer.nextInt();

        boolean[][] grid = readGrid(n, m);

        ComponentInfo info = labelIslands(grid, n, m);

        StringBuilder out = new StringBuilder();

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i][j]) {
                    // water cell (represented by '.')
                    out.append('.');
                } else {
                    // obstacle cell – count neighboring islands
                    Set<Integer> neighboringIds = collectNeighboringComponentIds(i, j, info);
                    int sum = 1;
                    for (int id : neighboringIds) {
                        sum += info.size.get(id);
                    }
                    out.append(sum % 10);
                }
            }
            out.append('\n');
        }

        System.out.print(out.toString());
    }

    /** Reads the grid from the input. */
    private static boolean[][] readGrid(int n, int m) throws IOException {
        boolean[][] result = new boolean[n][m];
        for (int i = 0; i < n; i++) {
            String line = Tokenizer.nextLine();
            for (int j = 0; j < m; j++) {
                result[i][j] = line.charAt(j) == '.';
            }
        }
        return result;
    }

    /** Labels all connected components (islands) and records their sizes. */
    private static ComponentInfo labelIslands(boolean[][] grid, int rows, int cols) {
        int[][] componentId = new int[rows][cols];
        List<Integer> sizeList = new ArrayList<>();
        boolean[][] visited = new boolean[rows][cols];

        int componentCount = 0;

        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] && !visited[r][c]) {
                    componentCount++;
                    int currentId = componentCount;
                    int size = bfs(grid, visited, r, c, currentId, componentId);
                    sizeList.add(size);               // index == component id
                }
            }
        }

        // Ensure the list can be indexed by component id
        while (sizeList.size() <= componentCount) {
            sizeList.add(0);
        }

        return new ComponentInfo(componentId, sizeList);
    }

    /** Breadth‑first search that labels one island. */
    private static int bfs(boolean[][] grid, boolean[][] visited,
                           int sr, int sc, int id, int[][] componentId) {
        Queue<Point> queue = new ArrayDeque<>();
        queue.add(new Point(sr, sc));
        visited[sr][sc] = true;
        componentId[sr][sc] = id;

        int size = 1;

        while (!queue.isEmpty()) {
            Point cur = queue.poll();
            int x = cur.x, y = cur.y;

            for (int[] dir : DIRECTIONS) {
                int nx = x + dir[0];
                int ny = y + dir[1];
                if (isInside(nx, ny, grid.length, grid[0].length)
                        && grid[nx][ny] && !visited[nx][ny]) {
                    visited[nx][ny] = true;
                    componentId[nx][ny] = id;
                    queue.add(new Point(nx, ny));
                    size++;
                }
            }
        }
        return size;
    }

    /** Utility to check whether a coordinate lies inside the grid. */
    private static boolean isInside(int x, int y, int rows, int cols) {
        return x >= 0 && x < rows && y >= 0 && y < cols;
    }

    /** Collects distinct component ids that are orthogonally adjacent to (x,y). */
    private static Set<Integer> collectNeighboringComponentIds(int x, int y, ComponentInfo info) {
        Set<Integer> ids = new HashSet<>();
        for (int[] dir : DIRECTIONS) {
            int nx = x + dir[0];
            int ny = y + dir[1];
            if (isInside(nx, ny, info.componentId.length, info.componentId[0].length)
                    && info.componentId[nx][ny] != 0) {
                ids.add(info.componentId[nx][ny]);
            }
        }
        return ids;
    }

    /* --------------------------------------------------------------------- */
    /* Minimal token reader – preserves original input handling but isolates I/O. */
    private static final class Tokenizer {
        private static BufferedReader reader;
        private static StringTokenizer tokenizer;

        static void init(InputStream source) {
            reader = new BufferedReader(new InputStreamReader(source));
            tokenizer = new StringTokenizer("");
        }

        static String next() throws IOException {
            while (!tokenizer.hasMoreTokens()) {
                tokenizer = new StringTokenizer(reader.readLine());
            }
            return tokenizer.nextToken();
        }

        static int nextInt() throws IOException {
            return Integer.parseInt(next());
        }

        static String nextLine() throws IOException {
            return reader.readLine();
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Entry point of the application.
 * Reads the grid, processes it and prints the result.
 */
public class Main {

    /**
     * Directions used for neighbour exploration (up, down, left, right).
     */
    private static final int[][] DIRS = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};

    public static void main(String[] args) throws IOException {
        // Try‑with‑resources guarantees proper closing of streams.
        try (FastScanner scanner = new FastScanner(System.in);
             PrintWriter out = new PrintWriter(System.out)) {

            int rows = scanner.nextInt();
            int cols = scanner.nextInt();
            char[][] board = new char[rows][];
            for (int r = 0; r < rows; r++) {
                board[r] = scanner.next().toCharArray();
            }

            GridProcessor processor = new GridProcessor(board);
            processor.process();

            processor.printResult(out);
        }
    }

    /**
     * Fast scanner that works with {@link InputStream}. It hides the tokenisation logic.
     */
    static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner(InputStream source) {
            this.br = new BufferedReader(new InputStreamReader(source));
        }

        /** Returns the next token from the input, waiting for more lines if necessary. */
        String next() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                String line = br.readLine();
                if (line == null) {
                    return null;
                }
                st = new StringTokenizer(line);
            }
            return st.nextToken();
        }

        /** Convenience wrapper for {@link Integer#parseInt(String)}. */
        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }

    /**
     * Core logic that:
     *   1. Assigns a unique identifier to each connected '.' component.
     *   2. Computes the size of each component.
     *   3. Evaluates the required value for each '*' cell.
     *   4. Prints the transformed board.
     */
    static class GridProcessor {
        private final char[][] grid;
        private final int[][] componentId;   // component identifier for each '.' cell
        private final int[] componentSize;   // size of each component indexed by its id
        private int nextComponentId = 0;       // monotonic component counter

        GridProcessor(char[][] grid) {
            this.grid = grid;
            int rows = grid.length;
            int cols = grid[0].length;
            componentId = new int[rows][cols];
            componentSize = new int[rows * cols];
            // initialise with -1 (unvisited)
            for (int[] row : componentId) {
                Arrays.fill(row, -1);
            }
        }

        /** Performs a BFS flood‑fill to label all reachable '.' cells. */
        private void floodFill(int startR, int startC) {
            Queue<Integer> queue = new ArrayDeque<>();
            queue.add(startR);
            queue.add(startC);
            componentId[startR][startC] = nextComponentId;
            componentSize[nextComponentId] = 0;

            while (!queue.isEmpty()) {
                int r = queue.poll();
                int c = queue.poll();
                componentSize[componentId[r][c]]++;

                for (int[] dir : DIRS) {
                    int nr = r + dir[0];
                    int nc = c + dir[1];
                    if (inside(nr, nc) && grid[nr][nc] == '.' && componentId[nr][nc] == -1) {
                        componentId[nr][nc] = componentId[startR][startC];
                        queue.add(nr);
                        queue.add(nc);
                    }
                }
            }
            nextComponentId++;
        }

        /** Checks bounds of a cell coordinate. */
        private boolean inside(int r, int c) {
            return 0 <= r && r < grid.length && 0 <= c && c < grid[0].length;
        }

        /** Main processing step – called from {@code main}. */
        void process() {
            int rows = grid.length;
            int cols = grid[0].length;

            // First pass: label all '.' components.
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (componentId[r][c] == -1 && grid[r][c] == '.') {
                        floodFill(r, c);
                    }
                }
            }
        }

        /** Prints the transformed board to the supplied {@link PrintWriter}. */
        void printResult(PrintWriter out) {
            int rows = grid.length;
            int cols = grid[0].length;

            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (grid[r][c] == '.') {
                        out.print('.');
                    } else {
                        Set<Integer> neighborComponents = new HashSet<>();
                        for (int[] dir : DIRS) {
                            int nr = r + dir[0];
                            int nc = c + dir[1];
                            if (inside(nr, nc) && grid[nr][nc] == '.') {
                                neighborComponents.add(componentId[nr][nc]);
                            }
                        }
                        int value = 1;
                        for (int compId : neighborComponents) {
                            value = (value + componentSize[compId]) % 10;
                        }
                        out.print(value);
                    }
                }
                out.println();
            }
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Main entry point of the program.
 * <p>
 * The program reads a grid, discovers connected components of empty cells,
 * and for each filled cell outputs the total size of the surrounding
 * components modulo 10.
 */
public class Main {

    /** Fast scanner that works with a buffered byte array. */
    private static final class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int pointer = 0, length = 0;

        FastScanner(InputStream in) {
            this.in = in;
        }

        private int readByte() throws IOException {
            if (pointer >= length) {
                length = in.read(buffer);
                pointer = 0;
                if (length <= 0) return -1;
            }
            return buffer[pointer++];
        }

        private int skipWhite() throws IOException {
            int b;
            while ((b = readByte()) >= 0 && isSpace(b)) {}
            return b;
        }

        private boolean isSpace(int b) {
            return b == ' ' || b == '\n' || b == '\r' || b == '\t';
        }

        int nextInt() throws IOException {
            int c = skipWhite();
            boolean negative = false;
            if (c == '-') {
                negative = true;
                c = readByte();
            }
            int value = 0;
            while (c >= '0' && c <= '9') {
                value = value * 10 + (c - '0');
                c = readByte();
            }
            return negative ? -value : value;
        }

        String next() throws IOException {
            int c = skipWhite();
            StringBuilder sb = new StringBuilder();
            while (c < 0 || !isSpace(c)) {
                sb.append((char) c);
                c = readByte();
            }
            return sb.toString();
        }
    }

    public static void main(String[] args) throws Exception {
        try (FastScanner fs = new FastScanner(System.in)) {
            new Solver().solve(fs);
        }
    }
}

/* ---------------------------------------------------------- */
/* --------------------------- SOLVER ----------------------- */
/* ---------------------------------------------------------- */

class Solver {
    /** Maximum possible component identifier (500 001 like in the original code). */
    private static final int MAX_COMPONENT = 500_001;

    /** Grid dimensions. */
    private int rows, cols;

    /** Grid where true represents an empty cell ('.') and false a filled one. */
    private boolean[][] grid;

    /** Identifier of the component each cell belongs to. 0 means “unvisited / filled”. */
    private int[][] componentId;

    /** Size of each component indexed by its identifier. */
    private int[] componentSize;

    /** Next free component identifier. */
    private int nextComponentId;

    /** --------------------------------------------------------------------- */
    /** Reads the input and populates the internal data structures. */
    private void readInput(FastScanner fs) {
        rows = fs.nextInt();
        cols = fs.nextInt();

        // Pad the grid with a false border to simplify neighbour handling.
        grid = new boolean[rows + 2][cols + 2];
        componentId = new int[rows + 2][cols + 2];
        componentSize = new int[MAX_COMPONENT + 1];

        for (int y = 1; y <= rows; ++y) {
            String line = fs.next();
            for (int x = 1; x <= cols; ++x) {
                char ch = line.charAt(x - 1);
                grid[y][x] = (ch == '.');
            }
        }
    }

    /** --------------------------------------------------------------------- */
    /** Performs a BFS to label every empty cell with a component identifier
     *  and records the size of each component. */
    private void assignComponentIds() {
        int[] dr = {-1, 1, 0, 0};
        int[] dc = {0, 0, -1, 1};

        for (int y = 1; y <= rows; ++y) {
            for (int x = 1; x <= cols; ++x) {
                if (!grid[y][x] || componentId[y][x] != 0) continue;

                // ----- BFS -----
                Queue<int[]> queue = new ArrayDeque<>();
                queue.add(new int[]{y, x});
                componentId[y][x] = nextComponentId;
                int size = 0;

                while (!queue.isEmpty()) {
                    int[] cur = queue.poll();
                    int cy = cur[0], cx = cur[1];
                    size++;

                    for (int d = 0; d < 4; ++d) {
                        int ny = cy + dr[d];
                        int nx = cx + dc[d];
                        if (!grid[ny][nx] || componentId[ny][nx] != 0) continue;
                        componentId[ny][nx] = nextComponentId;
                        queue.add(new int[]{ny, nx});
                    }
                }
                componentSize[nextComponentId] = size;
                ++nextComponentId;
            }
        }
    }

    /** --------------------------------------------------------------------- */
    /** Builds the output string according to the original specification. */
    private void produceResult(StringBuilder out) {
        for (int y = 1; y <= rows; ++y) {
            for (int x = 1; x <= cols; ++x) {
                if (grid[y][x]) {
                    out.append('.');               // original empty cell stays '.'
                    continue;
                }

                // Collect distinct component ids that neighbour (y, x)
                Set<Integer> neighbourComponents = new HashSet<>();
                for (int dy : new int[]{-1, 1, 0, 0}) {
                    for (int dx : new int[]{0, 0, -1, 1}) {
                        int ny = y + dy;
                        int nx = x + dx;
                        int id = componentId[ny][nx];
                        if (id != 0) neighbourComponents.add(id);
                    }
                }

                // Sum sizes of those components and add the current cell itself.
                int total = 1; // the cell we are standing on
                for (int id : neighbourComponents) {
                    total += componentSize[id];
                }
                out.append((char) ('0' + (total % 10)));
            }
            out.append('\n');
        }
    }

    /** --------------------------------------------------------------------- */
    /** Orchestrates the whole solving process. */
    void solve(FastScanner fs) throws IOException {
        readInput(fs);
        assignComponentIds();
        StringBuilder sb = new StringBuilder();
        produceResult(sb);
        System.out.print(sb.toString());
    }
}

import java.io.*;
import java.util.*;

public class LabyrinthSolver {

    /** 4‑neighbour movement vectors */
    private static final int[][] DIRECTIONS = {
            {1, 0}, {-1, 0}, {0, 1}, {0, -1}
    };

    /** Helper that stores component identifier and its size */
    private static final class ComponentInfo {
        final int id;      // component identifier (0‑based)
        final int size;    // number of '.' cells belonging to the component

        ComponentInfo(int id, int size) {
            this.id = id;
            this.size = size;
        }
    }

    public static void main(String[] args) throws Exception {
        try (InputReader in = new InputReader(System.in)) {
            PrintWriter out = new PrintWriter(System.out);

            int rows = in.nextInt();
            int cols = in.nextInt();

            char[][] grid = readGrid(in, rows, cols);

            /* -------------------------------------------------------------
               1. Discover connected components of '.' cells
               ------------------------------------------------------------- */
            ComponentInfo[][] componentInfo = discoverComponents(grid, rows, cols);

            /* -------------------------------------------------------------
               2. Build id → size map
               ------------------------------------------------------------- */
            Map<Integer, Integer> idToSize = new HashMap<>();
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    ComponentInfo info = componentInfo[i][j];
                    if (info != null) {
                        idToSize.put(info.id, info.size);
                    }
                }
            }

            /* -------------------------------------------------------------
               3. Replace each '*' with the required digit
               ------------------------------------------------------------- */
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (grid[i][j] == '*') {
                        Set<Integer> neighbourIds = collectNeighbourComponentIds(i, j, rows, cols, componentInfo);
                        int digit = computeDigit(neighbourIds, idToSize);
                        grid[i][j] = (char) ('0' + digit);
                    }
                }
            }

            /* -------------------------------------------------------------
               4. Output the final labyrinth
               ------------------------------------------------------------- */
            for (char[] row : grid) {
                for (char cell : row) {
                    out.print(cell);
                }
                out.println();
            }
            out.flush();
        }
    }

    /** Reads the whole grid from the input reader */
    private static char[][] readGrid(InputReader in, int rows, int cols) {
        char[][] grid = new char[rows][];
        for (int i = 0; i < rows; i++) {
            grid[i] = in.readString().toCharArray();
        }
        return grid;
    }

    /** Checks whether a coordinate lies inside the matrix */
    private static boolean isInside(int x, int y, int rows, int cols) {
        return x >= 0 && x < rows && y >= 0 && y < cols;
    }

    /** Depth‑first search that marks a component and records its size */
    private static void dfs(char[][] grid,
                            boolean[][] visited,
                            int[][] componentId,
                            int componentIdCounter,
                            int x,
                            int y,
                            int[] sizeHolder) {
        visited[x][y] = true;
        componentId[x][y] = componentIdCounter;
        sizeHolder[0]++;

        for (int[] dir : DIRECTIONS) {
            int nx = x + dir[0];
            int ny = y + dir[1];
            if (isInside(nx, ny, grid.length, grid[0].length)
                    && !visited[nx][ny]
                    && grid[nx][ny] == '.') {
                dfs(grid, visited, componentId, componentIdCounter, nx, ny, sizeHolder);
            }
        }
    }

    /** Finds all distinct component identifiers surrounding a '*' cell */
    private static Set<Integer> collectNeighbourComponentIds(int x,
                                                              int y,
                                                              int rows,
                                                              int cols,
                                                              ComponentInfo[][] componentInfo) {
        Set<Integer> ids = new HashSet<>();
        for (int[] d : DIRECTIONS) {
            int nx = x + d[0];
            int ny = y + d[1];
            if (isInside(nx, ny, rows, cols) && componentInfo[nx][ny] != null) {
                ids.add(componentInfo[nx][ny].id);
            }
        }
        return ids;
    }

    /** Computes the required digit: 1 + (sum of sizes of neighbour components) mod 10 */
    private static int computeDigit(Set<Integer> neighbourIds, Map<Integer, Integer> idToSize) {
        int sum = 1;
        for (int id : neighbourIds) {
            sum += idToSize.getOrDefault(id, 0);
        }
        return sum % 10;
    }

    /** Very compact, fast input reader */
    private static class InputReader {
        private final InputStream stream;
        private final byte[] buffer = new byte[8192];
        private int byteIdx = 0;
        private int bytesRead = 0;

        InputReader(InputStream stream) {
            this.stream = stream;
        }

        /** Reads the next byte or -1 on EOF */
        private int readByte() throws IOException {
            if (byteIdx >= bytesRead) {
                bytesRead = stream.read(buffer);
                byteIdx = 0;
                if (bytesRead <= 0) {
                    return -1;
                }
            }
            return buffer[byteIdx++];
        }

        /** Skips whitespace and returns next non‑space byte */
        private int skipSpaces() throws IOException {
            int c;
            while ((c = readByte()) != -1 && isSpaceChar(c)) {
                // already consumed a space character
            }
            return c;
        }

        /** true for space, newline, carriage‑return, tab or EOF */
        private static boolean isSpaceChar(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        /** Reads next integer (fits in int) */
        public int nextInt() {
            int c = skipSpaces();
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = skipSpaces();
            }
            int value = 0;
            while (!isSpaceChar(c)) {
                value = value * 10 + (c - '0');
                c = skipSpaces();
            }
            return value * sign;
        }

        /** Reads a string that ends at whitespace */
        public String readString() {
            int c = skipSpaces();
            StringBuilder sb = new StringBuilder();
            while (!isSpaceChar(c)) {
                sb.appendCodePoint(c);
                c = skipSpaces();
            }
            return sb.toString();
        }
    }
}

/*
 *  ------------------------------------------------------------
 *  Refactored version of the original program.
 *  - Clear separation of concerns
 *  - Meaningful naming & small focused methods
 *  - Avoid magic numbers (constants are named)
 *  - Single‑responsibility classes
 *  ------------------------------------------------------------
 */

import java.io.*;
import java.util.*;

/**
 * Handles all console I/O for the solution.
 */
class ConsoleIO {
    private final BufferedReader reader;
    private final PrintWriter writer;

    ConsoleIO() {
        this.reader = new BufferedReader(new InputStreamReader(System.in));
        this.writer = new PrintWriter(System.out, true); // auto‑flush
    }

    /** Reads a line, returning an empty string on EOF. */
    String readLine() {
        try {
            return reader.readLine();
        } catch (IOException e) {
            return "";
        }
    }

    /** Reads a whole line and trims trailing newline characters. */
    private String trimmedLine() {
        return readLine().trim();
    }

    /** Reads n integers from a single line. */
    int[] readIntArray() {
        String[] tokens = trimmedLine().split("\\s+");
        int[] result = new int[tokens.length];
        for (int i = 0; i < tokens.length; i++) {
            result[i] = Integer.parseInt(tokens[i]);
        }
        return result;
    }

    /** Writes a line to standard output. */
    void writeLine(String line) {
        writer.println(line);
    }

    /** Writes a sequence of values separated by a single space. */
    void writeSpaceSeparated(Collection<Integer> values) {
        for (Iterator<Integer> it = values.iterator(); it.hasNext(); ) {
            writer.print(it.next());
            if (it.hasNext()) {
                writer.print(' ');
            }
        }
        writer.println();
    }
}

/**
 * Represents the whole input grid and provides utility operations on it.
 */
final class Grid {
    private final char[][] original;   // '.' or '#' from the input
    private final int[][] componentId; // component identifier for '.' cells, -1 for '#'
    private final int rows;
    private final int cols;
    private final int[] dx = {-1, 0, 1, 0};
    private final int[] dy = {0, 1, 0, -1};

    Grid(int rows, int cols) {
        this.rows = rows;
        this.cols = cols;
        this.original = new char[rows][cols];
        this.componentId = new int[rows][cols];
        initialize();
    }

    /** Fills the original array with characters read from the input. */
    void readFromInput(ConsoleIO io) throws IOException {
        for (int r = 0; r < rows; r++) {
            String line = io.readLine();
            if (line == null) {
                throw new IOException("Unexpected end of input");
            }
            System.arraycopy(line.toCharArray(), 0, original[r], 0, cols);
        }
    }

    /** Initializes componentId array (‑1 for every cell). */
    private void initialize() {
        for (int r = 0; r < rows; r++) {
            Arrays.fill(componentId[r], -1);
        }
    }

    /** Returns a character at (r,c). */
    char getChar(int r, int c) {
        return original[r][c];
    }

    /** Sets the component identifier for a cell. */
    void setComponentId(int r, int c, int id) {
        componentId[r][c] = id;
    }

    /** Retrieves the component identifier of a cell. */
    int getComponentId(int r, int c) {
        return componentId[r][c];
    }

    /** Returns the number of rows. */
    int rows() {
        return rows;
    }

    /** Returns the number of columns. */
    int cols() {
        return cols;
    }

    /**
     * Performs a breadth‑first search to label all connected '.' cells with a
     * unique component id and stores the size of each component.
     *
     * @return an array where index = component id and value = component size.
     */
    int[] labelComponents() {
        int[] componentSize = new int[rows * cols + 1]; // 1‑based ids
        int compId = 1;

        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (getChar(r, c) == '.' && getComponentId(r, c) == -1) {
                    int size = bfsLabel(r, c, compId, componentSize);
                    componentSize[compId] = size;
                    compId++;
                }
            }
        }
        return componentSize;
    }

    /** Breadth‑first search that labels a component and returns its size. */
    private int bfsLabel(int startR, int startC, int id, int[] sizeArray) {
        Queue<Point> queue = new ArrayDeque<>();
        queue.add(new Point(startR, startC));
        setComponentId(startR, startC, id);
        int size = 1;

        while (!queue.isEmpty()) {
            Point cur = queue.poll();
            for (int dir = 0; dir < 4; dir++) {
                int nr = cur.r + dx[dir];
                int nc = cur.c + dy[dir];
                if (valid(nr, nc) && getChar(nr, nc) == '.' && getComponentId(nr, nc) == -1) {
                    setComponentId(nr, nc, id);
                    queue.add(new Point(nr, nc));
                    size++;
                }
            }
        }
        return size;
    }

    /** Checks whether (r,c) lies inside the grid boundaries. */
    private boolean valid(int r, int c) {
        return r >= 0 && c >= 0 && r < rows && c < cols;
    }
}

/**
 * Utility class that groups coordinates.
 */
final class Point {
    final int r;
    final int c;

    Point(int r, int c) {
        this.r = r;
        this.c = c;
    }
}

/**
 * Core algorithm implementation.
 */
class Solver {
    private final ConsoleIO io;
    private final Grid grid;
    private final int[] componentSize; // componentSize[id] = size of component id

    Solver(ConsoleIO io) {
        this.io = Objects.requireNonNull(io);
        this.grid = new Grid(0, 0);
    }

    /** Orchestrates the whole solution. */
    void solve() throws IOException {
        // ----------- read dimensions and grid -----------------
        int[] dims = io.readIntArray();
        int rows = dims[0];
        int cols = dims[1];
        grid = new Grid(rows, cols);
        grid.readFromInput(io);

        // ----------- label connected components ---------------
        componentSize = grid.labelComponents();

        // ----------- compute and output the result -------------
        produceResult();
    }

    /** Builds the output for each cell according to the problem statement. */
    private void produceResult() {
        int rows = grid.rows();
        int cols = grid.cols();

        for (int r = 0; r < rows; r++) {
            StringBuilder line = new StringBuilder(cols);
            for (int c = 0; c < cols; c++) {
                char cell = grid.getChar(r, c);
                if (cell == '.') {
                    line.append('.');
                } else { // cell is '#'
                    int extraSize = computeExtraSize(r, c);
                    line.append(extraSize % 10); // single digit as required
                }
            }
            io.writeLine(line.toString());
        }
    }

    /**
     * Determines how many extra cells are reachable when turning the current
     * obstacle ('#') into a walkable cell. It counts each adjacent component
     * only once.
     */
    private int computeExtraSize(int startR, int startC) {
        boolean[] visitedComp = new boolean[componentSize.length];
        int total = 1; // the cell itself counts as one

        for (int dir = 0; dir < 4; dir++) {
            int nr = startR + dx[dir];
            int nc = startC + dy[dir];
            if (!grid.valid(nr, nc)) {
                continue;
            }
            int compId = grid.getComponentId(nr, nc);
            if (compId == -1) {
                continue; // outside the component graph
            }
            if (visitedComp[compId]) {
                continue; // already counted this component
            }
            visitedComp[compId] = true;
            total += componentSize[compId];
        }
        return total;
    }
}

/**
 * Entry point – wires everything together.
 */
public class Main {
    public static void main(String[] args) {
        ConsoleIO console = new ConsoleIO();
        new Solver(console).solve();
        console.flush(); // close the underlying PrintWriter
    }
}

import java.io.*;
import java.util.*;

/**
 * Refactored version of the original program.
 *
 * <p>
 * The program reads a grid of characters ('.' represents an empty cell).  
 * For every empty region it computes the region size and stores that size in a
 * secondary matrix. Then, for every non‑empty cell it counts how many distinct
 * empty regions touch the cell, adds one (the cell itself) and writes the
 * resulting digit (modulo 10) back into the grid.
 * </p>
 *
 * <p>Changes made for maintainability and readability:</p>
 * <ul>
 *   <li>Extracted small helper classes ({@link Cell}, {@link DisjointSet},
 *       {@link FastScanner}, {@link RegionInfo}) to keep the main logic clean.</li>
 *   <li>Used meaningful names instead of single‑letter identifiers.</li>
 *   <li>Replaced manual queue handling with {@link Queue} of {@link Cell}
 *       objects.</li>
 *   <li>Wrapped I/O in try‑with‑resources to guarantee proper closure.</li>
 *   <li>Extracted direction vectors into a constant.</li>
 *   <li>Added short comments and Javadoc where helpful.</li>
 *   <li>Grouped related operations into small, single‑purpose methods.</li>
 * </ul>
 */
public class Main {

    /** Four cardinal directions used throughout the algorithm. */
    private static final int[][] DIRECTIONS = {
            {0,  1},   // right
            {1,  0},   // down
            {0, -1},   // left
            {-1, 0}    // up
    };

    /** Simple container for a board cell. */
    private static final class Cell {
        final int row;
        final int col;
        Cell(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }

    /** Disjoint‑set (Union‑Find) implementation. */
    private static final class DisjointSet {
        private final int[] parentSize;   // negative size for roots

        DisjointSet(int n) {
            parentSize = new int[n];
            Arrays.fill(parentSize, -1);
        }

        /** Find the root of the set containing {@code x}. */
        int find(int x) {
            if (parentSize[x] < 0) {
                return x;
            }
            return parentSize[x] = find(parentSize[x]);
        }

        /** Union the sets of {@code a} and {@code b}. */
        void union(int a, int b) {
            int rootA = find(a);
            int rootB = find(b);
            if (rootA == rootB) {
                return;
            }
            // union by size (larger tree absorbs smaller one)
            if (parentSize[rootA] > parentSize[rootB]) {
                parentSize[rootA] += parentSize[rootB];
                parentSize[rootB] = rootA;
            } else {
                parentSize[rootB] += parentSize[rootA];
                parentSize[rootA] = rootB;
            }
        }
    }

    /** Holds the result of the region‑size computation. */
    private static final class RegionInfo {
        final int[][] size;   // size of each '.' region stored per cell
        final DisjointSet ds; // union‑find structure used for component identification

        RegionInfo(int[][] size, DisjointSet ds) {
            this.size = size;
            this.ds = ds;
        }
    }

    /** Fast scanner that hides the boilerplate of tokenisation. */
    private static final class FastScanner {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        FastScanner(InputStream source) {
            this.reader = new BufferedReader(new InputStreamReader(source));
        }

        /** Returns the next non‑empty token, or {@code null} on EOF. */
        private String nextToken() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                String line = reader.readLine();
                if (line == null) {
                    return null;
                }
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(nextToken());
        }

        /** Reads the next token as a character array (used for grid lines). */
        char[] nextCharArray() throws IOException {
            String token = nextToken();
            if (token == null) {
                return null;
            }
            return token.toCharArray();
        }
    }

    /** Entry point of the program. */
    public static void main(String[] args) throws IOException {
        // The input format:  n m  (first line) followed by n lines of m characters.
        try (FastScanner fs = new FastScanner(System.in);
             PrintWriter out = new PrintWriter(System.out)) {

            int rows = fs.nextInt();
            int cols = fs.nextInt();

            char[][] grid = new char[rows][];
            for (int r = 0; r < rows; r++) {
                grid[r] = fs.nextCharArray();
            }

            RegionInfo regionInfo = computeRegionInfo(grid, rows, cols);
            char[][] result = transformGrid(grid, regionInfo.size, regionInfo.ds, rows, cols);

            for (char[] line : result) {
                out.println(new String(line));
            }
        }
    }

    /**
     * Performs a BFS over every connected '.' component, records its size and
     * builds the disjoint‑set structure required for later neighbour‑component
     * deduplication.
     */
    private static RegionInfo computeRegionInfo(char[][] grid, int rows, int cols) {
        int[][] size = new int[rows][cols];
        boolean[][] visited = new boolean[rows][cols];
        DisjointSet dsu = new DisjointSet(rows * cols);

        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (visited[r][c] || grid[r][c] != '.') {
                    continue;
                }
                List<Cell> component = bfsCollectComponent(grid, visited, r, c, dsu);
                int componentSize = component.size();

                // Store the same size for every cell belonging to this component.
                for (Cell cell : component) {
                    size[cell.row][cell.col] = componentSize;
                }
            }
        }
        return new RegionInfo(size, dsu);
    }

    /**
     * Breadth‑first search that gathers all cells of a '.' component,
     * performs union operations between adjacent cells and returns the whole
     * component.
     */
    private static List<Cell> bfsCollectComponent(char[][] grid,
                                                    boolean[][] visited,
                                                    int startR,
                                                    int startC,
                                                    DisjointSet dsu) {
        Queue<Cell> queue = new ArrayDeque<>();
        List<Cell> component = new ArrayList<>();

        queue.add(new Cell(startR, startC));
        visited[startR][startC] = true;
        component.add(new Cell(startR, startC));

        outer:
        while (!queue.isEmpty()) {
            Cell cur = queue.poll();

            for (int[] dir : DIRECTIONS) {
                int nr = cur.row + dir[0];
                int nc = cur.col + dir[1];

                if (!isInside(nr, rows = grid.length, nc, cols = grid[0].length)) {
                    continue;
                }
                if (visited[nr][nc] || grid[nr][nc] != '.') {
                    continue;
                }

                int curId = cur.row * grid[0].length + cur.col;
                int nbId = nr * grid[0].length + nc;
                dsu.union(curId, nbId);

                visited[nr][nc] = true;
                queue.add(new Cell(nr, nc));
                component.add(new Cell(nr, nc));
            }
        }
        return component;
    }

    /**
     * Applies the numeric transformation described in the original solution.
     * For each non‑'.' cell the algorithm:
     * <ol>
     *   <li>Counts the cell itself (contributes 1).</li>
     *   <li>Looks at the four orthogonal neighbours that are '.' cells.</li>
     *   <li>Adds the stored size of each *distinct* neighbouring component.</li>
     *   <li>Writes (sum % 10) as a character back into the grid.</li>
     * </ol>
     */
    private static char[][] transformGrid(char[][] original,
                                           int[][] componentSize,
                                           DisjointSet ds,
                                           int rows,
                                           int cols) {
        char[][] result = new char[rows][];
        for (int r = 0; r < rows; r++) {
            result[r] = new char[cols];
            for (int c = 0; c < cols; c++) {
                char ch = original[r][c];
                if (ch == '.') {
                    result[r][c] = ch;               // keep empty cells unchanged
                    continue;
                }

                int sum = 1;                         // the cell itself
                boolean[] visitedDirection = new boolean[4];
                Set<Integer> seenRoots = new HashSet<>();

                for (int k = 0; k < 4; k++) {
                    int nr = r + DIRECTIONS[k][0];
                    int nc = c + DIRECTIONS[k][1];

                    if (!isInside(nr, rows, nc, cols) || original[nr][nc] != '.') {
                        continue;
                    }

                    int neighborId = nr * cols + nc;
                    int root = ds.find(neighborId);

                    // Only count a component once
                    if (seenRoots.add(root)) {
                        sum += componentSize[nr][nc];
                    }
                }

                result[r][c] = (char) ('0' + (sum % 10));
            }
        }
        return result;
    }

    /** Utility: checks whether a coordinate lies inside the given bounds. */
    private static boolean isInside(int r, int maxR, int c, int maxC) {
        return r >= 0 && r < maxR && c >= 0 && c < maxC;
    }
}

/**
 * Fast scanner that works on raw bytes – keeps the original performance
 * characteristics while providing better method names.
 */
final class FastScanner {
    private final byte[] buffer = new byte[1 << 10];
    private int bufferPos = 0, bufferLen = -1;
    private final InputStream in;

    FastScanner(InputStream in) {
        this.in = in;
    }

    /** Read next non‑whitespace character. */
    private int readChar() throws IOException {
        if (bufferPos >= bufferLen) {
            bufferLen = in.read(buffer);
            bufferPos = 0;
            if (bufferLen <= 0) {
                return -1;
            }
        }
        return buffer[bufferPos++];
    }

    /** Skip any whitespace characters. */
    private static boolean isWhitespace(int c) {
        return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
    }

    /** Return next int from the input. */
    int nextInt() throws IOException {
        int c;
        do {
            c = readChar();
        } while (isWhitespace(c));

        int sign = 1;
        if (c == '-') {
            sign = -1;
            c = readChar();
        }

        int value = 0;
        while (!isWhitespace(c) && c != -1) {
            if (c >= '0' && c <= '9') {
                value = value * 10 + (c - '0');
            } else {
                throw new InputMismatchException();
            }
            c = readChar();
        }
        return value * sign;
    }

    /** Return next non‑empty token (String) from the input. */
    String nextString() throws IOException {
        int c;
        do {
            c = readChar();
        } while (isWhitespace(c));

        StringBuilder sb = new StringBuilder();
        while (!isWhitespace(c) && c != -1) {
            sb.append((char) c);
            c = readChar();
        }
        return sb.toString();
    }
}

/**
 * Holds the parsed grid together with all auxiliary structures used by the
 * algorithm (component IDs, visited flag, component sizes, …).
 */
final class GridState {
    private final char[][] map;          // original '.' / '*' characters
    private final int[][] componentId;   // component identifier for each cell (0 = none)
    private final boolean[][] visited;   // used during DFS/BFS
    private final int[][] componentSize; // size of each component (index starts at 1)

    int componentCount;                  // number of distinct components found
    int rows, cols;                      // grid dimensions

    GridState(char[][] map, int rows, int cols) {
        this.map = map;
        this.rows = rows;
        this.cols = cols;
        this.componentId = new int[rows][cols];
        this.visited = new boolean[rows][cols];
        this.componentSize = new int[rows * cols + 1]; // safe upper bound
    }

    /** Assign a unique id to every '.' region (component). */
    void labelComponents() {
        int nextId = 1;
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (map[r][c] == '*' || visited[r][c]) {
                    continue;
                }
                dfsLabel(r, c, nextId);
                nextId++;
            }
        }
        componentCount = nextId - 1; // last id used
    }

    /** Depth‑first search that fills {@code componentId} for a component. */
    private void dfsLabel(int r, int c, int id) {
        visited[r][c] = true;
        componentId[r][c] = id;
        componentSize[id]++; // count cells belonging to this component

        // explore 4‑neighbourhood
        if (r > 0 && !visited[r - 1][c] && map[r - 1][c] == '.') {
            dfsLabel(r - 1, c, id);
        }
        if (r + 1 < rows && !visited[r + 1][c] && map[r + 1][c] == '.') {
            dfsLabel(r + 1, c, id);
        }
        if (c > 0 && !visited[r][c - 1] && map[r][c - 1] == '.') {
            dfsLabel(r, c - 1, id);
        }
        if (c + 1 < cols && !visited[r][c + 1] && map[r][c + 1] == '.') {
            dfsLabel(r, c + 1, id);
        }
    }

    /** Compute the digit that must be placed at (r,c) in the output. */
    int computeDigit(int r, int c) {
        if (map[r][c] != '.') {
            throw new IllegalArgumentException("Called on non‑dot cell");
        }
        boolean[] seen = new boolean[componentCount + 1];
        int neighbourWeight = 0;

        // up
        if (r > 0 && componentId[r - 1][c] != 0 && !seen[componentId[r - 1][c]]) {
            neighbourWeight += componentSize[componentId[r - 1][c]];
            seen[componentId[r - 1][c]] = true;
        }
        // down
        if (r + 1 < rows && componentId[r + 1][c] != 0 && !seen[componentId[r + 1][c]]) {
            neighbourWeight += componentSize[componentId[r + 1][c]];
            seen[componentId[r + 1][c]] = true;
        }
        // left
        if (c > 0 && componentId[r][c - 1] != 0 && !seen[componentId[r][c - 1]]) {
            neighbourWeight += componentSize[componentId[r][c - 1]];
            seen[componentId[r][c - 1]] = true;
        }
        // right
        if (c + 1 < cols && componentId[r][c + 1] != 0 && !seen[componentId[r][c + 1]]) {
            neighbourWeight += componentSize[componentId[r][c + 1]];
            seen[componentId[r][c + 1]] = true;
        }

        return (neighbourWeight + 1) % 10;
    }

    /** Retrieve the stored grid (used for building the final string). */
    char[][] getOriginalMap() {
        return map;
    }
}

/**
 * Main driver – parses input, processes the grid and prints the required output.
 */
public class Main {
    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);

        int rows = fs.nextInt();
        int cols = fs.nextInt();

        // read the whole grid at once
        char[][] raw = new char[rows][];
        for (int r = 0; r < rows; r++) {
            raw[r] = fs.nextString().toCharArray();
        }

        GridState state = new GridState(raw, rows, cols);
        state.labelComponents();

        StringBuilder out = new StringBuilder();
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                char cell = state.getOriginalMap()[r][c];
                if (cell == '.') {
                    out.append((char) ('0' + state.computeDigit(r, c)));
                } else {
                    out.append('.');
                }
            }
            out.append('\n');
        }

        System.out.print(out.toString());
    }
}

import java.io.*;
import java.util.*;

/**
 * Main class that reads a labyrinth description from standard input,
 * analyses the connected empty cells and prints a transformed grid.
 *
 * <p>Each wall cell ('*') is printed as '.', each empty cell ('.')
 * shows the size of its connected component modulo 10 as a single digit.
 *
 * <p>The implementation is deliberately stylised for readability:
 * <ul>
 *   <li>All mutable state is confined to a dedicated {@code Labyrinth} object.</li>
 *   <li>Resources are managed with try‑with‑resources.</li>
 *   <li>Clear naming, small helper classes and separation of concerns improve maintainability.</li>
 * </ul>
 */
public class Labyrinth2 {

    /** Helper class that encapsulates the whole analysis of a labyrinth. */
    private static final class Labyrinth {
        private final int rows;
        private final int cols;
        private final boolean[][] blocked;          // true → wall ('*')
        private final int[][] componentId;           // -1 will never be used; 0 = unlabeled
        private final int[] componentSize;           // size of each component (1‑based index)
        private final StringBuilder output;          // final result

        Labyrinth(int rows, int cols, boolean[][] blocked) {
            this.rows = rows;
            this.cols = cols;
            this.blocked = blocked;
            this.componentId = new int[rows][cols];
            this.componentSize = new int[rows * cols + 1]; // +1 → 1‑based indexing
            this.output = new StringBuilder();
        }

        /** Assigns a component id to each empty cell and records component sizes. */
        void labelComponents() {
            int currentId = 1;
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (!blocked[r][c] && componentId[r][c] == 0) {
                        dfsLabel(r, c, currentId);
                        currentId++;
                    }
                }
            }
        }

        /** Depth‑first search (iterative) that labels one connected component. */
        private void dfsLabel(int startR, int startC, int id) {
            Deque<int[]> stack = new ArrayDeque<>();
            stack.push(new int[]{startR, startC});
            componentId[startR][startC] = id;
            componentSize[id]++;

            while (!stack.isEmpty()) {
                int[] cur = stack.pop();
                int r = cur[0];
                int c = cur[1];

                for (int[] dir : Directions.NEIGHBORS) {
                    int nr = r + dir[0];
                    int nc = c + dir[1];
                    if (!inside(nr, nc)) continue;
                    if (blocked[nr][nc]) continue;
                    if (componentId[nr][nc] != 0) continue;
                    componentId[nr][nc] = id;
                    componentSize[id]++;
                    stack.push(new int[]{nr, nc});
                }
            }
        }

        /** Checks whether a cell lies inside the grid borders. */
        private boolean inside(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }

        /** Produces the character that must be printed for a given cell. */
        char digitAt(int r, int c) {
            if (blocked[r][c]) {
                return '.';
            }
            int id = componentId[r][c];
            int sizeModulo10 = componentSize[id] % 10;
            return (char) ('0' + sizeModulo10);
        }

        /** Constructs the final multi‑line output string. */
        void buildOutput() {
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    output.append(digitAt(r, c));
                }
                output.append('\n');
            }
        }

        /** Directions used for neighbour exploration: up, down, left, right. */
        private static final class Directions {
            private static final int[][] NEIGHBORS = {
                {-1, 0},   // up
                { 1, 0},   // down
                { 0,-1},   // left
                { 0, 1}    // right
            };
        }
    }

    /** Entry point – reads input, processes it and prints the transformed grid. */
    public static void main(String[] args) throws IOException {
        // Try‑with‑resources guarantees proper closing of I/O streams.
        try (BufferedReader br = new BufferedReader(
                new InputStreamReader(System.in));
             PrintWriter out = new PrintWriter(System.out)) {

            // -----------------------------------------------------------------
            // 1️⃣  Parse dimensions and the grid itself.
            // -----------------------------------------------------------------
            String firstLine = br.readLine();
            if (firstLine == null) return;
            String[] dimTokens = firstLine.trim().split("\\s+");
            int rows = Integer.parseInt(dimTokens[0]);
            int cols = Integer.parseInt(dimTokens[1]);

            boolean[][] grid = new boolean[rows][cols];
            for (int r = 0; r < rows; r++) {
                String line = br.readLine();
                if (line == null) break;
                for (int c = 0; c < cols; c++) {
                    // '*' denotes a wall, any other character denotes an empty cell.
                    grid[r][c] = line.charAt(c) == '*';
                }
            }

            // -----------------------------------------------------------------
            // 2️⃣  Analyse the labyrinth.
            // -----------------------------------------------------------------
            Labyrinth labyrinth = new Labyrinth(rows, cols, grid);
            labyrinth.labelComponents();
            labyrinth.buildOutput();

            // -----------------------------------------------------------------
            // 3️⃣  Emit the result.
            // -----------------------------------------------------------------
            out.print(labyrinth.output.toString());
        }
    }
}

import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.io.IOException;
import java.util.*;

public class Main {

    /** Directions used for exploring a component */
    private static final int[][] DIRECTIONS = {
            {-1, 0}, {1, 0}, {0, -1}, {0, 1}
    };

    /** Size of the input grid */
    private final int rows, cols;

    /** Grid read from input */
    private char[][] grid;

    /** Component identifier for each '.' cell (‑1 for walls or unprocessed cells) */
    private int[][] componentId;

    /** Size of each component, indexed by its component number */
    private final int[] componentSize;

    /** Next unused component identifier */
    private int nextComponentId;

    /** Result buffer for the output */
    private StringBuilder output;

    /** --------------------------------------------------------------------- */
    /** Entry point */
    public static void main(String[] args) throws IOException {
        new Main().solve();
    }

    /** --------------------------------------------------------------------- */
    /** Core logic – reading, processing and printing the answer */
    private void solve() throws IOException {
        // ----- read input ----------------------------------------------------
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in))) {
            StringTokenizer tk = new StringTokenizer(br.readLine());
            rows = Integer.parseInt(tk.nextToken());
            cols = Integer.parseInt(tk.nextToken());

            grid = new char[rows][cols];
            for (int r = 0; r < rows; r++) {
                String line = br.readLine();
                System.arraycopy(line.toCharArray(), 0, grid[r], 0, cols);
            }
        }

        // ----- prepare data structures ---------------------------------------
        componentId = new int[rows][cols];
        Arrays.fill(componentId, -1);               // -1 == not visited / wall
        componentSize = new int[rows * cols];       // max possible components
        nextComponentId = 0;

        // ----- discover components -------------------------------------------
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '.' && componentId[r][c] == -1) {
                    assignComponentId(r, c, nextComponentId++);
                }
            }
        }

        // ----- build answer ----------------------------------------------------
        output = new StringBuilder(rows * cols);
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '*') {
                    output.append(calculateImpact(r, c));
                } else {
                    output.append('.');
                }
            }
            output.append('\n');
        }

        System.out.print(output.toString());
    }

    /** --------------------------------------------------------------------- */
    /** Assigns a unique identifier to all reachable '.' cells starting from
     *  (sr,sc) and records the size of the component.
     */
    private void assignComponentId(int sr, int sc, int id) {
        Queue<int[]> queue = new ArrayDeque<>();
        queue.add(new int[]{sr, sc});
        componentId[sr][sc] = id;
        int size = 0;

        while (!queue.isEmpty()) {
            int[] cur = queue.poll();
            int r = cur[0];
            int c = cur[1];
            size++;

            for (int[] dir : DIRECTIONS) {
                int nr = r + dir[0];
                int nc = c + dir[1];
                if (inside(nr, nc) && grid[nr][nc] == '.' && componentId[nr][nc] == -1) {
                    componentId[nr][nc] = id;
                    queue.add(new int[]{nr, nc});
                }
            }
        }

        componentSize[id] = size; // store component size for later use
    }

    /** --------------------------------------------------------------------- */
    /** Returns the character that represents the impact of a '*' cell.
     *  The impact is the sum of the sizes of distinct neighboring components,
     *  modulo 10.
     */
    private char calculateImpact(int r, int c) {
        Set<Integer> neighboringComponentIds = new HashSet<>();

        for (int[] dir : DIRECTIONS) {
            int nr = r + dir[0];
            int nc = c + dir[1];
            if (!inside(nr, nc)) continue;

            if (grid[nr][nc] != '.') continue; // only '.' cells belong to a component
            int compId = componentId[nr][nc];
            if (compId == -1) continue;        // safety, should never happen
            neighboringComponentIds.add(compId);
        }

        int impact = 0;
        for (int id : neighboringComponentIds) {
            impact += componentSize[id];
        }

        return Character.forDigit(impact % 10, 10);
    }

    /** --------------------------------------------------------------------- */
    /** Utility – checks whether a cell (r,c) lies inside the grid. */
    private boolean inside(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }
}

import java.io.*;
import java.util.*;

/**
 * Solves the described grid problem.
 * <p>
 * The program reads a rectangular grid consisting of '.' and '*' characters.
 * It groups connected '.' cells into components, counts the size of each component,
 * and for every '*' cell prints the sum of the sizes of the neighboring components
 * modulo 10 (as a digit). Empty cells are printed as '.'.
 * </p>
 */
public final class Main {

    /** Modulus used for intermediate calculations. */
    private static final long MOD = 1_000_000_007L;

    /** Directions used when exploring neighbours (up, down, left, right). */
    private static final int[] DR = { -1, 1, 0, 0 };
    private static final int[] DC = { 0, 0, -1, 1 };

    /** Fast scanner based on a buffered input stream. */
    private final FastScanner fs;

    /** Output writer (normally {@code System.out}). */
    private final PrintWriter out;

    /** Grid characters. */
    private char[][] grid;

    /** Component identifier for each cell (0 = not visited). */
    private int[][] componentId;

    /** Size of each component, indexed by component identifier (1‑based). */
    private int[] componentSize;

    /** Current component identifier counter. */
    private int componentCounter;

    /** Number of rows and columns of the grid. */
    private int rows, cols;

    public static void main(String[] args) throws Exception {
        new Main().run();
    }

    /** Constructor that initializes the scanner and the output writer. */
    public Main() {
        this.fs = new FastScanner();
        this.out = new PrintWriter(System.out, true);
    }

    /** Entry point – reads input, processes it and prints the result. */
    public void run() throws Exception {
        solve();
        out.flush();
    }

    /** Core logic: read data, colour components, and emit the answer. */
    private void solve() {
        rows = fs.nextInt();
        cols = fs.nextInt();

        grid = new char[rows][cols];
        componentId = new int[rows][cols];
        componentSize = new int[rows * cols + 1]; // +1 to make 1‑based indexing safe

        // -----------------------------------------------------------------
        // 1️⃣  Read the whole grid
        // -----------------------------------------------------------------
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                grid[r][c] = fs.nextChar();
            }
        }

        // -----------------------------------------------------------------
        // 2️⃣  Colour each connected '.' component
        // -----------------------------------------------------------------
        componentCounter = 1; // start from 1 to keep 0 as “unvisited”
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '.' && componentId[r][c] == 0) {
                    exploreComponent(r, c);
                    componentCounter++;
                }
            }
        }

        // -----------------------------------------------------------------
        // 3️⃣  Produce the required output
        // -----------------------------------------------------------------
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '*') {
                    out.print(digitForStar(r, c));
                } else {
                    out.print('.');
                }
            }
            out.println();
        }
    }

    /** Depth‑first exploration of a '.' component using an explicit stack. */
    private void exploreComponent(int startR, int startC) {
        ArrayDeque<int[]> stack = new ArrayDeque<>();
        stack.addLast(new int[]{startR, startC});

        while (!stack.isEmpty()) {
            int[] cur = stack.removeLast();
            int r = cur[0], c = cur[1];
            if (componentId[r][c] != 0) {
                continue; // already processed
            }
            componentId[r][c] = componentCounter;
            componentSize[componentCounter]++;

            // push all unvisited neighbours that are '.' onto the stack
            for (int d = 0; d < 4; d++) {
                int nr = r + DR[d];
                int nc = c + DC[d];
                if (nr < 0 || nr >= rows || nc < 0 || nc >= cols) {
                    continue;
                }
                if (grid[nr][nc] == '.' && componentId[nr][nc] == 0) {
                    stack.addLast(new int[]{nr, nc});
                }
            }
        }
    }

    /** Returns the digit that must be printed for a '*' at (r,c). */
    private char digitForStar(int r, int c) {
        // gather distinct component ids of the four neighbours
        Set<Integer> neighbourComponents = new HashSet<>();
        for (int d = 0; d < 4; d++) {
            int nr = r + DR[d];
            int nc = c + DC[d];
            if (nr < 0 || nr >= rows || nc < 0 || nc >= cols) {
                continue;
            }
            int id = componentId[nr][nc];
            if (id != 0) {
                neighbourComponents.add(id);
            }
        }

        // sum the sizes of those components and take modulo 10
        long sum = 1; // count the current '*' cell itself
        for (int id : neighbourComponents) {
            sum += componentSize[id];
        }
        return Character.forDigit((int) (sum % 10), 10);
    }

    /** ---------------------------------------------------------------
     *  Small utility class that wraps a byte buffer and provides fast I/O.
     *  --------------------------------------------------------------- */
    private static final class FastScanner {

        private final byte[] buffer = new byte[1 << 12];
        private int bufferPos = 0, bufferLen = 0;

        FastScanner() { }

        /** Reads the next byte, expanding the buffer if necessary. */
        private int readByte() throws IOException {
            if (bufferPos >= bufferLen) {
                bufferLen = System.in.read(buffer);
                bufferPos = 0;
                if (bufferLen <= 0) {
                    return -1;
                }
            }
            return buffer[bufferPos++];
        }

        /** Checks whether the current byte is whitespace. */
        private boolean isSpace(int ch) {
            return ch == ' ' || ch == '\n' || ch == '\r' || ch == '\t' || ch == -1;
        }

        /** Skips leading whitespace. */
        private int skipWhite(int start) throws IOException {
            int c;
            while ((c = readByte()) != -1 && isSpace(c)) { }
            return c;
        }

        /** Reads the next integer. */
        int nextInt() throws IOException {
            int c = skipWhite(readByte());
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = readByte();
            }
            int result = 0;
            while (c >= '0' && c <= '9') {
                result = result * 10 + (c - '0');
                c = readByte();
            }
            return result * sign;
        }

        /** Reads the next character (skipping whitespace). */
        char nextChar() throws IOException {
            int c = skipWhite(readByte());
            return (char) c;
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Entry point of the program.
 *
 * <p>The program reads a rectangular board consisting of two characters:
 * <ul>
 *   <li>'.' – empty cell</li>
 *   <li>'*' – occupied cell</li>
 * </ul>
 * It discovers every maximal connected component of empty cells,
 * records its size and then prints, for every occupied cell,
 * the size (mod 10) of the component that would appear if that cell were turned
 * into an empty cell and merged with its neighbouring empty components.
 *
 * <p>The implementation has been refactored for readability, testability and
 * maintainability: logic is split into small, well‑named methods, constants are
 * clearly named, and the flow of data is expressed by dedicated helper classes.
 */
public class Main {

    /** Symbol used for an empty cell */
    private static final char EMPTY = '.';

    /** Symbol used for a filled cell */
    private static final char FILLED = '*';

    /** Four orthogonal directions */
    private static final int[][] NEIGHBOURS = {
            {1, 0},   // down
            {-1, 0},  // up
            {0, -1},  // left
            {0, 1}    // right
    };

    /** --------------------------------------------------------------------- */
    /** Program entry point */
    public static void main(String[] args) throws Exception {
        // Fast I/O – the original implementation already used a custom scanner,
        // which we keep but rename it for clarity.
        try (FastScanner scanner = new FastScanner(System.in);
             PrintWriter out = new PrintWriter(System.out)) {

            int rows = scanner.nextInt();
            int cols = scanner.nextInt();

            // Read the whole board into a convenient array.
            String[] board = new String[rows];
            for (int r = 0; r < rows; r++) {
                board[r] = scanner.next();
            }

            // Process the board – all heavy lifting is delegated to this method.
            ComponentInfo info = analyseBoard(board);

            // Produce and output the result lines.
            List<String> result = info.buildResult(board);
            for (String line : result) {
                out.println(line);
            }
        }
    }

    /** --------------------------------------------------------------------- */
    /** Discover every empty component and store its size. */
    private static ComponentInfo analyseBoard(String[] board) {
        int n = board.length;
        int m = board[0].length();

        // Mapping from component id (starting at 1) to its size.
        Map<Integer, Integer> sizeById = new HashMap<>();

        // Component id per cell – 0 means “not yet visited”.
        int[][] componentId = new int[n][m];

        int nextId = 1;
        for (int r = 0; r < n; r++) {
            String row = board[r];
            for (int c = 0; c < m; c++) {
                if (row.charAt(c) != EMPTY) {
                    continue;
                }
                if (componentId[r][c] != 0) {
                    continue; // already processed by a previous expansion
                }

                // ---- BFS that discovers one connected component ----
                int id = nextId++;
                componentId[r][c] = id;
                Queue<int[]> queue = new ArrayDeque<>();
                queue.add(new int[]{r, c});

                while (!queue.isEmpty()) {
                    int[] cur = queue.poll();
                    for (int[] dir : NEIGHBOURS) {
                        int nr = cur[0] + dir[0];
                        int nc = cur[1] + dir[1];
                        if (!inBounds(nr, nc, n, m)) {
                            continue;
                        }
                        char neighbourChar = board[nr].charAt(nc);
                        if (neighbourChar != EMPTY || componentId[nr][nc] != 0) {
                            continue;
                        }
                        componentId[nr][nc] = id;
                        queue.add(new int[]{nr, nc});
                    }
                }

                // ---- Store the size of the discovered component ----
                int componentSize = countSize(componentId, id, n, m);
                sizeById.put(id, componentSize);
            }
        }

        return new ComponentInfo(componentId, sizeById);
    }

    /** --------------------------------------------------------------------- */
    /** Count cells that have the given component identifier. */
    private static int countSize(int[][] componentId, int id, int n, int m) {
        int cnt = 0;
        for (int r = 0; r < n; r++) {
            for (int c = 0; c < m; c++) {
                if (componentId[r][c] == id) {
                    cnt++;
                }
            }
        }
        return cnt;
    }

    /** --------------------------------------------------------------------- */
    /** Validate array bounds (inclusive). */
    private static boolean inBounds(int r, int c, int rows, int cols) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    /** --------------------------------------------------------------------- */
    /** Helper class that holds the results of the board analysis. */
    private static final class ComponentInfo {
        /** Mapping from component id → size (number of cells). */
        private final Map<Integer, Integer> sizeById;

        /** componentId[r][c] – id of the component that occupies cell (r,c). */
        private final int[][] componentId;

        ComponentInfo(int[][] componentId, Map<Integer, Integer> sizeById) {
            this.componentId = componentId;
            this.sizeById = sizeById;
        }

        /** Build the output that must be printed for each filled cell. */
        List<String> buildResult(String[] board) {
            StringBuilder sb = new StringBuilder();
            List<String> lines = new ArrayList<>();

            for (int r = 0; r < board.length; r++) {
                for (int c = 0; c < board[r].length(); c++) {
                    char ch = board[r].charAt(c);
                    if (ch == EMPTY) {
                        sb.append(EMPTY);
                    } else { // filled cell
                        Set<Integer> neighbourComponentIds = collectNeighbourIds(r, c, board.length, board[0].length());
                        int mergedSize = 1; // the cell itself
                        for (int id : neighbourComponentIds) {
                            mergedSize += sizeById.get(id);
                        }
                        sb.append(mergedSize % 10);
                    }
                    // End of line handling
                    if (c == board[r].length() - 1) {
                        lines.add(sb.toString());
                        sb.setLength(0);
                    } else {
                        sb.append(EMPTY);
                    }
                }
            }
            return lines;
        }

        /** Collect the ids of all distinct empty components surrounding (r,c). */
        private Set<Integer> collectNeighbourIds(int r, int c, int rows, int cols) {
            Set<Integer> ids = new HashSet<>();
            for (int[] dir : NEIGHBOURS) {
                int nr = r + dir[0];
                int nc = c + dir[1];
                if (!inBounds(nr, nc, rows, cols)) {
                    continue;
                }
                char neighbour = board[nr].charAt(nc);
                if (neighbour != EMPTY) {
                    continue;
                }
                int id = componentId[nr][nc];
                if (id == 0) {
                    continue;
                }
                ids.add(id);
            }
            return ids;
        }
    }

    /** --------------------------------------------------------------------- */
    /** Simple fast scanner compatible with the original semantics. */
    private static final class FastScanner implements AutoCloseable {
        private final BufferedReader reader;
        private String[] tokenBuffer;
        private int tokenIndex;

        FastScanner(InputStream is) {
            reader = new BufferedReader(new InputStreamReader(is));
        }

        /** Return all remaining tokens from the current line.
         *  If the buffer is exhausted, read the next line.
         */
        String[] fetchTokens() throws IOException {
            if (tokenBuffer == null || tokenIndex == tokenBuffer.length) {
                tokenBuffer = reader.readLine().split(" ");
                tokenIndex = 0;
            }
            return tokenBuffer;
        }

        /** Read the next integer token. */
        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }

        /** Return the next token (String). */
        String next() throws IOException {
            String[] tokens = fetchTokens();
            return tokens[tokenIndex++];
        }

        @Override
        public void close() throws Exception {
            reader.close();
        }
    }
}

// ---------------------------------------------------------------
//  Refactored version of the original `Main` class.
//  The program reads a grid, finds connected components of empty
//  cells ('.'), assigns each component a unique id and size, and
//  finally replaces each wall ('*') with a digit representing the
//  total size of all unique neighboring empty components (mod 10).
// ---------------------------------------------------------------
import java.io.*;
import java.util.*;

public class Main implements Runnable {

    /* -----------------------------------------------------------
       Constants & configuration
       ----------------------------------------------------------- */
    private static final long MOD = 1_000_000_007L;               // not used here, kept for symmetry with original
    private static final int MAX_VISIT = 1_001;                  // maximum matrix dimension
    private static final int[] DX = { -1, 0, 1, 0 };              // movement directions
    private static final int[] DY = { 0, -1, 0, 1 };
    private final boolean debugConsole = false;                  // flag that could enable custom file I/O

    /* -----------------------------------------------------------
       I/O fields
       ----------------------------------------------------------- */
    private FastScanner scanner;
    private PrintWriter writer;

    /* -----------------------------------------------------------
       Problem‑specific fields
       ----------------------------------------------------------- */
    private int n, m;                                            // grid dimensions
    private final int[][] visited = new int[MAX_VISIT][MAX_VISIT];
    private final Map<Integer, Integer> componentSize = new HashMap<>();
    // componentId starts at 1; 0 is reserved for walls

    /* -----------------------------------------------------------
       Entry point
       ----------------------------------------------------------- */
    public static void main(String[] args) throws Exception {
        new Main().run();
    }

    @Override
    public void run() {
        long start = System.currentTimeMillis();
        try {
            init();                // set up scanners/writers
            solve();               // core solving routine
        } finally {
            writer.flush();
        }
        System.err.println("Execution time: " + (System.currentTimeMillis() - start) + " ms");
    }

    /* -----------------------------------------------------------
       I/O initialisation – can be extended for special test cases
       ----------------------------------------------------------- */
    private void init() throws IOException {
        // In a typical contest environment we just use System.in / System.out.
        // The flag `debugConsole` could be toggled to read/write from files.
        InputStream inStream = System.in;
        OutputStream outStream = System.out;

        if (debugConsole) {
            try {
                outStream = new FileOutputStream("/home/puneet/Desktop/output.txt");
                inStream = new FileInputStream("/home/puneet/Desktop/input.txt");
            } catch (Exception ignored) {
            }
        }
        scanner = new FastScanner(inStream);
        writer = new PrintWriter(outStream);
    }

    /* -----------------------------------------------------------
       Main solve routine – handles a single test case (repeated loop)
       ----------------------------------------------------------- */
    private void solve() {
        int testCases = 1;                       // the original code expects only 1 case
        while (testCases-- > 0) {
            solveSingleTestCase();
        }
    }

    /* -----------------------------------------------------------
       Solve a single grid instance
       ----------------------------------------------------------- */
    private void solveSingleTestCase() {
        // ----- read dimensions -------------------------------------------------
        n = scanner.nextInt();
        m = scanner.nextInt();

        char[][] grid = new char[n][m];
        for (int i = 0; i < n; ++i) {
            String line = scanner.next();
            for (int j = 0; j < m; ++j) {
                grid[i][j] = line.charAt(j);
            }
        }

        // ----- first pass: discover components of '.' -------------------------
        int componentId = 0;
        // reset visited flags
        Arrays.fill(visited, new int[m * n]); // ensures all entries are 0

        for (int i = 0; i < n; ++i) {
            for (int j = 0; j < m; ++j) {
                if (visited[i][j] == 0 && grid[i][j] == '.') {
                    int size = dfs(grid, i, j, ++componentId);
                    componentSize.put(componentId, size);
                }
            }
        }

        // ----- second pass: build output ----------------------------------------
        for (int i = 0; i < n; ++i) {
            for (int j = 0; j < m; ++j) {
                if (grid[i][j] == '*') {
                    int total = 0;
                    Set<Integer> neighbourIds = new HashSet<>();

                    for (int d = 0; d < 4; ++d) {
                        int ni = i + DX[d];
                        int nj = j + DY[d];
                        if (inBounds(ni, nj) && visited[ni][nj] != 0) {
                            neighbourIds.add(visited[ni][nj]);
                        }
                    }
                    for (int id : neighbourIds) {
                        total += componentSize.getOrDefault(id, 0);
                    }
                    writer.print((total % 10));            // same output as original
                } else {
                    writer.print('.');
                }
            }
            writer.println();
        }
    }

    /* -----------------------------------------------------------
       Depth‑first search that returns the size of a component.
       ----------------------------------------------------------- */
    private int dfs(char[][] grid, int x, int y, int id) {
        visited[x][y] = id;
        int size = 1;

        for (int d = 0; d < 4; ++d) {
            int nx = x + DX[d];
            int ny = y + DY[d];
            if (inBounds(nx, ny) && grid[nx][ny] == '.' && visited[nx][ny] == 0) {
                size += dfs(grid, nx, ny, id);
            }
        }
        return size;
    }

    /* -----------------------------------------------------------
       Bounds check for matrix coordinates
       ----------------------------------------------------------- */
    private boolean inBounds(int x, int y) {
        return x >= 0 && x < n && y >= 0 && y < m;
    }

    /* -----------------------------------------------------------
       Lightweight, fast scanner based on BufferedInputStream.
       ----------------------------------------------------------- */
    private static final class FastScanner {
        private final BufferedInputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream source) {
            in = new BufferedInputStream(source);
        }

        private int readByte() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c, sign = 1, val = 0;
            do {
                c = readByte();
            } while (c <= ' ' && c != -1);
            if (c == '-') {
                sign = -1;
                c = readByte();
            }
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = readByte();
            }
            return val * sign;
        }

        String next() throws IOException {
            int c;
            do {
                c = readByte();
            } while (c <= ' ');
            StringBuilder sb = new StringBuilder();
            while (c > ' ') {
                sb.append((char) c);
                c = readByte();
            }
            return sb.toString();
        }
    }
}

