/**
 * Utility class that processes a labyrinth represented by '.' (empty) and '#' (wall) cells.
 * It builds a union‑find structure over all empty cells and then prints, for every wall cell,
 * the total size of adjacent empty‑cell regions (mod 10) on a line‑by‑line basis.
 */
final class LabyrinthProcessor {

    /** Directions used for neighbour checks (up, down, left, right). */
    private static final int[][] DIRS = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};

    /** Private constructor – this class only contains static helpers. */
    private LabyrinthProcessor() {}

    /**
     * Executes the labyrinth algorithm.
     *
     * @param board the labyrinth matrix where '.' denotes an empty cell
     * @return a list of strings, each representing one output line
     * @throws IllegalArgumentException if the board has inconsistent row lengths
     */
    static List<String> process(char[][] board) {
        validateBoard(board);
        int rows = board.length;
        int cols = board[0].length;

        // ---------- 1️⃣ Build Union‑Find over all '.' cells ----------
        UnionFind uf = new UnionFind(rows * cols);
        boolean[][] visited = new boolean[rows][cols];

        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (board[r][c] != '.' || visited[r][c]) {
                    continue;
                }
                visited[r][c] = true;
                uf.makeSet(r * cols + c);
                unionNeighbors(board, visited, r, c, rows, cols);
            }
        }

        // ---------- 2️⃣ Produce the required output ----------
        List<String> result = new ArrayList<>(rows);
        for (int r = 0; r < rows; r++) {
            StringBuilder line = new StringBuilder(cols);
            for (int c = 0; c < cols; c++) {
                if (board[r][c] == '.') {
                    line.append('.');
                    continue;
                }
                // wall cell → count adjacent empty‑cell regions
                Set<Integer> adjacentRoots = new HashSet<>();
                for (int[] dir : DIRS) {
                    int nr = r + dir[0];
                    int nc = c + dir[1];
                    if (inBounds(nr, nc, rows, cols) && board[nr][nc] == '.') {
                        int root = uf.find(nr * cols + nc);
                        adjacentRoots.add(root);
                    }
                }
                int regionSize = adjacentRoots.stream()
                        .mapToInt(uf::size)
                        .sum();
                line.append((char) ((regionSize % 10) + '0'));
            }
            result.add(line.toString());
        }
        return result;
    }

    /** Validates that all rows of the board have the same length. */
    private static void validateBoard(char[][] board) {
        if (board == null || board.length == 0) {
            return;
        }
        int expected = board[0].length;
        for (char[] row : board) {
            if (row == null || row.length != expected) {
                throw new IllegalArgumentException(
                        "All rows must have the same length. Found " + expected);
            }
        }
    }

    /** Checks array bounds. */
    private static boolean inBounds(int r, int c, int rows, int cols) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    /** Unites the current cell with its already‑visited neighbours. */
    private static void unionNeighbors(char[][] board,
                                       boolean[][] visited,
                                       int r,
                                       int c,
                                       int rows,
                                       int cols) {
        for (int[] dir : DIRS) {
            int nr = r + dir[0];
            int nc = c + dir[1];
            if (inBounds(nr, nc, rows, cols)
                    && board[nr][nc] == '.'
                    && visited[nr][nc]) {
                int curIdx = r * cols + c;
                int neighIdx = nr * cols + nc;
                uf.union(curIdx, neighIdx);
            }
        }
    }

    /** ---------- Union‑Find (Disjoint Set) implementation ---------- */
    private static final class UnionFind {
        private final int[] parent;
        private final int[] size;

        UnionFind(int n) {
            parent = new int[n];
            size = new int[n];
            for (int i = 0; i < n; i++) {
                parent[i] = i;
                size[i] = 1; // will be overwritten by makeSet()
            }
        }

        /** Initializes a set for a single element. */
        void makeSet(int x) {
            parent[x] = x;
            size[x] = 1;
        }

        /** Returns the representative of the set containing {@code x}. */
        int find(int x) {
            int root = x;
            while (root != parent[root]) {
                parent[root] = parent[parent[root]];
                root = parent[root];
            }
            return root;
        }

        /** Merges the sets of {@code a} and {@code b}. */
        void union(int a, int b) {
            int rootA = find(a);
            int rootB = find(b);
            if (rootA == rootB) {
                return;
            }
            // union by size (larger set becomes parent)
            if (size[rootA] < size[rootB]) {
                int tmp = rootA; rootA = rootB; rootB = tmp;
            }
            parent[rootB] = rootA;
            size[rootA] += size[rootB];
        }
    }
}

/**
 * Minimal wrapper that reads from {@code stdin} and prints the processed labyrinth.
 * This class keeps {@code LabyrinthProcessor} pure (it returns data instead of printing),
 * which makes unit testing straightforward.
 */
public final class Main {
    private Main() {}

    public static void main(String[] args) throws Exception {
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in))) {
            String[] header = br.readLine().split("\\s+");
            if (header.length != 2) {
                throw new IllegalArgumentException("Expected two dimensions on the first line");
            }
            int rows = Integer.parseInt(header[0]);
            int cols = Integer.parseInt(header[1]);

            char[][] board = new char[rows][];
            for (int r = 0; r < rows; r++) {
                String line = br.readLine();
                if (line == null) {
                    throw new IOException("Unexpected end of input while reading board");
                }
                board[r] = line.toCharArray();
            }

            LabyrinthProcessor processor = new LabyrinthProcessor(); // pure utility, no state
            List<String> output = processor.process(board);
            output.forEach(System.out::println);
        } catch (IOException e) {
            // In a real application we could log this, but for this small program printing is fine.
            e.printStackTrace();
        }
    }
}

package solution;

import java.io.*;
import java.util.*;

/**
 * Reads a grid, computes connected component sizes and replaces each '*'
 * cell with the sum (mod 10) of the sizes of the adjacent components.
 *
 * The implementation follows a clear separation of concerns:
 *   1. Input handling,
 *   2. Component discovery,
 *   3. Asterisk evaluation,
 *   4. Output rendering.
 *
 * All public entry points are deliberately small to keep the class easily
 * testable.
 */
public class Solver {

    /* --------------------------------------------------------------
     *  I/O helpers
     * -------------------------------------------------------------- */
    private final FastScanner scanner;
    private final PrintWriter printer;

    public Solver(InputStream in, PrintWriter out) {
        this.scanner = new FastScanner(in);
        this.printer = out;
    }

    /* --------------------------------------------------------------
     *  Core algorithm
     * -------------------------------------------------------------- */
    public void solve() {
        int rows = scanner.nextInt();
        int cols = scanner.nextInt();

        char[][] grid = readGrid(rows, cols);
        int[][] compId = assignComponentIds(grid);
        Map<Integer, Integer> componentSize = computeComponentSizes(compId, grid);
        replaceAsterisks(grid, compId, componentSize);

        printGrid(grid);
    }

    /** Reads the data part after the dimensions and builds a padded grid. */
    private char[][] readGrid(int rows, int cols) {
        char[][] grid = new char[rows + 2][cols + 2];
        fillBoundary(grid, '#');

        for (int r = 1; r <= rows; r++) {
            String line = scanner.next();
            grid[r] = ("#" + line + "#").toCharArray();
        }
        return grid;
    }

    private void fillBoundary(char[][] grid, char value) {
        Arrays.fill(grid[0], value);
        Arrays.fill(grid[grid.length - 1], value);
        for (char[] row : grid) {
            if (row.length > 0) {
                row[0] = value;
                row[row.length - 1] = value;
            }
        }
    }

    /**
     * Assigns a unique component identifier to each '.' cell (via BFS).
     * '#' cells receive id 0; '*' cells remain untouched (id stays 0).
     */
    private int[][] assignComponentIds(char[][] grid) {
        int rows = grid.length;
        int cols = grid[0].length;
        int[][] compId = new int[rows][cols];
        int nextId = 1;

        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '.' && compId[r][c] == 0) {
                    bfsComponent(grid, compId, nextId++);
                }
            }
        }
        return compId;
    }

    /** BFS that marks all reachable '.' cells with the current component id. */
    private void bfsComponent(char[][] grid, int[][] compId, int id) {
        Deque<Integer> qY = new ArrayDeque<>();
        Deque<Integer> qX = new ArrayDeque<>();

        qY.addLast(0); // placeholder – will be replaced immediately
        qX.addLast(0);
        // find the real start cell
        outer:
        for (int r = 0; r < grid.length; r++) {
            for (int c = 0; c < grid[r].length; c++) {
                if (grid[r][c] == '.' && compId[r][c] == 0) {
                    qY.addLast(r);
                    qX.addLast(c);
                    break outer;
                }
            }
        }

        while (!qY.isEmpty()) {
            int y = qY.removeFirst();
            int x = qX.removeFirst();
            compId[y][x] = id;

            exploreNeighbour(grid, compId, y + 1, x, id);
            exploreNeighbour(grid, compId, y - 1, x, id);
            exploreNeighbour(grid, compId, y, x + 1, id);
            exploreNeighbour(grid, compId, y, x - 1, id);
        }
    }

    /** Marks a neighbour with the given id if it is a '.' and not visited yet. */
    private void exploreNeighbour(char[][] grid, int[][] compId,
                                  int nr, int nc, int id) {
        if (isInside(grid, nr, nc) && grid[nr][nc] == '.' && compId[nr][nc] == 0) {
            compId[nr][nc] = id;
        }
    }

    private boolean isInside(char[][] grid, int r, int c) {
        return r >= 0 && r < grid.length && c >= 0 && c < grid[r].length;
    }

    /** Stores the size of each component identified by its id. */
    private Map<Integer, Integer> computeComponentSizes(int[][] compId, char[][] grid) {
        Map<Integer, Integer> sizeMap = new HashMap<>();
        for (int[] row : compId) {
            for (int id : row) {
                if (id != 0) {
                    sizeMap.merge(id, 1, Integer::sum);
                }
            }
        }
        return sizeMap;
    }

    /**
     * For every '*' cell, sum the sizes of the distinct adjacent components,
     * take the result modulo 10 and replace the character with the digit.
     */
    private void replaceAsterisks(char[][] grid, int[][] compId,
                                  Map<Integer, Integer> sizeMap) {
        int rows = grid.length;
        int cols = grid[0].length;

        for (int r = 1; r < rows - 1; r++) {
            for (int c = 1; c < cols - 1; c++) {
                if (grid[r][c] == '*') {
                    Set<Integer> neighbourIds = collectAdjacentComponentIds(grid, compId, r, c);
                    long sum = 1; // the '*' itself counts as 1
                    for (int id : neighbourIds) {
                        sum += sizeMap.getOrDefault(id, 0);
                    }
                    grid[r][c] = (char) ('0' + (int) (sum % 10));
                }
            }
        }
    }

    /** Returns the set of component ids that surround the given cell. */
    private Set<Integer> collectAdjacentComponentIds(char[][] grid,
                                                       int[][] compId,
                                                       int r, int c) {
        Set<Integer> ids = new HashSet<>();
        addIfValid(ids, compId, r - 1, c);
        addIfValid(ids, compId, r + 1, c);
        addIfValid(ids, compId, r, c - 1);
        addIfValid(ids, compId, r, c + 1);
        return ids;
    }

    private void addIfValid(Set<Integer> set, int[][] compId, int nr, int nc) {
        if (isInside(compId, nr, nc)) {
            int id = compId[nr][nc];
            if (id != 0) {
                set.add(id);
            }
        }
    }

    private boolean isInside(int[][] compId, int r, int c) {
        return r >= 0 && r < compId.length && c >= 0 && c < compId[r].length;
    }

    /** Prints the resulting grid to the configured output stream. */
    private void printGrid(char[][] grid) {
        for (int r = 1; r < grid.length - 1; r++) {
            for (int c = 1; c < grid[r].length - 1; c++) {
                printer.print(grid[r][c]);
            }
            printer.println();
        }
    }

    /* --------------------------------------------------------------
     *  Fast scanner (unchanged but nicely encapsulated)
     * -------------------------------------------------------------- */
    private static class FastScanner {
        private final DataInputStream din;
        private final byte[] buffer;
        private int bufferPtr;
        private int bytesRead;

        FastScanner(InputStream in) {
            this.din = new DataInputStream(in);
            this.buffer = new byte[1 << 16];
            this.bufferPtr = this.bytesRead = 0;
        }

        private byte read() throws IOException {
            if (bufferPtr == bytesRead) {
                fillBuffer();
            }
            return buffer[bufferPtr++];
        }

        private void fillBuffer() throws IOException {
            bytesRead = din.read(buffer, 0, buffer.length);
            bufferPtr = 0;
            if (bytesRead <= 0) {
                buffer[0] = -1;
            }
        }

        /** Skips leading whitespace. */
        private int skipWhite() throws IOException {
            int c;
            do {
                c = read();
            } while (isSpaceChar(c));
            return c;
        }

        private static boolean isSpaceChar(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        int nextInt() throws IOException {
            int c = skipWhite();
            boolean neg = false;
            if (c == '-') {
                neg = true;
                c = read();
            }
            int val = 0;
            do {
                val = val * 10 + (c - '0');
            } while ((c = read()) >= '0' && c <= '9');
            return neg ? -val : val;
        }
    }
}

/* --------------------------------------------------------------
 *  Entry point
 * -------------------------------------------------------------- */
class Main {
    public static void main(String[] args) throws Exception {
        Solver solver = new Solver(System.in, new PrintWriter(System.out, false));
        solver.solve();
    }
}

/**
 * Refactored solution for the “Symbol Grid” problem.
 *
 * The program reads a grid of characters, assigns a unique identifier to every
 * connected component of '.' cells, stores the size of each component and then
 * evaluates every '*' cell by summing the sizes of the distinct neighbouring
 * components (plus 1) and printing the last digit of that sum.
 *
 * The implementation favours readability, clear naming and modern Java practices
 * (try‑with‑resources, immutable collections where appropriate, BFS/DFS without
 * recursion, etc.).
 */
public class SymbolGridSolver {

    /** Simple scanner wrapper that mimics the original MyScanner. */
    private static final class MyScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        MyScanner() {
            this.br = new BufferedReader(new InputStreamReader(System.in));
        }

        /** Return the next non‑empty token. */
        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    throw new UncheckedIOException(e);
                }
            }
            return st.nextToken();
        }

        /** Convenience method for reading integers. */
        int nextInt() {
            return Integer.parseInt(next());
        }
    }

    /**
     * Holds the size of each connected component identified by an integer id.
     */
    private static final class ComponentSizeRegistry {
        /** Mapping from component id (1‑based) to its size. */
        private final Map<Integer, Long> sizes = new HashMap<>();
        /** Next available component identifier. */
        private int nextId = 1;

        /** Register a component of the given size and return its id. */
        int register(long size) {
            int id = nextId++;
            sizes.put(id, size);
            return id;
        }

        /** Retrieve the size of a component by its id. */
        long sizeOf(int id) {
            return sizes.get(id);
        }

        /** Current number of registered components. */
        int componentCount() {
            return nextId - 1;
        }
    }

    /** Directions used for exploring neighbours (up, down, left, right). */
    private static final class Directions {
        static final int[] DR = {-1, 0, 1, 0};
        static final int[] DC = {0, -1, 0, 1};
    }

    /**
     * Entry point of the program.
     */
    public static void main(String[] args) throws IOException {
        MyScanner scanner = new MyScanner();
        PrintWriter out = new PrintWriter(new BufferedOutputStream(System.out));

        // -----------------------------------------------------------------
        // 1️⃣  Read dimensions and grid
        // -----------------------------------------------------------------
        int rows = scanner.nextInt();
        int cols = scanner.nextInt();

        char[][] grid = new char[rows][];
        for (int r = 0; r < rows; r++) {
            grid[r] = scanner.next().toCharArray();
        }

        // -----------------------------------------------------------------
        // 2️⃣  Discover all '.' components and record their sizes
        // -----------------------------------------------------------------
        int[][] componentId = new int[rows][cols];      // 0 = not visited yet
        ComponentSizeRegistry registry = new ComponentSizeRegistry();

        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '.' && componentId[r][c] == 0) {
                    long componentSize = breadthFirstSize(grid, componentId, registry);
                    registry.register(componentSize);
                }
            }
        }

        // -----------------------------------------------------------------
        // 3️⃣  Resolve each '*' cell using its neighbouring component sizes
        // -----------------------------------------------------------------
        char[][] output = new char[rows][cols];
        for (int r = 0; r < rows; r++) {
            Arrays.fill(output[r], '.');
        }

        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '*') {
                    long sum = evaluateStarCell(grid, componentId, registry, r, c);
                    output[r][c] = Character.forName("java.lang.String$C" + (sum % 10));
                }
            }
        }

        // -----------------------------------------------------------------
        // 4️⃣  Emit the result
        // -----------------------------------------------------------------
        for (char[] row : output) {
            out.println(new String(row));
        }

        out.close();
    }

    /**
     * Performs a BFS starting at (startRow,startCol) to compute the size of the
     * connected '.' component.  The visited cells are marked with a unique
     * component identifier.
     *
     * @return the number of cells belonging to the discovered component.
     */
    private static long breadthFirstSize(
            char[][] grid,
            int[][] componentId,
            ComponentSizeRegistry registry) {

        Queue<int[]> queue = new ArrayDeque<>();
        queue.add(new int[]{0, 0}); // placeholder, will be replaced by real start
        // Find the first unvisited '.' cell to start BFS
        outer:
        for (int r = 0; r < grid.length; r++) {
            for (int c = 0; c < grid[r].length; c++) {
                if (grid[r][c] == '.' && componentId[r][c] == 0) {
                    queue.clear();
                    queue.add(new int[]{r, c});
                    componentId[r][c] = registry.nextId; // provisional id (will be registered later)
                    int discovered = 0;
                    while (!queue.isEmpty()) {
                        int[] cur = queue.poll();
                        int cr = cur[0];
                        int cc = cur[1];
                        discovered++;
                        for (int d = 0; d < Directions.DR.length; d++) {
                            int nr = cr + Directions.DR[d];
                            int nc = cc + Directions.DC[d];
                            if (isInBounds(grid, nr, nc) &&
                                grid[nr][nc] == '.' &&
                                componentId[nr][nc] == 0) {
                                componentId[nr][nc] = registry.nextId;
                                queue.add(new int[]{nr, nc});
                            }
                        }
                    }
                    // Register the component with its real size and return it
                    return registry.register((long) discovered);
                }
            }
        }
        // If we reach here there were no '.' cells – this should never happen
        return 0L;
    }

    /** Helper that checks array bounds. */
    private static boolean isInBounds(char[][] grid, int r, int c) {
        return r >= 0 && r < grid.length && c >= 0 && c < grid[0].length;
    }

    /**
     * Calculates the value for a '*' cell by adding the sizes of all distinct
     * neighbouring components (identified by their ids) and then adding 1.
     *
     * @return the last decimal digit of the computed sum.
     */
    private static long evaluateStarCell(
            char[][] grid,
            int[][] componentId,
            ComponentSizeRegistry registry,
            int r,
            int c) {

        if (!isInBounds(grid, r, c)) {
            return 0L;
        }

        Set<Integer> neighbourIds = new HashSet<>();

        for (int d = 0; d < Directions.DR.length; d++) {
            int nr = r + Directions.DR[d];
            int nc = c + Directions.DC[d];
            if (isInBounds(grid, nr, nc) && grid[nr][nc] == '.') {
                int cid = componentId[nr][nc];
                if (cid != 0) {
                    neighbourIds.add(cid);
                }
            }
        }

        long sum = 1; // the '+ 1' required by the problem statement
        for (int id : neighbourIds) {
            sum += registry.sizeOf(id);
        }
        return sum % 10;
    }
}

/**
 * Refactored version of {@code TheLabyrinth}.
 *
 * <p>Improvements made:
 *
 * <ul>
 *   <li>Extracted concerns into small, focused methods.
 *   <li>Used {@link BufferedReader} with try‑with‑resources to guarantee closure.
 *   <li>Replaced recursion with an explicit stack for DFS to avoid stack‑overflow on large inputs.
 *   <li>Introduced {@code Direction} enum to centralise neighbour handling.
 *   <li>Used {@link StringBuilder} instead of {@link StringBuffer} for single‑threaded output.
 *   <li>Removed all {@code printStackTrace()} calls in favour of a simple logger.
 *   <li>Adopted consistent naming conventions and added Javadoc comments.
 *   <li>Encapsulated the core logic in a dedicated {@code LabyrinthProcessor} class.
 * </ul>
 *
 * The functionality remains identical to the original program:
 * it reads a grid of characters, identifies connected components of '.' cells,
 * and replaces each '*' with a digit representing the number of distinct
 * adjacent component sizes (modulo 10).
 */
public class TheLabyrinth {

    /** Simple logger that prints stack traces to {@code System.err}. */
    private static void log(Throwable t) {
        t.printStackTrace();
    }

    /** Represents the four orthogonal directions used for neighbour traversal. */
    private enum Direction {
        UP(-1, 0),
        DOWN(1, 0),
        LEFT(0, -1),
        RIGHT(0, 1);

        private final int rowDelta;
        private final int colDelta;

        Direction(int rowDelta, int colDelta) {
            this.rowDelta = rowDelta;
            this.colDelta = colDelta;
        }

        int[] delta() {
            return new int[]{rowDelta, colDelta};
        }
    }

    /** Core class that owns the algorithmic steps. */
    private static final class LabyrinthProcessor {

        private final char[][] grid;
        private final int[][] componentId;   // component identifier per cell
        private final boolean[][] visited;
        private final Map<Integer, Integer> componentSize; // componentId -> size
        private int nextComponentId;

        LabyrinthProcessor(char[][] grid) {
            this.grid = grid;
            int rows = grid.length;
            int cols = grid[0].length;
            this.componentId = new int[rows][cols];
            this.visited = new boolean[rows][cols];
            this.componentSize = new HashMap<>();
            this.nextComponentId = 1;
        }

        /** Performs the whole processing pipeline and writes the result to {@code System.out}. */
        void processAndPrint() {
            labelComponents();

            StringBuilder out = new StringBuilder();
            for (int r = 0; r < grid.length; r++) {
                StringBuilder line = new StringBuilder(grid[r].length);
                for (int c = 0; c < grid[r].length; c++) {
                    char cell = grid[r][c];
                    if (cell != '*') {
                        line.append(cell);
                    } else {
                        line.append(digitForStar(r, c));
                    }
                }
                out.append(line).append('\n');
            }
            System.out.print(out.toString());
        }

        /** Assigns a unique id to each '.' component and records its size. */
        private void labelComponents() {
            for (int r = 0; r < grid.length; r++) {
                for (int c = 0; c < grid[0].length; c++) {
                    if (grid[r][c] == '.' && !visited[r][c]) {
                        int component = bfsComponent(r, c);
                        componentSize.put(component, componentSize.getOrDefault(component, 0) + sizeOfLastComponent());
                        nextComponentId = component + 1;
                    }
                }
            }
        }

        /** BFS‑based component labeling that returns the assigned component id. */
        private int bfsComponent(int startRow, int startCol) {
            int id = nextComponentId++;
            Deque<int[]> stack = new ArrayDeque<>();
            stack.push(new int[]{startRow, startCol});

            while (!stack.isEmpty()) {
                int[] cur = stack.pop();
                int r = cur[0];
                int c = cur[1];
                if (visited[r][c]) {
                    continue;
                }
                visited[r][c] = true;
                componentId[r][c] = id;

                for (Direction dir : Direction.values()) {
                    int nr = r + dir.delta()[0];
                    int nc = c + dir.delta()[1];
                    if (isInBounds(nr, nc) && grid[nr][nc] == '.' && !visited[nr][nc]) {
                        stack.push(new int[]{nr, nc});
                    }
                }
            }
            return id;
        }

        /** Returns the size of the most recently discovered component (used only internally). */
        private int sizeOfLastComponent() {
            // The size is stored in the componentSize map when the component is created.
            // This method simply returns the size of the component we just added.
            // It is kept private to avoid exposing extra data structures.
            int lastId = nextComponentId - 1;
            return componentSize.getOrDefault(lastId, 0);
        }

        /** Determines the digit that should replace a '*' at (row, col). */
        private char digitForStar(int row, int col) {
            Set<Integer> neighbourComponents = new HashSet<>();
            int total = 0;

            for (Direction dir : Direction.values()) {
                int nr = row + dir.delta()[0];
                int nc = col + dir.delta()[1];
                if (isInBounds(nr, nc) && componentId[nr][nc] != 0 && neighbourComponents.add(componentId[nr][nc])) {
                    total += componentSize.get(neighbourComponents.stream()
                                                          .filter(id -> id == componentId[nr][nc])
                                                          .findFirst()
                                                          .orElse(-1));
                }
            }
            return (char) (((total + 1) % 10) + '0');
        }

        /** Checks whether a given cell coordinate lies inside the grid. */
        private boolean isInBounds(int r, int c) {
            return r >= 0 && r < grid.length && c >= 0 && c < grid[0].length;
        }
    }

    /** Entry point – parses input and launches the processor. */
    public static void main(String[] args) {
        try (FastScanner sc = new FastScanner()) {
            int rows = sc.nextInt();
            int cols = sc.nextInt();

            char[][] grid = readGrid(sc, rows, cols);
            new LabyrinthProcessor(grid).processAndPrint();
        } catch (Exception e) {
            log(e);
        }
    }

    /** Reads the grid of characters from the scanner. */
    private static char[][] readGrid(FastScanner sc, int rows, int cols) {
        char[][] grid = new char[rows][cols];
        for (int r = 0; r < rows; r++) {
            String line = sc.nextToken();
            for (int c = 0; c < cols; c++) {
                grid[r][c] = line.charAt(c);
            }
        }
        return grid;
    }

    /**
     * Fast scanner that works with both file arguments and {@code System.in}.
     *
     * <p>Only the methods that are actually used by the refactored program are
     * provided; the implementation remains compatible with the original.
     */
    public static final class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        /** Creates a scanner that reads from the given file. */
        public FastScanner(String filePath) {
            try {
                br = new BufferedReader(new FileReader(filePath));
            } catch (FileNotFoundException e) {
                log(e);
                throw new IllegalArgumentException("File not found: " + filePath, e);
            }
        }

        /** Creates a scanner that reads from standard input. */
        public FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        /** Returns the next token, fetching a new line if necessary. */
        private String nextToken() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) {
                        return null;
                    }
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    log(e);
                }
            }
            return st.nextToken();
        }

        /** Convenience wrapper for {@code nextInt()}. */
        public int nextInt() {
            return Integer.parseInt(nextToken());
        }

        /** Convenience wrapper for {@code nextLong()}. */
        public long nextLong() {
            return Long.parseLong(nextToken());
        }

        /** Convenience wrapper for {@code nextDouble()}. */
        public double nextDouble() {
            return Double.parseDouble(nextToken());
        }
    }
}

import java.io.*;
import java.util.*;

public class P616C {
    private static final PrintWriter OUT = new PrintWriter(System.out);
    private static char[][] grid;
    private static boolean[][] visited;
    private static int rows;
    private static int cols;
    private static List<Integer> groupSizes;
    private static Cell[][] cellGrid;
    private static final int[] ROW_OFFSETS = {0, 1, 0, -1};
    private static final int[] COL_OFFSETS = {1, 0, -1, 0};

    public static void main(String[] args) throws IOException {
        initInput();
        findConnectedComponents();
        calculateGroupTotals();
        printResult();
        OUT.flush();
    }

    private static void initInput() throws IOException {
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
        String[] dims = reader.readLine().split("\\s+");
        rows = Integer.parseInt(dims[0]);
        cols = Integer.parseInt(dims[1]);

        grid = new char[rows][cols];
        visited = new boolean[rows][cols];
        cellGrid = new Cell[rows][cols];
        groupSizes = new ArrayList<>();

        for (int i = 0; i < rows; i++) {
            grid[i] = reader.readLine().toCharArray();
        }
    }

    private static void findConnectedComponents() {
        int currentGroupId = 0;

        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == '.' && !visited[i][j]) {
                    processComponent(i, j, currentGroupId++);
                }
            }
        }
    }

    private static void processComponent(int startRow, int startCol, int groupId) {
        Queue<Cell> queue = new LinkedList<>();
        queue.add(new Cell(startRow, startCol, groupId));
        visited[startRow][startCol] = true;
        cellGrid[startRow][startCol] = new Cell(startRow, startCol, groupId);

        int componentSize = 0;
        while (!queue.isEmpty()) {
            Cell current = queue.poll();
            componentSize++;

            for (int direction = 0; direction < 4; direction++) {
                int nextRow = current.row + ROW_OFFSETS[direction];
                int nextCol = current.column + COL_OFFSETS[direction];

                if (isInvalid(nextRow, nextCol)) continue;
                if (grid[nextRow][nextCol] != '.') continue;
                if (visited[nextRow][nextCol]) continue;

                visited[nextRow][nextCol] = true;
                cellGrid[nextRow][nextCol] = new Cell(nextRow, nextCol, groupId);
                queue.add(new Cell(nextRow, nextCol));
            }
        }
        groupSizes.add(componentSize);
    }

    private static boolean isInvalid(int row, int col) {
        return row < 0 || col < 0 || row >= rows || col >= cols;
    }

    private static void calculateGroupTotals() {
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == '*') {
                    processObstacle(i, j);
                }
            }
        }
    }

    private static void processObstacle(int row, int col) {
        Set<Integer> adjacentGroupIds = new HashSet<>();

        for (int direction = 0; direction < 4; direction++) {
            int nextRow = row + ROW_OFFSETS[direction];
            int nextCol = col + COL_OFFSETS[direction];

            if (isInvalid(nextRow, nextCol)) continue;
            if (grid[nextRow][nextCol] != '.') continue;

            int groupId = cellGrid[nextRow][nextCol].groupId;
            adjacentGroupIds.add(groupId);
        }

        int total = 0;
        for (int groupId : adjacentGroupIds) {
            total += groupSizes.get(groupId);
        }

        grid[row][col] = (char) ((total % 10) + '0');
    }

    private static void printResult() {
        StringBuilder output = new StringBuilder();
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                output.append(grid[i][j] == '.' ? '.' : grid[i][j]);
            }
            output.append('\n');
        }
        OUT.print(output.toString());
    }

    private static class Cell {
        final int row;
        final int column;
        final int groupId;

        Cell(int row, int column) {
            this.row = row;
            this.column = column;
            this.groupId = 0;
        }

        Cell(int row, int column, int groupId) {
            this.row = row;
            this.column = column;
            this.groupId = groupId;
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.Arrays;
import java.util.HashSet;
import java.util.Objects;
import java.util.Set;

/**
 * Refactored solution that computes, for every '*' cell, the sum of the
 * sizes of the adjacent '.' connected components modulo 10.
 *
 * The program follows a clear structure:
 *   1. Reads the grid.
 *   2. Builds a Union‑Find (Disjoint Set) structure to identify connected
 *      '.' components and their sizes.
 *   3. For each '*' cell, aggregates the sizes of distinct neighboring
 *      components and stores the result modulo 10.
 *   4. Prints the resulting grid.
 *
 * The implementation favours readability, explicit naming and avoidance of
 * unnecessary reflection or debugging code.
 */
public class Main {

    // Directions: right, down, left, up
    private static final int[][] DIRS = {{0, 1}, {1, 0}, {0, -1}, {-1, 0}};

    /** Disjoint Set Union data structure for grid cells. */
    private static final class UF {
        private final int[] parent;
        private final int[] size; // size of component (valid only for roots)

        UF(int elements) {
            parent = new int[elements];
            size = new int[elements];
            for (int i = 0; i < elements; i++) {
                parent[i] = i;
                size[i] = 1;
            }
        }

        /** Find the root of x with path compression. */
        int find(int x) {
            if (parent[x] != x) {
                parent[x] = find(parent[x]);
            }
            return parent[x];
        }

        /** Union the sets containing x and y. */
        void union(int x, int y) {
            int rx = find(x);
            int ry = find(y);
            if (rx == ry) {
                return;
            }
            // Attach smaller tree under the larger one.
            if (size[rx] < size[ry]) {
                int tmp = rx; rx = ry; ry = tmp;
            }
            parent[ry] = rx;
            size[rx] += size[ry];
        }

        /** Size of the component that contains x. */
        int componentSize(int x) {
            return size[find(x)];
        }
    }

    /** Simple token reader based on BufferedReader. */
    private static final class Stdin {
        private final BufferedReader br;
        private final java.util.Queue<String> tokenQueue = new java.util.ArrayDeque<>();

        Stdin() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        /** Return the next whitespace‑separated token from stdin. */
        private String nextToken() {
            while (true) {
                try {
                    if (tokenQueue.isEmpty()) {
                        String line = br.readLine();
                        if (line == null) {
                            throw new IOException("EOF");
                        }
                        for (String tok : line.trim().split("\\s+")) {
                            tokenQueue.add(tok);
                        }
                    }
                    return tokenQueue.poll();
                } catch (IOException e) {
                    throw new UncheckedIOException(e);
                }
            }
        }

        int nextInt() {
            return Integer.parseInt(nextToken());
        }

        /** Read exactly n tokens and return them as a String array. */
        String[] nextStringArray(int n) {
            String[] arr = new String[n];
            for (int i = 0; i < n; i++) {
                arr[i] = nextToken();
            }
            return arr;
        }
    }

    /** Simple output wrapper around PrintWriter. */
    private static final class Stdout {
        private final PrintWriter out = new PrintWriter(System.out, true);

        /** Print a row of characters (joined into a single string). */
        void printRow(String[] row) {
            out.println(String.join("", row));
        }

        /** Flush the underlying stream. */
        void flush() {
            out.flush();
        }
    }

    /** Main solving routine. */
    public void solve() {
        Stdin stdin = new Stdin();
        Stdout stdout = new Stdout();

        int n = stdin.nextInt();
        int m = stdin.nextInt();
        String[] grid = stdin.nextStringArray(n);

        int totalCells = n * m;
        UF uf = new UF(totalCells);

        /* -------------------------------------------------------------
         * 1️⃣ Unite all '.' cells into connected components.
         * ------------------------------------------------------------- */
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i].charAt(j) != '.') {
                    continue;
                }
                int id = i * m + j;               // linear index of (i, j)
                // Union with already processed neighbours (up & left)
                for (int[] d : DIRS) {
                    int ni = i + d[0];
                    int nj = j + d[1];
                    if (ni < 0 || ni >= n || nj < 0 || nj >= m) {
                        continue;
                    }
                    if (grid[ni].charAt(nj) == '.') {
                        int nid = ni * m + nj;
                        uf.union(id, nid);
                    }
                }
            }
        }

        /* -------------------------------------------------------------
         * 2️⃣ Build the answer grid.
         * ------------------------------------------------------------- */
        char[][] answer = new char[n][];
        for (int i = 0; i < n; i++) {
            answer[i] = new char[m];
            Arrays.fill(answer[i], '.');        // default value
        }

        /* -------------------------------------------------------------
         * 3️⃣ Process each '*' cell.
         * ------------------------------------------------------------- */
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i].charAt(j) != '*') {
                    continue;
                }
                Set<Integer> seenComponents = new HashSet<>();
                int summedSize = 0;

                for (int[] d : DIRS) {
                    int ni = i + d[0];
                    int nj = j + d[1];
                    if (ni < 0 || ni >= n || nj < 0 || nj >= m) {
                        continue;
                    }
                    if (grid[ni].charAt(nj) == '.') {
                        int compRoot = uf.find(ni * m + nj);
                        if (seenComponents.add(compRoot)) {
                            summedSize += uf.componentSize(compRoot);
                        }
                    }
                }
                answer[i][j] = (char) ('0' + (summedSize % 10));
            }
        }

        /* -------------------------------------------------------------
         * 4️⃣ Output the result.
         * ------------------------------------------------------------- */
        for (char[] row : answer) {
            stdout.printRow(row);
        }
        stdout.flush();
    }

    /** Entry point. */
    public static void main(String[] args) {
        new Main().solve();
    }
}

import java.io.*;
import java.util.*;

/**
 * Refactored version of the original labyrinth solver.
 * The functionality is identical, but the code is now:
 *   • Better organized (clear separation of concerns)
 *   • Uses meaningful names and small helper classes
 *   • Avoids magic numbers and deep nesting
 *   • Is easier to read, maintain and extend
 */
public class TheLabyrinth {

    /** Fast scanner used for reading input. */
    private static class FastReader {
        private final InputStream stream;
        private final byte[] buffer = new byte[1024];
        private int ptr = 0, len = 0;

        FastReader(InputStream stream) {
            this.stream = stream;
        }

        private int readByte() {
            if (ptr >= len) {
                len = stream.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        private int skipWhite() {
            int c;
            do {
                c = readByte();
            } while (c <= ' ');
            return c;
        }

        int nextInt() {
            int c = skipWhite();
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = readByte();
            }
            long val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = readByte();
            }
            return (int) (sign * val);
        }

        long nextLong() {
            long c = skipWhite();
            long sign = 1;
            if (c == '-') {
                sign = -1;
                c = readByte();
            }
            long val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = readByte();
            }
            return sign * val;
        }

        /** Reads the next non‑whitespace token. */
        String next() {
            int c = skipWhite();
            StringBuilder sb = new StringBuilder();
            while (c > ' ') {
                sb.append((char) c);
                c = readByte();
            }
            return sb.toString();
        }

        /** Reads the next line (including spaces). */
        String nextLine() {
            StringBuilder sb = new StringBuilder();
            int c;
            // skip trailing newlines from previous reads
            while ((c = readByte()) != -1 && (c == '\n' || c == '\r')) {}
            while (c != -1) {
                sb.append((char) c);
                c = readByte();
                if (c == '\n' || c == '\r') break;
            }
            return sb.toString();
        }
    }

    /** Four cardinal directions. */
    private static final int[] DR = {1, -1, 0, 0};
    private static final int[] DC = {0, 0, -1, 1};

    /** Simple container for a cell coordinate. */
    private static final class Pair {
        final int r, c;
        Pair(int r, int c) { this.r = r; this.c = c; }
    }

    /** Entry point of the program. */
    public static void main(String[] args) throws Exception {
        FastReader fr = new FastReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        int n = fr.nextInt();          // number of rows
        int m = fr.nextInt();          // number of columns
        char[][] grid = new char[n][];
        for (int i = 0; i < n; i++) {
            String line = fr.nextLine().trim();
            grid[i] = line.toCharArray();
        }

        // -----------------------------------------------------------------
        // 1️⃣  Discover all connected components of '.' cells.
        // -----------------------------------------------------------------
        int[][] componentId = new int[n][m];          // id of component for each '.' cell
        Map<Integer, Integer> sizeById = new HashMap<>(); // component id → size
        boolean[][] visited = new boolean[n][m];
        int currentId = 0;

        for (int r = 0; r < n; r++) {
            for (int c = 0; c < m; c++) {
                if (grid[r][c] == '*' || visited[r][c]) continue;

                // BFS to explore the whole component
                List<Pair> component = new ArrayList<>();
                Queue<Pair> queue = new ArrayDeque<>();
                queue.add(new Pair(r, c));
                visited[r][c] = true;
                component.add(new Pair(r, c));

                while (!queue.isEmpty()) {
                    Pair cur = queue.poll();
                    int cr = cur.r, cc = cur.c;
                    for (int d = 0; d < 4; d++) {
                        int nr = cr + DR[d];
                        int nc = cc + DC[d];
                        if (valid(nr, nc, n, m)
                                && grid[nr][nc] == '.'
                                && !visited[nr][nc]) {
                            visited[nr][nc] = true;
                            queue.add(new Pair(nr, nc));
                            component.add(new Pair(nr, nc));
                        }
                    }
                }

                int componentSize = component.size();
                sizeById.put(currentId, componentSize);
                for (Pair p : component) {
                    componentId[p.r][p.c] = currentId;
                }
                currentId++;
            }
        }

        // -----------------------------------------------------------------
        // 2️⃣  Build the result matrix.
        // -----------------------------------------------------------------
        char[][] result = new char[n][];
        for (int r = 0; r < n; r++) {
            StringBuilder sb = new StringBuilder(m);
            for (int c = 0; c < m; c++) {
                if (grid[r][c] == '.') {
                    sb.append('.');
                    continue;
                }

                // Obstacle cell – look at the neighboring components.
                int total = 1; // count the obstacle itself
                Set<Integer> seenIds = new HashSet<>();
                for (int d = 0; d < 4; d++) {
                    int nr = r + DR[d];
                    int nc = c + DC[d];
                    if (!valid(nr, nc, n, m) || grid[nr][nc] != '.') continue;
                    int id = componentId[nr][nc];
                    if (id == 0) continue; // safety guard
                    if (seenIds.add(id)) { // true only if id was not present before
                        total += sizeById.get(id);
                    }
                }
                sb.append((char) ('0' + (total % 10)));
            }
            result[r] = sb.toString().toCharArray();
        }

        // -----------------------------------------------------------------
        // 3️⃣  Output the final grid.
        // -----------------------------------------------------------------
        for (char[] row : result) {
            out.println(new String(row));
        }
        out.flush();
    }

    /** Utility method to check array bounds. */
    private static boolean valid(int r, int c, int n, int m) {
        return r >= 0 && r < n && c >= 0 && c < m;
    }
}

import java.io.*;
import java.util.*;

public class Main {

    /** Symbolic constants for cell states */
    private static final int EMPTY = 0;   // traversable cell
    private static final int OBSTACLE = -1; // cell that contains '*'

    public static void main(String[] args) throws Exception {
        // try‑with‑resources guarantees proper closure of streams
        try (FastScanner scanner = new FastScanner(System.in);
             PrintWriter writer = new PrintWriter(System.out)) {

            int rows = scanner.nextInt();
            int cols = scanner.nextInt();

            char[][] rawInput = new char[rows][];
            for (int r = 0; r < rows; r++) {
                rawInput[r] = scanner.next().toCharArray();
            }

            int[][] grid = parseInput(rawInput);
            ComponentInfo[] components = analyzeComponents(grid, rows, cols);
            char[][] output = buildResult(grid, rows, cols, components);

            for (char[] line : output) {
                writer.println(new String(line));
            }
        }
    }

    /** Converts the character grid to an integer representation */
    private static int[][] parseInput(char[][] raw) {
        int rows = raw.length;
        int cols = raw[0].length;
        int[][] grid = new int[rows][cols];
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                grid[r][c] = (raw[r][c] == '*') ? OBSTACLE : EMPTY;
            }
        }
        return grid;
    }

    /** Information about a connected component of empty cells */
    private static final class ComponentInfo {
        final int id;    // component identifier (≥1)
        final int size;  // number of cells in the component

        ComponentInfo(int id, int size) {
            this.id = id;
            this.size = size;
        }
    }

    /** Finds all components of empty cells and records their sizes */
    private static ComponentInfo[] analyzeComponents(int[][] grid,
                                                     int rows,
                                                     int cols) {
        int[] sizeById = new int[rows * cols + 1]; // occasional oversize for safety
        Arrays.fill(sizeById, 0);
        int nextId = 1;

        int[] dr = {1, 0, -1, 0};
        int[] dc = {0, 1, 0, -1};

        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] != EMPTY) continue;
                if (grid[r][c] > 0) continue; // already processed

                int id = nextId++;
                bfsLabel(grid, rows, cols, r, c, id, dr, dc);
            }
        }

        // Populate ComponentInfo array
        ComponentInfo[] comps = new ComponentInfo[nextId];
        for (int id = 1; id < nextId; id++) {
            comps[id] = new ComponentInfo(id, sizeById[id]);
        }
        return comps;
    }

    /** Breadth‑first search that tags all cells of a component with the given id */
    private static void bfsLabel(int[][] grid,
                                 int rows,
                                 int cols,
                                 int startR,
                                 int startC,
                                 int id,
                                 int[] dr,
                                 int[] dc) {
        Queue<int[]> queue = new ArrayDeque<>();
        queue.add(new int[]{startR, startC});
        grid[startR][startC] = id;

        while (!queue.isEmpty()) {
            int[] cur = queue.poll();
            int r = cur[0];
            int c = cur[1];

            for (int k = 0; k < dr.length; k++) {
                int nr = r + dr[k];
                int nc = c + dc[k];
                if (isInBounds(nr, nc, rows, cols) && grid[nr][nc] == EMPTY) {
                    grid[nr][nc] = id;
                    queue.add(new int[]{nr, nc});
                }
            }
        }
    }

    /** Scans the grid once to count how many cells carry a particular id */
    private static int countComponentSize(int[][] grid, int id,
                                          int[] dr, int[] dc) {
        int count = 0;
        outer:
        for (int r = 0; r < grid.length; r++) {
            for (int c = 0; c < grid[0].length; c++) {
                if (grid[r][c] == id) {
                    count++;
                }
            }
        }
        return count;
    }

    /** Constructs the output matrix where each obstacle is replaced by a digit */
    private static char[][] buildResult(int[][] grid,
                                        int rows,
                                        int cols,
                                        ComponentInfo[] components) {
        char[][] result = new char[rows][cols];
        int[] dr = {1, 0, -1, 0};
        int[] dc = {0, 1, 0, -1};

        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == OBSTACLE) {
                    processObstacle(r, c, grid, dr, dc, components, result);
                } else {
                    result[r][c] = '.';
                }
            }
        }
        return result;
    }

    /** For a single obstacle cell computes the digit to print */
    private static void processObstacle(int r, int c,
                                        int[][] grid,
                                        int[] dr,
                                        int[] dc,
                                        ComponentInfo[] components,
                                        char[][] result) {
        boolean[] seen = new boolean[components.length];
        int sum = 1; // count the obstacle cell itself

        for (int i = 0; i < dr.length; i++) {
            int nr = r + dr[i];
            int nc = c + dc[i];
            if (!isInBounds(nr, nc, grid.length, grid[0].length)) continue;

            int id = grid[nr][nc];
            if (id > 0 && !seen[id]) {
                seen[id] = true;
                sum += components[id].size;
            }
        }

        result[r][c] = (char) ('0' + (sum % 10));
    }

    /** Small helper to keep bounds checks tidy */
    private static boolean isInBounds(int r, int c, int rows, int cols) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    /** Fast scanner that reads tokens from standard input */
    static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner(InputStream input) {
            br = new BufferedReader(new InputStreamReader(input));
            st = new StringTokenizer("");
        }

        String next() throws IOException {
            while (!st.hasMoreTokens()) {
                st = new StringTokenizer(br.readLine());
            }
            return st.nextToken();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }
}

import java.io.*;
import java.util.HashSet;
import java.util.Set;

/**
 * Solution for the grid problem.
 *
 * <p>
 * The program reads an {@code n × m} grid that contains '.' (empty cells) and
 * '*' (blocked cells). For every blocked cell it prints a digit that represents
 * the total size of the distinct neighboring empty components, increased by one
 * and taken modulo {@code 10}. Empty cells are printed as '.'.
 * </p>
 */
public class Solution {

    // -------------------------------------------------------------------------
    //  Constants & direction vectors
    // -------------------------------------------------------------------------
    /** up, left, right, down */
    private static final int[] DX = {-1, 0, 0, 1};
    private static final int[] DY = {0, -1, 1, 0};

    // -------------------------------------------------------------------------
    //  Shared state
    // -------------------------------------------------------------------------
    private static char[][] grid;                     // the input grid
    private static int[][] componentId;               // component identifier per cell
    private static int[] componentSize;               // size of each component (1‑based)
    private static int componentCount;                // number of distinct '.' components

    // -------------------------------------------------------------------------
    //  Entry point
    // -------------------------------------------------------------------------
    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();
        PrintWriter out = new PrintWriter(System.out);

        int n = fs.nextInt();      // number of rows
        int m = fs.nextInt();      // number of columns

        grid = new char[n];
        for (int i = 0; i < n; i++) {
            grid[i] = fs.next().toCharArray();
        }

        componentId   = new int[n][m];
        componentSize = new int[n * m + 1];   // use 1‑based indexing
        componentCount = 0;

        // -------------------------------------------------------------
        //  Phase 1 – label all '.' components and compute their sizes.
        // -------------------------------------------------------------
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i][j] == '.' && componentId[i][j] == 0) {
                    componentCount++;
                    componentSize[componentCount] = dfsLabel(i, j, componentCount);
                }
            }
        }

        // -------------------------------------------------------------
        //  Phase 2 – produce the required output.
        // -------------------------------------------------------------
        char[][] result = new char[n][];
        for (int i = 0; i < n; i++) {
            char[] row = new char[m];
            for (int j = 0; j < m; j++) {
                if (grid[i][j] == '.') {
                    row[j] = '.';
                } else {
                    int sum = 0;
                    Set<Integer> neighbourComponents = new HashSet<>();

                    for (int d = 0; d < 4; d++) {
                        int ni = i + DX[d];
                        int nj = j + DY[d];
                        if (isInside(ni, nj) && grid[ni][nj] == '.') {
                            neighbourComponents.add(componentId[ni][nj]);
                        }
                    }
                    for (int comp : neighbourComponents) {
                        sum += componentSize[comp];
                    }
                    // (sum + 1) % 10 gives the required digit.
                    row[j] = Character.forDigit((sum + 1) % 10, 10);
                }
            }
            out.println(row);
        }

        out.flush();
    }

    // -------------------------------------------------------------------------
    //  DFS that labels a connected '.' component and returns its size.
    // -------------------------------------------------------------------------
    /**
     * Recursively visits all reachable '.' cells, assigns them {@code currentId},
     * and returns the total number of visited cells.
     */
    private static int dfsLabel(int i, int j, int currentId) {
        componentId[i][j] = currentId;
        int size = 1;
        for (int d = 0; d < 4; d++) {
            int ni = i + DX[d];
            int nj = j + DY[d];
            if (isInside(ni, nj) && grid[ni][nj] == '.' && componentId[ni][nj] == 0) {
                size += dfsLabel(ni, nj, currentId);
            }
        }
        return size;
    }

    // -------------------------------------------------------------------------
    //  Helper utilities
    // -------------------------------------------------------------------------
    /** Checks whether a cell lies inside the grid boundaries. */
    private static boolean isInside(int x, int y) {
        return 0 <= x && x < grid.length && 0 <= y && y < grid[0].length;
    }

    /** Simple fast scanner that tokenises the whole input line by line. */
    private static final class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        /** Returns the next token, reading a new line if necessary. */
        private String next() throws IOException {
            while (st == null || !st.hasMoreElements()) {
                st = new StringTokenizer(br.readLine());
            }
            return st.nextToken();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }
}

import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Scanner;

/**
 * Reads a rectangular grid consisting of '.' (empty) and '*' (blocked) cells.
 * For each blocked cell the program prints a digit that equals the sum of the
 * sizes of all distinct adjacent regions (modulo 10). Empty cells are printed
 * as '.'.
 *
 * <p>Refactored version – focuses on readability, encapsulation and
 * maintainability.</p>
 */
public class Main {

    /** Four orthogonal directions: up, right, down, left. */
    private enum Direction {
        UP(-1, 0), RIGHT(0, 1), DOWN(1, 0), LEFT(0, -1);

        private final int deltaI;
        private final int deltaJ;

        Direction(int deltaI, int deltaJ) {
            this.deltaI = deltaI;
            this.deltaJ = deltaJ;
        }

        int deltaI() {
            return deltaI;
        }

        int deltaJ() {
            return deltaJ;
        }
    }

    /** Entry point of the program. */
    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            solve(scanner);
        }
    }

    /** Orchestrates input reading, processing and output printing. */
    private static void solve(Scanner scanner) {
        int rows = scanner.nextInt();
        int columns = scanner.nextInt();
        scanner.nextLine(); // discard end‑of‑line

        String[] grid = new String[rows];
        for (int i = 0; i < rows; i++) {
            grid[i] = scanner.nextLine();
        }

        int[][] regionIds = new int[rows][columns];
        Map<Integer, Integer> regionSize = new HashMap<>();

        discoverRegions(grid, regionIds, regionSize);

        char[][] output = computeResult(grid, regionIds, regionSize);

        for (char[] row : output) {
            System.out.println(row);
        }
    }

    /** Assigns a unique identifier to each connected component of '*' cells
     *  and records the size of each component. */
    private static void discoverRegions(String[] grid, int[][] regionIds,
                                         Map<Integer, Integer> regionSize) {
        // Mark blocked cells with -1
        for (int i = 0; i < grid.length; i++) {
            for (int j = 0; j < grid[i].length(); j++) {
                if (grid[i].charAt(j) == '*') {
                    regionIds[i][j] = -1;
                }
            }
        }

        int nextId = 1;
        for (int i = 0; i < grid.length; i++) {
            for (int j = 0; j < grid[i].length(); j++) {
                if (regionIds[i][j] == 0) {
                    int size = floodFill(grid, regionIds, i, j, nextId);
                    regionSize.put(nextId, size);
                    nextId++;
                }
            }
        }
    }

    /** Recursive flood‑fill that labels all cells of the current region. */
    private static int floodFill(String[] grid, int[][] regionIds,
                                 int i, int j, int id) {
        regionIds[i][j] = id;
        int filled = 1;

        for (Direction dir : Direction.values()) {
            int ni = i + dir.deltaI();
            int nj = j + dir.deltaJ();

            if (isInBounds(grid, ni, nj) && regionIds[ni][nj] == 0) {
                filled += floodFill(grid, regionIds, ni, nj, id);
            }
        }
        return filled;
    }

    /** Generates the output matrix based on adjacency information of blocked cells. */
    private static char[][] computeResult(String[] grid, int[][] regionIds,
                                          Map<Integer, Integer> regionSize) {
        char[][] output = new char[grid.length][grid[0].length];

        for (int i = 0; i < grid.length; i++) {
            for (int j = 0; j < grid[i].length(); j++) {
                if (regionIds[i][j] == -1) {
                    output[i][j] = digitForBlockedCell(grid, regionIds, regionSize, i, j);
                } else {
                    output[i][j] = '.';
                }
            }
        }
        return output;
    }

    /** Calculates the digit to be placed on a blocked ('*') cell. */
    private static char digitForBlockedCell(String[] grid, int[][] regionIds,
                                            Map<Integer, Integer> regionSize,
                                            int row, int col) {
        Set<Integer> neighboringRegionIds = new HashSet<>();

        for (Direction dir : Direction.values()) {
            int ni = row + dir.deltaI();
            int nj = col + dir.deltaJ();

            if (isInBounds(grid, ni, nj) && regionIds[ni][nj] > 0) {
                neighboringRegionIds.add(regionIds[ni][nj]);
            }
        }

        int sum = 0;
        for (int id : neighboringRegionIds) {
            sum += regionSize.get(id);
        }
        return Character.forDigit(sum % 10, 10);
    }

    /** Returns true if the given coordinates are inside the grid. */
    private static boolean isInBounds(String[] grid, int i, int j) {
        return i >= 0 && i < grid.length && j >= 0 && j < grid[i].length();
    }
}

import java.io.*;
import java.util.*;
import java.util.stream.Collectors;

/**
 * Refactored solution for the problem "CF5C".
 *
 * <p>Changes made:
 * <ul>
 *   <li>Extracted small, single‑purpose classes ({@code Board}, {@code Cell})</li>
 *   <li>Replaced nested {@code InputReader} with a dedicated class</li>
 *   <li>Used descriptive variable / method names</li>
 *   <li>Removed dead code (unused joins, shuffling, etc.)</li>
 *   <li>Prefer Java 8 streams where they improve readability</li>
 *   <li>Encapsulated debug handling and I/O selection in {@code main}</li>
 * </ul>
 */
public final class CF5CRefactored {

    /** Switch to debug mode when an {@code input.in} file is present. */
    private static boolean DEBUG = false;

    private static final class Board {
        private final int rows, cols;
        private final boolean[][] grid;

        Board(int rows, int cols) {
            this.rows = rows;
            this.cols = cols;
            this.grid = new boolean[rows + 2][cols + 2]; // padded with false border
        }

        /** Fill the interior of the board from the input stream. */
        void readFrom(InputReader in) {
            for (int r = 0; r < rows; r++) {
                String line = in.next();
                for (int c = 0; c < cols; c++) {
                    grid[r + 1][c + 1] = line.charAt(c) == '.';
                }
            }
        }

        boolean isOpen(int x, int y) {
            return grid[x][y];
        }
    }

    /** Simple pair of coordinates used for BFS/DFS. */
    private static final class Cell {
        final int x, y;
        Cell(int x, int y) {
            this.x = x;
            this.y = y;
        }
    }

    /** Reads tokens from an {@link InputStream} using a small hand‑rolled buffer. */
    private static final class InputReader implements AutoCloseable {
        private final InputStream in;
        private final byte[] buf = new byte[8192];
        private int ptr = 0, len = 0;

        InputReader(InputStream in) {
            this.in = in;
        }

        private int readByte() throws IOException {
            if (ptr >= len) {
                len = in.read(buf);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buf[ptr++];
        }

        private static boolean isSpace(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        /** Skip leading whitespace. */
        private void skipSpaces() throws IOException {
            int c;
            while ((c = readByte()) != -1 && isSpace(c)) {}
            if (c != -1) ptr--; // retract one char to include the first non‑space
        }

        /** Return the next whitespace‑separated token. */
        String next() throws IOException {
            skipSpaces();
            StringBuilder sb = new StringBuilder();
            int c = readByte();
            while (!isSpace(c)) {
                sb.append((char) c);
                c = readByte();
            }
            return sb.toString();
        }

        /** Read the next {@code int} token. */
        int nextInt() throws IOException {
            return (int) nextLong();
        }

        /** Read the next {@code long} token. */
        long nextLong() throws IOException {
            skipSpaces();
            boolean negative = false;
            int c = readByte();
            if (c == '-') {
                negative = true;
                c = readByte();
            }
            long value = 0;
            while (!isSpace(c) && c != -1) {
                value = value * 10 + (c - '0');
                c = readByte();
            }
            return negative ? -value : value;
        }

        @Override
        public void close() throws IOException {
            // Do not close System.in – only close when a dedicated file stream is used.
        }
    }

    /** Entry point. */
    public static void main(String[] args) throws Exception {
        long start = System.currentTimeMillis();

        // Enable debug mode if an input file named "input.in" exists.
        DEBUG = new File("input.in").exists();

        InputStream source = DEBUG
                ? new FileInputStream(new File("input.in"))
                : System.in;

        if (DEBUG) {
            solve(source);
            System.out.println("Time: " + (System.currentTimeMillis() - start) + " ms");
        } else {
            solve(source);
        }
    }

    /** Solve a single test case – repeatedly called for each test when DEBUG is on. */
    private static void solve(InputStream source) throws IOException {
        try (InputReader reader = new InputReader(source)) {
            runCase(reader);
        }
    }

    /** Process one test case and print the answer directly to {@code System.out}. */
    private static void runCase(InputReader in) {
        int tests = 1;
        if (DEBUG) {
            tests = in.nextInt();
        }

        StringBuilder overall = new StringBuilder();
        for (int t = 1; t <= tests; t++) {
            if (t > 1) overall.append('\n');
            System.out.print("------ ").append(t).append(" ------\n");
            processSingleTest(in, overall);
        }
        System.out.print(overall.toString());
    }

    /** Core logic for a single test case. */
    private static void processSingleTest(InputReader in, StringBuilder out) {
        int n = in.nextInt();
        int m = in.nextInt();

        Board board = new Board(n, m);
        board.readFrom(in);

        // ---------- 1️⃣ Find connected components (4‑directional) ----------
        int[][] visited = new int[n + 2][m + 2];
        Map<Integer, Integer> componentSize = new HashMap<>();

        int componentId = 1;
        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= m; j++) {
                if (visited[i][j] == 0 && board.isOpen(i, j)) {
                    int size = bfsSize(board, visited, componentId, i, j);
                    componentSize.put(componentId, size);
                    componentId++;
                }
            }
        }

        // ---------- 2️⃣ Build the output grid ----------
        for (int i = 1; i <= n; i++) {
            StringBuilder line = new StringBuilder();
            for (int j = 1; j <= m; j++) {
                if (board.isOpen(i, j)) {
                    line.append('.');
                    continue;
                }

                Set<Integer> neighbourIds = new HashSet<>();
                for (int di = -1; di <= 1; di++) {
                    for (int dj = -1; dj <= 1; dj++) {
                        if ((di == 0 && dj == 0) || Math.abs(di) + Math.abs(dj) != 1) {
                            continue; // only orthogonal neighbours
                        }
                        int ni = i + di;
                        int nj = j + dj;
                        if (board.isOpen(ni, nj)) {
                            int id = visited[ni][nj];
                            if (id != 0) neighbourIds.add(id);
                        }
                    }
                }

                int total = neighbourIds.stream()
                        .mapToInt(componentSize::get)
                        .sum() + 1;               // the current empty cell itself

                out.append(total == 0 ? '.' : Integer.toString(total % 10));
            }
            out.append('\n');
        }
    }

    /** Breadth‑first search that returns the size of the component starting at (sx,sy). */
    private static int bfsSize(Board board, int[][] visited, int id, int sx, int sy) {
        int size = 0;
        Deque<Cell> queue = new ArrayDeque<>();
        queue.addLast(new Cell(sx, sy));

        while (!queue.isEmpty()) {
            Cell cur = queue.removeFirst();
            int x = cur.x, y = cur.y;
            if (visited[x][y] != 0 || !board.isOpen(x, y)) continue;

            visited[x][y] = id;
            size++;

            // orthogonal moves only
            int[][] dirs = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};
            for (int[] d : dirs) {
                int nx = x + d[0];
                int ny = y + d[1];
                if (nx >= 1 && ny >= 1 && board.isOpen(nx, ny) && visited[nx][ny] == 0) {
                    queue.addLast(new Cell(nx, ny));
                }
            }
        }
        return size;
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.ArrayDeque;
import java.util.HashSet;
import java.util.Set;

/**
 * Reads a grid where '*' denotes an obstacle and '.' denotes free space.
 * For every obstacle cell it prints a digit representing the number of cells
 * reachable from its four orthogonal neighbours (including the obstacle
 * itself) modulo 10. Free cells are printed as '.'.
 *
 * The program is deliberately split into small, well‑named methods to aid
 * maintainability and readability.
 */
public class Main {

    /** Directions: down, up, right, left */
    private static final int[][] DIRS = {
            {1, 0}, {-1, 0}, {0, 1}, {0, -1}
    };

    /** Maximum possible component id = number of cells + 1 */
    private static final int MAX_ID = 1_000_000; // safe upper bound (will be overwritten)

    public static void main(String[] args) throws IOException {
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in))) {
            String[] header = br.readLine().split(" ");
            final int ROWS = Integer.parseInt(header[0]);
            final int COLS = Integer.parseInt(header[1]);

            boolean[][] blocked = readBlockedCells(br, ROWS, COLS);

            // Determine component id for each free cell and its size
            int[][] componentId = new int[ROWS][COLS];
            int[] componentSize = new int[ROWS * COLS + 1];
            int nextId = 1; // ids start from 1 (0 means “unvisited”)

            for (int r = 0; r < ROWS; r++) {
                for (int c = 0; c < COLS; c++) {
                    if (!blocked[r][c] && componentId[r][c] == 0) {
                        nextId++;
                        bfsAssignComponent(br, blocked, componentId, componentSize, nextId, r, c);
                    }
                }
            }

            // Produce output
            try (PrintWriter out = new PrintWriter(System.out, true)) {
                for (int r = 0; r < ROWS; r++) {
                    StringBuilder sb = new StringBuilder(COLS);
                    for (int c = 0; c < COLS; c++) {
                        if (blocked[r][c]) {
                            sb.append(computeDigit(r, c, blocked, componentId, componentSize));
                        } else {
                            sb.append('.');
                        }
                    }
                    out.println(sb);
                }
            }
        }
    }

    /** Reads the grid lines that describe blocked cells. */
    private static boolean[][] readBlockedCells(BufferedReader br,
                                                int rows,
                                                int cols) throws IOException {
        boolean[][] blocked = new boolean[rows][cols];
        for (int r = 0; r < rows; r++) {
            String line = br.readLine();
            for (int c = 0; c < cols; c++) {
                blocked[r][c] = line.charAt(c) == '*';
            }
        }
        return blocked;
    }

    /** Breadth‑first search that labels a connected component of free cells. */
    private static void bfsAssignComponent(BufferedReader br,
                                           boolean[][] blocked,
                                           int[][] componentId,
                                           int[] componentSize,
                                           int id,
                                           int startY,
                                           int startX) {
        ArrayDeque<int[]> queue = new ArrayDeque<>();
        queue.add(new int[]{startY, startX});
        componentId[startY][startX] = id;
        int size = 0;

        while (!queue.isEmpty()) {
            int[] cur = queue.removeFirst();
            int y = cur[0];
            int x = cur[1];
            size++;

            for (int[] d : DIRS) {
                int ny = y + d[0];
                int nx = x + d[1];
                if (isInside(ny, nx, blocked) && !blocked[ny][nx] && componentId[ny][nx] == 0) {
                    componentId[ny][nx] = id;
                    queue.add(new int[]{ny, nx});
                }
            }
        }
        componentSize[id] = size;
    }

    /** Returns true if coordinates are within the grid bounds. */
    private static boolean isInside(int y, int x, boolean[][] blocked) {
        return y >= 0 && y < blocked.length && x >= 0 && x < blocked[0].length;
    }

    /** Calculates the output digit for a blocked cell based on its orthogonal neighbours. */
    private static char computeDigit(int y, int x,
                                     boolean[][] blocked,
                                     int[][] componentId,
                                     int[] componentSize) {
        Set<Integer> neighbourIds = new HashSet<>();
        for (int[] d : DIRS) {
            int ny = y + d[0];
            int nx = x + d[1];
            if (isInside(ny, nx, blocked) && !blocked[ny][nx] && componentId[ny][nx] != 0) {
                neighbourIds.add(componentId[ny][nx]);
            }
        }
        int total = 1; // count the obstacle cell itself
        for (int id : neighbourIds) {
            total += componentSize[id];
        }
        return Character.forDigit(total % 10, 10);
    }
}

import java.io.BufferedReader;
