/**
 * Refactored version of the original program.
 *
 * <p>This version improves readability, separates concerns into small
 * helper methods, uses meaningful names and modern collection handling,
 * and eliminates the confusing auxiliary queues.</p>
 *
 * <p>The functionality remains identical to the original:</p>
 * <ul>
 *   <li>Read a grid of '.' (empty) and '*' (obstacle) characters.</li>
 *   <li>Label each connected component of '.' cells and store its size.</li>
 *   <li>For every '*' cell compute the sum of the sizes of the distinct
 *       neighboring components, take the sum modulo 10 and output that digit.</li>
 *   <li>All '.' cells are left unchanged in the output.</li>
 * </ul>
 */
public class CEdu52 {

    /** Character used for empty cells. */
    private static final char EMPTY = '.';

    /** Character used for obstacles. */
    private static final char OBSTACLE = '*';

    /** Character used to temporarily mark visited cells during BFS. */
    private static final char MARKED = '_';

    /** Four‑direction movement vectors. */
    private static final int[] DR = {1, -1, 0, 0};
    private static final int[] DC = {0, 0, 1, -1};

    public static void main(String[] args) throws IOException {
        /* -------------------------------------------------------------
         *  Input handling
         * ------------------------------------------------------------- */
        try (BufferedReader reader = new BufferedReader(
                new InputStreamReader(System.in));
             PrintWriter out = new PrintWriter(System.out)) {

            String[] firstLine = reader.readLine().split("\\s+");
            int rows = Integer.parseInt(firstLine[0]);
            int cols = Integer.parseInt(firstLine[1]);

            char[][] grid = new char[rows][];
            for (int r = 0; r < rows; r++) {
                grid[r] = reader.readLine().toCharArray();
            }

            /* -------------------------------------------------------------
             *  Component labeling
             * ------------------------------------------------------------- */
            int nextComponentId = 1;
            int[][] componentId = new int[rows][cols]; // 0 = not visited yet
            Map<Integer, Integer> componentSize = new HashMap<>();

            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (grid[r][c] == EMPTY && componentId[r][c] == 0) {
                        int size = bfs(grid, componentId, componentSize,
                                nextComponentId, r, c, rows, cols);
                        componentSize.put(nextComponentId, size);
                        nextComponentId++;
                    }
                }
            }

            /* -------------------------------------------------------------
             *  Build the result grid
             * ------------------------------------------------------------- */
            char[][] result = new char[rows][cols];
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (grid[r][c] == OBSTACLE) {
                        result[r][c] = computeObstacleValue(
                                grid, componentId, componentSize, r, c, rows, cols);
                    } else {
                        result[r][c] = EMPTY;
                    }
                }
            }

            /* -------------------------------------------------------------
             *  Output
             * ------------------------------------------------------------- */
            for (char[] row : result) {
                out.println(new String(row));
            }
        }
    }

    /**
     * Breadth‑first search that labels all cells of the current component
     * with {@code componentNumber} and returns the component's size.
     */
    private static int bfs(char[][] grid, int[][] componentId,
                           Map<Integer, Integer> componentSize,
                           int componentNumber, int startR, int startC,
                           int rows, int cols) {
        int size = 0;
        ArrayDeque<int[]> queue = new ArrayDeque<>();
        queue.add(new int[]{startR, startC});

        while (!queue.isEmpty()) {
            int[] cur = queue.pollFirst();
            int r = cur[0];
            int c = cur[1];

            // Skip already processed cells
            if (grid[r][c] != EMPTY || componentId[r][c] != 0) {
                continue;
            }

            componentId[r][c] = componentNumber;
            size++;

            // Explore neighbours
            for (int d = 0; d < 4; d++) {
                int nr = r + DR[d];
                int nc = c + DC[d];
                if (isInBounds(nr, rows) && isInBounds(nc, cols)
                        && grid[nr][nc] == EMPTY && componentId[nr][nc] == 0) {
                    queue.addLast(new int[]{nr, nc});
                }
            }
        }
        return size;
    }

    /**
     * Calculates the digit that must be printed for an obstacle cell.
     * The digit is the sum of the sizes of all distinct neighbouring
     * components, taken modulo 10.
     */
    private static char computeObstacleValue(char[][] grid, int[][] componentId,
                                             Map<Integer, Integer> componentSize,
                                             int r, int c, int rows, int cols) {
        Set<Integer> seenComponents = new HashSet<>();
        int sum = 1; // count the obstacle cell itself

        for (int d = 0; d < 4; d++) {
            int nr = r + DR[d];
            int nc = c + DC[d];
            if (!isInBounds(nr, rows) || !isInBounds(nc, cols)) {
                continue;
            }
            if (grid[nr][nc] == EMPTY) {
                int compId = componentId[nr][nc];
                if (compId != 0 && !seenComponents.contains(compId)) {
                    sum += componentSize.getOrDefault(compId, 0);
                    seenComponents.add(compId);
                }
            }
        }
        return Character.forDigit(sum % 10, 10);
    }

    /** Simple bounds check – keeps the original semantics. */
    private static boolean isInBounds(int index, int bound) {
        return index >= 0 && index < bound;
    }
}

import java.io.*;
import java.util.*;

/**
 * Refactored solution for the grid‑based puzzle.
 * <p>
 * The program is split into small, focused methods and uses
 * expressive naming, generics and proper resource handling.
 * </p>
 */
public class Solution {

    /** Four orthogonal movement vectors. */
    private static final int[][] DIRS = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};

    /** Checks whether a coordinate lies inside the grid. */
    private static boolean inBounds(int x, int y, int cols, int rows) {
        return x >= 0 && x < cols && y >= 0 && y < rows;
    }

    /**
     * Flood‑fills a connected component of walkable cells.
     *
     * @param id        unique identifier for the component,
     * @param sx        start column,
     * @param sy        start row,
     * @param block     matrix indicating blocked cells,
     * @param idMap     matrix storing component IDs,
     * @return size of the component.
     */
    private static int bfs(int id, int sx, int sy, boolean[][] block, int[][] idMap) {
        if (block[sy][sx]) {
            return 0;
        }
        if (idMap[sy][sx] >= 0 && idMap[sy][sx] != id) {
            return 0;
        }

        Deque<Integer> xQueue = new ArrayDeque<>();
        Deque<Integer> yQueue = new ArrayDeque<>();
        xQueue.addLast(sx);
        yQueue.addLast(sy);
        idMap[sy][sx] = id;

        int size = 1;
        while (!xQueue.isEmpty()) {
            int x = xQueue.pollFirst();
            int y = yQueue.pollFirst();

            for (int[] d : DIRS) {
                int nx = x + d[0];
                int ny = y + d[1];

                if (!inBounds(nx, ny, idMap[0].length, idMap.length)
                        || block[ny][nx]
                        || idMap[ny][nx] >= 0) {
                    continue;
                }

                idMap[ny][nx] = id;
                xQueue.addLast(nx);
                yQueue.addLast(ny);
                size++;
            }
        }
        return size;
    }

    /** Simple scanner that reads from {@code System.in}. */
    public static class Scanner implements Closeable {
        private final BufferedReader br;
        private StringTokenizer tok;

        public Scanner(InputStream is) {
            br = new BufferedReader(new InputStreamReader(is));
        }

        /** Ensures a non‑empty {@link StringTokenizer} is available. */
        private void ensureTokens() throws IOException {
            while (tok == null || !tok.hasMoreTokens()) {
                String line = br.readLine();
                if (line == null) {
                    return;
                }
                tok = new StringTokenizer(line);
            }
        }

        public String next() {
            ensureTokens();
            return tok.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        @Override
        public void close() {
            try {
                br.close();
            } catch (IOException ignored) {
            }
        }
    }

    /** Entry point of the program. */
    public static void main(String[] args) throws IOException {
        try (Scanner sc = new Scanner(System.in)) {
            int rows = sc.nextInt();
            int cols = sc.nextInt();

            boolean[][] block = new boolean[rows][cols];
            for (int y = 0; y < rows; y++) {
                String line = sc.next();
                for (int x = 0; x < cols; x++) {
                    block[y][x] = line.charAt(x) == '*';
                }
            }

            int[][] idMap = new int[rows][cols];
            Arrays.fill(idMap, -1);

            /** Component sizes indexed by component id. */
            List<Integer> componentSizes = new ArrayList<>();
            int componentId = 0;
            for (int y = 0; y < rows; y++) {
                for (int x = 0; x < cols; x++) {
                    if (!block[y][x] && idMap[y][x] < 0) {
                        componentSizes.add(bfs(componentId++, x, y, block, idMap));
                    }
                }
            }

            StringBuilder out = new StringBuilder();
            for (int y = 0; y < rows; y++) {
                for (int x = 0; x < cols; x++) {
                    if (!block[y][x]) {
                        out.append('.');
                        continue;
                    }

                    long answer = 1;
                    Set<Integer> seenIds = new HashSet<>();
                    for (int[] d : DIRS) {
                        int nx = x + d[0];
                        int ny = y + d[1];

                        if (!inBounds(nx, ny, cols, rows) || block[ny][nx]) {
                            continue;
                        }
                        int nid = idMap[ny][nx];
                        if (nid < 0 || seenIds.contains(nid)) {
                            continue;
                        }
                        seenIds.add(nid);
                        answer += componentSizes.get(nid);
                    }
                    out.append((char) ('0' + (int) (answer % 10)));
                }
                out.append('\n');
            }
            System.out.print(out);
        }
    }
}

import java.io.*;
