/**
 * Refactored version of the original «Educational5C» solution.
 * The program reads a grid, discovers connected components of '.' cells,
 * and prints for each '#' cell a digit representing the sum (mod 10)
 * of the sizes of adjacent distinct components, plus 1.
 * The output for each row starts from the 5‑th character, exactly as
 * the original implementation did.
 */
public class Educational5C {

    /** Maximum size used in the original code – kept only for backward compatibility. */
    private static final int MAX = 1005;

    /** Four possible movement directions (right, left, up, down). */
    private static final int[][] DIRECTIONS = {
            {0, 1},   // right
            {0, -1},  // left
            {-1, 0},  // up
            {1, 0}    // down
    };

    /** Simple container for component identifier and its size. */
    private static final class Component {
        final int id;      // component identifier
        final int size;    // number of '.' cells in the component

        Component(int id, int size) {
            this.id = id;
            this.size = size;
        }
    }

    public static void main(String[] args) throws IOException {
        /* --------------------------------------------------------------
         *  Input handling – try‑with‑resources guarantees proper closing.
         * -------------------------------------------------------------- */
        try (BufferedReader br = new BufferedReader(
                     new InputStreamReader(System.in));
             PrintWriter pw = new PrintWriter(
                     new OutputStreamWriter(System.out), true)) {

            // ----- 1. read dimensions (n, m) -----
            int[] dim = extractFirstNumbers(br);
            int n = dim[0];
            int m = dim[1];

            // ----- 2. read the grid -----
            char[][] grid = new char[n][];
            for (int i = 0; i < n; i++) {
                grid[i] = readNextLine(br).toCharArray();
            }

            // ----- 3. discover components of '.' cells -----
            int[][] componentId = new int[n][m];   // -1 = not part of a component
            int[] componentSize = new int[n * m];  // size per component (index = id)
            boolean[][] visited = new boolean[n][m];
            int componentCount = 0;

            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    if (grid[i][j] == '.' && !visited[i][j]) {
                        Component comp = exploreComponent(i, j, grid,
                                visited, componentId, componentSize);
                        componentCount = comp.id + 1; // next free identifier
                    }
                }
            }

            // ----- 4. build answer rows -----
            StringBuilder[] answerRows = new StringBuilder[n];
            for (int i = 0; i < n; i++) {
                answerRows[i] = new StringBuilder(m);
            }

            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    if (grid[i][j] == '.') {
                        answerRows[i].append('.');
                    } else {
                        int sum = 1;                     // base value
                        boolean[] seen = new boolean[componentCount];

                        for (int d = 0; d < DIRECTIONS.length; d++) {
                            int ni = i + DIRECTIONS[d][0];
                            int nj = j + DIRECTIONS[d][1];

                            if (isInside(ni, nj, n, m) && grid[ni][nj] == '.') {
                                int cid = componentId[ni][nj];
                                if (cid != -1 && !seen[cid]) {
                                    seen[cid] = true;
                                    sum += componentSize[cid];
                                }
                            }
                        }
                        answerRows[i].append((char) ('0' + (sum % 10)));
                    }
                }
                // Original program prints only the substring starting at index 4.
                String outputLine = answerRows[i].toString();
                pw.println(outputLine.substring(4));
            }
        }
    }

    /** Extracts the first sequence of digits from the given line, returning them as an int array. */
    private static int[] extractFirstNumbers(BufferedReader br) throws IOException {
        String line = br.readLine();
        List<Integer> numbers = new ArrayList<>();
        StringBuilder current = new StringBuilder();

        for (char ch : line.toCharArray()) {
            if (Character.isDigit(ch)) {
                current.append(ch);
            } else if (current.length() > 0) {
                numbers.add(Integer.parseInt(current.toString()));
                current.setLength(0);
            }
        }
        if (current.length() > 0) {
            numbers.add(Integer.parseInt(current.toString()));
        }
        return numbers.stream().mapToInt(Integer::intValue).toArray();
    }

    /** Reads the next non‑empty line from the reader. */
    private static String readNextLine(BufferedReader br) throws IOException {
        String line;
        do {
            line = br.readLine();
        } while (line == null && line.isEmpty());
        return line;
    }

    /** Depth‑first search (iterative) that marks a '.' component and records its size. */
    private static Component exploreComponent(int startX, int startY,
                                              char[][] grid,
                                              boolean[][] visited,
                                              int[][] componentId,
                                              int[] componentSize) {
        Deque<int[]> stack = new ArrayDeque<>();
        stack.push(new int[]{startX, startY});

        int currentId = componentSize.length; // next unused identifier
        int size = 0;

        while (!stack.isEmpty()) {
            int[] cur = stack.pop();
            int x = cur[0];
            int y = cur[1];

            if (visited[x][y]) {
                continue;
            }
            visited[x][y] = true;
            componentId[x][y] = currentId;
            size++;

            for (int[][] dir : DIRECTIONS) {
                int nx = x + dir[0];
                int ny = y + dir[1];
                if (isInside(nx, ny, grid.length, grid[0].length)
                        && grid[nx][ny] == '.' && !visited[nx][ny]) {
                    stack.push(new int[]{nx, ny});
                }
            }
        }

        componentSize[currentId] = size;
        return new Component(currentId, size);
    }

    /** Checks whether the given coordinates lie inside the grid. */
    private static boolean isInside(int i, int j, int rows, int cols) {
        return i >= 0 && i < rows && j >= 0 && j < cols;
    }
}

import java.io.*;
import java.util.*;

/**
 * Entry point of the application.
 * Reads input, runs the solver and prints the result.
 */
public class Main {

    public static void main(String[] args) throws IOException {
        // Use try‑with‑resources to guarantee streams are closed.
        try (InputStream in = System.in;
             OutputStream out = System.out) {

            InputReader reader = new InputReader(in);
            PrintWriter writer = new PrintWriter(out);
            new Solver().solve(reader, writer);
        }
    }

    /**
     * Simple wrapper around a {@link BufferedReader} that can
     * tokenise input lines.
     */
    static class InputReader {
        private final BufferedReader br;
        private StringTokenizer tokenizer;

        InputReader(InputStream stream) {
            br = new BufferedReader(new InputStreamReader(stream));
        }

        /** Returns the next token (word) from the input stream. */
        String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    throw new UncheckedIOException(e);
                }
            }
            return tokenizer.nextToken();
        }

        /** Convenience method for reading an {@code int}. */
        int nextInt() {
            return Integer.parseInt(next());
        }
    }

    /**
     * Core algorithm for problem "C".
     * The class is deliberately stateless apart from the data
     * needed for the current test case.
     */
    static class Solver {

        /** Four‑direction vectors: up, left, down, right. */
        private static final int[][] DIRS = {
                {-1, 0},   // up
                {0, -1},   // left
                {1, 0},    // down
                {0, 1}     // right
        };

        private char[][] grid;          // original grid
        private int rows, cols;         // dimensions
        private int[][] componentId;    // component index for each '.' cell
        private int[] componentSize;    // size of each component
        private int componentCount;     // number of distinct components

        /** Solves the problem using the supplied input & output streams. */
        void solve(InputReader reader, PrintWriter out) {
            // ----- 1️⃣ Read input -------------------------------------------------
            rows = reader.nextInt();
            cols = reader.nextInt();

            grid = new char[rows];
            for (int r = 0; r < rows; ++r) {
                grid[r] = reader.next().toCharArray();
            }

            // ----- 2️⃣ Prepare auxiliary data structures -------------------------
            prepareDataStructures();

            // ----- 3️⃣ Label all empty ('.') components -------------------------
            labelComponents();

            // ----- 4️⃣ Build the answer grid --------------------------------------
            char[][] answer = copyGrid();

            boolean[] visited = new boolean[componentCount];
            for (int r = 0; r < rows; ++r) {
                for (int c = 0; c < cols; ++c) {
                    if (grid[r][c] == '*') {
                        answer[r][c] = computeStarValue(r, c, visited);
                    }
                }
            }

            // ----- 5️⃣ Output -------------------------------------------------------
            for (char[] row : answer) {
                out.println(new String(row));
            }
        }

        /** Initializes mutable arrays used throughout the algorithm. */
        private void prepareDataStructures() {
            componentId = new int[rows][cols];
            componentSize = new int[rows * cols];
            Arrays.fill(componentId, -1);
        }

        /** Assigns a component id to each '.' cell using DFS. */
        private void labelComponents() {
            componentCount = 0;
            for (int r = 0; r < rows; ++r) {
                for (int c = 0; c < cols; ++c) {
                    if (grid[r][c] == '.' && componentId[r][c] == -1) {
                        floodFill(r, c);
                        ++componentCount;
                    }
                }
            }
        }

        /** Recursive depth‑first search that labels a connected component. */
        private void floodFill(int r, int c) {
            componentId[r][c] = componentCount;
            componentSize[componentCount]++;

            for (int[][] dir : DIRS) {
                int nr = r + dir[0];
                int nc = c + dir[1];
                if (inside(nr, nc) && grid[nr][nc] == '.' && componentId[nr][nc] == -1) {
                    floodFill(nr, nc);
                }
            }
        }

        /** Returns true when (r, c) is inside the rectangular grid. */
        private boolean inside(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }

        /** Produces a shallow copy of the original grid (so we can overwrite '*'). */
        private char[][] copyGrid() {
            char[][] copy = new char[rows][];
            for (int r = 0; r < rows; ++r) {
                copy[r] = grid[r].clone();
            }
            return copy;
        }

        /**
         * Computes the numeric value for a '*' cell.
         * The value equals 1 plus the sum of sizes of distinct adjacent components.
         */
        private char computeStarValue(int r, int c, boolean[] visited) {
            int value = 1;
            // Gather adjacent component ids
            for (int[][] dir : DIRS) {
                int nr = r + dir[0];
                int nc = c + dir[1];
                if (inside(nr, nc) && grid[nr][nc] == '.') {
                    int comp = componentId[nr][nc];
                    if (!visited[comp]) {
                        visited[comp] = true;
                        value += componentSize[comp];
                    }
                }
            }

            // Reset visited flags for the next '*' cell
            for (int[][] dir : DIRS) {
                int nr = r + dir[0];
                int nc = c + dir[1];
                if (inside(nr, nc) && grid[nr][nc] == '.') {
                    visited[componentId[nr][nc]] = false;
                }
            }

            return (char) ('0' + (value % 10));
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Refactored Labyrinth solver.
 *
 * <p>This version separates the algorithmic steps into well‑named methods, uses
 * expressive variable names, and avoids raw index gymnastics by employing a
 * directional array.  The code follows a clear flow:
 *
 * <ol>
 *   <li>Read the grid dimensions and the grid itself.</li>
 *   <li>Discover all vacant regions (components) and store their sizes.</li>
 *   <li>Replace each rock ('*') with a digit that represents the total size of
 *       adjacent vacant components.</li>
 * </ol>
 *
 * The implementation is intentionally kept simple and self‑contained so that
 * it can be compiled and run without any external dependencies.
 */
public class Labyrinth {

    /** Directions used for exploring neighbours (up, down, left, right). */
    private static final int[] DX = {-1, 1, 0, 0};
    private static final int[] DY = {0, 0, -1, 1};

    public static void main(String[] args) throws IOException {
        /* --------------------------------------------------------------
         * 1️⃣  Input handling
         * -------------------------------------------------------------- */
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(System.in))) {
            // First line: n m
            String[] header = reader.readLine().trim().split("\\s+");
            int rows = Integer.parseInt(header[0]);
            int cols = Integer.parseInt(header[1]);

            // Remaining lines: the grid
            char[][] grid = new char[rows][];
            for (int r = 0; r < rows; r++) {
                grid[r] = reader.readLine().trim().toCharArray();
            }

            /* --------------------------------------------------------------
             * 2️⃣  Component discovery (BFS/DFS over '.' cells)
             * -------------------------------------------------------------- */
            int[][] componentId = new int[rows][cols];   // 0 = not visited yet
            List<Integer> componentSize = new ArrayList<>();

            int nextComponentId = 0;
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (grid[r][c] == '*' || componentId[r][c] != 0) {
                        continue; // skip rocks and already visited cells
                    }
                    int id = nextComponentId++; // unique (0‑based) component identifier
                    int size = exploreComponent(grid, componentId, r, c, id);
                    componentSize.add(size);
                }
            }

            /* --------------------------------------------------------------
             * 3️⃣  Build the output – replace each rock with a digit
             * -------------------------------------------------------------- */
            StringBuilder output = new StringBuilder();
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    char cell = grid[r][c];
                    if (cell == '.') {
                        output.append('.');                 // vacant cells stay unchanged
                    } else { // cell == '*'
                        Set<Integer> neighbourComponentIds = collectNeighbourComponentIds(
                                grid, componentId, r, c, rows, cols);

                        long totalSize = 1; // count the current rock itself
                        for (int compIdx : neighbourComponentIds) {
                            totalSize += componentSize.get(compIdx);
                        }
                        output.append((char) ('0' + (int) (totalSize % 10)));
                    }
                }
                output.append('\n');
            }

            System.out.print(output);
        }
    }

    /**
     * Explores a single vacant region using an explicit stack (DFS).  All cells
     * belonging to the same region receive the same {@code id} (stored as
     * {@code id+1} to distinguish from the sentinel value 0).
     *
     * @return the number of cells in the explored component
     */
    private static int exploreComponent(char[][] grid, int[][] componentId,
                                        int startRow, int startCol, int id) {
        Deque<Integer> stack = new ArrayDeque<>();
        stack.push(startRow * grid[0].length + startCol);
        componentId[startRow][startCol] = id + 1; // mark as visited
        int size = 0;

        while (!stack.isEmpty()) {
            int linearIdx = stack.pop();
            int r = linearIdx / grid[0].length;
            int c = linearIdx % grid[0].length;
            size++;

            for (int d = 0; d < 4; d++) {
                int nr = r + DX[d];
                int nc = c + DY[d];
                if (!inBounds(nr, nc, grid.length, grid[0].length)) {
                    continue;
                }
                if (grid[nr][nc] == '.' && componentId[nr][nc] == 0) {
                    componentId[nr][nc] = id + 1;
                    stack.push(nr * grid[0].length + nc);
                }
            }
        }
        return size;
    }

    /**
     * Gathers the component identifiers of all adjacent '.' cells surrounding
     * the given position.  Duplicates are eliminated with a {@link Set}.
     *
     * @return a set of zero‑based component indices that touch the cell
     */
    private static Set<Integer> collectNeighbourComponentIds(char[][] grid,
                                                              int[][] componentId,
                                                              int row, int col,
                                                              int rows, int cols) {
        Set<Integer> ids = new HashSet<>();
        for (int d = 0; d < 4; d++) {
            int nr = row + DX[d];
            int nc = col + DY[d];
            if (!inBounds(nr, nc, rows, cols)) {
                continue;
            }
            if (grid[nr][nc] == '.' && componentId[nr][nc] != 0) {
                // componentId is stored as id+1, so subtract 1 to get the original index
                ids.add(componentId[nr][nc] - 1);
            }
        }
        return ids;
    }

    /** Helper to test array bounds. */
    private static boolean inBounds(int x, int y, int maxX, int maxY) {
        return x >= 0 && x < maxX && y >= 0 && y < maxY;
    }
}

