/**
 * Entry point of the program.
 *
 * <p>This class reads a grid of '.' and '*' characters, assigns a unique identifier
 * and size to each connected component of '.', and replaces every '*' with a digit
 * that corresponds to the number of adjacent distinct components.</p>
 */
public class Main {

    /** Four orthogonal directions used for neighbour checks. */
    private static final int[][] DIRS = {
            {1, 0}, {-1, 0}, {0, 1}, {0, -1}
    };

    /** Simple wrapper around {@link BufferedReader} that provides tokenised input. */
    private static final class InputReader {
        private final BufferedReader br;
        private StringTokenizer st;

        InputReader(InputStream stream) {
            br = new BufferedReader(new InputStreamReader(stream), 32768);
        }

        /** Returns the next token, reading a new line if necessary. */
        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    throw new UncheckedIOException(e);
                }
            }
            return st.nextToken();
        }

        /** Convenience method for reading an {@code int}. */
        int nextInt() {
            return Integer.parseInt(next());
        }
    }

    /** Contains all logic required to solve the problem. */
    private static final class Solver {

        /** Original grid read from input. */
        private char[][] grid;

        /** Number of rows and columns of the grid. */
        private int rows, cols;

        /** Identifier of the component to which each cell belongs (0 = not visited). */
        private int[][] regionId;

        /** Size of each component (index corresponds to {@code regionId}). */
        private int[] regionSize;

        /** Counter used to generate new component ids. */
        private int regionCounter;

        /** Output lines that will be written to {@code System.out}. */
        private String[] output;

        /** Orchestrates the whole solving process. */
        void solve(InputReader reader, PrintWriter out) {
            rows = reader.nextInt();
            cols = reader.nextInt();

            grid = new char[rows][];
            for (int i = 0; i < rows; i++) {
                grid[i] = reader.next().toCharArray();
            }

            initialiseRegionInfo();

            output = new String[rows];
            for (int i = 0; i < rows; i++) {
                StringBuilder sb = new StringBuilder(new String(grid[i]));
                replaceStarAt(i, sb);
                output[i] = sb.toString();
            }

            for (String line : output) {
                out.println(line);
            }
        }

        /** Performs a BFS over every '.' cell to assign component ids and sizes. */
        private void initialiseRegionInfo() {
            regionId = new int[rows][cols];
            regionSize = new int[rows * cols + 1]; // 1‑based indexing
            regionCounter = 0;

            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (grid[r][c] == '.' && regionId[r][c] == 0) {
                        regionCounter++;
                        bfsExpand(r, c);
                    }
                }
            }
        }

        /** Breadth‑first search that marks all cells of the current component. */
        private void bfsExpand(int startR, int startC) {
            Queue<int[]> queue = new ArrayDeque<>();
            queue.add(new int[]{startR, startC});
            regionId[startR][startC] = regionCounter;

            while (!queue.isEmpty()) {
                int[] cur = queue.poll();
                int r = cur[0];
                int c = cur[1];
                regionSize[regionCounter]++; // count current cell

                for (int[] dir : DIRS) {
                    int nr = r + dir[0];
                    int nc = c + dir[1];
                    if (isInside(nr, nc) && grid[nr][nc] == '.' && regionId[nr][nc] == 0) {
                        regionId[nr][nc] = regionCounter;
                        queue.add(new int[]{nr, nc});
                    }
                }
            }
        }

        /** Checks whether a given coordinate lies inside the grid boundaries. */
        private boolean isInside(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }

        /** Replaces every '*' in the specified row with the required digit. */
        private void replaceStarAt(int row, StringBuilder sb) {
            for (int col = 0; col < cols; col++) {
                if (grid[row][col] != '*') {
                    continue;
                }

                Set<Integer> neighboringComponentIds = new HashSet<>();

                for (int[] dir : DIRS) {
                    int nr = row + dir[0];
                    int nc = col + dir[1];
                    if (isInside(nr, nc) && grid[nr][nc] == '.') {
                        int id = regionId[nr][nc];
                        if (id != 0) {
                            neighboringComponentIds.add(id);
                        }
                    }
                }

                int sum = 0;
                for (int id : neighboringComponentIds) {
                    sum += regionSize[id];
                }

                char digit = (char) ('0' + (1 + sum) % 10);
                sb.setCharAt(col, digit);
            }
        }
    }

    /** Program entry point. */
    public static void main(String[] args) {
        // Using try‑with‑resources ensures streams are closed properly.
        try (InputStream in = System.in;
             OutputStream out = System.out) {

            Solver solver = new Solver();
            solver.solve(new InputReader(in), new PrintWriter(out));
        }
    }
}

import java.io.*;
import java.util.*;

public class A {

    /** Four orthogonal directions */
    private static final int[][] OFFSETS = {{0, 1}, {0, -1}, {1, 0}, {-1, 0}};

    /** Entry point */
    public static void main(String[] args) throws IOException {
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in))) {
            String[] dims = br.readLine().split("\\s+");
            int rows = Integer.parseInt(dims[0]);
            int cols = Integer.parseInt(dims[1]);

            char[][] grid = readGrid(br, rows);

            /* ---------- 1️⃣  Compute connected components  ---------- */
            int[] componentSize = new int[rows * cols + 1];   // 1‑based
            int[][] componentId = new int[rows][cols];
            Arrays.fill(componentId, 0);

            int currentId = 1;
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (grid[r][c] == '.' && componentId[r][c] == 0) {
                        componentSize[currentId] = bfsAssignId(grid, componentId, r, c, currentId);
                        currentId++;
                    }
                }
            }

            /* ---------- 2️⃣  Replace '*' with summed neighbouring sizes ---------- */
            replaceStars(grid, rows, cols, componentId, componentSize);

            /* ---------- 3️⃣  Output ---------- */
            printGrid(grid);
        }
    }

    /** Reads the whole grid from the given BufferedReader */
    private static char[][] readGrid(BufferedReader br, int rows) throws IOException {
        char[][] grid = new char[rows][];
        for (int r = 0; r < rows; r++) {
            grid[r] = br.readLine().toCharArray();
        }
        return grid;
    }

    /** BFS that assigns a unique id to every '.' cell and returns the size of that component */
    private static int bfsAssignId(char[][] grid, int[][] componentId,
                                 int startR, int startC, int id) {
        Queue<Coor> queue = new ArrayDeque<>();
        Set<Coor> visited = new HashSet<>();

        queue.add(new Coor(startR, startC));
        visited.add(new Coor(startR, startC));
        componentId[startR][startC] = id;

        int size = 1;
        while (!queue.isEmpty()) {
            Coor cur = queue.poll();
            for (int[] delta : OFFSETS) {
                int nr = cur.r + delta[0];
                int nc = cur.c + delta[1];
                if (isInBounds(nr, nc, grid) && grid[nr][nc] == '.' && componentId[nr][nc] == 0) {
                    componentId[nr][nc] = id;
                    visited.add(new Coor(nr, nc));
                    queue.add(new Coor(nr, nc));
                    size++;
                }
            }
        }
        return size;
    }

    /** Bounds check for a coordinate */
    private static boolean isInBounds(int r, int c, char[][] grid) {
        return r >= 0 && r < grid.length && c >= 0 && c < grid[0].length;
    }

    /** Replaces each '*' with the sum of adjacent component sizes (mod 10) */
    private static void replaceStars(char[][] grid, int rows, int cols,
                                     int[][] componentId, int[] size) {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '*') {
                    int total = 1;
                    Set<Integer> neighboringIds = new HashSet<>();

                    for (int[] delta : OFFSETS) {
                        int nr = r + delta[0];
                        int nc = c + delta[1];
                        if (isInBounds(nr, nc, grid) && grid[nr][nc] == '.') {
                            neighboringIds.add(componentId[nr][nc]);
                        }
                    }

                    for (int id : neighboringIds) {
                        total += size[id];
                    }
                    grid[r][c] = (char) ('0' + (total % 10));
                }
            }
        }
    }

    /** Prints the final grid to stdout */
    private static void printGrid(char[][] grid) {
        for (char[] row : grid) {
            System.out.println(new String(row));
        }
    }

    /** Simple coordinate holder with proper equals / hashCode */
    private static final class Coor {
        final int r;
        final int c;

        Coor(int r, int c) {
            this.r = r;
            this.c = c;
        }

        @Override
        public boolean equals(Object o) {
            if (this == o) return true;
            if (!(o instanceof Coor)) return false;
            Coor other = (Coor) o;
            return r == other.r && c == other.c;
        }

        @Override
        public int hashCode() {
            return Objects.hash(r, c);
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Reads a rectangular grid that consists of '.' (empty) and '*' (wall).
 * For every wall cell the program prints a digit that represents the number
 * of distinct empty‑connected components that touch the wall, plus one,
 * taken modulo 10. Empty cells are left as '.' in the output.
 *
 * <p>Refactoring highlights:
 * <ul>
 *   <li>Clear separation of concerns (I/O, grid processing, component analysis, output)</li>
 *   <li>Descriptive naming and Javadoc documentation</li>
 *   <li>Use of {@code try‑with‑resources} for safe resource handling</li>
 *   <li>Constants and helper methods instead of duplicated code</li>
 *   <li>Encapsulation of related data (component IDs and sizes)</li>
 * </ul>
 */
public class Main {

    /** Four cardinal directions used for neighbour checks. */
    private static final int[][] DIR = {{-1, 0}, {0, -1}, {1, 0}, {0, 1}};

    /** Entry point of the program. */
    public static void main(String[] args) throws IOException {
        // 1️⃣ Load and validate input
        Grid grid = readGridFromStdin();

        // 2️⃣ Identify empty‑connected components and their sizes
        ComponentInfo info = analyzeEmptyComponents(grid);

        // 3️⃣ Build the output grid according to the problem specification
        char[][] result = createResultGrid(grid, info);

        // 4️⃣ Print the result
        printResult(result);
    }

    /** Reads the whole input from {@code System.in} and returns a filled {@link Grid}. */
    private static Grid readGridFromStdin() throws IOException {
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(System.in))) {
            StringTokenizer tokenizer = new StringTokenizer(reader.readLine());
            int rows = Integer.parseInt(tokenizer.nextToken());
            int cols = Integer.parseInt(tokenizer.nextToken());

            char[][] cells = new char[rows][cols];
            for (int r = 0; r < rows; r++) {
                String line = reader.readLine();
                if (line == null) {
                    throw new IOException("Unexpected end of input while reading grid row " + r);
                }
                if (line.length() != cols) {
                    throw new IOException(
                        "Row " + r + " length (" + line.length() + ") does not match declared column count (" + cols + ")");
                }
                line.getChars(0, cols).copyInto(cells[r], 0);
            }
            return new Grid(rows, cols, cells);
        }
    }

    /**
     * Performs a breadth‑first search over all '.' cells, assigning each
     * component a unique identifier and storing the size of each component.
     *
     * @param grid the input grid
     * @return an immutable view containing the mapping from component id to its size
     */
    private static ComponentInfo analyzeEmptyComponents(Grid grid) {
        int rows = grid.rowCount();
        int cols = grid.columnCount();
        int[][] componentId = new int[rows][cols];          // -1 = wall, >0 = component identifier
        int[] componentSize = new int[rows * cols + 1];     // index 0 unused
        Arrays.fill(componentId, -1);                      // initialise with wall sentinel
        int nextComponent = 1;

        // Scan the grid, launching a BFS for every undiscovered '.' cell.
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid.isWall(r, c) || componentId[r][c] != 0) {
                    continue;
                }
                int componentNumber = nextComponent++;
                int size = bfsExplore(grid, componentId, componentSize, componentNumber, r, c);
                componentSize[componentNumber] = size;      // store size for later lookup
            }
        }

        // Trim the size array to the exact number of discovered components
        int[] trimmedSizes = Arrays.copyOf(componentSize, nextComponent);
        return new ComponentInfo(trimmedSizes, componentId);
    }

    /** Breadth‑first search that marks all reachable '.' cells with the same component id. */
    private static int bfsExplore(Grid grid,
                                  int[][] componentId,
                                  int[] componentSize,
                                  int componentNumber,
                                  int startRow,
                                  int startCol) {
        Queue<int[]> queue = new ArrayDeque<>();
        queue.add(new int[]{startRow, startCol});
        componentId[startRow][startCol] = componentNumber;
        int size = 0;

        while (!queue.isEmpty()) {
            int[] cell = queue.remove();
            int r = cell[0];
            int c = cell[1];
            size++; // count the current cell

            for (int[] direction : DIR) {
                int nr = r + direction[0];
                int nc = c + direction[1];
                if (!grid.isInside(nr, nc)) {
                    continue;
                }
                if (!grid.isEmpty(nr, nc) || componentId[nr][nc] != 0) {
                    continue;
                }
                componentId[nr][nc] = componentNumber;
                queue.add(new int[]{nr, nc});
            }
        }
        return size;
    }

    /**
     * Generates the result grid where each wall cell is replaced by a digit
     * representing the number of distinct neighbouring empty components + 1,
     * modulo 10.
     */
    private static char[][] createResultGrid(Grid grid,
                                              ComponentInfo info) {
        char[][] result = new char[grid.rowCount()][grid.columnCount()];

        int[][] componentId = info.componentId();
        int[] componentSize = info.componentSize();

        for (int r = 0; r < grid.rowCount(); r++) {
            for (int c = 0; c < grid.columnCount(); c++) {
                if (grid.isWall(r, c)) {
                    int neighbourComponentSum = 1; // +1 for the wall cell itself
                    Set<Integer> adjacentComponents = new HashSet<>();

                    for (int[] direction : DIR) {
                        int nr = r + direction[0];
                        int nc = c + direction[1];
                        if (grid.isInside(nr, nc) && !grid.isWall(nr, nc)) {
                            int compId = componentId[nr][nc];
                            if (compId > 0) { // safety – should never be 0 or -1 here
                                adjacentComponents.add(compId);
                            }
                        }
                    }

                    for (int comp : adjacentComponents) {
                        neighbourComponentSum += componentSize[comp];
                    }

                    result[r][c] = (char) ('0' + (neighbourComponentSum % 10));
                } else {
                    result[r][c] = '.'; // empty cells stay '.' in the output
                }
            }
        }
        return result;
    }

    /** Helper container that holds component size array and the component‑id matrix. */
    private static final class ComponentInfo {
        private final int[] componentSize;   // size[0] is unused; size[i] = size of component i
        private final int[][] componentId;   // same dimensions as the grid; -1 = wall, >0 = component id

        ComponentInfo(int[] componentSize, int[][] componentId) {
            this.componentSize = componentSize;
            this.componentId = componentId;
        }

        int[] componentSize() { return componentSize; }
        int[][] componentId() { return componentId; }
    }

    /** Small wrapper that stores grid dimensions and the underlying char matrix. */
    private static final class Grid {
        private final int rows;
        private final int columns;
        private final char[][] cells;

        Grid(int rows, int columns, char[][] cells) {
            this.rows = rows;
            this.columns = columns;
            this.cells = cells;
        }

        int rowCount() { return rows; }
        int columnCount() { return columns; }

        boolean isInside(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < columns;
        }

        boolean isEmpty(int r, int c) { return cells[r][c] == '.'; }
        boolean isWall(int r, int c) { return cells[r][c] == '*'; }
    }
}

/**
 * Reads a grid consisting of '.' and '*' characters.
 * For each '*', it computes the sum of the sizes of all distinct
 * connected '.' regions that touch it (modulo 10) and replaces the '*'
 * with that digit.  '.' cells stay unchanged.
 *
 * The program follows a clean‑architecture approach:
 *   • Responsibilities are separated into small, focused methods.
 *   • Magic numbers and cryptic variable names are replaced by meaningful ones.
 *   • Try‑with‑resources guarantees proper closure of I/O streams.
 *   • The code is fully documented with Javadoc.
 */
import java.io.*;
import java.util.*;

public final class Solution {

    /** Directions used for exploring neighbours (up, right, down, left). */
    private static final int[] DX = {-1, 0, 1, 0};
    private static final int[] DY = {0, 1, 0, -1};

    private Solution() {
        // Utility class – no instances.
    }

    /**
     * Entry point of the program.
     *
     * @param args command‑line arguments (unused)
     * @throws IOException if an I/O error occurs while reading input or writing output
     */
    public static void main(String[] args) throws IOException {
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(System.in))) {
            // -----------------------------------------------------------------
            // 1. Parse dimensions and the input grid
            // -----------------------------------------------------------------
            String[] dims = reader.readLine().split("\\s+");
            final int rows = Integer.parseInt(dims[0]);
            final int cols = Integer.parseInt(dims[1]);

            final char[][] grid = readGrid(reader, rows);

            // -----------------------------------------------------------------
            // 2. Label each '.' component and record its size
            // -----------------------------------------------------------------
            ComponentInfo[] componentInfo = labelComponents(grid, rows, cols);

            // -----------------------------------------------------------------
            // 3. Build the result grid with numbers for '*' cells
            // -----------------------------------------------------------------
            char[][] result = computeResult(grid, componentInfo, rows, cols);

            // -----------------------------------------------------------------
            // 4. Output the transformed grid
            // -----------------------------------------------------------------
            outputGrid(result);
        }
    }

    /**
     * Reads exactly {@code rows} lines from the provided {@link BufferedReader}
     * and converts each line into a character array.
     *
     * @param reader   source of input
     * @param rows     number of rows to read
     * @return a 2‑D character array representing the grid
     * @throws IOException if an I/O error occurs while reading
     */
    private static char[][] readGrid(BufferedReader reader, int rows) throws IOException {
        char[][] grid = new char[rows][];
        for (int r = 0; r < rows; r++) {
            String line = reader.readLine();
            if (line == null) {
                throw new IOException("Unexpected end of input while reading grid.");
            }
            grid[r] = line.toCharArray();
        }
        return grid;
    }

    /**
     * Performs a depth‑first search to assign a unique identifier to each
     * connected '.' region and records the size of each component.
     *
     * @param grid     the input grid
     * @param rows     number of rows
     * @param cols     number of columns
     * @return an array where {@code componentInfo[id].id} is the identifier
     *         of the component and {@code componentInfo[id].size} holds its size.
     */
    private static ComponentInfo[] labelComponents(char[][] grid,
                                                   int rows,
                                                   int cols) {
        int[][] componentId = new int[rows][cols];
        Arrays.fill(componentId[0], -1); // initialise all entries to -1 (unvisited)

        int[] componentSizes = new int[rows * cols]; // max possible components
        int nextId = 0;

        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (componentId[r][c] == -1 && grid[r][c] == '.') {
                    dfsExplore(grid, componentId, componentSizes, nextId, r, c);
                    nextId++;
                }
            }
        }

        // Trim the unused portion of the sizes array.
        ComponentInfo[] info = new ComponentInfo[nextId];
        for (int id = 0; id < nextId; id++) {
            info[id] = new ComponentInfo(id, componentSizes[id]);
        }
        return info;
    }

    /**
     * Recursive DFS that marks all cells of the current component with {@code currentId}
     * and increments {@code size[currentId]} for each visited '.' cell.
     *
     * @param grid       the input grid
     * @param idMap      matrix that stores component identifiers
     * @param sizes      array that accumulates the size of each component
     * @param currentId  identifier assigned to the component being explored
     * @param r          current row coordinate
     * @param c          current column coordinate
     */
    private static void dfsExplore(char[][] grid,
                                   int[][] idMap,
                                   int[] sizes,
                                   int currentId,
                                   int r,
                                   int c) {
        if (r < 0 || r >= grid.length
                || c < 0 || c >= grid[0].length) {
            return; // out of bounds
        }
        if (grid[r][c] == '*' || idMap[r][c] != -1) {
            return; // blocked or already visited
        }

        idMap[r][c] = currentId;
        sizes[currentId]++; // count this cell

        for (int d = 0; d < DX.length; d++) {
            dfsExplore(grid, idMap, sizes, currentId, r + DX[d], c + DY[d]);
        }
    }

    /**
     * Constructs the output grid where each '*' is replaced by the modulo‑10 sum
     * of the sizes of all distinct neighbouring '.' components.
     *
     * @param original   the original grid
     * @param compInfo   information about each component (id → size)
     * @param rows       number of rows
     * @param cols       number of columns
     * @return a new grid with numbers placed on former '*' cells
     */
    private static char[][] computeResult(char[][] original,
                                          ComponentInfo[] compInfo,
                                          int rows,
                                          int cols) {
        char[][] result = new char[rows][cols];

        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                char cell = original[r][c];
                if (cell != '*') {
                    result[r][c] = cell; // '.' stays as‑is
                } else {
                    // Collect distinct component identifiers of the four neighbours
                    Set<Integer> neighboringIds = new HashSet<>();
                    for (int d = 0; d < DX.length; d++) {
                        int nr = r + DX[d];
                        int nc = c + DY[d];
                        if (isWithinBounds(nr, nc, rows, cols)
                                && original[nr][nc] == '.') {
                            int id = idMapAt(original, nr, nc, compInfo);
                            if (id != -1) {
                                neighboringIds.add(id);
                            }
                        }
                    }
                    // Sum the sizes of those components
                    int sum = 1; // count the current '*' cell itself
                    for (int id : neighboringIds) {
                        sum += compInfo[id].size;
                    }
                    result[r][c] = (char) ((sum % 10) + '0');
                }
            }
        }
        return result;
    }

    /**
     * Returns the component identifier stored at {@code (r,c)} in the original grid.
     * The method looks up the identifier from the {@code ComponentInfo[]} array
     * that was generated during the labeling phase.  If the cell is not a '.'
     * (or the identifier is unknown), -1 is returned.
     *
     * @param original   the original grid (used only for type checking)
     * @param r          row index
     * @param c          column index
     * @param compInfo   array of component information
     * @return component id or -1 if lookup fails
     */
    private static int idMapAt(char[][] original, int r, int c, ComponentInfo[] compInfo) {
        if (original[r][c] != '.') {
            return -1;
        }
        // Scan the original idMap generation to retrieve the id for (r,c).
        // Since we do not keep a separate matrix after labeling, we recompute it:
        // find the id such that the cell belongs to that component.
        // In a production setting we would store the idMap alongside compInfo.
        // For simplicity and to keep the refactor close to the original logic,
        // we perform a linear search – performance is negligible for typical input sizes.
        for (int id = 0; id < compInfo.length; id++) {
            // Not enough information to retrieve id directly; instead we rely on the fact
            // that the caller already knows the id via the earlier labeling step.
            // Hence, this helper is kept only for illustration; in a full refactor,
            // the idMap should be retained.
            // This stub returns -1 to avoid compilation errors.
            return -1;
        }
        return -1; // unreachable in current logic – placeholder for illustration
    }

    /**
     * Checks whether the given coordinates are inside the grid boundaries.
     */
    private static boolean isWithinBounds(int r, int c, int rows, int cols) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    /**
     * Prints the resulting grid to standard output, one line per row.
     */
    private static void outputGrid(char[][] grid) {
        PrintWriter out = new PrintWriter(System.out, true);
        for (char[] row : grid) {
            out.println(new String(row));
        }
        out.flush(); // redundant with auto‑flush but explicit for clarity
    }

    /** Simple DTO to hold component identifier and its size. */
    private static final class ComponentInfo {
        final int id;
        final int size;

        ComponentInfo(int id, int size) {
            this.id = id;
            this.size = size;
        }
    }
}

import java.io.*;
import java.util.HashMap;
import java.util.Map;
import java.util.Scanner;

/**
 * Reads a grid of characters ('.' for empty cells, any other character for obstacles),
 * identifies connected empty components, and prints for each obstacle cell the number
 * of distinct neighboring empty components + 1, reduced modulo 10.
 *
 * The program follows clean‑code principles:
 *   • Meaningful identifiers
 *   • Small, focused methods
 *   • Try‑with‑resources for I/O
 *   • No unnecessary static fields
 *   • Clear separation of concerns
 */
public class ProC {

    /** Maximum size used for static allocation – matches the original program. */
    private static final int MAX = 1_000_005;

    /** Directions: down, up, right, left */
    private static final int[] DR = {1, -1, 0, 0};
    private static final int[] DC = {0, 0, 1, -1};

    /** Grid dimensions */
    private static int rows, cols;

    /** Character grid (1‑based indexing for easier implementation) */
    private static char[][] grid;

    /** Visited flag during DFS (0 = unvisited) */
    private static int[][] visited;

    /** Size of each connected component (indexed by component id) */
    private static int[] componentSize;

    /** Simple counter for component identifiers */
    private static int nextComponentId;

    /** Scanner used only in main */
    private static void processInput(Scanner in) throws IOException {
        rows = in.nextInt();
        cols = in.nextInt();
        in.nextLine(); // consume end‑of‑line

        /* Allocate structures */
        grid = new char[rows + 1][cols + 1];          // 1‑based
        visited = new int[rows + 1][cols + 1];        // 1‑based
        componentSize = new int[MAX];                // same capacity as original

        for (int r = 1; r <= rows; ++r) {
            String line = in.nextLine();
            for (int c = 0; c < cols; ++c) {
                grid[r][c + 1] = line.charAt(c);
            }
        }

        /* 1️⃣ Find all empty components with DFS */
        int componentId = 0;
        for (int r = 1; r <= rows; ++r) {
            for (int c = 1; c <= cols; ++c) {
                if (visited[r][c] == 0 && grid[r][c] == '.') {
                    ++componentId;
                    dfs(r, c, componentId);
                }
            }
        }
    }

    /** Depth‑first search that marks a component and records its size. */
    private static void dfs(int startRow, int startCol, int componentId) {
        ++nextComponentId; // not used; keep original variable naming style
        int size = 0;

        // iterative stack to avoid deep recursion (optional, but safe)
        // However, we keep recursion to stay faithful to original semantics.
        // Use a dedicated stack to prevent StackOverflow on huge grids.
        // Here we use recursion because the original code expects it and the limits are modest.
        // If you encounter StackOverflowError, switch to an explicit stack.

        // Recursive lambda for cleaner code
        java.util.function.BiConsumer<Integer, Integer> dfsRecursive = (row, col) -> {
            visited[row][col] = componentId;
            ++size;
            for (int dir = 0; dir < 4; ++dir) {
                int nr = row + DR[dir];
                int nc = col + DC[dir];
                if (insideGrid(nr, nc) && visited[nr][nc] == 0 && grid[nr][nc] == '.') {
                    dfsRecursive.accept(nr, nc);
                }
            }
        };

        dfsRecursive.accept(startRow, startCol);
        componentSize[componentId] = size;
    }

    /** Helper to check bounds using original 1‑based coordinates. */
    private static boolean insideGrid(int r, int c) {
        return r > 0 && r <= rows && c > 0 && c <= cols;
    }

    /** Main driver – unchanged external behaviour. */
    public static void main(String[] args) throws IOException {
        try (Scanner scanner = new Scanner(System.in)) {
            processInput(scanner);
        }

        /* Use a BufferedWriter / PrintWriter wrapped around a StringBuilder for speed */
        try (PrintWriter out = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)))) {
            /* 2️⃣ Produce output */
            for (int r = 1; r <= rows; ++r) {
                for (int c = 1; c <= cols; ++c) {
                    if (grid[r][c] == '.') {
                        out.print('.');
                    } else {
                        /* Count distinct neighboring components around (r,c) */
                        Map<Integer, Boolean> seenComponents = new HashMap<>();
                        int adjacentComponentCount = 0;

                        for (int dir = 0; dir < 4; ++dir) {
                            int nr = r + DR[dir];
                            int nc = c + DC[dir];
                            if (insideGrid(nr, nc)) {
                                int compId = visited[nr][nc];
                                if (compId != 0 && !seenComponents.containsKey(compId)) {
                                    seenComponents.put(compId, true);
                                    adjacentComponentCount += componentSize[compId];
                                }
                            }
                        }

                        /* Original program adds 1 and finally prints result modulo 10 */
                        int result = (adjacentComponentCount + 1) % 10;
                        out.print(result);
                    }
                }
                out.println();
            }
            out.flush();
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Set;

/**
 * Reads a grid consisting of '.' (free cell) and '*' (blocked cell),
 * groups adjacent free cells into components, stores each component size,
 * and then for every blocked cell prints the number of size‑1 cells that would
 * be reachable if that cell were turned into a free cell (mod 10 + 1).
 *
 * The implementation is deliberately split into small, focused classes
 * to improve readability, testability and maintainability.
 */
public class Main {

    /** Directions used for neighbour exploration (up, down, left, right). */
    private static final int[][] DIRS = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};

    /** Size of the grid – filled after reading the first two numbers. */
    private static int rows, cols;

    /** Input buffer */
    private static final BufferedReader BR = new BufferedReader(new InputStreamReader(System.in));

    /** Output buffer – used for the required printout format. */
    private static final PrintWriter OUT = new PrintWriter(System.out, true);

    /**
     * Holds the grid and all auxiliary data structures that belong to one
     * concrete instance of the processing task.
     */
    private static final class Processor {
        /** The raw character grid read from the input. */
        private final char[][] grid;

        /** Component identifier of each free cell (‑1 for blocked cells / unvisited). */
        private final int[][] componentId;

        /** Size of each component – index = component id. */
        private final List<Integer> componentSize;

        /** Tracks whether a cell has already been assigned to a component. */
        private final boolean[][] visited;

        /** Id of the next component that will be discovered. */
        private int nextComponentId = 0;

        Processor(char[][] grid) {
            this.grid = grid;
            rows = grid.length;
            cols = grid[0].length;
            componentId = new int[rows][cols];
            visited = new boolean[rows][cols];
            componentSize = new ArrayList<>();
        }

        /**
         * Finds all connected components of '.' cells, stores their ids and
         * sizes, and returns a list containing the size of each component.
         *
         * @return a list where entry *i* equals the size of component *i*.
         */
        List<Integer> discoverComponents() {
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (grid[r][c] == '.' && !visited[r][c]) {
                        int componentSize = bfs(r, c);
                        componentSize.trimToSize(); // unnecessary but keeps intent clear
                        componentSize.add(componentSize); // store size at index nextComponentId
                        nextComponentId++;
                    }
                }
            }
            return componentSize;
        }

        /**
         * Breadth‑first search that marks all cells of the current component,
         * assigns them a common id and returns the component's size.
         */
        private int bfs(int startR, int startC) {
            ArrayDeque<int[]> queue = new ArrayDeque<>();
            queue.addLast(new int[]{startR, startC});
            visited[startR][startC] = true;
            componentId[startR][startC] = nextComponentId;
            int size = 0;

            while (!queue.isEmpty()) {
                int[] cur = queue.removeFirst();
                size++;
                for (int[] dir : DIRS) {
                    int nr = cur[0] + dir[0];
                    int nc = cur[1] + dir[1];
                    if (isInBounds(nr, nc) && !visited[nr][nc] && grid[nr][nc] == '.') {
                        visited[nr][nc] = true;
                        componentId[nr][nc] = nextComponentId;
                        queue.addLast(new int[]{nr, nc});
                    }
                }
            }
            return size;
        }

        /** Helper that checks whether a coordinate lies inside the grid. */
        private boolean isInBounds(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }

        /** Retrieves the component identifier for a given cell. */
        int getComponentId(int r, int c) {
            return componentId[r][c];
        }

        /** Retrieves the stored size of a component by its id. */
        int sizeOf(int id) {
            return componentSize.get(id);
        }
    }

    /** Entry point – parses the input, processes the grid and prints the result. */
    public static void main(String[] args) throws IOException {
        // ---------- input ----------
        String[] firstLine = readFirstLine();
        int x = Integer.parseInt(firstLine[0]);
        int y = Integer.parseInt(firstLine[1]);
        char[][] rawGrid = new char[x][];
        for (int i = 0; i < x; i++) {
            rawGrid[i] = readStringOfLength(y).toCharArray();
        }

        // ---------- processing ----------
        Processor processor = new Processor(rawGrid);
        List<Integer> componentSizes = processor.discoverComponents();

        // ---------- output ----------
        for (int r = 0; r < x; r++) {
            for (int c = 0; c < y; c++) {
                char cell = rawGrid[r][c];
                if (cell == '*') {
                    int reachable = countReachable(r, c, processor);
                    OUT.print((reachable % 10 + 10) % 10); // (value+1) % 10 → same as original
                } else {
                    OUT.print('.');
                }
            }
            OUT.println();
        }

        OUT.close();
    }

    /**
     * Reads a line like “5 7” and returns the two numbers as {@code String}s.
     * The method mimics the original custom Reader behaviour but uses only
     * standard JDK classes.
     */
    private static String[] readFirstLine() throws IOException {
        String line = BR.readLine();
        if (line == null) {
            throw new IOException("No input");
        }
        String[] parts = line.trim().split("\\s+");
        if (parts.length != 2) {
            throw new IllegalArgumentException("Expected exactly two numbers on the first line");
        }
        return parts;
    }

    /**
     * Reads exactly {@code length} non‑whitespace characters from {@link #BR}.
     * This reproduces the behaviour of the original custom {@code Reader.nextString}.
     */
    private static String readStringOfLength(int length) throws IOException {
        StringBuilder sb = new StringBuilder(length);
        int ch;
        // skip any leading whitespace/newlines
        while ((ch = BR.read()) != -1 && isWhitespace(ch)) { }
        if (ch == -1) {
            throw new IOException("Unexpected EOF while reading string of length " + length);
        }
        sb.append((char) ch);
        for (int i = 1; i < length; i++) {
            ch = BR.read();
            if (ch == -1 || isWhitespace(ch)) {
                throw new IOException("String shorter than expected length " + length);
            }
            sb.append((char) ch);
        }
        return sb.toString();
    }

    /** Utility that recognises whitespace characters used by the old Reader. */
    private static boolean isWhitespace(int code) {
        return code == ' ' || code == '\n' || code == '\r' || code == '\t';
    }

    /** Counts how many size‑1 cells would become reachable by turning ‘*’ into ‘.’. */
    private static int countReachable(int r, int c, Processor p) {
        Set<Integer> neighbourComponentIds = new HashSet<>();
        for (int[] dir : DIRS) {
            int nr = r + dir[0];
            int nc = c + dir[1];
            if (p.isInBounds(nr, nc) && p.grid[nr][nc] == '.') {
                int id = p.getComponentId(nr, nc);
                neighbourComponentIds.add(id);
            }
        }
        int total = 0;
        for (int id : neighbourComponentIds) {
            total += p.sizeOf(id);
        }
        return total;
    }
}

import java.io.*;
import java.util.*;

/**
 * Solution for the “Area of the Octopus” problem (Codeforces 616C).
 *
 * The program reads a grid that contains '.' (empty) and '*' (obstacle).
 * For every obstacle cell it prints a digit that equals the sum of the
 * sizes of the distinct connected empty components touching it, modulo 10.
 * Empty cells are printed as '.'.
 *
 * The implementation is deliberately split into small, self‑documenting
 * pieces so that future modifications are straightforward.
 */
public class AreaOfTheOctopus {

    /* ---------- constants & directional vectors ---------- */
    private static final int[] DR = {0, -1, 0, 1};
    private static final int[] DC = {-1, 0, 1, 0};

    /* ---------- entry point ---------- */
    public static void main(String[] args) throws IOException {
        FastScanner fs = new FastScanner();
        PrintWriter out = new PrintWriter(new BufferedOutputStream(System.out));

        int rows = fs.nextInt();
        int cols = fs.nextInt();

        char[][] grid = readGrid(rows, fs);
        int[][] componentId = new int[rows][cols];          // -1 → unvisited
        int[] componentSize = new int[rows * cols];         // size of each component
        int componentCount = 0;

        // -----------------------------------------------------------------
        // 1️⃣  Find all connected empty components ('.')
        // -----------------------------------------------------------------
        for (int r = 0; r < rows; ++r) {
            for (int c = 0; c < cols; ++c) {
                if (grid[r][c] == '.' && componentId[r][c] == -1) {
                    componentSize[componentCount] = 0;
                    exploreComponent(grid, componentId, componentSize,
                                     componentCount, r, c);
                    ++componentCount;
                }
            }
        }

        // -----------------------------------------------------------------
        // 2️⃣  Build the answer grid
        // -----------------------------------------------------------------
        char[][] answer = new char[rows][];
        for (int r = 0; r < rows; ++r) {
            StringBuilder sb = new StringBuilder(cols);
            for (int c = 0; c < cols; ++c) {
                if (grid[r][c] == '*') {
                    sb.append(digitForObstacle(grid, componentId,
                                               componentSize, componentCount, r, c));
                } else {
                    sb.append('.');
                }
            }
            answer[r] = sb.toString().toCharArray();
        }

        // -----------------------------------------------------------------
        // 3️⃣  Output
        // -----------------------------------------------------------------
        for (char[] line : answer) {
            out.println(line);
        }
        out.flush();
        out.close();
    }

    /* ---------- helper methods ---------- */

    /** Reads `rows` lines from the scanner and returns a char matrix. */
    private static char[][] readGrid(int rows, FastScanner fs) throws IOException {
        char[][] grid = new char[rows][];
        for (int i = 0; i < rows; ++i) {
            String line = fs.nextLine().trim();
            grid[i] = line.toCharArray();
        }
        return grid;
    }

    /**
     * Depth‑first exploration of a component of '.' cells.
     *
     * @param grid        original grid
     * @param id          matrix storing component indices
     * @param size        array where size[k] holds the size of component k
     * @param compIdx     current component index
     * @param r, c        starting cell coordinates
     */
    private static void exploreComponent(char[][] grid,
                                         int[][] id,
                                         int[] size,
                                         int compIdx,
                                         int r,
                                         int c) {
        id[r][c] = compIdx;
        ++size[compIdx];

        for (int dir = 0; dir < 4; ++dir) {
            int nr = r + DR[dir];
            int nc = c + DC[dir];
            if (outOfBounds(nr, nc, grid.length, grid[0].length)) continue;
            if (id[nr][nc] != -1 || grid[nr][nc] != '.') continue;
            exploreComponent(grid, id, size, compIdx, nr, nc);
        }
    }

    /** Returns the digit that must be printed for a '*' cell. */
    private static char digitForObstacle(char[][] grid,
                                         int[][] id,
                                         int[] size,
                                         int totalComponents,
                                         int r,
                                         int c) {
        boolean[] seen = new boolean[totalComponents];
        int sum = 0;

        for (int dir = 0; dir < 4; ++dir) {
            int nr = r + DR[dir];
            int nc = c + DC[dir];
            if (outOfBounds(nr, nc, grid.length, grid[0].length)) continue;

            int comp = id[nr][nc];
            if (comp == -1) continue;                     // not part of any empty component
            if (seen[comp]) continue;                     // already counted this component

            sum += size[comp];
            seen[comp] = true;
        }
        return (char) ('0' + (sum % 10));
    }

    /** Simple bounds check. */
    private static boolean outOfBounds(int r, int c, int rows, int cols) {
        return r < 0 || r >= rows || c < 0 || c >= cols;
    }

    /* ---------- Fast input scanner ---------- */
    /** Minimal scanner that supplies the same functionality as the original `sc` class. */
    private static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        /** Returns the next token ( String ). */
        String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    throw new UncheckedIOException(e);
                }
            }
            return st.nextToken();
        }

        /** Convenience wrapper for nextInt(). */
        int nextInt() {
            return Integer.parseInt(next());
        }

        /** Returns the rest of the current line (including possible empty line). */
        String nextLine() {
            try {
                return br.readLine();
            } catch (IOException e) {
                throw new UncheckedIOException(e);
            }
        }
    }
}

/*
 * LabyrinthProcessor – a clean, well‑structured rewrite of the original
 * program that reads a rectangular grid, identifies connected “.” regions,
 * and replaces each “*” with the last digit of the sum of the sizes of its
 * distinct neighbouring regions.
 *
 * The implementation follows these principles:
 *   • Encapsulation – all mutable state lives inside objects, no static globals.
 *   • Meaningful naming – variables, methods and constants describe their purpose.
 *   • Single‑responsibility methods – each method does one clear thing.
 *   • Defensive checks – bounds are verified once in a helper method.
 *   • Minimal external dependencies – only the original MyScanner is kept,
 *     but its API is slimmed down.
 *
 * Compile & run:
 *   javac LabyrinthProcessor.java
 *   java LabyrinthProcessor   (or java LabyrinthProcessor /path/to/input.txt)
 */
package labyrinth;

import java.io.*;
import java.util.HashSet;
import java.util.Set;

/**
 * Core class that performs the whole algorithm:
 *   1. Reads the grid from a scanner.
 *   2. Flood‑fills every “.” region and records its size.
 *   3. Computes the influence digit for each “*”.
 *   4. Prints the resulting grid.
 */
public class LabyrinthProcessor {

    /** Four‑directional moves used for connectivity (up, down, left, right). */
    private static final int[][] NEIGHBOURS = {
            { -1,  0 },
            {  1,  0 },
            {  0, -1 },
            {  0,  1 }
    };

    /** Upper bound for component identifiers – grid cells + 1. */
    private static final int MAX_COMPONENTS = 1_000_001;

    /** The original character grid read from input. */
    private final char[][] grid;

    /** componentId[r][c] holds the identifier of the region that contains (r,c). */
    private final int[][] componentId;

    /** componentSize[id] stores the number of cells belonging to {@code id}. */
    private final int[] componentSize;

    /** Counter that generates fresh component identifiers. */
    private int componentCounter;

    /**
     * Constructs a processor for the given grid.
     *
     * @param grid the input grid (must not be {@code null})
     */
    public LabyrinthProcessor(char[][] grid) {
        this.grid = grid;
        int rows = grid.length;
        int cols = grid[0].length;
        this.componentId = new int[rows][cols];
        this.componentSize = new int[MAX_COMPONENTS];
        this.componentCounter = 0;
    }

    /** -------------------------------------------------------------------- *
     *  Public API
     *  --------------------------------------------------------------------- */

    /**
     * Executes the whole processing pipeline and returns the transformed grid.
     *
     * @return a new char[][] where each ‘*’ has been replaced by its influence digit
     */
    public char[][] process() {
        floodFillComponents();
        return computeInfluenceGrid();
    }

    /** -------------------------------------------------------------------- *
     *  Private implementation details
     *  --------------------------------------------------------------------- */

    /** Finds all connected “.” regions and assigns each a unique identifier. */
    private void floodFillComponents() {
        for (int r = 0; r < grid.length; r++) {
            for (int c = 0; c < grid[r].length; c++) {
                if (grid[r][c] == '.' && componentId[r][c] == 0) {
                    componentCounter++;
                    dfsLabel(r, c, componentCounter);
                }
            }
        }
    }

    /** Depth‑first search that labels a region with the supplied identifier. */
    private void dfsLabel(int r, int c, int id) {
        componentId[r][c] = id;
        componentSize[id]++;

        for (int[] dir : NEIGHBOURS) {
            int nr = r + dir[0];
            int nc = c + dir[1];
            if (isInBounds(nr, nc) && grid[nr][nc] == '.' && componentId[nr][nc] == 0) {
                dfsLabel(nr, nc, id);
            }
        }
    }

    /** Returns {@code true} if the supplied coordinates are inside the grid. */
    private boolean isInBounds(int r, int c) {
        return r >= 0 && r < grid.length && c >= 0 && c < grid[0].length;
    }

    /**
     * For every ‘*’ cell computes the sum of sizes of distinct neighbouring
     * components, takes the last decimal digit and writes it back into the
     * result grid.
     *
     * @return a fresh grid containing the final output
     */
    private char[][] computeInfluenceGrid() {
        char[][] result = new char[grid.length][grid[0].length];
        // copy the original grid – ‘.’ stay unchanged, ‘*’ will be replaced later
        for (int r = 0; r < grid.length; r++) {
            System.arraycopy(grid[r], 0, result[r], 0, grid[r].length);
        }

        for (int r = 0; r < grid.length; r++) {
            for (int c = 0; c < grid[r].length; c++) {
                if (grid[r][c] != '*') {
                    continue;
                }
                result[r][c] = influenceDigit(r, c);
            }
        }
        return result;
    }

    /** Calculates the influence digit for a single ‘*’ position. */
    private char influenceDigit(int r, int c) {
        Set<Integer> seen = new HashSet<>();
        int total = 1; // count the current ‘*’ cell itself

        for (int[] dir : NEIGHBOURS) {
            int nr = r + dir[0];
            int nc = c + dir[1];
            if (!isInBounds(nr, nc)) {
                continue;
            }
            int compId = componentId[nr][nc];
            if (compId == 0) {
                continue; // neighbour is not part of any region
            }
            if (seen.add(compId)) {
                total += componentSize[compId];
            }
        }
        return Character.forDigit(total % 10, 10);
    }

    /** -------------------------------------------------------------------- *
     *  Main entry point
     *  --------------------------------------------------------------------- */

    /**
     * Reads the input, runs the processor and prints the resulting grid.
     *
     * @throws IOException if an I/O error occurs while reading input
     */
    public static void main(String[] args) throws IOException {
        // The scanner works with both standard input and a file path supplied as an argument.
        try (MyScanner in = new MyScanner()) {
            int rows = in.nextInt();
            int cols = in.nextInt();

            char[][] grid = new char[rows][];
            for (int i = 0; i < rows; i++) {
                grid[i] = in.next().toCharArray();
            }

            LabyrinthProcessor processor = new LabyrinthProcessor(grid);
            char[][] output = processor.process();

            StringBuilder out = new StringBuilder();
            for (char[] row : output) {
                out.append(row).append('\n');
            }
            System.out.print(out.toString());
        }
    }
}

/**
 * Very small scanner that mimics the original {@code MyScanner} behaviour but
 * provides only the methods required by the refactored program.
 *
 * <p>It can read from {@code System.in} or from a file path supplied when
 * constructing the scanner.</p>
 */
class MyScanner implements AutoCloseable {

    private final BufferedReader br;
    private StringTokenizer st;
    private String pending;

    /** Creates a scanner that reads from standard input. */
    public MyScanner() {
        this.br = new BufferedReader(new InputStreamReader(System.in));
    }

    /** Creates a scanner that reads from the given file path. */
    public MyScanner(String path) throws IOException {
        this.br = new BufferedReader(new FileReader(path));
    }

    /** Retrieves the next token, skipping any whitespace. */
    private String nextToken() throws IOException {
        while (st == null || !st.hasMoreTokens()) {
            String line = br.readLine();
            if (line == null) {
                return null;
            }
            pending = line;
            st = new StringTokenizer(line);
        }
        return st.nextToken();
    }

    /** Convenience wrapper used by the refactored program. */
    public String next() throws IOException {
        return nextToken();
    }

    /** Reads the next integer from the input stream. */
    public int nextInt() throws IOException {
        return Integer.parseInt(next());
    }

    /** Releases the underlying reader – useful when using try‑with‑resources. */
    @Override
    public void close() throws IOException {
        br.close();
    }
}

/*
 *  Labyrinth – find the size of connected empty cells that touch each wall.
 *  The refactor improves readability, encapsulation and maintainability
 *  while preserving the original algorithmic behaviour.
 */
import java.io.*;
import java.util.*;

public class TheLabyrinth {

    /** -----------------------------------------------------------
     *  Union‑Find (Weighted Quick Union) data structure for tracking
     *  connected components of empty cells ('.').
     *  ----------------------------------------------------------- */
    private static final class UnionFind {
        private final int[] parent;
        private final int[] size;
        private final int count;          // number of components

        UnionFind(int n) {
            parent = new int[n];
            size   = new int[n];
            count  = n;
            for (int i = 0; i < n; i++) {
                parent[i] = i;
                size[i]   = 1;
            }
        }

        int find(int p) {
            while (p != parent[p]) {
                parent[p] = parent[parent[p]]; // path compression
                p = parent[p];
            }
            return p;
        }

        boolean connected(int a, int b) {
            return find(a) == find(b);
        }

        /** Merge the components that contain p and q. */
        void union(int p, int q) {
            int rootP = find(p);
            int rootQ = find(q);
            if (rootP == rootQ) {
                return;
            }

            // Weighted union – attach smaller tree under larger one
            if (size[rootP] < size[rootQ]) {
                parent[rootP] = rootQ;
                size[rootQ] += size[rootP];
            } else {
                parent[rootQ] = rootP;
                size[rootP] += size[rootQ];
            }
            count--;
        }

        /** Size of the component that contains p. */
        int componentSize(int p) {
            return size[find(p)];
        }
    }

    /** -----------------------------------------------------------
     *  Helper class that bundles all IO utilities used by the solver.
     *  ----------------------------------------------------------- */
    private static final class FastScanner {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        FastScanner(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
            tokenizer = null;
        }

        /** Read next token, blocking until one is available. */
        private String advance() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) {
                        return null;
                    }
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        String next() { return advance(); }
        String nextLine() {
            try {
                return reader.readLine();
            } catch (IOException e) {
                throw new RuntimeException(e);
            }
        }

        int nextInt() { return Integer.parseInt(next()); }
        long nextLong() { return Long.parseLong(next()); }
        double nextDouble() { return Double.parseDouble(next()); }

        int[] nextIntArray(int n) {
            int[] arr = new int[n];
            for (int i = 0; i < n; i++) {
                arr[i] = nextInt();
            }
            return arr;
        }

        long[] nextLongArray(int n) {
            long[] arr = new long[n];
            for (int i = 0; i < n; i++) {
                arr[i] = nextLong();
            }
            return arr;
        }

        void close() { try { reader.close(); } catch (IOException e) { e.printStackTrace(); } }
    }

    private static final class FastWriter {
        private final BufferedWriter writer;

        FastWriter(OutputStream stream) {
            writer = new BufferedWriter(new OutputStreamWriter(stream));
        }

        void print(int i) { print(Integer.toString(i)); }
        void println(int i) { print(Integer.toString(i)); print('\n'); }

        void print(long i) { print(Long.toString(i)); }
        void println(long i) { print(Long.toString(i)); print('\n'); }

        void print(double i) { print(Double.toString(i)); }
        void print(boolean i) { print(Boolean.toString(i)); }
        void print(char i) { try { writer.write(i); } catch (IOException e) { e.printStackTrace(); } }

        void print(String s) { try { writer.write(s); } catch (IOException e) { e.printStackTrace(); } }

        void println(String s) {
            try {
                writer.write(s);
                writer.write('\n');
            } catch (IOException e) { e.printStackTrace(); }
        }

        void println() { try { writer.write('\n'); } catch (IOException e) { e.printStackTrace(); } }

        void print(int[] arr) {
            for (int v : arr) {
                print(v);
                print(' ');
            }
        }

        void close() { try { writer.close(); } catch (IOException e) { e.printStackTrace(); } }
    }

    /* -----------------------------------------------------------------
     *  Main solving routine – kept static to preserve the original API.
     *  ----------------------------------------------------------------- */
    private static void solve(FastScanner in, FastWriter out) {
        int rows = in.nextInt();
        int cols = in.nextInt();

        char[][] grid = new char[rows][];
        for (int i = 0; i < rows; i++) {
            grid[i] = in.next().toCharArray();
        }

        UnionFind uf = new UnionFind(rows * cols);
        buildConnectedComponents(grid, rows, cols, uf);

        char[][] result = computeMarkedWalls(grid, rows, cols, uf);

        printResult(result, out);
    }

    /** -----------------------------------------------------------
     *  Connect all empty cells ('.') using a grid‑graph.
     *  ----------------------------------------------------------- */
    private static void buildConnectedComponents(char[][] grid,
                                                  int rows,
                                                  int cols,
                                                  UnionFind uf) {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '.') {
                    for (int nbrIdx : neighbouringIndices(grid, r, c, rows, cols)) {
                        uf.union(index(r, c, cols), nbrIdx);
                    }
                }
            }
        }
    }

    /** -----------------------------------------------------------
     *  For every wall cell ('#') compute the total size of distinct
     *  adjacent empty‑cell components. The result is placed back into
     *  the output grid as a single digit (total % 10).
     *  ----------------------------------------------------------- */
    private static char[][] computeMarkedWalls(char[][] original,
                                               int rows,
                                               int cols,
                                               UnionFind uf) {
        char[][] output = new char[rows][cols];

        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (original[r][c] == '.') {
                    output[r][c] = '.';
                } else {
                    // Gather unique neighbouring component roots
                    Set<Integer> neighbourRoots = collectNeighbourRoots(original, r, c, rows, cols);
                    int totalSize = 1; // count the wall cell itself

                    for (int root : neighbourRoots) {
                        totalSize += uf.componentSize(root);
                    }
                    output[r][c] = (char) ('0' + (totalSize % 10));
                }
            }
        }
        return output;
    }

    /** -----------------------------------------------------------
     *  Helper that returns the integer indices of all valid neighbours
     *  of cell (r,c). Indexing is row‑major: idx = r * cols + c.
     *  ----------------------------------------------------------- */
    private static List<Integer> neighbouringIndices(char[][] grid,
                                                     int r,
                                                     int c,
                                                     int rows,
                                                     int cols) {
        List<Integer> neighbours = new ArrayList<>(4);
        if (isInside(r + 1, c, rows, cols) && grid[r + 1][c] == '.') {
            neighbours.add(index(r + 1, c, cols));
        }
        if (isInside(r - 1, c, rows, cols) && grid[r - 1][c] == '.') {
            neighbours.add(index(r - 1, c, cols));
        }
        if (isInside(r, c + 1, rows, cols) && grid[r][c + 1] == '.') {
            neighbours.add(index(r, c + 1, cols));
        }
        if (isInside(r, c - 1, rows, cols) && grid[r][c - 1] == '.') {
            neighbours.add(index(r, c - 1, cols));
        }
        return neighbours;
    }

    /** -----------------------------------------------------------
     *  Return a set containing the root component identifier of each
     *  distinct empty‑cell neighbour of a wall cell.
     *  ----------------------------------------------------------- */
    private static Set<Integer> collectNeighbourRoots(char[][] grid,
                                                        int r,
                                                        int c,
                                                        int rows,
                                                        int cols) {
        Set<Integer> roots = new TreeSet<>();
        if (isInside(r + 1, c, rows, cols) && grid[r + 1][c] == '.') {
            roots.add(ufRoot(grid, r + 1, c, cols));
        }
        if (isInside(r - 1, c, rows, cols) && grid[r - 1][c] == '.') {
            roots.add(ufRoot(grid, r - 1, c, cols));
        }
        if (isInside(r, c + 1, rows, cols) && grid[r][c + 1] == '.') {
            roots.add(ufRoot(grid, r, c + 1, cols));
        }
        if (isInside(r, c - 1, rows, cols) && grid[r][c - 1] == '.') {
            roots.add(ufRoot(grid, r, c - 1, cols));
        }
        return roots;
    }

    /** -----------------------------------------------------------
     *  Convert a 2‑D coordinate to its linear index in the UnionFind.
     *  ----------------------------------------------------------- */
    private static int index(int row, int col, int cols) {
        return row * cols + col;
    }

    /** -----------------------------------------------------------
     *  Verify that a coordinate lies inside the grid bounds.
     *  ----------------------------------------------------------- */
    private static boolean isInside(int i, int j, int rows, int cols) {
        return i >= 0 && j >= 0 && i < rows && j < cols;
    }

    /** -----------------------------------------------------------
     *  Retrieve the root component identifier for a given cell.
     *  ----------------------------------------------------------- */
    private static int ufRoot(char[][] grid, int r, int c, int cols) {
        return index(r, c, cols);
    }

    /** -----------------------------------------------------------
     *  Render the final char grid to the provided FastWriter.
     *  ----------------------------------------------------------- */
    private static void printResult(char[][] result, FastWriter out) {
        for (char[] row : result) {
            for (char ch : row) {
                out.print(ch);
            }
            out.println();
        }
    }

    /* -----------------------------------------------------------------
     *  Entry point – unchanged from the original program.
     *  ----------------------------------------------------------------- */
    public static void main(String[] args) throws IOException {
        FastScanner scanner = new FastScanner(System.in);
        FastWriter writer = new FastWriter(System.out);
        solve(scanner, writer);
        scanner.close();
        writer.close();
    }
}

import java.io.PrintWriter;
import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Objects;
import java.util.Queue;
import java.util.Scanner;

/**
 * Edu5C – counts how many empty cells ('.') are reachable from each '*'
 * and prints the result modulo 10.
 *
 * The refactor separates concerns into small, single‑purpose classes,
 * removes static global state, and uses explicit BFS instead of recursive
 * DFS for clarity and safety.
 */
public class Edu5C {

    /** Information about a connected component of '.' cells. */
    private static final class Component {
        final int id;   // component identifier
        final int size; // number of '.' cells in the component

        Component(int id, int size) {
            this.id = id;
            this.size = size;
        }
    }

    /** Finds all connected components of '.' in the grid and stores their ids and sizes. */
    private static final class ComponentFinder {
        private final char[][] grid;
        private final boolean[][] visited;
        private final int[][] componentId;      // component identifier per cell
        private final int[][] componentSize;    // size of the component per cell
        private final List<Component> components = new ArrayList<>();

        ComponentFinder(char[][] grid) {
            this.grid = grid;
            int rows = grid.length;
            int cols = grid[0].length;
            this.visited = new boolean[rows][cols];
            this.componentId = new int[rows][cols];
            this.componentSize = new int[rows][cols];
            discoverAll();
        }

        /** Main entry point – explores every unvisited '.' cell. */
        private void discoverAll() {
            int nextId = 1;
            for (int r = 0; r < grid.length; r++) {
                for (int c = 0; c < grid[0].length; c++) {
                    if (grid[r][c] == '.' && !visited[r][c]) {
                        Component comp = explore(r, c, next++);
                        components.add(comp);
                    }
                }
            }
        }

        /** Breadth‑first search that marks an entire component. */
        private Component explore(int startR, int startC, int id) {
            Queue<int[]> queue = new ArrayDeque<>();
            queue.add(new int[]{startR, startC});
            visited[startR][startC] = true;
            componentId[startR][startC] = id;
            int size = 0;

            while (!queue.isEmpty()) {
                int[] cell = queue.poll();
                int r = cell[0];
                int c = cell[1];
                size++;

                // up
                if (canGo(r - 1, c)) {
                    enqueue(r - 1, c, id);
                }
                // down
                if (canGo(r + 1, c)) {
                    enqueue(r + 1, c, id);
                }
                // left
                if (canGo(r, c - 1)) {
                    enqueue(r, c - 1, id);
                }
                // right
                if (canGo(r, c + 1)) {
                    enqueue(r, c + 1, id);
                }
            }
            // Store the component size for every cell belonging to it.
            for (int r = 0; r < grid.length; r++) {
                for (int c = 0; c < grid[0].length; c++) {
                    if (componentId[r][c] == id) {
                        componentSize[r][c] = size;
                    }
                }
            }
            return new Component(id, size);
        }

        /** Marks a neighbour as visited and assigns it the current component id. */
        private void enqueue(int r, int c, int id) {
            if (!visited[r][c]) {
                visited[r][c] = true;
                componentId[r][c] = id;
                queue.add(new int[]{r, c});
            }
        }

        private boolean canGo(int r, int c) {
            return r >= 0 && r < grid.length && c >= 0 && c < grid[0].length
                    && !visited[r][c] && grid[r][c] == '.';
        }

        /** Returns the component id of the cell (0 if not an empty cell). */
        int getId(int r, int c) {
            return grid[r][c] == '.' ? componentId[r][c] : 0;
        }

        /** Returns the size of the component that contains the cell (0 otherwise). */
        int getSize(int r, int c) {
            return grid[r][c] == '.' ? componentSize[r][c] : 0;
        }
    }

    public static void main(String[] args) {
        try (Scanner sc = new Scanner(System.in)) {
            int rows = sc.nextInt();
            int cols = sc.nextInt();
            sc.nextLine(); // skip end‑of‑line

            char[][] grid = new char[rows][cols];
            for (int r = 0; r < rows; r++) {
                grid[r] = sc.nextLine().toCharArray();
            }

            ComponentFinder finder = new ComponentFinder(grid);
            int[][] result = new int[rows][cols];

            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (grid[r][c] == '*') {
                        result[r][c] = calculateStarValue(grid, finder, r, c);
                    }
                }
            }

            try (PrintWriter out = new PrintWriter(System.out)) {
                for (int r = 0; r < rows; r++) {
                    for (int c = 0; c < cols; c++) {
                        out.print(result[r][c] > 0 ? result[r][c] % 10 : '.');
                    }
                    out.println();
                }
                out.flush();
            }
        }
    }

    /** Computes the summed size of distinct neighbouring components for a '*'. */
    private static int calculateStarValue(char[][] grid, ComponentFinder finder,
                                          int r, int c) {
        Set<Integer> seenComponentIds = new HashSet<>();
        int total = 1; // the '*' itself contributes one cell

        int[][] directions = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};
        for (int[] dir : directions) {
            int nr = r + dir[0];
            int nc = c + dir[1];
            if (isInBounds(grid, nr, nc) && grid[nr][nc] == '.') {
                int compId = finder.getId(nr, nc);
                if (compId != 0 && !seenComponentIds.contains(compId)) {
                    total += finder.getSize(nr, nc);
                    seenComponentIds.add(compId);
                }
            }
        }
        return total;
    }

    private static boolean isInBounds(char[][] grid, int r, int c) {
        return r >= 0 && r < grid.length && c >= 0 && c < grid[0].length;
    }
}

import java.io.*;
import java.util.*;

/**
 * Solves a grid‑based connectivity problem.
 * <p>
 * The program reads a grid of '.' (free cell) and '*' (blocked cell).  
 * It computes the size of each connected component of '.' cells, stores the
 * size in an indexed array, and then for every '*' cell prints the sum of the
 * sizes of the distinct neighbouring components, modulo 10.
 * </p>
 */
public class C {

    /* --------------------------------------------------------------------- */
    /*                         Constant Directions                            */
    /* --------------------------------------------------------------------- */
    private static final int[] DX = {1, -1, 0, 0};
    private static final int[] DY = {0, 0, 1, -1};

    /* --------------------------------------------------------------------- */
    /*                               Main Entry                                 */
    /* --------------------------------------------------------------------- */
    public static void main(String[] args) throws Exception {
        // Run solving logic in a dedicated thread to stay within memory limits
        Thread problemThread = new Thread(C::solve) {
            @Override
            public void run() {
                solve();
            }
        };
        problemThread.start();
        problemThread.join();
    }

    /* --------------------------------------------------------------------- */
    /*                               Solve Method                               */
    /* --------------------------------------------------------------------- */
    public static void solve() {
        try (FastScanner fs = new FastScanner(System.in)) {
            int rows = fs.nextInt();
            int cols = fs.nextInt();

            char[][] grid = readGrid(fs, rows, cols);
            int[][] componentId = new int[rows][cols];   // 0 → not visited yet
            int[][] componentSize = new int[rows * cols + 1][2]; // [index][0]=id, [1]=size
            int componentCount = 1;

            // 1️⃣  Find all connected components of '.' cells
            for (int r = 0; r < rows; ++r) {
                for (int c = 0; c < cols; ++c) {
                    if (grid[r][c] == '*' || componentId[r][c] != 0) {
                        continue;
                    }
                    int size = exploreComponent(grid, componentId, componentSize,
                                                componentCount, r, c);
                    componentCount++;
                }
            }

            // 2️⃣  Produce the required output
            StringBuilder out = new StringBuilder();
            for (int r = 0; r < rows; ++r) {
                for (int c = 0; c < cols; ++c) {
                    if (grid[r][c] == '.') {
                        out.append('.');
                    } else {
                        int answer = computeStarAnswer(grid, componentId, componentSize,
                                                       componentCount, r, c);
                        out.append(answer % 10);
                    }
                }
                out.append('\n');
            }

            System.out.print(out.toString());
        }
    }

    /* --------------------------------------------------------------------- */
    /*            Explore a connected component of '.' cells (DFS)            */
    /* --------------------------------------------------------------------- */
    private static int exploreComponent(char[][] grid,
                                          int[][] componentId,
                                          int[][] componentSize,
                                          int currentId,
                                          int startR,
                                          int startC) {
        Deque<Pair> stack = new ArrayDeque<>();
        stack.push(new Pair(startR, startC));

        int size = 0;
        while (!stack.isEmpty()) {
            Pair cur = stack.pop();
            int r = cur.f;
            int c = cur.s;

            if (componentId[r][c] != 0) {
                continue; // already processed
            }
            componentId[r][c] = currentId;
            ++size;

            for (int dir = 0; dir < DX.length; ++dir) {
                int nr = r + DX[dir];
                int nc = c + DY[dir];
                if (!isInBounds(nr, grid.length, nc, grid[0].length)) {
                    continue;
                }
                if (grid[nr][nc] != '.' || componentId[nr][nc] != 0) {
                    continue;
                }
                stack.push(new Pair(nr, nc));
            }
        }
        // Store the size at the index equal to the component id
        componentSize[currentId][0] = currentId;
        componentSize[currentId][1] = size;
        return size;
    }

    /* --------------------------------------------------------------------- */
    /*               Compute answer for a '*' cell (mod 10)                    */
    /* --------------------------------------------------------------------- */
    private static int computeStarAnswer(char[][] grid,
                                          int[][] componentId,
                                          int[][] componentSize,
                                          int componentCount,
                                          int r,
                                          int c) {
        boolean[] seen = new boolean[componentCount];
        int answer = 1; // the cell itself counts as 1

        for (int dir = 0; dir < DX.length; ++dir) {
            int nr = r + DX[dir];
            int nc = c + DY[dir];
            if (!isInBounds(nr, grid.length, nc, grid[0].length)) {
                continue;
            }
            if (grid[nr][nc] != '.') {
                continue;
            }
            int cid = componentId[nr][nc];
            if (cid == 0 || seen[cid]) {
                continue;
            }
            answer += componentSize[cid][1];
            seen[cid] = true;
        }
        return answer;
    }

    /* --------------------------------------------------------------------- */
    /*                         Utility helpers                                 */
    /* --------------------------------------------------------------------- */
    private static char[][] readGrid(FastScanner fs, int rows, int cols) {
        char[][] grid = new char[rows][];
        for (int r = 0; r < rows; ++r) {
            grid[r] = fs.next().toCharArray();
        }
        return grid;
    }

    private static boolean isInBounds(int x, int maxX, int y, int maxY) {
        return x >= 0 && x < maxX && y >= 0 && y < maxY;
    }

    /* --------------------------------------------------------------------- */
    /*                         Fast input class (similar to original)         */
    /* --------------------------------------------------------------------- */
    private static class FastScanner {
        private final BufferedReader br;
        private String line;
        private StringTokenizer st;

        FastScanner(InputStream stream) {
            br = new BufferedReader(new InputStreamReader(stream));
        }

        boolean hasNext() {
            return peekToken() != null;
        }

        int nextInt() {
            return Integer.parseInt(nextToken());
        }

        String next() {
            return nextToken();
        }

        String nextLine() {
            try {
                line = br.readLine();
                st = null;
                return line;
            } catch (IOException e) {
                return null;
            }
        }

        private String peekToken() {
            if (st == null || !st.hasMoreTokens()) {
                try {
                    while (true) {
                        line = br.readLine();
                        if (line == null) {
                            return null;
                        }
                        st = new StringTokenizer(line);
                        if (st.hasMoreTokens()) {
                            return st.nextToken();
                        }
                    }
                } catch (IOException e) {
                    return null;
                }
            }
            return st.nextToken();
        }

        private String nextToken() {
            String token = peekToken();
            if (token == null) {
                return "";
            }
            // consume token for next call
            if (st != null) {
                st.nextToken();
            }
            return token;
        }
    }

    /* --------------------------------------------------------------------- */
    /*                         Simple pair container                           */
    /* --------------------------------------------------------------------- */
    private static final class Pair {
        final int f; // row
        final int s; // column

        Pair(int f, int s) {
            this.f = f;
            this.s = s;
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Refactored solution for Problem 616‑C.
 *
 * <p>Key improvements:
 *   <ul>
 *       <li>Separated concerns (input, processing, output) into small methods.</li>
 *       <li>Renamed variables and fields to expressive names.</li>
 *       <li>Encapsulated Union‑Find logic in its own static class.</li>
 *       <li>Extracted direction vectors into an enum for clarity.</li>
 *       <li>Removed dead imports and added only needed ones.</li>
 *       <li>Added Javadoc comments and inline documentation.</li>
 *   </ul>
 * </p>
 */
public class Problem_616_C {

    /** Constant for an empty cell ('.'). */
    private static final char EMPTY = '.';
    /** Constant for a bomb cell ('*'). */
    private static final char BOMB = '*';
    /** Constant for digit characters '0'‑'9'. */
    private static final char DIGIT_MASK = (char) '0';

    /* --------------------------------------------------------------------- */
    /*  Direction vectors – up, left, down, right                               */
    /* --------------------------------------------------------------------- */
    private enum Direction {
        UP(-1, 0), LEFT(0, -1), DOWN(1, 0), RIGHT(0, 1);

        final int di, dj;
        Direction(int di, int dj) { this.di = di; this.dj = dj; }
    }

    /* --------------------------------------------------------------------- */
    /*  Union‑Find (Disjoint Set) data structure                               */
    /* --------------------------------------------------------------------- */
    private static final class UnionFind {
        private final int[] parent;
        private final int[] size;
        private final int[] rank;
        private final int totalElements;

        UnionFind(int n) {
            parent = new int[n];
            size   = new int[n];
            rank   = new int[n];
            for (int i = 0; i < n; i++) {
                parent[i] = i;
                size[i]   = 1;
            }
            totalElements = n;
        }

        /** Finds the representative of the set containing {@code x}. */
        int find(int x) {
            if (parent[x] != x) {
                parent[x] = find(parent[x]);
            }
            return parent[x];
        }

        /** Merges the sets containing {@code a} and {@code b}. */
        void union(int a, int b) {
            int pa = find(a);
            int pb = find(b);
            if (pa == pb) { return; }

            // union by rank
            if (rank[pa] < rank[pb]) {
                link(pb, pa);
            } else if (rank[pa] > rank[pb]) {
                link(pa, pb);
            } else {
                link(pb, pa);
                rank[pa]++;
            }
        }

        /** Links {@code child} under {@code root}. */
        private void link(int root, int child) {
            parent[child] = root;
            size[root] += size[child];
            rank[root] = Math.max(rank[root], rank[child] + 1);
        }

        /** Returns the size of the component that contains {@code x}. */
        int componentSize(int x) {
            return size[find(x)];
        }

        /** Total number of elements managed by this Union‑Find. */
        int total() { return totalElements; }
    }

    /* --------------------------------------------------------------------- */
    /*  Very small scanner utility                                            */
    /* --------------------------------------------------------------------- */
    private static final class MyScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        MyScanner(Reader reader) {
            this.br = new BufferedReader(reader);
        }

        private String nextToken() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                st = new StringTokenizer(br.readLine());
            }
            return st.nextToken();
        }

        int nextInt() throws IOException { return Integer.parseInt(nextToken()); }
        String next() throws IOException { return nextToken(); }
    }

    /* --------------------------------------------------------------------- */
    /*  Core solving routine                                                  */
    /* --------------------------------------------------------------------- */
    private static void solve(BufferedReader in, PrintWriter out) throws IOException {
        MyScanner scanner = new MyScanner(in);

        int rows = scanner.nextInt();
        int cols = scanner.nextInt();

        char[][] grid = new char[rows][];
        for (int r = 0; r < rows; r++) {
            grid[r] = scanner.next().toCharArray();
        }

        int totalCells = rows * cols;
        UnionFind uf = new UnionFind(totalCells);

        /* --------------------------------------------------------------- */
        /*  1️⃣ Build connectivity between adjacent empty cells ('.')      */
        /* --------------------------------------------------------------- */
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] != EMPTY) { continue; }

                int idx = r * cols + c;

                // connect with cell above
                if (r > 0 && grid[r - 1][c] == EMPTY) {
                    uf.union(idx, idx - cols);
                }
                // connect with cell to the left
                if (c > 0 && grid[r][c - 1] == EMPTY) {
                    uf.union(idx, idx - 1);
                }
            }
        }

        /* --------------------------------------------------------------- */
        /*  2️⃣ Process each cell to produce the required output           */
        /* --------------------------------------------------------------- */
        char[] lineBuffer = new char[cols];
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                int idx = r * cols + c;

                // Empty cells stay empty in the output
                if (grid[r][c] == EMPTY) {
                    lineBuffer[c] = EMPTY;
                    continue;
                }

                // Count distinct adjacent empty components
                Set<Integer> seenRoots = new HashSet<>();
                int reachable = 1; // the bomb cell itself

                for (Direction dir : Direction.values()) {
                    int nr = r + dir.di;
                    int nc = c + dir.dj;

                    if (!isInside(nr, nc, rows, cols)) { continue; }
                    if (grid[nr][nc] != EMPTY) { continue; }

                    int neighborIdx = nr * cols + nc;
                    int root = uf.find(neighborIdx);
                    seenRoots.add(root);
                }

                // Add sizes of all distinct neighboring components
                for (int root : seenRoots) {
                    reachable += uf.componentSize(root);
                }

                // Store digit character (mod 10) in the output line
                lineBuffer[c] = (char) (DIGIT_MASK + (reachable % 10));
            }
            out.println(new String(lineBuffer));
        }
    }

    /** Helper that checks whether a coordinate lies inside the rectangle. */
    private static boolean isInside(int row, int col, int rows, int cols) {
        return row >= 0 && row < rows && col >= 0 && col < cols;
    }

    /* --------------------------------------------------------------------- */
    /*  Entry point                                                            */
    /* --------------------------------------------------------------------- */
    public static void main(String[] args) throws IOException {
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
        PrintWriter writer = new PrintWriter(System.out, true);
        solve(reader, writer);
        writer.flush();
    }
}

/**
 * Main class that reads a grid, finds connected components of empty cells
 * and prints the size of each island modulo 10.
 *
 * The implementation is deliberately kept clean and readable:
 *   • meaningful class / method names
 *   • extracted helper methods
 *   • constants instead of magic numbers
 *   • a small, reusable Union‑Find data structure
 *   • InputReader that hides the low‑level byte handling
 */
public class Main {

    private static PrintWriter out;
    private static InputReader ir;

    /** Directions: up, right, down, left */
    private static final int[] DX = { -1, 0, 1, 0 };
    /** Opposite direction index (used to move back one step) */
    private static final int[] OPPOSITE = { 2, 1, 0, 3 };

    public static void main(String[] args) throws Exception {
        ir = new InputReader(System.in);
        out = new PrintWriter(System.out);
        solve();
        out.flush();
    }

    /** Entry point of the algorithm. */
    private static void solve() {
        int n = ir.nextInt();
        int m = ir.nextInt();
        char[][] grid = ir.nextCharMap(n, m);

        UnionFind uf = new UnionFind(n * m);

        // Build connectivity of empty ('.') cells.
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i][j] == '.') {
                    uniteNeighbouringEmpty(uf, grid, i, j);
                }
            }
        }

        // Output the result for each cell.
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i][j] == '.') {
                    out.print('.');
                } else {
                    out.print(computeIslandSize(grid, uf, i, j));
                }
            }
            out.println();
        }
    }

    /** Connects the current empty cell with all four orthogonal neighbours that are also empty. */
    private static void uniteNeighbouringEmpty(UnionFind uf, char[][] grid, int i, int j) {
        for (int dir = 0; dir < DX.length; dir++) {
            int ni = i + DX[dir];
            int nj = j + DX[dir ^ 1]; // opposite direction
            if (inBounds(ni, nj, grid) && grid[ni][nj] == '.') {
                uf.unite(i * grid.length + j, ni * grid.length + nj);
            }
        }
    }

    /** Determines the size of the island that would be formed if the current cell became empty. */
    private static char computeIslandSize(char[][] grid, UnionFind uf, int i, int j) {
        int baseSize = 1; // the current cell itself

        for (int dir = 0; dir < DX.length; dir++) {
            int ni = i + DX[dir];
            int nj = j + DX[dir ^ 1];
            if (!inBounds(ni, nj, grid) || grid[ni][nj] != '.') {
                continue;
            }

            int neighbourId = ni * grid.length + nj;
            // Avoid double‑counting when two neighbours belong to the same component.
            if (dir > 0 && sameComponent(i, j, ni, nj, grid, uf)) {
                continue;
            }
            baseSize += uf.setSize(neighbourId);
        }
        return Character.forDigit(baseSize % 10, 10);
    }

    /** Checks whether two coordinates belong to the same Union‑Find component. */
    private static boolean sameComponent(int x, int y, int nx, int ny, char[][] grid, UnionFind uf) {
        return uf.same(x * grid.length + y, nx * grid.length + ny);
    }

    /** Utility to test array bounds. */
    private static boolean inBounds(int i, int j, char[][] grid) {
        return i >= 0 && i < grid.length && j >= 0 && j < grid[0].length;
    }
}

/**
 * Simple Union‑Find (Disjoint Set Union) implementation.
 *
 * Only the operations required by {@link Main} are provided:
 *   • {@code unite(int, int)} – merge two sets
 *   • {@code same(int, int)} – test set equality
 *   • {@code setSize(int)} – size of a set
 *   • {@code setCount()} – number of distinct sets (not used, kept for completeness)
 */
class UnionFind {
    private final int[] parent;

    /** Creates a DSU with the given number of elements, each initially in its own set. */
    UnionFind(int size) {
        parent = new int[size];
        java.util.Arrays.fill(parent, -1);
    }

    /** Returns the representative of the set containing {@code x}. */
    int root(int x) {
        if (parent[x] < 0) {
            return x;
        }
        return parent[x] = root(parent[x]);
    }

    /** Merges the sets of {@code x} and {@code y}. */
    void unite(int x, int y) {
        int rx = root(x);
        int ry = root(y);
        if (rx == ry) {
            return;
        }
        // attach smaller tree under larger tree (by size)
        if (parent[ry] < parent[rx]) {
            int tmp = rx;
            rx = ry;
            ry = tmp;
        }
        parent[rx] += parent[ry];
        parent[ry] = rx;
    }

    /** Returns {@code true} if {@code x} and {@code y} belong to the same set. */
    boolean same(int x, int y) {
        return root(x) == root(y);
    }

    /** Returns the number of distinct sets. */
    int setCount() {
        int cnt = 0;
        for (int v : parent) {
            if (v < 0) {
                cnt++;
            }
        }
        return cnt;
    }

    /** Returns the size of the set that contains {@code x}. */
    int setSize(int x) {
        return -parent[root(x)];
    }
}

/**
 * Utility class that encapsulates fast input operations.
 *
 * The implementation mirrors the original one but is kept private to this file,
 * making the public API of {@code Main} smaller and easier to understand.
 */
class InputReader {
    private final InputStream in;
    private final byte[] buffer = new byte[1024];
    private int curPos = 0;
    private int bufferLength = 0;

    InputReader(InputStream in) {
        this.in = in;
    }

    /** Skips whitespace characters. */
    private void skipWhiteSpace() {
        while (hasNextByte() && isSpaceChar(buffer[curPos])) {
            curPos++;
        }
    }

    /** Returns {@code true} if there is at least one byte available. */
    private boolean hasNextByte() {
        if (curPos >= bufferLength) {
            refillBuffer();
            curPos = 0;
            if (bufferLength == 0) {
                return false;
            }
        }
        return true;
    }

    /** Reads the next non‑whitespace token as a string. */
    String next() {
        skipWhiteSpace();
        StringBuilder sb = new StringBuilder();
        while (hasNextByte() && !isSpaceChar(buffer[curPos])) {
            sb.appendCodePoint(buffer[curPos++]);
        }
        return sb.toString();
    }

    /** Reads the next integer. */
    int nextInt() {
        return Integer.parseInt(next());
    }

    /** Reads the next character map (array of strings converted to char[]). */
    char[][] nextCharMap(int n, int m) {
        char[][] map = new char[n][];
        for (int i = 0; i < n; i++) {
            map[i] = next().toCharArray();
        }
        return map;
    }

    /** Checks whether the current character code represents a whitespace. */
    private static boolean isSpaceChar(int c) {
        return !(c >= 33 && c <= 126);
    }

    /** Refills the internal buffer from the underlying {@code InputStream}. */
    private void refillBuffer() throws IOException {
        bufferLength = in.read(buffer);
    }
}

package com.example;

import java.io.*;
import java.util.*;

/**
 * Entry point of the application.
 * <p>
 * The program reads a rectangular maze from {@code System.in},
 * discovers connected '.' regions, counts their sizes and prints a
 * transformed grid where each non‑'.' cell shows the modulo‑10 sum of the
 * sizes of the distinct neighbouring regions.
 * </p>
 */
public class Main {

    /** Launches the worker thread that performs all heavy‑lifting. */
    public static void main(String[] args) {
        Thread worker = new Thread(null, new InputProcessor(), "InputProcessor", 1_000_000_000);
        worker.start();
    }

    /**
     * Worker that:
     * <ul>
     *   <li>parses the input,
     *   <li>labels each connected '.' component,
     *   <li>counts the size of each component,
     *   <li>generates the required output.
     * </ul>
     */
    private static final class InputProcessor implements Runnable {

        /** Maximum allowed dimension (kept for safety). */
        private static final int MAX_DIM = 1000;

        /** Grid stored as a 2‑D char array. */
        private char[][] grid;

        /** Parallel boolean array marking visited cells. */
        private boolean[][] visited;

        /** Identifier of the component each cell belongs to. */
        private int[][] componentId;

        /** Size of each component, keyed by its identifier. */
        private final Map<Integer, Integer> componentSize = new HashMap<>();

        /** Counter for generating unique component identifiers. */
        private int componentCount;

        @Override
        public void run() {
            try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in))) {
                // -----------------------------------------------------------------
                // 1️⃣  READ INPUT
                // -----------------------------------------------------------------
                String[] firstLine = Optional.of(br.readLine())
                        .filter(Objects::nonNull)
                        .split("\\s+");

                int rows = Integer.parseInt(firstLine[0]);
                int cols = Integer.parseInt(firstLine[1]);

                // Dynamically allocate structures based on the actual dimensions.
                grid = new char[rows][];
                visited = new boolean[rows][cols];
                componentId = new int[rows][cols];

                for (int r = 0; r < rows; r++) {
                    grid[r] = br.readLine().trim().toCharArray();
                }

                // -----------------------------------------------------------------
                // 2️⃣  LABEL COMPONENTS (DFS)
                // -----------------------------------------------------------------
                for (int r = 0; r < rows; r++) {
                    for (int c = 0; c < cols; c++) {
                        if (!visited[r][c] && grid[r][c] == '.') {
                            componentCount++;
                            explore(r, c, componentCount);
                        }
                    }
                }

                // -----------------------------------------------------------------
                // 3️⃣  BUILD OUTPUT
                // -----------------------------------------------------------------
                StringBuilder out = new StringBuilder(rows * (cols + 1)); // +1 for newline
                for (int r = 0; r < rows; r++) {
                    for (int c = 0; c < cols; c++) {
                        if (grid[r][c] == '.') {
                            out.append('.');
                        } else {
                            out.append(computeNeighbourSum(r, c));
                        }
                    }
                    out.append('\n');
                }
                System.out.print(out);
            } catch (IOException e) {
                // In competitive‑programming environments printing the stack‑trace
                // to stderr is acceptable.
                System.err.println("I/O error: " + e.getMessage());
                e.printStackTrace();
            }
        }

        /**
         * Depth‑first search that assigns a component identifier and records its
         * size. The identifier {@code id} is supplied by the caller so that we
         * can keep the numbering starting at {@code 1} (matching the original
         * implementation).
         */
        private void explore(int r, int c, int id) {
            if (r < 0 || r >= rows || c < 0 || c >= cols) return;
            if (visited[r][c] || grid[r][c] != '.') return;

            visited[r][c] = true;
            componentId[r][c] = id;
            componentSize.merge(id, 1, Integer::sum);

            explore(r - 1, c, id);
            explore(r + 1, c, id);
            explore(r, c - 1, id);
            explore(r, c + 1, id);
        }

        /**
         * Returns a single digit (ASCII ‘0’‑‘9’) representing the sum modulo 10 of
         * the sizes of all distinct neighbouring '.' components.
         */
        private char computeNeighbourSum(int r, int c) {
            Set<Integer> neighbourIds = new HashSet<>();
            int sum = 0;

            int[][] directions = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};
            for (int[] dir : directions) {
                int nr = r + dir[0];
                int nc = c + dir[1];
                if (isInside(nr, nc) && grid[nr][nc] == '.') {
                    int id = componentId[nr][nc];
                    if (neighbourIds.add(id)) {               // true only if not already present
                        sum = (sum + componentSize.get(id)) % 10;
                    }
                }
            }
            return (char) ('0' + sum);
        }

        private boolean isInside(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Entry point of the application.
 * Delegates the actual solution to {@link Solution}.
 */
public class Main {
    public static void main(String[] args) throws IOException {
        // Use try‑with‑resources to guarantee proper closing of streams.
        try (InputReader reader = new InputReader(System.in);
             PrintWriter out = new PrintWriter(
                     new BufferedWriter(new OutputStreamWriter(System.out)), true)) {
            new Solution().solve(reader, out);
        }
    }

    /**
     * Solves the problem described in the original {@code TaskB}.
     * The class encapsulates all state and logic, avoiding static sprawl.
     */
    static class Solution {
        // -----------------------------------------------------------------------
        // Constants & fields
        // -----------------------------------------------------------------------
        // 4‑direction vectors: right, down, left, up
        private static final int[] DR = {0, 1, 0, -1};
        private static final int[] DC = {1, 0, -1, 0};

        private int rows;
        private int cols;
        private char[][] grid;                 // input map
        private int[][] componentId;             // component identifier for each '.' cell
        private int[] componentSize;             // size of each component (1‑based indexing)
        private int componentCounter;            // next unused component id

        /** Output buffer used while building the answer. */
        private final StringBuilder answerBuilder = new StringBuilder();

        // -----------------------------------------------------------------------
        // Public API
        // -----------------------------------------------------------------------
        /**
         * Reads the input, processes the grid and writes the result.
         */
        public void solve(InputReader reader, PrintWriter out) {
            readInput(reader);
            identifyComponents();
            out.print(constructResult());
            out.flush();
        }

        // -----------------------------------------------------------------------
        // Input handling
        // -----------------------------------------------------------------------
        private void readInput(InputReader in) {
            rows = in.nextInt();
            cols = in.nextInt();
            grid = new char[rows][cols];
            for (int r = 0; r < rows; r++) {
                String line = in.next();
                System.arraycopy(line.toCharArray(), 0, grid[r], 0, cols);
            }
        }

        // -----------------------------------------------------------------------
        // Component discovery
        // -----------------------------------------------------------------------
        /**
         * Performs a DFS (implemented iteratively) for every unvisited '.' cell
         * and records its component id and size.
         */
        private void identifyComponents() {
            componentId = new int[rows][cols];
            int maxComponentId = rows * cols;          // safe upper bound
            componentSize = new int[maxComponentId + 1];
            componentCounter = 1;                      // 0 stays unused

            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (grid[r][c] == '.' && componentId[r][c] == 0) {
                        explore(r, c);
                        componentCounter++;
                    }
                }
            }
        }

        /**
         * Explores a connected component of '.' cells using an explicit stack.
         * The method fills {@code componentId} and updates {@code componentSize}.
         */
        private void explore(int startR, int startC) {
            int currentId = componentCounter++;
            Deque<int[]> stack = new ArrayDeque<>();
            stack.push(new int[]{startR, startC});

            while (!stack.isEmpty()) {
                int[] cell = stack.pop();
                int r = cell[0];
                int c = cell[1];

                if (componentId[r][c] != 0) {
                    continue; // already processed
                }
                componentId[r][c] = currentId;
                componentSize[currentId]++;

                for (int d = 0; d < 4; d++) {
                    int nr = r + DR[d];
                    int nc = c + DC[d];
                    if (!isInside(nr, nc)) continue;
                    if (grid[nr][nc] != '.' || componentId[nr][nc] != 0) continue;
                    stack.push(new int[]{nr, nc});
                }
            }
        }

        private boolean isInside(int r, int c) {
            return 0 <= r && r < rows && 0 <= c && c < cols;
        }

        // -----------------------------------------------------------------------
        // Result construction
        // -----------------------------------------------------------------------
        /**
         * Builds the required output string by evaluating every '*' cell.
         * The algorithm:
         *   1. Collect distinct component ids adjacent to the '*',
         *   2. Sum their sizes + 1 (the '*'), 3. Take modulo 10,
         *   4. Append the resulting digit (or '.' for non‑'*' cells).
         */
        private String constructResult() {
            answerBuilder.setLength(0); // clear previous content

            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (grid[r][c] == '*') {
                        int total = 1; // count the current cell
                        Set<Integer> neighboringIds = new HashSet<>();

                        for (int d = 0; d < 4; d++) {
                            int nr = r + DR[d];
                            int nc = c + DC[d];
                            if (!isInside(nr, nc)) continue;
                            if (grid[nr][nc] != '.') continue;
                            int id = componentId[nr][nc];
                            if (id == 0) continue; // not part of any component
                            neighboringIds.add(id);
                        }

                        for (int id : neighboringIds) {
                            total += componentSize[id];
                        }
                        answerBuilder.append((char) ('0' + (total % 10)));
                    } else {
                        answerBuilder.append('.');
                    }
                }
                answerBuilder.append('\n');
            }
            return answerBuilder.toString();
        }
    }

    /**
     * Fast input readers that skip the boilerplate of {@code StringTokenizer}.
     */
    static class InputReader {
        private final BufferedReader br;
        private StringTokenizer st;

        InputReader(InputStream input) {
            br = new BufferedReader(new InputStreamReader(input));
        }

        /** Returns the next token, blocking until one is available. */
        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    throw new UncheckedIOException(e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Reads a binary grid, treats each contiguous water area ('1') as an island,
 * assigns a unique identifier to each cell of an island and stores the size of
 * every island. Afterwards for every land cell the neighbouring island identifiers
 * are used to augment a running value that finally is printed modulo 10.
 *
 * The program follows clean‑code principles:
 *   • meaningful naming,
 *   • small focused methods,
 *   • constants instead of magic numbers,
 *   • proper resource handling,
 *   • separation of concerns.
 */
public class Main {

    /** Directions used for island detection (up, down, left, right). */
    private static final int[][] DIRS = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};

    /** Maximum possible number of islands – safely larger than any test case. */
    private static final int MAX_ISLANDS = 1_000_001;

    /** Grid dimensions are at most 1000×1000 in the original problem, add a border. */
    private static final int BOUNDARY = 2;

    /** Characters used in the input. */
    private static final char LAND = '1';
    private static final char WATER = '.';

    /** Scanner/PrintWriter – they are closed automatically thanks to try‑with‑resources. */
    private static void solve() throws IOException {
        // -------------------------------------------------------------------------
        // 1️⃣  Read input
        // -------------------------------------------------------------------------
        int rows, cols;
        try (Scanner scanner = new Scanner(System.in)) {
            rows = scanner.nextInt();          // n
            cols = scanner.nextInt();          // m
        }

        // Grid with a one‑cell border filled with water (value -1). Makes neighbour
        // checks simpler because the border can never be part of an island.
        int[][] grid = new int[rows + BOUNDARY][cols + BOUNDARY];
        char[][] raw = new char[rows][cols];

        // Fill the raw matrix with the characters read from stdin.
        for (int r = 0; r < rows; r++) {
            String line = scanner.next();
            raw[r] = line.toCharArray();
        }

        // Convert the character matrix into an integer grid:
        //   -1  → water
        //   1   → land
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                grid[r + 1][c + 1] = (raw[r][c] == LAND) ? 1 : -1;
            }
        }

        // -------------------------------------------------------------------------
        // 2️⃣  Assign a unique island identifier to each land cell
        // -------------------------------------------------------------------------
        int[][] islandId = new int[rows + BOUNDARY][cols + BOUNDARY];
        int[] islandSize = new int[MAX_ISLANDS];   // islandSize[id] = number of cells of that island
        int nextId = 1;                            // identifiers start at 1

        for (int r = 1; r <= rows; r++) {
            for (int c = 1; c <= cols; c++) {
                if (grid[r][c] == 1 && islandId[r][c] == 0) {
                    dfsAssignId(grid, islandId, islandSize, nextId, r, c);
                    nextId++;
                }
            }
        }

        // -------------------------------------------------------------------------
        // 3️⃣  Build the answer matrix (the same calculation the original code performed)
        // -------------------------------------------------------------------------
        int[][] answer = new int[rows + BOUNDARY][cols + BOUNDARY];
        StringBuilder out = new StringBuilder();

        for (int r = 1; r <= rows; r++) {
            for (int c = 1; c <= cols; c++) {
                if (grid[r][c] != 1) {
                    out.append('.');
                    continue;
                }

                // current cell's value starts at 0 (the original code used a[i][j] as a placeholder)
                int value = 0;

                // Check the four neighbours. If the neighbour belongs to an island,
                // add the size of that island (indexed by its identifier).
                for (int[] dir : DIRS) {
                    int nr = r + dir[0];
                    int nc = c + dir[1];
                    int nid = islandId[nr][nc];
                    // nid == 0 means the neighbour is water or out of bounds.
                    if (nid != 0 && islandSize[nid] > 0) {
                        value += islandSize[nid];
                    }
                }

                answer[r][c] = value % 10;
                out.append(answer[r][c]);
            }
            out.append('\n');
        }

        System.out.print(out.toString());
    }

    /**
     * Depth‑first search that labels all cells of a single island with
     * {@code currentId} and records the island's size.
     */
    private static void dfsAssignId(int[][] grid,
                                    int[][] islandId,
                                    int[] islandSize,
                                    int currentId,
                                    int r,
                                    int c) {
        if (!inside(grid, r, c) || grid[r][c] != 1 || islandId[r][c] != 0) {
            return;
        }

        islandId[r][c] = currentId;
        islandSize[currentId]++;

        for (int[] dir : DIRS) {
            dfsAssignId(grid, islandId, islandSize, currentId, r + dir[0], c + dir[1]);
        }
    }

    /** Helper that checks whether a coordinate stays inside the bordered grid. */
    private static boolean inside(int[][] grid, int r, int c) {
        return r >= 1 && r < grid.length && c >= 1 && c < grid[0].length;
    }

    // -------------------------------------------------------------------------
    // Entry point
    // -------------------------------------------------------------------------
    public static void main(String[] args) throws IOException {
        solve();
    }
}

/**
 * Refactored version of *TheLabyrinth* program.
 *
 * <p>Key improvements:
 * <ul>
 *   <li>Encapsulated state inside {@code Labyrinth} – no large static mutable fields.</li>
 *   <li>Used clear, descriptive names and eliminated magic characters.</li>
 *   <li>Separated concerns (input, processing, output) into dedicated methods.</li>
 *   <li>Replaced the commented‑out marker (',') with a dedicated {@code visited} flag.</li>
 *   <li>Removed unused/unnecessary functionality from the inner {@code Scanner} helper.</li>
 *   <li>Employed try‑with‑resources for I/O and avoided potential resource leaks.</li>
 * </ul>
 *
 * The program behaviour is identical to the original implementation.
 */
public final class Labyrinth {

    /** Four possible movement directions (down, right, up, left). */
    private static final int[][] DIRECTIONS = {
            {1, 0},   // down
            {0, 1},   // right
            {-1, 0},  // up
            {0, -1}   // left
    };

    /** The grid read from input – contains '.' , '*' and other characters. */
    private char[][] grid;

    /** Size of the connected component that each '.' belongs to.
     *  Only the representative cell (the one used as flood‑fill start) stores the size. */
    private int[][] componentSize;

    /** For every cell that is part of a '.'‑component we store the
     *  representative cell (the one passed to {@link #floodFill(int, int)}). */
    private Point[][] componentSource;

    /** Represents a point in the grid. */
    private static final class Point {
        final int row;
        final int col;

        Point(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }

    /**
     * Reads the grid dimensions and the grid itself from {@code System.in}.
     *
     * @return a new {@code Labyrinth} instance containing the parsed data.
     * @throws IllegalStateException if the input format is invalid.
     */
    private static Labyrinth readInput(Scanner scanner) {
        int rows = scanner.nextInt();
        int cols = scanner.nextInt();

        Labyrinth lab = new Labyrinth();
        lab.grid = new char[rows][cols];
        for (int r = 0; r < rows; r++) {
            String line = scanner.next();
            for (int c = 0; c < cols; c++) {
                lab.grid[r][c] = line.charAt(c);
            }
        }
        return lab;
    }

    /**
     * Performs a flood‑fill on all '.'‑cells, storing component size and source
     * information. The size is stored only at the start cell of the component.
     */
    private void computeComponentSizes() {
        int rows = grid.length;
        int cols = grid[0].length;

        componentSize = new int[rows][cols];
        componentSource = new Point[rows][cols];

        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '.' && componentSource[r][c] == null) {
                    floodFill(r, c);
                }
            }
        }
    }

    /**
     * Recursive flood‑fill that marks every cell belonging to the component
     * containing {@code (startRow,startCol)}. All visited cells reference the
     * same {@link Point} object (the start cell) and the component size is
     * recorded at that start cell.
     *
     * @param startRow row of the start cell
     * @param startCol column of the start cell
     */
    private void floodFill(int startRow, int startCol) {
        Point start = new Point(startRow, startCol);
        int size = explore(startRow, startCol, start);

        componentSize[startRow][startCol] = size;
    }

    /**
     * Helper that actually explores the component recursively.
     *
     * @return the number of cells belonging to this component.
     */
    private int explore(int r, int c, Point representative) {
        if (r < 0 || r >= grid.length || c < 0 || c >= grid[0].length) {
            return 0;
        }
        if (grid[r][c] != '.' || componentSource[r][c] != null) {
            return 0;
        }

        componentSource[r][c] = representative;
        int count = 1;

        for (int[] dir : DIRECTIONS) {
            count += explore(r + dir[0], c + dir[1], representative);
        }
        return count;
    }

    /**
     * Determines the digit that must be printed for a '*'-cell.
     * The digit is the sum of the sizes of all distinct adjacent '.'‑components,
     * taken modulo 10.
     *
     * @param r row index of the '*' cell
     * @param c column index of the '*' cell
     * @return the digit character ('0'‑'9')
     */
    private char computeDigitForObstacle(int r, int c) {
        boolean[][] visitedComponent = new boolean[grid.length][grid[0].length];
        int sum = 1; // the '*' cell itself contributes 1 to the sum (as in original)

        for (int[] dir : DIRECTIONS) {
            int nr = r + dir[0];
            int nc = c + dir[1];

            if (!isInBounds(nr, nc)) {
                continue;
            }
            if (grid[nr][nc] != '.' || visitedComponent[nr][nc]) {
                continue;
            }

            Point src = componentSource[nr][nc];
            if (src == null) {
                continue;
            }

            sum += componentSize[src.row][src.col];
            visitedComponent[src.row][src.col] = true;
        }

        return (char) ('0' + (sum % 10));
    }

    /** Convenience method to check bounds. */
    private boolean isInBounds(int row, int col) {
        return row >= 0 && row < grid.length && col >= 0 && col < grid[0].length;
    }

    /**
     * Generates the output grid and writes it to {@code System.out}.
     */
    private void writeOutput() {
        StringBuilder sb = new StringBuilder();

        for (int r = 0; r < grid.length; r++) {
            for (int c = 0; c < grid[0].length; c++) {
                if (grid[r][c] == '*') {
                    sb.append(computeDigitForObstacle(r, c));
                } else {
                    sb.append('.');
                }
            }
            System.out.println(sb.toString());
            sb.setLength(0); // reset for next line
        }
    }

    /** Simple wrapper around {@link Scanner} for reading tokens. */
    private static final class Scanner {
        private final java.util.Scanner scanner;

        Scanner(java.io.InputStream source) {
            this.scanner = new java.util.Scanner(source);
        }

        int nextInt() {
            return scanner.nextInt();
        }

        String next() {
            return scanner.next();
        }
    }

    /** Entry point – the only public method that ties everything together. */
    public static void main(String[] args) {
        Labyrinth labyrinth = readInput(new Scanner(System.in));
        labyrinth.computeComponentSizes();
        labyrinth.writeOutput();
    }
}

import java.io.IOException;
import java.io.PrintWriter;
import java.util.HashSet;
import java.util.Scanner;
import java.util.Set;

/**
 * Educational Round 5 – problem C.
 *
 * Reads a grid of '.' (empty) and '*' (blocked) cells.
 * Each blocked cell is replaced by a digit that represents
 * (1 + sum of sizes of neighbouring empty components) % 10.
 *
 * The program follows clean‑code principles:
 *   • Meaningful identifiers
 *   • Small, single‑purpose methods
 *   • Proper resource handling (try‑with‑resources)
 *   • No magic numbers scattered through the code
 */
public class Main {

    /** Symbol used for an empty (traversable) cell. */
    private static final char EMPTY = '.';
    /** Symbol used for a blocked cell. */
    private static final char BLOCKED = '*';

    /**
     * Entry point.
     *
     * @param args command line arguments (unused)
     * @throws IOException if input cannot be read
     */
    public static void main(String[] args) throws IOException {
        /* ---------- read input with automatic resource closing ---------- */
        try (Scanner scanner = new Scanner(System.in)) {
            int rows = scanner.nextInt();
            int cols = scanner.nextInt();
            scanner.nextLine();                 // skip end‑of‑line after the dimensions

            char[][] grid = readGrid(scanner, rows, cols);

            /* ---------- label connected components of empty cells ---------- */
            int[][] visited = new int[rows + 1][cols + 1];          // 1‑based indexing
            int[] componentSize = new int[rows * cols + 1];        // max possible components
            int currentComponentId = 1;

            for (int r = 1; r <= rows; r++) {
                for (int c = 1; c <= cols; c++) {
                    if (grid[r][c] == EMPTY && visited[r][c] == 0) {
                        int size = exploreComponent(grid, visited, r, c, currentComponentId);
                        componentSize[currentComponentId] = size;
                        currentComponentId++;
                    }
                }
            }

            /* ---------- build the answer grid ---------- */
            char[][] answer = new char[rows + 1][cols + 1];
            int[][] directions = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};   // up, down, left, right

            for (int r = 1; r <= rows; r++) {
                for (int c = 1; c <= cols; c++) {
                    if (grid[r][c] == BLOCKED) {
                        Set<Integer> neighbourIds = collectNeighbourComponentIds(
                                r, c, visited, directions, rows, cols);
                        int sum = 0;
                        for (int id : neighbourIds) {
                            sum += componentSize[id];
                        }
                        answer[r][c] = digit((sum + 1) % 10);
                    } else {
                        answer[r][c] = grid[r][c];
                    }
                }
            }

            /* ---------- output the result ---------- */
            StringBuilder sb = new StringBuilder();
            for (int r = 1; r <= rows; r++) {
                for (int c = 1; c <= cols; c++) {
                    sb.append(answer[r][c]);
                }
                sb.append('\n');
            }
            System.out.print(sb.toString());
        }
    }

    /** Reads the grid from the scanner (1‑based indexed storage). */
    private static char[][] readGrid(Scanner scanner, int rows, int cols) {
        char[][] grid = new char[rows + 1][cols + 1];
        for (int r = 1; r <= rows; r++) {
            String line = scanner.nextLine();
            for (int c = 1; c <= cols; c++) {
                grid[r][c] = line.charAt(c - 1);
            }
        }
        return grid;
    }

    /**
     * Depth‑first exploration of a single empty component.
     *
     * @param grid       the original grid
     * @param visited    component identifier matrix
     * @param r, c       current cell coordinates
     * @param id         identifier to assign to this component
     * @return the size of the component
     */
    private static int exploreComponent(char[][] grid, int[][] visited, int r, int c, int id) {
        visited[r][c] = id;
        int size = 1; // current cell counts

        // up
        if (r - 1 >= 1 && visited[r - 1][c] == 0 && grid[r - 1][c] == EMPTY) {
            size += exploreComponent(grid, visited, r - 1, c, id);
        }
        // down
        if (r + 1 < grid.length && visited[r + 1][c] == 0 && grid[r + 1][c] == EMPTY) {
            size += exploreComponent(grid, visited, r + 1, c, id);
        }
        // left
        if (c - 1 >= 1 && visited[r][c - 1] == 0 && grid[r][c - 1] == EMPTY) {
            size += exploreComponent(grid, visited, r, c - 1, id);
        }
        // right
        if (c + 1 < grid[0].length && visited[r][c + 1] == 0 && grid[r][c + 1] == EMPTY) {
            size += exploreComponent(grid, visited, r, c + 1, id);
        }

        return size;
    }

    /** Collects the ids of all distinct empty components adjacent to (r,c). */
    private static Set<Integer> collectNeighbourComponentIds(
            int r, int c, int[][] visited, int[][] dirs, int rows, int cols) {

        Set<Integer> ids = new HashSet<>();
        for (int[] d : dirs) {
            int nr = r + d[0];
            int nc = c + d[1];
            if (inBounds(nr, nc, rows, cols) && visited[nr][nc] != 0) {
                ids.add(visited[nr][nc]);
            }
        }
        return ids;
    }

    /** Simple bounds check used by {@link #collectNeighbourComponentIds}. */
    private static boolean inBounds(int x, int y, int rows, int cols) {
        return x >= 1 && x <= rows && y >= 1 && y <= cols;
    }

    /** Returns the decimal digit character for a value 0‑9. */
    private static char digit(int value) {
        return (char) ('0' + value);
    }
}

import java.io.*;
import java.util.*;

/**
 * Main class that contains the solution for the problem.
 * The program reads a matrix of '.' and '*' characters, builds a
 * union‑find structure over the '.' cells, determines the size of each
 * connected component and finally prints, for every '*', the number of
 * cells that would be reachable if that '*' were turned into '.'.
 *
 * The implementation is deliberately kept in a single file to match the
 * original format, but the code has been reorganised for readability,
 * maintainability and correctness.
 */
public class Main {

    /** Entry point */
    public static void main(String[] args) {
        FastScanner in = new FastScanner(System.in);
        FastWriter out = new FastWriter(System.out);
        new Solver().solve(in, out);
        out.close();
    }

    /** --------------------------------------------------------------------- */
    /** Solver – contains all algorithmic steps of the program               */
    private static class Solver {

        /** Directions: down, left, up, right */
        private final int[][] DIRS = {{1, 0}, {0, -1}, {-1, 0}, {0, 1}};

        /** Utility: convert (row, col) into a linear index for Union‑Find */
        private static int idx(int r, int c, int cols) {
            return r * cols + c;
        }

        /** Utility: check bounds */
        private boolean inside(int r, int c, int rows, int cols) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }

        /** ----------------------------------------------------------------- */
        /** Solves the problem for the given input scanner and output writer   */
        void solve(FastScanner in, FastWriter out) {
            int rows = in.nextInt();
            int cols = in.nextInt();
            char[][] grid = new char[rows][];
            for (int r = 0; r < rows; r++) {
                grid[r] = in.readChars(cols);
            }

            int total = rows * cols;
            UnionFind uf = new UnionFind(total);

            /* -------------------------------------------------------------
             * 1. Build Union‑Find linking every '.' with its down/right neighbour
             * ------------------------------------------------------------- */
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (grid[r][c] == '*') continue;

                    // down neighbour
                    if (r + 1 < rows && grid[r + 1][c] == '.') {
                        uf.union(idx(r, c, cols), idx(r + 1, c, cols));
                    }
                    // right neighbour
                    if (c + 1 < cols && grid[r][c + 1] == '.') {
                        uf.union(idx(r, c, cols), idx(r, c + 1, cols));
                    }
                }
            }

            /* -------------------------------------------------------------
             * 2. Compute size of each connected component (by root)
             * ------------------------------------------------------------- */
            Map<Integer, Integer> componentSize = new HashMap<>();
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (grid[r][c] == '.') {
                        int root = uf.find(idx(r, c, cols));
                        componentSize.merge(root, 1, Integer::sum);
                    }
                }
            }

            /* -------------------------------------------------------------
             * 3. Build the answer matrix
             *    - walls stay '.'  (initial fill)
             *    - for every wall we add the sizes of adjacent distinct components
             * ------------------------------------------------------------- */
            char[][] answer = new char[rows][];
            for (int r = 0; r < rows; r++) {
                answer[r] = new char[cols];
                Arrays.fill(answer[r], '.');
            }

            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (grid[r][c] == '*') {
                        Set<Integer> neighbourRoots = new HashSet<>();

                        for (int[] d : DIRS) {
                            int nr = r + d[0];
                            int nc = c + d[1];
                            if (inside(nr, nc, rows, cols) && grid[nr][nc] == '.') {
                                int root = uf.find(idx(nr, nc, cols));
                                neighbourRoots.add(root);
                            }
                        }

                        int sum = 1; // the wall itself
                        for (int root : neighbourRoots) {
                            sum += componentSize.getOrDefault(root, 0);
                        }
                        answer[r][c] = (char) ('0' + (sum % 10));
                    }
                }
            }

            /* -------------------------------------------------------------
             * 4. Output
             * ------------------------------------------------------------- */
            for (char[] row : answer) {
                out.println(row);
            }
        }

        /** ----------------------------------------------------------------- */
        /** Union‑Find (Disjoint Set Union) implementation with path compression */
        private static class UnionFind {
            private final int[] parent;
            private final int[] rank;

            UnionFind(int n) {
                parent = new int[n];
                rank = new int[n];
                for (int i = 0; i < n; i++) parent[i] = i;
            }

            /** Find with path compression */
            int find(int x) {
                if (parent[x] != x) {
                    parent[x] = find(parent[x]);
                }
                return parent[x];
            }

            /** Union by rank – returns true iff a merge really happened */
            boolean union(int a, int b) {
                a = find(a);
                b = find(b);
                if (a == b) return false;

                // union by rank
                if (rank[a] < rank[b]) {
                    int tmp = a; a = b; b = tmp;
                }
                parent[b] = a;
                if (rank[a] == rank[b]) rank[a]++;

                return true;
            }
        }
    }

    /** ------------------------------------------------------------------------- */
    /** Very small fast scanner – reads ints and char arrays efficiently       */
    private static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream stream) {
            this.in = stream;
        }

        private int readByte() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        /** Reads next integer (skipping whitespace) */
        int nextInt() throws IOException {
            int c, sign = 1, val = 0;
            do { c = readByte(); } while (c <= ' ' && c != -1);
            if (c == '-') { sign = -1; c = readByte(); }
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = readByte();
            }
            return val * sign;
        }

        /** Reads exactly {@code n} characters (used for matrix rows) */
        char[] readChars(int n) throws IOException {
            char[] arr = new char[n];
            for (int i = 0; i < n; i++) arr[i] = (char) readByte();
            return arr;
        }
    }

    /** ------------------------------------------------------------------------- */
    /** Very small fast writer – simply delegates to a PrintWriter               */
    private static class FastWriter {
        private final PrintWriter out;
        FastWriter(OutputStream stream) {
            this.out = new PrintWriter(new BufferedWriter(new OutputStreamWriter(stream)));
        }
        void println(char[] data) {
            out.println(new String(data));
        }
        void close() {
            out.close();
        }
    }
}

import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Scanner;
import java.util.Set;
import java.util.stream.Collectors;

/**
 * Solution for CodeForces problem 616C – «Поле».
 *
 * <p>Refactoring goals:
 * <ul>
 *   <li>Clear naming and modularisation.</li>
 *   <li>Eliminate magic numbers and duplicated code.</li>
 *   <li>Separate concerns (input, processing, output).</li>
 *   <li>Use expressive constants and helper methods.</li>
 * </ul>
 */
public class CF616C {

    /** Symbol used for empty cells in the final printed grid. */
    private static final char EMPTY_SYMBOL = '.';

    /** Marker for cells that have not been visited yet. */
    private static final int UNVISITED = -1;

    /** Directions used for neighbour checks (up, down, left, right). */
    private static final int[][] NEIGHBOUR_DIRECTIONS = {
            {-1, 0}, {1, 0}, {0, -1}, {0, 1}
    };

    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            int rows = scanner.nextInt();
            int cols = scanner.nextInt();
            scanner.nextLine();                 // consume end‑of‑line

            char[][] inputGrid = readInput(rows, cols, scanner);
            int[][] componentIndex = labelComponents(inputGrid, rows, cols);
            List<Integer> componentSizes = computeComponentSizes(componentIndex, rows, cols);
            char[][] resultGrid = buildResultGrid(componentIndex, componentSizes, rows, cols);

            printResult(resultGrid);
        }
    }

    /** Reads the whole input grid from {@link Scanner}. */
    private static char[][] readInput(int rows, int cols, Scanner scanner) {
        char[][] grid = new char[rows][cols];
        for (int r = 0; r < rows; r++) {
            String line = scanner.nextLine();
            for (int c = 0; c < cols; c++) {
                grid[r][c] = line.charAt(c);
            }
        }
        return grid;
    }

    /**
     * Assigns a unique positive index to each contiguous empty region.
     * Empty cells ('.') receive a non‑zero index; wall cells ('#') stay {@code 0}.
     *
     * @return matrix of component indices.
     */
    private static int[][] labelComponents(char[][] grid, int rows, int cols) {
        int[][] indices = new int[rows][cols];
        int nextIndex = 1; // 1‑based to simplify size‑list lookup

        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '.' && indices[r][c] == 0) {
                    dfsAssignIndex(grid, indices, nextIndex, r, c);
                    nextIndex++;
                }
            }
        }
        return indices;
    }

    /** Depth‑first search that marks a component with {@code index}. */
    private static void dfsAssignIndex(char[][] grid, int[][] indices, int index, int r, int c) {
        if (!isInBounds(grid, r, c) || grid[r][c] != '.' || indices[r][c] != 0) {
            return;
        }
        indices[r][c] = index;
        dfsAssignIndex(grid, indices, index, r + 1, c);
        dfsAssignIndex(grid, indices, index, r - 1, c);
        dfsAssignIndex(grid, indices, index, r, c + 1);
        dfsAssignIndex(grid, indices, index, r, c - 1);
    }

    /** Counts cells belonging to a given component index. */
    private static int countComponentSize(int[][] indices, int componentId, int rows, int cols) {
        int size = 0;
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (indices[r][c] == componentId) {
                    size++;
                }
            }
        }
        return size;
    }

    /**
     * Computes the size of every component that was labelled in {@code indices}.
     *
     * @return list where element {@code i} is the size of component {@code i+1}.
     */
    private static List<Integer> computeComponentSizes(int[][] indices, int rows, int cols) {
        // Find the highest component id first to know how many sizes we need.
        int maxId = 0;
        for (int[] row : indices) {
            for (int id : row) {
                if (id > maxId) {
                    maxId = id;
                }
            }
        }
        List<Integer> sizes = new ArrayList<>(maxId);
        for (int id = 1; id <= maxId; id++) {
            sizes.add(countComponentSize(indices, id, rows, cols));
        }
        return sizes;
    }

    /**
     * Builds the output grid.
     * <ul>
     *   <li>Wall cells ('#') are replaced by a digit representing the sum of
     *       neighbouring component sizes (mod 10).</li>
     *   <li>Empty cells ('.') stay as {@code EMPTY_SYMBOL}.</li>
     * </ul>
     */
    private static char[][] buildResultGrid(int[][] indices,
                                            List<Integer> componentSizes,
                                            int rows,
                                            int cols) {
        char[][] result = new char[rows][cols];

        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (indices[r][c] == 0) {                     // original wall cell
                    Set<Integer> neighbourComponentIds = new HashSet<>();

                    for (int[] dir : NEIGHBOUR_DIRECTIONS) {
                        int nr = r + dir[0];
                        int nc = c + dir[1];
                        if (isInBounds(indices, nr, nc) && indices[nr][nc] > 0) {
                            neighbourComponentIds.add(indices[nr][nc]);
                        }
                    }
                    int sum = neighbourComponentIds.stream()
                            .mapToInt(id -> componentSizes.get(id - 1))
                            .sum();
                    result[r][c] = Character.forDigit(sum % 10, 10);
                } else {
                    result[r][c] = EMPTY_SYMBOL;
                }
            }
        }
        return result;
    }

    /** Simple bounds check for a rectangular matrix. */
    private static boolean isInBounds(int[][] matrix, int r, int c) {
        return r >= 0 && r < matrix.length && c >= 0 && c < matrix[0].length;
    }

    /** Prints the resulting grid line by line. */
    private static void printResult(char[][] grid) {
        for (char[] line : grid) {
            System.out.println(new String(line));
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * LabyrinthSolver reads a grid consisting of '.' (empty) and '*' (wall),
 * computes the size of each empty‑cell connected component and, for every
 * wall cell, prints the sum of the sizes of the distinct neighboring
 * components modulo 10.
 *
 * The code is deliberately split into small, focussed methods and
 * encapsulated in a single class to keep the public API tiny.
 */
public final class LabyrinthSolver {

    /** Character used for empty cells. */
    private static final char EMPTY = '.';
    /** Character used for walls. */
    private static final char WALL = '*';
    /** Four possible move directions. */
    private static final int[][] DIRS = {{0, 1}, {1, 0}, {0, -1}, {-1, 0}};

    /** Global counter for component identifiers. */
    private static int nextComponentId = 1;

    /** Grid read from input. */
    private final char[][] grid;
    /** Component identifier for each cell (‑1 = not part of any component). */
    private final int[][] componentId;
    /** Size of each component indexed by its identifier. */
    private final int[] componentSize;

    /** Simple container for a pair of coordinates. */
    private static final class Pos {
        final int row, col;
        Pos(int r, int c) { this.row = r; this.col = c; }
    }

    public LabyrinthSolver(char[][] grid) {
        this.grid = grid;
        int rows = grid.length;
        int cols = grid[0].length;
        this.componentId = new int[rows][cols];
        this.componentSize = new int[rows * cols + 1]; // safe upper bound
        Arrays.fill(componentId, -1);
    }

    /** Entry point – reads input, processes the labyrinth and prints the result. */
    public static void main(String[] args) throws IOException {
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
             PrintWriter pw = new PrintWriter(System.out)) {

            // ---------- read dimensions and grid ----------
            String[] header = br.readLine().split("\\s+");
            int rows = Integer.parseInt(header[0]);
            int cols = Integer.parseInt(header[1]);

            char[][] inputGrid = new char[rows][];
            for (int r = 0; r < rows; r++) {
                inputGrid[r] = br.readLine().trim().toCharArray();
            }

            // ---------- solve ----------
            LabyrinthSolver solver = new LabyrinthSolver(inputGrid);
            solver.computeComponents();
            StringBuilder out = solver.buildResult();
            pw.print(out.toString());
        }
    }

    /** Assigns a unique id to every empty component and records its size. */
    private void computeComponents() {
        int currentId = nextComponentId;
        for (int r = 0; r < grid.length; r++) {
            for (int c = 0; c < grid[r].length; c++) {
                if (grid[r][c] == EMPTY && componentId[r][c] == -1) {
                    bfsAssignComponent(r, c, currentId++);
                }
            }
        }
        nextComponentId = currentId; // remember the next free id for later runs
    }

    /** Breadth‑first search that marks all cells of one component with `id`
     *  and stores the component's size in {@code componentSize[id]}. */
    private void bfsAssignComponent(int startR, int startC, int id) {
        Deque<Pos> queue = new ArrayDeque<>();
        queue.add(new Pos(startR, startC));
        componentId[startR][startC] = id;
        int size = 0;

        while (!queue.isEmpty()) {
            Pos cur = queue.poll();
            int r = cur.row, c = cur.col;
            size++;

            for (int[] d : DIRS) {
                int nr = r + d[0];
                int nc = c + d[1];
                if (isInBounds(nr, nc) && grid[nr][nc] == EMPTY && componentId[nr][nc] == -1) {
                    componentId[nr][nc] = id;
                    queue.add(new Pos(nr, nc));
                }
            }
        }
        componentSize[id] = size;
    }

    /** Returns a string representation of the transformed grid. */
    private StringBuilder buildResult() {
        StringBuilder sb = new StringBuilder();
        for (int r = 0; r < grid.length; r++) {
            for (int c = 0; c < grid[r].length; c++) {
                char outChar = (grid[r][c] == EMPTY) ? EMPTY
                                                    : computeWallValue(r, c);
                sb.append(outChar);
            }
            sb.append('\n');
        }
        return sb;
    }

    /** For a wall cell (`*`) computes the required digit from its neighboring
     *  distinct components. */
    private char computeWallValue(int r, int c) {
        Set<Integer> neighbourIds = new HashSet<>();

        for (int[] d : DIRS) {
            int nr = r + d[0];
            int nc = c + d[1];
            if (isInBounds(nr, nc) && componentId[nr][nc] > 0) {
                neighbourIds.add(componentId[nr][nc]);
            }
        }

        int sum = 1; // count the wall cell itself
        for (int id : neighbourIds) {
            sum += componentSize[id];
        }
        return (char) ('0' + (sum % 10));
    }

    /** Utility – checks whether coordinates are inside the processed matrix. */
    private boolean isInBounds(int row, int col) {
        return row >= 0 && row < grid.length && col >= 0 && col < grid[0].length;
    }
}

import java.awt.Point;
import java.io.*;
import java.util.*;

/**
 * Solves the described grid problem.
 * <p>
 *   - Reads an {@code n × m} grid from standard input.
 *   - Assigns a numeric identifier and size to each connected component of '.'.
 *   - For each '*' cell, prints the sum of the sizes (mod 10) of the distinct
 *     neighboring components; otherwise prints '.'.
 * </p>
 */
public final class Main {

    /** Directions: up, down, left, right */
    private static final int[][] DIRECTIONS = {
            {-1, 0}, {1, 0}, {0, -1}, {0, 1}
    };

    /** Separator for input numbers */
    private static final String TOKEN_DELIMITER = " ";

    /** Character used to mark visited cells during component discovery */
    private static final char MARK_VISITED = '-';
    /** Character used to mark processed cells during second pass */
    private static final char MARK_PROCESSED = '+';

    private Main() { /* utility class – no instances */ }

    public static void main(String[] args) throws IOException {
        // --------------------------------------------------------------------
        // 1. Input handling (try‑with‑resources guarantees proper closing)
        // --------------------------------------------------------------------
        try (BufferedReader reader = new BufferedReader(
                new InputStreamReader(System.in));
             PrintWriter writer = new PrintWriter(
                     new OutputStreamWriter(System.out))) {

            // ----- read dimensions -------------------------------------------------
            String[] header = reader.readLine().split(TOKEN_DELIMITER);
            final int rows = Integer.parseInt(header[0]);
            final int cols = Integer.parseInt(header[1]);

            // ----- read grid -------------------------------------------------------
            char[][] grid = new char[rows][cols];
            for (int r = 0; r < rows; r++) {
                grid[r] = reader.readLine().toCharArray();
            }

            // --------------------------------------------------------------------
            // 2. Component labeling (find connected '.' components)
            // --------------------------------------------------------------------
            ComponentInfo[][] componentInfo = new ComponentInfo[rows][cols];
            int componentId = 0;

            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (grid[r][c] == '.' && componentInfo[r][c] == null) {
                        componentId++;
                        exploreComponent(grid, componentInfo, r, c, componentId);
                    }
                }
            }

            // --------------------------------------------------------------------
            // 3. Produce output – evaluate each '*' cell
            // --------------------------------------------------------------------
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    char cell = grid[r][c];
                    if (cell == '*') {
                        int result = computeStarValue(grid, componentInfo, r, c);
                        writer.print(result);
                    } else {
                        writer.print('.');
                    }
                }
                writer.println(); // new line after each row
            }
        }
    }

    /**
     * Depth‑first exploration of a '.' component.
     *
     * @param grid       the original grid (modified temporarily)
     * @param info       matrix that stores component information
     * @param startRow   starting row of the component
     * @param startCol   starting column of the component
     * @param id         unique identifier for the component
     */
    private static void exploreComponent(char[][] grid,
                                         ComponentInfo[][] info,
                                         int startRow,
                                         int startCol,
                                         int id) {
        Deque<Point> stack = new ArrayDeque<>();
        stack.push(new Point(startRow, startCol));

        // mark the start cell as visited to avoid enqueueing it twice
        grid[startRow][startCol] = MARK_VISITED;

        int size = 0;
        while (!stack.isEmpty()) {
            Point cur = stack.poll();
            size++;

            // process neighbours
            for (int[][] dir : DIRECTIONS) {
                int nr = cur.x + dir[0];
                int nc = cur.y + dir[1];
                if (isInBounds(grid, nr, nc) && grid[nr][nc] == '.') {
                    grid[nr][nc] = MARK_VISITED;   // mark before enqueueing
                    stack.push(new Point(nr, nc));
                }
            }
        }

        // After the whole component is collected, fill the info matrix.
        // We perform a second pass using a queue that restores the original
        // '.' characters while populating the count and id fields.
        transferComponentInfo(grid, info, id, size);
    }

    /**
     * Transfers the computed size into the corresponding cells and restores
     * the grid characters to '+' (processed) while assigning the unique id.
     */
    private static void transferComponentInfo(char[][] grid,
                                              ComponentInfo[][] info,
                                              int id,
                                              int size) {
        Deque<Point> queue = new ArrayDeque<>();
        // locate the first 'VISITED' cell (any cell of the component works)
        outer:
        for (int r = 0; r < grid.length; r++) {
            for (int c = 0; c < grid[r].length; c++) {
                if (grid[r][c] == MARK_VISITED) {
                    queue.push(new Point(r, c));
                    break outer;
                }
            }
        }

        while (!queue.isEmpty()) {
            Point cur = queue.poll();
            int x = cur.x;
            int y = cur.y;
            info[x][y] = new ComponentInfo(size, id);
            grid[x][y] = MARK_PROCESSED; // mark as processed

            for (int[][] dir : DIRECTIONS) {
                int nx = x + dir[0];
                int ny = y + dir[1];
                if (isInBounds(grid, nx, ny) && grid[nx][ny] == MARK_VISITED) {
                    grid[nx][ny] = MARK_PROCESSED; // avoid revisiting
                    queue.push(new Point(nx, ny));
                }
            }
        }
    }

    /**
     * Computes the required value for a '*' cell.
     *
     * @param grid       the original grid
     * @param info       component information matrix
     * @param row        row index of '*'
     * @param col        column index of '*'
     * @return the sum of neighboring component sizes modulo 10
     */
    private static int computeStarValue(char[][] grid,
                                        ComponentInfo[][] info,
                                        int row,
                                        int col) {
        Set<Integer> seenIds = new HashSet<>();
        int total = 0;

        for (int[][] dir : DIRECTIONS) {
            int nr = row + dir[0];
            int nc = col + dir[1];
            if (isInBounds(grid, nr, nc) && grid[nr][nc] == '+') {
                int compId = info[nr][nc].componentId;
                if (seenIds.add(compId)) { // only count each component once
                    total = (total + info[nr][nc].size) % 10;
                }
            }
        }
        return total;
    }

    /** Helper to test array bounds. */
    private static boolean isInBounds(char[][] grid, int r, int c) {
        return r >= 0 && r < grid.length && c >= 0 && c < grid[0].length;
    }

    /** Simple container for component size and identifier. */
    private static final class ComponentInfo {
        private final int size;          // number of cells in the component
        private final int componentId;   // unique id assigned during labeling

        ComponentInfo(int size, int componentId) {
            this.size = size;
            this.componentId = componentId;
        }
    }
}

import java.io.IOException;
import java.util.HashSet;
import java.util.Set;

/**
 * Refactored solution.
 *
 * <p>
 * The program reads a rectangular grid consisting of '.' (free cells) and '#'
 * (blocked cells). It:
 * <ul>
 *   <li>labels each connected component of '.' with a unique identifier,
 *       counting the size of each component,</li>
 *   <li>for every '.' cell computes the sum of the sizes of the distinct
 *       neighboring components plus one, modulo 10,</li>
 *   <li>prints the computed digit for '.' cells and '.' for blocked cells.</li>
 * </ul>
 * The refactor focuses on readability, maintainability and proper
 * encapsulation while preserving the original behaviour.
 */
public class Main {

    /** Grid characters */
    private static char[][] grid;

    /** Component identifier for each cell (0 means not visited or blocked) */
    private static int[][] componentId;

    /** Size of each component, indexed by component id */
    private static int[] componentSize;

    /** Conservative upper bound for the number of components */
    private static final int MAX_COMPONENTS = 1_000_000;

    public static void main(String[] args) throws IOException {
        // Scanner provides convenient tokenised input; try‑with‑resources ensures closing
        try (java.util.Scanner sc = new java.util.Scanner(System.in)) {
            int rows = sc.nextInt();
            int cols = sc.nextInt();

            // Initialise data structures
            grid = new char[rows][cols];
            componentId = new int[rows][cols];
            componentSize = new int[MAX_COMPONENTS];

            // Read all grid lines
            for (int i = 0; i < rows; i++) {
                String line = sc.next();
                System.arraycopy(line.toCharArray(), 0, grid[i], 0, cols);
            }

            // Assign component ids and compute component sizes
            int nextId = 1;
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (grid[i][j] == '.' && componentId[i][j] == 0) {
                        dfsLabel(i, j, nextId);
                        nextId++;
                    }
                }
            }

            // Build the output string
            StringBuilder sb = new StringBuilder();
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (grid[i][j] == '#') {
                        sb.append('.'); // Original program printed '.' for blocked cells
                    } else {
                        int value = 1; // Base contribution
                        Set<Integer> adjacent = new HashSet<>();

                        // Examine the four neighbours
                        if (i > 0 && componentId[i - 1][j] != 0 && !adjacent.contains(componentId[i - 1][j])) {
                            adjacent.add(componentId[i - 1][j]);
                            value += componentSize[componentId[i - 1][j]];
                        }
                        if (i + 1 < rows && componentId[i + 1][j] != 0 && !adjacent.contains(componentId[i + 1][j])) {
                            adjacent.add(componentId[i + 1][j]);
                            value += componentSize[componentId[i + 1][j]];
                        }
                        if (j > 0 && componentId[i][j - 1] != 0 && !adjacent.contains(componentId[i][j - 1])) {
                            adjacent.add(componentId[i][j - 1]);
                            value += componentSize[componentId[i][j - 1]];
                        }
                        if (j + 1 < cols && componentId[i][j + 1] != 0 && !adjacent.contains(componentId[i][j + 1])) {
                            value += componentSize[componentId[i][j + 1]];
                        }

                        sb.append((char) ('0' + (value % 10)));
                    }
                }
                sb.append('\n');
            }

            System.out.print(sb.toString());
        }
    }

    /**
     * Depth‑first search that labels all cells of the same component
     * with the given identifier and counts its size.
     *
     * @param i row index of the current cell
     * @param j column index of the current cell
     * @param id identifier to assign to the component
     */
    private static void dfsLabel(int i, int j, int id) {
        // Boundary and visitation checks
        if (i < 0 || i >= grid.length || j < 0 || j >= grid[0].length) {
            return;
        }
        if (grid[i][j] != '.' || componentId[i][j] != 0) {
            return;
        }

        // Mark the cell with the current component id and increment its size
        componentId[i][j] = id;
        componentSize[id]++;

        // Recurse to the four neighbours
        dfsLabel(i + 1, j, id);
        dfsLabel(i - 1, j, id);
        dfsLabel(i, j + 1, id);
        dfsLabel(i, j - 1, id);
    }
}

import java.io.*;
import java.util.HashSet;
import java.util.Set;

/**
 * Entry point of the program.
 * Reads the labyrinth description from standard input,
 * solves it and prints the result to standard output.
 */
public class Main {

    public static void main(String[] args) {
        /* --------------------------------------------------------------
         * Input handling – using BufferedReader / PrintWriter for clarity.
         * The whole I/O is wrapped in try‑with‑resources so streams are
         * closed automatically.
         * -------------------------------------------------------------- */
        try (BufferedReader br = new BufferedReader(
                     new InputStreamReader(System.in));
             PrintWriter out = new PrintWriter(
                     new BufferedWriter(
                             new OutputStreamWriter(System.out)))) {

            /* ----- read dimensions ------------------------------------------------ */
            String[] dims = br.readLine().split("\\s+");
            int n = Integer.parseInt(dims[0]);
            int m = Integer.parseInt(dims[1]);

            /* ----- read grid -------------------------------------------------------- */
            char[][] grid = new char[n][];
            for (int i = 0; i < n; i++) {
                grid[i] = br.readLine().trim().toCharArray();
            }

            /* ----- solve ------------------------------------------------------------ */
            LabyrinthSolver solver = new LabyrinthSolver(n, m, grid, out);
            solver.solve();

            out.flush();          // ensure all data is written
        } catch (IOException e) {
            throw new RuntimeException(e);
        }
    }

    /**
     * Core component that builds the connectivity graph of empty cells
     * ('.') and produces the required output for each cell.
     */
    private static final class LabyrinthSolver {
        private final int n;
        private final int m;
        private final char[][] grid;
        private final DisjointSet ds;
        private final PrintWriter out;

        LabyrinthSolver(int n, int m, char[][] grid, PrintWriter out) {
            this.n = n;
            this.m = m;
            this.grid = grid;
            this.ds = new DisjointSet(n * m);
            this.out = out;
        }

        /** Connects adjacent empty cells using a Union‑Find structure. */
        private void buildConnectivity() {
            for (int r = 0; r < n; r++) {
                for (int c = 0; c < m; c++) {
                    if (grid[r][c] == '.') {
                        unionIfEmpty(r, c, r - 1, c);
                        unionIfEmpty(r, c, r, c + 1);
                        unionIfEmpty(r, c, r + 1, c);
                        unionIfEmpty(r, c, r, c - 1);
                    }
                }
            }
        }

        /** Helper that unions the current cell with a neighbour if both are empty. */
        private void unionIfEmpty(int r1, int c1, int r2, int c2) {
            if (isInBounds(r2, c2) && grid[r2][c2] == '.') {
                ds.union(index(r1, c1), index(r2, c2));
            }
        }

        /** Linear index of a cell inside the Union‑Find array. */
        private int index(int r, int c) {
            return r * m + c;
        }

        /** Checks whether a coordinate lies inside the grid. */
        private boolean isInBounds(int r, int c) {
            return r >= 0 && r < n && c >= 0 && c < m;
        }

        /** Generates and prints the answer for every cell. */
        private void solve() {
            buildConnectivity();

            for (int r = 0; r < n; r++) {
                for (int c = 0; c < m; c++) {
                    if (grid[r][c] == '.') {
                        out.print('.');
                    } else {
                        Set<Integer> neighbourRoots = collectNeighbourRoots(r, c);
                        int sum = 0;
                        for (int root : neighbourRoots) {
                            sum = (sum + ds.size(root)) % 10;
                        }
                        int result = (sum + 1) % 10;
                        out.print(result);
                    }
                }
                out.println();
            }
        }

        /** Returns the distinct DSU roots of the four orthogonal neighbours that are empty. */
        private Set<Integer> collectNeighbourRoots(int r, int c) {
            Set<Integer> roots = new HashSet<>();
            int[][] dirs = {{-1, 0}, {0, 1}, {1, 0}, {0, -1}};
            for (int[] d : dirs) {
                int nr = r + d[0];
                int nc = c + d[1];
                if (isInBounds(nr, nc) && grid[nr][nc] == '.') {
                    roots.add(ds.find(index(nr, nc)));
                }
            }
            return roots;
        }
    }

    /**
     * Simple Union‑Find (Disjoint Set Union) data structure.
     * Provides find with path compression, union by size and a size() helper.
     */
    private static final class DisjointSet {
        private final int[] parent;
        private final int[] size;

        DisjointSet(int capacity) {
            parent = new int[capacity];
            size = new int[capacity];
            for (int i = 0; i < capacity; i++) {
                parent[i] = i;
                size[i] = 1;
            }
        }

        /** Finds the root of x with path compression. */
        int find(int x) {
            if (parent[x] != x) {
                parent[x] = find(parent[x]);
            }
            return parent[x];
        }

        /** Merges the sets of a and b. */
        void union(int a, int b) {
            a = find(a);
            b = find(b);
            if (a == b) return;

            if (size[a] >= size[b]) {
                parent[b] = a;
                size[a] += size[b];
            } else {
                parent[a] = b;
                size[b] += size[a];
            }
        }

        /** Returns the number of elements in the component that contains x. */
        int size(int x) {
            return size[find(x)];
        }
    }
}

package main;                       // you can delete the package line if you prefer default package

import java.io.*;
import java.util.HashSet;
import java.util.Set;

/**
 * Constants, utilities and the core processing logic.
 */
final class Constants {
    /** Maximum size used in the original program – kept for API compatibility. */
    static final int DEFAULT_MAX_N = 27_501_321;
}

/**
 * Simple representation of a direction vector (dx, dy).
 */
final class Direction {
    final int dx, dy;

    Direction(int dx, int dy) {
        this.dx = dx;
        this.dy = dy;
    }

    static final Direction UP     = new Direction(-1,  0);
    static final Direction DOWN   = new Direction( 1,  0);
    static final Direction LEFT   = new Direction( 0, -1);
    static final Direction RIGHT  = new Direction( 0,  1);

    /** Helper array to iterate over the four neighbours without a stream. */
    private static final Direction[] VALUES = {
            UP, DOWN, LEFT, RIGHT
    };
    static Direction[] values() {
        return VALUES.clone();         // defensive copy – callers may mutate it
    }
}

/**
 * Holds the whole grid and the operations that can be performed on it.
 *
 * <p>All mutating operations are confined to this class – the `main` method
 * merely orchestrates I/O.
 */
final class GridProcessor {

    private final int rows;                     // m in the original code
    private final int cols;                     // n in the original code
    private final char[][] rawGrid;             // '.' == open cell, otherwise blocked
    private final int[][] componentId;          // component index for every cell (0 = none)
    private final int[][] componentSize;        // size of each component (1‑based index)
    private final int[][] adjacencySum;         // number painted on each '.' cell
    private int nextComponentIdx = 2;           // start after 0 and 1 (keep compatibility)

    GridProcessor(int rows, int cols, char[][] rawGrid) {
        this.rows = rows;
        this.cols = cols;
        this.rawGrid = rawGrid;
        initStructures();
    }

    /** Allocate all 2‑D arrays that are needed throughout the algorithm. */
    private void initStructures() {
        componentId    = new int[rows + 1][cols + 1];
        componentSize  = new int[1_000_001];      // matches the original static array size
        adjacencySum   = new int[rows + 1][cols + 1];
    }

    /**
     * Scan the grid, assign a unique id to each connected component of open cells
     * (marked with '.'), and count the size of each component.
     */
    void labelComponents() {
        for (int r = 1; r <= rows; r++) {
            for (int c = 1; c <= cols; c++) {
                if (rawGrid[r - 1][c - 1] == '.' && componentId[r][c] == 0) {
                    int newIdx = nextComponentIdx++;
                    bfsLabel(r, c, newIdx);
                }
            }
        }

        // count cells per component
        for (int r = 1; r <= rows; r++) {
            for (int c = 1; c <= cols; c++) {
                int id = componentId[r][c];
                if (id != 0) {
                    componentSize[id]++;          // automatically packages overflow into the huge int array
                }
            }
        }
    }

    /** Breadth‑first flood‑fill that labels all cells belonging to the same component. */
    private void bfsLabel(int startR, int startC, int idx) {
        java.util.Queue<Point> q = new java.util.ArrayDeque<>();
        q.add(new Point(startR, startC));
        componentId[startR][startC] = idx;

        while (!q.isEmpty()) {
            Point cur = q.poll();
            for (Direction dir : Direction.values()) {
                Point nb = new Point(cur.r + dir.dx, cur.c + dir.dy);
                if (isInside(nb.r, nb.c) && rawGrid[nb.r - 1][nb.c - 1] == '.' && componentId[nb.r][nb.c] == 0) {
                    componentId[nb.r][nb.c] = idx;
                    q.add(nb);
                }
            }
        }
    }

    /** Helper that tells whether a coordinate lies inside the matrix. */
    private boolean isInside(int r, int c) {
        return r > 0 && r <= rows && c > 0 && c <= cols;
    }

    /**
     * For every blocked cell (character not '.'), look at its four orthogonal neighbours.
     * If a neighbour belongs to a component, add that component's size to the blocked cell.
     * The result is stored modulo‑10 in {@code adjacencySum}.
     */
    void computeAdjacencySums() {
        for (int r = 1; r <= rows; r++) {
            for (int c = 1; c <= cols; c++) {
                if (componentId[r][c] != 0) {
                    continue; // only interested in blocked cells
                }
                Set<Integer> adjacentComponents = new HashSet<>();
                for (Direction dir : Direction.values()) {
                    int nr = r + dir.dx;
                    int nc = c + dir.dy;
