/**
 * Helper for reading tokens from {@link InputStream}.
 */
final class InputReader {

    private final BufferedReader reader;
    private StringTokenizer tokenizer;

    InputReader(InputStream stream) {
        this.reader = new BufferedReader(new InputStreamReader(stream), 32768);
    }

    /** Returns {@code true} if a next token is available. */
    private boolean hasNext() {
        while (tokenizer == null || !tokenizer.hasMoreTokens()) {
            try {
                String line = reader.readLine();
                if (line == null) {
                    return false;
                }
                tokenizer = new StringTokenizer(line);
            } catch (IOException e) {
                throw new RuntimeException(e);
            }
        }
        return true;
    }

    /** Reads the next token (non‑null). */
    String next() {
        if (!hasNext()) {
            throw new NoSuchElementException();
        }
        return tokenizer.nextToken();
    }

    /** Convenience method for reading an {@code int}. */
    int nextInt() {
        return Integer.parseInt(next());
    }
}

/**
 * Core logic of the problem.
 * <p>
 * The grid consists of empty cells ('.') and filled cells ('#'). Filled cells
 * belonging to the same connected component receive a unique positive id.
 * For each empty cell we compute the sum of the sizes of the distinct adjacent
 * components, take the last decimal digit and output it. Filled cells are
 * represented by '.' in the final output.
 */
final class ArtistComplexSolver {

    /** Directions used for connectivity checks. */
    private enum Direction {
        UP(-1, 0),
        DOWN(1, 0),
        LEFT(0, -1),
        RIGHT(0, 1);

        private final int dr;
        private final int dc;

        Direction(int dr, int dc) {
            this.dr = dr;
            this.dc = dc;
        }

        int[] delta() {
            return new int[]{dr, dc};
        }
    }

    /** Identifier of a connected component; 0 indicates an empty cell. */
    private int[][] color;   // component id per cell
    private long[] componentSize; // size of each component (index = id)

    /** Grid dimensions. */
    private int rows, cols;

    /** Reads the grid, assigns component ids and produces the required output. */
    void process(InputReader in, PrintWriter out) {
        rows = in.nextInt();
        cols = in.nextInt();

        char[][] grid = readGrid(in);
        initDataStructures(grid);

        int currentComponentId = 0;
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (color[r][c] == 0) {
                    currentComponentId++;
                    dfs(r, c, currentComponentId);
                }
            }
        }

        StringBuilder sb = new StringBuilder();
        for (int r = 0; r < rows; r++) {
            sb.setLength(0); // reset for each output row
            for (int c = 0; c < cols; c++) {
                if (color[r][c] > 0) {
                    sb.append('.'); // filled cell stays a dot
                } else {
                    sb.append(computeDigitForEmptyCell(r, c));
                }
            }
            out.println(sb);
        }
    }

    /** Reads the grid into a character matrix. */
    private char[][] readGrid(InputReader in) {
        char[][] grid = new char[rows][];
        for (int r = 0; r < rows; r++) {
            String line = in.next();
            grid[r] = line.toCharArray();
        }
        return grid;
    }

    /** Allocates auxiliary arrays and initializes them based on the grid. */
    private void initDataStructures(char[][] grid) {
        color = new int[rows][cols];
        componentSize = new long[rows * cols + 1]; // max possible id + 1

        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                boolean isEmpty = grid[r][c] == '.';
                color[r][c] = isEmpty ? 0 : -1; // -1 placeholder for filled cells before id assignment
            }
        }
    }

    /** Depth‑first search that labels all cells of a component with {@code id}. */
    private void dfs(int startR, int startC, int id) {
        // Use an explicit stack to avoid deep recursion on huge grids
        java.util.ArrayDeque<int[]> stack = new java.util.ArrayDeque<>();
        stack.push(new int[]{startR, startC});

        while (!stack.isEmpty()) {
            int[] cur = stack.pop();
            int r = cur[0];
            int c = cur[1];
            if (color[r][c] != 0) {
                continue; // already processed
            }
            color[r][c] = id;
            componentSize[id]++;

            for (Direction dir : Direction.values()) {
                int nr = r + dir.delta()[0];
                int nc = c + dir.delta()[1];
                if (inBounds(nr, nc) && color[nr][nc] == 0) {
                    stack.push(new int[]{nr, nc});
                }
            }
        }
    }

    /** Returns {@code true} if coordinates are inside the grid. */
    private boolean inBounds(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    /**
     * Computes the digit that must be printed for an empty cell at {@code (r,c)}.
     * The digit is {@code (sum of sizes of distinct neighboring components) % 10}.
     */
    private char computeDigitForEmptyCell(int r, int c) {
        Set<Integer> seenComponentIds = new HashSet<>();
        long totalSize = 0;

        for (Direction dir : Direction.values()) {
            int nr = r + dir.delta()[0];
            int nc = c + dir.delta()[1];
            if (!inBounds(nr, nc) || color[nr][nc] <= 0) {
                continue; // out of bounds or not part of a component
            }
            int compId = color[nr][nc];
            if (seenComponentIds.add(compId)) { // only count once per component
                totalSize += componentSize[compId];
            }
        }
        return Character.forDigit((int) (totalSize % 10), 10);
    }
}

import java.io.*;
import java.util.*;

/**
 * Refactored implementation of “The Labyrinth” problem.
 *
 * <p>Original behaviour is preserved:
 * <ul>
 *   <li>Empty cells ('.') are printed as '.'.</li>
 *   <li>For each wall cell ('*') the sum of sizes of distinct adjacent rooms
 *       modulo 10 is printed.</li>
 *   <li>Rooms are identified with a colour identifier and their size.</li>
 * </ul>
 * The code is split into small, cohesive classes, uses meaningful names,
 * final fields where possible and tries‑with‑resources for all I/O.
 */
public class Labyrinth {

    /* --------------------------------------------------------------------- */
    /* Constants                                                             */
    /* --------------------------------------------------------------------- */
    private static final char WALL = '*';
    private static final char EMPTY_OUT = '.';   // printed for empty cells

    /** four possible movement directions */
    private enum Direction {
        UP(-1, 0), DOWN(1, 0), LEFT(0, -1), RIGHT(0, 1);
        private final int dr, dc;
        Direction(int dr, int dc) { this.dr = dr; this.dc = dc; }
        int dr() { return dr; }
        int dc() { return dc; }
    }

    /* --------------------------------------------------------------------- */
    /* Core processing class                                                  */
    /* --------------------------------------------------------------------- */
    private static final class Processor {

        private final char[][] maze;          // input grid
        private final int[][] componentColor; // colour identifier of each cell
        private final int[][] componentSize;  // size of each component
        private final boolean[][] visited;    // visited flag for DFS
        private int nextColorId = 1;           // colour ids start at 1

        Processor(char[][] maze) {
            this.maze = maze;
            int r = maze.length;
            int c = maze[0].length;
            this.componentColor = new int[r][c];
            this.componentSize = new int[r][c];
            this.visited = new boolean[r][c];
        }

        /** Executes the whole algorithm and writes the answer to the supplied writer */
        void runAndPrint(Reader source, Writer destination) throws IOException {
            // All I/O is wrapped in try‑with‑resources to guarantee closure.
            try (BufferedReader br = new BufferedReader(source)) {
                // ------------------- read dimensions -------------------
                String dimLine = br.readLine();
                if (dimLine == null) throw new IllegalArgumentException("Empty input");
                StringTokenizer dimTok = new StringTokenizer(dimLine);
                int rows = Integer.parseInt(dimTok.nextToken());
                int cols = Integer.parseInt(dimTok.nextToken());

                // ------------------- read / validate the maze ----------
                // Ensure the previously allocated grid matches the declared size.
                if (rows != maze.length || cols != maze[0].length) {
                    maze = new char[rows][cols]; // re‑allocate if necessary
                }
                for (int i = 0; i < rows; i++) {
                    String line = br.readLine();
                    if (line == null || line.length() != cols) {
                        throw new IllegalArgumentException("Invalid row length");
                    }
                    for (int j = 0; j < cols; j++) {
                        maze[i][j] = line.charAt(j);
                    }
                }

                // ------------------- discover components -------------------
                int componentId = 1;
                for (int i = 0; i < rows; i++) {
                    for (int j = 0; j < cols; j++) {
                        if (maze[i][j] != WALL && componentColor[i][j] == 0) {
                            int area = dfsExplore(i, j);
                            floodfillAssign(i, j, componentId, area);
                            componentId++;
                        }
                    }
                }

                // ------------------- produce output -------------------
                try (PrintWriter out = new PrintWriter(destination, true)) {
                    for (int i = 0; i < rows; i++) {
                        for (int j = 0; j < cols; j++) {
                            if (maze[i][j] == WALL) {
                                int contribution = adjacentComponentSum(i, j);
                                out.print(contribution % 10);
                            } else {
                                out.print(EMPTY_OUT);
                            }
                        }
                        out.println();
                    }
                }
            }
        }

        /** Depth‑first search that returns the size of the component starting at (r,c) */
        private int dfsExplore(int startR, int startC) {
            int count = 0;
            Deque<Coord> stack = new ArrayDeque<>();
            stack.push(new Coord(startR, startC));
            visited[startR][startC] = true;
            while (!stack.isEmpty()) {
                Coord cur = stack.pop();
                count++;
                for (Direction d : Direction.values()) {
                    int nr = cur.r + d.dr();
                    int nc = cur.c + d.dc();
                    if (valid(nr, nc) && !visited[nr][nc]) {
                        visited[nr][nc] = true;
                        stack.push(new Coord(nr, nc));
                    }
                }
            }
            return count;
        }

        /** Flood‑fill the just discovered component with its colour id and size */
        private void floodfillAssign(int r, int c, int colourId, int size) {
            Queue<Coord> queue = new ArrayDeque<>();
            queue.add(new Coord(r, c));
            componentColor[r][c] = colourId;
            componentSize[r][c] = size;

            while (!queue.isEmpty()) {
                Coord cur = queue.poll();
                for (Direction d : Direction.values()) {
                    int nr = cur.r + d.dr();
                    int nc = cur.c + d.dc();
                    if (valid(nr, nc) && componentColor[nr][nc] == 0) {
                        componentColor[nr][nc] = colourId;
                        componentSize[nr][nc] = size;
                        queue.add(new Coord(nr, nc));
                    }
                }
            }
        }

        /** True when (r,c) lies inside the grid and points to a non‑wall cell */
        private boolean valid(int r, int c) {
            return r >= 0 && r < maze.length && c >= 0 && c < maze[0].length
                    && maze[r][c] != WALL;
        }

        /** Sum of sizes of distinct neighbouring components */
        private int adjacentComponentSum(int r, int c) {
            Set<Integer> seen = new HashSet<>();
            int sum = 0;
            for (Direction d : Direction.values()) {
                int nr = r + d.dr();
                int nc = c + d.dc();
                if (valid(nr, nc)) {
                    int col = componentColor[nr][nc];
                    if (col != 0 && seen.add(col)) {
                        sum += componentSize[nr][nc];
                    }
                }
            }
            return sum;
        }

        /** Simple holder for a pair of coordinates */
        private static final class Coord {
            final int r, c;
            Coord(int r, int c) { this.r = r; this.c = c; }
        }
    }

    /* --------------------------------------------------------------------- */
    /* Program entry point                                                    */
    /* --------------------------------------------------------------------- */
    public static void main(String[] args) throws Exception {
        /* ---- read dimensions and the whole input up front ------------------- */
        BufferedReader sysIn = new BufferedReader(new InputStreamReader(System.in));
        String firstLine = sysIn.readLine();
        if (firstLine == null) return;                     // empty input

        StringTokenizer dimTok = new StringTokenizer(firstLine);
        int rows = Integer.parseInt(dimTok.nextToken());
        int cols = Integer.parseInt(dimTok.nextToken());

        // Temporary grid – will be resized if the declared size differs.
        char[][] maze = new char[rows][cols];

        // Remaining lines constitute the maze.
        List<String> remaining = new ArrayList<>();
        String line;
        while ((line = sysIn.readLine()) != null) {
            remaining.add(line);
        }

        // Fill the grid, validating row lengths.
        for (int i = 0; i < remaining.size(); i++) {
            String cur = remaining.get(i);
            if (cur.length() != cols) {
                throw new IllegalArgumentException("Row length mismatch");
            }
            for (int j = 0; j < cols; j++) {
                maze[i][j] = cur.charAt(j);
            }
        }

        // Re‑assemble the complete input string (first line + maze rows) for the processor.
        String fullInput = firstLine + System.lineSeparator()
                + String.join(System.lineSeparator(), remaining);

        // Run the algorithm and write the result to stdout.
        Processor processor = new Processor(maze);
        try (StringReader reader = new StringReader(fullInput);
             Writer out = new BufferedWriter(new OutputStreamWriter(System.out))) {

            processor.runAndPrint(reader, out);
        }
    }
}

import java.io.*;
import java.util.*;

public class Main {

    /* ---------- I/O ---------- */
    private static PrintWriter out;
    private static InputReader in;

    /* ---------- Constants ---------- */
    private static final int MAX = 1_010;               // safe upper bound for component indices
    private static final int[] DX = {-1, 1, 0, 0};       // up, down, right, left
    private static final int[] DY = {0, 0, 1, -1};

    /* ---------- Input data ---------- */
    private static char[][] grid;                     // raw characters
    private static int[][] componentId;               // component number for each '.' cell
    private static int[] componentSize;               // size of each component (index = component id)
    private static int componentCount;                // next available component id
    private static int rows, cols;                    // current grid dimensions

    /* ---------- Entry point ---------- */
    public static void main(String[] args) {
        out = new PrintWriter(System.out);
        in = new InputReader();
        new Main().solve();           // invoke the solving routine
        out.flush();
        out.close();
    }

    /* ---------- Solving routine ---------- */
    private void solve() {
        rows = in.nextInt();
        cols = in.nextInt();

        // read grid
        grid = new char[rows][];
        for (int i = 0; i < rows; i++) {
            grid[i] = in.next().trim().toCharArray();
        }

        initDataStructures();

        // discover components and compute their sizes
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == '*' || componentId[i][j] != -1) {
                    continue;
                }
                componentCount++;
                int size = dfs(i, j, componentCount);
                componentSize[componentCount] = size;
            }
        }

        // produce the required output
        for (int i = 0; i < rows; i++) {
            StringBuilder sb = new StringBuilder();
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == '.') {
                    sb.append('.');
                } else {
                    sb.append(calculateImpact(i, j));
                }
            }
            out.println(sb);
        }
    }

    /* ---------- Helper initialisation ---------- */
    private void initDataStructures() {
        componentId = new int[rows][cols];
        Arrays.fill(componentId, -1);
        componentSize = new int[MAX];   // we use component ids 1..componentCount
        componentCount = 0;
    }

    /* ---------- Depth‑first search for component discovery ---------- */
    private int dfs(int i, int j, int id) {
        if (i < 0 || i >= rows || j < 0 || j >= cols) {
            return 0;
        }
        if (grid[i][j] == '*' || componentId[i][j] != -1) {
            return 0;
        }
        componentId[i][j] = id;
        int size = 1;
        for (int d = 0; d < 4; d++) {
            size += dfs(i + DX[d], j + DY[d], id);
        }
        return size;
    }

    /* ---------- Impact calculation for a non‑'.' cell ---------- */
    private char calculateImpact(int i, int j) {
        Set<Integer> seenIds = new HashSet<>();
        int impact = 0;

        for (int d = 0; d < 4; d++) {
            int ni = i + DX[d];
            int nj = j + DY[d];
            if (!isInside(ni, nj) || grid[ni][nj] == '*') {
                continue;
            }
            int cid = componentId[ni][nj];
            if (!seenIds.add(cid)) {
                continue;
            }
            impact += componentSize[cid];
        }
        return (char) ((impact + 1) % 10 + '0');
    }

    /* ---------- Bounds check ---------- */
    private boolean isInside(int x, int y) {
        return x >= 0 && x < rows && y >= 0 && y < cols;
    }

    /* ---------- Input reader ---------- */
    public static class InputReader {
        private final BufferedReader br;
        private StringTokenizer st;

        public InputReader() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        public String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    // ignore
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public long nextLong() {
            return Long.parseLong(next());
        }

        public double nextDouble() {
            return Double.parseDouble(next());
        }
    }
}

