import java.util.Queue;
import java.util.concurrent.ArrayBlockingQueue;

/**
 * Refactored version of the original program that improves readability,
 * maintainability and overall code quality.
 *
 * <p>What it does:
 * <ul>
 *   <li>Reads an N×M grid consisting of '.' (empty) and '*' (bomb) characters.</li>
 *   <li>Labels each connected region of empty cells and stores its size.</li>
 *   <li>For every bomb cell it counts how many distinct empty regions are
 *       reachable orthogonally, adds their sizes together and prints the
 *       last digit of that sum.</li>
 *   <li>All empty cells are printed as '.' in the output.</li>
 * </ul>
 *
 * The refactor focuses on clear separation of concerns, expressive naming,
 * and use of modern Java constructs (try‑with‑resources, ArrayDeque, etc.).
 */
public class Abood2B {

    /* --------------------------------------------------------------------- */
    /* Constants & static state                                               */
    /* --------------------------------------------------------------------- */
    private static final int[] DX = {0, 1, 0, -1};
    private static final int[] DY = {1, 0, -1, 0};

    private static int rows, cols;
    private static int[][] grid;           // 0 = empty, 1 = bomb
    private static int[][] componentLabel; // component id for each cell
    private static final List<Integer> componentSize = new ArrayList<>();

    /* --------------------------------------------------------------------- */
    /* Entry point                                                            */
    /* --------------------------------------------------------------------- */
    public static void main(String[] args) throws IOException {
        /* try‑with‑resources ensures the reader is closed promptly */
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in))) {
            // ----- read dimensions -------------------------------------------------
            StringTokenizer dimTok = new StringTokenizer(br.readLine());
            rows = Integer.parseInt(dimTok.nextToken());
            cols = Integer.parseInt(dimTok.nextToken());

            // ----- read grid ---------------------------------------------------------
            grid = new int[rows][cols];
            String[] rawLines = new String[rows];
            for (int i = 0; i < rows; i++) {
                rawLines[i] = br.readLine();
                for (int j = 0; j < cols; j++) {
                    grid[i][j] = rawLines[i].charAt(j) == '*' ? 1 : 0;
                }
            }

            // ----- label all connected empty regions ---------------------------------
            componentLabel = new int[rows][cols];
            Arrays.fill(componentLabel, -1);
            int componentId = 0;

            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (grid[i][j] == 0 && componentLabel[i][j] == -1) {
                        bfsLabelComponent(i, j, componentId++, componentLabel);
                    }
                }
            }

            // ----- compute and output result -----------------------------------------
            StringBuilder out = new StringBuilder();
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (grid[i][j] == 0) {
                        out.append('.');                               // empty cell
                    } else {
                        out.append(computeBombEffect(i, j));
                    }
                }
                out.append('\n');
            }
            System.out.print(out.toString());
        }
    }

    /* --------------------------------------------------------------------- */
    /* Breadth‑first search that labels a component and records its size       */
    /* --------------------------------------------------------------------- */
    private static void bfsLabelComponent(int startX, int startY,
                                            int componentId,
                                            int[][] componentLabel) {
        Queue<Point> queue = new ArrayBlockingQueue<>(rows * cols);
        queue.add(new Point(startX, startY));
        componentLabel[startX][startY] = componentId;
        int size = 1;

        while (!queue.isEmpty()) {
            Point cur = queue.poll();
            int x = cur.x, y = cur.y;

            for (int dir = 0; dir < 4; dir++) {
                int nx = x + DX[dir], ny = y + DY[dir];
                if (isInBounds(nx, ny) &&
                    grid[nx][ny] == 0 &&               // only walk through empty cells
                    componentLabel[nx][ny] == -1) {    // not visited yet
                    componentLabel[nx][ny] = componentId;
                    queue.add(new Point(nx, ny));
                    size++;
                }
            }
        }
        componentSize.add(size);
    }

    /* --------------------------------------------------------------------- */
    /* Helper that computes the digit to print for a bomb cell                 */
    /* --------------------------------------------------------------------- */
    private static char computeBombEffect(int x, int y) {
        HashSet<Integer> neighbourComponents = new HashSet<>();
        int total = 1; // the bomb cell itself counts as 1

        for (int dir = 0; dir < 4; dir++) {
            int nx = x + DX[dir], ny = y + DY[dir];
            if (isInBounds(nx, ny) &&
                grid[nx][ny] == 0 &&               // neighbour is empty
                neighbourComponents.add(componentLabel[nx][ny])) {
                total += componentSize.get(componentLabel[nx][ny]);
            }
        }
        return Character.forDigit(total % 10, 10);
    }

    /* --------------------------------------------------------------------- */
    /* Simple utility class that holds a point (x, y)                         */
    /* --------------------------------------------------------------------- */
    private static final class Point {
        final int x, y;
        Point(int x, int y) { this.x = x; this.y = y; }
    }

    /* --------------------------------------------------------------------- */
    /* Bounds checking helper                                                 */
    /* --------------------------------------------------------------------- */
    private static boolean isInBounds(int x, int y) {
        return x >= 0 && x < rows && y >= 0 && y < cols;
    }
}

