/**
 * Simple data holder for matrix coordinates.
 */
final class Cell {
    final int row;
    final int col;

    Cell(int row, int col) {
        this.row = row;
        this.col = col;
    }
}

/**
 * Encapsulates directions used for neighbour exploration.
 */
final class Directions {
    static final int[] DR = {-1, 1, 0, 0};
    static final int[] DC = {0, 0, -1, 1};
}

/**
 * Core problem logic – separates input handling, processing and output.
 */
final class Solver {

    private static final char EMPTY   = '.';
    private static final char OBSTACLE = '*';

    private char[][] grid;                         // the input matrix
    private int[][] componentId;                   // component identifier for each empty cell
    private final Map<Integer, Integer> componentSize = new HashMap<>();

    /** Solves the problem using the provided scanner/printer pair. */
    public void solve(FastScanner in, FastPrinter out) {
        int n = in.nextInt();
        int m = in.nextInt();
        grid = new char[n][];
        componentId = new int[n][m];

        // ----- read the matrix -------------------------------------------------
        for (int i = 0; i < n; i++) {
            grid[i] = in.next().toCharArray();
        }

        // ----- discover connected components of empty cells --------------------
        int componentIndex = 1;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (grid[i][j] == EMPTY && componentId[i][j] == 0) {
                    int size = bfs(i, j, componentIndex++);
                    componentSize.put(componentIndex - 1, size);   // id → size
                }
            }
        }

        // ----- build the output matrix -----------------------------------------
        for (int i = 0; i < n; i++) {
            StringBuilder sb = new StringBuilder(m);
            for (int j = 0; j < m; j++) {
                if (grid[i][j] == OBSTACLE) {
                    Set<Integer> neighbourComponents = new HashSet<>();

                    // collect distinct component ids touching this obstacle
                    for (int d = 0; d < 4; d++) {
                        int ni = i + Directions.DR[d];
                        int nj = j + Directions.DC[d];
                        if (inside(ni, nj) && grid[ni][nj] == EMPTY) {
                            int cid = componentId[ni][nj];
                            if (cid != 0) {
                                neighbourComponents.add(cid);
                            }
                        }
                    }

                    int total = 1; // the current obstacle cell itself
                    for (int cid : neighbourComponents) {
                        total += componentSize.get(cid);
                    }
                    sb.append((char) ('0' + (total % 10)));
                } else {
                    sb.append(EMPTY);
                }
            }
            out.printLine(sb.toString());
        }
    }

    /** Breadth‑first search that marks a connected component of '.' cells. */
    private int bfs(int startRow, int startCol, int componentLabel) {
        Queue<Cell> queue = new ArrayDeque<>();
        queue.add(new Cell(startRow, startCol));
        grid[startRow][startCol] = '-';          // mark as visited
        int size = 0;

        while (!queue.isEmpty()) {
            Cell cur = queue.poll();
            componentId[cur.row][cur.col] = componentLabel;
            size++;

            for (int d = 0; d < 4; d++) {
                int nr = cur.row + Directions.DR[d];
                int nc = cur.col + Directions.DC[d];
                if (inside(nr, nc) && grid[nr][nc] == EMPTY) {
                    queue.add(new Cell(nr, nc));
                    grid[nr][nc] = '-';           // mark visited
                }
            }
        }
        return size;
    }

    /** Checks whether a given cell lies inside the matrix bounds. */
    private boolean inside(int row, int col) {
        return row >= 0 && row < grid.length && col >= 0 && col < grid[0].length;
    }
}

/**
 * Fast input scanner based on {@link BufferedReader} and {@link StringTokenizer}.
 */
final class FastScanner {

    private final BufferedReader reader;
    private StringTokenizer tokenizer;

    FastScanner(InputStream stream) {
        this.reader = new BufferedReader(new InputStreamReader(stream), 32768);
        this.tokenizer = null;
    }

    private void ensureTokenizer() throws IOException {
        while (tokenizer == null || !tokenizer.hasMoreTokens()) {
            String line = reader.readLine();
            if (line == null) {
                return;
            }
            tokenizer = new StringTokenizer(line);
        }
    }

    int nextInt() {
        ensureTokenizer();
        return Integer.parseInt(tokenizer.nextToken());
    }
}

/**
 * Fast output printer that wraps a {@link PrintWriter}.
 */
final class FastPrinter {

    private final PrintWriter writer;

    FastPrinter(OutputStream stream) {
        this.writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(stream)));
    }

    void print(Object... objects) {
        for (int i = 0; i < objects.length; i++) {
            if (i != 0) {
                writer.print(' ');
            }
            writer.print(objects[i]);
        }
    }

    void printLine(Object... objects) {
        print(objects);
        writer.println();
    }

    void close() {
        writer.close();
    }
}

