import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.util.*;
import java.util.stream.Collectors;

/**
 * Small utility that behaves like {@link Scanner} but avoids the overhead of
 * {@code java.util.Scanner} for competitive‑programming style input.
 */
final class FastScanner {
    private final BufferedReader reader;
    private StringTokenizer tokenizer;

    FastScanner(InputStream source) {
        this.reader = new BufferedReader(new InputStreamReader(source, 32768), 32768);
    }

    /** Returns the next non‑empty token or {@code null} if EOF. */
    String next() {
        while (tokenizer == null || !tokenizer.hasMoreTokens()) {
            try {
                String line = reader.readLine();
                if (line == null) return null;
                tokenizer = new StringTokenizer(line);
            } catch (IOException e) {
                throw new UncheckedIOException(e);
            }
        }
        return tokenizer.nextToken();
    }
}

/**
 * Holds static data describing a cell in the grid.
 */
final class Cell {
    final int row;
    final int col;

    Cell(int row, int col) {
        this.row = row;
        this.col = col;
    }

    /** Up, down, left, right neighbours. */
    static final List<Cell> NEIGHBOURS = List.of(
            new Cell(1, 0),   // down
            new Cell(-1, 0),  // up
            new Cell(0, 1),   // right
            new Cell(0, -1)   // left
    );
}

/**
 * Holds information about a connected component (its identifier and size).
 */
final class Component {
    final int id;
    final int size;

    Component(int id, int size) {
        this.id = id;
        this.size = size;
    }
}

/**
 * Core logic for reading the grid, discovering connected components and
 * producing the required output.
 */
final class GridSolver {
    private final FastScanner in;
    private final StringBuilder out;
    private int rows, cols;

    /** Grid where {@code true} = traversable cell ('.') , {@code false} = obstacle. */
    private boolean[][] traversable;

    /** Component identifier for each traversable cell; 0 = unvisited / obstacle. */
    private int[][] componentId;

    /** Size of each component (index = component identifier). */
    private final int[] componentSize;

    /** Visited flag for BFS. */
    private final boolean[][] visited;

    /** Current component identifier incremented for each new BFS run. */
    private int nextComponentId = 1;

    /** Directions for neighbour iteration. */
    private final int[] dr = {1, -1, 0, 0};
    private final int[] dc = {0, 0, 1, -1};

    GridSolver(FastScanner in) {
        this.in = in;
        this.out = new StringBuilder();
        this.componentSize = new int[/*max possible*/ (int) 1e5 + 4];
    }

    /** Entry point used by {@code Main}. */
    void solve() {
        readDimensionsAndGrid();
        analyseComponents();
        generateResult();
    }

    /** Parses {@code R C} and the grid itself. */
    private void readDimensionsAndGrid() {
        rows = Integer.parseInt(in.next());
        cols = Integer.parseInt(in.next());

        traversable = new boolean[rows][cols];
        for (int r = 0; r < rows; ++r) {
            String line = in.next();
            for (int c = 0; c < cols; ++c) {
                traversable[r][c] = line.charAt(c) == '.';
            }
        }
    }

    /** Finds all connected components using BFS. */
    private void analyseComponents() {
        componentId = new int[rows][cols];
        visited = new boolean[rows][cols];

        for (int r = 0; r < rows; ++r) {
            for (int c = 0; c < cols; ++c) {
                if (!visited[r][c] && traversable[r][c]) {
                    bfs(r, c);
                }
            }
        }
    }

    /** Performs BFS starting at {@code (sr, sc)} and fills component data structures. */
    private void bfs(int sr, int sc) {
        Queue<Integer> qr = new ArrayDeque<>();
        Queue<Integer> qc = new ArrayDeque<>();

        qr.add(sr);
        qc.add(sc);
        visited[sr][sc] = true;
        componentId[sr][sc] = nextComponentId;

        while (!qr.isEmpty()) {
            int r = qr.poll();
            int c = qc.poll();

            ++componentSize[nextComponentId]; // count cell for current component

            for (int dir = 0; dir < 4; ++dir) {
                int nr = r + dr[dir];
                int nc = c + dc[dir];
                if (!isInBounds(nr, nc) || !traversable[nr][nc] || visited[nr][nc]) {
                    continue;
                }
                visited[nr][nc] = true;
                componentId[nr][nc] = nextComponentId;
                qr.add(nr);
                qc.add(nc);
            }
        }
        ++nextComponentId;
    }

    /** Writes the required output to {@code out}. */
    private void generateResult() {
        for (int r = 0; r < rows; ++r) {
            for (int c = 0; c < cols; ++c) {
                if (traversable[r][c]) {
                    out.append('.');
                } else {
                    int touchingComponentCount = 1;
                    Set<Integer> adjacentComponentIds = new HashSet<>();

                    for (int dir = 0; dir < 4; ++dir) {
                        int nr = r + dr[dir];
                        int nc = c + dc[dir];
                        if (!isInBounds(nr, nc)) continue;

                        int compId = componentId[nr][nc];
                        if (compId == 0) continue; // obstacle cell ignored

                        adjacentComponentIds.add(compId);
                    }

                    // Sum sizes of distinct adjacent components.
                    for (int compId : adjacentComponentIds) {
                        touchingComponentCount += componentSize[compId];
                    }
                    out.append(touchingComponentCount % 10);
                }
            }
            out.append('\n');
        }
    }

    /** Helper – checks array bounds. */
    private boolean isInBounds(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }
}

/**
 * Tiny wrapper that bridges the original `Main` entry point with the refactored
 * {@link GridSolver}.  It holds no business logic itself.
 */
public class Main {
    public static void main(String[] args) throws java.io.FileNotFoundException {
        GridSolver solver = new GridSolver(new FastScanner(System.in));
        solver.solve();
        System.out.print(solver.out);
    }
}

import java.io.*;
import java.util.HashSet;
import java.util.Set;

/**
 * Refactored version of the original {@code TheLabyrinth} program.
 * The refactor focuses on readability, maintainability and clear separation
 * of concerns while preserving the original functionality.
 */
public class TheLabyrinth implements Closeable {

    /* ---------- I/O helpers ------------------------------------------------- */

    private final InputReader in;
    private final PrintWriter out;

    /** Simple fast scanner for competitive‑style input. */
    private static class InputReader implements Closeable {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        InputReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream), 32768);
            tokenizer = null;
        }

        /** Returns the next token, waiting for input if necessary. */
        String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        /** Convenience method for reading an {@code int}. */
        int ni() {
            return Integer.parseInt(next());
        }

        /** Convenience method for reading a {@code long}. */
        long nl() {
            return Long.parseLong(next());
        }

        @Override
        public void close() throws IOException {
            reader.close();
        }
    }

    /* ---------- Union‑Find (Disjoint Set) ----------------------------------- */

    /** Classic Union‑Find data structure that also tracks component size. */
    private static class UnionFind {
        /** Parent pointer for each element. */
        private final int[] parent;
        /** Size of the component rooted at each index (only valid for roots). */
        private final int[] size;

        UnionFind(int elements) {
            parent = new int[elements];
            size = new int[elements];
            for (int i = 0; i < elements; i++) {
                parent[i] = i;
                size[i] = 1;
            }
        }

        /** Returns the representative (root) of the set containing {@code x}. */
        int find(int x) {
            if (parent[x] != x) {
                parent[x] = find(parent[x]);
            }
            return parent[x];
        }

        /** Merges the sets containing {@code a} and {@code b}. */
        void union(int a, int b) {
            int rootA = find(a);
            int rootB = find(b);
            if (rootA == rootB) {
                return;
            }
            // Union by size: attach smaller tree under larger one.
            if (size[rootA] < size[rootB]) {
                int tmp = rootA;
                rootA = rootB;
                rootB = tmp;
            }
            parent[rootB] = rootA;
            size[rootA] += size[rootB];
        }

        /** Returns the size of the component whose root is {@code root}. */
        int componentSize(int root) {
            return size[root];
        }
    }

    /* ---------- Construction & processing ----------------------------------- */

    /** Default directions used for neighbour exploration. */
    private static final int[][] DIRS = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};

    /** Translates a 2‑D cell coordinate into a 1‑D index for the Union‑Find array. */
    private static int linearIndex(int rows, int cols, int r, int c) {
        return r * cols + c;
    }

    public TheLabyrinth() {
        this.in = new InputReader(System.in);
        this.out = new PrintWriter(System.out);
    }

    /** Entry point – reads input, processes it and prints the result. */
    public void solve() {
        final int rows = ni();
        final int cols = ni();

        char[][] grid = readGrid(rows);
        UnionFind uf = buildUnionFind(grid, rows, cols);

        // Transform each obstacle cell based on surrounding component sizes.
        transformObstacles(grid, uf, rows, cols);

        // Output the modified grid.
        printGrid(grid);
    }

    /** Reads the whole grid from the input. */
    private static char[][] readGrid(int rows) {
        char[][] grid = new char[rows][];
        for (int r = 0; r < rows; r++) {
            grid[r] = in.next().toCharArray();
        }
        return grid;
    }

    /** Creates a Union‑Find structure that unites all empty ('.') cells. */
    private static UnionFind buildUnionFind(char[][] grid, int rows, int cols) {
        UnionFind uf = new UnionFind(rows * cols);

        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] != '.') {
                    continue;
                }
                // Down neighbour
                if (r + 1 < rows && grid[r + 1][c] == '.') {
                    uf.union(linearIndex(cols, rows, r, c),
                             linearIndex(cols, rows, r + 1, c));
                }
                // Right neighbour
                if (c + 1 < cols && grid[r][c + 1] == '.') {
                    uf.union(linearIndex(cols, rows, r, c),
                             linearIndex(cols, rows, r, c + 1));
                }
            }
        }
        return uf;
    }

    /** Updates every '*' cell with a digit representing the number of adjacent
     *  empty components plus one, modulo 10. */
    private static void transformObstacles(char[][] grid,
                                            UnionFind uf,
                                            int rows,
                                            int cols) {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == '.') {
                    continue; // nothing to do on empty cells
                }

                Set<Integer> uniqueRoots = new HashSet<>();
                int totalEmptyCells = 0;

                for (int[] d : DIRS) {
                    int nr = r + d[0];
                    int nc = c + d[1];
                    if (isInside(nr, cols) && isInside(nc, rows) && grid[nr][nc] == '.') {
                        int root = uf.find(linearIndex(cols, rows, nr, nc));
                        if (uniqueRoots.add(root)) {
                            totalEmptyCells += uf.componentSize(root);
                        }
                    }
                }
                // Digit = (totalEmptyCells + 1) mod 10, converted back to a char.
                grid[r][c] = (char) ('0' + ((totalEmptyCells + 1) % 10));
            }
        }
    }

    /** Helper that checks whether a coordinate lies inside the grid. */
    private static boolean isInside(int coord, int size) {
        return coord >= 0 && coord < size;
    }

    /** Helper that checks both row and column bounds. */
    private static boolean isInside(int r, int c, int rows, int cols) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    /** Prints the resulting grid to standard output. */
    private static void printGrid(char[][] grid) {
        for (char[] row : grid) {
            out.println(row);
        }
    }

    @Override
    public void close() {
        try {
            in.close();
            out.close();
        } catch (IOException e) {
            // Closing resources should never throw; we just ignore the exception.
        }
    }

    /** Main method – uses try‑with‑resources to ensure proper cleanup. */
    public static void main(String[] args) throws IOException {
        try (TheLabyrinth solver = new TheLabyrinth()) {
            solver.solve();
        }
    }
}

import java.util.Scanner;

/**
 * Refactored version of the original utility.
 *
 * <p>
 *   The program reads three points (x y) from {@code System.in} and prints:
 *   <ul>
 *     <li>1 – all points share the same x‑coordinate or the same y‑coordinate
 *           (they lie on a single vertical or horizontal line)
 *     <li>2 – two points are on the same vertical/horizontal line and the third
 *           point lies strictly between them on that line
 *     <li>3 – any other configuration (corner or generic triangle)
 *   </ul>
 * </p>
 *
 * <p>Key improvements over the original code</p>
 * <ul>
 *   <li>Extracted a small immutable {@link Point} class</li>
 *   <li>Business logic split into well‑named helper methods</li>
 *   <li>No static mutable fields – all data is passed as arguments</li>
 *   <li>Scanning is performed in a try‑with‑resources block</li>
 *   <li>Clear, self‑documenting flow and early returns</li>
 *   <li>Constant‑time checks instead of deep nested conditionals</li>
 * </ul>
 *
 * @author  Refactored by <strong>Assistant</strong>
 */
public class Main {

    /** Simple container for an (x, y) integer coordinate. */
    private static final class Point {
        final int x;
        final int y;

        Point(int x, int y) {
            this.x = x;
            this.y = y;
        }

        /** Equality helpers */
        boolean sameX(Point other) { return x == other.x; }
        boolean sameY(Point other) { return y == other.y; }

        /** Human‑readable representation for debugging (optional). */
        @Override public String toString() {
            return "(" + x + ", " + y + ")";
        }
    }

    /** Reads a single point from the supplied {@link Scanner}. */
    private static Point readPoint(Scanner sc) {
        int x = sc.nextInt();
        int y = sc.nextInt();
        return new Point(x, y);
    }

    /** Determines whether three points are collinear (share the same x or y). */
    private static boolean areCollinearHorizontallyOrVertically(Point a, Point b, Point c) {
        return (a.sameX(b) && b.sameX(c))   // vertical line
            || (a.sameY(b) && b.sameY(c)); // horizontal line
    }

    /** Checks if a designated “middle” point lies strictly between two others
     *  on the same vertical or horizontal line. */
    private static boolean isMiddle(Point middle, Point left, Point right) {
        // vertical alignment
        if (middle.sameX(left) && middle.sameX(right)) {
            int lowY  = Math.min(left.y, right.y);
            int highY = Math.max(left.y, right.y);
            return lowY < middle.y && middle.y < highY;
        }
        // horizontal alignment
        if (middle.sameY(left) && middle.sameY(right)) {
            int lowX  = Math.min(left.x, right.x);
            int highX = Math.max(left.x, right.x);
            return lowX < middle.x && middle.x < highX;
        }
        return false;
    }

    /**
     * Core analysis routine – decides which of the three possible outputs to emit.
     *
     * @param p1 first point
     * @param p2 second point
     * @param p3 third point
     */
    private static void analyze(Point p1, Point p2, Point p3) {
        // 1️⃣  All three points share the same x or same y → line
        if (areCollinearHorizontallyOrVertically(p1, p2, p3)) {
            System.out.println(1);
            return;
        }

        // 2️⃣  One point is between the other two on a vertical/horizontal line → corner
        if (isMiddle(p1, p2, p3) ||
            isMiddle(p2, p1, p3) ||
            isMiddle(p3, p1, p2)) {
            System.out.println(2);
            return;
        }

        // 3️⃣  Anything else
        System.out.println(3);
    }

    /** Entry point – reads three points and triggers the analysis. */
    public static void main(String[] args) {
        try (Scanner sc = new Scanner(System.in)) {
            Point p1 = readPoint(sc);
            Point p2 = readPoint(sc);
            Point p3 = readPoint(sc);
            analyze(p1, p2, p3);
        }
    }
}

