    }

    /**
     * Executes the solution:
     * reads three points from {@code System.in} and prints the minimal number
     * of moves required to make them collinear.
     */
    private static void solve() {
        try (Scanner scanner = new Scanner(System.in)) {
            Geometry geometry = new Geometry();
            int answer = geometry.computeMinSteps(scanner);
            System.out.println(answer);
        }
    }
}

/**
 * Utility class that encapsulates the algorithm.
 * <p>
 * The logic has been extracted into well‑named private methods, making the
 * flow easy to follow and test.  All variable names describe their purpose,
 * and the method is fully documented with Javadoc.
 */
class Geometry {

    /**
     * Reads six integers from the supplied {@link Scanner} representing three
     * points {@code (x1,y1), (x2,y2), (x3,y3)} and returns the minimal number of
     * moves needed to align them.
     *
     * @param scanner a scanner positioned at the input tokens
     * @return the minimal number of moves (1, 2 or 3)
     */
    public int computeMinSteps(Scanner scanner) {
        // --------------------------------------------------------------------
        // 1️⃣  Input
        // --------------------------------------------------------------------
        int x1 = scanner.nextInt();
        int y1 = scanner.nextInt();
        int x2 = scanner.nextInt();
        int y2 = scanner.nextInt();
        int x3 = scanner.nextInt();
        int y3 = scanner.nextInt();

        // --------------------------------------------------------------------
        // 2️⃣  Initial worst‑case answer
        // --------------------------------------------------------------------
        int answer = 3; // three separate moves in the worst case

        // --------------------------------------------------------------------
        // 3️⃣  Cases that can be solved in a single move
        // --------------------------------------------------------------------
        if (x1 == x2 && x2 == x3) {           // all x‑coordinates equal → vertical line
            answer = Math.min(answer, 1);
        }
        if (y1 == y2 && y2 == y3) {           // all y‑coordinates equal → horizontal line
            answer = Math.min(answer, 1);
        }

        // --------------------------------------------------------------------
        // 4️⃣  Cases that can be solved in two moves
        // --------------------------------------------------------------------
        // Two points share the same x‑coordinate and the third point lies
        // outside the y‑range defined by them.
        if (x1 == x2 && (y3 >= Math.max(y1, y2) || y3 <= Math.min(y1, y2))) {
            answer = Math.min(answer, 2);
        }
        if (x1 == x3 && (y2 >= Math.max(y1, y3) || y2 <= Math.min(y1, y3))) {
            answer = Math.min(answer, 2);
        }
        if (x2 == x3 && (y1 >= Math.max(y2, y3) || y1 <= Math.min(y2, y3))) {
            answer = Math.min(answer, 2);
        }

        // Two points share the same y‑coordinate and the third point lies
        // outside the x‑range defined by them.
        if (y1 == y2 && (x3 >= Math.max(x1, x2) || x3 <= Math.min(x1, x2))) {
            answer = Math.min(answer, 2);
        }
        if (y1 == y3 && (x2 >= Math.max(x1, x3) || x2 <= Math.min(x1, x3))) {
            answer = Math.min(answer, 2);
        }
        if (y2 == y3 && (x1 >= Math.max(x2, x3) || x1 <= Math.min(x2, x3))) {
            answer = Math.min(answer, 2);
        }

        // --------------------------------------------------------------------
        // 5️⃣  Return the result
        // --------------------------------------------------------------------
        return answer;
    }
}

import java.io.*;
import java.util.StringTokenizer;

/**
 * Solution for problem «cf340_d».
 *
 * <p>Reads six integers (two coordinates for each of three points) and prints one
 * of three possible results:
 * <ul>
 *   <li>1 – all three points share the same X coordinate or the same Y coordinate</li>
 *   <li>2 – two points share a coordinate and the third point lies outside the
 *        interval defined by those two points on the other axis</li>
 *   <li>3 – otherwise</li>
 * </ul>
 *
 * <p>Refactoring focuses on:
 * <ul>
 *   <li>Descriptive naming of variables and methods</li>
 *   <li>Extraction of logical parts into dedicated helper methods</li>
 *   <li>Removal of duplicated code</li>
 *   <li>Use of Java‑idiomatic constructs (try‑with‑resources)</li>
 * </ul>
 */
public class cf340_d {

    /* ---------------------------------------------------------------------- */
    /*  I/O Helpers – keep the original flexible file/stdin interface          */
    /* ---------------------------------------------------------------------- */
    private final boolean fileInput = false;      // true → use "*.in" / "*.out" files
    private final String fileName   = "";         // leave empty for console I/O

    private BufferedReader br;
    private StringTokenizer in;
    private PrintWriter  out;

    private String nextToken() throws IOException {
        while (in == null || !in.hasMoreTokens()) {
            in = new StringTokenizer(br.readLine());
        }
        return in.nextToken();
    }

    private int    nextInt()    throws IOException { return Integer.parseInt(nextToken()); }
    private long   nextLong()   throws IOException { return Long.parseLong(nextToken()); }

    /* ---------------------------------------------------------------------- */
    /*  Core logic – decision making                                          */
    /* ---------------------------------------------------------------------- */

    /** Reads the six coordinates from the input stream. */
    private void readInput() {
        xa = nextLong(); ya = nextLong();
        xb = nextLong(); yb = nextLong();
        xc = nextLong(); yc = nextLong();
    }

    /** Determines the answer according to the original problem logic. */
    private int determineAnswer() {
        // 1 – all three x's equal **or** all three y's equal
        if (isAllXEqual(xa, xb, xc) || isAllYEqual(ya, yb, yc)) {
            return 1;
        }

        // 2 – any pair shares a coordinate and the third point lies outside
        //     the interval formed by that pair on the *other* axis
        if (isOutsideSegmentAlongX(xa, xb, xc, ya, yb, yc) ||
            isOutsideSegmentAlongX(xa, xc, xb, ya, yc, yb) ||
            isOutsideSegmentAlongY(ya, yb, yc, xa, xb, xc) ||
            isOutsideSegmentAlongY(ya, yc, yb, xa, xc, xb) ||
            isOutsideSegmentAlongX(xb, xc, xa, yb, yc, ya) ||
            isOutsideSegmentAlongY(yb, yc, ya, xb, xc, xa)) {
            return 2;
        }

        // 3 – all other cases
        return 3;
    }

    /** Returns {@code true} if {@code x1 == x2 == x3}. */
    private boolean isAllXEqual(long x1, long x2, long x3) {
        return x1 == x2 && x1 == x3;
    }

    /** Returns {@code true} if {@code y1 == y2 == y3}. */
    private boolean isAllYEqual(long y1, long y2, long y3) {
        return y1 == y2 && y1 == y3;
    }

    /**
     * Checks whether point {@code (cX, cY)} lies outside the interval defined by
     * {@code aX..bX} on the X‑axis, assuming the Y‑coordinates of a and b are equal
     * (i.e. they share a Y coordinate).
     */
    private boolean isOutsideSegmentAlongX(long ax, long bx, long cx,
                                            long ay, long by, long cy) {
        // Pair (ax, ay) and (bx, by) share the same X?
        if (ax != bx) return false;
        // The shared X is the axis we care about; the other axis is Y.
        // We need to know whether cy is outside the [min, max] of ay and by.
        double minY = Math.min(ay, by);
        double maxY = Math.max(ay, by);
        return cy < minY || cy > maxY;
    }

    /**
     * Checks whether point {@code (cX, cY)} lies outside the interval defined by
     * {@code aY..bY} on the Y‑axis, assuming the X‑coordinates of a and b are equal.
     */
    private boolean isOutsideSegmentAlongY(long ay, long by, long cy,
                                            long ax, long bx, long cx) {
        // Pair (ax, ay) and (bx, by) share the same Y?
        if (ay != by) return false;
        double minX = Math.min(ax, bx);
        double maxX = Math.max(ax, bx);
        return cx < minX || cx > maxX;
    }

    /** Executes the whole solution: parsing, computation and output. */
    private void solve() throws IOException {
        readInput();
        int answer = determineAnswer();
        out.print(answer);
    }

    /* ---------------------------------------------------------------------- */
    /*  Program entry point                                                    */
    /* ---------------------------------------------------------------------- */
    public void run() throws IOException {
        try (Reader reader = fileInput ? new FileReader(fileName + ".in") : new InputStreamReader(System.in);
             BufferedReader brr = new BufferedReader(reader);
             PrintWriter pw = fileInput ? new PrintWriter(fileName + ".out") : new PrintWriter(System.out)) {
            br = brr;
            in = new StringTokenizer(brr.readLine());
            solve();

            br.close();
            pw.close();
        } catch (IOException e) {
            // Silent fail – original program behaved the same way.
            System.err.println(e.getMessage());
        }
    }

    public static void main(String[] args) throws IOException {
        new cf340_d().run();
    }

    /* ---------------------------------------------------------------------- */
    /*  Minimal debugging helpers (kept for parity with original code)        */
    /* ---------------------------------------------------------------------- */
    private void log(String s) { System.out.print(s); }
    private void logln(String s) { System.out.println(s); }
}

/*
 *  Refactored solution for the original problem.
 *  The program reads three (x, y) points, determines the minimal number of
 *  lines (horizontal or vertical) needed to connect all points, and prints
 *  the answer.
 *
 *  Changes made:
 *   •  All I/O is isolated in dedicated reader / writer classes.
 *   •  Point is a small immutable value object.
 *   •  Magic numbers and duplicated logic are replaced by well‑named
 *      helper methods.
 *   •  Variable names are expressive and the control flow is flattened.
 *   •  Unused utilities (dump, sorting helpers, segment trees, timers …)
 *      have been removed.
 *   •  The code follows a clear structure: input → decision → output.
 *   •  Java‑8 style constructs are avoided to keep the program readable for
 *      all Java versions used in contests.
 *
 *  The logic is unchanged – only the structure and naming have been improved.
 */
import java.io.*;
import java.util.*;

public class Main {

    /* --------------------------------------------------------------
     *  Utility data classes
     * -------------------------------------------------------------- */
    /** Immutable pair of integer coordinates. */
    private static final class Point {
        final int x;
        final int y;

        Point(int x, int y) {
            this.x = x;
            this.y = y;
        }
    }

    /** Simple buffered line / token reader. */
    private static final class InputReader implements Closeable {
        private final BufferedReader br;
        private int cur = -2;                     // sentinel – not read yet

        /** Creates a reader from standard input. */
        InputReader() throws IOException {
            this(new InputStreamReader(System.in));
        }

        /** Creates a reader from a file (used only by the original stub). */
        InputReader(String filePath) throws IOException {
            this(new InputStreamReader(new FileInputStream(filePath)));
        }

        /** Creates a reader from an arbitrary {@link Reader}. */
        InputReader(Reader source) {
            this.br = new BufferedReader(source);
        }

        /** Skips whitespace characters. */
        private void skipWhitespace() throws IOException {
            while (cur != -1 && Character.isWhitespace((char) cur)) {
                cur = br.read();
            }
        }

        /** Returns the next non‑whitespace token. */
        String nextToken() throws IOException {
            StringBuilder sb = new StringBuilder();
            skipWhitespace();
            while (cur != -1 && !Character.isWhitespace((char) cur)) {
                sb.append((char) cur);
                cur = br.read();
            }
            return sb.toString();
        }

        /** Reads a whole line (including empty lines). */
        String readLine() throws IOException {
            StringBuilder sb = new StringBuilder();
            while (cur != -1 && cur != '\n' && cur != '\r') {
                sb.append((char) cur);
                cur = br.read();
            }
            return sb.toString();
        }

        /** Reads the next integer. */
        int nextInt() throws IOException {
            return Integer.parseInt(nextToken());
        }

        /** Reads the next long. */
        long nextLong() throws IOException {
            return Long.parseLong(nextToken());
        }

        /** Reads the next double. */
        double nextDouble() throws IOException {
            return Double.parseDouble(nextToken());
        }

        @Override public void close() throws IOException {
            br.close();
        }
    }

    /** Simple wrapper around {@link PrintWriter} that can write to a file or
     *  to {@code System.out}. */
    private static final class OutputWriter implements Closeable {
        private final PrintWriter pw;

        OutputWriter(Writer source) {
            this.pw = new PrintWriter(source);
        }

        /** Writes an int followed by a line break. */
        void println(int value) {
            pw.println(value);
        }

        /** Writes an int without a line break. */
        void print(int value) {
            pw.print(value);
        }

        /** Flushes and closes the underlying stream. */
        @Override public void close() {
            pw.close();
        }
    }

    /* --------------------------------------------------------------
     *  Helper functions used by the algorithm
     * -------------------------------------------------------------- */

    /**
     * Returns {@code true} when {@code value} is NOT inside the half‑open
     * interval {@code [left, right)} after the lower bound has been made
     * smaller than the upper bound.  The original method was named {@code out}
     * and returned the opposite of what we need here.
     */
    private static boolean isOutside(int value, int left, int right) {
        return value <= left || right <= value;
    }

    /**
     * Checks whether {@code x} lies strictly between {@code left} and {@code right}
     * (the order does not matter).  The method mirrors the behaviour of the
     * original {@code out(l,r,x)} call.
     */
    private static boolean liesBetweenExclusive(int left, int right, int x) {
        left = Math.min(left, right);
        right = Math.max(left, right);
        return isOutside(x, left, right);
    }

    /**
     * Solves a single test case.
     *
     * @param in  reader that supplies the input data
     * @param out writer that receives the answer
     * @throws IOException if an I/O error occurs
     */
    private static void solve(InputReader in, OutputWriter out) throws IOException {
        // ---- read three points -------------------------------------------------
        Point[] pts = new Point[3];
        for (int i = 0; i < 3; ++i) {
            int x = in.nextInt();
            int y = in.nextInt();
            pts[i] = new Point(x, y);
        }

        // ---- quick answer when all x or all y are identical -------------------
        boolean allXEqual = pts[0].x == pts[1].x && pts[1].x == pts[2].x;
        boolean allYEqual = pts[0].y == pts[1].y && pts[1].y == pts[2].y;
        if (allXEqual || allYEqual) {
            out.println(1);
            return;
        }

        // ---- try to reduce the answer to 2 -----------------------------------
        int answer = 3; // default (cannot be solved with fewer lines)

        // Examine each unordered pair of points
        for (int i = 0; i < 3; ++i) {
            for (int j = i + 1; j < 3; ++j) {
                int k = 3 - i - j; // index of the remaining point

                if (pts[i].x == pts[j].x) {                     // vertical alignment
                    int yMin = Math.min(pts[i].y, pts[j].y);
                    int yMax = Math.max(pts[i].y, pts[j].y);
                    if (liesBetweenExclusive(yMin, yMax, pts[k].y)) {
                        answer = 2;
                    }
                } else if (pts[i].y == pts[j].y) {               // horizontal alignment
                    int xMin = Math.min(pts[i].x, pts[j].x);
                    int xMax = Math.max(pts[i].x, pts[j].x);
                    if (liesBetweenExclusive(xMin, xMax, pts[k].x)) {
                        answer = 2;
                    }
                }
            }
        }

        // ---- output -----------------------------------------------------------
        out.println(answer);
    }

    /* --------------------------------------------------------------
     *  Program entry point
     * -------------------------------------------------------------- */
    public static void main(String[] args) {
        try (InputReader reader = new InputReader();
             OutputWriter writer = new OutputWriter(System.out)) {
            new Main().run(reader, writer);
        } catch (IOException e) {
            // In contest environments we simply print the stack trace.
            e.printStackTrace();
        }
    }

    /** Small wrapper that glues together input, solving and output. */
    private void run(InputReader in, OutputWriter out) throws IOException {
        solve(in, out);
        out.close();
    }
}

import java.util.Scanner;

/**
 * Refactored version of the original program.
 *
 * <p>This implementation improves readability and maintainability by:
 * <ul>
 *   <li>Extracting the offset logic into a named constant.</li>
 *   <li>Wrapping point data in a small {@code Point} class.</li>
 *   <li>Separating input handling, classification logic, and output.</li>
 *   <li>Using descriptive method names and avoiding deeply nested conditionals.</li>
 *   <li>Eliminating magic numbers and ambiguous variable names.</li>
 * </ul>
 */
public class Main {

    /** Constant offset that was added to each raw input value in the original code. */
    private static final long OFFSET = 1_000_000_000L;

    /** Simple holder for a 2‑D point with long coordinates. */
    private static final class Point {
        final long x;
        final long y;

        Point(long x, long y) {
            this.x = x;
            this.y = y;
        }
    }

    /** Entry point of the program. */
    public static void main(String[] args) {
        // Try‑with‑resources ensures the Scanner is closed promptly.
        try (Scanner sc = new Scanner(System.in)) {
            Point p1 = readPoint(sc);
            Point p2 = readPoint(sc);
            Point p3 = readPoint(sc);

            String result = classify(p1, p2, p3);
            System.out.println(result);
        }
    }

    /** Reads a pair of integers, adds the predefined offset, and wraps them in a {@code Point}. */
    private static Point readPoint(Scanner sc) {
        long rawX = sc.nextLong();
        long rawY = sc.nextLong();
        return new Point(rawX + OFFSET, rawY + OFFSET);
    }

    /**
     * Determines the relationship among three points and returns the appropriate code
     * ("1", "2" or "3").
     *
     * @param a first point
     * @param b second point
     * @param c third point
     * @return a string representing the classification
     */
    private static String classify(Point a, Point b, Point b, Point c) {
        // If any two points share the same X coordinate, handle the vertical case.
        if (a.x == b.x) {
            return evaluateVerticalAlignment(a, b, c);
        }
        // If any two points share the same Y coordinate, handle the horizontal case.
        if (a.y == b.y) {
            return evaluateHorizontalAlignment(a, b, c);
        }
        // General case where no two points share an axis coordinate.
        return evaluateGeneralCase(a, b, c);
    }

    /** Handles the situation where the first two points define a vertical line. */
    private static String evaluateVerticalAlignment(Point p1, Point p2, Point p3) {
        // All three points lie on the same vertical line.
        if (p3.x == p1.x) {
            return "1";
        }

        // Order the Y values of p1 and p2 to simplify comparison.
        if (p1.y > p2.y) {
            return (p3.y < p1.y && p3.y > p2.y) ? "3" : "2";
        } else {
            return (p3.y < p2.y && p3.y > p1.y) ? "3" : "2";
        }
    }

    /** Handles the situation where the first two points define a horizontal line. */
    private static String evaluateHorizontalAlignment(Point p1, Point p2, Point p3) {
        // All three points lie on the same horizontal line.
        if (p3.y == p1.y) {
            return "1";
        }

        // Order the X values of p1 and p2.
        if (p1.x > p2.x) {
            return (p3.x < p1.x && p3.x > p2.x) ? "3" : "2";
        } else {
            return (p3.x < p2.x && p3.x > p1.x) ? "3" : "2";
        }
    }

    /**
     * Handles the general case where no two of the first points share an axis.
     * The logic mirrors the original nested-if structure but is expressed
     * with clearer, top‑level method calls.
     */
    private static String evaluateGeneralCase(Point a, Point b, Point c) {
        // Check for shared X coordinate with the third point.
        if (a.x == c.x) {
            return orderingResult(a.y, c.y, b.y);
        }
        if (b.x == c.x) {
            return orderingResult(b.y, c.y, a.y);
        }
        // Check for shared Y coordinate with the third point.
        if (a.y == c.y) {
            return orderingResult(a.x, c.x, b.x);
        }
        if (b.y == c.y) {
            return orderingResult(b.x, c.x, a.x);
        }
        // Default fallback – matches the original program's final outcome.
        return "3";
    }

    /**
     * Helper that encapsulates the ordering check used in several places.
     *
     * @param larger   the larger of the two reference coordinates
     * @param smaller  the smaller of the two reference coordinates
     * @param middle   the coordinate to test
     * @return "3" if {@code middle} lies strictly between {@code smaller} and {@code larger},
     *         otherwise "2".
     */
    private static String orderingResult(long larger, long smaller, long middle) {
        return (middle < larger && middle > smaller) ? "3" : "2";
    }
}

import java.util.Scanner;

/**
 * Refactored version of the original program.
 * Reads three points from standard input and prints:
 *   1 – when all three points share the same X or the same Y,
 *   2 – when two points share a coordinate but the third point does NOT lie between them,
 *   3 – in all other cases.
 */
public class Test {

    /** Simple immutable point class. */
    private static final class Point {
        final long x;
        final long y;

        Point(long x, long y) {
            this.x = x;
            this.y = y;
        }
    }

    /** Reads three points from the scanner. */
    private static Point readPoint(Scanner scn) {
        long x = scn.nextLong();
        long y = scn.nextLong();
        return new Point(x, y);
    }

    /** Returns true when the X‑coordinates of all points are equal. */
    private static boolean allXEqual(Point a, Point b, Point c) {
        return a.x == b.x && b.x == c.x;
    }

    /** Returns true when the Y‑coordinates of all points are equal. */
    private static boolean allYEqual(Point a, Point b, Point c) {
        return a.y == b.y && b.y == c.y;
    }

    /**
     * Returns {@code true} if {@code middle} lies strictly between {@code a} and {@code b}.
     * Works for any ordering of {@code a} and {@code b}.
     */
    private static boolean isBetween(long a, long b, long middle) {
        long min = Math.min(a, b);
        long max = Math.max(a, b);
        return middle > min && middle < max;
    }

    /** Determines the output value according to the original specification. */
    private static int determineOutput(Point p1, Point p2, Point p3) {
        // 1. All X or all Y equal -> print 1
        if (allXEqual(p1, p2, p3) || allYEqual(p1, p2, p3)) {
            return 1;
        }

        // Helper to decide between a pair sharing a coordinate
        java.util.function.BiFunction<Long, Long, Integer> checkPair =
                (coord1, coord2) -> {
                    if (isBetween(coord1, coord2, p3.y)) { // third point's Y used for vertical case
                        return 3;
                    }
                    return 2;
                };

        // Check each possible pair for equal X
        if (p1.x == p2.x) {
            return (isBetween(p1.y, p2.y, p3.y)) ? 3 : 2;
        }
        if (p1.x == p3.x) {
            return (isBetween(p1.y, p3.y, p2.y)) ? 3 : 2;
        }
        if (p2.x == p3.x) {
            return (isBetween(p2.y, p3.y, p1.y)) ? 3 : 2;
        }

        // Check each possible pair for equal Y
        if (p1.y == p2.y) {
            return (isBetween(p1.x, p2.x, p3.x)) ? 3 : 2;
        }
        if (p1.y == p3.y) {
            return (isBetween(p1.x, p3.x, p2.x)) ? 3 : 2;
        }
        if (p2.y == p3.y) {
            return (isBetween(p2.x, p3.x, p1.x)) ? 3 : 2;
        }

        // Default case – no equal coordinates
        return 3;
    }

    public static void main(String[] args) {
        try (Scanner scn = new Scanner(System.in)) {
            Point p1 = readPoint(scn);
            Point p2 = readPoint(scn);
            Point p3 = readPoint(scn);

            int result = determineOutput(p1, p2, p3);
            System.out.println(result);
        }
    }
}

