/**
 * Refactored version of the original C339D program.
 * The refactor focuses on:
 *   • Extracting a small {@code Point} class to hold coordinate data.
 *   • Consolidating repetitive checks into a dedicated {@code determineResult} method.
 *   • Using early returns and clear condition grouping.
 *   • Leveraging try‑with‑resources for the {@code Scanner}.
 */
public class C339D {

    /** Simple immutable point representation. */
    private static final class Point {
        final int x;
        final int y;

        Point(int x, int y) {
            this.x = x;
            this.y = y;
        }
    }

    /**
     * Determines the output value based on the relative positions of three points.
     *
     * @param a first point
     * @param b second point
     * @param c third point
     * @return 1, 2, or 3 according to the original logic
     */
    private static int determineResult(Point a, Point b, Point c) {
        // 1️⃣ All three share the same x‑coordinate or the same y‑coordinate.
        if (a.x == b.x && b.x == c.x) {
            return 1;
        }
        if (a.y == b.y && b.y == c.y) {
            return 1;
        }

        // Helper to decide if a third coordinate lies “outside” the range defined by two others.
        java.util.function.BiFunction<Integer, Integer, Boolean> outsideRange = (val, pair) -> {
            int min = Math.min(pair[0], pair[1]);
            int max = Math.max(pair[0], pair[1]);
            return val >= max || val <= min;
        };

        // 2️⃣ Check each pair for shared coordinate and the position of the remaining point.
        // Pair (a, b)
        if (a.x == b.x) {
            if (a.y == c.y || b.y == c.y ||
                outsideRange.apply(c.y, new Integer[]{a.y, b.y})) {
                return 2;
            }
        }
        if (a.y == b.y) {
            if (a.x == c.x || b.x == c.x ||
                outsideRange.apply(c.x, new Integer[]{a.x, b.x})) {
                return 2;
            }
        }

        // Pair (a, c)
        if (a.x == c.x) {
            if (a.y == b.y || c.y == b.y ||
                outsideRange.apply(b.y, new Integer[]{a.y, c.y})) {
                return 2;
            }
        }
        if (a.y == c.y) {
            if (a.x == b.x || c.x == b.x ||
                outsideRange.apply(b.x, new Integer[]{a.x, c.x})) {
                return 2;
            }
        }

        // Pair (b, c)
        if (b.x == c.x) {
            if (b.y == a.y || c.y == a.y ||
                outsideRange.apply(a.y, new Integer[]{b.y, c.y})) {
                return 2;
            }
        }
        if (b.y == c.y) {
            if (b.x == a.x || c.x == a.x ||
                outsideRange.apply(a.x, new Integer[]{b.x, c.x})) {
                return 2;
            }
        }

        // Default case
        return 3;
    }

    /** Entry point – reads three points and prints the computed result. */
    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            Point p1 = new Point(scanner.nextInt(), scanner.nextInt());
            Point p2 = new Point(scanner.nextInt(), scanner.nextInt());
            Point p3 = new Point(scanner.nextInt(), scanner.nextInt());

            System.out.println(determineResult(p1, p2, p3));
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

/**
 * Reads three points from standard input and prints:
 *   1 – if all points share the same X coordinate or the same Y coordinate,
 *   2 – if one point lies on a horizontal or vertical segment formed by the other two,
 *   3 – otherwise.
 *
 * The logic has been refactored for readability, testability and maintainability.
 */
public class Main {

    /** Simple immutable point representation. */
    private static final class Point {
        final int x;
        final int y;

        Point(int x, int y) {
            this.x = x;
            this.y = y;
        }

        /** Checks if this point shares the same X coordinate with another point. */
        boolean sharesX(Point other) {
            return x == other.x;
        }

        /** Checks if this point shares the same Y coordinate with another point. */
        boolean sharesY(Point other) {
            return y == other.y;
        }

        /**
         * Returns true if {@code this} lies on the axis‑aligned segment between {@code a} and {@code b}.
         *
         * @param a first endpoint of the segment
         * @param b second endpoint of the segment
         * @return true if the point is on the vertical or horizontal line formed by {@code a} and {@code b}
         *         and its coordinate on that axis is between the two points.
         */
        boolean liesOnSegment(Point a, Point b) {
            // If x coordinates are equal we are on a vertical line → check y bounds.
            if (sharesX(a)) {
                return y >= Math.min(a.y, b.y) && y <= Math.max(a.y, b.y);
            }
            // Otherwise we are on a horizontal line → check x bounds.
            return x >= Math.min(a.x, b.x) && x <= Math.max(a.x, b.x);
        }
    }

    public static void main(String[] args) throws IOException {
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in))) {
            Point p1 = parsePoint(br.readLine());
            Point p2 = parsePoint(br.readLine());
            Point p3 = parsePoint(br.readLine());

            if (areAllXEqual(p1, p2, p3) || areAllYEqual(p1, p2, p3)) {
                System.out.println(1);
            } else if (isOnVerticalOrHorizontalSegment(p1, p2, p3) ||
                       isOnVerticalOrHorizontalSegment(p1, p3, p2) ||
                       isOnVerticalOrHorizontalSegment(p2, p3, p1)) {
                System.out.println(2);
            } else {
                System.out.println(3);
            }
        }
    }

    /** Helper: converts a "x y" line into a {@link Point}. */
    private static Point parsePoint(String line) {
        StringTokenizer st = new StringTokenizer(line);
        return new Point(Integer.parseInt(st.nextToken()), Integer.parseInt(st.nextToken()));
    }

    /** Checks whether the three points have identical X coordinates. */
    private static boolean areAllXEqual(Point a, Point b, Point c) {
        return a.x == b.x && b.x == c.x;
    }

    /** Checks whether the three points have identical Y coordinates. */
    private static boolean areAllYEqual(Point a, Point b, Point c) {
        return a.y == b.y && b.y == c.y;
    }

    /**
     * Determines whether {@code candidate} lies on an axis‑aligned segment formed by {@code a} and {@code b}.
     *
     * @return true if {@code candidate} shares either the X or Y coordinate with {@code a}
     *         and its coordinate on that axis is between {@code a} and {@code b}.
     */
    private static boolean isOnVerticalOrHorizontalSegment(Point candidate, Point a, Point b) {
        // Candidate must be aligned with 'a' either vertically or horizontally.
        boolean alignedVertically = candidate.sharesX(a);
        boolean alignedHorizontally = candidate.sharesY(a);
        if (!alignedVertically && !alignedHorizontally) {
            return false;
        }

        // If aligned vertically, check y‑range; if horizontally, check x‑range.
        return candidate.liesOnSegment(a, b);
    }
}

import java.util.Scanner;

/**
 * Reads the coordinates of three points and prints:
 *   1 – if all x‑coordinates are equal or all y‑coordinates are equal,
 *   2 – if a pair of points share a coordinate (x or y) and the third point
 *       lies outside the interval defined by that pair,
 *   3 – otherwise.
 *
 * The logic follows the original program but is organised into small,
 * reusable methods and clearly separated cases, making the code easier to
 * maintain and extend.
 */
public class Main {

    public static void main(String[] args) {
        try (Scanner sc = new Scanner(System.in)) {
            // Read three points (x1,y1), (x2,y2), (x3,y3)
            int[] x = new int[3];
            int[] y = new int[3];
            for (int i = 0; i < 3; i++) {
                x[i] = sc.nextInt();
                y[i] = sc.nextInt();
            }

            // Case 1: all x‑coordinates equal OR all y‑coordinates equal → output 1
            if (allEqual(x) || allEqual(y)) {
                System.out.println(1);
                return;
            }

            // Case 2: check for equal Y among pairs (0‑1, 1‑2, 0‑2)
            int[] yPairOrder = {{0, 1}, {1, 2}, {0, 2}};
            for (int[] pair : yPairOrder) {
                int a = pair[0];
                int b = pair[1];
                if (y[a] == y[b]) {
                    int third = 3 - a - b;               // index of the remaining point
                    int minX = Math.min(x[a], x[b]);
                    int maxX = Math.max(x[a], x[b]);
                    if (x[third] <= minX || x[third] >= maxX) {
                        System.out.println(2);
                    } else {
                        System.out.println(3);
                    }
                    return;
                }
            }

            // Case 3: check for equal X among pairs (0‑1, 1‑2, 0‑2)
            int[] xPairOrder = {{0, 1}, {1, 2}, {0, 2}};
            for (int[] pair : xPairOrder) {
                int a = pair[0];
                int b = pair[1];
                if (x[a] == x[b]) {
                    int third = 3 - a - b;
                    int minY = Math.min(y[a], y[b]);
                    int maxY = Math.max(y[a], y[b]);
                    if (y[third] <= minY || y[third] >= maxY) {
                        System.out.println(2);
                    } else {
                        System.out.println(3);
                    }
                    return;
                }
            }

            // Default case – none of the above conditions matched
            System.out.println(3);
        }
    }

    /** Returns true if all elements of the given array are equal. */
    private static boolean allEqual(int[] arr) {
        return arr[0] == arr[1] && arr[1] == arr[2];
    }
}

import java.io.*;
import java.util.*;

public class Main {

    public static void main(String[] args) throws Exception {
        InputReader in = new InputReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        // ----- read three points (x0,y0) (x1,y1) (x2,y2) -----
        int[] xs = new int[3];
        int[] ys = new int[3];
        for (int i = 0; i < 3; i++) {
            xs[i] = in.nextInt();
            ys[i] = in.nextInt();
        }

        // ----- count distinct coordinates -----
        int distinctX = distinctCount(xs);
        int distinctY = distinctCount(ys);
        int answer = Math.min(distinctX, distinctY);

        // ----- special case when the minimum distinct count is 2 -----
        if (answer == 2) {
            if (distinctX == 2 && distinctY != 2) {
                if (hasYInsideRange(xs, ys)) {
                    answer = 3;
                }
            } else if (distinctY == 2 && distinctX != 2) {
                if (hasXInsideRange(xs, ys)) {
                    answer = 3;
                }
            }
        }

        out.println(answer);
        out.close();
    }

    /* -------------------------------------------------------------
       Helper methods – each does one small, well‑named job
       ------------------------------------------------------------- */

    /** Returns the number of distinct values in the given array. */
    private static int distinctCount(int[] values) {
        Set<Integer> set = new HashSet<>();
        for (int v : values) {
            set.add(v);
        }
        return set.size();
    }

    /** Checks whether some y‑coordinate of the point whose x differs
        lies strictly between the other two y‑coordinates. */
    private static boolean hasYInsideRange(int[] xs, int[] ys) {
        return isBetween(ys[0], ys[1], ys[2])
                || isBetween(ys[0], ys[2], ys[1])
                || isBetween(ys[1], ys[2], ys[0]);
    }

    /** Checks whether some x‑coordinate of the point whose y differs
        lies strictly between the other two x‑coordinates. */
    private static boolean hasXInsideRange(int[] xs, int[] ys) {
        return isBetween(xs[0], xs[1], xs[2])
                || isBetween(xs[0], xs[2], xs[1])
                || isBetween(xs[1], xs[2], xs[0]);
    }

    /** Generic “between” test – true iff c is strictly between a and b. */
    private static boolean isBetween(int a, int b, int c) {
        return c > Math.min(a, b) && c < Math.max(a, b);
    }

    /* -------------------------------------------------------------
       Fast I/O utilities (unchanged from the original, only kept
       because they are used by the rest of the program)
       ------------------------------------------------------------- */
    static class InputReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        InputReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream), 32768);
            tokenizer = null;
        }

        String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        boolean hasNext() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) {
                        return false;
                    }
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return true;
        }
    }
}

import java.util.Arrays;
import java.util.Scanner;

/**
 * Refactored solution for the geometry problem.
 * Improves readability, naming, structure and adds small safety
 * (floating‑point tolerance) while preserving original behaviour.
 */
public class GeometryProblem {

    private static final Scanner SCANNER = new Scanner(System.in);

    public static void main(String[] args) {
        Point p1 = readPoint();
        Point p2 = readPoint();
        Point p3 = readPoint();

        double[] distances = {
                distance(p1, p2),
                distance(p2, p3),
                distance(p1, p3)
        };
        Arrays.sort(distances);
        double sideA = distances[0];
        double sideB = distances[1];
        double sideC = distances[2];

        if (isDegenerate(p1, p2, p3)) {
            System.out.println(1);
            return;
        }

        boolean isRight = isRightTriangle(sideA, sideB, sideC);
        boolean hasAxisAlignment = hasAxisAlignment(p1, p2, p3);
        boolean specialAlignment = hasSpecialAlignment(p1, p2, p3);

        if (isRight && (hasAxisAlignment || specialAlignment)) {
            System.out.println(2);
        } else {
            System.out.println(3);
        }
    }

    /** Reads a single point (x y) from standard input. */
    private static Point readPoint() {
        int x = SCANNER.nextInt();
        int y = SCANNER.nextInt();
        return new Point(x, y);
    }

    /** Euclidean distance between two points. */
    private static double distance(Point a, Point b) {
        return Math.hypot(b.x - a.x, b.y - a.y);
    }

    /**
     * Determines whether three side lengths form a right triangle.
     * Uses a small epsilon to avoid floating‑point rounding issues.
     */
    private static boolean isRightTriangle(double a, double b, double c) {
        double[] sides = {a, b, c};
        Arrays.sort(sides);
        double smallest = sides[0];
        double middle = sides[1];
        double largest = sides[2];
        final double EPS = 1e-9;
        return Math.abs(smallest * smallest + middle * middle - largest * largest) < EPS;
    }

    /** Checks for the degenerate case where all points share the same X or all share the same Y. */
    private static boolean isDegenerate(Point p1, Point p2, Point p3) {
        return (p1.x == p2.x && p2.x == p3.x) || (p1.y == p2.y && p2.y == p3.y);
    }

    /** Whether any two of the three points share an X or a Y coordinate. */
    private static boolean hasAxisAlignment(Point p1, Point p2, Point p3) {
        return (p1.x == p2.x) || (p1.x == p3.x) || (p2.x == p3.x)
                || (p1.y == p2.y) || (p1.y == p3.y) || (p2.y == p3.y);
    }

    /** Evaluates the special alignment condition defined by the original problem. */
    private static boolean hasSpecialAlignment(Point p1, Point p2, Point p3) {
        return isCYKABLYATX(p1.x, p1.y, p2.x, p2.y, p3.x, p3.y)
                || isCYKABLYATY(p1.x, p1.y, p2.x, p2.y, p3.x, p3.y);
    }

    /* --------------------------------------------------------------------- */
    /* Helper methods that replicate the original, intentionally‑named logic */
    /* --------------------------------------------------------------------- */

    private static boolean isCYKABLYATX(int x1, int y1, int x2, int y2, int x3, int y3) {
        if (x1 == x2 && (y1 == y3 || y2 == y3)) return true;
        if (x3 == x2 && (y3 == y1 || y2 == y1)) return true;
        if (x1 == x3 && (y1 == y2 || y2 == y3)) return true;
        return false;
    }

    private static boolean isCYKABLYATY(int x1, int y1, int x2, int y2, int x3, int y3) {
        if (y1 == y2 && (x1 == x3 || x2 == x3)) return true;
        if (y3 == y2 && (x3 == x1 || x2 == x1)) return true;
        if (y1 == y3 && (x1 == x2 || x2 == x3)) return true;
        return false;
    }

    /** Simple immutable point holder. */
    private static final class Point {
        final int x;
        final int y;

        Point(int x, int y) {
            this.x = x;
            this.y = y;
        }
    }
}

import java.io.IOException;
import java.util.Scanner;

/**
 * Solution – determines the minimum number of axis‑aligned straight lines
 * required to connect three given points.
 *
 * Refactored for maintainability:
 *   • Clear class and method names.
 *   • Small, single‑purpose helper methods.
 *   • Use of {@code final} fields and early returns.
 *   • Modern I/O (Scanner / PrintWriter) with try‑with‑resources.
 */
public class Solution {

    /* ------------------------------------------------------ */
    /*  Data structure */
    /* ------------------------------------------------------ */
    private static final class Point {
        private final int x;
        private final int y;

        Point(int x, int y) {
            this.x = x;
            this.y = y;
        }

        int getX() { return x; }
        int getY() { return y; }
    }

    /* ------------------------------------------------------ */
    /*  Geometry helpers */
    /* ------------------------------------------------------ */
    /** Checks whether all points share the same X coordinate (vertical line). */
    private static boolean isVertical(Point[] pts) {
        int firstX = pts[0].x;
        for (int i = 1; i < pts.length; i++) {
            if (pts[i].x != firstX) {
                return false;
            }
        }
        return true;
    }

    /** Checks whether all points share the same Y coordinate (horizontal line). */
    private static boolean isHorizontal(Point[] pts) {
        int firstY = pts[0].y;
        for (int i = 1; i < pts.length; i++) {
            if (pts[i].y != firstY) {
                return false;
            }
        }
        return true;
    }

    /** Returns {@code true} if {@code value} lies strictly between {@code a} and {@code b}. */
    private static boolean isBetween(int value, int a, int b) {
        int lo = Math.min(a, b);
        int hi = Math.max(a, b);
        return value > lo && value < hi;
    }

    /** True if point {@code m} lies strictly between {@code a} and {@code b} on the Y axis. */
    private static boolean isBetweenY(Point m, Point a, Point b) {
        return isBetween(m.y, a.y, b.y);
    }

    /** True if point {@code m} lies strictly between {@code a} and {@code b} on the X axis. */
    private static boolean isBetweenX(Point m, Point a, Point b) {
        return isBetween(m.x, a.x, b.x);
    }

    /**
     * Calculates the minimum number of axis‑aligned straight lines needed
     * to connect the three supplied points.
     */
    private static int minLines(Point a, Point b, Point c) {
        // 1 line – all points aligned horizontally or vertically
        if (isHorizontal(new Point[]{a, b, c}) || isVertical(new Point[]{a, b, c})) {
            return 1;
        }

        // 2 lines – any pair shares a coordinate and the third point does NOT
        // lie between them on the orthogonal axis.
        if (a.x == b.x && !isBetweenY(c, a, b)) return 2;
        if (a.y == b.y && !isBetweenX(c, a, b)) return 2;

        if (a.x == c.x && !isBetweenY(b, a, c)) return 2;
        if (a.y == c.y && !isBetweenX(b, a, c)) return 2;

        if (b.x == c.x && !isBetweenY(a, b, c)) return 2;
        if (b.y == c.y && !isBetweenX(a, b, c)) return 2;

        // Otherwise three lines are required.
        return 3;
    }

    /* ------------------------------------------------------ */
    /*  Core algorithm */
    /* ------------------------------------------------------ */
    private static void solve(Scanner in, PrintWriter out) {
        Point[] points = new Point[3];
        for (int i = 0; i < 3; i++) {
            points[i] = new Point(in.nextInt(), in.nextInt());
        }

        int answer = minLines(points[0], points[1], points[2]);
        out.println(answer);
    }

    /* ------------------------------------------------------ */
    /*  Entry point */
    /* ------------------------------------------------------ */
    public static void main(String[] args) throws IOException {
        // Using try‑with‑resources guarantees proper closing of the scanner.
        try (Scanner scanner = new Scanner(System.in)) {
            solve(scanner, new PrintWriter(System.out));
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.ArrayList;
import java.util.List;

/**
 * Reads three 2‑D points from standard input and prints a single integer
 * (1, 2 or 3) that describes their geometric relationship.
 *
 * The algorithm is deliberately kept simple:
 *   1. If all three x‑coordinates are equal or all three y‑coordinates are equal
 *      → output 1.
 *   2. Otherwise, look for a pair that shares the same x‑coordinate (or y‑coordinate).
 *      If such a pair exists, order the two points by the other coordinate
 *      and check whether the third point lies strictly between them.
 *      * If it does → output 3.
 *      * Otherwise → output 2.
 *   3. If no pair shares a coordinate → output 3.
 *
 * The code is intentionally explicit rather than nested, making it straightforward
 * to read, test and extend.
 */
public class D {

    /** Simple container for a point with integer coordinates. */
    private static class Point {
        final int x;
        final int y;

        Point(int x, int y) {
            this.x = x;
            this.y = y;
        }
    }

    /** Fast scanner for reading integers from stdin – identical to the original. */
    private static class FastScanner {
        private final BufferedReader br;

        FastScanner(Reader in) {
            this.br = new BufferedReader(in);
        }

        /** Returns the next token (or reads a new line) */
        private String nextToken() throws IOException {
            while (true) {
                String line = br.readLine();
                if (line == null) {
                    return null;
                }
                StringTokenizer tokenizer = new StringTokenizer(line);
                if (tokenizer.hasMoreTokens()) {
                    return tokenizer.nextToken();
                }
            }
        }

        /** Convenience wrapper – parses the next token as an int */
        int nextInt() throws IOException {
            return Integer.parseInt(nextToken());
        }
    }

    /** Reads exactly three points from stdin. */
    private static List<Point> readPoints(FastScanner sc) {
        List<Point> points = new ArrayList<>(3);
        for (int i = 0; i < 3; i++) {
            int x = sc.nextInt();
            int y = sc.nextInt();
            points.add(new Point(x, y));
        }
        return points;
    }

    /** Returns true if all three points share the same x‑coordinate. */
    private static boolean allEqualX(List<Point> pts) {
        return pts.get(0).x == pts.get(1).x && pts.get(1).x == pts.get(2).x;
    }

    /** Returns true if all three points share the same y‑coordinate. */
    private static boolean allEqualY(List<Point> pts) {
        return pts.get(0).y == pts.get(1).y && pts.get(1).y == pts.get(2).y;
    }

    /**
     * Determines whether the given pair of points have the same x‑coordinate.
     * Returns the indices of the two points (0‑based) if they match, otherwise -1.
     */
    private static int findEqualXPair(List<Point> pts) {
        for (int i = 0; i < 3; i++) {
            for (int j = i + 1; j < 3; j++) {
                if (pts.get(i).x == pts.get(j).x) {
                    return i * 10 + j; // encode pair (i,j) in a single int
                }
            }
        }
        return -1;
    }

    /**
     * Determines whether the given pair of points have the same y‑coordinate.
     * Returns the indices of the two points (0‑based) if they match, otherwise -1.
     */
    private static int findEqualYPair(List<Point> pts) {
        for (int i = 0; i < 3; i++) {
            for (int j = i + 1; j < 3; j++) {
                if (pts.get(i).y == pts.get(j).y) {
                    return i * 10 + j;
                }
            }
        }
        return -1;
    }

    /** Swaps two integer variables – tiny utility used by callers. */
    private static void swap(int[] arr, int i, int j) {
        int tmp = arr[i];
        arr[i] = arr[j];
        arr[j] = tmp;
    }

    /**
     * Core logic that decides which integer (1, 2 or 3) to output.
     *
     * @param points three input points
     * @return the computed result
     */
    private static int computeResult(List<Point> points) {
        // 1️⃣ Full alignment on x or y → result = 1
        if (allEqualX(points) || allEqualY(points)) {
            return 1;
        }

        // 2️⃣ Look for a pair that shares the same x‑coordinate
        int pairX = findEqualXPair(points);
        if (pairX != -1) {
            // Decode the pair indices from the encoded value
            int i = pairX / 10;
            int j = pairX % 10;

            // Extract the y‑values of the pair and the third point
            int y_i = points.get(i).y;
            int y_j = points.get(j).y;
            int y_k = points.get(3 - i - j).y; // remaining index

            // Order the pair's y‑values (a ≤ b)
            if (y_i > y_j) {
                swap(new int[]{y_i, y_j}, 0, 1);
            }
            // y_i <= y_j now
            // The third point lies strictly between them ?
            if (y_i < y_k && y_j > y_k) {
                return 3;
            } else {
                return 2;
            }
        }

        // 3️⃣ Look for a pair that shares the same y‑coordinate (mirror of step 2)
        int pairY = findEqualYPair(points);
        if (pairY != -1) {
            int i = pairY / 10;
            int j = pairY % 10;

            int x_i = points.get(i).x;
            int x_j = points.get(j).x;
            int x_k = points.get(3 - i - j).x;

            // Order the pair's x‑values (a ≤ b)
            if (x_i > x_j) {
                swap(new int[]{x_i, x_j}, 0, 1);
            }
            // x_i <= x_j now
            // The third point lies strictly between them ?
            if (x_i < x_k && x_j > x_k) {
                return 3;
            } else {
                return 2;
            }
        }

        // 4️⃣ No matching pair → result = 3
        return 3;
    }

    /** Main entry point – unchanged public signature. */
    public static void main(String[] args) throws Exception {
        FastScanner sc = new FastScanner(new InputStreamReader(System.in));
        List<Point> points = readPoints(sc);
        int result = computeResult(points);
        System.out.println(result);
    }
}

