/**
 * Wrapper around {@link BufferedReader} that provides convenient
 * tokenised input methods.
 */
class InputReader {
    private final BufferedReader br;
    private StringTokenizer st;

    InputReader(InputStream stream) {
        br = new BufferedReader(new InputStreamReader(stream), 32768);
        st = null;
    }

    /** @return next token as a {@link String} */
    String next() {
        while (st == null || !st.hasMoreTokens()) {
            try {
                st = new StringTokenizer(br.readLine());
            } catch (IOException e) {
                throw new RuntimeException(e);
            }
        }
        return st.nextToken();
    }

    /** @return next token parsed as {@code int} */
    int nextInt() {
        return Integer.parseInt(next());
    }

    /** @return next token parsed as {@code long} */
    long nextLong() {
        return Long.parseLong(next());
    }

    /** @return next token parsed as {@code double} */
    double nextDouble() {
        return Double.parseDouble(next());
    }

    /** @return an array of {@code int} of the requested size */
    int[] nextIntArray(int n) {
        int[] a = new int[n];
        for (int i = 0; i < n; i++) {
            a[i] = nextInt();
        }
        return a;
    }

    /** @return an array of {@code long} of the requested size */
    long[] nextLongArray(int n) {
        long[] a = new long[n];
        for (int i = 0; i < n; i++) {
            a[i] = nextLong();
        }
        return a;
    }
}

/**
 * Core logic of the program – reads six integers and determines
 * the result according to the original specification.
 */
class Solver {

    /**
     * Reads six integers from {@link InputReader} and writes the
     * calculated result to {@link PrintWriter}.
     */
    void solve(InputReader in, PrintWriter out) {
        // read the six integers (the original code used variable names a‑f)
        int a = in.nextInt(); // first integer
        int b = in.nextInt(); // second integer
        int c = in.nextInt(); // third integer
        int d = in.nextInt(); // fourth integer
        int e = in.nextInt(); // fifth integer
        int f = in.nextInt(); // sixth integer

        int result = evaluate(a, b, c, d, e, f);
        out.print(result);
    }

    /**
     * Encapsulates the original series of conditional checks.
     * The method returns:
     *   1 – when three specific equalities hold,
     *   2 – when any of the overlapping‑interval checks succeed,
     *   3 – otherwise (behaviour that matched the original default value).
     */
    private int evaluate(int a, int b, int c, int d, int e, int f) {
        // Helper that implements the “overlap” condition used many times.
        // The condition is true when x is either >= max(y,z) or <= min(y,z).
        boolean overlaps(int x, int y, int z) {
            return x >= Math.max(y, z) || x <= Math.min(y, z);
        }

        // Each condition from the original code is expressed with a meaningful name.
        boolean condAEqualsCAndFOverlapsBOrD = (a == c) && overlaps(f, b, d);
        boolean condAEqualsEAndDOverlapsBOrF = (a == e) && overlaps(d, b, f);
        boolean condEEqualsCAndBOverlapsDOrF = (e == c) && overlaps(b, d, f);
        boolean condBEqualsDAndEOverlapsAOrC = (b == d) && overlaps(e, a, c);
        boolean condBEqualsFAndCOverlapsAOrE = (b == f) && overlaps(c, a, e);
        boolean condFEqualsDAndAOverlapsCOrE = (f == d) && overlaps(a, c, e);

        // Collect all “type‑2” overlapping situations.
        if (condAEqualsCAndFOverlapsBOrD
                || condAEqualsEAndDOverlapsBOrF
                || condEEqualsCAndBOverlapsDOrF
                || condBEqualsDAndEOverlapsAOrC
                || condBEqualsFAndCOverlapsAOrE
                || condFEqualsDAndAOverlapsCOrE) {
            return 2;
        }

        // Special cases that force the result to 1.
        if ((a == c) && (c == e)) {
            return 1;
        }
        if ((b == d) && (d == f)) {
            return 1;
        }

        // Default behaviour mirrors the original code (variable x was initialised to 3).
        return 3;
    }
}

