/**
 * Solution for the “Three Points” problem.
 *
 * <p>
 *   The program reads three points (x, y) from standard input.
 *   It then prints:
 *   <ul>
 *     <li>1 – if all three points share the same X coordinate or the same Y coordinate.</li>
 *     <li>2 – if one of the points lies on the axis‑aligned segment formed by the other two.</li>
 *     <li>3 – otherwise.</li>
 *   </ul>
 * </p>
 */
public class Main {

    /** Simple container for a point in 2‑D integer space. */
    private static final class Point {
        final int x;
        final int y;

        Point(int x, int y) {
            this.x = x;
            this.y = y;
        }
    }

    /** Fast scanner based on the original CodeChef template. */
    private static final class FastScanner {
        private final InputStream stream;
        private final byte[] buffer = new byte[8192];
        private int currentByte;
        private int bytesRead;
        private int pointer;

        FastScanner(InputStream stream) {
            this.stream = stream;
        }

        private int readByte() throws IOException {
            if (pointer >= bytesRead) {
                currentByte = stream.read();
                if (currentByte == -1) {
                    return -1;
                }
                pointer = 0;
                bytesRead = currentByte == 0 ? 1 : stream.read(buffer);
            } else {
                currentByte--;
            }
            return buffer[currentByte];
        }

        private static boolean isSpace(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        /** Reads the next integer from the input. */
        int nextInt() throws IOException {
            int c = readByte();
            while (isSpace(c)) {
                c = readByte();
            }
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = readByte();
            }

            int result = 0;
            do {
                if (c < '0' || c > '9') {
                    throw new InputMismatchException();
                }
                result = result * 10 + (c - '0');
                c = readByte();
            } while (!isSpace(c));

            return result * sign;
        }
    }

    /** Test whether the third point lies on the axis‑aligned segment defined by the first two. */
    private static boolean isOnSegment(Point a, Point b, Point c) {
        // Same X and c's Y lies between a and b
        if ((a.x == b.x || a.x == c.x || b.x == c.x) && isBetween(a.y, b.y, c.y)) {
            return true;
        }
        // Same Y and c's X lies between a and b
        if ((a.y == b.y || a.y == c.y || b.y == c.y) && isBetween(a.x, b.x, c.x)) {
            return true;
        }
        return false;
    }

    /** Helper that checks if a value lies between two others (inclusive). */
    private static boolean isBetween(int lo, int hi, int value) {
        return Math.min(lo, hi) <= value && value <= Math.max(lo, hi);
    }

    /** Checks if any of the three points shares an X or a Y coordinate with the others. */
    private static boolean allXEqual(Point p1, Point p2, Point p3) {
        return p1.x == p2.x && p2.x == p3.x;
    }

    private static boolean allYEqual(Point p1, Point p2, Point p3) {
        return p1.y == p2.y && p2.y == p3.y;
    }

    /**
     * Determines whether the three points can be covered by drawing at most two axis‑aligned
     * lines (vertical or horizontal) that intersect each other.
     *
     * @return true if some point lies on the axis‑aligned segment of another pair.
     */
    private static boolean needsTwoLines(Point p1, Point p2, Point p3) {
        // Check all permutations for the “point on segment” condition
        return isOnSegment(p1, p2, p3) ||
               isOnSegment(p2, p3, p1) ||
               isOnSegment(p1, p3, p2);
    }

    public static void main(String[] args) throws Exception {
        FastScanner scanner = new FastScanner(System.in);

        Point[] points = new Point[3];
        for (int i = 0; i < 3; i++) {
            int x = scanner.nextInt();
            int y = scanner.nextInt();
            points[i] = new Point(x, y);
        }

        // If all three points share the same X coordinate or the same Y coordinate,
        // we can cover them with a single line.
        if (allXEqual(points[0], points[1], points[2]) || allYEqual(points[0], points[1], points[2])) {
            System.out.println(1);
            return;
        }

        // Otherwise, if one point lies on the axis‑aligned segment of the other two,
        // two lines are sufficient.
        if (needsTwoLines(points[0], points[1], points[2]) ||
            needsTwoLines(points[1], points[2], points[0]) ||
            needsTwoLines(points[0], points[2], points[1])) {
            System.out.println(2);
        } else {
            System.out.println(3);
        }
    }
}

