/**
 * Solution for the problem that reads three points and determines the
 * smallest number of axis‑aligned line segments needed to connect them.
 *
 * <p>Changes made for readability and maintainability:
 * <ul>
 *   <li>Extracted small helper methods with expressive names.</li>
 *   <li>Replaced the duplicated permutation logic with explicit
 *       calls to a single, well‑named {@code check} method.</li>
 *   <li>Used a tiny immutable {@code Point} class with final fields.</li>
 *   <li>Removed unused imports and added Javadoc comments.</li>
 *   <li>Kept the original algorithmic behaviour while improving structure.</li>
 * </ul>
 */
public class Main {

    /** Entry point – delegates all work to {@link #solve(InputReader,PrintWriter)}. */
    public static void main(String[] args) {
        solve(new InputReader(System.in), new PrintWriter(System.out));
    }

    /**
     * Reads three points, decides whether 1, 2 or 3 lines are required and prints the answer.
     *
     * @param in  reader that supplies the three coordinate pairs
     * @param out writer to which the result is printed
     */
    private static void solve(InputReader in, PrintWriter out) {
        Point a = readPoint(in);
        Point b = readPoint(in);
        Point c = readPoint(in);

        if (isAllSameXOrY(a, b, c)) {
            out.println(1);
        } else if (anyLShapeExists(a, b, c)) {
            out.println(2);
        } else {
            out.println(3);
        }
    }

    /** Reads a single point (two integers) from the supplied {@link InputReader}. */
    private static Point readPoint(InputReader in) {
        int x = in.nextInt();
        int y = in.nextInt();
        return new Point(x, y);
    }

    /** True when the three points lie on a single vertical or horizontal line. */
    private static boolean isAllSameXOrY(Point p1, Point p2, Point p3) {
        return (p1.x == p2.x && p2.x == p3.x)   // vertical line
                || (p1.y == p2.y && p2.y == p3.y); // horizontal line
    }

    /**
     * Determines whether any ordering of the three points lets the third point
     * lie on an axis‑aligned “L” formed by the other two – exactly the condition
     * that originally warranted a {@code 2}‑line answer.
     */
    private static boolean anyLShapeExists(Point p1, Point p2, Point p3) {
        // The original code exercised all six possible orderings.
        return check(p1, p2, p3)
                || check(p2, p1, p3)
                || check(p1, p3, p2)
                || check(p3, p1, p2)
                || check(p2, p3, p1)
                || check(p3, p2, p1);
    }

    /**
     * Implements the original {@code check} logic with clearer naming and a
     * helper {@code between} method.
     *
     * @return {@code true} if the candidate point sits on the vertical side
     *         defined by {@code start} and the horizontal side defined by {@code end}.
     */
    private static boolean check(Point start, Point end, Point candidate) {
        // candidate must share the x‑coordinate of {@code start}
        // and its y‑value must be between start.y and end.y (inclusive).
        if (candidate.x == start.x && between(candidate.y, start.y, end.y)) {
            return true;
        }
        // candidate must share the y‑coordinate of {@code end}
        // and its x‑value must be between start.x and end.x (inclusive).
        if (candidate.y == end.y && between(candidate.x, start.x, end.x)) {
            return true;
        }
        return false;
    }

    /**
     * Returns {@code true} when {@code value} lies inclusively between {@code a}
     * and {@code b} (order‑independent).
     */
    private static boolean between(int value, int a, int b) {
        return value >= Math.min(a, b) && value <= Math.max(a, b);
    }

    /** Simple immutable container for a point with integer coordinates. */
    private static final class Point {
        final int x;
        final int y;

        Point() {
            this(0, 0);
        }

        Point(int x, int y) {
            this.x = x;
            this.y = y;
        }
    }
}

