import java.io.IOException;
import java.io.InputStream;
import java.io.OutputStream;
import java.io.PrintWriter;
import java.util.Arrays;

/**
 * Refactored solution for the “Three Points” problem.
 * The logic is identical to the original implementation, but the
 * code has been reorganised for readability, maintainability and
 * proper separation of concerns.
 */
public class Main {

    public static void main(String[] args) {
        InputStream inStream = System.in;
        OutputStream outStream = System.out;
        InputReader reader = new InputReader(inStream);
        PrintWriter printer = new PrintWriter(outStream);

        // There is only a single test case in the original source.
        Solver solver = new Solver();
        solver.solve(reader, printer);

        printer.close();
    }

    /**
     * Core logic that reads three points, analyses their geometry and
     * prints the minimum number of axis‑aligned segments required to
     * connect them.
     */
    private static class Solver {

        /** Entry point used by {@link Main#main}. */
        void solve(InputReader reader, PrintWriter printer) {
            Point[] points = readPoints(reader);
            int answer = computeAnswer(points);
            printer.println(answer);
        }

        /** Reads exactly three points from the input stream. */
        private static Point[] readPoints(InputReader reader) {
            Point[] points = new Point[3];
            for (int i = 0; i < 3; i++) {
                int x = reader.readInt();
                int y = reader.readInt();
                points[i] = new Point(x, y);
            }
            return points;
        }

        /**
         * Determines the minimal number of axis‑aligned segments required
         * to connect the three given points.
         *
         * @return 1, 2 or 3 according to the geometric configuration.
         */
        private static int computeAnswer(Point[] pts) {
            // 1️⃣  All points share the same X or the same Y → one straight line.
            if (allSameCoordinate(pts, Point::x) || allSameCoordinate(pts, Point::y)) {
                return 1;
            }

            // 2️⃣  Count how many points have at least one neighbour aligned
            //      horizontally or vertically.
            int pointsWithNeighbour = countPointsWithNeighbour(pts);
            if (pointsWithNeighbour == 3) {
                return 2;          // Every point can be linked with a neighbour.
            }
            if (pointsWithNeighbour == 0) {
                return 3;          // No two points share X or Y.
            }

            // 3️⃣  The only remaining situation: a “corner” formed by a pair
            //      of aligned points and a third point that may lie between
            //      them on that axis.
            Point f = findAlignedPair(pts)[0];
            Point s = findAlignedPair(pts)[1];
            Point t = remainingPoint(pts, f, s);

            // If the third point lies strictly between the pair on the shared
            // axis we need three segments, otherwise two suffice.
            return (liesBetween(f, s, t)) ? 3 : 2;
        }

        /** Returns true iff all points have the same value for the supplied selector. */
        private static boolean allSameCoordinate(Point[] pts, CoordSelector selector) {
            int first = selector.select(pts[0]);
            for (Point p : pts) {
                if (selector.select(p) != first) {
                    return false;
                }
            }
            return true;
        }

        /** Counts points that share X or Y with at least one other point. */
        private static int countPointsWithNeighbour(Point[] pts) {
            int[] counters = new int[3];
            for (int i = 0; i < 3; i++) {
                for (int j = 0; j < 3; j++) {
                    if (i == j) {
                        continue;
                    }
                    if (pts[i].x == pts[j].x || pts[i].y == pts[j].y) {
                        counters[i]++;
                    }
                }
            }
            return (int) Arrays.stream(counters).filter(c -> c > 0).count();
        }

        /**
         * Finds a pair of distinct points that are aligned horizontally
         * or vertically. Returns the two points as a two‑element array.
         * The method assumes that such a pair exists.
         */
        private static Point[] findAlignedPair(Point[] pts) {
            for (int i = 0; i < 3; i++) {
                for (int j = i + 1; j < 3; j++) {
                    if (pts[i].x == pts[j].x || pts[i].y == pts[j].y) {
                        return new Point[]{pts[i], pts[j]};
                    }
                }
            }
            throw new IllegalStateException("No aligned pair found – should be impossible.");
        }

        /** Returns the point that is not part of the supplied pair. */
        private static Point remainingPoint(Point[] all, Point a, Point b) {
            for (Point p : all) {
                if (p != a && p != b) {
                    return p;
                }
            }
            throw new IllegalStateException("Third point not found.");
        }

        /** true if the coordinate of {@code middle} lies strictly between those of {@code a} and {@code b}. */
        private static boolean liesBetween(Point a, Point b, Point middle) {
            if (a.x == b.x) { // vertical alignment
                int min = Math.min(a.y, b.y);
                int max = Math.max(a.y, b.y);
                return min < middle.y && middle.y < max;
            }
            // horizontal alignment
            int min = Math.min(a.x, b.x);
            int max = Math.max(a.x, b.x);
            return min < middle.x && middle.x < max;
        }
    }

    /** Simple immutable point with X and Y coordinates. */
    private static final class Point {
        final int x;
        final int y;

        Point(int x, int y) {
            this.x = x;
            this.y = y;
        }

        /** Reads a point from the given {@link InputReader}. */
        static Point fromReader(InputReader reader) {
            int x = reader.readInt();
            int y = reader.readInt();
            return new Point(x, y);
        }

        /** Functional interface to extract either X or Y. */
        @FunctionalInterface
        interface CoordSelector {
            int select(Point p);
        }
    }

    /**
     * Minimal input reader that works with the custom integer reading logic
     * used in the original program.
     */
    private static class InputReader {
        private final InputStream stream;
        private final byte[] buffer = new byte[1024];
        private int curChar;
        private int numChars;
        private final InputReader.SpaceCharFilter filter;

        InputReader(InputStream stream) {
            this.stream = stream;
            this.filter = this::isWhitespace;
        }

        private int read() {
            if (numChars == -1) {
                throw new java.util.InputMismatchException();
            }
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buffer);
                } catch (IOException e) {
                    throw new java.util.InputMismatchException();
                }
                if (numChars <= 0) {
                    return -1;
                }
            }
            return buffer[curChar++];
        }

        /** Reads the next signed integer from the input. */
        int readInt() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            int value = 0;
            do {
                if (c < '0' || c > '9') {
                    throw new java.util.InputMismatchException();
                }
                value = value * 10 + (c - '0');
                c = read();
            } while (!isSpaceChar(c));
            return value * sign;
        }

        private boolean isSpaceChar(int c) {
            return filter != null && filter.isSpaceChar(c);
        }

        private static boolean isWhitespace(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }
    }
}

import java.util.Scanner;

/**
 * Refactored solution for the Round 340 problem.
 *
 * <p>
 * The program reads the coordinates of three points and outputs:
 * <ul>
 *   <li>1 – if all three points share the same x‑coordinate or the same y‑coordinate,
 *   <li>2 – otherwise, when a point lies strictly between the other two on a shared axis,
 *   <li>3 – in every remaining case.
 * </ul>
 * </p>
 *
 * <p>The logic of the original implementation has been extracted into small,
 * well‑named blocks, making the flow easy to follow and maintain.</p>
 */
public class Round340 {

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        // read the six integer coordinates
        int x1 = sc.nextInt();
        int y1 = sc.nextInt();
        int x2 = sc.nextInt();
        int y2 = sc.nextInt();
        int x3 = sc.nextInt();
        int y3 = sc.nextInt();

        // compute and print the result
        System.out.println(solve(x1, y1, x2, y2, x3, y3));
        sc.close();
    }

    /**
     * Implements the exact decision logic of the original program,
     * but with clear, linear control flow.
     *
     * @return 1, 2 or 3 according to the specification
     */
    private static int solve(int x1, int y1, int x2, int y2, int x3, int y3) {
        // 1 – all x equal or all y equal
        if ((x1 == x2 && x1 == x3) || (y1 == y2 && y1 == y3)) {
            return 1;
        }

        // Helper predicate: checks if c is strictly between a and b
        java.util.function.Predicate<Integer, Integer, Integer> between = (a, b, c) ->
                c > Math.min(a, b) && c < Math.max(a, b);

        // Check ordered x‑equalities (the same order as the original code)
        if (x1 == x2) {
            return between.test(y1, y2, y3) ? 3 : 2;
        }
        if (x2 == x3) {
            return between.test(y2, y3, y1) ? 3 : 2;
        }
        if (x1 == x3) {
            return between.test(y1, y3, y2) ? 3 : 2;
        }

        // Then check ordered y‑equalities
        if (y1 == y2) {
            return between.test(x1, x2, x3) ? 3 : 2;
        }
        if (y2 == y3) {
            return between.test(x2, x3, x1) ? 3 : 2;
        }
        if (y1 == y3) {
            return between.test(x1, x3, x2) ? 3 : 2;
        }

        // Default case – none of the special conditions matched
        return 3;
    }
}

