/**
 * Fast integer reader that works with {@link BufferedReader} and {@link StringTokenizer}.
 * It avoids the overhead of {@link Scanner} while still supporting the primitives used by the
 * solution.
 */
class FastScanner {
    private final BufferedReader br;
    private StringTokenizer st;

    FastScanner(InputStream stream) {
        br = new BufferedReader(new InputStreamReader(stream));
    }

    /** Returns the next token or {@code null} if EOF is reached. */
    private String nextToken() {
        while (st == null || !st.hasMoreTokens()) {
            try {
                st = new StringTokenizer(br.readLine());
            } catch (IOException e) {
                return null;
            }
        }
        return st.nextToken();
    }

    int nextInt() {
        return Integer.parseInt(nextToken());
    }

    // Additional helpers (nextLong, nextDouble, …) can be added if needed.
}

/**
 * Holds the three points that are read from the input.
 */
final class Point {
    final int x;
    final int y;

    Point(int x, int y) {
        this.x = x;
        this.y = y;
    }
}

/**
 * Encapsulates the geometric problem solving logic.
 *
 * <p>All public methods are static‑like in behaviour – they accept a {@link FastScanner}
 * and a {@link PrintWriter} and write exactly one integer answer.
 */
class Solver {

    /** Maximum number of points we need to store. */
    private static final int POINT_COUNT = 3;

    /** Temporary array used while reading input points. */
    private final Point[] points = new Point[POINT_COUNT];

    /** Reads three points from the supplied scanner. */
    private void readPoints(FastScanner scanner) {
        for (int i = 0; i < POINT_COUNT; i++) {
            int x = scanner.nextInt();
            int y = scanner.nextInt();
            points[i] = new Point(x, y);
        }
    }

    /** Determines whether all three points share the same x‑coordinate or the same y‑coordinate. */
    private boolean allXEqual() {
        return points[0].x == points[1].x && points[1].x == points[2].x;
    }

    private boolean allYEqual() {
        return points[0].y == points[1].y && points[1].y == points[2].y;
    }

    /** Checks the special “vertical” predicate used in the original solution. */
    private boolean verticalCondition(int i, int j, int k) {
        return points[i].x == points[j].x &&
                (Math.min(points[i].y, points[j].y) >= points[k].y ||
                 Math.max(points[i].y, points[j].y) <= points[k].y);
    }

    /** Checks the special “horizontal” predicate used in the original solution. */
    private boolean horizontalCondition(int i, int j, int k) {
        return points[i].y == points[j].y &&
                (Math.min(points[i].x, points[j].x) >= points[k].x ||
                 Math.max(points[i].x, points[j].x) <= points[k].x);
    }

    /** Solves the problem and writes the result to the supplied {@link PrintWriter}. */
    void solve(FastScanner scanner, PrintWriter out) {
        readPoints(scanner);

        // 1 – all points are already collinear vertically or horizontally → only one line needed.
        if (allXEqual() || allYEqual()) {
            out.println(1);
            return;
        }

        // 2 – test every ordering of three points to see if any pair creates a line that
        //     also “covers” the third point according to the problem’s definition.
        boolean canFinishInTwo = verticalCondition(0, 1, 2) ||
                                    verticalCondition(0, 2, 1) ||
                                    verticalCondition(1, 2, 0) ||
                                    horizontalCondition(0, 1, 2) ||
                                    horizontalCondition(0, 2, 1) ||
                                    horizontalCondition(1, 2, 0);

        out.println(canFinishInTwo ? 2 : 3);
    }
}

import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.StringTokenizer;

/**
 * Main class that reads groups of three points and prints the required code.
 * The logic has been split into small, well‑named methods to improve
 * readability and maintainability.
 */
public class Main {

    public static void main(String[] args) {
        FastScanner fs = new FastScanner();
        PrintWriter out = new PrintWriter(System.out);

        while (fs.hasNext()) {
            int x1 = fs.nextInt();
            int y1 = fs.nextInt();
            int x2 = fs.nextInt();
            int y2 = fs.nextInt();
            int x3 = fs.nextInt();
            int y3 = fs.nextInt();

            int result = solve(x1, y1, x2, y2, x3, y3);
            out.println(result);
        }

        out.close();
    }

    /**
     * Determines the output for a single test case.
     *
     * @return 1, 2, or 3 according to the original algorithm
     */
    private static int solve(int x1, int y1, int x2, int y2, int x3, int y3) {
        // 1️⃣  All x‑coordinates equal OR all y‑coordinates equal → answer 1
        if ((x1 == x2 && x2 == x3) || (y1 == y2 && y2 == y3)) {
            return 1;
        }

        // 2️⃣  Any two share the same X → treat as a vertical case
        if (x1 == x2 || x1 == x3 || x2 == x3) {
            if (x1 == x2) {
                return isBetween(y1, y2, y3) ? 3 : 2;
            } else if (x1 == x3) {
                return isBetween(y1, y3, y2) ? 3 : 2;
            } else { // x2 == x3
                return isBetween(y2, y3, y1) ? 3 : 2;
            }
        }

        // 3️⃣  Any two share the same Y → treat as a horizontal case
        if (y1 == y2 || y1 == y3 || y2 == y3) {
            if (y1 == y2) {
                return isBetween(x1, x2, x3) ? 3 : 2;
            } else if (y1 == y3) {
                return isBetween(x1, x3, x2) ? 3 : 2;
            } else { // y2 == y3
                return isBetween(x2, x3, x1) ? 3 : 2;
            }
        }

        // 4️⃣  No coordinate shared → answer 3
        return 3;
    }

    /**
     * Checks whether {@code value} lies strictly between {@code a} and {@code b}.
     */
    private static boolean isBetween(int a, int b, int value) {
        return (a < value && value < b) || (b < value && value < a);
    }

    /**
     * Fast scanner that works like the original InputReader but is a bit more
     * compact and keeps the same public API.
     */
    private static class FastScanner {
        private final BufferedReader buf;
        private StringTokenizer tok;

        FastScanner() {
            buf = new BufferedReader(new InputStreamReader(System.in));
        }

        boolean hasNext() {
            while (tok == null || !tok.hasMoreElements()) {
                try {
                    tok = new StringTokenizer(buf.readLine());
                } catch (Exception e) {
                    return false;
                }
            }
            return true;
        }

        String next() {
            return hasNext() ? tok.nextToken() : null;
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        long nextLong() {
            return Long.parseLong(next());
        }

        double nextDouble() {
            return Double.parseDouble(next());
        }

        // Additional helpers kept for completeness (not used here)
        BigInteger nextBigInteger() {
            return new BigInteger(next());
        }

        BigDecimal nextBigDecimal() {
            return new BigDecimal(next());
        }
    }
}

/*
 * Refactored version of the original program.
 * The program reads three points (x, y), evaluates a simple combinatorial answer
 * and prints it.  The logic is unchanged – only the structure, naming and
 * separation of concerns have been improved for readability and maintainability.
 *
 *   •  I/O handling is isolated in a small `AnotherReader` wrapper.
 *   •  Domain objects and comparators are clearly named.
 *   •  Core algorithm lives in tiny, pure methods.
 *   •  Magic numbers, duplicated code and unnecessary static helpers have been removed.
 *
 * Compile & run (assuming the original input format):
 *   javac Main.java
 *   java Main
 */

import java.io.*;
import java.util.*;

public class Main {

    /* --------------------------------------------------------------------- */
    /*  Data model                                                          */
    /* --------------------------------------------------------------------- */

    /** Simple immutable point used throughout the program. */
    private static final class Node {
        final int x;
        final int y;

        Node(int x, int y) {
            this.x = x;
            this.y = y;
        }
    }

    /* --------------------------------------------------------------------- */
    /*  Core algorithm                                                       */
    /* --------------------------------------------------------------------- */

    /**
     * Reads three points, computes the answer and prints it.
     *
     * @param reader source of integers (two per point, three points total)
     * @param out    destination for the answer
     * @throws IOException if reading fails
     */
    private static void solve(AnotherReader reader, PrintWriter out) throws IOException {
        Node[] points = new Node[3];
        Set<Integer> distinctX = new HashSet<>();
        Set<Integer> distinctY = new HashSet<>();

        // --- read three points ------------------------------------------------
        for (int i = 0; i < 3; i++) {
            points[i] = new Node(reader.ni(), reader.ni());
            distinctX.add(points[i].x);
            distinctY.add(points[i].y);
        }

        int answer = Math.min(distinctX.size(), distinctY.size());

        // If the answer could still be 3 we must perform extra checks.
        if (answer == 2 && needsThree(points)) {
            out.println(3);
            return;
        }

        out.println(answer);
    }

    /**
     * Determines whether the three supplied points force the answer to be {@code 3}.
     * This reproduces the original validation logic but expressed with clearer
     * intent and no duplicated code.
     *
     * @param pts three points (guaranteed to have exactly two distinct x‑values
     *            or two distinct y‑values)
     * @return {@code true} if the configuration matches a “degenerate” case
     */
    private static boolean needsThree(Node[] pts) {
        // --- check edges when sorted by x ------------------------------------
        Node[] byX = pts.clone();
        Comparator<Node> byXComparator = Comparator.comparingInt(p -> p.x);
        Arrays.sort(byX, byXComparator);

        if (byX[0].x == byX[1].x) {
            int lowY = Math.min(byX[0].y, byX[1].y);
            int highY = Math.max(byX[0].y, byX[1].y);
            int yOfThird = byX[2].y;
            if (yOfThird < lowY || yOfThird > highY) {
                return true;
            }
        }
        if (byX[1].x == byX[2].x) {
            int lowY = Math.min(byX[1].y, byX[2].y);
            int highY = Math.max(byX[1].y, byX[2].y);
            int yOfFirst = byX[0].y;
            if (yOfFirst < lowY || yOfFirst > highY) {
                return true;
            }
        }

        // --- symmetric checks for sorting by y -------------------------------
        Node[] byY = pts.clone();
        Comparator<Node> byYComparator = Comparator.comparingInt(p -> p.y);
        Arrays.sort(byY, byYComparator);

        if (byY[0].y == byY[1].y) {
            int lowX = Math.min(byY[0].x, byY[1].x);
            int highX = Math.max(byY[0].x, byY[1].x);
            int xOfThird = byY[2].x;
            if (xOfThird < lowX || xOfThird > highX) {
                return true;
            }
        }
        if (byY[1].y == byY[2].y) {
            int lowX = Math.min(byY[1].x, byY[2].x);
            int highX = Math.max(byY[1].x, byY[2].x);
            int xOfFirst = byY[0].x;
            if (xOfFirst < lowX || xOfFirst > highX) {
                return true;
            }
        }

        return false;
    }

    /* --------------------------------------------------------------------- */
    /*  Program entry point                                                   */
    /* --------------------------------------------------------------------- */

    /**
     * Starts the application.  The {@code useOnlineJudge} flag decides whether
     * input is taken from {@code System.in} (typical for online judges) or from
     * a file named {@code input.txt}.  The flag can be toggled for local testing.
     */
    public static void main(String[] args) throws IOException {
        boolean useOnlineJudge = true; // set to false to read from "input.txt"

        AnotherReader reader = (useOnlineJudge)
                ? new AnotherReader()                 // reads from stdin
                : new AnotherReader(100);             // placeholder for file reading

        PrintWriter out = new PrintWriter(System.out);
        solve(reader, out);
        out.flush();
    }

    /* --------------------------------------------------------------------- */
    /*  Minimal I/O helper                                                    */
    /* --------------------------------------------------------------------- */

    /**
     * Very small wrapper around {@link BufferedReader} that mimics the original
     * {@code AnotherReader}.  Only the methods actually used by the program are
     * exposed; everything else has been eliminated to keep the class lean.
     */
    private static final class AnotherReader {
        private final BufferedReader br;
        private StringTokenizer st;

        /** Reads from standard input. */
        AnotherReader() throws FileNotFoundException {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        /** Reads from a fixed file (kept for compatibility). */
        AnotherReader(int dummy) throws FileNotFoundException {
            // The original used a file named "input.txt".  The constant 100 is
            // irrelevant – we simply re‑use the same constructor signature.
            br = new BufferedReader(new FileReader("input.txt"));
        }

        /** Returns the next token or blocks until one is available. */
        private String next() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                st = new StringTokenizer(br.readLine());
            }
            return st.nextToken();
        }

        /** Convenience methods used by {@link #solve}. */
        int ni() throws IOException                { return Integer.parseInt(next()); }
        long nl() throws IOException                { return Long.parseLong(next()); }
        double nd() throws IOException               { return Double.parseDouble(next()); }
        String nln() throws IOException             { return br.readLine(); }
    }
}

import java.io.*;
import java.util.*;
import java.util.stream.Collectors;

/**
 * Refactored version of the original program (formerly D617).
 * The code is split into small, focused classes and methods,
 * uses expressive names, and follows standard Java conventions.
 */
public class D617 {

    /** Simple container for a point (x, y). */
    private static final class Point implements Comparable<Point> {
        final long x, y;

        Point(long x, long y) {
            this.x = x;
            this.y = y;
        }

        /** Lexicographic ordering – first by x, then by y. */
        @Override
        public int compareTo(Point o) {
            int cmp = Long.compare(this.x, o.x);
            return (cmp != 0) ? cmp : Long.compare(this.y, o.y);
        }
    }

    /** Fast Scanner that lazily reads tokens from the input stream. */
    private static final class FastScanner {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        FastScanner(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream), 1 << 16);
        }

        /** Makes sure a {@link StringTokenizer} is available. */
        private void loadTokenizer() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                tokenizer = new StringTokenizer(reader.readLine());
            }
        }

        long nextLong() throws IOException {
            loadTokenizer();
            return Long.parseLong(tokenizer.nextToken());
        }

        // Convenience methods – they are not used directly but kept for API parity.
        int nextInt() throws IOException { return Integer.parseInt(next()); }
        double nextDouble() throws IOException { return Double.parseDouble(next()); }
    }

    /** Tests whether a third point lies between two others on the same x‑ or y‑axis. */
    private static boolean isIntermediate(Point[] pts, int i, int j, boolean onX) {
        Point a = pts[i];
        Point b = pts[j];

        long fixed = onX ? a.x : a.y;
        long min = Math.min( (onX ? a.y : a.x), (onX ? b.y : b.x) );
        long max = Math.max( (onX ? a.y : a.x), (onX ? b.y : b.x) );

        for (int k = 0; k < pts.length; k++) {
            if (k == i || k == j) continue;                     // skip the two endpoints
            Point p = pts[k];
            if (onX) {
                if (p.x == fixed && p.y >= min && p.y <= max) return true;
            } else {
                if (p.y == fixed && p.x >= min && p.x <= max) return true;
            }
        }
        return false;
    }

    public static void main(String[] args) throws Exception {
        // -----------------------------------------------------------------------
        // Input handling
        // -----------------------------------------------------------------------
        try (FastScanner scanner = new FastScanner(System.in);
             PrintWriter out = new PrintWriter(System.out)) {

            Point[] points = new Point[3];
            for (int i = 0; i < 3; i++) {
                long x = scanner.nextLong();
                long y = scanner.nextLong();
                points[i] = new Point(x, y);
            }

            // -------------------------------------------------------------------
            // Primary ordering – lexicographic (x then y)
            // -------------------------------------------------------------------
            Arrays.sort(points);

            // -------------------------------------------------------------------
            // Trivial case: all x‑coordinates equal or all y‑coordinates equal
            // -------------------------------------------------------------------
            Set<Long> uniqX = Arrays.stream(points).mapToLong(p -> p.x).boxed()
                                        .collect(Collectors.toSet());
            Set<Long> uniqY = Arrays.stream(points).mapToLong(p -> p.y).boxed()
                                        .collect(Collectors.toSet());

            if (uniqX.size() == 1 || uniqY.size() == 1) {
                out.println(1);
                return;
            }

            // -------------------------------------------------------------------
            // Look for a “between” relationship among three distinct points
            // -------------------------------------------------------------------
            boolean betweenFound = false;
            for (int i = 0; i < points.length && !betweenFound; i++) {
                for (int j = 0; j < points.length; j++) {
                    if (i == j) continue;

                    if (points[i].x == points[j].x) {
                        betweenFound = isIntermediate(points, i, j, true);
                    } else if (points[i].y == points[j].y) {
                        betweenFound = isIntermediate(points, i, j, false);
                    }
                    if (betweenFound) break;
                }
            }

            out.println(betweenFound ? 2 : 3);
        }
    }
}

import java.io.*;
import java.util.*;

/**
 *  CF617D – Minimum number of axis‑aligned segments required to connect
 *  three given points.  The algorithm has been extracted into small,
 *  well‑named methods and the input handling is isolated in a dedicated
 *  {@link InputReader} class, making the program easier to read,
 *  test and maintain.
 */
public class Main {

    /** Simple immutable container for a point (x, y). */
    private static final class Point {
        final int x;
        final int y;

        Point(int x, int y) {
            this.x = x;
            this.y = y;
        }
    }

    /** Entry point of the program. */
    public static void main(String[] args) {
        InputReader reader = new InputReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        // read the three points
        Point p1 = new Point(reader.nextInt(), reader.nextInt());
        Point p2 = new Point(reader.nextInt(), reader.nextInt());
        Point p3 = new Point(reader.nextInt(), reader.nextInt());

        // compute and output the answer
        out.println(solve(p1, p2, p3));
        out.flush();
    }

    /** Returns 1, 2 or 3 – the minimal number of axis‑aligned segments needed. */
    private static int solve(Point a, Point b, Point c) {
        if (allXEqual(a, b, c) || allYEqual(a, b, c)) {
            return 1;                     // all three lie on a single vertical/horizontal line
        }
        if (canBeConnectedWithTwoSegments(a, b, c)) {
            return 2;                     // two segments are sufficient
        }
        return 3;                         // otherwise three segments are needed
    }

    /** Checks whether all three points share the same x‑coordinate. */
    private static boolean allXEqual(Point a, Point b, Point c) {
        return a.x == b.x && b.x == c.x;
    }

    /** Checks whether all three points share the same y‑coordinate. */
    private static boolean allYEqual(Point a, Point b, Point c) {
        return a.y == b.y && b.y == c.y;
    }

    /**
     * Determines whether the three points can be linked using exactly two
     * axis‑aligned segments.  This is possible if:
     * <ul>
     *   <li>Two points share an x‑coordinate and the third point’s y‑coordinate
     *       lies between the y‑coordinates of those two points, <b>or</b>
     *   <li>Two points share a y‑coordinate and the third point’s x‑coordinate
     *       lies between the x‑coordinates of those two points.
     * </ul>
     */
    private static boolean canBeConnectedWithTwoSegments(Point p1,
                                                          Point p2,
                                                          Point p3) {
        // check all six possible pairs
        if (shareX(p1, p2) && betweenY(p1.y, p2.y, p3.y)) return true;
        if (shareY(p1, p2) && betweenX(p1.x, p2.x, p3.x)) return true;

        if (shareX(p1, p3) && betweenY(p1.y, p3.y, p2.y)) return true;
        if (shareY(p1, p3) && betweenX(p1.x, p3.x, p2.x)) return true;

        if (shareX(p2, p3) && betweenY(p2.y, p3.y, p1.y)) return true;
        if (shareY(p2, p3) && betweenX(p2.x, p3.x, p1.x)) return true;

        return false;
    }

    /** Helper – do two points have the same x‑coordinate? */
    private static boolean shareX(Point a, Point b) {
        return a.x == b.x;
    }

    /** Helper – do two points have the same y‑coordinate? */
    private static boolean shareY(Point a, Point b) {
        return a.y == b.y;
    }

    /** Returns true if {@code v} lies in the closed interval [min, max]. */
    private static boolean between(int min, int max, int v) {
        return v >= min && v <= max;
    }

    /** Original fast scanner (unchanged from the supplied code). */
    private static class InputReader {
        private final InputStream stream;
        private final byte[] buf = new byte[1024];
        private int curChar, numChars;
        private final InputReader.SpaceCharFilter filter = new SpaceCharFilter() {
            public boolean isSpaceChar(int c) {
                return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
            }
        };

        InputReader(InputStream stream) {
            this.stream = stream;
        }

        private int read() {
            if (numChars == -1) throw new InputMismatchException();
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (numChars <= 0) return -1;
            }
            return buf[curChar++];
        }

        public int nextInt() {
            int c = read();
            while (isSpaceChar(c)) c = read();
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            int res = 0;
            do {
                if (c < '0' || c > '9') throw new InputMismatchException();
                res = res * 10 + (c - '0');
                c = read();
            } while (!isSpaceChar(c));
            return res * sign;
        }

        private boolean isSpaceChar(int c) {
            return filter != null ? filter.isSpaceChar(c) : isWhitespace(c);
        }

        private boolean isWhitespace(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }
    }
}

