        }
    }

    /** Reads a single integer from a line of the given BufferedReader. */
    private static int readInt(BufferedReader br) throws IOException {
        return Integer.parseInt(br.readLine().trim());
    }

    /**
     * Executes the core logic.
     *
     * @param x1 y1 coordinate of the first point
     * @param y1 y1 coordinate of the first point
     * @param x2 y2 coordinate of the second point
     * @param y2 y2 coordinate of the second point
     * @param x3 y3 coordinate of the third point
     * @param y3 y3 coordinate of the third point
     */
    private static void solve(int x1, int y1, int x2, int y2, int x3, int y3) {
        // Case 1 – all x or all y are identical
        if (allEqual(x1, x2, x3) || allEqual(y1, y2, y3)) {
            System.out.println(1);
            return;
        }

        // Case 2 – any of the complex conditions is satisfied
        if (isCase2(x1, y1, x2, y2, x3, y3)) {
            System.out.println(2);
            return;
        }

        // Case 3 – fallback
        System.out.println(3);
    }

    /** Helper that checks whether three integers are all equal. */
    private static boolean allEqual(int... vals) {
        return vals[0] == vals[1] && vals[1] == vals[2];
    }

    /**
     * Replicates the original “case 2” condition but in a readable way.
     *
     * The algorithm checks each pair of points that share either the same
     * X or Y coordinate and then evaluates the inner expression exactly as
     * the original code did.
     */
    private static boolean isCase2(int x1, int y1, int x2, int y2, int x3, int y3) {
        // pair (x1, y1) vs (x2, y2)
        if (x1 == x2 && (y1 == y3 || y2 == y3 || y3 < min(y1, y2) || y3 > max(y1, y2))) {
            return true;
        }
        if (y1 == y2 && (x1 == x3 || x2 == x3 || x3 < min(x1, x2) || x3 > max(x1, x2))) {
            return true;
        }

        // pair (x2, y2) vs (x3, y3)
        if (x2 == x3 && (y2 == y1 || y3 == y1 || y1 < min(y2, y3) || y1 > max(y2, y3))) {
            return true;
        }
        if (y2 == y3 && (x2 == x1 || x3 == x1 || x1 < min(x2, x3) || x1 > max(x2, x3))) {
            return true;
        }

        // pair (x1, y1) vs (x3, y3)
        if (x1 == x3 && (y1 == y2 || y3 == y2 || y2 < min(y1, y3) || y2 > max(y1, y3))) {
            return true;
        }
        if (y1 == y3 && (x1 == x2 || x3 == x2 || x2 < min(x1, x3) || x2 > max(x1, x3))) {
            return true;
        }

        return false;
    }
}

