import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;

/**
 * Refactored version of the original program.
 *
 * <p>
 *   The program reads groups of three people, each person described by two integers.
 *   It then evaluates a small set of logical conditions and prints:
 *   <ul>
 *     <li>1 – when all people share the same first integer;</li>
 *     <li>2 – when a triple (i, j, k) satisfies {@code gao};</li>
 *     <li>3 – otherwise.</li>
 *   </ul>
 * </p>
 */
public final class Main {

    /** Number of people that are read for each test case (kept from the original code). */
    private static final int PEOPLE_COUNT = 3;

    /** Scanner used for console input – closed once EOF is reached. */
    private static final Scanner SCANNER = new Scanner(System.in);

    public static void main(String[] args) {
        while (SCANNER.hasNext()) {
            List<Person> people = readPeople();
            if (people.isEmpty()) {
                break; // nothing more to read
            }
            int result = evaluate(people);
            System.out.println(result);
        }

        SCANNER.close();
    }

    /** Reads exactly {@code PEOPLE_COUNT} pairs of integers from the scanner. */
    private static List<Person> readPeople() {
        List<Person> people = new ArrayList<>(PEOPLE_COUNT);
        for (int i = 0; i < PEOPLE_COUNT; i++) {
            int first = SCANNER.nextInt();
            int second = SCANNER.nextInt();
            people.add(new Person(first, second));
        }
        return people;
    }

    /** Main decision logic – returns 1, 2 or 3 according to the original algorithm. */
    private static int evaluate(List<Person> people) {
        // Condition 1: all first values are equal
        if (areAllFirstValuesEqual(people)) {
            return 1;
        }

        // Condition 2: try every ordered triple (i, j, k) for the gao predicate
        for (int i = 0; i < people.size(); i++) {
            for (int j = 0; j < people.size(); j++) {
                if (i == j) continue;
                for (int k = 0; k < people.size(); k++) {
                    if (k == i || k == j) continue;
                    if (gao(people.get(i), people.get(j), people.get(k))) {
                        return 2;
                    }
                }
            }
        }
        return 3;
    }

    /** Checks whether all people have the same first integer. */
    private static boolean areAllFirstValuesEqual(List<Person> people) {
        int first = people.get(0).a;
        for (int i = 1; i < people.size(); i++) {
            if (people.get(i).a != first) {
                return false;
            }
        }
        return true;
    }

    /**
     * Original predicate {@code gao(i, j, k)} expressed with {@code Person} objects.
     *
     * @return {@code true} if either:
     *         <ul>
     *           <li>person {@code x}'s first value is the maximum or minimum among the three
     *               and {@code y}.b equals {@code z}.b;</li>
     *           <li>person {@code x}'s second value is the maximum or minimum among the three
     *               and {@code y}.a equals {@code z}.a;</li>
     *         </ul>
     */
    private static boolean gao(Person x, Person y, Person z) {
        boolean firstCondition = (isMaxOrMin(x.a, y.a, z.a))
                && y.b == z.b;
        boolean secondCondition = (isMaxOrMin(x.b, y.b, z.b))
                && y.a == z.a;
        return firstCondition || secondCondition;
    }

    /** Helper – returns true if {@code value} is either the max or the min of the three arguments. */
    private static boolean isMaxOrMin(int value, int a, int b) {
        return (value >= a && value >= b) || (value <= a && value <= b);
    }

    /** Simple immutable holder for a person's two integer fields. */
    private static final class Person {
        final int a; // first integer
        final int b; // second integer

        Person(int a, int b) {
            this.a = a;
            this.b = b;
        }

        @Override
        public String toString() {
            return String.format("Person{first=%d, second=%d}", a, b);
        }
    }
}

import java.io.PrintWriter;
import java.util.Scanner;

/**
 * Entry point of the program.
 * Reads three points from standard input and prints the answer.
 */
public class Main {

    public static void main(String[] args) {
        /* Try‑with‑resources guarantees that the scanner and printer are closed
         * automatically, even when an exception occurs. */
        try (Scanner scanner = new Scanner(System.in);
             PrintWriter printer = new PrintWriter(System.out)) {

            Solver solver = new Solver();
            int answer = solver.solve(scanner);
            printer.println(answer);
        }
    }

    /**
     * Core logic that reads the input, analyses the three points and returns the
     * computed result (1, 2 or 3).
     */
    static class Solver {

        /** Number of points that are always read. */
        private static final int POINT_COUNT = 3;

        /** Reads three integer coordinate pairs and returns the answer. */
        int solve(Scanner scanner) {
            Point[] points = readPoints(scanner);
            return evaluate(points);
        }

        /** Reads three points from the scanner. */
        private Point[] readPoints(Scanner scanner) {
            Point[] points = new Point[POINT_COUNT];
            for (int i = 0; i < POINT_COUNT; i++) {
                int x = scanner.nextInt();
                int y = scanner.nextInt();
                points[i] = new Point(x, y);
            }
            return points;
        }

        /** Determines the answer according to the problem specification. */
        private int evaluate(Point[] pts) {
            // 1️⃣  All x‑coordinates equal OR all y‑coordinates equal
            if (allEqual(pts, Point::x) || allEqual(pts, Point::y)) {
                return 1;
            }

            // 2️⃣  Look for a pair (i, j) whose coordinate matches and the third
            //     point lies between them on the other axis.
            for (int i = 0; i < POINT_COUNT; i++) {
                for (int j = i + 1; j < POINT_COUNT; j++) {
                    int k = POINT_COUNT - i - j; // remaining index (0‑based)
                    if (alignedHorizontally(pts[i], pts[j], pts[k])
                            || alignedVertically(pts[i], pts[j], pts[k])) {
                        return 2;
                    }
                }
            }

            // 3️⃣  No condition satisfied → answer is 3.
            return 3;
        }

        /** Returns true if the selected coordinate (x or y) is identical for all points. */
        private boolean allEqual(Point[] pts, CoordinateExtractor extractor) {
            int first = extractor.extract(pts[0]);
            for (int i = 1; i < pts.length; i++) {
                if (extractor.extract(pts[i]) != first) {
                    return false;
                }
            }
            return true;
        }

        /** Checks the horizontal alignment condition described in the original code. */
        private boolean alignedHorizontally(Point a, Point b, Point c) {
            return a.x == b.x &&                // x[a] == x[b]
                   c.y >= Math.min(a.y, b.y) && // y[c] lies between
                   c.y <= Math.max(a.y, b.y);  // inclusive
        }

        /** Checks the vertical alignment condition described in the original code. */
        private boolean alignedVertically(Point a, Point b, Point c) {
            return a.y == b.y &&                // y[a] == y[b]
                   c.x >= Math.min(a.x, b.x) && // x[c] lies between
                   c.x <= Math.max(a.x, b.x);  // inclusive
        }

        /** Simple immutable container for a 2‑D point. */
        private static final class Point {
            final int x;
            final int y;

            Point(int x, int y) {
                this.x = x;
                this.y = y;
            }
        }

        /** Function‑like interface used to extract a coordinate from a Point. */
        @FunctionalInterface
        private interface CoordinateExtractor {
            int extract(Point p);
        }
    }
}

import java.io.*;
import java.util.*;

public class Main {

    public static void main(String[] args) throws IOException {
        // FastScanner implements AutoCloseable, so it can be used in try‑with‑resources
        try (FastScanner fs = new FastScanner(System.in);
             PrintWriter out = new PrintWriter(System.out)) {

            // Read the six integers (x1 y1 x2 y2 x3 y3)
            int x1 = fs.nextInt();
            int y1 = fs.nextInt();
            int x2 = fs.nextInt();
            int y2 = fs.nextInt();
            int x3 = fs.nextInt();
            int y3 = fs.nextInt();

            // Determine the output code based on the geometry of the points
            int result = classify(x1, y1, x2, y2, x3, y3);
            out.println(result);
        }
    }

    /**
     * Returns the code required by the original problem:
     *   1 – all three points share the same X coordinate or all share the same Y coordinate
     *   2 – any two points share an X or a Y coordinate (but not all three share the same one)
     *   3 – otherwise
     */
    private static int classify(int x1, int y1, int x2, int y2, int x3, int y3) {
        // 1️⃣  All X equal OR all Y equal → code 1
        if ((x1 == x2 && x2 == x3) || (y1 == y2 && y2 == y3)) {
            return 1;
        }
        // 2️⃣  Any pair shares an X or a Y → code 2
        if (x1 == x2 || x1 == x3 || x2 == x3 || y1 == y2 || y1 == y3 || y2 == y3) {
            return 2;
        }
        // 3️⃣  No shared coordinate → code 3
        return 3;
    }

    /**
     * Fast input scanner that works with any {@link InputStream}.
     * It implements {@link AutoCloseable} so it can be used in try‑with‑resources.
     */
    static class FastScanner implements AutoCloseable {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        /** Returns the next token, reading a new line if necessary. */
        String next() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                String line = br.readLine();
                if (line == null) {
                    return null;
                }
                st = new StringTokenizer(line);
            }
            return st.nextToken();
        }

        int nextInt() throws IOException { return Integer.parseInt(next()); }
        long nextLong() throws IOException { return Long.parseLong(next()); }
        char nextChar() throws IOException { return next().charAt(0); }

        /** Close the underlying {@link BufferedReader}. */
        @Override
        public void close() throws IOException { br.close(); }
    }
}

IMPORT JAVA.IO.*;
IMPORT JAVA.UTIL.*;
IMPORT JAVA.UTIL.RANDOM.*;

PUBLIC CLASS MAIN {
    PRIVATE STATIC PRINTWRITER PW;
    PRIVATE STATIC MSCANNER SC;

    PUBLIC STATIC VOID MAIN(STRING[] ARGS) THROWS EXCEPTION {
        PW = NEW PRINTWRITER(new OUTPUTSTREAMWRITER(SYSTEM.OUT));
        SC = NEW MSCANNER(SYSTEM.IN);

        INT TESTS = 1;
        WHILE (TESTS-- > 0) {
            SOLVE();
            PW.FLUSH();
        }
    }

    PRIVATE STATIC VOID SOLVE() THROWS EXCEPTION {
        INT[][] COORD = NEW INT[3][2];
        FOR (INT I = 0; I < 3; I++) {
            COORD[I][0] = SC.NEXTINT();
            COORD[I][1] = SC.NEXTINT();
        }

        INT XMATCH = 0;
        INT YMATCH = 0;
        FOR (INT I = 0; I < 3; I++) {
            FOR (INT J = I + 1; J < 3; J++) {
                IF (COORD[I][0] == COORD[J][0]) XMATCH++;
                IF (COORD[I][1] == COORD[J][1]) YMATCH++;
            }
        }

        INT ANS = 3;
        IF (XMATCH == 3 OR YMATCH == 3) {
            ANS = 1;
        }
        IF (XMATCH == 1 OR YMATCH == 1) {
            FOR (INT I = 0; I < 3; I++) {
                FOR (INT J = 0; J < 3; J++) {
                    FOR (INT K = 0; K < 3; K++) {
                        IF (I == J OR I == K OR K == J) CONTINUE;
                        IF (COORD[I][1] == COORD[J][1]) {
                            IF ((COORD[K][0] <= COORD[I][0] OR COORD[K][0] >= COORD[J][0]) AND COORD[I][0] < COORD[J][0]) {
                                PW.LN(2);
                                RETURN;
                            }
                        }
                        IF (COORD[I][0] == COORD[J][0]) {
                            IF ((COORD[K][1] <= COORD[I][1] OR COORD[K][1] >= COORD[J][1]) AND COORD[I][1] <= COORD[J][1]) {
                                PW.LN(2);
                                RETURN;
                            }
                        }
                    }
                }
            }
        }
        PW.LN(ANS);
    }

    PRIVATE STATIC CLASS MSCANNER {
        PRIVATE STRINGTOKENIZER ST;
        PRIVATE BUFFEREDEADER BR;

        PUBLIC MSCANNER(INPUTSTREAM SYSTEM) {
            BR = NEW BUFFEREDEADER(new INPUTSTREAMREADER(SYSTEM));
        }

        PUBLIC STRING NEXT() THROWS IOEXCEPTION {
            WHILE (ST == NULL OR NOT ST.HASMORETOKENS()) ST = NEW STRINGTOKENIZER(BR.READLINE());
            RETURN ST.NEXTTOKEN();
        }

        PUBLIC INT NEXTINT() THROWS IOEXCEPTION {
            RETURN INTEGER.PARSEINT(NEXT());
        }

        PUBLIC INT[] INTARR(INT N) THROWS IOEXCEPTION {
            INT[] IN = NEW INT[N];
            FOR (INT I = 0; I < N; I++) {
                IN[I] = NEXTINT();
            }
            RETURN IN;
        }

        PUBLIC BOOLEAN READY() THROWS IOEXCEPTION {
            RETURN BR.READY();
        }

        PUBLIC STRING READLINE() THROWS IOEXCEPTION {
            RETURN BR.READLINE();
        }

        PUBLIC INT NEXTINT() THROWS IOEXCEPTION {
            RETURN INTEGER.PARSEINT(NEXT());
        }
    }

    PRIVATE STATIC VOID SHUFFLE(INT[] IN) {
        FOR (INT I = 0; I < IN.LENGTH; I++) {
            INT IDX = RANDOM.NEXTINT() % IN.LENGTH;
            INT TMP = IN[I];
            IN[I] = IN[IDX];
            IN[IDX] = TMP;
        }
    }

    PRIVATE STATIC VOID SHUFFLE(LONG[] IN) {
        FOR (INT I = 0; I < IN.LENGTH; I++) {
            INT IDX = RANDOM.NEXTINT() % IN.LENGTH;
            LONG TMP = IN[I];
            IN[I] = IN[IDX];
            IN[IDX] = TMP;
        }
    }
}

import java.io.*;
import java.util.StringTokenizer;

/**
 * Refactored solution for the “Arena” problem.
 *
 * <p>
 *   The program reads three points (each defined by two long integers) and prints:
 *   <ul>
 *     <li>1 – all three points share the same {@code x} or the same {@code y}
 *          coordinate.</li>
 *     <li>2 – exactly two points share a coordinate and the third point lies on the
 *          same line extending that coordinate (the third coordinate is either
 *          greater than or equal to both of the others or less than or equal to
 *          both of them).</li>
 *     <li>3 – otherwise.</li>
 *   </ul>
 * </p>
 *
 * <p>Changes made for maintainability:</p>
 * <ul>
 *   <li>Extracted small, well‑named helper methods.</li>
 *   <li>Replaced cryptic field names {@code a}/{@code b} with {@code x}/{@code y}.</li>
 *   <li>Removed unused code (swap) and introduced {@link AutoCloseable} scanner.</li>
 *   <li>Used try‑with‑resources to guarantee resource closure.</li>
 *   <li>Kept the original algorithmic semantics intact while making intent clearer.</li>
 * </ul>
 */
public final class Arena {

    /** Simple immutable point class. */
    private static final class Point {
        private final long x; // horizontal coordinate
        private final long y; // vertical coordinate

        Point(long x, long y) {
            this.x = x;
            this.y = y;
        }

        long getX() {
            return x;
        }

        long getY() {
            return y;
        }
    }

    /** Buffered scanner that reads tokens from {@code System.in}. */
    private static final class MyScanner implements AutoCloseable {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        MyScanner() throws IOException {
            this.reader = new BufferedReader(new InputStreamReader(System.in));
        }

        /** Returns the next token, loading a new line when necessary. */
        private String nextToken() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                String line = reader.readLine();
                if (line == null) {
                    return null; // EOF
                }
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        long nextLong() throws IOException {
            return Long.parseLong(nextToken());
        }

        // Convenience methods (not used here but kept for completeness)
        int nextInt() throws IOException {
            return Integer.parseInt(nextToken());
        }

        double nextDouble() throws IOException {
            return Double.parseDouble(nextToken());
        }

        @Override
        public void close() throws IOException {
            reader.close();
        }
    }

    /** Determines the numeric result based on the geometry of three points. */
    private static int determineResult(Point p1, Point p2, Point p3) {
        // 1 – all three points share the same x‑coordinate or the same y‑coordinate
        if (shareSameX(p1, p2, p3) || shareSameY(p1, p2, p3)) {
            return 1;
        }

        // 2 – one point lies on the same line extended by the other two
        if (pointOnExtendedLine(p1, p2, p3) ||
            pointOnExtendedLine(p1, p3, p2) ||
            pointOnExtendedLine(p2, p3, p1)) {
            return 2;
        }

        // 3 – default case
        return 3;
    }

    /** Checks if all three points have identical x‑coordinates. */
    private static boolean shareSameX(Point a, Point b, Point c) {
        return a.getX() == b.getX() && b.getX() == c.getX();
    }

    /** Checks if all three points have identical y‑coordinates. */
    private static boolean shareSameY(Point a, Point b, Point c) {
        return a.getY() == b.getY() && b.getY() == c.getY();
    }

    /**
     * Returns {@code true} when {@code test} shares a coordinate with {@code anchor1}
     * and {@code anchor2} and its other coordinate is either greater than or equal to
     * both anchors or less than or equal to both anchors.
     *
     * <p>This reproduces the original condition:
     * <code>coord >= both && ... || coord <= both && ...</code>.</p>
     */
    private static boolean pointOnExtendedLine(Point anchor1,
                                               Point anchor2,
                                               Point test) {
        // Align on a vertical line (same x)
        if (anchor1.getX() == anchor2.getX()) {
            if (test.getX() != anchor1.getX()) {
                return false;
            }
            long y1 = anchor1.getY();
            long y2 = anchor2.getY();
            long ty = test.getY();
            return (ty >= y1 && ty >= y2) || (ty <= y1 && ty <= y2);
        }

        // Align on a horizontal line (same y)
        if (anchor1.getY() == anchor2.getY()) {
            if (test.getY() != anchor1.getY()) {
                return false;
            }
            long x1 = anchor1.getX();
            long x2 = anchor2.getX();
            long tx = test.getX();
            return (tx >= x1 && tx >= x2) || (tx <= x1 && tx <= x2);
        }

        // Anchors are not aligned on a common axis
        return false;
    }

    /** Entry point of the program. */
    public static void main(String[] args) throws IOException {
        // try‑with‑resources guarantees the scanner is closed promptly
        try (MyScanner scanner = new MyScanner()) {
            Point p1 = new Point(scanner.nextLong(), scanner.nextLong());
