import java.io.PrintWriter;
import java.util.Scanner;

/**
 * Determines the output for three given points based on their coordinates.
 * The logic is extracted into small, well‑named methods to improve readability
 * and maintainability.
 */
public class Main {

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        PrintWriter out = new PrintWriter(System.out);
        try {
            int x1 = scanner.nextInt();
            int y1 = scanner.nextInt();
            int x2 = scanner.nextInt();
            int y2 = scanner.nextInt();
            int x3 = scanner.nextInt();
            int y3 = scanner.nextInt();

            int result = evaluate(x1, y1, x2, y2, x3, y3);
            out.println(result);
        } finally {
            out.flush();
        }
    }

    /**
     * Core decision logic.
     *
     * @return 1, 2 or 3 according to the original specification
     */
    private static int evaluate(int x1, int y1, int x2, int y2, int x3, int y3) {
        // All x coordinates equal or all y coordinates equal → output 1
        if (allEqual(x1, x2, x3) || allEqual(y1, y2, y3)) {
            return 1;
        }

        // Exactly one pair shares an x coordinate
        if (x1 == x2)   return handleSharedX(x1, y1, y2, y3);
        if (x1 == x3)   return handleSharedX(x1, y1, y3, y2);
        if (x2 == x3)   return handleSharedX(x2, y2, y3, y1);

        // Exactly one pair shares a y coordinate
        if (y1 == y2)   return handleSharedY(y1, x1, x2, x3);
        if (y1 == y3)   return handleSharedY(y1, x1, x3, x2);
        if (y2 == y3)   return handleSharedY(y2, x2, x3, x1);

        // No shared coordinate → output 3
        return 3;
    }

    /** Returns true if the three values are equal. */
    private static boolean allEqual(int a, int b, int c) {
        return a == b && b == c;
    }

    /** Handles the case where two points share the same x coordinate. */
    private static int handleSharedX(int sharedX, int yA, int yB, int yOther) {
        int minY = Math.min(yA, yB);
        int maxY = Math.max(yA, yB);
        return (yOther < minY || yOther > maxY) ? 2 : 3;
    }

    /** Handles the case where two points share the same y coordinate. */
    private static int handleSharedY(int sharedY, int xA, int xB, int xOther) {
        int minX = Math.min(xA, xB);
        int maxX = Math.max(xA, xB);
        return (xOther < minX || xOther > maxX) ? 2 : 3;
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.StringTokenizer;

public class ProblemD {

    public static void main(String[] args) {
        InputReader in = new InputReader();
        PrintWriter out = new PrintWriter(System.out);

        new ProblemD().solve(in, out);

        out.close();
    }

    public void solve(InputReader in, PrintWriter out) {
        int[] xs = new int[3];
        int[] ys = new int[3];

        for (int i = 0; i < 3; i++) {
            xs[i] = in.nextInt();
            ys[i] = in.nextInt();
        }

        if (allCoordinatesEqual(xs)) {
            out.println(1);
            return;
        }

        if (allCoordinatesEqual(ys)) {
            out.println(1);
            return;
        }

        for (int i = 0; i < 3; i++) {
            for (int j = i + 1; j < 3; j++) {
                if (isHorizontallyAligned(ys[i], ys[j])) {
                    int k = getRemainingIndex(i, j);
                    if (isBetween(xs[k], xs[i], xs[j])) {
                        out.println(3);
                        return;
                    } else {
                        out.println(2);
                        return;
                    }
                }

                if (isVerticallyAligned(xs[i], xs[j])) {
                    int k = getRemainingIndex(i, j);
                    if (isBetween(ys[k], ys[i], ys[j])) {
                        out.println(3);
                        return;
                    } else {
                        out.println(2);
                        return;
                    }
                }
            }
        }

        out.println(3);
    }

    private static boolean allCoordinatesEqual(int[] coords) {
        return coords[0] == coords[1] && coords[0] == coords[2];
    }

    private static boolean isHorizontallyAligned(int y1, int y2) {
        return y1 == y2;
    }

    private static boolean isVerticallyAligned(int x1, int x2) {
        return x1 == x2;
    }

    private static boolean isBetween(int value, int a, int b) {
        return (value > a && value < b) || (value < a && value > b);
    }

    private static int getRemainingIndex(int i, int j) {
        for (int k = 0; k < 3; k++) {
            if (k != i && k != j) {
                return k;
            }
        }
        return -1;
    }

    static class InputReader {
        public BufferedReader br;
        public StringTokenizer st;

        public InputReader() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        public String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        long nextLong() {
            return Long.parseLong(next());
        }

        double nextDouble() {
            return Double.parseDouble(next());
        }

        String nextLine() {
            String str = "";
            try {
                str = br.readLine();
            } catch (IOException e) {
                e.printStackTrace();
            }
            return str;
        }
    }
}

import java.io.BufferedReader;
import java.io.FileReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

/**
 * Solution for the "minimum number of vertical lines" problem.
 * <p>
 * The algorithm works as follows:
 * <ul>
 *   <li>If all three points lie on the same vertical line (same {@code x}) or on the same horizontal line (same {@code y}),
 *       only one line is needed – answer {@code 1}.</li>
 *   <li>Otherwise we check whether two of the points share a coordinate (either {@code x} or {@code y}) and the third point
 *       lies *outside* the interval formed by the other two points in the orthogonal direction.
 *       If such a configuration exists, two lines are sufficient – answer {@code 2}.</li>
 *   <li>If none of the above holds, three lines are required – answer {@code 3}.</li>
 * </ul>
 * <p>
 * The implementation is deliberately split into small, pure methods to make the flow easy to understand,
 * test, and extend.  All input handling is isolated in {@link InputReader} to keep the business logic
 * free from static fields and I/O concerns.
 */
public class TaskD {

    /** Simple immutable representation of a point in the plane. */
    private static final class Point {
        final int x;
        final int y;

        Point(int x, int y) {
            this.x = x;
            this.y = y;
        }

        @Override public String toString() {
            return "(" + x + ", " + y + ")";
        }
    }

    /** Reads six integers from the supplied {@link BufferedReader}. */
    private static final class InputReader {
        private final BufferedReader br;

        /** Creates a reader that reads from {@code System.in}. */
        InputReader() {
            this(new InputStreamReader(System.in));
        }

        /** Creates a reader that reads from a file (used only by tests). */
        InputReader(File file) throws IOException {
            this.br = new BufferedReader(new FileReader(file));
        }

        /** Consumes the next token and parses it as {@code int}. */
        int nextInt() {
            return Integer.parseInt(nextToken());
        }

        /** Returns the next token, blocking until one is available. */
        private String nextToken() {
            while (true) {
                try {
                    String line = br.readLine();
                    if (line == null) {
                        return null; // should never happen in a correct judge run
                    }
                    StringTokenizer st = new StringTokenizer(line);
                    if (st.hasMoreTokens()) {
                        return st.nextToken();
                    }
                } catch (IOException e) {
                    throw new UncheckedIOException(e);
                }
            }
        }
    }

    /** Calculates the minimum number of vertical lines required to cover the three given points. */
    private static int solve(Point a, Point b, Point c) {
        // 1️⃣  All three share the same x‑coordinate or the same y‑coordinate → only one line needed.
        if (a.x == b.x && b.x == c.x) return 1;
        if (a.y == b.y && b.y == c.y) return 1;

        // 2️⃣  Check every unordered pair for a matching coordinate.
        Point[] points = {a, b, c};
        for (int i = 0; i < points.length; i++) {
            for (int j = i + 1; j < points.length; j++) {
                Point p1 = points[i];
                Point p2 = points[j];
                Point p3 = points[i == 0 ? 2 : (i == 1 ? 0 : 1)]; // the remaining point

                // ── equal X values ────────────────────────────────────────
                if (p1.x == p2.x) {
                    if (p3.y < Math.min(p1.y, p2.y) || p3.y > Math.max(p1.y, p2.y)) {
                        return 2;
                    }
                }

                // ── equal Y values ────────────────────────────────────────
                if (p1.y == p2.y) {
                    if (p3.x < Math.min(p1.x, p2.x) || p3.x > Math.max(p1.x, p2.x)) {
                        return 2;
                    }
                }
            }
        }

        // 3️⃣  No configuration yields answer 1 or 2 → answer 3.
        return 3;
    }

    /** Entry point – parses input and prints the result. */
    public static void main(String[] args) throws IOException {
        InputReader reader = new InputReader();          // reads from stdin
        Point p1 = new Point(reader.nextInt(), reader.nextInt());
        Point p2 = new Point(reader.nextInt(), reader.nextInt());
        Point p3 = new Point(reader.nextInt(), reader.nextInt());

        int answer = solve(p1, p2, p3);
        System.out.println(answer);
    }
}

