/**
 * Refactored version of the original D617 program.
 *
 * <p>Reads six integers that represent the coordinates of three points
 * (x₁,y₁), (x₂,y₂), (x₃,y₃) and prints the number of distinct lines that can be
 * formed by these points (1, 2 or 3). The implementation is deliberately
 * organized for readability, testability and future extension.</p>
 */
public class D617 {

    /** Program entry point. */
    public static void main(String[] args) throws IOException {
        // Using a small wrapper class to encapsulate input parsing.
        try (InputReader reader = new InputReader()) {
            int x1 = reader.nextInt();
            int y1 = reader.nextInt();
            int x2 = reader.nextInt();
            int y2 = reader.nextInt();
            int x3 = reader.nextInt();
            int y3 = reader.nextInt();

            int result = countDistinctLines(x1, y1, x2, y2, x3, y3);
            System.out.println(result);
        }
    }

    /**
     * Determines how many distinct lines can be derived from the three supplied
     * points.
     *
     * <p>The method follows the same logical rules as the original code but
     * expresses them in a clearer, more maintainable way.</p>
     *
     * @param x1 y‑coordinate of the first point
     * @param y1 y‑coordinate of the first point
     * @param x2 y‑coordinate of the second point
     * @param y2 y‑coordinate of the second point
     * @param x3 y‑coordinate of the third point
     * @param y3 y‑coordinate of the third point
     * @return 1 if all points share the same x or y value, 2 if exactly two
     *         points share a coordinate and the third lies outside the range,
     *         otherwise 3.
     */
    private static int countDistinctLines(int x1, int y1,
                                            int x2, int y2,
                                            int x3, int y3) {
        // All x‑values identical → vertical line (or a single point)
        if (x1 == x2 && x2 == x3) {
            return 1;
        }
        // All y‑values identical → horizontal line (or a single point)
        if (y1 == y2 && y2 == y3) {
            return 1;
        }

        // Exactly two points share the same x‑value – check the third point's y.
        if (x1 == x2 && (y3 < Math.min(y1, y2) || y3 > Math.max(y1, y2))) {
            return 2;
        }
        if (x1 == x3 && (y2 < Math.min(y1, y3) || y2 > Math.max(y1, y3))) {
            return 2;
        }
        if (x2 == x3 && (y1 < Math.min(y2, y3) || y1 > Math.max(y2, y3))) {
            return 2;
        }

        // Exactly two points share the same y‑value – check the third point's x.
        if (y1 == y2 && (x3 < Math.min(x1, x2) || x3 > Math.max(x1, x2))) {
            return 2;
        }
        if (y1 == y3 && (x2 < Math.min(x1, x3) || x2 > Math.max(x1, x3))) {
            return 2;
        }
        if (y2 == y3 && (x1 < Math.min(x2, x3) || x1 > Math.max(x2, x3))) {
            return 2;
        }

        // No special case matched → three distinct lines.
        return 3;
    }

    /**
     * Simple fast input reader that skips whitespace and returns the next
     * integer from {@code System.in}.
     *
     * <p>Designed to be lightweight while preserving the original program's
     * speed characteristics.</p>
     */
    private static final class InputReader implements AutoCloseable {
        private final BufferedReader br;

        private InputReader() {
            this.br = new BufferedReader(new InputStreamReader(System.in));
        }

        /**
         * Reads the next token that represents an integer.
         *
         * @return the next integer value
         * @throws IOException if an I/O error occurs
         */
        int nextInt() throws IOException {
            // Skip any leading whitespace (including newlines)
            int ch;
            do {
                ch = br.read();
            } while (Character.isWhitespace(ch));

            // Build the number until a non‑digit character is encountered
            StringBuilder sb = new StringBuilder();
            sb.append((char) ch);
            while (true) {
                ch = br.read();
                if (ch == -1 || !Character.isDigit(ch)) {
                    break;
                }
                sb.append((char) ch);
            }
            return Integer.parseInt(sb.toString());
        }

        @Override
        public void close() throws IOException {
            br.close();
        }
    }
}

import java.util.Scanner;

/**
 * Main program – reads three points, analyses their mutual geometry and prints a numeric answer.
 *
 * <p>The refactor focuses on readability, encapsulation and separation of concerns:
 * <ul>
 *   <li>All geometry utilities are confined to {@link Geometry}}.
 *   <li>Naming follows Java conventions and constants are used where appropriate.
 *   <li>Static mutable fields have been removed – data are passed as method arguments.
 *   <li>Logic is split into small, well‑named methods, each doing one clear thing.
 * </ul>
 */
public class Main {

    /* --------------------------------------------------------------------- */
    /*  Geometry helper classes                                                */
    /* --------------------------------------------------------------------- */
    private static final class Geometry {

        /** Simple immutable point. */
        private static final class Point {
            final long x, y;

            Point(long x, long y) {
                this.x = x;
                this.y = y;
            }
        }

        /** Line defined by two points and the implicit equation ax + by + c = 0. */
        private static final class Line {
            final long a, b, c;   // coefficients of ax + by + c = 0
            final Point p, q;     // two distinct points on the line

            Line(Point p, Point q) {
                this.p = p;
                this.q = q;
                this.a = q.y - p.y;
                this.b = p.x - q.x;
                this.c = p.y * q.x - p.x * q.y;
            }

            /** Checks whether the given point lies on this line. */
            boolean contains(Point pt) {
                return a * pt.x + b * pt.y + c == 0;
            }

            /** Returns true if the direction vectors of the two lines are orthogonal. */
            boolean isPerpendicular(Line other) {
                long dx1 = p.x - q.x;
                long dy1 = p.y - q.y;
                long dx2 = other.p.x - other.q.x;
                long dy2 = other.p.y - other.q.y;
                return dx1 * dx2 + dy1 * dy2 == 0;
            }
        }

        /** Enum describing the axis we project onto. */
        private enum Axis { X, Y }

        /**
         * Determines whether a point lies outside (or exactly on the border of) the
         * open projection interval of a line on the specified axis.
         *
         * @param point  point to test
         * @param line   line whose projection is inspected
         * @param axis   axis of projection ({@code X} or {@code Y})
         * @return {@code true} if the coordinate is ≤ min or ≥ max of the projection
         */
        private static boolean isOutsideOrOnBoundary(Point point, Line line, Axis axis) {
            long min, max, coord;
            switch (axis) {
                case X -> {
                    min = Math.min(line.p.x, line.q.x);
                    max = Math.max(line.p.x, line.q.x);
                    coord = point.x;
                }
                case Y -> {
                    min = Math.min(line.p.y, line.q.y);
                    max = Math.max(line.p.y, line.q.y);
                    coord = point.y;
                }
                default -> throw new IllegalStateException();
            }
            // “inside” would be (min < coord && coord < max); we want the opposite.
            return !(min < coord && coord < max);
        }
    }

    /* --------------------------------------------------------------------- */
    /*  Core algorithm                                                       */
    /* --------------------------------------------------------------------- */
    private static int computeAnswer(
            Geometry.Line ab,
            Geometry.Line ac,
            Geometry.Line ox,
            Geometry.Line oy,
            Geometry.Point b,
            Geometry.Point c) {

        /* 1️⃣  Both AB and AC are perpendicular to the same axis → answer = 1 */
        if ((ab.isPerpendicular(ox) && ac.isPerpendicular(ox)) ||
            (ab.isPerpendicular(oy) && ac.isPerpendicular(oy))) {
            return 1;
        }

        /* 2️⃣  Scan the three sides looking for a line that is perpendicular
         *      to one axis and for which the appropriate third point is outside
         *      the line’s projection on that axis. If found → answer = 2.       */
        for (int i = 0; i < 3; i++) {
            Geometry.Line line = switch (i) {
                case 0 -> ab;
                case 1 -> ac;
                case 2 -> bc;
                default -> throw new IllegalStateException();
            };

            if (line.isPerpendicular(ox)) {                     // perpendicular to X‑axis
                if (Geometry.isOutsideOrOnBoundary(c, line, Geometry.Axis.Y)) {
                    return 2;
                }
                break;
            }
            if (line.isPerpendicular(oy)) {                     // perpendicular to Y‑axis
                if (Geometry.isOutsideOrOnBoundary(b, line, Geometry.Axis.X)) {
                    return 2;
                }
                break;
            }
        }

        /* 3️⃣  No condition matched → answer = 3 */
        return 3;
    }

    /* --------------------------------------------------------------------- */
    /*  Entry point                                                            */
    /* --------------------------------------------------------------------- */
    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            Geometry.Point a = new Geometry.Point(scanner.nextInt(), scanner.nextInt());
            Geometry.Point b = new Geometry.Point(scanner.nextInt(), scanner.nextInt());
            Geometry.Point c = new Geometry.Point(scanner.nextInt(), scanner.nextInt());

            Geometry.Line ab = new Geometry.Line(a, b);
            Geometry.Line ac = new Geometry.Line(a, c);
            Geometry.Line bc = new Geometry.Line(b, c);
            Geometry.Line ox = new Geometry.Line(new Geometry.Point(0, 0), new Geometry.Point(1, 0)); // X‑axis
            Geometry.Line oy = new Geometry.Line(new Geometry.Point(0, 0), new Geometry.Point(0, 1)); // Y‑axis

            int answer = computeAnswer(ab, ac, ox, oy, b, c);
            System.out.print(answer);
        }
    }
}

