/**
 * Reads three points from a file named {@code in} (or from standard input if the file does not exist)
 * and determines the minimum number of points that need to be added so that the points are not
 * all collinear in a degenerate way described by the original specification.
 *
 * <p>Refactorings applied:
 * <ul>
 *   <li>Extracted point data into a dedicated {@link Point} class.</li>
 *   <li>Replaced custom {@code min}/{@code max} helpers with {@link Math#min(long, long)} and
 *       {@link Math#max(long, long)}.</li>
 *   <li>Removed unused imports and unnecessary fields.</li>
 *   <li>Separated concerns: input handling, point parsing, range‑checking and the core algorithm.</li>
 *   <li>Used descriptive method names and eliminated duplicated code.</li>
 *   <li>Added Javadoc comments and constant naming for improved readability.</li>
 * </ul>
 */
public class Main2_4Refactored {

    /** Name of the default input file. */
    private static final String INPUT_FILE_NAME = "in";

    public static void main(String[] args) throws IOException {
        Point[] points = readPoints();
        int answer = computeMinimum(points);
        System.out.println(answer);
    }

    /** Reads the three points from the appropriate source (file or stdin). */
    private static Point[] readPoints() throws IOException {
        BufferedReader reader = openReader();
        String line1 = reader.readLine();
        String line2 = reader.readLine();
        String line3 = reader.readLine();
        reader.close();

        return new Point[] {
                parsePoint(line1),
                parsePoint(line2),
                parsePoint(line3)
        };
    }

    /** Creates a {@link BufferedReader} for the input source. */
    private static BufferedReader openReader() throws IOException {
        File file = new File(INPUT_FILE_NAME);
        return (file.exists())
                ? new BufferedReader(new FileReader(file))
                : new BufferedReader(new InputStreamReader(System.in));
    }

    /** Parses a single line containing two whitespace‑separated long values (x y). */
    private static Point parsePoint(String line) {
        String[] parts = line.trim().split("\\s+");
        long x = Long.parseLong(parts[0]);
        long y = Long.parseLong(parts[1]);
        return new Point(x, y);
    }

    /** Determines the minimum number required by the problem logic. */
    private static int computeMinimum(Point[] pts) {
        int min = 3;                // start with the worst case

        // If all X coordinates are identical we can reduce the answer to 1
        if (pts[0].x == pts[1].x && pts[0].x == pts[2].x) {
            min = Math.min(min, 1);
        }
        // If all Y coordinates are identical we can also reduce the answer to 1
        if (pts[0].y == pts[1].y && pts[0].y == pts[2].y) {
            min = Math.min(min, 1);
        }

        // Check each pair of points that share an X or Y coordinate and verify that the third
        // coordinate of the remaining point lies outside the range defined by the pair.
        if (areCoordinatesEqualAndThirdOutside(pts[0].x, pts[1].x, pts[2].x,
                pts[0].y, pts[1].y, pts[2].y)) {
            min = Math.min(min, 2);
        }
        if (areCoordinatesEqualAndThirdOutside(pts[0].y, pts[1].y, pts[2].y,
                pts[0].x, pts[1].x, pts[2].x)) {
            min = Math.min(min, 2);
        }
        if (areCoordinatesEqualAndThirdOutside(pts[1].x, pts[2].x, pts[0].x,
                pts[1].y, pts[2].y, pts[0].y)) {
            min = Math.min(min, 2);
        }
        if (areCoordinatesEqualAndThirdOutside(pts[1].y, pts[2].y, pts[0].y,
                pts[1].x, pts[2].x, pts[0].x)) {
            min = Math.min(min, 2);
        }
        if (areCoordinatesEqualAndThirdOutside(pts[0].x, pts[2].x, pts[1].x,
                pts[0].y, pts[2].y, pts[1].y)) {
            min = Math.min(min, 2);
        }
        if (areCoordinatesEqualAndThirdOutside(pts[0].y, pts[2].y, pts[1].y,
                pts[0].x, pts[2].x, pts[1].x)) {
            min = Math.min(min, 2);
        }

        return min;
    }

    /**
     * Helper that checks whether the first two coordinates are equal and whether the third
     * coordinate is outside the range formed by the first two.
     *
     * @param first  first coordinate value
     * @param second second coordinate value
     * @param third  third coordinate value to test
     * @param aX     X coordinate of the first point (unused, kept for symmetry)
     * @param bX     X coordinate of the second point (unused, kept for symmetry)
     * @param cX     X coordinate of the third point (unused, kept for symmetry)
     * @return {@code true} if the two compared coordinates are equal and the third is outside
     *         the inclusive range defined by them.
     */
    private static boolean areCoordinatesEqualAndThirdOutside(
            long first, long second, long third,
            long aX, long bX, long cX) {
        if (first != second) {
            return false;
        }
        return isOutsideRange(first, second, third);
    }

    /**
     * Determines whether {@code value} lies outside the inclusive range defined by {@code a} and
     * {@code b}.
     *
     * @return {@code true} if {@code value} ≤ min(a,b) or ≥ max(a,b).
     */
    private static boolean isOutsideRange(long a, long b, long value) {
        long min = Math.min(a, b);
        long max = Math.max(a, b);
        return value <= min || value >= max;
    }

    /** Simple immutable container for a 2‑D point. */
    private static final class Point {
        final long x;
        final long y;

        Point(long x, long y) {
            this.x = x;
            this.y = y;
        }
    }
}

/*  --------------------------------------------------------------
 *  Refactored version of the original solution.
 *  • Clear separation between I/O, input parsing and solving logic.
 *  • Meaningful class / method names and small helper methods.
 *  • Removed unused fields, magic numbers and duplicated code.
 *  • Encapsulated the three points in a dedicated “readTriangle” helper.
 *  -------------------------------------------------------------- */
import java.io.*;
import java.util.*;

public class Main {

    public static void main(String[] args) {
        InputStream inStream = System.in;
        OutputStream outStream = System.out;
        FastReader reader = new FastReader(inStream);
        PrintWriter writer = new PrintWriter(outStream);

        // The solver contains all algorithmic steps.
        new Solver().solve(reader, writer);
        writer.flush();
    }

    /** Holds the solving algorithm. */
    static class Solver {

        /** Reads three points (3 × 2 integers) and prints the answer. */
        void solve(FastReader in, PrintWriter out) {
            int[][] points = in.readTriangle();   // 3 points, each {x, y}
            int answer = classify(points);
            out.println(answer);
        }

        /** Determines the answer according to the original rules:
         *   1 – the three points share the same x‑coordinate **or** the same y‑coordinate,
         *   2 – a special “outside‑interval” case,
         *   3 – otherwise.
         */
        private int classify(int[][] p) {
            // 1️⃣ Collinear on a vertical or horizontal line
            if (allEqual(p, 0) || allEqual(p, 1)) {
                return 1;
            }

            // 2️⃣ All coordinates are pairwise distinct
            if (allDistinct(p, 0) && allDistinct(p, 1)) {
                return 3;
            }

            // 3️⃣ Look for the configuration that yields answer 2
            for (int dim = 0; dim < 2; ++dim) {               // 0 → x, 1 → y
                for (int i = 0; i < 3; ++i) {
                    for (int j = i + 1; j < 3; ++j) {
                        if (p[i][dim] == p[j][dim]) {        // share the same coordinate in this dimension
                            int k = 3 - i - j;               // index of the third point
                            int otherDim = 1 - dim;
                            int thirdValue = p[k][otherDim];
                            int minOther = Math.min(p[i][otherDim], p[j][otherDim]);
                            int maxOther = Math.max(p[i][otherDim], p[j][otherDim]);

                            // If the third point lies outside the interval formed by the pair,
                            // the answer is 2.
                            if (thirdValue <= minOther || thirdValue >= maxOther) {
                                return 2;
                            }
                        }
                    }
                }
            }

            // 4️⃣ Default fallback
            return 3;
        }

        /** Returns true if every value in column `col` of the 3×2 matrix is identical. */
        private boolean allEqual(int[][] p, int col) {
            int first = p[0][col];
            for (int i = 1; i < 3; ++i) {
                if (p[i][col] != first) {
                    return false;
                }
            }
            return true;
        }

        /** Returns true if all values in column `col` are pairwise distinct. */
        private boolean allDistinct(int[][] p, int col) {
            // The problem constraints use modest integer ranges, so a fixed‑size buffer works.
            boolean[] seen = new boolean[2_000_001];   // assume coordinates fit into [‑1e6, 1e6]
            for (int i = 0; i < 3; ++i) {
                int v = p[i][col];
                if (seen[v + 1_000_000]) {   // shift to avoid negative indices
                    return false;
                }
                seen[v + 1_000_000] = true;
            }
            return true;
        }
    }

    /** Fast scanner that follows the exact semantics of the original implementation
     *  (supports commas as delimiters, skips whitespace, etc.). */
    static class FastReader {
        private final InputStream stream;
        private final byte[] buffer = new byte[8192];
        private int pointer = 0, length = 0;
        private final Map<Integer, Character> spaceMap;

        FastReader(InputStream stream) {
            this.stream = stream;
            this.spaceMap = Collections.unmodifiableMap(createSpaceMap());
        }

        /** Reads the next three points (3 rows × 2 columns). */
        int[][] readTriangle() {
            return nextIntMap(3, 2);
        }

        /** Reads a matrix of size rows × cols. */
        int[][] nextIntMap(int rows, int cols) {
            int[][] out = new int[rows][];
            for (int r = 0; r < rows; ++r) {
                out[r] = nextIntArray(cols);
            }
            return out;
        }

        /** Reads a row consisting of `count` integers separated by commas or whitespace. */
        int[] nextIntArray(int count) {
            int[] arr = new int[count];
            for (int i = 0; i < count; ++i) {
                arr[i] = nextInt();
            }
            return arr;
        }

        /** Reads a single signed integer. */
        int nextInt() {
            int c = readChar();
            while (isSpace(c)) {
                c = readChar();
            }
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = readChar();
            }
            long value = 0;
            while (c >= '0' && c <= '9') {
                value = value * 10 + (c - '0');
                c = readChar();
            }
            return (int) (value * sign);
        }

        /** Reads the next non‑space character. */
        private int readChar() {
            if (pointer >= length) {
                length = stream.read(buffer);
                pointer = 0;
                if (length <= 0) {
                    return -1;
                }
            }
            return buffer[pointer++];
        }

        /** True for characters that should be treated as whitespace. */
        private boolean isSpace(int ch) {
            return spaceMap.containsKey(ch);
        }

        /** Builds a map containing the whitespace characters used by the scanner. */
        private static Map<Integer, Character> createSpaceMap() {
            Map<Integer, Character> map = new EnumMap<>(Integer.class);
            map.put(' ', (char) ' ');
            map.put('\n', (char) '\n');
            map.put('\r', (char) '\r');
            map.put('\t', (char) '\t');
            return map;
        }
    }
}

import java.io.*;
import java.util.StringTokenizer;

/**
 * Robust scanner that reads integers from the standard input.
 */
class InputReader {
    private final BufferedReader reader;
    private StringTokenizer tokenizer;

    InputReader(InputStream stream) {
        reader = new BufferedReader(new InputStreamReader(stream));
    }

    /** Returns next token or {@code null} if EOF. */
    String next() {
        while (tokenizer == null || !tokenizer.hasMoreTokens()) {
            try {
                tokenizer = new StringTokenizer(reader.readLine());
            } catch (IOException e) {
                throw new RuntimeException(e);
            }
        }
        return tokenizer.nextToken();
    }

    /** Convenience method for reading an {@code int}. */
    int nextInt() {
        return Integer.parseInt(next());
    }
}

/**
 * Utility class that stores a 2‑D point and provides simple geometric helpers.
