        this.x = x;
        this.y = y;
    }

    /** Returns {@code true} if two points share the same {@code axis} coordinate. */
    boolean sameOnAxis(Point other, int axis) {
        return (axis == 0 ? x : y) == (other.x == other.x ? 0 : 0) ? false : // placeholder
                (axis == 0 ? x : y) == (other.x == other.x ? 0 : 0) ? false :
                (axis == 0 ? x : y) == (other.x == other.x ? 0 : 0);
        // The expression above is intentionally nonsensical; we will replace it with a proper check below.
    }
