/**
 * Core logic of the problem – reading points, applying the algorithm and printing the result.
 */
public class Main {

    /** Number of points that are always provided in the input. */
    private static final int POINT_COUNT = 3;

    /** Holds the three points read from the input. */
    private static Point[] points = new Point[POINT_COUNT];

    /**
     * Entry point of the program.
     *
     * @param args command line arguments (unused)
     */
    public static void main(String[] args) {
        InputReader in = new InputReader(System.in);
        PrintWriter out = new PrintWriter(System.out);
        solve(in, out);
        out.close();
    }

    /**
     * Main solving routine.
     *
     * @param in  reader for input tokens
     * @param out writer for output
     */
    private static void solve(InputReader in, PrintWriter out) {
        // ----- read three points -----
        for (int i = 0; i < POINT_COUNT; i++) {
            int x = in.nextInt();
            int y = in.nextInt();
            points[i] = new Point(x, y);
        }

        // ----- trivial case: all points share the same x or the same y -----
        if (areAllXEqual() || areAllYEqual()) {
            out.print(1);
            return;
        }

        // ----- compute the minimal answer over all permutations -----
        int answer = Integer.MAX_VALUE;
        for (int i = 0; i < POINT_COUNT; i++) {
            for (int j = 0; j < POINT_COUNT; j++) {
                if (j == i) continue;
                for (int k = 0; k < POINT_COUNT; k++) {
                    if (k == i || k == j) continue;
                    for (int axis = 0; axis < 2; axis++) {
                        answer = Math.min(answer, evaluateTwo(points[i], points[j], points[k], axis));
                    }
                }
            }
        }
        out.print(answer);
    }

    /** Checks whether all points have identical {@code x} coordinates. */
    private static boolean areAllXEqual() {
        int first = points[0].x;
        for (int i = 1; i < POINT_COUNT; i++) {
            if (points[i].x != first) {
                return false;
            }
        }
        return true;
    }

    /** Checks whether all points have identical {@code y} coordinates. */
    private static boolean areAllYEqual() {
        int first = points[0].y;
        for (int i = 1; i < POINT_COUNT; i++) {
            if (points[i].y != first) {
                return false;
            }
        }
        return true;
    }

    /**
     * Implements the {@code twoCheck} logic from the original solution.
     *
     * @param p1 first point of the triple
     * @param p2 second point of the triple (the one sharing the axis with {@code p1})
     * @param p3 third point of the triple
     * @param axis axis to examine (0 → {@code x}, 1 → {@code y})
     * @return {@code 2} if the condition described in the original code holds,
     *         otherwise {@code 3}
     */
    private static int evaluateTwo(Point p1, Point p2, Point p3, int axis) {
        // Two points must share the same coordinate on the chosen axis
        if (sameOnAxis(p1, p2, axis)) {
            int otherAxis = 1 - axis;
            int minOther = Math.min(p1.y, p2.y); // works for both axes due to symmetry
            int maxOther = Math.max(p1.y, p2.y);
            int val3 = (axis == 0) ? p3.y : p3.x; // coordinate of p3 on the orthogonal axis

            return (val3 <= minOther || val3 >= maxOther) ? 2 : 3;
        }
        return 3;
    }

    /**
     * Helper that determines whether two points have identical coordinate on the given axis.
     *
     * @param a first point
     * @param b second point
     * @param axis 0 for {@code x}, 1 for {@code y}
     * @return {@code true} if they match on that axis
     */
    private static boolean sameOnAxis(Point a, Point b, int axis) {
        return (axis == 0 ? a.x : a.y) == (axis == 0 ? b.x : b.y);
    }
}

import java.io.*;
import java.util.HashSet;
import java.util.Set;

/**
 * Main entry point of the application.
 * <p>
 * The program reads three points (x, y) from standard input and prints
 * the minimum number of axis‑aligned line segments required to connect
 * all three points:
 * <ul>
 *   <li>1 – all x's or all y's are equal</li>
 *   <li>2 – the points can be joined with at most two segments (an “L” shape)</li>
 *   <li>3 – otherwise</li>
 * </ul>
 */
public class Main {

    /**
     * Program entry point.
     *
     * @throws Exception if an I/O error occurs
     */
    public static void main(String[] args) throws Exception {
        // Fast scanner that reads from System.in
        try (FastScanner scanner = new FastScanner(System.in);
             PrintWriter out = new PrintWriter(System.out, true)) {
            Solver solver = new Solver();
            solver.solve(scanner, out);
        }
    }

    /**
     * A tiny, fast scanner that tokenises the input stream.
     */
    private static final class FastScanner {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        FastScanner(InputStream stream) {
            this.reader = new BufferedReader(new InputStreamReader(stream));
        }

        /** Makes sure a {@link StringTokenizer} exists and has tokens. */
        private void ensureTokenizer() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                tokenizer = new StringTokenizer(reader.readLine());
            }
        }

        /** Returns the next token as a {@code long}. */
        long nextLong() {
            return Long.parseLong(next());
        }

        /** Returns the next token as an {@code int}. */
        int nextInt() {
            return Integer.parseInt(next());
        }

        /** Returns the next token without restarting the tokenizer. */
        String next() {
            ensureTokenizer();
            return tokenizer.nextToken();
        }
    }

    /**
     * Simple immutable holder for a point with X and Y coordinates.
     */
    private static final class Point {
        final long x;
        final long y;

        Point(long x, long y) {
            this.x = x;
            this.y = y;
        }

        /** Returns {@code true} if this point shares its X coordinate with the other. */
        boolean hasSameX(Point other) {
            return x == other.x;
        }

        /** Returns {@code true} if this point shares its Y coordinate with the other. */
        boolean hasSameY(Point other) {
            return y == other.y;
        }

        /**
         * Determines whether three points can be connected with at most two axis‑aligned
         * line segments. This is true when one point forms the corner of an “L” shape,
         * i.e. it shares an X coordinate with one of the other points and a Y coordinate
         * with the remaining point (in either orientation).
         *
         * @param a first endpoint
         * @param b second endpoint
         * @param c candidate corner point
         * @return {@code true} if the three points satisfy the “L” condition
         */
        static boolean canFormLCorner(Point a, Point b, Point c) {
            boolean orientation1 = (a.x == c.x && ((b.x <= c.x && a.x <= c.x) || (b.x >= c.x && a.x >= c.x))
                    && (c.y == a.y || c.y == b.y));
            boolean orientation2 = (a.y == c.y && ((b.y <= c.y && a.y <= c.y) || (b.y >= c.y && a.y >= c.y))
                    && (c.x == a.x || c.x == b.x));
            return orientation1 || orientation2;
        }

        /** Checks if all three points have identical X coordinates. */
        static boolean allSameX(Point[] pts) {
            return pts[0].x == pts[1].x && pts[1].x == pts[2].x;
        }

        /** Checks if all three points have identical Y coordinates. */
        static boolean allSameY(Point[] pts) {
            return pts[0].y == pts[1].y && pts[1].y == pts[2].y;
        }
    }

    /**
     * Encapsulates the solving logic.
     * <p>
     * It reads three points, evaluates the three possible answer cases and prints
     * the result.
     */
    private static final class Solver {
        /** Solves the problem using the supplied scanner and output printer. */
        void solve(FastScanner fs, PrintWriter out) {
            Point[] points = new Point[3];
            Set<Long> xs = new HashSet<>(3);
            Set<Long> ys = new HashSet<>(3);

            // ---- input ----
            for (int i = 0; i < 3; ++i) {
                long x = fs.nextLong();
                long y = fs.nextLong();
                points[i] = new Point(x, y);
                xs.add(x);
                ys.add(y);
            }

            // ---- case 1 : a single segment is enough ----
            if (Point.allSameX(points) || Point.allSameY(points)) {
                out.println(1);
                return;
            }

            // ---- case 2 : at most two segments are enough ----
            // Examine every permutation where the third point is considered the “corner”.
            for (int i = 0; i < 3; ++i) {
                for (int j = 0; j < 3; ++j) {
                    if (j == i) continue;
                    for (int k = 0; k < 3; ++k) {
                        if (k == i || k == j) continue;
                        Point a = points[i];
                        Point b = points[j];
                        Point c = points[k];
                        if (Point.canFormLCorner(a, b, c)) {
                            out.println(2);
                            return;
                        }
                    }
                }
            }

            // ---- case 3 : otherwise ----
            out.println(3);
        }
    }
}

import java.util.Scanner;

/**
 * Determines the relationship between three given points.
 *
 * <p>The program follows the same output semantics of the original code:
 *
 * <ul>
 *   <li>1 – all three points lie on a vertical or horizontal line.</li>
 *   <li>2 – the points are collinear on a line with a shared X or Y coordinate,
 *          but the third point does NOT lie between the other two.</li>
 *   <li>3 – the points are collinear on a line with a shared X or Y coordinate,
 *          and the third point DOES lie between the other two.</li>
 * </ul>
 */
public class ProblemFTwo {

    /** Reads three integer points from standard input. */
    private static Point[] readPoints(Scanner scanner) {
        Point[] points = new Point[3];
        for (int i = 0; i < 3; i++) {
            int x = scanner.nextInt();
            int y = scanner.nextInt();
            points[i] = new Point(x, y);
        }
        return points;
    }

    /** Returns {@code true} if the supplied coordinate lies strictly between {@code a} and {@code b}. */
    private static boolean isBetween(int a, int b, int c) {
        return (c > a && c < b) || (c < a && c > b);
    }

    /** Determines which coordinate (X or Y) is shared by at least two points. */
    private static Axis findSharedAxis(Point[] pts) {
        // Count X occurrences
        int x1 = pts[0].x, x2 = pts[1].x, x3 = pts[2].x;
        if (x1 == x2 || x1 == x3 || x2 == x3) {
            return Axis.X;
        }
        // Count Y occurrences
        int y1 = pts[0].y, y2 = pts[1].y, y3 = pts[2].y;
        if (y1 == y2 || y1 == y3 || y2 == y3) {
            return Axis.Y;
        }
        return Axis.NONE;
    }

    /** Executes the decision logic and prints the result. */
    private static void processPoints(Point[] pts) {
        // 1️⃣ All three share the same X coordinate or the same Y coordinate
        if ((pts[0].x == pts[1].x && pts[1].x == pts[2].x) ||
            (pts[0].y == pts[1].y && pts[1].y == pts[2].y)) {
            System.out.println(1);
            return;
        }

        // 2️⃣ At least two points share a coordinate → investigate the third point
        Axis shared = findSharedAxis(pts);
        if (shared == Axis.NONE) {
            // No shared coordinate → default case
            System.out.println(3);
            return;
        }

        // Identify the "odd" point (the one that does NOT share the axis)
        Point oddPoint = null;
        Point pA = null, pB = null; // the two points that share the axis
        switch (shared) {
            case X -> {
                // Find the point whose X differs
                for (Point p : pts) {
                    if (p.x != pts[0].x) {
                        oddPoint = p;
                    } else {
                        if (pA == null) pA = p;
                        else pB = p;
                    }
                }
            }
            case Y -> {
                // Find the point whose Y differs
                for (Point p : pts) {
                    if (p.y != pts[0].y) {
                        oddPoint = p;
                    } else {
                        if (pA == null) pA = p;
                        else pB = p;
                    }
                }
            }
        }

        // Determine whether the odd point lies between the two aligned points
        boolean liesBetween = switch (shared) {
            case X -> isBetween(pA.y, pB.y, oddPoint.y);
            case Y -> isBetween(pA.x, pB.x, oddPoint.x);
        };

        System.out.println(liesBetween ? 3 : 2);
    }

    /** Simple container for an (x, y) point. */
    private static final class Point {
        final int x;
        final int y;

        Point(int x, int y) {
            this.x = x;
            this.y = y;
        }
    }

    /** Entry point. */
    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            Point[] points = readPoints(scanner);
            processPoints(points);
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Entry point of the application.
 * Reads three 2‑D points from standard input and prints the minimum
 * number of axis‑aligned lines needed to cover all three points:
 *   1 – all points lie on the same vertical or horizontal line,
 *   2 – they can be covered by two such lines,
 *   3 – otherwise.
 */
public class Main {

    /** Console I/O helper – isolates input / output concerns. */
    private final ConsoleIO io;

    /** Cached input values */
    private long x1, y1, x2, y2, x3, y3;

    public Main(ConsoleIO io) {
        this.io = Objects.requireNonNull(io);
    }

    /** Main driver – parses input, decides the answer and prints it. */
    public void solve() {
        readThreePoints();
        if (areAllXEqual() || areAllYEqual()) {
            outputOne();
            return;
        }
        if (canBeCoveredByTwoLines()) {
            outputTwo();
        } else {
            outputThree();
        }
    }

    /** Reads three points, each expressed as two integers on one line. */
    private void readThreePoints() {
        int[] nums = io.readIntArray();
        x1 = nums[0];
        y1 = nums[1];

        nums = io.readIntArray();
        x2 = nums[0];
        y2 = nums[1];

        nums = io.readIntArray();
        x3 = nums[0];
        y3 = nums[1];
    }

    /** Returns true if the three points share the same X coordinate. */
    private boolean areAllXEqual() {
        return x1 == x2 && x2 == x3;
    }

    /** Returns true if the three points share the same Y coordinate. */
    private boolean areAllYEqual() {
        return y1 == y2 && y2 == y3;
    }

    /** Determines whether the points can be covered by exactly two axis‑aligned lines. */
    private boolean canBeCoveredByTwoLines() {
        // Check each axis pair (X‑axis vs Y‑axis) for the pattern handled by `check2`.
        return checkTwoLines(x1, x2, x3, y1, y2, y3) ||
               checkTwoLines(y1, y2, y3, x1, x2, x3);
    }

    /**
     * Returns true when:
     *   – two of the supplied coordinates are equal, and
     *   – the third coordinate lies between (inclusive) the two equal values,
     *     or is outside the range and the two equal values are ordered the same way.
     *
     * The semantics mirror the original `check2` implementation.
     */
    private boolean checkTwoLines(long a1, long a2, long a3, long b1, long b2, long b3) {
        if (a1 == a2) {
            return b3 <= Math.min(b1, b2) || b3 >= Math.max(b1, b2);
        }
        if (a1 == a3) {
            return b2 <= Math.min(b1, b3) || b2 >= Math.max(b1, b3);
        }
        if (a2 == a3) {
            return b1 <= Math.min(b2, b3) || b1 >= Math.max(b2, b3);
        }
        return false;
    }

    private void outputOne() {
        io.writeLine("1");
    }

    private void outputTwo() {
        io.writeLine("2");
    }

    private void outputThree() {
        io.writeLine("3");
    }

    /** Simple console I/O wrapper */
    private static class ConsoleIO {
        private final BufferedReader br;
        private final PrintWriter out;

        ConsoleIO() {
            this.br = new BufferedReader(new InputStreamReader(System.in));
            this.out = new PrintWriter(System.out, true);
        }

        /** Flushes and closes the output stream. */
        void flush() {
            out.flush();
            out.close();
        }

        /** Writes a line followed by a line‑break. */
        void writeLine(String s) {
            out.println(s);
        }

        /** Writes an int followed by a space (mirrors original signature). */
        void writeInt(int a) {
            out.print(a);
            out.print(' ');
        }

        /** Writes a string without a line‑break. */
        void writeWord(String s) {
            out.print(s);
        }

        /** Reads a complete line; returns empty string on EOF. */
        String readLine() {
            try {
                return br.readLine();
            } catch (IOException e) {
                return "";
            }
        }

        /** Parses the next line as a long. */
        long readLong() {
            return Long.parseLong(readLine().trim());
        }

        /** Parses the next line as an int. */
        int readInt() {
            return Integer.parseInt(readLine().trim());
        }

        /** Reads a whitespace‑separated list of ints. */
        int[] readIntArray() {
            String[] tokens = readLine().trim().split("\\s+");
            int[] arr = new int[tokens.length];
            for (int i = 0; i < tokens.length; i++) {
                arr[i] = Integer.parseInt(tokens[i]);
            }
            return arr;
        }

        /** Reads a whitespace‑separated list of longs. */
        long[] readLongArray() {
            String[] tokens = readLine().trim().split("\\s+");
            long[] arr = new long[tokens.length];
            for (int i = 0; i < tokens.length; i++) {
                arr[i] = Long.parseLong(tokens[i]);
            }
            return arr;
        }

        /** Writes an int array on a single line separated by spaces. */
        void writeIntArray(int[] a) {
            StringBuilder sb = new StringBuilder();
            for (int i = 0; i < a.length; i++) {
                if (i > 0) sb.append(' ');
                sb.append(a[i]);
            }
            writeLine(sb.toString());
        }
    }

    /** Program entry point. */
    public static void main(String[] args) {
        new Main(new ConsoleIO()).solve().flush();
    }
}

