/**
 * Encapsulates all solution logic.
 * Keeps the algorithm separate from I/O handling for easier testing and reuse.
 */
final class Solver {

    private static final int POINT_COUNT = 3;
    private final Point[] points = new Point[POINT_COUNT];

    /** Reads the three points, applies the algorithm and prints the answer. */
    public void run(Scanner sc, PrintWriter out) {
        readPoints(sc);
        if (allXEqual()) {
            out.println(1);
        } else if (anyJudgeTrue()) {
            out.println(2);
        } else {
            out.println(3);
        }
    }

    /** Reads three (x, y) pairs from the scanner. */
    private void readPoints(Scanner sc) {
        for (int i = 0; i < POINT_COUNT; i++) {
            int x = sc.nextInt();
            int y = sc.nextInt();
            points[i] = new Point(x, y);
        }
    }

    /** Returns true if all points share the same X coordinate. */
    private boolean allXEqual() {
        return points[0].x == points[1].x && points[1].x == points[2].x;
    }

    /** Returns true if there exists a pair of points that share a coordinate
     *  and the third point lies outside the interval defined by that coordinate. */
    private boolean anyJudgeTrue() {
        for (int i = 0; i < POINT_COUNT; i++) {
            for (int j = 0; j < POINT_COUNT; j++) {
                if (i == j) continue;
                for (int k = 0; k < POINT_COUNT; k++) {
                    if (k == i || k == j) continue;
                    if (judge(points[i], points[j], points[k])) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    /**
     * Mirrors the original {@code judge} method.
     *
     * @return {@code true} if {@code a} and {@code b} share either X or Y,
     *         and {@code c} lies outside the interval they define on that axis.
     */
    private boolean judge(Point a, Point b, Point c) {
        if (a.x == b.x) {
            int minY = Math.min(a.y, b.y);
            int maxY = Math.max(a.y, b.y);
            return c.y < minY || c.y > maxY;
        }
        if (a.y == b.y) {
            int minX = Math.min(a.x, b.x);
            int maxX = Math.max(a.x, b.x);
            return c.x < minX || c.x > maxX;
        }
        return false;
    }
}

/**
 * Simple immutable point class that supports natural ordering.
 * Used by {@link Solver} for clarity and future extensibility.
 */
final class Point implements Comparable<Point> {
    final int x;
    final int y;

    Point(int x, int y) {
        this.x = x;
        this.y = y;
    }

    @Override
    public int compareTo(Point o) {
        int cmp = Integer.compare(this.x, o.x);
        return (cmp != 0) ? cmp : Integer.compare(this.y, o.y);
    }

    @Override
    public boolean equals(Object o) {
        if (this == o) return true;
        if (!(o instanceof Point)) return false;
        Point p = (Point) o;
        return x == p.x && y == p.y;
    }

    @Override
    public int hashCode() {
        return 31 * x + y;
    }
}

/**
 * Refactored version of the original {@code Polyline} program.
 *
 * <p>This refactor improves maintainability by:
 * <ul>
 *   <li>Separating input handling from business logic.</li>
 *   <li>Extracting repeated calculations into small, well‑named methods.</li>
 *   <li>Using descriptive identifiers and a dedicated {@code Point} record.</li>
 *   <li>Encapsulating the decision‑making process in a pure function.</li>
 *   <li>Adding Javadoc comments and consistent formatting.</li>
 * </ul>
 *
 * <p>The program reads six integers from {@code stdin} representing three 2‑D points
 * (x, y, x₂, y₂, x₃, y₃) and prints an integer code that describes the geometric
 * relationship of the three points.</p>
 */
public final class Polyline {

    /** Private constructor – utility class. */
    private Polyline() { }

    /** Entry point. */
    public static void main(String[] args) {
        Point p1 = readPoint(1);
        Point p2 = readPoint(2);
        Point p3 = readPoint(3);

        int result = classify(p1, p2, p3);
        System.out.println(result);
    }

    /** Reads the next two integers from {@code Scanner} and creates a {@code Point}. */
    private static Point readPoint(int index) {
        Scanner scanner = new Scanner(System.in);
        int x = scanner.nextInt();
        int y = scanner.nextInt();
        scanner.close();               // No further use of the scanner – close now.
        return new Point(x, y, index);
    }

    /**
     * Determines the relationship among three points.
     *
     * @return an integer code:
     * <ul>
     *   <li>{@code 1} – all x coordinates are equal (vertical line) or all y coordinates are equal (horizontal line).</li>
     *   <li>{@code 2} – points are collinear on a non‑axis‑aligned line, but the third point does not lie between the other two on the shared axis.</li>
     *   <li>{@code 3} – the third point lies strictly between the other two on the shared axis.</li>
     * </ul>
     */
    private static int classify(Point a, Point b, Point c) {
        // 1️⃣  All x equal → vertical line
        if (a.x == b.x && a.x == c.x) {
            return 1;
        }

        // 2️⃣  All y equal → horizontal line
        if (a.y == b.y && a.y == c.y) {
            return 1;
        }

        // Helper that checks whether {@code middle} lies strictly between {@code first} and {@code second}.
        java.util.function.BiPredicate<Integer, Integer> isBetween = (mid, first, second) -> {
            int min = Math.min(first, second);
            int max = Math.max(first, second);
            return mid > min && mid < max;
        };

        // Points share the same X coordinate (a.x == b.x) → check vertical alignment
        if (a.x == b.x) {
            return isBetween.test(c.y, a.y, b.y) ? 3 : 2;
        }
        // Points share the same X coordinate (a.x == c.x) → check vertical alignment
        if (a.x == c.x) {
            return isBetween.test(b.y, a.y, c.y) ? 3 : 2;
        }
        // Points share the same X coordinate (b.x == c.x) → check vertical alignment
        if (b.x == c.x) {
            return isBetween.test(a.y, b.y, c.y) ? 3 : 2;
        }

        // Points share the same Y coordinate (a.y == b.y) → check horizontal alignment
        if (a.y == b.y) {
            return isBetween.test(c.x, a.x, b.x) ? 3 : 2;
        }
        // Points share the same Y coordinate (a.y == c.y) → check horizontal alignment
        if (a.y == c.y) {
            return isBetween.test(b.x, a.x, c.x) ? 3 : 2;
        }
        // Points share the same Y coordinate (b.y == c.y) → check horizontal alignment
        if (b.y == c.y) {
            return isBetween.test(a.x, b.x, c.x) ? 3 : 2;
        }

        // No axis alignment → assume generic collinear case (ans = 3)
        return 3;
    }

    /** Simple immutable data holder for a 2‑D point with an identifier for debugging. */
    private record Point(int x, int y, int id) { }
}

import java.io.*;
import java.util.Arrays;
import java.util.Comparator;

/**
 * Entry point of the program.
 *
 * <p>Reads three points, computes two intermediate costs and prints the smaller one.
 * The algorithm is the same as the original version, but the code has been
 * reorganised for readability, maintainability and clarity.</p>
 */
public class Main {

    /** number of points that are read from the input */
    private static final int POINT_COUNT = 3;

    public static void main(String[] args) {
        // --------------------------------------------------------------
        // 1. Input handling
        // --------------------------------------------------------------
        try (FastScanner scanner = new FastScanner(System.in);
             PrintWriter out = new PrintWriter(System.out, true)) {

            int[][] points = readPoints(scanner, POINT_COUNT);

            // --------------------------------------------------------------
            // 2. First cost calculation – points are sorted by their X‑coordinate
            // --------------------------------------------------------------
            Arrays.sort(points, Comparator.comparingInt(p -> p[0]));
            int costX = solve(points);

            // --------------------------------------------------------------
            // 3. Prepare for the second calculation: swap X and Y coordinates
            // --------------------------------------------------------------
            for (int[] p : points) {
                int tmp = p[0];
                p[0] = p[1];
                p[1] = tmp;
            }
            // after swapping we have to sort again by the new X‑coordinate
            Arrays.sort(points, Comparator.comparingInt(p -> p[0]));

            // --------------------------------------------------------------
            // 4. Second cost calculation
            // --------------------------------------------------------------
            int costY = solve(points);

            // --------------------------------------------------------------
            // 5. Output the smaller of the two costs
            // --------------------------------------------------------------
            out.println(Math.min(costX, costY));
        }
    }

    /**
     * Reads {@code POINT_COUNT} points from the supplied scanner.
     *
     * @param scanner input scanner
     * @param count   number of points to read
     * @return a 2‑dimensional array where each row holds {x, y}
     */
    private static int[][] readPoints(FastScanner scanner, int count) {
        int[][] points = new int[count][2];
        for (int i = 0; i < count; i++) {
            points[i][0] = scanner.nextInt(); // x
            points[i][1] = scanner.nextInt(); // y
        }
        return points;
    }

    /**
     * Implements the original {@code solve} logic but with expressive names
     * and without magic numbers.
     *
     * @param pts array of three points, expected to be sorted by their X‑coordinate
     * @return 1, 2 or 3 according to the configuration of the points
     */
    private static int solve(int[][] pts) {
        // If all X‑coordinates are identical the answer is 1.
        if (pts[0][0] == pts[1][0] && pts[1][0] == pts[2][0]) {
            return 1;
        }

        // Examine the two adjacent pairs (0‑1) and (1‑2) for equal X‑values.
        for (int adjacent = 0; adjacent <= 1; adjacent++) {
            if (pts[adjacent][0] == pts[adjacent + 1][0]) {
                // Determine the smallest and largest Y of the equal‑X pair.
                int minY = Math.min(pts[adjacent][1], pts[adjacent + 1][1]);
                int maxY = Math.max(pts[adjacent][1], pts[adjacent + 1][1]);

                // Index of the remaining (third) point.
                int middleIdx = 2 - 2 * adjacent; // 2 when adjacent==0, 0 when adjacent==1
                int middleY = pts[middleIdx][1];

                // If the third point's Y lies strictly between the min and max,
                // the configuration corresponds to case 3.
                if (minY < middleY && middleY < maxY) {
                    return 3;
                }
                // Otherwise it corresponds to case 2.
                return 2;
            }
        }
        // No adjacent equal X‑values → case 3 by default.
        return 3;
    }

    /**
     * Lightweight scanner based on a reusable byte buffer.
     * It provides the same methods used in the original solution
     * (nextInt, nextLong, etc.) while keeping the implementation compact.
     */
    private static class FastScanner implements AutoCloseable {
        private final InputStream stream;
        private final byte[] buffer = new byte[1024];
        private int bytesRead = 0;
        private int currentPos = 0;

        FastScanner(InputStream stream) {
            this.stream = stream;
        }

        private int nextByte() {
            if (currentPos >= bytesRead) {
                currentPos = 0;
                bytesRead = stream.read(buffer);
                if (bytesRead <= 0) {
                    return -1;
                }
            }
            return buffer[currentPos++];
        }

        private int nextInt() {
            int c;
            do {
                c = nextByte();
            } while (isSpaceChar(c));

            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = nextByte();
            }

            int result = 0;
            while (!isSpaceChar(c)) {
                result = result * 10 + (c - '0');
                c = nextByte();
            }
            return result * sign;
        }

        private static boolean isSpaceChar(int ch) {
            return ch == ' ' || ch == '\n' || ch == '\r' || ch == '\t' || ch == -1;
        }

        @Override
        public void close() {
            try { stream.close(); } catch (IOException ignored) {}
        }
    }
}

import java.io.*;
import java.util.*;

public class D {

    /** Simple container for a 2‑D point */
    private static final class Point {
        final int x, y;
        Point(int x, int y) { this.x = x; this.y = y; }
    }

    /** --------------------------------------------------------------------- */
    /** Program entry point */
    /** --------------------------------------------------------------------- */
    public static void main(String[] args) throws Exception {
        new D().run();
    }

    private void run() throws Exception {
        FastScanner fs = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(System.out, true);
        solve(fs, out);
        out.flush();
    }

    /** --------------------------------------------------------------------- */
    /** Reads the three points, computes the answer and prints it                */
    /** --------------------------------------------------------------------- */
    private void solve(FastScanner fs, PrintWriter out) {
        List<Point> points = readPoints(fs);
        int answer = computeAnswer(points);
        out.println(answer);
    }

    /** --------------------------------------------------------------------- */
    /** Reads three (x, y) pairs from the scanner                               */
    /** --------------------------------------------------------------------- */
    private List<Point> readPoints(FastScanner fs) {
        int x1 = fs.nextInt(), y1 = fs.nextInt();
        int x2 = fs.nextInt(), y2 = fs.nextInt();
        int x3 = fs.nextInt(), y3 = fs.nextInt();
        return List.of(new Point(x1, y1), new Point(x2, y2), new Point(x3, y3));
    }

    /** --------------------------------------------------------------------- */
    /** Core decision logic                                                     */
    /** --------------------------------------------------------------------- */
    private int computeAnswer(List<Point> pts) {
        Point a = pts.get(0), b = pts.get(1), c = pts.get(2);

        // All three share the same x‑coordinate or the same y‑coordinate → 1
        if ((a.x == b.x && b.x == c.x) || (a.y == b.y && b.y == c.y)) {
            return 1;
        }

        // Check for the “right‑angle” configuration that yields answer 2
        if (hasTwoConfiguration(pts)) {
            return 2;
        }

        // Otherwise the answer is 3
        return 3;
    }

    /** --------------------------------------------------------------------- */
    /** Determines whether the three points can form the pattern that gives 2   */
    /** --------------------------------------------------------------------- */
    private boolean hasTwoConfiguration(List<Point> p) {
        Point a = p.get(0), b = p.get(1), c = p.get(2);

        // Any pair shares an x‑coordinate and the third point lies outside that
        // pair's y‑range
        boolean sameX = (a.x == b.x && (c.y <= Math.min(a.y, b.y) || c.y >= Math.max(a.y, b.y)))
                || (a.x == c.x && (b.y <= Math.min(a.y, c.y) || b.y >= Math.max(a.y, c.y)))
                || (b.x == c.x && (a.y <= Math.min(b.y, c.y) || a.y >= Math.max(b.y, c.y)));

        // Any pair shares a y‑coordinate and the third point lies outside that
        // pair's x‑range
        boolean sameY = (a.y == b.y && (c.x <= Math.min(a.x, b.x) || c.x >= Math.max(a.x, b.x)))
                || (a.y == c.y && (b.x <= Math.min(a.x, c.x) || b.x >= Math.max(a.x, c.x)))
                || (b.y == c.y && (a.x <= Math.min(b.x, c.x) || a.x >= Math.max(b.x, c.x)));

        return sameX || sameY;
    }

    /** --------------------------------------------------------------------- */
    /** Fast scanner kept from the original code for speed and compatibility    */
    /** --------------------------------------------------------------------- */
    private static final class FastScanner {
        private final InputStream stream;
        private final byte[] buffer = new byte[16_384];
        private int ptr = 0, len = 0;

        FastScanner(InputStream stream) {
            this.stream = stream;
        }

        private int readByte() throws IOException {
            if (ptr >= len) {
                len = stream.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        boolean isSpaceChar(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        String next() {
            int c;
            while (isSpaceChar(c = readByte()));
            StringBuilder sb = new StringBuilder();
            do {
                sb.append((char) c);
            } while (!isSpaceChar(c = readByte()));
            return sb.toString();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;

/**
 * Refactored version of the original program.
 * <p>
 * The code is split into small, single‑purpose methods, uses meaningful names,
 * avoids duplicated calculations and eliminates magic numbers.  All logic is
 * preserved, but the structure is now easier to understand and maintain.
 */
public class Main {

    /** Simple container for a 2‑D point. */
    private static final class Point {
        int x;
        int y;
    }

    /** Encodes the type of relationship between two points. */
    private enum Relation { SAME_X, SAME_Y, DIFFERENT }

    public static void main(String[] args) {
        List<Point> points = readInputPoints();
        int bestScore = Integer.MAX_VALUE;

        // All six permutations of three distinct indices (0,1,2)
        int[][] permutations = {
                {0, 1, 2}, {0, 2, 1},
                {1, 0, 2}, {1, 2, 0},
                {2, 0, 1}, {2, 1, 0}
        };

        for (int[] idx : permutations) {
            int score = calculateScore(points, idx[0], idx[1], idx[2]);
            if (score < bestScore) {
                bestScore = score;
            }
        }

        System.out.println(bestScore);
    }

    /** Reads three points from standard input. */
    private static List<Point> readInputPoints() {
        List<Point> points = new ArrayList<>(3);
        try (Scanner scanner = new Scanner(System.in)) {
            for (int i = 0; i < 3; i++) {
                Point p = new Point();
                p.x = scanner.nextInt();
                p.y = scanner.nextInt();
                points.add(p);
            }
        }
        return points;
    }

    /**
     * Evaluates the score for a given ordering of three points.
     * The score follows the same rules as the original implementation.
     */
    private static int calculateScore(List<Point> points,
                                      int aIdx, int bIdx, int cIdx) {
        Relation relAB = getRelation(points.get(aIdx), points.get(bIdx));
        Relation relAC = getRelation(points.get(aIdx), points.get(cIdx));
        Relation relBC = getRelation(points.get(bIdx), points.get(cIdx));

        // All three pairs share the same axis (all SAME_X or all SAME_Y)
        if ((relAB == Relation.SAME_X && relAC == Relation.SAME_X && relBC == Relation.SAME_X) ||
            (relAB == Relation.SAME_Y && relAC == Relation.SAME_Y && relBC == Relation.SAME_Y)) {
            return 1;
        }

        // If the first pair has no shared axis, the answer is always 3.
        if (relAB == Relation.DIFFERENT) {
            return 3;
        }

        // Determine whether point C lies outside the bounding interval of A and B
        // on the axis that A and B share.
        return isOutsideBoundingBox(points, aIdx, bIdx, cIdx, relAB) ? 2 : 3;
    }

    /** Returns the relational type between two points. */
    private static Relation getRelation(Point p1, Point p2) {
        if (p1.x == p2.x) {
            return Relation.SAME_X;
        }
        if (p1.y == p2.y) {
            return Relation.SAME_Y;
        }
        return Relation.DIFFERENT;
    }

    /**
     * Checks whether point {@code c} is outside the bounding box of points
     * {@code a} and {@code b} on the axis they share.
     */
    private static boolean isOutsideBoundingBox(List<Point> points,
                                                int aIdx, int bIdx, int cIdx,
                                                Relation sharedRelation) {
        Point a = points.get(aIdx);
        Point b = points.get(bIdx);
        Point c = points.get(cIdx);

        if (sharedRelation == Relation.SAME_X) {
            int minY = Math.min(a.y, b.y);
            int maxY = Math.max(a.y, b.y);
            return c.y <= minY || c.y >= maxY;
        } else { // Relation.SAME_Y
            int minX = Math.min(a.x, b.x);
            int maxX = Math.max(a.x, b.x);
            return c.x <= minX || c.x >= maxX;
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.PrintWriter;
import java.util.StringTokenizer;

/**
 * Refactored solution for the three‑point positioning problem.
 * <p>
 * The program reads three points (x₁,y₁), (x₂,y₂), (x₃,y₃) and prints
 * <ul>
 *   <li>1 – if all x‑coordinates are equal **or** all y‑coordinates are equal,
 *   <li>2 – if one point lies on the same horizontal or vertical line but
 *          outside the interval formed by the other two points,
 *   <li>3 – otherwise.
 * </ul>
 * </p>
 */
public final class Main {

    /** Input helper that reads tokens from {@code System.in}. */
    private static final class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner(InputStream source) {
            br = new BufferedReader(new InputStreamReader(source));
        }

        private String nextToken() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    throw new UncheckedIOException(e);
                }
            }
            return st.nextToken();
        }

        long nextLong() {
            return Long.parseLong(nextToken());
        }

        int nextInt() {
            return Integer.parseInt(nextToken());
        }
    }

    /** Entry point – delegates to {@link #run()}. */
    public static void main(String[] args) {
        new Main().run();
    }

    /** Main processing routine. */
    public void run() {
        FastScanner in = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(System.out, true);

        long x1 = in.nextLong();
        long y1 = in.nextLong();
        long x2 = in.nextLong();
        long y2 = in.nextLong();
        long x3 = in.nextLong();
        long y3 = in.nextLong();

        int result = classify(x1, y1, x2, y2, x3, y3);
        out.println(result);
    }

    /**
     * Evaluates the positional relationship of the three points.
     *
     * @return 1, 2 or 3 according to the specification.
     */
    private static int classify(long x1, long y1,
                                long x2, long y2,
                                long x3, long y3) {
        // 1️⃣ All x‑coordinates are equal → vertical line
        if (isAllEqual(x1, x2, x3)) {
            return 1;
        }
        // 1️⃣ All y‑coordinates are equal → horizontal line
        if (isAllEqual(y1, y2, y3)) {
            return 1;
        }

        // 2️⃣ Check for a “gap” point on a horizontal line
        if (isGapOnHorizontalLine(x1, y1, x2, y2, x3, y3)) {
            return 2;
        }
        // 2️⃣ Check for a “gap” point on a vertical line
        if (isGapOnVerticalLine(x1, y1, x2, y2, x3, y3)) {
            return 2;
        }

        // Default case
        return 3;
    }

    private static boolean isAllEqual(long a, long b, long c) {
        return a == b && b == c;
    }

    /** Returns {@code true} if point (x3, y3) lies on the same horizontal line as (x1,y1) and (x2,y2)
     *  and falls outside the interval formed by x₁ and x₂. */
    private static boolean isGapOnHorizontalLine(long x1, long y1,
                                                   long x2, long y2,
                                                   long x3, long y3) {
        // shared y‑coordinate
        if (y3 != y1) {
            return false;
        }
        long minX = Math.min(x1, x2);
        long maxX = Math.max(x1, x2);
        return (x3 <= minX) || (x3 >= maxX);
    }

    /** Returns {@code true} if point (x3, y3) lies on the same vertical line as (x1,y1) and (x2,y2)
     *  and falls outside the interval formed by y₁ and y₂. */
    private static boolean isGapOnVerticalLine(long x1, long y1,
                                                 long x2, long y2,
                                                 long x3, long y3) {
        // shared x‑coordinate
        if (x3 != x1) {
            return false;
        }
        long minY = Math.min(y1, y2);
        long maxY = Math.max(y1, y2);
        return (y3 <= minY) || (y3 >= maxY);
    }
}

import java.io.*;
import java.util.*;

/**
 * Refactored solution for the “Three Points” problem.
 * Reads three integer points, then outputs:
 *   1 – all X coordinates equal or all Y coordinates equal,
 *   2 – one point lies on the axis‑aligned segment formed by the other two,
 *   3 – otherwise.
 */
public class Codeforces {

    /** Simple immutable point class. */
    private static final class Point {
        final int x;
        final int y;

        Point(int x, int y) {
            this.x = x;
            this.y = y;
        }

        int x() { return x; }
        int y() { return y; }
    }

    /** Checks whether a value lies between two inclusive bounds. */
    private static boolean between(int a, int b, int c) {
        return Math.min(a, b) <= c && c <= Math.max(a, b);
    }

    /**
     * Determines whether {@code middle} lies on the axis‑aligned segment
     * between {@code a} and {@code b}.
     *
     * @return true if the three points are collinear horizontally or vertically
     *         and {@code middle} is between {@code a} and {@code b} on that line.
     */
    private static boolean isOnSegment(Point a, Point b, Point middle) {
        // vertical line (common x‑coordinate)
        if (a.x == b.x && a.x == middle.x && between(a.y, b.y, middle.y)) {
            return true;
        }
        // horizontal line (common y‑coordinate)
        if (a.y == b.y && a.y == middle.y && between(a.x, b.x, middle.x)) {
            return true;
        }
        return false;
    }

    /**
     * Solves a single test case consisting of three points.
     *
     * @param p1 first point
     * @param p2 second point
     * @param p3 third point
     * @return the answer according to the problem statement (1, 2 or 3)
     */
    private static int solve(Point p1, Point p2, Point p3) {
        // All X equal or all Y equal → answer 1
        if ((p1.x() == p2.x() && p2.x() == p3.x()) ||
            (p1.y() == p2.y() && p2.y() == p3.y())) {
            return 1;
        }
        // Any point lies on the segment formed by the other two → answer 2
        if (isOnSegment(p1, p2, p3) ||
            isOnSegment(p1, p3, p2) ||
            isOnSegment(p2, p3, p1)) {
            return 2;
        }
        // Otherwise → answer 3
        return 3;
    }

    /** Simple fast scanner based on BufferedReader + StringTokenizer. */
    private static final class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner(InputStream in) {
            this.br = new BufferedReader(new InputStreamReader(in));
        }

        /** Makes sure a tokenizer is ready; reads a new line if needed. */
        private void ensureTokenizer() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                String line = br.readLine();
                if (line == null) {
                    st = null;
                } else {
                    st = new StringTokenizer(line);
                }
            }
        }

        int nextInt() throws IOException {
            ensureTokenizer();
            return Integer.parseInt(st.nextToken());
        }
    }

    /** Entry point – reads three points and prints the result. */
    public void solve() throws IOException {
        FastScanner fs = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(System.out);

        Point[] pts = new Point[3];
        for (int i = 0; i < 3; i++) {
            pts[i] = new Point(fs.nextInt(), fs.nextInt());
        }

        out.println(solve(pts[0], pts[1], pts[2]));
        out.flush();
    }

    public static void main(String[] args) {
        try {
            new Codeforces().solve();
        } catch (Exception e) {
            e.printStackTrace();
        }
    }
}

import java.io.*;
import java.util.*;
import java.util.function.IntFunction;

/**
 * Solves the problem described by the original code.
 *
 * <p>Key improvements over the original version:
 * <ul>
 *   <li>Input handling is isolated in {@link InputReader}.</li>
 *   <li>Data about each line is stored in a small {@link Point} record,
 *       giving semantic names to the two read values.</li>
 *   <li>Logical steps (reading, checking column equality, applying the
 *       “swap” transformation, and deciding the answer) are split into
 *       clearly‑named private methods.</li>
 *   <li>Magic numbers are replaced by named constants where appropriate.</li>
 *   <li>Naming, formatting and comments follow common Java conventions.</li>
 * </ul>
 */
public class Main {

    /** No magic modulo value is required for this problem – keep the field for compatibility. */
    private static final int MOD = 1_000_000_007;

    /** Small immutable container for the two integers read per line. */
    private static final class Point {
        final int first;   // original “x”
        final int second;  // original “y”

        Point(int first, int second) {
            this.first = first;
            this.second = second;
        }

        /** Swaps the two stored values (used to simulate the in‑place column swap). */
        void swap() {
            int tmp = first;
            first = second;
            second = tmp;
        }
    }

    /** Simple wrapper around {@link BufferedReader} that tokenises input lines. */
    private static final class InputReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        InputReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream), 32768);
        }

        /** Returns the next token, reading a new line if necessary. */
        private String nextToken() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new UncheckedIOException(e);
                }
            }
            return tokenizer.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(nextToken());
        }
    }

    /** Entry point – delegates all work to helper methods. */
    public static void main(String[] args) {
        try (InputStream in = System.in;
             PrintWriter out = new PrintWriter(System.out)) {
            solve(in, out);
            out.flush();
        }
    }

    /** Orchestrates the whole solution. */
    private static void solve(InputReader in, PrintWriter out) {
        Point[] points = readPoints(in);

        if (allValuesEqual(points, Point::first) || allValuesEqual(points, Point::second)) {
            out.print(1);
            return;
        }

        if (hasOverlappingSecondCoordinate(points)) {
            out.print(2);
            return;
        }

        // Simulate the column‑swap performed in the original code.
        for (Point p : points) {
            p.swap();
        }

        if (hasOverlappingSecondCoordinate(points)) {
            out.print(2);
        } else {
            out.print(3);
        }
    }

    /** Reads three points, each consisting of two integers, from the input stream. */
    private static Point[] readPoints(InputReader in) {
        Point[] points = new Point[3];
        for (int i = 0; i < 3; i++) {
            int a = in.nextInt();   // first column
            int b = in.nextInt();   // second column
            points[i] = new Point(a, b);
        }
        return points;
    }

    /** Checks whether the supplied accessor returns the same value for all points. */
    private static boolean allValuesEqual(Point[] points, IntFunction<Integer> accessor) {
        int first = accessor.apply(points[0]);
        for (int i = 1; i < points.length; i++) {
            if (accessor.apply(points[i]) != first) {
                return false;
            }
        }
        return true;
    }

    /** Implements the original `ok` routine – looks for a point whose second coordinate
     *  lies strictly outside the interval spanned by a pair of points sharing the same first coordinate. */
    private static boolean hasOverlappingSecondCoordinate(Point[] points) {
        for (int i = 0; i < points.length; i++) {
            for (int j = i + 1; j < points.length; j++) {
                if (points[i].first != points[j].first) {
                    continue;                     // we only care about equal “first” values
                }
                int commonFirst = points[i].first;
                int lowY = Math.min(points[i].second, points[j].second);
                int highY = Math.max(points[i].second, points[j].second);

                for (int k = 0; k < points.length; k++) {
                    if (k == i || k == j) {
                        continue;
                    }
                    int otherY = points[k].second;
                    if (otherY < lowY || otherY > highY) {
                        return true;
                    }
                }
            }
        }
        return false;
    }
}

import java.io.BufferedReader;
