import java.io.InputStreamReader;
import java.util.StringTokenizer;

/**
 * Refactored version of the original program.
 *
 * <p>The program reads three points (each defined by an x and y integer coordinate)
 * from standard input and prints:
 *
 * <ul>
 *   <li>1 – if all three points share the same x‑coordinate or the same y‑coordinate
 *   <li>2 – if the points form an “L‑shape” (i.e. two points are aligned vertically
 *        or horizontally and the third point lies on that line segment)
 *   <li>3 – otherwise
 * </ul>
 *
 * <p>All functionality is isolated in small, self‑contained methods and classes,
 * making the code easier to maintain and extend.
 */
public class Main {

    /** Simple immutable point representation. */
    private static final class Point {
        private final int x;
        private final int y;

        Point(int x, int y) {
            this.x = x;
            this.y = y;
        }
    }

    /** Fast scanner that reads tokens from {@code System.in}. */
    private static final class FastScanner {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        FastScanner() throws IOException {
            this.reader = new BufferedReader(new InputStreamReader(System.in));
        }

        /** Ensures a {@code StringTokenizer} is ready for use. */
        private void ensureTokenizer() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                tokenizer = new StringTokenizer(reader.readLine());
            }
        }

        /** Reads the next integer token. */
        int nextInt() throws IOException {
            ensureTokenizer();
            return Integer.parseInt(tokenizer.nextToken());
        }
    }

    /**
     * Determines the relationship among three points.
     *
     * @param a first point
     * @param b second point
     * @param c third point
     * @return 1, 2 or 3 according to the original logic
     */
    private static int classify(Point a, Point b, Point c) {
        // 1 – all x or all y are equal
        if ((a.x == b.x && b.x == c.x) || (a.y == b.y && b.y == c.y)) {
            return 1;
        }

        // 2 – vertical or horizontal alignment where the third point lies on the segment
        if (a.x == b.x && (c.y >= Math.max(a.y, b.y) || c.y <= Math.min(a.y, b.y))) {
            return 2;
        }
        if (a.x == c.x && (b.y >= Math.max(a.y, c.y) || b.y <= Math.min(a.y, c.y))) {
            return 2;
        }
        if (b.x == c.x && (a.y >= Math.max(b.y, c.y) || a.y <= Math.min(b.y, c.y))) {
            return 2;
        }
        if (a.y == b.y && (c.x >= Math.max(a.x, b.x) || c.x <= Math.min(a.x, b.x))) {
            return 2;
        }
        if (a.y == c.y && (b.x >= Math.max(a.x, c.x) || b.x <= Math.min(a.x, c.x))) {
            return 2;
        }
        if (b.y == c.y && (a.x >= Math.max(b.x, c.x) || a.x <= Math.min(b.x, c.x))) {
            return 2;
        }

        // 3 – any other configuration
        return 3;
    }

    /** Entry point of the program. */
    public static void main(String[] args) {
        try (FastScanner scanner = new FastScanner()) {
            Point p1 = new Point(scanner.nextInt(), scanner.nextInt());
            Point p2 = new Point(scanner.nextInt(), scanner.nextInt());
            Point p3 = new Point(scanner.nextInt(), scanner.nextInt());

            System.out.println(classify(p1, p2, p3));
        } catch (IOException e) {
            // In a competition environment we simply re‑throw as an unchecked exception.
            throw new RuntimeException(e);
        }
    }
}

import java.io.*;
import java.util.*;

public class Round340Div2 {

    /* -----------------------------------------------------------
       Point representation
       ----------------------------------------------------------- */
    private static final class Point implements Comparable<Point> {
        final int x, y;

        Point(int x, int y) {
            this.x = x;
            this.y = y;
        }

        @Override public int compareTo(Point o) {
            return Integer.compare(x, o.x);
        }
    }

    /* -----------------------------------------------------------
       Simple scanner for fast input
       ----------------------------------------------------------- */
    private static final class FastScanner {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        FastScanner() throws IOException {
            reader = new BufferedReader(new InputStreamReader(System.in));
        }

        private void loadTokens() {
            try {
                tokenizer = new StringTokenizer(reader.readLine());
            } catch (IOException e) {
                throw new UncheckedIOException(e);
            }
        }

        String nextToken() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                loadTokens();
            }
            return tokenizer.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(nextToken());
        }
    }

    /* -----------------------------------------------------------
       Computation of the minimal number of moves
       ----------------------------------------------------------- */
    private static int computeMinSteps(Point a, Point b, Point c) {
        // All points already collinear (vertical or horizontal)
        if (a.x == b.x && b.x == c.x || a.y == b.y && b.y == c.y) {
            return 1;
        }

        // a and b share the same X coordinate – check y‑range of c
        if (a.x == b.x && a.y < b.y) {
            if (c.y >= b.y || c.y <= a.y) {
                return 2;
            }
        }

        // a and b share the same Y coordinate – check x‑range of c
        if (a.y == b.y && a.x < b.x) {
            if (c.x >= b.x || c.x <= a.x) {
                return 2;
            }
        }

        // otherwise no single move can make them collinear
        return 3;
    }

    /* -----------------------------------------------------------
       Utility methods for permutation handling
       ----------------------------------------------------------- */
    private static boolean nextPermutation(int[] a) {
        int i = a.length - 1;
        while (i > 0 && a[i] < a[i - 1]) {
            i--;
        }
        if (i == 0) {
            return false;
        }
        int j = a.length - 1;
        while (a[j] < a[i - 1]) {
            j--;
        }
        swap(a, i - 1, j);
        reverse(a, i, a.length - 1);
        return true;
    }

    private static void swap(int[] arr, int i, int j) {
        int tmp = arr[i];
        arr[i] = arr[j];
        arr[j] = tmp;
    }

    private static void reverse(int[] arr, int from, int to) {
        while (from < to) {
            swap(arr, from++, to--);
        }
    }

    /* -----------------------------------------------------------
       Entry point
       ----------------------------------------------------------- */
    public static void main(String[] args) throws IOException {
        FastScanner scanner = new FastScanner();

        Point[] points = new Point[3];
        for (int i = 0; i < 3; i++) {
            points[i] = new Point(scanner.nextInt(), scanner.nextInt());
        }

        int answer = 3;
        int[] perm = {0, 1, 2};

        do {
            answer = Math.min(answer,
                    computeMinSteps(
                            points[perm[0]],
                            points[perm[1]],
                            points[perm[2]]
                    ));
        } while (nextPermutation(perm));

        System.out.println(answer);
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.PrintWriter;
import java.util.HashSet;
import java.util.HashMap;
import java.util.Map;
import java.util.Set;

public class Main {

    /** Simple immutable holder for a 2‑D point. */
    private static final class Point {
        final int x;
        final int y;

        Point(int x, int y) {
            this.x = x;
            this.y = y;
        }

        /** Returns the coordinate that is repeated (for the "normal" axis). */
        static Point[] groupedByAxis(Point p1, Point p2, Point p3, boolean byX) {
            // The point whose coordinate (x or y) is unique is returned as the third element.
            // The other two points (with the same coordinate) are returned first.
            if (byX) {
                if (p1.x == p2.x) {
                    return new Point[]{p1, p2, p3};
                } else if (p2.x == p3.x) {
                    return new Point[]{p2, p3, p1};
                } else {
                    return new Point[]{p1, p3, p2};
                }
            } else { // byY
                if (p1.y == p2.y) {
                    return new Point[]{p1, p2, p3};
                } else if (p2.y == p3.y) {
                    return new Point[]{p2, p3, p1};
                } else {
                    return new Point[]{p1, p3, p2};
                }
            }
        }

        /** Checks whether `value` lies strictly between `a` and `b`. */
        static boolean isBetween(int value, int a, int b) {
            int lo = Math.min(a, b);
            int hi = Math.max(a, b);
            return value > lo && value < hi;
        }
    }

    public static void main(String[] args) throws IOException {
        try (BufferedReader br = new BufferedReader(new java.io.InputStreamReader(System.in))) {
            PrintWriter pw = new PrintWriter(System.out);

            Point[] points = readThreePoints(br);
            int answer = computeAnswer(points);

            pw.println(answer);
            pw.flush();
        }
    }

    /** Reads three lines from the supplied BufferedReader and converts them to {@link Point}s. */
    private static Point[] readThreePoints(BufferedReader br) throws IOException {
        Point[] pts = new Point[3];
        for (int i = 0; i < 3; i++) {
            String[] parts = br.readLine().trim().split("\\s+");
            int x = Integer.parseInt(parts[0]);
            int y = Integer.parseInt(parts[1]);
            pts[i] = new Point(x, y);
        }
        return pts;
    }

    /** Main decision logic – kept separate for readability and testability. */
    private static int computeAnswer(Point[] pts) {
        Set<Integer> distinctX = collectCoordinate(pts, p -> p.x);
        Set<Integer> distinctY = collectCoordinate(pts, p -> p.y);

        // Simple cases where the answer is fixed
        if (distinctX.size() == 1 || distinctY.size() == 1) {
            return 1;
        }
        if (distinctX.size() == 3 && distinctY.size() == 3) {
            return 3;
        }
        if (distinctX.size() == 2 && distinctY.size() == 2) {
            return 2;
        }

        // At this point exactly one of the axes has exactly two distinct values.
        if (distinctX.size() == 2) {
            return handleAxisWithTwoValues(pts, true); // true → axis is X
        }
        // distinctY.size() must be 2 here
        return handleAxisWithTwoValues(pts, false); // false → axis is Y
    }

    /** Helper that deals with the situation where exactly two distinct values exist on the chosen axis. */
    private static int handleAxisWithTwoValues(Point[] pts, boolean byX) {
        // Split points into the group that shares the repeated coordinate and the loner.
        Point[] grouped = Point.groupedByAxis(pts[0], pts[1], pts[2], byX);
        Point loner = grouped[2];
        Point p1 = grouped[0];
        Point p2 = grouped[1];

        // Compare the *other* coordinate (Y if we grouped by X, X otherwise) of the loner.
        int otherValue = byX ? loner.y : loner.x;
        int other1 = byX ? p1.y : p1.x;
        int other2 = byX ? p2.y : p2.x;

        return Point.isBetween(otherValue, other1, other2) ? 3 : 2;
    }

    /** Collects a specific coordinate from all points using a supplied mapping function. */
    private static Set<Integer> collectCoordinate(Point[] points, java.util.function.Function<Point, Integer> extractor) {
        Set<Integer> set = new HashSet<>();
        for (Point p : points) {
            set.add(extractor.apply(p));
        }
        return set;
    }
}

import java.io.*;
import java.util.StringTokenizer;

/**
 * Competitive‑programming template with a fast scanner,
 * a tiny point utility, and a clean solve routine.
 *
 * The logic is identical to the original implementation,
 * but the code is now split into well‑named, reusable parts,
 * uses meaningful identifiers and avoids raw types.
 */
public class Main {

    /*------------------------------------------------------------------*/
    /*  Fast input scanner                                               */
    /*------------------------------------------------------------------*/
    private static final class FastScanner {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        FastScanner(BufferedReader reader) {
            this.reader = reader;
        }

        /** Make sure a tokenizer with tokens exists. */
        private void ensureTokens() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                String line = reader.readLine();
                if (line == null || line.isBlank()) {
                    tokenizer = null;
                    continue;
                }
                tokenizer = new StringTokenizer(line, " :");
            }
        }

        String next() throws IOException {
            ensureTokens();
            return tokenizer.nextToken();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }

        long nextLong() throws IOException {
            return Long.parseLong(next());
        }

        double nextDouble() throws IOException {
            return Double.parseDouble(next());
        }
    }

    /*------------------------------------------------------------------*/
    /*  Simple immutable point representation                             */
    /*------------------------------------------------------------------*/
    private static final class Point {
        final long x;
        final long y;

        Point(long x, long y) {
            this.x = x;
            this.y = y;
        }
    }

    /*------------------------------------------------------------------*/
    /*  Solver – contains the actual algorithm and the entry point      */
    /*------------------------------------------------------------------*/
    private static final class Solver implements Runnable {

        private static final long MEMORY_SNAPSHOT = Runtime.getRuntime().freeMemory();

        private final FastScanner scanner = new FastScanner(new BufferedReader(new InputStreamReader(System.in)));
        private final PrintWriter out = new PrintWriter(System.out, true);

        /** Entry point used by the launcher thread. */
        static void launch() {
            new Thread(null, new Solver(), "", 1L * 200L * 1024L * 1024L).start();
        }

        @Override
        public void run() {
            try {
                long startTime = System.currentTimeMillis();
                long memoryBefore = Runtime.getRuntime().freeMemory();

                solve();

                out.close(); // flush everything before checking debug info
                if (!isOnlineJudge()) {
                    System.err.println("Time = " + (System.currentTimeMillis() - startTime) + " ms");
                    long memoryAfter = Runtime.getRuntime().freeMemory();
                    System.err.println("Memory = " + ((memoryBefore - memoryAfter) >> 10) + " KB");
                }
            } catch (Exception ex) {
                ex.printStackTrace();
                System.exit(-1);
            }
        }

        private boolean isOnlineJudge() {
            return System.getProperty("ONLINE_JUDGE") != null;
        }

        /** Core solution – reads three points and prints the answer. */
        private void solve() throws IOException {
            Point a = new Point(scanner.nextInt(), scanner.nextInt());
            Point b = new Point(scanner.nextInt(), scanner.nextInt());
            Point c = new Point(scanner.nextInt(), scanner.nextInt());

            if (allThreeShareCoordinate(a, b, c)) {
                out.println(1);
                return;
            }

            if (anyThirdPointOutsideSegment(a, b, c) ||
                anyThirdPointOutsideSegment(a, c, b) ||
                anyThirdPointOutsideSegment(b, a, c) ||
                anyThirdPointOutsideSegment(b, c, a) ||
                anyThirdPointOutsideSegment(c, a, b) ||
                anyThirdPointOutsideSegment(c, b, a)) {
                out.println(2);
            } else {
                out.println(3);
            }
        }

        /** Are the three points collinear on a vertical or horizontal line? */
        private boolean allThreeShareCoordinate(Point p1, Point p2, Point p3) {
            return (p1.x == p2.x && p2.x == p3.x) || (p1.y == p2.y && p2.y == p3.y);
        }

        /**
         * Returns {@code true} if the third point lies on the same line as
         * {@code anchor} and {@code other} AND it is *outside* the segment
         * formed by those two points.
         */
        private boolean anyThirdPointOutsideSegment(Point anchor, Point other, Point third) {
            if (anchor.x == other.x) {
                return third.y <= Math.min(anchor.y, other.y) ||
                       third.y >= Math.max(anchor.y, other.y);
            }
            if (anchor.y == other.y) {
                return third.x <= Math.min(anchor.x, other.x) ||
                       third.x >= Math.max(anchor.x, other.x);
            }
            return false;
        }
    }

    /*------------------------------------------------------------------*/
    /*  Launcher – starts the solver thread                               */
    /*------------------------------------------------------------------*/
    public static void main(String[] args) {
        Solver.launch();
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.*;

/**
 * Main class that reads three points, determines whether they lie on a
 * horizontal/vertical line or form a rectangle, and prints the minimum
 * number of straight lines (horizontal or vertical) needed to cover all
 * points – 1, 2 or 3.
 *
 * <p>The algorithm works in three easy‑to‑read steps:
 * <ol>
 *   <li>Collect the x‑coordinates and y‑coordinates in separate sets to
 *       know how many distinct values we have.</li>
 *   <li>Sort the points by {@code x} and by {@code y} and look for
 *       adjacent equal coordinates.</li>
 *   <li>Apply the rule set described in the original program.</li>
 * </ol>
 *
 * The code is deliberately split into small, pure methods so that each
 * responsibility is clear and unit‑testing becomes straightforward.
 */
public final class Main {

    /** Entry point. */
    public static void main(String[] args) throws IOException {
        try (FastScanner fs = new FastScanner()) {
            int ans = solve(fs.readThreePoints());
            System.out.println(ans);
        }
    }

    /** Reads exactly three points from the scanner. */
    private static List<Point> readThreePoints(FastScanner fs) {
        List<Point> points = new ArrayList<>(3);
        for (int i = 0; i < 3; i++) {
            long x = fs.nextLong();
            long y = fs.nextLong();
            points.add(new Point(x, y));
        }
        return Collections.unmodifiableList(points);
    }

    /** Implements the core decision logic. */
    private static int solve(List<Point> points) {
        // distinct x / y values
        Set<Long> distinctX = distinctCoordinates(points, Point::x);
        Set<Long> distinctY = distinctCoordinates(points, Point::y);

        // If all points share the same x or the same y → one line enough.
        if (distinctX.size() == 1 || distinctY.size() == 1) {
            return 1;
        }

        // Sort once by x and once by y to test adjacency of equal values.
        List<Point> byX = new ArrayList<>(points);
        List<Point> byY = new ArrayList<>(points);
        byX.sort(Comparator.comparingLong(Point::x));
        byY.sort(Comparator.comparingLong(Point::y));

        boolean adjacentEqualX = hasAdjacentEqual(b(y -> b.x), byX);
        boolean adjacentEqualY = hasAdjacentEqual(b.y, byY);

        // Two lines are sufficient when:
        //   * there are exactly two different x‑values and two different y‑values,
        //   * or an adjacent pair of points shares the same x (in x‑sorted order)
        //     or the same y (in y‑sorted order).
        if (distinctX.size() == 2 && distinctY.size() == 2 || adjacentEqualX || adjacentEqualY) {
            return 2;
        }

        // Otherwise three lines are required.
        return 3;
    }

    /** Helper that checks whether a list contains two equal consecutive elements. */
    private static <T> boolean hasAdjacentEqual(Function<? super T, Long> extractor, List<T> list) {
        for (int i = 0; i < list.size() - 1; i++) {
            if (extractor.apply(list.get(i)).equals(extractor.apply(list.get(i + 1)))) {
                return true;
            }
        }
        return false;
    }

    /** Returns a collection containing the distinct values produced by {@code extractor}. */
    private static <T, R> Set<R> distinctCoordinates(List<T> points, Function<? super T, R> extractor) {
        return points.stream().map(extractor).collect(Collectors.toSet());
    }

    /** Holds a single point with immutable coordinates. */
    public static final class Point {
        private final long x;
        private final long y;

        public Point(long x, long y) {
            this.x = x;
            this.y = y;
        }

        public long x() {
            return x;
        }

        public long y() {
            return y;
        }

        @Override
        public boolean equals(Object o) {
            if (this == o) return true;
            if (!(o instanceof Point)) return false;
            Point other = (Point) o;
            return x == other.x && y == other.y;
        }

        @Override
        public int hashCode() {
            return Objects.hash(x, y);
        }

        @Override
        public String toString() {
            return "Point(%d, %d)".formatted(x, y);
        }
    }

    /** Very small fast scanner that works with both files and stdin. */
    public static final class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner() {
            this(new InputStreamReader(System.in));
        }

        public FastScanner(Reader in) {
            this.br = new BufferedReader(in);
        }

        /** Reads the next token, blocking until a token is available. */
        public String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) {
                        return null; // EOF
                    }
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new UncheckedIOException(e);
                }
            }
            return st.nextToken();
        }

        /** Reads the next long value (or throws NumberFormatException if not a number). */
        public long nextLong() {
            return Long.parseLong(next());
        }

        /** Reads the next int value. */
        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

