/**
 * Solves the “Polyline” problem by determining the minimal number of
 * axis‑aligned segments required to connect three given points.
 *
 * The algorithm follows these rules:
 * <ul>
 *   <li>If all points share the same X or the same Y coordinate, only 1 level is needed.</li>
 *   <li>If any point lies on a segment formed by the other two, the answer is 2.</li>
 *   <li>Otherwise the answer is 3.</li>
 * </ul>
 */
public class Polyline {

    /** Number of input points (always 3 for this problem). */
    private static final int POINT_COUNT = 3;

    /** Minimum possible answer (used when points are collinear on a straight line). */
    private static final int MIN_ANSWER = 1;

    /** Maximum possible answer (used as the fallback). */
    private static final int MAX_ANSWER = 3;

    /** Simple wrapper around {@link BufferedReader} that tokenises input. */
    private static final class InputReader {
        private final BufferedReader br;
        private StringTokenizer st;

        InputReader(BufferedReader br) {
            this.br = br;
        }

        /** Returns the next token, reading a new line when necessary. */
        private String nextToken() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                String line = br.readLine();
                if (line == null) {
                    return null;
                }
                st = new StringTokenizer(line);
            }
            return st.nextToken();
        }

        /** Reads the next integer from the input. */
        int nextInt() throws IOException {
            return Integer.parseInt(nextToken());
        }
    }

    /** Simple wrapper around {@link PrintWriter} for output. */
    private static final class OutputWriter {
        private final PrintWriter pw;

        OutputWriter(java.io.OutputStream out) {
            this.pw = new PrintWriter(out);
        }

        void println(int value) {
            pw.println(value);
        }

        void close() {
            pw.close();
        }
    }

    /* --------------------------------------------------------------------- */
    /*  Entry point                                                          */
    /* --------------------------------------------------------------------- */
    public static void main(String[] args) throws IOException {
        new Polyline().solve();
    }

    /** Core solving routine – reads input, computes the answer, prints it. */
    private void solve() throws IOException {
        int[] xs = new int[POINT_COUNT];
        int[] ys = new int[POINT_COUNT];

        InputReader reader = new InputReader(new BufferedReader(new InputStreamReader(System.in)));

        for (int i = 0; i < POINT_COUNT; i++) {
            xs[i] = reader.nextInt();
            ys[i] = reader.nextInt();
        }

        int answer = computeAnswer(xs, ys);
        new OutputWriter(System.out).println(answer);
    }

    /* --------------------------------------------------------------------- */
    /*  Answer computation                                                   */
    /* --------------------------------------------------------------------- */

    /** Determines the minimal number of levels required for the polyline. */
    private int computeAnswer(int[] x, int[] y) {
        // 1️⃣  All x‑coordinates equal (vertical line) or all y‑coordinates equal (horizontal line)
        if (areAllXEqual(x) || areAllYEqual(y)) {
            return MIN_ANSWER;
        }

        // 2️⃣  Check whether any point lies on the axis‑aligned segment formed by the other two.
        for (int i = 0; i < POINT_COUNT; i++) {
            int a = (i + 1) % POINT_COUNT;
            int b = (i + 2) % POINT_COUNT;

            if (pointLiesOnSegment(i, a, b, x, y)) {
                return 2;
            }
        }

        // 3️⃣  Otherwise three levels are necessary.
        return MAX_ANSWER;
    }

    /** Returns true if all x‑values are identical. */
    private boolean areAllXEqual(int[] x) {
        return x[0] == x[1] && x[1] == x[2];
    }

    /** Returns true if all y‑values are identical. */
    private boolean areAllYEqual(int[] y) {
        return y[0] == y[1] && y[1] == y[2];
    }

    /**
     * Checks whether the point at index {@code k} lies on the axis‑aligned
     * segment that connects points {@code i} and {@code j}.
     *
     * @return {@code true} if point {@code k} is on the segment between {@code i} and {@code j}.
     */
    private boolean pointLiesOnSegment(int k, int i, int j, int[] x, int[] y) {
        // The segment is vertical (share the same X coordinate).
        if (x[k] == x[i] || x[k] == x[j]) {
            int minY = Math.min(y[i], y[j]);
            int maxY = Math.max(y[i], y[j]);
            return y[k] >= minY && y[k] <= maxY;
        }

        // The segment is horizontal (share the same Y coordinate).
        if (y[k] == y[i] || y[k] == y[j]) {
            int minX = Math.min(x[i], x[j]);
            int maxX = Math.max(x[i], x[j]);
            return x[k] >= minX && x[k] <= maxX;
        }

        // Points do not align on a common row or column → not on the segment.
        return false;
    }
}

import java.io.*;
import java.util.*;

public class Solution {

    /** Simple container for a 2‑D point. */
    private static final class Point {
        final int x;
        final int y;

        Point(int x, int y) {
            this.x = x;
            this.y = y;
        }
    }

    /** Determines the answer for a set of three points. */
    private static int solve(Point[] pts) {
        // 1️⃣  All points share the same X coordinate (column) → answer 1
        if (pts[0].x == pts[1].x && pts[1].x == pts[2].x) {
            return 1;
        }
        // 2️⃣  All points share the same Y coordinate (row) → answer 1
        if (pts[0].y == pts[1].y && pts[1].y == pts[2].y) {
            return 1;
        }

        // Helper to check “point lies on the same column/row and is extreme”
        // relative to two other points.
        java.util.function.BiPredicate<Point, Point> extremeOnColumn = (p, a) -> {
            return p.x == a.x && (p.y >= Math.max(a.y, pts[otherIndex(a, pts) == 0 ? 1 : 0].y)
                                    || p.y <= Math.min(a.y, pts[otherIndex(a, pts) == 0 ? 1 : 0].y));
        };
        java.util.function.BiPredicate<Point, Point> extremeOnRow = (p, a) -> {
            return p.y == a.y && (p.x >= Math.max(a.x, pts[otherIndex(a, pts) == 0 ? 1 : 0].x)
                                    || p.x <= Math.min(a.x, pts[otherIndex(a, pts) == 0 ? 1 : 0].x));
        };

        // 3️⃣  Patterns that lead to answer 2 – checked by column matches
        if (pts[0].x == pts[1].x && extremeOnColumn.test(pts[2], pts[0])) return 2;
        if (pts[0].x == pts[2].x && extremeOnColumn.test(pts[1], pts[0])) return 2;
        if (pts[1].x == pts[2].x && extremeOnColumn.test(pts[0], pts[1])) return 2;

        // 4️⃣  Patterns that lead to answer 2 – checked by row matches
        if (pts[0].y == pts[1].y && extremeOnRow.test(pts[2], pts[0])) return 2;
        if (pts[0].y == pts[2].y && extremeOnRow.test(pts[1], pts[0])) return 2;
        if (pts[1].y == pts[2].y && extremeOnRow.test(pts[0], pts[1])) return 2;

        // 5️⃣  Anything else → answer 3
        return 3;
    }

    /** Utility to obtain the index of the point that is *not* the given one. */
    private static int otherIndex(int exclude, Point[] arr) {
        return (exclude == 0) ? 1 : 0;
    }

    public static void main(String[] args) {
        FastReader scan = new FastReader();
        PrintWriter out = new PrintWriter(System.out);

        // The original snippet used a fixed loop count of 1 – keep that behaviour.
        for (int testNumber = 1; testNumber <= 1; testNumber++) {
            Point[] points = new Point[3];
            for (int i = 0; i < 3; i++) {
                points[i] = new Point(scan.nextInt(), scan.nextInt());
            }
            int result = solve(points);
            out.println(result);
        }
        out.close();
    }

    /** Fast input reader that works with both console and file sources. */
    static class FastReader {
        private final BufferedReader br;
        private StringTokenizer st;

        FastReader() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    throw new UncheckedIOException(e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        long nextLong() {
            return Long.parseLong(next());
        }

        double nextDouble() {
            return Double.parseDouble(next());
        }

        String nextLine() {
            try {
                return br.readLine();
            } catch (IOException e) {
                throw new UncheckedIOException(e);
            }
        }
    }
}

import java.io.*;
import java.util.HashSet;
import java.util.Set;

/**
 * Reads three points from standard input and prints:
 *   1 – if all x‑coordinates are equal or all y‑coordinates are equal,
 *   2 – if any point lies on the same horizontal or vertical line as the other two
 *       and is not strictly between them,
 *   3 – otherwise.
 *
 * The implementation focuses on readability, proper resource handling,
 * and meaningful naming.
 */
public final class Solution {

    /** Immutable point with integer coordinates. */
    private static final class Point {
        final int x;
        final int y;

        Point(int x, int y) {
            this.x = x;
            this.y = y;
        }

        /**
         * Returns {@code true} if this point shares the same horizontal or vertical
         * line with {@code a} and {@code b} and is not strictly between them
         * (i.e. its coordinate equals or lies outside the interval formed by {@code a}
         * and {@code b}).
         */
        boolean isOnOuterEdge(Point a, Point b) {
            // Horizontal alignment
            if (a.y == b.y && this.y == a.y) {
                int minX = Math.min(a.x, b.x);
                int maxX = Math.max(a.x, b.x);
                return this.x <= minX || this.x >= maxX;
            }
            // Vertical alignment
            if (a.x == b.x && this.x == a.x) {
                int minY = Math.min(a.y, b.y);
                int maxY = Math.max(a.y, b.y);
                return this.y <= minY || this.y >= maxY;
            }
            return false;
        }
    }

    private static Point readPoint(Scanner sc) {
        int x = sc.nextInt();
        int y = sc.nextInt();
        return new Point(x, y);
    }

    public static void main(String[] args) throws IOException {
        // Try‑with‑resources ensures streams are closed automatically.
        try (Scanner scanner = new Scanner(System.in);
             PrintWriter out = new PrintWriter(System.out)) {

            Point[] points = new Point[3];
            Set<Integer> distinctX = new HashSet<>();
            Set<Integer> distinctY = new HashSet<>();

            // Read three points and collect distinct coordinates.
            for (int i = 0; i < 3; i++) {
                points[i] = readPoint(scanner);
                distinctX.add(points[i].x);
                distinctY.add(points[i].y);
            }

            // Case 1: all x or all y are identical → output 1.
            if (distinctX.size() == 1 || distinctY.size() == 1) {
                out.println(1);
                return;
            }

            // Determine if any point lies on the outer edge of the segment formed
            // by the other two points.
            boolean anyOutside = false;
            for (int i = 0; i < 3; i++) {
                Point p = points[i];
                Point a = points[(i + 1) % 3];
                Point b = points[(i + 2) % 3];
                if (p.isOnOuterEdge(a, b)) {
                    anyOutside = true;
                    break;
                }
            }

            out.println(anyOutside ? 2 : 3);
        }
    }

    /** Simple wrapper around {@code java.util.Scanner} for this program. */
    private static final class Scanner {
        private final java.util.Scanner sc;

        Scanner(java.io.InputStream source) {
            this.sc = new java.util.Scanner(source);
        }

        int nextInt() {
            return sc.nextInt();
        }
    }
}

import java.io.*;
import java.util.*;

public class Main {

    /** Simple immutable point class used for the three input coordinates. */
    private static final class Point implements Comparable<Point> {
        final int x;
        final int y;

        Point(int x, int y) {
            this.x = x;
            this.y = y;
        }

        /** Natural ordering: first by X, then by Y. */
        @Override
        public int compareTo(Point o) {
            if (x != o.x) {
                return Integer.compare(x, o.x);
            }
            return Integer.compare(y, o.y);
        }
    }

    /** Determines the classification code (1, 2 or 3) for the three points. */
    private static int determineResult(Point[] pts) {
        // All three points share the same X coordinate → vertical line
        if (pts[0].x == pts[1].x && pts[1].x == pts[2].x) {
            return 1;
        }

        // All three points share the same Y coordinate → horizontal line
        if (pts[0].y == pts[1].y && pts[1].y == pts[2].y) {
            return 1;
        }

        // Check for any alignment on X or Y.
        boolean hasVerticalAlignment   = pts[0].x == pts[1].x ||
                                         pts[0].x == pts[2].x ||
                                         pts[1].x == pts[2].x;

        boolean hasHorizontalAlignment = pts[0].y == pts[1].y ||
                                         pts[0].y == pts[2].y ||
                                         pts[1].y == pts[2].y;

        // Original program returned 2 whenever the points could be considered
        // aligned in either direction; keep the same semantics.
        if (hasVerticalAlignment || hasHorizontalAlignment) {
            return 2;
        }

        // When no alignment exists we fall back to the default case.
        return 3;
    }

    public static void main(String[] args) throws Exception {
        try (Scanner scanner = new Scanner(System.in);
             PrintWriter out = new PrintWriter(new BufferedOutputStream(System.out))) {

            Point[] points = new Point[3];
            for (int i = 0; i < 3; ++i) {
                int x = scanner.nextInt();
                int y = scanner.nextInt();
                points[i] = new Point(x, y);
            }

            Arrays.sort(points);
            int result = determineResult(points);
            out.println(result);
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Main entry point. Handles input, creates the solver and prints the result.
 */
public class Main {

    public static void main(String[] args) {
        // Use try‑with‑resources to guarantee streams are closed.
        try (InputReader reader = new InputReader(System.in);
             PrintWriter out = new PrintWriter(System.out)) {
            new Solver().solve(reader, out);
        }
    }

    /**
     * Reads all input data and delegates the actual solving logic to {@link Solver}.
     */
    static final class Solver {

        /** Entry point for the solving algorithm. */
        void solve(InputReader in, PrintWriter out) {
            Point a = readPoint(in);
            Point b = readPoint(in);
            Point c = readPoint(in);

            // If the three points are collinear and the vector from a→b is axis‑aligned,
            // the answer is 1 (the same behaviour as the original code).
            if (isCollinearAndAxisAligned(a, b, c, out)) {
                return;
            }

            // Try to find a suitable origin (x, y) taken from the set of distinct
            // coordinates of the original points. If exactly two distinct directions
            // are required we can finish in two moves.
            if (canFinishInTwoMoves(a, b, c, out)) {
                return;

            // Otherwise three moves are always sufficient.
            out.println(3);
        }

        /** Returns true if the answer is known to be 1, otherwise prints 1 and exits. */
        private boolean isCollinearAndAxisAligned(Point a, Point b, Point c, PrintWriter out) {
            Point dirAB = a.subtract(b);
            // collinearity test: cross product of (a‑b) and (a‑c) must be zero
            if (dirAB.det(a.subtract(c)) == 0) {
                // axis‑aligned if either component is zero
                if (dirAB.x == 0 || dirAB.y == 0) {
                    out.println(1);
                    return true;
                }
            }
            return false;
        }

        /** Checks all candidate origins composed of distinct x‑ and y‑coordinates.
         *  Prints 2 and exits if a suitable origin is found, otherwise returns false. */
        private boolean canFinishInTwoMoves(Point a, Point b, Point c, PrintWriter out) {
            Point[] points = {a, b, c};
            long[] xs = {a.x, b.x, c.x};
            long[] ys = {a.y, b.y, c.y};

            for (long x : xs) {
                for (long y : ys) {
                    Point origin = new Point(x, y);
                    int mask = 0;

                    for (Point p : points) {
                        Point delta = p.subtract(origin);

                        // If the move is not purely horizontal or vertical, skip this origin.
                        if (delta.x != 0 && delta.y != 0) {
                            continue outerLoop;
                        }

                        // Ignore the case where origin coincides with the point (no movement).
                        if (delta.x == 0 && delta.y == 0) {
                            continue;
                        }

                        // Record the required direction.
                        if (delta.x == 0) {                     // vertical movement
                            mask |= (delta.y < 0) ? Direction.UP.bit : Direction.DOWN.bit;
                        } else {                                // horizontal movement
                            mask |= (delta.x < 0) ? Direction.LEFT.bit : Direction.RIGHT.bit;
                        }
                    }

                    // Exactly two distinct directions are needed for a two‑move solution.
                    if (Integer.bitCount(mask) == 2) {
                        out.println(2);
                        return true;
                    }
                }
            }
            // No origin gave exactly two directions → cannot finish in two moves.
            return false;

            // -----------------------------------------------------------------
            // Support for breaking out of the nested loops once a suitable origin
            // has been examined. The label is only used for the continue statement.
            // -----------------------------------------------------------------
            outerLoop: ;
        }

        /** Directions that are allowed when moving axis‑alignly. */
        private enum Direction {
            UP(0),       // negative y
            DOWN(1),     // positive y
            LEFT(2),     // negative x
            RIGHT(3);    // positive x

            private final int bit;
            Direction(int bit) { this.bit = bit; }

            /** Returns the bit used for the bit‑mask representation. */
            int bit() { return bit; }
        }

        /** Simple immutable 2‑D point with long coordinates. */
        private static final class Point {
            final long x, y;

            Point(long x, long y) {
                this.x = x;
                this.y = y;
            }

            /** Vector subtraction. */
            Point subtract(Point o) {
                return new Point(x - o.x, y - o.y);
            }

            /** 2‑D cross product (det) of this point with another point treated as a vector.
             *  Used to test collinearity. */
            long det(Point o) {
                return x * o.y - y * o.x;
            }
        }
    }

    /**
     * Fast scanner that reads tokens from {@code System.in}.
     * It mimics the original {@code InputReader} but uses {@link BufferedReader}
     * only once per line for better performance.
     */
    static final class InputReader implements AutoCloseable {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        InputReader(InputStream stream) {
            this.reader = new BufferedReader(new InputStreamReader(stream));
        }

        /** Returns the next token, reading a new line if necessary. */
        String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new UncheckedIOException(e);
                }
            }
            return tokenizer.nextToken();
        }

        /** Convenience wrapper around {@code Integer.parseInt}. */
        int nextInt() {
            return Integer.parseInt(next());
        }

        @Override
        public void close() throws IOException {
            reader.close();
        }
    }
}

import java.io.*;
import java.util.*;
import java.util.stream.*;

public class Main {

    public static void main(String[] args) throws Exception {
        /* Try‑with‑resources guarantees that the reader is closed */
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in))) {
            PrintWriter pw = new PrintWriter(System.out, true);
            int answer = solve(br);
            pw.println(answer);
        }
    }

    /**
     * Reads three points from {@code in} and returns the required result.
     */
    private static int solve(BufferedReader in) throws IOException {
        /* ---- input ---- */
        Point p1 = readPoint(in);
        Point p2 = readPoint(in);
        Point p3 = readPoint(in);
        List<Point> points = List.of(p1, p2, p3);

        /* ---- distinct coordinate counts ---- */
        Set<Integer> distinctX = points.stream().map(p -> p.x()).collect(Collectors.toSet());
        Set<Integer> distinctY = points.stream().map(p -> p.y()).collect(Collectors.toSet());

        int minDistinct = Math.min(distinctX.size(), distinctY.size());

        /* ---- early exit when the minimum is not 2 ---- */
        if (minDistinct != 2) {
            return minDistinct;
        }

        /* ---- exactly two distinct values in one axis ---- */
        return distinctX.size() == 2
                ? handleDuplicateCoordinate(points, true)   // duplicate X → look at Y interval
                : handleDuplicateCoordinate(points, false); // duplicate Y → look at X interval
    }

    /** Reads a single point (two integers separated by whitespace). */
    private static Point readPoint(BufferedReader in) throws IOException {
        String[] tokens = in.readLine().split("\\s+");
        int x = Integer.parseInt(tokens[0]);
        int y = Integer.parseInt(tokens[1]);
        return new Point(x, y);
    }

    /**
     * Handles the case when exactly two points share the same X (or Y) coordinate.
     *
     * @param points   the three input points
     * @param duplicateX {@code true} if the duplicate axis is X, {@code false} otherwise
     * @return 2 or 3 according to the geometric condition
     */
    private static int handleDuplicateCoordinate(List<Point> points, boolean duplicateX) {
        /* ---- group points by the axis we are interested in (X or Y) ---- */
        Map<Integer, List<Point>> byAxis = points.stream()
                .collect(Collectors.groupingBy(p -> duplicateX ? p.x() : p.y()));

        /* ---- find the key that appears exactly twice ---- */
        int dupKey = byAxis.entrySet().stream()
                .filter(e -> e.getValue().size() == 2)
                .map(Map.Entry::getKey)
                .findFirst()
                .orElseThrow();

        List<Point> dupPoints = byAxis.get(dupKey);
        Point other = byAxis.entrySet().stream()
                .filter(e -> e.getValue().size() == 1)
                .findFirst()
                .map(Map.Entry::getValue)
                .orElseThrow()
                .get(0);

        /* ---- compute the interval of the *other* coordinate of the duplicated pair ---- */
        int coordA = duplicateX ? dupPoints.get(0).y() : dupPoints.get(0).x();
        int coordB = duplicateX ? dupPoints.get(1).y() : dupPoints.get(1).x();
        int low = Math.min(coordA, coordB);
        int high = Math.max(coordA, coordB);

        /* ---- check the remaining point against that interval ---- */
        int otherCoord = duplicateX ? other.y() : other.x();

        return (otherCoord <= low || otherCoord >= high) ? 2 : 3;
    }

    /** Immutable holder for a 2‑D point. */
    private record Point(int x, int y) {}
}

import java.io.*;
import java.util.*;

public class Main {

    /** Entry point – reads three points, solves the geometry problem and prints the result. */
    public static void main(String[] args) {
        try (FastScanner fs = new FastScanner(new InputStreamReader(System.in));
             FastPrintWriter out = new FastPrintWriter(new BufferedOutputStream(System.out))) {

            Point[] points = readPoints(fs);
            Arrays.sort(points);
            int answer = solve(points);
            out.println(answer);
        }
    }

    /** Reads exactly three points from the scanner. */
    private static Point[] readPoints(FastScanner fs) {
        Point[] pts = new Point[3];
        for (int i = 0; i < 3; i++) {
            long x = fs.nextLong();
            long y = fs.nextLong();
            pts[i] = new Point(x, y);
        }
        return pts;
    }

    /**
     * Implements the original solving algorithm with clearer variable names and
     * straightforward conditional flow.
     *
     * @return 1, 2 or 3 according to the geometry rules.
     */
    private static int solve(Point[] pts) {
        Point a = pts[0];
        Point b = pts[1];
        Point c = pts[2];

        // 1 – all three points are collinear horizontally or vertically
        if (areHorizontalCollinear(a, b, c) || areVerticalCollinear(a, b, c)) {
            return 1;
        }

        // a and b share the same X coordinate
        if (a.x == b.x) {
            // c lies strictly between a and b on the Y‑axis
            if (c.y < b.y && c.y > a.y) return 3;
            return 2;
        }

        // a and b share the same Y coordinate
        if (a.y == b.y) return 2;

        // Determine which of a.y / b.y is larger
        if (b.y < a.y) {
            // b is below a
            if (c.x == b.x) {
                // c is vertically aligned with b
                if (c.y <= a.y) return 2;   // c is at or below a
                return 3;                   // c is above a
            }
            if (c.y == b.y) return 2;
            return 3;
        }

        // b.y > a.y  (b is above a)
        if (c.x == b.x) return 2;
        if (c.y == b.y) return 2;
        return 3;
    }

    /** Utility methods for collinearity checks – keep the main algorithm readable. */
    private static boolean areHorizontalCollinear(Point a, Point b, Point c) {
        return a.y == b.y && b.y == c.y;
    }

    private static boolean areVerticalCollinear(Point a, Point b, Point c) {
        return a.x == b.x && b.x == c.x;
    }

    /** Simple point representation with natural (lexicographic) ordering. */
    private static final class Point implements Comparable<Point> {
        final long x;
        final long y;

        Point(long x, long y) {
            this.x = x;
            this.y = y;
        }

        @Override
        public int compareTo(Point o) {
            int cmp = Long.compare(this.x, o.x);
            if (cmp != 0) return cmp;
            return Long.compare(this.y, o.y);
        }
    }

    /** Fast scanner that tokenises input without the overhead of regular expressions. */
    private static final class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner(InputStreamReader in) {
            this.br = new BufferedReader(in);
        }

        /** Returns the next token as a {@code String}. */
        String next() throws IOException {
            while (st == null || !st.hasMoreElements()) {
                String line = br.readLine();
                if (line == null) throw new EOFException();
                st = new StringTokenizer(line);
            }
            return st.nextToken();
        }

        /** Convenience wrapper for reading a {@code long}. */
        long nextLong() throws IOException {
            return Long.parseLong(next());
        }
    }

    /** Fast printer that writes a line and flushes automatically. */
    private static final class FastPrintWriter extends PrintWriter {
        FastPrintWriter(OutputStream out) {
            super(out, true); // auto‑flush on println()
        }
    }
}

