import java.util.*;

/**
 * Refactored solution for the fence construction problem.
 * It reads three points per test case and computes the minimal number of
 * required fence segments according to the original algorithm.
 */
public class Main {

    // -----------------------------------------------------------------------
    // I/O helpers
    // -----------------------------------------------------------------------
    private static final FastReader INPUT = new FastReader();
    private static final PrintWriter OUTPUT = new PrintWriter(System.out);
    private static boolean DEBUG = false;

    public static void main(String[] args) throws IOException {
        run();
        OUTPUT.flush();
        if (DEBUG) {
            System.err.println("Execution time: " + (System.currentTimeMillis() - startTime) + " ms");
        }
    }

    private static long startTime = System.currentTimeMillis();

    private static void run() {
        // The original code only processes a single test case,
        // but the loop structure is kept for possible future extensions.
        int testCaseCount = 1;
        for (int tc = 1; tc <= testCaseCount; tc++) {
            processTestCase(tc);
        }
    }

    // -----------------------------------------------------------------------
    // Core logic
    // -----------------------------------------------------------------------
    /**
     * Reads three points (each point consists of an x and a y coordinate)
     * and determines the answer for the current test case.
     *
     * @param tc test case number (used only for debugging output)
     * @throws IOException if input reading fails
     */
    private static void processTestCase(int tc) throws IOException {
        int[] xs = new int[3];
        int[] ys = new int[3];

        for (int i = 0; i < 3; i++) {
            xs[i] = INPUT.nextInt();
            ys[i] = INPUT.nextInt();
        }

        // If all points share the same x-coordinate or the same y-coordinate,
        // exactly one fence segment is sufficient.
        if (allEqual(xs) || allEqual(ys)) {
            OUTPUT.println(1);
            return;
        }

        int minRequiredSegments = Integer.MAX_VALUE;

        // Evaluate each point as the "candidate" that may lie outside the
        // segment formed by the other two points.
        for (int excluded = 0; excluded < 3; excluded++) {
            int requiredSegments = computeRequiredSegments(xs, ys, excluded);
            minRequiredSegments = Math.min(minRequiredSegments, requiredSegments);
        }

        OUTPUT.println(minRequiredSegments);
    }

    /**
     * Determines whether all elements of the given array are equal.
     *
     * @param arr integer array to check
     * @return true if every element is equal, false otherwise
     */
    private static boolean allEqual(int[] arr) {
        for (int i = 1; i < arr.length; i++) {
            if (arr[i] != arr[0]) {
                return false;
            }
        }
        return true;
    }

    /**
     * Computes the required number of fence segments when the point at
     * {@code excluded} is considered the candidate that may lie outside the
     * line segment formed by the remaining two points.
     *
     * @param xs   x-coordinates of the three points
     * @param ys   y-coordinates of the three points
     * @param excluded index of the point to test as the candidate
     * @return 2 if the candidate requires only two segments,
     *         3 otherwise.
     */
    private static int computeRequiredSegments(int[] xs, int[] ys, int excluded) {
        // Identify the indices of the other two points
        int a = (excluded + 1) % 3;
        int b = (excluded + 2) % 3;

        // If the two base points are vertically aligned (same x)
        if (xs[a] == xs[b]) {
            int candidateY = ys[excluded];
            int minY = Math.min(ys[a], ys[b]);
            int maxY = Math.max(ys[a], ys[b]);

            // Candidate lies outside the vertical interval => only 2 segments needed
            if (candidateY <= minY || candidateY >= maxY) {
                trace("Vertical case: points", xs, ys, excluded);
                return 2;
            }
            return 3;
        }

        // If the two base points are horizontally aligned (same y)
        if (ys[a] == ys[b]) {
            int candidateX = xs[excluded];
            int minX = Math.min(xs[a], xs[b]);
            int maxX = Math.max(xs[a], xs[b]);

            if (candidateX <= minX || candidateX >= maxX) {
                trace("Horizontal case: points", xs, ys, excluded);
                return 2;
            }
            return 3;
        }

        // No special alignment => 3 segments are required.
        return 3;
    }

    // -----------------------------------------------------------------------
    // Debug helper
    // -----------------------------------------------------------------------
    private static void trace(Object... objs) {
        if (!DEBUG) {
            return;
        }
        System.err.println(Arrays.deepToString(objs));
    }

    // -----------------------------------------------------------------------
    // Fast input utilities
    // -----------------------------------------------------------------------
    /**
     * Simple fast scanner based on {@link BufferedReader} and {@link StringTokenizer}.
     */
    private static final class FastReader {
        private final BufferedReader br;
        private StringTokenizer st;

        FastReader() {
            this.br = new BufferedReader(new InputStreamReader(System.in));
        }

        /** Returns the next token as an {@code int}. */
        int nextInt() throws IOException {
            while (st == null || !st.hasMoreElements()) {
                st = new StringTokenizer(br.readLine());
            }
            return Integer.parseInt(st.nextToken());
        }
    }
}

