/**
 * Determines the minimal number of axis‑aligned segments required
 * to connect three distinct points.
 *
 * The algorithm works as follows:
 * <ul>
 *   <li>If all three points share the same X coordinate or the same Y coordinate,
 *       they are already aligned → 1 segment.</li>
 *   <li>If exactly two points share a coordinate (vertical or horizontal),
 *       and the third point's orthogonal coordinate lies strictly between the
 *       other two, an “L‑shape” can be formed using three segments → 3.</li>
 *   <li>Otherwise, a connection can always be achieved with only two segments → 2.</li>
 * </ul>
 */
public class CodefrocesD {

    /** Fast input helper that mimics the original Scanner behaviour. */
    private static final class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner(InputStream source) {
            br = new BufferedReader(new InputStreamReader(source));
            st = null;
        }

        /** Returns the next token (a word) or reads a new line if none are left. */
        private String nextToken() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                String line = br.readLine();
                if (line == null) {
                    return null;
                }
                st = new StringTokenizer(line);
            }
            return st.nextToken();
        }

        /** Convenience wrappers for primitive types. */
        int nextInt() throws IOException {
            return Integer.parseInt(nextToken());
        }

        long nextLong() throws IOException {
            return Long.parseLong(nextToken());
        }

        /** Returns the rest of the line (including possible trailing spaces). */
        String nextLine() throws IOException {
            return br.readLine();
        }

        boolean ready() throws IOException {
            return br.ready();
        }
    }

    /** Entry point of the program. */
    public static void main(String[] args) throws IOException {
        FastScanner fs = new FastScanner(System.in);

        // Read the six integers that describe the three points.
        int x1 = fs.nextInt();
        int y1 = fs.nextInt();
        int x2 = fs.nextInt();
        int y2 = fs.nextInt();
        int x3 = fs.nextInt();
        int y3 = fs.nextInt();

        int answer = solve(x1, y1, x2, y2, x3, y3);
        System.out.println(answer);
    }

    /**
     * Calculates the minimal number of axis‑aligned segments needed
     * to join the three supplied points.
     *
     * @param x1 Y‑coordinate of point 1
     * @param y1 X‑coordinate of point 1
     * @param x2 Y‑coordinate of point 2
     * @param y2 X‑coordinate of point 2
     * @param x3 Y‑coordinate of point 3
     * @param y3 X‑coordinate of point 3
     * @return 1, 2 or 3 depending on the geometry of the points
     */
    private static int solve(int x1, int y1, int x2, int y2, int x3, int y3) {
        // 1️⃣ All three points share the same X → vertical line.
        if (x1 == x2 && x2 == x3) {
            return 1;
        }

        // 2️⃣ All three points share the same Y → horizontal line.
        if (y1 == y2 && y2 == y3) {
            return 1;
        }

        // Helper to test if a value lies strictly between two others.
        java.util.function.IntPredicate between = (v, a, b) -> v > Math.min(a, b) && v < Math.max(a, b);

        // -----------------------------------------------------------------
        // Cases where two points share a coordinate.
        // -----------------------------------------------------------------

        // Two vertical points (same X) → check Y of the third point.
        if (x1 == x2) {
            return between.test(y3, Math.min(y1, y2), Math.max(y1, y2)) ? 3 : 2;
        }
        // Two vertical points (x2, x3) → check Y of point 1.
        if (x2 == x3) {
            return between.test(y1, Math.min(y2, y3), Math.max(y2, y3)) ? 3 : 2;
        }
        // Two vertical points (x1, x3) → check Y of point 2.
        if (x1 == x3) {
            return between.test(y2, Math.min(y1, y3), Math.max(y1, y3)) ? 3 : 2;
        }

        // Two horizontal points (same Y) → check X of the third point.
        if (y1 == y2) {
            return between.test(x3, Math.min(x1, x2), Math.max(x1, x2)) ? 3 : 2;
        }
        if (y2 == y3) {
            return between.test(x1, Math.min(x2, x3), Math.max(x2, x3)) ? 3 : 2;
        }
        if (y1 == y3) {
            return between.test(x2, Math.min(x1, x3), Math.max(x1, x3)) ? 3 : 2;
        }

        // No two points share a coordinate → a 2‑segment solution always exists.
        return 3;
    }
}

import java.io.BufferedInputStream;
import java.util.Scanner;

/**
 * Geometry utilities for checking the relative position of three points.
 *
 * <p>Each point is represented by two integer coordinates.
 * The program reads six integers from standard input:
 * <pre>
 *   x1 y1 x2 y2 x3 y3
 * </pre>
 * and prints one of the following:
 * <ul>
 *   <li><b>1</b> – all points share the same {@code x} or the same {@code y}
 *       (i.e. they are collinear on a vertical or horizontal line).</li>
 *   <li><b>2</b> – one of the points lies strictly between the other two
 *       on a line that has a constant {@code x} or {@code y}.</li>
 *   <li><b>3</b> – otherwise (the three points form a non‑degenerate triangle).</li>
 * </ul>
 *
 * <p>All logic is isolated in small, well‑named methods, which makes the
 * program easy to test and to extend.
 */
public class Main {

    /** Simple wrapper around {@link Scanner} that reads only integers. */
    private static final class FastInput {
        private static final Scanner SCANNER = new Scanner(new BufferedInputStream(System.in));

        /** Reads the next integer from the input stream. */
        static int nextInt() {
            return SCANNER.nextInt();
        }
    }

    /**
     * Determines whether the three points are collinear on a vertical or
     * horizontal line. In that case the answer is {@code 1}.
     *
     * @param x1, y1 coordinates of the first point
     * @param x2, y2 coordinates of the second point
     * @param x3, y3 coordinates of the third point
     * @return {@code true} if all x's are equal or all y's are equal
     */
    private static boolean isLineVerticalOrHorizontal(int x1, int y1,
                                                       int x2, int y2,
                                                       int x3, int y3) {
        return (x1 == x2 && x2 == x3) || (y1 == y2 && y2 == y3);
    }

    /**
     * Checks whether a point {@code (px, py)} lies between the other two points
     * on a line that is either vertical or horizontal.
     *
     * @param px, py coordinates of the candidate point
     * @param ax, ay coordinates of the first reference point
     * @param bx, by coordinates of the second reference point
     * @return {@code true} if {@code (px,py)} is strictly between the other two
     */
    private static boolean isBetween(int px, int py,
                                     int ax, int ay,
                                     int bx, int by) {
        // The line must be either vertical or horizontal – the caller guarantees this.
        if (ax == bx) {                     // vertical line (x constant)
            return px == ax &&
                   ((py > Math.min(ay, by)) && (py < Math.max(ay, by)));
        } else {                            // horizontal line (y constant)
            return py == ay &&
                   ((px > Math.min(ax, bx)) && (px < Math.max(ax, bx)));
        }
    }

    /**
     * Returns {@code 2} if one of the points is located strictly between the
     * other two on a line with constant x or y, otherwise {@code 0}.
     *
     * @return 2 if a point is between the others, 0 otherwise
     */
    private static int checkIntermediatePoint(int x1, int y1,
                                               int x2, int y2,
                                               int x3, int y3) {
        // vertical candidates
        if (x1 == x2) {
            if (isBetween(y1, x1, x3, y3, x1, y1) ||
                isBetween(y3, x3, x1, y1, x2, y2)) {
                return 2;
            }
        }
        if (x1 == x3) {
            if (isBetween(y1, x1, x2, y2, x1, y1) ||
                isBetween(y2, x2, x1, y1, x3, y3)) {
                return 2;
            }
        }
        if (x2 == x3) {
            if (isBetween(y2, x2, x1, y1, x2, y2) ||
                isBetween(y1, x1, x3, y3, x2, y2)) {
                return 2;
            }
        }
        // horizontal candidates
        if (y1 == y2) {
            if (isBetween(x1, y1, x3, y3, x1, y1) ||
                isBetween(x3, y3, x1, y1, x2, y2)) {
                return 2;
            }
        }
        if (y1 == y3) {
            if (isBetween(x1, y1, x2, y2, x1, y1) ||
                isBetween(x2, y2, x1, y1, x3, y3)) {
                return 2;
            }
        }
        if (y2 == y3) {
            if (isBetween(x2, y2, x1, y1, x2, y2) ||
                isBetween(x1, y1, x3, y3, x2, y2)) {
                return 2;
            }
        }
        return 0;
    }

    /** Entry point of the program. */
    public static void main(String[] args) {
        // Read the six integers that describe three points
        int x1 = FastInput.nextInt();
        int y1 = FastInput.nextInt();
        int x2 = FastInput.nextInt();
        int y2 = FastInput.nextInt();
        int x3 = FastInput.nextInt();
        int y3 = FastInput.nextInt();

        // 1️⃣  All points share the same x or the same y → output 1
        if (isLineVerticalOrHorizontal(x1, y1, x2, y2, x3, y3)) {
            System.out.println(1);
            return;
        }

        // 2️⃣  One point is strictly between the other two on a line → output 2
        if (checkIntermediatePoint(x1, y1, x2, y2, x3, y3) == 2) {
            System.out.println(2);
            return;
        }

        // 3️⃣  Otherwise the three points form a non‑degenerate triangle → output 3
        System.out.println(3);
    }
}

import java.io.*;
import java.util.*;
import java.util.function.Function;
import java.util.stream.Collectors;

/**
 * Refactored version of the original program.
 *
 * The program reads three points (each point on a separate line as "x y"),
 * analyses the distribution of the x‑ and y‑coordinates and prints:
 *
 *   1 – all points share the same x or the same y,
 *   2 – the isolated point lies outside the min–max range of the others,
 *   3 – any other configuration.
 *
 * The refactor focuses on readability, maintainability and separation of concerns.
 */
public class P617D {

    /* --------------------------------------------------------------
     *  I/O constants – keep a single source of truth for streams.
     * -------------------------------------------------------------- */
    private static final BufferedReader IN = new BufferedReader(
            new InputStreamReader(System.in));
    private static final PrintWriter OUT = new PrintWriter(new BufferedWriter(
            new OutputStreamWriter(System.out)));

    /* --------------------------------------------------------------
     *  Entry point
     * -------------------------------------------------------------- */
    public static void main(String[] args) throws IOException {
        List<Point> points = readPoints();
        OUT.println(determineResult(points));
        OUT.close();
    }

    /* --------------------------------------------------------------
     *  Input handling
     * -------------------------------------------------------------- */
    private static List<Point> readPoints() throws IOException {
        List<Point> points = new ArrayList<>(3);
        for (int i = 0; i < 3; i++) {
            String[] tokens = IN.readLine().split("\\s+");
            int x = Integer.parseInt(tokens[0]);
            int y = Integer.parseInt(tokens[1]);
            points.add(new Point(x, y));
        }
        return points;
    }

    /* --------------------------------------------------------------
     *  Core algorithm
     * -------------------------------------------------------------- */
    private static int determineResult(List<Point> pts) {
        Map<Integer, Integer> freqX = frequency(extract(pts, Point::getX));
        Map<Integer, Integer> freqY = frequency(extract(pts, Point::getY));

        int distinctX = freqX.size();
        int distinctY = freqY.size();

        // 1 – all points lie on a vertical or a horizontal line
        if (distinctX == 1 || distinctY == 1) {
            return 1;
        }
        // 2 – exactly two distinct x-values and exactly two distinct y-values
        if (distinctX == 2 && distinctY == 2) {
            return 2;
        }
        // Cases where the distribution of one coordinate has size 2
        if (distinctX == 2) {
            return analyzeTwoXCase(pts);
        }
        if (distinctY == 2) {
            return analyzeTwoYCase(pts);
        }
        // Default outcome for any other configuration
        return 3;
    }

    /** Counts occurrences of each integer in the supplied list. */
    private static Map<Integer, Integer> frequency(List<Integer> values) {
        Map<Integer, Integer> map = new HashMap<>();
        for (int v : values) {
            map.merge(v, 1, Integer::sum);
        }
        return map;
    }

    /** Extracts a property (e.g. x or y) from every point in the list. */
    private static <T> List<T> extract(List<Point> points, Function<Point, T> getter) {
        return points.stream().map(getter).toList();
    }

    /* --------------------------------------------------------------
     *  Specialized handling for the two‑distinct‑x case
     * -------------------------------------------------------------- */
    private static int analyzeTwoXCase(List<Point> pts) {
        Point isolated = findIsolatedByX(pts);
        int isolatedY = isolated.y;

        int lowY = minYOfSharedX(pts, isolated.x);
        int highY = maxYOfSharedX(pts, isolated.x);

        return (isolatedY > highY || isolatedY < lowY) ? 2 : 3;
    }

    /** Returns the point whose x‑value occurs only once. */
    private static Point findIsolatedByX(List<Point> pts) {
        Map<Integer, List<Point>> byX = pts.stream()
                .collect(Collectors.groupingBy(Point::getX));

        for (List<Point> group : byX.values()) {
            if (group.size() == 1) {
                return group.get(0);
            }
        }
        // The input guarantees a singleton group exists
        return pts.get(0);
    }

    /** Finds the minimum y among points sharing a given x‑value. */
    private static int minYOfSharedX(List<Point> pts, int sharedX) {
        return pts.stream()
                .filter(p -> p.x == sharedX)
                .mapToInt(Point::y)
                .min()
                .orElseThrow();
    }

    /** Finds the maximum y among points sharing a given x‑value. */
    private static int maxYOfSharedX(List<Point> pts, int sharedX) {
        return pts.stream()
                .filter(p -> p.x == sharedX)
                .mapToInt(Point::y)
                .max()
                .orElseThrow();
    }

    /* --------------------------------------------------------------
     *  Specialized handling for the two‑distinct‑y case (symmetric)
     * -------------------------------------------------------------- */
    private static int analyzeTwoYCase(List<Point> pts) {
        Point isolated = findIsolatedByY(pts);
        int isolatedX = isolated.x;

        int lowX = minXOfSharedY(pts, isolated.y);
        int highX = maxXOfSharedY(pts, isolated.y);

        return (isolatedX > highX || isolatedX < lowX) ? 2 : 3;
    }

    /** Returns the point whose y‑value occurs only once. */
    private static Point findIsolatedByY(List<Point> pts) {
        Map<Integer, List<Point>> byY = pts.stream()
                .collect(Collectors.groupingBy(Point::getY));

        for (List<Point> group : byY.values()) {
            if (group.size() == 1) {
                return group.get(0);
            }
        }
        return pts.get(0); // fallback – should never be reached for valid input
    }

    /** Finds the minimum x among points sharing a given y‑value. */
    private static int minXOfSharedY(List<Point> pts, int sharedY) {
        return pts.stream()
                .filter(p -> p.y == sharedY)
                .mapToInt(Point::x)
                .min()
                .orElseThrow();
    }

    /** Finds the maximum x among points sharing a given y‑value. */
    private static int maxXOfSharedY(List<Point> pts, int sharedY) {
        return pts.stream()
                .filter(p -> p.y == sharedY)
                .mapToInt(Point::x)
                .max()
                .orElseThrow();
    }

    /* --------------------------------------------------------------
     *  Simple immutable holder for a coordinate pair.
     * -------------------------------------------------------------- */
    private static final class Point {
        private final int x;
        private final int y;

        Point(int x, int y) {
            this.x = x;
            this.y = y;
        }

        int getX() { return x; }
        int getY() { return y; }
    }
}

import java.io.*;
import java.util.*;

/**
 * Solution for the problem where we have to decide whether three
 * points lie on a vertical/horizontal line or whether we can adjust
 * one coordinate to obtain a line of three equal projections.
 *
 * The refactor aims at readability, maintainability and extensibility:
 * <ul>
 *   <li>Logical parts are extracted into small, well‑named methods.</li>
 *   <li>Descriptive variable names replace the cryptic original ones.</li>
 *   <li>Magic numbers are replaced by constants or enums.</li>
 *   <li>All I/O handling is confined to {@link InputReader} and {@link OutputWriter}.</li>
 *   <li>Static imports are avoided – explicit imports make the code clearer.</li>
 * </ul>
 */
public class Main {

    /** The writer used to output answers. */
    private static PrintWriter out;

    /** The reader used to gather input from {@code System.in}. */
    private static InputReader in;

    public static void main(String[] args) throws Exception {
        in = new InputReader(System.in);
        out = new PrintWriter(System.out, true);
        solve();
        out.flush();
    }

    /**
     * Main logic: reads three points, analyses them and prints
     * 1, 2 or 3 according to the problem statement.
     */
    private static void solve() {
        // read three points
        Point[] points = readThreePoints();

        // check the trivial case where all x‑ or y‑coordinates are equal
        if (isAllXCoordinatesEqual(points) || isAllYCoordinatesEqual(points)) {
            out.println(1);
            return;
        }

        // analyse each dimension (x‑ and y‑axis) separately
        for (Axis axis : Axis.values()) {
            if (containsIdenticalCoordinate(points, axis)) {
                Pair pair = findPairWithDuplicate(axis);
                int otherIdx = otherIndex(pair.first, pair.second);
                Point other = points[otherIdx];

                // verify that the duplicate value is *outside* the interval
                // defined by the two other points on the remaining axis
                if (isStrictlyOutsideInterval(pair, axis, other)) {
                    out.println(3);
                } else {
                    out.println(2);
                }
                return;
            }
        }

        // if we reached this point, no earlier case matched
        out.println(3);
    }

    /** Helper that reads three points, each consisting of two integers. */
    private static Point[] readThreePoints() {
        Point[] pts = new Point[3];
        for (int i = 0; i < 3; i++) {
            pts[i] = new Point(in.nextInt(), in.nextInt());
        }
        return pts;
    }

    /** Returns true when all three points share the same x‑coordinate. */
    private static boolean isAllXCoordinatesEqual(Point[] pts) {
        return pts[0].x == pts[1].x && pts[1].x == pts[2].x;
    }

    /** Returns true when all three points share the same y‑coordinate. */
    private static boolean isAllYCoordinatesEqual(Point[] pts) {
        return pts[0].y == pts[1].y && pts[1].y == pts[2].y;
    }

    /** Axis enum – makes the code self‑documenting. */
    private enum Axis {
        X('x'), Y('y');

        private final char label;

        Axis(char label) {
            this.label = label;
        }

        char label() {
            return label;
        }
    }

    /**
     * Checks whether the given axis contains at least one pair of points
     * with equal coordinate value.
     */
    private static boolean containsIdenticalCoordinate(Point[] pts, Axis axis) {
        char coord = axis.label();
        return (coord == 'x' && pts[0].x == pts[1].x || pts[0].x == pts[2].x || pts[1].x == pts[2].x)
                || (coord == 'y' && pts[0].y == pts[1].y || pts[0].y == pts[2].y || pts[1].y == pts[2].y);
    }

    /**
     * Finds the first pair of points that share the same coordinate on the
     * supplied axis and returns their indices.
     */
    private static Pair findPairWithDuplicate(Axis axis) {
        char coord = axis.label();
        for (int i = 0; i < 3; i++) {
            for (int j = i + 1; j < 3; j++) {
                if (sameCoordinateOnAxis(i, j, axis)) {
                    return new Pair(i, j);
                }
            }
        }
        throw new IllegalStateException("No duplicate coordinate found on axis " + axis);
    }

    /** Returns true if points {@code i} and {@code j} have equal coordinate on {@code axis}. */
    private static boolean sameCoordinateOnAxis(int i, int j, Axis axis) {
        return switch (axis) {
            case X -> points[i].x == points[j].x;
            case Y -> points[i].y == points[j].y;
        };
    }

    /** Returns the index of the third point that is not part of {@code pair}. */
    private static int otherIndex(int a, int b) {
        for (int i = 0; i < 3; i++) {
            if (i != a && i != b) {
                return i;
            }
        }
        throw new IllegalStateException("Unexpected indices");
    }

    /** Determines whether the value on the complementary axis for {@code other} lies outside
     * the interval defined by the duplicate pair. */
    private static boolean isStrictlyOutsideInterval(Pair pair, Axis axis, Point other) {
        // Choose the coordinate on the complementary axis of the duplicate pair
        char dupCoordChar = axis.label();
        char otherCoordChar = complementaryCoordinate(dupCoordChar);

        int dupValue = getCoordinateOnAxis(pair.first, dupCoordChar);
        int otherValue = getCoordinate(other, otherCoordChar);
        int thirdValue = getCoordinate(points[otherIndex(pair.first, pair.second)], otherCoordChar);

        // Cast to long to avoid overflow during multiplication
        long diff1 = (long) dupValue - otherValue;
        long diff2 = (long) otherValue - thirdValue;
        return diff1 * diff2 > 0; // strictly outside the interval
    }

    /** Returns the coordinate of {@code p} on the given axis (either 'x' or 'y'). */
    private static int getCoordinate(Point p, char axis) {
        return switch (axis) {
            case 'x' -> p.x;
            case 'y' -> p.y;
            default -> throw new IllegalArgumentException("Invalid axis: " + axis);
        };
    }

    /** Returns the complementary axis character (e.g. 'x' → 'y'). */
    private static char complementaryCoordinate(char axis) {
        return (axis == 'x') ? 'y' : 'x';
    }

    /** Utility class that holds a pair of integer indices. */
    private static final class Pair {
        final int first;
        final int second;

        Pair(int first, int second) {
            this.first = first;
            this.second = second;
        }
    }

    /** Represents a 2‑dimensional point with integer coordinates. */
    private static final class Point {
        final int x;
        final int y;

        Point(int x, int y) {
            this.x = x;
            this.y = y;
        }
    }
}

