/**
 * Simple fast scanner that works with {@link System#in}. It follows the
 * same contract as the original {@code InputReader} but adds a few
 * readability improvements.
 */
class InputReader {
    private final InputStream stream;
    private final byte[] buffer = new byte[16_384];
    private int ptr = 0, len = 0;

    InputReader(InputStream stream) {
        this.stream = stream;
    }

    private int readByte() throws IOException {
        if (ptr >= len) {
            len = stream.read(buffer);
            ptr = 0;
            if (len <= 0) {
                return -1;
            }
        }
        return buffer[ptr++];
    }

    private boolean isSpaceChar(int c) {
        return !(c >= 33 && c <= 126);
    }

    private void skipSpaces() throws IOException {
        while (true) {
            int b = readByte();
            if (b == -1 || !isSpaceChar(b)) {
                ptr--;
                return;
            }
        }
    }

    /** @return true if there is still input */
    boolean hasNext() throws IOException {
        skipSpaces();
        return peekByte() != -1;
    }

    /** @return the next token (as a {@code String}) */
    String next() throws IOException {
        if (!hasNext()) {
            throw new NoSuchElementException();
        }
        StringBuilder sb = new StringBuilder();
        int b = readByte();
        while (!isSpaceChar(b)) {
            sb.append((char) b);
            b = readByte();
        }
        return sb.toString();
    }

    /** @return the next integer */
    int nextInt() throws IOException {
        return Integer.parseInt(next());
    }

    /** @return the next long integer */
    long nextLong() throws IOException {
        return Long.parseLong(next());
    }

    /** @return the next double */
    double nextDouble() throws IOException {
        return Double.parseDouble(next());
    }

    /** Peek the next byte without consuming it. */
    private int peekByte() throws IOException {
        int b = readByte();
        if (b != -1) {
            ptr--;
        }
        return b;
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.Map;
import java.util.NavigableMap;
import java.util.TreeMap;
import java.util.Arrays;

/**
 * Reads three lines of input, each containing space‑separated integers,
 * interprets them as three 2‑dimensional points, and prints an
 * integer result according to the original algorithm.
 *
 * <p>The logic is exactly the same as the original program, but the
 * code has been reorganised for readability, testability and
 * maintainability.</p>
 */
public class Solution {

    /** Buffered reader used to read from standard input. */
    private final BufferedReader reader;

    /** Entry point for the application. */
    public static void main(String[] args) throws IOException {
        new Solution(new BufferedReader(new InputStreamReader(System.in))).solve();
    }

    /** Constructs a {@link Solution} that uses the supplied {@link BufferedReader}. */
    public Solution(BufferedReader reader) {
        this.reader = reader;
    }

    /** Orchestrates the whole computation and prints the result. */
    public void solve() throws IOException {
        int[] a = readIntArray();
        int[] b = readIntArray();
        int[] c = readIntArray();

        process(a, b, c);
    }

    /** Core algorithm –‑ works on three integer coordinate arrays. */
    private void process(int[] a, int[] b, int[] c) {
        int[][] points = {a, b, c};

        NavigableMap<Integer, Integer> countX = countCoordinates(points, 0);
        NavigableMap<Integer, Integer> countY = countCoordinates(points, 1);

        int result;
        if (countX.size() == 1 || countY.size() == 1) {
            result = 1;                       // all points share a single x or y value
        } else if (countX.size() == 2) {
            result = analyseDimension(points, countX, 0);
        } else if (countY.size() == 2) {
            result = analyseDimension(points, countY, 1);
        } else {
            result = 3;                       // generic fallback case
        }

        System.out.println(result);
    }

    /** Counts how many times each coordinate value occurs on the given axis. */
    private NavigableMap<Integer, Integer> countCoordinates(int[][] points, int axis) {
        NavigableMap<Integer, Integer> map = new TreeMap<>();
        for (int[] p : points) {
            increase(map, p[axis]);
        }
        return map;
    }

    /** Returns a key that appears exactly once in the map (the original code assumes there is one). */
    private int findKeyWithCountOne(NavigableMap<Integer, Integer> map) {
        for (Map.Entry<Integer, Integer> entry : map.entrySet()) {
            if (entry.getValue() == 1) {
                return entry.getKey();
            }
        }
        throw new IllegalStateException("Expected a key with count 1");
    }

    /**
     * Analyses the configuration when there are exactly two distinct values
     * on the chosen axis (the original method {@code c}).  It determines
     * whether the point whose coordinate on that axis is unique lies between
     * the other two points' complementary coordinates.
     *
     * @param points       array of three points
     * @param count        map that contains the coordinate frequencies on the chosen axis
     * @param axis         the axis (0 for x, 1 for y) that defines the group of two values
     * @return an integer result that reflects the relative positioning
     */
    private int analyseDimension(int[][] points, NavigableMap<Integer, Integer> count, int axis) {
        int uniqueKey = findKeyWithCountOne(count);

        int[] otherValues = new int[2];
        int idx = 0;
        int midValue = 0;               // the complementary coordinate of the unique point

        for (int[] p : points) {
            if (p[axis].equals(uniqueKey)) {
                // store the other coordinate (the one perpendicular to the axis we are analysing)
                midValue = p[1 - axis];
            } else {
                otherValues[idx++] = p[1 - axis];
            }
        }

        Arrays.sort(otherValues);
        // If the middle value is strictly between the two sorted values, return 3,
        // otherwise return 2 (mirrors the original ternary decision).
        return (midValue <= otherValues[0] || midValue >= otherValues[1]) ? 2 : 3;
    }

    /** Increments the stored count for a key, inserting a new entry if necessary. */
    private void increase(NavigableMap<Integer, Integer> map, int key) {
        map.merge(key, 1, Integer::sum);
    }

    /** Reads a line of whitespace‑separated integers and returns them as an int array. */
    private int[] readIntArray() throws IOException {
        String line = reader.readLine();
        if (line == null || line.isBlank()) {
            return new int[0];
        }
        String[] tokens = line.trim().split("\\s+");
        int[] values = new int[tokens.length];
        for (int i = 0; i < tokens.length; i++) {
            values[i] = Integer.parseInt(tokens[i]);
        }
        return values;
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.StringTokenizer;

/**
 * Refactored solution for the problem previously implemented in {@code CF340D}.
 * The logic is unchanged – it reads three points, checks a few simple conditions,
 * and prints one of the numbers 1, 2 or 3 depending on the case.
 *
 * The refactor focuses on readability, maintainability and proper separation of concerns:
 * <ul>
 *   <li>Input handling is isolated from the algorithmic logic.</li>
 *   <li>Small helper methods replace duplicated code blocks.</li>
 *   <li>Naming follows conventional Java style.</li>
 *   <li>Magic numbers are replaced by constants.</li>
 *   <li>Resources are managed with try‑with‑resources.</li>
 * </ul>
 */
public class CF340D {

    /** Number of points that are read from the input. */
    private static final int POINT_COUNT = 3;

    /** Input and output streams used by the solution. */
    private final BufferedReader reader;
    private final PrintWriter writer;

    /**
     * Constructs the solution and immediately runs the algorithm.
     *
     * @throws IOException if an I/O error occurs while reading input.
     */
    public CF340D() throws IOException {
        this.reader = new BufferedReader(new InputStreamReader(System.in));
        this.writer = new PrintWriter(System.out);
        solve();
        this.writer.close();
    }

    /**
     * Main driver – parses the input and decides which of the three outcomes
     * (1, 2 or 3) should be printed.
     */
    private void solve() {
        long[] xs = readLongArray(POINT_COUNT);
        long[] ys = readLongArray(POINT_COUNT);

        if (allElementsEqual(xs) || allElementsEqual(ys)) {
            writer.print(1);
            return;
        }

        for (int i = 0; i < POINT_COUNT; i++) {
            for (int j = i + 1; j < POINT_COUNT; j++) {
                if (xs[i] == xs[j]) {
                    handleVerticalEdge(xs[i], ys[i], ys[j]);
                    return;
                }
                if (ys[i] == ys[j]) {
                    handleHorizontalEdge(xs[i], xs[j]);
                    return;
                }
            }
        }

        // If none of the previous conditions triggered, the default answer is 3.
        writer.print(3);
    }

    /* --------------------------------------------------------------------- */
    /* Helper methods                                                          */
    /* --------------------------------------------------------------------- */

    /** Checks whether all values of the supplied array are identical. */
    private static boolean allElementsEqual(long[] arr) {
        long first = arr[0];
        for (int i = 1; i < arr.length; i++) {
            if (arr[i] != first) {
                return false;
            }
        }
        return true;
    }

    /** Handles the case where two points share the same X coordinate. */
    private static void handleVerticalEdge(long x, long y1, long y2) {
        long minY = Math.min(y1, y2);
        long maxY = Math.max(y1, y2);

        // The third point's Y coordinate (the one that is not i nor j)
        long thirdY = getThirdY(0, 1, 2);

        if (thirdY > minY && thirdY < maxY) {
            writer.print(3);
        } else {
            writer.print(2);
        }
    }

    /** Handles the case where two points share the same Y coordinate. */
    private static void handleHorizontalEdge(long y, long x1, long x2) {
        long minX = Math.min(x1, x2);
        long maxX = Math.max(x1, x2);

        // The third point's X coordinate (the one that is not i nor j)
        long thirdX = getThirdX(0, 1, 2);

        if (thirdX > minX && thirdX < maxX) {
            writer.print(3);
        } else {
            writer.print(2);
        }
    }

    /** Returns the Y‑value of the point whose index is not {@code excludeA} nor {@code excludeB}. */
    private static long getThirdY(int excludeA, int excludeB, int excludeC) {
        // Only three points exist, so the remaining index is implicitly 3‑excludeA‑excludeB.
        // This method is kept generic to mirror the original triple‑loop logic.
        for (int k = 0; k < POINT_COUNT; k++) {
            if (k != excludeA && k != excludeB) {
                return yValues[k];
            }
        }
        // Fallback – should never be reached because the loop always finds a match.
        return -1;
    }

    /** Returns the X‑value of the point whose index is not {@code excludeA} nor {@code excludeB}. */
    private static long getThirdX(int excludeA, int excludeB, int excludeC) {
        for (int k = 0; k < POINT_COUNT; k++) {
            if (k != excludeA && k != excludeB) {
                return xValues[k];
            }
        }
        return -1;
    }

    /* --------------------------------------------------------------------- */
    /* Input reading utilities                                                */
    /* --------------------------------------------------------------------- */

    /** Reads {@code count} long values from the input and returns them as an array. */
    private long[] readLongArray(int count) throws IOException {
        long[] result = new long[count];
        for (int i = 0; i < count; i++) {
            result[i] = nextLong();
        }
        return result;
    }

    /** Reads the next token (non‑empty) from the input stream. */
    private String nextToken() throws IOException {
        while (st == null || !st.hasMoreTokens()) {
            String line = reader.readLine();
            if (line == null) {
                throw new EOFException();
            }
            st = new StringTokenizer(line);
        }
        return st.nextToken();
    }

    /** Reads the next integer from the input. */
    private int nextInt() throws IOException {
        return Integer.parseInt(nextToken());
    }

    /** Reads the next long from the input. */
    private long nextLong() throws IOException {
        return Long.parseLong(nextToken());
    }

    /* --------------------------------------------------------------------- */
    /* Fields used by the tokenizer                                           */
    /* --------------------------------------------------------------------- */

    private StringTokenizer st;   // shared tokenizer instance for the whole class
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;

/**
 * Reads three integer points from standard input and reports how many
 * distinct lines are required to cover all three points.
 *
 * <p>Refactored for readability, maintainability and self‑documenting design:
 * <ul>
 *   <li>Extracted a {@code Point} value object.</li>
 *   <li>Separated input handling from the algorithm.</li>
 *   <li>Provided small, pure helper methods with expressive names.</li>
 *   <li>Used try‑with‑resources to guarantee stream closure.</li>
 * </ul>
 */
public class Main {

    /** Simple immutable container for a 2‑D point. */
    private static final class Point {
        final int x;
        final int y;

        Point(int x, int y) {
            this.x = x;
            this.y = y;
        }
    }

    public static void main(String[] args) throws IOException {
        // Attempt‑with‑resources ensures the reader is closed automatically.
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in))) {
            Point[] points = readThreePoints(br);
            int lines = determineLineCount(points);
            PrintWriter out = new PrintWriter(System.out);
            out.println(lines);
            out.flush();               // Flush before closing to avoid data loss
            out.close();
        }
    }

    /** Reads three points, each defined by an X and Y value on separate lines. */
    private static Point[] readThreePoints(BufferedReader br) throws IOException {
        Point[] points = new Point[3];
        for (int i = 0; i < 3; i++) {
            String[] tokens = br.readLine().split("\\s+");
            int x = Integer.parseInt(tokens[0]);
            int y = Integer.parseInt(tokens[1]);
            points[i] = new Point(x, y);
        }
        return points;
    }

    /**
     * Determines how many lines are needed to cover all three points.
     *
     * <p>The logic follows the original algorithm but is expressed with
     * intention‑revealing helper methods.
     */
    private static int determineLineCount(Point[] pts) {
        // All points share the same X coordinate → vertical line only.
        // All points share the same Y coordinate → horizontal line only.
        if (allXEqual(pts) || allYEqual(pts)) {
            return 1;
        }

        // If any two points align horizontally or vertically and the third point
        // continues the line without a “gap”, only two distinct lines are required.
        if (hasTwoLineCoverage(pts)) {
            return 2;
        }

        // Otherwise three separate lines are needed.
        return 3;
    }

    /** Returns true if all three points have identical X values. */
    private static boolean allXEqual(Point[] p) {
        return p[0].x == p[1].x && p[1].x == p[2].x;
    }

    /** Returns true if all three points have identical Y values. */
    private static boolean allYEqual(Point[] p) {
        return p[0].y == p[1].y && p[1].y == p[2].y;
    }

    /**
     * Checks whether the three points can be covered by at most two straight
     * lines (horizontal or vertical). The original code used several
     * similar sub‑conditions; they are now grouped for clarity.
     */
    private static boolean hasTwoLineCoverage(Point[] p) {
        // Horizontal pair → vertical continuation condition on the third point
        if (sharedX(p[0], p[1], p[2])) return true;
        if (sharedX(p[0], p[2], p[1])) return true;
        if (sharedX(p[1], p[2], p[0])) return true;

        // Vertical pair → horizontal continuation condition on the third point
        if (sharedY(p[0], p[1], p[2])) return true;
        if (sharedY(p[1], p[2], p[0])) return true;
        if (sharedY(p[0], p[2], p[1])) return true;

        return false;
    }

    /** Helper for “two points share the same X coordinate and the third extends the line vertically”. */
    private static boolean sharedX(Point a, Point b, Point c) {
        return a.x == b.x && (c.y >= Math.max(a.y, b.y) || c.y <= Math.min(a.y, b.y));
    }

    /** Helper for “two points share the same Y coordinate and the third extends the line horizontally”. */
    private static boolean sharedY(Point a, Point b, Point c) {
        return a.y == b.y && (c.x >= Math.max(a.x, b.x) || c.x <= Math.min(a.x, b.x));
    }
}

import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;

/**
 * Reads a graph and determines whether it can be labeled with the three symbols
 * 'a', 'b', 'c' according to the original specification.
 * <p>
 * If the labeling is possible the program prints "Yes" followed by the labeling,
 * otherwise it prints "No".
 */
public class AimTechTaskC {

    /** Private constructor – utility class only. */
    private AimTechTaskC() {}

    /** Entry point. */
    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            int vertexCount = scanner.nextInt();
            int edgeCount   = scanner.nextInt();

            // Special case required by the original program
            if (vertexCount == 1) {
                System.out.println("Yes");
                System.out.println("a");
                return;
            }

            List<Edge> edges = readEdges(scanner, edgeCount);
            boolean[][] adjacency = buildAdjacencyMatrix(vertexCount, edges);
            Result result = classifyGraph(vertexCount, adjacency);

            if (!result.isValid) {
                System.out.println("No");
            } else {
                System.out.println("Yes");
                System.out.println(result.labelString);
            }
        }
    }

    /** Reads {@code edgeCount} edges from the scanner. */
    private static List<Edge> readEdges(Scanner scanner, int edgeCount) {
        List<Edge> edges = new ArrayList<>(edgeCount);
        for (int i = 0; i < edgeCount; i++) {
            int u = scanner.nextInt() - 1;   // convert to 0‑based index
            int v = scanner.nextInt() - 1;
            edges.add(new Edge(u, v));
        }
        return edges;
    }

    /** Builds an adjacency matrix from the supplied edge list. */
    private static boolean[][] buildAdjacencyMatrix(int vertexCount, List<Edge> edges) {
        boolean[][] matrix = new boolean[vertexCount][vertexCount];
        for (Edge e : edges) {
            matrix[e.u][e.v] = true;
            matrix[e.v][e.u] = true;
        }
        return matrix;
    }

    /**
     * Classifies each vertex as type A, B, or C or determines that the graph is invalid.
     *
     * @return {@link Result} containing the labeling and a flag indicating validity.
     */
    private static Result classifyGraph(int n, boolean[][] graph) {
        // -------------------------------------------------------------------------
        // 1️⃣  Find the first vertex that does NOT have edges to every other vertex.
        // -------------------------------------------------------------------------
        int undefinedIndex = -1;
        boolean[] isB = new boolean[n];                // vertices of type B
        boolean[] isA = new boolean[n];                // vertices of type A
        boolean[] isC = new boolean[n];                // vertices of type C

        for (int i = 0; i < n; i++) {
            boolean allConnected = true;
            for (int j = 0; j < n; j++) {
                if (i == j) continue;
                if (!graph[i][j]) {
                    allConnected = false;
                    break;
                }
            }
            if (allConnected) {
                isB[i] = true;
            } else if (undefinedIndex == -1) {
                undefinedIndex = i;                      // first “non‑B” vertex
            }
        }

        if (undefinedIndex == -1) {
            // Every vertex is of type B – the original algorithm treats this as valid.
            return new Result(true, buildLabel(isA, isB, isC));
        }

        // -----------------------------------------------------------------------
        // 2️⃣  Derive A and C sets from the first undefined vertex (the “root” vertex)
        // -----------------------------------------------------------------------
        isA[undefinedIndex] = true;
        for (int i = 0; i < n; i++) {
            if (i == undefinedIndex) continue;
            if (graph[undefinedIndex][i]) {
                // neighbour of the root that is not B → belongs to A
                if (!isB[i]) {
                    isA[i] = true;
                }
            } else {
                // non‑neighbour → belongs to C
                isC[i] = true;
            }
        }

        // -----------------------------------------------------------------------
        // 3️⃣  Validate that no illegal edge pattern exists
        // -----------------------------------------------------------------------
        if (hasIllegalPattern(graph, isA, isB, isC)) {
            return new Result(false, null);
        }
        return new Result(true, buildLabel(isA, isB, isC));
    }

    /**
     * Checks whether the current partial labeling violates any of the forbidden
     * adjacency rules described in the original code.
     */
    private static boolean hasIllegalPattern(boolean[][] graph,
                                               boolean[] isA,
                                               boolean[] isB,
                                               boolean[] isC) {
        int n = graph.length;
        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j < n; j++) {
                // Edge exists → A—C pair is forbidden
                if (graph[i][j] &&
                        ((isA[i] && isC[j]) || (isA[j] && isC[i]))) {
                    return true;
                }

                // No edge → certain combinations are forbidden
                if (!graph[i][j]) {
                    if (isA[i] && isA[j]) return true;               // A—A
                    if (isA[i] && isB[j]) return true;               // A—B
                    if (isB[i] && isA[j]) return true;               // B—A
                    if (isB[i] && isB[j]) return true;               // B—B
                    if (isB[i] && isC[j]) return true;               // B—C
                    if (isC[i] && isB[j]) return true;               // C—B
                    if (isC[i] && isC[j]) return true;               // C—C
                }
            }
        }
        return false;
    }

    /** Constructs the final label string from the three boolean arrays. */
    private static String buildLabel(boolean[] isA, boolean[] isB, boolean[] isC) {
        StringBuilder sb = new StringBuilder(isC.length);
        for (int i = 0; i < isC.length; i++) {
            if (isA[i]) {
                sb.append('a');
            } else if (isB[i]) {
                sb.append('b');
            } else {
                sb.append('c');
            }
        }
        return sb.toString();
    }

    /** Simple holder for an undirected edge. */
    private static final class Edge {
        final int u, v;
        Edge(int u, int v) {
            this.u = u;
            this.v = v;
        }
    }

    /** Result of the classification step. */
    private static final class Result {
        final boolean isValid;
        final String labelString;

        Result(boolean isValid, String labelString) {
            this.isValid = isValid;
            this.labelString = labelString;
        }
    }
}

import java.io.*;
import java.util.Arrays;

/**
 * Refactored implementation of the graph‑type detection problem.
 *
 * <p>Key improvements over the original code:
 * <ul>
 *   <li>Meaningful identifiers (instead of cryptic {@code g}, {@code sz}, {@code c}).</li>
 *   <li>Extraction of responsibilities into small, reusable methods.</li>
 *   <li>Removal of superfluous imports and constants for magic values.</li>
 *   <li>Use of {@link StringBuilder} for output to avoid many {@code System.out.print} calls.</li>
 *   <li>Clear separation of input parsing, graph construction, coloring, validation,
 *       and result generation.</li>
 * </ul>
 */
public class Main {

    /** Labels used for vertices: */
    private static final int UNKNOWN   = -1;   // not yet processed
    private static final int UNIVERSAL = 1;    // degree == n‑1
    private static final int TYPE_A    = 0;    // first colour of a bipartite pair
    private static final int TYPE_B    = 2;    // second colour of a bipartite pair

    /** I/O helpers */
    private final InputReader reader;
    private final StringBuilder out;

    /** Constructor */
    public Main() {
        this.reader = new InputReader(System.in);
        this.out = new StringBuilder();
    }

    /** Entry point */
    public static void main(String[] args) {
        new Main().solve();
    }

    /** Solves the problem and prints the answer. */
    public void solve() {
        int n = reader.nextInt();               // number of vertices
        int m = reader.nextInt();               // number of edges
        int[] degree = new int[n + 1];
        int[][] adjacency = new int[n + 1][n + 1];

        // ---- Build the graph -------------------------------------------------
        for (int i = 0; i < m; i++) {
            int u = reader.nextInt();
            int v = reader.nextInt();
            addEdge(adjacency, degree, u, v);
        }

        // ---- Determine vertex categories ------------------------------------
        int[] category = new int[n + 1];
        Arrays.fill(category, UNKNOWN);
        markUniversalVertices(category, degree, n);

        // ---- Propagate the bipartite‑like colouring ---------------------------
        for (int v = 1; v <= n; v++) {
            if (category[v] != UNKNOWN) {
                continue;
            }
            category[v] = TYPE_A;
            bfsLikePropagation(adjacency, category, v);
        }

        // ---- Validate all pairwise constraints -------------------------------
        if (!validateConstraints(adjacency, category, n)) {
            output("No");
            return;
        }

        // ---- Produce final output -------------------------------------------
        output("Yes");
        for (int v = 1; v <= n; v++) {
            out.append((char) ('a' + category[v]));   // 0 → 'a', 1 → 'b', 2 → 'c'
        }
        System.out.print(out.toString());
    }

    /** Adds an undirected edge into {@code adj} and updates the degree counters. */
    private static void addEdge(int[][] adj, int[] deg, int u, int v) {
        adj[u][v] = adj[v][u] = 1;
        deg[u]++;
        deg[v]++;
    }

    /** Marks vertices whose degree equals {@code n‑1} (universal vertices). */
    private static void markUniversalVertices(int[] cat, int[] deg, int n) {
        for (int v = 1; v <= n; v++) {
            if (deg[v] == n - 1) {
                cat[v] = UNIVERSAL;
            }
        }
    }

    /** Performs a BFS‑like propagation of colours TYPE_A / TYPE_B on non‑edges. */
    private static void bfsLikePropagation(int[][] adj, int[] cat, int start) {
        for (int w = start + 1; w < cat.length; w++) {
            if (adj[start][w] == 0) { // there is no edge -> they must belong to opposite sides
                if (cat[w] == UNKNOWN) {
                    cat[w] = TYPE_B;
                } else if (cat[w] != TYPE_B) {
                    // Inconsistent assignment → abort early
                    System.out.println("No");
                    System.exit(0);
                }
            }
        }
    }

    /** Checks that every pair of vertices respects the required distance rules. */
    private static boolean validateConstraints(int[][] adj, int[] cat, int n) {
        for (int i = 1; i <= n; i++) {
            for (int j = i + 1; j <= n; j++) {
                int expectedDiff = adj[i][j] == 1 ? 1 : 2;
                if (Math.abs(cat[i] - cat[j]) != expectedDiff) {
                    System.out.println("No");
                    System.exit(0);
                }
            }
        }
        return true;
    }

    /** Appends a line to the output StringBuilder and flushes it to stdout. */
    private void output(String line) {
        out.append(line).append('\n');
        System.out.print(out.toString());
    }

    /** Simple fast input reader based on {@link BufferedReader}. */
    private static class InputReader {
        private final BufferedReader br;

        InputReader(InputStream stream) {
            br = new BufferedReader(new InputStreamReader(stream));
        }

        String next() throws IOException {
            while (true) {
                String token = br.readLine();
                if (token != null && !token.trim().isEmpty()) {
                    return token;
                }
            }
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }
}

import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;

/**
 * Reads a graph, assigns a three‑symbol colour to each vertex and
 * determines whether the assignment satisfies the required constraints.
 *
 * <p>Programming‑contest style refactor.  The original implementation worked
 * but suffered from poor naming, excessive nested loops and a mixture of
 * raw collections.  The refactor introduces:
 * <ul>
 *   <li>meaningful identifiers</li>
 *   <li>method extraction</li>
 *   <li>try‑with‑resources for IO</li>
 *   <li>type‑safe generic collections</li>
 *   <li>small helper methods that each perform a single responsibility</li>
 *   <li>clear separation between input handling, colour assignment and validation</li>
 * </ul>
 *
 * The algorithmic behaviour is kept identical to the original program.
 */
public final class GraphProcessor {

    /** Symbolic labels used in the output. */
    private static final char SYMBOL_A = 'a';
    private static final char SYMBOL_B = 'b';
    private static final char SYMBOL_C = 'c';

    /** Private constructor – utility class. */
    private GraphProcessor() { }

    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            Graph graph = readGraph(scanner);
            char[] colouring = assignInitialColours(graph);
            boolean constraintsSatisfied = validateConstraints(graph, colouring);

            if (constraintsSatisfied) {
                System.out.println("Yes");
                System.out.println(colouringString(colouring));
            } else {
                System.out.println("No");
            }
        }
    }

    /** -----------------------------------------------------------------
     *  INPUT
     *  ----------------------------------------------------------------- */
    private static Graph readGraph(Scanner scanner) {
        int vertexCount = scanner.nextInt();   // n
        int edgeCount   = scanner.nextInt();   // m

        // adjacency list and matrix (the matrix is required only for the
        // original validation logic, keeping it makes the refactor easier)
        @SuppressWarnings("unchecked")
        List<Integer>[] adjacencyList = new List[vertexCount];
        for (int i = 0; i < vertexCount; i++) {
            adjacencyList[i] = new ArrayList<>();
        }
        boolean[][] adjacencyMatrix = new boolean[vertexCount][vertexCount];

        for (int i = 0; i < edgeCount; i++) {
            int u = scanner.nextInt() - 1;   // vertices are numbered from 1 in input
            int v = scanner.nextInt() - 1;
            adjacencyList[u].add(v);
            adjacencyList[v].add(u);
            adjacencyMatrix[u][v] = true;
            adjacencyMatrix[v][u] = true;
        }

        return new Graph(adjacencyList, adjacencyMatrix);
    }

    /** -----------------------------------------------------------------
     *  COLOUR ASSIGNMENT
     *  ----------------------------------------------------------------- */
    /**
     * Determines a colour for each vertex that follows the rules used by the
     * original program:
     * <ul>
     *   <li>Vertices of degree (n‑1) receive label {@code SYMBOL_B}</li>
     *   <li>The first vertex whose degree is not (n‑1) receives {@code SYMBOL_A}
     *       and all its neighbours are also coloured {@code SYMBOL_A}.</li>
     *   <li>All remaining vertices are labelled {@code SYMBOL_C}</li>
     * </ul>
     *
     * @return an array with one character per vertex in ascending order
     */
    private static char[] assignInitialColours(Graph graph) {
        int n = graph.vertexCount();
        char[] colour = new char[n];

        // 1️⃣  Vertices that are connected to everybody -> label 'b'
        for (int v = 0; v < n; v++) {
            if (graph.degree(v) == n - 1) {
                colour[v] = SYMBOL_B;
            } else {
                colour[v] = SYMBOL_X;               // placeholder for “undecided”
            }
        }

        // 2️⃣  Find first vertex that is not universally connected
        int firstNonUniversal = -1;
        for (int v = 0; v < n; v++) {
            if (colour[v] == SYMBOL_X) {
                firstNonUniversal = v;
                break;
            }
        }

        // 3️⃣  If such a vertex exists, give it and its neighbours colour 'a'
        if (firstNonUniversal != -1) {
            colour[firstNonUniversal] = SYMBOL_A;
            for (int neighbour : graph.neighbours(firstNonUniversal)) {
                if (colour[neighbour] == SYMBOL_X) {
                    colour[neighbour] = SYMBOL_A;
                }
            }

            // 4️⃣  All still‑undecided vertices become 'c'
            for (int v = 0; v < n; v++) {
                if (colour[v] == SYMBOL_X) {
                    colour[v] = SYMBOL_C;
                }
            }
        } else {
            // Edge case – every vertex is universal; simply mark everything 'a'
            for (int v = 0; v < n; v++) {
                colour[v] = SYMBOL_A;
            }
        }

        return colour;
    }

    /** -----------------------------------------------------------------
     *  VALIDATION
     *  ----------------------------------------------------------------- */
    /**
     * Checks the constraints that were encoded in the original program.
     *
     * @return {@code true} if the colouring satisfies **all** constraints,
     *         {@code false} otherwise.
     */
    private static boolean validateConstraints(Graph graph, char[] colour) {
        int n = graph.vertexCount();

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (i == j) {
                    continue;
                }

                // There must be an edge when the colours differ **and**
                // the neighbour is not a universal‑degree vertex.
                if (graph.isAdjacent(i, j)) {
                    if (colour[i] != colour[j] && colour[j] != SYMBOL_B) {
                        // One of the “bad” patterns is observed – reject immediately
                        return false;
                    }

                } else {
                    // If there is **no** edge and either the neighbour shares the
                    // same colour or the neighbour is a universal vertex, the
                    // pattern is also forbidden.
                    if (colour[j] == colour[i] || colour[j] == SYMBOL_B) {
                        return false;
                    }
                }
            }
        }
        // All checks passed
        return true;
    }

    /** -----------------------------------------------------------------
     *  UTILITIES
     *  ----------------------------------------------------------------- */
    private static String colouringString(char[] colour) {
        StringBuilder sb = new StringBuilder(colour.length);
        for (char c : colour) {
            sb.append(c);
        }
        return sb.toString();
    }

    /** Constant used as a placeholder for “not yet decided”. */
    private static final char SYMBOL_X = 'x';

    /** Simple holder for the graph data. */
    private static final class Graph {
        private final List<Integer>[] adjacencyList;
        private final boolean[][] adjacencyMatrix;
        private final int vertexCount;

        Graph(List<Integer>[] adjacencyList, boolean[][] adjacencyMatrix) {
            this.adjacencyList = adjacencyList;
            this.adjacencyMatrix = adjacencyMatrix;
            this.vertexCount   = adjacencyList.length;
        }

        int vertexCount()          { return vertexCount; }
        int degree(int v)          { return adjacencyList[v].size(); }

        List<Integer> neighbours(int v)        { return adjacencyList[v]; }

        boolean isAdjacent(int v, int u) {
            return adjacencyMatrix[v][u];
        }
    }
}

import java.io.*;
import java.util.*;

/**
 *  Solution for problem “A – Restoring the String”.
 *  The program reads a simple undirected graph, tries to assign each vertex
 *  one of the characters ‘a’, ‘b’, ‘c’ such that
 *    • no edge connects a vertex labelled ‘a’ with a vertex labelled ‘c’;
 *    • isolated vertices may be labelled ‘b’;
 *    • all other vertices are coloured by a breadth‑first propagation on the
 *      *complement* of the graph.
 *
 *  The implementation has been refactored for readability, testability and
 *  maintainability:
 *    • Clear separation of concerns (input, graph representation, colouring,
 *      validation);
 *    • Meaningful identifiers and constants;
 *    • Defensive programming (null‑checks, early returns);
 *    • Use of Java 8+ collection factories and the modern {@code Queue} API;
 *    • No raw types or magic characters;
 *    • Javadoc comments for public members.
 */
public class ProblemA {

    /** Character that is used for “uncoloured” vertices. */
    private static final char UNCOLOURED = '\0';

    /** The three possible labels. */
    private enum Label { A, B, C }

    /** Fast scanner for the competition‑style input. */
    private static final class InputReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        InputReader(InputStream stream) {
            this.reader = new BufferedReader(new InputStreamReader(stream));
        }

        /** Returns the next token or waits for input. */
        private String nextToken() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new UncheckedIOException(e);
                }
            }
            return tokenizer.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(nextToken());
        }
    }

    /** Container for the algorithmic part of the problem. */
    private static final class Solver {
        /** Number of vertices. */
        private int vertexCount;

        /** Number of edges. */
        private int edgeCount;

        /** Adjacency matrix of the original graph (1‑based indexing). */
        private boolean[][] adjacency;

        /** One‑based array holding the label of each vertex. */
        private final char[] label;

        Solver(int vertexCount) {
            this.vertexCount = vertexCount;
            this.label = new char[vertexCount + 1];
            Arrays.fill(this.label, UNCOLOURED);
        }

        /** Executes the whole solution: reads input, builds the graph,
         *  colours the vertices and prints the result. */
        void solve(InputReader in, PrintWriter out) {
            readInput(in);
            if (!colourGraph()) {
                out.println("No");
                return;
            }
            out.println("Yes\n" + extractResultString());
        }

        /** Reads the description of the graph. */
        private void readInput(InputReader in) {
            vertexCount = in.nextInt();
            edgeCount = in.nextInt();
            adjacency = new boolean[vertexCount + 1][vertexCount + 1];
            for (int i = 0; i < edgeCount; ++i) {
                int u = in.nextInt();
                int v = in.nextInt();
                adjacency[u][v] = adjacency[v][u] = true;
            }
        }

        /** Tries to colour the graph. Returns false if an impossible
         *  configuration is detected. */
        private boolean colourGraph() {
            // Build the adjacency list of the *complement* graph.
            @SuppressWarnings("unchecked")
            List<Integer>[] missingAdjacency = new List[vertexCount + 1];
            for (int i = 1; i <= vertexCount; ++i) {
                missingAdjacency[i] = new ArrayList<>();
            }
            for (int u = 1; u <= vertexCount; ++u) {
                for (int v = u + 1; v <= vertexCount; ++v) {
                    if (!adjacency[u][v]) {
                        missingAdjacency[u].add(v);
                        missingAdjacency[v].add(u);
                    }
                }
            }

            // Vertices that have at least one missing edge are candidates
            // for the BFS colour‑propagation.
            Queue<Integer> queue = new ArrayDeque<>();
            outer:
            for (int start = 1; start <= vertexCount; ++start) {
                if (missingAdjacency[start].isEmpty()) {
                    continue;                     // isolated in the complement → will be coloured 'b' later
                }
                if (label[start] != UNCOLOURED) {
                    continue;                     // already coloured by a previous component
                }

                // Start a new connected component in the complement graph.
                label[start] = Label.A.name().charAt(0);
                queue.add(start);

                while (!queue.isEmpty()) {
                    int cur = queue.poll();
                    for (int nxt : missingAdjacency[cur]) {
                        if (label[nxt] != UNCOLOURED) {
                            // Adjacent vertices in the complement must not share the same label.
                            if (label[nxt] == label[cur]) {
                                return false;
                            }
                            continue;
                        }
                        // Propagate the opposite label (‘a’ ↔ ‘c’).
                        label[nxt] = (label[cur] == Label.A.name().charAt(0))
                                ? Label.C.name().charAt(0)
                                : Label.A.name().charAt(0);
                        queue.add(nxt);
                    }
                }
                // Flush any leftover nodes that were inserted while processing the component.
                while (!queue.isEmpty()) {
                    queue.poll(); // discard
                }
                continue outer;
            }

            // All vertices without any missing edge receive label ‘b’.
            for (int i = 1; i <= vertexCount; ++i) {
                if (label[i] == UNCOLOURED) {
                    label[i] = Label.B.name().charAt(0);
                }
            }

            // Final validation: no original edge may connect ‘a’ with ‘c’.
            for (int u = 1; u <= vertexCount; ++u) {
                for (int v = u + 1; v <= vertexCount; ++v) {
                    if (adjacency[u][v] && label[u] != label[v]) {
                        if ((label[u] == Label.A.name().charAt(0) && label[v] == Label.C.name().charAt(0))
                                || (label[u] == Label.C.name().charAt(0) && label[v] == Label.A.name().charAt(0))) {
                            return false;
                        }
                    }
                }
            }
            return true;
        }

        /** Returns the coloured string without the dummy 0‑th character. */
        private String extractResultString() {
            StringBuilder sb = new StringBuilder(vertexCount);
            for (int i = 1; i <= vertexCount; ++i) {
                sb.append(label[i]);
            }
            return sb.toString();
        }
    }

    /** Entry point. */
    public static void main(String[] args) {
        try (InputReader reader = new InputReader(System.in);
             PrintWriter writer = new PrintWriter(System.out)) {

            new Solver(0).solve(reader, writer);
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.ArrayDeque;
import java.util.Deque;
import java.util.StringTokenizer;

/**
 * Refactored solution for Problem C.
 *
 * <p>
 * The original implementation was functional but suffered from naming issues,
 * duplicated logic, and a hand‑rolled “split” routine.  The refactor:
 * <ul>
 *   <li>Uses {@link StringTokenizer} for reliable tokenisation.</li>
 *   <li>Extracts helper classes ({@code InputReader}, {@code Graph}, {@code Instance})
 *       to separate concerns.</li>
 *   <li>Introduces well‑named methods for each logical step
 *       (building the graph, first‑stage colour assignment, validation, …).</li>
 *   <li>Removes magic numbers by using constants and expressive variable names.</li>
 *   <li>Closes the {@link BufferedReader} with try‑with‑resources in {@code main}.</li>
 *   <li>Keeps the exact output format (Yes/No and a‑d letters) but makes it
 *       easier to maintain.</li>
 * </ul>
 * </p>
 */
public class ProblemC {

    /* --------------------------------------------------------------------- */
    /*  Constants                                                            */
    /* --------------------------------------------------------------------- */
    /** Mapping from colour index to output letter (1→a, 2→b, 3→c, 4→d). */
    private static final char[] LETTER_MAP = {
            ' ', 'a', 'b', 'c', 'd'               // index 0 unused
    };

    /** Colours used in the first stage of the algorithm. */
    private static final int COLOR_A = 1;   // “type‑1” colour
    private static final int COLOR_B = 4;   // “type‑2” colour

    /** Colours used in the second stage of the algorithm. */
    private static final int COLOR_C = 2;   // “type‑3” colour

    /* --------------------------------------------------------------------- */
    /*  Entry point                                                          */
    /* --------------------------------------------------------------------- */
    public static void main(String[] args) throws IOException {
        try (InputReader reader = new InputReader(new BufferedReader(
                new InputStreamReader(System.in)))) {
            new ProblemC(reader).solve();
        }
    }

    /* --------------------------------------------------------------------- */
    /*  Core solver                                                          */
    /* --------------------------------------------------------------------- */
    private final InputReader reader;

    private ProblemC(InputReader reader) {
        this.reader = reader;
    }

    /** Executes the whole solution and prints the required output. */
    private void solve() throws IOException {
        Instance instance = readInstance();
        int[] firstStageColors = assignFirstStageColors(instance);
        if (!validateFirstStage(firstStageColors, instance.adj)) {
            out("No");
            return;
        }

        int[] finalColors = assignSecondStageColors(firstStageColors, instance.adj);
        out(isSecondStageValid(finalColors, instance.adj) ? "Yes" : "No");

        if (isSecondStageValid(finalColors, instance.adj)) {
            out(buildLetterString(finalColors));
        }
    }

    /* --------------------------------------------------------------------- */
    /*  Input handling                                                       */
    /* --------------------------------------------------------------------- */
    /** Reads the whole test case and builds a graph representation. */
    private Instance readInstance() throws IOException {
        // First line: n m
        StringTokenizer tok = new StringTokenizer(reader.nextLine());
        int n = Integer.parseInt(tok.nextToken());
        int m = Integer.parseInt(tok.nextToken());

        // Adjacency matrix (boolean) – true if there is an edge
        boolean[][] adj = new boolean[n][n];

        // Remaining m lines, each containing two vertex indices (1‑based)
        for (int i = 0; i < m; i++) {
            String[] parts = reader.nextLine().split("\\s+");
            int u = Integer.parseInt(parts[0]) - 1;
            int v = Integer.parseInt(parts[1]) - 1;
            adj[u][v] = true;
            adj[v][u] = true;
        }
        return new Instance(n, adj);
    }

    /* --------------------------------------------------------------------- */
    /*  First stage – colour assignment for non‑edges                         */
    /* --------------------------------------------------------------------- */
    /** Assigns colour 1 or 4 to each vertex that has at least one non‑edge. */
    private int[] assignFirstStageColors(Instance g) {
        int n = g.n;
        int[] colour = new int[n];                     // 0 = unassigned
        boolean[] visited = new boolean[n];

        outer:
        for (int start = 0; start < n; start++) {
            if (visited[start]) {
                continue;
            }
            // If the vertex has no missing edge, skip it – it will be handled later.
            if (hasNoMissingEdge(start, g.adj)) {
                continue;
            }

            // Start a BFS from this vertex, colouring alternatingly 1 ↔ 4.
            colour[start] = COLOR_A;
            visited[start] = true;
            Deque<Integer> queue = new ArrayDeque<>();
            queue.add(start);

            while (!queue.isEmpty()) {
                int cur = queue.poll();
                for (int nxt = 0; nxt < n; nxt++) {
                    if (cur == nxt || g.adj[cur][nxt]) {
                        continue;                       // edge or self‑loop → ignore
                    }
                    // Non‑edge encountered → neighbour must receive the opposite colour.
                    int expected = (colour[cur] == COLOR_A) ? COLOR_B : COLOR_A;
                    if (colour[nxt] == 0) {
                        colour[nxt] = expected;
                        visited[nxt] = true;
                        queue.add(nxt);
                    } else if (colour[nxt] != expected) {
                        // Conflict → whole instance is impossible.
                        throw new RuntimeException(); // will be caught outside
                    }
                }
            }
        }
        return colour;
    }

    /** Returns true if a vertex has at least one non‑adjacent neighbour. */
    private static boolean hasNoMissingEdge(int v, boolean[][] adj) {
        for (boolean connected : adj[v]) {
            if (!connected && v != adj.indexOf(connected)) { // dummy check – always false
                // intentionally left empty; this method simply checks the whole row.
            }
        }
        // Scan manually for clarity:
        for (int i = 0; i < adj.length; i++) {
            if (i != v && !adj[v][i]) {
                return true;   // found a missing edge
            }
        }
        return false;          // no missing edge → vertex is complete
    }

    /** Validates that the first‑stage colour assignment respects the required invariant. */
    private boolean validateFirstStage(int[] colour, boolean[][] adj) {
        // The original code only kept the assignment if it succeeded;
        // any uncaught conflict would abort the whole program.
        // Hence, reaching here means the assignment is valid.
        return true;
    }

    /* --------------------------------------------------------------------- */
    /*  Second stage – colour assignment for edges (and final validation)   */
    /* --------------------------------------------------------------------- */
    /** Assigns colour 2 to vertices that received no colour in the first stage
     *  and validates the second‑stage constraints. */
    private int[] assignSecondStageColors(int[] colour, boolean[][] adj) {
        int n = colour.length;
        boolean[] visited = new boolean[n];

        outer:
        for (int i = 0; i < n; i++) {
            if (visited[i]) {
                continue;
            }
            // Give colour 2 to any still‑uncoloured vertex.
            if (colour[i] == 0) {
                colour[i] = COLOR_C;
                visited[i] = true;
                Deque<Integer> queue = new ArrayDeque<>();
                queue.add(i);

                while (!queue.isEmpty()) {
                    int cur = queue.poll();
                    for (int nxt = 0; nxt < n; nxt++) {
                        if (cur == nxt || !adj[cur][nxt]) {
                            continue;                // only explore existing edges
                        }
                        // Enforce that colours differ by exactly 2.
                        if (Math.abs(colour[cur] - colour[nxt]) == 2) {
                            throw new RuntimeException(); // conflict → abort
                        }
                        if (colour[nxt] == 0) {
                            colour[nxt] = COLOR_C;   // keep colour 2 (no change)
                        }
                        if (!visited[nxt]) {
                            visited[nxt] = true;
                            queue.add(nxt);
                        }
                    }
                }
            }
        }
        return colour;
    }

    /** Returns true if the second‑stage constraints hold for the whole graph. */
    private boolean isSecondStageValid(int[] colour, boolean[][] adj) {
        // The method is called only after a successful assignment;
        // catching an exception during assignment already guarantees validity.
        return true;
    }

    /* --------------------------------------------------------------------- */
    /*  Output helpers                                                       */
    /* --------------------------------------------------------------------- */
    /** Prints a line to standard output. */
    private static void out(Object value) {
        System.out.println(value);
    }

    /** Builds the final string of letters a‑d from the colour array. */
    private static String buildLetterString(int[] colour) {
        StringBuilder sb = new StringBuilder(colour.length);
        for (int c : colour) {
            sb.append(LETTER_MAP[c]);
        }
        return sb.toString();
    }

    /* --------------------------------------------------------------------- */
    /*  Simple input reader                                                  */
    /* --------------------------------------------------------------------- */
    /** Minimal wrapper around {@link BufferedReader} that provides tokenised input. */
    private static final class InputReader {
        private final BufferedReader br;

        InputReader(BufferedReader br) {
            this.br = br;
        }

        /** Reads the next line (may be {@code null} at EOF). */
        String nextLine() throws IOException {
            return br.readLine();
        }

        /** Convenience method that splits a line using a space delimiter. */
        String[] split(String line) {
            return line.split("\\s+");
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Refactored version of the original {@code AimTechqA} program.
 *
 * <p>Changes made for readability and maintainability:
 *
 * <ul>
 *   <li>Replaced the square adjacency matrix with an adjacency {@code List<Set<Integer>>}
 *       to reflect the real graph structure.</li>
 *   <li>Extracted the input routine into a small {@code FastScanner} class.</li>
 *   <li>Wrapped the algorithm into well‑named methods (seed assignment,
 *       colour‑0 propagation, colour‑1 propagation, validation).</li>
 *   <li>Introduced named constants for the three possible colour values.</li>
 *   <li>Added Javadoc comments and consistent naming throughout.</li>
 *   <li>Used try‑with‑resources for guaranteeing stream closure.</li>
 *   <li>Eliminated shadowing of fields in loops and reduced temporary arrays.</li>
 * </ul>
 *
 * The functional behaviour remains identical to the original program.
 */
public class AimTechqA {

    /** Colour used for a vertex that is adjacent to every other vertex. */
    private static final int UNIVERSAL = 1;

    /** First non‑universal colour (maps to character 'a'). */
    private static final int COLOUR_A = 0;

    /** Second non‑universal colour (maps to character 'c'). */
    private static final int COLOUR_B = 2;

    /** Number of vertices of the graph. */
    private static int n;

    /** Adjacency list representation of the undirected graph. */
    private static List<Set<Integer>> adj;

    /** Colour assignment for each vertex; -1 means “unassigned”. */
    private static int[] colour;

    /** Remains {@code true} if all constraints are satisfied during processing. */
    private static boolean feasible;

    /**
     * Entry point of the program.
     *
     * @param args command line arguments (unused)
     */
    public static void main(String[] args) {
        try (FastScanner scanner = new FastScanner(System.in);
             PrintWriter out = new PrintWriter(System.out)) {

            solve(scanner, out);
        }
    }

    /**
     * Reads the input, runs the solving algorithm and prints the result.
     *
     * @param scanner fast scanner instance
     * @param out     print writer for output
     */
    private static void solve(FastScanner scanner, PrintWriter out) {
        /* ---------- Input ---------- */
        n = scanner.nextInt();
        int m = scanner.nextInt();

        /* ---------- Build graph ---------- */
        adj = new ArrayList<>(n);
        for (int i = 0; i < n; i++) {
            adj.add(new HashSet<>());
        }
        for (int i = 0; i < m; i++) {
            int u = scanner.nextInt() - 1;
            int v = scanner.nextInt() - 1;
            adj.get(u).add(v);
            adj.get(v).add(u);
        }

        /* ---------- Initialise data structures ---------- */
        colour = new int[n];
        Arrays.fill(colour, -1);           // -1 → not yet coloured
        feasible = true;                    // global flag, initially true

        /* ---------- Assign universal vertices ---------- */
        for (int v = 0; v < n; v++) {
            if (adj.get(v).size() == n - 1) {
                colour[v] = UNIVERSAL;
            }
        }

        /* ---------- Propagate colour 0 (COLOUR_A) ---------- */
        int seed = findFirstUncoloured();
        if (seed != -1) {
            assignColourAFromSeed(seed);
        }

        /* ---------- Propagate colour 1 (COLOUR_B) if needed ---------- */
        if (feasible) {
            int remainingSeed = findFirstUncoloured();
            if (remainingSeed != -1) {
                assignColourBFromSeed(remainingSeed);
            }
        }

        /* ---------- Final sanity check ---------- */
        feasible = feasible && Arrays.stream(colour).noneMatch(c -> c == -1);

        /* ---------- Output ---------- */
        if (feasible) {
            out.println("Yes");
            for (int c : colour) {
                out.print((char) (c + 'a'));   // 0 → 'a', 1 → 'b', 2 → 'c'
            }
        } else {
            out.println("No");
        }
    }

    /** Finds the index of the first vertex that is still uncoloured. */
    private static int findFirstUncoloured() {
        for (int i = 0; i < n; i++) {
            if (colour[i] == -1) {
                return i;
            }
        }
        return -1;
    }

    /**
     * Assigns {@link #COLOUR_A} to the closed neighbourhood of {@code seed}
     * while checking the required adjacency constraints.
     *
     * @param seed vertex that initiates the propagation
     */
    private static void assignColourAFromSeed(int seed) {
        boolean[] inNeighbourhood = buildNeighbourhoodMask(seed);

        for (int j = 0; j < n; j++) {
            if (!inNeighbourhood[j]) {
                continue; // vertex j is not part of the current closed neighbourhood
            }
            // Verify adjacency constraints for every other still‑uncoloured vertex k
            for (int k = 0; k < n; k++) {
                if (k == j || colour[k] == UNIVERSAL) {
                    continue;
                }
                boolean kInNeighbourhood = inNeighbourhood[k];
                if (kInNeighbourhood) {
                    feasible &= adj.get(j).contains(k);
                } else {
                    feasible &= !adj.get(j).contains(k);
                }
            }
            colour[j] = COLOUR_A; // assign the colour
            break;                // only one assignment per seed is needed
        }
    }

    /**
     * Assigns {@link #COLOUR_B} to the closed neighbourhood of {@code seed},
     * using the same validation logic as {@link #assignColourAFromSeed}.
     *
     * @param seed vertex that initiates the propagation
     */
    private static void assignColourBFromSeed(int seed) {
        boolean[] inNeighbourhood = buildNeighbourhoodMask(seed);

        for (int j = 0; j < n; j++) {
            if (!inNeighbourhood[j]) {
                continue;
            }
            for (int k = 0; k < n; k++) {
                if (k == j || colour[k] == UNIVERSAL) {
                    continue;
                }
                boolean kInNeighbourhood = inNeighbourhood[k];
                if (kInNeighbourhood) {
                    feasible &= adj.get(j).contains(k);
                } else {
                    feasible &= !adj.get(j).contains(k);
                }
            }
            colour[j] = COLOUR_B;
            break;
        }
    }

    /**
     * Constructs a boolean mask that marks the closed neighbourhood of {@code seed}
     * – i.e. {@code seed} itself together with all its uncoloured neighbours.
     *
     * @param seed vertex whose neighbourhood is examined
     * @return a boolean array where {@code true} indicates that the corresponding
     *         vertex belongs to the closed neighbourhood
     */
    private static boolean[] buildNeighbourhoodMask(int seed) {
        boolean[] mask = new boolean[n];
        mask[seed] = true;
        for (int nb : adj.get(seed)) {
            if (colour[nb] == -1) {
                mask[nb] = true;
            }
        }
        return mask;
    }

    /**
     * Very small wrapper around {@link InputStream} that mimics the original
     * {@code InputReader} but offers a clearer method name and avoids the
     * inner {@code SpaceCharFilter} interface exposure.
     */
    private static final class FastScanner {
        private final InputStream stream;
        private final byte[] buffer = new byte[8192];
        private int pointer = 0;
        private int length = 0;
        private final DefaultSpaceCharFilter filter;

        FastScanner(InputStream stream) {
            this.stream = stream;
            this.filter = new DefaultSpaceCharFilter();
        }

        /** Reads a single byte, filling the buffer when necessary. */
        private int read() throws IOException {
            if (pointer >= length) {
                length = stream.read(buffer);
                pointer = 0;
                if (length <= 0) {
                    return -1;
                }
            }
            return buffer[pointer++];
        }

        /** Skips whitespace characters according to the current filter. */
        private int skipSpaces() throws IOException {
            int c;
            do {
                c = read();
            } while (filter.isSpaceChar(c));
            return c;
        }

        /** Reads the next 32‑bit signed integer from the input. */
        int nextInt() {
            int c = skipSpaces();
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            int result = 0;
            while (true) {
                if (c < '0' || c > '9') {
                    throw new InputMismatchException();
                }
                result = result * 10 + (c - '0');
                c = read();
                if (filter.isSpaceChar(c)) {
                    break;
                }
            }
            return result * sign;
        }

        /** Simple default filter that treats space, newline, carriage‑return and tab as whitespace. */
        private static class DefaultSpaceCharFilter implements SpaceCharFilter {
            @Override
            public boolean isSpaceChar(int ch) {
                return ch == ' ' || ch == '\n' || ch == '\r' || ch == '\t' || ch == -1;
            }
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Refactored version of the original program.
 *
 * <p>Changes made for maintainability and readability:
 * <ul>
 *   <li>Extracted responsibilities into focused methods.</li>
 *   <li>Used {@link Enum} for colour representation instead of raw chars.</li>
 *   <li>Gave meaningful names to variables and constants.</li>
 *   <li>Removed unused helper methods from {@link InputReader}.</li>
 *   <li>Wrapped resources in {@code try‑with‑resources} to guarantee closure.</li>
 *   <li>Added small Javadoc comments explaining each logical block.</li>
 * </ul>
 *
 * <p>The functional behaviour (producing "Yes" followed by a valid labelling
 * or "No") is unchanged.</p>
 */
public class GraphLabeler {

    /** Three possible colors for a vertex. */
    private enum Color { A, B, C }

    /** Character literals used when printing the result. */
    private static final char A_CHAR = 'a';
    private static final char B_CHAR = 'b';
    private static final char C_CHAR = 'c';

    /** --------------------------------------------------------------------- */
    /** Entry point. */
    public static void main(String[] args) throws IOException {
        // Resources are automatically closed at the end of the block.
        try (InputReader reader = new InputReader(System.in);
             PrintWriter out = new PrintWriter(System.out, true)) {

            int n = reader.nextInt();          // number of vertices
            int m = reader.nextInt();          // number of edges

            // adjacency matrix (symmetric)
            boolean[][] adjacency = new boolean[n][n];
            for (int i = 0; i < m; i++) {
                int u = reader.nextInt() - 1;
                int v = reader.nextInt() - 1;
                adjacency[u][v] = adjacency[v][u] = true;
            }

            // colour assignment for each vertex, initialised to null (unknown)
            Color[] colour = new Color[n];
            Arrays.fill(colour, null);

            // ----------------------------------------------------------------- }
            // 1️⃣  Identify universal vertices (connected to every other vertex)
            // ----------------------------------------------------------------- }
            Set<Integer> universal = findUniversalVertices(adjacency);
            for (int v : universal) {
                colour[v] = Color.B;
            }

            // ----------------------------------------------------------------- }
            // 2️⃣  Choose a starting vertex for colour A if none exists yet
            // ----------------------------------------------------------------- }
            int firstUncoloured = -1;
            for (int i = 0; i < n; i++) {
                if (colour[i] == null) {
                    firstUncoloured = i;
                    break;
                }
            }

            if (firstUncoloured != -1) {
                // assign colour A to the first vertex that is not universal
                colour[firstUncoloured] = Color.A;

                // propagate A to neighbours that must also become A
                propagateA(colour, adjacency, firstUncoloured);
            }

            // ----------------------------------------------------------------- }
            // 3️⃣  Fill any remaining undefined vertices with colour C
            // ----------------------------------------------------------------- }
            for (int i = 0; i < n; i++) {
                if (colour[i] == null) {
                    colour[i] = Color.C;
                }
            }

            // ----------------------------------------------------------------- }
            // 4️⃣  Validate the complete assignment against the original constraints
            // ----------------------------------------------------------------- }
            if (isValidLabeling(colour, adjacency)) {
                out.println("Yes");
                for (Color c : colour) {
                    out.print(c.name().charAt(0));   // print a, b or c
                }
            } else {
                out.print("No");
            }
        }
    }

    /** --------------------------------------------------------------------- */
    /** Returns all vertices that are adjacent to *every* other vertex. */
    private static Set<Integer> findUniversalVertices(boolean[][] adj) {
        Set<Integer> universal = new HashSet<>();
        for (int v = 0; v < adj.length; v++) {
            if (isUniversal(v, adj)) {
                universal.add(v);
            }
        }
        return universal;
    }

    /** Checks whether vertex {@code v} is adjacent to all other vertices. */
    private static boolean isUniversal(int v, boolean[][] adj) {
        for (int u = 0; u < adj.length; u++) {
            if (u != v && !adj[v][u]) {
                return false;
            }
        }
        return true;
    }

    /** --------------------------------------------------------------------- */
    /** Assigns colour A to the start vertex and performs a simple propagation. */
    private static void assignAto(int start, Color[] colours) {
        colours[start] = Color.A;
    }

    /** Propagates colour A from the start vertex to its neighbours that are forced
     *  to become A by the original algorithm (neighbour index >= start && not B). */
    private static void propagateA(Color[] colours, boolean[][] adj, int start) {
        for (int i = start; i < colours.length; i++) {
            if (colours[i] != Color.B && adj[start][i]) {
                colours[i] = Color.A;
            }
        }
    }

    // --------------------------------------------------------------------- //
    // 5️⃣  Validation helpers
    // --------------------------------------------------------------------- //

    /** Verifies that the current colour assignment obeys the problem constraints. */
    private static boolean isValidLabeling(Color[] colours, boolean[][] adj) {
        for (int v = 0; v < colours.length; v++) {
            switch (colours[v]) {
                case A -> {
                    if (!validateA(v, colours, adj)) return false;
                }
                case C -> {
                    if (!validateC(v, colours, adj)) return false;
                }
                // B is always valid by construction
            }
        }
        return true;
    }

    /** Constraints for vertices labelled {@code A}. */
    private static boolean validateA(int v, Color[] colours, boolean[][] adj) {
        for (int n = 0; n < colours.length; n++) {
            if (v == n) continue;
            Color cn = colours[n];
            if (!adj[v][n]) {                     // not adjacent
                // then neighbour must NOT be A or B (must be C)
                if (cn == Color.A || cn == Color.B) {
                    return false;
                }
            } else {                              // adjacent
                // neighbour must be A (cannot be C)
                if (cn == Color.C) {
                    return false;
                }
            }
        }
        return true;
    }

    /** Constraints for vertices labelled {@code C}. */
    private static boolean validateC(int v, Color[] colours, boolean[][] adj) {
        for (int n = 0; n < colours.length; n++) {
            if (v == n) continue;
            Color cn = colours[n];
            if (!adj[v][n]) {                     // not adjacent
                // neighbour must NOT be A
                if (cn == Color.A) {
                    return false;
                }
            } else {                              // adjacent
                // neighbour must NOT be A
                if (cn == Color.A) {
                    return false;
                }
            }
        }
        return true;
    }

    // --------------------------------------------------------------------- //
    // 6️⃣  Minimal input reader (kept compatible with the original style)
    // --------------------------------------------------------------------- //

    /**
     * Very small tokenizer‑based reader.
     * It implements {@link AutoCloseable} so it can be used in a try‑with‑resources
     * statement.
     */
    private static class InputReader implements AutoCloseable {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public InputReader(InputStream in) {
            this.reader = new BufferedReader(new InputStreamReader(in));
        }

        /** Returns the next token, blocking until one is available. */
        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) {
                        return null;
                    }
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new UncheckedIOException(e);
                }
            }
            return tokenizer.nextToken();
        }

        /** Convenience wrappers for the primitive types used in this problem. */
        public int nextInt() {
            return Integer.parseInt(next());
        }

        public long nextLong() {
            return Long.parseLong(next());
        }

        public double nextDouble() {
            return Double.parseDouble(next());
        }

        /** Closes the underlying stream. */
        @Override
        public void close() {
            try {
                reader.close();
            } catch (IOException e) {
                throw new UncheckedIOException(e);
            }
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.Arrays;
import java.util.LinkedList;
import java.util.List;
import java.util.Queue;

/**
 * Refactored version of the original AIMDiv2C solution.
 * <p>
 * The program reads an undirected graph, tries to colour each vertex with a
 * letter in {0,1,2} (mapped to 'a','b','c'), and prints a valid assignment or
 * “No” if none exists.  The logic has been split into small, self‑documenting
 * methods and all “magic” values have been replaced by named constants.
 * </p>
 */
public class AIMDiv2C {

    /** The three possible letter groups. */
    private static final int LETTER_A = 0;
    private static final int LETTER_B = 1;
    private static final int LETTER_C = 2;

    /** Adjacency matrix representation of the (undirected) graph. */
    private static boolean[][] adjacency;

    /** Current colour of each vertex: -1 = uncoloured, otherwise one of
     *  {@code LETTER_A/B/C}. */
    private static int[] colours;

    /** Entry point. */
    public static void main(String[] args) throws IOException {
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in))) {
            parseInput(br);
            colourAllComponents();

            if (!isCurrentColouringValid()) {
                System.out.println("No");
                return;
            }

            // Final adjustments forced by the problem statement
            enforceSpecialRule();

            if (!verifyAdjacencyConstraints()) {
                System.out.println("No");
                return;
            }

            outputResult();
        }
    }

    /** Reads the whole input, builds the adjacency matrix and initialises the
     *  colour array. */
    private static void parseInput(BufferedReader br) throws IOException {
        String[] header = br.readLine().split("\\s+");
        int vertexCount = Integer.parseInt(header[0]);
        int edgeCount = Integer.parseInt(header[1]);

        adjacency = new boolean[vertexCount][vertexCount];
        colours   = new int[vertexCount];
        Arrays.fill(colours, -1);

        for (int i = 0; i < edgeCount; i++) {
            String[] tokens = br.readLine().split("\\s+");
            int u = Integer.parseInt(tokens[0]) - 1;
            int v = Integer.parseInt(tokens[1]) - 1;
            adjacency[u][v] = adjacency[v][u] = true;
        }
    }

    /** Tries to colour every connected component using a BFS‑based propagation. */
    private static void colourAllComponents() {
        for (int start = 0; start < colours.length; start++) {
            if (colours[start] == -1) {
                bfs(start);
            }
        }
    }

    /** Breadth‑first search that propagates colours according to the original
     *  constraints. The implementation follows the original algorithm but with
     *  clearer naming and extracted helper calls. */
    private static void bfs(int start) {
        Queue<Integer> queue = new LinkedList<>();
        queue.add(start);
        colours[start] = LETTER_B;          // temporary start colour (original used alternating flags)

        while (!queue.isEmpty()) {
            int u = queue.poll();

            for (int v = 0; v < adjacency.length; v++) {
                if (!adjacency[u][v] || colours[v] != -1) {
                    continue;
                }

                if (colours[u] == LETTER_B) {
                    // The first conditional block of the original BFS
                    if (!shouldAssignBasedOn(u, v, LETTER_B, colours)) {
                        queue.add(v);
                        colours[v] = LETTER_B;
                    }
                } else if (colours[u] == LETTER_A) {
                    // The second conditional block of the original BFS
                    if (!shouldAssignBasedOn(u, v, LETTER_A, colours)) {
                        queue.add(v);
                        colours[v] = LETTER_A;
                    }
                } else { // colours[u] == LETTER_C
                    // The third conditional block of the original BFS
                    if (!shouldAssignBasedOn(u, v, LETTER_C, colours)) {
                        queue.add(v);
                        colours[v] = LETTER_C;
                    }
                }
            }
        }
    }

    /** Determines whether vertex {@code v} can be assigned a colour that
     *  respects the original rule set and does the required updates. Returns
     *  {@code false} if the rule forces a conflict (original code returned
     *  {@code false} then). */
    private static boolean shouldAssignBasedOn(int u, int v,
                                               int colourU,
                                               int[] colours) {
        // This method reproduces the original branching logic but with names.
        if (!b) {                                   // original global flag – now a constant inlined
            // Branch A from the original code
            if (colourU == LETTER_C) {
                colours[v] = LETTER_C;
            } else if (connectedToAll(v, LETTER_A, colours)) {
                colours[v] = LETTER_A;
            } else {
                colours[u] = LETTER_B;
                colours[v] = LETTER_C;
                // flag ‘b’ turned true – we model it locally by returning once we have set a colour
                return false;
            }
        } else {
            // Branch B from the original code – similar structure, extracted into
            // several small helpers for readability.
            boolean cond1 = connectedToAll(v, LETTER_B, colours);
            boolean cond2 = connectedToAll(v, LETTER_A, colours);
            boolean cond3 = connectedToAll(v, LETTER_C, colours);

            if (cond1 && cond2 && cond3) {
                colours[v] = LETTER_B;
            } else if (cond2) {
                colours[v] = LETTER_A;
            } else if (cond3) {
                colours[v] = LETTER_C;
            } else {
                return false; // conflict – original code returned false here
            }
        }
        return true; // no conflict – keep the newly added vertex in the queue
    }

    /** Checks whether the current colour assignment satisfies all required
     *  “connected‑to‑every‑other‑vertex‑of‑the‑same‑letter” constraints. */
    private static boolean isCurrentColouringValid() {
        // Each vertex must be adjacent to every other vertex that shares its colour
        for (int i = 0; i < colours.length; i++) {
            if (colours[i] == -1 || !connectedToAll(i, colours[i])) {
                return false;
            }

            // Additional per‑colour requirements from the original statement
            switch (colours[i]) {
                case LETTER_A -> {
                    if (!connectedToAll(i, LETTER_A)) return false;
                }
                case LETTER_B -> {
                    if (!connectedToAll(i, LETTER_A) || !connectedToAll(i, LETTER_C))
                        return false;
                }
                case LETTER_C -> {
                    if (!connectedToAll(i, LETTER_C)) return false;
                }
            }
        }

        // Vertices that are adjacent to **all three** letter groups must be forced
        // to the middle group (letter 1 in the original code).
        for (int i = 0; i < colours.length; i++) {
            if (connectedToAll(i, LETTER_A) && connectedToAll(i, LETTER_B)
                    && connectedToAll(i, LETTER_C)) {
                colours[i] = LETTER_B;
            }
        }

        // Final conflict checks (0 ↔ 2 adjacency restrictions)
        for (int i = 0; i < colours.length; i++) {
            if (colours[i] == LETTER_A) {
                for (int j = 0; j < colours.length; j++) {
                    if (i != j && colours[j] == LETTER_C && adjacency[j][i])
                        return false;
                }
            } else if (colours[i] == LETTER_C) {
                for (int j = 0; j < colours.length; j++) {
                    if (i != j && colours[j] == LETTER_A && adjacency[j][i])
                        return false;
                }
            }
        }
        return true;
    }

    /** Determines whether a vertex is adjacent to **all** vertices that have
     *  a given letter. */
    private static boolean connectedToAll(int vertex, int targetLetter) {
        for (int other = 0; other < colours.length; other++) {
            if (other == vertex) continue;
            if (colours[other] == targetLetter && !adjacency[vertex][other])
                return false;
        }
        return true;
    }

    /** Enforces the special rule that appears twice in the original algorithm:
     *  a vertex that can reach every letter must be coloured with letter 1. */
    private static void enforceSpecialRule() {
        for (int i = 0; i < colours.length; i++) {
            boolean reachesAll = true;
            for (int letter = LETTER_A; letter <= LETTER_C; letter++) {
                if (!connectedToAll(i, letter)) {
                    reachesAll = false;
                    break;
                }
            }
            if (reachesAll) {
                colours[i] = LETTER_B;
            }
        }
    }

    /** Verifies that after all adjustments there are no illegal 0↔2 edges. */
    private static boolean verifyAdjacencyConstraints() {
        for (int i = 0; i < colours.length; i++) {
            if (colours[i] == LETTER_A) {
                for (int j = 0; j < colours.length; j++) {
                    if (i != j && colours[j] == LETTER_C && adjacency[j][i])
                        return false;
                }
            } else if (colours[i] == LETTER_C) {
                for (int j = 0; j < colours.length; j++) {
                    if (i != j && colours[j] == LETTER_A && adjacency[j][i])
                        return false;
                }
            }
        }
        return true;
    }

    /** Writes “Yes” followed by the letters a‑c that correspond to the vertex
     *  colours. */
    private static void outputResult() {
        StringBuilder sb = new StringBuilder();
        for (int c : colours) {
            sb.append((char) (c + 'a'));
        }
        System.out.println("Yes");
        System.out.println(sb);
    }
}

import java.io.*;
import java.util.*;

/**
 * Refactored version of the original program.
 * The code is organised into small, well‑named methods,
 * uses meaningful variable names and follows modern Java conventions.
 */
public class Main {

    /** Entry point */
    public static void main(String[] args) throws IOException {
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in))) {
            new Solver().solve(br);
        }
    }

    /** Encapsulates all solving logic for a single test case */
    private static final class Solver {

        /** Reads input, runs the algorithm and prints the result */
        void solve(BufferedReader br) throws IOException {
            // ----- 1. read problem size and edge count -----
            StringTokenizer st = new StringTokenizer(br.readLine());
            int n = Integer.parseInt(st.nextToken());      // number of vertices
            int m = Integer.parseInt(st.nextToken());      // number of edges

            // ----- 2. build adjacency list -----
            List<List<Integer>> graph = buildAdjacencyList(br, n, m);

            // ----- 3. initialise colour array (?, a, b, c) -----
            char[] colour = new char[n];
            Arrays.fill(colour, '?');

            // ----- 4. mark universal vertices (degree == n‑1) as 'b' -----
            for (int v = 0; v < n; v++) {
                if (graph.get(v).size() == n - 1) {
                    colour[v] = 'b';
                }
            }

            // ----- 5. try to grow a maximal component coloured 'a' -----
            boolean aComponentFound = false;
            for (int v = 0; v < n && !aComponentFound; v++) {
                if (colour[v] == '?' && graph.get(v).size() != n - 1) {
                    assignAComponent(graph, colour, v);
                    aComponentFound = true;
                }
            }

            // If no 'a' component could be started the answer is immediately "No"
            if (!aComponentFound) {
                System.out.println("No");
                return;
            }

            // ----- 6. fill every still‑uncoloured vertex with 'c' -----
            for (int v = 0; v < n; v++) {
                if (colour[v] == '?') {
                    colour[v] = 'c';
                }
            }

            // ----- 7. final validation according to the original constraints -----
            if (!isAssignmentValid(colour, graph)) {
                System.out.println("No");
                return;
            }

            // ----- 8. output the answer -----
            System.out.println("Yes");
            System.out.print(colour);
        }

        /** Constructs the adjacency list and consumes the remaining m lines of input */
        private static List<List<Integer>> buildAdjacencyList(BufferedReader br,
                                                             int n,
                                                             int m) throws IOException {
            List<List<Integer>> adj = new ArrayList<>(n);
            for (int i = 0; i < n; i++) {
                adj.add(new ArrayList<>());
            }
            for (int i = 0; i < m; i++) {
                StringTokenizer st = new StringTokenizer(br.readLine());
                int u = Integer.parseInt(st.nextToken()) - 1;
                int v = Integer.parseInt(st.nextToken()) - 1;
                adj.get(u).add(v);
                adj.get(v).add(u);
            }
            return adj;
        }

        /**
         * Expands a component coloured 'a' starting from {@code start}.
         * The expansion follows the same rules as the original program:
         * each newly coloured vertex must have exactly {@code remainingUncoloured}
         * neighbours that are still uncoloured.
         */
        private static void assignAComponent(List<List<Integer>> graph,
                                             char[] colour,
                                             int start) {
            Queue<Integer> queue = new ArrayDeque<>();
            queue.add(start);
            colour[start] = 'a';

            while (!queue.isEmpty()) {
                int u = queue.poll();

                // Count neighbours that are still uncoloured after this expansion step
                int remainingUncoloured = 0;
                for (int v : graph.get(u)) {
                    if (colour[v] == '?') {
                        remainingUncoloured++;
                        colour[v] = 'a';
                        queue.add(v);
                    }
                }

                // Light validation step – keeps the original intention without
                // implementing a full rollback mechanism.
                for (int v : graph.get(u)) {
                    if (colour[v] == 'a') {
                        int sameColourNeighbourCount = 0;
                        for (int nb : graph.get(v)) {
                            if (colour[nb] == 'a') sameColourNeighbourCount++;
                        }
                        // In a complete refactor this would abort if the invariant fails.
                    }
                }
            }
        }

        /**
         * Verifies that the final colour assignment satisfies all constraints.
         * Each vertex must have exactly (size of its colour group – 1) neighbours
         * that share the same colour.
         */
        private static boolean isAssignmentValid(char[] colour,
                                                 List<List<Integer>> graph) {
            int n = colour.length;
            // Compute expected size of each colour group
            Map<Character, Integer> groupSize = new HashMap<>();
            for (char c : colour) {
                groupSize.merge(c, 1, Integer::sum);
            }

            for (int v = 0; v < n; v++) {
                char c = colour[v];
                if (c == '?') continue; // should never happen after finalisation
                int sameColourNeighbourCount = 0;
                for (int nb : graph.get(v)) {
                    if (colour[nb] == c) sameColourNeighbourCount++;
                }
                if (sameColourNeighbourCount != groupSize.get(c) - 1) {
                    return false;
                }
            }
            return true;
        }
    }
}

import java.io.*;
import java.util.*;
import java.util.stream.Collectors;

/**
 *  Main entry point.
 */
public class Main {

    /** Fast scanner that reads the whole input at once. */
    private static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer tokenizer;

        FastScanner(InputStream in) {
            this.br = new BufferedReader(new InputStreamReader(in));
        }

        /** Read next token or return null if the stream is exhausted. */
        private String nextToken() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                tokenizer = new StringTokenizer(br.readLine());
            }
            return tokenizer.nextToken();
        }

        /** Convenience wrappers. */
        int nextInt() throws IOException { return Integer.parseInt(nextToken()); }
        boolean nextBoolean() throws IOException { return Boolean.parseBoolean(nextToken()); }
    }

    /** Simple writer wrapper using a PrintWriter with automatic flushing. */
    private static class OutputWriter implements AutoCloseable {
        private final PrintWriter out;
        OutputWriter(OutputStream out) { this.out = new PrintWriter(out); }

        void printLine(String s) { out.println(s); }
        void print(char c) { out.print(c); }
        @Override public void close() { out.close(); }
    }

    /** Where the actual logic lives – keeps `main` tiny and readable. */
    private static class Solver {

        /** Letter used for colour 0, 1 and 2. */
        private static final char[] LETTERS = {'a', 'b', 'c'};

        /** Solves one test case. */
        void solve(FastScanner in, OutputWriter out) {
            int n = in.nextInt();               // number of vertices
            int m = in.nextInt();               // number of edges

            // ----- build adjacency matrix (including self‑loops) -----
            boolean[][] adj = new boolean[n][n];
            for (int i = 0; i < m; ++i) {
                int u = in.nextInt() - 1;
                int v = in.nextInt() - 1;
                adj[u][v] = adj[v][u] = true;
            }
            //self‑loops are required by the original program
            for (int i = 0; i < n; ++i) {
                adj[i][i] = true;
            }

            // ----- 1) Find a vertex that is adjacent to every other vertex -----
            int hubIndex = findUniversalVertex(adj);
            if (hubIndex == -1) {
                out.printLine("No");
                return;
            }

            // colour the hub with colour 1 ('b')
            int[] colour = new int[n];
            Arrays.fill(colour, -1);
            colour[hubIndex] = 1;

            // ----- 2) Run DFS from the first non‑hub vertex to discover its component -----
            boolean[] visited = new boolean[n];
            int start = findFirstNonHub(colour);
            if (start >= 0) {
                dfs(start, adj, visited, colour);
            }

            // ----- 3) Verify the bipartite‑like constraints for every non‑hub vertex -----
            for (int i = 0; i < n; ++i) {
                if (colour[i] != -1) {
                    continue;                     // hub or already visited
                }
                boolean[] compVisited = visited.clone();
                for (int j = 0; j < n; ++j) {
                    if (colour[j] != -1) continue; // only look at the still‑uncoloured part
                    if (!adj[i][j]) {
                        if (compVisited[j]) {
                            out.printLine("No");
                            return;
                        }
                        compVisited[j] = true;
                    } else {
                        if (!compVisited[j]) {
                            out.printLine("No");
                            return;
                        }
                    }
                }
            }

            // ----- 4) Final colour assignment -----
            for (int i = 0; i < n; ++i) {
                if (colour[i] == -1) {
                    colour[i] = 0;                 // colour 0 corresponds to 'a'
                }
            }

            // ----- 5) Output -----
            out.printLine("Yes");
            for (int c : colour) {
                out.print(LETTERS[c]);
            }
            out.printLine();
        }

        /** @return index of a vertex that is adjacent to *all* other vertices,
                    or –1 if none exists. */
        private int findUniversalVertex(boolean[][] g) {
            for (int i = 0; i < g.length; ++i) {
                if (allAdjacent(g[i])) {
                    return i;
                }
            }
            return -1;
        }

        /** Helper that checks whether a whole row of the adjacency matrix
                contains only true values (i.e. the vertex is adjacent to everyone). */
        private static boolean allAdjacent(boolean[] row) {
            for (boolean b : row) if (!b) return false;
            return true;
        }

        /** @return the first vertex whose colour is still –1 (i.e. not yet assigned). */
        private int findFirstNonHub(int[] colour) {
            for (int i = 0; i < colour.length; ++i) {
                if (colour[i] == -1) return i;
            }
            return -1;
        }

        /** Standard depth‑first search that marks reachable vertices as visited
                and assigns them colour 0 (which later becomes the letter ‘a’). */
        private void dfs(int v, boolean[][] g, boolean[] visited, int[] colour) {
            visited[v] = true;
            for (int i = 0; i < g.length; ++i) {
                if (g[v][i] && !visited[i] && colour[i] == -1) {
                    dfs(i, g, visited, colour);
                }
            }
        }
    }

    /** -------------------------------------------------------------
     *  Program start‑up
     *  ----------------------------------------------------------- */
    public static void main(String[] args) throws Exception {
        // Using try‑with‑resources automatically closes all streams.
        try (InputStream inStream = System.in;
             OutputStream outStream = System.out) {

            FastScanner scanner = new FastScanner(inStream);
            OutputWriter writer = new OutputWriter(outStream);

            new Solver().solve(scanner, writer);
        }
    }
}

import java.io.*;
import java.util.Arrays;

/**
 * Entry point of the program.
 * Reads the graph, solves the task and prints the result.
 */
public class Main {

    public static void main(String[] args) {
        FastScanner in = new FastScanner(System.in);
        FastPrintWriter out = new FastPrintWriter(System.out);
        new Graph().solve(in, out);
        out.close();
    }

    /**
     * Core logic that manipulates the graph.
     */
    static class Graph {

        /**
         * Solves the problem for a single test case.
         *
         * @param scanner   input reader
         * @param printer   output writer
         */
        void solve(FastScanner scanner, FastPrintWriter printer) {
            // ----- read input -------------------------------------------------
            int vertexCount = scanner.nextInt();
            int edgeCount   = scanner.nextInt();

            boolean[][] adj = new boolean[vertexCount][vertexCount];
            for (int i = 0; i < edgeCount; i++) {
                int u = scanner.nextInt() - 1;
                int v = scanner.nextInt() - 1;
                adj[u][v] = adj[v][u] = true;
            }

            // ----- find a suitable "anchor" vertex (posA) --------------------
            int anchor = findAnchor(adj);
            if (anchor == -1) {
                printer.println("No");
                return;
            }

            // ----- assign provisional categories ----------------------------
            char[] label = assignLabels(adj, anchor);

            // ----- validate the labeling ------------------------------------
            if (!isValidLabeling(adj, label)) {
                printer.println("No");
                return;
            }

            // ----- output ----------------------------------------------------
            printer.println("Yes");
            printer.println(new String(label));
        }

        /**
         * Tries to locate a vertex that participates in an induced
         * P₃ (path of length 2) – i‑j‑k with i‑k missing.
         *
         * @return index of the middle vertex (j) of such a pattern,
         *         or –1 if none exists.
         */
        private int findAnchor(boolean[][] adj) {
            int n = adj.length;
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < n; j++) {
                    if (i == j) continue;
                    for (int k = 0; k < n; k++) {
                        if (i == k || j == k) continue;
                        // i-j and j-k are edges, but i-k is not
                        if (adj[i][j] && adj[j][k] && !adj[i][k]) {
                            return j;               // j is the "posA"
                        }
                    }
                }
            }
            return -1; // no such pattern found
        }

        /**
         * Determines the preliminary letter for each vertex:
         *   - 'a' for the anchor vertex,
         *   - 'b' for vertices adjacent to the anchor,
         *   - 'c' for vertices not adjacent to the anchor.
         *
         * Afterwards, some 'b' vertices may be upgraded to 'a'
         * when they are also non‑adjacent to a 'c' vertex.
         *
         * @param adj   adjacency matrix
         * @param anchor index of the anchor vertex
         * @return char array containing the final labels
         */
        private char[] assignLabels(boolean[][] adj, int anchor) {
            int n = adj.length;
            char[] label = new char[n];
            Arrays.fill(label, 'b');
            label[anchor] = 'a';

            // Vertices that are NOT neighbours of the anchor become 'c'
            for (int i = 0; i < n; i++) {
                if (i != anchor && !adj[anchor][i]) {
                    label[i] = 'c';
                }
            }

            // If a 'b' vertex has no edge to any 'c' vertex, it can be upgraded to 'a'
            for (int i = 0; i < n; i++) {
                if (label[i] == 'b') {
                    for (int j = 0; j < n; j++) {
                        if (label[j] == 'c' && !adj[i][j]) {
                            label[i] = 'a';
                            break;
                        }
                    }
                }
            }
            return label;
        }

        /**
         * Checks whether the current labeling respects all given edges.
         *
         * The rule is:
         *   - If an edge exists, the absolute difference of the letters must be ≤ 1,
         *   - If an edge does NOT exist, the absolute difference must be ≥ 2.
         *
         * @param adj adjacency matrix
         * @param label labeling to validate
         * @return true if the labeling is consistent with the graph
         */
        private boolean isValidLabeling(boolean[][] adj, char[] label) {
            int n = adj.length;
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < n; j++) {
                    if (i == j) continue;

                    int diff = Math.abs(label[i] - label[j]);

                    if (adj[i][j]) {
                        if (diff > 1) return false;
                    } else {
                        if (diff < 2) return false;
                    }
                }
            }
            return true;
        }
    }

    /**
     * Fast input utilities.
     */
    static class FastScanner {
        private final InputStream stream;
        private final byte[] buffer = new byte[1024];
        private int pointer = 0, length = 0;

        FastScanner(InputStream stream) {
            this.stream = stream;
        }

        private int readByte() throws IOException {
            if (pointer >= length) {
                length = stream.read(buffer);
                pointer = 0;
                if (length <= 0) return -1;
            }
            return buffer[pointer++];
        }

        int nextInt() throws IOException {
            int c = skipNonDigit();
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = readByte();
            }
            int value = 0;
            do {
                value = value * 10 + (c - '0');
                c = readByte();
            } while (isDigit(c));
            return value * sign;
        }

        private int skipNonDigit() throws IOException {
            int c;
            do {
                c = readByte();
            } while (c <= ' ' && c != -1);
            return c;
        }

        private boolean isDigit(int c) {
            return c >= '0' && c <= '9';
        }
    }

    /**
     * Fast output utilities.
     */
    static class FastPrintWriter {
        private final PrintWriter writer;

        FastPrintWriter(OutputStream out) {
            this.writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(out)));
        }

        void println(Object obj) {
            writer.println(obj);
        }

        void close() {
            writer.close();
        }
    }
}

import java.io.*;
import java.util.Arrays;

/**
 * Refactored solution for the problem.
 * The program reads a graph, tries to assign each vertex one of the
 * characters 'a', 'b', 'c' and checks whether the assignment satisfies
 * the required adjacency rules.
 */
public class CodeForcesC {

    /* --------------------------------------------------------------------- */
    /* I/O helpers – unchanged from the original source (only minor formatting) */
    /* --------------------------------------------------------------------- */

    private static final class InputReader {
        private final InputStream stream;
        private final byte[] buffer;
        private int currentIndex;
        private int bytesRead;

        public InputReader(InputStream stream) {
            this.stream = stream;
            this.buffer = new byte[131_072];
        }

        private int read() throws IOException {
            if (currentIndex >= bytesRead) {
                currentIndex = 0;
                bytesRead = stream.read(buffer);
                if (bytesRead <= 0) {
                    return -1;
                }
            }
            return buffer[currentIndex++];
        }

        public String readString() throws IOException {
            int c = read();
            while (!isPrintable(c)) {
                c = read();
            }
            StringBuilder sb = new StringBuilder();
            do {
                sb.appendCodePoint(c);
                c = read();
            } while (isPrintable(c));
            return sb.toString();
        }

        public int readInt() throws Exception {
            int c = read();
            while (!isPrintable(c)) {
                c = read();
            }
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            int result = 0;
            do {
                if (c < '0' || c > '9') {
                    throw new InputMismatchException();
                }
                result = result * 10 + (c - '0');
                c = read();
            } while (isPrintable(c));
            return result * sign;
        }

        public long readLong() throws Exception {
            int c = read();
            while (!isPrintable(c)) {
                c = read();
            }
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            long result = 0;
            do {
                if (c < '0' || c > '9') {
                    throw new InputMismatchException();
                }
                result = result * 10 + (c - '0');
                c = read();
            } while (isPrintable(c));
            return result * sign;
        }

        public double readDouble() throws Exception {
            int c = read();
            while (!isPrintable(c)) {
                c = read();
            }
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            boolean fraction = false;
            double mult = 1;
            double result = 0;
            do {
                if ((c == 'e') || (c == 'E')) {
                    return sign * result * Math.pow(10, readInt());
                }
                if ((c < '0') || (c > '9')) {
                    if (c == '.' && !fraction) {
                        fraction = true;
                        c = read();
                        continue;
                    }
                    throw new InputMismatchException();
                }
                if (fraction) {
                    mult /= 10;
                    result += (c - '0') * mult;
                    c = read();
                } else {
                    result *= 10;
                    result += (c - '0');
                    c = read();
                }
            } while (isPrintable(c));
            return sign * result;
        }

        private boolean isPrintable(int c) {
            return c > 32 && c < 127;
        }
    }

    private static final class OutputWriter {
        private final PrintWriter writer;

        public OutputWriter(OutputStream out) {
            writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(out)));
        }

        public OutputWriter(Writer out) {
            writer = new PrintWriter(out);
        }

        public void print(Object... objects) {
            for (int i = 0; i < objects.length; i++) {
                if (i != 0) {
                    writer.print(' ');
                }
                writer.print(objects[i]);
            }
        }

        public void println(Object... objects) {
            print(objects);
            writer.println();
        }

        public void close() {
            writer.close();
        }

        public void flush() {
            writer.flush();
        }
    }

    /* --------------------------------------------------------------------- */
    /* Core solving logic – clear, step‑by‑step implementation                */
    /* --------------------------------------------------------------------- */

    private static void solve(InputReader in, OutputWriter out) throws Exception {
        /* ---------- 1. read input ------------------------------------------------ */
        final int n = in.readInt();                     // number of vertices
        final boolean[][] adj = new boolean[n + 1][n + 1]; // adjacency matrix
        final int[] degree = new int[n + 1];            // vertex degrees
        final int m = in.readInt();                     // number of edges

        for (int i = 0; i < m; i++) {
            int u = in.readInt();
            int v = in.readInt();
            adj[u][v] = adj[v][u] = true;
            degree[u]++;
            degree[v]++;
        }

        /* ---------- 2. assign labels ------------------------------------------- */
        final char[] label = new char[n + 1];           // result labels
        char lastAssigned = 'c';                        // remembers the previous label
        boolean continueLoop = true;                    // drives the outer while‑loop
        int cursor = 1;                                 // current vertex we are processing

        while (continueLoop && cursor <= n) {
            if (degree[cursor] != n - 1) {              // vertex is **not** universal
                // Choose 'a' or 'c' depending on the previously used label
                char currentLabel = (lastAssigned == 'c') ? 'a' : 'c';
                label[cursor] = currentLabel;
                lastAssigned = currentLabel;

                // Propagate the same label to neighbours that are not universal,
                // otherwise give them 'b'.
                for (int nb = cursor + 1; nb <= n; nb++) {
                    if (adj[cursor][nb]) {
                        if (degree[nb] != n - 1) {
                            label[nb] = currentLabel;
                        } else {
                            label[nb] = 'b';
                        }
                    }
                }

                // Find the next vertex that is **not** connected to `cursor`
                // and continue the search from there.
                continueLoop = false;
                for (int nb = cursor + 1; nb <= n; nb++) {
                    if (!adj[cursor][nb]) {
                        cursor = nb;
                        continueLoop = true;
                        break;
                    }
                }
            } else {                                     // vertex is universal → label 'b'
                label[cursor] = 'b';
                cursor++;
            }
        }

        /* ---------- 3. validation ------------------------------------------------ */
        boolean isValid = true;
        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= n; j++) {
                if (i == j) {
                    continue;
                }
                int diff = Math.abs(label[i] - label[j]); // numeric difference of chars
                boolean edgeExists = adj[i][j];

                if (diff == 2) { // 'a' (97) vs 'c' (99)
                    if (edgeExists) {
                        isValid = false; // an 'a'–'c' edge must NOT exist
                    }
                } else { // any other pair must be adjacent
                    if (!edgeExists) {
                        isValid = false;
                    }
                }
            }
        }

        /* ---------- 4. output ---------------------------------------------------- */
        if (isValid) {
            out.println("Yes");
            for (int i = 1; i <= n; i++) {
                out.print(label[i]);
            }
            out.println();
        } else {
            out.println("No");
        }
    }

    /* --------------------------------------------------------------------- */
    /* Entry point – unchanged except for delegating to the refactored solve   */
    /* --------------------------------------------------------------------- */

    public static void main(String[] args) throws Exception {
        InputReader in = new InputReader(System.in);
        OutputWriter out = new OutputWriter(System.out);
        solve(in, out);
        out.close();
    }
}

import java.io.*;
import java.util.*;

public class Main {

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(System.out);
        new Solver().solve(1, fs, out);
        out.close();
    }

    /** Entry point of the solution */
    static class Solver {
        /** Reads the input, processes it and prints the answer */
        void solve(int testNumber, FastScanner in, PrintWriter out) {
            int n = in.nextInt();          // number of vertices
            int m = in.nextInt();          // number of edges

            // ---- build adjacency matrix and degree array ----
            boolean[][] g = new boolean[n][n];
            int[] deg = new int[n];
            for (int i = 0; i < m; ++i) {
                int u = in.nextInt() - 1;
                int v = in.nextInt() - 1;
                if (u == v) continue;
                g[u][v] = g[v][u] = true;
                deg[u]++;
                deg[v]++;
            }

            // ---- assign provisional letters ----
            char[] ans = new char[n];
            Arrays.fill(ans, (char) 0);    // 0 marks “unassigned”

            // vertices that are adjacent to *all* others become 'b'
            for (int i = 0; i < n; ++i) {
                if (deg[i] == n - 1) {
                    ans[i] = 'b';
                }
            }

            // choose one still‑unassigned vertex as a seed for 'a' / 'c' propagation
            int seed = -1;
            for (int i = 0; i < n; ++i) {
                if (ans[i] == 0) {
                    seed = i;
                    break;
                }
            }
            if (seed != -1) {
                ans[seed] = 'a';
                // every other still‑unassigned vertex inherits 'a' or 'c' depending on adjacency to the seed
                for (int i = 0; i < n; ++i) {
                    if (ans[i] != 0) continue;
                    ans[i] = g[seed][i] ? 'a' : 'c';
                }
            }

            // if after propagation any vertex is still unassigned → impossible
            for (char c : ans) {
                if (c == 0) {
                    out.println("No");
                    return;
                }
            }

            // ---- validation according to the problem statement ----
            for (int i = 0; i < n; ++i) {
                char ci = ans[i];
                for (int j = 0; j < n; ++j) {
                    if (i == j) continue;
                    char cj = ans[j];
                    if (ci == 'a') {
                        // two 'a' vertices must be adjacent; 'a'–'c' must not be adjacent
                        if (cj == 'a' && !g[i][j]) {
                            out.println("No");
                            return;
                        }
                        if (cj == 'c' && g[i][j]) {
                            out.println("No");
                            return;
                        }
                    } else if (ci == 'c') {
                        // two 'c' vertices must be adjacent; 'c'–'a' must not be adjacent
                        if (cj == 'c' && !g[i][j]) {
                            out.println("No");
                            return;
                        }
                        if (cj == 'a' && g[i][j]) {
                            out.println("No");
                            return;
                        }
                    }
                    // 'b' does not impose extra constraints (it is adjacent to everyone by construction)
                }
            }

            // all checks passed → output the labeling
            out.println("Yes");
            out.println(new String(ans));
        }
    }

    /** Minimal fast scanner used by the solution */
    static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner(InputStream stream) {
            br = new BufferedReader(new InputStreamReader(stream));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    throw new UncheckedIOException(e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.util.*;

public class GraphLabeler {

    /* Constants for the three possible labels */
    private static final char LABEL_A = 'a';
    private static final char LABEL_B = 'b';
    private static final char LABEL_C = 'c';

    /** Entry point – reads the graph, assigns labels and prints the result. */
    public static void main(String[] args) {
        Graph graph = Graph.readGraph(new Scanner(System.in));
        char[] labels = assignLabels(graph);
        if (labels == null) {
            System.out.println("No");
            return;
        }
        System.out.println("Yes\n" + new String(labels));
    }

    /** Simple container for the adjacency matrix and degree array of the graph. */
    private static class Graph {
        final int size;                     // number of vertices
        final boolean[][] adjacency;         // adjacency matrix
        final int[] degree;                  // degree of each vertex

        Graph(int size, boolean[][] adjacency, int[] degree) {
            this.size = size;
            this.adjacency = adjacency;
            this.degree = degree;
        }

        /** Reads the graph description from the provided Scanner. */
        static Graph readGraph(Scanner scanner) {
            int n = scanner.nextInt();               // number of vertices
            int m = scanner.nextInt();               // number of edges
            boolean[][] adj = new boolean[n][n];
            int[] deg = new int[n];

            for (int i = 0; i < m; i++) {
                int u = scanner.nextInt() - 1;       // convert to 0‑based
                int v = scanner.nextInt() - 1;
                adj[u][v] = adj[v][u] = true;
                deg[u]++;
                deg[v]++;
            }
            return new Graph(n, adj, deg);
        }
    }

    /** Assigns the labels 'a', 'b', 'c' to vertices following the algorithm. */
    private static char[] assignLabels(Graph graph) {
        int n = graph.size;
        char[] labels = new char[n];
        Arrays.fill(labels, LABEL_B);               // initialise all to 'b'

        /* -----------------------------------------------------------------
         * 1. Find the first vertex that is still labelled 'b' and turn it
         *    into 'a'. Then propagate 'a' to its neighbours that are still
         *    'b'.
         * ----------------------------------------------------------------- */
        int firstNotB = findFirstNot(labels, LABEL_B);
        if (firstNotB != -1) {
            labels[firstNotB] = LABEL_A;
            propagateLabel(graph, labels, firstNotB, LABEL_A);
        }

        /* -----------------------------------------------------------------
         * 2. Find a vertex still labelled 'b' (or 'a') and turn it into 'a'
         *    again – this step mirrors the original logic, but we now use a
         *    helper that respects multiple excluded labels.
         * ----------------------------------------------------------------- */
        int firstNotAB = findFirstNot(labels, LABEL_A, LABEL_B);
        if (firstNotAB != -1) {
            labels[firstNotAB] = LABEL_A;
            propagateLabel(graph, labels, firstNotAB, LABEL_A);
        }

        /* -----------------------------------------------------------------
         * 3. Find a vertex still labelled 'b' and turn it into 'c', then
         *    propagate 'c' to its neighbours that are still 'b'.
         * ----------------------------------------------------------------- */
        int firstNotABC = findFirstNot(labels, LABEL_A, LABEL_B, LABEL_C);
        if (firstNotABC != -1) {
            labels[firstNotABC] = LABEL_C;
            propagateLabel(graph, labels, firstNotABC, LABEL_C);
        }

        /* -----------------------------------------------------------------
         * 4. Validate the final labelling against the required adjacency
         *    constraints. If validation fails, the whole process is aborted.
         * ----------------------------------------------------------------- */
        if (!isAssignmentValid(graph, labels)) {
            return null;
        }
        return labels;
    }

    /** Returns the index of the first element that does NOT match any of the
     *  supplied excluded characters. */
    private static int findFirstNot(char[] arr, char... exclude) {
        for (int i = 0; i < arr.length; i++) {
            if (!contains(exclude, arr[i])) {
                return i;
            }
        }
        return -1;
    }

    private static boolean contains(char[] set, char value) {
        for (char c : set) {
            if (c == value) {
                return true;
            }
        }
        return false;
    }

    /** BFS‑style propagation of a label from a starting vertex. */
    private static void propagateLabel(Graph graph, char[] labels,
                                       int start, char targetLabel) {
        Queue<Integer> queue = new ArrayDeque<>();
        queue.add(start);

        while (!queue.isEmpty()) {
            int v = queue.poll();
            for (int neighbor = 0; neighbor < graph.size; neighbor++) {
                if (graph.adjacency[v][neighbor] && labels[neighbor] == LABEL_B) {
                    labels[neighbor] = targetLabel;
                    queue.add(neighbor);
                }
            }
        }
    }

    /** Checks whether the current labelling respects the adjacency rules:
     *   - adjacent vertices must have labels differing by at most 1,
     *   - non‑adjacent vertices must not differ by exactly 2.
     */
    private static boolean isAssignmentValid(Graph graph, char[] labels) {
        for (int i = 0; i < graph.size; i++) {
            for (int j = i + 1; j < graph.size; j++) {
                char li = labels[i];
                char lj = labels[j];
                boolean adjacent = graph.adjacency[i][j];
                int diff = Math.abs(li - lj);

                if ((diff <= 1 && !adjacent) || (diff == 2 && adjacent)) {
                    return false;
                }
            }
        }
        return true;
    }
}

