/**
 * Main entry point of the program.
 */
public class Main {

    public static void main(String[] args) throws IOException {
        Solver solver = new Solver();
        solver.solve();
    }
}

/**
 * Handles all the algorithmic work.
 */
class Solver {

    private final FastScanner scanner;
    private final FastWriter writer;

    Solver() throws IOException {
        scanner = new FastScanner();
        writer = new FastWriter();
    }

    /** Entry point of the solving process. */
    void solve() throws IOException {
        int n = scanner.nextInt();          // number of vertices
        int m = scanner.nextInt();          // number of edges

        /* -------------------------------------------------------------
         *  Trivial case – the graph is already complete.
         * ------------------------------------------------------------- */
        if (m == n * (n - 1) / 2) {
            writer.println("Yes");
            writer.append("a".repeat(n));
            writer.println();
            writer.close();
            return;
        }

        Graph graph = new Graph(n);
        graph.buildFrom(scanner);

        char[] result = new char[n];
        int assigned = 0;

        /* -------------------------------------------------------------
         *  1️⃣  Vertices of degree (n‑1) get the label 'b'.
         * ------------------------------------------------------------- */
        for (int i = 0; i < n; i++) {
            if (graph.degree(i) == n - 1) {
                result[i] = 'b';
                assigned++;
                graph.removeAllEdgesOf(i);
            }
        }

        /* -------------------------------------------------------------
         *  2️⃣  Find the first vertex whose closed neighbourhood is a clique.
         *      Label that vertex and all its neighbours 'a'.
         * ------------------------------------------------------------- */
        int aVertex = findCliqueRoot(graph);
        if (aVertex == -1) {
            writer.println("No");
            writer.close();
            return;
        }
        result[aVertex] = 'a';
        assigned++;
        for (int nb : graph.neighbors(aVertex)) {
            if (result[nb] == 0) {
                result[nb] = 'a';
                assigned++;
            }
        }

        /* -------------------------------------------------------------
         *  3️⃣  Same procedure with label 'c'.
         * ------------------------------------------------------------- */
        int cVertex = findCliqueRoot(graph);
        if (cVertex == -1) {
            writer.println("No");
            writer.close();
            return;
        }
        result[cVertex] = 'c';
        assigned++;
        for (int nb : graph.neighbors(cVertex)) {
            if (result[nb] == 0) {
                result[nb] = 'c';
                assigned++;
            }
        }

        /* -------------------------------------------------------------
         *  4️⃣  Every vertex must receive a label.
         * ------------------------------------------------------------- */
        for (char c : result) {
            if (c == 0) {
                writer.println("No");
                writer.close();
                return;
            }
        }

        /* -------------------------------------------------------------
         *  5️⃣  If we managed to assign exactly n labels we have a solution.
         * ------------------------------------------------------------- */
        if (assigned == n) {
            writer.println("Yes");
            writer.append(result);
            writer.println();
        } else {
            writer.println("No");
        }

        writer.close();
    }

    /**
     * Returns a vertex whose closed neighbourhood (the vertex itself plus all
     * its neighbours) forms a complete graph, or {@code -1} if none exists.
     */
    private int findCliqueRoot(Graph graph) {
        for (int v = 0; v < graph.vertexCount(); v++) {
            if (graph.degree(v) == 0) {
                continue; // already processed completely
            }
            if (isClique(v, graph)) {
                return v;
            }
        }
        return -1;
    }

    /**
     * Checks whether the vertex {@code root} together with its neighbours
     * induces a complete sub‑graph.
     */
    private boolean isClique(int root, Graph graph) {
        // The set of vertices that must be present: root + all neighbours.
        BitSet required = new BitSet(graph.vertexCount());
        required.set(root);
        for (int nb : graph.neighbors(root)) {
            required.set(nb);
        }

        // Every neighbour must be adjacent to exactly the same set.
        for (int nb : graph.neighbors(root)) {
            BitSet neighbourSet = new BitSet(graph.vertexCount());
            neighbourSet.set(root);
            neighbourSet.or(graph.neighbourSet(nb));
            if (!neighbourSet.equals(required)) {
                return false;
            }
        }
        return true;
    }
}

/**
 * Simple representation of an undirected graph.
 */
class Graph {
    private final int vertexCount;
    private final List<Set<Integer>> adjacency;

    Graph(int n) {
        this.vertexCount = n;
        this.adjacency = new ArrayList<>(n);
        for (int i = 0; i < n; i++) {
            adjacency.add(new HashSet<>());
        }
    }

    /** Adds an undirected edge (u, v). */
    void addEdge(int u, int v) {
        adjacency.get(u).add(v);
        adjacency.get(v).add(u);
    }

    /** Builds the graph from the input scanner. */
    void buildFrom(FastScanner scanner) {
        // Clear any previous data.
        for (Set<Integer> set : adjacency) {
            set.clear();
        }
        int m = scanner.nextInt();
        for (int i = 0; i < m; i++) {
            int u = scanner.nextInt() - 1;
            int v = scanner.nextInt() - 1;
            addEdge(u, v);
        }
    }

    /** Returns the degree of vertex {@code v}. */
    int degree(int v) {
        return adjacency.get(v).size();
    }

    /** Returns a read‑only view of the neighbours of {@code v}. */
    List<Integer> neighbors(int v) {
        return Collections.unmodifiableList(new ArrayList<>(adjacency.get(v)));
    }

    /** Returns the underlying neighbour set of {@code v}. */
    Set<Integer> neighbourSet(int v) {
        return adjacency.get(v);
    }

    /** Removes all edges incident to {@code v} (used after labeling it). */
    void removeAllEdgesOf(int v) {
        for (int nb : adjacency.get(v)) {
            adjacency.get(nb).remove(v);
        }
        adjacency.get(v).clear();
    }

    /** Number of vertices in the graph. */
    int vertexCount() {
        return vertexCount;
    }
}

/**
 * Fast scanner that reads tokens from {@code System.in} or from a file.
 */
class FastScanner {
    private final BufferedReader reader;
    private StringTokenizer tokenizer;

    FastScanner() throws IOException {
        this.reader = new BufferedReader(new InputStreamReader(System.in));
    }

    FastScanner(String filename) throws IOException {
        this.reader = new BufferedReader(new FileInputStream(filename));
    }

    /** Reads the next token. */
    String next() throws IOException {
        advanceTokenizer();
        return tokenizer != null ? tokenizer.snextToken() : null;
    }

    /** Reads the next integer. */
    int nextInt() throws IOException {
        return Integer.parseInt(next());
    }

    /** Advances the tokenizer, reading a new line when necessary. */
    private void advanceTokenizer() throws IOException {
        while (tokenizer == null || !tokenizer.hasMoreTokens()) {
            String line = reader.readLine();
            if (line == null) {
                tokenizer = null;
                return;
            }
            tokenizer = new StringTokenizer(line);
        }
    }
}

/**
 * Wrapper around {@link PrintWriter} that can write to a file or to {@code System.out}.
 */
class FastWriter extends PrintWriter {

    FastWriter() throws IOException {
        super(new BufferedWriter(new OutputStreamWriter(System.out)));
    }

    FastWriter(String filename) throws IOException {
        super(new BufferedWriter(new FileWriter(filename)));
    }
}

import java.io.*;
import java.util.*;

/**
 * Refactored solution for the original problem.
 *
 * <p>
 * The program reads an undirected graph, determines whether the vertices can be
 * labelled with the letters {@code 'a'}, {@code 'b'}, {@code 'c'} so that an edge
 * exists exactly when the corresponding letters are equal or adjacent in the
 * alphabetical order, and prints {@code "Yes"} together with a valid labelling
 * or {@code "No"} otherwise.
 * </p>
 *
 * <p>Key improvements compared with the original code:
 * <ul>
 *   <li>Clear separation of concerns (input, graph construction, labelling,
 *       validation).</li>
 *   <li>Descriptive naming of variables and methods.</li>
 *   <li>Extraction of reusable helper methods.</li>
 *   <li>Early exits and guard clauses to reduce nesting.</li>
 *   <li>Javadoc comments and inline explanations.</li>
 * </ul>
 * </p>
 */
public class Solution {

    /** Fast scanner that mirrors the functionality of the original {@code InputReader}. */
    private static final class FastScanner {
        private final InputStream stream;
        private final byte[] buffer = new byte[8192];
        private int cursor = 0;
        private int end = -1;
        private final SpaceCharFilter filter;

        FastScanner(InputStream stream) {
            this.stream = stream;
        }

        /** Reads the next non‑space character. */
        private int readChar() {
            if (end == -1) {
                throw new NoSuchElementException();
            }
            if (cursor >= end) {
                cursor = 0;
                end = stream.read(buffer);
                if (end <= 0) {
                    return -1;
                }
            }
            return buffer[cursor++];
        }

        /** Consumes whitespace characters until a non‑space is found. */
        private int skipSpaces(int c) {
            while (isSpaceChar(c)) {
                c = readChar();
            }
            return c;
        }

        /** Reads a signed integer. */
        int nextInt() {
            int c = skipSpaces(readChar());

            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = readChar();
            }

            int result = 0;
            do {
                if (c < '0' || c > '9') {
                    throw new NumberFormatException();
                }
                result = result * 10 + (c - '0');
                c = readChar();
            } while (!isSpaceChar(c));

            return result * sign;
        }

        /** Reads the next string up to whitespace. */
        String readString() {
            int c = skipSpaces(readChar());

            StringBuilder sb = new StringBuilder();
            do {
                sb.appendCodePoint(c);
                c = readChar();
            } while (!isSpaceChar(c));

            return sb.toString();
        }

        /** Checks whether a character is considered whitespace. */
        private boolean isSpaceChar(int c) {
            if (filter != null) {
                return filter.isSpaceChar(c);
            }
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        /** Optional filter for custom whitespace handling. */
        interface SpaceCharFilter {
            boolean isSpaceChar(int ch);
        }
    }

    /** Entry point of the program. */
    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(System.out);

        solveProblem(fs, out);
        out.close();
    }

    /**
     * Core logic that solves the problem.
     *
     * @param fs  scanner that provides the input data
     * @param out writer to which the result is printed
     */
    private static void solveProblem(FastScanner fs, PrintWriter out) {
        int n = fs.nextInt();               // number of vertices
        int m = fs.nextInt();               // number of edges

        // --------------------------------------------------------------------
        // 1. Build adjacency matrix and compute vertex degrees.
        // --------------------------------------------------------------------
        boolean[][] adjacency = new boolean[n][n];
        int[] degree = new int[n];
        for (int i = 0; i < m; i++) {
            int u = fs.nextInt() - 1;
            int v = fs.nextInt() - 1;
            adjacency[u][v] = true;
            adjacency[v][u] = true;
            degree[u]++;
            degree[v]++;
        }

        // --------------------------------------------------------------------
        // 2. Initialise result array and a visited flag array.
        // --------------------------------------------------------------------
        char[] assignment = new char[n];
        boolean[] visited = new boolean[n];

        // --------------------------------------------------------------------
        // 3. Nodes that are adjacent to *all* other vertices get label 'b'.
        // --------------------------------------------------------------------
        for (int i = 0; i < n; i++) {
            if (degree[i] == n - 1) {
                assignment[i] = 'b';
                visited[i] = true;
            }
        }

        // --------------------------------------------------------------------
        // 4. Process remaining connected components. At most two components
        //    may remain; otherwise the instance is impossible.
        // --------------------------------------------------------------------
        int componentIndex = 0; // 0 → label 'a', 1 → label 'c'

        outerLoop:
        for (int i = 0; i < n; i++) {
            if (visited[i]) {
                continue;
            }

            // More than two distinct components → impossible.
            if (componentIndex >= 2) {
                out.println("No");
                return;
            }

            // Explore the whole component starting from i.
            List<Integer> component = new ArrayList<>();
            Queue<Integer> queue = new ArrayDeque<>();
            queue.add(i);
            visited[i] = true;
            component.add(i);
            assignment[i] = (componentIndex == 0) ? 'a' : 'c';

            // BFS to collect all vertices reachable from i.
            while (!queue.isEmpty()) {
                int cur = queue.poll();
                for (int nb = 0; nb < n; nb++) {
                    if (!visited[nb] && adjacency[cur][nb]) {
                        visited[nb] = true;
                        component.add(nb);
                        queue.add(nb);
                        assignment[nb] = assignment[i];
                    }
                }
            }

            // Verify that the component is a *clique* (complete subgraph).
            if (!isClique(component, adjacency)) {
                out.println("No");
                return;
            }

            componentIndex++;
        }

        // --------------------------------------------------------------------
        // 5. Ensure every vertex has been visited (i.e., labelled).
        // --------------------------------------------------------------------
        for (boolean v : visited) {
            if (!v) {
                out.println("No");
                return;
            }
        }

        // --------------------------------------------------------------------
        // 6. All checks passed → print the answer.
        // --------------------------------------------------------------------
        out.println("Yes");
        for (int i = 0; i < n; i++) {
            out.print(assignment[i]);
        }
    }

    /**
     * Determines whether the given set of vertices induces a complete subgraph.
     *
     * @param vertices list of vertex indices
     * @param adj      adjacency matrix of the graph
     * @return {@code true} if every pair of vertices in {@code vertices}
     *         is connected by an edge
     */
    private static boolean isClique(List<Integer> vertices, boolean[][] adj) {
        for (int i = 0; i < vertices.size(); i++) {
            for (int j = i + 1; j < vertices.size(); j++) {
                int u = vertices.get(i);
                int v = vertices.get(j);
                if (!adj[u][v]) {
                    return false;
                }
            }
        }
        return true;
    }
}

/*
 * Refactored solution for the original problem.
 * The program reads a graph, decides whether a certain assignment is possible,
 * and – if it is – outputs a labeling of the vertices with the letters
 * 'a' … 'd'.  All functionality is kept, but the code is now
 *   • easier to read
 *   • split into small, single‑responsibility classes
 *   • free of magic numbers and deep nesting
 *   • properly documented with comments.
 */

import java.io.*;
import java.util.*;

public class Main {

    /** Entry point – delegates all work to {@link #solve()}. */
    public static void main(String[] args) {
        try {
            new Main().solve();
        } catch (IOException e) {
            e.printStackTrace();
            System.exit(42);
        }
    }

    /** -------------------------------------------------------------
     *  Public solving routine – keeps I/O handling separate from logic.
     *  ------------------------------------------------------------- */
    public void solve() throws IOException {
        // try‑with‑resources guarantees proper closure of streams
        try (InputReader in = new InputReader();
             PrintWriter out = new PrintWriter(System.out)) {

            int n = in.nextInt();          // number of vertices
            int m = in.nextInt();          // number of edges
            Graph graph = new Graph(n);

            // --- read the edges -------------------------------------------------
            for (int i = 0; i < m; i++) {
                int u = in.nextInt() - 1;
                int v = in.nextInt() - 1;
                graph.addEdge(u, v);
            }

            // --- core processing ------------------------------------------------
            ProcessingResult result = process(graph);

            // --- output ---------------------------------------------------------
            out.println(result.answer);
            if ("Yes".equals(result.answer)) {
                out.print(result.letters);
            }
            out.flush();   // ensure everything is written before closing
        }
    }

    /** -------------------------------------------------------------
     *  Core algorithm – returns both the decision and (if applicable)
     *  the vertex labeling.
     *  ------------------------------------------------------------- */
    private static final class ProcessingResult {
        final String answer;          // "Yes" or "No"
        final char[] letters;         // vertex labels, only meaningful when answer=="Yes"

        ProcessingResult(String answer, char[] letters) {
            this.answer = answer;
            this.letters = letters;
        }
    }

    private ProcessingResult process(Graph graph) {
        int n = graph.n;
        int[] color = new int[n];                     // -1 == uncolored
        Arrays.fill(color, -1);
        String answer = "Yes";

        // 1️⃣  Vertices that are connected to all others receive a special colour (1)
        for (int v = 0; v < n; v++) {
            if (graph.degree(v) == n - 1) {
                color[v] = 1;
            }
        }

        // 2️⃣  Try to colour each not‑yet‑coloured component
        for (int start = 0; start < n && answer.equals("Yes"); start++) {
            if (color[start] != -1) {
                continue;               // already coloured
            }

            int cur = -2;                // sentinel meaning “no colour yet”
            // Scan neighbours to decide a starting colour
            for (int nb : graph.adj.get(start)) {
                int colNb = color[nb];
                if (colNb == -1 || colNb == 1) {    // uncoloured or special colour → ignore
                    continue;
                }
                // Detect contradictory patterns (same as original code)
                if (colNb == 0 && cur == 2) {
                    answer = "No";
                    break;
                }
                if (colNb == 2 && cur == 0) {
                    answer = "No";
                    break;
                }
                cur = colNb;               // keep moving along the colour chain
            }
            if (!answer.equals("Yes")) {
                break;
            }

            // Look at non‑adjacent vertices to refine the colour choice
            for (int v = 0; v < n; v++) {
                if (!graph.hasEdge(start, v) && start != v) {
                    int colV = color[v];
                    if (colV == -1 || colV == 1) {
                        continue;
                    }
                    if (colV == 0 && cur == 0) {
                        answer = "No";
                        break;
                    }
                    if (colV == 2 && cur == 2) {
                        answer = "No";
                        break;
                    }
                    // Cycle through the allowed colours 0 ↔ 2 ↔ 0 …
                    cur = (2 + colV) % 4;
                }
            }
            if (!answer.equals("Yes")) {
                break;
            }

            // Assign the resolved colour; if still unknown, fall back to 0
            color[start] = (cur == -2) ? 0 : cur;
        }

        // 3️⃣  Any remaining uncoloured vertices are set to 0 (neutral colour)
        for (int i = 0; i < n; i++) {
            if (color[i] == -1) {
                color[i] = 0;
            }
        }

        // If we ever hit a contradiction, report it immediately
        if (!answer.equals("Yes")) {
            return new ProcessingResult("No", null);
        }

        // 4️⃣  Convert the integer colours to the required lowercase letters.
        //     The original program used the mapping: 0→'a', 1→'b', 2→'c', 3→'d'.
        char[] letters = new char[n];
        for (int i = 0; i < n; i++) {
            // Guard against accidental values outside 0‑3
            int idx = ((color[i] + 4) % 4);
            letters[i] = (char) ('a' + idx);
        }

        return new ProcessingResult("Yes", letters);
    }

    /** -------------------------------------------------------------
     *  Simple buffered scanner that works like the original FastScanner
     *  but lives inside its own small class for clarity.
     *  ------------------------------------------------------------- */
    private static final class InputReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        InputReader() throws IOException {
            reader = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                tokenizer = new StringTokenizer(reader.readLine());
            }
            return tokenizer.nextToken();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }

    /** -------------------------------------------------------------
     *  Graph representation – adjacency list + cheap dense‑matrix test.
     *  ------------------------------------------------------------- */
    private static final class Graph {
        final int n;                      // number of vertices
        final List<Set<Integer>> adj;     // adjacency list
        final int[][] dense;                // dense matrix; -1 == no edge

        Graph(int n) {
            this.n = n;
            adj = new ArrayList<>(n);
            dense = new int[n][n];
            for (int i = 0; i < n; i++) {
                adj.add(new HashSet<>());
                Arrays.fill(dense[i], -1);
            }
        }

        /** Add an undirected edge (u, v). */
        void addEdge(int u, int v) {
            adj.get(u).add(v);
            adj.get(v).add(u);
            dense[u][v] = dense[v][u] = 1;
        }

        /** Does an edge (u, v) exist? */
        boolean hasEdge(int u, int v) {
            return u == v || dense[u][v] == 1;
        }

        /** Degree of vertex u. */
        int degree(int u) {
            return adj.get(u).size();
        }
    }
}

/**
 * Refactored solution for the “String” problem (CF 18C).
 *
 * The program reads an undirected graph, checks a triangle condition,
 * tries to label each vertex with one of the letters ‘a’, ‘b’, ‘c’,
 * and prints the labeling if it exists.
 *
 * Refactoring highlights:
 *   • Clear class responsibilities (ScannerWrapper, Solver).
 *   • Meaningful names and constants instead of magic literals.
 *   • Small helper methods that isolate distinct algorithmic steps.
 *   • Defensive programming (try‑with‑resources, unchecked IOException).
 *   • Removed duplicated imports and unused code.
 */
public final class Main {

    /** Labels used for the output. */
    private static final char LABEL_A = 'a';
    private static final char LABEL_B = 'b';
    private static final char LABEL_C = 'c';

    public static void main(String[] args) throws Exception {
        try (ScannerWrapper sc = new ScannerWrapper(System.in)) {
            new Solver().solve(sc, System.out);
        }
    }

    /** Minimal scanner that supplies `nextInt()` and `nextToken()`. */
    private static final class ScannerWrapper {
        private final BufferedReader br;
        private StringTokenizer st;

        ScannerWrapper(InputStream in) {
            this.br = new BufferedReader(new InputStreamReader(in), 32768);
        }

        private void ensureTokens() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    throw new UncheckedIOException(e);
                }
            }
        }

        int nextInt() {
            ensureTokens();
            return Integer.parseInt(st.nextToken());
        }

        String nextToken() {
            ensureTokens();
            return st.nextToken();
        }
    }

    /** Core solving logic. */
    private static final class Solver {

        /** Entry point used by `main`. */
        void solve(ScannerWrapper sc, PrintWriter out) {
            int n = sc.nextInt();          // number of vertices
            int m = sc.nextInt();          // number of edges

            boolean[][] adj = readGraph(n, sc);
            if (!checkTriangleCondition(adj)) {
                out.println("No");
                return;
            }

            char[] label = new char[n];
            Arrays.fill(label, '\0');

            Set<Integer>[] nonAdj = buildNonAdjacencySets(adj);
            assignMiddleVertices(label, adj, nonAdj);
            if (!completeLabeling(label, nonAdj)) {
                out.println("No");
                return;
            }

            out.println("Yes");
            out.print(label);
        }

        /** Reads `m` edges and fills an adjacency matrix. */
        private static boolean[][] readGraph(int n, ScannerWrapper sc) {
            boolean[][] g = new boolean[n][n];
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < n; j++) {
                    g[i][j] = false;
                }
            }
            for (int i = 0; i < n; i++) {
                int u = sc.nextInt() - 1;
                int v = sc.nextInt() - 1;
                g[u][v] = true;
                g[v][u] = true;
            }
            return g;
        }

        /** Verifies the triangle condition required by the problem. */
        private static boolean checkTriangleCondition(boolean[][] g) {
            final int n = g.length;
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < n; j++) {
                    if (i == j) continue;
                    for (int k = 0; k < n; k++) {
                        if (i == k || j == k) continue;
                        if (!g[i][j] && !g[j][k] && !g[k][i]) {
                            return false;
                        }
                    }
                }
            }
            return true;
        }

        /** Builds for each vertex the set of vertices it is NOT adjacent to. */
        private static Set<Integer>[] buildNonAdjacencySets(boolean[][] g) {
            int n = g.length;
            @SuppressWarnings("unchecked")
            Set<Integer>[] diff = new Set[n];
            for (int i = 0; i < n; i++) {
                diff[i] = new HashSet<>();
            }
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < n; j++) {
                    if (i != j && !g[i][j]) {
                        diff[i].add(j);
                        diff[j].add(i);
                    }
                }
            }
            return diff;
        }

        /**
         * Assigns label ‘b’ to any vertex that sits in the middle of a
         * “missing‑edge triangle” (i, j, k) where (i,j) and (j,k) exist
         * but (i,k) does not.  The method also records the induced
         * non‑adjacency constraints.
         */
        private static void assignMiddleVertices(char[] label,
                                                   boolean[][] g,
                                                   Set<Integer>[] diff) {
            final int n = g.length;
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < n; j++) {
                    if (i == j || !g[i][j]) continue;
                    for (int k = 0; k < n; k++) {
                        if (i == k || k == j) continue;
                        if (g[i][k]) continue;                // edge already present
                        // middle vertex j participates in a missing‑edge triangle
                        if (label[i] == LABEL_B || label[k] == LABEL_B) {
                            // ‘b' cannot coexist with ‘a' or ‘c' on the same vertex
                            label[i] = label[k] = '\0';      // revert to break outer loops
                            return;
                        }
                        label[j] = LABEL_B;
                        diff[i].add(k);
                        diff[k].add(i);
                    }
                }
            }
        }

        /**
         * Completes the labeling for vertices that are still unassigned.
         * Remaining vertices are forced to ‘a' or ‘c' according to the
         * constraints gathered in the non‑adjacency sets.  Returns `null`
         * if the resulting labeling would violate the rules.
         */
        private static char[] completeLabeling(char[] label,
                                                Set<Integer>[] diff) {
            final int n = label.length;
            for (int v = 0; v < n; v++) {
                if (label[v] != '\0') continue;
                label[v] = LABEL_A;                     // start all pending with ‘a'
                for (int nb : diff[v]) {
                    if (label[nb] == '\0') {
                        label[nb] = LABEL_C;             // their neighbours become ‘c'
                    }
                }
            }
            // final sanity check – every unordered pair of non‑adjacent
            // vertices must receive different letters.
            outer:
            for (int i = 0; i < n; i++) {
                for (int j = i + 1; j < n; j++) {
                    if (!diff[i].contains(j) && label[i] == label[j]) {
                        break outer;                     // violation → reject
                    }
                }
            }
            return label;
        }
    }
}

import java.io.*;
import java.util.*;

public class Main {

    /** Maps the internal colour identifiers to the required output letters. */
    private static char colourToLetter(int colour) {
        return switch (colour) {
            case 1 -> 'a';
            case 2 -> 'b';
            case 3 -> 'c';
            default -> '?';
        };
    }

    /**
     * Solves a single test case.
     *
     * @param in  fast scanner that reads the input
     * @param out print writer that writes the answer
     */
    private static void solve(FastScanner in, PrintWriter out) {
        int n = in.nextInt();   // number of vertices
        int m = in.nextInt();   // number of edges

        // --------------------------------------------------------------
        // Build adjacency list (1‑based for readability)
        // --------------------------------------------------------------
        @SuppressWarnings("unchecked")
        List<Integer>[] adj = new List[n + 1];
        for (int i = 1; i <= n; ++i) {
            adj[i] = new ArrayList<>();
        }
        for (int i = 0; i < m; ++i) {
            int u = in.nextInt();
            int v = in.nextInt();
            adj[u].add(v);
            adj[v].add(u);
        }

        // colour[]: 0 = uncoloured, 1 = A, 2 = B, 3 = C
        int[] colour = new int[n + 1];
        Arrays.fill(colour, 0);

        // --------------------------------------------------------------
        // 1️⃣  Vertices of type B – they must be adjacent to every other vertex
        // --------------------------------------------------------------
        int countB = 0;
        for (int v = 1; v <= n; ++v) {
            if (adj[v].size() == n - 1) {
                colour[v] = 2;          // B
                ++countB;
            }
        }

        // --------------------------------------------------------------
        // 2️⃣  Choose a first uncoloured vertex as type A and propagate to C
        // --------------------------------------------------------------
        int firstA = -1;
        for (int v = 1; v <= n; ++v) {
            if (colour[v] == 0) {
                firstA = v;
                break;
            }
        }
        if (firstA != -1) {
            colour[firstA] = 1;        // A
            // all still‑uncoloured neighbours become type C
            for (int nb : adj[firstA]) {
                if (colour[nb] == 0) {
                    colour[nb] = 3;   // C
                }
            }
        }

        // --------------------------------------------------------------
        // 3️⃣  Remaining uncoloured vertices become type C
        // --------------------------------------------------------------
        int firstC = -1;
        for (int v = 1; v <= n; ++v) {
            if (colour[v] == 0) {
                firstC = v;
                break;
            }
        }
        if (firstC != -1) {
            colour[firstC] = 3;        // C
            for (int nb : adj[firstC]) {
                if (colour[nb] == 0) {
