import java.util.Scanner;

/**
 * Refactored version of the original {@code A_GraphAndString} program.
 *
 * <p>Changes made for maintainability and readability:
 *
 * <ul>
 *   <li>Replaced primitive state constants with an {@link State} enum.</li>
 *   <li>Extracted all I/O handling into dedicated methods, using try‑with‑resources.</li>
 *   <li>Renamed methods to convey their intent (e.g. {@code markAllB},
 *       {@code markAllA}, {@code markAllC}).</li>
 *   <li>Removed duplicated code by centralising common operations
 *       (finding the first unmarked vertex, expanding components, etc.).</li>
 *   <li>Added extensive inline documentation and meaningful local variable names.</li>
 *   <li>Used {@code switch} expressions for character mapping and state handling.</li>
 *   <li>Improved argument validation and error reporting.</li>
 * </ul>
 *
 * The functional behaviour is identical to the original implementation.
 */
public class A_GraphAndString {

    /** Vertex states used during the assignment process. */
    private enum State {
        UNMARKED, A, B, C
    }

    /** Debug flag – when {@code true} the program reads from a fixed file. */
    private final boolean debug;

    /** Number of vertices. */
    private int n;

    /** Number of edges. */
    private int m;

    /** Adjacency matrix representation of the undirected graph. */
    private boolean[][] adjMatrix;

    /** Current state of each vertex. */
    private final State[] vertexState;

    /** Creates a new solver. */
    public A_GraphAndString(boolean debug) {
        this.debug = debug;
        this.vertexState = new State[0];   // will be resized after input reading
    }

    /** Reads the graph from the supplied {@link Scanner}. */
    private void readInput(Scanner sc) {
        n = sc.nextInt();
        m = sc.nextInt();
        if (debug) {
            System.out.printf("n=%d m=%d%n", n, m);
        }

        // initialise adjacency matrix and vertex state array
        adjMatrix = new boolean[n][n];
        vertexState = new State[n];
        for (int i = 0; i < n; i++) {
            vertexState[i] = State.UNMARKED;
        }

        // read edges
        for (int i = 0; i < m; i++) {
            int u = sc.nextInt() - 1;
            int v = sc.nextInt() - 1;
            if (debug) {
                System.out.printf("%d %d%n", u + 1, v + 1);
            }
            adjMatrix[u][v] = adjMatrix[v][u] = true;
        }
    }

    /** Entry point used by the original program. */
    public static void main(String[] args) {
        A_GraphAndString solver = new A_GraphAndString(false);
        try (Scanner scanner = openScanner()) {
            solver.readInput(scanner);
            solver.solve();
        } catch (IOException e) {
            System.err.println("Failed to read input: " + e.getMessage());
            e.printStackTrace();
        }
    }

    /** Opens the appropriate {@link Scanner} – either from a debug file or stdin. */
    private static Scanner openScanner() throws FileNotFoundException {
        // The original program expected a file at this path when running in debug mode.
        // We preserve that behaviour for backward compatibility.
        try (FileInputStream fis = new FileInputStream("src\\x0001_aim_tech_round_div_1\\A_input1.txt")) {
            return new Scanner(fis);
        } catch (FileNotFoundException ignored) {
            // Fall back to standard input if the file does not exist.
            return new Scanner(System.in);
        }
    }

    /** Orchestrates the whole solving process. */
    public void solve() {
        // Special‑case: graph with no edges.
        if (m == 0) {
            handleEmptyGraph();
            return;
        }

        // 1️⃣ Mark universal vertices as B.
        markAllB();

        // 2️⃣ Mark an A‑connected component.
        if (!markAllA()) {
            // All vertices are already B → output the all‑B result.
            outputAllB();
            return;
        }

        // 3️⃣ Mark a C‑connected component.
        if (!markAllC()) {
            // Inconsistent marking → invalid solution.
            System.out.println("No");
            return;
        }

        // 4️⃣ Validate the produced assignment.
        if (isAssignmentValid()) {
            outputResult();
        } else {
            System.out.println("No");
        }
    }

    /** Handles the case where the graph has no edges (identical to the original logic). */
    private void handleEmptyGraph() {
        System.out.println("Yes");
        switch (n) {
            case 1 -> System.out.print("a");
            case 2 -> System.out.print("ac");
            default -> System.out.print("No");
        }
    }

    /** Marks every vertex that is adjacent to *all* other vertices as B. */
    private void markAllB() {
        for (int v = 0; v < n; v++) {
            boolean isUniversal = true;
            for (int u = 0; u < n; u++) {
                if (v == u) continue;
                if (!adjacent(v, u)) {
                    isUniversal = false;
                    break;
                }
            }
            if (isUniversal) {
                vertexState[v] = State.B;
            }
        }
    }

    /** Marks a maximal connected component of currently UNMARKED vertices as A. */
    private boolean markAllA() {
        int firstUnmarked = findFirstUnmarked();
        if (firstUnmarked == -1) {
            // No unmarked vertices left → already all B.
            outputAllB();
            return false;
        }

        vertexState[firstUnmarked] = State.A;
        expandComponent(firstUnmarked, State.A);
        return true;
    }

    /** Marks a maximal connected component of currently UNMARKED vertices as C. */
    private boolean markAllC() {
        int firstUnmarked = findFirstUnmarked();
        if (firstUnmarked == -1) {
            // No work left – emit a result composed only of A/B.
            outputResultUsingOnlyAandB();
            return false;
        }

        vertexState[firstUnmarked] = State.C;
        // Every still‑UNMARKED vertex must be adjacent to the chosen C vertex.
        for (int v = firstUnmarked + 1; v < n; v++) {
            if (vertexState[v] == State.UNMARKED) {
                if (!adjacent(firstUnmarked, v)) {
                    System.out.println("No");
                    return false;
                }
                vertexState[v] = State.C;
            }
        }
        return true;
    }

    /** Finds the index of the first vertex whose state is {@link State#UNMARKED}. */
    private int findFirstUnmarked() {
        for (int i = 0; i < n; i++) {
            if (vertexState[i] == State.UNMARKED) {
                return i;
            }
        }
        return -1; // none found
    }

    /** Expands a component of a given {@link State} from the source vertex. */
    private void expandComponent(int source, State targetState) {
        for (int v = source + 1; v < n; v++) {
            if (vertexState[v] == State.UNMARKED && adjacent(source, v)) {
                vertexState[v] = targetState;
            }
        }
    }

    /** Prints “Yes” followed by a string consisting solely of the letter ‘b’. */
    private void outputAllB() {
        System.out.println("Yes");
        for (int i = 0; i < n; i++) {
            System.out.print('b');
        }
    }

    /** Prints “Yes” followed by a string made of ‘a’ (for A) and ‘b’ (for B only). */
    private void outputResultUsingOnlyAandB() {
        System.out.println("Yes");
        for (int i = 0; i < n; i++) {
            System.out.print(vertexState[i] == State.B ? 'b' : 'a');
        }
    }

    /** Prints the final assignment ('a', 'b', or 'c') according to the stored states. */
    private void outputResult() {
        System.out.println("Yes");
        for (State s : vertexState) {
            System.out.print(mapStateToLetter(s));
        }
    }

    /** Validates the current assignment against the problem constraints. */
    private boolean isAssignmentValid() {
        for (int i = 0; i < n; i++) {
            State si = vertexState[i];
            if (si == State.B) continue;            // B vertices impose no restrictions
            State complementary = (si == State.A) ? State.C : State.A;

            for (int j = 0; j < n; j++) {
                if (i == j) continue;
                State sj = vertexState[j];
                boolean connected = adjacent(i, j);

                // (connected && sj == complementary)  -> illegal
                // ( !connected && sj == si)            -> illegal
                if ((connected && sj == complementary) || (!connected && sj == si)) {
                    return false;
                }
            }
        }
        return true;
    }

    /** Returns {@code true} if vertices {@code u} and {@code v} are adjacent. */
    private boolean adjacent(int u, int v) {
        return adjMatrix[u][v] || adjMatrix[v][u];
    }

    /** Converts a {@link State} to its printable character. */
    private char mapStateToLetter(State s) {
        return switch (s) {
            case A -> 'a';
            case B -> 'b';
            case C -> 'c';
            default -> throw new AssertionError();
        };
    }
}

/**
 * Refactored version of the original program.
 *
 * <p>
 * The program reads a simple undirected graph (vertices numbered from 1 to {@code n})
 * and {@code m} edges.  It then assigns a label ('a', 'b', or 'c') to each vertex
 * according to the following rules and checks whether the label assignment
 * satisfies a set of edge‑based constraints.  Finally it prints “Yes” followed by
 * the labels (or “No” if the constraints are violated).
 * </p>
 *
 * <p>Key improvements over the original code:</p>
 * <ul>
 *   <li>Clear separation of concerns (input, processing, output).</li>
 *   <li>Descriptive naming and meaningful constants.</li>
 *   <li>Removal of unnecessary global mutable fields.</li>
 *   <li>Use of try‑with‑resources for I/O.</li>
 *   <li>Extraction of logical steps into well‑named methods.</li>
 *   <li>Optional use of {@link Enum} for the three possible labels.</li>
 *   <li>Robust validation with early exits instead of labelled breaks.</li>
 * </ul>
 */
public class GraphLabeler {

    /** Simple wrapper around {@link BufferedReader} and {@link PrintWriter}. */
    private static final class IO {
        private final BufferedReader reader;
        private final PrintWriter writer;

        IO() throws java.io.IOException {
            this.reader = new BufferedReader(new java.io.InputStreamReader(System.in));
            this.writer = new PrintWriter(System.out);
        }

        /** Returns the next non‑empty token from {@link BufferedReader}. */
        private String nextToken() throws java.io.IOException {
            while (st == null || !st.hasMoreTokens()) {
                st = new StringTokenizer(reader.readLine());
            }
            return st.nextToken();
        }

        /** Reads an {@code int}. */
        int nextInt() throws java.io.IOException {
            return Integer.parseInt(nextToken());
        }

        /** Reads a {@code char}. */
        char nextChar() throws java.io.IOException {
            return nextToken().charAt(0);
        }

        /** Writes the given string without a newline. */
        void print(String s) {
            writer.print(s);
        }

        /** Writes the given string followed by a newline. */
        void println(String s) {
            writer.println(s);
        }

        /** Flushes and closes the underlying streams. */
        void close() {
            writer.flush();
            try {
                reader.close();
            } catch (java.io.IOException e) {
                // ignore: nothing to do
            }
        }

        private StringTokenizer st;
    }

    /** The three possible labels for a vertex. */
    private enum Label {
        A('a'), B('b'), C('c');
        private final char symbol;

        Label(char symbol) {
            this.symbol = symbol;
        }

        @Override
        public String toString() {
            return String.valueOf(symbol);
        }
    }

    /** Holds the graph data (adjacency matrix & degree list). */
    private static final class Graph {
        private final int n;
        private final boolean[][] adjacency;
        private final int[] degree;

        Graph(int n) {
            this.n = n;
            this.adjacency = new boolean[n + 1][n + 1];
            this.degree = new int[n + 1];
        }

        /** Adds an undirected edge (a,b). */
        void addEdge(int a, int b) {
            adjacency[a][b] = true;
            adjacency[b][a] = true;
            degree[a]++;
            degree[b]++;
        }

        /** Returns the vertex count. */
        int vertexCount() {
            return n;
        }

        /** Returns adjacency matrix entry (i,j). */
        boolean hasEdge(int i, int j) {
            return adjacency[i][j];
        }

        /** Returns degree of vertex i. */
        int degreeOf(int i) {
            return degree[i];
        }
    }

    /** Core logic: read input → build graph → assign labels → validate → output. */
    private void solve() throws java.io.IOException {
        IO io = new IO();
        try {
            int n = io.nextInt();               // number of vertices
            int m = io.nextInt();               // number of edges
            Graph graph = buildGraph(n, m, io);

            Label[] labels = assignLabels(graph);
            if (!validate(graph, labels)) {
                io.print("No");
                return;
            }

            io.println("Yes");
            for (int v = 1; v <= n; v++) {
                io.print(labels[v].toString());
            }
            io.println();
        } finally {
            io.close();
        }
    }

    /** Reads the edge list and populates the {@link Graph}. */
    private Graph buildGraph(int n, int m, IO io) {
        Graph graph = new Graph(n);
        for (int i = 0; i < m; i++) {
            int a = io.nextInt();
            int b = io.nextInt();
            graph.addEdge(a, b);
        }
        return graph;
    }

    /**
     * Assigns a {@link Label} to each vertex according to the original algorithm.
     * <p>
     *   * Vertices with degree {@code n‑1} get label {@link Label#B}.
     *   * The first vertex that does *not* have label {@link Label#B} is labelled
     *     {@link Label#A}; all its neighbours are also labelled {@link Label#A}.
     *   * All remaining vertices receive {@link Label#C}.
     * </p>
     */
    private Label[] assignLabels(Graph graph) {
        int n = graph.vertexCount();
        Label[] label = new Label[n + 1];
        java.util.Arrays.fill(label, Label.C);

        // label vertices of maximal degree with 'B'
        for (int v = 1; v <= n; v++) {
            if (graph.degreeOf(v) == n - 1) {
                label[v] = Label.B;
            }
        }

        // find the first vertex that is not labelled 'B' and propagate 'A' to it and its neighbours
        for (int v = 1; v <= n; v++) {
            if (label[v] != Label.B) {
                label[v] = Label.A;
                for (int neighbour = 1; neighbour <= n; neighbour++) {
                    if (graph.hasEdge(v, neighbour)) {
                        label[neighbour] = Label.A;
                    }
                }
                break; // only the first such vertex is processed
            }
        }
        return label;
    }

    /**
     * Checks whether the current labeling satisfies all edge constraints.
     * The rules are equivalent to the nested loops of the original program.
     */
    private boolean validate(Graph graph, Label[] label) {
        int n = graph.vertexCount();

        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= n; j++) {
                if (i == j) {
                    continue;
                }
                Label li = label[i];
                Label lj = label[j];

                if (li == Label.A) {
                    // Ai must NOT be adjacent to Cj
                    if (lj == Label.C && graph.hasEdge(i, j)) {
                        return false;
                    }
                    // Ai must be adjacent to any non‑C vertex (i.e., A or B)
                    if (lj != Label.C && !graph.hasEdge(i, j)) {
                        return false;
                    }
                } else if (li == Label.C) {
                    // Ci must NOT be adjacent to Aj
                    if (lj == Label.A && graph.hasEdge(i, j)) {
                        return false;
                    }
                    // Ci must be adjacent to any non‑A vertex (i.e., B or C)
                    if (lj != Label.A && !graph.hasEdge(i, j)) {
                        return false;
                    }
                } else { // li == Label.B
                    // Bi must be adjacent to *every* other vertex
                    if (!graph.hasEdge(i, j)) {
                        return false;
                    }
                }
            }
        }
        return true;
    }

    /** Entry point. */
    public static void main(String[] args) throws java.io.IOException {
        new GraphLabeler().solve();
    }
}

import java.io.IOException;
import java.util.HashSet;
import java.util.Optional;
import java.util.Scanner;
import java.util.Set;

/**
 * Refactored version of the original program.
 *
 * <p>
 * The program reads an undirected graph, tries to assign each vertex a label
 * from the set {@code {a, b, c}} such that the adjacency constraints are met,
 * and prints either {@code Yes} followed by the labeling or {@code No} if no
 * valid labeling exists.
 * </p>
 */
public class Main {

    /** Simple immutable pair used internally. */
    private static final class Pair {
        final int first;
        final int second;

        Pair(int first, int second) {
            this.first = first;
            this.second = second;
        }
    }

    /** Holds all logic that works with the input graph. */
    private static final class GraphProcessor {
        private int vertexCount;
        private int edgeCount;
        private final boolean[][] adjacency;

        GraphProcessor(int vertexCount, int edgeCount) {
            this.vertexCount = vertexCount;
            this.edgeCount = edgeCount;
            this.adjacency = new boolean[vertexCount][vertexCount];
            initSelfLoops();
        }

        /** Populate the adjacency matrix with self‑loops and read edges. */
        private void initialize() throws IOException {
            // self‑loops are always considered present
            for (int i = 0; i < vertexCount; ++i) {
                adjacency[i][i] = true;
            }

            try (Scanner scanner = new Scanner(System.in)) {
                for (int i = 0; i < edgeCount; ++i) {
                    int a = scanner.nextInt() - 1;
                    int b = scanner.nextInt() - 1;
                    adjacency[a][b] = adjacency[b][a] = true;
                }
            }
        }

        /** Find the first missing edge (i, j) with i < j. */
        private Optional<Pair> findFirstMissingEdge() {
            for (int i = 0; i < vertexCount; ++i) {
                for (int j = i + 1; j < vertexCount; ++j) {
                    if (!adjacency[i][j]) {
                        return Optional.of(new Pair(i, j));
                    }
                }
            }
            return Optional.empty(); // graph is complete
        }

        /** All vertices that are NOT adjacent to the given vertex. */
        private Set<Integer> nonAdjacent(int vertex) {
            Set<Integer> result = new HashSet<>();
            for (int i = 0; i < vertexCount; ++i) {
                if (!adjacency[vertex][i]) {
                    result.add(i);
                }
            }
            return result;
        }

        /** Verify that a set of vertices induces a clique. */
        private boolean isClique(Set<Integer> vertices) {
            for (int i : vertices) {
                for (int j : vertices) {
                    if (!adjacency[i][j]) {
                        return false;
                    }
                }
            }
            return true;
        }

        /** Check that there is at least one edge between the two given sets. */
        private boolean hasEdgesBetween(Set<Integer> a, Set<Integer> b) {
            for (int i : a) {
                for (int j : b) {
                    if (adjacency[i][j]) {
                        return true;
                    }
                }
            }
            return false;
        }

        /** Verify that the given vertex is adjacent to every vertex of the set. */
        private boolean isFullyConnected(int vertex, Set<Integer> set) {
            for (int other : set) {
                if (!adjacency[vertex][other]) {
                    return false;
                }
            }
            return true;
        }

        /** Process the graph and output the answer. */
        private void process() throws IOException {
            Optional<Pair> maybeMissing = findFirstMissingEdge();

            // The graph is complete – every vertex can be labelled 'a'.
            if (!maybeMissing.isPresent()) {
                System.out.println("Yes");
                printRepeated('a');
                return;
            }

            Pair missing = maybeMissing.get();
            int u = missing.first;
            int v = missing.second;

            Set<Integer> nonAdjacentU = nonAdjacent(u);
            Set<Integer> nonAdjacentV = nonAdjacent(v);

            // Basic feasibility checks.
            if (!isClique(nonAdjacentU)
                    || !isClique(nonAdjacentV)
                    || hasEdgesBetween(nonAdjacentU, nonAdjacentV)) {
                System.out.print("No");
                return;
            }

            // Build the resulting label string.
            char[] labels = new char[vertexCount];
            Set<Integer> setB = new HashSet<>();

            for (int i = 0; i < vertexCount; ++i) {
                if (nonAdjacentU.contains(i)) {
                    labels[i] = 'a';
                } else if (nonAdjacentV.contains(i)) {
                    labels[i] = 'c';
                } else {
                    labels[i] = 'b';
                    if (!isFullyConnected(i, nonAdjacentU)
                            || !isFullyConnected(i, nonAdjacentV)) {
                        System.out.print("No");
                        return;
                    }
                    setB.add(i);
                }
            }

            // Finally, the vertices labelled 'b' must form a clique.
            if (!isClique(setB)) {
                System.out.print("No");
                return;
            }

            // Success – output the labeling.
            System.out.println("Yes");
            System.out.println(new String(labels));
        }

        /** Utility: print a character {@code count} times without a newline. */
        private void printRepeated(char ch) {
            for (int i = 0; i < vertexCount; ++i) {
                System.out.print(ch);
            }
        }
    }

    /** Entry point – thin wrapper that only deals with input/output. */
    public static void main(String[] args) throws IOException {
        try (Scanner scanner = new Scanner(System.in)) {
            int n = scanner.nextInt();
            int m = scanner.nextInt();

            GraphProcessor processor = new GraphProcessor(n, m);
            processor.initialize();
            processor.process();
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.Arrays;

/**
 * Refactored version of the original CF19 solution.
 *
 * <p>This version improves readability, separates concerns into small
 * methods, uses try‑with‑resources, and replaces duplicated logic with
 * well‑named helper routines.  The functional behaviour remains unchanged.</p>
 */
public class CF19 {

    /** Simple wrapper around the adjacency matrix and degree information. */
    private static final class Graph {
        private final int n;                     // number of vertices
        private final boolean[][] adjacency;     // adjacency matrix
        private final int[] degree;              // degree of each vertex

        Graph(int n) {
            this.n = n;
            this.adjacency = new boolean[n][n];
            this.degree = new int[n];
        }

        /** Adds an undirected edge between {@code u} and {@code v}. */
        void addEdge(int u, int v) {
            adjacency[u][v] = true;
            adjacency[v][u] = true;
            degree[u]++;
            degree[v]++;
        }

        /** Returns the degree of vertex {@code v}. */
        int degreeOf(int v) {
            return degree[v];
        }

        /** Checks whether vertices {@code u} and {@code v} are adjacent. */
        boolean areAdjacent(int u, int v) {
            return adjacency[u][v];
        }
    }

    /** Entry point of the program. */
    public static void main(String[] args) {
        // try‑with‑resources guarantees the BufferedReader is closed automatically
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in))) {
            Graph graph = readGraph(br);
            int specialIdx = locateSpecialNode(graph);
            if (specialIdx < 0) {
                System.out.println("No");
                return;
            }

            if (!verifySpecialAdjacencies(graph, specialIdx)) {
                System.out.println("No");
                return;
            }

            Result result = analyseGraph(graph, specialIdx);
            if (!result.isValid()) {
                System.out.println("No");
                return;
            }

            outputAnswer(result);
        } catch (IOException e) {
            // Convert checked exception to unchecked to keep the signature clean
            throw new UncheckedIOException(e);
        }
    }

    /** Reads the header and edge list, building a {@link Graph} instance. */
    private static Graph readGraph(BufferedReader br) throws IOException {
        String[] header = br.readLine().split("\\s+");
        int n = Integer.parseInt(header[0]);
        int m = Integer.parseInt(header[1]);

        Graph g = new Graph(n);
        for (int i = 0; i < m; i++) {
            int[] edge = readIntArray(br);
            int u = edge[0] - 1;
            int v = edge[1] - 1;
            g.addEdge(u, v);
        }
        return g;
    }

    /** Finds the vertex that is connected to every other vertex (degree = n‑1). */
    private static int locateSpecialNode(Graph g) {
        for (int i = 0; i < g.n; i++) {
            if (g.degreeOf(i) == g.n - 1) {
                return i;
            }
        }
        return -1; // not found
    }

    /** Verifies that the special node is adjacent to all other vertices. */
    private static boolean verifySpecialAdjacencies(Graph g, int special) {
        for (int other = 0; other < g.n; other++) {
            if (other != special && !g.areAdjacent(special, other)) {
                return false;
            }
        }
        return true;
    }

    /** Main analytical phase – determines groups A, B, C and validates them. */
    private static Result analyseGraph(Graph g, int special) {
        int[] degree = g.degree;

        // Find a reference vertex that is *not* the special one.
        int reference = -1;
        for (int i = 0; i < g.n; i++) {
            if (i != special && degree[i] != g.n - 1) {
                reference = i;
                break;
            }
        }

        // If every vertex is special (complete graph) we treat it as a trivial case.
        boolean allSpecial = reference == -1;
        boolean[] groupA = new boolean[g.n];
        boolean[] groupC = new boolean[g.n];

        if (!allSpecial) {
            int refDeg = degree[reference];
            for (int v = 0; v < g.n; v++) {
                if (v == special) continue;
                if (degree[v] != refDeg) continue;

                if (g.areAdjacent(reference, v)) {
                    groupA[v] = true;        // belongs to the "a" group
                } else {
                    groupC[v] = true;        // belongs to the "c" group
                }
            }
            groupA[reference] = true;        // reference itself belongs to "a"
        }

        // Build the final label array according to the original output format.
        char[] label = new char[g.n];
        for (int i = 0; i < g.n; i++) {
            if (i == special) {
                label[i] = 'b';
            } else if (groupA[i]) {
                label[i] = 'a';
            } else {
                label[i] = 'c';
            }
        }

        // In the original code the analysis never fails after reaching this point,
        // but we keep the boolean wrapper to preserve the original contract.
        return new Result(true, label);
    }

    /** Simple container for the analysis result. */
    private static final class Result {
        private final boolean valid;
        private final char[] label;   // label[i] = 'a', 'b' or 'c'

        Result(boolean valid, char[] label) {
            this.valid = valid;
            this.label = label;
        }

        boolean isValid() {
            return valid;
        }

        char label(int index) {
            return label[index];
        }
    }

    /** Reads a line of integers separated by whitespace. */
    private static int[] readIntArray(BufferedReader br) throws IOException {
        String[] tokens = br.readLine().split("\\s+");
        int[] arr = new int[tokens.length];
        for (int i = 0; i < tokens.length; i++) {
            arr[i] = Integer.parseInt(tokens[i]);
        }
        return arr;
    }

    /** Reads a single string (currently unused but kept for compatibility). */
    private static String readString(BufferedReader br) throws IOException {
        return br.readLine();
    }
}

import java.io.*;
import java.util.*;

public class CodeForces {

    /*--------------------------------------------------------------
        Fast input utility (preserves original behaviour)
    --------------------------------------------------------------*/
    private static final class FastScanner {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        FastScanner(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
        }

        private void ensureTokenizer() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                tokenizer = new StringTokenizer(reader.readLine());
            }
        }

        int nextInt() throws IOException {
            ensureTokenizer();
            return Integer.parseInt(tokenizer.nextToken());
        }

        long nextLong() throws IOException {
            ensureTokenizer();
            return Long.parseLong(tokenizer.nextToken());
        }

        double nextDouble() throws IOException {
            ensureTokenizer();
            return Double.parseDouble(tokenizer.nextToken());
        }
    }

    /*--------------------------------------------------------------
        Graph representation
    --------------------------------------------------------------*/
    private static final class Graph {
        private final boolean[][] adjacency;
        private final int vertexCount;

        Graph(int n) {
            this.vertexCount = n;
            this.adjacency = new boolean[n][n];
        }

        void addEdge(int u, int v) {
            adjacency[u][v] = adjacency[v][u] = true;
        }

        boolean isAdjacent(int u, int v) {
            return adjacency[u][v];
        }
    }

    /*--------------------------------------------------------------
        Colour assignment algorithm
    --------------------------------------------------------------*/
    private static final class ColourAssigner {
        private final int vertexCount;
        private final boolean[][] adjacency;
        private final int[] colour; // 0, 1 or 2

        ColourAssigner(int n) {
            this.vertexCount = n;
            this.adjacency = new boolean[n][n];
            this.colour = new int[n];
            Arrays.fill(colour, 1);                 // 1 = “unassigned”
        }

        void addEdge(int u, int v) {
            adjacency[u][v] = adjacency[v][u] = true;
        }

        /** Executes the whole assignment logic.
            Returns true if a valid assignment exists, false otherwise. */
        boolean assign(PrintWriter out) {
            // 1. Propagate constraints that come from *non‑edges*
            for (int i = 0; i < vertexCount; i++) {
                for (int j = 0; j < vertexCount; j++) {
                    if (i == j) continue;
                    if (!adjacency[i][j]) {               // i and j are NOT connected
                        enforceNonEdge(i, j);
                    }
                }
            }

            // 2. Verify that every edge and every non‑edge obey the required pattern
            if (!verifyConstraints(out)) {
                return false;                           // “No” has already been printed
            }
            return true;
        }

        /** Implements the rule described in the original program
            for a pair (i, j) that is **not** an edge. */
        private void enforceNonEdge(int i, int j) {
            if (colour[i] == 1 && colour[j] == 1) {
                // both currently unassigned → fix them to 0 and 2
                colour[i] = 0;
                colour[j] = 2;
            } else if (colour[i] == colour[j]) {
                // same non‑1 colour but already assigned → impossible configuration
                throw new IllegalStateException();
            } else if (colour[i] != 1) {               // i already fixed (0 or 2)
                colour[j] = (colour[i] == 0) ? 2 : 0;
            } else if (colour[j] != 1) {               // j already fixed
                colour[i] = (colour[j] == 2) ? 0 : 2;
            }
        }

        /** Checks that all edges and non‑edges respect the required pattern.
            If a check fails, prints “No”, flushes the output and returns false. */
        private boolean verifyConstraints(PrintWriter out) {
            for (int i = 0; i < vertexCount; i++) {
                for (int j = i + 1; j < vertexCount; j++) {
                    boolean isEdge = adjacency[i][j];
                    boolean isZeroTwo = (colour[i] == 0 && colour[j] == 2) ||
                                        (colour[i] == 2 && colour[j] == 0);

                    if (isEdge) {
                        if (isZeroTwo) {
                            out.println("No");
                            out.flush();
                            return false;
                        }
                    } else { // non‑edge
                        if (!isZeroTwo) {
                            out.println("No");
                            out.flush();
                            return false;
                        }
                    }
                }
            }
            return true;
        }

        /** Returns the colour of a vertex as a lower‑case letter (used for output). */
        char toLetter(int index) {
            return (char) (colour[index] + 'a');
        }
    }

    /*--------------------------------------------------------------
        Main driver
    --------------------------------------------------------------*/
    public static void main(String[] args) throws IOException {
        FastScanner fs = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(System.out);

        int n = fs.nextInt();          // number of vertices
        int m = fs.nextInt();          // number of edges

        ColourAssigner builder = new ColourAssigner(n);
        for (int i = 0; i < m; i++) {
            int u = fs.nextInt() - 1;
            int v = fs.nextInt() - 1;
            builder.addEdge(u, v);
        }

        try {
            if (!builder.assign(out)) {
                // The assignment routine already printed “No”, nothing else to do.
            }
        } finally {
            out.flush();
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Refactored version of the original program.
 *
 * <p>The program reads a graph, determines whether it can be coloured with three
 * colours (a‑b‑c) while respecting the constraints encoded in the input, and
 * prints “Yes” together with a valid colour assignment or “No” otherwise.
 *
 * <p>The original code was hard to read and mixed many responsibilities in one
 * large class.  The refactor separates concerns into small, focused classes and
 * uses expressive names, generics and modern Java constructs.
 */
public class Main {

    /* --------------------------------------------------------------------- */
    /* 1️⃣  Fast input utilities                                               */
    /* --------------------------------------------------------------------- */
    /** Simple wrapper around {@link BufferedReader} that tokenises input. */
    private static final class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner(InputStream source) {
            br = new BufferedReader(new InputStreamReader(source));
        }

        private void ensureTokenizer() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                String line = br.readLine();
                if (line == null) return;
                st = new StringTokenizer(line);
            }
        }

        int nextInt() throws IOException {
            ensureTokenizer();
            return Integer.parseInt(st.nextToken());
        }

        long nextLong() throws IOException {
            ensureTokenizer();
            return Long.parseLong(st.nextToken());
        }

        double nextDouble() throws IOException {
            ensureTokenizer();
            return Double.parseDouble(st.nextToken());
        }
    }

    /* --------------------------------------------------------------------- */
    /* 2️⃣  Union‑Find (Disjoint Set)                                          */
    /* --------------------------------------------------------------------- */
    /** Classic Union‑Find data structure with path compression. */
    private static final class UnionFind {
        private final int[] parent;

        UnionFind(int size) {
            parent = new int[size];
            for (int i = 0; i < size; i++) parent[i] = i;
        }

        /** Find the representative of the set that contains {@code x}. */
        int find(int x) {
            if (parent[x] != x) {
                parent[x] = find(parent[x]);
            }
            return parent[x];
        }

        /** Merge the sets of {@code x} and {@code y}. */
        void union(int x, int y) {
            parent[find(x)] = find(y);
        }

        /** Are {@code x} and {@code y} in the same set? */
        boolean connected(int x, int y) {
            return find(x) == find(y);
        }
    }

    /* --------------------------------------------------------------------- */
    /* 3️⃣  Graph representation                                                */
    /* --------------------------------------------------------------------- */
    /** Simple adjacency‑list graph that also stores neighbour‑sets for O(1)
     *  containment checks. */
    private static final class Graph {
        private final int n;
        private final List<Integer>[] adjacency;
        private final Set<Integer>[] neighbourSets;

        Graph(int n) {
            this.n = n;
            adjacency = new ArrayList[n];
            neighbourSets = new Set[n];
            for (int i = 0; i < n; i++) {
                adjacency[i] = new ArrayList<>();
                neighbourSets[i] = new HashSet<>();
            }
        }

        /** Add an undirected edge between {@code u} and {@code v}. */
        void addEdge(int u, int v) {
            adjacency[u].add(v);
            adjacency[v].add(u);
            neighbourSets[u].add(v);
            neighbourSets[v].add(u);
        }

        /** Number of vertices. */
        int size() {
            return n;
        }

        /** Neighbour list of a vertex (read‑only). */
        List<Integer> neighbours(int v) {
            return Collections.unmodifiableList(adjacency[v]);
        }

        /** neighbour‑set of a vertex (read‑only). */
        Set<Integer> neighbourSet(int v) {
            return Collections.unmodifiableSet(neighbourSets[v]);
        }
    }

    /* --------------------------------------------------------------------- */
    /* 4️⃣  Colour representation                                               */
    /* --------------------------------------------------------------------- */
    /** Enum that maps the three allowed colours to their printable characters. */
    private enum Color {
        ONE('a'), TWO('b'), THREE('c');

        private final char label;
        Color(char label) { this.label = label; }
        char label() { return label; }
    }

    /** Holds a partial colour assignment and tracks feasibility of the current
     *  partial solution. */
    private static final class Coloring {
        private final int[] assignment;   // -1 = unassigned
        private final boolean[] visited;  // tracks DFS visitation
        private boolean feasible;

        Coloring(int size) {
            assignment = new int[size];
            visited = new boolean[size];
            feasible = true;
        }

        /** Assign a colour to a vertex. */
        void assign(int vertex, Color colour) {
            assignment[vertex] = colour.ordinal();
            visited[vertex] = true;
        }

        /** Current colour index (‑1 if uncoloured). */
        int getAssignment(int v) {
            return assignment[v];
        }

        /** Has the vertex been visited by DFS? */
        boolean isVisited(int v) {
            return visited[v];
        }

        /** Reset visitation flags – useful when trying a new root colour. */
        void resetVisited() {
            Arrays.fill(visited, false);
        }

        /** Mark the current solution as infeasible. */
        void setInfeasible() {
            feasible = false;
        }

        /** Is the current partial solution still viable? */
        boolean isFeasible() {
            return feasible;
        }
    }

    /* --------------------------------------------------------------------- */
    /* 5️⃣  Core algorithm – DFS colouring with constraints                    */
    /* --------------------------------------------------------------------- */
    /**
     * Checks whether assigning {@code colour} to vertex {@code v} respects all
     * constraints derived from the graph and the Union‑Find structure.
     */
    private static boolean canAssign(Graph g,
                                     Coloring col,
                                     int v,
                                     Color colour,
                                     UnionFind uf) {
        int colourIdx = colour.ordinal();

        for (int i = 0; i < g.size(); i++) {
            // Vertices that share the same colour must belong to the same component.
            if (col.getAssignment(i) == colourIdx && !uf.connected(v, i)) {
                return false;
            }

            // Adjacent vertices must be in the same component.
            if (!uf.connected(v, i) && !g.neighbourSet(v).contains(i)) {
                return false;
            }

            // Colours that differ by at most 1 must also share a component.
            int diff = Math.abs(colourIdx - col.getAssignment(i));
            if (diff <= 1 && !g.neighbourSet(v).contains(i)) {
                return false;
            }
        }
        return true;
    }

    /**
     * Depth‑first search that tries to colour the component reachable from
     * {@code start} using {@code startColour}.  The search stops as soon as the
     * solution becomes infeasible.
     */
    private static void dfsColour(Graph g,
                                  Coloring col,
                                  UnionFind uf,
                                  int start,
                                  Color startColour) {
        if (!col.isFeasible()) return;

        Deque<Integer> stack = new ArrayDeque<>();
        stack.push(start);
        col.assign(start, startColour);

        while (!stack.isEmpty() && col.isFeasible()) {
            int cur = stack.pop();

            for (int nb : g.neighbours(cur)) {
                if (col.isVisited(nb)) continue;

                // Try to keep the same colour as the parent
                if (canAssign(g, col, nb, startColour, uf)) {
                    col.assign(nb, startColour);
                    stack.push(nb);
                    continue;
                }

                // Try the two neighbouring colours (differ by ±1)
                Color[] alternatives = {
                        Color.values()[(startColour.ordinal() + 1) % 3],
                        Color.values()[(startColour.ordinal() + 2) % 3]
                };
                for (Color alt : alternatives) {
                    if (canAssign(g, col, nb, alt, uf)) {
                        col.assign(nb, alt);
                        stack.push(nb);
                        break;
                    }
                }

                // If nothing works, the current branch is dead‑ended.
                if (!col.isFeasible()) break;
            }
        }
    }

    /* --------------------------------------------------------------------- */
    /* 6️⃣  Main entry point                                                   */
    /* --------------------------------------------------------------------- */
    public static void main(String[] args) throws IOException {
        FastScanner scanner = new FastScanner(System.in);

        int n = scanner.nextInt();          // number of vertices
        int m = scanner.nextInt();          // number of edges

        Graph graph = new Graph(n);
        UnionFind uf = new UnionFind(n);

        /* -------------------------------------------------------------
         * Build the graph and perform the Union‑Find merging that the
         * original program describes.
         * ------------------------------------------------------------- */
        for (int i = 0; i < m; i++) {
            int u = scanner.nextInt() - 1;
            int v = scanner.nextInt() - 1;
            graph.addEdge(u, v);

            // Original logic: vertices of equal degree that are not directly
            // linked should be merged if their adjacency sets are identical.
            // This is exactly what we reproduce here.
            if (graph.neighbours(u).size() == graph.neighbours(v).size()
                    && !graph.neighbourSet(u).contains(v)
                    && !uf.connected(u, v)) {

                boolean identicalAdjacency = true;
                for (int nb : graph.neighbours(u)) {
                    if (!graph.neighbourSet(v).contains(nb)) {
                        identicalAdjacency = false;
                        break;
                    }
                }
                if (identicalAdjacency) {
                    uf.union(u, v);
                }
            }
        }

        /* -------------------------------------------------------------
         * Try to colour the whole graph.  For each possible colour of the
         * first vertex we start a DFS that propagates constraints.
         * ------------------------------------------------------------- */
        Coloring trial = new Coloring(n);
        boolean solutionFound = false;
        StringBuilder outputBuilder = new StringBuilder();

        for (int rootColourIdx = 0; rootColourIdx < 3 && !solutionFound; rootColourIdx++) {
            Coloring current = new Coloring(n);
            Color rootColour = Color.values()[rootColourIdx];

            dfsColour(graph, current, uf, 0, rootColour);
            if (!current.isFeasible()) continue;

            // Ensure every vertex received a colour; if some vertex stayed
            // unvisited we attempt to colour it with any admissible colour.
            boolean allColoured = true;
            for (int v = 0; v < n && allColoured; v++) {
                if (current.isVisited(v)) continue;
                boolean coloured = false;
                for (int c = 0; c < 3 && !coloured; c++) {
                    if (canAssign(graph, current, v, Color.values()[c], uf)) {
                        current.assign(v, Color.values()[c]);
                        coloured = true;
                    }
                }
                if (!coloured) {
                    allColoured = false;
                }
            }

            if (allColoured) {
                solutionFound = true;
                for (int v = 0; v < n; v++) {
                    outputBuilder.append(Color.values()[current.getAssignment(v)].label());
                }
            }
        }

        /* -------------------------------------------------------------
         * Produce the final answer.
         * ------------------------------------------------------------- */
        if (solutionFound) {
            System.out.println("Yes");
            System.out.println(outputBuilder);
        } else {
            System.out.println("No");
        }
    }
}

import java.io.InputStream;
import java.util.HashSet;
import java.util.Set;

/**
 * Refactored version of the original {@code GraphAndString} program.
 * <p>
 * The program reads an undirected graph, assigns the characters {@code 'a'},
 * {@code 'b'}, {@code 'c'} according to the original algorithm and then checks
 * whether the assignment satisfies the required adjacency condition.
 * </p>
 */
public class GraphStringColoring {

    /** Entry point. */
    public static void main(String[] args) {
        try (FastScanner fs = new FastScanner()) {
            int n = fs.nextInt();           // number of vertices
            int m = fs.nextInt();           // number of edges

            // --- build adjacency list -------------------------------------------------
            Set<Integer>[] adjacency = new Set[n];
            for (int i = 0; i < n; i++) {
                adjacency[i] = new HashSet<>();
            }
            for (int i = 0; i < m; i++) {
                int u = fs.nextInt() - 1;
                int v = fs.nextInt() - 1;
                adjacency[u].add(v);
                adjacency[v].add(u);
            }

            // --- assign colours -------------------------------------------------------
            char[] colour = new char[n];
            fillInitialColours(adjacency, colour);

            // --- validation -----------------------------------------------------------
            if (isConsistent(adjacency, colour)) {
                System.out.println("Yes");
                System.out.println(new String(colour));
            } else {
                System.out.println("No");
            }
        } catch (InputError e) {
            throw new AssertionError("Invalid input", e);
        }
    }

    /** Populates {@code colour} with ‘a’, ‘b’ and possibly ‘c’ using the original rules. */
    private static void fillInitialColours(Set<Integer>[] adjacency, char[] colour) {
        int n = adjacency.length;

        // Vertices adjacent to all others receive the colour ‘b’.
        for (int v = 0; v < n; v++) {
            if (adjacency[v].size() == n - 1) {
                colour[v] = 'b';
            }
        }

        // Remaining vertices start with ‘a’; any vertex not adjacent to such a vertex
        // receives the colour ‘c’.
        for (int v = 0; v < n; v++) {
            if (colour[v] == 0) {               // still unassigned
                colour[v] = 'a';
                for (int u = v + 1; u < n; u++) {
                    if (!adjacency[v].contains(u)) {
                        colour[u] = 'c';
                    }
                }
            }
        }
    }

    /** Checks whether the produced colour string matches the adjacency pattern. */
    private static boolean isConsistent(Set<Integer>[] adjacency, char[] colour) {
        int n = adjacency.length;
        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j < n; j++) {
                boolean shouldBeEdge = adjacency[i].contains(j);
                boolean actuallyEdge = Math.abs(colour[i] - colour[j]) <= 1;
                if (shouldBeEdge != actuallyEdge) {
                    return false;
                }
            }
        }
        return true;
    }

    /** Fast scanner that works with the original input format (space‑separated ints). */
    private static class FastScanner implements AutoCloseable {
        private static final int BUFFER_SIZE = 1 << 10;
        private final byte[] buffer = new byte[BUFFER_SIZE];
        private int pointer = 0;
        private int length = 0;
        private final InputStream stream;

        FastScanner() {
            this(System.in);
        }

        FastScanner(InputStream stream) {
            this.stream = stream;
        }

        private int readByte() throws IOException {
            if (pointer >= length) {
                length = stream.read(buffer);
                pointer = 0;
                if (length <= 0) {
                    return -1;
                }
            }
            return buffer[pointer++];
        }

        /** Reads the next token as a non‑negative integer. */
        int nextInt() {
            int c;
            do {
                c = readByte();
                if (c == -1) throw new InputError();
            } while (isSpace(c));

            boolean negative = false;
            if (c == '-') {
                negative = true;
                c = readByte();
            }

            int value = 0;
            do {
                if (c < '0' || c > '9') throw new InputError();
                value = value * 10 + (c - '0');
                c = readByte();
            } while (!isSpace(c));

            return negative ? -value : value;
        }

        private boolean isSpace(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        @Override
        public void close() throws IOException {
            stream.close();
        }
    }

    /** Runtime exception used to signal malformed input. */
    private static class InputError extends RuntimeException {
        private static final long serialVersionUID = 1L;
        InputError() {
            super("Input parsing error");
        }
    }
}

/**
 * Refactored solution for the graph‑letter assignment problem.
 *
 * <p>This version improves readability, separates concerns and uses modern Java
 * constructs (try‑with‑resources, proper naming, constants, etc.) while keeping
 * the original algorithmic behaviour.</p>
 */
public class Main {

    /** Entry point. */
    public static void main(String[] args) {
        // Use try‑with‑resources so streams are closed automatically.
        try (java.io.InputStream inStream = System.in;
             java.io.OutputStream outStream = System.out) {

            InputReader input = new InputReader(inStream);
            PrintWriter output = new PrintWriter(outStream, true); // auto‑flush

            GraphSolver solver = new GraphSolver();
            solver.solve(input, output);
        }
    }
}

/**
 * Handles all logic related to solving the problem.
 */
final class GraphSolver {

    /** Private constructor – utility class. */
    private GraphSolver() { }

    /** Alphabet used for the answer. */
    private static final char LETTER_A = 'a';
    private static final char LETTER_B = 'b';
    private static final char LETTER_C = 'c';

    /**
     * Executes the solution.
     *
     * @param input  source of tokens
     * @param out    where the result is written
     */
    void solve(InputReader input, PrintWriter out) {
        int n = input.nextInt(); // number of vertices
        int m = input.nextInt(); // number of edges

        // Build adjacency list (1‑based indexing)
        var adjacency = buildAdjacencyList(n, input);

        // Determine which vertices have degree n‑1 – they will be assigned 'b'.
        char[] answer = new char[n + 1];
        initAnswerWithZeros(answer);
        markDegreeOneVerticesAsB(adjacency, answer, n);

        // Find a component that is not completely connected and run DFS from it.
        // The visited vertices will be labelled 'a' later.
        findFirstNonCompleteComponent(adjacency, answer);

        // Any still‑unassigned vertex gets label 'c'.
        labelRemainingVerticesAsC(answer, n);

        // Validate the constructed assignment.
        if (!validateAssignment(adjacency, answer)) {
            out.println("No");
            return;
        }

        // Output
        out.println("Yes");
        for (int v = 1; v <= n; v++) {
            out.print(answer[v]);
        }
    }

    /** Creates a 1‑based adjacency list (sets for O(1) look‑ups). */
    private static java.util.List<java.util.Set<Integer>> buildAdjacencyList(
            int vertexCount, InputReader input) {

        var adjacency = new java.util.ArrayList<java.util.Set<Integer>>(vertexCount + 1);
        for (int i = 0; i <= vertexCount; i++) {
            adjacency.add(new java.util.HashSet<>());
        }

        for (int i = 0; i < input.nextInt(); i++) { // read m edges – we ignore m after reading
            int u = input.nextInt();
            int v = input.nextInt();
            adjacency.get(u).add(v);
            adjacency.get(v).add(u);
        }
        return adjacency;
    }

    /** Fills an array with the null character (Unicode 0). */
    private static void initAnswerWithZeros(char[] arr) {
        java.util.Arrays.fill(arr, '\0');
    }

    /**
     * Vertices with degree {@code n‑1} are forced to be 'b'.
     * This is a direct consequence of the problem constraints.
     */
    private static void markDegreeOneVerticesAsB(
            java.util.List<java.util.Set<Integer>> adjacency,
            char[] answer,
            int vertexCount) {

        for (int v = 1; v <= vertexCount; v++) {
            if (adjacency.get(v).size() == vertexCount - 1) {
                answer[v] = LETTER_B;
            }
        }
    }

    /** Depth‑first search that labels a connected component with ‘a’. */
    private static void dfsMarkComponent(
            java.util.List<java.util.Set<Integer>> adjacency,
            char[] answer,
            int start) {

        java.util.ArrayDeque<Integer> stack = new java.util.ArrayDeque<>();
        stack.push(start);

        while (!stack.isEmpty()) {
            int cur = stack.pop();
            if (answer[cur] != '\0') {
                continue;
            }
            answer[cur] = LETTER_A;
            stack.addAll(adjacency.get(cur));
        }
    }

    /**
     * Locates the first vertex that has not been assigned yet and runs DFS
     * from it to fill a component with 'a'.  The method stops after the first
     * such component is processed – the remaining vertices will be handled
     * later (they become 'c').
     */
    private static void findFirstNonCompleteComponent(
            java.util.List<java.util.Set<Integer>> adjacency,
            char[] answer) {

        for (int v = 1; v < answer.length; v++) {
            if (answer[v] == '\0') {
                dfsMarkComponent(adjacency, answer, v);
                break; // only one component needs to be processed this way
            }
        }
    }

    /** Any vertex still unassigned becomes 'c'. */
    private static void labelRemainingVerticesAsC(char[] answer, int n) {
        for (int v = 1; v <= n; v++) {
            if (answer[v] == '\0') {
                answer[v] = LETTER_C;
            }
        }
    }

    /**
     * Checks the assignment against the edge constraints.
     *
     * @return {@code true} if the labeling is valid, {@code false} otherwise.
     */
    private static boolean validateAssignment(
            java.util.List<java.util.Set<Integer>> adjacency,
            char[] answer) {

        for (int v = 1; v < answer.length; v++) {
            // Build the set of neighbours for quick lookup.
            java.util.Set<Integer> neighbourSet = adjacency.get(v);

            for (int u : neighbourSet) {
                // Adjacent letters must differ by at most 1 in ASCII value.
                if (Math.abs(answer[v] - answer[u]) > 1) {
                    return false;
                }
            }

            // All non‑neighbouring vertices (except self) must differ by more than 1.
            for (int u = 1; u <= answer.length - 1; u++) {
                if (u == v) {
                    continue;
                }
                if (!neighbourSet.contains(u)) {
                    if (Math.abs(answer[v] - answer[u]) <= 1) {
                        return false;
                    }
                }
            }
        }
        return true;
    }
}

/**
 * Simple fast scanner that reads tokens from an {@link InputStream}.
 * It mimics the behaviour of the original {@code InputReader} but is
 * encapsulated in its own class for better separation of concerns.
 */
final class InputReader {
    private final BufferedReader reader;
    private StringTokenizer tokenizer;

    public InputReader(InputStream stream) {
        this.reader = new BufferedReader(new java.io.InputStreamReader(stream));
    }

    /** Ensures that a tokenizer is ready and contains tokens. */
    private void ensureTokenizer() {
        if (tokenizer == null || !tokenizer.hasMoreTokens()) {
            try {
                tokenizer = new StringTokenizer(reader.readLine());
            } catch (java.io.IOException e) {
                throw new UncheckedIOException(e);
            }
        }
    }

    /** Returns the next token. */
    String next() {
        ensureTokenizer();
        return tokenizer.nextToken();
    }

    /** Convenience wrapper for {@code Integer.parseInt(next())}. */
    int nextInt() {
        return Integer.parseInt(next());
    }
}

/**
 * Graph coloring with a simple propagation rule.
 *
 * The program reads an undirected graph (vertices numbered from 0) and
 * tries to assign each vertex a color (integer) satisfying:
 *   1. For every non‑adjacent pair (u, v) the colors must differ.
 *   2. For every adjacent pair (u, v) the absolute difference of colors
 *      must be at most 1.
 *
 * If a valid coloring exists, the program prints “Yes” followed by a
 * string of lower‑case letters representing the colors; otherwise it
 * prints “No”.
 *
 * The implementation is deliberately kept simple for educational
 * purposes, but the code is now easier to read, test and extend.
 */
public class GraphColoring {

    /** Fast scanner that reads tokens from standard input. */
    private static final class FastScanner {
        private final java.io.BufferedReader reader;
        private java.util.StringTokenizer tokenizer;

        FastScanner(java.io.BufferedReader reader) {
            this.reader = java.io.BufferedReader;
        }

        String nextToken() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new java.util.StringTokenizer(reader.readLine());
                } catch (java.io.IOException e) {
                    throw new UncheckedIOException(e);
                }
            }
            return tokenizer.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(nextToken());
        }
    }

    /** Holds all data related to the problem instance. */
    private static final class Problem {
        private final int vertexCount;
        private final int edgeCount;
        private final boolean[][] adjacency;
        private final int[] color;               // 0 = unassigned, otherwise 1‑based color
        private boolean feasible;                 // becomes false if a constraint is violated

        Problem(int vertexCount, int edgeCount) {
            this.vertexCount = vertexCount;
            this.edgeCount = edgeCount;
            this.adjacency = new boolean[vertexCount][vertexCount];
            this.color = new int[vertexCount];
        }

        void addEdge(int u, int v) {
            adjacency[u][v] = true;
            adjacency[v][u] = true;
        }

        /** Assign a color to `start` and propagate to all vertices reachable via non‑edges. */
        void propagate(int start) {
            assign(start, 1);
            for (int vertex = 0; vertex < vertexCount && feasible; vertex++) {
                if (color[vertex] != 0) {
                    continue;
                }
                // Is `vertex` isolated in the complement graph? (i.e., has at least one non‑edge)
                boolean hasNonEdge = false;
                for (int other = 0; other < vertexCount; other++) {
                    if (other == vertex) {
                        continue;
                    }
                    if (!adjacency[vertex][other]) {
                        hasNonEdge = true;
                        break;
                    }
                }
                if (hasNonEdge) {
                    propagateComponent(vertex, 1);
                }
            }
        }

        /** Recursive helper used by {@link #propagate(int)}. */
        private void propagateComponent(int v, int currentColor) {
            color[v] = currentColor;
            for (int neighbor = 0; neighbor < vertexCount && feasible; neighbor++) {
                if (v == neighbor) {
                    continue;
                }
                if (!adjacency[v][neighbor]) {                 // non‑edge
                    if (color[neighbor] == currentColor) {
                        feasible = false;
                        return;
                    }
                    if (color[neighbor] == 0) {
                        propagateComponent(neighbor, -currentColor);
                    }
                }
            }
        }

        /** Validate that every adjacent pair respects the “difference ≤ 1” rule. */
        void validateAdjacencyConstraints() {
            if (!feasible) {
                return;
            }
            for (int i = 0; i < vertexCount && feasible; i++) {
                for (int j = i + 1; j < vertexCount && feasible; j++) {
                    if (adjacency[i][j]) {
                        int diff = color[i] - color[j];
                        if (diff < -1 || diff > 1) {
                            feasible = false;
                        }
                    }
                }
            }
        }

        /** Convert the integer colors to lower‑case letters for output. */
        String toLetterString() {
            StringBuilder sb = new StringBuilder(vertexCount);
            for (int c : color) {
                sb.append((char) ('a' + c - 1));
            }
            return sb.toString();
        }
    }

    /** Entry point. */
    public static void main(String[] args) throws java.io.IOException {
        try (java.io.InputStream in = System.in) {
            FastScanner fs = new FastScanner(new java.io.BufferedReader(new java.io.InputStreamReader(in)));

            int n = fs.nextInt();          // number of vertices
            int m = fs.nextInt();          // number of edges

            Problem problem = new Problem(n, m);

            for (int i = 0; i < m; i++) {
                int u = fs.nextInt() - 1;
                int v = fs.nextInt() - 1;
                problem.addEdge(u, v);
            }

            // Attempt to assign colors using the special propagation rule.
            problem.feasible = true;
            for (int v = 0; v < n && problem.feasible; v++) {
                if (problem.color[v] != 0) {
                    continue;
                }
                boolean isolatedInComplement = true;
                for (int other = 0; other < n; other++) {
                    if (other == v) {
                        continue;
                    }
                    if (!problem.adjacency[v][other]) {
                        isolatedInComplement = false;
                        break;
                    }
                }
                if (!isolatedInComplement) {
                    problem.propagate(v);
                }
            }

            // Final validation step.
            problem.validateAdjacencyConstraints();

            // Produce output.
            java.io.PrintWriter out = new java.io.PrintWriter(new java.io.BufferedWriter(new java.io.OutputStreamWriter(System.out)));
            if (!problem.feasible) {
                out.println("No");
            } else {
                out.println("Yes");
                out.println(problem.toLetterString());
            }
            out.flush();
        }
    }
}

/**
 * GraphAndString
 *
 * Reads an undirected graph (vertex/edge count followed by edges) and decides whether the
 * vertices can be labelled with the characters 'a', 'b' or 'c' such that the following
 * conditions hold:
 *
 * 1. Vertices with degree (V‑1) receive label 'b'.
 * 2. Starting from a vertex labelled 'a', its neighbours that are not already labelled
 *    'b' receive the same label 'a'. The process repeats until no new vertices can be
 *    labelled 'a'.
 * 3. The same logic is applied for label 'c' on the first still‑unlabelled vertex.
 * 4. After an initial assignment, every vertex must have *only* neighbours with the same
 *    label (or 'b') and every non‑'b' label must appear on exactly the expected number
 *    of vertices.
 *
 * If the conditions are satisfied the program prints "Yes" followed by the labels
 * (space‑less concatenation) otherwise it prints "No".
 *
 * The refactor separates input, graph construction, assignment logic, validation and
 * output into distinct, reusable methods and classes.
 */
public class GraphAndString {

    /** Simple representation of a vertex in the graph. */
    private static final class Vertex {
        final int id;                 // 1‑based identifier used for input/output
        char label = '\0';            // label assigned after algorithm ('a'|'b'|'c'|'\0')
        Vertex(int id) { this.id = id; }
    }

    /** Holds the graph and all related operations. */
    private static final class Graph {
        private final int vertexCount;
        private final Vertex[] vertices;
        private final java.util.List<Integer>[] adjacency; // array of mutable lists

        Graph(int vertexCount) {
            this.vertexCount = vertexCount;
            this.vertices = new Vertex[vertexCount + 1]; // index 0 unused
            this.adjacency = new java.util.ArrayList[vertexCount + 1];
            for (int i = 1; i <= vertexCount; i++) {
                vertices[i] = new Vertex(i);
                adjacency[i] = new java.util.ArrayList<>();
            }
        }

        /** Adds an undirected edge between u and v. */
        void addEdge(int u, int v) {
            adjacency[u].add(v);
            adjacency[v].add(u);
        }

        Vertex[] getVertices() {
            return vertices;
        }

        /** Helper to split a line of whitespace‑separated integers. */
        static int[] parseInts(String line) {
            String[] tokens = line.trim().split("\\s+");
            int[] numbers = new int[tokens.length];
            for (int i = 0; i < tokens.length; i++) {
                numbers[i] = Integer.parseInt(tokens[i]);
            }
            return numbers;
        }
    }

    /** Entry point */
    public static void main(String[] args) {
        /* --------------------------------------------------------------
         * 1. Read input safely (try‑with‑resources guarantees closure)
         * -------------------------------------------------------------- */
        try (java.io.BufferedReader br = new java.io.BufferedReader(
                new java.io.InputStreamReader(System.in))
        ) {

            // First line: vertex count and edge count
            String[] firstLineTokens = br.readLine().trim().split("\\s+");
            int vertexCount = Integer.parseInt(firstLineTokens[0]);
            int edgeCount = Integer.parseInt(firstLineTokens[1]);

            Graph graph = new Graph(vertexCount);

            // Subsequent edges
            for (int i = 0; i < edgeCount; i++) {
                String edgeLine = br.readLine();
                if (edgeLine == null) {
                    throw new IllegalArgumentException("Not enough lines for edges");
                }
                int[] u v = parseInts(edgeLine);
                if (u < 1 || u > vertexCount || v < 1 || v > vertexCount) {
                    throw new IllegalArgumentException("Vertex id out of range: " + u + " or " + v);
                }
                graph.addEdge(u, v);
            }

            // Run the assignment + validation algorithm
            boolean valid = assignAndValidate(labelsFromGraph(graph));

            // Output result
            try (java.io.PrintWriter pw = new java.io.PrintWriter(System.out)) {
                pw.println(valid ? "Yes" : "No");
                if (valid) {
                    // Concatenate labels starting from vertex 1
                    for (int i = 1; i <= vertexCount; i++) {
                        pw.print(graph.getVertices()[i].label);
                    }
                    pw.println();
                }
            }

        } catch (Exception e) {
            // In the original program failures were silently ignored; we keep the same behaviour
        }
    }

    /**
     * Core algorithm that:
     *   • labels vertices with 'a', 'b' or 'c' following the rules described in the class comment,
     *   • validates the resulting labelling,
     *   • returns true if and only if the validation succeeds.
     */
    private static boolean assignAndValidate(Graph graph) {
        Vertex[] vertices = graph.getVertices();

        // -----------------------------------------------------------------
        // 1️⃣  Vertices with degree (V‑1) are forced to 'b'.
        // -----------------------------------------------------------------
        boolean changed = true;
        while (changed) {
            changed = false;
            for (int v = 1; v <= graph.vertexCount; v++) {
                if (vertices[v].label == '\0' && graph.adjacency[v].size() == graph.vertexCount - 1) {
                    vertices[v].label = 'b';
                    changed = true;
                }
            }
        }

        // -----------------------------------------------------------------
        // 2️⃣  Propagate label 'a' from the first non‑'b' vertex that has not been labelled yet.
        // -----------------------------------------------------------------
        for (int v = 1; v <= graph.vertexCount; v++) {
            if (vertices[v].label == '\0') {
                propagateLabel(vertices, graph, v, 'a');
                break; // only one start point for 'a' is intended
            }
        }

        // -----------------------------------------------------------------
        // 3️⃣  Propagate label 'c' from the next still‑unlabelled vertex.
        // -----------------------------------------------------------------
        for (int v = 1; v <= graph.vertexCount; v++) {
            if (vertices[v].label == '\0') {
                propagateLabel(vertices, graph, v, 'c');
                break;
            }
        }

        // -----------------------------------------------------------------
        // 4️⃣  Validation: every non‑'b' vertex must have ONLY neighbours with the
        //      same label (or 'b') and must have exactly (labelCount‑1) neighbours
        //      sharing that label.
        // -----------------------------------------------------------------
        boolean isValid = true;
        // Pre‑compute counts for faster lookup
        int countA = 0, countC = 0;
        for (int v = 1; v <= graph.vertexCount; v++) {
            char l = vertices[v].label;
            if (l == 'a') countA++;
            else if (l == 'c') countC++;
        }

        for (int v = 1; v <= graph.vertexCount && isValid; v++) {
            char self = vertices[v].label;
            if (self == '\0' || self == 'b') {
                continue; // nothing to validate for unassigned or 'b'
            }

            int sameLabelNeighbourCount = 0;
            for (int nbrId : graph.adjacency[v]) {
                char nbrLabel = vertices[nbrId].label;
                if (nbrLabel != 'b' && nbrLabel != self) {
                    // neighbour has a different non‑'b' label -> invalid
                    isValid = false;
                    break;
                }
                if (nbrLabel == self) {
                    sameLabelNeighbourCount++;
                }
            }

            // The required neighbour count for 'a' or 'c' is the total number of vertices
            // having that label minus one (the vertex itself).
            int required = (self == 'a') ? countA - 1 : countC - 1;
            if (isValid && sameLabelNeighbourCount != required) {
                isValid = false;
            }
        }

        return isValid;
    }

    /**
     * Propagates a label from a starting vertex to all reachable vertices that are not
     * already labelled 'b'. The propagation respects the original algorithmic behaviour:
     * a vertex receives the same label as its parent only if it is currently unlabelled.
     *
     * @param vertices   array of Vertex objects (1‑based indexing)
     * @param graph      the graph to query adjacency lists from
     * @param startId    vertex id from which propagation starts
     * @param labelChar  the character ('a' or 'c') to assign
     */
    private static void propagateLabel(Vertex[] vertices,
                                       Graph graph,
                                       int startId,
                                       char labelChar) {
        vertices[startId].label = labelChar;
        for (int neighbourId : graph.adjacency[startId]) {
            Vertex neighbour = vertices[neighbourId];
            if (neighbour.label == '\0') {
                // Perform a breadth‑first‑style propagation by re‑calling this method
                // for each newly discovered vertex. This mimics the original nested loops.
                propagateLabel(vertices, graph, neighbourId, labelChar);
            }
        }
    }
}

import java.io.IOException;
import java.math.BigDecimal;
import java.util.*;

/**
 * Reads an undirected graph and tries to assign each vertex one of the
 * letters a, b or c according to the rules described in the original
 * program. If the assignment is possible it prints "Yes" followed by the
 * per‑vertex labels; otherwise it prints "No".
 *
 * The implementation is deliberately split into small, pure methods to
 * improve readability, testability and reuse.
 */
public class Main {

    private static final Scanner SCANNER = new Scanner(System.in);

    /* --------------------------------------------------------------------- */
    /* Entry point                                                          */
    /* --------------------------------------------------------------------- */
    public static void main(String[] args) throws IOException {
        try {
            Graph graph = readGraph();
            Optional<Labeling> result = LabelingProcessor.compute(graph);

            result.ifPresentOrElse(
                    labeling -> {
                        System.out.println("Yes");
                        labeling.printLabels();
                    },
                    () -> System.out.println("No")
            );
        } finally {
            SCANNER.close();
        }
    }

    /* --------------------------------------------------------------------- */
    /* Input handling                                                         */
    /* --------------------------------------------------------------------- */
    private static Graph readGraph() {
        int n = SCANNER.nextInt();          // number of vertices
        int m = SCANNER.nextInt();          // number of edges

        List<Integer>[] adjacency = new ArrayList[n];
        for (int i = 0; i < n; i++) {
            adjacency[i] = new ArrayList<>();
        }

        // add edges
        for (int i = 0; i < m; i++) {
            int u = SCANNER.nextInt() - 1;
            int v = SCANNER.nextInt() - 1;
            adjacency[u].add(v);
            adjacency[v].add(u);
        }

        return new Graph(n, adjacency);
    }

    /* --------------------------------------------------------------------- */
    /* Core logic – processing of the graph                                   */
    /* --------------------------------------------------------------------- */
    private static class LabelingProcessor {

        private static final Set<Integer> COND_INCOMPLETE = Set.of(0, 1);

        /**
         * Attempts to produce a {@link Labeling}. Returns {@link Optional#empty()}
         * if the graph cannot be labelled according to the rules.
         */
        static Optional<Labeling> compute(Graph g) {
            // 1️⃣  Vertices with degree n‑1 → set B
            Set<Integer> b = identifyFullDegreeVertices(g);
            if (b.size() > 1) {
                return Optional.empty();               // more than one “b‑vertex” ⇒ impossible
            }

            // 2️⃣  Build set A around a first non‑B vertex
            Set<Integer> a = identifySetA(g, b);
            if (a == null) {
                return Optional.empty();
            }

            // 3️⃣  Remaining vertices that are not yet labelled → set C
            Set<Integer> c = identifySetC(g, b, a);
            if (c == null) {
                return Optional.empty();
            }

            // 4️⃣  Validate structural constraints for A, B and C
            if (!validateSets(g, a, b, c)) {
                return Optional.empty();
            }

            // 5️⃣  Decision: every vertex is labelled exactly once?
            if (a.size() + b.size() + c.size() != g.vertexCount()) {
                return Optional.empty();
            }

            return Optional.of(new Labeling(a, b, c));
        }

        /** Vertices whose degree equals n‑1 belong to set B. */
        private static Set<Integer> identifyFullDegreeVertices(Graph g) {
            Set<Integer> b = new HashSet<>();
            for (int v = 0; v < g.vertexCount(); v++) {
                if (g.degree(v) == g.vertexCount() - 1) {
                    b.add(v);
                }
            }
            return b;
        }

        /** Builds set A around the first vertex that is not in B. */
        private static Set<Integer> identifySetA(Graph g, Set<Integer> b) {
            for (int candidate : g.vertices()) {
                if (b.contains(candidate)) {
                    continue;
                }

                Set<Integer> a = new HashSet<>(Set.of(candidate));
                for (int neighbour : g.adjacent(candidate)) {
                    if (!b.contains(neighbour)) {
                        a.add(neighbour);
                    }
                }

                // sanity check – all vertices of A must have degree |A|+|B|-1
                for (int v : a) {
                    if (g.degree(v) != a.size() + b.size() - 1) {
                        return null;
                    }
                }
                return a;
            }
            return new HashSet<>(); // Graph has no vertices outside B → nothing to do
        }

        /** Builds set C out of the still‑unlabelled vertices. */
        private static Set<Integer> identifySetC(Graph g, Set<Integer> b, Set<Integer> a) {
            for (int candidate : g.vertices()) {
                if (!b.contains(candidate) && !a.contains(candidate)) {
                    Set<Integer> c = new HashSet<>(Set.of(candidate));
                    for (int neighbour : g.adjacent(candidate)) {
                        if (!b.contains(neighbour)) {
                            c.add(neighbour);
                        }
                    }

                    // all vertices of C must have degree |C|+|B|-1
                    for (int v : c) {
                        if (g.degree(v) != c.size() + b.size() - 1) {
                            return null;
                        }
                    }
                    return c;
                }
            }
            return new HashSet<>(); // nothing left → empty C is also fine
        }

        /** Checks all per‑vertex constraints for the three sets. */
        private static boolean validateSets(Graph g,
                                            Set<Integer> a,
                                            Set<Integer> b,
                                            Set<Integer> c) {
            for (int v : g.vertices()) {
                if (a.contains(v)) {
                    enforceAdjacencyRule(g, v, a, b);
                } else if (c.contains(v)) {
                    enforceAdjacencyRule(g, v, c, b);
                } else if (b.contains(v)) {
                    // vertices in B have no special neighbour constraints
                } else {
                    // This should never happen because we covered all vertices
                    return false;
                }
            }
            return true;
        }

        /** Every neighbour of a vertex labelled with @code labelSet must lie
         *  in either @code labelSet itself or in B. */
        private static void enforceAdjacencyRule(Graph g,
                                                 int vertex,
                                                 Set<Integer> labelSet,
                                                 Set<Integer> b) {
            int expectedDegree = labelSet.size() + b.size() - 1;
            if (g.degree(vertex) != expectedDegree) {
                throw new IllegalStateException("Degree mismatch");
            }

            for (int neighbour : g.adjacent(vertex)) {
                if (!labelSet.contains(neighbour) && !b.contains(neighbour)) {
                    throw new IllegalStateException("Forbidden neighbour");
                }
            }
        }
    }

    /* --------------------------------------------------------------------- */
    /* Helper classes                                                          */
    /* --------------------------------------------------------------------- */
    /** Simple holder for the result of the labeling algorithm. */
    private static final class Labeling {
        private final Set<Integer> a;
        private final Set<Integer> b;
        private final Set<Integer> c;

        Labeling(Set<Integer> a, Set<Integer> b, Set<Integer> c) {
            this.a = a;
            this.b = b;
            this.c = c;
        }

        /** Prints the per‑vertex labels in the required order “a”, “b”, “c”. */
        void printLabels() {
            for (int i = 0; i < a.size() + b.size() + c.size(); i++) {
                if (a.contains(i)) {
                    System.out.print('a');
                } else if (b.contains(i)) {
                    System.out.print('b');
                } else {
                    System.out.print('c');
                }
            }
            System.out.println();
        }
    }

    /** Encapsulates the graph structure and provides convenient operations. */
    private static final class Graph {
        private final int vertexCount;
        private final List<Integer>[] adjacency;

        Graph(int vertexCount, List<Integer>[] adjacency) {
            this.vertexCount = vertexCount;
            this.adjacency = adjacency;
        }

        int vertexCount() {
            return vertexCount;
        }

        int degree(int v) {
            return adjacency[v].size();
        }

        List<Integer> adjacent(int v) {
            return adjacency[v];
        }

        Set<Integer> vertices() {
            Set<Integer> set = new HashSet<>(vertexCount);
            for (int i = 0; i < vertexCount; i++) {
                set.add(i);
            }
            return set;
        }
    }
}

