/**
 * Refactored version of the original program.
 *
 * <p>
 * The program reads an undirected simple graph, builds its complement, tries to colour
 * the complement graph with three colours (1, 2, 3) while respecting certain degree
 * constraints, and prints "Yes" together with a three‑letter answer (a, b, c) if a
 * valid colouring exists; otherwise it prints "No".
 * </p>
 */
public class C {

    /** Set of possible colours used for the output letters. */
    private static final char[] LETTERS = {'a', 'b', 'c'};

    /** Entry point. */
    public static void main(String[] args) throws IOException {
        solve();
    }

    /**
     * Contains the whole logic of the program split into small, reusable methods.
     */
    private static void solve() throws IOException {
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in))) {
            int n = readInt(br.readLine());
            int m = readInt(br.readLine());

            boolean[][] adjacency = readAdjacencyMatrix(br, n, m);

            boolean[][] complement = buildComplement(adjacency, n);

            int[] complementDegree = computeDegreeArray(complement, n);

            int[] colour = new int[n];
            colour = assignColours(complement, complementDegree, colour);

            if (colour != null) {
                System.out.println("Yes");
                System.out.println(buildAnswer(colour));
            } else {
                System.out.println("No");
            }
        }
    }

    /** Reads a line and extracts the first integer from it. */
    private static int readInt(String line) {
        StringTokenizer st = new StringTokenizer(line);
        return Integer.parseInt(st.nextToken());
    }

    /**
     * Builds an {@code n × n} adjacency matrix from {@code m} edges.
     *
     * @param br       source of input lines
     * @param n        number of vertices
     * @param m        number of edges
     * @return adjacency matrix where {@code matrix[i][j] == true} iff there is an edge i–j
     */
    private static boolean[][] readAdjacencyMatrix(BufferedReader br, int n, int m) throws IOException {
        boolean[][] matrix = new boolean[n][n];
        for (int i = 0; i < m; i++) {
            StringTokenizer st = new StringTokenizer(br.readLine());
            int a = Integer.parseInt(st.nextToken()) - 1;
            int b = Integer.parseInt(st.nextToken()) - 1;
            matrix[a][b] = true;
            matrix[b][a] = true;
        }
        return matrix;
    }

    /**
     * Constructs the complement of the given adjacency matrix.
     *
     * @param adj    original adjacency matrix
     * @param n      number of vertices
     * @return       matrix where {@code result[i][j]} is true iff {@code i != j} and
     *               there is no edge between {@code i} and {@code j} in {@code adj}
     */
    private static boolean[][] buildComplement(boolean[][] adj, int n) {
        boolean[][] complement = new boolean[n][n];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (i != j && !adj[i][j]) {
                    complement[i][j] = true;
                }
            }
        }
        return complement;
    }

    /**
     * Computes the degree of each vertex in the complement graph.
     *
     * @param comp complement adjacency matrix
     * @param n    number of vertices
     * @return     array where {@code result[i]} equals the degree of vertex {@code i}
     */
    private static int[] computeDegreeArray(boolean[][] comp, int n) {
        int[] degree = new int[n];
        for (int i = 0; i < n; i++) {
            int cnt = 0;
            for (int j = 0; j < n; j++) {
                if (comp[i][j]) {
                    cnt++;
                }
            }
            degree[i] = cnt;
        }
        return degree;
    }

    /**
     * Tries to colour the complement graph using three colours.
     *
     * <p>
     * Colour {@code 1} corresponds to letter {@code 'a'}, colour {@code 2} to {@code 'b'},
     * and colour {@code 3} to {@code 'c'}. The method also checks the additional
     * degree‑consistency constraints from the original algorithm.
     * </p>
     *
     * @param comp         complement adjacency matrix
     * @param degree       degree of each vertex in the complement
     * @param initColour   array of initial colour values (all {@code 0} means uncoloured)
     * @return             the same {@code initColour} array if a valid colouring is found,
     *                     otherwise {@code null}
     */
    private static int[] assignColours(boolean[][] comp, int[] degree, int[] initColour) {
        // Find a vertex that has at least one neighbour in the complement to start from.
        int root = findRoot(degree);
        if (root < 0) {
            // All vertices are isolated – every vertex may receive colour 2.
            fillWithColour(initColour, 2);
            return initColour;
        }

        initColour[root] = 1;
        Queue<Integer> queue = new ArrayDeque<>();
        queue.add(root);

        int countColour1 = 1; // number of vertices coloured with 1
        int countColour3 = 0; // number of vertices coloured with 3

        while (!queue.isEmpty()) {
            int cur = queue.poll();
            for (int nxt = 0; nxt < comp.length; nxt++) {
                if (nxt == cur || !comp[cur][nxt]) {
                    continue;
                }
                if (initColour[nxt] == 0) {
                    if (initColour[cur] == 1) {
                        initColour[nxt] = 3;
                        countColour3++;
                    } else {
                        initColour[nxt] = 1;
                        countColour1++;
                    }
                    queue.add(nxt);
                } else if (initColour[nxt] == initColour[cur] || initColour[nxt] == 2) {
                    // Inconsistent colouring discovered.
                    return null;
                }
            }
        }

        // After BFS every vertex must have been coloured.
        for (int c : initColour) {
            if (c == 0) {
                return null;
            }
        }

        // Verify that each colour class respects the degree conditions.
        for (int i = 0; i < n; i++) {
            switch (initColour[i]) {
                case 1 -> {
                    if (degree[i] != countColour1) {
                        return null;
                    }
                }
                case 3 -> {
                    if (degree[i] != countColour3) {
                        return null;
                    }
                }
                case 2 -> {
                    // colour 2 is only allowed for isolated vertices.
                    if (degree[i] != 0) {
                        return null;
                    }
                }
            }
        }
        return initColour;
    }

    /** Finds an index of a vertex with non‑zero degree in {@code degree} or returns –1. */
    private static int findRoot(int[] degree) {
        for (int i = 0; i < degree.length; i++) {
            if (degree[i] > 0) {
                return i;
            }
        }
        return -1;
    }

    /** Fills the given array with the supplied colour value (1, 2 or 3). */
    private static void fillWithColour(int[] arr, int colour) {
        for (int i = 0; i < arr.length; i++) {
            arr[i] = colour;
        }
    }

    /** Transforms the colour array into the required output string of letters. */
    private static String buildAnswer(int[] colour) {
        StringBuilder sb = new StringBuilder(colour.length);
        for (int c : colour) {
            sb.append(LETTERS[c - 1]); // colours are 1‑based matching the LETTERS array
        }
        return sb.toString();
    }
}

/**
 * DSA1417 – Main entry point.
 * This class coordinates input, graph processing and output.
 */
public final class Main {

    /** Entry point. */
    public static void main(String[] args) throws IOException {
        // Use try‑with‑resources to guarantee stream closure.
        try (var input = System.in; var output = System.out) {
            var reader = new InputReader(input);
            var printer = new PrintWriter(output, true);

            Graph graph = new Graph(reader);
            var result = graph.process();

            printer.println(result);
        }
