/**
 * Reads tokens from the input stream.
 * Wraps java.io.BufferedReader for convenient tokenisation.
 */
class InputReader {
    private final StringTokenizer tokenizer;

    InputReader(InputStream stream) {
        tokenizer = null;
        // Note: the field is deliberately left package‑private to simplify testing.
    }

    String next() {
        while (tokenizer == null || !tokenizer.hasMoreTokens()) {
            try {
                tokenizer = new StringTokenizer(new BufferedReader(
                        new InputStreamReader(System.in)).readLine());
            } catch (IOException e) {
                throw new UncheckedIOException(e);
            }
        }
        return tokenizer.nextToken();
    }

    int nextInt() {
        return Integer.parseInt(next());
    }
}

/**
 * Encapsulates all graph‑related logic.
 * The class is deliberately immutable after construction – this makes it easier
 * to reason about state and test individual methods.
 */
final class Graph {

    private final int vertexCount;
    private final boolean[][] adjacency;   // true = edge exists
    private final int[] degree;            // degree of each vertex after edge removal
    private final int[] color;             // 0 = uncoloured, 1/2 = two colours of a bipartition

    Graph(InputReader reader) {
        this.vertexCount = reader.nextInt();
        int edgeCount = reader.nextInt();

        // Initialise a complete (undirected) graph.
        adjacency = new boolean[vertexCount][vertexCount];
        degree = new int[vertexCount];
        for (int i = 0; i < vertexCount; i++) {
            Arrays.fill(adjacency[i], true);
            degree[i] = vertexCount - 1;
        }

        // Remove the specified edges.
        for (int i = 0; i < edgeCount; i++) {
            int u = reader.nextInt() - 1;
            int v = reader.nextInt() - 1;
            removeEdge(u, v);
        }

        // Prepare temporary containers used during DFS.
        color = new int[vertexCount];
        // No explicit visitation array needed – we treat “uncoloured” as “unvisited”.
    }

    /**
     * Executes the required algorithm:
     *   1. Checks bipartiteness via DFS.
     *   2. Computes per‑vertex labels.
     *   3. Verifies the global constraint (pairwise differences).
     *   4. Returns a string that is either "No" or "Yes" followed by the
     *      resulting label sequence encoded as letters.
     */
    String process() {
        // Step 1 – ensure the graph is bipartite (connected components individually).
        for (int v = 0; v < vertexCount; v++) {
            if (color[v] == 0) {
                if (!isBipartite(v, 1)) {
                    return "No";
                }
            }
        }

        // Step 2 – assign final labels according to the problem statement.
        int[] finalLabel = assignLabels();

        // Step 3 – validate the pairwise condition.
        if (!satisfiesPairwiseConstraint(finalLabel)) {
            return "No";
        }

        // Step 4 – encode answer as required.
        StringBuilder builder = new StringBuilder(vertexCount);
        for (int label : finalLabel) {
            builder.append((char) ('a' + label));
        }
        return "Yes\n" + builder.toString();
    }

    /** Removes an undirected edge (u, v) from the adjacency matrix and updates degrees. */
    private void removeEdge(int u, int v) {
        if (adjacency[u][v]) {
            adjacency[u][v] = false;
            adjacency[v][u] = false;
            degree[u]--;
            degree[v]--;
        }
    }

    /**
     * Depth‑first search that checks bipartiteness starting from `start`.
     *
     * @param start   vertex from which the search originates
     * @param colour  the colour we assign to `start` (used as a binary flag)
     * @return true iff the component containing `start` is bipartite
     */
    private boolean isBipartite(int start, int colour) {
        // Use a stack to avoid deep recursion (stack‑safe for typical constraints).
        Deque<Integer> stack = new ArrayDeque<>();
        stack.push(start);
        color[start] = colour;

        while (!stack.isEmpty()) {
            int current = stack.pop();
            int curColour = color[current];

            for (int neighbour = 0; neighbour < vertexCount; neighbour++) {
                if (neighbour == current || !adjacency[current][neighbour]) {
                    continue;
                }

                if (color[neighbour] == 0) {
                    color[neighbour] = curColour ^ 1; // flip colour
                    stack.push(neighbour);
                } else if (color[neighbour] == curColour) {
                    // Same colour on adjacent vertices → not bipartite.
                    return false;
                }
            }
        }
        return true;
    }

    /**
     * Produces the final integer label for each vertex:
     *   - 1 if its degree became 0 after edge removal.
     *   - 2 if it received colour 1 in the bipartite colouring.
     *   - 0 otherwise (preserves colour 2 as label 0).
     *
     * The method returns a freshly allocated array; callers must treat it as immutable.
     */
    private int[] assignLabels() {
        int[] labels = new int[vertexCount];
        for (int i = 0; i < vertexCount; i++) {
            if (degree[i] == 0) {
                labels[i] = 1;
            } else if (color[i] == 1) {
                labels[i] = 2;
            } else {
                labels[i] = 0;
            }
        }
        return labels;
    }

    /**
     * Checks the global constraint: for every unordered pair (i, j) we must have
     *   • label[i] != label[j]  and
     *   • |label[i] - label[j]| != 1
     * The original algorithm decremented a counter `m` for each violating pair.
     * Here we simply return false as soon as a violation is detected.
     *
     * @param labels array of vertex labels
     * @return true if the pairwise condition holds for all pairs
     */
    private boolean satisfiesPairwiseConstraint(int[] labels) {
        for (int i = 0; i < vertexCount; i++) {
            for (int j = i + 1; j < vertexCount; j++) {
                int diff = Math.abs(labels[i] - labels[j]);
                if (labels[i] == labels[j] || diff == 1) {
                    // The original code subtracted one from `m` for each such pair.
                    // If *any* pair remains that would keep `m` non‑zero, we reject.
                    return false;
                }
            }
        }
        return true;
    }
}

import java.io.*;
import java.util.*;

public class Main {

    /* --------------------------------------------------------------------- */
    /*  Constants – they replace the raw characters used in the original code */
    private static final char LABEL_A = 'a';
    private static final char LABEL_B = 'b';
    private static final char LABEL_C = 'c';

    /** Sentinel value used to signal an inconsistency during DFS. */
    private static final int FAILURE = -1;

    /* --------------------------------------------------------------------- */
    /*  I/O fields */
    private BufferedReader reader;
    private PrintWriter writer;
    private StringTokenizer tokenizer;

    /** Complement‑graph representation: missingAdj[i] contains every vertex
     *  that is *not* adjacent to i in the original graph. */
    private List<Set<Integer>> missingAdj;

    /** Current label assigned to each vertex. */
    private char[] labels;

    /* --------------------------------------------------------------------- */
    /*  Entry point */
    public static void main(String[] args) {
        new Main().run();
    }

    /* --------------------------------------------------------------------- */
    /*  Orchestrates input, processing and output. */
    private void run() throws IOException {
        setupIO();
        try {
            solve();
        } finally {
            writer.flush();
            writer.close();
        }
    }

    /* --------------------------------------------------------------------- */
    /*  Core algorithm */
    private void solve() {
        int n = readInt();                 // number of vertices
        int m = readInt();                 // number of edges in the original graph
        buildMissingAdjacency(n);          // fill with all possible non‑self edges
        removeProvidedEdges(m);            // delete the m edges that *are* present

        // each vertex starts with the label 'b'
        labels = new char[n];
        Arrays.fill(labels, LABEL_B);
        int componentCount = 0;            // how many DFS “components” were processed

        for (int start = 0; start < n; start++) {
            if (labels[start] == LABEL_B) {
                int dfsResult = dfs(start, LABEL_A);
                if (dfsResult == FAILURE) {
                    output("No");
                    return;
                }
                // a component of size 1 means the start vertex stayed labelled 'b'
                if (dfsResult == 1) {
                    labels[start] = LABEL_B;
                } else {
                    componentCount++;
                }
            }
        }

        // According to the original logic we only continue when componentCount is
        // either 0 or 1; any other value makes the answer impossible.
        if (componentCount != 0 && componentCount != 1) {
            output("No");
            return;
        }

        // Verify that no pair of non‑adjacent vertices has labels at distance 2
        if (violatesConstraints()) {
            output("No");
        } else {
            output("Yes");
            writer.println(String.valueOf(labels));
        }
    }

    /* --------------------------------------------------------------------- */
    /*  Builds the complement adjacency list (all possible edges except self). */
    private void buildMissingAdjacency(int n) {
        missingAdj = new ArrayList<>(n);
        for (int i = 0; i < n; i++) {
            Set<Integer> neighbours = new HashSet<>();
            for (int j = 0; j < n; j++) {
                if (i != j) neighbours.add(j);
            }
            missingAdj.add(neighbours);
        }
    }

    /* --------------------------------------------------------------------- */
    /*  Removes the m edges supplied in the input from the complement graph. */
    private void removeProvidedEdges(int m) {
        for (int i = 0; i < m; i++) {
            int u = readInt() - 1;
            int v = readInt() - 1;
            missingAdj.get(u).remove(Integer.valueOf(v));
            missingAdj.get(v).remove(Integer.valueOf(u));
        }
    }

    /* --------------------------------------------------------------------- */
    /*  Depth‑first search that assigns alternating labels 'a' and 'c'.
     *
     *  @param v        current vertex
     *  @param expectedLabel label that must be placed on v
     *  @return number of vertices processed in this DFS call,
     *          or {@link #FAILURE} if a conflict is detected.
     */
    private int dfs(int v, char expectedLabel) {
        labels[v] = expectedLabel;
        int processed = 1;

        for (int neighbour : missingAdj.get(v)) {
            // Conflict – two vertices that must be non‑adjacent receive the same label
            if (labels[neighbour] == expectedLabel) {
                return FAILURE;
            }

            // If neighbour has not been labelled yet, continue the search
            if (labels[neighbour] == LABEL_B) {
                char nextLabel = (expectedLabel == LABEL_A) ? LABEL_C : LABEL_A;
                int subResult = dfs(neighbour, nextLabel);
                if (subResult == FAILURE) {
                    return FAILURE;
                }
                processed += subResult;
            }
        }
        return processed;
    }

    /* --------------------------------------------------------------------- */
    /*  Checks the final feasibility condition: any pair of non‑adjacent
     *  vertices whose labels differ by exactly 2 makes the whole instance
     *  invalid. */
    private boolean violatesConstraints() {
        for (int i = 0; i < labels.length; i++) {
            for (int j = 0; j < labels.length; j++) {
                if (!missingAdj.get(i).contains(j) && Math.abs(labels[i] - labels[j]) == 2) {
                    return true;
                }
            }
        }
        return false;
    }

    /* --------------------------------------------------------------------- */
    /*  Small wrapper used to print the literal "No". */
    private void output(String token) {
        writer.println(token);
    }

    /* --------------------------------------------------------------------- */
    /*  Input helpers – a tiny Lexer over the token stream. */
    private void setupIO() throws IOException {
        reader = new BufferedReader(new InputStreamReader(System.in));
        writer = new PrintWriter(System.out);
        tokenizer = new StringTokenizer(reader.readLine());
    }

    /** Returns the next token, expanding the tokenizer when necessary. */
    private String nextToken() throws IOException {
        while (tokenizer == null || !tokenizer.hasMoreTokens()) {
            tokenizer = new StringTokenizer(reader.readLine());
        }
        return tokenizer.nextToken();
    }

    /** Reads an integer from the input stream. */
    private int readInt() throws IOException {
        return Integer.parseInt(nextToken());
    }
}

import java.io.BufferedReader;
import java.io.BufferedWriter;
import java.io.IOException;
import java.io.InputStream;
import java.io.OutputStream;
import java.util.HashSet;
import java.util.List;
import java.util.Scanner;
import java.util.Set;

/**
 * Solution for the “Graph and String” problem.
 * <p>
 * The algorithm works as follows:
 * <ul>
 *   <li>Read an undirected graph with V vertices and E edges.</li>
 *   <li>Identify three disjoint vertex sets:
 *       <ul>
 *         <li>A – a mixed neighbourhood (chosen based on degree conditions).</li>
 *         <li>B – vertices that are adjacent to all other vertices.</li>
 *         <li>C – the remaining vertices.</li>
 *       </ul>
 *   </li>
 *   <li>Validate that each set satisfies specific adjacency constraints.</li>
 *   <li>If validation succeeds, output “Yes” followed by a string of length V
 *       composed of the characters ‘a’, ‘b’ and ‘c’ representing membership in
 *       sets A, B and C respectively.</li>
 * </ul>
 *
 * <p>All I/O is performed through {@link FastScanner} and {@link FastWriter}
 * which wrap {@code System.in} and {@code System.out} for speed.</p>
 */
public final class GraphStringSolver {

    /** Character used to denote membership in set A. */
    private static final char CHAR_A = 'a';
    /** Character used to denote membership in set B. */
    private static final char CHAR_B = 'b';
    /** Character used to denote membership in set C. */
    private static final char CHAR_C = 'c';

    private GraphStringSolver() {
        /* utility class – no instances */
    }

    public static void main(String[] args) throws IOException {
        try (FastScanner scanner = new FastScanner(System.in);
             FastWriter writer = new FastWriter(System.out)) {

            solve(scanner, writer);
        }
    }

    /**
     * Orchestrates the whole solving process.
     *
     * @param scanner input scanner
     * @param writer  output writer
     */
    private static void solve(FastScanner scanner, FastWriter writer) {
        int vertexCount = scanner.nextInt();
        int edgeCount = scanner.nextInt();

        /* ---- Special case: no edges ------------------------------------------------ */
        if (edgeCount == 0) {
            if (vertexCount == 1 || vertexCount == 2) {
                writer.println("Yes");
                writer.print(vertexCount == 1 ? "a" : "ac");
            } else {
                writer.print("No");
            }
            return;
        }

        /* ---- Build adjacency list --------------------------------------------------- */
        List<Set<Integer>> adjacency = buildAdjacencyList(vertexCount, scanner);

        /* ---- Derive the three sets based on degree conditions ---------------------- */
        Set<Integer> setB = findUniversalVertices(vertexCount, adjacency);
        Set<Integer> setA = discoverSetA(vertexCount, adjacency, setB);
        Set<Integer> setC = remainingVertices(vertexCount, setA, setB);

        /* ---- Validate the derived sets ------------------------------------------------ */
        if (!validateSetA(vertexCount, adjacency, setA, setB, setC)) {
            writer.print("No");
            return;
        }
        if (!validateSetB(vertexCount, adjacency, setA, setB, setC)) {
            writer.print("No");
            return;
        }
        if (!validateSetC(vertexCount, adjacency, setA, setB, setC)) {
            writer.print("No");
            return;
        }

        /* ---- All checks passed – output the answer --------------------------------- */
        writer.println("Yes");
        writer.print(constructResultString(vertexCount, setA, setB, setC));
    }

    /**
     * Constructs an adjacency list (indexed from 1) for the given graph.
     *
     * @param vertexCount number of vertices
     * @param scanner     scanner that provides the edge list
     * @return adjacency list where {@code adjacency.get(i)} holds the neighbours of vertex i
     */
    private static List<Set<Integer>> buildAdjacencyList(int vertexCount, FastScanner scanner) {
        // initialise list with empty sets (index 0 unused)
        List<Set<Integer>> adjacency = new java.util.ArrayList<>(vertexCount + 1);
        for (int i = 0; i <= vertexCount; i++) {
            adjacency.add(new HashSet<>());
        }

        // read edges and populate adjacency sets
        for (int i = 0; i < edgeCount; i++) {
            int u = scanner.nextInt();
            int v = scanner.nextInt();
            adjacency.get(u).add(v);
            adjacency.get(v).add(u);
        }
        return adjacency;
    }

    /**
     * Finds all vertices that are adjacent to every other vertex (degree == V‑1).
     *
     * @param vertexCount number of vertices
     * @param adjacency   adjacency list
     * @return set of universal vertices
     */
    private static Set<Integer> findUniversalVertices(int vertexCount,
                                                        List<Set<Integer>> adjacency) {
        Set<Integer> universal = new HashSet<>();
        for (int v = 1; v <= vertexCount; v++) {
            if (adjacency.get(v).size() == vertexCount - 1) {
                universal.add(v);
            }
        }
        return universal;
    }

    /**
     * Determines set {@code A}:
     * <p>
     * Choose a vertex that is not universal, put it into {@code A}, and also add all
     * of its neighbours that are not universal.</p>
     *
     * @param vertexCount   number of vertices
     * @param adjacency     adjacency list
     * @param universalSet  set of universal vertices (B)
     * @return set A
     */
    private static Set<Integer> discoverSetA(int vertexCount,
                                             List<Set<Integer>> adjacency,
                                             Set<Integer> universalSet) {
        Set<Integer> aSet = new HashSet<>();
        for (int v = 1; v <= vertexCount; v++) {
            if (!universalSet.contains(v)) {
                aSet.add(v);
                for (int neighbour : adjacency.get(v)) {
                    if (!universalSet.contains(neighbour)) {
                        aSet.add(neighbour);
                    }
                }
                break; // only one such vertex is needed
            }
        }
        return aSet;
    }

    /**
     * Returns the vertices that are neither in {@code A} nor in {@code B}.
     *
     * @param vertexCount total vertices
     * @param aSet        set A
     * @param bSet        set B
     * @return set C
     */
    private static Set<Integer> remainingVertices(int vertexCount,
                                                  Set<Integer> aSet,
                                                  Set<Integer> bSet) {
        Set<Integer> cSet = new HashSet<>();
        for (int v = 1; v <= vertexCount; v++) {
            if (!aSet.contains(v) && !bSet.contains(v)) {
                cSet.add(v);
            }
        }
        return cSet;
    }

    /**
     * Validates the adjacency constraints for set {@code A}.
     *
     * @param vertexCount   number of vertices
     * @param adjacency     adjacency list
     * @param aSet          set A
     * @param bSet          set B
     * @param cSet          set C
     * @return true if all vertices in A satisfy the required condition
     */
    private static boolean validateSetA(int vertexCount,
                                        List<Set<Integer>> adjacency,
                                        Set<Integer> aSet,
                                        Set<Integer> bSet,
                                        Set<Integer> cSet) {
        int requiredDegree = aSet.size() + bSet.size() - 1;
        for (int vertex : aSet) {
            int missing = 0;
            for (int neighbour : adjacency.get(vertex)) {
                if (aSet.contains(neighbour) || bSet.contains(neighbour)) {
                    missing++;
                }
                if (cSet.contains(neighbour)) {
                    // illegal adjacency to C
                    return false;
                }
            }
            if (missing != requiredDegree) {
                return false;
            }
        }
        return true;
    }

    /**
     * Validates the adjacency constraints for set {@code B}.
     *
     * @param vertexCount   number of vertices
     * @param adjacency     adjacency list
     * @param aSet          set A
     * @param bSet          set B
     * @param cSet          set C
     * @return true if all vertices in B satisfy the required condition
     */
    private static boolean validateSetB(int vertexCount,
                                        List<Set<Integer>> adjacency,
                                        Set<Integer> aSet,
                                        Set<Integer> bSet,
                                        Set<Integer> cSet) {
        int requiredDegree = aSet.size() + bSet.size() + cSet.size() - 1;
        for (int vertex : bSet) {
            int missing = 0;
            for (int neighbour : adjacency.get(vertex)) {
                if (aSet.contains(neighbour) || bSet.contains(neighbour) || cSet.contains(neighbour)) {
                    missing++;
                }
            }
            if (missing != requiredDegree) {
                return false;
            }
        }
        return true;
    }

    /**
     * Validates the adjacency constraints for set {@code C}.
     *
     * @param vertexCount   number of vertices
     * @param adjacency     adjacency list
     * @param aSet          set A
     * @param bSet          set B
     * @param cSet          set C
     * @return true if all vertices in C satisfy the required condition
     */
    private static boolean validateSetC(int vertexCount,
                                        List<Set<Integer>> adjacency,
                                        Set<Integer> aSet,
                                        Set<Integer> bSet,
                                        Set<Integer> cSet) {
        int requiredDegree = cSet.size() + bSet.size() - 1;
        for (int vertex : cSet) {
            int missing = 0;
            for (int neighbour : adjacency.get(vertex)) {
                if (cSet.contains(neighbour) || bSet.contains(neighbour)) {
                    missing++;
                }
                if (aSet.contains(neighbour)) {
                    // illegal adjacency from C to A
                    return false;
                }
            }
            if (missing != requiredDegree) {
                return false;
            }
        }
        return true;
    }

    /**
     * Constructs the output string that encodes membership in sets A, B and C.
     *
     * @param vertexCount number of vertices
     * @param aSet        set A
     * @param bSet        set B
     * @param cSet        set C
     * @return a string of length {@code vertexCount} consisting of 'a', 'b', 'c'
     */
    private static String constructResultString(int vertexCount,
                                               Set<Integer> aSet,
                                               Set<Integer> bSet,
                                               Set<Integer> cSet) {
        char[] result = new char[vertexCount];
        for (int v = 1; v <= vertexCount; v++) {
            if (aSet.contains(v)) {
                result[v - 1] = CHAR_A;
            } else if (bSet.contains(v)) {
                result[v - 1] = CHAR_B;
            } else {
                result[v - 1] = CHAR_C;
            }
        }
        return new String(result);
    }
}

