/**
 * Fast scanner that reads tokens from {@code System.in} using a
 * {@link BufferedReader} and a {@link StringTokenizer}.
 */
class FastScanner {
    private final BufferedReader reader;
    private StringTokenizer tokenizer;

    FastScanner(InputStream stream) {
        this.reader = new BufferedReader(new java.io.InputStreamReader(stream));
        this.tokenizer = null;
    }

    /** Returns the next token, or {@code null} if the stream is exhausted. */
    private String nextToken() {
        while (tokenizer == null || !tokenizer.hasMoreTokens()) {
            try {
                String line = reader.readLine();
                if (line == null) {
                    return null;
                }
                tokenizer = new StringTokenizer(line);
            } catch (Exception e) {
                throw new RuntimeException(e);
            }
        }
        return tokenizer.nextToken();
    }

    public String next() {
        return nextToken();
    }

    public int nextInt() {
        return Integer.parseInt(next());
    }

    public long nextLong() {
        return Long.parseLong(next());
    }

    public double nextDouble() {
        return Double.parseDouble(next());
    }

    public int[] nextIntArray(int n) {
        int[] arr = new int[n];
        for (int i = 0; i < n; i++) {
            arr[i] = nextInt();
        }
        return arr;
    }

    public void close() {
        try {
            reader.close();
        } catch (IOException e) {
            e.printStackTrace();
        }
    }
}

/**
