            writer.close();
        } catch (IOException e) {
            e.printStackTrace();
        }
    }
}

import java.io.*;
import java.util.*;

public class Solution {

    /* Fast scanner to avoid repeated StringTokenizer boilerplate */
    private static final class FastScanner {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        FastScanner(InputStream source) {
            reader = new BufferedReader(new InputStreamReader(source));
        }

        private void ensureTokens() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                tokenizer = new StringTokenizer(reader.readLine());
            }
        }

        int nextInt() throws IOException {
            ensureTokens();
            return Integer.parseInt(tokenizer.nextToken());
        }

        String next() throws IOException {
            ensureTokens();
            return tokenizer.nextToken();
        }
    }

    /* Constants for the three possible colors */
    private static final char COLOR_A = 'a';
    private static final char COLOR_B = 'b';
    private static final char COLOR_C = 'c';

    public static void main(String[] args) throws Exception {
        try (FastScanner fs = new FastScanner(System.in)) {
            int n = fs.nextInt();          // number of vertices
            int m = fs.nextInt();          // number of forced non‑edges

            boolean[][] adj = buildAdjacencyMatrix(n, m, fs);

            char[] colors = assignColors(adj, n);
            if (colors == null) {
                System.out.println("No");
                return;
            }

            if (!validate(adj, colors)) {
                System.out.println("No");
                return;
            }

            System.out.println("Yes");
            System.out.println(new String(colors));
        }
    }

    /**
     * Builds the adjacency matrix where {@code adj[i][j]==true} means there is an edge
     * between vertex i and vertex j. Initially every distinct pair is connected,
     * then the {@code m} given edges are removed.
     */
    private static boolean[][] buildAdjacencyMatrix(int n, int m, FastScanner fs) throws IOException {
        boolean[][] adj = new boolean[n][n];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                adj[i][j] = i != j;                 // all non‑self loops present
            }
        }

        for (int i = 0; i < m; i++) {
            int a = fs.nextInt() - 1;   // convert to 0‑based indices
            int b = fs.nextInt() - 1;
            adj[a][b] = false;
            adj[b][a] = false;
        }
        return adj;
    }

    /**
     * Assigns colors to vertices.
     * <ul>
     *   <li>'b' – isolated vertices (default)</li>
     *   <li>'a'/'c' – vertices that are connected by an edge.
     *        The first encountered edge receives the colors 'a' and 'c',
     *        and subsequent edges propagate the alternating pattern.
     * </ul>
     * @return an array of colors, or {@code null} if assignment is impossible.
     */
    private static char[] assignColors(boolean[][] adj, int n) {
        char[] colors = new char[n];
        Arrays.fill(colors, COLOR_B);

        boolean foundFirstEdge = false;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (i == j || !adj[i][j]) continue;   // skip self‑loops and non‑edges

                if (!foundFirstEdge) {
                    // first edge gets the special a/c pair
                    colors[i] = COLOR_A;
                    colors[j] = COLOR_C;
                    foundFirstEdge = true;
                } else {
                    // maintain the alternating a↔c relationship
                    if (colors[i] == colors[j]) {
                        return null; // impossible
                    }
                    // ensure the two endpoints have opposite {a,c} colors
                    if (colors[i] == COLOR_A) colors[j] = COLOR_C;
                    else if (colors[i] == COLOR_C) colors[j] = COLOR_A;
                    else if (colors[j] == COLOR_A) colors[i] = COLOR_C;
                    else if (colors[j] == COLOR_C) colors[i] = COLOR_A;
                }
            }
        }
        // If no edge ever existed, the default all‑'b' coloring stays.
        return colors;
    }

    /**
     * Validates whether the current coloring satisfies all problem constraints:
     * <ul>
     *   <li>A vertex coloured 'b' must have no incident edges.</li>
     *   <li>Two vertices of the same non‑'b' colour must NOT be adjacent.</li>
     *   <li>Two vertices of different non‑'b' colours must be adjacent.</li>
     * </ul>
     */
    private static boolean validate(boolean[][] adj, char[] colors) {
        int n = colors.length;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (colors[i] == COLOR_B) {
                    if (adj[i][j]) return false;          // isolated vertex expected
                    continue;
                }
                if (colors[j] == COLOR_B) {
                    if (adj[i][j]) return false;          // isolated vertex expected
                    continue;
                }
                if (colors[i] == colors[j]) {
                    if (adj[i][j]) return false;          // same colour must not be adjacent
                } else {
                    if (!adj[i][j]) return false;         // different colours must be adjacent
                }
            }
        }
        return true;
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.*;

/**
 * Solution for problem “C624”.
 *
 * The program reads an undirected graph, analyses its structure and prints a
 * labeling of the vertices with the characters 'a', 'b' and 'c' that satisfies
 * the required constraints.
 */
public class Main {

    /** Simple immutable pair used as a key for grouping nodes. */
    private static final class Pair {
        final int first;
        final int second;

        Pair(int first, int second) {
            this.first  = first;
            this.second = second;
        }

        @Override public boolean equals(Object o) {
            if (this == o) return true;
            if (!(o instanceof Pair)) return false;
            Pair pair = (Pair) o;
            return first == pair.first && second == pair.second;
        }

        @Override public int hashCode() {
            return Objects.hash(first, second);
        }

        @Override public String toString() {
            return "(" + first + ", " + second + ")";
        }
    }

    /** Encapsulates the graph data structure. */
    private static final class Graph {
        private final int size;
        private final int[][] adjacency; // 1‑based adjacency matrix
        private final int[] degree;      // degree[i] = number of incident edges

        Graph(int size) {
            this.size  = size;
            this.adjacency = new int[size + 1][size + 1];
            this.degree  = new int[size + 1];
        }

        /** Adds an undirected edge (u, v). */
        void addEdge(int u, int v) {
            if (u == v) return;
            adjacency[u][v] = adjacency[v][u] = 1;
            degree[u]++;
            degree[v]++;
        }

        /** Returns the degree of the given node. */
        int getDegree(int node) {
            return degree[node];
        }

        /** Returns the adjacency value between two nodes. */
        int getAdjacency(int u, int v) {
            return adjacency[u][v];
        }
    }

    public static void main(String[] args) throws IOException {
        /* -------------------------------------------------------------
         *  Input handling
         * ------------------------------------------------------------- */
        try (BufferedReader br = new BufferedReader(
                new InputStreamReader(System.in))) {

            String[] header = br.readLine().split("\\s+");
            int n = Integer.parseInt(header[0]);
            int m = Integer.parseInt(header[1]);

            Graph graph = new Graph(n);
            Set<Integer> universal = new HashSet<>();

            /* -------------------------------------------------------------
             *  Build the graph and collect “universal” vertices (degree = n‑1)
             * ------------------------------------------------------------- */
            for (int i = 0; i < m; i++) {
                String[] parts = br.readLine().split("\\s+");
                int u = Integer.parseInt(parts[0]);
                int v = Integer.parseInt(parts[1]);
                graph.addEdge(u, v);

                if (graph.getDegree(u) == n - 1) universal.add(u);
                if (graph.getDegree(v) == n - 1) universal.add(v);
            }

            // Nodes that never appear in an edge can still be universal.
            for (int i = 1; i <= n; i++) {
                if (!universal.contains(i) && graph.getDegree(i) == n - 1) {
                    universal.add(i);
                }
            }

            /* -------------------------------------------------------------
             *  Find the *only* non‑universal vertex (if any)
             * ------------------------------------------------------------- */
            Integer nonUniversal = null;
            for (int i = 1; i <= n; i++) {
                if (!universal.contains(i)) {
                    nonUniversal = i;
                    break;
                }
            }

            /* -------------------------------------------------------------
             *  Group remaining vertices by (degree, adjacency to non‑universal)
             * ------------------------------------------------------------- */
            Map<Pair, List<Integer>> groups = new HashMap<>();
            for (int i = 1; i <= n; i++) {
                if (universal.contains(i)) continue;

                int deg        = graph.getDegree(i);
                int adjToNonU  = graph.getAdjacency(i, nonUniversal);
                Pair   key     = new Pair(deg, adjToNonU);

                groups.computeIfAbsent(key, k -> new ArrayList<>()).add(i);
            }

            /* -------------------------------------------------------------
             *  Validation
             * ------------------------------------------------------------- */
            // More than two distinct groups → impossible.
            if (groups.size() > 2) {
                System.out.println("No");
                return;
            }

            // Every group must be a clique.
            for (List<Integer> group : groups.values()) {
                for (int a : group) {
                    for (int b : group) {
                        if (a != b && graph.getAdjacency(a, b) == 0) {
                            System.out.println("No");
                            return;
                        }
                    }
                }
            }

            /* -------------------------------------------------------------
             *  Build the output string
             * ------------------------------------------------------------- */
            char[] result = new char[n];
            // default label – will be overwritten later
            Arrays.fill(result, 'a');

            // universal vertices get label 'b'
            for (int u : universal) {
                result[u - 1] = 'b';
            }

            // assign 'a' to the first group, 'c' to the second (if present)
            int groupIndex = 0;
            for (List<Integer> group : groups.values()) {
                char label = (groupIndex == 0) ? 'a' : 'c';
                groupIndex++;
                for (int v : group) {
                    result[v - 1] = label;
                }
            }

            System.out.println("Yes");
            System.out.println(new String(result));
        }
    }
}

import java.util.*;

/**
 * Refactored version of the original program.
 * <p>
 * The code has been reorganised into small, well‑named methods,
 * uses meaningful identifiers, constants and Java‑8‑style constructs,
 * and isolates the core logic from I/O.  All original behaviour is
 * preserved.
 */
public class GraphLabeler {

    /* --------------------------------------------------------------------- */
    /*                     Constants & Helper Types                         */
    /* --------------------------------------------------------------------- */
    private static final char LABEL_A = 'a';
    private static final char LABEL_B = 'b';
    private static final char LABEL_C = 'c';

    /** The original `match` method – only rejects the pair (a, c). */
    private static boolean isValidAdjacency(char source, char target) {
        return !(source == LABEL_A && target == LABEL_C);
    }

    /** Simple container for the graph data. */
    private static final class Graph {
        final int vertexCount;
        final List<Integer>[] adjacency;

        Graph(int vertexCount, List<Integer>[] adjacency) {
            this.vertexCount = vertexCount;
            this.adjacency = adjacency;
        }
    }

    /* --------------------------------------------------------------------- */
    /*                               Entry Point                              */
    /* --------------------------------------------------------------------- */
    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            Graph graph = readGraph(scanner);
            char[] labels = assignLabels(graph);
            String answer = buildAnswer(labels);

            if (validateAssignment(graph, labels)) {
                System.out.println("Yes\n" + answer);
            } else {
                System.out.println("No");
            }
        }
    }

    /* --------------------------------------------------------------------- */
    /*                            Input Handling                              */
    /* --------------------------------------------------------------------- */
    private static Graph readGraph(Scanner sc) {
        int n = sc.nextInt();          // number of vertices
        int m = sc.nextInt();          // number of edges

        @SuppressWarnings("unchecked")
        List<Integer>[] adjacency = new ArrayList[n];
        for (int i = 0; i < n; i++) {
            adjacency[i] = new ArrayList<>();
        }

        for (int i = 0; i < m; i++) {
            int u = sc.nextInt() - 1;
            int v = sc.nextInt() - 1;
            adjacency[u].add(v);
            adjacency[v].add(u);
        }
        return new Graph(n, adjacency);
    }

    /* --------------------------------------------------------------------- */
    /*                           Label Assignment                             */
    /* --------------------------------------------------------------------- */
    private static char[] assignLabels(Graph graph) {
        char[] label = new char[graph.vertexCount];
        Arrays.fill(label, 'x');

        /* ---- vertices adjacent to every other vertex become 'b' ---- */
        for (int i = 0; i < graph.vertexCount; i++) {
            if (graph.adjacency[i].size() == graph.vertexCount - 1) {
                label[i] = LABEL_B;
            }
        }

        /* ---- spread 'a' from the first unmarked vertex ---- */
        int firstUnmarked = indexOf(label, 'x');
        if (firstUnmarked >= 0) {
            label[firstUnmarked] = LABEL_A;
            spreadLabel(label, graph.adjacency, firstUnmarked, LABEL_A);
        }

        /* ---- the rest become 'c' ---- */
        for (int i = 0; i < graph.vertexCount; i++) {
            if (label[i] == 'x') {
                label[i] = LABEL_C;
            }
        }

        /* ---- verify that all 'a' and all 'c' vertices form cliques ---- */
        if (!isClique(graph.adjacency, collectIndices(label, LABEL_A))) {
            System.out.println("No");
            System.exit(0);
        }
        if (!isClique(graph.adjacency, collectIndices(label, LABEL_C))) {
            System.out.println("No");
            System.exit(0);
        }

        return label;
    }

    /** Breadth‑first spread of a given label starting from `start`. */
    private static void spreadLabel(char[] label,
                                    List<Integer>[] adjacency,
                                    int start,
                                    char targetLabel) {
        Queue<Integer> queue = new ArrayDeque<>();
        queue.add(start);
        while (!queue.isEmpty()) {
            int cur = queue.poll();
            for (int nb : adjacency[cur]) {
                if (label[nb] == 'x') {
                    label[nb] = targetLabel;
                    queue.add(nb);
                }
            }
        }
    }

    private static int indexOf(char[] arr, char value) {
        for (int i = 0; i < arr.length; i++) {
            if (arr[i] == value) {
                return i;
            }
        }
        return -1;
    }

    private static List<Integer> collectIndices(char[] label, char target) {
        List<Integer> indices = new ArrayList<>();
        for (int i = 0; i < label.length; i++) {
            if (label[i] == target) {
                indices.add(i);
            }
        }
        return indices;
    }

    /** Checks whether a set of vertices induces a clique. */
    private static boolean isClique(List<Integer>[] adj, List<Integer> vertices) {
        for (int i = 0; i < vertices.size(); i++) {
            int u = vertices.get(i);
            for (int j = i + 1; j < vertices.size(); j++) {
                int v = vertices.get(j);
                if (!adj[u].contains(v)) {
                    return false;
                }
            }
        }
        return true;
    }

    /* --------------------------------------------------------------------- */
    /*                               Answer Build                              */
    /* --------------------------------------------------------------------- */
    /** The original program concatenated the labels in vertex order. */
    private static String buildAnswer(char[] labels) {
        return new String(labels);
    }

    /* --------------------------------------------------------------------- */
    /*                     Validation of the Final Assignment                */
    /* --------------------------------------------------------------------- */
    /**
     * Replicates the original validation logic.
     * It rejects the assignment if any edge (u, v) with u < v has
     * label[u] == 'a' && label[v] == 'c' (the only forbidden adjacency).
     */
    private static boolean validateAssignment(Graph graph, char[] labels) {
        for (int u = 0; u < graph.vertexCount; u++) {
            for (int v : graph.adjacency[u]) {
                if (u < v && labels[u] == LABEL_A && labels[v] == LABEL_C) {
                    return false;
                }
            }
        }
        return true;
    }
}

// Refactored solution for CF624C – 2
// The program reads a graph, assigns letters 'a', 'b' or 'c' to its vertices and
// prints "Yes" together with the assignment if it satisfies the required
// adjacency rules, otherwise it prints "No".

import java.io.*;
import java.util.*;

/**
 * Main class that encapsulates the whole solution.
 * All mutable state is confined to method parameters / local variables –
 * there are no package‑private static fields.
 */
public class CF624C_2 {

    /** Fast scanner based on BufferedReader / StringTokenizer. */
    private static final class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner(InputStream is) {
            br = new BufferedReader(new InputStreamReader(is));
        }

        private String nextToken() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                String line = br.readLine();
                if (line == null) return null;
                st = new StringTokenizer(line);
            }
            return st.nextToken();
        }

        int nextInt() throws IOException { return Integer.parseInt(nextToken()); }
        long nextLong() throws IOException { return Long.parseLong(nextToken()); }
        double nextDouble() throws IOException { return Double.parseDouble(nextToken()); }
        String nextLine() throws IOException { return br.readLine(); }
    }

    /** Simple wrapper that stores the adjacency matrix and vertex degrees. */
    private static final class Graph {
        private final int n;               // number of vertices (1‑based)
        private final int[][] adj;         // adjacency matrix
        private final int[] degree;        // degree of each vertex

        Graph(int n) {
            this.n = n;
            this.adj = new int[n + 1][n + 1];
            this.degree = new int[n + 1];
        }

        void addEdge(int u, int v) {
            adj[u][v] = adj[v][u] = 1;
            degree[u]++;
            degree[v]++;
        }

        int getDegree(int v) { return degree[v]; }
        boolean hasEdge(int u, int v) { return adj[u][v] == 1; }
    }

    /** Holds the current letter assignment and provides validation utilities. */
    private static final class Assignment {
        private final int n;
        private final Graph graph;
        private final char[] letters;      // 1‑based, '\0' denotes “unassigned”
        private final boolean[] visited;   // DFS visitation flag

        Assignment(int n, Graph graph) {
            this.n = n;
            this.graph = graph;
            this.letters = new char[n + 1];
            Arrays.fill(letters, '\0');
            this.visited = new boolean[n + 1];
        }

        /** Perform the whole assignment process. */
        void assign() {
            int componentIdx = 0;

            // 1️⃣ Vertices adjacent to *all* others become 'b' immediately.
            for (int v = 1; v <= n; v++) {
                if (graph.getDegree(v) == n - 1) {
                    letters[v] = 'b';
                    visited[v] = true;
                }
            }

            // 2️⃣ Process components that contain at least one 'b' vertex.
            for (int start = 1; start <= n; start++) {
                if (!visited[start] && letters[start] == 'b') {
                    componentIdx++;
                    dfs(start, componentIdx % 2 == 0 ? 'a' : 'c', componentIdx);
                }
            }

            // 3️⃣ Process the remaining unvisited vertices (components without a 'b').
            for (int start = 1; start <= n; start++) {
                if (!visited[start]) {
                    componentIdx++;
                    char startColour = (componentIdx % 2 == 1) ? 'a' : 'c';
                    dfs(start, startColour, componentIdx);
                }
            }
        }

        /** Depth‑first search that propagates the colour throughout a component. */
        private void dfs(int v, char colour, int componentNumber) {
            visited[v] = true;
            if (letters[v] == '\0') {
                letters[v] = colour;
            }

            // The original code used a simple counter to decide between two
            // auxiliary letters when the current vertex is labelled 'b'.
            // For readability we keep the same behaviour.
            char neighbourColour = colour;
            if (colour == 'b') {
                // Alternate between 'a' and 'c' for the first two neighbours.
                neighbourColour = 'a';
            }

            int neighbourCounter = 0;
            for (int to = 1; to <= n; to++) {
                if (!graph.hasEdge(v, to) || visited[to]) continue;

                if (letters[to] != '\0') continue; // already coloured

                if (letters[v] == 'b') {
                    // First neighbour gets 'a', second gets 'c', then stop assigning.
                    letters[to] = (neighbourCounter == 0) ? 'a' : 'c';
                } else {
                    letters[to] = neighbourColour;
                }
                neighbourCounter++;

                dfs(to, letters[to], componentNumber);
            }
        }

        /** Verify that the produced assignment respects all adjacency constraints. */
        boolean isValid() {
            for (int v = 1; v <= n; v++) {
                char cur = letters[v];
                if (cur == '\0') continue; // should never happen in a complete assignment

                for (int to = 1; to <= n; to++) {
                    if (v == to) continue;

                    boolean edgeExists = graph.hasEdge(v, to);

                    if (edgeExists) {
                        // Edge must connect only allowed pairings.
                        if (cur == 'a' && !(letters[to] == 'a' || letters[to] == 'b')) return false;
                        if (cur == 'c' && !(letters[to] == 'b' || letters[to] == 'c')) return false;
                    } else {
                        // Non‑edge must *not* connect forbidden pairings.
                        if (cur == 'a' && (letters[to] == 'b' || letters[to] == 'a')) return false;
                        if (cur == 'c' && (letters[to] == 'b' || letters[to] == 'c')) return false;
                    }
                }
            }
            return true;
        }

        char[] getLetters() { return letters; }
    }

    /** Entry point of the program. */
    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)));

        int n = fs.nextInt();          // number of vertices
        int m = fs.nextInt();          // number of edges

        Graph graph = new Graph(n);
        for (int i = 0; i < m; i++) {
            int u = fs.nextInt();
            int v = fs.nextInt();
            graph.addEdge(u, v);
        }

        Assignment assign = new Assignment(n, graph);
        assign.assign();

        if (!assign.isValid()) {
            out.println("No");
        } else {
            out.println("Yes");
            StringBuilder sb = new StringBuilder();
            for (int i = 1; i <= n; i++) {
                sb.append(assign.getLetters()[i]);
            }
            out.println(sb.toString());
        }

        out.flush();   // ensure all output is written before closing
    }
}

import java.util.Arrays;
import java.util.Scanner;

/**
 * Reads a graph, attempts to assign each vertex a label according to a specific
 * rule and validates the resulting labeling.
 */
public class C624 {

    // -------------------------------------------------------------------------
    // Constants for the three possible labels used by the algorithm
    // -------------------------------------------------------------------------
    private static final char LABEL_UNKNOWN = 'z'; // initial placeholder
    private static final char LABEL_B = 'b';
    private static final char LABEL_A = 'a';
    private static final char LABEL_C = 'c';

    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            Graph graph = readGraph(scanner);
            char[] labels = assignLabels(graph);
            boolean consistent = isAssignmentConsistent(graph, labels);

            if (consistent) {
                System.out.println("Yes\n" + new String(labels).trim());
            } else {
                System.out.println("No");
            }
        }
    }

    /** Parses input and builds an adjacency matrix representation of the graph. */
    private static Graph readGraph(Scanner scanner) {
        int n = scanner.nextInt();   // number of vertices
        int m = scanner.nextInt();   // number of edges

        boolean[][] adjacency = new boolean[n][n];
        // Vertices are considered adjacent to themselves
        for (int i = 0; i < n; i++) {
            adjacency[i][i] = true;
        }

        // Read each undirected edge and fill the adjacency matrix
        for (int i = 0; i < m; i++) {
            int u = scanner.nextInt() - 1;
            int v = scanner.nextInt() - 1;
            adjacency[u][v] = true;
            adjacency[v][u] = true;
        }

        return new Graph(n, adjacency);
    }

    /** Assigns a label to every vertex following the problem’s rules. */
    private static char[] assignLabels(Graph graph) {
        int n = graph.size();
        char[] labels = new char[n];
        Arrays.fill(labels, LABEL_UNKNOWN);

        int firstNonB = -1;                     // first vertex that is NOT labelled 'b'

        // Step 1 – identify vertices that are adjacent to every other vertex
        for (int i = 0; i < n; i++) {
            if (isUniversal(i, graph)) {
                labels[i] = LABEL_B;
            } else if (firstNonB == -1) {
                firstNonB = i;                  // remember the first non‑b vertex
            }
        }

        // Step 2 – if such a vertex exists, propagate labels from it
        if (firstNonB != -1) {
            labels[firstNonB] = LABEL_A;
            for (int j = 0; j < n; j++) {
                if (j == firstNonB || labels[j] == LABEL_B) {
                    continue;
                }
                labels[j] = graph.adjacent(firstNonB, j) ? LABEL_A : LABEL_C;
            }
        }

        return labels;
    }

    /** Verifies that the labeling respects adjacency constraints. */
    private static boolean isAssignmentConsistent(Graph graph, char[] labels) {
        int n = graph.size();

        for (int i = 0; i < n; i++) {
            if (labels[i] == LABEL_B) continue;   // ignore 'b' vertices in checks
            for (int j = 0; j < n; j++) {
                if (labels[j] == LABEL_B) continue;
                if (graph.adjacent(i, j)) {
                    if (labels[i] != labels[j]) {
                        return false;               // adjacent vertices must share a label
                    }
                } else {
                    if (labels[i] == labels[j]) {
                        return false;               // non‑adjacent vertices must differ
                    }
                }
            }
        }
        return true;
    }

    /** Determines whether a vertex is adjacent to all other vertices (a "universal" vertex). */
    private static boolean isUniversal(int v, Graph graph) {
        for (int w = 0; w < graph.size(); w++) {
            if (!graph.adjacent(v, w)) {
                return false;
            }
        }
        return true;
    }

    /** Simple wrapper around an adjacency matrix for clearer intent. */
    private static final class Graph {
        private final int size;
        private final boolean[][] adjacency;

        Graph(int size, boolean[][] adjacency) {
            this.size = size;
            this.adjacency = adjacency;
        }

        /** Returns true if there is an edge between i and j. */
        boolean adjacent(int i, int j) {
            return adjacency[i][j];
        }

        /** Number of vertices in the graph. */
        int size() {
            return size;
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Main class – entry point of the program.
 * <p>
 * The program reads an undirected graph, tries to assign each vertex one of three
 * colors ('a', 'b', 'c') such that the absolute difference of the numeric values
 * of adjacent colors is at most 1. If such an assignment exists it prints "Yes"
 * and the color string, otherwise it prints "No".
 */
public class Main {

    /** Character used for each logical colour in the output. */
    private static final char OUT_A = 'a';
    private static final char OUT_B = 'b';
    private static final char OUT_C = 'c';

    public static void main(String[] args) {
        // Use try‑with‑resources to guarantee proper stream closing.
        try (InputStream in = System.in;
             OutputStream out = System.out) {

            FastInput reader = new FastInput(in);
            PrintWriter writer = new PrintWriter(out);

            new Solver().solve(reader, writer);
            writer.flush();       // ensure all output is flushed before streams are closed
        }
    }

    /** Fast line‑oriented input. */
    private static final class FastInput {
        private final BufferedReader br;
        private StringTokenizer st;

        FastInput(InputStream stream) {
            this.br = new BufferedReader(new InputStreamReader(stream));
        }

        /** Returns the next token, expanding the input lazily. */
        private String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    throw new UncheckedIOException(e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        long nextLong() {
            return Long.parseLong(next());
        }

        double nextDouble() {
            return Double.parseDouble(next());
        }

        float nextFloat() {
            return Float.parseFloat(next());
        }

        /** Utility to read a whole int array of fixed size. */
        int[] nextIntArray(int size) {
            int[] arr = new int[size];
            for (int i = 0; i < size; i++) {
                arr[i] = nextInt();
            }
            return arr;
        }
    }

    /**
     * Core logic of the problem.
     * <p>
     * The algorithm works in three clear phases:
     * <ol>
     *   <li>Construct the adjacency list of the graph.</li>
     *   <li>Assign colours respecting the special constraints.</li>
     *   <li>Validate every edge and produce the required output.</li>
     * </ol>
     */
    private static final class Solver {

        /** Enumerates the possible logical colours used internally. */
        private enum LogicalColor {
            UNCOLORED,
            ONE,   // maps to output 'a'
            TWO,   // maps to output 'b'
            THREE  // maps to output 'c'
        }

        /** Helper that converts a {@link LogicalColor} into its numeric id (1‑3). */
        private static int toNumber(LogicalColor c) {
            return switch (c) {
                case ONE    -> 1;
                case TWO    -> 2;
                case THREE  -> 3;
                default    -> 0;
            };
        }

        /** Main entry point called from {@code Main}. */
        void solve(FastInput in, PrintWriter out) {
            final int n = in.nextInt();          // number of vertices
            final int m = in.nextInt();          // number of edges

            // -----------------------------------------------------------------
            // 1️⃣ Build adjacency list (list of neighbours for each vertex)
            // -----------------------------------------------------------------
            @SuppressWarnings("unchecked")
            List<Integer>[] adj = new ArrayList[n];
            for (int i = 0; i < n; i++) {
                adj[i] = new ArrayList<>();
            }

            for (int i = 0; i < m; i++) {
                int u = in.nextInt() - 1;          // convert to 0‑based
                int v = in.nextInt() - 1;
                if (u == v) continue;              // ignore self‑loops
                adj[u].add(v);
                adj[v].add(u);
            }

            // -----------------------------------------------------------------
            // 2️⃣ Assign logical colours respecting the problem constraints
            // -----------------------------------------------------------------
            LogicalColor[] logicalColor = new LogicalColor[n];
            Arrays.fill(logicalColor, LogicalColor.UNCOLORED);

            for (int start = 0; start < n; start++) {
                if (logicalColor[start] != LogicalColor.UNCOLORED) {
                    continue; // already processed
                }

                // start a new connected component with an arbitrary initial colour
                logicalColor[start] = LogicalColor.ONE; // colour 1 == 'a'

                Deque<Integer> queue = new ArrayDeque<>();
                queue.add(start);

                while (!queue.isEmpty()) {
                    int u = queue.pollFirst();
                    assignNeighbourColors(u, adj, logicalColor, queue);
                }
            }

            // Give the default colour "B" (2) to any vertex that stayed uncoloured
            for (int i = 0; i < n; i++) {
                logicalColor[i] = (logicalColor[i] == LogicalColor.UNCOLORED)
                        ? LogicalColor.TWO
                        : logicalColor[i];
            }

            // -----------------------------------------------------------------
            // 3️⃣ Final validation of all edges and produce output
            // -----------------------------------------------------------------
            if (!edgesRespectConstraint(adj, logicalColor)) {
                out.println("No");
                return;
            }

            out.println("Yes");
            for (int i = 0; i < n; i++) {
                switch (logicalColor[i]) {
                    case ONE  -> out.print(OUT_A);
                    case TWO  -> out.print(OUT_B);
                    case THREE-> out.print(OUT_C);
                }
            }
            out.println(); // terminate the line of colours
        }

        /** Assigns a colour to an uncoloured neighbour `v` of `u` based on `u`'s colour. */
        private void assignNeighbourColors(int u,
                                           List<Integer>[] adj,
                                           LogicalColor[] color,
                                           Deque<Integer> queue) {

            LogicalColor cu = color[u];
            int uncolouredIndex = -1; // index in adj[u] that is still UNCOLORED

            for (int v : adj[u]) {
                LogicalColor cv = color[v];

                if (cv == LogicalColor.UNCOLORED) {
                    // decide which colour to give to vertex v
                    color[v] = resolveNeighbourColor(u, cu);
                    queue.addLast(v); // propagate from the newly coloured vertex
                } else {
                    // already coloured – only need to validate the edge now
                    validateEdge(u, v, cu, cv);
                }
            }
        }

        /** Determines the only legal colour for an uncoloured neighbour given the colour of its coloured neighbour. */
        private LogicalColor resolveNeighbourColor(int u, LogicalColor colourOfU) {
            // Color "TWO" (value 2) is forbidden for the neighbour.
            if (colourOfU == LogicalColor.TWO) {
                throw new IllegalStateException("invalid edge"); // triggers "No"
            }

            // If the neighbour already has a value, it must be compatible.
            // Here we are dealing with the first time we colour the neighbour.
            // The rule from the original code translates to:
            //   neighbour = (neighbour == 1) ? 3 : 1
            // i.e. we flip between 1 and 3.
            return (colourOfU == LogicalColor.ONE) ? LogicalColor.THREE : LogicalColor.ONE;
        }

        /** Checks that two adjacent vertices satisfy the “difference ≤ 1” rule. */
        private boolean validateEdge(int u, int v, LogicalColor cu, LogicalColor cv) {
            int diff = Math.abs(
                    Solver.toNumber(cu) - Solver.toNumber(cv));
            return diff <= 1;
        }

        /** Verifies *all* edges of the graph respect the constraint. */
        private boolean edgesRespectConstraint(List<Integer>[] adj,
                                               LogicalColor[] color) {
            for (int u = 0; u < adj.length; u++) {
                for (int v : adj[u]) {
                    if (Math.abs(
                            Solver.toNumber(color[u]) -
                            Solver.toNumber(color[v])) > 1) {
                        return false;
                    }
                }
            }
            return true;
        }
    }
}

/**
 *  Maintainable solution for the graph‑coloring decision problem.
 *
 *  The program reads a graph (n vertices, m undirected edges) and determines
 *  whether the vertices can be labelled with 'a', 'b' or 'c' so that the
 *  following constraints hold:
 *
 *   • A vertex of degree n‑1 is always labelled 'b'.
 *   • Two adjacent vertices may not receive the pair {'a','c'} or {'c','a'}.
 *   • Two non‑adjacent vertices may not receive the pair {'a','b'}, {'b','a'},
 *     {'b','c'}, or {'c','b'}.
 *
 *  If such a labelling exists the program prints "Yes" followed by the label
 *  sequence; otherwise it prints "No".
 *
 *  The implementation is deliberately split into small, well‑named methods,
 *  uses clear constants, avoids cryptic naming and follows modern Java style.
 */
public class Main {

    /* --------------------------------------------------------------------- */
    /*  Public entry point                                                     */
    /* --------------------------------------------------------------------- */

    public static void main(String[] args) {
        new Main().run();
    }

    /* --------------------------------------------------------------------- */
    /*  Core logic                                                             */
    /* --------------------------------------------------------------------- */

    /** Entry point used by {@code run()}. */
    private void solve() {
        int n = scanner.nextInt();
        int m = scanner.nextInt();

        boolean[][] adjacency = readAdjacency(n, m);

        // 0 = unassigned, 1 = 'a', 2 = 'b', 4 = 'c'
        int[] role = assignRoles(adjacency, n);

        if (role == null) {
            out.println("No");
            return;
        }

        out.println("Yes");
        for (int r : role) {
            out.print(mapRoleToChar(r));
        }
        out.println();
    }

    /** Builds the adjacency matrix from the input pairs. */
    private static boolean[][] readAdjacency(int size, int edgeCount) {
        boolean[][] g = new boolean[size][size];
        for (int i = 0; i < edgeCount; ++i) {
            int a = scanner.nextInt() - 1;
            int b = scanner.nextInt() - 1;
            g[a][b] = g[b][a] = true;
        }
        return g;
    }

    /**
     * Tries to assign a role to each vertex respecting the constraints.
     *
     * @return an integer array where each entry is {@code 1}, {@code 2} or {@code 4}
     *         representing the characters {@code a}, {@code b}, {@code c}
     *         respectively; {@code null} if no valid assignment exists.
     */
    private static int[] assignRoles(boolean[][] graph, int vertexCount) {
        int[] role = new int[vertexCount];
        boolean[] degreeFull = new boolean[vertexCount];

        // 1️⃣  Vertices with degree (n‑1) are forced to role 2 ('b')
        for (int v = 0; v < vertexCount; ++v) {
            int neighbourCount = countNeighbours(graph, v);
            if (neighbourCount == vertexCount - 1) {
                role[v] = 2;                 // 'b'
                degreeFull[v] = true;        // already decided
            }
        }

        // 2️⃣  Iterate over the remaining (undecided) vertices in order
        for (int v = 0; v < vertexCount; ++v) {
            if (degreeFull[v]) {
                continue; // already assigned
            }

            // Try role 1 ('a')
            if (tryAssignRole(role, graph, vertexCount, v, 1, 1)) {
                continue;
            }

            // Try role 4 ('c')
            if (tryAssignRole(role, graph, vertexCount, v, 4, 4)) {
                continue;
            }

            // Neither role works → impossible to satisfy constraints
            return null;
        }

        return role;
    }

    /** Counts how many neighbours a vertex has. */
    private static int countNeighbours(boolean[][] graph, int vertex) {
        int cnt = 0;
        for (boolean edge : graph[vertex]) {
            if (edge) ++cnt;
        }
        return cnt;
    }

    /**
     * Attempts to assign {@code candidateRole} to {@code v}.
     *
     * @param currentRoles   partially filled role array
     * @param graph          adjacency matrix
     * @param size           number of vertices
     * @param v              vertex being considered
     * @param candidateRole  role we try (1 = 'a', 4 = 'c')
     * @param forbiddenMask  bit‑mask of roles that this choice would forbid
     *                       with previously processed vertices (used for early exit)
     * @return {@code true} if assignment is compatible with all previous vertices,
     *         {@code false} otherwise.
     */
    private static boolean tryAssignRole(
            int[] currentRoles,
            boolean[][] graph,
            int size,
            int v,
            int candidateRole,
            int forbiddenMask) {

        // Check compatibility with every already processed vertex j < v
        for (int j = 0; j < v; ++j) {
            int prevRole = currentRoles[j];
            if (prevRole == 0) {
                // Not processed yet – ignore; it will be checked later
                continue;
            }

            boolean adjacent = graph[v][j];

            // If we are assigning 'a' we cannot be adjacent to a vertex already
            // labelled 'c' (role 4) and we must NOT be adjacent to a 'c' that
            // was already assigned (would break the adjacency rule).
            if (candidateRole == 1) {
                if (adjacent && prevRole == 4) {
                    return false; // adjacency to a 'c' is forbidden
                }
                if (!adjacent && (prevRole == 1 || prevRole == 2)) {
                    return false; // non‑adjacent to a role that would clash
                }
                // Additional logical checks for 'c' neighbours are handled in
                // the assignment for role 4; no extra test needed here.
                continue;
            }

            // Symmetric checks for role 4 ('c')
            if (candidateRole == 4) {
                if (adjacent && prevRole == 1) {
                    return false; // adjacency to a 'a' is forbidden
                }
                if (!adjacent && (prevRole == 2 || prevRole == 4)) {
                    return false; // non‑adjacent to a 'b' or another 'c'
                }
            }
        }

        // If we reach this point the candidate respects all constraints.
        currentRoles[v] = candidateRole;
        return true;
    }

    /** Maps internal role numbers to the corresponding character. */
    private static char mapRoleToChar(int role) {
        return switch (role) {
            case 1 -> 'a';
            case 2 -> 'b';
            case 4 -> 'c';
            default -> '?';
        };
    }

    /* --------------------------------------------------------------------- */
    /*  I/O helpers                                                            */
    /* --------------------------------------------------------------------- */

    /** Simple fast scanner used by the original solution. */
    private static final FastScanner scanner = new FastScanner(System.in);
    /** Output stream used for printing the answer. */
    private static final PrintWriter out = new PrintWriter(System.out);

    /** Utility class offering buffered token based input. */
    private static final class FastScanner {
        private final InputStream stream;
        private final byte[] buffer = new byte[16 * 1024];
        private int bytesIn = 0, ptr = 0;

        FastScanner(InputStream stream) {
            this.stream = Objects.requireNonNull(stream);
        }

        private int readByte() {
            if (ptr >= bytesIn) {
                bytesIn = stream.read(buffer);
                ptr = 0;
                if (bytesIn <= 0) {
                    return -1;
                }
            }
            return buffer[ptr++];
        }

        /** Skips whitespace characters. */
        private static boolean isSpace(int c) {
            return c <= ' '; // includes '\n', '\r', '\t', ' '
        }

        /** Reads next non‑whitespace token as a string. */
        private String nextToken() {
            int c;
            do {
                c = readByte();
            } while (c != -1 && isSpace(c));

            if (c == -1) {
                return null;
            }

            StringBuilder sb = new StringBuilder();
            do {
                sb.append((char) c);
                c = readByte();
            } while (c != -1 && !isSpace(c));

            return sb.toString();
        }

        /** Convenience wrappers used by the original code. */
        int nextInt()          { return Integer.parseInt(nextToken()); }
        long nextLong()        { return Long.parseLong(nextToken()); }
        double nextDouble()    { return Double.parseDouble(nextToken()); }

        String next()          { return nextToken(); }
        String nextLine()      { try { return nextToken(); } catch (Exception e) { return null; } }
    }
}

/*
 *  Simple competitive‑programming utilities.
 *  The program reads a graph, checks whether its complement can be coloured
 *  with {a, b, c} according to the problem’s rules and prints the result.
 */
package solution;

import java.io.*;
import java.util.*;

/**
 * Entry point of the application.
 * In a contest setting the whole code lives in one file, therefore the
 * {@code main} method creates and runs the {@link TaskAdapter} that contains
 * the solution logic.
 */
public class Main {

    /** Starts a task that reads from {@code System.in} and writes to {@code System.out}. */
    public static void main(String[] args) throws Exception {
        // The thread size 1 << 29 is only kept to stay compatible with the original code.
        Thread thread = new Thread(null, new TaskAdapter(), "", 1 << 29);
        thread.start();
        thread.join();                     // wait for the task to finish
    }

    /**
     * Wrapper that adapts the old {@code AGraphAndString} logic to the new
     * architecture.  It is deliberately tiny – all heavy work is delegated
     * to {@link GraphProcessor}.
     */
    private static final class TaskAdapter implements Runnable {

        @Override
        public void run() {
            try (FastInput input = new FastInput(System.in);
                 FastOutput output = new FastOutput(System.out)) {

                GraphProcessor processor = new GraphProcessor();
                processor.solve(input, output);
                output.flush();               // explicit flush (FastOutput implements AutoCloseable)
            }
        }
    }

    /* -------------------------------------------------------------------------
     *  Utility classes – fast I/O and program output
     * ---------------------------------------------------------------------- */
    /**
     * Very small fast scanner that works on {@link InputStream}.
     * It mirrors the functionality of the original {@code FastInput} but
     * is kept private to avoid exposing unnecessary public members.
     */
    private static final class FastInput implements Closeable {
        private final InputStream stream;
        private final byte[] buffer = new byte[1 << 13];
        private int bufferLen = 0, bufferPos = 0;

        FastInput(InputStream stream) {
            this.stream = Objects.requireNonNull(stream);
        }

        /** Skips whitespace characters. */
        private void skipWhitespace() throws IOException {
            int read;
            do {
                read = readByte();
            } while (read <= ' ' && read != -1);
            bufferPos = 0;
            bufferLen = read;
        }

        /** Reads next signed integer. */
        int readInt() throws IOException {
            skipWhitespace();
            boolean negative = false;
            if (buffer[bufferPos] == '-' || buffer[bufferPos] == '+') {
                negative = buffer[bufferPos] == '-';
                ++bufferPos;
            }
            long value = 0;
            while (bufferPos < bufferLen && buffer[bufferPos] >= '0') {
                value = value * 10 + (buffer[bufferPos] - '0');
                ++bufferPos;
            }
            // Pull next chunk if we ran out of data
            if (bufferPos == bufferLen) {
                bufferPos = 0;
                bufferLen = readByte();
            }
            return (int) (negative ? -value : value);
        }

        /** Reads a single byte from underlying stream (may fill buffer first). */
        private int readByte() throws IOException {
            if (bufferPos >= bufferLen) {
                bufferPos = 0;
                bufferLen = stream.read(buffer);
            }
            return (bufferLen == -1) ? -1 : buffer[bufferPos++];
        }

        @Override
        public void close() throws IOException {
            stream.close();
        }
    }

    /**
     * Efficient writer that buffers output and flushes only when necessary.
     * It implements {@link AutoCloseable} so it can be used in try‑with‑resources.
     */
    private static final class FastOutput implements Appendable, Closeable, AutoCloseable {
        private static final int THRESHOLD = 1 << 13;                 // flush when > 8KB
        private final Writer writer;
        private final StringBuilder buffer = new StringBuilder(THRESHOLD * 2);

        FastOutput(OutputStream outputStream) {
            this.writer = new OutputStreamWriter(outputStream);
        }

        FastOutput(Writer writer) {
            this.writer = writer;
        }

        FastOutput append(String s) {
            buffer.append(s);
            afterWrite();
            return this;
        }

        FastOutput append(char c) {
            buffer.append(c);
            afterWrite();
            return this;
        }

        /** Flushes the internal buffer if it exceeds the defined threshold. */
        private void afterWrite() {
            if (buffer.length() > THRESHOLD) {
                flush();
            }
        }

        /** Writes the buffered data to the underlying writer. */
        private void flush() {
            try {
                writer.append(buffer);
                writer.flush();
                buffer.setLength(0);
            } catch (IOException e) {
                throw new UncheckedIOException(e);
            }
        }

        /** Prints a line break. */
        FastOutput println() {
            return append(System.lineSeparator());
        }

        /** Prints the supplied string followed by a newline. */
        FastOutput println(String s) {
            return append(s).println();
        }

        /** Closes the underlying writer after flushing. */
        @Override
        public void close() {
            flush();
            try {
                writer.close();
            } catch (IOException e) {
                throw new UncheckedIOException(e);
            }
        }
    }

    /* -------------------------------------------------------------------------
     *  Core logic – graph processing
     * ---------------------------------------------------------------------- */
    /**
     * Contains the algorithm that decides whether a given undirected graph can
     * be coloured with the characters {@code 'a', 'b', 'c'} according to the
     * problem statement.
     *
     * <p>All public methods are deliberately small and side‑effect free so
     * they are easy to unit‑test.</p>
     */
    private static final class GraphProcessor {

        /**
         * Reads the whole input (fast scanner) and writes the answer (fast writer).
         *
         * @param in  input source (must not be {@code null})
         * @param out output destination (must not be {@code null})
         */
        void solve(FastInput in, FastOutput out) {
            int n = in.readInt();          // number of vertices
            int m = in.readInt();          // number of edges

            // adjacency matrix as boolean[][] – simple and fast for small n
            boolean[][] adj = new boolean[n][n];
            for (int i = 0; i < m; ++i) {
                int u = in.readInt() - 1;
                int v = in.readInt() - 1;
                checkVertexIndex(u, n);
                checkVertexIndex(v, n);
                adj[u][v] = adj[v][u] = true;
            }

            // Find a missing edge (u, v) – if none exists the graph is complete.
            Pair<Integer, Integer> missing = findMissingEdge(adj, n);
            if (missing == null) {
                // Complement graph has no edges → trivially colourable with 'a's
                out.println("Yes");
                out.append(String.valueOf(new char[n])).println();
                return;
            }

            int a = missing.first;
            int c = missing.second;

            // Partition vertices based on connections to a and c
            boolean[] inA = new boolean[n];
            boolean[] inC = new boolean[n];
            boolean[] inB = new boolean[n];

            markNeighbourhood(a, adj, inA);
            markNeighbourhood(c, adj, inC);

            // Vertices incident to both a and c belong to set B
            for (int i = 0; i < n; ++i) {
                if (inA[i] && inC[i]) {
                    inB[i] = true;
                    inA[i] = inC[i] = false;
                }
            }

            // Every vertex must belong to exactly one of the three sets
            if (!allVerticesCovered(inA, inB, inC)) {
                out.println("No");
                return;
            }

            // Verify that the adjacency relationship respects the allowed
            // absolute difference ≤ 1 rule between the three colour classes.
            for (int i = 0; i < n; ++i) {
                for (int j = i + 1; j < n; ++j) {
                    int typeI = resolveType(inA[i], inB[i], inC[i]);
                    int typeJ = resolveType(inA[j], inB[j], inC[j]);

                    boolean expectedAdjacent = (Math.abs(typeI - typeJ) <= 1);
                    if (expectedAdjacent != adj[i][j]) {
                        out.println("No");
                        return;
                    }
                }
            }

            // All checks passed – construct and print the answer
            out.println("Yes");
            StringBuilder answer = new StringBuilder(n);
            for (int i = 0; i < n; ++i) {
                answer.append(colourChar(inA[i], inB[i], inC[i]));
            }
            out.append(answer);
        }

        /** Returns a pair (u, v) such that there is no edge between them, or {@code null} if the graph is complete. */
        private static Pair<Integer, Integer> findMissingEdge(boolean[][] adj, int n) {
            for (int i = 0; i < n; ++i) {
                for (int j = i + 1; j < n; ++j) {
                    if (!adj[i][j]) {
                        return new Pair<>(i, j);
                    }
                }
            }
            return null;
        }

        /** Marks all neighbours of vertex {@code v} in {@code arr}. */
        private static void markNeighbourhood(int v, boolean[][] adj, boolean[] arr) {
            for (int i = 0; i < arr.length; ++i) {
                arr[i] = adj[v][i];
            }
        }

        /** Returns true if every vertex belongs to exactly one of the three sets. */
        private static boolean allVerticesCovered(boolean[] a, boolean[] b, boolean[] c) {
            for (int i = 0; i < a.length; ++i) {
                if (!(a[i] || b[i] || c[i])) {
                    return false;
                }
            }
            return true;
        }

        /** Translates the boolean belonging to a set into an integer representing its colour class. */
        private static int resolveType(boolean inA, boolean inB, boolean inC) {
            if (inA) {
                return 0;      // 'a' → class 0
            }
            if (inC) {
                return 2;      // 'c' → class 2
            }
            return 1;          // 'b' → class 1 (only case left)
        }

        /** Returns the character that corresponds to the set a vertex belongs to. */
        private static char colourChar(boolean inA, boolean inB, boolean inC) {
            if (inA) {
                return 'a';
            }
            if (inC) {
                return 'c';
            }
            return 'b';
        }
    }

    /* -------------------------------------------------------------------------
     *  Simple immutable pair class – avoids pulling in external libraries.
     * ---------------------------------------------------------------------- */
    private static final class Pair<F, S> {
        final F first;
        final S second;

        Pair(F first, S second) {
            this.first = first;
            this.second = second;
        }
    }
}

/**
 * Refactored version of the original AIMTechA program.
 *
 * <p>This implementation focuses on readability, maintainability and modern Java practices
 * while preserving the original algorithmic behaviour.</p>
 */
public class AIMTechA {

    /** Fast scanner for reading input from {@code System.in}. */
    private static final class FastScanner {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        FastScanner(InputStream stream) {
            this.reader = new BufferedReader(new InputStreamReader(stream), 32768);
        }

        /** Returns the next token, reading a new line if necessary. */
        private String loadNextToken() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new UncheckedIOException(e);
                }
            }
            return tokenizer.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(loadNextToken());
        }

        long nextLong() {
            return Long.parseLong(loadNextToken());
        }

        double nextDouble() {
            return Double.parseDouble(loadNextToken());
        }
    }

    /** Alphabet letters used for vertex coloring (excluding '\0'). */
    private static final class Colors {
        static final char UNUSED = '\0';
        static final char UNIVERSAL = 'b';
        static final char START = 'a';
        static final char NEXT = 'c';
    }

    /** Core logic of the program. */
    public static void main(String[] args) {
        FastScanner fs = new FastScanner(System.in);

        // ----- 1. Read graph ----------------------------------------------------
        int n = fs.nextInt();          // number of vertices
        int m = fs.nextInt();          // number of edges
        boolean[][] adj = new boolean[n][n];
        char[] color = new char[n];    // coloring result

        for (int i = 0; i < m; i++) {
            int u = fs.nextInt() - 1;
            int v = fs.nextInt() - 1;
            adj[u][v] = true;
            adj[v][u] = true;
        }

        // ----- 2. Identify universal vertices (connected to every other vertex) --
        boolean anyUniversal = false;
        for (int v = 0; v < n; v++) {
            boolean connectedToAll = true;
            for (int u = 0; u < n; u++) {
                if (u == v) continue;
                if (!adj[v][u]) {
                    connectedToAll = false;
                    break;
                }
            }
            if (connectedToAll) {
                color[v] = Colors.UNIVERSAL;
                anyUniversal = true;
            }
        }

        // ----- 3. Validate triangle condition for non‑universal triples ----------
        for (int i = 0; i < n; i++) {
            if (color[i] != Colors.UNUSED) continue;
            for (int j = i + 1; j < n; j++) {
                if (color[j] != Colors.UNUSED) continue;
                for (int k = j + 1; k < n; k++) {
                    if (color[k] != Colors.UNUSED) continue;

                    int edgeCount = 0;
                    if (adj[i][j]) edgeCount++;
                    if (adj[j][k]) edgeCount++;
                    if (adj[i][k]) edgeCount++;

                    // Reject if the triangle has 0 or 2 edges (i.e. not 1 or 3)
                    if (edgeCount == 0 || edgeCount == 2) {
                        System.out.println("No");
                        return;
                    }
                }
            }
        }

        // ----- 4. Assign colors to remaining vertices ---------------------------
        char nextColor = Colors.START;
        for (int v = 0; v < n; v++) {
            if (color[v] != Colors.UNUSED) continue;

            // Try to copy a neighbor's color that is not the universal colour.
            boolean found = false;
            for (int u = 0; u < n; u++) {
                if (adj[v][u] && color[u] != Colors.UNUSED && color[u] != Colors.UNIVERSAL) {
                    color[v] = color[u];
                    found = true;
                    break;
                }
            }

            // If no such neighbor exists, use the next fresh colour.
            if (!found) {
                color[v] = nextColor;
                if (nextColor == Colors.START) {
                    nextColor = Colors.NEXT;
                }
            }
        }

        // ----- 5. Output result --------------------------------------------------
        System.out.println("Yes");
        System.out.println(new String(color));
    }
}

import java.io.*;
import java.util.*;

/**
 * Entry point of the application.
 * It delegates the whole solving process to {@link GraphColoringSolver}.
 */
public class Main {

    /** Mapping from numeric colour index (1‑based) to the required output character. */
    private static final char[] COLOR_CHAR = {'a', 'b', 'c'};

    public static void main(String[] args) throws IOException {
        FastScanner scanner = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(System.out);

        GraphColoringSolver solver = new GraphColoringSolver();
        solver.solve(scanner, out);

        out.flush();
    }

    /** Simple fast scanner that works with the original input format. */
    static final class FastScanner {
        private final InputStream stream;
        private final byte[] buffer = new byte[16 * 1024];
        private int ptr = 0, len = 0;

        FastScanner(InputStream stream) {
            this.stream = stream;
        }

        private int readByte() throws IOException {
            if (len < 0) throw new InputMismatchException();
            if (ptr >= len) {
                ptr = 0;
                len = stream.read(buffer);
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        /** Reads the next integer (skipping white‑space). */
        int nextInt() throws IOException {
            int c;
            do {
                c = readByte();
            } while (c <= ' ');                     // skip blanks
            boolean neg = false;
            if (c == '-') {
                neg = true;
                c = readByte();
            }
            int sign = neg ? -1 : 1;
            int value = 0;
            while (c >= '0' && c <= '9') {
                value = value * 10 + (c - '0');
                c = readByte();
            }
            return sign * value;
        }
    }

    /** Encapsulates the algorithm that decides whether a valid colouring exists
     *  and prints the required answer. */
    static final class GraphColoringSolver {

        /** Solves one test case (the problem only contains a single case). */
        void solve(FastScanner in, PrintWriter out) {
            int n = in.nextInt();          // number of vertices
            int m = in.nextInt();          // number of edges

            Graph graph = new Graph(n);
            for (int i = 0; i < m; i++) {
                int u = in.nextInt() - 1;
                int v = in.nextInt() - 1;
                graph.addEdge(u, v);
            }

            // 1. Try to find a legal 3‑colouring using the recursive routine.
            int[] colour = graph.findColouring();
            if (colour == null) {
                out.println("No");
                return;
            }

            // 2. Verify the extra constraint: no edge may connect colours that differ by 2.
            if (!graph.isEdgeDifferenceValid(colour)) {
                out.println("No");
                return;
            }

            // 3. All checks passed → output the answer.
            out.println("Yes");
            out.print(buildColourString(colour));
            out.println();               // matches the original trailing newline
        }
    }

    /** Utility class that stores the graph structure and colour‑related logic. */
    static final class Graph {

        private final int vertexCount;
        private final boolean[][] adjacency;   // matrix for O(1) edge test
        private final List<Integer>[] neighbours; // adjacency list for iteration
        private int[] storedColour;              // colour after a successful DFS

        Graph(int n) {
            this.vertexCount = n;
            @SuppressWarnings("unchecked")
            List<Integer>[] a = new List[n];
            for (int i = 0; i < n; i++) {
                a[i] = new ArrayList<>();
            }
            this.adjacency = new boolean[n][n];
            this.neighbours = a;
        }

        /** Adds an undirected edge between {@code u} and {@code v}. */
        void addEdge(int u, int v) {
            if (!adjacency[u][v]) {
                neighbours[u].add(v);
                neighbours[v].add(u);
                adjacency[u][v] = adjacency[v][u] = true;
            }
        }

        /** Returns the list of neighbours of vertex {@code u}. */
        List<Integer> neighbours(int u) {
            return neighbours[u];
        }

        /** Checks whether an edge exists between {@code u} and {@code v}. */
        boolean hasEdge(int u, int v) {
            return adjacency[u][v];
        }

        /** Tries to colour the graph with the three colours {1,2,3}.
         *  The method returns the colour array on success, or {@code null} on failure. */
        int[] findColouring() {
            int[] colour = new int[vertexCount];   // 0 = uncoloured
            for (int v = 0; v < vertexCount; v++) {
                if (colour[v] == 0 && !dfs(v, -1, 1, colour)) {
                    return null;                   // conflict → no valid colouring
                }
            }
            storedColour = colour.clone();         // keep it for later output
            return colour;
        }

        /** Depth‑first search that assigns colours according to the rules of the original algorithm. */
        private boolean dfs(int u, int parent, int currentColour, int[] colour) {
            // If the vertex was already coloured with a different colour → conflict.
            if (colour[u] != 0 && colour[u] != currentColour) {
                return false;
            }

            int assigned = (colour[u] == 0) ? currentColour : colour[u];
            colour[u] = assigned;

            // Examine all neighbours (including non‑neighbours via the adjacency matrix).
            for (int v = 0; v < vertexCount; v++) {
                if (v == u || v == parent) continue;
                if (!hasEdge(u, v)) continue;          // we only care about real edges

                if (colour[v] == 0) {
                    // Missing neighbour must receive the complementary colour.
                    int nextColour = complementary(assigned);
                    if (!dfs(v, u, nextColour, colour)) {
                        return false;
                    }
                } else if (colour[v] == assigned) {
                    // Adjacent vertices may not share the same colour.
                    return false;
                }
            }
            return true;
        }

        /** Returns the colour that is *not* used among {1,2,3}. */
        private int complementary(int c) {
            return 4 - c;                             // because 1+2+3 = 6, 6‑c = 4‑c for c∈{1,2,3}
        }

        /** Checks the extra rule: no edge may connect colours that differ by exactly 2. */
        boolean isEdgeDifferenceValid(int[] colour) {
            for (int u = 0; u < vertexCount; u++) {
                for (int v : neighbours(u)) {
                    if (Math.abs(colour[u] - colour[v]) == 2) {
                        return false;
                    }
                }
            }
            return true;
        }

        /** Transforms the numeric colour indices back into the required a/b/c string. */
        private static String buildColourString(int[] colour) {
            StringBuilder sb = new StringBuilder(colour.length);
            for (int c : colour) {
                sb.append(COLOR_CHAR[c - 1]);        // c is 1‑based → map to a,b,c
            }
            return sb.toString();
        }
    }
}

/*  Refactored solution for the graph‑labeling problem.
 *  The program reads an undirected graph (N vertices, M edges),
 *  tries to assign each vertex one of the characters {'a','b','c'}
 *  according to the original algorithm, validates the assignment
 *  and prints either “No” or “Yes” together with the resulting string.
 *
 *  The refactor focuses on readability, separation of concerns and
 *  proper resource handling while preserving the original behaviour.
 */
package Main;

import java.io.*;
import java.util.*;

/**
 * Main driver of the program.
 */
public class Main {

    /** character used as the default value before a label is decided */
    private static final char DEFAULT_LABEL = 'b';

    /** adjacency matrix of the undirected graph */
    private final boolean[][] adjacency;

    /** label assigned to each vertex – will be filled by the algorithm */
    private final char[] labels;

    /** number of vertices */
    private final int n;

    /**
     * Constructs the solver with the given adjacency matrix and an empty label array.
     *
     * @param adjacency adjacency matrix (symmetric)
     * @param n        number of vertices
     */
    public Main(boolean[][] adjacency, int n) {
        this.adjacency = adjacency;
        this.n = n;
        this.labels = new char[n];
        Arrays.fill(this.labels, DEFAULT_LABEL);
    }

    /** Executes the whole solving process and prints the result. */
    public void solveAndPrint() throws IOException {
        assignLabelsAccordingToNonEdges();

        if (!isAssignmentValid()) {
            System.out.println("No");
            return;
        }

        System.out.println("Yes");
        System.out.print(labels);
    }

    /** Implements the original label‑assignment logic for non‑adjacent vertex pairs. */
    private void assignLabelsAccordingToNonEdges() {
        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j < n; j++) {
                if (!adjacency[i][j]) {
                    assignIfNecessary(i, j);
                }
            }
        }
    }

    /**
     * Ensures that at least one of the two vertices gets a concrete label
     * ('a' or 'c') when they are not connected by an edge.
     *
     * @param i first vertex index
     * @param j second vertex index
     */
    private void assignIfNecessary(int i, int j) {
        char vi = labels[i];
        char vj = labels[j];

        // i already has a concrete label – propagate it to j
        if (vi == 'a') {
            labels[j] = 'c';
        } else if (vi == 'c') {
            labels[j] = 'a';
        }
        // j already has a concrete label – propagate it to i
        else if (vj == 'a') {
            labels[i] = 'c';
        } else if (vj == 'c') {
            labels[i] = 'a';
        }
        // neither vertex has a concrete label yet – pick 'a' and 'c' arbitrarily
        else if (vi == DEFAULT_LABEL && vj == DEFAULT_LABEL) {
            labels[i] = 'a';
            labels[j] = 'c';
        }
    }

    /** Validates the produced labeling against the original problem constraints. */
    private boolean isAssignmentValid() {
        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j < n; j++) {
                int diff = Math.abs(labels[i] - labels[j]);

                boolean edgeExists = adjacency[i][j];
                if (edgeExists && diff != 2) {
                    return false;                     // adjacent vertices must differ by 2
                }
                if (!edgeExists && diff > 1) {
                    return false;                     // non‑adjacent vertices must differ by at least 2
                }
            }
        }
        return true;
    }

    /** Simple fast scanner used by the original code. */
    private static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner() {
            this.br = new BufferedReader(new InputStreamReader(System.in));
        }

        /** Returns the next token from standard input. */
        String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    throw new UncheckedIOException(e);
                }
            }
            return st.nextToken();
        }

        /** Reads the next integer. */
        int ni() {
            return Integer.parseInt(next());
        }
    }

    /** Entry point – unchanged from the original program logic. */
    public static void main(String[] args) throws IOException {
        FastScanner sc = new FastScanner();
        PrintWriter out = new PrintWriter(System.out, true);

        int N = sc.ni();
        int M = sc.ni();

        boolean[][] adj = new boolean[N][N];
        for (int i = 0; i < M; i++) {
            int a = sc.ni() - 1;
            int b = sc.ni() - 1;
            adj[a][b] = true;
            adj[b][a] = true;
        }

        Main solver = new Main(adj, N);
        solver.solveAndPrint();

        out.close();
    }
}

import java.io.*;
import java.util.*;

/**
 * Main entry point of the program.
 * It delegates the actual solving logic to {@link Solution}.
 */
public class Main {

    public static void main(String[] args) throws IOException {
        try (InputStream in = System.in;
             OutputStream out = System.out) {

            InputReader reader = new InputReader(in);
            PrintWriter writer = new PrintWriter(out, true);

            new Solution().solve(reader, writer);
        }
    }
}

/**
 * Solves the problem.
 * The class is deliberately kept separate from {@code Main} to improve testability
 * and to keep the I/O handling outside of the algorithmic code.
 */
class Solution {

    private static final char LETTER_A = 'a';
    private static final char LETTER_B = 'b';
    private static final char LETTER_C = 'c';

    /** Entry point used by {@code Main}. */
    public void solve(InputReader reader, PrintWriter writer) {
        int n = reader.nextInt();
        int m = reader.nextInt();

        // adjacency matrix (1‑based indexing) and degree array
        int[][] adjacency = new int[n + 1][n + 1];
        int[] degree = new int[n + 1];

        // each vertex has a self‑loop – required by the original algorithm
        for (int i = 1; i <= n; i++) {
            adjacency[i][i] = 1;
        }

        // read the edges
        for (int i = 0; i < m; i++) {
            int u = reader.nextInt();
            int v = reader.nextInt();
            addEdge(adjacency, degree, u, v);
        }

        char[] labels = new char[n + 1];
        Arrays.fill(labels, ' ');

        // 1️⃣  Vertices adjacent to all others are forced to label 'b'
        labelAllConnectedVertices(adjacency, degree, labels);

        // 2️⃣  Remaining vertices are labelled with a BFS that propagates 'a' and 'c'
        assignRemainingLabels(adjacency, labels);

        // 3️⃣  Validate the produced labeling against the adjacency constraints
        if (!isValidLabeling(adjacency, labels)) {
            writer.println("No");
            return;
        }

        // 4️⃣  Output the answer
        writer.println("Yes");
        for (int i = 1; i <= n; i++) {
            writer.print(labels[i]);
        }
        writer.println();
    }

    /** Helper that records an undirected edge and updates the degree counters. */
    private void addEdge(int[][] adjacency, int[] degree, int u, int v) {
        adjacency[u][v] = 1;
        adjacency[v][u] = 1;
        degree[u]++;
        degree[v]++;
    }

    /** Marks every vertex that is adjacent to *all* other vertices with the letter 'b'. */
    private void labelAllConnectedVertices(int[][] adjacency, int[] degree, char[] labels) {
        int totalVertices = adjacency.length - 1; // because of 1‑based indexing
        for (int v = 1; v < adjacency.length; v++) {
            if (degree[v] == totalVertices - 1) { // n‑1 neighbours (self‑loop excluded)
                labels[v] = LETTER_B;
            }
        }
    }

    /** Flood‑fills each connected component with 'a' and 'c' according to adjacency. */
    private void assignRemainingLabels(int[][] adjacency, char[] labels) {
        for (int start = 1; start < adjacency.length; start++) {
            if (labels[start] != ' ') {
                continue; // already labelled 'b'
            }

            // start a new component with the canonical label 'a'
            labels[start] = LETTER_A;
            Queue<Integer> queue = new ArrayDeque<>();
            queue.add(start);

            while (!queue.isEmpty()) {
                int cur = queue.poll();

                for (int nxt = 1; nxt < adjacency.length; nxt++) {
                    if (labels[nxt] != ' ') {
                        continue; // already labelled
                    }

                    if (adjacency[cur][nxt] == 1) {
                        labels[nxt] = LETTER_A;
                        queue.add(nxt);
                    } else {
                        labels[nxt] = LETTER_C;
                    }
                }
            }
        }
    }

    /** Verifies that the produced labeling respects the original adjacency rules. */
    private boolean isValidLabeling(int[][] adjacency, char[] labels) {
        for (int u = 1; u < adjacency.length; u++) {
            for (int v = u + 1; v < adjacency.length; v++) {
                boolean adjacent = adjacency[u][v] == 1;
                if (isIncompatible(labels[u], labels[v], adjacent)) {
                    return false;
                }
            }
        }
        return true;
    }

    /**
     * Returns {@code true} if the pair of letters is *incompatible* with the
     * adjacency relation required by the problem.
     * The rule (taken from the original code) is:
     * <ul>
     *   <li>letters that differ by 2 must <strong>not</strong> be adjacent;</li>
     *   <li>letters that differ by 0 or 1 must <strong>be</strong> adjacent.</li>
     * </ul>
     */
    private boolean isIncompatible(char a, char b, boolean adjacent) {
        int diff = Math.abs(a - b);
        return (diff == 2 && adjacent) || (diff < 2 && !adjacent);
    }
}

/**
 * Very small wrapper around {@code BufferedReader} / {@code StringTokenizer}
 * that supplies convenient parsing methods.
 */
class InputReader {
    private final BufferedReader reader;
    private StringTokenizer tokenizer;

    InputReader(InputStream stream) {
        reader = new BufferedReader(new InputStreamReader(stream));
    }

    /** Returns the next token from the input stream. */
    String next() {
        while (tokenizer == null || !tokenizer.hasMoreTokens()) {
            try {
                tokenizer = new StringTokenizer(reader.readLine());
            } catch (IOException e) {
                throw new UncheckedIOException(e);
            }
        }
        return tokenizer.nextToken();
    }

    /** Parses the next token as an {@code int}. */
    int nextInt() {
        return Integer.parseInt(next());
    }
}

