import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.StringTokenizer;

/**
 * Reads the input, builds the graph and tries to assign a label
 * (a, b or c) to each vertex while respecting the problem constraints.
 *
 * Constraints:
 *  - Any pair of *non‑adjacent* vertices must receive different symbols
 *    among {a, c}.
 *  - Any pair of *adjacent* vertices must receive the same symbol.
 *
 * If the assignment is impossible the program prints "No", otherwise it
 * prints "Yes" followed by a string of length N containing only
 * characters a, b or c.
 */
public class Main {

    /* ------------------------------------------------------------------ */
    /*                         Constants & Symbols                        */
    /* ------------------------------------------------------------------ */
    private static final String SYM_A = "a";
    private static final String SYM_C = "c";
    private static final String SYM_B = "b";   // default/filling symbol

    /* ------------------------------------------------------------------ */
    /*                               Entry Point                            */
    /* ------------------------------------------------------------------ */
    public static void main(String[] args) throws IOException {
        FastScanner fs = new FastScanner(System.in);

        int n = fs.nextInt();          // number of vertices
        int m = fs.nextInt();          // number of edges

        // adjacency list representation
        @SuppressWarnings("unchecked")
        ArrayList<Integer>[] adj = new ArrayList[n];
        for (int i = 0; i < n; i++) {
            adj[i] = new ArrayList<>();
        }

        // read edges
        for (int i = 0; i < m; i++) {
            int u = fs.nextInt() - 1;
            int v = fs.nextInt() - 1;
            adj[u].add(v);
            adj[v].add(u);
        }

        String[] colors = assignColors(n, adj);
        if (colors == null) {
            System.out.println("No");
        } else {
            System.out.println("Yes");
            for (int i = 0; i < n; i++) {
                if (colors[i] == null) {
                    colors[i] = SYM_B;    // fill remaining positions with 'b'
                }
                System.out.print(colors[i]);
            }
            System.out.println();
        }
    }

    /* ------------------------------------------------------------------ */
    /*                Core algorithm: coloring / validation                */
    /* ------------------------------------------------------------------ */
    /**
     * Attempts to assign a symbolic colour (a or c) to each vertex.
     *
     * @return an array of length N containing "a", "b" or "c",
     *         or {@code null} if the constraints cannot be satisfied.
     */
    private static String[] assignColors(int n, ArrayList<Integer>[] adj) {
        String[] color = new String[n];
        Arrays.fill(color, null);

        /* --------------------------------------------------------------
         * 1) Propagate constraints for every non‑edge.
         *    For a missing edge (u,v) we must have colour[u] != colour[v]
         *    when both symbols belong to {a,c}.  The only valid
         *    unordered pair is {a,c}.
         * -------------------------------------------------------------- */
        for (int u = 0; u < n; u++) {
            for (int v = u + 1; v < n; v++) {
                if (!areAdjacent(u, v, adj)) {
                    // No edge → the two endpoints must differ and be {a,c}
                    if (color[u] == null && color[v] == null) {
                        color[u] = SYM_A;
                        color[v] = SYM_C;
                    } else if (color[u] == null) {
                        color[u] = opposite(color[v]);
                    } else if (color[v] == null) {
                        color[v] = opposite(color[u]);
                    } else if (!compatible(color[u], color[v])) {
                        return null; // conflict detected
                    }
                }
            }
        }

        /* --------------------------------------------------------------
         * 2) Verify that every existing edge connects vertices with the
         *    same colour.  If a mismatch is found the whole assignment is
         *    impossible.
         * -------------------------------------------------------------- */
        for (int u = 0; u < n; u++) {
            for (int v : adj[u]) {
                if (u < v && !color[u].equals(color[v])) {
                    return null;
                }
            }
        }

        return color;
    }

    /** Checks whether vertices u and v share an edge in the adjacency list. */
    private static boolean areAdjacent(int u, int v, ArrayList<Integer>[] adj) {
        for (int w : adj[u]) {
            if (w == v) {
                return true;
            }
        }
        return false;
    }

    /** Returns the opposite symbol of a∈{a,c}.  (a↔c) */
    private static String opposite(String s) {
        return s.equals(SYM_A) ? SYM_C : SYM_A;
    }

    /** Two symbols are compatible when they are different members of {a,c}. */
    private static boolean compatible(String a, String b) {
        return !(a.equals(b) && (a.equals(SYM_A) || a.equals(SYM_C)));
    }
}

/* ----------------------------------------------------------------------
   Helper class: fast tokeniser for reading integers / strings from stdin.
   ---------------------------------------------------------------------- */
class FastScanner {
    private final BufferedReader br;
    private StringTokenizer st;

    FastScanner(InputStream in) {
        br = new BufferedReader(new InputStreamReader(in));
    }

    /** Reads the next integer token. */
    int nextInt() throws IOException {
        return Integer.parseInt(nextToken());
    }

    /** Reads a whole line of tokens (used for custom parsing). */
    String nextToken() throws IOException {
        while (st == null || !st.hasMoreElements()) {
            String line = br.readLine();
            if (line == null) {
                return null;
            }
            st = new StringTokenizer(line);
        }
        return st.nextToken();
    }
}

import java.io.*;
import java.util.*;
import java.util.stream.Collectors;

/**
 * Reads a simple undirected graph, tries to colour each vertex with
 *   – 'b'  : universal vertex (connected to every other vertex)
 *   – 'a'  : part of a special independent set,
 *   – 'c'  : the remaining vertices,
 * and decides whether such a colouring satisfies the problem constraints.
 *
 * The implementation is split into small, purpose‑focused classes so that
 * each piece has a single responsibility.
 */
public class GraphAndString {

    /* --------------------------------------------------------------------- *
     * 1️⃣  Data model                                                          *
     * --------------------------------------------------------------------- */
    /** Represents an undirected graph using an adjacency‑list. */
    private static final class Graph {
        private final int vertexCount;
        private final List<Integer>[] adjacency;   // unmodifiable for callers

        Graph(int vertexCount, List<Integer>[] adjacency) {
            this.vertexCount = vertexCount;
            this.adjacency = adjacency;
        }

        /** Number of vertices in the graph. */
        int vertexCount() { return vertexCount; }

        /** All neighbours of a given vertex. */
        List<Integer> neighbours(int v) { return adjacency[v]; }

        /** True if vertex {@code v} is adjacent to every other vertex. */
        boolean isUniversal(int v) {
            return adjacency[v].size() == vertexCount - 1;
        }

        /** Parses the graph from a {@link Scanner} that reads from {@code System.in}. */
        static Graph fromInput(Scanner scanner) {
            int n = scanner.nextInt();                     // number of vertices
            int m = scanner.nextInt();                     // number of edges
            @SuppressWarnings("unchecked")
            List<Integer>[] adjacency = (List<Integer>[]) new ArrayList[n];
            for (int i = 0; i < n; i++) {
                adjacency[i] = new ArrayList<>();
            }
            for (int i = 0; i < m; i++) {
                int u = scanner.nextInt() - 1;               // input uses 1‑based indices
                int v = scanner.nextInt() - 1;
                addUndirectedEdge(adjacency, u, v);
            }
            return new Graph(n, adjacency);
        }

        private static void addUndirectedEdge(List<Integer>[] adj, int u, int v) {
            adj[u].add(v);
            adj[v].add(u);
        }
    }

    /** The three possible colours in the original problem. */
    private enum VertexColour {
        UNKNOWN('c'),          // default colour before any decision is made
        UNIVERSAL('b'),          // vertex connected to all others
        COMMON('a');             // part of the special independent set

        private final char label;
        VertexColour(char label) { this.label = label; }
        char label() { return label; }
    }

    /** Holds the colour assignment and the validation logic. */
    private static final class Colouring {
        private final char[] labels;   // one of 'a','b','c' for each vertex

        Colouring(int size) { this.labels = new char[size]; }

        /** Assign a colour to a vertex without copying the whole array. */
        void assign(int vertex, VertexColour colour) {
            labels[vertex] = colour.label();
        }

        /** Counts how many vertices carry a given colour. */
        long count(VertexColour colour) {
            return Arrays.stream(labels).filter(c -> c == colour.label()).count();
        }

        /** Convenience shortcut used by the validator. */
        char colourOf(int vertex) { return labels[vertex]; }

        /**
         * Validates the whole colour assignment against the original algorithm.
         * Returns {@code true} if every vertex satisfies the required constraints.
         */
        boolean isValid(Graph graph) {
            final long totalA = count(VertexColour.COMMON);
            final long totalB = count(VertexColour.UNIVERSAL);
            final long totalC = count(VertexColour.UNKNOWN);   // never used, kept for parity

            for (int u = 0; u < graph.vertexCount(); u++) {
                long cntA = 0, cntB = 0, cntC = 0;

                // self‑contribution
                switch (labels[u]) {
                    case 'a' -> cntA++;
                    case 'b' -> cntB++;
                    case 'c' -> cntC++;
                }

                // neighbours' contribution
                for (int v : graph.neighbours(u)) {
                    switch (labels[v]) {
                        case 'a' -> cntA++;
                        case 'b' -> cntB++;
                        case 'c' -> cntC++;
                    }
                }

                // The original program's exact validation rules
                if (labels[u] == 'a') {
                    if (cntC > 0 || cntB != totalB || cntA != totalA) {
                        return false;
                    }
                } else if (labels[u] == 'c') {
                    if (cntA > 0 || cntB != totalB || cntC != totalC) {
                        return false;
                    }
                }
            }
            return true;
        }

        /** Returns the colour string that would be printed when the answer is “Yes”. */
        String asString() { return new String(labels); }
    }

    /* --------------------------------------------------------------------- *
     * 2️⃣  Main orchestration                                                  *
     * --------------------------------------------------------------------- */
    public static void main(String[] args) throws IOException {
        // Try‑with‑resources guarantees that every stream is closed exactly once.
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in))) {
            Scanner scanner = new Scanner(br);
            PrintWriter out = new PrintWriter(System.out, true); // auto‑flush

            // ---- 1. Build the graph -------------------------------------------------
            Graph graph = Graph.fromInput(scanner);
            int n = graph.vertexCount();

            // ---- 2. Initialise colour array -----------------------------------------
            VertexColour[] colourEnum = new VertexColour[n];
            Arrays.fill(colourEnum, VertexColour.UNKNOWN);

            // ---- 3. Mark all universal vertices ------------------------------------
            for (int v = 0; v < n; v++) {
                if (graph.isUniversal(v)) {
                    colourEnum[v] = VertexColour.UNIVERSAL;
                }
            }

            // ---- 4. Pick the first non‑universal vertex and colour its neighbourhood --
            int firstNonUniversal = -1;
            for (int v = 0; v < n; v++) {
                if (colourEnum[v] == VertexColour.UNKNOWN) {
                    firstNonUniversal = v;
                    break;
                }
            }

            // Apply the same logic as the original program:
            //   * the chosen vertex becomes COMMON,
            //   * all of its neighbours that are still UNKNOWN also become COMMON,
            //   * finally any remaining UNKNOWN vertices are also forced to COMMON.
            if (firstNonUniversal != -1) {
                Colouring colouring = new Colouring(n);
                colouring.assign(firstNonUniversal, VertexColour.COMMON);

                for (int nb : graph.neighbours(firstNonUniversal)) {
                    if (colourEnum[nb] == VertexColour.UNKNOWN) {
                        Colouring temp = new Colouring(n);
                        temp.assign(nb, VertexColour.COMMON);
                        // copy the temporary result back into the main label array
                        // (the original code simply overwrote the same array, so we can do it directly)
                        // In practice this step is a no‑op because we will later overwrite all UNKNOWN slots.
                    }
                }

                // All still‑UNKNOWN vertices are marked COMMON as well – matches original behaviour.
                for (int v = 0; v < n; v++) {
                    if (colourEnum[v] == VertexColour.UNKNOWN) {
                        colourEnum[v] = VertexColour.COMMON;
                    }
                }
            }

            // ---- 5. Translate the enum into the character array used for output ----
            Colouring finalColouring = new Colouring(n);
            for (int i = 0; i < n; i++) {
                finalColouring.labels[i] = colourEnum[i].label();
            }

            // ---- 6. Validation -------------------------------------------------------
            boolean valid = finalColouring.isValid(graph);

            out.println(valid ? "Yes" : "No");
            if (valid) {
                out.println(finalColouring.asString());
            }
        }
    }
}

import java.io.*;
import java.util.*;

public class Main {

    // -----------------------------------------------------------------
    // I/O helpers
    // -----------------------------------------------------------------
    private static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner() {
            this.br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                st = new StringTokenizer(br.readLine());
            }
            return st.nextToken();
        }
    }

    private static class PrintWriterExt {
        private final PrintWriter out;
        PrintWriterExt(OutputStream stream) { this.out = new PrintWriter(stream, false); }

        void println(String s) { out.println(s); }
        void print(String s)   { out.print(s); }
        void close()           { out.close(); }
    }

    // -----------------------------------------------------------------
    // Core algorithm
    // -----------------------------------------------------------------
    private static void solve(FastScanner in, PrintWriterExt out) throws IOException {
        final int n = in.nextInt();
        final int q = in.nextInt();

        // ---------- build graph ----------
        boolean[][] adj = new boolean[n][n];
        @SuppressWarnings("unchecked")
        List<Integer>[] neigh = new List[n];
        for (int i = 0; i < n; i++) {
            neigh[i] = new ArrayList<>();
        }

        for (int i = 0; i < q; i++) {
            int u = in.nextInt() - 1;
            int v = in.nextInt() - 1;

            neigh[u].add(v);
            neigh[v].add(u);
            adj[u][v] = adj[v][u] = true;
        }

        // ---------- initial assignment ----------
        char[] result = new char[n];
        Arrays.fill(result, '\0');

        // Vertices adjacent to every other vertex become 'b'
        for (int i = 0; i < n; i++) {
            if (neigh[i].size() == n - 1) {
                result[i] = 'b';
            }
        }

        // ---------- propagate components ----------
        int componentIdx = 0; // 0 -> 'a', 1 -> 'c'
        for (int v = 0; v < n; v++) {
            if (result[v] != '\0') continue;

            // assign a fresh letter to the whole component containing v
            char letter = (componentIdx == 0) ? 'a' : 'c';
            assignLetter(result, adj, neigh, v, letter);
            componentIdx++;

            // more than two components → impossible
            if (componentIdx > 1) {
                break;
            }
        }

        if (componentIdx == 0) {
            // everything already assigned (all 'b')
            out.println("Yes");
            out.print(new String(result));
            out.close();
            return;
        }
        if (componentIdx == 2) {
            // exactly two components were assigned, continue validation
        } else {
            // three or more components → reject
            out.println("No");
            out.close();
            return;
        }

        // ---------- validation ----------
        if (!isValid(result, adj)) {
            out.println("No");
            out.close();
            return;
        }

        // ---------- output ----------
        out.println("Yes");
        out.print(new String(result));
        out.close();
    }

    /** Breadth‑first propagation of a letter through the component that contains `start`. */
    private static void assignLetter(char[] out, boolean[][] adj, List<Integer>[] neigh,
                                     int start, char letter) {
        Deque<Integer> stack = new ArrayDeque<>();
        stack.push(start);
        while (!stack.isEmpty()) {
            int cur = stack.pop();
            if (out[cur] != '\0') continue;          // already processed
            out[cur] = letter;
            for (int nb : neigh[cur]) {
                if (out[nb] == '\0') {
                    stack.push(nb);
                }
            }
        }
    }

    /** Checks the rule: if there is no edge between i and j then their letters must differ by > 1. */
    private static boolean isValid(char[] letters, boolean[][] adj) {
        int len = letters.length;
        for (int i = 0; i < len; i++) {
            for (int j = i + 1; j < len; j++) {
                if (!adj[i][j]) {                     // no edge
                    int diff = Math.abs(letters[i] - letters[j]);
                    if (diff <= 1) {
                        return false;
                    }
                }
            }
        }
        return true;
    }

    // -----------------------------------------------------------------
    // Entry point
    // -----------------------------------------------------------------
    public static void main(String[] args) throws IOException {
        FastScanner scanner = new FastScanner();
        PrintWriterExt printer = new PrintWriterExt(System.out);
        solve(scanner, printer);
    }
}

import java.io.*;
import java.util.StringTokenizer;

/**
 * Refactored solution for the original {@code TaskC}.
 *
 * <p>This program reads an undirected graph, assigns the letters {@code a}, {@code b},
 * {@code c} to its vertices and decides whether such an assignment satisfies the
 * condition that two vertices are adjacent if and only if the ASCII codes of their
 * letters differ by exactly {@code 1}.  If the condition holds, the program prints
 * {@code Yes} followed by the letter assignment; otherwise it prints {@code No}.</p>
 */
public class Main {

    /** Represents the three possible letters used in the solution */
    private static final char LETTER_A = 'a';
    private static final char LETTER_B = 'b';
    private static final char LETTER_C = 'c';

    /** Checks whether the supplied character assignment respects the adjacency rule. */
    private static boolean isAssignmentValid(char[] letters, boolean[][] adj) {
        int n = letters.length;
        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j < n; j++) {
                int diff = Math.abs(letters[i] - letters[j]);

                boolean edgeExists = adj[i][j];
                boolean diffIsTwo = diff == 2;               // 'a' vs 'c' → 97 vs 99
                boolean diffIsOne = diff == 1;               // 'a' vs 'b' or 'b' vs 'c'

                if (edgeExists && !diffIsOne) {
                    return false;
                }
                if (!edgeExists && diffIsTwo) {
                    return false;
                }
            }
        }
        return true;
    }

    /** Encapsulates the logic that solves a single test case. */
    static class Solver {
        /** Solves the problem using the supplied {@link InputReader} and {@link PrintWriter}. */
        void solve(int testNumber, InputReader in, PrintWriter out) {
            int n = in.nextInt();   // number of vertices
            int m = in.nextInt();   // number of edges

            // ---------- Build adjacency matrix & compute degrees ----------
            boolean[][] adjacency = new boolean[n][n];
            int[] degree = new int[n];

            for (int i = 0; i < m; i++) {
                int u = in.nextInt() - 1;
                int v = in.nextInt() - 1;
                adjacency[u][v] = adjacency[v][u] = true;
                degree[u]++;
                degree[v]++;
            }

            // ---------- Assign tentative letters ----------
            char[] letters = new char[n];
            // Vertices of degree (n‑1) must be labelled 'b'
            for (int i = 0; i < n; i++) {
                if (degree[i] == n - 1) {
                    letters[i] = LETTER_B;
                }
            }

            // Find the first vertex that is not yet labelled; it becomes 'a',
            // together with all its neighbours that are still unlabelled.
            for (int i = 0; i < n; i++) {
                if (letters[i] != 0) {
                    continue;
                }
                letters[i] = LETTER_A;
                for (int j = 0; j < n; j++) {
                    if (i == j) {
                        continue;
                    }
                    if (adjacency[i][j] && letters[j] == 0) {
                        letters[j] = LETTER_A;
                    }
                }
                break; // only one such vertex is needed
            }

            // All still unlabelled vertices become 'c'
            for (int i = 0; i < n; i++) {
                if (letters[i] == 0) {
                    letters[i] = LETTER_C;
                }
            }

            // ---------- Validate the assignment ----------
            if (!isAssignmentValid(letters, adjacency)) {
                out.println("No");
                return;
            }

            // ---------- Output ----------
            out.println("Yes");
            for (char c : letters) {
                out.print(c);
            }
            out.println();
        }
    }

    /** Simple input reader that splits lines into tokens. */
    static class InputReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        InputReader(InputStream inputStream) {
            reader = new BufferedReader(new InputStreamReader(inputStream), 32768);
        }

        String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }
    }

    /** Entry point */
    public static void main(String[] args) {
        InputStream inStream = System.in;
        OutputStream outStream = System.out;
        InputReader in = new InputReader(inStream);
        PrintWriter out = new PrintWriter(outStream);
        new Solver().solve(1, in, out);
        out.close();
    }
}

